int GetSingleKeyAloneRemapCount(void* config)
    {
        auto mapping = static_cast<MappingConfiguration*>(config);
        return static_cast<int>(mapping->aloneSingleKeyReMap.size());
    }

bool GetSingleKeyAloneRemap(void* config, int index, SingleKeyMapping* mapping)
    {
        auto mappingConfig = static_cast<MappingConfiguration*>(config);

        std::vector<std::pair<DWORD, KeyShortcutTextUnion>> allMappings;

        for (const auto& kv : mappingConfig->aloneSingleKeyReMap)
        {
            allMappings.push_back(kv);
        }

        if (index < 0 || index >= allMappings.size())
        {
            return false;
        }

        const auto& kv = allMappings[index];
        mapping->originalKey = static_cast<int>(kv.first);

        // Remap to single key
        if (kv.second.index() == 0)
        {
            mapping->targetKey = AllocateAndCopyString(std::to_wstring(std::get<DWORD>(kv.second)));
            mapping->isShortcut = false;
        }
        // Remap to shortcut
        else if (kv.second.index() == 1)
        {
            mapping->targetKey = AllocateAndCopyString(std::get<Shortcut>(kv.second).ToHstringVK().c_str());
            mapping->isShortcut = true;
        }
        else
        {
            mapping->targetKey = AllocateAndCopyString(L"");
            mapping->isShortcut = false;
        }

        return true;
    }

bool AddSingleKeyAloneRemap(void* config, int originalKey, int targetKey)
    {
        auto mappingConfig = static_cast<MappingConfiguration*>(config);
        return mappingConfig->AddSingleKeyAloneRemap(static_cast<DWORD>(originalKey), static_cast<DWORD>(targetKey));
    }

bool AddSingleKeyAloneToShortcutRemap(void* config, int originalKey, const wchar_t* targetKeys)
    {
        auto mappingConfig = static_cast<MappingConfiguration*>(config);

        if (!targetKeys)
        {
            return false;
        }

        Shortcut targetShortcut(targetKeys);

        return mappingConfig->AddSingleKeyAloneRemap(static_cast<DWORD>(originalKey), targetShortcut);
    }

bool DeleteSingleKeyAloneRemap(void* config, int originalKey)
    {
        auto mappingConfig = static_cast<MappingConfiguration*>(config);

        auto it = mappingConfig->aloneSingleKeyReMap.find(static_cast<DWORD>(originalKey));
        if (it != mappingConfig->aloneSingleKeyReMap.end())
        {
            mappingConfig->aloneSingleKeyReMap.erase(it);
            return true;
        }

        return false;
    }

TEST_METHOD (LoadSingleKeyRemaps_ShouldRouteAloneToAloneTable_AndAlwaysToRegularTable)
        {
            MappingConfiguration config;

            // Alone entry: A -> B, tagged condition="alone" (as SaveSettingsToFile writes it)
            json::JsonObject aloneEntry;
            aloneEntry.SetNamedValue(KeyboardManagerConstants::OriginalKeysSettingName, json::value(winrt::to_hstring(static_cast<unsigned int>(0x41))));
            aloneEntry.SetNamedValue(KeyboardManagerConstants::NewRemapKeysSettingName, json::value(winrt::to_hstring(static_cast<unsigned int>(0x42))));
            aloneEntry.SetNamedValue(KeyboardManagerConstants::RemapConditionSettingName, json::value(KeyboardManagerConstants::RemapConditionAlone));

            // Always entry: C -> D, no condition field (legacy shape; loader defaults to "always")
            json::JsonObject alwaysEntry;
            alwaysEntry.SetNamedValue(KeyboardManagerConstants::OriginalKeysSettingName, json::value(winrt::to_hstring(static_cast<unsigned int>(0x43))));
            alwaysEntry.SetNamedValue(KeyboardManagerConstants::NewRemapKeysSettingName, json::value(winrt::to_hstring(static_cast<unsigned int>(0x44))));

            json::JsonArray inProcess;
            inProcess.Append(aloneEntry);
            inProcess.Append(alwaysEntry);

            json::JsonObject remapKeys;
            remapKeys.SetNamedValue(KeyboardManagerConstants::InProcessRemapKeysSettingName, inProcess);

            json::JsonObject root;
            root.SetNamedValue(KeyboardManagerConstants::RemapKeysSettingName, remapKeys);

            config.LoadSingleKeyRemaps(root);

            // Alone entry routed to the alone table (A -> B) and NOT the regular table
            Assert::AreEqual(static_cast<size_t>(1), config.aloneSingleKeyReMap.size());
            Assert::IsTrue(config.aloneSingleKeyReMap.find(0x41) != config.aloneSingleKeyReMap.end());
            Assert::AreEqual(static_cast<DWORD>(0x42), std::get<DWORD>(config.aloneSingleKeyReMap[0x41]));
            Assert::IsTrue(config.singleKeyReMap.find(0x41) == config.singleKeyReMap.end());

            // Always entry routed to the regular table (C -> D) and NOT the alone table
            Assert::AreEqual(static_cast<size_t>(1), config.singleKeyReMap.size());
            Assert::IsTrue(config.singleKeyReMap.find(0x43) != config.singleKeyReMap.end());
            Assert::AreEqual(static_cast<DWORD>(0x44), std::get<DWORD>(config.singleKeyReMap[0x43]));
            Assert::IsTrue(config.aloneSingleKeyReMap.find(0x43) == config.aloneSingleKeyReMap.end());
        }

void AppendAloneSourceKeyEvent(std::vector<INPUT>& keyEventList, DWORD encodedKey, bool keyUp) noexcept
    {
        const DWORD plainKey = Helpers::ClearKeyNumpadOrigin(encodedKey);
        const DWORD flags = keyUp ? KEYEVENTF_KEYUP : 0;
        Helpers::SetKeyEvent(keyEventList, INPUT_KEYBOARD, static_cast<WORD>(plainKey), flags, KeyboardManagerConstants::KEYBOARDMANAGER_SINGLEKEY_FLAG);

        if (Helpers::IsNumpadOriginated(encodedKey))
        {
            // Numpad origin: override SetKeyEvent's VK-based extended default. This is the inverse of
            // EncodeKeyNumpadOrigin -- for the navigation keys a numpad origin means NOT extended, while
            // for VK_RETURN / VK_DIVIDE it means extended.
            INPUT& injected = keyEventList.back();
            if (plainKey == VK_RETURN || plainKey == VK_DIVIDE)
            {
                injected.ki.dwFlags |= KEYEVENTF_EXTENDEDKEY;
            }
            else
            {
                injected.ki.dwFlags &= ~KEYEVENTF_EXTENDEDKEY;
            }
        }
    }

void PromotePendingAloneKeysToCombination(KeyboardManagerInput::InputInterface& ii, State& state, DWORD exceptKey) noexcept
    {
        for (const DWORD pendingKey : state.GetPendingAloneKeys())
        {
            if (pendingKey == exceptKey)
            {
                // Auto-repeat of the alone key itself; keep it a tap candidate.
                continue;
            }

            std::vector<INPUT> keyEventList;
            AppendAloneSourceKeyEvent(keyEventList, pendingKey, /*keyUp*/ false);
            if (!ii.SendVirtualInput(keyEventList))
            {
                // Injection was blocked (e.g. by UIPI). Don't mark this as a started combination,
                // otherwise the eventual key-up would inject an unmatched real key-up while the physical
                // key-down was swallowed. Mirrors the injection-failure handling in HandleSingleKeyRemapEvent.
                continue;
            }

            state.SetAloneCombination(pendingKey);
        }
    }

intptr_t HandleSingleKeyAloneRemapEvent(KeyboardManagerInput::InputInterface& ii, LowlevelKeyboardEvent* data, State& state) noexcept
    {
        // Ignore our own injected events to avoid re-processing / recursion.
        if (GeneratedByKBM(data))
        {
            return 0;
        }

        const DWORD vk = data->lParam->vkCode;
        const bool isKeyUp = (data->wParam == WM_KEYUP || data->wParam == WM_SYSKEYUP);
        const bool isKeyDown = (data->wParam == WM_KEYDOWN || data->wParam == WM_SYSKEYDOWN);

        // Detect, before any state below is mutated, whether another alone-mapped key is already held
        // (pending or already in a combination) as this key goes down. If so, this key is being pressed
        // in combination with that one -- it was NOT tapped alone -- so it must not become a solo-tap
        // candidate that would fire its alone action on release.
        const bool pressedInCombination = isKeyDown && state.HasOtherHeldAloneKey(vk);

        // Step 1: a key-down of a DIFFERENT key while alone keys are pending means those pending keys
        // are now being used in combination. Flush them by injecting their original key-down as a real
        // key/modifier so the in-combination behavior (e.g. Right Ctrl acting as Ctrl) works. (A click
        // or scroll does the same via the mouse hook; see PromotePendingAloneKeysToCombination.)
        if (isKeyDown)
        {
            PromotePendingAloneKeysToCombination(ii, state, vk);
        }

        // Step 2: handle the alone-mapped key's own events.
        const auto aloneRemap = state.GetSingleKeyAloneRemap(vk);
        if (aloneRemap)
        {
            auto it = aloneRemap.value();

            if (isKeyDown)
            {
                // Suppress the physical key-down. Become a tap candidate on the first down; while already
                // in a combination (real key-down injected), just keep suppressing auto-repeats.
                if (!state.IsAloneCombination(vk))
                {
                    if (pressedInCombination)
                    {
                        // Pressed while another alone key was held: treat as a combination, not a tap.
                        // Inject the real key-down now and mark it a combination so its release only
                        // releases the real key and never fires the alone action.
                        std::vector<INPUT> keyEventList;
                        AppendAloneSourceKeyEvent(keyEventList, vk, /*keyUp*/ false);
                        if (!ii.SendVirtualInput(keyEventList))
                        {
                            // Injection was blocked (e.g. by UIPI): let the physical key-down through
                            // instead of suppressing it into a combination we could not start, so it is
                            // not swallowed with no matching injected key. Its later physical key-up then
                            // also passes through (the key is neither pending nor a combination).
                            return 0;
                        }
                        state.SetAloneCombination(vk);
                    }
                    else
                    {
                        state.SetAlonePending(vk);
                    }
                }
                return 1;
            }

            if (isKeyUp)
            {
                if (state.IsAlonePending(vk))
                {
                    // Tapped alone: fire the remapped alone action as a tap (down + up).
                    std::vector<INPUT> keyEventList;
                    const auto& target = it->second;
                    if (target.index() == 0)
                    {
                        const DWORD targetKey = std::get<DWORD>(target);
                        // A disabled alone target means "tapping alone does nothing".
                        if (targetKey != CommonSharedConstants::VK_DISABLED)
                        {
                            // Filter artificial KBM key codes (e.g. VK_WIN_BOTH -> VK_LWIN) before
                            // injecting, mirroring HandleSingleKeyRemapEvent; otherwise a "Win (Both)"
                            // alone target would inject the invalid virtual key 0x104 and do nothing.
                            const DWORD filteredTargetKey = Helpers::FilterArtificialKeys(targetKey);
                            Helpers::SetKeyEvent(keyEventList, INPUT_KEYBOARD, static_cast<WORD>(filteredTargetKey), 0, KeyboardManagerConstants::KEYBOARDMANAGER_SINGLEKEY_FLAG);
                            Helpers::SetKeyEvent(keyEventList, INPUT_KEYBOARD, static_cast<WORD>(filteredTargetKey), KEYEVENTF_KEYUP, KeyboardManagerConstants::KEYBOARDMANAGER_SINGLEKEY_FLAG);
                        }
                    }
                    else if (target.index() == 1)
                    {
                        // Shortcut-valued alone target: a tap fires the whole shortcut as a
                        // press-and-release (modifiers down, action-key down, then released in
                        // reverse). Mirrors the key-to-shortcut injection in HandleSingleKeyRemapEvent.
                        const Shortcut targetShortcut = std::get<Shortcut>(target);
                        // Filter the action key too (e.g. VK_WIN_BOTH -> VK_LWIN), mirroring the
                        // key-to-shortcut path in HandleSingleKeyRemapEvent.
                        const DWORD filteredActionKey = Helpers::FilterArtificialKeys(targetShortcut.GetActionKey());
                        Helpers::SetModifierKeyEvents(targetShortcut, Modifiers(), keyEventList, true, KeyboardManagerConstants::KEYBOARDMANAGER_SINGLEKEY_FLAG);
                        Helpers::SetKeyEvent(keyEventList, INPUT_KEYBOARD, static_cast<WORD>(filteredActionKey), 0, KeyboardManagerConstants::KEYBOARDMANAGER_SINGLEKEY_FLAG);
                        Helpers::SetKeyEvent(keyEventList, INPUT_KEYBOARD, static_cast<WORD>(filteredActionKey), KEYEVENTF_KEYUP, KeyboardManagerConstants::KEYBOARDMANAGER_SINGLEKEY_FLAG);
                        Helpers::SetModifierKeyEvents(targetShortcut, Modifiers(), keyEventList, false, KeyboardManagerConstants::KEYBOARDMANAGER_SINGLEKEY_FLAG);
                    }
                    // NOTE: text-valued alone targets are a later phase (no producer yet).

                    if (!keyEventList.empty())
                    {
                        ii.SendVirtualInput(keyEventList);
                    }

                    state.ClearAloneKeyState(vk);
                    return 1;
                }

                if (state.IsAloneCombination(vk))
                {
                    // Was used in combination: release the real key we injected on its key-down (matching
                    // its numpad origin, so a numpad-originated key is released as the same key we pressed).
                    std::vector<INPUT> keyEventList;
                    AppendAloneSourceKeyEvent(keyEventList, vk, /*keyUp*/ true);
                    ii.SendVirtualInput(keyEventList);

                    state.ClearAloneKeyState(vk);
                    return 1;
                }

                // Not tracked (already resolved): pass the key-up through.
                return 0;
            }
        }

        return 0;
    }

LRESULT CALLBACK KeyboardManager::MouseHookProc(int nCode, const WPARAM wParam, const LPARAM lParam)
{
    if (nCode == HC_ACTION)
    {
        // Only a deliberate button-press or wheel means a held alone key is being used in
        // combination. Mouse MOVE must NOT count, or an incidental move would swallow the tap.
        // Mouse events are never suppressed here — we only promote the held key, then pass through.
        switch (wParam)
        {
        case WM_LBUTTONDOWN:
        case WM_RBUTTONDOWN:
        case WM_MBUTTONDOWN:
        case WM_XBUTTONDOWN:
        case WM_MOUSEWHEEL:
        case WM_MOUSEHWHEEL:
            keyboardManagerObjectPtr->HandleMouseHookEvent();
            break;
        default:
            break;
        }
    }

    return CallNextHookEx(mouseHookHandleCopy, nCode, wParam, lParam);
}

id KeyboardManager::HandleMouseHookEvent() noexcept
{
    if (loadingSettings)
    {
        return;
    }

    // Suspend while the remap key/shortcut editor window is capturing input, mirroring
    // HandleKeyboardHookEvent.
    if (editorIsRunningEvent != nullptr && WaitForSingleObject(editorIsRunningEvent, 0) == WAIT_OBJECT_0)
    {
        return;
    }

    // Common path: no alone key is held, so a click/scroll is none of our business.
    if (!state.HasPendingAloneKeys())
    {
        return;
    }

    // An alone-mapped key is held and the user clicked/scrolled: promote it to a real modifier so
    // the mouse action is seen in combination (e.g. Ctrl+Click, Ctrl+Wheel). The matching real
    // key-up is injected by the keyboard handler when the alone key is released.
    KeyboardEventHandlers::PromotePendingAloneKeysToCombination(inputHandler, state);
}

id KeyboardManager::StartLowlevelMouseHook()
{
#if defined(DISABLE_LOWLEVEL_HOOKS_WHEN_DEBUGGED)
    if (IsDebuggerPresent())
    {
        return;
    }
#endif

    if (!mouseHookHandle)
    {
        mouseHookHandle = SetWindowsHookEx(WH_MOUSE_LL, MouseHookProc, GetModuleHandle(NULL), NULL);
        mouseHookHandleCopy = mouseHookHandle;
        if (!mouseHookHandle)
        {
            DWORD errorCode = GetLastError();
            show_last_error_message(L"SetWindowsHookEx", errorCode, L"PowerToys - Keyboard Manager");
            auto errorMessage = get_last_error_message(errorCode);
            Trace::Error(errorCode, errorMessage.has_value() ? errorMessage.value() : L"", L"StartLowlevelMouseHook::SetWindowsHookEx");
        }
    }
}

id KeyboardManager::StopLowlevelMouseHook()
{
    if (mouseHookHandle)
    {
        UnhookWindowsHookEx(mouseHookHandle);
        mouseHookHandle = nullptr;
    }
    return !(state.appSpecificShortcutReMap.empty() && state.appSpecificShortcutReMapSortedKeys.empty() && state.osLevelShortcutReMap.empty() && state.osLevelShortcutReMapSortedKeys.empty() && state.singleKeyReMap.empty() && state.aloneSingleKeyReMap.empty() && state.singleKeyToTextReMap.empty());
    // Remap a key tapped alone (dual-key). Runs before the regular single-key remap so it can hold
    // the key-down (lazy) and decide tap-vs-combination; if it handles the event, suppress the original.
    intptr_t SingleKeyAloneRemapResult = KeyboardEventHandlers::HandleSingleKeyAloneRemapEvent(inputHandler, data, state);
    if (SingleKeyAloneRemapResult == 1)
    {
        return 1;
    }

std::optional<SingleKeyRemapTable::iterator> State::GetSingleKeyAloneRemap(const DWORD& originalKey)
{
    auto it = aloneSingleKeyReMap.find(originalKey);
    if (it != aloneSingleKeyReMap.end())
    {
        return it;
    }

    return std::nullopt;
}

void State::SetAlonePending(const DWORD key)
{
    aloneCombinationKeys.erase(key);
    alonePendingKeys.insert(key);
}

void State::SetAloneCombination(const DWORD key)
{
    alonePendingKeys.erase(key);
    aloneCombinationKeys.insert(key);
}

void State::ClearAloneKeyState(const DWORD key)
{
    alonePendingKeys.erase(key);
    aloneCombinationKeys.erase(key);
}

void State::ClearAllAloneKeyState()
{
    alonePendingKeys.clear();
    aloneCombinationKeys.clear();
}

bool State::HasOtherHeldAloneKey(const DWORD except) const
{
    for (const DWORD key : alonePendingKeys)
    {
        if (key != except)
        {
            return true;
        }
    }

    for (const DWORD key : aloneCombinationKeys)
    {
        if (key != except)
        {
            return true;
        }
    }

    return false;
}

TEST_CLASS (SingleKeyAloneRemappingTests)
    {
    private:
        KeyboardManagerInput::MockedInput mockedInputHandler;
        State testState;

        // Predicate that counts how many IME On events flow through SendVirtualInput. Installing it
        // also resets the call counter to 0.
        void CountImeOnInjections()
        {
            mockedInputHandler.SetSendVirtualInputTestHandler([](LowlevelKeyboardEvent* data) {
                return data->lParam->vkCode == VK_IME_ON;
            });
        }

    public:
        TEST_METHOD_INITIALIZE(InitializeTestEnv)
        {
            TestHelpers::ResetTestEnv(mockedInputHandler, testState);

            // Bind the alone-remap handler under test as the hook procedure.
            std::function<intptr_t(LowlevelKeyboardEvent*)> currentHookProc = std::bind(&KeyboardEventHandlers::HandleSingleKeyAloneRemapEvent, std::ref(mockedInputHandler), std::placeholders::_1, std::ref(testState));
            mockedInputHandler.SetHookProc(currentHookProc);
        }

void CountImeOnInjections()
        {
            mockedInputHandler.SetSendVirtualInputTestHandler([](LowlevelKeyboardEvent* data) {
                return data->lParam->vkCode == VK_IME_ON;
            });
        }

TEST_METHOD (AloneRemap_ShouldNotInjectOnKeyDown_AndSuppressOriginal)
        {
            // Right Ctrl alone -> IME On
            testState.AddSingleKeyAloneRemap(VK_RCONTROL, (DWORD)VK_IME_ON);
            CountImeOnInjections();

            std::vector<INPUT> rctrlDown{
                { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL } },
            };
            mockedInputHandler.SendVirtualInput(rctrlDown);

            // Nothing injected yet: neither the original Right Ctrl nor the alone action.
            Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));
            Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_IME_ON));
            Assert::AreEqual(0, mockedInputHandler.GetSendVirtualInputCallCount());
        }

TEST_METHOD (AloneRemap_ShouldInjectAloneAction_OnTapWithoutOtherKey)
        {
            testState.AddSingleKeyAloneRemap(VK_RCONTROL, (DWORD)VK_IME_ON);
            CountImeOnInjections();

            std::vector<INPUT> rctrlDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL } } };
            mockedInputHandler.SendVirtualInput(rctrlDown);

            // Still nothing on the way down.
            Assert::AreEqual(0, mockedInputHandler.GetSendVirtualInputCallCount());

            std::vector<INPUT> rctrlUp{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL, .dwFlags = KEYEVENTF_KEYUP } } };
            mockedInputHandler.SendVirtualInput(rctrlUp);

            // On release the alone action fires as a tap: IME On down + up = 2 injected events.
            Assert::AreEqual(2, mockedInputHandler.GetSendVirtualInputCallCount());
            // The original Right Ctrl was never sent as a real modifier.
            Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));
        }

TEST_METHOD (AloneRemap_ShouldPassOriginalKeyThrough_InCombination)
        {
            testState.AddSingleKeyAloneRemap(VK_RCONTROL, (DWORD)VK_IME_ON);
            CountImeOnInjections();

            // Right Ctrl down (held, tap candidate) — not injected yet.
            std::vector<INPUT> rctrlDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL } } };
            mockedInputHandler.SendVirtualInput(rctrlDown);
            Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));

            // H pressed while Right Ctrl held -> combination: Right Ctrl is now injected as a real
            // modifier and H passes through.
            std::vector<INPUT> hDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = 0x48 } } };
            mockedInputHandler.SendVirtualInput(hDown);

            Assert::AreEqual(true, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));
            Assert::AreEqual(true, mockedInputHandler.GetVirtualKeyState(0x48));
            // The alone action must NOT have fired.
            Assert::AreEqual(0, mockedInputHandler.GetSendVirtualInputCallCount());

            // Releasing Right Ctrl releases the real modifier; still no alone action.
            std::vector<INPUT> rctrlUp{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL, .dwFlags = KEYEVENTF_KEYUP } } };
            mockedInputHandler.SendVirtualInput(rctrlUp);

            Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));
            Assert::AreEqual(0, mockedInputHandler.GetSendVirtualInputCallCount());
        }

ST_METHOD (AloneRemap_DisabledAloneTarget_ShouldInjectNothing_OnTap)
        {
            testState.AddSingleKeyAloneRemap(VK_RCONTROL, (DWORD)CommonSharedConstants::VK_DISABLED);

            // Count every event that reaches SendVirtualInput.
            mockedInputHandler.SetSendVirtualInputTestHandler([](LowlevelKeyboardEvent*) { return true; });

            std::vector<INPUT> rctrlDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL } } };
            mockedInputHandler.SendVirtualInput(rctrlDown);
            std::vector<INPUT> rctrlUp{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL, .dwFlags = KEYEVENTF_KEYUP } } };
            mockedInputHandler.SendVirtualInput(rctrlUp);

            // Only the two driving events flowed through; the handler injected nothing extra.
            Assert::AreEqual(2, mockedInputHandler.GetSendVirtualInputCallCount());
            Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));
        }

ST_METHOD (AloneRemap_ShouldTapAgain_AfterPreviousCombinationCycle)
        {
            testState.AddSingleKeyAloneRemap(VK_RCONTROL, (DWORD)VK_IME_ON);

            std::vector<INPUT> rctrlDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL } } };
            std::vector<INPUT> hDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = 0x48 } } };
            std::vector<INPUT> rctrlUp{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL, .dwFlags = KEYEVENTF_KEYUP } } };

            // Cycle 1: combination (Right Ctrl + H) — resolves without firing the alone action.
            mockedInputHandler.SendVirtualInput(rctrlDown);
            mockedInputHandler.SendVirtualInput(hDown);
            mockedInputHandler.SendVirtualInput(rctrlUp);

            // Start counting IME On injections for cycle 2.
            CountImeOnInjections();

            // Cycle 2: solo tap — the alone action fires again (down + up = 2 injected events).
            mockedInputHandler.SendVirtualInput(rctrlDown);
            mockedInputHandler.SendVirtualInput(rctrlUp);
            Assert::AreEqual(2, mockedInputHandler.GetSendVirtualInputCallCount());
        }

ETHOD (AloneRemap_MousePromotion_ShouldPassOriginalKeyThrough_OnClick)
        {
            testState.AddSingleKeyAloneRemap(VK_RCONTROL, (DWORD)VK_IME_ON);
            CountImeOnInjections();

            // Right Ctrl down (held, tap candidate) — nothing injected yet.
            std::vector<INPUT> rctrlDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL } } };
            mockedInputHandler.SendVirtualInput(rctrlDown);
            Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));

            // A mouse button-down/scroll arrives while Right Ctrl is held: the mouse hook promotes the
            // held key to a real modifier (Right Ctrl is now injected as a real Ctrl).
            KeyboardEventHandlers::PromotePendingAloneKeysToCombination(mockedInputHandler, testState);

            Assert::AreEqual(true, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));
            // The alone action must NOT have fired.
            Assert::AreEqual(0, mockedInputHandler.GetSendVirtualInputCallCount());

            // Releasing Right Ctrl releases the real modifier; still no alone action.
            std::vector<INPUT> rctrlUp{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL, .dwFlags = KEYEVENTF_KEYUP } } };
            mockedInputHandler.SendVirtualInput(rctrlUp);

            Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));
            Assert::AreEqual(0, mockedInputHandler.GetSendVirtualInputCallCount());
        }

D (AloneRemap_MousePromotion_NoHeldKey_IsNoOp_AndTapStillFires)
        {
            testState.AddSingleKeyAloneRemap(VK_RCONTROL, (DWORD)VK_IME_ON);

            // Click while nothing is held: promotion has no pending keys, so it injects nothing.
            KeyboardEventHandlers::PromotePendingAloneKeysToCombination(mockedInputHandler, testState);

            CountImeOnInjections();

            // Solo tap afterwards still fires the alone action (down + up = 2 injected events).
            std::vector<INPUT> rctrlDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL } } };
            std::vector<INPUT> rctrlUp{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL, .dwFlags = KEYEVENTF_KEYUP } } };
            mockedInputHandler.SendVirtualInput(rctrlDown);
            mockedInputHandler.SendVirtualInput(rctrlUp);
            Assert::AreEqual(2, mockedInputHandler.GetSendVirtualInputCallCount());
        }

D (AloneRemap_ShortcutTarget_ShouldInjectFullShortcut_OnTap)
        {
            // Right Ctrl alone -> Ctrl+A
            Shortcut aloneTarget;
            aloneTarget.SetKey(VK_CONTROL);
            aloneTarget.SetKey(0x41);
            testState.AddSingleKeyAloneRemap(VK_RCONTROL, aloneTarget);

            // Count injections of the shortcut's action key (A).
            mockedInputHandler.SetSendVirtualInputTestHandler([](LowlevelKeyboardEvent* data) {
                return data->lParam->vkCode == 0x41;
            });

            std::vector<INPUT> rctrlDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL } } };
            mockedInputHandler.SendVirtualInput(rctrlDown);
            // Lazy: nothing injected on the way down.
            Assert::AreEqual(0, mockedInputHandler.GetSendVirtualInputCallCount());

            std::vector<INPUT> rctrlUp{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL, .dwFlags = KEYEVENTF_KEYUP } } };
            mockedInputHandler.SendVirtualInput(rctrlUp);

            // On tap the shortcut's action key is injected as down + up = 2 events (previously the
            // shortcut target was ignored and nothing was injected).
            Assert::AreEqual(2, mockedInputHandler.GetSendVirtualInputCallCount());
            // The original Right Ctrl was never sent as its real self.
            Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));
        }

D (AloneRemap_WinBothTarget_ShouldInjectLeftWin_OnTap)
        {
            testState.AddSingleKeyAloneRemap(VK_RCONTROL, (DWORD)CommonSharedConstants::VK_WIN_BOTH);

            // Count injections of the filtered real key (Left Win). The artificial 0x104 must never appear.
            mockedInputHandler.SetSendVirtualInputTestHandler([](LowlevelKeyboardEvent* data) {
                Assert::AreNotEqual((DWORD)CommonSharedConstants::VK_WIN_BOTH, (DWORD)data->lParam->vkCode);
                return data->lParam->vkCode == VK_LWIN;
            });

            std::vector<INPUT> rctrlDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL } } };
            mockedInputHandler.SendVirtualInput(rctrlDown);
            // Lazy: nothing injected on the way down.
            Assert::AreEqual(0, mockedInputHandler.GetSendVirtualInputCallCount());

            std::vector<INPUT> rctrlUp{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL, .dwFlags = KEYEVENTF_KEYUP } } };
            mockedInputHandler.SendVirtualInput(rctrlUp);

            // On tap, Left Win is injected as down + up = 2 events.
            Assert::AreEqual(2, mockedInputHandler.GetSendVirtualInputCallCount());
        }

D (AloneRemap_SecondAloneKeyWhileFirstHeld_IsCombination_NotTap)
        {
            testState.AddSingleKeyAloneRemap(VK_LCONTROL, (DWORD)VK_IME_OFF);
            testState.AddSingleKeyAloneRemap(VK_RCONTROL, (DWORD)VK_IME_ON);

            // Count either alone (IME) action firing.
            mockedInputHandler.SetSendVirtualInputTestHandler([](LowlevelKeyboardEvent* data) {
                return data->lParam->vkCode == VK_IME_ON || data->lParam->vkCode == VK_IME_OFF;
            });

            // Left Ctrl down (held, tap candidate) — nothing injected yet.
            std::vector<INPUT> lctrlDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_LCONTROL } } };
            mockedInputHandler.SendVirtualInput(lctrlDown);

            // Right Ctrl down while Left Ctrl is held: both are a combination now. Left Ctrl is promoted
            // to a real modifier and Right Ctrl is injected as a real key too; no alone action fires.
            std::vector<INPUT> rctrlDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL } } };
            mockedInputHandler.SendVirtualInput(rctrlDown);
            Assert::AreEqual(true, mockedInputHandler.GetVirtualKeyState(VK_LCONTROL));
            Assert::AreEqual(true, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));

            // Releasing Right Ctrl releases the real key; it must NOT fire IME On (it was not tapped alone).
            std::vector<INPUT> rctrlUp{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL, .dwFlags = KEYEVENTF_KEYUP } } };
            mockedInputHandler.SendVirtualInput(rctrlUp);
            Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));

            // Release Left Ctrl as well.
            std::vector<INPUT> lctrlUp{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_LCONTROL, .dwFlags = KEYEVENTF_KEYUP } } };
            mockedInputHandler.SendVirtualInput(lctrlUp);
            Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_LCONTROL));

            // No alone (IME) action fired at any point.
            Assert::AreEqual(0, mockedInputHandler.GetSendVirtualInputCallCount());
        }

        //

(AloneRemap_PromotionInjectionBlocked_DoesNotStrandCombination)
        {
            testState.AddSingleKeyAloneRemap(VK_RCONTROL, (DWORD)VK_IME_ON);

            // Block only the KBM-injected real Right Ctrl (the promotion), identified by the single-key
            // injection marker, so the test's own driving Right Ctrl events still reach the hook and the
            // alone action (IME On) still succeeds.
            mockedInputHandler.SetSendVirtualInputShouldFail([](const std::vector<INPUT>& inputs) {
                for (const INPUT& i : inputs)
                {
                    if (i.ki.wVk == VK_RCONTROL && i.ki.dwExtraInfo == KeyboardManagerConstants::KEYBOARDMANAGER_SINGLEKEY_FLAG)
                    {
                        return true;
                    }
                }
                return false;
            });

            // Count IME On (the alone action) injections.
            CountImeOnInjections();

            // Right Ctrl down (tap candidate), then H down triggers promotion whose injection is blocked.
            std::vector<INPUT> rctrlDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL } } };
            mockedInputHandler.SendVirtualInput(rctrlDown);
            std::vector<INPUT> hDown{ { .type = INPUT_KEYBOARD, .ki = { .wVk = 0x48 } } };
            mockedInputHandler.SendVirtualInput(hDown);

            // Right Ctrl was never injected as a real modifier (the injection was blocked).
            Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_RCONTROL));

            // Because the blocked promotion left Right Ctrl a tap candidate (not a stranded combination),
            // releasing it fires the alone action (IME On down + up = 2) rather than injecting an unmatched
            // real Right Ctrl key-up.
            std::vector<INPUT> rctrlUp{ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_RCONTROL, .dwFlags = KEYEVENTF_KEYUP } } };
            mockedInputHandler.SendVirtualInput(rctrlUp);
            Assert::AreEqual(2, mockedInputHandler.GetSendVirtualInputCallCount());
        }

        //

(AppendAloneSourceKeyEvent_PreservesNumpadOrigin)
        {
            // NumLock-off numpad navigation key: VK_LEFT arriving NOT extended encodes as numpad-origin.
            const DWORD numpadLeft = Helpers::EncodeKeyNumpadOrigin(VK_LEFT, /*extended*/ false);
            Assert::IsTrue(Helpers::IsNumpadOriginated(numpadLeft), L"numpad-origin bit should be set");

            std::vector<INPUT> numpadEvent;
            KeyboardEventHandlers::AppendAloneSourceKeyEvent(numpadEvent, numpadLeft, /*keyUp*/ false);
            Assert::AreEqual((size_t)1, numpadEvent.size());
            // The real VK is recovered (marker cleared) and the event is NOT extended (numpad, not arrow).
            Assert::AreEqual((WORD)VK_LEFT, numpadEvent[0].ki.wVk);
            Assert::AreEqual((DWORD)0, numpadEvent[0].ki.dwFlags & KEYEVENTF_EXTENDEDKEY);

            // Contrast: the real arrow (extended) VK_LEFT carries no origin marker and IS injected extended.
            const DWORD arrowLeft = Helpers::EncodeKeyNumpadOrigin(VK_LEFT, /*extended*/ true);
            Assert::IsFalse(Helpers::IsNumpadOriginated(arrowLeft), L"arrow key should carry no numpad-origin bit");

            std::vector<INPUT> arrowEvent;
            KeyboardEventHandlers::AppendAloneSourceKeyEvent(arrowEvent, arrowLeft, /*keyUp*/ false);
            Assert::AreEqual((size_t)1, arrowEvent.size());
            Assert::AreEqual((WORD)VK_LEFT, arrowEvent[0].ki.wVk);
            Assert::AreNotEqual((DWORD)0, arrowEvent[0].ki.dwFlags & KEYEVENTF_EXTENDEDKEY);
        }
    };

bool MappingConfiguration::AddSingleKeyAloneRemap(const DWORD& originalKey, const KeyShortcutTextUnion& aloneRemapKey)
{
    // Reject a duplicate source key within the alone table.
    auto it = aloneSingleKeyReMap.find(originalKey);
    if (it != aloneSingleKeyReMap.end())
    {
        return false;
    }

    aloneSingleKeyReMap[originalKey] = aloneRemapKey;
    return true;
}

void StopProcess()
    {
        if (exitEvent)
        {
            if (!SetEvent(exitEvent))
            {
                Logger::error(L"Failed to signal {}. {}", CommonSharedConstants::SHORTCUT_GUIDE_EXIT_EVENT, get_last_error_or_default(GetLastError()));
            }
        }

        if (!m_process)
        {
            return;
        }

        if (!IsProcessActive())
        {
            return;
        }

        constexpr DWORD gracefulShutdownTimeoutMs = 2000;
        constexpr DWORD forcedShutdownTimeoutMs = 5000;
        auto waitResult = WaitForSingleObject(m_process.get(), gracefulShutdownTimeoutMs);
        if (waitResult == WAIT_TIMEOUT)
        {
            Logger::warn("Shortcut Guide did not exit gracefully; terminating it.");
            if (!TerminateProcess(m_process.get(), 0))
            {
                Logger::error(L"Failed to terminate Shortcut Guide. {}", get_last_error_or_default(GetLastError()));
            }
            else if (WaitForSingleObject(m_process.get(), forcedShutdownTimeoutMs) != WAIT_OBJECT_0)
            {
                Logger::error("Shortcut Guide did not terminate within the timeout.");
            }
        }
        else if (waitResult == WAIT_FAILED)
        {
            Logger::error(L"Failed to wait for Shortcut Guide shutdown. {}", get_last_error_or_default(GetLastError()));
        }

        m_process = {};
    }

void FancyZones::AbortMoveSize()
{
    if (m_windowMouseSnapper)
    {
        m_windowMouseSnapper->Abort();
        m_windowMouseSnapper = nullptr;
    }

    m_draggingState.Disable();
}

