                *ppsid = nullptr;
            bSuccess = TRUE;
bool TwoWayPipeMessageIPC::TwoWayPipeMessageIPCImpl::create_pipe_security_attributes(HANDLE token, PipeSecurityAttributes& security_attributes)
    HANDLE process_token = nullptr;
    EXPLICIT_ACCESS entries[3]{};
    bool success = false;
    DWORD administrators_sid_size = 0;
    DWORD local_system_sid_size = 0;
    TOKEN_ELEVATION elevation{};
    DWORD elevation_size = 0;
    PSID server_sid = nullptr;
    TRUSTEE_TYPE server_trustee_type = TRUSTEE_IS_GROUP;
    auto set_entry = [](EXPLICIT_ACCESS& entry, DWORD access, PSID sid, TRUSTEE_TYPE trustee_type) {
        entry.grfAccessPermissions = access;
        entry.grfAccessMode = SET_ACCESS;
        entry.grfInheritance = NO_INHERITANCE;
        entry.Trustee.TrusteeForm = TRUSTEE_IS_SID;
        entry.Trustee.TrusteeType = trustee_type;
        entry.Trustee.ptstrName = static_cast<LPTSTR>(sid);
    };

    if (!token)
    {
        if (!OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &process_token))
        {
            return false;
        }
        token = process_token;
    }
    if (!GetLogonSID(token, &security_attributes.logon_sid))
        goto Cleanup;
    }

void TwoWayPipeMessageIPC::TwoWayPipeMessageIPCImpl::finish_connection_handler(const std::shared_ptr<ConnectionHandler>& handler)
{
    HANDLE pipe_handle = INVALID_HANDLE_VALUE;
        std::scoped_lock lock(connection_handlers_mutex);
        pipe_handle = handler->pipe_handle.get();
        if (pipe_handle != INVALID_HANDLE_VALUE)
        {
            DisconnectNamedPipe(pipe_handle);
        }
        handler->pipe_handle.reset();
    {
        std::scoped_lock lock(connection_handlers_mutex);
        handler->completed = true;
    }
}

bool TwoWayPipeMessageIPC::TwoWayPipeMessageIPCImpl::start_connection_handler(OwnedPipeHandle&& pipe_handle)
{
    auto handler = std::make_shared<ConnectionHandler>(std::move(pipe_handle));
    {
        std::scoped_lock lock(connection_handlers_mutex);
        connection_handlers.emplace_back(handler);
    }
    try
    {
        handler->thread = std::thread(&TwoWayPipeMessageIPCImpl::handle_pipe_connection, this, handler);
        return true;
    }
    catch (...)
    {
        finish_connection_handler(handler);
        reap_finished_connection_handlers();
        return false;
    }
}

void TwoWayPipeMessageIPC::TwoWayPipeMessageIPCImpl::reap_finished_connection_handlers()
{
    std::vector<std::shared_ptr<ConnectionHandler>> completed_handlers;
    {
        std::scoped_lock lock(connection_handlers_mutex);
        for (auto it = connection_handlers.begin(); it != connection_handlers.end();)
        {
            if ((*it)->completed)
            {
                completed_handlers.emplace_back(*it);
                it = connection_handlers.erase(it);
            }
            else
            {
                ++it;
            }
        }
    }

    for (const auto& handler : completed_handlers)
    {
        if (handler->thread.joinable())
        {
            handler->thread.join();
        }
    }
}

void TwoWayPipeMessageIPC::TwoWayPipeMessageIPCImpl::cancel_and_wait_for_connection_handlers()
{
    std::vector<std::shared_ptr<ConnectionHandler>> handlers;
    {
        std::scoped_lock lock(connection_handlers_mutex);
        for (const auto& handler : connection_handlers)
        {
            if (handler->pipe_handle.valid())
            {
                CancelIoEx(handler->pipe_handle.get(), nullptr);
                DisconnectNamedPipe(handler->pipe_handle.get());
            }
        }
        handlers.swap(connection_handlers);
    }

    for (const auto& handler : handlers)
    {
        if (handler->thread.joinable())
        {
            handler->thread.join();
        }
    }
    // The first instance claims exclusive ownership of the name; later instances omit this flag.
    auto create_listener = [&](bool first_instance) {
        DWORD open_mode = PIPE_ACCESS_DUPLEX | WRITE_DAC;
        if (first_instance)
        {
            open_mode |= FILE_FLAG_FIRST_PIPE_INSTANCE;
        }

        PipeSecurityAttributes security_attributes;
        if (!create_pipe_security_attributes(token, security_attributes))
        {
            return INVALID_HANDLE_VALUE;
        }

        return CreateNamedPipe(
            pipe_name,
            open_mode,
            PIPE_TYPE_MESSAGE |
                PIPE_READMODE_MESSAGE |
                PIPE_WAIT |
                PIPE_REJECT_REMOTE_CLIENTS,
            PIPE_UNLIMITED_INSTANCES,
            BUFSIZE,
            BUFSIZE,
            0,
            &security_attributes.attributes);
    };

    OwnedPipeHandle listener{ create_listener(true) };
    if (!listener.valid())
    {
        return;
    }

    while (!closed.load())
            if (closed.load())
                break;
            current_connect_pipe_handle = listener.get();
        const BOOL connected = ConnectNamedPipe(listener.get(), NULL) ? TRUE : (GetLastError() == ERROR_PIPE_CONNECTED);

        if (!connected)
            if (closed.load())
            {
                break;
            }
            DisconnectNamedPipe(listener.get());
            continue;

        OwnedPipeHandle replacement;
        while (!closed.load() && !replacement.valid())
            replacement.reset(create_listener(false));
            if (!replacement.valid() && !closed.load())
            {
                Sleep(10);
            }

        if (closed.load())
        {
            break;
        }

        start_connection_handler(std::move(listener));
        listener = std::move(replacement);
        reap_finished_connection_handlers();
    }

HFONT MakeFont(UINT dpi, bool header)
    {
        NONCLIENTMETRICSW ncm{ sizeof(ncm) };
        SystemParametersInfoW(SPI_GETNONCLIENTMETRICS, sizeof(ncm), &ncm, 0);
        LOGFONTW lf = ncm.lfMessageFont;
        const int pointSize = header ? 14 : 9;
        lf.lfHeight = -MulDiv(pointSize, static_cast<int>(dpi), 72);
        lf.lfWeight = header ? FW_SEMIBOLD : FW_NORMAL;
        return CreateFontIndirectW(&lf);
    }

std::wstring GetDesktopPath()
    {
        PWSTR raw = nullptr;
        std::wstring result;
        if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_Desktop, KF_FLAG_DEFAULT, nullptr, &raw)))
        {
            result = raw;
        }
        if (raw)
        {
            CoTaskMemFree(raw);
        }
        return result;
    }

std::wstring FindNewestReport(const std::wstring& folder)
    {
        namespace fs = std::filesystem;
        if (folder.empty())
        {
            return {};
        }

        std::wstring best;
        fs::file_time_type bestTime{};
        std::error_code ec;
        for (const auto& entry : fs::directory_iterator(folder, ec))
        {
            if (ec)
            {
                break;
            }
            std::error_code itemEc;
            if (!entry.is_regular_file(itemEc))
            {
                continue;
            }
            const auto name = entry.path().filename().wstring();
            if (name.rfind(L"PowerToysReport_", 0) != 0 || entry.path().extension() != L".zip")
            {
                continue;
            }
            const auto writeTime = fs::last_write_time(entry, itemEc);
            if (itemEc)
            {
                continue;
            }
            if (best.empty() || writeTime > bestTime)
            {
                best = entry.path().wstring();
                bestTime = writeTime;
            }
        }
        return best;
    }

void ForceForeground(HWND hwnd)
    {
        const HWND foreground = GetForegroundWindow();
        const DWORD targetThread = GetWindowThreadProcessId(hwnd, nullptr);
        const DWORD foregroundThread = foreground ? GetWindowThreadProcessId(foreground, nullptr) : 0;
        const bool attach = foregroundThread != 0 && foregroundThread != targetThread;
        if (attach)
        {
            AttachThreadInput(foregroundThread, targetThread, TRUE);
        }
        BringWindowToTop(hwnd);
        SetForegroundWindow(hwnd);
        SetActiveWindow(hwnd);
        if (attach)
        {
            AttachThreadInput(foregroundThread, targetThread, FALSE);
        }
    }

void RevealZip(const std::wstring& path)
    {
        if (path.empty())
        {
            return;
        }
        const std::wstring args = L"/select,\"" + path + L"\"";
        ShellExecuteW(nullptr, L"open", L"explorer.exe", args.c_str(), nullptr, SW_SHOWNORMAL);
    }

void OpenIssuePage(const std::wstring& zipPath)
    {
        const std::wstring url =
            L"https://github.com/microsoft/PowerToys/issues/new?template=bug_report.yml&labels=Issue-Bug%2CTriage-Needed&version=" +
            get_product_version();
        ShellExecuteW(nullptr, L"open", url.c_str(), nullptr, nullptr, SW_SHOWNORMAL);

        // Reveal the .zip so the user can drag it into the freshly opened issue page.
        RevealZip(zipPath);
    }

void CreateControls(HWND hwnd, DialogState* st)
    {
        const HINSTANCE inst = reinterpret_cast<HINSTANCE>(&__ImageBase);
        const UINT dpi = st->dpi;

        RECT cr{};
        GetClientRect(hwnd, &cr);
        const int margin = Scale(20, dpi);
        const int contentW = cr.right - 2 * margin;
        int y = margin;

        st->hStatus = CreateWindowExW(0, L"STATIC", L"", WS_CHILD | WS_VISIBLE | SS_LEFT | SS_NOPREFIX, margin, y, contentW, Scale(58, dpi), hwnd, nullptr, inst, nullptr);
        SendMessageW(st->hStatus, WM_SETFONT, reinterpret_cast<WPARAM>(st->hHeaderFont), TRUE);
        y += Scale(64, dpi);

        st->hPath = CreateWindowExW(0, L"EDIT", L"", WS_CHILD | ES_READONLY | ES_AUTOHSCROLL | WS_TABSTOP, margin, y, contentW, Scale(24, dpi), hwnd, nullptr, inst, nullptr);
        SendMessageW(st->hPath, WM_SETFONT, reinterpret_cast<WPARAM>(st->hFont), TRUE);
        ShowCtl(st->hPath, false);
        y += Scale(34, dpi);

        st->hHint = CreateWindowExW(0, L"STATIC", GET_RESOURCE_STRING(IDS_BUGREPORT_GENERATING_HINT).c_str(), WS_CHILD | WS_VISIBLE | SS_LEFT | SS_NOPREFIX, margin, y, contentW, Scale(48, dpi), hwnd, nullptr, inst, nullptr);
        SendMessageW(st->hHint, WM_SETFONT, reinterpret_cast<WPARAM>(st->hFont), TRUE);

        const int btnH = Scale(30, dpi);
        const int btnY = cr.bottom - margin - btnH;
        const int gap = Scale(10, dpi);
        const int wOpen = Scale(110, dpi);
        const int wIssue = Scale(150, dpi);
        const int wClose = Scale(90, dpi);

        st->hOpenFolder = CreateButton(hwnd, ID_BTN_OPEN_FOLDER, GET_RESOURCE_STRING(IDS_BUGREPORT_OPEN_FOLDER), margin, btnY, wOpen, btnH, st->hFont, inst, false);
        st->hCreateIssue = CreateButton(hwnd, ID_BTN_CREATE_ISSUE, GET_RESOURCE_STRING(IDS_BUGREPORT_CREATE_ISSUE), margin + wOpen + gap, btnY, wIssue, btnH, st->hFont, inst, false);
        st->hClose = CreateButton(hwnd, ID_BTN_CLOSE, GET_RESOURCE_STRING(IDS_BUGREPORT_CLOSE), cr.right - margin - wClose, btnY, wClose, btnH, st->hFont, inst, true);
    }

void SetDoneState(DialogState* st)
    {
        st->done = true;
        SetWindowTextW(st->hStatus, GET_RESOURCE_STRING(IDS_BUGREPORT_DONE_HEADER).c_str());
        SetWindowTextW(st->hPath, st->zipPath.c_str());
        SetWindowTextW(st->hHint, GET_RESOURCE_STRING(IDS_BUGREPORT_DONE_HINT).c_str());
        ShowCtl(st->hPath, true);
        ShowCtl(st->hOpenFolder, true);
        ShowCtl(st->hCreateIssue, true);
        SetFocus(st->hCreateIssue);
    }

void SetFailedState(DialogState* st)
    {
        st->done = true;
        SetWindowTextW(st->hStatus, GET_RESOURCE_STRING(IDS_BUGREPORT_FAILED).c_str());
        ShowCtl(st->hPath, false);
        ShowCtl(st->hHint, false);
        ShowCtl(st->hOpenFolder, false);
        ShowCtl(st->hCreateIssue, false);
        SetFocus(st->hClose);
    }

LRESULT CALLBACK DlgProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam)
    {
        DialogState* st = reinterpret_cast<DialogState*>(GetWindowLongPtrW(hwnd, GWLP_USERDATA));
        switch (msg)
        {
        case WM_CREATE:
        {
            auto* cs = reinterpret_cast<CREATESTRUCTW*>(lParam);
            st = static_cast<DialogState*>(cs->lpCreateParams);
            SetWindowLongPtrW(hwnd, GWLP_USERDATA, reinterpret_cast<LONG_PTR>(st));
            CreateControls(hwnd, st);
            SetWindowTextW(st->hStatus, GET_RESOURCE_STRING(IDS_BUGREPORT_GENERATING).c_str());
            SetTimer(hwnd, ANIM_TIMER_ID, 400, nullptr);
            return 0;
        }
        case WM_TIMER:
            if (st && wParam == ANIM_TIMER_ID && !st->done)
            {
                st->animDots = (st->animDots + 1) % 4;
                std::wstring text = GET_RESOURCE_STRING(IDS_BUGREPORT_GENERATING);
                text.append(static_cast<size_t>(st->animDots), L'.');
                SetWindowTextW(st->hStatus, text.c_str());
            }
            return 0;
        case WM_BUGREPORT_DONE:
            if (st)
            {
                KillTimer(hwnd, ANIM_TIMER_ID);
                SetDoneState(st);
            }
            return 0;
        case WM_BUGREPORT_FAILED:
            if (st)
            {
                KillTimer(hwnd, ANIM_TIMER_ID);
                SetFailedState(st);
            }
            return 0;
        case WM_CTLCOLORSTATIC:
            SetBkColor(reinterpret_cast<HDC>(wParam), GetSysColor(COLOR_WINDOW));
            SetTextColor(reinterpret_cast<HDC>(wParam), GetSysColor(COLOR_WINDOWTEXT));
            return reinterpret_cast<LRESULT>(GetSysColorBrush(COLOR_WINDOW));
        case WM_COMMAND:
            if (st)
            {
                switch (LOWORD(wParam))
                {
                case ID_BTN_OPEN_FOLDER:
                    RevealZip(st->zipPath);
                    return 0;
                case ID_BTN_CREATE_ISSUE:
                    OpenIssuePage(st->zipPath);
                    return 0;
                case ID_BTN_CLOSE:
                    DestroyWindow(hwnd);
                    return 0;
                }
            }
            return 0;
        case WM_CLOSE:
            DestroyWindow(hwnd);
            return 0;
        case WM_DESTROY:
            PostQuitMessage(0);
            return 0;
        }
        return DefWindowProcW(hwnd, msg, wParam, lParam);
    }

void RegisterDialogClass()
    {
        static std::once_flag flag;
        std::call_once(flag, []() {
            WNDCLASSEXW wc{ sizeof(wc) };
            wc.lpfnWndProc = DlgProc;
            wc.hInstance = reinterpret_cast<HINSTANCE>(&__ImageBase);
            wc.hCursor = LoadCursorW(nullptr, IDC_ARROW);
            wc.hbrBackground = reinterpret_cast<HBRUSH>(COLOR_WINDOW + 1);
            wc.lpszClassName = kWindowClass;
            wc.hIcon = LoadIconW(reinterpret_cast<HINSTANCE>(&__ImageBase), MAKEINTRESOURCEW(APPICON));
            RegisterClassExW(&wc);
        });
    }

BOOL CALLBACK FindWindowByPidProc(HWND hwnd, LPARAM lParam)
    {
        auto* data = reinterpret_cast<FindWindowByPidData*>(lParam);
        DWORD windowPid = 0;
        GetWindowThreadProcessId(hwnd, &windowPid);
        if (windowPid == data->pid)
        {
            data->hwnd = hwnd;
            return FALSE;
        }
        return TRUE;
    }

void KeyboardListener::UpdateActivationSettings(int32_t activationKey, int32_t inputTime, int32_t holdDuration)
    {
        std::lock_guard<std::mutex> lock(m_mutex_activation_settings);
        m_settings.activationKey = static_cast<PowerAccentActivationKey>(activationKey);
        m_settings.inputTime = std::chrono::milliseconds(inputTime);
        m_settings.holdDuration = std::chrono::milliseconds(holdDuration);
    }

bool AreEqual(const D2D1_RECT_F& left, const D2D1_RECT_F& right)
    {
        return left.left == right.left &&
               left.top == right.top &&
               left.right == right.right &&
               left.bottom == right.bottom;
    }

bool AreEqual(const D2D1_ROUNDED_RECT& left, const D2D1_ROUNDED_RECT& right)
    {
        return AreEqual(left.rect, right.rect) &&
               left.radiusX == right.radiusX &&
               left.radiusY == right.radiusY;
    }

winrt::com_ptr<ID2D1Geometry> FrameDrawer::CreateBorderGeometry(const DrawableRect& drawableRect)
{
    const float halfThickness = drawableRect.thickness / 2.0f;
    winrt::com_ptr<ID2D1Geometry> outerGeometry;
    winrt::com_ptr<ID2D1Geometry> innerGeometry;

    if (drawableRect.roundedRect)
    {
        const auto& borderRect = drawableRect.roundedRect.value();
        const auto outerRect = D2D1::RoundedRect(
            D2D1::RectF(
                borderRect.rect.left - halfThickness,
                borderRect.rect.top - halfThickness,
                borderRect.rect.right + halfThickness,
                borderRect.rect.bottom + halfThickness),
            borderRect.radiusX + halfThickness,
            borderRect.radiusY + halfThickness);
        const auto innerRect = D2D1::RoundedRect(
            D2D1::RectF(
                borderRect.rect.left + halfThickness,
                borderRect.rect.top + halfThickness,
                borderRect.rect.right - halfThickness,
                borderRect.rect.bottom - halfThickness),
            (std::max)(borderRect.radiusX - halfThickness, 0.0f),
            (std::max)(borderRect.radiusY - halfThickness, 0.0f));

        winrt::com_ptr<ID2D1RoundedRectangleGeometry> outerRoundedGeometry;
        if (FAILED(GetD2DFactory()->CreateRoundedRectangleGeometry(outerRect, outerRoundedGeometry.put())))
        {
            return nullptr;
        }

        outerGeometry = outerRoundedGeometry.as<ID2D1Geometry>();

        if (innerRect.rect.left >= innerRect.rect.right || innerRect.rect.top >= innerRect.rect.bottom)
        {
            return outerGeometry;
        }

        winrt::com_ptr<ID2D1RoundedRectangleGeometry> innerRoundedGeometry;
        if (FAILED(GetD2DFactory()->CreateRoundedRectangleGeometry(innerRect, innerRoundedGeometry.put())))
        {
            return nullptr;
        }

        innerGeometry = innerRoundedGeometry.as<ID2D1Geometry>();
    }
    else if (drawableRect.rect)
    {
        const auto& borderRect = drawableRect.rect.value();
        const auto outerRect = D2D1::RectF(
            borderRect.left - halfThickness,
            borderRect.top - halfThickness,
            borderRect.right + halfThickness,
            borderRect.bottom + halfThickness);
        const auto innerRect = D2D1::RectF(
            borderRect.left + halfThickness,
            borderRect.top + halfThickness,
            borderRect.right - halfThickness,
            borderRect.bottom - halfThickness);

        winrt::com_ptr<ID2D1RectangleGeometry> outerRectangleGeometry;
        if (FAILED(GetD2DFactory()->CreateRectangleGeometry(outerRect, outerRectangleGeometry.put())))
        {
            return nullptr;
        }

        outerGeometry = outerRectangleGeometry.as<ID2D1Geometry>();

        if (innerRect.left >= innerRect.right || innerRect.top >= innerRect.bottom)
        {
            return outerGeometry;
        }

        winrt::com_ptr<ID2D1RectangleGeometry> innerRectangleGeometry;
        if (FAILED(GetD2DFactory()->CreateRectangleGeometry(innerRect, innerRectangleGeometry.put())))
        {
            return nullptr;
        }

        innerGeometry = innerRectangleGeometry.as<ID2D1Geometry>();
    }

    if (!outerGeometry || !innerGeometry)
    {
        return nullptr;
    }

    ID2D1Geometry* geometries[] = { outerGeometry.get(), innerGeometry.get() };
    winrt::com_ptr<ID2D1GeometryGroup> borderGeometry;
    if (FAILED(GetD2DFactory()->CreateGeometryGroup(D2D1_FILL_MODE_ALTERNATE, geometries, ARRAYSIZE(geometries), borderGeometry.put())))
    {
        return nullptr;
    }

    return borderGeometry.as<ID2D1Geometry>();
}

TEST_METHOD (integerConstructorShouldProperlyInitializeBuildVersionNumber)
        {
            VersionHelper sut(0, 100, 2607, 8001);

            Assert::AreEqual(0ull, sut.major);
            Assert::AreEqual(100ull, sut.minor);
            Assert::AreEqual(2607ull, sut.revision);
            Assert::AreEqual(8001ull, sut.build);
            Assert::AreEqual(0ull, sut->build);
        }

TEST_METHOD (stringConstructorShouldProperlyInitializationFourPartVersionNumbers)
        {
            auto sut = VersionHelper::fromString("v0.100.2607.08001");
            Assert::IsTrue(sut.has_value());
            Assert::AreEqual(0ull, sut->major);
            Assert::AreEqual(100ull, sut->minor);
            Assert::AreEqual(2607ull, sut->revision);
            Assert::AreEqual(8001ull, sut->build);
        }

