        {
            VersionHelper expected{ 12ull, 13ull, 111ull, 5ull };
            auto actual = VersionHelper::fromString(L"12.13.111.5");

            Assert::IsTrue(actual.has_value());
            Assert::AreEqual(*actual, expected);
