std::wstring CurrentExePath()
        {
            wchar_t buf[MAX_PATH * 2] = {};
            GetModuleFileNameW(nullptr, buf, ARRAYSIZE(buf));
            return buf;
        }

std::wstring DirOf(const std::wstring& p)
        {
            const auto pos = p.find_last_of(L"\\/");
            return pos == std::wstring::npos ? p : p.substr(0, pos);
        }

std::wstring BaseOf(const std::wstring& p)
        {
            const auto pos = p.find_last_of(L"\\/");
            return pos == std::wstring::npos ? p : p.substr(pos + 1);
        }

~ConnectedPipe()
            {
                if (server != INVALID_HANDLE_VALUE)
                {
                    CloseHandle(server);
                }
                if (client != INVALID_HANDLE_VALUE)
                {
                    CloseHandle(client);
                }
            }

bool MakeConnectedPipe(ConnectedPipe& out)
        {
            static LONG counter = 0;
            const std::wstring name = L"\\\\.\\pipe\\pt_auth_test_" +
                                      std::to_wstring(GetCurrentProcessId()) + L"_" +
                                      std::to_wstring(GetTickCount64()) + L"_" +
                                      std::to_wstring(InterlockedIncrement(&counter));
            HANDLE server = CreateNamedPipeW(name.c_str(),
                                             PIPE_ACCESS_DUPLEX,
                                             PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT,
                                             1,
                                             4096,
                                             4096,
                                             0,
                                             nullptr);
            if (server == INVALID_HANDLE_VALUE)
            {
                return false;
            }

            HANDLE client = INVALID_HANDLE_VALUE;
            std::thread connectThread([&]() {
                client = CreateFileW(name.c_str(), GENERIC_READ | GENERIC_WRITE, 0, nullptr, OPEN_EXISTING, 0, nullptr);
            });
            const BOOL connected = ConnectNamedPipe(server, nullptr) ? TRUE : (GetLastError() == ERROR_PIPE_CONNECTED);
            connectThread.join();

            if (!connected || client == INVALID_HANDLE_VALUE)
            {
                CloseHandle(server);
                if (client != INVALID_HANDLE_VALUE)
                {
                    CloseHandle(client);
                }
                return false;
            }
            out.server = server;
            out.client = client;
            return true;
        }

TEST_CLASS(PipeCallerAuthTests)
    {
    public:
        // A disabled policy is a pass-through (preserves the managed start(nullptr) server and tests).
        TEST_METHOD(DisabledPolicy_Accepts)
        {
            interop_auth::CallerPolicy policy;
            interop_auth::VerificationCache cache;
            const auto res = interop_auth::AuthenticateClient(nullptr, policy, cache);
            Assert::IsTrue(res.accepted);
        }

TEST_METHOD(GetModuleVersion_KnownBinary_NonZero)
        {
            wchar_t sys[MAX_PATH] = {};
            GetSystemDirectoryW(sys, ARRAYSIZE(sys));
            const std::wstring kernel = std::wstring(sys) + L"\\kernel32.dll";
            Assert::IsTrue(interop_auth::GetModuleVersion(kernel) != 0ULL);
        }

TEST_METHOD(EnabledPolicy_MatchingCaller_Accepts)
        {
            ConnectedPipe cp;
            Assert::IsTrue(MakeConnectedPipe(cp), L"failed to set up connected pipe");

            const std::wstring exe = CurrentExePath();
            interop_auth::CallerPolicy policy;
            policy.enabled = true;
            policy.expectedDirectory = DirOf(exe);
            policy.allowedBasenames = { BaseOf(exe) };
            policy.expectedVersion = 0; // skip version match
            policy.requireMicrosoftSignature = false; // test host is not Microsoft-signed

            interop_auth::VerificationCache cache;
            const auto res = interop_auth::AuthenticateClient(cp.server, policy, cache);
            Assert::IsTrue(res.accepted, L"legitimate self caller should be accepted");
            Assert::AreEqual(GetCurrentProcessId(), res.pid);
        }

TEST_METHOD(EnabledPolicy_WrongBasename_Rejects)
        {
            ConnectedPipe cp;
            Assert::IsTrue(MakeConnectedPipe(cp), L"failed to set up connected pipe");

            const std::wstring exe = CurrentExePath();
            interop_auth::CallerPolicy policy;
            policy.enabled = true;
            policy.expectedDirectory = DirOf(exe);
            policy.allowedBasenames = { L"definitely_not_the_test_host.exe" };
            policy.requireMicrosoftSignature = false;

            bool logged = false;
            policy.logReject = [&](const interop_auth::AuthResult&) { logged = true; };

            interop_auth::VerificationCache cache;
            const auto res = interop_auth::AuthenticateClient(cp.server, policy, cache);
            Assert::IsFalse(res.accepted, L"caller with non-allowlisted basename must be rejected");
            Assert::AreEqual(L"bad-basename", res.reasonCode);
            Assert::IsTrue(logged, L"rejection must invoke the log callback");
        }

TEST_METHOD(EnabledPolicy_WrongDirectory_Rejects)
        {
            ConnectedPipe cp;
            Assert::IsTrue(MakeConnectedPipe(cp), L"failed to set up connected pipe");

            const std::wstring exe = CurrentExePath();
            interop_auth::CallerPolicy policy;
            policy.enabled = true;
            policy.expectedDirectory = L"C:\\Windows\\System32"; // not where the test host lives
            policy.allowedBasenames = { BaseOf(exe) };
            policy.requireMicrosoftSignature = false;

            interop_auth::VerificationCache cache;
            const auto res = interop_auth::AuthenticateClient(cp.server, policy, cache);
            Assert::IsFalse(res.accepted);
            Assert::AreEqual(L"bad-directory", res.reasonCode);
        }

ST_METHOD(SeparateCaches_AreIndependent)
        {
            const std::wstring exe = CurrentExePath();

            interop_auth::CallerPolicy acceptPolicy;
            acceptPolicy.enabled = true;
            acceptPolicy.expectedDirectory = DirOf(exe);
            acceptPolicy.allowedBasenames = { BaseOf(exe) };
            acceptPolicy.requireMicrosoftSignature = false;

            interop_auth::CallerPolicy rejectPolicy = acceptPolicy;
            rejectPolicy.allowedBasenames = { L"not_the_test_host.exe" };

            interop_auth::VerificationCache cacheA; // e.g. the Settings server's cache
            interop_auth::VerificationCache cacheB; // e.g. the Quick Access server's cache

            ConnectedPipe cp1;
            Assert::IsTrue(MakeConnectedPipe(cp1), L"failed to set up connected pipe 1");
            const auto rA = interop_auth::AuthenticateClient(cp1.server, acceptPolicy, cacheA);
            Assert::IsTrue(rA.accepted, L"self caller accepted under the permissive policy");

            // Same client process (same pid + creation time), different server/cache/policy.
            ConnectedPipe cp2;
            Assert::IsTrue(MakeConnectedPipe(cp2), L"failed to set up connected pipe 2");
            const auto rB = interop_auth::AuthenticateClient(cp2.server, rejectPolicy, cacheB);
            Assert::IsFalse(rB.accepted, L"a separate server cache must not inherit the other's accept verdict");
            Assert::AreEqual(L"bad-basename", rB.reasonCode);
        }

std::wstring ToLower(std::wstring s)
        {
            for (auto& c : s)
            {
                c = static_cast<wchar_t>(towlower(c));
            }
            return s;
        }

std::wstring CanonicalizePath(const std::wstring& path)
        {
            // Backup semantics so this works for both files and directories.
            HANDLE h = CreateFileW(path.c_str(),
                                   0,
                                   FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                                   nullptr,
                                   OPEN_EXISTING,
                                   FILE_FLAG_BACKUP_SEMANTICS,
                                   nullptr);
            if (h == INVALID_HANDLE_VALUE)
            {
                // Fail closed: a path we cannot open/canonicalize must not slip past the
                // directory-prefix check as a non-canonical raw path.
                return {};
            }
            wchar_t buf[1024] = {};
            DWORD len = GetFinalPathNameByHandleW(h, buf, ARRAYSIZE(buf), FILE_NAME_NORMALIZED);
            CloseHandle(h);
            if (len == 0 || len >= ARRAYSIZE(buf))
            {
                return {};
            }
            std::wstring result(buf, len);
            if (result.rfind(L"\\\\?\\", 0) == 0)
            {
                result.erase(0, 4);
            }
            return result;
        }

std::wstring BaseName(const std::wstring& path)
        {
            const auto pos = path.find_last_of(L"\\/");
            return pos == std::wstring::npos ? path : path.substr(pos + 1);
        }

bool PathIsUnderDirectory(const std::wstring& canonicalFile, const std::wstring& directory)
        {
            if (directory.empty() || canonicalFile.empty())
            {
                return false;
            }
            std::wstring dir = ToLower(CanonicalizePath(directory));
            if (dir.empty())
            {
                // CanonicalizePath failed closed; an empty prefix must not match every path.
                return false;
            }
            if (!dir.empty() && dir.back() != L'\\')
            {
                dir.push_back(L'\\');
            }
            const std::wstring file = ToLower(canonicalFile);
            return file.size() > dir.size() && file.compare(0, dir.size(), dir) == 0;
        }

bool BasenameAllowed(const std::wstring& canonicalFile, const std::vector<std::wstring>& allowed)
        {
            const std::wstring base = ToLower(BaseName(canonicalFile));
            for (const auto& a : allowed)
            {
                if (ToLower(a) == base)
                {
                    return true;
                }
            }
            return false;
        }

bool LeafIsMicrosoft(PCCERT_CONTEXT cert)
        {
            if (!cert)
            {
                return false;
            }
            wchar_t name[256] = {};
            const DWORD n = CertGetNameStringW(cert, CERT_NAME_SIMPLE_DISPLAY_TYPE, 0, nullptr, name, ARRAYSIZE(name));
            // Case-insensitive: cert display-name casing can vary and this is a secondary check on top
            // of the machine-root Authenticode chain in ChainsToMachineRoot.
            return n > 1 && wcsstr(ToLower(name).c_str(), L"microsoft corporation") != nullptr;
        }

bool ChainsToMachineRoot(PCCERT_CONTEXT leaf, HCERTSTORE additionalStore)
        {
            if (!leaf)
            {
                return false;
            }

            char codeSigningOid[] = szOID_PKIX_KP_CODE_SIGNING;
            LPSTR oids[] = { codeSigningOid };
            CERT_CHAIN_PARA para = {};
            para.cbSize = sizeof(para);
            para.RequestedUsage.dwType = USAGE_MATCH_TYPE_AND;
            para.RequestedUsage.Usage.cUsageIdentifier = 1;
            para.RequestedUsage.Usage.rgpszUsageIdentifier = oids;

            // Cached-only revocation: never hit the network; treat "unknown/offline" as not-revoked.
            const DWORD flags = CERT_CHAIN_CACHE_ONLY_URL_RETRIEVAL |
                                CERT_CHAIN_REVOCATION_CHECK_CHAIN_EXCLUDE_ROOT;

            PCCERT_CHAIN_CONTEXT chain = nullptr;
            if (!CertGetCertificateChain(HCCE_LOCAL_MACHINE, leaf, nullptr, additionalStore, &para, flags, nullptr, &chain))
            {
                return false;
            }

            bool ok = false;
            const DWORD ignore = CERT_TRUST_REVOCATION_STATUS_UNKNOWN | CERT_TRUST_IS_OFFLINE_REVOCATION;
            if ((chain->TrustStatus.dwErrorStatus & ~ignore) == 0)
            {
                CERT_CHAIN_POLICY_PARA policyPara = {};
                policyPara.cbSize = sizeof(policyPara);
                CERT_CHAIN_POLICY_STATUS policyStatus = {};
                policyStatus.cbSize = sizeof(policyStatus);
                if (CertVerifyCertificateChainPolicy(CERT_CHAIN_POLICY_AUTHENTICODE, chain, &policyPara, &policyStatus))
                {
                    ok = (policyStatus.dwError == 0);
                }
            }

            CertFreeCertificateChain(chain);
            return ok;
        }

ol HasIntactAuthenticodeSignature(const std::wstring& path)
        {
            WINTRUST_FILE_INFO fileInfo = {};
            fileInfo.cbStruct = sizeof(fileInfo);
            fileInfo.pcwszFilePath = path.c_str();

            WINTRUST_DATA wd = {};
            wd.cbStruct = sizeof(wd);
            wd.dwUIChoice = WTD_UI_NONE;
            wd.fdwRevocationChecks = WTD_REVOKE_NONE;
            wd.dwUnionChoice = WTD_CHOICE_FILE;
            wd.pFile = &fileInfo;
            wd.dwStateAction = WTD_STATEACTION_VERIFY;
            wd.dwProvFlags = WTD_SAFER_FLAG | WTD_CACHE_ONLY_URL_RETRIEVAL;

            GUID action = WINTRUST_ACTION_GENERIC_VERIFY_V2;
            HWND noWindow = static_cast<HWND>(INVALID_HANDLE_VALUE);
            const LONG status = WinVerifyTrust(noWindow, &action, &wd);

            wd.dwStateAction = WTD_STATEACTION_CLOSE;
            WinVerifyTrust(noWindow, &action, &wd);

            return status == ERROR_SUCCESS;
        }

ol VerifyMicrosoftSignedMachineRoot(const std::wstring& path)
        {
            // 1) Integrity + valid signature (default store). Rejects unsigned / tampered / stapled.
            if (!HasIntactAuthenticodeSignature(path))
            {
                return false;
            }

            // 2) Re-anchor trust in the machine root store and confirm the signer leaf is Microsoft.
            HCERTSTORE hStore = nullptr;
            HCRYPTMSG hMsg = nullptr;
            if (!CryptQueryObject(CERT_QUERY_OBJECT_FILE,
                                  path.c_str(),
                                  CERT_QUERY_CONTENT_FLAG_PKCS7_SIGNED_EMBED,
                                  CERT_QUERY_FORMAT_FLAG_BINARY,
                                  0,
                                  nullptr,
                                  nullptr,
                                  nullptr,
                                  &hStore,
                                  &hMsg,
                                  nullptr))
            {
                return false;
            }

            bool result = false;
            DWORD signerSize = 0;
            if (CryptMsgGetParam(hMsg, CMSG_SIGNER_INFO_PARAM, 0, nullptr, &signerSize) && signerSize > 0)
            {
                std::vector<BYTE> signerBuf(signerSize);
                if (CryptMsgGetParam(hMsg, CMSG_SIGNER_INFO_PARAM, 0, signerBuf.data(), &signerSize))
                {
                    auto* signer = reinterpret_cast<CMSG_SIGNER_INFO*>(signerBuf.data());
                    CERT_INFO certInfo = {};
                    certInfo.Issuer = signer->Issuer;
                    certInfo.SerialNumber = signer->SerialNumber;
                    PCCERT_CONTEXT leaf = CertGetSubjectCertificateFromStore(
                        hStore, X509_ASN_ENCODING | PKCS_7_ASN_ENCODING, &certInfo);
                    if (leaf)
                    {
                        result = LeafIsMicrosoft(leaf) && ChainsToMachineRoot(leaf, hStore);
                        CertFreeCertificateContext(leaf);
                    }
                }
            }

            if (hMsg)
            {
                CryptMsgClose(hMsg);
            }
            if (hStore)
            {
                CertCloseStore(hStore, 0);
            }
            return result;
        }

signed long long ProcessCreationKey(HANDLE process)
        {
            FILETIME create = {}, exit = {}, kernel = {}, user = {};
            if (!GetProcessTimes(process, &create, &exit, &kernel, &user))
            {
                return 0;
            }
            return (static_cast<unsigned long long>(create.dwHighDateTime) << 32) | create.dwLowDateTime;
        }

signed long long GetModuleVersion(const std::wstring& path)
    {
        if (path.empty())
        {
            return 0;
        }
        // Read the fixed file-version from the PE's RT_VERSION resource using kernel32-only APIs
        // (LoadLibraryEx as a data/resource image), avoiding the version.dll import lib.
        HMODULE mod = LoadLibraryExW(path.c_str(), nullptr, LOAD_LIBRARY_AS_IMAGE_RESOURCE | LOAD_LIBRARY_AS_DATAFILE);
        if (!mod)
        {
            return 0;
        }
        unsigned long long result = 0;
        if (HRSRC res = FindResourceW(mod, MAKEINTRESOURCEW(1 /* VS_VERSION_INFO */), RT_VERSION))
        {
            if (HGLOBAL glob = LoadResource(mod, res))
            {
                const void* locked = LockResource(glob);
                const DWORD size = SizeofResource(mod, res);
                if (locked != nullptr && size >= sizeof(VS_FIXEDFILEINFO))
                {
                    std::vector<BYTE> bytes(size);
                    memcpy(bytes.data(), locked, size);
                    for (size_t i = 0; i + sizeof(VS_FIXEDFILEINFO) <= bytes.size(); i += sizeof(DWORD))
                    {
                        VS_FIXEDFILEINFO ffi{};
                        memcpy(&ffi, &bytes[i], sizeof(ffi));
                        if (ffi.dwSignature == 0xFEEF04BD)
                        {
                            result = (static_cast<unsigned long long>(ffi.dwFileVersionMS) << 32) | ffi.dwFileVersionLS;
                            break;
                        }
                    }
                }
            }
        }
        FreeLibrary(mod);
        return result;
    }

signed long long GetOwnModuleVersion()
    {
        wchar_t self[MAX_PATH * 2] = {};
        const DWORD n = GetModuleFileNameW(nullptr, self, ARRAYSIZE(self));
        if (n == 0 || n >= ARRAYSIZE(self))
        {
            return 0;
        }
        return GetModuleVersion(self);
    }

thResult AuthenticateClient(HANDLE pipe, const CallerPolicy& policy, VerificationCache& cache)
    {
        AuthResult res;
        if (!policy.enabled)
        {
            res.accepted = true;
            return res;
        }

        ULONG pid = 0;
        if (!GetNamedPipeClientProcessId(pipe, &pid))
        {
            res.reasonCode = L"no-client-pid";
            return res;
        }
        res.pid = pid;

        if (policy.expectedClientPid.has_value() && policy.expectedClientPid.value() != pid)
        {
            res.reasonCode = L"pid-mismatch";
            if (policy.logReject)
            {
                policy.logReject(res);
            }
            return res;
        }

        // Hold the process handle for the whole check so the PID cannot be recycled under us.
        HANDLE process = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
        if (!process)
        {
            res.reasonCode = L"open-process-failed";
            if (policy.logReject)
            {
                policy.logReject(res);
            }
            return res;
        }

        const unsigned long long createTime = ProcessCreationKey(process);

        {
            AuthResult cached;
            if (cache.TryGet(pid, createTime, cached))
            {
                cached.pid = pid;
                CloseHandle(process);
                // Do not re-log on a cache hit (dedup across the per-message connections).
                return cached;
            }
        }

        wchar_t imageBuf[MAX_PATH * 2] = {};
        DWORD cch = ARRAYSIZE(imageBuf);
        std::wstring canonical;
        if (QueryFullProcessImageNameW(process, 0, imageBuf, &cch))
        {
            canonical = CanonicalizePath(imageBuf);
        }
        res.imagePath = canonical;

        const wchar_t* reason = L"";
        bool accepted = false;

        if (canonical.empty())
        {
            reason = L"image-path-failed";
        }
        else if (!PathIsUnderDirectory(canonical, policy.expectedDirectory))
        {
            reason = L"bad-directory";
        }
        else if (!BasenameAllowed(canonical, policy.allowedBasenames))
        {
            reason = L"bad-basename";
        }
        else if (policy.expectedVersion != 0 && GetModuleVersion(canonical) != policy.expectedVersion)
        {
            reason = L"version-mismatch";
        }
        else
        {
            bool signatureOk = true;
            if (policy.requireMicrosoftSignature)
            {
#ifdef _DEBUG
                // DEV-ONLY: local builds are not Microsoft-signed. Directory, basename and version are
                // still enforced above. This relaxation is physically compiled out of Release.
                signatureOk = true;
#else
                signatureOk = VerifyMicrosoftSignedMachineRoot(canonical);
#endif
            }
            if (!signatureOk)
            {
                reason = L"not-microsoft-signed";
            }
            else
            {
                accepted = true;
            }
        }

        CloseHandle(process);

        res.accepted = accepted;
        res.reasonCode = reason;

        cache.Put(pid, createTime, res);

        // Required rejection logging (once per process instance, deduped by the cache above).
        if (!accepted && policy.logReject)
        {
            policy.logReject(res);
        }

        return res;
    }
}

void SaveCustomGridLayout(const GUID& uuid, bool showSpacing, int spacing, int sensitivityRadius)
        {
            json::JsonObject root{};
            json::JsonArray layoutsArray{};

            json::JsonObject gridLayoutJson{};
            gridLayoutJson.SetNamedValue(NonLocalizable::CustomLayoutsIds::UuidID, json::value(FancyZonesUtils::GuidToString(uuid).value()));
            gridLayoutJson.SetNamedValue(NonLocalizable::CustomLayoutsIds::NameID, json::value(L"Custom grid layout"));
            gridLayoutJson.SetNamedValue(NonLocalizable::CustomLayoutsIds::TypeID, json::value(NonLocalizable::CustomLayoutsIds::GridID));

            json::JsonArray rowsPercentage{};
            rowsPercentage.Append(json::value(10000));

            json::JsonArray columnsPercentage{};
            columnsPercentage.Append(json::value(5000));
            columnsPercentage.Append(json::value(5000));

            json::JsonArray cells{};
            {
                json::JsonArray cellsRow{};
                cellsRow.Append(json::value(0));
                cellsRow.Append(json::value(1));
                cells.Append(cellsRow);
            }

            json::JsonObject info{};
            info.SetNamedValue(NonLocalizable::CustomLayoutsIds::RowsID, json::value(1));
            info.SetNamedValue(NonLocalizable::CustomLayoutsIds::ColumnsID, json::value(2));
            info.SetNamedValue(NonLocalizable::CustomLayoutsIds::RowsPercentageID, rowsPercentage);
            info.SetNamedValue(NonLocalizable::CustomLayoutsIds::ColumnsPercentageID, columnsPercentage);
            info.SetNamedValue(NonLocalizable::CustomLayoutsIds::CellChildMapID, cells);
            info.SetNamedValue(NonLocalizable::CustomLayoutsIds::ShowSpacingID, json::value(showSpacing));
            info.SetNamedValue(NonLocalizable::CustomLayoutsIds::SpacingID, json::value(spacing));
            info.SetNamedValue(NonLocalizable::CustomLayoutsIds::SensitivityRadiusID, json::value(sensitivityRadius));

            gridLayoutJson.SetNamedValue(NonLocalizable::CustomLayoutsIds::InfoID, info);
            layoutsArray.Append(gridLayoutJson);
            root.SetNamedValue(NonLocalizable::CustomLayoutsIds::CustomLayoutsArrayID, layoutsArray);

            json::to_file(CustomLayouts::CustomLayoutsFileName(), root);
            CustomLayouts::instance().LoadData();
        }

TEST_METHOD (EditedCustomLayoutSpacingRefreshesExistingWorkArea)
        {
            const auto uuid = FancyZonesUtils::GuidFromString(L"{5A9D6A0F-4C6E-4C0C-8B1B-9F3E7C2D1A11}").value();

            auto zoneGap = [](const auto& zones) -> LONG {
                std::vector<RECT> rects;
                for (const auto& [id, zone] : zones)
                {
                    rects.push_back(zone.GetZoneRect());
                }
                std::sort(rects.begin(), rects.end(), [](const RECT& a, const RECT& b) { return a.left < b.left; });
                return rects[1].left - rects[0].right;
            };

            // The layout and its applied snapshot initially have no spacing.
            SaveCustomGridLayout(uuid, /*showSpacing*/ false, /*spacing*/ 0, /*sensitivityRadius*/ 5);
            LayoutData snapshot{
                .uuid = uuid,
                .type = FancyZonesDataTypes::ZoneSetLayoutType::Custom,
                .showSpacing = false,
                .spacing = 0,
                .zoneCount = 2,
                .sensitivityRadius = 5,
            };
            AppliedLayouts::instance().ApplyLayout(m_workAreaId, snapshot);

            auto workArea = WorkArea::Create({}, m_workAreaId, m_emptyUniqueId, m_workAreaRect);
            Assert::IsFalse(workArea == nullptr);
            Assert::IsNotNull(workArea->GetLayout().get());
            Assert::AreEqual(static_cast<size_t>(2), workArea->GetLayout()->Zones().size());
            Assert::AreEqual(0L, zoneGap(workArea->GetLayout()->Zones()), L"Zones should be adjacent before the edit");

            // User edits the layout to add spacing; only custom-layouts.json is rewritten, the
            // applied-layouts snapshot stays stale.
            SaveCustomGridLayout(uuid, /*showSpacing*/ true, /*spacing*/ 100, /*sensitivityRadius*/ 30);

            // The custom-layouts file-update handler refreshes active work areas via InitLayout.
            workArea->InitLayout();

            Assert::AreEqual(static_cast<size_t>(2), workArea->GetLayout()->Zones().size());
            Assert::IsTrue(zoneGap(workArea->GetLayout()->Zones()) > 20, L"Edited spacing was not applied to the existing work area");
        }

inline bool IsLightTheme()
    {
        DWORD value = 0;
        DWORD size = sizeof(value);
        HKEY key = nullptr;
        if (RegOpenKeyExW(HKEY_CURRENT_USER,
                          L"Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize",
                          0, KEY_READ, &key) == ERROR_SUCCESS)
        {
            DWORD type = 0;
            if (RegQueryValueExW(key, L"AppsUseLightTheme", nullptr, &type,
                                 reinterpret_cast<LPBYTE>(&value), &size) != ERROR_SUCCESS ||
                type != REG_DWORD)
            {
                value = 0;
            }
            RegCloseKey(key);
        }
        return value != 0;
    }

inline Gdiplus::Color Card(bool light)
    {
        return light ? Gdiplus::Color(179, 255, 255, 255)  // #B3FFFFFF
                     : Gdiplus::Color(210, 18, 18, 18);     // dark, mostly-opaque tile
    }

constexpr COLORREF CardRef(bool light)
    {
        // Opaque approximation of the card-over-acrylic color, available for any
        // surface that needs a solid blend background.
        return light ? RGB(248, 248, 248) : RGB(20, 20, 20);
    }

inline Gdiplus::Color CardStroke(bool light)
    {
        return light ? Gdiplus::Color(15, 0, 0, 0)
                     : Gdiplus::Color(25, 0, 0, 0);
    }

inline Gdiplus::Color SurfaceStrokeDefault(bool light)
    {
        return light ? Gdiplus::Color(24, 0, 0, 0)
                     : Gdiplus::Color(64, 255, 255, 255);
    }

inline Gdiplus::Color PreviewStroke(bool light)
    {
        return light ? Gdiplus::Color(28, 0, 0, 0)
                     : Gdiplus::Color(60, 255, 255, 255);
    }

inline Gdiplus::Color FocusShadow(bool light)
    {
        // Contrast hairline just inside the accent ring: white in light mode,
        // black in dark mode.
        return light ? Gdiplus::Color(120, 255, 255, 255)
                     : Gdiplus::Color(150, 0, 0, 0);
    }

static bool SupportsSystemBackdrop()
{
    using RtlGetVersionPtr = LONG(WINAPI*)(PRTL_OSVERSIONINFOW);
    static const DWORD build = []() -> DWORD {
        if (HMODULE nt = GetModuleHandleW(L"ntdll.dll"))
        {
            auto fn = reinterpret_cast<RtlGetVersionPtr>(GetProcAddress(nt, "RtlGetVersion"));
            RTL_OSVERSIONINFOW vi{};
            vi.dwOSVersionInfoSize = sizeof(vi);
            if (fn && fn(&vi) == 0)
                return vi.dwBuildNumber;
        }
        return 0;
    }();
    return build >= 22621;
}

static LRESULT CALLBACK ThumbHostProc(HWND h, UINT msg, WPARAM w, LPARAM l)
{
    if (msg == WM_ERASEBKGND)
    {
        if (g_thumbSolidMode && g_thumbSolidBrush)
        {
            RECT rc{};
            GetClientRect(h, &rc);
            FillRect(reinterpret_cast<HDC>(w), &rc, g_thumbSolidBrush);
        }
        return 1;
    }
    return DefWindowProcW(h, msg, w, l);
}

static void ApplyBackdrop(HWND hwnd, bool light)
{
    if (SupportsSystemBackdrop())
    {
        g_thumbSolidMode = false;
        MARGINS glass{ -1, -1, -1, -1 };
        DwmExtendFrameIntoClientArea(hwnd, &glass);
        int backdrop = DWMSBT_TRANSIENTWINDOW;
        DwmSetWindowAttribute(hwnd, DWMWA_SYSTEMBACKDROP_TYPE, &backdrop, sizeof(backdrop));
    }
    else
    {
        g_thumbSolidMode = true;
        if (g_thumbSolidBrush)
            DeleteObject(g_thumbSolidBrush);
        g_thumbSolidBrush = CreateSolidBrush(AltTabStyle::BackdropSolidRef(light));
    }
}

static std::wstring ProcessImagePath(HWND hwnd)
{
    DWORD pid = 0;
    GetWindowThreadProcessId(hwnd, &pid);
    if (!pid)
        return std::wstring();

    HANDLE proc = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
    if (!proc)
        return std::wstring();

    wchar_t buf[MAX_PATH * 2];
    DWORD len = static_cast<DWORD>(sizeof(buf) / sizeof(buf[0]));
    std::wstring result;
    if (QueryFullProcessImageNameW(proc, 0, buf, &len))
        result.assign(buf, len);
    CloseHandle(proc);
    return result;
}

static bool IsApplicationFrameHost(const std::wstring& path)
{
    size_t slash = path.find_last_of(L"\\/");
    const wchar_t* name = path.c_str() + (slash == std::wstring::npos ? 0 : slash + 1);
    return _wcsicmp(name, L"ApplicationFrameHost.exe") == 0;
}

static BOOL CALLBACK FindCoreWindowProc(HWND child, LPARAM lp)
{
    CoreWindowFind* cf = reinterpret_cast<CoreWindowFind*>(lp);
    wchar_t cls[64];
    if (GetClassNameW(child, cls, ARRAYSIZE(cls)) &&
        wcscmp(cls, L"Windows.UI.Core.CoreWindow") == 0)
    {
        DWORD pid = 0;
        GetWindowThreadProcessId(child, &pid);
        if (pid && pid != cf->hostPid)
        {
            cf->found = child;
            return FALSE; // stop enumerating
        }
    }
    return TRUE;
}

static std::wstring RealProcessImagePath(HWND hwnd)
{
    std::wstring path = ProcessImagePath(hwnd);
    if (!IsApplicationFrameHost(path))
        return path;

    DWORD hostPid = 0;
    GetWindowThreadProcessId(hwnd, &hostPid);

    CoreWindowFind cf;
    cf.hostPid = hostPid;
    EnumChildWindows(hwnd, FindCoreWindowProc, reinterpret_cast<LPARAM>(&cf));
    if (cf.found)
    {
        std::wstring real = ProcessImagePath(cf.found);
        if (!real.empty())
            return real;
    }
    return path;
}

static AltWindowCycleLogic::WindowEligibility QueryWindowEligibility(HWND hwnd)
{
    AltWindowCycleLogic::WindowEligibility eligibility;

    eligibility.isVisible = IsWindowVisible(hwnd) != FALSE;
    if (!eligibility.isVisible)
        return eligibility;

    int cloaked = 0;
    eligibility.isCloaked = SUCCEEDED(DwmGetWindowAttribute(hwnd, DWMWA_CLOAKED, &cloaked, sizeof(cloaked))) && cloaked;
    if (eligibility.isCloaked)
        return eligibility;

    HWND walk = GetAncestor(hwnd, GA_ROOTOWNER);
    HWND tryPopup = nullptr;
    for (;;)
    {
        tryPopup = GetLastActivePopup(walk);
        if (tryPopup == walk)
            break;
        if (IsWindowVisible(tryPopup))
            break;
        walk = tryPopup;
    }
    eligibility.isAltTabRepresentative = (walk == hwnd);
    if (!eligibility.isAltTabRepresentative)
        return eligibility;

    LONG_PTR exStyle = GetWindowLongPtrW(hwnd, GWL_EXSTYLE);
    eligibility.isToolWindow = (exStyle & WS_EX_TOOLWINDOW) != 0;
    eligibility.isAppWindow = (exStyle & WS_EX_APPWINDOW) != 0;
    return eligibility;
}

static BOOL CALLBACK EnumProc(HWND hwnd, LPARAM lp)
{
    EnumCtx* ctx = reinterpret_cast<EnumCtx*>(lp);

    AltWindowCycleLogic::CandidateWindow candidate;
    candidate.id = reinterpret_cast<uintptr_t>(hwnd);
    candidate.eligibility = QueryWindowEligibility(hwnd);

    // Resolve the owning process only for eligible windows, matching the original
    // short-circuit (avoids an OpenProcess for windows that are dropped anyway).
    if (AltWindowCycleLogic::IsAltTabEligible(candidate.eligibility))
        candidate.processKey = RealProcessImagePath(hwnd);

    ctx->candidates.push_back(std::move(candidate));
    return TRUE;
}

static bool GetAppWindows(HWND& foreground, std::vector<HWND>& windows)
{
    windows.clear();
    foreground = GetForegroundWindow();
    if (!foreground)
        return false;

    const std::wstring foregroundKey = RealProcessImagePath(foreground);
    if (foregroundKey.empty())
        return false;

    EnumCtx ctx;
    EnumWindows(EnumProc, reinterpret_cast<LPARAM>(&ctx));

    const std::vector<unsigned long long> selected =
        AltWindowCycleLogic::SelectCycleWindows(foregroundKey, ctx.candidates);

    windows.reserve(selected.size());
    for (const unsigned long long id : selected)
        windows.push_back(reinterpret_cast<HWND>(static_cast<uintptr_t>(id)));

    return !windows.empty();
}

static void ForceForeground(HWND hwnd)
{
    if (IsIconic(hwnd))
        ShowWindow(hwnd, SW_RESTORE);

    DWORD fgThread = GetWindowThreadProcessId(GetForegroundWindow(), nullptr);
    DWORD myThread = GetCurrentThreadId();

    if (fgThread && fgThread != myThread)
        AttachThreadInput(myThread, fgThread, TRUE);

    BringWindowToTop(hwnd);
    SetForegroundWindow(hwnd);
    SetFocus(hwnd);

    if (fgThread && fgThread != myThread)
        AttachThreadInput(myThread, fgThread, FALSE);
}

static LRESULT CALLBACK EscapeHookProc(int code, WPARAM wParam, LPARAM lParam)
{
    if (code == HC_ACTION && (wParam == WM_KEYDOWN || wParam == WM_SYSKEYDOWN))
    {
        const auto* keyInfo = reinterpret_cast<const KBDLLHOOKSTRUCT*>(lParam);

        // Keep this callback bounded: teardown runs on the UI thread's own message
        // loop rather than inline, so the OS low-level hook timeout is never at risk.
        if (keyInfo && keyInfo->vkCode == VK_ESCAPE && g_uiThreadId &&
            PostThreadMessageW(g_uiThreadId, WM_AWC_CANCEL, 0, 0))
        {
            return 1;
        }
    }

    return CallNextHookEx(nullptr, code, wParam, lParam);
}

bool Switcher::Init(HINSTANCE instance)
{
    hinst = instance;

    WNDCLASSW hc = {};
    hc.style = CS_HREDRAW | CS_VREDRAW;
    hc.lpfnWndProc = &ThumbHostProc;
    hc.hInstance = hinst;
    hc.hCursor = LoadCursorW(nullptr, IDC_ARROW);
    hc.hbrBackground = nullptr;
    hc.lpszClassName = L"AltWindowCycleThumbHost";
    RegisterClassW(&hc);

    thumbHost = CreateWindowExW(
        WS_EX_TOPMOST | WS_EX_TOOLWINDOW | WS_EX_NOACTIVATE,
        hc.lpszClassName, L"", WS_POPUP | WS_DISABLED,
        0, 0, 0, 0, nullptr, nullptr, hinst, nullptr);
    if (!thumbHost)
        return false;

    WNDCLASSW wc = {};
    wc.style = CS_HREDRAW | CS_VREDRAW;
    wc.lpfnWndProc = &Switcher::WndProc;
    wc.hInstance = hinst;
    wc.hCursor = LoadCursorW(nullptr, IDC_ARROW);
    wc.hbrBackground = nullptr;
    wc.lpszClassName = L"AltWindowCycleOverlay";
    RegisterClassW(&wc);

    overlay = CreateWindowExW(
        WS_EX_TOPMOST | WS_EX_TOOLWINDOW | WS_EX_NOACTIVATE | WS_EX_LAYERED,
        wc.lpszClassName, L"", WS_POPUP,
        0, 0, 0, 0, nullptr, nullptr, hinst, nullptr);
    if (!overlay)
        return false;

    SetWindowLongPtrW(overlay, GWLP_USERDATA, reinterpret_cast<LONG_PTR>(this));
    return true;
}

void Switcher::Shutdown()
{
    RemoveEscapeHook();
    UnregisterThumbnails();
    if (thumbHost)
    {
        DestroyWindow(thumbHost);
        thumbHost = nullptr;
    }
    if (font)
    {
        DeleteObject(font);
        font = nullptr;
    }
    if (overlay)
    {
        KillTimer(overlay, TIMER_ID);
        DestroyWindow(overlay);
        overlay = nullptr;
    }
    UnregisterClassW(L"AltWindowCycleOverlay", hinst);
    UnregisterClassW(L"AltWindowCycleThumbHost", hinst);
    if (g_thumbSolidBrush)
    {
        DeleteObject(g_thumbSolidBrush);
        g_thumbSolidBrush = nullptr;
    }
    state = St::Idle;
}

static unsigned int CurrentModifiersDown()
{
    unsigned int modifiers = 0;
    const auto isDown = [](int vk) {
        return (GetAsyncKeyState(vk) & 0x8000) != 0;
    };

    if (isDown(VK_MENU))
    {
        modifiers |= AltWindowCycleLogic::ModifierAlt;
    }
    if (isDown(VK_CONTROL))
    {
        modifiers |= AltWindowCycleLogic::ModifierCtrl;
    }
    if (isDown(VK_SHIFT))
    {
        modifiers |= AltWindowCycleLogic::ModifierShift;
    }
    if (isDown(VK_LWIN) || isDown(VK_RWIN))
    {
        modifiers |= AltWindowCycleLogic::ModifierWin;
    }

    return modifiers;
}

void Switcher::OnHotkey(bool forward, unsigned int holdModifiers)
{
    if (state == St::Idle)
    {
        HWND fg;
        if (!GetAppWindows(fg, windows) || windows.size() < 2)
            return;

        int idx = -1;
        for (size_t i = 0; i < windows.size(); ++i)
            if (windows[i] == fg) { idx = static_cast<int>(i); break; }
        if (idx < 0)
            idx = 0;

        anchorWindow = fg;
        activeHoldModifiers = AltWindowCycleLogic::StableHoldModifiers(holdModifiers);
        const auto firstHotkey = AltWindowCycleLogic::BeginCycle(idx, static_cast<int>(windows.size()), forward);
        if (firstHotkey.action != AltWindowCycleLogic::FirstHotkeyAction::ShowOverlay)
            return;

        selected = firstHotkey.selected;
        ShowOverlayWindow();
        state = St::Visible;
        SetTimer(overlay, TIMER_ID, TIMER_MS, nullptr);
    }
    else
    {
        selected = AltWindowCycleLogic::WrapIndex(forward ? selected + 1 : selected - 1, static_cast<int>(windows.size()));
        SetSelection(selected);
    }
}

void Switcher::OnTick()
{
    if (!AltWindowCycleLogic::AreRequiredModifiersDown(activeHoldModifiers, CurrentModifiersDown()))
    {
        Commit();
        return;
    }
}

void Switcher::OnCancel()
{
    if (state == St::Visible)
    {
        Cancel();
    }
}

void Switcher::Commit()
{
    KillTimer(overlay, TIMER_ID);
    if (state == St::Visible)
        HideOverlayWindow();
    anchorWindow = nullptr;

    if (selected >= 0 && selected < static_cast<int>(windows.size()))
    {
        HWND target = windows[selected];
        if (IsWindow(target))
            ForceForeground(target);
    }
    state = St::Idle;
}

void Switcher::Cancel()
{
    KillTimer(overlay, TIMER_ID);
    if (state == St::Visible)
        HideOverlayWindow();
    anchorWindow = nullptr;
    state = St::Idle;
}

static UINT GetMonitorEffectiveDpi(HMONITOR mon)
{
    UINT dpiX = 96, dpiY = 96;
    if (mon && SUCCEEDED(GetDpiForMonitor(mon, MDT_EFFECTIVE_DPI, &dpiX, &dpiY)) && dpiX)
        return dpiX;
    return 96;
}

static RECT GetWorkArea(HMONITOR mon)
{
    MONITORINFO mi = {};
    mi.cbSize = sizeof(mi);
    if (mon && GetMonitorInfoW(mon, &mi))
        return mi.rcWork;
    RECT fallback = { 0, 0, 1920, 1080 };
    return fallback;
}

static UINT GetDpiForHostOnMonitor(HWND host, HMONITOR mon, const RECT& work)
{
    if (host && mon)
    {
        SetWindowPos(host, nullptr, work.left, work.top, 1, 1,
                     SWP_NOZORDER | SWP_NOACTIVATE | SWP_NOOWNERZORDER | SWP_HIDEWINDOW);
        UINT dpi = GetDpiForWindow(host);
        if (dpi)
            return dpi;
    }
    return GetMonitorEffectiveDpi(mon);
}

static HICON GetWindowIcon(HWND hwnd)
{
    DWORD_PTR res = 0;
    HICON icon = nullptr;
    if (SendMessageTimeoutW(hwnd, WM_GETICON, ICON_SMALL2, 0, SMTO_ABORTIFHUNG, 100, &res) && res)
        icon = reinterpret_cast<HICON>(res);
    if (!icon && SendMessageTimeoutW(hwnd, WM_GETICON, ICON_BIG, 0, SMTO_ABORTIFHUNG, 100, &res) && res)
        icon = reinterpret_cast<HICON>(res);
    if (!icon)
        icon = reinterpret_cast<HICON>(GetClassLongPtrW(hwnd, GCLP_HICONSM));
    if (!icon)
        icon = reinterpret_cast<HICON>(GetClassLongPtrW(hwnd, GCLP_HICON));
    return icon;
}

void Switcher::ShowOverlayWindow()
{
    if (windows.empty())
        return;

    int anchorIdx = selected;
    if (anchorIdx < 0) anchorIdx = 0;
    if (anchorIdx >= static_cast<int>(windows.size())) anchorIdx = 0;
    HWND anchor = IsWindow(anchorWindow) ? anchorWindow : windows[anchorIdx];

    HMONITOR mon = GetAnchorMonitor(anchor);
    RECT work = GetWorkArea(mon);
    UINT dpi = GetDpiForHostOnMonitor(thumbHost, mon, work);
    scale = dpi / 96.0;

    int x, y, panelW, panelH;
    ComputeLayout(work, x, y, panelW, panelH);

    EnsureFont();

    icons.clear();
    titles.clear();
    for (HWND w : windows)
    {
        icons.push_back(GetWindowIcon(w));
        titles.push_back(GetTitle(w));
    }

    ovX = x; ovY = y; ovW = panelW; ovH = panelH;

    SetWindowPos(thumbHost, HWND_TOPMOST, x, y, panelW, panelH,
                 SWP_NOACTIVATE | SWP_NOOWNERZORDER);
    ApplyBackdrop(thumbHost, AltTabStyle::IsLightTheme());
    DWORD cornerPref = DWMWCP_ROUND;
    DwmSetWindowAttribute(thumbHost, DWMWA_WINDOW_CORNER_PREFERENCE,
                          &cornerPref, sizeof(cornerPref));
    HRGN rgn = CreateRoundRectRgn(0, 0, panelW + 1, panelH + 1,
                                  2 * Scaled(8), 2 * Scaled(8));
    if (rgn != nullptr)
    {
        // SetWindowRgn takes ownership of the region on success; on failure the
        // caller still owns it, so delete it to avoid leaking the HRGN.
        if (SetWindowRgn(thumbHost, rgn, FALSE) == 0)
        {
            DeleteObject(rgn);
        }
    }
    RedrawWindow(thumbHost, nullptr, nullptr,
                 RDW_INVALIDATE | RDW_ERASE | RDW_UPDATENOW | RDW_ALLCHILDREN);
    RegisterThumbnails();

    // Update the hidden layered bitmap before showing it. Otherwise, monitor/DPI
    // switches can flash the previous-size overlay for one frame.
    RenderLayered();
    SetWindowPos(thumbHost, HWND_TOPMOST, x, y, panelW, panelH,
                 SWP_NOACTIVATE | SWP_SHOWWINDOW);
    SetWindowPos(overlay, HWND_TOPMOST, x, y, panelW, panelH,
                 SWP_NOACTIVATE | SWP_SHOWWINDOW);
    SetWindowPos(thumbHost, overlay, 0, 0, 0, 0,
                 SWP_NOACTIVATE | SWP_NOMOVE | SWP_NOSIZE);
    InstallEscapeHook();
}

void Switcher::HideOverlayWindow()
{
    RemoveEscapeHook();
    ShowWindow(overlay, SW_HIDE);
    ShowWindow(thumbHost, SW_HIDE);
    UnregisterThumbnails();
    icons.clear();
    titles.clear();
}

void Switcher::InstallEscapeHook()
{
    if (!g_escapeHook)
    {
        g_escapeHook = SetWindowsHookExW(WH_KEYBOARD_LL, EscapeHookProc, nullptr, 0);
    }
}

void Switcher::RemoveEscapeHook()
{
    if (g_escapeHook)
    {
        UnhookWindowsHookEx(g_escapeHook);
        g_escapeHook = nullptr;
    }
}

void Switcher::SetSelection(int index)
{
    selected = index;
    const int nextPageStart = AltWindowCycleLogic::PageStartForSelection(
        selected,
        static_cast<int>(windows.size()),
        overlayLayout.pageSize);
    if (nextPageStart != pageStart)
    {
        pageStart = nextPageStart;
        RegisterThumbnails();
    }
    RenderLayered();
}

void Switcher::OnThemeChanged()
{
    if (state != St::Visible)
        return;
    ApplyBackdrop(thumbHost, AltTabStyle::IsLightTheme());
    RedrawWindow(thumbHost, nullptr, nullptr,
                 RDW_INVALIDATE | RDW_ERASE | RDW_UPDATENOW | RDW_ALLCHILDREN);
    RenderLayered();
}

void Switcher::ComputeLayout(const RECT& work, int& x, int& y, int& panelW, int& panelH)
{
    overlayLayout = AltWindowCycleLogic::ComputeOverlayLayout(work, static_cast<int>(windows.size()), scale);
    pad = overlayLayout.pad;
    gap = overlayLayout.gap;
    tileW = overlayLayout.tileW;
    headerH = overlayLayout.headerH;
    previewH = overlayLayout.previewH;
    inner = overlayLayout.inner;
    radius = overlayLayout.radius;
    cardTrimBottom = overlayLayout.cardTrimBottom;
    iconSize = overlayLayout.iconSize;
    tileH = overlayLayout.tileH;
    cols = overlayLayout.cols;
    rows = overlayLayout.rows;
    pageStart = AltWindowCycleLogic::PageStartForSelection(
        selected,
        static_cast<int>(windows.size()),
        overlayLayout.pageSize);

    x = overlayLayout.panelX;
    y = overlayLayout.panelY;
    panelW = overlayLayout.panelW;
    panelH = overlayLayout.panelH;
}

static SIZE QueryThumbSize(HTHUMBNAIL th)
{
    SIZE s = { 0, 0 };
    DwmQueryThumbnailSourceSize(th, &s);
    return s;
}

static SIZE ClientSourceSize(HWND hwnd)
{
    RECT cr = {};
    if (GetClientRect(hwnd, &cr))
    {
        SIZE s = { cr.right - cr.left, cr.bottom - cr.top };
        if (s.cx > 0 && s.cy > 0)
            return s;
    }
    return { 0, 0 };
}

void Switcher::RegisterThumbnails()
{
    UnregisterThumbnails();

    const int pageEnd = (std::min)(
        pageStart + overlayLayout.pageSize,
        static_cast<int>(windows.size()));
    for (int windowIndex = pageStart, slot = 0; windowIndex < pageEnd; ++windowIndex, ++slot)
    {
        RECT dest = PreviewRect(TileRect(slot));
        HTHUMBNAIL th = nullptr;
        if (FAILED(DwmRegisterThumbnail(thumbHost, windows[windowIndex], &th)) || !th)
        {
            thumbs.push_back(nullptr);
            continue;
        }
        thumbs.push_back(th);

        SIZE clientSize = IsIconic(windows[windowIndex]) ? SIZE{ 0, 0 } : ClientSourceSize(windows[windowIndex]);
        BOOL clientOnly = TRUE;
        if (clientSize.cx <= 0 || clientSize.cy <= 0)
        {
            clientSize = QueryThumbSize(th);
            clientOnly = FALSE;
        }
        RECT avail = { 0, 0, clientSize.cx, clientSize.cy };
        if (clientOnly)
        {
            int ix = (std::min)(2, (int)(avail.right - avail.left) / 4);
            int iy = (std::min)(2, (int)(avail.bottom - avail.top) / 4);
            avail.left += ix; avail.right -= ix;
            avail.top += iy; avail.bottom -= iy;
        }
        RECT rcSrc = AltWindowCycleLogic::CoverSource(dest, avail);
        DWM_THUMBNAIL_PROPERTIES props = {};
        props.dwFlags = DWM_TNP_RECTDESTINATION | DWM_TNP_RECTSOURCE |
                        DWM_TNP_VISIBLE | DWM_TNP_OPACITY | DWM_TNP_SOURCECLIENTAREAONLY;
        props.rcDestination = dest;
        props.rcSource = rcSrc;
        props.opacity = 255;
        props.fVisible = TRUE;
        props.fSourceClientAreaOnly = clientOnly;
        DwmUpdateThumbnailProperties(th, &props);
    }
}

void Switcher::UnregisterThumbnails()
{
    for (HTHUMBNAIL th : thumbs)
        if (th)
            DwmUnregisterThumbnail(th);
    thumbs.clear();
}

void Switcher::EnsureFont()
{
    if (font && fontScale == scale)
        return;
    if (font)
    {
        DeleteObject(font);
        font = nullptr;
    }
    int height = -Scaled(14);
    font = CreateFontW(height, 0, 0, 0, FW_NORMAL, FALSE, FALSE, FALSE,
                       DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS,
                       CLEARTYPE_NATURAL_QUALITY, DEFAULT_PITCH | FF_DONTCARE, L"Segoe UI");
    fontScale = scale;
}

static void BuildRoundRect(Gdiplus::GraphicsPath& path, const Gdiplus::RectF& r, Gdiplus::REAL rad)
{
    path.Reset();
    Gdiplus::REAL d = rad * 2;
    if (d <= 0 || d > r.Width || d > r.Height)
    {
        path.AddRectangle(r);
        return;
    }
    path.AddArc(r.X, r.Y, d, d, 180, 90);
    path.AddArc(r.GetRight() - d, r.Y, d, d, 270, 90);
    path.AddArc(r.GetRight() - d, r.GetBottom() - d, d, d, 0, 90);
    path.AddArc(r.X, r.GetBottom() - d, d, d, 90, 90);
    path.CloseFigure();
}

static void BuildBottomRoundRect(Gdiplus::GraphicsPath& path, const Gdiplus::RectF& r, Gdiplus::REAL rad)
{
    path.Reset();
    Gdiplus::REAL d = rad * 2;
    if (d <= 0 || d > r.Width || d > r.Height)
    {
        path.AddRectangle(r);
        return;
    }
    path.AddLine(r.X, r.Y, r.GetRight(), r.Y);
    path.AddLine(r.GetRight(), r.Y, r.GetRight(), r.GetBottom() - rad);
    path.AddArc(r.GetRight() - d, r.GetBottom() - d, d, d, 0, 90);
    path.AddArc(r.X, r.GetBottom() - d, d, d, 90, 90);
    path.CloseFigure();
}

static Gdiplus::RectF InflateF(const RECT& r, int by)
{
    return Gdiplus::RectF(
        static_cast<Gdiplus::REAL>(r.left - by),
        static_cast<Gdiplus::REAL>(r.top - by),
        static_cast<Gdiplus::REAL>((r.right - r.left) + 2 * by),
        static_cast<Gdiplus::REAL>((r.bottom - r.top) + 2 * by));
}

static std::wstring GetTitle(HWND hwnd)
{
    wchar_t buf[256];
    int len = GetWindowTextW(hwnd, buf, static_cast<int>(sizeof(buf) / sizeof(buf[0])));
    return std::wstring(buf, len > 0 ? len : 0);
}

static void DrawIconOverPARGB(void* destBits, int destW, int destH,
                              HICON icon, int x, int y, int size)
{
    if (!destBits || !icon || destW <= 0 || destH <= 0 || size <= 0)
        return;

    HDC screen = GetDC(nullptr);
    HDC iconDC = CreateCompatibleDC(screen);
    if (!iconDC)
    {
        ReleaseDC(nullptr, screen);
        return;
    }

    BITMAPINFO bi = {};
    bi.bmiHeader.biSize = sizeof(bi.bmiHeader);
    bi.bmiHeader.biWidth = size;
    bi.bmiHeader.biHeight = -size;
    bi.bmiHeader.biPlanes = 1;
    bi.bmiHeader.biBitCount = 32;
    bi.bmiHeader.biCompression = BI_RGB;

    void* iconBits = nullptr;
    HBITMAP dib = CreateDIBSection(screen, &bi, DIB_RGB_COLORS, &iconBits, nullptr, 0);
    if (!dib)
    {
        DeleteDC(iconDC);
        ReleaseDC(nullptr, screen);
        return;
    }

    HGDIOBJ oldBmp = SelectObject(iconDC, dib);
    ZeroMemory(iconBits, static_cast<size_t>(size) * size * 4);
    DrawIconEx(iconDC, 0, 0, icon, size, size, 0, nullptr, DI_NORMAL);

    BYTE* src = static_cast<BYTE*>(iconBits);
    BYTE* dst = static_cast<BYTE*>(destBits);

    bool hasAlpha = false;
    for (int i = 0; i < size * size; ++i)
    {
        if (src[i * 4 + 3] != 0)
        {
            hasAlpha = true;
            break;
        }
    }

    // Legacy (1-bit mask) icons carry no per-pixel alpha, so DrawIconEx leaves the
    // alpha channel at 0 and a pure-black opaque pixel is indistinguishable from a
    // transparent one by color alone. Render the icon over a white background on
    // a second pass: pixels identical on both backgrounds are opaque (preserving black
    // detail), pixels that differ by ~full white are transparent.
    void* whiteBits = nullptr;
    HBITMAP whiteDib = nullptr;
    if (!hasAlpha)
    {
        whiteDib = CreateDIBSection(screen, &bi, DIB_RGB_COLORS, &whiteBits, nullptr, 0);
        if (whiteDib)
        {
            SelectObject(iconDC, whiteDib);
            memset(whiteBits, 0xFF, static_cast<size_t>(size) * size * 4);
            DrawIconEx(iconDC, 0, 0, icon, size, size, 0, nullptr, DI_NORMAL);
        }
    }
    BYTE* white = static_cast<BYTE*>(whiteBits);

    for (int sy = 0; sy < size; ++sy)
    {
        int dy = y + sy;
        if (dy < 0 || dy >= destH)
            continue;
        for (int sx = 0; sx < size; ++sx)
        {
            int dx = x + sx;
            if (dx < 0 || dx >= destW)
                continue;

            size_t srcOff = (static_cast<size_t>(sy) * size + sx) * 4;
            BYTE* s = src + srcOff;
            BYTE* d = dst + (static_cast<size_t>(dy) * destW + dx) * 4;

            if (hasAlpha)
            {
                int a = s[3];
                if (a == 0)
                    continue;

                int sb = s[0], sg = s[1], sr = s[2];
                if (sb > a || sg > a || sr > a)
                {
                    sb = (sb * a + 127) / 255;
                    sg = (sg * a + 127) / 255;
                    sr = (sr * a + 127) / 255;
                }
                int inv = 255 - a;
                d[0] = static_cast<BYTE>((std::min)(255, sb + (d[0] * inv + 127) / 255));
                d[1] = static_cast<BYTE>((std::min)(255, sg + (d[1] * inv + 127) / 255));
                d[2] = static_cast<BYTE>((std::min)(255, sr + (d[2] * inv + 127) / 255));
                d[3] = 255;
            }
            else
            {
                bool opaque;
                if (white)
                {
                    BYTE* whitePx = white + srcOff;
                    int diff = (whitePx[0] - s[0]) + (whitePx[1] - s[1]) + (whitePx[2] - s[2]);
                    opaque = diff < 384; // < half of 3*255 → covered on both backgrounds
                }
                else
                {
                    opaque = (s[0] || s[1] || s[2]);
                }
                if (opaque)
                {
                    d[0] = s[0]; d[1] = s[1]; d[2] = s[2]; d[3] = 255;
                }
            }
        }
    }

    SelectObject(iconDC, oldBmp);
    DeleteObject(dib);
    if (whiteDib)
        DeleteObject(whiteDib);
    DeleteDC(iconDC);
    ReleaseDC(nullptr, screen);
}

atic void DrawHeaderText(BYTE* destBits, int destW, int destH, HFONT fontHandle,
                           const RECT& rc, const std::wstring& text,
                           COLORREF textColor,
                           UINT alignFlag = DT_LEFT)
{
    if (!destBits || destW <= 0 || destH <= 0 || text.empty() || !fontHandle)
        return;

    int w = rc.right - rc.left;
    int h = rc.bottom - rc.top;
    if (w <= 0 || h <= 0)
        return;

    HDC screen = GetDC(nullptr);
    HDC textDC = CreateCompatibleDC(screen);

    BITMAPINFO bi = {};
    bi.bmiHeader.biSize = sizeof(bi.bmiHeader);
    bi.bmiHeader.biWidth = w;
    bi.bmiHeader.biHeight = -h;
    bi.bmiHeader.biPlanes = 1;
    bi.bmiHeader.biBitCount = 32;
    bi.bmiHeader.biCompression = BI_RGB;

    void* scratchBits = nullptr;
    HBITMAP scratch = CreateDIBSection(screen, &bi, DIB_RGB_COLORS, &scratchBits, nullptr, 0);
    if (!scratch)
    {
        DeleteDC(textDC);
        ReleaseDC(nullptr, screen);
        return;
    }

    HGDIOBJ oldBmp = SelectObject(textDC, scratch);
    HGDIOBJ oldFont = SelectObject(textDC, fontHandle);
    RECT fill = { 0, 0, w, h };
    // Render white text on a black scratch; the luminance doubles as a coverage
    // mask so the glyphs can be composited onto the translucent card without
    // painting an opaque background box behind them.
    HBRUSH bg = CreateSolidBrush(RGB(0, 0, 0));
    FillRect(textDC, &fill, bg);
    DeleteObject(bg);

    int oldBk = SetBkMode(textDC, TRANSPARENT);
    COLORREF oldColor = SetTextColor(textDC, RGB(255, 255, 255));

    RECT textRc = fill;
    DrawTextW(textDC, text.c_str(), static_cast<int>(text.size()), &textRc,
              alignFlag | DT_SINGLELINE | DT_VCENTER | DT_END_ELLIPSIS | DT_NOPREFIX);

    SetTextColor(textDC, oldColor);
    SetBkMode(textDC, oldBk);
    SelectObject(textDC, oldFont);

    const int tb = GetBValue(textColor);
    const int tg = GetGValue(textColor);
    const int tr = GetRValue(textColor);
    const BYTE* src = static_cast<const BYTE*>(scratchBits);
    for (int y = 0; y < h; ++y)
    {
        int dy = rc.top + y;
        if (dy < 0 || dy >= destH)
            continue;
        for (int x = 0; x < w; ++x)
        {
            int dx = rc.left + x;
            if (dx < 0 || dx >= destW)
                continue;

            const BYTE* s = src + (static_cast<size_t>(y) * w + x) * 4;
            int a = (s[0] + s[1] + s[2] + 1) / 3; // glyph coverage 0..255
            if (a == 0)
                continue;

            // Source-over onto premultiplied-alpha dest (BGRA). The text is opaque,
            // so its premultiplied contribution is colour * coverage.
            BYTE* d = destBits + (static_cast<size_t>(dy) * destW + dx) * 4;
            int inv = 255 - a;
            d[0] = static_cast<BYTE>((tb * a + 127) / 255 + (d[0] * inv + 127) / 255);
            d[1] = static_cast<BYTE>((tg * a + 127) / 255 + (d[1] * inv + 127) / 255);
            d[2] = static_cast<BYTE>((tr * a + 127) / 255 + (d[2] * inv + 127) / 255);
            d[3] = static_cast<BYTE>(a + (d[3] * inv + 127) / 255);
        }
    }

    SelectObject(textDC, oldBmp);
    DeleteObject(scratch);
    DeleteDC(textDC);
    ReleaseDC(nullptr, screen);
}

atic COLORREF GetAccentColor()
{
    DWORD color = 0, size = sizeof(color), type = 0;
    HKEY key = nullptr;
    if (RegOpenKeyExW(HKEY_CURRENT_USER, L"Software\\Microsoft\\Windows\\DWM",
                      0, KEY_QUERY_VALUE, &key) == ERROR_SUCCESS)
    {
        LONG r = RegQueryValueExW(key, L"AccentColor", nullptr, &type,
                                  reinterpret_cast<BYTE*>(&color), &size);
        RegCloseKey(key);
        if (r == ERROR_SUCCESS && type == REG_DWORD)
            return color & 0x00FFFFFF;
    }
    DWORD argb = 0;
    BOOL opaque = FALSE;
    if (SUCCEEDED(DwmGetColorizationColor(&argb, &opaque)))
        return RGB((argb >> 16) & 0xFF, (argb >> 8) & 0xFF, argb & 0xFF);

    return AltTabStyle::AccentFallbackRef();
}

ESULT CALLBACK Switcher::WndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam)
{
    Switcher* self = reinterpret_cast<Switcher*>(GetWindowLongPtrW(hwnd, GWLP_USERDATA));
    if (self)
    {
        switch (msg)
        {
        case WM_TIMER:
            if (wParam == TIMER_ID)
            {
                self->OnTick();
                return 0;
            }
            break;
        case WM_ERASEBKGND:
            return 1;
        case WM_SETTINGCHANGE:
            if (lParam &&
                lstrcmpiW(reinterpret_cast<LPCWSTR>(lParam), L"ImmersiveColorSet") == 0)
            {
                self->OnThemeChanged();
                return 0;
            }
            break;
        }
    }
    return DefWindowProcW(hwnd, msg, wParam, lParam);
}

atic void CloseUIThreadHandle()
{
    CloseHandle(g_uiThread);
    g_uiThread = nullptr;
    g_uiThreadId = 0;
    g_threadHinst = nullptr;
    g_initOk.store(false);
}

atic void ClearExitedUIThread()
{
    if (g_uiThread && WaitForSingleObject(g_uiThread, 0) == WAIT_OBJECT_0)
    {
        CloseUIThreadHandle();
    }
}

atic bool RequestShutdownAndJoinUIThread(DWORD timeoutMs)
{
    if (!g_uiThread)
    {
        return true;
    }

    g_shutdownRequested.store(true);

    const bool bounded = timeoutMs != INFINITE;
    const ULONGLONG deadline = bounded ? GetTickCount64() + timeoutMs : 0;

    // The queue may not exist yet when initialization times out, so WM_QUIT is
    // re-posted until the bounded UI-thread work completes and the thread exits.
    for (;;)
    {
        if (g_uiThreadId)
        {
            PostThreadMessageW(g_uiThreadId, WM_QUIT, 0, 0);
        }

        DWORD slice = UIThreadJoinPollMs;
        if (bounded)
        {
            const ULONGLONG now = GetTickCount64();
            if (now >= deadline)
            {
                return false;
            }

            slice = static_cast<DWORD>((std::min<ULONGLONG>)(UIThreadJoinPollMs, deadline - now));
        }

        if (WaitForSingleObject(g_uiThread, slice) == WAIT_OBJECT_0)
        {
            break;
        }
    }

    CloseUIThreadHandle();
    return true;
}

atic bool PostHotkeyToUIThread(bool forward, unsigned int holdModifiers)
{
    return g_uiThreadId &&
           PostThreadMessageW(g_uiThreadId, WM_AWC_HOTKEY, forward ? 1u : 0u, static_cast<LPARAM>(holdModifiers)) != FALSE;
}

atic DWORD WINAPI UIThreadProc(LPVOID param)
{
    UNREFERENCED_PARAMETER(param);

    HINSTANCE hinst = g_threadHinst;
    HANDLE readyEvent = g_threadReadyEvent;
    g_threadReadyEvent = nullptr;

    // Set per-monitor v2 DPI awareness on this thread so overlay layout and DWM
    // thumbnail rects line up on any monitor. Does not affect the host process.
    SetThreadDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);

    Gdiplus::GdiplusStartupInput gdiplusStartupInput = {};
    ULONG_PTR token = 0;
    Gdiplus::GdiplusStartup(&token, &gdiplusStartupInput, nullptr);

    const bool initOk = g_switcher.Init(hinst);
    g_initOk.store(initOk);

    // Signal the caller that initialization is complete (success or failure).
    if (readyEvent)
    {
        SetEvent(readyEvent);
        CloseHandle(readyEvent);
    }

    if (!initOk || g_shutdownRequested.load())
    {
        g_switcher.Shutdown();
        if (token)
            Gdiplus::GdiplusShutdown(token);
        return initOk ? 0 : 1;
    }

    MSG msg;
    while (GetMessageW(&msg, nullptr, 0, 0) > 0)
    {
        if (msg.hwnd == nullptr && msg.message == WM_AWC_HOTKEY)
        {
            g_switcher.OnHotkey(msg.wParam != 0, static_cast<unsigned int>(msg.lParam));
        }
        else if (msg.hwnd == nullptr && msg.message == WM_AWC_CANCEL)
        {
            g_switcher.OnCancel();
        }
        else
        {
            TranslateMessage(&msg);
            DispatchMessageW(&msg);
        }
    }

    // Destroy all overlay resources BEFORE GdiplusShutdown.
    g_switcher.Shutdown();

    if (token)
        Gdiplus::GdiplusShutdown(token);

    return 0;
}

ol InitializeAltWindowCycle(HINSTANCE hinst)
{
    ClearExitedUIThread();

    // A previous disable() may have left a thread winding down. Give it a short,
    // bounded chance to finish rather than racing a second UI thread onto the
    // single global Switcher.
    if (g_uiThread != nullptr && g_shutdownRequested.load())
    {
        RequestShutdownAndJoinUIThread(UIThreadJoinTimeoutMs);
    }

    if (g_uiThread != nullptr)
    {
        if (g_shutdownRequested.load())
        {
            Logger::error("AltWindowCycle UI thread from a previous session is still running; enable aborted");
            return false;
        }

        return true; // already running or still starting
    }

    g_initOk.store(false);
    g_shutdownRequested.store(false);

    HANDLE readyEvent = CreateEventW(nullptr, TRUE, FALSE, nullptr);
    if (!readyEvent)
        return false;

    HANDLE readyEventForThread = nullptr;
    if (!DuplicateHandle(GetCurrentProcess(), readyEvent, GetCurrentProcess(), &readyEventForThread, 0, FALSE, DUPLICATE_SAME_ACCESS))
    {
        CloseHandle(readyEvent);
        return false;
    }

    g_threadHinst = hinst;
    g_threadReadyEvent = readyEventForThread;

    DWORD tid = 0;
    g_uiThread = CreateThread(nullptr, 0, UIThreadProc, nullptr, 0, &tid);
    if (!g_uiThread)
    {
        g_threadReadyEvent = nullptr;
        CloseHandle(readyEventForThread);
        CloseHandle(readyEvent);
        return false;
    }
    g_uiThreadId = tid;

    // Briefly wait for Init() so an outright failure is reported synchronously. A
    // timeout is not fatal: the thread keeps starting and the first hotkey simply
    // arrives once its message queue exists.
    const DWORD waitResult = WaitForSingleObject(readyEvent, UIThreadInitWaitMs);
    CloseHandle(readyEvent);
    if (waitResult == WAIT_OBJECT_0 && !g_initOk.load())
    {
        RequestShutdownAndJoinUIThread(UIThreadJoinTimeoutMs);
        return false;
    }

    return true;
}

id ShutdownAltWindowCycle(bool blockUntilExit)
{
    if (!RequestShutdownAndJoinUIThread(blockUntilExit ? INFINITE : UIThreadJoinTimeoutMs))
    {
        Logger::warn("AltWindowCycle UI thread did not exit within the disable() budget; it will finish asynchronously");
    }
}

ol HandleAltWindowCycleHotkey(bool forward, unsigned int holdModifiers)
{
    ClearExitedUIThread();
    if (!g_uiThread || g_shutdownRequested.load())
        return false;

    return PostHotkeyToUIThread(forward, holdModifiers);
}

void AssertRectEqual(const RECT& expected, const RECT& actual)
        {
            Assert::AreEqual(expected.left, actual.left, L"left");
            Assert::AreEqual(expected.top, actual.top, L"top");
            Assert::AreEqual(expected.right, actual.right, L"right");
            Assert::AreEqual(expected.bottom, actual.bottom, L"bottom");
        }

AltWindowCycleLogic::CandidateWindow MakeCandidate(
            unsigned long long id,
            const std::wstring& processKey,
            bool visible = true,
            bool cloaked = false,
            bool representative = true,
            bool toolWindow = false,
            bool appWindow = false)
        {
            AltWindowCycleLogic::CandidateWindow candidate;
            candidate.id = id;
            candidate.processKey = processKey;
            candidate.eligibility.isVisible = visible;
            candidate.eligibility.isCloaked = cloaked;
            candidate.eligibility.isAltTabRepresentative = representative;
            candidate.eligibility.isToolWindow = toolWindow;
            candidate.eligibility.isAppWindow = appWindow;
            return candidate;
        }

void AssertIds(std::initializer_list<unsigned long long> expected, const std::vector<unsigned long long>& actual)
        {
            Assert::AreEqual(static_cast<int>(expected.size()), static_cast<int>(actual.size()), L"cycle set size");
            size_t i = 0;
            for (const unsigned long long id : expected)
            {
                Assert::IsTrue(id == actual[i], L"cycle set id/order mismatch");
                ++i;
            }
        }

TEST_CLASS(AltWindowCycleLogicTests)
    {
    public:
        TEST_METHOD(ComputeOverlayLayoutUsesExpectedUnscaledGeometry)
        {
            const RECT work = { 0, 0, 1920, 1080 };

            const auto layout = AltWindowCycleLogic::ComputeOverlayLayout(work, 4, 1.0);

            Assert::AreEqual(32, layout.pad);
            Assert::AreEqual(26, layout.gap);
            Assert::AreEqual(270, layout.tileW);
            Assert::AreEqual(48, layout.headerH);
            Assert::AreEqual(142, layout.previewH);
            Assert::AreEqual(6, layout.inner);
            Assert::AreEqual(10, layout.radius);
            Assert::AreEqual(16, layout.iconSize);
            Assert::AreEqual(202, layout.tileH);
            Assert::AreEqual(4, layout.cols);
            Assert::AreEqual(1, layout.rows);
            Assert::AreEqual(4, layout.pageSize);
            Assert::AreEqual(1222, layout.panelW);
            Assert::AreEqual(266, layout.panelH);
            Assert::AreEqual(349, layout.panelX);
            Assert::AreEqual(407, layout.panelY);
        }

TEST_METHOD(ComputeOverlayLayoutUsesRoundedScaledGeometry)
        {
            const RECT work = { 0, 0, 1920, 1080 };

            const auto layout = AltWindowCycleLogic::ComputeOverlayLayout(work, 6, 1.5);

            Assert::AreEqual(48, layout.pad);
            Assert::AreEqual(39, layout.gap);
            Assert::AreEqual(405, layout.tileW);
            Assert::AreEqual(72, layout.headerH);
            Assert::AreEqual(213, layout.previewH);
            Assert::AreEqual(9, layout.inner);
            Assert::AreEqual(15, layout.radius);
            Assert::AreEqual(24, layout.iconSize);
            Assert::AreEqual(303, layout.tileH);
            Assert::AreEqual(4, layout.cols);
            Assert::AreEqual(2, layout.rows);
            Assert::AreEqual(6, layout.pageSize);
            Assert::AreEqual(1833, layout.panelW);
            Assert::AreEqual(741, layout.panelH);
            Assert::AreEqual(43, layout.panelX);
            Assert::AreEqual(169, layout.panelY);
        }

TEST_METHOD(ComputeOverlayLayoutHandlesEmptyWindowCount)
        {
            const RECT work = { 10, 20, 810, 620 };

            const auto layout = AltWindowCycleLogic::ComputeOverlayLayout(work, 0, 1.0);

            Assert::AreEqual(1, layout.cols);
            Assert::AreEqual(0, layout.rows);
            Assert::AreEqual(0, layout.pageSize);
        }

TEST_METHOD(TilePreviewAndHeaderRectsUsePanelRelativeInsetViewport)
        {
            const RECT work = { 0, 0, 1920, 1080 };
            const auto layout = AltWindowCycleLogic::ComputeOverlayLayout(work, 4, 1.0);

            const RECT tile = AltWindowCycleLogic::TileRect(layout, 0);
            AssertRectEqual({ 32, 32, 302, 234 }, tile);

            const RECT preview = AltWindowCycleLogic::PreviewRect(layout, tile);
            AssertRectEqual({ 33, 80, 301, 233 }, preview);

            const RECT header = AltWindowCycleLogic::HeaderRect(layout, tile);
            AssertRectEqual({ 44, 32, 290, 80 }, header);
        }

TEST_METHOD(CoverSourceCropsWideSourceToDestinationAspectRatio)
        {
            const RECT dest = { 0, 0, 100, 100 };
            const RECT avail = { 0, 0, 400, 200 };

            const RECT source = AltWindowCycleLogic::CoverSource(dest, avail);

            AssertRectEqual({ 100, 0, 300, 200 }, source);
        }

TEST_METHOD(CoverSourceCropsTallSourceToDestinationAspectRatio)
        {
            const RECT dest = { 0, 0, 100, 100 };
            const RECT avail = { 0, 0, 200, 400 };

            const RECT source = AltWindowCycleLogic::CoverSource(dest, avail);

            AssertRectEqual({ 0, 100, 200, 300 }, source);
        }

TEST_METHOD(CoverSourceReturnsAvailableRegionForInvalidInputs)
        {
            const RECT dest = { 0, 0, 0, 100 };
            const RECT avail = { 1, 2, 3, 4 };

            const RECT source = AltWindowCycleLogic::CoverSource(dest, avail);

            AssertRectEqual(avail, source);
        }

TEST_METHOD(WrapIndexWrapsForwardAndBackward)
        {
            Assert::AreEqual(0, AltWindowCycleLogic::WrapIndex(3, 3));
            Assert::AreEqual(2, AltWindowCycleLogic::WrapIndex(-1, 3));
            Assert::AreEqual(1, AltWindowCycleLogic::WrapIndex(4, 3));
            Assert::AreEqual(0, AltWindowCycleLogic::WrapIndex(4, 0));
        }

TEST_METHOD(StableHoldModifiersPreferNonShiftModifiers)
        {
            Assert::AreEqual(AltWindowCycleLogic::ModifierAlt, AltWindowCycleLogic::StableHoldModifiers(AltWindowCycleLogic::ModifierAlt | AltWindowCycleLogic::ModifierShift));
            Assert::AreEqual(AltWindowCycleLogic::ModifierCtrl, AltWindowCycleLogic::StableHoldModifiers(AltWindowCycleLogic::ModifierCtrl | AltWindowCycleLogic::ModifierShift));
            Assert::AreEqual(AltWindowCycleLogic::ModifierWin, AltWindowCycleLogic::StableHoldModifiers(AltWindowCycleLogic::ModifierWin));
            Assert::AreEqual(AltWindowCycleLogic::ModifierShift, AltWindowCycleLogic::StableHoldModifiers(AltWindowCycleLogic::ModifierShift));
            Assert::AreEqual(0u, AltWindowCycleLogic::StableHoldModifiers(0));
        }

TEST_METHOD(AreRequiredModifiersDownRequiresEveryHeldModifier)
        {
            Assert::IsFalse(AltWindowCycleLogic::AreRequiredModifiersDown(0, AltWindowCycleLogic::ModifierAlt));
            Assert::IsFalse(AltWindowCycleLogic::AreRequiredModifiersDown(AltWindowCycleLogic::ModifierAlt, 0));
            Assert::IsFalse(AltWindowCycleLogic::AreRequiredModifiersDown(AltWindowCycleLogic::ModifierAlt | AltWindowCycleLogic::ModifierCtrl, AltWindowCycleLogic::ModifierAlt));
            Assert::IsTrue(AltWindowCycleLogic::AreRequiredModifiersDown(AltWindowCycleLogic::ModifierAlt, AltWindowCycleLogic::ModifierAlt | AltWindowCycleLogic::ModifierShift));
            Assert::IsTrue(AltWindowCycleLogic::AreRequiredModifiersDown(AltWindowCycleLogic::ModifierAlt | AltWindowCycleLogic::ModifierCtrl, AltWindowCycleLogic::ModifierAlt | AltWindowCycleLogic::ModifierCtrl | AltWindowCycleLogic::ModifierShift));
        }

TEST_METHOD(BeginCycleSelectsNextOrPreviousAndShowsOverlay)
        {
            const auto forward = AltWindowCycleLogic::BeginCycle(0, 3, true);
            Assert::AreEqual(1, forward.selected);
            Assert::IsTrue(forward.action == AltWindowCycleLogic::FirstHotkeyAction::ShowOverlay);

            const auto backward = AltWindowCycleLogic::BeginCycle(0, 3, false);
            Assert::AreEqual(2, backward.selected);
            Assert::IsTrue(backward.action == AltWindowCycleLogic::FirstHotkeyAction::ShowOverlay);

            const auto ignored = AltWindowCycleLogic::BeginCycle(0, 1, true);
            Assert::AreEqual(0, ignored.selected);
            Assert::IsTrue(ignored.action == AltWindowCycleLogic::FirstHotkeyAction::Ignore);
        }

TEST_METHOD(IsAltTabEligibleRejectsEachDisqualifyingCondition)
        {
            // Invisible.
            Assert::IsFalse(AltWindowCycleLogic::IsAltTabEligible({ false, false, true, false }));
            // Cloaked (e.g. a background virtual-desktop window).
            Assert::IsFalse(AltWindowCycleLogic::IsAltTabEligible({ true, true, true, false }));
            // Owned / not the representative window of its owner chain.
            Assert::IsFalse(AltWindowCycleLogic::IsAltTabEligible({ true, false, false, false }));
            // Tool window.
            Assert::IsFalse(AltWindowCycleLogic::IsAltTabEligible({ true, false, true, true }));
        }

TEST_METHOD(ProcessKeyEqualsIsCaseInsensitiveAndRejectsEmptyCandidate)
        {
            Assert::IsTrue(AltWindowCycleLogic::ProcessKeyEquals(L"C:\\Apps\\Foo.exe", L"c:\\apps\\foo.EXE"));
            Assert::IsFalse(AltWindowCycleLogic::ProcessKeyEquals(L"C:\\Apps\\Foo.exe", L"C:\\Apps\\Bar.exe"));
            Assert::IsFalse(AltWindowCycleLogic::ProcessKeyEquals(L"", L"C:\\Apps\\Foo.exe"));
        }

TEST_METHOD(SelectCycleWindowsKeepsOnlyForegroundProcessInEnumerationOrder)
        {
            const std::wstring fg = L"C:\\Apps\\Editor.exe";
            const std::vector<AltWindowCycleLogic::CandidateWindow> candidates = {
                MakeCandidate(10, L"C:\\Apps\\Editor.exe"),
                MakeCandidate(20, L"C:\\Apps\\Browser.exe"),
                MakeCandidate(30, L"c:\\apps\\editor.EXE"), // same app, different casing
                MakeCandidate(40, L"C:\\Apps\\Browser.exe"),
                MakeCandidate(50, L"C:\\Apps\\Editor.exe"),
            };

            AssertIds({ 10, 30, 50 }, AltWindowCycleLogic::SelectCycleWindows(fg, candidates));
        }

TEST_METHOD(SelectCycleWindowsExcludesIneligibleWindowsOfTheSameApp)
        {
            const std::wstring fg = L"C:\\Apps\\Editor.exe";
            const std::vector<AltWindowCycleLogic::CandidateWindow> candidates = {
                MakeCandidate(1, fg), // eligible
                MakeCandidate(2, fg, /*visible*/ false),
                MakeCandidate(3, fg, /*visible*/ true, /*cloaked*/ true),
                MakeCandidate(4, fg, /*visible*/ true, /*cloaked*/ false, /*representative*/ false),
                MakeCandidate(5, fg, /*visible*/ true, /*cloaked*/ false, /*representative*/ true, /*tool*/ true),
                MakeCandidate(6, fg), // eligible
            };

            AssertIds({ 1, 6 }, AltWindowCycleLogic::SelectCycleWindows(fg, candidates));
        }

TEST_METHOD(SelectCycleWindowsReturnsEmptyWhenForegroundKeyUnknown)
        {
            const std::vector<AltWindowCycleLogic::CandidateWindow> candidates = {
                MakeCandidate(1, L"C:\\Apps\\Editor.exe"),
            };

            Assert::AreEqual(0u, static_cast<unsigned int>(AltWindowCycleLogic::SelectCycleWindows(L"", candidates).size()));
        }

TEST_METHOD(SelectCycleWindowsHandlesZeroAndSingleCandidate)
        {
            const std::wstring fg = L"C:\\Apps\\Editor.exe";

            Assert::AreEqual(0u, static_cast<unsigned int>(AltWindowCycleLogic::SelectCycleWindows(fg, {}).size()));

            const std::vector<AltWindowCycleLogic::CandidateWindow> single = { MakeCandidate(99, fg) };
            AssertIds({ 99 }, AltWindowCycleLogic::SelectCycleWindows(fg, single));
        }

TEST_METHOD(SelectCycleWindowsIncludesEveryWindowOfATiedProcess)
        {
            // Several windows of the same app (the real grouping key is the resolved
            // process image path, so multiple windows / duplicate pids all cycle).
            const std::wstring fg = L"C:\\Apps\\Editor.exe";
            const std::vector<AltWindowCycleLogic::CandidateWindow> candidates = {
                MakeCandidate(7, fg),
                MakeCandidate(8, fg),
                MakeCandidate(9, fg),
            };

            AssertIds({ 7, 8, 9 }, AltWindowCycleLogic::SelectCycleWindows(fg, candidates));
        }

TEST_METHOD(SelectCycleWindowsDropsCandidatesWithNoResolvedProcess)
        {
            const std::wstring fg = L"C:\\Apps\\Editor.exe";
            const std::vector<AltWindowCycleLogic::CandidateWindow> candidates = {
                MakeCandidate(1, fg),
                MakeCandidate(2, L""), // eligible flags but process could not be resolved
                MakeCandidate(3, fg),
            };

            AssertIds({ 1, 3 }, AltWindowCycleLogic::SelectCycleWindows(fg, candidates));
        }

TEST_METHOD(ComputeOverlayLayoutClampsColumnsToWindowCount)
        {
            const RECT work = { 0, 0, 1920, 1080 };

            const auto layout = AltWindowCycleLogic::ComputeOverlayLayout(work, 1, 1.0);

            Assert::AreEqual(1, layout.cols);
            Assert::AreEqual(1, layout.rows);
        }

TEST_METHOD(ComputeOverlayLayoutRespectsMaxColumns)
        {
            const RECT work = { 0, 0, 1920, 1080 };

            const auto layout = AltWindowCycleLogic::ComputeOverlayLayout(work, 10, 1.0, 3);

            Assert::AreEqual(3, layout.cols);
            Assert::AreEqual(4, layout.rows); // ceil(10 / 3)
        }

TEST_METHOD(ComputeOverlayLayoutClampsColumnsAndRowsToNarrowWorkArea)
        {
            const RECT work = { 0, 0, 640, 480 };

            const auto layout = AltWindowCycleLogic::ComputeOverlayLayout(work, 8, 1.0);

            // (640 - 64 + 26) / (270 + 26) = 2 columns fit the work area.
            Assert::AreEqual(2, layout.cols);
            Assert::AreEqual(1, layout.rows);
            Assert::AreEqual(2, layout.pageSize);
            Assert::IsTrue(layout.panelH <= work.bottom - work.top);
        }

TEST_METHOD(ComputeOverlayLayoutScalesPaddingAcrossDpi)
        {
            const RECT work = { 0, 0, 1920, 1080 };

            Assert::AreEqual(32, AltWindowCycleLogic::ComputeOverlayLayout(work, 4, 1.0).pad);
            Assert::AreEqual(40, AltWindowCycleLogic::ComputeOverlayLayout(work, 4, 1.25).pad);
            Assert::AreEqual(48, AltWindowCycleLogic::ComputeOverlayLayout(work, 4, 1.5).pad);
            Assert::AreEqual(64, AltWindowCycleLogic::ComputeOverlayLayout(work, 4, 2.0).pad);
        }

TEST_METHOD(ComputeOverlayLayoutPaginatesRowsThatDoNotFitWorkArea)
        {
            const RECT work = { 0, 0, 1920, 1080 };

            const auto layout = AltWindowCycleLogic::ComputeOverlayLayout(work, 13, 1.5);

            Assert::AreEqual(4, layout.cols);
            Assert::AreEqual(2, layout.rows);
            Assert::AreEqual(8, layout.pageSize);
            Assert::IsTrue(layout.panelH <= work.bottom - work.top);
        }

TEST_METHOD(PageStartForSelectionKeepsSelectedWindowOnPage)
        {
            Assert::AreEqual(0, AltWindowCycleLogic::PageStartForSelection(0, 13, 8));
            Assert::AreEqual(0, AltWindowCycleLogic::PageStartForSelection(7, 13, 8));
            Assert::AreEqual(8, AltWindowCycleLogic::PageStartForSelection(8, 13, 8));
            Assert::AreEqual(8, AltWindowCycleLogic::PageStartForSelection(12, 13, 8));
            Assert::AreEqual(0, AltWindowCycleLogic::PageStartForSelection(-1, 13, 8));
            Assert::AreEqual(8, AltWindowCycleLogic::PageStartForSelection(13, 13, 8));
            Assert::AreEqual(0, AltWindowCycleLogic::PageStartForSelection(0, 0, 0));
        }

TEST_METHOD(PageCountReportsPagesForPaginationAffordance)
        {
            Assert::AreEqual(1, AltWindowCycleLogic::PageCount(1, 8));
            Assert::AreEqual(1, AltWindowCycleLogic::PageCount(8, 8));
            Assert::AreEqual(2, AltWindowCycleLogic::PageCount(9, 8));
            Assert::AreEqual(2, AltWindowCycleLogic::PageCount(13, 8));
            Assert::AreEqual(3, AltWindowCycleLogic::PageCount(17, 8));
            Assert::AreEqual(0, AltWindowCycleLogic::PageCount(0, 8));
            Assert::AreEqual(0, AltWindowCycleLogic::PageCount(13, 0));
        }

TEST_METHOD(TileRectAdvancesAcrossColumnsAndRows)
        {
            const RECT work = { 0, 0, 1920, 1080 };
            const auto layout = AltWindowCycleLogic::ComputeOverlayLayout(work, 8, 1.0);

            Assert::AreEqual(6, layout.cols); // sanity: second row exists

            // Second column, first row.
            AssertRectEqual({ 328, 32, 598, 234 }, AltWindowCycleLogic::TileRect(layout, 1));
            // First column, second row.
            AssertRectEqual({ 32, 260, 302, 462 }, AltWindowCycleLogic::TileRect(layout, 6));
        }

TEST_METHOD(WrapIndexNormalizesNegativeAndOversizedIndices)
        {
            Assert::AreEqual(2, AltWindowCycleLogic::WrapIndex(-4, 3));
            Assert::AreEqual(1, AltWindowCycleLogic::WrapIndex(7, 3));
            Assert::AreEqual(0, AltWindowCycleLogic::WrapIndex(0, 5));
            Assert::AreEqual(0, AltWindowCycleLogic::WrapIndex(-3, 3));
        }

TEST_METHOD(BeginCycleClampsNegativeCurrentIndex)
        {
            const auto forward = AltWindowCycleLogic::BeginCycle(-1, 3, true);
            Assert::AreEqual(1, forward.selected);
            Assert::IsTrue(forward.action == AltWindowCycleLogic::FirstHotkeyAction::ShowOverlay);

            const auto backward = AltWindowCycleLogic::BeginCycle(-5, 3, false);
            Assert::AreEqual(2, backward.selected);
        }

TEST_METHOD(StableHoldModifiersStripsUnknownBitsAndPrefersNonShift)
        {
            const unsigned int expected =
                AltWindowCycleLogic::ModifierAlt | AltWindowCycleLogic::ModifierCtrl | AltWindowCycleLogic::ModifierWin;
            Assert::AreEqual(expected, AltWindowCycleLogic::StableHoldModifiers(0xFFu));
        }

BOOL APIENTRY DllMain(HMODULE /*hModule*/, DWORD ul_reason_for_call, LPVOID /*lpReserved*/)
{
    switch (ul_reason_for_call)
    {
    case DLL_PROCESS_ATTACH:
        Trace::RegisterProvider();
        break;
    case DLL_THREAD_ATTACH:
    case DLL_THREAD_DETACH:
        break;
    case DLL_PROCESS_DETACH:
        Trace::UnregisterProvider();
        break;
    }
    return TRUE;
}

static unsigned int ModifierMaskFromHotkey(const PowertoyModuleIface::Hotkey& hotkey)
    {
        unsigned int modifiers = 0;
        if (hotkey.alt)
        {
            modifiers |= AltWindowCycleLogic::ModifierAlt;
        }
        if (hotkey.ctrl)
        {
            modifiers |= AltWindowCycleLogic::ModifierCtrl;
        }
        if (hotkey.shift)
        {
            modifiers |= AltWindowCycleLogic::ModifierShift;
        }
        if (hotkey.win)
        {
            modifiers |= AltWindowCycleLogic::ModifierWin;
        }

        return AltWindowCycleLogic::StableHoldModifiers(modifiers);
    }

static void parse_hotkey(const winrt::Windows::Data::Json::JsonObject& properties,
                             const wchar_t* key,
                             PowertoyModuleIface::Hotkey& hotkey)
    {
        try
        {
            auto jsonHotkeyObject = properties.GetNamedObject(key);
            hotkey.win = jsonHotkeyObject.GetNamedBoolean(JSON_KEY_WIN);
            hotkey.alt = jsonHotkeyObject.GetNamedBoolean(JSON_KEY_ALT);
            hotkey.shift = jsonHotkeyObject.GetNamedBoolean(JSON_KEY_SHIFT);
            hotkey.ctrl = jsonHotkeyObject.GetNamedBoolean(JSON_KEY_CTRL);
            hotkey.key = static_cast<unsigned char>(jsonHotkeyObject.GetNamedNumber(JSON_KEY_CODE));
        }
        catch (...)
        {
            Logger::error("Failed to initialize AltWindowCycle shortcut from settings");
        }
    }

AltWindowCycle()
    {
        LoggerHelpers::init_logger(L"AltWindowCycle", L"ModuleInterface", "AltWindowCycle");
        init_settings();
    }

virtual void destroy() override
    {
        // The runner unloads this DLL right after destroy() returns, so the UI
        // thread must be fully gone before the module code disappears.
        ShutdownAltWindowCycle(true); // idempotent
        delete this;
    }

virtual bool get_config(wchar_t* buffer, int* buffer_size) override
    {
        HINSTANCE hinstance = reinterpret_cast<HINSTANCE>(&__ImageBase);

        PowerToysSettings::Settings settings(hinstance, get_name());
        settings.set_description(L"Cycle between the windows of the currently focused application.");

        return settings.serialize_to_buffer(buffer, buffer_size);
    }

virtual void set_config(const wchar_t* config) override
    {
        try
        {
            PowerToysSettings::PowerToyValues values =
                PowerToysSettings::PowerToyValues::from_json_string(config, get_key());

            parse_settings(values);
            values.save_to_settings_file();
        }
        catch (std::exception&)
        {
            // Improper JSON.
        }
    }

virtual void enable() override
    {
        m_enabled = InitializeAltWindowCycle(reinterpret_cast<HINSTANCE>(&__ImageBase));
        if (m_enabled)
        {
            Trace::EnableAltWindowCycle(true);
        }
    }

virtual void disable() override
    {
        m_enabled = false;
        Trace::EnableAltWindowCycle(false);

        // disable() runs on the runner thread that services the centralized
        // low-level keyboard hook, so it must never block on the UI thread.
        ShutdownAltWindowCycle(false);
    }

virtual size_t get_hotkeys(Hotkey* hotkeys, size_t buffer_size) override
    {
        if (hotkeys && buffer_size >= HotkeyCount)
        {
            hotkeys[HotkeyNext] = m_nextHotkey;
            hotkeys[HotkeyPrevious] = m_previousHotkey;
        }

        return HotkeyCount;
    }

virtual bool on_hotkey(size_t hotkeyId) override
    {
        if (!m_enabled)
        {
            return false;
        }

        if (hotkeyId == HotkeyNext)
        {
            Trace::CycleWindow(true);
            return HandleAltWindowCycleHotkey(true, ModifierMaskFromHotkey(m_nextHotkey));
        }

        if (hotkeyId == HotkeyPrevious)
        {
            Trace::CycleWindow(false);
            return HandleAltWindowCycleHotkey(false, ModifierMaskFromHotkey(m_previousHotkey));
        }

        return false;
    }

void AltWindowCycle::init_settings()
{
    try
    {
        PowerToysSettings::PowerToyValues settings =
            PowerToysSettings::PowerToyValues::load_from_settings_file(AltWindowCycle::get_key());
        parse_settings(settings);
    }
    catch (std::exception&)
    {
        // Error while loading from the settings file. Let default values stay as they are.
    }
}

void AltWindowCycle::parse_settings(PowerToysSettings::PowerToyValues& settings)
{
    // Reset to defaults before parsing so removed/invalid values fall back cleanly.
    m_nextHotkey = PowertoyModuleIface::Hotkey{};
    m_previousHotkey = PowertoyModuleIface::Hotkey{};

    auto settingsObject = settings.get_raw_json();
    if (settingsObject.GetView().Size() && settingsObject.HasKey(JSON_KEY_PROPERTIES))
    {
        auto properties = settingsObject.GetNamedObject(JSON_KEY_PROPERTIES);
        if (properties.HasKey(JSON_KEY_NEXT_WINDOW_SHORTCUT))
        {
            parse_hotkey(properties, JSON_KEY_NEXT_WINDOW_SHORTCUT, m_nextHotkey);
        }
        if (properties.HasKey(JSON_KEY_PREVIOUS_WINDOW_SHORTCUT))
        {
            parse_hotkey(properties, JSON_KEY_PREVIOUS_WINDOW_SHORTCUT, m_previousHotkey);
        }
    }
    else
    {
        Logger::info("AltWindowCycle settings are empty");
    }

    // Default: Alt+` cycles to the next window of the focused app.
    if (!m_nextHotkey.key || !HasModifier(m_nextHotkey))
    {
        m_nextHotkey.win = false;
        m_nextHotkey.ctrl = false;
        m_nextHotkey.shift = false;
        m_nextHotkey.alt = true;
        m_nextHotkey.key = DEFAULT_BACKTICK_VK;
    }

    // Default: Shift+Alt+` cycles to the previous window of the focused app.
    if (!m_previousHotkey.key || !HasModifier(m_previousHotkey))
    {
        m_previousHotkey.win = false;
        m_previousHotkey.ctrl = false;
        m_previousHotkey.shift = true;
        m_previousHotkey.alt = true;
        m_previousHotkey.key = DEFAULT_BACKTICK_VK;
    }
}

void Trace::EnableAltWindowCycle(const bool enabled) noexcept
{
    TraceLoggingWriteWrapper(
        g_hProvider,
        "AltWindowCycle_EnableAltWindowCycle",
        ProjectTelemetryPrivacyDataTag(ProjectTelemetryTag_ProductAndServicePerformance),
        TraceLoggingKeyword(PROJECT_KEYWORD_MEASURE),
        TraceLoggingBoolean(enabled, "Enabled"));
}

void Trace::CycleWindow(const bool forward) noexcept
{
    TraceLoggingWriteWrapper(
        g_hProvider,
        "AltWindowCycle_CycleWindow",
        ProjectTelemetryPrivacyDataTag(ProjectTelemetryTag_ProductAndServicePerformance),
        TraceLoggingKeyword(PROJECT_KEYWORD_MEASURE),
        TraceLoggingBoolean(forward, "Forward"));
}

void KeyboardListener::ForceReset()
    {
        letterPressed = LetterKey::None;
        m_toolbarVisible = false;
        m_triggeredWithSpace = false;
        m_triggeredWithLeftArrow = false;
        m_triggeredWithRightArrow = false;
        m_leftShiftPressed = false;
        m_rightShiftPressed = false;
    }

bool verified_signer_is_microsoft(CRYPT_PROVIDER_DATA* provData)
        {
            CRYPT_PROVIDER_SGNR* signer = WTHelperGetProvSignerFromChain(provData, 0, FALSE, 0);
            if (!signer || signer->csCertChain == 0)
            {
                return false;
            }

            CRYPT_PROVIDER_CERT* leaf = WTHelperGetProvCertFromChain(signer, 0);
            if (!leaf || !leaf->pCert)
            {
                return false;
            }

            // Match on the certificate's Organization (O) rather than the CN (which can vary,
            // e.g. ".NET"). Compare case-insensitively so a cosmetic casing difference can't cause
            // a false negative. Mutable copy of the OID string: CertGetNameStringW takes a
            // non-const void* type param.
            char organizationOid[] = szOID_ORGANIZATION_NAME;
            const DWORD nameLen = CertGetNameStringW(leaf->pCert, CERT_NAME_ATTR_TYPE, 0, organizationOid, nullptr, 0);
            if (nameLen <= 1)
            {
                return false;
            }

            std::wstring organization(nameLen, L'\0');
            CertGetNameStringW(leaf->pCert, CERT_NAME_ATTR_TYPE, 0, organizationOid, organization.data(), nameLen);
            organization.resize(nameLen - 1); // drop the trailing null terminator

            return _wcsicmp(organization.c_str(), MICROSOFT_ORGANIZATION_NAME) == 0;
        }

bool cached_revocation_says_revoked(const std::wstring& installerPath, void* verifiedFileHandle)
        {
            WINTRUST_FILE_INFO fileInfo{};
            fileInfo.cbStruct = sizeof(fileInfo);
            fileInfo.pcwszFilePath = installerPath.c_str();
            fileInfo.hFile = verifiedFileHandle;

            GUID actionGuid = WINTRUST_ACTION_GENERIC_VERIFY_V2;

            WINTRUST_DATA trustData{};
            trustData.cbStruct = sizeof(trustData);
            trustData.dwUIChoice = WTD_UI_NONE;
            trustData.fdwRevocationChecks = WTD_REVOKE_WHOLECHAIN;
            trustData.dwUnionChoice = WTD_CHOICE_FILE;
            trustData.dwStateAction = WTD_STATEACTION_VERIFY;
            trustData.dwProvFlags = WTD_SAFER_FLAG | WTD_CACHE_ONLY_URL_RETRIEVAL;
            trustData.pFile = &fileInfo;

            const LONG status = WinVerifyTrust(static_cast<HWND>(INVALID_HANDLE_VALUE), &actionGuid, &trustData);

            trustData.dwStateAction = WTD_STATEACTION_CLOSE;
            WinVerifyTrust(static_cast<HWND>(INVALID_HANDLE_VALUE), &actionGuid, &trustData);

            return status == static_cast<LONG>(CERT_E_REVOKED);
        }

std::wstring read_version_string(const std::vector<BYTE>& versionInfo, WORD language, WORD codePage, const wchar_t* name)
        {
            wchar_t subBlock[128];
            swprintf_s(subBlock, L"\\StringFileInfo\\%04x%04x\\%s", language, codePage, name);

            LPVOID value = nullptr;
            UINT valueLen = 0;
            if (VerQueryValueW(versionInfo.data(), subBlock, &value, &valueLen) && value != nullptr && valueLen > 0)
            {
                std::wstring result{ static_cast<const wchar_t*>(value), valueLen };
                result.resize(wcslen(result.c_str()));
                return result;
            }
            return {};
        }

bool exe_version_info_is_powertoys(const std::wstring& installerPath)
        {
            DWORD ignoredHandle = 0;
            const DWORD size = GetFileVersionInfoSizeW(installerPath.c_str(), &ignoredHandle);
            if (size == 0)
            {
                Logger::error(L"Installer '{}' has no version resource (error {:#x})", installerPath, GetLastError());
                return false;
            }

            std::vector<BYTE> versionInfo(size);
            if (!GetFileVersionInfoW(installerPath.c_str(), 0, size, versionInfo.data()))
            {
                Logger::error(L"Couldn't read the version resource of installer '{}' (error {:#x})", installerPath, GetLastError());
                return false;
            }

            struct LangAndCodePage
            {
                WORD language;
                WORD codePage;
            };
            LangAndCodePage* translations = nullptr;
            UINT translationsBytes = 0;
            if (!VerQueryValueW(versionInfo.data(), L"\\VarFileInfo\\Translation", reinterpret_cast<LPVOID*>(&translations), &translationsBytes) ||
                translations == nullptr || translationsBytes < sizeof(LangAndCodePage))
            {
                Logger::error(L"Installer '{}' version resource has no translation table", installerPath);
                return false;
            }

            const size_t translationCount = translationsBytes / sizeof(LangAndCodePage);
            for (size_t i = 0; i < translationCount; ++i)
            {
                const std::wstring company = read_version_string(versionInfo, translations[i].language, translations[i].codePage, L"CompanyName");
                const std::wstring product = read_version_string(versionInfo, translations[i].language, translations[i].codePage, L"ProductName");

                if (_wcsicmp(company.c_str(), MICROSOFT_ORGANIZATION_NAME) == 0 &&
                    product.starts_with(POWERTOYS_PRODUCT_NAME_PREFIX))
                {
                    return true;
                }
            }

            Logger::error(L"Installer '{}' version resource doesn't match the PowerToys bootstrapper identity", installerPath);
            return false;
        }

bool msi_upgrade_code_is_powertoys(const std::wstring& installerPath)
        {
            PMSIHANDLE database;
            UINT result = MsiOpenDatabaseW(installerPath.c_str(), MSIDBOPEN_READONLY, &database);
            if (result != ERROR_SUCCESS)
            {
                Logger::error(L"Couldn't open installer '{}' as an MSI database (error {})", installerPath, result);
                return false;
            }

            PMSIHANDLE view;
            result = MsiDatabaseOpenViewW(database, L"SELECT `Value` FROM `Property` WHERE `Property` = 'UpgradeCode'", &view);
            if (result != ERROR_SUCCESS)
            {
                Logger::error(L"Couldn't query the UpgradeCode of MSI '{}' (error {})", installerPath, result);
                return false;
            }

            result = MsiViewExecute(view, 0);
            if (result != ERROR_SUCCESS)
            {
                Logger::error(L"Couldn't execute the UpgradeCode query for MSI '{}' (error {})", installerPath, result);
                return false;
            }

            PMSIHANDLE record;
            result = MsiViewFetch(view, &record);
            if (result != ERROR_SUCCESS)
            {
                Logger::error(L"MSI '{}' has no UpgradeCode property (error {})", installerPath, result);
                return false;
            }

            wchar_t upgradeCode[64] = {};
            DWORD upgradeCodeLen = ARRAYSIZE(upgradeCode);
            result = MsiRecordGetStringW(record, 1, upgradeCode, &upgradeCodeLen);
            if (result != ERROR_SUCCESS)
            {
                Logger::error(L"Couldn't read the UpgradeCode value of MSI '{}' (error {})", installerPath, result);
                return false;
            }

            if (_wcsicmp(upgradeCode, POWER_TOYS_UPGRADE_CODE) == 0 ||
                _wcsicmp(upgradeCode, POWER_TOYS_UPGRADE_CODE_USER) == 0)
            {
                return true;
            }

            Logger::error(L"MSI '{}' UpgradeCode {} is not a known PowerToys package", installerPath, upgradeCode);
            return false;
        }

bool is_expected_powertoys_installer(const std::wstring& installerPath)
        {
            if (installerPath.ends_with(L".msi"))
            {
                return msi_upgrade_code_is_powertoys(installerPath);
            }
            // Otherwise it is the WiX bootstrapper .exe (matching how Stage 2 launches it).
            return exe_version_info_is_powertoys(installerPath);
        }

bool verify_installer_trust(const std::wstring& installerPath, void* verifiedFileHandle)
    {
        WINTRUST_FILE_INFO fileInfo{};
        fileInfo.cbStruct = sizeof(fileInfo);
        fileInfo.pcwszFilePath = installerPath.c_str();
        fileInfo.hFile = verifiedFileHandle; // verify the exact bytes we hold open, closing the TOCTOU window
        fileInfo.pgKnownSubject = nullptr;

        GUID actionGuid = WINTRUST_ACTION_GENERIC_VERIFY_V2;

        WINTRUST_DATA trustData{};
        trustData.cbStruct = sizeof(trustData);
        trustData.dwUIChoice = WTD_UI_NONE;
        trustData.fdwRevocationChecks = WTD_REVOKE_NONE;
        trustData.dwUnionChoice = WTD_CHOICE_FILE;
        trustData.dwStateAction = WTD_STATEACTION_VERIFY;
        // WTD_CACHE_ONLY_URL_RETRIEVAL keeps chain building local: without it WinVerifyTrust can
        // reach the network to fetch missing intermediates, which may hang or time out when the
        // update is applied offline. Revocation checks are already disabled above for the same reason.
        trustData.dwProvFlags = WTD_SAFER_FLAG | WTD_CACHE_ONLY_URL_RETRIEVAL;
        trustData.pFile = &fileInfo;

        const LONG status = WinVerifyTrust(static_cast<HWND>(INVALID_HANDLE_VALUE), &actionGuid, &trustData);

        // Read the signer from the verified state BEFORE closing it, so the publisher check is
        // bound to exactly the signature just validated against the locked handle.
        bool microsoftSigned = false;
        if (status == ERROR_SUCCESS)
        {
            if (CRYPT_PROVIDER_DATA* provData = WTHelperProvDataFromStateData(trustData.hWVTStateData))
            {
                microsoftSigned = verified_signer_is_microsoft(provData);
            }
        }

        trustData.dwStateAction = WTD_STATEACTION_CLOSE;
        WinVerifyTrust(static_cast<HWND>(INVALID_HANDLE_VALUE), &actionGuid, &trustData);

        if (status != ERROR_SUCCESS)
        {
            Logger::error(L"Installer Authenticode trust verification failed for '{}' (status: {:#010x})", installerPath, static_cast<uint32_t>(status));
            return false;
        }

        if (!microsoftSigned)
        {
            // Reaches here both when the signer's organization is not "Microsoft Corporation" and
            // when the signer information couldn't be read from the verified state at all; the
            // wording covers both so it isn't misread as "a specific, known non-Microsoft signer".
            Logger::error(L"Installer '{}' is Authenticode-signed but its signer could not be confirmed as Microsoft Corporation; refusing to run it elevated", installerPath);
            return false;
        }

        // Reject only a chain that is DEFINITIVELY revoked per locally cached revocation data;
        // offline/unknown is treated as not-revoked so offline updates still succeed.
        if (cached_revocation_says_revoked(installerPath, verifiedFileHandle))
        {
            Logger::error(L"Installer '{}' certificate chain is revoked; refusing to run it elevated", installerPath);
            return false;
        }

        // Identity pinning: confirm this is the PowerToys installer, not merely any Microsoft-signed
        // binary, so a different Microsoft-signed installer/tool can't be used for a confused-deputy
        // elevation.
        if (!is_expected_powertoys_installer(installerPath))
        {
            Logger::error(L"Installer '{}' is Microsoft-signed but is not the PowerToys installer; refusing to run it elevated", installerPath);
            return false;
        }

        return true;
    }

TEST_METHOD(HandleStatelessSessionEndMessage_QueryEndSession_AllowsShutdown)
        {
            LRESULT result = 0;
            bool handled = handle_stateless_session_end_message(nullptr, WM_QUERYENDSESSION, 0, 0, result);

            Assert::IsTrue(handled, L"WM_QUERYENDSESSION should be handled");
            Assert::AreEqual(static_cast<LRESULT>(TRUE), result,
                             L"WM_QUERYENDSESSION must return TRUE so the OS can proceed with shutdown");
        }

TEST_METHOD(HandleStatelessSessionEndMessage_EndSessionCancelled_DoesNotTearDown)
        {
            // wparam == FALSE means another app vetoed shutdown; we must not
            // tear down. We pass a real HWND so that an accidental
            // DestroyWindow call would be observable.
            WNDCLASSW wc{};
            wc.lpfnWndProc = DefWindowProcW;
            wc.hInstance = GetModuleHandleW(nullptr);
            wc.lpszClassName = L"EndSessionTest_Cancelled";
            RegisterClassW(&wc);

            HWND hwnd = CreateWindowExW(0, L"EndSessionTest_Cancelled", L"Test",
                                        0, 0, 0, 0, 0, HWND_MESSAGE, nullptr,
                                        GetModuleHandleW(nullptr), nullptr);
            Assert::IsNotNull(hwnd, L"Test window must be created");

            LRESULT result = 0xDEAD;
            bool handled = handle_stateless_session_end_message(hwnd, WM_ENDSESSION, FALSE, 0, result);

            Assert::IsTrue(handled, L"WM_ENDSESSION should be handled");
            Assert::AreEqual(static_cast<LRESULT>(0), result);
            Assert::IsTrue(IsWindow(hwnd) == TRUE,
                           L"Window must survive WM_ENDSESSION when shutdown is cancelled");

            DestroyWindow(hwnd);
            UnregisterClassW(L"EndSessionTest_Cancelled", GetModuleHandleW(nullptr));
        }

TEST_METHOD(HandleStatelessSessionEndMessage_EndSessionConfirmed_TearsDownAndExitsLoop)
        {
            // wparam == TRUE means shutdown is actually proceeding. The
            // helper must DestroyWindow, which routes through WM_DESTROY ->
            // PostQuitMessage(0), so a subsequent run_message_loop returns.
            WNDCLASSW wc{};
            wc.lpfnWndProc = [](HWND hwnd, UINT msg, WPARAM w, LPARAM l) -> LRESULT {
                if (msg == WM_DESTROY)
                {
                    PostQuitMessage(0);
                    return 0;
                }
                return DefWindowProcW(hwnd, msg, w, l);
            };
            wc.hInstance = GetModuleHandleW(nullptr);
            wc.lpszClassName = L"EndSessionTest_Confirmed";
            RegisterClassW(&wc);

            HWND hwnd = CreateWindowExW(0, L"EndSessionTest_Confirmed", L"Test",
                                        0, 0, 0, 0, 0, HWND_MESSAGE, nullptr,
                                        GetModuleHandleW(nullptr), nullptr);
            Assert::IsNotNull(hwnd, L"Test window must be created");

            LRESULT result = 0xDEAD;
            bool handled = handle_stateless_session_end_message(hwnd, WM_ENDSESSION, TRUE, 0, result);

            Assert::IsTrue(handled, L"WM_ENDSESSION should be handled");
            Assert::AreEqual(static_cast<LRESULT>(0), result);

            // After DestroyWindow the window must no longer exist and the
            // message loop must exit promptly because WM_QUIT was posted.
            // The timeout exceeds the assertion threshold so the test fails
            // if the loop waits for the timer instead of consuming WM_QUIT.
            auto start = std::chrono::steady_clock::now();
            run_message_loop(false, 3000);
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                std::chrono::steady_clock::now() - start);

            Assert::IsFalse(IsWindow(hwnd) == TRUE,
                            L"Window must be destroyed after WM_ENDSESSION(TRUE)");
            Assert::IsTrue(elapsed.count() < 2000,
                           L"Message loop must exit quickly after WM_ENDSESSION, not wait for the timeout");

            UnregisterClassW(L"EndSessionTest_Confirmed", GetModuleHandleW(nullptr));
        }

TEST_METHOD(HandleStatelessSessionEndMessage_UnrelatedMessage_NotHandled)
        {
            LRESULT result = 0xDEAD;
            bool handled = handle_stateless_session_end_message(nullptr, WM_USER, 0, 0, result);

            Assert::IsFalse(handled, L"Non-end-session messages must fall through");
            Assert::AreEqual(static_cast<LRESULT>(0xDEAD), result,
                             L"out_result must be left untouched when not handled");
        }

TEST_METHOD(HandleStatelessSessionEndMessage_EndSessionConfirmed_SignalsSystemSessionEnding)
        {
            // wparam == TRUE must flag the system session ending before teardown.
            WNDCLASSW wc{};
            wc.lpfnWndProc = [](HWND hwnd, UINT msg, WPARAM w, LPARAM l) -> LRESULT {
                if (msg == WM_DESTROY)
                {
                    PostQuitMessage(0);
                    return 0;
                }
                return DefWindowProcW(hwnd, msg, w, l);
            };
            wc.hInstance = GetModuleHandleW(nullptr);
            wc.lpszClassName = L"EndSessionTest_Signals";
            RegisterClassW(&wc);

            HWND hwnd = CreateWindowExW(0, L"EndSessionTest_Signals", L"Test",
                                        0, 0, 0, 0, 0, HWND_MESSAGE, nullptr,
                                        GetModuleHandleW(nullptr), nullptr);
            Assert::IsNotNull(hwnd, L"Test window must be created");

            LRESULT result = 0;
            bool system_session_ending = false;
            bool handled = handle_stateless_session_end_message(hwnd, WM_ENDSESSION, TRUE, 0, result, &system_session_ending);

            Assert::IsTrue(handled, L"WM_ENDSESSION should be handled");
            Assert::IsTrue(system_session_ending,
                           L"WM_ENDSESSION(TRUE) must flag a full system session end so WM_DESTROY can skip blocking cleanup");

            // Drain the WM_QUIT posted by the test WndProc so it cannot leak into
            // a subsequent test running on the same thread.
            run_message_loop(false, 1000);
            UnregisterClassW(L"EndSessionTest_Signals", GetModuleHandleW(nullptr));
        }

TEST_METHOD(HandleStatelessSessionEndMessage_CloseApp_DoesNotSignalSystemSessionEnding)
        {
            WNDCLASSW wc{};
            wc.lpfnWndProc = DefWindowProcW;
            wc.hInstance = GetModuleHandleW(nullptr);
            wc.lpszClassName = L"EndSessionTest_CloseApp";
            RegisterClassW(&wc);

            HWND hwnd = CreateWindowExW(0, L"EndSessionTest_CloseApp", L"Test",
                                        0, 0, 0, 0, 0, HWND_MESSAGE, nullptr,
                                        GetModuleHandleW(nullptr), nullptr);
            Assert::IsNotNull(hwnd, L"Test window must be created");

            LRESULT result = 0;
            bool system_session_ending = false;
            bool handled = handle_stateless_session_end_message(
                hwnd, WM_ENDSESSION, TRUE, ENDSESSION_CLOSEAPP, result, &system_session_ending);

            Assert::IsTrue(handled, L"WM_ENDSESSION should be handled");
            Assert::IsFalse(system_session_ending,
                            L"ENDSESSION_CLOSEAPP must retain normal child-process cleanup");
            Assert::IsFalse(IsWindow(hwnd) == TRUE,
                            L"The window must still close for ENDSESSION_CLOSEAPP");

            UnregisterClassW(L"EndSessionTest_CloseApp", GetModuleHandleW(nullptr));
        }

TEST_METHOD(HandleStatelessSessionEndMessage_EndSessionCancelled_DoesNotSignalSystemSessionEnding)
        {
            // wparam == FALSE (another app vetoed) must not flag session-ending, so a
            // caller keeps doing its normal cleanup if it later closes on its own.
            LRESULT result = 0;
            bool system_session_ending = false;
            bool handled = handle_stateless_session_end_message(nullptr, WM_ENDSESSION, FALSE, 0, result, &system_session_ending);

            Assert::IsTrue(handled, L"WM_ENDSESSION should be handled");
            Assert::IsFalse(system_session_ending,
                            L"A cancelled shutdown must not flag the system session ending");
        }

TEST_METHOD(HandleStatelessSessionEndMessage_QueryEndSession_DoesNotSignalSystemSessionEnding)
        {
            // The query phase only asks permission; it must not flag teardown.
            LRESULT result = 0;
            bool system_session_ending = false;
            bool handled = handle_stateless_session_end_message(nullptr, WM_QUERYENDSESSION, 0, 0, result, &system_session_ending);

            Assert::IsTrue(handled, L"WM_QUERYENDSESSION should be handled");
            Assert::AreEqual(static_cast<LRESULT>(TRUE), result);
            Assert::IsFalse(system_session_ending,
                            L"WM_QUERYENDSESSION must not flag the system session ending");
        }

