static void secure_memset(void *v, int c, size_t n) {
    volatile unsigned char *p = (volatile unsigned char *)v;
    while (n--) {
        *p++ = (unsigned char)c;
    }
}

int ACLCheckAllPerm(client *c, pendingCommand *pcmd, int *idxptr) {
    /* The cached key result holds key positions within pcmd->argv, so it is only
     * usable for the command we are actually about to check. */
    serverAssert(!pcmd || (pcmd->cmd == c->cmd));
    return ACLCheckAllUserCommandPerm(c->user, c->cmd, c->argv, c->argc,
                getClientCachedKeyResult(pcmd), idxptr);

getKeysResult *getClientCachedKeyResult(pendingCommand *pcmd) {
    if (!pcmd) return NULL;
    serverAssert(pcmd->flags & PENDING_CMD_FLAG_PREPROCESSED);

    /* Return cached result if available */
    if (pcmd->flags & PENDING_CMD_KEYS_RESULT_VALID)
        return &pcmd->keys_result;

void createDumpPayload(rio *payload, robj *o, robj *key, int dbid, int flags, size_t size_hint) {
     * byte followed by the serialized object. This is understood by RESTORE.
     * 'size_hint', when non-zero, sizes the buffer to the caller's estimate of
     * the payload in a single allocation to avoid reallocations. */
    sds buffer;
    if (size_hint) {
        buffer = sdsnewlen(SDS_NOINIT, size_hint);
        sdssetlen(buffer, 0);
        buffer[0] = '\0';
    } else {
        buffer = sdsempty();
    }
    rioInitWithBuffer(payload,buffer);

    /* A DUMP payload is standalone: serialize objects self-contained (not ref
     * form), and skip LZF when the caller asked for raw bytes. */
    int prev_ref = rdbSaveSetRefMode(0);
    int prev_comp = server.rdb_compression;
    if (flags & DUMP_PAYLOAD_DONT_COMPRESS) server.rdb_compression = 0;
    server.rdb_compression = prev_comp;
    rdbSaveSetRefMode(prev_ref);

/* CRC-less, compression-less DUMP payload for RESTORE; returns an sds the caller
 * owns. size_hint (if nonzero) presizes. */
sds createRawDumpPayload(robj *o, robj *key, int dbid, int flags, size_t size_hint) {
    rio payload;
    createDumpPayload(&payload, o, key, dbid,
                      DUMP_PAYLOAD_SKIP_CHECKSUM | DUMP_PAYLOAD_DONT_COMPRESS | flags, size_hint);
    return payload.io.buffer.ptr;
}

    createDumpPayload(&payload,o,c->argv[1],c->db->id,0,0);
        createDumpPayload(&payload,kvArray[j],keyArray[j],dbid,0,0);

sds createRawDumpPayload(robj *o, robj *key, int dbid, int flags, size_t size_hint) {
    rio payload;
    createDumpPayload(&payload, o, key, dbid,
                      DUMP_PAYLOAD_SKIP_CHECKSUM | DUMP_PAYLOAD_DONT_COMPRESS | flags, size_hint);
    return payload.io.buffer.ptr;
}

void defragTmplArray(defragKeysCtx *ctx, kvobj *ob) {
    serverAssert(ob->type == OBJ_HASH && ob->encoding == OBJ_ENCODING_TMPL_ARRAY);
    hashTemplateArray *hta = ob->ptr, *newhta;
    if ((newhta = activeDefragAlloc(hta))) ob->ptr = hta = newhta;
    if (hta->field_count > server.active_defrag_max_scan_fields) {
        defragLater(ctx, ob);
    } else {
        for (unsigned long long i = 0; i < hta->field_count; i++) {
            sds newsds = activeDefragSds(hta->values[i]);
            if (newsds) hta->values[i] = newsds;
        }
    }
}

long scanLaterTmplArray(robj *ob, unsigned long *cursor, monotime endtime) {
    serverAssert(ob->type == OBJ_HASH && ob->encoding == OBJ_ENCODING_TMPL_ARRAY);
    hashTemplateArray *hta = ob->ptr;
    unsigned long long n = hta->field_count;
    long iterations = 0;
    while (*cursor < n) {
        sds newsds = activeDefragSds(hta->values[*cursor]);
        if (newsds) hta->values[*cursor] = newsds;
        server.stat_active_defrag_scanned++;
        (*cursor)++;
        if (++iterations > 128) {
            if (getMonotonicUs() > endtime) return 1;
            iterations = 0;
        }
    }
    *cursor = 0;
    return 0;
}

static doneStatus defragStageHashTemplates(void *ctx, monotime endtime) {
    unsigned long *cursor = ctx;
    hashTemplateRegistry *reg = server.htemplates;
    if (reg == NULL || reg->by_id == NULL) return DEFRAG_DONE;

    unsigned long iterations = 0;
    while (*cursor < reg->by_id_next) {
        hashTemplate *tmpl = hashTemplateGetById(*cursor);
        (*cursor)++;
        if (tmpl == NULL) continue; /* freed or never-used slot */

        hashTemplateDefrag(tmpl);

        if (++iterations > 64) {
            iterations = 0;
            if (getMonotonicUs() >= endtime) return DEFRAG_NOT_DONE;
        }
    }
    return DEFRAG_DONE;
}

static void defragTmplRegistryCb(void *privdata, const dictEntry *de, dictEntryLink plink) {
    UNUSED(privdata); 
    UNUSED(de);
    UNUSED(plink);
}

static doneStatus defragRegistryDict(dict **dref, unsigned long *cursor, monotime endtime) {
    dictDefragFunctions fns = { .defragAlloc = activeDefragAlloc };
    unsigned long iterations = 0;
    do {
        *cursor = dictScanDefrag(*dref, *cursor, defragTmplRegistryCb, &fns, NULL);
        if (++iterations > 64) {
            iterations = 0;
            if (getMonotonicUs() >= endtime) return DEFRAG_NOT_DONE;
        }
    } while (*cursor != 0);
    dict *newd = dictDefragTables(*dref);
    if (newd) *dref = newd;
    return DEFRAG_DONE;
}

static doneStatus defragStageHashTemplatesById(void *ctx, monotime endtime) {
    unsigned long *cursor = ctx;
    unsigned long iterations = 0;
    while (hashTemplateDefragByIdChunk(*cursor)) {
        (*cursor)++;
        if (++iterations > 64) {
            iterations = 0;
            if (getMonotonicUs() >= endtime) return DEFRAG_NOT_DONE;
        }
    }
    return DEFRAG_DONE;
}

static uint64_t lpEncodeEntries(listpackEntry *entries, unsigned int len,
                                struct listpackInsertEntry *enc)
{
    uint64_t addedlen = 0;
    for (unsigned int i = 0; i < len; i++) {
        listpackEntry *e = &entries[i];
        if (e->sval) {
           /* Calling lpEncodeGetType() results into the encoded version of the
            * element to be stored into 'intenc' in case it is representable as
            * an integer: in that case, the function returns LP_ENCODING_INT.
            * Otherwise, if LP_ENCODING_STR is returned, we'll have to call
            * lpEncodeString() to actually write the encoded string on place
            * later.
            *
            * Whatever the returned encoding is, 'enclen' is populated with the
            * length of the encoded element. */
            enc[i].enctype = lpEncodeGetType(e->sval, e->slen,
                                             enc[i].intenc, &enc[i].enclen);
        } else {
            enc[i].enctype = LP_ENCODING_INT;
            lpEncodeIntegerGetType(e->lval, enc[i].intenc, &enc[i].enclen);
        }
        addedlen += enc[i].enclen;

        /* We need to also encode the backward-parsable length of the element
         * and append it to the end: this allows to traverse the listpack from
         * the end to the start. */
        enc[i].backlen_size = lpEncodeBacklen(enc[i].backlen, enc[i].enclen);
        addedlen += enc[i].backlen_size;
    }
    return addedlen;
}

static unsigned char *lpWriteEntries(unsigned char *dst, listpackEntry *entries,
                                     struct listpackInsertEntry *enc,
                                     unsigned int len, unsigned char **newp)
{
    for (unsigned int i = 0; i < len; i++) {
        listpackEntry *ent = &entries[i];

        if (newp)
            *newp = dst;

        if (enc[i].enctype == LP_ENCODING_INT)
            memcpy(dst, enc[i].intenc, enc[i].enclen);
        else
            lpEncodeString(dst, ent->sval, ent->slen);

        dst += enc[i].enclen;
        memcpy(dst, enc[i].backlen, enc[i].backlen_size);
        dst += enc[i].backlen_size;
    }
    return dst;
}

unsigned char *lpNewWithEntries(listpackEntry *entries, unsigned int len) {
    assert(entries != NULL && len > 0);

    struct listpackInsertEntry tmp[LP_BATCH_STACK_ENTRIES];
    struct listpackInsertEntry *enc = tmp;
    if (len > sizeof(tmp) / sizeof(struct listpackInsertEntry))
        enc = zmalloc(len * sizeof(struct listpackInsertEntry));

    uint64_t entries_len = lpEncodeEntries(entries, len, enc);
    uint64_t listpack_bytes = LP_HDR_SIZE + entries_len + 1; /* +1 for EOF */
    if (listpack_bytes > UINT32_MAX) {
        if (enc != tmp) lp_free(enc);
        return NULL;
    }
    unsigned char *lp = lp_malloc(listpack_bytes);
    unsigned char *tail = lpWriteEntries(lp + LP_HDR_SIZE, entries, enc, len, NULL);
    *tail = LP_EOF;

    uint32_t num_elements = (len >= LP_HDR_NUMELE_UNKNOWN) ? LP_HDR_NUMELE_UNKNOWN : len;
    lpSetNumElements(lp, num_elements);
    lpSetTotalBytes(lp, listpack_bytes);
    if (enc != tmp) lp_free(enc);

    return lp;
}

int rdbSaveSetRefMode(int enable) {
    int prev = rdb_save_templates_as_ref;
    rdb_save_templates_as_ref = enable;
    return prev;
}

atic void rdbFreeSdsArray(sds *v, uint64_t count) {
    if (v == NULL) return;
    for (uint64_t i = 0; i < count; i++) sdsfree(v[i]);
    zfree(v);
}

atic sds *rdbLoadSdsArray(rio *rdb, uint64_t count, const char *ctx) {
    /* Grow as we read; don't pre-size to 'count' (untrusted: a corrupt huge
     * value would reserve gigabytes before reading any data). */
    sds *v = NULL;
    uint64_t cap = 0;
    for (uint64_t i = 0; i < count; i++) {
        if (i == cap) {
            uint64_t newcap = cap ? cap * 2 : 16;
            if (newcap > count) newcap = count;
            sds *nv = ztryrealloc(v, sizeof(sds) * newcap);
            if (nv == NULL) {
                rdbReportCorruptRDB("%s field count %llu too large",
                    ctx, (unsigned long long)count);
                rdbFreeSdsArray(v, i);
                return NULL;
            }
            v = nv;
            cap = newcap;
        }
        v[i] = rdbGenericLoadStringObject(rdb, RDB_LOAD_SDS, NULL);
        if (v[i] == NULL) {
            rdbFreeSdsArray(v, i);
            return NULL;
        }
    }
    return v;
}

atic int rdbEnsureHashTemplatesCap(uint64_t id) {
    size_t maxcap = SIZE_MAX / sizeof(*rdb_tmpls);
    if (id >= maxcap) {
        rdbReportCorruptRDB("Hash template ID %llu exceeds loader capacity",
            (unsigned long long)id);
        return C_ERR;
    }
    if (id < rdb_tmpls_cap)
        return C_OK;

    size_t needed = (size_t)id + 1;
    size_t newcap = rdb_tmpls_cap ? rdb_tmpls_cap : 16;
    if (newcap > maxcap)
        newcap = maxcap;
    while (newcap < needed) {
        if (newcap > maxcap / 2) {
            newcap = maxcap;
            break;
        }
        newcap *= 2;
    }

    /* A corrupt huge id fails. */
    uint64_t *newarr = ztryrealloc(rdb_tmpls, sizeof(*rdb_tmpls) * newcap);
    if (newarr == NULL) {
        rdbReportCorruptRDB("Hash template ID %llu requires too much memory "
            "(%zu entries)", (unsigned long long)id, newcap);
        return C_ERR;
    }
    rdb_tmpls = newarr;
    /* Set new slots with RDB_TMPL_EMPTY (UINT64_MAX). */
    memset(rdb_tmpls + rdb_tmpls_cap, 0xFF, sizeof(*rdb_tmpls) * (newcap - rdb_tmpls_cap));
    rdb_tmpls_cap = newcap;
    return C_OK;
}

t rdbLoadHashTemplate(rio *rdb) {
    uint64_t id, field_count;

    /* Read template ID. */
    if ((id = rdbLoadLen(rdb, NULL)) == RDB_LENERR)
        return C_ERR;

    /* Read field count. */
    if ((field_count = rdbLoadLen(rdb, NULL)) == RDB_LENERR)
        return C_ERR;

    /* A zero-field template is invalid. */
    if (field_count == 0) {
        rdbReportCorruptRDB("Hash template ID %llu has zero fields", (unsigned long long)id);
        return C_ERR;
    }

    if (rdbEnsureHashTemplatesCap(id) != C_OK)
        return C_ERR;
    if (rdb_tmpls[id] != RDB_TMPL_EMPTY) {
        rdbReportCorruptRDB("Duplicate hash template ID %llu", (unsigned long long)id);
        return C_ERR;
    }

    /* Read field names */
    sds *fields = rdbLoadSdsArray(rdb, field_count, "Hash template");
    if (fields == NULL) return C_ERR;

    /* Reject unsorted/duplicate fields; the template field lookup assumes them. */
    if (!hashTemplateValidateFields(fields, field_count)) {
        rdbReportCorruptRDB("Hash template fields not strictly sorted");
        for (uint64_t j = 0; j < field_count; j++) sdsfree(fields[j]);
        zfree(fields);
        return C_ERR;
    }

    /* Get or create template. */
    hashTemplate *tmpl = hashTemplateGetOrCreate(fields, field_count);
    hashTemplateIncrHoldRef(tmpl);
    rdb_tmpls[id] = tmpl->id;

    /* Free fields array */
    for (uint64_t j = 0; j < field_count; j++)
        sdsfree(fields[j]);
    zfree(fields);

    return C_OK;
}

id rdbClearHashTemplates(void) {
    if (!rdb_tmpls) return;
    for (size_t i = 0; i < rdb_tmpls_cap; i++) {
        if (rdb_tmpls[i] != RDB_TMPL_EMPTY)
            hashTemplateDecrHoldRef(hashTemplateGetById(rdb_tmpls[i]));
    }
    zfree(rdb_tmpls);
    rdb_tmpls = NULL;
    rdb_tmpls_cap = 0;
}

atic unsigned char *rdbLoadTmplLpBlob(rio *rdb, int deep, long long *id_out) {
    size_t encoded_len;
    unsigned char *lp = rdbGenericLoadStringObject(rdb, RDB_LOAD_PLAIN, &encoded_len);
    if (lp == NULL || encoded_len == 0) {
        zfree(lp);
        return NULL;
    }

    if (deep) server.stat_dump_payload_sanitizations++;
    if (!lpValidateIntegrity(lp, encoded_len, deep, NULL, NULL)) {
        rdbReportCorruptRDB("template-listpack integrity check failed.");
        zfree(lp);
        return NULL;
    }

    /* First entry is the saved-side template ID (must be an integer). */
    unsigned char *p = lpFirst(lp);
    if (p == NULL) {
        rdbReportCorruptRDB("template-listpack is empty.");
        zfree(lp);
        return NULL;
    }
    unsigned int vlen;
    long long vll;
    if (lpGetValue(p, &vlen, &vll) != NULL) {
        rdbReportCorruptRDB("template-listpack first entry is not an integer.");
        zfree(lp);
        return NULL;
    }
    if (id_out) *id_out = vll;
    return lp;
}

atic int rdbCheckTmplLpCount(unsigned char *lp, unsigned long long field_count) {
    if (lpLength(lp) == field_count + 1) return 1;
    rdbReportCorruptRDB("template-listpack entry count %lu does not match %llu fields",
                        (unsigned long)lpLength(lp), (unsigned long long)field_count);
    zfree(lp);
    return 0;
}

atic robj *rdbFinalizeTmplLp(unsigned char *lp, hashTemplate *tmpl) {
    unsigned char *p = lpFirst(lp);
    serverAssert(p != NULL);
    lp = lpReplaceInteger(lp, &p, (long long)tmpl->id);

    hashTemplateIncrKeyRef(tmpl);
    robj *o = createObject(OBJ_HASH, lp);
    o->encoding = OBJ_ENCODING_TMPL_LP;
    return o;
}

atic int rdbLoadTemplateFields(rio *rdb, int deep, rdbTmplFields *out) {
    *out = (rdbTmplFields) {0};

    uint64_t fmt = rdbLoadLen(rdb, NULL);
    if (fmt == RDB_LENERR) return C_ERR;

    if (fmt == 0) {
        /* FIELDS_LP: field names come as one listpack blob. Try a registry
         * lookup keyed by the blob first; only parse the fields if that misses. */
        size_t blen;
        unsigned char *blob = rdbGenericLoadStringObject(rdb, RDB_LOAD_PLAIN, &blen);
        if (blob == NULL) return C_ERR;

        if (blen == 0 || !lpValidateIntegrity(blob, blen, deep, NULL, NULL)) {
            rdbReportCorruptRDB("template field blob integrity check failed.");
            zfree(blob);
            return C_ERR;
        }
        /* Fast path: Lookup template with blob to avoid parsing the fields */
        hashTemplate *tmpl = hashTemplateGetByFieldsLp(blob);
        if (tmpl != NULL) {
            zfree(blob);
            out->tmpl = tmpl;
            out->field_count = tmpl->field_count;
            return C_OK;
        }
        /* Slow path: Parse the fields. Caller will lookup the template later. */
        uint64_t count = lpLength(blob);
        if (count == 0) {
            rdbReportCorruptRDB("template with zero fields");
            zfree(blob);
            return C_ERR;
        }
        sds *fields = count > SIZE_MAX / sizeof(sds) ?
                      NULL : ztrymalloc(sizeof(sds) * count);
        if (fields == NULL) {
            rdbReportCorruptRDB("template field count %llu too large", (unsigned long long)count);
            zfree(blob);
            return C_ERR;
        }
        unsigned char *p = lpFirst(blob);
        uint64_t i = 0;
        for (; i < count && p != NULL; i++) {
            unsigned int slen;
            long long lval;
            unsigned char *s = lpGetValue(p, &slen, &lval);
            fields[i] = s ? sdsnewlen(s, slen) : sdsfromlonglong(lval);
            p = lpNext(blob, p);
        }
        if (i != count || p != NULL) {
            rdbReportCorruptRDB("template field blob entry count mismatch");
            rdbFreeSdsArray(fields, i);
            zfree(blob);
            return C_ERR;
        }
        if (!hashTemplateValidateFields(fields, count)) {
            rdbReportCorruptRDB("template fields not strictly sorted");
            rdbFreeSdsArray(fields, count);
            zfree(blob);
            return C_ERR;
        }
        out->fields = fields;
        out->field_count = count;
        out->fields_lp = blob; /* attached on create; transfers ownership */
        return C_OK;
    }

    if (fmt == 1) {
        /* FIELDS_RAW: a field count, then that many field-name strings, one by
         * one. No blob to look up by, so the fields are always parsed. */
        uint64_t count = rdbLoadLen(rdb, NULL);
        if (count == RDB_LENERR) return C_ERR;
        if (count == 0) {
            rdbReportCorruptRDB("template with zero fields");
            return C_ERR;
        }
        sds *fields = rdbLoadSdsArray(rdb, count, "template fields");
        if (fields == NULL) return C_ERR;
        if (!hashTemplateValidateFields(fields, count)) {
            rdbReportCorruptRDB("template fields not strictly sorted");
            rdbFreeSdsArray(fields, count);
            return C_ERR;
        }
        out->fields = fields;
        out->field_count = count;
        return C_OK;
    }

    rdbReportCorruptRDB("unknown template fields format %llu", (unsigned long long)fmt);
    return C_ERR;
}

atic hashTemplate *rdbCreateTemplateFromFields(rdbTmplFields *out) {
    if (out->tmpl != NULL) return out->tmpl; /* registry hit */
    hashTemplate *tmpl = hashTemplateGetOrCreate(out->fields, out->field_count);
    rdbFreeSdsArray(out->fields, out->field_count);
    out->fields = NULL;
    if (out->fields_lp != NULL) {
        hashTemplateIndexFieldsLp(tmpl, out->fields_lp); /* transfers ownership */
        out->fields_lp = NULL;
    }
    return tmpl;
}

atic void rdbDiscardTemplateFields(rdbTmplFields *out) {
    if (out->fields) rdbFreeSdsArray(out->fields, out->field_count);
    if (out->fields_lp) zfree(out->fields_lp);
    out->fields = NULL;
    out->fields_lp = NULL;
}

t rdbLoadRioWithLoadingCtx(rio *rdb, int rdbflags, rdbSaveInfo *rsi, rdbLoadingCtx *rdb_loading_ctx) {
    /* Create the load-time conversion context (plain hash -> template hash), 
     * but only when load-time conversion config is enabled (min-entries > 0). 
     * It applies only to RDBs that have no templates and is freed as soon as a
     * template header is seen. */
    rdb_load_tmpl_ctx = (server.hash_rdb_load_min_template_entries > 0)
        ? rdbLoadTemplateCtxCreate(server.hash_rdb_load_template_disassembly_threshold)
        : NULL;

    int retval = rdbLoadRioWithLoadingCtxInternal(rdb, rdbflags, rsi, rdb_loading_ctx);

    /* On success, disassemble the templates that stayed few-key back to plain
     * hashes. Skip on failure: the partial dataset is discarded anyway. */
    if (retval == C_OK)
        rdbLoadTemplateCtxDisassemble(rdb_load_tmpl_ctx);
    rdbLoadTemplateCtxFree(rdb_load_tmpl_ctx);
    rdb_load_tmpl_ctx = NULL;

    rdbClearHashTemplates();
    return retval;
}

int sdscmplen(const sds s1, const sds s2) {
    size_t l1 = sdslen(s1);
    size_t l2 = sdslen(s2);
    if (l1 != l2) return (l1 > l2) ? 1 : -1;
    return memcmp(s1, s2, l1);
}

static void clusterFireTopologyChangeEventIfNeeded(void) {
    if (!server.cluster->topology_change_flags) return;

    /* No data payload beyond the change reasons: a subscribing module reads
     * whatever else it needs about the new topology via the cluster info module
     * APIs (CLUSTER SLOTS, RedisModule_GetClusterNodesList/NodeInfo,
     * RedisModule_GetClusterSize, ...). */
    RedisModuleClusterTopologyChangeInfo info = {
        .version = REDISMODULE_CLUSTER_TOPOLOGY_CHANGE_INFO_VERSION,
        .change_flags = server.cluster->topology_change_flags,
    };
    server.cluster->topology_change_flags = 0;
    moduleFireServerEvent(REDISMODULE_EVENT_CLUSTER_TOPOLOGY_CHANGE, 0, &info);
}

static void clusterTopologyCallback(RedisModuleCtx *ctx, RedisModuleEvent e,
                                    uint64_t subevent, void *data)
{
    REDISMODULE_NOT_USED(ctx);
    REDISMODULE_NOT_USED(subevent); /* Single subevent; reasons are in the data. */
    if (e.id != REDISMODULE_EVENT_CLUSTER_TOPOLOGY_CHANGE) return;

    RedisModuleClusterTopologyChangeInfo *info = data;
    event_count++;
    if (info->change_flags & REDISMODULE_CLUSTER_TOPOLOGY_CHANGE_FLAG_SLOT)
        slot_count++;
    if (info->change_flags & REDISMODULE_CLUSTER_TOPOLOGY_CHANGE_FLAG_ROLE)
        role_count++;
    if (info->change_flags & REDISMODULE_CLUSTER_TOPOLOGY_CHANGE_FLAG_STATE)
        state_count++;
    if (info->change_flags & REDISMODULE_CLUSTER_TOPOLOGY_CHANGE_FLAG_NODE)
        node_count++;
}

static int statsCommand(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
    REDISMODULE_NOT_USED(argv);
    if (argc != 1) return RedisModule_WrongArity(ctx);
    RedisModule_ReplyWithMap(ctx, 5);
    RedisModule_ReplyWithCString(ctx, "events");
    RedisModule_ReplyWithLongLong(ctx, event_count);
    RedisModule_ReplyWithCString(ctx, "slot");
    RedisModule_ReplyWithLongLong(ctx, slot_count);
    RedisModule_ReplyWithCString(ctx, "role");
    RedisModule_ReplyWithLongLong(ctx, role_count);
    RedisModule_ReplyWithCString(ctx, "state");
    RedisModule_ReplyWithLongLong(ctx, state_count);
    RedisModule_ReplyWithCString(ctx, "node");
    RedisModule_ReplyWithLongLong(ctx, node_count);
    return REDISMODULE_OK;
}

int RedisModule_OnLoad(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
    REDISMODULE_NOT_USED(argv);
    REDISMODULE_NOT_USED(argc);

    if (RedisModule_Init(ctx, "cluster_topology", 1, REDISMODULE_APIVER_1) == REDISMODULE_ERR)
        return REDISMODULE_ERR;

    if (RedisModule_SubscribeToServerEvent(ctx,
            RedisModuleEvent_ClusterTopologyChange, clusterTopologyCallback) == REDISMODULE_ERR)
        return REDISMODULE_ERR;

    if (RedisModule_CreateCommand(ctx, "cluster_topology.stats", statsCommand,
            "", 0, 0, 0) == REDISMODULE_ERR)
        return REDISMODULE_ERR;

    return REDISMODULE_OK;
}

static void executePostExecUnitJob(RedisModulePostExecUnitJob *job) {
    RedisModuleCtx ctx;
    moduleCreateContext(&ctx, job->module, REDISMODULE_CTX_TEMP_CLIENT);
    selectDb(ctx.client, job->dbid);

    if (job->key) {
        server.firing_keyed_post_notif_jobs = 1;
        job->cb.key_callback(&ctx, job->key, job->pd);
        server.firing_keyed_post_notif_jobs = 0;
        decrRefCount(job->key);
    } else {
        job->cb.callback(&ctx, job->pd);
    }
    if (job->free_pd) job->free_pd(job->pd);

    moduleFreeContext(&ctx);
    zfree(job);
}

ddPostNotificationJobForKey(RedisModuleCtx *ctx, RedisModulePostNotifyJobPerKeyFunc callback, RedisModuleString *key, void *privdata, void (*free_privdata)(void*)) {

    /* The API is only meaningful from inside a keyspace-notification handler:
     * that is the single-key context the per-key contract is scoped to. */
    if (!server.in_keyspace_notification) {
        serverLog(LL_WARNING,
            "API misuse detected in module %s: "
            "RedisModule_AddPostNotificationJobForKey called outside a "
            "keyspace-notification handler.",
            ctx->module->name);
        return REDISMODULE_ERR;
    }

    if (!callback || !key) {
      serverLog(LL_WARNING,
            "API misuse detected in module %s: "
            "RedisModule_AddPostNotificationJobForKey called with NULL callback or key.",
            ctx->module->name);
      return REDISMODULE_ERR;
    }

    RedisModulePostExecUnitJob *job = zmalloc(sizeof(*job));
    job->module = ctx->module;
    job->cb.key_callback = callback;
    job->key = key;
    incrRefCount(job->key);
    job->pd = privdata;
    job->free_pd = free_privdata;
    job->dbid = ctx->client->db->id;
    listAddNodeTail(modulePostExecUnitJobs, job);
    /* A per-key job (key != NULL) always fires between sub-commands and during
     * AOF replay - that is the meaning of choosing this API. Arm the hint that
     * gates the explicit drains in execCommand/scriptCall/AOF replay. */
    server.fire_keyed_jobs_between_subcommands = 1;
    return REDISMODULE_OK;
}

