void forkChildCallback(RedisModuleCtx *ctx, RedisModuleEvent e, uint64_t sub, void *data)
{
    REDISMODULE_NOT_USED(e);
    REDISMODULE_NOT_USED(data);

    /* All ForkChild subevents fire on the main thread in the parent process, so
     * logging into the in-module dict (rather than the keyspace) is safe. */
    char *keyname = NULL;
    switch (sub) {
        case REDISMODULE_SUBEVENT_FORK_CHILD_BORN:      keyname = "fork-child-born"; break;
        case REDISMODULE_SUBEVENT_FORK_CHILD_DIED:      keyname = "fork-child-died"; break;
        case REDISMODULE_SUBEVENT_FORK_CHILD_PRE:       keyname = "fork-child-pre"; break;
        case REDISMODULE_SUBEVENT_FORK_CHILD_CANCELLED: keyname = "fork-child-cancelled"; break;
    }
    if (keyname) LogNumericEvent(ctx, keyname, 0);

    /* A nested RM_Fork from within FORK_CHILD_PRE must be rejected. */
    if (sub == REDISMODULE_SUBEVENT_FORK_CHILD_PRE) assert(RedisModule_Fork(NULL, NULL) == -1);
}

static int raxLinkStillValid(rax *rax, unsigned char *s, size_t len, raxNodeLink *link) {
    raxNode *stopnode, **parentlink;
    int splitpos = 0;
    size_t consumed = raxLowWalk(rax,s,len,&stopnode,&parentlink,&splitpos,NULL);
    return stopnode == link->stopnode &&
           parentlink == link->parentlink &&
           consumed == link->consumed &&
           splitpos == link->splitpos;
}

int raxFindLink(rax *rax, unsigned char *s, size_t len,
                void **value, raxNodeLink *link) {
    debugf("### FindLink: %.*s\n", (int)len, s);
    link->splitpos = 0;
    link->consumed = raxLowWalk(rax,s,len,
                         &link->stopnode,&link->parentlink,
                         &link->splitpos,NULL);
    /* Match condition: query fully consumed, stopped at a clean node
     * boundary (not mid-prefix on a compressed node), and the stop node
     * is a key. */
    if (link->consumed != len ||
        (link->stopnode->iscompr && link->splitpos != 0) ||
        !link->stopnode->iskey)
        return 0;
    if (value != NULL) *value = raxGetData(link->stopnode);
    return 1;
}

static bool cbm_path_is_razor(const char *rel_path) {
    if (!rel_path) {
        return false;
    }
    size_t len = strlen(rel_path);
    static const char suffix[] = ".razor";
    size_t slen = sizeof(suffix) - 1U;
    return len > slen && strcmp(rel_path + (len - slen), suffix) == 0;
}

atic const char *razor_page_route_on_line(CBMArena *a, const char *line, const char *line_end) {
    static const char directive[] = "@page";
    const size_t dlen = sizeof(directive) - 1U;

    const char *p = line;
    while (p < line_end && (*p == ' ' || *p == '\t')) {
        p++;
    }
    if (p == line_end) {
        return NULL; /* blank line — nothing can follow */
    }
    if ((size_t)(line_end - p) <= dlen || strncmp(p, directive, dlen) != 0) {
        return NULL;
    }
    p += dlen;
    if (*p != ' ' && *p != '\t') {
        return NULL; /* `@pageSize` and friends */
    }
    while (p < line_end && (*p == ' ' || *p == '\t')) {
        p++;
    }
    if (p == line_end || *p != '"') {
        return NULL;
    }
    p++;
    const char *route = p;
    while (p < line_end && *p != '"') {
        p++;
    }
    if (p == line_end || p == route || *route != '/') {
        return NULL; /* unterminated, empty, or not a rooted path */
    }
    return cbm_arena_strndup(a, route, (size_t)(p - route));
}

