TEST(gbuf_edge_props_unreadable_confidence_does_not_displace_absent) {
    const char *no_conf = "{\"callee\":\"f\",\"strategy\":\"lsp\"}";
    const char *bad_conf = "{\"callee\":\"f\",\"confidence\":null,\"strategy\":\"registry\"}";

    cbm_gbuf_t *gb = cbm_gbuf_new("test", "/tmp");
    int64_t a = cbm_gbuf_upsert_node(gb, "Function", "a", "pkg.a", "f.go", 1, 5, "{}");
    int64_t b = cbm_gbuf_upsert_node(gb, "Function", "b", "pkg.b", "f.go", 6, 10, "{}");
    cbm_gbuf_insert_edge(gb, a, b, "CALLS", no_conf);
    cbm_gbuf_insert_edge(gb, a, b, "CALLS", bad_conf); /* unreadable, arrives last */

    const cbm_gbuf_edge_t **edges = NULL;
    int count = 0;
    cbm_gbuf_find_edges_by_type(gb, "CALLS", &edges, &count);
    ASSERT_EQ(count, 1);
    ASSERT_TRUE(strstr(edges[0]->properties_json, "\"strategy\":\"lsp\"") != NULL);

    cbm_gbuf_free(gb);
    PASS();
}

TEST(tool_trace_path_unreadable_confidence_reports_not_recorded) {
    cbm_mcp_server_t *srv = cbm_mcp_server_new(NULL);
    cbm_store_t *st = cbm_mcp_server_store(srv);
    const char *proj = "badconf-proj";
    cbm_mcp_server_set_project(srv, proj);
    cbm_store_upsert_project(st, proj, "/tmp/badconf");
    cbm_node_t caller = {.project = proj,
                         .label = "Function",
                         .name = "caller",
                         .qualified_name = "badconf-proj.src.caller",
                         .file_path = "src/a.c",
                         .start_line = 1,
                         .end_line = 5};
    cbm_node_t callee = {.project = proj,
                         .label = "Function",
                         .name = "target",
                         .qualified_name = "badconf-proj.src.target",
                         .file_path = "src/a.c",
                         .start_line = 10,
                         .end_line = 20};
    int64_t id_caller = cbm_store_upsert_node(st, &caller);
    int64_t id_callee = cbm_store_upsert_node(st, &callee);
    ASSERT_GT(id_caller, 0);
    ASSERT_GT(id_callee, 0);
    /* The strategy reads fine; only the confidence is malformed. */
    cbm_edge_t e = {.project = proj,
                    .source_id = id_caller,
                    .target_id = id_callee,
                    .type = "CALLS",
                    .properties_json = "{\"callee\":\"target\",\"confidence\":null,"
                                       "\"strategy\":\"lsp_trait_dispatch\",\"candidates\":1}"};
    ASSERT_GT(cbm_store_insert_edge(st, &e), 0);

    char *ev = cbm_mcp_server_handle(
        srv, "{\"jsonrpc\":\"2.0\",\"id\":93,\"method\":\"tools/call\","
             "\"params\":{\"name\":\"trace_path\",\"arguments\":{\"function_name\":\"caller\","
             "\"project\":\"badconf-proj\",\"direction\":\"outbound\",\"include_evidence\":true}}}");
    ASSERT_NOT_NULL(ev);
    char *ev_txt = extract_text_content(ev);
    ASSERT_NOT_NULL(ev_txt);
    /* Positive controls: the hop and its readable class still come through, so
     * a failure below is about the confidence and not a broken request. */
    ASSERT_NOT_NULL(strstr(ev_txt, "target"));
    ASSERT_NOT_NULL(strstr(ev_txt, "lsp"));
    /* The claim: an unreadable confidence is never published as 0.00. */
    ASSERT_NULL(strstr(ev_txt, "0.00"));
    free(ev_txt);
    free(ev);

    cbm_mcp_server_free(srv);
    PASS();
}

TEST(cypher_parse_rejects_trailing_tokens) {
    cbm_query_t *q = NULL;
    char *err = NULL;
    int rc = cbm_cypher_parse("MATCH (f:Function) RETURN f.name AS n BANANA SPLIT 99", &q, &err);
    ASSERT_NEQ(rc, 0);
    ASSERT_NOT_NULL(err);
    ASSERT_NULL(q);

    /* The message must name what actually stopped the parse, and must not
     * mention WITH: this query has no WITH in it anywhere. */
    ASSERT(strstr(err, "BANANA") != NULL);
    ASSERT(strstr(err, "WITH") == NULL);

    free(err);
    PASS();
}

ST(cypher_parse_rejects_second_with_clause) {
    cbm_query_t *q = NULL;
    char *err = NULL;
    int rc = cbm_cypher_parse("MATCH (f:Function) "
                              "OPTIONAL MATCH (a)-[:CALLS]->(f) "
                              "WITH f, count(a) AS calls "
                              "OPTIONAL MATCH (b)-[:USAGE]->(f) "
                              "WITH f, calls, count(b) AS usages "
                              "WHERE calls = 0 AND usages = 0 "
                              "RETURN f.name AS n",
                              &q, &err);
    ASSERT_NEQ(rc, 0);
    ASSERT_NOT_NULL(err);
    ASSERT_NULL(q);

    /* Here the note earns its place. The parse stops at OPTIONAL, and the
     * reason is the second WITH further along, which the reader cannot see
     * from the stopping point alone. */
    ASSERT(strstr(err, "only one WITH clause is supported") != NULL);

    free(err);
    PASS();
}

ST(cypher_parse_accepts_single_with_clause) {
    cbm_query_t *q = NULL;
    char *err = NULL;
    int rc = cbm_cypher_parse("MATCH (f:Function) "
                              "WITH f, f.name AS n "
                              "WHERE n = 'buildTree' "
                              "RETURN n",
                              &q, &err);
    ASSERT_EQ(rc, 0);
    ASSERT_NULL(err);
    ASSERT_NOT_NULL(q);

    cbm_query_free(q);
    PASS();
}

bool chialisp_head_is_not_call(const char *t) {
    if (!t) {
        return true;
    }
    static const char *filtered[] = {
        /* --- CLVM primitives (VM ops) --- */
        "q", "a", "i", "c", "f", "r", "l", "x", "=", ">s", "sha256", "substr", "strlen", "concat",
        "+", "-", "*", "/", "divmod", ">", "ash", "lsh", "logand", "logior", "logxor", "lognot",
        "point_add", "pubkey_for_exp", "not", "any", "all", "softfork", "coinid", "g1_subtract",
        "g1_multiply", "g1_negate", "g2_add", "g2_subtract", "g2_multiply", "g2_negate", "g1_map",
        "g2_map", "bls_pairing_identity", "bls_verify", "modpow", "%", "secp256k1_verify",
        "secp256r1_verify", "keccak256",
        /* --- Chialisp syntax / binding / intrinsics (not calls or defs) --- */
        "quote", "qq", "unquote", "&rest", "let", "let*", "assign", "assign-inline",
        "assign-lambda", "lambda", "mod", "if", "list", "com", "opt", "@", "@*env*", "print",
        /* --- def / export / include heads (never a call) --- */
        "defun", "defun-inline", "defmacro", "defmac", "defconstant", "defconst", "namespace",
        "export", "embed-file", "compile-file", "include", NULL};
    for (int i = 0; filtered[i]; i++) {
        if (strcmp(t, filtered[i]) == 0) {
            return true;
        }
    }
    return false;
}

/* T

l chialisp_node_is_binder_list(CBMArena *a, TSNode node, const char *source) {
    /* At most two levels: the binder itself, and one binding pair inside a
     * `let` binding container. Bounded on purpose — never an ancestor walk. */
    for (int level = 0; level < 2; level++) {
        TSNode parent = ts_node_parent(node);
        if (ts_node_is_null(parent) || strcmp(ts_node_type(parent), "list") != 0) {
            return false;
        }
        TSNode head = cbm_lisp_named_child_skip_comments(parent, 0);
        if (!ts_node_is_null(head) && strcmp(ts_node_type(head), "symbol") == 0) {
            char *ht = cbm_node_text(a, head, source);
            if (!ht) {
                return false;
            }
            /* `(defun NAME (params) ...)` — the params are the third form. */
            if (strcmp(ht, "defun") == 0 || strcmp(ht, "defun-inline") == 0 ||
                strcmp(ht, "defmacro") == 0 || strcmp(ht, "defmac") == 0) {
                TSNode params = cbm_lisp_named_child_skip_comments(parent, 2);
                return !ts_node_is_null(params) && ts_node_eq(params, node);
            }
            /* `(mod (ARGS) ...)`, `(lambda (x) ...)`, `(let ((a 1)) ...)`. */
            if (strcmp(ht, "mod") == 0 || strcmp(ht, "lambda") == 0 || strcmp(ht, "let") == 0 ||
                strcmp(ht, "let*") == 0) {
                TSNode binder = cbm_lisp_named_child_skip_comments(parent, 1);
                return !ts_node_is_null(binder) && ts_node_eq(binder, node);
            }
            return false;
        }
        /* The head is not a symbol, so `parent` may itself be a let-binding
         * container and `node` one of its pairs — retry one level up. */
        node = parent;
    }
    return false;
}

static char *e

is_exempt(CBMExtractCtx *ctx, TSNode receiver) {
    if (ts_node_is_null(receiver)) {
        return false;
    }

    /* super().m() — the receiver is a call node whose function is `super`. */
    if (strcmp(ts_node_type(receiver), "call") == 0) {
        TSNode fn = ts_node_child_by_field_name(receiver, TS_FIELD("function"));
        if (!ts_node_is_null(fn) && strcmp(ts_node_type(fn), "identifier") == 0) {
            char *name = cbm_node_text(ctx->arena, fn, ctx->source);
            return name && strcmp(name, "super") == 0;
        }
        return false;
    }

    /* Walk an attribute chain down to its root identifier: for `pkg.sub.fn()`
     * the receiver is `pkg.sub`, whose root is `pkg` — the name an import binds. */
    bool direct_identifier = strcmp(ts_node_type(receiver), "identifier") == 0;
    TSNode root = receiver;
    while (!ts_node_is_null(root) && strcmp(ts_node_type(root), "attribute") == 0) {
        root = ts_node_child_by_field_name(root, TS_FIELD("object"));
    }
    if (ts_node_is_null(root) || strcmp(ts_node_type(root), "identifier") != 0) {
        return false;
    }

    char *name = cbm_node_text(ctx->arena, root, ctx->source);
    if (!name) {
        return false;
    }
    /* self/cls only as a DIRECT receiver: `self.m()` is class-local, but
     * `self.client.m()` has receiver `self.client` of unknown type. */
    if (direct_identifier && (strcmp(name, "self") == 0 || strcmp(name, "cls") == 0)) {
        return true;
    }
    /* Import-bound root, incl. aliases (`import tools as toolkit` binds
     * local_name "toolkit"). Per-file scan: imports.count is a file-local
     * number (tens), never the corpus, so this stays O(file), not O(corpus). */
    for (int i = 0; i < ctx->result->imports.count; i++) {
        const char *local_name = ctx->result->imports.items[i].local_name;
        if (local_name && strcmp(local_name, name) == 0) {
            return true;
        }
    }
    return false;
}

            // Python receiver

size_t utf8_sequence_len(unsigned char lead) {
    if ((lead & UTF8_LEAD2_MASK) == UTF8_LEAD2_MARK) {
        return UTF8_LEN_2;
    }
    if ((lead & UTF8_LEAD3_MASK) == UTF8_LEAD3_MARK) {
        return UTF8_LEN_3;
    }
    if ((lead & UTF8_LEAD4_MASK) == UTF8_LEAD4_MARK) {
        return UTF8_LEN_4;
    }
    return UTF8_LEN_1;
}

/* D

void utf8_trim_partial_tail(char *text) {
    size_t n = strlen(text);
    if (n == 0) {
        return;
    }
    size_t i = n;
    while (i > 0 && ((unsigned char)text[i - UTF8_LEN_1] & UTF8_CONT_MASK) == UTF8_CONT_MARK) {
        i--;
    }
    if (i == 0) {
        text[0] = '\0'; /* continuation bytes only — not decodable */
        return;
    }
    size_t need = utf8_sequence_len((unsigned char)text[i - UTF8_LEN_1]);
    if (i - UTF8_LEN_1 + need > n) {
        text[i - UTF8_LEN_1] = '\0';
    }
}

/* Col

har *collapse_prose(CBMArena *a, const char *src, size_t len) {
    if (!src || len == 0) {
        return NULL;
    }
    char *out = (char *)cbm_arena_alloc(a, MAX_COMMENT_LEN + NULL_TERM);
    if (!out) {
        return NULL;
    }
    size_t w = 0;
    bool in_ws = true; /* start true so leading whitespace is swallowed */
    for (size_t i = 0; i < len && w < MAX_COMMENT_LEN; i++) {
        unsigned char c = (unsigned char)src[i];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
            in_ws = true;
            continue;
        }
        if (in_ws && w > 0) {
            out[w++] = ' ';
            if (w >= MAX_COMMENT_LEN) {
                break;
            }
        }
        in_ws = false;
        out[w++] = (char)c;
    }
    out[w] = '\0';
    utf8_trim_partial_tail(out);
    return out[0] ? out : NULL;
}

static

ool is_markdown_heading_kind(const char *kind) {
