// Extract

p_path_stem(CBMArena *a, const char *path) {
    if (!path) {
        return NULL;
    }
    const char *slash = strrchr(path, '/');
    const char *base = slash ? slash + SKIP_CHAR : path;
    const char *dot = strrchr(base, '.');
    size_t len = (dot && dot != base) ? (size_t)(dot - base) : strlen(base);
    return cbm_arena_strndup(a, base, len);
}

    bool chial

bool cbm_lisp_node_in_quote(CBMArena *a, TSNode node, const char *source) {
    TSNode cur = ts_node_parent(node);
    for (int guard = 0; guard < CBM_LISP_QUOTE_ANCESTOR_MAX && !ts_node_is_null(cur); guard++) {
        const char *ck = ts_node_type(cur);
        if ((strcmp(ck, "list") == 0 || strcmp(ck, "list_lit") == 0) &&
            ts_node_named_child_count(cur) > 0) {
            TSNode h = ts_node_named_child(cur, 0);
            const char *hk = ts_node_type(h);
            if (strcmp(hk, "symbol") == 0 || strcmp(hk, "sym_lit") == 0) {
                char *ht = cbm_node_text(a, h, source);
                if (ht &&
                    (strcmp(ht, "q") == 0 || strcmp(ht, "quote") == 0 || strcmp(ht, "qq") == 0)) {
                    return true;
                }
            }
        }
        cur = ts_node_parent(cur);
    }
    return false;
}

TSNode cbm_lisp_named_child_skip_comments(TSNode node, uint32_t want) {
    uint32_t nc = ts_node_named_child_count(node);
    uint32_t seen = 0;
    for (uint32_t i = 0; i < nc; i++) {
        TSNode c = ts_node_named_child(node, i);
        if (strcmp(ts_node_type(c), "comment") == 0) {
            continue;
        }
        if (seen == want) {
            return c;
        }
        seen++;
    }
    TSNode null_node = {0};
    return null_node;
}

bool cbm_chialisp_is_def_head(const char *t) {
    if (!t) {
        return false;
    }
    /* `export` and `namespace` are absent ON PURPOSE. `(export foo)` re-exports
     * a function `(defun foo ...)` already defined in the same file, so
     * admitting it here mints a SECOND node for the same symbol. They stay in
     * the not-a-call filter (extract_calls.c) because they are still not calls.
     */
    static const char *heads[] = {"mod",          "defun",       "defun-inline", "defmacro",
                                  "defmac",       "defconstant", "defconst",     "embed-file",
                                  "compile-file", NULL};
    for (int i = 0; heads[i]; i++) {
        if (strcmp(t, heads[i]) == 0) {
            return true;
        }
    }
    return false;

static bool ts_lex(TSLexer *lexer, TSStateId state) {
  START_LEXER();
  eof = lexer->eof(lexer);
  switch (state) {
    case 0:
      if (eof) ADVANCE(5);
      ADVANCE_MAP(
        '"', 1,
        '\'', 2,
        '(', 6,
        ')', 7,
        '-', 14,
        '.', 13,
        '0', 10,
        ';', 8,
      );
      if (('\t' <= lookahead && lookahead <= '\r') ||
          lookahead == ' ') SKIP(0);
      if (('1' <= lookahead && lookahead <= '9')) ADVANCE(11);
      if (lookahead != 0) ADVANCE(16);
      END_STATE();
    case 1:
      if (lookahead == '"') ADVANCE(12);
      if (lookahead == '\\') ADVANCE(3);
      if (lookahead != 0) ADVANCE(1);
      END_STATE();
    case 2:
      if (lookahead == '\'') ADVANCE(12);
      if (lookahead == '\\') ADVANCE(4);
      if (lookahead != 0) ADVANCE(2);
      END_STATE();
    case 3:
      if (lookahead != 0 &&
          lookahead != '\n') ADVANCE(1);
      END_STATE();
    case 4:
      if (lookahead != 0 &&
          lookahead != '\n') ADVANCE(2);
      END_STATE();
    case 5:
      ACCEPT_TOKEN(ts_builtin_sym_end);
      END_STATE();
    case 6:
      ACCEPT_TOKEN(anon_sym_LPAREN);
      END_STATE();
    case 7:
      ACCEPT_TOKEN(anon_sym_RPAREN);
      END_STATE();
    case 8:
      ACCEPT_TOKEN(sym_comment);
      if (lookahead != 0 &&
          lookahead != '\n' &&
          lookahead != '\r') ADVANCE(8);
      END_STATE();
    case 9:
      ACCEPT_TOKEN(sym_hex);
      if (('0' <= lookahead && lookahead <= '9') ||
          ('A' <= lookahead && lookahead <= 'F') ||
          ('a' <= lookahead && lookahead <= 'f')) ADVANCE(9);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    case 10:
      ACCEPT_TOKEN(sym_number);
      if (lookahead == 'X' ||
          lookahead == 'x') ADVANCE(15);
      if (('0' <= lookahead && lookahead <= '9')) ADVANCE(11);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    case 11:
      ACCEPT_TOKEN(sym_number);
      if (('0' <= lookahead && lookahead <= '9')) ADVANCE(11);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    case 12:
      ACCEPT_TOKEN(sym_string);
      END_STATE();
    case 13:
      ACCEPT_TOKEN(sym_dot);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    case 14:
      ACCEPT_TOKEN(sym_symbol);
      if (('0' <= lookahead && lookahead <= '9')) ADVANCE(11);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    case 15:
      ACCEPT_TOKEN(sym_symbol);
      if (('0' <= lookahead && lookahead <= '9') ||
          ('A' <= lookahead && lookahead <= 'F') ||
          ('a' <= lookahead && lookahead <= 'f')) ADVANCE(9);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    case 16:
      ACCEPT_TOKEN(sym_symbol);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    default:
      return false;
  }
}

scope_holds(const char *const *names, int count, const char *want) {
    for (int i = 0; i < count; i++) {
        if (names[i] && strcmp(names[i], want) == 0) {
            return true;
        }
    }
    return false;
}

/* Every n

ollect_declared_names(const cbm_query_t *q, const char **out, int cap) {
    int n = 0;
    for (int pi = 0; pi < q->pattern_count; pi++) {
        const cbm_pattern_t *pat = &q->patterns[pi];
        for (int ni = 0; ni < pat->node_count; ni++) {
            const char *var = pat->nodes[ni].variable;
            if (var && !scope_holds(out, n, var)) {
                if (n >= cap) {
                    return -1;
                }
                out[n++] = var;
            }
        }
        for (int ri = 0; ri < pat->rel_count; ri++) {
            const char *var = pat->rels[ri].variable;
            if (var && !scope_holds(out, n, var)) {
                if (n >= cap) {
                    return -1;
                }
                out[n++] = var;
            }
        }
    }
    if (q->unwind_alias && !scope_holds(out, n, q->unwind_alias)) {
        if (n >= cap) {
            return -1;
        }
        out[n++] = q->unwind_alias;
    }
    return n;
}

/* What a

lect_with_names(const cbm_return_clause_t *wc, const char **out, int cap) {
    int n = 0;
    for (int i = 0; i < wc->count; i++) {
        const cbm_return_item_t *item = &wc->items[i];
        const char *name = NULL;
        if (item->alias) {
            name = item->alias;
        } else if (item->variable && !item->property && !item->func) {
            name = item->variable;
        }
        if (name && !scope_holds(out, n, name)) {
            if (n >= cap) {
                return -1;
            }
            out[n++] = name;
        }
    }
    return n;
}

/* Build the

cope_error(const char *var, const char *clause, const char *why) {
    char buf[CBM_SZ_256];
    snprintf(buf, sizeof(buf), "variable '%s' is not in scope for %s — %s", var, clause, why);
    return heap_strdup(buf);
}

/* The variabl

r *scope_checkable_var(const cbm_return_item_t *item) {
    if (item->kase || !item->variable) {
        return NULL;
    }
    if (strcmp(item->variable, "*") == 0) {
        return NULL;
    }
    return item->variable;
}

/* Answers NUL

ck_projection_scope(const cbm_query_t *q) {
    const char *declared[CYP_SCOPE_MAX_NAMES];
    int declared_n = collect_declared_names(q, declared, CYP_SCOPE_MAX_NAMES);
    if (declared_n < 0) {
        return NULL; /* too many names to model — stay quiet rather than guess */
    }

    /* A WITH still reads the pattern variables. */
    if (q->with_clause && !q->with_clause->star) {
        for (int i = 0; i < q->with_clause->count; i++) {
            const char *var = scope_checkable_var(&q->with_clause->items[i]);
            if (var && !scope_holds(declared, declared_n, var)) {
                return scope_error(var, "WITH", "no pattern in this query names it");
            }
        }
    }

    if (!q->ret || q->ret->star) {
        return NULL;
    }

    /* A RETURN after a WITH reads only what the WITH left behind. */
    const char *after_with[CYP_SCOPE_MAX_NAMES];
    const char *const *scope = declared;
    int scope_n = declared_n;
    if (q->with_clause) {
        scope_n = collect_with_names(q->with_clause, after_with, CYP_SCOPE_MAX_NAMES);
        if (scope_n < 0) {
            return NULL;
        }
        scope = after_with;
    }

    for (int i = 0; i < q->ret->count; i++) {
        const char *var = scope_checkable_var(&q->ret->items[i]);
        if (var && !scope_holds(scope, scope_n, var)) {
            return scope_error(var, "RETURN",
                               q->with_clause ? "the WITH clause did not carry it through"
                                              : "no pattern in this query names it");
        }
    }
    return NULL;
}

