    }
    char detail[CBM_SZ_256] = "";
    if (!db_hashes_match_disk(repo_path, db_path, project_name, detail, sizeof(detail))) {
        snprintf(g_basis_blocker, sizeof(g_basis_blocker), "db_hashes_differ_from_disk %s", detail);
        return false;
    }
    return true;
}

