    sqlite3_stmt *relink = NULL;
    if (sqlite3_prepare_v2(db,
                           "INSERT OR IGNORE INTO edges (project, source_id, target_id,"
                           " type, properties)"
                           " SELECT ?1, s.id, t.id, ?2, ?3 FROM nodes s, nodes t"
                           " WHERE s.project = ?1 AND s.qualified_name = ?4"
                           " AND t.project = ?1 AND t.qualified_name = ?5",
                           CBM_NOT_FOUND, &relink, NULL) != SQLITE_OK) {
        return false;
    }
    bool ok = true;
    for (int i = 0; i < snapshot_count && ok; i++) {
        sqlite3_reset(relink);
        sqlite3_bind_text(relink, DELTA_BIND_1, project, CBM_NOT_FOUND, DELTA_SQLITE_TRANSIENT);
        sqlite3_bind_text(relink, DELTA_BIND_2, snapshot[i].type, CBM_NOT_FOUND,
                          DELTA_SQLITE_TRANSIENT);
        sqlite3_bind_text(relink, DELTA_BIND_3, snapshot[i].props, CBM_NOT_FOUND,
                          DELTA_SQLITE_TRANSIENT);
        sqlite3_bind_text(relink, DELTA_BIND_4, snapshot[i].source_qn, CBM_NOT_FOUND,
                          DELTA_SQLITE_TRANSIENT);
        sqlite3_bind_text(relink, DELTA_BIND_5, snapshot[i].target_qn, CBM_NOT_FOUND,
                          DELTA_SQLITE_TRANSIENT);
        ok = sqlite3_step(relink) == SQLITE_DONE;
    }
    sqlite3_finalize(relink);
    return ok;
}

bool c_cpp_family(CBMLanguage lang) {
    return lang == CBM_LANG_C || lang == CBM_LANG_CPP;
}

bool

bm_suppress_cross_language_ref(CBMLanguage caller_lang, const char *target_file_path) {
    /* #1928: USAGE / WRITES / READS analog of the CALLS guard above. A
     * variable or field reference resolved by the short-name registry must
     * not cross a language boundary: unlike CALLS, a reference edge carries
     * no import-closure evidence at all — a Go test's local `event` and an
     * eBPF C probe's automatic `event` share nothing but the spelling, so
     * EVERY registry strategy is a bare-name guess here and none is exempt.
     * LSP-backed semantic references resolve before the registry fallback
     * and never reach this predicate, which is where a genuine cross-language
     * binding (a future cgo resolver) would live. The JS/TS family keeps its
     * exemption (.js/.ts/.d.ts pairs legitimately share symbols), and C/C++
     * count as one family (.h maps to CBM_LANG_CPP). */
    if (caller_lang == CBM_LANG_COUNT || !target_file_path || !target_file_path[0]) {
        return false;
    }
    CBMLanguage target_lang = cbm_language_for_filename(path_basename(target_file_path));
    if (target_lang == CBM_LANG_COUNT) {
        return false;
    }
    if (caller_lang == target_lang) {
        return false;
    }
    if (js_ts_family(caller_lang) && js_ts_family(target_lang)) {
        return false;
    }
    if (c_cpp_family(caller_lang) && c_cpp_family(target_lang)) {
        return false;
    }
    return true;
}

bool c

_go_suppress_bare_field_ref(bool is_go, const char *ref_name, const char *target_label) {
    /* #1942: a bare (dot-less) Go reference can never denote a struct field —
     * field access is always a selector expression (x.f), and selector
     * references resolve through the LSP join, never through the bare-name
     * registry fallback. Every Field-targeted reference edge in the field
     * census carried dot-less text, so dropping the bind loses nothing real.
     * Go-gated: a C#/Java/C++/Python method body legitimately references its
     * own members bare (cp_reads_writes_cs_static_field pins that shape as
     * required), so a global veto would break those languages. */
    if (!is_go || !ref_name || !ref_name[0] || !target_label) {
        return false;
    }
    if (strcmp(target_label, "Field") != 0) {
        return false;
    }
    return strchr(ref_name, '.') == NULL;
}

bool camel) {
    char sql[FTS_SQL_BUF];
    int n = snprintf(sql, sizeof(sql),
                     "INSERT INTO nodes_fts (rowid, name, qualified_name, label, file_path%s)"
                     " SELECT id, %s, qualified_name, label, file_path%s FROM nodes%s;",
                     with_body ? ", body" : "", camel ? "cbm_camel_split(name)" : "name",
                     with_body ? ", " FTS_BODY_EXPR : "",
                     project ? " WHERE project = ?1 AND id > ?2" : "");
    if (n <= 0 || (size_t)n >= sizeof(sql)) {
        return CBM_STORE_ERR;
    }
    sqlite3_stmt *stmt = NULL;
    if (sqlite3_prepare_v2(s->db, sql, CBM_NOT_FOUND, &stmt, NULL) != SQLITE_OK) {
        return CBM_STORE_NOT_FOUND;
    }
    if (project) {
        sqlite3_bind_text(stmt, ST_COL_1, project, CBM_NOT_FOUND, BIND_TRANSIENT);
        sqlite3_bind_int64(stmt, ST_COL_2, after_id);
    }
    int rc = sqlite3_step(stmt) == SQLITE_DONE ? CBM_STORE_OK : CBM_STORE_ERR;
    if (rc != CBM_STORE_OK) {
        store_set_error_sqlite(s, "fts_backfill");
    }
    sqlite3_finalize(stmt);
    return rc;
}

int cbm_store_fts_rebuild(cbm_store_t *s, const char *project, int64_t after_id) {
    if (!s || !s->db) {

return CBM_STORE_ERR;
    }
    /* Wholesale only: the incremental caller adds rows to a live index. */
    if (!project &&
        exec_sql(s, "INSERT INTO nodes_fts(nodes_fts) VALUES('delete-all');") != CBM_STORE_OK) {
        return CBM_STORE_ERR;
    }
    /* Degrade one capability at a time, widest first.  Dropping `body` covers a
     * legacy four-column table or a build without JSON1; dropping
     * cbm_camel_split covers a connection where the function is not registered
     * (the pre-existing fallback).  Each attempt is a single statement, so a
     * failed one rolls itself back before the next runs. */
    const bool with_body = fts_has_body_column(s);
    const struct {
        bool body;
        bool camel;
    } ladder[] = {{true, true}, {true, false}, {false, true}, {false, false}};
    int rc = CBM_STORE_NOT_FOUND;
    for (size_t i = 0; i < sizeof(ladder) / sizeof(ladder[0]); i++) {
        if (ladder[i].body && !with_body) {
            continue;
        }
        rc = fts_backfill_try(s, project, after_id, ladder[i].body, ladder[i].camel);
        if (rc == CBM_STORE_OK) {
            return rc;
        }
    }
    return rc;
}

