TEST(daemon_application_sensitive_root_blocks_auto_index_but_preserves_controls) {
    app_env_backup_t cache_environment;
    app_env_backup_t home_environment;
    bool environments_saved = app_env_backup_capture(&cache_environment, "CBM_CACHE_DIR") &&
                              app_env_backup_capture(&home_environment, "HOME");
    char sensitive_raw[APP_TEST_PATH_CAP];
    char ordinary_raw[APP_TEST_PATH_CAP];
    char cache_raw[APP_TEST_PATH_CAP];
    (void)snprintf(sensitive_raw, sizeof(sensitive_raw), "%s/cbm-app-sensitive-auto-home-XXXXXX",
                   cbm_tmpdir());
    (void)snprintf(ordinary_raw, sizeof(ordinary_raw), "%s/cbm-app-sensitive-auto-project-XXXXXX",
                   cbm_tmpdir());
    (void)snprintf(cache_raw, sizeof(cache_raw), "%s/cbm-app-sensitive-auto-cache-XXXXXX",
                   cbm_tmpdir());
    bool dirs_ok = cbm_mkdtemp(sensitive_raw) != NULL && cbm_mkdtemp(ordinary_raw) != NULL &&
                   cbm_mkdtemp(cache_raw) != NULL;
    char sensitive[APP_TEST_PATH_CAP] = {0};
    char ordinary[APP_TEST_PATH_CAP] = {0};
    char cache[APP_TEST_PATH_CAP] = {0};
    bool canonical = dirs_ok && cbm_canonical_path(sensitive_raw, sensitive, sizeof(sensitive)) &&
                     cbm_canonical_path(ordinary_raw, ordinary, sizeof(ordinary)) &&
                     cbm_canonical_path(cache_raw, cache, sizeof(cache));
    char sensitive_source[APP_TEST_PATH_CAP];
    char ordinary_source[APP_TEST_PATH_CAP];
    (void)snprintf(sensitive_source, sizeof(sensitive_source), "%s/tracked.c", sensitive);
    (void)snprintf(ordinary_source, sizeof(ordinary_source), "%s/tracked.c", ordinary);
    bool files_ok = canonical && app_test_create_empty_file(sensitive_source) &&
                    app_test_create_empty_file(ordinary_source);
    bool environments_set = environments_saved && files_ok &&
                            cbm_setenv("CBM_CACHE_DIR", cache, 1) == 0 &&
                            cbm_setenv("HOME", sensitive, 1) == 0;
    cbm_config_t *stored_config = environments_set ? cbm_config_open(cache) : NULL;
    bool config_ready = stored_config &&
                        cbm_config_set(stored_config, CBM_CONFIG_AUTO_INDEX, "true") == 0 &&
                        cbm_config_set(stored_config, CBM_CONFIG_AUTO_WATCH, "false") == 0;

    app_fake_worker_context_t fake;
    app_fake_worker_context_init(&fake);
    cbm_daemon_application_worker_ops_t worker_ops = {
        .context = &fake,
        .start = app_fake_worker_start,
        .poll = app_fake_worker_poll,
        .cancel = app_fake_worker_cancel,
        .log_path = app_fake_worker_log_path,
        .destroy = app_fake_worker_destroy,
    };
    cbm_daemon_application_config_t config = {
        .config = stored_config,
        .worker_ops = &worker_ops,
    };
    cbm_daemon_application_t *application =
        config_ready ? cbm_daemon_application_new(&config) : NULL;
    cbm_daemon_runtime_application_callbacks_t callbacks =
        cbm_daemon_application_runtime_callbacks(application);
    cbm_daemon_runtime_application_session_t *sensitive_session =
        application ? app_test_open(&callbacks, 4030) : NULL;
    cbm_daemon_runtime_application_session_t *ordinary_session =
        application ? app_test_open(&callbacks, 4031) : NULL;
    cbm_daemon_runtime_application_session_t *approved_session =
        application ? app_test_open(&callbacks, 4032) : NULL;

    int background_baseline = cbm_daemon_application_background_initializes_for_test();
    bool sensitive_initialized = app_test_initialize_profile(
        &callbacks, sensitive_session, sensitive, CBM_MCP_TOOL_PROFILE_ALL, NULL, NULL);
    bool sensitive_evaluated = app_wait_for_background_initializes(background_baseline + 1);
    bool sensitive_blocked = sensitive_initialized && sensitive_evaluated &&
                             atomic_load(&fake.starts) == 0 &&
                             cbm_daemon_application_active_jobs(application) == 0;

    bool ordinary_initialized = app_test_initialize_profile(&callbacks, ordinary_session, ordinary,
                                                            CBM_MCP_TOOL_PROFILE_ALL, NULL, NULL);
    bool ordinary_admitted = ordinary_initialized && app_wait_for_atomic_int(&fake.starts, 1) &&
                             cbm_daemon_application_active_jobs(application) == 1;
    if (ordinary_session) {
        callbacks.session_cancel(callbacks.context, ordinary_session);
        callbacks.session_close(callbacks.context, ordinary_session);
        ordinary_session = NULL;
    }
    bool ordinary_reaped = ordinary_admitted && app_wait_for_atomic_int(&fake.cancels, 1) &&
                           app_wait_for_atomic_int(&fake.destroys, 1) &&
                           app_wait_for_active_jobs(application, 0);

    char grant_error[APP_TEST_PATH_CAP];
    bool approved = ordinary_reaped && cbm_workspace_grant_add(cache, sensitive, sensitive, true,
                                                               grant_error, sizeof(grant_error));
    bool approved_initialized =
        approved && app_test_initialize_profile(&callbacks, approved_session, sensitive,
                                                CBM_MCP_TOOL_PROFILE_ALL, NULL, NULL);
    bool approved_admitted = approved_initialized && app_wait_for_atomic_int(&fake.starts, 2) &&
                             cbm_daemon_application_active_jobs(application) == 1;

    if (sensitive_session) {
        callbacks.session_cancel(callbacks.context, sensitive_session);
        callbacks.session_close(callbacks.context, sensitive_session);
    }
    if (approved_session) {
        callbacks.session_cancel(callbacks.context, approved_session);
        callbacks.session_close(callbacks.context, approved_session);
    }
    if (ordinary_session) {
        callbacks.session_cancel(callbacks.context, ordinary_session);
        callbacks.session_close(callbacks.context, ordinary_session);
    }
    bool approved_reaped = approved_admitted && app_wait_for_atomic_int(&fake.cancels, 2) &&
                           app_wait_for_atomic_int(&fake.destroys, 2) &&
                           app_wait_for_active_jobs(application, 0);
    if (!approved_reaped) {
        atomic_store(&fake.allow_completion, true);
    }
    bool stopped = application && cbm_daemon_application_shutdown(application, APP_TEST_TIMEOUT_MS);
    cbm_daemon_application_free(application);
    cbm_config_close(stored_config);
    (void)th_rmtree(sensitive);
    (void)th_rmtree(ordinary);
    (void)th_rmtree(cache);
    bool cache_restored = app_env_backup_restore(&cache_environment);
    bool home_restored = app_env_backup_restore(&home_environment);

    ASSERT_TRUE(environments_saved);
    ASSERT_TRUE(dirs_ok);
    ASSERT_TRUE(canonical);
    ASSERT_TRUE(files_ok);
    ASSERT_TRUE(environments_set);
    ASSERT_TRUE(config_ready);
    ASSERT_TRUE(sensitive_blocked);
    ASSERT_TRUE(ordinary_admitted);
    ASSERT_TRUE(ordinary_reaped);
    ASSERT_TRUE(approved);
    ASSERT_TRUE(approved_admitted);
    ASSERT_TRUE(approved_reaped);
    ASSERT_TRUE(stopped);
    ASSERT_TRUE(cache_restored);
    ASSERT_TRUE(home_restored);
    PASS();
}

TEST(daemon_application_sensitive_root_blocks_watch_but_preserves_controls) {
    app_env_backup_t cache_environment;
    app_env_backup_t home_environment;
    bool environments_saved = app_env_backup_capture(&cache_environment, "CBM_CACHE_DIR") &&
                              app_env_backup_capture(&home_environment, "HOME");
    char sensitive_raw[APP_TEST_PATH_CAP];
    char ordinary_raw[APP_TEST_PATH_CAP];
    char cache_raw[APP_TEST_PATH_CAP];
    (void)snprintf(sensitive_raw, sizeof(sensitive_raw), "%s/cbm-app-sensitive-watch-home-XXXXXX",
                   cbm_tmpdir());
    (void)snprintf(ordinary_raw, sizeof(ordinary_raw), "%s/cbm-app-sensitive-watch-project-XXXXXX",
                   cbm_tmpdir());
    (void)snprintf(cache_raw, sizeof(cache_raw), "%s/cbm-app-sensitive-watch-cache-XXXXXX",
                   cbm_tmpdir());
    bool dirs_ok = cbm_mkdtemp(sensitive_raw) != NULL && cbm_mkdtemp(ordinary_raw) != NULL &&
                   cbm_mkdtemp(cache_raw) != NULL;
    char sensitive[APP_TEST_PATH_CAP] = {0};
    char ordinary[APP_TEST_PATH_CAP] = {0};
    char cache[APP_TEST_PATH_CAP] = {0};
    bool canonical = dirs_ok && cbm_canonical_path(sensitive_raw, sensitive, sizeof(sensitive)) &&
                     cbm_canonical_path(ordinary_raw, ordinary, sizeof(ordinary)) &&
                     cbm_canonical_path(cache_raw, cache, sizeof(cache));
    bool environments_set = environments_saved && canonical &&
                            cbm_setenv("CBM_CACHE_DIR", cache, 1) == 0 &&
                            cbm_setenv("HOME", sensitive, 1) == 0;
    cbm_config_t *stored_config = environments_set ? cbm_config_open(cache) : NULL;
    bool config_ready = stored_config &&
                        cbm_config_set(stored_config, CBM_CONFIG_AUTO_INDEX, "false") == 0 &&
                        cbm_config_set(stored_config, CBM_CONFIG_AUTO_WATCH, "true") == 0;
    char *sensitive_project = canonical ? cbm_project_name_from_path(sensitive) : NULL;
    char *ordinary_project = canonical ? cbm_project_name_from_path(ordinary) : NULL;
    char sensitive_db[APP_TEST_PATH_CAP] = {0};
    char ordinary_db[APP_TEST_PATH_CAP] = {0};
    if (sensitive_project) {
        (void)snprintf(sensitive_db, sizeof(sensitive_db), "%s/%s.db", cache, sensitive_project);
    }
    if (ordinary_project) {
        (void)snprintf(ordinary_db, sizeof(ordinary_db), "%s/%s.db", cache, ordinary_project);
    }
    bool db_ready = config_ready && sensitive_project && ordinary_project &&
                    app_test_create_empty_file(sensitive_db) &&
                    app_test_create_empty_file(ordinary_db);

    cbm_store_t *store = cbm_store_open_memory();
    cbm_watcher_t *watcher = cbm_watcher_new(store, app_test_index_noop, NULL);
    cbm_daemon_application_config_t config = {
        .watcher = watcher,
        .config = stored_config,
    };
    cbm_daemon_application_t *application =
        db_ready && watcher ? cbm_daemon_application_new(&config) : NULL;
    cbm_daemon_runtime_application_callbacks_t callbacks =
        cbm_daemon_application_runtime_callbacks(application);
    cbm_daemon_runtime_application_session_t *sensitive_session =
        application ? app_test_open(&callbacks, 4033) : NULL;
    cbm_daemon_runtime_application_session_t *ordinary_session =
        application ? app_test_open(&callbacks, 4034) : NULL;
    cbm_daemon_runtime_application_session_t *approved_session =
        application ? app_test_open(&callbacks, 4035) : NULL;

    bool sensitive_initialized = app_test_initialize_profile(
        &callbacks, sensitive_session, sensitive, CBM_MCP_TOOL_PROFILE_ALL, NULL, NULL);
    bool sensitive_blocked = sensitive_initialized && cbm_watcher_watch_count(watcher) == 0;
    bool ordinary_initialized = app_test_initialize_profile(&callbacks, ordinary_session, ordinary,
                                                            CBM_MCP_TOOL_PROFILE_ALL, NULL, NULL);
    bool ordinary_watched = ordinary_initialized && cbm_watcher_watch_count(watcher) == 1;
    if (ordinary_session) {
        callbacks.session_close(callbacks.context, ordinary_session);
        ordinary_session = NULL;
    }
    bool ordinary_released = ordinary_watched && cbm_watcher_watch_count(watcher) == 0;

    char grant_error[APP_TEST_PATH_CAP];
    bool approved = ordinary_released && cbm_workspace_grant_add(cache, sensitive, sensitive, true,
                                                                 grant_error, sizeof(grant_error));
    bool approved_initialized =
        approved && app_test_initialize_profile(&callbacks, approved_session, sensitive,
                                                CBM_MCP_TOOL_PROFILE_ALL, NULL, NULL);
    bool approved_watched = approved_initialized && cbm_watcher_watch_count(watcher) == 1;

    if (sensitive_session) {
        callbacks.session_close(callbacks.context, sensitive_session);
    }
    if (approved_session) {
        callbacks.session_close(callbacks.context, approved_session);
    }
    if (ordinary_session) {
        callbacks.session_close(callbacks.context, ordinary_session);
    }
    bool watches_released = watcher && cbm_watcher_watch_count(watcher) == 0;
    bool stopped = application && cbm_daemon_application_shutdown(application, APP_TEST_TIMEOUT_MS);
    cbm_daemon_application_free(application);
    if (watcher) {
        cbm_watcher_stop(watcher);
        cbm_watcher_free(watcher);
    }
    cbm_store_close(store);
    cbm_config_close(stored_config);
    free(sensitive_project);
    free(ordinary_project);
    (void)th_rmtree(sensitive);
    (void)th_rmtree(ordinary);
    (void)th_rmtree(cache);
    bool cache_restored = app_env_backup_restore(&cache_environment);
    bool home_restored = app_env_backup_restore(&home_environment);

    ASSERT_TRUE(environments_saved);
    ASSERT_TRUE(dirs_ok);
    ASSERT_TRUE(canonical);
    ASSERT_TRUE(environments_set);
    ASSERT_TRUE(config_ready);
    ASSERT_TRUE(db_ready);
    ASSERT_TRUE(sensitive_blocked);
    ASSERT_TRUE(ordinary_watched);
    ASSERT_TRUE(ordinary_released);
    ASSERT_TRUE(approved);
    ASSERT_TRUE(approved_watched);
    ASSERT_TRUE(watches_released);
    ASSERT_TRUE(stopped);
    ASSERT_TRUE(cache_restored);
    ASSERT_TRUE(home_restored);
    PASS();
}

ST(daemon_bootstrap_mute_endpoint_holder_is_reserved_and_never_unavailable) {
    cbm_daemon_runtime_connect_result_t mute = {0};
    mute.status = CBM_DAEMON_RUNTIME_CONNECT_ERROR;
    mute.muted_endpoint_holder_pid = 4242;
    ASSERT_EQ(cbm_daemon_bootstrap_classify_failed_connect(&mute, 1),
              CBM_DAEMON_BOOTSTRAP_PROBE_RESERVED);
    ASSERT_EQ(cbm_daemon_bootstrap_classify_failed_connect(&mute, 0),
              CBM_DAEMON_BOOTSTRAP_PROBE_RESERVED);
    ASSERT_EQ(cbm_daemon_bootstrap_classify_failed_connect(&mute, -1),
              CBM_DAEMON_BOOTSTRAP_PROBE_RESERVED);

    /* A protocol-level rejection still wins over the holder pid: an answering
     * generation is more precise evidence than a silent one. */
    cbm_daemon_runtime_connect_result_t rejected = {0};
    rejected.status = CBM_DAEMON_RUNTIME_CONNECT_REJECTED;
    rejected.muted_endpoint_holder_pid = 4242;
    snprintf(rejected.message, sizeof(rejected.message), "CBM daemon is stopping");
    ASSERT_EQ(cbm_daemon_bootstrap_classify_failed_connect(&rejected, 0),
              CBM_DAEMON_BOOTSTRAP_PROBE_TERMINAL);
    PASS();
}

static cbm_daemon_runtime_application_session_t *frontend_idle_session_open(
    void *context, cbm_daemon_client_id_t client_id, uint64_t authenticated_process_id) {
    return context && client_id != CBM_DAEMON_CLIENT_ID_INVALID && authenticated_process_id != 0
               ? (cbm_daemon_runtime_application_session_t *)context
               : NULL;
}

static cbm_daemon_runtime_application_status_t frontend_idle_request(
    void *context, cbm_daemon_runtime_application_session_t *session,
    cbm_daemon_runtime_application_token_t request_token, const uint8_t *request,
    uint32_t request_length, uint8_t **response_out, uint32_t *response_length_out) {
    (void)request_token;
    if (!context || session != (cbm_daemon_runtime_application_session_t *)context ||
        !response_out || !response_length_out || (request_length > 0 && !request)) {
        return CBM_DAEMON_RUNTIME_APPLICATION_HANDLER_ERROR;
    }
    *response_out = NULL;
    *response_length_out = 0;
    return CBM_DAEMON_RUNTIME_APPLICATION_OK;
}

static void frontend_idle_request_cancel(
    void *context, cbm_daemon_runtime_application_session_t *session,
    cbm_daemon_runtime_application_token_t request_token) {
    (void)context;
    (void)session;
    (void)request_token;
}

static void frontend_idle_session_cancel(
    void *context, cbm_daemon_runtime_application_session_t *session) {
    (void)context;
    (void)session;
}

static void frontend_idle_session_close(
    void *context, cbm_daemon_runtime_application_session_t *session) {
    (void)context;
    (void)session;
}

static uint64_t frontend_test_process_id(void) {
#ifdef _WIN32
    return (uint64_t)GetCurrentProcessId();
#else
    return (uint64_t)getpid();
#endif
}

static bool frontend_idle_fixture_start(frontend_idle_fixture_t *fixture) {
    static const char cache[] =
        "dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd";
    memset(fixture, 0, sizeof(*fixture));
    if (!frontend_maintenance_fixture_start(&fixture->maintenance, "idle-observer")) {
        return false;
    }
    char build[CBM_DAEMON_BUILD_FINGERPRINT_SIZE];
    int log_written = snprintf(fixture->conflict_log, sizeof(fixture->conflict_log),
                               "%s/conflicts.ndjson", fixture->maintenance.parent);
    if (log_written <= 0 || log_written >= (int)sizeof(fixture->conflict_log) ||
        !cbm_daemon_runtime_process_build_fingerprint(frontend_test_process_id(), build)) {
        return false;
    }
    cbm_daemon_build_identity_t identity = {
        .semantic_version = "2.4.0",
        .build_fingerprint = build,
        .cache_fingerprint = cache,
        .protocol_abi = 3,
        .store_abi = 11,
        .feature_abi = 7,
    };
    cbm_daemon_runtime_application_callbacks_t callbacks = {
        .context = fixture,
        .session_open = frontend_idle_session_open,
        .request = frontend_idle_request,
        .request_cancel = frontend_idle_request_cancel,
        .session_cancel = frontend_idle_session_cancel,
        .session_close = frontend_idle_session_close,
    };
    cbm_daemon_runtime_service_config_t config = {
        .endpoint = fixture->maintenance.endpoint,
        .identity = identity,
        .conflict_log_path = fixture->conflict_log,
        .conflict_log_cap_bytes = 64U * 1024U,
        .max_clients = 2,
        .lease_timeout_ms = 5000,
        .request_timeout_ms = 30000,
        .shutdown_timeout_ms = 30000,
        .application = callbacks,
    };
    fixture->service = cbm_daemon_runtime_service_start(&config);
    cbm_daemon_runtime_connect_result_t connect_result = {0};
    fixture->client = fixture->service
                          ? cbm_daemon_runtime_client_connect(fixture->maintenance.endpoint, &identity,
                                                              30000, &connect_result)
                          : NULL;
    return fixture->client && connect_result.status == CBM_DAEMON_RUNTIME_CONNECT_ACCEPTED;
}

static bool frontend_idle_fixture_finish(frontend_idle_fixture_t *fixture) {
    bool ok = true;
    if (fixture->client) {
        ok = cbm_daemon_runtime_client_close(fixture->client, 30000) && ok;
        fixture->client = NULL;
    }
    if (fixture->service) {
        if (cbm_daemon_runtime_service_state(fixture->service) !=
            CBM_DAEMON_RUNTIME_SERVICE_EXITED) {
            ok = cbm_daemon_runtime_service_stop(fixture->service, 30000) && ok;
        }
        ok = cbm_daemon_runtime_service_free(fixture->service) && ok;
        fixture->service = NULL;
    }
    frontend_maintenance_fixture_finish(&fixture->maintenance);
    return ok;
}

static FILE *frontend_test_fdopen_read(int fd) {
#ifdef _WIN32
    return _fdopen(fd, "rb");
#else
    return fdopen(fd, "rb");
#endif
}

static int frontend_test_close_fd(int fd) {
#ifdef _WIN32
    return _close(fd);
#else
    return close(fd);
#endif
}

static void *frontend_idle_run(void *opaque) {
    frontend_idle_run_t *run = opaque;
    run->result =
        cbm_daemon_frontend_mcp_run(run->client, run->manager, run->input, run->output);
    return NULL;
}

TEST(daemon_frontend_idle_uses_one_maintenance_observer) {
    frontend_idle_fixture_t fixture;
    bool fixture_ready = frontend_idle_fixture_start(&fixture);
    int input_pipe[2] = {-1, -1};
    bool pipe_ready = fixture_ready && cbm_pipe(input_pipe) == 0;
    FILE *input = pipe_ready ? frontend_test_fdopen_read(input_pipe[0]) : NULL;
    FILE *output = input ? tmpfile() : NULL;
    frontend_idle_run_t run = {
        .client = fixture.client,
        .manager = fixture.maintenance.manager,
        .input = input,
        .output = output,
        .result = -1,
    };
    if (output) {
        fixture.client = NULL; /* cbm_daemon_frontend_mcp_run consumes it. */
    }
    cbm_daemon_frontend_test_observer_reset(true);
    cbm_thread_t frontend_thread;
    bool thread_started =
        output && cbm_thread_create(&frontend_thread, 0, frontend_idle_run, &run) == 0;
    uint64_t deadline = cbm_now_ms() + 10000U;
    while (thread_started && cbm_now_ms() < deadline &&
           (!cbm_daemon_frontend_test_monitor_waiting() ||
            cbm_daemon_frontend_test_worker_idle_cycles() == 0)) {
        cbm_usleep(1000);
    }
    bool monitor_waiting = cbm_daemon_frontend_test_monitor_waiting();
    uint64_t monitor_observations = cbm_daemon_frontend_test_monitor_observations();
    uint64_t worker_observations = cbm_daemon_frontend_test_worker_observations();
    uint64_t idle_cycles = cbm_daemon_frontend_test_worker_idle_cycles();
    cbm_daemon_frontend_test_observer_release();
    bool input_closed = !pipe_ready || frontend_test_close_fd(input_pipe[1]) == 0;
    bool joined = thread_started && cbm_thread_join(&frontend_thread) == 0;
    bool input_stream_closed = !input || fclose(input) == 0;
    bool output_closed = !output || fclose(output) == 0;
    bool fixture_closed = frontend_idle_fixture_finish(&fixture);

    ASSERT_TRUE(fixture_ready);
    ASSERT_TRUE(pipe_ready);
    ASSERT_TRUE(thread_started);
    ASSERT_TRUE(monitor_waiting);
    ASSERT_EQ(monitor_observations, 1);
    ASSERT_TRUE(idle_cycles > 0);
    ASSERT_EQ(worker_observations, 0);
    ASSERT_TRUE(input_closed);
    ASSERT_TRUE(joined);
    ASSERT_EQ(run.result, 0);
    ASSERT_TRUE(input_stream_closed);
    ASSERT_TRUE(output_closed);
    ASSERT_TRUE(fixture_closed);
    PASS();
}

static void runtime_test_containment_hook(const char *component) {
    if (component && strcmp(component, "application_request_join") == 0) {
        atomic_store_explicit(&runtime_test_containment_component_exact, true,
                              memory_order_release);
    }
    atomic_fetch_add_explicit(&runtime_test_containment_fired, 1, memory_order_release);
}

TEST(daemon_runtime_abandoned_request_join_reaches_containment_in_bounded_time) {
    static const uint8_t request[] = {'w', 'e', 'd', 'g', 'e'};
    enum { JOIN_BOUND_MS = 150, CONTAINMENT_OBSERVED_MAX_MS = 5000 };
    cbm_daemon_build_identity_t identity =
        runtime_test_identity("2.4.0", runtime_test_self_build());
    runtime_application_context_t context;
    runtime_application_context_init(&context, true);
    atomic_store_explicit(&context.ignore_first_request_cancel, true, memory_order_release);
    atomic_store(&runtime_test_containment_fired, 0);
    atomic_store(&runtime_test_containment_component_exact, false);
    atomic_bool request_thread_completed;
    atomic_init(&request_thread_completed, false);
    runtime_test_fixture_t fixture;
    bool started = runtime_test_fixture_start_application(&fixture, "application-abandoned-join",
                                                          &identity, &context);
    cbm_daemon_runtime_connect_result_t result = {0};
    cbm_daemon_runtime_client_t *client = NULL;
    runtime_application_client_call_t call = {
        .request = request,
        .request_length = (uint32_t)sizeof(request),
        .completed = &request_thread_completed,
        .status = CBM_DAEMON_RUNTIME_APPLICATION_OK,
    };
    cbm_thread_t request_thread;
    int request_thread_create_rc = -1;
    int request_thread_join_rc = -1;
    bool request_thread_started = false;
    bool callback_started = false;
    bool close_begun = false;
    bool containment_observed = false;
    uint64_t containment_elapsed_ms = UINT64_MAX;
    bool exited_after_release = false;

    cbm_daemon_runtime_set_abandoned_request_join_timeout_for_testing(JOIN_BOUND_MS);
    cbm_daemon_runtime_set_containment_hook_for_testing(runtime_test_containment_hook);

    if (started) {
        client = cbm_daemon_runtime_client_connect(fixture.endpoint, &identity,
                                                   RUNTIME_TEST_TIMEOUT_MS, &result);
    }
    if (client) {
        call.client = client;
        request_thread_create_rc = cbm_thread_create(
            &request_thread, 128U * 1024U, runtime_application_client_request_thread, &call);
        request_thread_started = request_thread_create_rc == 0;
        callback_started =
            request_thread_started &&
            runtime_test_wait_atomic_bool(&context.first_request_started, RUNTIME_TEST_TIMEOUT_MS);
    }
    if (callback_started) {
        uint64_t containment_started_ms = cbm_now_ms();
        close_begun = cbm_daemon_runtime_client_close_begin(client);
        uint64_t deadline = cbm_now_ms() + CONTAINMENT_OBSERVED_MAX_MS;
        while (atomic_load_explicit(&runtime_test_containment_fired, memory_order_acquire) == 0 &&
               cbm_now_ms() < deadline) {
            struct timespec pause = {.tv_sec = 0, .tv_nsec = 1000000};
            (void)cbm_nanosleep(&pause, NULL);
        }
        containment_observed =
            atomic_load_explicit(&runtime_test_containment_fired, memory_order_acquire) > 0;
        containment_elapsed_ms = cbm_now_ms() - containment_started_ms;
    }

    /* Cooperation after the boundary: the reap waits for the released handler
     * so join and teardown stay provably leak-free under the sanitizers. */
    atomic_store_explicit(&context.release_first_request, true, memory_order_release);
    if (request_thread_started) {
        request_thread_join_rc = cbm_thread_join(&request_thread);
    }
    if (client) {
        (void)cbm_daemon_runtime_client_close_finish(client, RUNTIME_TEST_TIMEOUT_MS);
        client = NULL;
    }
    if (started) {
        exited_after_release =
            cbm_daemon_runtime_service_wait_exited(fixture.service, RUNTIME_TEST_TIMEOUT_MS);
    }
    free(call.response);
    runtime_test_fixture_finish(&fixture);
    cbm_daemon_runtime_set_containment_hook_for_testing(NULL);
    cbm_daemon_runtime_set_abandoned_request_join_timeout_for_testing(0);

    ASSERT_TRUE(started);
    ASSERT_EQ(result.status, CBM_DAEMON_RUNTIME_CONNECT_ACCEPTED);
    ASSERT_EQ(request_thread_create_rc, 0);
    ASSERT_TRUE(callback_started);
    ASSERT_TRUE(close_begun);
    ASSERT_TRUE(containment_observed);
    ASSERT_TRUE(containment_elapsed_ms <= CONTAINMENT_OBSERVED_MAX_MS);
    ASSERT_EQ(atomic_load(&runtime_test_containment_fired), 1);
    ASSERT_TRUE(atomic_load(&runtime_test_containment_component_exact));
    ASSERT_EQ(request_thread_join_rc, 0);
    ASSERT_TRUE(exited_after_release);
    ASSERT_EQ(atomic_load(&context.opened), 1);
    ASSERT_EQ(atomic_load(&context.requests), 1);
    ASSERT_EQ(atomic_load(&context.cancelled), 1);
    ASSERT_EQ(atomic_load(&context.closed), 1);
    PASS();
}

static void *runtime_test_mute_holder_thread(void *opaque) {
    runtime_mute_holder_t *holder = opaque;
    while (!atomic_load_explicit(&holder->stop, memory_order_acquire) &&
           atomic_load_explicit(&holder->held_count, memory_order_acquire) < 2) {
        cbm_daemon_ipc_connection_t *connection = NULL;
        int accepted = cbm_daemon_ipc_accept(holder->listener, 50, &connection);
        if (accepted == 1 && connection) {
            int index = atomic_load_explicit(&holder->held_count, memory_order_acquire);
            holder->held[index] = connection;
            atomic_store_explicit(&holder->held_count, index + 1, memory_order_release);
        }
    }
    return NULL;
}

static uint64_t runtime_test_self_process_id(void) {
#ifdef _WIN32
    return (uint64_t)GetCurrentProcessId();
#else
    return (uint64_t)getpid();
#endif
}

TEST(daemon_runtime_mute_endpoint_holder_pid_is_reported) {
    enum { MUTE_CONNECT_TIMEOUT_MS = 500 };
    cbm_daemon_build_identity_t identity =
        runtime_test_identity("2.4.0", runtime_test_self_build());
    char parent[RUNTIME_TEST_PATH_CAP] = {0};
    char key[CBM_DAEMON_KEY_SIZE] = {0};
    char runtime_dir[RUNTIME_TEST_PATH_CAP] = {0};
    cbm_daemon_ipc_endpoint_t *endpoint = NULL;
    runtime_mute_holder_t holder = {0};
    atomic_init(&holder.held_count, 0);
    atomic_init(&holder.stop, false);
    cbm_thread_t holder_thread;
    bool holder_started = false;

    bool prepared = th_secure_runtime_parent_new(parent, sizeof(parent), "mute-holder") &&
                    cbm_daemon_rendezvous_key(key);
    endpoint = prepared ? cbm_daemon_ipc_endpoint_new(key, parent) : NULL;
    bool runtime_dir_copied =
        endpoint &&
        runtime_test_copy_path(runtime_dir, cbm_daemon_ipc_endpoint_runtime_dir(endpoint));
    holder.listener = endpoint ? cbm_daemon_ipc_listen(endpoint) : NULL;
    holder_started =
        holder.listener &&
        cbm_thread_create(&holder_thread, 0, runtime_test_mute_holder_thread, &holder) == 0;

    cbm_daemon_runtime_connect_result_t connect_result = {0};
    cbm_daemon_runtime_client_t *client = NULL;
    cbm_daemon_runtime_status_t status = {0};
    bool status_active = true;
    if (holder_started) {
        client = cbm_daemon_runtime_client_connect(endpoint, &identity, MUTE_CONNECT_TIMEOUT_MS,
                                                   &connect_result);
        status_active = cbm_daemon_runtime_request_status(endpoint, &identity,
                                                          MUTE_CONNECT_TIMEOUT_MS, &status);
    }

    atomic_store_explicit(&holder.stop, true, memory_order_release);
    if (holder_started) {
        (void)cbm_thread_join(&holder_thread);
    }
    for (size_t index = 0; index < 2; index++) {
        if (holder.held[index]) {
            cbm_daemon_ipc_connection_close(holder.held[index]);
        }
    }
    if (holder.listener) {
        cbm_daemon_ipc_listener_close(holder.listener);
    }
    cbm_daemon_ipc_endpoint_free(endpoint);
    (void)cbm_rmdir(runtime_dir);
    (void)cbm_rmdir(parent);

    ASSERT_TRUE(prepared);
    ASSERT_TRUE(runtime_dir_copied);
    ASSERT_TRUE(holder_started);
    ASSERT_NULL(client);
    ASSERT_EQ(connect_result.status, CBM_DAEMON_RUNTIME_CONNECT_ERROR);
    ASSERT_EQ(connect_result.muted_endpoint_holder_pid, runtime_test_self_process_id());
    ASSERT_FALSE(status_active);
    ASSERT_EQ(status.muted_endpoint_holder_pid, runtime_test_self_process_id());
    PASS();
}

static int ei_edge_count_is(const EILangFile *files, int nfiles, const char *edge_type,
                            int expected) {
    EILangProj lp;
    cbm_store_t *store = ei_index_files(&lp, files, nfiles);
    int got = store ? cbm_store_count_edges_by_type(store, lp.project, edge_type) : -1;
    if (got != expected) {
        fprintf(stderr, "  [%s] FAIL count=%d expected==%d\n", edge_type, got, expected);
    }
    ei_cleanup(&lp, store);
    return got == expected;
}

TEST(ei_go_import_never_binds_symbol) {
    /* #1934: a Go import path names a package, never a symbol. `os/exec` is
     * external (not in the graph), so the ONLY correct outcome is no edge —
     * but Strategy 3's symbol-name fallback matched the path's last segment
     * against any project definition named `exec` and bound the import to a
     * test harness's method. Exact count: the internal `util` import (edge 1,
     * via Strategy 1 → the package Folder) must be the whole IMPORTS
     * relation; the fallback edge onto harness.exec (reproduce-first RED:
     * count 2) must not exist. */
    static const EILangFile f[] = {
        {"go.mod", "module example.com/fxi

go 1.22
"},
        {"util/util.go", "package util

func Tag() string { return "t" }
"},
        {"helper/harness.go", "package helper

type harness struct{ n int }

"
                              "func (h *harness) exec(cmd string) error { return nil }
"},
        /* Same-package decoy: the field-measured survivor bound os/exec to a
         * method in the IMPORTER'S OWN package (Strategy 1b's sibling-file
         * resolution accepts symbol labels too), so the fixture needs the
         * collision both cross-package and same-package. */
        {"app/aux.go", "package app

type runner struct{ n int }

"
                       "func (r *runner) exec(cmd string) error { return nil }
"},
        {"app/run.go", "package app

import (
	"os/exec"

"
                       "	"example.com/fxi/util"
)

"
                       "func Run() error {
	_ = util.Tag()
"
                       "	return exec.Command("true").Run()
}
"}};
    ASSERT_TRUE(ei_edge_count_is(f, 5, "IMPORTS", 1));
    PASS();
}

TEST(chialisp_puzzle_defs_and_labels) {
    const char *src = "; a Chialisp puzzle\n"
                      "(mod (ARG)\n"
                      "  (include condition_codes.clib)\n"
                      "  (defconstant TWO 2)\n"
                      "  (defconstant HASH (sha256 1))\n"
                      "  (defun-inline square (x) (* x x))\n"
                      "  (defun apply_twice (v) (square (square v)))\n"
                      "  (defmacro assert items (f items))\n"
                      "  (apply_twice ARG)\n"
                      ")\n";
    CBMFileResult *r = extract(src, CBM_LANG_CHIALISP, "t", "puzzles/my_puzzle.clsp");
    ASSERT_NOT_NULL(r);
    ASSERT_FALSE(r->has_error);
    /* `mod` has no name of its own — the puzzle is named by its file. */
    ASSERT(has_def(r, "Module", "my_puzzle"));
    /* Defs are NESTED inside `(mod ...)`; a walk that stops at the module
     * loses every one of them. */
    ASSERT(has_def(r, "Function", "square"));
    ASSERT(has_def(r, "Function", "apply_twice"));
    ASSERT(has_def(r, "Macro", "assert"));
    /* `defconstant` binds an arbitrary EXPRESSION, not just a primitive. */
    ASSERT(has_def(r, "Constant", "TWO"));
    ASSERT(has_def(r, "Constant", "HASH"));
    /* A dotted include filename resolves as one symbol. */
    ASSERT(has_import(r, "condition_codes.clib"));
    /* Real calls survive; CLVM primitives and def heads do not become calls. */
    ASSERT(has_call(r, "square"));
    ASSERT(has_call(r, "apply_twice"));
    ASSERT(!has_call(r, "sha256"));
    ASSERT(!has_call(r, "defun"));
    ASSERT(!has_call(r, "mod"));
    ASSERT(!has_call(r, "include"));
    /* A parameter list is a `list` too — but it binds, it does not invoke. */
    ASSERT(!has_call(r, "x"));
    ASSERT(!has_call(r, "v"));
    ASSERT(!has_call(r, "items"));
    cbm_free_result(r);
    PASS();
}

TE

(chialisp_comment_line_endings) {
    /* LF, CRLF, and a comment closed by EOF with no trailing newline. The
     * public grammar's comment rule was `/;.*\r\n/`, so an LF file lost every
     * form after the first comment. */
    const char *lf = "(mod (A)\n; note\n(defun f (x) x)\n)\n";
    const char *crlf = "(mod (A)\r\n; note\r\n(defun f (x) x)\r\n)\r\n";
    const char *eof = "(mod (A)\n(defun f (x) x)\n)\n; trailing comment, no newline";
    const char *srcs[] = {lf, crlf, eof};
    for (int i = 0; i < 3; i++) {
        CBMFileResult *r = extract(srcs[i], CBM_LANG_CHIALISP, "t", "c.clsp");
        ASSERT_NOT_NULL(r);
        ASSERT_FALSE(r->has_error);
        ASSERT_FALSE(r->parse_incomplete);
        ASSERT(has_def(r, "Function", "f"));
        cbm_free_result(r);
    }
    PASS();
}

TE

(chialisp_library_defs_and_quoted_data) {
    /* A .clib wraps its definitions in one enclosing list, and its macros embed
     * puzzle-shaped literals under `(q ...)`. Those literals are DATA: a def
     * head or call symbol inside one must mint nothing. */
    const char *src = "(\n"
                      "  (defconstant TWO 2)\n"
                      "  (defmacro emit () (q . (defun ghost (x) (real_helper x))))\n"
                      "  (defun real_helper (x) (+ x TWO))\n"
                      ")\n";
    CBMFileResult *r = extract(src, CBM_LANG_CHIALISP, "t", "curry.clib");
    ASSERT_NOT_NULL(r);
    ASSERT_FALSE(r->has_error);
    ASSERT(has_def(r, "Constant", "TWO"));
    ASSERT(has_def(r, "Macro", "emit"));
    ASSERT(has_def(r, "Function", "real_helper"));
    ASSERT(!has_def_any(r, "ghost"));
    ASSERT(!has_call(r, "real_helper"));
    cbm_free_result(r);
    PASS();
}

TE

(chialisp_export_names_do_not_duplicate_defs) {
    /* `(export foo)` names a function already defined in the same file. As a
     * def head it would mint a SECOND node for `foo`; as a call head it would
     * mint a phantom call. It is neither. */
    const char *src = "(\n"
                      "  (defun foo (x) x)\n"
                      "  (export foo)\n"
                      ")\n";
    CBMFileResult *r = extract(src, CBM_LANG_CHIALISP, "t", "e.clsp");
    ASSERT_NOT_NULL(r);
    ASSERT_FALSE(r->has_error);
    int foo_defs = 0;
    for (int i = 0; i < r->defs.count; i++) {
        if (r->defs.items[i].name && strcmp(r->defs.items[i].name, "foo") == 0) {
            foo_defs++;
        }
    }
    ASSERT_EQ(foo_defs, 1);
    ASSERT(!has_call(r, "export"));
    ASSERT(!has_call(r, "foo"));
    cbm_free_result(r);
    PASS();
}

TE

(chialisp_comment_before_def_head_keeps_the_name) {
    /* Comments are NAMED nodes and so occupy named-child indices. A comment
     * between the head and the name shifts them by one; defs and call-scope
     * must skip comments the same way or they stop describing the same tree. */
    const char *src = "(mod ()\n"
                      "  (defun ; why this exists\n"
                      "     documented (x) (* x 2))\n"
                      "  (defun caller () (documented 21))\n"
                      ")\n";
    CBMFileResult *r = extract(src, CBM_LANG_CHIALISP, "t", "d.clsp");
    ASSERT_NOT_NULL(r);
    ASSERT_FALSE(r->has_error);
    ASSERT(has_def(r, "Function", "documented"));
    ASSERT(has_def(r, "Function", "caller"));
    ASSERT(has_call(r, "documented"));
    cbm_free_result(r);
    PASS();
}

TE

(chialisp_dialect_sigil_is_not_a_file_import) {
    /* `(include *standard-cl-26*)` selects a dialect; recording it as an import
     * invents a dependency on a file that does not exist. The compiler filters
     * `*...*` names and so must we. */
    const char *src = "(mod ()\n"
                      "  (include *standard-cl-26*)\n"
                      "  (include curry.clib)\n"
                      ")\n";
    CBMFileResult *r = extract(src, CBM_LANG_CHIALISP, "t", "s.clsp");
    ASSERT_NOT_NULL(r);
    ASSERT_FALSE(r->has_error);
    ASSERT(has_import(r, "curry.clib"));
    ASSERT(!has_import(r, "standard-cl-26"));
    cbm_free_result(r);
    PASS();
}

