    ASSERT_EQ(self_call, 1);
    ASSERT_EQ(super_call, 1);
    ASSERT_EQ(imported_module, 1);
    ASSERT_EQ(imported_alias, 1);
    ASSERT_EQ(bare, 1);
    cbm_free_result(r);
    PASS();
}

