}

TEST(ws_sensitive_root_explicit_approval_is_preserved) {
    char root[256];
    char *created = th_mktempdir("cbm_ws_403_home");
    ASSERT_NOT_NULL(created);
    snprintf(root, sizeof(root), "%s", created);

    char cache[256];
    created = th_mktempdir("cbm_ws_403");
    ASSERT_NOT_NULL(created);
    snprintf(cache, sizeof(cache), "%s", created);

    char err[1024];
    ASSERT_FALSE(cbm_workspace_root_allowed(root, root, cache, NULL, err, sizeof(err)));
    ASSERT_NOT_NULL(strstr(err, "--approve-sensitive"));
    ASSERT_TRUE(cbm_workspace_grant_add(cache, root, root, true, err, sizeof(err)));
    ASSERT_TRUE(cbm_workspace_root_allowed(root, root, cache, NULL, err, sizeof(err)));

    th_cleanup(root);
    th_cleanup(cache);
    PASS();
}

TEST(ws_sensitive_approval_upgrades_existing_ordinary_exact_grant) {
    char root[256];
    char *created = th_mktempdir("cbm_ws_403_exact");
    ASSERT_NOT_NULL(created);
    snprintf(root, sizeof(root), "%s", created);

    char cache[256];
    created = th_mktempdir("cbm_ws_403_exact_cache");
    ASSERT_NOT_NULL(created);
    snprintf(cache, sizeof(cache), "%s", created);

    char err[1024];
    ASSERT_TRUE(cbm_workspace_grant_add(cache, NULL, root, false, err, sizeof(err)));
    ASSERT_FALSE(cbm_workspace_root_allowed(root, root, cache, NULL, err, sizeof(err)));

    ASSERT_TRUE(cbm_workspace_grant_add(cache, root, root, true, err, sizeof(err)));
    ASSERT_TRUE(cbm_workspace_root_allowed(root, root, cache, NULL, err, sizeof(err)));
    /* A repeated explicit approval must recognize the marked exact grant rather
     * than append another exception. */
    ASSERT_TRUE(cbm_workspace_grant_add(cache, root, root, true, err, sizeof(err)));

    char listed[4096];
    char expected[4096];
    ASSERT_TRUE(cbm_workspace_grant_list(cache, listed, sizeof(listed)));
    snprintf(expected, sizeof(expected), "%s\n(approved) %s\n", root, root);
    ASSERT_STR_EQ(listed, expected);

    th_cleanup(root);
    th_cleanup(cache);
    PASS();
}

TEST(ws_sensitive_approval_adds_exact_exception_under_ordinary_ancestor) {
    char ancestor[256];
    char *created = th_mktempdir("cbm_ws_403_ancestor");
    ASSERT_NOT_NULL(created);
    snprintf(ancestor, sizeof(ancestor), "%s", created);

    char cache[256];
    created = th_mktempdir("cbm_ws_403_ancestor_cache");
    ASSERT_NOT_NULL(created);
    snprintf(cache, sizeof(cache), "%s", created);

    char sensitive[1024];
    snprintf(sensitive, sizeof(sensitive), "%s/private-project", ancestor);
    ASSERT_EQ(cbm_mkdir(sensitive), 0);
    char err[1024];
    ASSERT_TRUE(cbm_workspace_grant_add(cache, NULL, ancestor, false, err, sizeof(err)));
    ASSERT_FALSE(cbm_workspace_root_allowed(sensitive, sensitive, cache, NULL, err, sizeof(err)));

    ASSERT_TRUE(cbm_workspace_grant_add(cache, sensitive, sensitive, true, err, sizeof(err)));
    ASSERT_TRUE(
        cbm_workspace_root_allowed(sensitive, sensitive, cache, NULL, err, sizeof(err)));
    ASSERT_TRUE(cbm_workspace_grant_add(cache, sensitive, sensitive, true, err, sizeof(err)));

    char listed[4096];
    char expected[4096];
    ASSERT_TRUE(cbm_workspace_grant_list(cache, listed, sizeof(listed)));
    snprintf(expected, sizeof(expected), "%s\n(approved) %s\n", ancestor, sensitive);
    ASSERT_STR_EQ(listed, expected);

    th_cleanup(ancestor);
    th_cleanup(cache);
    PASS();
}

static bool ts_lex(TSLexer *lexer, TSStateId state) {
  START_LEXER();
  eof = lexer->eof(lexer);
  switch (state) {
    case 0:
      if (eof) ADVANCE(5);
      ADVANCE_MAP(
        '"', 1,
        '\'', 2,
        '(', 6,
        ')', 7,
        '-', 14,
        '.', 13,
        '0', 10,
        ';', 8,
      );
      if (('\t' <= lookahead && lookahead <= '\r') ||
          lookahead == ' ') SKIP(0);
      if (('1' <= lookahead && lookahead <= '9')) ADVANCE(11);
      if (lookahead != 0) ADVANCE(16);
      END_STATE();
    case 1:
      if (lookahead == '"') ADVANCE(12);
      if (lookahead == '\\') ADVANCE(3);
      if (lookahead != 0) ADVANCE(1);
      END_STATE();
    case 2:
      if (lookahead == '\'') ADVANCE(12);
      if (lookahead == '\\') ADVANCE(4);
      if (lookahead != 0) ADVANCE(2);
      END_STATE();
    case 3:
      if (lookahead != 0 &&
          lookahead != '\n') ADVANCE(1);
      END_STATE();
    case 4:
      if (lookahead != 0 &&
          lookahead != '\n') ADVANCE(2);
      END_STATE();
    case 5:
      ACCEPT_TOKEN(ts_builtin_sym_end);
      END_STATE();
    case 6:
      ACCEPT_TOKEN(anon_sym_LPAREN);
      END_STATE();
    case 7:
      ACCEPT_TOKEN(anon_sym_RPAREN);
      END_STATE();
    case 8:
      ACCEPT_TOKEN(sym_comment);
      if (lookahead != 0 &&
          lookahead != '\n' &&
          lookahead != '\r') ADVANCE(8);
      END_STATE();
    case 9:
      ACCEPT_TOKEN(sym_hex);
      if (('0' <= lookahead && lookahead <= '9') ||
          ('A' <= lookahead && lookahead <= 'F') ||
          ('a' <= lookahead && lookahead <= 'f')) ADVANCE(9);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    case 10:
      ACCEPT_TOKEN(sym_number);
      if (lookahead == 'X' ||
          lookahead == 'x') ADVANCE(15);
      if (('0' <= lookahead && lookahead <= '9')) ADVANCE(11);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    case 11:
      ACCEPT_TOKEN(sym_number);
      if (('0' <= lookahead && lookahead <= '9')) ADVANCE(11);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    case 12:
      ACCEPT_TOKEN(sym_string);
      END_STATE();
    case 13:
      ACCEPT_TOKEN(sym_dot);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    case 14:
      ACCEPT_TOKEN(sym_symbol);
      if (('0' <= lookahead && lookahead <= '9')) ADVANCE(11);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    case 15:
      ACCEPT_TOKEN(sym_symbol);
      if (('0' <= lookahead && lookahead <= '9') ||
          ('A' <= lookahead && lookahead <= 'F') ||
          ('a' <= lookahead && lookahead <= 'f')) ADVANCE(9);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    case 16:
      ACCEPT_TOKEN(sym_symbol);
      if (lookahead != 0 &&
          (lookahead < '\t' || '\r' < lookahead) &&
          lookahead != ' ' &&
          lookahead != '"' &&
          (lookahead < '\'' || ')' < lookahead) &&
          lookahead != ';') ADVANCE(16);
      END_STATE();
    default:
      return false;
  }
}

scope_holds(const char *const *names, int count, const char *want) {
    for (int i = 0; i < count; i++) {
        if (names[i] && strcmp(names[i], want) == 0) {
            return true;
        }
    }
    return false;
}

/* Every n

ollect_declared_names(const cbm_query_t *q, const char **out, int cap) {
    int n = 0;
    for (int pi = 0; pi < q->pattern_count; pi++) {
        const cbm_pattern_t *pat = &q->patterns[pi];
        for (int ni = 0; ni < pat->node_count; ni++) {
            const char *var = pat->nodes[ni].variable;
            if (var && !scope_holds(out, n, var)) {
                if (n >= cap) {
                    return -1;
                }
                out[n++] = var;
            }
        }
        for (int ri = 0; ri < pat->rel_count; ri++) {
            const char *var = pat->rels[ri].variable;
            if (var && !scope_holds(out, n, var)) {
                if (n >= cap) {
                    return -1;
                }
                out[n++] = var;
            }
        }
    }
    if (q->unwind_alias && !scope_holds(out, n, q->unwind_alias)) {
        if (n >= cap) {
            return -1;
        }
        out[n++] = q->unwind_alias;
    }
    return n;
}

/* What a

lect_with_names(const cbm_return_clause_t *wc, const char **out, int cap) {
    int n = 0;
    for (int i = 0; i < wc->count; i++) {
        const cbm_return_item_t *item = &wc->items[i];
        const char *name = NULL;
        if (item->alias) {
            name = item->alias;
        } else if (item->variable && !item->property && !item->func) {
            name = item->variable;
        }
        if (name && !scope_holds(out, n, name)) {
            if (n >= cap) {
                return -1;
            }
            out[n++] = name;
        }
    }
    return n;
}

/* Build the

cope_error(const char *var, const char *clause, const char *why) {
    char buf[CBM_SZ_256];
    snprintf(buf, sizeof(buf), "variable '%s' is not in scope for %s — %s", var, clause, why);
    return heap_strdup(buf);
}

/* The variabl

r *scope_checkable_var(const cbm_return_item_t *item) {
    if (item->kase || !item->variable) {
        return NULL;
    }
    if (strcmp(item->variable, "*") == 0) {
        return NULL;
    }
    return item->variable;
}

/* Answers NUL

ck_projection_scope(const cbm_query_t *q) {
    const char *declared[CYP_SCOPE_MAX_NAMES];
    int declared_n = collect_declared_names(q, declared, CYP_SCOPE_MAX_NAMES);
    if (declared_n < 0) {
        return NULL; /* too many names to model — stay quiet rather than guess */
    }

    /* A WITH still reads the pattern variables. */
    if (q->with_clause && !q->with_clause->star) {
        for (int i = 0; i < q->with_clause->count; i++) {
            const char *var = scope_checkable_var(&q->with_clause->items[i]);
            if (var && !scope_holds(declared, declared_n, var)) {
                return scope_error(var, "WITH", "no pattern in this query names it");
            }
        }
    }

    if (!q->ret || q->ret->star) {
        return NULL;
    }

    /* A RETURN after a WITH reads only what the WITH left behind. */
    const char *after_with[CYP_SCOPE_MAX_NAMES];
    const char *const *scope = declared;
    int scope_n = declared_n;
    if (q->with_clause) {
        scope_n = collect_with_names(q->with_clause, after_with, CYP_SCOPE_MAX_NAMES);
        if (scope_n < 0) {
            return NULL;
        }
        scope = after_with;
    }

    for (int i = 0; i < q->ret->count; i++) {
        const char *var = scope_checkable_var(&q->ret->items[i]);
        if (var && !scope_holds(scope, scope_n, var)) {
            return scope_error(var, "RETURN",
                               q->with_clause ? "the WITH clause did not carry it through"
                                              : "no pattern in this query names it");
        }
    }
    return NULL;
}

