        if (p->fips.p2 != NULL && !OSSL_PARAM_set_BN(p->fips.p2, t->p2))
        if (p->fips.q1 != NULL && !OSSL_PARAM_set_BN(p->fips.q1, t->q1))
        if (p->fips.q2 != NULL && !OSSL_PARAM_set_BN(p->fips.q2, t->q2))
int ossl_rsa_acvp_test_get_params(RSA *r, OSSL_PARAM params[])
{
    RSA_PARAMS p;

    if (!rsa_acvp_output_decoder(params, &p))
        return 0;
    return ossl_rsa_acvp_test_get_params_parsed(r, &p);
}

static int pkcs12_parse_existing_ca_mfail_test(void)
{
    int i, ret = -1;
    PKCS12 *p12 = NULL;
    STACK_OF(X509) *ca = NULL, *initial_ca = NULL;
    X509 *initial_certs[3] = { NULL };

    if (!TEST_ptr(p12 = PKCS12_load(in_file))
        || !TEST_ptr(ca = sk_X509_new_null()))
        goto err;

    for (i = 0; i < 3; i++) {
        if (!TEST_ptr(initial_certs[i] = X509_new()))
            goto err;

        if (!TEST_true(sk_X509_push(ca, initial_certs[i]))) {
            X509_free(initial_certs[i]);
            goto err;
        }
    }
    initial_ca = ca;

    MFAIL_start();
    ret = PKCS12_parse(p12, in_pass, NULL, NULL, &ca);
    MFAIL_end();

    if (ret == 0
        && (!TEST_ptr_eq(ca, initial_ca)
            || !TEST_int_eq(sk_X509_num(ca), 3)
            || !TEST_ptr_eq(sk_X509_value(ca, 0), initial_certs[0])
            || !TEST_ptr_eq(sk_X509_value(ca, 1), initial_certs[1])
            || !TEST_ptr_eq(sk_X509_value(ca, 2), initial_certs[2])))
        ret = -1;

err:
    PKCS12_free(p12);
    OSSL_STACK_OF_X509_free(ca);
    return ret;
}

int FuzzerTestOneInput(const uint8_t *buf, size_t len)
{
    BIO *in = NULL;
    CONF *conf = NULL;
    X509 *cert = NULL;
    X509V3_CTX ctx;

    if (len == 0)
        return 0;

    if (len > MAX_INPUT_SIZE)
        len = MAX_INPUT_SIZE;

    in = BIO_new(BIO_s_mem());
    if (in == NULL)
        goto end;

    if ((size_t)BIO_write(in, buf, (int)len) != len)
        goto end;

    conf = NCONF_new(NULL);
    if (conf == NULL)
        goto end;

    if (NCONF_load_bio(conf, in, NULL) <= 0)
        goto end;

    cert = X509_new();
    if (cert != NULL) {
        X509V3_set_ctx(&ctx, cert, cert, NULL, NULL, 0);
        X509V3_set_nconf(&ctx, conf);
        X509V3_EXT_add_nconf(conf, &ctx, "default", cert);
        X509_free(cert);
        cert = NULL;
    }

    cert = X509_new();
    if (cert != NULL) {
        X509V3_set_ctx(&ctx, NULL, NULL, NULL, NULL, 0);
        X509V3_set_nconf(&ctx, conf);
        X509V3_EXT_add_nconf(conf, &ctx, "default", cert);
    }

end:
    X509_free(cert);
    NCONF_free(conf);
    BIO_free(in);
    ERR_clear_error();

    return 0;
}

int ossl_dtls_conn_wait_for_write(SSL *s)
{
    SSL_CONNECTION *sc = SSL_CONNECTION_FROM_SSL_ONLY(s);
    DTLS_LISTENER *dl;
    int fatal;

    if (sc == NULL || sc->d1 == NULL || sc->d1->listener == NULL)
        return 0;

    dl = (DTLS_LISTENER *)sc->d1->listener;

    ossl_crypto_mutex_lock(dl->mutex);
    fatal = dl->fatal;
    ossl_crypto_mutex_unlock(dl->mutex);
    if (fatal)
        return 0;

    return ossl_dtls_block_until_ready(s, SSL_POLL_EVENT_W,
        ossl_time_infinite(), /*bound_by_event_timeout=*/0);
}

static int rlayer_dtls_block_for_write(void *cbarg)
{
    SSL_CONNECTION *s = cbarg;

    if (s == NULL || s->d1 == NULL || s->d1->listener == NULL
        || !ossl_dtls_blocking(SSL_CONNECTION_GET_SSL(s)))
        return 0;

    return ossl_dtls_conn_wait_for_write(SSL_CONNECTION_GET_SSL(s));
}

static long failing_send_ctrl(BIO *bio, int cmd, long num, void *ptr)
{
    BIO *next = BIO_next(bio);

    if (next == NULL)
        return 0;

    if (cmd == BIO_CTRL_DUP)
        return 0L;

    /*
     * Everything else, the poll descriptors in particular, has to reach the
     * socket underneath: the blocking write waits on the descriptor this
     * returns.
     */
    return BIO_ctrl(next, cmd, num, ptr);
}

static int failing_send_sendmmsg(BIO *bio, BIO_MSG *msg, size_t stride,
    size_t num_msg, uint64_t flags, size_t *msgs_processed)
{
    struct failing_send_data *data = BIO_get_data(bio);
    BIO *next = BIO_next(bio);

    if (data == NULL || next == NULL)
        return 0;

    data->sends++;

    if (data->fails_remaining > 0) {
        data->fails_remaining--;
        *msgs_processed = 0;
        /*
         * BIO_err_is_non_fatal() accepts this, so the record layer treats the
         * send as one to be attempted again rather than as an error.
         */
        ERR_raise(ERR_LIB_BIO, BIO_R_NON_FATAL);
        return 0;
    }

    return BIO_sendmmsg(next, msg, stride, num_msg, flags, msgs_processed);
}

static const BIO_METHOD *bio_f_failing_send_filter(void)
{
    if (method_failing_send == NULL) {
        method_failing_send = BIO_meth_new(BIO_TYPE_FAILING_SEND_FILTER,
            "Failing datagram send filter");
        if (method_failing_send == NULL
            || !BIO_meth_set_ctrl(method_failing_send, failing_send_ctrl)
            || !BIO_meth_set_sendmmsg(method_failing_send,
                failing_send_sendmmsg))
            return NULL;
    }
    return method_failing_send;
}

static int test_dtls_blocking_write(void)
{
    SSL_CTX *sctx = NULL, *cctx = NULL;
    SSL *listener = NULL, *clientssl = NULL, *serverssl = NULL;
    BIO_ADDR *server_addr = NULL;
    BIO *sockbio = NULL, *filter = NULL;
    struct failing_send_data data;
    int server_fd = -1, client_fd = -1;
    int testresult = 0;
    char buf[256];
    size_t written = 0, readbytes = 0;
    int i, ret = -1;

    memset(&data, 0, sizeof(data));

    if (!TEST_true(create_ssl_ctx_pair(NULL, DTLS_server_method(),
            DTLS_client_method(), DTLS1_VERSION, 0, &sctx, &cctx, cert,
            privkey)))
        goto end;

    if (!TEST_true(create_dtls_listener(sctx, SSL_LISTENER_FLAG_SINGLE_THREAD,
            &listener, &server_addr, &server_fd)))
        goto end;

    /*
     * Insert the filter in front of the listener's socket for writes only,
     * leaving reads to reach the socket directly. The listener holds a
     * reference for each direction, so the filter chain needs one of its own.
     */
    if (!TEST_ptr(sockbio = SSL_get_wbio(listener))
        || !TEST_ptr(filter = BIO_new(bio_f_failing_send_filter())))
        goto end;

    BIO_set_data(filter, &data);
    BIO_set_init(filter, 1);

    if (!TEST_true(BIO_up_ref(sockbio))) {
        BIO_free(filter);
        goto end;
    }

    BIO_push(filter, sockbio);
    SSL_set0_wbio(listener, filter); /* the listener owns the chain now */
    filter = NULL;

    if (!TEST_true(create_dtls_client_for_addr(cctx, server_addr, &clientssl,
            &client_fd)))
        goto end;

    if (!drive_until_connection_queued(listener, clientssl)
        || !TEST_ptr(serverssl = SSL_accept_connection(listener,
                         SSL_ACCEPT_CONNECTION_NO_BLOCK)))
        goto end;

    if (!TEST_true(create_ssl_connection(serverssl, clientssl, SSL_ERROR_NONE)))
        goto end;

    /*
     * Everything up to here, including any post-handshake traffic, has gone
     * through the filter untouched. Reject the next send only.
     */
    if (!TEST_true(SSL_set_blocking_mode(serverssl, 1))
        || !TEST_int_eq(SSL_get_blocking_mode(serverssl), 1))
        goto end;

    data.sends = 0;
    data.fails_remaining = 1;

    if (!TEST_true(SSL_write_ex(serverssl, "msg", 3, &written))
        || !TEST_size_t_eq(written, 3))
        goto end;

    /*
     * The send really was rejected, and was retried rather than reported: the
     * count proves a second attempt was made, which is the whole behaviour
     * under test. Without it, a write which never reached the filter at all
     * would look the same as one which was retried.
     */
    if (!TEST_int_eq(data.fails_remaining, 0)
        || !TEST_int_ge(data.sends, 2))
        goto end;

    /* The datagram reached the client, so nothing was dropped on the way. */
    for (i = 0; i < 20; i++) {
        ret = SSL_read_ex(clientssl, buf, sizeof(buf), &readbytes);
        if (ret == 1)
            break;
        if (!TEST_int_eq(SSL_get_error(clientssl, ret), SSL_ERROR_WANT_READ))
            goto end;
        OSSL_sleep(10);
    }

    if (!TEST_int_eq(ret, 1)
        || !TEST_mem_eq(buf, readbytes, "msg", 3))
        goto end;

    testresult = 1;
end:
    SSL_free(serverssl);
    SSL_free(clientssl);
    SSL_free(listener);
    BIO_ADDR_free(server_addr);
    if (server_fd >= 0)
        BIO_closesocket(server_fd);
    if (client_fd >= 0)
        BIO_closesocket(client_fd);
    SSL_CTX_free(sctx);
    SSL_CTX_free(cctx);
    BIO_meth_free(method_failing_send);
    method_failing_send = NULL;
    return testresult;
}

int ossl_dtls_conn_wait_for_datagram(SSL *s)
{
    SSL_CONNECTION *sc = SSL_CONNECTION_FROM_SSL_ONLY(s);
    DTLS_LISTENER *dl;
    int empty;

    if (sc == NULL || sc->d1 == NULL || sc->d1->rx == NULL
        || sc->d1->listener == NULL)
        return 0;

    dl = (DTLS_LISTENER *)sc->d1->listener;

    for (;;) {
        ossl_crypto_mutex_lock(dl->mutex);
        if (dl->fatal) {
            ossl_crypto_mutex_unlock(dl->mutex);
            return 0;
        }
        ossl_crypto_mutex_unlock(dl->mutex);

        /*
         * An infinite deadline here is bounded by the connection's own event
         * timeout, which the poll translation folds in, so this still wakes in
         * time to retransmit.
         */
        if (!ossl_dtls_block_until_ready(s, SSL_POLL_EVENT_R,
                ossl_time_infinite()))
            return 0;

        if (!SSL_handle_events(s))
            return 0;

        ossl_dgram_demux_pump(sc->d1->rx->demux);

        ossl_crypto_mutex_lock(sc->d1->rx->mutex);
        empty = ossl_list_urxe_is_empty(&sc->d1->rx->urxe_pending);
        ossl_crypto_mutex_unlock(sc->d1->rx->mutex);

        if (!empty)
            return 1;
    }
}

static int nonblocking_handshake(struct read_thread_args *ta)
{
    int i, ret = -1, err;

    if (!TEST_true(SSL_set_blocking_mode(ta->conn, 0)))
        return 0;

    for (i = 0; i < 200; i++) {
        ret = SSL_accept(ta->conn);
        if (ret == 1)
            break;
        err = SSL_get_error(ta->conn, ret);
        if (err != SSL_ERROR_WANT_READ && err != SSL_ERROR_WANT_WRITE) {
            TEST_error("SSL_accept failed (err %d)", err);
            return 0;
        }
        /* Nothing else will service the listener while we are in here. */
        if (!TEST_true(SSL_handle_events(ta->listener)))
            return 0;
        OSSL_sleep(10);
    }

    if (!TEST_int_eq(ret, 1))
        return 0;

    return TEST_true(SSL_set_blocking_mode(ta->conn, 1));
}

static unsigned int blocking_read_thread(void *arg)
{
    struct read_thread_args *ta = (struct read_thread_args *)arg;

    ta->conn = SSL_accept_connection(ta->listener, 0);
    if (!TEST_ptr(ta->conn))
        return 0;

    /*
     * A listener-created connection has no BIO of its own to block in - it
     * reads from a queue the listener demultiplexes into - so without the
     * emulation these calls return immediately with WANT_READ instead of
     * waiting.
     */
    if (ta->nonblocking_handshake) {
        if (!nonblocking_handshake(ta))
            return 0;
    } else if (!TEST_int_gt(SSL_accept(ta->conn), 0)) {
        return 0;
    }

    if (!TEST_true(SSL_read_ex(ta->conn, ta->buf, sizeof(ta->buf) - 1,
            &ta->readbytes)))
        return 0;

    ta->result = 1;
    return 0;
}

static int test_dtls_blocking_read(int idx)
{
    SSL_CTX *sctx = NULL, *cctx = NULL;
    SSL *listener = NULL, *client = NULL;
    struct read_thread_args read_args;
    BIO_ADDR *server_addr = NULL;
    int server_fd = -1, client_fd = -1;
    int testresult = 0;
    size_t written;
    int i, ret = -1, err;

    memset(&read_args, 0, sizeof(read_args));

    if (!TEST_true(create_ssl_ctx_pair(NULL, DTLS_server_method(),
            DTLS_client_method(), 0, 0, &sctx, &cctx, cert, privkey)))
        goto err;

    if (!TEST_true(create_listener(sctx, &listener, &server_addr, &server_fd)))
        goto err;

    /* Blocking is the default, but this test depends on it, so be explicit. */
    if (!TEST_true(SSL_set_blocking_mode(listener, 1)))
        goto err;

    /*
     * As in test_dtls_blocking_accept, create the client's socket before the
     * thread which will park in the blocking accept, because nothing can
     * release that thread except a connection arriving. Nothing is sent until
     * SSL_connect() below, so the accept still waits.
     */
    if (!TEST_true(create_client(cctx, server_addr, &client, &client_fd)))
        goto err;

    read_args.listener = listener;
    read_args.nonblocking_handshake = idx;
    read_args.thread = ossl_crypto_thread_native_start(blocking_read_thread,
        &read_args, 1);
    if (!TEST_ptr(read_args.thread))
        goto err;

    /* Drive the client's handshake to completion. */
    SSL_set_connect_state(client);
    for (i = 0; i < 200; i++) {
        ret = SSL_connect(client);
        if (ret == 1)
            break;
        err = SSL_get_error(client, ret);
        if (err != SSL_ERROR_WANT_READ && err != SSL_ERROR_WANT_WRITE) {
            TEST_error("SSL_connect failed (err %d)", err);
            goto err;
        }
        OSSL_sleep(10);
    }
    if (!TEST_int_eq(ret, 1))
        goto err;

    /* Let the server thread reach its read and find nothing there. */
    OSSL_sleep(BLOCKING_READ_QUIET_MS);

    if (!TEST_true(SSL_write_ex(client, CLIENT_TO_SERVER_MSG,
            strlen(CLIENT_TO_SERVER_MSG), &written)))
        goto err;

    ossl_crypto_thread_native_join(read_args.thread, NULL);
    ossl_crypto_thread_native_clean(read_args.thread);
    read_args.thread = NULL;

    if (!TEST_int_eq(read_args.result, 1))
        goto err;

    read_args.buf[read_args.readbytes] = '\0';
    if (!TEST_str_eq(read_args.buf, CLIENT_TO_SERVER_MSG))
        goto err;

    testresult = 1;
err:
    if (read_args.thread != NULL) {
        ossl_crypto_thread_native_join(read_args.thread, NULL);
        ossl_crypto_thread_native_clean(read_args.thread);
    }
    SSL_free(read_args.conn);
    SSL_free(client);
    SSL_free(listener);
    BIO_ADDR_free(server_addr);
    if (server_fd >= 0)
        BIO_closesocket(server_fd);
    if (client_fd >= 0)
        BIO_closesocket(client_fd);
    SSL_CTX_free(sctx);
    SSL_CTX_free(cctx);
    return testresult;
}

static int create_dtls_listener_unconfigured(SSL_CTX *sctx, uint64_t listener_flags,
/*
 * As create_dtls_listener_unconfigured(), but also opts out of blocking mode.
 *
 * These tests drive both ends of a handshake from a single thread, so the server
 * side must not block: a blocking read would wait for a client which only this
 * thread can advance. A listener is blocking by default, so opt out here rather
 * than in each test, and note that connections accepted from it inherit this.
 *
 * A test which needs to observe the default, or to exercise blocking mode, should
 * use create_dtls_listener_unconfigured() and configure what it needs.
 */
static int create_dtls_listener(SSL_CTX *sctx, uint64_t listener_flags,
    SSL **listener, BIO_ADDR **server_addr, int *server_fd)
{
    if (!create_dtls_listener_unconfigured(sctx, listener_flags, listener,
            server_addr, server_fd))
        return 0;

    if (!TEST_true(SSL_set_blocking_mode(*listener, 0))) {
        SSL_free(*listener);
        BIO_ADDR_free(*server_addr);
        if (*server_fd >= 0)
            BIO_closesocket(*server_fd);
        *listener = NULL;
        *server_addr = NULL;
        *server_fd = -1;
        return 0;
    }

    return 1;
}

static int ossl_dtls_desires_blocking(const SSL *s)
{
    const SSL_CONNECTION *sc = SSL_CONNECTION_FROM_CONST_SSL_ONLY(s);
    const DTLS_LISTENER *dl = NULL;

    if (sc != NULL && sc->d1 != NULL) {
        if (sc->d1->req_blocking_mode != DTLS_BLOCKING_MODE_INHERIT)
            return sc->d1->req_blocking_mode == DTLS_BLOCKING_MODE_BLOCKING;

        dl = (const DTLS_LISTENER *)sc->d1->listener;
    } else if (IS_DTLS_LISTENER(s)) {
        dl = (const DTLS_LISTENER *)s;
    }

    if (dl == NULL)
        return 0;

    return dl->req_blocking_mode != DTLS_BLOCKING_MODE_NONBLOCKING;
}

static int ossl_dtls_can_support_blocking(const SSL *s)
{
    const SSL_CONNECTION *sc = SSL_CONNECTION_FROM_CONST_SSL_ONLY(s);
    const SSL *listener = NULL;
    BIO_POLL_DESCRIPTOR desc;
    BIO *rbio;

    if (sc != NULL && sc->d1 != NULL)
        listener = sc->d1->listener;
    else if (IS_DTLS_LISTENER(s))
        listener = s;

    if (listener == NULL)
        return 0;

    rbio = SSL_get_rbio(listener);
    if (rbio == NULL)
        return 0;

    return BIO_get_rpoll_descriptor(rbio, &desc) != 0
        && desc.type == BIO_POLL_DESCRIPTOR_TYPE_SOCK_FD;
}

int ossl_dtls_set_blocking_mode(SSL *s, int blocking)
{
    SSL_CONNECTION *sc = SSL_CONNECTION_FROM_SSL_ONLY(s);
    unsigned int mode = (blocking != 0)
        ? DTLS_BLOCKING_MODE_BLOCKING
        : DTLS_BLOCKING_MODE_NONBLOCKING;

    /*
     * Only a listener, or a connection created from one, has a blocking mode.
     * Any other DTLS object takes its behaviour from its own BIO in the
     * traditional way, so there is nothing here to configure.
     */
    if (!IS_DTLS_LISTENER(s)
        && (sc == NULL || sc->d1 == NULL || sc->d1->listener == NULL)) {
        ERR_raise(ERR_LIB_SSL, ERR_R_PASSED_INVALID_ARGUMENT);
        return 0;
    }

    /*
     * Refuse to claim blocking we cannot deliver, as QUIC does. Checked before
     * anything is written, so that a call which fails leaves the mode alone
     * rather than reporting failure having already changed it.
     */
    if (blocking && !ossl_dtls_can_support_blocking(s)) {
        ERR_raise(ERR_LIB_SSL, ERR_R_UNSUPPORTED);
        return 0;
    }

    if (IS_DTLS_LISTENER(s))
        ((DTLS_LISTENER *)s)->req_blocking_mode = mode;
    else
        sc->d1->req_blocking_mode = mode;

    return 1;
}

int ossl_dtls_get_blocking_mode(const SSL *s)
{
    const SSL_CONNECTION *sc = SSL_CONNECTION_FROM_CONST_SSL_ONLY(s);

    if (!IS_DTLS_LISTENER(s)
        && (sc == NULL || sc->d1 == NULL || sc->d1->listener == NULL))
        return -1;

    return ossl_dtls_blocking(s);
}

static int drive_until_connection_queued(SSL *listener, SSL *clientssl)
{
    SSL_POLL_ITEM poll_item;
    struct timeval poll_timeout;
    size_t poll_result = 0;
    int abortctr, retc, err_code;

    poll_item.desc.type = BIO_POLL_DESCRIPTOR_TYPE_SSL;
    poll_item.desc.value.ssl = listener;
    poll_timeout.tv_sec = 0;
    poll_timeout.tv_usec = 0;

    SSL_set_connect_state(clientssl);

    for (abortctr = 0; abortctr < 100; abortctr++) {
        retc = SSL_connect(clientssl);
        err_code = SSL_get_error(clientssl, retc);
        if (retc <= 0
            && err_code != SSL_ERROR_WANT_READ
            && err_code != SSL_ERROR_WANT_WRITE) {
            TEST_error("SSL_connect failed (err %d)", err_code);
            return 0;
        }

        /* A zero timeout, so this ticks the listener without ever waiting. */
        poll_item.events = SSL_POLL_EVENT_IC;
        poll_item.revents = 0;

        if (!TEST_true(SSL_poll(&poll_item, 1, sizeof(poll_item), &poll_timeout,
                0, &poll_result)))
            return 0;

        if ((poll_item.revents & SSL_POLL_EVENT_IC) != 0)
            return 1;
    }

    TEST_error("cookie exchange loop did not converge");
    return 0;
}

static int test_dtls_blocking_mode(void)
{
    SSL_CTX *sctx = NULL, *cctx = NULL;
    SSL *listener = NULL, *clientssl = NULL, *serverssl = NULL;
    SSL *memlistener = NULL, *memclient = NULL, *plainssl = NULL;
    BIO_ADDR *server_addr = NULL, *client_addr = NULL;
    int server_fd = -1, client_fd = -1;
    int testresult = 0;

    if (!TEST_true(create_ssl_ctx_pair(NULL, DTLS_server_method(),
            DTLS_client_method(), DTLS1_VERSION, 0, &sctx, &cctx, cert,
            privkey)))
        goto end;

    /* A socket BIO supplies a poll descriptor, so blocking is available. */
    if (!TEST_true(create_dtls_listener(sctx,
            SSL_LISTENER_FLAG_REQUIRE_HVR | SSL_LISTENER_FLAG_REQUIRE_HRR
                | SSL_LISTENER_FLAG_SINGLE_THREAD,
            &listener, &server_addr, &server_fd)))
        goto end;

    /* Blocking by default, having never been configured. */
    if (!TEST_int_eq(SSL_get_blocking_mode(listener), 1))
        goto end;

    /* Get a connection object accepted from the listener to examine. */
    if (!TEST_true(create_dtls_client_for_addr(cctx, server_addr, &clientssl,
            &client_fd)))
        goto end;

    if (!drive_until_connection_queued(listener, clientssl)
        || !TEST_ptr(serverssl = SSL_accept_connection(listener,
                         SSL_ACCEPT_CONNECTION_NO_BLOCK)))
        goto end;

    /* It inherits the listener's mode. */

    if (!TEST_int_eq(SSL_get_blocking_mode(serverssl), 1))
        goto end;

    /* Setting the listener non-blocking is inherited by the connection. */
    if (!TEST_true(SSL_set_blocking_mode(listener, 0))
        || !TEST_int_eq(SSL_get_blocking_mode(listener), 0)
        || !TEST_int_eq(SSL_get_blocking_mode(serverssl), 0))
        goto end;

    /* A setting on the connection overrides what it would inherit. */
    if (!TEST_true(SSL_set_blocking_mode(serverssl, 1))
        || !TEST_int_eq(SSL_get_blocking_mode(serverssl), 1)
        || !TEST_int_eq(SSL_get_blocking_mode(listener), 0))
        goto end;

    /*
     * A connection's own setting survives SSL_clear(). The mode is a property
     * of the connection as the application configured it, not of the handshake,
     * and dtls1_clear() memsets d1 and restores only selected fields.
     *
     * The listener and the connection must disagree for this to prove anything:
     * were the connection's setting lost it would fall back to inheriting, and
     * that is only visible if the listener says something different.
     */
    if (!TEST_true(SSL_set_blocking_mode(listener, 1))
        || !TEST_true(SSL_set_blocking_mode(serverssl, 0))
        || !TEST_int_eq(SSL_get_blocking_mode(listener), 1)
        || !TEST_int_eq(SSL_get_blocking_mode(serverssl), 0))
        goto end;

    if (!TEST_true(SSL_clear(serverssl))
        || !TEST_int_eq(SSL_get_blocking_mode(serverssl), 0))
        goto end;

    /*
     * Clear again. SSL_clear() resets the method to the default one, so the
     * first call above went through the ssl_deinit/ssl_init path that
     * reallocates d1 while this one goes through dtls1_clear(). Both discard
     * d1, so both have to be covered.
     */
    if (!TEST_true(SSL_clear(serverssl))
        || !TEST_int_eq(SSL_get_blocking_mode(serverssl), 0))
        goto end;

    /* And back the other way round. */
    if (!TEST_true(SSL_set_blocking_mode(listener, 1))
        || !TEST_true(SSL_set_blocking_mode(serverssl, 0))
        || !TEST_int_eq(SSL_get_blocking_mode(listener), 1)
        || !TEST_int_eq(SSL_get_blocking_mode(serverssl), 0))
        goto end;

    /*
     * A listener on BIOs which cannot supply a poll descriptor reports
     * non-blocking however it was configured, and asking for blocking fails.
     */
    if (!TEST_true(create_dtls_listener_and_client_mem(sctx, cctx,
            SSL_LISTENER_FLAG_SINGLE_THREAD, &memlistener, &memclient,
            &client_addr)))
        goto end;

    if (!TEST_int_eq(SSL_get_blocking_mode(memlistener), 0))
        goto end;

    ERR_clear_error();
    if (!TEST_false(SSL_set_blocking_mode(memlistener, 1))
        || !TEST_int_eq((int)ERR_GET_REASON(ERR_peek_error()), ERR_R_UNSUPPORTED))
        goto end;
    ERR_clear_error();

    /* Asking for non-blocking is fine, that being what it already is. */
    if (!TEST_true(SSL_set_blocking_mode(memlistener, 0))
        || !TEST_int_eq(SSL_get_blocking_mode(memlistener), 0))
        goto end;

    /*
     * A DTLS object which did not come from a listener has no blocking mode:
     * it takes its behaviour from its own BIO in the traditional way.
     */
    if (!TEST_ptr(plainssl = SSL_new(cctx)))
        goto end;

    if (!TEST_int_eq(SSL_get_blocking_mode(plainssl), -1)
        || !TEST_false(SSL_set_blocking_mode(plainssl, 1))
        || !TEST_false(SSL_set_blocking_mode(plainssl, 0)))
        goto end;

    testresult = 1;
end:
    ERR_clear_error();
    SSL_free(plainssl);
    SSL_free(memclient);
    SSL_free(memlistener);
    SSL_free(serverssl);
    SSL_free(clientssl);
    SSL_free(listener);
    BIO_ADDR_free(client_addr);
    BIO_ADDR_free(server_addr);
    if (server_fd >= 0)
        BIO_closesocket(server_fd);
    if (client_fd >= 0)
        BIO_closesocket(client_fd);
    SSL_CTX_free(sctx);
    SSL_CTX_free(cctx);
    return testresult;
}

static int test_dtls_accept_wait_requires_mode_and_flag(void)
{
    SSL_CTX *sctx = NULL;
    SSL *listener = NULL;
    BIO_ADDR *server_addr = NULL;
    int server_fd = -1;
    int testresult = 0;

    if (!TEST_ptr(sctx = SSL_CTX_new(DTLS_server_method())))
        goto end;

    if (!TEST_true(create_dtls_listener(sctx, SSL_LISTENER_FLAG_SINGLE_THREAD,
            &listener, &server_addr, &server_fd)))
        goto end;

    /* Non-blocking mode, and no flag: the mode alone stops it waiting. */
    if (!TEST_true(SSL_set_blocking_mode(listener, 0))
        || !TEST_ptr_null(SSL_accept_connection(listener, 0)))
        goto end;

    /* Blocking mode, but the flag overrides it. */
    if (!TEST_true(SSL_set_blocking_mode(listener, 1))
        || !TEST_int_eq(SSL_get_blocking_mode(listener), 1)
        || !TEST_ptr_null(SSL_accept_connection(listener,
            SSL_ACCEPT_CONNECTION_NO_BLOCK)))
        goto end;

    testresult = 1;
end:
    SSL_free(listener);
    BIO_ADDR_free(server_addr);
    if (server_fd >= 0)
        BIO_closesocket(server_fd);
    SSL_CTX_free(sctx);
    return testresult;
}

static int test_dtls_blocking_mode_failed_set_is_inert(void)
{
    SSL_CTX *sctx = NULL;
    SSL *listener = NULL;
    BIO_ADDR *server_addr = NULL;
    BIO *rbio = NULL;
    int server_fd = -1;
    int testresult = 0;

    if (!TEST_ptr(sctx = SSL_CTX_new(DTLS_server_method())))
        goto end;

    if (!TEST_true(create_dtls_listener(sctx, SSL_LISTENER_FLAG_SINGLE_THREAD,
            &listener, &server_addr, &server_fd)))
        goto end;

    /* Ask for non-blocking explicitly, so the default cannot mask a change. */
    if (!TEST_true(SSL_set_blocking_mode(listener, 0))
        || !TEST_int_eq(SSL_get_blocking_mode(listener), 0))
        goto end;

    /* Keep the BIO, then take it away so blocking cannot be supported. */
    if (!TEST_ptr(rbio = SSL_get_rbio(listener))
        || !TEST_true(BIO_up_ref(rbio)))
        goto end;

    SSL_set0_rbio(listener, NULL);

    ERR_clear_error();
    if (!TEST_false(SSL_set_blocking_mode(listener, 1))
        || !TEST_int_eq((int)ERR_GET_REASON(ERR_peek_error()),
            ERR_R_UNSUPPORTED)) {
        BIO_free(rbio);
        goto end;
    }
    ERR_clear_error();

    /* Give the BIO back, which makes blocking supportable once more. */
    SSL_set0_rbio(listener, rbio);

    /* The refused request must not have taken effect. */
    if (!TEST_int_eq(SSL_get_blocking_mode(listener), 0))
        goto end;

    testresult = 1;
end:
    SSL_free(listener);
    BIO_ADDR_free(server_addr);
    if (server_fd >= 0)
        BIO_closesocket(server_fd);
    SSL_CTX_free(sctx);
    return testresult;
}

int ossl_dtls_block_until_ready(SSL *ssl, uint64_t events, OSSL_TIME deadline)
{
    SSL_POLL_ITEM item;
    size_t result_count = 0;

    item.desc.type = BIO_POLL_DESCRIPTOR_TYPE_SSL;
    item.desc.value.ssl = ssl;
    item.events = events;
    item.revents = 0;

    return poll_block(&item, 1, sizeof(item), deadline, &result_count);
}

static unsigned int blocking_accept_thread(void *arg)
{
    struct accept_thread_args *ta = (struct accept_thread_args *)arg;

    ta->conn = SSL_accept_connection(ta->listener, 0);
    ta->result = (ta->conn != NULL);
    return 1;
}

static int test_dtls_blocking_accept(void)
{
    SSL_CTX *sctx = NULL, *cctx = NULL;
    SSL *listener = NULL, *client = NULL;
    struct accept_thread_args accept_args;
    BIO_ADDR *server_addr = NULL;
    int server_fd = -1, client_fd = -1;
    int testresult = 0;
    int i, ret, err;

    memset(&accept_args, 0, sizeof(accept_args));

    if (!TEST_true(create_ssl_ctx_pair(NULL, DTLS_server_method(),
            DTLS_client_method(), 0, 0, &sctx, &cctx, cert, privkey)))
        goto err;

    if (!TEST_true(create_listener(sctx, &listener, &server_addr, &server_fd)))
        goto err;

    /*
     * Create the client's socket first, but do not connect with it yet. There
     * is no way to cancel a blocking SSL_accept_connection(), so a thread
     * parked in one is released only by a connection arriving - which means
     * nothing between starting the thread and the exchange completing may bail
     * out, or the join below would wait for ever. Anything which can fail is
     * therefore done up front. The accept still has to wait, since no datagram
     * is sent until SSL_connect() below.
     */
    if (!TEST_true(create_client(cctx, server_addr, &client, &client_fd)))
        goto err;

    accept_args.listener = listener;
    accept_args.thread = ossl_crypto_thread_native_start(blocking_accept_thread,
        &accept_args, 1);
    if (!TEST_ptr(accept_args.thread))
        goto err;

    /*
     * Drive the client's side of the cookie exchange. The accepting thread
     * ticks the listener, so this only has to keep the client moving.
     */
    SSL_set_connect_state(client);
    for (i = 0; i < 200 && accept_args.result == 0; i++) {
        ret = SSL_connect(client);
        err = SSL_get_error(client, ret);
        if (ret <= 0 && err != SSL_ERROR_WANT_READ && err != SSL_ERROR_WANT_WRITE) {
            TEST_error("SSL_connect failed (err %d)", err);
            goto err;
        }
        OSSL_sleep(10);
    }

    ossl_crypto_thread_native_join(accept_args.thread, NULL);
    ossl_crypto_thread_native_clean(accept_args.thread);
    accept_args.thread = NULL;

    if (!TEST_int_eq(accept_args.result, 1) || !TEST_ptr(accept_args.conn))
        goto err;

    testresult = 1;
err:
    if (accept_args.thread != NULL) {
        ossl_crypto_thread_native_join(accept_args.thread, NULL);
        ossl_crypto_thread_native_clean(accept_args.thread);
    }
    SSL_free(accept_args.conn);
    SSL_free(client);
    SSL_free(listener);
    BIO_ADDR_free(server_addr);
    if (server_fd >= 0)
        BIO_closesocket(server_fd);
    if (client_fd >= 0)
        BIO_closesocket(client_fd);
    SSL_CTX_free(sctx);
    SSL_CTX_free(cctx);
    return testresult;
}

static int rio_poll_builder_is_empty(const RIO_POLL_BUILDER *rpb)
{
#if RIO_POLL_METHOD == RIO_POLL_METHOD_SELECT
    return rpb->hwm_fd < 0;
#elif RIO_POLL_METHOD == RIO_POLL_METHOD_POLL
    return rpb->pfd_num == 0;
#else
    return 1;
#endif
}

static int test_dtls_timer_stopped_when_retransmits_exhausted(void)
{
    SSL_CTX *sctx = NULL, *cctx = NULL;
    SSL *clientssl = NULL, *serverssl = NULL;
    struct timeval timer_left;
    int is_infinite = 0;
    int retc, rets;
    int testresult = 0;

    if (!TEST_true(create_ssl_ctx_pair(NULL, DTLS_server_method(),
            DTLS_client_method(), DTLS1_VERSION, 0, &sctx, &cctx, cert,
            privkey)))
        goto end;

    if (!TEST_true(create_ssl_objects(sctx, cctx, &serverssl, &clientssl,
            NULL, NULL)))
        goto end;

    DTLS_set_timer_cb(serverssl, tiny_timer_cb);

    retc = SSL_connect(clientssl);
    if (!TEST_int_le(retc, 0)
        || !TEST_int_eq(SSL_get_error(clientssl, retc), SSL_ERROR_WANT_READ))
        goto end;

    /*
     * With a timeout this short the server's timer is expired on every read
     * attempt, so the accept retransmits until the budget runs out and fails
     * the connection by itself. The client is never fed, so nothing is ever
     * acknowledged.
     *
     * The retransmissions happen in dtls1_read_bytes(), which calls
     * dtls1_handle_timeout() and, when it reports that it retransmitted, goes
     * back to its start label to try the read again.
     */
    rets = SSL_accept(serverssl);
    if (!TEST_int_le(rets, 0)
        || !TEST_int_eq(SSL_get_error(serverssl, rets), SSL_ERROR_SSL))
        goto end;

    /* The timer must not have been left armed in the past. */
    if (!TEST_true(SSL_get_event_timeout(serverssl, &timer_left, &is_infinite))
        || !TEST_true(is_infinite))
        goto end;

    testresult = 1;
end:
    SSL_free(serverssl);
    SSL_free(clientssl);
    SSL_CTX_free(sctx);
    SSL_CTX_free(cctx);
    return testresult;
}

static unsigned int short_timer_cb(SSL *s, unsigned int timer_us)
{
    ++short_timer_cb_count;
    return 50000; /* 50ms */
}

static int test_dtls_poll_conn_honours_retransmit_timer(void)
{
    SSL_CTX *sctx = NULL, *cctx = NULL;
    SSL *clientssl = NULL, *serverssl = NULL;
    SSL_POLL_ITEM poll_item;
    struct timeval poll_timeout, timer_left;
    size_t poll_result = 0;
    int is_infinite = 0;
    int retc, rets, err_code;
    int testresult = 0;

    if (!TEST_true(create_ssl_ctx_pair(NULL, DTLS_server_method(),
            DTLS_client_method(), DTLS1_VERSION, 0, &sctx, &cctx, cert,
            privkey)))
        goto end;

    if (!TEST_true(create_ssl_objects(sctx, cctx, &serverssl, &clientssl,
            NULL, NULL)))
        goto end;

    /*
     * Install the short timeout before the server sends anything, so that it
     * is picked up when the retransmission timer is first started rather than
     * only on a later expiry.
     */
    DTLS_set_timer_cb(serverssl, short_timer_cb);

    /*
     * Drive just far enough for the server to send its first flight and start
     * its retransmission timer. The client is then left alone, so the flight
     * stays unacknowledged for the duration of the poll.
     */
    retc = SSL_connect(clientssl);
    if (!TEST_int_le(retc, 0)
        || !TEST_int_eq(SSL_get_error(clientssl, retc), SSL_ERROR_WANT_READ))
        goto end;

    /*
     * The server consumes the ClientHello, sends its flight and then waits for
     * the client, so this does not complete the handshake.
     */
    rets = SSL_accept(serverssl);
    if (!TEST_int_le(rets, 0))
        goto end;

    err_code = SSL_get_error(serverssl, rets);
    if (!TEST_true(err_code == SSL_ERROR_WANT_READ
            || err_code == SSL_ERROR_WANT_WRITE))
        goto end;

    /*
     * Assert the precondition through the same call SSL_poll() uses to compute
     * its deadline: a running timer is reported as a finite timeout.
     */
    if (!TEST_true(SSL_get_event_timeout(serverssl, &timer_left, &is_infinite))
        || !TEST_false(is_infinite))
        goto end;

    short_timer_cb_count = 0;

    /*
     * Nothing will arrive for this connection during the poll, so it runs to
     * its deadline. Along the way the retransmission timer must expire and be
     * serviced, which re-arms the timer via the callback.
     */
    poll_item.desc.type = BIO_POLL_DESCRIPTOR_TYPE_SSL;
    poll_item.desc.value.ssl = serverssl;
    poll_item.events = SSL_POLL_EVENT_R;
    poll_item.revents = 0;
    poll_timeout.tv_sec = 0;
    poll_timeout.tv_usec = 500000;

    if (!TEST_true(SSL_poll(&poll_item, 1, sizeof(poll_item), &poll_timeout, 0,
            &poll_result)))
        goto end;

    if (!TEST_uint_gt(short_timer_cb_count, 0))
        goto end;

    testresult = 1;
end:
    SSL_free(serverssl);
    SSL_free(clientssl);
    SSL_CTX_free(sctx);
    SSL_CTX_free(cctx);
    return testresult;
}

static void postpoll_translation_cleanup_ssl_dtls_listener(SSL *ssl)
{
    DTLS_LISTENER *dl = (DTLS_LISTENER *)ssl;

    /* Need to mirror the enter blocking section call */
    if (dl->have_notifier && ossl_rio_notifier_as_fd(&dl->notifier) != -1)
        ossl_dtls_listener_leave_blocking_section(ssl);
}

static void dtls_listener_signal_notifier(DTLS_LISTENER *dl)
{
    if (dl->have_notifier && dl->cur_blocking_waiters > 0
        && !dl->signalled_notifier) {
        ossl_rio_notifier_signal(&dl->notifier);
        dl->signalled_notifier = 1;
    }
}

static int test_dtls_notifier_signalled_on_accept_queue_push(void)
{
    SSL_CTX *sctx = NULL, *cctx = NULL;
    SSL *listener = NULL, *clientssl = NULL;
    BIO_ADDR *server_addr = NULL;
    DTLS_LISTENER *dl;
    SSL_POLL_ITEM poll_item;
    struct timeval poll_timeout;
    size_t poll_result = 0;
    int server_fd = -1, client_fd = -1;
    int in_blocking_section = 0;
    int abortctr, retc, err_code;
    int testresult = 0;

    if (!TEST_true(create_ssl_ctx_pair(NULL, DTLS_server_method(),
            DTLS_client_method(), DTLS1_VERSION, 0, &sctx, &cctx, cert,
            privkey)))
        goto end;

    /*
     * Multi-threaded mode (no SSL_LISTENER_FLAG_SINGLE_THREAD) so that the
     * listener has a notifier at all.
     */
    if (!TEST_true(create_dtls_listener(sctx,
            SSL_LISTENER_FLAG_REQUIRE_HVR | SSL_LISTENER_FLAG_REQUIRE_HRR,
            &listener, &server_addr, &server_fd)))
        goto end;

    dl = (DTLS_LISTENER *)listener;
    if (!TEST_true(dl->have_notifier))
        goto end;

    if (!TEST_true(create_dtls_client_for_addr(cctx, server_addr, &clientssl,
            &client_fd)))
        goto end;

    /* Pose as a thread waiting for readiness, so signalling is enabled. */
    ossl_dtls_listener_enter_blocking_section(listener);
    in_blocking_section = 1;

    /*
     * Drive the cookie exchange, splitting each round into its two halves so
     * that the two signalling opportunities can be told apart:
     *
     *   - demuxing a datagram to a connection's receive queue, which the
     *     packet handler has always signalled, and
     *   - completing a connection and pushing it onto the accept queue.
     *
     * Pumping the demux directly performs only the first. The signal it
     * raises is then cleared, so when the listener is next ticked the pump
     * finds nothing new and only the accept queue push can signal.
     *
     * There is no public API for that split: SSL_poll() and
     * SSL_accept_connection() both tick the listener, which does the two
     * together.
     */
    poll_item.desc.type = BIO_POLL_DESCRIPTOR_TYPE_SSL;
    poll_item.desc.value.ssl = listener;
    poll_timeout.tv_sec = 0;
    poll_timeout.tv_usec = 0;

    SSL_set_connect_state(clientssl);
    for (abortctr = 0; abortctr < 100; abortctr++) {
        retc = SSL_connect(clientssl);
        err_code = SSL_get_error(clientssl, retc);
        if (retc <= 0
            && err_code != SSL_ERROR_WANT_READ
            && err_code != SSL_ERROR_WANT_WRITE) {
            TEST_error("SSL_connect failed (err %d)", err_code);
            goto end;
        }

        ossl_dgram_demux_pump(dl->demux);

        ossl_dtls_listener_leave_blocking_section(listener);
        in_blocking_section = 0;
        if (!TEST_int_eq(dl->signalled_notifier, 0))
            goto end;
        ossl_dtls_listener_enter_blocking_section(listener);
        in_blocking_section = 1;

        /*
         * A zero timeout, so this ticks the listener and reads out the result
         * without ever blocking, and therefore without itself entering a
         * blocking section and clearing the signal we are watching for.
         */
        poll_item.events = SSL_POLL_EVENT_IC;
        poll_item.revents = 0;

        if (!TEST_true(SSL_poll(&poll_item, 1, sizeof(poll_item), &poll_timeout,
                0, &poll_result)))
            goto end;

        if ((poll_item.revents & SSL_POLL_EVENT_IC) != 0)
            break;
    }

    if (!TEST_size_t_gt(SSL_get_accept_connection_queue_len(listener), 0))
        goto end;

    /* The accept queue push must have woken any waiter. */
    if (!TEST_int_eq(dl->signalled_notifier, 1))
        goto end;

    testresult = 1;
end:
    if (in_blocking_section)
        ossl_dtls_listener_leave_blocking_section(listener);
    SSL_free(clientssl);
    SSL_free(listener);
    BIO_ADDR_free(server_addr);
    if (server_fd >= 0)
        BIO_closesocket(server_fd);
    if (client_fd >= 0)
        BIO_closesocket(client_fd);
    SSL_CTX_free(sctx);
    SSL_CTX_free(cctx);
    return testresult;
}

static void rteth_enable_napi(struct rteth_ctrl *ctrl)
{
	for (int i = 0; i < RTETH_RX_RINGS; i++)
		napi_enable(&ctrl->rx_info[i].napi);
	ctrl->napi_enabled = true;
}

static void rteth_disable_napi(struct rteth_ctrl *ctrl)
{
	if (!ctrl->napi_enabled)
		return;

	ctrl->napi_enabled = false;
	for (int i = 0; i < RTETH_RX_RINGS; i++)
		napi_disable(&ctrl->rx_info[i].napi);
}

static void rtldsa_838x_stat_init(struct rtl838x_switch_priv *priv)
{
	/* Enable statistics module: all counters plus debug */
	sw_w32_mask(0, 3, RTL838X_STAT_CTRL);
}

static void rteth_reset_work(struct work_struct *work)
{
	struct rteth_ctrl *ctrl = container_of(work, struct rteth_ctrl, reset_work);
	struct net_device *dev = ctrl->dev;
	int ret;

	rtnl_lock();

	if (!netif_running(dev))
		goto out;

	rteth_stop(dev);
	ret = rteth_open(dev);
	if (ret) {
		netdev_err(dev, "tx timeout recovery failed: %d\n", ret);
		netif_device_detach(dev);
		goto out;
	}

	netif_trans_update(dev);

out:
	rtnl_unlock();
}

static void close_socket(uv_os_sock_t sock) {
#ifdef _WIN32
  ASSERT_OK(closesocket(sock));
#else
  ASSERT_OK(close(sock));
#endif
}

int uv__write_cancel(uv_write_t* req) {
  struct uv__queue* q;
  uv_stream_t* stream;

  stream = req->handle;

  /* N.B.: If the request already completed, we still return 0, but the callback
    will not return ECANCELED - nothing to do here. */
  uv__queue_foreach(q, &stream->write_queue) {
    if (q == &req->queue) {
      uv__queue_remove(&req->queue);
      req->error = UV_ECANCELED;

      /* uv__write_callbacks will handle write_queue_size and freeing bufs. */
      uv__queue_insert_tail(&stream->write_completed_queue, &req->queue);
      uv__io_feed(stream->loop, &stream->io_watcher);
      break;
    }
  }

  return 0;
}

static void uv__pipe_cancel_synchronous_io(volatile HANDLE* thread_ptr,
                                            CRITICAL_SECTION* lock) {
  HANDLE thread;
  HANDLE expected_invalid = INVALID_HANDLE_VALUE;
  EnterCriticalSection(lock);

  thread = *thread_ptr;
  if (thread == NULL) {
    /* The thread pool thread has not yet reached the point of blocking, we
     * can pre-empt it here. However, we still need to wait for the thread
     * to acknowledge the interrupt. Otherwise it could race with the next
     * request. It does this by setting *thread_ptr back to NULL. */
    *thread_ptr = INVALID_HANDLE_VALUE;
    do {
      LeaveCriticalSection(lock);
      WaitOnAddress(thread_ptr, &expected_invalid, sizeof(*thread_ptr), INFINITE);
      EnterCriticalSection(lock);
    } while (*thread_ptr != NULL);
    /* Finally set this back to INVALID_HANDLE_VALUE to retain the
     * invariant that it'll be INVALID_HANDLE_VALUE on exit from this function. */
    *thread_ptr = INVALID_HANDLE_VALUE;
  } else {
    /* Spin until the thread has acknowledged (by changing *thread_ptr)
     * that it is past the point of blocking. */
    while (thread != INVALID_HANDLE_VALUE) {
      BOOL r = CancelSynchronousIo(thread);
      assert(r || GetLastError() == ERROR_NOT_FOUND);
      LeaveCriticalSection(lock);
      SwitchToThread();
      EnterCriticalSection(lock);
      thread = *thread_ptr;
    }
  }
  LeaveCriticalSection(lock);
}

void uv__pipe_interrupt_read(uv_pipe_t* handle) {
  if (handle->flags & UV_HANDLE_READ_CANCELLATION_PENDING)
    BOOL r = CancelIoEx(handle->handle, &handle->read_req.u.io.overlapped);
    uv__pipe_cancel_synchronous_io(
        &handle->pipe.conn.readfile_thread_handle,
        &handle->pipe.conn.thread_lock);
  handle->flags |= UV_HANDLE_READ_CANCELLATION_PENDING;
/* Remove the element after prev from the non-overlapped write queue.
 * prev must be a node in the queue. Returns the removed element. */
static uv_write_t* uv__remove_non_overlapped_write_req_after(
    uv_pipe_t* handle, uv_write_t* prev) {
  uv_write_t* req;

  req = (uv_write_t*) prev->next_req;
  if (req == prev) {
    /* Only element. */
    handle->pipe.conn.non_overlapped_writes_tail = NULL;
  } else {
    prev->next_req = req->next_req;
    if (req == handle->pipe.conn.non_overlapped_writes_tail)
      handle->pipe.conn.non_overlapped_writes_tail = prev;
  }
  return req;
}


static uv_write_t* uv__remove_non_overlapped_write_req(uv_pipe_t* handle) {
  if (handle->pipe.conn.non_overlapped_writes_tail == NULL)
    return NULL;

  return uv__remove_non_overlapped_write_req_after(
      handle, handle->pipe.conn.non_overlapped_writes_tail);
}


/* Find and remove a specific request from the non-overlapped write queue.
 * Returns the queued req if found and removed, NULL otherwise. */
static uv_write_t* uv__remove_specific_non_overlapped_write_req(
    uv_pipe_t* handle, uv_write_t* target) {
  uv_write_t* tail;
  uv_write_t* prev;
  uv_write_t* curr;

  tail = handle->pipe.conn.non_overlapped_writes_tail;
  if (tail == NULL)
    return NULL;

  prev = tail;
  curr = (uv_write_t*) tail->next_req;
  do {
    if (curr == target)
      return uv__remove_non_overlapped_write_req_after(handle, prev);

    prev = curr;
    curr = (uv_write_t*) curr->next_req;
  } while (prev != tail);

  return NULL;
}


int uv__pipe_write_cancel_non_overlapped(uv_pipe_t* handle, uv_write_t* req) {
  uv_write_t* queued_req;

  assert(handle->flags & UV_HANDLE_NON_OVERLAPPED_PIPE);
  assert(!(handle->flags & UV_HANDLE_BLOCKING_WRITES));

  /* On the thread pool - send the cancellation signal. */
  if (handle->pipe.conn.non_overlapped_write_active == req) {
    /* N.B.: It's possible to end up here multiple times if `req` is cancelled
     * again after an initial cancellation, but before the completion is processed.
     * This is harmless - uv__pipe_cancel_synchronous_io will see that the thread
     * has concluded and do nothing. */
    uv__pipe_cancel_synchronous_io(
        &handle->pipe.conn.writefile_thread_handle,
        &handle->pipe.conn.thread_lock);
    return 0;
  }

  /* If it's in the queue, remove and complete it as cancelled. */
  queued_req = uv__remove_specific_non_overlapped_write_req(handle, req);
  if (queued_req != NULL) {
    SET_REQ_ERROR(queued_req, ERROR_OPERATION_ABORTED);
    SET_REQ_NWRITTEN(queued_req, 0);
    uv__insert_pending_req(handle->loop, (uv_req_t*) queued_req);
    return 0;
  }

  /* Already completed (including previously cancelled). */
  return 0;
}

/* Cancel all active and pending non-overlapped writes. */
static void uv__pipe_flush_non_overlapped_writes(uv_pipe_t* handle) {
  uv_write_t* req;

  /* Cancel the active write if there is one. */
  if (handle->pipe.conn.non_overlapped_write_active != NULL)
    uv__pipe_cancel_synchronous_io(
        &handle->pipe.conn.writefile_thread_handle,
        &handle->pipe.conn.thread_lock);

  /* Drain the entire queue. */
  while ((req = uv__remove_non_overlapped_write_req(handle)) != NULL) {
    SET_REQ_ERROR(req, ERROR_OPERATION_ABORTED);
    SET_REQ_NWRITTEN(req, 0);
    uv__insert_pending_req(handle->loop, (uv_req_t*) req);
  }
}


    if (handle->flags & UV_HANDLE_NON_OVERLAPPED_PIPE) {
      /* The non-overlapped writer thread reads handle->handle. To avoid
       * the possibility of a stale value, we must shoot it down now before we
       * close the handle. While we're at it, cancel the whole queue, to
       * avoid putting things on the thread pool only for them to come straight
       * back with an invalid handle error. */
      uv__pipe_flush_non_overlapped_writes(handle);
    }

/* Register the current thread for cancellation via CancelSynchronousIo.
 * Returns 0 on success, or a Windows error code on failure (including
 * ERROR_OPERATION_ABORTED if pre-empted by uv__pipe_cancel_synchronous_io).
 * On success, the caller must call uv__pipe_end_synchronous_io after the
 * blocking operation. On failure, the caller must not. */
static DWORD uv__pipe_begin_synchronous_io(volatile HANDLE* thread_ptr,
                                            CRITICAL_SECTION* lock,
                                            HANDLE* thread_out) {
    /* Even if we failed here, we still need to synchronize */
    DWORD err = GetLastError();
    EnterCriticalSection(lock);
    *thread_ptr = *thread_ptr == INVALID_HANDLE_VALUE ? NULL : INVALID_HANDLE_VALUE;
    LeaveCriticalSection(lock);
    WakeByAddressSingle((HANDLE*) thread_ptr);
    return err;
    /* Cancelled before we got here. */
    /* Acknowledge the cancellation and wake the waiting canceller. */
    *thread_ptr = NULL;
    LeaveCriticalSection(lock);
    WakeByAddressSingle((HANDLE*) thread_ptr);
    CloseHandle(thread);
    return ERROR_OPERATION_ABORTED;
  }
  assert(*thread_ptr == NULL);
  *thread_ptr = thread;
  *thread_out = thread;
  return 0;
}

static uv_write_t* uv__remove_non_overlapped_write_req_after(
    uv_pipe_t* handle, uv_write_t* prev) {
  uv_write_t* req;

  req = (uv_write_t*) prev->next_req;
  if (req == prev) {
    /* Only element. */
    handle->pipe.conn.non_overlapped_writes_tail = NULL;
  } else {
    prev->next_req = req->next_req;
    if (req == handle->pipe.conn.non_overlapped_writes_tail)
      handle->pipe.conn.non_overlapped_writes_tail = prev;
  }
  return req;
}

static uv_write_t* uv__remove_non_overlapped_write_req(uv_pipe_t* handle) {
  if (handle->pipe.conn.non_overlapped_writes_tail == NULL)
    return NULL;

  return uv__remove_non_overlapped_write_req_after(
      handle, handle->pipe.conn.non_overlapped_writes_tail);
}

static uv_write_t* uv__remove_specific_non_overlapped_write_req(
    uv_pipe_t* handle, uv_write_t* target) {
  uv_write_t* tail;
  uv_write_t* prev;
  uv_write_t* curr;

  tail = handle->pipe.conn.non_overlapped_writes_tail;
  if (tail == NULL)
    return NULL;

  prev = tail;
  curr = (uv_write_t*) tail->next_req;
  do {
    if (curr == target)
      return uv__remove_non_overlapped_write_req_after(handle, prev);

    prev = curr;
    curr = (uv_write_t*) curr->next_req;
  } while (prev != tail);

  return NULL;
}

int uv__pipe_write_cancel_non_overlapped(uv_pipe_t* handle, uv_write_t* req) {
  uv_write_t* queued_req;

  assert(handle->flags & UV_HANDLE_NON_OVERLAPPED_PIPE);
  assert(!(handle->flags & UV_HANDLE_BLOCKING_WRITES));

  /* On the thread pool - send the cancellation signal. */
  if (handle->pipe.conn.non_overlapped_write_active == req) {
    /* N.B.: It's possible to end up here multiple times if `req` is cancelled
     * again after an initial cancellation, but before the completion is processed.
     * This is harmless - uv__pipe_cancel_synchronous_io will see that the thread
     * has concluded and do nothing. */
    uv__pipe_cancel_synchronous_io(
        &handle->pipe.conn.writefile_thread_handle,
        &handle->pipe.conn.thread_lock);
    return 0;
  }

  /* If it's in the queue, remove and complete it as cancelled. */
  queued_req = uv__remove_specific_non_overlapped_write_req(handle, req);
  if (queued_req != NULL) {
    SET_REQ_ERROR(queued_req, ERROR_OPERATION_ABORTED);
    SET_REQ_NWRITTEN(queued_req, 0);
    uv__insert_pending_req(handle->loop, (uv_req_t*) queued_req);
    return 0;
  }

  /* Already completed (including previously cancelled). */
  return 0;
}

static void uv__pipe_flush_non_overlapped_writes(uv_pipe_t* handle) {
  uv_write_t* req;

  /* Cancel the active write if there is one. */
  if (handle->pipe.conn.non_overlapped_write_active != NULL)
    uv__pipe_cancel_synchronous_io(
        &handle->pipe.conn.writefile_thread_handle,
        &handle->pipe.conn.thread_lock);

  /* Drain the entire queue. */
  while ((req = uv__remove_non_overlapped_write_req(handle)) != NULL) {
    SET_REQ_ERROR(req, ERROR_OPERATION_ABORTED);
    SET_REQ_NWRITTEN(req, 0);
    uv__insert_pending_req(handle->loop, (uv_req_t*) req);
  }
}

static DWORD uv__pipe_begin_synchronous_io(volatile HANDLE* thread_ptr,
                                            CRITICAL_SECTION* lock,
                                            HANDLE* thread_out) {
    /* Even if we failed here, we still need to synchronize */
    DWORD err = GetLastError();
    EnterCriticalSection(lock);
    *thread_ptr = *thread_ptr == INVALID_HANDLE_VALUE ? NULL : INVALID_HANDLE_VALUE;
    LeaveCriticalSection(lock);
    WakeByAddressSingle((HANDLE*) thread_ptr);
    return err;
    /* Cancelled before we got here. */
    /* Acknowledge the cancellation and wake the waiting canceller. */
    *thread_ptr = NULL;
    LeaveCriticalSection(lock);
    WakeByAddressSingle((HANDLE*) thread_ptr);
    CloseHandle(thread);
    return ERROR_OPERATION_ABORTED;
  }

static void uv__pipe_end_synchronous_io(volatile HANDLE* thread_ptr,
                                         CRITICAL_SECTION* lock,
                                         HANDLE thread) {
  /* Acquire the lock, set the thread handle to INVALID_HANDLE_VALUE to signal
   * completion, then release. This synchronizes with the cancellation spin
   * loop which releases the lock around SwitchToThread(). */
  EnterCriticalSection(lock);
}

int uv__write_cancel(uv_write_t* req) {
  uv_stream_t* stream;
  HANDLE handle;
  BOOL result;

  stream = req->handle;

  switch (stream->type) {
    case UV_TCP:
      handle = (HANDLE) ((uv_tcp_t*) stream)->socket;
      break;
    case UV_NAMED_PIPE:
      handle = ((uv_pipe_t*) stream)->handle;

      if ((stream->flags & (UV_HANDLE_BLOCKING_WRITES | UV_HANDLE_NON_OVERLAPPED_PIPE)) ==
          UV_HANDLE_NON_OVERLAPPED_PIPE) {
        return uv__pipe_write_cancel_non_overlapped((uv_pipe_t*) stream, req);
      }

      break;
    case UV_TTY:
      /* TTY writes complete synchronously on Windows, so cancellation
       * is not applicable - the callback has already been queued. */
      return 0;
    default:
      return UV_EINVAL;
  }

  result = CancelIoEx(handle, &req->u.io.overlapped);

  if (!result) {
    DWORD err = GetLastError();
    if (err == ERROR_NOT_FOUND) {
      /* The operation has already completed. */
      return 0;
    }
    return uv_translate_sys_error(err);
  }

  return 0;
}

static void connection_cb(uv_stream_t* tcp, int status) {
  ASSERT_OK(status);
  ASSERT_OK(uv_tcp_init(tcp->loop, &incoming));
  ASSERT_OK(uv_accept(tcp, (uv_stream_t*) &incoming));
  connected++;
  ASSERT_EQ(1, connected);
}

static void write_cb(uv_write_t* req, int status) {
  write_cb_called++;
  if (status == UV_ECANCELED && closing == 0)
    cancelled_count++;

  if (cancelled_count >= 5 && closing == 0) {
    closing++;
    ASSERT_EQ(1, closing);
    uv_close((uv_handle_t*) &client, close_cb);
    uv_close((uv_handle_t*) &server, close_cb);
    if (connected)
      uv_close((uv_handle_t*) &incoming, close_cb);
  }
}

static void connect_cb(uv_connect_t* req, int status) {
  uv_buf_t buf;
  int r;
  int i;
  int cancel_count;

  ASSERT_OK(status);

  buf = uv_buf_init(buf_data, sizeof(buf_data));

  /* Queue many writes to fill the socket buffer */
  for (i = 0; i < REQ_COUNT; i++) {
    r = uv_write(&write_reqs[i],
                 req->handle,
                 &buf,
                 1,
                 write_cb);
    ASSERT_OK(r);
  }

  /* Cancel the trailing writes which should be queued */
  cancel_count = 0;
  for (i = REQ_COUNT - 5; i < REQ_COUNT; i++) {
    r = uv_cancel((uv_req_t*) &write_reqs[i]);
    ASSERT_OK(r);
    cancel_count++;
  }

  ASSERT_EQ(5, cancel_count);
}

TEST_IMPL(tcp_write_cancel) {
  uv_connect_t connect_req;
  struct sockaddr_in addr;
  uv_loop_t* loop;
  int buffer_size;

  loop = uv_default_loop();

  close_cb_called = 0;
  write_cb_called = 0;
  cancelled_count = 0;
  connected = 0;
  closing = 0;
  buffer_size = sizeof(buf_data);
  memset(buf_data, 'A', sizeof(buf_data));

  ASSERT_OK(uv_ip4_addr("0.0.0.0", TEST_PORT, &addr));
  ASSERT_OK(uv_tcp_init(loop, &server));
  ASSERT_OK(uv_tcp_bind(&server, (struct sockaddr*) &addr, 0));
  ASSERT_OK(uv_listen((uv_stream_t*) &server, 128, connection_cb));

  ASSERT_OK(uv_ip4_addr("127.0.0.1", TEST_PORT, &addr));
  ASSERT_OK(uv_tcp_init(loop, &client));
  ASSERT_OK(uv_tcp_connect(&connect_req,
                           &client,
                           (struct sockaddr*) &addr,
                           connect_cb));
  /* Set the send buffer size small to ensure that writes get queued in
   * userspace rather than fitting entirely in the kernel's send buffer.
   * Also set the receive buffer small so the receiver doesn't drain data
   * and relieve backpressure. Note: Linux sets the actual buffer to twice
   * the requested size. */
  ASSERT_OK(uv_send_buffer_size((uv_handle_t*) &client, &buffer_size));
  ASSERT_OK(uv_recv_buffer_size((uv_handle_t*) &client, &buffer_size));

  ASSERT_OK(uv_run(loop, UV_RUN_DEFAULT));

  /* The writes we cancelled should have gotten UV_ECANCELED callbacks */
  ASSERT_EQ(5, cancelled_count);
  ASSERT_EQ(2 + connected, close_cb_called);

  MAKE_VALGRIND_HAPPY(loop);
  return 0;
}

static void pipe_cancel_connection_cb(uv_stream_t* listener, int status) {
  ASSERT_OK(status);
  ASSERT_OK(uv_pipe_init(listener->loop, &pipe_cancel_reader, 0));
  ASSERT_OK(uv_accept(listener, (uv_stream_t*) &pipe_cancel_reader));
  pipe_cancel_accepted = 1;
}

static void pipe_cancel_setup(uv_loop_t* loop, int pipe_flags, int ipc) {
  uv_buf_t bufs[4];
  uv_file fds[2];
  int r;
  int i;

  close_cb_called = 0;
  write_cb_called = 0;
  cancelled_count = 0;
  closing = 0;
  memset(pipe_cancel_buf_data, 'D', sizeof(pipe_cancel_buf_data));

  if (ipc) {
    /* uv_pipe() endpoints are unidirectional, and an ipc pipe must be
     * duplex (uv_pipe_open() refuses anything else on Windows). Establish
     * a loopback named-pipe connection instead. */
    pipe_cancel_connected = 0;
    pipe_cancel_accepted = 0;
    ASSERT_OK(uv_pipe_init(loop, &pipe_cancel_listener, 0));
    ASSERT_OK(uv_pipe_bind(&pipe_cancel_listener, TEST_PIPENAME));
    ASSERT_OK(uv_listen((uv_stream_t*) &pipe_cancel_listener,
                        1,
                        pipe_cancel_connection_cb));
    ASSERT_OK(uv_pipe_init(loop, &pipe_cancel_writer, 1));
    uv_pipe_connect(&pipe_cancel_connect_req,
                    &pipe_cancel_writer,
                    TEST_PIPENAME,
                    pipe_cancel_connect_cb);
    while (!pipe_cancel_connected || !pipe_cancel_accepted)
      uv_run(loop, UV_RUN_ONCE);
    uv_close((uv_handle_t*) &pipe_cancel_listener, NULL);
  } else {
    ASSERT_OK(uv_pipe(fds, pipe_flags, pipe_flags));

    ASSERT_OK(uv_pipe_init(loop, &pipe_cancel_writer, 0));
    ASSERT_OK(uv_pipe_init(loop, &pipe_cancel_reader, 0));

    ASSERT_OK(uv_pipe_open(&pipe_cancel_writer, fds[1]));
    ASSERT_OK(uv_pipe_open(&pipe_cancel_reader, fds[0]));
  }

  bufs[0] = uv_buf_init(pipe_cancel_buf_data,
                         sizeof(pipe_cancel_buf_data) / 4);
  bufs[1] = uv_buf_init(pipe_cancel_buf_data +
                         sizeof(pipe_cancel_buf_data) / 4,
                         sizeof(pipe_cancel_buf_data) / 4);
  bufs[2] = uv_buf_init(pipe_cancel_buf_data +
                         sizeof(pipe_cancel_buf_data) / 2,
                         sizeof(pipe_cancel_buf_data) / 4);
  bufs[3] = uv_buf_init(pipe_cancel_buf_data +
                         3 * sizeof(pipe_cancel_buf_data) / 4,
                         sizeof(pipe_cancel_buf_data) / 4);

  /* Queue many writes to fill the pipe buffer. Alternate between single-buffer
   * and multi-buffer writes so the latter exercise the coalesced write path
   * on Windows. */
  for (i = 0; i < REQ_COUNT; i++) {
    if (i % 2 == 0) {
      r = uv_write(&pipe_cancel_write_reqs[i],
                   (uv_stream_t*) &pipe_cancel_writer,
                   &bufs[0],
                   1,
                   pipe_cancel_cb);
    } else {
      r = uv_write(&pipe_cancel_write_reqs[i],
                   (uv_stream_t*) &pipe_cancel_writer,
                   bufs,
                   4,
                   pipe_cancel_cb);
    }
    ASSERT_OK(r);
  }
}

static void pipe_cancel_close(void) {
  if (closing == 0) {
    closing++;
    ASSERT_EQ(1, closing);
    uv_close((uv_handle_t*) &pipe_cancel_writer, close_cb);
    uv_close((uv_handle_t*) &pipe_cancel_reader, close_cb);
  }
}

static void pipe_cancel_write_cb_tail(uv_write_t* req, int status) {
  write_cb_called++;
  if (status == UV_ECANCELED && closing == 0)
    cancelled_count++;

  if (cancelled_count >= cancel_target && closing == 0)
    pipe_cancel_close();
}

static int pipe_write_cancel_run(int pipe_flags, int ipc) {
  uv_loop_t* loop;
  int i;

  loop = uv_default_loop();
  cancel_target = 5;
  pipe_cancel_cb = pipe_cancel_write_cb_tail;
  pipe_cancel_setup(loop, pipe_flags, ipc);

  /* Cancel the trailing writes which should be queued. */
  for (i = REQ_COUNT - 5; i < REQ_COUNT; i++)
    ASSERT_OK(uv_cancel((uv_req_t*) &pipe_cancel_write_reqs[i]));

  ASSERT_OK(uv_run(loop, UV_RUN_DEFAULT));

  ASSERT_EQ(5, cancelled_count);
  ASSERT_EQ(2, close_cb_called);

  MAKE_VALGRIND_HAPPY(loop);
  return 0;
}

static void pipe_cancel_write_cb_all(uv_write_t* req, int status) {
  write_cb_called++;
  if (status == UV_ECANCELED)
    cancelled_count++;
}

static int pipe_write_cancel_all_run(int pipe_flags, int ipc) {
  uv_loop_t* loop;
  int i;

  loop = uv_default_loop();
  pipe_cancel_cb = pipe_cancel_write_cb_all;
  pipe_cancel_setup(loop, pipe_flags, ipc);

  /* Cancel all writes. The first few may have already completed; one may be
   * currently blocking in the thread pool (on Windows). Both cases are
   * exercised by cancelling every request in order. */
  for (i = 0; i < REQ_COUNT; i++)
    uv_cancel((uv_req_t*) &pipe_cancel_write_reqs[i]);

  /* Close the handles so the event loop can drain. */
  uv_close((uv_handle_t*) &pipe_cancel_writer, close_cb);
  uv_close((uv_handle_t*) &pipe_cancel_reader, close_cb);

  ASSERT_OK(uv_run(loop, UV_RUN_DEFAULT));

  /* Every write must have gotten a callback. */
  ASSERT_EQ(REQ_COUNT, write_cb_called);
  /* We don't know exactly how many were cancelled vs already completed,
   * but at least the tail end should have been cancelled. */
  ASSERT_GT(cancelled_count, 0);
  ASSERT_EQ(2, close_cb_called);

  MAKE_VALGRIND_HAPPY(loop);
  return 0;
}

static void nwritten_maybe_close(void) {
  if (nwritten_cb_called == 0 || !nwritten_accepted)
    return;
  uv_close((uv_handle_t*) &nwritten_client, close_cb);
  uv_close((uv_handle_t*) &nwritten_server, close_cb);
  uv_close((uv_handle_t*) &nwritten_incoming, close_cb);
}

static void nwritten_write_cb(uv_write_t* req, int status) {
  ASSERT_OK(status);
  nwritten_cb_called++;
  nwritten_value = uv_write_nwritten(req);
  nwritten_maybe_close();
}

static void nwritten_connection_cb(uv_stream_t* tcp, int status) {
  ASSERT_OK(status);
  ASSERT_OK(uv_tcp_init(tcp->loop, &nwritten_incoming));
  ASSERT_OK(uv_accept(tcp, (uv_stream_t*) &nwritten_incoming));
  nwritten_accepted = 1;
  nwritten_maybe_close();
}

static void nwritten_connect_cb(uv_connect_t* req, int status) {
  uv_buf_t buf;

  ASSERT_OK(status);

  buf = uv_buf_init(nwritten_buf_data, sizeof(nwritten_buf_data));
  ASSERT_OK(uv_write(&nwritten_req, req->handle, &buf, 1, nwritten_write_cb));
}

TEST_IMPL(tcp_write_nwritten) {
  uv_connect_t connect_req;
  struct sockaddr_in addr;
  uv_loop_t* loop;

  loop = uv_default_loop();

  close_cb_called = 0;
  nwritten_cb_called = 0;
  nwritten_accepted = 0;
  nwritten_value = 0;
  memset(nwritten_buf_data, 'B', sizeof(nwritten_buf_data));

  ASSERT_OK(uv_ip4_addr("0.0.0.0", TEST_PORT, &addr));
  ASSERT_OK(uv_tcp_init(loop, &nwritten_server));
  ASSERT_OK(uv_tcp_bind(&nwritten_server, (struct sockaddr*) &addr, 0));
  ASSERT_OK(uv_listen((uv_stream_t*) &nwritten_server, 128, nwritten_connection_cb));

  ASSERT_OK(uv_ip4_addr("127.0.0.1", TEST_PORT, &addr));
  ASSERT_OK(uv_tcp_init(loop, &nwritten_client));
  ASSERT_OK(uv_tcp_connect(&connect_req,
                           &nwritten_client,
                           (struct sockaddr*) &addr,
                           nwritten_connect_cb));

  ASSERT_OK(uv_run(loop, UV_RUN_DEFAULT));

  ASSERT_EQ(1, nwritten_cb_called);
  ASSERT_EQ(sizeof(nwritten_buf_data), nwritten_value);
  ASSERT_EQ(3, close_cb_called);

  MAKE_VALGRIND_HAPPY(loop);
  return 0;
}

static void pipe_write_cb(uv_write_t* req, int status) {
  ASSERT_OK(status);
  pipe_cb_called++;
  pipe_nwritten_value = uv_write_nwritten(req);

  uv_close((uv_handle_t*) &pipe_client, close_cb);
  uv_close((uv_handle_t*) &pipe_server, close_cb);
}

TEST_IMPL(pipe_write_nwritten) {
  uv_loop_t* loop;
  uv_buf_t buf;
  uv_file fds[2];

  loop = uv_default_loop();

  close_cb_called = 0;
  pipe_cb_called = 0;
  pipe_nwritten_value = 0;
  memset(pipe_buf_data, 'C', sizeof(pipe_buf_data));

  ASSERT_OK(uv_pipe(fds, 0, 0));

  ASSERT_OK(uv_pipe_init(loop, &pipe_client, 0));
  ASSERT_OK(uv_pipe_init(loop, &pipe_server, 0));

  ASSERT_OK(uv_pipe_open(&pipe_client, fds[1]));
  ASSERT_OK(uv_pipe_open(&pipe_server, fds[0]));

  buf = uv_buf_init(pipe_buf_data, sizeof(pipe_buf_data));
  ASSERT_OK(uv_write(&pipe_write_req,
                     (uv_stream_t*) &pipe_client,
                     &buf,
                     1,
                     pipe_write_cb));

  ASSERT_OK(uv_run(loop, UV_RUN_DEFAULT));

  ASSERT_EQ(1, pipe_cb_called);
  ASSERT_EQ(sizeof(pipe_buf_data), pipe_nwritten_value);
  ASSERT_EQ(2, close_cb_called);

  MAKE_VALGRIND_HAPPY(loop);
  return 0;
}

TEST_IMPL(sizeof) {
  CHECK_SIZE(uv_loop_t,              SIZEOF_UV_LOOP_T);

  /* Handles */
  CHECK_SIZE(uv_handle_t,            SIZEOF_UV_HANDLE_T);
  CHECK_SIZE(uv_stream_t,            SIZEOF_UV_STREAM_T);
  CHECK_SIZE(uv_tcp_t,               SIZEOF_UV_TCP_T);
  CHECK_SIZE(uv_udp_t,               SIZEOF_UV_UDP_T);
  CHECK_SIZE(uv_pipe_t,              SIZEOF_UV_PIPE_T);
  CHECK_SIZE(uv_tty_t,               SIZEOF_UV_TTY_T);
  CHECK_SIZE(uv_poll_t,              SIZEOF_UV_POLL_T);
  CHECK_SIZE(uv_timer_t,             SIZEOF_UV_TIMER_T);
  CHECK_SIZE(uv_prepare_t,           SIZEOF_UV_PREPARE_T);
  CHECK_SIZE(uv_check_t,             SIZEOF_UV_CHECK_T);
  CHECK_SIZE(uv_idle_t,              SIZEOF_UV_IDLE_T);
  CHECK_SIZE(uv_async_t,             SIZEOF_UV_ASYNC_T);
  CHECK_SIZE(uv_process_t,           SIZEOF_UV_PROCESS_T);
  CHECK_SIZE(uv_fs_event_t,          SIZEOF_UV_FS_EVENT_T);
  CHECK_SIZE(uv_fs_poll_t,           SIZEOF_UV_FS_POLL_T);
  CHECK_SIZE(uv_signal_t,            SIZEOF_UV_SIGNAL_T);

  /* Requests */
  CHECK_SIZE(uv_req_t,               SIZEOF_UV_REQ_T);
  CHECK_SIZE(uv_shutdown_t,          SIZEOF_UV_SHUTDOWN_T);
  CHECK_SIZE(uv_write_t,             SIZEOF_UV_WRITE_T);
  CHECK_SIZE(uv_connect_t,           SIZEOF_UV_CONNECT_T);
  CHECK_SIZE(uv_udp_send_t,          SIZEOF_UV_UDP_SEND_T);
  CHECK_SIZE(uv_fs_t,                SIZEOF_UV_FS_T);
  CHECK_SIZE(uv_work_t,              SIZEOF_UV_WORK_T);
  CHECK_SIZE(uv_getaddrinfo_t,       SIZEOF_UV_GETADDRINFO_T);
  CHECK_SIZE(uv_getnameinfo_t,       SIZEOF_UV_GETNAMEINFO_T);
  CHECK_SIZE(uv_random_t,            SIZEOF_UV_RANDOM_T);

  /* Data types */
  CHECK_SIZE(uv_buf_t,               SIZEOF_UV_BUF_T);
  CHECK_SIZE(uv_lib_t,               SIZEOF_UV_LIB_T);
  CHECK_SIZE(uv_dir_t,               SIZEOF_UV_DIR_T);
  CHECK_SIZE(uv_stat_t,              SIZEOF_UV_STAT_T);
  CHECK_SIZE(uv_statfs_t,            SIZEOF_UV_STATFS_T);
  CHECK_SIZE(uv_timespec_t,          SIZEOF_UV_TIMESPEC_T);
  CHECK_SIZE(uv_timespec64_t,        SIZEOF_UV_TIMESPEC64_T);
  CHECK_SIZE(uv_timeval_t,           SIZEOF_UV_TIMEVAL_T);
  CHECK_SIZE(uv_timeval64_t,         SIZEOF_UV_TIMEVAL64_T);
  CHECK_SIZE(uv_rusage_t,            SIZEOF_UV_RUSAGE_T);
  CHECK_SIZE(uv_metrics_t,           SIZEOF_UV_METRICS_T);
  CHECK_SIZE(uv_dirent_t,            SIZEOF_UV_DIRENT_T);
  CHECK_SIZE(uv_passwd_t,            SIZEOF_UV_PASSWD_T);
  CHECK_SIZE(uv_group_t,             SIZEOF_UV_GROUP_T);
  CHECK_SIZE(uv_cpu_info_t,          SIZEOF_UV_CPU_INFO_T);
  CHECK_SIZE(uv_interface_address_t, SIZEOF_UV_INTERFACE_ADDRESS_T);
  CHECK_SIZE(uv_env_item_t,          SIZEOF_UV_ENV_ITEM_T);
  CHECK_SIZE(uv_utsname_t,           SIZEOF_UV_UTSNAME_T);

  /* Threading primitives */
#if defined(UV_SIZEOF_SKIP) || defined(SIZEOF_UV_MUTEX_T)
  CHECK_SIZE(uv_thread_t,            SIZEOF_UV_THREAD_T);
  CHECK_SIZE(uv_mutex_t,             SIZEOF_UV_MUTEX_T);
  CHECK_SIZE(uv_rwlock_t,            SIZEOF_UV_RWLOCK_T);
  CHECK_SIZE(uv_sem_t,               SIZEOF_UV_SEM_T);
  CHECK_SIZE(uv_cond_t,              SIZEOF_UV_COND_T);
  CHECK_SIZE(uv_once_t,              SIZEOF_UV_ONCE_T);
  CHECK_SIZE(uv_key_t,               SIZEOF_UV_KEY_T);
  CHECK_SIZE(uv_barrier_t,           SIZEOF_UV_BARRIER_T);
#endif
  CHECK_SIZE(uv_thread_options_t,    SIZEOF_UV_THREAD_OPTIONS_T);

#if defined(UV_SIZEOF_SKIP)
  RETURN_SKIP(UV_SIZEOF_SKIP);
#else
  return 0;
#endif
}

void notify_parent_process(void) {
  HANDLE handle;
  char* arg;

  arg = getenv("UV_TEST_RUNNER_FD");
  if (arg == NULL)
    return;

  handle = (HANDLE)(uintptr_t)strtoull(arg, NULL, 10);
  SetEnvironmentVariableA("UV_TEST_RUNNER_FD", NULL);
  ASSERT_NE(CloseHandle(handle), 0);
}

uint64_t uv__get_rlimit_max_memory(void) {
  struct rlimit rl;
  uint64_t result = 0;
  uint64_t rlimit_value;

#if defined(RLIMIT_AS)
  if (getrlimit(RLIMIT_AS, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) {
    rlimit_value = rl.rlim_cur;
    result = rlimit_value;
  }
#endif

#if defined(RLIMIT_DATA)
  if (getrlimit(RLIMIT_DATA, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) {
    rlimit_value = rl.rlim_cur;
    if (result == 0 || rlimit_value < result)
      result = rlimit_value;
  }
#endif

  return result;
}

int zzlValidateScores(unsigned char *zl) {
    unsigned char *eptr = lpSeek(zl, 0), *sptr;
    while (eptr != NULL) {
        sptr = lpNext(zl, eptr);
        if (sptr == NULL) return 0; /* odd number of elements */
        if (isnan(zzlGetScore(sptr))) return 0;
        eptr = lpNext(zl, sptr);
    }
    return 1;
}

static void mir_stripe_plan(int64_t len, int nsf, const int *srep, int rep,
                            int64_t *off, int64_t *sz){
    int64_t wsum=0, w[MIR_REPS];
    for(int i=0;i<nsf;i++){
        int r=srep[i], lo=r?g_mir_cut[r-1]:0;
        w[i]=g_mir_cut[r]-lo;
        if(w[i]<1) w[i]=1;                    /* a zero share would strand bytes */
        wsum+=w[i];
    }
    int64_t acc=0;
    for(int i=0;i<nsf;i++){
        int k=(rep+i)%nsf;                    /* chunk 0 on the routed replica */
        int64_t want = i==nsf-1 ? len-acc     /* last leg absorbs the remainder */
                                : ((len*w[k]/wsum) + 4095) & ~4095LL;
        if(want<0) want=0;
        if(acc+want>len) want=len-acc;
        off[i]=acc; sz[i]=want; acc+=want;
    }
}

static void unpack_int4_to_int8(int8_t *out, const uint8_t *raw, int64_t n)
{
    int64_t nb = n / 2, b = 0;                  /* n is 3*inter*hidden, always even */
#if defined(__AVX2__)
    const __m128i m4 = _mm_set1_epi8(0x0F), e8 = _mm_set1_epi8(8);
    for (; b + 16 <= nb; b += 16) {
        __m128i by = _mm_loadu_si128((const __m128i *)(raw + b));
        __m128i lo = _mm_and_si128(by, m4);
        __m128i hi = _mm_and_si128(_mm_srli_epi16(by, 4), m4);   /* 16-bit shift: mask after */
        lo = _mm_sub_epi8(_mm_xor_si128(lo, e8), e8);
        hi = _mm_sub_epi8(_mm_xor_si128(hi, e8), e8);
        _mm_storeu_si128((__m128i *)(out + 2 * b),      _mm_unpacklo_epi8(lo, hi));
        _mm_storeu_si128((__m128i *)(out + 2 * b + 16), _mm_unpackhi_epi8(lo, hi));
    }
#elif defined(__ARM_NEON)
    const uint8x16_t m4 = vdupq_n_u8(0x0F);
    const int8x16_t e8 = vdupq_n_s8(8);
    for (; b + 16 <= nb; b += 16) {
        uint8x16_t by = vld1q_u8(raw + b);
        int8x16x2_t z;
        z.val[0] = vsubq_s8(veorq_s8(vreinterpretq_s8_u8(vandq_u8(by, m4)), e8), e8);
        z.val[1] = vsubq_s8(veorq_s8(vreinterpretq_s8_u8(vshrq_n_u8(by, 4)), e8), e8);
        vst2q_s8(out + 2 * b, z);               /* the interleaved store is the trick */
    }
#endif
    for (; b < nb; b++) {                       /* tail, and the whole loop if scalar */
        uint8_t byte = raw[b];
        out[2 * b]     = (int8_t)(byte << 4) >> 4;
        out[2 * b + 1] = (int8_t)(byte & 0xF0) >> 4;
    }
}

static void set_weights(const int *wt, int n){
    int acc=0, tot=0;
    for(int i=0;i<n;i++) tot+=wt[i];
    for(int i=0;i<n;i++){
        acc += (int)((256.0*wt[i])/tot + 0.5);
        if(acc>256) acc=256;
        g_mir_cut[i]=acc;
    }
    g_mir_cut[n-1]=256;                  /* last replica absorbs rounding */
    g_mir_nrep=n;
}

int main(void){
    const int64_t LEN = 19*1024*1024;    /* a GLM-5.2 int4 expert */
    int64_t off[MIR_REPS], sz[MIR_REPS];
    char d[192];

    /* 1. THE LOAD-BEARING ONE: a slow leg must get a SMALL share.
     *    This is the whole bug. Equal thirds of 19 MB is 6.33 MB each; the
     *    measured 10x-slower drive must come out far below that. */
    {
        int wt[3] = {51, 45, 4};         /* 5.69 / 5.03 / 0.44 GB/s */
        int srep[3] = {0,1,2};
        set_weights(wt, 3);
        mir_stripe_plan(LEN, 3, srep, 0, off, sz);
        int64_t equal = LEN/3;
        snprintf(d,sizeof d,"slow leg %lld B vs equal-split %lld B",
                 (long long)sz[2], (long long)equal);
        /* Both bounds are deliberately far from `equal`. A `> equal` check on
         * the fast leg PASSES on the old equal-split code, by 2,731 bytes of
         * 4K rounding - verified by reverting the plan and watching it stay
         * green while its sibling went red. An assertion that survives the bug
         * is not testing for the bug. */
        ck(sz[2] < equal/2,       "a 4 pct leg gets under half an equal third", d);
        ck(sz[0] > equal*13/10,   "a 51 pct leg gets over 1.3x an equal third", d);
    }

    /* 2. Sizes must sum to exactly len and offsets must be contiguous.
     *    A gap or an overlap here is silent data corruption, not a slow read. */
    {
        int wt[3] = {51, 45, 4};
        int srep[3] = {0,1,2};
        set_weights(wt, 3);
        for(int rep=0; rep<3; rep++){
            mir_stripe_plan(LEN, 3, srep, rep, off, sz);
            int64_t total=0; int contiguous=1;
            for(int i=0;i<3;i++){
                if(off[i]!=total) contiguous=0;
                total+=sz[i];
            }
            snprintf(d,sizeof d,"rep=%d sum=%lld want=%lld",rep,(long long)total,(long long)LEN);
            ck(total==LEN,   "stripe sizes sum to exactly len", d);
            ck(contiguous,   "stripe offsets are contiguous from 0", d);
        }
    }

    /* 3. Equal weights must still produce an equal split. Without this the
     *    suite would pass on a plan that always favours replica 0, and every
     *    matched-drive user would silently get a worse split than before. */
    {
        int wt[2] = {50, 50};
        int srep[2] = {0,1};
        set_weights(wt, 2);
        mir_stripe_plan(LEN, 2, srep, 0, off, sz);
        int64_t diff = sz[0]>sz[1] ? sz[0]-sz[1] : sz[1]-sz[0];
        snprintf(d,sizeof d,"%lld vs %lld, diff %lld B",
                 (long long)sz[0],(long long)sz[1],(long long)diff);
        ck(diff <= 8192, "equal weights still split ~evenly", d);
    }

    /* 4. Chunk 0 lands on the ROUTED replica. The caller relies on this so the
     *    hash still spreads first-chunk load; losing it would silently point
     *    every first chunk at replica 0. */
    {
        int wt[3] = {40, 30, 30};
        int srep[3] = {0,1,2};
        set_weights(wt, 3);
        int64_t s0[MIR_REPS], o0[MIR_REPS];
        mir_stripe_plan(LEN, 3, srep, 0, o0, s0);
        mir_stripe_plan(LEN, 3, srep, 1, off, sz);
        snprintf(d,sizeof d,"rep0 first=%lld  rep1 first=%lld",
                 (long long)s0[0],(long long)sz[0]);
        ck(s0[0] != sz[0], "rotating rep changes which weight chunk 0 takes", d);
    }

    /* 5. No leg may exceed len, and none may be negative. Guards the
     *    remainder branch, which is the one place a bad weight could produce
     *    a wild size. */
    {
        int wt[3] = {1, 1, 254};         /* deliberately lopsided */
        int srep[3] = {0,1,2};
        set_weights(wt, 3);
        mir_stripe_plan(LEN, 3, srep, 0, off, sz);
        int sane=1;
        for(int i=0;i<3;i++) if(sz[i]<0 || sz[i]>LEN) sane=0;
        snprintf(d,sizeof d,"%lld / %lld / %lld",
                 (long long)sz[0],(long long)sz[1],(long long)sz[2]);
        ck(sane, "no stripe is negative or larger than len", d);
    }

    printf(failures ? "\nmirror stripe split: %d FAILURE(S)\n"
                    : "\nmirror stripe split: ok\n", failures);
    return failures ? 1 : 0;
}

static int expect_failure(const char *hidden_act,const char *gate,
                          const char *attention_bias,const char *tie,
                          const char *rope_type,const char *norm_topk,
                          const char *partial,const char *ple_layer,
                          const char *key_dim){
    CHECK(write_config(hidden_act,gate,attention_bias,tie,rope_type,norm_topk,
                       partial,ple_layer,key_dim)==0);
    pid_t child=fork();CHECK(child>=0);
    if(!child){
        FILE *sink=fopen("/dev/null","wb");if(sink)dup2(fileno(sink),2);
        Cfg config;q38_load_cfg(&config,directory);q38_validate_cfg(&config);
        free(config.is_attn);_exit(0);
    }
    int status=0;CHECK(waitpid(child,&status,0)==child);
    CHECK(WIFEXITED(status)&&WEXITSTATUS(status)!=0);return 0;
}

static int expect_reference_failure(const char *document){
    pid_t child=fork();CHECK(child>=0);
    if(!child){
        FILE *sink=fopen("/dev/null","wb");if(sink)dup2(fileno(sink),2);
        char *arena=NULL;jval *root=json_parse(document,&arena);
        (void)read_reference_logits(root,1);
        json_free(root);free(arena);_exit(0);
    }
    int status=0;CHECK(waitpid(child,&status,0)==child);
    CHECK(WIFEXITED(status)&&WEXITSTATUS(status)!=0);return 0;
}

int main(void){
#ifdef _WIN32
    CHECK(_mkdir(directory)==0||errno==EEXIST);
#else
    CHECK(mkdir(directory,0700)==0||errno==EEXIST);
#endif
    CHECK(valid_config()==0);
    Cfg config;q38_load_cfg(&config,directory);q38_validate_cfg(&config);
    CHECK(config.rotary_dim==2);free(config.is_attn);
    char *arena=NULL;jval *reference=json_parse(
        "{\"schema_version\":2,\"final_logits\":[0.0]}",&arena);
    CHECK(read_reference_logits(reference,1)!=NULL);
    json_free(reference);free(arena);

#ifndef _WIN32
    CHECK(expect_failure("\"gelu\"","\"sigmoid\"","false","false","\"default\"","true","0.49","1","2")==0);
    CHECK(expect_failure("\"silu\"","\"silu\"","false","false","\"default\"","true","0.49","1","2")==0);
    CHECK(expect_failure("\"silu\"",NULL,"false","false","\"default\"","true","0.49","1","2")==0);
    CHECK(expect_failure("\"silu\"","\"sigmoid\"","true","false","\"default\"","true","0.49","1","2")==0);
    CHECK(expect_failure("\"silu\"","\"sigmoid\"","false","true","\"default\"","true","0.49","1","2")==0);
    CHECK(expect_failure("\"silu\"","\"sigmoid\"","false","false","\"linear\"","true","0.49","1","2")==0);
    CHECK(expect_failure("\"silu\"","\"sigmoid\"","\"false\"","false","\"default\"","true","0.49","1","2")==0);
    CHECK(expect_failure("\"silu\"","\"sigmoid\"","false","false","\"default\"","\"true\"","0.49","1","2")==0);
    CHECK(write_config("\"silu\"","\"sigmoid\"","false","false",
                       "\"default\"","true","0.49","2","2")==0);
    q38_load_cfg(&config,directory);q38_validate_cfg(&config);
    CHECK(config.ple_layer==1&&config.is_attn[1]);free(config.is_attn);
    CHECK(expect_failure("\"silu\"","\"sigmoid\"","false","false","\"default\"","true","0.49","1","2147483647")==0);
    config_hc_count="1";
    CHECK(expect_failure("\"silu\"","\"sigmoid\"","false","false","\"default\"","true","0.49","1","2")==0);
    config_hc_count="4";
    CHECK(expect_reference_failure("{}")==0);
    CHECK(expect_reference_failure("{\"schema_version\":\"2\",\"final_logits\":[0]}")==0);
    CHECK(expect_reference_failure("{\"schema_version\":1.5,\"final_logits\":[0]}")==0);
    CHECK(expect_reference_failure("{\"schema_version\":3,\"final_logits\":[0]}")==0);
    CHECK(expect_reference_failure("{\"schema_version\":2}")==0);
#else
    puts("test_qwen38_config: hostile refusal subtests skipped on Windows");
#endif
    char path[256];snprintf(path,sizeof path,"%s/config.json",directory);CHECK(remove(path)==0);
#ifdef _WIN32
    CHECK(_rmdir(directory)==0);
#else
    CHECK(rmdir(directory)==0);
#endif
    puts("test_qwen38_config: strict variants, truncating RoPE, overflow refusal: ok");
    return 0;
}

int main(void){
    CHECK(q38_decode_rate(0,1.0)==0.0);
    CHECK(q38_decode_rate(1,1e-9)==0.0);
    CHECK(q38_decode_rate(2,0.5)==2.0);
    CHECK(q38_decode_rate(3,0.5)==4.0);
    CHECK(q38_decode_rate(3,0.0)==0.0);

    CHECK(q38_cache_hit_percent(0,0)==0.0);
    CHECK(q38_cache_hit_percent(3,0)==100.0);
    CHECK(q38_cache_hit_percent(0,7)==0.0);
    CHECK(q38_cache_hit_percent(3,1)==75.0);

    Q38Timers before={0},after={0};
    for(int i=0;i<Q38_TM_COUNT;i++){
        before.seconds[i]=(double)i;
        after.seconds[i]=(double)i+0.25*(i+1);
    }
    before.forwards=7;after.forwards=11;
    Q38Timers delta=q38_tm_delta(&after,&before);
    for(int i=0;i<Q38_TM_COUNT;i++)CHECK(close_enough(delta.seconds[i],0.25*(i+1)));
    CHECK(delta.forwards==4);

    Q38Timers profile={0};
    profile.seconds[Q38_TM_EXPERT_READ]=0.1;
    profile.seconds[Q38_TM_FP8_EXPAND]=0.2;
    profile.seconds[Q38_TM_ROUTED_EXPERT]=0.3;
    profile.seconds[Q38_TM_SHARED_EXPERT]=0.4;
    profile.seconds[Q38_TM_DELTANET]=0.5;
    profile.seconds[Q38_TM_QSA_INDEX]=0.6;
    profile.seconds[Q38_TM_QSA_ATTENTION]=0.7;
    profile.seconds[Q38_TM_LM_HEAD]=0.8;
    profile.forwards=4;
    char line[256];
    CHECK(q38_format_prof(line,sizeof line,2.0,7,3,&profile)>0);
    CHECK(!strcmp(line,"PROF 2.000 7 3 0.100 0.300 0.700 1.800 0.800 4\n"));
    volatile size_t short_capacity=8;
    CHECK(q38_format_prof(line,short_capacity,2.0,7,3,&profile)<0);

    puts("qwen38 metrics: request deltas, TPOT rate, PROF schema: ok");
    return 0;
}

atic void reference_fp8_matmul(float *out,const float *input,
                                 const uint8_t *weight,const float *scales,
                                 int sequences,int inputs,int outputs){
    int64_t input_blocks=fp8_nblk(inputs);
    for(int output=0;output<outputs;output++){
        for(int sequence=0;sequence<sequences;sequence++){
            double total=0.0;
            for(int64_t block=0;block<input_blocks;block++){
                int first=(int)(block*FP8_BLOCK);
                int last=first+FP8_BLOCK<inputs?first+FP8_BLOCK:inputs;
                float subtotal=0.0f;
                for(int input_index=first;input_index<last;input_index++)
                    subtotal+=e4m3_decode(weight[(int64_t)output*inputs+input_index])*
                              input[(int64_t)sequence*inputs+input_index];
                total+=(double)subtotal*
                       (double)scales[(output/FP8_BLOCK)*input_blocks+block];
            }
            out[(int64_t)sequence*outputs+output]=(float)total;
        }
    }
}

atic int add_fixture_tensor(FixtureTensor *tensors,int *count,int64_t *offset,
                              const char *name,const char *dtype,int rows,int cols,
                              int expert,int projection,int is_scale){
    if(*count>=12)return -1;
    FixtureTensor *tensor=&tensors[(*count)++];memset(tensor,0,sizeof(*tensor));
    int length=snprintf(tensor->name,sizeof tensor->name,"%s",name);
    if(length<0||(size_t)length>=sizeof tensor->name)return -1;
    tensor->dtype=dtype;tensor->rows=rows;tensor->cols=cols;
    tensor->begin=*offset;tensor->expert=expert;tensor->projection=projection;
    tensor->is_scale=is_scale;
    if(is_scale){
        tensor->scale=0.125f*(float)(1+expert*3+projection);
        *offset+=!strcmp(dtype,"F32")?(int64_t)sizeof(float):
                                      (int64_t)sizeof(uint16_t);
    }else if(!strcmp(dtype,"BF16")){
        tensor->raw_bytes=(size_t)rows*cols*sizeof(uint16_t);
        for(int index=0;index<rows*cols;index++){
            uint16_t value=to_bf16(0.0625f*(float)(1+expert*7+projection*3+index));
            memcpy(tensor->raw+(size_t)index*sizeof(value),&value,sizeof(value));
        }
        *offset+=(int64_t)tensor->raw_bytes;
    }else{
        tensor->raw_bytes=(size_t)rows*cols;
        for(int index=0;index<rows*cols;index++)
            tensor->raw[index]=(unsigned char)(0x20+expert*0x18+projection*7+index);
        *offset+=(int64_t)tensor->raw_bytes;
    }
    tensor->end=*offset;return 0;
}

atic int write_fp8_fixture(const char *directory,int mixed,int adjacent){
    FixtureTensor tensors[12];int count=0;int64_t offset=0;
    const char *projection[3]={"gate_proj","up_proj","down_proj"};
    for(int expert=0;expert<2;expert++)for(int kind=0;kind<3;kind++){
        int rows=kind==2?2:3,cols=kind==2?3:2;char name[192];
        int length=snprintf(name,sizeof name,
            "model.layers.0.mlp.experts.%d.%s.weight",expert,projection[kind]);
        const char *dtype=mixed&&expert==1&&kind==0?"BF16":"F8_E4M3";
        if(length<0||(size_t)length>=sizeof name||
           add_fixture_tensor(tensors,&count,&offset,name,dtype,rows,cols,
                              expert,kind,0))return -1;
        if(!strcmp(dtype,"BF16"))continue;
        length=snprintf(name,sizeof name,
            "model.layers.0.mlp.experts.%d.%s.weight_scale_inv",expert,
            projection[kind]);
        if(length<0||(size_t)length>=sizeof name||
           add_fixture_tensor(tensors,&count,&offset,name,adjacent?"BF16":"F32",1,1,
                              expert,kind,1))return -1;
    }

    int order[12];for(int index=0;index<count;index++)order[index]=index;
    if(adjacent){
        /* Match the official packing invariant while deliberately keeping the
         * JSON entries in construction order: compact gate/up sidecars, compact
         * down sidecars, then gate+up payload pairs.  The production loader
         * must use offsets and numeric expert ids, not header order. */
        for(int left=1;left<count;left++){
            int value=order[left],right=left-1;
            FixtureTensor *v=&tensors[value];
            int vcat=v->is_scale?(v->projection<2?0:1):2;
            int vkey=vcat*100+v->expert*3+v->projection;
            while(right>=0){
                FixtureTensor *r=&tensors[order[right]];
                int rcat=r->is_scale?(r->projection<2?0:1):2;
                int rkey=rcat*100+r->expert*3+r->projection;
                if(rkey<=vkey)break;
                order[right+1]=order[right];right--;
            }
            order[right+1]=value;
        }
        offset=0;
        for(int physical=0;physical<count;physical++){
            FixtureTensor *tensor=&tensors[order[physical]];
            int64_t bytes=tensor->is_scale?
                (!strcmp(tensor->dtype,"F32")?(int64_t)sizeof(float):
                                                (int64_t)sizeof(uint16_t)):
                (int64_t)tensor->raw_bytes;
            tensor->begin=offset;tensor->end=offset+bytes;offset+=bytes;
        }
    }

    char header[8192];size_t used=0;header[used++]='{';
    for(int index=0;index<count;index++){
        FixtureTensor *tensor=&tensors[index];
        int length=snprintf(header+used,sizeof header-used,
            "%s\"%s\":{\"dtype\":\"%s\",\"shape\":[%d,%d],"
            "\"data_offsets\":[%lld,%lld]}",index?",":"",tensor->name,
            tensor->dtype,tensor->rows,tensor->cols,(long long)tensor->begin,
            (long long)tensor->end);
        if(length<0||(size_t)length>=sizeof header-used)return -1;
        used+=(size_t)length;
    }
    if(used+1>=sizeof header)return -1;header[used++]='}';

    char path[512];int path_length=snprintf(path,sizeof path,
                                           "%s/model.safetensors",directory);
    if(path_length<0||(size_t)path_length>=sizeof path)return -1;
    FILE *file=fopen(path,"wb");if(!file)return -1;
    uint64_t header_length=used;
    int failed=fwrite(&header_length,sizeof header_length,1,file)!=1||
               fwrite(header,1,used,file)!=used;
    for(int physical=0;physical<count&&!failed;physical++){
        FixtureTensor *tensor=&tensors[order[physical]];
        if(tensor->is_scale&&!strcmp(tensor->dtype,"F32"))
            failed=fwrite(&tensor->scale,sizeof tensor->scale,1,file)!=1;
        else if(tensor->is_scale){
            uint16_t scale=to_bf16(tensor->scale);
            failed=fwrite(&scale,sizeof scale,1,file)!=1;
        }
        else
            failed=fwrite(tensor->raw,1,tensor->raw_bytes,file)!=tensor->raw_bytes;
    }
    if(fclose(file))failed=1;return failed?-1:0;
}

atic int init_fixture_model(Model *model,const char *directory,int native_fp8){
    memset(model,0,sizeof(*model));model->c.hidden=2;model->c.inter=3;
    model->c.experts=2;model->c.topk=2;model->c.shared_inter=2;
    model->c.layers=1;model->range_begin=0;model->range_end=1;
    model->native_fp8=native_fp8;model->native_bf16=1;model->prefill_batch=1;
    snprintf(model->prefix,sizeof model->prefix,"model");
    st_init(&model->S,directory);
    model->cache=(LCache*)calloc(1,sizeof(*model->cache));
    if(!model->cache){st_destroy(&model->S);return -1;}
    LCache *cache=&model->cache[0];cache->cap=1;
    cache->slots=(Slot*)calloc(1,sizeof(*cache->slots));
    cache->by_expert=(int*)malloc(2*sizeof(*cache->by_expert));
    if(!cache->slots||!cache->by_expert){
        free(cache->slots);free(cache->by_expert);free(model->cache);
        st_destroy(&model->S);memset(model,0,sizeof(*model));return -1;
    }
    cache->by_expert[0]=cache->by_expert[1]=-1;return 0;
}

atic void destroy_fixture_model(Model *model){
    if(model->cache){
        for(int slot=0;slot<model->cache[0].n;slot++){
            q38_weight_free(&model->cache[0].slots[slot].gate);
            q38_weight_free(&model->cache[0].slots[slot].up);
            q38_weight_free(&model->cache[0].slots[slot].down);
            free(model->cache[0].slots[slot].fp8_slab);
        }
        free(model->cache[0].slots);free(model->cache[0].by_expert);
    }
    if(model->expert_scales)free(model->expert_scales[0].values);
    free(model->expert_scales);free(model->cache);st_destroy(&model->S);
    memset(model,0,sizeof(*model));
}

atic int init_fixture_moe_layer(Model *model){
    static const float router[4]={1.0f,-1.0f,-1.0f,1.0f};
    static const float shared_gate[4]={0.25f,-0.5f,0.75f,0.125f};
    static const float shared_up[4]={-0.25f,0.5f,0.375f,0.625f};
    static const float shared_down[4]={0.5f,-0.125f,0.25f,0.75f};
    static const float gate[2]={0.2f,-0.35f};
    Layer *layer=(Layer*)calloc(1,sizeof(*layer));
    if(!layer)return -1;
    q38_weight_reserve(&layer->router,Q38_WEIGHT_F32,2,2);
    q38_weight_reserve(&layer->sh_g,Q38_WEIGHT_F32,2,2);
    q38_weight_reserve(&layer->sh_u,Q38_WEIGHT_F32,2,2);
    q38_weight_reserve(&layer->sh_d,Q38_WEIGHT_F32,2,2);
    memcpy(layer->router.data,router,sizeof router);
    memcpy(layer->sh_g.data,shared_gate,sizeof shared_gate);
    memcpy(layer->sh_u.data,shared_up,sizeof shared_up);
    memcpy(layer->sh_d.data,shared_down,sizeof shared_down);
    layer->sh_gate=(float*)malloc(sizeof gate);
    if(!layer->sh_gate){
        q38_weight_free(&layer->router);q38_weight_free(&layer->sh_g);
        q38_weight_free(&layer->sh_u);q38_weight_free(&layer->sh_d);
        free(layer);return -1;
    }
    memcpy(layer->sh_gate,gate,sizeof gate);model->L=layer;
    return 0;
}

atic void destroy_fixture_moe_layer(Model *model){
    if(!model->L)return;
    q38_weight_free(&model->L[0].router);q38_weight_free(&model->L[0].sh_g);
    q38_weight_free(&model->L[0].sh_u);q38_weight_free(&model->L[0].sh_d);
    free(model->L[0].sh_gate);free(model->L);model->L=NULL;
}

atic int verify_loaded_fp8_weight(const Q38Weight *weight,int expert,
                                    int projection,int native_fp8){
    int rows=projection==2?2:3,cols=projection==2?3:2;
    if(!weight||weight->rows!=rows||weight->cols!=cols||
       weight->kind!=(native_fp8?Q38_WEIGHT_FP8:Q38_WEIGHT_F32))return -1;
    float scale=fixture_fp8_scale(expert,projection);
    for(int index=0;index<rows*cols;index++){
        uint8_t raw=fixture_fp8_byte(expert,projection,index);
        if(native_fp8){
            if(((const uint8_t*)weight->data)[index]!=raw||
               weight->scale_count!=1||weight->scales[0]!=scale)return -1;
        }else if(((const float*)weight->data)[index]!=e4m3_decode(raw)*scale)
            return -1;
    }
    float input[3]={0.75f,-0.5f,0.25f},got[3]={0},want[3]={0};
    for(int row=0;row<rows;row++){
        float subtotal=0.0f;
        for(int col=0;col<cols;col++){
            float value=e4m3_decode(fixture_fp8_byte(
                expert,projection,row*cols+col));
            if(!native_fp8)value*=scale;
            subtotal+=value*input[col];
        }
        want[row]=native_fp8?(float)((double)subtotal*(double)scale):subtotal;
    }
    q38_weight_matmul(got,input,weight,1,cols,rows);
    return memcmp(got,want,(size_t)rows*sizeof(float))?-1:0;
}

atic int verify_loaded_fp8_slot(const Slot *slot,int expert,int native_fp8){
    return verify_loaded_fp8_weight(&slot->gate,expert,0,native_fp8)||
           verify_loaded_fp8_weight(&slot->up,expert,1,native_fp8)||
           verify_loaded_fp8_weight(&slot->down,expert,2,native_fp8)?-1:0;
}

atic int check_fixture_mode(const char *directory,int native_fp8,int expect_fast){
    Model model;if(init_fixture_model(&model,directory,native_fp8))return -1;
    int result=-1;
    uint64_t bytes_per_capacity=0,fixed_scale_bytes=0;unsigned numeric_kinds=0;
    if(q38_segment_expert_layout(&model,0,1,&bytes_per_capacity,
                                 &fixed_scale_bytes,&numeric_kinds))
        goto cleanup;
    char numeric_class[96];
    q38_segment_numeric_class(numeric_class,sizeof numeric_class,numeric_kinds);
    if(native_fp8){
        if(bytes_per_capacity!=18||fixed_scale_bytes!=24||
           numeric_kinds!=Q38_EXPERT_FP8_BLOCK||
           strcmp(numeric_class,
                  "qwen38/fp8-block-f32dot-f64blocksum/cpu-v1"))goto cleanup;
    }else if(bytes_per_capacity!=72||fixed_scale_bytes||
              numeric_kinds!=Q38_EXPERT_FP8_EXPANDED||
              strcmp(numeric_class,
                     "qwen38/fp8-expanded-f32dot/cpu-v1"))goto cleanup;
    int capacity=0;
    if(q38_segment_cache_capacity(bytes_per_capacity,fixed_scale_bytes,2,
                                  fixed_scale_bytes+bytes_per_capacity*2,
                                  &capacity)||capacity!=2||
       !q38_segment_cache_capacity(bytes_per_capacity,fixed_scale_bytes,2,
                                   fixed_scale_bytes+bytes_per_capacity-1,
                                   &capacity))goto cleanup;
    if(q38_segment_cache_resize(&model,2)||model.cache[0].cap!=2||
       q38_segment_cache_resize(&model,1)||model.cache[0].cap!=1)goto cleanup;

    Slot *first=q38_expert_get(&model,0,0);if(!first)goto cleanup;
    Q38WeightKind expected=native_fp8?Q38_WEIGHT_FP8:Q38_WEIGHT_F32;
    if(first->gate.kind!=expected||first->up.kind!=expected||
       first->down.kind!=expected||model.miss!=1||model.hits!=0||
       verify_loaded_fp8_slot(first,0,native_fp8))goto cleanup;
    void *slab=first->fp8_slab;
    if(expect_fast){
        if(!native_fp8||!slab||first->gate.data!=slab||
           first->up.data!=(unsigned char*)slab+6||
           first->down.data!=(unsigned char*)slab+12||
           model.expert_weight_reads!=2||model.expert_scale_reads!=2||
           model.expert_pair_reads!=1||model.expert_scale_bytes!=24)
            goto cleanup;
    }else if(model.expert_pair_reads||slab)goto cleanup;
    float first_value=native_fp8?e4m3_decode(((uint8_t*)first->gate.data)[0])*
                                  first->gate.scales[0]:
                                 ((float*)first->gate.data)[0];
    if(q38_expert_get(&model,0,0)!=first||model.miss!=1||model.hits!=1)goto cleanup;
    Slot *second=q38_expert_get(&model,0,1);
    if(second!=first||model.cache[0].by_expert[0]!=-1||
       model.cache[0].by_expert[1]!=0||model.miss!=2||model.hits!=1||
       verify_loaded_fp8_slot(second,1,native_fp8))goto cleanup;
    if(expect_fast&&(second->fp8_slab!=slab||model.expert_weight_reads!=4||
                     model.expert_scale_reads!=2||model.expert_pair_reads!=2))
        goto cleanup;
    float second_value=native_fp8?e4m3_decode(((uint8_t*)second->gate.data)[0])*
                                   second->gate.scales[0]:
                                  ((float*)second->gate.data)[0];
    if(first_value==second_value)goto cleanup;
    if(q38_expert_get(&model,0,0)!=first||model.cache[0].by_expert[0]!=0||
       model.cache[0].by_expert[1]!=-1||model.miss!=3)goto cleanup;
    if(expect_fast&&(first->fp8_slab!=slab||model.expert_weight_reads!=6||
                     model.expert_scale_reads!=2||model.expert_pair_reads!=3))
        goto cleanup;
    result=0;
cleanup:
    destroy_fixture_model(&model);return result;
}

atic int check_mixed_layout(const char *directory,int native_fp8,
                              uint64_t expected_bytes,unsigned expected_kinds,
                              const char *expected_class){
    Model model;if(init_fixture_model(&model,directory,native_fp8))return -1;
    uint64_t bytes=0,fixed=0;unsigned kinds=0;char numeric_class[96];int result=-1;
    if(!q38_segment_expert_layout(&model,0,1,&bytes,&fixed,&kinds)){
        q38_segment_numeric_class(numeric_class,sizeof numeric_class,kinds);
        if(bytes==expected_bytes&&!fixed&&kinds==expected_kinds&&
           !strcmp(numeric_class,expected_class)){
            Slot *slot=q38_expert_get(&model,0,0);
            if(slot&&!verify_loaded_fp8_slot(slot,0,native_fp8)&&
               q38_expert_get(&model,0,1)==slot&&
               slot->gate.kind==Q38_WEIGHT_BF16&&
               slot->up.kind==(native_fp8?Q38_WEIGHT_FP8:Q38_WEIGHT_F32)&&
               slot->down.kind==(native_fp8?Q38_WEIGHT_FP8:Q38_WEIGHT_F32)&&
               model.cache[0].by_expert[0]==-1&&
               model.cache[0].by_expert[1]==0){
                int bf16_ok=1;
                const uint16_t *gate=(const uint16_t*)slot->gate.data;
                for(int index=0;index<6;index++)
                    if(gate[index]!=to_bf16(0.0625f*(float)(8+index)))bf16_ok=0;
                if(bf16_ok&&!verify_loaded_fp8_weight(&slot->up,1,1,native_fp8)&&
                   !verify_loaded_fp8_weight(&slot->down,1,2,native_fp8)&&
                   q38_expert_get(&model,0,0)==slot&&
                   slot->gate.kind==(native_fp8?Q38_WEIGHT_FP8:Q38_WEIGHT_F32)&&
                   model.cache[0].by_expert[0]==0&&
                   model.cache[0].by_expert[1]==-1)result=0;
            }
        }
    }
    destroy_fixture_model(&model);return result;
}

atic int check_parallel_batch(const char *directory){
    Model model;if(init_fixture_model(&model,directory,1))return -1;
    int result=-1;model.expert_parallel_reads=1;
    int first_ids[2]={1,0};Slot *first[2]={0};
    if(q38_expert_get_batch(&model,0,first_ids,2,first)||model.cache[0].n||
       model.miss||model.hits)goto cleanup;
    if(q38_segment_cache_resize(&model,2))goto cleanup;
    if(!q38_expert_get_batch(&model,0,first_ids,2,first)||!first[0]||!first[1]||
       first[0]==first[1]||first[0]->eid!=1||first[1]->eid!=0||
       model.miss!=2||model.hits||model.expert_parallel_batches!=1||
       model.expert_weight_reads!=4||model.expert_scale_reads!=2||
       model.expert_pair_reads!=2||verify_loaded_fp8_slot(first[0],1,1)||
       verify_loaded_fp8_slot(first[1],0,1))goto cleanup;
    int second_ids[2]={0,1};Slot *second[2]={0};
    if(!q38_expert_get_batch(&model,0,second_ids,2,second)||
       second[0]!=first[1]||second[1]!=first[0]||model.miss!=2||
       model.hits!=2||model.expert_parallel_batches!=1||
       model.expert_weight_reads!=4)goto cleanup;
    result=0;
cleanup:
    destroy_fixture_model(&model);return result;
}

atic int check_malformed_scale_metadata(const char *directory){
    Model model;if(init_fixture_model(&model,directory,1))return -1;
    char name[320];
    q38_name(&model,name,sizeof name,0,
             "mlp.experts.0.gate_proj.weight_scale_inv");
    st_tensor *scale=st_find(&model.S,name);int result=-1;
    if(scale){
        int64_t original_bytes=scale->nbytes;
        scale->nbytes++;
        uint64_t bytes=0,fixed=0;unsigned kinds=0;
        if(q38_segment_expert_layout(&model,0,1,&bytes,&fixed,&kinds)&&
           !q38_prepare_expert_scale_bank(&model,0))result=0;
        scale->nbytes=original_bytes;
    }
    destroy_fixture_model(&model);return result;
}

atic int check_moe_prefill_parity(const char *directory,int native_fp8,
                                    int cache_capacity){
    static const float input[6]={0.5f,-0.25f,0.5f,-0.25f,0.5f,-0.25f};
    Model prefill={0},decode={0};float batched[6],serial[6];int result=-1;
    if(init_fixture_model(&prefill,directory,native_fp8) ||
       init_fixture_model(&decode,directory,native_fp8) ||
       init_fixture_moe_layer(&prefill) || init_fixture_moe_layer(&decode))
        goto cleanup;
    prefill.c.norm_topk=1;decode.c.norm_topk=1;
    if(cache_capacity!=1&&q38_segment_cache_resize(&prefill,cache_capacity))
        goto cleanup;
    if(cache_capacity!=1&&q38_segment_cache_resize(&decode,cache_capacity))
        goto cleanup;
    prefill.expert_parallel_reads=1;
    q38_moe(&prefill,prefill.L,0,input,3,batched);
    for(int row=0;row<3;row++)
        q38_moe_decode(&decode,decode.L,0,input+(int64_t)row*2,1,
                       serial+(int64_t)row*2);
    if(memcmp(batched,serial,sizeof batched)){
        fprintf(stderr,"prefill parity mismatch native=%d cap=%d:\n",native_fp8,cache_capacity);
        for(int i=0;i<6;i++)fprintf(stderr," %d %.9g %.9g\n",i,batched[i],serial[i]);
        goto cleanup;
    }
    /* Every row routes to both experts.  The grouped prefill loads each expert
     * once, even with a one-slot cache; serial decode must reload both experts
     * for every row.  Native FP8 uses two physical payload ranges per load. */
    uint64_t reads_per_expert=native_fp8?2:3;
    uint64_t expected_decode_misses=cache_capacity>=2?2:6;
    uint64_t expected_decode_reads=expected_decode_misses*reads_per_expert;
    if(prefill.miss!=2||decode.miss!=expected_decode_misses||
       prefill.expert_weight_reads!=2*reads_per_expert||
       decode.expert_weight_reads!=expected_decode_reads){
        fprintf(stderr,"prefill metrics mismatch native=%d cap=%d: miss %llu/%llu reads %llu/%llu\n",
                native_fp8,cache_capacity,(unsigned long long)prefill.miss,
                (unsigned long long)decode.miss,(unsigned long long)prefill.expert_weight_reads,
                (unsigned long long)decode.expert_weight_reads);
        goto cleanup;
    }
    if(cache_capacity>=2&&
       (prefill.hits!=0||decode.hits!=4||
        prefill.expert_parallel_batches!=(native_fp8?1u:0u))){
        fprintf(stderr,"prefill cache metrics mismatch native=%d cap=%d: hits %llu/%llu batches %llu\n",
                native_fp8,cache_capacity,(unsigned long long)prefill.hits,
                (unsigned long long)decode.hits,(unsigned long long)prefill.expert_parallel_batches);
        goto cleanup;
    }
    result=0;
cleanup:
    destroy_fixture_moe_layer(&prefill);destroy_fixture_moe_layer(&decode);
    destroy_fixture_model(&prefill);destroy_fixture_model(&decode);return result;
}

atic int check_mixed_moe_prefill_parity(const char *directory){
    static const float input[6]={0.5f,-0.25f,0.5f,-0.25f,0.5f,-0.25f};
    Model prefill={0},decode={0};float batched[6],serial[6];int result=-1;
    if(init_fixture_model(&prefill,directory,1)||
       init_fixture_model(&decode,directory,1)||
       init_fixture_moe_layer(&prefill)||init_fixture_moe_layer(&decode))
        goto cleanup;
    prefill.c.norm_topk=1;decode.c.norm_topk=1;
    q38_moe(&prefill,prefill.L,0,input,3,batched);
    for(int row=0;row<3;row++)
        q38_moe_decode(&decode,decode.L,0,input+(int64_t)row*2,1,
                       serial+(int64_t)row*2);
    if(!memcmp(batched,serial,sizeof batched)&&prefill.miss==2&&decode.miss==6)
        result=0;
cleanup:
    destroy_fixture_moe_layer(&prefill);destroy_fixture_moe_layer(&decode);
    destroy_fixture_model(&prefill);destroy_fixture_model(&decode);return result;
}

atic void fill_test_weight(Q38Weight *weight,int rows,int columns,int salt){
    q38_weight_reserve(weight,Q38_WEIGHT_F32,rows,columns);
    float *values=(float*)weight->data;
    for(int index=0;index<rows*columns;index++)
        values[index]=(float)(((index+1)*(salt+3))%17-8)/16.f;
}

atic int check_deltanet_prefill_parity(void){
    enum { ROWS=3,H=2,VH=1,KH=1,KD=2,VD=2,V=VH*VD,CD=2*KH*KD+V,CK=2 };
    Cfg config={0};
    config.hidden=H;config.dn_vheads=VH;config.dn_kheads=KH;
    config.dn_kdim=KD;config.dn_vdim=VD;config.dn_conv_dim=CD;
    config.dn_convk=CK;config.eps=1e-6f;
    Layer layer={0};
    fill_test_weight(&layer.dn_qkv,CD,H,1);
    fill_test_weight(&layer.dn_z,V,H,2);
    fill_test_weight(&layer.dn_b,VH,H,3);
    fill_test_weight(&layer.dn_a,VH,H,4);
    fill_test_weight(&layer.dn_out,H,V,5);
    layer.dn_conv=(float*)malloc((size_t)CD*CK*sizeof(float));
    layer.dn_dtbias=(float*)malloc(VH*sizeof(float));
    layer.dn_alog=(float*)malloc(VH*sizeof(float));
    layer.dn_norm=(float*)malloc(VD*sizeof(float));
    if(!layer.dn_conv||!layer.dn_dtbias||!layer.dn_alog||!layer.dn_norm)
        goto fail;
    for(int index=0;index<CD*CK;index++)
        layer.dn_conv[index]=(float)((index%7)-3)/16.f;
    layer.dn_dtbias[0]=0.125f;layer.dn_alog[0]=-0.75f;
    layer.dn_norm[0]=0.875f;layer.dn_norm[1]=1.125f;

    float recurrence_a[VH*KD*VD]={0},recurrence_b[VH*KD*VD]={0};
    float convolution_a[CD*(CK-1)]={0},convolution_b[CD*(CK-1)]={0};
    float *recurrence_rows_a[1]={recurrence_a},*recurrence_rows_b[1]={recurrence_b};
    float *convolution_rows_a[1]={convolution_a},*convolution_rows_b[1]={convolution_b};
    Model batched={0},serial={0};
    batched.c=config;serial.c=config;
    batched.prefill_batch=1;
    batched.DN_rec=recurrence_rows_a;serial.DN_rec=recurrence_rows_b;
    batched.DN_conv=convolution_rows_a;serial.DN_conv=convolution_rows_b;
    float input[ROWS*H]={0.5f,-0.25f,-0.75f,0.625f,0.125f,0.875f};
    float output_a[ROWS*H],output_b[ROWS*H];
    q38_deltanet(&batched,&layer,0,input,ROWS,output_a);
    for(int row=0;row<ROWS;row++)
        q38_deltanet(&serial,&layer,0,input+(int64_t)row*H,1,
                     output_b+(int64_t)row*H);
    if(memcmp(output_a,output_b,sizeof output_a)||
       memcmp(recurrence_a,recurrence_b,sizeof recurrence_a)||
       memcmp(convolution_a,convolution_b,sizeof convolution_a))goto fail;

    q38_weight_free(&layer.dn_qkv);q38_weight_free(&layer.dn_z);
    q38_weight_free(&layer.dn_b);q38_weight_free(&layer.dn_a);
    q38_weight_free(&layer.dn_out);free(layer.dn_conv);free(layer.dn_dtbias);
    free(layer.dn_alog);free(layer.dn_norm);return 0;
fail:
    q38_weight_free(&layer.dn_qkv);q38_weight_free(&layer.dn_z);
    q38_weight_free(&layer.dn_b);q38_weight_free(&layer.dn_a);
    q38_weight_free(&layer.dn_out);free(layer.dn_conv);free(layer.dn_dtbias);
    free(layer.dn_alog);free(layer.dn_norm);return -1;
}

atic int check_segment_failure_outputs(void){
    Model partial={0};partial.c.layers=1;q38_model_free(&partial);
    char error[128];void *output=(void*)(uintptr_t)1;
    ColiSegmentCapabilities capabilities;
    ColiSegmentEngineOptions engine_options={
        .struct_size=sizeof(engine_options),.model_dir="unused",
        .context_tokens=1,.backend_mask=COLI_SEGMENT_CAP_CUDA,
    };
    if(!qwen38_segment_engine_open(&output,&capabilities,&engine_options,
                                   error,sizeof error)||output)return -1;

    Qwen38SegmentEngine engine={0};engine.context_tokens=1;
    ColiSegmentSessionOptions session_options={
        .struct_size=sizeof(session_options),.context_tokens=2,
    };
    output=(void*)(uintptr_t)1;
    if(!qwen38_segment_session_create(&engine,&output,&session_options,
                                      error,sizeof error)||output)return -1;
    return 0;
}

t main(void){
    enum { S=2, I=257, O=129 };
    Q38Weight fp8={0};q38_weight_reserve(&fp8,Q38_WEIGHT_FP8,O,I);
    CHECK(fp8.scale_count==6);CHECK(q38_weight_bytes(&fp8)==(uint64_t)O*I+6*sizeof(float));
    uint8_t *raw=(uint8_t*)fp8.data;
    for(int64_t i=0;i<fp8.elements;i++)raw[i]=(uint8_t)((i*17+13)%0x7f);
    for(int64_t block=0;block<fp8.scale_count;block++)
        fp8.scales[block]=(float)(block+1)*0.25f*(block&1?-1.0f:1.0f);
    float x[S*I];for(int i=0;i<S*I;i++)x[i]=(float)((i%19)-9)/7.f;
    float want[S*O],got[S*O];
    reference_fp8_matmul(want,x,raw,fp8.scales,S,I,O);
    q38_weight_matmul(got,x,&fp8,S,I,O);
    CHECK(!memcmp(want,got,sizeof want));
    void *same=fp8.data;q38_weight_reserve(&fp8,Q38_WEIGHT_FP8,O,I);
    CHECK(fp8.data==same);
    q38_weight_free(&fp8);CHECK(fp8.kind==Q38_WEIGHT_NONE&&!fp8.data&&!fp8.scales);

    enum { BI=9, BO=4, BS=3 };
    Q38Weight bf16={0};q38_weight_reserve(&bf16,Q38_WEIGHT_BF16,BO,BI);
    uint16_t *half=(uint16_t*)bf16.data;float full[BO*BI];
    for(int i=0;i<BO*BI;i++){
        float value=(float)((i%11)-5)*0.125f;
        half[i]=to_bf16(value);full[i]=bf16_to_f32(half[i]);
    }
    float bx[BS*BI],bwant[BS*BO],bgot[BS*BO];
    for(int i=0;i<BS*BI;i++)bx[i]=(float)((i%7)-3)*0.25f;
    q38_matmul(bwant,bx,full,BS,BI,BO);
    q38_weight_matmul(bgot,bx,&bf16,BS,BI,BO);
    CHECK(!memcmp(bwant,bgot,sizeof bwant));
    float row[BI];q38_weight_row(&bf16,2,row);
    CHECK(!memcmp(row,full+2*BI,sizeof row));
    CHECK(q38_weight_bytes(&bf16)==(uint64_t)BO*BI*sizeof(uint16_t));
    q38_weight_free(&bf16);

    char directory[]="test_qwen38_native_XXXXXX";CHECK(mkdtemp(directory)!=NULL);
    CHECK(write_fp8_fixture(directory,0,0)==0);
    CHECK(check_fixture_mode(directory,1,0)==0);
    CHECK(check_fixture_mode(directory,0,0)==0);
    char path[512];int path_length=snprintf(path,sizeof path,
                                           "%s/model.safetensors",directory);
    CHECK(path_length>0&&(size_t)path_length<sizeof path);
    CHECK(remove(path)==0);CHECK(rmdir(directory)==0);

    char mixed_directory[]="test_qwen38_mixed_XXXXXX";
    CHECK(mkdtemp(mixed_directory)!=NULL);
    CHECK(write_fp8_fixture(mixed_directory,1,0)==0);
    CHECK(check_mixed_layout(mixed_directory,1,32,
          Q38_EXPERT_FP8_BLOCK|Q38_EXPERT_BF16,
          "qwen38/mixed-expert-arithmetic-05/cpu-v1")==0);
    CHECK(check_mixed_layout(mixed_directory,0,72,
          Q38_EXPERT_FP8_EXPANDED|Q38_EXPERT_BF16,
          "qwen38/mixed-expert-arithmetic-06/cpu-v1")==0);
    CHECK(check_mixed_moe_prefill_parity(mixed_directory)==0);
    path_length=snprintf(path,sizeof path,"%s/model.safetensors",mixed_directory);
    CHECK(path_length>0&&(size_t)path_length<sizeof path);
    CHECK(remove(path)==0);CHECK(rmdir(mixed_directory)==0);

    char adjacent_directory[]="test_qwen38_adjacent_XXXXXX";
    CHECK(mkdtemp(adjacent_directory)!=NULL);
    CHECK(write_fp8_fixture(adjacent_directory,0,1)==0);
    CHECK(check_fixture_mode(adjacent_directory,1,1)==0);
    CHECK(check_fixture_mode(adjacent_directory,0,0)==0);
    CHECK(check_parallel_batch(adjacent_directory)==0);
    CHECK(check_malformed_scale_metadata(adjacent_directory)==0);
    CHECK(check_moe_prefill_parity(adjacent_directory,1,1)==0);
    CHECK(check_moe_prefill_parity(adjacent_directory,1,2)==0);
    CHECK(check_moe_prefill_parity(adjacent_directory,0,1)==0);
    CHECK(check_deltanet_prefill_parity()==0);
    path_length=snprintf(path,sizeof path,"%s/model.safetensors",adjacent_directory);
    CHECK(path_length>0&&(size_t)path_length<sizeof path);
    CHECK(remove(path)==0);CHECK(rmdir(adjacent_directory)==0);

    CHECK(check_segment_failure_outputs()==0);

    puts("qwen38 native weights: FP8 oracle, coalesced slabs/scales, parallel demand sets, fallbacks, adapter failures: ok");
    return 0;
}

static void fill_state(Model *m,float value){
    for(int i=0;i<m->c.layers;i++)if(!m->c.is_attn[i]){
        for(size_t j=0;j<g_q38_prefix.rec_cells;j++)m->DN_rec[i][j]=value;
        for(size_t j=0;j<g_q38_prefix.conv_cells;j++)m->DN_conv[i][j]=value+1.f;
    }
    for(size_t j=0;j<g_q38_prefix.ple_cells;j++)m->PLE_conv_state[j]=value+2.f;
    m->ple_history_len=2;m->ple_history[0]=41;m->ple_history[1]=42;
}

static int check_state(const Model *m,float value){
    for(int i=0;i<m->c.layers;i++)if(!m->c.is_attn[i]){
        for(size_t j=0;j<g_q38_prefix.rec_cells;j++)if(m->DN_rec[i][j]!=value)return 0;
        for(size_t j=0;j<g_q38_prefix.conv_cells;j++)if(m->DN_conv[i][j]!=value+1.f)return 0;
    }
    for(size_t j=0;j<g_q38_prefix.ple_cells;j++)if(m->PLE_conv_state[j]!=value+2.f)return 0;
    return m->ple_history_len==2&&m->ple_history[0]==41&&m->ple_history[1]==42;
}

static void free_fake(Model *m){
    q38_prefix_cache_release(m);
    for(int i=0;i<m->c.layers;i++){
        free(m->DN_rec[i]);free(m->DN_conv[i]);
        free(m->K[i]);free(m->V[i]);free(m->IK[i]);
    }
    free(m->DN_rec);free(m->DN_conv);free(m->K);free(m->V);free(m->IK);
    free(m->PLE_conv_state);free(m->ple_history);free(m->c.is_attn);
}

int main(void){
    Model m={0};
    m.c.layers=2;m.c.vocab=8;m.c.dn_vheads=1;m.c.dn_kdim=2;m.c.dn_vdim=2;
    m.c.dn_conv_dim=2;m.c.dn_convk=3;m.c.ple_layer=1;m.c.hc_width=2;
    m.c.ple_convk=3;m.c.ngram_size=1;m.c.is_attn=calloc(2,1);CHECK(m.c.is_attn);
    m.c.is_attn[1]=1;
    m.DN_rec=calloc(2,sizeof(float*));m.DN_conv=calloc(2,sizeof(float*));
    m.K=calloc(2,sizeof(float*));m.V=calloc(2,sizeof(float*));m.IK=calloc(2,sizeof(float*));
    CHECK(m.DN_rec&&m.DN_conv&&m.K&&m.V&&m.IK);
    m.DN_rec[0]=calloc(4,sizeof(float));m.DN_conv[0]=calloc(4,sizeof(float));
    m.PLE_conv_state=calloc(4,sizeof(float));m.ple_history=calloc(2,sizeof(int64_t));
    CHECK(m.DN_rec[0]&&m.DN_conv[0]&&m.PLE_conv_state&&m.ple_history);
    CHECK(q38_prefix_cache_layout(&m));

    /* Serve allocates its planned QSA ceiling once.  Reuse must preserve the
     * position-indexed prefix without a second allocation or growth peak. */
    m.c.kv_heads=1;m.c.head_dim=2;m.c.idx_dim=2;
    CHECK(q38_serve_ensure_kv(&m,6));CHECK(m.kv_cap==6);m.kv_len=3;
    float *initial_k=m.K[1],*initial_v=m.V[1],*initial_ik=m.IK[1];
    for(int i=0;i<6;i++){m.K[1][i]=(float)i;m.V[1][i]=(float)(10+i);m.IK[1][i]=(float)(20+i);}

    const int first[]={1,2,3};float first_logits[8];
    for(int i=0;i<8;i++)first_logits[i]=(float)(100+i);
    fill_state(&m,7.f);CHECK(q38_prefix_cache_save(&m,first,3,first_logits));
    fill_state(&m,99.f);m.kv_len=3;
    const int extension[]={1,2,3,4};
    CHECK(q38_prefix_restore(&m,extension,4)==3);CHECK(check_state(&m,7.f));
    CHECK(q38_serve_ensure_kv(&m,6));CHECK(m.kv_cap==6&&m.kv_len==3);
    CHECK(m.K[1]==initial_k&&m.V[1]==initial_v&&m.IK[1]==initial_ik);
    CHECK(!q38_serve_ensure_kv(&m,7));
    for(int i=0;i<6;i++){CHECK(m.K[1][i]==(float)i);CHECK(m.V[1][i]==(float)(10+i));CHECK(m.IK[1][i]==(float)(20+i));}

    /* An exact prompt restores the recurrent state and its saved logits. */
    fill_state(&m,55.f);CHECK(q38_prefix_restore(&m,first,3)==3);CHECK(check_state(&m,7.f));
    fill_state(&m,56.f);CHECK(q38_prefix_restore(&m,extension,4)==3);CHECK(check_state(&m,7.f));
    CHECK(q38_prefix_cache_save(&m,extension,4,first_logits));
    fill_state(&m,88.f);CHECK(q38_prefix_restore(&m,extension,4)==4);CHECK(check_state(&m,7.f));
    const float *cached=q38_prefix_cached_logits(&m);CHECK(cached&&cached[0]==100.f&&cached[7]==107.f);

    /* A mismatch is never restored; the serve miss path invalidates then
     * resets the live recurrent state before feeding the new prompt. */
    const int shorter[]={1,2,3};CHECK(q38_prefix_restore(&m,shorter,3)==0);
    const int mismatch[]={1,2,4};CHECK(q38_prefix_restore(&m,mismatch,3)==0);
    q38_prefix_cache_invalidate();reset_recurrent(&m);m.kv_len=0;
    CHECK(!g_q38_prefix.valid&&m.kv_len==0&&m.ple_history_len==0);
    for(size_t i=0;i<g_q38_prefix.rec_cells;i++)CHECK(m.DN_rec[0][i]==0.f);
    for(size_t i=0;i<g_q38_prefix.conv_cells;i++)CHECK(m.DN_conv[0][i]==0.f);
    for(size_t i=0;i<g_q38_prefix.ple_cells;i++)CHECK(m.PLE_conv_state[i]==0.f);
    free_fake(&m);
    puts("qwen38 prefix: single QSA allocation, exact/extension reuse, reset: ok");
    return 0;
}

static FILE *input_with(const char *bytes){
    FILE *file=tmpfile();
    if(!file)return NULL;
    size_t n=strlen(bytes);
    if(fwrite(bytes,1,n,file)!=n||fseek(file,0,SEEK_SET)){fclose(file);return NULL;}
    return file;
}

int main(void){
    CHECK(q38_reference_mode("ref.json",0)==1);
    CHECK(q38_reference_mode("prompt.txt",0)==0);
    CHECK(q38_reference_mode("ref.json",1)==0);
    CHECK(fabs(q38_decode_rate(3,0.5)-4.0)<1e-12);
    CHECK(q38_decode_rate(1,0.5)==0.0);
    CHECK(q38_decode_rate(3,0.0)==0.0);
    FILE *out=tmpfile();CHECK(out!=NULL);
    FILE *in=input_with("SUBMIT req 0 5 2 0 1\nHello\n");CHECK(in!=NULL);
    ServeReq q={0};
    CHECK(serve_read_req(in,out,&q,NULL)==2);
    CHECK(!strcmp(q.id,"req")&&q.slot==0&&q.max_tok==2&&q.plen==5&&!strcmp(q.payload,"Hello"));
    free(q.payload);fclose(in);

    /* The wire codec must consume a valid frame before the one-slot policy
     * rejects a nonzero cache slot, so the following command remains aligned. */
    in=input_with("SUBMIT wrong 7 5 1 0 1\nHello\nCANCEL wrong\n");CHECK(in!=NULL);
    CHECK(serve_read_req(in,out,NULL,NULL)==0);
    CHECK(serve_read_req(in,out,NULL,"wrong")==3);
    fclose(in);

    in=input_with("STOP req\nCANCEL req\n");CHECK(in!=NULL);
    CHECK(serve_read_req(in,out,NULL,"req")==1);
    CHECK(serve_read_req(in,out,NULL,"req")==3);
    fclose(in);

    /* The rejected payload must be drained or the following CANCEL would be
     * parsed from "Hello" and silently lost. */
    in=input_with("SUBMIT queued 0 5 1 0 1\nHello\nCANCEL req\n");CHECK(in!=NULL);
    CHECK(serve_read_req(in,out,NULL,"req")==0);
    CHECK(serve_read_req(in,out,NULL,"req")==3);
    fclose(in);

    in=input_with("SUBMIT bad 0 0 1 nan 1\n\n");CHECK(in!=NULL);
    CHECK(serve_read_req(in,out,&q,NULL)==0);
    fclose(in);fclose(out);
    puts("qwen38 serve framing: mode, decode rate, submit, busy drain, stop, cancel: ok");
    return 0;
}

static float *json_floats(jval *node, int64_t *count)
{
    if (!node || node->t != J_ARR) return NULL;
    float *out = (float *)malloc((size_t)node->len * sizeof(float));
    if (!out) return NULL;
    for (int i = 0; i < node->len; i++) out[i] = (float)node->kids[i]->num;
    *count = node->len;
    return out;
}

static const float *want_tensor(shards *S, const char *name, int64_t expect)
{
    char full[512];
    snprintf(full, sizeof full, "model.visual.%s", name);
    st_tensor *t = st_find(S, full);
    if (!t) { fprintf(stderr, "manca il tensore %s\n", full); exit(1); }
    if (expect > 0 && t->numel != expect) {
        fprintf(stderr, "%s ha %lld valori, ne servono %lld\n",
                full, (long long)t->numel, (long long)expect); exit(1);
    }
    float *buf = (float *)malloc((size_t)t->numel * sizeof(float));
    if (!buf) { fprintf(stderr, "OOM su %s\n", full); exit(1); }
    st_read_f32(S, full, buf, t->numel);
    return buf;
}

static void load_linear(shards *S, Q38Linear *l, const char *stem, int out, int in)
{
    char name[256];
    snprintf(name, sizeof name, "%s.weight", stem);
    l->w = want_tensor(S, name, (int64_t)out * in);
    snprintf(name, sizeof name, "%s.bias", stem);
    l->b = want_tensor(S, name, out);
    l->out = out; l->in = in;
}

static void load_norm(shards *S, Q38Norm *n, const char *stem, int width)
{
    char name[256];
    snprintf(name, sizeof name, "%s.weight", stem);
    n->w = want_tensor(S, name, width);
    snprintf(name, sizeof name, "%s.bias", stem);
    n->b = want_tensor(S, name, width);
}

static int compare(const char *label, const float *got, const float *want,
                   int64_t count, float tolerance)
{
    double worst = 0.0; int64_t at = -1;
    for (int64_t i = 0; i < count; i++) {
        double delta = fabs((double)got[i] - (double)want[i]);
        if (delta > worst) { worst = delta; at = i; }
    }
    if (worst <= tolerance) {
        printf("  ok   %-14s %lld valori, scarto max %.3e\n", label, (long long)count, worst);
        return 0;
    }
    printf("  FAIL %-14s scarto max %.3e a %lld (nostro %.6f, riferimento %.6f)\n",
           label, worst, (long long)at, got[at], want[at]);
    return 1;
}

int main(int argc, char **argv)
{
    /* `make test-c` esegue ogni tests/test_* SENZA argomenti. Senza fixture
     * questo test non ha verificato niente, e dirlo saltato e' l'unica risposta
     * onesta: uscire con errore lo farebbe fallire su ogni macchina che non ha
     * ancora generato la fixture, e uscire con successo sarebbe una bugia. */
    const char *fixture = (argc >= 2) ? argv[1] : "./qwen38_vision_tiny";
    char path[1024];
    snprintf(path, sizeof path, "%s/ref_vision.json", fixture);
    FILE *f = fopen(path, "rb");
    if (!f) { printf("SKIP: manca %s; genera la fixture con "
                     "tools/make_qwen38_vision_tiny.py\n", path); return 0; }
    fseek(f, 0, SEEK_END); long size = ftell(f); fseek(f, 0, SEEK_SET);
    char *text = (char *)malloc((size_t)size + 1);
    if (!text || fread(text, 1, (size_t)size, f) != (size_t)size) {
        fprintf(stderr, "lettura di %s fallita\n", path); return 1; }
    text[size] = 0; fclose(f);
    char *arena = NULL;
    jval *ref = json_parse(text, &arena);
    if (!ref || ref->t != J_OBJ) { fprintf(stderr, "ref_vision.json malformato\n"); return 1; }

    jval *grid = json_get(ref, "grid");
    int grid_h = (int)grid->kids[1]->num, grid_w = (int)grid->kids[2]->num;
    int hidden = (int)json_get(ref, "hidden_size")->num;
    int out_hidden = (int)json_get(ref, "out_hidden")->num;
    int64_t npix = 0, nout = 0, nlast = 0;
    float *pixels = json_floats(json_get(ref, "pixels"), &npix);
    float *want_out = json_floats(json_get(ref, "output"), &nout);
    float *want_last = json_floats(json_get(ref, "last_hidden"), &nlast);

    shards S; st_init(&S, fixture);

    /* La geometria viene dal config della fixture, non da costanti qui: una
     * torre con dimensioni diverse deve fallire dicendo cosa non torna, non
     * leggere silenziosamente pesi della misura sbagliata. */
    snprintf(path, sizeof path, "%s/config.json", fixture);
    FILE *cf = fopen(path, "rb");
    if (!cf) { fprintf(stderr, "manca %s\n", path); return 1; }
    fseek(cf, 0, SEEK_END); long csize = ftell(cf); fseek(cf, 0, SEEK_SET);
    char *ctext = (char *)malloc((size_t)csize + 1);
    if (!ctext || fread(ctext, 1, (size_t)csize, cf) != (size_t)csize) return 1;
    ctext[csize] = 0; fclose(cf);
    char *carena = NULL;
    jval *cfg = json_get(json_parse(ctext, &carena), "vision_config");
    if (!cfg) { fprintf(stderr, "config.json senza vision_config\n"); return 1; }

    Q38Vision v;
    memset(&v, 0, sizeof v);
    v.depth = (int)json_get(cfg, "depth")->num;
    v.hidden = hidden;
    v.heads = (int)json_get(cfg, "num_heads")->num;
    v.head_dim = v.hidden / v.heads;
    v.inter = (int)json_get(cfg, "intermediate_size")->num;
    v.patch = (int)json_get(cfg, "patch_size")->num;
    v.merge = (int)json_get(cfg, "spatial_merge_size")->num;
    v.temporal = (int)json_get(cfg, "temporal_patch_size")->num;
    v.in_ch = (int)json_get(cfg, "in_channels")->num;
    v.out_hidden = out_hidden;
    v.num_pos = (int)json_get(cfg, "num_position_embeddings")->num;
    v.side = (int)(sqrt((double)v.num_pos) + 0.5);
    v.eps = 1e-6f;

    int features = v.in_ch * v.temporal * v.patch * v.patch;
    load_linear(&S, &v.patch_embed, "patch_embed.proj", v.hidden, features);
    v.pos_embed = want_tensor(&S, "pos_embed.weight", (int64_t)v.num_pos * v.hidden);
    v.blocks = (Q38VBlock *)calloc((size_t)v.depth, sizeof(Q38VBlock));
    for (int i = 0; i < v.depth; i++) {
        char stem[128];
        snprintf(stem, sizeof stem, "blocks.%d.norm1", i);
        load_norm(&S, &v.blocks[i].norm1, stem, v.hidden);
        snprintf(stem, sizeof stem, "blocks.%d.norm2", i);
        load_norm(&S, &v.blocks[i].norm2, stem, v.hidden);
        snprintf(stem, sizeof stem, "blocks.%d.attn.qkv", i);
        load_linear(&S, &v.blocks[i].qkv, stem, 3 * v.hidden, v.hidden);
        snprintf(stem, sizeof stem, "blocks.%d.attn.proj", i);
        load_linear(&S, &v.blocks[i].proj, stem, v.hidden, v.hidden);
        snprintf(stem, sizeof stem, "blocks.%d.mlp.linear_fc1", i);
        load_linear(&S, &v.blocks[i].fc1, stem, v.inter, v.hidden);
        snprintf(stem, sizeof stem, "blocks.%d.mlp.linear_fc2", i);
        load_linear(&S, &v.blocks[i].fc2, stem, v.hidden, v.inter);
    }
    int wide = v.hidden * v.merge * v.merge;
    load_norm(&S, &v.merger_norm, "merger.norm", v.hidden);
    load_linear(&S, &v.merger_fc1, "merger.linear_fc1", wide, wide);
    load_linear(&S, &v.merger_fc2, "merger.linear_fc2", v.out_hidden, wide);

    int patches = grid_h * grid_w;
    if (npix != (int64_t)patches * features) {
        fprintf(stderr, "pixels: %lld valori, ne servono %lld\n",
                (long long)npix, (long long)patches * features);
        return 1;
    }
    float *out = (float *)calloc((size_t)patches, sizeof(float) * (size_t)v.out_hidden);
    float *last = (float *)calloc((size_t)patches * v.hidden, sizeof(float));
    int tokens = q38_vision_forward_dbg(&v, pixels, grid_h, grid_w, out, last);
    if (tokens <= 0) { fprintf(stderr, "la torre ha rifiutato la griglia\n"); return 1; }

    printf("torre vision Qwen3.8: %d patch -> %d token\n", patches, tokens);
    int failures = 0;
    if ((int64_t)tokens * v.out_hidden != nout) {
        printf("  FAIL forma: %d x %d, il riferimento dice %lld valori\n",
               tokens, v.out_hidden, (long long)nout);
        failures++;
    } else {
        /* 8e-4 non e' una tolleranza scelta per far passare il test: e' MISURATA.
         * Il riferimento in float32 confrontato con se stesso in float64 differisce
         * di 1.83e-4 su queste attivazioni, che arrivano a 154. Il nostro scarto e'
         * dello stesso ordine, quindi e' l'aritmetica di chi ci confrontiamo, non
         * un difetto. Un errore vero -- ordine delle patch, teste, residui -- si
         * presenta a 1e-3 o piu': la gelu sbagliata nel merger, che era un difetto
         * VERO trovato qui, dava 4.6e-3. La soglia sta in mezzo apposta. */
        failures += compare("pooler", out, want_out, nout, 8e-4f);
    }
    if ((int64_t)patches * v.hidden == nlast)
        failures += compare("last_hidden", last, want_last, nlast, 8e-4f);

    /* Il merger da solo: se alimentato con l'uscita del RIFERIMENTO produce il
     * pooler del riferimento, allora il merger e' corretto e lo scarto sul
     * pooler e' quello dei blocchi amplificato dalla sua LayerNorm -- non un
     * difetto suo. Senza questa distinzione i due casi sono indistinguibili. */
    {
        int wide2 = v.hidden * v.merge * v.merge, tok2 = patches / (v.merge * v.merge);
        float *normed = (float *)calloc((size_t)patches * v.hidden, sizeof(float));
        float *hid = (float *)calloc((size_t)tok2 * wide2, sizeof(float));
        float *got = (float *)calloc((size_t)tok2 * v.out_hidden, sizeof(float));
        q38v_layernorm(normed, want_last, &v.merger_norm, patches, v.hidden, v.eps);
        q38v_linear(hid, normed, &v.merger_fc1, tok2);
        for (int i = 0; i < tok2 * wide2; i++) hid[i] = q38v_gelu_exact(hid[i]);
        q38v_linear(got, hid, &v.merger_fc2, tok2);
        failures += compare("merger da solo", got, want_out, nout, 8e-4f);
        free(normed); free(hid); free(got);
    }

    /* Una griglia che il merge non chiude deve essere rifiutata, non arrotondata. */
    if (q38_vision_forward(&v, pixels, 3, 3, out) != -1) {
        printf("  FAIL una griglia 3x3 con merge 2 e' stata accettata\n");
        failures++;
    } else {
        printf("  ok   griglia non divisibile per il merge rifiutata\n");
    }

    printf("\n%s\n", failures ? "TEST FAIL" : "la torre combacia con l'oracolo upstream");
    return failures ? 1 : 0;
}

static int open_engine(const char *family, const char *model_dir,
                       uint32_t begin, uint32_t end, uint32_t context,
                       ColiSegmentEngine **engine,
                       ColiSegmentCapabilities *capabilities,
                       char *error, size_t error_size) {
    return open_engine_limited(family,model_dir,begin,end,context,0,engine,
                               capabilities,error,error_size);
}

static int create_session_limited(ColiSegmentEngine *engine,uint32_t context,
                                  uint64_t memory_limit,
                                  ColiSegmentSession **session,
