static void write_snap(const char *dir) {
    char path[512];
    snprintf(path, sizeof(path), "%s/model.safetensors", dir);
    const char *hdr =
        "{\"f8\":{\"dtype\":\"F8_E4M3\",\"shape\":[3,5],\"data_offsets\":[0,15]},"
        "\"ids\":{\"dtype\":\"I64\",\"shape\":[4],\"data_offsets\":[15,47]},"
        "\"f32\":{\"dtype\":\"F32\",\"shape\":[1],\"data_offsets\":[47,51]}}";
    uint64_t hlen = strlen(hdr);
    unsigned char bytes[51];
    for (int i = 0; i < (int)sizeof(bytes); i++) bytes[i] = (unsigned char)(0xa0 + i);
    FILE *f = fopen(path, "wb");
    if (!f) { perror(path); exit(1); }
    fwrite(&hlen, 8, 1, f);
    fwrite(hdr, 1, hlen, f);
    fwrite(bytes, 1, sizeof(bytes), f);
    fclose(f);
}

static int expect_failure(shards *S, const char *name, int64_t off, int64_t nbytes,
                          void *out, int64_t cap, const char *needle) {
    int pipefd[2]; CHECK(pipe(pipefd) == 0);
    pid_t pid = fork(); CHECK(pid >= 0);
    if (pid == 0) {
        dup2(pipefd[1], 2); close(pipefd[0]); close(pipefd[1]);
        st_read_slice_raw_cap(S, name, off, nbytes, out, cap, 0);
        _exit(42);
    }
    close(pipefd[1]);
    char err[512] = {0};
    ssize_t n = read(pipefd[0], err, sizeof(err) - 1); (void)n;
    close(pipefd[0]);
    int status = 0; waitpid(pid, &status, 0);
    CHECK(WIFEXITED(status) && WEXITSTATUS(status) == 1);
    CHECK(strstr(err, needle) != NULL);
    return 0;
}

int main(void) {
    char dir[] = "test_st_slice_XXXXXX";
    CHECK(mkdtemp(dir) != NULL);
    write_snap(dir);

    shards S; st_init(&S, dir);
    CHECK(st_numel(&S, "f8") == 15);
    CHECK(st_nbytes(&S, "f8") == 15);
    CHECK(st_numel(&S, "ids") == 4);
    CHECK(st_nbytes(&S, "ids") == 32);

    unsigned char f8[5] = {0};
    st_read_slice_raw_cap(&S, "f8", 7, 5, f8, sizeof(f8), 0);
    for (int i = 0; i < 5; i++) CHECK(f8[i] == (unsigned char)(0xa0 + 7 + i));

    uint64_t ids[2] = {0};
    st_read_slice_raw_cap(&S, "ids", 8, sizeof(ids), ids, sizeof(ids), 0);
    unsigned char *id_bytes = (unsigned char *)ids;
    for (int i = 0; i < (int)sizeof(ids); i++)
        CHECK(id_bytes[i] == (unsigned char)(0xa0 + 15 + 8 + i));

    /* Empty slices are valid, but must leave the destination untouched. */
    unsigned char sentinel = 0x5a;
    st_read_slice_raw_cap(&S, "f8", 15, 0, &sentinel, 0, 1);
    CHECK(sentinel == 0x5a);
    st_read_slice_f32(&S, "f32", 1, 0, NULL, 1);

#ifndef _WIN32
    unsigned char out[16] = {0};
    CHECK(expect_failure(&S, "f8", -1, 1, out, sizeof(out), "negative") == 0);
    CHECK(expect_failure(&S, "f8", 0, -1, out, sizeof(out), "negative") == 0);
    CHECK(expect_failure(&S, "f8", 0, 16, out, sizeof(out), "out of tensor byte bounds") == 0);
    CHECK(expect_failure(&S, "f8", 0, 8, out, 7, "destination holds") == 0);
    CHECK(expect_failure(&S, "f8", 0, 1, NULL, 1, "NULL destination") == 0);
    CHECK(expect_failure(&S, "f8", 15, 1, out, sizeof(out), "out of tensor byte bounds") == 0);

    /* Exercise the absolute-offset overflow guard independently of the tensor
     * range checks.  This mutates only the child-inherited index. */
    st_tensor *f8_tensor = st_find(&S, "f8");
    CHECK(f8_tensor != NULL);
    int64_t saved_off = f8_tensor->off;
    int64_t saved_nbytes = f8_tensor->nbytes;
    f8_tensor->off = INT64_MAX;
    f8_tensor->nbytes = INT64_MAX;
    CHECK(expect_failure(&S, "f8", 1, 1, out, sizeof(out), "overflows int64") == 0);
    f8_tensor->off = saved_off;
    f8_tensor->nbytes = saved_nbytes;
#else
    printf("test_st_slice: rejection subtests skipped on Windows\n");
#endif

    st_destroy(&S);
    char path[512];
    snprintf(path, sizeof(path), "%s/model.safetensors", dir);
    CHECK(remove(path) == 0);
#ifdef _WIN32
    CHECK(_rmdir(dir) == 0);
#else
    CHECK(rmdir(dir) == 0);
#endif
    printf("test_st_slice: raw F8/I64 slices and bounds: ok\n");
    return 0;
}

static void set_weights(const int *wt, int n){
    int acc=0, tot=0;
    for(int i=0;i<n;i++) tot+=wt[i];
    for(int i=0;i<n;i++){
        acc += (int)((256.0*wt[i])/tot + 0.5);
        if(acc>256) acc=256;
        g_mir_cut[i]=acc;
    }
    g_mir_cut[n-1]=256;                  /* last replica absorbs rounding */
    g_mir_nrep=n;
}

int main(void){
    const int64_t LEN = 19*1024*1024;    /* a GLM-5.2 int4 expert */
    int64_t off[MIR_REPS], sz[MIR_REPS];
    char d[192];

    /* 1. THE LOAD-BEARING ONE: a slow leg must get a SMALL share.
     *    This is the whole bug. Equal thirds of 19 MB is 6.33 MB each; the
     *    measured 10x-slower drive must come out far below that. */
    {
        int wt[3] = {51, 45, 4};         /* 5.69 / 5.03 / 0.44 GB/s */
        int srep[3] = {0,1,2};
        set_weights(wt, 3);
        mir_stripe_plan(LEN, 3, srep, 0, off, sz);
        int64_t equal = LEN/3;
        snprintf(d,sizeof d,"slow leg %lld B vs equal-split %lld B",
                 (long long)sz[2], (long long)equal);
        /* Both bounds are deliberately far from `equal`. A `> equal` check on
         * the fast leg PASSES on the old equal-split code, by 2,731 bytes of
         * 4K rounding - verified by reverting the plan and watching it stay
         * green while its sibling went red. An assertion that survives the bug
         * is not testing for the bug. */
        ck(sz[2] < equal/2,       "a 4 pct leg gets under half an equal third", d);
        ck(sz[0] > equal*13/10,   "a 51 pct leg gets over 1.3x an equal third", d);
    }

    /* 2. Sizes must sum to exactly len and offsets must be contiguous.
     *    A gap or an overlap here is silent data corruption, not a slow read. */
    {
        int wt[3] = {51, 45, 4};
        int srep[3] = {0,1,2};
        set_weights(wt, 3);
        for(int rep=0; rep<3; rep++){
            mir_stripe_plan(LEN, 3, srep, rep, off, sz);
            int64_t total=0; int contiguous=1;
            for(int i=0;i<3;i++){
                if(off[i]!=total) contiguous=0;
                total+=sz[i];
            }
            snprintf(d,sizeof d,"rep=%d sum=%lld want=%lld",rep,(long long)total,(long long)LEN);
            ck(total==LEN,   "stripe sizes sum to exactly len", d);
            ck(contiguous,   "stripe offsets are contiguous from 0", d);
        }
    }

    /* 3. Equal weights must still produce an equal split. Without this the
     *    suite would pass on a plan that always favours replica 0, and every
     *    matched-drive user would silently get a worse split than before. */
    {
        int wt[2] = {50, 50};
        int srep[2] = {0,1};
        set_weights(wt, 2);
        mir_stripe_plan(LEN, 2, srep, 0, off, sz);
        int64_t diff = sz[0]>sz[1] ? sz[0]-sz[1] : sz[1]-sz[0];
        snprintf(d,sizeof d,"%lld vs %lld, diff %lld B",
                 (long long)sz[0],(long long)sz[1],(long long)diff);
        ck(diff <= 8192, "equal weights still split ~evenly", d);
    }

    /* 4. Chunk 0 lands on the ROUTED replica. The caller relies on this so the
     *    hash still spreads first-chunk load; losing it would silently point
     *    every first chunk at replica 0. */
    {
        int wt[3] = {40, 30, 30};
        int srep[3] = {0,1,2};
        set_weights(wt, 3);
        int64_t s0[MIR_REPS], o0[MIR_REPS];
        mir_stripe_plan(LEN, 3, srep, 0, o0, s0);
        mir_stripe_plan(LEN, 3, srep, 1, off, sz);
        snprintf(d,sizeof d,"rep0 first=%lld  rep1 first=%lld",
                 (long long)s0[0],(long long)sz[0]);
        ck(s0[0] != sz[0], "rotating rep changes which weight chunk 0 takes", d);
    }

    /* 5. No leg may exceed len, and none may be negative. Guards the
     *    remainder branch, which is the one place a bad weight could produce
     *    a wild size. */
    {
        int wt[3] = {1, 1, 254};         /* deliberately lopsided */
        int srep[3] = {0,1,2};
        set_weights(wt, 3);
        mir_stripe_plan(LEN, 3, srep, 0, off, sz);
        int sane=1;
        for(int i=0;i<3;i++) if(sz[i]<0 || sz[i]>LEN) sane=0;
        snprintf(d,sizeof d,"%lld / %lld / %lld",
                 (long long)sz[0],(long long)sz[1],(long long)sz[2]);
        ck(sane, "no stripe is negative or larger than len", d);
    }

    printf(failures ? "\nmirror stripe split: %d FAILURE(S)\n"
                    : "\nmirror stripe split: ok\n", failures);
    return failures ? 1 : 0;
}

static void mir_stripe_plan(int64_t len, int nsf, const int *srep, int rep,
                            int64_t *off, int64_t *sz){
    int64_t wsum=0, w[MIR_REPS];
    for(int i=0;i<nsf;i++){
        int r=srep[i], lo=r?g_mir_cut[r-1]:0;
        w[i]=g_mir_cut[r]-lo;
        if(w[i]<1) w[i]=1;                    /* a zero share would strand bytes */
        wsum+=w[i];
    }
    int64_t acc=0;
    for(int i=0;i<nsf;i++){
        int k=(rep+i)%nsf;                    /* chunk 0 on the routed replica */
        int64_t want = i==nsf-1 ? len-acc     /* last leg absorbs the remainder */
                                : ((len*w[k]/wsum) + 4095) & ~4095LL;
        if(want<0) want=0;
        if(acc+want>len) want=len-acc;
        off[i]=acc; sz[i]=want; acc+=want;
    }
}

void lv_theme_set_user_data(lv_theme_t * theme, void * user_data)
{
    if(theme == NULL) return;
    theme->user_data = user_data;
}

void * lv_theme_get_user_data(const lv_theme_t * theme)
{
    if(theme == NULL) return NULL;
    return theme->user_data;
}

void test_theme_user_data(void)
{
    lv_theme_t theme;
    lv_memzero(&theme, sizeof(theme));
    int dummy = 42;

    // NULL user_data must be accepted
    lv_theme_set_user_data(&theme, NULL);
    TEST_ASSERT_EQUAL_PTR(NULL, theme.user_data);

    // NULL theme must not crash
    lv_theme_set_user_data(NULL, &dummy);

    // A non NULL value can be retrieved
    lv_theme_set_user_data(&theme, &dummy);
    TEST_ASSERT_EQUAL_PTR(&dummy, lv_theme_get_user_data(&theme));
}

void test_scale_section_pad_radial(void)
{
    lv_obj_t * scale = lv_scale_create(lv_screen_active());
    lv_obj_set_size(scale, 200, 200);
    lv_scale_set_mode(scale, LV_SCALE_MODE_ROUND_INNER);
    lv_obj_center(scale);

    lv_scale_set_label_show(scale, false);
    lv_scale_set_total_tick_count(scale, 11);
    lv_scale_set_major_tick_every(scale, 5);
    lv_scale_set_range(scale, 0, 100);

    /* Make the main arc visible so the section arcs can be visually distinguished. */
    static lv_style_t main_arc_style;
    lv_style_init(&main_arc_style);
    lv_style_set_arc_color(&main_arc_style, lv_palette_main(LV_PALETTE_GREY));
    lv_style_set_arc_width(&main_arc_style, 2U);
    lv_obj_add_style(scale, &main_arc_style, LV_PART_MAIN);

    /* Section 1: no radial pad - the arc should sit on the default scale radius. */
    static lv_style_t section_no_pad_style;
    lv_style_init(&section_no_pad_style);
    lv_style_set_arc_color(&section_no_pad_style, lv_palette_main(LV_PALETTE_BLUE));
    lv_style_set_arc_width(&section_no_pad_style, 4U);

    lv_scale_section_t * section_no_pad = lv_scale_add_section(scale);
    lv_scale_set_section_range(scale, section_no_pad, 0, 50);
    lv_scale_set_section_style_main(scale, section_no_pad, &section_no_pad_style);

    /* Section 2: radial pad of 20 - the section arc must be drawn 20 px inside. */
    static lv_style_t section_padded_style;
    lv_style_init(&section_padded_style);
    lv_style_set_arc_color(&section_padded_style, lv_palette_main(LV_PALETTE_RED));
    lv_style_set_arc_width(&section_padded_style, 4U);
    lv_style_set_pad_radial(&section_padded_style, 20);

    lv_scale_section_t * section_padded = lv_scale_add_section(scale);
    lv_scale_set_section_range(scale, section_padded, 50, 100);
    lv_scale_set_section_style_main(scale, section_padded, &section_padded_style);

    TEST_ASSERT_EQUAL_SCREENSHOT("widgets/scale_10.png");
}

bool
ts_debug_point_is_enabled(const char *name)
{
	DebugPoint point;
	LockAcquireResult lock_acquire_result;

	debug_point_init(&point, name);

	lock_acquire_result = LockAcquire(&point.tag, ShareLock, true, true);
	switch (lock_acquire_result)
	{
		case LOCKACQUIRE_OK:
			/* ShareLock granted means no other session holds ExclusiveLock; the
			 * point is enabled only if this session itself enabled it. */
			LockRelease(&point.tag, ShareLock, true);
			return LockHeldByMeCompat(&point.tag, ExclusiveLock, false);
		case LOCKACQUIRE_ALREADY_HELD:
		case LOCKACQUIRE_ALREADY_CLEAR:
			LockRelease(&point.tag, ShareLock, true);
			return false;
		case LOCKACQUIRE_NOT_AVAIL:
			/* Another session holds the ExclusiveLock: the point is enabled. */
			return true;
	}

	pg_unreachable();
	return false;
}

else if (etup->level > highestLevel)
