    NfcApp* instance = context;

    widget_reset(instance->widget);
}

void nfc_scene_key_dict_add_on_enter(void* context) {
    NfcApp* instance = context;
    const NfcKeyDict* dict = nfc_key_dict(instance->key_dict_type);

    // Setup view
    ByteInput* byte_input = instance->byte_input;
    byte_input_set_header_text(byte_input, "Enter the key in hex");
    byte_input_set_result_callback(
        byte_input,
        nfc_protocol_support_common_byte_input_done_callback,
        NULL,
        instance,
        instance->byte_input_store,
        dict->key_size);
    view_dispatcher_switch_to_view(instance->view_dispatcher, NfcViewByteInput);
}

bool nfc_scene_key_dict_add_on_event(void* context, SceneManagerEvent event) {
    NfcApp* instance = context;
    bool consumed = false;

    if(event.type == SceneManagerEventTypeCustom) {
        if(event.event == NfcCustomEventByteInputDone) {
            const NfcKeyDict* dict = nfc_key_dict(instance->key_dict_type);

            KeysDict* user_dict =
                keys_dict_alloc(dict->user_path, KeysDictModeOpenAlways, dict->key_size);

            if(keys_dict_is_key_present(user_dict, instance->byte_input_store, dict->key_size)) {
                scene_manager_next_scene(instance->scene_manager, NfcSceneKeyDictWarnDuplicate);
            } else if(keys_dict_add_key(user_dict, instance->byte_input_store, dict->key_size)) {
                scene_manager_next_scene(instance->scene_manager, NfcSceneSaveSuccess);
                dolphin_deed(DolphinDeedNfcKeyAdd);
            } else {
                // Full SD, missing /ext/nfc/assets, read-only card: the user would otherwise just
                // land back on an unchanged counter.
                FURI_LOG_E(TAG, "Failed to add a key to %s", dict->user_path);
                notification_message(instance->notifications, &sequence_error);
                scene_manager_previous_scene(instance->scene_manager);
            }

            keys_dict_free(user_dict);
            consumed = true;
        }
    }

    return consumed;
}

void nfc_scene_key_dict_add_on_exit(void* context) {
    NfcApp* instance = context;

    // Clear view
    byte_input_set_result_callback(instance->byte_input, NULL, NULL, NULL, NULL, 0);
    byte_input_set_header_text(instance->byte_input, "");
}

static bool
    nfc_scene_key_dict_delete_load_key(const NfcKeyDict* dict, uint32_t key_index, uint8_t* key) {
    KeysDict* user_dict = keys_dict_alloc(dict->user_path, KeysDictModeOpenAlways, dict->key_size);
    bool loaded = key_index < keys_dict_get_total_keys(user_dict);
    for(size_t i = 0; loaded && i < (key_index + 1); i++) {
        loaded = keys_dict_get_next_key(user_dict, key, dict->key_size);
    }
    keys_dict_free(user_dict);
    return loaded;
}

void nfc_scene_key_dict_delete_on_enter(void* context) {
    NfcApp* instance = context;
    const NfcKeyDict* dict = nfc_key_dict(instance->key_dict_type);

    uint32_t key_index =
        scene_manager_get_scene_state(instance->scene_manager, NfcSceneKeyDictDelete);

    uint8_t key[NFC_BYTE_INPUT_STORE_SIZE];
    const bool key_loaded = nfc_scene_key_dict_delete_load_key(dict, key_index, key);

    widget_add_string_element(
        instance->widget,
        64,
        0,
        AlignCenter,
        AlignTop,
        FontPrimary,
        key_loaded ? "Delete this key?" : "Key Not Found");
    widget_add_button_element(
        instance->widget,
        GuiButtonTypeLeft,
        key_loaded ? "Cancel" : "Back",
        nfc_protocol_support_common_widget_callback,
        instance);

    if(key_loaded) {
        // Only offer Delete for a key we could read back; otherwise the dialog asks the user to
        // confirm deleting a blank line.
        widget_add_button_element(
            instance->widget,
            GuiButtonTypeRight,
            "Delete",
            nfc_protocol_support_common_widget_callback,
            instance);

        FuriString* key_str = furi_string_alloc();
        for(size_t i = 0; i < dict->key_size; i++) {
            furi_string_cat_printf(key_str, "%02X", key[i]);
        }
        widget_add_string_element(
            instance->widget,
            64,
            32,
            AlignCenter,
            AlignCenter,
            FontSecondary,
            furi_string_get_cstr(key_str));
        furi_string_free(key_str);
    } else {
        FURI_LOG_W(TAG, "Key %lu is gone from %s", key_index, dict->user_path);
    }

    view_dispatcher_switch_to_view(instance->view_dispatcher, NfcViewWidget);
}

bool nfc_scene_key_dict_delete_on_event(void* context, SceneManagerEvent event) {
    NfcApp* instance = context;
    bool consumed = false;

    if(event.type == SceneManagerEventTypeCustom) {
        if(event.event == GuiButtonTypeRight) {
            const NfcKeyDict* dict = nfc_key_dict(instance->key_dict_type);
            uint32_t key_index =
                scene_manager_get_scene_state(instance->scene_manager, NfcSceneKeyDictDelete);
            uint8_t key[NFC_BYTE_INPUT_STORE_SIZE];
            bool deleted = false;
            if(nfc_scene_key_dict_delete_load_key(dict, key_index, key)) {
                KeysDict* user_dict =
                    keys_dict_alloc(dict->user_path, KeysDictModeOpenAlways, dict->key_size);
                deleted = keys_dict_delete_key(user_dict, key, dict->key_size);
                keys_dict_free(user_dict);
            }
            if(deleted) {
                scene_manager_next_scene(instance->scene_manager, NfcSceneDeleteSuccess);
            } else {
                FURI_LOG_E(TAG, "Failed to delete key %lu from %s", key_index, dict->user_path);
                notification_message(instance->notifications, &sequence_error);
                scene_manager_previous_scene(instance->scene_manager);
            }
        } else if(event.event == GuiButtonTypeLeft) {
            scene_manager_previous_scene(instance->scene_manager);
        }
        consumed = true;
    }

    return consumed;
}

void nfc_scene_key_dict_delete_on_exit(void* context) {
    NfcApp* instance = context;

    widget_reset(instance->widget);
}

void nfc_scene_key_dict_list_on_enter(void* context) {
    NfcApp* instance = context;
    const NfcKeyDict* dict = nfc_key_dict(instance->key_dict_type);

    KeysDict* user_dict = keys_dict_alloc(dict->user_path, KeysDictModeOpenAlways, dict->key_size);

    submenu_set_header(instance->submenu, "Select key to delete:");
    FuriString* temp_str = furi_string_alloc();

    const size_t keys_num =
        MIN((size_t)NFC_SCENE_KEY_DICT_LIST_MAX, keys_dict_get_total_keys(user_dict));
    uint8_t key[NFC_BYTE_INPUT_STORE_SIZE];

    for(size_t i = 0; i < keys_num; i++) {
        if(!keys_dict_get_next_key(user_dict, key, dict->key_size)) {
            // The count said there were more. Short list rather than no list, but say why.
            FURI_LOG_W(TAG, "Dictionary %s ended early at key %u", dict->user_path, (unsigned)i);
            break;
        }
        furi_string_reset(temp_str);
        for(size_t j = 0; j < dict->key_size; j++) {
            furi_string_cat_printf(temp_str, "%02X", key[j]);
        }
        submenu_add_item(
            instance->submenu,
            furi_string_get_cstr(temp_str),
            i,
            nfc_protocol_support_common_submenu_callback,
            instance);
    }

    furi_string_free(temp_str);
    keys_dict_free(user_dict);

    view_dispatcher_switch_to_view(instance->view_dispatcher, NfcViewMenu);
}

bool nfc_scene_key_dict_list_on_event(void* context, SceneManagerEvent event) {
    NfcApp* instance = context;

    bool consumed = false;
    if(event.type == SceneManagerEventTypeCustom) {
        scene_manager_set_scene_state(instance->scene_manager, NfcSceneKeyDictDelete, event.event);
        scene_manager_next_scene(instance->scene_manager, NfcSceneKeyDictDelete);
        consumed = true;
    }

    return consumed;
}

void nfc_scene_key_dict_list_on_exit(void* context) {
    NfcApp* instance = context;

    submenu_reset(instance->submenu);
}

static void nfc_generate_mf_ultralight_c(NfcDevice* nfc_device) {
    MfUltralightData* mfu_data = mf_ultralight_alloc();
    nfc_generate_mf_ul_common(mfu_data);

    mfu_data->type = MfUltralightTypeMfulC;
    mfu_data->pages_total = 48; // MF0ICU2: 48 pages, 0x00-0x2F
    mfu_data->pages_read = 48;
    mfu_data->page[2].data[1] = 0x48; // Internal byte (default)

    // AUTH0 (page 0x2A byte 0) = 0x30 protects nothing, so the card reads without authentication; if
    // the user later lowers it, the default 3DES key at pages 0x2C-0x2F (used as-is by the listener
    // via mf_ultralight_3des_get_key) is a known dictionary entry, so it stays unlockable. UL-C has
    // no GetVersion and no originality signature, so version/signature stay zeroed.
    mfu_data->page[0x2A].data[0] = 0x30;
    memcpy(
        &mfu_data->page[0x2C], mf_ultralight_c_default_key, sizeof(mf_ultralight_c_default_key));

    nfc_device_set_data(nfc_device, NfcProtocolMfUltralight, mfu_data);
    mf_ultralight_free(mfu_data);
}

static void nfc_generate_mf_ultralight_aes(NfcDevice* nfc_device) {
    MfUltralightData* mfu_data = mf_ultralight_alloc();
    nfc_generate_mf_ul_common(mfu_data);

    mfu_data->type = MfUltralightTypeUltralightAES;
    mfu_data->pages_total = 60; // MF0AES20: 60 pages, 0x00-0x3B
    mfu_data->pages_read = 60;
    memcpy(&mfu_data->version, version_bytes_mf0aes20, sizeof(MfUltralightVersion));
    mfu_data->page[2].data[1] = 0x48; // Internal byte (MF0AES20 default)

    // Factory-default config (matches a blank MF0AES20): AUTH0 protects nothing (open); and, left at
    // their all-zero defaults, AUTH_LIM unlimited, Random ID / secure messaging off, key locks off,
    // and the DataProtKey (0x30-0x33) / UIDRetrKey (0x34-0x37).
    mfu_data->page[MF_ULTRALIGHT_AES_CFG_PAGE].data[3] = 0x3C; // AUTH0 > 0x3B => disabled
    mfu_data->page[MF_ULTRALIGHT_AES_ACCESS_PAGE].data[0] = MF_ULTRALIGHT_AES_ACCESS_PROT |
                                                            MF_ULTRALIGHT_AES_ACCESS_CNT_INC_EN |
                                                            MF_ULTRALIGHT_AES_ACCESS_CNT_RD_EN;
    mfu_data->page[MF_ULTRALIGHT_AES_ACCESS_PAGE].data[1] = 0x05; // VCTID

    // Placeholder originality signature so the emulated card answers READ_SIG; random, so it won't
    // verify against NXP's key - expected for a fabricated card.
    furi_hal_random_fill_buf(mfu_data->aes_signature, MF_ULTRALIGHT_AES_SIGNATURE_SIZE);
    mfu_data->aes_signature_present = true;

    nfc_device_set_data(nfc_device, NfcProtocolMfUltralight, mfu_data);
    mf_ultralight_free(mfu_data);
}

bool lfrfid_delete_key_file(LfRfid* app, const FuriString* path) {
    furi_assert(app);
    furi_assert(path);

    return storage_simply_remove(app->storage, furi_string_get_cstr(path));
}

static void nfc_scene_mf_classic_dict_attack_start_poller(NfcApp* instance) {
    // Every dictionary phase runs on its own poller, so the latch has to be cleared per phase.
    instance->nfc_dict_context.poller_has_card_data = false;
    instance->poller = nfc_poller_alloc(instance->nfc, NfcProtocolMfClassic);
    nfc_poller_start(instance->poller, nfc_dict_attack_worker_callback, instance);
}

static void
    nfc_scene_mf_classic_update_initial_merge(MfClassicData* base, const MfClassicData* fresh) {
    for(uint16_t block_num = 0; block_num < MF_CLASSIC_TOTAL_BLOCKS_MAX; block_num++) {
        if(!mf_classic_is_block_read(fresh, block_num)) continue;
        MfClassicBlock block = fresh->block[block_num]; // set_block_read() wants it mutable
        mf_classic_set_block_read(base, block_num, &block);
    }

    const MfClassicKeyType key_types[] = {MfClassicKeyTypeA, MfClassicKeyTypeB};
    for(uint8_t sector_num = 0; sector_num < MF_CLASSIC_TOTAL_SECTORS_MAX; sector_num++) {
        const MfClassicSectorTrailer* sec_tr =
            mf_classic_get_sector_trailer_by_sector(fresh, sector_num);
        for(size_t i = 0; i < COUNT_OF(key_types); i++) {
            if(!mf_classic_is_key_found(fresh, sector_num, key_types[i])) continue;
            const MfClassicKey* key = (key_types[i] == MfClassicKeyTypeA) ? &sec_tr->key_a :
                                                                            &sec_tr->key_b;
            mf_classic_set_key_found(
                base,
                sector_num,
                key_types[i],
                bit_lib_bytes_to_num_be(key->data, sizeof(MfClassicKey)));
        }
    }
}

static void nfc_scene_mf_classic_update_initial_log_gaps(
    const MfClassicData* dump,
    const MfClassicData* fresh) {
    uint8_t sectors_had = 0, keys_had = 0, sectors_got = 0, keys_got = 0;
    mf_classic_get_read_sectors_and_keys(dump, &sectors_had, &keys_had);
    mf_classic_get_read_sectors_and_keys(fresh, &sectors_got, &keys_got);
    if(sectors_got < sectors_had || keys_got < keys_had) {
        FURI_LOG_W(
            TAG,
            "Partial re-read: %u/%u sectors, %u/%u keys; keeping the rest of the dump",
            sectors_got,
            sectors_had,
            keys_got,
            keys_had);
    }
    if(dump->type != fresh->type) {
        FURI_LOG_W(
            TAG,
            "Type mismatch: dump %s, card %s; keeping the dump's",
            mf_classic_get_device_name(dump, NfcDeviceNameTypeShort),
            mf_classic_get_device_name(fresh, NfcDeviceNameTypeShort));
    }
}

static inline int16_t spin_clamp(int32_t value) {
    if(value > SPIN_MAX) return SPIN_MAX;
    if(value < -SPIN_MAX) return -SPIN_MAX;
    return (int16_t)value;
}

static void cube_animate(CubeState* state) {
    state->speed[0] += state->speed[2] >> TUMBLE_SHIFT;
    state->speed[2] -= state->speed[0] >> TUMBLE_SHIFT;
    state->speed[1] += state->speed[0] >> (TUMBLE_SHIFT + 1);
    state->speed[0] -= state->speed[1] >> (TUMBLE_SHIFT + 1);

    for(uint32_t i = 0; i < 3; i++) {
        state->speed[i] -= state->speed[i] >> SPIN_DAMPING;
        state->phase[i] += state->speed[i];
    }
}

static inline void fb_put_pixel(uint8_t* fb, int32_t x, int32_t y) {
    if((uint32_t)x < SCREEN_WIDTH && (uint32_t)y < SCREEN_HEIGHT) {
        fb[((y >> 3) * SCREEN_WIDTH) + x] |= 1 << (y & 7);
    }
}

static void fb_draw_line(uint8_t* fb, int32_t x0, int32_t y0, int32_t x1, int32_t y1) {
    int32_t dx = abs(x1 - x0);
    int32_t dy = -abs(y1 - y0);
    int32_t step_x = x0 < x1 ? 1 : -1;
    int32_t step_y = y0 < y1 ? 1 : -1;
    int32_t err = dx + dy;

    for(;;) {
        fb_put_pixel(fb, x0, y0);
        if(x0 == x1 && y0 == y1) break;
        int32_t e2 = 2 * err;
        if(e2 >= dy) {
            err += dy;
            x0 += step_x;
        }
        if(e2 <= dx) {
            err += dx;
            y0 += step_y;
        }
    }
}

static void cube_draw_callback(Canvas* canvas, void* context) {
    CubeState* state = context;
    cube_animate(state);

    canvas_draw_str(canvas, 2, 9, "Angry pixels");
    canvas_draw_str(canvas, 92, 9, "run!");
    canvas_draw_str(canvas, 4, 38, "bonk!");
    canvas_draw_str(canvas, 99, 38, "ouch!");
    canvas_draw_str(canvas, 20, 62, "the floor is lava");

    int32_t sin_x = lut_sin(state->phase[0]), cos_x = lut_cos(state->phase[0]);
    int32_t sin_y = lut_sin(state->phase[1]), cos_y = lut_cos(state->phase[1]);
    int32_t sin_z = lut_sin(state->phase[2]), cos_z = lut_cos(state->phase[2]);

    int32_t rx[8];
    int32_t ry[8];
    int32_t rz[8];
    int32_t dx[8];
    int32_t dy[8];

    for(uint32_t i = 0; i < 8; i++) {
        int32_t x = cube_vertex[i][0] * FIXED_ONE;
        int32_t y = cube_vertex[i][1] * FIXED_ONE;
        int32_t z = cube_vertex[i][2] * FIXED_ONE;

        int32_t t = (y * cos_x - z * sin_x) >> FIXED_SHIFT;
        z = (y * sin_x + z * cos_x) >> FIXED_SHIFT;
        y = t;

        t = (x * cos_y + z * sin_y) >> FIXED_SHIFT;
        z = (z * cos_y - x * sin_y) >> FIXED_SHIFT;
        x = t;

        t = (x * cos_z - y * sin_z) >> FIXED_SHIFT;
        y = (x * sin_z + y * cos_z) >> FIXED_SHIFT;
        x = t;

        rx[i] = x;
        ry[i] = y;
        rz[i] = z;

        int32_t depth = z + CAMERA_DISTANCE;
        dx[i] = (x * FOCAL_LENGTH) / depth;
        dy[i] = (y * FOCAL_LENGTH) / depth;
    }

    /* canvas_get_buffer() returns the canvas backing framebuffer directly.
     * At this point it already holds the glyphs rasterized by
     * canvas_draw_str() above: the same buffer is first read back for
     * pixel-exact collision, then written to draw the cube in place. */
    uint8_t* fb = canvas_get_buffer(canvas);

    int32_t cur_x = state->pos_x >> POS_SHIFT;
    int32_t cur_y = state->pos_y >> POS_SHIFT;
    int32_t next_x = (state->pos_x + state->vel_x) >> POS_SHIFT;
    int32_t next_y = (state->pos_y + state->vel_y) >> POS_SHIFT;

    /* Read pass: probe the framebuffer at every projected cube vertex,
     * separately for the advanced X and the advanced Y position, to find out
     * along which axis the cube would run into already-drawn pixels. */
    int32_t torque[3] = {0, 0, 0};
    bool hit_x = false;
    bool hit_y = false;
    for(uint32_t i = 0; i < 8; i++) {
        if(fb_hit(fb, next_x + dx[i], cur_y + dy[i])) {
            hit_x = true;
            int32_t push = (state->vel_x > 0) ? -1 : 1;
            torque[1] += rz[i] * push;
            torque[2] -= ry[i] * push;
        }
        if(fb_hit(fb, cur_x + dx[i], next_y + dy[i])) {
            hit_y = true;
            int32_t push = (state->vel_y > 0) ? -1 : 1;
            torque[0] -= rz[i] * push;
            torque[2] += rx[i] * push;
        }
    }
    for(uint32_t i = 0; i < 3; i++) {
        state->speed[i] =
            spin_clamp(state->speed[i] + ((torque[i] * inv_inertia[i]) >> TORQUE_SHIFT));
    }
    if(hit_x) state->vel_x = -state->vel_x;
    if(hit_y) state->vel_y = -state->vel_y;
    state->pos_x += state->vel_x;
    state->pos_y += state->vel_y;

    int32_t center_x = state->pos_x >> POS_SHIFT;
    int32_t center_y = state->pos_y >> POS_SHIFT;

    /* Write pass: rasterize the cube edges straight into the framebuffer,
     * on top of everything the canvas API drew this frame. */
    for(uint32_t i = 0; i < 12; i++) {
        fb_draw_line(
            fb,
            center_x + dx[cube_edge[i][0]],
            center_y + dy[cube_edge[i][0]],
            center_x + dx[cube_edge[i][1]],
            center_y + dy[cube_edge[i][1]]);
    }
}

int32_t example_canvas_buffer_app(void* arg) {
    UNUSED(arg);

    for(uint32_t i = 0; i < SIN_LUT_SIZE; i++) {
        sin_lut[i] = (int16_t)lroundf(sinf(i * (6.2831853f / SIN_LUT_SIZE)) * FIXED_ONE);
    }

    CubeState state = {0};
    state.speed[0] = 240;
    state.speed[1] = -180;
    state.speed[2] = 130;
    state.pos_x = (SCREEN_WIDTH / 2) << POS_SHIFT;
    state.pos_y = (SCREEN_HEIGHT / 2) << POS_SHIFT;
    state.vel_x = (furi_hal_random_get() & 1) ? MOVE_SPEED_X : -MOVE_SPEED_X;
    state.vel_y = (furi_hal_random_get() & 1) ? MOVE_SPEED_Y : -MOVE_SPEED_Y;

    FuriMessageQueue* queue = furi_message_queue_alloc(8, sizeof(InputEvent));
    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, cube_draw_callback, &state);
    view_port_input_callback_set(view_port, cube_input_callback, queue);

    NotificationApp* notification = furi_record_open(RECORD_NOTIFICATION);
    notification_message(notification, &sequence_display_backlight_enforce_on);

    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);

    bool running = true;
    while(running) {
        InputEvent event;
        if(furi_message_queue_get(queue, &event, 16) == FuriStatusOk) {
            if(event.type == InputTypePress && event.key == InputKeyBack) {
                running = false;
            }
        }
        view_port_update(view_port);
    }

    gui_remove_view_port(gui, view_port);
    furi_record_close(RECORD_GUI);

    notification_message(notification, &sequence_display_backlight_enforce_auto);
    furi_record_close(RECORD_NOTIFICATION);
    view_port_free(view_port);
    furi_message_queue_free(queue);

    return 0;
}

static void gps_location_callback(GpsStatus status, const GpsLocation* location, void* context) {
    GpsClickApp* app = context;
    furi_mutex_acquire(app->mutex, FuriWaitForever);
    app->state = GpsClickStateResult;
    app->status = status;
    bool got_fix = status == GpsStatusOk && location;
    if(got_fix) {
        app->location = *location;
        app->has_fix = true;
    } else {
        app->has_fix = false;
        app->location = (GpsLocation){0};
    }
    furi_mutex_release(app->mutex);

    if(got_fix) {
        notification_message(app->notifications, &sequence_blink_green_10);
    }
}

static void render_message(Canvas* canvas, const char* primary, const char* secondary) {
    canvas_set_font(canvas, FontPrimary);
    canvas_draw_str_aligned(canvas, 64, 30, AlignCenter, AlignBottom, primary);
    if(secondary) {
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str_aligned(canvas, 64, 44, AlignCenter, AlignBottom, secondary);
    }
}

static void render_callback(Canvas* canvas, void* context) {
    GpsClickApp* app = context;
    furi_mutex_acquire(app->mutex, FuriWaitForever);

    char buffer[64];

    if(app->state == GpsClickStateIdle) {
        render_message(canvas, "GPS one-shot request", "Press OK to get location");
    } else if(app->state == GpsClickStateWaiting) {
        render_message(canvas, "Requesting...", NULL);
    } else if(app->state == GpsClickStateSendFailed) {
        render_message(canvas, "No USB/BLE connection", "Press OK to retry");
    } else if(app->state == GpsClickStateTimeout) {
        render_message(canvas, "No response", "Press OK to retry");
    } else if(app->status == GpsStatusNotSupported) {
        render_message(canvas, "GPS not available", "Press OK to retry");
    } else if(app->status == GpsStatusNoPermission) {
        render_message(canvas, "Permission denied", "Press OK to retry");
    } else if(app->status == GpsStatusDisabled) {
        render_message(canvas, "Location disabled", "Press OK to retry");
    } else if(app->status == GpsStatusUnknown) {
        render_message(canvas, "Location error", "Press OK to retry");
    } else if(!app->has_fix) {
        render_message(canvas, "No location data", "Press OK to retry");
    } else {
        const GpsLocation* location = &app->location;

        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 32, 8, AlignCenter, AlignBottom, "Latitude");
        canvas_draw_str_aligned(canvas, 96, 8, AlignCenter, AlignBottom, "Longitude");
        canvas_draw_str_aligned(canvas, 21, 30, AlignCenter, AlignBottom, "Course");
        canvas_draw_str_aligned(canvas, 64, 30, AlignCenter, AlignBottom, "Speed");
        canvas_draw_str_aligned(canvas, 107, 30, AlignCenter, AlignBottom, "Altitude");
        canvas_draw_str_aligned(canvas, 32, 52, AlignCenter, AlignBottom, "Satellites");
        canvas_draw_str_aligned(canvas, 96, 52, AlignCenter, AlignBottom, "Accuracy");

        canvas_set_font(canvas, FontSecondary);

        // coordinate
        gps_location_format_coordinate(buffer, sizeof(buffer), location->latitude);
        canvas_draw_str_aligned(canvas, 32, 18, AlignCenter, AlignBottom, buffer);
        gps_location_format_coordinate(buffer, sizeof(buffer), location->longitude);
        canvas_draw_str_aligned(canvas, 96, 18, AlignCenter, AlignBottom, buffer);

        // heading
        gps_location_format_heading(buffer, sizeof(buffer), location->heading);
        canvas_draw_str_aligned(canvas, 21, 40, AlignCenter, AlignBottom, buffer);

        // speed
        gps_location_format_speed(buffer, sizeof(buffer), location->speed);
        strlcat(buffer, " m/s", sizeof(buffer));
        canvas_draw_str_aligned(canvas, 64, 40, AlignCenter, AlignBottom, buffer);

        // altitude
        gps_location_format_altitude(buffer, sizeof(buffer), location->altitude);
        strlcat(buffer, " m", sizeof(buffer));
        canvas_draw_str_aligned(canvas, 107, 40, AlignCenter, AlignBottom, buffer);

        // satellites
        snprintf(buffer, sizeof(buffer), "%lu", location->satellites);
        canvas_draw_str_aligned(canvas, 32, 62, AlignCenter, AlignBottom, buffer);

        // accuracy
        gps_location_format_accuracy(buffer, sizeof(buffer), location->accuracy);
        strlcat(buffer, " m", sizeof(buffer));
        canvas_draw_str_aligned(canvas, 96, 62, AlignCenter, AlignBottom, buffer);
    }

    furi_mutex_release(app->mutex);
}

int32_t gps_click_app(void* p) {
    UNUSED(p);

    GpsClickApp* app = malloc(sizeof(GpsClickApp));
    app->mutex = furi_mutex_alloc(FuriMutexTypeNormal);
    app->state = GpsClickStateIdle;
    app->status = GpsStatusOk;
    app->has_fix = false;
    app->location = (GpsLocation){0};
    app->request_tick = 0;

    FuriMessageQueue* event_queue = furi_message_queue_alloc(8, sizeof(InputEvent));

    /*
     * RECORD_GPS is the public firmware service handle. Applications do not
     * parse RPC directly; they use this service API and receive GpsLocation.
     */
    Gps* gps = furi_record_open(RECORD_GPS);
    NotificationApp* notifications = furi_record_open(RECORD_NOTIFICATION);
    app->notifications = notifications;
    gps_set_location_callback(gps, gps_location_callback, app);

    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, render_callback, app);
    view_port_input_callback_set(view_port, input_callback, event_queue);

    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);

    notification_message(notifications, &sequence_display_backlight_enforce_on);

    InputEvent event;
    for(bool processing = true; processing;) {
        if(furi_message_queue_get(event_queue, &event, 100) == FuriStatusOk) {
            if(event.type == InputTypeShort && event.key == InputKeyBack) {
                processing = false;
            } else if(event.type == InputTypeShort && event.key == InputKeyOk) {
                furi_mutex_acquire(app->mutex, FuriWaitForever);
                bool waiting = app->state == GpsClickStateWaiting;
                furi_mutex_release(app->mutex);

                /*
                 * gps_request_location() asks the companion for a single fix.
                 * Its return value means the command was sent through a live
                 * GPS bridge, not that the fix has already arrived; the reply
                 * comes through the location callback. Ignore OK while a
                 * request is still in flight.
                 */
                if(!waiting) {
                    bool sent = gps_request_location(gps);
                    furi_mutex_acquire(app->mutex, FuriWaitForever);
                    if(sent) {
                        app->state = GpsClickStateWaiting;
                        app->request_tick = furi_get_tick();
                    } else {
                        app->state = GpsClickStateSendFailed;
                    }
                    app->has_fix = false;
                    app->location = (GpsLocation){0};
                    furi_mutex_release(app->mutex);
                    if(!sent) {
                        notification_message(notifications, &sequence_blink_red_10);
                    }
                }
            }
        }

        /*
         * No reply for GPS_REQUEST_TIMEOUT_MS: report the timeout and let the
         * user retry with OK. A late reply after this point is still accepted
         * by the callback and simply replaces the timeout screen.
         */
        furi_mutex_acquire(app->mutex, FuriWaitForever);
        bool timed_out = app->state == GpsClickStateWaiting &&
                         furi_get_tick() - app->request_tick >
                             furi_ms_to_ticks(GPS_REQUEST_TIMEOUT_MS);
        if(timed_out) {
            app->state = GpsClickStateTimeout;
        }
        furi_mutex_release(app->mutex);
        if(timed_out) {
            notification_message(notifications, &sequence_blink_red_10);
        }

        view_port_update(view_port);
    }

    /*
     * Shut down in reverse order: detach the service callback, then close
     * RECORD_GPS. There is no stream to stop for one-shot requests.
     */
    gps_set_location_callback(gps, NULL, NULL);
    furi_record_close(RECORD_GPS);

    notification_message(notifications, &sequence_display_backlight_enforce_auto);
    furi_record_close(RECORD_NOTIFICATION);

    view_port_enabled_set(view_port, false);
    gui_remove_view_port(gui, view_port);
    furi_record_close(RECORD_GUI);
    view_port_free(view_port);
    furi_message_queue_free(event_queue);
    furi_mutex_free(app->mutex);
    free(app);

    return 0;
}

static void gps_view_reset_locked(GpsView* gps_view) {
    gps_view->connected = false;
    gps_view->status = GpsStatusOk;
    gps_view->has_fix = false;
    gps_view->location = (GpsLocation){0};
    gps_view->last_location_tick = 0;
}

static void gps_location_callback(GpsStatus status, const GpsLocation* location, void* context) {
    GpsView* gps_view = context;
    furi_mutex_acquire(gps_view->mutex, FuriWaitForever);
    gps_view->connected = true;
    gps_view->status = status;
    gps_view->last_location_tick = furi_get_tick();
    bool got_fix = status == GpsStatusOk && location;
    if(got_fix) {
        gps_view->location = *location;
        gps_view->has_fix = true;
    } else {
        gps_view->has_fix = false;
        gps_view->location = (GpsLocation){0};
    }
    furi_mutex_release(gps_view->mutex);

    if(got_fix) {
        notification_message(gps_view->notifications, &sequence_blink_green_10);
    }
}

static void render_callback(Canvas* canvas, void* context) {
    GpsView* gps_view = context;
    furi_mutex_acquire(gps_view->mutex, FuriWaitForever);

    char buffer[64];

    if(!gps_view->connected) {
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 64, 32, AlignCenter, AlignBottom, "No USB/BLE connection");
    } else if(gps_view->status == GpsStatusNotSupported) {
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 64, 32, AlignCenter, AlignBottom, "GPS not available");
    } else if(gps_view->status == GpsStatusNoPermission) {
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 64, 32, AlignCenter, AlignBottom, "Permission denied");
    } else if(gps_view->status == GpsStatusDisabled) {
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 64, 32, AlignCenter, AlignBottom, "Location disabled");
    } else if(gps_view->status == GpsStatusUnknown) {
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 64, 32, AlignCenter, AlignBottom, "Location error");
    } else if(!gps_view->has_fix) {
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 64, 32, AlignCenter, AlignBottom, "Waiting for data...");
    } else {
        const GpsLocation* location = &gps_view->location;

        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 32, 8, AlignCenter, AlignBottom, "Latitude");
        canvas_draw_str_aligned(canvas, 96, 8, AlignCenter, AlignBottom, "Longitude");
        canvas_draw_str_aligned(canvas, 21, 30, AlignCenter, AlignBottom, "Course");
        canvas_draw_str_aligned(canvas, 64, 30, AlignCenter, AlignBottom, "Speed");
        canvas_draw_str_aligned(canvas, 107, 30, AlignCenter, AlignBottom, "Altitude");
        canvas_draw_str_aligned(canvas, 32, 52, AlignCenter, AlignBottom, "Satellites");
        canvas_draw_str_aligned(canvas, 96, 52, AlignCenter, AlignBottom, "Accuracy");

        canvas_set_font(canvas, FontSecondary);

        // coordinate
        gps_location_format_coordinate(buffer, sizeof(buffer), location->latitude);
        canvas_draw_str_aligned(canvas, 32, 18, AlignCenter, AlignBottom, buffer);
        gps_location_format_coordinate(buffer, sizeof(buffer), location->longitude);
        canvas_draw_str_aligned(canvas, 96, 18, AlignCenter, AlignBottom, buffer);

        // heading
        gps_location_format_heading(buffer, sizeof(buffer), location->heading);
        canvas_draw_str_aligned(canvas, 21, 40, AlignCenter, AlignBottom, buffer);

        // speed
        gps_location_format_speed(buffer, sizeof(buffer), location->speed);
        strlcat(buffer, " m/s", sizeof(buffer));
        canvas_draw_str_aligned(canvas, 64, 40, AlignCenter, AlignBottom, buffer);

        // altitude
        gps_location_format_altitude(buffer, sizeof(buffer), location->altitude);
        strlcat(buffer, " m", sizeof(buffer));
        canvas_draw_str_aligned(canvas, 107, 40, AlignCenter, AlignBottom, buffer);

        // satellites
        snprintf(buffer, sizeof(buffer), "%lu", location->satellites);
        canvas_draw_str_aligned(canvas, 32, 62, AlignCenter, AlignBottom, buffer);

        // accuracy
        gps_location_format_accuracy(buffer, sizeof(buffer), location->accuracy);
        strlcat(buffer, " m", sizeof(buffer));
        canvas_draw_str_aligned(canvas, 96, 62, AlignCenter, AlignBottom, buffer);
    }

    furi_mutex_release(gps_view->mutex);
}

int32_t gps_stream_app(void* p) {
    UNUSED(p);

    GpsView* gps_view = malloc(sizeof(GpsView));
    gps_view->mutex = furi_mutex_alloc(FuriMutexTypeNormal);
    gps_view_reset_locked(gps_view);

    FuriMessageQueue* event_queue = furi_message_queue_alloc(8, sizeof(InputEvent));

    /*
     * RECORD_GPS is the public firmware service handle. Applications do not
     * parse RPC directly; they use this service API and receive GpsLocation.
     */
    Gps* gps = furi_record_open(RECORD_GPS);
    NotificationApp* notifications = furi_record_open(RECORD_NOTIFICATION);
    gps_view->notifications = notifications;
    gps_set_location_callback(gps, gps_location_callback, gps_view);

    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, render_callback, gps_view);
    view_port_input_callback_set(view_port, input_callback, event_queue);

    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);

    InputEvent event;
    uint32_t next_poll = 0;
    bool stream_active = false;
    uint32_t stream_start_tick = 0;
    bool backlight_on = true;
    notification_message(notifications, &sequence_display_backlight_enforce_on);

    for(bool processing = true; processing;) {
        if(furi_message_queue_get(event_queue, &event, 100) == FuriStatusOk) {
            if(event.type == InputTypeShort && event.key == InputKeyBack) {
                processing = false;
            } else if(event.type == InputTypeShort && event.key == InputKeyOk) {
                backlight_on = !backlight_on;
                if(backlight_on) {
                    notification_message(notifications, &sequence_display_backlight_enforce_on);
                } else {
                    notification_message(notifications, &sequence_display_backlight_enforce_auto);
                    notification_message(notifications, &sequence_display_backlight_off);
                }
            }
        }

        if(furi_get_tick() >= next_poll) {
            uint32_t now = furi_get_tick();
            next_poll = now + furi_ms_to_ticks(GPS_POLL_PERIOD_MS);

            if(!stream_active) {
                /*
                 * gps_request_stream() asks the companion to stream location
                 * data. Its return value means the command was sent through a
                 * live GPS bridge, not that a fresh fix has already arrived.
                 * Once it succeeds the stream stays open; it is not
                 * re-requested until a timeout resets the state below.
                 */
                if(gps_request_stream(gps, GPS_STREAM_FREQUENCY)) {
                    stream_active = true;
                    stream_start_tick = now;
                } else {
                    notification_message(notifications, &sequence_blink_red_10);
                    furi_mutex_acquire(gps_view->mutex, FuriWaitForever);
                    gps_view_reset_locked(gps_view);
                    furi_mutex_release(gps_view->mutex);
                }
            } else {
                furi_mutex_acquire(gps_view->mutex, FuriWaitForever);
                uint32_t last_packet_tick = gps_view->last_location_tick ?
                                                gps_view->last_location_tick :
                                                stream_start_tick;
                furi_mutex_release(gps_view->mutex);

                /*
                 * No packets for GPS_STREAM_TIMEOUT_MS: close the stale
                 * stream, drop to the disconnected state and wait for the
                 * bridge again on the next poll cycles.
                 */
                if(now - last_packet_tick > furi_ms_to_ticks(GPS_STREAM_TIMEOUT_MS)) {
                    gps_stop_stream(gps);
                    stream_active = false;
                    furi_mutex_acquire(gps_view->mutex, FuriWaitForever);
                    gps_view_reset_locked(gps_view);
                    furi_mutex_release(gps_view->mutex);
                }
            }
        }

        view_port_update(view_port);
    }

    /*
     * Shut down in reverse order: stop the companion stream, detach the service
     * callback, then close RECORD_GPS.
     */
    gps_stop_stream(gps);
    gps_set_location_callback(gps, NULL, NULL);
    furi_record_close(RECORD_GPS);

    notification_message(notifications, &sequence_display_backlight_enforce_auto);
    furi_record_close(RECORD_NOTIFICATION);

    view_port_enabled_set(view_port, false);
    gui_remove_view_port(gui, view_port);
    furi_record_close(RECORD_GUI);
    view_port_free(view_port);
    furi_message_queue_free(event_queue);
    furi_mutex_free(gps_view->mutex);
    free(gps_view);

    return 0;
}

static void bad_apple_store_body(BadAppleApp* app, const uint8_t* data, size_t size) {
    if(app->file_failed || !size) return;
    if(!storage_file_is_open(app->file)) {
        app->file_failed = true;
        return;
    }
    if(storage_file_write(app->file, data, size) != size) {
        app->file_failed = true;
        return;
    }
    app->bytes_saved += size;
}

static void bad_apple_pack_ssd(const Framebuffer fb, uint8_t* ssd) {
    for(int page = 0; page < (SCREEN_HEIGHT / 8); ++page) {
        const uint8_t* r0 = fb[page * 8 + 0];
        const uint8_t* r1 = fb[page * 8 + 1];
        const uint8_t* r2 = fb[page * 8 + 2];
        const uint8_t* r3 = fb[page * 8 + 3];
        const uint8_t* r4 = fb[page * 8 + 4];
        const uint8_t* r5 = fb[page * 8 + 5];
        const uint8_t* r6 = fb[page * 8 + 6];
        const uint8_t* r7 = fb[page * 8 + 7];
        uint8_t* out = ssd + page * DISP_W;
        for(int col = 0; col < SCREEN_WIDTH; ++col) {
            out[col] = (uint8_t)(
                (r0[col] != 0) | ((r1[col] != 0) << 1) | ((r2[col] != 0) << 2) |
                ((r3[col] != 0) << 3) | ((r4[col] != 0) << 4) | ((r5[col] != 0) << 5) |
                ((r6[col] != 0) << 6) | ((r7[col] != 0) << 7));
        }
    }
}

static void bad_apple_event_callback(const NetworkEvent* event, void* context) {
    if(event->connection_id != BAD_APPLE_REQUEST_ID) return;
    BadAppleApp* app = context;

    furi_mutex_acquire(app->mutex, FuriWaitForever);
    switch(event->type) {
    /* Body chunk. event->data is valid only during the callback, so it is
     * written to SD right here. */
    case NetworkEventReceived:
        if(event->data && event->size) bad_apple_store_body(app, event->data, event->size);
        break;
    /* Always the last event of the request: transport error, or
     * http_status + total body size. */
    case NetworkEventHttpResponse:
        app->http_status = event->http_status;
        if(event->error != NetworkErrorNone) {
            app->state = BadAppleError;
            app->error = event->error;
        } else if(event->http_status != 200) {
            app->state = BadAppleError;
            app->error = NetworkErrorInternal;
            snprintf(
                app->status_message,
                sizeof(app->status_message),
                "HTTP %lu",
                (unsigned long)event->http_status);
        } else if(app->file_failed || app->bytes_saved == 0) {
            app->state = BadAppleError;
            app->error = NetworkErrorFileError;
        } else {
            app->state = BadAppleDownloaded;
            app->play_requested = true;
        }
        break;
    default:
        break;
    }
    furi_mutex_release(app->mutex);
}

static void bad_apple_draw_callback(Canvas* canvas, void* context) {
    BadAppleApp* app = context;
    furi_mutex_acquire(app->mutex, FuriWaitForever);

    if(app->state == BadApplePlaying || app->state == BadAppleDone) {
        uint8_t* ssd = canvas_get_buffer(canvas);
        if(ssd) bad_apple_pack_ssd(app->fb, ssd);
    } else {
        char line[64];
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 64, 11, AlignCenter, AlignBottom, "Bad Apple");
        canvas_set_font(canvas, FontSecondary);
        const char* status = "Starting...";
        if(app->state == BadAppleNoBridge) status = "No USB/BLE connection";
        else if(app->state == BadAppleDownloading) status = "Downloading GIF...";
        else if(app->state == BadAppleDownloaded) status = "Preparing playback...";
        else if(app->state == BadAppleError) {
            status = app->status_message[0] ? app->status_message :
                                              network_error_to_string(app->error);
        }
        canvas_draw_str_aligned(canvas, 64, 28, AlignCenter, AlignBottom, status);
        snprintf(line, sizeof(line), "%lu bytes saved", (unsigned long)app->bytes_saved);
        canvas_draw_str_aligned(canvas, 64, 42, AlignCenter, AlignBottom, line);
        canvas_draw_str_aligned(canvas, 64, 58, AlignCenter, AlignBottom, BAD_APPLE_SAVE_PATH);
    }

    furi_mutex_release(app->mutex);
}

static bool gif_read_le16(File* file, uint16_t* value) {
    uint8_t b[2];
    if(storage_file_read(file, b, sizeof(b)) != sizeof(b)) return false;
    *value = (uint16_t)b[0] | ((uint16_t)b[1] << 8);
    return true;
}

static bool gif_skip_sub_blocks(File* file) {
    uint8_t size = 0;
    do {
        if(!gif_read_u8(file, &size)) return false;
        if(size && !gif_skip(file, size)) return false;
    } while(size);
    return true;
}

static bool gif_stream_next_byte(GifStream* stream, uint8_t* value) {
    if(stream->block_pos >= stream->block_size) {
        if(!gif_read_u8(stream->file, &stream->block_size)) return false;
        stream->block_pos = 0;
        if(stream->block_size == 0) return false;
        if(storage_file_read(stream->file, stream->block, stream->block_size) != stream->block_size)
            return false;
    }
    *value = stream->block[stream->block_pos++];
    return true;
}

static int32_t gif_stream_read_code(GifStream* stream, uint8_t code_size) {
    while(stream->bit_count < code_size) {
        uint8_t next = 0;
        if(!gif_stream_next_byte(stream, &next)) return -1;
        stream->bit_buffer |= ((uint32_t)next) << stream->bit_count;
        stream->bit_count += 8;
    }

    uint32_t code = stream->bit_buffer & ((1UL << code_size) - 1);
    stream->bit_buffer >>= code_size;
    stream->bit_count -= code_size;
    return code;
}

static bool gif_draw_index(
    BadAppleApp* app,
    uint16_t* pixel,
    uint16_t left,
    uint16_t top,
    uint16_t width,
    uint16_t height,
    bool interlace,
    const uint8_t* palette,
    uint16_t palette_size,
    int16_t transparent,
    uint8_t color_index) {
    if(*pixel >= (uint32_t)width * height) return true;
    if(color_index < palette_size && color_index != transparent) {
        uint16_t row = *pixel / width;
        uint16_t col = *pixel % width;
        if(interlace) {
            static const uint8_t starts[] = {0, 4, 2, 1};
            static const uint8_t steps[] = {8, 8, 4, 2};
            uint16_t mapped = row;
            uint16_t count = 0;
            for(uint8_t pass = 0; pass < 4; pass++) {
                for(uint16_t y = starts[pass]; y < height; y += steps[pass]) {
                    if(count++ == row) {
                        mapped = y;
                        pass = 4;
                        break;
                    }
                }
            }
            row = mapped;
        }
        uint16_t x = left + col;
        uint16_t y = top + row;
        if(x < SCREEN_WIDTH && y < SCREEN_HEIGHT) {
            app->fb[y][x] = gif_palette_luma(palette, color_index) < 128;
        }
    }
    (*pixel)++;
    return *pixel >= (uint32_t)width * height;
}

static bool gif_decode_image(
    BadAppleApp* app,
    File* file,
    GifWork* work,
    uint16_t left,
    uint16_t top,
    uint16_t width,
    uint16_t height,
    bool interlace,
    const uint8_t* palette,
    uint16_t palette_size,
    int16_t transparent) {
    uint8_t min_code_size = 0;
    if(!gif_read_u8(file, &min_code_size) || min_code_size > 8) return false;

    GifStream stream = {.file = file};
    uint16_t* prefix = work->prefix;
    uint8_t* suffix = work->suffix;
    uint8_t* stack = work->stack;

    int32_t clear_code = 1 << min_code_size;
    int32_t end_code = clear_code + 1;
    int32_t next_code = end_code + 1;
    uint8_t code_size = min_code_size + 1;
    int32_t old_code = -1;
    uint8_t first = 0;
    uint16_t pixel = 0;

    for(int32_t i = 0; i < clear_code; i++) {
        prefix[i] = 0;
        suffix[i] = i;
    }

    for(;;) {
        int32_t code = gif_stream_read_code(&stream, code_size);
        if(code < 0) break;
        if(code == clear_code) {
            code_size = min_code_size + 1;
            next_code = end_code + 1;
            old_code = -1;
            continue;
        }
        if(code == end_code) break;

        int32_t in_code = code;
        uint16_t stack_len = 0;
        if(code >= next_code) {
            if(old_code < 0) {
                return false;
            }
            stack[stack_len++] = first;
            code = old_code;
        }

        while(code >= clear_code) {
            if(code >= GIF_MAX_CODES || stack_len >= GIF_STACK_MAX) {
                return false;
            }
            stack[stack_len++] = suffix[code];
            code = prefix[code];
        }

        first = suffix[code];
        stack[stack_len++] = first;

        while(stack_len) {
            if(gif_draw_index(
                   app,
                   &pixel,
                   left,
                   top,
                   width,
                   height,
                   interlace,
                   palette,
                   palette_size,
                   transparent,
                   stack[--stack_len])) {
                break;
            }
        }

        if(old_code >= 0 && next_code < GIF_MAX_CODES) {
            prefix[next_code] = old_code;
            suffix[next_code] = first;
            next_code++;
            if(next_code == (1 << code_size) && code_size < 12) code_size++;
        }
        old_code = in_code;
        if(pixel >= (uint32_t)width * height) break;
    }

    gif_skip_sub_blocks(file);
    return true;
}

static bool bad_apple_play_gif(BadAppleApp* app, ViewPort* view_port, FuriMessageQueue* event_queue) {
    if(!storage_file_open(app->file, BAD_APPLE_SAVE_PATH, FSAM_READ, FSOM_OPEN_EXISTING)) return false;

    uint8_t header[13];
    bool ok = storage_file_read(app->file, header, sizeof(header)) == sizeof(header) &&
              memcmp(header, "GIF", 3) == 0;
    uint8_t global_palette[256 * 3];
    uint16_t global_palette_size = 0;
    if(ok && (header[10] & 0x80)) {
        global_palette_size = 1 << ((header[10] & 0x07) + 1);
        ok = storage_file_read(app->file, global_palette, global_palette_size * 3) ==
             global_palette_size * 3;
    }
    uint32_t frames_start = storage_file_tell(app->file);

    uint16_t delay_ms = 80;
    int16_t transparent = -1;
    bool processing = true;
    GifWork work = {
        .prefix = malloc(sizeof(uint16_t) * GIF_MAX_CODES),
        .suffix = malloc(sizeof(uint8_t) * GIF_MAX_CODES),
        .stack = malloc(GIF_STACK_MAX),
    };
    if(!work.prefix || !work.suffix || !work.stack) ok = false;
    while(ok && processing) {
        InputEvent event;
        if(furi_message_queue_get(event_queue, &event, 1) == FuriStatusOk) {
            if(event.type == InputTypeShort && event.key == InputKeyBack) {
                processing = false;
                break;
            }
        }

        uint8_t sep = 0;
        if(!gif_read_u8(app->file, &sep)) break;
        if(sep == 0x3B) {
            if(frames_start && storage_file_seek(app->file, frames_start, true)) {
                delay_ms = BAD_APPLE_MIN_DELAY_MS;
                transparent = -1;
                continue;
            }
            break;
        }
        if(sep == 0x21) {
            uint8_t label = 0;
            if(!gif_read_u8(app->file, &label)) {
                ok = false;
                break;
            }
            if(label == 0xF9) {
                uint8_t block_size = 0;
                uint8_t packed = 0;
                uint16_t delay_cs = 0;
                uint8_t trans = 0;
                uint8_t terminator = 0;
                ok = gif_read_u8(app->file, &block_size) && block_size == 4 &&
                     gif_read_u8(app->file, &packed) && gif_read_le16(app->file, &delay_cs) &&
                     gif_read_u8(app->file, &trans) && gif_read_u8(app->file, &terminator);
                if(!ok) break;
                delay_ms = delay_cs ? delay_cs * 10 : BAD_APPLE_MIN_DELAY_MS;
                if(delay_ms < BAD_APPLE_MIN_DELAY_MS) delay_ms = BAD_APPLE_MIN_DELAY_MS;
                transparent = (packed & 0x01) ? trans : -1;
            } else {
                ok = gif_skip_sub_blocks(app->file);
            }
        } else if(sep == 0x2C) {
            uint16_t left = 0;
            uint16_t top = 0;
            uint16_t width = 0;
            uint16_t height = 0;
            uint8_t packed = 0;
            ok = gif_read_le16(app->file, &left) && gif_read_le16(app->file, &top) &&
                 gif_read_le16(app->file, &width) && gif_read_le16(app->file, &height) &&
                 gif_read_u8(app->file, &packed);
            if(!ok) break;

            uint8_t local_palette[256 * 3];
            const uint8_t* palette = global_palette;
            uint16_t palette_size = global_palette_size;
            if(packed & 0x80) {
                palette_size = 1 << ((packed & 0x07) + 1);
                ok = storage_file_read(app->file, local_palette, palette_size * 3) == palette_size * 3;
                palette = local_palette;
            }
            if(!ok || !palette_size) break;

            furi_mutex_acquire(app->mutex, FuriWaitForever);
            app->state = BadApplePlaying;
            app->delay_ms = delay_ms;
            furi_mutex_release(app->mutex);

            ok = gif_decode_image(
                app,
                app->file,
                &work,
                left,
                top,
                width,
                height,
                packed & 0x40,
                palette,
                palette_size,
                transparent);
            if(!ok) break;

            furi_mutex_acquire(app->mutex, FuriWaitForever);
            app->frames++;
            furi_mutex_release(app->mutex);
            view_port_update(view_port);
            furi_delay_ms(delay_ms);
        } else {
            ok = false;
        }
    }

    free(work.prefix);
    free(work.suffix);
    free(work.stack);
    storage_file_close(app->file);
    return ok;
}

int32_t network_bad_apple_app(void* p) {
    UNUSED(p);

    BadAppleApp* app = malloc(sizeof(BadAppleApp));
    memset(app, 0, sizeof(BadAppleApp));
    app->mutex = furi_mutex_alloc(FuriMutexTypeNormal);
    app->state = BadAppleInit;

    FuriMessageQueue* event_queue = furi_message_queue_alloc(8, sizeof(InputEvent));
    app->storage = furi_record_open(RECORD_STORAGE);
    app->file = storage_file_alloc(app->storage);
    if(!storage_file_open(app->file, BAD_APPLE_SAVE_PATH, FSAM_WRITE, FSOM_CREATE_ALWAYS)) {
        app->file_failed = true;
    }

    Network* network = furi_record_open(RECORD_NETWORK);
    network_set_event_callback(network, bad_apple_event_callback, app);

    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, bad_apple_draw_callback, app);
    view_port_input_callback_set(view_port, bad_apple_input_callback, event_queue);

    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);

    /* No save_path: the body is streamed to this app chunk by chunk as
     * NetworkEventReceived. */
    const NetworkHttpRequest request = {
        .method = NetworkHttpMethodGet,
        .url = BAD_APPLE_URL,
        .timeout_ms = BAD_APPLE_TIMEOUT_MS,
    };

    /* false = no live companion session (USB/BLE); the download itself runs
     * asynchronously and finishes in the event callback. */
    furi_mutex_acquire(app->mutex, FuriWaitForever);
    bool requested = network_http_request(network, BAD_APPLE_REQUEST_ID, &request);
    app->state = requested ? BadAppleDownloading : BadAppleNoBridge;
    furi_mutex_release(app->mutex);

    InputEvent event;
    for(bool processing = true; processing;) {
        if(furi_message_queue_get(event_queue, &event, 100) == FuriStatusOk) {
            if(event.type == InputTypeShort && event.key == InputKeyBack) processing = false;
        }

        furi_mutex_acquire(app->mutex, FuriWaitForever);
        bool play_requested = app->play_requested;
        app->play_requested = false;
        furi_mutex_release(app->mutex);

        if(play_requested) {
            if(storage_file_is_open(app->file)) storage_file_close(app->file);
            bool ok = bad_apple_play_gif(app, view_port, event_queue);
            furi_mutex_acquire(app->mutex, FuriWaitForever);
            app->state = ok ? BadAppleDone : BadAppleError;
            if(!ok) app->error = NetworkErrorInternal;
            furi_mutex_release(app->mutex);
        }

        view_port_update(view_port);
    }

    /* Unsubscribe before closing the record so late body chunks cannot reach
     * a freed context. */
    network_set_event_callback(network, NULL, NULL);
    furi_record_close(RECORD_NETWORK);

    if(storage_file_is_open(app->file)) storage_file_close(app->file);
    storage_file_free(app->file);
    furi_record_close(RECORD_STORAGE);

    view_port_enabled_set(view_port, false);
    gui_remove_view_port(gui, view_port);
    furi_record_close(RECORD_GUI);
    view_port_free(view_port);
    furi_message_queue_free(event_queue);
    furi_mutex_free(app->mutex);
    free(app);

    return 0;
}

static void bad_apple_pack_ssd(const Framebuffer fb, uint8_t* ssd) {
    for(int page = 0; page < (SCREEN_HEIGHT / 8); ++page) {
        const uint8_t* r0 = fb[page * 8 + 0];
        const uint8_t* r1 = fb[page * 8 + 1];
        const uint8_t* r2 = fb[page * 8 + 2];
        const uint8_t* r3 = fb[page * 8 + 3];
        const uint8_t* r4 = fb[page * 8 + 4];
        const uint8_t* r5 = fb[page * 8 + 5];
        const uint8_t* r6 = fb[page * 8 + 6];
        const uint8_t* r7 = fb[page * 8 + 7];
        uint8_t* out = ssd + page * DISP_W;
        for(int col = 0; col < SCREEN_WIDTH; ++col) {
            out[col] = (uint8_t)(
                (r0[col] != 0) | ((r1[col] != 0) << 1) | ((r2[col] != 0) << 2) |
                ((r3[col] != 0) << 3) | ((r4[col] != 0) << 4) | ((r5[col] != 0) << 5) |
                ((r6[col] != 0) << 6) | ((r7[col] != 0) << 7));
        }
    }
}

static void bad_apple_event_callback(const NetworkEvent* event, void* context) {
    if(event->connection_id != BAD_APPLE_REQUEST_ID) return;
    BadAppleApp* app = context;

    furi_mutex_acquire(app->mutex, FuriWaitForever);
    /* save_path is set, so the companion writes the body to SD itself: there are
     * no NetworkEventReceived chunks to handle, only the final response. */
    if(event->type == NetworkEventHttpResponse) {
        app->http_status = event->http_status;
        if(event->error != NetworkErrorNone) {
            app->state = BadAppleError;
            app->error = event->error;
        } else if(event->http_status != 200) {
            app->state = BadAppleError;
            app->error = NetworkErrorInternal;
            snprintf(
                app->status_message,
                sizeof(app->status_message),
                "HTTP %lu",
                (unsigned long)event->http_status);
        } else if(!event->saved_to_file) {
            app->state = BadAppleError;
            app->error = NetworkErrorFileError;
        } else {
            app->state = BadAppleDownloaded;
            app->play_requested = true;
        }
    }
    furi_mutex_release(app->mutex);
}

static void bad_apple_draw_callback(Canvas* canvas, void* context) {
    BadAppleApp* app = context;
    furi_mutex_acquire(app->mutex, FuriWaitForever);

    if(app->state == BadApplePlaying || app->state == BadAppleDone) {
        uint8_t* ssd = canvas_get_buffer(canvas);
        if(ssd) bad_apple_pack_ssd(app->fb, ssd);
    } else {
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 64, 11, AlignCenter, AlignBottom, "Bad Apple (save)");
        canvas_set_font(canvas, FontSecondary);
        const char* status = "Starting...";
        if(app->state == BadAppleNoBridge) status = "No USB/BLE connection";
        else if(app->state == BadAppleDownloading) status = "Downloading on companion...";
        else if(app->state == BadAppleDownloaded) status = "Preparing playback...";
        else if(app->state == BadAppleError) {
            status = app->status_message[0] ? app->status_message :
                                              network_error_to_string(app->error);
        }
        canvas_draw_str_aligned(canvas, 64, 28, AlignCenter, AlignBottom, status);
        canvas_draw_str_aligned(canvas, 64, 58, AlignCenter, AlignBottom, BAD_APPLE_SAVE_PATH);
    }

    furi_mutex_release(app->mutex);
}

static bool gif_read_le16(File* file, uint16_t* value) {
    uint8_t b[2];
    if(storage_file_read(file, b, sizeof(b)) != sizeof(b)) return false;
    *value = (uint16_t)b[0] | ((uint16_t)b[1] << 8);
    return true;
}

static bool gif_skip_sub_blocks(File* file) {
    uint8_t size = 0;
    do {
        if(!gif_read_u8(file, &size)) return false;
        if(size && !gif_skip(file, size)) return false;
    } while(size);
    return true;
}

static bool gif_stream_next_byte(GifStream* stream, uint8_t* value) {
    if(stream->block_pos >= stream->block_size) {
        if(!gif_read_u8(stream->file, &stream->block_size)) return false;
        stream->block_pos = 0;
        if(stream->block_size == 0) return false;
        if(storage_file_read(stream->file, stream->block, stream->block_size) != stream->block_size)
            return false;
    }
    *value = stream->block[stream->block_pos++];
    return true;
}

static int32_t gif_stream_read_code(GifStream* stream, uint8_t code_size) {
    while(stream->bit_count < code_size) {
        uint8_t next = 0;
        if(!gif_stream_next_byte(stream, &next)) return -1;
        stream->bit_buffer |= ((uint32_t)next) << stream->bit_count;
        stream->bit_count += 8;
    }

    uint32_t code = stream->bit_buffer & ((1UL << code_size) - 1);
    stream->bit_buffer >>= code_size;
    stream->bit_count -= code_size;
    return code;
}

static bool gif_draw_index(
    BadAppleApp* app,
    uint16_t* pixel,
    uint16_t left,
    uint16_t top,
    uint16_t width,
    uint16_t height,
    bool interlace,
    const uint8_t* palette,
    uint16_t palette_size,
    int16_t transparent,
    uint8_t color_index) {
    if(*pixel >= (uint32_t)width * height) return true;
    if(color_index < palette_size && color_index != transparent) {
        uint16_t row = *pixel / width;
        uint16_t col = *pixel % width;
        if(interlace) {
            static const uint8_t starts[] = {0, 4, 2, 1};
            static const uint8_t steps[] = {8, 8, 4, 2};
            uint16_t mapped = row;
            uint16_t count = 0;
            for(uint8_t pass = 0; pass < 4; pass++) {
                for(uint16_t y = starts[pass]; y < height; y += steps[pass]) {
                    if(count++ == row) {
                        mapped = y;
                        pass = 4;
                        break;
                    }
                }
            }
            row = mapped;
        }
        uint16_t x = left + col;
        uint16_t y = top + row;
        if(x < SCREEN_WIDTH && y < SCREEN_HEIGHT) {
            app->fb[y][x] = gif_palette_luma(palette, color_index) < 128;
        }
    }
    (*pixel)++;
    return *pixel >= (uint32_t)width * height;
}

static bool gif_decode_image(
    BadAppleApp* app,
    File* file,
    GifWork* work,
    uint16_t left,
    uint16_t top,
    uint16_t width,
    uint16_t height,
    bool interlace,
    const uint8_t* palette,
    uint16_t palette_size,
    int16_t transparent) {
    uint8_t min_code_size = 0;
    if(!gif_read_u8(file, &min_code_size) || min_code_size > 8) return false;

    GifStream stream = {.file = file};
    uint16_t* prefix = work->prefix;
    uint8_t* suffix = work->suffix;
    uint8_t* stack = work->stack;

    int32_t clear_code = 1 << min_code_size;
    int32_t end_code = clear_code + 1;
    int32_t next_code = end_code + 1;
    uint8_t code_size = min_code_size + 1;
    int32_t old_code = -1;
    uint8_t first = 0;
    uint16_t pixel = 0;

    for(int32_t i = 0; i < clear_code; i++) {
        prefix[i] = 0;
        suffix[i] = i;
    }

    for(;;) {
        int32_t code = gif_stream_read_code(&stream, code_size);
        if(code < 0) break;
        if(code == clear_code) {
            code_size = min_code_size + 1;
            next_code = end_code + 1;
            old_code = -1;
            continue;
        }
        if(code == end_code) break;

        int32_t in_code = code;
        uint16_t stack_len = 0;
        if(code >= next_code) {
            if(old_code < 0) {
                return false;
            }
            stack[stack_len++] = first;
            code = old_code;
        }

        while(code >= clear_code) {
            if(code >= GIF_MAX_CODES || stack_len >= GIF_STACK_MAX) {
                return false;
            }
            stack[stack_len++] = suffix[code];
            code = prefix[code];
        }

        first = suffix[code];
        stack[stack_len++] = first;

        while(stack_len) {
            if(gif_draw_index(
                   app,
                   &pixel,
                   left,
                   top,
                   width,
                   height,
                   interlace,
                   palette,
                   palette_size,
                   transparent,
                   stack[--stack_len])) {
                break;
            }
        }

        if(old_code >= 0 && next_code < GIF_MAX_CODES) {
            prefix[next_code] = old_code;
            suffix[next_code] = first;
            next_code++;
            if(next_code == (1 << code_size) && code_size < 12) code_size++;
        }
        old_code = in_code;
        if(pixel >= (uint32_t)width * height) break;
    }

    gif_skip_sub_blocks(file);
    return true;
}

static bool bad_apple_play_gif(BadAppleApp* app, ViewPort* view_port, FuriMessageQueue* event_queue) {
    if(!storage_file_open(app->file, BAD_APPLE_SAVE_PATH, FSAM_READ, FSOM_OPEN_EXISTING)) return false;

    uint8_t header[13];
    bool ok = storage_file_read(app->file, header, sizeof(header)) == sizeof(header) &&
              memcmp(header, "GIF", 3) == 0;
    uint8_t global_palette[256 * 3];
    uint16_t global_palette_size = 0;
    if(ok && (header[10] & 0x80)) {
        global_palette_size = 1 << ((header[10] & 0x07) + 1);
        ok = storage_file_read(app->file, global_palette, global_palette_size * 3) ==
             global_palette_size * 3;
    }
    uint32_t frames_start = storage_file_tell(app->file);

    uint16_t delay_ms = 80;
    int16_t transparent = -1;
    bool processing = true;
    GifWork work = {
        .prefix = malloc(sizeof(uint16_t) * GIF_MAX_CODES),
        .suffix = malloc(sizeof(uint8_t) * GIF_MAX_CODES),
        .stack = malloc(GIF_STACK_MAX),
    };
    if(!work.prefix || !work.suffix || !work.stack) ok = false;
    while(ok && processing) {
        InputEvent event;
        if(furi_message_queue_get(event_queue, &event, 1) == FuriStatusOk) {
            if(event.type == InputTypeShort && event.key == InputKeyBack) {
                processing = false;
                break;
            }
        }

        uint8_t sep = 0;
        if(!gif_read_u8(app->file, &sep)) break;
        if(sep == 0x3B) {
            if(frames_start && storage_file_seek(app->file, frames_start, true)) {
                delay_ms = BAD_APPLE_MIN_DELAY_MS;
                transparent = -1;
                continue;
            }
            break;
        }
        if(sep == 0x21) {
            uint8_t label = 0;
            if(!gif_read_u8(app->file, &label)) {
                ok = false;
                break;
            }
            if(label == 0xF9) {
                uint8_t block_size = 0;
                uint8_t packed = 0;
                uint16_t delay_cs = 0;
                uint8_t trans = 0;
                uint8_t terminator = 0;
                ok = gif_read_u8(app->file, &block_size) && block_size == 4 &&
                     gif_read_u8(app->file, &packed) && gif_read_le16(app->file, &delay_cs) &&
                     gif_read_u8(app->file, &trans) && gif_read_u8(app->file, &terminator);
                if(!ok) break;
                delay_ms = delay_cs ? delay_cs * 10 : BAD_APPLE_MIN_DELAY_MS;
                if(delay_ms < BAD_APPLE_MIN_DELAY_MS) delay_ms = BAD_APPLE_MIN_DELAY_MS;
                transparent = (packed & 0x01) ? trans : -1;
            } else {
                ok = gif_skip_sub_blocks(app->file);
            }
        } else if(sep == 0x2C) {
            uint16_t left = 0;
            uint16_t top = 0;
            uint16_t width = 0;
            uint16_t height = 0;
            uint8_t packed = 0;
            ok = gif_read_le16(app->file, &left) && gif_read_le16(app->file, &top) &&
                 gif_read_le16(app->file, &width) && gif_read_le16(app->file, &height) &&
                 gif_read_u8(app->file, &packed);
            if(!ok) break;

            uint8_t local_palette[256 * 3];
            const uint8_t* palette = global_palette;
            uint16_t palette_size = global_palette_size;
            if(packed & 0x80) {
                palette_size = 1 << ((packed & 0x07) + 1);
                ok = storage_file_read(app->file, local_palette, palette_size * 3) == palette_size * 3;
                palette = local_palette;
            }
            if(!ok || !palette_size) break;

            furi_mutex_acquire(app->mutex, FuriWaitForever);
            app->state = BadApplePlaying;
            app->delay_ms = delay_ms;
            furi_mutex_release(app->mutex);

            ok = gif_decode_image(
                app,
                app->file,
                &work,
                left,
                top,
                width,
                height,
                packed & 0x40,
                palette,
                palette_size,
                transparent);
            if(!ok) break;

            furi_mutex_acquire(app->mutex, FuriWaitForever);
            app->frames++;
            furi_mutex_release(app->mutex);
            view_port_update(view_port);
            furi_delay_ms(delay_ms);
        } else {
            ok = false;
        }
    }

    free(work.prefix);
    free(work.suffix);
    free(work.stack);
    storage_file_close(app->file);
    return ok;
}

int32_t network_bad_apple_save_app(void* p) {
    UNUSED(p);

    BadAppleApp* app = malloc(sizeof(BadAppleApp));
    memset(app, 0, sizeof(BadAppleApp));
    app->mutex = furi_mutex_alloc(FuriMutexTypeNormal);
    app->state = BadAppleInit;

    FuriMessageQueue* event_queue = furi_message_queue_alloc(8, sizeof(InputEvent));
    app->storage = furi_record_open(RECORD_STORAGE);
    app->file = storage_file_alloc(app->storage);

    Network* network = furi_record_open(RECORD_NETWORK);
    network_set_event_callback(network, bad_apple_event_callback, app);

    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, bad_apple_draw_callback, app);
    view_port_input_callback_set(view_port, bad_apple_input_callback, event_queue);

    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);

    /* save_path tells the companion to write the response body to the SD card
     * itself; the firmware only waits for the final NetworkEventHttpResponse. */
    const NetworkHttpRequest request = {
        .method = NetworkHttpMethodGet,
        .url = BAD_APPLE_URL,
        .save_path = BAD_APPLE_SAVE_PATH,
        .timeout_ms = BAD_APPLE_TIMEOUT_MS,
    };

    /* false = no live companion session (USB/BLE); the download runs on the
     * companion and finishes in the event callback. */
    furi_mutex_acquire(app->mutex, FuriWaitForever);
    bool requested = network_http_request(network, BAD_APPLE_REQUEST_ID, &request);
    app->state = requested ? BadAppleDownloading : BadAppleNoBridge;
    furi_mutex_release(app->mutex);

    InputEvent event;
    for(bool processing = true; processing;) {
        if(furi_message_queue_get(event_queue, &event, 100) == FuriStatusOk) {
            if(event.type == InputTypeShort && event.key == InputKeyBack) processing = false;
        }

        furi_mutex_acquire(app->mutex, FuriWaitForever);
        bool play_requested = app->play_requested;
        app->play_requested = false;
        furi_mutex_release(app->mutex);

        if(play_requested) {
            if(storage_file_is_open(app->file)) storage_file_close(app->file);
            bool ok = bad_apple_play_gif(app, view_port, event_queue);
            furi_mutex_acquire(app->mutex, FuriWaitForever);
            app->state = ok ? BadAppleDone : BadAppleError;
            if(!ok) app->error = NetworkErrorInternal;
            furi_mutex_release(app->mutex);
        }

        view_port_update(view_port);
    }

    /* Unsubscribe before closing the record so a late event cannot reach a
     * freed context. */
    network_set_event_callback(network, NULL, NULL);
    furi_record_close(RECORD_NETWORK);

    if(storage_file_is_open(app->file)) storage_file_close(app->file);
    storage_file_free(app->file);
    furi_record_close(RECORD_STORAGE);

    view_port_enabled_set(view_port, false);
    gui_remove_view_port(gui, view_port);
    furi_record_close(RECORD_GUI);
    view_port_free(view_port);
    furi_message_queue_free(event_queue);
    furi_mutex_free(app->mutex);
    free(app);

    return 0;
}

static void network_test_event_callback(const NetworkEvent* event, void* context) {
    NetworkTest* test = context;
    if(event->connection_id != NETWORK_TEST_REQUEST_ID) return;

    furi_mutex_acquire(test->mutex, FuriWaitForever);
    if(event->type == NetworkEventHttpResponse) {
        /* error covers the transport (DNS/TCP/TLS/timeout/file). On success
         * http_status is the HTTP code, size is the body size, saved_to_file
         * confirms the companion wrote the body to save_path. */
        if(event->error != NetworkErrorNone) {
            test->state = AppStateError;
            test->error = event->error;
        } else {
            test->state = AppStateDone;
            test->http_status = event->http_status;
            test->body_size = event->size;
            test->saved_to_file = event->saved_to_file;
        }
    }
    furi_mutex_release(test->mutex);
}

static void render_callback(Canvas* canvas, void* context) {
    NetworkTest* test = context;
    furi_mutex_acquire(test->mutex, FuriWaitForever);

    char buffer[64];

    canvas_set_font(canvas, FontPrimary);
    canvas_draw_str_aligned(canvas, 64, 10, AlignCenter, AlignBottom, "Internet test");

    canvas_set_font(canvas, FontSecondary);
    canvas_draw_str_aligned(canvas, 64, 21, AlignCenter, AlignBottom, NETWORK_TEST_URL);

    const char* status;
    switch(test->state) {
    case AppStateNoBridge:
        status = "No USB/BLE connection";
        break;
    case AppStateInit:
    case AppStateRequesting:
        status = "Requesting...";
        break;
    case AppStateDone:
        status = "Internet available";
        break;
    case AppStateError:
        status = network_error_to_string(test->error);
        break;
    default:
        status = "";
        break;
    }
    canvas_draw_str_aligned(canvas, 64, 33, AlignCenter, AlignBottom, status);

    if(test->http_status) {
        snprintf(buffer, sizeof(buffer), "HTTP %lu", (unsigned long)test->http_status);
        canvas_draw_str_aligned(canvas, 64, 44, AlignCenter, AlignBottom, buffer);
    }

    if(test->state == AppStateDone) {
        const char* tail = test->saved_to_file ? "saved to SD" : "received";
        snprintf(buffer, sizeof(buffer), "%lu bytes %s", (unsigned long)test->body_size, tail);
        canvas_draw_str_aligned(canvas, 64, 55, AlignCenter, AlignBottom, buffer);
    }

    furi_mutex_release(test->mutex);
}

int32_t network_app(void* p) {
    UNUSED(p);

    NetworkTest* test = malloc(sizeof(NetworkTest));
    test->mutex = furi_mutex_alloc(FuriMutexTypeNormal);
    test->state = AppStateInit;
    test->error = NetworkErrorNone;
    test->http_status = 0;
    test->body_size = 0;
    test->saved_to_file = false;

    FuriMessageQueue* event_queue = furi_message_queue_alloc(8, sizeof(InputEvent));

    Network* network = furi_record_open(RECORD_NETWORK);
    network_set_event_callback(network, network_test_event_callback, test);

    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, render_callback, test);
    view_port_input_callback_set(view_port, input_callback, event_queue);

    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);

    /* Unset fields default to NULL/0: no extra headers, no request body,
     * timeout_ms = 0 would select the companion default. */
    const NetworkHttpRequest request = {
        .method = NetworkHttpMethodGet,
        .url = NETWORK_TEST_URL,
        .save_path = NETWORK_TEST_SAVE_PATH,
        .timeout_ms = NETWORK_TEST_TIMEOUT_MS,
    };

    /* true only means the request was handed to a live companion session; the
     * outcome arrives asynchronously in the callback. false = no USB/BLE RPC
     * session with a companion app. */
    furi_mutex_acquire(test->mutex, FuriWaitForever);
    bool requesting = network_http_request(network, NETWORK_TEST_REQUEST_ID, &request);
    test->state = requesting ? AppStateRequesting : AppStateNoBridge;
    furi_mutex_release(test->mutex);

    InputEvent event;
    for(bool processing = true; processing;) {
        if(furi_message_queue_get(event_queue, &event, 100) == FuriStatusOk) {
            if(event.type == InputTypeShort && event.key == InputKeyBack) {
                processing = false;
            }
        }
        view_port_update(view_port);
    }

    /* Unsubscribe before closing the record: a late event must not reach a
     * freed context. */
    network_set_event_callback(network, NULL, NULL);
    furi_record_close(RECORD_NETWORK);

    view_port_enabled_set(view_port, false);
    gui_remove_view_port(gui, view_port);
    furi_record_close(RECORD_GUI);
    view_port_free(view_port);
    furi_message_queue_free(event_queue);
    furi_mutex_free(test->mutex);
    free(test);

    return 0;
}

static size_t dns_build_query(uint8_t* buf, size_t cap, uint16_t txid, const char* name) {
    size_t need = 12 + strlen(name) + 2 + 4;
    if(cap < need) return 0;

    memset(buf, 0, 12);
    buf[0] = txid >> 8;
    buf[1] = txid & 0xFF;
    buf[2] = 0x01; /* recursion desired */
    buf[5] = 0x01; /* one question */

    size_t pos = 12;
    const char* label = name;
    while(*label) {
        const char* dot = strchr(label, '.');
        size_t len = dot ? (size_t)(dot - label) : strlen(label);
        if(len == 0 || len > 63) return 0;
        buf[pos++] = len;
        memcpy(&buf[pos], label, len);
        pos += len;
        label += len;
        if(*label == '.') label++;
    }
    buf[pos++] = 0;
    buf[pos++] = 0x00;
    buf[pos++] = 0x01; /* QTYPE A */
    buf[pos++] = 0x00;
    buf[pos++] = 0x01; /* QCLASS IN */
    return pos;
}

static bool dns_parse_response(
    const uint8_t* data,
    size_t size,
    uint16_t txid,
    char* ip,
    size_t ip_size,
    uint32_t* ttl) {
    if(size < 12) return false;
    if((((uint16_t)data[0] << 8) | data[1]) != txid) return false;
    uint16_t flags = ((uint16_t)data[2] << 8) | data[3];
    if((flags & 0x8000) == 0) return false; /* not a response */
    if((flags & 0x000F) != 0) return false; /* RCODE != NOERROR */
    uint16_t qdcount = ((uint16_t)data[4] << 8) | data[5];
    uint16_t ancount = ((uint16_t)data[6] << 8) | data[7];
    if(ancount == 0) return false;

    size_t pos = 12;
    for(uint16_t i = 0; i < qdcount; i++) {
        while(pos < size && data[pos] != 0 && (data[pos] & 0xC0) != 0xC0) {
            pos += (size_t)data[pos] + 1;
        }
        if(pos >= size) return false;
        pos += (data[pos] & 0xC0) == 0xC0 ? 2 : 1;
        pos += 4; /* QTYPE + QCLASS */
    }

    for(uint16_t i = 0; i < ancount; i++) {
        if(pos >= size) return false;
        if((data[pos] & 0xC0) == 0xC0) {
            pos += 2;
        } else {
            while(pos < size && data[pos] != 0) {
                pos += (size_t)data[pos] + 1;
            }
            pos++;
        }
        if(pos + 10 > size) return false;
        uint16_t type = ((uint16_t)data[pos] << 8) | data[pos + 1];
        uint16_t dns_class = ((uint16_t)data[pos + 2] << 8) | data[pos + 3];
        uint32_t rec_ttl = ((uint32_t)data[pos + 4] << 24) | ((uint32_t)data[pos + 5] << 16) |
                           ((uint32_t)data[pos + 6] << 8) | data[pos + 7];
        uint16_t rdlen = ((uint16_t)data[pos + 8] << 8) | data[pos + 9];
        pos += 10;
        if(pos + rdlen > size) return false;
        if(type == 1 && dns_class == 1 && rdlen == 4) {
            snprintf(ip, ip_size, "%u.%u.%u.%u", data[pos], data[pos + 1], data[pos + 2], data[pos + 3]);
            if(ttl) *ttl = rec_ttl;
            return true;
        }
        pos += rdlen;
    }
    return false;
}

static uint32_t http_parse_status(const uint8_t* data, size_t size) {
    if(size < 12) return 0;
    if(memcmp(data, "HTTP/1.", 7) != 0) return 0;
    uint32_t status = 0;
    for(size_t i = 9; i < 12; i++) {
        if(data[i] < '0' || data[i] > '9') return 0;
        status = status * 10 + (data[i] - '0');
    }
    return status;
}

static void ping_push_close(PingApp* app, uint32_t id) {
    if(id == 0) return;
    if(app->close_count < COUNT_OF(app->close_ids)) {
        app->close_ids[app->close_count++] = id;
    }
}

static void ping_record(
    PingApp* app,
    bool ok,
    uint32_t time_ms,
    uint32_t aux_ms,
    size_t rx_bytes,
    NetworkError error,
    const char* detail) {
    if(app->active_seq >= PROBE_COUNT) return;
    ProbeResult* result = &app->results[app->active_seq];
    result->done = true;
    result->ok = ok;
    result->time_ms = time_ms ? time_ms : 1;
    result->aux_ms = aux_ms;
    result->rx_bytes = rx_bytes;
    result->error = error;
    strlcpy(result->detail, detail, sizeof(result->detail));

    if(ok) {
        app->received++;
        app->total_ms += result->time_ms;
        if(app->received == 1 || result->time_ms < app->min_ms) app->min_ms = result->time_ms;
        if(result->time_ms > app->max_ms) app->max_ms = result->time_ms;
    } else if(error != NetworkErrorNone) {
        app->error = error;
    }
}

static void ping_probe_finish(PingApp* app) {
    app->probe_active = false;
    app->send_tcp_request = false;
    if(app->mode == ProbeModeTcp) {
        ping_push_close(app, app->cur_id);
    }
    app->active_seq++;
    app->start_probe = app->active_seq < PROBE_COUNT;
    if(app->active_seq >= PROBE_COUNT) {
        app->state = app->received ? RunStateDone : RunStateError;
        if(!app->received && app->error == NetworkErrorNone) app->error = NetworkErrorTimeout;
        if(app->socket_open) {
            ping_push_close(app, app->cur_id);
            app->socket_open = false;
        }
    }
}

static void ping_handle_dns_event(PingApp* app, const NetworkEvent* event) {
    switch(event->type) {
    /* Answer to network_connect(): event->state/error report the outcome,
     * event->resolved_ip (not used here) carries the peer address. */
    case NetworkEventConnected:
        if(app->state == RunStateOpening) {
            if(event->error == NetworkErrorNone && event->state == NetworkStateConnected) {
                app->state = RunStateProbing;
                app->start_probe = true;
                app->next_probe_tick = furi_get_tick();
            } else {
                app->state = RunStateError;
                app->error = event->error != NetworkErrorNone ? event->error :
                                                                NetworkErrorInternal;
                ping_push_close(app, app->cur_id);
                app->socket_open = false;
            }
        }
        break;
    case NetworkEventReceived:
        if(app->probe_active && event->data && event->size) {
            char ip[16];
            uint32_t ttl = 0;
            if(dns_parse_response(event->data, event->size, app->dns_txid, ip, sizeof(ip), &ttl)) {
                char detail[40];
                snprintf(detail, sizeof(detail), "A %s ttl=%lus", ip, (unsigned long)ttl);
                strlcpy(app->resolved_ip, ip, sizeof(app->resolved_ip));
                ping_record(
                    app,
                    true,
                    furi_get_tick() - app->started_tick,
                    0,
                    event->size,
                    NetworkErrorNone,
                    detail);
                ping_probe_finish(app);
            }
            /* Mismatched txid: a late reply to a lost probe, keep waiting. */
        }
        break;
    /* Ack for network_send(): only interesting when the datagram failed. */
    case NetworkEventSent:
        if(app->probe_active && event->error != NetworkErrorNone) {
            ping_record(app, false, 0, 0, 0, event->error, "");
            ping_probe_finish(app);
        }
        break;
    /* Socket died (peer/companion side) or close was acknowledged. */
    case NetworkEventStateChanged:
    case NetworkEventClosed:
        if(app->state == RunStateProbing && network_state_is_terminal(event->state)) {
            NetworkError error = event->error != NetworkErrorNone ? event->error :
                                                                    NetworkErrorNotConnected;
            if(app->probe_active) {
                ping_record(app, false, 0, 0, 0, error, "");
            }
            app->probe_active = false;
            app->start_probe = false;
            app->state = RunStateError;
            app->error = error;
            app->socket_open = false;
        }
        break;
    default:
        break;
    }
}

static void ping_handle_tcp_event(PingApp* app, const NetworkEvent* event) {
    if(!app->probe_active) return;

    switch(event->type) {
    case NetworkEventConnected:
        if(!app->tcp_request_sent) {
            if(event->error == NetworkErrorNone && event->state == NetworkStateConnected) {
                app->tcp_syn_ms = furi_get_tick() - app->started_tick;
                if(event->resolved_ip && event->resolved_ip[0]) {
                    strlcpy(app->resolved_ip, event->resolved_ip, sizeof(app->resolved_ip));
                }
                app->send_tcp_request = true;
            } else {
                ping_record(app, false, 0, 0, 0, event->error, "");
                ping_probe_finish(app);
            }
        }
        break;
    case NetworkEventReceived:
        /* First chunk of the response stops the clock; trailing chunks arrive
         * with probe_active already false and are dropped. */
        if(app->tcp_request_sent && event->data && event->size) {
            char detail[40];
            uint32_t status = http_parse_status(event->data, event->size);
            if(status) {
                snprintf(
                    detail,
                    sizeof(detail),
                    "HTTP %lu %.21s",
                    (unsigned long)status,
                    app->resolved_ip[0] ? app->resolved_ip : TARGET_NAME);
            } else {
                snprintf(
                    detail,
                    sizeof(detail),
                    "raw %.21s",
                    app->resolved_ip[0] ? app->resolved_ip : TARGET_NAME);
            }
            ping_record(
                app,
                true,
                furi_get_tick() - app->started_tick,
                app->tcp_syn_ms,
                event->size,
                NetworkErrorNone,
                detail);
            ping_probe_finish(app);
        }
        break;
    case NetworkEventSent:
        if(event->error != NetworkErrorNone) {
            ping_record(app, false, 0, 0, 0, event->error, "");
            ping_probe_finish(app);
        }
        break;
    case NetworkEventStateChanged:
    case NetworkEventClosed:
        if(network_state_is_terminal(event->state)) {
            NetworkError error = event->error != NetworkErrorNone ? event->error :
                                                                    NetworkErrorNotConnected;
            ping_record(app, false, 0, 0, 0, error, "");
            ping_probe_finish(app);
        }
        break;
    default:
        break;
    }
}

static void ping_handle_https_event(PingApp* app, const NetworkEvent* event) {
    if(!app->probe_active) return;
    /* HTTP requests produce exactly one terminal event; with no save_path the
     * body would also stream in as NetworkEventReceived (ignored here). */
    if(event->type != NetworkEventHttpResponse) return;

    if(event->error == NetworkErrorNone) {
        char detail[40];
        snprintf(detail, sizeof(detail), "HTTP %lu via TLS", (unsigned long)event->http_status);
        ping_record(
            app,
            true,
            furi_get_tick() - app->started_tick,
            0,
            event->size,
            NetworkErrorNone,
            detail);
    } else {
        ping_record(app, false, 0, 0, 0, event->error, "");
    }
    ping_probe_finish(app);
}

static void ping_event_callback(const NetworkEvent* event, void* context) {
    PingApp* app = context;

    furi_mutex_acquire(app->mutex, FuriWaitForever);
    if(event->connection_id == app->cur_id) {
        switch(app->mode) {
        case ProbeModeDns:
            ping_handle_dns_event(app, event);
            break;
        case ProbeModeTcp:
            ping_handle_tcp_event(app, event);
            break;
        case ProbeModeHttps:
            ping_handle_https_event(app, event);
            break;
        default:
            break;
        }
    }
    furi_mutex_release(app->mutex);
}

static void ping_start_run(PingApp* app, Network* network, ProbeMode mode) {
    furi_mutex_acquire(app->mutex, FuriWaitForever);
    uint32_t stale_id = app->socket_open || (app->mode == ProbeModeTcp && app->probe_active) ?
                            app->cur_id :
                            0;
    app->mode = mode;
    app->error = NetworkErrorNone;
    memset(app->results, 0, sizeof(app->results));
    app->active_seq = 0;
    app->probe_active = false;
    app->send_tcp_request = false;
    app->tcp_request_sent = false;
    app->sent = 0;
    app->received = 0;
    app->min_ms = 0;
    app->max_ms = 0;
    app->total_ms = 0;
    app->tcp_syn_ms = 0;
    app->resolved_ip[0] = '\0';
    app->socket_open = false;
    app->cur_id = ++app->id_counter;
    uint32_t run_id = app->cur_id;

    if(mode == ProbeModeDns) {
        app->state = RunStateOpening;
        app->start_probe = false;
        app->started_tick = furi_get_tick();
    } else {
        app->state = RunStateProbing;
        app->start_probe = true;
        app->next_probe_tick = furi_get_tick();
    }
    furi_mutex_release(app->mutex);

    if(stale_id) network_close(network, stale_id);

    if(mode == ProbeModeDns) {
        /* One UDP socket for the whole run. The call only queues the request:
         * the outcome comes back as NetworkEventConnected. */
        bool opened = network_connect(
            network, run_id, DNS_SERVER, DNS_PORT, NetworkProtocolUdp, PROBE_TIMEOUT_MS);
        furi_mutex_acquire(app->mutex, FuriWaitForever);
        if(opened) {
            app->socket_open = true;
        } else {
            app->state = RunStateNoBridge;
        }
        furi_mutex_release(app->mutex);
    }
}

static void ping_process(PingApp* app, Network* network) {
    uint32_t closes[COUNT_OF(app->close_ids)];
    uint32_t close_count;
    bool dns_send = false;
    bool head_send = false;
    bool tcp_connect = false;
    bool https_request = false;
    uint32_t action_id = 0;
    uint16_t txid = 0;

    furi_mutex_acquire(app->mutex, FuriWaitForever);
    uint32_t now = furi_get_tick();

    if(app->state == RunStateOpening &&
       now - app->started_tick > furi_ms_to_ticks(PROBE_TIMEOUT_MS)) {
        app->state = RunStateError;
        app->error = NetworkErrorTimeout;
        if(app->socket_open) {
            ping_push_close(app, app->cur_id);
            app->socket_open = false;
        }
    }

    if(app->probe_active) {
        uint32_t timeout_ms = app->mode == ProbeModeHttps ? HTTPS_TIMEOUT_MS : PROBE_TIMEOUT_MS;
        if(now - app->started_tick > furi_ms_to_ticks(timeout_ms)) {
            ping_record(app, false, 0, 0, 0, NetworkErrorTimeout, "");
            ping_probe_finish(app);
        }
    }

    if(app->send_tcp_request && app->probe_active) {
        app->send_tcp_request = false;
        app->tcp_request_sent = true;
        head_send = true;
        action_id = app->cur_id;
    }

    bool launch = app->state == RunStateProbing && app->start_probe && !app->probe_active &&
                  app->active_seq < PROBE_COUNT && now >= app->next_probe_tick;
    if(launch) {
        app->start_probe = false;
        app->probe_active = true;
        app->sent++;
        app->started_tick = now;
        app->next_probe_tick = now + furi_ms_to_ticks(PROBE_INTERVAL_MS);
        app->tcp_request_sent = false;
        app->tcp_syn_ms = 0;
        if(app->mode == ProbeModeDns) {
            app->dns_txid = (uint16_t)((now << 4) | app->active_seq);
            dns_send = true;
            action_id = app->cur_id;
            txid = app->dns_txid;
        } else {
            app->cur_id = ++app->id_counter;
            action_id = app->cur_id;
            if(app->mode == ProbeModeTcp) {
                tcp_connect = true;
            } else {
                https_request = true;
            }
        }
    }

    close_count = app->close_count;
    memcpy(closes, app->close_ids, close_count * sizeof(uint32_t));
    app->close_count = 0;
    furi_mutex_release(app->mutex);

    /* Fire-and-forget: the companion confirms each close with
     * NetworkEventClosed. */
    for(uint32_t i = 0; i < close_count; i++) {
        network_close(network, closes[i]);
    }

    /* Every network_* call below returns false only when there is no live
     * companion session; probe results arrive via ping_event_callback. */
    bool bridge_ok = true;
    if(dns_send) {
        /* One datagram per probe over the open UDP socket
         * (payload <= NETWORK_MAX_DATA_SIZE); reply = NetworkEventReceived. */
        uint8_t query[64];
        size_t query_size = dns_build_query(query, sizeof(query), txid, TARGET_NAME);
        bridge_ok = query_size && network_send(network, action_id, query, query_size);
    } else if(head_send) {
        /* Raw bytes over the connected TCP socket - the service does not
         * interpret them, HTTP framing is this app's own. */
        bridge_ok = network_send(
            network, action_id, (const uint8_t*)TCP_HEAD_REQUEST, strlen(TCP_HEAD_REQUEST));
    } else if(tcp_connect) {
        /* Fresh client-assigned id per probe: each probe is its own TCP
         * connection, timed from here to NetworkEventConnected. */
        bridge_ok = network_connect(
            network, action_id, TARGET_NAME, TCP_PORT, NetworkProtocolTcp, PROBE_TIMEOUT_MS);
    } else if(https_request) {
        /* Full HTTP stack on the companion; concludes with
         * NetworkEventHttpResponse for this request id. */
        const NetworkHttpRequest request = {
            .method = NetworkHttpMethodHead,
            .url = HTTPS_URL,
            .timeout_ms = HTTPS_TIMEOUT_MS,
        };
        bridge_ok = network_http_request(network, action_id, &request);
    }

    if(!bridge_ok) {
        furi_mutex_acquire(app->mutex, FuriWaitForever);
        app->state = RunStateNoBridge;
        app->probe_active = false;
        app->start_probe = false;
        app->socket_open = false;
        furi_mutex_release(app->mutex);
    }
}

static const char* ping_mode_title(ProbeMode mode) {
    switch(mode) {
    case ProbeModeDns:
        return "< DNS/UDP 1.1.1.1:53 >";
    case ProbeModeTcp:
        return "< TCP + raw HTTP :80 >";
    case ProbeModeHttps:
        return "< HTTPS request >";
    default:
        return "";
    }
}

static void ping_render_callback(Canvas* canvas, void* context) {
    PingApp* app = context;
    furi_mutex_acquire(app->mutex, FuriWaitForever);

    char line[64];
    canvas_set_font(canvas, FontSecondary);
    canvas_draw_str_aligned(canvas, 64, 8, AlignCenter, AlignBottom, ping_mode_title(app->mode));

    uint32_t cursor = app->active_seq;
    if(app->probe_active && cursor < PROBE_COUNT) {
        cursor++;
    }
    uint32_t first = cursor > 2 ? cursor - 2 : 0;
    uint32_t visible = cursor - first;
    if(visible > 2) visible = 2;

    for(uint32_t slot = 0; slot < visible; slot++) {
        uint32_t i = first + slot;
        const ProbeResult* result = &app->results[i];
        uint8_t y = 21 + slot * 20;

        if(result->done && result->ok) {
            switch(app->mode) {
            case ProbeModeTcp:
                snprintf(
                    line,
                    sizeof(line),
                    "seq=%lu syn=%lu http=%lums",
                    (unsigned long)i,
                    (unsigned long)result->aux_ms,
                    (unsigned long)result->time_ms);
                break;
            case ProbeModeDns:
                snprintf(
                    line,
                    sizeof(line),
                    "seq=%lu time=%lums rx=%uB",
                    (unsigned long)i,
                    (unsigned long)result->time_ms,
                    (unsigned)result->rx_bytes);
                break;
            default:
                snprintf(
                    line,
                    sizeof(line),
                    "seq=%lu time=%lums",
                    (unsigned long)i,
                    (unsigned long)result->time_ms);
                break;
            }
            canvas_draw_str(canvas, 0, y, line);
            canvas_draw_str(canvas, 0, y + 9, result->detail);
        } else if(result->done) {
            snprintf(line, sizeof(line), "seq=%lu lost", (unsigned long)i);
            canvas_draw_str(canvas, 0, y, line);
            canvas_draw_str(canvas, 0, y + 9, network_error_to_string(result->error));
        } else if(app->probe_active && app->active_seq == i) {
            snprintf(line, sizeof(line), "seq=%lu", (unsigned long)i);
            canvas_draw_str(canvas, 0, y, line);
            if(app->mode == ProbeModeDns) {
                snprintf(line, sizeof(line), "txid=0x%04X...", app->dns_txid);
            } else if(app->mode == ProbeModeTcp) {
                if(app->tcp_request_sent) {
                    snprintf(
                        line, sizeof(line), "syn=%lums wait rsp", (unsigned long)app->tcp_syn_ms);
                } else {
                    snprintf(line, sizeof(line), "connecting...");
                }
            } else {
                snprintf(line, sizeof(line), "TLS handshake...");
            }
            canvas_draw_str(canvas, 0, y + 9, line);
        }
    }

    if(app->state == RunStateNoBridge) {
        canvas_draw_str(canvas, 0, 63, "No USB/BLE connection");
    } else if(app->state == RunStateOpening) {
        canvas_draw_str(canvas, 0, 63, "Opening UDP socket...");
    } else if(app->state == RunStateDone || app->state == RunStateError) {
        uint32_t loss = ((PROBE_COUNT - app->received) * 100) / PROBE_COUNT;
        if(app->received) {
            snprintf(
                line,
                sizeof(line),
                "%lu/%u rx %lu%% loss %lu/%lu/%lums",
                (unsigned long)app->received,
                PROBE_COUNT,
                (unsigned long)loss,
                (unsigned long)app->min_ms,
                (unsigned long)(app->total_ms / app->received),
                (unsigned long)app->max_ms);
        } else {
            snprintf(
                line,
                sizeof(line),
                "0/%u rx: %s",
                PROBE_COUNT,
                network_error_to_string(app->error));
        }
        canvas_draw_str(canvas, 0, 63, line);
    } else {
        snprintf(
            line,
            sizeof(line),
            "%.21s %lu/%u",
            app->resolved_ip[0] ? app->resolved_ip : TARGET_NAME,
            (unsigned long)app->sent,
            PROBE_COUNT);
        canvas_draw_str(canvas, 0, 63, line);
    }

    furi_mutex_release(app->mutex);
}

int32_t network_ping_app(void* p) {
    UNUSED(p);

    PingApp* app = malloc(sizeof(PingApp));
    memset(app, 0, sizeof(PingApp));
    app->mutex = furi_mutex_alloc(FuriMutexTypeNormal);
    app->state = RunStateIdle;
    app->id_counter = CONNECTION_ID_BASE;

    FuriMessageQueue* event_queue = furi_message_queue_alloc(8, sizeof(InputEvent));
    Network* network = furi_record_open(RECORD_NETWORK);
    network_set_event_callback(network, ping_event_callback, app);

    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, ping_render_callback, app);
    view_port_input_callback_set(view_port, ping_input_callback, event_queue);

    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);

    ping_start_run(app, network, ProbeModeDns);

    InputEvent event;
    for(bool processing = true; processing;) {
        if(furi_message_queue_get(event_queue, &event, 100) == FuriStatusOk &&
           event.type == InputTypeShort) {
            furi_mutex_acquire(app->mutex, FuriWaitForever);
            ProbeMode mode = app->mode;
            furi_mutex_release(app->mutex);

            if(event.key == InputKeyBack) {
                processing = false;
            } else if(event.key == InputKeyOk) {
                ping_start_run(app, network, mode);
            } else if(event.key == InputKeyLeft || event.key == InputKeyRight) {
                uint32_t step = event.key == InputKeyRight ? 1 : ProbeModeCount - 1;
                ping_start_run(app, network, (ProbeMode)((mode + step) % ProbeModeCount));
            }
        }

        ping_process(app, network);
        view_port_update(view_port);
    }

    furi_mutex_acquire(app->mutex, FuriWaitForever);
    if(app->socket_open || app->probe_active) {
        ping_push_close(app, app->cur_id);
        app->socket_open = false;
    }
    uint32_t close_count = app->close_count;
    uint32_t closes[COUNT_OF(app->close_ids)];
    memcpy(closes, app->close_ids, close_count * sizeof(uint32_t));
    app->close_count = 0;
    furi_mutex_release(app->mutex);
    for(uint32_t i = 0; i < close_count; i++) {
        network_close(network, closes[i]);
    }

    /* Unsubscribe before closing the record so late events cannot reach a
     * freed context. */
    network_set_event_callback(network, NULL, NULL);
    furi_record_close(RECORD_NETWORK);

    view_port_enabled_set(view_port, false);
    gui_remove_view_port(gui, view_port);
    furi_record_close(RECORD_GUI);
    view_port_free(view_port);
    furi_message_queue_free(event_queue);
    furi_mutex_free(app->mutex);
    free(app);

    return 0;
}

static void ws_test_reset(WsTestApp* app) {
    app->error = NetworkErrorNone;
    app->tx_bytes = 0;
    app->rx_bytes = 0;
    app->start_tick = 0;
    app->elapsed_ticks = 0;
    app->received[0] = '\0';
    app->got_echo = false;
    app->send_requested = false;
    app->close_requested = false;

    const char* name = furi_hal_version_get_name_ptr();
    strlcpy(app->name, (name && name[0]) ? name : "Flipper", sizeof(app->name));
}

static void ws_test_start(WsTestApp* app, Network* network) {
    furi_mutex_acquire(app->mutex, FuriWaitForever);
    ws_test_reset(app);
    app->state = WsConnecting;
    uint32_t id = app->conn_id;
    furi_mutex_release(app->mutex);

    /* DNS+TCP+TLS+upgrade all happen on the companion; the handshake result
     * arrives as NetworkEventConnected. NULL = no extra handshake headers.
     * false = no live companion session. */
    bool opened = network_websocket_open(network, id, WS_URL, NULL, WS_TIMEOUT_MS);
    if(!opened) {
        furi_mutex_acquire(app->mutex, FuriWaitForever);
        app->state = WsNoBridge;
        furi_mutex_release(app->mutex);
    }
}

static void ws_test_event_callback(const NetworkEvent* event, void* context) {
    WsTestApp* app = context;

    furi_mutex_acquire(app->mutex, FuriWaitForever);
    if(event->connection_id != app->conn_id) {
        furi_mutex_release(app->mutex);
        return;
    }

    switch(event->type) {
    /* Handshake answer for network_websocket_open(). */
    case NetworkEventConnected:
        if(event->error == NetworkErrorNone && event->state == NetworkStateConnected) {
            app->send_requested = true;
        } else {
            app->state = WsError;
            app->error = event->error;
        }
        break;
    /* One event per inbound frame. event->data is valid only during the
     * callback - copy it out. event->binary marks binary frames (unused: the
     * echo comes back as text). */
    case NetworkEventReceived:
        if(event->data && event->size) {
            app->rx_bytes += event->size;
            size_t copy = event->size < sizeof(app->received) - 1 ? event->size :
                                                                    sizeof(app->received) - 1;
            memcpy(app->received, event->data, copy);
            app->received[copy] = '\0';

            if(!app->got_echo && event->size == app->tx_bytes &&
               memcmp(event->data, app->name, app->tx_bytes) == 0) {
                app->got_echo = true;
                app->elapsed_ticks = furi_get_tick() - app->start_tick;
                app->state = WsDone;
                app->close_requested = true;
            }
        }
        break;
    /* Ack for network_websocket_send(); error set if the frame was not sent. */
    case NetworkEventSent:
        if(event->error != NetworkErrorNone) {
            app->state = WsError;
            app->error = event->error;
        }
        break;
    /* Connection dropped by the peer/companion, or our close was confirmed. */
    case NetworkEventStateChanged:
    case NetworkEventClosed:
        if(app->state != WsDone && app->state != WsError) {
            app->state = app->got_echo ? WsDone : WsError;
            if(!app->got_echo && app->error == NetworkErrorNone) {
                app->error = event->error == NetworkErrorNone ? NetworkErrorNotConnected :
                                                                event->error;
            }
        }
        break;
    case NetworkEventHttpResponse:
        break;
    }
    furi_mutex_release(app->mutex);
}

static void ws_test_draw_callback(Canvas* canvas, void* context) {
    WsTestApp* app = context;
    furi_mutex_acquire(app->mutex, FuriWaitForever);

    char line[64];

    canvas_set_font(canvas, FontPrimary);
    canvas_draw_str_aligned(canvas, 64, 10, AlignCenter, AlignBottom, "WS echo test");

    canvas_set_font(canvas, FontSecondary);
    const char* status = "Starting...";
    switch(app->state) {
    case WsNoBridge:
        status = "No USB/BLE connection";
        break;
    case WsConnecting:
        status = "Connecting...";
        break;
    case WsWaiting:
        status = "Waiting for echo...";
        break;
    case WsDone:
        status = "Echo OK, closed";
        break;
    case WsError:
        status = network_error_to_string(app->error);
        break;
    default:
        break;
    }
    canvas_draw_str_aligned(canvas, 0, 22, AlignLeft, AlignBottom, status);

    snprintf(line, sizeof(line), "TX: %lu bytes", (unsigned long)app->tx_bytes);
    canvas_draw_str_aligned(canvas, 0, 33, AlignLeft, AlignBottom, line);

    snprintf(
        line,
        sizeof(line),
        "RX: %lu bytes  %lu ms",
        (unsigned long)app->rx_bytes,
        (unsigned long)app->elapsed_ticks);
    canvas_draw_str_aligned(canvas, 0, 44, AlignLeft, AlignBottom, line);

    if(app->received[0]) {
        snprintf(line, sizeof(line), "< %.60s", app->received);
        canvas_draw_str_aligned(canvas, 0, 55, AlignLeft, AlignBottom, line);
    }

    canvas_draw_str_aligned(canvas, 0, 64, AlignLeft, AlignBottom, "OK: retry  Back: exit");

    furi_mutex_release(app->mutex);
}

int32_t network_websocket_app(void* p) {
    UNUSED(p);

    WsTestApp* app = malloc(sizeof(WsTestApp));
    memset(app, 0, sizeof(WsTestApp));
    app->mutex = furi_mutex_alloc(FuriMutexTypeNormal);
    app->state = WsInit;
    app->conn_id = WS_BASE_ID;

    FuriMessageQueue* event_queue = furi_message_queue_alloc(8, sizeof(InputEvent));

    Network* network = furi_record_open(RECORD_NETWORK);
    network_set_event_callback(network, ws_test_event_callback, app);

    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, ws_test_draw_callback, app);
    view_port_input_callback_set(view_port, ws_test_input_callback, event_queue);

    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);

    ws_test_start(app, network);

    InputEvent event;
    for(bool processing = true; processing;) {
        if(furi_message_queue_get(event_queue, &event, 100) == FuriStatusOk) {
            if(event.type == InputTypeShort) {
                if(event.key == InputKeyBack) {
                    processing = false;
                } else if(event.key == InputKeyOk) {
                    furi_mutex_acquire(app->mutex, FuriWaitForever);
                    app->restart_requested = true;
                    furi_mutex_release(app->mutex);
                }
            }
        }

        furi_mutex_acquire(app->mutex, FuriWaitForever);
        bool do_send = app->send_requested;
        app->send_requested = false;
        bool do_close = app->close_requested;
        app->close_requested = false;
        bool do_restart = app->restart_requested;
        app->restart_requested = false;
        uint32_t id = app->conn_id;
        if(do_send) {
            app->start_tick = furi_get_tick();
            app->tx_bytes = strlen(app->name);
            app->state = WsWaiting;
        }
        furi_mutex_release(app->mutex);

        if(do_send) {
            /* Text frame (binary = false), payload <= NETWORK_MAX_DATA_SIZE.
             * Delivery is confirmed by NetworkEventSent. */
            network_websocket_send(network, id, (const uint8_t*)app->name, strlen(app->name), false);
        }

        if(do_close) {
            network_close(network, id);
        }

        if(do_restart) {
            network_close(network, id);
            /* Never reuse a closed connection id: bump it so events from the
             * old connection fail the conn_id check in the callback. */
            furi_mutex_acquire(app->mutex, FuriWaitForever);
            app->conn_id++;
            furi_mutex_release(app->mutex);
            ws_test_start(app, network);
        }

        view_port_update(view_port);
    }

    /* Close the (possibly already closed) connection, then unsubscribe before
     * releasing the record so late events cannot reach a freed context. */
    network_close(network, app->conn_id);
    network_set_event_callback(network, NULL, NULL);
    furi_record_close(RECORD_NETWORK);

    view_port_enabled_set(view_port, false);
    gui_remove_view_port(gui, view_port);
    furi_record_close(RECORD_GUI);
    view_port_free(view_port);
    furi_message_queue_free(event_queue);
    furi_mutex_free(app->mutex);
    free(app);

    return 0;
}

uint16_t mf_plus_get_admin_key_address(MfPlusAdminKeyType type) {
    for(size_t i = 0; i < COUNT_OF(mf_plus_admin_key_addresses); i++) {
        if(mf_plus_admin_key_addresses[i].type == type) {
            return mf_plus_admin_key_addresses[i].address;
        }
    }
    furi_crash("Invalid MfPlusAdminKeyType");
}

bool mf_plus_admin_key_type_from_address(uint16_t address, MfPlusAdminKeyType* type) {
    for(size_t i = 0; i < COUNT_OF(mf_plus_admin_key_addresses); i++) {
        if(mf_plus_admin_key_addresses[i].address == address) {
            *type = mf_plus_admin_key_addresses[i].type;
            return true;
        }
    }
    return false;
}

static void mf_plus_key_cache_file_path(const uint8_t* uid, size_t uid_len, FuriString* path) {
    furi_string_printf(path, "%s/", MF_PLUS_KEY_CACHE_FOLDER);
    for(size_t i = 0; i < uid_len; i++) {
        furi_string_cat_printf(path, "%02X", uid[i]);
    }
    furi_string_cat_printf(path, "%s", MF_PLUS_KEY_CACHE_EXTENSION);
}

void mf_plus_key_cache_free(MfPlusKeyCache* instance) {
    furi_assert(instance);

    free(instance);
}

void mf_plus_key_cache_reset(MfPlusKeyCache* instance) {
    furi_assert(instance);

    // Only the masks gate the getters, so clearing them is enough to invalidate stale key bytes.
    instance->key_a_mask = 0;
    instance->key_b_mask = 0;
    instance->admin_key_mask = 0;
}

bool mf_plus_key_cache_save(const MfPlusData* data) {
    furi_assert(data);

    // Nothing recovered -> nothing worth caching (avoids leaving empty cache files behind).
    if((data->key_a_mask == 0) && (data->key_b_mask == 0) && (data->admin_key_mask == 0)) {
        return true;
    }

    size_t uid_len = 0;
    const uint8_t* uid = mf_plus_get_uid(data, &uid_len);
    FuriString* file_path = furi_string_alloc();
    mf_plus_key_cache_file_path(uid, uid_len, file_path);

    Storage* storage = furi_record_open(RECORD_STORAGE);
    FlipperFormat* ff = flipper_format_buffered_file_alloc(storage);

    FuriString* temp_str = furi_string_alloc();
    uint64_t admin_mask = data->admin_key_mask;
    bool save_success = false;
    do {
        if(!storage_simply_mkdir(storage, MF_PLUS_KEY_CACHE_FOLDER)) break;
        if(!storage_simply_remove(storage, furi_string_get_cstr(file_path))) break;
        if(!flipper_format_buffered_file_open_always(ff, furi_string_get_cstr(file_path))) break;

        if(!flipper_format_write_header_cstr(
               ff, mf_plus_key_cache_file_header, mf_plus_key_cache_file_version))
            break;
        if(!flipper_format_write_string_cstr(
               ff, "Mifare Plus type", mf_plus_get_device_name(data, NfcDeviceNameTypeShort)))
            break;
        if(!flipper_format_write_hex_uint64(ff, "Key A map", &data->key_a_mask, 1)) break;
        if(!flipper_format_write_hex_uint64(ff, "Key B map", &data->key_b_mask, 1)) break;
        if(!flipper_format_write_hex_uint64(ff, "Admin map", &admin_mask, 1)) break;

        bool key_save_success = true;
        for(size_t i = 0; (i < MF_PLUS_MAX_SECTORS) && key_save_success; i++) {
            if(FURI_BIT(data->key_a_mask, i)) {
                furi_string_printf(temp_str, "Key A sector %d", i);
                key_save_success = flipper_format_write_hex(
                    ff, furi_string_get_cstr(temp_str), data->key_a[i].data, MF_PLUS_KEY_SIZE);
            }
            if(!key_save_success) break;
            if(FURI_BIT(data->key_b_mask, i)) {
                furi_string_printf(temp_str, "Key B sector %d", i);
                key_save_success = flipper_format_write_hex(
                    ff, furi_string_get_cstr(temp_str), data->key_b[i].data, MF_PLUS_KEY_SIZE);
            }
        }
        for(size_t i = 0; (i < MfPlusAdminKeyNum) && key_save_success; i++) {
            if(FURI_BIT(data->admin_key_mask, i)) {
                furi_string_printf(temp_str, "Admin key %d", i);
                key_save_success = flipper_format_write_hex(
                    ff, furi_string_get_cstr(temp_str), data->admin_key[i].data, MF_PLUS_KEY_SIZE);
            }
        }
        save_success = key_save_success;
    } while(false);

    flipper_format_free(ff);
    furi_string_free(temp_str);
    furi_string_free(file_path);
    furi_record_close(RECORD_STORAGE);

    return save_success;
}

bool mf_plus_key_cache_load(MfPlusKeyCache* instance, const uint8_t* uid, size_t uid_len) {
    furi_assert(instance);
    furi_assert(uid);

    mf_plus_key_cache_reset(instance);

    FuriString* file_path = furi_string_alloc();
    mf_plus_key_cache_file_path(uid, uid_len, file_path);

    Storage* storage = furi_record_open(RECORD_STORAGE);
    FlipperFormat* ff = flipper_format_buffered_file_alloc(storage);

    FuriString* temp_str = furi_string_alloc();
    uint64_t admin_mask = 0;
    bool load_success = false;
    do {
        if(!flipper_format_buffered_file_open_existing(ff, furi_string_get_cstr(file_path))) break;

        uint32_t version = 0;
        if(!flipper_format_read_header(ff, temp_str, &version)) break;
        if(furi_string_cmp_str(temp_str, mf_plus_key_cache_file_header)) break;
        if(version != mf_plus_key_cache_file_version) break;

        if(!flipper_format_read_hex_uint64(ff, "Key A map", &instance->key_a_mask, 1)) break;
        if(!flipper_format_read_hex_uint64(ff, "Key B map", &instance->key_b_mask, 1)) break;
        if(!flipper_format_read_hex_uint64(ff, "Admin map", &admin_mask, 1)) break;
        instance->admin_key_mask = (uint8_t)admin_mask;

        bool key_read_success = true;
        for(size_t i = 0; (i < MF_PLUS_MAX_SECTORS) && key_read_success; i++) {
            if(FURI_BIT(instance->key_a_mask, i)) {
                furi_string_printf(temp_str, "Key A sector %d", i);
                key_read_success = flipper_format_read_hex(
                    ff, furi_string_get_cstr(temp_str), instance->key_a[i].data, MF_PLUS_KEY_SIZE);
            }
            if(!key_read_success) break;
            if(FURI_BIT(instance->key_b_mask, i)) {
                furi_string_printf(temp_str, "Key B sector %d", i);
                key_read_success = flipper_format_read_hex(
                    ff, furi_string_get_cstr(temp_str), instance->key_b[i].data, MF_PLUS_KEY_SIZE);
            }
        }
        for(size_t i = 0; (i < MfPlusAdminKeyNum) && key_read_success; i++) {
            if(FURI_BIT(instance->admin_key_mask, i)) {
                furi_string_printf(temp_str, "Admin key %d", i);
                key_read_success = flipper_format_read_hex(
                    ff,
                    furi_string_get_cstr(temp_str),
                    instance->admin_key[i].data,
                    MF_PLUS_KEY_SIZE);
            }
        }
        load_success = key_read_success;
    } while(false);

    // A partially-parsed file must not surface half a keyset; drop everything on any error.
    if(!load_success) mf_plus_key_cache_reset(instance);

    flipper_format_buffered_file_close(ff);
    flipper_format_free(ff);
    furi_string_free(temp_str);
    furi_string_free(file_path);
    furi_record_close(RECORD_STORAGE);

    return load_success;
}

bool mf_plus_key_cache_get_sector_key(
    const MfPlusKeyCache* instance,
    uint8_t sector,
    MfPlusKeyType key_type,
    MfPlusKey* out_key) {
    furi_assert(instance);
    furi_assert(out_key);

    if(sector >= MF_PLUS_MAX_SECTORS) return false;

    if(key_type == MfPlusKeyTypeB) {
        if(!FURI_BIT(instance->key_b_mask, sector)) return false;
        *out_key = instance->key_b[sector];
    } else {
        if(!FURI_BIT(instance->key_a_mask, sector)) return false;
        *out_key = instance->key_a[sector];
    }

    return true;
}

bool mf_plus_key_cache_get_admin_key(
    const MfPlusKeyCache* instance,
    MfPlusAdminKeyType admin_type,
    MfPlusKey* out_key) {
    furi_assert(instance);
    furi_assert(out_key);

    if(admin_type >= MfPlusAdminKeyNum) return false;
    if(!FURI_BIT(instance->admin_key_mask, admin_type)) return false;
    *out_key = instance->admin_key[admin_type];

    return true;
}

static void nfc_scene_mf_plus_add_show_keys(NfcApp* instance) {
    if(!nfc_scene_mf_plus_is_sl3(instance)) return;
    submenu_add_item(
        instance->submenu,
        "Show Keys",
        SubmenuIndexShowKeys,
        nfc_protocol_support_common_submenu_callback,
        instance);
}

static void nfc_scene_mf_plus_saved_menu_on_enter(NfcApp* instance) {
    if(nfc_scene_mf_plus_is_sl3(instance)) {
        submenu_change_item_label(
            instance->submenu, SubmenuIndexCommonWrite, "Write to Initial Card");
        submenu_add_item(
            instance->submenu,
            "Update from Initial Card",
            SubmenuIndexUpdate,
            nfc_protocol_support_common_submenu_callback,
            instance);
    }
    nfc_scene_mf_plus_add_show_keys(instance);
}

static bool nfc_scene_mf_plus_menu_on_event(NfcApp* instance, SceneManagerEvent event) {
    if(event.type == SceneManagerEventTypeCustom) {
        if(event.event == SubmenuIndexShowKeys) {
            scene_manager_next_scene(instance->scene_manager, NfcSceneMfPlusShowKeys);
            return true;
        } else if(event.event == SubmenuIndexUpdate) {
            scene_manager_next_scene(instance->scene_manager, NfcSceneMfPlusUpdateInitial);
            return true;
        }
    }
    return false;
}

static bool nfc_scene_read_on_event_mf_plus(NfcApp* instance, SceneManagerEvent event) {
    // Auto-continue an SL3 identity read into the dictionary attack (mirrors MIFARE Classic).
    if(event.type == SceneManagerEventTypeCustom &&
       event.event == NfcCustomEventPollerIncomplete) {
        scene_manager_next_scene(instance->scene_manager, NfcSceneMfPlusDictAttack);
        return true;
    }
    return false;
}

static NfcCommand nfc_scene_write_poller_callback_mf_plus(NfcGenericEvent event, void* context) {
    furi_assert(context);
    furi_assert(event.protocol == NfcProtocolMfPlus);
    furi_assert(event.event_data);
    NfcApp* instance = context;
    const MfPlusPollerEvent* mfp_event = event.event_data;
    const MfPlusData* write_data = nfc_device_get_data(instance->nfc_device, NfcProtocolMfPlus);

    NfcCommand command = NfcCommandContinue;

    switch(mfp_event->type) {
    case MfPlusPollerEventTypeRequestMode: {
        // Only write the exact card the dump came from: match the UID before entering write mode.
        const MfPlusData* tag_data = nfc_poller_get_data(instance->poller);
        size_t tag_uid_len = 0, dump_uid_len = 0;
        const uint8_t* tag_uid = mf_plus_get_uid(tag_data, &tag_uid_len);
        const uint8_t* dump_uid = mf_plus_get_uid(write_data, &dump_uid_len);
        if(tag_uid_len == dump_uid_len && memcmp(tag_uid, dump_uid, tag_uid_len) == 0) {
            mfp_event->data->mode_request.mode = MfPlusPollerModeWrite;
        } else {
            furi_string_set(instance->text_box_store, "Use the source\ncard only");
            view_dispatcher_send_custom_event(instance->view_dispatcher, NfcCustomEventWrongCard);
            command = NfcCommandStop;
        }
        break;
    }
    case MfPlusPollerEventTypeRequestWriteSector: {
        // Provide the sector's recovered AES key (prefer A) so the poller can authenticate to write.
        const uint8_t sector = mfp_event->data->write_sector_request.sector;
        if(mf_plus_is_key_found(write_data, sector, MfPlusKeyTypeA)) {
            mfp_event->data->write_sector_request.key = write_data->key_a[sector];
            mfp_event->data->write_sector_request.key_type = MfPlusKeyTypeA;
            mfp_event->data->write_sector_request.key_provided = true;
        } else if(mf_plus_is_key_found(write_data, sector, MfPlusKeyTypeB)) {
            mfp_event->data->write_sector_request.key = write_data->key_b[sector];
            mfp_event->data->write_sector_request.key_type = MfPlusKeyTypeB;
            mfp_event->data->write_sector_request.key_provided = true;
        }
        break;
    }
    case MfPlusPollerEventTypeRequestWriteBlock: {
        // Provide the block only if the dump captured it.
        const uint16_t block_num = mfp_event->data->write_block_request.block_num;
        if(mf_plus_is_block_read(write_data, block_num)) {
            mfp_event->data->write_block_request.block = write_data->block[block_num];
            mfp_event->data->write_block_request.block_provided = true;
        }
        break;
    }
    case MfPlusPollerEventTypeWriteSuccess:
        view_dispatcher_send_custom_event(instance->view_dispatcher, NfcCustomEventPollerSuccess);
        command = NfcCommandStop;
        break;
    case MfPlusPollerEventTypeWriteFailed:
        view_dispatcher_send_custom_event(instance->view_dispatcher, NfcCustomEventPollerFailure);
        command = NfcCommandStop;
        break;
    default:
        break;
    }

    return command;
}

static void nfc_scene_write_on_enter_mf_plus(NfcApp* instance) {
    instance->poller = nfc_poller_alloc(instance->nfc, NfcProtocolMfPlus);
    nfc_poller_start(instance->poller, nfc_scene_write_poller_callback_mf_plus, instance);
    furi_string_set(instance->text_box_store, "Use the source\ncard only");
}

static bool nfc_scene_save_name_on_event_mf_plus(NfcApp* instance, SceneManagerEvent event) {
    bool consumed = false;

    if(event.type == SceneManagerEventTypeCustom && event.event == NfcCustomEventTextInputDone) {
        if(nfc_scene_mf_plus_is_sl3(instance)) {
            mf_plus_key_cache_save(nfc_device_get_data(instance->nfc_device, NfcProtocolMfPlus));
        }
        consumed = true;
    }

    return consumed;
}

static void nfc_render_mf_plus_recovery_stats(const MfPlusData* data, FuriString* str) {
    if(data->security_level != MfPlusSecurityLevel3) return;

    const uint8_t sectors_total = mf_plus_get_sector_count(data->size);
    uint8_t sectors_read = 0;
    uint8_t keys_found = 0;
    mf_plus_get_read_sectors_and_keys(data, &sectors_read, &keys_found);

    furi_string_cat_printf(str, "\nKeys Found: %u/%u", keys_found, sectors_total * 2);
    furi_string_cat_printf(str, "\nSectors Read: %u/%u", sectors_read, sectors_total);
}

static void nfc_render_mf_plus_hex_or_unknown(
    const uint8_t* bytes,
    size_t len,
    bool known,
    FuriString* str) {
    for(size_t i = 0; i < len; i++) {
        if(known) {
            furi_string_cat_printf(str, "%02X", bytes[i]);
        } else {
            furi_string_cat(str, "??");
        }
        if((i % 2) == 1 && i + 1 < len) furi_string_cat(str, " ");
    }
}

static void nfc_render_mf_plus_blocks(const MfPlusData* data, FuriString* str) {
    const uint8_t sectors = mf_plus_get_sector_count(data->size);
    if(sectors == 0) return;
    furi_string_cat(str, "\e#Blocks\n");
    for(uint8_t s = 0; s < sectors; s++) {
        const uint16_t first = mf_plus_sector_get_first_block(s);
        const uint16_t trailer = first + mf_plus_sector_get_block_count(s) - 1;
        for(uint16_t b = first; b <= trailer; b++) {
            // Block number on its own line, hex below -- a 16-byte block then wraps to two even
            // 2-byte-group lines instead of colliding with the "N:" prefix.
            furi_string_cat_printf(str, "%u:\n", b);
            if(b == trailer) {
                nfc_render_mf_plus_hex_or_unknown(
                    data->key_a[s].data,
                    MF_PLUS_KEY_SIZE,
                    mf_plus_is_key_found(data, s, MfPlusKeyTypeA),
                    str);
                furi_string_cat(str, " ");
                nfc_render_mf_plus_hex_or_unknown(
                    &data->block[b].data[6], 4, mf_plus_is_block_read(data, b), str);
                furi_string_cat(str, " ");
                nfc_render_mf_plus_hex_or_unknown(
                    data->key_b[s].data,
                    MF_PLUS_KEY_SIZE,
                    mf_plus_is_key_found(data, s, MfPlusKeyTypeB),
                    str);
            } else {
                nfc_render_mf_plus_hex_or_unknown(
                    data->block[b].data, MF_PLUS_BLOCK_SIZE, mf_plus_is_block_read(data, b), str);
            }
            furi_string_cat(str, "\n");
        }
    }
}

void nfc_render_mf_plus_dump(const MfPlusData* data, FuriString* str) {
    if(data->security_level != MfPlusSecurityLevel3) {
        furi_string_cat(str, "No block data: only an SL3 card exposes keys/blocks here.\n");
        return;
    }

    // The full dump is several KB. Reserve it in one shot so the many furi_string_cat calls below
    // don't grow the buffer by doubling -- that transient ~2x realloc can fail on the memory-tight
    // NFC thread (~30 KB free), which showed up as intermittent OOM when opening this view. ~64
    // bytes/block comfortably covers a labelled data block; trailers cost more but are outnumbered.
    furi_string_reserve(str, (size_t)mf_plus_get_block_count(data->size) * 64 + 2048);

    nfc_render_mf_plus_blocks(data, str);

    furi_string_cat(str, "\n\e#Admin Keys\n");
    for(uint8_t a = 0; a < MfPlusAdminKeyNum; a++) {
        const MfPlusAdminKeyType type = (MfPlusAdminKeyType)a;
        furi_string_cat_printf(str, "%s:\n", mf_plus_get_admin_key_name(type));
        nfc_render_mf_plus_hex_or_unknown(
            data->admin_key[a].data, MF_PLUS_KEY_SIZE, mf_plus_is_admin_key_found(data, type), str);
        furi_string_cat(str, "\n");
    }

    furi_string_cat(str, "\n\e#Config Blocks\n");
    for(uint8_t c = 0; c < MF_PLUS_CONFIG_BLOCK_NUM; c++) {
        furi_string_cat_printf(str, "B00%u:", c);
        nfc_render_mf_plus_hex_or_unknown(
            data->config_block[c].data,
            MF_PLUS_BLOCK_SIZE,
            mf_plus_is_config_block_read(data, c),
            str);
        furi_string_cat(str, "\n");
    }

    if(data->signature_present) {
        furi_string_cat(str, "\n\e#Signature\n");
        nfc_render_mf_plus_hex_or_unknown(data->signature, MF_PLUS_SIGNATURE_SIZE, true, str);
        furi_string_cat(str, "\n");
    }
}

atic bool
    nfc_scene_mf_plus_dict_attack_next_key(NfcMfPlusDictAttackContext* ctx, MfPlusKey* key) {
    if(!ctx->on_system_dict && ctx->user_dict != NULL) {
        if(keys_dict_get_next_key(ctx->user_dict, key->data, sizeof(MfPlusKey))) {
            return true;
        }
        // User dictionary exhausted for this request; continue with the system dictionary.
        ctx->on_system_dict = true;
    }

    if(ctx->system_dict != NULL) {
        return keys_dict_get_next_key(ctx->system_dict, key->data, sizeof(MfPlusKey));
    }

    return false;
}

cCommand nfc_mf_plus_dict_attack_worker_callback(NfcGenericEvent event, void* context) {
    furi_assert(context);
    furi_assert(event.event_data);
    furi_assert(event.protocol == NfcProtocolMfPlus);

    NfcCommand command = NfcCommandContinue;
    NfcApp* instance = context;
    MfPlusPollerEvent* mfp_event = event.event_data;
    NfcMfPlusDictAttackContext* ctx = &instance->mf_plus_dict_context;

    if(mfp_event->type == MfPlusPollerEventTypeRequestMode) {
        mfp_event->data->mode_request.mode = MfPlusPollerModeRead;
        // The poller has parsed the version/type by now, so the card geometry is known.
        const MfPlusData* data = nfc_poller_get_data(instance->poller);
        ctx->sectors_total = mf_plus_get_sector_count(data->size);
        view_dispatcher_send_custom_event(
            instance->view_dispatcher, NfcCustomEventDictAttackDataUpdate);
    } else if(mfp_event->type == MfPlusPollerEventTypeRequestKey) {
        const bool is_admin = mfp_event->data->key_request.is_admin;
        const uint8_t sector = mfp_event->data->key_request.sector;
        const uint8_t key_type = mfp_event->data->key_request.key_type;
        const uint8_t admin_type = mfp_event->data->key_request.admin_type;

        // A change of target (sector key A/B, or which admin key) since the last request means the
        // poller advanced; restart the combined key stream from the top of the user dictionary.
        bool target_changed;
        if(!ctx->request_seen || is_admin != ctx->last_is_admin) {
            target_changed = true;
        } else if(is_admin) {
            target_changed = admin_type != ctx->last_admin_type;
        } else {
            target_changed = sector != ctx->last_sector || key_type != ctx->last_key_type;
        }
        if(target_changed) {
            if(ctx->user_dict != NULL) keys_dict_rewind(ctx->user_dict);
            if(ctx->system_dict != NULL) keys_dict_rewind(ctx->system_dict);
            ctx->on_system_dict = (ctx->user_dict == NULL);
            ctx->dict_keys_current = 0;
            ctx->cache_key_fed = false;
            ctx->request_seen = true;
            ctx->last_is_admin = is_admin;
            ctx->last_sector = sector;
            ctx->last_key_type = key_type;
            ctx->last_admin_type = admin_type;
        }
        // Admin keys aren't sectors; leave the sector display untouched during the admin phase.
        if(!is_admin) ctx->current_sector = sector;

        MfPlusKey key = {};
        bool cache_hit = false;
        // Offer the cached key for this target first, once. Cache hits don't advance the dictionary
        // progress counter -- they aren't part of dict_keys_total. If the cached key fails to
        // authenticate the poller re-requests the same target, and cache_key_fed then routes it to
        // the dictionaries (covers a re-keyed card).
        if(!ctx->cache_key_fed) {
            ctx->cache_key_fed = true;
            cache_hit =
                is_admin ?
                    mf_plus_key_cache_get_admin_key(ctx->key_cache, admin_type, &key) :
                    mf_plus_key_cache_get_sector_key(ctx->key_cache, sector, key_type, &key);
        }
        if(cache_hit) {
            mfp_event->data->key_request.key = key;
            mfp_event->data->key_request.key_provided = true;
        } else if(nfc_scene_mf_plus_dict_attack_next_key(ctx, &key)) {
            mfp_event->data->key_request.key = key;
            mfp_event->data->key_request.key_provided = true;
            ctx->dict_keys_current++;
            if(ctx->dict_keys_current % 10 == 0) {
                view_dispatcher_send_custom_event(
                    instance->view_dispatcher, NfcCustomEventDictAttackDataUpdate);
            }
        } else {
            mfp_event->data->key_request.key_provided = false;
        }
    } else if(mfp_event->type == MfPlusPollerEventTypeDataUpdate) {
        ctx->current_sector = mfp_event->data->data_update.current_sector;
        ctx->sectors_read = mfp_event->data->data_update.sectors_read;
        ctx->keys_found = mfp_event->data->data_update.keys_found;
        view_dispatcher_send_custom_event(
            instance->view_dispatcher, NfcCustomEventDictAttackDataUpdate);
    } else if(mfp_event->type == MfPlusPollerEventTypeReadSuccess) {
        view_dispatcher_send_custom_event(
            instance->view_dispatcher, NfcCustomEventDictAttackComplete);
        command = NfcCommandStop;
    } else if(mfp_event->type == MfPlusPollerEventTypeReadFailed) {
        // A lost card or comms fault is NOT the same as an incomplete dictionary: log it and route
        // to a distinct failure path so the scan is never graded as a clean read. The finish
        // handler still preserves whatever was recovered before the fault.
        FURI_LOG_W(
            TAG,
            "Read aborted (poller error %d) after %u/%u sectors",
            mfp_event->data->error,
            ctx->sectors_read,
            ctx->sectors_total);
        view_dispatcher_send_custom_event(instance->view_dispatcher, NfcCustomEventPollerFailure);
        command = NfcCommandStop;
    } else {
        FURI_LOG_E(TAG, "Unhandled poller event %d", mfp_event->type);
    }

    return command;
}

atic void nfc_scene_mf_plus_dict_attack_result_callback(DictAttackEvent event, void* context) {
    furi_assert(context);
    NfcApp* instance = context;
    if(event == DictAttackEventSkipPressed) {
        view_dispatcher_send_custom_event(instance->view_dispatcher, NfcCustomEventDictAttackSkip);
    }
}

atic void nfc_scene_mf_plus_dict_attack_update_view(NfcApp* instance) {
    NfcMfPlusDictAttackContext* ctx = &instance->mf_plus_dict_context;
    dict_attack_set_sectors_total(instance->dict_attack, ctx->sectors_total);
    dict_attack_set_sectors_read(instance->dict_attack, ctx->sectors_read);
    dict_attack_set_keys_found(instance->dict_attack, ctx->keys_found);
    dict_attack_set_current_sector(instance->dict_attack, ctx->current_sector);
    dict_attack_set_current_dict_key(instance->dict_attack, ctx->dict_keys_current);
}

atic void nfc_scene_mf_plus_dict_attack_setup_dicts(NfcApp* instance) {
    NfcMfPlusDictAttackContext* ctx = &instance->mf_plus_dict_context;

    // The user dictionary is optional and lazily created by the key-management scenes; drop the
    // handle when the file is missing or holds no keys so the pass falls straight to the system one.
    if(keys_dict_check_presence(NFC_APP_MF_PLUS_DICT_USER_PATH)) {
        ctx->user_dict = keys_dict_alloc(
            NFC_APP_MF_PLUS_DICT_USER_PATH, KeysDictModeOpenAlways, sizeof(MfPlusKey));
        if(keys_dict_get_total_keys(ctx->user_dict) == 0) {
            keys_dict_free(ctx->user_dict);
            ctx->user_dict = NULL;
        }
    }
    // A missing system dictionary is not fatal (the attack just finds nothing), but it means a
    // broken install, so make it diagnosable instead of a silent "found no keys".
    if(!keys_dict_check_presence(NFC_APP_MF_PLUS_DICT_SYSTEM_PATH)) {
        FURI_LOG_W(TAG, "System dictionary %s is missing", NFC_APP_MF_PLUS_DICT_SYSTEM_PATH);
    }
    ctx->system_dict = keys_dict_alloc(
        NFC_APP_MF_PLUS_DICT_SYSTEM_PATH, KeysDictModeOpenExisting, sizeof(MfPlusKey));

    ctx->dict_keys_total =
        (ctx->user_dict != NULL ? keys_dict_get_total_keys(ctx->user_dict) : 0) +
        keys_dict_get_total_keys(ctx->system_dict);
    ctx->dict_keys_current = 0;
    ctx->on_system_dict = (ctx->user_dict == NULL);
    ctx->request_seen = false;

    // Per-UID key cache: if this exact card was saved before, its recovered keys authenticate on the
    // first try per sector, so the pass flies through instead of walking the dictionaries. A miss
    // (no cache file / different card) leaves the cache empty and the attack runs exactly as before.
    ctx->key_cache = mf_plus_key_cache_alloc();
    ctx->cache_key_fed = false;
    const MfPlusData* data = nfc_device_get_data(instance->nfc_device, NfcProtocolMfPlus);
    size_t uid_len = 0;
    const uint8_t* uid = mf_plus_get_uid(data, &uid_len);
    if(mf_plus_key_cache_load(ctx->key_cache, uid, uid_len)) {
        FURI_LOG_I(TAG, "Key cache hit; seeding dictionary attack with saved keys");
    }

    // The dict_attack view is shared; its type persists from whichever scene last used it (e.g. the
    // Ultralight-C scene never resets it), so set the sector-oriented layout explicitly on entry.
    dict_attack_set_type(instance->dict_attack, DictAttackTypeMfClassic);
    dict_attack_set_header(instance->dict_attack, "MF Plus Dictionary");
    dict_attack_set_total_dict_keys(instance->dict_attack, ctx->dict_keys_total);
    dict_attack_set_current_dict_key(instance->dict_attack, 0);
    dict_attack_set_callback(
        instance->dict_attack, nfc_scene_mf_plus_dict_attack_result_callback, instance);
}

id nfc_scene_mf_plus_dict_attack_on_enter(void* context) {
    NfcApp* instance = context;

    nfc_scene_mf_plus_dict_attack_setup_dicts(instance);
    nfc_scene_mf_plus_dict_attack_update_view(instance);
    dict_attack_set_card_state(instance->dict_attack, true);

    view_dispatcher_switch_to_view(instance->view_dispatcher, NfcViewDictAttack);
    nfc_blink_read_start(instance);

    instance->poller = nfc_poller_alloc(instance->nfc, NfcProtocolMfPlus);
    nfc_poller_start(instance->poller, nfc_mf_plus_dict_attack_worker_callback, instance);
}

atic void nfc_scene_mf_plus_dict_attack_finish(NfcApp* instance, bool aborted) {
    // Push whatever the poller recovered (full or partial) to the device for the results screen.
    const MfPlusData* data = nfc_poller_get_data(instance->poller);
    nfc_device_set_data(instance->nfc_device, NfcProtocolMfPlus, data);
    // A clean pass that captured every block is a full success; an aborted scan (comms fault / lost
    // card) or a partial recovery is semi-success. mf_plus_is_card_read checks captured blocks, not
    // the poller's sector counter, which also counts sectors that aborted mid-read.
    bool fully_read = !aborted && mf_plus_is_card_read(data);
    notification_message(
        instance->notifications, fully_read ? &sequence_success : &sequence_semi_success);
    scene_manager_next_scene(instance->scene_manager, NfcSceneReadSuccess);
    dolphin_deed(DolphinDeedNfcReadSuccess);
}

ol nfc_scene_mf_plus_dict_attack_on_event(void* context, SceneManagerEvent event) {
    NfcApp* instance = context;
    bool consumed = false;

    if(event.type == SceneManagerEventTypeCustom) {
        if(event.event == NfcCustomEventDictAttackComplete ||
           event.event == NfcCustomEventDictAttackSkip) {
            nfc_scene_mf_plus_dict_attack_finish(instance, false);
            consumed = true;
        } else if(event.event == NfcCustomEventPollerFailure) {
            nfc_scene_mf_plus_dict_attack_finish(instance, true);
            consumed = true;
        } else if(event.event == NfcCustomEventDictAttackDataUpdate) {
            nfc_scene_mf_plus_dict_attack_update_view(instance);
            consumed = true;
        }
    } else if(event.type == SceneManagerEventTypeBack) {
        scene_manager_next_scene(instance->scene_manager, NfcSceneExitConfirm);
        consumed = true;
    }

    return consumed;
}

id nfc_scene_mf_plus_dict_attack_on_exit(void* context) {
    NfcApp* instance = context;
    NfcMfPlusDictAttackContext* ctx = &instance->mf_plus_dict_context;

    nfc_poller_stop(instance->poller);
    nfc_poller_free(instance->poller);

    dict_attack_reset(instance->dict_attack);

    if(ctx->user_dict != NULL) {
        keys_dict_free(ctx->user_dict);
        ctx->user_dict = NULL;
    }
    if(ctx->system_dict != NULL) {
        keys_dict_free(ctx->system_dict);
        ctx->system_dict = NULL;
    }
    if(ctx->key_cache != NULL) {
        mf_plus_key_cache_free(ctx->key_cache);
        ctx->key_cache = NULL;
    }

    ctx->on_system_dict = false;
    ctx->sectors_total = 0;
    ctx->sectors_read = 0;
    ctx->current_sector = 0;
    ctx->keys_found = 0;
    ctx->dict_keys_total = 0;
    ctx->dict_keys_current = 0;
    ctx->request_seen = false;
    ctx->last_is_admin = false;
    ctx->last_sector = 0;
    ctx->last_key_type = 0;
    ctx->last_admin_type = 0;
    ctx->cache_key_fed = false;

    nfc_blink_stop(instance);
}

void nfc_scene_mf_plus_iso4_info_on_enter(void* context) {
    NfcApp* instance = context;
    const MfPlusData* data = nfc_device_get_data(instance->nfc_device, NfcProtocolMfPlus);

    furi_string_reset(instance->text_box_store);
    nfc_render_mf_plus_iso14443_4(data, instance->text_box_store);

    widget_add_text_scroll_element(
        instance->widget, 0, 0, 128, 52, furi_string_get_cstr(instance->text_box_store));
    widget_add_button_element(
        instance->widget,
        GuiButtonTypeRight,
        "More",
        nfc_protocol_support_common_widget_callback,
        instance);

    view_dispatcher_switch_to_view(instance->view_dispatcher, NfcViewWidget);
}

bool nfc_scene_mf_plus_iso4_info_on_event(void* context, SceneManagerEvent event) {
    NfcApp* instance = context;
    bool consumed = false;
    if(event.type == SceneManagerEventTypeCustom && event.event == GuiButtonTypeRight) {
        scene_manager_next_scene(instance->scene_manager, NfcSceneMfPlusVersion);
        consumed = true;
    }
    return consumed;
}

void nfc_scene_mf_plus_iso4_info_on_exit(void* context) {
    NfcApp* instance = context;
    widget_reset(instance->widget);
    furi_string_reset(instance->text_box_store);
}

void nfc_scene_mf_plus_keys_widget_callback(GuiButtonType result, InputType type, void* context) {
    NfcApp* instance = context;
    if(type == InputTypeShort) {
        view_dispatcher_send_custom_event(instance->view_dispatcher, result);
    }
}

void nfc_scene_mf_plus_keys_on_enter(void* context) {
    NfcApp* instance = context;

    // System dict key count
    KeysDict* dict = keys_dict_alloc(
        NFC_APP_MF_PLUS_DICT_SYSTEM_PATH, KeysDictModeOpenExisting, sizeof(MfPlusKey));
    uint32_t system_dict_keys_total = keys_dict_get_total_keys(dict);
    keys_dict_free(dict);

    // User dict key count (lazily created)
    dict =
        keys_dict_alloc(NFC_APP_MF_PLUS_DICT_USER_PATH, KeysDictModeOpenAlways, sizeof(MfPlusKey));
    uint32_t user_dict_keys_total = keys_dict_get_total_keys(dict);
    keys_dict_free(dict);

    FuriString* temp_str = furi_string_alloc();
    widget_add_string_element(
        instance->widget, 0, 0, AlignLeft, AlignTop, FontPrimary, "MIFARE Plus Keys");
    furi_string_printf(temp_str, "System dict: %lu", system_dict_keys_total);
    widget_add_string_element(
        instance->widget,
        0,
        20,
        AlignLeft,
        AlignTop,
        FontSecondary,
        furi_string_get_cstr(temp_str));
    furi_string_printf(temp_str, "User dict: %lu", user_dict_keys_total);
    widget_add_string_element(
        instance->widget,
        0,
        32,
        AlignLeft,
        AlignTop,
        FontSecondary,
        furi_string_get_cstr(temp_str));
    widget_add_icon_element(instance->widget, 87, 13, &I_Keychain_39x36);
    widget_add_button_element(
        instance->widget,
        GuiButtonTypeCenter,
        "Add",
        nfc_scene_mf_plus_keys_widget_callback,
        instance);
    if(user_dict_keys_total > 0) {
        widget_add_button_element(
            instance->widget,
            GuiButtonTypeRight,
            "List",
            nfc_scene_mf_plus_keys_widget_callback,
            instance);
    }
    furi_string_free(temp_str);

    view_dispatcher_switch_to_view(instance->view_dispatcher, NfcViewWidget);
}

bool nfc_scene_mf_plus_keys_on_event(void* context, SceneManagerEvent event) {
    NfcApp* instance = context;
    bool consumed = false;

    if(event.type == SceneManagerEventTypeCustom) {
        if(event.event == GuiButtonTypeCenter) {
            scene_manager_next_scene(instance->scene_manager, NfcSceneMfPlusKeysAdd);
            consumed = true;
        } else if(event.event == GuiButtonTypeRight) {
            scene_manager_next_scene(instance->scene_manager, NfcSceneMfPlusKeysList);
            consumed = true;
        }
    }

    return consumed;
}

void nfc_scene_mf_plus_keys_on_exit(void* context) {
    NfcApp* instance = context;

    widget_reset(instance->widget);
}

void nfc_scene_mf_plus_keys_add_byte_input_callback(void* context) {
    NfcApp* instance = context;

    view_dispatcher_send_custom_event(instance->view_dispatcher, NfcCustomEventByteInputDone);
}

void nfc_scene_mf_plus_keys_add_on_enter(void* context) {
    NfcApp* instance = context;

    ByteInput* byte_input = instance->byte_input;
    byte_input_set_header_text(byte_input, "Enter the key in hex");
    byte_input_set_result_callback(
        byte_input,
        nfc_scene_mf_plus_keys_add_byte_input_callback,
        NULL,
        instance,
        instance->byte_input_store,
        sizeof(MfPlusKey));
    view_dispatcher_switch_to_view(instance->view_dispatcher, NfcViewByteInput);
}

bool nfc_scene_mf_plus_keys_add_on_event(void* context, SceneManagerEvent event) {
    NfcApp* instance = context;
    bool consumed = false;

    if(event.type == SceneManagerEventTypeCustom) {
        if(event.event == NfcCustomEventByteInputDone) {
            KeysDict* dict = keys_dict_alloc(
                NFC_APP_MF_PLUS_DICT_USER_PATH, KeysDictModeOpenAlways, sizeof(MfPlusKey));

            MfPlusKey key = {};
            memcpy(key.data, instance->byte_input_store, sizeof(MfPlusKey));
            if(keys_dict_is_key_present(dict, key.data, sizeof(MfPlusKey))) {
                scene_manager_next_scene(instance->scene_manager, NfcSceneMfPlusKeysWarnDuplicate);
            } else if(keys_dict_add_key(dict, key.data, sizeof(MfPlusKey))) {
                scene_manager_next_scene(instance->scene_manager, NfcSceneSaveSuccess);
                dolphin_deed(DolphinDeedNfcKeyAdd);
            } else {
                scene_manager_previous_scene(instance->scene_manager);
            }

            keys_dict_free(dict);
            consumed = true;
        }
    }

    return consumed;
}

void nfc_scene_mf_plus_keys_add_on_exit(void* context) {
    NfcApp* instance = context;

    byte_input_set_result_callback(instance->byte_input, NULL, NULL, NULL, NULL, 0);
    byte_input_set_header_text(instance->byte_input, "");
}

static bool nfc_scene_mf_plus_keys_delete_load_key(uint32_t key_index, MfPlusKey* key) {
    KeysDict* user_dict =
        keys_dict_alloc(NFC_APP_MF_PLUS_DICT_USER_PATH, KeysDictModeOpenAlways, sizeof(MfPlusKey));
    bool loaded = key_index < keys_dict_get_total_keys(user_dict);
    for(size_t i = 0; loaded && i < (key_index + 1); i++) {
        loaded = keys_dict_get_next_key(user_dict, key->data, sizeof(MfPlusKey));
    }
    keys_dict_free(user_dict);
    return loaded;
}

void nfc_scene_mf_plus_keys_delete_widget_callback(
    GuiButtonType result,
    InputType type,
    void* context) {
    NfcApp* instance = context;
    if(type == InputTypeShort) {
        view_dispatcher_send_custom_event(instance->view_dispatcher, result);
    }
}

void nfc_scene_mf_plus_keys_delete_on_enter(void* context) {
    NfcApp* instance = context;

    uint32_t key_index =
        scene_manager_get_scene_state(instance->scene_manager, NfcSceneMfPlusKeysDelete);

    widget_add_string_element(
        instance->widget, 64, 0, AlignCenter, AlignTop, FontPrimary, "Delete this key?");
    widget_add_button_element(
        instance->widget,
        GuiButtonTypeLeft,
        "Cancel",
        nfc_scene_mf_plus_keys_delete_widget_callback,
        instance);
    widget_add_button_element(
        instance->widget,
        GuiButtonTypeRight,
        "Delete",
        nfc_scene_mf_plus_keys_delete_widget_callback,
        instance);

    MfPlusKey stack_key;
    if(nfc_scene_mf_plus_keys_delete_load_key(key_index, &stack_key)) {
        FuriString* key_str = furi_string_alloc();
        for(size_t i = 0; i < sizeof(MfPlusKey); i++) {
            furi_string_cat_printf(key_str, "%02X", stack_key.data[i]);
        }
        widget_add_string_element(
            instance->widget,
            64,
            32,
            AlignCenter,
            AlignCenter,
            FontSecondary,
            furi_string_get_cstr(key_str));
        furi_string_free(key_str);
    }

    view_dispatcher_switch_to_view(instance->view_dispatcher, NfcViewWidget);
}

bool nfc_scene_mf_plus_keys_delete_on_event(void* context, SceneManagerEvent event) {
    NfcApp* instance = context;
    bool consumed = false;

    if(event.type == SceneManagerEventTypeCustom) {
        if(event.event == GuiButtonTypeRight) {
            uint32_t key_index =
                scene_manager_get_scene_state(instance->scene_manager, NfcSceneMfPlusKeysDelete);
            MfPlusKey stack_key;
            bool deleted = false;
            if(nfc_scene_mf_plus_keys_delete_load_key(key_index, &stack_key)) {
                KeysDict* user_dict = keys_dict_alloc(
                    NFC_APP_MF_PLUS_DICT_USER_PATH, KeysDictModeOpenAlways, sizeof(MfPlusKey));
                deleted = keys_dict_delete_key(user_dict, stack_key.data, sizeof(MfPlusKey));
                keys_dict_free(user_dict);
            }
            if(deleted) {
                scene_manager_next_scene(instance->scene_manager, NfcSceneDeleteSuccess);
            } else {
                scene_manager_previous_scene(instance->scene_manager);
            }
        } else if(event.event == GuiButtonTypeLeft) {
            scene_manager_previous_scene(instance->scene_manager);
        }
        consumed = true;
    }

    return consumed;
}

void nfc_scene_mf_plus_keys_delete_on_exit(void* context) {
    NfcApp* instance = context;

    widget_reset(instance->widget);
}

