static void nfc_generate_mf_plus_version(
    MfPlusVersion* version,
    uint8_t hw_major,
    uint8_t hw_storage,
    const uint8_t* card_uid,
    uint8_t uid_len) {
    // Field values match a real MIFARE Plus EV1 GetVersion capture (hw_proto 0x04; the software
    // version reports its own major/minor 0x01/0x01, independent of the hardware major).
    version->hw_vendor = NXP_MANUFACTURER_ID;
    version->hw_type = 0x02;
    version->hw_subtype = 0x01;
    version->hw_major = hw_major;
    version->hw_minor = 0x00;
    version->hw_storage = hw_storage;
    version->hw_proto = 0x04;

    version->sw_vendor = NXP_MANUFACTURER_ID;
    version->sw_type = 0x02;
    version->sw_subtype = 0x01;
    version->sw_major = 0x01;
    version->sw_minor = 0x01;
    version->sw_storage = hw_storage;
    version->sw_proto = 0x04;

    if(uid_len == 7) {
        memcpy(version->uid, card_uid, 7);
    } else {
        version->uid[0] = NXP_MANUFACTURER_ID;
        furi_hal_random_fill_buf(&version->uid[1], 6);
    }
    furi_hal_random_fill_buf(version->batch, sizeof(version->batch));
    version->prod_week = 0x18;
    version->prod_year = 0x18;
}

static void nfc_generate_mf_plus_default_content(MfPlusData* data) {
    MfPlusKey default_key;
    memset(default_key.data, 0xFF, MF_PLUS_KEY_SIZE);

    MfPlusBlock zero_block;
    memset(zero_block.data, 0x00, MF_PLUS_BLOCK_SIZE);

    const uint16_t block_count = mf_plus_get_block_count(data->size);
    for(uint16_t b = 0; b < block_count; b++) {
        mf_plus_set_block_read(data, b, &zero_block);
    }

    const uint8_t sector_count = mf_plus_get_sector_count(data->size);
    for(uint8_t s = 0; s < sector_count; s++) {
        mf_plus_set_key_found(data, s, MfPlusKeyTypeA, &default_key);
        mf_plus_set_key_found(data, s, MfPlusKeyTypeB, &default_key);
    }

    for(uint8_t a = 0; a < MfPlusAdminKeyNum; a++) {
        mf_plus_set_admin_key_found(data, (MfPlusAdminKeyType)a, &default_key);
    }

    for(uint8_t c = 0; c < MF_PLUS_CONFIG_BLOCK_NUM; c++) {
        mf_plus_set_config_block_read(data, c, &zero_block);
    }
}

static void nfc_generate_mf_plus_block_0(
    MfPlusData* data,
    const uint8_t* uid,
    uint8_t uid_len,
    uint8_t sak,
    uint8_t atqa0,
    uint8_t atqa1) {
    MfPlusBlock block0;
    memset(block0.data, 0xFF, MF_PLUS_BLOCK_SIZE); // manufacturer bytes
    memcpy(block0.data, uid, uid_len);

    uint8_t offset = uid_len;
    if(uid_len == 4) {
        block0.data[4] = uid[0] ^ uid[1] ^ uid[2] ^
                         uid[3]; // BCC (7-byte UIDs carry no block-0 BCC)
        offset = 5;
    }
    block0.data[offset] = sak;
    block0.data[offset + 1] = atqa0;
    block0.data[offset + 2] = atqa1;

    mf_plus_set_block_read(data, 0, &block0);
}

static void nfc_generate_mf_plus(
    NfcDevice* nfc_device,
    uint8_t uid_len,
    MfPlusType type,
    MfPlusSize size,
    const uint8_t* ats_hist) {
    furi_assert(uid_len == 4 || uid_len == 7);

    MfPlusData* data = mf_plus_alloc();

    uint8_t uid[MF_PLUS_UID_SIZE_MAX];
    uid[0] = NXP_MANUFACTURER_ID;
    furi_hal_random_fill_buf(&uid[1], uid_len - 1);
    uid[3] |=
        0x01; // avoid the forbidden 0x88 cascade tag as the first byte of CL2 in a 7-byte UID
    mf_plus_set_uid(data, uid, uid_len);

    // SL3 presents SAK 0x20 (ISO14443-4). ATQA size bit: 4K = 0x02, 1K/2K = 0x04; +0x40 for a
    // 7-byte UID. SE's size comes from its ATS, not the ATQA, so it shares the 1K/2K coding.
    Iso14443_3aData* iso3 = iso14443_4a_get_base_data(data->iso14443_4a_data);
    iso3->atqa[0] = (size == MfPlusSize4K) ? 0x02 : 0x04;
    if(uid_len == 7) {
        iso3->atqa[0] |= 0x40;
    }
    iso3->atqa[1] = 0x00;
    iso3->sak = 0x20;

    // Standard MIFARE Plus ATS: TL T0 TA TB TC + 7 historical bytes (FSCI 5 = 64-byte frame, TA/TB/TC
    // present). tl is the full ATS length so iso14443_4a_save round-trips it.
    Iso14443_4aAtsData* ats = &data->iso14443_4a_data->ats_data;
    ats->t0 = 0x75;
    ats->ta_1 = 0x77;
    ats->tb_1 = 0x80;
    ats->tc_1 = 0x02;
    simple_array_init(ats->t1_tk, MF_PLUS_ATS_HIST_LEN);
    memcpy(simple_array_get_data(ats->t1_tk), ats_hist, MF_PLUS_ATS_HIST_LEN);
    ats->tl = 5 + MF_PLUS_ATS_HIST_LEN;

    data->type = type;
    data->size = size;
    data->security_level = MfPlusSecurityLevel3;

    nfc_generate_mf_plus_default_content(data);
    nfc_generate_mf_plus_block_0(data, uid, uid_len, iso3->sak, iso3->atqa[0], iso3->atqa[1]);

    // EV1/EV2 answer GetVersion and carry an originality signature; the EV0 products (SE/S/X) do
    // neither, so their version stays zeroed (shown as "no GetVersion") and signature_present false.
    if(type == MfPlusTypeEV1 || type == MfPlusTypeEV2) {
        const uint8_t hw_major = (type == MfPlusTypeEV2) ? 0x22 : 0x11;
        const uint8_t hw_storage = (size == MfPlusSize4K) ? 0x18 : 0x16;
        nfc_generate_mf_plus_version(&data->version, hw_major, hw_storage, uid, uid_len);
        furi_hal_random_fill_buf(data->signature, MF_PLUS_SIGNATURE_SIZE);
        data->signature_present = true;
    }

    nfc_device_set_data(nfc_device, NfcProtocolMfPlus, data);
    mf_plus_free(data);
}

static void mf_plus_crypto_aes_ecb(
    bool encrypt,
    const uint8_t key[MF_PLUS_AES_KEY_SIZE],
    const uint8_t input[MF_PLUS_AES_BLOCK_SIZE],
    uint8_t output[MF_PLUS_AES_BLOCK_SIZE]) {
    mbedtls_aes_context ctx;
    mbedtls_aes_init(&ctx);
    if(encrypt) {
        furi_check(mbedtls_aes_setkey_enc(&ctx, key, 128) == 0);
        furi_check(mbedtls_aes_crypt_ecb(&ctx, MBEDTLS_AES_ENCRYPT, input, output) == 0);
    } else {
        furi_check(mbedtls_aes_setkey_dec(&ctx, key, 128) == 0);
        furi_check(mbedtls_aes_crypt_ecb(&ctx, MBEDTLS_AES_DECRYPT, input, output) == 0);
    }
    mbedtls_aes_free(&ctx);
}

static void mf_plus_crypto_aes_cbc(
    bool encrypt,
    const uint8_t key[MF_PLUS_AES_KEY_SIZE],
    const uint8_t iv[MF_PLUS_AES_BLOCK_SIZE],
    const uint8_t* input,
    uint8_t* output,
    size_t length) {
    // CBC needs whole 16-byte blocks; a zero/partial length is a caller-contract violation
    // (mbedtls would no-op or error) — fail loud rather than skip or emit crypto silently.
    furi_check(length != 0 && (length % MF_PLUS_AES_BLOCK_SIZE) == 0);

    // mbedtls updates the IV in place; keep the caller's const IV intact.
    uint8_t iv_local[MF_PLUS_AES_BLOCK_SIZE];
    memcpy(iv_local, iv, MF_PLUS_AES_BLOCK_SIZE);

    mbedtls_aes_context ctx;
    mbedtls_aes_init(&ctx);
    if(encrypt) {
        furi_check(mbedtls_aes_setkey_enc(&ctx, key, 128) == 0);
        furi_check(
            mbedtls_aes_crypt_cbc(&ctx, MBEDTLS_AES_ENCRYPT, length, iv_local, input, output) ==
            0);
    } else {
        furi_check(mbedtls_aes_setkey_dec(&ctx, key, 128) == 0);
        furi_check(
            mbedtls_aes_crypt_cbc(&ctx, MBEDTLS_AES_DECRYPT, length, iv_local, input, output) ==
            0);
    }
    mbedtls_aes_free(&ctx);
}

id mf_plus_crypto_ecb_encrypt(
    const uint8_t key[MF_PLUS_AES_KEY_SIZE],
    const uint8_t input[MF_PLUS_AES_BLOCK_SIZE],
    uint8_t output[MF_PLUS_AES_BLOCK_SIZE]) {
    mf_plus_crypto_aes_ecb(true, key, input, output);
}

id mf_plus_crypto_ecb_decrypt(
    const uint8_t key[MF_PLUS_AES_KEY_SIZE],
    const uint8_t input[MF_PLUS_AES_BLOCK_SIZE],
    uint8_t output[MF_PLUS_AES_BLOCK_SIZE]) {
    mf_plus_crypto_aes_ecb(false, key, input, output);
}

id mf_plus_crypto_cbc_encrypt(
    const uint8_t key[MF_PLUS_AES_KEY_SIZE],
    const uint8_t iv[MF_PLUS_AES_BLOCK_SIZE],
    const uint8_t* input,
    uint8_t* output,
    size_t length) {
    mf_plus_crypto_aes_cbc(true, key, iv, input, output, length);
}

id mf_plus_crypto_cbc_decrypt(
    const uint8_t key[MF_PLUS_AES_KEY_SIZE],
    const uint8_t iv[MF_PLUS_AES_BLOCK_SIZE],
    const uint8_t* input,
    uint8_t* output,
    size_t length) {
    mf_plus_crypto_aes_cbc(false, key, iv, input, output, length);
}

atic void mf_plus_crypto_cmac_shift_left(
    const uint8_t in[MF_PLUS_AES_BLOCK_SIZE],
    uint8_t out[MF_PLUS_AES_BLOCK_SIZE]) {
    uint8_t carry = 0;
    for(int i = MF_PLUS_AES_BLOCK_SIZE - 1; i >= 0; i--) {
        out[i] = (uint8_t)((in[i] << 1) | carry);
        carry = (in[i] >> 7) & 1;
    }
}

atic void mf_plus_crypto_cmac_subkeys(
    const uint8_t key[MF_PLUS_AES_KEY_SIZE],
    uint8_t k1[MF_PLUS_AES_BLOCK_SIZE],
    uint8_t k2[MF_PLUS_AES_BLOCK_SIZE]) {
    const uint8_t rb = 0x87;
    uint8_t l[MF_PLUS_AES_BLOCK_SIZE];
    memset(l, 0, sizeof(l));
    mf_plus_crypto_ecb_encrypt(key, l, l);

    mf_plus_crypto_cmac_shift_left(l, k1);
    if(l[0] & 0x80) k1[MF_PLUS_AES_BLOCK_SIZE - 1] ^= rb;

    mf_plus_crypto_cmac_shift_left(k1, k2);
    if(k1[0] & 0x80) k2[MF_PLUS_AES_BLOCK_SIZE - 1] ^= rb;
}

id mf_plus_crypto_cmac(
    const uint8_t key[MF_PLUS_AES_KEY_SIZE],
    const uint8_t* data,
    size_t length,
    uint8_t mac[MF_PLUS_AES_BLOCK_SIZE]) {
    uint8_t k1[MF_PLUS_AES_BLOCK_SIZE], k2[MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_cmac_subkeys(key, k1, k2);

    size_t n = (length + MF_PLUS_AES_BLOCK_SIZE - 1) / MF_PLUS_AES_BLOCK_SIZE;
    if(n == 0) n = 1;
    const bool last_complete = (length > 0) && (length % MF_PLUS_AES_BLOCK_SIZE == 0);

    uint8_t x[MF_PLUS_AES_BLOCK_SIZE];
    memset(x, 0, sizeof(x));

    for(size_t i = 0; i < n - 1; i++) {
        uint8_t y[MF_PLUS_AES_BLOCK_SIZE];
        for(size_t j = 0; j < MF_PLUS_AES_BLOCK_SIZE; j++) {
            y[j] = x[j] ^ data[i * MF_PLUS_AES_BLOCK_SIZE + j];
        }
        mf_plus_crypto_ecb_encrypt(key, y, x);
    }

    uint8_t last[MF_PLUS_AES_BLOCK_SIZE];
    const size_t offset = (n - 1) * MF_PLUS_AES_BLOCK_SIZE;
    if(last_complete) {
        for(size_t j = 0; j < MF_PLUS_AES_BLOCK_SIZE; j++) {
            last[j] = data[offset + j] ^ k1[j];
        }
    } else {
        memset(last, 0, sizeof(last));
        const size_t rem = length - offset;
        memcpy(last, &data[offset], rem);
        last[rem] = 0x80;
        for(size_t j = 0; j < MF_PLUS_AES_BLOCK_SIZE; j++) {
            last[j] ^= k2[j];
        }
    }

    uint8_t y[MF_PLUS_AES_BLOCK_SIZE];
    for(size_t j = 0; j < MF_PLUS_AES_BLOCK_SIZE; j++) {
        y[j] = x[j] ^ last[j];
    }
    mf_plus_crypto_ecb_encrypt(key, y, mac);
}

id mf_plus_crypto_cmac8(
    const uint8_t key[MF_PLUS_AES_KEY_SIZE],
    const uint8_t* data,
    size_t length,
    uint8_t mac[MF_PLUS_MAC_SIZE]) {
    uint8_t full[MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_cmac(key, data, length, full);
    for(size_t i = 0; i < MF_PLUS_MAC_SIZE; i++) {
        mac[i] = full[i * 2 + 1];
    }
}

id mf_plus_crypto_derive_session_keys(
    const uint8_t key[MF_PLUS_AES_KEY_SIZE],
    const uint8_t rnd_a[MF_PLUS_AES_BLOCK_SIZE],
    const uint8_t rnd_b[MF_PLUS_AES_BLOCK_SIZE],
    uint8_t k_enc[MF_PLUS_AES_KEY_SIZE],
    uint8_t k_mac[MF_PLUS_AES_KEY_SIZE]) {
    uint8_t sv[MF_PLUS_AES_BLOCK_SIZE];

    // Kenc: RndA[11..15] || RndB[11..15] || (RndA[4..8] ^ RndB[4..8]) || 0x11
    memcpy(&sv[0], &rnd_a[11], 5);
    memcpy(&sv[5], &rnd_b[11], 5);
    for(int i = 0; i < 5; i++) {
        sv[10 + i] = rnd_a[4 + i] ^ rnd_b[4 + i];
    }
    sv[15] = 0x11;
    mf_plus_crypto_ecb_encrypt(key, sv, k_enc);

    // Kmac: RndA[7..11] || RndB[7..11] || (RndA[0..4] ^ RndB[0..4]) || 0x22
    memcpy(&sv[0], &rnd_a[7], 5);
    memcpy(&sv[5], &rnd_b[7], 5);
    for(int i = 0; i < 5; i++) {
        sv[10 + i] = rnd_a[i] ^ rnd_b[i];
    }
    sv[15] = 0x22;
    mf_plus_crypto_ecb_encrypt(key, sv, k_mac);
}

id mf_plus_crypto_calculate_mac(
    const uint8_t k_mac[MF_PLUS_AES_KEY_SIZE],
    uint8_t cmd,
    uint16_t counter,
    const uint8_t ti[4],
    const uint8_t* data,
    size_t data_length,
    uint8_t mac[MF_PLUS_MAC_SIZE]) {
    // Header is cmd(1)+ctr(2)+TI(4)=7 bytes.
    furi_check(data_length <= MF_PLUS_CRYPTO_MAC_MAX_DATA);

    uint8_t buf[7 + MF_PLUS_CRYPTO_MAC_MAX_DATA];
    size_t n = 0;
    buf[n++] = cmd;
    buf[n++] = (uint8_t)(counter & 0xFF);
    buf[n++] = (uint8_t)((counter >> 8) & 0xFF);
    memcpy(&buf[n], ti, 4);
    n += 4;
    if(data && data_length > 0) {
        memcpy(&buf[n], data, data_length);
        n += data_length;
    }
    mf_plus_crypto_cmac8(k_mac, buf, n, mac);
}

atic void mf_plus_crypto_iv_counter_word(uint16_t r_ctr, uint16_t w_ctr, uint8_t word[4]) {
    word[0] = (uint8_t)(r_ctr & 0xFF);
    word[1] = (uint8_t)(r_ctr >> 8);
    word[2] = (uint8_t)(w_ctr & 0xFF);
    word[3] = (uint8_t)(w_ctr >> 8);
}

id mf_plus_crypto_build_read_iv(
    const uint8_t ti[4],
    uint16_t r_ctr,
    uint16_t w_ctr,
    uint8_t iv[MF_PLUS_AES_BLOCK_SIZE]) {
    // Read IV: counter word repeated across IV[0..11], TI at IV[12..15].
    uint8_t word[4];
    mf_plus_crypto_iv_counter_word(r_ctr, w_ctr, word);
    for(size_t i = 0; i < 3; i++) {
        memcpy(&iv[i * 4], word, sizeof(word));
    }
    memcpy(&iv[12], ti, 4);
}

id mf_plus_crypto_build_write_iv(
    const uint8_t ti[4],
    uint16_t r_ctr,
    uint16_t w_ctr,
    uint8_t iv[MF_PLUS_AES_BLOCK_SIZE]) {
    // Write IV: TI at IV[0..3], counter word repeated across IV[4..15].
    memcpy(&iv[0], ti, 4);
    uint8_t word[4];
    mf_plus_crypto_iv_counter_word(r_ctr, w_ctr, word);
    for(size_t i = 0; i < 3; i++) {
        memcpy(&iv[4 + i * 4], word, sizeof(word));
    }
}

id mf_plus_crypto_rotate_left(
    const uint8_t input[MF_PLUS_AES_BLOCK_SIZE],
    uint8_t output[MF_PLUS_AES_BLOCK_SIZE]) {
    memcpy(output, &input[1], MF_PLUS_AES_BLOCK_SIZE - 1);
    output[MF_PLUS_AES_BLOCK_SIZE - 1] = input[0];
}

uint16_t mf_plus_get_block_count(MfPlusSize size) {
    switch(size) {
    case MfPlusSize1K:
        return 64;
    case MfPlusSize2K:
        return 128;
    case MfPlusSize4K:
        return 256;
    default:
        return 0;
    }
}

uint8_t mf_plus_get_sector_count(MfPlusSize size) {
    switch(size) {
    case MfPlusSize1K:
        return 16;
    case MfPlusSize2K:
        return 32;
    case MfPlusSize4K:
        return 40;
    default:
        return 0;
    }
}

void mf_plus_set_block_read(MfPlusData* data, uint16_t block_num, const MfPlusBlock* block) {
    furi_check(block_num < MF_PLUS_MAX_BLOCKS);
    data->block[block_num] = *block;
    data->block_read_mask[block_num / 32] |= (1UL << (block_num % 32));
}

bool mf_plus_is_card_read(const MfPlusData* data) {
    // Fully read == every data block captured. The poller bumps its sector counter even when a
    // sector aborts on a MAC mismatch or a denied block, so this block-level check (not that
    // counter) is the honest full-vs-partial verdict, mirroring mf_classic_is_card_read.
    const uint16_t block_count = mf_plus_get_block_count(data->size);
    if(block_count == 0) return false;
    for(uint16_t i = 0; i < block_count; i++) {
        if(!mf_plus_is_block_read(data, i)) return false;
    }
    return true;
}

void mf_plus_get_read_sectors_and_keys(
    const MfPlusData* data,
    uint8_t* sectors_read,
    uint8_t* keys_found) {
    const uint8_t sectors = mf_plus_get_sector_count(data->size);
    uint8_t read = 0;
    uint8_t keys = 0;

    for(uint8_t s = 0; s < sectors; s++) {
        if(mf_plus_is_key_found(data, s, MfPlusKeyTypeA)) keys++;
        if(mf_plus_is_key_found(data, s, MfPlusKeyTypeB)) keys++;

        // A sector counts as read once all of its data blocks have been captured.
        const uint16_t first = mf_plus_sector_get_first_block(s);
        const uint8_t count = mf_plus_sector_get_block_count(s);
        bool all_read = true;
        for(uint8_t b = 0; b < count; b++) {
            if(!mf_plus_is_block_read(data, first + b)) {
                all_read = false;
                break;
            }
        }
        if(all_read) read++;
    }

    *sectors_read = read;
    *keys_found = keys;
}

bool mf_plus_is_key_found(const MfPlusData* data, uint8_t sector, MfPlusKeyType key_type) {
    furi_check(sector < MF_PLUS_MAX_SECTORS);
    const uint64_t mask = (key_type == MfPlusKeyTypeB) ? data->key_b_mask : data->key_a_mask;
    return (mask >> sector) & 1U;
}

void mf_plus_set_key_found(
    MfPlusData* data,
    uint8_t sector,
    MfPlusKeyType key_type,
    const MfPlusKey* key) {
    furi_check(sector < MF_PLUS_MAX_SECTORS);
    if(key_type == MfPlusKeyTypeB) {
        data->key_b[sector] = *key;
        data->key_b_mask |= (1ULL << sector);
    } else {
        data->key_a[sector] = *key;
        data->key_a_mask |= (1ULL << sector);
    }
}

void mf_plus_set_admin_key_found(MfPlusData* data, MfPlusAdminKeyType type, const MfPlusKey* key) {
    furi_check(type < MfPlusAdminKeyNum);
    data->admin_key[type] = *key;
    data->admin_key_mask |= (uint8_t)(1U << type);
}

void mf_plus_set_config_block_read(MfPlusData* data, uint8_t index, const MfPlusBlock* block) {
    furi_check(index < MF_PLUS_CONFIG_BLOCK_NUM);
    data->config_block[index] = *block;
    data->config_read_mask |= (uint8_t)(1U << index);
}

void mf_plus_merge_update(MfPlusData* base, const MfPlusData* fresh) {
    furi_check(base);
    furi_check(fresh);

    // Per-field overlay: copy only what `fresh` actually recovered, never clearing a field `base`
    // already had (see mf_plus.h for why a successful re-read can still come back with less).
    for(uint16_t block = 0; block < MF_PLUS_MAX_BLOCKS; block++) {
        if(mf_plus_is_block_read(fresh, block)) {
            mf_plus_set_block_read(base, block, &fresh->block[block]);
        }
    }
    for(uint8_t sector = 0; sector < MF_PLUS_MAX_SECTORS; sector++) {
        if(mf_plus_is_key_found(fresh, sector, MfPlusKeyTypeA)) {
            mf_plus_set_key_found(base, sector, MfPlusKeyTypeA, &fresh->key_a[sector]);
        }
        if(mf_plus_is_key_found(fresh, sector, MfPlusKeyTypeB)) {
            mf_plus_set_key_found(base, sector, MfPlusKeyTypeB, &fresh->key_b[sector]);
        }
    }
    for(uint8_t type = 0; type < MfPlusAdminKeyNum; type++) {
        if(mf_plus_is_admin_key_found(fresh, type)) {
            mf_plus_set_admin_key_found(base, type, &fresh->admin_key[type]);
        }
    }
    for(uint8_t index = 0; index < MF_PLUS_CONFIG_BLOCK_NUM; index++) {
        if(mf_plus_is_config_block_read(fresh, index)) {
            mf_plus_set_config_block_read(base, index, &fresh->config_block[index]);
        }
    }
    if(fresh->signature_present) {
        memcpy(base->signature, fresh->signature, MF_PLUS_SIGNATURE_SIZE);
        base->signature_present = true;
    }
}

static void mf_plus_bytes_to_str(FuriString* out, const uint8_t* data, size_t len, bool known) {
    furi_string_reset(out);
    for(size_t i = 0; i < len; i++) {
        if(known) {
            furi_string_cat_printf(out, "%02X ", data[i]);
        } else {
            furi_string_cat_printf(out, "?? ");
        }
    }
    furi_string_trim(out);
}

static bool mf_plus_str_to_bytes(FuriString* str, uint8_t* out, size_t len) {
    furi_check(len <= MF_PLUS_SIGNATURE_SIZE);
    furi_string_trim(str);
    if(furi_string_size(str) < (3 * len - 1)) return false; // truncated / too short
    if(furi_string_get_char(str, 0) == '?') return false; // legitimate unknown ("?? ..")

    uint8_t tmp[MF_PLUS_SIGNATURE_SIZE];
    for(size_t i = 0; i < len; i++) {
        char hi = furi_string_get_char(str, 3 * i);
        char lo = furi_string_get_char(str, 3 * i + 1);
        if(!hex_char_to_uint8(hi, lo, &tmp[i])) {
            FURI_LOG_W(TAG, "Corrupt MFP hex field, treating as unknown");
            return false;
        }
    }
    memcpy(out, tmp, len);
    return true;
}

bool mf_plus_sl3_data_save(const MfPlusData* data, FlipperFormat* ff) {
    bool saved = false;
    FuriString* key = furi_string_alloc();
    FuriString* val = furi_string_alloc();

    do {
        if(!flipper_format_write_uint32(
               ff, MF_PLUS_FFF_DATA_FORMAT_VERSION_KEY, &mf_plus_data_format_version, 1))
            break;

        bool ok = true;

        // Blocks / keys / config exist only for a fully-AES (SL3) card.
        if(data->security_level == MfPlusSecurityLevel3) {
            if(!flipper_format_write_comment_cstr(ff, "SL3 blocks and keys, \'??\' means unknown"))
                break;

            const uint16_t blocks = mf_plus_get_block_count(data->size);
            const uint8_t sectors = mf_plus_get_sector_count(data->size);

            for(uint16_t i = 0; ok && i < blocks; i++) {
                mf_plus_bytes_to_str(
                    val, data->block[i].data, MF_PLUS_BLOCK_SIZE, mf_plus_is_block_read(data, i));
                furi_string_printf(key, "Block %u", i);
                ok = flipper_format_write_string(ff, furi_string_get_cstr(key), val);
            }

            for(uint8_t s = 0; ok && s < sectors; s++) {
                mf_plus_bytes_to_str(
                    val, data->key_a[s].data, MF_PLUS_KEY_SIZE, (data->key_a_mask >> s) & 1U);
                furi_string_printf(key, "Key A %u", s);
                ok = flipper_format_write_string(ff, furi_string_get_cstr(key), val);
                if(!ok) break;

                mf_plus_bytes_to_str(
                    val, data->key_b[s].data, MF_PLUS_KEY_SIZE, (data->key_b_mask >> s) & 1U);
                furi_string_printf(key, "Key B %u", s);
                ok = flipper_format_write_string(ff, furi_string_get_cstr(key), val);
            }

            for(uint8_t a = 0; ok && a < MfPlusAdminKeyNum; a++) {
                mf_plus_bytes_to_str(
                    val,
                    data->admin_key[a].data,
                    MF_PLUS_KEY_SIZE,
                    (data->admin_key_mask >> a) & 1U);
                ok = flipper_format_write_string(ff, mf_plus_admin_key_names[a], val);
            }

            for(uint8_t c = 0; ok && c < MF_PLUS_CONFIG_BLOCK_NUM; c++) {
                mf_plus_bytes_to_str(
                    val,
                    data->config_block[c].data,
                    MF_PLUS_BLOCK_SIZE,
                    (data->config_read_mask >> c) & 1U);
                furi_string_printf(key, "Config Block %u", c);
                ok = flipper_format_write_string(ff, furi_string_get_cstr(key), val);
            }
        }
        if(!ok) break;

        // Originality signature, written LAST and only when the card actually has one. EV0/S/X have
        // none, so omitting it avoids a misleading all-"??" line; its absence loads as "no
        // signature". Level-independent (EV1/EV2 expose it at any security level).
        if(data->signature_present) {
            mf_plus_bytes_to_str(val, data->signature, MF_PLUS_SIGNATURE_SIZE, true);
            if(!flipper_format_write_string(ff, MF_PLUS_FFF_SIGNATURE_KEY, val)) break;
        }

        saved = true;
    } while(false);

    furi_string_free(key);
    furi_string_free(val);
    return saved;
}

bool mf_plus_sl3_data_load(MfPlusData* data, FlipperFormat* ff) {
    // Legacy metadata-only dumps have no "Data format version" -> nothing more to read.
    uint32_t dfv = 0;
    if(!flipper_format_read_uint32(ff, MF_PLUS_FFF_DATA_FORMAT_VERSION_KEY, &dfv, 1)) {
        return true;
    }
    // Refuse a payload written by a newer, unknown layout rather than misparsing it as v1.
    if(dfv > mf_plus_data_format_version) {
        FURI_LOG_W(TAG, "Unsupported MFP data format version %lu", (unsigned long)dfv);
        return false;
    }

    bool loaded = false;
    FuriString* key = furi_string_alloc();
    FuriString* val = furi_string_alloc();

    do {
        bool ok = true;

        if(data->security_level == MfPlusSecurityLevel3) {
            const uint16_t blocks = mf_plus_get_block_count(data->size);
            const uint8_t sectors = mf_plus_get_sector_count(data->size);

            MfPlusBlock block_tmp;
            MfPlusKey key_tmp;

            for(uint16_t i = 0; ok && i < blocks; i++) {
                furi_string_printf(key, "Block %u", i);
                ok = flipper_format_read_string(ff, furi_string_get_cstr(key), val);
                if(ok && mf_plus_str_to_bytes(val, block_tmp.data, MF_PLUS_BLOCK_SIZE)) {
                    mf_plus_set_block_read(data, i, &block_tmp);
                }
            }

            for(uint8_t s = 0; ok && s < sectors; s++) {
                furi_string_printf(key, "Key A %u", s);
                ok = flipper_format_read_string(ff, furi_string_get_cstr(key), val);
                if(ok && mf_plus_str_to_bytes(val, key_tmp.data, MF_PLUS_KEY_SIZE)) {
                    mf_plus_set_key_found(data, s, MfPlusKeyTypeA, &key_tmp);
                }
                if(!ok) break;

                furi_string_printf(key, "Key B %u", s);
                ok = flipper_format_read_string(ff, furi_string_get_cstr(key), val);
                if(ok && mf_plus_str_to_bytes(val, key_tmp.data, MF_PLUS_KEY_SIZE)) {
                    mf_plus_set_key_found(data, s, MfPlusKeyTypeB, &key_tmp);
                }
            }

            for(uint8_t a = 0; ok && a < MfPlusAdminKeyNum; a++) {
                ok = flipper_format_read_string(ff, mf_plus_admin_key_names[a], val);
                if(ok && mf_plus_str_to_bytes(val, key_tmp.data, MF_PLUS_KEY_SIZE)) {
                    mf_plus_set_admin_key_found(data, (MfPlusAdminKeyType)a, &key_tmp);
                }
            }

            for(uint8_t c = 0; ok && c < MF_PLUS_CONFIG_BLOCK_NUM; c++) {
                furi_string_printf(key, "Config Block %u", c);
                ok = flipper_format_read_string(ff, furi_string_get_cstr(key), val);
                if(ok && mf_plus_str_to_bytes(val, block_tmp.data, MF_PLUS_BLOCK_SIZE)) {
                    mf_plus_set_config_block_read(data, c, &block_tmp);
                }
            }
        }
        if(!ok) break;

        // The signature is written last and only when present, so its absence is not an error: it
        // simply means the card has no originality signature.
        data->signature_present = false;
        if(flipper_format_read_string(ff, MF_PLUS_FFF_SIGNATURE_KEY, val)) {
            data->signature_present =
                mf_plus_str_to_bytes(val, data->signature, MF_PLUS_SIGNATURE_SIZE);
        }

        loaded = true;
    } while(false);

    furi_string_free(key);
    furi_string_free(val);
    return loaded;
}

void mf_plus_listener_reset_session(MfPlusListener* instance) {
    furi_assert(instance);

    instance->state = MfPlusListenerStateIdle;
    memset(&instance->session, 0, sizeof(instance->session));
    memset(instance->rnd_b, 0, sizeof(instance->rnd_b));
    memset(&instance->auth_key, 0, sizeof(instance->auth_key));
    instance->get_version_stage = 0;
}

static MfPlusListener*
    mf_plus_listener_alloc(Iso14443_4aListener* iso14443_4a_listener, MfPlusData* data) {
    furi_assert(iso14443_4a_listener);
    furi_assert(data);

    MfPlusListener* instance = malloc(sizeof(MfPlusListener));
    instance->iso14443_4a_listener = iso14443_4a_listener;
    instance->data = data;
    instance->tx_buffer = bit_buffer_alloc(MF_PLUS_LISTENER_BUF_SIZE);

    instance->mfp_event.data = &instance->mfp_event_data;
    instance->generic_event.protocol = NfcProtocolMfPlus;
    instance->generic_event.instance = instance;
    instance->generic_event.event_data = &instance->mfp_event;

    mf_plus_listener_reset_session(instance);

    return instance;
}

static void mf_plus_listener_free(MfPlusListener* instance) {
    furi_assert(instance);
    furi_assert(instance->tx_buffer);

    bit_buffer_free(instance->tx_buffer);
    free(instance);
}

static void mf_plus_listener_set_callback(
    MfPlusListener* instance,
    NfcGenericCallback callback,
    void* context) {
    furi_assert(instance);

    instance->callback = callback;
    instance->context = context;
}

static const MfPlusData* mf_plus_listener_get_data(const MfPlusListener* instance) {
    furi_assert(instance);
    furi_assert(instance->data);

    return instance->data;
}

static NfcCommand mf_plus_listener_run(NfcGenericEvent event, void* context) {
    furi_assert(context);
    // The parent transport is ISO14443-4A (NOT ISO15693, as the type_4_tag template mistakenly
    // asserts) -- MfPlus is registered as a child of NfcProtocolIso14443_4a.
    furi_assert(event.protocol == NfcProtocolIso14443_4a);
    furi_assert(event.event_data);

    MfPlusListener* instance = context;
    Iso14443_4aListenerEvent* iso14443_4a_event = event.event_data;
    NfcCommand command = NfcCommandContinue;

    switch(iso14443_4a_event->type) {
    case Iso14443_4aListenerEventTypeFieldOff:
        mf_plus_listener_reset_session(instance);
        command = NfcCommandSleep;
        break;
    case Iso14443_4aListenerEventTypeHalted:
        mf_plus_listener_reset_session(instance);
        break;
    case Iso14443_4aListenerEventTypeReceivedData: {
        const BitBuffer* rx_buffer = iso14443_4a_event->data->buffer;
        const size_t rx_size = bit_buffer_get_size_bytes(rx_buffer);
        if(rx_size == 0) break;

        const uint8_t cmd = bit_buffer_get_byte(rx_buffer, 0);

        // GetVersion arrives native (0x60, then 0xAF continuations) or ISO7816-wrapped (0x90 0x60,
        // then 0x90 0xAF); peek the inner command byte to route both and to keep the multi-frame
        // chain alive across 0xAF. Any other command aborts an in-flight chain (below).
        const bool wrapped = (cmd == MF_PLUS_ISO_CLA && rx_size >= 2);
        const uint8_t inner = wrapped ? bit_buffer_get_byte(rx_buffer, 1) : cmd;
        if(inner == MF_PLUS_CMD_GET_VERSION) {
            command = mf_plus_listener_get_version_handler(instance, wrapped);
            break;
        }
        if(inner == MF_PLUS_CMD_ADDITIONAL_FRAME && instance->get_version_stage > 0) {
            command = mf_plus_listener_get_version_continue_handler(instance, wrapped);
            break;
        }
        instance->get_version_stage = 0;

        switch(cmd) {
        case MF_PLUS_CMD_AUTH_FIRST:
            command = mf_plus_listener_auth_first_handler(instance, rx_buffer);
            break;
        case MF_PLUS_CMD_AUTH_CONTINUE:
            command = mf_plus_listener_auth_continue_handler(instance, rx_buffer);
            break;
        case MF_PLUS_CMD_READ_ENC:
            command = mf_plus_listener_read_handler(instance, rx_buffer, false);
            break;
        case MF_PLUS_CMD_READ_PLAIN:
            command = mf_plus_listener_read_handler(instance, rx_buffer, true);
            break;
        case MF_PLUS_CMD_READ_SIG:
            command = mf_plus_listener_read_signature_handler(instance, rx_buffer);
            break;
        case MF_PLUS_CMD_WRITE_ENC:
            command = mf_plus_listener_write_handler(instance, rx_buffer, true);
            break;
        case MF_PLUS_CMD_WRITE_PLAIN:
            command = mf_plus_listener_write_handler(instance, rx_buffer, false);
            break;
        case MF_PLUS_CMD_WRITE_PERSO:
            command = mf_plus_listener_write_perso_handler(instance, rx_buffer);
            break;
        default:
            // Unimplemented command (non-first auth 0x76, wrapped non-GetVersion 0x90 xx, ...): NAK
            // it like a real card so a reader's info scan gets a response instead of timing out.
            // (GetVersion 0x60 is routed above -- served for EV1/EV2, NAKed for EV0.)
            FURI_LOG_D(TAG, "Unsupported command 0x%02X", cmd);
            command = mf_plus_listener_unsupported_handler(instance, rx_buffer);
            break;
        }
        break;
    }
    default:
        break;
    }

    return command;
}

static void mf_plus_listener_send(MfPlusListener* instance, const uint8_t* data, size_t len) {
    bit_buffer_reset(instance->tx_buffer);
    bit_buffer_copy_bytes(instance->tx_buffer, data, len);
    iso14443_4a_listener_send_block(instance->iso14443_4a_listener, instance->tx_buffer);
}

static bool
    mf_plus_listener_resolve_key(MfPlusListener* instance, uint16_t key_id, MfPlusKey* key) {
    const MfPlusData* data = instance->data;
    const uint8_t sector_count = mf_plus_get_sector_count(data->size);

    if(key_id >= 0x4000U && key_id < 0x4000U + 2U * sector_count) {
        const uint8_t sector = (uint8_t)((key_id - 0x4000U) >> 1);
        const MfPlusKeyType key_type = (MfPlusKeyType)((key_id - 0x4000U) & 1U);
        if(!mf_plus_is_key_found(data, sector, key_type)) return false;
        *key = (key_type == MfPlusKeyTypeB) ? data->key_b[sector] : data->key_a[sector];
        return true;
    }

    MfPlusAdminKeyType admin_type;
    switch(key_id) {
    case 0x9000:
        admin_type = MfPlusAdminKeyCardMaster;
        break;
    case 0x9001:
        admin_type = MfPlusAdminKeyCardConfig;
        break;
    case 0x9003:
        admin_type = MfPlusAdminKeyL3Switch;
        break;
    case 0x9004:
        admin_type = MfPlusAdminKeySL1CardAuth;
        break;
    default:
        return false;
    }
    if(!mf_plus_is_admin_key_found(data, admin_type)) return false;
    *key = data->admin_key[admin_type];
    return true;
}

static bool mf_plus_listener_resolve_block(
    MfPlusListener* instance,
    uint8_t block_low,
    uint8_t block_high,
    MfPlusBlock* out) {
    const MfPlusData* data = instance->data;

    if(block_high == 0x00) {
        if(block_low >= mf_plus_get_block_count(data->size)) return false;
        if(!mf_plus_is_block_read(data, block_low)) return false;
        *out = data->block[block_low];
        return true;
    }
    if(block_high == MF_PLUS_CONFIG_BLOCK_HIGH) {
        if(block_low >= MF_PLUS_CONFIG_BLOCK_NUM) return false;
        if(!mf_plus_is_config_block_read(data, block_low)) return false;
        *out = data->config_block[block_low];
        return true;
    }
    return false;
}

NfcCommand mf_plus_listener_auth_first_handler(MfPlusListener* instance, const BitBuffer* rx) {
    // [AUTH_FIRST, key_id_lo, key_id_hi, 0x00]
    if(bit_buffer_get_size_bytes(rx) < 4) {
        FURI_LOG_D(TAG, "AUTH_FIRST frame too short");
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_AUTH_ERROR);
        return NfcCommandContinue;
    }
    const uint16_t key_id = bit_buffer_get_byte(rx, 1) |
                            ((uint16_t)bit_buffer_get_byte(rx, 2) << 8);

    // A fresh AUTH_FIRST always restarts authentication.
    mf_plus_listener_reset_session(instance);

    if(!mf_plus_listener_resolve_key(instance, key_id, &instance->auth_key)) {
        // We never recovered this sector's key. A real card still answers AUTH_FIRST (it holds every
        // key) and only rejects a wrong key at AUTH_CONTINUE -- and some readers (e.g. a U-Prox
        // encoder) abort the whole exchange if AUTH_FIRST itself is NAKed. So run the handshake with
        // a random placeholder key: phase 1 completes normally, then the reader's phase-2 token can't
        // echo our RndB, so we NAK at AUTH_CONTINUE exactly as a real card rejects a wrong key.
        FURI_LOG_D(TAG, "AUTH_FIRST for unrecovered key 0x%04X (placeholder)", key_id);
        furi_hal_random_fill_buf(instance->auth_key.data, MF_PLUS_KEY_SIZE);
    }

    // Card picks RndB and returns E(key, RndB); the poller ECB-decrypts it with the same key.
    furi_hal_random_fill_buf(instance->rnd_b, sizeof(instance->rnd_b));

    uint8_t resp[1 + MF_PLUS_AES_BLOCK_SIZE];
    resp[0] = MF_PLUS_STATUS_OK;
    mf_plus_crypto_ecb_encrypt(instance->auth_key.data, instance->rnd_b, &resp[1]);

    mf_plus_listener_send(instance, resp, sizeof(resp));
    instance->state = MfPlusListenerStateAuthFirstDone;
    return NfcCommandContinue;
}

NfcCommand mf_plus_listener_auth_continue_handler(MfPlusListener* instance, const BitBuffer* rx) {
    // [AUTH_CONTINUE, E(key, iv=0, rrot(RndA) || rol(RndB)) (32)]
    if(instance->state != MfPlusListenerStateAuthFirstDone) {
        FURI_LOG_D(TAG, "AUTH_CONTINUE without a prior AUTH_FIRST (state=%d)", instance->state);
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_AUTH_ERROR);
        return NfcCommandContinue;
    }
    if(bit_buffer_get_size_bytes(rx) < 1 + 2 * MF_PLUS_AES_BLOCK_SIZE) {
        FURI_LOG_D(TAG, "AUTH_CONTINUE frame too short");
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_AUTH_ERROR);
        return NfcCommandContinue;
    }

    const uint8_t zero_iv[MF_PLUS_AES_BLOCK_SIZE] = {0};
    uint8_t dec[2 * MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_cbc_decrypt(
        instance->auth_key.data, zero_iv, bit_buffer_get_data(rx) + 1, dec, sizeof(dec));

    // dec = rrot(RndA) || rol(RndB). The RndB echo proves the reader holds our key.
    uint8_t rnd_b_rot[MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_rotate_left(instance->rnd_b, rnd_b_rot);
    if(memcmp(&dec[MF_PLUS_AES_BLOCK_SIZE], rnd_b_rot, MF_PLUS_AES_BLOCK_SIZE) != 0) {
        // Wrong key: the reader's token doesn't echo our RndB. NAK so a key check (PM3 `hf mfp chk`)
        // records a miss and advances instead of hanging on a timeout, which would desync its scan.
        FURI_LOG_D(TAG, "AUTH_CONTINUE RndB echo mismatch");
        mf_plus_listener_reset_session(instance);
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_AUTH_ERROR);
        return NfcCommandContinue;
    }

    const uint8_t* rnd_a_rrot = &dec[0]; // the value the card treats as RndA (rrot(RndA))

    // Establish the session: fresh TI, counters reset, session keys from rrot(RndA) + RndB (the
    // same inputs the poller derives from).
    MfPlusListenerSession* s = &instance->session;
    furi_hal_random_fill_buf(s->ti, sizeof(s->ti));
    s->r_ctr = 0;
    s->w_ctr = 0;
    mf_plus_crypto_derive_session_keys(
        instance->auth_key.data, rnd_a_rrot, instance->rnd_b, s->k_enc, s->k_mac);

    // Response = E(key, iv=0, TI(4) || RndA'(16) || caps). The reader expects rol(RndA). One
    // rotate-left of the extracted value satisfies both readers: for this port's poller (which put
    // rrot(RndA) here) it yields RndA (its 3rd accepted variant), and for a PM3-style reader (which
    // put RndA here) it yields rol(RndA). The cap bytes after are unused by the poller.
    uint8_t rnd_a_echo[MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_rotate_left(rnd_a_rrot, rnd_a_echo);

    uint8_t plain[2 * MF_PLUS_AES_BLOCK_SIZE] = {0};
    memcpy(&plain[0], s->ti, 4);
    memcpy(&plain[4], rnd_a_echo, MF_PLUS_AES_BLOCK_SIZE);

    uint8_t resp[1 + 2 * MF_PLUS_AES_BLOCK_SIZE];
    resp[0] = MF_PLUS_STATUS_OK;
    mf_plus_crypto_cbc_encrypt(instance->auth_key.data, zero_iv, plain, &resp[1], sizeof(plain));

    mf_plus_listener_send(instance, resp, sizeof(resp));
    instance->state = MfPlusListenerStateAuthenticated;
    return NfcCommandContinue;
}

NfcCommand
    mf_plus_listener_read_handler(MfPlusListener* instance, const BitBuffer* rx, bool plain) {
    // [READ, block_lo, block_hi, count, cmd_mac(8)]. Encrypted (0x31) and plaintext (0x33) reads
    // are identical except for the opcode fed into the MAC and whether the data is encrypted.
    if(instance->state != MfPlusListenerStateAuthenticated) {
        FURI_LOG_D(TAG, "READ before authentication (state=%d)", instance->state);
        return NfcCommandContinue;
    }
    if(bit_buffer_get_size_bytes(rx) < 4 + MF_PLUS_MAC_SIZE) {
        FURI_LOG_D(TAG, "READ frame too short");
        return NfcCommandContinue;
    }

    const uint8_t block_low = bit_buffer_get_byte(rx, 1);
    const uint8_t block_high = bit_buffer_get_byte(rx, 2);
    const uint8_t count = bit_buffer_get_byte(rx, 3);
    if(count != 0x01) {
        FURI_LOG_D(TAG, "READ count %u unsupported (single-block only)", count);
        return NfcCommandContinue;
    }

    MfPlusListenerSession* s = &instance->session;
    const uint8_t opcode = plain ? MF_PLUS_CMD_READ_PLAIN : MF_PLUS_CMD_READ_ENC;

    // Verify the command MAC (pre-increment r_ctr), same layout the poller builds.
    const uint8_t payload[3] = {block_low, block_high, count};
    uint8_t cmd_mac[MF_PLUS_MAC_SIZE];
    mf_plus_crypto_calculate_mac(
        s->k_mac, opcode, s->r_ctr, s->ti, payload, sizeof(payload), cmd_mac);
    if(memcmp(bit_buffer_get_data(rx) + 4, cmd_mac, MF_PLUS_MAC_SIZE) != 0) {
        FURI_LOG_D(TAG, "READ command MAC mismatch");
        return NfcCommandContinue;
    }

    MfPlusBlock block;
    if(!mf_plus_listener_resolve_block(instance, block_low, block_high, &block)) {
        FURI_LOG_D(TAG, "READ of unavailable block hi=0x%02X lo=%u", block_high, block_low);
        return NfcCommandContinue;
    }

    // The response MAC always uses the post-increment counter; an encrypted (0x31) read's IV too.
    s->r_ctr++;

    // Data travels as ciphertext for 0x31, plaintext for 0x33. The response MAC covers the bytes as
    // transmitted, so it is computed over whichever form goes on the wire.
    uint8_t data[MF_PLUS_BLOCK_SIZE];
    if(plain) {
        memcpy(data, block.data, MF_PLUS_BLOCK_SIZE);
    } else {
        uint8_t iv[MF_PLUS_AES_BLOCK_SIZE];
        mf_plus_crypto_build_read_iv(s->ti, s->r_ctr, s->w_ctr, iv);
        mf_plus_crypto_cbc_encrypt(s->k_enc, iv, block.data, data, MF_PLUS_BLOCK_SIZE);
    }

    uint8_t mac_input[sizeof(payload) + MF_PLUS_BLOCK_SIZE];
    memcpy(&mac_input[0], payload, sizeof(payload));
    memcpy(&mac_input[sizeof(payload)], data, MF_PLUS_BLOCK_SIZE);
    uint8_t resp_mac[MF_PLUS_MAC_SIZE];
    mf_plus_crypto_calculate_mac(
        s->k_mac, MF_PLUS_STATUS_OK, s->r_ctr, s->ti, mac_input, sizeof(mac_input), resp_mac);

    uint8_t resp[1 + MF_PLUS_BLOCK_SIZE + MF_PLUS_MAC_SIZE];
    resp[0] = MF_PLUS_STATUS_OK;
    memcpy(&resp[1], data, MF_PLUS_BLOCK_SIZE);
    memcpy(&resp[1 + MF_PLUS_BLOCK_SIZE], resp_mac, MF_PLUS_MAC_SIZE);

    mf_plus_listener_send(instance, resp, sizeof(resp));
    return NfcCommandContinue;
}

static bool mf_plus_listener_store_write(
    MfPlusListener* instance,
    uint16_t block_addr,
    const uint8_t* plain) {
    MfPlusData* data = instance->data;
    const uint8_t sector_count = mf_plus_get_sector_count(data->size);

    if(block_addr >= 0x4000U && block_addr < 0x4000U + 2U * sector_count) {
        const uint8_t sector = (uint8_t)((block_addr - 0x4000U) >> 1);
        const MfPlusKeyType key_type = (MfPlusKeyType)((block_addr - 0x4000U) & 1U);
        MfPlusKey key;
        memcpy(key.data, plain, MF_PLUS_KEY_SIZE);
        mf_plus_set_key_found(data, sector, key_type, &key);
        return true;
    }

    MfPlusAdminKeyType admin_type;
    bool is_admin = true;
    switch(block_addr) {
    case 0x9000:
        admin_type = MfPlusAdminKeyCardMaster;
        break;
    case 0x9001:
        admin_type = MfPlusAdminKeyCardConfig;
        break;
    case 0x9003:
        admin_type = MfPlusAdminKeyL3Switch;
        break;
    case 0x9004:
        admin_type = MfPlusAdminKeySL1CardAuth;
        break;
    default:
        is_admin = false;
        break;
    }
    if(is_admin) {
        MfPlusKey key;
        memcpy(key.data, plain, MF_PLUS_KEY_SIZE);
        mf_plus_set_admin_key_found(data, admin_type, &key);
        return true;
    }

    if(block_addr < mf_plus_get_block_count(data->size)) {
        MfPlusBlock block;
        memcpy(block.data, plain, MF_PLUS_BLOCK_SIZE);
        mf_plus_set_block_read(data, block_addr, &block);
        return true;
    }

    if((block_addr >> 8) == MF_PLUS_CONFIG_BLOCK_HIGH &&
       (block_addr & 0xFF) < MF_PLUS_CONFIG_BLOCK_NUM) {
        MfPlusBlock block;
        memcpy(block.data, plain, MF_PLUS_BLOCK_SIZE);
        mf_plus_set_config_block_read(data, (uint8_t)(block_addr & 0xFF), &block);
        return true;
    }

    return false;
}

NfcCommand
    mf_plus_listener_write_handler(MfPlusListener* instance, const BitBuffer* rx, bool encrypted) {
    // [WRITE, BNr_lo, BNr_hi, data(16), cmd_mac(8)]. 0xA1 = encrypted (keys; the block is
    // CBC-decrypted with the write IV), 0xA3 = plain (data blocks carry plaintext). Both MAC the
    // command; a reader writes only after authenticating.
    if(instance->state != MfPlusListenerStateAuthenticated) {
        FURI_LOG_D(TAG, "WRITE before authentication (state=%d)", instance->state);
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_CMD_UNAVAILABLE);
        return NfcCommandContinue;
    }
    if(bit_buffer_get_size_bytes(rx) < 3 + MF_PLUS_BLOCK_SIZE + MF_PLUS_MAC_SIZE) {
        FURI_LOG_D(TAG, "WRITE frame too short");
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_CMD_UNAVAILABLE);
        return NfcCommandContinue;
    }

    const uint8_t block_low = bit_buffer_get_byte(rx, 1);
    const uint8_t block_high = bit_buffer_get_byte(rx, 2);
    const uint16_t block_addr = block_low | ((uint16_t)block_high << 8);
    const uint8_t* wire_data = bit_buffer_get_data(rx) + 3; // 16 data bytes as transmitted
    const uint8_t* received_mac = bit_buffer_get_data(rx) + 3 + MF_PLUS_BLOCK_SIZE;

    MfPlusListenerSession* s = &instance->session;
    const uint8_t opcode = encrypted ? MF_PLUS_CMD_WRITE_ENC : MF_PLUS_CMD_WRITE_PLAIN;

    // Verify the command MAC (pre-increment w_ctr) over {BNr_lo, BNr_hi, data-as-transmitted}.
    uint8_t mac_input[2 + MF_PLUS_BLOCK_SIZE];
    mac_input[0] = block_low;
    mac_input[1] = block_high;
    memcpy(&mac_input[2], wire_data, MF_PLUS_BLOCK_SIZE);
    uint8_t cmd_mac[MF_PLUS_MAC_SIZE];
    mf_plus_crypto_calculate_mac(
        s->k_mac, opcode, s->w_ctr, s->ti, mac_input, sizeof(mac_input), cmd_mac);
    if(memcmp(received_mac, cmd_mac, MF_PLUS_MAC_SIZE) != 0) {
        FURI_LOG_D(TAG, "WRITE command MAC mismatch");
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_AUTH_ERROR);
        return NfcCommandContinue;
    }

    // Recover the plaintext: 0xA1 CBC-decrypts with the write IV (pre-increment w_ctr); 0xA3 already
    // carries plaintext.
    uint8_t plain[MF_PLUS_BLOCK_SIZE];
    if(encrypted) {
        uint8_t iv[MF_PLUS_AES_BLOCK_SIZE];
        mf_plus_crypto_build_write_iv(s->ti, s->r_ctr, s->w_ctr, iv);
        mf_plus_crypto_cbc_decrypt(s->k_enc, iv, wire_data, plain, MF_PLUS_BLOCK_SIZE);
    } else {
        memcpy(plain, wire_data, MF_PLUS_BLOCK_SIZE);
    }

    if(!mf_plus_listener_store_write(instance, block_addr, plain)) {
        FURI_LOG_D(TAG, "WRITE to unsupported address 0x%04X", block_addr);
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_CMD_UNAVAILABLE);
        return NfcCommandContinue;
    }

    // Write accepted: advance w_ctr, then MAC the OK status over the post-increment counter.
    s->w_ctr++;
    uint8_t resp_mac[MF_PLUS_MAC_SIZE];
    mf_plus_crypto_calculate_mac(s->k_mac, MF_PLUS_STATUS_OK, s->w_ctr, s->ti, NULL, 0, resp_mac);

    uint8_t resp[1 + MF_PLUS_MAC_SIZE];
    resp[0] = MF_PLUS_STATUS_OK;
    memcpy(&resp[1], resp_mac, MF_PLUS_MAC_SIZE);
    mf_plus_listener_send(instance, resp, sizeof(resp));
    return NfcCommandContinue;
}

NfcCommand mf_plus_listener_read_signature_handler(MfPlusListener* instance, const BitBuffer* rx) {
    // [READ_SIG, 0x00]. The originality signature is level-independent and needs no auth.
    UNUSED(rx);
    if(!instance->data->signature_present) {
        // No signature to serve (an EV0/S/X part has none): NAK like a card that doesn't support the
        // command, so the reader's info scan gets a response instead of a timeout.
        FURI_LOG_D(TAG, "READ_SIG but card has no originality signature");
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_CMD_UNAVAILABLE);
        return NfcCommandContinue;
    }

    uint8_t resp[1 + MF_PLUS_SIGNATURE_SIZE];
    resp[0] = MF_PLUS_STATUS_OK;
    memcpy(&resp[1], instance->data->signature, MF_PLUS_SIGNATURE_SIZE);

    mf_plus_listener_send(instance, resp, sizeof(resp));
    return NfcCommandContinue;
}

NfcCommand mf_plus_listener_write_perso_handler(MfPlusListener* instance, const BitBuffer* rx) {
    // The probe fires WritePerso at an invalid block purely to read its rejection status, and a real
    // card needs neither auth nor a particular state to reject it -- so ignore the frame and
    // unconditionally answer the SL3 status. (This listener only ever emulates SL3.)
    UNUSED(rx);
    mf_plus_listener_send_status(instance, MF_PLUS_STATUS_CMD_UNAVAILABLE);
    return NfcCommandContinue;
}

NfcCommand mf_plus_listener_unsupported_handler(MfPlusListener* instance, const BitBuffer* rx) {
    // Any command this listener doesn't implement (non-first auth 0x76, ...). A real card NAKs it
    // rather than staying silent, so answer 0x0B: this keeps a reader's info scan from stalling on
    // "no response", and reading it back still falls through to ATS-based typing.
    UNUSED(rx);
    mf_plus_listener_send_status(instance, MF_PLUS_STATUS_CMD_UNAVAILABLE);
    return NfcCommandContinue;
}

static void mf_plus_listener_send_version_frame(
    MfPlusListener* instance,
    bool wrapped,
    uint8_t status,
    const uint8_t* chunk,
    size_t chunk_len) {
    uint8_t resp[MF_PLUS_BLOCK_SIZE + 2]; // longest chunk is 14 bytes, plus up to 2 status bytes
    size_t len = 0;
    if(wrapped) {
        memcpy(resp, chunk, chunk_len);
        len = chunk_len;
        resp[len++] = MF_PLUS_ISO_SW1;
        resp[len++] = status;
    } else {
        resp[len++] = status;
        memcpy(&resp[len], chunk, chunk_len);
        len += chunk_len;
    }
    mf_plus_listener_send(instance, resp, len);
}

NfcCommand mf_plus_listener_get_version_handler(MfPlusListener* instance, bool wrapped) {
    if(!mf_plus_listener_has_version(instance)) {
        // EV0 (S/X/SE) has no GetVersion; NAK 0x0B like the real chip (this is TagInfo's EV gate).
        instance->get_version_stage = 0;
        FURI_LOG_D(TAG, "GetVersion but card is EV0 (no version)");
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_CMD_UNAVAILABLE);
        return NfcCommandContinue;
    }
    // MfPlusVersion is a packed 28-byte record (7 HW || 7 SW || 7 UID || 5 batch || week || year), so
    // replaying it in three chunks reproduces the real 0x60 -> 0xAF -> 0xAF exchange. Frame 1 = the 7
    // HW bytes with the "more frames" status.
    const uint8_t* v = (const uint8_t*)&instance->data->version;
    mf_plus_listener_send_version_frame(
        instance, wrapped, MF_PLUS_STATUS_ADDITIONAL_FRAME, &v[0], 7);
    instance->get_version_stage = 1;
    return NfcCommandContinue;
}

NfcCommand mf_plus_listener_get_version_continue_handler(MfPlusListener* instance, bool wrapped) {
    const uint8_t* v = (const uint8_t*)&instance->data->version;
    if(instance->get_version_stage == 1) {
        // Frame 2: the 7 SW bytes, still "more frames".
        mf_plus_listener_send_version_frame(
            instance, wrapped, MF_PLUS_STATUS_ADDITIONAL_FRAME, &v[7], 7);
        instance->get_version_stage = 2;
    } else {
        // Frame 3 (final): UID + batch + production date, ended with 0x90 (OK) -- a real MFP ends
        // non-zero, unlike DESFire's 0x00.
        mf_plus_listener_send_version_frame(instance, wrapped, MF_PLUS_STATUS_OK, &v[14], 14);
        instance->get_version_stage = 0;
    }
    return NfcCommandContinue;
}

static void mf_plus_poller_read_advance(MfPlusPoller* instance) {
    if(instance->current_key_type == MfPlusKeyTypeA) {
        instance->current_key_type = MfPlusKeyTypeB;
        instance->state = MfPlusPollerStateRequestKey;
        return;
    }

    instance->current_sector++;
    instance->current_key_type = MfPlusKeyTypeA;
    instance->sector_blocks_read = false;
    if(instance->current_sector >= mf_plus_get_sector_count(instance->data->size)) {
        instance->current_admin = 0;
        instance->state = MfPlusPollerStateRequestAdminKey;
    } else {
        instance->state = MfPlusPollerStateRequestKey;
    }
}

static void mf_plus_poller_admin_advance(MfPlusPoller* instance) {
    instance->current_admin++;
    if(instance->current_admin >= MfPlusAdminKeyNum) {
        instance->state = MfPlusPollerStateReadSuccess;
    } else {
        instance->state = MfPlusPollerStateRequestAdminKey;
    }
}

static NfcCommand mf_plus_poller_handler_request_mode(MfPlusPoller* instance) {
    furi_assert(instance);

    instance->mfp_event.data->mode_request.mode = MfPlusPollerModeInfo;
    instance->mfp_event.type = MfPlusPollerEventTypeRequestMode;
    NfcCommand command = instance->callback(instance->general_event, instance->context);
    instance->mode = instance->mfp_event.data->mode_request.mode;

    // Secure-messaging flows only make sense on an SL3 card; otherwise just report identity.
    if(instance->data->security_level == MfPlusSecurityLevel3 &&
       instance->mode == MfPlusPollerModeRead) {
        instance->state = MfPlusPollerStateReadSignature;
    } else if(
        instance->data->security_level == MfPlusSecurityLevel3 &&
        instance->mode == MfPlusPollerModeWrite) {
        instance->current_sector = 0;
        instance->current_block = 0;
        instance->write_plain = false;
        instance->write_mode_locked = false;
        instance->state = MfPlusPollerStateRequestWriteSector;
    } else {
        instance->state = MfPlusPollerStateReadSuccess;
    }
    return command;
}

static NfcCommand mf_plus_poller_handler_read_signature(MfPlusPoller* instance) {
    furi_assert(instance);

    // Best-effort: a card without (or rejecting) an originality signature must not fail the read.
    bool present = false;
    MfPlusError error =
        mf_plus_poller_read_signature(instance, instance->data->signature, &present);
    instance->data->signature_present = present;
    if(error != MfPlusErrorNone) {
        FURI_LOG_D(TAG, "Signature read error %d (ignored)", error);
    } else if(!present) {
        FURI_LOG_D(TAG, "Card has no originality signature");
    }

    instance->current_sector = 0;
    instance->current_key_type = MfPlusKeyTypeA;
    instance->sector_blocks_read = false;
    instance->sectors_read = 0;
    instance->keys_found = 0;
    instance->read_plain = false;
    instance->read_mode_locked = false;
    instance->current_admin = 0;
    instance->admin_keys_found = 0;
    instance->current_config_block = 0;
    // Guard a (spurious) 0-sector card so RequestKey isn't entered for a nonexistent sector.
    instance->state = (mf_plus_get_sector_count(instance->data->size) == 0) ?
                          MfPlusPollerStateReadSuccess :
                          MfPlusPollerStateRequestKey;
    return NfcCommandContinue;
}

static NfcCommand mf_plus_poller_handler_request_key(MfPlusPoller* instance) {
    furi_assert(instance);

    // Key iteration is delegated to the app: it must eventually answer key_provided = false so the
    // scan advances (there is no poller-side attempt cap). Mirrors the mf_classic dict-attack loop.
    instance->mfp_event.data->key_request.is_admin = false;
    instance->mfp_event.data->key_request.sector = instance->current_sector;
    instance->mfp_event.data->key_request.key_type = instance->current_key_type;
    instance->mfp_event.data->key_request.key_provided = false;
    instance->mfp_event.type = MfPlusPollerEventTypeRequestKey;
    NfcCommand command = instance->callback(instance->general_event, instance->context);

    if(instance->mfp_event.data->key_request.key_provided) {
        instance->current_key = instance->mfp_event.data->key_request.key;
        instance->state = MfPlusPollerStateAuthSector;
    } else {
        // No (more) candidate keys for this sector/type.
        mf_plus_poller_read_advance(instance);
    }
    return command;
}

static NfcCommand mf_plus_poller_handler_auth_sector(MfPlusPoller* instance) {
    furi_assert(instance);

    MfPlusError error = mf_plus_poller_authenticate(
        instance,
        instance->current_sector,
        instance->current_key_type,
        &instance->current_key,
        &instance->session);

    if(error == MfPlusErrorNone) {
        mf_plus_set_key_found(
            instance->data,
            instance->current_sector,
            instance->current_key_type,
            &instance->current_key);
        instance->keys_found++;

        if(instance->sector_blocks_read) {
            // Blocks already captured via the other key -> just record this key and move on.
            mf_plus_poller_read_advance(instance);
        } else {
            instance->current_block = mf_plus_sector_get_first_block(instance->current_sector);
            instance->state = MfPlusPollerStateReadSectorBlocks;
        }
    } else if(error == MfPlusErrorAuth) {
        // The card rejected our token: a genuine wrong key -> ask the app for the next candidate.
        instance->state = MfPlusPollerStateRequestKey;
    } else {
        // A comms/RF fault (or lost card) is NOT a wrong key: fail loudly rather than silently
        // dropping a possibly-correct key and leaving the sector unread.
        FURI_LOG_W(TAG, "Auth error %d at sector %u", error, instance->current_sector);
        instance->error = error;
        instance->state = MfPlusPollerStateReadFailed;
    }
    return NfcCommandContinue;
}

static NfcCommand mf_plus_poller_handler_read_sector_blocks(MfPlusPoller* instance) {
    furi_assert(instance);

    const uint8_t sector = instance->current_sector;
    const uint16_t end_block =
        mf_plus_sector_get_first_block(sector) + mf_plus_sector_get_block_count(sector);

    MfPlusBlock block;
    MfPlusError error = mf_plus_poller_read_block(
        instance,
        (uint8_t)instance->current_block,
        0x00,
        instance->read_plain,
        &instance->session,
        &block);

    // Read-mode probe. Some SL3 cards require plaintext (0x33) reads instead of encrypted (0x31).
    // Until a block has been read successfully (read_mode_locked), a status rejection (Rejected, a
    // bare status frame that leaves r_ctr in sync) means "wrong mode": re-authenticate this sector
    // and retry the SAME block in the other mode, in-line. Only a success adopts the other mode, so
    // a block that both modes refuse is treated as unreadable (not a mode signal) and skipped with
    // the mode unchanged -- the next block re-probes. A transient comms fault (Protocol/Timeout) is
    // NOT a Rejected, so it never flips the mode.
    if(error == MfPlusErrorRejected && !instance->read_mode_locked) {
        const bool other_plain = !instance->read_plain;
        FURI_LOG_D(
            TAG,
            "Read refused on block %u; probing %s mode",
            instance->current_block,
            other_plain ? "plain" : "encrypted");
        MfPlusError reauth = mf_plus_poller_authenticate(
            instance,
            sector,
            instance->current_key_type,
            &instance->current_key,
            &instance->session);
        if(reauth != MfPlusErrorNone) {
            error = reauth;
        } else {
            error = mf_plus_poller_read_block(
                instance,
                (uint8_t)instance->current_block,
                0x00,
                other_plain,
                &instance->session,
                &block);
            if(error == MfPlusErrorNone) {
                instance->read_plain = other_plain; // the other mode works -> adopt it card-wide
            }
        }
    }

    bool sector_complete;
    if(error == MfPlusErrorNone) {
        instance->read_mode_locked = true; // a successful read pins the card-wide read mode
        mf_plus_set_block_read(instance->data, instance->current_block, &block);
        instance->current_block++;
        sector_complete = instance->current_block >= end_block;
    } else if(error == MfPlusErrorNotPresent || error == MfPlusErrorTimeout) {
        instance->error = error;
        instance->state = MfPlusPollerStateReadFailed;
        return NfcCommandContinue;
    } else if(error == MfPlusErrorAuth) {
        // A response-MAC mismatch (or a failed probe re-auth) means r_ctr is desynced, so the rest
        // of this sector can't be read reliably. Abort it (the next sector re-authenticates and
        // resets the counter).
        FURI_LOG_W(
            TAG, "Block %u auth failure; aborting sector %u", instance->current_block, sector);
        sector_complete = true;
    } else {
        // Access-denied / transient / refused-in-both-modes: leave this block unread and try the
        // next one. The mode is left unchanged (and unlocked if still probing).
        FURI_LOG_D(TAG, "Skipping block %u (error %d)", instance->current_block, error);
        instance->current_block++;
        sector_complete = instance->current_block >= end_block;
    }

    if(!sector_complete) {
        return NfcCommandContinue;
    }

    instance->sector_blocks_read = true;
    instance->sectors_read++;

    instance->mfp_event.data->data_update.current_sector = sector;
    instance->mfp_event.data->data_update.sectors_read = instance->sectors_read;
    instance->mfp_event.data->data_update.keys_found = instance->keys_found;
    instance->mfp_event.type = MfPlusPollerEventTypeDataUpdate;
    NfcCommand command = instance->callback(instance->general_event, instance->context);

    mf_plus_poller_read_advance(instance);
    return command;
}

static bool mf_plus_poller_config_incomplete(const MfPlusPoller* instance) {
    for(uint8_t c = 0; c < MF_PLUS_CONFIG_BLOCK_NUM; c++) {
        if(!mf_plus_is_config_block_read(instance->data, c)) return true;
    }
    return false;
}

static NfcCommand mf_plus_poller_handler_request_admin_key(MfPlusPoller* instance) {
    furi_assert(instance);

    // Same app-driven dictionary loop as sectors, but the target is an admin key (0x90xx). The app
    // must eventually answer key_provided = false so the scan advances to the next admin key.
    instance->mfp_event.data->key_request.is_admin = true;
    instance->mfp_event.data->key_request.admin_type = (MfPlusAdminKeyType)instance->current_admin;
    instance->mfp_event.data->key_request.key_provided = false;
    instance->mfp_event.type = MfPlusPollerEventTypeRequestKey;
    NfcCommand command = instance->callback(instance->general_event, instance->context);

    if(instance->mfp_event.data->key_request.key_provided) {
        instance->current_key = instance->mfp_event.data->key_request.key;
        instance->state = MfPlusPollerStateAuthAdminKey;
    } else {
        mf_plus_poller_admin_advance(instance);
    }
    return command;
}

static NfcCommand mf_plus_poller_handler_auth_admin_key(MfPlusPoller* instance) {
    furi_assert(instance);

    const MfPlusAdminKeyType admin_type = (MfPlusAdminKeyType)instance->current_admin;
    MfPlusError error = mf_plus_poller_authenticate_key_id(
        instance, mf_plus_admin_key_id[admin_type], &instance->current_key, &instance->session);

    if(error == MfPlusErrorNone) {
        mf_plus_set_admin_key_found(instance->data, admin_type, &instance->current_key);
        instance->admin_keys_found++;
        // The Card Master / Config key unlocks the 0xB0xx config blocks; read them now while this
        // session is fresh (any later admin auth resets it).
        const bool unlocks_config =
            (admin_type == MfPlusAdminKeyCardMaster || admin_type == MfPlusAdminKeyCardConfig);
        if(unlocks_config && mf_plus_poller_config_incomplete(instance)) {
            instance->current_config_block = 0;
            instance->state = MfPlusPollerStateReadConfig;
        } else {
            mf_plus_poller_admin_advance(instance);
        }
    } else if(error == MfPlusErrorAuth) {
        // Wrong candidate -> ask for the next dictionary candidate for this same admin key.
        instance->state = MfPlusPollerStateRequestAdminKey;
    } else if(error == MfPlusErrorNotPresent || error == MfPlusErrorTimeout) {
        // The card is gone. Every sector was already captured before the admin phase, so finish
        // with what we have rather than downgrading an otherwise-complete read to a failure.
        FURI_LOG_D(TAG, "Card lost during admin phase (error %d)", error);
        instance->state = MfPlusPollerStateReadSuccess;
    } else {
        // The card rejected AUTH_FIRST for this address: the slot is not exposed on this card (a
        // present sector/admin slot always answers AUTH_FIRST regardless of the candidate). Skip
        // the whole key -- re-probing it with every remaining dict candidate is pointless -- and
        // keep the read; admin keys are best-effort bonus that must not fail a complete read.
        FURI_LOG_D(TAG, "Admin key %u unavailable (error %d)", instance->current_admin, error);
        mf_plus_poller_admin_advance(instance);
    }
    return NfcCommandContinue;
}

static NfcCommand mf_plus_poller_handler_read_config(MfPlusPoller* instance) {
    furi_assert(instance);

    // Skip blocks already captured (e.g. by the CMK pass before this CCK pass).
    while(instance->current_config_block < MF_PLUS_CONFIG_BLOCK_NUM &&
          mf_plus_is_config_block_read(instance->data, instance->current_config_block)) {
        instance->current_config_block++;
    }
    if(instance->current_config_block >= MF_PLUS_CONFIG_BLOCK_NUM) {
        mf_plus_poller_admin_advance(instance);
        return NfcCommandContinue;
    }

    MfPlusBlock block;
    // Config blocks (0xB0xx) are always read encrypted via the CMK/CCK session.
    MfPlusError error = mf_plus_poller_read_block(
        instance,
        instance->current_config_block,
        MF_PLUS_CONFIG_BLOCK_HIGH,
        false,
        &instance->session,
        &block);

    if(error == MfPlusErrorNone) {
        mf_plus_set_config_block_read(instance->data, instance->current_config_block, &block);
        instance->current_config_block++;
    } else if(error == MfPlusErrorNotPresent || error == MfPlusErrorTimeout) {
        // Card gone during the bonus config read: finish with the (already complete) sector data
        // rather than failing the read.
        FURI_LOG_D(TAG, "Card lost during config read (error %d)", error);
        instance->state = MfPlusPollerStateReadSuccess;
    } else if(error == MfPlusErrorAuth) {
        // MAC mismatch desyncs r_ctr: this session can't read the rest. Abort the pass WITHOUT
        // marking config done, so a subsequent CMK/CCK auth re-authenticates and retries.
        FURI_LOG_W(
            TAG,
            "Config block %u MAC mismatch; aborting config pass",
            instance->current_config_block);
        mf_plus_poller_admin_advance(instance);
    } else {
        // Access-denied (a block this key does not own) or transient: leave it unread and try the
        // next, same as an unreadable data block. Config is best-effort and never fails the read.
        FURI_LOG_D(
            TAG, "Skipping config block %u (error %d)", instance->current_config_block, error);
        instance->current_config_block++;
    }
    return NfcCommandContinue;
}

static NfcCommand mf_plus_poller_handler_request_write_sector(MfPlusPoller* instance) {
    furi_assert(instance);

    if(instance->current_sector >= mf_plus_get_sector_count(instance->data->size)) {
        instance->state = MfPlusPollerStateWriteSuccess;
        return NfcCommandContinue;
    }

    // Ask the app for the recovered AES key of this sector (from the loaded dump).
    instance->mfp_event.data->write_sector_request.sector = instance->current_sector;
    instance->mfp_event.data->write_sector_request.key_provided = false;
    instance->mfp_event.type = MfPlusPollerEventTypeRequestWriteSector;
    NfcCommand command = instance->callback(instance->general_event, instance->context);

    if(instance->mfp_event.data->write_sector_request.key_provided) {
        instance->current_key = instance->mfp_event.data->write_sector_request.key;
        instance->current_key_type = instance->mfp_event.data->write_sector_request.key_type;
        instance->state = MfPlusPollerStateAuthWriteSector;
    } else {
        // No recovered key for this sector -> it can't be authenticated to write. Skip it.
        mf_plus_poller_write_advance(instance);
    }
    return command;
}

static NfcCommand mf_plus_poller_handler_auth_write_sector(MfPlusPoller* instance) {
    furi_assert(instance);

    MfPlusError error = mf_plus_poller_authenticate(
        instance,
        instance->current_sector,
        instance->current_key_type,
        &instance->current_key,
        &instance->session);

    if(error == MfPlusErrorNone) {
        instance->current_block = mf_plus_sector_get_first_block(instance->current_sector);
        instance->state = MfPlusPollerStateRequestWriteBlock;
    } else if(error == MfPlusErrorAuth) {
        // The supplied key (which the dump recovered) is rejected by the source card: something is
        // wrong (wrong card slipped past the UID check, or a re-keyed sector). Fail the write.
        FURI_LOG_W(TAG, "Write auth failed at sector %u", instance->current_sector);
        instance->error = error;
        instance->state = MfPlusPollerStateWriteFailed;
    } else {
        instance->error = error;
        instance->state = MfPlusPollerStateWriteFailed;
    }
    return NfcCommandContinue;
}

static NfcCommand mf_plus_poller_handler_request_write_block(MfPlusPoller* instance) {
    furi_assert(instance);

    const uint16_t end_block = mf_plus_sector_get_first_block(instance->current_sector) +
                               mf_plus_sector_get_block_count(instance->current_sector);
    if(instance->current_block >= end_block) {
        mf_plus_poller_write_advance(instance);
        return NfcCommandContinue;
    }

    instance->mfp_event.data->write_block_request.block_num = instance->current_block;
    instance->mfp_event.data->write_block_request.block_provided = false;
    instance->mfp_event.type = MfPlusPollerEventTypeRequestWriteBlock;
    NfcCommand command = instance->callback(instance->general_event, instance->context);

    if(instance->mfp_event.data->write_block_request.block_provided) {
        instance->current_write_block = instance->mfp_event.data->write_block_request.block;
        instance->state = MfPlusPollerStateWriteBlock;
    } else {
        // Block not captured in the dump -> nothing to write here; skip it.
        instance->current_block++;
    }
    return command;
}

static NfcCommand mf_plus_poller_handler_write_block(MfPlusPoller* instance) {
    furi_assert(instance);

    MfPlusError error = mf_plus_poller_write_block(
        instance,
        (uint8_t)instance->current_block,
        0x00,
        instance->write_plain,
        &instance->current_write_block,
        &instance->session);

    // Write-mode probe, mirroring the read handler. Until a block has been written successfully
    // (write_mode_locked), a card status rejection (Rejected) means "wrong mode": re-authenticate
    // this sector and retry the SAME block in the other mode, in-line. The other mode is adopted
    // only on success, so a block refused in both modes is treated as access-denied (not a mode
    // signal) and skipped with the mode unchanged. A transient comms fault never flips the mode.
    if(error == MfPlusErrorRejected && !instance->write_mode_locked) {
        const bool other_plain = !instance->write_plain;
        FURI_LOG_D(
            TAG,
            "Write refused on block %u; probing %s mode",
            instance->current_block,
            other_plain ? "plain" : "encrypted");
        MfPlusError reauth = mf_plus_poller_authenticate(
            instance,
            instance->current_sector,
            instance->current_key_type,
            &instance->current_key,
            &instance->session);
        if(reauth != MfPlusErrorNone) {
            error = reauth;
        } else {
            error = mf_plus_poller_write_block(
                instance,
                (uint8_t)instance->current_block,
                0x00,
                other_plain,
                &instance->current_write_block,
                &instance->session);
            if(error == MfPlusErrorNone) {
                instance->write_plain = other_plain; // the other mode works -> adopt it card-wide
            }
        }
    }

    if(error == MfPlusErrorNone) {
        instance->write_mode_locked = true; // a successful write pins the card-wide write mode
        instance->current_block++;
        instance->state = MfPlusPollerStateRequestWriteBlock;
    } else if(error == MfPlusErrorNotPresent || error == MfPlusErrorTimeout) {
        instance->error = error;
        instance->state = MfPlusPollerStateWriteFailed;
    } else if(error == MfPlusErrorAuth) {
        // Response-MAC mismatch: the session crypto is desynced, so the rest can't be trusted.
        FURI_LOG_W(TAG, "Write block %u MAC desync; failing", instance->current_block);
        instance->error = error;
        instance->state = MfPlusPollerStateWriteFailed;
    } else {
        // Access-denied / refused-in-both-modes / transient: leave this block and try the next.
        FURI_LOG_D(TAG, "Skipping write of block %u (error %d)", instance->current_block, error);
        instance->current_block++;
        instance->state = MfPlusPollerStateRequestWriteBlock;
    }
    return NfcCommandContinue;
}

static NfcCommand mf_plus_poller_handler_write_failed(MfPlusPoller* instance) {
    furi_assert(instance);

    FURI_LOG_D(TAG, "Write failed");
    iso14443_4a_poller_halt(instance->iso14443_4a_poller);

    instance->mfp_event.type = MfPlusPollerEventTypeWriteFailed;
    instance->mfp_event.data->error = instance->error;
    NfcCommand command = instance->callback(instance->general_event, instance->context);
    instance->state = MfPlusPollerStateIdle;

    return command;
}

static NfcCommand mf_plus_poller_handler_write_success(MfPlusPoller* instance) {
    furi_assert(instance);

    FURI_LOG_D(TAG, "Write success");
    iso14443_4a_poller_halt(instance->iso14443_4a_poller);

    instance->mfp_event.type = MfPlusPollerEventTypeWriteSuccess;
    NfcCommand command = instance->callback(instance->general_event, instance->context);

    return command;
}

static MfPlusError mf_plus_poller_send_raw(
    MfPlusPoller* instance,
    const uint8_t* cmd,
    size_t cmd_len,
    uint8_t* resp,
    size_t* resp_len,
    size_t resp_capacity) {
    bit_buffer_reset(instance->input_buffer);
    bit_buffer_copy_bytes(instance->input_buffer, cmd, cmd_len);
    bit_buffer_reset(instance->result_buffer);

    Iso14443_4aError error = iso14443_4a_poller_send_block(
        instance->iso14443_4a_poller, instance->input_buffer, instance->result_buffer);
    if(error != Iso14443_4aErrorNone) {
        return mf_plus_process_error(error);
    }

    size_t len = bit_buffer_get_size_bytes(instance->result_buffer);
    if(len > resp_capacity) {
        FURI_LOG_W(TAG, "Truncating %zu-byte response to %zu", len, resp_capacity);
        len = resp_capacity;
    }
    memcpy(resp, bit_buffer_get_data(instance->result_buffer), len);
    *resp_len = len;
    return MfPlusErrorNone;
}

MfPlusError mf_plus_poller_authenticate_key_id(
    MfPlusPoller* instance,
    uint16_t key_id,
    const MfPlusKey* key,
    MfPlusPollerSession* session) {
    furi_check(instance);
    furi_check(key);
    furi_check(session);

    // Part 1: request E(key, RndB). The card answers regardless of whether the key is correct;
    // the key is only proven in Part 2.
    const uint8_t cmd1[4] = {
        MF_PLUS_CMD_AUTH_FIRST, (uint8_t)(key_id & 0xFF), (uint8_t)(key_id >> 8), 0x00};
    uint8_t resp[64];
    size_t resp_len = 0;
    MfPlusError error =
        mf_plus_poller_send_raw(instance, cmd1, sizeof(cmd1), resp, &resp_len, sizeof(resp));
    if(error != MfPlusErrorNone) return error;
    if(resp_len < 1 + MF_PLUS_AES_BLOCK_SIZE || resp[0] != MF_PLUS_STATUS_OK) {
        return MfPlusErrorProtocol;
    }

    uint8_t rnd_b[MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_ecb_decrypt(key->data, &resp[1], rnd_b);

    // Our RndA, and rrot(RndA) (rotate right one byte) — the value the card echoes and keys off.
    uint8_t rnd_a[MF_PLUS_AES_BLOCK_SIZE];
    furi_hal_random_fill_buf(rnd_a, sizeof(rnd_a));
    uint8_t rnd_a_rrot[MF_PLUS_AES_BLOCK_SIZE];
    rnd_a_rrot[0] = rnd_a[MF_PLUS_AES_BLOCK_SIZE - 1];
    memcpy(&rnd_a_rrot[1], rnd_a, MF_PLUS_AES_BLOCK_SIZE - 1);

    uint8_t rnd_b_rot[MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_rotate_left(rnd_b, rnd_b_rot);

    // Part 2: token = AES-CBC(key, iv=0, rrot(RndA) || rol(RndB)).
    uint8_t plain[2 * MF_PLUS_AES_BLOCK_SIZE];
    memcpy(&plain[0], rnd_a_rrot, MF_PLUS_AES_BLOCK_SIZE);
    memcpy(&plain[MF_PLUS_AES_BLOCK_SIZE], rnd_b_rot, MF_PLUS_AES_BLOCK_SIZE);

    const uint8_t zero_iv[MF_PLUS_AES_BLOCK_SIZE] = {0};
    uint8_t cmd2[1 + 2 * MF_PLUS_AES_BLOCK_SIZE];
    cmd2[0] = MF_PLUS_CMD_AUTH_CONTINUE;
    mf_plus_crypto_cbc_encrypt(key->data, zero_iv, plain, &cmd2[1], sizeof(plain));

    error = mf_plus_poller_send_raw(instance, cmd2, sizeof(cmd2), resp, &resp_len, sizeof(resp));
    if(error != MfPlusErrorNone) return error;
    if(resp_len < 1 + 2 * MF_PLUS_AES_BLOCK_SIZE || resp[0] != MF_PLUS_STATUS_OK) {
        return MfPlusErrorAuth;
    }

    // Response = E(TI(4) || RndA'(16) || caps). Decrypt and verify the RndA echo (the auth proof;
    // a wrong key fails to reproduce it). Accept the rotation variants the fork validated.
    uint8_t dec[2 * MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_cbc_decrypt(key->data, zero_iv, &resp[1], dec, sizeof(dec));

    uint8_t rnd_a_rot[MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_rotate_left(rnd_a, rnd_a_rot);
    if(memcmp(&dec[4], rnd_a_rrot, MF_PLUS_AES_BLOCK_SIZE) != 0 &&
       memcmp(&dec[4], rnd_a_rot, MF_PLUS_AES_BLOCK_SIZE) != 0 &&
       memcmp(&dec[4], rnd_a, MF_PLUS_AES_BLOCK_SIZE) != 0) {
        return MfPlusErrorAuth;
    }

    memcpy(session->ti, &dec[0], 4);
    session->r_ctr = 0;
    session->w_ctr = 0;
    // Derive the session keys from rrot(RndA) (what the card treats as RndA) and RndB.
    mf_plus_crypto_derive_session_keys(
        key->data, rnd_a_rrot, rnd_b, session->k_enc, session->k_mac);

    return MfPlusErrorNone;
}

PlusError mf_plus_poller_authenticate(
    MfPlusPoller* instance,
    uint8_t sector,
    MfPlusKeyType key_type,
    const MfPlusKey* key,
    MfPlusPollerSession* session) {
    // Sector keys live in the 0x40xx keyspace: 0x4000 + 2*sector + key_type.
    const uint16_t key_id = 0x4000U + ((uint16_t)sector << 1) + (uint8_t)key_type;
    return mf_plus_poller_authenticate_key_id(instance, key_id, key, session);
}

PlusError mf_plus_poller_read_block(
    MfPlusPoller* instance,
    uint8_t block_low,
    uint8_t block_high,
    bool plain,
    MfPlusPollerSession* session,
    MfPlusBlock* out) {
    furi_check(instance);
    furi_check(session);
    furi_check(out);

    // A block whose access conditions require plaintext communication is read with 0x33 instead of
    // 0x31: identical command/MAC/counter model, but the data travels in the clear (no decrypt) and
    // the response MAC is over the plaintext. The card rejects the wrong opcode (see the state
    // machine's mode probe).
    const uint8_t opcode = plain ? MF_PLUS_CMD_READ_PLAIN : MF_PLUS_CMD_READ_ENC;

    // Command MAC over the 2-byte little-endian block address {low, high} + count, with the
    // pre-increment R_ctr. Data blocks use high = 0x00; config blocks (0xB0xx) use high = 0xB0.
    const uint8_t payload[3] = {block_low, block_high, 0x01};
    uint8_t cmd_mac[MF_PLUS_MAC_SIZE];
    mf_plus_crypto_calculate_mac(
        session->k_mac, opcode, session->r_ctr, session->ti, payload, sizeof(payload), cmd_mac);

    uint8_t cmd[4 + MF_PLUS_MAC_SIZE];
    cmd[0] = opcode;
    cmd[1] = block_low;
    cmd[2] = block_high;
    cmd[3] = 0x01;
    memcpy(&cmd[4], cmd_mac, MF_PLUS_MAC_SIZE);

    uint8_t resp[64];
    size_t resp_len = 0;
    MfPlusError error =
        mf_plus_poller_send_raw(instance, cmd, sizeof(cmd), resp, &resp_len, sizeof(resp));
    if(error != MfPlusErrorNone) return error; // comms/RF fault (or lost card): not a mode signal
    // status(1) + data(16) + mac(8). A short frame with a non-OK status (e.g. 0x0B "command not
    // available") is the card rejecting this read mode -> Rejected (distinct from a comms Protocol
    // error), which the caller may retry in the other mode. The rejection is a bare status frame, so
    // r_ctr is NOT advanced below -- the session stays in sync for a retry.
    if(resp_len < 1 + MF_PLUS_BLOCK_SIZE + MF_PLUS_MAC_SIZE || resp[0] != MF_PLUS_STATUS_OK) {
        return MfPlusErrorRejected;
    }

    // The response MAC (and, for an encrypted read, the decryption IV) both use the post-increment
    // counter. The MAC covers the data bytes exactly as transmitted -- ciphertext for 0x31,
    // plaintext for 0x33 -- so this computation is identical for both modes.
    session->r_ctr++;

    uint8_t mac_input[sizeof(payload) + MF_PLUS_BLOCK_SIZE];
    memcpy(&mac_input[0], payload, sizeof(payload));
    memcpy(&mac_input[sizeof(payload)], &resp[1], MF_PLUS_BLOCK_SIZE);
    uint8_t resp_mac[MF_PLUS_MAC_SIZE];
    mf_plus_crypto_calculate_mac(
        session->k_mac,
        MF_PLUS_STATUS_OK,
        session->r_ctr,
        session->ti,
        mac_input,
        sizeof(mac_input),
        resp_mac);
    if(memcmp(&resp[1 + MF_PLUS_BLOCK_SIZE], resp_mac, MF_PLUS_MAC_SIZE) != 0) {
        // Distinct from a status-byte rejection: a MAC mismatch means r_ctr is now desynced
        // (it was already advanced above), so the caller must abort the sector rather than retry.
        return MfPlusErrorAuth;
    }

    if(plain) {
        memcpy(out->data, &resp[1], MF_PLUS_BLOCK_SIZE);
    } else {
        uint8_t iv[MF_PLUS_AES_BLOCK_SIZE];
        mf_plus_crypto_build_read_iv(session->ti, session->r_ctr, session->w_ctr, iv);
        mf_plus_crypto_cbc_decrypt(session->k_enc, iv, &resp[1], out->data, MF_PLUS_BLOCK_SIZE);
    }

    return MfPlusErrorNone;
}

PlusError mf_plus_poller_write_block(
    MfPlusPoller* instance,
    uint8_t block_low,
    uint8_t block_high,
    bool plain,
    const MfPlusBlock* in,
    MfPlusPollerSession* session) {
    furi_check(instance);
    furi_check(session);
    furi_check(in);

    // The card-side mirror of mf_plus_listener_write_handler. A block whose access conditions require
    // plaintext communication is written with 0xA3 instead of 0xA1: 0xA1 CBC-encrypts the block with
    // the write IV (pre-increment W_ctr), 0xA3 sends it in the clear. The command MAC always covers
    // the data exactly as transmitted; the card rejects the wrong opcode (see the write mode probe).
    const uint8_t opcode = plain ? MF_PLUS_CMD_WRITE_PLAIN : MF_PLUS_CMD_WRITE_ENC;

    uint8_t wire_data[MF_PLUS_BLOCK_SIZE];
    if(plain) {
        memcpy(wire_data, in->data, MF_PLUS_BLOCK_SIZE);
    } else {
        uint8_t iv[MF_PLUS_AES_BLOCK_SIZE];
        mf_plus_crypto_build_write_iv(session->ti, session->r_ctr, session->w_ctr, iv);
        mf_plus_crypto_cbc_encrypt(session->k_enc, iv, in->data, wire_data, MF_PLUS_BLOCK_SIZE);
    }

    // Command MAC over {block_low, block_high} + the wire data, with the pre-increment W_ctr.
    uint8_t mac_input[2 + MF_PLUS_BLOCK_SIZE];
    mac_input[0] = block_low;
    mac_input[1] = block_high;
    memcpy(&mac_input[2], wire_data, MF_PLUS_BLOCK_SIZE);
    uint8_t cmd_mac[MF_PLUS_MAC_SIZE];
    mf_plus_crypto_calculate_mac(
        session->k_mac, opcode, session->w_ctr, session->ti, mac_input, sizeof(mac_input), cmd_mac);

    uint8_t cmd[3 + MF_PLUS_BLOCK_SIZE + MF_PLUS_MAC_SIZE];
    cmd[0] = opcode;
    cmd[1] = block_low;
    cmd[2] = block_high;
    memcpy(&cmd[3], wire_data, MF_PLUS_BLOCK_SIZE);
    memcpy(&cmd[3 + MF_PLUS_BLOCK_SIZE], cmd_mac, MF_PLUS_MAC_SIZE);

    uint8_t resp[64];
    size_t resp_len = 0;
    MfPlusError error =
        mf_plus_poller_send_raw(instance, cmd, sizeof(cmd), resp, &resp_len, sizeof(resp));
    if(error != MfPlusErrorNone) return error; // comms/RF fault (or lost card): not a mode signal
    // status(1) + resp_mac(8). A short frame with a non-OK status (e.g. 0x0B "command not
    // available") is the card rejecting this write mode -> Rejected (distinct from a comms Protocol
    // error), which the caller may retry in the other mode. r_ctr/w_ctr are NOT advanced below on
    // that path, so the session stays in sync for a retry.
    if(resp_len < 1 + MF_PLUS_MAC_SIZE || resp[0] != MF_PLUS_STATUS_OK) {
        return MfPlusErrorRejected;
    }

    // The write took on the card: it advanced W_ctr and MAC'd the OK status over the post-increment
    // value, so mirror that before verifying.
    session->w_ctr++;
    uint8_t resp_mac[MF_PLUS_MAC_SIZE];
    mf_plus_crypto_calculate_mac(
        session->k_mac, MF_PLUS_STATUS_OK, session->w_ctr, session->ti, NULL, 0, resp_mac);
    if(memcmp(&resp[1], resp_mac, MF_PLUS_MAC_SIZE) != 0) {
        // A response-MAC mismatch means W_ctr is now desynced (already advanced above), so the caller
        // must abort the sector rather than retry.
        return MfPlusErrorAuth;
    }

    return MfPlusErrorNone;
}

PlusError
    mf_plus_poller_read_signature(MfPlusPoller* instance, uint8_t* signature, bool* present) {
    furi_check(instance);
    furi_check(signature);
    furi_check(present);

    *present = false;

    const uint8_t cmd[2] = {MF_PLUS_CMD_READ_SIG, 0x00};
    uint8_t resp[64];
    size_t resp_len = 0;
    MfPlusError error =
        mf_plus_poller_send_raw(instance, cmd, sizeof(cmd), resp, &resp_len, sizeof(resp));
    if(error != MfPlusErrorNone) return error;

    // Cards vary: some prefix a 0x90 status byte, others return the raw 56 signature bytes.
    const uint8_t* sig = NULL;
    if(resp_len >= 1 + MF_PLUS_SIGNATURE_SIZE && resp[0] == MF_PLUS_STATUS_OK) {
        sig = &resp[1];
    } else if(resp_len >= MF_PLUS_SIGNATURE_SIZE) {
        sig = &resp[0];
    }

    if(sig != NULL) {
        memcpy(signature, sig, MF_PLUS_SIGNATURE_SIZE);
        *present = true;
    }
    // A card with no signature (EV0 / unsupported) is not an error.
    return MfPlusErrorNone;
}

static void nfc_show_loading_view(NfcApp* nfc, NfcView view, bool show) {
        view_dispatcher_switch_to_view(nfc->view_dispatcher, view);
void nfc_show_loading_popup(void* context, bool show) {
    NfcApp* nfc = context;
    nfc_show_loading_view(nfc, NfcViewLoading, show);
}

void nfc_show_loading_label_popup(void* context, const char* text, bool show) {
    NfcApp* nfc = context;
