static void loading_label_draw_callback(Canvas* canvas, void* _model) {
    LoadingLabelModel* model = _model;

    canvas_set_color(canvas, ColorWhite);
    canvas_draw_box(canvas, 0, 0, canvas_width(canvas), canvas_height(canvas));
    canvas_set_color(canvas, ColorBlack);

    // Spinner on the left, vertically centered
    const uint8_t icon_x = 12;
    const uint8_t icon_y = canvas_height(canvas) / 2 - 24 / 2;
    canvas_draw_icon(canvas, icon_x, icon_y, &A_Loading_24);
    canvas_draw_icon_animation(canvas, icon_x, icon_y, model->icon);

    // Label to the right of the spinner
    if(model->text) {
        canvas_set_font(canvas, FontPrimary);
        elements_multiline_text_aligned(
            canvas, 82, canvas_height(canvas) / 2, AlignCenter, AlignCenter, model->text);
    }
}

static bool loading_label_input_callback(InputEvent* event, void* context) {
    UNUSED(event);
    furi_assert(context);
    // Consume all input while loading
    return true;
}

static void loading_label_enter_callback(void* context) {
    furi_assert(context);
    LoadingLabel* instance = context;
    LoadingLabelModel* model = view_get_model(instance->view);
    view_tie_icon_animation(instance->view, model->icon);
    icon_animation_start(model->icon);
    view_commit_model(instance->view, false);
}

static void loading_label_exit_callback(void* context) {
    furi_assert(context);
    LoadingLabel* instance = context;
    LoadingLabelModel* model = view_get_model(instance->view);
    icon_animation_stop(model->icon);
    view_commit_model(instance->view, false);
}

LoadingLabel* loading_label_alloc(void) {
    LoadingLabel* instance = malloc(sizeof(LoadingLabel));
    instance->view = view_alloc();
    view_allocate_model(instance->view, ViewModelTypeLocking, sizeof(LoadingLabelModel));
    LoadingLabelModel* model = view_get_model(instance->view);
    model->icon = icon_animation_alloc(&A_Loading_24);
    model->text = NULL;
    view_tie_icon_animation(instance->view, model->icon);
    view_commit_model(instance->view, false);

    view_set_context(instance->view, instance);
    view_set_draw_callback(instance->view, loading_label_draw_callback);
    view_set_input_callback(instance->view, loading_label_input_callback);
    view_set_enter_callback(instance->view, loading_label_enter_callback);
    view_set_exit_callback(instance->view, loading_label_exit_callback);

    return instance;
}

void loading_label_free(LoadingLabel* instance) {
    furi_check(instance);

    LoadingLabelModel* model = view_get_model(instance->view);
    icon_animation_free(model->icon);
    view_commit_model(instance->view, false);

    view_free(instance->view);
    free(instance);
}

void loading_label_set_text(LoadingLabel* instance, const char* text) {
    furi_check(instance);
    LoadingLabelModel* model = view_get_model(instance->view);
    model->text = text;
    view_commit_model(instance->view, true);
}

static bool mf_classic_ats_is_plus_2k_sl1(const uint8_t* ats, size_t ats_size) {
    if(ats_size < 2) return false;

    // TL counts the ATS bytes up to (not including) the CRC; clamp to what we actually received.
    size_t tl = ats[0];
    if(tl > ats_size) tl = ats_size;

    // Skip TL, T0 and the optional interface bytes to reach the historical bytes T1..Tk.
    size_t offset = 2;
    const uint8_t t0 = ats[1];
    if(t0 & MF_CLASSIC_ATS_T0_TA1) offset++;
    if(t0 & MF_CLASSIC_ATS_T0_TB1) offset++;
    if(t0 & MF_CLASSIC_ATS_T0_TC1) offset++;
    if(offset > tl) return false;

    const size_t tk_len = sizeof(mf_classic_plus_2k_sl1_ats_tk[0]);
    if(tl - offset != tk_len) return false;
    for(size_t i = 0; i < COUNT_OF(mf_classic_plus_2k_sl1_ats_tk); i++) {
        if(memcmp(&ats[offset], mf_classic_plus_2k_sl1_ats_tk[i], tk_len) == 0) return true;
    }
    return false;
}

static bool mf_classic_poller_is_plus_2k_sl1(MfClassicPoller* instance) {
    bit_buffer_reset(instance->tx_plain_buffer);
    bit_buffer_append_byte(instance->tx_plain_buffer, MF_CLASSIC_RATS_CMD);
    bit_buffer_append_byte(instance->tx_plain_buffer, MF_CLASSIC_RATS_PARAM);

    Iso14443_3aError error = iso14443_3a_poller_send_standard_frame(
        instance->iso14443_3a_poller,
        instance->tx_plain_buffer,
        instance->rx_plain_buffer,
        MF_CLASSIC_RATS_FWT_FC);
    if(error != Iso14443_3aErrorNone) return false; // no ATS -> not a Plus

    const size_t ats_size = bit_buffer_get_size_bytes(instance->rx_plain_buffer);
    if(mf_classic_ats_is_plus_2k_sl1(bit_buffer_get_data(instance->rx_plain_buffer), ats_size)) {
        return true;
    }

    // Answered RATS but ATS isn't a known Plus 2K sig (Plus SE, SL0/SL3, variant, or clone); stay 1K.
    FURI_LOG_D(TAG, "RATS answered but ATS not Plus 2K (%u B); staying 1K", (unsigned)ats_size);
    return false;
}

static uint32_t nfc_mf_ultralight_get_features(NfcApp* instance) {
    const MfUltralightData* data =
        nfc_device_get_data(instance->nfc_device, NfcProtocolMfUltralight);
    return (data->type == MfUltralightTypeUltralightAES) ? NfcProtocolFeatureEmulateUid :
                                                           MF_ULTRALIGHT_DEFAULT_FEATURES;
}

static MfPlusType mf_plus_type_from_ats(const uint8_t* historical_bytes, size_t len) {
    if(len != MF_PLUS_T1_TK_VALUE_LEN) return MfPlusTypeUnknown;
    if(memcmp(historical_bytes, mf_plus_ats_t1_tk_values[0], len) == 0) return MfPlusTypeS;
    if(memcmp(historical_bytes, mf_plus_ats_t1_tk_values[1], len) == 0) return MfPlusTypeX;
    if(memcmp(historical_bytes, mf_plus_ats_t1_tk_values[2], len) == 0 ||
       memcmp(historical_bytes, mf_plus_ats_t1_tk_values[3], len) == 0)
        return MfPlusTypeSE;
    return MfPlusTypeUnknown;
}

static MfPlusSize mf_plus_size_from_atqa(const uint8_t atqa[2]) {
    const uint16_t atqa_value = atqa[0] | ((uint16_t)atqa[1] << 8);
    if(atqa_value & 0x0004) return MfPlusSize2K;
    if(atqa_value & 0x0002) return MfPlusSize4K;
    return MfPlusSizeUnknown;
}

atic MfPlusSecurityLevel mf_plus_poller_resolve_sak20_security_level(MfPlusPoller* instance) {
    const Iso14443_4aData* iso14443_4a_data =
        iso14443_4a_poller_get_data(instance->iso14443_4a_poller);
    if(iso14443_4a_data->iso14443_3a_data->sak != 0x20) {
        return MfPlusSecurityLevelUnknown;
    }

    MfPlusProbeResult probe = MfPlusProbeResultNotPlus;
    if(mf_plus_poller_probe_security_level(instance, &probe) != MfPlusErrorNone) {
        return MfPlusSecurityLevelUnknown;
    }

    switch(probe) {
    case MfPlusProbeResultSl0:
        return MfPlusSecurityLevel0;
    case MfPlusProbeResultSl3:
        return MfPlusSecurityLevel3;
    default: // MfPlusProbeResultNotPlus
        return MfPlusSecurityLevelUnknown;
    }
}

MfPlusError
    mf_plus_poller_probe_security_level(MfPlusPoller* instance, MfPlusProbeResult* result) {
    furi_check(instance);
    furi_check(result);

    bit_buffer_reset(instance->input_buffer);
    bit_buffer_append_byte(instance->input_buffer, MF_PLUS_CMD_WRITE_PERSO);
    bit_buffer_append_byte(instance->input_buffer, 0x90); // block 0x9090 (little-endian), invalid
    bit_buffer_append_byte(instance->input_buffer, 0x90);
    for(size_t i = 0; i < MF_PLUS_WRITE_PERSO_PROBE_LEN - 3; i++) {
        bit_buffer_append_byte(instance->input_buffer, 0x00);
    }

    NxpNativeCommandStatus status = NXP_NATIVE_COMMAND_STATUS_OPERATION_OK;
    Iso14443_4aError error = nxp_native_command_iso14443_4a_poller(
        instance->iso14443_4a_poller,
        &status,
        instance->input_buffer,
        instance->result_buffer,
        NxpNativeCommandModePlain,
        instance->tx_buffer,
        instance->rx_buffer);
    if(error != Iso14443_4aErrorNone) {
        return mf_plus_process_error(error);
    }

    // MIFARE Plus answers WritePerso with a single status byte: 0x09 = invalid block rejected (still
    // in SL0 personalization), 0x06/0x0B = the documented SL3 rejections. Treat any other reply
    // (DESFire status words, length error, ...) as not-a-Plus so the caller keeps its DESFire-safe
    // fallback -- no real DESFire status code is 0x06/0x09/0x0B. (PM3 hf mfp info.)
    FURI_LOG_D(TAG, "SL probe (SAK 20) WritePerso status 0x%02X", status);
    switch(status) {
    case 0x09:
        *result = MfPlusProbeResultSl0;
        break;
    case 0x06:
    case 0x0B:
        *result = MfPlusProbeResultSl3;
        break;
    default:
        *result = MfPlusProbeResultNotPlus;
        break;
    }
    return MfPlusErrorNone;
}

static int
av_count_limit(AV *av)
{
	dTHX;
	Size_t		cnt = av_count(av);

	if (cnt > MaxArraySize)
		ereport(ERROR,
				(errcode(ERRCODE_PROGRAM_LIMIT_EXCEEDED),
				 errmsg("array size exceeds the maximum allowed (%zu)",
						MaxArraySize)));
	return (int) cnt;
}

ol oled_task_kb(void) {
    if (!oled_task_user()) {
        return false;
    }

    oled_set_cursor(0, 0);
    oled_write_P(PSTR("   HEER  S1"), false);

    oled_set_cursor(0, 1);
    oled_write_P(PSTR("---------------"), false);

    // Shown as a number, not a name: a board-level default cannot know what any
    // given keymap calls its layers.
    oled_set_cursor(0, 2);
    oled_write_P(PSTR("LAYER "), false);
    oled_write_char('0' + get_highest_layer(layer_state), false);

    oled_set_cursor(0, 3);
    oled_write_P(PSTR("["), false);
    for (uint8_t i = 0; i < 4; i++) {
        oled_write_P(get_highest_layer(layer_state) == i ? PSTR("*") : PSTR("-"), false);
    }
    oled_write_P(PSTR("]"), false);

    return true;
}

void test_fatfs_fcntl_setfl(const char* filename)
{
    unlink(filename);
    int fd = open(filename, O_RDWR | O_CREAT | O_TRUNC);
    TEST_ASSERT_NOT_EQUAL(-1, fd);

    int flags = fcntl(fd, F_GETFL);
    TEST_ASSERT_NOT_EQUAL(-1, flags);
    TEST_ASSERT_EQUAL(O_RDWR, flags & O_ACCMODE);
    TEST_ASSERT_EQUAL(0, flags & O_APPEND);

    /* F_SETFL must not clobber O_ACCMODE when arg is only a status flag. */
    TEST_ASSERT_EQUAL(0, fcntl(fd, F_SETFL, O_APPEND));
    flags = fcntl(fd, F_GETFL);
    TEST_ASSERT_EQUAL(O_RDWR, flags & O_ACCMODE);
    TEST_ASSERT_NOT_EQUAL(0, flags & O_APPEND);

    TEST_ASSERT_EQUAL(4, write(fd, "AAAA", 4));
    TEST_ASSERT_NOT_EQUAL(-1, lseek(fd, 0, SEEK_SET));
    TEST_ASSERT_EQUAL(4, write(fd, "BBBB", 4));
    TEST_ASSERT_EQUAL(0, close(fd));

    char buf[10] = { 0 };
    FILE *f_r = fopen(filename, "r");
    TEST_ASSERT_NOT_NULL(f_r);
    TEST_ASSERT_EQUAL(8, fread(buf, 1, 8, f_r));
    TEST_ASSERT_EQUAL_STRING_LEN("AAAABBBB", buf, 8);
    TEST_ASSERT_EQUAL(0, fclose(f_r));
    unlink(filename);
}

static
ULONG
i8042GetHyperVOSBuild(
    VOID)
{
    INT CpuInfo[4];
    ULONG MaxHvLeaf;

    /* Check if we are running under a hypervisor */
    __cpuid(CpuInfo, 1);
    if (!(CpuInfo[2] & 0x80000000))
        return 0;

    /* Check for the Hyper-V signature "Microsoft Hv" */
    __cpuid(CpuInfo, 0x40000000);
    MaxHvLeaf = (ULONG)CpuInfo[0];
    DPRINT1("Hypervisor CPUID: max leaf 0x%lx, signature '%.4s%.4s%.4s'\n",
            MaxHvLeaf, (PCHAR)&CpuInfo[1], (PCHAR)&CpuInfo[2], (PCHAR)&CpuInfo[3]);
    if (CpuInfo[1] != 0x7263694D || /* "Micr" */
        CpuInfo[2] != 0x666F736F || /* "osof" */
        CpuInfo[3] != 0x76482074)   /* "t Hv" */
        return 0;

    if (MaxHvLeaf < 0x40000002)
        return 0;

    /* Hypervisor system identity: EAX holds the host OS build number */
    __cpuid(CpuInfo, 0x40000002);
    DPRINT1("Hyper-V interface reports host build %lu\n", (ULONG)CpuInfo[0]);
    return (ULONG)CpuInfo[0];
}

bool QuadF::IsRotated() const {
    if (IsEmpty()) {
        return false;
    }
    const float eps = 0.5f;
    return fabsf(ul.y - ur.y) > eps || fabsf(ll.y - lr.y) > eps || fabsf(ul.x - ll.x) > eps || fabsf(ur.x - lr.x) > eps;
}

static bool HandlePolyLineClick(MainWindow* win, Point pt, WPARAM key) {
    // one point plus this click is a single segment; closing it would just
    // double back on itself, so let it keep collecting vertices instead
    bool close = bit::IsMaskSet(key, (WPARAM)MK_CONTROL) && len(p.points) > 2;
    if (close) {
        // by value: VecAppend takes a reference, and growing the vec frees the
        // buffer that reference would point into
        // by value: VecAppend takes a reference, and growing the vec frees the
        // buffer that reference would point into
        PointF first = p.points[0];
        VecAppend(p.points, first);
        CommitPlacementCommand(win, dm->CvtToScreen(pageNo, first));
        return true;
    }
            HandlePolyLineClick(win, pt, key);

static void SetFilter(AnnotFilterToolbar* f, Str text) {
    f->filter.Reset();
    f->filterWords.Reset();
    if (!ParseAnnotSearch(text, f->filter)) {
        f->filter.Reset();
        StrVec words;
        SplitFilterToWords(text, words);
        for (Str w : words) {
            AnnotSearchAddContentWord(f->filter, w);
        }
    }
    AnnotSearchContentWords(f->filter, f->filterWords);
}

static ILayout* NewFilterHelp(int gap) {
    struct HelpRow {
        Str syntax;
        Str what;
    };
    HelpRow rows[] = {
        {StrL(":a=name  :a!=name"), _TRA("author is / is not")},
        {StrL(":t=text  :t!=line"), _TRA("type is / is not")},
        {StrL(":c+  :c-"), _TRA("has / has no contents")},
    };
    PlatformFont* font = GetAppFont();
    Color col = ThemeWindowTextDisabledColor();
    auto mkText = [&](Str s) -> ILayout* {
        return NewVirtText({
            .s = s,
            .font = font,
            .textColor = col,
            .isRtl = IsUIRtl(),
            .ellipsis = true,
        });
    };

    auto* box = new VBox();
    box->alignCross = CrossAxisAlign::Stretch;
    box->AddChild(mkText(_TRA("Search syntax:")));
    box->AddChild(new Spacer(0, gap / 2));
    int nRows = (int)dimof(rows);
    auto* table = new Table();
    table->SetSize(nRows, 2);
    table->colGap = 2 * gap;
    for (int i = 0; i < nRows; i++) {
        table->SetCell(i, 0, mkText(rows[i].syntax));
        table->SetCell(i, 1, mkText(rows[i].what));
    }
    box->AddChild(table);
    return box;
}

static void PostedRefreshAnnots(MainWindow* win) {
    if (IsMainWindowValidAndNotClosing(win)) {
        RefreshAnnotFilterAnnotations(win);
    }
}

void ClearAnnotFilterAnnotations(MainWindow* win) {
    AnnotFilterToolbar* f = win ? win->annotFilterToolbar : nullptr;
    if (!f) {
        return;
    }
    CancelPendingSelection(f);
    VecReset(f->annotations);
    VecReset(f->visibleAnnots);
    if (VirtListBox* lb = ActiveList(f)) {
        lb->SetModel(NewAnnotListModel(f));
        lb->Invalidate();
    }
    UpdateCue(f);
    UpdateFloatButtons(f);
    uitask::Post(MkFunc0(PostedRefreshAnnots, win), "RefreshAnnotFilterAnnots");
}

static void AddCond(AnnotMatchOpts& opts, AnnotMatchCond::Type tp, Str s, AnnotationType annotType) {
    auto* c = new AnnotMatchCond;
    c->tp = tp;
    c->annotType = annotType;
    c->s = str::Dup(s);
    // conditions are ANDed, so order does not matter; append anyway so the
    // list reads the way the user typed it
    ListInsertEnd(&opts.conds, c);
}

static int ScanName(Str s, int i) {
    int start = i;
    while (i < s.len && str::IsAlNum(s.s[i])) {
        i++;
    }
    return i - start;
}

static void SkipWs(Str s, int& i) {
    while (i < s.len && IsFilterWs(s.s[i])) {
        i++;
    }
}

static bool ScanOp(Str s, int& i, bool& isNotOut) {
    SkipWs(s, i);
    if (i < s.len && s.s[i] == '!') {
        if (i + 1 >= s.len || s.s[i + 1] != '=') {
            return false;
        }
        isNotOut = true;
        i += 2;
        return true;
    }
    if (i < s.len && s.s[i] == '=') {
        isNotOut = false;
        i++;
        if (i < s.len && s.s[i] == '=') {
            i++;
        }
        return true;
    }
    return false;
}

static Str ScanValue(Str s, int& i) {
    SkipWs(s, i);
    int start = i;
    while (i < s.len && !IsFilterWs(s.s[i])) {
        i++;
    }
    return Str(s.s + start, i - start);
}

bool ParseAnnotSearch(Str filter, AnnotMatchOpts& optsOut) {
    Str s = filter;
    int i = 0;
    while (i < s.len) {
        SkipWs(s, i);
        if (i >= s.len) {
            break;
        }
        if (s.s[i] != ':') {
            Str word = ScanValue(s, i);
            if (len(word) > 0) {
                AddCond(optsOut, AnnotMatchCond::Type::ContentMatches, word, AnnotationType::Unknown);
            }
            continue;
        }
        i++; // ':'
        int nameLen = ScanName(s, i);
        Str name = Str(s.s + i, nameLen);
        i += nameLen;
        if (str::EqI(name, StrL("c"))) {
            // ":c+" / ":c-", no operator and no value
            if (i >= s.len || (s.s[i] != '+' && s.s[i] != '-')) {
                return false;
            }
            auto tp = (s.s[i] == '+') ? AnnotMatchCond::Type::HasContent : AnnotMatchCond::Type::NoContent;
            i++;
            AddCond(optsOut, tp, {}, AnnotationType::Unknown);
            continue;
        }
        bool isAuthor = str::EqI(name, StrL("a"));
        bool isType = str::EqI(name, StrL("t"));
        if (!isAuthor && !isType) {
            return false;
        }
        bool isNot = false;
        if (!ScanOp(s, i, isNot)) {
            return false;
        }
        Str val = ScanValue(s, i);
        if (len(val) == 0) {
            return false;
        }
        if (isAuthor) {
            auto tp = isNot ? AnnotMatchCond::Type::AuthorNotEqual : AnnotMatchCond::Type::AuthorEqual;
            AddCond(optsOut, tp, val, AnnotationType::Unknown);
            continue;
        }
        AnnotationType annotType = AnnotationTypeFromName(val);
        if (annotType == AnnotationType::Unknown) {
            return false;
        }
        auto tp = isNot ? AnnotMatchCond::Type::AnnotTypeNotEqual : AnnotMatchCond::Type::AnnotTypeEqual;
        AddCond(optsOut, tp, {}, annotType);
    }
    return true;
}

bool AnnotMatchesFields(Str author, Str contents, AnnotationType annotType, const AnnotMatchOpts& opts) {
    // the positive conditions on one field are alternatives; "no such condition"
    // and "one of them matched" both pass
    bool wantAuthor = false, sawAuthor = false;
    bool wantType = false, sawType = false;
    for (AnnotMatchCond* c = opts.conds; c; c = c->next) {
        switch (c->tp) {
            case AnnotMatchCond::Type::AuthorEqual:
                wantAuthor = true;
                sawAuthor = sawAuthor || str::EqI(author, c->s);
                break;
            case AnnotMatchCond::Type::AuthorNotEqual:
                if (str::EqI(author, c->s)) {
                    return false;
                }
                break;
            case AnnotMatchCond::Type::AnnotTypeEqual:
                wantType = true;
                sawType = sawType || (annotType == c->annotType);
                break;
            case AnnotMatchCond::Type::AnnotTypeNotEqual:
                if (annotType == c->annotType) {
                    return false;
                }
                break;
            case AnnotMatchCond::Type::ContentMatches:
                if (!str::ContainsI(contents, c->s)) {
                    return false;
                }
                break;
            case AnnotMatchCond::Type::HasContent:
                if (len(contents) == 0) {
                    return false;
                }
                break;
            case AnnotMatchCond::Type::NoContent:
                if (len(contents) > 0) {
                    return false;
                }
                break;
        }
    }
    if (wantAuthor && !sawAuthor) {
        return false;
    }
    if (wantType && !sawType) {
        return false;
    }
    return true;
}

bool AnnotMatches(Annotation* annot, const AnnotMatchOpts& opts) {
    if (!annot) {
        return false;
    }
    return AnnotMatchesFields(Author(annot), Contents(annot), Type(annot), opts);
}

void AnnotSearchAddContentWord(AnnotMatchOpts& opts, Str word) {
    if (len(word) > 0) {
        AddCond(opts, AnnotMatchCond::Type::ContentMatches, word, AnnotationType::Unknown);
    }
}

void AnnotSearchContentWords(const AnnotMatchOpts& opts, StrVec& wordsOut) {
    for (AnnotMatchCond* c = opts.conds; c; c = c->next) {
        if (c->tp == AnnotMatchCond::Type::ContentMatches) {
            AppendIfNotExists(&wordsOut, c->s);
        }
    }
}

static AnnotMatchCond* CondAt(const AnnotMatchOpts& opts, int idx) {
    AnnotMatchCond* c = opts.conds;
    while (c && idx > 0) {
        c = c->next;
        idx--;
    }
    return c;
}

bool AnnotSearch_UnitTests() {
    using Type = AnnotMatchCond::Type;
    {
        // plain words are content conditions
        AnnotMatchOpts opts;
        utassert(ParseAnnotSearch(StrL("todo later"), opts));
        utassert(CondCount(opts) == 2);
        utassert(CondAt(opts, 0)->tp == Type::ContentMatches);
        utassert(str::Eq(CondAt(opts, 0)->s, StrL("todo")));
        utassert(str::Eq(CondAt(opts, 1)->s, StrL("later")));
    }
    {
        // an empty filter matches everything
        AnnotMatchOpts opts;
        utassert(ParseAnnotSearch(StrL(""), opts));
        utassert(CondCount(opts) == 0);
        utassert(AnnotMatchesFields(StrL("kjk"), StrL(""), AnnotationType::Text, opts));
    }
    {
        // the three author spellings parse the same
        for (Str f : {StrL(":a=kjk"), StrL(":a = kjk"), StrL(":a== kjk")}) {
            AnnotMatchOpts opts;
            utassert(ParseAnnotSearch(f, opts));
            utassert(CondCount(opts) == 1);
            utassert(CondAt(opts, 0)->tp == Type::AuthorEqual);
            utassert(str::Eq(CondAt(opts, 0)->s, StrL("kjk")));
        }
    }
    {
        AnnotMatchOpts opts;
        utassert(ParseAnnotSearch(StrL(":a!= kjk"), opts));
        utassert(CondAt(opts, 0)->tp == Type::AuthorNotEqual);
        utassert(AnnotMatchesFields(StrL("bob"), StrL(""), AnnotationType::Text, opts));
        utassert(!AnnotMatchesFields(StrL("kjk"), StrL(""), AnnotationType::Text, opts));
        // author match is case-insensitive
        utassert(!AnnotMatchesFields(StrL("KJK"), StrL(""), AnnotationType::Text, opts));
    }
    {
        // ":t" takes an untranslated type name, spaces and case ignored
        AnnotMatchOpts opts;
        utassert(ParseAnnotSearch(StrL(":t== freetext"), opts));
        utassert(CondAt(opts, 0)->tp == Type::AnnotTypeEqual);
        utassert(CondAt(opts, 0)->annotType == AnnotationType::FreeText);
        utassert(AnnotMatchesFields({}, {}, AnnotationType::FreeText, opts));
        utassert(!AnnotMatchesFields({}, {}, AnnotationType::Text, opts));
    }
    {
        AnnotMatchOpts opts;
        utassert(ParseAnnotSearch(StrL(":t !=line"), opts));
        utassert(CondAt(opts, 0)->tp == Type::AnnotTypeNotEqual);
        utassert(!AnnotMatchesFields({}, {}, AnnotationType::Line, opts));
        utassert(AnnotMatchesFields({}, {}, AnnotationType::Ink, opts));
    }
    {
        // several "==" on one field are alternatives
        AnnotMatchOpts opts;
        utassert(ParseAnnotSearch(StrL(":t=text :t=freetext"), opts));
        utassert(CondCount(opts) == 2);
        utassert(AnnotMatchesFields({}, {}, AnnotationType::Text, opts));
        utassert(AnnotMatchesFields({}, {}, AnnotationType::FreeText, opts));
        utassert(!AnnotMatchesFields({}, {}, AnnotationType::Ink, opts));
    }
    {
        // several "!=" all have to hold
        AnnotMatchOpts opts;
        utassert(ParseAnnotSearch(StrL(":a!=kjk :a!=bob"), opts));
        utassert(!AnnotMatchesFields(StrL("kjk"), {}, AnnotationType::Text, opts));
        utassert(!AnnotMatchesFields(StrL("bob"), {}, AnnotationType::Text, opts));
        utassert(AnnotMatchesFields(StrL("ann"), {}, AnnotationType::Text, opts));
    }
    {
        // ":c+" keeps only annotations that have contents
        AnnotMatchOpts opts;
        utassert(ParseAnnotSearch(StrL(":c+"), opts));
        utassert(CondCount(opts) == 1);
        utassert(CondAt(opts, 0)->tp == Type::HasContent);
        utassert(AnnotMatchesFields({}, StrL("a note"), AnnotationType::Text, opts));
        utassert(!AnnotMatchesFields({}, StrL(""), AnnotationType::Text, opts));
        utassert(!AnnotMatchesFields({}, {}, AnnotationType::Text, opts));
    }
    {
        // ":c-" keeps only the ones with none
        AnnotMatchOpts opts;
        utassert(ParseAnnotSearch(StrL(":c-"), opts));
        utassert(CondAt(opts, 0)->tp == Type::NoContent);
        utassert(!AnnotMatchesFields({}, StrL("a note"), AnnotationType::Text, opts));
        utassert(AnnotMatchesFields({}, StrL(""), AnnotationType::Text, opts));
        utassert(AnnotMatchesFields({}, {}, AnnotationType::Text, opts));
    }
    {
        // asking for both at once matches nothing, and must not be a parse error
        AnnotMatchOpts opts;
        utassert(ParseAnnotSearch(StrL(":c+ :c-"), opts));
        utassert(!AnnotMatchesFields({}, StrL("x"), AnnotationType::Text, opts));
        utassert(!AnnotMatchesFields({}, {}, AnnotationType::Text, opts));
    }
    {
        // conditions and words combine; contents match on substring, any case
        AnnotMatchOpts opts;
        utassert(ParseAnnotSearch(StrL(":a=kjk :t!=line :c+ TODO"), opts));
        utassert(CondCount(opts) == 4);
        utassert(AnnotMatchesFields(StrL("kjk"), StrL("a todo item"), AnnotationType::Text, opts));
        utassert(!AnnotMatchesFields(StrL("bob"), StrL("a todo item"), AnnotationType::Text, opts));
        utassert(!AnnotMatchesFields(StrL("kjk"), StrL("a todo item"), AnnotationType::Line, opts));
        utassert(!AnnotMatchesFields(StrL("kjk"), StrL("something else"), AnnotationType::Text, opts));
        StrVec words;
        AnnotSearchContentWords(opts, words);
        utassert(len(words) == 1);
        utassert(str::Eq(words[0], StrL("TODO")));
    }
    // malformed input is rejected rather than silently matching nothing
    TestParseFails(StrL(":a"));
    TestParseFails(StrL(":a="));
    TestParseFails(StrL(":a kjk"));
    TestParseFails(StrL(":t=nosuchtype"));
    TestParseFails(StrL(":zz=1"));
    TestParseFails(StrL(":a!kjk"));
    TestParseFails(StrL(":c"));
    TestParseFails(StrL(":c="));
    TestParseFails(StrL(":nc"));
    return true;
}

AnnotationType AnnotationTypeFromName(Str name) {
    TempStr want = str::DupTemp(name);
    want.len -= str::RemoveCharsInPlace(want, StrL(" -_"));
    if (len(want) == 0) {
        return AnnotationType::Unknown;
    }
    int idx = 0;
    SeqStrings names = gAnnotationTypeNames;
    for (int off = 0; SeqStrAt(names, off); idx++) {
        if (str::EqI(SeqStrAt(names, off), want)) {
            return (AnnotationType)idx;
        }
        if (!SeqStrAdvance(names, off)) {
            break;
        }
    }
    return AnnotationType::Unknown;
}

static void StartPickedFindTask(PickedTermData* d) {
    AutoDelete del(d);
    MainWindow* win = d->win;
    if (!IsMainWindowValidAndNotClosing(win) || !win->findEdit) {
        return;
    }
    if (!str::Eq(win->findEdit->GetTextTemp(), d->term)) {
        win->findEdit->SetText(d->term);
    }
    CbEditSetModified(win->findEdit, false);
    FindTextOnThread(win, TextSearch::Direction::Forward, d->term, true, false);
}

void StartPickedFindTerm(MainWindow* win, Str term) {
    if (!win || len(term) == 0) {
        return;
    }
    auto* d = new PickedTermData;
    d->win = win;
    d->term = str::Dup(term);
    uitask::Post(MkFunc0<PickedTermData>(StartPickedFindTask, d), "TaskFindHistoryPick");
}

static int DecimalDigits(int n) {
    int digits = 1;
    while (n >= 10) {
        n /= 10;
        digits++;
    }
    return digits;
}

int FindStatusDx(PlatformFont* font, int totalHits, bool capped) {
    int digits = DecimalDigits(std::max(totalHits, 0));
    int nChars = (2 * digits) + 3; // N, " / ", M
    if (capped) {
        nChars++; // the trailing '+' in e.g. "999 / 999+"
    }
    return nChars * font->averageCharWidth;
}

bool FindBarWnd::UpdateStatusWidth(int totalHits, bool capped) {
    if (!statusBox || totalHits < 0) {
        return false;
    }
    int dx = FindStatusDx(status->font, totalHits, capped);
    if (statusBox->dx == dx) {
        return false;
    }
    statusBox->dx = dx;
    statusTotalHits = totalHits;
    statusCapped = capped;
    return true;
}

int CbGetItemsCount(HWND hwnd) {
    if (!hwnd) {
        return 0;
    }
    int n = (int)SendMessageW(hwnd, CB_GETCOUNT, 0, 0);
    return n < 0 ? 0 : n;
}

static void ReplaceDropDownItems(HWND hwnd, StrVec& items) {
    for (int i = CbGetItemsCount(hwnd) - 1; i >= 0; i--) {
        CbDeleteString(hwnd, i);
    }
    int n = len(items);
    for (int i = 0; i < n; i++) {
        CbInsertString(hwnd, i, items[i]);
    }
}

static LRESULT CALLBACK DropDownProc(HWND hwnd, UINT msg, WPARAM wp, LPARAM lp, UINT_PTR, DWORD_PTR) {
    if (msg != WM_SIZE) {
        return DefSubclassProc(hwnd, msg, wp, lp);
    }
    int start = 0, end = 0;
    CbEditGetSelection(hwnd, start, end);
    LRESULT res = DefSubclassProc(hwnd, msg, wp, lp);
    CbEditSelectText(hwnd, start, end);
    return res;
}

static int HoverPyramidTopRow(int n) {
    int w = 1;
    while (((w * (w + 1)) / 2) < n) {
        w++;
    }
    return w;
}

static void AddHoverPyramidRow(VBox* vbox, const Vec<VirtCtrl*>& cells, int a0, int a1, int b0, int b1) {
    auto* hbox = new HBox();
    hbox->alignCross = CrossAxisAlign::Stretch;
    for (int i = a0; i < a1; i++) {
        hbox->AddChild(cells[i]);
    }
    for (int i = b0; i < b1; i++) {
        hbox->AddChild(cells[i]);
    }
    vbox->AddChild(hbox);
}

static void PaintHoverDropdownRightHalf(MainWindow* win, VirtHostPaintEvent* ev) {
    ToolbarVirt* tb = win ? win->toolbarVirt : nullptr;
    if (!tb) {
        return;
    }
    Vec<ToolbarHoverItemState>& items = tb->hoverItems;
    int n = len(items);
    constexpr int kMaxRows = 32;
    int rowTop[kMaxRows];
    int rowBottom[kMaxRows];
    int rowSplit[kMaxRows];
    int nRows = 0;
    int prevTop = INT_MIN;
    while (nRows < kMaxRows) {
        // the topmost row below the last one found
        int y = INT_MAX;
        for (int i = 0; i < n; i++) {
            // only a strip has halves; a menu's rows are all one ground
            VirtCtrl* c = items[i].isStripCell ? items[i].ctrl : nullptr;
            if (c) {
                int cy = c->BoundsInWindow().y;
                if (cy > prevTop && cy < y) {
                    y = cy;
                }
            }
        }
        if (y == INT_MAX) {
            break;
        }
        int bottom = y;
        int right = INT_MIN;
        int split = INT_MAX;
        for (int i = 0; i < n; i++) {
            VirtCtrl* c = items[i].ctrl;
            if (!c) {
                continue;
            }
            Rect r = c->BoundsInWindow();
            if (r.y != y) {
                continue;
            }
            bottom = std::max(bottom, r.y + r.dy);
            right = std::max(right, r.x + r.dx);
            if (items[i].isRightHalf) {
                split = std::min(split, r.x);
            }
        }
        if (split == INT_MAX) {
            // nothing of the larger side in this row: only the space past its
            // end is on that side
            split = right;
        }
        rowTop[nRows] = y;
        rowBottom[nRows] = bottom;
        rowSplit[nRows] = split;
        nRows++;
        prevTop = y;
    }
    Rect cr = ev->clientRect;
    Color col = TbSubtleBgColor();
    for (int i = 0; i < nRows; i++) {
        // the first and last bands take in the border, so no strip of the
        // other ground is left above or below them
        int y = (i == 0) ? cr.y : rowTop[i];
        int bottom = (i == nRows - 1) ? cr.y + cr.dy : rowBottom[i];
        int x = rowSplit[i];
        ev->gfx->FillRect(Rect{x, y, (cr.x + cr.dx) - x, bottom - y}, col);
    }
}

TempStr ZoomLevelStrExact(float zoom) {
    if (zoom <= 0) {
        return ZoomLevelStr(zoom);
    }
    return fmt("%g%%", zoom);
}

void CustomZoomWnd::SetEditFromSelection() {
    int idx = listBox ? listBox->GetCurrentSelection() : -1;
    if (!editZoom || idx < 0 || idx >= len(zoomLevels)) {
        return;
    }
    editZoom->SetText(ZoomLevelStrExact(zoomLevels[idx]));
    EditSelectAll(editZoom);
}

void CustomZoomWnd::SelectLevelFromEdit() {
    if (!listBox || !editZoom) {
        return;
    }
    TempStr text = editZoom->GetTextTemp();
    int sel = -1;
    for (int i = 0; i < len(zoomLevels); i++) {
        if (str::EqI(text, ZoomLevelStrExact(zoomLevels[i]))) {
            sel = i;
            break;
        }
    }
    listBox->SetCurrentSelection(sel);
    if (sel >= 0) {
        listBox->EnsureVisible(sel);
    }
}

bool CustomZoomWnd::MoveSelection(int vkey) {
    if (!listBox) {
        return false;
    }
    int n = listBox->ItemsCount();
    if (n == 0) {
        return false;
    }
    int sel = listBox->GetCurrentSelection();
    if (sel < 0) {
        // a typed zoom that is none of them: step into the list from the end
        // the key comes from
        sel = (vkey == VK_UP) ? n - 1 : 0;
    } else if (vkey == VK_UP) {
        sel = std::max(sel - 1, 0);
    } else {
        sel = std::min(sel + 1, n - 1);
    }
    listBox->SetCurrentSelection(sel);
    listBox->EnsureVisible(sel);
    SetEditFromSelection();
    return true;
}

void CustomZoomWnd::OnKeyDown(KeyEvent* ev) {
    if (ev->vkey == VK_UP || ev->vkey == VK_DOWN) {
        ev->didHandle = MoveSelection(ev->vkey);
    }
}

static void TakeHoverButtonTooltip(MainWindow* win, int cmdId) {
    ToolbarVirt* tb = win->toolbarVirt;
    if (VirtCtrl* btn = ToolbarItemForCmd(win, cmdId)) {
        str::ReplaceWithCopy(&tb->hoverSavedTip, btn->tooltip);
        btn->SetTooltip({});
    }
}

static void GiveHoverButtonTooltipBack(MainWindow* win) {
    ToolbarVirt* tb = win->toolbarVirt;
    if (tb->hoverCmdId == 0) {
        return;
    }
    if (VirtCtrl* btn = ToolbarItemForCmd(win, tb->hoverCmdId)) {
        btn->SetTooltip(tb->hoverSavedTip);
    }
    str::Free(tb->hoverSavedTip);
    tb->hoverSavedTip = {};
}

void SetToolbarHoverDropdown(MainWindow* win, int cmdId, const Func1<ToolbarHoverBuildEvent*>& build, int groupId) {
        reg->groupId = groupId;
    reg.groupId = groupId;
    TakeHoverButtonTooltip(win, cmdId);
            ToolbarHoverReg* from = FindHoverReg(tb, tb->hoverCmdId);
            ToolbarHoverReg* to = FindHoverReg(tb, cmdId);
            int group = from ? from->groupId : 0;
            if (group != 0 && to && to->groupId == group) {
                // both buttons share this drop-down, so it stays put: the two
                // sit side by side and sliding it between them would be a
                // twitch, not a new drop-down
                tb->host->KillTimer(kCloseHoverDropdownTimerId);
                GiveHoverButtonTooltipBack(win);
                tb->hoverCmdId = cmdId;
                TakeHoverButtonTooltip(win, cmdId);
                return;
            }
    // one strip for the two of them, so it doesn't jump when the mouse crosses
    // from one to the other
    SetToolbarHoverDropdown(win, CmdZoomIn, MkFunc1(BuildZoomHoverMenu, win), CmdZoomIn);
    SetToolbarHoverDropdown(win, CmdZoomOut, MkFunc1(BuildZoomHoverMenu, win), CmdZoomIn);

void Paint(VirtPaintCtx& ctx) override {
        bool enabled = IsEnabled();
        Rect r = ctx.bounds;
        if (enabled && HasFlag(vwfHovered)) {
            ctx.gfx->FillRect(r, TbHoverColor());
        }
        if (isCurrent) {
            ctx.gfx->DrawRect(r, TbTextColor(), DpiScale(1));
        }
        Color col = enabled ? TbTextColor() : TbDisabledColor();
        ctx.gfx->DrawText(text, r, gfxTextCenter | gfxTextVCenter, font, col);
    }

static void RecordHoverItem(ToolbarVirt* tb, VirtCtrl* w, Str text, const ToolbarHoverMenuItem& it) {
    ToolbarHoverItemState st;
    st.ctrl = w;
    st.text = text;
    st.cmdId = it.cmdId;
    st.isCurrent = it.isCurrent;
    VecAppend(tb->hoverItems, st);
}

ILayout* NewToolbarHoverStrip(MainWindow* win, const Vec<ToolbarHoverMenuItem>& items, VirtCtrl** currentOut) {
    ToolbarVirt* tb = win ? win->toolbarVirt : nullptr;
    if (!tb) {
        return nullptr;
    }
    auto* hbox = new HBox();
    hbox->alignCross = CrossAxisAlign::Stretch;
    for (const ToolbarHoverMenuItem& it : items) {
        auto* cell = new ToolbarHoverCell();
        cell->id = it.cmdId;
        cell->font = tb->platformFont;
        cell->isCurrent = it.isCurrent;
        str::ReplaceWithCopy(&cell->text, it.text);
        cell->SetIsEnabled(it.enabled);
        cell->onClick = MkFunc1(OnHoverRowClicked, win);
        hbox->AddChild(cell);
        RecordHoverItem(tb, cell, cell->text, it);
        tb->hoverItems[len(tb->hoverItems) - 1].isStripCell = true;
        if (it.isCurrent && currentOut) {
            *currentOut = cell;
        }
    }
    int b = DpiScale(kHoverMenuBorder);
    return new Padding(hbox, Insets{b, b, b, b});
}

static TempStr HoverDropdownStateTemp(MainWindow* win) {
    ToolbarVirt* tb = win ? win->toolbarVirt : nullptr;
    VirtHost* host = tb ? tb->hoverHost : nullptr;
    if (!host) {
        return StrL("dropdown cmd=0 items=0\n");
    }
    str::Builder out;
    int n = len(tb->hoverItems);
    out.Append(fmt("dropdown cmd=%d items=%d\n", tb->hoverCmdId, n));
    for (int i = 0; i < n; i++) {
        ToolbarHoverItemState& st = tb->hoverItems[i];
        Rect r = st.ctrl ? host->ToScreen(st.ctrl->BoundsInWindow()) : Rect{};
        out.Append(fmt("dropdown-item idx=%d cmd=%d current=%d rect=%d,%d,%d,%d text=%s\n", i, st.cmdId,
                       st.isCurrent ? 1 : 0, r.x, r.y, r.x + r.dx, r.y + r.dy, st.text));
    }
    return ToStrTemp(out);
}

static void ZoomHoverLevels(Vec<ZoomHoverLevel>& out) {
    int n = 0;
    float* levels = GetDefaultZoomLevels(&n);
    Vec<int>* cmdIds = GetZoomStepCmdIds();
    if (!levels || !cmdIds || len(*cmdIds) != n) {
        return;
    }
    bool addedFits = false;
    for (int i = 0; i < n; i++) {
        if (!addedFits && levels[i] > 100) {
            // the fit modes go where their size puts them, i.e. right after
            // 100% in every list that has it
            VecAppend(out, ZoomHoverLevel{kZoomFitPage, CmdZoomFitPage});
            VecAppend(out, ZoomHoverLevel{kZoomFitWidth, CmdZoomFitWidth});
            addedFits = true;
        }
        VecAppend(out, ZoomHoverLevel{levels[i], (*cmdIds)[i]});
    }
    if (!addedFits) {
        VecAppend(out, ZoomHoverLevel{kZoomFitPage, CmdZoomFitPage});
        VecAppend(out, ZoomHoverLevel{kZoomFitWidth, CmdZoomFitWidth});
    }
}

static TempStr ZoomHoverLevelStrTemp(float zoom) {
    if (zoom < 0) {
        // a fit mode
        return ZoomLevelStr(zoom);
    }
    // ZoomLevelStr() rounds, which would show 12.5% as "12%"; the Zoom menu's
    // rows for the same levels don't, so neither do ours
    return fmt("%g%%", zoom);
}

static int ZoomHoverCurrentIdx(MainWindow* win, const Vec<ZoomHoverLevel>& levels) {
    DocController* ctrl = win ? win->ctrl : nullptr;
    if (!ctrl) {
        return -1;
    }
    float current = ctrl->GetZoomVirtual(false);
    // the same fuzz DisplayModel::GetNextZoomStep uses to match a level
    constexpr float kZoomFuzz = 0.01f;
    for (int i = 0; i < len(levels); i++) {
        float zl = levels[i].zoom;
        if (current + kZoomFuzz >= zl && current - kZoomFuzz <= zl) {
            return i;
        }
    }
    return -1;
}

static void BuildZoomHoverMenu(MainWindow* win, ToolbarHoverBuildEvent* ev) {
    DocController* ctrl = win ? win->ctrl : nullptr;
    if (!ctrl) {
        return;
    }
    Vec<ZoomHoverLevel> levels;
    ZoomHoverLevels(levels);
    int currentIdx = ZoomHoverCurrentIdx(win, levels);

    Vec<ToolbarHoverMenuItem> items;
    for (int i = 0; i < len(levels); i++) {
        ToolbarHoverMenuItem it;
        it.text = ZoomHoverLevelStrTemp(levels[i].zoom);
        it.cmdId = levels[i].cmdId;
        it.isCurrent = i == currentIdx;
        VecAppend(items, it);
    }

    VirtCtrl* anchorCtrl = nullptr;
    ev->layout = NewToolbarHoverStrip(win, items, &anchorCtrl);
    ToolbarVirt* tb = win->toolbarVirt;
    if (!anchorCtrl) {
        // at a zoom none of them is: anchor on the level it is closest to, so
        // the strip still opens around where the zoom is
        float absolute = ctrl->GetZoomVirtual(true);
        int nearest = -1;
        float nearestDiff = 0;
        for (int i = 0; i < len(levels); i++) {
            float zl = levels[i].zoom;
            if (zl <= 0) {
                continue;
            }
            float diff = absolute > zl ? absolute - zl : zl - absolute;
            if (nearest < 0 || diff < nearestDiff) {
                nearest = i;
                nearestDiff = diff;
            }
        }
        if (nearest >= 0 && nearest < len(tb->hoverItems)) {
            anchorCtrl = tb->hoverItems[nearest].ctrl;
        }
    }
    ev->anchor = anchorCtrl;
}

static void UpdateZoomHoverDropdown(MainWindow* win) {
    ToolbarVirt* tb = win ? win->toolbarVirt : nullptr;
    if (!tb || !tb->hoverHost) {
        return;
    }
    if (tb->hoverCmdId != CmdZoomIn && tb->hoverCmdId != CmdZoomOut) {
        return;
    }
    Vec<ZoomHoverLevel> levels;
    ZoomHoverLevels(levels);
    int currentIdx = ZoomHoverCurrentIdx(win, levels);
    for (int i = 0; i < len(tb->hoverItems); i++) {
        ToolbarHoverItemState& st = tb->hoverItems[i];
        if (!st.isStripCell || !st.ctrl) {
            continue;
        }
        bool isCurrent = i == currentIdx;
        auto* cell = (ToolbarHoverCell*)st.ctrl;
        if (cell->isCurrent == isCurrent) {
            continue;
        }
        cell->isCurrent = isCurrent;
        st.isCurrent = isCurrent;
        cell->Invalidate();
    }
}

static float
flow_line_top(fz_html_flow *flow)
{
	float y = flow->y - flow->box->s.layout.em;
	return y < 0 ? 0 : y;
}

static VirtCtrl* ToolbarItemForCmd(MainWindow* win, int cmdId) {
    ToolbarVirt* tb = win ? win->toolbarVirt : nullptr;
    if (!tb) {
        return nullptr;
    }
    for (VirtCtrl* w : tb->items) {
        if (w && w->id == cmdId && w->GetVisibility() == Visibility::Visible) {
            return w;
        }
    }
    for (VirtCtrl* w : tb->annotationItems) {
        if (w && w->id == cmdId && w->GetVisibility() == Visibility::Visible) {
            return w;
        }
    }
    return nullptr;
}

int ShortcutDx() {
        if (!shortcut) {
            return 0;
        }
        return PlatformFontMeasureText(font, shortcut).dx + DpiScale(kHoverRowShortcutGapX);
    }

Size GetIdealSize() override {
        Size ts = PlatformFontMeasureText(font, text);
        int dx = (2 * DpiScale(kHoverRowPadX)) + iconSize + DpiScale(kHoverRowIconGapX) + ts.dx + ShortcutDx();
        int dy = std::max(ts.dy, iconSize) + (2 * DpiScale(kHoverRowPadY));
        return {dx, dy};
    }

void Paint(VirtPaintCtx& ctx) override {
        bool enabled = IsEnabled();
        Rect r = ctx.bounds;
        if (enabled && HasFlag(vwfHovered)) {
            ctx.gfx->FillRect(r, TbHoverColor());
        }
        int x = r.x + DpiScale(kHoverRowPadX);
        if (pixmap) {
            int y = r.y + ((r.dy - pixmap->height) / 2);
            ctx.gfx->DrawPixmap(pixmap, {x, y, pixmap->width, pixmap->height});
        }
        x += iconSize + DpiScale(kHoverRowIconGapX);
        int right = r.Right() - DpiScale(kHoverRowPadX);
        Color col = enabled ? TbTextColor() : TbDisabledColor();
        if (shortcut) {
            // right-aligned and dimmer, the way a menu shows its accelerator
            Rect sr{x, r.y, right - x, r.dy};
            ctx.gfx->DrawText(shortcut, sr, gfxTextRight | gfxTextVCenter, font, TbDisabledColor());
            right -= ShortcutDx();
        }
        Rect tr{x, r.y, right - x, r.dy};
        ctx.gfx->DrawText(text, tr, gfxTextVCenter | gfxTextEllipsis, font, col);
    }

static void PostedHideHoverDropdown(MainWindow* win) {
    if (IsMainWindowValidAndNotClosing(win)) {
        HideToolbarHoverDropdown(win);
    }
}

static void OnHoverRowClicked(MainWindow* win, VirtMouseEvent* ev) {
    VirtCtrl* w = ev ? ev->target : nullptr;
    if (!w || !w->IsEnabled()) {
        return;
    }
    int cmdId = w->id;
    // the click is being handled by the drop-down's own window, so it can only
    // be torn down once that returns
    uitask::Post(MkFunc0(PostedHideHoverDropdown, win), "HideToolbarHoverDropdown");
    ToolbarPostCommand(win, cmdId);
}

ILayout* NewToolbarHoverMenu(MainWindow* win, const Vec<ToolbarHoverMenuItem>& items) {
    ToolbarVirt* tb = win ? win->toolbarVirt : nullptr;
    if (!tb) {
        return nullptr;
    }
    int iconSize = tb->iconSize;
    Color fg = TbTextColor();
    Color dis = TbDisabledColor();
    Color bg = TbBgColor();
    auto* vbox = new VBox();
    vbox->alignCross = CrossAxisAlign::Stretch;
    for (const ToolbarHoverMenuItem& it : items) {
        auto* row = new ToolbarHoverRow();
        row->id = it.cmdId;
        row->font = tb->platformFont;
        row->iconSize = iconSize;
        str::ReplaceWithCopy(&row->text, it.text);
        str::ReplaceWithCopy(&row->shortcut, ShortcutsForCmdTemp(it.cmdId, 1));
        if (it.svgIcon) {
            row->pixmap = GetCachedPixmapForSvg(it.svgIcon, iconSize, iconSize, it.enabled ? fg : dis, bg);
        }
        row->SetIsEnabled(it.enabled);
        row->onClick = MkFunc1(OnHoverRowClicked, win);
        vbox->AddChild(row);
    }
    int b = DpiScale(kHoverMenuBorder);
    return new Padding(vbox, Insets{b, b, b, b});
}

static void OnHoverDropdownMouseLeave(MainWindow* win) {
    ToolbarVirt* tb = win ? win->toolbarVirt : nullptr;
    if (tb && tb->host && tb->hoverCmdId != 0) {
        tb->host->SetTimer(kCloseHoverDropdownTimerId, kCloseHoverDropdownDelayMs);
    }
}

void HideToolbarHoverDropdown(MainWindow* win) {
    ToolbarVirt* tb = win ? win->toolbarVirt : nullptr;
    if (!tb) {
        return;
    }
    if (tb->hoverCmdId != 0) {
        if (VirtCtrl* btn = ToolbarItemForCmd(win, tb->hoverCmdId)) {
            btn->SetTooltip(tb->hoverSavedTip);
        }
        str::Free(tb->hoverSavedTip);
        tb->hoverSavedTip = {};
    }
    tb->hoverPendingCmdId = 0;
    tb->hoverCmdId = 0;
    if (tb->host) {
        tb->host->KillTimer(kOpenHoverDropdownTimerId);
        tb->host->KillTimer(kCloseHoverDropdownTimerId);
    }
    if (tb->hoverHost) {
        VirtHost* h = tb->hoverHost;
        tb->hoverHost = nullptr;
        delete h;
    }
}

static ToolbarHoverReg* FindHoverReg(ToolbarVirt* tb, int cmdId) {
    if (!tb || cmdId == 0) {
        return nullptr;
    }
    for (ToolbarHoverReg& reg : tb->hoverRegs) {
        if (reg.cmdId == cmdId) {
            return &reg;
        }
    }
    return nullptr;
}

void SetToolbarHoverDropdown(MainWindow* win, int cmdId, const Func1<ToolbarHoverBuildEvent*>& build) {
    ToolbarVirt* tb = win ? win->toolbarVirt : nullptr;
    if (!tb) {
        return;
    }
    if (ToolbarHoverReg* reg = FindHoverReg(tb, cmdId)) {
        reg->build = build;
        return;
    }
    ToolbarHoverReg reg;
    reg.cmdId = cmdId;
    reg.build = build;
    VecAppend(tb->hoverRegs, reg);
}

static void OpenHoverDropdown(MainWindow* win, int cmdId) {
    ToolbarVirt* tb = win ? win->toolbarVirt : nullptr;
    ToolbarHoverReg* reg = FindHoverReg(tb, cmdId);
    if (!reg || !reg->build.IsValid() || !tb->host) {
        return;
    }
    Rect anchor = GetToolbarButtonScreenRect(win, cmdId);
    if (anchor.IsEmpty()) {
        return;
    }
    ToolbarHoverBuildEvent ev;
    ev.win = win;
    reg->build.Call(&ev);
    if (!ev.layout) {
        return;
    }

    VirtHost::CreateArgs args;
    args.parent = win->hwndFrame;
    args.className = WStrL(L"SumatraToolbarHoverMenu");
    args.isPopup = true;
    args.visible = false;
    args.noActivate = true;
    args.userData = win;
    args.bgColor = TbBgColor();
    args.isRtl = IsUIRtl();
    args.initialSize = {100, 100};
    VirtHost* host = VirtHost::Create(args);
    if (!host) {
        delete ev.layout;
        return;
    }
    host->onPaintBackground = MkFunc1(PaintHoverDropdownBg, win);
    host->onMouseLeave = MkFunc0(OnHoverDropdownMouseLeave, win);
    Size sz = host->SetLayoutSizedToContent(ev.layout);

    // under the button, left edges aligned, kept on the monitor
    Rect r{anchor.x, anchor.Bottom(), sz.dx, sz.dy};
    r = ShiftRectToWorkArea(r, win->hwndFrame, true);
    host->SetPos(r, true);

    // the button's tooltip would sit on top of the drop-down, and WM_SETCURSOR
    // would bring it back, so the button goes without one until this closes
    // the button's tooltip would sit on top of the drop-down, and WM_SETCURSOR
    // would bring it back, so the button goes without one until this closes
    if (VirtCtrl* btn = ToolbarItemForCmd(win, cmdId)) {
        str::ReplaceWithCopy(&tb->hoverSavedTip, btn->tooltip);
        btn->SetTooltip({});
    }
    if (tb->host->vroot) {
        tb->host->vroot->HideTooltip();
    }
    tb->hoverHost = host;
    tb->hoverCmdId = cmdId;
    tb->hoverPendingCmdId = 0;
}

static void ToolbarHoverDropdownOnMouseMove(MainWindow* win) {
    ToolbarVirt* tb = win ? win->toolbarVirt : nullptr;
    if (!tb || !tb->host || len(tb->hoverRegs) == 0) {
        return;
    }
    Point ptScreen = UiCursorScreenPos();
    bool overMenu = ToolbarHoverDropdownContainsScreenPoint(win, ptScreen);
    int cmdId = 0;
    if (HostHasPoint(tb->host, ptScreen)) {
        // a disabled button still gets its drop-down, the way it still gets its
        // tooltip: the rows say what could be done and why they are greyed
        VirtCtrl* w = ToolbarItemFromPoint(win, tb->host->FromScreen(ptScreen));
        if (w && FindHoverReg(tb, w->id)) {
            cmdId = w->id;
        }
    }

    if (tb->hoverCmdId != 0) {
        // one is open: keep it while the mouse is on its button or in it
        if (overMenu || cmdId == tb->hoverCmdId) {
            tb->host->KillTimer(kCloseHoverDropdownTimerId);
            return;
        }
        tb->host->SetTimer(kCloseHoverDropdownTimerId, kCloseHoverDropdownDelayMs);
        return;
    }
    if (cmdId == tb->hoverPendingCmdId) {
        return;
    }
    tb->hoverPendingCmdId = cmdId;
    tb->host->KillTimer(kOpenHoverDropdownTimerId);
    if (cmdId != 0) {
        tb->host->SetTimer(kOpenHoverDropdownTimerId, UiTooltipDelayMs());
    }
}

static void OnHoverDropdownTimer(MainWindow* win, int timerId) {
    ToolbarVirt* tb = win ? win->toolbarVirt : nullptr;
    if (!tb || !tb->host) {
        return;
    }
    if (timerId == kOpenHoverDropdownTimerId) {
        tb->host->KillTimer(kOpenHoverDropdownTimerId);
        int cmdId = tb->hoverPendingCmdId;
        tb->hoverPendingCmdId = 0;
        if (cmdId != 0) {
            OpenHoverDropdown(win, cmdId);
        }
        return;
    }
    tb->host->KillTimer(kCloseHoverDropdownTimerId);
    Point pt = UiCursorScreenPos();
    if (ToolbarHoverDropdownContainsScreenPoint(win, pt)) {
        return;
    }
    // still on the button that opened it: leave it up
    if (GetToolbarButtonScreenRect(win, tb->hoverCmdId).Contains(pt)) {
        return;
    }
    HideToolbarHoverDropdown(win);
}

static void BuildSaveHoverMenu(MainWindow* win, ToolbarHoverBuildEvent* ev) {
    WindowTab* tab = win ? win->CurrentTab() : nullptr;
    auto* ctx = NewBuildMenuCtx(tab, Point{0, 0});
    AutoCall delCtx(DeleteBuildMenuCtx, ctx);
    bool dirty = ctx->hasUnsavedAnnotations;

    TempStr base = tab ? path::GetBaseNameTemp(tab->filePath) : TempStr{};
    Str saveText = _TRA("Save changes to existing PDF");
    if (len(base) > 0) {
        saveText = fmt(_TRA("Save changes to %s").s, base);
    }

    Vec<ToolbarHoverMenuItem> items;
    VecAppend(items, {Str(gIconSave), saveText, CmdSaveAnnotations, dirty});
    VecAppend(items, {Str(gIconSaveToNewFile), _TRA("Save changes to a new PDF"), CmdSaveAnnotationsNewFile, dirty});
    VecAppend(items, {Str(gIconTrash), _TRA("Discard changes"), CmdDiscardChanges, dirty});
    ev->layout = NewToolbarHoverMenu(win, items);
}

static bool SetPdfAnnotationButtonHiddenByIdx(MainWindow* win, int idx, bool isHidden) {
    VirtCtrl* w = PdfAnnotationToolbarItemAt(win, idx);
    if (!w) {
        return false;
    }
    Visibility want = isHidden ? Visibility::Collapse : Visibility::Visible;
    if (w->GetVisibility() == want) {
        return false;
    }
    w->SetVisibility(want);
    return true;
}

