NO_INLINE void* VecInsertSpaceNonTemplated(VecNonTemplated* v, int elSize, int idx, int count) {
    int len = v->len;
    int newLen = std::max(len, idx) + count;
    if (!VecReserveNonTemplated(nullptr, v, elSize, newLen)) {
        return nullptr;
    }
    char* res = (char*)v->els + (size_t)idx * (size_t)elSize;
    if (len > idx) {
        char* dst = res + (size_t)count * (size_t)elSize;
        memmove(dst, res, (size_t)(len - idx) * (size_t)elSize);
    }
    v->len = newLen;
    return res;
}

NO_INLINE bool VecResizeNonTemplated(VecNonTemplated* v, int elSize, int newSize) {
    if (newSize < 0) {
        return false;
    }
    int curCap = v->cap < 0 ? -v->cap : v->cap;
    if (newSize > curCap) {
        if (!VecReserveNonTemplated(nullptr, v, elSize, newSize)) {
            return false;
        }
        curCap = v->cap < 0 ? -v->cap : v->cap;
    }
    v->len = newSize;
    if (v->els && curCap > newSize) {
        char* tail = (char*)v->els + (size_t)newSize * (size_t)elSize;
        memset(tail, 0, (size_t)(curCap - newSize) * (size_t)elSize);
    }
    return true;
}

NO_INLINE void VecRemoveAtNonTemplated(VecNonTemplated* v, int elSize, int idx, int count) {
    int len = v->len;
    char* els = (char*)v->els;
    if (len > idx + count) {
        char* dst = els + (size_t)idx * (size_t)elSize;
        char* src = els + (size_t)(idx + count) * (size_t)elSize;
        memmove(dst, src, (size_t)(len - idx - count) * (size_t)elSize);
    }
    len -= count;
    memset(els + (size_t)len * (size_t)elSize, 0, (size_t)count * (size_t)elSize);
    v->len = len;
}

NO_INLINE void VecRemoveAtFastNonTemplated(VecNonTemplated* v, int elSize, int idx) {
    int len = v->len;
    ReportIf(idx >= len);
    if (idx >= len) {
        return;
    }
    char* els = (char*)v->els;
    char* toRemove = els + (size_t)idx * (size_t)elSize;
    char* last = els + (size_t)(len - 1) * (size_t)elSize;
    if (toRemove != last) {
        memcpy(toRemove, last, (size_t)elSize);
    }
    memset(last, 0, (size_t)elSize);
    v->len = len - 1;
}

NO_INLINE void VecFreeElsNonTemplated(VecNonTemplated* v) {
    if (!v->els) {
        return;
    }
    if (v->cap > 0) {
        Free(nullptr, v->els);
    } else {
        v->cap = 0;
    }
    v->els = nullptr;
}

NO_INLINE void VecClearNonTemplated(VecNonTemplated* v, int elSize) {
    v->len = 0;
    int curCap = v->cap < 0 ? -v->cap : v->cap;
    if (v->els && curCap > 0) {
        memset(v->els, 0, (size_t)curCap * (size_t)elSize);
    }
}

NO_INLINE void* VecTakeNonTemplated(VecNonTemplated* v, int elSize) {
    void* els = v->els;
    if (v->cap < 0) {
        int n = v->len;
        v->els = nullptr;
        v->cap = 0;
        v->len = 0;
        if (n <= 0) {
            return nullptr;
        }
        if (!VecRealloc(nullptr, &v->els, 0, &v->cap, n, elSize)) {
            return nullptr;
        }
        void* res = v->els;
        memcpy(res, els, (size_t)n * (size_t)elSize);
        v->els = nullptr;
        v->cap = 0;
        return res;
    }
    v->els = nullptr;
    v->len = 0;
    v->cap = 0;
    return els;
}

static int VecNextCap(int cap, int wanted, int elSize) {
    if (cap == 0) {
        int floorCap = elSize == 1 ? 8 : elSize <= 1024 ? 4 : 1;
        return std::max(floorCap, wanted);
    }
    return std::max(cap * 2, wanted);
}

NO_INLINE bool VecReserveNonTemplated(Arena* arena, VecNonTemplated& v, int wantedSize) {
    int elSize = v.elSize;
    int curCap = v.cap < 0 ? -v.cap : v.cap;
    if (wantedSize <= curCap) {
        return true;
    }
    int newCap = VecNextCap(curCap, wantedSize, elSize);
    if (v.cap < 0) {
        void* borrowed = *v.pels;
        *v.pels = nullptr;
        v.cap = 0;
        if (!VecRealloc(arena, v.pels, 0, &v.cap, newCap, elSize)) {
            *v.pels = borrowed;
            v.cap = -curCap;
            return false;
        }
        if (v.len > 0) {
            memcpy(*v.pels, borrowed, (size_t)v.len * (size_t)elSize);
        }
        return true;
    }
    return VecRealloc(arena, v.pels, v.len, &v.cap, newCap, elSize);
}

int SkipWs(Str& s) {
    int i = 0;
    while (i < s.len && IsWs(s.s[i])) {
        i++;
    }
    s.s += i;
    s.len -= i;
    return i;
}

int SkipNonWs(Str& s) {
    int i = 0;
    while (i < s.len && !IsWs(s.s[i])) {
        i++;
    }
    s.s += i;
    s.len -= i;
    return i;
}

Str NextWord(Str& s) {
    SkipWs(s);
    Str word = s;
    word.len = SkipNonWs(s);
    if (word.len == 0) {
        return {};
    }
    return word;
}

Str TrimWs(Str s, TrimOpt opt) {
    if (IsNull(s)) {
        return s;
    }
    if (opt != TrimOpt::Right) {
        SkipWs(s);
    }
    if (opt != TrimOpt::Left) {
        while (s.len > 0 && IsWs(s.s[s.len - 1])) {
            s.len--;
        }
    }
    return s;
}

static void StrSkipWsTest() {
    // SkipWs / SkipNonWs eat from the front and report how much they ate
    Str s = StrL("  \t ab c");
    utassert(str::SkipWs(s) == 4 && str::Eq(s, StrL("ab c")));
    utassert(str::SkipWs(s) == 0 && str::Eq(s, StrL("ab c")));
    utassert(str::SkipNonWs(s) == 2 && str::Eq(s, StrL(" c")));

    s = StrL("   ");
    utassert(str::SkipWs(s) == 3 && len(s) == 0);
    s = StrL("");
    utassert(str::SkipWs(s) == 0 && str::SkipNonWs(s) == 0);

    // NextWord walks the whitespace-separated words
    Str rest = StrL("  one\ttwo\r\nthree  ");
    utassert(str::Eq(str::NextWord(rest), StrL("one")));
    utassert(str::Eq(str::NextWord(rest), StrL("two")));
    utassert(str::Eq(str::NextWord(rest), StrL("three")));
    utassert(!str::NextWord(rest));

    rest = StrL(" \t ");
    utassert(!str::NextWord(rest));

    // TrimWs only narrows the view, the string itself isn't touched
    Str orig = StrL(" \t a b \n");
    utassert(str::Eq(str::TrimWs(orig), StrL("a b")));
    utassert(str::Eq(str::TrimWs(orig, str::TrimOpt::Left), StrL("a b \n")));
    utassert(str::Eq(str::TrimWs(orig, str::TrimOpt::Right), StrL(" \t a b")));
    utassert(len(orig) == 8);
    utassert(len(str::TrimWs(StrL("  "))) == 0);
    utassert(str::IsNull(str::TrimWs(Str{})));
}

static int ParseLimitedNumber(Str& s, int formatOff, Str format, const ParseArg& valueOut) {
    unsigned int width;
    char f2[] = "% ";
    Str formatAt = Str(format.s + formatOff, format.len - formatOff);
    Str endF = Parse(formatAt, "%u%c", &width, &f2[1]);
    if (!str::IsNull(endF) && str::ContainsChar(StrL("udx"), f2[1]) && width <= (unsigned)s.len) {
        char limited[16]; // 32-bit integers are at most 11 characters long
        str::BufSet(Str(limited, std::min((int)width + 1, dimofi(limited))), Str(s.s, (int)width));
        Str end = ParseArgs(Str(limited), f2, &valueOut, 1);
        if (!str::IsNull(end) && !end.s[0]) {
            Eat(s, (int)width);
            return (int)(endF.s - format.s) - 1;
        }
    }
    return -1;
}

static bool* FindBoolSettingInStruct(const StructInfo* info, u8* base, Str pathPrefix, Str name) {
    if (!info || !base || len(name) == 0) {
        return nullptr;
    }
    const char* fieldName = info->fieldNames;
    for (u16 i = 0; i < info->fieldCount; i++) {
        const FieldInfo& field = info->fields[i];
        Str fname(fieldName);
        fieldName += len(fname) + 1;
        if (field.type == SettingType::Comment || field.offset == (size_t)-1) {
            continue;
        }
        u8* fieldPtr = base + field.offset;
        TempStr path = len(pathPrefix) > 0 ? fmt("%s.%s", pathPrefix, fname) : str::DupTemp(fname);
        if (field.type == SettingType::Struct) {
            const auto* sub = (const StructInfo*)field.value;
            bool* found = FindBoolSettingInStruct(sub, fieldPtr, path, name);
            if (found) {
                return found;
            }
            continue;
        }
        if (field.type != SettingType::Bool) {
            continue;
        }
        if (str::EqI(fname, name) || str::EqI(path, name)) {
            return (bool*)fieldPtr;
        }
    }
    return nullptr;
}

