onst char *cjk_enc_cmap_name(int enc)
{
	switch (enc)
	case ENC_KOREAN: return "UniKS-UCS2-H";
	case ENC_JAPANESE: return "UniJIS-UCS2-H";
	case ENC_HANT: return "UniCNS-UCS2-H";
	case ENC_HANS: return "UniGB-UCS2-H";
