static void stamp_message_info(void *payload, const app_ur_session *elem) {
  /* Zero-initialized: message_info has padding between msgnum and mstime, and
   * the whole struct is copied onto the wire. */
  message_info mi = {0};
  mi.msgnum = elem->wmsgnum;
  mi.mstime = current_mstime;
  memcpy(payload, &mi, sizeof(mi));
}

static void copy_auth_parameters(ts_ur_super_session *orig_ss, ts_ur_super_session *ss, bool acquire_quota) {
    if (acquire_quota) {
      inc_quota(ss, ss->username);
    }
   * session; both hold the same owner credentials after the resume. The
   * allocation's single quota unit stays on the surviving session (acquire_quota
   * re-checks it under the refreshed identity); the pending session was never
   * separately charged, so its teardown below releases nothing. */
    copy_auth_parameters(pending_ss, orig_ss, true);
            // acquire_quota=false: orig_ss keeps holding the allocation's single
            // quota unit for the whole mobility grace period, so charging this
            // temporary resuming session too would double-count and reject
            // legitimate resumes under --user-quota / --total-quota.
            copy_auth_parameters(orig_ss, ss, false);
  /* A first-stage mobility close only suspends the session: it keeps the
   * allocation, relay socket, and mobility ticket alive for a later resume.
   * The allocation and bandwidth quota charge must stay held for as long as the
   * allocation remains resumable; releasing it here would let an authenticated
   * client disconnect and immediately re-allocate past --user-quota /
   * --total-quota. The charge is released only in the
   * final (2nd stage) teardown below. */
  /* Final teardown: the allocation is gone, so release its quota and bandwidth
   * charge now (a first-stage mobility close returned above without releasing). */
  dec_quota(ss);
  dec_bps(ss);

static void turn_wall_clock(time_t *secs, unsigned *msec) {
#if defined(_MSC_VER)
  /* 100ns ticks since 1601-01-01; 11644473600s from there to the Unix epoch. */
  FILETIME ft;
  ULARGE_INTEGER ticks;
  GetSystemTimeAsFileTime(&ft);
  ticks.LowPart = ft.dwLowDateTime;
  ticks.HighPart = ft.dwHighDateTime;
  const uint64_t since_epoch = ticks.QuadPart - 116444736000000000ULL;
  *secs = (time_t)(since_epoch / 10000000ULL);
  *msec = (unsigned)((since_epoch / 10000ULL) % 1000ULL);
#elif defined(CLOCK_REALTIME)
  struct timespec tp = {0, 0};
  clock_gettime(CLOCK_REALTIME, &tp);
  *secs = tp.tv_sec;
  *msec = (unsigned)(tp.tv_nsec / 1000000);
#else
  *secs = time(NULL);
  *msec = 0;
#endif
}

static const char *turn_find_msec_spec(const char *format) {
  for (const char *p = format; *p; ++p) {
    if (*p != '%') {
      continue;
    }
    if (p[1] == '%') {
      ++p;
      continue;
    }
    if (p[1] == 'f') {
      return p;
    }
  }
  return NULL;
}

static void turn_write_msec(char *p, unsigned msec) {
  p[0] = (char)('0' + (msec / 100) % 10);
  p[1] = (char)('0' + (msec / 10) % 10);
  p[2] = (char)('0' + msec % 10);
}

static size_t turn_render_timestamp_format(char *buf, size_t bufsz, const struct tm *tm_now, unsigned msec,
                                           size_t *msec_off) {
  *msec_off = TURN_LOG_NO_MSEC;

  const char *spec = turn_find_msec_spec(turn_log_timestamp_format);
  if (!spec) {
    return strftime(buf, bufsz, turn_log_timestamp_format, tm_now);
  }

  size_t len = 0;
  const size_t head_len = (size_t)(spec - turn_log_timestamp_format);
  if (head_len) {
    char head[MAX_LOG_TIMESTAMP_FORMAT_LEN] = {0};
    memcpy(head, turn_log_timestamp_format, head_len);
    len = strftime(buf, bufsz, head, tm_now);
    if (len == 0) {
      return 0;
    }
  }

  if (len + TURN_LOG_MSEC_DIGITS >= bufsz) {
    return 0;
  }
  turn_write_msec(buf + len, msec);
  *msec_off = len;
  len += TURN_LOG_MSEC_DIGITS;

  const char *tail = spec + 2;
  if (*tail) {
    const size_t tail_len = strftime(buf + len, bufsz - len, tail, tm_now);
    if (tail_len == 0) {
      return 0;
    }
    len += tail_len;
  }
  return len;
}

static size_t turn_log_render_timestamp(char *out, size_t outsz) {
  static TURN_THREAD_LOCAL struct {
    bool valid;
    bool iso_format;
    uint32_t generation;
    turn_time_t key;
    size_t len;
    size_t msec_off;
    char text[TURN_LOG_TIMESTAMP_CACHE_SIZE];
  } cache;

  const bool iso_format = (use_new_log_timestamp_format != 0);
  const uint32_t generation = turn_atomic_load_u32(&log_timestamp_format_generation);

  time_t now = 0;
  unsigned msec = 0;
  if (iso_format) {
    turn_wall_clock(&now, &msec);
  }
  const turn_time_t key = iso_format ? (turn_time_t)now : log_time();

  if (!cache.valid || cache.key != key || cache.iso_format != iso_format || cache.generation != generation) {
    size_t len = 0;
    size_t msec_off = TURN_LOG_NO_MSEC;
    if (iso_format) {
      struct tm tm_now = {0};
      if (turn_localtime(&now, &tm_now)) {
        len = turn_render_timestamp_format(cache.text, sizeof(cache.text), &tm_now, msec, &msec_off);
        if (len == 0) {
          /* Rendering does not fit the cache; fall back to the caller's buffer. */
          size_t direct_off = TURN_LOG_NO_MSEC;
          return turn_render_timestamp_format(out, outsz, &tm_now, msec, &direct_off);
        }
      }
    } else {
      const int written = snprintf(cache.text, sizeof(cache.text), "%lu", (unsigned long)key);
      if (written > 0 && (size_t)written < sizeof(cache.text)) {
        len = (size_t)written;
      }
    }
    cache.len = len;
    cache.msec_off = msec_off;
    cache.key = key;
    cache.iso_format = iso_format;
    cache.generation = generation;
    cache.valid = true;
  }

  const size_t len = min(cache.len, outsz);
  memcpy(out, cache.text, len);
  if (cache.msec_off != TURN_LOG_NO_MSEC && cache.msec_off + TURN_LOG_MSEC_DIGITS <= len) {
    turn_write_msec(out + cache.msec_off, msec);
  }
  return len;
}

static TURN_THREAD_LOCAL struct {
    bool valid;
    bool iso_format;
    uint32_t generation;
    turn_time_t key;
    size_t len;
    size_t msec_off;
    char text[TURN_LOG_TIMESTAMP_CACHE_SIZE];
  }

static struct tm *turn_localtime(const time_t *timep, struct tm *result) {
#if defined(WINDOWS)
  return (localtime_s(result, timep) == 0) ? result : NULL;
#else
  return localtime_r(timep, result);
#endif
}

static bool udp_get_string_attr(const uint8_t *data, size_t len, uint16_t attr_type, char *out, size_t out_size) {
  stun_attr_ref sar = stun_attr_get_first_by_type_str(data, len, attr_type);
  if (!sar) {
    return false;
  }
  const size_t alen = min((size_t)stun_attr_get_len(sar), out_size - 1);
  memcpy(out, stun_attr_get_value(sar), alen);
  out[alen] = 0;
  return true;
}

static bool udp_unauthenticated_reply_ratelimited(dtls_listener_relay_server_type *server, const ioa_addr *src,
                                                  int err_code) {
  turn_turnserver *ts = server->ts;

  if (!ts->ratelimit_unauthorized_requests || !*(ts->ratelimit_unauthorized_requests)) {
    return false;
  }

  bool first_drop = false;
  bool first_collision = false;
  const bool over = ratelimit_consume_address(src, (uint32_t) * (ts->ratelimit_unauthorized_requests_per_sec),
                                              &first_drop, &first_collision);

  if (first_collision) {
    char raddr[INET6_ADDRSTRLEN + 1] = {0};
    addr_to_string_no_port(src, raddr);
    TURN_LOG_FUNC(TURN_LOG_LEVEL_INFO,
                  "401 rate-limit bucket collision from %s, sharing active bucket budget for this window\n", raddr);
  }
  if (over && first_drop) {
    char raddr[INET6_ADDRSTRLEN + 1] = {0};
    addr_to_string_no_port(src, raddr);
    TURN_LOG_FUNC(TURN_LOG_LEVEL_INFO,
                  "unauthorized-response rate-limit exceeded from %s (error %d), suppressing responses for this "
                  "window\n",
                  raddr, err_code);
  }

  return over;
}

static void udp_send_stateless_error(dtls_listener_relay_server_type *server, ioa_net_data *nd, uint16_t method,
                                     stun_tid *tid, int err_code, const uint8_t *reason, const char *nonce,
                                     const char *realm, bool enforce_fingerprints) {
  turn_turnserver *ts = server->ts;

  ioa_network_buffer_handle nbh = ioa_network_buffer_allocate(server->e);
  size_t rlen = ioa_network_buffer_get_size(nbh);
  stun_init_error_response_str(method, ioa_network_buffer_data(nbh), &rlen, err_code, reason, tid,
                               ts->include_reason_string);
  if (nonce) {
    stun_attr_add_str(ioa_network_buffer_data(nbh), &rlen, STUN_ATTRIBUTE_NONCE, (const uint8_t *)nonce,
                      (int)strlen(nonce));
    stun_attr_add_str(ioa_network_buffer_data(nbh), &rlen, STUN_ATTRIBUTE_REALM, (const uint8_t *)realm,
                      (int)strlen(realm));
    if (ts->oauth) {
      const char *server_name = ts->oauth_server_name;
      if (!(server_name && server_name[0])) {
        server_name = realm;
      }
      stun_attr_add_str(ioa_network_buffer_data(nbh), &rlen, STUN_ATTRIBUTE_THIRD_PARTY_AUTHORIZATION,
                        (const uint8_t *)server_name, strlen(server_name));
    }
  }
  if (ts->software_attribute) {
    const char *software = get_version(ts);
    stun_attr_add_str(ioa_network_buffer_data(nbh), &rlen, STUN_ATTRIBUTE_SOFTWARE, (const uint8_t *)software,
                      strlen(software));
  }
  if (ts->fingerprint || enforce_fingerprints) {
    if (!stun_attr_add_fingerprint_str(ioa_network_buffer_data(nbh), &rlen)) {
      ioa_network_buffer_delete(server->e, nbh);
      return;
    }
  }
  ioa_network_buffer_set_size(nbh, rlen);

  udp_send_message(server, nbh, &(nd->src_addr));
  ioa_network_buffer_delete(server->e, nbh);
}

static bool udp_stateless_binding_fast_path(dtls_listener_relay_server_type *server, ioa_socket_handle listen_s,
                                            ioa_net_data *nd) {
  turn_turnserver *ts = server->ts;

  if (!ts || turn_params.no_udp || !server->udp_listen_s || !listen_s) {
    return false;
  }

  const uint8_t *data = ioa_network_buffer_data(nd->nbh);
  const size_t len = ioa_network_buffer_get_size(nd->nbh);

  bool enforce_fingerprints = false;
  if (!stun_is_command_message_full_check_str(data, len, false, &enforce_fingerprints) ||
      !stun_is_request_str(data, len) || (stun_get_method_str(data, len) != STUN_METHOD_BINDING)) {
    return false;
  }

  /* --secure-stun makes BINDING an authenticated method, which is
   * check_stun_auth's business, not the listener's. */
  if (*(ts->secure_stun)) {
    return false;
  }

  if (*(ts->no_stun)) {
    /* handle_turn_command ignores the request without a reply. Do the same,
     * minus the session it would have left behind. */
    return true;
  }

  /* --log-binding is a debugging aid whose per-session lines only the relay can
   * produce, so leave the old path in place while it is on. */
  if (server->e->verbose && ts->log_binding && *(ts->log_binding)) {
    return false;
  }

  /* The attribute walk mirrors handle_turn_binding's, including which
   * attributes are silently accepted and which count as unknown. */
  uint16_t unknown_attrs[MAX_NUMBER_OF_UNKNOWN_ATTRS] = {0};
  uint16_t ua_num = 0;

  stun_attr_ref sar = stun_attr_get_first_str(data, len);
  while (sar && (ua_num < MAX_NUMBER_OF_UNKNOWN_ATTRS)) {
    const int attr_type = stun_attr_get_type(sar);
    switch (attr_type) {
    case STUN_ATTRIBUTE_CHANGE_REQUEST:
    case STUN_ATTRIBUTE_PADDING:
    case STUN_ATTRIBUTE_RESPONSE_PORT:
      /* RFC 5780 probes are answered from an alternate address or port, which
       * only the relay's alternate sockets can do. */
      return false;
    case OLD_STUN_ATTRIBUTE_RESPONSE_ADDRESS:
    case STUN_ATTRIBUTE_OAUTH_ACCESS_TOKEN:
    case STUN_ATTRIBUTE_PRIORITY:
    case STUN_ATTRIBUTE_FINGERPRINT:
    case STUN_ATTRIBUTE_MESSAGE_INTEGRITY:
    case STUN_ATTRIBUTE_USERNAME:
    case STUN_ATTRIBUTE_REALM:
    case STUN_ATTRIBUTE_NONCE:
    case STUN_ATTRIBUTE_ORIGIN:
      break;
    default:
      if (attr_type >= 0x0000 && attr_type <= 0x7FFF) {
        unknown_attrs[ua_num++] = nswap16(attr_type);
      }
    };
    sar = stun_attr_get_next_covered_str(data, len, sar);
  }

  stun_report_binding(NULL, STUN_PROMETHEUS_METRIC_TYPE_REQUEST);

  stun_tid tid;
  stun_tid_from_message_str(data, len, &tid);

  ioa_network_buffer_handle nbh = ioa_network_buffer_allocate(server->e);
  size_t rlen = ioa_network_buffer_get_size(nbh);

  if (ua_num > 0) {
    stun_init_error_response_str(STUN_METHOD_BINDING, ioa_network_buffer_data(nbh), &rlen, 420, NULL, &tid,
                                 ts->include_reason_string);
    stun_attr_add_str(ioa_network_buffer_data(nbh), &rlen, STUN_ATTRIBUTE_UNKNOWN_ATTRIBUTES,
                      (const uint8_t *)unknown_attrs, (ua_num * 2));
  } else {
    if (!stun_set_binding_response_str(ioa_network_buffer_data(nbh), &rlen, &tid, &(nd->src_addr), 0, NULL, 0, false,
                                       *(ts->stun_backward_compatibility), ts->include_reason_string)) {
      ioa_network_buffer_delete(server->e, nbh);
      return false;
    }
    /* An RFC 5780 server advertises its alternate address on every Binding
     * response, not only on the CHANGE-REQUEST probes. */
    if (ts->rfc5780 && ts->alt_addr_cb) {
      ioa_addr *response_origin = get_local_addr_from_ioa_socket(listen_s);
      ioa_addr other_address = {0};
      if (response_origin && (ts->alt_addr_cb(response_origin, &other_address) == 0)) {
        stun_attr_add_addr_str(ioa_network_buffer_data(nbh), &rlen, STUN_ATTRIBUTE_RESPONSE_ORIGIN, response_origin);
        stun_attr_add_addr_str(ioa_network_buffer_data(nbh), &rlen, STUN_ATTRIBUTE_OTHER_ADDRESS, &other_address);
      }
    }
  }

  if (ts->software_attribute) {
    const char *software = get_version(ts);
    stun_attr_add_str(ioa_network_buffer_data(nbh), &rlen, STUN_ATTRIBUTE_SOFTWARE, (const uint8_t *)software,
                      strlen(software));
  }
  if (ts->fingerprint || enforce_fingerprints) {
    if (!stun_attr_add_fingerprint_str(ioa_network_buffer_data(nbh), &rlen)) {
      ioa_network_buffer_delete(server->e, nbh);
      return true;
    }
  }
  ioa_network_buffer_set_size(nbh, rlen);

  stun_report_binding(NULL, ua_num ? STUN_PROMETHEUS_METRIC_TYPE_ERROR : STUN_PROMETHEUS_METRIC_TYPE_RESPONSE);

  udp_send_message(server, nbh, &(nd->src_addr));
  ioa_network_buffer_delete(server->e, nbh);

  return true;
}

static void test_evenport_r0_does_not_reserve_sibling(void) {
  turnports *t = turnports_create(NULL, TEST_PORT_START, TEST_PORT_END);
  TEST_ASSERT_NOT_NULL(t);

  const int port = turnports_allocate_even(t, 0 /* R=0: no rtcp reservation */, NULL);
  TEST_ASSERT_TRUE(port >= TEST_PORT_START && port <= TEST_PORT_END);
  TEST_ASSERT_EQUAL_INT(0, port & 1);
  TEST_ASSERT_TRUE(turnports_is_allocated(t, (uint16_t)port));
  /* The odd sibling must stay available. */
  TEST_ASSERT_TRUE(turnports_is_available(t, (uint16_t)(port + 1)));

  turnports_release(t, (uint16_t)port);
  TEST_ASSERT_EQUAL_UINT16(TEST_NPORTS, turnports_size(t));

  free(t);
}

static void test_evenport_r0_alloc_release_does_not_leak(void) {
  turnports *t = turnports_create(NULL, TEST_PORT_START, TEST_PORT_END);
  TEST_ASSERT_NOT_NULL(t);

  for (int i = 0; i < 100; ++i) {
    const int port = turnports_allocate_even(t, 0, NULL);
    char msg[96] = {0};
    snprintf(msg, sizeof(msg), "EVEN-PORT(R=0) allocation failed at cycle %d (pool leaked)", i);
    TEST_ASSERT_TRUE_MESSAGE(port >= TEST_PORT_START && port <= TEST_PORT_END, msg);
    TEST_ASSERT_EQUAL_INT(0, port & 1);
    turnports_release(t, (uint16_t)port);
    TEST_ASSERT_EQUAL_UINT16(TEST_NPORTS, turnports_size(t));
  }

  free(t);
}

static void test_evenport_r1_reserves_sibling(void) {
  turnports *t = turnports_create(NULL, TEST_PORT_START, TEST_PORT_END);
  TEST_ASSERT_NOT_NULL(t);

  uint64_t token = 0;
  const int port = turnports_allocate_even(t, 1 /* R=1: reserve rtcp */, &token);
  TEST_ASSERT_TRUE(port >= TEST_PORT_START && port <= TEST_PORT_END);
  TEST_ASSERT_EQUAL_INT(0, port & 1);
  TEST_ASSERT_TRUE(turnports_is_allocated(t, (uint16_t)port));
  /* Sibling is held, not free. */
  TEST_ASSERT_FALSE(turnports_is_available(t, (uint16_t)(port + 1)));

  free(t);
}

static void test_in_range_native_ipv6_non_prefix_aligned(void) {
  ioa_addr a = {0}, b = {0};
  make_addr("2001:db8::100", &a);
  make_addr("2001:db8::200", &b);
  ioa_addr_range denied = {0};
  ioa_addr_range_set(&denied, &a, &b);

  const char *inside[] = {
      "2001:db8::100",                  /* min endpoint          */
      "2001:db8::101", "2001:db8::1ff", /* the byte15 > 0 gap */
      "2001:db8::200",                  /* max endpoint          */
  };
  for (size_t i = 0; i < sizeof(inside) / sizeof(inside[0]); ++i) {
    ioa_addr peer = {0};
    make_addr(inside[i], &peer);
    TEST_ASSERT_TRUE_MESSAGE(ioa_addr_in_range(&denied, &peer), inside[i]);
  }

  const char *outside[] = {"2001:db8::ff", "2001:db8::201", "2001:db9::1"};
  for (size_t i = 0; i < sizeof(outside) / sizeof(outside[0]); ++i) {
    ioa_addr peer = {0};
    make_addr(outside[i], &peer);
    TEST_ASSERT_FALSE_MESSAGE(ioa_addr_in_range(&denied, &peer), outside[i]);
  }
}

static void test_in_range_native_ipv6_wide_span(void) {
  ioa_addr a = {0}, b = {0};
  make_addr("2001:db8::", &a);
  make_addr("2001:db9::", &b);
  ioa_addr_range denied = {0};
  ioa_addr_range_set(&denied, &a, &b);

  const char *inside[] = {
      "2001:db8::",           /* min endpoint                       */
      "2001:db8::1",          /* PoC Case 2                          */
      "2001:db8:0:0:0:0:0:1", /* PoC Case 2, fully-expanded form     */
      "2001:db8::53",         /* exploit scenario internal DNS/DB host */
      "2001:db9::",           /* max endpoint                       */
  };
  for (size_t i = 0; i < sizeof(inside) / sizeof(inside[0]); ++i) {
    ioa_addr peer = {0};
    make_addr(inside[i], &peer);
    TEST_ASSERT_TRUE_MESSAGE(ioa_addr_in_range(&denied, &peer), inside[i]);
  }

  const char *outside[] = {"2001:db7:ffff::1", "2001:db9::1"};
  for (size_t i = 0; i < sizeof(outside) / sizeof(outside[0]); ++i) {
    ioa_addr peer = {0};
    make_addr(outside[i], &peer);
    TEST_ASSERT_FALSE_MESSAGE(ioa_addr_in_range(&denied, &peer), outside[i]);
  }
}

static void msg_finish(void) {
  test_nbh.len = msg_len;
/* Builds a Send indication carrying peer_count XOR-PEER-ADDRESS attributes
 * followed by a DATA attribute, and loads it into the fixture buffer. */
static void make_send_indication(const ioa_addr *peers, size_t peer_count, const uint8_t *payload, size_t payload_len) {
  msg_begin(STUN_METHOD_SEND, true);
  for (size_t i = 0; i < peer_count; ++i) {
    msg_add_peer(&(peers[i]));
  }
  msg_add_data(payload, payload_len);
  msg_finish();
}

  in_buffer.recv_ttl = recv_ttl;
  last_ua_num = ua_num;
  return err_code;
}

static void make_send_indication(const ioa_addr *peers, size_t peer_count, const uint8_t *payload, size_t payload_len) {
  msg_begin(STUN_METHOD_SEND, true);
  for (size_t i = 0; i < peer_count; ++i) {
    msg_add_peer(&(peers[i]));
  }
  msg_add_data(payload, payload_len);
  msg_finish();
}

static bool has_permission(const char *ip, uint16_t port) {
  ioa_addr addr;
  make_addr(&addr, ip, port);
  return allocation_get_permission(&(ss.alloc), &addr) != NULL;
}

static void test_send_relays_zero_length_data(void) {
  ioa_addr peer;
  make_addr(&peer, PEER_A, PEER_PORT_A);
  add_permission(PEER_A, PEER_PORT_A);

  msg_begin(STUN_METHOD_SEND, true);
  msg_add_peer(&peer);
  msg_add_data(NULL, 0);
  msg_finish();

  TEST_ASSERT_EQUAL_INT(0, run_send());
  TEST_ASSERT_EQUAL_INT(1, sent_capture.calls);
  TEST_ASSERT_TRUE(addr_eq(&peer, &(sent_capture.dest)));
  TEST_ASSERT_EQUAL_size_t(0, sent_capture.len);
}

