  msg_begin(STUN_METHOD_CREATE_PERMISSION, false);
  msg_add_peer(&peer);
  msg_finish();

  TEST_ASSERT_EQUAL_INT(0, run_create_permission(NULL));
  TEST_ASSERT_TRUE(has_permission(PEER_A, (uint16_t)(PEER_PORT_A + 1234)));
}

