}

stun_attr_ref stun_attr_get_next_covered_str(const uint8_t *buf, size_t len, stun_attr_ref prev) {
  /* Everything past MESSAGE-INTEGRITY falls outside the HMAC, so stop here. */
  if (prev && stun_attr_get_type(prev) == STUN_ATTRIBUTE_MESSAGE_INTEGRITY) {
    return NULL;
  }
  return stun_attr_get_next_str(buf, len, prev);
}

static void build_authenticated_allocate(uint8_t *buf, size_t *len) {
  hmackey_t key;
  test_integrity_key(key);

  *len = 0;
  stun_init_request_str(STUN_METHOD_ALLOCATE, buf, len);
  TEST_ASSERT_TRUE(stun_attr_add_str(buf, len, STUN_ATTRIBUTE_REQUESTED_TRANSPORT, TEST_TRANSPORT_UDP, 4));
  TEST_ASSERT_TRUE(stun_attr_add_str(buf, len, STUN_ATTRIBUTE_LIFETIME, TEST_LIFETIME_600, 4));
  TEST_ASSERT_TRUE(
      stun_attr_add_integrity_by_key_str(buf, len, TEST_UNAME, TEST_REALM, key, TEST_NONCE, SHATYPE_DEFAULT));
}

static int count_attrs_of_type(const uint8_t *buf, size_t len, uint16_t type, bool covered_only) {
  int n = 0;
  stun_attr_ref sar = stun_attr_get_first_str(buf, len);
  while (sar) {
    if (stun_attr_get_type(sar) == (int)type) {
      ++n;
    }
    sar = covered_only ? stun_attr_get_next_covered_str(buf, len, sar) : stun_attr_get_next_str(buf, len, sar);
  }
  return n;
}

static void test_trailing_attr_survives_integrity_check(void) {
  uint8_t buf[1024] = {0};
  size_t len = 0;
  hmackey_t key;

  build_authenticated_allocate(buf, &len);
  test_integrity_key(key);

  /* Appending an attribute rewrites the header length; no key is needed,
     because the HMAC does not reach past MESSAGE-INTEGRITY. */
  TEST_ASSERT_TRUE(stun_attr_add_str(buf, &len, STUN_ATTRIBUTE_LIFETIME, TEST_LIFETIME_1, 4));

  /* The tampered message still authenticates. This is the whole reason the
     parse loops must stop at MESSAGE-INTEGRITY on their own. */
  TEST_ASSERT_EQUAL_INT(
      1, stun_check_message_integrity_by_key_str(TURN_CREDENTIALS_LONG_TERM, buf, len, key, NULL, SHATYPE_DEFAULT));
}

static void test_covered_walk_ignores_attr_after_message_integrity(void) {
  uint8_t buf[1024] = {0};
  size_t len = 0;

  build_authenticated_allocate(buf, &len);
  TEST_ASSERT_EQUAL_INT(1, count_attrs_of_type(buf, len, STUN_ATTRIBUTE_LIFETIME, true));

  TEST_ASSERT_TRUE(stun_attr_add_str(buf, &len, STUN_ATTRIBUTE_LIFETIME, TEST_LIFETIME_1, 4));

  /* An unbounded walk hands the attacker's LIFETIME to the handler, which
     assigns unconditionally, so the trailing value wins. */
  TEST_ASSERT_EQUAL_INT(2, count_attrs_of_type(buf, len, STUN_ATTRIBUTE_LIFETIME, false));
  /* A covered walk never sees it. */
  TEST_ASSERT_EQUAL_INT(1, count_attrs_of_type(buf, len, STUN_ATTRIBUTE_LIFETIME, true));
}

static void test_covered_walk_yields_message_integrity_itself(void) {
  uint8_t buf[1024] = {0};
  size_t len = 0;

  build_authenticated_allocate(buf, &len);

  /* The boundary is inclusive: callers still dispatch on MESSAGE-INTEGRITY
     (SKIP_ATTRIBUTES relies on seeing it) and stop only afterwards. */
  TEST_ASSERT_EQUAL_INT(1, count_attrs_of_type(buf, len, STUN_ATTRIBUTE_MESSAGE_INTEGRITY, true));
}

static void test_covered_walk_is_full_walk_without_message_integrity(void) {
  uint8_t buf[1024] = {0};
  size_t len = 0;

  /* Nothing is protected, so there is no boundary to honour. */
  stun_init_request_str(STUN_METHOD_ALLOCATE, buf, &len);
  TEST_ASSERT_TRUE(stun_attr_add_str(buf, &len, STUN_ATTRIBUTE_REQUESTED_TRANSPORT, TEST_TRANSPORT_UDP, 4));
  TEST_ASSERT_TRUE(stun_attr_add_str(buf, &len, STUN_ATTRIBUTE_LIFETIME, TEST_LIFETIME_600, 4));
  TEST_ASSERT_TRUE(stun_attr_add_str(buf, &len, STUN_ATTRIBUTE_LIFETIME, TEST_LIFETIME_1, 4));

  TEST_ASSERT_EQUAL_INT(2, count_attrs_of_type(buf, len, STUN_ATTRIBUTE_LIFETIME, true));
  TEST_ASSERT_EQUAL_INT(1, count_attrs_of_type(buf, len, STUN_ATTRIBUTE_REQUESTED_TRANSPORT, true));
}

static void test_covered_walk_hides_message_integrity_sha256_from_420(void) {
  uint8_t buf[1024] = {0};
  size_t len = 0;
  uint8_t sha256_hmac[32] = {0};

  build_authenticated_allocate(buf, &len);

  /* An RFC 8489 client sends MESSAGE-INTEGRITY-SHA256 after MESSAGE-INTEGRITY.
     0x001C is comprehension-required, so an unbounded walk collects it as an
     unknown attribute and the server answers 420 -- rejecting a conformant
     client. The covered walk never reaches it, which is what the RFC requires
     and what keeps such clients working. */
  TEST_ASSERT_TRUE(stun_attr_add_str(buf, &len, TEST_ATTR_MESSAGE_INTEGRITY_SHA256, sha256_hmac, 32));

  TEST_ASSERT_EQUAL_INT(1, count_attrs_of_type(buf, len, TEST_ATTR_MESSAGE_INTEGRITY_SHA256, false));
  TEST_ASSERT_EQUAL_INT(0, count_attrs_of_type(buf, len, TEST_ATTR_MESSAGE_INTEGRITY_SHA256, true));
}

static void test_message_build_and_parse_survive_misaligned_buffer(void) {
  /* The message builders and header parsers (stun_init_command_str,
   * stun_attr_add_str, stun_attr_add_fingerprint_str, stun_get_method_str,
   * stun_is_command_message_str, stun_get_message_len_str, ...) used to
   * access the wire buffer through casts to wider integer pointers — the
   * store-side twin of the attribute-accessor reads already pinned by the
   * misaligned tests above. Build and re-parse a complete message on a buffer
   * one byte off an aligned base and confirm every step still works.
   */
  uint8_t raw[2 + 1024] = {0};
  uint8_t *buf = misalign(raw);
  size_t len = 0;

  stun_init_request_str(STUN_METHOD_BINDING, buf, &len);
  TEST_ASSERT_EQUAL_size_t(STUN_HEADER_LENGTH, len);

  const uint16_t rport = 12345;
  TEST_ASSERT_TRUE(stun_attr_add_response_port_str(buf, &len, rport));
  TEST_ASSERT_TRUE(stun_attr_add_fingerprint_str(buf, &len));

  TEST_ASSERT_TRUE(stun_is_command_message_str(buf, len));
  TEST_ASSERT_TRUE(stun_is_request_str(buf, len));
  TEST_ASSERT_EQUAL_UINT16(STUN_METHOD_BINDING, stun_get_method_str(buf, len));
  TEST_ASSERT_EQUAL_UINT16(stun_make_request(STUN_METHOD_BINDING), stun_get_msg_type_str(buf, len));
  TEST_ASSERT_EQUAL_INT((int)len, stun_get_command_message_len_str(buf, len));
  TEST_ASSERT_FALSE(is_channel_msg_str(buf, len));

  int fingerprint_present = 0;
  TEST_ASSERT_TRUE(stun_is_command_message_full_check_str(buf, len, 1, &fingerprint_present));
  TEST_ASSERT_TRUE(fingerprint_present);

  stun_attr_ref sar = stun_attr_get_first_by_type_str(buf, len, STUN_ATTRIBUTE_RESPONSE_PORT);
  TEST_ASSERT_NOT_NULL(sar);
  TEST_ASSERT_EQUAL_INT((int)rport, stun_attr_get_response_port_str(sar));

  size_t app_len = 0;
  TEST_ASSERT_EQUAL_INT((int)len, stun_get_message_len_str(buf, len, 0, &app_len));
  TEST_ASSERT_EQUAL_size_t(len, app_len);

  /* Old (RFC 3489) header path: cookie is read and reported through the same
   * previously-misaligned loads. */
  {
    uint8_t raw_old[2 + 64] = {0};
    uint8_t *obuf = misalign(raw_old);
    size_t olen = 0;
    const uint32_t old_cookie = 0x12345678;
    old_stun_init_command_str(stun_make_request(STUN_METHOD_BINDING), obuf, &olen, old_cookie);
    uint32_t parsed_cookie = 0;
    TEST_ASSERT_TRUE(old_stun_is_command_message_str(obuf, olen, &parsed_cookie));
    TEST_ASSERT_EQUAL_UINT32(old_cookie, parsed_cookie);
  }
}

atic void test_channel_message_survives_misaligned_buffer(void) {
  /* Channel-data framing (stun_init_channel_message_str,
   * stun_is_channel_message_str, is_channel_msg_str, and the channel branch of
   * stun_get_message_len_str) reads and writes the channel number and data
   * length through what used to be direct wide-pointer access. Exercise the
   * whole round trip on a misaligned buffer.
   */
  uint8_t raw[2 + 1024] = {0};
  uint8_t *buf = misalign(raw);
  size_t len = 0;
  const uint16_t channel = 0x4001;
  const int payload_len = 200;

  TEST_ASSERT_TRUE(stun_init_channel_message_str(channel, buf, &len, payload_len, false));
  TEST_ASSERT_EQUAL_size_t((size_t)(4 + payload_len), len);

  TEST_ASSERT_TRUE(is_channel_msg_str(buf, len));
  TEST_ASSERT_FALSE(stun_is_command_message_str(buf, len));

  uint16_t parsed_channel = 0;
  size_t blen = len;
  TEST_ASSERT_TRUE(stun_is_channel_message_str(buf, &blen, &parsed_channel, false));
  TEST_ASSERT_EQUAL_UINT16(channel, parsed_channel);

  size_t app_len = 0;
  TEST_ASSERT_EQUAL_INT((int)len, stun_get_message_len_str(buf, len, 0, &app_len));
  TEST_ASSERT_EQUAL_size_t(len, app_len);
}

atic void test_addr_attrs_survive_misaligned_buffer(void) {
  /* stun_addr_encode/stun_addr_decode wrote and read the port and IPv4
   * address fields through casts to wider integer pointers into the attribute
   * body. Round-trip XOR-mapped (port and address are XORed with the magic
   * cookie / transaction id) and plain address attributes, IPv4 and IPv6, on
   * a message that sits one byte off an aligned base.
   */
  uint8_t raw[2 + 1024] = {0};
  uint8_t *buf = misalign(raw);
  size_t len = 0;
  stun_tid tid = {0};
  stun_init_success_response_str(STUN_METHOD_BINDING, buf, &len, &tid);

  ioa_addr peer4 = {0};
  ioa_addr peer6 = {0};
  ioa_addr origin4 = {0};
  TEST_ASSERT_EQUAL_INT(0, make_ioa_addr((const uint8_t *)"203.0.113.5", 43210, &peer4));
  TEST_ASSERT_EQUAL_INT(0, make_ioa_addr((const uint8_t *)"2001:db8::1", 43211, &peer6));
  TEST_ASSERT_EQUAL_INT(0, make_ioa_addr((const uint8_t *)"192.0.2.10", 3478, &origin4));

  TEST_ASSERT_TRUE(stun_attr_add_addr_str(buf, &len, STUN_ATTRIBUTE_XOR_MAPPED_ADDRESS, &peer4));
  TEST_ASSERT_TRUE(stun_attr_add_addr_str(buf, &len, STUN_ATTRIBUTE_XOR_PEER_ADDRESS, &peer6));
  TEST_ASSERT_TRUE(stun_attr_add_addr_str(buf, &len, STUN_ATTRIBUTE_RESPONSE_ORIGIN, &origin4));

  ioa_addr got4 = {0};
  ioa_addr got6 = {0};
  ioa_addr got_origin = {0};
  TEST_ASSERT_TRUE(stun_attr_get_first_addr_str(buf, len, STUN_ATTRIBUTE_XOR_MAPPED_ADDRESS, &got4, NULL));
  TEST_ASSERT_TRUE(stun_attr_get_first_addr_str(buf, len, STUN_ATTRIBUTE_XOR_PEER_ADDRESS, &got6, NULL));
  TEST_ASSERT_TRUE(stun_attr_get_first_addr_str(buf, len, STUN_ATTRIBUTE_RESPONSE_ORIGIN, &got_origin, NULL));

  TEST_ASSERT_TRUE(addr_eq(&peer4, &got4));
  TEST_ASSERT_TRUE(addr_eq(&peer6, &got6));
  TEST_ASSERT_TRUE(addr_eq(&origin4, &got_origin));
}

void shutdown_server(void) {
  run_auth_server_flag = 0; /* turn_params.stop_turn_server is already true */

  /* Wake every dispatching event loop immediately instead of waiting for
   * its 5-second loopexit tick. Safe cross-thread because
   * evthread_use_pthreads() was called in setup_server. */
  if (turn_params.general_relay_servers_number > 0) {
    for (size_t i = 0; i < get_real_general_relay_servers_number(); i++) {
      if (general_relay_servers[i] && general_relay_servers[i]->event_base) {
        event_base_loopbreak(general_relay_servers[i]->event_base);
      }
    }
  }
  /* Auth server 0 is the housekeeping thread: it has no event base and
   * exits via run_auth_server_flag within its 1-second sleep slice. */
  for (authserver_id sn = 1; sn < authserver_number; ++sn) {
    if (authserver[sn].event_base) {
      event_base_loopbreak(authserver[sn].event_base);
    }
  }
  if (adminserver.event_base) {
    event_base_loopbreak(adminserver.event_base);
  }

  /* Join all worker threads so none of them can be inside an OpenSSL
   * call when main returns and OPENSSL_cleanup runs from atexit
   * (https://github.com/coturn/coturn/issues/1633). When
   * general_relay_servers_number == 0 the relay servers run inline on
   * this thread (thr == pthread_self()), so joining would deadlock. */
  if (turn_params.general_relay_servers_number > 0) {
    for (size_t i = 0; i < get_real_general_relay_servers_number(); i++) {
      if (general_relay_servers[i]) {
        pthread_join(general_relay_servers[i]->thr, NULL);
      }
    }
  }
  for (authserver_id sn = 0; sn < authserver_number; ++sn) {
    pthread_join(authserver[sn].thr, NULL);
  }
  pthread_join(adminserver.thr, NULL);

  TURN_LOG_FUNC(TURN_LOG_LEVEL_INFO, "All worker threads joined\n");
}

static void turn_out_of_memory(const char *file, int line, const char *what, size_t sz) {
  turn_log_func_default(file, line, TURN_LOG_LEVEL_ERROR, "FATAL: out of memory: %s(%lu) failed, aborting\n", what,
                        (unsigned long)sz);
  abort();
}

void *turn_malloc_impl(size_t sz, const char *file, int line) {
  void *ptr = malloc(sz);
  if (!ptr && sz) {
    turn_out_of_memory(file, line, "malloc", sz);
  }
  return ptr;
}

void *turn_calloc_impl(size_t number, size_t size, const char *file, int line) {
  void *ptr = calloc(number, size);
  if (!ptr && number && size) {
    turn_out_of_memory(file, line, "calloc", number * size);
  }
  return ptr;
}

void *turn_realloc_impl(void *ptr, size_t sz, const char *file, int line) {
  void *newptr = realloc(ptr, sz);
  if (!newptr && sz) {
    turn_out_of_memory(file, line, "realloc", sz);
  }
  return newptr;
}

char *turn_strdup_impl(const char *s, const char *file, int line) {
  if (!s) {
    return NULL;
  }
  char *ptr = strdup(s);
  if (!ptr) {
    turn_out_of_memory(file, line, "strdup", strlen(s) + 1);
  }
  return ptr;
}

static void test_decode_one_padding_char(void) {
  size_t out_len = 0;
  unsigned char *out = base64_decode("Zm8=", 4, &out_len); /* "fo" */

  TEST_ASSERT_NOT_NULL(out);
  TEST_ASSERT_EQUAL_size_t(2, out_len);
  TEST_ASSERT_EQUAL_MEMORY("fo", out, 2);
  free(out);
}

static void test_decode_two_padding_chars(void) {
  size_t out_len = 0;
  unsigned char *out = base64_decode("Zg==", 4, &out_len); /* "f" */

  TEST_ASSERT_NOT_NULL(out);
  TEST_ASSERT_EQUAL_size_t(1, out_len);
  TEST_ASSERT_EQUAL_MEMORY("f", out, 1);
  free(out);
}

static SSL *tls_connect(ioa_socket_raw fd, ioa_addr *remote_addr, const char *remote_host, bool *try_again,
                        int connect_cycle) {
  /* RFC 6066 section 3: SNI carries DNS hostnames only, never IP literals. */
  if (remote_host && remote_host[0]) {
    struct in_addr v4;
    struct in6_addr v6;
    if (inet_pton(AF_INET, remote_host, &v4) != 1 && inet_pton(AF_INET6, remote_host, &v6) != 1) {
      if (SSL_set_tlsext_host_name(ssl, remote_host) != 1) {
        TURN_LOG_FUNC(TURN_LOG_LEVEL_WARNING, "%s: cannot set SNI host name '%s'\n", __FUNCTION__, remote_host);
      }
    }
  }

    clnet_info->ssl = tls_connect(clnet_info->fd, &remote_addr, remote_address, &try_again, connect_cycle++);
        tls_connect(elem->pinfo.tcp_conn[i]->tcp_data_fd, &(elem->pinfo.remote_addr), elem->pinfo.rsaddr, &try_again,
                    connect_cycle++);

static void make_stun_header(uint8_t *buf, uint16_t body_len) {
  /* Type: top two bits clear, not a valid channel number. Use BINDING. */
  buf[0] = (uint8_t)(STUN_METHOD_BINDING >> 8);
  buf[1] = (uint8_t)(STUN_METHOD_BINDING & 0xFF);
  /* Body length (network byte order). */
  buf[2] = (uint8_t)(body_len >> 8);
  buf[3] = (uint8_t)(body_len & 0xFF);
  /* Magic cookie. */
  buf[4] = 0x21;
  buf[5] = 0x12;
  buf[6] = 0xA4;
  buf[7] = 0x42;
  /* Transaction id (bytes 8..19) left as-is by the caller. */
}

static void test_message_len_does_not_overflow_uint16(void) {
  /* Body lengths that are 4-byte aligned and within 16 of 0xFFFF: len + 20
   * wraps a uint16_t to 4/8/12/16. With only a header-sized buffer present,
   * the truncated value would falsely pass the `<= blen` bounds check and the
   * function would claim a tiny message, orphaning the rest of the TCP stream.
   * The fix computes the length in uint32_t, so each of these must instead be
   * reported as "incomplete" (return -1) given a short buffer. */
  const uint16_t overflow_body_lens[] = {65520, 65524, 65528, 65532};

  for (size_t i = 0; i < sizeof(overflow_body_lens) / sizeof(overflow_body_lens[0]); ++i) {
    uint8_t buf[STUN_HEADER_LENGTH] = {0};
    make_stun_header(buf, overflow_body_lens[i]);

    size_t app_len = 12345; /* sentinel; must not be written on the short path */
    const int mlen = stun_get_message_len_str(buf, sizeof(buf), 1, &app_len);

    /* Without the uint32_t widening this returned a small positive value
     * (4/8/12/16) that the TCP framing layer would act on
     * (mlen > 0 && mlen <= blen), consuming only a few bytes. With the fix the
     * real length (body + 20) exceeds blen, so the function reports
     * "incomplete" (-1) and the framing layer waits for more data instead of
     * desynchronizing. The key property is that it is never a small positive
     * value here. */
    TEST_ASSERT_EQUAL_INT(-1, mlen);
    TEST_ASSERT_FALSE(mlen > 0 && mlen <= (int)sizeof(buf));
    TEST_ASSERT_EQUAL_size_t(12345, app_len);
  }
}

static void test_message_len_accepts_full_well_formed_message(void) {
  /* A genuine, fully-present STUN message is still parsed correctly. */
  const uint16_t body_len = 8;
  uint8_t buf[STUN_HEADER_LENGTH + 8] = {0};
  make_stun_header(buf, body_len);

  size_t app_len = 0;
  const int mlen = stun_get_message_len_str(buf, sizeof(buf), 1, &app_len);

  TEST_ASSERT_EQUAL_INT((int)(STUN_HEADER_LENGTH + body_len), mlen);
  TEST_ASSERT_EQUAL_size_t((size_t)(STUN_HEADER_LENGTH + body_len), app_len);
}

static int turn_barrier_init(turn_barrier_t *b, unsigned int n) {
  if (n == 0) {
    errno = EINVAL;
    return -1;
  }
  if (pthread_mutex_init(&b->mtx, NULL) != 0) {
    return -1;
  }
  if (pthread_cond_init(&b->cond, NULL) != 0) {
    pthread_mutex_destroy(&b->mtx);
    return -1;
  }
  b->threshold = n;
  b->count = 0;
  b->generation = 0;
  return 0;
}

static int turn_barrier_wait(turn_barrier_t *b) {
  pthread_mutex_lock(&b->mtx);
  const unsigned int gen = b->generation;
  if (++b->count == b->threshold) {
    /* Last thread to arrive releases the rest and resets for reuse. */
    b->generation++;
    b->count = 0;
    pthread_cond_broadcast(&b->cond);
    pthread_mutex_unlock(&b->mtx);
    return PTHREAD_BARRIER_SERIAL_THREAD;
  }
  /* The generation guard absorbs spurious condvar wakeups. */
  while (gen == b->generation) {
    pthread_cond_wait(&b->cond, &b->mtx);
  }
  pthread_mutex_unlock(&b->mtx);
  return 0;
}

static char *prom_read_file(const char *path) {
  FILE *f = fopen(path, "rb");
  if (f == NULL) {
    return NULL;
  }
  char *buf = NULL;
  if (fseek(f, 0, SEEK_END) == 0) {
    long size = ftell(f);
    if (size >= 0 && fseek(f, 0, SEEK_SET) == 0) {
      buf = malloc((size_t)size + 1);
      if (buf != NULL) {
        if (fread(buf, 1, (size_t)size, f) != (size_t)size) {
          free(buf);
          buf = NULL;
        } else {
          buf[size] = '\0';
        }
      }
    }
  }
  fclose(f);
  return buf;
}

static char *prom_strdup(const char *s) {
  if (s == NULL) {
    return NULL;
  }
  size_t n = strlen(s) + 1;
  char *p = malloc(n);
  if (p != NULL) {
    memcpy(p, s, n);
  }
  return p;
}

static prom_metric_t *prom_metric_new(prom_metric_type_t type, const char *name, const char *help,
                                      size_t label_key_count, const char **label_keys) {
  if (name == NULL) {
    return NULL;
  }

  prom_metric_t *m = calloc(1, sizeof(*m));
  if (m == NULL) {
    return NULL;
  }

  m->type = type;
  m->name = prom_strdup(name);
  m->help = prom_strdup(help != NULL ? help : "");
  m->label_count = label_key_count;
  if (m->name == NULL || m->help == NULL) {
    goto fail;
  }

  if (label_key_count > 0) {
    m->label_keys = calloc(label_key_count, sizeof(char *));
    if (m->label_keys == NULL) {
      goto fail;
    }
    for (size_t i = 0; i < label_key_count; i++) {
      m->label_keys[i] = prom_strdup(label_keys != NULL ? label_keys[i] : "");
      if (m->label_keys[i] == NULL) {
        goto fail;
      }
    }
  }

  if (pthread_mutex_init(&m->mutex, NULL) != 0) {
    goto fail;
  }
  return m;

fail:
  if (m->label_keys != NULL) {
    for (size_t i = 0; i < label_key_count; i++) {
      free(m->label_keys[i]);
    }
    free(m->label_keys);
  }
  free(m->name);
  free(m->help);
  free(m);
  return NULL;
}

static void prom_metric_destroy(prom_metric_t *m) {
  if (m == NULL) {
    return;
  }
  prom_sample_t *s = m->samples;
  while (s != NULL) {
    prom_sample_t *next = s->next;
    if (s->label_values != NULL) {
      for (size_t i = 0; i < m->label_count; i++) {
        free(s->label_values[i]);
      }
      free(s->label_values);
    }
    free(s);
    s = next;
  }
  if (m->label_keys != NULL) {
    for (size_t i = 0; i < m->label_count; i++) {
      free(m->label_keys[i]);
    }
    free(m->label_keys);
  }
  pthread_mutex_destroy(&m->mutex);
  free(m->name);
  free(m->help);
  free(m);
}

static int label_values_equal(const prom_metric_t *m, char *const *a, const char *const *b) {
  for (size_t i = 0; i < m->label_count; i++) {
    const char *av = a[i] != NULL ? a[i] : "";
    const char *bv = (b != NULL && b[i] != NULL) ? b[i] : "";
    if (strcmp(av, bv) != 0) {
      return 0;
    }
  }
  return 1;
}

static prom_sample_t *prom_metric_find_or_create_sample(prom_metric_t *m, const char **label_values) {
  for (prom_sample_t *s = m->samples; s != NULL; s = s->next) {
    if (label_values_equal(m, s->label_values, label_values)) {
      return s;
    }
  }

  prom_sample_t *s = calloc(1, sizeof(*s));
  if (s == NULL) {
    return NULL;
  }
  if (m->label_count > 0) {
    s->label_values = calloc(m->label_count, sizeof(char *));
    if (s->label_values == NULL) {
      free(s);
      return NULL;
    }
    for (size_t i = 0; i < m->label_count; i++) {
      const char *v = (label_values != NULL && label_values[i] != NULL) ? label_values[i] : "";
      s->label_values[i] = prom_strdup(v);
      if (s->label_values[i] == NULL) {
        for (size_t j = 0; j < i; j++) {
          free(s->label_values[j]);
        }
        free(s->label_values);
        free(s);
        return NULL;
      }
    }
  }
  s->value = 0.0;
  s->next = m->samples;
  m->samples = s;
  return s;
}

static int prom_metric_add(prom_metric_t *self, prom_metric_type_t expected, double r_value,
                           const char **label_values) {
  if (self == NULL || self->type != expected) {
    return 1;
  }
  pthread_mutex_lock(&self->mutex);
  prom_sample_t *s = prom_metric_find_or_create_sample(self, label_values);
  int rc = 1;
  if (s != NULL) {
    s->value += r_value;
    rc = 0;
  }
  pthread_mutex_unlock(&self->mutex);
  return rc;
}

static int prom_metric_set(prom_metric_t *self, prom_metric_type_t expected, double r_value,
                           const char **label_values) {
  if (self == NULL || self->type != expected) {
    return 1;
  }
  pthread_mutex_lock(&self->mutex);
  prom_sample_t *s = prom_metric_find_or_create_sample(self, label_values);
  int rc = 1;
  if (s != NULL) {
    s->value = r_value;
    rc = 0;
  }
  pthread_mutex_unlock(&self->mutex);
  return rc;
}

int prom_counter_add(prom_counter_t *self, double r_value, const char **label_values) {
  /* Counters are monotonic; silently ignore negative deltas like upstream. */
  if (r_value < 0) {
    return 1;
  }
  return prom_metric_add(self, PROM_COUNTER, r_value, label_values);
}

int prom_collector_registry_default_init(void) {
  int rc = 0;
  pthread_mutex_lock(&g_default_init_mutex);
  if (PROM_COLLECTOR_REGISTRY_DEFAULT == NULL) {
    prom_collector_registry_t *r = calloc(1, sizeof(*r));
    if (r == NULL || pthread_mutex_init(&r->mutex, NULL) != 0) {
      free(r);
      rc = 1;
    } else {
      PROM_COLLECTOR_REGISTRY_DEFAULT = r;
    }
  }
  pthread_mutex_unlock(&g_default_init_mutex);
  return rc;
}

prom_metric_t *prom_collector_registry_must_register_metric(prom_metric_t *metric) {
  if (metric == NULL) {
    return NULL;
  }
  prom_collector_registry_t *r = PROM_COLLECTOR_REGISTRY_DEFAULT;
  if (r == NULL) {
    /* Match upstream's "must" contract: a registration failure is fatal. */
    fprintf(stderr, "prom: default registry not initialized before registering '%s'\n", metric->name);
    prom_metric_destroy(metric);
    abort();
  }
  pthread_mutex_lock(&r->mutex);
  metric->next = r->metrics;
  r->metrics = metric;
  pthread_mutex_unlock(&r->mutex);
  return metric;
}

static void prom_buf_append(prom_buf_t *b, const char *s, size_t n) {
  if (b->oom) {
    return;
  }
  if (b->len + n + 1 > b->cap) {
    size_t cap = b->cap ? b->cap : 4096;
    while (b->len + n + 1 > cap) {
      cap *= 2;
    }
    char *p = realloc(b->data, cap);
    if (p == NULL) {
      b->oom = 1;
      return;
    }
    b->data = p;
    b->cap = cap;
  }
  memcpy(b->data + b->len, s, n);
  b->len += n;
  b->data[b->len] = '\0';
}

static void prom_buf_append_label_value(prom_buf_t *b, const char *s) {
  for (const char *p = s != NULL ? s : ""; *p != '\0'; p++) {
    switch (*p) {
    case '\\':
      prom_buf_append(b, "\\\\", 2);
      break;
    case '"':
      prom_buf_append(b, "\\\"", 2);
      break;
    case '\n':
      prom_buf_append(b, "\\n", 2);
      break;
    default:
      prom_buf_append(b, p, 1);
      break;
    }
  }
}

static void prom_buf_append_value(prom_buf_t *b, double v) {
  char tmp[64];
  int n;
  /* Print integral values within a double's exact-integer range (2^53) without
   * a fractional part for clean, exact output of packet/byte counters; fall
   * back to %g for the rare fractional gauge or an out-of-range/NaN value.
   * Integrality is tested with a round-trip cast so no <math.h> (and no libm
   * link) is needed. */
  if (v >= -9007199254740992.0 && v <= 9007199254740992.0 && v == (double)(long long)v) {
    n = snprintf(tmp, sizeof(tmp), "%lld", (long long)v);
  } else {
    n = snprintf(tmp, sizeof(tmp), "%g", v);
  }
  if (n > 0) {
    prom_buf_append(b, tmp, (size_t)n);
  }
}

static void prom_metric_render(prom_buf_t *b, prom_metric_t *m) {
  const char *type_str = (m->type == PROM_COUNTER) ? "counter" : "gauge";

  prom_buf_append_str(b, "# HELP ");
  prom_buf_append_str(b, m->name);
  prom_buf_append(b, " ", 1);
  prom_buf_append_str(b, m->help);
  prom_buf_append(b, "\n", 1);

  prom_buf_append_str(b, "# TYPE ");
  prom_buf_append_str(b, m->name);
  prom_buf_append(b, " ", 1);
  prom_buf_append_str(b, type_str);
  prom_buf_append(b, "\n", 1);

  pthread_mutex_lock(&m->mutex);
  for (prom_sample_t *s = m->samples; s != NULL; s = s->next) {
    prom_buf_append_str(b, m->name);
    if (m->label_count > 0) {
      prom_buf_append(b, "{", 1);
      for (size_t i = 0; i < m->label_count; i++) {
        if (i > 0) {
          prom_buf_append(b, ",", 1);
        }
        prom_buf_append_str(b, m->label_keys[i]);
        prom_buf_append(b, "=\"", 2);
        prom_buf_append_label_value(b, s->label_values != NULL ? s->label_values[i] : "");
        prom_buf_append(b, "\"", 1);
      }
      prom_buf_append(b, "}", 1);
    }
    prom_buf_append(b, " ", 1);
    prom_buf_append_value(b, s->value);
    prom_buf_append(b, "\n", 1);
  }
  pthread_mutex_unlock(&m->mutex);
}

const char *prom_collector_registry_bridge(prom_collector_registry_t *registry) {
  if (registry == NULL) {
    return NULL;
  }

  prom_buf_t b = {0};

  /* Render in registration order. Metrics are prepended on register, so walk a
   * reversed snapshot of the list to keep output stable across scrapes. */
  pthread_mutex_lock(&registry->mutex);
  size_t count = 0;
  for (prom_metric_t *m = registry->metrics; m != NULL; m = m->next) {
    count++;
  }
  prom_metric_t **ordered = count ? calloc(count, sizeof(*ordered)) : NULL;
  if (count && ordered == NULL) {
    pthread_mutex_unlock(&registry->mutex);
    return NULL;
  }
  size_t idx = count;
  for (prom_metric_t *m = registry->metrics; m != NULL; m = m->next) {
    ordered[--idx] = m;
  }
  pthread_mutex_unlock(&registry->mutex);

  for (size_t i = 0; i < count; i++) {
    prom_metric_render(&b, ordered[i]);
  }
  free(ordered);

  if (b.oom) {
    free(b.data);
    return NULL;
  }
  if (b.data == NULL) {
    /* No metrics registered: still return a valid empty, freeable string. */
    b.data = prom_strdup("");
  }
  return b.data;
}

static char *render(void) {
  char *out = (char *)prom_collector_registry_bridge(PROM_COLLECTOR_REGISTRY_DEFAULT);
  TEST_ASSERT_NOT_NULL(out);
  return out;
}

static void test_counter_accumulates_per_label_set(void) {
  const char *keys[] = {"realm", "user"};
  prom_counter_t *c =
      prom_collector_registry_must_register_metric(prom_counter_new("t_traffic", "rcv packets", 2, keys));
  TEST_ASSERT_NOT_NULL(c);

  const char *bob[] = {"north.gov", "bob"};
  const char *alice[] = {"north.gov", "alice"};
  prom_counter_add(c, 5, bob);
  prom_counter_add(c, 3, bob); /* same series -> 8 */
  prom_counter_add(c, 7, alice);

  char *out = render();
  TEST_ASSERT_NOT_NULL(strstr(out, "# TYPE t_traffic counter"));
  TEST_ASSERT_NOT_NULL(strstr(out, "t_traffic{realm=\"north.gov\",user=\"bob\"} 8"));
  TEST_ASSERT_NOT_NULL(strstr(out, "t_traffic{realm=\"north.gov\",user=\"alice\"} 7"));
  free(out);
}

static void test_counter_ignores_negative_delta(void) {
  prom_counter_t *c = prom_collector_registry_must_register_metric(prom_counter_new("t_monotonic", "h", 0, NULL));
  prom_counter_add(c, 10, NULL);
  TEST_ASSERT_NOT_EQUAL(0, prom_counter_add(c, -4, NULL)); /* rejected */

  char *out = render();
  TEST_ASSERT_NOT_NULL(strstr(out, "t_monotonic 10"));
  free(out);
}

static void test_gauge_inc_dec(void) {
  const char *keys[] = {"type"};
  prom_gauge_t *g = prom_collector_registry_must_register_metric(prom_gauge_new("t_allocations", "allocs", 1, keys));
  const char *udp[] = {"udp"};
  prom_gauge_inc(g, udp);
  prom_gauge_inc(g, udp);
  prom_gauge_dec(g, udp); /* -> 1 */

  char *out = render();
  TEST_ASSERT_NOT_NULL(strstr(out, "# TYPE t_allocations gauge"));
  TEST_ASSERT_NOT_NULL(strstr(out, "t_allocations{type=\"udp\"} 1"));
  free(out);
}

static void test_label_value_escaping(void) {
  const char *keys[] = {"user"};
  prom_counter_t *c = prom_collector_registry_must_register_metric(prom_counter_new("t_escape", "h", 1, keys));
  const char *weird[] = {"a\"b\\c\nd"};
  prom_counter_add(c, 1, weird);

  char *out = render();
  /* backslash, double-quote and newline must be escaped per text format. */
  TEST_ASSERT_NOT_NULL(strstr(out, "t_escape{user=\"a\\\"b\\\\c\\nd\"} 1"));
  free(out);
}

int main(void) {
  UNITY_BEGIN();
  RUN_TEST(test_counter_accumulates_per_label_set);
  RUN_TEST(test_counter_ignores_negative_delta);
  RUN_TEST(test_gauge_inc_dec);
  RUN_TEST(test_label_value_escaping);
  return UNITY_END();
}

void ioa_engine_record_packets(ioa_engine_handle e, uint32_t processed, uint32_t dropped) {
  if (!e) {
    return;
  }
  /* Lock-free: only ever touched by this engine's own relay thread. Flushed to
   * the shared prometheus counters once per second by timer_handler. */
  e->prom_packets_processed += processed;
  e->prom_packets_dropped += dropped;
}

static void maybe_flush_prom_counters(ioa_engine_handle e) {
  if (!turn_params.prometheus || !e) {
    return;
  }

  struct prom_udp_counter_deltas d = {0};

  d.packets_processed = e->prom_packets_processed - e->prom_packets_processed_flushed;
  d.packets_dropped = e->prom_packets_dropped - e->prom_packets_dropped_flushed;
  e->prom_packets_processed_flushed = e->prom_packets_processed;
  e->prom_packets_dropped_flushed = e->prom_packets_dropped;

#if defined(__linux__)
  d.recvmmsg_calls = e->udp_recvmmsg_calls - e->udp_recvmmsg_calls_prom_flushed;
  d.recvmmsg_packets = e->udp_recvmmsg_packets - e->udp_recvmmsg_packets_prom_flushed;
  d.sendmmsg_flushes = e->udp_sendmmsg_flushes - e->udp_sendmmsg_flushes_prom_flushed;
  d.sendmmsg_datagrams = e->udp_sendmmsg_datagrams - e->udp_sendmmsg_datagrams_prom_flushed;
  d.sendmmsg_gso_datagrams = e->udp_sendmmsg_gso_datagrams - e->udp_sendmmsg_gso_datagrams_prom_flushed;
  e->udp_recvmmsg_calls_prom_flushed = e->udp_recvmmsg_calls;
  e->udp_recvmmsg_packets_prom_flushed = e->udp_recvmmsg_packets;
  e->udp_sendmmsg_flushes_prom_flushed = e->udp_sendmmsg_flushes;
  e->udp_sendmmsg_datagrams_prom_flushed = e->udp_sendmmsg_datagrams;
  e->udp_sendmmsg_gso_datagrams_prom_flushed = e->udp_sendmmsg_gso_datagrams;
#endif

  prom_flush_udp_counters(&d);
}

static int redis_maybe_start_tls_sync(redisContext *rc, Ryconninfo *co) {
  if (!rc || !co->use_tls) {
    return 0;
  }
#if defined(TURN_HAVE_HIREDIS_SSL)
  return redis_start_tls(rc, co);
#else
  TURN_LOG_FUNC(TURN_LOG_LEVEL_ERROR, "Redis TLS requested but hiredis_ssl support is not compiled in\n");
  return -1;
#endif
        }

void RyconninfoFree(Ryconninfo *co) {
  if (co) {
    free(co->host);
    free(co->dbname);
    free(co->user);
    free(co->password);
    free(co->tls_ca);
    free(co->tls_capath);
    free(co->tls_cert);
    free(co->tls_key);
    free(co->tls_sni);
    memset(co, 0, sizeof(Ryconninfo));
    free(co);
  }
}

Ryconninfo *RyconninfoParse(const char *userdb, char **errmsg) {
  Ryconninfo *co = (Ryconninfo *)calloc(1, sizeof(Ryconninfo));
  if (!co) {
    return NULL;
  }
  /* Tri-state: -1 means "not specified", so the secure default (peer
   * verification on) can be applied without clobbering an explicit
   * "tls-verify=none". */
  co->tls_verify = -1;

  if (userdb) {
    char *s0 = strdup(userdb);
    char *s = s0;

    while (s && *s) {

      while (*s && (*s == ' ')) {
        ++s;
      }
      char *snext = strstr(s, " ");
      if (snext) {
        *snext = 0;
        ++snext;
      }

      char *seq = strstr(s, "=");
      if (!seq) {
        if (*s) {
          /* a non-empty token with no '=' is a syntax error */
          RyconninfoFree(co);
          co = NULL;
          if (errmsg) {
            *errmsg = strdup(s);
          }
        }
        break;
      }

      *seq = 0;
      if (!strcmp(s, "host")) {
        free(co->host);
        co->host = strdup(seq + 1);
      } else if (!strcmp(s, "ip")) {
        free(co->host);
        co->host = strdup(seq + 1);
      } else if (!strcmp(s, "addr")) {
        free(co->host);
        co->host = strdup(seq + 1);
      } else if (!strcmp(s, "ipaddr")) {
        free(co->host);
        co->host = strdup(seq + 1);
      } else if (!strcmp(s, "hostaddr")) {
        free(co->host);
        co->host = strdup(seq + 1);
      } else if (!strcmp(s, "dbname")) {
        free(co->dbname);
        co->dbname = strdup(seq + 1);
      } else if (!strcmp(s, "db")) {
        free(co->dbname);
        co->dbname = strdup(seq + 1);
      } else if (!strcmp(s, "database")) {
        free(co->dbname);
        co->dbname = strdup(seq + 1);
      } else if (!strcmp(s, "user")) {
        free(co->user);
        co->user = strdup(seq + 1);
      } else if (!strcmp(s, "uname")) {
        free(co->user);
        co->user = strdup(seq + 1);
      } else if (!strcmp(s, "name")) {
        free(co->user);
        co->user = strdup(seq + 1);
      } else if (!strcmp(s, "username")) {
        free(co->user);
        co->user = strdup(seq + 1);
      } else if (!strcmp(s, "password")) {
        free(co->password);
        co->password = strdup(seq + 1);
      } else if (!strcmp(s, "pwd")) {
        free(co->password);
        co->password = strdup(seq + 1);
      } else if (!strcmp(s, "passwd")) {
        free(co->password);
        co->password = strdup(seq + 1);
      } else if (!strcmp(s, "secret")) {
        free(co->password);
        co->password = strdup(seq + 1);
      } else if (!strcmp(s, "port")) {
        co->port = (unsigned int)atoi(seq + 1);
      } else if (!strcmp(s, "p")) {
        co->port = (unsigned int)atoi(seq + 1);
      } else if (!strcmp(s, "connect_timeout")) {
        co->connect_timeout = (unsigned int)atoi(seq + 1);
      } else if (!strcmp(s, "timeout")) {
        co->connect_timeout = (unsigned int)atoi(seq + 1);
      } else if (!strcmp(s, "tls") || !strcmp(s, "ssl")) {
        co->use_tls = ry_parse_bool(seq + 1);
      } else if (!strcmp(s, "tls-ca") || !strcmp(s, "ca") || !strcmp(s, "cacert")) {
        free(co->tls_ca);
        co->tls_ca = strdup(seq + 1);
      } else if (!strcmp(s, "tls-capath") || !strcmp(s, "capath")) {
        free(co->tls_capath);
        co->tls_capath = strdup(seq + 1);
      } else if (!strcmp(s, "tls-cert") || !strcmp(s, "cert")) {
        free(co->tls_cert);
        co->tls_cert = strdup(seq + 1);
      } else if (!strcmp(s, "tls-key") || !strcmp(s, "clientkey")) {
        free(co->tls_key);
        co->tls_key = strdup(seq + 1);
      } else if (!strcmp(s, "tls-sni") || !strcmp(s, "sni") || !strcmp(s, "servername")) {
        free(co->tls_sni);
        co->tls_sni = strdup(seq + 1);
      } else if (!strcmp(s, "tls-verify") || !strcmp(s, "verify")) {
        co->tls_verify = (!strcmp(seq + 1, "none") || !strcmp(seq + 1, "0") || !strcmp(seq + 1, "false")) ? 0 : 1;
      } else {
        RyconninfoFree(co);
        co = NULL;
        if (errmsg) {
          *errmsg = strdup(s);
        }
        break;
      }

      s = snext;
    }

    free(s0);
  }

  if (co) {
    if (!(co->dbname)) {
      co->dbname = strdup("0");
    }
    if (!(co->host)) {
      co->host = strdup("127.0.0.1");
    }
    if (co->tls_verify < 0) {
      co->tls_verify = 1; /* secure default: verify the server certificate */
    }
  }

  return co;
}

static int redis_le_init_ssl(struct redisLibeventEvents *e, redisAsyncContext *ac) {
  if (!e || !e->ssl_ctx) {
    return 0;
  }
#if defined(TURN_HAVE_HIREDIS_SSL)
  if (redisInitiateSSLWithContext(&ac->c, (redisSSLContext *)e->ssl_ctx) != REDIS_OK) {
    TURN_LOG_FUNC(TURN_LOG_LEVEL_ERROR, "%s: Redis TLS init failed: %s\n", __FUNCTION__, ac->c.errstr);
    return -1;
  }
  return 0;
#else
  (void)ac;
  TURN_LOG_FUNC(TURN_LOG_LEVEL_ERROR, "%s: Redis TLS requested but hiredis_ssl support is not compiled in\n",
                __FUNCTION__);
  return -1;
#endif
}

redis_context_handle redisLibeventAttach(struct event_base *base, char *ip0, int port0, char *user, char *pwd, int db,
                                         void *ssl_ctx) {
  e->ssl_ctx = ssl_ctx;

  /* Upgrade to TLS before any command (AUTH/SELECT) is queued. */
  if (redis_le_init_ssl(e, ac) < 0) {
    redisAsyncFree(ac);
    e->context = NULL;
    free(e->ip);
    free(e->user);
    free(e->pwd);
    free(e);
    return NULL;
  }
  /* Re-upgrade to TLS before any command is queued on the new context. */
  if (redis_le_init_ssl(e, ac) < 0) {
    redisAsyncFree(ac);
    e->context = NULL;
    return;
  }

static void test_defaults_applied_for_empty_string(void) {
  Ryconninfo *co = RyconninfoParse("", NULL);
  TEST_ASSERT_NOT_NULL(co);
  TEST_ASSERT_EQUAL_STRING("127.0.0.1", co->host);
  TEST_ASSERT_EQUAL_STRING("0", co->dbname);
  TEST_ASSERT_EQUAL_INT(0, co->use_tls);
  TEST_ASSERT_EQUAL_INT(1, co->tls_verify); /* secure default */
  TEST_ASSERT_EQUAL_UINT(0, co->port);
  RyconninfoFree(co);
}

static void test_defaults_applied_for_null_string(void) {
  Ryconninfo *co = RyconninfoParse(NULL, NULL);
  TEST_ASSERT_NOT_NULL(co);
  TEST_ASSERT_EQUAL_STRING("127.0.0.1", co->host);
  TEST_ASSERT_EQUAL_STRING("0", co->dbname);
  RyconninfoFree(co);
}

static void test_legacy_fields_parse(void) {
  Ryconninfo *co =
      RyconninfoParse("host=redis.example port=6390 user=turn password=s3cret dbname=2 connect_timeout=7", NULL);
  TEST_ASSERT_NOT_NULL(co);
  TEST_ASSERT_EQUAL_STRING("redis.example", co->host);
  TEST_ASSERT_EQUAL_UINT(6390, co->port);
  TEST_ASSERT_EQUAL_STRING("turn", co->user);
  TEST_ASSERT_EQUAL_STRING("s3cret", co->password);
  TEST_ASSERT_EQUAL_STRING("2", co->dbname);
  TEST_ASSERT_EQUAL_UINT(7, co->connect_timeout);
  TEST_ASSERT_EQUAL_INT(0, co->use_tls);
  RyconninfoFree(co);
}

static void test_tls_enabled_with_ca(void) {
  Ryconninfo *co = RyconninfoParse("host=localhost tls=true ca=/etc/coturn/ca.crt", NULL);
  TEST_ASSERT_NOT_NULL(co);
  TEST_ASSERT_EQUAL_INT(1, co->use_tls);
  TEST_ASSERT_EQUAL_STRING("/etc/coturn/ca.crt", co->tls_ca);
  TEST_ASSERT_EQUAL_INT(1, co->tls_verify); /* peer verification on by default */
  RyconninfoFree(co);
}

static void test_tls_mutual_and_sni(void) {
  Ryconninfo *co =
      RyconninfoParse("tls=on tls-ca=/c/ca.pem tls-cert=/c/client.crt tls-key=/c/client.key tls-sni=redis.prod", NULL);
  TEST_ASSERT_NOT_NULL(co);
  TEST_ASSERT_EQUAL_INT(1, co->use_tls);
  TEST_ASSERT_EQUAL_STRING("/c/ca.pem", co->tls_ca);
  TEST_ASSERT_EQUAL_STRING("/c/client.crt", co->tls_cert);
  TEST_ASSERT_EQUAL_STRING("/c/client.key", co->tls_key);
  TEST_ASSERT_EQUAL_STRING("redis.prod", co->tls_sni);
  RyconninfoFree(co);
}

static void test_tls_aliases(void) {
  /* ssl/cacert/cert/clientkey/servername/capath are accepted aliases. */
  Ryconninfo *co = RyconninfoParse(
      "ssl=1 cacert=/a/ca capath=/a/cadir cert=/a/c.crt clientkey=/a/c.key servername=name.example", NULL);
  TEST_ASSERT_NOT_NULL(co);
  TEST_ASSERT_EQUAL_INT(1, co->use_tls);
  TEST_ASSERT_EQUAL_STRING("/a/ca", co->tls_ca);
  TEST_ASSERT_EQUAL_STRING("/a/cadir", co->tls_capath);
  TEST_ASSERT_EQUAL_STRING("/a/c.crt", co->tls_cert);
  TEST_ASSERT_EQUAL_STRING("/a/c.key", co->tls_key);
  TEST_ASSERT_EQUAL_STRING("name.example", co->tls_sni);
  RyconninfoFree(co);
}

static void test_tls_boolean_false_values(void) {
  const char *off[] = {"tls=0", "tls=false", "tls=no", "tls=off", "ssl=0"};
  for (size_t i = 0; i < sizeof(off) / sizeof(off[0]); i++) {
    Ryconninfo *co = RyconninfoParse(off[i], NULL);
    TEST_ASSERT_NOT_NULL(co);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, co->use_tls, off[i]);
    RyconninfoFree(co);
  }
}

static void test_tls_boolean_true_values(void) {
  const char *on[] = {"tls=1", "tls=true", "tls=yes", "tls=on"};
  for (size_t i = 0; i < sizeof(on) / sizeof(on[0]); i++) {
    Ryconninfo *co = RyconninfoParse(on[i], NULL);
    TEST_ASSERT_NOT_NULL(co);
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, co->use_tls, on[i]);
    RyconninfoFree(co);
  }
}

