static void test_unknown_key_rejected(void) {
  char *errmsg = NULL;
  Ryconninfo *co = RyconninfoParse("host=localhost boguskey=1", &errmsg);
  TEST_ASSERT_NULL(co);
  TEST_ASSERT_NOT_NULL(errmsg);
  TEST_ASSERT_EQUAL_STRING("boguskey", errmsg);
  free(errmsg);
}

