static size_t db_extract_hosts(const char *connstr, char out[][TURN_LONG_STRING_SIZE], size_t max) {
  size_t n = 0;
  if (!connstr || !connstr[0]) {
    return 0;
  }

  if (strstr(connstr, "://")) {
    /* URI form */
    const char *p = strstr(connstr, "://") + 3;
    size_t authlen = strcspn(p, "/?"); /* authority ends at first '/' or '?' */
    char auth[TURN_LONG_STRING_SIZE] = {0};
    if (authlen >= sizeof(auth)) {
      authlen = sizeof(auth) - 1;
    }
    memcpy(auth, p, authlen);
    char *at = strrchr(auth, '@'); /* drop any userinfo */
    char *hostlist = at ? at + 1 : auth;
    char *save = NULL;
    for (char *tok = strtok_r(hostlist, ",", &save); tok && n < max; tok = strtok_r(NULL, ",", &save)) {
      char host[TURN_LONG_STRING_SIZE] = {0};
      if (tok[0] == '[') {
        /* [IPv6]:port */
        char *end = strchr(tok, ']');
        if (end) {
          size_t hl = (size_t)(end - (tok + 1));
          if (hl >= sizeof(host)) {
            hl = sizeof(host) - 1;
          }
          memcpy(host, tok + 1, hl);
        }
      } else {
        size_t hl = strcspn(tok, ":"); /* strip :port */
        if (hl >= sizeof(host)) {
          hl = sizeof(host) - 1;
        }
        memcpy(host, tok, hl);
      }
      if (host[0]) {
        STRCPY(out[n], host);
        ++n;
      }
    }
    return n;
  }

  /* key=value form (space-separated) */
  char buf[TURN_LONG_STRING_SIZE] = {0};
  STRCPY(buf, connstr);
  char *save = NULL;
  for (char *tok = strtok_r(buf, " ", &save); tok && n < max; tok = strtok_r(NULL, " ", &save)) {
    char *eq = strchr(tok, '=');
    if (!eq) {
      continue;
    }
    *eq = 0;
    const char *key = tok;
    const char *val = eq + 1;
    if (!strcmp(key, "host") || !strcmp(key, "ip") || !strcmp(key, "addr") || !strcmp(key, "ipaddr") ||
        !strcmp(key, "hostaddr")) {
      if (val[0]) {
        STRCPY(out[n], val);
        ++n;
      }
    }
  }
  return n;
}

static void deny_one_db_connstr(const char *label, const char *connstr) {
  char hosts[8][TURN_LONG_STRING_SIZE];
  const size_t n = db_extract_hosts(connstr, hosts, 8);
  if (n == 0) {
    /* No explicit host: the redis/mysql/pgsql drivers then default to loopback,
     * which good_peer_addr() already denies. Remote DBs always carry a host. */
    TURN_LOG_FUNC(TURN_LOG_LEVEL_INFO,
                  "Security: no explicit host in the %s connection string; backend assumed loopback (already "
                  "denied). Add a denied-peer-ip if your database is remote.\n",
                  label);
    return;
  }
  for (size_t i = 0; i < n; ++i) {
    if (add_ip_list_range(hosts[i], NULL, &turn_params.ip_blacklist) == 0) {
      TURN_LOG_FUNC(TURN_LOG_LEVEL_INFO,
                    "Security: relay connections to the %s backend host %s are denied (auto denied-peer-ip)\n", label,
                    hosts[i]);
    } else {
      TURN_LOG_FUNC(TURN_LOG_LEVEL_WARNING,
                    "Security: could not resolve %s backend host %s to auto-deny it; add an explicit "
                    "denied-peer-ip for it.\n",
                    label, hosts[i]);
    }
  }
}

static void deny_self_db_endpoints(void) {
  const persistent_users_db_t *pudb = &(turn_params.default_users_db.persistent_users_db);
  switch (turn_params.default_users_db.userdb_type) {
  case TURN_USERDB_TYPE_PQ:
    deny_one_db_connstr("PostgreSQL userdb", pudb->userdb);
    break;
  case TURN_USERDB_TYPE_MYSQL:
    deny_one_db_connstr("MySQL userdb", pudb->userdb);
    break;
  case TURN_USERDB_TYPE_MONGO:
    deny_one_db_connstr("MongoDB userdb", pudb->userdb);
    break;
  case TURN_USERDB_TYPE_REDIS:
    deny_one_db_connstr("Redis userdb", pudb->userdb);
    break;
  case TURN_USERDB_TYPE_SQLITE:
  case TURN_USERDB_TYPE_UNKNOWN:
  default:
    break; /* SQLite is a local file -- no network endpoint to deny. */
  }
  if (turn_params.use_redis_statsdb && turn_params.redis_statsdb.connection_string[0]) {
    deny_one_db_connstr("Redis stats DB", turn_params.redis_statsdb.connection_string);
  }
}

bool ioa_addr_get_embedded_ipv4(const ioa_addr *addr, ioa_addr *embedded) {
  if (!addr || !embedded || addr->ss.sa_family != AF_INET6) {
    return false;
  }

  const uint8_t *u = (const uint8_t *)&(addr->s6.sin6_addr);
  const uint8_t *v4 = NULL;

  if (u[0] == 0 && u[1] == 0 && u[2] == 0 && u[3] == 0 && u[4] == 0 && u[5] == 0 && u[6] == 0 && u[7] == 0 &&
      u[8] == 0 && u[9] == 0 && u[10] == 0xff && u[11] == 0xff) {
    /* IPv4-mapped: ::ffff:a.b.c.d (::ffff:0:0/96) */
    v4 = u + 12;
  } else if (u[0] == 0x20 && u[1] == 0x02) {
    /* 6to4: 2002:AABB:CCDD::/16 -> embedded IPv4 is bytes 2..5 */
    v4 = u + 2;
  } else if (u[0] == 0x00 && u[1] == 0x64 && u[2] == 0xff && u[3] == 0x9b && u[4] == 0 && u[5] == 0 && u[6] == 0 &&
             u[7] == 0 && u[8] == 0 && u[9] == 0 && u[10] == 0 && u[11] == 0) {
    /* NAT64 well-known prefix: 64:ff9b::/96 -> embedded IPv4 is bytes 12..15 */
    v4 = u + 12;
  } else if (u[0] == 0 && u[1] == 0 && u[2] == 0 && u[3] == 0 && u[4] == 0 && u[5] == 0 && u[6] == 0 && u[7] == 0 &&
             u[8] == 0 && u[9] == 0 && u[10] == 0 && u[11] == 0) {
    /* IPv4-compatible: ::a.b.c.d (::/96). Intentionally skip :: (unspecified)
     * and ::1 (IPv6 loopback) -- those are handled natively by ioa_addr_is_zero
     * and ioa_addr_is_loopback and must not be reduced to a 0.0.0.x IPv4. */
    if (!(u[12] == 0 && u[13] == 0 && u[14] == 0 && (u[15] == 0 || u[15] == 1))) {
      v4 = u + 12;
    }
  }

  if (!v4) {
    return false;
  }

  memset(embedded, 0, sizeof(*embedded));
  embedded->s4.sin_family = AF_INET;
  memcpy(&(embedded->s4.sin_addr), v4, 4);
  embedded->s4.sin_port = addr->s6.sin6_port;
  return true;
}

static void make_v4_range(ioa_addr_range *r, const char *lo, const char *hi) {
  ioa_addr a = {0}, b = {0};
  make_addr(lo, &a);
  make_addr(hi, &b);
  ioa_addr_range_set(r, &a, &b);
}

static void test_embedded_ipv4_all_encodings(void) {
  const char *encodings[] = {
      "::ffff:10.0.0.5", /* IPv4-mapped   */
      "::10.0.0.5",      /* IPv4-compat   */
      "2002:a00:5::",    /* 6to4          */
      "64:ff9b::a00:5",  /* NAT64         */
  };
  ioa_addr expected = {0};
  make_addr("10.0.0.5", &expected);
  for (size_t i = 0; i < sizeof(encodings) / sizeof(encodings[0]); ++i) {
    ioa_addr in = {0}, out = {0};
    make_addr(encodings[i], &in);
    TEST_ASSERT_TRUE_MESSAGE(ioa_addr_get_embedded_ipv4(&in, &out), encodings[i]);
    TEST_ASSERT_EQUAL_INT(AF_INET, out.ss.sa_family);
    TEST_ASSERT_TRUE_MESSAGE(addr_eq_no_port(&out, &expected), encodings[i]);
  }
}

static void test_embedded_ipv4_rejects_non_embedding(void) {
  const char *non[] = {"::1", "::", "2001:db8::1", "fc00::1", "8.8.8.8"};
  for (size_t i = 0; i < sizeof(non) / sizeof(non[0]); ++i) {
    ioa_addr in = {0}, out = {0};
    make_addr(non[i], &in);
    TEST_ASSERT_FALSE_MESSAGE(ioa_addr_get_embedded_ipv4(&in, &out), non[i]);
  }
}

static void test_in_range_matches_all_ipv4_in_ipv6_encodings(void) {
  ioa_addr_range denied = {0};
  make_v4_range(&denied, "10.0.0.0", "10.255.255.255");

  const char *encodings[] = {
      "::ffff:10.0.0.5",
      "::10.0.0.5",
      "2002:a00:5::",
      "64:ff9b::a00:5",
