static int sqlite_prepare_bind(sqlite3 *sqliteconnection, sqlite3_stmt **st, const char *sql, int nparams,
                               const char *const params[]) {
  int rc = sqlite3_prepare(sqliteconnection, sql, -1, st, 0);
  if (rc != SQLITE_OK) {
    return rc;
  }
  for (int i = 0; i < nparams; ++i) {
    rc = sqlite3_bind_text(*st, i + 1, params[i] ? params[i] : "", -1, SQLITE_TRANSIENT);
    if (rc != SQLITE_OK) {
      return rc;
    }
  }
  return SQLITE_OK;
}

static void assert_prepared(const char *expect_cmd, int nparams) {
  TEST_ASSERT_TRUE_MESSAGE(mystub_used_stmt(), "expected a prepared statement, got mysql_query()");
  TEST_ASSERT_EQUAL_STRING(expect_cmd, mystub_last_command());
  TEST_ASSERT_EQUAL_INT(nparams, mystub_nparams());
}

