  struct mp_deregister_ctx ctx = {e, (ur_addr_map_value_type)(uintptr_t)turn_session, peer_addr, 0};
  ur_addr_map_foreach_key_arg(&e->mp_table, mp_deregister_cb, &ctx);
}

