static BOOL xf_rail_get_workarea(xfContext* xfc, xfWorkArea* workArea)
{
	WINPR_ASSERT(xfc);
	WINPR_ASSERT(workArea);
	const BOOL rc = xf_GetWorkArea(xfc);
	*workArea = xfc->workArea;
	return rc;
}

static UINT xf_rail_send_workarea(xfContext* xfc)
{
	WINPR_ASSERT(xfc);

	if (!xfc->remote_app || !xfc->rail)
		return CHANNEL_RC_OK;

	xfWorkArea current = WINPR_C_ARRAY_INIT;
	if (!xf_rail_get_workarea(xfc, &current))
		return CHANNEL_RC_OK;

	if (xfc->railWorkAreaValid && (current.x == xfc->railWorkArea.x) &&
	    (current.y == xfc->railWorkArea.y) && (current.width == xfc->railWorkArea.width) &&
	    (current.height == xfc->railWorkArea.height))
	{
		WLog_DBG(TAG,
		         "Suppressing work area %" PRId32 ",%" PRId32 " %" PRIu32 "x%" PRIu32 ": unchanged",
		         current.x, current.y, current.width, current.height);
		return CHANNEL_RC_OK;
	}

	const INT64 right = (INT64)current.x + current.width;
	const INT64 bottom = (INT64)current.y + current.height;
	const RAIL_SYSPARAM_ORDER sysparam = { .params = SPI_MASK_SET_WORK_AREA,
		                                   .workArea.left =
		                                       WINPR_CXX_COMPAT_CAST(UINT16, current.x),
		                                   .workArea.top = WINPR_CXX_COMPAT_CAST(UINT16, current.y),
		                                   .workArea.right = WINPR_CXX_COMPAT_CAST(UINT16, right),
		                                   .workArea.bottom =
		                                       WINPR_CXX_COMPAT_CAST(UINT16, bottom) };

	WLog_DBG(TAG, "Sending work area %" PRId32 ",%" PRId32 " %" PRIu32 "x%" PRIu32, current.x,
	         current.y, current.width, current.height);
	const UINT rc = xfc->rail->ClientSystemParam(xfc->rail, &sysparam);
	if (rc == CHANNEL_RC_OK)
	{
		xfc->railWorkArea = current;
		xfc->railWorkAreaValid = TRUE;
	}
	return rc;
}

static uint64_t xf_rail_workarea_timer(rdpContext* context, WINPR_ATTR_UNUSED void* userdata,
                                       FreeRDP_TimerID timerID,
                                       WINPR_ATTR_UNUSED uint64_t timestamp,
                                       WINPR_ATTR_UNUSED uint64_t interval)
{
	xfContext* xfc = (xfContext*)context;
	WINPR_ASSERT(xfc);

	if (xfc->railWorkAreaTimerId != timerID)
		return 0;

	xfc->railWorkAreaTimerId = 0;
	const UINT rc = xf_rail_send_workarea(xfc);
	if (rc != CHANNEL_RC_OK)
		WLog_ERR(TAG, "Failed to send settled work area: %" PRIu32, rc);
	return 0;
}

BOOL xf_rail_schedule_workarea(xfContext* xfc)
{
	WINPR_ASSERT(xfc);

	xfWorkArea current = WINPR_C_ARRAY_INIT;
	if (!xf_rail_get_workarea(xfc, &current))
	{
		WLog_DBG(TAG, "Suppressing work area update: current value unavailable");
		return TRUE;
	}

	WLog_DBG(TAG,
	         "Deferring work area %" PRId32 ",%" PRId32 " %" PRIu32 "x%" PRIu32 ": still settling",
	         current.x, current.y, current.width, current.height);

	rdpContext* context = (rdpContext*)xfc;
	if (xfc->railWorkAreaTimerId != 0)
	{
		freerdp_timer_remove(context, xfc->railWorkAreaTimerId);
		xfc->railWorkAreaTimerId = 0;
	}

	xfc->railWorkAreaTimerId = freerdp_timer_add(context, WORKAREA_SETTLE_INTERVAL_NS,
	                                             xf_rail_workarea_timer, nullptr, true);
	if (xfc->railWorkAreaTimerId == 0)
		WLog_ERR(TAG, "Failed to arm work area settle timer");
	return xfc->railWorkAreaTimerId != 0;
		xfc->railWorkAreaValid = FALSE;
		if (!xf_rail_select_workarea_events(xfc))
			WLog_WARN(TAG, "Failed to subscribe to root-window work-area changes");
	xfc->railWorkAreaValid = FALSE;
	xfc->railWorkAreaTimerId = 0;
	rdpContext* context = (rdpContext*)xfc;

	if (xfc->railWorkAreaTimerId != 0)
	{
		freerdp_timer_remove(context, xfc->railWorkAreaTimerId);
		xfc->railWorkAreaTimerId = 0;
	}

static int magicmouse_reset_resume(struct hid_device *hdev)
{
	struct magicmouse_sc *msc = hid_get_drvdata(hdev);

	/* The device drops out of multitouch mode on resume; re-send the
	 * enable report.  Only the HID_TYPE_USBMOUSE interface accepts it, and
	 * it must be deferred. Sending it inline here is too early.
	 */
	if (msc && hdev->type == HID_TYPE_USBMOUSE)
		schedule_delayed_work(&msc->work, msecs_to_jiffies(500));

	return 0;
}

static void _xmp_add_new(Exiv2::XmpData &xmpData, const char *key, const T &value)
{
  Exiv2::XmpTextValue v(Exiv2::toString(value));
  xmpData.add(Exiv2::XmpKey(key), &v);
}

static void
ErrorIfOutputPluginNotAllowed(MultiConnection *connection, char *outputPlugin)
{
	StringInfo command = makeStringInfo();
	appendStringInfo(command,
					 "SELECT current_setting('output_plugin_libraries', true), "
					 "coalesce(bool_or(CASE WHEN name LIKE '\"%%\"' THEN "
					 "replace(substring(name, 2, length(name) - 2), '\"\"', '\"') "
					 "ELSE name END = %s), false) "
					 "FROM (SELECT btrim(elem, E' \\t\\n\\r\\f') AS name FROM unnest("
					 "string_to_array(coalesce(current_setting("
					 "'output_plugin_libraries', true), %s), ',')) elem) s",
					 quote_literal_cstr(outputPlugin),
					 quote_literal_cstr(outputPlugin));

	PGresult *result = NULL;
	int queryResult = ExecuteOptionalRemoteCommand(connection, command->data, &result);

	if (queryResult != RESPONSE_OKAY || !IsResponseOK(result) || PQntuples(result) != 1)
	{
		ReportResultError(connection, result, ERROR);
	}

	char *allowedPlugins = "";
	if (!PQgetisnull(result, 0, 0))
	{
		allowedPlugins = pstrdup(PQgetvalue(result, 0, 0));
	}

	bool isAllowed = (strcmp(PQgetvalue(result, 0, 1), "t") == 0);

	PQclear(result);
	ForgetResults(connection);

	if (isAllowed)
	{
		return;
	}

	StringInfo newValue = makeStringInfo();
	if (allowedPlugins[0] != '\0')
	{
		appendStringInfo(newValue, "%s, ", allowedPlugins);
	}
	appendStringInfoString(newValue, outputPlugin);

	ereport(ERROR, (errmsg("output plugin \"%s\" is not allowed on the source node",
						   outputPlugin),
					errdetail("Non-blocking shard splits replicate data with the \"%s\" "
							  "logical decoding output plugin, but PostgreSQL on node "
							  "%s:%d only allows the plugins listed in "
							  "\"output_plugin_libraries\", which is set to \"%s\".",
							  outputPlugin, connection->hostname, connection->port,
							  allowedPlugins),
					errhint("Allow the plugin on every node and reload the "
							"configuration, for example: ALTER SYSTEM SET "
							"output_plugin_libraries = %s; SELECT pg_reload_conf();",
							newValue->data)));
}

static bool
WarnIfDeprecatedPseudoconstantQualsGucIsSet(bool *newval, void **extra,
											GucSource source)
{
	/* warn whenever the value comes from anywhere other than the built-in default */
	if (source != PGC_S_DEFAULT)
	{
		ereport(WARNING, (errcode(ERRCODE_WARNING_DEPRECATED_FEATURE),
						  errmsg("citus.enable_outer_joins_with_pseudoconstant_"
								 "quals_pre_pg17 has no effect and is deprecated"),
						  errdetail("This setting only applied to PostgreSQL 16, "
									"which Citus no longer supports."),
						  errhint("Remove it from your configuration. It will be "
								  "removed in a future Citus release.")));
	}

	return true;
}

static bool
RepackStmtOptionEnabled(ClusterStmt *clusterStmt, const char *optionName)
{
	DefElem *opt = NULL;
	foreach_declared_ptr(opt, clusterStmt->params)
	{
		if (strcmp(opt->defname, optionName) == 0)
		{
			return defGetBoolean(opt);
		}
	}
	return false;
}

char *
GetAlterPublicationExcludedTablesDDLCommand(Oid publicationId,
											bool includeLocalTables)
{
	CreatePublicationStmt *createPubStmt = BuildCreatePublicationStmt(publicationId);

	AlterPublicationStmt *alterPubStmt = makeNode(AlterPublicationStmt);
	alterPubStmt->pubname = createPubStmt->pubname;
	alterPubStmt->action = AP_SetObjects;
	alterPubStmt->pubobjects = createPubStmt->pubobjects;
	alterPubStmt->for_all_tables = createPubStmt->for_all_tables;
	alterPubStmt->for_all_sequences = createPubStmt->for_all_sequences;

	/* we took the WHERE clause from the catalog where it is already transformed */
	bool whereClauseRequiresTransform = false;

	return DeparseAlterPublicationStmtExtended((Node *) alterPubStmt,
											   whereClauseRequiresTransform,
											   includeLocalTables);
}

static bool
AppendPublicationAllObjects(StringInfo buf, bool forAllTables,
							bool forAllSequences, List *publicationObjects,
							bool whereClauseNeedsTransform,
							bool includeLocalTables)
{
	bool appendedObject = false;

	if (forAllTables)
	{
		appendStringInfoString(buf, " ALL TABLES");
		appendedObject = true;

		StringInfoData exceptObjects = { 0 };
		initStringInfo(&exceptObjects);

		if (AppendPublicationObjects(&exceptObjects, publicationObjects,
									 whereClauseNeedsTransform,
									 includeLocalTables))
		{
			appendStringInfo(buf, " EXCEPT (%s)", exceptObjects.data + 1);
		}

		pfree(exceptObjects.data);
	}

	if (forAllSequences)
	{
		appendStringInfoString(buf, appendedObject ? ", ALL SEQUENCES" :
							   " ALL SEQUENCES");
		appendedObject = true;
	}

	return appendedObject;
}

static bool
EnsurePublicationPropagatable(Oid publicationId)
{
	ObjectAddress *publicationAddress = palloc0(sizeof(ObjectAddress));
	ObjectAddressSet(*publicationAddress, PublicationRelationId, publicationId);
	List *addresses = list_make1(publicationAddress);

	if (!ShouldPropagateAnyObject(addresses))
	{
		return false;
	}

	EnsureAllObjectDependenciesExistOnAllNodes(addresses);

	return true;
}

void
multi_build_simple_rel_hook(PlannerInfo *root, RelOptInfo *rel,
							RangeTblEntry *rte)
{
	/* the delegate ignores these args; it re-derives the RTE from rel->relid */
	multi_get_relation_info_hook(root, InvalidOid, false, rel);
}

static void
PruneOrClausesForTaskFragments(Query *taskQuery, List *fragmentCombination,
							   HTAB **armShardHash)
{
	Node *quals = taskQuery->jointree->quals;
	if (quals == NULL)
	{
		return;
	}

	RangeTableFragment *fragment = NULL;
	foreach_declared_ptr(fragment, fragmentCombination)
	{
		if (fragment->fragmentType != CITUS_RTE_RELATION)
		{
			continue;
		}

		ShardInterval *shardInterval = (ShardInterval *) fragment->fragmentReference;
		Oid relationId = shardInterval->relationId;

		/*
		 * Only hash-distributed tables with a distribution key are eligible:
		 * for these the regular shard-pruning machinery can decide which shard
		 * an OR arm targets.
		 */
		CitusTableCacheEntry *cacheEntry = GetCitusTableCacheEntry(relationId);
		if (!IsCitusTableTypeCacheEntry(cacheEntry, HASH_DISTRIBUTED) ||
			!HasDistributionKeyCacheEntry(cacheEntry))
		{
			continue;
		}

		quals = PruneUnreachableOrArms(quals, relationId, fragment->rangeTableId,
									   shardInterval->shardId, armShardHash);
	}

	taskQuery->jointree->quals = quals;
}

static Node *
PruneUnreachableOrArms(Node *qual, Oid relationId, Index rangeTableId, uint64 shardId,
					   HTAB **armShardHash)
{
	if (qual == NULL)
	{
		return NULL;
	}

	if (IsA(qual, List))
	{
		List *conjuncts = (List *) qual;
		ListCell *conjunctCell = NULL;
		foreach(conjunctCell, conjuncts)
		{
			lfirst(conjunctCell) = PruneUnreachableOrArms((Node *) lfirst(conjunctCell),
														  relationId, rangeTableId,
														  shardId, armShardHash);
		}

		return (Node *) conjuncts;
	}

	if (IsA(qual, BoolExpr))
	{
		BoolExpr *boolExpr = (BoolExpr *) qual;

		if (boolExpr->boolop == AND_EXPR)
		{
			ListCell *argCell = NULL;
			foreach(argCell, boolExpr->args)
			{
				lfirst(argCell) = PruneUnreachableOrArms((Node *) lfirst(argCell),
														 relationId, rangeTableId,
														 shardId, armShardHash);
			}

			return qual;
		}
		else if (boolExpr->boolop == OR_EXPR)
		{
			List *keptArms = NIL;
			bool anyDropped = false;
			int keptCount = 0;
			int armIndex = 0;
			ListCell *armCell = NULL;

			foreach(armCell, boolExpr->args)
			{
				Node *arm = (Node *) lfirst(armCell);
				List *armShardList = ReachableShardListForArm(arm, relationId,
															  rangeTableId,
															  armShardHash);
				bool reachable = ShardListContainsShardId(armShardList, shardId);

				if (reachable)
				{
					keptCount++;
				}

				if (!reachable && !anyDropped)
				{
					/*
					 * First arm we drop: only now do we materialize the kept
					 * list, backfilling the earlier arms, which were all kept.
					 */
					anyDropped = true;
					keptArms = list_copy_head(boolExpr->args, armIndex);
				}
				else if (reachable && anyDropped)
				{
					keptArms = lappend(keptArms, arm);
				}

				armIndex++;
			}

			/*
			 * Be a strict no-op unless we both kept at least one arm and
			 * dropped at least one: nothing dropped needs no rewrite, and
			 * keeping zero arms would only happen if our pruning disagreed with
			 * the task's own shard selection. Not building the list until the
			 * first arm is dropped also avoids allocating in the common case
			 * where every arm is retained.
			 */
			if (!anyDropped || keptCount == 0)
			{
				return qual;
			}

			if (keptCount == 1)
			{
				/* a single-argument OR is not a valid expression */
				return (Node *) linitial(keptArms);
			}

			boolExpr->args = keptArms;
			return qual;
		}
	}

	return qual;
}

static List *
ReachableShardListForArm(Node *arm, Oid relationId, Index rangeTableId,
						 HTAB **armShardHash)
{
	if (*armShardHash == NULL)
	{
		HASHCTL info = { 0 };
		info.keysize = sizeof(ArmShardHashKey);
		info.entrysize = sizeof(ArmShardHashEntry);
		info.hash = ArmShardHashFn;
		info.match = ArmShardMatchFn;
		info.hcxt = CurrentMemoryContext;

		*armShardHash = hash_create("Or arm shard cache", 32, &info,
									HASH_ELEM | HASH_FUNCTION | HASH_COMPARE |
									HASH_CONTEXT);
	}

	ArmShardHashKey lookupKey;
	memset(&lookupKey, 0, sizeof(lookupKey));
	lookupKey.relationId = relationId;
	lookupKey.rangeTableId = rangeTableId;
	lookupKey.arm = arm;

	bool found = false;
	ArmShardHashEntry *entry = hash_search(*armShardHash, &lookupKey, HASH_FIND,
										   &found);
	if (found)
	{
		return entry->shardIntervalList;
	}

	/*
	 * Compute the shard list before inserting the entry so the cache is never
	 * left holding an entry with an uninitialized value (e.g. if PruneShards
	 * throws).
	 */
	List *armClauseList = make_ands_implicit((Expr *) arm);
	List *shardIntervalList = PruneShards(relationId, rangeTableId, armClauseList, NULL);

	entry = hash_search(*armShardHash, &lookupKey, HASH_ENTER, NULL);
	entry->shardIntervalList = shardIntervalList;

	return shardIntervalList;
}

static uint32
ArmShardHashFn(const void *key, Size keysize)
{
	const ArmShardHashKey *hashKey = (const ArmShardHashKey *) key;

	char *armString = nodeToString(hashKey->arm);
	uint32 hashValue = hash_bytes((const unsigned char *) armString,
								  strlen(armString));
	pfree(armString);

	hashValue = hash_combine(hashValue, hash_uint32((uint32) hashKey->relationId));
	hashValue = hash_combine(hashValue, hash_uint32((uint32) hashKey->rangeTableId));

	return hashValue;
}

static int
ArmShardMatchFn(const void *key1, const void *key2, Size keysize)
{
	const ArmShardHashKey *hashKey1 = (const ArmShardHashKey *) key1;
	const ArmShardHashKey *hashKey2 = (const ArmShardHashKey *) key2;

	if (hashKey1->relationId == hashKey2->relationId &&
		hashKey1->rangeTableId == hashKey2->rangeTableId &&
		equal(hashKey1->arm, hashKey2->arm))
	{
		return 0;
	}

	return 1;
}

static bool
ShardListContainsShardId(List *shardIntervalList, uint64 shardId)
{
	ShardInterval *shardInterval = NULL;
	foreach_declared_ptr(shardInterval, shardIntervalList)
	{
		if (shardInterval->shardId == shardId)
		{
			return true;
		}
	}

	return false;
}

static struct bufferevent *
ws_threadsafe_bevcb(struct event_base *base, void *arg)
{
	return bufferevent_socket_new(
		base, -1, BEV_OPT_CLOSE_ON_FREE | BEV_OPT_THREADSAFE);
}

static void
http_on_ws_early_free_cb(struct evhttp_request *req, void *arg)
{
	struct evws_connection *evws;

	evws = evws_new_session(req, on_ws_msg_cb, (void *)0xDEADBEEF,
		BEV_OPT_THREADSAFE);
	if (evws == NULL) {
		ws_early_free_session_was_null = 1;
		test_ok++;
	}
}

static void
ws_early_free_drain_readcb(struct bufferevent *bev, void *arg)
{
	evbuffer_drain(bufferevent_get_input(bev), evbuffer_get_length(
		bufferevent_get_input(bev)));
}

void
http_ws_early_free_test(void *arg)
{
	struct basic_test_data *data = arg;
	struct bufferevent *bev = NULL;
	evutil_socket_t fd;
	ev_uint16_t port = 0;
	struct evhttp *http = http_setup(&port, data->base, 0);
	struct evbuffer *out;
	struct timeval tv = {5, 0};

	exit_base = data->base;
	ws_early_free_session_was_null = 0;

	evhttp_set_bevcb(http, ws_threadsafe_bevcb, NULL);
	evhttp_set_cb(http, "/ws_early_free", http_on_ws_early_free_cb, NULL);

	fd = http_connect("127.0.0.1", port);
	bev = create_bev(data->base, fd, 0, BEV_OPT_CLOSE_ON_FREE);
	bufferevent_setcb(bev, ws_early_free_drain_readcb, http_writecb,
		http_ws_errorcb, data->base);
	out = bufferevent_get_output(bev);

	evbuffer_add_printf(out,
		"GET /ws_early_free HTTP/1.1\r\n"
		"Host: somehost\r\n"
		"Connection: Upgrade\r\n"
		"Upgrade: websocket\r\n"
		"Sec-WebSocket-Key: x3JJHMbDL1EzLkh9GBhXDw==\r\n"
		"\r\n");

	test_ok = 0;
	event_base_loopexit(data->base, &tv);
	event_base_dispatch(data->base);

	tt_int_op(ws_early_free_session_was_null, ==, 1);

	evhttp_free(http);
end:
	if (bev)
		bufferevent_free(bev);
}

static size_t acquire_buf(struct st_zstd_context_t *self)
    if (self->bufs.size == 0 || self->bufs.entries[self->bufs.size - 1].len == self->buf_capacity) {
        h2o_vector_reserve(NULL, &self->bufs, self->bufs.size + 1);
        h2o_sendvec_init_raw(self->bufs.entries + self->bufs.size++, h2o_mem_alloc(self->buf_capacity), 0);
    }

static void test_acl_legacy_format(void)
{
    h2o_connect_acl_entry_t entry;

    /* `:*` means any port, same as omitting the port */
    ok(h2o_connect_parse_acl(&entry, "+127.0.0.1:*") == NULL);
    ok(entry.allow_);
    ok(entry.addr_family == H2O_CONNECT_ACL_ADDRESS_V4);
    ok(entry.addr.v4 == 0x7f000001);
    ok(entry.addr_mask == 32);
    ok(entry.port_min == 0);
    ok(entry.port_max == 0);

    /* `:*` on the wildcard address */
    ok(h2o_connect_parse_acl(&entry, "+*:*") == NULL);
    ok(entry.addr_family == H2O_CONNECT_ACL_ADDRESS_ANY);
    ok(entry.port_min == 0);
    ok(entry.port_max == 0);

    /* legacy order: netmask after the port (address:port/mask) */
    ok(h2o_connect_parse_acl(&entry, "+10.0.0.0:443/8") == NULL);
    ok(entry.allow_);
    ok(entry.addr_family == H2O_CONNECT_ACL_ADDRESS_V4);
    ok(entry.addr_mask == 8);
    ok(entry.port_min == 443);
    ok(entry.port_max == 443);

    /* legacy order with a port range (address:port-port/mask) */
    ok(h2o_connect_parse_acl(&entry, "+10.0.0.0:80-443/8") == NULL);
    ok(entry.addr_mask == 8);
    ok(entry.port_min == 80);
    ok(entry.port_max == 443);

    /* legacy order with any-port wildcard followed by a netmask */
    ok(h2o_connect_parse_acl(&entry, "+10.0.0.0:*/8") == NULL);
    ok(entry.addr_mask == 8);
    ok(entry.port_min == 0);
    ok(entry.port_max == 0);

    /* new and legacy orders yield the same result */
    h2o_connect_acl_entry_t entry2;
    ok(h2o_connect_parse_acl(&entry, "+10.0.0.0/8:443") == NULL);
    ok(h2o_connect_parse_acl(&entry2, "+10.0.0.0:443/8") == NULL);
    ok(entry.addr.v4 == entry2.addr.v4 && entry.addr_mask == entry2.addr_mask && entry.port_min == entry2.port_min &&
       entry.port_max == entry2.port_max);

    /* error: netmask given on both sides of the port */
    ok(h2o_connect_parse_acl(&entry, "+10.0.0.0/8:443/16") != NULL);
}

static int parse_decimal(const char **s, const char *end)
{
    const char *start = *s;
    int v = 0;

    for (; *s != end && '0' <= **s && **s <= '9'; ++*s) {
        int digit = **s - '0';
        /* reject if `v * 10 + digit` would overflow INT_MAX, checked before the multiply to avoid relying on a wider type */
        if (v > (INT_MAX - digit) / 10)
            return -1;
        v = v * 10 + digit;
    }
    if (*s == start)
        return -1;
    return v;
}

static uint64_t get_request_stream_size(struct st_h2o_http3_server_stream_t *stream)
{
    if (!quicly_recvstate_transfer_complete(&stream->quic->recvstate))
        return stream->quic->recvstate.received.ranges[0].end;

    /* On reset, recvstate has no final size and clears received ranges. In that case, data_off is the best available contiguous
     * byte count. */
    if (stream->quic->recvstate.eos == UINT64_MAX)
        return stream->quic->recvstate.data_off;

    return stream->quic->recvstate.eos;
}

static void log_stream_stats(struct st_h2o_http3_server_stream_t *stream)
{
    H2O_PROBE_CONN(H3S_STREAM_STATS, &get_conn(stream)->super, stream->quic->stream_id, get_request_stream_size(stream),
                   stream->stats.received.frame.headers, stream->req.req_body_bytes_received, stream->stats.received.qpack.count,
                   stream->stats.received.qpack.text_bytes, stream->quic->sendstate.size_inflight, stream->stats.sent.frame.headers,
                   stream->req.bytes_sent, stream->stats.sent.qpack.count, stream->stats.sent.qpack.text_bytes);
    H2O_LOG_CONN(h3s_stream_stats, &get_conn(stream)->super, {
        uint64_t request_stream_size = get_request_stream_size(stream);
        uint64_t response_stream_size = stream->quic->sendstate.size_inflight;
        PTLS_LOG_ELEMENT_UNSIGNED(stream_id, stream->quic->stream_id);
        PTLS_LOG_ELEMENT_UNSIGNED(request_stream_size, request_stream_size);
        PTLS_LOG_ELEMENT_UNSIGNED(request_headers_frame_size, stream->stats.received.frame.headers);
        PTLS_LOG_ELEMENT_UNSIGNED(request_body_size, stream->req.req_body_bytes_received);
        PTLS_LOG_ELEMENT_UNSIGNED(request_header_count, stream->stats.received.qpack.count);
        PTLS_LOG_ELEMENT_UNSIGNED(request_header_text_size, stream->stats.received.qpack.text_bytes);
        PTLS_LOG_ELEMENT_UNSIGNED(response_stream_size, response_stream_size);
        PTLS_LOG_ELEMENT_UNSIGNED(response_headers_frame_size, stream->stats.sent.frame.headers);
        PTLS_LOG_ELEMENT_UNSIGNED(response_body_size, stream->req.bytes_sent);
        PTLS_LOG_ELEMENT_UNSIGNED(response_header_count, stream->stats.sent.qpack.count);
        PTLS_LOG_ELEMENT_UNSIGNED(response_header_text_size, stream->stats.sent.qpack.text_bytes);
    });
}

void h2o_qpack_decoder_update_num_blocked(h2o_qpack_decoder_t *qpack, int delta)
    if (delta > 0) {
        assert(qpack->num_blocked + (uint64_t)delta <= qpack->max_blocked);
        qpack->num_blocked += (uint64_t)delta;
    }

static uint64_t calc_max_blocked_streams(h2o_http3_conn_t *conn)
{
    if (conn->qpack.ctx->decoder_table_capacity == 0)
        return 0;
    return quicly_get_context(conn->super.quic)->transport_params.max_streams_bidi;
}

static void rteth_reset_work(struct work_struct *work)
{
	struct rteth_ctrl *ctrl = container_of(work, struct rteth_ctrl, reset_work);
	struct net_device *dev = ctrl->dev;
	int ret;

	rtnl_lock();

	if (!netif_running(dev))
		goto out;

	rteth_stop(dev);
	ret = rteth_open(dev);
	if (ret) {
		netdev_err(dev, "tx timeout recovery failed: %d\n", ret);
		netif_device_detach(dev);
		goto out;
	}

	netif_trans_update(dev);

out:
	rtnl_unlock();
}

static void setRtcDateTimeFromGps(void) {
    if (!rtcHasTime() && gpsSol.dateTime.valid) {
        dateTime_t dt;
        dt.year = gpsSol.dateTime.year;
        dt.month = gpsSol.dateTime.month;
        dt.day = gpsSol.dateTime.day;
        dt.hours = gpsSol.dateTime.hour;
        dt.minutes = gpsSol.dateTime.min;
        dt.seconds = gpsSol.dateTime.sec;
        dt.millis = gpsSol.dateTime.millis;
        rtcSetDateTime(&dt);
    }
}

TEST_F(RcControlsModesTest, updateActivatedModesBoxParalyzeLatchesForeverOnceActivated)
{
    // given
    modeActivationConditionsMutable(7)->modeId = BOXPARALYZE;
    modeActivationConditionsMutable(7)->auxChannelIndex = AUX1 - NON_AUX_CHANNEL_COUNT;
    modeActivationConditionsMutable(7)->range.startStep = CHANNEL_VALUE_TO_STEP(1700);
    modeActivationConditionsMutable(7)->range.endStep = CHANNEL_VALUE_TO_STEP(2100);

    boxBitmask_t mask;
    memset(&mask, 0, sizeof(mask));
    rcModeUpdate(&mask);

    memset(&rxRuntimeState, 0, sizeof(rxRuntimeState_t));
    rxRuntimeState.channelCount = MAX_SUPPORTED_RC_CHANNEL_COUNT - NON_AUX_CHANNEL_COUNT;

    for (int index = AUX1; index < MAX_SUPPORTED_RC_CHANNEL_COUNT; index++) {
        rcData[index] = PWM_RANGE_MIDDLE;
    }

    analyzeModeActivationConditions();

    // when: switch is in-range before the boot guard has ever seen it off
    resetMillis();
    rcData[AUX1] = PWM_RANGE_MAX;
    updateActivatedModes();

    // then: activation is withheld until the switch has been observed off
    EXPECT_FALSE(IS_RC_MODE_ACTIVE(BOXPARALYZE));

    // when: switch goes off and the boot delay elapses
    rcData[AUX1] = PWM_RANGE_MIDDLE;
    fixedMillis = STICKY_MODE_BOOT_DELAY_US / 1000 + 1;
    updateActivatedModes();

    // then: still inactive, but the guard is now armed
    EXPECT_FALSE(IS_RC_MODE_ACTIVE(BOXPARALYZE));

    // when: switch is moved into range
    rcData[AUX1] = PWM_RANGE_MAX;
    updateActivatedModes();

    // then: mode activates normally
    EXPECT_TRUE(IS_RC_MODE_ACTIVE(BOXPARALYZE));

    // when: switch is moved back out of range
    rcData[AUX1] = PWM_RANGE_MIDDLE;
    updateActivatedModes();

    // then: BOXPARALYZE is a kill switch and must stay active until reboot
    EXPECT_TRUE(IS_RC_MODE_ACTIVE(BOXPARALYZE));
}

TEST_F(RcControlsModesTest, updateActivatedModesBoxBlackboxEraseDoesNotLatchForever)
{
    // given
    modeActivationConditionsMutable(8)->modeId = BOXBLACKBOXERASE;
    modeActivationConditionsMutable(8)->auxChannelIndex = AUX2 - NON_AUX_CHANNEL_COUNT;
    modeActivationConditionsMutable(8)->range.startStep = CHANNEL_VALUE_TO_STEP(1700);
    modeActivationConditionsMutable(8)->range.endStep = CHANNEL_VALUE_TO_STEP(2100);

    boxBitmask_t mask;
    memset(&mask, 0, sizeof(mask));
    rcModeUpdate(&mask);

    memset(&rxRuntimeState, 0, sizeof(rxRuntimeState_t));
    rxRuntimeState.channelCount = MAX_SUPPORTED_RC_CHANNEL_COUNT - NON_AUX_CHANNEL_COUNT;

    for (int index = AUX1; index < MAX_SUPPORTED_RC_CHANNEL_COUNT; index++) {
        rcData[index] = PWM_RANGE_MIDDLE;
    }

    analyzeModeActivationConditions();

    // when: switch is in-range before RX has ever been seen off (rcData defaults, e.g. before RX link)
    resetMillis();
    rcData[AUX2] = PWM_RANGE_MAX;
    updateActivatedModes();

    // then: erase is withheld (this is the #15173 boot-time spurious-erase bug)
    EXPECT_FALSE(IS_RC_MODE_ACTIVE(BOXBLACKBOXERASE));

    // when: switch goes off and the boot delay elapses
    rcData[AUX2] = PWM_RANGE_MIDDLE;
    fixedMillis = STICKY_MODE_BOOT_DELAY_US / 1000 + 1;
    updateActivatedModes();

    // then: still inactive, but the guard is now armed
    EXPECT_FALSE(IS_RC_MODE_ACTIVE(BOXBLACKBOXERASE));

    // when: switch is moved into range
    rcData[AUX2] = PWM_RANGE_MAX;
    updateActivatedModes();

    // then: mode activates normally
    EXPECT_TRUE(IS_RC_MODE_ACTIVE(BOXBLACKBOXERASE));

    // when: switch is moved back out of range
    rcData[AUX2] = PWM_RANGE_MIDDLE;
    updateActivatedModes();

    // then: unlike BOXPARALYZE, this must turn off again so blackboxUpdate() can
    // leave BLACKBOX_STATE_ERASED and resume normal logging
    EXPECT_FALSE(IS_RC_MODE_ACTIVE(BOXBLACKBOXERASE));
}

TEST(IoSerialTest, TestPassthroughEscape)
