bool rxMspIsRcChannelFresh(uint8_t chan)
{
    if (!rxMspRcFrameEverReceived) {
        return false;
    }
    if (chan >= lastRxMspRcFrameChannelCount) {
        return false;
    }
    return (millis() - lastRxMspRcFrameMs) <= RX_MSP_RC_FRAME_FRESH_MS;

TEST(MspOverrideTest, ChannelFreshness)
{
    // Before any frame is received, every channel is stale.
    simulationMillis = 1000;
    EXPECT_FALSE(rxMspIsRcChannelFresh(0));
    EXPECT_FALSE(rxMspIsRcChannelFresh(3));
    EXPECT_FALSE(rxMspIsRcChannelFresh(8));

    // A 4-channel (AETR-only) frame makes channels 0..3 fresh; AUX channels
    // beyond the frame's channelCount remain stale even though the frame
    // itself is current.
    uint16_t frame4[MAX_SUPPORTED_RC_CHANNEL_COUNT] = {1500, 1500, 1500, 1000};
    rxMspFrameReceive(frame4, 4);
    EXPECT_TRUE(rxMspIsRcChannelFresh(0));
    EXPECT_TRUE(rxMspIsRcChannelFresh(3));
    EXPECT_FALSE(rxMspIsRcChannelFresh(4));
    EXPECT_FALSE(rxMspIsRcChannelFresh(8));

    // Inside the freshness window: still fresh.
    simulationMillis = 1000 + 250;
    EXPECT_TRUE(rxMspIsRcChannelFresh(0));
    EXPECT_FALSE(rxMspIsRcChannelFresh(4));

    // A 6-channel frame extends freshness to AUX2 (channel 5).
    simulationMillis = 1500;
    uint16_t frame6[MAX_SUPPORTED_RC_CHANNEL_COUNT] = {1500, 1500, 1500, 1000, 2000, 1750};
    rxMspFrameReceive(frame6, 6);
    EXPECT_TRUE(rxMspIsRcChannelFresh(0));
    EXPECT_TRUE(rxMspIsRcChannelFresh(5));
    EXPECT_FALSE(rxMspIsRcChannelFresh(6));

    // Past the freshness window every channel becomes stale, regardless of
    // whether earlier frames had covered it.
    simulationMillis = 1500 + 301;
    EXPECT_FALSE(rxMspIsRcChannelFresh(0));
    EXPECT_FALSE(rxMspIsRcChannelFresh(5));

    // A subsequent shorter frame shrinks coverage: a previously-fresh AUX
    // channel must drop back to stale even while channels 0..3 stay fresh.
    simulationMillis = 2000;
    rxMspFrameReceive(frame4, 4);
    EXPECT_TRUE(rxMspIsRcChannelFresh(3));
    EXPECT_FALSE(rxMspIsRcChannelFresh(5));
}

TEST_BEGIN(test_thread_arena_resume_percpu) {
	test_skip_if(!have_percpu_arena
	    || !PERCPU_ARENA_ENABLED(opt_percpu_arena));

	unsigned limit = percpu_arena_ind_limit(opt_percpu_arena);
	/* Bypass the tcache so every allocation and free hits the arena. */
	const int flags = MALLOCX_TCACHE_NONE;

	void *warm = mallocx(1, 0);
	expect_ptr_not_null(warm, "Unexpected mallocx() failure");
	dallocx(warm, 0);

	unsigned cur;
	size_t sz = sizeof(cur);
	expect_d_eq(mallctl("thread.arena", (void *)&cur, &sz, NULL, 0), 0,
	    "Unexpected mallctl() failure");
	expect_u_lt(cur, limit, "Thread should start on a per-CPU arena");

	unsigned manual;
	sz = sizeof(manual);
	expect_d_eq(mallctl("arenas.create", (void *)&manual, &sz, NULL, 0), 0,
	    "Unexpected arenas.create() failure");
	expect_u_ge(manual, limit, "A manual arena is outside the per-CPU range");

	unsigned old;
	sz = sizeof(old);
	expect_d_eq(mallctl("thread.arena", (void *)&old, &sz, (void *)&manual,
	    sizeof(manual)), 0, "Binding to a manual arena should be allowed");
	sz = sizeof(cur);
	expect_d_eq(mallctl("thread.arena", (void *)&cur, &sz, NULL, 0), 0,
	    "Unexpected mallctl() failure");
	expect_u_eq(cur, manual, "Thread should be bound to the manual arena");

	void *p_manual = mallocx(1024, flags);
	expect_ptr_not_null(p_manual, "Unexpected mallocx() failure");
	unsigned found;
	sz = sizeof(found);
	expect_d_eq(mallctl("arenas.lookup", (void *)&found, &sz,
	    (void *)&p_manual, sizeof(p_manual)), 0,
	    "Unexpected arenas.lookup() failure");
	expect_u_eq(found, manual, "Allocation should come from the manual arena");

	void *scratch = mallocx(1024, flags);
	expect_ptr_not_null(scratch, "Unexpected mallocx() failure");
	dallocx(scratch, flags);

	unsigned resume = 0;
	expect_d_eq(mallctl("thread.arena", NULL, NULL, (void *)&resume,
	    sizeof(resume)), 0, "Should resume per-CPU selection, not fail");
	sz = sizeof(cur);
	expect_d_eq(mallctl("thread.arena", (void *)&cur, &sz, NULL, 0), 0,
	    "Unexpected mallctl() failure");
	expect_u_lt(cur, limit, "Thread should be back on a per-CPU arena");

	void *p_percpu = mallocx(1024, flags);
	expect_ptr_not_null(p_percpu, "Unexpected mallocx() failure");
	sz = sizeof(found);
	expect_d_eq(mallctl("arenas.lookup", (void *)&found, &sz,
	    (void *)&p_percpu, sizeof(p_percpu)), 0,
	    "Unexpected arenas.lookup() failure");
	expect_u_lt(found, limit, "Allocation should come from a per-CPU arena");
	dallocx(p_percpu, flags);

	/* Free the manual-arena region while bound to a different arena. */
	dallocx(p_manual, flags);
}

TEST_END

int
main(void) {
	return test(
	    test_thread_arena_resume_percpu);
}

void SetUp() override {
    // A single IO thread makes one blocked session destructor stall the whole scheduler.
    ANNOTATE_UNPROTECTED_WRITE(FLAGS_io_thread_pool_size) = 1;
    PgSharedMemTest::SetUp();
  }

TEST_F_EX(PgSharedMemTest, SessionShutdownBlocksScheduler, PgSharedMemSchedulerBlockTest) {
  auto conn = ASSERT_RESULT(Connect());
  ASSERT_OK(conn.Execute("CREATE TABLE t (key INT PRIMARY KEY) SPLIT INTO 1 TABLETS"));
  const auto backend_pid = ASSERT_RESULT(conn.FetchRow<int32_t>("SELECT pg_backend_pid()"));
  std::optional<PGConn> bystander = ASSERT_RESULT(Connect());

  auto* client_service =
      cluster_->mini_tablet_server(kPgTsIndex)->server()->TEST_GetPgClientService();
  const auto num_sessions = client_service->TEST_SessionsCount();

  ANNOTATE_UNPROTECTED_WRITE(FLAGS_TEST_transactional_read_delay_ms) = kReadDelayMs;
  auto reset_delay = ScopeExit([] {
    ANNOTATE_UNPROTECTED_WRITE(FLAGS_TEST_transactional_read_delay_ms) = 0;
  });

  // The INSERT makes the transaction real, so the SELECT takes the delayed transactional read
  // path: it hangs in the tserver keeping the shared exchange busy, and fails when the backend
  // is killed below.
  ASSERT_OK(conn.StartTransaction(IsolationLevel::SNAPSHOT_ISOLATION));
  ASSERT_OK(conn.Execute("INSERT INTO t VALUES (1)"));
  TestThreadHolder thread_holder;
  thread_holder.AddThreadFunctor([&conn] {
    ASSERT_NOK(conn.Fetch("SELECT * FROM t"));
  });
  // Let the read reach the tserver and mark the exchange busy.
  SleepFor(1s * kTimeMultiplier);

  ASSERT_EQ(kill(backend_pid, SIGKILL), 0);
  thread_holder.JoinAll();

  // The dead backend's session expires and its destructor runs on the scheduler IO thread.
  ASSERT_OK(WaitFor([client_service, num_sessions] {
    return client_service->TEST_SessionsCount() < num_sessions;
  }, 10s * kTimeMultiplier, "Killed backend session expired"));
  // Give the destructor time to start waiting on the busy exchange.
  SleepFor(2s * kTimeMultiplier);

  bystander.reset();
  ASSERT_OK(WaitFor([client_service, num_sessions] {
    return client_service->TEST_SessionsCount() <= num_sessions - 2;
  }, MonoDelta::FromMilliseconds(kReadDelayMs / 4), "Bystander session cleaned up"));
}

TEST_F(PgThinClientTest, ReplayOfReplicatedWriteWinsOverExpiredFence) {
  auto conn = ASSERT_RESULT(Connect());
  ASSERT_OK(conn.Execute(
      "CREATE TABLE dup_fenced (k int, v bytea, PRIMARY KEY(k ASC))"));

  const auto db_oid = ASSERT_RESULT(FetchOid(&conn, "SELECT oid FROM pg_database "
                                                     "WHERE datname = current_database()"));
  const auto table_oid = ASSERT_RESULT(FetchOid(&conn, "SELECT 'dup_fenced'::regclass::oid"));

  const auto addr = TServerAddr();
  const char* addrs[] = {addr.c_str()};
  ybthin_client* client = nullptr;
  {
    auto st = ybthin_client_create(
        addrs, 1, /* tls= */ nullptr, /* pool= */ nullptr, /* rpc_timeout_ms= */ 60000,
        /* num_reactors= */ 0, &client);
    ASSERT_EQ(st.code, YBTHIN_OK) << (st.message ? st.message : "");
  }
  ybthin_table* table = nullptr;
  ybthin_table_info info = {};
  {
    auto st = ybthin_table_open(client, db_oid, table_oid, &table, &info);
    ASSERT_EQ(st.code, YBTHIN_OK) << (st.message ? st.message : "");
  }
  const int32_t v_id = info.columns[1].id;

  // Wide enough that the first attempt is comfortably admitted even on a slow build, short enough
  // that the resend below arrives after it has passed.
  constexpr int kFenceDelaySec = 10;
  const auto fence = HybridTime::FromMicros(
      static_cast<uint64_t>(GetCurrentTimeMicros()) + kFenceDelaySec * 1000000ULL).ToPB();

  const std::string payload = "fenced-dup";
  ybthin_bind key[] = {I32(11)};
  ybthin_bind value[] = {Bytea(payload)};
  int32_t value_ids[] = {v_id};
  ybthin_upsert_row row = {table, key, 1, value_ids, value, 1, fence};

  std::promise<WriteOutcome> promise;
  auto future = promise.get_future();
  // Replicate the write inside its fence, then make the client believe it timed out so it keeps
  // resending the identical ops -- same retryable request id, same fence.
  ANNOTATE_UNPROTECTED_WRITE(FLAGS_TEST_asyncrpc_finished_set_timedout) = true;
  ybthin_upsert_batch_async(client, &row, 1, &OnWriteDone, &promise);
  // Hold the flag until the fence is well past, so the resend that gets through carries an
  // expired fence for an id the tablet has already replicated.
  SleepFor((kFenceDelaySec + 5) * 1s);
  ANNOTATE_UNPROTECTED_WRITE(FLAGS_TEST_asyncrpc_finished_set_timedout) = false;

  auto out = future.get();
  ASSERT_EQ(out.code, YBTHIN_OK)
      << "a replayed already-replicated write must report success even though its fence has "
      << "since passed; got: " << out.message;

  ASSERT_EQ(1, ASSERT_RESULT(conn.FetchRow<PGUint64>(
                   "SELECT count(*) FROM dup_fenced WHERE k = 11")));
  ASSERT_EQ(payload, ASSERT_RESULT(conn.FetchRow<std::string>(
                         "SELECT encode(v, 'escape') FROM dup_fenced WHERE k = 11")));

  ybthin_columns_free(info.columns, info.n_columns);
  ybthin_table_close(table);
  ybthin_client_destroy(client);
}

Status RaftConsensus::CheckWriteFenceUnlocked(const ConsensusRoundPtr& round) {
  const auto& msg = *round->replicate_msg();
  if (msg.op_type() != OperationType::WRITE_OP) {
    return Status::OK();
  }
  const auto fence = HybridTime::FromPB(msg.write().ignore_after_hybrid_time());
  if (!fence) {
    return Status::OK();
  }
  // clock_, not the op's own hybrid time, which AddLeaderPending has not assigned yet. Nor
  // state_->Clock(), which is the coarse clock and not in the fence's time domain.
  const auto now = clock_->Now();
  if (fence > now) {
    return Status::OK();
  }
  return STATUS_EC_FORMAT(
      Expired, tserver::TabletServerError(TabletServerErrorPB::WRITE_FENCE_EXPIRED),
      "Write is fenced: ignore_after_hybrid_time $0 is not after $1", fence, now);
}

TEST_F(PgThinClientTest, WriteFencedByIgnoreAfterHybridTime) {
  auto conn = ASSERT_RESULT(Connect());
  ASSERT_OK(conn.Execute("CREATE TABLE fenced (k int, v bytea, PRIMARY KEY(k ASC))"));

  const auto db_oid = ASSERT_RESULT(FetchOid(&conn, "SELECT oid FROM pg_database "
                                                     "WHERE datname = current_database()"));
  const auto table_oid = ASSERT_RESULT(FetchOid(&conn, "SELECT 'fenced'::regclass::oid"));

  const auto addr = TServerAddr();
  const char* addrs[] = {addr.c_str()};
  ybthin_client* client = nullptr;
  {
    auto st = ybthin_client_create(
        addrs, 1, /* tls= */ nullptr, /* pool= */ nullptr, /* rpc_timeout_ms= */ 60000,
        /* num_reactors= */ 0, &client);
    ASSERT_EQ(st.code, YBTHIN_OK) << (st.message ? st.message : "");
  }
  ybthin_table* table = nullptr;
  ybthin_table_info info = {};
  {
    auto st = ybthin_table_open(client, db_oid, table_oid, &table, &info);
    ASSERT_EQ(st.code, YBTHIN_OK) << (st.message ? st.message : "");
  }
  const int32_t v_id = info.columns[1].id;

  const std::string payload = "fence";
  int32_t value_ids[] = {v_id};

  auto upsert = [&](int32_t k, uint64_t fence) -> ybthin_status_code {
    ybthin_bind key[] = {I32(k)};
    ybthin_bind value[] = {Bytea(payload)};
    ybthin_upsert_row row = {table, key, 1, value_ids, value, 1, fence};
    std::promise<WriteOutcome> promise;
    auto future = promise.get_future();
    ybthin_upsert_batch_async(client, &row, 1, &OnWriteDone, &promise);
    return future.get().code;
  };

  // HybridTime 1 is behind any clock reading the leader can take.
  ASSERT_EQ(upsert(1, 1), YBTHIN_FENCED) << "a write past its fence must be rejected";
  ASSERT_EQ(0, ASSERT_RESULT(conn.FetchRow<PGUint64>(
                   "SELECT count(*) FROM fenced WHERE k = 1")))
      << "a fenced write must not take effect";

  // Compared against the leader's clock, so it has to be a hybrid time, not a micro count.
  const auto far_future = HybridTime::FromMicros(
      static_cast<uint64_t>(GetCurrentTimeMicros()) + 3600 * 1000000ULL).ToPB();
  ASSERT_EQ(upsert(2, far_future), YBTHIN_OK) << "a write inside its fence must be applied";
  ASSERT_EQ(1, ASSERT_RESULT(conn.FetchRow<PGUint64>(
                   "SELECT count(*) FROM fenced WHERE k = 2")));

  // No fence at all behaves as before.
  ASSERT_EQ(upsert(3, 0), YBTHIN_OK);
  ASSERT_EQ(1, ASSERT_RESULT(conn.FetchRow<PGUint64>(
                   "SELECT count(*) FROM fenced WHERE k = 3")));

  // A leaked entry from the fenced round at k = 1 never drains, so this would never hold. Waiting
  // rather than sampling absorbs the cluster's unrelated background writes.
  ASSERT_OK(WaitFor(
      [this]() -> Result<bool> {
        for (const auto& peer : ListTabletPeers(cluster_.get(), ListPeersFilter::kAll)) {
          auto raft_consensus = VERIFY_RESULT(peer->GetRaftConsensus());
          if (raft_consensus->TEST_CountRetryableRequests().running != 0) {
            return false;
          }
        }
        return true;
      },
      10s, "fenced write left a retryable-request registration behind"));

  ybthin_columns_free(info.columns, info.n_columns);
  ybthin_table_close(table);
  ybthin_client_destroy(client);
}

TEST_F(FsManagerTestBase, DuplicateTabletMetadataFailsStartupTabletEnumeration) {
  const string wal_path = GetTestPath("wal");
  const string data_path_1 = GetTestPath("data1");
  const string data_path_2 = GetTestPath("data2");
  ReinitFsManager({ wal_path }, { data_path_1, data_path_2 });
  ASSERT_OK(fs_manager()->CreateInitialFileSystemLayout());

  const auto meta_dirs = fs_manager()->GetRaftGroupMetadataDirs();
  ASSERT_EQ(2, meta_dirs.size());
  const char* const kTabletId = "0123456789abcdef0123456789abcdef";
  for (const auto& dir : meta_dirs) {
    std::unique_ptr<WritableFile> writer;
    ASSERT_OK(env_->NewWritableFile(JoinPathSegments(dir, kTabletId), &writer));
  }

  const auto result = fs_manager()->ListTabletIds(CleanupTemporaryFiles::kFalse);
  ASSERT_NOK(result);
  ASSERT_TRUE(result.status().IsIllegalState()) << result.status();
  ASSERT_STR_CONTAINS(result.status().ToString(), "Remove the duplicate one");
}

Result<std::map<std::string, std::vector<std::string>>> FsManager::ListTabletIdsByRoot() {
  RETURN_NOT_OK(Init());

  std::map<std::string, std::vector<std::string>> result;
  for (const string& root : canonicalized_data_fs_roots_) {
    auto& ids = result[root];
    const auto dir = GetRaftGroupMetadataDir(GetServerTypeDataPath(root, server_type_));
    if (!env_->FileExists(dir)) {
      // A root that has never held tablets. Not an error; it is the zero-superblock case of the
      // pin decision.
      continue;
    }
    std::vector<std::string> children = VERIFY_RESULT_PREPEND(
        ListDir(dir), Substitute("Couldn't list tablets in metadata directory $0", dir));
    for (const auto& child : children) {
      // Pass a null Env so that temp files are ignored rather than deleted: this path must stay
      // read-only, it is what the offline survey runs.
      if (!CheckTabletId(/* env = */ nullptr, dir, child)) {
        continue;
      }
      ids.push_back(child);
    }
    std::sort(ids.begin(), ids.end());
  }
  return result;
}

Result<FsRootPinReport> FsManager::SurveyDataRoots(
    const std::vector<TabletSuperblockEvidence>& evidence,
    FsRootEvidenceComplete evidence_complete) {
  RETURN_NOT_OK(Init());

  FsRootPinInputs inputs;
  inputs.server_type = server_type_;
  inputs.data_roots = canonicalized_data_fs_roots_;
  inputs.wal_roots = canonicalized_wal_fs_roots_;
  inputs.evidence = evidence;
  inputs.evidence_complete = evidence_complete;
  inputs.dropped_roots = dropped_fs_roots_;

  for (const string& root : canonicalized_data_fs_roots_) {
    inputs.pin_files[root] = ReadFsRootPinFile(env_, GetFsRootPinPath(root));

    // Classify the root by its instance file, exactly as CheckAndOpenFileSystemRoots does, so that
    // the offline survey reaches the same conclusions as the server. Reading the protobuf rather
    // than stat-ing it matters: in one field incident a node's instance file was present but
    // failed its checksum, which is a read corruption that any existence check would miss.
    InstanceMetadataPB instance;
    const auto read_result =
        pb_util::ReadPBContainerFromPath(env_, GetInstanceMetadataPath(root), &instance);
    if (read_result.IsNotFound()) {
      // Ways a root can look like this: a node that has never been formatted -- normal, and the
      // case where every root looks like this; a blank replacement volume at an existing mount
      // point, which is what the adoption path in CreateFileSystemRoots() exists for; a root newly
      // added to --fs_data_dirs; or a volume that did not mount, which presents as an empty
      // directory on the root filesystem and would otherwise pass as "a root with no tablets".
      // EvaluateFsRootPins separates the never-formatted node from the rest by whether any sibling
      // is formatted. Nothing on disk separates the rest from each other, which is why
      // kUnformatted only ever warns.
      inputs.unformatted_roots.insert(root);
    } else if (!read_result.ok()) {
      // The server would drop this root and run without it, so the tablets on it are invisible to
      // everything downstream. Say so rather than report a clean node.
      inputs.dropped_roots.insert(root);
    }
  }

  inputs.likely_unmounted_roots = RootsLikelyUnmounted(canonicalized_data_fs_roots_);

  return EvaluateFsRootPins(inputs);
}

std::set<string> FsManager::RootsLikelyUnmounted(const std::set<string>& roots) {
  // A data root whose volume failed to mount is a real, usually empty, directory sitting on the
  // root filesystem. From inside the process that is visible as st_dev matching "/" - the same
  // device identity the pin file's filesystem-UUID probe goes by.
  //
  // Only meaningful as a *relative* signal, and only ever used to word a warning more sharply:
  // a single-drive node, a bind mount, and most container layouts all legitimately put data roots
  // on the root device, so this must not gate anything.
  struct stat root_fs_stat;
  if (stat("/", &root_fs_stat) != 0) {
    return {};
  }

  std::set<string> on_root_fs;
  size_t stat_failures = 0;
  for (const auto& root : roots) {
    struct stat root_stat;
    if (stat(root.c_str(), &root_stat) != 0) {
      ++stat_failures;
      continue;
    }
    if (root_stat.st_dev == root_fs_stat.st_dev) {
      on_root_fs.insert(root);
    }
  }
  // A root we could not stat is unknown, not evidence either way. What makes this signal
  // meaningful is a split among the roots we could see: at least one on the root device and at
  // least one demonstrably not. All known roots on the root device, or none of them, tells us
  // nothing: that is a single-drive node, an all-container layout, or a total mount failure.
  const size_t known = roots.size() - stat_failures;
  if (on_root_fs.empty() || on_root_fs.size() == known) {
    return {};
  }
  return on_root_fs;
}

Status FsManager::ApplyFsRootPinReport(const FsRootPinReport& report, bool may_write) {
  const auto policy = FsRootPinPolicyFromFlags();

  // Emitted whenever there is warning-level content, not only when warning is the report's *top*
  // severity. Do not "simplify" this to HasWarnings(): that is `Severity() == kWarning` exactly,
  // so it goes false the moment any root also fails - the case where the operator most needs the
  // whole picture. Concretely: with /mnt/d0 swapped and /mnt/d2's volume not mounted, the refusal
  // would name d0 and say nothing about d2, so remounting d0 and restarting would let d2 be
  // adopted as a fresh empty root.
  const auto warnings = report.WarningMessage();
  if (!warnings.empty()) {
    LOG(WARNING) << "Data volume layout anomalies that do not by themselves refuse startup:\n"
                 << warnings;
  }

  if (report.HasFailure()) {
    const auto message = report.FailureMessage();
    if (report.ShouldRefuseStartup(policy)) {
      // LOG_AND_RETURN_FROM_MAIN_NOT_OK turns this into a single aggregated FATAL. Deliberately not
      // a per-tablet FATAL and not a restart loop: the operator needs one message naming every
      // affected root, once.
      return STATUS(
          IllegalState, message + "\nRefusing to start until the mounts are corrected.\n");
    }
    // Configured to tolerate this one. Log the identical diagnosis so the evidence is in the log
    // either way, and fall through -- but not to the pin writes, see below.
    LOG(ERROR) << "Starting anyway, per --fs_root_pin_enforce / "
               << "--fs_root_pin_refuse_on_superblock_conflict, despite:" << message;
  }

  // Never record new state on a node we have just diagnosed as wrong, whatever the policy says
  // about refusing. Certification is evidence-gated and so is safe in isolation, but a report with
  // a failure in it is not a picture we should be adding to.
  if (!may_write || read_only_ || !policy.write_pins || report.HasFailure()) {
    return Status::OK();
  }

  for (const auto& root : report.CertifiableRoots()) {
    const auto pin = FsRootPin::ForMountPoint(root);
    const auto pin_path = GetFsRootPinPath(root);
    RETURN_NOT_OK_PREPEND(
        WriteFsRootPinFile(env_, pin_path, pin),
        Substitute("Unable to pin data root $0", root));
    const auto* verdict = report.FindRoot(root);
    LOG(INFO) << "Pinned data root " << root << " at " << pin_path << " (filesystem UUID "
              << (pin.filesystem_uuid.empty() ? "unknown" : pin.filesystem_uuid)
              << ", certified by " << (verdict ? verdict->superblocks_with_evidence : 0)
              << " tablet superblocks)";
  }
  return Status::OK();
}

Status FsManager::VerifyExistingDataRootPins() {
  // Tablets have not been enumerated at this point, so unpinned roots come back kPending and are
  // left for CertifyDataRoots(). Everything that can be decided from the pin files alone -- the
  // common case, and the cheapest one -- is decided here, before anything else runs.
  auto report = VERIFY_RESULT(SurveyDataRoots({}, FsRootEvidenceComplete::kFalse));

  if (report.HasFailure()) {
    // Only on the failure path, and only a directory listing: tell the operator how much data is
    // on each affected root. We cannot say which tablets disagree here -- that needs the parsed
    // superblocks, which live a layer up -- but "412 tablet superblocks under this root" is what
    // turns an abstract path complaint into something an operator can act on.
    auto ids_by_root = ListTabletIdsByRoot();
    if (ids_by_root.ok()) {
      for (auto& verdict : report.verdicts) {
        auto it = ids_by_root->find(verdict.root);
        if (it != ids_by_root->end()) {
          verdict.superblocks_seen = it->second.size();
        }
      }
    } else {
      LOG(WARNING) << "Could not count tablets per data root for the failure message: "
                   << ids_by_root.status();
    }
  }

  return ApplyFsRootPinReport(report, /* may_write = */ false);
}

Status FsManager::CertifyDataRoots(const std::vector<TabletSuperblockEvidence>& evidence) {
  auto report = VERIFY_RESULT(SurveyDataRoots(evidence, FsRootEvidenceComplete::kTrue));
  RETURN_NOT_OK(ApplyFsRootPinReport(report, /* may_write = */ true));
  LOG(INFO) << report.SummaryLine();
  return Status::OK();
}

TabletSuperblockEvidence Evidence(
    const string& tablet_id, const string& found_under, const string& recorded_data,
    const string& recorded_wal = "") {
  TabletSuperblockEvidence e;
  e.tablet_id = tablet_id;
  e.containing_root = found_under;
  e.recorded_data_root = recorded_data;
  e.recorded_wal_root = recorded_wal.empty() ? recorded_data : recorded_wal;
  return e;
}

TabletSuperblockEvidence UnreadableSuperblock(
    const string& tablet_id, const string& found_under, const string& error) {
  TabletSuperblockEvidence e;
  e.tablet_id = tablet_id;
  e.containing_root = found_under;
  e.read_error = error;
  return e;
}

FsRootPinFile PresentPin(const string& mount_point) {
  FsRootPinFile f;
  f.state = FsRootPinFileState::kPresent;
  f.pin.mount_point = mount_point;
  f.pin.pinned_at = "2026-07-29T18:22:04Z";
  f.pin.filesystem_uuid = "b3f2a41c-9d0e-4c77-8a15-2e6f0c9d1b44";
  return f;
}

FsRootPinFile UnreadablePin(const string& error) {
  FsRootPinFile f;
  f.state = FsRootPinFileState::kUnparseable;
  f.error = error;
  return f;
}

FsRootPinFile IoErrorPin(const string& error) {
  FsRootPinFile f;
  f.state = FsRootPinFileState::kIoError;
  f.error = error;
  return f;
}

FsRootState StateOf(const FsRootPinReport& report, const string& root) {
  const auto* v = report.FindRoot(root);
  EXPECT_NE(v, nullptr) << "no verdict for root " << root;
  return v ? v->state : FsRootState::kPending;
}

FsRootRepinDecision RepinOf(const FsRootPinReport& report, const string& root) {
  const auto* v = report.FindRoot(root);
  EXPECT_NE(v, nullptr) << "no verdict for root " << root;
  return v ? DecideRepin(*v) : FsRootRepinDecision::kNotNeeded;
}

FsRootPinStartupPolicy StrictPolicy() {
  FsRootPinStartupPolicy p;
  p.refuse_on_superblock_conflict = true;
  return p;
}

FsRootPinStartupPolicy WarnOnlyPolicy() {
  FsRootPinStartupPolicy p;
  p.refuse_on_pin_mismatch = false;
  return p;
}

FsRootPinInputs TwoRoots() {
    FsRootPinInputs inputs;
    inputs.server_type = kServerType;
    inputs.data_roots = {kD0, kD1};
    inputs.wal_roots = {kD0, kD1};
    inputs.evidence_complete = FsRootEvidenceComplete::kTrue;
    return inputs;
  }

TEST_F(FsRootPinDecisionTest, PinMatchesProceeds) {
  auto inputs = TwoRoots();
  inputs.pin_files[kD0] = PresentPin(kD0);
  inputs.pin_files[kD1] = PresentPin(kD1);
  inputs.evidence = {Evidence("t1", kD0, kD0), Evidence("t2", kD1, kD1)};

  auto report = EvaluateFsRootPins(inputs);
  ASSERT_EQ(FsRootState::kVerified, StateOf(report, kD0));
  ASSERT_EQ(FsRootState::kVerified, StateOf(report, kD1));
  ASSERT_FALSE(report.HasFailure());
  ASSERT_FALSE(report.HasWarnings());
  ASSERT_TRUE(report.FailureMessage().empty());
  ASSERT_TRUE(report.CertifiableRoots().empty());
}

TEST_F(FsRootPinDecisionTest, SwappedMountsRefuseNamingBoth) {
  auto inputs = TwoRoots();
  inputs.pin_files[kD0] = PresentPin(kD1);  // The volume at /mnt/d0 was pinned at /mnt/d1.
  inputs.pin_files[kD1] = PresentPin(kD0);
  inputs.evidence = {Evidence("t1", kD0, kD1), Evidence("t2", kD1, kD0)};

  auto report = EvaluateFsRootPins(inputs);
  ASSERT_EQ(FsRootState::kMismatched, StateOf(report, kD0));
  ASSERT_EQ(FsRootState::kMismatched, StateOf(report, kD1));
  ASSERT_TRUE(report.HasFailure());
  // Nothing is written on a refusal, however consistent the rest of the node looks.
  ASSERT_TRUE(report.CertifiableRoots().empty());

  const auto message = report.FailureMessage();
  ASSERT_STR_CONTAINS(message, "/mnt/d0 holds the volume pinned at /mnt/d1");
  ASSERT_STR_CONTAINS(message, "/mnt/d1 holds the volume pinned at /mnt/d0");
  ASSERT_STR_CONTAINS(message, "/mnt/d0 and /mnt/d1 appear to be swapped.");
  ASSERT_STR_CONTAINS(message, "No data has been lost");
  ASSERT_STR_CONTAINS(message, "Do not delete anything");
}

TEST_F(FsRootPinDecisionTest, WarningsSurviveAlongsideAFailure) {
  FsRootPinInputs inputs;
  inputs.server_type = kServerType;
  inputs.data_roots = {"/mnt/d0", "/mnt/d1", "/mnt/d2"};
  inputs.wal_roots = inputs.data_roots;
  inputs.evidence_complete = FsRootEvidenceComplete::kTrue;
  inputs.pin_files["/mnt/d0"] = PresentPin("/mnt/d1");   // failure: mismatched
  inputs.pin_files["/mnt/d1"] = PresentPin("/mnt/d1");   // fine
  inputs.unformatted_roots = {"/mnt/d2"};                // warning: no instance file

  auto report = EvaluateFsRootPins(inputs);
  ASSERT_TRUE(report.HasFailure());
  // Top severity is failure, so HasWarnings() (which is Severity() == kWarning exactly) is false
  // here. A caller gating warning output on it would drop the warning text entirely.
  ASSERT_FALSE(report.HasWarnings());

  ASSERT_STR_CONTAINS(report.FailureMessage(), "/mnt/d0 holds the volume pinned at /mnt/d1");

  const auto warnings = report.WarningMessage();
  ASSERT_FALSE(warnings.empty()) << "warning content must survive a failing sibling";
  ASSERT_STR_CONTAINS(warnings, "/mnt/d2 has no instance file");
  // And it must say what is about to happen to it, not only what was seen.
  ASSERT_STR_CONTAINS(warnings, "adopted as a new, empty data directory");
}

TEST_F(FsRootPinDecisionTest, UnformattedRootOnRootFilesystemSaysSo) {
  auto inputs = TwoRoots();
  inputs.pin_files[kD0] = PresentPin(kD0);
  inputs.unformatted_roots = {kD1};
  inputs.likely_unmounted_roots = {kD1};

  auto report = EvaluateFsRootPins(inputs);
  ASSERT_EQ(FsRootState::kUnformatted, StateOf(report, kD1));
  ASSERT_STR_CONTAINS(report.WarningMessage(), "same device as / while its sibling data roots");

  // Without the hint the warning stays generic rather than inventing the diagnosis.
  inputs.likely_unmounted_roots.clear();
  auto quiet = EvaluateFsRootPins(inputs);
  ASSERT_STR_NOT_CONTAINS(quiet.WarningMessage(), "same device as /");
  ASSERT_STR_CONTAINS(quiet.WarningMessage(), "/mnt/d1 has no instance file");
}

TEST_F(FsRootPinDecisionTest, MismatchThatIsNotASwapDoesNotClaimOne) {
  auto inputs = TwoRoots();
  inputs.pin_files[kD0] = PresentPin("/mnt/d7");
  inputs.pin_files[kD1] = PresentPin(kD1);

  auto report = EvaluateFsRootPins(inputs);
  ASSERT_TRUE(report.HasFailure());
  const auto message = report.FailureMessage();
  ASSERT_STR_CONTAINS(message, "/mnt/d0 holds the volume pinned at /mnt/d7");
  ASSERT_STR_NOT_CONTAINS(message, "appear to be swapped");
}

TEST_F(FsRootPinDecisionTest, ThreeWayRotationIsReportedAsSuch) {
  FsRootPinInputs inputs;
  inputs.server_type = kServerType;
  inputs.data_roots = {"/mnt/d0", "/mnt/d1", "/mnt/d2"};
  inputs.wal_roots = inputs.data_roots;
  inputs.evidence_complete = FsRootEvidenceComplete::kTrue;
  inputs.pin_files["/mnt/d0"] = PresentPin("/mnt/d1");
  inputs.pin_files["/mnt/d1"] = PresentPin("/mnt/d2");
  inputs.pin_files["/mnt/d2"] = PresentPin("/mnt/d0");

  auto report = EvaluateFsRootPins(inputs);
  ASSERT_TRUE(report.HasFailure());
  ASSERT_STR_CONTAINS(
      report.FailureMessage(), "remounted onto each other's mount points");
}

TEST_F(FsRootPinDecisionTest, UnreadablePinRefusesAndIsNotTreatedAsAbsent) {
  auto inputs = TwoRoots();
  inputs.pin_files[kD0] = UnreadablePin("not valid JSON: Missing a closing quotation mark");
  inputs.pin_files[kD1] = PresentPin(kD1);
  // Evidence that would otherwise certify /mnt/d0 happily.
  inputs.evidence = {Evidence("t1", kD0, kD0), Evidence("t2", kD1, kD1)};

  auto report = EvaluateFsRootPins(inputs);
  ASSERT_EQ(FsRootState::kPinUnparseable, StateOf(report, kD0));
  ASSERT_TRUE(report.HasFailure());
  ASSERT_TRUE(report.CertifiableRoots().empty());
  ASSERT_STR_CONTAINS(report.FailureMessage(), "pin file whose contents are unusable");
  ASSERT_STR_CONTAINS(report.FailureMessage(), "Missing a closing quotation mark");

  // The evidence still says the data belongs here, so the corrupt pin is repairable in place.
  ASSERT_EQ(FsRootRepinDecision::kSafe, RepinOf(report, kD0));
}

TEST_F(FsRootPinDecisionTest, ConsistentSuperblocksCertify) {
  auto inputs = TwoRoots();
  inputs.evidence = {
      Evidence("t1", kD0, kD0), Evidence("t2", kD0, kD0), Evidence("t3", kD1, kD1)};

  auto report = EvaluateFsRootPins(inputs);
  ASSERT_EQ(FsRootState::kCertifiable, StateOf(report, kD0));
  ASSERT_EQ(FsRootState::kCertifiable, StateOf(report, kD1));
  ASSERT_FALSE(report.HasFailure());
  ASSERT_EQ(vector<string>({kD0, kD1}), report.CertifiableRoots());
}

TEST_F(FsRootPinDecisionTest, OneInconsistentSuperblockRefusesAndPinsNothing) {
  auto inputs = TwoRoots();
  inputs.evidence = {
      Evidence("tablet_aaa", kD0, kD0),
      Evidence("tablet_bbb", kD0, kD1),  // Found under d0, superblock says d1.
      Evidence("tablet_ccc", kD1, kD1)};

  auto report = EvaluateFsRootPins(inputs);
  ASSERT_EQ(FsRootState::kEvidenceConflict, StateOf(report, kD0));
  ASSERT_EQ(FsRootState::kCertifiable, StateOf(report, kD1));
  ASSERT_TRUE(report.HasFailure());

  // Which tablet's metadata is not agreeing, and what it says.
  const auto* v = report.FindRoot(kD0);
  ASSERT_ONLY_NOTNULL(v);
  ASSERT_EQ(1, v->disagreeing_superblocks.size());
  ASSERT_EQ("tablet_bbb", v->disagreeing_superblocks[0].tablet_id);
  ASSERT_EQ(kD1, v->disagreeing_superblocks[0].recorded_data_root);
  ASSERT_EQ(kD0, v->disagreeing_superblocks[0].containing_root);
  ASSERT_EQ(2, v->superblocks_seen);
  ASSERT_EQ(2, v->superblocks_with_evidence);

  const auto message = report.FailureMessage();
  ASSERT_STR_CONTAINS(message, "tablet tablet_bbb: superblock says /mnt/d1, found under /mnt/d0");
  ASSERT_STR_CONTAINS(message, "1 of 2 tablet superblocks under it record a different data root");
  ASSERT_STR_CONTAINS(message, "Not writing a pin");
}

TEST_F(FsRootPinDecisionTest, ZeroTabletRootStaysUncertified) {
  auto inputs = TwoRoots();
  inputs.evidence = {Evidence("t1", kD0, kD0)};  // Nothing under /mnt/d1 at all.

  auto report = EvaluateFsRootPins(inputs);
  ASSERT_EQ(FsRootState::kCertifiable, StateOf(report, kD0));
  ASSERT_EQ(FsRootState::kUncertified, StateOf(report, kD1));
  ASSERT_FALSE(report.HasFailure());
  ASSERT_EQ(vector<string>({kD0}), report.CertifiableRoots());
}

