TEST_F(FsRootPinManagerTest, SuperblockPathShapesNormalizeToTheFsRoot) {
  auto fs = OpenFsManager();

  const auto data_root = fs->GetDataRootDirs()[0];      // <root>/yb-data/<server>/data
  const auto wal_root = fs->GetWalRootDirs()[0];        // <root>/yb-data/<server>/wals
  const auto rocksdb_dir = JoinPathSegments(
      data_root, FsManager::kRocksDBDirName, "table-abc", "tablet-def");
  const auto wal_dir = JoinPathSegments(wal_root, "table-abc", "tablet-def");

  // data_root_dir() and wal_root_dir() strip back to these two, and GetTabletPath() yields the
  // server data path. All three must land on the same fs root.
  const auto expected = FsRootOfYbDataPath(data_root);
  ASSERT_FALSE(expected.empty());
  ASSERT_EQ(expected, FsRootOfYbDataPath(data_root));
  ASSERT_EQ(expected, FsRootOfYbDataPath(wal_root));
  ASSERT_EQ(expected, FsRootOfYbDataPath(rocksdb_dir));
  ASSERT_EQ(expected, FsRootOfYbDataPath(wal_dir));
  ASSERT_EQ(expected, FsRootOfYbDataPath(GetServerTypeDataPath(expected, kServerType)));

  // And it is one of the roots the manager is actually configured with.
  ASSERT_TRUE(expected == root_a_ || expected == root_b_) << expected;
}

std::string NowIso8601Utc() {
  const time_t now = time(nullptr);
  struct tm tm_utc;
  if (gmtime_r(&now, &tm_utc) == nullptr) {
    return std::string();
  }
  char buf[32];
  if (strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
    return std::string();
  }
  return std::string(buf);
}

std::string ResolveFilesystemUuid(const std::string& path) {
#ifdef __linux__
  // Best effort, and quietly gives up on any error: this value is a breadcrumb for an operator
  // matching the failure message to a device, and never gates anything. /dev/disk/by-uuid is not
  // mounted in most container deployments, so an empty result is the common case there.
  struct stat path_stat;
  if (stat(path.c_str(), &path_stat) != 0) {
    return std::string();
  }

  static constexpr const char* kByUuidDir = "/dev/disk/by-uuid";
  DIR* dir = opendir(kByUuidDir);
  if (dir == nullptr) {
    return std::string();
  }

  std::string result;
  struct dirent* entry = nullptr;
  while ((entry = readdir(dir)) != nullptr) {
    if (entry->d_name[0] == '.') {
      continue;
    }
    const std::string link = JoinPathSegments(kByUuidDir, entry->d_name);
    struct stat dev_stat;
    // stat() follows the symlink to the device node, whose st_rdev is the device id that the
    // mounted filesystem reports as st_dev.
    if (stat(link.c_str(), &dev_stat) != 0) {
      continue;
    }
    if (S_ISBLK(dev_stat.st_mode) && dev_stat.st_rdev == path_stat.st_dev) {
      result = entry->d_name;
      break;
    }
  }
  closedir(dir);
  return result;
#else
  return std::string();
#endif
}

std::string ReadStringField(const rapidjson::Value& obj, const char* name) {
  auto it = obj.FindMember(name);
  if (it == obj.MemberEnd() || !it->value.IsString()) {
    return std::string();
  }
  return std::string(it->value.GetString(), it->value.GetStringLength());
}

bool MountsPermutedAmongThemselves(const std::vector<const FsRootVerdict*>& mismatched) {
  if (mismatched.size() < 2) {
    return false;
  }
  std::set<std::string> roots;
  for (const auto* v : mismatched) {
    roots.insert(v->root);
  }
  std::set<std::string> targets;
  for (const auto* v : mismatched) {
    if (roots.find(v->pin.mount_point) == roots.end()) {
      return false;
    }
    if (!targets.insert(v->pin.mount_point).second) {
      return false;
    }
  }
  return targets.size() == roots.size();
}

void AppendTabletLines(
    const std::vector<TabletSuperblockEvidence>& tablets, std::ostringstream* out) {
  const size_t shown = std::min(tablets.size(), kMaxTabletsInMessage);
  for (size_t i = 0; i < shown; ++i) {
    const auto& t = tablets[i];
    *out << "      tablet " << t.tablet_id << ": superblock says " << t.recorded_data_root
         << ", found under " << t.containing_root << "\n";
  }
  if (tablets.size() > shown) {
    *out << "      (and " << (tablets.size() - shown) << " more, not shown)\n";
  }
}

void AppendSideAnomalies(const FsRootVerdict& v, const char* indent, std::ostringstream* out) {
  if (!v.unreadable_superblocks.empty()) {
    *out << indent << Plural(v.unreadable_superblocks.size(), "tablet superblock") << " under "
         << v.root << " could not be read, so they are not evidence of anything:\n";
    const size_t shown = std::min(v.unreadable_superblocks.size(), kMaxTabletsInMessage);
    for (size_t i = 0; i < shown; ++i) {
      *out << indent << "    tablet " << v.unreadable_superblocks[i].tablet_id << ": "
           << v.unreadable_superblocks[i].read_error << "\n";
    }
    if (v.unreadable_superblocks.size() > shown) {
      *out << indent << "    (and " << (v.unreadable_superblocks.size() - shown) << " more)\n";
    }
  }
  if (!v.unknown_wal_root_superblocks.empty()) {
    *out << indent << v.root << ": "
         << Plural(v.unknown_wal_root_superblocks.size(), "tablet superblock")
         << " record a WAL root that is not in --fs_wal_dirs\n";
  }
}

std::string FsRootPin::ToJson() const {
  std::stringstream ss;
  JsonWriter w(&ss, JsonWriter::PRETTY);
  w.StartObject();
  w.String("mount_point");
  w.String(mount_point);
  w.String("pinned_at");
  w.String(pinned_at);
  if (!filesystem_uuid.empty()) {
    w.String("filesystem_uuid");
    w.String(filesystem_uuid);
  }
  w.EndObject();
  // A trailing newline so `cat` output is not glued to the shell prompt. JSON parsers ignore it.
  return ss.str() + "\n";
}

Result<FsRootPin> FsRootPin::ParseJson(const std::string& json) {
  rapidjson::Document doc;
  // Length-delimited, so an embedded NUL is seen as the corruption it is rather than silently
  // truncating the document at it.
  doc.Parse(json.data(), json.size());
  if (doc.HasParseError()) {
    return STATUS_FORMAT(
        Corruption, "not valid JSON: $0 (at offset $1)",
        rapidjson::GetParseError_En(doc.GetParseError()), doc.GetErrorOffset());
  }
  if (!doc.IsObject()) {
    return STATUS(Corruption, "not a JSON object");
  }

  FsRootPin pin;
  pin.mount_point = ReadStringField(doc, "mount_point");
  pin.pinned_at = ReadStringField(doc, "pinned_at");
  pin.filesystem_uuid = ReadStringField(doc, "filesystem_uuid");

  // mount_point is the only field that gates startup, so it is the only one we insist on. A pin
  // without it tells us nothing, and treating it as absent would let the next start re-certify
  // whatever layout happens to be current.
  if (pin.mount_point.empty()) {
    return STATUS(Corruption, "\"mount_point\" is missing, empty, or not a string");
  }
  if (pin.mount_point[0] != '/') {
    return STATUS_FORMAT(
        Corruption, "\"mount_point\" is not an absolute path: $0", pin.mount_point);
  }
  return pin;
}

FsRootPin FsRootPin::ForMountPoint(const std::string& mount_point) {
  FsRootPin pin;
  pin.mount_point = mount_point;
  pin.pinned_at = NowIso8601Utc();
  pin.filesystem_uuid = ResolveFilesystemUuid(mount_point);
  return pin;
}

FsRootSeverity FsRootVerdict::Severity() const {
  switch (state) {
    case FsRootState::kMismatched:
    case FsRootState::kPinUnparseable:
    case FsRootState::kEvidenceConflict:
      return FsRootSeverity::kFailure;

    case FsRootState::kPinIoError:
    case FsRootState::kUnformatted:
      return FsRootSeverity::kWarning;

    case FsRootState::kVerified:
    case FsRootState::kCertifiable:
    case FsRootState::kUncertified:
    case FsRootState::kPending:
      // A superblock naming another root under a root whose pin matches is not a swap -- the pin
      // proves the volume did not move -- but something moved a tablet directory by hand and those
      // tablets will not find their data.
      if (!disagreeing_superblocks.empty() || HasSideAnomalies(*this)) {
        return FsRootSeverity::kWarning;
      }
      return FsRootSeverity::kOk;
  }
  return FsRootSeverity::kOk;
}

FsRootPinStartupPolicy FsRootPinPolicyFromFlags() {
  FsRootPinStartupPolicy policy;
  policy.refuse_on_pin_mismatch = FLAGS_fs_root_pin_enforce;
  // --fs_root_pin_enforce is the master refusal switch: with it off, warn-only mode tolerates
  // everything, a superblock conflict included.
  policy.refuse_on_superblock_conflict =
      FLAGS_fs_root_pin_enforce && FLAGS_fs_root_pin_refuse_on_superblock_conflict;
  policy.write_pins = FLAGS_fs_root_pin_write;
  return policy;
}

bool RefusesUnder(const FsRootVerdict& verdict, const FsRootPinStartupPolicy& policy) {
  switch (verdict.state) {
    case FsRootState::kMismatched:
    case FsRootState::kPinUnparseable:
      // A pin this feature wrote on an earlier boot disagrees with reality. This cannot fire on a
      // first upgrade, so enforcing it costs nothing that was not already broken.
      return policy.refuse_on_pin_mismatch;

    case FsRootState::kEvidenceConflict:
      return policy.refuse_on_superblock_conflict;

    case FsRootState::kPinIoError:
    case FsRootState::kUnformatted:
    case FsRootState::kVerified:
    case FsRootState::kCertifiable:
    case FsRootState::kUncertified:
    case FsRootState::kPending:
      return false;
  }
  return false;
}

FsRootSeverity FsRootPinReport::Severity() const {
  auto worst = dropped_roots.empty() ? FsRootSeverity::kOk : FsRootSeverity::kWarning;
  for (const auto& v : verdicts) {
    worst = std::max(worst, v.Severity());
  }
  return worst;
}

bool FsRootPinReport::ShouldRefuseStartup(const FsRootPinStartupPolicy& policy) const {
  for (const auto& v : verdicts) {
    if (RefusesUnder(v, policy)) {
      return true;
    }
  }
  return false;
}

std::vector<std::string> FsRootPinReport::CertifiableRoots() const {
  std::vector<std::string> roots;
  for (const auto& v : verdicts) {
    if (v.state == FsRootState::kCertifiable) {
      roots.push_back(v.root);
    }
  }
  return roots;
}

const FsRootVerdict* FsRootPinReport::FindRoot(const std::string& root) const {
  for (const auto& v : verdicts) {
    if (v.root == root) {
      return &v;
    }
  }
  return nullptr;
}

int FsPinExitCodeForSeverity(FsRootSeverity severity) {
  switch (severity) {
    case FsRootSeverity::kFailure: return kFsPinExitFailure;
    case FsRootSeverity::kWarning: return kFsPinExitWarning;
    case FsRootSeverity::kOk: return kFsPinExitOk;
  }
  return kFsPinExitCannotRun;
}

FsRootRepinDecision DecideRepin(const FsRootVerdict& verdict) {
  switch (verdict.state) {
    case FsRootState::kMismatched:
    case FsRootState::kPinUnparseable:
      // The pin disagrees with the mount point, or is corrupt. The superblocks decide which of the
      // two records is the stale one: if they name the root we are looking at, the data belongs
      // here and only the pin is wrong.
      if (verdict.superblocks_with_evidence == 0) {
        return FsRootRepinDecision::kUnprovable;
      }
      return verdict.disagreeing_superblocks.empty() ? FsRootRepinDecision::kSafe
                                                 : FsRootRepinDecision::kUnsafeVolumeMoved;

    case FsRootState::kEvidenceConflict:
      // No pin is involved: the superblocks themselves name another root. Writing a pin cannot make
      // those tablets find their data.
      return FsRootRepinDecision::kUnsafeVolumeMoved;

    case FsRootState::kPinIoError:
      // We could not read what is there. Overwriting it blind would destroy the only record.
      return FsRootRepinDecision::kUnprovable;

    case FsRootState::kVerified:
    case FsRootState::kCertifiable:
    case FsRootState::kUncertified:
    case FsRootState::kPending:
    case FsRootState::kUnformatted:
      return FsRootRepinDecision::kNotNeeded;
  }
  return FsRootRepinDecision::kNotNeeded;
}

std::string FsRootPinReport::FailureMessage(Audience audience) const {
  if (!HasFailure()) {
    return std::string();
  }

  std::ostringstream out;
  // Leading newline: this text reaches the log behind up to two RETURN_NOT_OK_PREPEND prefixes, and
  // the headline has to start its own line to be readable.
  //
  // Whether this ends in a refusal is the caller's decision (see --fs_root_pin_enforce), so the
  // text states the diagnosis and the remedy but does not announce an action.
  out << "\nData volumes are not mounted where they were.\n\n";

  std::vector<const FsRootVerdict*> mismatched;
  bool any_repin_safe = false;
  for (const auto& v : verdicts) {
    if (DecideRepin(v) == FsRootRepinDecision::kSafe) {
      any_repin_safe = true;
    }
    switch (v.state) {
      case FsRootState::kMismatched:
        mismatched.push_back(&v);
        out << "  " << v.root << " holds the volume pinned at " << v.pin.mount_point << "\n";
        out << "      pin file " << v.pin_path;
        if (!v.pin.pinned_at.empty()) {
          out << ", pinned at " << v.pin.pinned_at;
        }
        if (!v.pin.filesystem_uuid.empty()) {
          out << ", filesystem UUID " << v.pin.filesystem_uuid;
        }
        out << "\n";
        if (v.superblocks_seen > 0) {
          out << "      " << Plural(v.superblocks_seen, "tablet superblock")
              << " under this root\n";
        }
        if (!v.disagreeing_superblocks.empty()) {
          out << "      " << v.disagreeing_superblocks.size()
              << " of them also record a different data root:\n";
          AppendTabletLines(v.disagreeing_superblocks, &out);
        } else if (v.superblocks_with_evidence > 0) {
          out << "      but every superblock under it names this root, so the data belongs here\n"
              << "      and it is the pin that is stale\n";
        }
        AppendSideAnomalies(v, "      ", &out);
        break;

      case FsRootState::kPinUnparseable:
        out << "  " << v.root << " has a pin file whose contents are unusable\n";
        out << "      " << v.pin_path << ": " << v.read_error << "\n";
        out << "      Treating it as unpinned would re-certify whatever layout is current and\n"
            << "      hide a swap, so it is a failure rather than a fresh start.\n";
        AppendSideAnomalies(v, "      ", &out);
        break;

      case FsRootState::kEvidenceConflict:
        out << "  " << v.root << " has no pin file, and " << v.disagreeing_superblocks.size()
            << " of "
            << Plural(v.superblocks_with_evidence, "tablet superblock")
            << " under it record a different data root\n";
        AppendTabletLines(v.disagreeing_superblocks, &out);
        out << "      Not writing a pin: the evidence contradicts the layout we would record.\n";
        AppendSideAnomalies(v, "      ", &out);
        break;

      case FsRootState::kVerified:
      case FsRootState::kCertifiable:
      case FsRootState::kUncertified:
      case FsRootState::kPending:
      case FsRootState::kPinIoError:
      case FsRootState::kUnformatted:
        break;
    }
  }

  if (MountsPermutedAmongThemselves(mismatched)) {
    std::vector<std::string> names;
    for (const auto* v : mismatched) {
      names.push_back(v->root);
    }
    out << "\n";
    if (names.size() == 2) {
      out << names[0] << " and " << names[1] << " appear to be swapped.\n";
    } else {
      out << JoinStrings(names, ", ")
          << " appear to have been remounted onto each other's mount points.\n";
    }
  }

  if (!dropped_roots.empty()) {
    out << "\nThis report is incomplete: " << JoinStrings(dropped_roots, ", ")
        << " could not be opened, so tablets on those roots were not examined.\n";
  }

  out << "\nRemount the data volumes where they were and restart. No data has been lost: every\n"
      << "file moved with its volume, and only the absolute paths recorded in tablet metadata\n"
      << "disagree with the mounts. Do not delete anything, and in particular do not remove\n"
      << "duplicate tablet directories.\n";

  if (any_repin_safe) {
    out << "\nOne or more roots above hold data that does belong to them, with only a stale pin\n"
        << "recording otherwise. `yb-fs_pin repin` rewrites exactly those pins, and refuses the\n"
        << "roots whose superblocks show the volume really moved.\n";
  }
  if (audience == Audience::kServerLog) {
    out << "\nRun `yb-fs_pin survey` for the full per-tablet detail.\n";
  }
  return out.str();
}

std::string FsRootPinReport::WarningMessage() const {
  if (Severity() == FsRootSeverity::kOk) {
    return std::string();
  }

  std::ostringstream out;
  for (const auto& v : verdicts) {
    switch (v.state) {
      case FsRootState::kUnformatted:
        out << "  " << v.root << " has no instance file while other roots do. It was never\n"
            << "  formatted, was wiped, is a blank or newly added volume, or -- the case worth\n"
            << "  ruling out first -- its volume did not mount, leaving an empty directory on\n"
            << "  the root filesystem.\n";
        if (v.likely_unmounted) {
          out << "  It is on the same device as / while its sibling data roots are not, which is\n"
              << "  what an unmounted mount point looks like from in here. Treat that as the\n"
              << "  likely explanation unless you know this disk was just replaced or added.\n";
        }
        // Say what is about to happen, not merely what was observed. Startup does not refuse on
        // this state, so CreateFileSystemRoots() is about to adopt the root by writing a fresh
        // instance file into it -- right for a genuine disk replacement, exactly wrong for a
        // volume that failed to mount, and irreversible in the sense that the evidence of the
        // original state is gone.
        out << "  This root will be adopted as a new, empty data directory on this start. If its\n"
            << "  volume simply failed to mount, stop the server now and mount it.\n";
        break;
      case FsRootState::kPinIoError:
        out << "  " << v.root << ": pin file " << v.pin_path << " could not be read: "
            << v.read_error << "\n"
            << "  Leaving it alone: it is neither trusted nor replaced, and this root will not\n"
            << "  be certified while the fault persists.\n";
        if (!v.disagreeing_superblocks.empty()) {
          out << "  " << v.disagreeing_superblocks.size() << " of "
              << Plural(v.superblocks_with_evidence, "tablet superblock")
              << " under it record a different data root. With the pin unreadable, whether this\n"
              << "  volume is mounted where it belongs cannot be verified.\n";
          AppendTabletLines(v.disagreeing_superblocks, &out);
        }
        break;
      default:
        break;
    }
    // Only kVerified establishes the claim below: the pin was read and it names this root. Other
    // warning-severity states (kPinIoError, kUnformatted) can also carry disagreeing superblocks,
    // but there the pin was unreadable or absent, and "the volume has not moved" is not known.
    if (!v.disagreeing_superblocks.empty() && v.state == FsRootState::kVerified) {
      out << "  " << v.root << " is pinned here and the volume has not moved, but "
          << v.disagreeing_superblocks.size() << " of "
          << Plural(v.superblocks_with_evidence, "tablet superblock")
          << " under it record a different data root. Something moved tablet\n"
          << "  directories by hand; those tablets will not find their data.\n";
      AppendTabletLines(v.disagreeing_superblocks, &out);
    }
    // Side anomalies are reported for every root that FailureMessage() does not already cover.
    // A failing root gets them there, next to its own diagnosis, so repeating them here would
    // double them up now that both messages reach the log.
    if (v.Severity() != FsRootSeverity::kFailure) {
      AppendSideAnomalies(v, "  ", &out);
    }
  }
  if (!dropped_roots.empty()) {
    out << "  " << JoinStrings(dropped_roots, ", ")
        << " could not be opened and were not examined; a clean verdict here is not a clean node\n";
  }
  return out.str();
}

std::string FsRootPinReport::SummaryLine() const {
  size_t verified = 0, certifiable = 0, uncertified = 0, pending = 0, failing = 0, warning = 0;
  for (const auto& v : verdicts) {
    switch (v.state) {
      case FsRootState::kVerified: ++verified; break;
      case FsRootState::kCertifiable: ++certifiable; break;
      case FsRootState::kUncertified: ++uncertified; break;
      case FsRootState::kPending: ++pending; break;
      case FsRootState::kPinIoError:
      case FsRootState::kUnformatted: ++warning; break;
      case FsRootState::kMismatched:
      case FsRootState::kPinUnparseable:
      case FsRootState::kEvidenceConflict: ++failing; break;
    }
  }
  return Format(
      "data root pins: $0 roots, $1 verified, $2 certifiable, $3 uncertified (no tablets), "
      "$4 not yet checked, $5 needing attention, $6 with a wrong layout",
      verdicts.size(), verified, certifiable, uncertified, pending, warning, failing);
}

std::string FsRootPinReport::ToJson() const {
  std::stringstream ss;
  JsonWriter w(&ss, JsonWriter::PRETTY);
  w.StartObject();

  w.String("severity");
  w.String(ToString(Severity()));
  w.String("has_failure");
  w.Bool(HasFailure());
  w.String("exit_code");
  w.Int(FsPinExitCodeForReport(*this));
  w.String("summary");
  w.String(SummaryLine());

  w.String("roots");
  w.StartArray();
  for (const auto& v : verdicts) {
    w.StartObject();
    w.String("root");
    w.String(v.root);
    w.String("state");
    w.String(ToString(v.state));
    w.String("severity");
    w.String(ToString(v.Severity()));
    w.String("repin");
    w.String(ToString(DecideRepin(v)));
    w.String("pin_path");
    w.String(v.pin_path);
    if (!v.pin.mount_point.empty()) {
      w.String("pinned_mount_point");
      w.String(v.pin.mount_point);
    }
    if (!v.pin.pinned_at.empty()) {
      w.String("pinned_at");
      w.String(v.pin.pinned_at);
    }
    if (!v.pin.filesystem_uuid.empty()) {
      w.String("filesystem_uuid");
      w.String(v.pin.filesystem_uuid);
    }
    if (!v.read_error.empty()) {
      w.String("read_error");
      w.String(v.read_error);
    }
    w.String("superblocks_seen");
    w.Uint64(v.superblocks_seen);
    w.String("superblocks_with_evidence");
    w.Uint64(v.superblocks_with_evidence);

    const auto write_tablets = [&w](const char* name,
                                    const std::vector<TabletSuperblockEvidence>& tablets) {
      w.String(name);
      w.StartArray();
      for (const auto& t : tablets) {
        w.StartObject();
        w.String("tablet_id");
        w.String(t.tablet_id);
        w.String("containing_root");
        w.String(t.containing_root);
        if (!t.recorded_data_root.empty()) {
          w.String("recorded_data_root");
          w.String(t.recorded_data_root);
        }
        if (!t.recorded_wal_root.empty()) {
          w.String("recorded_wal_root");
          w.String(t.recorded_wal_root);
        }
        if (!t.read_error.empty()) {
          w.String("read_error");
          w.String(t.read_error);
        }
        w.EndObject();
      }
      w.EndArray();
    };
    write_tablets("disagreeing_superblocks", v.disagreeing_superblocks);
    write_tablets("unknown_wal_root_superblocks", v.unknown_wal_root_superblocks);
    write_tablets("unreadable_superblocks", v.unreadable_superblocks);
    w.EndObject();
  }
  w.EndArray();

  w.String("dropped_roots");
  w.StartArray();
  for (const auto& root : dropped_roots) {
    w.String(root);
  }
  w.EndArray();

  w.EndObject();
  return ss.str();
}

FsRootPinReport EvaluateFsRootPins(const FsRootPinInputs& inputs) {
  FsRootPinReport report;
  report.dropped_roots = inputs.dropped_roots;

  // A node where no root has an instance file has simply never been formatted, which is the normal
  // state on a first boot. It is only when the siblings have one that a missing instance file says
  // something about this root.
  const bool any_root_formatted = inputs.unformatted_roots.size() < inputs.data_roots.size();

  // Bucket the evidence by the root each superblock was found under.
  std::map<std::string, std::vector<const TabletSuperblockEvidence*>> evidence_by_root;
  for (const auto& e : inputs.evidence) {
    evidence_by_root[e.containing_root].push_back(&e);
  }

  for (const auto& root : inputs.data_roots) {
    FsRootVerdict v;
    v.root = root;
    v.pin_path = FsRootPinPath(root, inputs.server_type);

    auto ev_it = evidence_by_root.find(root);
    if (ev_it != evidence_by_root.end()) {
      for (const auto* e : ev_it->second) {
        ++v.superblocks_seen;
        if (!e->read_error.empty()) {
          v.unreadable_superblocks.push_back(*e);
          continue;
        }
        if (e->recorded_data_root.empty()) {
          // Superblock located but not parsed, or a tombstoned tablet that carries no rocksdb dir.
          // Either way it is not evidence of anything.
          continue;
        }
        ++v.superblocks_with_evidence;
        if (e->recorded_data_root != root) {
          v.disagreeing_superblocks.push_back(*e);
        }
        if (!e->recorded_wal_root.empty() &&
            inputs.wal_roots.find(e->recorded_wal_root) == inputs.wal_roots.end()) {
          v.unknown_wal_root_superblocks.push_back(*e);
        }
      }
    }

    auto pin_it = inputs.pin_files.find(root);
    const FsRootPinFile* pin_file = (pin_it == inputs.pin_files.end()) ? nullptr : &pin_it->second;
    const auto file_state = pin_file ? pin_file->state : FsRootPinFileState::kAbsent;

    // Missing instance file, siblings have one: nothing below can be trusted about this root, and
    // in particular an empty directory must not read as "a root with no tablets". Checked after the
    // pin state rather than before, so that a volume that was both swapped and wiped is still
    // reported as the swap it is -- the pin is the stronger signal and must not be masked.
    if (file_state == FsRootPinFileState::kAbsent && any_root_formatted &&
        inputs.unformatted_roots.find(root) != inputs.unformatted_roots.end()) {
      v.state = FsRootState::kUnformatted;
      v.likely_unmounted = inputs.likely_unmounted_roots.contains(root);
      report.verdicts.push_back(std::move(v));
      continue;
    }

    switch (file_state) {
      case FsRootPinFileState::kUnparseable:
        v.state = FsRootState::kPinUnparseable;
        v.read_error = pin_file->error;
        break;

      case FsRootPinFileState::kIoError:
        v.state = FsRootState::kPinIoError;
        v.read_error = pin_file->error;
        break;

      case FsRootPinFileState::kPresent:
        v.pin = pin_file->pin;
        // The pin is the strong evidence: it says which mount point this physical volume was
        // certified at. If it names this root, the volume has not moved, full stop -- a superblock
        // that disagrees is a separate (hand-moved directory) problem, reported as a warning.
        v.state = (pin_file->pin.mount_point == root) ? FsRootState::kVerified
                                                      : FsRootState::kMismatched;
        break;

      case FsRootPinFileState::kAbsent:
        if (!inputs.evidence_complete) {
          // The FsManager pass runs before tablets are enumerated. "No evidence gathered" must not
          // be mistaken for "no tablets", so leave the decision to the later pass.
          v.state = FsRootState::kPending;
        } else if (v.superblocks_with_evidence == 0) {
          // With no tablets there is no evidence the root is where it belongs, and we will not
          // record a mapping we cannot prove. Nothing is at risk: a swap can only cause harm if
          // data moved.
          v.state = FsRootState::kUncertified;
        } else if (v.disagreeing_superblocks.empty()) {
          v.state = FsRootState::kCertifiable;
        } else {
          v.state = FsRootState::kEvidenceConflict;
        }
        break;
    }

    report.verdicts.push_back(std::move(v));
  }

  // data_roots is a std::set, so verdicts come out sorted by root already.
  return report;
}

FsRootPinFile ReadFsRootPinFile(Env* env, const std::string& pin_path) {
  FsRootPinFile result;

  // Deliberately no FileExists() precheck: that is access(F_OK) with no errno inspection, so a pin
  // that exists but cannot be reached (EACCES on the parent, ELOOP, ENAMETOOLONG) would report as
  // absent, and a root with clean evidence would then overwrite it with the current mount point --
  // the same "bless whatever happens to be mounted" hazard that kPinUnparseable exists to close.
  // Reading and classifying the failure distinguishes ENOENT from everything else.
  auto size = env->GetFileSize(pin_path);
  if (!size.ok()) {
    result.state = size.status().IsNotFound() ? FsRootPinFileState::kAbsent
                                              : FsRootPinFileState::kIoError;
    if (result.state == FsRootPinFileState::kIoError) {
      result.error = size.status().ToString(/* include_file_and_line = */ false);
    }
    return result;
  }
  if (*size > kMaxFsRootPinFileSize) {
    result.state = FsRootPinFileState::kUnparseable;
    result.error = Format(
        "file is $0 bytes, far larger than any pin file (cap is $1)", *size,
        kMaxFsRootPinFileSize);
    return result;
  }

  faststring contents;
  Status s = ReadFileToString(env, pin_path, &contents);
  if (!s.ok()) {
    result.state = s.IsNotFound() ? FsRootPinFileState::kAbsent : FsRootPinFileState::kIoError;
    if (result.state == FsRootPinFileState::kIoError) {
      result.error = s.ToString(/* include_file_and_line = */ false);
    }
    return result;
  }

  auto pin = FsRootPin::ParseJson(contents.ToString());
  if (!pin.ok()) {
    result.state = FsRootPinFileState::kUnparseable;
    result.error = pin.status().message().ToBuffer();
    return result;
  }

  result.state = FsRootPinFileState::kPresent;
  result.pin = *pin;
  return result;
}

Status SweepFsRootPinTempFiles(Env* env, const std::string& pin_path) {
  const auto dir = DirName(pin_path);
  const auto prefix = Format("$0$1", BaseName(pin_path), kFsRootPinTempInfix);
  auto children = env->GetChildren(dir, ExcludeDots::kTrue);
  if (!children.ok()) {
    // The directory not being there is not a leftover-temp-file problem.
    return children.status().IsNotFound() ? Status::OK() : children.status();
  }
  for (const auto& child : *children) {
    if (child.rfind(prefix, 0) == 0) {
      const auto stale = JoinPathSegments(dir, child);
      LOG(INFO) << "Removing leftover data root pin temp file " << stale;
      RETURN_NOT_OK_PREPEND(env->DeleteFile(stale), "Unable to remove " + stale);
    }
  }
  return Status::OK();
}

Status WriteFsRootPinFile(Env* env, const std::string& pin_path, const FsRootPin& pin) {
  WARN_NOT_OK(SweepFsRootPinTempFiles(env, pin_path), "Could not sweep stale pin temp files");

  const std::string json = pin.ToJson();

  // Temp file, fsync, rename, fsync the directory. Unusable pin contents refuse startup, so a torn
  // write would otherwise brick the node on the next restart.
  const auto tmp_template = Format("$0$1XXXXXX", pin_path, kFsRootPinTempInfix);
  std::string tmp_path;
  std::unique_ptr<WritableFile> file;
  RETURN_NOT_OK_PREPEND(
      env->NewTempWritableFile(WritableFileOptions(), tmp_template, &tmp_path, &file),
      "Unable to create temp file for " + pin_path);
  env_util::ScopedFileDeleter tmp_deleter(env, tmp_path);

  RETURN_NOT_OK_PREPEND(file->Append(Slice(json)), "Failed to write " + tmp_path);
  RETURN_NOT_OK_PREPEND(file->Sync(), "Failed to Sync() " + tmp_path);
  RETURN_NOT_OK_PREPEND(file->Close(), "Failed to Close() " + tmp_path);
  RETURN_NOT_OK_PREPEND(env->RenameFile(tmp_path, pin_path), "Failed to rename onto " + pin_path);
  tmp_deleter.Cancel();
  RETURN_NOT_OK_PREPEND(
      env->SyncDir(DirName(pin_path)), "Failed to SyncDir() parent of " + pin_path);
  return Status::OK();
}

Status DeleteFsRootPinFile(Env* env, const std::string& pin_path) {
  RETURN_NOT_OK(SweepFsRootPinTempFiles(env, pin_path));
  const auto s = env->DeleteFile(pin_path);
  return s.IsNotFound() ? Status::OK() : s;
}

std::string FsRootOfYbDataPath(const std::string& path) {
  if (path.empty()) {
    return std::string();
  }
  std::string cur = path;
  for (int i = 0; i < kMaxYbDataAncestorWalk; ++i) {
    if (BaseName(cur) == kYbDataDirName) {
      return DirName(cur);
    }
    std::string parent = DirName(cur);
    if (parent == cur) {
      break;  // Reached "/" or a relative leaf; DirName is a fixed point there.
    }
    cur = std::move(parent);
  }
  return std::string();
}

Result<std::vector<std::string>> TabletMetaEntries(const std::string& root) {
    const auto dir =
        FsManager::GetRaftGroupMetadataDir(GetServerTypeDataPath(root, kServerType));
    auto entries = VERIFY_RESULT(Env::Default()->GetChildren(dir, ExcludeDots::kTrue));
    std::sort(entries.begin(), entries.end());
    return entries;
  }

Result<std::string> PinContents(const std::string& root) {
    faststring data;
    RETURN_NOT_OK(ReadFileToString(Env::Default(), FsRootPinPath(root, kServerType), &data));
    return data.ToString();
  }

Status SwapDrives(const std::string& a, const std::string& b) {
    auto* env = Env::Default();
    const auto tmp = a + ".swapping";
    RETURN_NOT_OK(env->RenameFile(a, tmp));
    RETURN_NOT_OK(env->RenameFile(b, a));
    return env->RenameFile(tmp, b);
  }

TEST_F(FsRootPinITest, SwappedDataDirsRefuseStartupWithoutCreatingReplicas) {
  ASSERT_OK(WaitAllReplicasReady(mini_cluster(), kDefaultTimeout));

  auto* ts = mini_cluster()->mini_tablet_server(0);
  const auto drive1 = Drive(0);
  const auto drive2 = Drive(1);

  // --- Certification. The cluster booted on freshly formatted roots, where there is nothing to
  // certify from; the pins are written by TSTabletManager::Init on the first start that finds
  // superblocks. Restart now that tablets exist and expect a pin on every data root: with four
  // tablets assigned least-loaded-first across three drives, no drive is left empty.
  ASSERT_OK(ts->Restart());
  ASSERT_OK(ts->WaitStarted());
  for (int d = 0; d < num_drives(); ++d) {
    const auto pin_path = FsRootPinPath(Drive(d), kServerType);
    ASSERT_TRUE(Env::Default()->FileExists(pin_path))
        << "expected TSTabletManager::Init to have certified " << Drive(d);
  }

  // What is on disk before anything goes wrong. The pin travels with its volume in the swap
  // below, so each captured value is later expected at the other path.
  const auto meta_on_drive1 = ASSERT_RESULT(TabletMetaEntries(drive1));
  const auto meta_on_drive2 = ASSERT_RESULT(TabletMetaEntries(drive2));
  ASSERT_FALSE(meta_on_drive1.empty());
  ASSERT_FALSE(meta_on_drive2.empty());
  const auto pin_of_drive1 = ASSERT_RESULT(PinContents(drive1));
  const auto pin_of_drive2 = ASSERT_RESULT(PinContents(drive2));

  // --- The swap. Refusal must arrive as an ordinary status out of the start path, naming both
  // roots, before tablets are opened.
  ts->Shutdown();
  ASSERT_OK(SwapDrives(drive1, drive2));

  auto status = ts->RestartStoppedServer();
  ASSERT_NOK(status);
  ASSERT_STR_CONTAINS(status.ToString(), "Refusing to start until the mounts are corrected");
  ASSERT_STR_CONTAINS(status.ToString(), "ts-1-drive-1");
  ASSERT_STR_CONTAINS(status.ToString(), "ts-1-drive-2");

  // --- Nothing was lost and nothing was invented. The refused boot must not have created a
  // replacement replica (the failure mode this detector exists to pre-empt) nor rewritten a pin;
  // the volumes' contents simply sit at exchanged paths.
  ASSERT_EQ(meta_on_drive2, ASSERT_RESULT(TabletMetaEntries(drive1)));
  ASSERT_EQ(meta_on_drive1, ASSERT_RESULT(TabletMetaEntries(drive2)));
  ASSERT_EQ(pin_of_drive2, ASSERT_RESULT(PinContents(drive1)));
  ASSERT_EQ(pin_of_drive1, ASSERT_RESULT(PinContents(drive2)));

  // --- Recovery is what the refusal message promises: put the mounts back and restart. No pin
  // surgery, no metadata surgery.
  ASSERT_OK(SwapDrives(drive1, drive2));
  ASSERT_OK(ts->RestartStoppedServer());
  ASSERT_OK(ts->WaitStarted());
  ASSERT_OK(WaitAllReplicasReady(mini_cluster(), kDefaultTimeout));
  ASSERT_EQ(meta_on_drive1, ASSERT_RESULT(TabletMetaEntries(drive1)));
  ASSERT_EQ(meta_on_drive2, ASSERT_RESULT(TabletMetaEntries(drive2)));
}

TEST_F(TestRaftGroupMetadata, MovedRocksDbDirReopensEmptyWithoutComplaint) {
  QLWriteRequestPB req;
  BuildPartialRow(0, 0, "foo", &req);
  ASSERT_OK(writer_->Write(&req));
  ASSERT_OK(harness_->tablet()->Flush(tablet::FlushMode::kSync, rocksdb::FlushReason::kTestOnly));

  const auto recorded_dir = harness_->tablet()->metadata()->rocksdb_dir();
  const auto pre_shutdown_ht = clock()->Now();
  harness_->tablet()->StartShutdown(DisableFlushOnShutdown::kFalse, AbortOps::kFalse);
  harness_->tablet()->CompleteShutdown();
  // The writer holds a ref to the old tablet; drop it so TabletReOpen fully replaces the tablet.
  writer_.reset();

  // Reopens the tablet the way this harness allows and makes prior data readable again: the
  // harness clock restarts at kInitial and the fresh MvccManager only advances with traffic, so
  // restore the clock and write one sentinel row; safe time then covers everything written
  // before the shutdown.
  const auto reopen_and_write_sentinel = [&]() {
    TabletReOpen();
    clock()->Update(pre_shutdown_ht);
    writer_.reset(new LocalTabletWriter(harness_->tablet()));
    QLWriteRequestPB sentinel;
    BuildPartialRow(100, 100, "sentinel", &sentinel);
    ASSERT_OK(writer_->Write(&sentinel));
  };

  // Control: a plain reopen, data untouched, serves the acknowledged row beside the sentinel.
  ASSERT_NO_FATALS(reopen_and_write_sentinel());
  std::vector<std::string> rows;
  ASSERT_OK(DumpTablet(*harness_->tablet(), &rows));
  ASSERT_EQ(2, rows.size());

  harness_->tablet()->StartShutdown(DisableFlushOnShutdown::kFalse, AbortOps::kFalse);
  harness_->tablet()->CompleteShutdown();
  writer_.reset();

  // The operator relocates the data (or the mount swaps): every byte still exists, just not at
  // the recorded absolute path.
  const auto moved_dir = recorded_dir + ".moved-by-operator";
  ASSERT_OK(Env::Default()->RenameFile(recorded_dir, moved_dir));

  // Reopen succeeds and takes new writes; nothing notices.
  ASSERT_NO_FATALS(reopen_and_write_sentinel());

  // The acknowledged rows are gone, a fresh database (holding only the new sentinel) sits at the
  // recorded path, and the real data is stranded at the moved path.
  ASSERT_OK(DumpTablet(*harness_->tablet(), &rows));
  ASSERT_EQ(1, rows.size());
  ASSERT_STR_CONTAINS(rows[0], "sentinel");
  ASSERT_TRUE(Env::Default()->FileExists(recorded_dir));
  ASSERT_TRUE(Env::Default()->FileExists(moved_dir));
}

TEST_F(TestRaftGroupMetadata, StaleCopyAtRecordedPathIsServedWithoutComplaint) {
  QLWriteRequestPB req;
  BuildPartialRow(0, 0, "v1", &req);
  ASSERT_OK(writer_->Write(&req));
  ASSERT_OK(harness_->tablet()->Flush(tablet::FlushMode::kSync, rocksdb::FlushReason::kTestOnly));

  const auto recorded_dir = harness_->tablet()->metadata()->rocksdb_dir();
  harness_->tablet()->StartShutdown(DisableFlushOnShutdown::kFalse, AbortOps::kFalse);
  harness_->tablet()->CompleteShutdown();
  writer_.reset();

  // Preserve the v1 incarnation, as a copied-away tablet directory or the other volume of a
  // swapped pair would.
  const auto stale_copy = recorded_dir + ".stale-copy";
  ASSERT_OK(Env::Default()->RenameFile(recorded_dir, stale_copy));

  // Second incarnation: overwrite row 0 and add row 1, i.e. writes the client saw acknowledged.
  ASSERT_NO_FATALS(TabletReOpen());
  writer_.reset(new LocalTabletWriter(harness_->tablet()));
  BuildPartialRow(0, 1, "v2", &req);
  ASSERT_OK(writer_->Write(&req));
  BuildPartialRow(1, 1, "v2-second-row", &req);
  ASSERT_OK(writer_->Write(&req));
  ASSERT_OK(harness_->tablet()->Flush(tablet::FlushMode::kSync, rocksdb::FlushReason::kTestOnly));
  const auto pre_shutdown_ht = clock()->Now();
  harness_->tablet()->StartShutdown(DisableFlushOnShutdown::kFalse, AbortOps::kFalse);
  harness_->tablet()->CompleteShutdown();
  writer_.reset();

  // The stale incarnation lands back at the recorded path.
  ASSERT_OK(Env::Default()->DeleteRecursively(recorded_dir));
  ASSERT_OK(Env::Default()->RenameFile(stale_copy, recorded_dir));

  // Reopen succeeds and serves the stale data with no error anywhere: the second row never
  // existed and row 0 is back at "v1". (Clock restored and a sentinel written for the same
  // reason as the previous test: the harness clock and MvccManager restart on reopen.)
  ASSERT_NO_FATALS(TabletReOpen());
  clock()->Update(pre_shutdown_ht);
  writer_.reset(new LocalTabletWriter(harness_->tablet()));
  BuildPartialRow(100, 100, "sentinel", &req);
  ASSERT_OK(writer_->Write(&req));

  std::vector<std::string> rows;
  ASSERT_OK(DumpTablet(*harness_->tablet(), &rows));
  ASSERT_EQ(2, rows.size());
  ASSERT_STR_CONTAINS(yb::ToString(rows), "v1");
  ASSERT_STR_NOT_CONTAINS(yb::ToString(rows), "v2-second-row");
}

TabletSuperblockEvidence ReadSuperblockEvidence(
    Env* env, const std::string& root, const std::string& server_type,
    const std::string& tablet_id) {
  TabletSuperblockEvidence evidence;
  evidence.tablet_id = tablet_id;
  evidence.containing_root = root;

  const auto path = JoinPathSegments(
      FsManager::GetRaftGroupMetadataDir(GetServerTypeDataPath(root, server_type)), tablet_id);

  tablet::RaftGroupReplicaSuperBlockPB superblock;
  const auto s = pb_util::ReadPBContainerFromPath(env, path, &superblock);
  if (!s.ok()) {
    // A superblock we cannot read is not evidence of anything, and a root made entirely of them
    // must not read as "a root with no tablets". Recording the error keeps it in the report and in
    // the JSON, rather than only on stderr where the caller parsing our output will not see it.
    evidence.read_error = s.ToString(/* include_file_and_line = */ false);
    return evidence;
  }

  evidence.recorded_data_root = FsRootOfYbDataPath(superblock.kv_store().rocksdb_dir());
  evidence.recorded_wal_root = FsRootOfYbDataPath(superblock.wal_dir());
  return evidence;
}

Result<std::vector<TabletSuperblockEvidence>> CollectEvidence(
    FsManager* fs_manager, const std::string& server_type) {
  auto by_root = VERIFY_RESULT(fs_manager->ListTabletIdsByRoot());

  std::vector<TabletSuperblockEvidence> evidence;
  for (const auto& [root, tablet_ids] : by_root) {
    for (const auto& tablet_id : tablet_ids) {
      evidence.push_back(ReadSuperblockEvidence(fs_manager->env(), root, server_type, tablet_id));
    }
  }
  return evidence;
}

void PrintTextReport(const FsRootPinReport& report, std::ostream* out) {
  *out << report.SummaryLine() << "\n\n";
  for (const auto& v : report.verdicts) {
    *out << "  " << v.root << ": " << ToString(v.state);
    if (!v.pin.mount_point.empty() && v.pin.mount_point != v.root) {
      *out << " (pinned at " << v.pin.mount_point << ")";
    }
    *out << ", " << v.superblocks_seen
         << (v.superblocks_seen == 1 ? " tablet superblock" : " tablet superblocks");
    if (v.superblocks_with_evidence != v.superblocks_seen) {
      *out << " (" << v.superblocks_with_evidence << " usable as evidence)";
    }
    const auto repin = DecideRepin(v);
    if (repin != FsRootRepinDecision::kNotNeeded) {
      *out << ", repin: " << ToString(repin);
    }
    *out << "\n";
    if (!v.read_error.empty()) {
      *out << "      pin file: " << v.read_error << "\n";
    }
    // The whole point of the offline survey is that it prints every disagreeing tablet, where the
    // startup message truncates. Support has had to reconstruct this table by hand in a real
    // incident of this bug.
    for (const auto& t : v.disagreeing_superblocks) {
      *out << "      tablet " << t.tablet_id << ": superblock says " << t.recorded_data_root
           << ", found under " << t.containing_root << "\n";
    }
    for (const auto& t : v.unreadable_superblocks) {
      *out << "      tablet " << t.tablet_id << ": unreadable superblock: " << t.read_error << "\n";
    }
    for (const auto& t : v.unknown_wal_root_superblocks) {
      *out << "      tablet " << t.tablet_id << ": WAL root " << t.recorded_wal_root
           << " is not in --fs_wal_dirs\n";
    }
  }

  if (report.HasFailure()) {
    *out << report.FailureMessage(FsRootPinReport::Audience::kOfflineCommand);
  } else if (report.HasWarnings()) {
    *out << "\nWarnings:\n" << report.WarningMessage();
  }
}

Status WritePinFor(const std::string& root) {
  const auto pin = FsRootPin::ForMountPoint(root);
  const auto pin_path = FsRootPinPath(root, FLAGS_server_type);
  RETURN_NOT_OK(WriteFsRootPinFile(Env::Default(), pin_path, pin));
  std::cout << "pinned " << root << " -> " << pin_path << std::endl;
  return Status::OK();
}

int RunPin(const FsRootPinReport& report) {
  if (report.HasFailure()) {
    std::cerr << "\nrefusing to pin: the layout above is wrong, and `pin` only ever records what\n"
              << "the superblocks already prove. If a pin is merely stale, `repin` is the repair\n"
              << "path." << std::endl;
    return kFsPinExitFailure;
  }
  for (const auto& root : report.CertifiableRoots()) {
    const auto s = WritePinFor(root);
    if (!s.ok()) {
      std::cerr << "error: unable to pin " << root << ": " << s.ToString() << std::endl;
      return kFsPinExitCannotRun;
    }
  }
  return FsPinExitCodeForReport(report);
}

FsRootSeverity SeverityExcluding(
    const FsRootPinReport& report, const std::set<std::string>& repaired) {
  auto worst = FsRootSeverity::kOk;
  for (const auto& v : report.verdicts) {
    if (repaired.contains(v.root)) {
      continue;
    }
    worst = std::max(worst, v.Severity());
  }
  // A root that could not be opened is still unexamined however many pins were rewritten.
  if (!report.dropped_roots.empty()) {
    worst = std::max(worst, FsRootSeverity::kWarning);
  }
  return worst;
}

int RunRepin(const FsRootPinReport& report) {
  std::vector<std::string> to_repin;
  std::vector<const FsRootVerdict*> moved;
  std::vector<const FsRootVerdict*> unprovable;

  for (const auto& v : report.verdicts) {
    switch (DecideRepin(v)) {
      case FsRootRepinDecision::kSafe: to_repin.push_back(v.root); break;
      case FsRootRepinDecision::kUnsafeVolumeMoved: moved.push_back(&v); break;
      case FsRootRepinDecision::kUnprovable: unprovable.push_back(&v); break;
      case FsRootRepinDecision::kNotNeeded: break;
    }
  }

  for (const auto* v : moved) {
    std::cerr << "\nrefusing to repin " << v->root << ": " << v->disagreeing_superblocks.size()
              << " of its tablet superblocks record a different data root, so this\n"
              << "volume really did move. Its tablets will not find their data at this path "
              << "whatever\nthe pin says. Remount the volume where it belongs instead."
              << std::endl;
  }

  // Kept apart from `unprovable`: a forced root has been repaired, so it must not go on
  // contributing to the exit code. Leaving it in was why a successful `repin --force` exited 1,
  // which the documented contract defines as "a data root's layout is wrong; block the upgrade" -
  // exactly backwards for a command that just fixed it, and read by anything scripted around
  // these codes.
  for (const auto* v : unprovable) {
    if (FLAGS_force) {
      std::cerr << "\n--force: repinning " << v->root << " with no superblock evidence that the\n"
                << "data belongs here. Nothing verified this; you are asserting it." << std::endl;
      to_repin.push_back(v->root);
    } else {
      std::cerr << "\nnot repinning " << v->root << ": no superblock under it can prove where its\n"
                << "data belongs, so rewriting the pin would record a mapping nothing verified.\n"
                << "Re-run with --force to assert it anyway." << std::endl;
    }
  }

  if (to_repin.empty()) {
    std::cerr << "\nnothing repinned." << std::endl;
    return FsPinExitCodeForReport(report);
  }

  std::set<std::string> repaired;
  for (const auto& root : to_repin) {
    const auto s = WritePinFor(root);
    if (!s.ok()) {
      std::cerr << "error: unable to repin " << root << ": " << s.ToString() << std::endl;
      return kFsPinExitCannotRun;
    }
    repaired.insert(root);
  }

  // What is left wrong now, not what was wrong when we started. Deriving it per root also stops a
  // fully repaired node from returning 0 while an unrelated warning - an unformatted sibling, say -
  // is still outstanding, which the old whole-report check hid in the other direction. A fully
  // repaired node comes back clean on the next survey, which is what the operator should run to
  // confirm.
  return FsPinExitCodeForSeverity(SeverityExcluding(report, repaired));
}

int Run(Command command) {
  FsManagerOpts opts;
  opts.server_type = FLAGS_server_type;
  // The survey must not create or probe anything. The writing commands need exactly one file per
  // root, which WriteFsRootPinFile does directly, so they do not need a writable FsManager either.
  opts.read_only = (command == Command::kSurvey);

  FsManager fs_manager(Env::Default(), opts);

  auto evidence = CollectEvidence(&fs_manager, FLAGS_server_type);
  if (!evidence.ok()) {
    std::cerr << "error: " << evidence.status().ToString() << std::endl;
    return kFsPinExitCannotRun;
  }

  auto report = fs_manager.SurveyDataRoots(*evidence, FsRootEvidenceComplete::kTrue);
  if (!report.ok()) {
    std::cerr << "error: " << report.status().ToString() << std::endl;
    return kFsPinExitCannotRun;
  }

  if (FLAGS_output_format == "json") {
    std::cout << report->ToJson() << std::endl;
  } else {
    PrintTextReport(*report, &std::cout);
  }

  switch (command) {
    case Command::kSurvey: return FsPinExitCodeForReport(*report);
    case Command::kPin: return RunPin(*report);
    case Command::kRepin: return RunRepin(*report);
  }
  return kFsPinExitCannotRun;
}

static int FsPinToolMain(int argc, char** argv) {
  FLAGS_logtostderr = 1;
  std::stringstream usage_str;
  PrintUsageToStream(argv[0], &usage_str);
  google::SetUsageMessage(usage_str.str());
  ParseCommandLineFlags(&argc, &argv, true);
  InitGoogleLoggingSafe(argv[0]);

  if (argc < 2) {
    PrintUsageToStream(argv[0], &std::cerr);
    return kFsPinExitCannotRun;
  }
  const std::string command_name = argv[1];
  Command command;
  if (command_name == "survey") {
    command = Command::kSurvey;
  } else if (command_name == "pin") {
    command = Command::kPin;
  } else if (command_name == "repin") {
    command = Command::kRepin;
  } else {
    std::cerr << "error: unknown command \"" << command_name << "\"" << std::endl << std::endl;
    PrintUsageToStream(argv[0], &std::cerr);
    return kFsPinExitCannotRun;
  }

  if (FLAGS_output_format != "text" && FLAGS_output_format != "json") {
    std::cerr << "error: --output_format must be \"text\" or \"json\"" << std::endl;
    return kFsPinExitCannotRun;
  }
  if (FLAGS_fs_data_dirs.empty()) {
    std::cerr << "error: --fs_data_dirs is required" << std::endl;
    return kFsPinExitCannotRun;
  }
  if (FLAGS_server_type != "tserver" && FLAGS_server_type != "master") {
    std::cerr << "error: --server_type must be \"tserver\" or \"master\"" << std::endl;
    return kFsPinExitCannotRun;
  }
  if (FLAGS_server_type == "master" && command != Command::kSurvey) {
    // A master enforces any pin it finds, because VerifyExistingDataRootPins runs from
    // CheckAndOpenFileSystemRoots, which is server-type agnostic. But no master code path calls
    // CertifyDataRoots, so a master pin would never be refreshed by the server after a legitimate
    // change: writing one leaves master coverage in a state that is neither on nor off. Surveying
    // is read-only and useful, so only the writing commands are blocked.
    std::cerr << "error: --server_type=master supports `survey` only. Master-side certification is"
              << "\nnot implemented yet, so a master pin would be enforced at startup but never"
              << "\nmaintained by the server." << std::endl;
    return kFsPinExitCannotRun;
  }

  return Run(command);
}

static void
ifree(uint dev, uint inum)
{
  struct buf *bp = bread(dev, IBLOCK(inum, sb));
  struct dinode *dip = (struct dinode*)bp->data + inum % IPB;
  dip->type = 0;
  log_write(bp);
  brelse(bp);
}

static bool
check_bgp_mup_nlri_list(tvbuff_t *tvb, unsigned offset, int end, bool add_path) {
    uint8_t  architecture_type;
    uint16_t route_type;
    int o;

    for (o = offset; o < end; ) {
        if (add_path) {
            o += 4;
        }
        if (o + 4 > end) {
            return false;
        }
        if (!tvb_bytes_exist(tvb, o, 4)) {
            /* Truncated capture: nothing seen so far contradicts the walk */
            return true;
        }
        architecture_type = tvb_get_uint8(tvb, o);
        route_type = tvb_get_ntohs(tvb, o + 1);
        if (architecture_type != BGP_MUP_AT_3GPP_5G || route_type == 0) {
            return false;
        }
        o += 4 + tvb_get_uint8(tvb, o + 3);
    }
    return o == end;
}

static int
detect_add_path_bgp_mup(tvbuff_t *tvb, unsigned offset, int end) {
    return !check_bgp_mup_nlri_list(tvb, offset, end, false) &&
        check_bgp_mup_nlri_list(tvb, offset, end, true);
}

static int
dissect_PRAL_AlarmItem(tvbuff_t *tvb, int offset,
    packet_info *pinfo, proto_tree *tree, uint8_t *drep, uint16_t *body_length)
{
    proto_item *properties_item;
    proto_tree *properties_tree;
    uint16_t value;
    unsigned reason_add_length;

    /* The item has four fixed uint16 fields and at least four additional octets. */
    if (*body_length < 12) {
        offset = dissect_pn_undecoded(tvb, offset, pinfo, tree, *body_length);
        *body_length = 0;
        return offset;
    }

    offset = dissect_dcerpc_uint16(tvb, offset, pinfo, tree, drep,
        hf_pn_io_channel_number, &value);

    properties_item = proto_tree_add_item(tree, hf_pn_io_pral_channel_properties,
        tvb, offset, 2, DREP_ENC_INTEGER(drep));
    properties_tree = proto_item_add_subtree(properties_item, ett_pn_io_channel_properties);
    dissect_dcerpc_uint16(tvb, offset, pinfo, properties_tree, drep,
        hf_pn_io_pral_channel_properties_reserved_1, &value);
    dissect_dcerpc_uint16(tvb, offset, pinfo, properties_tree, drep,
        hf_pn_io_pral_channel_properties_accumulative, &value);
    dissect_dcerpc_uint16(tvb, offset, pinfo, properties_tree, drep,
        hf_pn_io_pral_channel_properties_reserved_2, &value);
    offset = dissect_dcerpc_uint16(tvb, offset, pinfo, properties_tree, drep,
        hf_pn_io_pral_channel_properties_direction, &value);

    offset = dissect_dcerpc_uint16(tvb, offset, pinfo, tree, drep,
        hf_pn_io_pral_reason, &value);
    offset = dissect_dcerpc_uint16(tvb, offset, pinfo, tree, drep,
        hf_pn_io_pral_ext_reason, &value);

    reason_add_length = *body_length - 8;
    proto_tree_add_item(tree, hf_pn_io_pral_reason_add_value, tvb, offset,
        reason_add_length, ENC_NA);
    offset += reason_add_length;
    *body_length = 0;

    return offset;
}

static int
dissect_SAMRequest_block(tvbuff_t* tvb, int offset, packet_info* pinfo,
    proto_tree* tree, proto_item* item, uint8_t* drep,
    uint8_t u8BlockVersionHigh, uint8_t u8BlockVersionLow, uint16_t u16BodyLength)
{
    return dissect_SAM_block(tvb, offset, pinfo, tree, item, drep,
        u8BlockVersionHigh, u8BlockVersionLow, u16BodyLength, false);
}

static int
dissect_SAMResponse_block(tvbuff_t* tvb, int offset, packet_info* pinfo,
    proto_tree* tree, proto_item* item, uint8_t* drep,
    uint8_t u8BlockVersionHigh, uint8_t u8BlockVersionLow, uint16_t u16BodyLength)
{
    return dissect_SAM_block(tvb, offset, pinfo, tree, item, drep,
        u8BlockVersionHigh, u8BlockVersionLow, u16BodyLength, true);
}

static int
dissect_SCM_undecoded(tvbuff_t* tvb, int offset, int body_end,
    packet_info* pinfo, proto_tree* tree)
{
    if (offset < body_end) {
        dissect_pn_undecoded(tvb, offset, pinfo, tree, body_end - offset);
    }
    return body_end;
}

static int
dissect_SCM_padding(tvbuff_t* tvb, int offset, int body_end,
    packet_info* pinfo, proto_tree* tree)
{
    int padding_length = body_end - offset;

    if (padding_length > 0 && padding_length <= 3) {
        return dissect_pn_padding(tvb, offset, pinfo, tree, padding_length);
    }
    return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
}

static int
dissect_SCM_devid_domain(tvbuff_t* tvb, int offset, int body_end,
    packet_info* pinfo, proto_tree* tree, uint8_t* drep)
{
    if (body_end - offset < 4) {
        return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
    }
    return dissect_dcerpc_uint32(tvb, offset, pinfo, tree, drep,
        hf_pn_io_devid_domain, NULL);
}

static int
dissect_SCM_certificate(tvbuff_t* tvb, int offset, int body_end,
    packet_info* pinfo, proto_tree* tree)
{
    uint16_t certificate_length;

    if (body_end - offset < 2) {
        return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
    }

    proto_tree_add_item_ret_uint16(tree, hf_pn_io_certificate_length, tvb,
        offset, 2, ENC_BIG_ENDIAN, &certificate_length);
    offset += 2;
    if (certificate_length > body_end - offset) {
        return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
    }

    if (certificate_length > 0) {
        asn1_ctx_t asn1_ctx;
        tvbuff_t* certificate_tvb = tvb_new_subset_length(tvb, offset,
            certificate_length);

        asn1_ctx_init(&asn1_ctx, ASN1_ENC_BER, true, pinfo);
        dissect_x509af_Certificate(false, certificate_tvb, 0, &asn1_ctx,
            tree, hf_pn_io_certificate);
    }
    return offset + certificate_length;
}

static int
dissect_SCM_ee_certification_path(tvbuff_t* tvb, int offset, int body_end,
    packet_info* pinfo, proto_tree* tree, uint8_t* drep)
{
    uint16_t number_of_entries;

    if (body_end - offset < 4) {
        return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
    }
    offset = dissect_pn_padding(tvb, offset, pinfo, tree, 2);
    offset = dissect_dcerpc_uint16(tvb, offset, pinfo, tree, drep,
        hf_pn_io_number_of_entries, &number_of_entries);

    while (number_of_entries > 0) {
        int next_offset;
        int aligned_offset;

        if (body_end - offset < 2) {
            return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
        }
        next_offset = dissect_SCM_certificate(tvb, offset, body_end, pinfo,
            tree);
        if (next_offset <= offset || next_offset == body_end) {
            return next_offset;
        }
        number_of_entries--;
        offset = next_offset;
        aligned_offset = (offset + 3) & ~3;
        if (aligned_offset > body_end) {
            return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
        }
        if (aligned_offset > offset) {
            offset = dissect_pn_padding(tvb, offset, pinfo, tree,
                aligned_offset - offset);
        }
    }
    return offset;
}

static int
dissect_SCM_security_configuration_parameters(tvbuff_t* tvb, int offset,
    int body_end, packet_info* pinfo, proto_tree* tree)
{
    proto_item* configuration_item;
    proto_tree* configuration_tree;

    if (body_end - offset < 8) {
        return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
    }

    configuration_item = proto_tree_add_item(tree,
        hf_pn_io_security_configuration_parameters, tvb, offset, 8,
        ENC_BIG_ENDIAN);
    configuration_tree = proto_item_add_subtree(configuration_item,
        ett_pn_io_security_configuration_parameters);
    proto_tree_add_item(configuration_tree,
        hf_pn_io_scm_security_configuration_parameters_reserved, tvb,
        offset, 8, ENC_BIG_ENDIAN);
    proto_tree_add_item(configuration_tree,
        hf_pn_io_scm_credential_validity_period_check, tvb, offset, 8,
        ENC_BIG_ENDIAN);
    proto_tree_add_item(configuration_tree,
        hf_pn_io_scm_security_configuration_parameters_reserved1, tvb,
        offset, 8, ENC_BIG_ENDIAN);
    proto_tree_add_item(configuration_tree,
        hf_pn_io_scm_sack_degradation_threshold_factor, tvb, offset, 8,
        ENC_BIG_ENDIAN);
    proto_tree_add_item(configuration_tree,
        hf_pn_io_scm_security_configuration_parameters_reserved2, tvb,
        offset, 8, ENC_BIG_ENDIAN);
    return offset + 8;
}

static int
dissect_SCM_security_capabilities(tvbuff_t* tvb, int offset, int body_end,
    packet_info* pinfo, proto_tree* tree, uint8_t* drep)
{
    proto_item* features_item;
    proto_tree* features_tree;
    uint16_t number_of_entries;

    if (body_end - offset < 4) {
        return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
    }

    features_item = proto_tree_add_item(tree, hf_pn_io_security_features,
        tvb, offset, 2, ENC_BIG_ENDIAN);
    features_tree = proto_item_add_subtree(features_item,
        ett_pn_io_security_features);
    proto_tree_add_item(features_tree,
        hf_pn_io_scm_security_features_validity_period_checking, tvb,
        offset, 2, ENC_BIG_ENDIAN);
    proto_tree_add_item(features_tree, hf_pn_io_scm_security_features_reserved,
        tvb, offset, 2, ENC_BIG_ENDIAN);
    offset += 2;
    offset = dissect_dcerpc_uint16(tvb, offset, pinfo, tree, drep,
        hf_pn_io_number_of_entries, &number_of_entries);

    while (number_of_entries > 0) {
        proto_item* capability_item;
        proto_tree* capability_tree;
        uint16_t usage;
        int algorithm_hf;

        if (body_end - offset < 2) {
            return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
        }
        usage = tvb_get_ntohs(tvb, offset) & 0x00FF;
        capability_item = proto_tree_add_item(tree, hf_pn_io_security_capability,
            tvb, offset, 2, ENC_BIG_ENDIAN);
        capability_tree = proto_item_add_subtree(capability_item,
            ett_pn_io_security_capability);
        proto_tree_add_item(capability_tree, hf_pn_io_security_capability_usage,
            tvb, offset, 2, ENC_BIG_ENDIAN);
        switch (usage) {
        case 0x01:
            algorithm_hf = hf_pn_io_security_capability_algorithm_symmetric_ao;
            break;
        case 0x02:
            algorithm_hf = hf_pn_io_security_capability_algorithm_symmetric_ae;
            break;
        case 0x03:
            algorithm_hf = hf_pn_io_security_capability_algorithm_key_derivation_function;
            break;
        case 0x04:
            algorithm_hf = hf_pn_io_security_capability_algorithm_key_agreement_function;
            break;
        case 0x05:
            algorithm_hf = hf_pn_io_security_capability_algorithm_digital_signature_function;
            break;
        default:
            algorithm_hf = hf_pn_io_security_capability_algorithm_reserved;
            break;
        }
        proto_tree_add_item(capability_tree, algorithm_hf, tvb, offset, 2,
            ENC_BIG_ENDIAN);
        offset += 2;
        number_of_entries--;
    }
    return offset;
}

static int
dissect_SCM_certification_request(tvbuff_t* tvb, int offset, int body_end,
    packet_info* pinfo, proto_tree* tree)
{
    uint16_t request_length;

    if (body_end - offset < 2) {
        return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
    }
    proto_tree_add_item_ret_uint16(tree, hf_pn_io_certification_request_length,
        tvb, offset, 2, ENC_BIG_ENDIAN, &request_length);
    offset += 2;
    if (request_length > body_end - offset) {
        return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
    }

    {
        proto_item* request_item = proto_tree_add_item(tree,
            hf_pn_io_certification_request, tvb, offset, request_length,
            ENC_NA);
        if (request_length > 0 && pkcs10_handle != NULL) {
            proto_tree* request_tree = proto_item_add_subtree(request_item,
                ett_pn_io_certification_request);
            tvbuff_t* request_tvb = tvb_new_subset_length(tvb, offset,
                request_length);

            call_dissector(pkcs10_handle, request_tvb, pinfo, request_tree);
        }
    }
    return offset + request_length;
}

static int
dissect_SCMRequest_block(tvbuff_t* tvb, int offset, packet_info* pinfo,
    proto_tree* tree, proto_item* item, uint8_t* drep,
    uint8_t u8BlockVersionHigh, uint8_t u8BlockVersionLow, uint16_t u16BodyLength)
{
    int body_end = offset + u16BodyLength;
    uint16_t operation;

    if (u8BlockVersionHigh != 1 || u8BlockVersionLow != 0) {
        expert_add_info_format(pinfo, item, &ei_pn_io_block_version,
            "Block version %u.%u not implemented yet!", u8BlockVersionHigh,
            u8BlockVersionLow);
        return offset;
    }
    if (body_end - offset < 2) {
        return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
    }

    offset = dissect_dcerpc_uint16(tvb, offset, pinfo, tree, drep,
        hf_pn_io_scm_operation, &operation);
    switch (operation) {
    case 0x0001:
    case 0x0003:
    case 0x000D:
        break;
    case 0x0004:
    case 0x0005:
    case 0x0009:
    case 0x000B:
        offset = dissect_SCM_devid_domain(tvb, offset, body_end, pinfo, tree,
            drep);
        break;
    case 0x0006:
        offset = dissect_SCM_devid_domain(tvb, offset, body_end, pinfo, tree,
            drep);
        if (offset < body_end) {
            int request_info_length = body_end - offset;
            proto_item* request_info_item = proto_tree_add_item(tree,
                hf_pn_io_certification_request_information, tvb, offset,
                request_info_length, ENC_NA);

            if (pkcs10_cri_handle != NULL) {
                proto_tree* request_info_tree = proto_item_add_subtree(
                    request_info_item, ett_pn_io_certification_request_information);
                tvbuff_t* request_info_tvb = tvb_new_subset_length(tvb, offset,
                    request_info_length);

                call_dissector(pkcs10_cri_handle, request_info_tvb, pinfo,
                    request_info_tree);
            }
            offset = body_end;
        }
        break;
    case 0x0008:
        offset = dissect_SCM_devid_domain(tvb, offset, body_end, pinfo, tree,
            drep);
        if (offset < body_end) {
            offset = dissect_SCM_ee_certification_path(tvb, offset, body_end,
                pinfo, tree, drep);
        }
        break;
    case 0x000A:
        offset = dissect_SCM_devid_domain(tvb, offset, body_end, pinfo, tree,
            drep);
        if (offset < body_end) {
            offset = dissect_SCM_certificate(tvb, offset, body_end, pinfo,
                tree);
        }
        break;
    case 0x000C:
        offset = dissect_SCM_security_configuration_parameters(tvb, offset,
            body_end, pinfo, tree);
        break;
    default:
        return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
    }
    return dissect_SCM_padding(tvb, offset, body_end, pinfo, tree);
}

static int
dissect_SCMResponse_block(tvbuff_t* tvb, int offset, packet_info* pinfo,
    proto_tree* tree, proto_item* item, uint8_t* drep,
    uint8_t u8BlockVersionHigh, uint8_t u8BlockVersionLow, uint16_t u16BodyLength)
{
    int body_end = offset + u16BodyLength;
    uint16_t operation;

    if (u8BlockVersionHigh != 1 || u8BlockVersionLow != 0) {
        expert_add_info_format(pinfo, item, &ei_pn_io_block_version,
            "Block version %u.%u not implemented yet!", u8BlockVersionHigh,
            u8BlockVersionLow);
        return offset;
    }
    if (body_end - offset < 2) {
        return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
    }

    offset = dissect_dcerpc_uint16(tvb, offset, pinfo, tree, drep,
        hf_pn_io_scm_operation, &operation);
    switch (operation) {
    case 0x0001:
        offset = dissect_SCM_security_capabilities(tvb, offset, body_end,
            pinfo, tree, drep);
        break;
    case 0x0003:
        offset = dissect_SCM_security_configuration_parameters(tvb, offset,
            body_end, pinfo, tree);
        break;
    case 0x0004:
        offset = dissect_SCM_ee_certification_path(tvb, offset, body_end,
            pinfo, tree, drep);
        break;
    case 0x0005:
        offset = dissect_SCM_certificate(tvb, offset, body_end, pinfo, tree);
        break;
    case 0x0006:
        offset = dissect_SCM_certification_request(tvb, offset, body_end,
            pinfo, tree);
        break;
    case 0x0008:
    case 0x0009:
    case 0x000A:
    case 0x000B:
    case 0x000C:
    case 0x000D:
        break;
    default:
        return dissect_SCM_undecoded(tvb, offset, body_end, pinfo, tree);
    }
    return dissect_SCM_padding(tvb, offset, body_end, pinfo, tree);
}

static int
dissect_ARRecordAccessPolicy_block(tvbuff_t *tvb, int offset,
    packet_info *pinfo, proto_tree *tree, proto_item *item, uint8_t *drep,
    uint8_t u8BlockVersionHigh, uint8_t u8BlockVersionLow, uint16_t u16BodyLength)
{
    uint16_t number_of_entries;
    uint16_t entry_index;
    uint16_t value16;
    uint32_t value32;
    int body_end = offset + u16BodyLength;

    if (u8BlockVersionHigh != 1 || u8BlockVersionLow != 0) {
        expert_add_info_format(pinfo, item, &ei_pn_io_block_version,
            "Block version %u.%u not implemented yet!", u8BlockVersionHigh, u8BlockVersionLow);
        return offset;
    }

    if (u16BodyLength < 2)
        return dissect_pn_undecoded(tvb, offset, pinfo, tree, u16BodyLength);

    offset = dissect_dcerpc_uint16(tvb, offset, pinfo, tree, drep,
        hf_pn_io_number_of_entries, &number_of_entries);

    for (entry_index = 0; entry_index < number_of_entries && body_end - offset >= 16; entry_index++) {
        proto_item *entry_item;
        proto_tree *entry_tree;

        entry_item = proto_tree_add_item(tree, hf_pn_io_record_policy_set_data,
            tvb, offset, 16, ENC_NA);
        entry_tree = proto_item_add_subtree(entry_item, ett_pn_io_record_policy_set_data);
        proto_item_append_text(entry_item, " %u", entry_index + 1);

        proto_tree_add_item(entry_tree, hf_pn_io_ra_condition, tvb, offset, 2, ENC_BIG_ENDIAN);
        dissect_dcerpc_uint16(tvb, offset, pinfo, entry_tree, drep,
            hf_pn_io_ra_condition_reserved, &value16);
        offset = dissect_dcerpc_uint16(tvb, offset, pinfo, entry_tree, drep,
            hf_pn_io_ra_condition_ar_type, &value16);

        proto_tree_add_item(entry_tree, hf_pn_io_ra_access, tvb, offset, 2, ENC_BIG_ENDIAN);
        dissect_dcerpc_uint16(tvb, offset, pinfo, entry_tree, drep,
            hf_pn_io_ra_access_reserved, &value16);
        offset = dissect_dcerpc_uint16(tvb, offset, pinfo, entry_tree, drep,
            hf_pn_io_ra_access_type, &value16);

        proto_tree_add_item(entry_tree, hf_pn_io_ra_resource_slot, tvb, offset, 4, ENC_BIG_ENDIAN);
        dissect_dcerpc_uint32(tvb, offset, pinfo, entry_tree, drep,
            hf_pn_io_ra_resource_slot_end, &value32);
        offset = dissect_dcerpc_uint32(tvb, offset, pinfo, entry_tree, drep,
            hf_pn_io_ra_resource_slot_start, &value32);

        proto_tree_add_item(entry_tree, hf_pn_io_ra_resource_subslot, tvb, offset, 4, ENC_BIG_ENDIAN);
        dissect_dcerpc_uint32(tvb, offset, pinfo, entry_tree, drep,
            hf_pn_io_ra_resource_subslot_end, &value32);
        offset = dissect_dcerpc_uint32(tvb, offset, pinfo, entry_tree, drep,
            hf_pn_io_ra_resource_subslot_start, &value32);

        proto_tree_add_item(entry_tree, hf_pn_io_ra_resource_index, tvb, offset, 4, ENC_BIG_ENDIAN);
        dissect_dcerpc_uint32(tvb, offset, pinfo, entry_tree, drep,
            hf_pn_io_ra_resource_index_end, &value32);
        offset = dissect_dcerpc_uint32(tvb, offset, pinfo, entry_tree, drep,
            hf_pn_io_ra_resource_index_start, &value32);
    }

    if (offset < body_end)
        offset = dissect_pn_undecoded(tvb, offset, pinfo, tree, body_end - offset);

    return offset;
}

static int
dissect_sxp_sam_blocks(tvbuff_t *tvb, int offset, packet_info *pinfo, proto_tree *tree,
    const uint16_t *expected_types, unsigned required_count, unsigned expected_count)
{
    int start_offset = offset;
    unsigned block_index = 0;

    while (tvb_captured_length_remaining(tvb, offset) > 0 && block_index < expected_count) {
        int remaining = tvb_captured_length_remaining(tvb, offset);
        uint16_t block_type;
        uint16_t block_length;
        int block_size;

        if (remaining < 4) {
            break;
        }

        block_type = tvb_get_uint16(tvb, offset, ENC_BIG_ENDIAN);
        if (block_type != expected_types[block_index]) {
            break;
        }

        block_length = tvb_get_uint16(tvb, offset + 2, ENC_BIG_ENDIAN);
        block_size = block_length + 4;
        if (block_length < 2 || block_size > remaining) {
            proto_tree_add_expert_format(tree, pinfo, &ei_pn_sxp_malformed,
                tvb, offset, remaining, "Invalid SAM block length %u",
                block_length);
            break;
        }

        offset += block_size;
        block_index++;
    }

    if (block_index < required_count) {
        proto_tree_add_expert_format(tree, pinfo, &ei_pn_sxp_malformed, tvb, offset, 0,
            "Missing mandatory SAM block 0x%04x at position %u",
            expected_types[block_index], block_index + 1);
    }

    if (offset > start_offset) {
        tvbuff_t *blocks_tvb = tvb_new_subset_length(tvb, start_offset,
            offset - start_offset);

        dissect_sxp_pnio_blocks(blocks_tvb, 0, pinfo, tree);
    }

    if (tvb_captured_length_remaining(tvb, offset) > 0) {
        proto_tree_add_expert_format(tree, pinfo, &ei_pn_sxp_malformed, tvb, offset,
            MIN(tvb_captured_length_remaining(tvb, offset), 2),
            "Unexpected data after the SAM block sequence");
        return dissect_pn_user_data(tvb, offset, pinfo, tree,
            tvb_captured_length_remaining(tvb, offset), "UnexpectedSAMData");
    }
    return offset;
}

static int
dissect_sxp_samservice_req(tvbuff_t *tvb, int offset, packet_info *pinfo, proto_tree *tree)
{
    static const uint16_t expected_types[] = { 0x06E0, 0x06E2 };
    uint16_t block_type, block_length;
    uint32_t max_rsp_len;
    proto_item *pdu_item;
    proto_tree *pdu_tree;
    int start_offset;

    offset = dissect_sxp_header_req(tvb, offset, pinfo, tree, &block_type,
        &block_length, &max_rsp_len);
    if (tvb_captured_length_remaining(tvb, offset) > 0) {
        start_offset = offset;
        pdu_item = proto_tree_add_item(tree, hf_pn_sxp_pnservice_req_pdu, tvb,
            offset, tvb_captured_length_remaining(tvb, offset), ENC_NA);
        pdu_tree = proto_item_add_subtree(pdu_item,
            ett_pn_sxp_pnservice_req_pdu);
        offset = dissect_sxp_sam_blocks(tvb, offset, pinfo, pdu_tree,
            expected_types, 1, 2);
        proto_item_set_len(pdu_item, offset - start_offset);
    }
    return offset;
}

static tvbuff_t *
dissect_sxp_security(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree,
    bool *encrypted)
{
    uint8_t security_information;
    uint8_t security_control;
    uint16_t security_length_raw;
    uint16_t security_length;
    uint32_t security_sequence_counter;
    int protected_length = tvb_captured_length(tvb);
    proto_item *metadata_item;
    proto_tree *metadata_tree;
    proto_item *information_item;
    proto_tree *information_tree;
    proto_item *control_item;
    proto_tree *control_tree;
    proto_item *length_item;
    proto_tree *length_tree;

    *encrypted = false;
    if (protected_length < SXP_SECURITY_METADATA_LENGTH + SXP_SECURITY_CHECKSUM_LENGTH) {
        return tvb;
    }

    security_information = tvb_get_uint8(tvb, 0);
    security_control = tvb_get_uint8(tvb, 1);
    security_sequence_counter = tvb_get_ntohl(tvb, 2);
    security_length_raw = tvb_get_ntohs(tvb, 6);
    security_length = security_length_raw & 0x07FF;

    if ((security_information & 0xFE) != 0 ||
        (security_control & 0xF0) != 0 ||
        security_sequence_counter == 0 ||
        (security_length_raw & 0xF800) != 0 ||
        security_length == 0 ||
        protected_length != SXP_SECURITY_METADATA_LENGTH + security_length +
            SXP_SECURITY_CHECKSUM_LENGTH) {
        return tvb;
    }

    metadata_item = proto_tree_add_item(tree, hf_pn_sxp_security_metadata,
        tvb, 0, SXP_SECURITY_METADATA_LENGTH, ENC_NA);
    metadata_tree = proto_item_add_subtree(metadata_item,
        ett_pn_sxp_security_metadata);

    information_item = proto_tree_add_item(metadata_tree,
        hf_pn_sxp_security_information, tvb, 0, 1, ENC_BIG_ENDIAN);
    information_tree = proto_item_add_subtree(information_item,
        ett_pn_sxp_security_information);
    proto_tree_add_item(information_tree,
        hf_pn_sxp_security_information_protection_mode, tvb, 0, 1,
        ENC_BIG_ENDIAN);
    proto_tree_add_item(information_tree,
        hf_pn_sxp_security_information_reserved, tvb, 0, 1, ENC_BIG_ENDIAN);

    control_item = proto_tree_add_item(metadata_tree, hf_pn_sxp_security_control,
        tvb, 1, 1, ENC_BIG_ENDIAN);
    control_tree = proto_item_add_subtree(control_item,
        ett_pn_sxp_security_control);
    proto_tree_add_item(control_tree,
        hf_pn_sxp_security_control_generation_number, tvb, 1, 1,
        ENC_BIG_ENDIAN);
    proto_tree_add_item(control_tree, hf_pn_sxp_security_control_reserved,
        tvb, 1, 1, ENC_BIG_ENDIAN);

    proto_tree_add_item(metadata_tree, hf_pn_sxp_security_sequence_counter,
        tvb, 2, 4, ENC_BIG_ENDIAN);
    length_item = proto_tree_add_item(metadata_tree, hf_pn_sxp_security_length,
        tvb, 6, 2, ENC_BIG_ENDIAN);
    length_tree = proto_item_add_subtree(length_item, ett_pn_sxp_security_length);
    proto_tree_add_item(length_tree, hf_pn_sxp_security_length_value, tvb, 6,
        2, ENC_BIG_ENDIAN);
    proto_tree_add_item(length_tree, hf_pn_sxp_security_length_reserved, tvb, 6,
        2, ENC_BIG_ENDIAN);

    if ((security_information & 0x01) == 0) {
        proto_tree_add_item(tree, hf_pn_sxp_security_checksum, tvb,
            SXP_SECURITY_METADATA_LENGTH + security_length,
            SXP_SECURITY_CHECKSUM_LENGTH, ENC_NA);
        col_append_sep_str(pinfo->cinfo, COL_INFO, ", ", "Authentication only");
        return tvb_new_subset_length(tvb, SXP_SECURITY_METADATA_LENGTH,
            security_length);
    }

    *encrypted = true;
    proto_tree_add_item(tree, hf_pn_sxp_security_data, tvb,
        SXP_SECURITY_METADATA_LENGTH,
        security_length + SXP_SECURITY_CHECKSUM_LENGTH, ENC_NA);
    col_append_sep_str(pinfo->cinfo, COL_INFO, ", ",
        "Authenticated encryption");
    return NULL;
}

static bool
sapenqueue_check_length(tvbuff_t *tvb, packet_info *pinfo, proto_item *item, uint32_t offset, int needed, const char *field_name)
{
	int remaining = tvb_reported_length_remaining(tvb, offset);

	if (remaining < needed) {
		expert_add_info_format(pinfo, item, &ei_sapenqueue_invalid_length, "%s is truncated (expected=%d, actual=%d)", field_name, needed, remaining > 0 ? remaining : 0);
		return false;
	}
	return true;
}

