	ATF_TP_ADD_TC(tp, exec_ordinary_keeps_pmc);
	ATF_TP_ADD_TC(tp, exec_setid_traced_keeps_pmc);
	ATF_TP_ADD_TC(tp, exec_fexecve_setid_drops_pmc);

	return (atf_no_error());
}

