    test_encode_command();
    test_encode_reply();
    test_result_ok_semantics();
    test_parse_fragmented_replies();
    test_parse_nested_array_and_bulk_string();
    test_null_array_round_trip();
    test_parse_hard_error_does_not_block_following_reply();
    test_parse_incomplete_does_not_set_error();
    test_parse_hard_error_in_nested_array_recovers();
    return 0;
}

static RedisReply authSelectOnlyHandler(const RedisCommand& cmd) {
    if (!cmd.empty() && (cmd[0] == "AUTH" || cmd[0] == "SELECT")) {
        RedisReply reply;
        reply.type = REDIS_REPLY_STRING;
        reply.str = "OK";
        return reply;
    }
    RedisReply reply;
    reply.type = REDIS_REPLY_ERROR;
    reply.str = "ERR unsupported";
    return reply;
}

void setupSubscriber(RedisSubscriber* subscriber, int port) {
    subscriber->setHost("127.0.0.1");
    subscriber->setPort(port);
    subscriber->setAuth("secret");
    subscriber->setDb(5);
}

void bindCallbacks(RedisSubscriber* subscriber, SubscriberCapture* capture, const std::string& name) {
    subscriber->onSubscribe = [capture, name](const std::string& subscribed_name) {
        std::lock_guard<std::mutex> lock(capture->mutex);
        if (subscribed_name == name) {
            ++capture->subscribed;
        }
        capture->cv.notify_one();
    };
    subscriber->onUnsubscribe = [capture, name](const std::string& unsubscribed_name) {
        std::lock_guard<std::mutex> lock(capture->mutex);
        if (unsubscribed_name == name) {
            ++capture->unsubscribed;
        }
        capture->cv.notify_one();
    };
    subscriber->onMessage = [capture](const std::string& channel, const std::string& message) {
        std::lock_guard<std::mutex> lock(capture->mutex);
        capture->messages.push_back(channel + ":" + message);
        capture->cv.notify_one();
    };
}

void expectPublishedMessage(SubscriberCapture* capture, const std::string& expected) {
    std::unique_lock<std::mutex> lock(capture->mutex);
    bool received = capture->cv.wait_for(lock, std::chrono::seconds(3), [capture]() { return capture->messages.size() == 1; });
    assert(received);
    assert(capture->messages[0] == expected);
}

void runSubscriptionFlow(const std::string& subscription_name,
                         const std::string& publish_channel,
                         const std::string& expected_message,
                         int (RedisSubscriber::*subscribe_fn)(const std::string&),
                         int (RedisSubscriber::*unsubscribe_fn)(const std::string&)) {
    FakeRedisServer server;
    server.setCommandHandler(authSelectOnlyHandler);
    server.start();

    RedisSubscriber subscriber;
    setupSubscriber(&subscriber, server.port());

    SubscriberCapture capture;
    bindCallbacks(&subscriber, &capture, subscription_name);

    subscriber.start();
    assert((subscriber.*subscribe_fn)(subscription_name) == 0);
    assert(waitForCount(capture.mutex, capture.cv, &capture.subscribed, 1));

    assert(server.publish(publish_channel, "hello") == 1);
    expectPublishedMessage(&capture, expected_message);

    assert((subscriber.*unsubscribe_fn)(subscription_name) == 0);
    assert(waitForCount(capture.mutex, capture.cv, &capture.unsubscribed, 1));
    assert(server.publish(publish_channel, "ignored") == 0);

    subscriber.stop(true);
    server.stop();
}

static void test_subscribe_without_start_is_rejected() {
    RedisSubscriber subscriber;
    assert(subscriber.subscribe("late") == ERR_CONNECT);
    assert(subscriber.psubscribe("late:*") == ERR_CONNECT);
}

int main() {
    test_subscribe_and_message_callback();
    test_psubscribe_and_punsubscribe_callback();
    test_subscribe_without_start_is_rejected();
    return 0;
}

static std::shared_ptr<ClientState> getOrCreateState(const hv::SocketChannelPtr& channel) {
        std::shared_ptr<ClientState> state = channel->getContextPtr<ClientState>();
        if (!state) {
            state = channel->newContextPtr<ClientState>();
        }
        return state;
    }

static hv::RedisReply makeStringReply(const std::string& value, bool bulk = false) {
        hv::RedisReply reply;
        reply.type = hv::REDIS_REPLY_STRING;
        reply.str = value;
        reply.bulk = bulk;
        return reply;
    }

static hv::RedisReply makeIntegerReply(int64_t value) {
        hv::RedisReply reply;
        reply.type = hv::REDIS_REPLY_INTEGER;
        reply.integer = value;
        return reply;
    }

static hv::RedisReply makeErrorReply(const std::string& error) {
        hv::RedisReply reply;
        reply.type = hv::REDIS_REPLY_ERROR;
        reply.str = error;
        return reply;
    }

static hv::RedisReply makeArrayReply(const std::string& kind, const std::string& name, int64_t count) {
        hv::RedisReply reply;
        reply.type = hv::REDIS_REPLY_ARRAY;
        reply.elements.push_back(makeStringReply(kind, true));
        reply.elements.push_back(makeStringReply(name, true));
        reply.elements.push_back(makeIntegerReply(count));
        return reply;
    }

hv::RedisReply makePubSubReply(const hv::RedisCommand& command, const std::shared_ptr<ClientState>& state) {
        if (command.size() != 2) {
            return makeErrorReply("ERR wrong number of arguments");
        }
        const std::string& name = command[1];
        if (commandEquals(command, "SUBSCRIBE")) {
            state->channels.insert(name);
            return makeArrayReply("subscribe", name, (int64_t)(state->channels.size() + state->patterns.size()));
        }
        if (commandEquals(command, "PSUBSCRIBE")) {
            state->patterns.insert(name);
            return makeArrayReply("psubscribe", name, (int64_t)(state->channels.size() + state->patterns.size()));
        }
        if (commandEquals(command, "UNSUBSCRIBE")) {
            state->channels.erase(name);
            return makeArrayReply("unsubscribe", name, (int64_t)(state->channels.size() + state->patterns.size()));
        }
        state->patterns.erase(name);
        return makeArrayReply("punsubscribe", name, (int64_t)(state->channels.size() + state->patterns.size()));
    }

hv::RedisReply makeReply(const hv::RedisReply& request, const std::shared_ptr<ClientState>& state) {
        if (!request.isArray()) {
            return makeErrorReply("ERR invalid command");
        }

        hv::RedisCommand command;
        command.reserve(request.elements.size());
        for (size_t i = 0; i < request.elements.size(); ++i) {
            const hv::RedisReply& arg = request.elements[i];
            if (!arg.isString()) {
                return makeErrorReply("ERR invalid command arg");
            }
            command.push_back(arg.str);
        }

        if (commandEquals(command, "SUBSCRIBE") || commandEquals(command, "PSUBSCRIBE") || commandEquals(command, "UNSUBSCRIBE") || commandEquals(command, "PUNSUBSCRIBE")) {
            return makePubSubReply(command, state);
        }

        if (handler) {
            return handler(command);
        }

        return makeStringReply("OK");
    }

int publish(const std::string& channel, const std::string& message) {
        if (!server) {
            return 0;
        }

        int delivered = 0;
        server->foreachChannel([&](const hv::SocketChannelPtr& client) {
            std::shared_ptr<ClientState> state = client->getContextPtr<ClientState>();
            if (!state) {
                return;
            }
            if (state->channels.count(channel) != 0) {
                hv::RedisReply push;
                push.type = hv::REDIS_REPLY_ARRAY;
                push.elements.push_back(makeStringReply("message", true));
                push.elements.push_back(makeStringReply(channel, true));
                push.elements.push_back(makeStringReply(message, true));
                client->write(hv::RedisEncodeReply(push));
                ++delivered;
            }
            for (std::set<std::string>::const_iterator it = state->patterns.begin(); it != state->patterns.end(); ++it) {
                if (!hv_wildcard_match(channel.c_str(), it->c_str())) {
                    continue;
                }
                hv::RedisReply push;
                push.type = hv::REDIS_REPLY_ARRAY;
                push.elements.push_back(makeStringReply("pmessage", true));
                push.elements.push_back(makeStringReply(*it, true));
                push.elements.push_back(makeStringReply(channel, true));
                push.elements.push_back(makeStringReply(message, true));
                client->write(hv::RedisEncodeReply(push));
                ++delivered;
            }
        });
        return delivered;
    }

void FakeRedisServer::start() {
    stop();
    impl_->server = std::make_shared<hv::TcpServer>();
    impl_->server->createsocket(impl_->port, "127.0.0.1");
    if (impl_->server->listenfd >= 0) {
        sockaddr_u addr;
        socklen_t len = sizeof(addr);
        memset(&addr, 0, sizeof(addr));
        if (getsockname(impl_->server->listenfd, &addr.sa, &len) == 0) {
            impl_->port = sockaddr_port(&addr);
        }
    }

    impl_->server->onConnection = [](const hv::SocketChannelPtr& channel) {
        if (channel->isConnected()) {
            channel->newContextPtr<Impl::ClientState>();
        }
    };

    impl_->server->onMessage = [this](const hv::SocketChannelPtr& channel, hv::Buffer* buf) {
        std::shared_ptr<Impl::ClientState> state = Impl::getOrCreateState(channel);
        state->parser.Feed((const char*)buf->data(), buf->size());
        if (state->parser.HasError()) {
            channel->close();
            return;
        }
        while (state->parser.HasReply()) {
            hv::RedisReply request = state->parser.NextReply();
            hv::RedisReply reply = impl_->makeReply(request, state);
            channel->write(hv::RedisEncodeReply(reply));
            if (impl_->close_after_reply) {
                channel->close();
                return;
            }
        }
    };

    impl_->server->start();
}

void FakeRedisServer::stop() {
    if (impl_->server) {
        impl_->server->stop(true);
        impl_->server.reset();
    }
}

hv::StringList HttpService::Paths() const {
    if (!HasRoutes()) {
        return hv::StringList();
    }
    return router->Paths();
}

int main() {
    hv::HttpRouter<int> router;
    std::map<std::string, std::string> params;
    int value = 0;

    router.Insert("/hello", 1);
    router.Insert("/users/:id", 2);
    router.Insert("/orders/{orderId}", 3);
    router.Insert("/wildcard*", 4);
    router.Insert("/www.*.html", 5);
    router.Insert("*", 404);
    router.Insert("/users/list", 6);
    router.Insert("/dup", 7);
    router.Insert("/dup", 8);

    assert(router.Match("/hello", value, params));
    assert(value == 1);
    assert(params.empty());
    printf("Match /hello\n");

    params.clear();
    assert(router.Match("/users/123", value, params));
    assert(value == 2);
    assert(params["id"] == "123");
    printf("Match /users/:id\n");

    params.clear();
    assert(router.Match("/orders/42", value, params));
    assert(value == 3);
    assert(params["orderId"] == "42");
    printf("Match /orders/{orderId}\n");

    params.clear();
    assert(router.Match("/wildcard-tail", value, params));
    assert(value == 4);
    assert(params.empty());
    printf("Match /wildcard*\n");

    params.clear();
    assert(router.Match("/www.index.html", value, params));
    assert(value == 5);
    assert(params.empty());
    printf("Match /www.*.html\n");

    params.clear();
    assert(router.Match("/users/list", value, params));
    assert(value == 6);
    assert(params.empty());
    printf("Match /users/list\n");

    params.clear();
    assert(router.Match("/dup", value, params));
    assert(value == 8);
    assert(params.empty());
    printf("Match /dup\n");

    params["keep"] = "yes";
    assert(router.Match("/missing", value, params));
    assert(value == 404);
    assert(params["keep"] == "yes");
    printf("Match *\n");

    std::vector<std::string> paths = router.Paths();
    int dup_count = 0;
    bool has_colon_param_route = false;
    bool has_brace_param_route = false;
    bool has_wildcard_route = false;
    bool has_suffix_wildcard_route = false;
    bool has_any_wildcard_route = false;
    for (const auto& path : paths) {
        if (path == "/dup") {
            ++dup_count;
        }
        if (path == "/users/:id") {
            has_colon_param_route = true;
        }
        if (path == "/orders/{orderId}") {
            has_brace_param_route = true;
        }
        if (path == "/wildcard*") {
            has_wildcard_route = true;
        }
        if (path == "/www.*.html") {
            has_suffix_wildcard_route = true;
        }
        if (path == "*") {
            has_any_wildcard_route = true;
        }
    }
    assert(dup_count == 1);
    assert(has_colon_param_route);
    assert(has_brace_param_route);
    assert(has_wildcard_route);
    assert(has_suffix_wildcard_route);
    assert(has_any_wildcard_route);

    hv::HttpRouter<std::shared_ptr<int>> literal_router;
    std::shared_ptr<int> literal_value;
    std::map<std::string, std::string> literal_params;

    literal_router.Insert("/users/:id", std::make_shared<int>(1));
    assert(!literal_router.Find("/users/list", literal_value));

    literal_value = std::make_shared<int>(2);
    literal_router.Insert("/users/list", literal_value);

    std::shared_ptr<int> matched_value;
    literal_params.clear();
    assert(literal_router.Match("/users/list", matched_value, literal_params));
    assert(matched_value);
    assert(*matched_value == 2);
    assert(literal_params.empty());
    printf("Match /users/list\n");

    literal_params.clear();
    assert(literal_router.Match("/users/123", matched_value, literal_params));
    assert(matched_value);
    assert(*matched_value == 1);
    assert(literal_params["id"] == "123");
    printf("Match /users/:id\n");

    return 0;
}

int iowatcher_init(hloop_t* loop) {
    if (loop->iowatcher) return 0;
    io_uring_ctx_t* ctx;
    HV_ALLOC_SIZEOF(ctx);
    int ret = io_uring_queue_init(IO_URING_ENTRIES, &ctx->ring, 0);
    if (ret < 0) {
        HV_FREE(ctx);
        return ret;
    }
    ctx->nfds = 0;
    loop->iowatcher = ctx;
    return 0;
}

int iowatcher_cleanup(hloop_t* loop) {
    if (loop->iowatcher == NULL) return 0;
    io_uring_ctx_t* ctx = (io_uring_ctx_t*)loop->iowatcher;
    io_uring_queue_exit(&ctx->ring);
    HV_FREE(loop->iowatcher);
    return 0;
}

static struct io_uring_sqe* io_uring_get_sqe_safe(struct io_uring* ring) {
    struct io_uring_sqe* sqe = io_uring_get_sqe(ring);
    if (sqe == NULL) {
        // SQ is full, flush pending submissions and retry
        io_uring_submit(ring);
        sqe = io_uring_get_sqe(ring);
    }
    return sqe;
}

int iowatcher_add_event(hloop_t* loop, int fd, int events) {
    if (loop->iowatcher == NULL) {
        int ret = iowatcher_init(loop);
        if (ret < 0) {
            return ret;
        }
    }
    io_uring_ctx_t* ctx = (io_uring_ctx_t*)loop->iowatcher;
    hio_t* io = loop->ios.ptr[fd];

    unsigned poll_mask = 0;
    // pre events
    if (io->events & HV_READ) {
        poll_mask |= POLLIN;
    }
    if (io->events & HV_WRITE) {
        poll_mask |= POLLOUT;
    }
    // now events
    if (events & HV_READ) {
        poll_mask |= POLLIN;
    }
    if (events & HV_WRITE) {
        poll_mask |= POLLOUT;
    }

    struct io_uring_sqe* sqe;
    if (io->events != 0) {
        // Cancel the existing poll request first
        sqe = io_uring_get_sqe_safe(&ctx->ring);
        if (sqe == NULL) return -1;
        io_uring_prep_poll_remove(sqe, (uint64_t)fd);
        io_uring_sqe_set_data(sqe, IO_URING_CANCEL_TAG);
    } else {
        ctx->nfds++;
    }

    // Add poll for the combined events
    sqe = io_uring_get_sqe_safe(&ctx->ring);
    if (sqe == NULL) return -1;
    io_uring_prep_poll_add(sqe, fd, poll_mask);
    io_uring_sqe_set_data(sqe, (void*)(uintptr_t)fd);

    io_uring_submit(&ctx->ring);
    return 0;
}

int iowatcher_del_event(hloop_t* loop, int fd, int events) {
    io_uring_ctx_t* ctx = (io_uring_ctx_t*)loop->iowatcher;
    if (ctx == NULL) return 0;
    hio_t* io = loop->ios.ptr[fd];

    // Calculate remaining events
    unsigned poll_mask = 0;
    // pre events
    if (io->events & HV_READ) {
        poll_mask |= POLLIN;
    }
    if (io->events & HV_WRITE) {
        poll_mask |= POLLOUT;
    }
    // now events
    if (events & HV_READ) {
        poll_mask &= ~POLLIN;
    }
    if (events & HV_WRITE) {
        poll_mask &= ~POLLOUT;
    }

    // Cancel existing poll
    struct io_uring_sqe* sqe = io_uring_get_sqe_safe(&ctx->ring);
    if (sqe == NULL) return -1;
    io_uring_prep_poll_remove(sqe, (uint64_t)fd);
    io_uring_sqe_set_data(sqe, IO_URING_CANCEL_TAG);

    if (poll_mask == 0) {
        ctx->nfds--;
    } else {
        // Re-add with remaining events
        sqe = io_uring_get_sqe_safe(&ctx->ring);
        if (sqe == NULL) return -1;
        io_uring_prep_poll_add(sqe, fd, poll_mask);
        io_uring_sqe_set_data(sqe, (void*)(uintptr_t)fd);
    }

    io_uring_submit(&ctx->ring);
    return 0;
}

int iowatcher_poll_events(hloop_t* loop, int timeout) {
    io_uring_ctx_t* ctx = (io_uring_ctx_t*)loop->iowatcher;
    if (ctx == NULL) return 0;
    if (ctx->nfds == 0) return 0;

    struct __kernel_timespec ts;
    struct __kernel_timespec* tp = NULL;
    if (timeout != INFINITE) {
        ts.tv_sec = timeout / 1000;
        ts.tv_nsec = (timeout % 1000) * 1000000LL;
        tp = &ts;
    }

    struct io_uring_cqe* cqe;
    int ret;
    if (tp) {
        ret = io_uring_wait_cqe_timeout(&ctx->ring, &cqe, tp);
    } else {
        ret = io_uring_wait_cqe(&ctx->ring, &cqe);
    }
    if (ret < 0) {
        if (ret == -ETIME || ret == -EINTR) {
            return 0;
        }
        perror("io_uring_wait_cqe");
        return ret;
    }

    int nevents = 0;
    int sqe_queued = 0;
    unsigned nready = io_uring_cq_ready(&ctx->ring);
    unsigned i;
    for (i = 0; i < nready; ++i) {
        if (io_uring_peek_cqe(&ctx->ring, &cqe) != 0) break;
        void* data = io_uring_cqe_get_data(cqe);
        if (data == IO_URING_CANCEL_TAG) {
            io_uring_cqe_seen(&ctx->ring, cqe);
            continue;
        }

        int fd = (int)(uintptr_t)data;
        if (fd < 0 || fd >= loop->ios.maxsize) {
            io_uring_cqe_seen(&ctx->ring, cqe);
            continue;
        }
        hio_t* io = loop->ios.ptr[fd];
        if (io == NULL) {
            io_uring_cqe_seen(&ctx->ring, cqe);
            continue;
        }

        if (cqe->res < 0) {
            // Poll request failed: notify registered events, or both if none registered
            io->revents |= (io->events ? io->events : HV_RDWR);
            EVENT_PENDING(io);
            ++nevents;
        } else {
            int revents = cqe->res;
            if (revents & (POLLIN | POLLHUP | POLLERR)) {
                io->revents |= HV_READ;
            }
            if (revents & (POLLOUT | POLLHUP | POLLERR)) {
                io->revents |= HV_WRITE;
            }
            if (io->revents) {
                EVENT_PENDING(io);
                ++nevents;
            }
        }

        io_uring_cqe_seen(&ctx->ring, cqe);

        // io_uring POLL_ADD is one-shot, re-arm for the same events
        unsigned remask = 0;
        if (io->events & HV_READ) remask |= POLLIN;
        if (io->events & HV_WRITE) remask |= POLLOUT;
        if (remask) {
            struct io_uring_sqe* sqe = io_uring_get_sqe_safe(&ctx->ring);
            if (sqe) {
                io_uring_prep_poll_add(sqe, fd, remask);
                io_uring_sqe_set_data(sqe, (void*)(uintptr_t)fd);
                sqe_queued = 1;
            }
        }
    }

    if (sqe_queued) {
        io_uring_submit(&ctx->ring);
    }

    return nevents;
}

static int mqtt_v5_skip_properties(unsigned char** pp, unsigned char* end) {
    unsigned char* p = *pp;
    int bytes = end - p;
    if (bytes <= 0) return 0;
    int prop_len = (int)varint_decode(p, &bytes);
    if (bytes <= 0) return 0;
    p += bytes;     // skip varint bytes
    if (p + prop_len > end) return 0;
    p += prop_len;  // skip properties data
    *pp = p;
    return 1;
}

TEST(HtmlToPlainText, StripsTagsAndKeepsText) {
  EXPECT_EQ(htmlToPlainText("<b>quixotic</b> <i>adj.</i>"), "quixotic adj.");
  EXPECT_EQ(htmlToPlainText("<span class=\"x\">in span</span>"), "in span");
  EXPECT_EQ(htmlToPlainText("plain"), "plain");
  EXPECT_EQ(htmlToPlainText(""), "");
}

TEST(HtmlToPlainText, BlockElementsBecomeBreaks) {
  EXPECT_EQ(htmlToPlainText("a<br>b"), "a\nb");
  EXPECT_EQ(htmlToPlainText("<div>a</div><div>b</div>"), "a\nb");
  EXPECT_EQ(htmlToPlainText("<p>a</p><p>b</p>"), "a\n\nb");
  // Consecutive breaks do not stack up.
  EXPECT_EQ(htmlToPlainText("a<br><br><br>b"), "a\nb");
}

TEST(HtmlToPlainText, HeadingsBreakLikeParagraphs) {
  // tagBreak() lists h1-h6 among the paragraph-breaking names, so they must
  // actually reach that comparison -- a name scan that stops at the first digit
  // reads "h1" as "h" and the heading runs into the text after it.
  for (const char* tag : {"h1", "h2", "h3", "h4", "h5", "h6"}) {
    const std::string html = std::string("<") + tag + ">title</" + tag + ">body";
    EXPECT_EQ(htmlToPlainText(html), "title\n\nbody") << tag;
  }
  EXPECT_EQ(htmlToPlainText("<hr>after"), "after");
}

TEST(HtmlToPlainText, DecodesEntities) {
  EXPECT_EQ(htmlToPlainText("Tom &amp; Jerry"), "Tom & Jerry");
  EXPECT_EQ(htmlToPlainText("a&nbsp;b"),
            "a\xC2\xA0"
            "b");
  EXPECT_EQ(htmlToPlainText("&#65;&#66;"), "AB");
  EXPECT_EQ(htmlToPlainText("&#x2014;"), "\xE2\x80\x94");
  // Not entities: left as written rather than swallowed.
  EXPECT_EQ(htmlToPlainText("&notanentity;"), "&notanentity;");
  EXPECT_EQ(htmlToPlainText("100% & up"), "100% & up");
}

TEST(HtmlToPlainText, TrimsSurroundingWhitespace) {
  EXPECT_EQ(htmlToPlainText("<p>only</p>"), "only");
  EXPECT_EQ(htmlToPlainText("text   "), "text");
  EXPECT_EQ(htmlToPlainText("a\tb"), "a b");
  EXPECT_EQ(htmlToPlainText("<br>a"), "a");
}

TEST(HtmlToPlainText, SurvivesMalformedMarkup) {
  EXPECT_EQ(htmlToPlainText("a <b"), "a <b");
  EXPECT_EQ(htmlToPlainText("x < y"), "x < y");
  EXPECT_EQ(htmlToPlainText("<!-- comment -->kept"), "kept");
}

dp_copy_header_value(const char *p, int remaining, char *out, int outLen)
{
    while (remaining > 0 && (*p == ' ' || *p == '\t')) {
        p++;
        remaining--;
    }
    int i = 0;
    while (remaining > 0 && *p != '\r' && *p != '\n' && i < outLen - 1) {
        out[i++] = *p++;
        remaining--;
    }
    out[i] = '\0';
    while (i > 0 && (out[i - 1] == ' ' || out[i - 1] == '\t')) {
        out[--i] = '\0';
    }
    return i;
}

/*********

sdp_emit(int fieldId, ArkimeSession_t *session, const char *val, int vlen)
{
    if (fieldId < 0 || vlen <= 0) return;
    arkime_field_string_add(fieldId, session, val, vlen, TRUE);
}

/*********

sdp_extract(ArkimeSession_t *session, const uint8_t *data, int len)
{
    const char *p = (const char *)data;
    const char *end = p + len;

    // Skip the first line (request-line or status-line).
    while (p < end && *p != '\n') p++;
    if (p < end) p++;

    while (p < end) {
        const char *lineStart = p;
        while (p < end && *p != '\n') p++;
        int lineLen = p - lineStart;
        if (lineLen > 0 && lineStart[lineLen - 1] == '\r') lineLen--;
        if (lineLen == 0) break; // end of headers

        const char *colon = memchr(lineStart, ':', lineLen);
        if (colon) {
            int nameLen = colon - lineStart;
            const char *val = colon + 1;
            int remaining = lineLen - nameLen - 1;
            char vbuf[1024];
            int vlen;

            // Case-insensitive header name match.
            if (nameLen == 6 && g_ascii_strncasecmp(lineStart, "SERVER", 6) == 0) {
                vlen = ssdp_copy_header_value(val, remaining, vbuf, sizeof(vbuf));
                ssdp_emit(serverField, session, vbuf, vlen);
            } else if (nameLen == 10 && g_ascii_strncasecmp(lineStart, "USER-AGENT", 10) == 0) {
                vlen = ssdp_copy_header_value(val, remaining, vbuf, sizeof(vbuf));
                ssdp_emit(userAgentField, session, vbuf, vlen);
            } else if (nameLen == 2 && g_ascii_strncasecmp(lineStart, "ST", 2) == 0) {
                vlen = ssdp_copy_header_value(val, remaining, vbuf, sizeof(vbuf));
                ssdp_emit(stField, session, vbuf, vlen);
            } else if (nameLen == 2 && g_ascii_strncasecmp(lineStart, "NT", 2) == 0) {
                vlen = ssdp_copy_header_value(val, remaining, vbuf, sizeof(vbuf));
                ssdp_emit(ntField, session, vbuf, vlen);
            } else if (nameLen == 3 && g_ascii_strncasecmp(lineStart, "USN", 3) == 0) {
                vlen = ssdp_copy_header_value(val, remaining, vbuf, sizeof(vbuf));
                ssdp_emit(usnField, session, vbuf, vlen);
            } else if (nameLen == 8 && g_ascii_strncasecmp(lineStart, "LOCATION", 8) == 0) {
                vlen = ssdp_copy_header_value(val, remaining, vbuf, sizeof(vbuf));
                ssdp_emit(locationField, session, vbuf, vlen);
            }
        }

        if (p < end) p++; // consume LF
    }
}

/*********

dp_udp_parser(ArkimeSession_t *session, void *UNUSED(uw), const uint8_t *data, int len, int UNUSED(which))
{
    if (len < 8) return 0;
    if (data[0] != 'M' && data[0] != 'N' && data[0] != 'H') return 0;

    int isReq = (len >= 9 && memcmp(data, "M-SEARCH ", 9) == 0) ||
                (len >= 9 && memcmp(data, "NOTIFY * ", 9) == 0);
    int isResp = (len >= 7 && memcmp(data, "HTTP/1.", 7) == 0);
    if (!isReq && !isResp) return 0;

    ssdp_extract(session, data, len);
    return 0;
}

/*********

sdp_classify(ArkimeSession_t *session, const uint8_t *data, int len, int UNUSED(which), void *UNUSED(uw))
{
    // Already classified (e.g. the other direction fired first): the
    // registered per-session parser handles this packet, don't re-register.
    if (arkime_session_has_protocol(session, "ssdp"))
        return;

    // Quick gate: must look like HTTP-style start (request or status).
    if (len < 8) return;
    if (data[0] != 'M' && data[0] != 'N' && data[0] != 'H') return;

    int isReq = (len >= 9 && memcmp(data, "M-SEARCH ", 9) == 0) ||
                (len >= 9 && memcmp(data, "NOTIFY * ", 9) == 0);
    int isResp = (len >= 7 && memcmp(data, "HTTP/1.", 7) == 0);

    if (!isReq && !isResp) return;

    // For HTTP responses, only accept if it looks UPnP-ish.
    if (isResp) {
        if (!arkime_memstr((const char *)data, len, "\r\nST:", 5) &&
            !arkime_memstr((const char *)data, len, "\r\nUSN:", 6) &&
            !arkime_memstr((const char *)data, len, "UPnP", 4))
            return;
    }

    arkime_session_add_protocol(session, "ssdp");
    ssdp_extract(session, data, len);

    // Register a parser so subsequent packets in this session (e.g. NOTIFY after M-SEARCH,
    // or multiple NOTIFYs) also get header extraction.
    arkime_parsers_register(session, ssdp_udp_parser, NULL, 0);
}

/*********

parser_init()
{
    serverField = arkime_field_define("ssdp", "termfield",
                                      "ssdp.server", "Server", "ssdp.server",
                                      "SSDP/UPnP Server header",
                                      ARKIME_FIELD_TYPE_STR_GHASH, ARKIME_FIELD_FLAG_CNT,
                                      (char *)NULL);

    userAgentField = arkime_field_define("ssdp", "termfield",
                                         "ssdp.userAgent", "User Agent", "ssdp.userAgent",
                                         "SSDP/UPnP User-Agent header",
                                         ARKIME_FIELD_TYPE_STR_GHASH, ARKIME_FIELD_FLAG_CNT,
                                         (char *)NULL);

    stField = arkime_field_define("ssdp", "termfield",
                                  "ssdp.st", "Search Target", "ssdp.st",
                                  "SSDP M-SEARCH Search Target",
                                  ARKIME_FIELD_TYPE_STR_GHASH, ARKIME_FIELD_FLAG_CNT,
                                  (char *)NULL);

    ntField = arkime_field_define("ssdp", "termfield",
                                  "ssdp.nt", "Notification Type", "ssdp.nt",
                                  "SSDP NOTIFY Notification Type",
                                  ARKIME_FIELD_TYPE_STR_GHASH, ARKIME_FIELD_FLAG_CNT,
                                  (char *)NULL);

    usnField = arkime_field_define("ssdp", "termfield",
                                   "ssdp.usn", "USN", "ssdp.usn",
                                   "SSDP Unique Service Name",
                                   ARKIME_FIELD_TYPE_STR_GHASH, ARKIME_FIELD_FLAG_CNT,
                                   (char *)NULL);

    locationField = arkime_field_define("ssdp", "termfield",
                                        "ssdp.location", "Location", "ssdp.location",
                                        "SSDP/UPnP Location URL",
                                        ARKIME_FIELD_TYPE_STR_GHASH, ARKIME_FIELD_FLAG_CNT,
                                        (char *)NULL);

    // Content-based triggers (formerly in misc.c) so any-port SSDP is both
    // classified and extracted; ssdp_classify re-verifies and guards HTTP
    // responses with the UPnP-ish header check.
    arkime_parsers_classifier_register_udp("ssdp", NULL, 0, (const uint8_t *)"M-SEARCH ", 9, ssdp_classify);
    arkime_parsers_classifier_register_udp("ssdp", NULL, 0, (const uint8_t *)"NOTIFY * ", 9, ssdp_classify);
    arkime_parsers_classifier_register_udp("ssdp", NULL, 0, (const uint8_t *)"HTTP/1.", 7, ssdp_classify);
}

LOCAL void arkime_python_decref_threaded(PyObject *obj)
{
    if (PyThreadState_GetUnchecked()) {
        Py_DECREF(obj);
    } else if (arkimePacketThread >= 0 && packetThreadState[arkimePacketThread]) {
        PyEval_RestoreThread(packetThreadState[arkimePacketThread]);
        Py_DECREF(obj);
        PyEval_SaveThread();
    }
    // else: interpreter for this thread is gone (shutdown), leak the ref
}

LOCAL int nbns_udp_parser(ArkimeSession_t *session, void *UNUSED(uw), const uint8_t *data, int len, int UNUSED(which))
{
    nbns_parser(session, data, len);
    return 0;
}

LOCAL int tagger_map_v4(const char *ip, char *mapped, size_t size)
{
    if (strchr(ip, ':')) {
        g_strlcpy(mapped, ip, size);
        return 1;
    }
    const char *slash = strchr(ip, '/');
    if (slash) {
        int bits = atoi(slash + 1);
        if (bits < 0 || bits > 32 || slash - ip >= 40)
            return 0;
        snprintf(mapped, size, "::ffff:%.*s/%d", (int)(slash - ip), ip, 96 + bits);
    } else {
        snprintf(mapped, size, "::ffff:%s", ip);
    }
    return 1;
}

LOCAL void smb_remlen_consume(uint32_t *remlen, const uint8_t *start, const uint8_t *now)
{
    uint32_t consumed = (uint32_t)(now - start);
    if (consumed > *remlen)
        *remlen = 0;
    else
        *remlen -= consumed;
}

LOCAL int open_bpf_device()
    char bpf_device[256];
    // Try numbered BPF devices; they are exclusive-open so skip busy ones
        int fd = open(bpf_device, O_RDONLY);
        if (fd >= 0) {
            return fd;
        }

LOCAL patricia_node_t *tagger_make_and_lookup(patricia_tree_t *tree, const char *ip)
{
    char mapped[80];

    if (!strchr(ip, ':')) {
        const char *slash = strchr(ip, '/');
        if (slash) {
            int bits = atoi(slash + 1);
            if (bits < 0 || bits > 32 || slash - ip >= 40)
                return NULL;
            snprintf(mapped, sizeof(mapped), "::ffff:%.*s/%d", (int)(slash - ip), ip, 96 + bits);
        } else {
            snprintf(mapped, sizeof(mapped), "::ffff:%s", ip);
        }
        ip = mapped;
    }
    return make_and_lookup(tree, (char *)ip);
}

LOCAL void tagger_file_free(gpointer data)
{
    TaggerFile_t *file = data;

    free(file->str);
    g_free(file->md5);
    g_free(file->type);
    if (file->tags)
        g_strfreev(file->tags);
    if (file->elements)
        g_strfreev(file->elements);
    ARKIME_TYPE_FREE(TaggerFile_t, file);
}

LOCAL void zeekintel_item_free(gpointer data)
{
    ZeekIntelItem_t *item = data;
    g_free(item->indicator);
    if (item->source)
        g_free(item->source);
    if (item->desc)
        g_free(item->desc);
    if (item->url)
        g_free(item->url);
    ARKIME_TYPE_FREE(ZeekIntelItem_t, item);
}

LOCAL void zeekintel_ip_free(GPtrArray *items)
{
    if (items)
        g_ptr_array_free(items, TRUE);
}

LOCAL void zeekintel_hash_free(ZeekIntelStringHash_t *hash)
{
    ZeekIntelString_t *s;
    HASH_FORALL_POP_HEAD2(s_, *hash, s) {
        g_free(s->str);
        g_ptr_array_free(s->items, TRUE);
        ARKIME_TYPE_FREE(ZeekIntelString_t, s);
    }
}

LOCAL void zeekintel_db_free(ZeekIntelDB_t *db)
{
    if (!db)
        return;

    zeekintel_hash_free(&db->domains);
    zeekintel_hash_free(&db->urls);
    zeekintel_hash_free(&db->emails);
    zeekintel_hash_free(&db->fileHashes);
    zeekintel_hash_free(&db->certHashes);
    zeekintel_hash_free(&db->pubkeyHashes);

    if (db->ips)
        Destroy_Patricia(db->ips, (patricia_fn_data_t)zeekintel_ip_free);

    ARKIME_TYPE_FREE(ZeekIntelDB_t, db);
}

LOCAL ZeekIntelDB_t *zeekintel_db_new()
{
    ZeekIntelDB_t *db = ARKIME_TYPE_ALLOC0(ZeekIntelDB_t);

    HASH_INIT(s_, db->domains,      arkime_string_hash, arkime_string_cmp);
    HASH_INIT(s_, db->urls,         arkime_string_hash, arkime_string_cmp);
    HASH_INIT(s_, db->emails,       arkime_string_hash, arkime_string_cmp);
    HASH_INIT(s_, db->fileHashes,   arkime_string_hash, arkime_string_cmp);
    HASH_INIT(s_, db->certHashes,   arkime_string_hash, arkime_string_cmp);
    HASH_INIT(s_, db->pubkeyHashes, arkime_string_hash, arkime_string_cmp);
    db->ips = New_Patricia(128);

    return db;
}

LOCAL void zeekintel_hash_add(ZeekIntelStringHash_t *hash, const char *key, ZeekIntelItem_t *item)
{
    ZeekIntelString_t *s;
    uint32_t           h = arkime_string_hash(key);

    HASH_FIND_HASH(s_, *hash, h, key, s);
    if (!s) {
        s = ARKIME_TYPE_ALLOC0(ZeekIntelString_t);
        s->str = g_strdup(key);
        s->items = g_ptr_array_new_with_free_func(zeekintel_item_free);
        HASH_ADD_HASH(s_, *hash, h, s->str, s);
    }
    g_ptr_array_add(s->items, item);
}

LOCAL void zeekintel_ip_add(patricia_tree_t *tree, const char *indicator, ZeekIntelItem_t *item)
{
    patricia_node_t *node = make_and_lookup(tree, (char *)indicator);
    if (!node) {
        if (config.debug)
            LOG("Couldn't create node for %s", indicator);
        zeekintel_item_free(item);
        return;
    }
    if (!node->data)
        node->data = g_ptr_array_new_with_free_func(zeekintel_item_free);
    g_ptr_array_add((GPtrArray *)node->data, item);
}

LOCAL ZeekIntelType_t zeekintel_type_lookup(const char *type)
{
    if (strncmp(type, ZEEK_INTEL_PREFIX, ZEEK_INTEL_PREFIX_LEN) != 0)
        return ZEEK_INTEL_INVALID;

    const char *rest = type + ZEEK_INTEL_PREFIX_LEN;

    switch (rest[0]) {
    case 'A':
        if (strcmp(rest, "ADDR")        == 0) return ZEEK_INTEL_ADDR;
        break;
    case 'S':
        if (strcmp(rest, "SUBNET")      == 0) return ZEEK_INTEL_SUBNET;
        break;
    case 'D':
        if (strcmp(rest, "DOMAIN")      == 0) return ZEEK_INTEL_DOMAIN;
        break;
    case 'U':
        if (strcmp(rest, "URL")         == 0) return ZEEK_INTEL_URL;
        break;
    case 'E':
        if (strcmp(rest, "EMAIL")       == 0) return ZEEK_INTEL_EMAIL;
        break;
    case 'F':
        if (strcmp(rest, "FILE_HASH")   == 0) return ZEEK_INTEL_FILE_HASH;
        break;
    case 'C':
        if (strcmp(rest, "CERT_HASH")   == 0) return ZEEK_INTEL_CERT_HASH;
        break;
    case 'P':
        if (strcmp(rest, "PUBKEY_HASH") == 0) return ZEEK_INTEL_PUBKEY_HASH;
        break;
    }
    return ZEEK_INTEL_INVALID;
}

LOCAL gboolean zeekintel_db_add(ZeekIntelDB_t *db, const char *indicator, const char *type, const char *source, const char *desc, const char *url)
{
    ZeekIntelType_t t = zeekintel_type_lookup(type);
    if (t == ZEEK_INTEL_INVALID) {
        if (config.debug > 1)
            LOG("Skipping unsupported indicator_type %s for %s", type, indicator);
        return FALSE;
    }

    ZeekIntelItem_t *item = ARKIME_TYPE_ALLOC0(ZeekIntelItem_t);
    item->indicator = g_strdup(indicator);
    item->source    = source ? g_strdup(source) : NULL;
    item->desc      = desc   ? g_strdup(desc)   : NULL;
    item->url       = url    ? g_strdup(url)    : NULL;
    item->type      = t;

    switch (t) {
    case ZEEK_INTEL_ADDR:
    case ZEEK_INTEL_SUBNET:
        zeekintel_ip_add(db->ips, indicator, item);
        break;
    case ZEEK_INTEL_URL:
        // URLs are case sensitive, store as-is (matched against http.uri)
        zeekintel_hash_add(&db->urls, indicator, item);
        break;
    case ZEEK_INTEL_DOMAIN: {
        char *key = g_ascii_strdown(indicator, -1);
        zeekintel_hash_add(&db->domains, key, item);
        g_free(key);
        break;
    }
    case ZEEK_INTEL_EMAIL: {
        char *key = g_ascii_strdown(indicator, -1);
        zeekintel_hash_add(&db->emails, key, item);
        g_free(key);
        break;
    }
    case ZEEK_INTEL_FILE_HASH: {
        char *key = g_ascii_strdown(indicator, -1);
        zeekintel_hash_add(&db->fileHashes, key, item);
        g_free(key);
        break;
    }
    case ZEEK_INTEL_CERT_HASH: {
        char *key = g_ascii_strdown(indicator, -1);
        zeekintel_hash_add(&db->certHashes, key, item);
        g_free(key);
        break;
    }
    case ZEEK_INTEL_PUBKEY_HASH: {
        char *key = g_ascii_strdown(indicator, -1);
        zeekintel_hash_add(&db->pubkeyHashes, key, item);
        g_free(key);
        break;
    }
    default:
        zeekintel_item_free(item);
        return FALSE;
    }
    return TRUE;
}

LOCAL char zeekintel_unescape_sep(const char *s)
{
    if (s[0] == '\\' && (s[1] == 'x' || s[1] == 'X'))
        return (char)strtol(s + 2, NULL, 16);
    if (s[0] == '\\' && s[1] == 't')
        return '\t';
    return s[0];
}

LOCAL int zeekintel_parse_file(ZeekIntelDB_t *db, const char *filename)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        LOG("ERROR - Can't open zeekIntelFiles entry '%s' : %s", filename, strerror(errno));
        return 0;
    }

    char     sep      = '\t';
    char    *unset    = g_strdup("-");
    char    *empty    = g_strdup("(empty)");

    int      indicatorCol = 0;
    int      typeCol      = 1;
    int      sourceCol    = 2;
    int      descCol      = 3;
    int      urlCol       = 4;

    char    *line    = NULL;
    size_t   lineCap = 0;
    ssize_t  lineLen;
    int      count   = 0;

    while ((lineLen = getline(&line, &lineCap, fp)) >= 0) {
        while (lineLen > 0 && (line[lineLen - 1] == '\n' || line[lineLen - 1] == '\r'))
            line[--lineLen] = 0;

        if (lineLen == 0)
            continue;

        if (line[0] == '#') {
            if (strncmp(line, "#separator", 10) == 0) {
                const char *v = line + 10;
                while (*v == ' ' || *v == '\t')
                    v++;
                if (*v)
                    sep = zeekintel_unescape_sep(v);
            } else if (strncmp(line, "#fields", 7) == 0) {
                char sepstr[2] = {sep, 0};
                gchar **cols = g_strsplit(line, sepstr, -1);
                indicatorCol = typeCol = sourceCol = descCol = urlCol = -1;
                for (int c = 1; cols[c]; c++) {
                    if (strcmp(cols[c], "indicator") == 0)
                        indicatorCol = c - 1;
                    else if (strcmp(cols[c], "indicator_type") == 0)
                        typeCol = c - 1;
                    else if (strcmp(cols[c], "meta.source") == 0)
                        sourceCol = c - 1;
                    else if (strcmp(cols[c], "meta.desc") == 0)
                        descCol = c - 1;
                    else if (strcmp(cols[c], "meta.url") == 0)
                        urlCol = c - 1;
                }
                g_strfreev(cols);
            } else if (strncmp(line, "#unset_field", 12) == 0) {
                char *v = strchr(line, sep);
                if (v) {
                    g_free(unset);
                    unset = g_strdup(v + 1);
                }
            } else if (strncmp(line, "#empty_field", 12) == 0) {
                char *v = strchr(line, sep);
                if (v) {
                    g_free(empty);
                    empty = g_strdup(v + 1);
                }
            }
            // All other directives (#set_separator, #types, #path, ...) ignored
            continue;
        }

        if (indicatorCol < 0 || typeCol < 0)
            continue;

        char sepstr[2] = {sep, 0};
        gchar **vals = g_strsplit(line, sepstr, -1);
        guint   nvals = g_strv_length(vals);

        if ((guint)indicatorCol >= nvals || (guint)typeCol >= nvals) {
            g_strfreev(vals);
            continue;
        }

        const char *indicator = vals[indicatorCol];
        const char *type      = vals[typeCol];
        const char *source    = (sourceCol >= 0 && (guint)sourceCol < nvals) ? vals[sourceCol] : NULL;
        const char *desc      = (descCol   >= 0 && (guint)descCol   < nvals) ? vals[descCol]   : NULL;
        const char *url       = (urlCol    >= 0 && (guint)urlCol    < nvals) ? vals[urlCol]    : NULL;

        if (!indicator[0] || !type[0]) {
            g_strfreev(vals);
            continue;
        }

        // A hyphen (or empty) meta field is a null value in the Zeek format.
        if (source && (!source[0] || strcmp(source, unset) == 0 || strcmp(source, empty) == 0))
            source = NULL;
        if (desc && (!desc[0] || strcmp(desc, unset) == 0 || strcmp(desc, empty) == 0))
            desc = NULL;
        if (url && (!url[0] || strcmp(url, unset) == 0 || strcmp(url, empty) == 0))
            url = NULL;

        if (zeekintel_db_add(db, indicator, type, source, desc, url))
            count++;

        g_strfreev(vals);
    }

    free(line);
    g_free(unset);
    g_free(empty);
    fclose(fp);

    if (config.debug)
        LOG("Loaded %d indicators from %s", count, filename);

    return count;
}

LOCAL void zeekintel_load(char **names)
{
    ZeekIntelDB_t *db = zeekintel_db_new();

    int total = 0;
    int numFiles = 0;
    for (int i = 0; names[i]; i++) {
        total += zeekintel_parse_file(db, names[i]);
        numFiles++;
    }

    LOG("Loaded %d Zeek intel indicators from %d file(s)", total, numFiles);

    ZeekIntelDB_t *old = ARKIME_THREAD_ATOMIC_LOAD(currentDB);
    ARKIME_THREAD_ATOMIC_STORE(currentDB, db);
    if (old)
        arkime_free_later(old, (GDestroyNotify)zeekintel_db_free);
}

LOCAL void zeekintel_object_save(BSB *jbsb, ArkimeFieldObject_t *object, ArkimeSession_t *UNUSED(session))
{
    if (object->object == NULL)
        return;

    const ZeekIntelMatch_t *m = object->object;

    BSB_EXPORT_u08(*jbsb, '{');

    BSB_EXPORT_cstr(*jbsb, "\"indicator\":");
    arkime_db_js0n_str(jbsb, (uint8_t *)m->indicator, TRUE);
    BSB_EXPORT_u08(*jbsb, ',');

    BSB_EXPORT_sprintf(*jbsb, "\"indicator_type\":\"%s\",", zeekIntelTypeNames[m->type]);

    if (m->where)
        BSB_EXPORT_sprintf(*jbsb, "\"where\":\"%s\",", m->where);

    if (m->source) {
        BSB_EXPORT_cstr(*jbsb, "\"source\":");
        arkime_db_js0n_str(jbsb, (uint8_t *)m->source, TRUE);
        BSB_EXPORT_u08(*jbsb, ',');
    }
    if (m->desc) {
        BSB_EXPORT_cstr(*jbsb, "\"desc\":");
        arkime_db_js0n_str(jbsb, (uint8_t *)m->desc, TRUE);
        BSB_EXPORT_u08(*jbsb, ',');
    }
    if (m->url) {
        BSB_EXPORT_cstr(*jbsb, "\"url\":");
        arkime_db_js0n_str(jbsb, (uint8_t *)m->url, TRUE);
        BSB_EXPORT_u08(*jbsb, ',');
    }

    BSB_EXPORT_rewind(*jbsb, 1); // remove trailing comma
    BSB_EXPORT_u08(*jbsb, '}');
}

LOCAL void zeekintel_object_free(ArkimeFieldObject_t *object)
{
    ZeekIntelMatch_t *m = object->object;
    if (m) {
        g_free(m->indicator);
        g_free(m->source);
        g_free(m->desc);
        g_free(m->url);
        ARKIME_TYPE_FREE(ZeekIntelMatch_t, m);
    }
    ARKIME_TYPE_FREE(ArkimeFieldObject_t, object);
}

LOCAL uint32_t zeekintel_object_hash(const void *key)
{
    const ZeekIntelMatch_t *m = key;
    uint32_t h = arkime_string_hash(m->indicator) * 31 + (uint32_t)m->type;
    if (m->where)
        h = h * 31 + arkime_string_hash(m->where);
    return h;
}

LOCAL int zeekintel_object_cmp(const void *keyv, const void *elementv)
{
    const ArkimeFieldObject_t *element = elementv;
    if (element->object == NULL)
        return 0;

    const ZeekIntelMatch_t *a = keyv;
    const ZeekIntelMatch_t *b = element->object;

    if (a->type != b->type || strcmp(a->indicator, b->indicator) != 0)
        return 0;
    if ((a->where == NULL) != (b->where == NULL))
        return 0;
    if (a->where && strcmp(a->where, b->where) != 0)
        return 0;
    if ((a->source == NULL) != (b->source == NULL))
        return 0;
    if (a->source && strcmp(a->source, b->source) != 0)
        return 0;
    return 1;
}

LOCAL void zeekintel_apply(ArkimeSession_t *session, const GPtrArray *items, const char *where)
{
    for (guint i = 0; i < items->len; i++) {
        const ZeekIntelItem_t *item = g_ptr_array_index(items, i);

        arkime_session_add_tag(session, zeekIntelTag);

        ZeekIntelMatch_t *m = ARKIME_TYPE_ALLOC0(ZeekIntelMatch_t);
        m->indicator = g_strdup(item->indicator);
        m->type      = item->type;
        m->where     = where;
        m->source    = item->source ? g_strdup(item->source) : NULL;
        m->desc      = item->desc   ? g_strdup(item->desc)   : NULL;
        m->url       = item->url    ? g_strdup(item->url)    : NULL;

        // indicator/source/desc/url are untrusted feed data run through
        // arkime_db_js0n_str's JSON escaper, which can expand a byte up to
        // 6x (eg a control char becomes \u00XX); double them as a safety
        // margin so jsonSize doesn't undercount and truncate the document.
        int len = 100 + strlen(zeekIntelTypeNames[m->type])
                  + (m->where  ? strlen(m->where)          : 0)
                  + 2 * (strlen(m->indicator)
                         + (m->source ? strlen(m->source) : 0)
                         + (m->desc   ? strlen(m->desc)   : 0)
                         + (m->url    ? strlen(m->url)    : 0));

        ArkimeFieldObject_t *fobject = ARKIME_TYPE_ALLOC0(ArkimeFieldObject_t);
        fobject->object = m;

        if (!arkime_field_object_add(zeekintelField, session, fobject, len))
            zeekintel_object_free(fobject);  // duplicate match
    }
}

LOCAL void zeekintel_match_ip(ArkimeSession_t *session, ZeekIntelDB_t *db, const struct in6_addr *addr, const char *where)
{
    patricia_node_t *nodes[PATRICIA_MAXBITS + 1];
    prefix_t         prefix;

#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wstrict-aliasing"
    if (IN6_IS_ADDR_V4MAPPED(addr)) {
        prefix.family = AF_INET;
        prefix.bitlen = 32;
        prefix.add.sin.s_addr = ARKIME_V6_TO_V4(*addr);
    } else {
        prefix.family = AF_INET6;
        prefix.bitlen = 128;
        memcpy(&prefix.add.sin6.s6_addr, addr, 16);
    }
#pragma GCC diagnostic pop

    int cnt = patricia_search_all(db->ips, &prefix, 1, nodes);
    for (int i = 0; i < cnt; i++) {
        if (nodes[i]->data)
            zeekintel_apply(session, (GPtrArray *)nodes[i]->data, where);
    }
}

LOCAL void zeekintel_match_str_value(ArkimeSession_t *session, ZeekIntelStringHash_t *hash, const char *str, gboolean lower, const char *where)
{
    if (!str)
        return;

    ZeekIntelString_t *found;

    if (lower) {
        char *key = g_ascii_strdown(str, -1);
        HASH_FIND(s_, *hash, key, found);
        g_free(key);
    } else {
        HASH_FIND(s_, *hash, str, found);
    }

    if (found)
        zeekintel_apply(session, found->items, where);
}

LOCAL void zeekintel_match_str_field(ArkimeSession_t *session, ZeekIntelStringHash_t *hash, int pos, gboolean lower)
{
    const ArkimeFieldInfo_t *info = config.fields[pos];
    if (!info)
        return;

    const char *where = info->expression;

    void *getval = NULL;
    if (info->getCb) {
        getval = info->getCb(session, pos);
        if (!getval)
            return;
    } else if (pos >= session->maxFields || !session->fields[pos]) {
        return;
    }

    switch (info->type) {
    case ARKIME_FIELD_TYPE_STR:
        zeekintel_match_str_value(session, hash, info->getCb ? (char *)getval : session->fields[pos]->str, lower, where);
        break;
    case ARKIME_FIELD_TYPE_STR_ARRAY: {
        const GPtrArray *arr = info->getCb ? (GPtrArray *)getval : session->fields[pos]->sarray;
        for (guint i = 0; i < arr->len; i++)
            zeekintel_match_str_value(session, hash, g_ptr_array_index(arr, i), lower, where);
        break;
    }
    case ARKIME_FIELD_TYPE_STR_HASH: {
        if (info->getCb)
            break;  // no getCb STR_HASH fields exist
        const ArkimeStringHashStd_t *shash = session->fields[pos]->shash;
        ArkimeString_t *hstring;
        HASH_FORALL2(s_, *shash, hstring)
        zeekintel_match_str_value(session, hash, hstring->str, lower, where);
        break;
    }
    case ARKIME_FIELD_TYPE_STR_GHASH: {
        GHashTable    *ghash = info->getCb ? (GHashTable *)getval : session->fields[pos]->ghash;
        GHashTableIter iter;
        gpointer       ikey;
        g_hash_table_iter_init(&iter, ghash);
        while (g_hash_table_iter_next(&iter, &ikey, NULL))
            zeekintel_match_str_value(session, hash, (char *)ikey, lower, where);
        break;
    }
    default:
        break;
    }
}

LOCAL void zeekintel_match_ip_field(ArkimeSession_t *session, ZeekIntelDB_t *db, int pos)
{
    const ArkimeFieldInfo_t *info = config.fields[pos];
    if (!info || pos >= session->maxFields || !session->fields[pos])
        return;

    const char *where = info->expression;

    if (info->type == ARKIME_FIELD_TYPE_IP) {
        zeekintel_match_ip(session, db, session->fields[pos]->ip, where);
    } else { // ARKIME_FIELD_TYPE_IP_GHASH
        GHashTable    *ghash = session->fields[pos]->ghash;
        GHashTableIter iter;
        gpointer       ikey;
        g_hash_table_iter_init(&iter, ghash);
        while (g_hash_table_iter_next(&iter, &ikey, NULL))
            zeekintel_match_ip(session, db, (struct in6_addr *)ikey, where);
    }
}

LOCAL void zeekintel_plugin_save(ArkimeSession_t *session, int UNUSED(final))
{
    ZeekIntelDB_t *db = ARKIME_THREAD_ATOMIC_LOAD(currentDB);
    if (!db)
        return;

    // Primary src/dst IPs (ie ip.src / ip.dst)
    zeekintel_match_ip(session, db, &session->addr1, "ip.src");
    zeekintel_match_ip(session, db, &session->addr2, "ip.dst");

    for (guint i = 0; i < ipFields->len; i++)
        zeekintel_match_ip_field(session, db, g_array_index(ipFields, int, i));

    for (guint i = 0; i < domainFields->len; i++)
        zeekintel_match_str_field(session, &db->domains, g_array_index(domainFields, int, i), TRUE);

    for (guint i = 0; i < urlFields->len; i++)
        zeekintel_match_str_field(session, &db->urls, g_array_index(urlFields, int, i), FALSE);

    for (guint i = 0; i < fileHashFields->len; i++)
        zeekintel_match_str_field(session, &db->fileHashes, g_array_index(fileHashFields, int, i), TRUE);

    for (guint i = 0; i < certHashFields->len; i++)
        zeekintel_match_str_field(session, &db->certHashes, g_array_index(certHashFields, int, i), TRUE);

    for (guint i = 0; i < pubkeyHashFields->len; i++)
        zeekintel_match_str_field(session, &db->pubkeyHashes, g_array_index(pubkeyHashFields, int, i), TRUE);

    for (guint i = 0; i < emailFields->len; i++)
        zeekintel_match_str_field(session, &db->emails, g_array_index(emailFields, int, i), TRUE);
}

LOCAL gboolean zeekintel_category_has(const char *category, const char *token)
{
    if (!category)
        return FALSE;

    const int   tlen = strlen(token);
    const char *p    = category;

    while ((p = strstr(p, token))) {
        const char before = (p == category) ? 0 : p[-1];
        const char after  = p[tlen];
        if (!isalnum((unsigned char)before) && before != '_' &&
            !isalnum((unsigned char)after)  && after  != '_')
            return TRUE;
        p += tlen;
    }
    return FALSE;
}

LOCAL void zeekintel_field_list_add(GArray *list, int pos)
{
    if (pos < 0 || pos >= ARKIME_FIELDS_MAX)
        return;
    for (guint i = 0; i < list->len; i++)    // dedupe
        if (g_array_index(list, int, i) == pos)
            return;
    g_array_append_val(list, pos);
}

LOCAL void zeekintel_classify_field(const ArkimeFieldInfo_t *info)
{
    if (!info)
        return;

    if (ARKIME_FIELD_TYPE_IS_IP(info->type)) {
        // ip.src/ip.dst are getCb fields equal to addr1/addr2 (matched
        // directly); object-backed ip fields have no flat storage.
        if (!info->getCb && !(info->flags & ARKIME_FIELD_FLAG_FAKE))
            zeekintel_field_list_add(ipFields, info->pos);
        return;
    }

    if (!ARKIME_FIELD_TYPE_IS_STR(info->type) || !info->category)
        return;

    if (zeekintel_category_has(info->category, "host"))
        zeekintel_field_list_add(domainFields, info->pos);
    if (zeekintel_category_has(info->category, "url"))
        zeekintel_field_list_add(urlFields, info->pos);
    if (zeekintel_category_has(info->category, "md5") ||
        zeekintel_category_has(info->category, "sha1") ||
        zeekintel_category_has(info->category, "sha256")) {
        // Zeek treats file/content hashes, cert hashes, and cert public-key
        // hashes as distinct indicator types (FILE_HASH/CERT_HASH/PUBKEY_HASH)
        // that must not cross-match; route cert-related fields to their own
        // lists instead of lumping every md5/sha1/sha256 field together.
        if (strncmp(info->expression, "cert.", 5) == 0) {
            if (strstr(info->expression, "pubkey"))
                zeekintel_field_list_add(pubkeyHashFields, info->pos);
            else
                zeekintel_field_list_add(certHashFields, info->pos);
        } else {
            zeekintel_field_list_add(fileHashFields, info->pos);
        }
    }
    if (zeekintel_category_has(info->category, "user"))
        zeekintel_field_list_add(emailFields, info->pos);
}

LOCAL void zeekintel_field_list_add_exp(GArray *list, const char *expression)
{
    int pos = arkime_field_by_exp_ignore_error(expression);
    if (pos >= 0)
        zeekintel_field_list_add(list, pos);
}

LOCAL void zeekintel_build_fields()
{
    ipFields     = g_array_new(FALSE, FALSE, sizeof(int));
    domainFields = g_array_new(FALSE, FALSE, sizeof(int));
    urlFields    = g_array_new(FALSE, FALSE, sizeof(int));
    fileHashFields   = g_array_new(FALSE, FALSE, sizeof(int));
    certHashFields   = g_array_new(FALSE, FALSE, sizeof(int));
    pubkeyHashFields = g_array_new(FALSE, FALSE, sizeof(int));
    emailFields  = g_array_new(FALSE, FALSE, sizeof(int));

    for (int pos = 0; pos < config.maxDbField; pos++)
        zeekintel_classify_field(config.fields[pos]);
    for (int pos = config.minInternalField; pos < ARKIME_FIELDS_MAX; pos++)
        zeekintel_classify_field(config.fields[pos]);

    /*
     * FAKE schema fields carry the category but are removed/freed by field.c
     * after registration, so their host data (served by internal getCb fields)
     * can't be found by category.  Add the known getCb host fields explicitly;
     * the expression resolves to the getCb field and the add dedupes.
     */
    static const char *getcbHostExprs[] = {
        "dns.host", "host.dns.nameserver", "host.dns.mailserver",
        "dns.query.host", "dns.puny", "cert.alt", NULL
    };
    for (int i = 0; getcbHostExprs[i]; i++)
        zeekintel_field_list_add_exp(domainFields, getcbHostExprs[i]);

    if (config.debug)
        LOG("Matching %u ip, %u host, %u url, %u file hash, %u cert hash, %u pubkey hash, %u email fields",
            ipFields->len, domainFields->len, urlFields->len,
            fileHashFields->len, certHashFields->len, pubkeyHashFields->len, emailFields->len);
}

LOCAL void zeekintel_plugin_exit()
{
    ZeekIntelDB_t *db = ARKIME_THREAD_ATOMIC_LOAD(currentDB);
    ARKIME_THREAD_ATOMIC_STORE(currentDB, NULL);
    zeekintel_db_free(db);
}

void arkime_plugin_init()
{
    zeekIntelFiles = arkime_config_str_list(NULL, "zeekIntelFiles", NULL);
    if (!zeekIntelFiles || !zeekIntelFiles[0])
        CONFIGEXIT("zeekintel plugin enabled but no zeekIntelFiles set");

    zeekIntelTag = arkime_config_str(NULL, "zeekIntelTag", "zeek:intel");

    arkime_plugins_register("zeekintel", FALSE);

    arkime_plugins_set_cb("zeekintel",
                          NULL,
                          NULL,
                          NULL,
                          NULL,
                          zeekintel_plugin_save,
                          NULL,
                          zeekintel_plugin_exit,
                          NULL
                         );

    /*
     * One object field holding an array of match objects, each with its own
     * indicator / indicator_type / where / source / desc / url.  The match is
     * built and serialized at save time by zeekintel_object_save(), so these
     * per-subfield FAKE definitions (mirroring dns.answer.* / cert.*) exist
     * only to give the ES mapping/UI a searchable+clickable field per key;
     * field.c removes/frees FAKE fields after registration, so they carry no
     * storage and are not picked up by zeekintel_classify_field() below.
     */
    zeekintelField = arkime_field_object_register("zeekintel", "Zeek intel matches",
                                                  zeekintel_object_save, zeekintel_object_free,
                                                  zeekintel_object_hash, zeekintel_object_cmp);

    arkime_field_define("zeekintel", "lotermfield",
                        "zeekintel.indicator", "Indicator", "zeekintel.indicator",
                        "Zeek intel indicator that matched",
                        0, ARKIME_FIELD_FLAG_FAKE,
                        (char *)NULL);

    arkime_field_define("zeekintel", "lotermfield",
                        "zeekintel.type", "Indicator Type", "zeekintel.indicator_type",
                        "Zeek intel indicator_type of the match",
                        0, ARKIME_FIELD_FLAG_FAKE,
                        (char *)NULL);

    arkime_field_define("zeekintel", "lotermfield",
                        "zeekintel.where", "Where", "zeekintel.where",
                        "Arkime field expression the indicator matched in",
                        0, ARKIME_FIELD_FLAG_FAKE,
                        (char *)NULL);

    arkime_field_define("zeekintel", "lotermfield",
                        "zeekintel.source", "Source", "zeekintel.source",
                        "Zeek intel meta.source of the match",
                        0, ARKIME_FIELD_FLAG_FAKE,
                        (char *)NULL);

    arkime_field_define("zeekintel", "lotermfield",
                        "zeekintel.desc", "Description", "zeekintel.desc",
                        "Zeek intel meta.desc of the match",
                        0, ARKIME_FIELD_FLAG_FAKE,
                        (char *)NULL);

    arkime_field_define("zeekintel", "lotermfield",
                        "zeekintel.url", "URL", "zeekintel.url",
                        "Zeek intel meta.url of the match",
                        0, ARKIME_FIELD_FLAG_FAKE,
                        (char *)NULL);

    /*
     * Discover all the session fields worth matching (ip fields by type;
     * host/url/hash/email fields by category) from the field registry, now
     * that every parser has registered its fields.
     */
    zeekintel_build_fields();

    /*
     * Register the files with Arkime's standard config file monitor.  This
     * loads them right away and reloads them whenever they change.
     */
    arkime_config_monitor_files("zeek intel files", zeekIntelFiles, zeekintel_load);
}

LOCAL void scheme_watch_free(gpointer data)
{
    SchemeWatch_t *sw = (SchemeWatch_t *)data;
    g_free(sw->dirname);
    arkime_reader_scheme_actions_deref(sw->actions);
    ARKIME_TYPE_FREE(SchemeWatch_t, sw);
}

LOCAL ArkimePacketRC arkime_packet_mpacket(ArkimePacketBatch_t *batch, ArkimePacket_t *const packet, const uint8_t *data, int len)
{
    if (len < 14) {
#ifdef DEBUG_PACKET
        LOG("BAD PACKET: Too short %d", len);
#endif
        return ARKIME_PACKET_CORRUPT;
    }

    int offset = 0;

    // An optional leading octet (0x50) carries preamble alignment bits
    if (data[0] == 0x50)
        offset = 1;

    // Skip the 0x55 preamble octets, leaving room for the SMD and a frame
    while (offset + 2 < len && data[offset] == 0x55)
        offset++;

    switch (data[offset]) {
    case 0xd5: // SMD-E  Express frame
    case 0xe6: // SMD-S0 preemptable start / non-fragmented frame
    case 0x4c: // SMD-S1
    case 0x7f: // SMD-S2
    case 0xb3: // SMD-S3
        offset++;
        break;
    default:
        // SMD-V/SMD-R control frames have no Ethernet payload, and SMD-Cx
        // continuation fragments require reassembly we don't perform here
#ifdef DEBUG_PACKET
        LOG("Unsupported mPacket SMD 0x%02x", data[offset]);
#endif
        return ARKIME_PACKET_CORRUPT;
    }

    // What remains is the Ethernet mData followed by a trailing 4-byte CRC
    int elen = len - offset - 4;
    if (elen < 14) {
#ifdef DEBUG_PACKET
        LOG("BAD PACKET: Too short after preamble %d", elen);
#endif
        return ARKIME_PACKET_CORRUPT;
    }

    // Treat the inner Ethernet frame as the sole frame: pre-seeding etherOffset
    // makes arkime_packet_ether set outerEtherOffset == etherOffset, so the
    // preamble bytes are not mistaken for an outer MAC.
    packet->etherOffset = offset;
    return arkime_packet_ether(batch, packet, data + offset, elen);
}

