LOCAL void arkime_parsers_classifier_add_port(ArkimeClassifyHead_t *ch, const char *name, void *uw, ArkimeClassifyFunc func)
{
    ArkimeClassify_t *c = ARKIME_TYPE_ALLOC0(ArkimeClassify_t);
