    c->uw       = uw;
    c->func     = func;
    arkime_parsers_classifier_add(ch, c);
}

LOCAL void dtls_alpn_to_ja4alpn(const uint8_t *alpn, int len, uint8_t *ja4alpn)
{
    if (len == 0)
        return;

    len--;  // len now the offset of last byte, which could be 0
    if (isalnum(alpn[0]) && isalnum(alpn[len])) {
        ja4alpn[0] = alpn[0];
        ja4alpn[1] = alpn[len];
    } else {
        ja4alpn[0] = arkime_char_to_hexstr[alpn[0]][0];
        ja4alpn[1] = arkime_char_to_hexstr[alpn[len]][1];
    }
}

LOCAL int nbns_decode_label(const uint8_t *data, char *out)
{
    int outPos = 0;
    for (int i = 0; i < 30; i += 2) {  // 15 name chars; byte 16 is the suffix
        if (data[i] < 'A' || data[i] > 'P' || data[i + 1] < 'A' || data[i + 1] > 'P')
            break;
        char c = ((data[i] - 'A') << 4) | (data[i + 1] - 'A');
        if (c >= 0x20 && c <= 0x7e)
            out[outPos++] = c;
    }
    while (outPos > 0 && out[outPos - 1] == ' ')
        outPos--;
    out[outPos] = '\0';
    return outPos;
}

LOCAL char *smtp_parse_param_value(char *str)
{
    while (isspace(*str))
        str++;

    if (*str == '"') {
        str++;
        char *startstr = str;
        while (*str && *str != '"')
            str++;
        *str = 0;
        return startstr;
    }

    char *startstr = str;
    while (*str && *str != ';' && !isspace(*str))
        str++;
    *str = 0;

    return startstr;
}

atic inline void nt_ts_to_timeval(uint64_t ts_ns, struct timeval *tv)
{
    tv->tv_sec  = (time_t)(ts_ns / 1000000000ULL);
    tv->tv_usec = (suseconds_t)((ts_ns % 1000000000ULL) / 1000ULL);
}

CAL int reader_napatech_stats(ArkimeReaderStats_t *stats)
{
    stats->total   = 0;
    stats->dropped = ntDropped;
    for (int s = 0; s < ntNumStreams; s++) {
        stats->total += ntTotalPkts[s];
    }
    return 0;
}

CAL void *reader_napatech_thread(gpointer streamv)
{
    NtStream_t *st = (NtStream_t *)streamv;
    NtNetBuf_t  hSegBuf;     /* handle to one segment (N packets) */
    int         status;

    int threadNum = ARKIME_THREAD_INCROLD(ntThreadNum);
    int initFunc = arkime_get_named_func("arkime_reader_thread_init");
    arkime_call_named_func(initFunc, threadNum, NULL);

    ArkimePacketBatch_t batch;
    arkime_packet_batch_init(&batch);

    while (!config.quitting) {
        /* 100ms timeout so we can check config.quitting */
        status = NT_NetRxGet(st->hStream, &hSegBuf, 100);

        if (unlikely(status == NT_STATUS_TIMEOUT || status == NT_STATUS_TRYAGAIN)) {
            continue;
        }

        if (unlikely(status != NT_SUCCESS)) {
            char errBuf[256];
            NT_ExplainError(status, errBuf, sizeof(errBuf));
            LOG("Napatech stream %d error: %s", st->streamId, errBuf);
            arkime_quit();
            break;
        }

        /* ------ Walk all packets in this segment (zero-copy) ------------ *
         *                                                                  *
         * NT_NetRxGet in segment mode returns a contiguous buffer          *
         * containing back-to-back packet records. Each record starts with  *
         * a NtStd0Descr_t (16-byte standard descriptor from                *
         * pktdescr_std0.h), followed immediately by the L2 frame bytes,    *
         * then 0-7 bytes of 8-byte-alignment padding.                      *
         *                                                                  *
         * NtStd0Descr_t layout (128 bits, confirmed from SDK headers):     *
         *   [63:0]  timestamp   — 64-bit Unix nanoseconds (UNIX_NANOTIME)  *
         *   [79:64] storedLength:16 — total record bytes (stride), incl.   *
         *                            descriptor + payload + padding        *
         *   [95:80] (bit fields: crcError, checksums, rxPort, etc.)        *
         *   [111:96] wireLength:16 — original on-wire frame length         *
         *   [127:112] (bit fields: txPort, flags, extensionLength:3, ...)  *
         *                                                                  *
         * We set packet->copied = 0 and point packet->pkt directly into    *
         * the segment buffer (zero-copy). The segment is NOT released      *
         * until after arkime_packet_batch_flush(). Arkime's async packet   *
         * threads will copy each packet (packet.c ~line 1556) before the   *
         * FPGA can rotate the host buffer back around (~1.6 s at           *
         * 10 Gbps), matching the safety model used by tpacketv3 blocks.    *
         * ---------------------------------------------------------------- */
        uint64_t segLen  = NT_NET_GET_SEGMENT_LENGTH(hSegBuf);
        uint8_t *segBase = (uint8_t *)NT_NET_GET_SEGMENT_PTR(hSegBuf);
        uint8_t *segEnd  = segBase + segLen;

        for (uint8_t *p = segBase; p < segEnd;) {
            NtStd0Descr_t *d = (NtStd0Descr_t *)p;

            /* storedLength is in BYTES (already 8-byte-aligned) and is the
             * full record stride: descriptor + captured payload + padding.
             * Confirmed from pktdescr_std0.h setter:
             *   storedLength = (descrLength + capLength + 7) & ~7            */
            uint32_t  recSize = d->storedLength;

            if (unlikely(recSize == 0)) {
                /* Corrupt segment — stop walking to avoid infinite loop */
                LOG("Napatech stream %d: zero storedLength in segment, aborting walk",
                    st->streamId);
                break;
            }

            /* Descriptor length: 16-byte fixed header + optional extension
             * (extensionLength is in 8-byte units, per pktdescr_std0.h).    */
            uint16_t  descrLen = (uint16_t)sizeof(NtStd0Descr_t) +
                                 ((uint16_t)d->extensionLength << 3);
            uint8_t  *l2       = p + descrLen;

            /* wireLength = original frame bytes on the wire.
             * Captured payload may include 0-7 padding bytes due to alignment;
             * take the minimum so Arkime never sees garbage padding.          */
            uint16_t  wireLen  = d->wireLength;
            uint16_t  payLen   = (recSize > descrLen) ? (recSize - descrLen) : 0;
            uint16_t  capLen   = (payLen < wireLen) ? payLen : wireLen;
            uint64_t  ts      = d->timestamp;

            /* Software BPF filter — applied before allocation, so dropped
             * packets cost only this check with no malloc. */
            if (use_sw_bpf && bpf_filter(sw_bpf.bf_insns, l2, wireLen, capLen) == 0) {
                ARKIME_THREAD_INCR(ntDropped);
                p += recSize;
                continue;
            }

            if (unlikely(capLen != wireLen) &&
                !config.readTruncatedPackets && !config.ignoreErrors) {
                LOGEXIT("ERROR - Arkime requires full packet captures caplen: %d pktlen: %d\n"
                        "See https://arkime.com/faq#arkime_requires_full_packet_captures_error",
                        capLen, wireLen);
            }

            ArkimePacket_t *packet = ARKIME_TYPE_ALLOC0(ArkimePacket_t);
            packet->pkt       = l2;   /* zero-copy: pointer into segment buffer */
            packet->pktlen    = capLen;
            packet->readerPos = st->interfacePos;
            packet->copied    = 0;    /* Arkime will copy before freeing; segment
                                         held open until NT_NetRxRelease below */

            /* Hardware timestamp — nanosecond precision, no software jitter */
            nt_ts_to_timeval(ts, &packet->ts);

            /* VLANs preserved in wire order (no VLANStrip in NTPL) */

            ARKIME_THREAD_INCR(ntTotalPkts[st->interfacePos]);

            arkime_packet_batch(&batch, packet);

            p += recSize;
        }

        /* All packets in this segment have been batched. Flush to the
         * per-thread queues, then release the segment back to the FPGA.
         * The packet threads will copy asynchronously; the 2 GB host buffer
         * ring ensures the segment memory stays valid long enough. */
        arkime_packet_batch_flush(&batch);
        NT_NetRxRelease(st->hStream, hSegBuf);
    }

    arkime_packet_batch_flush(&batch);

    int exitFunc = arkime_get_named_func("arkime_reader_thread_exit");
    arkime_call_named_func(exitFunc, threadNum, NULL);
    return NULL;
}

/* ---------

r_napatech_start()
{
    /* NT_Init() and NT_NetRxOpen() were called in reader_napatech_init()
     * (which runs as root, before Arkime drops privileges to dropUser).
     * By the time start() is called, we are already running as nobody and
     * /dev/nt3gd is no longer accessible, so NTAPI calls that open the
     * device must NOT be placed here.
     *
     * All that remains is to tell Arkime the link type and spawn threads. */

    /* Tell Arkime the link type and snap length */
    arkime_packet_set_dltsnap(DLT_EN10MB, config.snapLen);

    LOG("Napatech: starting %d capture thread(s)", ntNumStreams);
    for (int s = 0; s < ntNumStreams; s++) {
        char tname[64];
        snprintf(tname, sizeof(tname), "arkime-nt-stream%d", s);
        g_thread_unref(g_thread_new(tname, reader_napatech_thread, &ntStreams[s]));
    }
}

/* -----------

r_napatech_stop()
{
    /* config.quitting is already set by caller; threads will drain */
}

LOCAL void rea

r_napatech_exit()
{
    for (int s = 0; s < ntNumStreams; s++) {
        if (ntStreams[s].hStream) {
            NT_NetRxClose(ntStreams[s].hStream);
            ntStreams[s].hStream = 0;
        }
    }
    g_free(ntStreams);
    ntStreams   = NULL;
    g_free(ntTotalPkts);
    ntTotalPkts = NULL;
    ntNumStreams = 0;
    if (use_sw_bpf)
        pcap_freecode(&sw_bpf);
    NT_Done();
}

/* -----------

r_napatech_parse_stream_range(const char *str,
                                              int **ids_out, int *count_out)
{
    int  capacity = 32;
    int *ids = g_malloc(capacity * sizeof(int));
    int  count = 0;
    const char *p = str;

    while (*p) {
        while (*p == ' ' || *p == '\t') p++;
        if (*p == '\0') break;

        char *end;
        long lo = strtol(p, &end, 10);
        if (end == p || lo < 0 || lo > 255) {
            g_free(ids);
            return -1;
        }
        p = end;
        while (*p == ' ' || *p == '\t') p++;

        long hi = lo;
        if (*p == '-') {
            p++;
            while (*p == ' ' || *p == '\t') p++;
            hi = strtol(p, &end, 10);
            if (end == p || hi < lo || hi > 255) {
                g_free(ids);
                return -1;
            }
            p = end;
        }
        while (*p == ' ' || *p == '\t') p++;

        for (long s = lo; s <= hi; s++) {
            if (count == capacity) {
                capacity *= 2;
                ids = g_realloc(ids, capacity * sizeof(int));
            }
            ids[count++] = (int)s;
        }
        if (*p == ',') p++;
    }

    if (count == 0) {
        g_free(ids);
        return -1;
    }
    *ids_out   = ids;
    *count_out = count;
    return 0;
}

/* Resolve the

er_napatech_get_stream_ids(int **ids_out, int *count_out)
{
    char errBuf[NT_ERRBUF_SIZE];
    int  status;

    char *cfgStr = arkime_config_str(NULL, "ntStreamIds", NULL);
    if (cfgStr) {
        int *ids;
        int  count;
        if (reader_napatech_parse_stream_range(cfgStr, &ids, &count) != 0) {
            CONFIGEXIT("Napatech: ntStreamIds '%s' is invalid. "
                       "Expected comma-separated IDs/ranges, e.g. '0-3,5,8-10'", cfgStr);
        }
        g_free(cfgStr);
        *ids_out   = ids;
        *count_out = count;
        return;
    }

    /* Auto-detect: NT_INFO_CMD_READ_STREAM returns stream IDs that have
     * host buffers allocated in ntservice.ini HostBuffersRx. */
    NtInfoStream_t hInfo;
    if ((status = NT_InfoOpen(&hInfo, "arkime-info")) != NT_SUCCESS) {
        NT_ExplainError(status, errBuf, sizeof(errBuf));
        CONFIGEXIT("Napatech: NT_InfoOpen failed: %s", errBuf);
    }

    NtInfo_t info;
    memset(&info, 0, sizeof(info));
    info.cmd = NT_INFO_CMD_READ_STREAM;
    if ((status = NT_InfoRead(hInfo, &info)) != NT_SUCCESS) {
        NT_ExplainError(status, errBuf, sizeof(errBuf));
        NT_InfoClose(hInfo);
        CONFIGEXIT("Napatech: NT_INFO_CMD_READ_STREAM failed: %s", errBuf);
    }
    NT_InfoClose(hInfo);

    uint32_t count = info.u.stream.data.count;
    if (count == 0) {
        CONFIGEXIT("Napatech: No stream IDs with host buffers found. "
                   "Check ntservice.ini HostBuffersRx and apply NTPL Assign rules.");
    }

    int *ids = g_malloc(count * sizeof(int));
    for (uint32_t i = 0; i < count; i++)
        ids[i] = info.u.stream.data.streamIDList[i];
    *ids_out   = ids;
    *count_out = (int)count;
}

/* -----------

r_napatech_init(const char *UNUSED(name))
{
    int  status;
    char errBuf[NT_ERRBUF_SIZE];

    /* --------------------------------------------------------------------- *
     * NT_Init and stream opens MUST happen here (init), NOT in start().      *
     *                                                                        *
     * Arkime drops privileges (setuid to dropUser) immediately after calling *
     * arkime_readers_set() in main(), which is what triggers this init()     *
     * callback.  By the time start() runs (from arkime_ready_gfunc via the   *
     * GLib main loop), the process is already running as dropUser (nobody)   *
     * and cannot open /dev/nt3gd (crw------- root root).                     *
     *                                                                        *
     * NTAPI's NT_Init opens /dev/nt3gd for mmap; NT_NetRxOpen allocates     *
     * per-stream host buffers mapped from ntservice.  Both require root.     *
     * --------------------------------------------------------------------- */

    if ((status = NT_Init(NTAPI_VERSION)) != NT_SUCCESS) {
        NT_ExplainError(status, errBuf, sizeof(errBuf));
        CONFIGEXIT("Napatech: NT_Init failed: %s", errBuf);
    }

    /* Optionally apply NTPL from a file before opening streams.
     * Set ntplFile=/path/to/arkime-streams.ntpl in config.ini to have the
     * plugin configure stream/port assignments automatically at startup.
     * If not set, NTPL must be applied manually (e.g. via ntpl -f ...). */
    char *ntplFile = arkime_config_str(NULL, "ntplFile", NULL);
    if (ntplFile) {
        NtConfigStream_t hCfg;
        NtNtplInfo_t     ntplInfo;

        if ((status = NT_ConfigOpen(&hCfg, "arkime-ntpl")) != NT_SUCCESS) {
            NT_ExplainError(status, errBuf, sizeof(errBuf));
            g_free(ntplFile);
            CONFIGEXIT("Napatech: NT_ConfigOpen failed: %s", errBuf);
        }

        FILE *f = fopen(ntplFile, "r");
        if (!f) {
            NT_ConfigClose(hCfg);
            g_free(ntplFile);
            CONFIGEXIT("Napatech: Cannot open ntplFile '%s': %s", ntplFile, strerror(errno));
        }

        char line[4096];
        int  linenum = 0;
        while (fgets(line, sizeof(line), f)) {
            linenum++;
            char *p = line;
            while (*p == ' ' || *p == '\t') p++;
            if (*p == '#' || *p == '\n' || *p == '\r' || *p == '\0') continue;
            size_t len = strlen(p);
            while (len > 0 && (p[len - 1] == '\n' || p[len - 1] == '\r')) p[--len] = '\0';
            if (len == 0) continue;

            if ((status = NT_NTPL(hCfg, p, &ntplInfo, NT_NTPL_PARSER_VALIDATE_NORMAL)) != NT_SUCCESS) {
                NT_ExplainError(status, errBuf, sizeof(errBuf));
                fclose(f);
                NT_ConfigClose(hCfg);
                g_free(ntplFile);
                CONFIGEXIT("Napatech: NTPL line %d failed: %s", linenum, errBuf);
            }
        }
        fclose(f);
        NT_ConfigClose(hCfg);
        LOG("Napatech: applied NTPL from '%s'", ntplFile);
        g_free(ntplFile);
    }

    /* Resolve stream IDs (from ntStreamIds= config or driver) and open them.
     * reader_napatech_get_stream_ids() returns a heap-allocated int[] whose
     * length drives the allocation of ntStreams/ntTotalPkts — no static cap. */
    {
        int *streamIds;
        int  streamCount;
        reader_napatech_get_stream_ids(&streamIds, &streamCount);

        ntStreams   = g_malloc0(streamCount * sizeof(NtStream_t));
        ntTotalPkts = g_malloc0(streamCount * sizeof(uint64_t));
        ntNumStreams = streamCount;

        for (int i = 0; i < streamCount; i++) {
            int s = streamIds[i];
            char streamName[64];
            snprintf(streamName, sizeof(streamName), "arkime_rx_%d", s);
            /* NT_NET_INTERFACE_SEGMENT: NT_NetRxGet returns a segment of N
             * packets at a time, enabling zero-copy batch release.
             * hostBufAllowance = -1: use the maximum host buffer for this
             * stream as configured in ntservice.ini HostBuffersRx. */
            status = NT_NetRxOpen(&ntStreams[i].hStream, streamName,
                                  NT_NET_INTERFACE_SEGMENT, s, -1);
            if (status != NT_SUCCESS) {
                NT_ExplainError(status, errBuf, sizeof(errBuf));
                g_free(streamIds);
                CONFIGEXIT("Napatech: NT_NetRxOpen(stream %d) failed: %s", s, errBuf);
            }
            ntStreams[i].streamId     = s;
            ntStreams[i].interfacePos = (uint8_t)i;
        }
        g_free(streamIds);
        LOG("Napatech: opened %d stream(s)", ntNumStreams);
    }

    /* Software BPF filter: compile config.bpf using a dead pcap handle.
     * Same pattern as reader-tzsp.c. Filtering runs per-packet in the
     * capture thread before any packet allocation. */
    use_sw_bpf = FALSE;
    if (config.bpf) {
        pcap_t *dead = pcap_open_dead(DLT_EN10MB, config.snapLen);
        if (pcap_compile(dead, &sw_bpf, config.bpf, 1, PCAP_NETMASK_UNKNOWN) == -1) {
            CONFIGEXIT("Napatech: Couldn't compile bpf filter '%s': %s",
                       config.bpf, pcap_geterr(dead));
        }
        pcap_close(dead);
        use_sw_bpf = TRUE;
        LOG("Napatech: software BPF filter active: '%s'", config.bpf);
    }

    ntDropped = 0;

    /* Register callbacks */
    arkime_reader_start = reader_napatech_start;
    arkime_reader_stats = reader_napatech_stats;
    arkime_reader_stop  = reader_napatech_stop;
    arkime_reader_exit  = reader_napatech_exit;

    LOG("Napatech reader initialized: %d stream(s) open", ntNumStreams);
}

/* -------------

void arkime_plugin_init()
{
    entropy_plugin_num = arkime_plugins_register("entropy", TRUE);

    entropyChunkSize = arkime_config_int(NULL, "entropyChunkSize", 0xffffffff, 1, 0xffffffff);
    entropyMaxUniqueValues = arkime_config_int(NULL, "entropyMaxUniqueValues", 10, 1, 0xffffffff);

    entropy_field[0] = arkime_field_define("general", "integer",
                                           "entropy.src", "Entropy Src", "entropy.src",
                                           "Shannon entropy of the source TCP/UDP data bytes, multiplied by 100",
                                           ARKIME_FIELD_TYPE_INT_ARRAY_UNIQUE, 0,
                                           (char *)NULL);

    entropy_field[1] = arkime_field_define("general", "integer",
                                           "entropy.dst", "Entropy Dst", "entropy.dst",
                                           "Shannon entropy of the destination TCP/UDP data bytes, multiplied by 100",
                                           ARKIME_FIELD_TYPE_INT_ARRAY_UNIQUE, 0,
                                           (char *)NULL);

    // A uint16_t histogram is enough when no single count (bounded by the
    // chunk size) can exceed 0xffff, which halves the per-session memory.
    if (entropyChunkSize <= 0xffff) {
        arkime_plugins_set_cb("entropy",
                              NULL,
                              entropy_udp_cb_16,
                              entropy_tcp_cb_16,
                              NULL,
                              entropy_save_16,
                              NULL,
                              NULL,
                              NULL);
    } else {
        arkime_plugins_set_cb("entropy",
                              NULL,
                              entropy_udp_cb_32,
                              entropy_tcp_cb_32,
                              NULL,
                              entropy_save_32,
                              NULL,
                              NULL,
                              NULL);
    }
}

void arkime_plugins_load(char **plugins, gboolean loadParsers)
    // A plugin may register a new load extension (e.g. .lua), so reload parsers
    // to pick those up. Skipped for rootPlugins, which run before parsers init.
    if (loadParsers) {
        int arkime_parsers_load();
        arkime_parsers_load();
    }

int arkime_parsers_add_protocol_cb(ArkimeSession_t *session, void *uw, const uint8_t *UNUSED(data), int UNUSED(remaining), int UNUSED(which))
{
    arkime_session_add_protocol(session, (const char *)uw);
    return 0;
}

LOCAL void ipfix_classify(ArkimeSession_t *session, const uint8_t *data, int len, int UNUSED(which), void *UNUSED(uw))
{
    if (len < 16)
        return;

    uint16_t msgLen = (data[2] << 8) | data[3];
    if (msgLen != len || msgLen < 16)
        return;

    uint32_t exportTime = ((uint32_t)data[4] << 24) | ((uint32_t)data[5] << 16) |
                          ((uint32_t)data[6] << 8)  | (uint32_t)data[7];
    if (exportTime < 1000000000 /*Sep 2001*/)
        return;

    arkime_session_add_protocol(session, "ipfix");
}

LOCAL void sflow_classify(ArkimeSession_t *session, const uint8_t *data, int len, int UNUSED(which), void *UNUSED(uw))
{
    if (len < 28)
        return;

    if (data[4] != 0 || data[5] != 0 || data[6] != 0 ||
        (data[7] != 1 && data[7] != 2))
        return;

    if (data[7] == 2 && len < 40)
        return;

    arkime_session_add_protocol(session, "sflow");
}

LOCAL uint32_t opcua_msg_len(const uint8_t *p)
{
    BSB bsb;
    BSB_INIT(bsb, p + 4, 4);
    uint32_t msgLen = 0;
    BSB_LIMPORT_u32(bsb, msgLen);
    return msgLen;
}

LOCAL int opcua_is_valid_header(const uint8_t *data)
{
    /* chunk type must be F, C, or A */
    if (data[3] != 'F' && data[3] != 'C' && data[3] != 'A')
        return 0;

    /* message type must be one of the known 3-letter codes; switch on the
     * first byte first to limit the number of memcmp calls. */
    switch (data[0]) {
    case 'H':
        return memcmp(data + 1, "EL", 2) == 0;
    case 'A':
        return memcmp(data + 1, "CK", 2) == 0;
    case 'E':
        return memcmp(data + 1, "RR", 2) == 0;
    case 'R':
        return memcmp(data + 1, "HE", 2) == 0;
    case 'O':
        return memcmp(data + 1, "PN", 2) == 0;
    case 'C':
        return memcmp(data + 1, "LO", 2) == 0;
    case 'M':
        return memcmp(data + 1, "SG", 2) == 0;
    default:
        return 0;
    }
}

LOCAL void opcua_parse_hel(ArkimeSession_t *session, const uint8_t *p, uint32_t msgLen)
{
    if (msgLen < OPCUA_HEADER_LEN + OPCUA_HEL_PRELUDE + 4)
        return;

    BSB bsb;
    BSB_INIT(bsb, p + OPCUA_HEADER_LEN + OPCUA_HEL_PRELUDE, msgLen - OPCUA_HEADER_LEN - OPCUA_HEL_PRELUDE);

    int32_t urlLen = 0;
    BSB_LIMPORT_u32(bsb, urlLen);
    if (BSB_IS_ERROR(bsb))
        return;
    if (urlLen <= 0 || urlLen > OPCUA_MAX_URL || (uint32_t)urlLen > BSB_REMAINING(bsb))
        return;
    arkime_field_string_add(endpointUrlField, session, (const char *)BSB_WORK_PTR(bsb), urlLen, TRUE);
}

LOCAL void opcua_parse_opn(ArkimeSession_t *session, const uint8_t *p, uint32_t msgLen)
{
    if (msgLen < OPCUA_HEADER_LEN + 4 + 4)
        return;

    BSB bsb;
    BSB_INIT(bsb, p + OPCUA_HEADER_LEN, msgLen - OPCUA_HEADER_LEN);
    BSB_IMPORT_skip(bsb, 4);                    /* SecureChannelId */

    int32_t sLen = 0;
    BSB_LIMPORT_u32(bsb, sLen);
    if (BSB_IS_ERROR(bsb))
        return;

    if (sLen > 0 && sLen <= OPCUA_MAX_URL && (uint32_t)sLen <= BSB_REMAINING(bsb)) {
        arkime_field_string_add(securityPolicyField, session,
                                (const char *)BSB_WORK_PTR(bsb), sLen, TRUE);
        BSB_IMPORT_skip(bsb, sLen);
    } else if (sLen > 0) {
        /* length set but exceeds our cap or remaining bytes - stream is suspect */
        return;
    }
    /* sLen == 0 (empty) or sLen == -1 (null) both fall through to SenderCertificate */

    int32_t cLen = 0;
    BSB_LIMPORT_u32(bsb, cLen);
    if (BSB_IS_ERROR(bsb))
        return;

    if (cLen > 0 && cLen <= OPCUA_MAX_CERT && (uint32_t)cLen <= BSB_REMAINING(bsb)) {
        arkime_parsers_call_named_func(tls_process_single_certificate_func,
                                       session, BSB_WORK_PTR(bsb), cLen, NULL);
    }
}

LOCAL int opcua_parser(ArkimeSession_t *session, void *uw, const uint8_t *data, int len, int which)
{
    ArkimeParserBuf_t *info = uw;

    if (arkime_parser_buf_add(info, which, data, len) < 0)
        return ARKIME_PARSER_UNREGISTER;

    while (info->len[which] >= OPCUA_HEADER_LEN) {
        const uint8_t *p = info->buf[which];

        if (!opcua_is_valid_header(p))
            return ARKIME_PARSER_UNREGISTER;

        uint32_t msgLen = opcua_msg_len(p);
        if (msgLen < OPCUA_HEADER_LEN || msgLen > OPCUA_MAX_MSG)
            return ARKIME_PARSER_UNREGISTER;
        if (msgLen > (uint32_t)info->bufMax)
            return ARKIME_PARSER_UNREGISTER;   /* won't ever fit; stop trying */
        if ((uint32_t)info->len[which] < msgLen)
            return 0;                          /* wait for more data */

        if (p[0] == 'H' && p[3] == 'F')
            opcua_parse_hel(session, p, msgLen);
        else if (p[0] == 'O' && p[3] == 'F')
            opcua_parse_opn(session, p, msgLen);

        arkime_parser_buf_del(info, which, msgLen);
        info->state[which]++;

        if (info->state[which] >= OPCUA_MAX_MSGS)
            return ARKIME_PARSER_UNREGISTER;
    }

    return 0;
}

LOCAL void opcua_classify(ArkimeSession_t *session, const uint8_t *data, int len, int UNUSED(which), void *UNUSED(uw))
{
    if (len < OPCUA_HEADER_LEN || !opcua_is_valid_header(data))
        return;

    uint32_t msgLen = opcua_msg_len(data);
    if (msgLen < OPCUA_HEADER_LEN || msgLen > OPCUA_MAX_MSG)
        return;

    if (arkime_session_has_protocol(session, "opcua"))
        return;

    arkime_session_add_protocol(session, "opcua");

    ArkimeParserBuf_t *info = arkime_parser_buf_create2(1024, OPCUA_BUF_MAX);
    arkime_parsers_register(session, opcua_parser, info, arkime_parser_buf_session_free);
}

void arkime_parser_init()
{
    arkime_parsers_classifier_register_tcp("opcua", NULL, 0, (const uint8_t *)"HELF", 4, opcua_classify);

    endpointUrlField = arkime_field_define("opcua", "termfield",
                                           "opcua.endpointUrl", "OPC UA Endpoint URL", "opcua.endpointUrl",
                                           "OPC UA endpoint URL from the Hello message",
                                           ARKIME_FIELD_TYPE_STR_GHASH, ARKIME_FIELD_FLAG_CNT,
                                           (char *)NULL);

    securityPolicyField = arkime_field_define("opcua", "termfield",
                                              "opcua.securityPolicyUri", "OPC UA Security Policy", "opcua.securityPolicyUri",
                                              "OPC UA SecurityPolicyUri from the OpenSecureChannel message",
                                              ARKIME_FIELD_TYPE_STR_GHASH, ARKIME_FIELD_FLAG_CNT,
                                              (char *)NULL);

    tls_process_single_certificate_func = arkime_parsers_get_named_func("tls_process_single_certificate");
}

LOCAL void arkime_rules_bpfp_free(gpointer data)
{
    struct bpf_program *bpfp = data;
    if (bpfp->bf_len)
        pcap_freecode(bpfp);
    g_free(bpfp);
}

LOCAL void arkime_ntlm_add_string(ArkimeSession_t *session, int field, BSB *sb, int unicode)
{
    if (field < 0 || BSB_IS_ERROR(*sb))
        return;
    uint32_t len = BSB_REMAINING(*sb);
    const uint8_t *buf = BSB_WORK_PTR(*sb);
    if (len == 0)
        return;

    if (unicode) {
        GError *error = NULL;
        gsize bread, bwritten;
        char *out = g_convert((const char *)buf, len, "utf-8", "ucs-2le", &bread, &bwritten, &error);
        if (error) {
            if (config.debug)
                LOG("ntlm utf-8 convert error: %s", error->message);
            g_error_free(error);
            return;
        }
        if (!out)
            return;
        if (!arkime_field_string_add(field, session, out, -1, FALSE))
            g_free(out);
    } else {
        arkime_field_string_add(field, session, (const char *)buf, len, TRUE);
    }
}

LOCAL gboolean arkime_ntlm_secbuf(const uint8_t *msg, uint32_t msglen,
                                  uint32_t pos, BSB *out)
{
    BSB_INIT(*out, NULL, 0);
    if (pos > msglen || msglen - pos < 8)
        return FALSE;

    BSB hdr;
    uint16_t slen;
    uint32_t soff;
    BSB_INIT(hdr, msg + pos, 8);
    BSB_LIMPORT_u16(hdr, slen);
    BSB_LIMPORT_skip(hdr, 2);              // skip MaxLen
    BSB_LIMPORT_u32(hdr, soff);
    if (BSB_IS_ERROR(hdr) || slen == 0)
        return FALSE;
    /* Overflow-safe bounds check: soff <= msglen AND slen <= msglen - soff. */
    if (soff > msglen || slen > msglen - soff)
        return FALSE;
    BSB_INIT(*out, msg + soff, slen);
    return TRUE;
}

LOCAL void arkime_ntlm_add_version(ArkimeSession_t *session, BSB *vb)
{
    uint8_t  major, minor;
    uint16_t build;
    BSB_LIMPORT_u08(*vb, major);
    BSB_LIMPORT_u08(*vb, minor);
    BSB_LIMPORT_u16(*vb, build);
    if (BSB_IS_ERROR(*vb))
        return;
    char buf[64];
    snprintf(buf, sizeof(buf), "%u.%u.%u", major, minor, build);
    arkime_field_string_add(ntlmVersionField, session, buf, -1, TRUE);
}

void arkime_parsers_ntlm_decode(ArkimeSession_t *session,
                                const uint8_t *data, uint32_t dlen)
{
    if (!data || dlen < 12)
        return;
    if (memcmp(data, "NTLMSSP\0", 8) != 0)
        return;

    BSB msg;
    BSB_INIT(msg, data, dlen);
    BSB_LIMPORT_skip(msg, 8); // already validated NTLMSSP signature

    uint32_t mtype;
    BSB_LIMPORT_u32(msg, mtype);
    if (BSB_IS_ERROR(msg) || mtype < 1 || mtype > 3)
        return;

    arkime_session_add_protocol(session, "ntlm");
    arkime_field_int_add(ntlmTypeField, session, mtype);

    uint32_t flags = 0;
    uint32_t domainPos = 0, userPos = 0, hostPos = 0, targetPos = 0, versionPos = 0;

    /* msg.ptr currently at offset 12 (after signature + mtype). */
    switch (mtype) {
    case 1: // NEGOTIATE_MESSAGE: flags @12
        BSB_LIMPORT_u32(msg, flags);
        domainPos  = 16;
        hostPos    = 24;
        versionPos = 32;
        break;
    case 2: // CHALLENGE_MESSAGE: target secbuf @12, flags @20
        targetPos  = 12;
        BSB_LIMPORT_skip(msg, 8);          // skip target secbuf
        BSB_LIMPORT_u32(msg, flags);
        versionPos = 48;
        break;
    case 3: // AUTHENTICATE_MESSAGE: lm/nt/domain/user/host/sessionkey, flags @60
        domainPos  = 28;
        userPos    = 36;
        hostPos    = 44;
        BSB_LIMPORT_skip(msg, 48);         // skip 6 secbufs (lm,nt,domain,user,host,sessionkey)
        BSB_LIMPORT_u32(msg, flags);
        versionPos = 64;
        break;
    }

    if (BSB_IS_ERROR(msg))
        return;

    int unicode = (flags & NTLM_NEGOTIATE_UNICODE) ? 1 : 0;
    if (mtype == 1)
        unicode = 0; // Type 1 OemDomainName/OemWorkstationName are always OEM
    BSB sb;

    if (domainPos && arkime_ntlm_secbuf(data, dlen, domainPos, &sb))
        arkime_ntlm_add_string(session, ntlmDomainField, &sb, unicode);
    if (userPos && arkime_ntlm_secbuf(data, dlen, userPos, &sb))
        arkime_ntlm_add_string(session, userField, &sb, unicode);
    if (hostPos && arkime_ntlm_secbuf(data, dlen, hostPos, &sb))
        arkime_ntlm_add_string(session, ntlmHostField, &sb, unicode);
    if (targetPos && arkime_ntlm_secbuf(data, dlen, targetPos, &sb))
        arkime_ntlm_add_string(session, ntlmTargetField, &sb, unicode);

    if ((flags & NTLM_NEGOTIATE_VERSION) && versionPos) {
        BSB vb;
        BSB_INIT(vb, data, dlen);
        BSB_LIMPORT_skip(vb, versionPos);
        if (BSB_NOT_ERROR(vb) && BSB_REMAINING(vb) >= 8)
            arkime_ntlm_add_version(session, &vb);
    }
}

gboolean arkime_parsers_ntlm_decode_base64(ArkimeSession_t *session,
                                           const char *b64, int b64len)
{
    if (!b64 || b64len < 11)
        return FALSE;

    while (b64len > 0 && (*b64 == ' ' || *b64 == '\t')) { b64++; b64len--; }
    while (b64len > 0 && (b64[b64len - 1] == ' ' || b64[b64len - 1] == '\t' ||
                          b64[b64len - 1] == '\r' || b64[b64len - 1] == '\n'))
        b64len--;

    if (b64len < 11 || memcmp(b64, "TlRMTVNTUA", 10) != 0)
        return FALSE;

    char *s = g_strndup(b64, b64len);
    gsize out_len = 0;
    guchar *decoded = g_base64_decode(s, &out_len);
    g_free(s);

    gboolean dispatched = FALSE;
    if (decoded) {
        if (out_len >= 12) {
            arkime_parsers_ntlm_decode(session, decoded, out_len);
            dispatched = TRUE;
        }
        g_free(decoded);
    }
    return dispatched;
}

LOCAL void imap_process_line(IMAPInfo_t *imap, ArkimeSession_t *session, const char *line, int len, int which)
{
    /* NTLM detection / decoding */
    if (which != imap->serverWhich && len > 16) {
        /* Client: "<tag> AUTHENTICATE NTLM [<base64>]" */
        const char *cmd = line;
        while (cmd < line + len && !isspace(*cmd)) cmd++;
        while (cmd < line + len && isspace(*cmd)) cmd++;
        if (line + len - cmd >= 17 && strncasecmp(cmd, "AUTHENTICATE NTLM", 17) == 0) {
            imap->inNtlmAuth = 1;
            const char *rest = cmd + 17;
            if (rest < line + len && *rest == ' ')
                arkime_parsers_ntlm_decode_base64(session, rest + 1, (line + len) - (rest + 1));
            return;
        }
    }
    if (imap->inNtlmAuth) {
        const char *b = line;
        int blen = len;
        /* Server continuation: "+ TlRMTVN..." */
        if (which == imap->serverWhich && blen > 2 && b[0] == '+' && b[1] == ' ') {
            b += 2; blen -= 2;
        }
        if (arkime_parsers_ntlm_decode_base64(session, b, blen))
            return;
    }

    /* Server responses */
    if (which == imap->serverWhich) {
        if (len > 6 && line[0] == '*' && line[1] == ' ') {
            if (arkime_memcasestr(line, len, "fetch", 5)) {
                imap->inFetch = TRUE;
                imap->inHeaders = TRUE;
            }
        } else if (imap->inFetch && len > 0 && line[0] == ')') {
            imap->inFetch = FALSE;
            imap->inHeaders = FALSE;
        } else if (imap->inFetch && imap->inHeaders) {
            if (len == 0) {
                imap->inHeaders = FALSE;
            } else {
                imap_parse_header_line(imap, session, line, len);
            }
        }
    }
    /* Client commands */
    else {
        if (len > 7) {
            const char *cmd = line;
            while (cmd < line + len && !isspace(*cmd)) cmd++;
            while (cmd < line + len && isspace(*cmd)) cmd++;

            if (strncasecmp(cmd, "SELECT ", 7) == 0 || strncasecmp(cmd, "EXAMINE ", 8) == 0) {
                const char *folder = cmd + (strncasecmp(cmd, "SELECT", 6) == 0 ? 7 : 8);
                while (folder < line + len && isspace(*folder)) folder++;

                const char *folderEnd = line + len;
                if (folder < line + len && *folder == '"') {
                    folder++;
                    folderEnd = memchr(folder, '"', folderEnd - folder);
                    if (!folderEnd) folderEnd = line + len;
                } else {
                    while (folderEnd > folder && isspace(folderEnd[-1])) folderEnd--;
                }

                if (folderEnd > folder) {
                    arkime_field_string_add(folderField, session, folder, folderEnd - folder, TRUE);
                }
            }
        }
    }
}

LOCAL void pop3_process_line(POP3Info_t *pop3, ArkimeSession_t *session, const char *line, int len, int which)
{
    /* Client: "AUTH NTLM [<base64>]" */
    if (which != pop3->serverWhich && len >= 9 &&
        strncasecmp(line, "AUTH NTLM", 9) == 0) {
        arkime_session_add_tag(session, "pop3:authntlm");
        pop3->inNtlmAuth = 1;
        if (len > 10 && line[9] == ' ') {
            if (arkime_parsers_ntlm_decode_base64(session, line + 10, len - 10))
                pop3->ntlmCount++;
        }
        return;
    }

    if (pop3->inNtlmAuth) {
        const char *b = line;
        int blen = len;
        /* Server continuation: "+ TlRMTVN..." */
        if (which == pop3->serverWhich && blen > 2 && b[0] == '+' && b[1] == ' ') {
            b += 2; blen -= 2;
        }
        if (arkime_parsers_ntlm_decode_base64(session, b, blen)) {
            pop3->ntlmCount++;
            /* After Type 3 (third message from client) we're done. */
            if (pop3->ntlmCount >= 3)
                pop3->done = 1;
            return;
        }
    }

    /* Client: "USER <name>" */
    if (which != pop3->serverWhich && len > 5 &&
        strncasecmp(line, "USER ", 5) == 0) {
        const char *u = line + 5;
        int ulen = len - 5;
        while (ulen > 0 && isspace((unsigned char)*u)) { u++; ulen--; }
        while (ulen > 0 && isspace((unsigned char)u[ulen - 1])) ulen--;
        if (ulen > 0)
            arkime_field_string_add_lower(userField, session, u, ulen);
        pop3->done = 1;
    }
}

LOCAL int pop3_parser(ArkimeSession_t *session, void *uw, const uint8_t *data, int remaining, int which)
{
    POP3Info_t *pop3 = uw;
    GString *line = pop3->line[which];

    while (remaining > 0) {
        const uint8_t *lineEnd = memchr(data, '\n', remaining);
        int lineLen;

        if (lineEnd) {
            lineLen = lineEnd - data;
            if (lineLen > 0 && data[lineLen - 1] == '\r')
                lineLen--;
        } else {
            if (line->len + remaining > 16384) {
                arkime_session_add_tag(session, "pop3:line-too-long");
                return ARKIME_PARSER_UNREGISTER;
            }
            g_string_append_len(line, (const char *)data, remaining);
            return 0;
        }

        if (line->len > 0) {
            if (line->len + lineLen > 16384) {
                arkime_session_add_tag(session, "pop3:line-too-long");
                return ARKIME_PARSER_UNREGISTER;
            }
            g_string_append_len(line, (const char *)data, lineLen);
            pop3_process_line(pop3, session, line->str, line->len, which);
            g_string_truncate(line, 0);
        } else {
            pop3_process_line(pop3, session, (const char *)data, lineLen, which);
        }

        remaining -= (lineEnd - data) + 1;
        data = lineEnd + 1;

        if (pop3->done)
            return ARKIME_PARSER_UNREGISTER;
    }

    return 0;
}

LOCAL void pop3_free(ArkimeSession_t UNUSED(*session), void *uw)
{
    POP3Info_t *pop3 = uw;
    g_string_free(pop3->line[0], TRUE);
    g_string_free(pop3->line[1], TRUE);
    ARKIME_TYPE_FREE(POP3Info_t, pop3);
}

LOCAL void pop3_classify(ArkimeSession_t *session, const uint8_t *data, int len, int which, void *UNUSED(uw))
{
    if (arkime_session_has_protocol(session, "pop3"))
        return;

    if (len < 8)
        return;

    /* Greeting "+OK ..." with "POP" somewhere in it */
    if (memcmp(data, "+OK ", 4) != 0)
        return;

    if (!arkime_memcasestr((const char *)data + 4, len - 4, "pop", 3))
        return;

    arkime_session_add_protocol(session, "pop3");

    POP3Info_t *pop3 = ARKIME_TYPE_ALLOC0(POP3Info_t);
    pop3->line[0] = g_string_sized_new(256);
    pop3->line[1] = g_string_sized_new(256);
    pop3->serverWhich = which;

    arkime_parsers_register(session, pop3_parser, pop3, pop3_free);
}

void arkime_field_free_one(ArkimeSession_t *session, int pos)
{
    ArkimeString_t             *hstring;
    ArkimeStringHashStd_t      *shash;
    ArkimeInt_t                *hint;
    ArkimeIntHashStd_t         *ihash;
    ArkimeFieldObject_t        *ho;
    ArkimeFieldObjectHashStd_t *ohash;
    ArkimeFieldObjectFreeFunc   freeCB;
    ArkimeField_t              *field;

    if (pos < 0 || pos >= session->maxFields)
        return;
    if (!(field = session->fields[pos]))
        return;

    switch (config.fields[pos]->type) {
    case ARKIME_FIELD_TYPE_STR:
        g_free(field->str);
        break;
    case ARKIME_FIELD_TYPE_STR_ARRAY:
        g_ptr_array_free(field->sarray, TRUE);
        break;
    case ARKIME_FIELD_TYPE_STR_HASH:
        shash = field->shash;
        HASH_FORALL_POP_HEAD2(s_, *shash, hstring) {
            g_free(hstring->str);
            ARKIME_TYPE_FREE(ArkimeString_t, hstring);
        }
        ARKIME_TYPE_FREE(ArkimeStringHashStd_t, shash);
        break;
    case ARKIME_FIELD_TYPE_INT:
        break;
    case ARKIME_FIELD_TYPE_INT_ARRAY_UNIQUE:
    case ARKIME_FIELD_TYPE_INT_ARRAY:
        g_array_free(field->iarray, TRUE);
        break;
    case ARKIME_FIELD_TYPE_INT_HASH:
        ihash = field->ihash;
        HASH_FORALL_POP_HEAD2(i_, *ihash, hint) {
            ARKIME_TYPE_FREE(ArkimeInt_t, hint);
        }
        ARKIME_TYPE_FREE(ArkimeIntHashStd_t, ihash);
        break;
    case ARKIME_FIELD_TYPE_FLOAT:
        break;
    case ARKIME_FIELD_TYPE_FLOAT_ARRAY:
        g_array_free(field->farray, TRUE);
        break;
    case ARKIME_FIELD_TYPE_IP:
        g_free(field->ip);
        break;
    case ARKIME_FIELD_TYPE_IP_GHASH:
    case ARKIME_FIELD_TYPE_INT_GHASH:
    case ARKIME_FIELD_TYPE_STR_GHASH:
    case ARKIME_FIELD_TYPE_FLOAT_GHASH:
        g_hash_table_destroy(field->ghash);
        break;
    case ARKIME_FIELD_TYPE_OBJECT:
        freeCB = config.fields[pos]->object_free;
        ohash = field->ohash;
        HASH_FORALL_POP_HEAD2(o_, *ohash, ho) {
            freeCB(ho);
        }
        ARKIME_TYPE_FREE(ArkimeFieldObjectHashStd_t, ohash);
        break;
    }
    ARKIME_TYPE_FREE(ArkimeField_t, field);
    session->fields[pos] = NULL;
}

LOCAL int ftp_process_client_line(ArkimeSession_t *session, const char *line, int len)
{
    while (len > 0 && (*line == ' ' || *line == '\t')) {
        line++;
        len--;
    }
    if (len < 3)
        return 0;

    const char *space = memchr(line, ' ', len);
    int cmdLen = space ? (int)(space - line) : len;
    if (cmdLen < 3 || cmdLen > 8)
        return 0;

    char cmd[16];
    int i;
    for (i = 0; i < cmdLen; i++) {
        if (!isalpha((uint8_t)line[i]))
            return 0;
        cmd[i] = toupper((uint8_t)line[i]);
    }
    cmd[cmdLen] = 0;

    if (strcmp(cmd, "HELO") == 0 || strcmp(cmd, "EHLO") == 0 || strcmp(cmd, "LHLO") == 0)
        return 1;

    const char *arg = space ? space + 1 : NULL;
    int argLen = space ? (len - cmdLen - 1) : 0;
    while (argLen > 0 && (*arg == ' ' || *arg == '\t')) {
        arg++;
        argLen--;
    }
    while (argLen > 0 && (arg[argLen - 1] == '\r' || arg[argLen - 1] == ' ' || arg[argLen - 1] == '\t')) {
        argLen--;
    }

    arkime_field_string_add(commandField, session, cmd, cmdLen, TRUE);

    if (argLen <= 0)
        return 0;

    if (strcmp(cmd, "USER") == 0) {
        arkime_field_string_add_lower(userField, session, arg, argLen);
    } else if (strcmp(cmd, "PASS") == 0) {
        arkime_session_add_tag(session, "ftp:password");
    } else if (strcmp(cmd, "RETR") == 0 || strcmp(cmd, "STOR") == 0 ||
               strcmp(cmd, "STOU") == 0 || strcmp(cmd, "APPE") == 0 ||
               strcmp(cmd, "DELE") == 0 || strcmp(cmd, "RNFR") == 0 ||
               strcmp(cmd, "RNTO") == 0 || strcmp(cmd, "MKD")  == 0 ||
               strcmp(cmd, "RMD")  == 0 || strcmp(cmd, "SIZE") == 0 ||
               strcmp(cmd, "MDTM") == 0) {
        arkime_field_string_add(filenameField, session, arg, argLen, TRUE);
    }
    return 0;
}

LOCAL void ftp_process_server_line(FTPInfo_t *ftp, ArkimeSession_t *session, const char *line, int len)
{
    if (len < 4)
        return;
    if (!isdigit((uint8_t)line[0]) || !isdigit((uint8_t)line[1]) || !isdigit((uint8_t)line[2]))
        return;

    int code = (line[0] - '0') * 100 + (line[1] - '0') * 10 + (line[2] - '0');
    arkime_field_int_add(responseCodeField, session, code);

    if (!ftp->sawBanner && code == 220) {
        const char *msg = line + 4;
        int msgLen = len - 4;
        while (msgLen > 0 && (*msg == '-' || *msg == ' ' || *msg == '\t')) {
            msg++;
            msgLen--;
        }
        while (msgLen > 0 && (msg[msgLen - 1] == '\r' || msg[msgLen - 1] == ' ' || msg[msgLen - 1] == '\t' || msg[msgLen - 1] == '-')) {
            msgLen--;
        }
        if (msgLen > 0) {
            arkime_field_string_add(bannerField, session, msg, msgLen, TRUE);
            ftp->sawBanner = 1;
        }
    }
}

LOCAL int ftp_parser(ArkimeSession_t *session, void *uw, const uint8_t *data, int remaining, int which)
{
    FTPInfo_t *ftp = uw;
    GString *buf = ftp->line[which];
    int isServer = (which == ftp->serverWhich);

    while (remaining > 0) {
        const uint8_t *lineEnd = memchr(data, '\n', remaining);
        int chunkLen;

        if (!lineEnd) {
            if (buf->len + remaining > FTP_LINE_MAX) {
                g_string_truncate(buf, 0);
                return ARKIME_PARSER_UNREGISTER;
            }
            g_string_append_len(buf, (const char *)data, remaining);
            return 0;
        }

        chunkLen = lineEnd - data;
        if (buf->len + chunkLen > FTP_LINE_MAX) {
            g_string_truncate(buf, 0);
            return ARKIME_PARSER_UNREGISTER;
        }
        g_string_append_len(buf, (const char *)data, chunkLen);

        int lineLen = buf->len;
        if (lineLen > 0 && buf->str[lineLen - 1] == '\r')
            lineLen--;

        if (lineLen > 0) {
            if (isServer) {
                ftp_process_server_line(ftp, session, buf->str, lineLen);
            } else if (ftp_process_client_line(session, buf->str, lineLen)) {
                arkime_field_free_one(session, bannerField);
                arkime_field_free_one(session, commandField);
                arkime_field_free_one(session, filenameField);
                arkime_field_free_one(session, responseCodeField);
                arkime_session_rm_protocol(session, "ftp");
                g_string_truncate(buf, 0);
                return ARKIME_PARSER_UNREGISTER;
            }
        }

        g_string_truncate(buf, 0);

        remaining -= chunkLen + 1;
        data = lineEnd + 1;
    }

    return 0;
}

LOCAL void ftp_free(ArkimeSession_t UNUSED(*session), void *uw)
{
    FTPInfo_t *ftp = uw;
    g_string_free(ftp->line[0], TRUE);
    g_string_free(ftp->line[1], TRUE);
    ARKIME_TYPE_FREE(FTPInfo_t, ftp);
}

LOCAL void ftp_classify(ArkimeSession_t *session, const uint8_t *data, int len, int which, void *UNUSED(uw))
{
    if (arkime_session_has_protocol(session, "ftp"))
        return;

    if (g_strstr_len((const char *)data, len, "LMTP") != NULL)
        return;
    if (g_strstr_len((const char *)data, len, "SMTP") != NULL)
        return;
    if (g_strstr_len((const char *)data, len, " TLS") != NULL)
        return;

    arkime_session_add_protocol(session, "ftp");

    FTPInfo_t *ftp = ARKIME_TYPE_ALLOC0(FTPInfo_t);
    ftp->line[0] = g_string_sized_new(128);
    ftp->line[1] = g_string_sized_new(128);
    ftp->serverWhich = which;

    arkime_parsers_register(session, ftp_parser, ftp, ftp_free);
}

void arkime_parser_init()
{
    userField = arkime_field_by_db("user");

    commandField = arkime_field_define("ftp", "uptermfield",
                                       "ftp.command", "Command", "ftp.command",
                                       "FTP command",
                                       ARKIME_FIELD_TYPE_STR_HASH, ARKIME_FIELD_FLAG_CNT,
                                       (char *)NULL);

    filenameField = arkime_field_define("ftp", "termfield",
                                        "ftp.filename", "Filename", "ftp.filename",
                                        "FTP filename argument (RETR/STOR/DELE/RNFR/RNTO/MKD/RMD/SIZE/MDTM)",
                                        ARKIME_FIELD_TYPE_STR_HASH, ARKIME_FIELD_FLAG_CNT,
                                        (char *)NULL);

    responseCodeField = arkime_field_define("ftp", "integer",
                                            "ftp.responseCode", "Response Code", "ftp.responseCode",
                                            "FTP response code",
                                            ARKIME_FIELD_TYPE_INT_GHASH, ARKIME_FIELD_FLAG_CNT,
                                            (char *)NULL);

    bannerField = arkime_field_define("ftp", "termfield",
                                      "ftp.banner", "Banner", "ftp.banner",
                                      "FTP server welcome banner",
                                      ARKIME_FIELD_TYPE_STR_HASH, ARKIME_FIELD_FLAG_CNT,
                                      (char *)NULL);

    arkime_parsers_classifier_register_tcp("ftp", NULL, 0, (const uint8_t *)"220 ", 4, ftp_classify);
    arkime_parsers_classifier_register_tcp("ftp", NULL, 0, (const uint8_t *)"220-", 4, ftp_classify);
}

LOCAL const char *radius_code_name(uint8_t code)
{
    switch (code) {
    case 1:
        return "access-request";
    case 2:
        return "access-accept";
    case 3:
        return "access-reject";
    case 4:
        return "accounting-request";
    case 5:
        return "accounting-response";
    case 11:
        return "access-challenge";
    case 12:
        return "status-server";
    case 13:
        return "status-client";
    default:
        return NULL;
    }
}

void *BigAlloc(size_t size)
{
  if (size == 0)
    return NULL;
#ifdef USE_posix_memalign
  {
    const size_t pageSize = g_LargePageSize;
    void *buf = NULL; // on Linux (and other systems), posix_memalign() does not modify memptr on failure (POSIX.1-2008 TC2).
    PRF(printf("\nBigAlloc 0x%08x=%5uMB", (unsigned)(size), (unsigned)(size >> 20));)
    if (pageSize && size > g_LargePageThresholdMin)
    {
      int res;
      const size_t mask = pageSize - 1;
      /* we can allocate aligned size, so data at the end of buffer also will use huge page
         if (size2 for madvise() is not aligned for huge page size)
           { Last data block will use small pages. It reduces memory allocation,
             but last data block with small pages can work slower.
             It's useful, if we have very large HUGE_PAGE: 32MB or 512MB. }
      */
      size_t size2 = (size + mask) & ~mask;
      if (size2 < size || (size & mask) <= g_LargePageThresholdMin)
        size2 = size;
      res = posix_memalign(&buf, pageSize, size2);
      PRF(printf(" posix_memalign size=0x%08x=%5uMB align=%u",
          (unsigned)(size2), (unsigned)(size2 >> 20), (unsigned)pageSize);)
      PRF(printf(" buf=%p", (void *)buf);)
      if (res == 0)
      {
#ifdef Z7_USE_BIG_ALLOC_MADVISE
        if ((g_LargePageFlags & Z7_LARGE_PAGES_FLAG_NO_MADVISE) == 0)
        {
          // Advise the kernel to use huge pages for this memory range
          // MADV_HUGEPAGE / MADV_NOHUGEPAGE : since Linux 2.6.38
          // madvise() only operates on whole pages, therefore addr must be page-aligned (4KB/8KB/16KB/64KB).
          // The value of size is rounded up to a multiple of page size.
          PRF(printf(" madvise g_LargePageFlags=%x", (unsigned)g_LargePageFlags);)
          res = madvise(buf, size2, (g_LargePageFlags & Z7_LARGE_PAGES_FLAG_NO_HUGEPAGE) ? MADV_NOHUGEPAGE : MADV_HUGEPAGE);
          if (res)
          {
            PRF(printf("\nERROR res=%d, errno=%d=%s\n", res, (int)errno, strerror(errno));)
            if (g_LargePageFlags & Z7_LARGE_PAGES_FLAG_FAIL_STOP)
            {
              free(buf);
              return NULL;
            }
          }
        }
#endif // Z7_USE_BIG_ALLOC_MADVISE
        PRF(printf("\n");)
        return buf;
      }
      PRF(printf("\nERROR res=%d=%s\n", res, strerror(res));)
      if (g_LargePageFlags & Z7_LARGE_PAGES_FLAG_FAIL_STOP)
        return NULL;
      // (res == ENOMEM) "Out of memory" is possible, if pageSize is too big.
      // so we do second attempt with smaller alignment
    }
  }
#endif // !USE_posix_memalign
  PRF(printf(" z7_AlignedAlloc size=0x%08x=%5uMB\n", (unsigned)(size), (unsigned)(size >> 20));)
  return z7_AlignedAlloc(size);
}

void z7_LargePage_Set(UInt32 flags, size_t pageSize, size_t threshold)
{
  g_LargePageFlags = flags;

#ifdef _WIN32
  if ((flags & Z7_LARGE_PAGES_FLAG_USE_HUGEPAGE) == 0)
  {
    g_LargePageSize = 0;
    g_LargePageThresholdMin = 0;
  }
  else
  {
    if ((flags & Z7_LARGE_PAGES_FLAG_DIRECT_PAGE_SIZE) == 0)
    {
#ifdef Z7_USE_DYN_GetLargePageMinimum
      Z7_DIAGNOSTIC_IGNORE_CAST_FUNCTION
typedef SIZE_T (WINAPI *Func_GetLargePageMinimum)(VOID);
      const
        Func_GetLargePageMinimum fn =
       (Func_GetLargePageMinimum) Z7_CAST_FUNC_C GetProcAddress(GetModuleHandle(TEXT("kernel32.dll")),
            "GetLargePageMinimum");
      if (fn)
        pageSize = fn();
      else
        pageSize = 0;
#else
      pageSize = GetLargePageMinimum();
#endif
      if (pageSize & (pageSize - 1))
        pageSize = 0;
    }
    g_LargePageSize = pageSize;
    if ((flags & Z7_LARGE_PAGES_FLAG_DIRECT_THRESHOLD) == 0)
      threshold = pageSize / 2;
    g_LargePageThresholdMin = threshold;
  }

#else // !_WIN32

  if (flags & Z7_LARGE_PAGES_FLAG_NO_PAGECODE)
  {
    g_LargePageSize = 0;
    g_LargePageThresholdMin = 0;
  }
  else
  {
    if ((flags & Z7_LARGE_PAGES_FLAG_DIRECT_PAGE_SIZE) == 0)
      pageSize = LARGE_PAGE_SIZE_DEFAULT;
    g_LargePageSize = pageSize;
    if ((flags & Z7_LARGE_PAGES_FLAG_DIRECT_THRESHOLD) == 0)
      threshold = pageSize / 2;
    g_LargePageThresholdMin = threshold;
  }
  // PRF(printf("\ng_LargePageSize=%x g_LargePageThresholdMin = %x g_LargePageFlags = %x", (unsigned)g_LargePageSize, (unsigned)g_LargePageThresholdMin, (unsigned)g_LargePageFlags);)
#endif // !_WIN32
}

static Z7_FORCE_INLINE BoolInt MY_IS_TERMINAL(FILE *x)
{
#ifdef _WIN32
  const int fd = _fileno(x);
  HANDLE h;
  DWORD st;
  if (fd < 0)
    return False;
  if (!_isatty(fd))
    return False;
  h = (HANDLE)(_get_osfhandle(fd));
  if (h == NULL || h == INVALID_HANDLE_VALUE)
    return False;
  return GetConsoleMode(h, &st) != 0;
#else
  return isatty(fileno(x)) != 0;
#endif
}

static Z7_FORCE_INLINE unsigned MyCharLower_Ascii(unsigned c)
{
  if (c >= 'A' && c <= 'Z')
    return (unsigned)(c + 0x20);
  return c;
}

static Z7_FORCE_INLINE
BoolInt IsString1PrefixedByString2_NoCase_Ascii(const UInt16 *s1, const char *s2)
{
  for (;;)
  {
    wchar_t c1;
    const char c2 = *s2++; if (c2 == 0) return True;
    c1 = *s1++;
    if (c1 != (unsigned char)c2 && MyCharLower_Ascii(c1) != MyCharLower_Ascii((unsigned char)c2))
      return False;
  }
}

static Z7_FORCE_INLINE
BoolInt IsReservedFsName(const UInt16 *name, size_t sLen)
{
  unsigned i;
  for (i = 0; i < Z7_ARRAY_SIZE(g_ReservedNames); i++)
  {
    const char *reservedName = g_ReservedNames[i];
    size_t len = strlen(reservedName);
    if (sLen < len)
      continue;
    if (!IsString1PrefixedByString2_NoCase_Ascii(name, reservedName))
      continue;
    if (i >= g_ReservedWithNum_Index)
    {
      if ((unsigned)((unsigned)name[len] - (unsigned)'0') > 9)
        continue;
      len++;
    }
    for (;;)
    {
      unsigned c;
      if (len >= sLen)
        return True;
      c = name[len++];
      if (c == 0 || c == '.')
        return True;
      if (c != ' ')
        break;
    }
  }
  return False;
}

static Z7_FORCE_INLINE
void Correct_FileName_for_FS(UInt16 *s, size_t size)
{
  while (size)
  {
    const unsigned c = s[--size];
    if (c != '.' && c != ' ')
      break;
    s[size] = '_';
  }
}

static Z7_FORCE_INLINE
void NormalizesPathParts_and_Dots(UInt16 *dest, const UInt16 *s, BoolInt isDir)
{
  UInt16 * const destStart = dest;
  size_t len;

  // remove absolute path prefixes
  for (; *s == WCHAR_PATH_SEPARATOR; s++)
  {}

  len = 0;
  for (;;)
  {
    const unsigned c = s[len];
    if (c != 0 && c != WCHAR_PATH_SEPARATOR)
    {
      len++;
      continue;
    }
    {
      if (len == 0
          || (len == 1 && s[len - 1] == '.')
          || (len == 2 && s[len - 1] == '.' && s[len - 2] == '.'))
      {
        if (c == 0)
        {
          if (!isDir)
          {
            *dest++ = '_';
            // if (len == 2) *dest++ = '_'; // for ".." -> "__"
          }
          break;
        }
      }
      else
      {
#ifdef _WIN32
        if (IsReservedFsName(s, len))
          *dest++ = '_';
#endif
        memcpy(dest, s, sizeof(s[0]) * len);
#ifdef _WIN32
        Correct_FileName_for_FS(dest, len);
#endif
        dest += len;
        if (c == 0)
          break;
        *dest++ = WCHAR_PATH_SEPARATOR;
      }
      s += len + 1;
      len = 0;
    }
  }

  if (dest != destStart && dest[-1] == WCHAR_PATH_SEPARATOR)
  {
    if (isDir)
      dest--;
    else
      *dest++ = '_';
  }

  if (dest == destStart)
    *dest++ = '_';
  *dest = 0;
}

static Z7_FORCE_INLINE
void Normalize_Path_from_7z_to_FS(UInt16 *s)
{
  // Normalize_Path_from_7z_to_FS(s);
  for (;; s++)
  {
    unsigned c = *s;
    if (c == 0)
      break;
    if (c == '/') // separator inside 7z archive
      c = WCHAR_PATH_SEPARATOR;
    else if (c == WCHAR_PATH_SEPARATOR)
      c = WCHAR_IN_FILE_NAME_BACKSLASH_REPLACEMENT;
#ifdef _WIN32
    else if (c < 0x20 || c == ':' || c == '*' || c == '?' || c == '<' || c == '>' || c == '|' || c == '"')
      c = '_';
    else
      continue;
    *s = (UInt16)c;
#endif
  }
}

static Z7_FORCE_INLINE
void NormalizePath_for_FS(UInt16 *dest, UInt16 *s, BoolInt isDir)
{
#if WCHAR_PATH_SEPARATOR != L'/'
  Normalize_Path_from_7z_to_FS(s);
#endif
  NormalizesPathParts_and_Dots(dest, s , isDir);
}

static WRes My_DeleteFileAlways(const UInt16 *path)
{
  const DWORD attrib = GetFileAttributesW(path);
  if (// attrib != INVALID_FILE_ATTRIBUTES &&
      (attrib & FILE_ATTRIBUTE_DIRECTORY) == 0 &&
      (attrib & FILE_ATTRIBUTE_READONLY))
  {
    if (!SetFileAttributes(path, attrib & ~(DWORD)FILE_ATTRIBUTE_READONLY))
      return GetLastError();
  }
  if (DeleteFileW(path))
    return 0;
  return GetLastError();
}

static WRes My_DeleteFileAlways(const UInt16 *path)
{
  CBuf buf;
  WRes res;
  Buf_Init(&buf);
  RINOK_WRes(Utf16_To_Char(&buf, path MY_FILE_CODE_PAGE_PARAM))
  res = remove((const char *)buf.data) == 0 ? 0 : errno;
  Buf_Free(&buf, &g_Alloc);
  return res;
}

static Z7_FORCE_INLINE BoolInt IsDangerousTerminalChar(wchar_t c)
{
  // if (c < 0) return False; // it's not expected case
  if (c < 0x20) return True;
  if (c < 0x7F) return False;
  if (c < 0x9F + 1) return True;
  // Unicode Bidirectional (BiDi) control characters:
  if (c < 0x202A) return False;
  if (c < 0x202E + 1) return True;
  if (c < 0x2066) return False;
  if (c < 0x2069 + 1) return True;
  return False;
}

static inline bool IsDangerousTerminalChar(wchar_t c)
{
  // return ((c <= 13 && c >= 7) || c == 0x1b);
#if 0 && defined(WCHAR_MIN) && WCHAR_MIN < 0
  // wchar_t is signed type in posix usually.
  // but negative numbers are not expected in wchar_t strings.
  // if we want to show negative characters, use the following check:
  if (c < 0) return false; // it's not expected case
#endif
  if (c < 0x20) return true;
  if (c < 0x7F) return false;
  if (c < 0x9F + 1) return true;
  // Unicode Bidirectional (BiDi) control characters:
  if (c < 0x202A) return false;
  if (c < 0x202E + 1) return true;
  if (c < 0x2066) return false;
  if (c < 0x2069 + 1) return true;
  return false;
}

static bool ReadFile_to_String(CFSTR fileName, AString &s)
{
  CByteBuffer buf;
  if (!ReadFile_to_Buffer(fileName, buf))
    return false;
  s.SetFrom_CalcLen((const char *)(const void *)(const Byte *)buf, (unsigned)buf.Size());
  return true;
}

bool Get_HugePageSize(UInt64 &pageSize)
{
  AString s2;
  if (ReadFile_to_String("/sys/kernel/mm/transparent_hugepage/hpage_pmd_size", s2))
  {
    pageSize = ConvertStringToUInt64(s2.Ptr(), NULL);
    if (pageSize)
      return true;
  }
  return false;
}

