      {ProjectModel::tr("X"), ProjectModel::tr("Y"), ProjectModel::tr("Z")},
      {                 -100,                  -100,                  -100},
      {                  100,                   100,                   100},
      false
    };
    // code-verify on
    populateThreeAxisDatasets(grp, baseIndex, layout);
    return true;
  }

  return true;
}

}

static int positionalGroupId(const std::vector<Group>& groups, int uniqueId)
{
  if (uniqueId < 0)
    return -1;

  for (const auto& group : groups)
    if (group.uniqueId == uniqueId)
      return group.groupId;

  return -1;
}

static void tallyDatasetWidgetTypes(const Dataset& ds, QMap<int, int>& counts)
{
  const auto keys = SerialStudio::getDashboardWidgets(ds);
  for (const auto& k : keys)
    if (SerialStudio::datasetWidgetEligibleForWorkspace(k))
      counts[static_cast<int>(k)] += 1;
}

static RefAnchor anchorRef(const WidgetRef& r, const std::vector<Group>& groups)
{
  RefAnchor a;
  a.widgetType        = r.widgetType;
  a.sourceGid         = r.groupUniqueId;
  a.datasetFrameIndex = -1;
  a.isGroupOrLed      = false;

  auto git = std::find_if(groups.begin(), groups.end(), [uid = r.groupUniqueId](const auto& g) {
    return g.uniqueId == uid;
  });
  if (git == groups.end())
    return a;

  const auto& g            = *git;
  const auto groupKey      = SerialStudio::getDashboardWidget(g);
  const bool emptyOutPanel = g.groupType == DataModel::GroupType::Output && g.outputWidgets.empty();
  const bool groupRef = SerialStudio::groupWidgetEligibleForWorkspace(groupKey) && !emptyOutPanel
                     && static_cast<int>(groupKey) == r.widgetType;
  const bool ledAggregate = (r.widgetType == static_cast<int>(SerialStudio::DashboardLED));
  if (groupRef || ledAggregate) {
    a.isGroupOrLed = true;
    return a;
  }

  int slot = 0;
  for (const auto& d : g.datasets) {
    const auto keys = SerialStudio::getDashboardWidgets(d);
    for (const auto& k : keys) {
      if (static_cast<int>(k) != r.widgetType)
        continue;

      if (!SerialStudio::datasetWidgetEligibleForWorkspace(k))
        continue;

      if (slot == r.relativeIndex) {
        a.datasetFrameIndex = d.index;
        return a;
      }

      slot += 1;
    }
  }

  return a;
}

static int slotForAnchor(const RefAnchor& a, const Group& g)
{
  if (a.datasetFrameIndex < 0)
    return -1;

  int slot = 0;
  for (const auto& d : g.datasets) {
    const auto keys = SerialStudio::getDashboardWidgets(d);
    for (const auto& k : keys) {
      if (static_cast<int>(k) != a.widgetType)
        continue;

      if (!SerialStudio::datasetWidgetEligibleForWorkspace(k))
        continue;

      if (d.index == a.datasetFrameIndex)
        return slot;

      slot += 1;
    }
  }

  return -1;
}

static void resolveOneWorkspaceRefs(Workspace& ws,
                                    const std::vector<RefAnchor>& src,
                                    const std::vector<Group>& groups)
{
  SS_ASSERT_LOG(src.size() == ws.widgetRefs.size());

  const size_t count = std::min(src.size(), ws.widgetRefs.size());
  for (size_t i = 0; i < count; ++i) {
    auto& r       = ws.widgetRefs[i];
    const auto& a = src[i];

    if (a.sourceGid < 0 || a.isGroupOrLed)
      continue;

    auto git = std::find_if(groups.begin(), groups.end(), [uid = r.groupUniqueId](const auto& g) {
      return g.uniqueId == uid;
    });
    if (git == groups.end())
      continue;

    const int newSlot = slotForAnchor(a, *git);
    if (newSlot >= 0)
      r.relativeIndex = newSlot;
  }
}

static QMap<int, int> runningCountsBeforeGroup(const std::vector<Group>& groups, int groupId)
{
  QMap<int, int> running;
  for (const auto& g : groups) {
    if (!SerialStudio::groupEligibleForWorkspace(g))
      continue;

    if (g.groupId == groupId)
      break;

    const auto groupKey = SerialStudio::getDashboardWidget(g);

    const bool isEmptyOutputPanel =
      g.groupType == DataModel::GroupType::Output && g.outputWidgets.empty();

    if (SerialStudio::groupWidgetEligibleForWorkspace(groupKey) && !isEmptyOutputPanel)
      running[static_cast<int>(groupKey)] += 1;

    for (const auto& ds : g.datasets)
      tallyDatasetWidgetTypes(ds, running);
  }

  return running;
}

QMap<int, int> widgetTypeCountsForGroup(const Group& group)
{
  QMap<int, int> counts;

  if (!SerialStudio::groupEligibleForWorkspace(group))
    return counts;

  auto groupKey = SerialStudio::getDashboardWidget(group);
  if (groupKey == SerialStudio::DashboardPlot3D && !SerialStudio::activated())
    groupKey = SerialStudio::DashboardMultiPlot;

  const bool isEmptyOutputPanel =
    group.groupType == DataModel::GroupType::Output && group.outputWidgets.empty();

  if (SerialStudio::groupWidgetEligibleForWorkspace(groupKey) && !isEmptyOutputPanel)
    counts[static_cast<int>(groupKey)] += 1;

  bool groupHasLed = false;
  for (const auto& ds : group.datasets) {
    if (ds.hideOnDashboard)
      continue;

    const auto keys = SerialStudio::getDashboardWidgets(ds);
    for (const auto& k : keys) {
      if (k == SerialStudio::DashboardLED) {
        groupHasLed = true;
        continue;
      }
      if (!SerialStudio::datasetWidgetEligibleForWorkspace(k))
        continue;

      counts[static_cast<int>(k)] += 1;
    }
  }

  if (groupHasLed)
    counts[static_cast<int>(SerialStudio::DashboardLED)] += 1;

  return counts;
}

void shiftRefsAfterGroupDelete(std::vector<Workspace>& workspaces,
                               const std::vector<Group>& groups,
                               int deletedGid,
                               const QMap<int, int>& deletedTypeCounts)
{
  SS_ASSERT(deletedGid >= 0, return);

  const int deletedAutoId = WorkspaceIds::PerGroupStart + deletedGid;

  workspaces.erase(
    std::remove_if(workspaces.begin(),
                   workspaces.end(),
                   [deletedAutoId](const Workspace& w) { return w.workspaceId == deletedAutoId; }),
    workspaces.end());

  for (auto& ws : workspaces) {
    if (ws.workspaceId > deletedAutoId && ws.workspaceId < WorkspaceIds::PerFolderStart)
      ws.workspaceId -= 1;

    for (auto it = ws.widgetRefs.begin(); it != ws.widgetRefs.end();) {
      const int newPos = positionalGroupId(groups, it->groupUniqueId);
      if (newPos < 0) {
        it = ws.widgetRefs.erase(it);
        continue;
      }

      if (newPos >= deletedGid) {
        const int lost    = deletedTypeCounts.value(it->widgetType, 0);
        it->relativeIndex = std::max(0, it->relativeIndex - lost);
      }

      ++it;
    }
  }
}

void shiftRefsAfterDatasetDelete(std::vector<Workspace>& workspaces,
                                 const std::vector<Group>& groups,
                                 int groupId,
                                 int groupUniqueId,
                                 const QMap<int, int>& datasetTypeCounts)
{
  SS_ASSERT(groupId >= 0, return);

  if (datasetTypeCounts.isEmpty())
    return;

  const QMap<int, int> runningAtGroup = runningCountsBeforeGroup(groups, groupId);

  for (auto& ws : workspaces) {
    ws.widgetRefs.erase(std::remove_if(ws.widgetRefs.begin(),
                                       ws.widgetRefs.end(),
                                       [&](const WidgetRef& r) {
                                         const int lost = datasetTypeCounts.value(r.widgetType, 0);
                                         if (lost == 0 || r.groupUniqueId != groupUniqueId)
                                           return false;

                                         const int base = runningAtGroup.value(r.widgetType, 0);
                                         return r.relativeIndex >= base
                                             && r.relativeIndex < base + lost;
                                       }),
                        ws.widgetRefs.end());

    for (auto& r : ws.widgetRefs) {
      const int lost = datasetTypeCounts.value(r.widgetType, 0);
      if (lost == 0)
        continue;

      const int base = runningAtGroup.value(r.widgetType, 0);
      if (r.relativeIndex < base + lost)
        continue;

      r.relativeIndex -= lost;
      SS_ASSERT(r.relativeIndex >= 0, r.relativeIndex = 0);
    }
  }
}

void shiftHiddenGroupIdsAfterGroupDelete(QSet<int>& hiddenGroupIds, int deletedGid)
{
  if (hiddenGroupIds.isEmpty())
    return;

  QSet<int> updated;
  for (const int id : std::as_const(hiddenGroupIds)) {
    if (id == deletedGid)
      continue;

    updated.insert(id > deletedGid ? id - 1 : id);
  }

  hiddenGroupIds = std::move(updated);
}

bool shiftLayoutKeysAfterGroupDelete(QJsonObject& widgetSettings, int deletedGid)
{
  if (widgetSettings.isEmpty())
    return false;

  const auto keys = widgetSettings.keys();
  bool changed    = false;

  if (widgetSettings.contains(Keys::layoutKey(deletedGid))) {
    widgetSettings.remove(Keys::layoutKey(deletedGid));
    changed = true;
  }

  const QString prefix = QStringLiteral("layout:");
  QList<QPair<int, QJsonObject>> moves;
  for (const auto& key : keys) {
    if (!key.startsWith(prefix))
      continue;

    bool ok      = false;
    const int id = key.mid(prefix.length()).toInt(&ok);
    if (!ok || id <= deletedGid)
      continue;

    moves.append({id, widgetSettings.value(key).toObject()});
  }

  std::sort(
    moves.begin(), moves.end(), [](const auto& a, const auto& b) { return a.first < b.first; });

  for (const auto& move : moves) {
    widgetSettings.remove(Keys::layoutKey(move.first));
    widgetSettings.insert(Keys::layoutKey(move.first - 1), move.second);
    changed = true;
  }

  return changed;
}

void remapHiddenGroupIdsAfterReorder(QSet<int>& hiddenGroupIds, const std::vector<int>& oldToNewGid)
{
  if (hiddenGroupIds.isEmpty())
    return;

  QSet<int> updated;
  for (const int id : std::as_const(hiddenGroupIds)) {
    if (id < 0 || static_cast<size_t>(id) >= oldToNewGid.size())
      continue;

    updated.insert(oldToNewGid[static_cast<size_t>(id)]);
  }

  hiddenGroupIds = std::move(updated);
}

void remapLayoutKeysAfterReorder(QJsonObject& widgetSettings, const std::vector<int>& oldToNewGid)
{
  if (widgetSettings.isEmpty())
    return;

  const QString prefix = QStringLiteral("layout:");
  QMap<int, QJsonObject> snapshot;

  for (const auto& key : widgetSettings.keys()) {
    if (!key.startsWith(prefix))
      continue;

    bool ok      = false;
    const int id = key.mid(prefix.length()).toInt(&ok);
    if (!ok || id < 0 || static_cast<size_t>(id) >= oldToNewGid.size())
      continue;

    snapshot.insert(id, widgetSettings.value(key).toObject());
    widgetSettings.remove(key);
  }

  for (auto it = snapshot.constBegin(); it != snapshot.constEnd(); ++it) {
    const int newId = oldToNewGid[static_cast<size_t>(it.key())];
    widgetSettings.insert(Keys::layoutKey(newId), it.value());
  }
}

void remapAutoWorkspaceIdsAfterReorder(std::vector<Workspace>& workspaces,
                                       const std::vector<int>& oldToNewGid)
{
  for (auto& ws : workspaces) {
    if (ws.workspaceId < WorkspaceIds::PerGroupStart || ws.workspaceId >= WorkspaceIds::UserStart)
      continue;

    const int oldGid = ws.workspaceId - WorkspaceIds::PerGroupStart;
    if (oldGid < 0 || static_cast<size_t>(oldGid) >= oldToNewGid.size())
      continue;

    ws.workspaceId = WorkspaceIds::PerGroupStart + oldToNewGid[static_cast<size_t>(oldGid)];
  }

  std::stable_sort(
    workspaces.begin(), workspaces.end(), [](const Workspace& a, const Workspace& b) {
      const bool aUser = a.workspaceId >= WorkspaceIds::UserStart;
      const bool bUser = b.workspaceId >= WorkspaceIds::UserStart;
      if (aUser != bUser)
        return !aUser;

      if (!aUser && !bUser)
        return a.workspaceId < b.workspaceId;

      return false;
    });
}

RefAnchors snapshotRefAnchors(const std::vector<Workspace>& workspaces,
                              const std::vector<Group>& groups)
{
  RefAnchors out;
  out.reserve(static_cast<qsizetype>(workspaces.size()));
  for (const auto& ws : workspaces) {
    std::vector<RefAnchor> bucket;
    bucket.reserve(ws.widgetRefs.size());
    for (const auto& r : ws.widgetRefs)
      bucket.push_back(anchorRef(r, groups));

    out.insert(ws.workspaceId, std::move(bucket));
  }
  return out;
}

void resolveRefAnchors(std::vector<Workspace>& workspaces,
                       const RefAnchors& anchors,
                       const std::vector<Group>& groups)
{
  for (auto& ws : workspaces) {
    const auto it = anchors.constFind(ws.workspaceId);
    if (it == anchors.constEnd())
      continue;

    resolveOneWorkspaceRefs(ws, it.value(), groups);
  }
}

static void setupUartConnection(IO::ConnectionManager& cm,
                                const QCommandLineParser& parser,
                                const CliOptions& opts)
{
  cm.setBusType(SerialStudio::BusType::UART);

  if (parser.isSet(opts.uartOpt)) {
    const QString device = parser.value(opts.uartOpt);
    cm.uart()->registerDevice(device);
  }

  if (parser.isSet(opts.baudOpt)) {
    bool ok               = false;
    const qint32 baudRate = parser.value(opts.baudOpt).toInt(&ok);
    if (!ok)
      qWarning() << "Invalid baud rate:" << parser.value(opts.baudOpt);
    else
      cm.uart()->setBaudRate(baudRate);
  }

  cm.connectDevice();
}

static void setupTcpConnection(IO::ConnectionManager& cm, const QString& tcpAddress)
{
  const QStringList parts = tcpAddress.split(':');
  if (parts.size() != 2) {
    qWarning() << "Invalid TCP address format. Expected: host:port";
    return;
  }

  bool ok            = false;
  const quint16 port = parts[1].toUInt(&ok);
  if (!ok || port == 0) {
    qWarning() << "Invalid TCP port:" << parts[1];
    return;
  }

  cm.setBusType(SerialStudio::BusType::Network);
  cm.network()->setTcpSocket();
  cm.network()->setRemoteAddress(parts[0]);
  cm.network()->setTcpPort(port);
  cm.connectDevice();
}

static void applyUdpRemote(IO::ConnectionManager& cm, const QString& udpRemote)
{
  const QStringList parts = udpRemote.split(':');
  if (parts.size() != 2) {
    qWarning() << "Invalid UDP address format. Expected: host:port";
    return;
  }

  bool ok                  = false;
  const quint16 remotePort = parts[1].toUInt(&ok);
  if (!ok || remotePort == 0) {
    qWarning() << "Invalid UDP remote port:" << parts[1];
    return;
  }

  cm.network()->setRemoteAddress(parts[0]);
  cm.network()->setUdpRemotePort(remotePort);
}

static void setupUdpConnection(IO::ConnectionManager& cm,
                               const QCommandLineParser& parser,
                               const CliOptions& opts)
{
  bool ok                 = false;
  const quint16 localPort = parser.value(opts.udpOpt).toUInt(&ok);
  if (!ok || localPort == 0) {
    qWarning() << "Invalid UDP local port:" << parser.value(opts.udpOpt);
    return;
  }

  cm.setBusType(SerialStudio::BusType::Network);
  cm.network()->setUdpSocket();
  cm.network()->setUdpLocalPort(localPort);

  if (parser.isSet(opts.udpMulticastOpt))
    cm.network()->setUdpMulticast(true);

  if (parser.isSet(opts.udpRemoteOpt))
    applyUdpRemote(cm, parser.value(opts.udpRemoteOpt));

  cm.connectDevice();
}

static void setupWebSocketConnection(IO::ConnectionManager& cm,
                                     const QCommandLineParser& parser,
                                     const CliOptions& opts,
                                     const QString& url)
{
  cm.setBusType(SerialStudio::BusType::Network);

  auto* network = cm.network();
  network->setSocketType(IO::Drivers::Network::SocketType::WebSocket);
  network->setWebSocketUrl(url);

  if (parser.isSet(opts.insecureTlsOpt))
    network->setIgnoreTlsErrors(true);

  cm.connectDevice();
}

static void setupHttpConnection(IO::ConnectionManager& cm,
                                const QCommandLineParser& parser,
                                const CliOptions& opts,
                                const QString& url)
{
  cm.setBusType(SerialStudio::BusType::Network);

  auto* network = cm.network();
  network->setSocketType(IO::Drivers::Network::SocketType::Http);
  network->setHttpUrl(url);

  if (parser.isSet(opts.httpMethodOpt)) {
    const QString method = parser.value(opts.httpMethodOpt).toUpper();
    const int index      = network->httpMethods().indexOf(method);
    if (index < 0) {
      qWarning() << "Invalid HTTP method:" << method;
      return;
    }

    network->setHttpMethodIndex(index);
  }

  if (parser.isSet(opts.httpIntervalOpt))
    network->setHttpInterval(parser.value(opts.httpIntervalOpt).toInt());

  if (parser.isSet(opts.httpHeaderOpt))
    network->setHttpHeaders(parser.values(opts.httpHeaderOpt).join(QChar('\n')));

  if (parser.isSet(opts.insecureTlsOpt))
    network->setIgnoreTlsErrors(true);

  cm.connectDevice();
}

void apply(IO::ConnectionManager& cm, const QCommandLineParser& parser, const CliOptions& opts)
{
  if (parser.isSet(opts.uartOpt) || parser.isSet(opts.baudOpt)) {
    setupUartConnection(cm, parser, opts);
    return;
  }

  if (parser.isSet(opts.tcpOpt)) {
    setupTcpConnection(cm, parser.value(opts.tcpOpt));
    return;
  }

  if (parser.isSet(opts.udpOpt)) {
    setupUdpConnection(cm, parser, opts);
    return;
  }

  if (parser.isSet(opts.wsOpt)) {
    setupWebSocketConnection(cm, parser, opts, parser.value(opts.wsOpt));
    return;
  }

  if (parser.isSet(opts.httpOpt)) {
    setupHttpConnection(cm, parser, opts, parser.value(opts.httpOpt));
    return;
  }

  static_cast<void>(CliIndustrialConfig::apply(cm, parser, opts));
}

static void applyModbusRegister(IO::Drivers::Modbus* modbus, const QString& spec)
{
  quint8 registerType = 0;
  quint16 start       = 0;
  quint16 count       = 0;
  if (!CliSpecParsers::parseModbusRegisterSpec(spec, registerType, start, count))
    return;

  modbus->addRegisterGroup(registerType, start, count);
}

static void applyModbusParity(IO::Drivers::Modbus* modbus, const QString& parity)
{
  const int index = CliSpecParsers::modbusParityIndex(parity);
  if (index < 0) {
    qWarning() << "Invalid ModBus parity (none/even/odd/space/mark):" << parity;
    modbus->setParityIndex(0);
    return;
  }

  modbus->setParityIndex(static_cast<quint8>(index));
}

static void applyModbusDataBits(IO::Drivers::Modbus* modbus, const QString& dataBits)
{
  const int index = CliSpecParsers::modbusDataBitsIndex(dataBits);
  if (index < 0) {
    qWarning() << "Invalid ModBus data bits (5/6/7/8):" << dataBits;
    modbus->setDataBitsIndex(3);
    return;
  }

  modbus->setDataBitsIndex(static_cast<quint8>(index));
}

static void applyModbusStopBits(IO::Drivers::Modbus* modbus, const QString& stopBits)
{
  const int index = CliSpecParsers::modbusStopBitsIndex(stopBits);
  if (index < 0) {
    qWarning() << "Invalid ModBus stop bits (1/1.5/2):" << stopBits;
    modbus->setStopBitsIndex(0);
    return;
  }

  modbus->setStopBitsIndex(static_cast<quint8>(index));
}

static void applyModbusSlave(IO::Drivers::Modbus* modbus,
                             const QCommandLineParser& parser,
                             const QCommandLineOption& opt)
{
  if (!parser.isSet(opt))
    return;

  bool ok                      = false;
  const unsigned int slave_val = parser.value(opt).toUInt(&ok);
  if (!ok || slave_val < 1 || slave_val > 247) {
    qWarning() << "Invalid ModBus slave address (1-247):" << parser.value(opt);
    return;
  }

  modbus->setSlaveAddress(static_cast<quint8>(slave_val));
}

static void applyModbusPoll(IO::Drivers::Modbus* modbus,
                            const QCommandLineParser& parser,
                            const QCommandLineOption& opt)
{
  if (!parser.isSet(opt))
    return;

  bool ok                = false;
  const quint16 interval = parser.value(opt).toUInt(&ok);
  if (!ok || interval < 50 || interval > 60000) {
    qWarning() << "Invalid ModBus poll interval (50-60000 ms):" << parser.value(opt);
    return;
  }

  modbus->setPollInterval(interval);
}

static void applyModbusBaud(IO::Drivers::Modbus* modbus,
                            const QCommandLineParser& parser,
                            const QCommandLineOption& opt)
{
  if (!parser.isSet(opt))
    return;

  bool ok               = false;
  const qint32 baudRate = parser.value(opt).toInt(&ok);
  if (!ok) {
    qWarning() << "Invalid ModBus baud rate:" << parser.value(opt);
    return;
  }

  modbus->setBaudRate(baudRate);
}

static void applyModbusRegisters(IO::Drivers::Modbus* modbus,
                                 const QCommandLineParser& parser,
                                 const QCommandLineOption& opt)
{
  modbus->clearRegisterGroups();
  if (!parser.isSet(opt)) {
    qWarning() << "No register groups specified. Use --modbus-register to add registers.";
    return;
  }

  const QStringList registerSpecs = parser.values(opt);
  for (const QString& spec : std::as_const(registerSpecs))
    applyModbusRegister(modbus, spec);
}

static void setupModbusRtuConnection(IO::ConnectionManager& cm,
                                     const QCommandLineParser& parser,
                                     const CliOptions& opts)
{
  const QString portPath = parser.value(opts.modbusRtuOpt);
  cm.setBusType(SerialStudio::BusType::ModBus);

  auto* modbus = cm.modbus();
  modbus->setProtocolIndex(0);

  const QStringList ports = modbus->serialPortList();
  const int portIndex     = ports.indexOf(portPath);
  if (portIndex < 0) {
    qWarning() << "ModBus serial port not found:" << portPath;
    qWarning() << "Available ports:" << ports.join(", ");
    return;
  }

  modbus->setSerialPortIndex(portIndex);
  applyModbusSlave(modbus, parser, opts.modbusSlaveOpt);
  applyModbusPoll(modbus, parser, opts.modbusPollOpt);
  applyModbusBaud(modbus, parser, opts.modbusBaudOpt);

  if (parser.isSet(opts.modbusParityOpt))
    applyModbusParity(modbus, parser.value(opts.modbusParityOpt).toLower());

  if (parser.isSet(opts.modbusDataBitsOpt))
    applyModbusDataBits(modbus, parser.value(opts.modbusDataBitsOpt));

  if (parser.isSet(opts.modbusStopBitsOpt))
    applyModbusStopBits(modbus, parser.value(opts.modbusStopBitsOpt));

  applyModbusRegisters(modbus, parser, opts.modbusRegisterOpt);
  cm.connectDevice();
}

static void setupModbusTcpConnection(IO::ConnectionManager& cm,
                                     const QCommandLineParser& parser,
                                     const CliOptions& opts)
{
  QString host;
  quint16 port = 502;
  if (!CliSpecParsers::parseModbusTcpAddress(parser.value(opts.modbusTcpOpt), host, port)) {
    qWarning() << "Invalid ModBus TCP address format. Expected: host[:port]";
    return;
  }

  cm.setBusType(SerialStudio::BusType::ModBus);

  auto* modbus = cm.modbus();
  modbus->setProtocolIndex(1);
  modbus->setHost(host);
  modbus->setPort(port);

  applyModbusSlave(modbus, parser, opts.modbusSlaveOpt);
  applyModbusPoll(modbus, parser, opts.modbusPollOpt);
  applyModbusRegisters(modbus, parser, opts.modbusRegisterOpt);
  cm.connectDevice();
}

[[nodiscard]] static QJsonObject parseOpcUaTagSpec(const QString& spec)
{
  using IO::Drivers::OpcUaWire::Type;
  using IO::Drivers::OpcUaWire::typeFromCode;

  QString id   = spec;
  QString type = QStringLiteral("f64");
  QString name;
  QString unit;
  int arrayLen = 1;

  auto body = spec;
  for (int guard = 0; guard < 4; ++guard) {
    const auto tail = body.section(QLatin1Char(':'), -1);
    if (tail.startsWith(QLatin1String("n=")) && tail.mid(2).toInt() > 0) {
      arrayLen = tail.mid(2).toInt();
      body     = body.section(QLatin1Char(':'), 0, -2);
      continue;
    }

    if (tail.startsWith(QLatin1String("unit="))) {
      unit = tail.mid(5);
      body = body.section(QLatin1Char(':'), 0, -2);
      continue;
    }

    break;
  }

  id               = body;
  const auto parts = body.split(QLatin1Char(':'));
  if (parts.size() >= 3 && typeFromCode(parts.at(parts.size() - 2)) != Type::Invalid) {
    name = parts.last();
    type = parts.at(parts.size() - 2);
    id   = parts.mid(0, parts.size() - 2).join(QLatin1Char(':'));
  } else if (parts.size() >= 2 && typeFromCode(parts.last()) != Type::Invalid) {
    type = parts.last();
    id   = parts.mid(0, parts.size() - 1).join(QLatin1Char(':'));
  } else if (parts.size() >= 2) {
    return {};
  }

  if (id.isEmpty())
    return {};

  QJsonObject tag;
  tag[QStringLiteral("id")]   = id;
  tag[QStringLiteral("t")]    = type;
  tag[QStringLiteral("n")]    = arrayLen;
  tag[QStringLiteral("unit")] = unit;
  tag[QStringLiteral("name")] = name.isEmpty() ? id : name;
  return tag;
}

static void setupOpcUaConnection(IO::ConnectionManager& cm,
                                 const QCommandLineParser& parser,
                                 const CliOptions& opts)
{
  const QString url = parser.value(opts.opcuaOpt);
  if (!url.startsWith(QLatin1String("opc.tcp://"))) {
    qWarning() << "Invalid OPC UA endpoint. Expected: opc.tcp://host[:port][/path]";
    return;
  }

  auto* opcua = cm.opcUa();
  cm.setBusType(SerialStudio::BusType::OpcUa);
  opcua->setEndpointUrl(url);

  if (parser.isSet(opts.opcuaUserOpt)) {
    opcua->setAuthMode(1);
    opcua->setUsername(parser.value(opts.opcuaUserOpt));
    if (parser.isSet(opts.opcuaPassOpt))
      opcua->setPassword(parser.value(opts.opcuaPassOpt));
  } else {
    opcua->setAuthMode(0);
  }

  if (parser.isSet(opts.opcuaIntervalOpt)) {
    bool ok            = false;
    const int interval = parser.value(opts.opcuaIntervalOpt).toInt(&ok);
    if (ok && interval >= 10 && interval <= 60000)
      opcua->setPublishingInterval(interval);
    else
      qWarning() << "Invalid OPC UA interval (10-60000 ms):" << parser.value(opts.opcuaIntervalOpt);
  }

  QJsonArray tags;
  const auto specs = parser.values(opts.opcuaTagOpt);
  for (const auto& spec : specs) {
    const auto tag = parseOpcUaTagSpec(spec);
    if (tag.isEmpty())
      qWarning() << "Invalid OPC UA tag spec (nodeId[:type[:name]], known type code):" << spec;
    else
      tags.append(tag);
  }

  if (tags.isEmpty()) {
    qWarning() << "No OPC UA tags given (--opcua-tag); nothing to subscribe to";
    return;
  }

  opcua->setTags(tags);

  if (!parser.isSet(opts.projectOpt) && !opcua->loadGeneratedProject())
    qWarning() << "Could not generate a project for the OPC UA tags";

  cm.connectDevice();
}

static void setupCanbusConnection(IO::ConnectionManager& cm,
                                  const QCommandLineParser& parser,
                                  const CliOptions& opts)
{
  const QStringList parts = parser.value(opts.canbusOpt).split(':');
  if (parts.size() != 2) {
    qWarning() << "Invalid CAN bus format. Expected: plugin:interface";
    return;
  }

  const QString plugin        = parts[0].toLower();
  const QString interfaceName = parts[1];

  cm.setBusType(SerialStudio::BusType::CanBus);
  auto* canBus = cm.canBus();

  const QStringList availablePlugins = canBus->pluginList();
  const int pluginIndex              = availablePlugins.indexOf(plugin);
  if (pluginIndex < 0) {
    qWarning() << "CAN plugin" << plugin << "not found";
    qWarning() << "Available plugins:" << availablePlugins.join(", ");
    return;
  }

  canBus->setPluginIndex(pluginIndex);
  const QStringList availableInterfaces = canBus->interfaceList();
  const int interfaceIndex              = availableInterfaces.indexOf(interfaceName);

  if (interfaceIndex < 0) {
    qWarning() << "CAN interface" << interfaceName << "not found for plugin" << plugin;
    qWarning() << "Available interfaces:" << availableInterfaces.join(", ");
    return;
  }

  canBus->setInterfaceIndex(interfaceIndex);

  if (parser.isSet(opts.canbusBitrateOpt)) {
    bool ok               = false;
    const quint32 bitrate = parser.value(opts.canbusBitrateOpt).toUInt(&ok);
    if (ok && bitrate > 0)
      canBus->setBitrate(bitrate);
    else
      qWarning() << "Invalid CAN bus bitrate:" << parser.value(opts.canbusBitrateOpt);
  }

  if (parser.isSet(opts.canbusFdOpt))
    canBus->setCanFD(true);

  cm.connectDevice();
}

static void applyPollInterval(IO::HAL_Driver* driver, const QString& value)
{
  bool ok            = false;
  const int interval = value.toInt(&ok);
  if (!ok || interval < 50 || interval > 60000) {
    qWarning() << "Invalid poll interval (50-60000 ms):" << value;
    return;
  }

  driver->setDriverProperty(QStringLiteral("pollInterval"), interval);
}

[[nodiscard]] static QString splitS7Spec(const IO::Drivers::S7& driver,
                                         const QString& spec,
                                         QString& name)
{
  name.clear();

  const int fields = static_cast<int>(spec.count(QLatin1Char(':'))) + 1;
  for (int last = fields - 1; last >= 0; --last) {
    const auto candidate = spec.section(QLatin1Char(':'), 0, last);
    if (!driver.validateAddress(candidate).isEmpty())
      continue;

    name = last + 1 < fields ? spec.section(QLatin1Char(':'), last + 1) : QString();
    return candidate;
  }

  return {};
}

static void setupS7Connection(IO::ConnectionManager& cm,
                              const QCommandLineParser& parser,
                              const CliOptions& opts)
{
  auto* s7 = cm.s7();
  cm.setBusType(SerialStudio::BusType::S7);
  s7->setHost(parser.value(opts.s7Opt));

  int rack = 0;
  if (CliSpecParsers::parseIntOption(parser, opts.s7RackOpt, 0, 7, QStringLiteral("S7 rack"), rack))
    s7->setRack(rack);

  int slot = 0;
  if (CliSpecParsers::parseIntOption(
        parser, opts.s7SlotOpt, 0, 31, QStringLiteral("S7 slot"), slot))
    s7->setSlot(slot);

  if (parser.isSet(opts.s7IntervalOpt))
    applyPollInterval(s7, parser.value(opts.s7IntervalOpt));

  QList<S7VarSpec> variables;
  const auto specs = parser.values(opts.s7VariableOpt);
  for (const auto& spec : specs) {
    QString name;
    const auto address = splitS7Spec(*s7, spec, name);
    if (address.isEmpty())
      qWarning() << "Invalid S7 variable spec:" << spec;
    else
      variables.append({name, address});
  }

  if (variables.isEmpty()) {
    qWarning() << "No S7 variables given (--s7-variable); nothing to poll";
    return;
  }

  s7->clearVariables();
  for (const auto& variable : variables)
    s7->addVariable(variable.name, variable.address);

  if (!parser.isSet(opts.projectOpt) && !s7->loadGeneratedProject())
    qWarning() << "Could not generate a project for the S7 variables";

  cm.connectDevice();
}

[[nodiscard]] static QList<EipTagSpec> parseEipTagSpecs(const QStringList& specs)
{
  QList<EipTagSpec> tags;
  for (const auto& spec : specs) {
    const auto parts   = spec.split(QLatin1Char(':'));
    const auto address = parts.value(0);
    if (address.isEmpty()) {
      qWarning() << "Invalid EtherNet/IP tag spec (empty tag name):" << spec;
      continue;
    }

    int element = -1;
    if (parts.size() > 2) {
      bool ok = false;
      element = parts.at(2).toInt(&ok);
      if (!ok || element < 0) {
        qWarning() << "Invalid EtherNet/IP tag element (>= 0):" << spec;
        continue;
      }
    }

    tags.append({element, address, parts.size() > 1 ? parts.at(1) : QStringLiteral("f32")});
  }

  return tags;
}

static void setupEthernetIpConnection(IO::ConnectionManager& cm,
                                      const QCommandLineParser& parser,
                                      const CliOptions& opts)
{
  auto* eip = cm.ethernetIp();
  cm.setBusType(SerialStudio::BusType::EthernetIp);
  eip->setHost(parser.value(opts.eipOpt));

  if (parser.isSet(opts.eipPathOpt))
    eip->setCipPath(parser.value(opts.eipPathOpt));

  if (parser.isSet(opts.eipPlcOpt)) {
    const auto families = eip->plcTypeList();
    const int index = static_cast<int>(families.indexOf(parser.value(opts.eipPlcOpt).toLower()));
    if (index < 0)
      qWarning() << "Unknown controller family:" << parser.value(opts.eipPlcOpt);
    else
      eip->setPlcTypeIndex(index);
  }

  if (parser.isSet(opts.eipIntervalOpt))
    applyPollInterval(eip, parser.value(opts.eipIntervalOpt));

  const QList<EipTagSpec> tags = parseEipTagSpecs(parser.values(opts.eipTagOpt));
  if (tags.isEmpty()) {
    qWarning() << "No EtherNet/IP tags given (--ethernetip-tag); nothing to poll";
    return;
  }

  eip->clearTags();
  for (const auto& tag : tags)
    eip->addTag(QString(), tag.tag, tag.type, tag.element);

  if (!parser.isSet(opts.projectOpt) && !eip->loadGeneratedProject())
    qWarning() << "Could not generate a project for the EtherNet/IP tags";

  cm.connectDevice();
}

static void applyIec104Timing(IO::Drivers::Iec104* iec104,
                              const QCommandLineParser& parser,
                              const CliOptions& opts)
{
  int windowK      = 0;
  const bool haveK = CliSpecParsers::parseIntOption(
    parser, opts.iec104KOpt, 1, 32767, QStringLiteral("IEC 60870-5-104 send window k"), windowK);
  if (haveK)
    iec104->setWindowK(windowK);

  int windowW      = 0;
  const bool haveW = CliSpecParsers::parseIntOption(
    parser, opts.iec104WOpt, 1, 32767, QStringLiteral("IEC 60870-5-104 ack window w"), windowW);
  if (haveW) {
    if (haveK && windowW > windowK)
      qWarning() << "IEC 60870-5-104 ack window w exceeds send window k; the station clamps w to k";

    iec104->setWindowW(windowW);
  }

  int t1            = 0;
  const bool haveT1 = CliSpecParsers::parseIntOption(
    parser, opts.iec104T1Opt, 1000, 255000, QStringLiteral("IEC 60870-5-104 t1 timeout (ms)"), t1);
  if (haveT1)
    iec104->setTimeoutT1(t1);

  int t2            = 0;
  const bool haveT2 = CliSpecParsers::parseIntOption(
    parser, opts.iec104T2Opt, 1000, 255000, QStringLiteral("IEC 60870-5-104 t2 timeout (ms)"), t2);
  if (haveT2) {
    if (haveT1 && t2 > t1)
      qWarning() << "IEC 60870-5-104 t2 timeout exceeds t1; the station clamps t2 to t1";

    iec104->setTimeoutT2(t2);
  }

  int t3 = 0;
  if (CliSpecParsers::parseIntOption(parser,
                                     opts.iec104T3Opt,
                                     1000,
                                     255000,
                                     QStringLiteral("IEC 60870-5-104 t3 timeout (ms)"),
                                     t3))
    iec104->setTimeoutT3(t3);
}

static void setupIec104Connection(IO::ConnectionManager& cm,
                                  const QCommandLineParser& parser,
                                  const CliOptions& opts)
{
  auto* iec104 = cm.iec104();
  cm.setBusType(SerialStudio::BusType::Iec104);
  iec104->setHost(parser.value(opts.iec104Opt));

  int value = 0;
  if (CliSpecParsers::parseIntOption(
        parser, opts.iec104PortOpt, 1, 65535, QStringLiteral("IEC 60870-5-104 port"), value))
    iec104->setPort(value);

  if (CliSpecParsers::parseIntOption(parser,
                                     opts.iec104CaOpt,
                                     0,
                                     65535,
                                     QStringLiteral("IEC 60870-5-104 common address"),
                                     value))
    iec104->setCommonAddress(value);

  applyIec104Timing(iec104, parser, opts);

  if (!parser.isSet(opts.projectOpt) && !iec104->loadGeneratedProject())
    qWarning() << "No IEC 60870-5-104 points are known yet; connect once so the station "
                  "interrogation can discover them, then re-run to generate a project";

  cm.connectDevice();
}

bool apply(IO::ConnectionManager& cm, const QCommandLineParser& parser, const CliOptions& opts)
{
  if (parser.isSet(opts.modbusRtuOpt)) {
    setupModbusRtuConnection(cm, parser, opts);
    return true;
  }

  if (parser.isSet(opts.modbusTcpOpt)) {
    setupModbusTcpConnection(cm, parser, opts);
    return true;
  }

  if (parser.isSet(opts.canbusOpt)) {
    setupCanbusConnection(cm, parser, opts);
    return true;
  }

  if (parser.isSet(opts.opcuaOpt)) {
    setupOpcUaConnection(cm, parser, opts);
    return true;
  }

  if (parser.isSet(opts.s7Opt)) {
    setupS7Connection(cm, parser, opts);
    return true;
  }

  if (parser.isSet(opts.eipOpt)) {
    setupEthernetIpConnection(cm, parser, opts);
    return true;
  }

  if (parser.isSet(opts.iec104Opt)) {
    setupIec104Connection(cm, parser, opts);
    return true;
  }

  return false;
}

bool parseIntOption(const QCommandLineParser& parser,
                    const QCommandLineOption& opt,
                    const int lo,
                    const int hi,
                    const QString& label,
                    int& out)
{
  SS_ASSERT(lo <= hi, return false);
  if (!parser.isSet(opt))
    return false;

  bool ok       = false;
  const int val = parser.value(opt).toInt(&ok);
  if (!ok || val < lo || val > hi) {
    qWarning().noquote()
      << QStringLiteral("Invalid %1 (%2-%3):").arg(label, QString::number(lo), QString::number(hi))
      << parser.value(opt);
    return false;
  }

  out = val;
  return true;
}

bool parseModbusTcpAddress(const QString& tcpAddress, QString& host, quint16& port)
{
  const QStringList parts = tcpAddress.split(':');
  if (parts.size() != 1 && parts.size() != 2)
    return false;

  host = parts[0];
  port = 502;
  if (parts.size() != 2)
    return true;

  bool ok         = false;
  const quint16 p = parts[1].toUInt(&ok);
  if (!ok || p == 0) {
    qWarning() << "Invalid ModBus TCP port:" << parts[1];
    return true;
  }

  port = p;
  return true;
}

bool parseModbusRegisterSpec(const QString& spec, quint8& type, quint16& start, quint16& count)
{
  const QStringList parts = spec.split(':');
  if (parts.size() != 3) {
    qWarning() << "Invalid register format. Expected: type:start:count";
    return false;
  }

  static const QHash<QString, quint8> kRegisterTypes = {
    { QStringLiteral("holding"), 0},
    {   QStringLiteral("input"), 1},
    {   QStringLiteral("coils"), 2},
    {QStringLiteral("discrete"), 3},
  };

  const QString typeStr = parts[0].toLower();
  const auto it         = kRegisterTypes.constFind(typeStr);
  if (it == kRegisterTypes.cend()) {
    qWarning() << "Invalid register type (holding/input/coils/discrete):" << typeStr;
    return false;
  }

  bool startOk             = false;
  bool countOk             = false;
  const quint16 startValue = parts[1].toUInt(&startOk);
  const quint16 countValue = parts[2].toUInt(&countOk);
  if (!startOk || !countOk || countValue < 1 || countValue > 125) {
    qWarning() << "Invalid register specification (start:0-65535, count:1-125):" << spec;
    return false;
  }

  type  = it.value();
  start = startValue;
  count = countValue;
  return true;
}

int modbusParityIndex(const QString& parity)
{
  static const QHash<QString, quint8> kParity = {
    { QStringLiteral("none"), 0},
    { QStringLiteral("even"), 1},
    {  QStringLiteral("odd"), 2},
    {QStringLiteral("space"), 3},
    { QStringLiteral("mark"), 4},
  };

  const auto it = kParity.constFind(parity);
  return it == kParity.cend() ? -1 : static_cast<int>(it.value());
}

int modbusDataBitsIndex(const QString& dataBits)
{
  static const QHash<QString, quint8> kDataBits = {
    {QStringLiteral("5"), 0},
    {QStringLiteral("6"), 1},
    {QStringLiteral("7"), 2},
    {QStringLiteral("8"), 3},
  };

  const auto it = kDataBits.constFind(dataBits);
  return it == kDataBits.cend() ? -1 : static_cast<int>(it.value());
}

int modbusStopBitsIndex(const QString& stopBits)
{
  static const QHash<QString, quint8> kStopBits = {
    {  QStringLiteral("1"), 0},
    {QStringLiteral("1.5"), 1},
    {  QStringLiteral("2"), 2},
  };

  const auto it = kStopBits.constFind(stopBits);
  return it == kStopBits.cend() ? -1 : static_cast<int>(it.value());
}

