QList<std::pair<int, int>> UI::ReplaySeekEngine::seekSeries() const
{
  QList<std::pair<int, int>> out;
  QSet<qint64> seen;

  auto add = [&](int sourceId, int uniqueId) {
    const qint64 key = seekKey(sourceId, uniqueId);
    if (seen.contains(key))
      return;

    seen.insert(key);
    out.append({sourceId, uniqueId});
  };

  const int plots = plotCount();
  for (int i = 0; i < plots; ++i) {
    const auto& ds = plotDataset(i);
    add(ds.sourceId, ds.uniqueId);

    if (ds.xAxisId == DataModel::kXAxisTime)
      continue;

    const auto xIt = m_datasets.constFind(ds.xAxisId);
    if (xIt != m_datasets.constEnd())
      add(xIt.value().sourceId, ds.xAxisId);
  }

  const int multis = multiplotCount();
  for (int i = 0; i < multis; ++i) {
    const auto& group = multiplotGroup(i);
    for (const auto& ds : group.datasets)
      add(group.sourceId, ds.uniqueId);
  }

  return out;
}

void UI::ReplaySeekEngine::fillSeekPlotSingle(int index,
                                              const QVector<double>& timesSec,
                                              const QHash<qint64, QVector<double>>& series,
                                              double timeOffset,
                                              QSet<const DSP::AxisData*>& filled)
{
  SS_ASSERT(index >= 0, return);
  SS_ASSERT(index < plotCount(), return);

  const auto& ds     = plotDataset(index);
  const auto& values = series.value(seekKey(ds.sourceId, ds.uniqueId));
  const int count    = qMin(timesSec.size(), values.size());

  if (ds.xAxisId == DataModel::kXAxisTime) {
    const auto rIt = m_plotTimeRings.find(index);
    if (rIt == m_plotTimeRings.end()) [[unlikely]]
      return;

    rIt.value().clear();
    for (int k = 0; k < count; ++k)
      rIt.value().appendDecimated(timesSec[k] + timeOffset, values[k]);

    return;
  }

  const auto yIt = m_yAxisData.find(ds.uniqueId);
  if (yIt != m_yAxisData.end() && !filled.contains(&yIt.value())) {
    filled.insert(&yIt.value());
    yIt.value().clear();
    for (int k = 0; k < count; ++k)
      yIt.value().push(values[k]);
  }

  const auto xDsIt = m_datasets.constFind(ds.xAxisId);
  if (xDsIt == m_datasets.constEnd())
    return;

  const auto xIt = m_xAxisData.find(ds.xAxisId);
  if (xIt == m_xAxisData.end() || filled.contains(&xIt.value()))
    return;

  const auto& xValues = series.value(seekKey(xDsIt.value().sourceId, ds.xAxisId));
  const int xCount    = qMin(timesSec.size(), xValues.size());
  filled.insert(&xIt.value());
  xIt.value().clear();
  for (int k = 0; k < xCount; ++k)
    xIt.value().push(xValues[k]);
}

void UI::ReplaySeekEngine::fillSeekPlotMulti(int index,
                                             const QVector<double>& timesSec,
                                             const QHash<qint64, QVector<double>>& series,
                                             double timeOffset)
{
  SS_ASSERT(index >= 0, return);
  SS_ASSERT(index < multiplotCount(), return);

  const auto& group = multiplotGroup(index);

  const auto rIt = m_multiplotTimeRings.find(index);
  if (rIt != m_multiplotTimeRings.end()) {
    auto& rings        = rIt.value();
    const size_t count = std::min(group.datasets.size(), rings.size());
    for (size_t j = 0; j < count; ++j) {
      const auto& ds     = group.datasets[j];
      const auto& values = series.value(seekKey(group.sourceId, ds.uniqueId));
      const int n        = qMin(timesSec.size(), values.size());
      rings[j].clear();
      for (int k = 0; k < n; ++k)
        rings[j].appendDecimated(timesSec[k] + timeOffset, values[k]);
    }

    return;
  }

  if (index >= m_multiplotValues.size()) [[unlikely]]
    return;

  auto& multiSeries  = m_multiplotValues[index];
  const size_t count = std::min(group.datasets.size(), multiSeries.y.size());
  for (size_t j = 0; j < count; ++j) {
    const auto& ds     = group.datasets[j];
    const auto& values = series.value(seekKey(group.sourceId, ds.uniqueId));
    const int n        = qMin(timesSec.size(), values.size());
    multiSeries.y[j].clear();
    for (int k = 0; k < n; ++k)
      multiSeries.y[j].push(values[k]);
  }
}

bool UI::ReplaySeekEngine::bulkLoadPlotWindow(const QVector<double>& timesSec,
                                              const QHash<qint64, QVector<double>>& series)
{
  // code-verify off
  // Debug-only ordering check: is_sorted is O(n) over the whole seek window, so a release
  // evaluation would walk every sample on every scrub.
  Q_ASSERT(std::is_sorted(timesSec.cbegin(), timesSec.cend()));
  // code-verify on

  if (timesSec.isEmpty()) [[unlikely]]
    return false;

  const double timeOffset = -timesSec.last();

  QSet<const DSP::AxisData*> filled;
  const int plots = plotCount();
  for (int i = 0; i < plots; ++i)
    fillSeekPlotSingle(i, timesSec, series, timeOffset, filled);

  const int multis = multiplotCount();
  for (int i = 0; i < multis; ++i)
    fillSeekPlotMulti(i, timesSec, series, timeOffset);

  return true;
}

QHash<qint64, DSP::EnvelopeRing> UI::ReplaySeekEngine::snapshotPlotTimeRings() const
{
  QHash<qint64, DSP::EnvelopeRing> out;
  const int n = plotCount();
  for (int i = 0; i < n; ++i) {
    const auto it = m_plotTimeRings.constFind(i);
    if (it == m_plotTimeRings.cend())
      continue;

    const auto& d = plotDataset(i);
    out.insert(seekKey(d.sourceId, d.uniqueId), it.value());
  }

  return out;
}

QHash<qint64, std::vector<DSP::EnvelopeRing>> UI::ReplaySeekEngine::snapshotMultiplotTimeRings()
  const
{
  QHash<qint64, std::vector<DSP::EnvelopeRing>> out;
  const int n = multiplotCount();
  for (int i = 0; i < n; ++i) {
    const auto it = m_multiplotTimeRings.constFind(i);
    if (it == m_multiplotTimeRings.cend())
      continue;

    const auto& g = multiplotGroup(i);
    out.insert(seekKey(g.sourceId, g.uniqueId), it.value());
  }

  return out;
}

static void replayTimeRing(const DSP::EnvelopeRing& saved, DSP::EnvelopeRing& target)
{
  const std::size_t n = std::min(saved.level0.time.size(), saved.level0.value.size());
  for (std::size_t k = 0; k < n; ++k)
    target.appendDecimated(saved.level0.time[k], saved.level0.value[k]);
}

void UI::ReplaySeekEngine::restorePlotTimeRings(QHash<qint64, DSP::EnvelopeRing>& snapshot)
{
  if (snapshot.isEmpty())
    return;

  const int n = plotCount();
  for (int i = 0; i < n; ++i) {
    auto ringIt = m_plotTimeRings.find(i);
    if (ringIt == m_plotTimeRings.end())
      continue;

    const auto& d = plotDataset(i);
    auto savedIt  = snapshot.find(seekKey(d.sourceId, d.uniqueId));
    if (savedIt == snapshot.end())
      continue;

    auto& live = ringIt.value();
    auto& kept = savedIt.value();
    if (kept.level0.time.raw() == nullptr)
      continue;

    if (live.level0.time.capacity() == kept.level0.time.capacity()
        && qFuzzyCompare(live.level0.interval, kept.level0.interval))
      live = std::move(kept);
    else
      replayTimeRing(kept, live);

    snapshot.erase(savedIt);
  }
}

void UI::ReplaySeekEngine::restoreMultiplotTimeRings(
  QHash<qint64, std::vector<DSP::EnvelopeRing>>& snapshot)
{
  if (snapshot.isEmpty())
    return;

  const int n = multiplotCount();
  for (int i = 0; i < n; ++i) {
    auto ringIt = m_multiplotTimeRings.find(i);
    if (ringIt == m_multiplotTimeRings.end())
      continue;

    const auto& g = multiplotGroup(i);
    auto savedIt  = snapshot.find(seekKey(g.sourceId, g.uniqueId));
    if (savedIt == snapshot.end())
      continue;

    auto& live = ringIt.value();
    auto& kept = savedIt.value();

    const std::size_t count = std::min(live.size(), kept.size());
    for (std::size_t j = 0; j < count; ++j) {
      if (kept[j].level0.time.raw() == nullptr)
        continue;

      if (live[j].level0.time.capacity() == kept[j].level0.time.capacity()
          && qFuzzyCompare(live[j].level0.interval, kept[j].level0.interval))
        live[j] = std::move(kept[j]);
      else
        replayTimeRing(kept[j], live[j]);
    }

    snapshot.erase(savedIt);
  }
}

QVariantList UI::TaskbarWorkspaces::model() const
{
  QVariantList model;
  const auto& workspaces = m_projectModel.activeWorkspaces();
  for (const auto& ws : workspaces) {
    QVariantMap entry;
    const bool fixedIcon = ws.icon.isEmpty();
    const auto icon =
      fixedIcon ? m_iconRegistry.icon(QStringLiteral("widgets"), QStringLiteral("workspace"), 16)
                : Misc::IconEngine::resolveActionIconSource(ws.icon);
    entry[QStringLiteral("id")]        = ws.workspaceId;
    entry[QStringLiteral("text")]      = ws.title;
    entry[QStringLiteral("separator")] = false;
    entry[QStringLiteral("icon")]      = icon;
    entry[QStringLiteral("iconId")] = fixedIcon ? QStringLiteral("widgets/workspace") : QString();
    model.append(entry);
  }

  return model;
}

[[nodiscard]] static QVariantList buildWorkspaceTreeLevel(
  int parentFolderId,
  Misc::IconRegistry& registry,
  const std::vector<DataModel::Workspace>& workspaces,
  const std::vector<DataModel::WorkspaceFolder>& folders)
{
  QVariantList level;

  for (const auto& f : folders) {
    if (f.parentFolderId != parentFolderId)
      continue;

    const auto children = buildWorkspaceTreeLevel(f.folderId, registry, workspaces, folders);
    if (children.isEmpty())
      continue;

    QVariantMap node;
    node[QStringLiteral("isFolder")] = true;
    node[QStringLiteral("id")]       = f.folderId;
    node[QStringLiteral("text")]     = f.title;
    node[QStringLiteral("icon")] =
      registry.icon(QStringLiteral("widgets"), QStringLiteral("folder"), 16);
    node[QStringLiteral("iconId")]   = QStringLiteral("widgets/folder");
    node[QStringLiteral("children")] = children;
    level.append(node);
  }

  for (const auto& ws : workspaces) {
    if (ws.parentFolderId != parentFolderId || ws.widgetRefs.empty())
      continue;

    QVariantMap node;
    const bool fixedIcon             = ws.icon.isEmpty();
    const auto icon                  = fixedIcon
                                       ? registry.icon(QStringLiteral("widgets"), QStringLiteral("workspace"), 16)
                                       : Misc::IconEngine::resolveActionIconSource(ws.icon);
    node[QStringLiteral("isFolder")] = false;
    node[QStringLiteral("id")]       = ws.workspaceId;
    node[QStringLiteral("text")]     = ws.title;
    node[QStringLiteral("icon")]     = icon;
    node[QStringLiteral("iconId")]   = fixedIcon ? QStringLiteral("widgets/workspace") : QString();
    node[QStringLiteral("children")] = QVariantList();
    level.append(node);
  }

  return level;
}

QVariantList UI::TaskbarWorkspaces::tree() const
{
  const auto& workspaces = m_projectModel.activeWorkspaces();

  const std::vector<DataModel::WorkspaceFolder> noFolders;
  const bool projectMode = m_appState.operationMode() == SerialStudio::ProjectFile;
  const auto& folders    = projectMode ? m_projectModel.editorWorkspaceFolders() : noFolders;
  return buildWorkspaceTreeLevel(-1, m_iconRegistry, workspaces, folders);
}

bool UI::TaskbarWorkspaces::contains(int workspaceId) const
{
  const auto list  = model();
  const auto match = [workspaceId](const QVariant& v) {
    return v.toMap().value(QStringLiteral("id")).toInt() == workspaceId;
  };

  return workspaceId >= 0 && std::any_of(list.begin(), list.end(), match);
}

int UI::TaskbarWorkspaces::indexForGroupId(int groupId) const
{
  const auto list = model();
  int index       = 0;
  for (auto it = list.begin(); it != list.end(); ++it) {
    const auto map = it->toMap();
    if (!map.contains(QStringLiteral("id")))
      continue;

    if (map.value(QStringLiteral("id")).toInt() == groupId)
      return index;

    ++index;
  }

  return -1;
}

QPair<int, int> UI::TaskbarWorkspaces::changeIndices(int fromGroupId, int toGroupId) const
{
  const auto list = model();
  int fromIndex   = -1;
  int toIndex     = -1;
  int index       = 0;
  for (auto it = list.begin(); it != list.end(); ++it) {
    const auto map = it->toMap();
    if (!map.contains(QStringLiteral("id")))
      continue;

    const int id = map.value(QStringLiteral("id")).toInt();
    if (id == fromGroupId)
      fromIndex = index;

    if (id == toGroupId)
      toIndex = index;

    ++index;
  }

  return {fromIndex, toIndex};
}

std::optional<int> UI::TaskbarWorkspaces::selectionAfterRebuild(bool independent,
                                                                int desiredGroupId,
                                                                int activeGroupId) const
{
  const auto list = model();
  if (list.isEmpty())
    return std::nullopt;

  const auto inList = [&list](int gid) {
    return gid >= 0 && std::any_of(list.begin(), list.end(), [gid](const QVariant& v) {
             return v.toMap().value(QStringLiteral("id")).toInt() == gid;
           });
  };

  if (independent && inList(desiredGroupId))
    return desiredGroupId;

  if (independent && inList(activeGroupId))
    return activeGroupId;

  const bool projectMode = m_appState.operationMode() == SerialStudio::ProjectFile;
  const int savedId      = m_projectModel.activeGroupId();
  if (projectMode && !independent && inList(savedId))
    return savedId;

  if (!list.first().canConvert<QVariantMap>())
    return -1;

  const QVariantMap first = list.first().toMap();
  return first.contains(QStringLiteral("id")) ? first[QStringLiteral("id")].toInt() : -1;
}

int UI::TaskbarWorkspaces::resolveRefWindowId(const DataModel::WidgetRef& ref) const
{
  const auto& map    = m_taskbar.windowMap();
  const int windowId = map.findWindowIdByGroupAndIndex(ref.widgetType, ref.relativeIndex);
  if (windowId < 0)
    return -1;

  const int refGid = m_dashboard.groupIdForUniqueId(ref.groupUniqueId);
  auto* item       = m_taskbar.findItemByWindowId(windowId);
  if (!item || item->data(TaskbarModel::GroupIdRole).toInt() != refGid)
    return -1;

  return windowId;
}

QVariantList UI::TaskbarWorkspaces::widgetIds(int workspaceId) const
{
  QVariantList ids;
  if (workspaceId < WorkspaceIds::AutoStart)
    return ids;

  const auto& workspaces = m_projectModel.activeWorkspaces();
  for (const auto& ws : workspaces) {
    if (ws.workspaceId != workspaceId)
      continue;

    for (const auto& ref : ws.widgetRefs) {
      const int windowId = resolveRefWindowId(ref);
      if (windowId >= 0)
        ids.append(windowId);
    }

    break;
  }

  return ids;
}

int UI::TaskbarWorkspaces::workspaceContainingWidget(int windowId) const
{
  const auto& workspaces = m_projectModel.activeWorkspaces();

  int firstMatch = -1;
  for (const auto& ws : workspaces) {
    if (ws.workspaceId < WorkspaceIds::AutoStart)
      continue;

    const auto matches = [this, windowId](const DataModel::WidgetRef& ref) {
      return resolveRefWindowId(ref) == windowId;
    };

    if (!std::any_of(ws.widgetRefs.begin(), ws.widgetRefs.end(), matches))
      continue;

    if (ws.workspaceId == m_taskbar.activeGroupId())
      return ws.workspaceId;

    if (firstMatch < 0)
      firstMatch = ws.workspaceId;
  }

  return firstMatch;
}

void UI::TaskbarWorkspaces::populateTaskbar(int groupId)
{
  auto* buttons = m_taskbar.taskbarButtons();
  SS_ASSERT(buttons != nullptr, return);

  const auto& workspaces = m_projectModel.activeWorkspaces();
  for (const auto& ws : workspaces) {
    if (ws.workspaceId != groupId)
      continue;

    for (const auto& ref : ws.widgetRefs) {
      const int windowId = resolveRefWindowId(ref);
      auto* item         = windowId < 0 ? nullptr : m_taskbar.findItemByWindowId(windowId);
      if (!item)
        continue;

      auto* clone = item->clone();
      m_taskbar.setWindowState(windowId, TaskbarModel::WindowNormal);
      buttons->appendRow(clone);
    }

    return;
  }
}

void UI::TaskbarWorkspaces::removeTaskbarRow(int windowId)
{
  auto* buttons = m_taskbar.taskbarButtons();
  SS_ASSERT(buttons != nullptr, return);

  for (int r = 0; r < buttons->rowCount(); ++r) {
    auto* row = buttons->item(r);
    if (!row || row->data(TaskbarModel::WindowIdRole).toInt() != windowId)
      continue;

    buttons->removeRow(r);
    return;
  }
}

void UI::TaskbarWorkspaces::revealWindow(int windowId)
{
  if (auto* window = m_taskbar.windowData(windowId)) {
    m_taskbar.showWindow(window);
    m_taskbar.setActiveWindow(window);
  }

  Q_EMIT highlightRequested(windowId);
}

int UI::TaskbarWorkspaces::indexOfWidgetRef(int workspaceId,
                                            int widgetType,
                                            int groupUniqueId,
                                            int relativeIndex) const
{
  const auto& workspaces = m_projectModel.activeWorkspaces();
  for (const auto& ws : workspaces) {
    if (ws.workspaceId != workspaceId)
      continue;

    for (size_t i = 0; i < ws.widgetRefs.size(); ++i) {
      const auto& ref = ws.widgetRefs[i];
      if (ref.widgetType == widgetType && ref.groupUniqueId == groupUniqueId
          && ref.relativeIndex == relativeIndex)
        return static_cast<int>(i);
    }

    return -1;
  }

  return -1;
}

bool UI::TaskbarWorkspaces::clearWorkspaceWidgets(int workspaceId)
{
  const auto& workspaces = m_projectModel.activeWorkspaces();
  for (const auto& ws : workspaces) {
    if (ws.workspaceId != workspaceId)
      continue;

    for (int i = static_cast<int>(ws.widgetRefs.size()) - 1; i >= 0; --i)
      m_projectModel.removeWidgetFromWorkspace(workspaceId, i);

    return true;
  }

  return false;
}

void UI::TaskbarWorkspaces::navigateToWidget(int windowId, int groupId, bool allowAddToWorkspace)
{
  auto* buttons = m_taskbar.taskbarButtons();
  SS_ASSERT(buttons != nullptr, return);

  for (int i = 0; i < buttons->rowCount(); ++i) {
    auto* row = buttons->item(i);
    if (!row || row->data(TaskbarModel::WindowIdRole).toInt() != windowId)
      continue;

    revealWindow(windowId);
    return;
  }

  const bool addToWorkspace = allowAddToWorkspace && !m_dashboard.frozen()
                           && m_taskbar.activeGroupId() >= WorkspaceIds::AutoStart;
  if (addToWorkspace)
    addWidgetToActiveWorkspace(windowId);

  else
    m_taskbar.setActiveGroupId(groupId);

  QTimer::singleShot(kRevealDelayMs, this, [this, windowId] { revealWindow(windowId); });
}

void UI::TaskbarWorkspaces::createWorkspace(const QString& name)
{
  m_projectModel.addWorkspace(name);

  const auto& workspaces = m_projectModel.activeWorkspaces();
  if (!workspaces.empty())
    m_taskbar.setActiveGroupId(workspaces.back().workspaceId);

  Q_EMIT workspacesChanged();
}

void UI::TaskbarWorkspaces::deleteWorkspace(int workspaceId)
{
  const bool customized = m_projectModel.customizeWorkspaces();
  const int floorId     = customized ? WorkspaceIds::AutoStart : WorkspaceIds::PerGroupStart;
  if (workspaceId < floorId)
    return;

  if (customized)
    m_projectModel.deleteWorkspace(workspaceId);

  else
    m_projectModel.hideGroup(workspaceId - WorkspaceIds::PerGroupStart);

  if (m_taskbar.activeGroupId() == workspaceId) {
    const auto list = model();
    if (!list.isEmpty())
      m_taskbar.setActiveGroupId(list.first().toMap().value(QStringLiteral("id"), -1).toInt());
  }

  Q_EMIT workspacesChanged();
}

void UI::TaskbarWorkspaces::renameWorkspace(int workspaceId, const QString& name)
{
  if (workspaceId < WorkspaceIds::AutoStart)
    return;

  m_projectModel.renameWorkspace(workspaceId, name);
  Q_EMIT workspacesChanged();
}

void UI::TaskbarWorkspaces::addWidgetToActiveWorkspace(int windowId)
{
  const int activeId = m_taskbar.activeGroupId();
  if (activeId < WorkspaceIds::AutoStart)
    return;

  auto* item = m_taskbar.findItemByWindowId(windowId);
  if (!item)
    return;

  const int relIdx = m_taskbar.windowMap().relativeIndexForWindow(windowId);
  if (relIdx < 0)
    return;

  const auto widgetType = item->data(TaskbarModel::WidgetTypeRole).toInt();
  const auto groupId    = item->data(TaskbarModel::GroupIdRole).toInt();
  const int groupUid    = m_dashboard.groupUniqueIdForGroupId(groupId);
  m_projectModel.addWidgetToWorkspace(activeId, widgetType, groupUid, relIdx);

  auto* buttons = m_taskbar.taskbarButtons();
  SS_ASSERT(buttons != nullptr, return);

  auto* clone = item->clone();
  m_taskbar.setWindowState(clone->data(TaskbarModel::WindowIdRole).toInt(),
                           TaskbarModel::WindowNormal);
  buttons->appendRow(clone);
  Q_EMIT taskbarRowsChanged();
}

void UI::TaskbarWorkspaces::removeWidgetFromActiveWorkspace(int windowId)
{
  const int activeId = m_taskbar.activeGroupId();
  if (activeId < WorkspaceIds::AutoStart)
    return;

  auto* item = m_taskbar.findItemByWindowId(windowId);
  if (!item)
    return;

  const int relIdx = m_taskbar.windowMap().relativeIndexForWindow(windowId);
  if (relIdx < 0)
    return;

  const auto widgetType = item->data(TaskbarModel::WidgetTypeRole).toInt();
  const auto groupId    = item->data(TaskbarModel::GroupIdRole).toInt();
  const int targetUid   = m_dashboard.groupUniqueIdForGroupId(groupId);

  const int refIndex = indexOfWidgetRef(activeId, widgetType, targetUid, relIdx);
  if (refIndex < 0)
    return;

  m_projectModel.removeWidgetFromWorkspace(activeId, refIndex);
  if (auto* window = m_taskbar.windowData(windowId))
    m_taskbar.unregisterWindow(window);

  removeTaskbarRow(windowId);
  Q_EMIT taskbarRowsChanged();
}

void UI::TaskbarWorkspaces::setWorkspaceWidgets(int workspaceId, const QVariantList& windowIds)
{
  if (workspaceId < WorkspaceIds::AutoStart || !clearWorkspaceWidgets(workspaceId))
    return;

  for (const auto& idVar : windowIds) {
    const int windowId = idVar.toInt();
    auto* item         = m_taskbar.findItemByWindowId(windowId);
    const int relIdx   = m_taskbar.windowMap().relativeIndexForWindow(windowId);
    if (!item || relIdx < 0)
      continue;

    const auto widgetType = item->data(TaskbarModel::WidgetTypeRole).toInt();
    const auto groupId    = item->data(TaskbarModel::GroupIdRole).toInt();
    const int groupUid    = m_dashboard.groupUniqueIdForGroupId(groupId);
    m_projectModel.addWidgetToWorkspace(workspaceId, widgetType, groupUid, relIdx);
  }

  if (m_taskbar.activeGroupId() == workspaceId)
    m_taskbar.setActiveGroupId(workspaceId);
}

static const std::array<int64_t, kMaxBlurTaps + 1>& blurReciprocalTable()
{
  static const auto table = []() {
    std::array<int64_t, kMaxBlurTaps + 1> t{};
    const int64_t one = int64_t(1) << kBlurReciprocalShift;
    for (int n = 1; n <= kMaxBlurTaps; ++n)
      t[n] = (one + n - 1) / n;

    return t;
  }();
  return table;
}

static void boxBlurHorizontal(const QImage& src, QImage& dst, int radius)
{
  const int w     = src.width();
  const int h     = src.height();
  const auto& inv = blurReciprocalTable();
  for (int y = 0; y < h; ++y) {
    const QRgb* srow = reinterpret_cast<const QRgb*>(src.constScanLine(y));
    QRgb* drow       = reinterpret_cast<QRgb*>(dst.scanLine(y));
    for (int x = 0; x < w; ++x) {
      int r = 0, g = 0, b = 0, a = 0, n = 0;
      const int x0 = qMax(0, x - radius);
      const int x1 = qMin(w - 1, x + radius);
      for (int k = x0; k <= x1; ++k) {
        r += qRed(srow[k]);
        g += qGreen(srow[k]);
        b += qBlue(srow[k]);
        a += qAlpha(srow[k]);
        ++n;
      }
      const int64_t recip = inv[n];
      drow[x]             = qRgba(static_cast<int>((r * recip) >> kBlurReciprocalShift),
                      static_cast<int>((g * recip) >> kBlurReciprocalShift),
                      static_cast<int>((b * recip) >> kBlurReciprocalShift),
                      static_cast<int>((a * recip) >> kBlurReciprocalShift));
    }
  }
}

static void boxBlurVertical(const QImage& src, QImage& dst, int radius)
{
  const int w     = src.width();
  const int h     = src.height();
  const auto& inv = blurReciprocalTable();
  for (int x = 0; x < w; ++x) {
    for (int y = 0; y < h; ++y) {
      int r = 0, g = 0, b = 0, a = 0, n = 0;
      const int y0 = qMax(0, y - radius);
      const int y1 = qMin(h - 1, y + radius);
      for (int k = y0; k <= y1; ++k) {
        const QRgb px  = reinterpret_cast<const QRgb*>(src.constScanLine(k))[x];
        r             += qRed(px);
        g             += qGreen(px);
        b             += qBlue(px);
        a             += qAlpha(px);
        ++n;
      }
      const int64_t recip = inv[n];
      reinterpret_cast<QRgb*>(dst.scanLine(y))[x] =
        qRgba(static_cast<int>((r * recip) >> kBlurReciprocalShift),
              static_cast<int>((g * recip) >> kBlurReciprocalShift),
              static_cast<int>((b * recip) >> kBlurReciprocalShift),
              static_cast<int>((a * recip) >> kBlurReciprocalShift));
    }
  }
}

void Widgets::PainterBlur::applyBoxBlur(QImage& image, int radius)
{
  for (int pass = 0; pass < 3; ++pass) {
    QImage blurred(image.size(), QImage::Format_ARGB32_Premultiplied);
    blurred.fill(Qt::transparent);
    boxBlurHorizontal(image, blurred, radius);
    image.fill(Qt::transparent);
    boxBlurVertical(blurred, image, radius);
  }
}

[[nodiscard]] static QString resolveFontFamily(const QString& family,
                                               const Misc::CommonFonts& commonFonts)
{
  const QString trimmed = family.trimmed();
  if (trimmed.isEmpty())
    return commonFonts.widgetFontFamily();

  const QString lower = trimmed.toLower();
  if (lower == QLatin1String("sans-serif") || lower == QLatin1String("system-ui")
      || lower == QLatin1String("ui-sans-serif"))
    return commonFonts.widgetFontFamily();

  if (lower == QLatin1String("monospace") || lower == QLatin1String("ui-monospace"))
    return commonFonts.monoFont().family();

  if (lower == QLatin1String("serif") || lower == QLatin1String("ui-serif")
      || lower == QLatin1String("cursive") || lower == QLatin1String("fantasy"))
    return commonFonts.uiFont().family();

  return trimmed;
}

QFont Widgets::PainterFont::parseFontSpec(const QString& spec, const Misc::CommonFonts& fonts)
{
  static const QRegularExpression sizeRe(QStringLiteral("(\\d+(?:\\.\\d+)?)\\s*px"));

  bool bold   = false;
  bool italic = false;
  qreal size  = 10.0;

  const auto sizeMatch = sizeRe.match(spec);
  if (sizeMatch.hasMatch())
    size = SerialStudio::toDouble(sizeMatch.captured(1));

  const QString lower = spec.toLower();
  if (lower.contains(QLatin1String("italic")))
    italic = true;

  if (lower.contains(QLatin1String("bold")) || lower.contains(QLatin1String(" 700"))
      || lower.contains(QLatin1String(" 800")) || lower.contains(QLatin1String(" 900")))
    bold = true;

  QString family;
  if (sizeMatch.hasMatch()) {
    const int sizeEnd  = sizeMatch.capturedEnd();
    const QString tail = spec.mid(sizeEnd).trimmed();
    static const QRegularExpression kSep(QStringLiteral("[,\\s]+"));
    const QStringList tokens = tail.split(kSep, Qt::SkipEmptyParts);
    if (!tokens.isEmpty())
      family = tokens.first();
  }

  QFont f(resolveFontFamily(family, fonts), 10);
  f.setPointSizeF(size * 0.75);
  f.setBold(bold);
  f.setItalic(italic);

  return f;
}

Widgets::PainterGradient* Widgets::PainterContext::createLinearGradient(qreal x0,
                                                                        qreal y0,
                                                                        qreal x1,
                                                                        qreal y1)
{
  auto* g = new PainterGradient(PainterGradient::Kind::Linear, this);
  g->setLinear(x0, y0, x1, y1);
  return g;
}

Widgets::PainterGradient* Widgets::PainterContext::createRadialGradient(
  qreal x0, qreal y0, qreal r0, qreal x1, qreal y1, qreal r1)
{
  auto* g = new PainterGradient(PainterGradient::Kind::Radial, this);
  g->setRadial(x0, y0, r0, x1, y1, r1);
  return g;
}

Widgets::PainterGradient* Widgets::PainterContext::createConicGradient(qreal startRad,
                                                                       qreal cx,
                                                                       qreal cy)
{
  auto* g = new PainterGradient(PainterGradient::Kind::Conic, this);
  g->setConic(cx, cy, startRad);
  return g;
}

Widgets::PainterPattern* Widgets::PainterContext::createPattern(const QString& src,
                                                                const QString& repetition)
{
  const QString resolved = resolveImagePath(src);
  if (resolved.isEmpty())
    return new PainterPattern(QPixmap(), repetition, this);

  return new PainterPattern(QPixmap(resolved), repetition, this);
}

void Widgets::TerminalBuffer::setColumns(int columns)
{
  SS_ASSERT(columns > 0, columns = DEFAULT_COLUMNS);
  m_columns = columns;
}

void Widgets::TerminalBuffer::setMaxLines(int maxLines)
{
  SS_ASSERT(maxLines > 0, maxLines = MAX_UPFRONT_RESERVE);
  m_maxLines = maxLines;
}

int Widgets::TerminalBuffer::takeDroppedLines()
{
  const int dropped = m_droppedLines;
  m_droppedLines    = 0;
  return dropped;
}

bool Widgets::TerminalBuffer::takeCursorMoved()
{
  const bool moved = m_cursorMoved;
  m_cursorMoved    = false;
  return moved;
}

int Widgets::TerminalBuffer::visualBottomRow() const
{
  const int row = m_cursor.y();

  int wrappedLines = 1;
  if (row < m_data.size()) {
    const int lineLength = static_cast<int>(m_data[row].length());
    wrappedLines         = (lineLength + m_columns - 1) / m_columns;
  }

  return row + wrappedLines - 1;
}

void Widgets::TerminalBuffer::reset()
{
  const int reserveLines = qMin(m_maxLines, MAX_UPFRONT_RESERVE);

  m_data.clear();
  m_data.squeeze();
  m_data.reserve(reserveLines);
  m_colorData.clear();
  m_colorData.squeeze();
  m_repeatCounts.clear();
  m_repeatCounts.squeeze();
  m_repeatCounts.reserve(reserveLines);

  m_droppedLines = 0;

  if (m_ansiColors)
    m_colorData.reserve(reserveLines);
}

void Widgets::TerminalBuffer::squeeze()
{
  m_data.squeeze();
  m_colorData.squeeze();
  m_repeatCounts.squeeze();
}

void Widgets::TerminalBuffer::setCursor(const QPoint& position)
{
  const QPoint clamped(qBound(0, position.x(), m_columns), qBound(0, position.y(), m_maxLines));
  if (m_cursor != clamped) {
    m_cursor      = clamped;
    m_cursorMoved = true;
  }
}

int Widgets::TerminalBuffer::trimToMaxLines()
{
  const int excess = static_cast<int>(m_data.size()) - m_maxLines;
  if (excess <= 0)
    return 0;

  trimFront(excess);
  return excess;
}

void Widgets::TerminalBuffer::trimFront(int linesToDrop)
{
  SS_ASSERT(linesToDrop > 0, return);
  SS_ASSERT(linesToDrop <= m_data.size(), linesToDrop = static_cast<int>(m_data.size()));

  m_data.erase(m_data.begin(), m_data.begin() + linesToDrop);

  // code-verify off
  // Trim color rows in lockstep with text rows regardless of the ansiColors() toggle: rows
  // recorded while colors were on must not survive as a stale, misaligned front.
  if (!m_colorData.isEmpty()) {
    const int colorDrop = qMin(linesToDrop, static_cast<int>(m_colorData.size()));
    m_colorData.erase(m_colorData.begin(), m_colorData.begin() + colorDrop);
  }
  // code-verify on

  if (!m_repeatCounts.isEmpty()) {
    const int countDrop = qMin(linesToDrop, static_cast<int>(m_repeatCounts.size()));
    m_repeatCounts.erase(m_repeatCounts.begin(), m_repeatCounts.begin() + countDrop);
  }

  if (m_cursor.y() >= linesToDrop)
    m_cursor.setY(m_cursor.y() - linesToDrop);
  else
    m_cursor.setY(0);

  m_droppedLines += linesToDrop;
}

void Widgets::TerminalBuffer::appendText(QStringView string)
{
  const int linesToDrop = static_cast<int>(m_data.size()) - m_maxLines + 1;
  if (m_data.size() >= m_maxLines && linesToDrop > 0)
    trimFront(linesToDrop);

  for (const auto& character : string) {
    const int cursorX = m_cursor.x();
    const int cursorY = m_cursor.y();
    replaceData(cursorX, cursorY, character);
    setCursor(cursorX + 1, cursorY);

    if (m_cursor.x() >= m_columns)
      setCursor(0, m_cursor.y() + 1);
  }
}

Widgets::TerminalBuffer::FeedResult Widgets::TerminalBuffer::processText(const QChar& byte,
                                                                         QString& text,
                                                                         bool vt100)
{
  const ushort code = byte.unicode();

  if (code == '\n') {
    appendText(text);
    text.clear();

    const int next_row = m_cursor.y() + (collapseCompletedLine() ? 0 : 1);
    setCursor(0, next_row);
    return Handled;
  }

  if (!vt100) {
    if (byte.isPrint())
      text.append(byte);

    return Handled;
  }

  switch (code) {
    case 0x1b:
      appendText(text);
      text.clear();
      return BeginEscape;
    case '\r':
      appendText(text);
      text.clear();
      setCursor(0, m_cursor.y());
      return Handled;
    case '\b':
      if (m_cursor.x() == 0)
        return Handled;

      appendText(text);
      text.clear();
      setCursor(m_cursor.x() - 1, m_cursor.y());
      return Handled;
    case 0x7F:
      appendText(text);
      text.clear();
      removeFromCursor(AnsiEraseDirection::Right, 1);
      return Handled;
    case '\t': {
      appendText(text);
      text.clear();
      const int nextTab = (m_cursor.x() / 8 + 1) * 8;
      const int spaces  = nextTab - m_cursor.x();
      text.fill(' ', spaces);
      appendText(text);
      text.clear();
      return Handled;
    }
    default:
      break;
  }

  if (byte.isPrint())
    text.append(byte);

  return Handled;
}

void Widgets::TerminalBuffer::replaceData(int x, int y, const QChar& byte)
{
  if (y >= m_data.size())
    m_data.resize(y + 1);

  while (m_repeatCounts.size() < m_data.size())
    m_repeatCounts.append(1);

  QString& line = m_data[y];

  if (m_ansiColors) {
    if (y >= m_colorData.size())
      m_colorData.resize(y + 1);

    QList<CharColor>& colorLine = m_colorData[y];

    if (x > line.size()) {
      const int padCount = x - static_cast<int>(line.size());
      for (int i = 0; i < padCount; ++i)
        colorLine.append(CharColor());
    }

    while (colorLine.size() < line.size())
      colorLine.append(CharColor());

    const CharColor charColor(m_palette.foreground(), m_palette.background());
    if (x >= 0 && x < colorLine.size())
      colorLine[x] = charColor;
    else if (x >= 0)
      colorLine.append(charColor);
  }

  if (x > line.size())
    line = line.leftJustified(x, ' ');

  if (x >= 0 && x < line.size())
    line[x] = byte.isPrint() ? byte : ' ';
  else if (x >= 0)
    line.append(byte.isPrint() ? byte : ' ');
}

void Widgets::TerminalBuffer::removeFromCursor(AnsiEraseDirection direction, int length)
{
  const auto positionX = m_cursor.x();
  const auto positionY = m_cursor.y();

  if (length < 0)
    length = INT_MAX;

  int removeSize = 0;
  if (direction == AnsiEraseDirection::Right) {
    const qsizetype lineLen =
      (positionY >= 0 && positionY < m_data.size()) ? m_data[positionY].size() : qsizetype(0);
    const qsizetype l1 = lineLen - positionX;
    const qsizetype l2 = static_cast<qsizetype>(length);
    removeSize         = static_cast<int>(qMin(qMax(l1, qsizetype(0)), l2));
  }

  else
    removeSize = qMin(length, positionX);

  int offset = 0;
  const QChar clearChar('\x7F');
  for (int i = 0; i < removeSize; ++i) {
    if (direction == AnsiEraseDirection::Left)
      offset = -1 - i;
    else
      offset = i;

    replaceData(m_cursor.x() + offset, positionY, clearChar);
  }
}

bool Widgets::TerminalBuffer::hasTimestampPrefix(QStringView line)
{
  constexpr int kStampLen        = 16;
  constexpr int kDigitIndices[9] = {0, 1, 3, 4, 6, 7, 9, 10, 11};

  if (line.size() < kStampLen)
    return false;

  if (line[2] != QLatin1Char(':') || line[5] != QLatin1Char(':') || line[8] != QLatin1Char('.'))
    return false;

  if (line[12] != QLatin1Char(' ') || line[13] != QLatin1Char('-') || line[14] != QLatin1Char('>')
      || line[15] != QLatin1Char(' '))
    return false;

  for (const int index : kDigitIndices)
    if (!line[index].isDigit())
      return false;

  return true;
}

QStringView Widgets::TerminalBuffer::lineContentView(QStringView line) const
{
  constexpr int kStampLen = 16;

  if (!m_showTimestamps || !hasTimestampPrefix(line))
    return line;

  return line.mid(kStampLen);
}

bool Widgets::TerminalBuffer::collapseCompletedLine()
{
  if (!m_collapseDuplicates)
    return false;

  const int y = m_cursor.y();
  if (y < 1 || y != m_data.size() - 1)
    return false;

  const auto current  = lineContentView(m_data[y]);
  const auto previous = lineContentView(m_data[y - 1]);
  if (current.trimmed().isEmpty() || current != previous)
    return false;

  m_data.removeLast();
  if (m_colorData.size() > m_data.size())
    m_colorData.resize(m_data.size());

  if (m_repeatCounts.size() > m_data.size())
    m_repeatCounts.resize(m_data.size());

  if (y - 1 < m_repeatCounts.size() && m_repeatCounts[y - 1] < INT_MAX)
    ++m_repeatCounts[y - 1];

  return true;
}

void Widgets::TerminalBuffer::eraseRowsAfter(int row)
{
  if (row + 1 >= m_data.size())
    return;

  m_data.erase(m_data.begin() + row + 1, m_data.end());
  if (m_ansiColors && row + 1 < m_colorData.size())
    m_colorData.erase(m_colorData.begin() + row + 1, m_colorData.end());

  if (row + 1 < m_repeatCounts.size())
    m_repeatCounts.erase(m_repeatCounts.begin() + row + 1, m_repeatCounts.end());
}

void Widgets::TerminalBuffer::eraseRowsBefore(int row)
{
  if (row <= 0)
    return;

  m_data.erase(m_data.begin(), m_data.begin() + row);
  if (m_ansiColors && row < m_colorData.size())
    m_colorData.erase(m_colorData.begin(), m_colorData.begin() + row);

  const auto countDrop = qMin<qsizetype>(row, m_repeatCounts.size());
  if (countDrop > 0)
    m_repeatCounts.erase(m_repeatCounts.begin(), m_repeatCounts.begin() + countDrop);
}

QByteArray Widgets::Vt100Keymap::specialKey(int key)
{
  QByteArray seq;
  switch (key) {
    case Qt::Key_Backspace:
      seq.append('\x7f');
      break;
    case Qt::Key_Delete:
      seq.append("\x1b[3~");
      break;
    case Qt::Key_Tab:
      seq.append('\t');
      break;
    case Qt::Key_Backtab:
      seq.append("\x1b[Z");
      break;
    case Qt::Key_Escape:
      seq.append('\x1b');
      break;
    case Qt::Key_Up:
      seq.append("\x1b[A");
      break;
    case Qt::Key_Down:
      seq.append("\x1b[B");
      break;
    case Qt::Key_Right:
      seq.append("\x1b[C");
      break;
    case Qt::Key_Left:
      seq.append("\x1b[D");
      break;
    case Qt::Key_Home:
      seq.append("\x1b[H");
      break;
    case Qt::Key_End:
      seq.append("\x1b[F");
      break;
    case Qt::Key_PageUp:
      seq.append("\x1b[5~");
      break;
    case Qt::Key_PageDown:
      seq.append("\x1b[6~");
      break;
    case Qt::Key_Insert:
      seq.append("\x1b[2~");
      break;
    case Qt::Key_F1:
      seq.append("\x1bOP");
      break;
    case Qt::Key_F2:
      seq.append("\x1bOQ");
      break;
    case Qt::Key_F3:
      seq.append("\x1bOR");
      break;
    case Qt::Key_F4:
      seq.append("\x1bOS");
      break;
    case Qt::Key_F5:
      seq.append("\x1b[15~");
      break;
    case Qt::Key_F6:
      seq.append("\x1b[17~");
      break;
    case Qt::Key_F7:
      seq.append("\x1b[18~");
      break;
    case Qt::Key_F8:
      seq.append("\x1b[19~");
      break;
    case Qt::Key_F9:
      seq.append("\x1b[20~");
      break;
    case Qt::Key_F10:
      seq.append("\x1b[21~");
      break;
    case Qt::Key_F11:
      seq.append("\x1b[23~");
      break;
    case Qt::Key_F12:
      seq.append("\x1b[24~");
      break;
    default:
      break;
  }

  return seq;
}

QByteArray Widgets::Vt100Keymap::translate(const QKeyEvent* event, const QByteArray& enterSequence)
{
  SS_ASSERT(event != nullptr, return QByteArray());

  QByteArray seq;
  const Qt::KeyboardModifiers mods = event->modifiers();
  const int key                    = event->key();

  if ((mods & Qt::ControlModifier) && key >= Qt::Key_A && key <= Qt::Key_Z) {
    seq.append(char(key - Qt::Key_A + 1));
    return seq;
  }

  if ((mods & Qt::ControlModifier) && key == Qt::Key_BracketLeft) {
    seq.append('\x1b');
    return seq;
  }

  if (key == Qt::Key_Return || key == Qt::Key_Enter)
    return enterSequence;

  seq = specialKey(key);
  if (!seq.isEmpty())
    return seq;

  if (!event->text().isEmpty())
    seq = event->text().toUtf8();

  return seq;
}

ariantMap TstChatDigest::userRow(const QString& text)
{
  QVariantMap row;
  row[QStringLiteral("role")]      = QStringLiteral("user");
  row[QStringLiteral("text")]      = text;
  row[QStringLiteral("toolCalls")] = QVariantList();
  return row;
}

ariantMap TstChatDigest::assistantRow(const QString& text, const QVariantList& calls)
{
  QVariantMap row;
  row[QStringLiteral("role")]      = QStringLiteral("assistant");
  row[QStringLiteral("text")]      = text;
  row[QStringLiteral("toolCalls")] = calls;
  return row;
}

ariantMap TstChatDigest::toolCard(const QString& name, AI::ToolCallStatus status)
{
  QVariantMap card;
  card[QStringLiteral("callId")] = name + QStringLiteral("-id");
  card[QStringLiteral("name")]   = name;
  card[QStringLiteral("status")] = static_cast<int>(status);
  return card;
}

id TstChatDigest::firstUserTextPicksFirstUserRow()
{
  const QVariantList rows{assistantRow(QStringLiteral("preamble"), {}),
                          userRow(QStringLiteral("first ask")),
                          userRow(QStringLiteral("second ask"))};

  QCOMPARE(AI::ChatDigest::firstUserText(rows), QStringLiteral("first ask"));
}

id TstChatDigest::firstUserTextIsEmptyWithoutUserRows()
{
  const QVariantList rows{assistantRow(QStringLiteral("only me"), {})};

  QVERIFY(AI::ChatDigest::firstUserText(rows).isEmpty());
  QVERIFY(AI::ChatDigest::firstUserText(QVariantList()).isEmpty());
}

id TstChatDigest::handoffDigestKeepsLastThreeAsksInOrder()
{
  const QVariantList rows{userRow(QStringLiteral("ask one")),
                          userRow(QStringLiteral("ask two")),
                          userRow(QStringLiteral("ask three")),
                          userRow(QStringLiteral("ask four")),
                          assistantRow(QStringLiteral("the reply"), {})};

  const auto digest = AI::ChatDigest::buildHandoffDigest(rows, 600);
  QVERIFY(digest.contains(QStringLiteral("Asked: ask two | ask three | ask four")));
  QVERIFY(!digest.contains(QStringLiteral("ask one")));
  QVERIFY(digest.contains(QStringLiteral("Last reply: the reply")));
}

id TstChatDigest::handoffDigestListsOnlyCompletedNonMetaActions()
{
  const QVariantList calls{
    toolCard(QStringLiteral("project.dataset.add"), AI::ToolCallStatus::Done),
    toolCard(QStringLiteral("meta.snapshot"), AI::ToolCallStatus::Done),
    toolCard(QStringLiteral("io.connect"), AI::ToolCallStatus::Error)};
  const QVariantList rows{assistantRow(QString(), calls), userRow(QStringLiteral("do it"))};

  const auto digest = AI::ChatDigest::buildHandoffDigest(rows, 600);
  QVERIFY(digest.contains(QStringLiteral("Actions: project.dataset.add")));
  QVERIFY(!digest.contains(QStringLiteral("meta.snapshot")));
  QVERIFY(!digest.contains(QStringLiteral("io.connect")));
}

id TstChatDigest::handoffDigestScrubsSecretsBeforeCapping()
{
  const QVariantList rows{userRow(QStringLiteral("my key is AKIAIOSFODNN7EXAMPLE ok"))};

  const auto digest = AI::ChatDigest::buildHandoffDigest(rows, 600);
  QVERIFY(!digest.contains(QStringLiteral("AKIAIOSFODNN7EXAMPLE")));
  QVERIFY(digest.contains(QStringLiteral("[REDACTED:aws_access_key_id]")));
}

id TstChatDigest::handoffDigestHonoursCharacterCap()
{
  const QVariantList rows{userRow(QString(300, QLatin1Char('a'))),
                          assistantRow(QString(300, QLatin1Char('b')), {})};

  QCOMPARE(static_cast<int>(AI::ChatDigest::buildHandoffDigest(rows, 32).size()), 32);
}

id TstChatDigest::staleCardsDowngradeOnlyUnfinishedStatuses()
{
  const QVariantList calls{toolCard(QStringLiteral("a.run"), AI::ToolCallStatus::Running),
                           toolCard(QStringLiteral("b.ask"), AI::ToolCallStatus::AwaitingConfirm),
                           toolCard(QStringLiteral("c.bad"), AI::ToolCallStatus::Error),
                           toolCard(QStringLiteral("d.no"), AI::ToolCallStatus::Denied)};
  QVariantList rows{userRow(QStringLiteral("go")), assistantRow(QString(), calls)};

  AI::ChatDigest::downgradeStaleToolCards(rows);

  const auto restored = rows.at(1).toMap().value(QStringLiteral("toolCalls")).toList();
  QCOMPARE(static_cast<int>(restored.size()), 4);
  QCOMPARE(restored.at(0).toMap().value(QStringLiteral("status")).toInt(),
           static_cast<int>(AI::ToolCallStatus::Done));
  QCOMPARE(restored.at(1).toMap().value(QStringLiteral("status")).toInt(),
           static_cast<int>(AI::ToolCallStatus::Done));
  QCOMPARE(restored.at(2).toMap().value(QStringLiteral("status")).toInt(),
           static_cast<int>(AI::ToolCallStatus::Error));
  QCOMPARE(restored.at(3).toMap().value(QStringLiteral("status")).toInt(),
           static_cast<int>(AI::ToolCallStatus::Denied));
  QCOMPARE(rows.at(0).toMap().value(QStringLiteral("role")).toString(), QStringLiteral("user"));
}

bool TstCliSpecParsers::parse(QCommandLineParser& parser,
                              const QCommandLineOption& opt,
                              const QString& value)
{
  if (!parser.addOption(opt))
    return false;

  const QString arg = QStringLiteral("--") + opt.names().first() + QStringLiteral("=") + value;
  return parser.parse(QStringList{QStringLiteral("app"), arg});
}

void TstCliSpecParsers::intOptionRejectsAnUnsetOption()
{
  QCommandLineParser parser;
  const QCommandLineOption opt(QStringLiteral("rack"), QStringLiteral("rack"), QStringLiteral("n"));
  QVERIFY(parser.addOption(opt));
  QVERIFY(parser.parse(QStringList{QStringLiteral("app")}));

  int out = 7;
  QVERIFY(!Misc::CliSpecParsers::parseIntOption(parser, opt, 0, 31, QStringLiteral("rack"), out));
  QCOMPARE(out, 7);
}

void TstCliSpecParsers::intOptionAcceptsAnInRangeValue()
{
  QCommandLineParser parser;
  const QCommandLineOption opt(QStringLiteral("rack"), QStringLiteral("rack"), QStringLiteral("n"));
  QVERIFY(parse(parser, opt, QStringLiteral("5")));

  int out = -1;
  QVERIFY(Misc::CliSpecParsers::parseIntOption(parser, opt, 0, 31, QStringLiteral("rack"), out));
  QCOMPARE(out, 5);
}

void TstCliSpecParsers::intOptionRejectsOutOfRangeValues()
{
  for (const QString& value : {QStringLiteral("-1"), QStringLiteral("32")}) {
    QCommandLineParser parser;
    const QCommandLineOption opt(
      QStringLiteral("rack"), QStringLiteral("rack"), QStringLiteral("n"));
    QVERIFY(parse(parser, opt, value));

    int out = 4;
    QTest::ignoreMessage(QtWarningMsg, QRegularExpression(QStringLiteral("Invalid rack")));
    QVERIFY(!Misc::CliSpecParsers::parseIntOption(parser, opt, 0, 31, QStringLiteral("rack"), out));
    QCOMPARE(out, 4);
  }
}

void TstCliSpecParsers::intOptionRejectsANonNumericToken()
{
  QCommandLineParser parser;
  const QCommandLineOption opt(QStringLiteral("rack"), QStringLiteral("rack"), QStringLiteral("n"));
  QVERIFY(parse(parser, opt, QStringLiteral("two")));

  int out = 3;
  QTest::ignoreMessage(QtWarningMsg, QRegularExpression(QStringLiteral("Invalid rack")));
  QVERIFY(!Misc::CliSpecParsers::parseIntOption(parser, opt, 0, 31, QStringLiteral("rack"), out));
  QCOMPARE(out, 3);
}

void TstCliSpecParsers::intOptionAcceptsADegenerateRange()
{
  QCommandLineParser parser;
  const QCommandLineOption opt(QStringLiteral("slot"), QStringLiteral("slot"), QStringLiteral("n"));
  QVERIFY(parse(parser, opt, QStringLiteral("1")));

  int out = -1;
  QVERIFY(Misc::CliSpecParsers::parseIntOption(parser, opt, 1, 1, QStringLiteral("slot"), out));
  QCOMPARE(out, 1);
}

void TstCliSpecParsers::intOptionRejectsAnInvertedRange()
{
  QCommandLineParser parser;
  const QCommandLineOption opt(QStringLiteral("slot"), QStringLiteral("slot"), QStringLiteral("n"));
  QVERIFY(parse(parser, opt, QStringLiteral("5")));

  int out = 9;
  QVERIFY(!Misc::CliSpecParsers::parseIntOption(parser, opt, 31, 0, QStringLiteral("slot"), out));
  QCOMPARE(out, 9);
}

