void TstCliSpecParsers::serialIndexTablesMapKnownTokens()
{
  QCOMPARE(Misc::CliSpecParsers::modbusParityIndex(QStringLiteral("none")), 0);
  QCOMPARE(Misc::CliSpecParsers::modbusParityIndex(QStringLiteral("even")), 1);
  QCOMPARE(Misc::CliSpecParsers::modbusParityIndex(QStringLiteral("odd")), 2);
  QCOMPARE(Misc::CliSpecParsers::modbusParityIndex(QStringLiteral("space")), 3);
  QCOMPARE(Misc::CliSpecParsers::modbusParityIndex(QStringLiteral("mark")), 4);

  QCOMPARE(Misc::CliSpecParsers::modbusDataBitsIndex(QStringLiteral("5")), 0);
  QCOMPARE(Misc::CliSpecParsers::modbusDataBitsIndex(QStringLiteral("8")), 3);

  QCOMPARE(Misc::CliSpecParsers::modbusStopBitsIndex(QStringLiteral("1")), 0);
  QCOMPARE(Misc::CliSpecParsers::modbusStopBitsIndex(QStringLiteral("1.5")), 1);
  QCOMPARE(Misc::CliSpecParsers::modbusStopBitsIndex(QStringLiteral("2")), 2);
}

void TstCliSpecParsers::serialIndexTablesRejectUnknownTokens()
{
  QCOMPARE(Misc::CliSpecParsers::modbusParityIndex(QStringLiteral("NONE")), -1);
  QCOMPARE(Misc::CliSpecParsers::modbusParityIndex(QString()), -1);
  QCOMPARE(Misc::CliSpecParsers::modbusDataBitsIndex(QStringLiteral("9")), -1);
  QCOMPARE(Misc::CliSpecParsers::modbusStopBitsIndex(QStringLiteral("1.0")), -1);
}

id capture(int sourceId, qint64 timestampMs)
  {
    auto& entry       = frames[sourceId];
    entry.sourceId    = sourceId;
    entry.timestampMs = timestampMs;
    entry.sequence    = ++sequence;
    newestSourceId    = sourceId;
  }
}

id TstLatestFrameTap::drainStaysIdleUntilArmed()
{
  QObject owner;
  CaptureState state;
  DataModel::ParseBudget budget;
  DataModel::LatestFrameTap tap(owner, state.frames, state.newestSourceId, state.sequence, budget);

  state.capture(0, 100);

  QVERIFY(!tap.drainForGui());

  tap.publish();
  QVERIFY(!tap.drainForGui());
}

id TstLatestFrameTap::requestIsLatchedUntilPublished()
{
  QObject owner;
  CaptureState state;
  DataModel::ParseBudget budget;
  DataModel::LatestFrameTap tap(owner, state.frames, state.newestSourceId, state.sequence, budget);

  QCOMPARE(tap.guiLatestFrame(-1).sequence, quint64(0));
  state.capture(0, 100);

  QVERIFY(tap.drainForGui());
  QVERIFY(!tap.drainForGui());

  tap.publish();
  QVERIFY(tap.drainForGui());
}

id TstLatestFrameTap::publishedCaptureReachesTheGui()
{
  QObject owner;
  CaptureState state;
  DataModel::ParseBudget budget;
  DataModel::LatestFrameTap tap(owner, state.frames, state.newestSourceId, state.sequence, budget);

  QCOMPARE(tap.guiLatestFrame(1).sequence, quint64(0));
  state.capture(1, 4242);
  tap.publish();
  QVERIFY(tap.drainForGui());

  const auto served = tap.guiLatestFrame(1);
  QCOMPARE(served.sourceId, 1);
  QCOMPARE(served.timestampMs, qint64(4242));
  QCOMPARE(served.sequence, quint64(1));

  QCOMPARE(tap.guiLatestFrame(9).sequence, quint64(0));
}

id TstLatestFrameTap::newestSourceIsServedByDefault()
{
  QObject owner;
  CaptureState state;
  DataModel::ParseBudget budget;
  DataModel::LatestFrameTap tap(owner, state.frames, state.newestSourceId, state.sequence, budget);

  QCOMPARE(tap.guiLatestFrame(-1).sequence, quint64(0));
  state.capture(0, 10);
  state.capture(3, 20);
  tap.publish();
  QVERIFY(tap.drainForGui());

  QCOMPARE(tap.guiLatestFrame(-1).sourceId, 3);
  QCOMPARE(tap.guiLatestFrame(0).timestampMs, qint64(10));
}

id TstLatestFrameTap::unchangedSequenceDoesNotRepublish()
{
  QObject owner;
  CaptureState state;
  DataModel::ParseBudget budget;
  DataModel::LatestFrameTap tap(owner, state.frames, state.newestSourceId, state.sequence, budget);

  QCOMPARE(tap.guiLatestFrame(-1).sequence, quint64(0));
  state.capture(2, 55);
  tap.publish();
  QVERIFY(tap.drainForGui());
  QCOMPARE(tap.guiLatestFrame(2).timestampMs, qint64(55));

  state.frames[2].timestampMs = 999;
  tap.publish();
  QVERIFY(tap.drainForGui());
  QCOMPARE(tap.guiLatestFrame(2).timestampMs, qint64(55));

  state.capture(2, 999);
  tap.publish();
  QVERIFY(tap.drainForGui());
  QCOMPARE(tap.guiLatestFrame(2).timestampMs, qint64(999));
}

id TstLatestFrameTap::parseLoadsMirrorTheBudget()
{
  QObject owner;
  CaptureState state;
  DataModel::ParseBudget budget;
  DataModel::LatestFrameTap tap(owner, state.frames, state.newestSourceId, state.sequence, budget);

  QVERIFY(tap.guiParseLoads().empty());

  const auto started = DataModel::ParseBudget::Clock::now();
  (void)budget.account(5, started, started + std::chrono::milliseconds(1));

  tap.publishParseLoads();

  const auto loads = tap.guiParseLoads();
  QCOMPARE(static_cast<int>(loads.size()), 1);
  QCOMPARE(loads.front().sourceId, 5);
  QVERIFY(loads.front().decimateN >= 1);
}

nodiscard]] static OpcUaTag makeTag(const QString& nodeId,
                                      const QString& name,
                                      const IO::Drivers::OpcUaWire::Type type,
                                      const QString& path = QString(),
                                      const int arrayLen  = 1)
{
  OpcUaTag tag;
  tag.nodeId   = nodeId;
  tag.name     = name;
  tag.path     = path;
  tag.type     = type;
  tag.arrayLen = arrayLen;
  return tag;
}

id TstOpcUaProjectBuilder::wireSchemaIsOneEntryPerElement()
{
  const QList<OpcUaTag> tags = {
    makeTag("ns=2;i=1", "Speed", IO::Drivers::OpcUaWire::Type::F64),
    makeTag("ns=2;i=2", "Axes", IO::Drivers::OpcUaWire::Type::I16, QString(), 3),
  };

  const auto schema = OpcUaProjectBuilder(tags).wireSchema();
  QCOMPARE(schema.count(), 4);
  QCOMPARE(schema.at(0).toObject().value(QStringLiteral("i")).toInt(), 0);
  QCOMPARE(schema.at(0).toObject().value(QStringLiteral("t")).toString(), QStringLiteral("f64"));
  QCOMPARE(schema.at(0).toObject().value(QStringLiteral("id")).toString(),
           QStringLiteral("ns=2;i=1"));
  QCOMPARE(schema.at(3).toObject().value(QStringLiteral("i")).toInt(), 3);
  QCOMPARE(schema.at(3).toObject().value(QStringLiteral("t")).toString(), QStringLiteral("i16"));
  QCOMPARE(schema.at(3).toObject().value(QStringLiteral("id")).toString(),
           QStringLiteral("ns=2;i=2"));
}

id TstOpcUaProjectBuilder::wireSchemaStopsAtTheSlotCeiling()
{
  const QList<OpcUaTag> tags = {
    makeTag("ns=2;i=1",
            "Wide",
            IO::Drivers::OpcUaWire::Type::U8,
            QString(),
            IO::Drivers::OpcUaWire::kMaxTags + 16),
  };

  QCOMPARE(OpcUaProjectBuilder(tags).wireSchema().count(), IO::Drivers::OpcUaWire::kMaxTags);
}

id TstOpcUaProjectBuilder::booleanTagsBecomeLedDatasets()
{
  const auto tag = makeTag("ns=2;i=7", "Running", IO::Drivers::OpcUaWire::Type::Bool);
  const auto set = OpcUaProjectBuilder::datasetFor(tag, 0, 1);

  QCOMPARE(set.index, 1);
  QVERIFY(set.led);
  QVERIFY(!set.plt);
  QCOMPARE(set.ledHigh, 1.0);
  QCOMPARE(set.wgtMax, 1.0);
  QCOMPARE(set.title, QStringLiteral("Running"));
}

id TstOpcUaProjectBuilder::numericTagsBecomePlotsWithRanges()
{
  auto tag       = makeTag("ns=2;i=8", "Torque", IO::Drivers::OpcUaWire::Type::F32);
  tag.unit       = QStringLiteral("Nm");
  tag.min        = -5;
  tag.max        = 25;
  const auto set = OpcUaProjectBuilder::datasetFor(tag, 0, 4);

  QVERIFY(set.plt);
  QVERIFY(!set.led);
  QCOMPARE(set.units, QStringLiteral("Nm"));
  QCOMPARE(set.wgtMin, -5.0);
  QCOMPARE(set.wgtMax, 25.0);
  QCOMPARE(set.pltMin, -5.0);
  QCOMPARE(set.pltMax, 25.0);

  const auto plain = OpcUaProjectBuilder::datasetFor(
    makeTag("ns=2;i=9", "Text", IO::Drivers::OpcUaWire::Type::Str), 0, 5);
  QVERIFY(!plain.plt);
  QVERIFY(!plain.led);
}

id TstOpcUaProjectBuilder::arrayElementsCarryIndexedTitles()
{
  const auto array = makeTag("ns=2;i=3", "Axis", IO::Drivers::OpcUaWire::Type::I32, QString(), 3);
  QCOMPARE(OpcUaProjectBuilder::datasetFor(array, 2, 3).title, QStringLiteral("Axis[2]"));

  const auto scalar = makeTag("ns=2;i=4", "Axis", IO::Drivers::OpcUaWire::Type::I32);
  QCOMPARE(OpcUaProjectBuilder::datasetFor(scalar, 0, 1).title, QStringLiteral("Axis"));
}

id TstOpcUaProjectBuilder::projectSkeleton()
{
  const QList<OpcUaTag> tags = {makeTag("ns=2;i=1", "Speed", IO::Drivers::OpcUaWire::Type::F64)};
  const auto project         = OpcUaProjectBuilder(tags).buildProject({});
  const auto source          = projectSource(project);

  QCOMPARE(project.value(Keys::Sources).toArray().count(), 1);
  QCOMPARE(source.value(Keys::SourceId).toInt(), 0);
  QCOMPARE(source.value(Keys::BusType).toInt(), static_cast<int>(SerialStudio::BusType::OpcUa));
  QCOMPARE(source.value(Keys::Decoder).toInt(), static_cast<int>(SerialStudio::Binary));
  QCOMPARE(source.value(Keys::FrameDetection).toInt(),
           static_cast<int>(SerialStudio::NoDelimiters));
  QCOMPARE(source.value(Keys::FrameParserLanguage).toInt(), static_cast<int>(SerialStudio::Native));
  QCOMPARE(source.value(Keys::FrameParserTemplate).toString(), QStringLiteral("opcua"));
  QVERIFY(source.value(Keys::FrameStart).toString().isEmpty());
  QVERIFY(source.value(Keys::FrameEnd).toString().isEmpty());
  QVERIFY(source.value(Keys::FrameParserCode).toString().isEmpty());

  const auto params = source.value(Keys::FrameParserParams).toObject();
  QCOMPARE(params.value(QStringLiteral("schema")).toArray().count(), 1);
}

