  QVERIFY(projectGroups(project).isEmpty());
  QCOMPARE(project.value(Keys::Sources).toArray().count(), 1);
  QVERIFY(OpcUaProjectBuilder({}).wireSchema().isEmpty());
}

id TstPainterEnums::lineCapMapsKnownNames()
