id TstPainterGeometry::sweepKeepsDirection()
{
  constexpr qreal kQuarter = M_PI * 0.5;

  QVERIFY(qAbs(normalizedSweep(0.0, kQuarter, false) - kQuarter) < 1e-9);
  QVERIFY(qAbs(normalizedSweep(0.0, kQuarter, true) - (kQuarter - 2.0 * M_PI)) < 1e-9);
  QVERIFY(qAbs(normalizedSweep(0.0, -kQuarter, false) - (2.0 * M_PI - kQuarter)) < 1e-9);
  QVERIFY(qAbs(normalizedSweep(0.0, -kQuarter, true) + kQuarter) < 1e-9);
  QVERIFY(qAbs(normalizedSweep(1.25, 1.25, false)) < 1e-9);
}

id TstPainterGeometry::sweepSaturatesAtOneTurn()
{
  constexpr qreal kTau = 2.0 * M_PI;

  QVERIFY(qAbs(normalizedSweep(0.0, kTau, false) - kTau) < 1e-9);
  QVERIFY(qAbs(normalizedSweep(0.0, 3.0 * M_PI, false) - kTau) < 1e-9);
  QVERIFY(qAbs(normalizedSweep(0.0, 40.0, false) - kTau) < 1e-9);
  QVERIFY(qAbs(normalizedSweep(0.0, -40.0, true) + kTau) < 1e-9);
}

id TstPainterGeometry::arcRejectsNonPositiveRadius()
{
  QPainterPath path;
  appendArc(path, 10.0, 10.0, 0.0, 0.0, M_PI, false);
  appendArc(path, 10.0, 10.0, -5.0, 0.0, M_PI, false);

  QCOMPARE(path.elementCount(), 0);
}

id TstPainterGeometry::arcLandsOnCanvasEndpoint()
{
  QPainterPath path;
  appendArc(path, 0.0, 0.0, 10.0, 0.0, M_PI * 0.5, false);

  const QPointF end = path.currentPosition();
  QVERIFY(qAbs(end.x()) < 1e-4);
  QVERIFY(qAbs(end.y() - 10.0) < 1e-4);
}

id TstPainterGeometry::arcHonoursDirection()
{
  QPainterPath cw;
  appendArc(cw, 0.0, 0.0, 10.0, 0.0, M_PI * 0.5, false);

  QPainterPath ccw;
  appendArc(ccw, 0.0, 0.0, 10.0, 0.0, M_PI * 0.5, true);

  const QPointF cwEnd  = cw.currentPosition();
  const QPointF ccwEnd = ccw.currentPosition();
  QVERIFY(qAbs(cwEnd.x() - ccwEnd.x()) < 1e-4);
  QVERIFY(qAbs(cwEnd.y() - ccwEnd.y()) < 1e-4);

  QVERIFY2(cw.boundingRect().width() < 12.0, "clockwise quarter arc left its quadrant");
  QVERIFY2(ccw.boundingRect().width() > 15.0, "counter-clockwise arc took the short way round");
}

id TstPainterGeometry::roundRectWithoutRadiiIsAPlainRect()
{
  QPainterPath rounded;
  appendRoundRect(rounded, 5.0, 7.0, 100.0, 50.0, 0.0, 0.0, 0.0, 0.0);

  QPainterPath plain;
  plain.addRect(5.0, 7.0, 100.0, 50.0);

  QCOMPARE(rounded.elementCount(), plain.elementCount());
  QCOMPARE(rounded.boundingRect(), plain.boundingRect());
}

id TstPainterGeometry::roundRectClampsRadiiToHalfTheShortSide()
{
  QPainterPath path;
  appendRoundRect(path, 0.0, 0.0, 100.0, 50.0, 1000.0, 1000.0, 1000.0, 1000.0);

  const QRectF bounds = path.boundingRect();
  QVERIFY(qAbs(bounds.left()) < 0.5);
  QVERIFY(qAbs(bounds.top()) < 0.5);
  QVERIFY(qAbs(bounds.width() - 100.0) < 0.5);
  QVERIFY(qAbs(bounds.height() - 50.0) < 0.5);
}

id TstPainterGeometry::arcToSeedsAnEmptyPath()
{
  QPainterPath path;
  appendArcTo(path, 30.0, 40.0, 90.0, 40.0, 5.0);

  QCOMPARE(path.elementCount(), 1);
  QVERIFY(qAbs(path.currentPosition().x() - 30.0) < 1e-9);
  QVERIFY(qAbs(path.currentPosition().y() - 40.0) < 1e-9);
}

id TstPainterGeometry::arcToRejectsNegativeRadius()
{
  QPainterPath path;
  appendArcTo(path, 30.0, 40.0, 90.0, 40.0, -1.0);

  QCOMPARE(path.elementCount(), 0);
}

id TstPainterGeometry::arcToDegradesToALine()
{
  QPainterPath collinear;
  collinear.moveTo(0.0, 0.0);
  appendArcTo(collinear, 10.0, 0.0, 20.0, 0.0, 5.0);
  QVERIFY(qAbs(collinear.currentPosition().x() - 10.0) < 1e-9);
  QVERIFY(qAbs(collinear.currentPosition().y()) < 1e-9);

  QPainterPath degenerate;
  degenerate.moveTo(10.0, 0.0);
  appendArcTo(degenerate, 10.0, 0.0, 20.0, 0.0, 5.0);
  QVERIFY(qAbs(degenerate.currentPosition().x() - 10.0) < 1e-9);
  QVERIFY(qAbs(degenerate.currentPosition().y()) < 1e-9);

  QPainterPath zeroRadius;
  zeroRadius.moveTo(0.0, 0.0);
  appendArcTo(zeroRadius, 100.0, 0.0, 100.0, 100.0, 0.0);
  QVERIFY(qAbs(zeroRadius.currentPosition().x() - 100.0) < 1e-9);
  QVERIFY(qAbs(zeroRadius.currentPosition().y()) < 1e-9);
}

id TstPainterGeometry::arcToSolvesARightAngleCorner()
{
  QPainterPath path;
  path.moveTo(0.0, 0.0);
  appendArcTo(path, 100.0, 0.0, 100.0, 100.0, 20.0);

  const QPointF end = path.currentPosition();
  QVERIFY2(qAbs(end.x() - 100.0) < 1e-4, "tangent arc missed the outgoing leg");
  QVERIFY2(qAbs(end.y() - 20.0) < 1e-4, "tangent arc ended at the wrong distance from the corner");

  QVERIFY2(path.boundingRect().right() < 100.5, "tangent arc overshot the corner");
}

id TstPainterGeometry::ellipseRejectsNonPositiveRadii()
{
  QPainterPath path;
  appendEllipse(path, 0.0, 0.0, 0.0, 10.0, 0.0, 0.0, 2.0 * M_PI, false);
  appendEllipse(path, 0.0, 0.0, 10.0, -1.0, 0.0, 0.0, 2.0 * M_PI, false);

  QCOMPARE(path.elementCount(), 0);
}

id TstPainterGeometry::ellipseRotatesItsBoundingBox()
{
  QPainterPath flat;
  appendEllipse(flat, 0.0, 0.0, 20.0, 10.0, 0.0, 0.0, 2.0 * M_PI, false);

  QPainterPath upright;
  appendEllipse(upright, 0.0, 0.0, 20.0, 10.0, M_PI * 0.5, 0.0, 2.0 * M_PI, false);

  QVERIFY2(flat.boundingRect().width() > flat.boundingRect().height(),
           "unrotated ellipse lost its major axis");
  QVERIFY2(upright.boundingRect().height() > upright.boundingRect().width(),
           "quarter-turn rotation did not swap the axes");
}

[[nodiscard]] UI::ReplaySeekBindings bindings()
  {
    return UI::ReplaySeekBindings{.xAxisData          = xAxisData,
                                  .yAxisData          = yAxisData,
                                  .plotTimeRings      = plotTimeRings,
                                  .multiplotTimeRings = multiplotTimeRings,
                                  .multiplotValues    = multiplotValues,
                                  .datasets           = datasets,
                                  .widgetGroups       = widgetGroups,
                                  .widgetDatasets     = widgetDatasets};
  }

DataModel::Dataset makeDataset(int sourceId, int uniqueId, int xAxisId = DataModel::kXAxisTime)
{
  DataModel::Dataset ds;
  ds.sourceId = sourceId;
  ds.uniqueId = uniqueId;
  ds.xAxisId  = xAxisId;
  return ds;
}

DataModel::Group makeGroup(int sourceId, int uniqueId, const std::vector<int>& datasetIds)
{
  DataModel::Group group;
  group.sourceId = sourceId;
  group.uniqueId = uniqueId;
  for (const int id : datasetIds)
    group.datasets.push_back(makeDataset(sourceId, id));

  return group;
}

void ReplaySeekEngineTest::keysAreSourceQualified()
{
  QCOMPARE(UI::ReplaySeekEngine::seekKey(0, 7), static_cast<qint64>(7));
  QVERIFY(UI::ReplaySeekEngine::seekKey(0, 7) != UI::ReplaySeekEngine::seekKey(1, 7));
  QVERIFY(UI::ReplaySeekEngine::seekKey(2, -1) != UI::ReplaySeekEngine::seekKey(3, -1));
}

void ReplaySeekEngineTest::seriesListsPlotsXSourcesAndCurves()
{
  Stores stores;
  stores.datasets.insert(12, makeDataset(1, 12));
  stores.widgetDatasets[SerialStudio::DashboardPlot] = {
    makeDataset(0, 10), makeDataset(0, 11, 12), makeDataset(0, 10)};
  stores.widgetGroups[SerialStudio::DashboardMultiPlot] = {makeGroup(2, 30, {20, 21})};

  UI::ReplaySeekEngine engine(stores.bindings());
  const auto pairs = engine.seekSeries();

  const QList<std::pair<int, int>> expected{
    {0, 10},
    {0, 11},
    {1, 12},
    {2, 20},
    {2, 21}
  };

  QCOMPARE(pairs.size(), 5);
  QVERIFY(pairs == expected);
}

void ReplaySeekEngineTest::emptyWindowIsRejected()
{
  Stores stores;
  UI::ReplaySeekEngine engine(stores.bindings());

  QVERIFY(!engine.bulkLoadPlotWindow({}, {}));
}

void ReplaySeekEngineTest::timeRingsAreClearedAndNormalized()
{
  Stores stores;
  stores.widgetDatasets[SerialStudio::DashboardPlot] = {makeDataset(0, 10)};
  stores.plotTimeRings.insert(0, DSP::EnvelopeRing(64, 1.0));
  stores.plotTimeRings[0].appendDecimated(500.0, 1.0);
  stores.plotTimeRings[0].appendDecimated(501.0, 2.0);

  QHash<qint64, QVector<double>> series;
  series.insert(UI::ReplaySeekEngine::seekKey(0, 10), {5.0, 6.0, 7.0, 8.0});

  UI::ReplaySeekEngine engine(stores.bindings());
  QVERIFY(engine.bulkLoadPlotWindow({10.0, 11.0, 12.0, 13.0}, series));

  const auto& ring = stores.plotTimeRings[0];
  QVERIFY(ring.level0.time.size() > 0);
  for (std::size_t i = 0; i < ring.level0.time.size(); ++i) {
    QVERIFY(ring.level0.time[i] <= 0.0);
    QVERIFY(ring.level0.time[i] >= -3.0);
  }
}

void ReplaySeekEngineTest::sampleRingsCarryXAndYSources()
{
  Stores stores;
  stores.datasets.insert(12, makeDataset(1, 12));
  stores.widgetDatasets[SerialStudio::DashboardPlot] = {makeDataset(0, 11, 12)};
  stores.yAxisData.insert(11, DSP::AxisData(16));
  stores.xAxisData.insert(12, DSP::AxisData(16));

  QHash<qint64, QVector<double>> series;
  series.insert(UI::ReplaySeekEngine::seekKey(0, 11), {1.0, 2.0, 3.0});
  series.insert(UI::ReplaySeekEngine::seekKey(1, 12), {7.0, 8.0, 9.0});

  UI::ReplaySeekEngine engine(stores.bindings());
  QVERIFY(engine.bulkLoadPlotWindow({0.0, 1.0, 2.0}, series));

  QCOMPARE(stores.yAxisData[11].size(), static_cast<std::size_t>(3));
  QCOMPARE(stores.xAxisData[12].size(), static_cast<std::size_t>(3));
  QCOMPARE(stores.yAxisData[11][2], 3.0);
  QCOMPARE(stores.xAxisData[12][0], 7.0);
}

void ReplaySeekEngineTest::multiplotCurvesFillTheirOwnRings()
{
  Stores stores;
  stores.widgetGroups[SerialStudio::DashboardMultiPlot] = {makeGroup(3, 30, {20, 21})};

  std::vector<DSP::EnvelopeRing> rings;
  rings.push_back(DSP::EnvelopeRing(64, 1.0));
  rings.push_back(DSP::EnvelopeRing(64, 1.0));
  stores.multiplotTimeRings.insert(0, std::move(rings));

  QHash<qint64, QVector<double>> series;
  series.insert(UI::ReplaySeekEngine::seekKey(3, 20), {1.0, 2.0, 3.0, 4.0});
  series.insert(UI::ReplaySeekEngine::seekKey(3, 21), {5.0, 6.0, 7.0, 8.0});

  UI::ReplaySeekEngine engine(stores.bindings());
  QVERIFY(engine.bulkLoadPlotWindow({0.0, 1.0, 2.0, 3.0}, series));

  QCOMPARE(stores.multiplotTimeRings[0].size(), static_cast<std::size_t>(2));
  QVERIFY(stores.multiplotTimeRings[0][0].level0.time.size() > 0);
  QVERIFY(stores.multiplotTimeRings[0][1].level0.time.size() > 0);
}

void ReplaySeekEngineTest::restoreReturnsRingsToTheirOwnPlot()
{
  Stores stores;
  stores.widgetDatasets[SerialStudio::DashboardPlot] = {makeDataset(0, 10), makeDataset(1, 10)};
  stores.plotTimeRings.insert(0, DSP::EnvelopeRing(64, 1.0));
  stores.plotTimeRings.insert(1, DSP::EnvelopeRing(64, 1.0));

  QHash<qint64, QVector<double>> series;
  series.insert(UI::ReplaySeekEngine::seekKey(0, 10), {1.0, 1.0, 1.0, 1.0});
  series.insert(UI::ReplaySeekEngine::seekKey(1, 10), {9.0, 9.0, 9.0, 9.0});

  UI::ReplaySeekEngine engine(stores.bindings());
  QVERIFY(engine.bulkLoadPlotWindow({0.0, 1.0, 2.0, 3.0}, series));

  auto snapshot = engine.snapshotPlotTimeRings();
  QCOMPARE(snapshot.size(), 2);

  stores.plotTimeRings[0] = DSP::EnvelopeRing(64, 1.0);
  stores.plotTimeRings[1] = DSP::EnvelopeRing(64, 1.0);
  QCOMPARE(stores.plotTimeRings[0].level0.time.size(), static_cast<std::size_t>(0));

  engine.restorePlotTimeRings(snapshot);

  QVERIFY(snapshot.isEmpty());
  QVERIFY(stores.plotTimeRings[0].level0.value.size() > 0);
  QVERIFY(stores.plotTimeRings[1].level0.value.size() > 0);
  QCOMPARE(stores.plotTimeRings[0].level0.value[0], 1.0);
  QCOMPARE(stores.plotTimeRings[1].level0.value[0], 9.0);
}

atic void primeStore(DataModel::DataTableStore& store)
{
  DataModel::Dataset dataset;
  dataset.uniqueId = kDatasetId;

  DataModel::Group group;
  group.datasets.push_back(dataset);

  DataModel::Frame templateFrame;
  templateFrame.groups.push_back(group);

  store.initialize({}, {}, templateFrame);
}

id TstTableSnapshotChannel::drainStaysIdleUntilArmed()
{
  QObject owner;
  DataModel::DataTableStore store;
  DataModel::TableSnapshotChannel channel(owner, store);

  primeStore(store);

  QVERIFY(!channel.drainForGui());
  QVERIFY(!channel.guiSnapshot());
}

id TstTableSnapshotChannel::requestIsLatchedUntilPublished()
{
  QObject owner;
  DataModel::DataTableStore store;
  DataModel::TableSnapshotChannel channel(owner, store);

  primeStore(store);
  channel.noteGuiUser();

  QVERIFY(channel.drainForGui());
  QVERIFY(!channel.drainForGui());

  channel.publish();
  QVERIFY(channel.drainForGui());
}

id TstTableSnapshotChannel::publishedSnapshotReachesTheGui()
{
  QObject owner;
  DataModel::DataTableStore store;
  DataModel::TableSnapshotChannel channel(owner, store);

  primeStore(store);
  channel.noteGuiUser();
  store.setDatasetFinal(kDatasetId, 42.0, QStringLiteral("42"), true);

  channel.publish();
  QVERIFY(channel.drainForGui());

  const auto snapshot = channel.guiSnapshot();
  QVERIFY(snapshot);

  const auto* value = snapshot->getDatasetFinal(kDatasetId);
  QVERIFY(value != nullptr);
  QCOMPARE(value->numericValue, 42.0);
}

id TstTableSnapshotChannel::unchangedStoreDoesNotRepublish()
{
  QObject owner;
  DataModel::DataTableStore store;
  DataModel::TableSnapshotChannel channel(owner, store);

  primeStore(store);
  channel.noteGuiUser();
  store.setDatasetFinal(kDatasetId, 1.0, QStringLiteral("1"), true);

  channel.publish();
  QVERIFY(channel.drainForGui());

  const auto first = channel.guiSnapshot();
  QVERIFY(first);

  channel.publish();
  QVERIFY(channel.drainForGui());
  QCOMPARE(channel.guiSnapshot().get(), first.get());
}

id TstTableSnapshotChannel::slotsAreRecycled()
{
  QObject owner;
  DataModel::DataTableStore store;
  DataModel::TableSnapshotChannel channel(owner, store);

  primeStore(store);
  channel.noteGuiUser();

  QSet<const void*> seen;
  for (int i = 0; i < 64; ++i) {
    store.setDatasetFinal(kDatasetId, static_cast<double>(i), QString::number(i), true);
    channel.publish();
    QVERIFY(channel.drainForGui());
    QVERIFY(channel.guiSnapshot());
    seen.insert(channel.guiSnapshot().get());
  }

  QVERIFY(seen.size() <= 8);

  const auto* newest = channel.guiSnapshot()->getDatasetFinal(kDatasetId);
  QVERIFY(newest != nullptr);
  QCOMPARE(newest->numericValue, 63.0);
}

atic void feed(Widgets::TerminalBuffer& buffer, const QString& data)
{
  QString text;
  int pos       = 0;
  const int len = data.size();

  while (pos < len) {
    const int runStart = pos;
    pos                = Widgets::TerminalBuffer::scanPrintableRun(data, pos);

    if (pos > runStart)
      text.append(QStringView(data).mid(runStart, pos - runStart));

    if (pos < len) {
      (void)buffer.processText(data[pos], text, false);
      ++pos;
    }
  }

  buffer.appendText(text);
}

id TstTerminalBuffer::scanPrintableRun_data()
{
  QTest::addColumn<QString>("data");
  QTest::addColumn<int>("expected");

  QTest::newRow("all printable") << QStringLiteral("hello") << 5;
  QTest::newRow("stops at newline") << QStringLiteral("ab\ncd") << 2;
  QTest::newRow("stops at carriage return") << QStringLiteral("ab\rcd") << 2;
  QTest::newRow("stops at escape") << QStringLiteral("ab\x1b[0m") << 2;
  QTest::newRow("stops at backspace") << QStringLiteral("ab\bcd") << 2;
  QTest::newRow("stops at tab") << QStringLiteral("ab\tcd") << 2;
  QTest::newRow("stops at delete") << QStringLiteral("ab\x7f") << 2;
  QTest::newRow("stops at bell") << QStringLiteral("ab\acd") << 2;
  QTest::newRow("leading control byte") << QStringLiteral("\nab") << 0;
  QTest::newRow("empty") << QString() << 0;
}

