QString DataModel::DBCImporter::muxTitleSuffix(const QList<MuxSpec>& gates)
{
  QStringList conditions;
  for (const auto& gate : gates) {
    QStringList values;
    for (const auto& range : gate.ranges)
      values.append(range.lo == range.hi ? QString::number(range.lo)
                                         : QStringLiteral("%1-%2").arg(QString::number(range.lo),
                                                                       QString::number(range.hi)));

    const auto joined = values.join(QLatin1Char(','));
    conditions.append(gates.size() > 1 ? QStringLiteral("%1=%2").arg(gate.parent, joined) : joined);
  }

  return conditions.join(QLatin1Char('/'));
}

QString DataModel::DBCImporter::datasetTitle(const OrderedSignal& entry)
{
  auto name       = entry.signal.name();
  const auto gate = muxTitleSuffix(entry.gates);

  if (entry.role == MuxRole::Selector && gate.isEmpty())
    return QString("%1 (selector)").arg(name);

  if (entry.role == MuxRole::Selector)
    return QString("%1 (selector, mux %2)").arg(name, gate);

  if (!gate.isEmpty())
    return QString("%1 (mux %2)").arg(name, gate);

  return name;
}

void DataModel::DBCImporter::appendResolved(const OrderedSignal& entry,
                                            QList<OrderedSignal>& ordered,
                                            QList<OrderedSignal>& pending,
                                            QSet<QString>& resolved)
{
  if (!gatesResolved(entry.gates, resolved)) {
    pending.append(entry);
    return;
  }

  if (entry.role == MuxRole::Selector)
    resolved.insert(entry.signal.name());

  ordered.append(entry);
}

QString DataModel::DBCImporter::rootSelectorName(const QList<OrderedSignal>& entries)
{
  for (const auto& entry : entries)
    if (entry.role == MuxRole::Selector && entry.gates.isEmpty())
      return entry.signal.name();

  return QString();
}

QString DataModel::DBCImporter::muxSpecField(const OrderedSignal& entry,
                                             const QString& rootSelector)
{
  qint64 value = 0;
  if (entry.role != MuxRole::Selector && simpleMuxValue(entry.gates, rootSelector, value))
    return QStringLiteral(", mux = %1").arg(value);

  QStringList conditions;
  for (const auto& gate : entry.gates) {
    QStringList ranges;
    for (const auto& range : gate.ranges)
      ranges.append(
        QStringLiteral("{%1, %2}").arg(QString::number(range.lo), QString::number(range.hi)));

    conditions.append(QStringLiteral("{p = %1, r = {%2}}")
                        .arg(luaQuote(gate.parent), ranges.join(QStringLiteral(", "))));
  }

  if (conditions.size() == 1)
    return QStringLiteral(", mux = %1").arg(conditions.constFirst());

  return QStringLiteral(", mux = {%1}").arg(conditions.join(QStringLiteral(", ")));
}

DataModel::DBCImporter::MuxRole DataModel::DBCImporter::classifyMux(
  const QCanSignalDescription& signal, QList<MuxSpec>& outGates)
{
  outGates.clear();
  const auto state = signal.multiplexState();
  if (state == QtCanBus::MultiplexState::None)
    return MuxRole::Plain;
  const bool selector = (state == QtCanBus::MultiplexState::MultiplexorSwitch
                         || state == QtCanBus::MultiplexState::SwitchAndSignal);
  if (signal.multiplexSignals().isEmpty())
    return selector ? MuxRole::Selector : MuxRole::Plain;
  if (!buildMuxGates(signal, outGates))
  return selector ? MuxRole::Selector : MuxRole::Muxed;
 * @brief Returns the total number of importable signals (excludes the ones whose multiplexing
 *        could not be resolved).
  for (const auto& message : messages)
    count += static_cast<int>(orderedSignals(message).size());

void DataModel::ProjectEditor::buildMqttSparkplugSection(const MQTT::Publisher& pub, bool enabled)
{
  auto* sparkplugHdr = new QStandardItem();
  sparkplugHdr->setData(SectionHeader, WidgetType);
  sparkplugHdr->setData(tr("Sparkplug"), PlaceholderValue);
  static auto& registry = Misc::IconRegistry::instance();
  sparkplugHdr->setData(registry.iconById(QStringLiteral("editor/mqtt-publisher"), 16),
                        ParameterIcon);
  m_mqttPublisherModel->appendRow(sparkplugHdr);

  auto* sparkplugItem = new QStandardItem();
  sparkplugItem->setEditable(true);
  sparkplugItem->setData(enabled, Active);
  sparkplugItem->setData(CheckBox, WidgetType);
  sparkplugItem->setData(pub.sparkplugEnabled(), EditableValue);
  sparkplugItem->setData(kMqttPublisher_SparkplugEnabled, ParameterType);
  sparkplugItem->setData(tr("Publish as Edge Node"), ParameterName);
  sparkplugItem->setData(tr("Publish datasets in the Sparkplug B namespace instead of the payload "
                            "selected above, with birth, death and rebirth handling"),
                         ParameterDescription);
  m_mqttPublisherModel->appendRow(sparkplugItem);

  if (!pub.sparkplugEnabled())
    return;

  auto* groupItem = new QStandardItem();
  groupItem->setEditable(true);
  groupItem->setData(enabled, Active);
  groupItem->setData(TextField, WidgetType);
  groupItem->setData(pub.sparkplugGroupId(), EditableValue);
  groupItem->setData(kMqttPublisher_SparkplugGroupId, ParameterType);
  groupItem->setData(tr("Group ID"), ParameterName);
  groupItem->setData(tr("Plant1"), PlaceholderValue);
  groupItem->setData(tr("Logical group this edge node belongs to"), ParameterDescription);
  m_mqttPublisherModel->appendRow(groupItem);

  auto* nodeItem = new QStandardItem();
  nodeItem->setEditable(true);
  nodeItem->setData(enabled, Active);
  nodeItem->setData(TextField, WidgetType);
  nodeItem->setData(pub.sparkplugEdgeNodeId(), EditableValue);
  nodeItem->setData(kMqttPublisher_SparkplugEdgeNode, ParameterType);
  nodeItem->setData(tr("Edge Node ID"), ParameterName);
  nodeItem->setData(tr("SerialStudio"), PlaceholderValue);
  nodeItem->setData(tr("Identifies this node inside the group"), ParameterDescription);
  m_mqttPublisherModel->appendRow(nodeItem);

  auto* deviceItem = new QStandardItem();
  deviceItem->setEditable(true);
  deviceItem->setData(enabled, Active);
  deviceItem->setData(TextField, WidgetType);
  deviceItem->setData(pub.sparkplugDeviceId(), EditableValue);
  deviceItem->setData(kMqttPublisher_SparkplugDevice, ParameterType);
  deviceItem->setData(tr("Device ID"), ParameterName);
  deviceItem->setData(tr("Optional"), PlaceholderValue);
  deviceItem->setData(tr("When set, datasets are published as a device of this node"),
                      ParameterDescription);
  m_mqttPublisherModel->appendRow(deviceItem);
}

static bool applyMqttSparkplugEdit(MQTT::Publisher& pub, int type, const QVariant& value)
{
  switch (type) {
    case kMqttPublisher_SparkplugGroupId:
      pub.setSparkplugGroupId(value.toString());
      return true;
    case kMqttPublisher_SparkplugEdgeNode:
      pub.setSparkplugEdgeNodeId(value.toString());
      return true;
    case kMqttPublisher_SparkplugDevice:
      pub.setSparkplugDeviceId(value.toString());
      return true;
    default:
      return false;
  }
}

bool DataModel::ProjectEditor::selectInfluxSinkItem(QStandardItem* item)
{
  if (item != m_influxSinkItem || item == nullptr)
    return false;

  setCurrentView(InfluxSinkView);
  return true;
}

void DataModel::ProjectEditor::selectInfluxSink()
{
  if (!m_selectionModel || !m_influxSinkItem)
    return;

  m_selectionModel->setCurrentIndex(m_influxSinkItem->index(), QItemSelectionModel::ClearAndSelect);
}

void DataModel::ProjectEditor::appendInfluxSinkTreeItem(QStandardItem* root)
{
  SS_ASSERT(root != nullptr, return);

  const QString q         = m_treeSearchQuery.trimmed();
  const bool filterActive = !q.isEmpty();
  if (filterActive && !SerialStudio::searchMatches(q, tr("InfluxDB Sink")))
    return;

  static auto& registry = Misc::IconRegistry::instance();
  auto* item            = new QStandardItem(tr("InfluxDB Sink"));
  item->setData(tr("InfluxDB Sink"), TreeViewText);
  item->setData(registry.icon(QStringLiteral("editor"), QStringLiteral("influx"), 16),
                TreeViewIcon);
  item->setData(-1, TreeViewFrameIndex);
  item->setData(KindInfluxSink, TreeItemKind);
  item->setData(-1, TreeItemId);
  item->setData(-1, TreeItemParentId);

  root->appendRow(item);
  m_influxSinkItem = item;
}

void DataModel::ProjectModel::loadSinkConfigs(const QJsonObject& json)
{

  m_influxSink = json.value(Keys::InfluxSink).toObject();
  Q_EMIT influxSinkChanged();

void DataModel::ProjectModel::setInfluxSink(const QJsonObject& config)
{
  if (m_influxSink == config)
    return;

  const ProjectUndoScope undo_scope{*this, tr("Change InfluxDB Sink")};

  m_influxSink = config;
  setModified(true);
  Q_EMIT influxSinkChanged();
}

void DataModel::ProjectModel::emitSinkConfigResets(bool hadMqttPublisher, bool hadInfluxSink)
{
  if (hadMqttPublisher)
    Q_EMIT mqttPublisherChanged();

  if (hadInfluxSink)
    Q_EMIT influxSinkChanged();
}

explicit WireLatchParser(int count) : NativeLatchParser(count)
  {
    SS_ASSERT_LOG(count > 0);
    SS_ASSERT_LOG(count <= IO::Drivers::OpcUaWire::kMaxTags);
  }

void walkEntries(const QByteArray& frame, Route&& route)
  {
    using namespace IO::Drivers::OpcUaWire;
    SS_ASSERT_LOG(latchCount() > 0);

    const QByteArrayView view(frame.constData(), qMin<qsizetype>(frame.size(), kMaxWireFrameBytes));
    if (!checkHeader(view))
      return;

    qsizetype pos = kHeaderBytes;
    Entry entry;
    for (int n = 0; n < kMaxTags && pos < view.size(); ++n) {
      if (!readEntry(view, pos, entry))
        break;

      SS_ASSERT_LOG(entry.index >= 0);
      route(entry);
    }
  }

explicit TypedWireParser(const QList<IO::Drivers::OpcUaWire::Type>& schema)
    : WireLatchParser(static_cast<int>(schema.size())), m_schema(schema)
  {
    SS_ASSERT_LOG(!m_schema.isEmpty());
    SS_ASSERT_LOG(m_schema.size() <= IO::Drivers::OpcUaWire::kMaxTags);
  }

[[nodiscard]] QList<QStringList> parseBinary(const QByteArray& frame) override
  {
    SS_ASSERT(!m_schema.isEmpty(), return latchedFrame());
    SS_ASSERT_LOG(m_schema.size() == latchCount());

    walkEntries(frame, [this](const IO::Drivers::OpcUaWire::Entry& entry) {
      if (entry.index < 0 || entry.index >= m_schema.size())
        return;

      if (m_schema.at(entry.index) == entry.type)
        storeAt(entry.index, entry.text);
    });

    return latchedFrame();
  }

explicit NamedWireParser(int count) : WireLatchParser(count)
  {
    SS_ASSERT_LOG(count > 0);
    SS_ASSERT_LOG(count <= IO::Drivers::OpcUaWire::kMaxTags);
  }

[[nodiscard]] QList<QStringList> parseBinary(const QByteArray& frame) override
  {
    SS_ASSERT(latchCount() > 0, return latchedFrame());
    SS_ASSERT_LOG(latchCount() <= IO::Drivers::OpcUaWire::kMaxTags);

    walkEntries(frame, [this](const IO::Drivers::OpcUaWire::Entry& entry) {
      if (entry.index >= 0 && entry.index < latchCount())
        storeAt(entry.index, entry.text);
    });

    return latchedFrame();
  }

[[nodiscard]] static int namedSchemaCount(const QJsonObject& params,
                                          const char* emptyMessage,
                                          QString& error)
{
  using namespace IO::Drivers::OpcUaWire;

  const auto items = DataModel::nativeParamArray(params, QStringLiteral("schema"));
  if (items.isEmpty() || items.size() > kMaxTags) {
    error = trWire(emptyMessage).arg(kMaxTags);
    return -1;
  }

  QList<bool> seen(items.size(), false);
  for (const auto& item : items) {
    const auto obj  = item.toObject();
    const int index = obj.value(QStringLiteral("index")).toInt(-1);
    if (index < 0 || index >= seen.size() || seen[index]) {
      error = trWire("The channel schema has an invalid, duplicate or missing index.");
      return -1;
    }

    seen[index] = true;
  }

  SS_ASSERT_LOG(!items.isEmpty());
  return static_cast<int>(items.size());
}

[[nodiscard]] QString description() const override
  {
    return trWire("Decodes the OPC UA driver's tag update frames into one latched channel "
                  "per subscribed tag. Generated with the OPC UA project; use with the "
                  "Binary decoder.");
  }

[[nodiscard]] QList<NativeParamSpec> params() const override
  {
    auto schema = DataModel::nativeParam(
      "schema",
      NativeParamType::Json,
      QT_TRANSLATE_NOOP("NativeTemplates", "Tag schema"),
      QT_TRANSLATE_NOOP("NativeTemplates",
                        "Ordered tag list written by the OPC UA project generator: one "
                        "{\"i\": index, \"t\": type} entry per channel."),
      QJsonArray());
    return {schema};
  }

[[nodiscard]] std::unique_ptr<INativeParser> makeParser(const QJsonObject& params,
                                                          QString& error) const override
  {
    using namespace IO::Drivers::OpcUaWire;

    const auto items = DataModel::nativeParamArray(params, QStringLiteral("schema"));
    if (items.isEmpty() || items.size() > kMaxTags) {
      error = trWire("The tag schema must list between 1 and %1 tags.").arg(kMaxTags);
      return nullptr;
    }

    QList<Type> schema(items.size(), Type::Invalid);
    for (const auto& item : items) {
      const auto obj  = item.toObject();
      const int index = obj.value(QStringLiteral("i")).toInt(-1);
      const auto type = typeFromCode(obj.value(QStringLiteral("t")).toString());
      if (index < 0 || index >= schema.size() || type == Type::Invalid
          || schema[index] != Type::Invalid) {
        error = trWire("The tag schema has an invalid, duplicate or missing index.");
        return nullptr;
      }

      schema[index] = type;
    }

    return std::make_unique<TypedWireParser>(schema);
  }

