[[nodiscard]] static std::unique_ptr<IO::HAL_Driver> makePlcDriver(Driver* uiDriver)
{
  const auto& tk = Licensing::CommercialToken::current();
  if (!tk.isValid() || !SS_LICENSE_GUARD())
    return nullptr;

  auto driver = std::make_unique<Driver>();
  driver->setPersistent(false);
  if (!uiDriver)
    return driver;

  uiDriver->setSessionPeer(driver.get());
  QObject::connect(
    driver.get(), &Driver::statusChanged, uiDriver, &Driver::statusChanged, Qt::UniqueConnection);
  return driver;
}

static QByteArray serializeCanFrame(const quint32 can_id,
                                    const bool extended,
                                    const QByteArray& payload)
{
  QByteArray data;
  data.reserve(extended ? 13 : 11);

  if (extended) {
    data.append(static_cast<char>(0x80 | ((can_id >> 24) & 0x1F)));
    data.append(static_cast<char>((can_id >> 16) & 0xFF));
  }

  data.append(static_cast<char>((can_id >> 8) & 0xFF));
  data.append(static_cast<char>(can_id & 0xFF));
  data.append(static_cast<char>(static_cast<quint8>(payload.size())));
  data.append(payload);

  const qsizetype min_size = extended ? 13 : 11;
  while (data.size() < min_size)
    data.append(static_cast<char>(0));

  return data;
}

static QVariantMap reassemblyCountersMap(const IO::Drivers::CanReassemblyCounters& counters)
{
  QVariantMap map;
  map.insert(QStringLiteral("aborted"), static_cast<qulonglong>(counters.aborted));
  map.insert(QStringLiteral("timeouts"), static_cast<qulonglong>(counters.timeouts));
  map.insert(QStringLiteral("completed"), static_cast<qulonglong>(counters.completed));
  map.insert(QStringLiteral("malformed"), static_cast<qulonglong>(counters.malformed));
  map.insert(QStringLiteral("sizeOverruns"), static_cast<qulonglong>(counters.sizeOverruns));
  map.insert(QStringLiteral("sequenceErrors"), static_cast<qulonglong>(counters.sequenceErrors));
  map.insert(QStringLiteral("sessionOverruns"), static_cast<qulonglong>(counters.sessionOverruns));
  return map;
}

QVariantMap IO::Drivers::CANBus::reassemblyCounters() const
{
  QVariantMap map;
  map.insert(QStringLiteral("enabled"), m_tpReassembly);
  map.insert(QStringLiteral("j1939"), reassemblyCountersMap(m_j1939.counters()));
  map.insert(QStringLiteral("isotp"), reassemblyCountersMap(m_isoTp.counters()));
  map.insert(QStringLiteral("j1939Sessions"), m_j1939.activeSessions());
  map.insert(QStringLiteral("isotpSessions"), m_isoTp.activeSessions());
  return map;
}

void IO::Drivers::CANBus::setTpReassembly(const bool enabled)
{
  if (m_tpReassembly == enabled)
    return;

  m_tpReassembly = enabled;
  m_settings.setValue("CanBusDriver/tpReassembly", enabled);

  m_j1939.reset();
  m_isoTp.reset();

  Q_EMIT tpReassemblyChanged();
}

bool IO::Drivers::CANBus::routeReassembly(const quint32 can_id,
                                          const bool extended,
                                          const QByteArray& payload,
                                          const CapturedData::SteadyTimePoint stamp)
{
  SS_ASSERT(m_tpReassembly, return false);
  SS_ASSERT_LOG(payload.size() <= 64);

  if (extended && J1939TransportReassembler::isTransportFrame(can_id)) {
    const auto done = m_j1939.feed(can_id, payload, stamp);
    if (done.has_value()) {
      const quint32 id = (static_cast<quint32>(done->priority & 0x07u) << 26)
                       | ((done->pgn & 0x3FFFFu) << 8) | done->sourceAddr;
      publishReassembled(id, done->bytes, done->firstSeen);
    }

    return true;
  }

  if (!IsoTpReassembler::isDiagnosticId(can_id, extended))
    return false;

  if (!IsoTpReassembler::isMultiFrame(payload))
    return false;

  const auto done = m_isoTp.feed(can_id, extended, payload, stamp);
  if (done.has_value())
    publishReassembled(done->canId, done->bytes, done->firstSeen);

  return true;
}

void IO::Drivers::CANBus::publishReassembled(const quint32 can_id,
                                             const QByteArray& payload,
                                             const CapturedData::SteadyTimePoint stamp)
{
  SS_ASSERT(!payload.isEmpty(), return);
  SS_ASSERT_LOG(can_id <= 0x1FFFFFFFu);

  QByteArray data;
  data.reserve(payload.size() + 5);
  data.append(static_cast<char>(0x80 | ((can_id >> 24) & 0x1F)));
  data.append(static_cast<char>((can_id >> 16) & 0xFF));
  data.append(static_cast<char>((can_id >> 8) & 0xFF));
  data.append(static_cast<char>(can_id & 0xFF));
  data.append(static_cast<char>(kLongFrameDlcMarker));
  data.append(payload);

  publishReceivedData(std::move(data), stamp);
}

int32 IO::Drivers::J1939TransportReassembler::parameterGroupNumber(const quint32 id29) noexcept
{
  const quint32 data_page = (id29 >> 24) & 0x03u;
  const quint32 format    = (id29 >> 16) & 0xFFu;

  if (format < 240)
    return (data_page << 16) | (format << 8);

  return (data_page << 16) | (format << 8) | ((id29 >> 8) & 0xFFu);
}

ol IO::Drivers::J1939TransportReassembler::isTransportFrame(const quint32 id29) noexcept
{
  const quint32 pgn = parameterGroupNumber(id29);
  return pgn == kTpCmPgn || pgn == kTpDtPgn;
}

int16 IO::Drivers::J1939TransportReassembler::sessionKey(const quint8 source,
                                                           const quint8 destination) noexcept
{
  return static_cast<quint16>((static_cast<quint16>(source) << 8) | destination);
}

id IO::Drivers::J1939TransportReassembler::reset()
{
  SS_ASSERT_LOG(m_sessions.size() <= kMaxSessions);

  m_sessions.clear();
  m_counters = CanReassemblyCounters();

  SS_ASSERT_LOG(m_sessions.isEmpty());
}

nst IO::Drivers::CanReassemblyCounters& IO::Drivers::J1939TransportReassembler::counters()
  const noexcept
{
  return m_counters;
}

d::optional<IO::Drivers::J1939TransportReassembler::Completed> IO::Drivers::
  J1939TransportReassembler::feed(const quint32 id29,
                                  const QByteArrayView payload,
                                  const SteadyTimePoint stamp)
{
  SS_ASSERT(m_sessions.size() <= kMaxSessions, return std::nullopt);
  SS_ASSERT_LOG(payload.size() <= 64);

  const quint32 pgn = parameterGroupNumber(id29);
  if (pgn != kTpCmPgn && pgn != kTpDtPgn)
    return std::nullopt;

  evictExpired(stamp);

  if (payload.size() < 8) {
    ++m_counters.malformed;
    return std::nullopt;
  }

  const quint8 source      = static_cast<quint8>(id29 & 0xFFu);
  const quint8 destination = static_cast<quint8>((id29 >> 8) & 0xFFu);

  if (pgn == kTpDtPgn)
    return handleDataTransfer(source, destination, payload, stamp);

  const quint8 priority = static_cast<quint8>((id29 >> 26) & 0x07u);
  handleConnectionManagement(source, destination, priority, payload, stamp);
  return std::nullopt;
}

id IO::Drivers::J1939TransportReassembler::handleConnectionManagement(
  const quint8 source,
  const quint8 destination,
  const quint8 priority,
  const QByteArrayView payload,
  const SteadyTimePoint stamp)
{
  SS_ASSERT(payload.size() >= 8, {
    ++m_counters.malformed;
    return;
  });
  SS_ASSERT_LOG(m_sessions.size() <= kMaxSessions);

  const quint8 control = static_cast<quint8>(payload.at(0));

  if (control == kCmAbort) {
    dropSession(sessionKey(source, destination), m_counters.aborted);
    dropSession(sessionKey(destination, source), m_counters.aborted);
    return;
  }

  if (control == kCmClearToSend || control == kCmEndOfMessageAck) {
    const auto peer = m_sessions.find(sessionKey(destination, source));
    if (peer != m_sessions.end())
      peer->lastSeen = stamp;

    return;
  }

  if (control != kCmBroadcastAnnounce && control != kCmRequestToSend)
    return;

  openSession(sessionKey(source, destination), priority, payload, stamp);
}

id IO::Drivers::J1939TransportReassembler::openSession(const quint16 key,
                                                         const quint8 priority,
                                                         const QByteArrayView payload,
                                                         const SteadyTimePoint stamp)
{
  SS_ASSERT(payload.size() >= 8, {
    ++m_counters.malformed;
    return;
  });
  SS_ASSERT_LOG(m_sessions.size() <= kMaxSessions);

  dropSession(key, m_counters.aborted);

  const int total_bytes = static_cast<quint8>(payload.at(1))
                        | (static_cast<int>(static_cast<quint8>(payload.at(2))) << 8);
  const int total_packets = static_cast<quint8>(payload.at(3));

  if (total_bytes < 1 || total_bytes > kJ1939MaxBytes) {
    ++m_counters.sizeOverruns;
    return;
  }

  const int expected_packets = (total_bytes + kTpDataBytesPerPacket - 1) / kTpDataBytesPerPacket;
  if (total_packets != expected_packets || total_packets > kJ1939MaxPackets) {
    ++m_counters.malformed;
    return;
  }

  if (m_sessions.size() >= kMaxSessions) {
    ++m_counters.sessionOverruns;
    return;
  }

  Session session;
  session.pgn = static_cast<quint32>(static_cast<quint8>(payload.at(5)))
              | (static_cast<quint32>(static_cast<quint8>(payload.at(6))) << 8)
              | (static_cast<quint32>(static_cast<quint8>(payload.at(7))) << 16);
  session.priority     = priority;
  session.totalBytes   = total_bytes;
  session.totalPackets = total_packets;
  session.firstSeen    = stamp;
  session.lastSeen     = stamp;
  session.bytes.reserve(total_packets * kTpDataBytesPerPacket);
  m_sessions.insert(key, session);
}

d::optional<IO::Drivers::J1939TransportReassembler::Completed> IO::Drivers::
  J1939TransportReassembler::handleDataTransfer(const quint8 source,
                                                const quint8 destination,
                                                const QByteArrayView payload,
                                                const SteadyTimePoint stamp)
{
  SS_ASSERT(payload.size() >= 8, {
    ++m_counters.malformed;
    return std::nullopt;
  });
  SS_ASSERT_LOG(m_sessions.size() <= kMaxSessions);

  const auto it = m_sessions.find(sessionKey(source, destination));
  if (it == m_sessions.end())
    return std::nullopt;

  if (static_cast<int>(static_cast<quint8>(payload.at(0))) != it->nextSequence) {
    m_sessions.erase(it);
    ++m_counters.sequenceErrors;
    return std::nullopt;
  }

  it->bytes.append(payload.constData() + 1, kTpDataBytesPerPacket);
  it->lastSeen = stamp;
  ++it->nextSequence;

  if (it->bytes.size() > kJ1939MaxBytes) {
    m_sessions.erase(it);
    ++m_counters.sizeOverruns;
    return std::nullopt;
  }

  if (it->nextSequence <= it->totalPackets)
    return std::nullopt;

  Completed done;
  done.bytes      = it->bytes.left(it->totalBytes);
  done.firstSeen  = it->firstSeen;
  done.pgn        = it->pgn;
  done.priority   = it->priority;
  done.sourceAddr = source;

  m_sessions.erase(it);
  ++m_counters.completed;
  return done;
}

id IO::Drivers::J1939TransportReassembler::dropSession(const quint16 key, quint64& counter)
{
  SS_ASSERT_LOG(m_sessions.size() <= kMaxSessions);

  const auto it = m_sessions.find(key);
  if (it == m_sessions.end())
    return;

  m_sessions.erase(it);
  ++counter;
}

id IO::Drivers::J1939TransportReassembler::evictExpired(const SteadyTimePoint stamp)
{
  SS_ASSERT_LOG(m_sessions.size() <= kMaxSessions);

  if (m_sessions.isEmpty())
    return;

  const auto timeout = std::chrono::milliseconds(kSessionTimeoutMs);
  for (auto it = m_sessions.begin(); it != m_sessions.end();)
    if (stamp >= it->lastSeen + timeout) {
      it = m_sessions.erase(it);
      ++m_counters.timeouts;
    } else
      ++it;
}

ol IO::Drivers::IsoTpReassembler::isDiagnosticId(const quint32 canId,
                                                   const bool extendedId) noexcept
{
  if (!extendedId)
    return canId >= 0x7E0u && canId <= 0x7EFu;

  const quint32 base = canId & 0x1FFF0000u;
  return base == 0x18DA0000u || base == 0x18DB0000u;
}

ol IO::Drivers::IsoTpReassembler::isMultiFrame(const QByteArrayView payload) noexcept
{
  if (payload.isEmpty())
    return false;

  const quint8 pci = static_cast<quint8>(static_cast<quint8>(payload.at(0)) >> 4);
  return pci >= kPciFirstFrame && pci <= kPciFlowControl;
}

id IO::Drivers::IsoTpReassembler::reset()
{
  SS_ASSERT_LOG(m_sessions.size() <= kMaxSessions);

  m_sessions.clear();
  m_counters = CanReassemblyCounters();

  SS_ASSERT_LOG(m_sessions.isEmpty());
}

d::optional<IO::Drivers::IsoTpReassembler::Completed> IO::Drivers::IsoTpReassembler::feed(
  const quint32 canId,
  const bool extendedId,
  const QByteArrayView payload,
  const SteadyTimePoint stamp)
{
  SS_ASSERT(m_sessions.size() <= kMaxSessions, return std::nullopt);
  SS_ASSERT_LOG(payload.size() <= 64);

  if (!isDiagnosticId(canId, extendedId))
    return std::nullopt;

  evictExpired(stamp);

  if (payload.isEmpty()) {
    ++m_counters.malformed;
    return std::nullopt;
  }

  const quint8 pci = static_cast<quint8>(static_cast<quint8>(payload.at(0)) >> 4);
  if (pci == kPciSingleFrame || pci == kPciFlowControl)
    return std::nullopt;

  if (pci == kPciConsecutiveFrame)
    return continueFrame(canId, payload, stamp);

  if (pci == kPciFirstFrame)
    startFirstFrame(canId, extendedId, payload, stamp);

  return std::nullopt;
}

id IO::Drivers::IsoTpReassembler::startFirstFrame(const quint32 canId,
                                                    const bool extendedId,
                                                    const QByteArrayView payload,
                                                    const SteadyTimePoint stamp)
{
  SS_ASSERT_LOG(m_sessions.size() <= kMaxSessions);

  if (payload.size() < 2) {
    ++m_counters.malformed;
    return;
  }

  const auto live = m_sessions.find(canId);
  if (live != m_sessions.end()) {
    m_sessions.erase(live);
    ++m_counters.aborted;
  }

  const int total =
    ((static_cast<quint8>(payload.at(0)) & 0x0F) << 8) | static_cast<quint8>(payload.at(1));

  if (total < kIsoTpMinMultiFrameBytes) {
    ++m_counters.malformed;
    return;
  }

  if (total > kIsoTpMaxBytes) {
    ++m_counters.sizeOverruns;
    return;
  }

  if (m_sessions.size() >= kMaxSessions) {
    ++m_counters.sessionOverruns;
    return;
  }

  Session session;
  session.totalBytes = total;
  session.extendedId = extendedId;
  session.firstSeen  = stamp;
  session.lastSeen   = stamp;
  session.bytes.reserve(total);
  session.bytes.append(payload.constData() + 2, qMin<qsizetype>(payload.size() - 2, total));
  m_sessions.insert(canId, session);
}

d::optional<IO::Drivers::IsoTpReassembler::Completed> IO::Drivers::IsoTpReassembler::
  continueFrame(const quint32 canId, const QByteArrayView payload, const SteadyTimePoint stamp)
{
  SS_ASSERT(!payload.isEmpty(), {
    ++m_counters.malformed;
    return std::nullopt;
  });
  SS_ASSERT_LOG(m_sessions.size() <= kMaxSessions);

  const auto it = m_sessions.find(canId);
  if (it == m_sessions.end())
    return std::nullopt;

  if ((static_cast<quint8>(payload.at(0)) & 0x0F) != it->nextSequence) {
    m_sessions.erase(it);
    ++m_counters.sequenceErrors;
    return std::nullopt;
  }

  const qsizetype room = it->totalBytes - it->bytes.size();
  const qsizetype take = qMin<qsizetype>(payload.size() - 1, room);
  if (take > 0)
    it->bytes.append(payload.constData() + 1, take);

  it->lastSeen     = stamp;
  it->nextSequence = (it->nextSequence + 1) & 0x0F;

  if (it->bytes.size() < it->totalBytes)
    return std::nullopt;

  Completed done;
  done.bytes      = it->bytes;
  done.firstSeen  = it->firstSeen;
  done.canId      = canId;
  done.extendedId = it->extendedId;

  m_sessions.erase(it);
  ++m_counters.completed;
  return done;
}

id IO::Drivers::IsoTpReassembler::evictExpired(const SteadyTimePoint stamp)
{
  SS_ASSERT_LOG(m_sessions.size() <= kMaxSessions);

  if (m_sessions.isEmpty())
    return;

  const auto timeout = std::chrono::milliseconds(kSessionTimeoutMs);
  for (auto it = m_sessions.begin(); it != m_sessions.end();)
    if (stamp >= it->lastSeen + timeout) {
      it = m_sessions.erase(it);
      ++m_counters.timeouts;
    } else
      ++it;
}

nodiscard]] static bool eipTagNameSafe(const QString& tag)
{
  SS_ASSERT_LOG(kEipMaxTagNameChars > 0);
  if (tag.isEmpty() || tag.size() > kEipMaxTagNameChars)
    return false;

  for (const QChar ch : tag)
    if (ch == QLatin1Char('&') || ch == QLatin1Char('=') || ch.isSpace())
      return false;

  return true;
}

nodiscard]] static int createHandle(const QByteArray& attributes, QString& error)
{
  SS_ASSERT(!attributes.isEmpty(), {
    error = QCoreApplication::translate("EthernetIp", "The tag attributes are empty");
    return -1;
  });

  const int handle = plc_tag_create(attributes.constData(), kEipCreateTimeoutMs);
  const int status = handle < 0 ? handle : plc_tag_status(handle);
  if (status == PLCTAG_STATUS_OK)
    return handle;

  SS_ASSERT_LOG(status != PLCTAG_STATUS_OK);
  error = QString::fromLatin1(plc_tag_decode_error(status));
  if (handle >= 0)
    (void)plc_tag_destroy(handle);

  return -1;
}

atic void releaseHandles(QList<int>& handles)
{
  SS_ASSERT_LOG(handles.size() >= 0);

  for (int i = 0; i < handles.size(); ++i) {
    if (handles.at(i) < 0)
      continue;

    (void)plc_tag_destroy(handles.at(i));
    handles[i] = -1;
  }
}

nodiscard]] static bool readHandle(int handle)
{
  SS_ASSERT(handle >= 0, return false);
  SS_ASSERT_LOG(kEipReadTimeoutMs > 0);

  return plc_tag_read(handle, kEipReadTimeoutMs) == PLCTAG_STATUS_OK;
}

nodiscard]] static QVariant decodeTag(int handle, IO::Drivers::OpcUaWire::Type type)
{
  using IO::Drivers::OpcUaWire::Type;
  SS_ASSERT(handle >= 0, return {});
  SS_ASSERT(type != Type::Invalid, return {});

  switch (type) {
    case Type::Bool:
      return QVariant(plc_tag_get_uint8(handle, 0) != 0);
    case Type::I8:
      return QVariant(static_cast<int>(plc_tag_get_int8(handle, 0)));
    case Type::U8:
      return QVariant(static_cast<uint>(plc_tag_get_uint8(handle, 0)));
    case Type::I16:
      return QVariant(static_cast<int>(plc_tag_get_int16(handle, 0)));
    case Type::U16:
      return QVariant(static_cast<uint>(plc_tag_get_uint16(handle, 0)));
    case Type::I32:
      return QVariant(static_cast<int>(plc_tag_get_int32(handle, 0)));
    case Type::U32:
      return QVariant(static_cast<qulonglong>(plc_tag_get_uint32(handle, 0)));
    case Type::I64:
      return QVariant(static_cast<qlonglong>(plc_tag_get_int64(handle, 0)));
    case Type::U64:
      return QVariant(static_cast<qulonglong>(plc_tag_get_uint64(handle, 0)));
    case Type::F32:
      return QVariant(static_cast<double>(plc_tag_get_float32(handle, 0)));
    case Type::F64:
      return QVariant(plc_tag_get_float64(handle, 0));
    case Type::Str:
      break;
    case Type::Invalid:
      return {};
  }

  constexpr int cap = IO::Drivers::OpcUaWire::kMaxStringBytes;
  QByteArray text(cap, static_cast<char>(0));
  if (plc_tag_get_string(handle, 0, text.data(), cap - 1) != PLCTAG_STATUS_OK)
    return {};

  return QVariant(QString::fromLatin1(text.constData()));
}

nodiscard]] static int createHandle(const QByteArray& attributes, QString& error)
{
  SS_ASSERT_LOG(!attributes.isEmpty());
  Q_UNUSED(attributes);

  error = QCoreApplication::translate("EthernetIp", "The %1 client is not available in this build")
            .arg(QLatin1String(kEipBackend));
  return -1;
}

atic void releaseHandles(QList<int>& handles)
{
  SS_ASSERT_LOG(handles.size() >= 0);
  handles.fill(-1);
}

nodiscard]] static bool readHandle(int handle)
{
  SS_ASSERT_LOG(handle >= -1);
  Q_UNUSED(handle);
  return false;
}

nodiscard]] static QVariant decodeTag(int handle, IO::Drivers::OpcUaWire::Type type)
{
  SS_ASSERT_LOG(handle >= -1);
  SS_ASSERT_LOG(type != IO::Drivers::OpcUaWire::Type::Invalid);
  Q_UNUSED(handle);
  Q_UNUSED(type);
  return {};
}

id IO::Drivers::EipPollWorker::configure(const QString& host,
                                           const QString& path,
                                           const QString& plcType,
                                           int interval,
                                           QVector<EipTag> tags)
{
  SS_ASSERT(!tags.isEmpty(), return);
  SS_ASSERT_LOG(interval >= kEipMinIntervalMs);

  m_host     = host;
  m_path     = path;
  m_plcType  = plcType;
  m_interval = interval;
  m_tags     = std::move(tags);
  m_values   = QList<QVariant>(m_tags.size());
  m_dirty    = QList<bool>(m_tags.size(), false);
  m_handles  = QList<int>(m_tags.size(), -1);

  qsizetype bytes = OpcUaWire::kHeaderBytes;
  for (const auto& tag : m_tags)
    bytes += OpcUaWire::maxEntryBytes(tag.type);

  const auto reserve = qMin<qsizetype>(bytes, OpcUaWire::kMaxFrameBytes);
  m_frames[0].reserve(reserve);
  m_frames[1].reserve(reserve);
}

yteArray IO::Drivers::EipPollWorker::attributes(const EipTag& tag) const
{
  SS_ASSERT(!tag.tag.isEmpty(), return {});
  SS_ASSERT_LOG(!m_host.isEmpty());

  QString name = tag.tag;
  if (tag.element >= 0)
    name += QStringLiteral("[%1]").arg(tag.element);

  QString attribs = QStringLiteral("protocol=ab-eip&gateway=%1&plc=%2&elem_count=1&name=%3")
                      .arg(m_host, m_plcType, name);
  if (!m_path.trimmed().isEmpty())
    attribs += QStringLiteral("&path=%1").arg(m_path.trimmed());

  return attribs.toLatin1();
}

ol IO::Drivers::EipPollWorker::connectToPlc()
{
  SS_ASSERT(!m_open, return true);

  m_dialError.clear();
  SS_ASSERT(!m_tags.isEmpty(), return false);

  QElapsedTimer budget;
  budget.start();
  for (int i = 0; i < m_tags.size(); ++i) {
    QString reason;
    const int handle = createHandle(attributes(m_tags.at(i)), reason);
    if (handle < 0) {
      m_dialError = tr("\"%1\": %2").arg(m_tags.at(i).tag, reason);
      shutdown();
      return false;
    }

    m_handles[i] = handle;
    if (budget.hasExpired(kEipDialDeadlineMs) && i + 1 < m_tags.size()) {
      m_dialError = tr("The controller did not open every tag within the connection deadline");
      shutdown();
      return false;
    }
  }

  m_open      = true;
  m_reported  = false;
  m_deadTicks = 0;
  m_timer     = new QTimer(this);
  m_timer->setInterval(m_interval);
  connect(m_timer, &QTimer::timeout, this, &IO::Drivers::EipPollWorker::onPollTick);
  m_timer->start();
  return true;
}

id IO::Drivers::EipPollWorker::shutdown()
{
  m_open = false;
  if (m_timer) {
    m_timer->stop();
    delete m_timer;
    m_timer = nullptr;
  }

  releaseHandles(m_handles);

  SS_ASSERT_LOG(m_timer == nullptr);
  SS_ASSERT_LOG(!m_open);
}

id IO::Drivers::EipPollWorker::onPollTick()
{
  if (!m_open || m_abort.load(std::memory_order_relaxed))
    return;

  const auto now       = std::chrono::steady_clock::now().time_since_epoch();
  const qint64 stampNs = std::chrono::duration_cast<std::chrono::nanoseconds>(now).count();

  int answered = 0;
  for (int i = 0; i < m_tags.size(); ++i) {
    if (m_abort.load(std::memory_order_relaxed))
      return;

    QVariant value;
    if (!readTag(i, value))
      continue;

    ++answered;
    if (m_values.at(i) == value)
      continue;

    m_values[i] = value;
    m_dirty[i]  = true;
  }

  m_deadTicks = answered > 0 ? 0 : m_deadTicks + 1;
  if (m_deadTicks >= kEipDeadTickLimit) {
    reportFailure(tr("The controller stopped answering tag reads"));
    return;
  }

  publishDirtySlots(stampNs);
}

ol IO::Drivers::EipPollWorker::readTag(int index, QVariant& value)
{
  SS_ASSERT(index >= 0 && index < m_tags.size() && index < m_handles.size(), return false);

  const int handle = m_handles.at(index);
  SS_ASSERT_LOG(handle >= -1);
  if (handle < 0 || !readHandle(handle)) {
    m_readsFailed.fetch_add(1, std::memory_order_relaxed);
    return false;
  }

  m_readsOk.fetch_add(1, std::memory_order_relaxed);
  value = decodeTag(handle, m_tags.at(index).type);
  return value.isValid();
}

id IO::Drivers::EipPollWorker::publishDirtySlots(qint64 stampNs)
{
  SS_ASSERT_LOG(m_dirty.size() == m_tags.size());
  SS_ASSERT_LOG(stampNs > 0);

  QByteArray& frame = m_frames[m_frameSlot];
  OpcUaWire::beginFrame(frame);
  for (int i = 0; i < m_tags.size(); ++i) {
    if (!m_dirty.at(i))
      continue;

    if (frame.size() + OpcUaWire::maxEntryBytes(m_tags.at(i).type) > OpcUaWire::kMaxFrameBytes)
      break;

    OpcUaWire::appendEntry(frame, i, m_tags.at(i).type, m_values.at(i));
    m_dirty[i] = false;
  }

  if (frame.size() <= OpcUaWire::kHeaderBytes)
    return;

  m_framesPublished.fetch_add(1, std::memory_order_relaxed);
  Q_EMIT frameReady(frame, stampNs);
  m_frameSlot ^= 1;
}

id IO::Drivers::EipPollWorker::reportFailure(const QString& reason)
{
  SS_ASSERT_LOG(!reason.isEmpty());
  if (m_reported)
    return;

  m_reported = true;
  m_open     = false;
  if (m_timer)
    m_timer->stop();

  Q_EMIT linkLost(reason);
}

::Drivers::EthernetIp::EthernetIp()
  : m_open(false)
  , m_persistent(true)
  , m_plcTypeIndex(0)
  , m_pollInterval(kEipDefaultIntervalMs)
  , m_lastStampNs(0)
  , m_linkDrops(0)
  , m_host(QStringLiteral("192.168.0.1"))
  , m_cipPath(QStringLiteral("1,0"))
  , m_thread(std::make_unique<QThread>())
  , m_worker(nullptr)
{
  loadSettings();

  static constexpr void (EthernetIp::* kConfigSignals[])() = {&EthernetIp::hostChanged,
                                                              &EthernetIp::cipPathChanged,
                                                              &EthernetIp::plcTypeChanged,
                                                              &EthernetIp::pollIntervalChanged,
                                                              &EthernetIp::tagsChanged};
  for (const auto signal : kConfigSignals)
    connect(this, signal, this, &IO::Drivers::EthernetIp::configurationChanged);

  Q_EMIT configurationChanged();
}

id IO::Drivers::EthernetIp::loadSettings()
{
  m_host         = m_settings.value("EipDriver/host", m_host).toString();
  m_cipPath      = m_settings.value("EipDriver/cipPath", m_cipPath).toString();
  m_plcTypeIndex = qBound(0,
                          m_settings.value("EipDriver/plcType", 0).toInt(),
                          static_cast<int>(std::size(kEipPlcTypes)) - 1);
  m_pollInterval = qBound(kEipMinIntervalMs,
                          m_settings.value("EipDriver/pollInterval", kEipDefaultIntervalMs).toInt(),
                          kEipMaxIntervalMs);

  const auto doc =
    QJsonDocument::fromJson(m_settings.value("EipDriver/tags", QByteArray("[]")).toByteArray());
  if (doc.isArray())
    setTags(doc.array());
}

id IO::Drivers::EthernetIp::saveTags()
{
  if (!m_persistent)
    return;

  m_settings.setValue("EipDriver/tags", QJsonDocument(tagsJson()).toJson(QJsonDocument::Compact));
}

id IO::Drivers::EthernetIp::setPersistent(const bool persistent) noexcept
{
  if (m_persistent == persistent)
    return;

  m_persistent = persistent;
}

id IO::Drivers::EthernetIp::setSessionPeer(EthernetIp* peer)
{
  SS_ASSERT(peer != this, return);
  if (m_sessionPeer == peer)
    return;

  m_sessionPeer = peer;
  if (peer)
    connect(peer,
            &QObject::destroyed,
            this,
            &IO::Drivers::EthernetIp::statusChanged,
            Qt::UniqueConnection);

  Q_EMIT statusChanged();
}

id IO::Drivers::EthernetIp::close()
{
  doClose();

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
}

id IO::Drivers::EthernetIp::doClose()
{
  m_open = false;
  if (!m_worker) {
    SS_ASSERT_LOG(!m_thread->isRunning());
    return;
  }

  disconnect(m_worker, nullptr, this, nullptr);
  if (m_thread->isRunning()) {
    m_worker->requestAbort();
    QMetaObject::invokeMethod(
      m_worker, [this] { m_worker->shutdown(); }, Qt::BlockingQueuedConnection);
    m_thread->quit();
    if (!m_thread->wait(kEipJoinTimeoutMs)) {
      qWarning() << "[EtherNet/IP] poll thread did not stop within" << kEipJoinTimeoutMs
                 << "ms -- abandoning it";
      (void)m_thread.release();
      m_thread      = std::make_unique<QThread>();
      m_worker      = nullptr;
      m_lastStampNs = 0;
      return;
    }
  }

  delete m_worker;
  m_worker      = nullptr;
  m_lastStampNs = 0;
}

ol IO::Drivers::EthernetIp::configurationOk() const noexcept
{
  if (m_host.trimmed().isEmpty() || m_tags.isEmpty())
    return false;

  return m_tags.size() <= OpcUaWire::kMaxTags;
}

nt64 IO::Drivers::EthernetIp::write(const QByteArray& data)
{
  Q_UNUSED(data);
  return -1;
}

ol IO::Drivers::EthernetIp::open(const QIODevice::OpenMode mode)
{
  Q_UNUSED(mode);

  doClose();
  if (!configurationOk()) {
    m_lastError = tr("The connection is not configured: check the host and the tag list");
    Q_EMIT statusChanged();
    return false;
  }

  m_lastError.clear();
  m_worker = new EipPollWorker();
  m_worker->configure(m_host.trimmed(), m_cipPath, plcType(), m_pollInterval, m_tags);
  m_worker->moveToThread(m_thread.get());
  connect(m_worker, &EipPollWorker::frameReady, this, &IO::Drivers::EthernetIp::onFrameReady);
  connect(m_worker, &EipPollWorker::linkLost, this, &IO::Drivers::EthernetIp::onLinkLost);

  m_thread->start();

  bool ok = false;
  QMetaObject::invokeMethod(
    m_worker, [this, &ok] { ok = m_worker->connectToPlc(); }, Qt::BlockingQueuedConnection);

  m_open = ok;
  if (!ok) {
    m_lastError = m_worker->dialError();
    logDriverError(
      tr("EtherNet/IP Connection Failed"),
      tr("\"%1\": %2")
        .arg(m_host, m_lastError.isEmpty() ? tr("the controller did not answer") : m_lastError));
    doClose();
  }

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
  return ok;
}

id IO::Drivers::EthernetIp::onFrameReady(const QByteArray& frame, qint64 stampNs)
{
  SS_ASSERT(!frame.isEmpty(), return);
  SS_ASSERT_LOG(stampNs > 0);

  const qint64 stamp = qMax(stampNs, m_lastStampNs + 1);
  m_lastStampNs      = stamp;
  publishReceivedData(frame, CapturedData::SteadyTimePoint(std::chrono::nanoseconds(stamp)));
}

id IO::Drivers::EthernetIp::onLinkLost(const QString& reason)
{
  m_lastError = reason;
  ++m_linkDrops;
  if (!m_open) {
    Q_EMIT statusChanged();
    return;
  }

  m_open = false;
  logDriverError(tr("EtherNet/IP Connection Lost"), reason);

  static auto& manager = ConnectionManager::instance();
  QMetaObject::invokeMethod(this, [this] { manager.disconnectDevice(this); }, Qt::QueuedConnection);

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
}

tring IO::Drivers::EthernetIp::plcType() const
{
  const int index = qBound(0, m_plcTypeIndex, static_cast<int>(std::size(kEipPlcTypes)) - 1);
  return QString::fromLatin1(kEipPlcTypes[index]);
}

tringList IO::Drivers::EthernetIp::plcTypeList()
{
  QStringList list;
  for (const auto* type : kEipPlcTypes)
    list.append(QString::fromLatin1(type));

  return list;
}

tringList IO::Drivers::EthernetIp::plcTypeLabels()
{
  const QStringList labels = {tr("ControlLogix"),
                              tr("CompactLogix"),
                              tr("MicroLogix"),
                              tr("Micro800"),
                              tr("PLC-5"),
                              tr("SLC 500"),
                              tr("Logix PCCC"),
                              tr("Omron NJ/NX")};

  SS_ASSERT(labels.size() == static_cast<int>(std::size(kEipPlcTypes)), return plcTypeList());
  return labels;
}

tring IO::Drivers::EthernetIp::statusText() const
{
  if (const auto* peer = sessionPeer())
    return peer->statusText();

  if (!m_open)
    return m_lastError.isEmpty() ? tr("Not connected") : m_lastError;

  const double hz = 1000.0 / qMax(1, m_pollInterval);
  return tr("Polling %1 tags at %2 Hz").arg(m_tags.size()).arg(hz, 0, 'f', 1);
}

tring IO::Drivers::EthernetIp::tagInfo(const int index) const
{
  if (index < 0 || index >= m_tags.size())
    return {};

  const auto& tag  = m_tags.at(index);
  const auto label = tag.element >= 0
                     ? QStringLiteral("%1[%2]").arg(tag.tag, QString::number(tag.element))
                     : tag.tag;
  return QStringLiteral("%1 (%2) %3").arg(tag.name, OpcUaWire::codeFromType(tag.type), label);
}

sonArray IO::Drivers::EthernetIp::tagsJson() const
{
  QJsonArray array;
  for (const auto& tag : m_tags)
    array.append(QJsonObject{
      {   QStringLiteral("name"),                          tag.name},
      {    QStringLiteral("tag"),                           tag.tag},
      {      QStringLiteral("t"), OpcUaWire::codeFromType(tag.type)},
      {QStringLiteral("element"),                       tag.element},
    });

  return array;
}

sonArray IO::Drivers::EthernetIp::wireSchema() const
{
  QJsonArray schema;
  for (int i = 0; i < m_tags.size() && i < OpcUaWire::kMaxTags; ++i)
    schema.append(QJsonObject{
      {QStringLiteral("index"),                 i},
      { QStringLiteral("name"), m_tags.at(i).name},
    });

  return schema;
}

sonObject IO::Drivers::EthernetIp::statusJson() const
{
  if (const auto* peer = sessionPeer())
    return peer->statusJson();

  const quint64 reads  = m_worker ? m_worker->readsOk() : 0;
  const quint64 failed = m_worker ? m_worker->readsFailed() : 0;
  const quint64 frames = m_worker ? m_worker->framesPublished() : 0;

  return QJsonObject{
    {      QStringLiteral("connected"),                           m_open},
    {           QStringLiteral("host"),                           m_host},
    {        QStringLiteral("cipPath"),                        m_cipPath},
    {        QStringLiteral("plcType"),                        plcType()},
    {   QStringLiteral("pollInterval"),                   m_pollInterval},
    {       QStringLiteral("tagCount"),                       tagCount()},
    {        QStringLiteral("readsOk"),       static_cast<qint64>(reads)},
    {    QStringLiteral("readsFailed"),      static_cast<qint64>(failed)},
    {QStringLiteral("framesPublished"),      static_cast<qint64>(frames)},
    {      QStringLiteral("linkDrops"), static_cast<qint64>(m_linkDrops)},
    {      QStringLiteral("lastError"),                      m_lastError},
    {     QStringLiteral("statusText"),                     statusText()},
  };
}

id IO::Drivers::EthernetIp::setHost(const QString& host)
{
  const auto trimmed = host.trimmed();
  if (m_host == trimmed)
    return;

  m_host = trimmed;
  if (m_persistent)
    m_settings.setValue("EipDriver/host", m_host);

  Q_EMIT hostChanged();
}

id IO::Drivers::EthernetIp::setCipPath(const QString& path)
{
  const auto trimmed = path.trimmed();
  if (m_cipPath == trimmed)
    return;

  m_cipPath = trimmed;
  if (m_persistent)
    m_settings.setValue("EipDriver/cipPath", m_cipPath);

  Q_EMIT cipPathChanged();
}

id IO::Drivers::EthernetIp::setPlcTypeIndex(const int index)
{
  const int clamped = qBound(0, index, static_cast<int>(std::size(kEipPlcTypes)) - 1);
  if (m_plcTypeIndex == clamped)
    return;

  m_plcTypeIndex = clamped;
  if (m_persistent)
    m_settings.setValue("EipDriver/plcType", m_plcTypeIndex);

  Q_EMIT plcTypeChanged();
}

id IO::Drivers::EthernetIp::setPollInterval(const int interval)
{
  const int clamped = qBound(kEipMinIntervalMs, interval, kEipMaxIntervalMs);
  if (m_pollInterval == clamped)
    return;

  m_pollInterval = clamped;
  if (m_persistent)
    m_settings.setValue("EipDriver/pollInterval", m_pollInterval);

  Q_EMIT pollIntervalChanged();
  Q_EMIT statusChanged();
}

id IO::Drivers::EthernetIp::setTags(const QJsonArray& tags)
{
  QVector<EipTag> list;
  QSet<QString> seen;
  for (const auto& item : tags) {
    const auto obj = item.toObject();

    EipTag tag;
    tag.tag     = obj.value(QStringLiteral("tag")).toString().trimmed();
    tag.name    = obj.value(QStringLiteral("name")).toString(tag.tag).trimmed();
    tag.type    = OpcUaWire::typeFromCode(obj.value(QStringLiteral("t")).toString());
    tag.element = obj.value(QStringLiteral("element")).toInt(-1);
    if (tag.tag.isEmpty() || tag.type == OpcUaWire::Type::Invalid || seen.contains(tag.name)
        || !eipTagNameSafe(tag.tag))
      continue;

    if (list.size() >= OpcUaWire::kMaxTags)
      break;

    seen.insert(tag.name);
    list.append(tag);
  }

  if (list == m_tags || tagsFrozen())
    return;

  m_tags = std::move(list);
  saveTags();
  Q_EMIT tagsChanged();
}

id IO::Drivers::EthernetIp::addTag(const QString& name,
                                     const QString& tag,
                                     const QString& type,
                                     const int element)
{
  const auto trimmedTag  = tag.trimmed();
  const auto trimmedName = name.trimmed().isEmpty() ? trimmedTag : name.trimmed();
  if (trimmedTag.isEmpty() || tagsFrozen() || m_tags.size() >= OpcUaWire::kMaxTags)
    return;

  if (!eipTagNameSafe(trimmedTag)) {
    logDriverError(tr("EtherNet/IP Tag"),
                   tr("The tag name \"%1\" is too long or contains characters that are not "
                      "allowed (no '&', '=' or whitespace).")
                     .arg(trimmedTag));
    return;
  }

  const auto wireType = OpcUaWire::typeFromCode(type);
  if (wireType == OpcUaWire::Type::Invalid) {
    logDriverError(tr("EtherNet/IP Tag"), tr("Unknown tag type \"%1\".").arg(type));
    return;
  }

  for (const auto& existing : m_tags)
    if (existing.name == trimmedName)
      return;

  m_tags.append(EipTag{trimmedName, trimmedTag, wireType, qMax(-1, element)});
  saveTags();
  Q_EMIT tagsChanged();
}

id IO::Drivers::EthernetIp::removeTag(const int index)
{
  if (index < 0 || index >= m_tags.size() || tagsFrozen())
    return;

  m_tags.removeAt(index);
  saveTags();
  Q_EMIT tagsChanged();
}

id IO::Drivers::EthernetIp::clearTags()
{
  if (m_tags.isEmpty() || tagsFrozen())
    return;

  m_tags.clear();
  saveTags();
  Q_EMIT tagsChanged();
}

ist<IO::DriverProperty> IO::Drivers::EthernetIp::driverProperties() const
{
  QList<IO::DriverProperty> props;

  IO::DriverProperty host;
  host.key   = QStringLiteral("host");
  host.label = tr("Gateway");
  host.type  = IO::DriverProperty::Text;
  host.value = m_host;
  props.append(host);

  IO::DriverProperty path;
  path.key   = QStringLiteral("cipPath");
  path.label = tr("CIP Path");
  path.type  = IO::DriverProperty::Text;
  path.value = m_cipPath;
  props.append(path);

  IO::DriverProperty family;
  family.key     = QStringLiteral("plcType");
  family.label   = tr("Controller Family");
  family.type    = IO::DriverProperty::ComboBox;
  family.value   = m_plcTypeIndex;
  family.options = plcTypeLabels();
  props.append(family);

  IO::DriverProperty interval;
  interval.key   = QStringLiteral("pollInterval");
  interval.label = tr("Poll Interval (ms)");
  interval.type  = IO::DriverProperty::IntField;
  interval.value = m_pollInterval;
  interval.min   = kEipMinIntervalMs;
  interval.max   = kEipMaxIntervalMs;
  props.append(interval);

  IO::DriverProperty tags;
  tags.key   = QStringLiteral("tags");
  tags.type  = IO::DriverProperty::Text;
  tags.value = QVariant::fromValue(tagsJson());
  props.append(tags);

  return props;
}

id IO::Drivers::EthernetIp::setDriverProperty(const QString& key, const QVariant& value)
{
  if (key == QLatin1String("host")) {
    setHost(value.toString());
    return;
  }

  if (key == QLatin1String("cipPath")) {
    setCipPath(value.toString());
    return;
  }

  if (key == QLatin1String("plcType")) {
    if (value.typeId() == QMetaType::QString)
      setPlcTypeIndex(static_cast<int>(plcTypeList().indexOf(value.toString())));
    else
      setPlcTypeIndex(value.toInt());

    return;
  }

  if (key == QLatin1String("pollInterval")) {
    setPollInterval(value.toInt());
    return;
  }

  if (key != QLatin1String("tags"))
    return;

  QJsonArray array;
  if (value.canConvert<QJsonArray>())
    array = value.toJsonArray();
  else if (value.typeId() == QMetaType::QVariantList) {
    const auto list = value.toList();
    for (const auto& item : list)
      array.append(QJsonValue::fromVariant(item));
  }

  setTags(array);
}

taModel::Dataset IO::Drivers::EthernetIp::datasetFor(const EipTag& tag, int index)
{
  SS_ASSERT_LOG(index >= 1);
  SS_ASSERT_LOG(!tag.name.isEmpty());

  DataModel::Dataset dataset;
  dataset.index = index;
  dataset.log   = true;
  dataset.title = tag.name;

  if (tag.type == OpcUaWire::Type::Bool) {
    dataset.led     = true;
    dataset.ledHigh = 1;
    dataset.wgtMax  = 1;
  } else if (tag.type != OpcUaWire::Type::Str && tag.type != OpcUaWire::Type::Invalid)
    dataset.plt = true;

  return dataset;
}

sonObject IO::Drivers::EthernetIp::buildProject() const
{
  QJsonObject project;
  project[Keys::Title]   = tr("EtherNet/IP Project");
  project[Keys::Actions] = QJsonArray();

  QJsonObject source;
  source[Keys::SourceId]              = 0;
  source[Keys::Title]                 = tr("EtherNet/IP");
  source[Keys::BusType]               = static_cast<int>(SerialStudio::BusType::EthernetIp);
  source[Keys::FrameStart]            = QString();
  source[Keys::FrameEnd]              = QString();
  source[Keys::Checksum]              = QString();
  source[Keys::FrameDetection]        = static_cast<int>(SerialStudio::NoDelimiters);
  source[Keys::Decoder]               = static_cast<int>(SerialStudio::Binary);
  source[Keys::HexadecimalDelimiters] = false;
  source[Keys::FrameParserCode]       = QString();
  source[Keys::FrameParserLanguage]   = static_cast<int>(SerialStudio::Native);
  source[Keys::FrameParserTemplate]   = QStringLiteral("ethernetip");
  source[Keys::FrameParserParams]     = QJsonObject{
        {QStringLiteral("schema"), wireSchema()}
  };

  QJsonObject conn;
  for (const auto& prop : driverProperties())
    if (prop.type != IO::DriverProperty::Password)
      conn.insert(prop.key, QJsonValue::fromVariant(prop.value));

  source[Keys::SourceConn] = conn;
  project[Keys::Sources]   = QJsonArray{source};

  QStringList order;
  QHash<QString, DataModel::Group> groups;
  for (int i = 0; i < m_tags.size(); ++i) {
    const auto& tag   = m_tags.at(i);
    const QString key = tag.tag.startsWith(QLatin1String("Program:"))
                        ? tag.tag.section(QLatin1Char('.'), 0, 0)
                        : tr("Controller Tags");
    if (!groups.contains(key)) {
      DataModel::Group group;
      group.groupId = order.size();
      group.widget  = QStringLiteral("datagrid");
      group.title   = key;
      groups.insert(key, group);
      order.append(key);
    }

    groups[key].datasets.push_back(datasetFor(tag, i + 1));
  }

  QJsonArray groupArray;
  for (const auto& key : order)
    groupArray.append(DataModel::serialize(groups.value(key)));

  project[Keys::Groups] = groupArray;
  return project;
}

taModel::ProjectModel* IO::Drivers::EthernetIp::loadGeneratedProject()
{
  if (m_tags.isEmpty())
    return nullptr;

  static auto& pm       = DataModel::ProjectModel::instance();
  static auto& appState = AppState::instance();
  appState.setOperationMode(SerialStudio::ProjectFile);
  if (!pm.loadFromJsonDocument(QJsonDocument(buildProject()), QString())) {
    logDriverError(tr("Failed to load generated project"),
                   tr("The generated project JSON could not be loaded."));
    return nullptr;
  }

  pm.setModified(true);
  return &pm;
}

id IO::Drivers::EthernetIp::generateProject()
{
  if (m_tags.isEmpty()) {
    Misc::Utilities::showMessageBox(tr("No tags configured"),
                                    tr("Add at least one tag before generating a project."),
                                    QMessageBox::Warning,
                                    tr("EtherNet/IP Project Generator"));
    return;
  }

  auto* pm = loadGeneratedProject();
  if (!pm)
    return;

  const int datasets = wireSchema().size();
  QObject::connect(
    pm,
    &DataModel::ProjectModel::saveDialogCompleted,
    this,
    [datasets](bool accepted) {
      if (!accepted)
        return;

      Misc::Utilities::showMessageBox(
        tr("Successfully generated project with %1 datasets.").arg(datasets),
        tr("The project editor is now open for customization."),
        QMessageBox::Information,
        tr("EtherNet/IP Project Generator"));
    },
    Qt::SingleShotConnection);

  (void)pm->saveJsonFile(true);
}

nodiscard]] static QJsonArray asJsonArray(const QVariant& value)
{
  if (value.canConvert<QJsonArray>())
    return value.toJsonArray();

  if (value.typeId() != QMetaType::QVariantList)
    return {};

  QJsonArray array;
  const auto list = value.toList();
  for (const auto& item : list)
    array.append(QJsonValue::fromVariant(item));

  return array;
}

id IO::Drivers::Iec104::loadSettings()
{
  m_host = m_settings.value("Iec104Driver/host", m_host).toString();
  m_port =
    qBound(1, m_settings.value("Iec104Driver/port", Iec104Proto::kDefaultPort).toInt(), 65535);
  m_commonAddress = qBound(0,
                           m_settings.value("Iec104Driver/commonAddress", m_commonAddress).toInt(),
                           kIec104MaxCommonAddress);

  m_windowK   = m_settings.value("Iec104Driver/windowK", kDefaultK).toInt();
  m_windowW   = m_settings.value("Iec104Driver/windowW", kDefaultW).toInt();
  m_timeoutT1 = m_settings.value("Iec104Driver/timeoutT1", kDefaultT1Ms).toInt();
  m_timeoutT2 = m_settings.value("Iec104Driver/timeoutT2", kDefaultT2Ms).toInt();
  m_timeoutT3 = m_settings.value("Iec104Driver/timeoutT3", kDefaultT3Ms).toInt();

  const auto doc = QJsonDocument::fromJson(
    m_settings.value("Iec104Driver/points", QByteArray("[]")).toByteArray());
  if (doc.isArray())
    setPoints(doc.array());
}

id IO::Drivers::Iec104::savePoints()
{
  if (!m_persistent || m_loading)
    return;

  m_settings.setValue("Iec104Driver/points",
                      QJsonDocument(pointsJson()).toJson(QJsonDocument::Compact));
}

id IO::Drivers::Iec104::reserveFrame()
{
  qsizetype bytes = OpcUaWire::kHeaderBytes;
  for (const auto& point : m_points)
    bytes += OpcUaWire::maxEntryBytes(wireTypeFor(point.kind));

  m_frameReserveBytes = qMin<qsizetype>(bytes, OpcUaWire::kMaxFrameBytes);
  m_frame             = QByteArray();
  m_frame.reserve(m_frameReserveBytes);
}

id IO::Drivers::Iec104::applyProtocolParameters()
{
  m_link.configure(m_windowK, m_windowW, m_timeoutT1, m_timeoutT2, m_timeoutT3);

  m_windowK   = m_link.windowK();
  m_windowW   = m_link.windowW();
  m_timeoutT1 = m_link.t1Ms();
  m_timeoutT2 = m_link.t2Ms();
  m_timeoutT3 = m_link.t3Ms();
}

id IO::Drivers::Iec104::setPersistent(const bool persistent) noexcept
{
  if (m_persistent == persistent)
    return;

  m_persistent = persistent;
}

id IO::Drivers::Iec104::setSessionPeer(Iec104* peer)
{
  SS_ASSERT(peer != this, return);

  if (m_sessionPeer == peer)
    return;

  m_sessionPeer = peer;
  if (peer) {
    connect(
      peer, &QObject::destroyed, this, &IO::Drivers::Iec104::statusChanged, Qt::UniqueConnection);
    connect(peer,
            &IO::Drivers::Iec104::pointsChanged,
            this,
            &IO::Drivers::Iec104::pointsChanged,
            Qt::UniqueConnection);
  }

  Q_EMIT statusChanged();
  Q_EMIT pointsChanged();
}

nst QVector<IO::Drivers::Iec104Point>& IO::Drivers::Iec104::pointTable() const noexcept
{
  if (const auto* peer = sessionPeer())
    return peer->m_points;

  return m_points;
}

id IO::Drivers::Iec104::adoptDiscoveredPoints()
{
  const auto* peer = sessionPeer();
  if (!peer || peer->m_points == m_points)
    return;

  m_points = peer->m_points;
  m_slotForIoa.clear();
  for (int i = 0; i < m_points.size(); ++i)
    m_slotForIoa.insert(m_points.at(i).ioa, i);

  m_values     = QList<QVariant>(m_points.size());
  m_stamps     = QList<qint64>(m_points.size(), -1);
  m_dirty      = QList<bool>(m_points.size(), false);
  m_dirtyCount = 0;

  savePoints();
  Q_EMIT pointsChanged();
}

id IO::Drivers::Iec104::close()
{
  doClose();

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
}

id IO::Drivers::Iec104::doClose()
{
  m_open    = false;
  m_started = false;

  m_timer->stop();
  disconnect(m_socket, &QTcpSocket::readyRead, this, &IO::Drivers::Iec104::onReadyRead);
  disconnect(m_socket, &QTcpSocket::errorOccurred, this, &IO::Drivers::Iec104::onSocketError);

  m_socket->abort();
  m_socket->close();

  m_rx.clear();
  m_clockValid    = false;
  m_lastStampNs   = 0;
  m_clockOffsetNs = 0;
  m_stationBaseMs = 0;
}

nt64 IO::Drivers::Iec104::write(const QByteArray& data)
{
  Q_UNUSED(data)
  return -1;
}

ol IO::Drivers::Iec104::open(const QIODevice::OpenMode mode)
{
  Q_UNUSED(mode)

  doClose();
  if (!configurationOk()) {
    m_lastError = tr("The connection is not configured: check the host and the port");
    Q_EMIT statusChanged();
    return false;
  }

  if (!dialStation()) {
    Q_EMIT statusChanged();
    return false;
  }

  connect(m_socket,
          &QTcpSocket::readyRead,
          this,
          &IO::Drivers::Iec104::onReadyRead,
          Qt::UniqueConnection);
  connect(m_socket,
          &QTcpSocket::errorOccurred,
          this,
          &IO::Drivers::Iec104::onSocketError,
          Qt::UniqueConnection);

  m_lastError.clear();
  m_open = true;
  m_rx.reserve(kIec104ReassemblyReserveBytes);
  reserveFrame();
  applyProtocolParameters();
  m_link.reset(monotonicMs());
  sendApdu(m_link.encodeUnnumbered(UFunction::StartDtAct, monotonicMs()));
  m_timer->start();

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
  return true;
}

ol IO::Drivers::Iec104::dialStation()
{
  SS_ASSERT(m_port > 0, return false);
  SS_ASSERT_LOG(m_socket->state() == QAbstractSocket::UnconnectedState);

  const auto host = m_host.trimmed();
  const auto port = static_cast<quint16>(m_port);

  m_socket->connectToHost(host, port);
  if (m_socket->waitForConnected(kIec104DialDeadlineMs))
    return true;

  m_lastError = m_socket->errorString();
  m_socket->abort();
  logDriverError(tr("IEC 104 Connection Failed"),
                 tr("Cannot connect to %1:%2 (%3)").arg(host, QString::number(port), m_lastError));
  return false;
}

id IO::Drivers::Iec104::sendApdu(const QByteArray& apdu)
{
  if (apdu.isEmpty() || !m_open)
    return;

  SS_ASSERT_LOG(apdu.size() >= kApciBytes);
  (void)m_socket->write(apdu);
}

id IO::Drivers::Iec104::onReadyRead()
{
  if (!m_open)
    return;

  const qint64 available = m_socket->bytesAvailable();
  if (available <= 0)
    return;

  const qsizetype used = m_rx.size();
  if (used + available > kIec104MaxRxBytes) {
    reportLinkLost(tr("The station sent more than the receive buffer holds"));
    return;
  }

  m_rx.resize(used + static_cast<qsizetype>(available));
  const qint64 read = m_socket->read(m_rx.data() + used, available);
  m_rx.resize(used + static_cast<qsizetype>(qMax<qint64>(0, read)));
  drainReceiveBuffer(monotonicMs());
}

id IO::Drivers::Iec104::drainReceiveBuffer(qint64 nowMs)
{
  const qsizetype discovered = m_points.size();
  qsizetype offset           = 0;
  for (int guard = 0; guard < kIec104MaxFramesPerRead && offset < m_rx.size(); ++guard) {
    const auto view = QByteArrayView(m_rx).sliced(offset);

    Apdu apdu;
    const auto result = m_link.consume(view, apdu, nowMs);
    if (result == ParseResult::NeedMore)
      break;

    if (result != ParseResult::Ok) {
      m_rx.clear();
      reportLinkLost(tr("The station sent a frame this link could not decode"));
      return;
    }

    offset += apdu.apduSize;
    if (apdu.type == FrameType::Unnumbered)
      handleUnnumbered(apdu.function, nowMs);
    else if (apdu.type == FrameType::Information)
      handleInformation(view.sliced(apdu.asduOffset, apdu.asduSize));
  }

  if (offset > 0)
    m_rx.remove(0, offset);

  if (m_points.size() != discovered)
    Q_EMIT pointsChanged();
}

id IO::Drivers::Iec104::handleUnnumbered(UFunction function, qint64 nowMs)
{
  if (function == UFunction::TestFrAct) {
    sendApdu(m_link.encodeUnnumbered(UFunction::TestFrCon, nowMs));
    return;
  }

  if (function == UFunction::StopDtAct) {
    sendApdu(m_link.encodeUnnumbered(UFunction::StopDtCon, nowMs));
    return;
  }

  if (function != UFunction::StartDtCon || m_started)
    return;

  m_started          = true;
  const auto request = encodeInterrogation(static_cast<quint16>(m_commonAddress), kQoiStation);
  sendApdu(m_link.encodeInformation(request, nowMs));
}

id IO::Drivers::Iec104::handleInformation(QByteArrayView asdu)
{
  Header header;
  if (decodeHeader(asdu, header) != DecodeResult::Ok) {
    ++m_skippedAsdus;
    return;
  }

  if (header.commonAddress != static_cast<quint16>(m_commonAddress))
    return;

  QList<Point> points;
  if (decode(asdu, header, points) != DecodeResult::Ok) {
    ++m_skippedAsdus;
    return;
  }

  for (const auto& point : points)
    ingestPoint(point);
}

id IO::Drivers::Iec104::ingestPoint(const Point& point)
{
  const int slot = slotForPoint(point);
  if (slot < 0)
    return;

  if (point.quality & QualityInvalid) {
    ++m_badQualityPoints;
    return;
  }

  if (point.quality != QualityGood)
    ++m_badQualityPoints;

  if (m_values.at(slot) == point.value)
    return;

  m_values[slot] = point.value;
  m_stamps[slot] = point.timeValid ? point.timeMsecs : -1;
  if (!m_dirty.at(slot)) {
    m_dirty[slot] = true;
    ++m_dirtyCount;
  }
}

t IO::Drivers::Iec104::slotForPoint(const Point& point)
{
  const auto known = m_slotForIoa.constFind(point.ioa);
  if (known != m_slotForIoa.constEnd())
    return known.value();

  if (m_points.size() >= OpcUaWire::kMaxTags)
    return -1;

  Iec104Point discovered;
  discovered.ioa    = point.ioa;
  discovered.typeId = point.typeId;
  discovered.kind   = point.kind;

  const int slot = static_cast<int>(m_points.size());
  m_points.append(discovered);
  m_slotForIoa.insert(point.ioa, slot);
  m_values.append(QVariant());
  m_stamps.append(-1);
  m_dirty.append(false);

  const int entryBytes = OpcUaWire::maxEntryBytes(wireTypeFor(point.kind));
  m_frameReserveBytes =
    qMin<qsizetype>(OpcUaWire::kMaxFrameBytes, m_frameReserveBytes + entryBytes);

  SS_ASSERT_LOG(m_values.size() == m_points.size());
  return slot;
}

id IO::Drivers::Iec104::onProtocolTick()
{
  if (!m_open)
    return;

  const qint64 now = monotonicMs();
  if (m_link.confirmOverdue(now)) {
    ++m_testTimeouts;
    reportLinkLost(tr("The station did not answer within t1"));
    return;
  }

  if (m_link.ackDue(now))
    sendApdu(m_link.encodeSupervisory(now));

  if (m_link.testDue(now))
    sendApdu(m_link.encodeUnnumbered(UFunction::TestFrAct, now));

  publishDeltaFrame();
}

id IO::Drivers::Iec104::publishDeltaFrame()
{
  SS_ASSERT_LOG(m_dirty.size() == m_points.size());
  if (m_dirtyCount <= 0)
    return;

  OpcUaWire::beginFrame(m_frame);

  qint64 earliest = -1;
  for (int i = 0; i < m_points.size(); ++i) {
    if (!m_dirty.at(i))
      continue;

    const auto type = wireTypeFor(m_points.at(i).kind);
    if (m_frame.size() + OpcUaWire::maxEntryBytes(type) > OpcUaWire::kMaxFrameBytes)
      break;

    OpcUaWire::appendEntry(m_frame, i, type, m_values.at(i));
    if (m_stamps.at(i) >= 0 && (earliest < 0 || m_stamps.at(i) < earliest))
      earliest = m_stamps.at(i);

    m_dirty[i] = false;
    --m_dirtyCount;
  }

  if (m_frame.size() <= OpcUaWire::kHeaderBytes)
    return;

  ++m_framesPublished;
  publishReceivedData(std::move(m_frame), toSteady(earliest));
  m_frame = QByteArray();
  m_frame.reserve(m_frameReserveBytes);
}

::CapturedData::SteadyTimePoint IO::Drivers::Iec104::toSteady(qint64 stationMs)
{
  const auto now = CapturedData::SteadyClock::now();
  const qint64 nowNs =
    std::chrono::duration_cast<std::chrono::nanoseconds>(now.time_since_epoch()).count();

  if (stationMs >= 0 && !m_clockValid) {
    m_clockValid    = true;
    m_stationBaseMs = stationMs;
    m_clockOffsetNs = nowNs;
  }

  qint64 stamp = nowNs;
  if (stationMs < 0 || !m_clockValid)
    ++m_unstampedPoints;
  else {
    const qint64 elapsedMs = (nowNs - m_clockOffsetNs) / kIec104NsPerMs;
    const qint64 skewMs    = stationMs - m_stationBaseMs - elapsedMs;
    if (skewMs > kIec104MaxSkewMs || skewMs < -kIec104MaxSkewMs)
      ++m_unstampedPoints;
    else
      stamp = m_clockOffsetNs + (stationMs - m_stationBaseMs) * kIec104NsPerMs;
  }

  stamp         = qMax(stamp, m_lastStampNs + 1);
  m_lastStampNs = stamp;
  return CapturedData::SteadyTimePoint(std::chrono::nanoseconds(stamp));
}

id IO::Drivers::Iec104::reportLinkLost(const QString& reason)
{
  m_lastError = reason;
  ++m_linkDrops;
  if (!m_open) {
    Q_EMIT statusChanged();
    return;
  }

  m_open    = false;
  m_started = false;
  m_timer->stop();
  logDriverError(tr("IEC 104 Connection Lost"), reason);

  static auto& manager = ConnectionManager::instance();
  QMetaObject::invokeMethod(this, [this] { manager.disconnectDevice(this); }, Qt::QueuedConnection);

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
}

nt64 IO::Drivers::Iec104::monotonicMs()
{
  const auto now = CapturedData::SteadyClock::now().time_since_epoch();
  return std::chrono::duration_cast<std::chrono::milliseconds>(now).count();
}

tring IO::Drivers::Iec104::statusText() const
{
  if (const auto* peer = sessionPeer())
    return peer->statusText();

  if (!m_open)
    return m_lastError.isEmpty() ? tr("Not connected") : m_lastError;

  if (!m_started)
    return tr("Starting data transfer…");

  return tr("Monitoring %1 point(s) from station %2").arg(m_points.size()).arg(m_commonAddress);
}

