nodiscard]] static int readSequence(QByteArrayView buffer, qsizetype pos) noexcept
{
  SS_ASSERT(pos >= 0 && pos + 1 < buffer.size(), return 0);

  const auto low  = static_cast<std::uint8_t>(buffer[pos]);
  const auto high = static_cast<std::uint8_t>(buffer[pos + 1]);
  return ((static_cast<int>(high) << 7) | (low >> 1)) & 0x7FFF;
}

atic void writeSequence(QByteArray& apdu, qsizetype pos, int value) noexcept
{
  SS_ASSERT(pos >= 0 && pos + 1 < apdu.size(), return);

  apdu[pos]     = static_cast<char>((value << 1) & 0xFE);
  apdu[pos + 1] = static_cast<char>((value >> 7) & 0xFF);
}

nodiscard]] static bool isKnownFunction(IO::Drivers::Iec104Proto::UFunction function) noexcept
{
  using IO::Drivers::Iec104Proto::UFunction;

  switch (function) {
    case UFunction::StartDtAct:
    case UFunction::StartDtCon:
    case UFunction::StopDtAct:
    case UFunction::StopDtCon:
    case UFunction::TestFrAct:
    case UFunction::TestFrCon:
      return true;
    case UFunction::None:
      break;
  }

  return false;
}

id IO::Drivers::Iec104Proto::Connection::reset(qint64 nowMs) noexcept
{
  m_sendSeq          = 0;
  m_recvSeq          = 0;
  m_ackedSeq         = 0;
  m_unackedRx        = 0;
  m_lastTrafficMs    = nowMs;
  m_firstUnackedRxMs = kNotArmed;
  m_sendPendingMs    = kNotArmed;
  m_controlPendingMs = kNotArmed;
}

id IO::Drivers::Iec104Proto::Connection::configure(
  int k, int w, int t1Ms, int t2Ms, int t3Ms) noexcept
{
  m_k = qBound(kMinWindow, k, kMaxWindow);
  m_w = qBound(kMinWindow, w, m_k);

  m_t1 = qBound(kMinTimeMs, t1Ms, kMaxTimeMs);
  m_t2 = qBound(kMinTimeMs, t2Ms, m_t1);
  m_t3 = qBound(kMinTimeMs, t3Ms, kMaxTimeMs);
}

ol IO::Drivers::Iec104Proto::Connection::ackDue(qint64 nowMs) const noexcept
{
  if (m_unackedRx <= 0)
    return false;

  if (m_unackedRx >= m_w)
    return true;

  return m_firstUnackedRxMs != kNotArmed && nowMs - m_firstUnackedRxMs >= m_t2;
}

ol IO::Drivers::Iec104Proto::Connection::testDue(qint64 nowMs) const noexcept
{
  if (m_lastTrafficMs == kNotArmed || m_controlPendingMs != kNotArmed)
    return false;

  return nowMs - m_lastTrafficMs >= m_t3;
}

ol IO::Drivers::Iec104Proto::Connection::confirmOverdue(qint64 nowMs) const noexcept
{
  if (m_sendPendingMs != kNotArmed && nowMs - m_sendPendingMs >= m_t1)
    return true;

  return m_controlPendingMs != kNotArmed && nowMs - m_controlPendingMs >= m_t1;
}

yteArray IO::Drivers::Iec104Proto::Connection::encodeUnnumbered(UFunction function, qint64 nowMs)
{
  SS_ASSERT(isKnownFunction(function), return {});

  QByteArray apdu(kApciBytes, static_cast<char>(0));
  apdu[0] = static_cast<char>(kStartByte);
  apdu[1] = static_cast<char>(kMinApduLength);
  apdu[2] = static_cast<char>(function);

  if (!isConfirmation(function) && m_controlPendingMs == kNotArmed)
    m_controlPendingMs = nowMs;

  m_lastTrafficMs = nowMs;
  ++m_framesSent;
  return apdu;
}

yteArray IO::Drivers::Iec104Proto::Connection::encodeSupervisory(qint64 nowMs)
{
  QByteArray apdu(kApciBytes, static_cast<char>(0));
  apdu[0] = static_cast<char>(kStartByte);
  apdu[1] = static_cast<char>(kMinApduLength);
  apdu[2] = static_cast<char>(0x01);
  writeSequence(apdu, 4, m_recvSeq);

  m_unackedRx        = 0;
  m_firstUnackedRxMs = kNotArmed;
  m_lastTrafficMs    = nowMs;
  ++m_framesSent;
  return apdu;
}

yteArray IO::Drivers::Iec104Proto::Connection::encodeInformation(QByteArrayView asdu,
                                                                   qint64 nowMs)
{
  SS_ASSERT(!asdu.isEmpty(), return {});

  if (asdu.size() > kMaxAsduBytes) {
    ++m_malformed;
    return {};
  }

  if (!sendWindowOpen())
    return {};

  QByteArray apdu(kApciBytes, static_cast<char>(0));
  apdu[0] = static_cast<char>(kStartByte);
  apdu[1] = static_cast<char>(kControlBytes + static_cast<int>(asdu.size()));
  writeSequence(apdu, 2, m_sendSeq);
  writeSequence(apdu, 4, m_recvSeq);
  apdu.append(asdu);

  m_sendSeq = (m_sendSeq + 1) % kSequenceModulo;
  if (m_sendPendingMs == kNotArmed)
    m_sendPendingMs = nowMs;

  m_unackedRx        = 0;
  m_firstUnackedRxMs = kNotArmed;
  m_lastTrafficMs    = nowMs;
  ++m_framesSent;
  return apdu;
}

::Drivers::Iec104Proto::ParseResult IO::Drivers::Iec104Proto::Connection::consume(
  QByteArrayView buffer, Apdu& out, qint64 nowMs)
{
  out = Apdu{};
  if (buffer.size() < 2)
    return ParseResult::NeedMore;

  if (static_cast<std::uint8_t>(buffer[0]) != kStartByte) {
    ++m_malformed;
    return ParseResult::Malformed;
  }

  const int length = static_cast<std::uint8_t>(buffer[1]);
  if (length < kMinApduLength || length > kMaxApduLength) {
    ++m_malformed;
    return ParseResult::Malformed;
  }

  const qsizetype total = static_cast<qsizetype>(length) + 2;
  if (buffer.size() < total)
    return ParseResult::NeedMore;

  out.apduSize    = total;
  m_lastTrafficMs = nowMs;
  ++m_framesReceived;

  const auto control = static_cast<std::uint8_t>(buffer[2]);
  if ((control & 0x01) == 0)
    return acceptInformation(buffer, out, nowMs);

  if ((control & 0x03) == 0x01)
    return acceptSupervisory(buffer, out, nowMs);

  return acceptUnnumbered(buffer, out);
}

::Drivers::Iec104Proto::ParseResult IO::Drivers::Iec104Proto::Connection::acceptInformation(
  QByteArrayView buffer, Apdu& out, qint64 nowMs)
{
  SS_ASSERT(out.apduSize >= kApciBytes, return ParseResult::Malformed);

  out.type       = FrameType::Information;
  out.sendSeq    = readSequence(buffer, 2);
  out.recvSeq    = readSequence(buffer, 4);
  out.asduOffset = kApciBytes;
  out.asduSize   = out.apduSize - kApciBytes;

  if (out.sendSeq != m_recvSeq) {
    ++m_sequenceErrors;
    return ParseResult::OutOfOrder;
  }

  if (!acknowledge(out.recvSeq, nowMs)) {
    ++m_sequenceErrors;
    return ParseResult::OutOfOrder;
  }

  m_recvSeq = (m_recvSeq + 1) % kSequenceModulo;
  if (m_unackedRx == 0)
    m_firstUnackedRxMs = nowMs;

  ++m_unackedRx;
  return ParseResult::Ok;
}

::Drivers::Iec104Proto::ParseResult IO::Drivers::Iec104Proto::Connection::acceptSupervisory(
  QByteArrayView buffer, Apdu& out, qint64 nowMs)
{
  if (out.apduSize != kApciBytes) {
    ++m_malformed;
    return ParseResult::Malformed;
  }

  out.type    = FrameType::Supervisory;
  out.recvSeq = readSequence(buffer, 4);
  if (!acknowledge(out.recvSeq, nowMs)) {
    ++m_sequenceErrors;
    return ParseResult::OutOfOrder;
  }

  return ParseResult::Ok;
}

::Drivers::Iec104Proto::ParseResult IO::Drivers::Iec104Proto::Connection::acceptUnnumbered(
  QByteArrayView buffer, Apdu& out)
{
  if (out.apduSize != kApciBytes) {
    ++m_malformed;
    return ParseResult::Malformed;
  }

  const auto function = static_cast<UFunction>(static_cast<std::uint8_t>(buffer[2]));
  if (!isKnownFunction(function)) {
    ++m_malformed;
    return ParseResult::Malformed;
  }

  out.type     = FrameType::Unnumbered;
  out.function = function;
  noteConfirmation(function);
  return ParseResult::Ok;
}

ol IO::Drivers::Iec104Proto::Connection::acknowledge(int recvSeq, qint64 nowMs) noexcept
{
  SS_ASSERT(recvSeq >= 0 && recvSeq < kSequenceModulo, return false);

  const int pending = outstanding();
  const int advance = (recvSeq - m_ackedSeq + kSequenceModulo) % kSequenceModulo;
  if (advance > pending)
    return false;

  m_ackedSeq = recvSeq;
  if (outstanding() == 0)
    m_sendPendingMs = kNotArmed;
  else if (advance > 0)
    m_sendPendingMs = nowMs;

  return true;
}

id IO::Drivers::Iec104Proto::Connection::noteConfirmation(UFunction function) noexcept
{
  if (isConfirmation(function))
    m_controlPendingMs = kNotArmed;
}

ol IO::Drivers::Iec104Proto::Connection::isConfirmation(UFunction function) noexcept
{
  return function == UFunction::StartDtCon || function == UFunction::StopDtCon
      || function == UFunction::TestFrCon;
}

::Drivers::Iec104Proto::UFunction IO::Drivers::Iec104Proto::Connection::confirmationFor(
  UFunction function) noexcept
{
  switch (function) {
    case UFunction::StartDtAct:
      return UFunction::StartDtCon;
    case UFunction::StopDtAct:
      return UFunction::StopDtCon;
    case UFunction::TestFrAct:
      return UFunction::TestFrCon;
    case UFunction::None:
    case UFunction::StartDtCon:
    case UFunction::StopDtCon:
    case UFunction::TestFrCon:
      break;
  }

  return UFunction::None;
}

nodiscard]] static inline std::uint8_t iec104Octet(QByteArrayView view, qsizetype pos) noexcept
{
  SS_ASSERT(pos >= 0 && pos < view.size(), return 0);

  return static_cast<std::uint8_t>(view[pos]);
}

nodiscard]] static quint32 readLe32(QByteArrayView view, qsizetype pos) noexcept
{
  return static_cast<quint32>(iec104Octet(view, pos))
       | (static_cast<quint32>(iec104Octet(view, pos + 1)) << 8)
       | (static_cast<quint32>(iec104Octet(view, pos + 2)) << 16)
       | (static_cast<quint32>(iec104Octet(view, pos + 3)) << 24);
}

nodiscard]] static quint32 readIoa(QByteArrayView view, qsizetype pos) noexcept
{
  return static_cast<quint32>(iec104Octet(view, pos))
       | (static_cast<quint32>(iec104Octet(view, pos + 1)) << 8)
       | (static_cast<quint32>(iec104Octet(view, pos + 2)) << 16);
}

nodiscard]] static std::uint8_t commonQuality(std::uint8_t descriptor) noexcept
{
  using namespace IO::Drivers::Iec104Proto;

  std::uint8_t quality  = QualityGood;
  quality              |= (descriptor & 0x10) ? QualityBlocked : 0;
  quality              |= (descriptor & 0x20) ? QualitySubstituted : 0;
  quality              |= (descriptor & 0x40) ? QualityNotTopical : 0;
  quality              |= (descriptor & 0x80) ? QualityInvalid : 0;
  return quality;
}

nodiscard]] static std::uint8_t measurandQuality(std::uint8_t qds) noexcept
{
  using namespace IO::Drivers::Iec104Proto;

  const std::uint8_t overflow = (qds & 0x01) ? QualityOverflow : QualityGood;
  return static_cast<std::uint8_t>(commonQuality(qds) | overflow);
}

nodiscard]] static std::uint8_t counterQuality(std::uint8_t sequence) noexcept
{
  using namespace IO::Drivers::Iec104Proto;

  std::uint8_t quality  = QualityGood;
  quality              |= (sequence & 0x20) ? QualityOverflow : 0;
  quality              |= (sequence & 0x40) ? QualitySubstituted : 0;
  quality              |= (sequence & 0x80) ? QualityInvalid : 0;
  return quality;
}

::Drivers::Iec104Proto::PointKind IO::Drivers::Iec104Proto::kindForType(
  std::uint8_t typeId) noexcept
{
  switch (typeId) {
    case kTypeSinglePoint:
    case kTypeSinglePointTime:
      return PointKind::Single;
    case kTypeDoublePoint:
    case kTypeDoublePointTime:
      return PointKind::Double;
    case kTypeMeasuredNormalized:
    case kTypeMeasuredNormalTime:
      return PointKind::Normalized;
    case kTypeMeasuredScaled:
    case kTypeMeasuredScaledTime:
      return PointKind::Scaled;
    case kTypeMeasuredFloat:
    case kTypeMeasuredFloatTime:
      return PointKind::Float;
    case kTypeIntegratedTotals:
    case kTypeIntegratedTotalsTime:
      return PointKind::Counter;
    default:
      break;
  }

  return PointKind::Invalid;
}

ol IO::Drivers::Iec104Proto::isRecognizedType(std::uint8_t typeId) noexcept
{
  if (isMonitorType(typeId))
    return true;

  return typeId == kTypeEndOfInitialization || typeId == kTypeInterrogation;
}

ol IO::Drivers::Iec104Proto::typeCarriesTime(std::uint8_t typeId) noexcept
{
  switch (typeId) {
    case kTypeSinglePointTime:
    case kTypeDoublePointTime:
    case kTypeMeasuredNormalTime:
    case kTypeMeasuredScaledTime:
    case kTypeMeasuredFloatTime:
    case kTypeIntegratedTotalsTime:
      return true;
    default:
      break;
  }

  return false;
}

t IO::Drivers::Iec104Proto::elementBytes(std::uint8_t typeId) noexcept
{
  const auto kind = kindForType(typeId);
  const int stamp = typeCarriesTime(typeId) ? kCp56Bytes : 0;

  switch (kind) {
    case PointKind::Single:
    case PointKind::Double:
      return 1 + stamp;
    case PointKind::Normalized:
    case PointKind::Scaled:
      return 3 + stamp;
    case PointKind::Float:
    case PointKind::Counter:
      return 5 + stamp;
    case PointKind::Invalid:
      break;
  }

  return isRecognizedType(typeId) ? 1 : -1;
}

nodiscard]] static bool readElement(QByteArrayView view,
                                      qsizetype pos,
                                      IO::Drivers::Iec104Proto::Point& out) noexcept
{
  using namespace IO::Drivers::Iec104Proto;

  switch (out.kind) {
    case PointKind::Single:
      out.value   = QVariant((iec104Octet(view, pos) & 0x01) != 0);
      out.quality = commonQuality(iec104Octet(view, pos));
      return true;
    case PointKind::Double:
      out.value   = QVariant(static_cast<uint>(iec104Octet(view, pos) & 0x03));
      out.quality = commonQuality(iec104Octet(view, pos));
      return true;
    case PointKind::Normalized:
      out.value   = QVariant(static_cast<qint16>(readLe16(view, pos)) / kNormalizedScale);
      out.quality = measurandQuality(iec104Octet(view, pos + 2));
      return true;
    case PointKind::Scaled:
      out.value   = QVariant(static_cast<int>(static_cast<qint16>(readLe16(view, pos))));
      out.quality = measurandQuality(iec104Octet(view, pos + 2));
      return true;
    case PointKind::Counter:
      out.value   = QVariant(static_cast<int>(static_cast<qint32>(readLe32(view, pos))));
      out.quality = counterQuality(iec104Octet(view, pos + 4));
      return true;
    case PointKind::Float:
      break;
    case PointKind::Invalid:
      return false;
  }

  const quint32 bits = readLe32(view, pos);
  float value        = 0.0F;
  std::memcpy(&value, &bits, sizeof(value));
  out.value   = QVariant(static_cast<double>(value));
  out.quality = measurandQuality(iec104Octet(view, pos + 4));
  return true;
}

nodiscard]] static bool decodeObject(QByteArrayView view,
                                       qsizetype pos,
                                       std::uint8_t typeId,
                                       quint32 ioa,
                                       IO::Drivers::Iec104Proto::Point& out) noexcept
{
  using namespace IO::Drivers::Iec104Proto;

  out        = Point{};
  out.ioa    = ioa;
  out.typeId = typeId;
  out.kind   = kindForType(typeId);
  if (!readElement(view, pos, out))
    return false;

  if (!typeCarriesTime(typeId))
    return true;

  const int stampAt = elementBytes(typeId) - kCp56Bytes;
  SS_ASSERT(stampAt > 0, return false);

  bool valid    = false;
  out.timeMsecs = decodeCp56Time2a(view, pos + stampAt, valid);
  out.timeValid = valid && out.timeMsecs >= 0;
  return true;
}

::Drivers::Iec104Proto::DecodeResult IO::Drivers::Iec104Proto::decodeHeader(QByteArrayView asdu,
                                                                              Header& out) noexcept
{
  out = Header{};
  if (asdu.size() < kAsduHeaderBytes)
    return DecodeResult::Truncated;

  const auto vsq   = iec104Octet(asdu, 1);
  const auto cause = iec104Octet(asdu, 2);

  out.typeId        = iec104Octet(asdu, 0);
  out.sequence      = (vsq & 0x80) != 0;
  out.objectCount   = static_cast<std::uint8_t>(vsq & 0x7F);
  out.cause         = static_cast<std::uint8_t>(cause & 0x3F);
  out.negative      = (cause & 0x40) != 0;
  out.test          = (cause & 0x80) != 0;
  out.originator    = iec104Octet(asdu, 3);
  out.commonAddress = readLe16(asdu, 4);

  if (out.typeId == 0)
    return DecodeResult::Malformed;

  return DecodeResult::Ok;
}

nodiscard]] static IO::Drivers::Iec104Proto::DecodeResult decodeIndividual(
  QByteArrayView asdu,
  const IO::Drivers::Iec104Proto::Header& header,
  int width,
  QList<IO::Drivers::Iec104Proto::Point>& points)
{
  using namespace IO::Drivers::Iec104Proto;

  const qsizetype mark = points.size();
  qsizetype pos        = kAsduHeaderBytes;
  for (int i = 0; i < header.objectCount && i < kMaxObjects; ++i) {
    if (pos + kIoaBytes + width > asdu.size()) {
      points.resize(mark);
      return DecodeResult::Truncated;
    }

    Point point;
    if (!decodeObject(asdu, pos + kIoaBytes, header.typeId, readIoa(asdu, pos), point)) {
      points.resize(mark);
      return DecodeResult::Malformed;
    }

    points.append(point);
    pos += kIoaBytes + width;
  }

  return DecodeResult::Ok;
}

nodiscard]] static IO::Drivers::Iec104Proto::DecodeResult decodeSequence(
  QByteArrayView asdu,
  const IO::Drivers::Iec104Proto::Header& header,
  int width,
  QList<IO::Drivers::Iec104Proto::Point>& points)
{
  using namespace IO::Drivers::Iec104Proto;

  if (kAsduHeaderBytes + kIoaBytes > asdu.size())
    return DecodeResult::Truncated;

  const quint32 base   = readIoa(asdu, kAsduHeaderBytes);
  const qsizetype mark = points.size();
  qsizetype pos        = kAsduHeaderBytes + kIoaBytes;
  for (int i = 0; i < header.objectCount && i < kMaxObjects; ++i) {
    if (pos + width > asdu.size()) {
      points.resize(mark);
      return DecodeResult::Truncated;
    }

    Point point;
    if (!decodeObject(asdu, pos, header.typeId, (base + i) & kMaxIoa, point)) {
      points.resize(mark);
      return DecodeResult::Malformed;
    }

    points.append(point);
    pos += width;
  }

  return DecodeResult::Ok;
}

::Drivers::Iec104Proto::DecodeResult IO::Drivers::Iec104Proto::decode(QByteArrayView asdu,
                                                                        Header& header,
                                                                        QList<Point>& points)
{
  const auto parsed = decodeHeader(asdu, header);
  if (parsed != DecodeResult::Ok)
    return parsed;

  if (!isRecognizedType(header.typeId))
    return DecodeResult::Unsupported;

  if (!isMonitorType(header.typeId) || header.objectCount == 0)
    return DecodeResult::Ok;

  const int width = elementBytes(header.typeId);
  SS_ASSERT(width > 0, return DecodeResult::Unsupported);

  if (header.sequence)
    return decodeSequence(asdu, header, width, points);

  return decodeIndividual(asdu, header, width, points);
}

nt64 IO::Drivers::Iec104Proto::decodeCp56Time2a(QByteArrayView view,
                                                  qsizetype pos,
                                                  bool& valid) noexcept
{
  valid = false;
  if (pos < 0 || pos + kCp56Bytes > view.size())
    return -1;

  const int millis = readLe16(view, pos);
  const int minute = iec104Octet(view, pos + 2) & 0x3F;
  const int hour   = iec104Octet(view, pos + 3) & 0x1F;
  const int day    = iec104Octet(view, pos + 4) & 0x1F;
  const int month  = iec104Octet(view, pos + 5) & 0x0F;
  const int year   = (iec104Octet(view, pos + 6) & 0x7F) + 2000;

  if (millis > kMaxMillisecond || minute > 59 || hour > 23)
    return -1;

  const QDate date(year, month, day);
  if (!date.isValid())
    return -1;

  const QTime time(hour, minute, millis / 1000, millis % 1000);
  if (!time.isValid())
    return -1;

  valid = (iec104Octet(view, pos + 2) & 0x80) == 0;
  return QDateTime(date, time, QTimeZone::UTC).toMSecsSinceEpoch();
}

yteArray IO::Drivers::Iec104Proto::encodeInterrogation(quint16 commonAddress, std::uint8_t qoi)
{
  SS_ASSERT(qoi >= kQoiStation, return {});

  QByteArray asdu;
  asdu.reserve(kAsduHeaderBytes + kIoaBytes + 1);
  asdu.append(static_cast<char>(kTypeInterrogation));
  asdu.append(static_cast<char>(0x01));
  asdu.append(static_cast<char>(kCauseActivation));
  asdu.append(static_cast<char>(0));
  asdu.append(static_cast<char>(commonAddress & 0xFF));
  asdu.append(static_cast<char>((commonAddress >> 8) & 0xFF));
  asdu.append(3, static_cast<char>(0));
  asdu.append(static_cast<char>(qoi));

  SS_ASSERT_LOG(asdu.size() == kAsduHeaderBytes + kIoaBytes + 1);
  return asdu;
}

void IO::Drivers::MQTT::setSparkplugEnabled(const bool enabled)
{
  if (m_sparkplugEnabled == enabled)
    return;

  m_sparkplugEnabled = enabled;
  if (!enabled)
    m_sparkplugTimer.stop();

  m_settings.setValue(settingsKey("sparkplugEnabled"), enabled);
  refreshTopicFilterCache();
  scheduleReconnectIfActive();
  Q_EMIT mqttConfigurationChanged();
}

bool IO::Drivers::MQTT::applySparkplugProperty(const QString& key, const QVariant& value)
{
  if (key == QLatin1String("sparkplugEnabled")) {
    setSparkplugEnabled(value.toBool());
    return true;
  }

  if (key == QLatin1String("sparkplugGroupId")) {
    setSparkplugGroupId(value.toString());
    return true;
  }

  return false;
}

atic qint64 sparkplugSteadyNs()
{
  const auto now = IO::CapturedData::SteadyClock::now();
  const auto ns  = std::chrono::duration_cast<std::chrono::nanoseconds>(now.time_since_epoch());

  SS_ASSERT_LOG(ns.count() >= 0);
  return ns.count();
}

atic SpWire::Type sparkplugWireType(Sparkplug::ValueKind kind) noexcept
{
  switch (kind) {
    case Sparkplug::ValueKind::Numeric:
      return SpWire::Type::F64;
    case Sparkplug::ValueKind::Boolean:
      return SpWire::Type::Bool;
    case Sparkplug::ValueKind::String:
      return SpWire::Type::Str;
    case Sparkplug::ValueKind::None:
      break;
  }

  return SpWire::Type::Invalid;
}

atic QVariant sparkplugValue(const IO::Drivers::SparkplugSession::SlotValue& slot)
{
  SS_ASSERT_LOG(slot.index >= 0);
  SS_ASSERT_LOG(slot.kind != Sparkplug::ValueKind::None);

  switch (slot.kind) {
    case Sparkplug::ValueKind::Numeric:
      return QVariant(slot.num);
    case Sparkplug::ValueKind::Boolean:
      return QVariant(slot.b);
    case Sparkplug::ValueKind::String:
      return QVariant(slot.str);
    case Sparkplug::ValueKind::None:
      break;
  }

  return {};
}

atic QString sparkplugGroupTitle(const IO::Drivers::SparkplugSession::SlotValue& slot)
{
  SS_ASSERT_LOG(!slot.node.isEmpty());
  SS_ASSERT_LOG(slot.index >= 0);

  if (slot.device.isEmpty())
    return slot.node;

  return QStringLiteral("%1 / %2").arg(slot.node, slot.device);
}

atic DataModel::Dataset sparkplugDataset(const IO::Drivers::SparkplugSession::SlotValue& slot)
{
  SS_ASSERT_LOG(slot.index >= 0);
  SS_ASSERT_LOG(!slot.name.isEmpty());

  DataModel::Dataset dataset;
  dataset.index = slot.index + 1;
  dataset.log   = true;
  dataset.title = slot.name;

  if (slot.kind == Sparkplug::ValueKind::Boolean) {
    dataset.led     = true;
    dataset.ledHigh = 1;
    dataset.wgtMax  = 1;
  } else if (slot.kind == Sparkplug::ValueKind::Numeric)
    dataset.plt = true;

  return dataset;
}

atic QJsonArray sparkplugSchema(
  const QVector<IO::Drivers::SparkplugSession::SlotValue>& slotTable)
{
  SS_ASSERT_LOG(slotTable.size() <= SpLimits::kMaxSlots);

  QJsonArray schema;
  for (const auto& slot : slotTable) {
    SS_ASSERT_LOG(slot.index == schema.size());
    if (slot.index < 0 || slot.index >= SpWire::kMaxTags)
      break;

    schema.append(QJsonObject{
      {QStringLiteral("index"),       slot.index},
      { QStringLiteral("name"), slot.displayName}
    });
  }

  return schema;
}

atic QJsonArray sparkplugGroups(
  const QVector<IO::Drivers::SparkplugSession::SlotValue>& slotTable)
{
  SS_ASSERT_LOG(slotTable.size() <= SpLimits::kMaxSlots);

  QStringList order;
  QHash<QString, DataModel::Group> groups;
  for (const auto& slot : slotTable) {
    const QString key = slot.group + QLatin1Char('/') + slot.node + QLatin1Char('/') + slot.device;
    if (!groups.contains(key)) {
      DataModel::Group group;
      group.groupId = order.size();
      group.widget  = QStringLiteral("datagrid");
      group.title   = sparkplugGroupTitle(slot);
      groups.insert(key, group);
      order.append(key);
    }

    auto& group = groups[key];
    group.datasets.push_back(sparkplugDataset(slot));
  }

  QJsonArray array;
  for (const auto& key : order)
    array.append(DataModel::serialize(groups.value(key)));

  SS_ASSERT_LOG(array.size() == order.size());
  return array;
}

id IO::Drivers::MQTT::setSparkplugPeer(MQTT* peer)
{
  SS_ASSERT(peer != this, return);
  SS_ASSERT_LOG(m_sparkplug.slotCount() >= 0);

  if (m_sparkplugPeer == peer)
    return;

  m_sparkplugPeer = peer;
}

::Drivers::SparkplugSession& IO::Drivers::MQTT::sparkplugSession()
{
  SS_ASSERT_LOG(m_sparkplugPeer.data() != this);
  SS_ASSERT_LOG(m_sparkplug.slotCount() >= 0);

  if (m_sparkplugPeer)
    return m_sparkplugPeer->m_sparkplug;

  return m_sparkplug;
}

nst IO::Drivers::SparkplugSession& IO::Drivers::MQTT::sparkplugSession() const
{
  SS_ASSERT_LOG(m_sparkplugPeer.data() != this);
  SS_ASSERT_LOG(m_sparkplug.slotCount() >= 0);

  if (m_sparkplugPeer)
    return m_sparkplugPeer->m_sparkplug;

  return m_sparkplug;
}

t IO::Drivers::MQTT::sparkplugSlotCount() const
{
  SS_ASSERT_LOG(m_sparkplug.slotCount() >= 0);
  SS_ASSERT_LOG(sparkplugSession().slotCount() <= SpLimits::kMaxSlots);

  return sparkplugSession().slotCount();
}

::Drivers::SparkplugSession::Counters IO::Drivers::MQTT::sparkplugCounters() const
{
  SS_ASSERT_LOG(m_sparkplug.slotCount() >= 0);
  SS_ASSERT_LOG(sparkplugSession().slotCount() <= SpLimits::kMaxSlots);

  return sparkplugSession().counters();
}

ol IO::Drivers::MQTT::rejectSparkplugGroupId(const QString& groupId) const
{
  SS_ASSERT_LOG(groupId.size() >= 0);
  SS_ASSERT_LOG(m_sparkplugGroupId.size() >= 0);

  if (!groupId.contains(u'+') && !groupId.contains(u'#') && !groupId.contains(u'/'))
    return false;

  logDriverError(
    tr("Invalid Sparkplug Group ID"),
    tr("A group ID cannot contain '+', '#' or '/'; keeping \"%1\".").arg(m_sparkplugGroupId));
  return true;
}

id IO::Drivers::MQTT::refreshTopicFilterCache()
{
  SS_ASSERT_LOG(SpLimits::kNamespace != nullptr);
  SS_ASSERT_LOG(qstrlen(SpLimits::kNamespace) > 0);

  const QString ns = QString::fromLatin1(SpLimits::kNamespace);
  if (!m_sparkplugEnabled)
    m_effectiveFilter = m_topicFilter;
  else if (m_sparkplugGroupId.isEmpty())
    m_effectiveFilter = ns + QStringLiteral("/#");
  else
    m_effectiveFilter = ns + QStringLiteral("/") + m_sparkplugGroupId + QStringLiteral("/#");

  m_topicMatcher.setFilter(m_effectiveFilter);
}

id IO::Drivers::MQTT::routeReceivedMessage(const QByteArray& message, const QMqttTopicName& topic)
{
  SS_ASSERT(!message.isEmpty(), return);
  SS_ASSERT_LOG(topic.isValid());

  if (!m_sparkplugEnabled) {
    publishReceivedData(message);
    return;
  }

  if (!m_sparkplug.ingest(topic.name(), message)) {
    publishReceivedData(message);
    return;
  }

  publishSparkplugRebirths();
}

id IO::Drivers::MQTT::publishSparkplugRebirths()
{
  SS_ASSERT_LOG(m_sparkplugEnabled);
  SS_ASSERT_LOG(m_lastRebirthMs.size() <= SpLimits::kMaxNodes);

  const auto drained = m_sparkplug.takeRebirthTopics();
  for (const auto& topic : drained)
    if (m_pendingRebirths.size() < SpLimits::kMaxNodes && !m_pendingRebirths.contains(topic))
      m_pendingRebirths.append(topic);

  if (m_pendingRebirths.isEmpty())
    return;

  QStringList unsent;
  const qint64 now = QDateTime::currentMSecsSinceEpoch();
  for (const auto& topic : std::as_const(m_pendingRebirths)) {
    const qint64 last   = m_lastRebirthMs.value(topic, 0);
    const bool tracked  = last != 0;
    const bool limited  = tracked && now - last < kSparkplugRebirthMs;
    const bool uncapped = tracked || m_lastRebirthMs.size() < SpLimits::kMaxNodes;
    if (limited || !uncapped) {
      unsent.append(topic);
      continue;
    }

    const auto payload = Sparkplug::encodeRebirthRequest(static_cast<quint64>(now));
    if (m_client.publish(QMqttTopicName(topic), payload, 0, false) < 0) {
      qCWarning(lcMqttSub) << "rebirth NCMD publish rejected for" << topic;
      unsent.append(topic);
      continue;
    }

    m_lastRebirthMs.insert(topic, now);
  }

  m_pendingRebirths.swap(unsent);
}

id IO::Drivers::MQTT::onSparkplugTick()
{
  SS_ASSERT_LOG(m_sparkplugState.frame.size() <= SpWire::kMaxFrameBytes);
  SS_ASSERT_LOG(m_sparkplug.slotCount() <= SpLimits::kMaxSlots);

  if (!m_sparkplugEnabled)
    return;

  if (++m_sparkplugState.diagTicks >= kSparkplugDiagTicks)
    reportSparkplugDrops();

  if (!m_sparkplug.hasDirtySlots())
    return;

  SpWire::beginFrame(m_sparkplugState.frame);
  m_sparkplugState.earliestMs = 0;
  m_sparkplug.consumeDirtySlots(
    [this](const SparkplugSession::SlotValue& slot) { appendSparkplugSlot(slot); });

  flushSparkplugFrame();
}

id IO::Drivers::MQTT::appendSparkplugSlot(const SparkplugSession::SlotValue& slot)
{
  SS_ASSERT(slot.index >= 0 && slot.index < SpWire::kMaxTags, return);
  SS_ASSERT_LOG(m_sparkplugState.frame.size() >= SpWire::kHeaderBytes);

  const auto type = sparkplugWireType(slot.kind);
  if (type == SpWire::Type::Invalid)
    return;

  if (m_sparkplugState.frame.size() + SpWire::maxEntryBytes(type) > SpWire::kMaxFrameBytes)
    flushSparkplugFrame();

  SpWire::appendEntry(m_sparkplugState.frame, slot.index, type, sparkplugValue(slot));

  auto& earliest = m_sparkplugState.earliestMs;
  if (slot.timestampMs > 0 && (earliest == 0 || slot.timestampMs < earliest))
    earliest = slot.timestampMs;
}

id IO::Drivers::MQTT::flushSparkplugFrame()
{
  SS_ASSERT_LOG(m_sparkplugState.frame.size() <= SpWire::kMaxFrameBytes);
  SS_ASSERT_LOG(m_sparkplugState.lastStampNs >= 0);

  if (!m_sparkplugEnabled)
    return;

  if (m_sparkplugState.frame.size() <= SpWire::kHeaderBytes)
    return;

  const auto stamp = sparkplugStamp(m_sparkplugState.earliestMs);
  publishReceivedData(std::move(m_sparkplugState.frame), stamp);

  m_sparkplugState.frame      = QByteArray();
  m_sparkplugState.earliestMs = 0;
  m_sparkplugState.frame.reserve(SpWire::kMaxFrameBytes);
  SpWire::beginFrame(m_sparkplugState.frame);
}

::CapturedData::SteadyTimePoint IO::Drivers::MQTT::sparkplugStamp(const quint64 timestampMs)
{
  SS_ASSERT_LOG(m_sparkplugState.lastStampNs >= 0);
  SS_ASSERT_LOG(m_sparkplugState.frame.size() <= SpWire::kMaxFrameBytes);

  const bool mappable = timestampMs > 0 && timestampMs < kSparkplugMaxStampMs;
  const qint64 nowNs  = sparkplugSteadyNs();
  qint64 stamp        = nowNs;
  if (m_sparkplugState.clockValid && mappable) {
    const qint64 sourceNs = static_cast<qint64>(timestampMs) * kSparkplugNsPerMs;
    const qint64 mapped   = sourceNs + m_sparkplugState.offsetNs;
    if (mapped <= nowNs && nowNs - mapped <= kSparkplugMaxSkewNs)
      stamp = mapped;
  }

  stamp                        = qMax(stamp, m_sparkplugState.lastStampNs + 1);
  m_sparkplugState.lastStampNs = stamp;
  return CapturedData::SteadyTimePoint(std::chrono::nanoseconds(stamp));
}

id IO::Drivers::MQTT::sparkplugStateChanged(const bool connected)
{
  SS_ASSERT_LOG(m_lastRebirthMs.size() <= SpLimits::kMaxNodes);
  SS_ASSERT_LOG(m_sparkplugState.frame.size() <= SpWire::kMaxFrameBytes);

  m_sparkplugTimer.stop();
  m_sparkplug.reset();
  m_lastRebirthMs.clear();
  m_pendingRebirths.clear();
  m_sparkplugState    = SparkplugState();
  m_sparkplugCounters = SparkplugSession::Counters();
  if (!connected || !m_sparkplugEnabled)
    return;

  const qint64 wallNs = QDateTime::currentMSecsSinceEpoch() * kSparkplugNsPerMs;
  m_sparkplug.setGroupFilter(m_sparkplugGroupId);
  m_sparkplugState.offsetNs   = sparkplugSteadyNs() - wallNs;
  m_sparkplugState.clockValid = true;
  m_sparkplugState.frame.reserve(SpWire::kMaxFrameBytes);
  SpWire::beginFrame(m_sparkplugState.frame);

  connect(&m_sparkplugTimer, &QTimer::timeout, this, &MQTT::onSparkplugTick, Qt::UniqueConnection);
  m_sparkplugTimer.start(kSparkplugTickMs);
}

id IO::Drivers::MQTT::reportSparkplugDrops()
{
  SS_ASSERT_LOG(m_pendingRebirths.size() <= SpLimits::kMaxNodes);
  SS_ASSERT_LOG(m_sparkplug.slotCount() <= SpLimits::kMaxSlots);

  m_sparkplugState.diagTicks = 0;

  const auto& now  = m_sparkplug.counters();
  const auto& last = m_sparkplugCounters;
  const auto delta = [](quint64 current, quint64 previous) -> quint64 {
    return (current > previous) ? current - previous : 0;
  };

  const quint64 gaps    = delta(now.seqGaps, last.seqGaps);
  const quint64 caps    = delta(now.capDrops, last.capDrops);
  const quint64 errors  = delta(now.decodeErrors, last.decodeErrors);
  const quint64 dropped = delta(now.preBirthDropped, last.preBirthDropped);
  const quint64 unsup   = delta(now.unsupportedMetrics, last.unsupportedMetrics);

  m_sparkplugCounters = now;
  if ((gaps | caps | errors | dropped | unsup) == 0)
    return;

  qCWarning(lcMqttSub).nospace() << "sparkplug drops since the last sample: decode=" << errors
                                 << " caps=" << caps << " preBirth=" << dropped
                                 << " seqGaps=" << gaps << " unsupported=" << unsup;
}

sonObject IO::Drivers::MQTT::buildSparkplugProject() const
{
  SS_ASSERT_LOG(sparkplugSession().slotCount() > 0);
  SS_ASSERT_LOG(sparkplugSession().slotValues().size() <= SpLimits::kMaxSlots);

  const auto& slotTable = sparkplugSession().slotValues();

  QJsonObject project;
  project[Keys::Title]   = tr("Sparkplug Project");
  project[Keys::Actions] = QJsonArray();

  QJsonObject source;
  source[Keys::SourceId]              = 0;
  source[Keys::Title]                 = tr("MQTT");
  source[Keys::BusType]               = static_cast<int>(SerialStudio::BusType::Mqtt);
  source[Keys::FrameStart]            = QString();
  source[Keys::FrameEnd]              = QString();
  source[Keys::Checksum]              = QString();
  source[Keys::FrameDetection]        = static_cast<int>(SerialStudio::NoDelimiters);
  source[Keys::Decoder]               = static_cast<int>(SerialStudio::Binary);
  source[Keys::HexadecimalDelimiters] = false;
  source[Keys::FrameParserCode]       = QString();
  source[Keys::FrameParserLanguage]   = static_cast<int>(SerialStudio::Native);
  source[Keys::FrameParserTemplate]   = QStringLiteral("sparkplug");
  source[Keys::FrameParserParams]     = QJsonObject{
        {QStringLiteral("schema"), sparkplugSchema(slotTable)}
  };

  QJsonObject conn;
  for (const auto& prop : driverProperties())
    if (prop.type != IO::DriverProperty::Password)
      conn.insert(prop.key, QJsonValue::fromVariant(prop.value));

  source[Keys::SourceConn] = conn;
  project[Keys::Sources]   = QJsonArray{source};
  project[Keys::Groups]    = sparkplugGroups(slotTable);
  return project;
}

id IO::Drivers::MQTT::generateProject()
{
  SS_ASSERT_LOG(sparkplugSession().slotCount() >= 0);
  SS_ASSERT_LOG(sparkplugSession().slotValues().size() <= SpLimits::kMaxSlots);

  if (sparkplugSession().slotCount() <= 0) {
    Misc::Utilities::showMessageBox(tr("No Sparkplug metrics discovered"),
                                    tr("Connect to the broker and wait for at least one birth "
                                       "certificate before generating a project."),
                                    QMessageBox::Warning,
                                    tr("Sparkplug Project Generator"));
    return;
  }

  static auto& pm       = DataModel::ProjectModel::instance();
  static auto& appState = AppState::instance();

  const auto project      = buildSparkplugProject();
  const auto previousMode = appState.operationMode();
  appState.setOperationMode(SerialStudio::ProjectFile);
  if (!pm.loadFromJsonDocument(QJsonDocument(project), QString())) {
    appState.setOperationMode(previousMode);
    logDriverError(tr("Failed to load generated project"),
                   tr("The generated project JSON could not be loaded."));
    return;
  }

  pm.setModified(true);
  sparkplugSession().markGenerated();

  const int groupCount = project.value(Keys::Groups).toArray().size();
  const int datasets   = sparkplugSession().slotCount();
  QObject::connect(
    &pm,
    &DataModel::ProjectModel::saveDialogCompleted,
    this,
    [groupCount, datasets](bool accepted) {
      if (!accepted)
        return;

      Misc::Utilities::showMessageBox(
        tr("Successfully generated project with %1 groups and %2 datasets.")
          .arg(groupCount)
          .arg(datasets),
        tr("The project editor is now open for customization."),
        QMessageBox::Information,
        tr("Sparkplug Project Generator"));
    },
    Qt::SingleShotConnection);

  (void)pm.saveJsonFile(true);
}

atic bool failDecode(QString* error, const QString& reason)
{
  SS_ASSERT_LOG(!reason.isEmpty());

  if (error)
    *error = reason;

  return false;
}

atic bool readVarint(QByteArrayView data, qsizetype& pos, quint64& value) noexcept
{
  SS_ASSERT(pos >= 0, return false);
  SS_ASSERT(pos <= data.size(), return false);

  quint64 result = 0;
  for (int i = 0; i < Sparkplug::kMaxVarintBytes; ++i) {
    if (pos >= data.size())
      return false;

    const auto byte = static_cast<quint8>(data[pos]);
    ++pos;

    result |= static_cast<quint64>(byte & 0x7Fu) << (7 * i);
    if ((byte & 0x80u) == 0) {
      value = result;
      return true;
    }
  }

  return false;
}

atic bool readFixed(QByteArrayView data, qsizetype& pos, int width, quint64& value) noexcept
{
  SS_ASSERT(width == 4 || width == 8, return false);
  SS_ASSERT(pos >= 0 && pos <= data.size(), return false);

  if (data.size() - pos < width)
    return false;

  quint64 result = 0;
  for (int i = 0; i < width; ++i)
    result |= static_cast<quint64>(static_cast<quint8>(data[pos + i])) << (8 * i);

  pos   += width;
  value  = result;
  return true;
}

atic bool readLengthDelimited(QByteArrayView data, qsizetype& pos, QByteArrayView& block)
{
  SS_ASSERT(pos >= 0, return false);
  SS_ASSERT(pos <= data.size(), return false);

  quint64 length = 0;
  if (!readVarint(data, pos, length))
    return false;

  if (length > static_cast<quint64>(Sparkplug::kMaxPayloadBytes))
    return false;

  const auto size = static_cast<qsizetype>(length);
  if (data.size() - pos < size)
    return false;

  block  = data.sliced(pos, size);
  pos   += size;
  return true;
}

atic bool splitTag(quint64 tag, quint32& field, quint32& wire) noexcept
{
  const quint64 number = tag >> 3;
  if (number == 0 || number > Sparkplug::kMaxFieldNumber)
    return false;

  field = static_cast<quint32>(number);
  wire  = static_cast<quint32>(tag & 0x07u);
  SS_ASSERT_LOG(field > 0);
  SS_ASSERT_LOG(wire <= 7);
  return true;
}

atic bool skipField(QByteArrayView data, qsizetype& pos, quint32 wire)
{
  SS_ASSERT(pos >= 0, return false);
  SS_ASSERT(pos <= data.size(), return false);

  quint64 scratch = 0;
  QByteArrayView block;
  switch (wire) {
    case Sparkplug::kWireVarint:
      return readVarint(data, pos, scratch);
    case Sparkplug::kWireFixed64:
      return readFixed(data, pos, 8, scratch);
    case Sparkplug::kWireFixed32:
      return readFixed(data, pos, 4, scratch);
    case Sparkplug::kWireLengthDelimited:
      return readLengthDelimited(data, pos, block);
    default:
      break;
  }

  return false;
}

atic double numericFromRaw(quint32 datatype, quint64 raw) noexcept
{
  SS_ASSERT_LOG(Sparkplug::kindForDataType(datatype) == Sparkplug::ValueKind::Numeric);
  SS_ASSERT_LOG(datatype >= 1);

  switch (static_cast<Sparkplug::DataType>(datatype)) {
    case Sparkplug::DataType::Int8:
      return static_cast<double>(static_cast<qint8>(static_cast<quint8>(raw)));
    case Sparkplug::DataType::Int16:
      return static_cast<double>(static_cast<qint16>(static_cast<quint16>(raw)));
    case Sparkplug::DataType::Int32:
      return static_cast<double>(static_cast<qint32>(static_cast<quint32>(raw)));
    case Sparkplug::DataType::Int64:
      return static_cast<double>(static_cast<qint64>(raw));
    case Sparkplug::DataType::UInt8:
      return static_cast<double>(static_cast<quint8>(raw));
    case Sparkplug::DataType::UInt16:
      return static_cast<double>(static_cast<quint16>(raw));
    case Sparkplug::DataType::UInt32:
      return static_cast<double>(static_cast<quint32>(raw));
    case Sparkplug::DataType::UInt64:
      return static_cast<double>(raw);
    case Sparkplug::DataType::Float:
      return static_cast<double>(std::bit_cast<float>(static_cast<quint32>(raw)));
    case Sparkplug::DataType::Double:
      return std::bit_cast<double>(raw);
    case Sparkplug::DataType::Unknown:
    case Sparkplug::DataType::Boolean:
    case Sparkplug::DataType::String:
    case Sparkplug::DataType::DateTime:
    case Sparkplug::DataType::Text:
    case Sparkplug::DataType::Uuid:
      break;
    default:
      break;
  }

  return 0.0;
}

atic void finalizeMetric(Sparkplug::Metric& out, const SparkplugDetail::MetricScratch& scratch)
{
  SS_ASSERT_LOG(out.kind == Sparkplug::ValueKind::None);
  SS_ASSERT_LOG(scratch.field == 0 || scratch.field >= Sparkplug::kMetricIntValue);

  out.supported = Sparkplug::isSupportedDataType(out.datatype);
  out.kind      = Sparkplug::kindForDataType(out.datatype);
  if (!out.supported || out.isNull || scratch.field == 0)
    return;

  if (out.kind == Sparkplug::ValueKind::Boolean)
    out.boolValue = (scratch.raw != 0);

  if (out.kind == Sparkplug::ValueKind::Numeric)
    out.numericValue = numericFromRaw(out.datatype, scratch.raw);
}

atic bool readMetricString(QByteArrayView data,
                             qsizetype& pos,
                             quint32 field,
                             quint32 wire,
                             Sparkplug::Metric& out,
                             SparkplugDetail::MetricScratch& scratch)
{
  SS_ASSERT(field == Sparkplug::kMetricName || field == Sparkplug::kMetricStringValue,
            return false);
  SS_ASSERT(pos >= 0 && pos <= data.size(), return false);

  if (wire != Sparkplug::kWireLengthDelimited)
    return false;

  QByteArrayView block;
  if (!readLengthDelimited(data, pos, block))
    return false;

  const bool is_name    = (field == Sparkplug::kMetricName);
  const qsizetype limit = is_name ? Sparkplug::kMaxIdentityBytes : Sparkplug::kMaxStringBytes;
  if (block.size() > limit)
    return false;

  if (is_name) {
    out.name    = QString::fromUtf8(block.data(), block.size());
    out.hasName = true;
    return true;
  }

  out.stringValue = QString::fromUtf8(block.data(), block.size());
  scratch.field   = field;
  return true;
}

atic bool readMetricReal(QByteArrayView data,
                           qsizetype& pos,
                           quint32 field,
                           quint32 wire,
                           SparkplugDetail::MetricScratch& scratch)
{
  SS_ASSERT(field == Sparkplug::kMetricFloatValue || field == Sparkplug::kMetricDoubleValue,
            return false);
  SS_ASSERT(pos >= 0 && pos <= data.size(), return false);

  const bool is_float    = (field == Sparkplug::kMetricFloatValue);
  const quint32 expected = is_float ? Sparkplug::kWireFixed32 : Sparkplug::kWireFixed64;
  if (wire != expected)
    return false;

  quint64 raw = 0;
  if (!readFixed(data, pos, is_float ? 4 : 8, raw))
    return false;

  scratch.raw   = raw;
  scratch.field = field;
  return true;
}

atic bool readMetricVarint(QByteArrayView data,
                             qsizetype& pos,
                             quint32 field,
                             quint32 wire,
                             Sparkplug::Metric& out,
                             SparkplugDetail::MetricScratch& scratch)
{
  SS_ASSERT(field > 0, return false);
  SS_ASSERT(pos >= 0 && pos <= data.size(), return false);

  if (wire != Sparkplug::kWireVarint)
    return false;

  quint64 raw = 0;
  if (!readVarint(data, pos, raw))
    return false;

  switch (field) {
    case Sparkplug::kMetricAlias:
      out.alias    = raw;
      out.hasAlias = true;
      return true;
    case Sparkplug::kMetricTimestamp:
      out.timestampMs = raw;
      return true;
    case Sparkplug::kMetricDatatype:
      out.datatype = static_cast<quint32>(raw);
      return true;
    case Sparkplug::kMetricIsNull:
      out.isNull = (raw != 0);
      return true;
    default:
      break;
  }

  scratch.raw   = raw;
  scratch.field = field;
  return true;
}

atic bool readMetricField(QByteArrayView data,
                            qsizetype& pos,
                            quint32 field,
                            quint32 wire,
                            Sparkplug::Metric& out,
                            SparkplugDetail::MetricScratch& scratch)
{
  SS_ASSERT(field > 0, return false);
  SS_ASSERT(pos >= 0 && pos <= data.size(), return false);

  if (field == Sparkplug::kMetricName || field == Sparkplug::kMetricStringValue)
    return readMetricString(data, pos, field, wire, out, scratch);

  if (field == Sparkplug::kMetricFloatValue || field == Sparkplug::kMetricDoubleValue)
    return readMetricReal(data, pos, field, wire, scratch);

  const bool is_varint = field == Sparkplug::kMetricAlias || field == Sparkplug::kMetricTimestamp
                      || field == Sparkplug::kMetricDatatype || field == Sparkplug::kMetricIsNull
                      || field == Sparkplug::kMetricIntValue || field == Sparkplug::kMetricLongValue
                      || field == Sparkplug::kMetricBooleanValue;
  if (is_varint)
    return readMetricVarint(data, pos, field, wire, out, scratch);

  return skipField(data, pos, wire);
}

atic bool decodeMetric(QByteArrayView data, Sparkplug::Metric& out, QString* error)
{
  SS_ASSERT(data.size() >= 0, return failDecode(error, QStringLiteral("invalid metric view")));
  SS_ASSERT_LOG(out.kind == Sparkplug::ValueKind::None);

  SparkplugDetail::MetricScratch scratch;
  qsizetype pos = 0;
  for (qsizetype i = 0; i < data.size() && pos < data.size(); ++i) {
    quint64 tag = 0;
    if (!readVarint(data, pos, tag))
      return failDecode(error, QStringLiteral("truncated metric field tag"));

    quint32 field = 0;
    quint32 wire  = 0;
    if (!splitTag(tag, field, wire))
      return failDecode(error, QStringLiteral("malformed metric field tag"));

    if (!readMetricField(data, pos, field, wire, out, scratch))
      return failDecode(error, QStringLiteral("malformed metric field %1").arg(field));
  }

  if (pos != data.size())
    return failDecode(error, QStringLiteral("metric field count exceeded"));

  finalizeMetric(out, scratch);
  return true;
}

atic bool readPayloadVarint(
  QByteArrayView data, qsizetype& pos, quint32 field, quint32 wire, Sparkplug::Payload& out)
{
  SS_ASSERT(field == Sparkplug::kPayloadTimestamp || field == Sparkplug::kPayloadSeq, return false);
  SS_ASSERT(pos >= 0 && pos <= data.size(), return false);

  if (wire != Sparkplug::kWireVarint)
    return false;

  quint64 raw = 0;
  if (!readVarint(data, pos, raw))
    return false;

  if (field == Sparkplug::kPayloadTimestamp) {
    out.timestampMs  = raw;
    out.hasTimestamp = true;
    return true;
  }

  out.seq    = raw;
  out.hasSeq = true;
  return true;
}

atic bool readPayloadMetric(
  QByteArrayView data, qsizetype& pos, quint32 wire, Sparkplug::Payload& out, QString* error)
{
  SS_ASSERT(pos >= 0 && pos <= data.size(),
            return failDecode(error, QStringLiteral("invalid payload cursor")));
  SS_ASSERT_LOG(out.metrics.size() <= Sparkplug::kMaxMetrics);

  if (wire != Sparkplug::kWireLengthDelimited)
    return failDecode(error, QStringLiteral("metrics field has wire type %1").arg(wire));

  QByteArrayView block;
  if (!readLengthDelimited(data, pos, block))
    return failDecode(error, QStringLiteral("truncated metric"));

  if (out.metrics.size() >= Sparkplug::kMaxMetrics)
    return failDecode(
      error, QStringLiteral("payload carries more than %1 metrics").arg(Sparkplug::kMaxMetrics));

  Sparkplug::Metric metric;
  if (!decodeMetric(block, metric, error))
    return false;

  out.metrics.append(std::move(metric));
  return true;
}

atic bool readPayloadField(QByteArrayView data,
                             qsizetype& pos,
                             quint32 field,
                             quint32 wire,
                             Sparkplug::Payload& out,
                             QString* error)
{
  SS_ASSERT(pos >= 0 && pos <= data.size(),
            return failDecode(error, QStringLiteral("invalid payload cursor")));
  SS_ASSERT(field > 0, return failDecode(error, QStringLiteral("field number 0 is reserved")));

  if (field == Sparkplug::kPayloadMetrics)
    return readPayloadMetric(data, pos, wire, out, error);

  const bool is_scalar = field == Sparkplug::kPayloadTimestamp || field == Sparkplug::kPayloadSeq;
  if (is_scalar && !readPayloadVarint(data, pos, field, wire, out))
    return failDecode(error, QStringLiteral("malformed payload field %1").arg(field));

  if (!is_scalar && !skipField(data, pos, wire))
    return failDecode(error, QStringLiteral("malformed payload field %1").arg(field));

  return true;
}

atic void appendVarint(QByteArray& out, quint64 value)
{
  SS_ASSERT_LOG(out.size() >= 0);

  quint64 remaining = value;
  for (int i = 0; i < Sparkplug::kMaxVarintBytes; ++i) {
    const auto byte   = static_cast<quint8>(remaining & 0x7Fu);
    remaining       >>= 7;
    if (remaining == 0) {
      out.append(static_cast<char>(byte));
      return;
    }

    out.append(static_cast<char>(byte | 0x80u));
  }

  SS_ASSERT_LOG(remaining == 0);
}

atic void appendTag(QByteArray& out, quint32 field, quint32 wire)
{
  SS_ASSERT(field > 0, return);
  SS_ASSERT(wire <= Sparkplug::kWireFixed32, return);

  appendVarint(out, (static_cast<quint64>(field) << 3) | wire);
}

atic void appendVarintField(QByteArray& out, quint32 field, quint64 value)
{
  SS_ASSERT(field > 0, return);
  SS_ASSERT_LOG(out.size() >= 0);

  appendTag(out, field, Sparkplug::kWireVarint);
  appendVarint(out, value);
}

atic void appendLengthDelimited(QByteArray& out, quint32 field, QByteArrayView block)
{
  SS_ASSERT(field > 0, return);
  SS_ASSERT(block.size() >= 0, return);

  appendTag(out, field, Sparkplug::kWireLengthDelimited);
  appendVarint(out, static_cast<quint64>(block.size()));
  if (!block.isEmpty())
    out.append(block.data(), block.size());
}

atic void appendFixedField(QByteArray& out, quint32 field, quint64 bits, int width)
{
  SS_ASSERT(field > 0, return);
  SS_ASSERT(width == 4 || width == 8, return);

  appendTag(out, field, width == 4 ? Sparkplug::kWireFixed32 : Sparkplug::kWireFixed64);
  for (int i = 0; i < width; ++i)
    out.append(static_cast<char>((bits >> (8 * i)) & 0xFFu));
}

atic bool integerFitsDataType(quint32 datatype, double value) noexcept
{
  SS_ASSERT_LOG(std::isfinite(value));
  SS_ASSERT_LOG(value == std::trunc(value));

  switch (static_cast<Sparkplug::DataType>(datatype)) {
    case Sparkplug::DataType::Int8:
      return value >= -128.0 && value <= 127.0;
    case Sparkplug::DataType::Int16:
      return value >= -32768.0 && value <= 32767.0;
    case Sparkplug::DataType::Int32:
      return value >= -2147483648.0 && value <= 2147483647.0;
    case Sparkplug::DataType::Int64:
      return value >= -9223372036854775808.0 && value < 9223372036854775808.0;
    case Sparkplug::DataType::UInt8:
      return value >= 0.0 && value <= 255.0;
    case Sparkplug::DataType::UInt16:
      return value >= 0.0 && value <= 65535.0;
    case Sparkplug::DataType::UInt32:
      return value >= 0.0 && value <= 4294967295.0;
    case Sparkplug::DataType::UInt64:
      return value >= 0.0 && value < 18446744073709551616.0;
    default:
      break;
  }

  return false;
}

atic quint32 valueFieldFor(quint32 datatype) noexcept
{
  switch (static_cast<Sparkplug::DataType>(datatype)) {
    case Sparkplug::DataType::Int8:
    case Sparkplug::DataType::Int16:
    case Sparkplug::DataType::Int32:
    case Sparkplug::DataType::UInt8:
    case Sparkplug::DataType::UInt16:
    case Sparkplug::DataType::UInt32:
      return Sparkplug::kMetricIntValue;
    case Sparkplug::DataType::Int64:
    case Sparkplug::DataType::UInt64:
      return Sparkplug::kMetricLongValue;
    case Sparkplug::DataType::Float:
      return Sparkplug::kMetricFloatValue;
    case Sparkplug::DataType::Double:
      return Sparkplug::kMetricDoubleValue;
    case Sparkplug::DataType::Boolean:
      return Sparkplug::kMetricBooleanValue;
    case Sparkplug::DataType::String:
    case Sparkplug::DataType::Text:
    case Sparkplug::DataType::Uuid:
      return Sparkplug::kMetricStringValue;
    default:
      break;
  }

  return 0;
}

atic quint64 rawFromNumeric(quint32 datatype, double value) noexcept
{
  SS_ASSERT(Sparkplug::numericFitsDataType(datatype, value), return 0);
  SS_ASSERT_LOG(Sparkplug::kindForDataType(datatype) == Sparkplug::ValueKind::Numeric);

  switch (static_cast<Sparkplug::DataType>(datatype)) {
    case Sparkplug::DataType::Int8:
      return static_cast<quint8>(static_cast<qint8>(value));
    case Sparkplug::DataType::Int16:
      return static_cast<quint16>(static_cast<qint16>(value));
    case Sparkplug::DataType::Int32:
      return static_cast<quint32>(static_cast<qint32>(value));
    case Sparkplug::DataType::Int64:
      return static_cast<quint64>(static_cast<qint64>(value));
    case Sparkplug::DataType::UInt8:
    case Sparkplug::DataType::UInt16:
    case Sparkplug::DataType::UInt32:
    case Sparkplug::DataType::UInt64:
      return static_cast<quint64>(value);
    case Sparkplug::DataType::Float:
      return std::bit_cast<quint32>(static_cast<float>(value));
    case Sparkplug::DataType::Double:
      return std::bit_cast<quint64>(value);
    default:
      break;
  }

  return 0;
}

atic bool encodeMetricValue(QByteArray& out, const Sparkplug::Metric& metric)
{
  const auto kind = Sparkplug::kindForDataType(metric.datatype);
  SS_ASSERT(kind != Sparkplug::ValueKind::None, return false);
  SS_ASSERT_LOG(valueFieldFor(metric.datatype) > 0);

  if (kind == Sparkplug::ValueKind::String) {
    const QByteArray utf8 = metric.stringValue.toUtf8();
    if (utf8.size() > Sparkplug::kMaxStringBytes)
      return false;

    appendLengthDelimited(out, Sparkplug::kMetricStringValue, utf8);
    return true;
  }

  if (kind == Sparkplug::ValueKind::Boolean) {
    appendVarintField(out, Sparkplug::kMetricBooleanValue, metric.boolValue ? 1 : 0);
    return true;
  }

  if (!Sparkplug::numericFitsDataType(metric.datatype, metric.numericValue))
    return false;

  const quint32 field = valueFieldFor(metric.datatype);
  const quint64 raw   = rawFromNumeric(metric.datatype, metric.numericValue);
  if (field == Sparkplug::kMetricFloatValue || field == Sparkplug::kMetricDoubleValue) {
    appendFixedField(out, field, raw, field == Sparkplug::kMetricFloatValue ? 4 : 8);
    return true;
  }

  appendVarintField(out, field, raw);
  return true;
}

atic bool encodeMetric(const Sparkplug::Metric& metric, QByteArray& out)
{
  SS_ASSERT(out.isEmpty(), return false);
  SS_ASSERT_LOG(metric.hasName || metric.hasAlias);

  if (metric.hasName) {
    const QByteArray name = metric.name.toUtf8();
    if (name.size() > Sparkplug::kMaxIdentityBytes)
      return false;

    appendLengthDelimited(out, Sparkplug::kMetricName, name);
  }

  if (metric.hasAlias)
    appendVarintField(out, Sparkplug::kMetricAlias, metric.alias);

  if (metric.timestampMs != 0)
    appendVarintField(out, Sparkplug::kMetricTimestamp, metric.timestampMs);

  appendVarintField(out, Sparkplug::kMetricDatatype, metric.datatype);

  if (metric.isNull) {
    appendVarintField(out, Sparkplug::kMetricIsNull, 1);
    return true;
  }

  return Sparkplug::isSupportedDataType(metric.datatype) && encodeMetricValue(out, metric);
}

ol IO::Drivers::SparkplugB::decodePayload(QByteArrayView data, Payload& out, QString* error)
{
  SS_ASSERT(data.size() >= 0, return failDecode(error, QStringLiteral("invalid payload view")));

  out = Payload();
  if (error)
    error->clear();

  if (data.size() > kMaxPayloadBytes)
    return failDecode(error, QStringLiteral("payload exceeds %1 bytes").arg(kMaxPayloadBytes));

  qsizetype pos = 0;
  for (qsizetype i = 0; i < data.size() && pos < data.size(); ++i) {
    quint64 tag = 0;
    if (!readVarint(data, pos, tag))
      return failDecode(error, QStringLiteral("truncated payload field tag"));

    quint32 field = 0;
    quint32 wire  = 0;
    if (!splitTag(tag, field, wire))
      return failDecode(error, QStringLiteral("malformed payload field tag"));

    if (!readPayloadField(data, pos, field, wire, out, error))
      return false;
  }

  if (pos != data.size())
    return failDecode(error, QStringLiteral("payload field count exceeded"));

  SS_ASSERT_LOG(out.metrics.size() <= kMaxMetrics);
  return true;
}

ol IO::Drivers::SparkplugB::numericFitsDataType(quint32 datatype, double value) noexcept
{
  if (kindForDataType(datatype) != ValueKind::Numeric || !std::isfinite(value))
    return false;

  switch (static_cast<DataType>(datatype)) {
    case DataType::Double:
      return true;
    case DataType::Float:
      return std::fabs(value) <= static_cast<double>(std::numeric_limits<float>::max());
    default:
      break;
  }

  if (value != std::trunc(value))
    return false;

  return integerFitsDataType(datatype, value);
}

yteArray IO::Drivers::SparkplugB::encodePayload(const Payload& payload)
{
  SS_ASSERT(payload.metrics.size() <= kMaxMetrics, return QByteArray());
  SS_ASSERT_LOG(payload.seq < 256 || !payload.hasSeq);

  QByteArray out;
  out.reserve(32 + payload.metrics.size() * 32);

  if (payload.hasTimestamp)
    appendVarintField(out, kPayloadTimestamp, payload.timestampMs);

  if (payload.hasSeq)
    appendVarintField(out, kPayloadSeq, payload.seq);

  QByteArray metric;
  metric.reserve(64);
  for (const auto& entry : payload.metrics) {
    metric.resize(0);
    if (!encodeMetric(entry, metric))
      continue;

    appendLengthDelimited(out, kPayloadMetrics, metric);
  }

  SS_ASSERT_LOG(out.size() <= kMaxPayloadBytes);
  return out;
}

yteArray IO::Drivers::SparkplugB::encodeRebirthRequest(quint64 timestampMs)
{
  const QByteArray name(kRebirthMetricName);
  SS_ASSERT(!name.isEmpty(), return QByteArray());

  QByteArray metric;
  metric.reserve(name.size() + 16);
  appendTag(metric, kMetricName, kWireLengthDelimited);
  appendVarint(metric, static_cast<quint64>(name.size()));
  metric.append(name);
  appendTag(metric, kMetricDatatype, kWireVarint);
  appendVarint(metric, static_cast<quint64>(DataType::Boolean));
  appendTag(metric, kMetricBooleanValue, kWireVarint);
  appendVarint(metric, 1);

  QByteArray payload;
  payload.reserve(metric.size() + 16);
  appendTag(payload, kPayloadTimestamp, kWireVarint);
  appendVarint(payload, timestampMs);
  appendTag(payload, kPayloadMetrics, kWireLengthDelimited);
  appendVarint(payload, static_cast<quint64>(metric.size()));
  payload.append(metric);

  SS_ASSERT_LOG(payload.size() > metric.size());
  return payload;
}

atic QString nodeKey(const QString& group, const QString& node)
{
  SS_ASSERT_LOG(group.size() >= 0);
  SS_ASSERT_LOG(node.size() >= 0);

  QString key;
  key.reserve(group.size() + node.size() + 1);
  key.append(group);
  key.append(QChar(u'\x1f'));
  key.append(node);
  return key;
}

atic QString slotKey(const QString& group,
                       const QString& node,
                       const QString& device,
                       const QString& metric)
{
  SS_ASSERT_LOG(node.size() >= 0);
  SS_ASSERT_LOG(metric.size() >= 0);

  QString key;
  key.reserve(group.size() + node.size() + device.size() + metric.size() + 3);
  key.append(nodeKey(group, node));
  key.append(QChar(u'\x1f'));
  key.append(device);
  key.append(QChar(u'\x1f'));
  key.append(metric);
  return key;
}

atic QString slotLabel(const QString& node, const QString& device, const QString& metric)
{
  SS_ASSERT_LOG(node.size() >= 0);
  SS_ASSERT_LOG(metric.size() >= 0);

  if (device.isEmpty())
    return QStringLiteral("%1/%2").arg(node, metric);

  return QStringLiteral("%1/%2/%3").arg(node, device, metric);
}

atic bool splitTopic(QStringView topic, QStringView* parts, int max, int& count)
{
  SS_ASSERT(parts != nullptr, return false);
  SS_ASSERT(max > 0, return false);

  count               = 0;
  qsizetype start     = 0;
  const qsizetype end = topic.size();
  for (qsizetype i = 0; i <= end; ++i) {
    if (i < end && topic[i] != QLatin1Char('/'))
      continue;

    if (count >= max)
      return false;

    parts[count] = topic.sliced(start, i - start);
    start        = i + 1;
    ++count;
  }

  return count > 0;
}

atic bool identitiesFit(const QStringView* parts, int count)
{
  SS_ASSERT(parts != nullptr, return false);
  SS_ASSERT(count > 0, return false);

  for (int i = 0; i < count; ++i)
    if (parts[i].size() > Sparkplug::kMaxIdentityBytes)
      return false;

  return true;
}

::Drivers::SparkplugSession::SparkplugSession()
  : m_newMetrics(0), m_dirtyCount(0), m_flushing(false)
{
  SS_ASSERT_LOG(m_slots.isEmpty());
  SS_ASSERT_LOG(m_counters.seqGaps == 0);
}

id IO::Drivers::SparkplugSession::reset()
{
  m_nodes.clear();
  m_slots.clear();
  m_slotIndex.clear();
  m_preBirth.clear();
  m_rebirthTopics.clear();

  m_counters   = Counters();
  m_newMetrics = 0;
  m_dirtyCount = 0;
  m_flushing   = false;

  SS_ASSERT_LOG(m_slots.isEmpty());
  SS_ASSERT_LOG(m_nodes.isEmpty());
}

id IO::Drivers::SparkplugSession::markGenerated()
{
  SS_ASSERT_LOG(m_slots.size() <= SpLimits::kMaxSlots);
  SS_ASSERT_LOG(m_slotIndex.size() == m_slots.size());

  m_newMetrics = 0;
}

id IO::Drivers::SparkplugSession::setGroupFilter(const QString& group)
{
  SS_ASSERT_LOG(group.size() >= 0);
  SS_ASSERT_LOG(m_groupFilter.size() >= 0);

  if (m_groupFilter == group)
    return;

  m_groupFilter = group;
  reset();
}

nst IO::Drivers::SparkplugSession::Counters& IO::Drivers::SparkplugSession::counters()
  const noexcept
{
  return m_counters;
}

nst QVector<IO::Drivers::SparkplugSession::SlotValue>& IO::Drivers::SparkplugSession::slotValues()
  const noexcept
{
  return m_slots;
}

tringList IO::Drivers::SparkplugSession::takeRebirthTopics()
{
  SS_ASSERT_LOG(m_rebirthTopics.size() <= SpLimits::kMaxNodes);
  SS_ASSERT_LOG(m_nodes.size() <= SpLimits::kMaxNodes);

  QStringList topics;
  topics.swap(m_rebirthTopics);
  return topics;
}

::Drivers::SparkplugSession::MessageType IO::Drivers::SparkplugSession::messageType(
  QStringView token, int count) noexcept
{
  SS_ASSERT_LOG(count >= 4);
  SS_ASSERT_LOG(count <= SpLimits::kMaxTopicElements);

  if (count == 4 && token == QLatin1StringView("NBIRTH"))
    return MessageType::NodeBirth;

  if (count == 4 && token == QLatin1StringView("NDATA"))
    return MessageType::NodeData;

  if (count == 4 && token == QLatin1StringView("NDEATH"))
    return MessageType::NodeDeath;

  if (count == 5 && token == QLatin1StringView("DBIRTH"))
    return MessageType::DeviceBirth;

  if (count == 5 && token == QLatin1StringView("DDATA"))
    return MessageType::DeviceData;

  if (count == 5 && token == QLatin1StringView("DDEATH"))
    return MessageType::DeviceDeath;

  return MessageType::Ignored;
}

ol IO::Drivers::SparkplugSession::parseTopic(QStringView topic, TopicInfo& out) const
{
  SS_ASSERT_LOG(out.type == MessageType::Ignored);
  SS_ASSERT_LOG(m_groupFilter.size() >= 0);

  QStringView parts[SpLimits::kMaxTopicElements];
  int count = 0;
  if (!splitTopic(topic, parts, SpLimits::kMaxTopicElements, count))
    return false;

  if (!identitiesFit(parts, count))
    return false;

  if (count < 3 || parts[0] != QLatin1StringView(SpLimits::kNamespace))
    return false;

  if (count == 3)
    return parts[1] == QLatin1StringView("STATE");

  if (count < 4 || parts[1].isEmpty() || parts[3].isEmpty())
    return false;

  if (count == SpLimits::kMaxTopicElements && parts[4].isEmpty())
    return false;

  if (!m_groupFilter.isEmpty() && parts[1] != m_groupFilter)
    return false;

  out.type  = messageType(parts[2], count);
  out.group = parts[1].toString();
  out.node  = parts[3].toString();
  if (count == SpLimits::kMaxTopicElements)
    out.device = parts[4].toString();

  return true;
}

ol IO::Drivers::SparkplugSession::ingest(QStringView topic, QByteArrayView payload)
{
  SS_ASSERT_LOG(m_slots.size() <= SpLimits::kMaxSlots);
  SS_ASSERT_LOG(m_preBirth.size() <= SpLimits::kMaxPreBirthMessages);

  TopicInfo info;
  if (!parseTopic(topic, info))
    return false;

  if (info.type == MessageType::Ignored) {
    ++m_counters.ignoredMessages;
    return true;
  }

  Sparkplug::Payload decoded;
  if (!Sparkplug::decodePayload(payload, decoded, nullptr)) {
    ++m_counters.decodeErrors;
    return true;
  }

  switch (info.type) {
    case MessageType::NodeBirth:
    case MessageType::DeviceBirth:
      handleBirth(info, decoded);
      break;
    case MessageType::NodeData:
    case MessageType::DeviceData:
      handleData(info, decoded, topic, payload);
      break;
    case MessageType::NodeDeath:
    case MessageType::DeviceDeath:
      handleDeath(info, decoded);
      break;
    case MessageType::Ignored:
      break;
  }

  return true;
}

id IO::Drivers::SparkplugSession::handleBirth(const TopicInfo& info,
                                                const SparkplugB::Payload& payload)
{
  SS_ASSERT_LOG(info.type == MessageType::NodeBirth || info.type == MessageType::DeviceBirth);
  SS_ASSERT_LOG(payload.metrics.size() <= Sparkplug::kMaxMetrics);

  NodeState* node = nodeState(info, true);
  if (!node)
    return;

  const bool node_birth = (info.type == MessageType::NodeBirth);
  if (node_birth) {
    node->aliasSlots.clear();
    node->devices.clear();
  }

  node->born           = true;
  node->lastSeq        = payload.seq % SpLimits::kSeqModulus;
  node->hasSeq         = payload.hasSeq;
  node->rebirthPending = false;
  if (node->onlineSlot < 0)
    node->onlineSlot =
      ensureSlot(info.group, info.node, QString(), QString::fromLatin1(SpLimits::kOnlineMetric));

  setOnline(*node, true, payload.timestampMs);

  QHash<quint64, int>* aliases = &node->aliasSlots;
  if (!node_birth) {
    DeviceState* device = deviceState(*node, info.device);
    if (!device)
      return;

    device->born = true;
    device->aliasSlots.clear();
    aliases = &device->aliasSlots;
  }

  registerBirthMetrics(info, *aliases, payload);
  flushPreBirth(info);
}

id IO::Drivers::SparkplugSession::registerBirthMetrics(const TopicInfo& info,
                                                         QHash<quint64, int>& aliases,
                                                         const SparkplugB::Payload& payload)
{
  SS_ASSERT_LOG(payload.metrics.size() <= Sparkplug::kMaxMetrics);
  SS_ASSERT_LOG(m_slots.size() <= SpLimits::kMaxSlots);

  for (const auto& metric : payload.metrics) {
    if (!metric.hasName) {
      ++m_counters.unsupportedMetrics;
      continue;
    }

    const int index = ensureSlot(info.group, info.node, info.device, metric.name);
    if (index < 0)
      continue;

    if (metric.hasAlias)
      registerAlias(aliases, metric.alias, index);

    applyMetric(index, metric, payload.timestampMs);
  }
}

id IO::Drivers::SparkplugSession::flushPreBirth(const TopicInfo& info)
{
  SS_ASSERT_LOG(m_preBirth.size() <= SpLimits::kMaxPreBirthMessages);
  SS_ASSERT_LOG(!m_flushing);

  if (m_flushing || m_preBirth.isEmpty())
    return;

  QList<PendingMessage> pending;
  pending.swap(m_preBirth);
  m_flushing = true;

  for (qsizetype i = 0; i < pending.size() && i < SpLimits::kMaxPreBirthMessages; ++i) {
    const PendingMessage& message = pending.at(i);
    const bool mine =
      message.node == info.node && message.group == info.group && message.device == info.device;
    if (!mine) {
      m_preBirth.append(message);
      continue;
    }

    const bool consumed = ingest(message.topic, message.payload);
    SS_ASSERT_LOG(consumed);
  }

  m_flushing = false;
}

id IO::Drivers::SparkplugSession::handleData(const TopicInfo& info,
                                               const SparkplugB::Payload& payload,
                                               QStringView topic,
                                               QByteArrayView raw)
{
  SS_ASSERT_LOG(info.type == MessageType::NodeData || info.type == MessageType::DeviceData);
  SS_ASSERT_LOG(payload.metrics.size() <= Sparkplug::kMaxMetrics);

  NodeState* node = nodeState(info, true);
  if (!node)
    return;

  if (!m_flushing)
    checkSequence(info, *node, payload);

  const QHash<quint64, int>* aliases = aliasTable(*node, info);
  if (!aliases || !resolvable(*aliases, payload)) {
    bufferMessage(info, topic, raw);
    flagRebirth(info, *node);
    return;
  }

  applyMetrics(info, *node, payload);
}

nst QHash<quint64, int>* IO::Drivers::SparkplugSession::aliasTable(const NodeState& node,
                                                                     const TopicInfo& info) const
{
  SS_ASSERT_LOG(node.devices.size() <= SpLimits::kMaxDevicesPerNode);
  SS_ASSERT_LOG(info.type != MessageType::Ignored);

  if (!node.born)
    return nullptr;

  if (info.device.isEmpty())
    return &node.aliasSlots;

  const auto it = node.devices.constFind(info.device);
  if (it == node.devices.constEnd() || !it->born)
    return nullptr;

  return &it->aliasSlots;
}

ol IO::Drivers::SparkplugSession::resolvable(const QHash<quint64, int>& aliases,
                                               const SparkplugB::Payload& payload) const
{
  SS_ASSERT_LOG(payload.metrics.size() <= Sparkplug::kMaxMetrics);
  SS_ASSERT_LOG(aliases.size() <= SpLimits::kMaxSlots);

  for (const auto& metric : payload.metrics) {
    if (metric.hasName || !metric.hasAlias)
      continue;

    if (!aliases.contains(metric.alias))
      return false;
  }

  return true;
}

id IO::Drivers::SparkplugSession::applyMetrics(const TopicInfo& info,
                                                 NodeState& node,
                                                 const SparkplugB::Payload& payload)
{
  SS_ASSERT_LOG(node.born);
  SS_ASSERT_LOG(payload.metrics.size() <= Sparkplug::kMaxMetrics);

  QHash<quint64, int>* aliases = &node.aliasSlots;
  if (!info.device.isEmpty()) {
    const auto it = node.devices.find(info.device);
    if (it == node.devices.end())
      return;

    aliases = &it->aliasSlots;
  }

  for (const auto& metric : payload.metrics) {
    const int index = slotForMetric(info, *aliases, metric);
    if (index < 0)
      continue;

    applyMetric(index, metric, payload.timestampMs);
  }
}

t IO::Drivers::SparkplugSession::slotForMetric(const TopicInfo& info,
                                                 QHash<quint64, int>& aliases,
                                                 const SparkplugB::Metric& metric)
{
  SS_ASSERT_LOG(aliases.size() <= SpLimits::kMaxSlots);
  SS_ASSERT_LOG(m_slots.size() <= SpLimits::kMaxSlots);

  if (!metric.hasName) {
    if (!metric.hasAlias) {
      ++m_counters.unsupportedMetrics;
      return -1;
    }

    const auto it = aliases.constFind(metric.alias);
    return (it == aliases.constEnd()) ? -1 : *it;
  }

  const int index = ensureSlot(info.group, info.node, info.device, metric.name);
  if (index >= 0 && metric.hasAlias)
    registerAlias(aliases, metric.alias, index);

  return index;
}

id IO::Drivers::SparkplugSession::applyMetric(int index,
                                                const SparkplugB::Metric& metric,
                                                quint64 fallbackMs)
{
  SS_ASSERT(index >= 0 && index < static_cast<int>(m_slots.size()), return);
  SS_ASSERT_LOG(m_slots.size() <= SpLimits::kMaxSlots);

  if (!metric.supported) {
    ++m_counters.unsupportedMetrics;
    return;
  }

  if (metric.isNull)
    return;

  SlotValue& slot  = m_slots[index];
  slot.kind        = metric.kind;
  slot.timestampMs = (metric.timestampMs != 0) ? metric.timestampMs : fallbackMs;

  switch (metric.kind) {
    case Sparkplug::ValueKind::Numeric:
      slot.num = metric.numericValue;
      break;
    case Sparkplug::ValueKind::Boolean:
      slot.b = metric.boolValue;
      break;
    case Sparkplug::ValueKind::String:
      slot.str = metric.stringValue.left(SpWire::kMaxStringBytes);
      break;
    case Sparkplug::ValueKind::None:
      break;
  }

  markDirty(slot);
}

id IO::Drivers::SparkplugSession::checkSequence(const TopicInfo& info,
                                                  NodeState& node,
                                                  const SparkplugB::Payload& payload)
{
  SS_ASSERT_LOG(!m_flushing);
  SS_ASSERT_LOG(node.lastSeq < SpLimits::kSeqModulus);

  if (!payload.hasSeq)
    return;

  const quint64 seq      = payload.seq % SpLimits::kSeqModulus;
  const quint64 expected = (node.lastSeq + 1) % SpLimits::kSeqModulus;
  const bool first       = !node.hasSeq;

  node.lastSeq = seq;
  node.hasSeq  = true;
  if (first || seq == expected)
    return;

  ++m_counters.seqGaps;
  flagRebirth(info, node);
}

id IO::Drivers::SparkplugSession::handleDeath(const TopicInfo& info,
                                                const SparkplugB::Payload& payload)
{
  SS_ASSERT_LOG(info.type == MessageType::NodeDeath || info.type == MessageType::DeviceDeath);
  SS_ASSERT_LOG(m_slots.size() <= SpLimits::kMaxSlots);

  NodeState* node = nodeState(info, false);
  if (!node) {
    ++m_counters.ignoredMessages;
    return;
  }

  if (info.type == MessageType::DeviceDeath) {
    const auto it = node->devices.find(info.device);
    if (it != node->devices.end())
      it->born = false;

    return;
  }

  node->born   = false;
  node->hasSeq = false;
  for (auto it = node->devices.begin(); it != node->devices.end(); ++it)
    it->born = false;

  setOnline(*node, false, payload.timestampMs);
}

id IO::Drivers::SparkplugSession::setOnline(NodeState& node, bool online, quint64 timestampMs)
{
  SS_ASSERT_LOG(node.onlineSlot < static_cast<int>(m_slots.size()));
  SS_ASSERT_LOG(m_slots.size() <= SpLimits::kMaxSlots);

  if (node.onlineSlot < 0)
    return;

  SlotValue& slot  = m_slots[node.onlineSlot];
  slot.kind        = Sparkplug::ValueKind::Boolean;
  slot.b           = online;
  slot.num         = online ? 1.0 : 0.0;
  slot.timestampMs = timestampMs;
  markDirty(slot);
}

id IO::Drivers::SparkplugSession::bufferMessage(const TopicInfo& info,
                                                  QStringView topic,
                                                  QByteArrayView payload)
{
  SS_ASSERT_LOG(m_preBirth.size() <= SpLimits::kMaxPreBirthMessages);
  SS_ASSERT_LOG(payload.size() >= 0);

  if (m_flushing) {
    ++m_counters.preBirthDropped;
    return;
  }

  if (m_preBirth.size() >= SpLimits::kMaxPreBirthMessages) {
    m_preBirth.removeFirst();
    ++m_counters.preBirthDropped;
  }

  PendingMessage message;
  message.topic   = topic.toString();
  message.node    = info.node;
  message.group   = info.group;
  message.device  = info.device;
  message.payload = payload.toByteArray();

  m_preBirth.append(message);
  ++m_counters.preBirthBuffered;
}

id IO::Drivers::SparkplugSession::flagRebirth(const TopicInfo& info, NodeState& node)
{
  SS_ASSERT_LOG(m_rebirthTopics.size() <= SpLimits::kMaxNodes);
  SS_ASSERT_LOG(m_nodes.size() <= SpLimits::kMaxNodes);

  if (node.rebirthPending)
    return;

  node.rebirthPending = true;
  ++m_counters.rebirthRequests;
  if (m_rebirthTopics.size() >= SpLimits::kMaxNodes)
    return;

  const QString space = QString::fromLatin1(SpLimits::kNamespace);
  m_rebirthTopics.append(QStringLiteral("%1/%2/NCMD/%3").arg(space, info.group, info.node));
}

::Drivers::SparkplugSession::NodeState* IO::Drivers::SparkplugSession::nodeState(
  const TopicInfo& info, bool create)
{
  SS_ASSERT_LOG(m_nodes.size() <= SpLimits::kMaxNodes);
  SS_ASSERT(!info.node.isEmpty(), return nullptr);

  const QString name = nodeKey(info.group, info.node);
  const auto it      = m_nodes.find(name);
  if (it != m_nodes.end())
    return &it.value();

  if (!create)
    return nullptr;

  if (m_nodes.size() >= SpLimits::kMaxNodes) {
    ++m_counters.capDrops;
    return nullptr;
  }

  return &m_nodes.insert(name, NodeState()).value();
}

::Drivers::SparkplugSession::DeviceState* IO::Drivers::SparkplugSession::deviceState(
  NodeState& node, const QString& name)
{
  SS_ASSERT_LOG(node.devices.size() <= SpLimits::kMaxDevicesPerNode);
  SS_ASSERT(!name.isEmpty(), return nullptr);

  const auto it = node.devices.find(name);
  if (it != node.devices.end())
    return &it.value();

  if (node.devices.size() >= SpLimits::kMaxDevicesPerNode) {
    ++m_counters.capDrops;
    return nullptr;
  }

  return &node.devices.insert(name, DeviceState()).value();
}

t IO::Drivers::SparkplugSession::ensureSlot(const QString& group,
                                              const QString& node,
                                              const QString& device,
                                              const QString& metric)
{
  SS_ASSERT_LOG(m_slots.size() <= SpLimits::kMaxSlots);
  SS_ASSERT_LOG(m_slotIndex.size() == m_slots.size());

  if (node.isEmpty() || metric.isEmpty()) {
    ++m_counters.unsupportedMetrics;
    return -1;
  }

  const bool oversized = node.size() > Sparkplug::kMaxIdentityBytes
                      || device.size() > Sparkplug::kMaxIdentityBytes
                      || metric.size() > Sparkplug::kMaxIdentityBytes;
  if (oversized) {
    ++m_counters.capDrops;
    return -1;
  }

  const QString key = slotKey(group, node, device, metric);
  const auto it     = m_slotIndex.constFind(key);
  if (it != m_slotIndex.constEnd())
    return *it;

  if (m_slots.size() >= SpLimits::kMaxSlots) {
    ++m_counters.capDrops;
    return -1;
  }

  SlotValue slot;
  slot.index       = static_cast<int>(m_slots.size());
  slot.name        = metric;
  slot.node        = node;
  slot.group       = group;
  slot.device      = device;
  slot.displayName = slotLabel(node, device, metric);

  m_slotIndex.insert(key, slot.index);
  m_slots.append(slot);
  ++m_newMetrics;
  return slot.index;
}

id IO::Drivers::SparkplugSession::registerAlias(QHash<quint64, int>& aliases,
                                                  quint64 alias,
                                                  int index)
{
  SS_ASSERT(index >= 0, return);
  SS_ASSERT_LOG(aliases.size() <= SpLimits::kMaxSlots);

  if (aliases.size() >= SpLimits::kMaxSlots && !aliases.contains(alias)) {
    ++m_counters.capDrops;
    return;
  }

  aliases.insert(alias, index);
}

id IO::Drivers::SparkplugSession::markDirty(SlotValue& slot)
{
  SS_ASSERT_LOG(slot.index >= 0);
  SS_ASSERT_LOG(m_dirtyCount <= m_slots.size());

  if (slot.dirty)
    return;

  slot.dirty = true;
  ++m_dirtyCount;
}

id IO::Drivers::S7PollWorker::configure(
  const QString& host, int rack, int slot, int interval, QVector<S7ReadItem> items)
{
  SS_ASSERT(!items.isEmpty(), return);
  SS_ASSERT_LOG(interval >= kS7MinIntervalMs);

  m_host     = host;
  m_rack     = rack;
  m_slot     = slot;
  m_interval = interval;
  m_items    = std::move(items);
  m_values   = QList<QVariant>(m_items.size());
  m_dirty    = QList<bool>(m_items.size(), false);

  m_reads.clear();
  m_reads.reserve(m_items.size());
  for (const auto& item : m_items)
    m_reads.append(S7Comm::itemForAddress(item.address));

  qsizetype bytes = OpcUaWire::kHeaderBytes;
  for (const auto& item : m_items)
    bytes += OpcUaWire::maxEntryBytes(item.wireType);

  const auto reserve = qMin<qsizetype>(bytes, OpcUaWire::kMaxFrameBytes);
  m_frames[0].reserve(reserve);
  m_frames[1].reserve(reserve);
}

ol IO::Drivers::S7PollWorker::connectToPlc()
{
  SS_ASSERT(!m_open, return true);
  SS_ASSERT(!m_reads.isEmpty(), return false);

  m_abort.store(false, std::memory_order_relaxed);
  m_dialError.clear();
  if (!dial()) {
    shutdown();
    return false;
  }

  m_open     = true;
  m_reported = false;
  m_timer    = new QTimer(this);
  m_timer->setInterval(m_interval);
  connect(m_timer, &QTimer::timeout, this, &IO::Drivers::S7PollWorker::onPollTick);
  m_timer->start();
  return true;
}

ol IO::Drivers::S7PollWorker::dial()
{
  SS_ASSERT(m_socket == nullptr, return false);
  SS_ASSERT(!m_host.isEmpty(), return false);

  m_rx.clear();
  m_codec.reset();
  m_transport.reset();

  m_socket = new QTcpSocket(this);
  m_socket->connectToHost(m_host, S7Comm::kIsoTsapPort);
  if (!m_socket->waitForConnected(kS7DialDeadlineMs)) {
    m_dialError = m_socket->errorString();
    return false;
  }

  const auto request = m_transport.buildConnectRequest(m_rack, m_slot);
  if (request.isEmpty() || m_socket->write(request) != request.size()) {
    m_dialError = tr("The ISO connection request could not be sent");
    return false;
  }

  QByteArray tpdu;
  if (!readTpdu(tpdu, kS7DialDeadlineMs) || !m_transport.parseConnectConfirm(tpdu)) {
    m_dialError = tr("The controller refused the ISO connection: check the rack and slot numbers");
    return false;
  }

  return negotiate();
}

ol IO::Drivers::S7PollWorker::negotiate()
{
  SS_ASSERT(m_socket != nullptr, return false);
  SS_ASSERT(!m_reads.isEmpty(), return false);

  const auto request = m_codec.buildSetupRequest(m_codec.nextReference());
  if (request.isEmpty() || !exchange(request, m_response)) {
    m_dialError = tr("The controller did not answer the S7comm setup request");
    return false;
  }

  if (m_codec.parseSetupResponse(m_response) != S7Comm::PduResult::Ok) {
    const auto reason = m_codec.lastError();
    m_dialError       = reason.isEmpty() ? tr("The controller refused the S7comm session") : reason;
    return false;
  }

  m_chunks = m_codec.planChunks(m_reads);
  SS_ASSERT_LOG(!m_chunks.isEmpty());
  return !m_chunks.isEmpty();
}

ol IO::Drivers::S7PollWorker::sendPdu(const QByteArray& pdu)
{
  SS_ASSERT(!pdu.isEmpty(), return false);
  SS_ASSERT(m_socket != nullptr, return false);

  const auto packet = m_transport.wrapData(pdu);
  if (packet.isEmpty() || m_socket->write(packet) != packet.size())
    return false;

  return m_socket->waitForBytesWritten(kS7ReplyDeadlineMs);
}

ol IO::Drivers::S7PollWorker::readTpdu(QByteArray& tpdu, int timeoutMs)
{
  SS_ASSERT(m_socket != nullptr, return false);
  SS_ASSERT_LOG(timeoutMs > 0);

  QElapsedTimer clock;
  clock.start();
  for (int round = 0; round < kS7MaxReadRounds; ++round) {
    if (m_abort.load(std::memory_order_relaxed))
      return false;

    m_rx.append(m_socket->readAll());

    S7Comm::Tpkt frame;
    const auto found = m_transport.extractTpkt(m_rx, frame);
    if (found == S7Comm::TpktResult::Malformed || m_rx.size() > kS7MaxReceiveBytes)
      return false;

    if (found == S7Comm::TpktResult::Ok) {
      tpdu = m_rx.mid(frame.tpduOffset, frame.tpduSize);
      m_rx.remove(0, frame.totalBytes);
      return true;
    }

    const auto left = timeoutMs - clock.elapsed();
    if (left <= 0 || !m_socket->waitForReadyRead(static_cast<int>(left)))
      return false;
  }

  return false;
}

ol IO::Drivers::S7PollWorker::exchange(const QByteArray& request, QByteArray& response)
{
  SS_ASSERT(!request.isEmpty(), return false);
  SS_ASSERT(m_socket != nullptr, return false);

  response.clear();
  if (!sendPdu(request))
    return false;

  for (int part = 0; part < kS7MaxTpdusPerReply; ++part) {
    if (m_abort.load(std::memory_order_relaxed))
      return false;

    QByteArray tpdu;
    if (!readTpdu(tpdu, kS7ReplyDeadlineMs))
      return false;

    bool complete = false;
    if (m_transport.acceptData(tpdu, response, complete) != S7Comm::TpktResult::Ok)
      return false;

    if (complete)
      return !response.isEmpty();
  }

  return false;
}

id IO::Drivers::S7PollWorker::shutdown()
{
  m_open = false;
  if (m_timer) {
    m_timer->stop();
    delete m_timer;
    m_timer = nullptr;
  }

  if (m_socket) {
    m_socket->abort();
    m_socket->close();
    delete m_socket;
    m_socket = nullptr;
  }

  m_rx.clear();
  m_chunks.clear();
  SS_ASSERT_LOG(m_timer == nullptr);
  SS_ASSERT_LOG(m_socket == nullptr);
}

id IO::Drivers::S7PollWorker::onPollTick()
{
  if (!m_open)
    return;

  const auto now       = std::chrono::steady_clock::now().time_since_epoch();
  const qint64 stampNs = std::chrono::duration_cast<std::chrono::nanoseconds>(now).count();

  SS_ASSERT_LOG(!m_chunks.isEmpty());
  for (const auto& chunk : m_chunks) {
    if (m_abort.load(std::memory_order_relaxed))
      return;

    if (pollChunk(chunk))
      continue;

    if (m_abort.load(std::memory_order_relaxed))
      return;

    reportFailure(tr("The controller closed the S7comm session"));
    return;
  }

  publishDirtySlots(stampNs);
}

ol IO::Drivers::S7PollWorker::pollChunk(const S7Comm::Chunk& chunk)
{
  SS_ASSERT(chunk.count > 0, return false);
  SS_ASSERT(chunk.first + chunk.count <= m_reads.size(), return false);

  const auto request = m_codec.buildReadRequest(m_codec.nextReference(), m_reads, chunk);
  if (request.isEmpty() || !exchange(request, m_response))
    return false;

  m_results.clear();
  const auto parsed = m_codec.parseReadResponse(m_response, chunk.count, m_results);
  if (parsed == S7Comm::PduResult::Refused) {
    m_readsFailed.fetch_add(chunk.count, std::memory_order_relaxed);
    m_itemErrors.fetch_add(chunk.count, std::memory_order_relaxed);
    return true;
  }

  if (parsed != S7Comm::PduResult::Ok)
    return false;

  for (int i = 0; i < m_results.size(); ++i)
    applyResult(chunk.first + i, m_results.at(i), m_response);

  return true;
}

id IO::Drivers::S7PollWorker::applyResult(int index,
                                            const S7Comm::ReadResult& result,
                                            QByteArrayView pdu)
{
  SS_ASSERT(index >= 0 && index < m_items.size(), return);
  SS_ASSERT(result.offset + result.size <= pdu.size(), return);

  if (result.returnCode != S7Comm::kReturnSuccess) {
    const auto fault = (static_cast<quint64>(index) + 1) << kS7FaultIndexShift;
    m_readsFailed.fetch_add(1, std::memory_order_relaxed);
    m_itemErrors.fetch_add(1, std::memory_order_relaxed);
    m_lastFault.store(fault | result.returnCode, std::memory_order_relaxed);
    return;
  }

  m_readsOk.fetch_add(1, std::memory_order_relaxed);
  const auto& address = m_items.at(index).address;
  const auto value    = S7Comm::decodeValue(address, pdu.sliced(result.offset, result.size));
  if (!value.isValid() || m_values.at(index) == value)
    return;

  m_values[index] = value;
  m_dirty[index]  = true;
}

id IO::Drivers::S7PollWorker::publishDirtySlots(qint64 stampNs)
{
  SS_ASSERT_LOG(m_dirty.size() == m_items.size());
  SS_ASSERT_LOG(stampNs > 0);

  QByteArray& frame = m_frames[m_frameSlot];
  OpcUaWire::beginFrame(frame);
  for (int i = 0; i < m_items.size(); ++i) {
    if (!m_dirty.at(i))
      continue;

    if (frame.size() + OpcUaWire::maxEntryBytes(m_items.at(i).wireType) > OpcUaWire::kMaxFrameBytes)
      break;

    OpcUaWire::appendEntry(frame, i, m_items.at(i).wireType, m_values.at(i));
    m_dirty[i] = false;
  }

  if (frame.size() <= OpcUaWire::kHeaderBytes)
    return;

  m_framesPublished.fetch_add(1, std::memory_order_relaxed);
  Q_EMIT frameReady(frame, stampNs);
  m_frameSlot ^= 1;
}

id IO::Drivers::S7PollWorker::reportFailure(const QString& reason)
{
  SS_ASSERT_LOG(!reason.isEmpty());
  if (m_reported)
    return;

  m_reported = true;
  m_open     = false;
  if (m_timer)
    m_timer->stop();

  Q_EMIT linkLost(reason);
}

::Drivers::S7::S7()
  : m_open(false)
  , m_persistent(true)
  , m_rack(0)
  , m_slot(kS7DefaultSlot)
  , m_pollInterval(kS7DefaultIntervalMs)
  , m_lastStampNs(0)
  , m_linkDrops(0)
  , m_host(QStringLiteral("192.168.0.1"))
  , m_thread(std::make_unique<QThread>())
  , m_worker(nullptr)
{
  loadSettings();

  static constexpr void (S7::* kConfigSignals[])() = {&S7::hostChanged,
                                                      &S7::rackChanged,
                                                      &S7::slotChanged,
                                                      &S7::pollIntervalChanged,
                                                      &S7::variablesChanged};
  for (const auto signal : kConfigSignals)
    connect(this, signal, this, &IO::Drivers::S7::configurationChanged);

  Q_EMIT configurationChanged();
}

id IO::Drivers::S7::loadSettings()
{
  m_host         = m_settings.value("S7Driver/host", m_host).toString();
  m_rack         = qBound(0, m_settings.value("S7Driver/rack", 0).toInt(), kS7MaxRack);
  m_slot         = qBound(0, m_settings.value("S7Driver/slot", kS7DefaultSlot).toInt(), kS7MaxSlot);
  m_pollInterval = qBound(kS7MinIntervalMs,
                          m_settings.value("S7Driver/pollInterval", kS7DefaultIntervalMs).toInt(),
                          kS7MaxIntervalMs);

  const auto doc =
    QJsonDocument::fromJson(m_settings.value("S7Driver/variables", QByteArray("[]")).toByteArray());
  if (doc.isArray())
    setVariables(doc.array());
}

id IO::Drivers::S7::saveVariables()
{
  if (!m_persistent)
    return;

  m_settings.setValue("S7Driver/variables",
                      QJsonDocument(variablesJson()).toJson(QJsonDocument::Compact));
}

id IO::Drivers::S7::refreshItems()
{
  m_items.clear();
  m_items.reserve(m_variables.size());

  for (const auto& variable : m_variables) {
    QString error;
    const auto parsed = S7Address::parse(variable.address, error);
    if (!S7Address::isValid(parsed))
      continue;

    S7ReadItem item;
    item.address  = parsed;
    item.wireType = wireTypeFor(parsed.type);
    m_items.append(item);
  }

  SS_ASSERT_LOG(m_items.size() <= m_variables.size());
  SS_ASSERT_LOG(m_items.size() <= OpcUaWire::kMaxTags);
}

id IO::Drivers::S7::setPersistent(const bool persistent) noexcept
{
  if (m_persistent == persistent)
    return;

  m_persistent = persistent;
}

id IO::Drivers::S7::setSessionPeer(S7* peer)
{
  SS_ASSERT(peer != this, return);
  if (m_sessionPeer == peer)
    return;

  m_sessionPeer = peer;
  if (peer)
    connect(peer, &QObject::destroyed, this, &IO::Drivers::S7::statusChanged, Qt::UniqueConnection);

  Q_EMIT statusChanged();
}

id IO::Drivers::S7::close()
{
  doClose();

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
}

id IO::Drivers::S7::doClose()
{
  m_open = false;
  if (!m_worker) {
    SS_ASSERT_LOG(!m_thread->isRunning());
    return;
  }

  disconnect(m_worker, nullptr, this, nullptr);
  if (m_thread->isRunning()) {
    m_worker->requestAbort();
    QMetaObject::invokeMethod(
      m_worker, [this] { m_worker->shutdown(); }, Qt::BlockingQueuedConnection);
    m_thread->quit();
    if (!m_thread->wait(kS7JoinTimeoutMs)) {
      qWarning() << "[S7] poll thread did not stop within" << kS7JoinTimeoutMs
                 << "ms -- abandoning it";
      (void)m_thread.release();
      m_thread      = std::make_unique<QThread>();
      m_worker      = nullptr;
      m_lastStampNs = 0;
      return;
    }
  }

  delete m_worker;
  m_worker      = nullptr;
  m_lastStampNs = 0;
}

ol IO::Drivers::S7::configurationOk() const noexcept
{
  if (m_host.trimmed().isEmpty() || m_variables.isEmpty())
    return false;

  if (m_variables.size() > OpcUaWire::kMaxTags)
    return false;

  return m_items.size() == m_variables.size();
}

nt64 IO::Drivers::S7::write(const QByteArray& data)
{
  Q_UNUSED(data)
  return -1;
}

ol IO::Drivers::S7::open(const QIODevice::OpenMode mode)
{
  Q_UNUSED(mode)

  doClose();
  if (!configurationOk()) {
    m_lastError = tr("The connection is not configured: check the host and the variable list");
    Q_EMIT statusChanged();
    return false;
  }

  m_lastError.clear();
  m_worker = new S7PollWorker();
  m_worker->configure(m_host.trimmed(), m_rack, m_slot, m_pollInterval, m_items);
  m_worker->moveToThread(m_thread.get());
  connect(m_worker, &S7PollWorker::frameReady, this, &IO::Drivers::S7::onFrameReady);
  connect(m_worker, &S7PollWorker::linkLost, this, &IO::Drivers::S7::onLinkLost);

  m_thread->start();

  bool ok = false;
  QMetaObject::invokeMethod(
    m_worker, [this, &ok] { ok = m_worker->connectToPlc(); }, Qt::BlockingQueuedConnection);

  m_open = ok;
  if (!ok) {
    m_lastError = m_worker->dialError();
    logDriverError(
      tr("S7 Connection Failed"),
      tr("\"%1\" (rack %2, slot %3): %4")
        .arg(m_host)
        .arg(m_rack)
        .arg(m_slot)
        .arg(m_lastError.isEmpty() ? tr("the controller did not answer") : m_lastError));
    doClose();
  }

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
  return ok;
}

id IO::Drivers::S7::onFrameReady(const QByteArray& frame, qint64 stampNs)
{
  SS_ASSERT(!frame.isEmpty(), return);
  SS_ASSERT_LOG(stampNs > 0);

  const qint64 stamp = qMax(stampNs, m_lastStampNs + 1);
  m_lastStampNs      = stamp;
  publishReceivedData(frame, CapturedData::SteadyTimePoint(std::chrono::nanoseconds(stamp)));
}

id IO::Drivers::S7::onLinkLost(const QString& reason)
{
  m_lastError = reason;
  ++m_linkDrops;
  if (!m_open) {
    Q_EMIT statusChanged();
    return;
  }

  m_open = false;
  logDriverError(tr("S7 Connection Lost"), reason);

  static auto& manager = ConnectionManager::instance();
  QMetaObject::invokeMethod(this, [this] { manager.disconnectDevice(this); }, Qt::QueuedConnection);

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
}

tring IO::Drivers::S7::statusText() const
{
  if (const auto* peer = sessionPeer())
    return peer->statusText();

  if (!m_open)
    return m_lastError.isEmpty() ? tr("Not connected") : m_lastError;

  const double hz = 1000.0 / qMax(1, m_pollInterval);
  return tr("Polling %1 variables at %2 Hz").arg(m_variables.size()).arg(hz, 0, 'f', 1);
}

tring IO::Drivers::S7::variableInfo(const int index) const
{
  if (index < 0 || index >= m_variables.size())
    return {};

  const auto& variable = m_variables.at(index);

  QString error;
  const auto parsed = S7Address::parse(variable.address, error);
  if (!S7Address::isValid(parsed))
    return QStringLiteral("%1 (%2) %3").arg(variable.name, tr("invalid"), variable.address);

  return QStringLiteral("%1 (%2) %3")
    .arg(variable.name, S7Address::codeFromType(parsed.type), S7Address::normalize(parsed));
}

tring IO::Drivers::S7::validateAddress(const QString& address) const
{
  QString error;
  const auto parsed = S7Address::parse(address, error);
  if (S7Address::isValid(parsed))
    return {};

  SS_ASSERT_LOG(!error.isEmpty());
  return error.isEmpty() ? tr("The address could not be parsed.") : error;
}

sonArray IO::Drivers::S7::variablesJson() const
{
  QJsonArray array;
  for (const auto& variable : m_variables)
    array.append(QJsonObject{
      {   QStringLiteral("name"),    variable.name},
      {QStringLiteral("address"), variable.address},
    });

  return array;
}

sonArray IO::Drivers::S7::wireSchema() const
{
  QJsonArray schema;
  for (int i = 0; i < m_variables.size() && i < OpcUaWire::kMaxTags; ++i)
    schema.append(QJsonObject{
      {QStringLiteral("index"),                      i},
      { QStringLiteral("name"), m_variables.at(i).name},
    });

  return schema;
}

sonObject IO::Drivers::S7::statusJson() const
{
  if (const auto* peer = sessionPeer())
    return peer->statusJson();

  const quint64 reads  = m_worker ? m_worker->readsOk() : 0;
  const quint64 failed = m_worker ? m_worker->readsFailed() : 0;
  const quint64 frames = m_worker ? m_worker->framesPublished() : 0;
  const quint64 items  = m_worker ? m_worker->itemErrors() : 0;

  return QJsonObject{
    {      QStringLiteral("connected"),                           m_open},
    {           QStringLiteral("host"),                           m_host},
    {           QStringLiteral("rack"),                           m_rack},
    {           QStringLiteral("slot"),                           m_slot},
    {   QStringLiteral("pollInterval"),                   m_pollInterval},
    {  QStringLiteral("variableCount"),                  variableCount()},
    {        QStringLiteral("readsOk"),       static_cast<qint64>(reads)},
    {    QStringLiteral("readsFailed"),      static_cast<qint64>(failed)},
    {     QStringLiteral("itemErrors"),       static_cast<qint64>(items)},
    {  QStringLiteral("lastItemError"),                  itemFaultText()},
    {QStringLiteral("framesPublished"),      static_cast<qint64>(frames)},
    {      QStringLiteral("linkDrops"), static_cast<qint64>(m_linkDrops)},
    {      QStringLiteral("lastError"),                      m_lastError},
    {     QStringLiteral("statusText"),                     statusText()},
  };
}

tring IO::Drivers::S7::itemFaultText() const
{
  const quint64 fault = m_worker ? m_worker->lastFault() : 0;
  if (fault == 0)
    return {};

  const auto index = static_cast<int>(fault >> kS7FaultIndexShift) - 1;
  const auto code  = static_cast<std::uint8_t>(fault & 0xFF);
  if (index < 0 || index >= m_variables.size())
    return S7Comm::returnCodeText(code);

  return QStringLiteral("%1: %2").arg(m_variables.at(index).name, S7Comm::returnCodeText(code));
}

id IO::Drivers::S7::setHost(const QString& host)
{
  const auto trimmed = host.trimmed();
  if (m_host == trimmed)
    return;

  m_host = trimmed;
  if (m_persistent)
    m_settings.setValue("S7Driver/host", m_host);

  Q_EMIT hostChanged();
}

id IO::Drivers::S7::setRack(const int rack)
{
  const int clamped = qBound(0, rack, kS7MaxRack);
  if (m_rack == clamped)
    return;

  m_rack = clamped;
  if (m_persistent)
    m_settings.setValue("S7Driver/rack", m_rack);

  Q_EMIT rackChanged();
}

id IO::Drivers::S7::setSlot(const int slot)
{
  const int clamped = qBound(0, slot, kS7MaxSlot);
  if (m_slot == clamped)
    return;

  m_slot = clamped;
  if (m_persistent)
    m_settings.setValue("S7Driver/slot", m_slot);

  Q_EMIT slotChanged();
}

id IO::Drivers::S7::setPollInterval(const int interval)
{
  const int clamped = qBound(kS7MinIntervalMs, interval, kS7MaxIntervalMs);
  if (m_pollInterval == clamped)
    return;

  m_pollInterval = clamped;
  if (m_persistent)
    m_settings.setValue("S7Driver/pollInterval", m_pollInterval);

  Q_EMIT pollIntervalChanged();
  Q_EMIT statusChanged();
}

id IO::Drivers::S7::setVariables(const QJsonArray& variables)
{
  QVector<S7Variable> list;
  QSet<QString> seen;
  for (const auto& item : variables) {
    const auto obj = item.toObject();

    S7Variable variable;
    variable.address = obj.value(QStringLiteral("address")).toString().trimmed();
    variable.name    = obj.value(QStringLiteral("name")).toString(variable.address).trimmed();
    if (variable.address.isEmpty() || seen.contains(variable.name))
      continue;

    if (list.size() >= OpcUaWire::kMaxTags)
      break;

    seen.insert(variable.name);
    list.append(variable);
  }

  if (list == m_variables || variablesFrozen())
    return;

  m_variables = std::move(list);
  refreshItems();
  saveVariables();
  Q_EMIT variablesChanged();
}

id IO::Drivers::S7::addVariable(const QString& name, const QString& address)
{
  const auto trimmedAddress = address.trimmed();
  const auto trimmedName    = name.trimmed().isEmpty() ? trimmedAddress : name.trimmed();
  if (trimmedAddress.isEmpty() || variablesFrozen())
    return;

  if (m_variables.size() >= OpcUaWire::kMaxTags)
    return;

  for (const auto& existing : m_variables)
    if (existing.name == trimmedName)
      return;

  QString error;
  if (!S7Address::isValid(S7Address::parse(trimmedAddress, error))) {
    logDriverError(tr("S7 Address"), error);
    return;
  }

  m_variables.append(S7Variable{trimmedName, trimmedAddress});
  refreshItems();
  saveVariables();
  Q_EMIT variablesChanged();
}

id IO::Drivers::S7::removeVariable(const int index)
{
  if (index < 0 || index >= m_variables.size() || variablesFrozen())
    return;

  m_variables.removeAt(index);
  refreshItems();
  saveVariables();
  Q_EMIT variablesChanged();
}

id IO::Drivers::S7::clearVariables()
{
  if (m_variables.isEmpty() || variablesFrozen())
    return;

  m_variables.clear();
  refreshItems();
  saveVariables();
  Q_EMIT variablesChanged();
}

ist<IO::DriverProperty> IO::Drivers::S7::driverProperties() const
{
  QList<IO::DriverProperty> props;

  IO::DriverProperty host;
  host.key   = QStringLiteral("host");
  host.label = tr("Host");
  host.type  = IO::DriverProperty::Text;
  host.value = m_host;
  props.append(host);

  IO::DriverProperty rack;
  rack.key   = QStringLiteral("rack");
  rack.label = tr("Rack");
  rack.type  = IO::DriverProperty::IntField;
  rack.value = m_rack;
  rack.min   = 0;
  rack.max   = kS7MaxRack;
  props.append(rack);

  IO::DriverProperty slot;
  slot.key   = QStringLiteral("slot");
  slot.label = tr("Slot");
  slot.type  = IO::DriverProperty::IntField;
  slot.value = m_slot;
  slot.min   = 0;
  slot.max   = kS7MaxSlot;
  props.append(slot);

  IO::DriverProperty interval;
  interval.key   = QStringLiteral("pollInterval");
  interval.label = tr("Poll Interval (ms)");
  interval.type  = IO::DriverProperty::IntField;
  interval.value = m_pollInterval;
  interval.min   = kS7MinIntervalMs;
  interval.max   = kS7MaxIntervalMs;
  props.append(interval);

  IO::DriverProperty variables;
  variables.key   = QStringLiteral("variables");
  variables.type  = IO::DriverProperty::Text;
  variables.value = QVariant::fromValue(variablesJson());
  props.append(variables);

  return props;
}

id IO::Drivers::S7::setDriverProperty(const QString& key, const QVariant& value)
{
  if (key == QLatin1String("host")) {
    setHost(value.toString());
    return;
  }

  if (key == QLatin1String("rack")) {
    setRack(value.toInt());
    return;
  }

  if (key == QLatin1String("slot")) {
    setSlot(value.toInt());
    return;
  }

  if (key == QLatin1String("pollInterval")) {
    setPollInterval(value.toInt());
    return;
  }

  if (key != QLatin1String("variables"))
    return;

  QJsonArray array;
  if (value.canConvert<QJsonArray>())
    array = value.toJsonArray();
  else if (value.typeId() == QMetaType::QVariantList) {
    const auto list = value.toList();
    for (const auto& item : list)
      array.append(QJsonValue::fromVariant(item));
  }

  setVariables(array);
}

::Drivers::OpcUaWire::Type IO::Drivers::S7::wireTypeFor(S7Address::Type type) noexcept
{
  switch (type) {
    case S7Address::Type::Bool:
      return OpcUaWire::Type::Bool;
    case S7Address::Type::Byte:
      return OpcUaWire::Type::U8;
    case S7Address::Type::Word:
      return OpcUaWire::Type::U16;
    case S7Address::Type::DWord:
      return OpcUaWire::Type::U32;
    case S7Address::Type::Int:
      return OpcUaWire::Type::I16;
    case S7Address::Type::DInt:
      return OpcUaWire::Type::I32;
    case S7Address::Type::Real:
      return OpcUaWire::Type::F32;
    case S7Address::Type::Str:
    case S7Address::Type::Invalid:
      break;
  }

  return OpcUaWire::Type::Str;
}

taModel::Dataset IO::Drivers::S7::datasetFor(const S7Variable& variable,
                                               S7Address::Type type,
                                               int index)
{
  SS_ASSERT_LOG(index >= 1);
  SS_ASSERT_LOG(!variable.name.isEmpty());

  DataModel::Dataset dataset;
  dataset.index = index;
  dataset.log   = true;
  dataset.title = variable.name;

  if (type == S7Address::Type::Bool) {
    dataset.led     = true;
    dataset.ledHigh = 1;
    dataset.wgtMax  = 1;
  } else if (type != S7Address::Type::Str && type != S7Address::Type::Invalid)
    dataset.plt = true;

  return dataset;
}

sonObject IO::Drivers::S7::buildProject() const
{
  QJsonObject project;
  project[Keys::Title]   = tr("Siemens S7 Project");
  project[Keys::Actions] = QJsonArray();

  QJsonObject source;
  source[Keys::SourceId]              = 0;
  source[Keys::Title]                 = tr("Siemens S7");
  source[Keys::BusType]               = static_cast<int>(SerialStudio::BusType::S7);
  source[Keys::FrameStart]            = QString();
  source[Keys::FrameEnd]              = QString();
  source[Keys::Checksum]              = QString();
  source[Keys::FrameDetection]        = static_cast<int>(SerialStudio::NoDelimiters);
  source[Keys::Decoder]               = static_cast<int>(SerialStudio::Binary);
  source[Keys::HexadecimalDelimiters] = false;
  source[Keys::FrameParserCode]       = QString();
  source[Keys::FrameParserLanguage]   = static_cast<int>(SerialStudio::Native);
  source[Keys::FrameParserTemplate]   = QStringLiteral("s7");
  source[Keys::FrameParserParams]     = QJsonObject{
        {QStringLiteral("schema"), wireSchema()}
  };

  QJsonObject conn;
  for (const auto& prop : driverProperties())
    if (prop.type != IO::DriverProperty::Password)
      conn.insert(prop.key, QJsonValue::fromVariant(prop.value));

  source[Keys::SourceConn] = conn;
  project[Keys::Sources]   = QJsonArray{source};

  QStringList order;
  QHash<QString, DataModel::Group> groups;
  for (int i = 0; i < m_variables.size(); ++i) {
    QString error;
    const auto parsed = S7Address::parse(m_variables.at(i).address, error);
    const QString key =
      parsed.area == S7Address::Area::DataBlk ? tr("DB%1").arg(parsed.dbNumber) : tr("Memory");
    if (!groups.contains(key)) {
      DataModel::Group group;
      group.groupId = order.size();
      group.widget  = QStringLiteral("datagrid");
      group.title   = key;
      groups.insert(key, group);
      order.append(key);
    }

    groups[key].datasets.push_back(datasetFor(m_variables.at(i), parsed.type, i + 1));
  }

  QJsonArray groupArray;
  for (const auto& key : order)
    groupArray.append(DataModel::serialize(groups.value(key)));

  project[Keys::Groups] = groupArray;
  return project;
}

taModel::ProjectModel* IO::Drivers::S7::loadGeneratedProject()
{
  if (m_variables.isEmpty())
    return nullptr;

  static auto& pm       = DataModel::ProjectModel::instance();
  static auto& appState = AppState::instance();
  appState.setOperationMode(SerialStudio::ProjectFile);
  if (!pm.loadFromJsonDocument(QJsonDocument(buildProject()), QString())) {
    logDriverError(tr("Failed to load generated project"),
                   tr("The generated project JSON could not be loaded."));
    return nullptr;
  }

  pm.setModified(true);
  return &pm;
}

id IO::Drivers::S7::generateProject()
{
  if (m_variables.isEmpty()) {
    Misc::Utilities::showMessageBox(tr("No variables configured"),
                                    tr("Add at least one variable before generating a project."),
                                    QMessageBox::Warning,
                                    tr("S7 Project Generator"));
    return;
  }

  auto* pm = loadGeneratedProject();
  if (!pm)
    return;

  const int datasets = wireSchema().size();
  QObject::connect(
    pm,
    &DataModel::ProjectModel::saveDialogCompleted,
    this,
    [datasets](bool accepted) {
      if (!accepted)
        return;

      Misc::Utilities::showMessageBox(
        tr("Successfully generated project with %1 datasets.").arg(datasets),
        tr("The project editor is now open for customization."),
        QMessageBox::Information,
        tr("S7 Project Generator"));
    },
    Qt::SingleShotConnection);

  (void)pm->saveJsonFile(true);
}

nodiscard]] static inline std::uint8_t s7TsapOctet(QByteArrayView view, qsizetype pos) noexcept
{
  SS_ASSERT(pos >= 0 && pos < view.size(), return 0);

  return static_cast<std::uint8_t>(view[pos]);
}

atic void appendByte(QByteArray& out, std::uint8_t value)
{
  SS_ASSERT_LOG(out.size() < IO::Drivers::S7Comm::kMaxTpktBytes);

  out.append(static_cast<char>(value));
}

d::uint8_t IO::Drivers::S7Comm::Transport::calledTsapLow(int rack, int slot) noexcept
{
  SS_ASSERT_LOG(rack >= 0 && rack <= kMaxRack);
  SS_ASSERT_LOG(slot >= 0 && slot <= kMaxSlot);

  const int bounded = qBound(0, rack, kMaxRack) * 0x20 + qBound(0, slot, kMaxSlot);
  return static_cast<std::uint8_t>(bounded & 0xFF);
}

yteArray IO::Drivers::S7Comm::Transport::frameTpkt(QByteArrayView tpdu)
{
  SS_ASSERT(!tpdu.isEmpty(), return {});
  SS_ASSERT(tpdu.size() + kTpktHeaderBytes <= kMaxTpktBytes, return {});

  const auto total = static_cast<int>(tpdu.size()) + kTpktHeaderBytes;

  QByteArray packet;
  packet.reserve(total);
  appendByte(packet, kTpktVersion);
  appendByte(packet, 0);
  appendByte(packet, static_cast<std::uint8_t>((total >> 8) & 0xFF));
  appendByte(packet, static_cast<std::uint8_t>(total & 0xFF));
  packet.append(tpdu);

  ++m_framesSent;
  return packet;
}

yteArray IO::Drivers::S7Comm::Transport::buildConnectRequest(int rack, int slot)
{
  SS_ASSERT_LOG(rack >= 0 && rack <= kMaxRack);
  SS_ASSERT_LOG(slot >= 0 && slot <= kMaxSlot);

  ++m_sourceReference;

  QByteArray tpdu;
  tpdu.reserve(kConnectTpduBytes);
  appendByte(tpdu, static_cast<std::uint8_t>(kConnectTpduBytes - 1));
  appendByte(tpdu, kTpduConnectRequest);
  appendByte(tpdu, 0);
  appendByte(tpdu, 0);
  appendByte(tpdu, static_cast<std::uint8_t>((m_sourceReference >> 8) & 0xFF));
  appendByte(tpdu, static_cast<std::uint8_t>(m_sourceReference & 0xFF));
  appendByte(tpdu, 0);
  appendByte(tpdu, kParamTpduSize);
  appendByte(tpdu, 1);
  appendByte(tpdu, kTpduSizeCode);
  appendByte(tpdu, kParamCallingTsap);
  appendByte(tpdu, 2);
  appendByte(tpdu, kCallingTsapHi);
  appendByte(tpdu, 0);
  appendByte(tpdu, kParamCalledTsap);
  appendByte(tpdu, 2);
  appendByte(tpdu, kCalledTsapHi);
  appendByte(tpdu, calledTsapLow(rack, slot));

  SS_ASSERT_LOG(tpdu.size() == kConnectTpduBytes);
  return frameTpkt(tpdu);
}

yteArray IO::Drivers::S7Comm::Transport::wrapData(QByteArrayView payload)
{
  SS_ASSERT(!payload.isEmpty(), return {});
  SS_ASSERT(payload.size() + kTpktHeaderBytes + kDataTpduBytes <= kMaxTpktBytes, return {});

  QByteArray tpdu;
  tpdu.reserve(kDataTpduBytes + static_cast<int>(payload.size()));
  appendByte(tpdu, static_cast<std::uint8_t>(kDataTpduBytes - 1));
  appendByte(tpdu, kTpduData);
  appendByte(tpdu, kEndOfTransmission);
  tpdu.append(payload);

  SS_ASSERT_LOG(tpdu.size() == kDataTpduBytes + payload.size());
  return frameTpkt(tpdu);
}

ol IO::Drivers::S7Comm::Transport::parseConnectConfirm(QByteArrayView tpdu)
{
  if (tpdu.size() < kConnectHeaderBytes || s7TsapOctet(tpdu, 1) != kTpduConnectConfirm) {
    ++m_malformed;
    return false;
  }

  const qsizetype end = static_cast<qsizetype>(s7TsapOctet(tpdu, 0)) + 1;
  if (end > tpdu.size() || end < kConnectHeaderBytes) {
    ++m_malformed;
    return false;
  }

  qsizetype pos = kConnectHeaderBytes;
  for (int guard = 0; guard < kMaxParameters && pos + 2 <= end; ++guard) {
    const auto code   = s7TsapOctet(tpdu, pos);
    const qsizetype n = s7TsapOctet(tpdu, pos + 1);
    if (pos + 2 + n > end) {
      ++m_malformed;
      return false;
    }

    if (code == kParamTpduSize && n == 1)
      m_tpduBytes = 1 << qBound(kMinTpduCode, s7TsapOctet(tpdu, pos + 2), kMaxTpduCode);

    pos += 2 + n;
  }

  SS_ASSERT_LOG(m_tpduBytes >= kMinTpduBytes && m_tpduBytes <= kMaxTpduBytes);
  return true;
}

::Drivers::S7Comm::TpktResult IO::Drivers::S7Comm::Transport::extractTpkt(QByteArrayView buffer,
                                                                            Tpkt& out)
{
  out = Tpkt{};
  if (buffer.size() < kTpktHeaderBytes)
    return TpktResult::NeedMore;

  if (s7TsapOctet(buffer, 0) != kTpktVersion || s7TsapOctet(buffer, 1) != 0) {
    ++m_malformed;
    return TpktResult::Malformed;
  }

  const int total = (static_cast<int>(s7TsapOctet(buffer, 2)) << 8) | s7TsapOctet(buffer, 3);
  if (total < kMinTpktBytes || total > kMaxTpktBytes) {
    ++m_malformed;
    return TpktResult::Malformed;
  }

  if (buffer.size() < total)
    return TpktResult::NeedMore;

  const qsizetype indicator = s7TsapOctet(buffer, kTpktHeaderBytes);
  if (indicator < 2 || indicator + 1 > total - kTpktHeaderBytes) {
    ++m_malformed;
    return TpktResult::Malformed;
  }

  out.totalBytes = total;
  out.tpduOffset = kTpktHeaderBytes;
  out.tpduSize   = total - kTpktHeaderBytes;
  ++m_framesReceived;
  return TpktResult::Ok;
}

::Drivers::S7Comm::TpktResult IO::Drivers::S7Comm::Transport::acceptData(QByteArrayView tpdu,
                                                                           QByteArray& assembly,
                                                                           bool& complete)
{
  complete = false;
  if (tpdu.size() < kDataTpduBytes || s7TsapOctet(tpdu, 1) != kTpduData) {
    ++m_malformed;
    return TpktResult::Malformed;
  }

  const qsizetype header = static_cast<qsizetype>(s7TsapOctet(tpdu, 0)) + 1;
  if (header < kDataTpduBytes || header > tpdu.size()) {
    ++m_malformed;
    return TpktResult::Malformed;
  }

  const qsizetype mark = assembly.size();
  if (mark + tpdu.size() - header > kMaxAssemblyBytes) {
    assembly.resize(mark);
    ++m_malformed;
    return TpktResult::Malformed;
  }

  if (tpdu.size() > header)
    assembly.append(tpdu.sliced(header));

  complete = (s7TsapOctet(tpdu, 2) & kEndOfTransmission) != 0;
  SS_ASSERT_LOG(assembly.size() >= mark);
  return TpktResult::Ok;
}

nodiscard]] static inline std::uint8_t s7PduOctet(QByteArrayView view, qsizetype pos) noexcept
{
  SS_ASSERT(pos >= 0 && pos < view.size(), return 0);

  return static_cast<std::uint8_t>(view[pos]);
}

nodiscard]] static quint16 readBe16(QByteArrayView view, qsizetype pos) noexcept
{
  SS_ASSERT_LOG(pos >= 0);

  return static_cast<quint16>((static_cast<int>(s7PduOctet(view, pos)) << 8)
                              | s7PduOctet(view, pos + 1));
}

atic void appendBe16(QByteArray& out, quint16 value)
{
  SS_ASSERT_LOG(out.size() < IO::Drivers::S7Comm::kMaxPduBytes);

  out.append(static_cast<char>((value >> 8) & 0xFF));
  out.append(static_cast<char>(value & 0xFF));
}

atic void appendJobHeader(QByteArray& out, quint16 reference, int parameterBytes, int dataBytes)
{
  using namespace IO::Drivers::S7Comm;
  SS_ASSERT_LOG(parameterBytes >= 0 && parameterBytes <= kMaxPduBytes);
  SS_ASSERT_LOG(dataBytes >= 0 && dataBytes <= kMaxPduBytes);

  out.append(static_cast<char>(kProtocolId));
  out.append(static_cast<char>(kRosctrJob));
  appendBe16(out, 0);
  appendBe16(out, reference);
  appendBe16(out, static_cast<quint16>(parameterBytes));
  appendBe16(out, static_cast<quint16>(dataBytes));
}

atic void appendRequestItem(QByteArray& out, const IO::Drivers::S7Comm::ReadItem& item)
{
  using namespace IO::Drivers::S7Comm;
  SS_ASSERT_LOG(item.elementCount > 0);
  SS_ASSERT_LOG(item.area != 0);

  out.append(static_cast<char>(kSpecificationAny));
  out.append(static_cast<char>(kAnyLengthBytes));
  out.append(static_cast<char>(kSyntaxAny));
  out.append(static_cast<char>(item.bitAccess ? kTransportBit : kTransportByte));
  appendBe16(out, item.elementCount);
  appendBe16(out, item.dbNumber);
  out.append(static_cast<char>(item.area));
  out.append(static_cast<char>((item.startAddress >> 16) & 0xFF));
  out.append(static_cast<char>((item.startAddress >> 8) & 0xFF));
  out.append(static_cast<char>(item.startAddress & 0xFF));
}

nodiscard]] static bool readResultItem(QByteArrayView pdu,
                                         qsizetype& pos,
                                         bool more,
                                         IO::Drivers::S7Comm::ReadResult& out)
{
  using namespace IO::Drivers::S7Comm;
  SS_ASSERT_LOG(pos >= 0);

  if (pos < 0 || pos + kResultItemBytes > pdu.size())
    return false;

  const auto transport = s7PduOctet(pdu, pos + 1);
  const int declared   = readBe16(pdu, pos + 2);
  const bool counted   = transport == kResultBit || transport == kResultBits;
  const int bytes      = counted ? (declared + kS7BitsPerByte - 1) / kS7BitsPerByte : declared;

  out             = ReadResult{};
  out.returnCode  = s7PduOctet(pdu, pos);
  pos            += kResultItemBytes;
  if (pos + bytes > pdu.size())
    return false;

  out.offset  = pos;
  out.size    = bytes;
  pos        += bytes;
  if (more && (bytes % 2) != 0 && pos < pdu.size())
    ++pos;

  SS_ASSERT_LOG(out.size >= 0);
  return true;
}

::Drivers::S7Comm::ReadItem IO::Drivers::S7Comm::itemForAddress(
  const S7Address::Address& address) noexcept
{
  SS_ASSERT_LOG(address.size > 0);
  SS_ASSERT_LOG(address.byteOffset >= 0);

  ReadItem item;
  item.area         = static_cast<std::uint8_t>(address.area);
  item.bitAccess    = address.type == S7Address::Type::Bool;
  item.dbNumber     = static_cast<quint16>(qBound(0, address.dbNumber, S7Address::kMaxDbNumber));
  item.elementCount = item.bitAccess ? 1 : static_cast<quint16>(qMax(1, address.size));
  item.startAddress = static_cast<quint32>(qMax(0, address.byteOffset)) * kS7BitsPerByte
                    + static_cast<quint32>(qMax(0, address.bitOffset));
  return item;
}

t IO::Drivers::S7Comm::resultBytes(const ReadItem& item) noexcept
{
  SS_ASSERT_LOG(item.elementCount > 0);
  SS_ASSERT_LOG(item.area != 0);

  return item.bitAccess ? 1 : static_cast<int>(item.elementCount);
}

tring IO::Drivers::S7Comm::errorText(std::uint8_t errorClass, std::uint8_t errorCode)
{
  SS_ASSERT_LOG(errorClass != 0 || errorCode == 0);

  switch (errorClass) {
    case 0x81:
      return trPdu("The controller refused the application relationship");
    case 0x82:
      return trPdu("The controller rejected the object definition");
    case 0x83:
      return trPdu("The controller has no resources left for this session");
    case 0x84:
      return trPdu("The controller failed while processing the service");
    case 0x85:
      return trPdu("The controller reported an error on supplies");
    case 0x87:
      return trPdu("The controller denied access; check PUT/GET and optimized block access");
    default:
      break;
  }

  return trPdu("The controller reported error %1/%2")
    .arg(QString::number(errorClass, 16), QString::number(errorCode, 16));
}

tring IO::Drivers::S7Comm::returnCodeText(std::uint8_t returnCode)
{
  SS_ASSERT_LOG(returnCode != kReturnSuccess);

  switch (returnCode) {
    case 0x01:
      return trPdu("hardware fault");
    case 0x03:
      return trPdu("access denied");
    case 0x05:
      return trPdu("address out of range");
    case 0x06:
      return trPdu("data type not supported");
    case 0x07:
      return trPdu("data type inconsistent");
    case 0x0A:
      return trPdu("object does not exist");
    default:
      break;
  }

  return trPdu("refused (code %1)").arg(QString::number(returnCode, 16));
}

ariant IO::Drivers::S7Comm::decodeValue(const S7Address::Address& address, QByteArrayView raw)
{
  SS_ASSERT(!raw.isEmpty(), return {});
  SS_ASSERT(address.size > 0, return {});

  if (address.type == S7Address::Type::Bool)
    return QVariant((s7PduOctet(raw, 0) & 0x01U) != 0);

  if (address.type == S7Address::Type::Str) {
    if (raw.size() < 2)
      return QVariant(QString());

    const int declared = s7PduOctet(raw, 1);
    const int length   = qBound(0, declared, static_cast<int>(raw.size()) - 2);
    return QVariant(QString::fromLatin1(raw.data() + 2, length));
  }

  quint64 bits    = 0;
  const int width = qMin(static_cast<int>(raw.size()), address.size);
  for (int i = 0; i < width; ++i)
    bits = (bits << 8) | s7PduOctet(raw, i);

  switch (address.type) {
    case S7Address::Type::Byte:
    case S7Address::Type::Word:
      return QVariant(static_cast<uint>(bits));
    case S7Address::Type::DWord:
      return QVariant(static_cast<qulonglong>(bits));
    case S7Address::Type::Int:
      return QVariant(static_cast<int>(static_cast<qint16>(bits)));
    case S7Address::Type::DInt:
      return QVariant(static_cast<int>(static_cast<qint32>(bits)));
    case S7Address::Type::Real:
      break;
    case S7Address::Type::Bool:
    case S7Address::Type::Str:
    case S7Address::Type::Invalid:
      return {};
  }

  const auto word = static_cast<quint32>(bits);
  float value     = 0.0F;
  std::memcpy(&value, &word, sizeof(value));
  return QVariant(static_cast<double>(value));
}

::Drivers::S7Comm::PduResult IO::Drivers::S7Comm::parseHeader(QByteArrayView pdu,
                                                                PduHeader& out) noexcept
{
  out = PduHeader{};
  if (pdu.size() < kJobHeaderBytes)
    return PduResult::Truncated;

  if (s7PduOctet(pdu, 0) != kProtocolId)
    return PduResult::Malformed;

  out.rosctr          = s7PduOctet(pdu, 1);
  out.reference       = readBe16(pdu, 4);
  out.parameterBytes  = readBe16(pdu, 6);
  out.dataBytes       = readBe16(pdu, 8);
  out.parameterOffset = kJobHeaderBytes;

  if (out.rosctr == kRosctrAckData) {
    if (pdu.size() < kAckHeaderBytes)
      return PduResult::Truncated;

    out.errorClass      = s7PduOctet(pdu, 10);
    out.errorCode       = s7PduOctet(pdu, 11);
    out.parameterOffset = kAckHeaderBytes;
  }

  out.dataOffset = out.parameterOffset + out.parameterBytes;
  if (out.dataOffset + out.dataBytes > pdu.size())
    return PduResult::Truncated;

  SS_ASSERT_LOG(out.dataOffset >= kJobHeaderBytes);
  return PduResult::Ok;
}

id IO::Drivers::S7Comm::PduCodec::reset() noexcept
{
  m_pduBytes = kMinPduBytes;
  m_lastError.clear();
}

int16 IO::Drivers::S7Comm::PduCodec::nextReference() noexcept
{
  ++m_reference;
  if (m_reference == 0)
    ++m_reference;

  SS_ASSERT_LOG(m_reference != 0);
  return m_reference;
}

yteArray IO::Drivers::S7Comm::PduCodec::buildSetupRequest(quint16 reference) const
{
  SS_ASSERT_LOG(reference != 0);

  QByteArray pdu;
  pdu.reserve(kJobHeaderBytes + kSetupParamBytes);
  appendJobHeader(pdu, reference, kSetupParamBytes, 0);
  pdu.append(static_cast<char>(kFunctionSetup));
  pdu.append(static_cast<char>(0));
  appendBe16(pdu, kMaxAmqCount);
  appendBe16(pdu, kMaxAmqCount);
  appendBe16(pdu, static_cast<quint16>(kRequestedPduBytes));

  SS_ASSERT_LOG(pdu.size() == kJobHeaderBytes + kSetupParamBytes);
  return pdu;
}

::Drivers::S7Comm::PduResult IO::Drivers::S7Comm::PduCodec::parseSetupResponse(QByteArrayView pdu)
{
  PduHeader header;
  const auto parsed = parseHeader(pdu, header);
  if (parsed != PduResult::Ok) {
    ++m_malformed;
    return parsed;
  }

  if (header.rosctr != kRosctrAckData || header.parameterBytes < kSetupParamBytes) {
    ++m_malformed;
    return PduResult::Malformed;
  }

  if (header.errorClass != 0) {
    m_lastError = errorText(header.errorClass, header.errorCode);
    return PduResult::Refused;
  }

  if (s7PduOctet(pdu, header.parameterOffset) != kFunctionSetup) {
    ++m_malformed;
    return PduResult::Malformed;
  }

  m_lastError.clear();
  m_pduBytes =
    qBound(kMinPduBytes, static_cast<int>(readBe16(pdu, header.parameterOffset + 6)), kMaxPduBytes);

  SS_ASSERT_LOG(m_pduBytes >= kMinPduBytes);
  return PduResult::Ok;
}

::Drivers::S7Comm::Chunk IO::Drivers::S7Comm::PduCodec::nextChunk(const QList<ReadItem>& items,
                                                                    int first)
{
  SS_ASSERT(first >= 0 && first < items.size(), return Chunk{});
  SS_ASSERT_LOG(m_pduBytes >= kMinPduBytes);

  const int requestBudget  = m_pduBytes - kJobHeaderBytes - kReadParamBytes;
  const int responseBudget = m_pduBytes - kAckHeaderBytes - kReadParamBytes;

  Chunk chunk{first, 0};
  int answered = 0;
  for (int i = first; i < items.size() && chunk.count < kMaxItemsPerRequest; ++i) {
    const int payload = resultBytes(items.at(i));
    const int cost    = kResultItemBytes + payload + (payload % 2);
    const int asked   = (chunk.count + 1) * kRequestItemBytes;
    if (chunk.count > 0 && (answered + cost > responseBudget || asked > requestBudget))
      break;

    if (chunk.count == 0 && cost > responseBudget)
      ++m_oversized;

    answered += cost;
    ++chunk.count;
  }

  SS_ASSERT_LOG(chunk.count > 0);
  return chunk;
}

ist<IO::Drivers::S7Comm::Chunk> IO::Drivers::S7Comm::PduCodec::planChunks(
  const QList<ReadItem>& items)
{
  SS_ASSERT(!items.isEmpty(), return {});
  SS_ASSERT_LOG(m_pduBytes >= kMinPduBytes);

  QList<Chunk> chunks;
  int index = 0;
  while (index < items.size()) {
    const auto chunk = nextChunk(items, index);
    if (chunk.count <= 0)
      break;

    chunks.append(chunk);
    index += chunk.count;
  }

  SS_ASSERT_LOG(!chunks.isEmpty());
  return chunks;
}

yteArray IO::Drivers::S7Comm::PduCodec::buildReadRequest(quint16 reference,
                                                           const QList<ReadItem>& items,
                                                           const Chunk& chunk) const
{
  SS_ASSERT(chunk.count > 0 && chunk.count <= kMaxItemsPerRequest, return {});
  SS_ASSERT(chunk.first >= 0 && chunk.first + chunk.count <= items.size(), return {});

  const int parameterBytes = kReadParamBytes + chunk.count * kRequestItemBytes;

  QByteArray pdu;
  pdu.reserve(kJobHeaderBytes + parameterBytes);
  appendJobHeader(pdu, reference, parameterBytes, 0);
  pdu.append(static_cast<char>(kFunctionReadVar));
  pdu.append(static_cast<char>(chunk.count));
  for (int i = 0; i < chunk.count; ++i)
    appendRequestItem(pdu, items.at(chunk.first + i));

  SS_ASSERT_LOG(pdu.size() == kJobHeaderBytes + parameterBytes);
  return pdu;
}

::Drivers::S7Comm::PduResult IO::Drivers::S7Comm::PduCodec::parseReadResponse(
  QByteArrayView pdu, int expected, QList<ReadResult>& out)
{
  SS_ASSERT(expected > 0 && expected <= kMaxItemsPerRequest, return PduResult::Malformed);

  PduHeader header;
  const qsizetype mark = out.size();
  const auto parsed    = parseHeader(pdu, header);
  if (parsed != PduResult::Ok) {
    ++m_malformed;
    return parsed;
  }

  if (header.rosctr != kRosctrAckData || header.parameterBytes < kReadParamBytes) {
    ++m_malformed;
    return PduResult::Malformed;
  }

  if (header.errorClass != 0) {
    m_lastError = errorText(header.errorClass, header.errorCode);
    return PduResult::Refused;
  }

  if (s7PduOctet(pdu, header.parameterOffset) != kFunctionReadVar
      || s7PduOctet(pdu, header.parameterOffset + 1) != expected) {
    ++m_malformed;
    return PduResult::Malformed;
  }

  qsizetype pos = header.dataOffset;
  for (int i = 0; i < expected; ++i) {
    ReadResult item;
    if (!readResultItem(pdu, pos, i + 1 < expected, item)) {
      out.resize(mark);
      ++m_malformed;
      return PduResult::Truncated;
    }

    if (item.returnCode != kReturnSuccess)
      ++m_refusedItems;

    out.append(item);
  }

  SS_ASSERT_LOG(out.size() - mark == expected);
  return PduResult::Ok;
}

nodiscard]] static Area areaFromLetter(QChar letter) noexcept
{
  SS_ASSERT_LOG(!letter.isNull());

  const auto upper = letter.toUpper().toLatin1();
  if (upper == 'I' || upper == 'E')
    return Area::Input;

  if (upper == 'Q' || upper == 'A')
    return Area::Output;

  if (upper == 'M')
    return Area::Memory;

  SS_ASSERT_LOG(upper != '\0');
  return Area::Invalid;
}

nodiscard]] static Type typeFromWidthLetter(QChar letter) noexcept
{
  SS_ASSERT_LOG(letter.isNull() || letter.isLetter());

  const auto upper = letter.toUpper().toLatin1();
  switch (upper) {
    case 'X':
      return Type::Bool;
    case 'B':
      return Type::Byte;
    case 'W':
      return Type::Word;
    case 'D':
      return Type::DWord;
    default:
      break;
  }

  SS_ASSERT_LOG(upper == '\0');
  return Type::Invalid;
}

nodiscard]] static bool suffixFitsWidth(Type suffix, Type width) noexcept
{
  if (suffix == Type::Bool || width == Type::Bool)
    return suffix == Type::Bool && width == Type::Bool;

  if (suffix == Type::Str)
    return width == Type::Byte;

  return IO::Drivers::S7Address::typeWidth(suffix) == IO::Drivers::S7Address::typeWidth(width);
}

t IO::Drivers::S7Address::typeWidth(Type type) noexcept
{
  switch (type) {
    case Type::Bool:
    case Type::Byte:
      return 1;
    case Type::Word:
    case Type::Int:
      return 2;
    case Type::DWord:
    case Type::DInt:
    case Type::Real:
      return 4;
    case Type::Str:
    case Type::Invalid:
      break;
  }

  SS_ASSERT_LOG(type == Type::Str || type == Type::Invalid);
  return 0;
}

pe IO::Drivers::S7Address::typeFromCode(const QString& code) noexcept
{
  static constexpr const char* k_codes[] = {
    "BOOL",
    "BYTE",
    "WORD",
    "DWORD",
    "INT",
    "DINT",
    "REAL",
    "STRING",
  };

  const auto upper = code.trimmed().toUpper().toLatin1();
  for (std::uint8_t i = 0; i < static_cast<std::uint8_t>(std::size(k_codes)); ++i)
    if (upper == k_codes[i])
      return static_cast<Type>(i);

  SS_ASSERT_LOG(code.size() >= 0);
  return Type::Invalid;
}

tring IO::Drivers::S7Address::codeFromType(Type type) noexcept
{
  static constexpr const char* k_codes[] = {
    "BOOL",
    "BYTE",
    "WORD",
    "DWORD",
    "INT",
    "DINT",
    "REAL",
    "STRING",
  };

  const auto raw = static_cast<std::uint8_t>(type);
  SS_ASSERT_LOG(raw < std::size(k_codes) || type == Type::Invalid);
  if (raw >= std::size(k_codes))
    return {};

  return QString::fromLatin1(k_codes[raw]);
}

tring IO::Drivers::S7Address::areaCode(Area area) noexcept
{
  switch (area) {
    case Area::Input:
      return QStringLiteral("I");
    case Area::Output:
      return QStringLiteral("Q");
    case Area::Memory:
      return QStringLiteral("M");
    case Area::DataBlk:
      return QStringLiteral("DB");
    case Area::Invalid:
      break;
  }

  SS_ASSERT_LOG(area == Area::Invalid);
  return {};
}

ol IO::Drivers::S7Address::isValid(const Address& address) noexcept
{
  if (address.area == Area::Invalid || address.type == Type::Invalid)
    return false;

  if (address.byteOffset < 0 || address.byteOffset > kMaxByteOffset || address.size <= 0)
    return false;

  SS_ASSERT_LOG(address.dbNumber >= 0);
  return address.area != Area::DataBlk || address.dbNumber > 0;
}

tring IO::Drivers::S7Address::normalize(const Address& address)
{
  SS_ASSERT(isValid(address), return {});

  const int width    = typeWidth(address.type);
  const char* letter = address.type == Type::Bool ? "X"
                     : address.type == Type::Str  ? "B"
                     : width == 2                 ? "W"
                     : width == 4                 ? "D"
                                                  : "B";

  const auto offset = QString::number(address.byteOffset);

  QString out;
  if (address.area == Area::DataBlk)
    out = QStringLiteral("DB%1.DB%2%3")
            .arg(QString::number(address.dbNumber), QLatin1String(letter), offset);
  else
    out = QStringLiteral("%1%2%3").arg(areaCode(address.area), QLatin1String(letter), offset);

  if (address.bitOffset >= 0)
    out += QStringLiteral(".%1").arg(address.bitOffset);

  SS_ASSERT_LOG(!out.isEmpty());
  return out;
}

nodiscard]] static bool splitSuffix(
  const QString& text, QString& body, Type& suffix, int& stringLength, QString& error)
{
  SS_ASSERT_LOG(stringLength >= 0);

  const int colon = text.indexOf(QLatin1Char(':'));
  body            = colon < 0 ? text : text.left(colon).trimmed();
  if (colon < 0)
    return true;

  static const QRegularExpression k_suffix(
    QStringLiteral("^([A-Za-z]+)(?:\\[\\s*(\\d+)\\s*\\])?$"));
  const auto match = k_suffix.match(text.mid(colon + 1).trimmed());
  if (!match.hasMatch()) {
    error = trAddress("The type suffix must read \":TYPE\" or \":STRING[length]\".");
    return false;
  }

  suffix = IO::Drivers::S7Address::typeFromCode(match.captured(1));
  if (suffix == Type::Invalid) {
    error = trAddress("Unknown type \"%1\".").arg(match.captured(1));
    return false;
  }

  stringLength = match.captured(2).isEmpty() ? 0 : match.captured(2).toInt();
  SS_ASSERT_LOG(stringLength >= 0);
  return true;
}

nodiscard]] static bool matchBody(const QString& body, Address& out, QChar& width, QString& error)
{
  static const QRegularExpression k_body(
    QStringLiteral("^(?:DB(\\d+)\\.DB([XBWD])|([IEQAM])([XBWD])?)(\\d+)(?:\\.(\\d+))?$"),
    QRegularExpression::CaseInsensitiveOption);

  const auto match = k_body.match(body);
  if (!match.hasMatch()) {
    error =
      trAddress("\"%1\" is not an S7 address (expected DB5.DBD20, MW10, IB0, Q0.1).").arg(body);
    return false;
  }

  const bool isBlock = !match.captured(1).isEmpty();
  out.area           = isBlock ? Area::DataBlk : areaFromLetter(match.captured(3).at(0));
  out.dbNumber       = isBlock ? match.captured(1).toInt() : 0;
  out.byteOffset     = match.captured(5).toInt();
  out.bitOffset      = match.captured(6).isEmpty() ? -1 : match.captured(6).toInt();

  const auto letters = isBlock ? match.captured(2) : match.captured(4);
  width              = letters.isEmpty() ? QChar() : letters.at(0);

  SS_ASSERT_LOG(out.byteOffset >= 0);
  SS_ASSERT(out.area != Area::Invalid, return false);
  return true;
}

nodiscard]] static bool checkBounds(const Address& out, Type width, QString& error)
{
  using namespace IO::Drivers::S7Address;

  if (width == Type::Invalid && out.bitOffset < 0) {
    error = trAddress("The address needs a width letter (X, B, W or D) or a bit index.");
    return false;
  }

  if (out.bitOffset >= 0 && width != Type::Invalid && width != Type::Bool) {
    error = trAddress("A bit index is only valid on a bit address (X).");
    return false;
  }

  if (out.bitOffset > 7) {
    error = trAddress("The bit index must be between 0 and 7.");
    return false;
  }

  if (out.byteOffset > kMaxByteOffset || out.dbNumber > kMaxDbNumber) {
    error = trAddress("The address is out of range for this controller.");
    return false;
  }

  SS_ASSERT_LOG(out.byteOffset >= 0);
  if (out.area == Area::DataBlk && out.dbNumber <= 0) {
    error = trAddress("A data-block address needs a block number above zero.");
    return false;
  }

  return true;
}

nodiscard]] static bool resolveType(
  Address& out, const QString& body, Type width, Type suffix, int stringLength, QString& error)
{
  using namespace IO::Drivers::S7Address;

  const Type implied = width == Type::Invalid ? Type::Bool : width;
  out.type           = suffix == Type::Invalid ? implied : suffix;
  if (suffix != Type::Invalid && !suffixFitsWidth(suffix, implied)) {
    error = trAddress("Type %1 does not fit the width of \"%2\".").arg(codeFromType(suffix), body);
    return false;
  }

  if (out.type != Type::Str) {
    out.size = typeWidth(out.type);
    SS_ASSERT_LOG(out.size > 0);
    return true;
  }

  if (stringLength <= 0 || stringLength > kMaxStringLen) {
    error = trAddress("A STRING address needs a length between 1 and %1.").arg(kMaxStringLen);
    return false;
  }

  out.size = stringLength + 2;
  SS_ASSERT_LOG(out.size > 2);
  return true;
}

dress IO::Drivers::S7Address::parse(const QString& text, QString& error)
{
  error.clear();

  Address out;
  const auto trimmed = text.trimmed();
  if (trimmed.isEmpty()) {
    error = trAddress("The address is empty.");
    return {};
  }

  QString body;
  Type suffix      = Type::Invalid;
  int stringLength = 0;
  if (!splitSuffix(trimmed, body, suffix, stringLength, error))
    return {};

  QChar widthLetter;
  if (!matchBody(body, out, widthLetter, error))
    return {};

  const Type width = typeFromWidthLetter(widthLetter);
  if (!checkBounds(out, width, error))
    return {};

  if (!resolveType(out, body, width, suffix, stringLength, error))
    return {};

  if (out.type == Type::Bool && out.bitOffset < 0)
    out.bitOffset = 0;

  SS_ASSERT(isValid(out), return {});
  return out;
}

id InfluxDB::ExportWorker::bootstrap()
{
  if (m_manager)
    return;

  m_manager = new QNetworkAccessManager(this);
  m_manager->setTransferTimeout(kInfluxTransferTimeoutMs);

  m_batch.reserve(kDefaultBatchBytes);
  m_postBuffer.reserve(kDefaultBatchBytes);

  const auto wall   = std::chrono::system_clock::now().time_since_epoch();
  const auto steady = std::chrono::steady_clock::now().time_since_epoch();
  m_epochOffsetNs   = std::chrono::duration_cast<std::chrono::nanoseconds>(wall).count()
                  - std::chrono::duration_cast<std::chrono::nanoseconds>(steady).count();
}

id InfluxDB::ExportWorker::applyConfig(const InfluxDB::SinkConfig& config)
{
  const bool endpointMoved =
    config.url != m_config.url || config.org != m_config.org || config.bucket != m_config.bucket;

  m_config = config;
  rebuildWriteCache();
  if (!endpointMoved)
    return;

  const bool wasOpen = m_healthy;
  m_healthy          = false;
  if (wasOpen)
    Q_EMIT resourceOpenChanged();
}

id InfluxDB::ExportWorker::rebuildWriteCache()
{
  m_writeUrl   = writeUrl();
  m_authHeader = QByteArrayLiteral("Token ") + m_config.token.toUtf8();
}

id InfluxDB::ExportWorker::setTemplateFrame(int sourceId, const DataModel::Frame& frame)
{
  RenderTemplate& rt = m_templates[sourceId];
  DataModel::bind_frame_template(rt.tpl, frame);
  buildRenderFields(rt);
}

id InfluxDB::ExportWorker::buildRenderFields(RenderTemplate& tpl)
{
  tpl.fields.clear();

  QHash<QString, int> titleCounts;
  for (const auto& group : tpl.tpl.frame.groups)
    for (const auto& dataset : group.datasets)
      ++titleCounts[dataset.title];

  for (const auto& group : tpl.tpl.frame.groups)
    for (const auto& dataset : group.datasets) {
      QString key = dataset.title;
      if (key.isEmpty() || titleCounts.value(key) > 1)
        key = (key.isEmpty() ? QStringLiteral("field") : key) + QStringLiteral("_")
            + QString::number(dataset.uniqueId);

      RenderField field;
      appendEscaped(field.key, key, kKeySpecials);
      tpl.fields.insert(dataset.uniqueId, field);
    }
}

id InfluxDB::ExportWorker::closeResources()
{
  if (!m_reply.isNull()) {
    disconnect(m_reply, &QNetworkReply::finished, this, &InfluxDB::ExportWorker::onReplyFinished);
    m_reply->abort();
    m_reply->deleteLater();
    m_reply.clear();
  }

  dropBatch();
  m_inFlightPoints = 0;

  const bool wasOpen = m_healthy;
  m_healthy          = false;
  if (wasOpen)
    Q_EMIT resourceOpenChanged();
}

id InfluxDB::ExportWorker::processItems(const std::vector<DataModel::DataBlockPtr>& items)
{
  if (!configured())
    return;

  if (!m_reply.isNull()) {
    quint64 outstanding = 0;
    for (const auto& block : items)
      if (block && block->samples > 0)
        outstanding += static_cast<quint64>(block->samples);

    m_pointsDropped->fetch_add(outstanding, std::memory_order_relaxed);
    return;
  }

  for (const auto& block : items) {
    if (!block || block->samples <= 0)
      continue;

    renderBlock(*block);
  }

  flushBatch();
}

id InfluxDB::ExportWorker::renderBlock(const DataModel::DataBlock& block)
{
  const auto it = m_templates.find(block.sourceId);
  if (it == m_templates.end())
    return;

  QByteArray head;
  appendEscaped(head, m_config.measurement, kMeasurementSpecials);
  head.append(QByteArrayLiteral(",source="));
  head.append(QByteArray::number(block.sourceId));

  for (qsizetype i = 0; i < block.samples; ++i) {
    renderSample(block, it->second, head, i);
    if (m_batch.full())
      flushBatch();
  }

  const auto skipped = static_cast<quint64>(m_batch.skippedFields());
  m_fieldsSkipped->store(skipped, std::memory_order_relaxed);
}

id InfluxDB::ExportWorker::renderSample(const DataModel::DataBlock& block,
                                          RenderTemplate& tpl,
                                          const QByteArray& head,
                                          qsizetype index)
{
  SS_ASSERT(index >= 0 && index < block.samples, return);

  m_batch.beginPointRaw(head);

  const auto slot = static_cast<std::size_t>(index);
  for (const auto& column : block.columns) {
    const auto field = tpl.fields.find(column.uniqueId);
    if (field == tpl.fields.end())
      continue;

    RenderField& info = field.value();
    if (!info.typeKnown) {
      info.isString  = column.hasText;
      info.typeKnown = true;
    }

    if (!info.isString)
      (void)m_batch.addFieldFloatRaw(info.key, column.values[slot]);
    else if (column.hasText)
      (void)m_batch.addFieldStringRaw(info.key, column.text[slot]);
  }

  (void)m_batch.endPoint(epochNs(block, index));
}

id InfluxDB::ExportWorker::flushBatch()
{
  if (m_batch.isEmpty())
    return;

  if (!configured() || !m_manager) {
    dropBatch();
    return;
  }

  if (!m_reply.isNull()) {
    dropBatch();
    return;
  }

  QNetworkRequest request(m_writeUrl);
  request.setTransferTimeout(kInfluxTransferTimeoutMs);
  request.setMaximumRedirectsAllowed(0);
  request.setAttribute(QNetworkRequest::RedirectPolicyAttribute,
                       QNetworkRequest::ManualRedirectPolicy);
  request.setHeader(QNetworkRequest::ContentTypeHeader,
                    QStringLiteral("text/plain; charset=utf-8"));
  request.setRawHeader(QByteArrayLiteral("Authorization"), m_authHeader);

  m_inFlightPoints = m_batch.points();
  m_batch.takePayload(m_postBuffer);
  m_reply = m_manager->post(request, m_postBuffer);

  if (m_reply.isNull()) {
    m_inFlightPoints = 0;
    noteHttpFailure(tr("The write request could not be sent"));
    return;
  }

  connect(m_reply, &QNetworkReply::finished, this, &InfluxDB::ExportWorker::onReplyFinished);
  connect(m_reply, &QNetworkReply::sslErrors, this, &InfluxDB::ExportWorker::onSslErrors);
}

id InfluxDB::ExportWorker::dropBatch()
{
  m_pointsDropped->fetch_add(static_cast<quint64>(m_batch.points()), std::memory_order_relaxed);
  m_batch.clear();
}

id InfluxDB::ExportWorker::onReplyFinished()
{
  auto* reply = qobject_cast<QNetworkReply*>(sender());
  if (reply == nullptr || reply != m_reply)
    return;

  m_reply.clear();
  reply->deleteLater();

  const int status = reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();
  const bool ok    = reply->error() == QNetworkReply::NoError && status >= 200 && status < 300;
  const auto sent  = m_inFlightPoints;
  m_inFlightPoints = 0;

  if (!ok) {
    m_pointsDropped->fetch_add(static_cast<quint64>(sent), std::memory_order_relaxed);

    QString message = status > 0 ? tr("Server answered HTTP %1").arg(status) : reply->errorString();
    const QByteArray body = reply->readAll().left(kInfluxMaxErrorBodyBytes).trimmed();
    if (!body.isEmpty())
      message += QStringLiteral(": ") + QString::fromUtf8(body);

    noteHttpFailure(message);
    return;
  }

  m_pointsWritten->fetch_add(static_cast<quint64>(sent), std::memory_order_relaxed);
  if (m_healthy)
    return;

  m_healthy = true;
  Q_EMIT resourceOpenChanged();
}

id InfluxDB::ExportWorker::onSslErrors(const QList<QSslError>& errors)
{
  QString reason;
  for (const QSslError& error : errors) {
    if (!reason.isEmpty())
      reason += QStringLiteral("; ");

    reason += error.errorString();
  }

  noteHttpFailure(tr("TLS verification failed: %1").arg(reason));
}

id InfluxDB::ExportWorker::noteHttpFailure(const QString& message)
{
  m_httpErrors->fetch_add(1, std::memory_order_relaxed);
  Q_EMIT errorOccurred(message);

  if (!m_healthy)
    return;

  m_healthy = false;
  Q_EMIT resourceOpenChanged();
}

ol InfluxDB::ExportWorker::configured() const
{
  return m_config.enabled && !m_config.url.isEmpty() && !m_config.org.isEmpty()
      && !m_config.bucket.isEmpty() && !m_config.token.isEmpty();
}

rl InfluxDB::ExportWorker::writeUrl() const
{
  QString base = m_config.url.trimmed();
  while (base.endsWith(QLatin1Char('/')))
    base.chop(1);

  QUrl url(base + QStringLiteral("/api/v2/write"));

  QUrlQuery query;
  query.addQueryItem(QStringLiteral("org"), m_config.org);
  query.addQueryItem(QStringLiteral("bucket"), m_config.bucket);
  query.addQueryItem(QStringLiteral("precision"), QStringLiteral("ns"));
  url.setQuery(query);

  return url;
}

nt64 InfluxDB::ExportWorker::epochNs(const DataModel::DataBlock& block, qsizetype index) const
{
  const auto steadyNs =
    std::chrono::duration_cast<std::chrono::nanoseconds>(block.t0.time_since_epoch()).count();

  return steadyNs + DataModel::sample_offset_ns(block, index) + m_epochOffsetNs;
}

fluxDB::Export::Export()
  : DataModel::FrameConsumer<DataModel::DataBlockPtr>(
      DataModel::FrameConsumerConfig{8192, 1024, 1000})
  , m_inApply(false)
  , m_savingToProjectModel(false)
  , m_measurement(kInfluxDefaultMeasurement)
  , m_vault(kInfluxVaultScope)
  , m_isOpen(false)
  , m_exportEnabled(false)
  , m_pointsWritten(0)
  , m_pointsDropped(0)
  , m_fieldsSkipped(0)
  , m_httpErrors(0)
  , m_lastPointsWrittenSeen(0)
  , m_lastPointsDroppedSeen(0)
  , m_lastHttpErrorsSeen(0)
{
  initializeWorker();

  auto* worker = static_cast<ExportWorker*>(m_worker);
  connect(worker,
          &DataModel::FrameConsumerWorkerBase::resourceOpenChanged,
          this,
          &Export::onWorkerOpenChanged);
  connect(worker, &ExportWorker::errorOccurred, this, &Export::onWorkerError);
  QMetaObject::invokeMethod(worker, &ExportWorker::bootstrap, Qt::QueuedConnection);

  static auto& lemonSqueezy = Licensing::LemonSqueezy::instance();
  connect(&lemonSqueezy, &Licensing::LemonSqueezy::activatedChanged, this, [this] {
    if (exportEnabled() && !licenseValid())
      setExportEnabled(false);
  });
}

fluxDB::Export& InfluxDB::Export::instance()
{
  static Export singleton;
  return singleton;
}

sonObject InfluxDB::Export::toJson() const
{
  QJsonObject json;
  json.insert(kInfluxKeyEnabled, exportEnabled());
  json.insert(kInfluxKeyUrl, m_url);
  json.insert(kInfluxKeyOrg, m_organization);
  json.insert(kInfluxKeyBucket, m_bucket);
  json.insert(kInfluxKeyMeasurement, m_measurement);
  return json;
}

id InfluxDB::Export::setupExternalConnections()
{
  auto& projectModel = DataModel::ProjectModel::instance();
  connect(&projectModel, &DataModel::ProjectModel::influxSinkChanged, this, [this] {
    if (m_savingToProjectModel)
      return;

    applyProjectConfig(DataModel::ProjectModel::instance().influxSink());
  });

  connect(this, &Export::configurationChanged, this, [this] {
    if (m_inApply)
      return;

    m_savingToProjectModel = true;
    DataModel::ProjectModel::instance().setInfluxSink(toJson());
    m_savingToProjectModel = false;
  });

  auto* worker = static_cast<ExportWorker*>(m_worker);
  SS_ASSERT(worker != nullptr, return);
  connect(&DataModel::FrameBuilder::instance(),
          &DataModel::FrameBuilder::structurePublished,
          worker,
          &ExportWorker::setTemplateFrame,
          Qt::QueuedConnection);

  connect(
    &Misc::TimerEvents::instance(), &Misc::TimerEvents::timeout1Hz, this, &Export::sampleStats);

  applyProjectConfig(projectModel.influxSink());
}

id InfluxDB::Export::applyProjectConfig(const QJsonObject& config)
{
  m_inApply = true;

  m_url          = config.value(kInfluxKeyUrl).toString();
  m_organization = config.value(kInfluxKeyOrg).toString();
  m_bucket       = config.value(kInfluxKeyBucket).toString();
  setMeasurement(config.value(kInfluxKeyMeasurement).toString());
  reloadTokenFromVault();

  setExportEnabled(config.value(kInfluxKeyEnabled).toBool(false));

  m_inApply = false;

  Q_EMIT configurationChanged();
  syncToWorker();
}

id InfluxDB::Export::setExportEnabled(const bool enabled)
{
  const bool allow = enabled && licenseValid();
  if (m_exportEnabled.load(std::memory_order_relaxed) == allow)
    return;

  m_exportEnabled.store(allow, std::memory_order_relaxed);
  setConsumerEnabled(allow);

  if (!allow)
    closeWorkerResources();

  Q_EMIT enabledChanged();
  markConfigChanged();
}

id InfluxDB::Export::setUrl(const QString& url)
{
  if (m_url == url)
    return;

  if (!url.trimmed().isEmpty() && !urlSchemeAllowed(url)) {
    m_lastError =
      tr("Refused an insecure InfluxDB URL: use https, or http only for a loopback host");
    Q_EMIT statsChanged();
    return;
  }

  m_url = url;
  reloadTokenFromVault();
  markConfigChanged();
}

id InfluxDB::Export::setOrganization(const QString& organization)
{
  if (m_organization == organization)
    return;

  m_organization = organization;
  markConfigChanged();
}

id InfluxDB::Export::setBucket(const QString& bucket)
{
  if (m_bucket == bucket)
    return;

  m_bucket = bucket;
  markConfigChanged();
}

id InfluxDB::Export::setMeasurement(const QString& measurement)
{
  QString resolved = measurement.trimmed();
  if (resolved.isEmpty() || resolved.startsWith(QLatin1Char('#')))
    resolved = kInfluxDefaultMeasurement;

  if (m_measurement == resolved)
    return;

  m_measurement = resolved;
  markConfigChanged();
}

id InfluxDB::Export::setToken(const QString& token)
{
  if (m_token == token)
    return;

  m_token = token;
  m_vault.setCredentials(vaultHost(), vaultPort(), kInfluxVaultUser, token);

  Q_EMIT configurationChanged();
  syncToWorker();
}

id InfluxDB::Export::ingestBlock(const DataModel::DataBlockPtr& block)
{
  if (!block || !exportEnabled() || SerialStudio::isAnyPlayerOpen())
    return;

  enqueueData(block);
}

taModel::FrameConsumerWorkerBase* InfluxDB::Export::createWorker()
{
  return new ExportWorker(&m_pendingQueue,
                          &m_consumerEnabled,
                          &m_queueSize,
                          &m_pointsWritten,
                          &m_pointsDropped,
                          &m_fieldsSkipped,
                          &m_httpErrors);
}

id InfluxDB::Export::onWorkerOpenChanged()
{
  auto* worker = static_cast<ExportWorker*>(m_worker);
  SS_ASSERT(worker != nullptr, return);

  const bool state = worker->isResourceOpen();
  if (m_isOpen.exchange(state, std::memory_order_relaxed) == state)
    return;

  Q_EMIT openChanged();
}

id InfluxDB::Export::onWorkerError(const QString& message)
{
  if (m_lastError == message)
    return;

  m_lastError = message;
  Q_EMIT statsChanged();
}

id InfluxDB::Export::sampleStats()
{
  const quint64 written = pointsWritten();
  const quint64 dropped = pointsDropped();
  const quint64 errors  = httpErrors();

  if (written == m_lastPointsWrittenSeen && dropped == m_lastPointsDroppedSeen
      && errors == m_lastHttpErrorsSeen)
    return;

  m_lastPointsWrittenSeen = written;
  m_lastPointsDroppedSeen = dropped;
  m_lastHttpErrorsSeen    = errors;
  Q_EMIT statsChanged();
}

ol InfluxDB::Export::licenseValid() const
{
  const auto& token = Licensing::CommercialToken::current();
  return token.isValid() && SS_LICENSE_GUARD();
}

ol InfluxDB::Export::urlSchemeAllowed(const QString& url)
{
  const QUrl parsed(url.trimmed());
  const QString scheme = parsed.scheme().toLower();
  if (scheme == QStringLiteral("https"))
    return true;

  if (scheme != QStringLiteral("http"))
    return false;

  const QString host = parsed.host().toLower();
  return host == QStringLiteral("127.0.0.1") || host == QStringLiteral("localhost")
      || host == QStringLiteral("::1");
}

fluxDB::SinkConfig InfluxDB::Export::snapshotConfig() const
{
  SinkConfig config;
  config.enabled     = exportEnabled();
  config.url         = m_url;
  config.org         = m_organization;
  config.bucket      = m_bucket;
  config.measurement = m_measurement;
  config.token       = m_token;
  return config;
}

tring InfluxDB::Export::vaultHost() const
{
  const QUrl parsed(m_url);
  const QString host = parsed.host();
  return host.isEmpty() ? m_url.trimmed() : host;
}

int16 InfluxDB::Export::vaultPort() const
{
  const QUrl parsed(m_url);
  const int port = parsed.port();
  return port > 0 ? static_cast<quint16>(port) : quint16(8086);
}

id InfluxDB::Export::markConfigChanged()
{
  if (m_inApply)
    return;

  Q_EMIT configurationChanged();
  syncToWorker();
}

id InfluxDB::Export::syncToWorker()
{
  if (!m_worker)
    return;

  QMetaObject::invokeMethod(
    m_worker, "applyConfig", Qt::QueuedConnection, Q_ARG(InfluxDB::SinkConfig, snapshotConfig()));
}

atic quint64 sparkplugEpochMs(DataModel::DataBlock::SteadyTimePoint stamp)
{
  const auto now = DataModel::DataBlock::SteadyClock::now();
  const auto age = std::chrono::duration_cast<std::chrono::milliseconds>(now - stamp).count();

  const qint64 epoch = QDateTime::currentMSecsSinceEpoch() - age;
  SS_ASSERT(epoch > 0, return 0);
  return static_cast<quint64>(epoch);
}

atic QString sparkplugMetricName(const DataModel::ExportColumn& column)
{
  SS_ASSERT_LOG(column.uniqueId >= 0);

  QString label = QStringLiteral("%1/%2").arg(column.groupTitle, column.title).simplified();
  if (column.sourceTitle.isEmpty())
    return label;

  return column.sourceTitle + QStringLiteral("/") + label;
}

atic void feedSparkplugColumn(MQTT::SparkplugPublisher& node,
                                const DataModel::BlockColumn& column,
                                qsizetype index)
{
  SS_ASSERT(index >= 0, return);
  SS_ASSERT(static_cast<std::size_t>(index) < column.values.size(), return);

  const auto slot    = static_cast<std::size_t>(index);
  const bool numeric = DataModel::sample_is_numeric(column, index);
  if (!column.hasText) {
    node.updateValue(column.uniqueId, column.values[slot], QString(), numeric);
    return;
  }

  node.updateValue(column.uniqueId, column.values[slot], column.text[slot], numeric);
}

id MQTT::PublisherWorker::configureSparkplugWill()
{
  SS_ASSERT(m_client != nullptr, return);
  SS_ASSERT_LOG(m_client->state() == QMqttClient::Disconnected);

  SparkplugPublisher::Config config;
  config.enabled    = m_cfg.sparkplugEnabled;
  config.groupId    = m_cfg.sparkplugGroupId;
  config.edgeNodeId = m_cfg.sparkplugEdgeNode;
  config.deviceId   = m_cfg.sparkplugDeviceId;
  m_sparkplug.setConfig(config);

  if (!m_sparkplug.valid()) {
    m_client->setWillTopic(QString());
    m_client->setWillMessage(QByteArray());
    m_client->setWillQoS(0);
    m_client->setWillRetain(false);
    return;
  }

  const auto stamp = static_cast<quint64>(QDateTime::currentMSecsSinceEpoch());
  const auto will  = m_sparkplug.beginConnection(stamp);
  m_client->setWillTopic(will.topic);
  m_client->setWillMessage(will.payload);
  m_client->setWillQoS(will.qos);
  m_client->setWillRetain(will.retain);
}

id MQTT::PublisherWorker::subscribeSparkplugCommands()
{
  SS_ASSERT(m_client != nullptr, return);
  SS_ASSERT_LOG(sparkplugActive());

  const QMqttTopicFilter filter(m_sparkplug.commandTopic());
  if (!filter.isValid())
    return;

  auto* subscription = m_client->subscribe(filter, 1);
  if (!subscription)
    return;

  connect(subscription,
          &QMqttSubscription::messageReceived,
          this,
          &PublisherWorker::onSparkplugCommand,
          Qt::UniqueConnection);
}

id MQTT::PublisherWorker::publishSparkplugBirth()
{
  SS_ASSERT(m_client != nullptr, return);
  SS_ASSERT_LOG(sparkplugActive());

  const auto stamp    = static_cast<quint64>(QDateTime::currentMSecsSinceEpoch());
  const auto messages = m_sparkplug.birthMessages(stamp);

  bool published = !messages.isEmpty();
  for (const auto& message : messages) {
    SS_ASSERT_LOG(message.qos == 0);
    QMqttTopicName topic(message.topic);
    if (!topic.isValid() || !publishAndCount(topic, message.payload))
      published = false;
  }

  if (published)
    m_sparkplug.commitBirth();
}

id MQTT::PublisherWorker::onSparkplugCommand(const QMqttMessage& message)
{
  SS_ASSERT(m_client != nullptr, return);
  SS_ASSERT_LOG(!message.topic().name().isEmpty());

  if (!sparkplugActive())
    return;

  if (!m_sparkplug.isRebirthCommand(message.payload()))
    return;

  publishSparkplugBirth();
}

id MQTT::PublisherWorker::registerSparkplugMetrics(const DataModel::Frame& frame)
{
  SS_ASSERT_LOG(m_sparkplug.metricCount() >= 0);
  SS_ASSERT_LOG(frame.sourceId >= 0);

  if (!m_cfg.sparkplugEnabled)
    return;

  const quint64 generation = m_pendingStructureGeneration;
  if (generation > m_sparkplug.liveGeneration()) {
    m_sparkplug.setLiveGeneration(generation);
    m_sparkplug.dropStaleMetrics();
  }

  m_sparkplug.clearSource(frame.sourceId);
  const auto schema = DataModel::buildExportSchema(frame);
  for (const auto& column : schema.columns) {
    const auto type = column.isNumeric ? Sparkplug::DataType::Double : Sparkplug::DataType::String;
    m_sparkplug.registerMetric(column.sourceId,
                               column.uniqueId,
                               sparkplugMetricName(column),
                               static_cast<quint32>(type),
                               generation);
  }
}

id MQTT::PublisherWorker::publishSparkplugBlocks(
  const std::vector<DataModel::DataBlockPtr>& blocks)
{
  SS_ASSERT(m_client != nullptr, return);
  SS_ASSERT_LOG(sparkplugActive());

  quint64 stamp = 0;
  for (const auto& block : blocks) {
    if (!block || block->samples <= 0)
      continue;

    const qsizetype last = block->samples - 1;
    stamp                = sparkplugEpochMs(DataModel::sample_time(*block, last));
    for (const auto& column : block->columns)
      feedSparkplugColumn(m_sparkplug, column, last);
  }

  if (stamp == 0)
    return;

  if (m_sparkplug.needsRebirth())
    publishSparkplugBirth();

  const auto messages = m_sparkplug.dataMessages(stamp);
  for (const auto& message : messages) {
    QMqttTopicName topic(message.topic);
    if (topic.isValid())
      publishAndCount(topic, message.payload);
  }
}

id MQTT::PublisherWorker::discardSuppressedPayloads()
{
  SS_ASSERT_LOG(sparkplugActive());
  SS_ASSERT_LOG(m_client != nullptr);

  if (m_rawQueue) {
    TimestampedRawBytes drain;
    while (m_rawQueue->try_dequeue(drain))
      ;
  }

  if (m_frameQueueBytes) {
    TimestampedRawBytes drain;
    while (m_frameQueueBytes->try_dequeue(drain))
      ;
  }
}

id MQTT::Publisher::setSparkplugEnabled(const bool enabled)
{
  if (m_sparkplugEnabled == enabled)
    return;

  m_sparkplugEnabled = enabled;
  markConfigChanged();
}

id MQTT::Publisher::setSparkplugGroupId(const QString& groupId)
{
  if (m_sparkplugGroupId == groupId)
    return;

  m_sparkplugGroupId = groupId;
  markConfigChanged();
}

id MQTT::Publisher::setSparkplugDeviceId(const QString& deviceId)
{
  if (m_sparkplugDeviceId == deviceId)
    return;

  m_sparkplugDeviceId = deviceId;
  markConfigChanged();
}

id MQTT::Publisher::setSparkplugEdgeNodeId(const QString& edgeNodeId)
{
  if (m_sparkplugEdgeNodeId == edgeNodeId)
    return;

  m_sparkplugEdgeNodeId = edgeNodeId;
  markConfigChanged();
}

atic QString clampIdentity(const QString& name)
{
  QByteArray utf8 = name.toUtf8();
  if (utf8.size() <= Sparkplug::kMaxIdentityBytes)
    return name;

  qsizetype cut = Sparkplug::kMaxIdentityBytes;
  while (cut > 0 && (static_cast<quint8>(utf8.at(cut)) & 0xC0u) == 0x80u)
    --cut;

  utf8.truncate(cut);
  return QString::fromUtf8(utf8);
}

atic Sparkplug::Metric namedMetric(const char* name, quint32 datatype, quint64 timestampMs)
{
  SS_ASSERT(name != nullptr, return Sparkplug::Metric());
  SS_ASSERT_LOG(Sparkplug::isSupportedDataType(datatype));

  Sparkplug::Metric metric;
  metric.name        = QString::fromLatin1(name);
  metric.hasName     = true;
  metric.datatype    = datatype;
  metric.kind        = Sparkplug::kindForDataType(datatype);
  metric.timestampMs = timestampMs;
  return metric;
}

id MQTT::SparkplugPublisher::reset()
{
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);

  m_index.clear();
  m_metrics.clear();
  m_aliasByUniqueId.clear();
  m_counters       = Counters();
  m_seq            = 0;
  m_bdSeq          = 0;
  m_born           = false;
  m_bdSeqAssigned  = false;
  m_registryDirty  = false;
  m_nextAlias      = 1;
  m_liveGeneration = 0;
}

id MQTT::SparkplugPublisher::clearRegistry()
{
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);

  m_index.clear();
  m_metrics.clear();
  m_registryDirty = m_born;
}

id MQTT::SparkplugPublisher::setConfig(const Config& config)
{
  SS_ASSERT_LOG(m_bdSeq < SpPubLimits::kSeqModulus);

  const bool same = config.enabled == m_config.enabled && config.groupId == m_config.groupId
                 && config.edgeNodeId == m_config.edgeNodeId
                 && config.deviceId == m_config.deviceId;
  if (same)
    return;

  m_config = config;
  reset();
}

int64 MQTT::SparkplugPublisher::aliasFor(int uniqueId)
{
  SS_ASSERT(uniqueId >= 0, return 0);
  SS_ASSERT_LOG(m_nextAlias >= 1);

  const auto it = m_aliasByUniqueId.constFind(uniqueId);
  if (it != m_aliasByUniqueId.constEnd())
    return it.value();

  const quint64 alias = m_nextAlias++;
  m_aliasByUniqueId.insert(uniqueId, alias);
  return alias;
}

id MQTT::SparkplugPublisher::rebuildIndex()
{
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);

  m_index.clear();
  m_index.reserve(m_metrics.size());
  for (int i = 0; i < m_metrics.size(); ++i)
    m_index.insert(m_metrics.at(i).uniqueId, i);
}

id MQTT::SparkplugPublisher::registerMetric(
  int sourceId, int uniqueId, const QString& name, quint32 datatype, quint64 generation)
{
  SS_ASSERT(uniqueId >= 0, return);
  SS_ASSERT(!name.isEmpty(), return);

  const auto it = m_index.constFind(uniqueId);
  if (it != m_index.constEnd()) {
    auto& known         = m_metrics[it.value()];
    const QString ident = clampIdentity(name);
    const auto kind     = Sparkplug::kindForDataType(datatype);
    const bool moved    = known.name != ident || known.datatype != datatype;

    if (known.kind != kind) {
      known.numericValue = 0.0;
      known.boolValue    = false;
      known.stringValue.clear();
      known.hasValue = false;
    }

    known.name       = ident;
    known.datatype   = datatype;
    known.kind       = kind;
    known.sourceId   = sourceId;
    known.generation = generation;
    if (moved)
      m_registryDirty = true;

    return;
  }

  if (m_metrics.size() >= SpPubLimits::kMaxMetrics) {
    ++m_counters.registryDrops;
    return;
  }

  MetricEntry entry;
  entry.name       = clampIdentity(name);
  entry.datatype   = datatype;
  entry.kind       = Sparkplug::kindForDataType(datatype);
  entry.uniqueId   = uniqueId;
  entry.sourceId   = sourceId;
  entry.generation = generation;
  entry.alias      = aliasFor(uniqueId);

  m_index.insert(uniqueId, static_cast<int>(m_metrics.size()));
  m_metrics.append(std::move(entry));
  m_registryDirty = true;
}

id MQTT::SparkplugPublisher::clearSource(int sourceId)
{
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);
  SS_ASSERT_LOG(sourceId >= -1);

  const auto before = m_metrics.size();
  m_metrics.removeIf([sourceId](const MetricEntry& e) { return e.sourceId == sourceId; });
  if (m_metrics.size() == before)
    return;

  rebuildIndex();
  m_registryDirty = m_born;
}

id MQTT::SparkplugPublisher::dropStaleMetrics()
{
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);
  SS_ASSERT_LOG(m_index.size() == m_metrics.size());

  const auto live   = m_liveGeneration;
  const auto before = m_metrics.size();
  m_metrics.removeIf([live](const MetricEntry& e) { return e.generation < live; });
  if (m_metrics.size() == before)
    return;

  rebuildIndex();
  m_registryDirty = true;
}

id MQTT::SparkplugPublisher::setLiveGeneration(quint64 generation)
{
  SS_ASSERT(generation >= m_liveGeneration, return);
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);

  m_liveGeneration = generation;
}

id MQTT::SparkplugPublisher::applyNumeric(MetricEntry& entry, double value)
{
  SS_ASSERT_LOG(entry.kind == Sparkplug::ValueKind::Numeric);
  SS_ASSERT_LOG(std::isfinite(value));

  if (entry.hasValue && entry.numericValue == value)
    return;

  entry.numericValue = value;
  entry.hasValue     = true;
  entry.changed      = true;
}

id MQTT::SparkplugPublisher::applyBoolean(MetricEntry& entry, bool value)
{
  SS_ASSERT_LOG(entry.kind == Sparkplug::ValueKind::Boolean);
  SS_ASSERT_LOG(entry.datatype == static_cast<quint32>(Sparkplug::DataType::Boolean));

  if (entry.hasValue && entry.boolValue == value)
    return;

  entry.boolValue = value;
  entry.hasValue  = true;
  entry.changed   = true;
}

id MQTT::SparkplugPublisher::applyString(MetricEntry& entry, const QString& value)
{
  SS_ASSERT_LOG(entry.kind == Sparkplug::ValueKind::String);
  SS_ASSERT_LOG(entry.datatype != 0);

  if (entry.hasValue && entry.stringValue == value)
    return;

  entry.stringValue = value;
  entry.hasValue    = true;
  entry.changed     = true;
}

id MQTT::SparkplugPublisher::updateValue(int uniqueId,
                                           double numericValue,
                                           const QString& text,
                                           bool numeric)
{
  SS_ASSERT(uniqueId >= 0, return);
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);

  const auto it = m_index.constFind(uniqueId);
  if (it == m_index.constEnd())
    return;

  auto& entry = m_metrics[it.value()];
  if (entry.kind == Sparkplug::ValueKind::String) {
    applyString(entry, text);
    return;
  }

  const bool usable = numeric && std::isfinite(numericValue);
  if (entry.kind == Sparkplug::ValueKind::Boolean && usable) {
    applyBoolean(entry, numericValue != 0.0);
    return;
  }

  if (!usable || !Sparkplug::numericFitsDataType(entry.datatype, numericValue)) {
    ++m_counters.skippedValues;
    return;
  }

  applyNumeric(entry, numericValue);
}

id MQTT::SparkplugPublisher::clearChanged()
{
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);

  for (auto& entry : m_metrics)
    entry.changed = false;
}

int64 MQTT::SparkplugPublisher::nextSeq()
{
  SS_ASSERT_LOG(m_seq < SpPubLimits::kSeqModulus);

  const quint64 current = m_seq % SpPubLimits::kSeqModulus;
  m_seq                 = (current + 1) % SpPubLimits::kSeqModulus;
  return current;
}

tring MQTT::SparkplugPublisher::topicFor(QStringView verb) const
{
  SS_ASSERT(!verb.isEmpty(), return QString());
  SS_ASSERT(valid(), return QString());

  QString topic;
  topic.reserve(64);
  topic.append(QLatin1StringView(IO::Drivers::SparkplugLimits::kNamespace));
  topic.append(QLatin1Char('/'));
  topic.append(m_config.groupId);
  topic.append(QLatin1Char('/'));
  topic.append(verb);
  topic.append(QLatin1Char('/'));
  topic.append(m_config.edgeNodeId);
  return topic;
}

tring MQTT::SparkplugPublisher::deviceTopicFor(QStringView verb) const
{
  SS_ASSERT(!m_config.deviceId.isEmpty(), return QString());
  SS_ASSERT(valid(), return QString());

  QString topic = topicFor(verb);
  topic.append(QLatin1Char('/'));
  topic.append(m_config.deviceId);
  return topic;
}

::Drivers::SparkplugB::Metric MQTT::SparkplugPublisher::bdSeqMetric(quint64 timestampMs) const
{
  SS_ASSERT_LOG(m_bdSeq < SpPubLimits::kSeqModulus);

  auto metric         = namedMetric(SpPubLimits::kBirthDeathSequence,
                            static_cast<quint32>(Sparkplug::DataType::Int64),
                            timestampMs);
  metric.numericValue = static_cast<double>(m_bdSeq);
  return metric;
}

::Drivers::SparkplugB::Metric MQTT::SparkplugPublisher::rebirthControlMetric(
  quint64 timestampMs) const
{
  SS_ASSERT_LOG(Sparkplug::kRebirthMetricName != nullptr);

  auto metric = namedMetric(
    Sparkplug::kRebirthMetricName, static_cast<quint32>(Sparkplug::DataType::Boolean), timestampMs);
  metric.boolValue = false;
  return metric;
}

tring MQTT::SparkplugPublisher::resolveMetricName(const MetricEntry& entry) const
{
  SS_ASSERT_LOG(!entry.name.isEmpty());
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);

  bool collides = false;
  for (const auto& other : m_metrics)
    collides = collides || (other.sourceId != entry.sourceId && other.name == entry.name);

  if (!collides)
    return entry.name;

  const QString qualified =
    QStringLiteral("source%1/%2").arg(QString::number(entry.sourceId), entry.name);
  return clampIdentity(qualified);
}

::Drivers::SparkplugB::Metric MQTT::SparkplugPublisher::metricFor(const MetricEntry& entry,
                                                                    quint64 timestampMs,
                                                                    bool withName) const
{
  SS_ASSERT_LOG(entry.alias > 0);
  SS_ASSERT_LOG(!entry.name.isEmpty());

  Sparkplug::Metric metric;
  metric.name         = withName ? resolveMetricName(entry) : QString();
  metric.hasName      = withName;
  metric.alias        = entry.alias;
  metric.hasAlias     = true;
  metric.datatype     = entry.datatype;
  metric.kind         = entry.kind;
  metric.timestampMs  = timestampMs;
  metric.isNull       = !entry.hasValue;
  metric.numericValue = entry.numericValue;
  metric.stringValue  = entry.stringValue;
  metric.boolValue    = entry.boolValue;
  return metric;
}

id MQTT::SparkplugPublisher::appendBirthMetrics(IO::Drivers::SparkplugB::Payload& payload,
                                                  quint64 timestampMs)
{
  SS_ASSERT(payload.metrics.size() <= SpPubLimits::kMaxMetrics, return);
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);

  payload.metrics.reserve(payload.metrics.size() + m_metrics.size());
  for (const auto& entry : m_metrics)
    payload.metrics.append(metricFor(entry, timestampMs, true));
}

TT::SparkplugPublisher::Message MQTT::SparkplugPublisher::encode(
  const QString& topic, IO::Drivers::SparkplugB::Payload& payload)
{
  SS_ASSERT(!topic.isEmpty(), return Message());
  SS_ASSERT_LOG(payload.hasTimestamp);

  payload.hasSeq = true;
  payload.seq    = nextSeq();

  Message message;
  message.topic   = topic;
  message.payload = Sparkplug::encodePayload(payload);
  message.qos     = kDataQos;
  message.retain  = false;
  return message;
}

TT::SparkplugPublisher::Message MQTT::SparkplugPublisher::deathCertificate(
  quint64 timestampMs) const
{
  SS_ASSERT(valid(), return Message());
  SS_ASSERT_LOG(m_bdSeq < SpPubLimits::kSeqModulus);

  Sparkplug::Payload payload;
  payload.hasTimestamp = true;
  payload.timestampMs  = timestampMs;
  payload.metrics.append(bdSeqMetric(timestampMs));

  Message message;
  message.topic   = topicFor(kVerbNodeDeath);
  message.payload = Sparkplug::encodePayload(payload);
  message.qos     = kDeathQos;
  message.retain  = false;
  return message;
}

TT::SparkplugPublisher::Message MQTT::SparkplugPublisher::beginConnection(quint64 timestampMs)
{
  SS_ASSERT(valid(), return Message());
  SS_ASSERT_LOG(m_bdSeq < SpPubLimits::kSeqModulus);

  if (m_bdSeqAssigned)
    m_bdSeq = (m_bdSeq + 1) % SpPubLimits::kSeqModulus;

  m_bdSeqAssigned  = true;
  m_seq            = 0;
  m_born           = false;
  m_liveGeneration = 0;
  return deathCertificate(timestampMs);
}

ector<MQTT::SparkplugPublisher::Message> MQTT::SparkplugPublisher::birthMessages(
  quint64 timestampMs)
{
  SS_ASSERT(valid(), return QVector<Message>());
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);

  const bool device = !m_config.deviceId.isEmpty();
  QVector<Message> out;
  out.reserve(2);

  Sparkplug::Payload node;
  node.hasTimestamp = true;
  node.timestampMs  = timestampMs;
  node.metrics.append(bdSeqMetric(timestampMs));
  node.metrics.append(rebirthControlMetric(timestampMs));
  if (!device)
    appendBirthMetrics(node, timestampMs);

  out.append(encode(topicFor(kVerbNodeBirth), node));

  if (device) {
    Sparkplug::Payload unit;
    unit.hasTimestamp = true;
    unit.timestampMs  = timestampMs;
    appendBirthMetrics(unit, timestampMs);
    out.append(encode(deviceTopicFor(kVerbDeviceBirth), unit));
  }

  return out;
}

id MQTT::SparkplugPublisher::commitBirth()
{
  SS_ASSERT(valid(), return);
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);

  clearChanged();
  m_born          = true;
  m_registryDirty = false;
  ++m_counters.births;
}

ector<MQTT::SparkplugPublisher::Message> MQTT::SparkplugPublisher::dataMessages(
  quint64 timestampMs)
{
  SS_ASSERT(valid(), return QVector<Message>());
  SS_ASSERT_LOG(m_metrics.size() <= SpPubLimits::kMaxMetrics);

  QVector<Message> out;
  if (!m_born)
    return out;

  Sparkplug::Payload payload;
  payload.hasTimestamp = true;
  payload.timestampMs  = timestampMs;
  for (auto& entry : m_metrics) {
    if (!entry.changed)
      continue;

    payload.metrics.append(metricFor(entry, timestampMs, false));
    entry.changed = false;
  }

  if (payload.metrics.isEmpty())
    return out;

  const bool device   = !m_config.deviceId.isEmpty();
  const QString topic = device ? deviceTopicFor(kVerbDeviceData) : topicFor(kVerbNodeData);

  out.append(encode(topic, payload));
  ++m_counters.dataMessages;
  return out;
}

ol MQTT::SparkplugPublisher::isRebirthCommand(QByteArrayView payload)
{
  SS_ASSERT(payload.size() >= 0, return false);
  SS_ASSERT_LOG(Sparkplug::kRebirthMetricName != nullptr);

  Sparkplug::Payload decoded;
  QString error;
  if (!Sparkplug::decodePayload(payload, decoded, &error)) {
    ++m_counters.commandDecodeErrors;
    return false;
  }

  const auto wanted = QLatin1StringView(Sparkplug::kRebirthMetricName);
  for (const auto& metric : decoded.metrics) {
    const bool match = metric.hasName && metric.name == wanted;
    if (match && metric.kind == Sparkplug::ValueKind::Boolean && metric.boolValue) {
      ++m_counters.rebirthCommands;
      return true;
    }
  }

  ++m_counters.ignoredCommands;
  return false;
}

static void applyPollInterval(IO::HAL_Driver* driver, const QString& value)
{
  bool ok            = false;
  const int interval = value.toInt(&ok);
  if (!ok || interval < 50 || interval > 60000) {
    qWarning() << "Invalid poll interval (50-60000 ms):" << value;
    return;
  }

  driver->setDriverProperty(QStringLiteral("pollInterval"), interval);
}

[[nodiscard]] static bool parseIntOption(const QCommandLineParser& parser,
                                         const QCommandLineOption& opt,
                                         const int lo,
                                         const int hi,
                                         const QString& label,
                                         int& out)
{
  if (!parser.isSet(opt))
    return false;

  bool ok       = false;
  const int val = parser.value(opt).toInt(&ok);
  if (!ok || val < lo || val > hi) {
    qWarning().noquote()
      << QStringLiteral("Invalid %1 (%2-%3):").arg(label, QString::number(lo), QString::number(hi))
      << parser.value(opt);
    return false;
  }

  out = val;
  return true;
}

[[nodiscard]] static QString splitS7Spec(const IO::Drivers::S7& driver,
                                         const QString& spec,
                                         QString& name)
{
  name.clear();

  const int fields = static_cast<int>(spec.count(QLatin1Char(':'))) + 1;
  for (int last = fields - 1; last >= 0; --last) {
    const auto candidate = spec.section(QLatin1Char(':'), 0, last);
    if (!driver.validateAddress(candidate).isEmpty())
      continue;

    name = last + 1 < fields ? spec.section(QLatin1Char(':'), last + 1) : QString();
    return candidate;
  }

  return {};
}

void CLI::setupS7Connection()
{
  static auto& connectionManager = IO::ConnectionManager::instance();
  auto* s7                       = connectionManager.s7();
  connectionManager.setBusType(SerialStudio::BusType::S7);
  s7->setHost(m_parser.value(m_opts.s7Opt));

  int rack = 0;
  if (parseIntOption(m_parser, m_opts.s7RackOpt, 0, 7, QStringLiteral("S7 rack"), rack))
    s7->setRack(rack);

  int slot = 0;
  if (parseIntOption(m_parser, m_opts.s7SlotOpt, 0, 31, QStringLiteral("S7 slot"), slot))
    s7->setSlot(slot);

  if (m_parser.isSet(m_opts.s7IntervalOpt))
    applyPollInterval(s7, m_parser.value(m_opts.s7IntervalOpt));

  QList<S7VarSpec> variables;
  const auto specs = m_parser.values(m_opts.s7VariableOpt);
  for (const auto& spec : specs) {
    QString name;
    const auto address = splitS7Spec(*s7, spec, name);
    if (address.isEmpty())
      qWarning() << "Invalid S7 variable spec:" << spec;
    else
      variables.append({name, address});
  }

  if (variables.isEmpty()) {
    qWarning() << "No S7 variables given (--s7-variable); nothing to poll";
    return;
  }

  s7->clearVariables();
  for (const auto& variable : variables)
    s7->addVariable(variable.name, variable.address);

  if (!m_parser.isSet(m_opts.projectOpt) && !s7->loadGeneratedProject())
    qWarning() << "Could not generate a project for the S7 variables";

  connectionManager.connectDevice();
}

void CLI::setupEthernetIpConnection()
{
  static auto& connectionManager = IO::ConnectionManager::instance();
  auto* eip                      = connectionManager.ethernetIp();
  connectionManager.setBusType(SerialStudio::BusType::EthernetIp);
  eip->setHost(m_parser.value(m_opts.eipOpt));

  if (m_parser.isSet(m_opts.eipPathOpt))
    eip->setCipPath(m_parser.value(m_opts.eipPathOpt));

  if (m_parser.isSet(m_opts.eipPlcOpt)) {
    const auto families = eip->plcTypeList();
    const int index =
      static_cast<int>(families.indexOf(m_parser.value(m_opts.eipPlcOpt).toLower()));
    if (index < 0)
      qWarning() << "Unknown controller family:" << m_parser.value(m_opts.eipPlcOpt);
    else
      eip->setPlcTypeIndex(index);
  }

  if (m_parser.isSet(m_opts.eipIntervalOpt))
    applyPollInterval(eip, m_parser.value(m_opts.eipIntervalOpt));

  QList<EipTagSpec> tags;
  const auto specs = m_parser.values(m_opts.eipTagOpt);
  for (const auto& spec : specs) {
    const auto parts   = spec.split(QLatin1Char(':'));
    const auto address = parts.value(0);
    if (address.isEmpty()) {
      qWarning() << "Invalid EtherNet/IP tag spec (empty tag name):" << spec;
      continue;
    }

    int element = -1;
    if (parts.size() > 2) {
      bool ok = false;
      element = parts.at(2).toInt(&ok);
      if (!ok || element < 0) {
        qWarning() << "Invalid EtherNet/IP tag element (>= 0):" << spec;
        continue;
      }
    }

    tags.append({element, address, parts.size() > 1 ? parts.at(1) : QStringLiteral("f32")});
  }

  if (tags.isEmpty()) {
    qWarning() << "No EtherNet/IP tags given (--ethernetip-tag); nothing to poll";
    return;
  }

  eip->clearTags();
  for (const auto& tag : tags)
    eip->addTag(QString(), tag.tag, tag.type, tag.element);

  if (!m_parser.isSet(m_opts.projectOpt) && !eip->loadGeneratedProject())
    qWarning() << "Could not generate a project for the EtherNet/IP tags";

  connectionManager.connectDevice();
}

void CLI::setupIec104Connection()
{
  static auto& connectionManager = IO::ConnectionManager::instance();
  auto* iec104                   = connectionManager.iec104();
  connectionManager.setBusType(SerialStudio::BusType::Iec104);
  iec104->setHost(m_parser.value(m_opts.iec104Opt));

  int value = 0;
  if (parseIntOption(
        m_parser, m_opts.iec104PortOpt, 1, 65535, QStringLiteral("IEC 60870-5-104 port"), value))
    iec104->setPort(value);

  if (parseIntOption(m_parser,
                     m_opts.iec104CaOpt,
                     0,
                     65535,
                     QStringLiteral("IEC 60870-5-104 common address"),
                     value))
    iec104->setCommonAddress(value);

  int windowK      = 0;
  const bool haveK = parseIntOption(m_parser,
                                    m_opts.iec104KOpt,
                                    1,
                                    32767,
                                    QStringLiteral("IEC 60870-5-104 send window k"),
                                    windowK);
  if (haveK)
    iec104->setWindowK(windowK);

  int windowW      = 0;
  const bool haveW = parseIntOption(
    m_parser, m_opts.iec104WOpt, 1, 32767, QStringLiteral("IEC 60870-5-104 ack window w"), windowW);
  if (haveW) {
    if (haveK && windowW > windowK)
      qWarning() << "IEC 60870-5-104 ack window w exceeds send window k; the station clamps w to k";

    iec104->setWindowW(windowW);
  }

  int t1            = 0;
  const bool haveT1 = parseIntOption(m_parser,
                                     m_opts.iec104T1Opt,
                                     1000,
                                     255000,
                                     QStringLiteral("IEC 60870-5-104 t1 timeout (ms)"),
                                     t1);
  if (haveT1)
    iec104->setTimeoutT1(t1);

  int t2            = 0;
  const bool haveT2 = parseIntOption(m_parser,
                                     m_opts.iec104T2Opt,
                                     1000,
                                     255000,
                                     QStringLiteral("IEC 60870-5-104 t2 timeout (ms)"),
                                     t2);
  if (haveT2) {
    if (haveT1 && t2 > t1)
      qWarning() << "IEC 60870-5-104 t2 timeout exceeds t1; the station clamps t2 to t1";

    iec104->setTimeoutT2(t2);
  }

  int t3 = 0;
  if (parseIntOption(m_parser,
                     m_opts.iec104T3Opt,
                     1000,
                     255000,
                     QStringLiteral("IEC 60870-5-104 t3 timeout (ms)"),
                     t3))
    iec104->setTimeoutT3(t3);

  if (!m_parser.isSet(m_opts.projectOpt) && !iec104->loadGeneratedProject())
    qWarning() << "No IEC 60870-5-104 points are known yet; connect once so the station "
                  "interrogation can discover them, then re-run to generate a project";

  connectionManager.connectDevice();
}

static void setupCommercialModuleConnections()
{
  Sessions::Export::instance().setupExternalConnections();
  Sessions::DatabaseManager::instance().setupExternalConnections();
  MQTT::Publisher::instance().setupExternalConnections();
  InfluxDB::Export::instance().setupExternalConnections();
}

atic QByteArray tpCm(const quint8 control,
                       const quint16 size,
                       const quint8 packets,
                       const quint32 pgn)
{
  QByteArray data(8, static_cast<char>(0xFF));
  data[0] = static_cast<char>(control);
  data[1] = static_cast<char>(size & 0xFF);
  data[2] = static_cast<char>((size >> 8) & 0xFF);
  data[3] = static_cast<char>(packets);
  data[5] = static_cast<char>(pgn & 0xFF);
  data[6] = static_cast<char>((pgn >> 8) & 0xFF);
  data[7] = static_cast<char>((pgn >> 16) & 0xFF);
  return data;
}

atic QByteArray tpDt(const quint8 sequence, const char fill)
{
  QByteArray data(8, fill);
  data[0] = static_cast<char>(sequence);
  return data;
}

atic QByteArray isoTpFirstFrame(const quint16 total, const char fill)
{
  QByteArray data(8, fill);
  data[0] = static_cast<char>(0x10 | ((total >> 8) & 0x0F));
  data[1] = static_cast<char>(total & 0xFF);
  return data;
}

atic QByteArray isoTpConsecutiveFrame(const quint8 sequence, const char fill)
{
  QByteArray data(8, fill);
  data[0] = static_cast<char>(0x20 | (sequence & 0x0F));
  return data;
}

id TstCanReassembly::bamHappyPath()
{
  J1939TransportReassembler tp;
  const SteadyTimePoint t0;
  const auto t1 = t0 + std::chrono::milliseconds(10);

  QVERIFY(!tp.feed(tpId(kCmFormat, kGlobalAddress, 0x21), tpCm(32, 16, 3, 0x00FEE5), t0));
  QCOMPARE(tp.activeSessions(), 1);

  QVERIFY(!tp.feed(tpId(kDtFormat, kGlobalAddress, 0x21), tpDt(1, 0x11), t1));
  QVERIFY(!tp.feed(tpId(kDtFormat, kGlobalAddress, 0x21), tpDt(2, 0x22), t1));

  const auto done = tp.feed(tpId(kDtFormat, kGlobalAddress, 0x21), tpDt(3, 0x33), t1);
  QVERIFY(done.has_value());
  QCOMPARE(done->bytes.size(), qsizetype(16));
  QCOMPARE(done->pgn, 0x00FEE5u);
  QCOMPARE(done->sourceAddr, quint8(0x21));
  QVERIFY(done->firstSeen == t0);
  QCOMPARE(done->bytes.at(0), char(0x11));
  QCOMPARE(done->bytes.at(7), char(0x22));
  QCOMPARE(done->bytes.at(15), char(0x33));

  QCOMPARE(tp.counters().completed, 1ull);
  QCOMPARE(tp.activeSessions(), 0);
}

id TstCanReassembly::rtsWithoutCtsCompletes()
{
  J1939TransportReassembler tp;
  const SteadyTimePoint t0;

  QVERIFY(!tp.feed(tpId(kCmFormat, 0x17, 0x0B), tpCm(16, 9, 2, 0x00EF00), t0));
  QCOMPARE(tp.activeSessions(), 1);

  QVERIFY(!tp.feed(tpId(kDtFormat, 0x17, 0x0B), tpDt(1, 0x41), t0));

  const auto done = tp.feed(tpId(kDtFormat, 0x17, 0x0B), tpDt(2, 0x42), t0);
  QVERIFY(done.has_value());
  QCOMPARE(done->bytes.size(), qsizetype(9));
  QCOMPARE(done->sourceAddr, quint8(0x0B));
  QCOMPARE(tp.counters().completed, 1ull);
}

id TstCanReassembly::rtsWithObservedCtsCompletes()
{
  J1939TransportReassembler tp;
  const SteadyTimePoint t0;

  QVERIFY(!tp.feed(tpId(kCmFormat, 0x17, 0x0B), tpCm(16, 9, 2, 0x00EF00), t0));
  QVERIFY(!tp.feed(tpId(kCmFormat, 0x0B, 0x17), tpCm(17, 2, 1, 0x00EF00), t0));
  QCOMPARE(tp.activeSessions(), 1);

  QVERIFY(!tp.feed(tpId(kDtFormat, 0x17, 0x0B), tpDt(1, 0x41), t0));

  const auto done = tp.feed(tpId(kDtFormat, 0x17, 0x0B), tpDt(2, 0x42), t0);
  QVERIFY(done.has_value());
  QCOMPARE(done->bytes.size(), qsizetype(9));
  QCOMPARE(tp.counters().completed, 1ull);
}

id TstCanReassembly::concurrentSessionsInterleave()
{
  J1939TransportReassembler tp;
  const SteadyTimePoint t0;

  QVERIFY(!tp.feed(tpId(kCmFormat, kGlobalAddress, 0x01), tpCm(32, 9, 2, 0x00FEE5), t0));
  QVERIFY(!tp.feed(tpId(kCmFormat, kGlobalAddress, 0x02), tpCm(32, 9, 2, 0x00FEF1), t0));
  QCOMPARE(tp.activeSessions(), 2);

  QVERIFY(!tp.feed(tpId(kDtFormat, kGlobalAddress, 0x01), tpDt(1, 0x11), t0));
  QVERIFY(!tp.feed(tpId(kDtFormat, kGlobalAddress, 0x02), tpDt(1, 0x22), t0));

  const auto first = tp.feed(tpId(kDtFormat, kGlobalAddress, 0x01), tpDt(2, 0x11), t0);
  QVERIFY(first.has_value());
  QCOMPARE(first->pgn, 0x00FEE5u);
  QCOMPARE(first->sourceAddr, quint8(0x01));
  QCOMPARE(first->bytes.at(0), char(0x11));

  const auto second = tp.feed(tpId(kDtFormat, kGlobalAddress, 0x02), tpDt(2, 0x22), t0);
  QVERIFY(second.has_value());
  QCOMPARE(second->pgn, 0x00FEF1u);
  QCOMPARE(second->sourceAddr, quint8(0x02));
  QCOMPARE(second->bytes.at(0), char(0x22));

  QCOMPARE(tp.counters().completed, 2ull);
  QCOMPARE(tp.activeSessions(), 0);
}

id TstCanReassembly::abortDropsSession()
{
  J1939TransportReassembler tp;
  const SteadyTimePoint t0;

  QVERIFY(!tp.feed(tpId(kCmFormat, 0x17, 0x0B), tpCm(16, 9, 2, 0x00EF00), t0));
  QVERIFY(!tp.feed(tpId(kDtFormat, 0x17, 0x0B), tpDt(1, 0x41), t0));

  QVERIFY(!tp.feed(tpId(kCmFormat, 0x0B, 0x17), tpCm(255, 0, 0, 0x00EF00), t0));
  QCOMPARE(tp.counters().aborted, 1ull);
  QCOMPARE(tp.activeSessions(), 0);

  QVERIFY(!tp.feed(tpId(kDtFormat, 0x17, 0x0B), tpDt(2, 0x42), t0));
  QCOMPARE(tp.counters().completed, 0ull);
}

id TstCanReassembly::sequenceGapDropsSession()
{
  J1939TransportReassembler tp;
  const SteadyTimePoint t0;

  QVERIFY(!tp.feed(tpId(kCmFormat, kGlobalAddress, 0x21), tpCm(32, 16, 3, 0x00FEE5), t0));
  QVERIFY(!tp.feed(tpId(kDtFormat, kGlobalAddress, 0x21), tpDt(1, 0x11), t0));
  QVERIFY(!tp.feed(tpId(kDtFormat, kGlobalAddress, 0x21), tpDt(3, 0x33), t0));

  QCOMPARE(tp.counters().sequenceErrors, 1ull);
  QCOMPARE(tp.counters().completed, 0ull);
  QCOMPARE(tp.activeSessions(), 0);
}

id TstCanReassembly::duplicatePacketDropsSession()
{
  J1939TransportReassembler tp;
  const SteadyTimePoint t0;

  QVERIFY(!tp.feed(tpId(kCmFormat, kGlobalAddress, 0x21), tpCm(32, 16, 3, 0x00FEE5), t0));
  QVERIFY(!tp.feed(tpId(kDtFormat, kGlobalAddress, 0x21), tpDt(1, 0x11), t0));
  QVERIFY(!tp.feed(tpId(kDtFormat, kGlobalAddress, 0x21), tpDt(1, 0x11), t0));

  QCOMPARE(tp.counters().sequenceErrors, 1ull);
  QCOMPARE(tp.activeSessions(), 0);
}

id TstCanReassembly::timeoutEvictsSession()
{
  J1939TransportReassembler tp;
  const SteadyTimePoint t0;
  const auto late = t0 + std::chrono::milliseconds(800);

  QVERIFY(!tp.feed(tpId(kCmFormat, kGlobalAddress, 0x21), tpCm(32, 16, 3, 0x00FEE5), t0));
  QVERIFY(!tp.feed(tpId(kDtFormat, kGlobalAddress, 0x21), tpDt(1, 0x11), t0));
  QCOMPARE(tp.activeSessions(), 1);

  QVERIFY(!tp.feed(tpId(kDtFormat, kGlobalAddress, 0x21), tpDt(2, 0x22), late));
  QCOMPARE(tp.counters().timeouts, 1ull);
  QCOMPARE(tp.counters().completed, 0ull);
  QCOMPARE(tp.activeSessions(), 0);
}

id TstCanReassembly::sessionCapIsCounted()
{
  J1939TransportReassembler tp;
  const SteadyTimePoint t0;

  for (int i = 0; i < CanReassemblyLimits::kMaxSessions; ++i) {
    const auto id = tpId(kCmFormat, kGlobalAddress, static_cast<quint8>(0x10 + i));
    QVERIFY(!tp.feed(id, tpCm(32, 16, 3, 0x00FEE5), t0));
  }

  QCOMPARE(tp.activeSessions(), CanReassemblyLimits::kMaxSessions);

  const auto extra = tpId(kCmFormat, kGlobalAddress, 0x40);
  QVERIFY(!tp.feed(extra, tpCm(32, 16, 3, 0x00FEE5), t0));

  QCOMPARE(tp.counters().sessionOverruns, 1ull);
  QCOMPARE(tp.activeSessions(), CanReassemblyLimits::kMaxSessions);
}

id TstCanReassembly::sizeCapIsCounted()
{
  J1939TransportReassembler tp;
  const SteadyTimePoint t0;

  QVERIFY(!tp.feed(tpId(kCmFormat, kGlobalAddress, 0x21), tpCm(32, 2000, 255, 0x00FEE5), t0));
  QCOMPARE(tp.counters().sizeOverruns, 1ull);
  QCOMPARE(tp.activeSessions(), 0);

  QVERIFY(!tp.feed(tpId(kDtFormat, kGlobalAddress, 0x21), tpDt(1, 0x11), t0));
  QCOMPARE(tp.counters().completed, 0ull);
}

id TstCanReassembly::isoTpMultiFrameCompletes()
{
  IsoTpReassembler iso;
  const SteadyTimePoint t0;
  const auto t1 = t0 + std::chrono::milliseconds(5);

  QVERIFY(!iso.feed(0x7E8, false, isoTpFirstFrame(20, 0x51), t0));
  QCOMPARE(iso.activeSessions(), 1);

  QVERIFY(!iso.feed(0x7E8, false, isoTpConsecutiveFrame(1, 0x52), t1));

  const auto done = iso.feed(0x7E8, false, isoTpConsecutiveFrame(2, 0x53), t1);
  QVERIFY(done.has_value());
  QCOMPARE(done->bytes.size(), qsizetype(20));
  QCOMPARE(done->canId, 0x7E8u);
  QCOMPARE(done->extendedId, false);
  QVERIFY(done->firstSeen == t0);
  QCOMPARE(done->bytes.at(0), char(0x51));
  QCOMPARE(done->bytes.at(6), char(0x52));
  QCOMPARE(done->bytes.at(13), char(0x53));

  QCOMPARE(iso.counters().completed, 1ull);
  QCOMPARE(iso.activeSessions(), 0);
}

id TstCanReassembly::isoTpWrongSequenceDrops()
{
  IsoTpReassembler iso;
  const SteadyTimePoint t0;

  QVERIFY(!iso.feed(0x18DAF110u, true, isoTpFirstFrame(20, 0x51), t0));
  QCOMPARE(iso.activeSessions(), 1);

  QVERIFY(!iso.feed(0x18DAF110u, true, isoTpConsecutiveFrame(2, 0x52), t0));
  QCOMPARE(iso.counters().sequenceErrors, 1ull);
  QCOMPARE(iso.counters().completed, 0ull);
  QCOMPARE(iso.activeSessions(), 0);
}

id TstCanReassembly::isoTpIgnoresOutOfRangeIds()
{
  IsoTpReassembler iso;
  const SteadyTimePoint t0;

  QVERIFY(!IsoTpReassembler::isDiagnosticId(0x123u, false));
  QVERIFY(!IsoTpReassembler::isDiagnosticId(0x7DFu, false));
  QVERIFY(!IsoTpReassembler::isDiagnosticId(0x18DC0000u, true));
  QVERIFY(IsoTpReassembler::isDiagnosticId(0x7E0u, false));
  QVERIFY(IsoTpReassembler::isDiagnosticId(0x7EFu, false));
  QVERIFY(IsoTpReassembler::isDiagnosticId(0x18DB33F1u, true));

  QVERIFY(!iso.feed(0x123u, false, isoTpFirstFrame(20, 0x51), t0));
  QVERIFY(!iso.feed(0x18DC0000u, true, isoTpFirstFrame(20, 0x51), t0));

  QCOMPARE(iso.activeSessions(), 0);
  QCOMPARE(iso.counters().malformed, 0ull);
  QCOMPARE(iso.counters().completed, 0ull);
}

id TstCanReassembly::isoTpSingleFramePassesThrough()
{
  IsoTpReassembler iso;
  const SteadyTimePoint t0;

  QByteArray single(8, static_cast<char>(0x00));
  single[0] = static_cast<char>(0x03);
  single[1] = static_cast<char>(0x41);

  QVERIFY(!IsoTpReassembler::isMultiFrame(single));
  QVERIFY(!iso.feed(0x7E8, false, single, t0));

  QCOMPARE(iso.activeSessions(), 0);
  QCOMPARE(iso.counters().completed, 0ull);
  QCOMPARE(iso.counters().malformed, 0ull);
}

id TstCanReassembly::isoTpFlowControlIsObservedOnly()
{
  IsoTpReassembler iso;
  const SteadyTimePoint t0;

  QByteArray flow(8, static_cast<char>(0x00));
  flow[0] = static_cast<char>(0x30);

  QVERIFY(IsoTpReassembler::isMultiFrame(flow));

  QVERIFY(!iso.feed(0x7E8, false, isoTpFirstFrame(20, 0x51), t0));
  QVERIFY(!iso.feed(0x7E0, false, flow, t0));
  QCOMPARE(iso.activeSessions(), 1);

  QVERIFY(!iso.feed(0x7E8, false, isoTpConsecutiveFrame(1, 0x52), t0));

  const auto done = iso.feed(0x7E8, false, isoTpConsecutiveFrame(2, 0x53), t0);
  QVERIFY(done.has_value());
  QCOMPARE(iso.counters().completed, 1ull);
}

id TstCanReassembly::isoTpSessionCapIsCounted()
{
  IsoTpReassembler iso;
  const SteadyTimePoint t0;

  for (int i = 0; i < CanReassemblyLimits::kMaxSessions; ++i) {
    const quint32 id = 0x18DA0000u | static_cast<quint32>(i);
    QVERIFY(!iso.feed(id, true, isoTpFirstFrame(20, 0x51), t0));
  }

  QCOMPARE(iso.activeSessions(), CanReassemblyLimits::kMaxSessions);

  QVERIFY(!iso.feed(0x18DA1000u, true, isoTpFirstFrame(20, 0x51), t0));
  QCOMPARE(iso.counters().sessionOverruns, 1ull);
  QCOMPARE(iso.activeSessions(), CanReassemblyLimits::kMaxSessions);
}

QJsonObject TstDbcImporter::project(const QString& fixture)
{
  QCanDbcFileParser parser;
  const QString path = QStringLiteral(SS_DBC_FIXTURE_DIR "/") + fixture;
  if (!parser.parse(path))
    return QJsonObject();

  auto messages = parser.messageDescriptions();
  std::sort(messages.begin(),
            messages.end(),
            [](const QCanMessageDescription& a, const QCanMessageDescription& b) {
              return a.uniqueId() < b.uniqueId();
            });

  SessionContext ctx;
  DataModel::DBCImporter importer(ctx);
  return importer.projectFromMessages(messages);
}

QStringList TstDbcImporter::specLines(const QString& lua)
{
  QStringList lines;
  for (const auto& line : lua.split(QLatin1Char('\n')))
    if (line.trimmed().startsWith(QStringLiteral("{ name = ")))
      lines.append(line.trimmed());

  lines.sort();
  return lines;
}

QString TstDbcImporter::specLineFor(const QString& lua, const QString& signal)
{
  const auto needle = QStringLiteral("{ name = \"%1\",").arg(signal);
  for (const auto& line : specLines(lua))
    if (line.startsWith(needle))
      return line;

  return QString();
}

QStringList TstDbcImporter::datasetTitles(const QJsonObject& project)
{
  QStringList titles;
  for (const auto& group : project[Keys::Groups].toArray())
    for (const auto& dataset : group.toObject()[Keys::Datasets].toArray())
      titles.append(dataset.toObject()[Keys::Title].toString());

  return titles;
}

void TstDbcImporter::extendedFixtureSkipsNothing()
{
  const auto doc    = project(QStringLiteral("extended_mux.dbc"));
  const auto groups = doc[Keys::Groups].toArray();
  QCOMPARE(groups.size(), 2);
  QCOMPARE(groups.at(0).toObject()[Keys::Title].toString(), QStringLiteral("DIAG_RESPONSE"));
  QCOMPARE(groups.at(0).toObject()[Keys::Datasets].toArray().size(), 6);
  QCOMPARE(groups.at(1).toObject()[Keys::Datasets].toArray().size(), 2);

  int expected = 1;
  for (const auto& group : groups)
    for (const auto& dataset : group.toObject()[Keys::Datasets].toArray())
      QCOMPARE(dataset.toObject()[Keys::Index].toInt(), expected++);

  QCOMPARE(expected, 9);

  const auto tables = doc[Keys::Tables].toArray();
  QCOMPARE(tables.size(), 2);
  QCOMPARE(tables.at(0).toObject()[Keys::Registers].toArray().size(), 6);
  QCOMPARE(tables.at(1).toObject()[Keys::Registers].toArray().size(), 2);
}

void TstDbcImporter::selectorsPrecedeTheirDependents()
{
  const auto doc = project(QStringLiteral("extended_mux.dbc"));
  const auto lua = doc[Keys::Sources].toArray().at(0).toObject()[Keys::FrameParserCode].toString();

  const auto mode        = lua.indexOf(QStringLiteral("{ name = \"Mode\","));
  const auto subMode     = lua.indexOf(QStringLiteral("{ name = \"SubMode\","));
  const auto packVoltage = lua.indexOf(QStringLiteral("{ name = \"PackVoltage\","));
  const auto faultCount  = lua.indexOf(QStringLiteral("{ name = \"FaultCount\","));
  const auto temperature = lua.indexOf(QStringLiteral("{ name = \"Temperature\","));

  QVERIFY(mode >= 0);
  QVERIFY(subMode > mode);
  QVERIFY(packVoltage > subMode);
  QVERIFY(faultCount > subMode);
  QVERIFY(temperature > mode);
}

void TstDbcImporter::extendedRangesReachTheLuaSpec()
{
  const auto doc = project(QStringLiteral("extended_mux.dbc"));
  const auto lua = doc[Keys::Sources].toArray().at(0).toObject()[Keys::FrameParserCode].toString();

  const auto mode = specLineFor(lua, QStringLiteral("Mode"));
  QVERIFY(mode.contains(QStringLiteral(", selector = true")));
  QVERIFY(!mode.contains(QStringLiteral(", mux = ")));

  const auto subMode = specLineFor(lua, QStringLiteral("SubMode"));
  QVERIFY(subMode.contains(QStringLiteral(", selector = true")));
  QVERIFY(subMode.contains(QStringLiteral(", mux = {p = \"Mode\", r = {{1, 1}}}")));

  QVERIFY(specLineFor(lua, QStringLiteral("PackVoltage"))
            .contains(QStringLiteral(", mux = {p = \"SubMode\", r = {{0, 3}}}")));
  QVERIFY(specLineFor(lua, QStringLiteral("FaultCount"))
            .contains(QStringLiteral(", mux = {p = \"SubMode\", r = {{4, 4}, {9, 11}}}")));
  QVERIFY(specLineFor(lua, QStringLiteral("Temperature"))
            .contains(QStringLiteral(", mux = {p = \"Mode\", r = {{2, 2}, {5, 7}}}")));
  QVERIFY(specLineFor(lua, QStringLiteral("SerialNumber")).contains(QStringLiteral(", mux = 3")));
}

void TstDbcImporter::datasetTitlesCarryTheSwitchValues()
{
  const auto titles = datasetTitles(project(QStringLiteral("extended_mux.dbc")));

  QVERIFY(titles.contains(QStringLiteral("Mode (selector)")));
  QVERIFY(titles.contains(QStringLiteral("SubMode (selector, mux 1)")));
  QVERIFY(titles.contains(QStringLiteral("PackVoltage (mux 0-3)")));
  QVERIFY(titles.contains(QStringLiteral("FaultCount (mux 4,9-11)")));
  QVERIFY(titles.contains(QStringLiteral("Temperature (mux 2,5-7)")));
  QVERIFY(titles.contains(QStringLiteral("SerialNumber (mux 3)")));
  QVERIFY(titles.contains(QStringLiteral("Uptime")));
}

void TstDbcImporter::generatedLuaMatchesRangesAtRuntime()
{
  const auto doc = project(QStringLiteral("extended_mux.dbc"));
  const auto lua = doc[Keys::Sources].toArray().at(0).toObject()[Keys::FrameParserCode].toString();

  QVERIFY(lua.contains(QStringLiteral("local function in_ranges(value, ranges)")));
  QVERIFY(lua.contains(QStringLiteral("if value >= range[1] and value <= range[2] then")));
  QVERIFY(lua.contains(QStringLiteral("local function mux_ok(mux, selectors, root)")));
  QVERIFY(lua.contains(QStringLiteral("if type(mux) == \"number\" then")));
  QVERIFY(lua.contains(QStringLiteral("return mux == root")));
  QVERIFY(lua.contains(QStringLiteral("return value ~= nil and in_ranges(value, mux.r)")));
  QVERIFY(
    lua.contains(QStringLiteral("if sig.mux == nil or mux_ok(sig.mux, selectors, root) then")));
  QVERIFY(lua.contains(QStringLiteral("selectors[sig.name] = raw")));
  QVERIFY(lua.contains(QStringLiteral("root = root or raw")));
}

void TstDbcImporter::generatedLuaStaysWithinLua51()
{
  const auto doc = project(QStringLiteral("extended_mux.dbc"));
  const auto lua = doc[Keys::Sources].toArray().at(0).toObject()[Keys::FrameParserCode].toString();

  QVERIFY(!lua.contains(QStringLiteral("<<")));
  QVERIFY(!lua.contains(QStringLiteral(">>")));
  QVERIFY(!lua.contains(QStringLiteral(" // ")));
  QVERIFY(!lua.contains(QStringLiteral("string.pack")));
  QVERIFY(!lua.contains(QStringLiteral("string.unpack")));
  QVERIFY(lua.contains(QStringLiteral("bit.band")));
  QVERIFY(lua.contains(QStringLiteral("math.floor")));
}

void TstDbcImporter::simpleMuxKeepsTheScalarForm()
{
  const auto doc = project(QStringLiteral("simple_mux.dbc"));
  const auto lua = doc[Keys::Sources].toArray().at(0).toObject()[Keys::FrameParserCode].toString();

  QVERIFY(!lua.contains(QStringLiteral("mux = {p = ")));
  QVERIFY(
    specLineFor(lua, QStringLiteral("Channel")).contains(QStringLiteral(", selector = true")));
  QVERIFY(specLineFor(lua, QStringLiteral("ChannelVoltage")).contains(QStringLiteral(", mux = 0")));
  QVERIFY(specLineFor(lua, QStringLiteral("ChannelCurrent")).contains(QStringLiteral(", mux = 1")));
  QVERIFY(specLineFor(lua, QStringLiteral("ChannelTemp")).contains(QStringLiteral(", mux = 2")));

  const auto titles = datasetTitles(doc);
  QVERIFY(titles.contains(QStringLiteral("Channel (selector)")));
  QVERIFY(titles.contains(QStringLiteral("ChannelVoltage (mux 0)")));
  QVERIFY(titles.contains(QStringLiteral("ChannelTemp (mux 2)")));
  QVERIFY(titles.contains(QStringLiteral("Timestamp")));
}

void TstDbcImporter::simpleMuxSpecMatchesTheStoredExpectation()
{
  const auto doc = project(QStringLiteral("simple_mux.dbc"));
  const auto lua = doc[Keys::Sources].toArray().at(0).toObject()[Keys::FrameParserCode].toString();

  const QStringList expected = {
    QStringLiteral("{ name = \"ChannelCurrent\", start = 8, len = 16, factor = 0.1, mux = 1 },"),
    QStringLiteral("{ name = \"ChannelTemp\", start = 8, len = 16, signed = true, factor = 0.5, "
                   "mux = 2 },"),
    QStringLiteral("{ name = \"ChannelVoltage\", start = 8, len = 16, factor = 0.1, mux = 0 },"),
    QStringLiteral("{ name = \"Channel\", start = 0, len = 8, selector = true }, -- Selects which "
                   "measurement rides in bytes 1-2"),
    QStringLiteral("{ name = \"LinkUp\", start = 24, len = 1 }, -- Gateway link state"),
    QStringLiteral("{ name = \"Timestamp\", start = 48, len = 16 },"),
    QStringLiteral("{ name = \"Uptime\", start = 0, len = 24 },"),
  };

  auto sorted = expected;
  sorted.sort();
  QCOMPARE(specLines(lua), sorted);
}

nodiscard]] static QByteArray unnumbered(UFunction function)
{
  QByteArray apdu(kApciBytes, static_cast<char>(0));
  apdu[0] = static_cast<char>(kStartByte);
  apdu[1] = static_cast<char>(kMinApduLength);
  apdu[2] = static_cast<char>(function);
  return apdu;
}

nodiscard]] static QByteArray supervisory(int recvSeq)
{
  QByteArray apdu(kApciBytes, static_cast<char>(0));
  apdu[0] = static_cast<char>(kStartByte);
  apdu[1] = static_cast<char>(kMinApduLength);
  apdu[2] = static_cast<char>(0x01);
  apdu[4] = static_cast<char>((recvSeq << 1) & 0xFE);
  apdu[5] = static_cast<char>((recvSeq >> 7) & 0xFF);
  return apdu;
}

nodiscard]] static QByteArray information(int sendSeq, int recvSeq, const QByteArray& payload)
{
  QByteArray apdu(kApciBytes, static_cast<char>(0));
  apdu[0] = static_cast<char>(kStartByte);
  apdu[1] = static_cast<char>(kMinApduLength + payload.size());
  apdu[2] = static_cast<char>((sendSeq << 1) & 0xFE);
  apdu[3] = static_cast<char>((sendSeq >> 7) & 0xFF);
  apdu[4] = static_cast<char>((recvSeq << 1) & 0xFE);
  apdu[5] = static_cast<char>((recvSeq >> 7) & 0xFF);
  apdu.append(payload);
  return apdu;
}

id TstIec104Apci::startDtHandshakeCompletes()
{
  Connection link;
  link.reset(0);

  const auto act = link.encodeUnnumbered(UFunction::StartDtAct, 0);
  QCOMPARE(act, unnumbered(UFunction::StartDtAct));
  QCOMPARE(act.size(), qsizetype(kApciBytes));
  QVERIFY(link.confirmOverdue(kDefaultT1Ms));

  Apdu apdu;
  const auto con = unnumbered(UFunction::StartDtCon);
  QCOMPARE(link.consume(con, apdu, 100), ParseResult::Ok);
  QCOMPARE(apdu.type, FrameType::Unnumbered);
  QCOMPARE(apdu.function, UFunction::StartDtCon);
  QCOMPARE(apdu.apduSize, qsizetype(kApciBytes));
  QVERIFY(!link.confirmOverdue(100 + kDefaultT1Ms));
}

id TstIec104Apci::testFrameKeepsTheLinkAlive()
{
  Connection link;
  link.reset(0);

  QCOMPARE(Connection::confirmationFor(UFunction::TestFrAct), UFunction::TestFrCon);
  QCOMPARE(Connection::confirmationFor(UFunction::StopDtAct), UFunction::StopDtCon);
  QCOMPARE(Connection::confirmationFor(UFunction::TestFrCon), UFunction::None);
  QVERIFY(Connection::isConfirmation(UFunction::StartDtCon));
  QVERIFY(!Connection::isConfirmation(UFunction::StartDtAct));

  (void)link.encodeUnnumbered(UFunction::TestFrAct, 1000);
  QVERIFY(link.confirmOverdue(1000 + kDefaultT1Ms));

  Apdu apdu;
  const auto con = unnumbered(UFunction::TestFrCon);
  QCOMPARE(link.consume(con, apdu, 1200), ParseResult::Ok);
  QVERIFY(!link.confirmOverdue(1200 + kDefaultT1Ms));
  QCOMPARE(link.framesSent(), quint64(1));
  QCOMPARE(link.framesReceived(), quint64(1));
}

id TstIec104Apci::informationFramesAdvanceTheSendCounter()
{
  Connection link;
  link.reset(0);

  const QByteArray payload("\x01\x02\x03", 3);
  for (int i = 0; i < 3; ++i) {
    const auto frame = link.encodeInformation(payload, 0);
    QCOMPARE(frame, information(i, 0, payload));
    QCOMPARE(link.sendSeq(), i + 1);
    QCOMPARE(link.outstanding(), i + 1);
  }

  QCOMPARE(link.ackedSeq(), 0);
}

id TstIec104Apci::receivedFramesAdvanceTheReceiveCounter()
{
  Connection link;
  link.reset(0);

  const QByteArray payload("\x0a\x0b", 2);
  const auto frame = information(0, 0, payload);

  Apdu apdu;
  QCOMPARE(link.consume(frame, apdu, 10), ParseResult::Ok);
  QCOMPARE(apdu.type, FrameType::Information);
  QCOMPARE(apdu.sendSeq, 0);
  QCOMPARE(apdu.asduOffset, qsizetype(kApciBytes));
  QCOMPARE(apdu.asduSize, qsizetype(payload.size()));
  QCOMPARE(frame.mid(apdu.asduOffset, apdu.asduSize), payload);
  QCOMPARE(link.recvSeq(), 1);
  QCOMPARE(link.unackedReceived(), 1);
}

id TstIec104Apci::outOfOrderSendSequenceIsRefused()
{
  Connection link;
  link.reset(0);

  const QByteArray payload("\x01", 1);
  const auto skipped = information(4, 0, payload);

  Apdu apdu;
  QCOMPARE(link.consume(skipped, apdu, 10), ParseResult::OutOfOrder);
  QCOMPARE(link.sequenceErrors(), quint64(1));
  QCOMPARE(link.recvSeq(), 0);
  QCOMPARE(apdu.apduSize, qsizetype(kApciBytes + 1));
}

id TstIec104Apci::acknowledgementBeyondWhatWasSentIsRefused()
{
  Connection link;
  link.reset(0);

  const QByteArray payload("\x01", 1);
  (void)link.encodeInformation(payload, 0);

  Apdu apdu;
  const auto ahead = supervisory(5);
  QCOMPARE(link.consume(ahead, apdu, 10), ParseResult::OutOfOrder);
  QCOMPARE(link.sequenceErrors(), quint64(1));
  QCOMPARE(link.ackedSeq(), 0);
  QCOMPARE(link.outstanding(), 1);
}

id TstIec104Apci::sequenceCountersWrapAtFifteenBits()
{
  Connection link;
  link.reset(0);

  Apdu apdu;
  const QByteArray payload("\x01", 1);
  for (int i = 0; i < kSequenceModulo; ++i) {
    QVERIFY(!link.encodeInformation(payload, 0).isEmpty());
    const auto ack = supervisory((i + 1) % kSequenceModulo);
    QCOMPARE(link.consume(ack, apdu, 0), ParseResult::Ok);
  }

  QCOMPARE(link.sendSeq(), 0);
  QCOMPARE(link.ackedSeq(), 0);
  QCOMPARE(link.outstanding(), 0);

  for (int i = 0; i < kSequenceModulo; ++i) {
    const auto frame = information(i, 0, payload);
    QCOMPARE(link.consume(frame, apdu, 0), ParseResult::Ok);
    (void)link.encodeSupervisory(0);
  }

  QCOMPARE(link.recvSeq(), 0);
  QCOMPARE(link.unackedReceived(), 0);
}

id TstIec104Apci::sendWindowClosesAtK()
{
  Connection link;
  link.reset(0);

  const QByteArray payload("\x01", 1);
  for (int i = 0; i < kDefaultK; ++i) {
    QVERIFY(link.sendWindowOpen());
    QVERIFY(!link.encodeInformation(payload, 0).isEmpty());
  }

  QVERIFY(!link.sendWindowOpen());
  QVERIFY(link.encodeInformation(payload, 0).isEmpty());
  QCOMPARE(link.outstanding(), kDefaultK);
}

id TstIec104Apci::supervisoryAcknowledgementReopensTheWindow()
{
  Connection link;
  link.reset(0);

  const QByteArray payload("\x01", 1);
  for (int i = 0; i < kDefaultK; ++i)
    (void)link.encodeInformation(payload, 0);

  Apdu apdu;
  const auto ack = supervisory(kDefaultK);
  QCOMPARE(link.consume(ack, apdu, 50), ParseResult::Ok);
  QCOMPARE(apdu.type, FrameType::Supervisory);
  QCOMPARE(apdu.recvSeq, kDefaultK);
  QCOMPARE(link.outstanding(), 0);
  QVERIFY(link.sendWindowOpen());
  QVERIFY(!link.confirmOverdue(50 + kDefaultT1Ms));
}

id TstIec104Apci::acknowledgementIsDueAtWindowW()
{
  Connection link;
  link.reset(0);

  const QByteArray payload("\x01", 1);
  Apdu apdu;
  for (int i = 0; i < kDefaultW; ++i) {
    const auto frame = information(i, 0, payload);
    QCOMPARE(link.consume(frame, apdu, 10), ParseResult::Ok);
  }

  QVERIFY(link.ackDue(10));
  QCOMPARE(link.unackedReceived(), kDefaultW);

  const auto ack = link.encodeSupervisory(20);
  QCOMPARE(ack, supervisory(kDefaultW));
  QVERIFY(!link.ackDue(20));
  QCOMPARE(link.unackedReceived(), 0);
}

id TstIec104Apci::acknowledgementIsDueAtT2()
{
  Connection link;
  link.reset(0);

  const QByteArray payload("\x01", 1);
  const auto frame = information(0, 0, payload);

  Apdu apdu;
  QCOMPARE(link.consume(frame, apdu, 1000), ParseResult::Ok);
  QVERIFY(!link.ackDue(1000 + kDefaultT2Ms - 1));
  QVERIFY(link.ackDue(1000 + kDefaultT2Ms));
}

id TstIec104Apci::testIsDueAtT3()
{
  Connection link;
  link.reset(0);

  QVERIFY(!link.testDue(kDefaultT3Ms - 1));
  QVERIFY(link.testDue(kDefaultT3Ms));

  (void)link.encodeUnnumbered(UFunction::TestFrAct, kDefaultT3Ms);
  QVERIFY(!link.testDue(kDefaultT3Ms * 3));

  Apdu apdu;
  const auto con = unnumbered(UFunction::TestFrCon);
  QCOMPARE(link.consume(con, apdu, kDefaultT3Ms + 10), ParseResult::Ok);
  QVERIFY(!link.testDue(kDefaultT3Ms + 20));
  QVERIFY(link.testDue(kDefaultT3Ms * 2 + 10));
}

id TstIec104Apci::unconfirmedActivationExpiresAtT1()
{
  Connection link;
  link.reset(0);

  QVERIFY(!link.confirmOverdue(kDefaultT1Ms));

  (void)link.encodeUnnumbered(UFunction::StartDtAct, 500);
  QVERIFY(!link.confirmOverdue(500 + kDefaultT1Ms - 1));
  QVERIFY(link.confirmOverdue(500 + kDefaultT1Ms));
}

id TstIec104Apci::unacknowledgedInformationExpiresAtT1()
{
  Connection link;
  link.reset(0);

  const QByteArray payload("\x01", 1);
  (void)link.encodeInformation(payload, 300);
  QVERIFY(!link.confirmOverdue(300 + kDefaultT1Ms - 1));
  QVERIFY(link.confirmOverdue(300 + kDefaultT1Ms));

  Apdu apdu;
  const auto ack = supervisory(1);
  QCOMPARE(link.consume(ack, apdu, 400), ParseResult::Ok);
  QVERIFY(!link.confirmOverdue(400 + kDefaultT1Ms));
}

id TstIec104Apci::partialFramesAskForMoreData()
{
  Connection link;
  link.reset(0);

  const QByteArray payload("\x01\x02\x03\x04", 4);
  const auto frame = information(0, 0, payload);

  Apdu apdu;
  for (qsizetype cut = 0; cut < frame.size(); ++cut) {
    const auto partial = frame.left(cut);
    QCOMPARE(link.consume(partial, apdu, 0), ParseResult::NeedMore);
  }

  QCOMPARE(link.framesReceived(), quint64(0));
  QCOMPARE(link.malformedFrames(), quint64(0));
  QCOMPARE(link.consume(frame, apdu, 0), ParseResult::Ok);
}

