  QCOMPARE(decoded.typeId, std::uint8_t(kTypeInterrogation));
  QCOMPARE(decoded.cause, std::uint8_t(kCauseActivation));
  QCOMPARE(decoded.commonAddress, quint16(258));
  QCOMPARE(decoded.objectCount, std::uint8_t(1));
  QVERIFY(points.isEmpty());
}

nodiscard]] static QByteArray onePoint(const QString& measurement,
                                         const QString& key,
                                         const QString& value,
                                         qint64 timestampNs)
{
  LineBatch batch;
  batch.beginPoint(measurement);
  (void)batch.addFieldString(key, value);
  (void)batch.endPoint(timestampNs);
  return batch.payload().trimmed();
}

