  for (int length = 0; length <= full.size(); ++length) {
    QString error;
    const auto address = parse(full.left(length), error);
    QVERIFY2(isValid(address) || !error.isEmpty(), qPrintable(full.left(length)));
    if (!isValid(address))
      QCOMPARE(address.size, 0);
  }
}

