                           0xC0, 0x01, 0x0A, 0xC1, 0x02, 0x01, 0x00, 0xC2, 0x02, 0x03, 0x01}));
  QCOMPARE(request.size(), qsizetype(kTpktHeaderBytes + kConnectTpduBytes));
  QCOMPARE(transport.framesSent(), quint64(1));
}

