{
  QFETCH(int, declared);
  QFETCH(int, expected);

  const auto parameters =
    bytes({0xF0, 0x00, 0x00, 0x01, 0x00, 0x01, (declared >> 8) & 0xFF, declared & 0xFF});

  PduCodec codec;
  QCOMPARE(codec.parseSetupResponse(acknowledgement(1, parameters, QByteArray(), 0, 0)),
           PduResult::Ok);
  QCOMPARE(codec.pduBytes(), expected);
