                        << 0.0 << false << QStringLiteral("free form");
  QTest::newRow("uuid") << code(DataType::Uuid) << textValue(QByteArray("6f9619ff-8b86-d011"))
                        << kStringKind << 0.0 << false << QStringLiteral("6f9619ff-8b86-d011");
