id TstSparkplugPayload::scalarDataTypes()
{
  QFETCH(quint32, datatype);
  QFETCH(QByteArray, value);
  QFETCH(int, kind);
  QFETCH(double, numeric);
  QFETCH(bool, boolean);
  QFETCH(QString, text);

  Payload payload;
  QString error;
  const auto wire = payloadOf({metricOf(QByteArray("m"), datatype, value)});
  QVERIFY2(decodePayload(wire, payload, &error), qPrintable(error));
  QVERIFY(error.isEmpty());
  QCOMPARE(payload.metrics.size(), qsizetype(1));

  const auto& metric = payload.metrics.constFirst();
  QVERIFY(metric.supported);
  QVERIFY(metric.hasName);
  QVERIFY(!metric.hasAlias);
  QVERIFY(!metric.isNull);
  QCOMPARE(metric.name, QStringLiteral("m"));
  QCOMPARE(metric.datatype, datatype);
  QCOMPARE(static_cast<int>(metric.kind), kind);
  QCOMPARE(metric.numericValue, numeric);
  QCOMPARE(metric.boolValue, boolean);
  QCOMPARE(metric.stringValue, text);
}

id TstSparkplugPayload::aliasOnlyMetric()
{
  QByteArray metric;
  appendVarintField(metric, kMetricAlias, 42);
  appendVarintField(metric, kMetricDatatype, code(DataType::Int32));
  appendVarintField(metric, kMetricIntValue, 7);

  Payload payload;
  QString error;
  QVERIFY2(decodePayload(payloadOf({metric}), payload, &error), qPrintable(error));
  QCOMPARE(payload.metrics.size(), qsizetype(1));

  const auto& decoded = payload.metrics.constFirst();
  QVERIFY(decoded.hasAlias);
  QVERIFY(!decoded.hasName);
  QVERIFY(decoded.name.isEmpty());
  QCOMPARE(decoded.alias, quint64(42));
  QCOMPARE(decoded.numericValue, 7.0);
}

id TstSparkplugPayload::datatypeAfterValue()
{
  QByteArray narrow;
  appendLenDelim(narrow, kMetricName, QByteArray("late"));
  appendVarintField(narrow, kMetricIntValue, signedRaw(-300));
  appendVarintField(narrow, kMetricDatatype, code(DataType::Int16));

  QByteArray real;
  appendFixed(real, kMetricDoubleValue, std::bit_cast<quint64>(-2.75), 8);
  appendVarintField(real, kMetricDatatype, code(DataType::Double));

  Payload payload;
  QString error;
  QVERIFY2(decodePayload(payloadOf({narrow, real}), payload, &error), qPrintable(error));
  QCOMPARE(payload.metrics.size(), qsizetype(2));
  QCOMPARE(static_cast<int>(payload.metrics.at(0).kind), kNumericKind);
  QCOMPARE(payload.metrics.at(0).numericValue, -300.0);
  QCOMPARE(payload.metrics.at(1).numericValue, -2.75);
}

id TstSparkplugPayload::nullMetric()
{
  QByteArray metric;
  appendLenDelim(metric, kMetricName, QByteArray("offline"));
  appendVarintField(metric, kMetricDatatype, code(DataType::Double));
  appendVarintField(metric, kMetricIsNull, 1);
  appendFixed(metric, kMetricDoubleValue, std::bit_cast<quint64>(9.5), 8);

  Payload payload;
  QString error;
  QVERIFY2(decodePayload(payloadOf({metric}), payload, &error), qPrintable(error));
  QCOMPARE(payload.metrics.size(), qsizetype(1));

  const auto& decoded = payload.metrics.constFirst();
  QVERIFY(decoded.isNull);
  QVERIFY(decoded.supported);
  QCOMPARE(static_cast<int>(decoded.kind), kNumericKind);
  QCOMPARE(decoded.numericValue, 0.0);
}

id TstSparkplugPayload::unsupportedDataTypes_data()
{
  QTest::addColumn<quint32>("datatype");
  QTest::addColumn<QByteArray>("value");

  QTest::newRow("datetime") << code(DataType::DateTime)
                            << varintValue(kMetricLongValue, 1700000000000ULL);
  QTest::newRow("code-16") << quint32(16) << varintValue(kMetricLongValue, 1);
  QTest::newRow("code-17") << quint32(17) << varintValue(kMetricIntValue, 1);
  QTest::newRow("unknown") << code(DataType::Unknown) << varintValue(kMetricIntValue, 1);
}

id TstSparkplugPayload::unsupportedDataTypes()
{
  QFETCH(quint32, datatype);
  QFETCH(QByteArray, value);

  Payload payload;
  QString error;
  const auto wire = payloadOf({metricOf(QByteArray("odd"), datatype, value)});
  QVERIFY2(decodePayload(wire, payload, &error), qPrintable(error));
  QCOMPARE(payload.metrics.size(), qsizetype(1));

  const auto& metric = payload.metrics.constFirst();
  QVERIFY(!metric.supported);
  QVERIFY(metric.hasName);
  QCOMPARE(metric.datatype, datatype);
  QCOMPARE(static_cast<int>(metric.kind), kNoneKind);
  QCOMPARE(metric.numericValue, 0.0);
  QCOMPARE(metric.boolValue, false);
}

id TstSparkplugPayload::unknownFieldsSkipped()
{
  QByteArray metric;
  appendLenDelim(metric, 5, QByteArray("metadata"));
  appendVarintField(metric, 8, 12345);
  appendFixed(metric, 16, 0x1122334455667788ULL, 8);
  appendLenDelim(metric, kMetricName, QByteArray("kept"));
  appendVarintField(metric, kMetricDatatype, code(DataType::UInt16));
  appendVarintField(metric, kMetricIntValue, 4321);
  appendFixed(metric, 20, 0x11223344ULL, 4);

  QByteArray wire;
  appendVarintField(wire, 42, 99);
  appendLenDelim(wire, kPayloadBody, QByteArray("body"));
  appendLenDelim(wire, kPayloadMetrics, metric);
  appendFixed(wire, 43, 0x55667788ULL, 4);
  appendFixed(wire, 44, 0x1122334455667788ULL, 8);
  appendLenDelim(wire, kPayloadUuid, QByteArray("2f1c"));

  Payload payload;
  QString error;
  QVERIFY2(decodePayload(wire, payload, &error), qPrintable(error));
  QCOMPARE(payload.metrics.size(), qsizetype(1));
  QCOMPARE(payload.metrics.constFirst().name, QStringLiteral("kept"));
  QCOMPARE(payload.metrics.constFirst().numericValue, 4321.0);
}

id TstSparkplugPayload::payloadHeaderFlags()
{
  Payload payload;
  QString error;
  QVERIFY2(decodePayload(richPayload(), payload, &error), qPrintable(error));
  QVERIFY(payload.hasTimestamp);
  QVERIFY(payload.hasSeq);
  QCOMPARE(payload.timestampMs, quint64(1700000000000ULL));
  QCOMPARE(payload.seq, quint64(3));
  QCOMPARE(payload.metrics.size(), qsizetype(2));
  QCOMPARE(payload.metrics.at(0).timestampMs, quint64(1700000000001ULL));
  QCOMPARE(payload.metrics.at(0).numericValue, 21.5);
  QCOMPARE(payload.metrics.at(1).stringValue, QStringLiteral("RUNNING"));

  QByteArray bare;
  appendLenDelim(
    bare,
    kPayloadMetrics,
    metricOf(QByteArray("n"), code(DataType::Boolean), varintValue(kMetricBooleanValue, 0)));
  QVERIFY2(decodePayload(bare, payload, &error), qPrintable(error));
  QVERIFY(!payload.hasTimestamp);
  QVERIFY(!payload.hasSeq);
  QCOMPARE(payload.timestampMs, quint64(0));
  QCOMPARE(payload.seq, quint64(0));
}

id TstSparkplugPayload::hostileInput_data()
{
  QTest::addColumn<QByteArray>("data");

  QByteArray truncatedVarint;
  appendTag(truncatedVarint, kPayloadTimestamp, kWireVarint);
  truncatedVarint.append("\xFF\xFF", 2);
  QTest::newRow("truncated varint") << truncatedVarint;

  QByteArray truncatedBlock;
  appendTag(truncatedBlock, kPayloadMetrics, kWireLengthDelimited);
  appendVarint(truncatedBlock, 10);
  truncatedBlock.append("abc", 3);
  QTest::newRow("truncated block") << truncatedBlock;

  QByteArray lyingLength;
  appendTag(lyingLength, kPayloadMetrics, kWireLengthDelimited);
  appendVarint(lyingLength, static_cast<quint64>(kMaxPayloadBytes) - 1);
  QTest::newRow("length past buffer") << lyingLength;

  QByteArray hugeLength;
  appendTag(hugeLength, kPayloadMetrics, kWireLengthDelimited);
  appendVarint(hugeLength, static_cast<quint64>(kMaxPayloadBytes) + 1);
  QTest::newRow("length past cap") << hugeLength;

  QTest::newRow("continuation run") << QByteArray(kMaxVarintBytes + 1, static_cast<char>(0xFF));
  QTest::newRow("field number zero") << QByteArray(1, static_cast<char>(0x00));

  QByteArray wideTag;
  appendVarint(wideTag, (kMaxFieldNumber + 1) << 3);
  QTest::newRow("field number too wide") << wideTag;

  QByteArray groupStart;
  appendTag(groupStart, kPayloadUuid, 3);
  QTest::newRow("payload group start") << groupStart;

  QByteArray groupEnd;
  appendTag(groupEnd, kPayloadUuid, 4);
  QTest::newRow("payload group end") << groupEnd;

  QByteArray metricGroup;
  appendTag(metricGroup, 18, 3);
  QTest::newRow("metric group start") << payloadOf({metricGroup});

  QByteArray metricString;
  appendTag(metricString, kMetricName, kWireLengthDelimited);
  appendVarint(metricString, 20);
  metricString.append("xy", 2);
  QTest::newRow("metric string past block") << payloadOf({metricString});

  QByteArray wrongWire;
  appendFixed(wrongWire, kPayloadTimestamp, 1, 4);
  QTest::newRow("timestamp wrong wire type") << wrongWire;

  QByteArray metricsAsVarint;
  appendVarintField(metricsAsVarint, kPayloadMetrics, 5);
  QTest::newRow("metrics wrong wire type") << metricsAsVarint;

  QByteArray shortFixed;
  appendTag(shortFixed, kPayloadUuid, kWireFixed64);
  shortFixed.append("abc", 3);
  QTest::newRow("truncated fixed64") << shortFixed;
}

id TstSparkplugPayload::hostileInput()
{
  QFETCH(QByteArray, data);

  Payload payload;
  QString error;
  QVERIFY(!decodePayload(data, payload, &error));
  QVERIFY(!error.isEmpty());
  QVERIFY(!decodePayload(data, payload, nullptr));
}

id TstSparkplugPayload::everyPrefixDecodesCleanly()
{
  const QByteArray full = richPayload();
  QVERIFY(full.size() > 32);

  for (qsizetype i = 0; i <= full.size(); ++i) {
    Payload payload;
    QString error = QStringLiteral("stale");
    const bool ok = decodePayload(QByteArrayView(full.constData(), i), payload, &error);
    QVERIFY2(ok == error.isEmpty(), qPrintable(QString::number(i)));
    QVERIFY2(payload.metrics.size() <= qsizetype(2), qPrintable(QString::number(i)));
  }

  Payload payload;
  QVERIFY(decodePayload(QByteArrayView(full.constData(), full.size()), payload, nullptr));
  QCOMPARE(payload.metrics.size(), qsizetype(2));
}

id TstSparkplugPayload::capsRejectOversizedInput()
{
  Payload payload;
  QString error;
  QVERIFY(!decodePayload(QByteArray(kMaxPayloadBytes + 1, '\0'), payload, &error));
  QVERIFY(error.contains(QString::number(kMaxPayloadBytes)));

  QByteArray tooMany;
  for (int i = 0; i <= kMaxMetrics; ++i)
    appendLenDelim(tooMany, kPayloadMetrics, QByteArray());

  QVERIFY(!decodePayload(tooMany, payload, &error));
  QVERIFY(error.contains(QString::number(kMaxMetrics)));

  QByteArray longString;
  appendVarintField(longString, kMetricDatatype, code(DataType::String));
  appendLenDelim(longString, kMetricStringValue, QByteArray(kMaxStringBytes + 1, 'x'));
  QVERIFY(!decodePayload(payloadOf({longString}), payload, &error));
  QVERIFY(!error.isEmpty());

  QByteArray atCap;
  for (int i = 0; i < kMaxMetrics; ++i)
    appendLenDelim(atCap, kPayloadMetrics, QByteArray());

  QVERIFY2(decodePayload(atCap, payload, &error), qPrintable(error));
  QCOMPARE(payload.metrics.size(), qsizetype(kMaxMetrics));
}

id TstSparkplugPayload::rebirthRequestRoundTrip()
{
  const QByteArray encoded = encodeRebirthRequest(1700000000000ULL);
  QVERIFY(!encoded.isEmpty());

  Payload payload;
  QString error;
  QVERIFY2(decodePayload(encoded, payload, &error), qPrintable(error));
  QVERIFY(payload.hasTimestamp);
  QVERIFY(!payload.hasSeq);
  QCOMPARE(payload.timestampMs, quint64(1700000000000ULL));
  QCOMPARE(payload.metrics.size(), qsizetype(1));

  const auto& metric = payload.metrics.constFirst();
  QVERIFY(metric.hasName);
  QVERIFY(metric.supported);
  QVERIFY(!metric.isNull);
  QVERIFY(metric.boolValue);
  QCOMPARE(metric.name, QString::fromUtf8(kRebirthMetricName));
  QCOMPARE(metric.datatype, code(DataType::Boolean));
  QCOMPARE(static_cast<int>(metric.kind), kBooleanKind);
}

nodiscard]] static SparkplugPublisher::Config nodeConfig(const QString& device = QString())
{
  SparkplugPublisher::Config config;
  config.enabled    = true;
  config.groupId    = QString::fromUtf8(kGroup);
  config.edgeNodeId = QString::fromUtf8(kNode);
  config.deviceId   = device;
  return config;
}

nodiscard]] static Payload decoded(const SparkplugPublisher::Message& message)
{
  Payload payload;
  QString error;
  const bool ok = decodePayload(message.payload, payload, &error);
  if (!ok)
    qWarning("payload on %s did not decode: %s", qPrintable(message.topic), qPrintable(error));

  return payload;
}

nodiscard]] static Metric metricNamed(const Payload& payload, const char* name)
{
  const auto wanted = QString::fromUtf8(name);
  for (const auto& metric : payload.metrics)
    if (metric.hasName && metric.name == wanted)
      return metric;

  return Metric();
}

nodiscard]] static bool hasAlias(const Payload& payload, quint64 alias)
{
  for (const auto& metric : payload.metrics)
    if (metric.hasAlias && metric.alias == alias)
      return true;

  return false;
}

nodiscard]] static double birthDeathSequence(const SparkplugPublisher::Message& message)
{
  const auto payload = decoded(message);
  const auto metric  = metricNamed(payload, MQTT::SparkplugPublisherLimits::kBirthDeathSequence);
  return metric.numericValue;
}

id TstSparkplugPublisher::topicsFollowTheNamespace()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  QVERIFY(node.valid());
  QCOMPARE(node.commandTopic(), QStringLiteral("spBv1.0/Plant1/NCMD/SS1"));

  const auto will = node.beginConnection(1000);
  QCOMPARE(will.topic, QStringLiteral("spBv1.0/Plant1/NDEATH/SS1"));
  QCOMPARE(static_cast<int>(will.qos), 1);
  QVERIFY(!will.retain);

  const auto birth = node.birthMessages(1000);
  QCOMPARE(birth.size(), qsizetype(1));
  QCOMPARE(birth.constFirst().topic, QStringLiteral("spBv1.0/Plant1/NBIRTH/SS1"));
  QCOMPARE(static_cast<int>(birth.constFirst().qos), 0);
}

id TstSparkplugPublisher::birthDeclaresEveryMetric()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  node.registerMetric(0, 11, QStringLiteral("Sensors/Temperature"), code(DataType::Double), 1);
  node.registerMetric(0, 22, QStringLiteral("Sensors/State"), code(DataType::String), 1);
  node.registerMetric(0, 33, QStringLiteral("Sensors/Valve"), code(DataType::Boolean), 1);
  QCOMPARE(node.metricCount(), 3);

  const auto will = node.beginConnection(1000);
  QVERIFY(!will.payload.isEmpty());

  const auto birth = node.birthMessages(1700000000000ULL);
  QCOMPARE(birth.size(), qsizetype(1));

  const auto payload = decoded(birth.constFirst());
  QVERIFY(payload.hasSeq);
  QVERIFY(payload.hasTimestamp);
  QCOMPARE(payload.metrics.size(), qsizetype(5));

  const auto temperature = metricNamed(payload, "Sensors/Temperature");
  QVERIFY(temperature.hasName);
  QVERIFY(temperature.hasAlias);
  QCOMPARE(temperature.alias, quint64(1));
  QCOMPARE(temperature.datatype, code(DataType::Double));
  QCOMPARE(static_cast<int>(temperature.kind), kNumericKind);

  const auto state = metricNamed(payload, "Sensors/State");
  QCOMPARE(state.alias, quint64(2));
  QCOMPARE(static_cast<int>(state.kind), kStringKind);

  const auto valve = metricNamed(payload, "Sensors/Valve");
  QCOMPARE(valve.alias, quint64(3));
  QCOMPARE(static_cast<int>(valve.kind), kBooleanKind);

  const auto control = metricNamed(payload, kRebirthMetricName);
  QVERIFY(control.hasName);
  QCOMPARE(static_cast<int>(control.kind), kBooleanKind);
}

id TstSparkplugPublisher::dataCarriesOnlyChangedMetrics()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  node.registerMetric(0, 11, QStringLiteral("Temperature"), code(DataType::Double), 1);
  node.registerMetric(0, 22, QStringLiteral("State"), code(DataType::String), 1);

  const auto will = node.beginConnection(1000);
  QVERIFY(!will.topic.isEmpty());

  const auto birth = node.birthMessages(1000);
  node.commitBirth();
  QCOMPARE(birth.size(), qsizetype(1));
  QVERIFY(node.dataMessages(1001).isEmpty());

  node.updateValue(11, 21.5, QString(), true);
  const auto data = node.dataMessages(1002);
  QCOMPARE(data.size(), qsizetype(1));
  QCOMPARE(data.constFirst().topic, QStringLiteral("spBv1.0/Plant1/NDATA/SS1"));

  const auto payload = decoded(data.constFirst());
  QCOMPARE(payload.metrics.size(), qsizetype(1));

  const auto& metric = payload.metrics.constFirst();
  QVERIFY(!metric.hasName);
  QVERIFY(metric.hasAlias);
  QVERIFY(!metric.isNull);
  QCOMPARE(metric.alias, quint64(1));
  QCOMPARE(metric.numericValue, 21.5);

  QVERIFY(node.dataMessages(1003).isEmpty());
  node.updateValue(11, 21.5, QString(), true);
  QVERIFY(node.dataMessages(1004).isEmpty());

  node.updateValue(22, 0.0, QStringLiteral("RUNNING"), false);
  const auto second = node.dataMessages(1005);
  QCOMPARE(second.size(), qsizetype(1));

  const auto text = decoded(second.constFirst());
  QCOMPARE(text.metrics.size(), qsizetype(1));
  QCOMPARE(text.metrics.constFirst().alias, quint64(2));
  QCOMPARE(text.metrics.constFirst().stringValue, QStringLiteral("RUNNING"));
}

id TstSparkplugPublisher::dataWaitsForTheBirth()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  node.registerMetric(0, 11, QStringLiteral("Temperature"), code(DataType::Double), 1);

  const auto will = node.beginConnection(1000);
  QVERIFY(!will.topic.isEmpty());

  node.updateValue(11, 4.25, QString(), true);
  QVERIFY(node.dataMessages(1001).isEmpty());

  const auto birth = node.birthMessages(1002);
  node.commitBirth();
  const auto payload = decoded(birth.constFirst());
  const auto metric  = metricNamed(payload, "Temperature");
  QVERIFY(!metric.isNull);
  QCOMPARE(metric.numericValue, 4.25);
  QVERIFY(node.dataMessages(1003).isEmpty());
}

id TstSparkplugPublisher::deviceMetricsRideTheDeviceTopics()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig(QString::fromUtf8(kDevice)));
  node.registerMetric(0, 11, QStringLiteral("Temperature"), code(DataType::Double), 1);

  const auto will = node.beginConnection(1000);
  QCOMPARE(will.topic, QStringLiteral("spBv1.0/Plant1/NDEATH/SS1"));

  const auto birth = node.birthMessages(1000);
  node.commitBirth();
  QCOMPARE(birth.size(), qsizetype(2));
  QCOMPARE(birth.constFirst().topic, QStringLiteral("spBv1.0/Plant1/NBIRTH/SS1"));
  QCOMPARE(birth.constLast().topic, QStringLiteral("spBv1.0/Plant1/DBIRTH/SS1/Line3"));

  const auto nodePayload = decoded(birth.constFirst());
  QCOMPARE(nodePayload.metrics.size(), qsizetype(2));
  QVERIFY(!metricNamed(nodePayload, "Temperature").hasName);

  const auto devicePayload = decoded(birth.constLast());
  QCOMPARE(devicePayload.metrics.size(), qsizetype(1));
  QCOMPARE(metricNamed(devicePayload, "Temperature").alias, quint64(1));

  node.updateValue(11, 7.5, QString(), true);
  const auto data = node.dataMessages(1001);
  QCOMPARE(data.size(), qsizetype(1));
  QCOMPARE(data.constFirst().topic, QStringLiteral("spBv1.0/Plant1/DDATA/SS1/Line3"));
}

id TstSparkplugPublisher::sequenceWrapsAcrossBirthsAndData()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  node.registerMetric(0, 11, QStringLiteral("Counter"), code(DataType::Double), 1);

  const auto will = node.beginConnection(1000);
  QVERIFY(!will.topic.isEmpty());

  const auto birth = node.birthMessages(1000);
  node.commitBirth();
  QCOMPARE(decoded(birth.constFirst()).seq, quint64(0));

  for (int i = 0; i < 300; ++i) {
    node.updateValue(11, static_cast<double>(i) + 1.0, QString(), true);
    const auto data = node.dataMessages(static_cast<quint64>(1001 + i));
    QCOMPARE(data.size(), qsizetype(1));
    QCOMPARE(decoded(data.constFirst()).seq, quint64((i + 1) % 256));
  }

  QCOMPARE(node.seq(), quint64(301 % 256));
}

id TstSparkplugPublisher::birthDeathSequenceMatchesTheWill()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  node.registerMetric(0, 11, QStringLiteral("Temperature"), code(DataType::Double), 1);

  const auto firstWill  = node.beginConnection(1000);
  const auto firstBirth = node.birthMessages(1001);
  QCOMPARE(node.bdSeq(), quint64(0));
  QCOMPARE(birthDeathSequence(firstWill), 0.0);
  QCOMPARE(birthDeathSequence(firstBirth.constFirst()), 0.0);

  const auto secondWill  = node.beginConnection(2000);
  const auto secondBirth = node.birthMessages(2001);
  QCOMPARE(node.bdSeq(), quint64(1));
  QCOMPARE(birthDeathSequence(secondWill), 1.0);
  QCOMPARE(birthDeathSequence(secondBirth.constFirst()), 1.0);
  QCOMPARE(decoded(secondBirth.constFirst()).seq, quint64(0));
  QVERIFY(!decoded(secondWill).hasSeq);
}

id TstSparkplugPublisher::rebirthCommandReissuesTheBirth()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  node.registerMetric(0, 11, QStringLiteral("Temperature"), code(DataType::Double), 1);

  const auto will = node.beginConnection(1000);
  QVERIFY(!will.topic.isEmpty());

  const auto birth = node.birthMessages(1000);
  node.commitBirth();
  QCOMPARE(birth.size(), qsizetype(1));
  QCOMPARE(node.counters().births, quint64(1));

  QVERIFY(node.isRebirthCommand(encodeRebirthRequest(1500)));
  QCOMPARE(node.counters().rebirthCommands, quint64(1));

  const auto rebirth = node.birthMessages(1501);
  node.commitBirth();
  QCOMPARE(rebirth.size(), qsizetype(1));
  QCOMPARE(node.counters().births, quint64(2));

  const auto payload = decoded(rebirth.constFirst());
  QCOMPARE(payload.metrics.size(), qsizetype(3));
  QCOMPARE(metricNamed(payload, "Temperature").alias, quint64(1));
  QCOMPARE(payload.seq, quint64(1));

  QVERIFY(!node.isRebirthCommand(QByteArray("\x08\x01", 2)));
  QCOMPARE(node.counters().ignoredCommands, quint64(1));
  QVERIFY(!node.isRebirthCommand(QByteArray("\xFF\xFF", 2)));
  QCOMPARE(node.counters().commandDecodeErrors, quint64(1));
}

id TstSparkplugPublisher::unrepresentableValuesAreSkippedAndCounted()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  node.registerMetric(0, 11, QStringLiteral("Small"), code(DataType::Int8), 1);
  node.registerMetric(0, 22, QStringLiteral("Temperature"), code(DataType::Double), 1);

  const auto will = node.beginConnection(1000);
  QVERIFY(!will.topic.isEmpty());

  const auto birth = node.birthMessages(1000);
  node.commitBirth();
  QCOMPARE(birth.size(), qsizetype(1));

  node.updateValue(11, 5000.0, QString(), true);
  QCOMPARE(node.counters().skippedValues, quint64(1));
  QVERIFY(node.dataMessages(1001).isEmpty());

  node.updateValue(11, 3.5, QString(), true);
  QCOMPARE(node.counters().skippedValues, quint64(2));
  QVERIFY(node.dataMessages(1002).isEmpty());

  node.updateValue(22, 0.0, QStringLiteral("not a number"), false);
  QCOMPARE(node.counters().skippedValues, quint64(3));
  QVERIFY(node.dataMessages(1003).isEmpty());

  node.updateValue(11, -12.0, QString(), true);
  const auto data = node.dataMessages(1004);
  QCOMPARE(data.size(), qsizetype(1));

  const auto payload = decoded(data.constFirst());
  QCOMPARE(payload.metrics.size(), qsizetype(1));
  QCOMPARE(payload.metrics.constFirst().numericValue, -12.0);
  QCOMPARE(node.counters().skippedValues, quint64(3));
}

id TstSparkplugPublisher::newMetricsAfterBirthRequestARebirth()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  node.registerMetric(0, 11, QStringLiteral("Temperature"), code(DataType::Double), 1);

  const auto will = node.beginConnection(1000);
  QVERIFY(!will.topic.isEmpty());

  const auto birth = node.birthMessages(1000);
  node.commitBirth();
  QCOMPARE(birth.size(), qsizetype(1));
  QVERIFY(!node.needsRebirth());

  node.registerMetric(0, 22, QStringLiteral("Pressure"), code(DataType::Double), 1);
  QVERIFY(node.needsRebirth());
  QCOMPARE(node.metricCount(), 2);

  const auto rebirth = node.birthMessages(1001);
  node.commitBirth();
  QVERIFY(!node.needsRebirth());
  QCOMPARE(metricNamed(decoded(rebirth.constFirst()), "Pressure").alias, quint64(2));
  QCOMPARE(metricNamed(decoded(rebirth.constFirst()), "Temperature").alias, quint64(1));
}

id TstSparkplugPublisher::twoSourcesGetDistinctStableAliases()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  node.registerMetric(kSourceA, 11, QStringLiteral("Temp"), code(DataType::Double), 1);
  node.registerMetric(kSourceA, 12, QStringLiteral("Humidity"), code(DataType::Double), 1);
  node.registerMetric(kSourceB, 21, QStringLiteral("Pressure"), code(DataType::Double), 1);
  QCOMPARE(node.metricCount(), 3);

  node.beginConnection(1000);
  const auto birth = decoded(node.birthMessages(1000).constFirst());
  node.commitBirth();
  QCOMPARE(metricNamed(birth, "Temp").alias, quint64(1));
  QCOMPARE(metricNamed(birth, "Humidity").alias, quint64(2));
  QCOMPARE(metricNamed(birth, "Pressure").alias, quint64(3));

  node.updateValue(11, 20.0, QString(), true);
  node.updateValue(21, 101.3, QString(), true);
  const auto data = decoded(node.dataMessages(1001).constFirst());
  QCOMPARE(data.metrics.size(), qsizetype(2));
  QVERIFY(hasAlias(data, 1));
  QVERIFY(hasAlias(data, 3));

  node.clearSource(kSourceA);
  node.registerMetric(kSourceA, 11, QStringLiteral("Temp"), code(DataType::Double), 2);
  QCOMPARE(node.metricCount(), 2);

  const auto rebirth = decoded(node.birthMessages(1002).constFirst());
  node.commitBirth();
  QCOMPARE(metricNamed(rebirth, "Temp").alias, quint64(1));
  QCOMPARE(metricNamed(rebirth, "Pressure").alias, quint64(3));
  QVERIFY(!metricNamed(rebirth, "Humidity").hasName);

  node.registerMetric(kSourceB, 22, QStringLiteral("Flow"), code(DataType::Double), 2);
  const auto grown = decoded(node.birthMessages(1003).constFirst());
  QCOMPARE(metricNamed(grown, "Flow").alias, quint64(4));
}

id TstSparkplugPublisher::restructuringOneSourceKeepsTheOther()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  node.registerMetric(kSourceA, 11, QStringLiteral("Temp"), code(DataType::Double), 1);
  node.registerMetric(kSourceB, 21, QStringLiteral("Pressure"), code(DataType::Double), 1);

  node.beginConnection(1000);
  node.birthMessages(1000);
  node.commitBirth();
  QVERIFY(!node.needsRebirth());

  node.clearSource(kSourceB);
  node.registerMetric(kSourceB, 21, QStringLiteral("Pressure"), code(DataType::Double), 2);
  node.registerMetric(kSourceB, 22, QStringLiteral("Flow"), code(DataType::Double), 2);
  QVERIFY(node.needsRebirth());

  const auto rebirth = decoded(node.birthMessages(1001).constFirst());
  node.commitBirth();
  QCOMPARE(metricNamed(rebirth, "Temp").alias, quint64(1));
  QCOMPARE(metricNamed(rebirth, "Pressure").alias, quint64(2));
  QCOMPARE(metricNamed(rebirth, "Flow").alias, quint64(3));
  QVERIFY(!node.needsRebirth());
}

id TstSparkplugPublisher::singleSourceMatchesTheLegacyWire()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  node.registerMetric(0, 11, QStringLiteral("Sensors/Temperature"), code(DataType::Double), 1);
  node.registerMetric(0, 22, QStringLiteral("Sensors/State"), code(DataType::String), 1);
  node.registerMetric(0, 33, QStringLiteral("Sensors/Valve"), code(DataType::Boolean), 1);

  node.beginConnection(1000);
  const auto birth = decoded(node.birthMessages(1700000000000ULL).constFirst());
  node.commitBirth();

  const auto temperature = metricNamed(birth, "Sensors/Temperature");
  QVERIFY(temperature.hasName);
  QCOMPARE(temperature.name, QStringLiteral("Sensors/Temperature"));
  QCOMPARE(temperature.alias, quint64(1));
  QCOMPARE(metricNamed(birth, "Sensors/State").alias, quint64(2));
  QCOMPARE(metricNamed(birth, "Sensors/Valve").alias, quint64(3));

  node.updateValue(11, 21.5, QString(), true);
  const auto data = decoded(node.dataMessages(1701).constFirst());
  QCOMPARE(data.metrics.size(), qsizetype(1));
  QVERIFY(!data.metrics.constFirst().hasName);
  QCOMPARE(data.metrics.constFirst().alias, quint64(1));
  QCOMPARE(data.metrics.constFirst().numericValue, 21.5);
}

id TstSparkplugPublisher::aSwapDropsTheDepartedSource()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());

  node.setLiveGeneration(1);
  node.dropStaleMetrics();
  node.clearSource(kSourceA);
  node.registerMetric(kSourceA, 11, QStringLiteral("Temp"), code(DataType::Double), 1);
  node.registerMetric(kSourceA, 12, QStringLiteral("Humidity"), code(DataType::Double), 1);
  QCOMPARE(node.metricCount(), 2);

  node.beginConnection(1000);
  node.birthMessages(1000);
  node.commitBirth();

  node.setLiveGeneration(2);
  node.dropStaleMetrics();
  node.clearSource(kSourceB);
  node.registerMetric(kSourceB, 21, QStringLiteral("Pressure"), code(DataType::Double), 2);
  QCOMPARE(node.metricCount(), 1);

  const auto rebirth = decoded(node.birthMessages(1001).constFirst());
  node.commitBirth();
  QCOMPARE(metricNamed(rebirth, "Pressure").alias, quint64(3));
  QVERIFY(!metricNamed(rebirth, "Temp").hasName);
  QVERIFY(!metricNamed(rebirth, "Humidity").hasName);
}

id TstSparkplugPublisher::theRegistryCapDropsAndCounts()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());

  const int cap  = MQTT::SparkplugPublisherLimits::kMaxMetrics;
  const int half = cap / 2;
  for (int i = 0; i < half; ++i)
    node.registerMetric(kSourceA, i, QStringLiteral("A%1").arg(i), code(DataType::Double), 1);
  for (int i = half; i < cap; ++i)
    node.registerMetric(kSourceB, i, QStringLiteral("B%1").arg(i), code(DataType::Double), 1);

  QCOMPARE(node.metricCount(), cap);
  QCOMPARE(node.counters().registryDrops, quint64(0));

  node.registerMetric(kSourceB, cap + 1, QStringLiteral("Overflow"), code(DataType::Double), 1);
  QCOMPARE(node.metricCount(), cap);
  QCOMPARE(node.counters().registryDrops, quint64(1));
}

id TstSparkplugPublisher::oneDeviceCarriesEverySource()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig(QString::fromUtf8(kDevice)));
  node.registerMetric(kSourceA, 11, QStringLiteral("Temp"), code(DataType::Double), 1);
  node.registerMetric(kSourceB, 21, QStringLiteral("Pressure"), code(DataType::Double), 1);

  node.beginConnection(1000);
  const auto birth = node.birthMessages(1000);
  node.commitBirth();
  QCOMPARE(birth.size(), qsizetype(2));
  QCOMPARE(birth.constLast().topic, QStringLiteral("spBv1.0/Plant1/DBIRTH/SS1/Line3"));

  const auto device = decoded(birth.constLast());
  QCOMPARE(device.metrics.size(), qsizetype(2));
  QCOMPARE(metricNamed(device, "Temp").alias, quint64(1));
  QCOMPARE(metricNamed(device, "Pressure").alias, quint64(2));
}

id TstSparkplugPublisher::collidingTitlesAreSourceQualified()
{
  SparkplugPublisher node;
  node.setConfig(nodeConfig());
  node.registerMetric(kSourceA, 11, QStringLiteral("Temperature"), code(DataType::Double), 1);
  node.registerMetric(kSourceA, 12, QStringLiteral("Speed"), code(DataType::Double), 1);
  node.registerMetric(kSourceB, 21, QStringLiteral("Temperature"), code(DataType::Double), 1);
  node.registerMetric(kSourceB, 22, QStringLiteral("Pressure"), code(DataType::Double), 1);

  node.beginConnection(1000);
  const auto birth = decoded(node.birthMessages(1000).constFirst());
  node.commitBirth();

  QVERIFY(metricNamed(birth, "source1/Temperature").hasName);
  QVERIFY(metricNamed(birth, "source2/Temperature").hasName);
  QVERIFY(metricNamed(birth, "Speed").hasName);
  QVERIFY(metricNamed(birth, "Pressure").hasName);
  QVERIFY(!metricNamed(birth, "Temperature").hasName);
}

atic void appendVarint(QByteArray& out, quint64 value)
{
  quint64 remaining = value;
  for (int i = 0; i < Sparkplug::kMaxVarintBytes; ++i) {
    const auto byte   = static_cast<quint8>(remaining & 0x7Fu);
    remaining       >>= 7;
    if (remaining == 0) {
      out.append(static_cast<char>(byte));
      return;
    }

    out.append(static_cast<char>(byte | 0x80u));
  }
}

atic void appendLenDelim(QByteArray& out, quint32 field, QByteArrayView block)
{
  appendTag(out, field, Sparkplug::kWireLengthDelimited);
  appendVarint(out, static_cast<quint64>(block.size()));
  if (!block.isEmpty())
    out.append(block.data(), block.size());
}

atic void appendVarintField(QByteArray& out, quint32 field, quint64 value)
{
  appendTag(out, field, Sparkplug::kWireVarint);
  appendVarint(out, value);
}

nodiscard]] static QByteArray realValue(double value)
{
  QByteArray out;
  appendTag(out, Sparkplug::kMetricDoubleValue, Sparkplug::kWireFixed64);
  const auto bits = std::bit_cast<quint64>(value);
  for (int i = 0; i < 8; ++i)
    out.append(static_cast<char>((bits >> (8 * i)) & 0xFFu));

  return out;
}

nodiscard]] static QByteArray flagValue(bool value)
{
  QByteArray out;
  appendVarintField(out, Sparkplug::kMetricBooleanValue, value ? 1 : 0);
  return out;
}

nodiscard]] static QByteArray longValue(quint64 value)
{
  QByteArray out;
  appendVarintField(out, Sparkplug::kMetricLongValue, value);
  return out;
}

nodiscard]] static QByteArray textValue(const QByteArray& text)
{
  QByteArray out;
  appendLenDelim(out, Sparkplug::kMetricStringValue, text);
  return out;
}

nodiscard]] static QByteArray makeMetric(const QByteArray& name,
                                           qint64 alias,
                                           quint32 datatype,
                                           const QByteArray& value)
{
  QByteArray out;
  if (!name.isEmpty())
    appendLenDelim(out, Sparkplug::kMetricName, name);

  if (alias >= 0)
    appendVarintField(out, Sparkplug::kMetricAlias, static_cast<quint64>(alias));

  appendVarintField(out, Sparkplug::kMetricDatatype, datatype);
  out.append(value);
  return out;
}

nodiscard]] static QByteArray makePayload(qint64 seq,
                                            quint64 timestampMs,
                                            const QList<QByteArray>& metrics)
{
  QByteArray out;
  appendVarintField(out, Sparkplug::kPayloadTimestamp, timestampMs);
  if (seq >= 0)
    appendVarintField(out, Sparkplug::kPayloadSeq, static_cast<quint64>(seq));

  for (const auto& metric : metrics)
    appendLenDelim(out, Sparkplug::kPayloadMetrics, metric);

  return out;
}

nodiscard]] static QString topicOf(const char* group, const char* verb, const char* node)
{
  return QStringLiteral("%1/%2/%3/%4")
    .arg(QString::fromLatin1(Limits::kNamespace),
         QString::fromLatin1(group),
         QString::fromLatin1(verb),
         QString::fromLatin1(node));
}

nodiscard]] static QString deviceTopic(const char* group,
                                         const char* verb,
                                         const char* node,
                                         const char* device)
{
  return topicOf(group, verb, node) + QLatin1Char('/') + QString::fromLatin1(device);
}

nodiscard]] static SparkplugSession::SlotValue slotNamed(const SparkplugSession& session,
                                                           const char* label)
{
  const QString wanted = QString::fromLatin1(label);
  for (const auto& slot : session.slotValues())
    if (slot.displayName == wanted)
      return slot;

  return SparkplugSession::SlotValue();
}

nodiscard]] static QStringList drainDirty(SparkplugSession& session)
{
  QStringList labels;
  session.consumeDirtySlots(
    [&labels](const SparkplugSession::SlotValue& slot) { labels.append(slot.displayName); });

  return labels;
}

id TstSparkplugSession::birthThenDataByAlias()
{
  SparkplugSession session;
  const QByteArray birth =
    makePayload(0,
                1000,
                {makeMetric("temperature", 1, code(DataType::Double), realValue(20.0)),
                 makeMetric("state", 2, code(DataType::String), textValue("IDLE"))});

  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge1"), birth));
  QCOMPARE(session.slotCount(), 3);
  QVERIFY(session.hasDirtySlots());
  QCOMPARE(drainDirty(session).size(), 3);
  QVERIFY(!session.hasDirtySlots());
  QCOMPARE(slotNamed(session, "edge1/Online").num, 1.0);
  QVERIFY(slotNamed(session, "edge1/Online").b);

  const QByteArray data =
    makePayload(1,
                2000,
                {makeMetric(QByteArray(), 1, code(DataType::Double), realValue(21.5)),
                 makeMetric(QByteArray(), 2, code(DataType::String), textValue("RUN"))});

  QVERIFY(session.ingest(topicOf("g1", "NDATA", "edge1"), data));
  QVERIFY(session.hasDirtySlots());
  QCOMPARE(slotNamed(session, "edge1/temperature").num, 21.5);
  QCOMPARE(slotNamed(session, "edge1/temperature").timestampMs, quint64(2000));
  QCOMPARE(slotNamed(session, "edge1/state").str, QStringLiteral("RUN"));
  QCOMPARE(drainDirty(session).size(), 2);
  QVERIFY(!session.hasDirtySlots());
  QCOMPARE(session.slotCount(), 3);
  QCOMPARE(session.counters().seqGaps, quint64(0));
  QCOMPARE(session.counters().unsupportedMetrics, quint64(0));
}

id TstSparkplugSession::dataBeforeBirthIsBuffered()
{
  SparkplugSession session;
  const QByteArray early =
    makePayload(0, 2000, {makeMetric(QByteArray(), 3, code(DataType::Double), realValue(7.5))});

  QVERIFY(session.ingest(deviceTopic("g1", "DDATA", "edge1", "dev1"), early));
  QCOMPARE(session.counters().preBirthBuffered, quint64(1));
  QCOMPARE(session.counters().rebirthRequests, quint64(1));
  QCOMPARE(session.slotCount(), 0);
  QVERIFY(!session.hasDirtySlots());

  const QByteArray birth =
    makePayload(1, 3000, {makeMetric("flow", 3, code(DataType::Double), realValue(0.0))});

  QVERIFY(session.ingest(deviceTopic("g1", "DBIRTH", "edge1", "dev1"), birth));
  QCOMPARE(session.slotCount(), 2);
  QCOMPARE(slotNamed(session, "edge1/dev1/flow").num, 7.5);
  QCOMPARE(slotNamed(session, "edge1/dev1/flow").timestampMs, quint64(2000));
  QCOMPARE(session.counters().preBirthDropped, quint64(0));
  QCOMPARE(session.counters().preBirthBuffered, quint64(1));

  const QByteArray later =
    makePayload(2, 4000, {makeMetric(QByteArray(), 3, code(DataType::Double), realValue(9.0))});

  QVERIFY(session.ingest(deviceTopic("g1", "DDATA", "edge1", "dev1"), later));
  QCOMPARE(slotNamed(session, "edge1/dev1/flow").num, 9.0);
  QCOMPARE(session.counters().preBirthBuffered, quint64(1));
  QCOMPARE(session.counters().seqGaps, quint64(0));
}

id TstSparkplugSession::preBirthBufferOverflow()
{
  SparkplugSession session;
  const int total = Limits::kMaxPreBirthMessages + 1;
  for (int i = 0; i < total; ++i) {
    const QByteArray data = makePayload(
      -1,
      static_cast<quint64>(1000 + i),
      {makeMetric(QByteArray(), i, code(DataType::Double), realValue(static_cast<double>(i)))});
    QVERIFY(session.ingest(topicOf("g1", "NDATA", "edge1"), data));
  }

  QCOMPARE(session.counters().preBirthBuffered, static_cast<quint64>(total));
  QCOMPARE(session.counters().preBirthDropped, quint64(1));
  QCOMPARE(session.counters().rebirthRequests, quint64(1));
  QCOMPARE(session.slotCount(), 0);

  QList<QByteArray> block;
  block.reserve(total);
  for (int i = 0; i < total; ++i)
    block.append(makeMetric(
      QByteArray("m") + QByteArray::number(i), i, code(DataType::Double), realValue(-1.0)));

  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge1"), makePayload(0, 5000, block)));
  QCOMPARE(session.slotCount(), total + 1);
  QCOMPARE(slotNamed(session, "edge1/m0").num, -1.0);
  QCOMPARE(slotNamed(session, "edge1/m1").num, 1.0);
  QCOMPARE(slotNamed(session, "edge1/m256").num, 256.0);
  QCOMPARE(session.counters().preBirthDropped, quint64(1));
}

id TstSparkplugSession::sequenceGapFlagsRebirth()
{
  SparkplugSession session;
  const QByteArray birth =
    makePayload(0, 1000, {makeMetric("rpm", 1, code(DataType::Double), realValue(0.0))});
  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge1"), birth));

  const QByteArray gapped =
    makePayload(2, 2000, {makeMetric(QByteArray(), 1, code(DataType::Double), realValue(120.0))});
  QVERIFY(session.ingest(topicOf("g1", "NDATA", "edge1"), gapped));
  QCOMPARE(session.counters().seqGaps, quint64(1));
  QCOMPARE(session.counters().rebirthRequests, quint64(1));
  QCOMPARE(slotNamed(session, "edge1/rpm").num, 120.0);

  const QVector<QString> queued = session.takeRebirthTopics();
  QCOMPARE(queued.size(), qsizetype(1));
  QCOMPARE(queued.constFirst(), topicOf("g1", "NCMD", "edge1"));
  QVERIFY(session.takeRebirthTopics().isEmpty());

  const QByteArray again =
    makePayload(5, 3000, {makeMetric(QByteArray(), 1, code(DataType::Double), realValue(130.0))});
  QVERIFY(session.ingest(topicOf("g1", "NDATA", "edge1"), again));
  QCOMPARE(session.counters().seqGaps, quint64(2));
  QCOMPARE(session.counters().rebirthRequests, quint64(1));
  QVERIFY(session.takeRebirthTopics().isEmpty());
  QCOMPARE(slotNamed(session, "edge1/rpm").num, 130.0);

  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge1"), makePayload(0, 4000, {})));
  const QByteArray reborn =
    makePayload(4, 5000, {makeMetric("rpm", 1, code(DataType::Double), realValue(140.0))});
  QVERIFY(session.ingest(topicOf("g1", "NDATA", "edge1"), reborn));
  QCOMPARE(session.counters().rebirthRequests, quint64(2));
  QCOMPARE(session.takeRebirthTopics().size(), qsizetype(1));
}

id TstSparkplugSession::deathCertificates()
{
  SparkplugSession session;
  const QByteArray birth =
    makePayload(0, 1000, {makeMetric("t", 1, code(DataType::Double), realValue(5.0))});
  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge1"), birth));
  QCOMPARE(drainDirty(session).size(), 2);

  QVERIFY(session.ingest(topicOf("g1", "NDEATH", "edge1"), makePayload(-1, 4000, {})));
  QCOMPARE(slotNamed(session, "edge1/Online").num, 0.0);
  QVERIFY(!slotNamed(session, "edge1/Online").b);
  QCOMPARE(drainDirty(session), QStringList{QStringLiteral("edge1/Online")});

  const QByteArray orphan =
    makePayload(-1, 5000, {makeMetric(QByteArray(), 1, code(DataType::Double), realValue(9.0))});
  QVERIFY(session.ingest(topicOf("g1", "NDATA", "edge1"), orphan));
  QCOMPARE(session.counters().preBirthBuffered, quint64(1));
  QCOMPARE(session.counters().rebirthRequests, quint64(1));
  QCOMPARE(slotNamed(session, "edge1/t").num, 5.0);

  SparkplugSession devices;
  QVERIFY(devices.ingest(topicOf("g1", "NBIRTH", "edge2"), makePayload(0, 1000, {})));
  const QByteArray deviceBirth =
    makePayload(1, 1100, {makeMetric("p", 7, code(DataType::Double), realValue(3.0))});
  QVERIFY(devices.ingest(deviceTopic("g1", "DBIRTH", "edge2", "dev1"), deviceBirth));
  QCOMPARE(drainDirty(devices).size(), 2);

  QVERIFY(devices.ingest(deviceTopic("g1", "DDEATH", "edge2", "dev1"), makePayload(-1, 1200, {})));
  QVERIFY(!devices.hasDirtySlots());
  QCOMPARE(slotNamed(devices, "edge2/Online").num, 1.0);
  QVERIFY(slotNamed(devices, "edge2/Online").b);

  const QByteArray stale =
    makePayload(-1, 1300, {makeMetric(QByteArray(), 7, code(DataType::Double), realValue(8.0))});
  QVERIFY(devices.ingest(deviceTopic("g1", "DDATA", "edge2", "dev1"), stale));
  QCOMPARE(devices.counters().preBirthBuffered, quint64(1));
  QCOMPARE(slotNamed(devices, "edge2/dev1/p").num, 3.0);
}

id TstSparkplugSession::unsupportedDataTypeKeepsValue()
{
  SparkplugSession session;
  const QByteArray birth =
    makePayload(0, 1000, {makeMetric("t", 1, code(DataType::Double), realValue(5.0))});
  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge1"), birth));
  QCOMPARE(drainDirty(session).size(), 2);

  const QByteArray odd =
    makePayload(1,
                2000,
                {makeMetric(QByteArray(), 1, code(DataType::DateTime), longValue(1700000000000ULL)),
                 makeMetric(QByteArray(), -1, code(DataType::Double), realValue(3.0))});

  QVERIFY(session.ingest(topicOf("g1", "NDATA", "edge1"), odd));
  QCOMPARE(session.counters().unsupportedMetrics, quint64(2));
  QCOMPARE(slotNamed(session, "edge1/t").num, 5.0);
  QCOMPARE(slotNamed(session, "edge1/t").timestampMs, quint64(1000));
  QVERIFY(!session.hasDirtySlots());
  QCOMPARE(session.slotCount(), 2);
}

id TstSparkplugSession::aliasCollisionAcrossNodes()
{
  SparkplugSession session;
  const QByteArray birthA =
    makePayload(0, 1000, {makeMetric("a", 1, code(DataType::Double), realValue(1.0))});
  const QByteArray birthB =
    makePayload(0, 1000, {makeMetric("b", 1, code(DataType::Double), realValue(2.0))});

  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edgeA"), birthA));
  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edgeB"), birthB));
  QCOMPARE(session.slotCount(), 4);

  const QByteArray dataA =
    makePayload(1, 2000, {makeMetric(QByteArray(), 1, code(DataType::Double), realValue(10.0))});
  const QByteArray dataB =
    makePayload(1, 2000, {makeMetric(QByteArray(), 1, code(DataType::Double), realValue(20.0))});

  QVERIFY(session.ingest(topicOf("g1", "NDATA", "edgeA"), dataA));
  QVERIFY(session.ingest(topicOf("g1", "NDATA", "edgeB"), dataB));
  QCOMPARE(slotNamed(session, "edgeA/a").num, 10.0);
  QCOMPARE(slotNamed(session, "edgeB/b").num, 20.0);
  QCOMPARE(session.slotCount(), 4);
  QCOMPARE(session.counters().preBirthBuffered, quint64(0));
}

id TstSparkplugSession::groupsScopeNodeIdentity()
{
  SparkplugSession session;
  const QByteArray birthA =
    makePayload(0, 1000, {makeMetric("a", 1, code(DataType::Double), realValue(1.0))});
  const QByteArray birthB =
    makePayload(0, 1000, {makeMetric("b", 1, code(DataType::Double), realValue(2.0))});

  QVERIFY(session.ingest(topicOf("gA", "NBIRTH", "edge1"), birthA));
  QVERIFY(session.ingest(topicOf("gB", "NBIRTH", "edge1"), birthB));
  QCOMPARE(session.slotCount(), 4);

  const QByteArray dataA =
    makePayload(1, 2000, {makeMetric(QByteArray(), 1, code(DataType::Double), realValue(10.0))});
  const QByteArray dataB =
    makePayload(1, 2000, {makeMetric(QByteArray(), 1, code(DataType::Double), realValue(20.0))});

  QVERIFY(session.ingest(topicOf("gA", "NDATA", "edge1"), dataA));
  QVERIFY(session.ingest(topicOf("gB", "NDATA", "edge1"), dataB));
  QCOMPARE(slotNamed(session, "edge1/a").num, 10.0);
  QCOMPARE(slotNamed(session, "edge1/b").num, 20.0);
  QCOMPARE(slotNamed(session, "edge1/a").group, QStringLiteral("gA"));
  QCOMPARE(slotNamed(session, "edge1/b").group, QStringLiteral("gB"));
  QCOMPARE(session.slotCount(), 4);
  QCOMPARE(session.counters().seqGaps, quint64(0));
  QCOMPARE(session.counters().preBirthBuffered, quint64(0));

  QVERIFY(session.ingest(topicOf("gA", "NDEATH", "edge1"), makePayload(-1, 3000, {})));
  QCOMPARE(session.slotValues().at(0).num, 0.0);
  QCOMPARE(session.slotValues().at(2).num, 1.0);
}

id TstSparkplugSession::topicRouting()
{
  SparkplugSession session;
  session.setGroupFilter(QStringLiteral("plant1"));
  QCOMPARE(session.groupFilter(), QStringLiteral("plant1"));

  const QByteArray birth =
    makePayload(0, 1000, {makeMetric("t", 1, code(DataType::Double), realValue(1.0))});

  QVERIFY(!session.ingest(topicOf("plant2", "NBIRTH", "edge1"), birth));
  QVERIFY(!session.ingest(QStringLiteral("acme/plant1/NBIRTH/edge1"), birth));
  QVERIFY(!session.ingest(QStringLiteral("spBv1.0/plant1"), birth));
  QVERIFY(!session.ingest(QStringLiteral("spBv1.0/plant1/NBIRTH/edge1/dev1/extra"), birth));
  QVERIFY(!session.ingest(QStringLiteral("spBv1.0/plant1/DBIRTH/edge1/"), birth));
  QVERIFY(!session.ingest(QStringLiteral("spBv1.0/plant1/DDATA/edge1/"), birth));
  QCOMPARE(session.slotCount(), 0);
  QCOMPARE(session.counters().ignoredMessages, quint64(0));

  QVERIFY(session.ingest(topicOf("plant1", "NBIRTH", "edge1"), birth));
  QCOMPARE(session.slotCount(), 2);

  QVERIFY(session.ingest(topicOf("plant1", "NCMD", "edge1"), QByteArray()));
  QVERIFY(session.ingest(QStringLiteral("spBv1.0/STATE/host1"), QByteArray()));
  QCOMPARE(session.counters().ignoredMessages, quint64(2));
  QCOMPARE(session.slotCount(), 2);
}

id TstSparkplugSession::identityCapsRefuseGrowth()
{
  const QByteArray huge(Sparkplug::kMaxIdentityBytes + 1, 'x');

  SparkplugSession session;
  const QByteArray named =
    makePayload(0, 1000, {makeMetric(huge, 1, code(DataType::Double), realValue(1.0))});
  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge1"), named));
  QCOMPARE(session.counters().decodeErrors, quint64(1));
  QCOMPARE(session.slotCount(), 0);

  const QByteArray birth =
    makePayload(0, 1000, {makeMetric("t", 1, code(DataType::String), textValue("ok"))});
  QVERIFY(!session.ingest(topicOf("g1", "NBIRTH", huge.constData()), birth));
  QVERIFY(!session.ingest(deviceTopic("g1", "DBIRTH", "edge1", huge.constData()), birth));
  QVERIFY(!session.ingest(topicOf(huge.constData(), "NBIRTH", "edge1"), birth));
  QCOMPARE(session.slotCount(), 0);

  const QByteArray wide(Wire::kMaxStringBytes * 4, 'y');
  const QByteArray big =
    makePayload(0, 1000, {makeMetric("t", 1, code(DataType::String), textValue(wide))});
  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge1"), big));
  QCOMPARE(session.slotCount(), 2);
  QCOMPARE(slotNamed(session, "edge1/t").str.size(), qsizetype(Wire::kMaxStringBytes));
}

id TstSparkplugSession::malformedPayloadCounted()
{
  SparkplugSession session;
  const QByteArray birth =
    makePayload(0, 1000, {makeMetric("t", 1, code(DataType::Double), realValue(4.5))});
  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge1"), birth));
  QCOMPARE(drainDirty(session).size(), 2);

  QByteArray truncated;
  truncated.append("\xFF\xFF\xFF", 3);
  QVERIFY(session.ingest(topicOf("g1", "NDATA", "edge1"), truncated));
  QCOMPARE(session.counters().decodeErrors, quint64(1));
  QVERIFY(!session.hasDirtySlots());
  QCOMPARE(session.slotCount(), 2);
  QCOMPARE(slotNamed(session, "edge1/t").num, 4.5);

  const QByteArray runOn(Sparkplug::kMaxVarintBytes + 1, static_cast<char>(0xFF));
  QVERIFY(session.ingest(topicOf("g1", "NDATA", "edge1"), runOn));
  QCOMPARE(session.counters().decodeErrors, quint64(2));
  QCOMPARE(session.counters().preBirthBuffered, quint64(0));
  QCOMPARE(session.slotCount(), 2);
}

id TstSparkplugSession::slotCapRefusesGrowth()
{
  SparkplugSession session;
  const int nodes   = 8;
  const int metrics = (Limits::kMaxSlots / nodes) - 1;

  QList<QByteArray> block;
  block.reserve(metrics);
  for (int i = 0; i < metrics; ++i)
    block.append(makeMetric(QByteArray("m") + QByteArray::number(i),
                            i,
                            code(DataType::Double),
                            realValue(static_cast<double>(i))));

  const QByteArray birth = makePayload(0, 1000, block);
  for (int n = 0; n < nodes; ++n) {
    const QByteArray node = QByteArray("n") + QByteArray::number(n);
    QVERIFY(session.ingest(topicOf("g1", "NBIRTH", node.constData()), birth));
  }

  QCOMPARE(session.slotCount(), Limits::kMaxSlots);
  QCOMPARE(session.counters().capDrops, quint64(0));

  const QByteArray extra =
    makePayload(1, 2000, {makeMetric("extra", -1, code(DataType::Double), realValue(1.0))});
  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "n0"), extra));
  QCOMPARE(session.slotCount(), Limits::kMaxSlots);
  QCOMPARE(session.counters().capDrops, quint64(1));
}

id TstSparkplugSession::schemaGenerationLifecycle()
{
  SparkplugSession session;
  const QByteArray birth =
    makePayload(0,
                1000,
                {makeMetric("a", 1, code(DataType::Double), realValue(1.0)),
                 makeMetric("b", 2, code(DataType::Boolean), flagValue(true))});

  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge1"), birth));
  QCOMPARE(session.newMetricsSinceGeneration(), quint64(3));

  const QVector<SparkplugSession::SlotValue> schema = session.slotValues();
  QCOMPARE(schema.size(), qsizetype(3));
  QCOMPARE(schema.at(0).index, 0);
  QCOMPARE(schema.at(0).name, QString::fromLatin1(Limits::kOnlineMetric));
  QCOMPARE(schema.at(0).node, QStringLiteral("edge1"));
  QVERIFY(schema.at(0).device.isEmpty());
  QCOMPARE(schema.at(1).name, QStringLiteral("a"));
  QCOMPARE(schema.at(2).name, QStringLiteral("b"));

  session.markGenerated();
  QCOMPARE(session.newMetricsSinceGeneration(), quint64(0));
  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge1"), birth));
  QCOMPARE(session.newMetricsSinceGeneration(), quint64(0));

  const QByteArray deviceBirth =
    makePayload(1, 2000, {makeMetric("p", 7, code(DataType::Double), realValue(3.0))});
  QVERIFY(session.ingest(deviceTopic("g1", "DBIRTH", "edge1", "dev1"), deviceBirth));
  QCOMPARE(session.newMetricsSinceGeneration(), quint64(1));

  const QVector<SparkplugSession::SlotValue> grown = session.slotValues();
  QCOMPARE(grown.size(), qsizetype(4));
  QCOMPARE(grown.at(3).index, 3);
  QCOMPARE(grown.at(3).device, QStringLiteral("dev1"));
  QCOMPARE(grown.at(3).name, QStringLiteral("p"));
}

id TstSparkplugSession::resetClearsSession()
{
  SparkplugSession session;
  const QByteArray birth =
    makePayload(0, 1000, {makeMetric("t", 1, code(DataType::Double), realValue(2.0))});
  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge1"), birth));

  const QByteArray orphan =
    makePayload(-1, 2000, {makeMetric(QByteArray(), 5, code(DataType::Double), realValue(99.0))});
  QVERIFY(session.ingest(topicOf("g1", "NDATA", "edge9"), orphan));
  QVERIFY(session.slotCount() > 0);
  QVERIFY(session.hasDirtySlots());
  QCOMPARE(session.counters().preBirthBuffered, quint64(1));

  session.reset();
  QCOMPARE(session.slotCount(), 0);
  QVERIFY(!session.hasDirtySlots());
  QVERIFY(session.slotValues().isEmpty());
  QVERIFY(session.takeRebirthTopics().isEmpty());
  QCOMPARE(session.newMetricsSinceGeneration(), quint64(0));
  QCOMPARE(session.counters().preBirthBuffered, quint64(0));
  QCOMPARE(session.counters().rebirthRequests, quint64(0));
  QCOMPARE(session.counters().seqGaps, quint64(0));

  const QByteArray revived =
    makePayload(0, 3000, {makeMetric("z", 5, code(DataType::Double), realValue(1.0))});
  QVERIFY(session.ingest(topicOf("g1", "NBIRTH", "edge9"), revived));
  QCOMPARE(session.slotCount(), 2);
  QCOMPARE(slotNamed(session, "edge9/z").num, 1.0);
}

EyeShader::EyeShader()
{
  setShaderFileName(VertexStage, QString::fromLatin1(Plot3DStereo::kVertexShader));
  setShaderFileName(FragmentStage, QString::fromLatin1(Plot3DStereo::kFragmentShader));
  setFlag(UpdatesGraphicsPipelineState, true);
}

bool EyeShader::updateUniformData(RenderState& state,
                                  QSGMaterial* newMaterial,
                                  QSGMaterial* oldMaterial)
{
  Q_UNUSED(newMaterial)
  Q_UNUSED(oldMaterial)

  QByteArray* buffer = state.uniformData();
  SS_ASSERT(buffer != nullptr, return false);
  SS_ASSERT(buffer->size() >= kUniformBytes, return false);

  bool changed = false;
  if (state.isMatrixDirty()) {
    const QMatrix4x4 matrix = state.combinedMatrix();
    std::memcpy(buffer->data(), matrix.constData(), kMatrixBytes);
    changed = true;
  }

  if (state.isOpacityDirty()) {
    const float opacity = state.opacity();
    std::memcpy(buffer->data() + kMatrixBytes, &opacity, sizeof(opacity));
    changed = true;
  }

  return changed;
}

bool EyeShader::updateGraphicsPipelineState(RenderState& state,
                                            GraphicsPipelineState* pipeline,
                                            QSGMaterial* newMaterial,
                                            QSGMaterial* oldMaterial)
{
  Q_UNUSED(state)
  Q_UNUSED(oldMaterial)

  SS_ASSERT(pipeline != nullptr, return false);
  SS_ASSERT(newMaterial != nullptr, return false);

  const auto* material = static_cast<const EyeMaterial*>(newMaterial);
  const auto channels  = Plot3DStereo::eyeChannels(material->mask());

  GraphicsPipelineState::ColorMask written = GraphicsPipelineState::A;
  if (channels.red)
    written |= GraphicsPipelineState::R;

  if (channels.green)
    written |= GraphicsPipelineState::G;

  if (channels.blue)
    written |= GraphicsPipelineState::B;

  pipeline->colorWrite = written;
  return true;
}

Widgets::EyeMaterial::EyeMaterial(const Plot3DStereo::EyeMask mask) : m_mask(mask)
{
  setFlag(QSGMaterial::Blending, true);
  setFlag(QSGMaterial::NoBatching, true);
}

QSGMaterialType* Widgets::EyeMaterial::type() const
{
  static QSGMaterialType monoType;
  static QSGMaterialType leftType;
  static QSGMaterialType rightType;

  if (m_mask == Plot3DStereo::EyeMask::Left)
    return &leftType;

  if (m_mask == Plot3DStereo::EyeMask::Right)
    return &rightType;

  return &monoType;
}

int Widgets::EyeMaterial::compare(const QSGMaterial* other) const
{
  SS_ASSERT(other != nullptr, return 1);
  SS_ASSERT(other->type() == type(), return 1);

  const auto* material = static_cast<const EyeMaterial*>(other);
  return static_cast<int>(m_mask) - static_cast<int>(material->mask());
}

QSGMaterialShader* Widgets::EyeMaterial::createShader(
  QSGRendererInterface::RenderMode renderMode) const
{
  Q_UNUSED(renderMode)
  return new Plot3DEyeDetail::EyeShader;
}

bool Widgets::EyeMaterialFactory::backendSupportsIsolation(QQuickWindow* window)
{
  SS_ASSERT(window != nullptr, return false);

  auto* renderer = window->rendererInterface();
  SS_ASSERT(renderer != nullptr, return false);

  switch (renderer->graphicsApi()) {
    case QSGRendererInterface::OpenGL:
    case QSGRendererInterface::Direct3D11:
    case QSGRendererInterface::Direct3D12:
    case QSGRendererInterface::Vulkan:
    case QSGRendererInterface::Metal:
      return true;
    default:
      return false;
  }
}

Widgets::EyeMaterialFactory::Factory Widgets::EyeMaterialFactory::forEye(
  const Plot3DStereo::EyeMask mask)
{
  if (mask == Plot3DStereo::EyeMask::Left)
    return &makeLeftEyeMaterial;

  if (mask == Plot3DStereo::EyeMask::Right)
    return &makeRightEyeMaterial;

  return nullptr;
}

void Widgets::Plot3D::syncTraceNode()
{
  for (int slot = 0; slot < Plot3DStereo::kEyeSlots; ++slot) {
    SS_ASSERT_LOG(m_tracePx[slot].size() == m_traceColors[slot].size());
    if (m_tracePx[slot].size() != m_traceColors[slot].size())
      continue;

    const auto* px      = m_tracePx[slot].data();
    const auto* colors  = m_traceColors[slot].data();
    const auto count    = static_cast<qsizetype>(m_tracePx[slot].size());
    const auto material = eyeFactory(slot);

    m_traceNodes[slot] =
      m_interpolate
        ? GpuStroke::buildStrokeNode(m_traceNodes[slot], px, colors, count, 1.0, material)
        : GpuStroke::buildPointNode(m_traceNodes[slot], px, colors, count, 1.0, material);
  }
}

static void releaseDetachedNode(QSGGeometryNode*& node)
{
  SS_ASSERT_LOG(!node || node->parent() == nullptr);
  if (node && node->parent())
    return;

  delete node;
  node = nullptr;
}

void Widgets::Plot3D::releaseStrokeNodes()
{
  for (int slot = 0; slot < Plot3DStereo::kEyeSlots; ++slot) {
    releaseDetachedNode(m_gridNodes[slot]);
    releaseDetachedNode(m_axisNodes[slot]);
    releaseDetachedNode(m_traceNodes[slot]);
  }
}

Widgets::GpuStroke::MaterialFactory Widgets::Plot3D::eyeFactory(const int slot) const
{
  SS_ASSERT(slot >= 0 && slot < Plot3DStereo::kEyeSlots, return nullptr);
  if (!m_anaglyph || !m_channelIsolation)
    return nullptr;

  return EyeMaterialFactory::forEye(slot == 0 ? EyeMask::Left : EyeMask::Right);
}

void Widgets::Plot3D::syncTileNode(QSGSimpleTextureNode*& slot,
                                   const QImage& tile,
                                   const QPointF& topLeft,
                                   bool& needsUpload)
{
  SS_ASSERT(window() != nullptr, return);

  if (tile.isNull()) {
    delete slot;
    slot        = nullptr;
    needsUpload = false;
    return;
  }

  if (!slot) {
    // code-verify off
    // Scene-graph nodes default to QSGNode::OwnedByParent, so appending transfers ownership to
    // the root and the slot is re-nulled whenever updatePaintNode is handed a null oldNode.
    slot = new QSGSimpleTextureNode;
    // code-verify on
    slot->setOwnsTexture(true);
    slot->setFiltering(QSGTexture::Linear);
    needsUpload = true;
  }

  if (needsUpload) {
    auto* texture = window()->createTextureFromImage(tile);
    SS_ASSERT_LOG(texture != nullptr);
    if (texture) {
      slot->setTexture(texture);
      needsUpload = false;
    }
  }

  const QSizeF size = tile.deviceIndependentSize();
  slot->setRect(QRectF(topLeft, size));
}

void Widgets::Plot3D::appendSceneNodes(QSGNode* root)
{
  SS_ASSERT(root != nullptr, return);

  const bool gridOnTop = m_cameraAngleX <= 270.0 && m_cameraAngleX > 90.0;
  const auto append    = [root](const EyeArray<QSGGeometryNode*>& nodes) {
    for (auto* node : nodes)
      if (node)
        root->appendChildNode(node);
  };

  if (gridOnTop)
    append(m_traceNodes);

  append(m_gridNodes);
  append(m_axisNodes);

  if (!gridOnTop)
    append(m_traceNodes);

  if (m_labelNode)
    root->appendChildNode(m_labelNode);

  if (m_indicatorNode)
    root->appendChildNode(m_indicatorNode);
}

void Widgets::Plot3D::syncBackgroundNode(QSGNode* root, const QRectF& rect)
{
  SS_ASSERT(root != nullptr, return);
  SS_ASSERT(window() != nullptr, return);

  if (!m_bgNode) {
    // code-verify off
    // Scene-graph nodes default to QSGNode::OwnedByParent, so appending below transfers
    // ownership to the root and the slot is re-nulled whenever updatePaintNode is handed a
    // null oldNode. There is no destructor release path to add.
    m_bgNode = new QSGSimpleTextureNode;
    // code-verify on
    m_bgNode->setOwnsTexture(true);
    m_bgNode->setFiltering(QSGTexture::Linear);
  }

  if (m_bgUpload && !m_bgTile.isNull()) {
    auto* texture = window()->createTextureFromImage(m_bgTile);
    SS_ASSERT_LOG(texture != nullptr);
    if (texture) {
      m_bgNode->setTexture(texture);
      m_bgUpload = false;
    }
  }

  m_bgNode->setRect(rect);
  root->appendChildNode(m_bgNode);
}

void Widgets::Plot3D::syncStrokeNodes(EyeArray<QSGGeometryNode*>& nodes,
                                      const EyeArray<std::vector<QPointF>>& px,
                                      const EyeArray<std::vector<QColor>>& colors,
                                      const double halfWidth)
{
  SS_ASSERT(halfWidth > 0.0, return);

  for (int slot = 0; slot < Plot3DStereo::kEyeSlots; ++slot) {
    SS_ASSERT_LOG(px[slot].size() == colors[slot].size());
    if (px[slot].size() != colors[slot].size())
      continue;

    nodes[slot] = GpuStroke::buildStrokeNode(nodes[slot],
                                             px[slot].data(),
                                             colors[slot].data(),
                                             static_cast<qsizetype>(px[slot].size()),
                                             halfWidth,
                                             eyeFactory(slot));
  }
}

int Widgets::Plot3DStereo::eyeSlot(const EyeMask mask)
{
  switch (mask) {
    case EyeMask::None:
    case EyeMask::Left:
      return 0;
    case EyeMask::Right:
      return 1;
  }

  Q_UNREACHABLE_RETURN(0);
}

bool Widgets::Plot3DStereo::shadersPresent()
{
  static const bool available = QFile::exists(QString::fromLatin1(kVertexShader))
                             && QFile::exists(QString::fromLatin1(kFragmentShader));

  return available;
}

float Widgets::Plot3DStereo::luminance(const QColor& color)
{
  SS_ASSERT(color.isValid(), return 0.0f);
  return 0.299f * color.redF() + 0.587f * color.greenF() + 0.114f * color.blueF();
}

Widgets::Plot3DStereo::EyeChannels Widgets::Plot3DStereo::eyeChannels(const EyeMask mask)
{
  switch (mask) {
    case EyeMask::None:
      return EyeChannels{true, true, true};
    case EyeMask::Left:
      return EyeChannels{true, false, false};
    case EyeMask::Right:
      return EyeChannels{false, true, true};
  }

  Q_UNREACHABLE_RETURN(EyeChannels{true, true, true});
}

QColor Widgets::Plot3DStereo::isolatedEyeColor(const QColor& color, const EyeMask mask)
{
  SS_ASSERT(color.isValid(), return color);
  if (mask == EyeMask::None)
    return color;

  const bool left = mask == EyeMask::Left;
  QColor out      = left ? QColor::fromRgbF(luminance(color), 0.0f, 0.0f)
                         : QColor::fromRgbF(0.0f, color.greenF(), color.blueF());

  out.setAlphaF(color.alphaF());
  return out;
}

QColor Widgets::Plot3DStereo::midBackground(const QColor& inner, const QColor& outer)
{
  SS_ASSERT(inner.isValid(), return outer);
  SS_ASSERT(outer.isValid(), return inner);

  return QColor::fromRgbF(0.5f * (inner.redF() + outer.redF()),
                          0.5f * (inner.greenF() + outer.greenF()),
                          0.5f * (inner.blueF() + outer.blueF()));
}

QColor Widgets::Plot3DStereo::blendedEyeColor(const QColor& color,
                                              const QColor& background,
                                              const EyeMask mask)
{
  if (mask == EyeMask::None)
    return color;

  SS_ASSERT(background.isValid(), return color);
  SS_ASSERT(color.isValid(), return color);

  const bool left = mask == EyeMask::Left;
  QColor out = left ? QColor::fromRgbF(luminance(color), background.greenF(), background.blueF())
                    : QColor::fromRgbF(background.redF(), color.greenF(), color.blueF());

  out.setAlphaF(left ? color.alphaF() : std::min(color.alphaF(), kOverlaidEyeAlpha));
  return out;
}

void TstPlot3DStereo::eyesOwnComplementaryChannels()
{
  const auto left  = Plot3DStereo::eyeChannels(Plot3DStereo::EyeMask::Left);
  const auto right = Plot3DStereo::eyeChannels(Plot3DStereo::EyeMask::Right);

  QVERIFY(left.red);
  QVERIFY(!left.green);
  QVERIFY(!left.blue);

  QVERIFY(!right.red);
  QVERIFY(right.green);
  QVERIFY(right.blue);

  QVERIFY(!(left.red && right.red));
  QVERIFY(!(left.green && right.green));
  QVERIFY(!(left.blue && right.blue));
}

void TstPlot3DStereo::monoPassesThroughUntouched()
{
  const auto mono = Plot3DStereo::eyeChannels(Plot3DStereo::EyeMask::None);
  QVERIFY(mono.red);
  QVERIFY(mono.green);
  QVERIFY(mono.blue);

  const QColor source(0x1B, 0x8E, 0xE1, 0x9C);
  const QColor background(0xEF, 0xF0, 0xF1);
  QCOMPARE(Plot3DStereo::isolatedEyeColor(source, Plot3DStereo::EyeMask::None), source);
  QCOMPARE(Plot3DStereo::blendedEyeColor(source, background, Plot3DStereo::EyeMask::None), source);
}

void TstPlot3DStereo::isolatedColorsCarryOnlyTheOwnedChannels()
{
  const QColor source(0x1B, 0x8E, 0xE1);

  const QColor left = Plot3DStereo::isolatedEyeColor(source, Plot3DStereo::EyeMask::Left);
  QVERIFY(sameChannel(left.redF(), Plot3DStereo::luminance(source)));
  QVERIFY(sameChannel(left.greenF(), 0.0f));
  QVERIFY(sameChannel(left.blueF(), 0.0f));

  const QColor right = Plot3DStereo::isolatedEyeColor(source, Plot3DStereo::EyeMask::Right);
  QVERIFY(sameChannel(right.redF(), 0.0f));
  QVERIFY(sameChannel(right.greenF(), source.greenF()));
  QVERIFY(sameChannel(right.blueF(), source.blueF()));
}

void TstPlot3DStereo::isolatedAlphaIsNeverCapped()
{
  const QColor opaque(0x5F, 0x66, 0x70, 0xFF);
  const QColor opaqueLeft  = Plot3DStereo::isolatedEyeColor(opaque, Plot3DStereo::EyeMask::Left);
  const QColor opaqueRight = Plot3DStereo::isolatedEyeColor(opaque, Plot3DStereo::EyeMask::Right);
  QVERIFY(sameChannel(opaqueLeft.alphaF(), 1.0f));
  QVERIFY(sameChannel(opaqueRight.alphaF(), 1.0f));

  const QColor faded(0x5F, 0x66, 0x70, 100);
  const QColor left = Plot3DStereo::isolatedEyeColor(faded, Plot3DStereo::EyeMask::Left);
  QVERIFY(sameChannel(left.alphaF(), faded.alphaF()));
}

void TstPlot3DStereo::everyThemeColorReachesBothEyes()
{
  constexpr float kMinContrast = 0.05f;

  for (const auto& theme : palettes()) {
    const QColor inner(QString::fromLatin1(theme.innerBackground));
    const QColor outer(QString::fromLatin1(theme.outerBackground));
    const QColor background = Plot3DStereo::midBackground(inner, outer);

    for (const char* entry : theme.colors) {
      const QColor source(QString::fromLatin1(entry));
      QVERIFY2(source.isValid(), entry);

      const QColor left  = Plot3DStereo::isolatedEyeColor(source, Plot3DStereo::EyeMask::Left);
      const QColor right = Plot3DStereo::isolatedEyeColor(source, Plot3DStereo::EyeMask::Right);

      const float red   = contrast(left.redF(), background.redF());
      const float green = contrast(right.greenF(), background.greenF());
      const float blue  = contrast(right.blueF(), background.blueF());

      QVERIFY2(red >= kMinContrast,
               qPrintable(QStringLiteral("%1 / %2 red eye")
                            .arg(QString::fromLatin1(theme.name), QString::fromLatin1(entry))));
      QVERIFY2(std::max(green, blue) >= kMinContrast,
               qPrintable(QStringLiteral("%1 / %2 cyan eye")
                            .arg(QString::fromLatin1(theme.name), QString::fromLatin1(entry))));
    }
  }
}

void TstPlot3DStereo::redAxisOnLightThemeReachesTheRedEye()
{
  const QColor axis(QStringLiteral("#e04b5a"));
  const QColor background(QStringLiteral("#eff0f1"));

  const float raw      = contrast(axis.redF(), background.redF());
  const QColor left    = Plot3DStereo::isolatedEyeColor(axis, Plot3DStereo::EyeMask::Left);
  const float isolated = contrast(left.redF(), background.redF());

  QVERIFY(raw < 0.08f);
  QVERIFY(isolated > 0.35f);
}

void TstPlot3DStereo::blueTraceOnDarkThemeReachesTheRedEye()
{
  const QColor trace(QStringLiteral("#1B8EE1"));
  const QColor background(QStringLiteral("#1A1A1A"));

  const float raw      = contrast(trace.redF(), background.redF());
  const QColor left    = Plot3DStereo::isolatedEyeColor(trace, Plot3DStereo::EyeMask::Left);
  const float isolated = contrast(left.redF(), background.redF());

  QVERIFY(raw < 0.02f);
  QVERIFY(isolated > 0.30f);
}

void TstPlot3DStereo::cyanEyeKeepsTheSourceHue()
{
  const QColor blue(QStringLiteral("#1B8EE1"));
  const QColor orange(QStringLiteral("#DB681A"));

  const auto right         = Plot3DStereo::EyeMask::Right;
  const QColor blueRight   = Plot3DStereo::isolatedEyeColor(blue, right);
  const QColor orangeRight = Plot3DStereo::isolatedEyeColor(orange, right);

  QVERIFY(blueRight.blueF() > blueRight.greenF());
  QVERIFY(orangeRight.greenF() > orangeRight.blueF());
  QVERIFY(blueRight != orangeRight);
}

void TstPlot3DStereo::blendedFallbackFillsFromTheBackground()
{
  const QColor source(QStringLiteral("#5f6670"));
  const QColor background(QStringLiteral("#eff0f1"));

  const QColor left =
    Plot3DStereo::blendedEyeColor(source, background, Plot3DStereo::EyeMask::Left);
  QVERIFY(sameChannel(left.greenF(), background.greenF()));
  QVERIFY(sameChannel(left.blueF(), background.blueF()));
  QVERIFY(sameChannel(left.redF(), Plot3DStereo::luminance(source)));

  const QColor right =
    Plot3DStereo::blendedEyeColor(source, background, Plot3DStereo::EyeMask::Right);
  QVERIFY(sameChannel(right.redF(), background.redF()));
  QVERIFY(sameChannel(right.greenF(), source.greenF()));
  QVERIFY(sameChannel(right.blueF(), source.blueF()));
}

void TstPlot3DStereo::blendedFallbackCapsOnlyTheOverlaidEye()
{
  const QColor opaque(0x1B, 0x8E, 0xE1, 0xFF);
  const QColor background(QStringLiteral("#eff0f1"));

  const QColor left =
    Plot3DStereo::blendedEyeColor(opaque, background, Plot3DStereo::EyeMask::Left);
  QVERIFY(sameChannel(left.alphaF(), 1.0f));

  const QColor right =
    Plot3DStereo::blendedEyeColor(opaque, background, Plot3DStereo::EyeMask::Right);
  QVERIFY(sameChannel(right.alphaF(), Plot3DStereo::kOverlaidEyeAlpha));

  const QColor faded(0x5F, 0x66, 0x70, 100);
  const QColor fadedRight =
    Plot3DStereo::blendedEyeColor(faded, background, Plot3DStereo::EyeMask::Right);
  QVERIFY(sameChannel(fadedRight.alphaF(), faded.alphaF()));
}

void TstPlot3DStereo::slotsSeparateTheEyesAndShareMono()
{
  QCOMPARE(Plot3DStereo::eyeSlot(Plot3DStereo::EyeMask::None), 0);
  QCOMPARE(Plot3DStereo::eyeSlot(Plot3DStereo::EyeMask::Left), 0);
  QCOMPARE(Plot3DStereo::eyeSlot(Plot3DStereo::EyeMask::Right), 1);
  QVERIFY(Plot3DStereo::eyeSlot(Plot3DStereo::EyeMask::Left)
          != Plot3DStereo::eyeSlot(Plot3DStereo::EyeMask::Right));
  QVERIFY(Plot3DStereo::kEyeSlots == 2);
}

void TstConsoleAnnotations::decoderPausesWithoutViewer()
{
  Console::AnnotationModel model;
  Console::AnnotationDecoder decoder(&model);
  decoder.setCode(newlineDecoder());
  decoder.setEnabled(true);
  QVERIFY(!decoder.active());

  decoder.feed(QByteArrayLiteral("abc\n"));
  model.commitPending();
  QCOMPARE(model.count(), 0);
  QCOMPARE(model.retainedEnd(), qint64(0));

  QObject viewer;
  decoder.setViewerActive(&viewer, true);
  QVERIFY(decoder.active());

  decoder.feed(QByteArrayLiteral("abc"));
  model.commitPending();
  QCOMPARE(model.count(), 0);
  QCOMPARE(model.retainedEnd(), qint64(3));

  decoder.setViewerActive(&viewer, false);
  decoder.feed(QByteArrayLiteral("xyz\n"));
  model.commitPending();
  QCOMPARE(model.count(), 0);
  QCOMPARE(model.retainedEnd(), qint64(3));

  decoder.setViewerActive(&viewer, true);
  decoder.feed(QByteArrayLiteral("de\n"));
  model.commitPending();
  QCOMPARE(model.count(), 2);
  QCOMPARE(model.at(0).start, qint64(3));
  QCOMPARE(model.at(0).end, qint64(4));
  QCOMPARE(model.at(1).start, qint64(5));
}

