static int bestNormalizedFormatIndex(const QList<ma_format>& formats)
{
  for (const auto format : kNormalizedFormats) {
    const int index = formats.indexOf(format);
    if (index >= 0)
      return index;
  }

  return 0;
}

static void normalizationTerms(ma_format format, bool enabled, float& offset, float& scale)
{
  offset = 0.0f;
  scale  = 1.0f;
  if (!enabled)
    return;

  switch (format) {
    case ma_format_u8:
      offset = -128.0f;
      scale  = kInvFullScaleU8;
      break;
    case ma_format_s16:
      scale = kInvFullScaleS16;
      break;
    case ma_format_s24:
      scale = kInvFullScaleS24;
      break;
    case ma_format_s32:
      scale = kInvFullScaleS32;
      break;
    default:
      break;
  }
}

static float decodeSample(ma_format format, const char* ptr)
{
  switch (format) {
    case ma_format_u8:
      return static_cast<float>(static_cast<quint8>(*ptr));
    case ma_format_s16:
      return static_cast<float>(qFromLittleEndian<qint16>(reinterpret_cast<const quint8*>(ptr)));
    case ma_format_s24: {
      const quint8* b  = reinterpret_cast<const quint8*>(ptr);
      const qint32 s24 = static_cast<qint32>(b[0]) | (static_cast<qint32>(b[1]) << 8)
                       | (static_cast<qint32>(b[2]) << 16);
      return static_cast<float>((s24 & 0x800000) ? (s24 | static_cast<qint32>(0xFF000000)) : s24);
    }
    case ma_format_s32:
      return static_cast<float>(qFromLittleEndian<qint32>(reinterpret_cast<const quint8*>(ptr)));
    case ma_format_f32: {
      float sample;
      std::memcpy(&sample, ptr, sizeof(float));
      return sample;
    }
    default:
      return 0.0f;
  }
}

static bool packNormalizedSample(ma_format format, const QByteArray& token, QVector<quint8>& out)
{
  bool ok      = false;
  float sample = token.toFloat(&ok);
  if (!ok) {
    qWarning() << "Invalid normalized sample:" << token;
    return false;
  }

  sample = qBound(-1.0f, sample, 1.0f);

  if (format == ma_format_f32) {
    const quint8* bytes = reinterpret_cast<const quint8*>(&sample);
    for (size_t b = 0; b < sizeof(float); ++b)
      out.append(bytes[b]);

    return true;
  }

  if (format == ma_format_u8) {
    out.append(static_cast<quint8>(qBound(0, qRound(sample * 127.0f) + 128, 255)));
    return true;
  }

  if (format == ma_format_s16) {
    const qint16 value  = static_cast<qint16>(qRound(sample * 32767.0f));
    const quint8* bytes = reinterpret_cast<const quint8*>(&value);
    out.append(bytes[0]);
    out.append(bytes[1]);
    return true;
  }

  if (format == ma_format_s24) {
    const qint32 value = qRound(sample * 8388607.0f);
    out.append(static_cast<quint8>(value & 0xFF));
    out.append(static_cast<quint8>((value >> 8) & 0xFF));
    out.append(static_cast<quint8>((value >> 16) & 0xFF));
    return true;
  }

  if (format == ma_format_s32) {
    const auto value    = static_cast<qint32>(qRound(static_cast<double>(sample) * 2147483647.0));
    const quint8* bytes = reinterpret_cast<const quint8*>(&value);
    out.append(bytes[0]);
    out.append(bytes[1]);
    out.append(bytes[2]);
    out.append(bytes[3]);
    return true;
  }

  qWarning() << "Unsupported format:" << static_cast<int>(format);
  return false;
}

static void setVertexColor(QSGGeometry::ColoredPoint2D& vertex,
                           const float x,
                           const float y,
                           const QColor& color,
                           double alpha)
{
  SS_ASSERT(alpha >= 0.0 && alpha <= 1.0, alpha = std::clamp(alpha, 0.0, 1.0));

  vertex.set(x,
             y,
             static_cast<unsigned char>(std::lround(color.redF() * alpha * 255.0)),
             static_cast<unsigned char>(std::lround(color.greenF() * alpha * 255.0)),
             static_cast<unsigned char>(std::lround(color.blueF() * alpha * 255.0)),
             static_cast<unsigned char>(std::lround(alpha * 255.0)));
}

static bool unitDir(const QPointF& from, const QPointF& to, QPointF& dir)
{
  const double dx  = to.x() - from.x();
  const double dy  = to.y() - from.y();
  const double len = std::sqrt(dx * dx + dy * dy);
  if (!(len > 1e-6))
    return false;

  dir = QPointF(dx / len, dy / len);
  return true;
}

static int fanSegments(const QPointF& dIn, const QPointF& dOut)
{
  const double dot   = std::clamp(dIn.x() * dOut.x() + dIn.y() * dOut.y(), -1.0, 1.0);
  const double cross = dIn.x() * dOut.y() - dIn.y() * dOut.x();
  const double phi   = std::atan2(std::abs(cross), dot);
  return std::clamp(static_cast<int>(std::ceil(phi / kFanStep)), 0, kFanMax);
}

static void emitCapSection(QSGGeometry::ColoredPoint2D* vertices,
                           int& v,
                           const QPointF& p,
                           const QPointF& n,
                           double hw,
                           const QColor& color)
{
  SS_ASSERT(vertices != nullptr, return);
  SS_ASSERT(hw > 0.0, hw = 0.25);

  const double alpha = color.alphaF();
  const double face  = std::max(0.25, hw - kFeatherPx * 0.5);
  const double edge  = face + kFeatherPx;

  setVertexColor(vertices[v++],
                 static_cast<float>(p.x() + n.x() * edge),
                 static_cast<float>(p.y() + n.y() * edge),
                 color,
                 0.0);
  setVertexColor(vertices[v++],
                 static_cast<float>(p.x() + n.x() * face),
                 static_cast<float>(p.y() + n.y() * face),
                 color,
                 alpha);
  setVertexColor(vertices[v++],
                 static_cast<float>(p.x() - n.x() * face),
                 static_cast<float>(p.y() - n.y() * face),
                 color,
                 alpha);
  setVertexColor(vertices[v++],
                 static_cast<float>(p.x() - n.x() * edge),
                 static_cast<float>(p.y() - n.y() * edge),
                 color,
                 0.0);
}

static void emitFan(QSGGeometry::ColoredPoint2D* vertices,
                    quint32* indices,
                    int& v,
                    int& idx,
                    const QPointF& p,
                    const QPointF& n0,
                    const QPointF& n1,
                    const int nFan,
                    const double hw,
                    const QColor& color)
{
  SS_ASSERT(vertices != nullptr, return);
  SS_ASSERT(indices != nullptr, return);
  SS_ASSERT(nFan >= 1, return);

  const double alpha = color.alphaF();
  const double face  = std::max(0.25, hw - kFeatherPx * 0.5);
  const double edge  = face + kFeatherPx;

  const double dot   = std::clamp(n0.x() * n1.x() + n0.y() * n1.y(), -1.0, 1.0);
  const double cross = n0.x() * n1.y() - n0.y() * n1.x();
  const double sweep = std::atan2(cross, dot) / nFan;
  const double cs    = std::cos(sweep);
  const double sn    = std::sin(sweep);

  const int center = v;
  setVertexColor(vertices[v++], static_cast<float>(p.x()), static_cast<float>(p.y()), color, alpha);

  double rx = n0.x();
  double ry = n0.y();
  for (int j = 0; j <= nFan; ++j) {
    const double dx = (j == nFan) ? n1.x() : rx;
    const double dy = (j == nFan) ? n1.y() : ry;
    setVertexColor(vertices[v++],
                   static_cast<float>(p.x() + dx * face),
                   static_cast<float>(p.y() + dy * face),
                   color,
                   alpha);
    setVertexColor(vertices[v++],
                   static_cast<float>(p.x() + dx * edge),
                   static_cast<float>(p.y() + dy * edge),
                   color,
                   0.0);
    const double nx = rx * cs - ry * sn;
    ry              = rx * sn + ry * cs;
    rx              = nx;
  }

  for (int j = 0; j < nFan; ++j) {
    const int c0   = center + 1 + 2 * j;
    const int c1   = center + 1 + 2 * (j + 1);
    indices[idx++] = static_cast<quint32>(center);
    indices[idx++] = static_cast<quint32>(c0);
    indices[idx++] = static_cast<quint32>(c1);
    indices[idx++] = static_cast<quint32>(c0);
    indices[idx++] = static_cast<quint32>(c0 + 1);
    indices[idx++] = static_cast<quint32>(c1 + 1);
    indices[idx++] = static_cast<quint32>(c0);
    indices[idx++] = static_cast<quint32>(c1 + 1);
    indices[idx++] = static_cast<quint32>(c1);
  }
}

static void emitJoinIndices(quint32* indices, int& idx, const int a, const int b)
{
  SS_ASSERT(indices != nullptr, return);
  SS_ASSERT(a >= 0 && b >= 0, return);

  for (int k = 0; k < 3; ++k) {
    indices[idx++] = static_cast<quint32>(a + k);
    indices[idx++] = static_cast<quint32>(b + k);
    indices[idx++] = static_cast<quint32>(a + k + 1);
    indices[idx++] = static_cast<quint32>(b + k);
    indices[idx++] = static_cast<quint32>(b + k + 1);
    indices[idx++] = static_cast<quint32>(a + k + 1);
  }
}

qsizetype Widgets::GpuStroke::runLength(const QPointF* pts, const qsizetype count, qsizetype& start)
{
  SS_ASSERT(pts != nullptr, return 0);
  SS_ASSERT(count >= 0, return 0);

  while (start < count && (!std::isfinite(pts[start].x()) || !std::isfinite(pts[start].y())))
    ++start;

  qsizetype end = start;
  while (end < count && std::isfinite(pts[end].x()) && std::isfinite(pts[end].y()))
    ++end;

  return end - start;
}

static QColor lerpColor(const QColor& a, const QColor& b, const double t)
{
  QColor out;
  out.setRedF(a.redF() * (1.0 - t) + b.redF() * t);
  out.setGreenF(a.greenF() * (1.0 - t) + b.greenF() * t);
  out.setBlueF(a.blueF() * (1.0 - t) + b.blueF() * t);
  out.setAlphaF(a.alphaF() * (1.0 - t) + b.alphaF() * t);
  return out;
}

static void pushDashPoint(std::vector<QPointF>& outPx,
                          std::vector<QColor>& outColors,
                          const QPointF& p,
                          const QColor& color)
{
  outPx.push_back(p);
  outColors.push_back(color);
}

static void closeDashSpan(std::vector<QPointF>& outPx,
                          std::vector<QColor>& outColors,
                          const QColor& color,
                          DashState& state)
{
  if (!state.spanOpen)
    return;

  pushDashPoint(outPx, outColors, QPointF(qQNaN(), qQNaN()), color);
  state.spanOpen = false;
}

static void dashSegment(const QPointF& a,
                        const QPointF& b,
                        const QColor& ca,
                        const QColor& cb,
                        const double onLength,
                        const double offLength,
                        DashState& state,
                        std::vector<QPointF>& outPx,
                        std::vector<QColor>& outColors)
{
  const double segLength = std::hypot(b.x() - a.x(), b.y() - a.y());
  if (!(segLength > 0.0))
    return;

  double travelled = 0.0;
  while (travelled < segLength) {
    const double step = std::min(state.remaining, segLength - travelled);
    const double t0   = travelled / segLength;
    const double t1   = (travelled + step) / segLength;

    if (state.drawing && !state.spanOpen) {
      pushDashPoint(outPx, outColors, a + (b - a) * t0, lerpColor(ca, cb, t0));
      state.spanOpen = true;
    }

    if (state.drawing)
      pushDashPoint(outPx, outColors, a + (b - a) * t1, lerpColor(ca, cb, t1));

    travelled       += step;
    state.remaining -= step;
    if (state.remaining > 1e-9)
      continue;

    closeDashSpan(outPx, outColors, cb, state);
    state.drawing   = !state.drawing;
    state.remaining = state.drawing ? onLength : offLength;
  }
}

void Widgets::GpuStroke::dashPolyline(const QPointF* px,
                                      const QColor* colors,
                                      const qsizetype count,
                                      const double onLength,
                                      const double offLength,
                                      std::vector<QPointF>& outPx,
                                      std::vector<QColor>& outColors)
{
  outPx.clear();
  outColors.clear();

  SS_ASSERT(px != nullptr, return);
  SS_ASSERT(colors != nullptr, return);
  SS_ASSERT(onLength > 0.0 && offLength > 0.0, return);
  if (count < 2)
    return;

  DashState state{true, false, onLength};
  for (qsizetype i = 0; i + 1 < count; ++i) {
    const QPointF a = px[i];
    const QPointF b = px[i + 1];
    const bool finite =
      std::isfinite(a.x()) && std::isfinite(a.y()) && std::isfinite(b.x()) && std::isfinite(b.y());
    if (!finite) {
      closeDashSpan(outPx, outColors, colors[i], state);
      continue;
    }

    dashSegment(a, b, colors[i], colors[i + 1], onLength, offLength, state, outPx, outColors);
  }

  closeDashSpan(outPx, outColors, colors[count - 1], state);
}

void Widgets::GpuStroke::countRun(const QPointF* px,
                                  const qsizetype start,
                                  const qsizetype len,
                                  qsizetype& vertexCount,
                                  qsizetype& indexCount)
{
  SS_ASSERT(px != nullptr, return);
  SS_ASSERT(len >= 2, return);

  auto dirAt = [&](const qsizetype i, const QPointF& fallback) {
    QPointF dir = fallback;
    (void)unitDir(px[start + i], px[start + i + 1], dir);
    return dir;
  };

  QPointF prevDir = dirAt(0, QPointF(1, 0));
  for (qsizetype i = 0; i + 1 < len; ++i) {
    const QPointF dir  = dirAt(i, prevDir);
    vertexCount       += 8;
    indexCount        += 18;

    if (i + 2 < len) {
      const QPointF dOut = dirAt(i + 1, dir);
      const int nFan     = fanSegments(dir, dOut);
      if (nFan >= 1) {
        vertexCount += 2 * nFan + 3;
        indexCount  += 9 * nFan;
      }
    }

    prevDir = dir;
  }
}

void Widgets::GpuStroke::emitRun(QSGGeometry::ColoredPoint2D* vertices,
                                 quint32* indices,
                                 int& v,
                                 int& idx,
                                 const QPointF* px,
                                 const qsizetype start,
                                 const qsizetype len,
                                 const double hw,
                                 const QColor& color,
                                 const QColor* colors)
{
  SS_ASSERT(vertices != nullptr, return);
  SS_ASSERT(indices != nullptr, return);
  SS_ASSERT(len >= 2, return);

  auto colorAt = [&](const qsizetype i) -> const QColor& {
    return colors ? colors[start + i] : color;
  };

  auto dirAt = [&](const qsizetype i, const QPointF& fallback) {
    QPointF dir = fallback;
    (void)unitDir(px[start + i], px[start + i + 1], dir);
    return dir;
  };

  QPointF prevDir = dirAt(0, QPointF(1, 0));
  for (qsizetype i = 0; i + 1 < len; ++i) {
    const QPointF dir = dirAt(i, prevDir);
    const QPointF n(-dir.y(), dir.x());

    const int body = v;
    emitCapSection(vertices, v, px[start + i], n, hw, colorAt(i));
    emitCapSection(vertices, v, px[start + i + 1], n, hw, colorAt(i + 1));
    emitJoinIndices(indices, idx, body, body + 4);

    if (i + 2 < len) {
      const QPointF dOut = dirAt(i + 1, dir);
      const int nFan     = fanSegments(dir, dOut);
      if (nFan >= 1) {
        const double s = (dir.x() * dOut.y() - dir.y() * dOut.x()) < 0.0 ? 1.0 : -1.0;
        const QPointF nOut(-dOut.y(), dOut.x());
        emitFan(vertices,
                indices,
                v,
                idx,
                px[start + i + 1],
                QPointF(n.x() * s, n.y() * s),
                QPointF(nOut.x() * s, nOut.y() * s),
                nFan,
                hw,
                colorAt(i + 1));
      }
    }

    prevDir = dir;
  }
}

static void emitPointQuad(QSGGeometry::ColoredPoint2D* vertices,
                          quint32* indices,
                          int& v,
                          int& idx,
                          const QPointF& p,
                          const double halfSize,
                          const QColor& color)
{
  SS_ASSERT(vertices != nullptr, return);
  SS_ASSERT(indices != nullptr, return);

  const double alpha = color.alphaF();
  const int base     = v;

  setVertexColor(vertices[v++],
                 static_cast<float>(p.x() - halfSize),
                 static_cast<float>(p.y() - halfSize),
                 color,
                 alpha);
  setVertexColor(vertices[v++],
                 static_cast<float>(p.x() + halfSize),
                 static_cast<float>(p.y() - halfSize),
                 color,
                 alpha);
  setVertexColor(vertices[v++],
                 static_cast<float>(p.x() + halfSize),
                 static_cast<float>(p.y() + halfSize),
                 color,
                 alpha);
  setVertexColor(vertices[v++],
                 static_cast<float>(p.x() - halfSize),
                 static_cast<float>(p.y() + halfSize),
                 color,
                 alpha);

  indices[idx++] = static_cast<quint32>(base);
  indices[idx++] = static_cast<quint32>(base + 1);
  indices[idx++] = static_cast<quint32>(base + 2);
  indices[idx++] = static_cast<quint32>(base);
  indices[idx++] = static_cast<quint32>(base + 2);
  indices[idx++] = static_cast<quint32>(base + 3);
}

QSGGeometryNode* Widgets::GpuStroke::buildStrokeNode(QSGGeometryNode* node,
                                                     const QPointF* px,
                                                     const QColor* colors,
                                                     const qsizetype count,
                                                     const double halfWidth)
{
  SS_ASSERT(halfWidth > 0.0, return nullptr);

  if (!px || !colors || count < 2) {
    delete node;
    return nullptr;
  }

  qsizetype vertexCount = 0;
  qsizetype indexCount  = 0;
  qsizetype start       = 0;
  while (start < count) {
    const qsizetype len = runLength(px, count, start);
    if (len >= 2)
      countRun(px, start, len, vertexCount, indexCount);

    start += len;
  }

  const bool drawable = vertexCount >= 8 && indexCount >= 18 && vertexCount <= kMaxGeometry
                     && indexCount <= kMaxGeometry;
  if (!drawable) {
    delete node;
    return nullptr;
  }

  const int vertices = static_cast<int>(vertexCount);
  const int idxs     = static_cast<int>(indexCount);

  if (!node) {
    node           = new QSGGeometryNode;
    auto* geometry = new QSGGeometry(
      QSGGeometry::defaultAttributes_ColoredPoint2D(), 0, 0, QSGGeometry::UnsignedIntType);
    geometry->setDrawingMode(QSGGeometry::DrawTriangles);
    node->setGeometry(geometry);
    node->setFlag(QSGNode::OwnsGeometry);
    node->setMaterial(new QSGVertexColorMaterial);
    node->setFlag(QSGNode::OwnsMaterial);
  }

  auto* geometry = node->geometry();
  SS_ASSERT(geometry != nullptr, return node);
  if (geometry->vertexCount() != vertices || geometry->indexCount() != idxs)
    geometry->allocate(vertices, idxs);

  int v   = 0;
  int idx = 0;
  start   = 0;
  while (start < count) {
    const qsizetype len = runLength(px, count, start);
    if (len >= 2)
      emitRun(geometry->vertexDataAsColoredPoint2D(),
              geometry->indexDataAsUInt(),
              v,
              idx,
              px,
              start,
              len,
              halfWidth,
              colors[start],
              colors);

    start += len;
  }

  node->markDirty(QSGNode::DirtyGeometry);
  return node;
}

QSGGeometryNode* Widgets::GpuStroke::buildPointNode(QSGGeometryNode* node,
                                                    const QPointF* px,
                                                    const QColor* colors,
                                                    const qsizetype count,
                                                    const double halfSize)
{
  SS_ASSERT(halfSize > 0.0, return nullptr);

  if (!px || !colors || count < 1) {
    delete node;
    return nullptr;
  }

  qsizetype points = 0;
  for (qsizetype i = 0; i < count; ++i)
    if (std::isfinite(px[i].x()) && std::isfinite(px[i].y()))
      ++points;

  const qsizetype vertexCount = points * 4;
  const qsizetype indexCount  = points * 6;
  const bool drawable = points >= 1 && vertexCount <= kMaxGeometry && indexCount <= kMaxGeometry;
  if (!drawable) {
    delete node;
    return nullptr;
  }

  const int vertices = static_cast<int>(vertexCount);
  const int idxs     = static_cast<int>(indexCount);

  if (!node) {
    node           = new QSGGeometryNode;
    auto* geometry = new QSGGeometry(
      QSGGeometry::defaultAttributes_ColoredPoint2D(), 0, 0, QSGGeometry::UnsignedIntType);
    geometry->setDrawingMode(QSGGeometry::DrawTriangles);
    node->setGeometry(geometry);
    node->setFlag(QSGNode::OwnsGeometry);
    node->setMaterial(new QSGVertexColorMaterial);
    node->setFlag(QSGNode::OwnsMaterial);
  }

  auto* geometry = node->geometry();
  SS_ASSERT(geometry != nullptr, return node);
  if (geometry->vertexCount() != vertices || geometry->indexCount() != idxs)
    geometry->allocate(vertices, idxs);

  auto* vertexData = geometry->vertexDataAsColoredPoint2D();
  auto* indexData  = geometry->indexDataAsUInt();

  int v   = 0;
  int idx = 0;
  for (qsizetype i = 0; i < count; ++i) {
    if (!std::isfinite(px[i].x()) || !std::isfinite(px[i].y()))
      continue;

    emitPointQuad(vertexData, indexData, v, idx, px[i], halfSize, colors[i]);
  }

  node->markDirty(QSGNode::DirtyGeometry);
  return node;
}

static void appendPolyline(std::vector<QPointF>& dstPx,
                           std::vector<QColor>& dstColors,
                           const std::vector<QPointF>& srcPx,
                           const std::vector<QColor>& srcColors)
{
  if (srcPx.empty())
    return;

  if (!dstPx.empty()) {
    dstPx.push_back(QPointF(qQNaN(), qQNaN()));
    dstColors.push_back(srcColors.front());
  }

  dstPx.insert(dstPx.end(), srcPx.begin(), srcPx.end());
  dstColors.insert(dstColors.end(), srcColors.begin(), srcColors.end());
}

void Widgets::Plot3D::syncTraceNode()
{
  SS_ASSERT(m_tracePx.size() == m_traceColors.size(), return);

  const auto count = static_cast<qsizetype>(m_tracePx.size());
  if (m_interpolate)
    m_traceNode =
      GpuStroke::buildStrokeNode(m_traceNode, m_tracePx.data(), m_traceColors.data(), count, 1.0);
  else
    m_traceNode =
      GpuStroke::buildPointNode(m_traceNode, m_tracePx.data(), m_traceColors.data(), count, 1.0);
}

void Widgets::Plot3D::appendSceneNodes(QSGNode* root)
{
  SS_ASSERT(root != nullptr, return);
  const bool gridOnTop = m_cameraAngleX <= 270.0 && m_cameraAngleX > 90.0;
  if (gridOnTop && m_traceNode)
    root->appendChildNode(m_traceNode);
  if (m_gridNode)
    root->appendChildNode(m_gridNode);
  if (m_axisNode)
    root->appendChildNode(m_axisNode);
  if (!gridOnTop && m_traceNode)
    root->appendChildNode(m_traceNode);
  if (m_labelNode)
    root->appendChildNode(m_labelNode);
  if (m_indicatorNode)
    root->appendChildNode(m_indicatorNode);
}

void Widgets::Plot3D::updatePolish()
{
  if (m_dirtyBackground) {
    m_bgTile = UI::Widgets::Plot3DDetail::buildBackgroundTile(
      boundingRect().size().toSize(), m_innerBackgroundColor, m_outerBackgroundColor);
    m_dirtyBackground = false;
    m_bgUpload        = true;
  }

  if (m_dirtyGrid)
    drawGrid();

  if (m_dirtyData)
    drawData();

  if (m_dirtyCameraIndicator)
    drawCameraIndicator();

  if (m_dirtyLabel)
    drawGridLabel();
}

void Widgets::Plot3D::applyCameraTransform(QMatrix4x4& matrix) const
{
  matrix.rotate(m_cameraAngleX, 1, 0, 0);
  matrix.rotate(m_cameraAngleY, 0, 1, 0);
  matrix.rotate(m_cameraAngleZ, 0, 0, 1);
  matrix.scale(m_worldScale);
  matrix.translate(-m_centerPoint);
 * @brief Rebuilds the grid and axis polylines. With stereo on, both eyes accumulate into the
 *        same buffers under complementary channel masks, replacing the two extra full-screen
 *        layers and the per-pixel merge.
void Widgets::Plot3D::drawGrid()
  m_gridPx.clear();
  m_gridColors.clear();
  m_axisPx.clear();
  m_axisColors.clear();

  matrix.perspective(45.0f, float(width()) / height(), kNearPlane, kFarPlane);
  matrix.translate(m_cameraOffsetX, m_cameraOffsetY, m_cameraOffsetZ);
    applyCameraTransform(eyes.first);
    applyCameraTransform(eyes.second);
    buildGridPolylines(eyes.first, EyeMask::Left);
    buildGridPolylines(eyes.second, EyeMask::Right);
    applyCameraTransform(matrix);
    buildGridPolylines(matrix, EyeMask::None);
  m_dirtyGrid = false;
}

void Widgets::Plot3D::drawCameraIndicator()
{

  if (width() < kIndicatorMinSize || height() < kIndicatorMinSize) {
    m_indicatorTile = QImage();
    return;
  }

  QMatrix4x4 matrix;
  matrix.rotate(m_cameraAngleX, 1, 0, 0);
  matrix.rotate(m_cameraAngleY, 0, 1, 0);
  matrix.rotate(m_cameraAngleZ, 0, 0, 1);

  const UI::Widgets::Plot3DDetail::IndicatorColors colors{
    m_xAxisColor, m_yAxisColor, m_zAxisColor, m_axisTextColor};

  m_indicatorTile = UI::Widgets::Plot3DDetail::buildCameraIndicatorTile(
    kIndicatorTileSize, displayPixelRatio(), matrix, m_commonFonts.customMonoFont(0.8), colors);
  m_indicatorUpload = true;
}

QImage UI::Widgets::Plot3DDetail::buildBackgroundTile(const QSize& itemSize,
                                                      const QColor& innerColor,
                                                      const QColor& outerColor)
{
  const int tw = qMax(32, itemSize.width() / 4);
  const int th = qMax(32, itemSize.height() / 4);

  QImage tile(tw, th, QImage::Format_ARGB32_Premultiplied);
  tile.fill(Qt::transparent);

  const QPointF center(tw * 0.5, th * 0.5);
  const double radius = qMax(tw, th) * 0.25;

  QRadialGradient gradient(center, radius);
  gradient.setColorAt(0.0, innerColor);
  gradient.setColorAt(1.0, outerColor);

  QPainter painter(&tile);
  painter.fillRect(QRectF(0, 0, tw, th), gradient);

  return tile;
}

QImage UI::Widgets::Plot3DDetail::buildCameraIndicatorTile(const int tileSize,
                                                           const qreal pixelRatio,
                                                           const QMatrix4x4& matrix,
                                                           const QFont& font,
                                                           const IndicatorColors& colors)
{
  QImage tile(QSize(tileSize, tileSize) * pixelRatio, QImage::Format_ARGB32_Premultiplied);
  tile.setDevicePixelRatio(pixelRatio);
  tile.fill(Qt::transparent);

  QPainter painter(&tile);
  painter.setRenderHint(QPainter::Antialiasing, true);
  painter.setFont(font);

  constexpr float kLineScale  = 18.0f;
  constexpr float kAxisLength = 2.0f;
  const QPointF origin(tileSize * 0.5, tileSize * 0.5);

  QList<Plot3DOverlayDetail::IndicatorAxis> axes = {
    {{1, 0, 0}, colors.xAxis, QStringLiteral("X"), {}},
    {{0, 1, 0}, colors.yAxis, QStringLiteral("Y"), {}},
    {{0, 0, 1}, colors.zAxis, QStringLiteral("Z"), {}}
  };

  for (auto& axis : axes)
    axis.projected = matrix * QVector4D(axis.direction * kAxisLength, 1.0f);

  std::sort(
    axes.begin(),
    axes.end(),
    [](const Plot3DOverlayDetail::IndicatorAxis& a, const Plot3DOverlayDetail::IndicatorAxis& b) {
      return a.projected.z() < b.projected.z();
    });

  const QFontMetrics metrics(font);
  const int textWidth      = metrics.horizontalAdvance("X");
  const int textHeight     = metrics.height();
  const float circleRadius = std::max(textWidth, textHeight) * 0.7f;

  for (const auto& axis : axes) {
    const QVector4D& t = axis.projected;
    const float invW   = t.w() != 0.0f ? 1.0f / t.w() : 0.0f;
    const QPointF tip(origin.x() + (t.x() * invW) * kLineScale,
                      origin.y() - (t.y() * invW) * kLineScale);

    painter.setPen(QPen(axis.color, 3));
    painter.drawLine(origin, tip);

    painter.setBrush(axis.color);
    painter.setPen(Qt::NoPen);
    painter.drawEllipse(tip, circleRadius, circleRadius);

    const QRectF textRect(
      tip.x() - circleRadius, tip.y() - circleRadius, circleRadius * 2, circleRadius * 2);
    painter.setPen(colors.text);
    painter.drawText(textRect, Qt::AlignCenter, axis.label);
  }

  return tile;
}

QImage UI::Widgets::Plot3DDetail::buildTextTile(const QString& text,
                                                const QFont& font,
                                                const QColor& color,
                                                const qreal pixelRatio)
{
  if (text.isEmpty())
    return QImage();

  const QFontMetrics metrics(font);
  const QSize logical = metrics.size(Qt::TextSingleLine, text) + QSize(2, 2);
  if (logical.isEmpty())
    return QImage();

  QImage tile(logical * pixelRatio, QImage::Format_ARGB32_Premultiplied);
  tile.setDevicePixelRatio(pixelRatio);
  tile.fill(Qt::transparent);

  QPainter painter(&tile);
  painter.setRenderHint(QPainter::TextAntialiasing, true);
  painter.setFont(font);
  painter.setPen(color);
  painter.drawText(QRectF(0, 0, logical.width(), logical.height()), Qt::AlignCenter, text);

  return tile;
}

void Widgets::Waterfall::renderAxisLayer()
{
  m_axisDirty     = false;
  m_overlayUpload = true;

  const QSize itemSize(qMax(1, qCeil(width())), qMax(1, qCeil(height())));
  const qreal dpr     = (window() ? window()->devicePixelRatio() : 1.0);
  const QSize bufSize = itemSize * dpr;
  if (bufSize.isEmpty())
    return;

  if (m_axisLayer.size() != bufSize) {
    m_axisLayer = QImage(bufSize, QImage::Format_ARGB32_Premultiplied);
    m_axisLayer.setDevicePixelRatio(dpr);
  }
  m_axisLayer.fill(Qt::transparent);

  QPainter painter(&m_axisLayer);
  painter.setRenderHint(QPainter::Antialiasing, true);
  painter.setRenderHint(QPainter::TextAntialiasing, true);

  static auto& fonts = Misc::CommonFonts::instance();
  painter.setFont(fonts.widgetFont(0.83, false));

  const QFontMetrics fm(painter.font());
  m_cachedPlotRect = computePlotRect(fm);
  if (m_cachedPlotRect.isEmpty())
    return;

  painter.setPen(QPen(m_borderColor, 1));
  painter.setBrush(Qt::NoBrush);
  painter.drawRect(m_cachedPlotRect);

  if (m_axisVisible && width() >= kMinAxisWidth && height() >= kMinAxisHeight) {
    drawXAxis(&painter, m_cachedPlotRect);
    drawYAxis(&painter, m_cachedPlotRect);
  }

  if (m_markersVisible && !m_markers.empty())
    drawMarkers(&painter, m_cachedPlotRect);

  if (m_cursorEnabled && m_cursorHovering)
    drawCursor(&painter, m_cachedPlotRect);
}

void Widgets::Waterfall::markAxisDirty()
{
  m_axisDirty = true;
  polish();
  update();
}

void Widgets::Waterfall::updatePolish()
{
  if (m_axisDirty)
    renderAxisLayer();
}

void Widgets::Waterfall::drawXAxis(QPainter* painter, const QRectF& plotRect) const
{
  if (m_samplingRate <= 0)
    return;

  double wMin = 0.0;
  double wMax = 0.0;
  visibleFreqWindow(wMin, wMax);
  const double wRange = wMax - wMin;
  if (wRange <= 0.0)
    return;

  const QFontMetrics fm(painter->font());
  const double tickTopY  = plotRect.bottom();
  const double tickBotY  = plotRect.bottom() + kAxisTickPx;
  const double labelY    = tickBotY + kAxisLabelPad;
  const double invWRange = 1.0 / wRange;
  const auto tickFreqs   = collectFreqTicks(wMin, wMax);

  for (const double v : tickFreqs) {
    const double t = (worldFromFreq(v) - wMin) * invWRange;
    if (t < 0.0 || t > 1.0)
      continue;

    const double x = plotRect.left() + t * plotRect.width();

    painter->setPen(QPen(m_gridColor, 1, Qt::DotLine));
    painter->drawLine(QPointF(x, plotRect.top()), QPointF(x, plotRect.bottom()));

    painter->setPen(QPen(m_borderColor, 1));
    painter->drawLine(QPointF(x, tickTopY), QPointF(x, tickBotY));

    const QString label  = formatFreqTick(v);
    const int labelWidth = fm.horizontalAdvance(label);
    painter->setPen(m_textColor);
    painter->drawText(QPointF(x - labelWidth * 0.5, labelY + fm.ascent()), label);
  }
}

void Widgets::Waterfall::drawYAxis(QPainter* painter, const QRectF& plotRect) const
{
  double dataMin = 0.0;
  double dataMax = 0.0;
  if (m_campbellMode) {
    dataMin = m_yMin;
    dataMax = m_yMax;
  } else {
    static auto& timer = Misc::TimerEvents::instance();
    const double fps   = timer.fps() > 0 ? timer.fps() : 24.0;
    dataMin            = 0.0;
    dataMax            = m_historySize / fps;
  }
  const double dataRange = dataMax - dataMin;
  if (dataRange <= 0.0)
    return;

  const double srcH    = dataRange / m_yZoom;
  const double maxPan  = qMax(0.0, (dataRange - srcH) * 0.5);
  const double centerD = (dataMin + dataMax) * 0.5 + qBound(-maxPan, m_yPan * dataRange, maxPan);
  const double yMin    = centerD - srcH * 0.5;
  const double yMax    = centerD + srcH * 0.5;

  const AxisTicks ticks = computeTimeTicks(srcH, kAxisTickCount);

  const QFontMetrics fm(painter->font());
  const double tickRightX = plotRect.left();
  const double tickLeftX  = plotRect.left() - kAxisTickPx;
  const double labelRight = tickLeftX - kAxisLabelPad;

  const double step      = ticks.step;
  const double invStep   = 1.0 / step;
  const double first     = std::ceil(yMin * invStep - 1e-9) * step;
  const double yRange    = yMax - yMin;
  const double invYRange = yRange > 0.0 ? 1.0 / yRange : 0.0;

  for (double v = first; v <= yMax + 1e-6; v += step) {
    const double t = (v - yMin) * invYRange;
    if (t < 0.0 || t > 1.0)
      continue;

    const double y = m_campbellMode ? plotRect.bottom() - t * plotRect.height()
                                    : plotRect.top() + t * plotRect.height();

    painter->setPen(QPen(m_gridColor, 1, Qt::DotLine));
    painter->drawLine(QPointF(plotRect.left(), y), QPointF(plotRect.right(), y));

    painter->setPen(QPen(m_borderColor, 1));
    painter->drawLine(QPointF(tickLeftX, y), QPointF(tickRightX, y));

    const QString label  = formatTimeTick(v, step);
    const int labelWidth = fm.horizontalAdvance(label);
    const double textCy  = qBound(plotRect.top() + fm.ascent() * 0.5,
                                 y + fm.ascent() * 0.5,
                                 plotRect.bottom() + fm.ascent() * 0.5);
    painter->setPen(m_textColor);
    painter->drawText(QPointF(labelRight - labelWidth, textCy), label);
  }

  static auto& fonts = Misc::CommonFonts::instance();
  const QFont titleFont(fonts.widgetFont(0.91, true));
  const QFontMetrics titleFm(titleFont);

  const QString title = m_campbellMode ? m_yAxisTitle : QObject::tr("Time (s)");
  const double titleX =
    labelRight - fm.horizontalAdvance(QStringLiteral("00.00")) - 2 - titleFm.descent();
  const double titleY = plotRect.center().y();

  painter->save();
  painter->setFont(titleFont);
  painter->translate(titleX, titleY);
  painter->rotate(-90.0);
  painter->setPen(m_textColor);
  painter->drawText(QPointF(-titleFm.horizontalAdvance(title) * 0.5, 0), title);
  painter->restore();
}

void Widgets::Waterfall::drawMarkers(QPainter* painter, const QRectF& plotRect) const
{
  m_chipHitRects.clear();
  SS_ASSERT(painter != nullptr, return);
  SS_ASSERT(!m_markers.empty(), return);
  if (plotRect.isEmpty() || m_samplingRate <= 0)
    return;

  double wMin = 0.0;
  double wMax = 0.0;
  visibleFreqWindow(wMin, wMax);
  const double range = wMax - wMin;
  if (range <= 0.0)
    return;

  painter->save();
  painter->setClipRect(plotRect);
  painter->setFont(m_commonFonts.widgetFont(0.8, false));

  const QFontMetrics fm(painter->font());
  double rowEnd[kMarkerChipRows] = {-1e18, -1e18, -1e18};
  const double invRange          = 1.0 / range;
  for (std::size_t i = 0; i < m_markers.size(); ++i) {
    const auto& m      = m_markers[i];
    const int idx      = static_cast<int>(i);
    const bool band    = m.freqHi > m.freqLo;
    const bool spotlit = m_selectedMarker == idx;
    const bool dimmed  = m_selectedMarker >= 0 && !spotlit;
    const double xLo =
      plotRect.left() + (worldFromFreq(m.freqLo) - wMin) * invRange * plotRect.width();
    const double xHi =
      band ? plotRect.left() + (worldFromFreq(m.freqHi) - wMin) * invRange * plotRect.width() : xLo;
    if (xHi < plotRect.left() || xLo > plotRect.right())
      continue;

    QColor base = m.customColor.isValid() ? m.customColor : m_accentColor;
    if (m.state == 2)
      base = m_alarmColor;
    else if (m.state == 1)
      base = m_warningColor;

    painter->setOpacity(dimmed ? 0.22 : 1.0);

    if (band) {
      QColor fill = base;
      fill.setAlpha(spotlit ? 78 : (m.state > 0 ? 64 : 40));
      painter->fillRect(QRectF(xLo, plotRect.top(), xHi - xLo, plotRect.height()), fill);

      QColor edge = base;
      edge.setAlpha(spotlit ? 200 : 120);
      const double ew = spotlit ? 2.0 : 1.0;
      painter->fillRect(QRectF(xLo, plotRect.top(), ew, plotRect.height()), edge);
      painter->fillRect(QRectF(xHi - ew, plotRect.top(), ew, plotRect.height()), edge);
    } else {
      QColor line = base;
      line.setAlpha(spotlit ? 255 : (m.state > 0 ? 240 : 170));
      const double lw = spotlit ? 3.0 : 2.0;
      painter->fillRect(QRectF(xLo - lw * 0.5, plotRect.top(), lw, plotRect.height()), line);
    }

    const QString name = m.label.isEmpty() ? formatFreqTick(m.freqLo) : m.label;
    const QString text = QObject::tr("%1  %2 dB").arg(name, QString::number(m.peakDb, 'f', 1));
    drawMarkerChip(painter, plotRect, fm, rowEnd, idx, spotlit, (xLo + xHi) * 0.5, text, base);
  }

  painter->setOpacity(1.0);
  painter->restore();
}

void Widgets::Waterfall::drawMarkerChip(QPainter* painter,
                                        const QRectF& plotRect,
                                        const QFontMetrics& fm,
                                        double* rowEnd,
                                        const int markerIndex,
                                        const bool spotlit,
                                        double cx,
                                        const QString& text,
                                        const QColor& color) const
{
  SS_ASSERT(painter != nullptr, return);
  SS_ASSERT(rowEnd != nullptr, return);

  const double w = fm.horizontalAdvance(text) + 8;
  const double h = fm.height() + 4;
  const double x =
    qBound(plotRect.left() + 2, cx - w * 0.5, qMax(plotRect.left() + 2, plotRect.right() - w - 2));

  int row = 0;
  while (row < kMarkerChipRows - 1 && rowEnd[row] > x - 4)
    ++row;

  rowEnd[row]    = qMax(rowEnd[row], x + w);
  const double y = plotRect.top() + 4 + row * (h + 2);
  const QRectF chipRect(x, y, w, h);
  m_chipHitRects.emplace_back(markerIndex, chipRect);

  QColor bg = color;
  bg.setAlpha(spotlit ? 255 : 230);
  painter->setPen(Qt::NoPen);
  painter->setBrush(bg);
  painter->drawRoundedRect(chipRect, 3, 3);

  if (spotlit) {
    painter->setPen(QPen(m_textColor, 1.5));
    painter->setBrush(Qt::NoBrush);
    painter->drawRoundedRect(chipRect, 3, 3);
  }

  painter->setPen(m_innerBg);
  painter->drawText(QPointF(x + 4, y + 2 + fm.ascent()), text);
}

int Widgets::Waterfall::markerChipAt(const QPointF& pos) const
{
  for (auto it = m_chipHitRects.rbegin(); it != m_chipHitRects.rend(); ++it)
    if (it->second.contains(pos))
      return it->first;

  return -1;
}

void Widgets::Waterfall::drawCursor(QPainter* painter, const QRectF& plotRect) const
{
  if (plotRect.isEmpty() || !plotRect.contains(m_cursorPos))
    return;

  static auto& fonts = Misc::CommonFonts::instance();
  painter->setFont(fonts.widgetFont(0.83, false));
  painter->setRenderHint(QPainter::TextAntialiasing, true);

  const double cx = qBound(plotRect.left(), m_cursorPos.x(), plotRect.right());
  const double cy = qBound(plotRect.top(), m_cursorPos.y(), plotRect.bottom());

  painter->setPen(QPen(QColor(255, 255, 255, 178), 1));
  painter->drawLine(QPointF(cx, plotRect.top()), QPointF(cx, plotRect.bottom()));
  painter->drawLine(QPointF(plotRect.left(), cy), QPointF(plotRect.right(), cy));

  double freqHz = 0.0;
  double yVal   = 0.0;
  cursorReadoutValues(plotRect, cx, cy, freqHz, yVal);

  auto fmtFreq = [](double hz) -> QString {
    const double abs = std::fabs(hz);
    if (abs >= 1e6)
      return QString::number(hz / 1e6, 'f', 2) + QStringLiteral(" MHz");

    if (abs >= 1e3)
      return QString::number(hz / 1e3, 'f', 2) + QStringLiteral(" kHz");

    return QString::number(hz, 'f', 1) + QStringLiteral(" Hz");
  };
  auto fmtTime = [](double s) -> QString {
    if (s < 1.0)
      return QString::number(std::round(s * 1000.0), 'f', 0) + QStringLiteral(" ms");

    if (s >= 100.0)
      return QString::number(s, 'f', 0) + QStringLiteral(" s");

    return QString::number(s, 'f', 2) + QStringLiteral(" s");
  };

  const QString freqText = QObject::tr("Freq: %1").arg(fmtFreq(freqHz));
  const QString timeText =
    m_campbellMode ? QStringLiteral("%1: %2").arg(m_yAxisTitle, QString::number(yVal, 'f', 2))
                   : QObject::tr("Time: −%1").arg(fmtTime(yVal));

  drawCursorTooltip(painter, plotRect, cx, cy, freqText, timeText);
}

id Widgets::Waterfall::cursorReadoutValues(
  const QRectF& plotRect, double cx, double cy, double& freqHz, double& yVal) const
{
  double wMinX = 0.0;
  double wMaxX = 0.0;
  visibleFreqWindow(wMinX, wMaxX);
  freqHz = freqFromWorld(wMinX + (cx - plotRect.left()) / plotRect.width() * (wMaxX - wMinX));

  double yMinAxis = 0.0;
  double yMaxAxis = 1.0;
  if (m_campbellMode) {
    yMinAxis = m_yMin;
    yMaxAxis = m_yMax;
  } else {
    static auto& timer = Misc::TimerEvents::instance();
    const double fps   = timer.fps() > 0 ? timer.fps() : 24.0;
    yMinAxis           = 0.0;
    yMaxAxis           = m_historySize / fps;
  }
  const double yRange  = yMaxAxis - yMinAxis;
  const double srcWY   = yRange / m_yZoom;
  const double maxPanY = qMax(0.0, (yRange - srcWY) * 0.5);
  const double centerY = (yMinAxis + yMaxAxis) * 0.5 + qBound(-maxPanY, m_yPan * yRange, maxPanY);
  const double yMinV   = centerY - srcWY * 0.5;
  const double yMaxV   = centerY + srcWY * 0.5;

  const double tY = (cy - plotRect.top()) / plotRect.height();
  yVal = m_campbellMode ? (yMaxV - tY * (yMaxV - yMinV)) : (yMinV + tY * (yMaxV - yMinV));
}

id Widgets::Waterfall::drawCursorTooltip(QPainter* painter,
                                           const QRectF& plotRect,
                                           double cx,
                                           double cy,
                                           const QString& freqText,
                                           const QString& timeText) const
{
  const QFontMetrics fm(painter->font());
  const int padX = 8;
  const int padY = 5;
  const int gap  = 2;
  const int w = std::max(fm.horizontalAdvance(freqText), fm.horizontalAdvance(timeText)) + padX * 2;
  const int h = fm.height() * 2 + gap + padY * 2;

  double tx = cx + 12;
  double ty = cy + 12;
  if (tx + w > plotRect.right())
    tx = cx - 12 - w;

  if (ty + h > plotRect.bottom())
    ty = cy - 12 - h;

  tx = qBound(plotRect.left() + 2, tx, plotRect.right() - w - 2);
  ty = qBound(plotRect.top() + 2, ty, plotRect.bottom() - h - 2);

  const QRectF tipRect(tx, ty, w, h);
  painter->setPen(Qt::NoPen);
  painter->setBrush(QColor(0, 0, 0, 184));
  painter->drawRoundedRect(tipRect, 3, 3);

  painter->setPen(QColor(Qt::white));
  const double textBaseline = ty + padY + fm.ascent();
  painter->drawText(QPointF(tx + padX, textBaseline), freqText);
  painter->drawText(QPointF(tx + padX, textBaseline + fm.height() + gap), timeText);
}

static SerialStudio::DatasetOption pickHeadlineDatasetOption(int options)
{
  for (const auto cand : {SerialStudio::DatasetPlot,
                          SerialStudio::DatasetFFT,
                          SerialStudio::DatasetBar,
                          SerialStudio::DatasetGauge,
                          SerialStudio::DatasetCompass,
                          SerialStudio::DatasetLED,
                          SerialStudio::DatasetWaterfall,
                          SerialStudio::DatasetMeter}) {
    if (options & cand)
      return cand;
  }
  return SerialStudio::DatasetGeneric;
}

static QJsonArray buildDatasetDeleteWarnings(int groupId,
                                             bool isDryRun,
                                             const QJsonArray& renumbered,
                                             const QString& backupPath)
{
  QJsonArray warnings;
  if (isDryRun)
    warnings.append(
      QStringLiteral(
        "DRY RUN: no changes were written. Re-call without dryRun:true to commit. The "
        "renumbered[] array shows datasetId/uniqueId values that WOULD shift in groupId=%1.")
        .arg(groupId));

  else if (!renumbered.isEmpty())
    warnings.append(
      QStringLiteral(
        "datasetId values in groupId=%1 were renumbered; cached uniqueIds for the affected "
        "datasets are now stale -- re-read project state before further mutations.")
        .arg(groupId));

  if (!isDryRun && !backupPath.isEmpty())
    warnings.append(QStringLiteral(
      "Pre-mutation snapshot saved at backupPath; pass it to assistant.restore to undo."));

  return warnings;
}

API::CommandResponse API::Handlers::ProjectHandler::groupAdd(const QString& id,
                                                             const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("title"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: title"));
  }

  if (!params.contains(QStringLiteral("widgetType"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: widgetType"));
  }

  const QString title = params.value(QStringLiteral("title")).toString();
  if (title.isEmpty()) {
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("title cannot be empty"));
  }

  const int widget_type = params.value(QStringLiteral("widgetType")).toInt();
  if (widget_type < 0 || widget_type > static_cast<int>(SerialStudio::BarPanel)) {
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("Invalid widgetType: must be 0..%1 "
                     "(see GroupWidget enum: 0=DataGrid, 1=Accelerometer, "
                     "2=Gyroscope, 3=GPS, 4=MultiPlot, 5=NoGroupWidget, "
                     "6=Plot3D, 7=ImageView, 8=Painter, 9=WebView, 10=BarPanel)")
        .arg(static_cast<int>(SerialStudio::BarPanel)));
  }

  const auto widget         = static_cast<SerialStudio::GroupWidget>(widget_type);
  static auto& projectModel = DataModel::ProjectModel::instance();
  projectModel.addGroup(title, widget);

  QJsonObject result;
  result[QStringLiteral("title")]      = title;
  result[QStringLiteral("widgetType")] = widget_type;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::groupDelete(const QString& id,
                                                                const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("groupId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: groupId"));

  const int groupId    = params.value(QStringLiteral("groupId")).toInt();
  static auto& project = DataModel::ProjectModel::instance();
  const auto& groups   = project.groups();
  if (groupId < 0 || static_cast<size_t>(groupId) >= groups.size())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  const auto& targetGroup = groups[groupId];
  QJsonArray childDatasets;
  for (const auto& d : targetGroup.datasets) {
    QJsonObject row;
    row[Keys::DatasetId]         = d.datasetId;
    row[Keys::UniqueId]          = d.uniqueId;
    row[QStringLiteral("title")] = d.title;
    childDatasets.append(row);
  }

  QJsonObject deleted;
  deleted[QStringLiteral("groupId")]      = groupId;
  deleted[QStringLiteral("title")]        = targetGroup.title;
  deleted[QStringLiteral("widget")]       = targetGroup.widget;
  deleted[QStringLiteral("datasetCount")] = childDatasets.size();
  deleted[QStringLiteral("datasets")]     = childDatasets;

  const bool isDryRun = params.value(QStringLiteral("dryRun")).toBool(false);

  QJsonArray renumbered;
  for (const auto& g : groups) {
    if (g.groupId <= groupId)
      continue;

    QJsonObject row;
    row[QStringLiteral("oldGroupId")]   = g.groupId;
    row[QStringLiteral("newGroupId")]   = g.groupId - 1;
    row[QStringLiteral("title")]        = g.title;
    row[QStringLiteral("datasetCount")] = static_cast<int>(g.datasets.size());
    renumbered.append(row);
  }

  QString backupPath;
  qint64 preEpoch = 0;
  if (!isDryRun) {
    static auto& backupManager = Misc::BackupManager::instance();
    backupPath                 = backupManager.snapshot(QStringLiteral("pre-groupDelete"));
    preEpoch                   = captureProjectEpoch();
    project.deleteGroup(groupId);
  }

  QJsonObject result;
  if (isDryRun)
    result[QStringLiteral("dryRun")] = true;

  result[QStringLiteral("deleted")]    = deleted;
  result[QStringLiteral("renumbered")] = renumbered;
  if (!backupPath.isEmpty())
    result[QStringLiteral("backupPath")] = backupPath;

  QJsonArray warnings;
  if (isDryRun)
    warnings.append(QStringLiteral(
      "DRY RUN: no changes were written. Re-call without dryRun:true to commit. The "
      "renumbered[] array shows groupId values that WOULD shift; every dataset in those "
      "groups would have its uniqueId invalidated."));

  else if (!renumbered.isEmpty())
    warnings.append(QStringLiteral(
      "groupId values shifted after deletion; uniqueIds of every dataset in renumbered "
      "groups are now stale -- re-read project state before further mutations."));

  if (!isDryRun && !backupPath.isEmpty())
    warnings.append(QStringLiteral(
      "Pre-mutation snapshot saved at backupPath; pass it to assistant.restore to undo."));

  if (!warnings.isEmpty())
    result[QStringLiteral("warnings")] = warnings;

  if (!isDryRun)
    appendStaleProjectWarning(result, params, preEpoch);

  attachProjectEpoch(result);
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::groupDuplicate(const QString& id,
                                                                   const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("groupId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: groupId"));

  const int groupId    = params.value(QStringLiteral("groupId")).toInt();
  static auto& project = DataModel::ProjectModel::instance();
  const auto& groups   = project.groups();
  if (groupId < 0 || static_cast<size_t>(groupId) >= groups.size())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  project.duplicateGroup(groupId);

  QJsonObject result;
  result[QStringLiteral("groupId")]    = groupId;
  result[QStringLiteral("duplicated")] = true;
  return CommandResponse::makeSuccess(id, result);
}

QString API::Handlers::ProjectHandler::widgetForDatasetOptions(int options)
{
  if (options & SerialStudio::DatasetMeter)
    return QStringLiteral("meter");

  if (options & SerialStudio::DatasetCompass)
    return QStringLiteral("compass");

  if (options & SerialStudio::DatasetGauge)
    return QStringLiteral("gauge");

  if (options & SerialStudio::DatasetBar)
    return QStringLiteral("bar");

  return QString();
}

void API::Handlers::ProjectHandler::applyDatasetVisualizationFlags(DataModel::Dataset& d,
                                                                   int options)
{
  if (options & SerialStudio::DatasetPlot)
    d.plt = true;

  if (options & SerialStudio::DatasetFFT)
    d.fft = true;

  if (options & SerialStudio::DatasetLED)
    d.led = true;

  if (options & SerialStudio::DatasetWaterfall)
    d.waterfall = true;

  const QString widget = widgetForDatasetOptions(options);
  if (!widget.isEmpty())
    d.widget = widget;
}

API::CommandResponse API::Handlers::ProjectHandler::datasetAdd(const QString& id,
                                                               const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("groupId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: groupId"));

  if (!params.contains(QStringLiteral("options")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: options"));

  const int groupId = params.value(QStringLiteral("groupId")).toInt();
  const int options = params.value(QStringLiteral("options")).toInt();
  if (options < 0 || options > 0b11111111)
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Invalid options: must be 0-255 (bit flags)"));

  static auto& project = DataModel::ProjectModel::instance();
  const auto& groups   = project.groups();
  if (groupId < 0 || static_cast<size_t>(groupId) >= groups.size())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  SerialStudio::DatasetOption headline = SerialStudio::DatasetGeneric;
  for (const auto cand : {SerialStudio::DatasetPlot,
                          SerialStudio::DatasetFFT,
                          SerialStudio::DatasetBar,
                          SerialStudio::DatasetGauge,
                          SerialStudio::DatasetCompass,
                          SerialStudio::DatasetLED,
                          SerialStudio::DatasetWaterfall,
                          SerialStudio::DatasetMeter}) {
    if (options & cand) {
      headline = cand;
      break;
    }
  }

  project.setSelectedGroup(groups[groupId]);
  project.addDataset(headline);

  const int remaining = options & ~static_cast<int>(headline);
  const auto& post    = project.groups();
  const int newIndex  = static_cast<int>(post[groupId].datasets.size()) - 1;
  if (remaining != 0 && newIndex >= 0) {
    DataModel::Dataset d = post[groupId].datasets[newIndex];
    applyDatasetVisualizationFlags(d, remaining);
    project.updateDataset(groupId, newIndex, d, true);
  }

  QJsonObject result;
  result[QStringLiteral("groupId")] = groupId;
  result[QStringLiteral("options")] = options;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::datasetAddMany(const QString& id,
                                                                   const QJsonObject& params)
{
  constexpr int kMaxAddManyCount = 1024;

  for (const auto& key :
       {QStringLiteral("groupId"), QStringLiteral("count"), QStringLiteral("options")}) {
    if (!params.contains(key))
      return CommandResponse::makeError(
        id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: %1").arg(key));
  }

  const int groupId = params.value(QStringLiteral("groupId")).toInt();
  const int count   = params.value(QStringLiteral("count")).toInt();
  const int options = params.value(QStringLiteral("options")).toInt();

  if (count <= 0 || count > kMaxAddManyCount)
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("Invalid count: must be 1..%1 (got %2)")
        .arg(QString::number(kMaxAddManyCount), QString::number(count)));

  if (options < 0 || options > 0b11111111)
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Invalid options: must be 0-255 (bit flags)"));

  static auto& project = DataModel::ProjectModel::instance();
  const auto& groups   = project.groups();
  if (groupId < 0 || static_cast<size_t>(groupId) >= groups.size())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  const QString titlePattern = params.value(QStringLiteral("titlePattern")).toString();
  const int startNumber      = params.contains(QStringLiteral("startNumber"))
                               ? params.value(QStringLiteral("startNumber")).toInt()
                               : 1;
  const int startIndex       = params.contains(QStringLiteral("startIndex"))
                               ? params.value(QStringLiteral("startIndex")).toInt()
                               : -1;

  if (startIndex < -1)
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("Invalid startIndex: must be -1 (auto), 0, or 1+"));

  const auto headline     = pickHeadlineDatasetOption(options);
  const int remainingBits = options & ~static_cast<int>(headline);

  project.setAutoSaveSuspended(true);
  project.setSelectedGroup(groups[groupId]);

  QJsonArray created;
  for (int i = 0; i < count; ++i) {
    project.addDataset(headline);

    const auto& post   = project.groups();
    const int newIndex = static_cast<int>(post[groupId].datasets.size()) - 1;
    if (newIndex < 0)
      continue;

    DataModel::Dataset d = post[groupId].datasets[newIndex];
    if (remainingBits != 0)
      applyDatasetVisualizationFlags(d, remainingBits);

    if (!titlePattern.isEmpty()) {
      QString title = titlePattern;
      title.replace(QStringLiteral("{n}"), QString::number(startNumber + i));
      title.replace(QStringLiteral("{i}"), QString::number(i));
      d.title = title;
    }

    if (startIndex >= 0)
      d.index = startIndex + i;

    project.updateDataset(groupId, newIndex, d, true);

    QJsonObject entry;
    entry[QStringLiteral("groupId")] = groupId;
    entry[Keys::DatasetId]           = d.datasetId;
    entry[Keys::Title]               = d.title;
    entry[QStringLiteral("index")]   = d.index;
    entry[Keys::UniqueId]            = d.uniqueId;
    created.append(entry);
  }

  project.setAutoSaveSuspended(false);
  project.flushAutoSave();

  QJsonObject result;
  result[QStringLiteral("groupId")] = groupId;
  result[QStringLiteral("count")]   = created.size();
  result[QStringLiteral("created")] = created;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::datasetDelete(const QString& id,
                                                                  const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("groupId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: groupId"));

  if (!params.contains(Keys::DatasetId))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: datasetId"));

  const int groupId    = params.value(QStringLiteral("groupId")).toInt();
  const int datasetId  = params.value(Keys::DatasetId).toInt();
  static auto& project = DataModel::ProjectModel::instance();
  const auto& groups   = project.groups();
  if (groupId < 0 || static_cast<size_t>(groupId) >= groups.size())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  if (datasetId < 0 || static_cast<size_t>(datasetId) >= groups[groupId].datasets.size())
    return CommandResponse::makeError(id,
                                      ErrorCode::InvalidParam,
                                      QStringLiteral("Dataset id not found: %1 in group %2")
                                        .arg(QString::number(datasetId), QString::number(groupId)));

  const auto& targetGroup   = groups[groupId];
  const auto& targetDataset = targetGroup.datasets[datasetId];

  QJsonObject deleted;
  deleted[QStringLiteral("groupId")]    = groupId;
  deleted[QStringLiteral("groupTitle")] = targetGroup.title;
  deleted[Keys::DatasetId]              = datasetId;
  deleted[Keys::UniqueId]               = targetDataset.uniqueId;
  deleted[QStringLiteral("title")]      = targetDataset.title;
  if (!targetDataset.units.isEmpty())
    deleted[QStringLiteral("units")] = targetDataset.units;

  if (!targetDataset.transformCode.isEmpty()) {
    deleted[QStringLiteral("hadTransform")]       = true;
    deleted[QStringLiteral("transformByteCount")] = targetDataset.transformCode.size();
  }

  const bool isDryRun = params.value(QStringLiteral("dryRun")).toBool(false);

  QJsonArray renumbered;
  for (const auto& d : targetGroup.datasets) {
    if (d.datasetId <= datasetId)
      continue;

    QJsonObject row;
    row[QStringLiteral("groupId")]      = groupId;
    row[QStringLiteral("oldDatasetId")] = d.datasetId;
    row[QStringLiteral("newDatasetId")] = d.datasetId - 1;
    row[Keys::UniqueId]                 = d.uniqueId;
    row[QStringLiteral("title")]        = d.title;
    renumbered.append(row);
  }

  QString backupPath;
  qint64 preEpoch = 0;
  if (!isDryRun) {
    static auto& backupManager = Misc::BackupManager::instance();
    backupPath                 = backupManager.snapshot(QStringLiteral("pre-datasetDelete"));
    preEpoch                   = captureProjectEpoch();
    project.deleteDataset(groupId, datasetId);
  }

  QJsonObject result;
  if (isDryRun)
    result[QStringLiteral("dryRun")] = true;

  result[QStringLiteral("deleted")]    = deleted;
  result[QStringLiteral("renumbered")] = renumbered;
  if (!backupPath.isEmpty())
    result[QStringLiteral("backupPath")] = backupPath;

  const auto warnings = buildDatasetDeleteWarnings(groupId, isDryRun, renumbered, backupPath);
  if (!warnings.isEmpty())
    result[QStringLiteral("warnings")] = warnings;

  if (!isDryRun)
    appendStaleProjectWarning(result, params, preEpoch);

  attachProjectEpoch(result);
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::datasetDuplicate(const QString& id,
                                                                     const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("groupId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: groupId"));

  if (!params.contains(Keys::DatasetId))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: datasetId"));

  const int groupId    = params.value(QStringLiteral("groupId")).toInt();
  const int datasetId  = params.value(Keys::DatasetId).toInt();
  static auto& project = DataModel::ProjectModel::instance();
  const auto& groups   = project.groups();
  if (groupId < 0 || static_cast<size_t>(groupId) >= groups.size())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  if (datasetId < 0 || static_cast<size_t>(datasetId) >= groups[groupId].datasets.size())
    return CommandResponse::makeError(id,
                                      ErrorCode::InvalidParam,
                                      QStringLiteral("Dataset id not found: %1 in group %2")
                                        .arg(QString::number(datasetId), QString::number(groupId)));

  project.duplicateDataset(groupId, datasetId);

  QJsonObject result;
  result[QStringLiteral("groupId")]    = groupId;
  result[Keys::DatasetId]              = datasetId;
  result[QStringLiteral("duplicated")] = true;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::datasetSetOption(const QString& id,
                                                                     const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("groupId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: groupId"));

  if (!params.contains(Keys::DatasetId))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: datasetId"));

  if (!params.contains(QStringLiteral("option")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: option"));

  if (!params.contains(QStringLiteral("enabled")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: enabled"));

  const int groupId   = params.value(QStringLiteral("groupId")).toInt();
  const int datasetId = params.value(Keys::DatasetId).toInt();
  const bool enabled  = params.value(QStringLiteral("enabled")).toBool();

  int option                  = 0;
  const QJsonValue optionJson = params.value(QStringLiteral("option"));
  if (optionJson.isString()) {
    option = API::EnumLabels::datasetOptionFromSlug(optionJson.toString());
    if (option == 0)
      return CommandResponse::makeError(
        id,
        ErrorCode::InvalidParam,
        QStringLiteral("Unknown option slug '%1'. Use one of: plot, fft, bar, gauge, "
                       "compass, led, waterfall.")
          .arg(optionJson.toString()));
  } else {
    option = optionJson.toInt();
  }

  static auto& project = DataModel::ProjectModel::instance();
  const auto& groups   = project.groups();
  if (groupId < 0 || static_cast<size_t>(groupId) >= groups.size())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  if (datasetId < 0 || static_cast<size_t>(datasetId) >= groups[groupId].datasets.size())
    return CommandResponse::makeError(id,
                                      ErrorCode::InvalidParam,
                                      QStringLiteral("Dataset id not found: %1 in group %2")
                                        .arg(QString::number(datasetId), QString::number(groupId)));

  project.setSelectedDataset(groups[groupId].datasets[datasetId]);
  project.changeDatasetOption(static_cast<SerialStudio::DatasetOption>(option), enabled);

  QJsonObject result;
  result[QStringLiteral("groupId")]    = groupId;
  result[Keys::DatasetId]              = datasetId;
  result[QStringLiteral("option")]     = option;
  result[QStringLiteral("optionSlug")] = API::EnumLabels::datasetOptionSlug(option);
  result[QStringLiteral("enabled")]    = enabled;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::datasetSetOptions(const QString& id,
                                                                      const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("groupId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: groupId"));

  if (!params.contains(Keys::DatasetId))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: datasetId"));

  if (!params.contains(QStringLiteral("options")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: options"));

  const int groupId   = params.value(QStringLiteral("groupId")).toInt();
  const int datasetId = params.value(Keys::DatasetId).toInt();

  int options                  = 0;
  const QJsonValue optionsJson = params.value(QStringLiteral("options"));
  if (optionsJson.isArray()) {
    QStringList slugs;
    for (const auto& v : optionsJson.toArray())
      slugs.append(v.toString());

    options = API::EnumLabels::datasetOptionsSlugsToBits(slugs);
  } else {
    options = optionsJson.toInt();
  }

  static auto& project = DataModel::ProjectModel::instance();
  const auto& groups   = project.groups();
  if (groupId < 0 || static_cast<size_t>(groupId) >= groups.size())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  if (datasetId < 0 || static_cast<size_t>(datasetId) >= groups[groupId].datasets.size())
    return CommandResponse::makeError(id,
                                      ErrorCode::InvalidParam,
                                      QStringLiteral("Dataset id not found: %1 in group %2")
                                        .arg(QString::number(datasetId), QString::number(groupId)));

  DataModel::Dataset d = groups[groupId].datasets[datasetId];
  d.plt                = (options & SerialStudio::DatasetPlot) != 0;
  d.fft                = (options & SerialStudio::DatasetFFT) != 0;
  d.led                = (options & SerialStudio::DatasetLED) != 0;
  d.waterfall          = (options & SerialStudio::DatasetWaterfall) != 0;

  const QString chosen = widgetForDatasetOptions(options);
  const bool wasOneOf  = d.widget == QStringLiteral("bar") || d.widget == QStringLiteral("gauge")
                     || d.widget == QStringLiteral("compass")
                     || d.widget == QStringLiteral("meter");
  if (!chosen.isEmpty())
    d.widget = chosen;
  else if (wasOneOf)
    d.widget = QString();

  project.updateDataset(groupId, datasetId, d, true);

  QJsonArray slugs;
  for (const auto& s : API::EnumLabels::datasetOptionsBitsToSlugs(options))
    slugs.append(s);

  QJsonObject result;
  result[QStringLiteral("groupId")]      = groupId;
  result[Keys::DatasetId]                = datasetId;
  result[QStringLiteral("options")]      = options;
  result[QStringLiteral("optionsSlugs")] = slugs;
  return CommandResponse::makeSuccess(id, result);
}

void applySimpleAlarmFields(DataModel::Dataset& d,
                            std::optional<bool> enabled,
                            std::optional<double> low,
                            std::optional<double> high)
{
  bool curEnabled       = !d.alarmBands.empty();
  double curLow         = std::numeric_limits<double>::quiet_NaN();
  double curHigh        = std::numeric_limits<double>::quiet_NaN();
  const double rangeMin = qMin(d.wgtMin, d.wgtMax);
  const double rangeMax = qMax(d.wgtMin, d.wgtMax);
  for (const auto& b : d.alarmBands) {
    if (static_cast<int>(b.severity) < 2)
      continue;

    const double bLo = qMin(b.min, b.max);
    const double bHi = qMax(b.min, b.max);
    if (qFuzzyCompare(1.0 + bLo, 1.0 + rangeMin) && bHi < rangeMax)
      curLow = bHi;
    else if (bLo > rangeMin && qFuzzyCompare(1.0 + bHi, 1.0 + rangeMax))
      curHigh = bLo;
  }

  const bool useEnabled = enabled.value_or(curEnabled);
  const double useLow   = low.value_or(curLow);
  const double useHigh  = high.value_or(curHigh);

  d.alarmBands.clear();
  if (!useEnabled)
    return;

  const double range = rangeMax - rangeMin;
  if (range <= 0)
    return;

  const double lo = std::isnan(useLow) ? rangeMin + range * 0.20 : useLow;
  const double hi = std::isnan(useHigh) ? rangeMin + range * 0.80 : useHigh;
  if (lo > rangeMin && lo < rangeMax) {
    DataModel::AlarmBand band;
    band.min      = rangeMin;
    band.max      = lo;
    band.severity = DataModel::AlarmSeverity::Warning;
    d.alarmBands.push_back(band);
  }

  if (hi > rangeMin && hi < rangeMax && hi > lo) {
    DataModel::AlarmBand band;
    band.min      = hi;
    band.max      = rangeMax;
    band.severity = DataModel::AlarmSeverity::Warning;
    d.alarmBands.push_back(band);
  }
}

static void appendUnknownFieldsWarning(QJsonObject& result,
                                       const QJsonObject& params,
                                       const QSet<QString>& consumed,
                                       const QString& command)
{
  QJsonArray unknownFields;
  for (const auto& key : params.keys())
    if (!consumed.contains(key))
      unknownFields.append(key);

  if (unknownFields.isEmpty())
    return;

  QJsonArray warnings;
  if (result.contains(QStringLiteral("warnings")))
    warnings = result.value(QStringLiteral("warnings")).toArray();

  QJsonObject w;
  w[QStringLiteral("code")]   = QStringLiteral("unknown_field");
  w[QStringLiteral("fields")] = unknownFields;
  w[QStringLiteral("message")] =
    QStringLiteral("These fields were ignored because they are not patchable via %1. "
                   "Call meta.describeCommand for the list of writable fields, "
                   "or check your spelling.")
      .arg(command);
  warnings.append(w);

  result[QStringLiteral("warnings")] = warnings;
}

API::CommandResponse API::Handlers::ProjectHandler::groupUpdate(const QString& id,
                                                                const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("groupId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: groupId"));

  const int groupId    = params.value(QStringLiteral("groupId")).toInt();
  static auto& project = DataModel::ProjectModel::instance();
  const auto& groups   = project.groups();
  if (groupId < 0 || static_cast<size_t>(groupId) >= groups.size())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  DataModel::Group g = groups[groupId];
  bool rebuildTree   = false;
  QSet<QString> consumed{QStringLiteral("groupId")};
  const auto identityKeyCount = consumed.size();

  const auto take = [&](const QString& key) -> bool {
    if (!params.contains(key))
      return false;

    consumed.insert(key);
    return true;
  };

  if (take(QStringLiteral("title"))) {
    g.title     = params.value(QStringLiteral("title")).toString();
    rebuildTree = true;
  }
  if (take(QStringLiteral("widget"))) {
    g.widget    = params.value(QStringLiteral("widget")).toString();
    rebuildTree = true;
  }
  if (take(QStringLiteral("columns")))
    g.columns = params.value(QStringLiteral("columns")).toInt();

  if (take(Keys::SourceId))
    g.sourceId = params.value(Keys::SourceId).toInt();

  if (take(QStringLiteral("painterCode")))
    g.painterCode = params.value(QStringLiteral("painterCode")).toString();

  if (consumed.size() > identityKeyCount)
    rebuildTree = true;

  project.updateGroup(groupId, g, rebuildTree);

  QJsonObject result;
  result[QStringLiteral("groupId")] = groupId;
  result[QStringLiteral("updated")] = true;
  appendUnknownFieldsWarning(result, params, consumed, QStringLiteral("project.group.update"));
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::datasetUpdate(const QString& id,
                                                                  const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("groupId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: groupId"));

  if (!params.contains(Keys::DatasetId))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: datasetId"));

  const int groupId    = params.value(QStringLiteral("groupId")).toInt();
  const int datasetId  = params.value(Keys::DatasetId).toInt();
  static auto& project = DataModel::ProjectModel::instance();
  const auto& groups   = project.groups();
  if (groupId < 0 || static_cast<size_t>(groupId) >= groups.size())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  const auto& datasets = groups[groupId].datasets;
  if (datasetId < 0 || static_cast<size_t>(datasetId) >= datasets.size())
    return CommandResponse::makeError(id,
                                      ErrorCode::InvalidParam,
                                      QStringLiteral("Dataset id not found: %1 in group %2")
                                        .arg(QString::number(datasetId), QString::number(groupId)));

  DataModel::Dataset d = datasets[datasetId];
  bool rebuildTree     = false;
  QSet<QString> consumed{
    QStringLiteral("groupId"), Keys::DatasetId, QStringLiteral("expectedProjectEpoch")};
  const auto identityKeyCount = consumed.size();
  const QString err           = applyDatasetUpdateParams(d, params, rebuildTree, consumed);
  if (!err.isEmpty())
    return CommandResponse::makeError(id, ErrorCode::InvalidParam, err);

  if (consumed.size() > identityKeyCount)
    rebuildTree = true;

  const auto preEpoch = captureProjectEpoch();
  project.updateDataset(groupId, datasetId, d, rebuildTree);

  QJsonObject result;
  result[QStringLiteral("groupId")] = groupId;
  result[Keys::DatasetId]           = datasetId;
  result[QStringLiteral("updated")] = true;

  appendUnknownFieldsWarning(result, params, consumed, QStringLiteral("project.dataset.update"));
  appendStaleProjectWarning(result, params, preEpoch);
  attachProjectEpoch(result);

  if (!d.transformCode.isEmpty() && d.transformLanguage != -1
      && d.transformLanguage != SerialStudio::Expression) {
    const auto warning = detectLanguageMismatch(d.transformCode, d.transformLanguage);
    if (!warning.isEmpty())
      result[QStringLiteral("warning")] = warning;
  }

  if (!d.transformCode.isEmpty() && !d.virtual_ && d.index <= 0)
    result[QStringLiteral("hint")] =
      QStringLiteral("transformCode set but virtual=false and index<=0; if this "
                     "dataset has no slot in the parser output array, set "
                     "virtual=true (next call: project.dataset.update{virtual:true}).");

  return CommandResponse::makeSuccess(id, result);
}

