{
  m_uart.reset();
  m_network.reset();
  m_bluetoothLE.reset();
#ifdef BUILD_COMMERCIAL
  m_hid.reset();
  m_usb.reset();
  m_mqtt.reset();
  m_audio.reset();
  m_opcUa.reset();
  m_canBus.reset();
  m_modbus.reset();
  m_process.reset();
#endif
}

void IO::DriverUiRegistry::setupExternalConnections()
{
  m_uart->setupExternalConnections();
#ifdef BUILD_COMMERCIAL
  m_usb->setupExternalConnections();
  m_opcUa->setupExternalConnections();
  m_canBus->setupExternalConnections();
  m_modbus->setupExternalConnections();
#endif
}

void IO::DriverUiRegistry::detachFrom(QObject* receiver) const
{
  SS_ASSERT(receiver != nullptr, return);

  for (auto* driver : all())
    QObject::disconnect(driver, nullptr, receiver, nullptr);
}

std::vector<IO::HAL_Driver*> IO::DriverUiRegistry::all() const
{
  std::vector<HAL_Driver*> drivers;
  drivers.reserve(kMaxUiDrivers);

  const auto add = [&drivers](HAL_Driver* driver) {
    if (driver)
      drivers.push_back(driver);
  };

  add(m_uart.get());
  add(m_network.get());
  add(m_bluetoothLE.get());
#ifdef BUILD_COMMERCIAL
  add(m_hid.get());
  add(m_usb.get());
  add(m_mqtt.get());
  add(m_audio.get());
  add(m_opcUa.get());
  add(m_canBus.get());
  add(m_modbus.get());
  add(m_process.get());
#endif

  SS_ASSERT(drivers.size() <= kMaxUiDrivers, return drivers);
  return drivers;
}

IO::HAL_Driver* IO::DriverUiRegistry::forBusType(SerialStudio::BusType type) const noexcept
{
  switch (type) {
    case SerialStudio::BusType::UART:
      return m_uart.get();
    case SerialStudio::BusType::Network:
      return m_network.get();
    case SerialStudio::BusType::BluetoothLE:
      return m_bluetoothLE.get();
#ifdef BUILD_COMMERCIAL
    case SerialStudio::BusType::Audio:
      return m_audio.get();
    case SerialStudio::BusType::ModBus:
      return m_modbus.get();
    case SerialStudio::BusType::CanBus:
      return m_canBus.get();
    case SerialStudio::BusType::RawUsb:
      return m_usb.get();
    case SerialStudio::BusType::HidDevice:
      return m_hid.get();
    case SerialStudio::BusType::Process:
      return m_process.get();
    case SerialStudio::BusType::Mqtt:
      return m_mqtt.get();
    case SerialStudio::BusType::OpcUa:
      return m_opcUa.get();
#endif
    default:
      return nullptr;
  }
}

static QString knownUuidName(const QBluetoothUuid& uuid)
{
  const QString key = uuid.toString(QUuid::WithoutBraces).toUpper();
  for (const auto& entry : BLE_KNOWN_UUIDS)
    if (key == QLatin1StringView(entry.uuid))
      return QString::fromUtf8(entry.name);

  return {};
}

static QString rawUuidName(const QBluetoothUuid& uuid)
{
  bool ok           = false;
  const quint16 u16 = uuid.toUInt16(&ok);
  if (ok)
    return QStringLiteral("0x")
         + QString::number(u16, 16).rightJustified(4, QLatin1Char('0')).toUpper();

  return uuid.toString(QUuid::WithoutBraces).toUpper();
}

QString bleServiceName(const QBluetoothUuid& uuid)
{
  const QString known = knownUuidName(uuid);
  if (!known.isEmpty())
    return known;

  bool ok           = false;
  const quint16 u16 = uuid.toUInt16(&ok);
  if (ok) {
    const QString sig =
      QBluetoothUuid::serviceClassToString(static_cast<QBluetoothUuid::ServiceClassUuid>(u16));
    if (!sig.isEmpty())
      return sig;
  }

  return rawUuidName(uuid);
}

QBluetoothUuid bleUuidFromString(const QString& uuid)
{
  QString text = uuid.trimmed();
  if (text.startsWith(QLatin1String("0x"), Qt::CaseInsensitive))
    text.remove(0, 2);

  if (text.size() == 4 || text.size() == 8) {
    bool ok           = false;
    const quint32 hex = text.toUInt(&ok, 16);
    if (ok) {
      if (text.size() == 4)
        return QBluetoothUuid(static_cast<quint16>(hex));

      return QBluetoothUuid(hex);
    }
  }

  return QBluetoothUuid(text);
}

QString bleCharacteristicName(const QLowEnergyCharacteristic& characteristic)
{
  const QString qtName = characteristic.name().simplified();
  if (!qtName.isEmpty())
    return qtName;

  const QBluetoothUuid uuid = characteristic.uuid();
  const QString known       = knownUuidName(uuid);
  if (!known.isEmpty())
    return known;

  bool ok           = false;
  const quint16 u16 = uuid.toUInt16(&ok);
  if (ok) {
    const QString sig =
      QBluetoothUuid::characteristicToString(static_cast<QBluetoothUuid::CharacteristicType>(u16));
    if (!sig.isEmpty())
      return sig;
  }

  return rawUuidName(uuid);
}

void Misc::PluginRunner::appendOutput(const QString& id, const QString& text)
{
  m_output[id] += text;
  Q_EMIT outputChanged(id);
}

bool Misc::PluginRunner::start(const QString& id,
                               const QString& pluginDir,
                               const QString& runtime,
                               const QString& entryPath,
                               const QString& title,
                               const bool terminal,
                               const bool hasPipDeps)
{
  SS_ASSERT(!id.isEmpty(), return false);
  SS_ASSERT(!isRunning(id), return false);

  auto* process = new QProcess(this);
  process->setWorkingDirectory(pluginDir);
  process->setProcessEnvironment(buildEnvironment());

  if (terminal)
    process->setProcessChannelMode(QProcess::ForwardedChannels);
  else {
    process->setProcessChannelMode(QProcess::MergedChannels);
    process->setStandardInputFile(QProcess::nullDevice());
  }

  m_output.insert(id, QString());
  wireProcess(process, id);
  startProcess(process, runtime, entryPath, terminal);

  if (!process->waitForStarted(kTerminateGraceMs)) {
    appendOutput(id, QStringLiteral("[Error] Failed to start: ") + process->errorString() + "\n");
    delete process;
    return false;
  }

  const auto mode = terminal ? QStringLiteral(" (terminal)") : QString();
  appendOutput(
    id, QStringLiteral("[Started] PID ") + QString::number(process->processId()) + mode + "\n");

  if (hasPipDeps && !QDir(pluginDir + "/venv").exists())
    appendOutput(
      id, QStringLiteral("[Setup] Installing required packages -- this may take a moment...\n"));

  m_processes.insert(id, process);

  QVariantMap entry;
  entry.insert("id", id);
  entry.insert("title", title);
  m_running.append(entry);
  Q_EMIT runningChanged();
  return true;
}

void Misc::PluginRunner::stop(const QString& id)
{
  auto it = m_processes.find(id);
  if (it == m_processes.end())
    return;

  static auto& dashboard = UI::Dashboard::instance();
  if (dashboard.available())
    m_userClosed.insert(id);

  auto* process = it.value();
  appendOutput(id, QStringLiteral("[Stopping...]\n"));

  process->disconnect(this);
  m_processes.erase(it);

  process->terminate();
  if (!process->waitForFinished(kTerminateGraceMs))
    process->kill();

  const auto remaining = QString::fromUtf8(process->readAll());
  if (!remaining.isEmpty())
    appendOutput(id, remaining);

  appendOutput(id, QStringLiteral("[Stopped]\n"));
  delete process;

  forget(id);
  Q_EMIT runningChanged();
}

void Misc::PluginRunner::stopAll()
{
  const auto ids = m_processes.keys();
  m_settings.setValue("RunningPlugins", QStringList(ids));

  for (const auto& id : ids) {
    auto* process = m_processes.value(id);
    if (!process)
      continue;

    process->disconnect(this);
    process->terminate();
    if (!process->waitForFinished(kTerminateGraceMs))
      process->kill();

    delete process;
  }

  m_processes.clear();
  m_running.clear();
  Q_EMIT runningChanged();
}

void Misc::PluginRunner::onFinished(const QString& id)
{
  auto it = m_processes.find(id);
  if (it == m_processes.end())
    return;

  static auto& dashboard = UI::Dashboard::instance();
  if (dashboard.available())
    m_userClosed.insert(id);

  auto* process        = it.value();
  const auto remaining = QString::fromUtf8(process->readAll());
  if (!remaining.isEmpty())
    appendOutput(id, remaining);

  appendOutput(id, QStringLiteral("[Exited with code %1]\n").arg(process->exitCode()));

  m_processes.erase(it);
  process->deleteLater();

  forget(id);
  Q_EMIT runningChanged();
}

void Misc::PluginRunner::forget(const QString& id)
{
  for (int i = 0; i < m_running.count(); ++i) {
    if (m_running.at(i).toMap().value("id").toString() == id) {
      m_running.removeAt(i);
      return;
    }
  }
}

void Misc::PluginRunner::wireProcess(QProcess* process, const QString& id)
{
  SS_ASSERT(process != nullptr, return);

  connect(process, &QProcess::readyRead, this, [this, id, process]() {
    m_output[id] += QString::fromUtf8(process->readAll());

    auto& buf = m_output[id];
    if (buf.size() > kMaxOutputChars)
      buf = buf.right(kKeptOutputChars);

    Q_EMIT outputChanged(id);
  });

  connect(process,
          QOverload<int, QProcess::ExitStatus>::of(&QProcess::finished),
          this,
          [this, id]() { onFinished(id); });

  connect(process, &QProcess::errorOccurred, this, [this, id](QProcess::ProcessError err) {
    Q_UNUSED(err)
    appendOutput(id, QStringLiteral("[Error] Plugin failed to start or crashed.\n"));
  });
}

QProcessEnvironment Misc::PluginRunner::buildEnvironment() const
{
  auto env  = QProcessEnvironment::systemEnvironment();
  auto path = env.value("PATH");
#ifdef Q_OS_MACOS
  const QStringList extraPaths = {
    "/opt/homebrew/bin",
    "/opt/homebrew/sbin",
    "/usr/local/bin",
    QDir::homePath() + "/.local/bin",
  };

  for (const auto& p : extraPaths)
    if (!path.contains(p) && QDir(p).exists())
      path = p + ":" + path;
#endif
  env.insert("PATH", path);
  env.insert("TK_SILENCE_DEPRECATION", "1");
  return env;
}

void Misc::PluginRunner::startProcess(QProcess* process,
                                      const QString& runtime,
                                      const QString& entryPath,
                                      const bool terminal)
{
  const bool isNative = runtime.isEmpty();
#ifndef Q_OS_WIN
  if (isNative)
    QFile::setPermissions(
      entryPath, QFile::permissions(entryPath) | QFileDevice::ExeUser | QFileDevice::ExeGroup);
#endif

  if (!terminal) {
    if (isNative)
      process->start(entryPath);
    else
      process->start(runtime, {entryPath});

    return;
  }

#ifdef Q_OS_MACOS
  Q_UNUSED(isNative)
  process->start("open", {"-a", "Terminal", entryPath});
#elif defined(Q_OS_WIN)
  if (isNative)
    process->start("cmd.exe", {"/c", "start", "cmd.exe", "/k", entryPath});
  else
    process->start("cmd.exe", {"/c", "start", "cmd.exe", "/k", runtime, entryPath});
#else
  const QStringList terms = {
    "x-terminal-emulator", "gnome-terminal", "konsole", "xfce4-terminal", "xterm"};
  for (const auto& term : terms) {
    if (QStandardPaths::findExecutable(term).isEmpty())
      continue;

    if (isNative)
      process->start(term, {"--", entryPath});
    else
      process->start(term, {"--", runtime, entryPath});

    return;
  }

  if (isNative)
    process->start(entryPath);
  else
    process->start(runtime, {entryPath});
#endif
}

void Sessions::DatabaseManager::createSchema(QSqlQuery& q)
{
  createSchemaSessionTables(q);
  migrateColumnsTable(q);
  migrateSessionsTable(q);
  createSchemaSampleTables(q);
  createSchemaStreamTables(q);
  createSchemaBlockTable(q);
  createSchemaTagTables(q);
  createSchemaProjectMetadata(q);
  createSchemaVerifications(q);
  q.exec(QStringLiteral("PRAGMA user_version = %1").arg(kUserVersion));
}

void Sessions::DatabaseManager::migrateColumnsTable(QSqlQuery& q)
{
  auto columnExists = [&q](const QString& column) {
    if (!q.exec(QStringLiteral("PRAGMA table_info(\"columns\")"))) {
      qWarning() << "[Sessions] PRAGMA table_info failed:" << q.lastError().text();
      return false;
    }
    while (q.next())
      if (q.value(1).toString().compare(column, Qt::CaseInsensitive) == 0)
        return true;

    return false;
  };

  if (!columnExists(QStringLiteral("source_id"))) {
    if (!q.exec("ALTER TABLE \"columns\" ADD COLUMN source_id INTEGER NOT NULL DEFAULT 0"))
      qWarning() << "[Sessions] ALTER add source_id failed:" << q.lastError().text();
  }

  if (!columnExists(QStringLiteral("source_title"))) {
    if (!q.exec("ALTER TABLE \"columns\" ADD COLUMN source_title TEXT NOT NULL DEFAULT ''"))
      qWarning() << "[Sessions] ALTER add source_title failed:" << q.lastError().text();
  }
}

void Sessions::DatabaseManager::migrateSessionsTable(QSqlQuery& q)
{
  auto columnExists = [&q](const QString& column) {
    if (!q.exec(QStringLiteral("PRAGMA table_info(\"sessions\")"))) {
      qWarning() << "[Sessions] PRAGMA table_info failed:" << q.lastError().text();
      return false;
    }
    while (q.next())
      if (q.value(1).toString().compare(column, Qt::CaseInsensitive) == 0)
        return true;

    return false;
  };

  static constexpr struct {
    const char* name;
    const char* type;
  } kColumns[] = {
    {     "raw_sha256",    "TEXT"},
    {"readings_sha256",    "TEXT"},
    {    "app_version",    "TEXT"},
    { "capture_format", "INTEGER"},
    {    "repro_class",    "TEXT"},
    { "frames_dropped", "INTEGER"},
    { "overflow_bytes", "INTEGER"},
    {  "stream_sha256",    "TEXT"},
    {     "view_state",    "TEXT"},
  };

  for (const auto& col : kColumns) {
    if (columnExists(QLatin1String(col.name)))
      continue;

    const auto sql = QStringLiteral("ALTER TABLE \"sessions\" ADD COLUMN %1 %2")
                       .arg(QLatin1String(col.name), QLatin1String(col.type));
    if (!q.exec(sql))
      qWarning() << "[Sessions] ALTER add" << col.name << "failed:" << q.lastError().text();
  }
}

void Sessions::DatabaseManager::createSchemaTagTables(QSqlQuery& q)
{
  q.exec("CREATE TABLE IF NOT EXISTS tags ("
         "  tag_id INTEGER PRIMARY KEY AUTOINCREMENT,"
         "  label  TEXT NOT NULL UNIQUE COLLATE NOCASE"
         ")");

  q.exec("CREATE TABLE IF NOT EXISTS session_tags ("
         "  session_id INTEGER NOT NULL,"
         "  tag_id     INTEGER NOT NULL,"
         "  PRIMARY KEY (session_id, tag_id)"
         ") WITHOUT ROWID");
}

void Sessions::DatabaseManager::createSchemaProjectMetadata(QSqlQuery& q)
{
  q.exec("CREATE TABLE IF NOT EXISTS project_metadata ("
         "  key   TEXT PRIMARY KEY,"
         "  value TEXT NOT NULL"
         ") WITHOUT ROWID");
}

void Sessions::DatabaseManager::createSchemaVerifications(QSqlQuery& q)
{
  q.exec("CREATE TABLE IF NOT EXISTS verifications ("
         "  verification_id INTEGER PRIMARY KEY AUTOINCREMENT,"
         "  session_id      INTEGER NOT NULL REFERENCES sessions,"
         "  verified_at     TEXT NOT NULL,"
         "  app_version     TEXT NOT NULL,"
         "  verdict         TEXT NOT NULL,"
         "  detail_json     TEXT"
         ")");
  q.exec("CREATE INDEX IF NOT EXISTS idx_verifications_session "
         "ON verifications (session_id, verification_id)");
}

static QVariantMap childFailureReport(const QString& code,
                                      int exitCode,
                                      const QByteArray& stderrData)
{
  static const struct {
    const char* code;
    const char* error;
    const char* hint;
  } kFailures[] = {
    {  "child-spawn-failed",
     "The check could not be started.",                                               "Restart Serial Studio and try again."        },
    {       "child-crashed",
     "The check stopped unexpectedly.", "Try again. If this keeps happening, please report it and include the session file."        },
    {"child-output-invalid",
     "The check did not return a readable result.",                                                "Try again. If this keeps happening, other software on this computer may be "
                                                "interfering with Serial Studio."},
  };

  QVariantMap map;
  map.insert(QStringLiteral("verdict"), QStringLiteral("error"));
  map.insert(QStringLiteral("errorCode"), code);
  map.insert(QStringLiteral("exitCode"), exitCode);
  for (const auto& entry : kFailures) {
    if (code == QLatin1String(entry.code)) {
      map.insert(QStringLiteral("error"), QString::fromLatin1(entry.error));
      map.insert(QStringLiteral("hint"), QString::fromLatin1(entry.hint));
      break;
    }
  }

  const QString tail = QString::fromUtf8(stderrData.right(kStderrTailBytes)).trimmed();
  if (!tail.isEmpty())
    map.insert(QStringLiteral("stderrTail"), tail);

  return map;
}

static bool writeCandidateSnapshot(const QString& path)
{
  static auto& project = DataModel::ProjectModel::instance();
  const auto json      = QJsonDocument(project.serializeToJson()).toJson(QJsonDocument::Compact);

  QFile file(path);
  if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate) || file.write(json) != json.size()) {
    file.close();
    QFile::remove(path);
    return false;
  }

  return true;
}

static void countSweepVerdict(
  const QString& verdict, int& passed, int& drifted, int& notVerifiable, int& failed)
{
  if (verdict == QLatin1String("identical"))
    ++passed;
  else if (verdict.endsWith(QLatin1String("-drift")))
    ++drifted;
  else if (verdict == QLatin1String("not_verifiable"))
    ++notVerifiable;
  else
    ++failed;
}

static QVariantMap readChildVerdict(QProcess* process,
                                    int exitCode,
                                    QProcess::ExitStatus status,
                                    bool& ok)
{
  SS_ASSERT(process != nullptr, return QVariantMap());

  const auto doc = QJsonDocument::fromJson(process->readAllStandardOutput());
  ok             = status == QProcess::NormalExit && doc.isObject();
  if (ok)
    return doc.object().toVariantMap();

  return childFailureReport(status != QProcess::NormalExit ? QStringLiteral("child-crashed")
                                                           : QStringLiteral("child-output-invalid"),
                            exitCode,
                            process->readAllStandardError());
}

void Sessions::ReproducibilityVerifier::shutdown()
{
  m_sweepActive = false;
  m_sweepQueue.clear();

  if (!m_process)
    return;

  m_process->terminate();
  if (!m_process->waitForFinished(kTerminateGraceMs))
    m_process->kill();
}

QVariantMap Sessions::ReproducibilityVerifier::sweepStatus() const
{
  int passed = 0, drifted = 0, notVerifiable = 0, failed = 0;
  for (const auto& entryVariant : m_sweepReports) {
    const auto report = entryVariant.toMap().value(QStringLiteral("report")).toMap();
    countSweepVerdict(
      report.value(QStringLiteral("verdict")).toString(), passed, drifted, notVerifiable, failed);
  }

  QVariantMap summary;
  summary.insert(QStringLiteral("passed"), passed);
  summary.insert(QStringLiteral("drifted"), drifted);
  summary.insert(QStringLiteral("notVerifiable"), notVerifiable);
  summary.insert(QStringLiteral("failed"), failed);

  QVariantMap status;
  status.insert(QStringLiteral("active"), m_sweepActive);
  status.insert(QStringLiteral("tag"), m_sweepTag);
  status.insert(QStringLiteral("remaining"), m_sweepQueue.size());
  status.insert(QStringLiteral("summary"), summary);
  status.insert(QStringLiteral("reports"), m_sweepReports);
  return status;
}

void Sessions::ReproducibilityVerifier::verify(int sessionId)
{
  SS_ASSERT(!m_archivePath.isEmpty(), return);

  if (m_process || m_sweepActive)
    return;

  auto* process = new QProcess(this);
  m_process     = process;
  Q_EMIT busyChanged();

  QStringList args{QStringLiteral("--verify-session"), m_archivePath, QStringLiteral("--headless")};
  if (sessionId >= 0)
    args << QStringLiteral("--verify-session-id") << QString::number(sessionId);

  connect(process,
          &QProcess::finished,
          this,
          [this, process, sessionId](int exitCode, QProcess::ExitStatus status) {
            bool ok  = false;
            auto map = readChildVerdict(process, exitCode, status, ok);

            int resolvedId = sessionId;
            if (resolvedId < 0 && map.contains(QStringLiteral("sessionId")))
              resolvedId = map.value(QStringLiteral("sessionId")).toInt();

            concludeVerification(resolvedId, ok && exitCode == 0, map);
          });
  connect(process, &QProcess::errorOccurred, this, [this, sessionId](QProcess::ProcessError err) {
    if (err == QProcess::FailedToStart)
      concludeVerification(
        sessionId,
        false,
        childFailureReport(QStringLiteral("child-spawn-failed"), -1, QByteArray()));
  });

  process->start(QCoreApplication::applicationFilePath(), args);
}

void Sessions::ReproducibilityVerifier::concludeVerification(int sessionId,
                                                             bool success,
                                                             const QVariantMap& verdict)
{
  if (!m_process)
    return;

  m_process->deleteLater();
  m_process = nullptr;
  Q_EMIT busyChanged();
  Q_EMIT verificationFinished(sessionId, success, verdict);
}

bool Sessions::ReproducibilityVerifier::publishStartFailure(int sessionId,
                                                            const QString& code,
                                                            const QString& error,
                                                            const QString& hint)
{
  QVariantMap map;
  map.insert(QStringLiteral("verdict"), QStringLiteral("error"));
  map.insert(QStringLiteral("errorCode"), code);
  map.insert(QStringLiteral("error"), error);
  map.insert(QStringLiteral("hint"), hint);

  m_lastReport = map;
  Q_EMIT reportChanged();
  Q_EMIT regressionFinished(sessionId, false, map);
  return false;
}

bool Sessions::ReproducibilityVerifier::regress(int sessionId, const QString& candidatePath)
{
  SS_ASSERT(!m_archivePath.isEmpty(), return false);

  if (m_process)
    return false;

  QString candidate = candidatePath;
  m_regressCandidateTemp.clear();
  if (candidate.isEmpty()) {
    candidate = QDir::temp().filePath(
      QStringLiteral("ss-regress-candidate-%1.json").arg(QCoreApplication::applicationPid()));
    if (!writeCandidateSnapshot(candidate))
      return publishStartFailure(
        sessionId,
        QStringLiteral("candidate-write-failed"),
        QStringLiteral("The current project could not be saved for comparison."),
        QStringLiteral("Check that there is enough free disk space, then try again."));

    m_regressCandidateTemp = candidate;
  }

  auto* process   = new QProcess(this);
  m_process       = process;
  m_regressActive = true;
  m_lastReport.clear();
  Q_EMIT busyChanged();
  Q_EMIT regressionBusyChanged();
  Q_EMIT reportChanged();

  QStringList args{QStringLiteral("--regress-session"),
                   m_archivePath,
                   QStringLiteral("--headless"),
                   QStringLiteral("--regress-project"),
                   candidate};
  if (sessionId >= 0)
    args << QStringLiteral("--regress-session-id") << QString::number(sessionId);

  connect(process,
          &QProcess::finished,
          this,
          [this, process, sessionId](int exitCode, QProcess::ExitStatus status) {
            bool ok  = false;
            auto map = readChildVerdict(process, exitCode, status, ok);

            int resolvedId = sessionId;
            if (resolvedId < 0 && map.contains(QStringLiteral("sessionId")))
              resolvedId = map.value(QStringLiteral("sessionId")).toInt();

            concludeRegression(resolvedId, ok && exitCode == 0, map);
          });
  connect(process, &QProcess::errorOccurred, this, [this, sessionId](QProcess::ProcessError err) {
    if (err != QProcess::FailedToStart)
      return;

    QMetaObject::invokeMethod(
      this,
      [this, sessionId]() {
        concludeRegression(
          sessionId,
          false,
          childFailureReport(QStringLiteral("child-spawn-failed"), -1, QByteArray()));
      },
      Qt::QueuedConnection);
  });

  process->start(QCoreApplication::applicationFilePath(), args);
  return true;
}

void Sessions::ReproducibilityVerifier::concludeRegression(int sessionId,
                                                           bool success,
                                                           const QVariantMap& report)
{
  if (!m_process)
    return;

  m_process->deleteLater();
  m_process       = nullptr;
  m_regressActive = false;

  if (!m_regressCandidateTemp.isEmpty()) {
    QFile::remove(m_regressCandidateTemp);
    m_regressCandidateTemp.clear();
  }

  m_lastReport = report;
  if (m_sweepActive)
    advanceSweep(sessionId, report);

  Q_EMIT busyChanged();
  Q_EMIT regressionBusyChanged();
  Q_EMIT reportChanged();
  Q_EMIT regressionFinished(sessionId, success, report);
}

QList<int> Sessions::ReproducibilityVerifier::taggedSessions(const QString& tag, bool& ok) const
{
  ok = false;
  QList<int> ids;
  const QString connName = QStringLiteral("ss_dbm_sweep_read");
  {
    auto db = QSqlDatabase::addDatabase(QStringLiteral("QSQLITE"), connName);
    db.setDatabaseName(m_archivePath);
    db.setConnectOptions(QStringLiteral("QSQLITE_OPEN_READONLY"));
    if (db.open()) {
      QSqlQuery q(db);
      q.prepare(QStringLiteral("SELECT s.session_id FROM sessions s "
                               "JOIN session_tags st ON st.session_id = s.session_id "
                               "JOIN tags t ON t.tag_id = st.tag_id "
                               "WHERE t.label = ? AND s.ended_at IS NOT NULL "
                               "ORDER BY s.session_id"));
      q.bindValue(0, tag);
      ok = q.exec();
      while (ok && q.next())
        ids.append(q.value(0).toInt());

      db.close();
    }
  }

  QSqlDatabase::removeDatabase(connName);
  return ids;
}

bool Sessions::ReproducibilityVerifier::regressByTag(const QString& tag,
                                                     const QString& candidatePath)
{
  SS_ASSERT(!m_archivePath.isEmpty(), return false);

  if (m_process || m_sweepActive || tag.trimmed().isEmpty())
    return false;

  bool queryOk   = false;
  const auto ids = taggedSessions(tag.trimmed(), queryOk);
  if (!queryOk)
    return publishStartFailure(-1,
                               QStringLiteral("sweep-query-failed"),
                               QStringLiteral("The tagged sessions could not be listed."),
                               QStringLiteral("Reopen the session file and try again."));

  QString candidate   = candidatePath;
  bool owns_candidate = false;
  if (candidate.isEmpty() && !ids.isEmpty()) {
    candidate = QDir::temp().filePath(
      QStringLiteral("ss-regress-sweep-%1.json").arg(QCoreApplication::applicationPid()));
    if (!writeCandidateSnapshot(candidate))
      return publishStartFailure(
        -1,
        QStringLiteral("candidate-write-failed"),
        QStringLiteral("The current project could not be saved for comparison."),
        QStringLiteral("Check that there is enough free disk space, then try again."));

    owns_candidate = true;
  }

  m_sweepTag           = tag.trimmed();
  m_sweepReports       = QVariantList();
  m_sweepOwnsCandidate = owns_candidate;
  m_sweepCandidate     = candidate;
  m_sweepQueue         = ids;
  m_sweepActive        = true;
  Q_EMIT sweepChanged();

  if (m_sweepQueue.isEmpty()) {
    finishSweep();
    return true;
  }

  const int first = m_sweepQueue.takeFirst();
  if (!regress(first, m_sweepCandidate)) {
    finishSweep();
    return false;
  }

  return true;
}

void Sessions::ReproducibilityVerifier::advanceSweep(int sessionId, const QVariantMap& report)
{
  QVariantMap entry;
  entry.insert(QStringLiteral("sessionId"), sessionId);
  entry.insert(QStringLiteral("report"), report);
  m_sweepReports.append(entry);

  if (m_sweepQueue.isEmpty() || m_archivePath.isEmpty()) {
    finishSweep();
    return;
  }

  const int next = m_sweepQueue.takeFirst();
  if (!regress(next, m_sweepCandidate))
    finishSweep();
}

void Sessions::ReproducibilityVerifier::finishSweep()
{
  if (m_sweepOwnsCandidate && !m_sweepCandidate.isEmpty())
    QFile::remove(m_sweepCandidate);

  m_sweepActive        = false;
  m_sweepOwnsCandidate = false;
  m_sweepCandidate.clear();
  m_sweepQueue.clear();
  Q_EMIT sweepChanged();
}

void Sessions::PreSessionState::clear()
{
  m_captured = false;
  m_viewState.clear();
  m_projectPath.clear();
  m_operationMode = SerialStudio::QuickPlot;
}

void Sessions::PreSessionState::capture(const SerialStudio::OperationMode mode,
                                        const QString& projectPath,
                                        const QString& viewState)
{
  SS_ASSERT_LOG(!m_captured);
  if (m_captured)
    return;

  m_captured      = true;
  m_viewState     = viewState;
  m_projectPath   = projectPath;
  m_operationMode = mode;
}

