void IO::Drivers::OpcUa::onDiscoveryTimeout()
{
  if (!m_discovering)
    return;

  teardownSession(m_discoverySession);
  onEndpointsFinished({}, OpcUaTypes::kStatusBadTimeout);
}

void IO::Drivers::OpcUa::onBrowseTimeout()
{
  if (!m_browsing)
    return;

  onBrowseFailed(tr("Timed out after %1 s").arg(kOpcUaBrowseDeadlineMs / 1000));
}

[[nodiscard]] static IO::Drivers::Network* networkDriver()
{
  static auto& connectionManager = IO::ConnectionManager::instance();
  return connectionManager.network();
}

API::CommandResponse API::Handlers::NetworkHandler::setWebSocketUrl(const QString& id,
                                                                    const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("url"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: url"));
  }

  const QString url    = params.value(QStringLiteral("url")).toString().trimmed();
  const QString scheme = QUrl(url, QUrl::StrictMode).scheme().toLower();
  if (scheme != QLatin1String("ws") && scheme != QLatin1String("wss")) {
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("URL must start with ws:// or wss://"));
  }

  networkDriver()->setWebSocketUrl(url);

  QJsonObject result;
  result[QStringLiteral("webSocketUrl")] = url;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::NetworkHandler::setHttpUrl(const QString& id,
                                                               const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("url"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: url"));
  }

  const QString url    = params.value(QStringLiteral("url")).toString().trimmed();
  const QString scheme = QUrl(url, QUrl::StrictMode).scheme().toLower();
  if (scheme != QLatin1String("http") && scheme != QLatin1String("https")) {
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("URL must start with http:// or https://"));
  }

  networkDriver()->setHttpUrl(url);

  QJsonObject result;
  result[QStringLiteral("httpUrl")] = url;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::NetworkHandler::setHttpMethod(const QString& id,
                                                                  const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("method"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: method"));
  }

  const QString method = params.value(QStringLiteral("method")).toString().toUpper();
  const int index      = networkDriver()->httpMethods().indexOf(method);
  if (index < 0) {
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("Invalid method: %1. Valid values: %2")
        .arg(method, networkDriver()->httpMethods().join(QStringLiteral(", "))));
  }

  networkDriver()->setHttpMethodIndex(index);

  QJsonObject result;
  result[QStringLiteral("httpMethod")] = method;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::NetworkHandler::setHttpBody(const QString& id,
                                                                const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("body"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: body"));
  }

  const QString body = params.value(QStringLiteral("body")).toString();
  networkDriver()->setHttpBody(body);

  QJsonObject result;
  result[QStringLiteral("httpBody")] = body;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::NetworkHandler::setHttpHeaders(const QString& id,
                                                                   const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("headers"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: headers"));
  }

  const QString headers = params.value(QStringLiteral("headers")).toString();
  networkDriver()->setHttpHeaders(headers);

  QJsonObject result;
  result[QStringLiteral("httpHeaders")] = headers;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::NetworkHandler::setHttpInterval(const QString& id,
                                                                    const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("interval"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: interval"));
  }

  const int interval = params.value(QStringLiteral("interval")).toInt();
  if (interval < 0 || interval > 3600000) {
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Interval must be 0, or between 10 and 3600000"));
  }

  networkDriver()->setHttpInterval(interval);

  QJsonObject result;
  result[QStringLiteral("httpInterval")] = networkDriver()->httpInterval();
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::NetworkHandler::setIgnoreTlsErrors(const QString& id,
                                                                       const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("enabled"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: enabled"));
  }

  const bool enabled = params.value(QStringLiteral("enabled")).toBool();
  networkDriver()->setIgnoreTlsErrors(enabled);

  QJsonObject result;
  result[QStringLiteral("ignoreTlsErrors")] = enabled;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::NetworkHandler::getStatus(const QString& id,
                                                              const QJsonObject& params)
{
  Q_UNUSED(params)

  auto* network = networkDriver();

  QJsonObject result;
  result[QStringLiteral("socketTypeIndex")] = network->socketTypeIndex();
  result[QStringLiteral("isOpen")]          = network->isOpen();
  result[QStringLiteral("isConnecting")]    = network->isConnecting();

  result[QStringLiteral("pollsOk")]      = static_cast<double>(network->pollsOk());
  result[QStringLiteral("pollsFailed")]  = static_cast<double>(network->pollsFailed());
  result[QStringLiteral("pollsSkipped")] = static_cast<double>(network->pollsSkipped());
  result[QStringLiteral("consecutiveFailures")] =
    static_cast<double>(network->consecutiveFailures());

QStringList IO::Drivers::Network::httpMethods() const
{
  QStringList list;
  list.append(QStringLiteral("GET"));
  list.append(QStringLiteral("POST"));
  list.append(QStringLiteral("PUT"));
  list.append(QStringLiteral("PATCH"));
  list.append(QStringLiteral("DELETE"));
  return list;
}

QStringList IO::Drivers::Network::webSocketFormats() const
{
  QStringList list;
  list.append(tr("Automatic"));
  list.append(tr("Text"));
  list.append(tr("Binary"));
  return list;
}

void IO::Drivers::Network::setIgnoreTlsErrors(const bool enabled)
{
  if (m_ignoreTlsErrors == enabled)
    return;

  m_ignoreTlsErrors = enabled;
  m_settings.setValue("NetworkDriver/ignoreTlsErrors", enabled);
  Q_EMIT ignoreTlsErrorsChanged();
}

void IO::Drivers::Network::setHttpUrl(const QString& url)
{
  if (m_httpUrl == url)
    return;

  m_httpUrl = url;
  m_settings.setValue("NetworkDriver/httpUrl", url);
  Q_EMIT httpChanged();
}

void IO::Drivers::Network::setHttpBody(const QString& body)
{
  if (m_httpBody == body)
    return;

  m_httpBody = body;
  m_settings.setValue("NetworkDriver/httpBody", body);
  Q_EMIT httpChanged();
}

void IO::Drivers::Network::setHttpHeaders(const QString& headers)
{
  if (m_httpHeaders == headers)
    return;
  m_httpHeaders = headers;
  m_settings.setValue("NetworkDriver/httpHeaders", headers);
  Q_EMIT httpChanged();
}

void IO::Drivers::Network::setHttpMethodIndex(const int index)
{
  if (m_httpMethod == index || index < 0 || index >= httpMethods().count())
    return;

  m_httpMethod = index;
  m_settings.setValue("NetworkDriver/httpMethod", index);
  Q_EMIT httpChanged();
}

void IO::Drivers::Network::setHttpInterval(const int interval)
{
  const int bounded = interval <= 0 ? 0 : qMax(interval, kHttpMinIntervalMs);
  if (m_httpInterval == bounded)
    return;

  m_httpInterval = bounded;
  m_settings.setValue("NetworkDriver/httpInterval", bounded);
  Q_EMIT httpChanged();
}

void IO::Drivers::Network::setSocketType(const SocketType type)
{
  if (m_socketType == type)
    return;

  m_socketType = type;
  m_settings.setValue("NetworkDriver/socketType", static_cast<int>(type));
  Q_EMIT socketTypeChanged();
 * @brief Handles an error on an established link: report once, tear down, stay down. Dial
 *        failures never reach here, because dialTcpBlocking() owns them; the teardown is queued
 *        on the connection manager because it destroys this driver.
void IO::Drivers::Network::reportLinkError(const QString& error)
  appendSocketTypeProperty(props);
  switch (socketType()) {
    case SocketType::Tcp:
      appendTcpProperties(props);
      break;
    case SocketType::Udp:
      appendUdpProperties(props);
      break;
    case SocketType::WebSocket:
      appendWebSocketProperties(props);
      break;
    case SocketType::Http:
      appendHttpProperties(props);
      break;
  }

  return props;
}

void IO::Drivers::Network::appendTlsProperty(QList<IO::DriverProperty>& props) const
{
  IO::DriverProperty tls;
  tls.key         = QStringLiteral("ignoreTlsErrors");
  tls.label       = tr("Ignore TLS Errors");
  tls.description = tr("Accept self-signed or mismatched certificates");
  tls.type        = IO::DriverProperty::CheckBox;
  tls.value       = m_ignoreTlsErrors;
  props.append(tls);
}

bool IO::Drivers::Network::applyTlsProperty(const QString& key, const QVariant& value)
{
  if (key != QLatin1String("ignoreTlsErrors"))
    return false;

  setIgnoreTlsErrors(value.toBool());
  return true;
}

[[nodiscard]] static QByteArray httpVerb(int index)
{
  switch (index) {
    case 1:
      return QByteArrayLiteral("POST");
    case 2:
      return QByteArrayLiteral("PUT");
    case 3:
      return QByteArrayLiteral("PATCH");
    case 4:
      return QByteArrayLiteral("DELETE");
    default:
      return QByteArrayLiteral("GET");
  }
}

[[nodiscard]] static QString replyFailureReason(const QNetworkReply* reply, int status)
{
  if (reply->error() != QNetworkReply::NoError)
    return reply->errorString();

  if (status > 0)
    return QObject::tr("Server answered HTTP %1").arg(status);

  return QObject::tr("The server sent no response");
}

bool IO::Drivers::Network::openHttp(const QIODevice::OpenMode mode)
{
  Q_UNUSED(mode);

  QUrl url;
  QString reason;
  if (!urlForCurrentMode(url, reason)) {
    logDriverError(tr("HTTP error"), reason);
    return false;
  }

  m_pollsOk             = 0;
  m_pollsFailed         = 0;
  m_pollsSkipped        = 0;
  m_consecutiveFailures = 0;
  m_httpFailureLogged   = false;

  connect(m_httpManager,
          &QNetworkAccessManager::sslErrors,
          this,
          &IO::Drivers::Network::onHttpSslErrors,
          static_cast<Qt::ConnectionType>(Qt::DirectConnection | Qt::UniqueConnection));

  m_dialPending = true;
  sendHttpRequest(m_httpBody.toUtf8());

  if (m_dialPending && m_reply.isNull()) {
    m_dialPending = false;
    logDriverError(tr("HTTP error"), tr("The request could not be sent"));
    return false;
  }

  return m_dialPending || m_httpActive;
}

void IO::Drivers::Network::closeHttp()
{
  m_pollTimer.stop();
  m_httpActive = false;

  if (m_reply.isNull())
    return;

  disconnect(m_reply, &QNetworkReply::finished, this, &IO::Drivers::Network::onHttpReplyFinished);
  m_reply->abort();
  m_reply->deleteLater();
  m_reply.clear();
}

void IO::Drivers::Network::sendHttpRequest(const QByteArray& body)
{
  QUrl url;
  QString reason;
  if (!urlForCurrentMode(url, reason))
    return;

  m_reply = m_httpManager->sendCustomRequest(buildHttpRequest(url), httpVerb(m_httpMethod), body);

  connect(m_reply,
          &QNetworkReply::finished,
          this,
          &IO::Drivers::Network::onHttpReplyFinished,
          Qt::UniqueConnection);
}

QNetworkRequest IO::Drivers::Network::buildHttpRequest(const QUrl& url) const
{
  QNetworkRequest request(url);
  request.setTransferTimeout(kHttpTransferTimeoutMs);
  request.setMaximumRedirectsAllowed(kHttpMaxRedirects);
  request.setAttribute(QNetworkRequest::RedirectPolicyAttribute,
                       m_httpMethod == kHttpMethodGet ? QNetworkRequest::NoLessSafeRedirectPolicy
                                                      : QNetworkRequest::ManualRedirectPolicy);
  request.setHeader(QNetworkRequest::ContentTypeHeader, QStringLiteral("application/octet-stream"));

  const auto lines = QStringView{m_httpHeaders}.split(u'\n', Qt::SkipEmptyParts);
  for (const auto& line : lines) {
    const qsizetype separator = line.indexOf(u':');
    if (separator <= 0)
      continue;

    const QByteArray name = line.left(separator).trimmed().toUtf8();
    if (!name.isEmpty())
      request.setRawHeader(name, line.mid(separator + 1).trimmed().toUtf8());
  }

  return request;
}

qint64 IO::Drivers::Network::writeHttp(const QByteArray& data)
{
  if (!m_reply.isNull()) {
    disconnect(m_reply, &QNetworkReply::finished, this, &IO::Drivers::Network::onHttpReplyFinished);
    m_reply->abort();
    m_reply->deleteLater();
    m_reply.clear();
  }

  sendHttpRequest(data);
  return m_reply.isNull() ? 0 : data.size();
}

bool IO::Drivers::Network::httpConfigured() const
{
  QUrl url;
  QString reason;
  return urlForCurrentMode(url, reason);
}

void IO::Drivers::Network::onPollTimeout()
{
  if (!m_httpActive)
    return;

  if (!m_reply.isNull()) {
    ++m_pollsSkipped;
    return;
  }

  sendHttpRequest(m_httpBody.toUtf8());
}

void IO::Drivers::Network::onHttpReplyFinished()
{
  const auto timestamp = IO::CapturedData::SteadyClock::now();

  auto* reply = qobject_cast<QNetworkReply*>(sender());
  if (reply == nullptr || reply != m_reply)
    return;

  m_reply.clear();
  reply->deleteLater();

  const int status = reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();
  const bool ok    = reply->error() == QNetworkReply::NoError && status >= 200 && status < 300;
  if (ok)
    publishReceivedData(reply->readAll(), timestamp);

  if (m_dialPending) {
    if (!ok) {
      failDial(replyFailureReason(reply, status));
      return;
    }

    m_httpActive = true;
    succeedDial();
    if (m_httpInterval > 0)
      m_pollTimer.start(m_httpInterval);

    return;
  }

  if (ok) {
    ++m_pollsOk;
    if (m_consecutiveFailures > 0)
      logDriverError(tr("HTTP source recovered"), tr("%1 is answering again").arg(m_httpUrl));

    m_consecutiveFailures = 0;
    m_httpFailureLogged   = false;
    return;
  }

  ++m_pollsFailed;
  ++m_consecutiveFailures;
  if (!m_httpFailureLogged) {
    m_httpFailureLogged = true;
    logDriverError(tr("HTTP poll failed"), replyFailureReason(reply, status));
  }
}

void IO::Drivers::Network::onHttpSslErrors(QNetworkReply* reply, const QList<QSslError>& errors)
{
  if (!m_ignoreTlsErrors || reply == nullptr)
    return;

  QStringList descriptions;
  descriptions.reserve(errors.count());
  for (const auto& error : errors)
    descriptions.append(error.errorString());

  logDriverError(tr("TLS verification bypassed"),
                 tr("Continuing to %1 despite: %2")
                   .arg(reply->url().toString(), descriptions.join(QStringLiteral("; "))));

  reply->ignoreSslErrors();
}

void IO::Drivers::Network::appendHttpProperties(QList<IO::DriverProperty>& props) const
{
  IO::DriverProperty url;
  url.key         = QStringLiteral("httpUrl");
  url.label       = tr("URL");
  url.description = tr("REST endpoint, for example %1").arg(defaultHttpUrl());
  url.type        = IO::DriverProperty::Text;
  url.value       = m_httpUrl;
  props.append(url);

  IO::DriverProperty method;
  method.key     = QStringLiteral("httpMethodIndex");
  method.label   = tr("Method");
  method.type    = IO::DriverProperty::ComboBox;
  method.value   = m_httpMethod;
  method.options = httpMethods();
  props.append(method);

  IO::DriverProperty interval;
  interval.key         = QStringLiteral("httpInterval");
  interval.label       = tr("Poll Interval (ms)");
  interval.description = tr("Use 0 to request only when data is sent");
  interval.type        = IO::DriverProperty::IntField;
  interval.value       = m_httpInterval;
  interval.min         = 0;
  interval.max         = 3600000;
  props.append(interval);

  IO::DriverProperty body;
  body.key   = QStringLiteral("httpBody");
  body.label = tr("Request Body");
  body.type  = IO::DriverProperty::Text;
  body.value = m_httpBody;
  props.append(body);

  IO::DriverProperty headers;
  headers.key         = QStringLiteral("httpHeaders");
  headers.label       = tr("Request Headers");
  headers.description = tr("One %1 pair per line").arg(QStringLiteral("Name: Value"));
  headers.type        = IO::DriverProperty::Text;
  headers.value       = m_httpHeaders;
  props.append(headers);

  appendTlsProperty(props);
}

bool IO::Drivers::Network::applyHttpProperty(const QString& key, const QVariant& value)
{
  if (key == QLatin1String("httpUrl")) {
    setHttpUrl(value.toString());
    return true;
  }

  if (key == QLatin1String("httpMethodIndex")) {
    setHttpMethodIndex(value.toInt());
    return true;
  }

  if (key == QLatin1String("httpInterval")) {
    setHttpInterval(value.toInt());
    return true;
  }

  if (key == QLatin1String("httpBody")) {
    setHttpBody(value.toString());
    return true;
  }

  if (key == QLatin1String("httpHeaders")) {
    setHttpHeaders(value.toString());
    return true;
  }

  return false;
}

static inline int probePoll(ProbePoll* fds, int timeoutMs)
{
#ifdef Q_OS_WIN
  return ::WSAPoll(fds, 1, timeoutMs);
#else
  return ::poll(fds, 1, timeoutMs);
#endif
}

[[nodiscard]] static bool probeConnectPending()
{
#ifdef Q_OS_WIN
  return ::WSAGetLastError() == WSAEWOULDBLOCK;
#else
  return errno == EINPROGRESS;
#endif
}

[[nodiscard]] static bool probeLastErrorRefused()
{
#ifdef Q_OS_WIN
  return ::WSAGetLastError() == WSAECONNREFUSED;
#else
  return errno == ECONNREFUSED;
#endif
}

static void closeProbeSocket(ProbeSocket handle)
{
#ifdef Q_OS_WIN
  ::closesocket(handle);
#else
  ::close(handle);
#endif
}

[[nodiscard]] static bool markProbeNonBlocking(ProbeSocket handle)
{
#ifdef Q_OS_WIN
  u_long mode = 1;
  return ::ioctlsocket(handle, FIONBIO, &mode) == 0;
#else
  const int flags = ::fcntl(handle, F_GETFL, 0);
  return flags != -1 && ::fcntl(handle, F_SETFL, flags | O_NONBLOCK) != -1;
#endif
}

[[nodiscard]] static bool probeTcpOnce(const addrinfo* address, int timeoutMs, bool& refused)
{
  SS_ASSERT(address != nullptr, return false);
  SS_ASSERT(timeoutMs >= 0, timeoutMs = 0);

  refused = false;

  const ProbeSocket handle =
    ::socket(address->ai_family, address->ai_socktype, address->ai_protocol);
  if (handle == kNoProbeSocket)
    return false;

  if (!markProbeNonBlocking(handle)) {
    closeProbeSocket(handle);
    return false;
  }

  const int dialed =
    ::connect(handle, address->ai_addr, static_cast<ProbeLen>(address->ai_addrlen));
  if (dialed == 0) {
    closeProbeSocket(handle);
    return true;
  }

  if (!probeConnectPending()) {
    refused = probeLastErrorRefused();
    closeProbeSocket(handle);
    return false;
  }

  ProbePoll pending{};
  pending.fd     = handle;
  pending.events = POLLOUT;

  const int ready = probePoll(&pending, timeoutMs);
  if (ready <= 0) {
    closeProbeSocket(handle);
    return false;
  }

  int error          = 0;
  ProbeLen errorSize = sizeof(error);
  const int queried =
    ::getsockopt(handle, SOL_SOCKET, SO_ERROR, reinterpret_cast<char*>(&error), &errorSize);
  closeProbeSocket(handle);

  refused = (queried == 0 && error == kProbeRefused);
  return queried == 0 && error == 0;
}

static bool waitForTcpEndpoint(const QString& host, quint16 port, QString& reason)
{
  SS_ASSERT(port != 0, return false);
  SS_ASSERT_LOG(!host.isEmpty());

  addrinfo hints{};
  hints.ai_family   = AF_UNSPEC;
  hints.ai_socktype = SOCK_STREAM;
  hints.ai_flags    = AI_ADDRCONFIG;

  const QByteArray node    = host.toUtf8();
  const QByteArray service = QByteArray::number(port);

  addrinfo* resolved = nullptr;
  if (::getaddrinfo(node.constData(), service.constData(), &hints, &resolved) != 0 || !resolved) {
    reason = QObject::tr("Host not found");
    return false;
  }

  QElapsedTimer deadline;
  deadline.start();

  while (deadline.elapsed() < kNetworkDialDeadlineMs) {
    bool refusedAny = false;
    for (const addrinfo* it = resolved; it != nullptr; it = it->ai_next) {
      const int remaining = kNetworkDialDeadlineMs - static_cast<int>(deadline.elapsed());
      if (remaining <= 0)
        break;

      bool refused = false;
      if (probeTcpOnce(it, remaining, refused)) {
        ::freeaddrinfo(resolved);
        return true;
      }

      refusedAny = refusedAny || refused;
    }

    if (!refusedAny) {
      reason = QObject::tr("Connection failed");
      ::freeaddrinfo(resolved);
      return false;
    }

    QThread::msleep(kNetworkDialPaceMs);
  }

  reason = QObject::tr("Connection timed out");
  ::freeaddrinfo(resolved);
  return false;
}

bool IO::Drivers::Network::dialTcpBlocking(const QString& host, const QIODevice::OpenMode mode)
{
  QString reason;
  if (!waitForTcpEndpoint(host, tcpPort(), reason)) {
    logDriverError(
      tr("Network socket error"),
      tr("Cannot connect to %1:%2 (%3)").arg(host, QString::number(tcpPort()), reason));
    return false;
  }

  m_tcpSocket->connectToHost(host, tcpPort(), mode);
  if (!m_tcpSocket->waitForConnected(kNetworkDialDeadlineMs)) {
    const QString finalReason = m_tcpSocket->errorString();
    m_tcpSocket->abort();
    logDriverError(
      tr("Network socket error"),
      tr("Cannot connect to %1:%2 (%3)").arg(host, QString::number(tcpPort()), finalReason));
    return false;
  }

  connect(m_tcpSocket,
          &QTcpSocket::readyRead,
          this,
          &IO::Drivers::Network::onTcpReadyRead,
          Qt::UniqueConnection);
  connect(m_tcpSocket,
          &QTcpSocket::errorOccurred,
          this,
          &IO::Drivers::Network::onTcpError,
          Qt::UniqueConnection);
  return true;
}

bool IO::Drivers::Network::openTcp(const QIODevice::OpenMode mode)
{
  auto hostAddr = remoteAddress();
  if (hostAddr.isEmpty())
    hostAddr = defaultAddress();

  return dialTcpBlocking(hostAddr, mode);
}

void IO::Drivers::Network::closeTcp()
{
  disconnect(m_tcpSocket, &QTcpSocket::readyRead, this, &IO::Drivers::Network::onTcpReadyRead);
  disconnect(m_tcpSocket, &QTcpSocket::errorOccurred, this, &IO::Drivers::Network::onTcpError);

  m_tcpSocket->abort();
  m_tcpSocket->close();
  m_tcpSocket->disconnectFromHost();
}

void IO::Drivers::Network::appendTcpProperties(QList<IO::DriverProperty>& props) const
{
  appendAddressProperty(props);

  IO::DriverProperty tcp;
  tcp.key   = QStringLiteral("tcpPort");
  tcp.label = tr("TCP Port");
  tcp.type  = IO::DriverProperty::IntField;
  tcp.value = m_tcpPort;
  tcp.min   = 1;
  tcp.max   = 65535;
  props.append(tcp);
}

bool IO::Drivers::Network::applyTcpProperty(const QString& key, const QVariant& value)
{
  if (key != QLatin1String("tcpPort"))
    return false;

  setTcpPort(static_cast<quint16>(value.toInt()));
  return true;
}

void IO::Drivers::Network::enlargeUdpReceiveBuffer()
{
  constexpr int kUdpReceiveBufferBytes = 8 * 1024 * 1024;
  m_udpSocket->setSocketOption(QAbstractSocket::ReceiveBufferSizeSocketOption,
                               kUdpReceiveBufferBytes);
}

bool IO::Drivers::Network::openUdp(const QIODevice::OpenMode mode)
{
  if (!m_address.isEmpty() && m_resolvedAddress.isNull() && !m_lookupActive)
    lookup(m_address);

  if (!m_udpSocket->bind(udpLocalPort(),
                         QAbstractSocket::ShareAddress | QAbstractSocket::ReuseAddressHint)) {
    qWarning() << "UDP bind failed on port" << udpLocalPort() << ":" << m_udpSocket->errorString();
    close();
    return false;
  }

  enlargeUdpReceiveBuffer();

  if (udpMulticast()) {
    const QHostAddress literal(m_address);
    const QHostAddress group = literal.isNull() ? m_resolvedAddress : literal;
    if (group.isNull() || !m_udpSocket->joinMulticastGroup(group)) {
      qWarning() << "UDP multicast join failed for" << m_address << ":"
                 << m_udpSocket->errorString();
      close();
      return false;
    }
  }

  if (m_udpSocket->open(mode)) {
    connect(m_udpSocket, &QUdpSocket::readyRead, this, &IO::Drivers::Network::onUdpReadyRead);
    return true;
  }

  close();
  return false;
}

void IO::Drivers::Network::closeUdp()
{
  disconnect(m_udpSocket, &QUdpSocket::readyRead, this, &IO::Drivers::Network::onUdpReadyRead);

  m_udpSocket->abort();
  m_udpSocket->close();
  m_udpSocket->disconnectFromHost();
}

qint64 IO::Drivers::Network::writeUdp(const QByteArray& data)
{
  const QHostAddress dest =
    m_resolvedAddress.isNull() ? QHostAddress(m_address) : m_resolvedAddress;
  if (dest.isNull())
    return -1;

  return m_udpSocket->writeDatagram(data, dest, udpRemotePort());
}

bool IO::Drivers::Network::udpOpen() const
{
  const auto state = m_udpSocket->state();
  return m_udpSocket->isOpen()
      && (state == QUdpSocket::ConnectedState || state == QUdpSocket::BoundState);
}

void IO::Drivers::Network::onUdpReadyRead()
{
  constexpr int kMaxDatagramsPerRead = 256;
  for (int n = 0; n < kMaxDatagramsPerRead && m_udpSocket->hasPendingDatagrams(); ++n) {
    const qint64 size = m_udpSocket->pendingDatagramSize();
    m_udpBuffer.resize(size);
    m_udpSocket->readDatagram(m_udpBuffer.data(), m_udpBuffer.size());
    publishReceivedData(m_udpBuffer);
  }
}

void IO::Drivers::Network::onUdpError(const QAbstractSocket::SocketError socketError)
{
  if (socketError == QAbstractSocket::ConnectionRefusedError) [[unlikely]]
    return;

  reportLinkError(m_udpSocket->errorString());
}

void IO::Drivers::Network::appendUdpProperties(QList<IO::DriverProperty>& props) const
{
  appendAddressProperty(props);

  IO::DriverProperty udpLocal;
  udpLocal.key   = QStringLiteral("udpLocalPort");
  udpLocal.label = tr("UDP Local Port");
  udpLocal.type  = IO::DriverProperty::IntField;
  udpLocal.value = m_udpLocalPort;
  udpLocal.min   = 0;
  udpLocal.max   = 65535;
  props.append(udpLocal);

  IO::DriverProperty udpRemote;
  udpRemote.key   = QStringLiteral("udpRemotePort");
  udpRemote.label = tr("UDP Remote Port");
  udpRemote.type  = IO::DriverProperty::IntField;
  udpRemote.value = m_udpRemotePort;
  udpRemote.min   = 1;
  udpRemote.max   = 65535;
  props.append(udpRemote);

  IO::DriverProperty multicast;
  multicast.key   = QStringLiteral("udpMulticast");
  multicast.label = tr("UDP Multicast");
  multicast.type  = IO::DriverProperty::CheckBox;
  multicast.value = m_udpMulticast;
  props.append(multicast);
}

bool IO::Drivers::Network::applyUdpProperty(const QString& key, const QVariant& value)
{
  if (key == QLatin1String("udpLocalPort")) {
    setUdpLocalPort(static_cast<quint16>(value.toInt()));
    return true;
  }

  if (key == QLatin1String("udpRemotePort")) {
    setUdpRemotePort(static_cast<quint16>(value.toInt()));
    return true;
  }

  if (key == QLatin1String("udpMulticast")) {
    setUdpMulticast(value.toBool());
    return true;
  }

  return false;
}

[[nodiscard]] static bool isUtf8Text(const QByteArray& data)
{
  QStringDecoder decoder(QStringDecoder::Utf8, QStringDecoder::Flag::Stateless);
  const QString decoded = decoder(data);
  Q_UNUSED(decoded);
  return !decoder.hasError();
}

bool IO::Drivers::Network::openWebSocket(const QIODevice::OpenMode mode)
{
  Q_UNUSED(mode);

  QUrl url;
  QString reason;
  if (!urlForCurrentMode(url, reason)) {
    logDriverError(tr("WebSocket error"), reason);
    return false;
  }

  connect(m_webSocket,
          &QWebSocket::connected,
          this,
          &IO::Drivers::Network::onWebSocketConnected,
          Qt::UniqueConnection);
  connect(m_webSocket,
          &QWebSocket::disconnected,
          this,
          &IO::Drivers::Network::onWebSocketDisconnected,
          Qt::UniqueConnection);
  connect(m_webSocket,
          &QWebSocket::errorOccurred,
          this,
          &IO::Drivers::Network::onWebSocketError,
          Qt::UniqueConnection);
  connect(m_webSocket,
          &QWebSocket::sslErrors,
          this,
          &IO::Drivers::Network::onWebSocketSslErrors,
          static_cast<Qt::ConnectionType>(Qt::DirectConnection | Qt::UniqueConnection));
  connect(m_webSocket,
          &QWebSocket::textMessageReceived,
          this,
          &IO::Drivers::Network::onWebSocketTextMessage,
          Qt::UniqueConnection);
  connect(m_webSocket,
          &QWebSocket::binaryMessageReceived,
          this,
          &IO::Drivers::Network::onWebSocketBinaryMessage,
          Qt::UniqueConnection);

  m_dialPending = true;
  m_webSocket->open(url);

  return m_dialPending || webSocketOpen();
}

void IO::Drivers::Network::closeWebSocket()
{
  // clang-format off
  disconnect(m_webSocket, &QWebSocket::connected,
             this, &IO::Drivers::Network::onWebSocketConnected);
  disconnect(m_webSocket, &QWebSocket::disconnected,
             this, &IO::Drivers::Network::onWebSocketDisconnected);
  disconnect(m_webSocket, &QWebSocket::errorOccurred,
             this, &IO::Drivers::Network::onWebSocketError);
  disconnect(m_webSocket, &QWebSocket::sslErrors,
             this, &IO::Drivers::Network::onWebSocketSslErrors);
  disconnect(m_webSocket, &QWebSocket::textMessageReceived,
             this, &IO::Drivers::Network::onWebSocketTextMessage);
  disconnect(m_webSocket, &QWebSocket::binaryMessageReceived,
             this, &IO::Drivers::Network::onWebSocketBinaryMessage);
  // clang-format on

  m_webSocket->abort();
}

qint64 IO::Drivers::Network::writeWebSocket(const QByteArray& data)
{
  const bool asText = m_webSocketFormat == 1 || (m_webSocketFormat == 0 && isUtf8Text(data));

  const qint64 sent = asText ? m_webSocket->sendTextMessage(QString::fromUtf8(data))
                             : m_webSocket->sendBinaryMessage(data);

  (void)m_webSocket->flush();
  return sent;
}

bool IO::Drivers::Network::webSocketConfigured() const
{
  QUrl url;
  QString reason;
  return urlForCurrentMode(url, reason);
}

void IO::Drivers::Network::onWebSocketDisconnected()
{
  if (m_dialPending) {
    const QString reason = m_webSocket->closeReason();
    failDial(reason.isEmpty() ? tr("The connection closed during the handshake") : reason);
    return;
  }

  reportLinkError(tr("The remote peer closed the connection"));
}

void IO::Drivers::Network::onWebSocketError(const QAbstractSocket::SocketError socketError)
{
  Q_UNUSED(socketError);

  const QString reason = m_webSocket->errorString();
  if (m_dialPending) {
    failDial(reason);
    return;
  }

  reportLinkError(reason);
}

void IO::Drivers::Network::onWebSocketSslErrors(const QList<QSslError>& errors)
{
  if (!m_ignoreTlsErrors)
    return;

  QStringList descriptions;
  descriptions.reserve(errors.count());
  for (const auto& error : errors)
    descriptions.append(error.errorString());

  logDriverError(
    tr("TLS verification bypassed"),
    tr("Continuing to %1 despite: %2")
      .arg(m_webSocket->requestUrl().toString(), descriptions.join(QStringLiteral("; "))));

  m_webSocket->ignoreSslErrors();
}

void IO::Drivers::Network::onWebSocketTextMessage(const QString& message)
{
  const auto timestamp = IO::CapturedData::SteadyClock::now();
  publishReceivedData(message.toUtf8(), timestamp);
}

void IO::Drivers::Network::onWebSocketBinaryMessage(const QByteArray& message)
{
  const auto timestamp = IO::CapturedData::SteadyClock::now();
  publishReceivedData(message, timestamp);
}

void IO::Drivers::Network::appendWebSocketProperties(QList<IO::DriverProperty>& props) const
{
  IO::DriverProperty url;
  url.key         = QStringLiteral("webSocketUrl");
  url.label       = tr("URL");
  url.description = tr("WebSocket endpoint, for example %1").arg(defaultWebSocketUrl());
  url.type        = IO::DriverProperty::Text;
  url.value       = m_webSocketUrl;
  props.append(url);

  IO::DriverProperty format;
  format.key     = QStringLiteral("webSocketFormatIndex");
  format.label   = tr("Send Format");
  format.type    = IO::DriverProperty::ComboBox;
  format.value   = m_webSocketFormat;
  format.options = webSocketFormats();
  props.append(format);

  appendTlsProperty(props);
}

bool IO::Drivers::Network::applyWebSocketProperty(const QString& key, const QVariant& value)
{
  if (key == QLatin1String("webSocketUrl")) {
    setWebSocketUrl(value.toString());
    return true;
  }

  if (key == QLatin1String("webSocketFormatIndex")) {
    setWebSocketFormatIndex(value.toInt());
    return true;
  }

  return false;
}

void CLI::setupWebSocketConnection(const QString& url)
{
  static auto& connectionManager = IO::ConnectionManager::instance();
  connectionManager.setBusType(SerialStudio::BusType::Network);

  auto* network = connectionManager.network();
  network->setSocketType(IO::Drivers::Network::SocketType::WebSocket);
  network->setWebSocketUrl(url);

  if (m_parser.isSet(m_opts.insecureTlsOpt))
    network->setIgnoreTlsErrors(true);

  connectionManager.connectDevice();
}

void CLI::setupHttpConnection(const QString& url)
{
  static auto& connectionManager = IO::ConnectionManager::instance();
  connectionManager.setBusType(SerialStudio::BusType::Network);

  auto* network = connectionManager.network();
  network->setSocketType(IO::Drivers::Network::SocketType::Http);
  network->setHttpUrl(url);

  if (m_parser.isSet(m_opts.httpMethodOpt)) {
    const QString method = m_parser.value(m_opts.httpMethodOpt).toUpper();
    const int index      = network->httpMethods().indexOf(method);
    if (index < 0) {
      qWarning() << "Invalid HTTP method:" << method;
      return;
    }

    network->setHttpMethodIndex(index);
  }

  if (m_parser.isSet(m_opts.httpIntervalOpt))
    network->setHttpInterval(m_parser.value(m_opts.httpIntervalOpt).toInt());

  if (m_parser.isSet(m_opts.httpHeaderOpt))
    network->setHttpHeaders(m_parser.values(m_opts.httpHeaderOpt).join(QChar('\n')));

  if (m_parser.isSet(m_opts.insecureTlsOpt))
    network->setIgnoreTlsErrors(true);

  connectionManager.connectDevice();
}

QString API::EnumLabels::securityPolicySlug(int value)
{
  switch (value) {
    case 0:
      return QStringLiteral("none");
    case 1:
      return QStringLiteral("basic128-rsa15");
    case 2:
      return QStringLiteral("basic256");
    case 3:
      return QStringLiteral("basic256-sha256");
    case 4:
      return QStringLiteral("aes128-sha256-rsaoaep");
    case 5:
