void API::Handlers::OpcUaHandler::registerSecurityCommands(CommandRegistry& registry)
{
  const auto empty = API::emptySchema();

  registry.registerCommand(
    QStringLiteral("io.opcua.setSecurityPolicy"),
    QStringLiteral("Set the security policy (params: policy - full URI or short name)"),
    API::makeSchema({
      {QStringLiteral("policy"),
       QStringLiteral("string"),
       QStringLiteral("None, Basic128Rsa15, Basic256, Basic256Sha256, "
                      "Aes128_Sha256_RsaOaep or Aes256_Sha256_RsaPss")}
  }),
    &setSecurityPolicy);
  registry.registerCommand(
    QStringLiteral("io.opcua.setSecurityMode"),
    QStringLiteral(
      "Set the message security mode (params: mode - 1=None, 2=Sign, 3=SignAndEncrypt)"),
    API::makeSchema({
      {QStringLiteral("mode"),
       QStringLiteral("integer"),
       QStringLiteral("1 = None, 2 = Sign, 3 = Sign and Encrypt")}
  }),
    &setSecurityMode);
  registry.registerCommand(
    QStringLiteral("io.opcua.setIdentityType"),
    QStringLiteral("Alias of io.opcua.setAuthMode (params: type)"),
    API::makeSchema({
      {QStringLiteral("type"),
       QStringLiteral("integer"),
       QStringLiteral("0 = anonymous, 1 = username/password, 2 = X.509 certificate")}
  }),
    &setIdentityType);
  registry.registerCommand(
    QStringLiteral("io.opcua.setUserCertificate"),
    QStringLiteral("Set the X.509 identity files (params: certificate, key - paths on disk)"),
    API::makeSchema({
      {QStringLiteral("certificate"),
       QStringLiteral("string"),
       QStringLiteral("Path to the user certificate (DER or PEM)")},
      {        QStringLiteral("key"),
       QStringLiteral("string"),
       QStringLiteral("Path to the private key")                  }
  }),
    &setUserCertificate);

  registry.registerCommand(QStringLiteral("io.opcua.getCertificate"),
                           QStringLiteral("Get this installation's OPC UA client certificate"),
                           empty,
                           &getCertificate);
  registry.registerCommand(
    QStringLiteral("io.opcua.regenerateCertificate"),
    QStringLiteral("Replace the client certificate and key; every server must trust it again"),
    empty,
    &regenerateCertificate);
  registry.registerCommand(
    QStringLiteral("io.opcua.exportCertificate"),
    QStringLiteral("Write the client certificate to a file (params: path); the key is never "
                   "exported"),
    API::makeSchema({
      {QStringLiteral("path"),
       QStringLiteral("string"),
       QStringLiteral("Destination path for the DER certificate")}
  }),
    &exportCertificate);
  registry.registerCommand(QStringLiteral("io.opcua.listTrusted"),
                           QStringLiteral("List the accepted server certificates"),
                           empty,
                           &listTrusted);
  registry.registerCommand(
    QStringLiteral("io.opcua.trustServer"),
    QStringLiteral("Accept the server certificate the last attempt was refused over (params: "
                   "fingerprint)"),
    API::makeSchema({
      {QStringLiteral("fingerprint"),
       QStringLiteral("string"),
       QStringLiteral("SHA-256 fingerprint reported by the failed attempt")}
  }),
    &trustServer);
  registry.registerCommand(
    QStringLiteral("io.opcua.revokeTrust"),
    QStringLiteral("Withdraw a previously accepted server certificate (params: fingerprint)"),
    API::makeSchema({
      {QStringLiteral("fingerprint"),
       QStringLiteral("string"),
       QStringLiteral("SHA-256 fingerprint from io.opcua.listTrusted")}
  }),
    &revokeTrust);
}

API::CommandResponse API::Handlers::OpcUaHandler::setSecurityPolicy(const QString& id,
                                                                    const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("policy")))
    return missingParam(id, "policy");

  const auto requested = params.value(QStringLiteral("policy")).toString();
  auto* driver         = opcUaDriver();

  const auto policies = IO::Drivers::OpcUa::supportedPolicies();
  for (const auto& uri : policies) {
    if (uri != requested && uri.section(QLatin1Char('#'), -1) != requested)
      continue;

    driver->setSecurityPolicy(uri);
    return CommandResponse::makeSuccess(id,
                                        QJsonObject{
                                          {QStringLiteral("policy"), uri}
    });
  }

  return CommandResponse::makeError(
    id, ErrorCode::InvalidParam, QStringLiteral("Unknown or unsupported security policy"));
}

API::CommandResponse API::Handlers::OpcUaHandler::setSecurityMode(const QString& id,
                                                                  const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("mode")))
    return missingParam(id, "mode");

  const int mode = params.value(QStringLiteral("mode")).toInt();
  if (mode < 1 || mode > 3)
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("mode must be 1, 2 or 3"));

  opcUaDriver()->setSecurityMode(mode);
  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("mode"), mode}
  });
}

API::CommandResponse API::Handlers::OpcUaHandler::setIdentityType(const QString& id,
                                                                  const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("type")))
    return missingParam(id, "type");

  QJsonObject forwarded;
  forwarded.insert(QStringLiteral("mode"), params.value(QStringLiteral("type")));
  return setAuthMode(id, forwarded);
}

API::CommandResponse API::Handlers::OpcUaHandler::setUserCertificate(const QString& id,
                                                                     const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("certificate")))
    return missingParam(id, "certificate");

  if (!params.contains(QStringLiteral("key")))
    return missingParam(id, "key");

  const auto certificate = params.value(QStringLiteral("certificate")).toString();
  const auto key         = params.value(QStringLiteral("key")).toString();
  if (!QFile::exists(certificate) || !QFile::exists(key))
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("certificate and key must both exist on disk"));

  if (!API::isPathAllowed(certificate) || !API::isPathAllowed(key))
    return CommandResponse::makeError(id,
                                      ErrorCode::InvalidParam,
                                      QStringLiteral("certificate and key must be inside an "
                                                     "allowed path"));

  auto* driver = opcUaDriver();
  driver->setUserCertificatePath(certificate);
  driver->setUserKeyPath(key);
  return CommandResponse::makeSuccess(
    id,
    QJsonObject{
      {QStringLiteral("certificate"), certificate},
      {        QStringLiteral("key"),         key}
  });
}

API::CommandResponse API::Handlers::OpcUaHandler::getCertificate(const QString& id,
                                                                 const QJsonObject& params)
{
  Q_UNUSED(params)
  return CommandResponse::makeSuccess(
    id,
    QJsonObject{
      {QStringLiteral("certificate"), opcUaDriver()->certificateJson()}
  });
}

API::CommandResponse API::Handlers::OpcUaHandler::regenerateCertificate(const QString& id,
                                                                        const QJsonObject& params)
{
  Q_UNUSED(params)
  auto* driver = opcUaDriver();
  if (!driver->regenerateCertificate())
    return CommandResponse::makeError(
      id, ErrorCode::OperationFailed, QStringLiteral("The certificate could not be generated"));

  return CommandResponse::makeSuccess(
    id,
    QJsonObject{
      {QStringLiteral("certificate"), driver->certificateJson()}
  });
}

API::CommandResponse API::Handlers::OpcUaHandler::exportCertificate(const QString& id,
                                                                    const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("path")))
    return missingParam(id, "path");

  const auto path = params.value(QStringLiteral("path")).toString();
  if (!API::isPathAllowed(path, true))
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("path is not allowed"));

  if (!opcUaDriver()->exportCertificate(path))
    return CommandResponse::makeError(
      id, ErrorCode::OperationFailed, QStringLiteral("The certificate could not be written"));

  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("path"), path}
  });
}

API::CommandResponse API::Handlers::OpcUaHandler::listTrusted(const QString& id,
                                                              const QJsonObject& params)
{
  Q_UNUSED(params)
  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("trusted"), opcUaDriver()->trustedJson()}
  });
}

API::CommandResponse API::Handlers::OpcUaHandler::trustServer(const QString& id,
                                                              const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("fingerprint")))
    return missingParam(id, "fingerprint");

  const auto fingerprint = params.value(QStringLiteral("fingerprint")).toString();
  auto* driver           = opcUaDriver();
  if (!driver->trustServerCertificate(fingerprint))
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("No refused server certificate matches that fingerprint"));

  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("trusted"), driver->trustedJson()}
  });
}

API::CommandResponse API::Handlers::OpcUaHandler::revokeTrust(const QString& id,
                                                              const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("fingerprint")))
    return missingParam(id, "fingerprint");

  auto* driver = opcUaDriver();
  if (!driver->revokeServerCertificate(params.value(QStringLiteral("fingerprint")).toString()))
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("No trusted certificate has that fingerprint"));

  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("trusted"), driver->trustedJson()}
  });
}

bool IO::Drivers::OpcUa::hasSelectedEndpoint() const noexcept
{
  return m_endpointIndex >= 0 && m_endpointIndex < m_endpoints.size()
      && endpointUsable(m_endpoints.at(m_endpointIndex))
      && endpointAcceptsToken(m_endpoints.at(m_endpointIndex), m_authMode);
 * @brief Creates a session bound to this driver's thread.
IO::Drivers::OpcUaSession* IO::Drivers::OpcUa::makeSession()
  return new OpcUaSession(this);
}

IO::Drivers::OpcUaSession::Identity IO::Drivers::OpcUa::identity() const
{
  OpcUaSession::Identity out;
  out.mode            = m_authMode;
  out.username        = m_username;
  out.password        = m_password;
  out.certificatePath = m_userCertificatePath;
  out.privateKeyPath  = m_userKeyPath;
  return out;
 * @brief The endpoint URL the dial targets (selected endpoint, else the typed one).
QString IO::Drivers::OpcUa::selectedEndpointUrl() const
  if (m_endpointIndex >= 0 && m_endpointIndex < m_endpoints.size())
    return m_endpoints.at(m_endpointIndex).endpointUrl;

  return m_endpointUrl;
bool IO::Drivers::OpcUa::endpointAcceptsToken(const OpcUaTypes::Endpoint& endpoint,
  const auto wanted = authMode == 1 ? OpcUaTypes::UserTokenType::Username
                    : authMode == 2 ? OpcUaTypes::UserTokenType::Certificate
                                    : OpcUaTypes::UserTokenType::Anonymous;
  if (endpoint.userTokenTypes.isEmpty())
  return endpoint.userTokenTypes.contains(wanted);
 * @brief The endpoint actually dialed: the discovered row carrying the URL the user typed, since
 *        servers advertise their own hostname (S7, Kepware, B&R) which rarely resolves from the
 *        engineering laptop. With no row selected the CONFIGURED policy and mode are used;
 *        falling back to None there would dial unencrypted whenever Discover was not pressed.
IO::Drivers::OpcUaTypes::Endpoint IO::Drivers::OpcUa::dialEndpoint() const
  OpcUaTypes::Endpoint endpoint;
    endpoint.endpointUrl = m_endpointUrl;
    endpoint.securityPolicyUri =
      m_securityPolicy.isEmpty() ? QString::fromLatin1(kPolicyNone) : m_securityPolicy;
    endpoint.securityMode = static_cast<OpcUaTypes::SecurityMode>(m_securityMode);
  QUrl advertised(endpoint.endpointUrl);
  endpoint.endpointUrl = advertised.toString();
 * @brief Ends a failed dial exactly once: tears the session down, logs, reports the verdict and
 * @brief Last-resort dial deadline; the stack normally reports sooner.
// Session signal handlers
 * @brief The session activated: settle the dial and start the subscription.
void IO::Drivers::OpcUa::onSessionConnected()
  if (!m_session)
  m_dialTimer->stop();
  m_connecting = false;
  reportOpenFinished(true);
  subscribeAll();
  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
}

void IO::Drivers::OpcUa::onSubscriptionLost(const QString& reason)
{
  if (!isOpen())
    return;

  enterPollMode(reason.isEmpty() ? tr("the server retired the subscription") : reason);
}

QString IO::Drivers::OpcUa::describeMode(OpcUaTypes::SecurityMode mode)
{
  switch (mode) {
    case OpcUaTypes::SecurityMode::None:
      return tr("None");
    case OpcUaTypes::SecurityMode::Sign:
      return tr("Sign");
    case OpcUaTypes::SecurityMode::SignAndEncrypt:
      return tr("Sign and Encrypt");
    case OpcUaTypes::SecurityMode::Invalid:
      break;
  }

  return tr("Invalid");
}

int IO::Drivers::OpcUa::negotiatedMode() const
{
  if (m_session && m_session->isOpen())
    return static_cast<int>(m_session->securityMode());

  return m_securityMode;
}

const QStringList& IO::Drivers::OpcUa::supportedPolicies()
{
  static const QStringList k_policies = [] {
    QStringList out;
    for (const auto* uri : kPolicyUris)
      out.append(QString::fromLatin1(uri));

    return out;
  }();

  return k_policies;
}

bool IO::Drivers::OpcUa::policyIsDeprecated(const QString& policyUri)
{
  return policyUri.endsWith(QLatin1String("#Basic128Rsa15"))
      || policyUri.endsWith(QLatin1String("#Basic256"));
}

bool IO::Drivers::OpcUa::endpointUsable(const OpcUaTypes::Endpoint& endpoint) const
{
  if (endpoint.securityMode == OpcUaTypes::SecurityMode::Invalid)
    return false;

  return supportedPolicies().contains(endpoint.securityPolicyUri);
}

void IO::Drivers::OpcUa::selectBestEndpoint(const QString& previousUrl)
{
  m_endpointIndex = -1;

  int bestScore = -1;
  for (int i = 0; i < m_endpoints.size(); ++i) {
    const auto& candidate = m_endpoints.at(i);
    if (!endpointUsable(candidate) || !endpointAcceptsToken(candidate, m_authMode))
      continue;

    if (!previousUrl.isEmpty() && candidate.endpointUrl == previousUrl) {
      m_endpointIndex = i;
      return;
    }

    const bool wanted = candidate.securityPolicyUri == m_securityPolicy
                     && static_cast<int>(candidate.securityMode) == m_securityMode;
    const int score = wanted ? 1000
                    : policyIsDeprecated(candidate.securityPolicyUri)
                      ? 0
                      : supportedPolicies().indexOf(candidate.securityPolicyUri) * 10
                          + static_cast<int>(candidate.securityMode);
    if (score <= bestScore)
      continue;

    bestScore       = score;
    m_endpointIndex = i;
  }

  if (m_endpointIndex >= 0) {
    m_securityPolicy = m_endpoints.at(m_endpointIndex).securityPolicyUri;
    m_securityMode   = static_cast<int>(m_endpoints.at(m_endpointIndex).securityMode);
  }

  Q_EMIT securityChanged();
  if (m_endpointIndex >= 0)
    return;

  m_lastError = tr("No endpoint this build can open with the selected identity");
  logDriverError(tr("OPC UA Discovery"), tr("\"%1\": %2").arg(m_endpointUrl, m_lastError));
}

QStringList IO::Drivers::OpcUa::securityPolicyList() const
{
  QStringList out;
  for (const auto& uri : supportedPolicies()) {
    const auto name = uri.section(QLatin1Char('#'), -1);
    out.append(policyIsDeprecated(uri) ? tr("%1 (deprecated)").arg(name) : name);
  }

  return out;
}

QVariantList IO::Drivers::OpcUa::securityPolicyDeprecated() const
{
  QVariantList out;
  for (const auto& uri : supportedPolicies())
    out.append(policyIsDeprecated(uri));

  return out;
}

void IO::Drivers::OpcUa::setSecurityPolicy(const QString& policyUri)
{
  if (m_securityPolicy == policyUri || !supportedPolicies().contains(policyUri))
    return;

  m_securityPolicy = policyUri;
  if (m_persistent)
    m_settings.setValue("OpcUaDriver/securityPolicy", m_securityPolicy);

  if (m_securityPolicy == QLatin1String(kPolicyNone))
    m_securityMode = static_cast<int>(OpcUaTypes::SecurityMode::None);
  else if (m_securityMode <= static_cast<int>(OpcUaTypes::SecurityMode::None))
    m_securityMode = static_cast<int>(OpcUaTypes::SecurityMode::SignAndEncrypt);

  m_endpointIndex = -1;
  Q_EMIT securityChanged();
  Q_EMIT endpointIndexChanged();
}

void IO::Drivers::OpcUa::setSecurityPolicyIndex(const int index)
{
  const auto policies = supportedPolicies();
  if (index < 0 || index >= policies.size())
    return;

  setSecurityPolicy(policies.at(index));
}

void IO::Drivers::OpcUa::setSecurityMode(const int mode)
{
  const int clamped = qBound(static_cast<int>(OpcUaTypes::SecurityMode::None),
                             mode,
                             static_cast<int>(OpcUaTypes::SecurityMode::SignAndEncrypt));
  if (m_securityMode == clamped)
    return;

  m_securityMode = clamped;
  if (clamped == static_cast<int>(OpcUaTypes::SecurityMode::None))
    m_securityPolicy = QString::fromLatin1(kPolicyNone);

  if (m_persistent) {
    m_settings.setValue("OpcUaDriver/securityMode", m_securityMode);
    m_settings.setValue("OpcUaDriver/securityPolicy", m_securityPolicy);
  }

  m_endpointIndex = -1;
  Q_EMIT securityChanged();
  Q_EMIT endpointIndexChanged();
}

static QString localPath(const QString& value)
{
  if (!value.startsWith(QLatin1String("file:")))
    return value;

  return QUrl(value).toLocalFile();
}

void IO::Drivers::OpcUa::setUserCertificatePath(const QString& value)
{
  const auto path = localPath(value);
  if (m_userCertificatePath == path)
    return;

  m_userCertificatePath = path;
  if (m_persistent)
    m_settings.setValue("OpcUaDriver/userCertificate", m_userCertificatePath);

  Q_EMIT securityChanged();
}

void IO::Drivers::OpcUa::setUserKeyPath(const QString& value)
{
  const auto path = localPath(value);
  if (m_userKeyPath == path)
    return;

  m_userKeyPath = path;
  if (m_persistent)
    m_settings.setValue("OpcUaDriver/userKey", m_userKeyPath);

  Q_EMIT securityChanged();
}

QVariantMap IO::Drivers::OpcUa::certificateMap(const OpcUaTypes::CertInfo& info)
{
  return QVariantMap{
    {          QStringLiteral("valid"),           info.valid},
    {        QStringLiteral("subject"),         info.subject},
    {         QStringLiteral("issuer"),          info.issuer},
    {    QStringLiteral("fingerprint"),     info.fingerprint},
    { QStringLiteral("applicationUri"),  info.applicationUri},
    {      QStringLiteral("notBefore"),       info.notBefore},
    {       QStringLiteral("notAfter"),        info.notAfter},
    {        QStringLiteral("trusted"),         info.trusted},
    {        QStringLiteral("expired"),         info.expired},
    {    QStringLiteral("notYetValid"),     info.notYetValid},
    {QStringLiteral("hostnameMatches"), info.hostnameMatches},
  };
}

QJsonObject IO::Drivers::OpcUa::certificateObject(const OpcUaTypes::CertInfo& info)
{
  return QJsonObject{
    {          QStringLiteral("valid"),                           info.valid},
    {        QStringLiteral("subject"),                         info.subject},
    {         QStringLiteral("issuer"),                          info.issuer},
    {    QStringLiteral("fingerprint"),                     info.fingerprint},
    { QStringLiteral("applicationUri"),                  info.applicationUri},
    {      QStringLiteral("notBefore"), info.notBefore.toString(Qt::ISODate)},
    {       QStringLiteral("notAfter"),  info.notAfter.toString(Qt::ISODate)},
    {        QStringLiteral("trusted"),                         info.trusted},
    {        QStringLiteral("expired"),                         info.expired},
    {    QStringLiteral("notYetValid"),                     info.notYetValid},
    {QStringLiteral("hostnameMatches"),                 info.hostnameMatches},
  };
}

QString IO::Drivers::OpcUa::describeTrustFailure(OpcUaTypes::TrustFailure failure)
{
  switch (failure) {
    case OpcUaTypes::TrustFailure::Untrusted:
      return tr("The server certificate is not trusted");
    case OpcUaTypes::TrustFailure::Expired:
      return tr("The server certificate has expired");
    case OpcUaTypes::TrustFailure::NotYetValid:
      return tr("The server certificate is not valid yet");
    case OpcUaTypes::TrustFailure::HostnameMismatch:
      return tr("The server certificate was not issued for this host");
    case OpcUaTypes::TrustFailure::Unreadable:
      return tr("The server certificate could not be parsed");
    case OpcUaTypes::TrustFailure::None:
      break;
  }

  return {};
}

void IO::Drivers::OpcUa::reportTrustFailure(const OpcUaSession* session)
{
  if (!session || session->trustFailure() == OpcUaTypes::TrustFailure::None)
    return;

  m_pendingTrust    = session->serverCertificate();
  const auto detail = describeTrustFailure(session->trustFailure());
  const auto map    = certificateMap(m_pendingTrust);

  m_lastError = detail;
  QMetaObject::invokeMethod(
    this,
    [this, map, detail] { Q_EMIT serverCertificateUntrusted(map, detail); },
    Qt::QueuedConnection);
}

QVariantList IO::Drivers::OpcUa::trustedCertificates() const
{
  QVariantList out;
  const auto certificates = OpcUaSecurity::trustedCertificates();
  for (const auto& certificate : certificates)
    out.append(certificateMap(OpcUaSecurity::inspect(certificate, QString())));

  return out;
}

QJsonArray IO::Drivers::OpcUa::trustedJson() const
{
  QJsonArray out;
  const auto certificates = OpcUaSecurity::trustedCertificates();
  for (const auto& certificate : certificates)
    out.append(certificateObject(OpcUaSecurity::inspect(certificate, QString())));

  return out;
}

bool IO::Drivers::OpcUa::regenerateCertificate()
{
  const bool ok = OpcUaSecurity::regenerateClientIdentity();
  if (ok)
    Q_EMIT certificateChanged();

  return ok;
}

bool IO::Drivers::OpcUa::trustServerCertificate(const QString& fingerprint)
{
  const auto* peer   = sessionPeer();
  const auto pending = peer ? peer->m_pendingTrust : m_pendingTrust;
  if (fingerprint.isEmpty() || pending.fingerprint.compare(fingerprint, Qt::CaseInsensitive) != 0)
    return false;

  if (!OpcUaSecurity::trustCertificate(pending.certificate))
    return false;

  Q_EMIT certificateChanged();
  return true;
}

bool IO::Drivers::OpcUa::revokeServerCertificate(const QString& fingerprint)
{
  const bool ok = OpcUaSecurity::revokeTrust(fingerprint);
  if (ok)
    Q_EMIT certificateChanged();

  return ok;
}

tring IO::Drivers::OpcUaSecurity::storageDirectory()
{
  static const QString k_path =
    QStandardPaths::writableLocation(QStandardPaths::AppConfigLocation) + QStringLiteral("/OpcUa");
  return k_path;
}

atic bool ensureStorage()
{
  const auto root = IO::Drivers::OpcUaSecurity::storageDirectory();
  SS_ASSERT(!root.isEmpty(), return false);

  return QDir().mkpath(root + QLatin1Char('/') + QString::fromLatin1(kTrustDir));
}

atic QByteArray readFile(const QString& path)
{
  QFile file(path);
  if (!file.open(QIODevice::ReadOnly))
    return {};

  return file.readAll();
}

atic bool writeFile(const QString& path, const QByteArray& data, bool ownerOnly)
{
  SS_ASSERT(!path.isEmpty(), return false);
  SS_ASSERT(!data.isEmpty(), return false);

  QFile file(path);
  if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate))
    return false;

  if (ownerOnly && !file.setPermissions(QFileDevice::ReadOwner | QFileDevice::WriteOwner)) {
    file.close();
    (void)QFile::remove(path);
    return false;
  }

  const bool ok = file.write(data) == data.size();
  file.close();
  if (!ok)
    (void)QFile::remove(path);

  return ok;
}

ol IO::Drivers::OpcUaSecurity::regenerateClientIdentity()
{
  const auto uri  = applicationUri();
  const auto host = QSysInfo::machineHostName();

  const auto subjectUtf8 = QStringLiteral("CN=Serial Studio@%1").arg(host).toUtf8();
  const auto orgUtf8     = QByteArrayLiteral("O=Serial Studio");
  const auto dnsUtf8     = QStringLiteral("DNS:%1").arg(host).toUtf8();
  const auto uriUtf8     = QStringLiteral("URI:%1").arg(uri).toUtf8();

  UA_String subject[2] = {UA_STRING(const_cast<char*>(subjectUtf8.constData())),
                          UA_STRING(const_cast<char*>(orgUtf8.constData()))};
  UA_String altName[2] = {UA_STRING(const_cast<char*>(dnsUtf8.constData())),
                          UA_STRING(const_cast<char*>(uriUtf8.constData()))};

  UA_KeyValueMap params       = UA_KEYVALUEMAP_NULL;
  UA_UInt16 expiresIn         = kCertificateDays;
  UA_UInt16 keyBits           = kCertificateBits;
  UA_QualifiedName expiresKey = UA_QUALIFIEDNAME(0, const_cast<char*>("expires-in-days"));
  UA_QualifiedName bitsKey    = UA_QUALIFIEDNAME(0, const_cast<char*>("key-size-bits"));

  UA_Variant expiresValue;
  UA_Variant bitsValue;
  UA_Variant_setScalar(&expiresValue, &expiresIn, &UA_TYPES[UA_TYPES_UINT16]);
  UA_Variant_setScalar(&bitsValue, &keyBits, &UA_TYPES[UA_TYPES_UINT16]);
  (void)UA_KeyValueMap_set(&params, expiresKey, &expiresValue);
  (void)UA_KeyValueMap_set(&params, bitsKey, &bitsValue);

  UA_ByteString certificate = UA_BYTESTRING_NULL;
  UA_ByteString privateKey  = UA_BYTESTRING_NULL;
  const auto status         = UA_CreateCertificate(UA_Log_Stdout,
                                           subject,
                                           2,
                                           altName,
                                           2,
                                           UA_CERTIFICATEFORMAT_DER,
                                           &params,
                                           &privateKey,
                                           &certificate);
  UA_KeyValueMap_clear(&params);
  if (status != UA_STATUSCODE_GOOD)
    return false;

  const QByteArray certDer(reinterpret_cast<const char*>(certificate.data),
                           static_cast<qsizetype>(certificate.length));
  const QByteArray keyDer(reinterpret_cast<const char*>(privateKey.data),
                          static_cast<qsizetype>(privateKey.length));
  UA_ByteString_clear(&certificate);
  UA_ByteString_clear(&privateKey);

  if (!ensureStorage())
    return false;

  const auto dir      = storageDirectory();
  const auto certPath = dir + QLatin1Char('/') + QString::fromLatin1(kCertFile);
  const auto keyPath  = dir + QLatin1Char('/') + QString::fromLatin1(kKeyFile);
  const auto certTmp  = certPath + QStringLiteral(".new");
  const auto keyTmp   = keyPath + QStringLiteral(".new");

  if (!writeFile(certTmp, certDer, false) || !writeFile(keyTmp, keyDer, true)) {
    (void)QFile::remove(certTmp);
    (void)QFile::remove(keyTmp);
    return false;
  }

  (void)QFile::remove(certPath);
  (void)QFile::remove(keyPath);
  return QFile::rename(certTmp, certPath) && QFile::rename(keyTmp, keyPath);
}

ol IO::Drivers::OpcUaSecurity::ensureClientIdentity(QByteArray& certificate, QByteArray& key)
{
  certificate = clientCertificate();
  key         = clientPrivateKey();
  if (!certificate.isEmpty() && !key.isEmpty())
    return true;

  if (!regenerateClientIdentity())
    return false;

  certificate = clientCertificate();
  key         = clientPrivateKey();
  return !certificate.isEmpty() && !key.isEmpty();
}

ol IO::Drivers::OpcUaSecurity::exportClientCertificate(const QString& path)
{
  const auto certificate = clientCertificate();
  if (certificate.isEmpty() || path.isEmpty())
    return false;

  return writeFile(path, certificate, false);
}

atic QString fingerprintOf(const QByteArray& certificate)
{
  const auto digest = QCryptographicHash::hash(certificate, QCryptographicHash::Sha256);
  return QString::fromLatin1(digest.toHex()).toUpper();
}

atic QString trustedPathFor(const QString& fingerprint)
{
  static const QRegularExpression digest(QStringLiteral("\\A[0-9A-F]{64}\\z"));
  const auto upper = fingerprint.toUpper();
  if (!digest.match(upper).hasMatch())
    return {};

  return IO::Drivers::OpcUaSecurity::storageDirectory() + QLatin1Char('/')
       + QString::fromLatin1(kTrustDir) + QLatin1Char('/') + upper + QStringLiteral(".der");
}

ist<QByteArray> IO::Drivers::OpcUaSecurity::trustedCertificates()
{
  QList<QByteArray> out;
  QDir dir(storageDirectory() + QLatin1Char('/') + QString::fromLatin1(kTrustDir));
  const auto entries = dir.entryList({QStringLiteral("*.der")}, QDir::Files, QDir::Name);
  for (const auto& entry : entries) {
    const auto data = readFile(dir.filePath(entry));
    if (!data.isEmpty())
      out.append(data);
  }

  return out;
}

atic bool isTrustedFingerprint(const QString& fingerprint, const QByteArray& certificate)
{
  SS_ASSERT(!certificate.isEmpty(), return false);

  const auto path = trustedPathFor(fingerprint);
  if (path.isEmpty())
    return false;

  return readFile(path) == certificate;
}

ol IO::Drivers::OpcUaSecurity::isTrusted(const QByteArray& certificate)
{
  if (certificate.isEmpty())
    return false;

  return isTrustedFingerprint(fingerprintOf(certificate), certificate);
}

ol IO::Drivers::OpcUaSecurity::trustCertificate(const QByteArray& certificate)
{
  if (certificate.isEmpty())
    return false;

  const auto path = trustedPathFor(fingerprintOf(certificate));
  if (path.isEmpty() || !ensureStorage())
    return false;

  return writeFile(path, certificate, false);
}

ol IO::Drivers::OpcUaSecurity::revokeTrust(const QString& fingerprint)
{
  const auto path = trustedPathFor(fingerprint);
  if (path.isEmpty())
    return false;

  return QFile::remove(path);
}

yteArray IO::Drivers::OpcUaSecurity::readCertificateFile(const QString& path)
{
  const auto data = readFile(path);
  if (data.isEmpty() || !data.startsWith("-----BEGIN"))
    return data;

  mbedtls_x509_crt chain;
  mbedtls_x509_crt_init(&chain);

  auto terminated = data;
  terminated.append('\0');

  QByteArray out;
  const auto* bytes = reinterpret_cast<const unsigned char*>(terminated.constData());
  if (mbedtls_x509_crt_parse(&chain, bytes, static_cast<size_t>(terminated.size())) == 0)
    out =
      QByteArray(reinterpret_cast<const char*>(chain.raw.p), static_cast<qsizetype>(chain.raw.len));

  mbedtls_x509_crt_free(&chain);
  return out;
}

atic QDateTime toDateTime(const mbedtls_x509_time& time)
{
  const QDate date(time.year, time.mon, time.day);
  const QTime clock(time.hour, time.min, time.sec);
  if (!date.isValid() || !clock.isValid())
    return {};

  return QDateTime(date, clock, QTimeZone::UTC);
}

atic QString addressFromSan(const mbedtls_x509_buf& raw)
{
  if (raw.len == 4)
    return QHostAddress(qFromBigEndian<quint32>(raw.p)).toString();

  if (raw.len == 16) {
    Q_IPV6ADDR bytes;
    memcpy(bytes.c, raw.p, sizeof(bytes.c));
    return QHostAddress(bytes).toString();
  }

  return {};
}

atic QString distinguishedName(const mbedtls_x509_name& name)
{
  char buffer[512] = {0};
  const int length = mbedtls_x509_dn_gets(buffer, sizeof(buffer), &name);
  if (length <= 0)
    return {};

  SS_ASSERT(static_cast<size_t>(length) <= sizeof(buffer), return {});
  return QString::fromUtf8(buffer, length);
}

atic void collectAltName(const mbedtls_x509_buf& buf, QStringList& names, QString& uri)
{
  mbedtls_x509_subject_alternative_name san;
  memset(&san, 0, sizeof(san));
  if (mbedtls_x509_parse_subject_alt_name(&buf, &san) != 0)
    return;

  const auto& raw = san.san.unstructured_name;
  const auto text =
    QString::fromUtf8(reinterpret_cast<const char*>(raw.p), static_cast<qsizetype>(raw.len));

  if (san.type == MBEDTLS_X509_SAN_DNS_NAME)
    names.append(text);
  else if (san.type == MBEDTLS_X509_SAN_UNIFORM_RESOURCE_IDENTIFIER)
    uri = text;
  else if (san.type == MBEDTLS_X509_SAN_IP_ADDRESS)
    names.append(addressFromSan(raw));

  mbedtls_x509_free_subject_alt_name(&san);
}

atic QStringList subjectAltNames(const mbedtls_x509_crt& certificate, QString& uri)
{
  QStringList names;
  int visited = 0;
  for (const auto* entry = &certificate.subject_alt_names; entry && visited < kMaxSubjectAltNames;
       entry             = entry->next, ++visited) {
    if (entry->buf.p != nullptr)
      collectAltName(entry->buf, names, uri);
  }

  names.removeAll(QString());
  return names;
}

atic bool matchesAddress(const QStringList& candidates, const QHostAddress& host)
{
  for (const auto& candidate : candidates) {
    QHostAddress other;
    if (other.setAddress(candidate) && other.isEqual(host))
      return true;
  }

  return false;
}

atic bool matchesHost(const QStringList& names, const QString& subject, const QString& host)
{
  if (host.isEmpty())
    return true;

  auto candidates       = names;
  const auto commonName = subject.section(QStringLiteral("CN="), 1).section(QLatin1Char(','), 0, 0);
  if (!commonName.isEmpty())
    candidates.append(commonName.trimmed());

  QHostAddress literal;
  if (literal.setAddress(host))
    return matchesAddress(candidates, literal);

  for (const auto& candidate : candidates) {
    if (candidate.compare(host, Qt::CaseInsensitive) == 0)
      return true;

    if (!candidate.startsWith(QStringLiteral("*.")) || candidate.size() <= 2)
      continue;

    if (host.section(QLatin1Char('.'), 1).compare(candidate.mid(2), Qt::CaseInsensitive) == 0)
      return true;
  }

  return false;
}

::Drivers::OpcUaTypes::CertInfo IO::Drivers::OpcUaSecurity::inspect(const QByteArray& certificate,
                                                                      const QString& host)
{
  OpcUaTypes::CertInfo info;
  info.certificate = certificate;
  if (certificate.isEmpty())
    return info;

  SS_ASSERT(certificate.size() <= kMaxCertificateBytes, return info);
  info.fingerprint = fingerprintOf(certificate);
  info.trusted     = isTrustedFingerprint(info.fingerprint, certificate);

  mbedtls_x509_crt parsed;
  mbedtls_x509_crt_init(&parsed);

  const auto* bytes = reinterpret_cast<const unsigned char*>(certificate.constData());
  SS_ASSERT(bytes != nullptr, return info);
  if (mbedtls_x509_crt_parse_der(&parsed, bytes, static_cast<size_t>(certificate.size())) != 0) {
    mbedtls_x509_crt_free(&parsed);
    return info;
  }

  info.valid     = true;
  info.subject   = distinguishedName(parsed.subject);
  info.issuer    = distinguishedName(parsed.issuer);
  info.notBefore = toDateTime(parsed.valid_from);
  info.notAfter  = toDateTime(parsed.valid_to);

  const auto names     = subjectAltNames(parsed, info.applicationUri);
  info.hostnameMatches = matchesHost(names, info.subject, host);
  mbedtls_x509_crt_free(&parsed);

  const auto now   = QDateTime::currentDateTimeUtc();
  info.expired     = info.notAfter.isValid() && info.notAfter < now;
  info.notYetValid = info.notBefore.isValid() && info.notBefore > now;
  return info;
}

static UA_StatusCode verifyTrampoline(UA_CertificateGroup* group, const UA_ByteString* certificate)
{
  auto* session = s_verifiers.value(group, nullptr);
  if (!session || !certificate || !certificate->data)
    return UA_STATUSCODE_BADCERTIFICATEINVALID;

  return session->verifyServerCertificate(QByteArray(
    reinterpret_cast<const char*>(certificate->data), static_cast<qsizetype>(certificate->length)));
}

bool IO::Drivers::OpcUaSession::applyIdentity(const Identity& identity)
{
  SS_ASSERT(m_client != nullptr, return false);
  UA_ClientConfig* config = UA_Client_getConfig(m_client);
  SS_ASSERT(config != nullptr, return false);

  if (identity.mode == 1) {
    config->allowNonePolicyPassword = true;
    applyUsernameIdentity(identity);
    return true;
  }

  if (identity.mode != 2)
    return true;

  const auto certificate = OpcUaSecurity::readCertificateFile(identity.certificatePath);
  QFile keyFile(identity.privateKeyPath);
  if (certificate.isEmpty() || !keyFile.open(QIODevice::ReadOnly))
    return false;

  const auto privateKey = keyFile.readAll();
  UA_ByteString cert    = {static_cast<size_t>(certificate.size()),
                           reinterpret_cast<UA_Byte*>(const_cast<char*>(certificate.constData()))};
  UA_ByteString key     = {static_cast<size_t>(privateKey.size()),
                           reinterpret_cast<UA_Byte*>(const_cast<char*>(privateKey.constData()))};

  return UA_ClientConfig_setAuthenticationCert(config, cert, key) == UA_STATUSCODE_GOOD;
}

IO::Drivers::OpcUaTypes::StatusCode IO::Drivers::OpcUaSession::verifyServerCertificate(
  const QByteArray& certificate)
{
  const auto host     = QUrl(m_endpointUrl).host();
  m_serverCertificate = OpcUaSecurity::inspect(certificate, host);

  if (!m_serverCertificate.valid) {
    m_trustFailure = OpcUaTypes::TrustFailure::Unreadable;
    return UA_STATUSCODE_BADCERTIFICATEINVALID;
  }

  if (m_serverCertificate.expired) {
    m_trustFailure = OpcUaTypes::TrustFailure::Expired;
    return UA_STATUSCODE_BADCERTIFICATETIMEINVALID;
  }

  if (m_serverCertificate.notYetValid) {
    m_trustFailure = OpcUaTypes::TrustFailure::NotYetValid;
    return UA_STATUSCODE_BADCERTIFICATETIMEINVALID;
  }

  if (!m_serverCertificate.hostnameMatches) {
    m_trustFailure = OpcUaTypes::TrustFailure::HostnameMismatch;
    return UA_STATUSCODE_BADCERTIFICATEHOSTNAMEINVALID;
  }

  if (!m_serverCertificate.trusted) {
    m_trustFailure = OpcUaTypes::TrustFailure::Untrusted;
    return UA_STATUSCODE_BADCERTIFICATEUNTRUSTED;
  }

  m_trustFailure = OpcUaTypes::TrustFailure::None;
  return UA_STATUSCODE_GOOD;
}

static void subscriptionTrampoline(UA_Client* client,
                                   void* userdata,
                                   UA_UInt32,
                                   UA_CreateSubscriptionResponse* reply)
{
  Q_UNUSED(userdata)
  auto* session = sessionOf(client);
  if (!session || !reply)
    return;

  session->handleSubscriptionCreated(reply->subscriptionId,
                                     static_cast<int>(reply->revisedPublishingInterval),
                                     reply->responseHeader.serviceResult);
}

static void monitoredItemsTrampoline(UA_Client* client,
                                     void* userdata,
                                     UA_UInt32,
                                     UA_CreateMonitoredItemsResponse* reply)
{
  Q_UNUSED(userdata)
  auto* session = sessionOf(client);
  if (!session || !reply)
    return;

  QList<StatusCode> perItemStatus;
  perItemStatus.reserve(static_cast<qsizetype>(reply->resultsSize));
  for (size_t i = 0; i < reply->resultsSize; ++i)
    perItemStatus.append(reply->results[i].statusCode);

  session->handleSubscribed(perItemStatus, reply->responseHeader.serviceResult);
}

static void subscriptionLostTrampoline(UA_Client* client,
                                       UA_UInt32,
                                       void*,
                                       UA_StatusChangeNotification* notification)
{
  auto* session = sessionOf(client);
  if (!session || !notification)
    return;

  session->handleSubscriptionLost(IO::Drivers::OpcUaMarshal::statusText(notification->status));
}

static void valueTrampoline(
  UA_Client* client, UA_UInt32, void*, UA_UInt32, void* monContext, UA_DataValue* value)
{
  auto* session = sessionOf(client);
  if (!session || !monContext || !value)
    return;

  using namespace IO::Drivers::OpcUaMarshal;

  MonitoredValue notification;
  notification.tag             = *static_cast<const int*>(monContext);
  notification.status          = value->hasStatus ? value->status : kStatusGood;
  notification.sourceTimestamp = sourceTimeOf(*value);
  if (value->hasServerTimestamp)
    notification.serverTimestamp = toDateTime(value->serverTimestamp);

  if (value->hasValue)
    notification.value = toVariant(value->value);

  session->handleValue(notification);
}

bool IO::Drivers::OpcUaSession::subscribe(const QStringList& nodeIds, int publishingIntervalMs)
{
  SS_ASSERT(!nodeIds.isEmpty(), return false);
  if (!m_client || !m_open)
    return false;

  m_monitoredNodes  = nodeIds;
  m_subscriptionId  = 0;
  m_revisedInterval = qBound(kSessionMinIntervalMs, publishingIntervalMs, kSessionMaxIntervalMs);

  m_monitorTags.resize(nodeIds.size());
  for (qsizetype i = 0; i < m_monitorTags.size(); ++i)
    m_monitorTags[i] = static_cast<int>(i);

  auto request                        = UA_CreateSubscriptionRequest_default();
  request.requestedPublishingInterval = static_cast<UA_Double>(m_revisedInterval);
  request.requestedLifetimeCount      = kSessionLifetimeCount;
  request.requestedMaxKeepAliveCount  = kSessionKeepAliveCount;

  const auto status = UA_Client_Subscriptions_create_async(m_client,
                                                           request,
                                                           this,
                                                           subscriptionLostTrampoline,
                                                           nullptr,
                                                           subscriptionTrampoline,
                                                           this,
                                                           nullptr);
  if (status != UA_STATUSCODE_GOOD) {
    handleSubscribed({}, status);
    return false;
  }

  return true;
}

void IO::Drivers::OpcUaSession::handleSubscriptionCreated(quint32 subscriptionId,
                                                          int revisedIntervalMs,
                                                          OpcUaTypes::StatusCode status)
{
  if (!isGood(status)) {
    handleSubscribed({}, status);
    return;
  }

  m_subscriptionId = subscriptionId;
  if (revisedIntervalMs > 0)
    m_revisedInterval = qBound(kSessionMinIntervalMs, revisedIntervalMs, kSessionMaxIntervalMs);

  createMonitoredItems();
}

void IO::Drivers::OpcUaSession::createMonitoredItems()
{
  SS_ASSERT(m_client != nullptr, return);
  SS_ASSERT(!m_monitoredNodes.isEmpty(), return);

  const auto count = static_cast<size_t>(m_monitoredNodes.size());
  std::vector<UA_MonitoredItemCreateRequest> items(count);
  std::vector<void*> contexts(count, nullptr);
  std::vector<UA_Client_DataChangeNotificationCallback> callbacks(count, valueTrampoline);

  for (size_t i = 0; i < count; ++i) {
    const auto index = static_cast<qsizetype>(i);
    UA_NodeId nodeId;
    const bool parsed = OpcUaMarshal::nodeIdFromString(m_monitoredNodes.at(index), nodeId);
    SS_ASSERT_LOG(parsed);

    items[i]                                      = UA_MonitoredItemCreateRequest_default(nodeId);
    items[i].requestedParameters.samplingInterval = static_cast<UA_Double>(m_revisedInterval);
    contexts[i]                                   = &m_monitorTags[index];
  }

  UA_CreateMonitoredItemsRequest request;
  UA_CreateMonitoredItemsRequest_init(&request);
  request.subscriptionId     = m_subscriptionId;
  request.timestampsToReturn = UA_TIMESTAMPSTORETURN_BOTH;
  request.itemsToCreate      = items.data();
  request.itemsToCreateSize  = count;

  const auto status = UA_Client_MonitoredItems_createDataChanges_async(m_client,
                                                                       request,
                                                                       contexts.data(),
                                                                       callbacks.data(),
                                                                       nullptr,
                                                                       monitoredItemsTrampoline,
                                                                       this,
                                                                       nullptr);
  for (auto& item : items)
    UA_MonitoredItemCreateRequest_clear(&item);

  if (status != UA_STATUSCODE_GOOD)
    handleSubscribed({}, status);
}

void IO::Drivers::OpcUaSession::handleSubscribed(const QList<OpcUaTypes::StatusCode>& perItemStatus,
                                                 OpcUaTypes::StatusCode serviceStatus)
{
  auto rows               = perItemStatus;
  const qsizetype missing = m_monitoredNodes.size() - rows.size();
  if (missing > 0)
    rows.append(QList<StatusCode>(missing, serviceStatus));

  Q_EMIT subscribed(rows);
}

void IO::Drivers::OpcUaSession::handleSubscriptionLost(const QString& reason)
{
  m_subscriptionId = 0;
  Q_EMIT subscriptionLost(reason);
}

static void readTrampoline(UA_Client* client,
                           void* userdata,
                           UA_UInt32 requestId,
                           UA_ReadResponse* reply)
{
  Q_UNUSED(userdata)
  auto* session = sessionOf(client);
  if (!session || !reply)
    return;

  using namespace IO::Drivers::OpcUaMarshal;

  QList<ReadRow> rows;
  rows.reserve(static_cast<qsizetype>(reply->resultsSize));

  for (size_t i = 0; i < reply->resultsSize; ++i) {
    const auto& result = reply->results[i];

    ReadRow row;
    row.status          = result.hasStatus ? result.status : kStatusGood;
    row.sourceTimestamp = sourceTimeOf(result);
    if (result.hasServerTimestamp)
      row.serverTimestamp = toDateTime(result.serverTimestamp);

    if (result.hasValue)
      row.value = toVariant(result.value);

    rows.append(row);
  }

  session->handleRead(requestId, rows, reply->responseHeader.serviceResult);
}

bool IO::Drivers::OpcUaSession::readValues(const QStringList& nodeIds)
{
  SS_ASSERT(!nodeIds.isEmpty(), return false);
  if (!m_client || !m_open || m_readInFlight)
    return false;

  const auto total = nodeIds.size();
  const auto span  = qMin<qsizetype>(total, m_readLimit);
  if (m_pollCursor >= total)
    m_pollCursor = 0;

  QList<ReadRow> rows;
  rows.reserve(span);
  for (qsizetype i = 0; i < span; ++i) {
    ReadRow row;
    row.nodeId    = nodeIds.at((m_pollCursor + i) % total);
    row.attribute = NodeAttribute::Value;
    rows.append(row);
  }

  m_pollCursor   = (m_pollCursor + span) % total;
  m_readInFlight = sendRead(rows, InternalRead::No, true, 0);
  return m_readInFlight;
}

bool IO::Drivers::OpcUaSession::readAttributes(const QStringList& nodeIds,
                                               const QList<OpcUaTypes::NodeAttribute>& attributes,
                                               quint32 token)
{
  SS_ASSERT(!nodeIds.isEmpty(), return false);
  SS_ASSERT(!attributes.isEmpty(), return false);
  if (!m_client || !m_open)
    return false;

  QList<ReadRow> rows;
  rows.reserve(nodeIds.size() * attributes.size());
  for (const auto& nodeId : nodeIds)
    for (const auto attribute : attributes) {
      ReadRow row;
      row.nodeId    = nodeId;
      row.attribute = attribute;
      rows.append(row);
    }

  return sendRead(rows, InternalRead::No, false, token);
}

bool IO::Drivers::OpcUaSession::sendRead(const QList<OpcUaTypes::ReadRow>& rows,
                                         InternalRead internalRead,
                                         bool valueRead,
                                         quint32 token)
{
  SS_ASSERT(m_client != nullptr, return false);
  SS_ASSERT(!rows.isEmpty(), return false);

  const auto count = static_cast<size_t>(rows.size());
  std::vector<UA_ReadValueId> items(count);
  for (size_t i = 0; i < count; ++i) {
    const auto& row = rows.at(static_cast<qsizetype>(i));
    UA_ReadValueId_init(&items[i]);
    const bool parsed = OpcUaMarshal::nodeIdFromString(row.nodeId, items[i].nodeId);
    SS_ASSERT_LOG(parsed);
    items[i].attributeId = static_cast<UA_UInt32>(row.attribute);
  }

  UA_ReadRequest request;
  UA_ReadRequest_init(&request);
  request.timestampsToReturn = UA_TIMESTAMPSTORETURN_BOTH;
  request.nodesToRead        = items.data();
  request.nodesToReadSize    = count;

  UA_UInt32 requestId = 0;
  const auto status =
    UA_Client_sendAsyncReadRequest(m_client, &request, readTrampoline, this, &requestId);

  for (auto& item : items)
    UA_ReadValueId_clear(&item);

  if (status != UA_STATUSCODE_GOOD)
    return false;

  PendingRead pending;
  pending.rows         = rows;
  pending.internalRead = internalRead;
  pending.valueRead    = valueRead;
  pending.token        = token;
  m_readRequests.insert(requestId, pending);
  return true;
}

void IO::Drivers::OpcUaSession::handleRead(quint32 requestId,
                                           const QList<OpcUaTypes::ReadRow>& rows,
                                           OpcUaTypes::StatusCode status)
{
  auto pending = m_readRequests.take(requestId);
  if (pending.rows.isEmpty())
    return;

  auto merged = std::move(pending.rows);
  for (qsizetype i = 0; i < merged.size() && i < rows.size(); ++i) {
    merged[i].value           = rows.at(i).value;
    merged[i].status          = rows.at(i).status;
    merged[i].sourceTimestamp = rows.at(i).sourceTimestamp;
    merged[i].serverTimestamp = rows.at(i).serverTimestamp;
  }

  if (pending.internalRead == InternalRead::No) {
    if (pending.valueRead)
      m_readInFlight = false;

    Q_EMIT readFinished(pending.token, merged, status);
    return;
  }

  if (pending.internalRead == InternalRead::NamespaceArray) {
    m_namespaceArray.clear();
    const auto entries = merged.first().value.toList();
    for (const auto& entry : entries)
      m_namespaceArray.append(entry.toString());

    return;
  }

  const int limit = merged.first().value.toInt();
  if (limit > 0)
    m_readLimit = qBound(1, limit, kSessionDefaultReadLimit * 10);
}

void IO::Drivers::OpcUaSession::requestServerLimits()
{
  SS_ASSERT(m_client != nullptr, return);

  ReadRow row;
  row.nodeId      = QString::fromLatin1(kNodeMaxNodesPerRead);
  row.attribute   = NodeAttribute::Value;
  const bool sent = sendRead({row}, InternalRead::ReadLimit, false, 0);
  SS_ASSERT_LOG(sent);
}

void IO::Drivers::OpcUaSession::requestNamespaceArray()
{
  SS_ASSERT(m_client != nullptr, return);

  ReadRow row;
  row.nodeId    = QString::fromLatin1(kNodeNamespaceArray);
  row.attribute = NodeAttribute::Value;

  const bool sent = sendRead({row}, InternalRead::NamespaceArray, false, 0);
  SS_ASSERT_LOG(sent);
}

static void browseTrampoline(UA_Client* client,
                             void* userdata,
                             UA_UInt32 requestId,
                             UA_BrowseResponse* reply)
{
  Q_UNUSED(userdata)
  auto* session = sessionOf(client);
  if (!session || !reply)
    return;

  using namespace IO::Drivers::OpcUaMarshal;

  auto status = reply->responseHeader.serviceResult;

  QList<ReferenceRow> children;
  for (size_t r = 0; r < reply->resultsSize; ++r) {
    const auto& result = reply->results[r];
    if (!isGood(result.statusCode))
      status = result.statusCode;

    for (size_t i = 0; i < result.referencesSize; ++i) {
      const auto& reference = result.references[i];

      ReferenceRow row;
      row.nodeId       = nodeIdToString(reference.nodeId.nodeId);
      row.namespaceUri = toQString(reference.nodeId.namespaceUri);
      row.browseName   = toQString(reference.browseName.name);
      row.displayName  = toQString(reference.displayName.text);
      row.nodeClass    = toNodeClass(static_cast<quint32>(reference.nodeClass));
      children.append(row);
    }
  }

  session->handleBrowse(requestId, children, status);
}

bool IO::Drivers::OpcUaSession::browse(const QString& nodeId, const OpcUaTypes::BrowseQuery& query)
{
  SS_ASSERT(!nodeId.isEmpty(), return false);
  if (!m_client || !m_open)
    return false;

  UA_BrowseDescription description;
  UA_BrowseDescription_init(&description);
  const bool parsed = OpcUaMarshal::nodeIdFromString(nodeId, description.nodeId);
  SS_ASSERT_LOG(parsed);

  description.browseDirection = UA_BROWSEDIRECTION_FORWARD;
  description.includeSubtypes = true;
  description.nodeClassMask   = static_cast<UA_UInt32>(query.nodeClassMask);
  description.resultMask      = UA_BROWSERESULTMASK_ALL;
  description.referenceTypeId = query.kind == OpcUaTypes::ReferenceKind::HasProperty
                                ? UA_NODEID_NUMERIC(0, UA_NS0ID_HASPROPERTY)
                                : UA_NODEID_NUMERIC(0, UA_NS0ID_HIERARCHICALREFERENCES);

  UA_BrowseRequest request;
  UA_BrowseRequest_init(&request);
  request.requestedMaxReferencesPerNode = kSessionMaxRefsPerNode;
  request.nodesToBrowse                 = &description;
  request.nodesToBrowseSize             = 1;

  UA_UInt32 requestId = 0;
  const auto status =
    UA_Client_sendAsyncBrowseRequest(m_client, &request, browseTrampoline, this, &requestId);

  UA_BrowseDescription_clear(&description);
  if (status != UA_STATUSCODE_GOOD)
    return false;

  PendingBrowse pending;
  pending.nodeId = nodeId;
  pending.token  = query.token;
  m_browseRequests.insert(requestId, pending);
  return true;
}

void IO::Drivers::OpcUaSession::handleBrowse(quint32 requestId,
                                             const QList<OpcUaTypes::ReferenceRow>& children,
                                             OpcUaTypes::StatusCode status)
{
  const auto pending = m_browseRequests.take(requestId);
  if (pending.nodeId.isEmpty())
    return;

  Q_EMIT browseFinished(pending.token, pending.nodeId, children, status);
}

bool IO::Drivers::OpcUaSession::modifyPublishingInterval(int intervalMs)
{
  if (!m_client || !m_open || m_subscriptionId == 0)
    return false;

  m_revisedInterval = qBound(kSessionMinIntervalMs, intervalMs, kSessionMaxIntervalMs);

  UA_ModifySubscriptionRequest request;
  UA_ModifySubscriptionRequest_init(&request);
  request.subscriptionId              = m_subscriptionId;
  request.requestedPublishingInterval = static_cast<UA_Double>(m_revisedInterval);
  request.requestedLifetimeCount      = kSessionLifetimeCount;
  request.requestedMaxKeepAliveCount  = kSessionKeepAliveCount;

  return UA_Client_Subscriptions_modify_async(m_client, request, nullptr, nullptr, nullptr)
      == UA_STATUSCODE_GOOD;
}

void IO::Drivers::OpcUaTagModel::onBrowseReply(quint32 token,
                                               const QString& nodeId,
                                               const QList<OpcUaTypes::ReferenceRow>& children,
                                               OpcUaTypes::StatusCode status)
{
  Q_UNUSED(nodeId)
  const auto pending = m_browseTokens.take(token);
  if (!pending.node)
    return;

  if (pending.purpose == Purpose::Level) {
    onBrowseFinished(pending.node, children, status);
    return;
  }

  if (pending.purpose == Purpose::Probe) {
    onProbeFinished(pending.node, children, status);
    return;
  }

  if (OpcUaTypes::isGood(status))
    onUnitsBrowsed(pending.node, children);

  --m_unitsInFlight;
  pumpUnitQueue();
}

void IO::Drivers::OpcUaTagModel::onProbeFinished(Node* node,
                                                 const QList<OpcUaTypes::ReferenceRow>& children,
                                                 OpcUaTypes::StatusCode status)
{
  SS_ASSERT(node != nullptr, return);
  node->probing = false;
  node->probed  = true;
  if (OpcUaTypes::isGood(status) && !node->fetched)
    node->expandable = !children.isEmpty();

  const auto index = indexOf(node);
  Q_EMIT dataChanged(index, index);

  --m_probesInFlight;
  pumpProbeQueue();
}

void TstEnumLabels::opcUaSecuritySlugsAreWellFormedAndUnique()
{
  QSet<QString> policies;
  for (int i = 0; i <= 5; ++i) {
    const auto slug = API::EnumLabels::securityPolicySlug(i);
    QVERIFY(isWellFormedSlug(slug));
    QVERIFY(!policies.contains(slug));
    QVERIFY(!API::EnumLabels::securityPolicyLabel(i).isEmpty());
    policies.insert(slug);
  }

  QSet<QString> modes;
  for (int i = 1; i <= 3; ++i) {
    const auto slug = API::EnumLabels::securityModeSlug(i);
    QVERIFY(isWellFormedSlug(slug));
    QVERIFY(!modes.contains(slug));
    QVERIFY(!API::EnumLabels::securityModeLabel(i).isEmpty());
    modes.insert(slug);
  }

  QSet<QString> tokens;
  for (int i = 0; i <= 3; ++i) {
    const auto slug = API::EnumLabels::identityTokenSlug(i);
    QVERIFY(isWellFormedSlug(slug));
    QVERIFY(!tokens.contains(slug));
    QVERIFY(!API::EnumLabels::identityTokenLabel(i).isEmpty());
    tokens.insert(slug);
  }
}

void TstEnumLabels::opcUaSecurityUnknownValuesFallBack()
{
  QCOMPARE(API::EnumLabels::securityPolicySlug(99), QStringLiteral("unknown"));
  QCOMPARE(API::EnumLabels::securityPolicyLabel(-1), QStringLiteral("Unknown"));
  QCOMPARE(API::EnumLabels::securityModeSlug(0), QStringLiteral("unknown"));
  QCOMPARE(API::EnumLabels::securityModeLabel(4), QStringLiteral("Unknown"));
  QCOMPARE(API::EnumLabels::identityTokenSlug(9), QStringLiteral("unknown"));
  QCOMPARE(API::EnumLabels::identityTokenLabel(9), QStringLiteral("Unknown"));
}

void IO::Drivers::OpcUa::setSessionPeer(OpcUa* peer)
{
  SS_ASSERT(peer != this, return);
  if (m_sessionPeer == peer)
    return;

  m_sessionPeer = peer;
  if (peer)
    connect(
      peer, &QObject::destroyed, this, &IO::Drivers::OpcUa::statusChanged, Qt::UniqueConnection);

  Q_EMIT statusChanged();
}

tring IO::Drivers::OpcUaMarshal::toQString(const UA_String& string)
{
  if (!string.data || string.length == 0)
    return {};

  return QString::fromUtf8(reinterpret_cast<const char*>(string.data),
                           static_cast<qsizetype>(string.length));
}

tring IO::Drivers::OpcUaMarshal::nodeIdToString(const UA_NodeId& id)
{
  UA_String text = UA_STRING_NULL;
  if (UA_NodeId_print(&id, &text) != UA_STATUSCODE_GOOD)
    return {};

  const auto out = toQString(text);
  UA_String_clear(&text);
  return out;
}

ol IO::Drivers::OpcUaMarshal::nodeIdFromString(const QString& text, UA_NodeId& out)
{
  UA_NodeId_init(&out);
  const auto utf8 = text.toUtf8();

  UA_String view;
  view.length = static_cast<size_t>(utf8.size());
  view.data   = reinterpret_cast<UA_Byte*>(const_cast<char*>(utf8.constData()));
  return UA_NodeId_parse(&out, view) == UA_STATUSCODE_GOOD;
}

ateTime IO::Drivers::OpcUaMarshal::toDateTime(UA_DateTime timestamp)
{
  if (timestamp == 0)
    return {};

  const qint64 msecs = (timestamp - UA_DATETIME_UNIX_EPOCH) / UA_DATETIME_MSEC;
  return QDateTime::fromMSecsSinceEpoch(msecs, QTimeZone::UTC);
}

ateTime IO::Drivers::OpcUaMarshal::sourceTimeOf(const UA_DataValue& value)
{
  if (!value.hasSourceTimestamp)
    return {};

  return toDateTime(value.sourceTimestamp);
}

atic QVariant scalarAt(const void* data, quint32 kind)
{
  SS_ASSERT(data != nullptr, return {});

  switch (kind) {
    case UA_DATATYPEKIND_BOOLEAN:
      return QVariant(*static_cast<const UA_Boolean*>(data));
    case UA_DATATYPEKIND_SBYTE:
      return QVariant(static_cast<int>(*static_cast<const UA_SByte*>(data)));
    case UA_DATATYPEKIND_BYTE:
      return QVariant(static_cast<uint>(*static_cast<const UA_Byte*>(data)));
    case UA_DATATYPEKIND_INT16:
      return QVariant(static_cast<int>(*static_cast<const UA_Int16*>(data)));
    case UA_DATATYPEKIND_UINT16:
      return QVariant(static_cast<uint>(*static_cast<const UA_UInt16*>(data)));
    case UA_DATATYPEKIND_INT32:
      return QVariant(static_cast<int>(*static_cast<const UA_Int32*>(data)));
    case UA_DATATYPEKIND_UINT32:
      return QVariant(static_cast<uint>(*static_cast<const UA_UInt32*>(data)));
    case UA_DATATYPEKIND_INT64:
      return QVariant(static_cast<qint64>(*static_cast<const UA_Int64*>(data)));
    case UA_DATATYPEKIND_UINT64:
      return QVariant(static_cast<quint64>(*static_cast<const UA_UInt64*>(data)));
    case UA_DATATYPEKIND_FLOAT:
      return QVariant(static_cast<float>(*static_cast<const UA_Float*>(data)));
    case UA_DATATYPEKIND_DOUBLE:
      return QVariant(static_cast<double>(*static_cast<const UA_Double*>(data)));
    case UA_DATATYPEKIND_STATUSCODE:
      return QVariant(static_cast<uint>(*static_cast<const UA_StatusCode*>(data)));
    default:
      break;
  }

  return {};
}

atic QVariant wrapperAt(const void* data, const UA_DataType* type)
{
  SS_ASSERT(data != nullptr, return {});
  SS_ASSERT(type != nullptr, return {});
  using namespace IO::Drivers::OpcUaMarshal;

  switch (type->typeKind) {
    case UA_DATATYPEKIND_STRING:
    case UA_DATATYPEKIND_BYTESTRING:
    case UA_DATATYPEKIND_XMLELEMENT:
      return toQString(*static_cast<const UA_String*>(data));
    case UA_DATATYPEKIND_DATETIME:
      return toDateTime(*static_cast<const UA_DateTime*>(data));
    case UA_DATATYPEKIND_LOCALIZEDTEXT:
      return toQString(static_cast<const UA_LocalizedText*>(data)->text);
    case UA_DATATYPEKIND_QUALIFIEDNAME:
      return toQString(static_cast<const UA_QualifiedName*>(data)->name);
    case UA_DATATYPEKIND_NODEID:
      return nodeIdToString(*static_cast<const UA_NodeId*>(data));
    default:
      break;
  }

  if (type == &UA_TYPES[UA_TYPES_EUINFORMATION])
    return toQString(static_cast<const UA_EUInformation*>(data)->displayName.text);

  if (type == &UA_TYPES[UA_TYPES_RANGE])
    return QVariant(static_cast<const UA_Range*>(data)->low);

  return {};
}

atic QVariant elementOf(const UA_Variant& variant, size_t index)
{
  SS_ASSERT(variant.type != nullptr, return {});

  const auto* bytes = static_cast<const quint8*>(variant.data);
  SS_ASSERT(bytes != nullptr, return {});

  const void* element = bytes + (index * variant.type->memSize);

  const auto scalar = scalarAt(element, variant.type->typeKind);
  if (scalar.isValid())
    return scalar;

  return wrapperAt(element, variant.type);
}

ariant IO::Drivers::OpcUaMarshal::toVariant(const UA_Variant& variant)
{
  if (!variant.type || !variant.data)
    return {};

  if (UA_Variant_isScalar(&variant))
    return elementOf(variant, 0);

  QVariantList list;
  list.reserve(static_cast<qsizetype>(variant.arrayLength));
  for (size_t i = 0; i < variant.arrayLength; ++i)
    list.append(elementOf(variant, i));

  return list;
}

::Drivers::OpcUaTypes::SecurityMode IO::Drivers::OpcUaMarshal::toSecurityMode(int mode) noexcept
{
  if (mode < static_cast<int>(OpcUaTypes::SecurityMode::None)
      || mode > static_cast<int>(OpcUaTypes::SecurityMode::SignAndEncrypt))
    return OpcUaTypes::SecurityMode::Invalid;

  return static_cast<OpcUaTypes::SecurityMode>(mode);
}

::Drivers::OpcUaTypes::UserTokenType IO::Drivers::OpcUaMarshal::toUserTokenType(int type) noexcept
{
  if (type < static_cast<int>(OpcUaTypes::UserTokenType::Anonymous)
      || type > static_cast<int>(OpcUaTypes::UserTokenType::IssuedToken))
    return OpcUaTypes::UserTokenType::Anonymous;

  return static_cast<OpcUaTypes::UserTokenType>(type);
}

::Drivers::OpcUaSession::OpcUaSession(QObject* parent)
  : QObject(parent)
  , m_connecting(false)
  , m_open(false)
  , m_readInFlight(false)
  , m_intent(Intent::Idle)
  , m_readLimit(kDefaultReadLimit)
  , m_subscriptionId(0)
  , m_pump(new QTimer(this))
  , m_client(nullptr)
{
  m_pump->setInterval(kPumpIntervalMs);
  m_pump->setTimerType(Qt::CoarseTimer);
  connect(m_pump, &QTimer::timeout, this, &IO::Drivers::OpcUaSession::pump);
}

id IO::Drivers::OpcUaSession::teardown()
{
  m_pump->stop();

  if (!m_client) {
    m_open           = false;
    m_connecting     = false;
    m_intent         = Intent::Idle;
    m_readInFlight   = false;
    m_subscriptionId = 0;
    return;
  }

  auto* client = m_client;
  m_client     = nullptr;

  UA_ClientConfig* config = UA_Client_getConfig(client);
  if (config) {
    config->clientContext = nullptr;
    config->stateCallback = nullptr;
  }

  UA_Client_delete(client);

  m_open           = false;
  m_connecting     = false;
  m_intent         = Intent::Idle;
  m_readInFlight   = false;
  m_subscriptionId = 0;
  m_monitoredNodes.clear();
  m_browseRequests.clear();
}

id IO::Drivers::OpcUaSession::close()
{
  if (!m_client)
    return;

  if (s_inPump) {
    m_open       = false;
    m_connecting = false;
    m_intent     = Intent::Idle;
    QMetaObject::invokeMethod(this, [this] { teardown(); }, Qt::QueuedConnection);
    return;
  }

  teardown();
}

id IO::Drivers::OpcUaSession::pump()
{
  if (!m_client)
    return;

  s_inPump          = true;
  const auto status = UA_Client_run_iterate(m_client, 0);
  s_inPump          = false;

  if (status == UA_STATUSCODE_GOOD || !m_open)
    return;

  m_open = false;
  Q_EMIT disconnected();
}

id IO::Drivers::OpcUaSession::startPump()
{
  if (!m_pump->isActive())
    m_pump->start();
}

atic IO::Drivers::OpcUaSession* sessionOf(UA_Client* client)
{
  if (!client)
    return nullptr;

  UA_ClientConfig* config = UA_Client_getConfig(client);
  if (!config)
    return nullptr;

  return static_cast<IO::Drivers::OpcUaSession*>(config->clientContext);
}

atic void stateTrampoline(UA_Client* client,
                            UA_SecureChannelState channelState,
                            UA_SessionState sessionState,
                            UA_StatusCode status)
{
  auto* session = sessionOf(client);
  if (!session)
    return;

  QMetaObject::invokeMethod(
    session,
    [session, channelState, sessionState, status] {
      session->handleStateChanged(
        static_cast<int>(channelState), static_cast<int>(sessionState), status);
    },
    Qt::DirectConnection);
}

ol IO::Drivers::OpcUaSession::ensureClient()
{
  teardown();

  m_client = UA_Client_new();
  if (!m_client)
    return false;

  UA_ClientConfig* config = UA_Client_getConfig(m_client);
  if (!config || UA_ClientConfig_setDefault(config) != UA_STATUSCODE_GOOD) {
    teardown();
    return false;
  }

  config->clientContext = this;
  config->stateCallback = stateTrampoline;
  config->timeout       = static_cast<UA_UInt32>(kRequestTimeoutMs);
  return true;
}

id IO::Drivers::OpcUaSession::failDial(const QString& reason)
{
  if (!m_connecting)
    return;

  m_connecting = false;
  m_intent     = Intent::Idle;
  m_lastReason = reason;
  close();

  Q_EMIT connectFailed(reason);
}

id IO::Drivers::OpcUaSession::handleStateChanged(int channelState,
                                                   int sessionState,
                                                   OpcUaTypes::StatusCode status)
{
  if (m_intent == Intent::Discovering && channelState == UA_SECURECHANNELSTATE_OPEN) {
    requestEndpoints();
    return;
  }

  if (sessionState == UA_SESSIONSTATE_ACTIVATED && !m_open) {
    m_open       = true;
    m_connecting = false;
    m_intent     = Intent::Idle;
    Q_EMIT connected();
    return;
  }

  if (channelState != UA_SECURECHANNELSTATE_CLOSED)
    return;

  if (m_connecting) {
    const auto reason =
      isGood(status) ? tr("The server closed the connection") : OpcUaMarshal::statusText(status);
    failDial(reason);
    return;
  }

  if (m_open) {
    m_open = false;
    Q_EMIT disconnected();
  }
}

ol IO::Drivers::OpcUaSession::discoverEndpoints(const QString& url)
{
  if (!ensureClient())
    return false;

  m_endpointUrl = url;
  m_intent      = Intent::Discovering;

  const auto utf8 = url.toUtf8();
  if (UA_Client_connectSecureChannelAsync(m_client, utf8.constData()) != UA_STATUSCODE_GOOD) {
    m_intent = Intent::Idle;
    teardown();
    return false;
  }

  startPump();
  return true;
}

atic void endpointsTrampoline(UA_Client* client, void* userdata, UA_UInt32, void* response)
{
  Q_UNUSED(userdata)
  auto* session = sessionOf(client);
  if (!session || !response)
    return;

  auto* reply = static_cast<UA_GetEndpointsResponse*>(response);
  QList<Endpoint> endpoints;
  endpoints.reserve(static_cast<qsizetype>(reply->endpointsSize));

  for (size_t i = 0; i < reply->endpointsSize; ++i) {
    const auto& source = reply->endpoints[i];

    Endpoint endpoint;
    endpoint.endpointUrl       = IO::Drivers::OpcUaMarshal::toQString(source.endpointUrl);
    endpoint.securityPolicyUri = IO::Drivers::OpcUaMarshal::toQString(source.securityPolicyUri);
    endpoint.applicationUri    = IO::Drivers::OpcUaMarshal::toQString(source.server.applicationUri);
    endpoint.securityMode =
      IO::Drivers::OpcUaMarshal::toSecurityMode(static_cast<int>(source.securityMode));
    endpoint.securityLevel = source.securityLevel;

    for (size_t t = 0; t < source.userIdentityTokensSize; ++t)
      endpoint.userTokenTypes.append(IO::Drivers::OpcUaMarshal::toUserTokenType(
        static_cast<int>(source.userIdentityTokens[t].tokenType)));

    endpoints.append(endpoint);
  }

  session->handleEndpoints(endpoints, reply->responseHeader.serviceResult);
}

id IO::Drivers::OpcUaSession::requestEndpoints()
{
  SS_ASSERT(m_client != nullptr, return);
  m_intent = Intent::Idle;

  const auto utf8 = m_endpointUrl.toUtf8();

  UA_GetEndpointsRequest request;
  UA_GetEndpointsRequest_init(&request);
  request.endpointUrl.length = static_cast<size_t>(utf8.size());
  request.endpointUrl.data   = reinterpret_cast<UA_Byte*>(const_cast<char*>(utf8.constData()));

  const auto status = __UA_Client_AsyncService(m_client,
                                               &request,
                                               &UA_TYPES[UA_TYPES_GETENDPOINTSREQUEST],
                                               endpointsTrampoline,
                                               &UA_TYPES[UA_TYPES_GETENDPOINTSRESPONSE],
                                               this,
                                               nullptr);
  if (status != UA_STATUSCODE_GOOD)
    handleEndpoints({}, status);
}

id IO::Drivers::OpcUaSession::handleEndpoints(const QList<OpcUaTypes::Endpoint>& endpoints,
                                                OpcUaTypes::StatusCode status)
{
  Q_EMIT endpointsReady(endpoints, status);
  close();
}

ol IO::Drivers::OpcUaSession::connectToEndpoint(const QString& url, const Identity& identity)
{
  if (!ensureClient())
    return false;

  m_endpointUrl = url;
  m_intent      = Intent::Connecting;
  m_connecting  = true;

  if (identity.mode == 1)
    applyUsernameIdentity(identity);

  const auto utf8   = url.toUtf8();
  const auto status = UA_Client_connectAsync(m_client, utf8.constData());
  if (status != UA_STATUSCODE_GOOD) {
    failDial(OpcUaMarshal::statusText(status));
    return false;
  }

  startPump();
  return true;
}

id IO::Drivers::OpcUaSession::applyUsernameIdentity(const Identity& identity)
{
  SS_ASSERT(m_client != nullptr, return);

  UA_ClientConfig* config = UA_Client_getConfig(m_client);
  SS_ASSERT(config != nullptr, return);

  auto* token = UA_UserNameIdentityToken_new();
  if (!token)
    return;

  UA_UserNameIdentityToken_init(token);
  token->userName = UA_STRING_ALLOC(identity.username.toUtf8().constData());
  token->password = UA_STRING_ALLOC(identity.password.toUtf8().constData());

  UA_ExtensionObject_clear(&config->userIdentityToken);
  UA_ExtensionObject_setValue(
    &config->userIdentityToken, token, &UA_TYPES[UA_TYPES_USERNAMEIDENTITYTOKEN]);
}

nodiscard]] static UA_Variant scalarVariant(void* data, quint16 typeIndex)
{
  UA_Variant variant;
  UA_Variant_init(&variant);
  variant.type        = &UA_TYPES[typeIndex];
  variant.storageType = UA_VARIANT_DATA_NODELETE;
  variant.data        = data;
  variant.arrayLength = 0;
  return variant;
}

nodiscard]] static UA_Variant arrayVariant(void* data, size_t count, quint16 typeIndex)
{
  UA_Variant variant  = scalarVariant(data, typeIndex);
  variant.arrayLength = count;
  return variant;
}

id TstOpcUaMarshal::numericScalarsRoundTrip()
{
  UA_Boolean flag = true;
  auto value      = scalarVariant(&flag, UA_TYPES_BOOLEAN);
  QCOMPARE(OpcUaMarshal::toVariant(value).toBool(), true);

  UA_Int32 i32 = -1234567;
  value        = scalarVariant(&i32, UA_TYPES_INT32);
  QCOMPARE(OpcUaMarshal::toVariant(value).toInt(), -1234567);

  UA_UInt32 u32 = 4000000000u;
  value         = scalarVariant(&u32, UA_TYPES_UINT32);
  QCOMPARE(OpcUaMarshal::toVariant(value).toUInt(), 4000000000u);

  UA_Int64 i64 = Q_INT64_C(-9007199254740993);
  value        = scalarVariant(&i64, UA_TYPES_INT64);
  QCOMPARE(OpcUaMarshal::toVariant(value).toLongLong(), Q_INT64_C(-9007199254740993));

  UA_Double dbl = 3.5;
  value         = scalarVariant(&dbl, UA_TYPES_DOUBLE);
  QCOMPARE(OpcUaMarshal::toVariant(value).toDouble(), 3.5);

  UA_Float flt = 0.5f;
  value        = scalarVariant(&flt, UA_TYPES_FLOAT);
  QCOMPARE(OpcUaMarshal::toVariant(value).toFloat(), 0.5f);

  UA_SByte sbyte = -128;
  value          = scalarVariant(&sbyte, UA_TYPES_SBYTE);
  QCOMPARE(OpcUaMarshal::toVariant(value).toInt(), -128);

  UA_Int16 i16 = -32768;
  value        = scalarVariant(&i16, UA_TYPES_INT16);
  QCOMPARE(OpcUaMarshal::toVariant(value).toInt(), -32768);
}

id TstOpcUaMarshal::stringAndTextValues()
{
  UA_String text = UA_STRING_STATIC("FILLING");
  auto value     = scalarVariant(&text, UA_TYPES_STRING);
  QCOMPARE(OpcUaMarshal::toVariant(value).toString(), QStringLiteral("FILLING"));

  UA_LocalizedText localized;
  localized.locale = UA_STRING_STATIC("en");
  localized.text   = UA_STRING_STATIC("Filler Level");
  value            = scalarVariant(&localized, UA_TYPES_LOCALIZEDTEXT);
  QCOMPARE(OpcUaMarshal::toVariant(value).toString(), QStringLiteral("Filler Level"));

  UA_String empty;
  empty.length = 0;
  empty.data   = nullptr;
  value        = scalarVariant(&empty, UA_TYPES_STRING);
  QVERIFY(OpcUaMarshal::toVariant(value).toString().isEmpty());
}

id TstOpcUaMarshal::engineeringUnitWrappers()
{
  UA_EUInformation unit;
  UA_EUInformation_init(&unit);
  unit.displayName.text = UA_STRING_STATIC("%");
  auto value            = scalarVariant(&unit, UA_TYPES_EUINFORMATION);
  QCOMPARE(OpcUaMarshal::toVariant(value).toString(), QStringLiteral("%"));

  UA_Range range;
  range.low  = -50.0;
  range.high = 250.0;
  value      = scalarVariant(&range, UA_TYPES_RANGE);
  QCOMPARE(OpcUaMarshal::toVariant(value).toDouble(), -50.0);
}

id TstOpcUaMarshal::arraysBecomeVariantLists()
{
  UA_Double zones[6] = {60.0, 61.5, 63.0, 64.5, 66.0, 67.5};
  const auto value   = arrayVariant(zones, 6, UA_TYPES_DOUBLE);

  const auto converted = OpcUaMarshal::toVariant(value);
  QCOMPARE(converted.typeId(), QMetaType::QVariantList);

  const auto list = converted.toList();
  QCOMPARE(list.size(), 6);
  QCOMPARE(list.at(0).toDouble(), 60.0);
  QCOMPARE(list.at(5).toDouble(), 67.5);
}

id TstOpcUaMarshal::nodeIdsRoundTrip()
{
  const QString stringId = QStringLiteral("ns=2;s=Plant.Line1.Filler.Level_pct");

  UA_NodeId parsed;
  QVERIFY(OpcUaMarshal::nodeIdFromString(stringId, parsed));
  QCOMPARE(parsed.namespaceIndex, static_cast<UA_UInt16>(2));
  QCOMPARE(OpcUaMarshal::nodeIdToString(parsed), stringId);
  UA_NodeId_clear(&parsed);

  const QString numericId = QStringLiteral("ns=2;i=5000");
  QVERIFY(OpcUaMarshal::nodeIdFromString(numericId, parsed));
  QCOMPARE(OpcUaMarshal::nodeIdToString(parsed), numericId);
  UA_NodeId_clear(&parsed);

  UA_NodeId rejected;
  QVERIFY(!OpcUaMarshal::nodeIdFromString(QStringLiteral("not a node id"), rejected));
  UA_NodeId_clear(&rejected);
}

id TstOpcUaMarshal::statusSeverityClassification()
{
  using namespace OpcUaTypes;

  QVERIFY(isGood(UA_STATUSCODE_GOOD));
  QVERIFY(!isBad(UA_STATUSCODE_GOOD));
  QVERIFY(!isUncertain(UA_STATUSCODE_GOOD));

  QVERIFY(isUncertain(UA_STATUSCODE_UNCERTAIN));
  QVERIFY(!isBad(UA_STATUSCODE_UNCERTAIN));
  QVERIFY(!isGood(UA_STATUSCODE_UNCERTAIN));

  QVERIFY(isBad(UA_STATUSCODE_BADINTERNALERROR));
  QVERIFY(isBad(UA_STATUSCODE_BADNODEIDUNKNOWN));
  QVERIFY(!isGood(UA_STATUSCODE_BADNODEIDUNKNOWN));

  QVERIFY(!OpcUaMarshal::statusText(UA_STATUSCODE_BADNODEIDUNKNOWN).isEmpty());
}

id TstOpcUaMarshal::sourceTimestampIsPreserved()
{
  const QDateTime expected =
    QDateTime::fromMSecsSinceEpoch(Q_INT64_C(1755000000000), QTimeZone::UTC);

  UA_DataValue value;
  UA_DataValue_init(&value);
  value.hasSourceTimestamp = true;
  value.sourceTimestamp    = (Q_INT64_C(1755000000000) * UA_DATETIME_MSEC) + UA_DATETIME_UNIX_EPOCH;

  const auto stamped = OpcUaMarshal::sourceTimeOf(value);
  QVERIFY(stamped.isValid());
  QCOMPARE(stamped.toUTC(), expected);
}

id TstOpcUaMarshal::absentTimestampIsInvalid()
{
  UA_DataValue value;
  UA_DataValue_init(&value);
  value.hasSourceTimestamp = false;
  value.sourceTimestamp    = 0;
  QVERIFY(!OpcUaMarshal::sourceTimeOf(value).isValid());

  value.hasSourceTimestamp = true;
  value.sourceTimestamp    = 0;
  QVERIFY(!OpcUaMarshal::sourceTimeOf(value).isValid());

  QVERIFY(!OpcUaMarshal::toDateTime(0).isValid());
}

static void Hacl_Bignum_Modulo_carry_top(uint64_t *b)
{
  uint64_t b4 = b[4U];
  uint64_t b0 = b[0U];
  uint64_t b4_ = b4 & (uint64_t)0x7ffffffffffffU;
  uint64_t b0_ = b0 + (uint64_t)19U * (b4 >> (uint32_t)51U);
  b[4U] = b4_;
  b[0U] = b0_;
}

inline static void Hacl_Bignum_Fproduct_copy_from_wide_(uint64_t *output, uint128_t *input)
{
  uint32_t i;
  for (i = (uint32_t)0U; i < (uint32_t)5U; i = i + (uint32_t)1U)
  {
    uint128_t xi = input[i];
    output[i] = (uint64_t)xi;
  }
}

inline static void
Hacl_Bignum_Fproduct_sum_scalar_multiplication_(uint128_t *output, uint64_t *input, uint64_t s)
{
  uint32_t i;
  for (i = (uint32_t)0U; i < (uint32_t)5U; i = i + (uint32_t)1U)
  {
    uint128_t xi = output[i];
    uint64_t yi = input[i];
    output[i] = xi + (uint128_t)yi * s;
  }
}

inline static void Hacl_Bignum_Fproduct_carry_wide_(uint128_t *tmp)
{
  uint32_t i;
  for (i = (uint32_t)0U; i < (uint32_t)4U; i = i + (uint32_t)1U)
  {
    uint32_t ctr = i;
    uint128_t tctr = tmp[ctr];
    uint128_t tctrp1 = tmp[ctr + (uint32_t)1U];
    uint64_t r0 = (uint64_t)tctr & (uint64_t)0x7ffffffffffffU;
    uint128_t c = tctr >> (uint32_t)51U;
    tmp[ctr] = (uint128_t)r0;
    tmp[ctr + (uint32_t)1U] = tctrp1 + c;
  }
}

inline static void Hacl_Bignum_Fmul_shift_reduce(uint64_t *output)
{
  uint64_t tmp = output[4U];
  uint64_t b0;
  {
    uint32_t i;
    for (i = (uint32_t)0U; i < (uint32_t)4U; i = i + (uint32_t)1U)
    {
      uint32_t ctr = (uint32_t)5U - i - (uint32_t)1U;
      uint64_t z = output[ctr - (uint32_t)1U];
      output[ctr] = z;
    }
  }
  output[0U] = tmp;
  b0 = output[0U];
  output[0U] = (uint64_t)19U * b0;
}

static void
Hacl_Bignum_Fmul_mul_shift_reduce_(uint128_t *output, uint64_t *input, uint64_t *input2)
{
  uint32_t i;
  uint64_t input2i;
  {
    uint32_t i0;
    for (i0 = (uint32_t)0U; i0 < (uint32_t)4U; i0 = i0 + (uint32_t)1U)
    {
      uint64_t input2i0 = input2[i0];
      Hacl_Bignum_Fproduct_sum_scalar_multiplication_(output, input, input2i0);
      Hacl_Bignum_Fmul_shift_reduce(input);
    }
  }
  i = (uint32_t)4U;
  input2i = input2[i];
  Hacl_Bignum_Fproduct_sum_scalar_multiplication_(output, input, input2i);
}

inline static void Hacl_Bignum_Fmul_fmul(uint64_t *output, uint64_t *input, uint64_t *input2)
{
  uint64_t tmp[5U] = { 0U };
  memcpy(tmp, input, (uint32_t)5U * sizeof input[0U]);
  KRML_CHECK_SIZE(sizeof (uint128_t), (uint32_t)5U);
  {
    uint128_t t[5U];
    {
      uint32_t _i;
      for (_i = 0U; _i < (uint32_t)5U; ++_i)
        t[_i] = (uint128_t)(uint64_t)0U;
    }
    {
      uint128_t b4;
      uint128_t b0;
      uint128_t b4_;
      uint128_t b0_;
      uint64_t i0;
      uint64_t i1;
      uint64_t i0_;
      uint64_t i1_;
      Hacl_Bignum_Fmul_mul_shift_reduce_(t, tmp, input2);
      Hacl_Bignum_Fproduct_carry_wide_(t);
      b4 = t[4U];
      b0 = t[0U];
      b4_ = b4 & (uint128_t)(uint64_t)0x7ffffffffffffU;
      b0_ = b0 + (uint128_t)(uint64_t)19U * (uint64_t)(b4 >> (uint32_t)51U);
      t[4U] = b4_;
      t[0U] = b0_;
      Hacl_Bignum_Fproduct_copy_from_wide_(output, t);
      i0 = output[0U];
      i1 = output[1U];
      i0_ = i0 & (uint64_t)0x7ffffffffffffU;
      i1_ = i1 + (i0 >> (uint32_t)51U);
      output[0U] = i0_;
      output[1U] = i1_;
    }
  }
}

inline static void Hacl_Bignum_Fsquare_fsquare__(uint128_t *tmp, uint64_t *output)
{
  uint64_t r0 = output[0U];
  uint64_t r1 = output[1U];
  uint64_t r2 = output[2U];
  uint64_t r3 = output[3U];
  uint64_t r4 = output[4U];
  uint64_t d0 = r0 * (uint64_t)2U;
  uint64_t d1 = r1 * (uint64_t)2U;
  uint64_t d2 = r2 * (uint64_t)2U * (uint64_t)19U;
  uint64_t d419 = r4 * (uint64_t)19U;
  uint64_t d4 = d419 * (uint64_t)2U;
  uint128_t s0 = (uint128_t)r0 * r0 + (uint128_t)d4 * r1 + (uint128_t)d2 * r3;
  uint128_t s1 = (uint128_t)d0 * r1 + (uint128_t)d4 * r2 + (uint128_t)(r3 * (uint64_t)19U) * r3;
  uint128_t s2 = (uint128_t)d0 * r2 + (uint128_t)r1 * r1 + (uint128_t)d4 * r3;
  uint128_t s3 = (uint128_t)d0 * r3 + (uint128_t)d1 * r2 + (uint128_t)r4 * d419;
  uint128_t s4 = (uint128_t)d0 * r4 + (uint128_t)d1 * r3 + (uint128_t)r2 * r2;
  tmp[0U] = s0;
  tmp[1U] = s1;
  tmp[2U] = s2;
  tmp[3U] = s3;
  tmp[4U] = s4;
}

inline static void Hacl_Bignum_Fsquare_fsquare_(uint128_t *tmp, uint64_t *output)
{
  uint128_t b4;
  uint128_t b0;
  uint128_t b4_;
  uint128_t b0_;
  uint64_t i0;
  uint64_t i1;
  uint64_t i0_;
  uint64_t i1_;
  Hacl_Bignum_Fsquare_fsquare__(tmp, output);
  Hacl_Bignum_Fproduct_carry_wide_(tmp);
  b4 = tmp[4U];
  b0 = tmp[0U];
  b4_ = b4 & (uint128_t)(uint64_t)0x7ffffffffffffU;
  b0_ = b0 + (uint128_t)(uint64_t)19U * (uint64_t)(b4 >> (uint32_t)51U);
  tmp[4U] = b4_;
  tmp[0U] = b0_;
  Hacl_Bignum_Fproduct_copy_from_wide_(output, tmp);
  i0 = output[0U];
  i1 = output[1U];
  i0_ = i0 & (uint64_t)0x7ffffffffffffU;
  i1_ = i1 + (i0 >> (uint32_t)51U);
  output[0U] = i0_;
  output[1U] = i1_;
}

static void
Hacl_Bignum_Fsquare_fsquare_times_(uint64_t *input, uint128_t *tmp, uint32_t count1)
{
  uint32_t i;
  Hacl_Bignum_Fsquare_fsquare_(tmp, input);
  for (i = (uint32_t)1U; i < count1; i = i + (uint32_t)1U)
    Hacl_Bignum_Fsquare_fsquare_(tmp, input);
}

inline static void
Hacl_Bignum_Fsquare_fsquare_times(uint64_t *output, uint64_t *input, uint32_t count1)
{
  KRML_CHECK_SIZE(sizeof (uint128_t), (uint32_t)5U);
  {
    uint128_t t[5U];
    {
      uint32_t _i;
      for (_i = 0U; _i < (uint32_t)5U; ++_i)
        t[_i] = (uint128_t)(uint64_t)0U;
    }
    memcpy(output, input, (uint32_t)5U * sizeof input[0U]);
    Hacl_Bignum_Fsquare_fsquare_times_(output, t, count1);
  }
}

inline static void Hacl_Bignum_Fsquare_fsquare_times_inplace(uint64_t *output, uint32_t count1)
{
  KRML_CHECK_SIZE(sizeof (uint128_t), (uint32_t)5U);
  {
    uint128_t t[5U];
    {
      uint32_t _i;
      for (_i = 0U; _i < (uint32_t)5U; ++_i)
        t[_i] = (uint128_t)(uint64_t)0U;
    }
    Hacl_Bignum_Fsquare_fsquare_times_(output, t, count1);
  }
}

inline static void Hacl_Bignum_Crecip_crecip(uint64_t *out, uint64_t *z)
{
  uint64_t buf[20U] = { 0U };
  uint64_t *a0 = buf;
  uint64_t *t00 = buf + (uint32_t)5U;
  uint64_t *b0 = buf + (uint32_t)10U;
  uint64_t *t01;
  uint64_t *b1;
  uint64_t *c0;
  uint64_t *a;
  uint64_t *t0;
  uint64_t *b;
  uint64_t *c;
  Hacl_Bignum_Fsquare_fsquare_times(a0, z, (uint32_t)1U);
  Hacl_Bignum_Fsquare_fsquare_times(t00, a0, (uint32_t)2U);
  Hacl_Bignum_Fmul_fmul(b0, t00, z);
  Hacl_Bignum_Fmul_fmul(a0, b0, a0);
  Hacl_Bignum_Fsquare_fsquare_times(t00, a0, (uint32_t)1U);
  Hacl_Bignum_Fmul_fmul(b0, t00, b0);
  Hacl_Bignum_Fsquare_fsquare_times(t00, b0, (uint32_t)5U);
  t01 = buf + (uint32_t)5U;
  b1 = buf + (uint32_t)10U;
  c0 = buf + (uint32_t)15U;
  Hacl_Bignum_Fmul_fmul(b1, t01, b1);
  Hacl_Bignum_Fsquare_fsquare_times(t01, b1, (uint32_t)10U);
  Hacl_Bignum_Fmul_fmul(c0, t01, b1);
  Hacl_Bignum_Fsquare_fsquare_times(t01, c0, (uint32_t)20U);
  Hacl_Bignum_Fmul_fmul(t01, t01, c0);
  Hacl_Bignum_Fsquare_fsquare_times_inplace(t01, (uint32_t)10U);
  Hacl_Bignum_Fmul_fmul(b1, t01, b1);
  Hacl_Bignum_Fsquare_fsquare_times(t01, b1, (uint32_t)50U);
  a = buf;
  t0 = buf + (uint32_t)5U;
  b = buf + (uint32_t)10U;
  c = buf + (uint32_t)15U;
  Hacl_Bignum_Fmul_fmul(c, t0, b);
  Hacl_Bignum_Fsquare_fsquare_times(t0, c, (uint32_t)100U);
  Hacl_Bignum_Fmul_fmul(t0, t0, c);
  Hacl_Bignum_Fsquare_fsquare_times_inplace(t0, (uint32_t)50U);
  Hacl_Bignum_Fmul_fmul(t0, t0, b);
  Hacl_Bignum_Fsquare_fsquare_times_inplace(t0, (uint32_t)5U);
  Hacl_Bignum_Fmul_fmul(out, t0, a);
}

inline static void Hacl_Bignum_fsum(uint64_t *a, uint64_t *b)
{
  uint32_t i;
  for (i = (uint32_t)0U; i < (uint32_t)5U; i = i + (uint32_t)1U)
  {
    uint64_t xi = a[i];
    uint64_t yi = b[i];
    a[i] = xi + yi;
  }
}

inline static void Hacl_Bignum_fdifference(uint64_t *a, uint64_t *b)
{
  uint64_t tmp[5U] = { 0U };
  uint64_t b0;
  uint64_t b1;
  uint64_t b2;
  uint64_t b3;
  uint64_t b4;
  memcpy(tmp, b, (uint32_t)5U * sizeof b[0U]);
  b0 = tmp[0U];
  b1 = tmp[1U];
  b2 = tmp[2U];
  b3 = tmp[3U];
  b4 = tmp[4U];
  tmp[0U] = b0 + (uint64_t)0x3fffffffffff68U;
  tmp[1U] = b1 + (uint64_t)0x3ffffffffffff8U;
  tmp[2U] = b2 + (uint64_t)0x3ffffffffffff8U;
  tmp[3U] = b3 + (uint64_t)0x3ffffffffffff8U;
  tmp[4U] = b4 + (uint64_t)0x3ffffffffffff8U;
  {
    uint32_t i;
    for (i = (uint32_t)0U; i < (uint32_t)5U; i = i + (uint32_t)1U)
    {
      uint64_t xi = a[i];
      uint64_t yi = tmp[i];
      a[i] = yi - xi;
    }
  }
}

inline static void Hacl_Bignum_fscalar(uint64_t *output, uint64_t *b, uint64_t s)
{
  KRML_CHECK_SIZE(sizeof (uint128_t), (uint32_t)5U);
  {
    uint128_t tmp[5U];
    {
      uint32_t _i;
      for (_i = 0U; _i < (uint32_t)5U; ++_i)
        tmp[_i] = (uint128_t)(uint64_t)0U;
    }
    {
      uint128_t b4;
      uint128_t b0;
      uint128_t b4_;
      uint128_t b0_;
      {
        uint32_t i;
        for (i = (uint32_t)0U; i < (uint32_t)5U; i = i + (uint32_t)1U)
        {
          uint64_t xi = b[i];
          tmp[i] = (uint128_t)xi * s;
        }
      }
      Hacl_Bignum_Fproduct_carry_wide_(tmp);
      b4 = tmp[4U];
      b0 = tmp[0U];
      b4_ = b4 & (uint128_t)(uint64_t)0x7ffffffffffffU;
      b0_ = b0 + (uint128_t)(uint64_t)19U * (uint64_t)(b4 >> (uint32_t)51U);
      tmp[4U] = b4_;
      tmp[0U] = b0_;
      Hacl_Bignum_Fproduct_copy_from_wide_(output, tmp);
    }
  }
}

static void
Hacl_EC_Point_swap_conditional_step(uint64_t *a, uint64_t *b, uint64_t swap1, uint32_t ctr)
{
  uint32_t i = ctr - (uint32_t)1U;
  uint64_t ai = a[i];
  uint64_t bi = b[i];
  uint64_t x = swap1 & (ai ^ bi);
  uint64_t ai1 = ai ^ x;
  uint64_t bi1 = bi ^ x;
  a[i] = ai1;
  b[i] = bi1;
}

static void
Hacl_EC_Point_swap_conditional_(uint64_t *a, uint64_t *b, uint64_t swap1, uint32_t ctr)
{
  if (!(ctr == (uint32_t)0U))
  {
    uint32_t i;
    Hacl_EC_Point_swap_conditional_step(a, b, swap1, ctr);
    i = ctr - (uint32_t)1U;
    Hacl_EC_Point_swap_conditional_(a, b, swap1, i);
  }
}

static void Hacl_EC_Point_swap_conditional(uint64_t *a, uint64_t *b, uint64_t iswap)
{
  uint64_t swap1 = (uint64_t)0U - iswap;
  Hacl_EC_Point_swap_conditional_(a, b, swap1, (uint32_t)5U);
  Hacl_EC_Point_swap_conditional_(a + (uint32_t)5U, b + (uint32_t)5U, swap1, (uint32_t)5U);
}

static void Hacl_EC_Point_copy(uint64_t *output, uint64_t *input)
{
  memcpy(output, input, (uint32_t)5U * sizeof input[0U]);
  memcpy(output + (uint32_t)5U,
    input + (uint32_t)5U,
    (uint32_t)5U * sizeof (input + (uint32_t)5U)[0U]);
}

static void Hacl_EC_Format_fexpand(uint64_t *output, uint8_t *input)
{
  uint64_t i0 = load64_le(input);
  uint8_t *x00 = input + (uint32_t)6U;
  uint64_t i1 = load64_le(x00);
  uint8_t *x01 = input + (uint32_t)12U;
  uint64_t i2 = load64_le(x01);
  uint8_t *x02 = input + (uint32_t)19U;
  uint64_t i3 = load64_le(x02);
  uint8_t *x0 = input + (uint32_t)24U;
  uint64_t i4 = load64_le(x0);
  uint64_t output0 = i0 & (uint64_t)0x7ffffffffffffU;
  uint64_t output1 = i1 >> (uint32_t)3U & (uint64_t)0x7ffffffffffffU;
  uint64_t output2 = i2 >> (uint32_t)6U & (uint64_t)0x7ffffffffffffU;
  uint64_t output3 = i3 >> (uint32_t)1U & (uint64_t)0x7ffffffffffffU;
  uint64_t output4 = i4 >> (uint32_t)12U & (uint64_t)0x7ffffffffffffU;
  output[0U] = output0;
  output[1U] = output1;
  output[2U] = output2;
  output[3U] = output3;
  output[4U] = output4;
}

static void Hacl_EC_Format_fcontract_first_carry_pass(uint64_t *input)
{
  uint64_t t0 = input[0U];
  uint64_t t1 = input[1U];
  uint64_t t2 = input[2U];
  uint64_t t3 = input[3U];
  uint64_t t4 = input[4U];
  uint64_t t1_ = t1 + (t0 >> (uint32_t)51U);
  uint64_t t0_ = t0 & (uint64_t)0x7ffffffffffffU;
  uint64_t t2_ = t2 + (t1_ >> (uint32_t)51U);
  uint64_t t1__ = t1_ & (uint64_t)0x7ffffffffffffU;
  uint64_t t3_ = t3 + (t2_ >> (uint32_t)51U);
  uint64_t t2__ = t2_ & (uint64_t)0x7ffffffffffffU;
  uint64_t t4_ = t4 + (t3_ >> (uint32_t)51U);
  uint64_t t3__ = t3_ & (uint64_t)0x7ffffffffffffU;
  input[0U] = t0_;
  input[1U] = t1__;
  input[2U] = t2__;
  input[3U] = t3__;
  input[4U] = t4_;
}

static void Hacl_EC_Format_fcontract_first_carry_full(uint64_t *input)
{
  Hacl_EC_Format_fcontract_first_carry_pass(input);
  Hacl_Bignum_Modulo_carry_top(input);
}

static void Hacl_EC_Format_fcontract_second_carry_pass(uint64_t *input)
{
  uint64_t t0 = input[0U];
  uint64_t t1 = input[1U];
  uint64_t t2 = input[2U];
  uint64_t t3 = input[3U];
  uint64_t t4 = input[4U];
  uint64_t t1_ = t1 + (t0 >> (uint32_t)51U);
  uint64_t t0_ = t0 & (uint64_t)0x7ffffffffffffU;
  uint64_t t2_ = t2 + (t1_ >> (uint32_t)51U);
  uint64_t t1__ = t1_ & (uint64_t)0x7ffffffffffffU;
  uint64_t t3_ = t3 + (t2_ >> (uint32_t)51U);
  uint64_t t2__ = t2_ & (uint64_t)0x7ffffffffffffU;
  uint64_t t4_ = t4 + (t3_ >> (uint32_t)51U);
  uint64_t t3__ = t3_ & (uint64_t)0x7ffffffffffffU;
  input[0U] = t0_;
  input[1U] = t1__;
  input[2U] = t2__;
  input[3U] = t3__;
  input[4U] = t4_;
}

static void Hacl_EC_Format_fcontract_second_carry_full(uint64_t *input)
{
  uint64_t i0;
  uint64_t i1;
  uint64_t i0_;
  uint64_t i1_;
  Hacl_EC_Format_fcontract_second_carry_pass(input);
  Hacl_Bignum_Modulo_carry_top(input);
  i0 = input[0U];
  i1 = input[1U];
  i0_ = i0 & (uint64_t)0x7ffffffffffffU;
  i1_ = i1 + (i0 >> (uint32_t)51U);
  input[0U] = i0_;
  input[1U] = i1_;
}

static void Hacl_EC_Format_fcontract_trim(uint64_t *input)
{
  uint64_t a0 = input[0U];
  uint64_t a1 = input[1U];
  uint64_t a2 = input[2U];
  uint64_t a3 = input[3U];
  uint64_t a4 = input[4U];
  uint64_t mask0 = FStar_UInt64_gte_mask(a0, (uint64_t)0x7ffffffffffedU);
  uint64_t mask1 = FStar_UInt64_eq_mask(a1, (uint64_t)0x7ffffffffffffU);
  uint64_t mask2 = FStar_UInt64_eq_mask(a2, (uint64_t)0x7ffffffffffffU);
  uint64_t mask3 = FStar_UInt64_eq_mask(a3, (uint64_t)0x7ffffffffffffU);
  uint64_t mask4 = FStar_UInt64_eq_mask(a4, (uint64_t)0x7ffffffffffffU);
  uint64_t mask = (((mask0 & mask1) & mask2) & mask3) & mask4;
  uint64_t a0_ = a0 - ((uint64_t)0x7ffffffffffedU & mask);
  uint64_t a1_ = a1 - ((uint64_t)0x7ffffffffffffU & mask);
  uint64_t a2_ = a2 - ((uint64_t)0x7ffffffffffffU & mask);
  uint64_t a3_ = a3 - ((uint64_t)0x7ffffffffffffU & mask);
  uint64_t a4_ = a4 - ((uint64_t)0x7ffffffffffffU & mask);
  input[0U] = a0_;
  input[1U] = a1_;
  input[2U] = a2_;
  input[3U] = a3_;
  input[4U] = a4_;
}

static void Hacl_EC_Format_fcontract_store(uint8_t *output, uint64_t *input)
{
  uint64_t t0 = input[0U];
  uint64_t t1 = input[1U];
  uint64_t t2 = input[2U];
  uint64_t t3 = input[3U];
  uint64_t t4 = input[4U];
  uint64_t o0 = t1 << (uint32_t)51U | t0;
  uint64_t o1 = t2 << (uint32_t)38U | t1 >> (uint32_t)13U;
  uint64_t o2 = t3 << (uint32_t)25U | t2 >> (uint32_t)26U;
  uint64_t o3 = t4 << (uint32_t)12U | t3 >> (uint32_t)39U;
  uint8_t *b0 = output;
  uint8_t *b1 = output + (uint32_t)8U;
  uint8_t *b2 = output + (uint32_t)16U;
  uint8_t *b3 = output + (uint32_t)24U;
  store64_le(b0, o0);
  store64_le(b1, o1);
  store64_le(b2, o2);
  store64_le(b3, o3);
}

static void Hacl_EC_Format_fcontract(uint8_t *output, uint64_t *input)
{
  Hacl_EC_Format_fcontract_first_carry_full(input);
  Hacl_EC_Format_fcontract_second_carry_full(input);
  Hacl_EC_Format_fcontract_trim(input);
  Hacl_EC_Format_fcontract_store(output, input);
}

static void Hacl_EC_Format_scalar_of_point(uint8_t *scalar, uint64_t *point)
{
  uint64_t *x = point;
  uint64_t *z = point + (uint32_t)5U;
  uint64_t buf[10U] = { 0U };
  uint64_t *zmone = buf;
  uint64_t *sc = buf + (uint32_t)5U;
  Hacl_Bignum_crecip(zmone, z);
  Hacl_Bignum_fmul(sc, x, zmone);
  Hacl_EC_Format_fcontract(scalar, sc);
}

static void
Hacl_EC_AddAndDouble_fmonty(
  uint64_t *pp,
  uint64_t *ppq,
  uint64_t *p,
  uint64_t *pq,
  uint64_t *qmqp
)
{
  uint64_t *qx = qmqp;
  uint64_t *x2 = pp;
  uint64_t *z2 = pp + (uint32_t)5U;
  uint64_t *x3 = ppq;
  uint64_t *z3 = ppq + (uint32_t)5U;
  uint64_t *x = p;
  uint64_t *z = p + (uint32_t)5U;
  uint64_t *xprime = pq;
  uint64_t *zprime = pq + (uint32_t)5U;
  uint64_t buf[40U] = { 0U };
  uint64_t *origx = buf;
  uint64_t *origxprime0 = buf + (uint32_t)5U;
  uint64_t *xxprime0 = buf + (uint32_t)25U;
  uint64_t *zzprime0 = buf + (uint32_t)30U;
  uint64_t *origxprime;
  uint64_t *xx0;
  uint64_t *zz0;
  uint64_t *xxprime;
  uint64_t *zzprime;
  uint64_t *zzzprime;
  uint64_t *zzz;
  uint64_t *xx;
  uint64_t *zz;
  uint64_t scalar;
  memcpy(origx, x, (uint32_t)5U * sizeof x[0U]);
  Hacl_Bignum_fsum(x, z);
  Hacl_Bignum_fdifference(z, origx);
  memcpy(origxprime0, xprime, (uint32_t)5U * sizeof xprime[0U]);
  Hacl_Bignum_fsum(xprime, zprime);
  Hacl_Bignum_fdifference(zprime, origxprime0);
  Hacl_Bignum_fmul(xxprime0, xprime, z);
  Hacl_Bignum_fmul(zzprime0, x, zprime);
  origxprime = buf + (uint32_t)5U;
  xx0 = buf + (uint32_t)15U;
  zz0 = buf + (uint32_t)20U;
  xxprime = buf + (uint32_t)25U;
  zzprime = buf + (uint32_t)30U;
  zzzprime = buf + (uint32_t)35U;
  memcpy(origxprime, xxprime, (uint32_t)5U * sizeof xxprime[0U]);
  Hacl_Bignum_fsum(xxprime, zzprime);
  Hacl_Bignum_fdifference(zzprime, origxprime);
  Hacl_Bignum_Fsquare_fsquare_times(x3, xxprime, (uint32_t)1U);
  Hacl_Bignum_Fsquare_fsquare_times(zzzprime, zzprime, (uint32_t)1U);
  Hacl_Bignum_fmul(z3, zzzprime, qx);
  Hacl_Bignum_Fsquare_fsquare_times(xx0, x, (uint32_t)1U);
  Hacl_Bignum_Fsquare_fsquare_times(zz0, z, (uint32_t)1U);
  zzz = buf + (uint32_t)10U;
  xx = buf + (uint32_t)15U;
  zz = buf + (uint32_t)20U;
  Hacl_Bignum_fmul(x2, xx, zz);
  Hacl_Bignum_fdifference(zz, xx);
  scalar = (uint64_t)121665U;
  Hacl_Bignum_fscalar(zzz, zz, scalar);
  Hacl_Bignum_fsum(zzz, xx);
  Hacl_Bignum_fmul(z2, zzz, zz);
}

static void
Hacl_EC_Ladder_SmallLoop_cmult_small_loop_step(
  uint64_t *nq,
  uint64_t *nqpq,
  uint64_t *nq2,
  uint64_t *nqpq2,
  uint64_t *q,
  uint8_t byt
)
{
  uint64_t bit0 = (uint64_t)(byt >> (uint32_t)7U);
  uint64_t bit;
  Hacl_EC_Point_swap_conditional(nq, nqpq, bit0);
  Hacl_EC_AddAndDouble_fmonty(nq2, nqpq2, nq, nqpq, q);
  bit = (uint64_t)(byt >> (uint32_t)7U);
  Hacl_EC_Point_swap_conditional(nq2, nqpq2, bit);
}

static void
Hacl_EC_Ladder_SmallLoop_cmult_small_loop_double_step(
  uint64_t *nq,
  uint64_t *nqpq,
  uint64_t *nq2,
  uint64_t *nqpq2,
  uint64_t *q,
  uint8_t byt
)
{
  uint8_t byt1;
  Hacl_EC_Ladder_SmallLoop_cmult_small_loop_step(nq, nqpq, nq2, nqpq2, q, byt);
  byt1 = byt << (uint32_t)1U;
  Hacl_EC_Ladder_SmallLoop_cmult_small_loop_step(nq2, nqpq2, nq, nqpq, q, byt1);
}

static void
Hacl_EC_Ladder_SmallLoop_cmult_small_loop(
  uint64_t *nq,
  uint64_t *nqpq,
  uint64_t *nq2,
  uint64_t *nqpq2,
  uint64_t *q,
  uint8_t byt,
  uint32_t i
)
{
  if (!(i == (uint32_t)0U))
  {
    uint32_t i_ = i - (uint32_t)1U;
    uint8_t byt_;
    Hacl_EC_Ladder_SmallLoop_cmult_small_loop_double_step(nq, nqpq, nq2, nqpq2, q, byt);
    byt_ = byt << (uint32_t)2U;
    Hacl_EC_Ladder_SmallLoop_cmult_small_loop(nq, nqpq, nq2, nqpq2, q, byt_, i_);
  }
}

static void
Hacl_EC_Ladder_BigLoop_cmult_big_loop(
  uint8_t *n1,
  uint64_t *nq,
  uint64_t *nqpq,
  uint64_t *nq2,
  uint64_t *nqpq2,
  uint64_t *q,
  uint32_t i
)
{
  if (!(i == (uint32_t)0U))
  {
    uint32_t i1 = i - (uint32_t)1U;
    uint8_t byte = n1[i1];
    Hacl_EC_Ladder_SmallLoop_cmult_small_loop(nq, nqpq, nq2, nqpq2, q, byte, (uint32_t)4U);
    Hacl_EC_Ladder_BigLoop_cmult_big_loop(n1, nq, nqpq, nq2, nqpq2, q, i1);
  }
}

static void Hacl_EC_Ladder_cmult(uint64_t *result, uint8_t *n1, uint64_t *q)
{
  uint64_t point_buf[40U] = { 0U };
  uint64_t *nq = point_buf;
  uint64_t *nqpq = point_buf + (uint32_t)10U;
  uint64_t *nq2 = point_buf + (uint32_t)20U;
  uint64_t *nqpq2 = point_buf + (uint32_t)30U;
  Hacl_EC_Point_copy(nqpq, q);
  nq[0U] = (uint64_t)1U;
  Hacl_EC_Ladder_BigLoop_cmult_big_loop(n1, nq, nqpq, nq2, nqpq2, q, (uint32_t)32U);
  Hacl_EC_Point_copy(result, nq);
}

void Hacl_Curve25519_crypto_scalarmult(uint8_t *mypublic, uint8_t *secret, uint8_t *basepoint)
{
  uint64_t buf0[10U] = { 0U };
  uint64_t *x0 = buf0;
  uint64_t *z = buf0 + (uint32_t)5U;
  uint64_t *q;
  Hacl_EC_Format_fexpand(x0, basepoint);
  z[0U] = (uint64_t)1U;
  q = buf0;
  {
    uint8_t e[32U] = { 0U };
    uint8_t e0;
    uint8_t e31;
    uint8_t e01;
    uint8_t e311;
    uint8_t e312;
    uint8_t *scalar;
    memcpy(e, secret, (uint32_t)32U * sizeof secret[0U]);
    e0 = e[0U];
    e31 = e[31U];
    e01 = e0 & (uint8_t)248U;
    e311 = e31 & (uint8_t)127U;
    e312 = e311 | (uint8_t)64U;
    e[0U] = e01;
    e[31U] = e312;
    scalar = e;
    {
      uint64_t buf[15U] = { 0U };
      uint64_t *nq = buf;
      uint64_t *x = nq;
      x[0U] = (uint64_t)1U;
      Hacl_EC_Ladder_cmult(nq, scalar, q);
      Hacl_EC_Format_scalar_of_point(mypublic, nq);
    }
  }
}

int mbedtls_everest_setup( mbedtls_ecdh_context_everest *ctx, int grp_id )
{
    if( grp_id != MBEDTLS_ECP_DP_CURVE25519 )
        return MBEDTLS_ERR_ECP_BAD_INPUT_DATA;
    mbedtls_x25519_init( &ctx->ctx );
    return 0;
}

int mbedtls_everest_make_params( mbedtls_ecdh_context_everest *ctx, size_t *olen,
                                 unsigned char *buf, size_t blen,
                                 int( *f_rng )( void *, unsigned char *, size_t ),
                                 void *p_rng )
{
    mbedtls_x25519_context *x25519_ctx = &ctx->ctx;
    return mbedtls_x25519_make_params( x25519_ctx, olen, buf, blen, f_rng, p_rng );
}

int mbedtls_everest_read_params( mbedtls_ecdh_context_everest *ctx,
                                 const unsigned char **buf,
                                 const unsigned char *end )
{
    mbedtls_x25519_context *x25519_ctx = &ctx->ctx;
