static int local_err_translation(psa_status_t status)
{
    return psa_status_to_mbedtls(status, psa_to_ssl_errors,
                                 ARRAY_LENGTH(psa_to_ssl_errors),
                                 psa_generic_status_to_mbedtls);
}

void mbedtls_ssl_ticket_init(mbedtls_ssl_ticket_context *ctx)
{
    memset(ctx, 0, sizeof(mbedtls_ssl_ticket_context));

#if defined(MBEDTLS_THREADING_C)
    mbedtls_mutex_init(&ctx->mutex);
#endif
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_ticket_gen_key(mbedtls_ssl_ticket_context *ctx,
                              unsigned char index)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    unsigned char buf[MAX_KEY_BYTES] = { 0 };
    mbedtls_ssl_ticket_key *key = ctx->keys + index;

#if defined(MBEDTLS_USE_PSA_CRYPTO)
    psa_key_attributes_t attributes = PSA_KEY_ATTRIBUTES_INIT;
#endif

#if defined(MBEDTLS_HAVE_TIME)
    key->generation_time = mbedtls_time(NULL);
#endif
    /* The lifetime of a key is the configured lifetime of the tickets when
     * the key is created.
     */
    key->lifetime = ctx->ticket_lifetime;

    if ((ret = ctx->f_rng(ctx->p_rng, key->name, sizeof(key->name))) != 0) {
        return ret;
    }

    if ((ret = ctx->f_rng(ctx->p_rng, buf, sizeof(buf))) != 0) {
        return ret;
    }

#if defined(MBEDTLS_USE_PSA_CRYPTO)
    psa_set_key_usage_flags(&attributes,
                            PSA_KEY_USAGE_ENCRYPT | PSA_KEY_USAGE_DECRYPT);
    psa_set_key_algorithm(&attributes, key->alg);
    psa_set_key_type(&attributes, key->key_type);
    psa_set_key_bits(&attributes, key->key_bits);

    ret = PSA_TO_MBEDTLS_ERR(
        psa_import_key(&attributes, buf,
                       PSA_BITS_TO_BYTES(key->key_bits),
                       &key->key));
#else
    /* With GCM and CCM, same context can encrypt & decrypt */
    ret = mbedtls_cipher_setkey(&key->ctx, buf,
                                mbedtls_cipher_get_key_bitlen(&key->ctx),
                                MBEDTLS_ENCRYPT);
#endif /* MBEDTLS_USE_PSA_CRYPTO */

    mbedtls_platform_zeroize(buf, sizeof(buf));

    return ret;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_ticket_update_keys(mbedtls_ssl_ticket_context *ctx)
{
#if !defined(MBEDTLS_HAVE_TIME)
    ((void) ctx);
#else
    mbedtls_ssl_ticket_key * const key = ctx->keys + ctx->active;
    if (key->lifetime != 0) {
        mbedtls_time_t current_time = mbedtls_time(NULL);
        mbedtls_time_t key_time = key->generation_time;

#if defined(MBEDTLS_USE_PSA_CRYPTO)
        psa_status_t status = PSA_ERROR_CORRUPTION_DETECTED;
#endif

        if (current_time >= key_time &&
            (uint64_t) (current_time - key_time) < key->lifetime) {
            return 0;
        }

        ctx->active = 1 - ctx->active;

#if defined(MBEDTLS_USE_PSA_CRYPTO)
        if ((status = psa_destroy_key(ctx->keys[ctx->active].key)) != PSA_SUCCESS) {
            return PSA_TO_MBEDTLS_ERR(status);
        }
#endif /* MBEDTLS_USE_PSA_CRYPTO */

        return ssl_ticket_gen_key(ctx, ctx->active);
    } else
#endif /* MBEDTLS_HAVE_TIME */
    return 0;
}

int mbedtls_ssl_ticket_rotate(mbedtls_ssl_ticket_context *ctx,
                              const unsigned char *name, size_t nlength,
                              const unsigned char *k, size_t klength,
                              uint32_t lifetime)
{
    const unsigned char idx = 1 - ctx->active;
    mbedtls_ssl_ticket_key * const key = ctx->keys + idx;
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;

#if defined(MBEDTLS_USE_PSA_CRYPTO)
    psa_status_t status = PSA_ERROR_CORRUPTION_DETECTED;
    psa_key_attributes_t attributes = PSA_KEY_ATTRIBUTES_INIT;
    const size_t bitlen = key->key_bits;
#else
    const int bitlen = mbedtls_cipher_get_key_bitlen(&key->ctx);
#endif

    if (nlength < TICKET_KEY_NAME_BYTES || klength * 8 < (size_t) bitlen) {
        return MBEDTLS_ERR_CIPHER_BAD_INPUT_DATA;
    }

#if defined(MBEDTLS_USE_PSA_CRYPTO)
    if ((status = psa_destroy_key(key->key)) != PSA_SUCCESS) {
        ret = PSA_TO_MBEDTLS_ERR(status);
        return ret;
    }

    psa_set_key_usage_flags(&attributes,
                            PSA_KEY_USAGE_ENCRYPT | PSA_KEY_USAGE_DECRYPT);
    psa_set_key_algorithm(&attributes, key->alg);
    psa_set_key_type(&attributes, key->key_type);
    psa_set_key_bits(&attributes, key->key_bits);

    if ((status = psa_import_key(&attributes, k,
                                 PSA_BITS_TO_BYTES(key->key_bits),
                                 &key->key)) != PSA_SUCCESS) {
        ret = PSA_TO_MBEDTLS_ERR(status);
        return ret;
    }
#else
    ret = mbedtls_cipher_setkey(&key->ctx, k, bitlen, MBEDTLS_ENCRYPT);
    if (ret != 0) {
        return ret;
    }
#endif /* MBEDTLS_USE_PSA_CRYPTO */

    ctx->active = idx;
    ctx->ticket_lifetime = lifetime;
    memcpy(key->name, name, TICKET_KEY_NAME_BYTES);
#if defined(MBEDTLS_HAVE_TIME)
    key->generation_time = mbedtls_time(NULL);
#endif
    key->lifetime = lifetime;

    return 0;
}

int mbedtls_ssl_ticket_setup(mbedtls_ssl_ticket_context *ctx,
                             int (*f_rng)(void *, unsigned char *, size_t), void *p_rng,
                             mbedtls_cipher_type_t cipher,
                             uint32_t lifetime)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    size_t key_bits;

#if defined(MBEDTLS_USE_PSA_CRYPTO)
    psa_algorithm_t alg;
    psa_key_type_t key_type;
#else
    const mbedtls_cipher_info_t *cipher_info;
#endif /* MBEDTLS_USE_PSA_CRYPTO */

#if defined(MBEDTLS_USE_PSA_CRYPTO)
    if (mbedtls_ssl_cipher_to_psa(cipher, TICKET_AUTH_TAG_BYTES,
                                  &alg, &key_type, &key_bits) != PSA_SUCCESS) {
        return MBEDTLS_ERR_SSL_BAD_INPUT_DATA;
    }

    if (PSA_ALG_IS_AEAD(alg) == 0) {
        return MBEDTLS_ERR_SSL_BAD_INPUT_DATA;
    }
#else
    cipher_info = mbedtls_cipher_info_from_type(cipher);

    if (mbedtls_cipher_info_get_mode(cipher_info) != MBEDTLS_MODE_GCM &&
        mbedtls_cipher_info_get_mode(cipher_info) != MBEDTLS_MODE_CCM &&
        mbedtls_cipher_info_get_mode(cipher_info) != MBEDTLS_MODE_CHACHAPOLY) {
        return MBEDTLS_ERR_SSL_BAD_INPUT_DATA;
    }

    key_bits = mbedtls_cipher_info_get_key_bitlen(cipher_info);
#endif /* MBEDTLS_USE_PSA_CRYPTO */

    if (key_bits > 8 * MAX_KEY_BYTES) {
        return MBEDTLS_ERR_SSL_BAD_INPUT_DATA;
    }

    ctx->f_rng = f_rng;
    ctx->p_rng = p_rng;

    ctx->ticket_lifetime = lifetime;

#if defined(MBEDTLS_USE_PSA_CRYPTO)
    ctx->keys[0].alg = alg;
    ctx->keys[0].key_type = key_type;
    ctx->keys[0].key_bits = key_bits;

    ctx->keys[1].alg = alg;
    ctx->keys[1].key_type = key_type;
    ctx->keys[1].key_bits = key_bits;
#else
    if ((ret = mbedtls_cipher_setup(&ctx->keys[0].ctx, cipher_info)) != 0) {
        return ret;
    }

    if ((ret = mbedtls_cipher_setup(&ctx->keys[1].ctx, cipher_info)) != 0) {
        return ret;
    }
#endif /* MBEDTLS_USE_PSA_CRYPTO */

    if ((ret = ssl_ticket_gen_key(ctx, 0)) != 0 ||
        (ret = ssl_ticket_gen_key(ctx, 1)) != 0) {
        return ret;
    }

    return 0;
}

int mbedtls_ssl_ticket_write(void *p_ticket,
                             const mbedtls_ssl_session *session,
                             unsigned char *start,
                             const unsigned char *end,
                             size_t *tlen,
                             uint32_t *ticket_lifetime)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_ssl_ticket_context *ctx = p_ticket;
    mbedtls_ssl_ticket_key *key;
    unsigned char *key_name = start;
    unsigned char *iv = start + TICKET_KEY_NAME_BYTES;
    unsigned char *state_len_bytes = iv + TICKET_IV_BYTES;
    unsigned char *state = state_len_bytes + TICKET_CRYPT_LEN_BYTES;
    size_t clear_len, ciph_len;

#if defined(MBEDTLS_USE_PSA_CRYPTO)
    psa_status_t status = PSA_ERROR_CORRUPTION_DETECTED;
#endif

    *tlen = 0;

    if (ctx == NULL || ctx->f_rng == NULL) {
        return MBEDTLS_ERR_SSL_BAD_INPUT_DATA;
    }

    /* We need at least 4 bytes for key_name, 12 for IV, 2 for len 16 for tag,
     * in addition to session itself, that will be checked when writing it. */
    MBEDTLS_SSL_CHK_BUF_PTR(start, end, TICKET_MIN_LEN);

#if defined(MBEDTLS_THREADING_C)
    if ((ret = mbedtls_mutex_lock(&ctx->mutex)) != 0) {
        return ret;
    }
#endif

    if ((ret = ssl_ticket_update_keys(ctx)) != 0) {
        goto cleanup;
    }

    key = &ctx->keys[ctx->active];

    *ticket_lifetime = key->lifetime;

    memcpy(key_name, key->name, TICKET_KEY_NAME_BYTES);

    if ((ret = ctx->f_rng(ctx->p_rng, iv, TICKET_IV_BYTES)) != 0) {
        goto cleanup;
    }

    /* Dump session state */
    if ((ret = mbedtls_ssl_session_save(session,
                                        state, (size_t) (end - state),
                                        &clear_len)) != 0 ||
        (unsigned long) clear_len > 65535) {
        goto cleanup;
    }
    MBEDTLS_PUT_UINT16_BE(clear_len, state_len_bytes, 0);

    /* Encrypt and authenticate */
#if defined(MBEDTLS_USE_PSA_CRYPTO)
    if ((status = psa_aead_encrypt(key->key, key->alg, iv, TICKET_IV_BYTES,
                                   key_name, TICKET_ADD_DATA_LEN,
                                   state, clear_len,
                                   state, end - state,
                                   &ciph_len)) != PSA_SUCCESS) {
        ret = PSA_TO_MBEDTLS_ERR(status);
        goto cleanup;
    }
#else
    if ((ret = mbedtls_cipher_auth_encrypt_ext(&key->ctx,
                                               iv, TICKET_IV_BYTES,
                                               /* Additional data: key name, IV and length */
                                               key_name, TICKET_ADD_DATA_LEN,
                                               state, clear_len,
                                               state, (size_t) (end - state), &ciph_len,
                                               TICKET_AUTH_TAG_BYTES)) != 0) {
        goto cleanup;
    }
#endif /* MBEDTLS_USE_PSA_CRYPTO */

    if (ciph_len != clear_len + TICKET_AUTH_TAG_BYTES) {
        ret = MBEDTLS_ERR_SSL_INTERNAL_ERROR;
        goto cleanup;
    }

    *tlen = TICKET_MIN_LEN + ciph_len - TICKET_AUTH_TAG_BYTES;

cleanup:
#if defined(MBEDTLS_THREADING_C)
    if (mbedtls_mutex_unlock(&ctx->mutex) != 0) {
        return MBEDTLS_ERR_THREADING_MUTEX_ERROR;
    }
#endif

    return ret;
}

static mbedtls_ssl_ticket_key *ssl_ticket_select_key(
    mbedtls_ssl_ticket_context *ctx,
    const unsigned char name[4])
{
    unsigned char i;

    for (i = 0; i < sizeof(ctx->keys) / sizeof(*ctx->keys); i++) {
        if (memcmp(name, ctx->keys[i].name, 4) == 0) {
            return &ctx->keys[i];
        }
    }

    return NULL;
}

int mbedtls_ssl_ticket_parse(void *p_ticket,
                             mbedtls_ssl_session *session,
                             unsigned char *buf,
                             size_t len)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_ssl_ticket_context *ctx = p_ticket;
    mbedtls_ssl_ticket_key *key;
    unsigned char *key_name = buf;
    unsigned char *iv = buf + TICKET_KEY_NAME_BYTES;
    unsigned char *enc_len_p = iv + TICKET_IV_BYTES;
    unsigned char *ticket = enc_len_p + TICKET_CRYPT_LEN_BYTES;
    size_t enc_len, clear_len;

#if defined(MBEDTLS_USE_PSA_CRYPTO)
    psa_status_t status = PSA_ERROR_CORRUPTION_DETECTED;
#endif

    if (ctx == NULL || ctx->f_rng == NULL) {
        return MBEDTLS_ERR_SSL_BAD_INPUT_DATA;
    }

    if (len < TICKET_MIN_LEN) {
        return MBEDTLS_ERR_SSL_BAD_INPUT_DATA;
    }

#if defined(MBEDTLS_THREADING_C)
    if ((ret = mbedtls_mutex_lock(&ctx->mutex)) != 0) {
        return ret;
    }
#endif

    if ((ret = ssl_ticket_update_keys(ctx)) != 0) {
        goto cleanup;
    }

    enc_len = MBEDTLS_GET_UINT16_BE(enc_len_p, 0);

    if (len != TICKET_MIN_LEN + enc_len) {
        ret = MBEDTLS_ERR_SSL_BAD_INPUT_DATA;
        goto cleanup;
    }

    /* Select key */
    if ((key = ssl_ticket_select_key(ctx, key_name)) == NULL) {
        /* We can't know for sure but this is a likely option unless we're
         * under attack - this is only informative anyway */
        ret = MBEDTLS_ERR_SSL_SESSION_TICKET_EXPIRED;
        goto cleanup;
    }

    /* Decrypt and authenticate */
#if defined(MBEDTLS_USE_PSA_CRYPTO)
    if ((status = psa_aead_decrypt(key->key, key->alg, iv, TICKET_IV_BYTES,
                                   key_name, TICKET_ADD_DATA_LEN,
                                   ticket, enc_len + TICKET_AUTH_TAG_BYTES,
                                   ticket, enc_len, &clear_len)) != PSA_SUCCESS) {
        ret = PSA_TO_MBEDTLS_ERR(status);
        goto cleanup;
    }
#else
    if ((ret = mbedtls_cipher_auth_decrypt_ext(&key->ctx,
                                               iv, TICKET_IV_BYTES,
                                               /* Additional data: key name, IV and length */
                                               key_name, TICKET_ADD_DATA_LEN,
                                               ticket, enc_len + TICKET_AUTH_TAG_BYTES,
                                               ticket, enc_len, &clear_len,
                                               TICKET_AUTH_TAG_BYTES)) != 0) {
        if (ret == MBEDTLS_ERR_CIPHER_AUTH_FAILED) {
            ret = MBEDTLS_ERR_SSL_INVALID_MAC;
        }

        goto cleanup;
    }
#endif /* MBEDTLS_USE_PSA_CRYPTO */

    if (clear_len != enc_len) {
        ret = MBEDTLS_ERR_SSL_INTERNAL_ERROR;
        goto cleanup;
    }

    /* Actually load session */
    if ((ret = mbedtls_ssl_session_load(session, ticket, clear_len)) != 0) {
        goto cleanup;
    }

#if defined(MBEDTLS_HAVE_TIME)
    mbedtls_ms_time_t ticket_creation_time, ticket_age;
    mbedtls_ms_time_t ticket_lifetime =
        (mbedtls_ms_time_t) key->lifetime * 1000;

    ret = mbedtls_ssl_session_get_ticket_creation_time(session,
                                                       &ticket_creation_time);
    if (ret != 0) {
        goto cleanup;
    }

    ticket_age = mbedtls_ms_time() - ticket_creation_time;
    if (ticket_age < 0 || ticket_age > ticket_lifetime) {
        ret = MBEDTLS_ERR_SSL_SESSION_TICKET_EXPIRED;
        goto cleanup;
    }
#endif

cleanup:
#if defined(MBEDTLS_THREADING_C)
    if (mbedtls_mutex_unlock(&ctx->mutex) != 0) {
        return MBEDTLS_ERR_THREADING_MUTEX_ERROR;
    }
#endif

    return ret;
}

void mbedtls_ssl_ticket_free(mbedtls_ssl_ticket_context *ctx)
{
    if (ctx == NULL) {
        return;
    }

#if defined(MBEDTLS_USE_PSA_CRYPTO)
    psa_destroy_key(ctx->keys[0].key);
    psa_destroy_key(ctx->keys[1].key);
#else
    mbedtls_cipher_free(&ctx->keys[0].ctx);
    mbedtls_cipher_free(&ctx->keys[1].ctx);
#endif /* MBEDTLS_USE_PSA_CRYPTO */

#if defined(MBEDTLS_THREADING_C)
    mbedtls_mutex_free(&ctx->mutex);
#endif

    mbedtls_platform_zeroize(ctx, sizeof(mbedtls_ssl_ticket_context));
}

static int local_err_translation(psa_status_t status)
{
    return psa_status_to_mbedtls(status, psa_to_ssl_errors,
                                 ARRAY_LENGTH(psa_to_ssl_errors),
                                 psa_generic_status_to_mbedtls);
}

int mbedtls_ssl_tls13_crypto_init(mbedtls_ssl_context *ssl)
{
    psa_status_t status = psa_crypto_init();
    if (status != PSA_SUCCESS) {
        (void) ssl; // unused when debugging is disabled
        MBEDTLS_SSL_DEBUG_RET(1, "psa_crypto_init", status);
    }
    return PSA_TO_MBEDTLS_ERR(status);
}

int mbedtls_ssl_tls13_fetch_handshake_msg(mbedtls_ssl_context *ssl,
                                          unsigned hs_type,
                                          unsigned char **buf,
                                          size_t *buf_len)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    int require_record_boundary;

    /* Require record-boundary alignment by default. The exceptions below are
     * handshake messages that may legitimately be followed by additional
     * handshake messages in the same record. Using the default behaviour for a
     * message that should be exempt is an interoperability bug; exempting a
     * message that should not be exempt may have security implications.
     */
    switch (hs_type) {
        case MBEDTLS_SSL_HS_NEW_SESSION_TICKET:
        case MBEDTLS_SSL_HS_ENCRYPTED_EXTENSIONS:
        case MBEDTLS_SSL_HS_CERTIFICATE:
        case MBEDTLS_SSL_HS_CERTIFICATE_REQUEST:
        case MBEDTLS_SSL_HS_CERTIFICATE_VERIFY:
        /*
         * For TLS 1.3, ServerHello (including HelloRetryRequest) must end at a
         * record boundary, but not for TLS 1.2. At this point the ServerHello
         * has not yet been processed, so we do not know whether it negotiates
         * TLS 1.3 or TLS 1.2. Defer the boundary check until the protocol
         * version is known to be TLS 1.3.
         */
        case MBEDTLS_SSL_HS_SERVER_HELLO:
            require_record_boundary = 0;
            break;

        default:
            /* ClientHello, EndOfEarlyData, Finished, and KeyUpdate.
             */
            require_record_boundary = 1;
    }

    ret = mbedtls_ssl_read_record(ssl, 0);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_read_record", ret);
        goto error;
    }

    ret = MBEDTLS_ERR_SSL_UNEXPECTED_MESSAGE;
    if (ssl->in_msgtype != MBEDTLS_SSL_MSG_HANDSHAKE ||
        ssl->in_msg[0]  != hs_type) {
        MBEDTLS_SSL_DEBUG_MSG(1, ("Receive unexpected handshake message."));
        goto error;
    }

    if (require_record_boundary && (ssl->in_hslen != ssl->in_msglen)) {
        MBEDTLS_SSL_DEBUG_MSG(1, ("Handshake message %s end not aligned with a record boundary",
                                  mbedtls_ssl_get_hs_msg_name(hs_type)));
        goto error;
    }

    /*
     * Jump handshake header (4 bytes, see Section 4 of RFC 8446).
     *    ...
     *    HandshakeType msg_type;
     *    uint24 length;
     *    ...
     */
    *buf = ssl->in_msg + 4;
    *buf_len = ssl->in_hslen - 4;
    return 0;

error:
    if (ret == MBEDTLS_ERR_SSL_UNEXPECTED_MESSAGE) {
        MBEDTLS_SSL_PEND_FATAL_ALERT(MBEDTLS_SSL_ALERT_MSG_UNEXPECTED_MESSAGE,
                                     MBEDTLS_ERR_SSL_UNEXPECTED_MESSAGE);
    }
    return ret;
}

int mbedtls_ssl_tls13_is_supported_versions_ext_present_in_exts(
    mbedtls_ssl_context *ssl,
    const unsigned char *buf, const unsigned char *end,
    const unsigned char **supported_versions_data,
    const unsigned char **supported_versions_data_end)
{
    const unsigned char *p = buf;
    size_t extensions_len;
    const unsigned char *extensions_end;

    *supported_versions_data = NULL;
    *supported_versions_data_end = NULL;

    /* Case of no extension */
    if (p == end) {
        return 0;
    }

    /* ...
     * Extension extensions<x..2^16-1>;
     * ...
     * struct {
     *      ExtensionType extension_type; (2 bytes)
     *      opaque extension_data<0..2^16-1>;
     * } Extension;
     */
    MBEDTLS_SSL_CHK_BUF_READ_PTR(p, end, 2);
    extensions_len = MBEDTLS_GET_UINT16_BE(p, 0);
    p += 2;

    /* Check extensions do not go beyond the buffer of data. */
    MBEDTLS_SSL_CHK_BUF_READ_PTR(p, end, extensions_len);
    extensions_end = p + extensions_len;

    while (p < extensions_end) {
        unsigned int extension_type;
        size_t extension_data_len;

        MBEDTLS_SSL_CHK_BUF_READ_PTR(p, extensions_end, 4);
        extension_type = MBEDTLS_GET_UINT16_BE(p, 0);
        extension_data_len = MBEDTLS_GET_UINT16_BE(p, 2);
        p += 4;
        MBEDTLS_SSL_CHK_BUF_READ_PTR(p, extensions_end, extension_data_len);

        if (extension_type == MBEDTLS_TLS_EXT_SUPPORTED_VERSIONS) {
            *supported_versions_data = p;
            *supported_versions_data_end = p + extension_data_len;
            return 1;
        }
        p += extension_data_len;
    }

    return 0;
}

static void ssl_tls13_create_verify_structure(const unsigned char *transcript_hash,
                                              size_t transcript_hash_len,
                                              unsigned char *verify_buffer,
                                              size_t *verify_buffer_len,
                                              int from)
{
    size_t idx;

    /* RFC 8446, Section 4.4.3:
     *
     * The digital signature [in the CertificateVerify message] is then
     * computed over the concatenation of:
     * -  A string that consists of octet 32 (0x20) repeated 64 times
     * -  The context string
     * -  A single 0 byte which serves as the separator
     * -  The content to be signed
     */
    memset(verify_buffer, 0x20, 64);
    idx = 64;

    if (from == MBEDTLS_SSL_IS_CLIENT) {
        memcpy(verify_buffer + idx, mbedtls_ssl_tls13_labels.client_cv,
               MBEDTLS_SSL_TLS1_3_LBL_LEN(client_cv));
        idx += MBEDTLS_SSL_TLS1_3_LBL_LEN(client_cv);
    } else { /* from == MBEDTLS_SSL_IS_SERVER */
        memcpy(verify_buffer + idx, mbedtls_ssl_tls13_labels.server_cv,
               MBEDTLS_SSL_TLS1_3_LBL_LEN(server_cv));
        idx += MBEDTLS_SSL_TLS1_3_LBL_LEN(server_cv);
    }

    verify_buffer[idx++] = 0x0;

    memcpy(verify_buffer + idx, transcript_hash, transcript_hash_len);
    idx += transcript_hash_len;

    *verify_buffer_len = idx;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_parse_certificate_verify(mbedtls_ssl_context *ssl,
                                              const unsigned char *buf,
                                              const unsigned char *end,
                                              const unsigned char *verify_buffer,
                                              size_t verify_buffer_len)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    psa_status_t status = PSA_ERROR_CORRUPTION_DETECTED;
    const unsigned char *p = buf;
    uint16_t algorithm;
    size_t signature_len;
    mbedtls_pk_type_t sig_alg;
    mbedtls_md_type_t md_alg;
    psa_algorithm_t hash_alg = PSA_ALG_NONE;
    unsigned char verify_hash[PSA_HASH_MAX_SIZE];
    size_t verify_hash_len;

    void const *options = NULL;
#if defined(MBEDTLS_X509_RSASSA_PSS_SUPPORT)
    mbedtls_pk_rsassa_pss_options rsassa_pss_options;
#endif /* MBEDTLS_X509_RSASSA_PSS_SUPPORT */

    /*
     * struct {
     *     SignatureScheme algorithm;
     *     opaque signature<0..2^16-1>;
     * } CertificateVerify;
     */
    MBEDTLS_SSL_CHK_BUF_READ_PTR(p, end, 2);
    algorithm = MBEDTLS_GET_UINT16_BE(p, 0);
    p += 2;

    /* RFC 8446 section 4.4.3
     *
     * If the CertificateVerify message is sent by a server, the signature
     * algorithm MUST be one offered in the client's "signature_algorithms"
     * extension unless no valid certificate chain can be produced without
     * unsupported algorithms
     *
     * RFC 8446 section 4.4.2.2
     *
     * If the client cannot construct an acceptable chain using the provided
     * certificates and decides to abort the handshake, then it MUST abort the
     * handshake with an appropriate certificate-related alert
     * (by default, "unsupported_certificate").
     *
     * Check if algorithm is an offered signature algorithm.
     */
    if (!mbedtls_ssl_sig_alg_is_offered(ssl, algorithm)) {
        /* algorithm not in offered signature algorithms list */
        MBEDTLS_SSL_DEBUG_MSG(1, ("Received signature algorithm(%04x) is not "
                                  "offered.",
                                  (unsigned int) algorithm));
        goto error;
    }

    if (mbedtls_ssl_get_pk_type_and_md_alg_from_sig_alg(
            algorithm, &sig_alg, &md_alg) != 0) {
        goto error;
    }

    hash_alg = mbedtls_md_psa_alg_from_type(md_alg);
    if (hash_alg == 0) {
        goto error;
    }

    MBEDTLS_SSL_DEBUG_MSG(3, ("Certificate Verify: Signature algorithm ( %04x )",
                              (unsigned int) algorithm));

    /*
     * Check the certificate's key type matches the signature alg
     */
    if (!mbedtls_pk_can_do(&ssl->session_negotiate->peer_cert->pk, sig_alg)) {
        MBEDTLS_SSL_DEBUG_MSG(1, ("signature algorithm doesn't match cert key"));
        goto error;
    }

    MBEDTLS_SSL_CHK_BUF_READ_PTR(p, end, 2);
    signature_len = MBEDTLS_GET_UINT16_BE(p, 0);
    p += 2;
    MBEDTLS_SSL_CHK_BUF_READ_PTR(p, end, signature_len);

    status = psa_hash_compute(hash_alg,
                              verify_buffer,
                              verify_buffer_len,
                              verify_hash,
                              sizeof(verify_hash),
                              &verify_hash_len);
    if (status != PSA_SUCCESS) {
        MBEDTLS_SSL_DEBUG_RET(1, "hash computation PSA error", status);
        goto error;
    }

    MBEDTLS_SSL_DEBUG_BUF(3, "verify hash", verify_hash, verify_hash_len);
#if defined(MBEDTLS_X509_RSASSA_PSS_SUPPORT)
    if (sig_alg == MBEDTLS_PK_RSASSA_PSS) {
        rsassa_pss_options.mgf1_hash_id = md_alg;

        rsassa_pss_options.expected_salt_len = PSA_HASH_LENGTH(hash_alg);
        options = (const void *) &rsassa_pss_options;
    }
#endif /* MBEDTLS_X509_RSASSA_PSS_SUPPORT */

    if ((ret = mbedtls_pk_verify_ext(sig_alg, options,
                                     &ssl->session_negotiate->peer_cert->pk,
                                     md_alg, verify_hash, verify_hash_len,
                                     p, signature_len)) == 0) {
        return 0;
    }
    MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_pk_verify_ext", ret);

error:
    /* RFC 8446 section 4.4.3
     *
     * If the verification fails, the receiver MUST terminate the handshake
     * with a "decrypt_error" alert.
     */
    MBEDTLS_SSL_PEND_FATAL_ALERT(MBEDTLS_SSL_ALERT_MSG_DECRYPT_ERROR,
                                 MBEDTLS_ERR_SSL_HANDSHAKE_FAILURE);
    return MBEDTLS_ERR_SSL_HANDSHAKE_FAILURE;

}

int mbedtls_ssl_tls13_process_certificate_verify(mbedtls_ssl_context *ssl)
{

#if defined(MBEDTLS_SSL_TLS1_3_KEY_EXCHANGE_MODE_EPHEMERAL_ENABLED)
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    unsigned char verify_buffer[SSL_VERIFY_STRUCT_MAX_SIZE];
    size_t verify_buffer_len;
    unsigned char transcript[MBEDTLS_TLS1_3_MD_MAX_SIZE];
    size_t transcript_len;
    unsigned char *buf;
    size_t buf_len;

    MBEDTLS_SSL_DEBUG_MSG(2, ("=> parse certificate verify"));

    MBEDTLS_SSL_PROC_CHK(
        mbedtls_ssl_tls13_fetch_handshake_msg(
            ssl, MBEDTLS_SSL_HS_CERTIFICATE_VERIFY, &buf, &buf_len));

    /* Need to calculate the hash of the transcript first
     * before reading the message since otherwise it gets
     * included in the transcript
     */
    ret = mbedtls_ssl_get_handshake_transcript(
        ssl,
        (mbedtls_md_type_t) ssl->handshake->ciphersuite_info->mac,
        transcript, sizeof(transcript),
        &transcript_len);
    if (ret != 0) {
        MBEDTLS_SSL_PEND_FATAL_ALERT(
            MBEDTLS_SSL_ALERT_MSG_INTERNAL_ERROR,
            MBEDTLS_ERR_SSL_INTERNAL_ERROR);
        return ret;
    }

    MBEDTLS_SSL_DEBUG_BUF(3, "handshake hash", transcript, transcript_len);

    /* Create verify structure */
    ssl_tls13_create_verify_structure(transcript,
                                      transcript_len,
                                      verify_buffer,
                                      &verify_buffer_len,
                                      (ssl->conf->endpoint == MBEDTLS_SSL_IS_CLIENT) ?
                                      MBEDTLS_SSL_IS_SERVER :
                                      MBEDTLS_SSL_IS_CLIENT);

    /* Process the message contents */
    MBEDTLS_SSL_PROC_CHK(ssl_tls13_parse_certificate_verify(
                             ssl, buf, buf + buf_len,
                             verify_buffer, verify_buffer_len));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_add_hs_msg_to_checksum(
                             ssl, MBEDTLS_SSL_HS_CERTIFICATE_VERIFY,
                             buf, buf_len));

cleanup:

    MBEDTLS_SSL_DEBUG_MSG(2, ("<= parse certificate verify"));
    MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_process_certificate_verify", ret);
    return ret;
#else
    ((void) ssl);
    MBEDTLS_SSL_DEBUG_MSG(1, ("should never happen"));
    return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
#endif /* MBEDTLS_SSL_TLS1_3_KEY_EXCHANGE_MODE_EPHEMERAL_ENABLED */
}

int mbedtls_ssl_tls13_parse_certificate(mbedtls_ssl_context *ssl,
                                        const unsigned char *buf,
                                        const unsigned char *end)
{
    ((void) ssl);
    ((void) buf);
    ((void) end);
    return MBEDTLS_ERR_SSL_FEATURE_UNAVAILABLE;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_validate_certificate(mbedtls_ssl_context *ssl)
{
    /* Authmode: precedence order is SNI if used else configuration */
#if defined(MBEDTLS_SSL_SRV_C) && defined(MBEDTLS_SSL_SERVER_NAME_INDICATION)
    const int authmode = ssl->handshake->sni_authmode != MBEDTLS_SSL_VERIFY_UNSET
                       ? ssl->handshake->sni_authmode
                       : ssl->conf->authmode;
#else
    const int authmode = ssl->conf->authmode;
#endif

    /*
     * If the peer hasn't sent a certificate ( i.e. it sent
     * an empty certificate chain ), this is reflected in the peer CRT
     * structure being unset.
     * Check for that and handle it depending on the
     * authentication mode.
     */
    if (ssl->session_negotiate->peer_cert == NULL) {
        MBEDTLS_SSL_DEBUG_MSG(1, ("peer has no certificate"));

#if defined(MBEDTLS_SSL_SRV_C)
        if (ssl->conf->endpoint == MBEDTLS_SSL_IS_SERVER) {
            /* The client was asked for a certificate but didn't send
             * one. The client should know what's going on, so we
             * don't send an alert.
             */
            ssl->session_negotiate->verify_result = MBEDTLS_X509_BADCERT_MISSING;
            if (authmode == MBEDTLS_SSL_VERIFY_OPTIONAL) {
                return 0;
            } else {
                MBEDTLS_SSL_PEND_FATAL_ALERT(
                    MBEDTLS_SSL_ALERT_MSG_NO_CERT,
                    MBEDTLS_ERR_SSL_NO_CLIENT_CERTIFICATE);
                return MBEDTLS_ERR_SSL_NO_CLIENT_CERTIFICATE;
            }
        }
#endif /* MBEDTLS_SSL_SRV_C */

#if defined(MBEDTLS_SSL_CLI_C)
        /* Regardless of authmode, the server is not allowed to send an empty
         * certificate chain. (Last paragraph before 4.4.2.1 in RFC 8446: "The
         * server's certificate_list MUST always be non-empty.") With authmode
         * optional/none, we continue the handshake if we can't validate the
         * server's cert, but we still break it if no certificate was sent. */
        if (ssl->conf->endpoint == MBEDTLS_SSL_IS_CLIENT) {
            MBEDTLS_SSL_PEND_FATAL_ALERT(MBEDTLS_SSL_ALERT_MSG_NO_CERT,
                                         MBEDTLS_ERR_SSL_FATAL_ALERT_MESSAGE);
            return MBEDTLS_ERR_SSL_FATAL_ALERT_MESSAGE;
        }
#endif /* MBEDTLS_SSL_CLI_C */
    }

    return mbedtls_ssl_verify_certificate(ssl, authmode,
                                          ssl->session_negotiate->peer_cert,
                                          NULL, NULL);
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_validate_certificate(mbedtls_ssl_context *ssl)
{
    ((void) ssl);
    return MBEDTLS_ERR_SSL_FEATURE_UNAVAILABLE;
}

int mbedtls_ssl_tls13_process_certificate(mbedtls_ssl_context *ssl)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    MBEDTLS_SSL_DEBUG_MSG(2, ("=> parse certificate"));

#if defined(MBEDTLS_SSL_TLS1_3_KEY_EXCHANGE_MODE_EPHEMERAL_ENABLED)
    unsigned char *buf;
    size_t buf_len;

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_tls13_fetch_handshake_msg(
                             ssl, MBEDTLS_SSL_HS_CERTIFICATE,
                             &buf, &buf_len));

    /* Parse the certificate chain sent by the peer. */
    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_tls13_parse_certificate(ssl, buf,
                                                             buf + buf_len));
    /* Validate the certificate chain and set the verification results. */
    MBEDTLS_SSL_PROC_CHK(ssl_tls13_validate_certificate(ssl));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_add_hs_msg_to_checksum(
                             ssl, MBEDTLS_SSL_HS_CERTIFICATE, buf, buf_len));

cleanup:
#else /* MBEDTLS_SSL_TLS1_3_KEY_EXCHANGE_MODE_EPHEMERAL_ENABLED */
    (void) ssl;
#endif /* MBEDTLS_SSL_TLS1_3_KEY_EXCHANGE_MODE_EPHEMERAL_ENABLED */

    MBEDTLS_SSL_DEBUG_MSG(2, ("<= parse certificate"));
    return ret;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_write_certificate_body(mbedtls_ssl_context *ssl,
                                            unsigned char *buf,
                                            unsigned char *end,
                                            size_t *out_len)
{
    const mbedtls_x509_crt *crt = mbedtls_ssl_own_cert(ssl);
    unsigned char *p = buf;
    unsigned char *certificate_request_context =
        ssl->handshake->certificate_request_context;
    unsigned char certificate_request_context_len =
        ssl->handshake->certificate_request_context_len;
    unsigned char *p_certificate_list_len;


    /* ...
     * opaque certificate_request_context<0..2^8-1>;
     * ...
     */
    MBEDTLS_SSL_CHK_BUF_PTR(p, end, certificate_request_context_len + 1);
    *p++ = certificate_request_context_len;
    if (certificate_request_context_len > 0) {
        memcpy(p, certificate_request_context, certificate_request_context_len);
        p += certificate_request_context_len;
    }

    /* ...
     * CertificateEntry certificate_list<0..2^24-1>;
     * ...
     */
    MBEDTLS_SSL_CHK_BUF_PTR(p, end, 3);
    p_certificate_list_len = p;
    p += 3;

    MBEDTLS_SSL_DEBUG_CRT(3, "own certificate", crt);

    while (crt != NULL) {
        size_t cert_data_len = crt->raw.len;

        MBEDTLS_SSL_CHK_BUF_PTR(p, end, cert_data_len + 3 + 2);
        MBEDTLS_PUT_UINT24_BE(cert_data_len, p, 0);
        p += 3;

        memcpy(p, crt->raw.p, cert_data_len);
        p += cert_data_len;
        crt = crt->next;

        /* Currently, we don't have any certificate extensions defined.
         * Hence, we are sending an empty extension with length zero.
         */
        MBEDTLS_PUT_UINT16_BE(0, p, 0);
        p += 2;
    }

    MBEDTLS_PUT_UINT24_BE(p - p_certificate_list_len - 3,
                          p_certificate_list_len, 0);

    *out_len = p - buf;

    MBEDTLS_SSL_PRINT_EXTS(
        3, MBEDTLS_SSL_HS_CERTIFICATE, ssl->handshake->sent_extensions);

    return 0;
}

int mbedtls_ssl_tls13_write_certificate(mbedtls_ssl_context *ssl)
{
    int ret;
    unsigned char *buf;
    size_t buf_len, msg_len;

    MBEDTLS_SSL_DEBUG_MSG(2, ("=> write certificate"));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_start_handshake_msg(
                             ssl, MBEDTLS_SSL_HS_CERTIFICATE, &buf, &buf_len));

    MBEDTLS_SSL_PROC_CHK(ssl_tls13_write_certificate_body(ssl,
                                                          buf,
                                                          buf + buf_len,
                                                          &msg_len));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_add_hs_msg_to_checksum(
                             ssl, MBEDTLS_SSL_HS_CERTIFICATE, buf, msg_len));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_finish_handshake_msg(
                             ssl, buf_len, msg_len));
cleanup:

    MBEDTLS_SSL_DEBUG_MSG(2, ("<= write certificate"));
    return ret;
}

int mbedtls_ssl_tls13_check_sig_alg_cert_key_match(uint16_t sig_alg,
                                                   mbedtls_pk_context *key)
{
    mbedtls_pk_type_t pk_type = (mbedtls_pk_type_t) mbedtls_ssl_sig_from_pk(key);
    size_t key_size = mbedtls_pk_get_bitlen(key);

    switch (pk_type) {
        case MBEDTLS_SSL_SIG_ECDSA:
            switch (key_size) {
                case 256:
                    return
                        sig_alg == MBEDTLS_TLS1_3_SIG_ECDSA_SECP256R1_SHA256;

                case 384:
                    return
                        sig_alg == MBEDTLS_TLS1_3_SIG_ECDSA_SECP384R1_SHA384;

                case 521:
                    return
                        sig_alg == MBEDTLS_TLS1_3_SIG_ECDSA_SECP521R1_SHA512;
                default:
                    break;
            }
            break;

        case MBEDTLS_SSL_SIG_RSA:
            switch (sig_alg) {
                case MBEDTLS_TLS1_3_SIG_RSA_PSS_RSAE_SHA256: /* Intentional fallthrough */
                case MBEDTLS_TLS1_3_SIG_RSA_PSS_RSAE_SHA384: /* Intentional fallthrough */
                case MBEDTLS_TLS1_3_SIG_RSA_PSS_RSAE_SHA512:
                    return 1;

                default:
                    break;
            }
            break;

        default:
            break;
    }

    return 0;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_write_certificate_verify_body(mbedtls_ssl_context *ssl,
                                                   unsigned char *buf,
                                                   unsigned char *end,
                                                   size_t *out_len)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    unsigned char *p = buf;
    mbedtls_pk_context *own_key;

    unsigned char handshake_hash[MBEDTLS_TLS1_3_MD_MAX_SIZE];
    size_t handshake_hash_len;
    unsigned char verify_buffer[SSL_VERIFY_STRUCT_MAX_SIZE];
    size_t verify_buffer_len;

    uint16_t *sig_alg = ssl->handshake->received_sig_algs;
    size_t signature_len = 0;

    *out_len = 0;

    own_key = mbedtls_ssl_own_key(ssl);
    if (own_key == NULL) {
        MBEDTLS_SSL_DEBUG_MSG(1, ("should never happen"));
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    ret = mbedtls_ssl_get_handshake_transcript(
        ssl, (mbedtls_md_type_t) ssl->handshake->ciphersuite_info->mac,
        handshake_hash, sizeof(handshake_hash), &handshake_hash_len);
    if (ret != 0) {
        return ret;
    }

    MBEDTLS_SSL_DEBUG_BUF(3, "handshake hash",
                          handshake_hash,
                          handshake_hash_len);

    ssl_tls13_create_verify_structure(handshake_hash, handshake_hash_len,
                                      verify_buffer, &verify_buffer_len,
                                      ssl->conf->endpoint);

    /*
     *  struct {
     *    SignatureScheme algorithm;
     *    opaque signature<0..2^16-1>;
     *  } CertificateVerify;
     */
    /* Check there is space for the algorithm identifier (2 bytes) and the
     * signature length (2 bytes).
     */
    MBEDTLS_SSL_CHK_BUF_PTR(p, end, 4);

    for (; *sig_alg != MBEDTLS_TLS1_3_SIG_NONE; sig_alg++) {
        psa_status_t status = PSA_ERROR_CORRUPTION_DETECTED;
        mbedtls_pk_type_t pk_type = MBEDTLS_PK_NONE;
        mbedtls_md_type_t md_alg = MBEDTLS_MD_NONE;
        psa_algorithm_t psa_algorithm = PSA_ALG_NONE;
        unsigned char verify_hash[PSA_HASH_MAX_SIZE];
        size_t verify_hash_len;

        if (!mbedtls_ssl_sig_alg_is_offered(ssl, *sig_alg)) {
            continue;
        }

        if (!mbedtls_ssl_tls13_sig_alg_for_cert_verify_is_supported(*sig_alg)) {
            continue;
        }

        if (!mbedtls_ssl_tls13_check_sig_alg_cert_key_match(*sig_alg, own_key)) {
            continue;
        }

        if (mbedtls_ssl_get_pk_type_and_md_alg_from_sig_alg(
                *sig_alg, &pk_type, &md_alg) != 0) {
            return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
        }

        /* Hash verify buffer with indicated hash function */
        psa_algorithm = mbedtls_md_psa_alg_from_type(md_alg);
        status = psa_hash_compute(psa_algorithm,
                                  verify_buffer,
                                  verify_buffer_len,
                                  verify_hash, sizeof(verify_hash),
                                  &verify_hash_len);
        if (status != PSA_SUCCESS) {
            return PSA_TO_MBEDTLS_ERR(status);
        }

        MBEDTLS_SSL_DEBUG_BUF(3, "verify hash", verify_hash, verify_hash_len);

        if ((ret = mbedtls_pk_sign_ext(pk_type, own_key,
                                       md_alg, verify_hash, verify_hash_len,
                                       p + 4, (size_t) (end - (p + 4)), &signature_len,
                                       ssl->conf->f_rng, ssl->conf->p_rng)) != 0) {
            MBEDTLS_SSL_DEBUG_MSG(2, ("CertificateVerify signature failed with %s",
                                      mbedtls_ssl_sig_alg_to_str(*sig_alg)));
            MBEDTLS_SSL_DEBUG_RET(2, "mbedtls_pk_sign_ext", ret);

            /* The signature failed. This is possible if the private key
             * was not suitable for the signature operation as purposely we
             * did not check its suitability completely. Let's try with
             * another signature algorithm.
             */
            continue;
        }

        MBEDTLS_SSL_DEBUG_MSG(2, ("CertificateVerify signature with %s",
                                  mbedtls_ssl_sig_alg_to_str(*sig_alg)));

        break;
    }

    if (*sig_alg == MBEDTLS_TLS1_3_SIG_NONE) {
        MBEDTLS_SSL_DEBUG_MSG(1, ("no suitable signature algorithm"));
        MBEDTLS_SSL_PEND_FATAL_ALERT(MBEDTLS_SSL_ALERT_MSG_HANDSHAKE_FAILURE,
                                     MBEDTLS_ERR_SSL_HANDSHAKE_FAILURE);
        return MBEDTLS_ERR_SSL_HANDSHAKE_FAILURE;
    }

    MBEDTLS_PUT_UINT16_BE(*sig_alg, p, 0);
    MBEDTLS_PUT_UINT16_BE(signature_len, p, 2);

    *out_len = 4 + signature_len;

    return 0;
}

int mbedtls_ssl_tls13_write_certificate_verify(mbedtls_ssl_context *ssl)
{
    int ret = 0;
    unsigned char *buf;
    size_t buf_len, msg_len;

    MBEDTLS_SSL_DEBUG_MSG(2, ("=> write certificate verify"));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_start_handshake_msg(
                             ssl, MBEDTLS_SSL_HS_CERTIFICATE_VERIFY,
                             &buf, &buf_len));

    MBEDTLS_SSL_PROC_CHK(ssl_tls13_write_certificate_verify_body(
                             ssl, buf, buf + buf_len, &msg_len));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_add_hs_msg_to_checksum(
                             ssl, MBEDTLS_SSL_HS_CERTIFICATE_VERIFY,
                             buf, msg_len));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_finish_handshake_msg(
                             ssl, buf_len, msg_len));

cleanup:

    MBEDTLS_SSL_DEBUG_MSG(2, ("<= write certificate verify"));
    return ret;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_preprocess_finished_message(mbedtls_ssl_context *ssl)
{
    int ret;

    ret = mbedtls_ssl_tls13_calculate_verify_data(
        ssl,
        ssl->handshake->state_local.finished_in.digest,
        sizeof(ssl->handshake->state_local.finished_in.digest),
        &ssl->handshake->state_local.finished_in.digest_len,
        ssl->conf->endpoint == MBEDTLS_SSL_IS_CLIENT ?
        MBEDTLS_SSL_IS_SERVER : MBEDTLS_SSL_IS_CLIENT);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_calculate_verify_data", ret);
        return ret;
    }

    return 0;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_parse_finished_message(mbedtls_ssl_context *ssl,
                                            const unsigned char *buf,
                                            const unsigned char *end)
{
    /*
     * struct {
     *     opaque verify_data[Hash.length];
     * } Finished;
     */
    const unsigned char *expected_verify_data =
        ssl->handshake->state_local.finished_in.digest;
    size_t expected_verify_data_len =
        ssl->handshake->state_local.finished_in.digest_len;
    /* Structural validation */
    if ((size_t) (end - buf) != expected_verify_data_len) {
        MBEDTLS_SSL_DEBUG_MSG(1, ("bad finished message"));

        MBEDTLS_SSL_PEND_FATAL_ALERT(MBEDTLS_SSL_ALERT_MSG_DECODE_ERROR,
                                     MBEDTLS_ERR_SSL_DECODE_ERROR);
        return MBEDTLS_ERR_SSL_DECODE_ERROR;
    }

    MBEDTLS_SSL_DEBUG_BUF(4, "verify_data (self-computed):",
                          expected_verify_data,
                          expected_verify_data_len);
    MBEDTLS_SSL_DEBUG_BUF(4, "verify_data (received message):", buf,
                          expected_verify_data_len);

    /* Semantic validation */
    if (mbedtls_ct_memcmp(buf,
                          expected_verify_data,
                          expected_verify_data_len) != 0) {
        MBEDTLS_SSL_DEBUG_MSG(1, ("bad finished message"));

        MBEDTLS_SSL_PEND_FATAL_ALERT(MBEDTLS_SSL_ALERT_MSG_DECRYPT_ERROR,
                                     MBEDTLS_ERR_SSL_HANDSHAKE_FAILURE);
        return MBEDTLS_ERR_SSL_HANDSHAKE_FAILURE;
    }
    return 0;
}

int mbedtls_ssl_tls13_process_finished_message(mbedtls_ssl_context *ssl)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    unsigned char *buf;
    size_t buf_len;

    MBEDTLS_SSL_DEBUG_MSG(2, ("=> parse finished message"));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_tls13_fetch_handshake_msg(
                             ssl, MBEDTLS_SSL_HS_FINISHED, &buf, &buf_len));

    /* Preprocessing step: Compute handshake digest */
    MBEDTLS_SSL_PROC_CHK(ssl_tls13_preprocess_finished_message(ssl));

    MBEDTLS_SSL_PROC_CHK(ssl_tls13_parse_finished_message(
                             ssl, buf, buf + buf_len));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_add_hs_msg_to_checksum(
                             ssl, MBEDTLS_SSL_HS_FINISHED, buf, buf_len));

cleanup:

    MBEDTLS_SSL_DEBUG_MSG(2, ("<= parse finished message"));
    return ret;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_prepare_finished_message(mbedtls_ssl_context *ssl)
{
    int ret;

    /* Compute transcript of handshake up to now. */
    ret = mbedtls_ssl_tls13_calculate_verify_data(ssl,
                                                  ssl->handshake->state_local.finished_out.digest,
                                                  sizeof(ssl->handshake->state_local.finished_out.
                                                         digest),
                                                  &ssl->handshake->state_local.finished_out.digest_len,
                                                  ssl->conf->endpoint);

    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "calculate_verify_data failed", ret);
        return ret;
    }

    return 0;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_write_finished_message_body(mbedtls_ssl_context *ssl,
                                                 unsigned char *buf,
                                                 unsigned char *end,
                                                 size_t *out_len)
{
    size_t verify_data_len = ssl->handshake->state_local.finished_out.digest_len;
    /*
     * struct {
     *     opaque verify_data[Hash.length];
     * } Finished;
     */
    MBEDTLS_SSL_CHK_BUF_PTR(buf, end, verify_data_len);

    memcpy(buf, ssl->handshake->state_local.finished_out.digest,
           verify_data_len);

    *out_len = verify_data_len;
    return 0;
}

int mbedtls_ssl_tls13_write_finished_message(mbedtls_ssl_context *ssl)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    unsigned char *buf;
    size_t buf_len, msg_len;

    MBEDTLS_SSL_DEBUG_MSG(2, ("=> write finished message"));

    MBEDTLS_SSL_PROC_CHK(ssl_tls13_prepare_finished_message(ssl));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_start_handshake_msg(ssl,
                                                         MBEDTLS_SSL_HS_FINISHED, &buf, &buf_len));

    MBEDTLS_SSL_PROC_CHK(ssl_tls13_write_finished_message_body(
                             ssl, buf, buf + buf_len, &msg_len));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_add_hs_msg_to_checksum(ssl,
                                                            MBEDTLS_SSL_HS_FINISHED, buf, msg_len));

    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_finish_handshake_msg(
                             ssl, buf_len, msg_len));
cleanup:

    MBEDTLS_SSL_DEBUG_MSG(2, ("<= write finished message"));
    return ret;
}

void mbedtls_ssl_tls13_handshake_wrapup(mbedtls_ssl_context *ssl)
{

    MBEDTLS_SSL_DEBUG_MSG(3, ("=> handshake wrapup"));

    MBEDTLS_SSL_DEBUG_MSG(1, ("Switch to application keys for inbound traffic"));
    mbedtls_ssl_set_inbound_transform(ssl, ssl->transform_application);

    MBEDTLS_SSL_DEBUG_MSG(1, ("Switch to application keys for outbound traffic"));
    mbedtls_ssl_set_outbound_transform(ssl, ssl->transform_application);

    /*
     * Free the previous session and switch to the current one.
     */
    if (ssl->session) {
        mbedtls_ssl_session_free(ssl->session);
        mbedtls_free(ssl->session);
    }
    ssl->session = ssl->session_negotiate;
    ssl->session_negotiate = NULL;

    MBEDTLS_SSL_DEBUG_MSG(3, ("<= handshake wrapup"));
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_write_change_cipher_spec_body(mbedtls_ssl_context *ssl,
                                                   unsigned char *buf,
                                                   unsigned char *end,
                                                   size_t *olen)
{
    ((void) ssl);

    MBEDTLS_SSL_CHK_BUF_PTR(buf, end, 1);
    buf[0] = 1;
    *olen = 1;

    return 0;
}

int mbedtls_ssl_tls13_write_change_cipher_spec(mbedtls_ssl_context *ssl)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;

    MBEDTLS_SSL_DEBUG_MSG(2, ("=> write change cipher spec"));

    /* Only one CCS to send. */
    if (ssl->handshake->ccs_sent) {
        ret = 0;
        goto cleanup;
    }

    /* Write CCS message */
    MBEDTLS_SSL_PROC_CHK(ssl_tls13_write_change_cipher_spec_body(
                             ssl, ssl->out_msg,
                             ssl->out_msg + MBEDTLS_SSL_OUT_CONTENT_LEN,
                             &ssl->out_msglen));

    ssl->out_msgtype = MBEDTLS_SSL_MSG_CHANGE_CIPHER_SPEC;

    /* Dispatch message */
    MBEDTLS_SSL_PROC_CHK(mbedtls_ssl_write_record(ssl, 0));

    ssl->handshake->ccs_sent = 1;

cleanup:

    MBEDTLS_SSL_DEBUG_MSG(2, ("<= write change cipher spec"));
    return ret;
}

int mbedtls_ssl_tls13_write_early_data_ext(mbedtls_ssl_context *ssl,
                                           int in_new_session_ticket,
                                           unsigned char *buf,
                                           const unsigned char *end,
                                           size_t *out_len)
{
    unsigned char *p = buf;

#if defined(MBEDTLS_SSL_SRV_C)
    const size_t needed = in_new_session_ticket ? 8 : 4;
#else
    const size_t needed = 4;
    ((void) in_new_session_ticket);
#endif

    *out_len = 0;

    MBEDTLS_SSL_CHK_BUF_PTR(p, end, needed);

    MBEDTLS_PUT_UINT16_BE(MBEDTLS_TLS_EXT_EARLY_DATA, p, 0);
    MBEDTLS_PUT_UINT16_BE(needed - 4, p, 2);

#if defined(MBEDTLS_SSL_SRV_C)
    if (in_new_session_ticket) {
        MBEDTLS_PUT_UINT32_BE(ssl->conf->max_early_data_size, p, 4);
        MBEDTLS_SSL_DEBUG_MSG(
            4, ("Sent max_early_data_size=%u",
                (unsigned int) ssl->conf->max_early_data_size));
    }
#endif

    *out_len = needed;

    mbedtls_ssl_tls13_set_hs_sent_ext_mask(ssl, MBEDTLS_TLS_EXT_EARLY_DATA);

    return 0;
}

int mbedtls_ssl_tls13_check_early_data_len(mbedtls_ssl_context *ssl,
                                           size_t early_data_len)
{
    /*
     * This function should be called only while an handshake is in progress
     * and thus a session under negotiation. Add a sanity check to detect a
     * misuse.
     */
    if (ssl->session_negotiate == NULL) {
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    /* RFC 8446 section 4.6.1
     *
     * A server receiving more than max_early_data_size bytes of 0-RTT data
     * SHOULD terminate the connection with an "unexpected_message" alert.
     * Note that if it is still possible to send early_data_len bytes of early
     * data, it means that early_data_len is smaller than max_early_data_size
     * (type uint32_t) and can fit in an uint32_t. We use this further
     * down.
     */
    if (early_data_len >
        (ssl->session_negotiate->max_early_data_size -
         ssl->total_early_data_size)) {

        MBEDTLS_SSL_DEBUG_MSG(
            2, ("EarlyData: Too much early data received, "
                "%lu + %" MBEDTLS_PRINTF_SIZET " > %lu",
                (unsigned long) ssl->total_early_data_size,
                early_data_len,
                (unsigned long) ssl->session_negotiate->max_early_data_size));

        MBEDTLS_SSL_PEND_FATAL_ALERT(
            MBEDTLS_SSL_ALERT_MSG_UNEXPECTED_MESSAGE,
            MBEDTLS_ERR_SSL_UNEXPECTED_MESSAGE);
        return MBEDTLS_ERR_SSL_UNEXPECTED_MESSAGE;
    }

    /*
     * early_data_len has been checked to be less than max_early_data_size
     * that is uint32_t. Its cast to an uint32_t below is thus safe. We need
     * the cast to appease some compilers.
     */
    ssl->total_early_data_size += (uint32_t) early_data_len;

    return 0;
}

int mbedtls_ssl_reset_transcript_for_hrr(mbedtls_ssl_context *ssl)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    unsigned char hash_transcript[PSA_HASH_MAX_SIZE + 4];
    size_t hash_len;
    const mbedtls_ssl_ciphersuite_t *ciphersuite_info =
        ssl->handshake->ciphersuite_info;

    MBEDTLS_SSL_DEBUG_MSG(3, ("Reset SSL session for HRR"));

    ret = mbedtls_ssl_get_handshake_transcript(ssl, (mbedtls_md_type_t) ciphersuite_info->mac,
                                               hash_transcript + 4,
                                               PSA_HASH_MAX_SIZE,
                                               &hash_len);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_get_handshake_transcript", ret);
        return ret;
    }

    hash_transcript[0] = MBEDTLS_SSL_HS_MESSAGE_HASH;
    hash_transcript[1] = 0;
    hash_transcript[2] = 0;
    hash_transcript[3] = (unsigned char) hash_len;

    hash_len += 4;

    MBEDTLS_SSL_DEBUG_BUF(4, "Truncated handshake transcript",
                          hash_transcript, hash_len);

    /* Reset running hash and replace it with a hash of the transcript */
    ret = mbedtls_ssl_reset_checksum(ssl);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_reset_checksum", ret);
        return ret;
    }
    ret = ssl->handshake->update_checksum(ssl, hash_transcript, hash_len);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "update_checksum", ret);
        return ret;
    }

    return ret;
}

int mbedtls_ssl_tls13_read_public_xxdhe_share(mbedtls_ssl_context *ssl,
                                              const unsigned char *buf,
                                              size_t buf_len)
{
    uint8_t *p = (uint8_t *) buf;
    const uint8_t *end = buf + buf_len;
    mbedtls_ssl_handshake_params *handshake = ssl->handshake;

    /* Get size of the TLS opaque key_exchange field of the KeyShareEntry struct. */
    MBEDTLS_SSL_CHK_BUF_READ_PTR(p, end, 2);
    uint16_t peerkey_len = MBEDTLS_GET_UINT16_BE(p, 0);
    p += 2;

    /* Check if key size is consistent with given buffer length. */
    MBEDTLS_SSL_CHK_BUF_READ_PTR(p, end, peerkey_len);

    /* Store peer's ECDH/FFDH public key. */
    if (peerkey_len > sizeof(handshake->xxdh_psa_peerkey)) {
        MBEDTLS_SSL_DEBUG_MSG(1, ("Invalid public key length: %u > %" MBEDTLS_PRINTF_SIZET,
                                  (unsigned) peerkey_len,
                                  sizeof(handshake->xxdh_psa_peerkey)));
        return MBEDTLS_ERR_SSL_HANDSHAKE_FAILURE;
    }
    memcpy(handshake->xxdh_psa_peerkey, p, peerkey_len);
    handshake->xxdh_psa_peerkey_len = peerkey_len;

    return 0;
}

static psa_status_t  mbedtls_ssl_get_psa_ffdh_info_from_tls_id(
    uint16_t tls_id, size_t *bits, psa_key_type_t *key_type)
{
    switch (tls_id) {
#if defined(PSA_WANT_DH_RFC7919_2048)
        case MBEDTLS_SSL_IANA_TLS_GROUP_FFDHE2048:
            *bits = 2048;
            *key_type = PSA_KEY_TYPE_DH_KEY_PAIR(PSA_DH_FAMILY_RFC7919);
            return PSA_SUCCESS;
#endif /* PSA_WANT_DH_RFC7919_2048 */
#if defined(PSA_WANT_DH_RFC7919_3072)
        case MBEDTLS_SSL_IANA_TLS_GROUP_FFDHE3072:
            *bits = 3072;
            *key_type =  PSA_KEY_TYPE_DH_KEY_PAIR(PSA_DH_FAMILY_RFC7919);
            return PSA_SUCCESS;
#endif /* PSA_WANT_DH_RFC7919_3072 */
#if defined(PSA_WANT_DH_RFC7919_4096)
        case MBEDTLS_SSL_IANA_TLS_GROUP_FFDHE4096:
            *bits = 4096;
            *key_type =  PSA_KEY_TYPE_DH_KEY_PAIR(PSA_DH_FAMILY_RFC7919);
            return PSA_SUCCESS;
#endif /* PSA_WANT_DH_RFC7919_4096 */
#if defined(PSA_WANT_DH_RFC7919_6144)
        case MBEDTLS_SSL_IANA_TLS_GROUP_FFDHE6144:
            *bits = 6144;
            *key_type =  PSA_KEY_TYPE_DH_KEY_PAIR(PSA_DH_FAMILY_RFC7919);
            return PSA_SUCCESS;
#endif /* PSA_WANT_DH_RFC7919_6144 */
#if defined(PSA_WANT_DH_RFC7919_8192)
        case MBEDTLS_SSL_IANA_TLS_GROUP_FFDHE8192:
            *bits = 8192;
            *key_type =  PSA_KEY_TYPE_DH_KEY_PAIR(PSA_DH_FAMILY_RFC7919);
            return PSA_SUCCESS;
#endif /* PSA_WANT_DH_RFC7919_8192 */
        default:
            return PSA_ERROR_NOT_SUPPORTED;
    }
}

int mbedtls_ssl_tls13_generate_and_write_xxdh_key_exchange(
    mbedtls_ssl_context *ssl,
    uint16_t named_group,
    unsigned char *buf,
    unsigned char *end,
    size_t *out_len)
{
    psa_status_t status = PSA_ERROR_GENERIC_ERROR;
    int ret = MBEDTLS_ERR_SSL_FEATURE_UNAVAILABLE;
    psa_key_attributes_t key_attributes;
    size_t own_pubkey_len;
    mbedtls_ssl_handshake_params *handshake = ssl->handshake;
    size_t bits = 0;
    psa_key_type_t key_type = PSA_KEY_TYPE_NONE;
    psa_algorithm_t alg = PSA_ALG_NONE;
    size_t buf_size = (size_t) (end - buf);

    MBEDTLS_SSL_DEBUG_MSG(1, ("Perform PSA-based ECDH/FFDH computation."));

    /* Convert EC's TLS ID to PSA key type. */
#if defined(PSA_WANT_ALG_ECDH)
    if (mbedtls_ssl_get_psa_curve_info_from_tls_id(
            named_group, &key_type, &bits) == PSA_SUCCESS) {
        alg = PSA_ALG_ECDH;
    }
#endif
#if defined(PSA_WANT_ALG_FFDH)
    if (mbedtls_ssl_get_psa_ffdh_info_from_tls_id(named_group, &bits,
                                                  &key_type) == PSA_SUCCESS) {
        alg = PSA_ALG_FFDH;
    }
#endif

    if (key_type == PSA_KEY_TYPE_NONE) {
        return MBEDTLS_ERR_SSL_HANDSHAKE_FAILURE;
    }

    if (buf_size < PSA_BITS_TO_BYTES(bits)) {
        return MBEDTLS_ERR_SSL_BUFFER_TOO_SMALL;
    }

    handshake->xxdh_psa_type = key_type;
    ssl->handshake->xxdh_psa_bits = bits;

    key_attributes = psa_key_attributes_init();
    psa_set_key_usage_flags(&key_attributes, PSA_KEY_USAGE_DERIVE);
    psa_set_key_algorithm(&key_attributes, alg);
    psa_set_key_type(&key_attributes, handshake->xxdh_psa_type);
    psa_set_key_bits(&key_attributes, handshake->xxdh_psa_bits);

    /* Generate ECDH/FFDH private key. */
    status = psa_generate_key(&key_attributes,
                              &handshake->xxdh_psa_privkey);
    if (status != PSA_SUCCESS) {
        ret = PSA_TO_MBEDTLS_ERR(status);
        MBEDTLS_SSL_DEBUG_RET(1, "psa_generate_key", ret);
        return ret;

    }

    /* Export the public part of the ECDH/FFDH private key from PSA. */
    status = psa_export_public_key(handshake->xxdh_psa_privkey,
                                   buf, buf_size,
                                   &own_pubkey_len);

    if (status != PSA_SUCCESS) {
        ret = PSA_TO_MBEDTLS_ERR(status);
        MBEDTLS_SSL_DEBUG_RET(1, "psa_export_public_key", ret);
        return ret;
    }

    *out_len = own_pubkey_len;

    return 0;
}

int mbedtls_ssl_tls13_check_received_extension(
    mbedtls_ssl_context *ssl,
    int hs_msg_type,
    unsigned int received_extension_type,
    uint32_t hs_msg_allowed_extensions_mask)
{
    uint32_t extension_mask = mbedtls_ssl_get_extension_mask(
        received_extension_type);

    MBEDTLS_SSL_PRINT_EXT(
        3, hs_msg_type, received_extension_type, "received");

    if ((extension_mask & hs_msg_allowed_extensions_mask) == 0) {
        MBEDTLS_SSL_PRINT_EXT(
            3, hs_msg_type, received_extension_type, "is illegal");
        MBEDTLS_SSL_PEND_FATAL_ALERT(
            MBEDTLS_SSL_ALERT_MSG_ILLEGAL_PARAMETER,
            MBEDTLS_ERR_SSL_ILLEGAL_PARAMETER);
        return MBEDTLS_ERR_SSL_ILLEGAL_PARAMETER;
    }

    ssl->handshake->received_extensions |= extension_mask;
    /*
     * If it is a message containing extension responses, check that we
     * previously sent the extension.
     */
    switch (hs_msg_type) {
        case MBEDTLS_SSL_HS_SERVER_HELLO:
        case MBEDTLS_SSL_TLS1_3_HS_HELLO_RETRY_REQUEST:
        case MBEDTLS_SSL_HS_ENCRYPTED_EXTENSIONS:
        case MBEDTLS_SSL_HS_CERTIFICATE:
            /* Check if the received extension is sent by peer message.*/
            if ((ssl->handshake->sent_extensions & extension_mask) != 0) {
                return 0;
            }
            break;
        default:
            return 0;
    }

    MBEDTLS_SSL_PRINT_EXT(
        3, hs_msg_type, received_extension_type, "is unsupported");
    MBEDTLS_SSL_PEND_FATAL_ALERT(
        MBEDTLS_SSL_ALERT_MSG_UNSUPPORTED_EXT,
        MBEDTLS_ERR_SSL_UNSUPPORTED_EXTENSION);
    return MBEDTLS_ERR_SSL_UNSUPPORTED_EXTENSION;
}

MBEDTLS_CHECK_RETURN_CRITICAL
int mbedtls_ssl_tls13_parse_record_size_limit_ext(mbedtls_ssl_context *ssl,
                                                  const unsigned char *buf,
                                                  const unsigned char *end)
{
    const unsigned char *p = buf;
    uint16_t record_size_limit;
    const size_t extension_data_len = end - buf;

    if (extension_data_len !=
        MBEDTLS_SSL_RECORD_SIZE_LIMIT_EXTENSION_DATA_LENGTH) {
        MBEDTLS_SSL_DEBUG_MSG(2,
                              ("record_size_limit extension has invalid length: %"
                               MBEDTLS_PRINTF_SIZET " Bytes",
                               extension_data_len));

        MBEDTLS_SSL_PEND_FATAL_ALERT(
            MBEDTLS_SSL_ALERT_MSG_ILLEGAL_PARAMETER,
            MBEDTLS_ERR_SSL_ILLEGAL_PARAMETER);
        return MBEDTLS_ERR_SSL_ILLEGAL_PARAMETER;
    }

    MBEDTLS_SSL_CHK_BUF_READ_PTR(p, end, 2);
    record_size_limit = MBEDTLS_GET_UINT16_BE(p, 0);

    MBEDTLS_SSL_DEBUG_MSG(2, ("RecordSizeLimit: %u Bytes", record_size_limit));

    /* RFC 8449, section 4:
     *
     * Endpoints MUST NOT send a "record_size_limit" extension with a value
     * smaller than 64.  An endpoint MUST treat receipt of a smaller value
     * as a fatal error and generate an "illegal_parameter" alert.
     */
    if (record_size_limit < MBEDTLS_SSL_RECORD_SIZE_LIMIT_MIN) {
        MBEDTLS_SSL_DEBUG_MSG(1, ("Invalid record size limit : %u Bytes",
                                  record_size_limit));
        MBEDTLS_SSL_PEND_FATAL_ALERT(
            MBEDTLS_SSL_ALERT_MSG_ILLEGAL_PARAMETER,
            MBEDTLS_ERR_SSL_ILLEGAL_PARAMETER);
        return MBEDTLS_ERR_SSL_ILLEGAL_PARAMETER;
    }

    ssl->session_negotiate->record_size_limit = record_size_limit;

    return 0;
}

MBEDTLS_CHECK_RETURN_CRITICAL
int mbedtls_ssl_tls13_write_record_size_limit_ext(mbedtls_ssl_context *ssl,
                                                  unsigned char *buf,
                                                  const unsigned char *end,
                                                  size_t *out_len)
{
    unsigned char *p = buf;
    *out_len = 0;

    MBEDTLS_STATIC_ASSERT(MBEDTLS_SSL_IN_CONTENT_LEN >= MBEDTLS_SSL_RECORD_SIZE_LIMIT_MIN,
                          "MBEDTLS_SSL_IN_CONTENT_LEN is less than the "
                          "minimum record size limit");

    MBEDTLS_SSL_CHK_BUF_PTR(p, end, 6);

    MBEDTLS_PUT_UINT16_BE(MBEDTLS_TLS_EXT_RECORD_SIZE_LIMIT, p, 0);
    MBEDTLS_PUT_UINT16_BE(MBEDTLS_SSL_RECORD_SIZE_LIMIT_EXTENSION_DATA_LENGTH,
                          p, 2);
    MBEDTLS_PUT_UINT16_BE(MBEDTLS_SSL_IN_CONTENT_LEN, p, 4);

    *out_len = 6;

    MBEDTLS_SSL_DEBUG_MSG(2, ("Sent RecordSizeLimit: %d Bytes",
                              MBEDTLS_SSL_IN_CONTENT_LEN));

    mbedtls_ssl_tls13_set_hs_sent_ext_mask(ssl, MBEDTLS_TLS_EXT_RECORD_SIZE_LIMIT);

    return 0;
}

static int local_err_translation(psa_status_t status)
{
    return psa_status_to_mbedtls(status, psa_to_ssl_errors,
                                 ARRAY_LENGTH(psa_to_ssl_errors),
                                 psa_generic_status_to_mbedtls);
}

static void ssl_tls13_hkdf_encode_label(
    size_t desired_length,
    const unsigned char *label, size_t label_len,
    const unsigned char *ctx, size_t ctx_len,
    unsigned char *dst, size_t *dst_len)
{
    size_t total_label_len =
        sizeof(tls13_label_prefix) + label_len;
    size_t total_hkdf_lbl_len =
        SSL_TLS1_3_KEY_SCHEDULE_HKDF_LABEL_LEN(total_label_len, ctx_len);

    unsigned char *p = dst;

    /* Add the size of the expanded key material. */
#if MBEDTLS_SSL_TLS1_3_KEY_SCHEDULE_MAX_EXPANSION_LEN > UINT16_MAX
#error "The desired key length must fit into an uint16 but \
    MBEDTLS_SSL_TLS1_3_KEY_SCHEDULE_MAX_EXPANSION_LEN is greater than UINT16_MAX"
#endif

    *p++ = MBEDTLS_BYTE_1(desired_length);
    *p++ = MBEDTLS_BYTE_0(desired_length);

    /* Add label incl. prefix */
    *p++ = MBEDTLS_BYTE_0(total_label_len);
    memcpy(p, tls13_label_prefix, sizeof(tls13_label_prefix));
    p += sizeof(tls13_label_prefix);
    memcpy(p, label, label_len);
    p += label_len;

    /* Add context value */
    *p++ = MBEDTLS_BYTE_0(ctx_len);
    if (ctx_len != 0) {
        memcpy(p, ctx, ctx_len);
    }

    /* Return total length to the caller.  */
    *dst_len = total_hkdf_lbl_len;
}

int mbedtls_ssl_tls13_hkdf_expand_label(
    psa_algorithm_t hash_alg,
    const unsigned char *secret, size_t secret_len,
    const unsigned char *label, size_t label_len,
    const unsigned char *ctx, size_t ctx_len,
    unsigned char *buf, size_t buf_len)
{
    unsigned char hkdf_label[SSL_TLS1_3_KEY_SCHEDULE_MAX_HKDF_LABEL_LEN];
    size_t hkdf_label_len = 0;
    psa_status_t status = PSA_ERROR_CORRUPTION_DETECTED;
    psa_status_t abort_status = PSA_ERROR_CORRUPTION_DETECTED;
    psa_key_derivation_operation_t operation =
        PSA_KEY_DERIVATION_OPERATION_INIT;

    if (label_len > MBEDTLS_SSL_TLS1_3_HKDF_LABEL_MAX_LABEL_LEN) {
        /* Should never happen since this is an internal
         * function, and we know statically which labels
         * are allowed. */
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    if (ctx_len > MBEDTLS_SSL_TLS1_3_KEY_SCHEDULE_MAX_CONTEXT_LEN) {
        /* Should not happen, as above. */
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    if (buf_len > MBEDTLS_SSL_TLS1_3_KEY_SCHEDULE_MAX_EXPANSION_LEN) {
        /* Should not happen, as above. */
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    if (!PSA_ALG_IS_HASH(hash_alg)) {
        return MBEDTLS_ERR_SSL_BAD_INPUT_DATA;
    }

    ssl_tls13_hkdf_encode_label(buf_len,
                                label, label_len,
                                ctx, ctx_len,
                                hkdf_label,
                                &hkdf_label_len);

    status = psa_key_derivation_setup(&operation, PSA_ALG_HKDF_EXPAND(hash_alg));

    if (status != PSA_SUCCESS) {
        goto cleanup;
    }

    status = psa_key_derivation_input_bytes(&operation,
                                            PSA_KEY_DERIVATION_INPUT_SECRET,
                                            secret,
                                            secret_len);

    if (status != PSA_SUCCESS) {
        goto cleanup;
    }

    status = psa_key_derivation_input_bytes(&operation,
                                            PSA_KEY_DERIVATION_INPUT_INFO,
                                            hkdf_label,
                                            hkdf_label_len);

    if (status != PSA_SUCCESS) {
        goto cleanup;
    }

    status = psa_key_derivation_output_bytes(&operation,
                                             buf,
                                             buf_len);

    if (status != PSA_SUCCESS) {
        goto cleanup;
    }

cleanup:
    abort_status = psa_key_derivation_abort(&operation);
    status = (status == PSA_SUCCESS ? abort_status : status);
    mbedtls_platform_zeroize(hkdf_label, hkdf_label_len);
    return PSA_TO_MBEDTLS_ERR(status);
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_make_traffic_key(
    psa_algorithm_t hash_alg,
    const unsigned char *secret, size_t secret_len,
    unsigned char *key, size_t key_len,
    unsigned char *iv, size_t iv_len)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;

    ret = mbedtls_ssl_tls13_hkdf_expand_label(
        hash_alg,
        secret, secret_len,
        MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(key),
        NULL, 0,
        key, key_len);
    if (ret != 0) {
        return ret;
    }

    ret = mbedtls_ssl_tls13_hkdf_expand_label(
        hash_alg,
        secret, secret_len,
        MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(iv),
        NULL, 0,
        iv, iv_len);
    return ret;
}

int mbedtls_ssl_tls13_make_traffic_keys(
    psa_algorithm_t hash_alg,
    const unsigned char *client_secret,
    const unsigned char *server_secret, size_t secret_len,
    size_t key_len, size_t iv_len,
    mbedtls_ssl_key_set *keys)
{
    int ret = 0;

    ret = ssl_tls13_make_traffic_key(
        hash_alg, client_secret, secret_len,
        keys->client_write_key, key_len,
        keys->client_write_iv, iv_len);
    if (ret != 0) {
        return ret;
    }

    ret = ssl_tls13_make_traffic_key(
        hash_alg, server_secret, secret_len,
        keys->server_write_key, key_len,
        keys->server_write_iv, iv_len);
    if (ret != 0) {
        return ret;
    }

    keys->key_len = key_len;
    keys->iv_len = iv_len;

    return 0;
}

int mbedtls_ssl_tls13_derive_secret(
    psa_algorithm_t hash_alg,
    const unsigned char *secret, size_t secret_len,
    const unsigned char *label, size_t label_len,
    const unsigned char *ctx, size_t ctx_len,
    int ctx_hashed,
    unsigned char *dstbuf, size_t dstbuf_len)
{
    int ret;
    unsigned char hashed_context[PSA_HASH_MAX_SIZE];
    if (ctx_hashed == MBEDTLS_SSL_TLS1_3_CONTEXT_UNHASHED) {
        psa_status_t status = PSA_ERROR_CORRUPTION_DETECTED;

        status = psa_hash_compute(hash_alg, ctx, ctx_len, hashed_context,
                                  PSA_HASH_LENGTH(hash_alg), &ctx_len);
        if (status != PSA_SUCCESS) {
            ret = PSA_TO_MBEDTLS_ERR(status);
            return ret;
        }
    } else {
        if (ctx_len > sizeof(hashed_context)) {
            /* This should never happen since this function is internal
             * and the code sets `ctx_hashed` correctly.
             * Let's double-check nonetheless to not run at the risk
             * of getting a stack overflow. */
            return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
        }

        memcpy(hashed_context, ctx, ctx_len);
    }

    return mbedtls_ssl_tls13_hkdf_expand_label(hash_alg,
                                               secret, secret_len,
                                               label, label_len,
                                               hashed_context, ctx_len,
                                               dstbuf, dstbuf_len);

}

int mbedtls_ssl_tls13_evolve_secret(
    psa_algorithm_t hash_alg,
    const unsigned char *secret_old,
    const unsigned char *input, size_t input_len,
    unsigned char *secret_new)
{
    int ret = MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    psa_status_t status = PSA_ERROR_CORRUPTION_DETECTED;
    psa_status_t abort_status = PSA_ERROR_CORRUPTION_DETECTED;
    size_t hlen;
    unsigned char tmp_secret[PSA_MAC_MAX_SIZE] = { 0 };
    const unsigned char all_zeroes_input[MBEDTLS_TLS1_3_MD_MAX_SIZE] = { 0 };
    const unsigned char *l_input = NULL;
    size_t l_input_len;

    psa_key_derivation_operation_t operation =
        PSA_KEY_DERIVATION_OPERATION_INIT;

    if (!PSA_ALG_IS_HASH(hash_alg)) {
        return MBEDTLS_ERR_SSL_BAD_INPUT_DATA;
    }

    hlen = PSA_HASH_LENGTH(hash_alg);

    /* For non-initial runs, call Derive-Secret( ., "derived", "")
     * on the old secret. */
    if (secret_old != NULL) {
        ret = mbedtls_ssl_tls13_derive_secret(
            hash_alg,
            secret_old, hlen,
            MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(derived),
            NULL, 0,        /* context */
            MBEDTLS_SSL_TLS1_3_CONTEXT_UNHASHED,
            tmp_secret, hlen);
        if (ret != 0) {
            goto cleanup;
        }
    }

    ret = 0;

    if (input != NULL && input_len != 0) {
        l_input = input;
        l_input_len = input_len;
    } else {
        l_input = all_zeroes_input;
        l_input_len = hlen;
    }

    status = psa_key_derivation_setup(&operation,
                                      PSA_ALG_HKDF_EXTRACT(hash_alg));

    if (status != PSA_SUCCESS) {
        goto cleanup;
    }

    status = psa_key_derivation_input_bytes(&operation,
                                            PSA_KEY_DERIVATION_INPUT_SALT,
                                            tmp_secret,
                                            hlen);

    if (status != PSA_SUCCESS) {
        goto cleanup;
    }

    status = psa_key_derivation_input_bytes(&operation,
                                            PSA_KEY_DERIVATION_INPUT_SECRET,
                                            l_input, l_input_len);

    if (status != PSA_SUCCESS) {
        goto cleanup;
    }

    status = psa_key_derivation_output_bytes(&operation,
                                             secret_new,
                                             PSA_HASH_LENGTH(hash_alg));

    if (status != PSA_SUCCESS) {
        goto cleanup;
    }

cleanup:
    abort_status = psa_key_derivation_abort(&operation);
    status = (status == PSA_SUCCESS ? abort_status : status);
    ret = (ret == 0 ? PSA_TO_MBEDTLS_ERR(status) : ret);
    mbedtls_platform_zeroize(tmp_secret, sizeof(tmp_secret));
    return ret;
}

int mbedtls_ssl_tls13_derive_early_secrets(
    psa_algorithm_t hash_alg,
    unsigned char const *early_secret,
    unsigned char const *transcript, size_t transcript_len,
    mbedtls_ssl_tls13_early_secrets *derived)
{
    int ret;
    size_t const hash_len = PSA_HASH_LENGTH(hash_alg);

    /* We should never call this function with an unknown hash,
     * but add an assertion anyway. */
    if (!PSA_ALG_IS_HASH(hash_alg)) {
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    /*
     *            0
     *            |
     *            v
     *  PSK ->  HKDF-Extract = Early Secret
     *            |
     *            +-----> Derive-Secret(., "c e traffic", ClientHello)
     *            |                     = client_early_traffic_secret
     *            |
     *            +-----> Derive-Secret(., "e exp master", ClientHello)
     *            |                     = early_exporter_master_secret
     *            v
     */

    /* Create client_early_traffic_secret */
    ret = mbedtls_ssl_tls13_derive_secret(
        hash_alg,
        early_secret, hash_len,
        MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(c_e_traffic),
        transcript, transcript_len,
        MBEDTLS_SSL_TLS1_3_CONTEXT_HASHED,
        derived->client_early_traffic_secret,
        hash_len);
    if (ret != 0) {
        return ret;
    }

    /* Create early exporter */
    ret = mbedtls_ssl_tls13_derive_secret(
        hash_alg,
        early_secret, hash_len,
        MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(e_exp_master),
        transcript, transcript_len,
        MBEDTLS_SSL_TLS1_3_CONTEXT_HASHED,
        derived->early_exporter_master_secret,
        hash_len);
    if (ret != 0) {
        return ret;
    }

    return 0;
}

int mbedtls_ssl_tls13_derive_handshake_secrets(
    psa_algorithm_t hash_alg,
    unsigned char const *handshake_secret,
    unsigned char const *transcript, size_t transcript_len,
    mbedtls_ssl_tls13_handshake_secrets *derived)
{
    int ret;
    size_t const hash_len = PSA_HASH_LENGTH(hash_alg);

    /* We should never call this function with an unknown hash,
     * but add an assertion anyway. */
    if (!PSA_ALG_IS_HASH(hash_alg)) {
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    /*
     *
     * Handshake Secret
     * |
     * +-----> Derive-Secret( ., "c hs traffic",
     * |                     ClientHello...ServerHello )
     * |                     = client_handshake_traffic_secret
     * |
     * +-----> Derive-Secret( ., "s hs traffic",
     * |                     ClientHello...ServerHello )
     * |                     = server_handshake_traffic_secret
     *
     */

    /*
     * Compute client_handshake_traffic_secret with
     * Derive-Secret( ., "c hs traffic", ClientHello...ServerHello )
     */

    ret = mbedtls_ssl_tls13_derive_secret(
        hash_alg,
        handshake_secret, hash_len,
        MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(c_hs_traffic),
        transcript, transcript_len,
        MBEDTLS_SSL_TLS1_3_CONTEXT_HASHED,
        derived->client_handshake_traffic_secret,
        hash_len);
    if (ret != 0) {
        return ret;
    }

    /*
     * Compute server_handshake_traffic_secret with
     * Derive-Secret( ., "s hs traffic", ClientHello...ServerHello )
     */

    ret = mbedtls_ssl_tls13_derive_secret(
        hash_alg,
        handshake_secret, hash_len,
        MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(s_hs_traffic),
        transcript, transcript_len,
        MBEDTLS_SSL_TLS1_3_CONTEXT_HASHED,
        derived->server_handshake_traffic_secret,
        hash_len);
    if (ret != 0) {
        return ret;
    }

    return 0;
}

int mbedtls_ssl_tls13_derive_application_secrets(
    psa_algorithm_t hash_alg,
    unsigned char const *application_secret,
    unsigned char const *transcript, size_t transcript_len,
    mbedtls_ssl_tls13_application_secrets *derived)
{
    int ret;
    size_t const hash_len = PSA_HASH_LENGTH(hash_alg);

    /* We should never call this function with an unknown hash,
     * but add an assertion anyway. */
    if (!PSA_ALG_IS_HASH(hash_alg)) {
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    /* Generate {client,server}_application_traffic_secret_0
     *
     * Master Secret
     * |
     * +-----> Derive-Secret( ., "c ap traffic",
     * |                      ClientHello...server Finished )
     * |                      = client_application_traffic_secret_0
     * |
     * +-----> Derive-Secret( ., "s ap traffic",
     * |                      ClientHello...Server Finished )
     * |                      = server_application_traffic_secret_0
     * |
     * +-----> Derive-Secret( ., "exp master",
     * |                      ClientHello...server Finished)
     * |                      = exporter_master_secret
     *
     */

    ret = mbedtls_ssl_tls13_derive_secret(
        hash_alg,
        application_secret, hash_len,
        MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(c_ap_traffic),
        transcript, transcript_len,
        MBEDTLS_SSL_TLS1_3_CONTEXT_HASHED,
        derived->client_application_traffic_secret_N,
        hash_len);
    if (ret != 0) {
        return ret;
    }

    ret = mbedtls_ssl_tls13_derive_secret(
        hash_alg,
        application_secret, hash_len,
        MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(s_ap_traffic),
        transcript, transcript_len,
        MBEDTLS_SSL_TLS1_3_CONTEXT_HASHED,
        derived->server_application_traffic_secret_N,
        hash_len);
    if (ret != 0) {
        return ret;
    }

    ret = mbedtls_ssl_tls13_derive_secret(
        hash_alg,
        application_secret, hash_len,
        MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(exp_master),
        transcript, transcript_len,
        MBEDTLS_SSL_TLS1_3_CONTEXT_HASHED,
        derived->exporter_master_secret,
        hash_len);
    if (ret != 0) {
        return ret;
    }

    return 0;
}

int mbedtls_ssl_tls13_derive_resumption_master_secret(
    psa_algorithm_t hash_alg,
    unsigned char const *application_secret,
    unsigned char const *transcript, size_t transcript_len,
    mbedtls_ssl_tls13_application_secrets *derived)
{
    int ret;
    size_t const hash_len = PSA_HASH_LENGTH(hash_alg);

    /* We should never call this function with an unknown hash,
     * but add an assertion anyway. */
    if (!PSA_ALG_IS_HASH(hash_alg)) {
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    ret = mbedtls_ssl_tls13_derive_secret(
        hash_alg,
        application_secret, hash_len,
        MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(res_master),
        transcript, transcript_len,
        MBEDTLS_SSL_TLS1_3_CONTEXT_HASHED,
        derived->resumption_master_secret,
        hash_len);

    if (ret != 0) {
        return ret;
    }

    return 0;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_key_schedule_stage_application(mbedtls_ssl_context *ssl)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_ssl_handshake_params *handshake = ssl->handshake;
    psa_algorithm_t const hash_alg = mbedtls_md_psa_alg_from_type(
        (mbedtls_md_type_t) handshake->ciphersuite_info->mac);

    /*
     * Compute MasterSecret
     */
    ret = mbedtls_ssl_tls13_evolve_secret(
        hash_alg,
        handshake->tls13_master_secrets.handshake,
        NULL, 0,
        handshake->tls13_master_secrets.app);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_evolve_secret", ret);
        return ret;
    }

    MBEDTLS_SSL_DEBUG_BUF(
        4, "Master secret",
        handshake->tls13_master_secrets.app, PSA_HASH_LENGTH(hash_alg));

    return 0;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_calc_finished_core(psa_algorithm_t hash_alg,
                                        unsigned char const *base_key,
                                        unsigned char const *transcript,
                                        unsigned char *dst,
                                        size_t *dst_len)
{
    mbedtls_svc_key_id_t key = MBEDTLS_SVC_KEY_ID_INIT;
    psa_key_attributes_t attributes = PSA_KEY_ATTRIBUTES_INIT;
    psa_status_t status = PSA_ERROR_CORRUPTION_DETECTED;
    size_t hash_len = PSA_HASH_LENGTH(hash_alg);
    unsigned char finished_key[PSA_MAC_MAX_SIZE];
    int ret;
    psa_algorithm_t alg;

    /* We should never call this function with an unknown hash,
     * but add an assertion anyway. */
    if (!PSA_ALG_IS_HASH(hash_alg)) {
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    /* TLS 1.3 Finished message
     *
     * struct {
     *     opaque verify_data[Hash.length];
     * } Finished;
     *
     * verify_data =
     *     HMAC( finished_key,
     *            Hash( Handshake Context +
     *                  Certificate*      +
     *                  CertificateVerify* )
     *    )
     *
     * finished_key =
     *    HKDF-Expand-Label( BaseKey, "finished", "", Hash.length )
     */

    ret = mbedtls_ssl_tls13_hkdf_expand_label(
        hash_alg, base_key, hash_len,
        MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(finished),
        NULL, 0,
        finished_key, hash_len);
    if (ret != 0) {
        goto exit;
    }

    alg = PSA_ALG_HMAC(hash_alg);
    psa_set_key_usage_flags(&attributes, PSA_KEY_USAGE_SIGN_MESSAGE);
    psa_set_key_algorithm(&attributes, alg);
    psa_set_key_type(&attributes, PSA_KEY_TYPE_HMAC);

    status = psa_import_key(&attributes, finished_key, hash_len, &key);
    if (status != PSA_SUCCESS) {
        ret = PSA_TO_MBEDTLS_ERR(status);
        goto exit;
    }

    status = psa_mac_compute(key, alg, transcript, hash_len,
                             dst, hash_len, dst_len);
    ret = PSA_TO_MBEDTLS_ERR(status);

exit:

    status = psa_destroy_key(key);
    if (ret == 0) {
        ret = PSA_TO_MBEDTLS_ERR(status);
    }

    mbedtls_platform_zeroize(finished_key, sizeof(finished_key));

    return ret;
}

int mbedtls_ssl_tls13_calculate_verify_data(mbedtls_ssl_context *ssl,
                                            unsigned char *dst,
                                            size_t dst_len,
                                            size_t *actual_len,
                                            int from)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;

    unsigned char transcript[MBEDTLS_TLS1_3_MD_MAX_SIZE];
    size_t transcript_len;

    unsigned char *base_key = NULL;
    size_t base_key_len = 0;
    mbedtls_ssl_tls13_handshake_secrets *tls13_hs_secrets =
        &ssl->handshake->tls13_hs_secrets;

    mbedtls_md_type_t const md_type = (mbedtls_md_type_t) ssl->handshake->ciphersuite_info->mac;

    psa_algorithm_t hash_alg = mbedtls_md_psa_alg_from_type(
        (mbedtls_md_type_t) ssl->handshake->ciphersuite_info->mac);
    size_t const hash_len = PSA_HASH_LENGTH(hash_alg);

    MBEDTLS_SSL_DEBUG_MSG(2, ("=> mbedtls_ssl_tls13_calculate_verify_data"));

    if (from == MBEDTLS_SSL_IS_CLIENT) {
        base_key = tls13_hs_secrets->client_handshake_traffic_secret;
        base_key_len = sizeof(tls13_hs_secrets->client_handshake_traffic_secret);
    } else {
        base_key = tls13_hs_secrets->server_handshake_traffic_secret;
        base_key_len = sizeof(tls13_hs_secrets->server_handshake_traffic_secret);
    }

    if (dst_len < hash_len) {
        ret = MBEDTLS_ERR_SSL_BUFFER_TOO_SMALL;
        goto exit;
    }

    ret = mbedtls_ssl_get_handshake_transcript(ssl, md_type,
                                               transcript, sizeof(transcript),
                                               &transcript_len);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_get_handshake_transcript", ret);
        goto exit;
    }
    MBEDTLS_SSL_DEBUG_BUF(4, "handshake hash", transcript, transcript_len);

    ret = ssl_tls13_calc_finished_core(hash_alg, base_key,
                                       transcript, dst, actual_len);
    if (ret != 0) {
        goto exit;
    }

    MBEDTLS_SSL_DEBUG_BUF(3, "verify_data for finished message", dst, hash_len);
    MBEDTLS_SSL_DEBUG_MSG(2, ("<= mbedtls_ssl_tls13_calculate_verify_data"));

exit:
    /* Erase handshake secrets */
    mbedtls_platform_zeroize(base_key, base_key_len);
    mbedtls_platform_zeroize(transcript, sizeof(transcript));
    return ret;
}

int mbedtls_ssl_tls13_create_psk_binder(mbedtls_ssl_context *ssl,
                                        const psa_algorithm_t hash_alg,
                                        unsigned char const *psk, size_t psk_len,
                                        int psk_type,
                                        unsigned char const *transcript,
                                        unsigned char *result)
{
    int ret = 0;
    unsigned char binder_key[PSA_MAC_MAX_SIZE];
    unsigned char early_secret[PSA_MAC_MAX_SIZE];
    size_t const hash_len = PSA_HASH_LENGTH(hash_alg);
    size_t actual_len;

#if !defined(MBEDTLS_DEBUG_C)
    ssl = NULL; /* make sure we don't use it except for debug */
    ((void) ssl);
#endif

    /* We should never call this function with an unknown hash,
     * but add an assertion anyway. */
    if (!PSA_ALG_IS_HASH(hash_alg)) {
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    /*
     *            0
     *            |
     *            v
     *  PSK ->  HKDF-Extract = Early Secret
     *            |
     *            +-----> Derive-Secret(., "ext binder" | "res binder", "")
     *            |                     = binder_key
     *            v
     */

    ret = mbedtls_ssl_tls13_evolve_secret(hash_alg,
                                          NULL,           /* Old secret */
                                          psk, psk_len,   /* Input      */
                                          early_secret);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_evolve_secret", ret);
        goto exit;
    }

    MBEDTLS_SSL_DEBUG_BUF(4, "mbedtls_ssl_tls13_create_psk_binder",
                          early_secret, hash_len);

    if (psk_type == MBEDTLS_SSL_TLS1_3_PSK_RESUMPTION) {
        ret = mbedtls_ssl_tls13_derive_secret(
            hash_alg,
            early_secret, hash_len,
            MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(res_binder),
            NULL, 0, MBEDTLS_SSL_TLS1_3_CONTEXT_UNHASHED,
            binder_key, hash_len);
        MBEDTLS_SSL_DEBUG_MSG(4, ("Derive Early Secret with 'res binder'"));
    } else {
        ret = mbedtls_ssl_tls13_derive_secret(
            hash_alg,
            early_secret, hash_len,
            MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(ext_binder),
            NULL, 0, MBEDTLS_SSL_TLS1_3_CONTEXT_UNHASHED,
            binder_key, hash_len);
        MBEDTLS_SSL_DEBUG_MSG(4, ("Derive Early Secret with 'ext binder'"));
    }

    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_derive_secret", ret);
        goto exit;
    }

    /*
     * The binding_value is computed in the same way as the Finished message
     * but with the BaseKey being the binder_key.
     */

    ret = ssl_tls13_calc_finished_core(hash_alg, binder_key, transcript,
                                       result, &actual_len);
    if (ret != 0) {
        goto exit;
    }

    MBEDTLS_SSL_DEBUG_BUF(3, "psk binder", result, actual_len);

exit:

    mbedtls_platform_zeroize(early_secret, sizeof(early_secret));
    mbedtls_platform_zeroize(binder_key,   sizeof(binder_key));
    return ret;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_get_cipher_key_info(
    const mbedtls_ssl_ciphersuite_t *ciphersuite_info,
    size_t *key_len, size_t *iv_len)
{
    psa_key_type_t key_type;
    psa_algorithm_t alg;
    size_t taglen;
    size_t key_bits;
    psa_status_t status = PSA_ERROR_CORRUPTION_DETECTED;

    if (ciphersuite_info->flags & MBEDTLS_CIPHERSUITE_SHORT_TAG) {
        taglen = 8;
    } else {
        taglen = 16;
    }

    status = mbedtls_ssl_cipher_to_psa((mbedtls_cipher_type_t) ciphersuite_info->cipher, taglen,
                                       &alg, &key_type, &key_bits);
    if (status != PSA_SUCCESS) {
        return PSA_TO_MBEDTLS_ERR(status);
    }

    *key_len = PSA_BITS_TO_BYTES(key_bits);

    /* TLS 1.3 only have AEAD ciphers, IV length is unconditionally 12 bytes */
    *iv_len = 12;

    return 0;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_generate_early_key(mbedtls_ssl_context *ssl,
                                        mbedtls_ssl_key_set *traffic_keys)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_md_type_t md_type;
    psa_algorithm_t hash_alg;
    size_t hash_len;
    unsigned char transcript[MBEDTLS_TLS1_3_MD_MAX_SIZE];
    size_t transcript_len;
    size_t key_len = 0;
    size_t iv_len = 0;
    mbedtls_ssl_tls13_early_secrets tls13_early_secrets;

    mbedtls_ssl_handshake_params *handshake = ssl->handshake;
    const mbedtls_ssl_ciphersuite_t *ciphersuite_info =
        handshake->ciphersuite_info;

    MBEDTLS_SSL_DEBUG_MSG(2, ("=> ssl_tls13_generate_early_key"));

    ret = ssl_tls13_get_cipher_key_info(ciphersuite_info, &key_len, &iv_len);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "ssl_tls13_get_cipher_key_info", ret);
        goto cleanup;
    }

    md_type = (mbedtls_md_type_t) ciphersuite_info->mac;

    hash_alg = mbedtls_md_psa_alg_from_type((mbedtls_md_type_t) ciphersuite_info->mac);
    hash_len = PSA_HASH_LENGTH(hash_alg);

    ret = mbedtls_ssl_get_handshake_transcript(ssl, md_type,
                                               transcript,
                                               sizeof(transcript),
                                               &transcript_len);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1,
                              "mbedtls_ssl_get_handshake_transcript",
                              ret);
        goto cleanup;
    }

    ret = mbedtls_ssl_tls13_derive_early_secrets(
        hash_alg, handshake->tls13_master_secrets.early,
        transcript, transcript_len, &tls13_early_secrets);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(
            1, "mbedtls_ssl_tls13_derive_early_secrets", ret);
        goto cleanup;
    }

    MBEDTLS_SSL_DEBUG_BUF(
        4, "Client early traffic secret",
        tls13_early_secrets.client_early_traffic_secret, hash_len);

    /*
     * Export client handshake traffic secret
     */
    if (ssl->f_export_keys != NULL) {
        ssl->f_export_keys(
            ssl->p_export_keys,
            MBEDTLS_SSL_KEY_EXPORT_TLS1_3_CLIENT_EARLY_SECRET,
            tls13_early_secrets.client_early_traffic_secret,
            hash_len,
            handshake->randbytes,
            handshake->randbytes + MBEDTLS_CLIENT_HELLO_RANDOM_LEN,
            MBEDTLS_SSL_TLS_PRF_NONE /* TODO: FIX! */);
    }

    ret = ssl_tls13_make_traffic_key(
        hash_alg,
        tls13_early_secrets.client_early_traffic_secret,
        hash_len, traffic_keys->client_write_key, key_len,
        traffic_keys->client_write_iv, iv_len);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "ssl_tls13_make_traffic_key", ret);
        goto cleanup;
    }
    traffic_keys->key_len = key_len;
    traffic_keys->iv_len = iv_len;

    MBEDTLS_SSL_DEBUG_BUF(4, "client early write_key",
                          traffic_keys->client_write_key,
                          traffic_keys->key_len);

    MBEDTLS_SSL_DEBUG_BUF(4, "client early write_iv",
                          traffic_keys->client_write_iv,
                          traffic_keys->iv_len);

    MBEDTLS_SSL_DEBUG_MSG(2, ("<= ssl_tls13_generate_early_key"));

cleanup:
    /* Erase early secrets and transcript */
    mbedtls_platform_zeroize(
        &tls13_early_secrets, sizeof(mbedtls_ssl_tls13_early_secrets));
    mbedtls_platform_zeroize(transcript, sizeof(transcript));
    return ret;
}

int mbedtls_ssl_tls13_compute_early_transform(mbedtls_ssl_context *ssl)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_ssl_key_set traffic_keys;
    mbedtls_ssl_transform *transform_earlydata = NULL;
    mbedtls_ssl_handshake_params *handshake = ssl->handshake;

    /* Next evolution in key schedule: Establish early_data secret and
     * key material. */
    ret = ssl_tls13_generate_early_key(ssl, &traffic_keys);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "ssl_tls13_generate_early_key",
                              ret);
        goto cleanup;
    }

    transform_earlydata = mbedtls_calloc(1, sizeof(mbedtls_ssl_transform));
    if (transform_earlydata == NULL) {
        ret = MBEDTLS_ERR_SSL_ALLOC_FAILED;
        goto cleanup;
    }

    ret = mbedtls_ssl_tls13_populate_transform(
        transform_earlydata,
        ssl->conf->endpoint,
        handshake->ciphersuite_info->id,
        &traffic_keys,
        ssl);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_populate_transform", ret);
        goto cleanup;
    }
    handshake->transform_earlydata = transform_earlydata;

cleanup:
    mbedtls_platform_zeroize(&traffic_keys, sizeof(traffic_keys));
    if (ret != 0) {
        mbedtls_free(transform_earlydata);
    }

    return ret;
}

int mbedtls_ssl_tls13_key_schedule_stage_early(mbedtls_ssl_context *ssl)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    psa_algorithm_t hash_alg;
    mbedtls_ssl_handshake_params *handshake = ssl->handshake;
    unsigned char *psk = NULL;
    size_t psk_len = 0;

    if (handshake->ciphersuite_info == NULL) {
        MBEDTLS_SSL_DEBUG_MSG(1, ("cipher suite info not found"));
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    hash_alg = mbedtls_md_psa_alg_from_type((mbedtls_md_type_t) handshake->ciphersuite_info->mac);
#if defined(MBEDTLS_SSL_TLS1_3_KEY_EXCHANGE_MODE_SOME_PSK_ENABLED)
    if (mbedtls_ssl_tls13_key_exchange_mode_with_psk(ssl)) {
        ret = mbedtls_ssl_tls13_export_handshake_psk(ssl, &psk, &psk_len);
        if (ret != 0) {
            MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_export_handshake_psk",
                                  ret);
            return ret;
        }
    }
#endif

    ret = mbedtls_ssl_tls13_evolve_secret(hash_alg, NULL, psk, psk_len,
                                          handshake->tls13_master_secrets.early);
#if defined(MBEDTLS_USE_PSA_CRYPTO) && \
    defined(MBEDTLS_SSL_TLS1_3_KEY_EXCHANGE_MODE_SOME_PSK_ENABLED)
    mbedtls_free((void *) psk);
#endif
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_evolve_secret", ret);
        return ret;
    }

    MBEDTLS_SSL_DEBUG_BUF(4, "mbedtls_ssl_tls13_key_schedule_stage_early",
                          handshake->tls13_master_secrets.early,
                          PSA_HASH_LENGTH(hash_alg));
    return 0;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_generate_handshake_keys(mbedtls_ssl_context *ssl,
                                             mbedtls_ssl_key_set *traffic_keys)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_md_type_t md_type;
    psa_algorithm_t hash_alg;
    size_t hash_len;
    unsigned char transcript[MBEDTLS_TLS1_3_MD_MAX_SIZE];
    size_t transcript_len;
    size_t key_len = 0;
    size_t iv_len = 0;

    mbedtls_ssl_handshake_params *handshake = ssl->handshake;
    const mbedtls_ssl_ciphersuite_t *ciphersuite_info =
        handshake->ciphersuite_info;
    mbedtls_ssl_tls13_handshake_secrets *tls13_hs_secrets =
        &handshake->tls13_hs_secrets;

    MBEDTLS_SSL_DEBUG_MSG(2, ("=> ssl_tls13_generate_handshake_keys"));

    ret = ssl_tls13_get_cipher_key_info(ciphersuite_info, &key_len, &iv_len);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "ssl_tls13_get_cipher_key_info", ret);
        return ret;
    }

    md_type = (mbedtls_md_type_t) ciphersuite_info->mac;

    hash_alg = mbedtls_md_psa_alg_from_type((mbedtls_md_type_t) ciphersuite_info->mac);
    hash_len = PSA_HASH_LENGTH(hash_alg);

    ret = mbedtls_ssl_get_handshake_transcript(ssl, md_type,
                                               transcript,
                                               sizeof(transcript),
                                               &transcript_len);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1,
                              "mbedtls_ssl_get_handshake_transcript",
                              ret);
        return ret;
    }

    ret = mbedtls_ssl_tls13_derive_handshake_secrets(
        hash_alg, handshake->tls13_master_secrets.handshake,
        transcript, transcript_len, tls13_hs_secrets);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_derive_handshake_secrets",
                              ret);
        return ret;
    }

    MBEDTLS_SSL_DEBUG_BUF(4, "Client handshake traffic secret",
                          tls13_hs_secrets->client_handshake_traffic_secret,
                          hash_len);
    MBEDTLS_SSL_DEBUG_BUF(4, "Server handshake traffic secret",
                          tls13_hs_secrets->server_handshake_traffic_secret,
                          hash_len);

    /*
     * Export client handshake traffic secret
     */
    if (ssl->f_export_keys != NULL) {
        ssl->f_export_keys(
            ssl->p_export_keys,
            MBEDTLS_SSL_KEY_EXPORT_TLS1_3_CLIENT_HANDSHAKE_TRAFFIC_SECRET,
            tls13_hs_secrets->client_handshake_traffic_secret,
            hash_len,
            handshake->randbytes,
            handshake->randbytes + MBEDTLS_CLIENT_HELLO_RANDOM_LEN,
            MBEDTLS_SSL_TLS_PRF_NONE /* TODO: FIX! */);

        ssl->f_export_keys(
            ssl->p_export_keys,
            MBEDTLS_SSL_KEY_EXPORT_TLS1_3_SERVER_HANDSHAKE_TRAFFIC_SECRET,
            tls13_hs_secrets->server_handshake_traffic_secret,
            hash_len,
            handshake->randbytes,
            handshake->randbytes + MBEDTLS_CLIENT_HELLO_RANDOM_LEN,
            MBEDTLS_SSL_TLS_PRF_NONE /* TODO: FIX! */);
    }

    ret = mbedtls_ssl_tls13_make_traffic_keys(
        hash_alg,
        tls13_hs_secrets->client_handshake_traffic_secret,
        tls13_hs_secrets->server_handshake_traffic_secret,
        hash_len, key_len, iv_len, traffic_keys);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_make_traffic_keys", ret);
        goto exit;
    }

    MBEDTLS_SSL_DEBUG_BUF(4, "client_handshake write_key",
                          traffic_keys->client_write_key,
                          traffic_keys->key_len);

    MBEDTLS_SSL_DEBUG_BUF(4, "server_handshake write_key",
                          traffic_keys->server_write_key,
                          traffic_keys->key_len);

    MBEDTLS_SSL_DEBUG_BUF(4, "client_handshake write_iv",
                          traffic_keys->client_write_iv,
                          traffic_keys->iv_len);

    MBEDTLS_SSL_DEBUG_BUF(4, "server_handshake write_iv",
                          traffic_keys->server_write_iv,
                          traffic_keys->iv_len);

    MBEDTLS_SSL_DEBUG_MSG(2, ("<= ssl_tls13_generate_handshake_keys"));

exit:

    return ret;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_key_schedule_stage_handshake(mbedtls_ssl_context *ssl)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_ssl_handshake_params *handshake = ssl->handshake;
    psa_algorithm_t const hash_alg = mbedtls_md_psa_alg_from_type(
        (mbedtls_md_type_t) handshake->ciphersuite_info->mac);
    unsigned char *shared_secret = NULL;
    size_t shared_secret_len = 0;

#if defined(MBEDTLS_SSL_TLS1_3_KEY_EXCHANGE_MODE_SOME_EPHEMERAL_ENABLED)
    /*
     * Compute ECDHE secret used to compute the handshake secret from which
     * client_handshake_traffic_secret and server_handshake_traffic_secret
     * are derived in the handshake secret derivation stage.
     */
    if (mbedtls_ssl_tls13_key_exchange_mode_with_ephemeral(ssl)) {
        if (mbedtls_ssl_tls13_named_group_is_ecdhe(handshake->offered_group_id) ||
            mbedtls_ssl_tls13_named_group_is_ffdh(handshake->offered_group_id)) {
#if defined(PSA_WANT_ALG_ECDH) || defined(PSA_WANT_ALG_FFDH)
            psa_algorithm_t alg =
                mbedtls_ssl_tls13_named_group_is_ecdhe(handshake->offered_group_id) ?
                PSA_ALG_ECDH : PSA_ALG_FFDH;

            /* Compute ECDH shared secret. */
            psa_status_t status = PSA_ERROR_GENERIC_ERROR;
            psa_key_attributes_t key_attributes = PSA_KEY_ATTRIBUTES_INIT;

            status = psa_get_key_attributes(handshake->xxdh_psa_privkey,
                                            &key_attributes);
            if (status != PSA_SUCCESS) {
                ret = PSA_TO_MBEDTLS_ERR(status);
            }

            shared_secret_len = PSA_BITS_TO_BYTES(
                psa_get_key_bits(&key_attributes));
            shared_secret = mbedtls_calloc(1, shared_secret_len);
            if (shared_secret == NULL) {
                return MBEDTLS_ERR_SSL_ALLOC_FAILED;
            }

            status = psa_raw_key_agreement(
                alg, handshake->xxdh_psa_privkey,
                handshake->xxdh_psa_peerkey, handshake->xxdh_psa_peerkey_len,
                shared_secret, shared_secret_len, &shared_secret_len);
            if (status != PSA_SUCCESS) {
                ret = PSA_TO_MBEDTLS_ERR(status);
                MBEDTLS_SSL_DEBUG_RET(1, "psa_raw_key_agreement", ret);
                goto cleanup;
            }

            status = psa_destroy_key(handshake->xxdh_psa_privkey);
            if (status != PSA_SUCCESS) {
                ret = PSA_TO_MBEDTLS_ERR(status);
                MBEDTLS_SSL_DEBUG_RET(1, "psa_destroy_key", ret);
                goto cleanup;
            }

            handshake->xxdh_psa_privkey = MBEDTLS_SVC_KEY_ID_INIT;
#endif /* PSA_WANT_ALG_ECDH || PSA_WANT_ALG_FFDH */
        } else {
            MBEDTLS_SSL_DEBUG_MSG(1, ("Group not supported."));
            return MBEDTLS_ERR_SSL_FEATURE_UNAVAILABLE;
        }
    }
#endif /* MBEDTLS_SSL_TLS1_3_KEY_EXCHANGE_MODE_SOME_EPHEMERAL_ENABLED */

    /*
     * Compute the Handshake Secret
     */
    ret = mbedtls_ssl_tls13_evolve_secret(
        hash_alg, handshake->tls13_master_secrets.early,
        shared_secret, shared_secret_len,
        handshake->tls13_master_secrets.handshake);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_evolve_secret", ret);
        goto cleanup;
    }

    MBEDTLS_SSL_DEBUG_BUF(4, "Handshake secret",
                          handshake->tls13_master_secrets.handshake,
                          PSA_HASH_LENGTH(hash_alg));

cleanup:
    if (shared_secret != NULL) {
        mbedtls_zeroize_and_free(shared_secret, shared_secret_len);
    }

    return ret;
}

MBEDTLS_CHECK_RETURN_CRITICAL
static int ssl_tls13_generate_application_keys(
    mbedtls_ssl_context *ssl,
    mbedtls_ssl_key_set *traffic_keys)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_ssl_handshake_params *handshake = ssl->handshake;

    /* Address at which to store the application secrets */
    mbedtls_ssl_tls13_application_secrets * const app_secrets =
        &ssl->session_negotiate->app_secrets;

    /* Holding the transcript up to and including the ServerFinished */
    unsigned char transcript[MBEDTLS_TLS1_3_MD_MAX_SIZE];
    size_t transcript_len;

    /* Variables relating to the hash for the chosen ciphersuite. */
    mbedtls_md_type_t md_type;

    psa_algorithm_t hash_alg;
    size_t hash_len;

    /* Variables relating to the cipher for the chosen ciphersuite. */
    size_t key_len = 0, iv_len = 0;

    MBEDTLS_SSL_DEBUG_MSG(2, ("=> derive application traffic keys"));

    /* Extract basic information about hash and ciphersuite */

    ret = ssl_tls13_get_cipher_key_info(handshake->ciphersuite_info,
                                        &key_len, &iv_len);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "ssl_tls13_get_cipher_key_info", ret);
        goto cleanup;
    }

    md_type = (mbedtls_md_type_t) handshake->ciphersuite_info->mac;

    hash_alg = mbedtls_md_psa_alg_from_type((mbedtls_md_type_t) handshake->ciphersuite_info->mac);
    hash_len = PSA_HASH_LENGTH(hash_alg);

    /* Compute current handshake transcript. It's the caller's responsibility
     * to call this at the right time, that is, after the ServerFinished. */

    ret = mbedtls_ssl_get_handshake_transcript(ssl, md_type,
                                               transcript, sizeof(transcript),
                                               &transcript_len);
    if (ret != 0) {
        goto cleanup;
    }

    /* Compute application secrets from master secret and transcript hash. */

    ret = mbedtls_ssl_tls13_derive_application_secrets(
        hash_alg, handshake->tls13_master_secrets.app,
        transcript, transcript_len, app_secrets);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(
            1, "mbedtls_ssl_tls13_derive_application_secrets", ret);
        goto cleanup;
    }

    /* Derive first epoch of IV + Key for application traffic. */

    ret = mbedtls_ssl_tls13_make_traffic_keys(
        hash_alg,
        app_secrets->client_application_traffic_secret_N,
        app_secrets->server_application_traffic_secret_N,
        hash_len, key_len, iv_len, traffic_keys);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_make_traffic_keys", ret);
        goto cleanup;
    }

    MBEDTLS_SSL_DEBUG_BUF(4, "Client application traffic secret",
                          app_secrets->client_application_traffic_secret_N,
                          hash_len);

    MBEDTLS_SSL_DEBUG_BUF(4, "Server application traffic secret",
                          app_secrets->server_application_traffic_secret_N,
                          hash_len);

    /*
     * Export client/server application traffic secret 0
     */
    if (ssl->f_export_keys != NULL) {
        ssl->f_export_keys(
            ssl->p_export_keys,
            MBEDTLS_SSL_KEY_EXPORT_TLS1_3_CLIENT_APPLICATION_TRAFFIC_SECRET,
            app_secrets->client_application_traffic_secret_N, hash_len,
            handshake->randbytes,
            handshake->randbytes + MBEDTLS_CLIENT_HELLO_RANDOM_LEN,
            MBEDTLS_SSL_TLS_PRF_NONE /* TODO: this should be replaced by
                                        a new constant for TLS 1.3! */);

        ssl->f_export_keys(
            ssl->p_export_keys,
            MBEDTLS_SSL_KEY_EXPORT_TLS1_3_SERVER_APPLICATION_TRAFFIC_SECRET,
            app_secrets->server_application_traffic_secret_N, hash_len,
            handshake->randbytes,
            handshake->randbytes + MBEDTLS_CLIENT_HELLO_RANDOM_LEN,
            MBEDTLS_SSL_TLS_PRF_NONE /* TODO: this should be replaced by
                                        a new constant for TLS 1.3! */);
    }

    MBEDTLS_SSL_DEBUG_BUF(4, "client application_write_key:",
                          traffic_keys->client_write_key, key_len);
    MBEDTLS_SSL_DEBUG_BUF(4, "server application write key",
                          traffic_keys->server_write_key, key_len);
    MBEDTLS_SSL_DEBUG_BUF(4, "client application write IV",
                          traffic_keys->client_write_iv, iv_len);
    MBEDTLS_SSL_DEBUG_BUF(4, "server application write IV",
                          traffic_keys->server_write_iv, iv_len);

    MBEDTLS_SSL_DEBUG_MSG(2, ("<= derive application traffic keys"));

cleanup:
    /* randbytes is not used again */
    mbedtls_platform_zeroize(ssl->handshake->randbytes,
                             sizeof(ssl->handshake->randbytes));

    mbedtls_platform_zeroize(transcript, sizeof(transcript));
    return ret;
}

int mbedtls_ssl_tls13_compute_handshake_transform(mbedtls_ssl_context *ssl)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_ssl_key_set traffic_keys;
    mbedtls_ssl_transform *transform_handshake = NULL;
    mbedtls_ssl_handshake_params *handshake = ssl->handshake;

    /* Compute handshake secret */
    ret = ssl_tls13_key_schedule_stage_handshake(ssl);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_derive_master_secret", ret);
        goto cleanup;
    }

    /* Next evolution in key schedule: Establish handshake secret and
     * key material. */
    ret = ssl_tls13_generate_handshake_keys(ssl, &traffic_keys);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "ssl_tls13_generate_handshake_keys",
                              ret);
        goto cleanup;
    }

    transform_handshake = mbedtls_calloc(1, sizeof(mbedtls_ssl_transform));
    if (transform_handshake == NULL) {
        ret = MBEDTLS_ERR_SSL_ALLOC_FAILED;
        goto cleanup;
    }

    ret = mbedtls_ssl_tls13_populate_transform(
        transform_handshake,
        ssl->conf->endpoint,
        handshake->ciphersuite_info->id,
        &traffic_keys,
        ssl);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_populate_transform", ret);
        goto cleanup;
    }
    handshake->transform_handshake = transform_handshake;

cleanup:
    mbedtls_platform_zeroize(&traffic_keys, sizeof(traffic_keys));
    if (ret != 0) {
        mbedtls_free(transform_handshake);
    }

    return ret;
}

int mbedtls_ssl_tls13_compute_resumption_master_secret(mbedtls_ssl_context *ssl)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_md_type_t md_type;
    mbedtls_ssl_handshake_params *handshake = ssl->handshake;
    unsigned char transcript[MBEDTLS_TLS1_3_MD_MAX_SIZE];
    size_t transcript_len;

    MBEDTLS_SSL_DEBUG_MSG(
        2, ("=> mbedtls_ssl_tls13_compute_resumption_master_secret"));

    md_type = (mbedtls_md_type_t) handshake->ciphersuite_info->mac;

    ret = mbedtls_ssl_get_handshake_transcript(ssl, md_type,
                                               transcript, sizeof(transcript),
                                               &transcript_len);
    if (ret != 0) {
        return ret;
    }

    ret = mbedtls_ssl_tls13_derive_resumption_master_secret(
        mbedtls_md_psa_alg_from_type(md_type),
        handshake->tls13_master_secrets.app,
        transcript, transcript_len,
        &ssl->session_negotiate->app_secrets);
    if (ret != 0) {
        return ret;
    }

    /* Erase master secrets */
    mbedtls_platform_zeroize(&handshake->tls13_master_secrets,
                             sizeof(handshake->tls13_master_secrets));

    MBEDTLS_SSL_DEBUG_BUF(
        4, "Resumption master secret",
        ssl->session_negotiate->app_secrets.resumption_master_secret,
        PSA_HASH_LENGTH(mbedtls_md_psa_alg_from_type(md_type)));

    MBEDTLS_SSL_DEBUG_MSG(
        2, ("<= mbedtls_ssl_tls13_compute_resumption_master_secret"));
    return 0;
}

int mbedtls_ssl_tls13_compute_application_transform(mbedtls_ssl_context *ssl)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_ssl_key_set traffic_keys;
    mbedtls_ssl_transform *transform_application = NULL;

    ret = ssl_tls13_key_schedule_stage_application(ssl);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1,
                              "ssl_tls13_key_schedule_stage_application", ret);
        goto cleanup;
    }

    ret = ssl_tls13_generate_application_keys(ssl, &traffic_keys);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1,
                              "ssl_tls13_generate_application_keys", ret);
        goto cleanup;
    }

    transform_application =
        mbedtls_calloc(1, sizeof(mbedtls_ssl_transform));
    if (transform_application == NULL) {
        ret = MBEDTLS_ERR_SSL_ALLOC_FAILED;
        goto cleanup;
    }

    ret = mbedtls_ssl_tls13_populate_transform(
        transform_application,
        ssl->conf->endpoint,
        ssl->handshake->ciphersuite_info->id,
        &traffic_keys,
        ssl);
    if (ret != 0) {
        MBEDTLS_SSL_DEBUG_RET(1, "mbedtls_ssl_tls13_populate_transform", ret);
        goto cleanup;
    }

    ssl->transform_application = transform_application;

cleanup:

    mbedtls_platform_zeroize(&traffic_keys, sizeof(traffic_keys));
    if (ret != 0) {
        mbedtls_free(transform_application);
    }
    return ret;
}

int mbedtls_ssl_tls13_export_handshake_psk(mbedtls_ssl_context *ssl,
                                           unsigned char **psk,
                                           size_t *psk_len)
{
#if defined(MBEDTLS_USE_PSA_CRYPTO)
    psa_key_attributes_t key_attributes = PSA_KEY_ATTRIBUTES_INIT;
    psa_status_t status = PSA_ERROR_CORRUPTION_DETECTED;

    *psk_len = 0;
    *psk = NULL;

    if (mbedtls_svc_key_id_is_null(ssl->handshake->psk_opaque)) {
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }

    status = psa_get_key_attributes(ssl->handshake->psk_opaque, &key_attributes);
    if (status != PSA_SUCCESS) {
        return PSA_TO_MBEDTLS_ERR(status);
    }

    *psk_len = PSA_BITS_TO_BYTES(psa_get_key_bits(&key_attributes));
    *psk = mbedtls_calloc(1, *psk_len);
    if (*psk == NULL) {
        return MBEDTLS_ERR_SSL_ALLOC_FAILED;
    }

    status = psa_export_key(ssl->handshake->psk_opaque,
                            (uint8_t *) *psk, *psk_len, psk_len);
    if (status != PSA_SUCCESS) {
        mbedtls_free((void *) *psk);
        *psk = NULL;
        return PSA_TO_MBEDTLS_ERR(status);
    }
    return 0;
#else
    *psk = ssl->handshake->psk;
    *psk_len = ssl->handshake->psk_len;
    if (*psk == NULL) {
        return MBEDTLS_ERR_SSL_INTERNAL_ERROR;
    }
    return 0;
#endif /* !MBEDTLS_USE_PSA_CRYPTO */
}

int mbedtls_ssl_tls13_exporter(const psa_algorithm_t hash_alg,
                               const unsigned char *secret, const size_t secret_len,
                               const unsigned char *label, const size_t label_len,
                               const unsigned char *context_value, const size_t context_len,
                               unsigned char *out, const size_t out_len)
{
    size_t hash_len = PSA_HASH_LENGTH(hash_alg);
    unsigned char hkdf_secret[MBEDTLS_TLS1_3_MD_MAX_SIZE];
    int ret = 0;

    ret = mbedtls_ssl_tls13_derive_secret(hash_alg, secret, secret_len, label, label_len, NULL, 0,
                                          MBEDTLS_SSL_TLS1_3_CONTEXT_UNHASHED, hkdf_secret,
                                          hash_len);
    if (ret != 0) {
        goto exit;
    }
    ret = mbedtls_ssl_tls13_derive_secret(hash_alg,
                                          hkdf_secret,
                                          hash_len,
                                          MBEDTLS_SSL_TLS1_3_LBL_WITH_LEN(exporter),
                                          context_value,
                                          context_len,
                                          MBEDTLS_SSL_TLS1_3_CONTEXT_UNHASHED,
                                          out,
                                          out_len);

exit:
    mbedtls_platform_zeroize(hkdf_secret, sizeof(hkdf_secret));
    return ret;
}

QVariant IO::Drivers::OpcUa::unwrapValue(const QVariant& value)
{
  if (value.canConvert<QOpcUaLocalizedText>())
    return value.value<QOpcUaLocalizedText>().text();

  return value;
}

nodiscard]] static IO::Drivers::OpcUa* opcUaDriver()
{
  static auto& connectionManager = IO::ConnectionManager::instance();
  return connectionManager.opcUa();
}

nodiscard]] static API::CommandResponse missingParam(const QString& id, const char* name)
{
  return API::CommandResponse::makeError(
    id,
    API::ErrorCode::MissingParam,
    QStringLiteral("Missing required parameter: %1").arg(QLatin1String(name)));
}

id API::Handlers::OpcUaHandler::registerCommands()
{
  static auto& registry = CommandRegistry::instance();
  registerConfigCommands(registry);
  registerDiscoveryCommands(registry);
  registerTagCommands(registry);
  registerQueryCommands(registry);
}

id API::Handlers::OpcUaHandler::registerConfigCommands(CommandRegistry& registry)
{
  registry.registerCommand(
    QStringLiteral("io.opcua.setEndpointUrl"),
    QStringLiteral("Set the OPC UA endpoint URL (params: url, e.g. opc.tcp://host:4840/path)"),
    API::makeSchema({
      {QStringLiteral("url"),
       QStringLiteral("string"),
       QStringLiteral("opc.tcp:// endpoint URL")}
  }),
    &setEndpointUrl);
  registry.registerCommand(
    QStringLiteral("io.opcua.setEndpointIndex"),
    QStringLiteral("Select a discovered endpoint by row (params: index; -1 = typed URL)"),
    API::makeSchema({
      {QStringLiteral("index"),
       QStringLiteral("integer"),
       QStringLiteral("Row in io.opcua.listEndpoints, or -1 for the typed URL")}
  }),
    &setEndpointIndex);
  registry.registerCommand(
    QStringLiteral("io.opcua.setAuthMode"),
    QStringLiteral("Set authentication (params: mode - 0=anonymous, 1=username/password)"),
    API::makeSchema({
      {QStringLiteral("mode"),
       QStringLiteral("integer"),
       QStringLiteral("0 = anonymous, 1 = username/password")}
  }),
    &setAuthMode);
  registry.registerCommand(QStringLiteral("io.opcua.setUsername"),
                           QStringLiteral("Set the username (params: username)"),
                           API::makeSchema({
                             {QStringLiteral("username"),
                              QStringLiteral("string"),
                              QStringLiteral("Username for mode 1")}
  }),
                           &setUsername);
  registry.registerCommand(
    QStringLiteral("io.opcua.setPassword"),
    QStringLiteral("Set the password (params: password; stored in the encrypted vault)"),
    API::makeSchema({
      {QStringLiteral("password"),
       QStringLiteral("string"),
       QStringLiteral("Password for mode 1")}
  }),
    &setPassword);
  registry.registerCommand(
    QStringLiteral("io.opcua.setPublishingInterval"),
    QStringLiteral("Set the publishing interval in milliseconds (params: intervalMs)"),
    API::makeSchema({
      {QStringLiteral("intervalMs"),
       QStringLiteral("integer"),
       QStringLiteral("Publishing interval in milliseconds (10-60000)")}
  }),
    &setPublishingInterval);
}

id API::Handlers::OpcUaHandler::registerDiscoveryCommands(CommandRegistry& registry)
{
  const auto empty = API::emptySchema();

  registry.registerCommand(
    QStringLiteral("io.opcua.discoverEndpoints"),
    QStringLiteral("Request the server's endpoints; poll io.opcua.listEndpoints for the result"),
    empty,
    &discoverEndpoints);
  registry.registerCommand(
    QStringLiteral("io.opcua.listEndpoints"),
    QStringLiteral("Get discovered endpoints with their policy, mode and selectability"),
    empty,
    &listEndpoints);
  registry.registerCommand(
    QStringLiteral("io.opcua.startBrowse"),
    QStringLiteral("Open a browse session; poll io.opcua.browse once browsing is true"),
    empty,
    &startBrowse);
  registry.registerCommand(
    QStringLiteral("io.opcua.browse"),
    QStringLiteral("Fetch one level of the address space (params: nodeId; empty = Objects)"),
    API::makeSchema({
      {QStringLiteral("nodeId"),
       QStringLiteral("string"),
       QStringLiteral("Folder node id (empty for the Objects folder)")}
  }),
    &browse);
  registry.registerCommand(
    QStringLiteral("io.opcua.stopBrowse"),
    QStringLiteral("Close the browse session and commit the picker selection to the tag list"),
    empty,
    &stopBrowse);
}

id API::Handlers::OpcUaHandler::registerTagCommands(CommandRegistry& registry)
{
  const auto empty = API::emptySchema();

  registry.registerCommand(
    QStringLiteral("io.opcua.setTags"),
    QStringLiteral("Replace the tag list (params: tags - array of {id, name, path, unit, t, n})"),
    API::makeSchema({
      {QStringLiteral("tags"),
       QStringLiteral("array"),
       QStringLiteral(
         "Tag objects: id (node id), name, path, unit, t (type code), n (array len)")}
  }),
    &setTags);
  registry.registerCommand(
    QStringLiteral("io.opcua.addTag"),
    QStringLiteral("Append one tag (params: id, name, t; optional path, unit, n)"),
    API::makeSchema({
      {  QStringLiteral("id"),QStringLiteral("string"),QStringLiteral("Variable node id")                                                        },
      {QStringLiteral("name"), QStringLiteral("string"),                          QStringLiteral("Display name")},
      {   QStringLiteral("t"),
       QStringLiteral("string"),
       QStringLiteral("Type code: bool,i8,u8,i16,u16,i32,u32,i64,u64,f32,f64,str")                              },
  }),
    &addTag);
  registry.registerCommand(QStringLiteral("io.opcua.removeTag"),
                           QStringLiteral("Remove a tag by position (params: index)"),
                           API::makeSchema({
                             {QStringLiteral("index"),
                              QStringLiteral("integer"),
                              QStringLiteral("Zero-based tag position")}
  }),
                           &removeTag);
  registry.registerCommand(
    QStringLiteral("io.opcua.clearTags"), QStringLiteral("Remove every tag"), empty, &clearTags);
  registry.registerCommand(
    QStringLiteral("io.opcua.generateProject"),
    QStringLiteral("Generate a project from the tag list and load it into the editor"),
    empty,
    &generateProject);
}

id API::Handlers::OpcUaHandler::registerQueryCommands(CommandRegistry& registry)
{
  const auto empty = API::emptySchema();

  registry.registerCommand(QStringLiteral("io.opcua.getConfig"),
                           QStringLiteral("Get current OPC UA configuration"),
                           empty,
                           &getConfiguration);
  registry.registerCommand(QStringLiteral("io.opcua.listTags"),
                           QStringLiteral("Get the configured tag list and wire schema"),
                           empty,
                           &listTags);
  registry.registerCommand(QStringLiteral("io.opcua.getStatus"),
                           QStringLiteral("Get session status and pulled diagnostics counters"),
                           empty,
                           &getStatus);
}

I::CommandResponse API::Handlers::OpcUaHandler::setEndpointUrl(const QString& id,
                                                                 const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("url")))
    return missingParam(id, "url");

  const QString url = params.value(QStringLiteral("url")).toString();
  const QUrl parsed(url);
  if (!url.startsWith(QLatin1String("opc.tcp://")) || !parsed.isValid() || parsed.host().isEmpty())
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("url must be a valid opc.tcp://host[:port][/path] endpoint"));

  opcUaDriver()->setEndpointUrl(url);
  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("url"), url}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::setEndpointIndex(const QString& id,
                                                                   const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("index")))
    return missingParam(id, "index");

  const int index = params.value(QStringLiteral("index")).toInt();
  auto* driver    = opcUaDriver();
  driver->setEndpointIndex(index);
  if (driver->endpointIndex() != index)
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Endpoint row is unknown or not selectable"));

  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("index"), index}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::setAuthMode(const QString& id,
                                                              const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("mode")))
    return missingParam(id, "mode");

  const int mode = params.value(QStringLiteral("mode")).toInt();
  if (mode < 0 || mode > 1)
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("mode must be 0 or 1"));

  opcUaDriver()->setAuthMode(mode);
  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("mode"), mode}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::setUsername(const QString& id,
                                                              const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("username")))
    return missingParam(id, "username");

  const QString username = params.value(QStringLiteral("username")).toString();
  opcUaDriver()->setUsername(username);
  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("username"), username}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::setPassword(const QString& id,
                                                              const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("password")))
    return missingParam(id, "password");

  opcUaDriver()->setPassword(params.value(QStringLiteral("password")).toString());
  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("stored"), true}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::setPublishingInterval(const QString& id,
                                                                        const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("intervalMs")))
    return missingParam(id, "intervalMs");

  const int interval = params.value(QStringLiteral("intervalMs")).toInt();
  if (interval < 10 || interval > 60000)
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("intervalMs must be between 10 and 60000"));

  auto* driver = opcUaDriver();
  driver->setPublishingInterval(interval);
  return CommandResponse::makeSuccess(
    id,
    QJsonObject{
      {QStringLiteral("intervalMs"), driver->publishingInterval()}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::discoverEndpoints(const QString& id,
                                                                    const QJsonObject& params)
{
  Q_UNUSED(params)
  auto* driver = opcUaDriver();
  driver->discoverEndpoints();
  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("discovering"), driver->discovering()}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::listEndpoints(const QString& id,
                                                                const QJsonObject& params)
{
  Q_UNUSED(params)
  auto* driver         = opcUaDriver();
  const auto endpoints = driver->endpointsJson();

  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {  QStringLiteral("discovering"),   driver->discovering()},
                                        {QStringLiteral("selectedIndex"), driver->endpointIndex()},
                                        {    QStringLiteral("endpoints"),               endpoints},
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::startBrowse(const QString& id,
                                                              const QJsonObject& params)
{
  Q_UNUSED(params)
  auto* driver = opcUaDriver();
  driver->startBrowse();
  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("browsing"), driver->browsing()}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::browse(const QString& id,
                                                         const QJsonObject& params)
{
  auto* driver = opcUaDriver();
  if (!driver->browsing())
    return CommandResponse::makeError(
      id,
      ErrorCode::OperationFailed,
      QStringLiteral("No browse session; call io.opcua.startBrowse"));

  const QString nodeId = params.value(QStringLiteral("nodeId")).toString();
  auto* model          = driver->tagModel();
  const bool known     = model->fetchNode(nodeId);
  if (!known && !nodeId.isEmpty())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Unknown node id; browse its parent first"));

  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {  QStringLiteral("nodeId"),                      nodeId},
                                        {   QStringLiteral("known"),                       known},
                                        {QStringLiteral("children"), model->childrenJson(nodeId)},
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::stopBrowse(const QString& id,
                                                             const QJsonObject& params)
{
  Q_UNUSED(params)
  auto* driver = opcUaDriver();
  driver->stopBrowse();
  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("tagCount"), driver->tagCount()}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::setTags(const QString& id,
                                                          const QJsonObject& params)
{
  if (!params.value(QStringLiteral("tags")).isArray())
    return missingParam(id, "tags");

  auto* driver       = opcUaDriver();
  const auto request = params.value(QStringLiteral("tags")).toArray();
  driver->setTags(request);

  return CommandResponse::makeSuccess(
    id,
    QJsonObject{
      {QStringLiteral("tagCount"),                  driver->tagCount()},
      { QStringLiteral("dropped"), request.size() - driver->tagCount()},
      {QStringLiteral("deferred"),              driver->tagsDeferred()}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::addTag(const QString& id,
                                                         const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("id")))
    return missingParam(id, "id");

  if (!params.contains(QStringLiteral("t")))
    return missingParam(id, "t");

  const auto type =
    IO::Drivers::OpcUaWire::typeFromCode(params.value(QStringLiteral("t")).toString());
  if (type == IO::Drivers::OpcUaWire::Type::Invalid)
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Unknown type code"));

  IO::Drivers::OpcUaTag tag;
  tag.nodeId = params.value(QStringLiteral("id")).toString();
  tag.name   = params.value(QStringLiteral("name")).toString(tag.nodeId);
  tag.path   = params.value(QStringLiteral("path")).toString();
  tag.unit   = params.value(QStringLiteral("unit")).toString();
  tag.type   = type;
  tag.arrayLen =
    qBound(1, params.value(QStringLiteral("n")).toInt(1), IO::Drivers::OpcUaWire::kMaxTags);

  auto* driver     = opcUaDriver();
  const int before = driver->tagCount();
  driver->addTag(tag);
  if (driver->tagCount() == before)
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Tag already present or over the tag budget"));

  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("tagCount"), driver->tagCount()}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::removeTag(const QString& id,
                                                            const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("index")))
    return missingParam(id, "index");

  auto* driver    = opcUaDriver();
  const int index = params.value(QStringLiteral("index")).toInt();
  if (index < 0 || index >= driver->tagCount())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("index out of range"));

  driver->removeTag(index);
  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("tagCount"), driver->tagCount()}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::clearTags(const QString& id,
                                                            const QJsonObject& params)
{
  Q_UNUSED(params)
  opcUaDriver()->clearTags();
  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {QStringLiteral("tagCount"), 0}
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::generateProject(const QString& id,
                                                                  const QJsonObject& params)
{
  Q_UNUSED(params)
  auto* driver = opcUaDriver();
  if (driver->tagCount() == 0)
    return CommandResponse::makeError(
      id, ErrorCode::OperationFailed, QStringLiteral("No tags configured"));

  if (!driver->loadGeneratedProject())
    return CommandResponse::makeError(
      id, ErrorCode::ExecutionError, QStringLiteral("The generated project could not be loaded"));

  const auto project = driver->buildProject();
  return CommandResponse::makeSuccess(
    id,
    QJsonObject{
      {  QStringLiteral("groups"), project.value(Keys::Groups).toArray().size()},
      {QStringLiteral("datasets"),                  driver->wireSchema().size()},
      { QStringLiteral("project"),                                      project},
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::getConfiguration(const QString& id,
                                                                   const QJsonObject& params)
{
  Q_UNUSED(params)
  auto* driver = opcUaDriver();
  return CommandResponse::makeSuccess(
    id,
    QJsonObject{
      {       QStringLiteral("endpointUrl"),         driver->endpointUrl()},
      {     QStringLiteral("endpointIndex"),       driver->endpointIndex()},
      {          QStringLiteral("authMode"),            driver->authMode()},
      {          QStringLiteral("username"),            driver->username()},
      {       QStringLiteral("hasPassword"), !driver->password().isEmpty()},
      {QStringLiteral("publishingInterval"),  driver->publishingInterval()},
      {          QStringLiteral("tagCount"),            driver->tagCount()},
      {   QStringLiteral("configurationOk"),     driver->configurationOk()},
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::listTags(const QString& id,
                                                           const QJsonObject& params)
{
  Q_UNUSED(params)
  auto* driver = opcUaDriver();
  return CommandResponse::makeSuccess(id,
                                      QJsonObject{
                                        {  QStringLiteral("tags"),   driver->tagsJson()},
                                        {QStringLiteral("schema"), driver->wireSchema()},
  });
}

I::CommandResponse API::Handlers::OpcUaHandler::getStatus(const QString& id,
                                                            const QJsonObject& params)
{
  Q_UNUSED(params)
  auto status = opcUaDriver()->statusJson();
  status.insert(QStringLiteral("browsing"), opcUaDriver()->browsing());
  return CommandResponse::makeSuccess(id, status);
}

explicit OpcUaParser(const QList<IO::Drivers::OpcUaWire::Type>& schema)
    : NativeLatchParser(static_cast<int>(schema.size())), m_schema(schema)
  {
    SS_ASSERT_LOG(!m_schema.isEmpty());
    SS_ASSERT_LOG(m_schema.size() <= IO::Drivers::OpcUaWire::kMaxTags);
  }

[[nodiscard]] QList<QStringList> parseBinary(const QByteArray& frame) override
  {
    using namespace IO::Drivers::OpcUaWire;
    SS_ASSERT(!m_schema.isEmpty(), return latchedFrame());

    const QByteArrayView view(frame.constData(), qMin<qsizetype>(frame.size(), kMaxBytesPerFrame));
    if (!checkHeader(view))
      return latchedFrame();

    qsizetype pos = kHeaderBytes;
    Entry entry;
    for (int n = 0; n < kMaxTags && pos < view.size(); ++n) {
      if (!readEntry(view, pos, entry))
        break;

      SS_ASSERT_LOG(entry.index >= 0);
      if (entry.index >= 0 && entry.index < m_schema.size() && m_schema[entry.index] == entry.type)
        storeAt(entry.index, entry.text);
    }

    return latchedFrame();
  }

[[nodiscard]] QString description() const override
  {
    return trBinary("Decodes the OPC UA driver's tag update frames into one latched channel "
                    "per subscribed tag. Generated with the OPC UA project; use with the "
                    "Binary decoder.");
  }

[[nodiscard]] QList<NativeParamSpec> params() const override
  {
    auto schema = DataModel::nativeParam(
      "schema",
      NativeParamType::Json,
      QT_TRANSLATE_NOOP("NativeTemplates", "Tag schema"),
      QT_TRANSLATE_NOOP("NativeTemplates",
                        "Ordered tag list written by the OPC UA project generator: one "
                        "{\"i\": index, \"t\": type} entry per channel."),
      QJsonArray());
    return {schema};
  }

[[nodiscard]] std::unique_ptr<INativeParser> makeParser(const QJsonObject& params,
                                                          QString& error) const override
  {
    using namespace IO::Drivers::OpcUaWire;

    const auto items = DataModel::nativeParamArray(params, QStringLiteral("schema"));
    if (items.isEmpty() || items.size() > kMaxTags) {
      error = trBinary("The tag schema must list between 1 and %1 tags.").arg(kMaxTags);
      return nullptr;
    }

    QList<Type> schema(items.size(), Type::Invalid);
    for (const auto& item : items) {
      const auto obj  = item.toObject();
      const int index = obj.value(QStringLiteral("i")).toInt(-1);
      const auto type = typeFromCode(obj.value(QStringLiteral("t")).toString());
      if (index < 0 || index >= schema.size() || type == Type::Invalid
          || schema[index] != Type::Invalid) {
        error = trBinary("The tag schema has an invalid, duplicate or missing index.");
        return nullptr;
      }

      schema[index] = type;
    }

    return std::make_unique<OpcUaParser>(schema);
  }

id IO::Drivers::OpcUa::setupExternalConnections()
{
  connect(&Misc::Translator::instance(),
          &Misc::Translator::languageChanged,
          this,
          &IO::Drivers::OpcUa::languageChanged);
}

::Drivers::OpcUa::~OpcUa()
{
  doClose();
  teardownClient(m_browseClient);
  teardownClient(m_discoveryClient);
  delete m_tagModel;
  m_tagModel = nullptr;

  const auto nodes = findChildren<QOpcUaNode*>(QString(), Qt::FindDirectChildrenOnly);
  for (auto* node : nodes)
    delete node;

  const auto clients = findChildren<QOpcUaClient*>(QString(), Qt::FindDirectChildrenOnly);
  for (auto* client : clients)
    delete client;
}

id IO::Drivers::OpcUa::loadSettings()
{
  m_endpointUrl = m_settings.value("OpcUaDriver/endpointUrl", m_endpointUrl).toString();
  m_authMode    = m_settings.value("OpcUaDriver/authMode", 0).toInt();
  m_username    = m_settings.value("OpcUaDriver/username", QString()).toString();
  m_publishingInterval =
    m_settings.value("OpcUaDriver/publishingInterval", kDefaultIntervalMs).toInt();
  m_publishingInterval = qBound(kMinIntervalMs, m_publishingInterval, kMaxIntervalMs);

  const QUrl url(m_endpointUrl);
  if (url.isValid() && !url.host().isEmpty())
    m_password =
      m_vault.credentials(url.host(), static_cast<quint16>(url.port(kDefaultPort))).password;

  const auto doc =
    QJsonDocument::fromJson(m_settings.value("OpcUaDriver/tags", QByteArray("[]")).toByteArray());
  if (doc.isArray())
    setTags(doc.array());
}

id IO::Drivers::OpcUa::saveTags()
{
  if (!m_persistent)
    return;

  m_settings.setValue("OpcUaDriver/tags", QJsonDocument(tagsJson()).toJson(QJsonDocument::Compact));
}

id IO::Drivers::OpcUa::setPersistent(const bool persistent) noexcept
{
  if (m_persistent == persistent)
    return;

  m_persistent = persistent;
}

id IO::Drivers::OpcUa::close()
{
  m_connecting = false;
  doClose();
  applyDeferredTags();

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
}

id IO::Drivers::OpcUa::applyDeferredTags()
{
  if (!m_hasDeferred)
    return;

  const auto pending = m_deferredTags;
  m_hasDeferred      = false;
  m_deferredTags     = QJsonArray();
  setTags(pending);
}

id IO::Drivers::OpcUa::doClose()
{
  if (m_pendingDial == PendingDial::Live)
    m_pendingDial = PendingDial::None;

  m_dialTimer->stop();
  m_pollTimer->stop();
  m_frameTimer->stop();

  for (auto* node : m_nodes) {
    if (!node)
      continue;

    disconnect(node, nullptr, this, nullptr);
    node->deleteLater();
  }

  m_nodes.clear();
  m_nodeIndex.clear();
  m_slots.clear();
  m_watchdog->stop();
  m_polledTags.clear();
  m_pendingMonitors = 0;
  m_failedMonitors  = 0;
  m_revisedInterval = 0;
  m_frameCursor     = 0;
  m_readLimit       = kDefaultReadLimit;
  m_readInFlight    = false;
  m_subscribing     = false;
  m_pollMode        = false;
  m_clockValid      = false;
  m_lastNotifyNs    = 0;
  m_serverOffsetMs  = 0;

  teardownClient(m_client);
}

id IO::Drivers::OpcUa::teardownClient(QOpcUaClient*& client)
{
  if (!client)
    return;

  disconnect(client, nullptr, this, nullptr);
  if (client->state() != QOpcUaClient::Disconnected)
    client->disconnectFromEndpoint();

  client->deleteLater();
  client = nullptr;
}

ol IO::Drivers::OpcUa::configurationOk() const noexcept
{
  if (m_tags.isEmpty() || m_tags.size() > OpcUaWire::kMaxTags)
    return false;

  if (m_authMode == 1 && m_username.isEmpty())
    return false;

  if (m_endpointIndex >= 0 && m_endpointIndex < m_endpoints.size())
    return policyIsNone(m_endpoints.at(m_endpointIndex));

  return QUrl(m_endpointUrl).isValid() && !QUrl(m_endpointUrl).host().isEmpty();
}

nt64 IO::Drivers::OpcUa::write(const QByteArray& data)
{
  Q_UNUSED(data)
  return 0;
}

ol IO::Drivers::OpcUa::open(const QIODevice::OpenMode mode)
{
  Q_UNUSED(mode)

  close();
  if (!configurationOk())
    return false;

  m_client = makeClient();
  if (!m_client) {
    logDriverError(tr("OPC UA Initialization Failed"),
                   tr("The %1 backend is not available in this build.").arg(kBackendName));
    return false;
  }

  connect(m_client, &QOpcUaClient::stateChanged, this, &IO::Drivers::OpcUa::onStateChanged);
  connect(m_client, &QOpcUaClient::errorChanged, this, &IO::Drivers::OpcUa::onErrorChanged);
  connect(
    m_client, &QOpcUaClient::readNodeAttributesFinished, this, &IO::Drivers::OpcUa::onReadFinished);

  applyAuthentication(m_client);
  if (m_authMode == 1)
    qCWarning(lcOpcUa) << "Username/password selected on a None-policy channel: credentials "
                          "travel unencrypted to"
                       << selectedEndpointUrl();

  m_connecting = true;
  m_lastError.clear();
  m_dialTimer->start(kDialDeadlineMs);

  if (hasSelectedEndpoint())
    m_client->connectToEndpoint(dialEndpoint());
  else {
    m_pendingDial = PendingDial::Live;
    discoverEndpoints();
  }

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
  return m_connecting || isOpen();
}

ol IO::Drivers::OpcUa::hasSelectedEndpoint() const noexcept
{
  return m_endpointIndex >= 0 && m_endpointIndex < m_endpoints.size()
      && policyIsNone(m_endpoints.at(m_endpointIndex))
      && endpointAcceptsToken(m_endpoints.at(m_endpointIndex), m_authMode);
}

pcUaProvider& IO::Drivers::OpcUa::provider()
{
  static QOpcUaProvider* instance = new QOpcUaProvider;
  return *instance;
}

pcUaClient* IO::Drivers::OpcUa::makeClient()
{
  auto* client = provider().createClient(QString::fromLatin1(kBackendName));
  if (!client)
    return nullptr;

  QOpcUaConnectionSettings settings;
  settings.setConnectTimeout(std::chrono::milliseconds(kDialDeadlineMs));
  settings.setRequestTimeout(std::chrono::milliseconds(kRequestTimeoutMs));
  settings.setSessionTimeout(std::chrono::milliseconds(kSessionTimeoutMs));
  settings.setSecureChannelLifeTime(std::chrono::milliseconds(kChannelLifetimeMs));
  client->setConnectionSettings(settings);
  client->setParent(this);
  return client;
}

id IO::Drivers::OpcUa::applyAuthentication(QOpcUaClient* client) const
{
  SS_ASSERT(client != nullptr, return);

  QOpcUaAuthenticationInformation auth;
  if (m_authMode == 1)
    auth.setUsernameAuthentication(m_username, m_password);
  else
    auth.setAnonymousAuthentication();

  client->setAuthenticationInformation(auth);
}

tring IO::Drivers::OpcUa::selectedEndpointUrl() const
{
  if (m_endpointIndex >= 0 && m_endpointIndex < m_endpoints.size())
    return m_endpoints.at(m_endpointIndex).endpointUrl();

  return m_endpointUrl;
}

ol IO::Drivers::OpcUa::policyIsNone(const QOpcUaEndpointDescription& endpoint)
{
  return endpoint.securityPolicy() == QLatin1String(kPolicyNone)
      && endpoint.securityMode() == QOpcUaEndpointDescription::None;
}

ol IO::Drivers::OpcUa::endpointAcceptsToken(const QOpcUaEndpointDescription& endpoint,
                                              const int authMode)
{
  const auto wanted =
    authMode == 1 ? QOpcUaUserTokenPolicy::Username : QOpcUaUserTokenPolicy::Anonymous;

  const auto tokens = endpoint.userIdentityTokens();
  if (tokens.isEmpty())
    return true;

  for (const auto& token : tokens)
    if (token.tokenType() == wanted)
      return true;

  return false;
}

pcUaEndpointDescription IO::Drivers::OpcUa::dialEndpoint() const
{
  QOpcUaEndpointDescription endpoint;
  if (!hasSelectedEndpoint()) {
    endpoint.setEndpointUrl(m_endpointUrl);
    endpoint.setSecurityPolicy(QString::fromLatin1(kPolicyNone));
    endpoint.setSecurityMode(QOpcUaEndpointDescription::None);
    return endpoint;
  }

  endpoint = m_endpoints.at(m_endpointIndex);

  const QUrl typed(m_endpointUrl);
  QUrl advertised(endpoint.endpointUrl());
  if (!typed.isValid() || typed.host().isEmpty() || !advertised.isValid())
    return endpoint;

  advertised.setHost(typed.host());
  advertised.setPort(typed.port(advertised.port(kDefaultPort)));
  endpoint.setEndpointUrl(advertised.toString());
  return endpoint;
}

id IO::Drivers::OpcUa::failDial(const QString& reason)
{
  if (!m_connecting)
    return;

  m_connecting = false;
  m_lastError  = reason;
  doClose();

  logDriverError(tr("OPC UA Connection Failed"),
                 reason.isEmpty() ? tr("Unable to connect to \"%1\".").arg(selectedEndpointUrl())
                                  : tr("\"%1\": %2").arg(selectedEndpointUrl(), reason));

  reportOpenFinished(false, reason);

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
}

id IO::Drivers::OpcUa::onLinkDropped(const QString& reason)
{
  m_lastError = reason;
  ++m_linkDrops;
  logDriverError(tr("OPC UA Connection Lost"), reason);

  static auto& manager = ConnectionManager::instance();
  QMetaObject::invokeMethod(this, [this] { manager.disconnectDevice(this); }, Qt::QueuedConnection);

  Q_EMIT statusChanged();
  Q_EMIT configurationChanged();
}

id IO::Drivers::OpcUa::onStateChanged(QOpcUaClient::ClientState state)
{
  if (!m_client)
    return;

  if (state == QOpcUaClient::Connected) {
    m_dialTimer->stop();
    m_connecting = false;
    reportOpenFinished(true);
    subscribeAll();
    Q_EMIT statusChanged();
    Q_EMIT configurationChanged();
    return;
  }

  if (state != QOpcUaClient::Disconnected)
    return;

  if (m_connecting)
    failDial(m_lastError.isEmpty() ? tr("The server closed the connection") : m_lastError);
  else if (!m_nodes.isEmpty())
    onLinkDropped(m_lastError.isEmpty() ? tr("The server closed the session") : m_lastError);
}

id IO::Drivers::OpcUa::onErrorChanged(QOpcUaClient::ClientError error)
{
  switch (error) {
    case QOpcUaClient::NoError:
      return;
    case QOpcUaClient::InvalidUrl:
      m_lastError = tr("Invalid endpoint URL");
      break;
    case QOpcUaClient::AccessDenied:
      m_lastError = tr("Access denied (bad credentials or anonymous login refused)");
      break;
    case QOpcUaClient::ConnectionError:
      m_lastError = tr("Connection error (server unreachable or refused)");
      break;
    case QOpcUaClient::UnsupportedAuthenticationInformation:
    case QOpcUaClient::InvalidAuthenticationInformation:
      m_lastError = tr("The server does not accept this authentication mode");
      break;
    case QOpcUaClient::InvalidEndpointDescription:
      m_lastError = tr("The endpoint description was rejected (unsupported security policy)");
      break;
    case QOpcUaClient::NoMatchingUserIdentityTokenFound:
      m_lastError = tr("The endpoint offers no matching user identity token");
      break;
    case QOpcUaClient::UnsupportedSecurityPolicy:
      m_lastError = tr("The security policy is not supported by this build");
      break;
    case QOpcUaClient::InvalidPki:
      m_lastError = tr("The certificate store is invalid or unreadable");
      break;
    case QOpcUaClient::CertificateUntrusted:
      m_lastError = tr("The server certificate is not trusted");
      break;
    default:
      m_lastError = tr("Unexpected backend error");
      break;
  }

  if (m_connecting && m_client && m_client->state() == QOpcUaClient::Disconnected)
    failDial(m_lastError);
}

id IO::Drivers::OpcUa::discoverEndpoints()
{
  if (m_discovering)
    return;

  const QUrl url(m_endpointUrl);
  if (!url.isValid() || url.host().isEmpty()) {
    m_lastError = tr("\"%1\" is not a valid endpoint URL").arg(m_endpointUrl);
    logDriverError(tr("OPC UA Discovery"), m_lastError);
    continuePendingDial();
    return;
  }

  teardownClient(m_discoveryClient);
  m_discoveryClient = makeClient();
  if (!m_discoveryClient) {
    m_lastError = tr("The %1 backend is not available in this build").arg(kBackendName);
    continuePendingDial();
    return;
  }

  connect(m_discoveryClient,
          &QOpcUaClient::endpointsRequestFinished,
          this,
          [this](const QList<QOpcUaEndpointDescription>& endpoints,
                 QOpcUa::UaStatusCode status,
                 const QUrl&) { onEndpointsFinished(endpoints, status); });

  m_discovering = true;
  Q_EMIT discoveringChanged();

  if (!m_discoveryClient->requestEndpoints(url))
    onEndpointsFinished({}, QOpcUa::UaStatusCode::BadInternalError);
}

id IO::Drivers::OpcUa::onEndpointsFinished(const QList<QOpcUaEndpointDescription>& endpoints,
                                             QOpcUa::UaStatusCode status)
{
  m_discovering = false;
  teardownClient(m_discoveryClient);

  if (status != QOpcUa::UaStatusCode::Good) {
    m_endpoints.clear();
    m_endpointIndex = -1;
    m_lastError     = tr("Discovery failed: %1").arg(QOpcUa::statusToString(status));
    logDriverError(tr("OPC UA Discovery Failed"), tr("\"%1\": %2").arg(m_endpointUrl, m_lastError));
  } else {
    const auto previous = m_endpointIndex >= 0 && m_endpointIndex < m_endpoints.size()
                          ? m_endpoints.at(m_endpointIndex).endpointUrl()
                          : QString();

    m_endpoints     = endpoints;
    m_endpointIndex = -1;

    for (int i = 0; i < m_endpoints.size(); ++i) {
      const auto& candidate = m_endpoints.at(i);
      if (!policyIsNone(candidate) || !endpointAcceptsToken(candidate, m_authMode))
        continue;

      if (m_endpointIndex < 0)
        m_endpointIndex = i;

      if (!previous.isEmpty() && candidate.endpointUrl() == previous) {
        m_endpointIndex = i;
        break;
      }
    }

    if (m_endpointIndex < 0) {
      m_lastError =
        tr("No None-policy endpoint; secure channels are not supported in this version");
      logDriverError(tr("OPC UA Discovery"), tr("\"%1\": %2").arg(m_endpointUrl, m_lastError));
    }
  }

  Q_EMIT discoveringChanged();
  Q_EMIT statusChanged();
  Q_EMIT endpointsChanged();
  Q_EMIT endpointIndexChanged();
  continuePendingDial();
}

id IO::Drivers::OpcUa::continuePendingDial()
{
  const auto pending = m_pendingDial;
  m_pendingDial      = PendingDial::None;

  if (pending == PendingDial::Live) {
    if (m_client && hasSelectedEndpoint())
      m_client->connectToEndpoint(dialEndpoint());
    else
      failDial(m_lastError.isEmpty() ? tr("Endpoint discovery failed") : m_lastError);

    return;
  }

  if (pending != PendingDial::Browse)
    return;

  if (m_browseClient && hasSelectedEndpoint()) {
    m_browseClient->connectToEndpoint(dialEndpoint());
    return;
  }

  Q_EMIT browseFailed(m_lastError.isEmpty() ? tr("Endpoint discovery failed") : m_lastError);
  cancelBrowse();
}

id IO::Drivers::OpcUa::subscribeAll()
{
  SS_ASSERT(m_client != nullptr, return);
  SS_ASSERT(!m_tags.isEmpty(), return);

  const auto steady     = std::chrono::steady_clock::now().time_since_epoch();
  const qint64 steadyNs = std::chrono::duration_cast<std::chrono::nanoseconds>(steady).count();
  m_clockOffsetNs       = steadyNs - QDateTime::currentMSecsSinceEpoch() * kNsPerMs;
  m_clockValid          = true;
  m_lastStampNs         = 0;
  m_lastNotifyNs        = steadyNs;
  m_serverOffsetMs      = 0;

  reserveFrame();
  readServerLimits();

  m_pendingMonitors = m_tags.size();
  m_failedMonitors  = 0;
  m_revisedInterval = m_publishingInterval;
  m_pollMode        = false;
  m_subscribing     = true;
  m_polledTags.clear();

  QOpcUaMonitoringParameters params(static_cast<double>(m_publishingInterval));
  params.setSamplingInterval(static_cast<double>(m_publishingInterval));
  params.setQueueSize(1);
  params.setDiscardOldest(true);
  for (int i = 0; i < m_tags.size(); ++i) {
    auto* node = m_client->node(m_tags.at(i).nodeId);
    if (node)
      node->setParent(this);

    m_nodes.append(node);
    m_nodeIndex.insert(m_tags.at(i).nodeId, i);
    if (!node) {
      onMonitoringEnabled(i, QOpcUa::UaStatusCode::BadNodeIdInvalid);
      continue;
    }

    connect(node, &QOpcUaNode::valueAttributeUpdated, this, [this, i](const QVariant& value) {
      onValueUpdated(i, value);
    });
    connect(node,
            &QOpcUaNode::enableMonitoringFinished,
            this,
            [this, i](QOpcUa::NodeAttribute, QOpcUa::UaStatusCode status) {
              onMonitoringEnabled(i, status);
            });

    if (!node->enableMonitoring(QOpcUa::NodeAttribute::Value, params))
      onMonitoringEnabled(i, QOpcUa::UaStatusCode::BadInternalError);
  }

  m_frameTimer->start(m_publishingInterval);
  m_watchdog->start(kWatchdogMs);
}

id IO::Drivers::OpcUa::readServerLimits()
{
  SS_ASSERT(m_client != nullptr, return);

  auto* node = m_client->node(QStringLiteral("ns=0;i=11705"));
  if (!node)
    return;

  node->setParent(this);
  connect(node, &QOpcUaNode::attributeRead, this, [this, node](QOpcUa::NodeAttributes) {
    const int limit = node->attribute(QOpcUa::NodeAttribute::Value).toInt();
    if (limit > 0)
      m_readLimit = qBound(1, limit, kDefaultReadLimit * 10);

    node->deleteLater();
  });

  if (!node->readAttributes(QOpcUa::NodeAttribute::Value))
    node->deleteLater();
}

id IO::Drivers::OpcUa::reserveFrame()
{
  m_firstIndex.clear();
  m_slots.clear();

  m_slotCount.clear();

  qsizetype bytes = OpcUaWire::kHeaderBytes;
  for (const auto& tag : m_tags) {
    const auto type = wireTypeFor(tag);
    const int count = qMax(1, tag.arrayLen);
    m_firstIndex.append(m_slots.size());
    m_slotCount.append(count);
    bytes += static_cast<qsizetype>(count) * OpcUaWire::maxEntryBytes(type);
    for (int i = 0; i < count; ++i) {
      Slot slot;
      slot.type = type;
      m_slots.append(slot);
    }
  }

  SS_ASSERT_LOG(m_slots.size() <= OpcUaWire::kMaxTags);
  m_frameBytes = qMin<qsizetype>(bytes, OpcUaWire::kMaxFrameBytes);
  m_frame      = QByteArray();
  m_frame.reserve(m_frameBytes);
}

id IO::Drivers::OpcUa::onMonitoringEnabled(int tag, QOpcUa::UaStatusCode status)
{
  SS_ASSERT(tag >= 0 && tag < m_tags.size(), return);
  if (m_pendingMonitors <= 0)
    return;

  --m_pendingMonitors;
  if (status != QOpcUa::UaStatusCode::Good) {
    ++m_failedMonitors;
    m_polledTags.append(tag);
    logDriverError(tr("OPC UA Monitored Item Refused"),
                   tr("\"%1\": %2").arg(m_tags.at(tag).nodeId, QOpcUa::statusToString(status)));
  } else if (m_revisedInterval == m_publishingInterval) {
    adoptRevisedInterval(tag);
  }

  if (m_pendingMonitors > 0)
    return;

  m_subscribing = false;
  if (m_failedMonitors == m_nodes.size()) {
    enterPollMode(tr("the server refused every monitored item"));
    return;
  }

  if (!m_polledTags.isEmpty()) {
    m_pollTimer->start(m_revisedInterval);
    onPollTick();
  }

  Q_EMIT statusChanged();
}

id IO::Drivers::OpcUa::adoptRevisedInterval(int tag)
{
  SS_ASSERT(tag >= 0 && tag < m_nodes.size(), return);
  auto* node = m_nodes.at(tag);
  SS_ASSERT(node != nullptr, return);

  const auto status = node->monitoringStatus(QOpcUa::NodeAttribute::Value);
  const int revised = static_cast<int>(status.publishingInterval());
  if (revised <= 0 || revised == m_revisedInterval)
    return;

  m_revisedInterval = qBound(kMinIntervalMs, revised, kMaxIntervalMs);
  if (m_frameTimer->isActive())
    m_frameTimer->start(m_revisedInterval);

  if (m_pollTimer->isActive())
    m_pollTimer->start(m_revisedInterval);
}

id IO::Drivers::OpcUa::enterPollMode(const QString& reason)
{
  if (m_pollMode)
    return;

  m_pollMode = true;
  m_polledTags.clear();
  for (int i = 0; i < m_tags.size(); ++i)
    m_polledTags.append(i);

  logDriverError(tr("OPC UA Subscription Unavailable"),
                 tr("Falling back to polling: %1.").arg(reason));

  m_pollTimer->start(m_revisedInterval > 0 ? m_revisedInterval : m_publishingInterval);
  onPollTick();
  Q_EMIT statusChanged();
}

id IO::Drivers::OpcUa::onWatchdogTick()
{
  if (!isOpen() || m_pollMode || m_subscribing || m_lastNotifyNs == 0)
    return;

  const auto now        = std::chrono::steady_clock::now().time_since_epoch();
  const qint64 nowNs    = std::chrono::duration_cast<std::chrono::nanoseconds>(now).count();
  const qint64 silentMs = (nowNs - m_lastNotifyNs) / kNsPerMs;
  const qint64 budgetMs =
    qMax<qint64>(kMinSilenceMs, static_cast<qint64>(m_revisedInterval) * kSilenceFactor);

  if (silentMs < budgetMs)
    return;

  enterPollMode(tr("no notification for %1 s").arg(silentMs / 1000));
}

id IO::Drivers::OpcUa::onPollTick()
{
  if (!isOpen() || m_polledTags.isEmpty())
    return;

  if (m_readInFlight) {
    ++m_skippedPolls;
    return;
  }

  issueRead(m_polledTags);
}

id IO::Drivers::OpcUa::issueRead(const QList<int>& tags)
{
  SS_ASSERT(m_client != nullptr, return);
  SS_ASSERT(!tags.isEmpty(), return);

  QList<QOpcUaReadItem> items;
  items.reserve(qMin(tags.size(), m_readLimit));
  for (const int tag : tags) {
    if (tag < 0 || tag >= m_tags.size())
      continue;

    items.append(QOpcUaReadItem(m_tags.at(tag).nodeId, QOpcUa::NodeAttribute::Value));
    if (items.size() < m_readLimit)
      continue;

    m_readInFlight = m_client->readNodeAttributes(items);
    items.clear();
    return;
  }

  if (!items.isEmpty())
    m_readInFlight = m_client->readNodeAttributes(items);
}

id IO::Drivers::OpcUa::onReadFinished(const QList<QOpcUaReadResult>& results,
                                        QOpcUa::UaStatusCode status)
{
  m_readInFlight = false;
  if (status != QOpcUa::UaStatusCode::Good) {
    logDriverError(tr("OPC UA Read Failed"), QOpcUa::statusToString(status));
    return;
  }

  for (const auto& result : results) {
    const int tag = m_nodeIndex.value(result.nodeId(), -1);
    if (tag < 0)
      continue;

    storeValue(tag, result.value(), result.statusCode(), result.sourceTimestamp());
  }
}

id IO::Drivers::OpcUa::onValueUpdated(int tag, const QVariant& value)
{
  SS_ASSERT(tag >= 0 && tag < m_nodes.size(), return);
  auto* node = m_nodes.at(tag);
  SS_ASSERT(node != nullptr, return);

  const auto now = std::chrono::steady_clock::now().time_since_epoch();
  m_lastNotifyNs = std::chrono::duration_cast<std::chrono::nanoseconds>(now).count();

  if (!m_serverOffsetMs) {
    const auto serverTs = node->serverTimestamp(QOpcUa::NodeAttribute::Value);
    if (serverTs.isValid())
      m_serverOffsetMs = serverTs.toMSecsSinceEpoch() - QDateTime::currentMSecsSinceEpoch();
  }

  storeValue(
    tag, value, node->valueAttributeError(), node->sourceTimestamp(QOpcUa::NodeAttribute::Value));
}

id IO::Drivers::OpcUa::storeValue(int tag,
                                    const QVariant& value,
                                    QOpcUa::UaStatusCode status,
                                    const QDateTime& sourceTs)
{
  SS_ASSERT(tag >= 0 && tag < m_firstIndex.size(), return);
  ++m_valuesReceived;

  const auto severity = static_cast<quint32>(status) & 0xC0000000u;
  if (severity >= 0x80000000u) {
    ++m_badStatusCount;
    markBad(tag);
    return;
  }

  const int first = m_firstIndex.at(tag);
  const int count = m_slotCount.at(tag);
  if (value.typeId() == QMetaType::QVariantList) {
    const auto list = value.toList();
    for (int i = 0; i < count && i < list.size() && first + i < m_slots.size(); ++i) {
      auto& slot    = m_slots[first + i];
      slot.value    = list.at(i);
      slot.sourceTs = sourceTs;
      slot.dirty    = true;
      slot.bad      = false;
    }

    return;
  }

  SS_ASSERT(first < m_slots.size(), return);
  auto& slot    = m_slots[first];
  slot.value    = value;
  slot.sourceTs = sourceTs;
  slot.dirty    = true;
  slot.bad      = false;
}

id IO::Drivers::OpcUa::markBad(int tag)
{
  SS_ASSERT(tag >= 0 && tag < m_firstIndex.size(), return);

  const int first = m_firstIndex.at(tag);
  const int count = m_slotCount.at(tag);
  for (int i = 0; i < count && first + i < m_slots.size(); ++i)
    m_slots[first + i].bad = true;
}

tringList IO::Drivers::OpcUa::badTags() const
{
  QStringList out;
  for (int tag = 0; tag < m_firstIndex.size() && tag < m_tags.size(); ++tag) {
    const int first = m_firstIndex.at(tag);
    if (first < m_slots.size() && m_slots.at(first).bad)
      out.append(m_tags.at(tag).nodeId);
  }

  return out;
}

::CapturedData::SteadyTimePoint IO::Drivers::OpcUa::toSteady(const QDateTime& sourceTs)
{
  const auto now = CapturedData::SteadyClock::now();
  const qint64 nowNs =
    std::chrono::duration_cast<std::chrono::nanoseconds>(now.time_since_epoch()).count();

  qint64 stamp = nowNs;
  if (!m_clockValid || !sourceTs.isValid())
    ++m_unstampedCount;
  else {
    const qint64 skewMs =
      sourceTs.toMSecsSinceEpoch() - QDateTime::currentMSecsSinceEpoch() - m_serverOffsetMs;
    if (skewMs > kMaxClockSkewMs || skewMs < -kMaxClockSkewMs)
      ++m_unstampedCount;
    else
      stamp = (sourceTs.toMSecsSinceEpoch() - m_serverOffsetMs) * kNsPerMs + m_clockOffsetNs;
  }

  stamp         = qMax(stamp, m_lastStampNs + 1);
  m_lastStampNs = stamp;
  return CapturedData::SteadyTimePoint(std::chrono::nanoseconds(stamp));
}

id IO::Drivers::OpcUa::onFrameTick()
{
  if (!isOpen())
    return;

  using namespace OpcUaWire;
  beginFrame(m_frame);

  QDateTime earliest;
  const int slotCount = m_slots.size();
  if (m_frameCursor >= slotCount)
    m_frameCursor = 0;

  for (int step = 0; step < slotCount; ++step) {
    const int index = (m_frameCursor + step) % slotCount;
    auto& slot      = m_slots[index];
    if (!slot.dirty)
      continue;

    if (m_frame.size() + maxEntryBytes(slot.type) > kMaxFrameBytes) {
      m_frameCursor = index;
      break;
    }

    if (!slot.warned && !valueFitsType(slot.value, slot.type)) {
      slot.warned = true;
      logDriverError(tr("OPC UA Type Mismatch"),
                     tr("Channel %1 is declared %2 but the server sends %3; the value is coerced.")
                       .arg(QString::number(index),
                            codeFromType(slot.type),
                            QString::fromLatin1(slot.value.typeName())));
    }

    appendEntry(m_frame, index, slot.type, slot.value);
    slot.dirty = false;
    if (!earliest.isValid() || (slot.sourceTs.isValid() && slot.sourceTs < earliest))
      earliest = slot.sourceTs;
  }

  if (m_frame.size() <= kHeaderBytes)
    return;

  ++m_framesPublished;
  publishReceivedData(std::move(m_frame), toSteady(earliest));
  m_frame = QByteArray();
  m_frame.reserve(m_frameBytes);
}

::Drivers::OpcUaWire::Type IO::Drivers::OpcUa::wireTypeFor(const OpcUaTag& tag) noexcept
{
  if (tag.type == OpcUaWire::Type::Invalid)
    return OpcUaWire::Type::Str;

  return tag.type;
}

::Drivers::OpcUaTagModel* IO::Drivers::OpcUa::tagModel()
{
  if (!m_tagModel) {
    m_tagModel = new OpcUaTagModel(this);
    connect(
      m_tagModel, &OpcUaTagModel::browseError, this, [this](const QString& id, const QString& r) {
        Q_EMIT browseFailed(tr("Browse of %1 failed: %2").arg(id, r));
      });
  }

  return m_tagModel;
}

id IO::Drivers::OpcUa::startBrowse()
{
  if (m_browsing)
    return;

  if (!QUrl(m_endpointUrl).isValid() || QUrl(m_endpointUrl).host().isEmpty()) {
    Q_EMIT browseFailed(tr("\"%1\" is not a valid endpoint URL.").arg(m_endpointUrl));
    return;
  }

  teardownClient(m_browseClient);
  m_browseClient = makeClient();
  if (!m_browseClient) {
    Q_EMIT browseFailed(tr("The %1 backend is not available in this build.").arg(kBackendName));
    return;
  }

  connect(
    m_browseClient, &QOpcUaClient::stateChanged, this, &IO::Drivers::OpcUa::onBrowseClientState);
  applyAuthentication(m_browseClient);

  tagModel()->preselect(m_tags);
  m_browsing = true;
  Q_EMIT browsingChanged();

  if (hasSelectedEndpoint())
    m_browseClient->connectToEndpoint(dialEndpoint());
  else {
    m_pendingDial = PendingDial::Browse;
    discoverEndpoints();
  }
}

id IO::Drivers::OpcUa::stopBrowse()
{
  if (m_tagModel && m_browseClient && m_browseClient->state() == QOpcUaClient::Connected) {
    QJsonArray array;
    const auto selected = m_tagModel->selectedTags();
    for (const auto& tag : selected)
      array.append(tagToJson(tag));

    for (const auto& tag : m_tags)
      if (!m_tagModel->hasSeen(tag.nodeId))
        array.append(tagToJson(tag));

    setTags(array);
  }

  if (m_tagModel)
    m_tagModel->setClient(nullptr);

  teardownClient(m_browseClient);
  if (!m_browsing)
    return;

  m_browsing = false;
  Q_EMIT browsingChanged();
}

id IO::Drivers::OpcUa::cancelBrowse()
{
  if (m_pendingDial == PendingDial::Browse)
    m_pendingDial = PendingDial::None;

  if (m_tagModel)
    m_tagModel->setClient(nullptr);

  teardownClient(m_browseClient);
  if (!m_browsing)
    return;

  m_browsing = false;
  Q_EMIT browsingChanged();
}

id IO::Drivers::OpcUa::onBrowseClientState(QOpcUaClient::ClientState state)
{
  if (!m_browseClient)
    return;

  if (state == QOpcUaClient::Connected) {
    tagModel()->setClient(m_browseClient);
    tagModel()->fetchMore(QModelIndex());
    return;
  }

  if (state != QOpcUaClient::Disconnected || !m_browsing)
    return;

  m_lastError = tr("Could not open a browse session on %1").arg(selectedEndpointUrl());
  Q_EMIT browseFailed(m_lastError);
  Q_EMIT statusChanged();
  if (m_tagModel)
    m_tagModel->setClient(nullptr);

  teardownClient(m_browseClient);
  m_browsing = false;
  Q_EMIT browsingChanged();
}

taModel::ProjectModel* IO::Drivers::OpcUa::loadGeneratedProject()
{
  if (m_tags.isEmpty())
    return nullptr;

  static auto& pm       = DataModel::ProjectModel::instance();
  static auto& appState = AppState::instance();
  appState.setOperationMode(SerialStudio::ProjectFile);
  if (!pm.loadFromJsonDocument(QJsonDocument(buildProject()), QString())) {
    logDriverError(tr("Failed to load generated project"),
                   tr("The generated project JSON could not be loaded."));
    return nullptr;
  }

  pm.setModified(true);
  return &pm;
}

id IO::Drivers::OpcUa::generateProject()
{
  if (m_tags.isEmpty()) {
    Misc::Utilities::showMessageBox(tr("No tags selected"),
                                    tr("Browse the server and select at least one tag before "
                                       "generating a project."),
                                    QMessageBox::Warning,
                                    tr("OPC UA Project Generator"));
    return;
  }

  auto* pm = loadGeneratedProject();
  if (!pm)
    return;

  const int groupCount = buildProject().value(Keys::Groups).toArray().size();
  const int datasets   = wireSchema().size();
  QObject::connect(
    pm,
    &DataModel::ProjectModel::saveDialogCompleted,
    this,
    [groupCount, datasets](bool accepted) {
      if (!accepted)
        return;

      Misc::Utilities::showMessageBox(
        tr("Successfully generated project with %1 groups and %2 datasets.")
          .arg(groupCount)
          .arg(datasets),
        tr("The project editor is now open for customization."),
        QMessageBox::Information,
        tr("OPC UA Project Generator"));
    },
    Qt::SingleShotConnection);

  (void)pm->saveJsonFile(true);
}

taModel::Dataset IO::Drivers::OpcUa::datasetFor(const OpcUaTag& tag, int element, int index)
{
  SS_ASSERT_LOG(index >= 1);
  const auto type = wireTypeFor(tag);

  DataModel::Dataset dataset;
  dataset.index = index;
  dataset.log   = true;
  dataset.units = tag.unit;
  dataset.title = qMax(1, tag.arrayLen) > 1
                  ? QStringLiteral("%1[%2]").arg(tag.name, QString::number(element))
                  : tag.name;

  if (type == OpcUaWire::Type::Bool) {
    dataset.led     = true;
    dataset.ledHigh = 1;
    dataset.wgtMax  = 1;
  } else if (type != OpcUaWire::Type::Str) {
    dataset.plt = true;
    if (tag.max > tag.min) {
      dataset.wgtMin = tag.min;
      dataset.wgtMax = tag.max;
      dataset.pltMin = tag.min;
      dataset.pltMax = tag.max;
    }
  }

  return dataset;
}

sonObject IO::Drivers::OpcUa::buildProject() const
{
  QJsonObject project;
  project[Keys::Title]   = tr("OPC UA Project");
  project[Keys::Actions] = QJsonArray();

  QJsonObject source;
  source[Keys::SourceId]              = 0;
  source[Keys::Title]                 = tr("OPC UA");
  source[Keys::BusType]               = static_cast<int>(SerialStudio::BusType::OpcUa);
  source[Keys::FrameStart]            = QString();
  source[Keys::FrameEnd]              = QString();
  source[Keys::Checksum]              = QString();
  source[Keys::FrameDetection]        = static_cast<int>(SerialStudio::NoDelimiters);
  source[Keys::Decoder]               = static_cast<int>(SerialStudio::Binary);
  source[Keys::HexadecimalDelimiters] = false;
  source[Keys::FrameParserCode]       = QString();
  source[Keys::FrameParserLanguage]   = static_cast<int>(SerialStudio::Native);
  source[Keys::FrameParserTemplate]   = QStringLiteral("opcua");
  source[Keys::FrameParserParams]     = QJsonObject{
        {QStringLiteral("schema"), wireSchema()}
  };

  QJsonObject conn;
  for (const auto& prop : driverProperties())
    if (prop.type != IO::DriverProperty::Password)
      conn.insert(prop.key, QJsonValue::fromVariant(prop.value));

  source[Keys::SourceConn] = conn;
  project[Keys::Sources]   = QJsonArray{source};

  QStringList order;
  QHash<QString, DataModel::Group> groups;
  int index = 0;
  for (const auto& tag : m_tags) {
    const QString key = tag.path.isEmpty() ? tr("Tags") : tag.path;
    if (!groups.contains(key)) {
      DataModel::Group group;
      group.groupId = order.size();
      group.widget  = QStringLiteral("datagrid");
      group.title   = key.section(QLatin1Char('/'), -1);
      groups.insert(key, group);
      order.append(key);
    }

    auto& group = groups[key];
    for (int i = 0; i < qMax(1, tag.arrayLen); ++i, ++index)
      group.datasets.push_back(datasetFor(tag, i, index + 1));
  }

  QJsonArray groupArray;
  for (const auto& key : order)
    groupArray.append(DataModel::serialize(groups.value(key)));

  project[Keys::Groups] = groupArray;
  return project;
}

tringList IO::Drivers::OpcUa::endpointList() const
{
  QStringList list;
  for (const auto& endpoint : m_endpoints) {
    const auto policy = endpoint.securityPolicy().section(QLatin1Char('#'), -1);
    const auto mode   = endpoint.securityMode() == QOpcUaEndpointDescription::None ? tr("None")
                      : endpoint.securityMode() == QOpcUaEndpointDescription::Sign
                        ? tr("Sign")
                        : tr("Sign & Encrypt");
    list.append(QStringLiteral("%1 / %2 / %3").arg(policy, mode, endpoint.endpointUrl()));
  }

  return list;
}

sonArray IO::Drivers::OpcUa::endpointsJson() const
{
  QJsonArray out;
  for (int i = 0; i < m_endpoints.size(); ++i) {
    const auto& endpoint = m_endpoints.at(i);

    QJsonArray tokens;
    for (const auto& token : endpoint.userIdentityTokens())
      tokens.append(static_cast<int>(token.tokenType()));

    out.append(QJsonObject{
      {QStringLiteral("index"), i},
      {QStringLiteral("policy"), endpoint.securityPolicy().section(QLatin1Char('#'), -1)},
      {QStringLiteral("mode"), static_cast<int>(endpoint.securityMode())},
      {QStringLiteral("url"), endpoint.endpointUrl()},
      {QStringLiteral("tokens"), tokens},
      {QStringLiteral("selectable"),
       policyIsNone(endpoint) && endpointAcceptsToken(endpoint, m_authMode)},
    });
  }

  return out;
}

ariantList IO::Drivers::OpcUa::endpointSelectable() const
{
  QVariantList list;
  for (const auto& endpoint : m_endpoints)
    list.append(policyIsNone(endpoint));

  return list;
}

tring IO::Drivers::OpcUa::statusText() const
{
  if (m_connecting)
    return tr("Connecting to %1").arg(selectedEndpointUrl());

  if (!isOpen())
    return m_lastError.isEmpty() ? tr("Not connected") : m_lastError;

  const int interval = m_revisedInterval > 0 ? m_revisedInterval : m_publishingInterval;
  const double hz    = 1000.0 / qMax(1, interval);

  if (m_subscribing)
    return tr("Subscribing, %1 of %2 tags")
      .arg(m_tags.size() - m_pendingMonitors)
      .arg(m_tags.size());

  if (!m_pollMode && !m_polledTags.isEmpty())
    return tr("Subscribed %1 tags, polling %2 refused, %3 Hz")
      .arg(m_tags.size() - m_polledTags.size())
      .arg(m_polledTags.size())
      .arg(hz, 0, 'f', 1);

  if (m_pollMode)
    return tr("Polling (server refused subscriptions), %1 tags, %2 Hz")
      .arg(m_tags.size())
      .arg(hz, 0, 'f', 1);

  return tr("Subscribed, %1 tags, %2 Hz").arg(m_tags.size()).arg(hz, 0, 'f', 1);
}

sonArray IO::Drivers::OpcUa::tagsJson() const
{
  QJsonArray array;
  for (const auto& tag : m_tags)
    array.append(tagToJson(tag));

  return array;
}

sonArray IO::Drivers::OpcUa::wireSchema() const
{
  QJsonArray schema;
  int index = 0;
  for (const auto& tag : m_tags) {
    const auto code = OpcUaWire::codeFromType(wireTypeFor(tag));
    for (int i = 0; i < qMax(1, tag.arrayLen) && index < OpcUaWire::kMaxTags; ++i, ++index)
      schema.append(QJsonObject{
        { QStringLiteral("i"),      index},
        { QStringLiteral("t"),       code},
        {QStringLiteral("id"), tag.nodeId}
      });
  }

  return schema;
}

tring IO::Drivers::OpcUa::tagInfo(const int index) const
{
  if (index < 0 || index >= m_tags.size())
    return {};

  const auto& tag = m_tags.at(index);
  return QStringLiteral("%1 (%2) %3")
    .arg(tag.name, OpcUaWire::codeFromType(wireTypeFor(tag)), tag.nodeId);
}

id IO::Drivers::OpcUa::setEndpointUrl(const QString& url)
{
  const auto trimmed = url.trimmed();
  if (m_endpointUrl == trimmed)
    return;

  m_endpointUrl = trimmed;
  if (m_persistent)
    m_settings.setValue("OpcUaDriver/endpointUrl", m_endpointUrl);

  m_endpoints.clear();
  m_endpointIndex = -1;

  const QUrl parsed(m_endpointUrl);
  if (parsed.isValid() && !parsed.host().isEmpty())
    m_password =
      m_vault.credentials(parsed.host(), static_cast<quint16>(parsed.port(kDefaultPort))).password;

  Q_EMIT endpointUrlChanged();
  Q_EMIT endpointsChanged();
  Q_EMIT endpointIndexChanged();
  Q_EMIT passwordChanged();
}

id IO::Drivers::OpcUa::setEndpointIndex(const int index)
{
  if (index == m_endpointIndex)
    return;

  if (index >= 0 && (index >= m_endpoints.size() || !policyIsNone(m_endpoints.at(index))))
    return;

  m_endpointIndex = index;
  Q_EMIT endpointIndexChanged();
}

id IO::Drivers::OpcUa::setAuthMode(const int mode)
{
  const int clamped = qBound(0, mode, 1);
  if (m_authMode == clamped)
    return;

  m_authMode = clamped;
  if (m_persistent)
    m_settings.setValue("OpcUaDriver/authMode", m_authMode);

  Q_EMIT authModeChanged();
}

id IO::Drivers::OpcUa::setUsername(const QString& username)
{
  if (m_username == username)
    return;

  m_username = username;
  const QUrl url(m_endpointUrl);
  if (m_persistent) {
    m_settings.setValue("OpcUaDriver/username", m_username);
    if (url.isValid() && !url.host().isEmpty())
      m_vault.setCredentials(
        url.host(), static_cast<quint16>(url.port(kDefaultPort)), m_username, m_password);
  }

  Q_EMIT usernameChanged();
}

id IO::Drivers::OpcUa::setPassword(const QString& password)
{
  if (m_password == password)
    return;

  m_password = password;
  const QUrl url(m_endpointUrl);
  if (m_persistent && url.isValid() && !url.host().isEmpty())
    m_vault.setCredentials(
      url.host(), static_cast<quint16>(url.port(kDefaultPort)), m_username, m_password);

  Q_EMIT passwordChanged();
}

id IO::Drivers::OpcUa::setPublishingInterval(const int interval)
{
  const int clamped = qBound(kMinIntervalMs, interval, kMaxIntervalMs);
  if (m_publishingInterval == clamped)
    return;

  m_publishingInterval = clamped;
  if (m_persistent)
    m_settings.setValue("OpcUaDriver/publishingInterval", m_publishingInterval);

  for (auto* node : m_nodes)
    if (node)
      (void)node->modifyMonitoring(QOpcUa::NodeAttribute::Value,
                                   QOpcUaMonitoringParameters::Parameter::PublishingInterval,
                                   static_cast<double>(m_publishingInterval));

  m_revisedInterval = m_publishingInterval;
  if (m_frameTimer->isActive())
    m_frameTimer->start(m_publishingInterval);

  if (m_pollTimer->isActive())
    m_pollTimer->start(m_publishingInterval);

  Q_EMIT publishingIntervalChanged();
  Q_EMIT statusChanged();
}

id IO::Drivers::OpcUa::setTags(const QJsonArray& tags)
{
  QList<OpcUaTag> list;
  QSet<QString> seen;
  int indices = 0;
  for (const auto& item : tags) {
    const auto tag  = tagFromJson(item.toObject());
    const int count = qMax(1, tag.arrayLen);
    if (tag.nodeId.isEmpty() || seen.contains(tag.nodeId) || count > OpcUaWire::kMaxTags - indices)
      continue;

    seen.insert(tag.nodeId);
    indices += count;
    list.append(tag);
  }

  if (list == m_tags)
    return;

  if (tagsFrozen()) {
    m_deferredTags = tags;
    m_hasDeferred  = true;
    return;
  }

  m_deferredTags = QJsonArray();
  m_hasDeferred  = false;
  m_tags         = list;
  saveTags();
  Q_EMIT tagsChanged();
}

id IO::Drivers::OpcUa::addTag(const OpcUaTag& tag)
{
  if (tag.nodeId.isEmpty() || tagsFrozen())
    return;

  for (const auto& existing : m_tags)
    if (existing.nodeId == tag.nodeId)
      return;

  int indices = 0;
  for (const auto& existing : m_tags)
    indices += qMax(1, existing.arrayLen);

  OpcUaTag bounded = tag;
  bounded.arrayLen = qBound(1, tag.arrayLen, OpcUaWire::kMaxTags);
  if (bounded.arrayLen > OpcUaWire::kMaxTags - indices)
    return;

  m_tags.append(bounded);
  saveTags();
  Q_EMIT tagsChanged();
}

id IO::Drivers::OpcUa::removeTag(const int index)
{
  if (index < 0 || index >= m_tags.size() || tagsFrozen())
    return;

  m_tags.removeAt(index);
  saveTags();
  Q_EMIT tagsChanged();
}

id IO::Drivers::OpcUa::clearTags()
{
  if (m_tags.isEmpty() || tagsFrozen())
    return;

  m_tags.clear();
  saveTags();
  Q_EMIT tagsChanged();
}

::Drivers::OpcUaTag IO::Drivers::OpcUa::tagFromJson(const QJsonObject& obj)
{
  OpcUaTag tag;
  tag.nodeId   = obj.value(QStringLiteral("id")).toString();
  tag.name     = obj.value(QStringLiteral("name")).toString(tag.nodeId);
  tag.path     = obj.value(QStringLiteral("path")).toString();
  tag.unit     = obj.value(QStringLiteral("unit")).toString();
  tag.type     = OpcUaWire::typeFromCode(obj.value(QStringLiteral("t")).toString());
  tag.arrayLen = qBound(1, obj.value(QStringLiteral("n")).toInt(1), OpcUaWire::kMaxTags);
  tag.min      = SerialStudio::toDouble(obj.value(QStringLiteral("min")));
  tag.max      = SerialStudio::toDouble(obj.value(QStringLiteral("max")));
  return tag;
}

sonObject IO::Drivers::OpcUa::tagToJson(const OpcUaTag& tag)
{
  return QJsonObject{
    {QStringLiteral("id"), tag.nodeId},
    {QStringLiteral("name"), tag.name},
    {QStringLiteral("path"), tag.path},
    {QStringLiteral("unit"), tag.unit},
    {QStringLiteral("t"), OpcUaWire::codeFromType(wireTypeFor(tag))},
    {QStringLiteral("n"), qMax(1, tag.arrayLen)},
    {QStringLiteral("min"), tag.min},
    {QStringLiteral("max"), tag.max},
  };
}

ist<IO::DriverProperty> IO::Drivers::OpcUa::driverProperties() const
{
  QList<IO::DriverProperty> props;

  IO::DriverProperty url;
  url.key   = QStringLiteral("endpointUrl");
  url.label = tr("Endpoint URL");
  url.type  = IO::DriverProperty::Text;
  url.value = selectedEndpointUrl();
  props.append(url);

  IO::DriverProperty auth;
  auth.key     = QStringLiteral("authMode");
  auth.label   = tr("Authentication");
  auth.type    = IO::DriverProperty::ComboBox;
  auth.value   = m_authMode;
  auth.options = authModeList();
  props.append(auth);

  IO::DriverProperty user;
  user.key   = QStringLiteral("username");
  user.label = tr("Username");
  user.type  = IO::DriverProperty::Text;
  user.value = m_username;
  props.append(user);

  IO::DriverProperty pass;
  pass.key   = QStringLiteral("password");
  pass.label = tr("Password");
  pass.type  = IO::DriverProperty::Password;
  pass.value = m_password;
  props.append(pass);

  IO::DriverProperty interval;
  interval.key   = QStringLiteral("publishingInterval");
  interval.label = tr("Poll Interval (ms)");
  interval.type  = IO::DriverProperty::IntField;
  interval.value = m_publishingInterval;
  interval.min   = kMinIntervalMs;
  interval.max   = kMaxIntervalMs;
  props.append(interval);

  IO::DriverProperty tags;
  tags.key   = QStringLiteral("tags");
  tags.type  = IO::DriverProperty::Text;
  tags.value = QVariant::fromValue(tagsJson());
  props.append(tags);

  return props;
}

id IO::Drivers::OpcUa::setDriverProperty(const QString& key, const QVariant& value)
{
  if (key == QLatin1String("endpointUrl")) {
    setEndpointUrl(value.toString());
    return;
  }

  if (key == QLatin1String("authMode")) {
    setAuthMode(value.toInt());
    return;
  }

  if (key == QLatin1String("username")) {
    setUsername(value.toString());
    return;
  }

  if (key == QLatin1String("password")) {
    setPassword(value.toString());
    return;
  }

  if (key == QLatin1String("publishingInterval")) {
    setPublishingInterval(value.toInt());
    return;
  }

  if (key != QLatin1String("tags"))
    return;

  QJsonArray array;
  if (value.canConvert<QJsonArray>())
    array = value.toJsonArray();
  else if (value.typeId() == QMetaType::QVariantList) {
    const auto list = value.toList();
    for (const auto& item : list)
      array.append(QJsonValue::fromVariant(item));
  }

  setTags(array);
}

::Drivers::OpcUaTagModel::OpcUaTagModel(QObject* parent)
  : QAbstractItemModel(parent)
  , m_client(nullptr)
  , m_root(std::make_unique<Node>())
  , m_unitsInFlight(0)
  , m_probesInFlight(0)
  , m_pendingBrowses(0)
  , m_lastBusy(false)
{
  m_root->folder     = true;
  m_root->expandable = true;
  m_root->nodeId     = QString::fromLatin1(kObjectsFolder);
  m_root->name       = QStringLiteral("Objects");
}

id IO::Drivers::OpcUaTagModel::setClient(QOpcUaClient* client)
{
  if (m_client == client)
    return;

  if (m_client)
    disconnect(m_client, nullptr, this, nullptr);

  m_client = client;
  clear();

  if (!m_client)
    return;

  connect(m_client,
          &QOpcUaClient::readNodeAttributesFinished,
          this,
          &IO::Drivers::OpcUaTagModel::onAttributesRead);
  (void)m_client->updateNamespaceArray();
}

id IO::Drivers::OpcUaTagModel::clear()
{
  for (auto* handle : m_handles)
    retireHandle(handle);

  m_handles.clear();
  m_pendingReads.clear();
  m_probeQueue.clear();
  m_unitQueue.clear();
  m_index.clear();
  m_unitsInFlight  = 0;
  m_probesInFlight = 0;
  m_pendingBrowses = 0;

  beginResetModel();
  m_root->children.clear();
  m_root->fetched  = false;
  m_root->fetching = false;
  m_root->checked  = false;
  endResetModel();

  publishBusy();
  Q_EMIT selectionChanged();
}

id IO::Drivers::OpcUaTagModel::publishBusy()
{
  const bool now = busy();
  if (now == m_lastBusy)
    return;

  m_lastBusy = now;
  Q_EMIT busyChanged();
}

::Drivers::OpcUaTagModel::Node* IO::Drivers::OpcUaTagModel::nodeAt(const QModelIndex& index) const
{
  if (!index.isValid())
    return m_root.get();

  auto* node = static_cast<Node*>(index.internalPointer());
  SS_ASSERT(node != nullptr, return m_root.get());
  return node;
}

odelIndex IO::Drivers::OpcUaTagModel::indexOf(Node* node) const
{
  SS_ASSERT(node != nullptr, return {});
  if (node == m_root.get() || !node->parent)
    return {};

  return createIndex(node->row, 0, node);
}

odelIndex IO::Drivers::OpcUaTagModel::index(int row, int column, const QModelIndex& parent) const
{
  if (column != 0 || row < 0)
    return {};

  const Node* node = nodeAt(parent);
  if (static_cast<size_t>(row) >= node->children.size())
    return {};

  return createIndex(row, 0, node->children[row].get());
}

odelIndex IO::Drivers::OpcUaTagModel::parent(const QModelIndex& child) const
{
  if (!child.isValid())
    return {};

  const Node* node = nodeAt(child);
  return indexOf(node->parent);
}

t IO::Drivers::OpcUaTagModel::columnCount(const QModelIndex& parent) const
{
  Q_UNUSED(parent)
  return 1;
}

ol IO::Drivers::OpcUaTagModel::hasChildren(const QModelIndex& parent) const
{
  const Node* node = nodeAt(parent);
  if (node->fetched)
    return !node->children.empty();

  return node->expandable;
}

ol IO::Drivers::OpcUaTagModel::canFetchMore(const QModelIndex& parent) const
{
  const Node* node = nodeAt(parent);
  return m_client && node->expandable && !node->fetched && !node->fetching;
}

id IO::Drivers::OpcUaTagModel::fetchMore(const QModelIndex& parent)
{
  if (canFetchMore(parent))
    browse(nodeAt(parent));
}

ash<int, QByteArray> IO::Drivers::OpcUaTagModel::roleNames() const
{
  static const QHash<int, QByteArray> k_roles = {
    {       NameRole,        "name"},
    {     NodeIdRole,      "nodeId"},
    {   TypeCodeRole,    "typeCode"},
    {     AccessRole,      "access"},
    {    CheckedRole,     "checked"},
    { SelectableRole,  "selectable"},
    {     FolderRole,      "folder"},
    {   ArrayLenRole,    "arrayLen"},
    {DescriptionRole, "description"},
    {       UnitRole,        "unit"},
    {Qt::DisplayRole,     "display"},
  };

  return k_roles;
}

ariant IO::Drivers::OpcUaTagModel::data(const QModelIndex& index, int role) const
{
  if (!index.isValid())
    return {};

  const Node* node = nodeAt(index);
  switch (role) {
    case Qt::DisplayRole:
    case NameRole:
      return node->name;
    case NodeIdRole:
      return node->nodeId;
    case TypeCodeRole:
      return node->folder ? QString() : OpcUaWire::codeFromType(node->type);
    case AccessRole:
      return node->folder ? QString() : (node->readable ? tr("read") : tr("no read"));
    case SelectableRole:
      return selectable(node);
    case FolderRole:
      return node->folder;
    case ArrayLenRole:
      return node->arrayLen;
    case DescriptionRole:
      return node->description;
    case UnitRole:
      return node->unit;
    case CheckedRole: {
      if (!node->folder)
        return node->checked ? 2 : 0;

      int checked = 0, selectableCount = 0;
      countSelectable(node, checked, selectableCount);
      if (checked == 0)
        return node->checked ? 2 : 0;

      return checked == selectableCount ? 2 : 1;
    }
    default:
      return {};
  }
}

ol IO::Drivers::OpcUaTagModel::setData(const QModelIndex& index, const QVariant& value, int role)
{
  if (!index.isValid() || role != CheckedRole)
    return false;

  setChecked(index, value.toBool());
  return true;
}

ol IO::Drivers::OpcUaTagModel::selectable(const Node* node) const noexcept
{
  SS_ASSERT(node != nullptr, return false);
  return !node->folder && node->readable && node->type != OpcUaWire::Type::Invalid;
}

id IO::Drivers::OpcUaTagModel::setChecked(const QModelIndex& index, const bool checked)
{
  Node* node = nodeAt(index);
  if (node == m_root.get() && !index.isValid())
    return;

  if (!node->folder) {
    if (!selectable(node) || node->checked == checked)
      return;

    node->checked = checked;
    if (checked)
      queueUnits(node);
    else
      for (Node* up = node->parent; up; up = up->parent)
        up->checked = false;
  } else {
    node->checked = checked;
    applySelectAll(node);
  }

  Q_EMIT dataChanged(index, index, {CheckedRole});
  for (Node* up = node->parent; up && up != m_root.get(); up = up->parent) {
    const auto upIndex = indexOf(up);
    Q_EMIT dataChanged(upIndex, upIndex, {CheckedRole});
  }

  Q_EMIT selectionChanged();
}

id IO::Drivers::OpcUaTagModel::applySelectAll(Node* node)
{
  SS_ASSERT(node != nullptr, return);
  SS_ASSERT(node->folder, return);

  for (auto& child : node->children) {
    if (child->folder) {
      child->checked = node->checked;
      applySelectAll(child.get());
      continue;
    }

    const bool tick = node->checked && selectable(child.get());
    if (tick && !child->checked)
      queueUnits(child.get());

    child->checked = tick;
  }

  if (node->children.empty())
    return;

  const auto first = indexOf(node->children.front().get());
  const auto last  = indexOf(node->children.back().get());
  Q_EMIT dataChanged(first, last, {CheckedRole});
}

id IO::Drivers::OpcUaTagModel::selectAllReadable()
{
  m_root->checked = true;
  applySelectAll(m_root.get());
  Q_EMIT selectionChanged();
}

id IO::Drivers::OpcUaTagModel::countSelectable(const Node* node,
                                                 int& checked,
                                                 int& selectableCount) const
{
  SS_ASSERT(node != nullptr, return);
  for (const auto& child : node->children) {
    if (child->folder) {
      countSelectable(child.get(), checked, selectableCount);
      continue;
    }

    if (!selectable(child.get()))
      continue;

    ++selectableCount;
    if (child->checked)
      ++checked;
  }
}

id IO::Drivers::OpcUaTagModel::countSelected(const Node* node, int& count, int& indices) const
{
  SS_ASSERT(node != nullptr, return);
  for (const auto& child : node->children) {
    if (child->folder)
      countSelected(child.get(), count, indices);
    else if (child->checked) {
      ++count;
      indices += qMax(1, child->arrayLen);
    }
  }
}

t IO::Drivers::OpcUaTagModel::selectedCount() const
{
  int count = 0, indices = 0;
  countSelected(m_root.get(), count, indices);
  return count;
}

t IO::Drivers::OpcUaTagModel::selectedIndices() const
{
  int count = 0, indices = 0;
  countSelected(m_root.get(), count, indices);
  return indices;
}

id IO::Drivers::OpcUaTagModel::collectSelected(const Node* node, QList<OpcUaTag>& out) const
{
  SS_ASSERT(node != nullptr, return);
  for (const auto& child : node->children) {
    if (child->folder) {
      collectSelected(child.get(), out);
      continue;
    }

    if (!child->checked)
      continue;

    OpcUaTag tag;
    tag.nodeId   = child->nodeId;
    tag.name     = child->name;
    tag.path     = child->path;
    tag.unit     = child->unit;
    tag.type     = child->type;
    tag.arrayLen = child->arrayLen;
    tag.min      = child->euMin;
    tag.max      = child->euMax;
    out.append(tag);
  }
}

ist<IO::Drivers::OpcUaTag> IO::Drivers::OpcUaTagModel::selectedTags() const
{
  QList<OpcUaTag> out;
  collectSelected(m_root.get(), out);
  return out;
}

::Drivers::OpcUaTagModel::Node* IO::Drivers::OpcUaTagModel::findNode(Node* from,
                                                                       const QString& nodeId) const
{
  SS_ASSERT(from != nullptr, return nullptr);
  if (from->nodeId == nodeId)
    return from;

  return m_index.value(nodeId, nullptr);
}

ol IO::Drivers::OpcUaTagModel::hasSeen(const QString& nodeId) const
{
  SS_ASSERT_LOG(!nodeId.isEmpty());
  return findNode(m_root.get(), nodeId) != nullptr;
}

sonArray IO::Drivers::OpcUaTagModel::childrenJson(const QString& nodeId) const
{
  QJsonArray out;
  const Node* node = nodeId.isEmpty() ? m_root.get() : findNode(m_root.get(), nodeId);
  if (!node)
    return out;

  for (const auto& child : node->children) {
    out.append(QJsonObject{
      {         QStringLiteral("id"),                                                    child->nodeId},
      {       QStringLiteral("name"),                                                      child->name},
      {     QStringLiteral("folder"),                                                    child->folder},
      { QStringLiteral("expandable"),                                                child->expandable},
      {          QStringLiteral("t"), child->folder ? QString() : OpcUaWire::codeFromType(child->type)},
      {   QStringLiteral("readable"),                                                  child->readable},
      { QStringLiteral("selectable"),                                          selectable(child.get())},
      {          QStringLiteral("n"),                                                  child->arrayLen},
      {       QStringLiteral("unit"),                                                      child->unit},
      {       QStringLiteral("path"),                                                      child->path},
      {QStringLiteral("description"),                                               child->description},
      {    QStringLiteral("fetched"),                                                   child->fetched},
    });
  }

  return out;
}

ol IO::Drivers::OpcUaTagModel::fetchNode(const QString& nodeId)
{
  if (!m_client)
    return false;

  Node* node = nodeId.isEmpty() ? m_root.get() : findNode(m_root.get(), nodeId);
  if (!node)
    return false;

  if (node->fetched || node->fetching)
    return true;

  browse(node);
  return true;
}

tring IO::Drivers::OpcUaTagModel::resolveNodeId(const QOpcUaExpandedNodeId& id) const
{
  const auto uri = id.namespaceUri();
  if (uri.isEmpty() || !m_client)
    return id.nodeId();

  const int index = m_client->namespaceArray().indexOf(uri);
  if (index < 0)
    return id.nodeId();

  const auto identifier = id.nodeId().section(QLatin1Char(';'), 1);
  if (identifier.isEmpty())
    return id.nodeId();

  return QStringLiteral("ns=%1;%2").arg(QString::number(index), identifier);
}

id IO::Drivers::OpcUaTagModel::browse(Node* node)
{
  SS_ASSERT(node != nullptr, return);
  if (!m_client || node->fetching || node->fetched)
    return;

  int depth = 0;
  for (const Node* up = node; up; up = up->parent)
    ++depth;

  if (depth > kMaxDepth)
    return;

  auto* handle = m_client->node(node->nodeId);
  if (!handle) {
    Q_EMIT browseError(node->nodeId, tr("invalid node id"));
    return;
  }

  node->fetching = true;
  ++m_pendingBrowses;
  handle->setParent(this);
  m_handles.append(handle);
  connect(handle,
          &QOpcUaNode::browseFinished,
          this,
          [this, node, handle](const QList<QOpcUaReferenceDescription>& children,
                               QOpcUa::UaStatusCode status) {
            onBrowseFinished(node, children, status);
            m_handles.removeOne(handle);
            retireHandle(handle);
          });

  if (!handle->browseChildren(QOpcUa::ReferenceTypeId::HierarchicalReferences,
                              QOpcUa::NodeClass::Object | QOpcUa::NodeClass::Variable)) {
    m_handles.removeOne(handle);
    retireHandle(handle);
    onBrowseFinished(node, {}, QOpcUa::UaStatusCode::BadInternalError);
  }

  publishBusy();
}

d::unique_ptr<IO::Drivers::OpcUaTagModel::Node> IO::Drivers::OpcUaTagModel::makeChild(
  Node* parent, const QOpcUaReferenceDescription& ref) const
{
  SS_ASSERT(parent != nullptr, return std::make_unique<Node>());

  auto child        = std::make_unique<Node>();
  child->parent     = parent;
  child->row        = static_cast<int>(parent->children.size());
  child->folder     = ref.nodeClass() != QOpcUa::NodeClass::Variable;
  child->expandable = child->folder;
  child->nodeId     = resolveNodeId(ref.targetNodeId());
  child->name =
    ref.displayName().text().isEmpty() ? ref.browseName().name() : ref.displayName().text();
  child->path =
    parent == m_root.get() ? parent->name : parent->path + QLatin1Char('/') + parent->name;

  if (parent->checked && parent->folder)
    child->inherited = true;

  child->checked = isPreselected(child->nodeId);

  return child;
}

id IO::Drivers::OpcUaTagModel::onBrowseFinished(Node* node,
                                                  const QList<QOpcUaReferenceDescription>& children,
                                                  QOpcUa::UaStatusCode status)
{
  SS_ASSERT(node != nullptr, return);
  node->fetching   = false;
  node->fetched    = true;
  m_pendingBrowses = qMax(0, m_pendingBrowses - 1);

  if (status != QOpcUa::UaStatusCode::Good) {
    Q_EMIT browseError(node->nodeId, QOpcUa::statusToString(status));
    publishBusy();
    return;
  }

  const auto parentIndex = indexOf(node);
  if (!children.isEmpty()) {
    beginInsertRows(parentIndex, 0, children.size() - 1);
    for (const auto& ref : children) {
      auto child = makeChild(node, ref);
      m_index.insert(child->nodeId, child.get());
      node->children.push_back(std::move(child));
    }
    endInsertRows();
  }

  readLevel(node);

  for (auto& child : node->children)
    queueProbe(child.get());

  expandPreselected(node);
  refreshAncestors(node);

  Q_EMIT dataChanged(parentIndex, parentIndex);
  Q_EMIT selectionChanged();
  publishBusy();
}

ol IO::Drivers::OpcUaTagModel::isPreselected(const QString& nodeId) const
{
  for (const auto& tag : m_preselected)
    if (tag.nodeId == nodeId)
      return true;

  return false;
}

tring IO::Drivers::OpcUaTagModel::pathOf(const Node* node) const
{
  SS_ASSERT(node != nullptr, return {});
  if (node == m_root.get())
    return node->name;

  return node->path + QLatin1Char('/') + node->name;
}

id IO::Drivers::OpcUaTagModel::expandPreselected(Node* node)
{
  SS_ASSERT(node != nullptr, return);
  if (m_preselected.isEmpty())
    return;

  for (auto& child : node->children) {
    if (!child->folder || child->fetched || child->fetching)
      continue;

    const auto branch = pathOf(child.get());
    for (const auto& tag : m_preselected) {
      if (tag.path != branch && !tag.path.startsWith(branch + QLatin1Char('/')))
        continue;

      Q_EMIT expandRequested(indexOf(child.get()));
      browse(child.get());
      break;
    }
  }
}

id IO::Drivers::OpcUaTagModel::readLevel(Node* node)
{
  SS_ASSERT(node != nullptr, return);
  if (!m_client)
    return;

  QList<QOpcUaReadItem> items;
  for (auto& child : node->children) {
    if (child->folder || child->attributesRead)
      continue;

    m_pendingReads.insert(child->nodeId, child.get());
    items.append(QOpcUaReadItem(child->nodeId, QOpcUa::NodeAttribute::DataType));
    items.append(QOpcUaReadItem(child->nodeId, QOpcUa::NodeAttribute::ValueRank));
    items.append(QOpcUaReadItem(child->nodeId, QOpcUa::NodeAttribute::ArrayDimensions));
    items.append(QOpcUaReadItem(child->nodeId, QOpcUa::NodeAttribute::AccessLevel));
    items.append(QOpcUaReadItem(child->nodeId, QOpcUa::NodeAttribute::UserAccessLevel));
    items.append(QOpcUaReadItem(child->nodeId, QOpcUa::NodeAttribute::Description));
    items.append(QOpcUaReadItem(child->nodeId, QOpcUa::NodeAttribute::Value));

    if (items.size() < kMaxNodesPerRead)
      continue;

    (void)m_client->readNodeAttributes(items);
    items.clear();
  }

  if (!items.isEmpty())
    (void)m_client->readNodeAttributes(items);
}

id IO::Drivers::OpcUaTagModel::onAttributesRead(const QList<QOpcUaReadResult>& results,
                                                  QOpcUa::UaStatusCode status)
{
  Q_UNUSED(status)

  QList<Node*> touched;
  for (const auto& result : results) {
    Node* node = m_pendingReads.value(result.nodeId(), nullptr);
    if (!node)
      continue;

    applyAttribute(node, result.attribute(), result.value(), result.statusCode());
    if (!touched.contains(node))
      touched.append(node);
  }

  for (auto* node : touched) {
    m_pendingReads.remove(node->nodeId);
    finishAttributes(node);
  }

  if (!touched.isEmpty())
    Q_EMIT selectionChanged();

  publishBusy();
}

id IO::Drivers::OpcUaTagModel::applyAttribute(Node* node,
                                                QOpcUa::NodeAttribute attribute,
                                                const QVariant& value,
                                                QOpcUa::UaStatusCode status)
{
  SS_ASSERT(node != nullptr, return);
  if (status != QOpcUa::UaStatusCode::Good)
    return;

  switch (attribute) {
    case QOpcUa::NodeAttribute::DataType:
      node->type = wireTypeFromDataTypeId(value.toString());
      break;
    case QOpcUa::NodeAttribute::Description:
      node->description = value.canConvert<QOpcUaLocalizedText>()
                          ? value.value<QOpcUaLocalizedText>().text()
                          : value.toString();
      break;
    case QOpcUa::NodeAttribute::AccessLevel:
    case QOpcUa::NodeAttribute::UserAccessLevel:
      node->readable =
        (value.toUInt() & static_cast<quint32>(QOpcUa::AccessLevelBit::CurrentRead)) != 0;
      break;
    case QOpcUa::NodeAttribute::ArrayDimensions: {
      const auto dims = value.toList();
      if (!dims.isEmpty())
        node->arrayLen = qBound(1, dims.first().toInt(), OpcUaWire::kMaxTags);

      break;
    }
    case QOpcUa::NodeAttribute::Value: {
      if (node->type == OpcUaWire::Type::Invalid)
        node->type = wireTypeFromValue(value);

      if (value.typeId() == QMetaType::QVariantList && node->arrayLen <= 1)
        node->arrayLen = qBound(1, static_cast<int>(value.toList().size()), OpcUaWire::kMaxTags);

      break;
    }
    default:
      break;
  }
}

id IO::Drivers::OpcUaTagModel::refreshAncestors(Node* node)
{
  SS_ASSERT(node != nullptr, return);
  for (Node* up = node; up && up != m_root.get(); up = up->parent) {
    const auto index = indexOf(up);
    Q_EMIT dataChanged(index, index, {CheckedRole});
  }
}

id IO::Drivers::OpcUaTagModel::finishAttributes(Node* node)
{
  SS_ASSERT(node != nullptr, return);
  node->attributesRead = true;

  if (!selectable(node))
    node->checked = false;
  else if (!node->checked)
    node->checked = isPreselected(node->nodeId);
  else if (node->inherited && !node->checked) {
    node->checked   = true;
    node->inherited = false;
    queueUnits(node);
  }

  const auto index = indexOf(node);
  Q_EMIT dataChanged(index, index);
  refreshAncestors(node->parent);
}

id IO::Drivers::OpcUaTagModel::queueProbe(Node* node)
{
  SS_ASSERT(node != nullptr, return);
  if (node->probed || node->probing || node->fetched || m_probeQueue.contains(node))
    return;

  m_probeQueue.enqueue(node);
  pumpProbeQueue();
}

id IO::Drivers::OpcUaTagModel::pumpProbeQueue()
{
  while (m_client && m_probesInFlight < kMaxProbesInFlight && !m_probeQueue.isEmpty()) {
    Node* node = m_probeQueue.dequeue();
    if (!node || node->probed || node->fetched)
      continue;

    auto* handle = m_client->node(node->nodeId);
    if (!handle) {
      node->probed     = true;
      node->expandable = false;
      continue;
    }

    ++m_probesInFlight;
    node->probing = true;
    handle->setParent(this);
    m_handles.append(handle);
    connect(handle,
            &QOpcUaNode::browseFinished,
            this,
            [this, node, handle](const QList<QOpcUaReferenceDescription>& children,
                                 QOpcUa::UaStatusCode status) {
              node->probing = false;
              node->probed  = true;
              if (status == QOpcUa::UaStatusCode::Good && !node->fetched)
                node->expandable = !children.isEmpty();

              const auto index = indexOf(node);
              Q_EMIT dataChanged(index, index);

              m_handles.removeOne(handle);
              retireHandle(handle);
              --m_probesInFlight;
              pumpProbeQueue();
            });

    if (!handle->browseChildren(QOpcUa::ReferenceTypeId::HierarchicalReferences,
                                QOpcUa::NodeClass::Object | QOpcUa::NodeClass::Variable)) {
      m_handles.removeOne(handle);
      retireHandle(handle);
      node->probing = false;
      --m_probesInFlight;
    }
  }
}

id IO::Drivers::OpcUaTagModel::queueUnits(Node* node)
{
  SS_ASSERT(node != nullptr, return);
  if (node->euResolved || m_unitQueue.contains(node))
    return;

  m_unitQueue.enqueue(node);
  pumpUnitQueue();
}

id IO::Drivers::OpcUaTagModel::pumpUnitQueue()
{
  while (m_client && m_unitsInFlight < kMaxUnitsInFlight && !m_unitQueue.isEmpty()) {
    Node* node = m_unitQueue.dequeue();
    if (!node || node->euResolved)
      continue;

    auto* handle = m_client->node(node->nodeId);
    if (!handle) {
      node->euResolved = true;
      continue;
    }

    ++m_unitsInFlight;
    node->euResolved = true;
    handle->setParent(this);
    m_handles.append(handle);
    connect(handle,
            &QOpcUaNode::browseFinished,
            this,
            [this, node, handle](const QList<QOpcUaReferenceDescription>& children,
                                 QOpcUa::UaStatusCode status) {
              if (status == QOpcUa::UaStatusCode::Good)
                onUnitsBrowsed(node, children);

              m_handles.removeOne(handle);
              retireHandle(handle);
              --m_unitsInFlight;
              pumpUnitQueue();
            });

    if (!handle->browseChildren(QOpcUa::ReferenceTypeId::HasProperty,
                                QOpcUa::NodeClass::Variable)) {
      m_handles.removeOne(handle);
      retireHandle(handle);
      --m_unitsInFlight;
    }
  }
}

id IO::Drivers::OpcUaTagModel::onUnitsBrowsed(Node* node,
                                                const QList<QOpcUaReferenceDescription>& children)
{
  SS_ASSERT(node != nullptr, return);
  if (!m_client)
    return;

  for (const auto& ref : children) {
    const auto name = ref.browseName().name();
    if (name != QLatin1String("EngineeringUnits") && name != QLatin1String("EURange"))
      continue;

    auto* handle = m_client->node(resolveNodeId(ref.targetNodeId()));
    if (!handle)
      continue;

    handle->setParent(this);
    m_handles.append(handle);
    connect(handle, &QOpcUaNode::attributeRead, this, [this, node, handle](QOpcUa::NodeAttributes) {
      const auto value = handle->attribute(QOpcUa::NodeAttribute::Value);
      if (value.canConvert<QOpcUaEUInformation>())
        node->unit = value.value<QOpcUaEUInformation>().displayName().text();

      else if (value.canConvert<QOpcUaRange>()) {
        node->euMin = value.value<QOpcUaRange>().low();
        node->euMax = value.value<QOpcUaRange>().high();
      }

      const auto index = indexOf(node);
      Q_EMIT dataChanged(index, index, {UnitRole});
      m_handles.removeOne(handle);
      retireHandle(handle);
    });

    if (!handle->readAttributes(QOpcUa::NodeAttribute::Value)) {
      m_handles.removeOne(handle);
      retireHandle(handle);
    }
  }
}

id IO::Drivers::OpcUaTagModel::retireHandle(QOpcUaNode* handle)
{
  if (!handle)
    return;

  disconnect(handle, nullptr, this, nullptr);
  handle->deleteLater();
}

::Drivers::OpcUaWire::Type IO::Drivers::OpcUaTagModel::wireTypeFromValue(
  const QVariant& value) noexcept
{
  using OpcUaWire::Type;

  auto probe = value;
  if (probe.typeId() == QMetaType::QVariantList) {
    const auto list = probe.toList();
    if (list.isEmpty())
      return Type::Invalid;

    probe = list.first();
  }

  switch (probe.typeId()) {
    case QMetaType::Bool:
      return Type::Bool;
    case QMetaType::SChar:
      return Type::I8;
    case QMetaType::UChar:
      return Type::U8;
    case QMetaType::Short:
      return Type::I16;
    case QMetaType::UShort:
      return Type::U16;
    case QMetaType::Int:
      return Type::I32;
    case QMetaType::UInt:
      return Type::U32;
    case QMetaType::LongLong:
      return Type::I64;
    case QMetaType::ULongLong:
      return Type::U64;
    case QMetaType::Float:
      return Type::F32;
    case QMetaType::Double:
      return Type::F64;
    case QMetaType::QString:
    case QMetaType::QDateTime:
    case QMetaType::QUuid:
    case QMetaType::QByteArray:
      return Type::Str;
    default:
      break;
  }

  if (probe.canConvert<QOpcUaLocalizedText>())
    return Type::Str;

  return Type::Invalid;
}

[[nodiscard]] static QJsonObject parseOpcUaTagSpec(const QString& spec)
{
  using IO::Drivers::OpcUaWire::Type;
  using IO::Drivers::OpcUaWire::typeFromCode;

  QString id   = spec;
  QString type = QStringLiteral("f64");
  QString name;
  QString unit;
  int arrayLen = 1;

  auto body = spec;
  for (int guard = 0; guard < 4; ++guard) {
    const auto tail = body.section(QLatin1Char(':'), -1);
    if (tail.startsWith(QLatin1String("n=")) && tail.mid(2).toInt() > 0) {
      arrayLen = tail.mid(2).toInt();
      body     = body.section(QLatin1Char(':'), 0, -2);
      continue;
    }

    if (tail.startsWith(QLatin1String("unit="))) {
      unit = tail.mid(5);
      body = body.section(QLatin1Char(':'), 0, -2);
      continue;
    }

    break;
  }

  id               = body;
  const auto parts = body.split(QLatin1Char(':'));
  if (parts.size() >= 3 && typeFromCode(parts.at(parts.size() - 2)) != Type::Invalid) {
    name = parts.last();
    type = parts.at(parts.size() - 2);
    id   = parts.mid(0, parts.size() - 2).join(QLatin1Char(':'));
  } else if (parts.size() >= 2 && typeFromCode(parts.last()) != Type::Invalid) {
    type = parts.last();
    id   = parts.mid(0, parts.size() - 1).join(QLatin1Char(':'));
  } else if (parts.size() >= 2) {
    return {};
  }

  if (id.isEmpty())
    return {};

  QJsonObject tag;
  tag[QStringLiteral("id")]   = id;
  tag[QStringLiteral("t")]    = type;
  tag[QStringLiteral("n")]    = arrayLen;
  tag[QStringLiteral("unit")] = unit;
  tag[QStringLiteral("name")] = name.isEmpty() ? id : name;
  return tag;
}

void CLI::setupOpcUaConnection()
{
  const QString url = m_parser.value(m_opts.opcuaOpt);
  if (!url.startsWith(QLatin1String("opc.tcp://"))) {
    qWarning() << "Invalid OPC UA endpoint. Expected: opc.tcp://host[:port][/path]";
    return;
  }

  static auto& connectionManager = IO::ConnectionManager::instance();
  auto* opcua                    = connectionManager.opcUa();
  connectionManager.setBusType(SerialStudio::BusType::OpcUa);
  opcua->setEndpointUrl(url);

  if (m_parser.isSet(m_opts.opcuaUserOpt)) {
    opcua->setAuthMode(1);
    opcua->setUsername(m_parser.value(m_opts.opcuaUserOpt));
    if (m_parser.isSet(m_opts.opcuaPassOpt))
      opcua->setPassword(m_parser.value(m_opts.opcuaPassOpt));
  } else {
    opcua->setAuthMode(0);
  }

  if (m_parser.isSet(m_opts.opcuaIntervalOpt)) {
    bool ok            = false;
    const int interval = m_parser.value(m_opts.opcuaIntervalOpt).toInt(&ok);
    if (ok && interval >= 10 && interval <= 60000)
      opcua->setPublishingInterval(interval);
    else
      qWarning() << "Invalid OPC UA interval (10-60000 ms):"
                 << m_parser.value(m_opts.opcuaIntervalOpt);
  }

  QJsonArray tags;
  const auto specs = m_parser.values(m_opts.opcuaTagOpt);
  for (const auto& spec : specs) {
    const auto tag = parseOpcUaTagSpec(spec);
    if (tag.isEmpty())
      qWarning() << "Invalid OPC UA tag spec (nodeId[:type[:name]], known type code):" << spec;
    else
      tags.append(tag);
  }

  if (tags.isEmpty()) {
    qWarning() << "No OPC UA tags given (--opcua-tag); nothing to subscribe to";
    return;
  }

  opcua->setTags(tags);

  if (!m_parser.isSet(m_opts.projectOpt) && !opcua->loadGeneratedProject())
    qWarning() << "Could not generate a project for the OPC UA tags";

  connectionManager.connectDevice();
}

void UI::Taskbar::applySavedWindowStates(const QJsonObject& layout)
{
  if (!m_windowManager)
    return;

  const auto states = m_windowManager->savedWindowStates(layout);
  if (states.isEmpty())
    return;

  for (auto it = states.cbegin(); it != states.cend(); ++it) {
    QStandardItem* item = findItemByWindowId(it.key());
    if (!item)
      continue;

    auto state = TaskbarModel::WindowNormal;
    if (it.value() == QStringLiteral("minimized"))
      state = TaskbarModel::WindowMinimized;
    else if (it.value() == QStringLiteral("closed"))
      state = TaskbarModel::WindowClosed;

    item->setData(state, TaskbarModel::WindowStateRole);
  }

  Q_EMIT windowStatesChanged();
  m_windowManager->triggerLayoutUpdate();
}

QMap<int, QString> UI::WindowManager::savedWindowStates(const QJsonObject& layout) const
{
  QMap<int, QString> states;
  if (layout.isEmpty() || !layout.contains("geometries"))
    return states;

  const QHash<StableKey, int> stableLookup = buildStableKeyToWindowId();
  const QJsonArray geometries              = layout["geometries"].toArray();

  for (const auto& val : std::as_const(geometries)) {
    const QJsonObject winGeom = val.toObject();
    const int id              = resolveSavedWindowId(winGeom, stableLookup, m_windows);
    const QString state       = winGeom.value("state").toString();
    if (id < 0 || state.isEmpty())
      continue;

    states.insert(id, state);
  }

  return states;
}

nodiscard]] static QJsonObject schemaParams(const QStringList& codes)
{
  QJsonArray schema;
  for (int i = 0; i < codes.size(); ++i)
    schema.append(QJsonObject{
      {QStringLiteral("i"),        i},
      {QStringLiteral("t"), codes[i]}
    });

  return QJsonObject{
    {QStringLiteral("schema"), schema}
  };
}

nodiscard]] static QByteArray frameOf(const QList<std::tuple<int, Type, QVariant>>& entries)
{
  QByteArray out;
  out.reserve(kHeaderBytes + entries.size() * maxEntryBytes(Type::Str));
  beginFrame(out);
  for (const auto& [index, type, value] : entries)
    appendEntry(out, index, type, value);

  return out;
}

id TstOpcUaWire::typeCodesRoundTrip()
{
  const QStringList codes = {
    "bool", "i8", "u8", "i16", "u16", "i32", "u32", "i64", "u64", "f32", "f64", "str"};
  for (const auto& code : codes) {
    const Type type = typeFromCode(code);
    QVERIFY(type != Type::Invalid);
    QCOMPARE(codeFromType(type), code);
  }

  QCOMPARE(typeFromCode(QStringLiteral("nope")), Type::Invalid);
  QVERIFY(codeFromType(Type::Invalid).isEmpty());
}

id TstOpcUaWire::scalarsRoundTrip_data()
{
  QTest::addColumn<int>("type");
  QTest::addColumn<QVariant>("value");
  QTest::addColumn<QString>("text");

  QTest::newRow("bool") << int(Type::Bool) << QVariant(true) << QStringLiteral("1");
  QTest::newRow("i8") << int(Type::I8) << QVariant(-100) << QStringLiteral("-100");
  QTest::newRow("u8") << int(Type::U8) << QVariant(200) << QStringLiteral("200");
  QTest::newRow("i16") << int(Type::I16) << QVariant(-32000) << QStringLiteral("-32000");
  QTest::newRow("u16") << int(Type::U16) << QVariant(65535) << QStringLiteral("65535");
  QTest::newRow("i32") << int(Type::I32) << QVariant(-2000000000) << QStringLiteral("-2000000000");
  QTest::newRow("u32") << int(Type::U32) << QVariant(4000000000u) << QStringLiteral("4000000000");
  QTest::newRow("i64") << int(Type::I64) << QVariant(qint64(-9000000000000000000LL))
                       << QStringLiteral("-9000000000000000000");
  QTest::newRow("u64") << int(Type::U64) << QVariant(quint64(18000000000000000000ULL))
                       << QStringLiteral("18000000000000000000");
  QTest::newRow("f32") << int(Type::F32) << QVariant(1.5f) << QStringLiteral("1.5");
  QTest::newRow("f64") << int(Type::F64) << QVariant(3.25) << QStringLiteral("3.25");
}

id TstOpcUaWire::scalarsRoundTrip()
{
  QFETCH(int, type);
  QFETCH(QVariant, value);
  QFETCH(QString, text);

  const auto wire  = static_cast<Type>(type);
  const auto frame = frameOf({
    {7, wire, value}
  });
  QCOMPARE(frame.size(), kHeaderBytes + kEntryHeaderBytes + payloadWidth(wire));

  qsizetype pos = kHeaderBytes;
  Entry entry;
  QVERIFY(readEntry(frame, pos, entry));
  QCOMPARE(entry.index, 7);
  QCOMPARE(entry.type, wire);
  QCOMPARE(entry.text, text);
  QCOMPARE(pos, frame.size());
}

id TstOpcUaWire::stringsTruncateAtCap()
{
  const QString text(kMaxStringBytes + 50, QLatin1Char('x'));
  const auto frame = frameOf({
    {3, Type::Str, text}
  });
  QCOMPARE(frame.size(), kHeaderBytes + kEntryHeaderBytes + 2 + kMaxStringBytes);

  qsizetype pos = kHeaderBytes;
  Entry entry;
  QVERIFY(readEntry(frame, pos, entry));
  QCOMPARE(entry.text.size(), kMaxStringBytes);
  QCOMPARE(entry.type, Type::Str);
}

id TstOpcUaWire::truncatedEntryStopsWalk()
{
  auto frame = frameOf({
    {0, Type::U16,   1},
    {1, Type::F64, 2.0}
  });
  frame.chop(3);

  qsizetype pos = kHeaderBytes;
  Entry entry;
  QVERIFY(readEntry(frame, pos, entry));
  QCOMPARE(entry.index, 0);

  const qsizetype before = pos;
  QVERIFY(!readEntry(frame, pos, entry));
  QCOMPARE(pos, before);
}

id TstOpcUaWire::badVersionRejected()
{
  auto frame = frameOf({
    {0, Type::Bool, true}
  });
  QVERIFY(checkHeader(frame));

  frame[0] = static_cast<char>(kWireVersion + 1);
  QVERIFY(!checkHeader(frame));
  QVERIFY(!checkHeader(QByteArray()));
}

id TstOpcUaWire::templateLatchesDeltas()
{
  const auto* tmpl = DataModel::nativeTemplateById(QStringLiteral("opcua"));
  QVERIFY(tmpl != nullptr);

  QString error;
  auto parser = tmpl->makeParser(schemaParams({"f64", "bool", "str"}), error);
  QVERIFY2(parser != nullptr, qPrintable(error));

  auto row = firstRow(parser->parseBinary(frameOf({
    {0,  Type::F64,  21.5},
    {1, Type::Bool,  true},
    {2,  Type::Str, "RUN"}
  })));
  QCOMPARE(row, QStringList({"21.5", "1", "RUN"}));

  row = firstRow(parser->parseBinary(frameOf({
    {1, Type::Bool, false}
  })));
  QCOMPARE(row, QStringList({"21.5", "0", "RUN"}));

  auto bad = frameOf({
    {0, Type::F64, 99.0}
  });
  bad[0]   = static_cast<char>(kWireVersion + 1);
  row      = firstRow(parser->parseBinary(bad));
  QCOMPARE(row, QStringList({"21.5", "0", "RUN"}));
}

id TstOpcUaWire::templateIgnoresUnknownIndexAndTypeMismatch()
{
  const auto* tmpl = DataModel::nativeTemplateById(QStringLiteral("opcua"));
  QVERIFY(tmpl != nullptr);

  QString error;
  auto parser = tmpl->makeParser(schemaParams({"i32", "i32"}), error);
  QVERIFY2(parser != nullptr, qPrintable(error));

  auto row = firstRow(parser->parseBinary(frameOf({
    { 0, Type::I32,    5},
    { 1, Type::F32, 1.0f},
    {40, Type::I32,    9}
  })));
  QCOMPARE(row, QStringList({"5", "0"}));
}

id TstOpcUaWire::templateRejectsBadSchema()
{
  const auto* tmpl = DataModel::nativeTemplateById(QStringLiteral("opcua"));
  QVERIFY(tmpl != nullptr);

  QString error;
  QVERIFY(tmpl->makeParser(QJsonObject(), error) == nullptr);
  QVERIFY(!error.isEmpty());

  QVERIFY(tmpl->makeParser(schemaParams({"f64", "nope"}), error) == nullptr);

  QJsonArray schema{
    QJsonObject{{QStringLiteral("i"), 5}, {QStringLiteral("t"), "f64"}}
  };
  QVERIFY(tmpl->makeParser(
            QJsonObject{
              {QStringLiteral("schema"), schema}
  },
            error)
          == nullptr);
}

API::CommandResponse API::Handlers::CANBusHandler::setDataBitrate(const QString& id,
                                                                  const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("dataBitrate"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: dataBitrate"));
  }

  const int dataBitrate = params.value(QStringLiteral("dataBitrate")).toInt();

  if (dataBitrate <= 0) {
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("dataBitrate must be positive"));
  }

  static auto& connectionManager = IO::ConnectionManager::instance();
  connectionManager.canBus()->setDataBitrate(static_cast<quint32>(dataBitrate));

  QJsonObject result;
  result[QStringLiteral("dataBitrate")] = dataBitrate;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::CANBusHandler::setLoopback(const QString& id,
                                                               const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("enabled"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: enabled"));
  }

  const bool enabled             = params.value(QStringLiteral("enabled")).toBool();
  static auto& connectionManager = IO::ConnectionManager::instance();
  connectionManager.canBus()->setLoopback(enabled);

  QJsonObject result;
  result[QStringLiteral("enabled")] = enabled;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::CANBusHandler::setListenOnly(const QString& id,
                                                                 const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("enabled"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: enabled"));
  }

  const bool enabled             = params.value(QStringLiteral("enabled")).toBool();
  static auto& connectionManager = IO::ConnectionManager::instance();
  connectionManager.canBus()->setListenOnly(enabled);

  QJsonObject result;
  result[QStringLiteral("enabled")] = enabled;
  return CommandResponse::makeSuccess(id, result);
}

int CSV::Player::dataColumnToFileColumn(int i) const
{
  SS_ASSERT(i >= 0, return -1);

  switch (m_tsMode) {
    case PlayerTimestampMode::Interval:
      return i;
    case PlayerTimestampMode::DateTimeColumn:
      return (i < m_timestampColumn) ? i : i + 1;
    case PlayerTimestampMode::Numeric:
    case PlayerTimestampMode::DateTime:
      return i + 1;
  }

  return -1;
}

void CSV::Player::injectSourceRow(int row, int sourceId)
{
  SS_ASSERT(row >= 0, return);
  SS_ASSERT(row < frameCount(), return);

  if (m_injecting)
    return;

  const QScopedValueRollback<bool> reentry_guard(m_injecting, true);
  const qsizetype count = splitDataCells(row);
  if (count <= 0)
    return;

  const auto it = m_sourceColumnsByIndex.constFind(sourceId);
  if (it == m_sourceColumnsByIndex.constEnd())
    return;

  static auto& frameBuilder = DataModel::FrameBuilder::instance();
  const auto timestamp      = rowSteadyTimestamp(row);
  const auto& orderedCols   = it.value();
  QVarLengthArray<QByteArrayView, 64> cells;
  cells.reserve(orderedCols.size());
  for (int col : orderedCols)
    cells.append((col >= 0 && col < count) ? m_dataSpans.at(col) : QByteArrayView());

  frameBuilder.replayChannelSpans(sourceId, cells.constData(), cells.size(), timestamp);
}

void CSV::Player::backfillSparseSources()
{
  constexpr int kBackfillScanMax = 262144;

  if (!m_multiSource || m_bitSourceIds.isEmpty())
    return;

  const int last = qMin(m_framePos, static_cast<int>(m_rowSourceBits.size()) - 1);
  if (last < 0)
    return;

  for (int b = 0; b < m_bitSourceIds.size(); ++b) {
    const auto mask = static_cast<quint8>(1u << b);
    const int stop  = qMax(0, last - kBackfillScanMax);
    int found       = -1;
    for (int r = last; r >= stop; --r) {
      if (m_rowSourceBits.at(r) & mask) {
        found = r;
        break;
      }
    }

    if (found < 0 || found == m_lastSourceRow.value(b, -1))
      continue;

    m_lastSourceRow[b] = found;
    injectSourceRow(found, m_bitSourceIds.at(b));
  }
  // code-verify off
  // replayChannelSpans() marshals blocking and pumps this thread's event loop, so a queued
  // updateData() or close click can re-enter here and tear state down under the byte views the
  // outer call already handed to the builder.
  // code-verify on
  if (m_injecting)
    return;

  const QScopedValueRollback<bool> reentry_guard(m_injecting, true);

void DataModel::FrameBuilder::forgetPublishedStructures()
{
  if (QThread::currentThread() != thread()) {
    invokeOnBuilderThread([this] { forgetPublishedStructures(); });
    return;
  }

  m_publishedStructureGeneration.clear();
}

void DataModel::FrameBuilder::onPlayerOpenChanged()
{
  const bool wasOpen  = m_playerOpen;
  m_playerOpen        = SerialStudio::isAnyPlayerOpen();
  m_captureFlagsDirty = true;
  rebuildTransformsForPlayback();

  if (wasOpen && !m_playerOpen)
    releaseReplayPoolStorage();
}

void DataModel::FrameBuilder::releaseReplayPoolStorage()
{
  SS_ASSERT_LOG(QThread::currentThread() == thread());

  for (auto& slot : m_blockPool) {
    if (slot.use_count() != 1)
      continue;

    slot->block      = DataModel::DataBlock();
    slot->generation = 0;
    slot->sourceId   = -1;
  }

  for (auto& slot : m_framePool) {
    if (slot.use_count() != 1)
      continue;

    slot->frame      = DataModel::TimestampedFrame();
    slot->generation = 0;
    slot->matchedSrc = nullptr;
    slot->flat       = {};
  }

  m_poolPolicy.releaseOwnership();
}

QVector<quint8> MDF4::Player::buildChannelSourceBits()
{
  m_bitSourceIds.clear();

  static auto& appState = AppState::instance();
  if (appState.operationMode() != SerialStudio::ProjectFile)
    return {};

  QVector<quint8> bits;
  static auto& projectModel = DataModel::ProjectModel::instance();
  for (const auto& g : projectModel.groups()) {
    if (g.widget == QLatin1String("image"))
      continue;

    int bit = static_cast<int>(m_bitSourceIds.indexOf(g.sourceId));
    if (bit < 0 && m_bitSourceIds.size() < 8) {
      bit = m_bitSourceIds.size();
      m_bitSourceIds.append(g.sourceId);
    }

    for (int i = 0; i < static_cast<int>(g.datasets.size()); ++i)
      bits.append(bit >= 0 ? static_cast<quint8>(1u << bit) : quint8(0));
  }

  return bits;
}

void MDF4::Player::injectSourceRow(int frameIndex, int sourceId)
{
  SS_ASSERT(frameIndex >= 0, return);
  SS_ASSERT(frameIndex < frameCount(), return);

  if (m_injecting)
    return;

  const QScopedValueRollback<bool> reentry_guard(m_injecting, true);
  const qsizetype count = buildRowCellsTyped(frameIndex, m_typedCells);
  if (count <= 0)
    return;

  const auto it = m_sourceChannelsByIndex.constFind(sourceId);
  if (it == m_sourceChannelsByIndex.constEnd())
    return;

  static auto& frameBuilder = DataModel::FrameBuilder::instance();
  const auto timestamp      = rowSteadyTimestamp(frameIndex);
  const auto& orderedChs    = it.value();
  QVarLengthArray<DataModel::FrameBuilder::ReplayCell, 128> cells;
  cells.reserve(orderedChs.size());
  for (int ch : orderedChs) {
    static const QString kEmpty;
    DataModel::FrameBuilder::ReplayCell cell{&kEmpty, 0.0};
    if (ch >= 0 && ch < count)
      cell = m_typedCells.at(ch);

    cells.append(cell);
  }

  frameBuilder.replayChannelsTyped(sourceId, cells.constData(), cells.size(), timestamp);
}

void MDF4::Player::backfillSparseSources()
{
  constexpr int kBackfillScanMax = 262144;

  if (!m_multiSource || m_bitSourceIds.isEmpty())
    return;

  const int last = qMin(m_framePos, static_cast<int>(m_rowSourceBits.size()) - 1);
  if (last < 0)
    return;

  for (int b = 0; b < m_bitSourceIds.size(); ++b) {
    const auto mask = static_cast<quint8>(1u << b);
    const int stop  = qMax(0, last - kBackfillScanMax);
    int found       = -1;
    for (int r = last; r >= stop; --r) {
      if (m_rowSourceBits.at(r) & mask) {
        found = r;
        break;
      }
    }

    if (found < 0 || found == m_lastSourceRow.value(b, -1))
      continue;

    m_lastSourceRow[b] = found;
    injectSourceRow(found, m_bitSourceIds.at(b));
  }
}

static inline int probePoll(ProbePoll* fds, int timeoutMs)
{
#ifdef Q_OS_WIN
  return ::WSAPoll(fds, 1, timeoutMs);
#else
  return ::poll(fds, 1, timeoutMs);
#endif
}

void API::MirrorSession::publishStructures()
{
  auto& dashboard = m_ctx.dashboard();
  for (const auto& frame : m_frames) {
    auto structure        = std::make_shared<DataModel::StructureSnapshot>();
    structure->generation = frame->structureGeneration;
    structure->data       = frame->data;
    dashboard.applyStructureSnapshot(structure);
  }
}

DataModel::DataBlockPtr API::MirrorSession::buildSnapshotBlock(
  const DataModel::TimestampedFrame& frame) const
{
  auto block                 = std::make_shared<DataModel::DataBlock>();
  block->sourceId            = frame.data.sourceId;
  block->structureGeneration = frame.structureGeneration;
  block->samples             = 1;
  block->t0                  = frame.timestamp;
  block->times.assign(1, 0);

  for (const auto& group : frame.data.groups)
    for (const auto& dataset : group.datasets) {
      DataModel::BlockColumn column;
      column.uniqueId = dataset.uniqueId;
      column.hasText  = true;
      column.values.assign(1, dataset.numericValue);
      column.numeric.assign(1, dataset.isNumeric ? 1 : 0);
      column.text.assign(1, dataset.value);
      block->columns.push_back(std::move(column));
    }

  return block;
}

API::ServerWorker::ServerWorker(moodycamel::ReaderWriterQueue<DataModel::DataBlockPtr>* queue,
                                std::atomic<bool>* enabled,
                                std::atomic<size_t>* queueSize)
  : DataModel::FrameConsumerWorker<DataModel::DataBlockPtr>(queue, enabled, queueSize)
void API::ServerWorker::processItems(const std::vector<DataModel::DataBlockPtr>& items)
  for (const auto& block : items) {
    if (!block || block->samples <= 0)
      continue;

    const auto tpl = m_templates.find(block->sourceId);
    if (tpl == m_templates.end())
      continue;

    for (qsizetype i = 0; i < block->samples; ++i) {
      if (array.size() >= kMaxBroadcastSamples)
        break;

      DataModel::apply_block_sample(tpl->second, *block, i);

      QJsonObject object;
      object.insert(QStringLiteral("data"), serialize(tpl->second.frame));
      array.append(object);
    }

    if (array.size() >= kMaxBroadcastSamples)
      break;
  if (array.isEmpty())
    return;

/**
 * @brief Stores one source's structure and rebuilds its uniqueId lookup. Queued from the GUI, so
 *        the assignment never races processItems().
 */
void API::ServerWorker::setTemplateFrame(int sourceId, const DataModel::Frame& frame)
{
  DataModel::bind_frame_template(m_templates[sourceId], frame);
}

  : DataModel::FrameConsumer<DataModel::DataBlockPtr>(
  , m_anyStreamSubscriber(false)
 *        workers' typed export payloads: pushStreamBlock() drops a block for every connection
 * @brief Adopts the frame structure the pipeline publishes on every layout change. The wire keeps
 *        its per-frame shape (spec 0055 D5), and a block carries values only, so the worker needs
 *        this to rebuild the frame it serializes.
 */
void API::Server::setupExternalConnections()
{
  SS_ASSERT(m_worker != nullptr, return);

  auto* worker = static_cast<ServerWorker*>(m_worker);
  connect(&DataModel::FrameBuilder::instance(),
          &DataModel::FrameBuilder::structurePublished,
          worker,
          &ServerWorker::setTemplateFrame,
          Qt::QueuedConnection);
}

void API::Server::ingestBlock(const DataModel::DataBlockPtr& block)
{
  if (!block || !enabled())
    return;

  enqueueData(block);

  if (!m_anyStreamSubscriber.load(std::memory_order_relaxed))
    return;

  QMetaObject::invokeMethod(this, [this, block] { pushStreamBlock(block); }, Qt::QueuedConnection);
}

static void drainDashboardRings()
{
  static auto& dashboard = UI::Dashboard::instance();
  static auto& pipeline  = IO::PipelineHost::instance();

  DataModel::DataBlockPtr block;
  DataModel::StructureSnapshotPtr structure;

  // code-verify off
  while (pipeline.dequeueStructureSnapshot(structure))
    dashboard.applyStructureSnapshot(structure);
  while (pipeline.dequeueDashboardBlock(block))
    dashboard.applyBlock(block);
  // code-verify on
}

[[nodiscard]] static QDir csvSessionDir(const QString& title)
{
  static auto& workspaceManager = Misc::WorkspaceManager::instance();
  const auto subdir             = workspaceManager.path(QStringLiteral("CSV"));

  QString safeTitle = title;
  safeTitle.remove(QChar('/'));
  safeTitle.remove(QChar('\\'));
  safeTitle.remove(QChar(':'));
  safeTitle.remove(QChar('*'));
  safeTitle.remove(QChar('?'));
  safeTitle.remove(QChar('"'));
  safeTitle.remove(QChar('<'));
  safeTitle.remove(QChar('>'));
  safeTitle.remove(QChar('|'));
  safeTitle.remove(QChar('\0'));
  safeTitle.remove(QStringLiteral(".."));
  safeTitle = safeTitle.simplified();

  int keep = 0;
  for (int i = safeTitle.size(); i > 0; --i) {
    const QChar c = safeTitle.at(i - 1);
    if (c != QChar('.') && c != QChar(' ')) {
      keep = i;
      break;
    }
  }

  safeTitle.truncate(keep);
  if (safeTitle.isEmpty())
    safeTitle = QStringLiteral("Untitled");

  const QString path = QStringLiteral("%1/%2/").arg(subdir, safeTitle);
  QDir dir(path);
  if (!dir.exists() && !dir.mkpath(QStringLiteral(".")))
    qWarning() << "[CSV] failed to create export directory:" << path;

  return dir;
}

static void appendDouble(QByteArray& dst, double value, std::chars_format fmt, int precision)
{
  SS_ASSERT(precision >= 0, return);
  SS_ASSERT(fmt == std::chars_format::fixed || fmt == std::chars_format::general, return);

  char buf[352];
#ifdef SS_APPLE_NO_FLOAT_TO_CHARS
  const char* spec = (fmt == std::chars_format::fixed) ? "%.*f" : "%.*g";
  const int len    = snprintf_l(buf, sizeof(buf), nullptr, spec, precision, value);
  SS_ASSERT(len > 0 && static_cast<size_t>(len) < sizeof(buf), return);
  dst.append(buf, static_cast<qsizetype>(len));
#else
  const auto res = std::to_chars(buf, buf + sizeof(buf), value, fmt, precision);
  SS_ASSERT(res.ec == std::errc(), return);
  dst.append(buf, static_cast<qsizetype>(res.ptr - buf));
#endif
}

void CSV::appendCsvDouble(QByteArray& dst, double value, bool fixed, int precision)
{
  appendDouble(
    dst, value, fixed ? std::chars_format::fixed : std::chars_format::general, precision);
}

QVariant Console::AnnotationModel::data(const QModelIndex& index, int role) const
{
  if (!index.isValid() || index.row() < 0 || index.row() >= static_cast<int>(m_items.size()))
    return {};

  const Annotation& a = m_items[static_cast<std::size_t>(index.row())];
  const int cls       = a.cls;
  const bool clsOk    = cls >= 0 && static_cast<std::size_t>(cls) < m_classes.size();
  const bool rowOk    = a.row >= 0 && a.row < m_rowNames.size();

  switch (role) {
    case StartRole:
      return a.start;
    case EndRole:
      return a.end;
    case LengthRole:
      return a.end - a.start + 1;
    case RowRole:
      return a.row;
    case RowNameRole:
      return rowOk ? m_rowNames.at(a.row) : QString::number(a.row);
    case ClassRole:
      return cls;
    case ClassNameRole:
      return clsOk ? m_classes[static_cast<std::size_t>(cls)].name : QString::number(cls);
    case ClassColorRole:
      return clsOk ? m_classes[static_cast<std::size_t>(cls)].color : QColor(Qt::gray);
    case TextRole:
      return text(index.row(), 0);
    case ShortTextRole:
      return text(index.row(), Annotation::kTextLevels - 1);
    default:
      break;
  }

  if (role != Qt::DisplayRole)
    return {};

  switch (index.column()) {
    case StartColumn:
      return a.start;
    case EndColumn:
      return a.end;
    case LengthColumn:
      return a.end - a.start + 1;
    case RowColumn:
      return rowOk ? m_rowNames.at(a.row) : QString::number(a.row);
    case ClassColumn:
      return clsOk ? m_classes[static_cast<std::size_t>(cls)].name : QString::number(cls);
    case TextColumn:
      return text(index.row(), 0);
    default:
      return {};
  }
}

QVariant Console::AnnotationModel::headerData(int section,
                                              Qt::Orientation orientation,
                                              int role) const
{
  if (orientation != Qt::Horizontal || role != Qt::DisplayRole)
    return {};

  switch (section) {
    case StartColumn:
      return tr("Start");
    case EndColumn:
      return tr("End");
    case LengthColumn:
      return tr("Length");
    case RowColumn:
      return tr("Row");
    case ClassColumn:
      return tr("Class");
    case TextColumn:
      return tr("Text");
    default:
      return {};
  }
}

QHash<int, QByteArray> Console::AnnotationModel::roleNames() const
{
  return {
    {Qt::DisplayRole,    "display"},
    {      StartRole,      "start"},
    {        EndRole,        "end"},
    {     LengthRole,     "length"},
    {        RowRole,        "row"},
    {    RowNameRole,    "rowName"},
    {      ClassRole,        "cls"},
    {  ClassNameRole,  "className"},
    { ClassColorRole, "classColor"},
    {       TextRole,       "text"},
    {  ShortTextRole,  "shortText"},
  };
}

QVariantList Console::AnnotationModel::classes() const
{
  QVariantList out;
  out.reserve(static_cast<qsizetype>(m_classes.size()));
  for (const auto& spec : m_classes) {
    QVariantMap entry;
    entry.insert(QStringLiteral("name"), spec.name);
    entry.insert(QStringLiteral("color"), spec.color);
    out.append(entry);
  }

  return out;
}

const Console::Annotation& Console::AnnotationModel::at(int index) const
{
  static const Annotation kEmpty{
    0, 0, 0, 0, {kOverflowTextId, -1, -1}
  };
  if (index < 0 || static_cast<std::size_t>(index) >= m_items.size())
    return kEmpty;

  return m_items[static_cast<std::size_t>(index)];
}

QString Console::AnnotationModel::text(int index, int level) const
{
  const Annotation& a = at(index);
  const int clamped   = std::clamp(level, 0, Annotation::kTextLevels - 1);
  for (int l = clamped; l >= 0; --l) {
    const int id = a.texts[l];
    if (id >= 0 && id < m_texts.size())
      return m_texts.at(id);
  }

  return m_texts.first();
}

std::size_t Console::AnnotationModel::windowFirstIndex(qint64 from) const
{
  if (!m_sortedByStart)
    return 0;

  const auto it =
    std::lower_bound(m_items.begin(), m_items.end(), from, [](const Annotation& a, qint64 value) {
      return a.start < value;
    });

  std::size_t first = static_cast<std::size_t>(std::distance(m_items.begin(), it));
  while (first > 0 && m_items[first - 1].end >= from)
    --first;

  return first;
}

std::vector<Console::AnnotationModel::SpanRun> Console::AnnotationModel::collectRuns(
  qint64 from, qint64 to, int row, int maxSpans, qint64 minSpanBytes) const
{
  std::vector<SpanRun> runs;
  if (to < from || maxSpans <= 0)
    return runs;

  const qint64 gap = std::max<qint64>(1, minSpanBytes);
  const int limit  = std::min(maxSpans, kMaxAnnotations);
  runs.reserve(static_cast<std::size_t>(std::min(limit, 4096)));

  for (std::size_t i = windowFirstIndex(from);
       i < m_items.size() && runs.size() < static_cast<std::size_t>(limit);
       ++i) {
    const Annotation& a = m_items[i];
    if (a.start > to && m_sortedByStart)
      break;

    if (a.row != row || a.end < from || a.start > to)
      continue;

    if (!runs.empty()) {
      SpanRun& last       = runs.back();
      const bool subPixel = (a.end - a.start + 1) <= gap && (a.start - last.end) <= gap;
      const bool inPixel  = (a.end - last.start + 1) <= gap;
      if (a.cls == last.cls && subPixel && inPixel) {
        last.end = a.end;
        ++last.count;
        continue;
      }
    }

    runs.push_back(SpanRun{a.start, a.end, a.cls, 1, static_cast<int>(i)});
  }

  return runs;
}

QVariantList Console::AnnotationModel::trackSpans(
  qint64 from, qint64 to, int row, int maxSpans, qint64 minSpanBytes) const
{
  QVariantList out;
  const auto runs = collectRuns(from, to, row, maxSpans, minSpanBytes);
  out.reserve(static_cast<qsizetype>(runs.size()));

  for (const SpanRun& run : runs) {
    const bool clsOk = run.cls >= 0 && static_cast<std::size_t>(run.cls) < m_classes.size();
    QVariantMap span;
    span.insert(QStringLiteral("start"), run.start);
    span.insert(QStringLiteral("end"), run.end);
    span.insert(QStringLiteral("cls"), run.cls);
    span.insert(QStringLiteral("count"), run.count);
    span.insert(QStringLiteral("color"),
                clsOk ? m_classes[static_cast<std::size_t>(run.cls)].color : QColor(Qt::gray));
    span.insert(QStringLiteral("text"), text(run.firstIndex, 0));
    span.insert(QStringLiteral("shortText"), text(run.firstIndex, Annotation::kTextLevels - 1));
    out.append(span);
  }

  return out;
}

QVariantMap Console::AnnotationModel::trackStrip(
  qint64 from, qint64 to, int row, int maxSpans, qint64 minSpanBytes, qreal pixels) const
{
  QVariantMap out;
  const auto runs   = collectRuns(from, to, row, maxSpans, minSpanBytes);
  const qreal width = std::max<qreal>(1, pixels);
  const qreal span  = static_cast<qreal>(std::max<qint64>(1, to - from));

  QList<qreal> geometry;
  geometry.reserve(static_cast<qsizetype>(runs.size()) * 6);
  for (const SpanRun& run : runs) {
    const qreal x0 = std::max<qreal>(0, (run.start - from) / span * width);
    const qreal x1 = std::min<qreal>(width, (run.end + 1 - from) / span * width);
    geometry << x0 << std::max<qreal>(1, x1 - x0) << static_cast<qreal>(run.start)
             << static_cast<qreal>(run.end) << static_cast<qreal>(run.cls)
             << static_cast<qreal>(run.count);
  }

  QStringList labels;
  QStringList shortLabels;
  if (runs.size() <= static_cast<std::size_t>(kLabelledSpanBudget)) {
    labels.reserve(static_cast<qsizetype>(runs.size()));
    shortLabels.reserve(static_cast<qsizetype>(runs.size()));
    for (const SpanRun& run : runs) {
      labels << text(run.firstIndex, 0);
      shortLabels << text(run.firstIndex, Annotation::kTextLevels - 1);
    }
  }

  out.insert(QStringLiteral("count"), static_cast<int>(runs.size()));
  out.insert(QStringLiteral("geometry"), QVariant::fromValue(geometry));
  out.insert(QStringLiteral("labels"), labels);
  out.insert(QStringLiteral("shortLabels"), shortLabels);
  return out;
}

QByteArray Console::AnnotationModel::payloadBytes(int cls, int maxBytes) const
{
  QByteArray out;
  if (maxBytes <= 0)
    return out;

  for (const Annotation& a : m_items) {
    if (a.cls != cls || a.start < m_bytesStart || a.end >= m_bytesEnd || a.end < a.start)
      continue;

    const qsizetype offset = static_cast<qsizetype>(a.start - m_bytesStart);
    const qsizetype length = static_cast<qsizetype>(a.end - a.start + 1);
    if (offset < 0 || offset + length > m_bytes.size())
      continue;

    const qsizetype room = static_cast<qsizetype>(maxBytes) - out.size();
    if (room <= 0)
      break;

    out.append(m_bytes.constData() + offset, std::min(length, room));
  }

  return out;
}

bool Console::AnnotationModel::exportCsv(const QString& path) const
{
  QFile file(path);
  if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate | QIODevice::Text))
    return false;

  const auto quote = [](const QString& value) {
    QString escaped = value;
    escaped.replace(QLatin1Char('"'), QStringLiteral("\"\""));
    return QLatin1Char('"') + escaped + QLatin1Char('"');
  };

  QTextStream out(&file);
  out << "start,end,length,row,class,text\n";
  for (std::size_t i = 0; i < m_items.size(); ++i) {
    const Annotation& a   = m_items[i];
    const QModelIndex idx = index(static_cast<int>(i), 0);
    out << a.start << ',' << a.end << ',' << (a.end - a.start + 1) << ','
        << quote(data(idx, RowNameRole).toString()) << ','
        << quote(data(idx, ClassNameRole).toString()) << ',' << quote(text(static_cast<int>(i), 0))
        << '\n';
  }

  return out.status() == QTextStream::Ok;
}

void Console::AnnotationModel::declareLayout(const QStringList& rows,
                                             const QVariantList& classSpecs)
{
  reset();

  m_rowNames = rows.mid(0, kMaxRows);
  if (m_rowNames.isEmpty())
    m_rowNames.append(tr("Annotations"));

  m_classes.clear();
  static const QColor kPalette[] = {
    QColor(0x4e, 0x79, 0xa7),
    QColor(0xf2, 0x8e, 0x2b),
    QColor(0xe1, 0x57, 0x59),
    QColor(0x76, 0xb7, 0xb2),
    QColor(0x59, 0xa1, 0x4f),
    QColor(0xed, 0xc9, 0x48),
    QColor(0xb0, 0x7a, 0xa1),
    QColor(0xff, 0x9d, 0xa7),
  };
  static constexpr int kPaletteSize = static_cast<int>(sizeof(kPalette) / sizeof(kPalette[0]));

  for (int i = 0; i < classSpecs.size() && i < kMaxClasses; ++i) {
    const QVariant& spec = classSpecs.at(i);
    ClassSpec entry;
    entry.color = kPalette[i % kPaletteSize];
    if (spec.canConvert<QVariantMap>()) {
      const auto map = spec.toMap();
      entry.name     = map.value(QStringLiteral("name")).toString();
      const QColor c = QColor::fromString(map.value(QStringLiteral("color")).toString());
      if (c.isValid())
        entry.color = c;
    } else {
      entry.name = spec.toString();
    }

    if (entry.name.isEmpty())
      entry.name = tr("class %1").arg(i);

    m_classes.push_back(entry);
  }

  if (m_classes.empty())
    m_classes.push_back(ClassSpec{tr("data"), kPalette[0]});

  Q_EMIT layoutDeclared();
}

void Console::AnnotationModel::annotate(
  qint64 start, qint64 end, int row, int cls, const QStringList& texts)
{
  if (end < start || start < 0 || row < 0 || row >= m_rowNames.size() || cls < 0
      || static_cast<std::size_t>(cls) >= m_classes.size())
    return;

  Annotation a;
  a.start = start;
  a.end   = end;
  a.row   = row;
  a.cls   = cls;
  for (int l = 0; l < Annotation::kTextLevels; ++l)
    a.texts[l] = (l < texts.size()) ? internText(texts.at(l)) : -1;

  if (texts.isEmpty())
    a.texts[0] = kOverflowTextId;

  if (m_pending.size() >= static_cast<std::size_t>(kMaxAnnotations))
    m_pending.erase(m_pending.begin(), m_pending.begin() + kMaxAnnotations / 4);

  m_pending.push_back(a);
}

void Console::AnnotationModel::commitPending()
{
  if (!m_pending.empty()) {
    const int staged   = static_cast<int>(m_pending.size());
    const int overflow = static_cast<int>(m_items.size()) + staged - kMaxAnnotations;
    if (overflow > 0)
      dropOldest(overflow);

    const int first = static_cast<int>(m_items.size());
    beginInsertRows(QModelIndex(), first, first + staged - 1);
    for (const Annotation& a : m_pending) {
      if (!m_items.empty() && a.start < m_items.back().start)
        m_sortedByStart = false;

      m_items.push_back(a);
    }

    endInsertRows();
    m_pending.clear();
    m_countDirty = true;
  }

  if (m_countDirty) {
    m_countDirty = false;
    Q_EMIT countChanged();
  }
}

void Console::AnnotationModel::ingestBytes(const QByteArray& bytes)
{
  if (bytes.isEmpty())
    return;

  m_bytes.append(bytes);
  m_bytesEnd += bytes.size();
  if (m_bytes.size() > kMaxRetainedBytes) {
    const qsizetype excess = m_bytes.size() - kMaxRetainedBytes;
    m_bytes.remove(0, excess);
    m_bytesStart += excess;
    trimToRetainedBytes();
  }

  m_countDirty = true;
}

void Console::AnnotationModel::reset()
{
  beginResetModel();
  m_items.clear();
  m_pending.clear();
  m_texts = QStringList{QStringLiteral("...")};
  m_textIds.clear();
  m_textIds.insert(m_texts.first(), kOverflowTextId);
  m_bytes.clear();
  m_bytesStart    = 0;
  m_bytesEnd      = 0;
  m_countDirty    = false;
  m_sortedByStart = true;
  endResetModel();
  Q_EMIT countChanged();
}

int Console::AnnotationModel::internText(const QString& text)
{
  const auto it = m_textIds.constFind(text);
  if (it != m_textIds.cend())
    return it.value();

  if (m_texts.size() >= kMaxTexts)
    return kOverflowTextId;

  const int id = m_texts.size();
  m_texts.append(text);
  m_textIds.insert(text, id);
  return id;
}

void Console::AnnotationModel::trimToRetainedBytes()
{
  int drop = 0;
  for (std::size_t i = 0; i < m_items.size(); ++i) {
    if (m_items[i].end >= m_bytesStart)
      break;

    ++drop;
  }

  if (drop > 0)
    dropOldest(drop);
}

void Console::AnnotationModel::dropOldest(int count)
{
  const int available = static_cast<int>(m_items.size());
  const int n         = std::clamp(count, 0, available);
  if (n == 0)
    return;

  beginRemoveRows(QModelIndex(), 0, n - 1);
  m_items.erase(m_items.begin(), m_items.begin() + n);
  endRemoveRows();
}

Console::AnnotationFilter::AnnotationFilter(QObject* parent)
  : QSortFilterProxyModel(parent), m_rowFilter(-1), m_classFilter(-1)
{
  setDynamicSortFilter(true);
}

void Console::AnnotationFilter::setRowFilter(int row)
{
  if (m_rowFilter == row)
    return;

  beginFilterChange();
  m_rowFilter = row;
  endFilterChange(QSortFilterProxyModel::Direction::Rows);
  Q_EMIT filterChanged();
}

void Console::AnnotationFilter::setClassFilter(int cls)
{
  if (m_classFilter == cls)
    return;

  beginFilterChange();
  m_classFilter = cls;
  endFilterChange(QSortFilterProxyModel::Direction::Rows);
  Q_EMIT filterChanged();
}

bool Console::AnnotationFilter::filterAcceptsRow(int sourceRow, const QModelIndex& parent) const
{
  const auto* source = sourceModel();
  if (!source)
    return false;

  const QModelIndex idx = source->index(sourceRow, 0, parent);
  if (m_rowFilter >= 0 && source->data(idx, AnnotationModel::RowRole).toInt() != m_rowFilter)
    return false;

  return m_classFilter < 0
      || source->data(idx, AnnotationModel::ClassRole).toInt() == m_classFilter;
}

QVariantList Console::AnnotationDecoder::templates() const
{
  QVariantList out;
  const auto definitions = DataModel::loadScriptTemplateManifest(
    QStringLiteral(":/scripts/annotations/templates.json"), "AnnotationDecoder");

  out.reserve(definitions.size());
  for (const auto& definition : definitions) {
    QVariantMap entry;
    entry.insert(QStringLiteral("file"), definition.file);
    entry.insert(QStringLiteral("name"), definition.name);
    entry.insert(QStringLiteral("default"), definition.isDefault);
    out.append(entry);
  }

  return out;
}

QString Console::AnnotationDecoder::templateCode(const QString& file) const
{
  return DataModel::readTextResource(DataModel::templateResourcePath(
    QStringLiteral(":/scripts/annotations"), file, QStringLiteral(".js")));
}

void Console::AnnotationDecoder::setCode(const QString& code)
{
  m_code = code;
  teardownEngine();
  m_failed = false;
  m_lastError.clear();

  if (m_code.trimmed().isEmpty()) {
    m_compiled = false;
    m_enabled  = false;
    Q_EMIT stateChanged();
    return;
  }

  QString error;
  m_compiled = compile(error);
  if (!m_compiled)
    fail(error);
  else
    Q_EMIT stateChanged();
}

void Console::AnnotationDecoder::setEnabled(bool enabled)
{
  if (enabled && !m_compiled)
    setCode(m_code);

  const bool next = enabled && m_compiled;
  if (m_enabled == next)
    return;

  m_enabled = next;
  Q_EMIT stateChanged();
}

void Console::AnnotationDecoder::feed(const QByteArray& bytes)
{
  SS_ASSERT(m_model != nullptr, return);

  if (bytes.isEmpty())
    return;

  m_model->ingestBytes(bytes);

  if (!m_enabled || !m_compiled || m_inFeed || !m_engine || !m_watchdog)
    return;

  m_inFeed = true;

  const QByteArray chunk = m_carry.isEmpty() ? bytes : (m_carry + bytes);
  const qint64 offset    = m_carryOffset;

  QJSValueList args;
  args << m_engine->toScriptValue(chunk) << QJSValue(static_cast<double>(offset)) << m_context;
  const QJSValue result = m_watchdog->call(m_decodeFn, args);

  if (m_watchdog->lastCallTimedOut()) {
    fail(tr("decode() exceeded %1 ms").arg(kWatchdogMs));
    m_inFeed = false;
    return;
  }

  if (result.isError()) {
    fail(result.property(QStringLiteral("message")).toString());
    m_inFeed = false;
    return;
  }

  qint64 consumed = result.isNumber() ? static_cast<qint64>(result.toNumber()) : chunk.size();
  consumed        = std::clamp<qint64>(consumed, 0, chunk.size());

  m_carry = chunk.mid(static_cast<qsizetype>(consumed));
  if (m_carry.size() > kMaxCarry) {
    const qsizetype dropped = m_carry.size() - kMaxCarry;
    m_carry.remove(0, dropped);
    consumed += dropped;
  }

  m_carryOffset = offset + consumed;
  m_inFeed      = false;
}

void Console::AnnotationDecoder::reset()
{
  m_carry.clear();
  if (m_model)
    m_model->reset();

  m_carryOffset = m_model ? m_model->retainedEnd() : 0;
}

bool Console::AnnotationDecoder::compile(QString& error)
{
  m_engine   = std::make_unique<QJSEngine>();
  m_watchdog = std::make_unique<DataModel::JsWatchdog>(
    m_engine.get(), kWatchdogMs, QStringLiteral("annotation decoder"));

  const QJSValue evaluated = m_engine->evaluate(m_code);
  if (evaluated.isError()) {
    error = tr("Line %1: %2")
              .arg(evaluated.property(QStringLiteral("lineNumber")).toInt())
              .arg(evaluated.property(QStringLiteral("message")).toString());
    return false;
  }

  const QJSValue decoder = m_engine->globalObject().property(QStringLiteral("decoder"));
  if (!decoder.isObject()) {
    error = tr("the script must define a global 'decoder' object");
    return false;
  }

  m_decodeFn = decoder.property(QStringLiteral("decode"));
  if (!m_decodeFn.isCallable()) {
    error = tr("'decoder.decode(bytes, offset, ctx)' is not a function");
    return false;
  }

  if (!readLayout(error))
    return false;

  QJSEngine::setObjectOwnership(m_model, QJSEngine::CppOwnership);
  m_context = m_engine->newQObject(m_model);
  m_carry.clear();
  m_carryOffset = m_model->retainedEnd();
  return true;
}

bool Console::AnnotationDecoder::readLayout(QString& error)
{
  const QJSValue decoder = m_engine->globalObject().property(QStringLiteral("decoder"));

  QStringList rows;
  const QJSValue rowsValue = decoder.property(QStringLiteral("rows"));
  if (rowsValue.isArray()) {
    const int n = rowsValue.property(QStringLiteral("length")).toInt();
    for (int i = 0; i < n && i < AnnotationModel::kMaxRows; ++i)
      rows.append(rowsValue.property(static_cast<quint32>(i)).toString());
  }

  QVariantList classes;
  const QJSValue classValue = decoder.property(QStringLiteral("classes"));
  if (classValue.isArray()) {
    const int n = classValue.property(QStringLiteral("length")).toInt();
    for (int i = 0; i < n && i < AnnotationModel::kMaxClasses; ++i)
      classes.append(classValue.property(static_cast<quint32>(i)).toVariant());
  }

  if (rows.isEmpty() || classes.isEmpty()) {
    error = tr("'decoder.rows' and 'decoder.classes' must be non-empty arrays");
    return false;
  }

  m_model->declareLayout(rows, classes);
  return true;
}

void Console::AnnotationDecoder::fail(const QString& error)
{
  ++m_errorCount;
  m_lastError = error.isEmpty() ? tr("unknown decoder error") : error;
  m_failed    = true;
  m_enabled   = false;
  m_compiled  = false;
  teardownEngine();
  qWarning() << "[Console] annotation decoder disabled:" << m_lastError;
  Q_EMIT stateChanged();
}

void Console::AnnotationDecoder::teardownEngine()
{
  m_decodeFn = QJSValue();
  m_context  = QJSValue();
  m_watchdog.reset();
  m_engine.reset();
}

int DataModel::DatasetTransformEditor::comboIndexForLanguage(int language)
{
  if (language == SerialStudio::Lua)
    return 0;

  return (language == SerialStudio::Expression) ? 2 : 1;
}

int DataModel::DatasetTransformEditor::languageForComboIndex(int index)
{
  if (index == 0)
    return SerialStudio::Lua;

  return (index == 2) ? SerialStudio::Expression : SerialStudio::JavaScript;
}

DataModel::Expression::TableResolver DataModel::DatasetTransformEditor::expressionTables()
{
  static auto& frameBuilder = DataModel::FrameBuilder::instance();
  return [](QStringView table, QStringView reg) -> qint64 {
    return frameBuilder.tableStore().handleOf(table.toString(), reg.toString());
  };
}

DataModel::Expression::NameResolver DataModel::DatasetTransformEditor::expressionResolver(
  DataModel::Expression::SlotTable& table)
{
  static auto& frameBuilder = DataModel::FrameBuilder::instance();

  QHash<QString, int> aliases;
  QSet<int> uniqueIds;
  frameBuilder.invokeOnBuilderThreadBlocking([&aliases, &uniqueIds] {
    for (const auto& group : frameBuilder.frame().groups)
      for (const auto& dataset : group.datasets) {
        uniqueIds.insert(dataset.uniqueId);
        if (!dataset.alias.isEmpty())
          aliases.insert(dataset.alias, dataset.uniqueId);
      }
  });

  return [aliases, uniqueIds, &table](QStringView name) -> int {
    const auto it = aliases.constFind(name.toString());
    if (it != aliases.cend())
      return table.slotFor(it.value());

    bool ok               = false;
    const int resolved_id = name.toInt(&ok);
    if (ok && uniqueIds.contains(resolved_id))
      return table.slotFor(resolved_id);

    return -1;
  };
  if (language == SerialStudio::Expression) {
    DataModel::Expression::SlotTable table;
    DataModel::Expression::Program program;
    return DataModel::Expression::compile(
             code, expressionResolver(table), expressionTables(), program, error)
           ? TransformStatus::Ok
           : TransformStatus::SyntaxError;
  }

  if (language == SerialStudio::Expression) {
    DataModel::Expression::SlotTable table;
    DataModel::Expression::Runtime runtime;
    QString error;
    if (!DataModel::Expression::compile(
          code, expressionResolver(table), expressionTables(), runtime.program, error))
      return tr("Error: %1").arg(error);

    return QString::number(runtime.run(inputValue, 0.0, table), 'g', 15);
  }

void DataModel::ExpressionHighlighter::highlightBlock(const QString& text)
{
  auto* style = syntaxStyle();
  if (!style)
    return;

  auto braced = m_braced.globalMatch(text);
  while (braced.hasNext()) {
    const auto match = braced.next();
    setFormat(match.capturedStart(), match.capturedLength(), style->getFormat("String"));
  }

  auto numbers = m_number.globalMatch(text);
  while (numbers.hasNext()) {
    const auto match = numbers.next();
    setFormat(match.capturedStart(), match.capturedLength(), style->getFormat("Number"));
  }

  auto builtins = m_builtin.globalMatch(text);
  while (builtins.hasNext()) {
    const auto match = builtins.next();
    setFormat(match.capturedStart(), match.capturedLength(), style->getFormat("Keyword"));
  }

  auto functions = m_function.globalMatch(text);
  while (functions.hasNext()) {
    const auto match = functions.next();
    setFormat(match.capturedStart(1), match.capturedLength(1), style->getFormat("Function"));
  }

  auto comments = m_comment.globalMatch(text);
  while (comments.hasNext()) {
    const auto match = comments.next();
    setFormat(match.capturedStart(), match.capturedLength(), style->getFormat("Comment"));
  }
}

void DataModel::FrameBuilder::refreshBlockPoolBudget(const DataModel::Frame& src) noexcept
{
  std::size_t datasets = 0;
  for (const auto& group : src.groups)
    datasets += group.datasets.size();

  constexpr std::size_t kFloor = IO::PipelineHost::kBlockRingSize + 8;
  if (datasets == 0) {
    m_blockSlotsUsable = kBlockPoolSlots;
    return;
  }

  const std::size_t perSample = 2 * sizeof(double) + 2 * sizeof(QString) + 1 + sizeof(qint64);
  const std::size_t perSlot = datasets * static_cast<std::size_t>(kFrameBlockSampleCap) * perSample;
  const std::size_t affordable = perSlot > 0 ? kBlockPoolBudgetBytes / perSlot : kBlockPoolSlots;

  m_blockSlotsUsable =
    static_cast<int>(std::clamp<std::size_t>(affordable, kFloor, kBlockPoolSlots));
}

std::shared_ptr<DataModel::FrameBuilder::PooledBlockSlot> DataModel::FrameBuilder::claimBlockSlot(
  int sourceId) noexcept
{
  static_assert(IO::PipelineHost::kBlockRingSize < kBlockPoolSlots - 8,
                "block pool must outsize the dashboard ring or staging starves");

  SS_ASSERT(!m_blockPool.empty(), return nullptr);

  const std::size_t n = std::min(m_blockPool.size(), static_cast<std::size_t>(m_blockSlotsUsable));
  std::size_t freeIdx = n;

  for (std::size_t k = 0; k < n; ++k) {
    const std::size_t idx = (m_blockPoolHint + k) % n;
    const auto& slot      = m_blockPool[idx];
    if (slot.use_count() != 1)
      continue;

    if (slot->generation == m_framePoolGeneration && slot->sourceId == sourceId) {
      m_blockPoolHint = (idx + 1) % n;
      return m_blockPool[idx];
    }

    if (freeIdx == n)
      freeIdx = idx;
  }

  if (freeIdx == n)
    return nullptr;

  m_blockPoolHint = (freeIdx + 1) % n;
  return m_blockPool[freeIdx];
}

DataModel::StructureSnapshotPtr DataModel::FrameBuilder::buildStructureSnapshot(
  const DataModel::Frame& src)
{
  auto snapshot        = std::make_shared<DataModel::StructureSnapshot>();
  snapshot->generation = m_framePoolGeneration;
  snapshot->data       = src;
  return snapshot;
}

bool DataModel::FrameBuilder::structureIsCurrent(int sourceId) const noexcept
{
  const auto it = m_publishedStructureGeneration.find(sourceId);
  return it != m_publishedStructureGeneration.end() && it->second == m_framePoolGeneration;
}

void DataModel::FrameBuilder::ensureStructurePublished(int sourceId, const DataModel::Frame& src)
{
  if (structureIsCurrent(sourceId)) [[likely]]
    return;

  static auto& pipeline = IO::PipelineHost::instance();
  pipeline.publishStructureToDashboard(buildStructureSnapshot(src));
  noteStructurePublished(sourceId);

  Q_EMIT structurePublished(sourceId, src);
}

void DataModel::FrameBuilder::bindBlockToFrame(PooledBlockSlot& slot,
                                               const DataModel::Frame& src,
                                               bool uniform)
{
  auto& block               = slot.block;
  block.sourceId            = src.sourceId;
  block.structureGeneration = m_framePoolGeneration;
  block.dt                  = std::chrono::nanoseconds(0);

  block.columns.clear();
  for (const auto& group : src.groups)
    for (const auto& dataset : group.datasets) {
      DataModel::BlockColumn column;
      column.uniqueId = dataset.uniqueId;
      column.hasText  = true;
      column.hasRaw   = true;
      block.columns.push_back(std::move(column));
    }

  DataModel::size_block_storage(block, kFrameBlockSampleCap, !uniform);
  slot.generation = m_framePoolGeneration;
  slot.sourceId   = src.sourceId;
}

DataModel::FrameBuilder::PooledBlockSlot* DataModel::FrameBuilder::openBlockFor(
  int sourceId, const DataModel::Frame& src)
{
  static auto& pipeline = IO::PipelineHost::instance();

  const auto it = m_openBlocks.find(sourceId);
  if (it != m_openBlocks.end()) [[likely]] {
    if (it->second->generation == m_framePoolGeneration) [[likely]]
      return it->second.get();

    flushBlock(sourceId);
  }

  auto slot = claimBlockSlot(sourceId);
  if (!slot) [[unlikely]] {
    notePoolExhausted();
    return nullptr;
  }

  if (slot->generation != m_framePoolGeneration || slot->sourceId != src.sourceId)
    bindBlockToFrame(*slot, src, false);

  slot->flushEpoch = pipeline.flushEpoch();
  DataModel::reset_block(slot->block);
  slot->block.structureGeneration = m_framePoolGeneration;

  const auto inserted = m_openBlocks.emplace(sourceId, std::move(slot));
  return inserted.first->second.get();
}

SS_HOT void DataModel::FrameBuilder::stageFrameValues(
  int sourceId, const DataModel::Frame& src, const DataModel::TimestampedFrame::SteadyTimePoint& ts)
{
  SS_ASSERT_HOTPATH(sourceId >= 0);

  static auto& pipeline = IO::PipelineHost::instance();

  ensureStructurePublished(sourceId, src);

  auto* slot = openBlockFor(sourceId, src);
  if (!slot) [[unlikely]]
    return;

  auto& block           = slot->block;
  const qsizetype index = block.samples;
  if (index == 0)
    block.t0 = ts;

  std::size_t column = 0;
  for (const auto& group : src.groups) {
    SS_NO_UNROLL
    for (const auto& dataset : group.datasets) {
      if (column >= block.columns.size()) [[unlikely]]
        break;

      SS_ASSERT_HOTPATH(block.columns[column].uniqueId == dataset.uniqueId);
      DataModel::write_block_sample(
        block.columns[column], index, dataset.numericValue, dataset.value, dataset.isNumeric);
      DataModel::write_block_raw(
        block.columns[column], index, dataset.rawNumericValue, dataset.rawValue);
      ++column;
    }
  }

  DataModel::write_block_time(
    block, index, std::chrono::duration_cast<std::chrono::nanoseconds>(ts - block.t0).count());

  block.samples = index + 1;

  const quint64 epoch = pipeline.flushEpoch();
  if (block.samples >= kFrameBlockSampleCap || epoch != slot->flushEpoch) [[unlikely]]
    flushBlock(sourceId);
}

SS_NO_UNROLL
    for (const auto& dataset : group.datasets) {
      if (column >= block.columns.size()) [[unlikely]]
        break;

      SS_ASSERT_HOTPATH(block.columns[column].uniqueId == dataset.uniqueId);
      DataModel::write_block_sample(
        block.columns[column], index, dataset.numericValue, dataset.value, dataset.isNumeric);
      DataModel::write_block_raw(
        block.columns[column], index, dataset.rawNumericValue, dataset.rawValue);
      ++column;
    }

void DataModel::FrameBuilder::flushBlock(int sourceId)
{
  const auto it = m_openBlocks.find(sourceId);
  if (it == m_openBlocks.end())
    return;

  auto slot = it->second;
  m_openBlocks.erase(it);

  if (slot->block.samples == 0)
    return;

  slot->block.blockNumber = ++m_blockNumbers[sourceId];
  publishBlock(DataModel::DataBlockPtr(slot, &slot->block));
}

void DataModel::FrameBuilder::flushOpenBlocks()
{
  if (m_openBlocks.empty()) [[likely]]
    return;

  std::vector<int> sources;
  sources.reserve(m_openBlocks.size());
  for (const auto& [sourceId, slot] : m_openBlocks)
    sources.push_back(sourceId);

  for (const int sourceId : sources)
    flushBlock(sourceId);
}

void DataModel::FrameBuilder::wireDisplayTickHooks(Misc::TimerEvents& timers,
                                                   IO::PipelineHost& pipeline)
{
  connect(&timers,
          &Misc::TimerEvents::uiTimeout,
          this,
          &DataModel::FrameBuilder::refreshStreamDrivenFrames);

  connect(
    &timers,
    &Misc::TimerEvents::uiTimeout,
    &pipeline,
    [&pipeline] { pipeline.bumpFlushEpoch(); },
    Qt::DirectConnection);

  connect(&timers, &Misc::TimerEvents::uiTimeout, this, [this] { flushOpenBlocks(); });
}

void DataModel::FrameBuilder::refreshAsyncSinks()
{
  if (QThread::currentThread() != thread()) {
    invokeOnBuilderThread([this] { refreshAsyncSinks(); });
    return;
  }

  refreshAnyAsyncSink();
}

DataModel::FrameBuilder::ProjectSnapshot DataModel::FrameBuilder::collectProjectSnapshot()
{
  static auto& pm = DataModel::ProjectModel::instance();
  SS_ASSERT_LOG(!pm.title().isEmpty());

  ProjectSnapshot snapshot;
  snapshot.title   = pm.title();
  snapshot.groups  = buildEnabledGroups(pm.groups());
  snapshot.actions = pm.actions();
  snapshot.sources = pm.sources();
  snapshot.decoder = pm.decoderMethod();
  return snapshot;
}

