[[nodiscard]] static bool probeLastErrorRefused()
{
#ifdef Q_OS_WIN
  return ::WSAGetLastError() == WSAECONNREFUSED;
#else
  return errno == ECONNREFUSED;
#endif
}

static void closeProbeSocket(ProbeSocket handle)
{
#ifdef Q_OS_WIN
  ::closesocket(handle);
#else
  ::close(handle);
#endif
}

[[nodiscard]] static bool markProbeNonBlocking(ProbeSocket handle)
{
#ifdef Q_OS_WIN
  u_long mode = 1;
  return ::ioctlsocket(handle, FIONBIO, &mode) == 0;
#else
  const int flags = ::fcntl(handle, F_GETFL, 0);
  return flags != -1 && ::fcntl(handle, F_SETFL, flags | O_NONBLOCK) != -1;
#endif
}

IO::Drivers::Network::~Network()
{
  close();

  m_tcpSocket->deleteLater();
  m_udpSocket->deleteLater();
}

[[nodiscard]] static bool probeTcpOnce(const addrinfo* address, int timeoutMs, bool& refused)
{
  SS_ASSERT(address != nullptr, return false);
  SS_ASSERT(timeoutMs >= 0, timeoutMs = 0);

  refused = false;

  const ProbeSocket handle =
    ::socket(address->ai_family, address->ai_socktype, address->ai_protocol);
  if (handle == kNoProbeSocket)
    return false;

  if (!markProbeNonBlocking(handle)) {
    closeProbeSocket(handle);
    return false;
  }

  const int dialed =
    ::connect(handle, address->ai_addr, static_cast<ProbeLen>(address->ai_addrlen));
  if (dialed == 0) {
    closeProbeSocket(handle);
    return true;
  }

  if (!probeConnectPending()) {
    refused = probeLastErrorRefused();
    closeProbeSocket(handle);
    return false;
  }

  ProbePoll pending{};
  pending.fd     = handle;
  pending.events = POLLOUT;

  const int ready = ProbePollFn(&pending, 1, timeoutMs);
  if (ready <= 0) {
    closeProbeSocket(handle);
    return false;
  }

  int error          = 0;
  ProbeLen errorSize = sizeof(error);
  const int queried =
    ::getsockopt(handle, SOL_SOCKET, SO_ERROR, reinterpret_cast<char*>(&error), &errorSize);
  closeProbeSocket(handle);

  refused = (queried == 0 && error == kProbeRefused);
  return queried == 0 && error == 0;
}

the drop is counted like a block's.
void IO::PipelineHost::publishStructureToDashboard(const DataModel::StructureSnapshotPtr& structure)
{
  SS_ASSERT(structure != nullptr, return);

  if (!m_dashboardAccepting.load(std::memory_order_relaxed))
    return;

  if (!m_structureRing.try_enqueue(structure)) [[unlikely]]
    ++m_dashboardDrops;
}

void IO::StreamProcessor::publishFftWindow(const ChannelState& state,
                                           DataModel::BlockColumn& column) const
{
  if (state.fftRing.empty() || state.fftFill < state.fftRing.size())
    return;

  column.fftWindow.resize(state.fftRing.size());

  const std::size_t cap      = state.fftRing.size();
  const std::size_t firstRun = cap - state.fftHead;
  std::copy_n(state.fftRing.data() + state.fftHead, firstRun, column.fftWindow.data());
  std::copy_n(state.fftRing.data(), state.fftHead, column.fftWindow.data() + firstRun);
}

[[nodiscard]] static QDir mdf4SessionDir(const QString& sanitizedName)
{
  static auto& workspaceManager = Misc::WorkspaceManager::instance();
  QDir dir(workspaceManager.path(QStringLiteral("MDF4")));

  if (!dir.exists(sanitizedName) && !dir.mkpath(sanitizedName)) {
    qWarning() << "[MDF4] failed to create export directory:" << dir.filePath(sanitizedName);
    return QDir(dir.filePath(sanitizedName));
  }

  if (!dir.cd(sanitizedName)) {
    qWarning() << "[MDF4] cannot enter export directory:" << dir.filePath(sanitizedName);
    return QDir(dir.filePath(sanitizedName));
  }

  return dir;
}

void MQTT::PublisherWorker::expandBlocks(const std::vector<DataModel::DataBlockPtr>& blocks)
{
  m_expanded.clear();

  for (const auto& block : blocks) {
    if (!block || block->samples <= 0)
      continue;

    const auto tpl = m_templates.find(block->sourceId);
    if (tpl == m_templates.end())
      continue;

    for (qsizetype i = 0; i < block->samples; ++i) {
      if (m_expanded.size() >= kMaxExpandedSamples)
        return;

      DataModel::apply_block_sample(tpl->second, *block, i);
      m_expanded.push_back(tpl->second.frame);
    }
  }
}

void Sessions::DatabaseManager::requestStreamStats(int sessionId)
{
  if (!isOpen())
    return;

  QMetaObject::invokeMethod(
    m_worker, "runStreamStatsLoad", Qt::QueuedConnection, Q_ARG(int, sessionId));
}

bool Sessions::DatabaseWorker::streamCsvRowsFromBlocks(int sessionId,
                                                       QFile& file,
                                                       QTextStream& out,
                                                       const std::vector<int>& uniqueIds,
                                                       qint64 totalRows,
                                                       const QString& outputPath)
{
  QMap<int, int> uidToCol;
  for (int i = 0; i < static_cast<int>(uniqueIds.size()); ++i)
    uidToCol.insert(uniqueIds[static_cast<size_t>(i)], i);

  QSqlQuery q(m_db);
  q.setForwardOnly(true);
  q.prepare(QStringLiteral("SELECT %1 FROM blocks WHERE session_id = ? ORDER BY t0_ns, block_id")
              .arg(QLatin1String(Sessions::kBlockColumns)));
  q.bindValue(0, sessionId);
  if (!q.exec()) {
    Q_EMIT csvExportFinished(outputPath, false, q.lastError().text());
    return false;
  }

  const int colCount        = static_cast<int>(uniqueIds.size());
  const qint64 progressTick = totalRows > 0 ? (totalRows / 100 + 1) : 0;
  std::map<qint64, QStringList> buffered;
  qint64 emitted = 0;

  const auto emitRow = [&](qint64 ts, const QStringList& cells) {
    out << QString::number(ts / 1e9, 'f', 9);
    for (const auto& cell : cells)
      out << ',' << cell;

    out << '\n';

    ++emitted;
    if (progressTick > 0 && emitted % progressTick == 0) {
      const double pct = static_cast<double>(emitted) / static_cast<double>(totalRows);
      Q_EMIT csvExportProgress(std::clamp(pct, 0.0, 1.0));
    }
  };

  const auto flushBelow = [&](qint64 watermark) {
    // code-verify off
    // Bounded: every pass erases one buffered instant, and the buffer is finite.
    for (auto it = buffered.begin(); it != buffered.end() && it->first < watermark;)
      it = (emitRow(it->first, it->second), buffered.erase(it));
    // code-verify on
  };

  std::vector<Sessions::ReadingRow> rows;
  while (q.next()) {
    if (m_cancelRequested.load(std::memory_order_acquire)) {
      file.close();
      file.remove();
      Q_EMIT csvExportFinished(outputPath, false, tr("Cancelled"));
      return false;
    }

    const qint64 blockStart = q.value(1).toLongLong();
    flushBelow(blockStart);

    if (buffered.size() > kMaxBufferedInstants)
      flushBelow(buffered.rbegin()->first);

    rows.clear();
    if (!Sessions::decodeBlockRow(q, rows))
      continue;

    for (const auto& row : rows) {
      const auto colIt = uidToCol.constFind(row.uniqueId);
      if (colIt == uidToCol.constEnd())
        continue;

      auto& cells = buffered[row.timestampNs];
      if (cells.isEmpty())
        cells = QStringList(colCount);

      cells[colIt.value()] =
        row.isNumeric ? QString::number(row.finalNumeric, 'g', 17) : row.finalString;
    }
  }

  flushBelow(std::numeric_limits<qint64>::max());
  return true;
}

void Sessions::hashBlockRow(QCryptographicHash& hash,
                            qint64 uniqueId,
                            qint64 t0Ns,
                            qint64 dtNs,
                            qint64 frames,
                            const QByteArray& values,
                            const QByteArray& rawValues,
                            const QByteArray& texts)
{
  hashLe64(hash, static_cast<quint64>(uniqueId));
  hashLe64(hash, static_cast<quint64>(t0Ns));
  hashLe64(hash, static_cast<quint64>(dtNs));
  hashLe64(hash, static_cast<quint64>(frames));
  hashLe64(hash, static_cast<quint64>(values.size()));
  hash.addData(values);
  hashLe64(hash, static_cast<quint64>(rawValues.size()));
  hash.addData(rawValues);
  hashLe64(hash, static_cast<quint64>(texts.size()));
  hash.addData(texts);
}

void Sessions::ExportWorker::setTemplateFrame(const DataModel::Frame& frame)
{
  if (frame.groups.empty())
    return;

  m_templateFrame = frame;
}

void Sessions::ExportWorker::applyPublishedStructure(const DataModel::Frame& frame)
{
