[[nodiscard]] std::vector<float> makeF32Payload(int kind, std::size_t count)
{
  const auto payload = makePayload(kind, count);

  std::vector<float> out(count, 0.0f);
  for (std::size_t i = 0; i < count; ++i)
    out[i] = static_cast<float>(payload[i]);

  return out;
}

void TstDspKernels::deinterleaveToF64_data()
{
  QTest::addColumn<qsizetype>("frames");
  QTest::addColumn<int>("channels");
  QTest::addColumn<int>("kind");

  for (const qsizetype frames : kLengths)
    for (const int channels : {1, 2, 3, 4, 8})
      for (const int kind : kPayloadKinds)
        QTest::addRow(
          "%s frames=%lld ch=%d", payloadName(kind), static_cast<long long>(frames), channels)
          << frames << channels << kind;
}

void TstDspKernels::deinterleaveToF64()
{
  QFETCH(qsizetype, frames);
  QFETCH(int, channels);
  QFETCH(int, kind);

  const auto n     = static_cast<std::size_t>(frames);
  const auto total = n * static_cast<std::size_t>(channels);
  const auto src   = makeF32Payload(kind, total + 8);

  for (int channel = 0; channel < channels; ++channel) {
    std::vector<double> vec(n + 4, -1.0);
    std::vector<double> ref(n + 4, -1.0);
    DSP::simdDeinterleaveToF64(src.data(), n, channels, channel, vec.data());
    DspRef::deinterleaveToF64(src.data(), n, channels, channel, ref.data());

    for (std::size_t i = 0; i < vec.size(); ++i)
      if (!bitEqual(vec[i], ref[i]))
        QFAIL(mismatch("simdDeinterleaveToF64",
                       static_cast<qsizetype>(i),
                       std::bit_cast<quint64>(vec[i]),
                       std::bit_cast<quint64>(ref[i]))
                .constData());
  }
}

void TstDspKernels::powerSpectrumDb_data()
{
  QTest::addColumn<qsizetype>("length");
  QTest::addColumn<int>("kind");

  for (const qsizetype length : kLengths)
    for (const int kind : kPayloadKinds)
      QTest::addRow("%s len=%lld", payloadName(kind), static_cast<long long>(length))
        << length << kind;
}

void TstDspKernels::powerSpectrumDb()
{
  QFETCH(qsizetype, length);
  QFETCH(int, kind);

  const auto n     = static_cast<std::size_t>(length);
  const auto inter = makeF32Payload(kind, 2 * n + 8);
  const float norm = 1.0f / (256.0f * 256.0f);

  std::vector<float> vec(n + 4, -7.0f);
  std::vector<float> ref(n + 4, -7.0f);
  DSP::simdPowerSpectrumDb(inter.data(), vec.data(), n, norm, 1e-24f, -100.0f);
  DspRef::powerSpectrumDb(inter.data(), ref.data(), n, norm, 1e-24f, -100.0f);

  for (std::size_t i = 0; i < vec.size(); ++i)
    if (!bitEqual(vec[i], ref[i]))
      QFAIL(mismatch("simdPowerSpectrumDb",
                     static_cast<qsizetype>(i),
                     std::bit_cast<quint32>(vec[i]),
                     std::bit_cast<quint32>(ref[i]))
              .constData());
}

[[nodiscard]] double waveform(std::int64_t i)
{
  const double saw = static_cast<double>(i % 37) - 18.0;
  const double alt = (i % 5 == 0) ? 40.0 : 0.0;
  return saw + alt * ((i / 5) % 2 == 0 ? 1.0 : -1.0) + static_cast<double>(i) * 1e-3;
}

void feedCells(DSP::EnvelopeRing& ring,
               std::int64_t firstCell,
               std::int64_t cells,
               int perCell,
               std::vector<Sample>& log)
{
  const double interval = ring.level0.interval;
  for (std::int64_t c = 0; c < cells; ++c) {
    for (int s = 0; s < perCell; ++s) {
      const std::int64_t i = c * perCell + s;
      const double t       = (static_cast<double>(firstCell + c) + (s + 0.5) / perCell) * interval;
      const double v       = waveform(i);
      ring.appendDecimated(t, v);
      log.push_back({t, v});
    }
  }
}

[[nodiscard]] bool bruteForce(const DSP::EnvelopeRing& ring,
                              const std::vector<Sample>& log,
                              std::int64_t first,
                              std::int64_t last,
                              double& outMin,
                              double& outMax)
{
  bool any = false;
  outMin   = std::numeric_limits<double>::max();
  outMax   = std::numeric_limits<double>::lowest();
  for (const auto& s : log) {
    const std::int64_t idx = ring.cellIndex(s.t);
    if (idx < first || idx >= last)
      continue;

    any    = true;
    outMin = std::min(outMin, s.v);
    outMax = std::max(outMax, s.v);
  }

  return any;
}

[[nodiscard]] int checkLevels(const DSP::EnvelopeRing& ring,
                              const std::vector<Sample>& log,
                              std::int64_t openIndex0)
{
  int checked = 0;
  for (std::size_t k = 0; k < ring.levels.size(); ++k) {
    const auto& level = ring.levels[k];
    double prevT      = std::numeric_limits<double>::lowest();
    for (std::size_t c = 0; c < level.cells.size(); ++c) {
      const auto& cell         = level.cells[c];
      const std::int64_t index = ring.cellIndex(cell.t0) >> level.shift;
      const std::int64_t first = index << level.shift;
      const std::int64_t last  = (index + 1) << level.shift;

      if (!(cell.t0 <= cell.t1))
        return -1;

      if (cell.t0 < prevT)
        return -1;

      prevT = cell.t1;
      if (openIndex0 >= first && openIndex0 < last)
        continue;

      double bMin = 0;
      double bMax = 0;
      if (!bruteForce(ring, log, first, last, bMin, bMax))
        return -1;

      if (std::min(cell.v0, cell.v1) != bMin || std::max(cell.v0, cell.v1) != bMax)
        return -1;

      ++checked;
    }
  }

  return checked;
}

void TstEnvelopeRing::sizing()
{
  const DSP::EnvelopeRing tiny(1, 1.0);
  QCOMPARE(tiny.coarseLevelCount(), 0);

  const DSP::EnvelopeRing small(1024, 1.0);
  QCOMPARE(small.coarseLevelCount(), 2);
  QCOMPARE(small.levels[0].cells.capacity(), std::size_t(33));
  QCOMPARE(small.levels[1].cells.capacity(), std::size_t(3));

  const DSP::EnvelopeRing large(262144, 10.0);
  QCOMPARE(large.coarseLevelCount(), 4);
  QCOMPARE(large.levels[0].cells.capacity(), std::size_t(8193));
  QCOMPARE(large.levels[3].cells.capacity(), std::size_t(3));

  const std::size_t level0Bytes = 262144 * 2 * sizeof(double);
  std::size_t coarseBytes       = 0;
  for (const auto& level : large.levels)
    coarseBytes += level.cells.capacity() * sizeof(DSP::EnvelopeCell);

  QVERIFY(coarseBytes * 14 <= level0Bytes);
  QCOMPARE(large.levelSpanSec(1), large.level0.interval * 16.0);
  QCOMPARE(large.levelSpanSec(3), large.level0.interval * 4096.0);
}

void TstEnvelopeRing::rampMatchesBruteForce()
{
  DSP::EnvelopeRing ring(4096, 1.0);
  QCOMPARE(ring.coarseLevelCount(), 2);

  std::vector<Sample> log;
  feedCells(ring, 0, 1500, 5, log);
  QCOMPARE(ring.level0.time.size(), std::size_t(3000));

  const int checked = checkLevels(ring, log, ring.openCell);
  QVERIFY(checked > 0);
  QCOMPARE(ring.levels[0].cells.size(), std::size_t(94));
  QCOMPARE(ring.levels[1].cells.size(), std::size_t(6));

  const std::int64_t sentinel = 4096LL * 64;
  ring.appendDecimated(static_cast<double>(sentinel) * ring.level0.interval, 0.0);
  log.push_back({static_cast<double>(sentinel) * ring.level0.interval, 0.0});
  QCOMPARE(checkLevels(ring, log, sentinel), 100);
}

void TstEnvelopeRing::wrapKeepsLevelsConsistent()
{
  DSP::EnvelopeRing ring(1024, 1.0);
  QCOMPARE(ring.coarseLevelCount(), 2);

  std::vector<Sample> log;
  feedCells(ring, 0, 5000, 3, log);
  QVERIFY(ring.level0.time.full());
  QVERIFY(ring.levels[0].cells.full());
  QVERIFY(ring.levels[1].cells.full());

  QVERIFY(checkLevels(ring, log, ring.openCell) > 0);

  const std::int64_t oldest0 = ring.cellIndex(ring.level0.time[0]);
  for (const auto& level : ring.levels) {
    const std::int64_t front = ring.cellIndex(level.cells.front().t0) >> level.shift;
    QVERIFY((front << level.shift) <= oldest0);
  }
}

void TstEnvelopeRing::resizeRebuildsLevels()
{
  DSP::EnvelopeRing ring(1024, 1.0);
  std::vector<Sample> log;
  feedCells(ring, 0, 700, 3, log);

  ring.resizeCapacity(4096, 1.0);
  QCOMPARE(ring.level0.time.capacity(), std::size_t(4096));
  QCOMPARE(ring.coarseLevelCount(), 2);
  QVERIFY(!ring.openCellValid);

  std::vector<Sample> retained;
  for (std::size_t k = 0; k < ring.level0.time.size(); ++k)
    retained.push_back({ring.level0.time[k], ring.level0.value[k]});

  QVERIFY(checkLevels(ring, retained, std::numeric_limits<std::int64_t>::min()) > 0);

  const std::int64_t nextCell = ring.cellIndex(ring.level0.time[ring.level0.time.size() - 1]) + 1;
  feedCells(ring, nextCell, 200, 5, retained);
  QVERIFY(ring.openCellValid);
  QVERIFY(checkLevels(ring, retained, ring.openCell) > 0);
}

void TstEnvelopeRing::levelSelection()
{
  DSP::EnvelopeRing ring(4096, 1.0);
  std::vector<Sample> log;
  feedCells(ring, 0, 1500, 5, log);

  const double interval = ring.level0.interval;
  const double oldest   = ring.level0.time[0];

  QCOMPARE(ring.selectLevel(100.0 * interval * 8.0, 100, oldest), 0);
  QCOMPARE(ring.selectLevel(100.0 * interval * 16.0, 100, oldest), 1);
  QCOMPARE(ring.selectLevel(100.0 * interval * 255.0, 100, oldest), 1);
  QCOMPARE(ring.selectLevel(100.0 * interval * 256.0, 100, oldest), 2);
  QCOMPARE(ring.selectLevel(100.0 * interval * 100000.0, 100, oldest), 2);

  QCOMPARE(ring.selectLevel(0.0, 100, oldest), 0);
  QCOMPARE(ring.selectLevel(1.0, 0, oldest), 0);
  QCOMPARE(ring.selectLevel(1.0, 100, std::numeric_limits<double>::quiet_NaN()), 0);

  const DSP::EnvelopeRing empty(4096, 1.0);
  QCOMPARE(empty.selectLevel(1.0, 10, 0.0), 0);
}

void TstEnvelopeRing::coverageFallback()
{
  DSP::EnvelopeRing ring(4096, 1.0);
  std::vector<Sample> log;
  feedCells(ring, 0, 3000, 5, log);
  QVERIFY(ring.levels[0].cells.full());

  const double interval = ring.level0.interval;
  const double wide     = 100.0 * interval * 16.0;

  QCOMPARE(ring.selectLevel(wide, 100, ring.level0.time[0]), 1);

  const std::int64_t front1 = ring.cellIndex(ring.levels[0].cells.front().t0) >> 4;
  const double tooOld       = static_cast<double>((front1 - 1) << 4) * interval;
  QCOMPARE(ring.selectLevel(wide, 100, tooOld), 0);
}

void TstEnvelopeRing::rejectsNonFinite()
{
  DSP::EnvelopeRing ring(1024, 1.0);
  std::vector<Sample> log;
  feedCells(ring, 0, 100, 4, log);

  const std::size_t n0    = ring.level0.time.size();
  const std::size_t n1    = ring.levels[0].cells.size();
  const std::size_t n2    = ring.levels[1].cells.size();
  const std::int64_t open = ring.openCell;
  const double nan        = std::numeric_limits<double>::quiet_NaN();
  const double inf        = std::numeric_limits<double>::infinity();
  const double t          = ring.level0.time[n0 - 1] + 100.0;
  const double values[]   = {nan, inf, -inf};
  for (const double bad : values) {
    ring.appendDecimated(bad, 1.0);
    ring.appendDecimated(t, bad);
  }

  QCOMPARE(ring.level0.time.size(), n0);
  QCOMPARE(ring.levels[0].cells.size(), n1);
  QCOMPARE(ring.levels[1].cells.size(), n2);
  QCOMPARE(ring.openCell, open);
  QVERIFY(ring.openCellValid);
}

void TstEnvelopeRing::downsampleReadsCoarseLevel()
{
  DSP::EnvelopeRing ring(4096, 1.0);
  std::vector<Sample> log;
  feedCells(ring, 0, 1500, 5, log);

  const double interval = ring.level0.interval;
  DSP::DownsampleWorkspace ws;
  QList<QPointF> viaRing;
  QList<QPointF> viaLevel0;

  const double narrow = 50.0 * interval;
  QVERIFY(DSP::downsampleTimeWindow(ring, -narrow, 0.0, 100, 100, viaRing, &ws));
  QVERIFY(DSP::downsampleTimeWindow(
    ring.level0.time, ring.level0.value, -narrow, 0.0, 100, 100, viaLevel0, &ws));
  QCOMPARE(viaRing, viaLevel0);

  const double wide = 1400.0 * interval;
  QCOMPARE(ring.selectLevel(wide, 50, ring.level0.time[0]), 1);
  QVERIFY(DSP::downsampleTimeWindow(ring, -wide, 0.0, 50, 100, viaRing, &ws));
  QVERIFY(!viaRing.isEmpty());
  QVERIFY(viaRing.size() <= 50 * 4);
  for (const auto& p : viaRing) {
    QVERIFY(p.x() >= -wide);
    QVERIFY(p.x() <= 0.0);
    QVERIFY(std::isfinite(p.y()));
  }
}

[[nodiscard]] double evalWith(const QString& text,
                              SlotTable& slots,
                              double v,
                              QString* error = nullptr)
{
  const NameResolver resolver = [&slots](QStringView name) -> int {
    if (name == u"a")
      return slots.slotFor(10);

    if (name == u"b")
      return slots.slotFor(11);

    if (name == u"Long Name")
      return slots.slotFor(12);

    return -1;
  };

  Runtime runtime;
  QString err;
  if (!compile(text, resolver, runtime.program, err)) {
    if (error)
      *error = err;

    return std::numeric_limits<double>::quiet_NaN();
  }

  return runtime.run(v, 0.0, slots);
}

[[nodiscard]] double evalPlain(const QString& text, double v)
{
  SlotTable slots;
  return evalWith(text, slots, v);
}

double fakeTableValue(const void*, qint64 handle)
{
  const qint64 count = static_cast<qint64>(sizeof(kFakeRegisters) / sizeof(kFakeRegisters[0]));
  return (handle >= 0 && handle < count) ? kFakeRegisters[handle]
                                         : std::numeric_limits<double>::quiet_NaN();
}

void TstExpressionTransform::tableRegisters()
{
  const NameResolver names = [](QStringView) {
    return -1;
  };
  const TableResolver tables = [](QStringView table, QStringView reg) -> qint64 {
    if (table == u"cal" && reg == u"scale")
      return 0;

    if (table == u"cal" && reg == u"offset")
      return 1;

    return -1;
  };

  SlotTable slots;
  Runtime runtime;
  QString error;
  QVERIFY2(
    compile("v * table(cal, scale) + table(cal, offset)", names, tables, runtime.program, error),
    qPrintable(error));

  runtime.tableValue = &fakeTableValue;
  QCOMPARE(runtime.run(4.0, 0.0, slots), 9.0);

  Program program;
  QVERIFY(!compile("table(cal, missing)", names, tables, program, error));
  QVERIFY(error.contains(QStringLiteral("unknown register")));

  QVERIFY(!compile("table(cal, scale)", names, program, error));
  QVERIFY(error.contains(QStringLiteral("not available")));
}

void TstExpressionTransform::arithmeticAndPrecedence()
{
  QCOMPARE(evalPlain("v * 0.0625 - 40", 1600.0), 60.0);
  QCOMPARE(evalPlain("1 + 2 * 3", 0.0), 7.0);
  QCOMPARE(evalPlain("(1 + 2) * 3", 0.0), 9.0);
  QCOMPARE(evalPlain("2 ^ 3 ^ 2", 0.0), 512.0);
  QCOMPARE(evalPlain("-2 ^ 2", 0.0), 4.0);
  QCOMPARE(evalPlain("7 % 4", 0.0), 3.0);
  QCOMPARE(evalPlain("-v", 3.0), -3.0);
  QCOMPARE(evalPlain("+v", 3.0), 3.0);
  QCOMPARE(evalPlain("1e3 + 2.5e-1", 0.0), 1000.25);
  QCOMPARE(evalPlain(".5 * 4", 0.0), 2.0);
}

void TstExpressionTransform::functionsAndConstants()
{
  QCOMPARE(evalPlain("sqrt(v)", 16.0), 4.0);
  QCOMPARE(evalPlain("abs(v)", -2.5), 2.5);
  QCOMPARE(evalPlain("min(v, 3)", 5.0), 3.0);
  QCOMPARE(evalPlain("max(v, 3)", 5.0), 5.0);
  QCOMPARE(evalPlain("clamp(v, 0, 1)", 5.0), 1.0);
  QCOMPARE(evalPlain("lerp(0, 10, 0.25)", 0.0), 2.5);
  QCOMPARE(evalPlain("hypot(3, 4)", 0.0), 5.0);
  QCOMPARE(evalPlain("pow(2, 10)", 0.0), 1024.0);
  QCOMPARE(evalPlain("floor(2.7) + ceil(2.2) + round(2.5)", 0.0), 8.0);
  QCOMPARE(evalPlain("log10(1000)", 0.0), 3.0);
  QCOMPARE(evalPlain("log2(8)", 0.0), 3.0);
  QCOMPARE(evalPlain("deg(pi)", 0.0), 180.0);
  QCOMPARE(evalPlain("rad(180)", 0.0), M_PI);
  QCOMPARE(evalPlain("cos(0) + sin(0)", 0.0), 1.0);
  QCOMPARE(evalPlain("atan2(0, 1)", 0.0), 0.0);
  QCOMPARE(evalPlain("e", 0.0), M_E);
  QVERIFY(std::isnan(evalPlain("nan", 0.0)));
  QVERIFY(std::isinf(evalPlain("inf", 0.0)));
  QVERIFY(std::isinf(evalPlain("1 / 0", 0.0)));
}

void TstExpressionTransform::comparisonsAndConditional()
{
  QCOMPARE(evalPlain("v > 2", 3.0), 1.0);
  QCOMPARE(evalPlain("v > 2", 1.0), 0.0);
  QCOMPARE(evalPlain("v >= 2 && v <= 4", 3.0), 1.0);
  QCOMPARE(evalPlain("v < 2 || v == 3", 3.0), 1.0);
  QCOMPARE(evalPlain("v != 3", 3.0), 0.0);
  QCOMPARE(evalPlain("!(v > 0)", 3.0), 0.0);
  QCOMPARE(evalPlain("v > 0 ? v : -v", -4.0), 4.0);
  QCOMPARE(evalPlain("v > 10 ? 1 : v > 5 ? 2 : 3", 7.0), 2.0);
  QCOMPARE(evalPlain("(v > 1) + (v > 2)", 3.0), 2.0);
}

void TstExpressionTransform::siblingNames()
{
  SlotTable slots;
  QVERIFY(std::isnan(evalWith("a + b", slots, 0.0)));

  slots.publish(10, 2.0);
  slots.publish(11, 5.0);
  QCOMPARE(evalWith("a + b", slots, 0.0), 7.0);
  QCOMPARE(evalWith("v - a", slots, 10.0), 8.0);

  slots.publish(12, 100.0);
  QCOMPARE(evalWith("{Long Name} / 4", slots, 0.0), 25.0);
  QCOMPARE(evalWith("{ Long Name } / 4", slots, 0.0), 25.0);

  slots.publish(99, 1.0);
  QCOMPARE(slots.slotOf(99), -1);
  QCOMPARE(slots.slotCount(), 3);
  QCOMPARE(slots.uniqueIdAt(0), 10);
}

void TstExpressionTransform::sampleHistory()
{
  SlotTable slots;
  const NameResolver resolver = [&slots](QStringView name) -> int {
    return (name == u"x") ? slots.slotFor(7) : -1;
  };

  Runtime runtime;
  QString error;
  QVERIFY(compile(
    "sample(x, 0) + 10 * sample(x, 1) + 100 * sample(x, 2)", resolver, runtime.program, error));
  QVERIFY(runtime.program.usesHistory);
  QVERIFY(std::isnan(runtime.run(0.0, 0.0, slots)));

  slots.publish(7, 1.0);
  slots.publish(7, 2.0);
  slots.publish(7, 3.0);
  QCOMPARE(runtime.run(0.0, 0.0, slots), 3.0 + 20.0 + 100.0);

  for (int i = 0; i < kMaxHistory + 5; ++i)
    slots.publish(7, static_cast<double>(i));

  QCOMPARE(slots.sample(0, 0), static_cast<double>(kMaxHistory + 4));
  QCOMPARE(slots.sample(0, kMaxHistory - 1), 5.0);
  QVERIFY(std::isnan(slots.sample(0, kMaxHistory)));
  QVERIFY(std::isnan(slots.sample(0, -1)));
  QVERIFY(std::isnan(slots.sample(3, 0)));

  Runtime negative;
  QVERIFY(compile("sample(x, -3)", resolver, negative.program, error));
  QCOMPARE(negative.run(0.0, 0.0, slots), slots.sample(0, 0));

  slots.reset();
  QVERIFY(std::isnan(slots.sample(0, 0)));
  QCOMPARE(slots.slotCount(), 1);
}

void TstExpressionTransform::countersAndDt()
{
  SlotTable slots;
  Runtime runtime;
  QString error;
  QVERIFY(compile("n * 1000 + dt", [](QStringView) { return -1; }, runtime.program, error));

  QCOMPARE(runtime.run(0.0, 10.0, slots), 0.0);
  QCOMPARE(runtime.run(0.0, 10.5, slots), 1000.5);
  QCOMPARE(runtime.run(0.0, 12.0, slots), 2001.5);

  runtime.reset();
  QCOMPARE(runtime.run(0.0, 20.0, slots), 0.0);
}

void TstExpressionTransform::compileErrors()
{
  SlotTable slots;
  QString error;

  QVERIFY(std::isnan(evalWith("sqtr(v)", slots, 1.0, &error)));
  QVERIFY(error.contains(QStringLiteral("sqtr")));

  QVERIFY(std::isnan(evalWith("zz + 1", slots, 1.0, &error)));
  QVERIFY(error.contains(QStringLiteral("zz")));

  QVERIFY(std::isnan(evalWith("(1 + 2", slots, 1.0, &error)));
  QVERIFY(!error.isEmpty());

  QVERIFY(std::isnan(evalWith("1 +", slots, 1.0, &error)));
  QVERIFY(std::isnan(evalWith("", slots, 1.0, &error)));
  QVERIFY(std::isnan(evalWith("min(1)", slots, 1.0, &error)));
  QVERIFY(std::isnan(evalWith("sample(1, 2)", slots, 1.0, &error)));
  QVERIFY(std::isnan(evalWith("1 2", slots, 1.0, &error)));
  QVERIFY(std::isnan(evalWith("1.2.3", slots, 1.0, &error)));
  QVERIFY(std::isnan(evalWith("{unterminated", slots, 1.0, &error)));
  QVERIFY(std::isnan(evalWith("v $ 2", slots, 1.0, &error)));

  Program program;
  QVERIFY(compile("v", [](QStringView) { return -1; }, program, error));
  QVERIFY(program.valid());
  QCOMPARE(program.maxSlot, -1);
  QVERIFY(!program.usesHistory);
}

void TstExpressionTransform::nanPropagatesAndDegenerateProgram()
{
  QVERIFY(std::isnan(evalPlain("v * 2", std::numeric_limits<double>::quiet_NaN())));
  QVERIFY(std::isnan(evalPlain("sqrt(v)", -1.0)));

  Program broken;
  broken.code.push_back(Node{Op::Add, 0, 0.0});
  broken.stackDepth = 1;

  Context ctx{};
  ctx.v = 1.0;
  QVERIFY(std::isnan(evaluate(broken, ctx)));

  Program empty;
  QVERIFY(std::isnan(evaluate(empty, ctx)));
}

void TstPlotAutoScale::ladderIsMonotonic()
{
  using namespace Widgets::AutoScale;
  QCOMPARE(ladderStep(0), 1.0);
  QCOMPARE(ladderStep(1), 2.0);
  QCOMPARE(ladderStep(2), 5.0);
  QCOMPARE(ladderStep(3), 10.0);
  QCOMPARE(ladderStep(-1), 0.5);
  QCOMPARE(ladderStep(-2), 0.2);
  QCOMPARE(ladderStep(-3), 0.1);
  QCOMPARE(ladderStep(-4), 0.05);

  for (int i = kMinStepIndex; i < kMaxStepIndex; ++i)
    QVERIFY(ladderStep(i) < ladderStep(i + 1));
}

void TstPlotAutoScale::ladderIndexPicksFirstFit()
{
  using namespace Widgets::AutoScale;
  QCOMPARE(ladderIndexFor(1.0), 0);
  QCOMPARE(ladderIndexFor(1.5), 1);
  QCOMPARE(ladderIndexFor(2.0), 1);
  QCOMPARE(ladderIndexFor(3.0), 2);
  QCOMPARE(ladderIndexFor(5.0), 2);
  QCOMPARE(ladderIndexFor(7.0), 3);
  QCOMPARE(ladderIndexFor(0.3), -1);
  QCOMPARE(ladderIndexFor(0.05), -4);
  QCOMPARE(ladderIndexFor(0.0), 0);
  QCOMPARE(ladderIndexFor(std::numeric_limits<double>::quiet_NaN()), 0);
}

void TstPlotAutoScale::firstQuantizationFitsExtent()
{
  using namespace Widgets::AutoScale;
  double min = 0.13;
  double max = 7.9;
  int index  = kNoStep;
  QVERIFY(quantizeRange(min, max, index));
  QCOMPARE(index, ladderIndexFor((7.9 - 0.13) / kDivisions));
  QCOMPARE(ladderStep(index), 1.0);
  QCOMPARE(min, 0.0);
  QCOMPARE(max, 8.0);
  QVERIFY(min <= 0.13);
  QVERIFY(max >= 7.9);
}

void TstPlotAutoScale::bipolarRangeSplitsAtZero()
{
  using namespace Widgets::AutoScale;
  double min = -0.37;
  double max = 1.42;
  int index  = kNoStep;
  QVERIFY(quantizeRange(min, max, index));
  const double step = ladderStep(index);
  QCOMPARE(step, 0.5);
  QVERIFY(std::fmod(min, step) == 0.0);
  QVERIFY(std::fmod(max, step) == 0.0);
  QCOMPARE(min, -0.5);
  QCOMPARE(max, 1.5);
}

void TstPlotAutoScale::positiveRangeIsNotForcedToZero()
{
  using namespace Widgets::AutoScale;
  double min = 100.3;
  double max = 104.1;
  int index  = kNoStep;
  QVERIFY(quantizeRange(min, max, index));
  QCOMPARE(ladderStep(index), 0.5);
  QCOMPARE(min, 100.0);
  QCOMPARE(max, 104.5);
}

void TstPlotAutoScale::growsImmediatelyShrinksWithMargin()
{
  using namespace Widgets::AutoScale;
  int index  = kNoStep;
  double min = 0.0;
  double max = 8.0;
  QVERIFY(quantizeRange(min, max, index));
  QCOMPARE(ladderStep(index), 1.0);

  min = 0.0;
  max = 8.4;
  QVERIFY(quantizeRange(min, max, index));
  QCOMPARE(ladderStep(index), 2.0);
  QCOMPARE(max, 10.0);

  min = 0.0;
  max = 7.9;
  QVERIFY(quantizeRange(min, max, index));
  QCOMPARE(ladderStep(index), 2.0);

  min = 0.0;
  max = 6.5;
  QVERIFY(quantizeRange(min, max, index));
  QCOMPARE(ladderStep(index), 2.0);

  min = 0.0;
  max = 6.3;
  QVERIFY(quantizeRange(min, max, index));
  QCOMPARE(ladderStep(index), 1.0);
  QCOMPARE(max, 7.0);

  min = 0.0;
  max = 1.0;
  QVERIFY(quantizeRange(min, max, index));
  QCOMPARE(ladderStep(index), 0.2);
}

void TstPlotAutoScale::rejectsDegenerateInput()
{
  using namespace Widgets::AutoScale;
  int index  = 3;
  double min = 2.0;
  double max = 2.0;
  QVERIFY(!quantizeRange(min, max, index));
  QCOMPARE(index, 3);
  QCOMPARE(min, 2.0);

  min = std::numeric_limits<double>::quiet_NaN();
  max = 5.0;
  QVERIFY(!quantizeRange(min, max, index));
  QCOMPARE(index, 3);

  min = 1.0;
  max = std::numeric_limits<double>::infinity();
  QVERIFY(!quantizeRange(min, max, index));
  QCOMPARE(index, 3);
}

[[nodiscard]] std::vector<float> makeSignal(int n)
{
  std::vector<float> out(static_cast<std::size_t>(n), 0.0f);

  quint32 state = 0x12345678u;
  for (int i = 0; i < n; ++i) {
    state          = state * 1664525u + 1013904223u;
    const double t = static_cast<double>(i);
    const double v = 1.75 + 3.0 * std::sin(kTwoPi * t * 5.0 / n)
                   + 0.5 * std::cos(kTwoPi * t * 17.0 / n) + 0.25 * std::sin(kTwoPi * t * 0.37)
                   + 1e-3 * static_cast<double>(state >> 16) / 65536.0;
    out[static_cast<std::size_t>(i)] = static_cast<float>(v);
  }

  return out;
}

void TstRealFft::realMatchesComplex_data()
{
  QTest::addColumn<int>("size");

  for (const int size : kSizes)
    QTest::addRow("n=%d", size) << size;
}

void TstRealFft::realMatchesComplex()
{
  QFETCH(int, size);

  const auto signal = makeSignal(size);
  const auto n      = static_cast<std::size_t>(size);
  const int bins    = size / 2 + 1;

  std::vector<kiss_fft_cpx> complexIn(n);
  for (std::size_t i = 0; i < n; ++i) {
    complexIn[i].r = signal[i];
    complexIn[i].i = 0.0f;
  }

  std::vector<kiss_fft_cpx> complexOut(n);
  kiss_fft_cfg complexPlan = kiss_fft_alloc(size, 0, nullptr, nullptr);
  QVERIFY(complexPlan != nullptr);
  kiss_fft(complexPlan, complexIn.data(), complexOut.data());
  kiss_fft_free(complexPlan);

  std::vector<kiss_fft_cpx> realOut(static_cast<std::size_t>(bins));
  kiss_fftr_cfg realPlan = kiss_fftr_alloc(size, 0, nullptr, nullptr);
  QVERIFY(realPlan != nullptr);
  kiss_fftr(realPlan, signal.data(), realOut.data());
  kiss_fftr_free(realPlan);

  float peak = 0.0f;
  for (int k = 0; k < bins; ++k) {
    const float re = complexOut[static_cast<std::size_t>(k)].r;
    const float im = complexOut[static_cast<std::size_t>(k)].i;
    peak           = std::max(peak, std::sqrt(re * re + im * im));
  }

  QVERIFY(peak > 0.0f);

  for (int k = 0; k < bins; ++k) {
    const auto idx  = static_cast<std::size_t>(k);
    const float dr  = realOut[idx].r - complexOut[idx].r;
    const float di  = realOut[idx].i - complexOut[idx].i;
    const float err = std::sqrt(dr * dr + di * di) / peak;
    if (err > kRelTolerance)
      QFAIL(QByteArray("bin ") + QByteArray::number(k) + " of " + QByteArray::number(size)
            + " diverged by " + QByteArray::number(static_cast<double>(err)) + " of peak");
  }
}

explicit FixtureDb(const QString& fileName, const QString& connection) : m_connection(connection)
  {
    const QString source = QStringLiteral(SS_FIXTURE_DIR "/%1").arg(fileName);
    m_copy               = m_dir.filePath(fileName);
    m_copied             = QFile::copy(source, m_copy);

    m_db = QSqlDatabase::addDatabase(QStringLiteral("QSQLITE"), m_connection);
    m_db.setDatabaseName(m_copy);
    m_opened = m_db.open();
  }

~FixtureDb()
  {
    if (m_db.isOpen())
      m_db.close();

    m_db = QSqlDatabase();
    QSqlDatabase::removeDatabase(m_connection);
  }

[[nodiscard]] int userVersion()
  {
    QSqlQuery q(m_db);
    return (q.exec(QStringLiteral("PRAGMA user_version")) && q.next()) ? q.value(0).toInt() : -1;
  }

[[nodiscard]] int scalar(const QString& sql)
  {
    QSqlQuery q(m_db);
    return (q.exec(sql) && q.next()) ? q.value(0).toInt() : -1;
  }

