void StreamBlockCodecTest::truncatedTextBlobIsRejected()
{
  const std::vector<QString> pair{QStringLiteral("abcd"), QStringLiteral("efgh")};
  QByteArray blob = Sessions::packStreamText(pair);
  blob.chop(2);

  std::vector<QString> output;
  QVERIFY(!Sessions::unpackStreamText(blob, 2, output));
}

void StreamBlockCodecTest::overlongTextBlobIsRejected()
{
  const std::vector<QString> single{QStringLiteral("abcd")};
  QByteArray blob = Sessions::packStreamText(single);
  blob.append('x');

  std::vector<QString> output;
  QVERIFY(!Sessions::unpackStreamText(blob, 1, output));
  QVERIFY(!Sessions::unpackStreamText(blob, 2, output));
}

class BlockCollector : public QObject {
  Q_OBJECT

public:
  explicit BlockCollector(StreamWorker& worker)
  {
    connect(
      worker.processor(),
      &StreamProcessor::blockReady,
      this,
      [this](const DataBlockPtr& block) {
        if (block)
          m_blocks.push_back(block);
      },
      Qt::QueuedConnection);
  }

  [[nodiscard]] const std::vector<DataBlockPtr>& blocks() const noexcept { return m_blocks; }

[[nodiscard]] double latest() const
  {
    for (auto it = m_blocks.rbegin(); it != m_blocks.rend(); ++it) {
      const auto& block = **it;
      if (block.columns.empty() || block.samples <= 0)
        continue;

      return block.columns.front().values[static_cast<std::size_t>(block.samples - 1)];
    }

    return 0.0;
  }

void runSweep(DSP::SweepEngine& engine, double start, double amplitude)
{
  (void)engine.advance(start - 0.001, -1.0);
  const double window = engine.activeWindow();
  const int steps     = 20;
  for (int i = 0; i <= steps; ++i) {
    const double t  = start + window * static_cast<double>(i) / steps;
    const double st = engine.advance(t, amplitude);
    if (st >= 0.0)
      engine.back[0].appendDecimated(st, amplitude);
  }

  (void)engine.advance(start + window * 1.05, amplitude);
}

void TstSweepSegments::retentionClampsToBudget()
{
  DSP::SweepEngine engine;
  engine.configure(1, 1024, 1.0);
  QCOMPARE(engine.segmentCapacity(), 0);

  engine.setSegmentRetention(8);
  QCOMPARE(engine.segmentCapacity(), 8);
  QCOMPARE(engine.segmentCount(), 0);

  engine.setSegmentRetention(1000);
  QCOMPARE(engine.segmentCapacity(), DSP::SweepEngine::kMaxSegments);

  DSP::SweepEngine big;
  big.configure(4, 262144, 10.0);
  big.setSegmentRetention(64);
  const std::size_t perSegment = 4u * 262144u * DSP::SweepEngine::kSegmentSlotBytes;
  QVERIFY(static_cast<std::size_t>(big.segmentCapacity()) * perSegment
          <= DSP::SweepEngine::kMaxSegmentBytes);
  QVERIFY(big.segmentCapacity() >= 1);
  QVERIFY(big.segmentCapacity() < 64);

  engine.setSegmentRetention(0);
  QCOMPARE(engine.segmentCapacity(), 0);
}

void TstSweepSegments::completedSweepsAreRetainedNewestFirst()
{
  DSP::SweepEngine engine;
  engine.configure(1, 256, 0.01);
  engine.setTrigger(0.0, DSP::SweepEngine::kRising, DSP::SweepEngine::kNormal, 0.0, 0);
  engine.enabled = true;
  engine.setSegmentRetention(4);

  runSweep(engine, 1.0, 1.0);
  runSweep(engine, 2.0, 2.0);
  runSweep(engine, 3.0, 3.0);
  QCOMPARE(engine.segmentCount(), 3);

  const DSP::SweepSegment* newest = engine.segment(0);
  const DSP::SweepSegment* oldest = engine.segment(2);
  QVERIFY(newest != nullptr);
  QVERIFY(oldest != nullptr);
  QVERIFY(newest->triggerSec > oldest->triggerSec);
  QCOMPARE(newest->curves.size(), std::size_t(1));
  QVERIFY(newest->curves.front().value.size() > 0);
  QCOMPARE(newest->curves.front().value[0], 3.0);
  QCOMPARE(oldest->curves.front().value[0], 1.0);
  QVERIFY(engine.segment(3) == nullptr);
  QVERIFY(engine.segment(-1) == nullptr);
}

void TstSweepSegments::segmentsAreDeepCopies()
{
  DSP::SweepEngine engine;
  engine.configure(1, 256, 0.01);
  engine.setTrigger(0.0, DSP::SweepEngine::kRising, DSP::SweepEngine::kNormal, 0.0, 0);
  engine.enabled = true;
  engine.setSegmentRetention(2);

  runSweep(engine, 1.0, 5.0);
  const DSP::SweepSegment* first = engine.segment(0);
  QVERIFY(first != nullptr);
  const std::size_t n = first->curves.front().value.size();
  QVERIFY(n > 0);

  runSweep(engine, 2.0, 7.0);
  runSweep(engine, 3.0, 9.0);
  const DSP::SweepSegment* stillFirst = engine.segment(1);
  QVERIFY(stillFirst != nullptr);
  QCOMPARE(stillFirst->curves.front().value[0], 7.0);
  QCOMPARE(engine.segment(0)->curves.front().value[0], 9.0);
  QVERIFY(engine.front[0].value.size() > 0);
  QVERIFY(engine.front[0].value.raw() != stillFirst->curves.front().value.raw());
}

void TstSweepSegments::wrapAndClear()
{
  DSP::SweepEngine engine;
  engine.configure(1, 256, 0.01);
  engine.setTrigger(0.0, DSP::SweepEngine::kRising, DSP::SweepEngine::kNormal, 0.0, 0);
  engine.enabled = true;
  engine.setSegmentRetention(3);

  for (int i = 1; i <= 5; ++i)
    runSweep(engine, static_cast<double>(i), static_cast<double>(i));

  QCOMPARE(engine.segmentCount(), 3);
  QCOMPARE(engine.segment(0)->curves.front().value[0], 5.0);
  QCOMPARE(engine.segment(2)->curves.front().value[0], 3.0);

  engine.clearSegments();
  QCOMPARE(engine.segmentCount(), 0);
  QCOMPARE(engine.segmentCapacity(), 3);

  runSweep(engine, 10.0, 1.0);
  QCOMPARE(engine.segmentCount(), 1);

  engine.resetState();
  QCOMPARE(engine.segmentCount(), 0);
}

void TstSweepSegments::takeoverRequiresSameShape()
{
  DSP::SweepEngine source;
  source.configure(1, 256, 0.01);
  source.setTrigger(0.0, DSP::SweepEngine::kRising, DSP::SweepEngine::kNormal, 0.0, 0);
  source.enabled = true;
  source.setSegmentRetention(2);
  runSweep(source, 1.0, 4.0);
  QCOMPARE(source.segmentCount(), 1);

  DSP::SweepEngine same;
  same.configure(1, 256, 0.01);
  same.takeSegmentsFrom(source);
  QCOMPARE(same.segmentCapacity(), 2);
  QCOMPARE(same.segmentCount(), 1);
  QCOMPARE(same.segment(0)->curves.front().value[0], 4.0);

  DSP::SweepEngine wider;
  wider.configure(2, 256, 0.01);
  wider.takeSegmentsFrom(source);
  QCOMPARE(wider.segmentCapacity(), 2);
  QCOMPARE(wider.segmentCount(), 0);

  DSP::SweepEngine bigger;
  bigger.configure(1, 512, 0.01);
  bigger.takeSegmentsFrom(source);
  QCOMPARE(bigger.segmentCapacity(), 2);
  QCOMPARE(bigger.segmentCount(), 0);
}

bool API::Server::hasStreamSubscribers() const noexcept
{
  for (auto it = m_connections.constBegin(); it != m_connections.constEnd(); ++it)
    if (it.value().streamSubscribed)
      return true;

  return false;
}

void DataModel::FrameBuilder::refreshFramePoolBudget(const DataModel::Frame& src) noexcept
{
  std::size_t datasets = 0;
  for (const auto& group : src.groups)
    datasets += group.datasets.size();

  const std::size_t bytes = sizeof(DataModel::Frame) + src.groups.size() * sizeof(DataModel::Group)
                          + datasets * sizeof(DataModel::Dataset);

  m_poolPolicy.applyMemoryBudget(bytes, kFramePoolBudgetBytes);
}

DataModel::TimestampedFramePtr DataModel::FrameBuilder::acquireReusedFrame(
  const DataModel::Frame& src)
{
  const size_t idx = claimPoolSlot(src.sourceId, true);
  if (idx == kInvalidSlotIdx)
    return {};

  const auto& slotOwner = m_framePool[idx];
  auto* slotRaw         = slotOwner.get();

  if (preparePooledSlot(slotRaw, src)) [[likely]]
    copy_frame_values(slotRaw->frame.data, src);

  slotRaw->frame.timestamp           = DataModel::TimestampedFrame::SteadyClock::now();
  slotRaw->frame.structureGeneration = m_framePoolGeneration;

  return TimestampedFramePtr(slotOwner, &slotRaw->frame);
}

bool DataModel::FrameBuilder::emitRepublishedFrame(const DataModel::Frame& frame,
                                                   int key,
                                                   bool feedExports)
{
  static auto& pipeline = IO::PipelineHost::instance();

  if (feedExports) {
    m_republishedSourceIds.insert(key);
    hotpathTxFrame(acquireFrame(frame));
    return true;
  }

  auto pooled = acquireReusedFrame(frame);
  if (!pooled)
    return false;

  m_republishedSourceIds.insert(key);
  pipeline.publishFrameToDashboard(pooled);
  return true;
}

void DataModel::FramePoolPolicy::releaseOwnership() noexcept
{
  std::fill(m_owner.begin(), m_owner.end(), kUnowned);
  m_hintBySource.clear();
}

void DataModel::FramePoolPolicy::applyMemoryBudget(std::size_t frameBytes,
                                                   std::size_t budgetBytes) noexcept
{
  if (frameBytes == 0 || budgetBytes == 0) {
    setSlotBudget(m_owner.size());
    return;
  }

  setSlotBudget(budgetBytes / frameBytes);
}

std::size_t DataModel::FramePoolPolicy::adopt(int sourceId, std::size_t idx) noexcept
{
  m_owner[idx] = sourceId;
  m_hintBySource.insert(sourceId, idx);
  m_walkHint = idx;
  return idx;
}

[[nodiscard]] auto fn() const
  {
    return [this](std::size_t idx) {
      return !m_pinned[idx];
    };
  }

void FramePoolPolicyTest::steadyStateNeverMaterialisesNewSlots()
{
  FramePoolPolicy policy(64);
  Liveness live(64);

  for (int i = 0; i < 500; ++i) {
    const auto [idx, pick] = policy.claim(0, false, live.fn());
    QVERIFY(idx != FramePoolPolicy::kInvalidSlot);
    Q_UNUSED(pick)
  }

  QCOMPARE(policy.materialised(), std::size_t(1));
  QCOMPARE(policy.stats().virginWalk, quint64(1));
  QCOMPARE(policy.stats().hintReuse, quint64(499));
}

void FramePoolPolicyTest::pinnedSlotWalksToWarmSlotNotVirgin()
{
  FramePoolPolicy policy(64);
  Liveness live(64);

  const auto first = policy.claim(0, false, live.fn());
  live.pin(first.first);

  const auto second = policy.claim(0, false, live.fn());
  QCOMPARE(second.second, SlotPick::VirginWalk);
  live.pin(second.first);

  live.releaseAll();
  live.pin(second.first);

  const auto third = policy.claim(0, false, live.fn());
  QCOMPARE(third.second, SlotPick::WarmWalk);
  QCOMPARE(third.first, first.first);
  QCOMPARE(policy.materialised(), std::size_t(2));
}

void FramePoolPolicyTest::hintedOnlyRefusesRatherThanMaterialise()
{
  FramePoolPolicy policy(64);
  Liveness live(64);

  const auto first = policy.claim(0, false, live.fn());
  live.pin(first.first);

  const auto refused = policy.claim(0, true, live.fn());
  QCOMPARE(refused.first, FramePoolPolicy::kInvalidSlot);
  QCOMPARE(refused.second, SlotPick::None);
  QCOMPARE(policy.materialised(), std::size_t(1));

  live.releaseAll();
  const auto reused = policy.claim(0, true, live.fn());
  QCOMPARE(reused.first, first.first);
  QCOMPARE(reused.second, SlotPick::HintReuse);
}

void FramePoolPolicyTest::memoryBudgetCapsMaterialisedSlots()
{
  FramePoolPolicy policy(8192);
  Liveness live(8192);

  policy.applyMemoryBudget(512 * 1024, 4 * 1024 * 1024);
  QCOMPARE(policy.slotBudget(), std::size_t(8));

  for (int source = 0; source < 40; ++source) {
    const auto [idx, pick] = policy.claim(source, false, live.fn());
    QVERIFY(idx != FramePoolPolicy::kInvalidSlot);
    live.pin(idx);
    Q_UNUSED(pick)
    live.releaseAll();
  }

  QCOMPARE(policy.materialised(), std::size_t(8));
  QVERIFY(policy.stats().steal > 0);
}

void FramePoolPolicyTest::ownershipReleaseKeepsMaterialisedCount()
{
  FramePoolPolicy policy(64);
  Liveness live(64);

  const auto first = policy.claim(0, false, live.fn());
  live.pin(first.first);
  const auto second = policy.claim(0, false, live.fn());
  Q_UNUSED(second)
  QCOMPARE(policy.materialised(), std::size_t(2));

  live.releaseAll();
  policy.releaseOwnership();

  const auto after = policy.claim(0, false, live.fn());
  QVERIFY(after.first != FramePoolPolicy::kInvalidSlot);
  QCOMPARE(policy.materialised(), std::size_t(2));
}

static quint64 endpointTokenKey()
{
  auto seed = QSysInfo::machineUniqueId();
  if (seed.isEmpty())
    seed = QSysInfo::machineHostName().toUtf8();

  const auto digest = QCryptographicHash::hash(seed, QCryptographicHash::Sha256);
  SS_ASSERT(digest.size() >= 8, return 0x5361766564546F6BULL);

  quint64 key = 0;
  for (int i = 0; i < 8; ++i)
    key = (key << 8) | static_cast<quint8>(digest.at(i));

  return key;
}

void API::ServerWorker::writeMirrorPayload(QTcpSocket* socket,
                                           const QString& sessionId,
                                           const QByteArray& data)
{
  SS_ASSERT(!data.isEmpty(), return);

  if (socket && m_sockets.value(socket) == sessionId && socket->isWritable()
      && underWriteCap(socket))
    socket->write(data);
}

bool DataModel::DataTableStore::isWritable(const QString& table, const QString& reg) const
{
  SS_ASSERT(m_initialized, return false);
  SS_ASSERT(m_isComputed.size() == m_storage.size(), return false);

  const int idx = indexOf(table, reg);
  if (idx < 0)
    return false;

  return m_isComputed[static_cast<size_t>(idx)];
}

bool DataModel::DataTableStore::isWritableHandle(qint64 handle) const
{
  SS_ASSERT(m_initialized, return false);
  SS_ASSERT(m_isComputed.size() == m_storage.size(), return false);

  if (handle < 0)
    return false;

  const int gen   = static_cast<int>(handle >> kHandleIndexBits);
  const int index = static_cast<int>(handle & kHandleIndexMask);
  if (gen != m_generation || index >= static_cast<int>(m_storage.size()))
    return false;

  return m_isComputed[static_cast<size_t>(index)];
}

bool DataModel::DataTableSnapshot::isWritable(const QString& table, const QString& reg) const
{
  const auto it = index.constFind(qMakePair(table, reg));
  if (it == index.constEnd())
    return false;

  const auto slot = static_cast<size_t>(it.value());
  return slot < computed.size() && computed[slot];
}

bool DataModel::DataTableSnapshot::isWritableHandle(qint64 handle) const
{
  if (handle < 0)
    return false;

  if (static_cast<int>(handle >> kHandleIndexBits) != generation)
    return false;

  const auto slot = static_cast<size_t>(handle & kHandleIndexMask);
  return slot < computed.size() && computed[slot];
}

void IO::ConnectionManager::connectDevice(HAL_Driver* driver)
{
  if (!driver)
    return;

  for (const auto& [id, dm] : m_devices) {
    if (dm && dm->driver() == driver) {
      connectDevice(id);
      return;
    }
  }
}

static void teardownHeadlessSession()
{
  Misc::ModuleManager::teardownHeadlessSessionModules();
  Misc::ModuleManager::stopFrameConsumerWorkers();
  SessionContext::current().shutdown();
}

[[nodiscard]] static bool containedInPackage(const QString& directory, const QString& relative)
{
  const auto base = QFileInfo(directory).absoluteFilePath() + QStringLiteral("/");
  const auto path = QFileInfo(directory + QStringLiteral("/") + relative).absoluteFilePath();

  return !relative.isEmpty() && !relative.startsWith(QStringLiteral("/"))
      && !relative.contains(QStringLiteral("..")) && path.startsWith(base);
}

QString API::EnumLabels::layoutPatternLabel(int value)
{
  switch (static_cast<UI::Layouts::Pattern>(value)) {
    case UI::Layouts::Pattern::MasterStack:
      return QStringLiteral("Master + Stack");
    case UI::Layouts::Pattern::MasterGrid:
      return QStringLiteral("Master + Grid");
    case UI::Layouts::Pattern::Row:
      return QStringLiteral("Row");
    case UI::Layouts::Pattern::Column:
      return QStringLiteral("Column");
    case UI::Layouts::Pattern::Spiral:
      return QStringLiteral("Spiral");
    case UI::Layouts::Pattern::Grid:
      return QStringLiteral("Grid");
  }
  return QStringLiteral("Grid");
}

API::CommandResponse API::Handlers::WindowHandler::setLayoutPattern(const QString& id,
                                                                    const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("pattern")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: pattern"));

  static auto& sessionRegistry = UI::UISessionRegistry::instance();
  auto* wm                     = sessionRegistry.primaryWindowManager();
  if (!wm)
    return noSession(id);

  const auto pattern = params.value(QStringLiteral("pattern")).toString();
  const int ratio    = params.value(QStringLiteral("ratio")).toInt(wm->layoutRatio());
  wm->selectLayoutPattern(pattern, ratio);

  QJsonObject result;
  result[QStringLiteral("pattern")] = wm->layoutPattern();
  result[QStringLiteral("ratio")]   = wm->layoutRatio();

void DataModel::FrameBuilder::clearLatestFrames()
{
  m_latestFrames.clear();
  m_latestFrameSourceId = -1;
  ++m_latestFrameSeq;
  clearLatestFrames();
    clearLatestFrames();
  clearLatestFrames();

QJsonObject DataModel::ProjectModel::layoutChoice(const QString& scope, int groupId) const
{
  const auto entry = m_widgetSettings.value(Keys::layoutKey(scope, groupId)).toObject();

  QJsonObject out;
  out.insert(QStringLiteral("pattern"), entry.value(QStringLiteral("pattern")).toString());
  out.insert(QStringLiteral("ratio"), entry.value(QStringLiteral("ratio")).toInt(8));
  return out;
}

void DataModel::ProjectModel::setLayoutChoice(const QString& scope,
                                              int groupId,
                                              const QString& pattern,
                                              int ratio)
{
  const auto key = Keys::layoutKey(scope, groupId);
  saveWidgetSetting(key, QStringLiteral("pattern"), pattern.trimmed().toLower());
  saveWidgetSetting(key, QStringLiteral("ratio"), qBound(1, ratio, 15));
}

[[nodiscard]] static qsizetype skipSpaces(const QString& s, qsizetype i)
{
  qsizetype j = i;
  while (j < s.size() && s[j].isSpace())
    ++j;

  return j;
}

[[nodiscard]] static LongBracket readLongBracket(const QString& s, qsizetype i)
{
  const qsizetype n = s.size();
  if (i >= n || s[i] != QLatin1Char('['))
    return {false, false, i};

  qsizetype level = 0;
  qsizetype j     = i + 1;
  while (j < n && s[j] == QLatin1Char('=')) {
    ++level;
    ++j;
  }

  if (j >= n || s[j] != QLatin1Char('['))
    return {false, false, i};

  const QString close =
    QStringLiteral("]") + QString(level, QLatin1Char('=')) + QStringLiteral("]");
  const qsizetype end = s.indexOf(close, j + 1);
  if (end < 0)
    return {true, false, n};

  return {true, true, end + close.size()};
}

[[nodiscard]] static qsizetype readComment(const QString& s, qsizetype i)
{
  const LongBracket bracket = readLongBracket(s, i + 2);
  if (bracket.present)
    return bracket.terminated ? bracket.end : -1;

  const qsizetype end = s.indexOf(QLatin1Char('\n'), i + 2);
  return end < 0 ? s.size() : end;
}

[[nodiscard]] static qsizetype readShortString(const QString& s, qsizetype i)
{
  const QChar quote = s[i];
  const qsizetype n = s.size();
  for (qsizetype j = i + 1; j < n; ++j) {
    if (s[j] == QLatin1Char('\\')) {
      ++j;
      continue;
    }

    if (s[j] == quote)
      return j + 1;

    if (s[j] == QLatin1Char('\n'))
      return -1;
  }

  return -1;
}

[[nodiscard]] static qsizetype readNumber(const QString& s, qsizetype i)
{
  const qsizetype n = s.size();
  const bool hex    = (i + 1 < n) && s[i] == QLatin1Char('0')
                && (s[i + 1] == QLatin1Char('x') || s[i + 1] == QLatin1Char('X'));

  qsizetype j = i;
  while (j < n && (s[j].isLetterOrNumber() || s[j] == QLatin1Char('.'))) {
    const bool marker = hex ? (s[j] == QLatin1Char('p') || s[j] == QLatin1Char('P'))
                            : (s[j] == QLatin1Char('e') || s[j] == QLatin1Char('E'));
    const bool signed_exponent =
      marker && j + 1 < n && (s[j + 1] == QLatin1Char('+') || s[j + 1] == QLatin1Char('-'));
    j += signed_exponent ? 2 : 1;
  }

  return j;
}

[[nodiscard]] static qsizetype readName(const QString& s, qsizetype i)
{
  qsizetype j = i;
  while (j < s.size() && (s[j].isLetterOrNumber() || s[j] == QLatin1Char('_')))
    ++j;

  return j;
}

[[nodiscard]] static qsizetype readOperator(const QString& s, qsizetype i)
{
  static const QString kThreeChar[] = {QStringLiteral("...")};
  static const QString kTwoChar[]   = {QStringLiteral(".."),
                                       QStringLiteral("=="),
                                       QStringLiteral("~="),
                                       QStringLiteral("<="),
                                       QStringLiteral(">="),
                                       QStringLiteral("<<"),
                                       QStringLiteral(">>"),
                                       QStringLiteral("//"),
                                       QStringLiteral("::")};

  for (const auto& candidate : kThreeChar)
    if (QStringView(s).sliced(i).startsWith(candidate))
      return i + candidate.size();

  for (const auto& candidate : kTwoChar)
    if (QStringView(s).sliced(i).startsWith(candidate))
      return i + candidate.size();

  return i + 1;
}

[[nodiscard]] static bool appendToken(
  const QString& s, qsizetype& i, qsizetype end, TokenKind kind, std::vector<Token>& out)
{
  if (end <= i)
    return false;

  out.push_back({kind, s.mid(i, end - i)});
  i = end;
  return true;
}

[[nodiscard]] static bool readOneToken(const QString& s, qsizetype& i, std::vector<Token>& out)
{
  const qsizetype n = s.size();
  const QChar c     = s[i];
  if (c.isSpace())
    return appendToken(s, i, skipSpaces(s, i), TokenKind::Trivia, out);

  if (c == QLatin1Char('-') && i + 1 < n && s[i + 1] == QLatin1Char('-'))
    return appendToken(s, i, readComment(s, i), TokenKind::Trivia, out);

  if (c == QLatin1Char('"') || c == QLatin1Char('\''))
    return appendToken(s, i, readShortString(s, i), TokenKind::String, out);

  if (c == QLatin1Char('[')) {
    const LongBracket bracket = readLongBracket(s, i);
    if (bracket.present)
      return bracket.terminated && appendToken(s, i, bracket.end, TokenKind::String, out);
  }

  if (c.isDigit() || (c == QLatin1Char('.') && i + 1 < n && s[i + 1].isDigit()))
    return appendToken(s, i, readNumber(s, i), TokenKind::Number, out);

  if (c.isLetter() || c == QLatin1Char('_'))
    return appendToken(s, i, readName(s, i), TokenKind::Name, out);

  return appendToken(s, i, readOperator(s, i), TokenKind::Operator, out);
}

[[nodiscard]] static bool tokenize(const QString& source, std::vector<Token>& out)
{
  out.clear();
  const qsizetype n = source.size();

  qsizetype i = 0;
  while (i < n) {
    const qsizetype start = i;
    if (!readOneToken(source, i, out))
      return false;

    SS_ASSERT(i > start, return false);
  }

  return true;
}

[[nodiscard]] static bool isKeyword(const QString& text)
{
  static const QStringList kKeywords = {
    QStringLiteral("and"),   QStringLiteral("break"),  QStringLiteral("do"),
    QStringLiteral("else"),  QStringLiteral("elseif"), QStringLiteral("end"),
    QStringLiteral("false"), QStringLiteral("for"),    QStringLiteral("function"),
    QStringLiteral("goto"),  QStringLiteral("if"),     QStringLiteral("in"),
    QStringLiteral("local"), QStringLiteral("nil"),    QStringLiteral("not"),
    QStringLiteral("or"),    QStringLiteral("repeat"), QStringLiteral("return"),
    QStringLiteral("then"),  QStringLiteral("true"),   QStringLiteral("until"),
    QStringLiteral("while")};

  return kKeywords.contains(text);
}

[[nodiscard]] static bool isValueKeyword(const QString& text)
{
  return text == QLatin1String("nil") || text == QLatin1String("true")
      || text == QLatin1String("false");
}

[[nodiscard]] static bool endsValue(const Token& token)
{
  if (token.kind == TokenKind::Number || token.kind == TokenKind::String)
    return true;

  if (token.kind == TokenKind::Name)
    return !isKeyword(token.text) || isValueKeyword(token.text);

  return token.text == QLatin1String(")") || token.text == QLatin1String("]")
      || token.text == QLatin1String("}") || token.text == QLatin1String("...");
}

[[nodiscard]] static int binaryPrecedence(const Token& token)
{
  const QString& t = token.text;
  if (token.kind == TokenKind::Name)
    return t == QLatin1String("or") ? 1 : (t == QLatin1String("and") ? 2 : 0);

  if (token.kind != TokenKind::Operator)
    return 0;

  if (t == QLatin1String("<") || t == QLatin1String(">") || t == QLatin1String("<=")
      || t == QLatin1String(">=") || t == QLatin1String("~=") || t == QLatin1String("=="))
    return 3;

  if (t == QLatin1String("|"))
    return 4;

  if (t == QLatin1String("~"))
    return 5;

  if (t == QLatin1String("&"))
    return 6;

  if (t == QLatin1String("<<") || t == QLatin1String(">>"))
    return 7;

  if (t == QLatin1String(".."))
    return 8;

  if (t == QLatin1String("+") || t == QLatin1String("-"))
    return 9;

  if (t == QLatin1String("*") || t == QLatin1String("/") || t == QLatin1String("//")
      || t == QLatin1String("%"))
    return 10;

  return t == QLatin1String("^") ? 12 : 0;
}

[[nodiscard]] static bool isUnaryPrefix(const Token& token)
{
  if (token.kind == TokenKind::Name)
    return token.text == QLatin1String("not");

  return token.text == QLatin1String("-") || token.text == QLatin1String("#")
      || token.text == QLatin1String("~");
}

[[nodiscard]] static qsizetype nextCode(const std::vector<Token>& v, qsizetype i)
{
  const auto n = static_cast<qsizetype>(v.size());
  qsizetype j  = i < 0 ? 0 : i;
  while (j < n && v[j].kind == TokenKind::Trivia)
    ++j;

  return j < n ? j : -1;
}

[[nodiscard]] static qsizetype prevCode(const std::vector<Token>& v, qsizetype i)
{
  const auto n = static_cast<qsizetype>(v.size());
  qsizetype j  = i >= n ? n - 1 : i;
  while (j >= 0 && v[j].kind == TokenKind::Trivia)
    --j;

  return j;
}

[[nodiscard]] static bool inPrefixPosition(const std::vector<Token>& v, qsizetype i)
{
  const qsizetype p = prevCode(v, i - 1);
  return p < 0 || !endsValue(v[p]);
}

[[nodiscard]] static bool isOpenBracket(const Token& token)
{
  return token.text == QLatin1String("(") || token.text == QLatin1String("[")
      || token.text == QLatin1String("{");
}

[[nodiscard]] static bool isCloseBracket(const Token& token)
{
  return token.text == QLatin1String(")") || token.text == QLatin1String("]")
      || token.text == QLatin1String("}");
}

[[nodiscard]] static qsizetype matchForward(const std::vector<Token>& v, qsizetype open)
{
  const auto n = static_cast<qsizetype>(v.size());
  int depth    = 0;
  for (qsizetype i = open; i < n; ++i) {
    if (isOpenBracket(v[i]))
      ++depth;
    else if (isCloseBracket(v[i]))
      --depth;
    else
      continue;

    if (depth == 0)
      return i;

    if (depth < 0)
      return -1;
  }

  return -1;
}

[[nodiscard]] static qsizetype matchBackward(const std::vector<Token>& v, qsizetype close)
{
  int depth = 0;
  for (qsizetype i = close; i >= 0; --i) {
    if (isCloseBracket(v[i]))
      ++depth;
    else if (isOpenBracket(v[i]))
      --depth;
    else
      continue;

    if (depth == 0)
      return i;

    if (depth < 0)
      return -1;
  }

  return -1;
}

[[nodiscard]] static qsizetype growSuffix(const std::vector<Token>& v, qsizetype j)
{
  const Token& token = v[j];
  if (token.text == QLatin1String(".") || token.text == QLatin1String(":")) {
    const qsizetype k = nextCode(v, j + 1);
    return (k >= 0 && v[k].kind == TokenKind::Name) ? k : -1;
  }

  if (isOpenBracket(token))
    return matchForward(v, j);

  return token.kind == TokenKind::String ? j : -1;
}

[[nodiscard]] static bool scanPrimaryForward(const std::vector<Token>& v,
                                             qsizetype i,
                                             qsizetype& last)
{
  const auto n = static_cast<qsizetype>(v.size());
  if (i < 0 || i >= n)
    return false;

  const Token& token = v[i];
  if (token.kind == TokenKind::Name && isKeyword(token.text) && !isValueKeyword(token.text))
    return false;

  qsizetype base = -1;
  if (token.kind == TokenKind::Name || token.kind == TokenKind::Number
      || token.kind == TokenKind::String || token.text == QLatin1String("..."))
    base = i;
  else if (token.text == QLatin1String("(") || token.text == QLatin1String("{"))
    base = matchForward(v, i);

  if (base < 0)
    return false;

  for (int step = 0; step < kMaxScanSteps; ++step) {
    const qsizetype j = nextCode(v, base + 1);
    if (j < 0)
      break;

    const qsizetype grown = growSuffix(v, j);
    if (grown < 0)
      break;

    base = grown;
  }

  last = base;
  return true;
}

[[nodiscard]] static qsizetype skipUnaryPrefixes(const std::vector<Token>& v, qsizetype i)
{
  qsizetype k = i;
  for (int step = 0; step < kMaxScanSteps; ++step) {
    if (k < 0 || !isUnaryPrefix(v[k]))
      return k;

    k = nextCode(v, k + 1);
  }

  return -1;
}

[[nodiscard]] static bool scanOperandForward(const std::vector<Token>& v,
                                             qsizetype start,
                                             int precedence,
                                             qsizetype& end)
{
  qsizetype i = nextCode(v, start);
  for (int step = 0; step < kMaxScanSteps; ++step) {
    i = skipUnaryPrefixes(v, i);
    if (i < 0)
      return false;

    qsizetype last = -1;
    if (!scanPrimaryForward(v, i, last))
      return false;

    end               = last;
    const qsizetype j = nextCode(v, last + 1);
    if (j < 0 || binaryPrecedence(v[j]) <= precedence)
      return true;

    i = nextCode(v, j + 1);
  }

  return false;
}

[[nodiscard]] static bool scanPrimaryBackward(const std::vector<Token>& v,
                                              qsizetype i,
                                              int depth,
                                              qsizetype& first)
{
  if (i < 0 || depth > kMaxDepth)
    return false;

  const Token& token = v[i];
  if (isCloseBracket(token)) {
    const qsizetype open = matchBackward(v, i);
    if (open < 0)
      return false;

    const qsizetype q = prevCode(v, open - 1);
    if (q >= 0 && endsValue(v[q]))
      return scanPrimaryBackward(v, q, depth + 1, first);

    first = open;
    return true;
  }

  if (!endsValue(token))
    return false;

  const qsizetype p = prevCode(v, i - 1);
  if (p >= 0 && (v[p].text == QLatin1String(".") || v[p].text == QLatin1String(":")))
    return scanPrimaryBackward(v, prevCode(v, p - 1), depth + 1, first);

  if (p >= 0 && token.kind == TokenKind::String && endsValue(v[p]))
    return scanPrimaryBackward(v, p, depth + 1, first);

  first = i;
  return true;
}

[[nodiscard]] static qsizetype absorbPrefixesBackward(const std::vector<Token>& v, qsizetype begin)
{
  qsizetype k = begin;
  for (int step = 0; step < kMaxScanSteps; ++step) {
    const qsizetype p = prevCode(v, k - 1);
    if (p < 0 || !isUnaryPrefix(v[p]) || !inPrefixPosition(v, p))
      return k;

    k = p;
  }

  return begin;
}

[[nodiscard]] static bool scanOperandBackward(const std::vector<Token>& v,
                                              qsizetype start,
                                              int precedence,
                                              qsizetype& first)
{
  qsizetype i = prevCode(v, start);
  for (int step = 0; step < kMaxScanSteps; ++step) {
    qsizetype begin = -1;
    if (!scanPrimaryBackward(v, i, 0, begin))
      return false;

    first             = absorbPrefixesBackward(v, begin);
    const qsizetype p = prevCode(v, first - 1);
    if (p < 0 || inPrefixPosition(v, p) || binaryPrecedence(v[p]) < precedence)
      return true;

    i = prevCode(v, p - 1);
  }

  return false;
}

[[nodiscard]] static int targetPrecedence(const std::vector<Token>& v, qsizetype i)
{
  const Token& token = v[i];
  if (token.kind != TokenKind::Operator)
    return 0;

  const QString& t = token.text;
  if (t == QLatin1String("~"))
    return inPrefixPosition(v, i) ? 11 : 5;

  if (t == QLatin1String("//"))
    return 10;

  if (t == QLatin1String("<<") || t == QLatin1String(">>"))
    return 7;

  if (t == QLatin1String("&"))
    return 6;

  return t == QLatin1String("|") ? 4 : 0;
}

[[nodiscard]] static bool findTarget(const std::vector<Token>& v, Target& out)
{
  bool found   = false;
  const auto n = static_cast<qsizetype>(v.size());
  for (qsizetype i = 0; i < n; ++i) {
    const int precedence = targetPrecedence(v, i);
    if (precedence <= 0 || (found && precedence <= out.precedence))
      continue;

    out.index      = i;
    out.precedence = precedence;
    out.unary      = v[i].text == QLatin1String("~") && precedence == 11;
    found          = true;
  }

  return found;
}

[[nodiscard]] static QString bitFunctionFor(const QString& op)
{
  if (op == QLatin1String("<<"))
    return QStringLiteral("bit.lshift");

  if (op == QLatin1String(">>"))
    return QStringLiteral("bit.rshift");

  if (op == QLatin1String("&"))
    return QStringLiteral("bit.band");

  if (op == QLatin1String("|"))
    return QStringLiteral("bit.bor");

  return QStringLiteral("bit.bxor");
}

[[nodiscard]] static QString joinRange(const std::vector<Token>& v, qsizetype from, qsizetype to)
{
  QString out;
  const auto n      = static_cast<qsizetype>(v.size());
  const qsizetype a = from < 0 ? 0 : from;
  const qsizetype b = to >= n ? n - 1 : to;
  for (qsizetype i = a; i <= b; ++i)
    out += v[i].text;

  return out;
}

[[nodiscard]] static QString significantGap(const std::vector<Token>& v,
                                            qsizetype from,
                                            qsizetype to)
{
  const QString gap = joinRange(v, from, to);
  return gap.trimmed().isEmpty() ? QString() : gap;
}

[[nodiscard]] static bool rewriteOnce(const QString& source, QString& out, bool& changed)
{
  changed = false;

  std::vector<Token> v;
  if (!tokenize(source, v))
    return false;

  Target target{-1, 0, false};
  if (!findTarget(v, target))
    return true;

  qsizetype rightEnd = -1;
  if (!scanOperandForward(v, target.index + 1, target.precedence, rightEnd))
    return false;

  const qsizetype rightStart = nextCode(v, target.index + 1);
  const QString rightGap     = significantGap(v, target.index + 1, rightStart - 1);
  const QString right        = joinRange(v, rightStart, rightEnd);
  const auto count           = static_cast<qsizetype>(v.size());
  const QString tail         = joinRange(v, rightEnd + 1, count - 1);

  changed = true;
  if (target.unary) {
    out = joinRange(v, 0, target.index - 1) + QStringLiteral("bit.bnot(") + rightGap + right
        + QStringLiteral(")") + tail;
    return true;
  }

  qsizetype leftStart = -1;
  if (!scanOperandBackward(v, target.index - 1, target.precedence, leftStart))
    return false;

  const qsizetype leftEnd = prevCode(v, target.index - 1);
  const QString leftGap   = significantGap(v, leftEnd + 1, target.index - 1);
  const QString left      = joinRange(v, leftStart, leftEnd);
  const QString head      = joinRange(v, 0, leftStart - 1);
  const QString gaps      = leftGap + rightGap;

  if (v[target.index].text == QLatin1String("//"))
    out = head + QStringLiteral("math.floor(") + left + QStringLiteral(" / ") + gaps + right
        + QStringLiteral(")") + tail;
  else
    out = head + bitFunctionFor(v[target.index].text) + QStringLiteral("(") + left
        + QStringLiteral(", ") + gaps + right + QStringLiteral(")") + tail;

  return true;
}

bool DataModel::LuaMigration::usesLua53Operators(const QString& script)
{
  std::vector<Token> v;
  if (!tokenize(script, v))
    return false;

  Target target{-1, 0, false};
  return findTarget(v, target);
}

QString DataModel::LuaMigration::migrateToLuaJit(const QString& script)
{
  if (script.isEmpty())
    return {};

  QString current = script;
  for (int pass = 0; pass < kMaxRewrites; ++pass) {
    QString next;
    bool changed = false;
    if (!rewriteOnce(current, next, changed))
      return {};

    if (!changed)
      return current == script ? QString() : current;

    current = next;
  }

  return {};
}

[[nodiscard]] static QString compilableMigration(lua_State* L, const QString& script)
{
  const QString migrated = DataModel::LuaMigration::migrateToLuaJit(script);
  if (migrated.isEmpty())
    return {};

  const QByteArray utf8 = migrated.toUtf8();
  const int status      = luaL_loadbuffer(L, utf8.constData(), utf8.size(), "migration_probe");
  lua_pop(L, 1);
  return status == LUA_OK ? migrated : QString();
}

[[nodiscard]] static DataModel::ProjectModel& projectModel()
{
  static auto& model = DataModel::ProjectModel::instance();
  return model;
}

static void applyLuaMigration(int sourceId, const QString& fixed)
{
  if (sourceId == 0)
    projectModel().setFrameParserCode(fixed);
  else
    projectModel().updateSourceFrameParser(sourceId, fixed);
}

static void offerLuaMigration(int sourceId,
                              const QString& error,
                              const QString& script,
                              const QString& fixed)
{
  const QString key =
    QStringLiteral("%1:%2").arg(QString::number(sourceId), QString::number(qHash(script)));
  QMetaObject::invokeMethod(
    qApp,
    [sourceId, error, fixed, key] {
      static QSet<QString> offered;
      if (offered.contains(key))
        return;

      if (offered.size() >= kMaxOfferedMigrations)
        offered.clear();

      offered.insert(key);
      const auto answer = Misc::Utilities::showMessageBox(
        QObject::tr("Lua Syntax Error"),
        QObject::tr("The parser code contains an error:\n\n%1\n\n"
                    "Serial Studio can rewrite the unsupported operators as bit.* calls and "
                    "reload the parser. The bit library works on 32-bit integers, so a value "
                    "wider than 32 bits will wrap once rewritten.")
          .arg(error),
        QMessageBox::Critical,
        QString(),
        QMessageBox::Yes | QMessageBox::No,
        QMessageBox::Yes,
        {
          {QMessageBox::Yes, QObject::tr("Fix Automatically")},
          { QMessageBox::No,   QObject::tr("Leave Unchanged")}
      });

      if (answer == QMessageBox::Yes)
        applyLuaMigration(sourceId, fixed);
    },
    Qt::QueuedConnection);
}

static void reportSyntaxError(
  lua_State* L, int sourceId, const QString& script, const QString& errorMsg, bool showMessageBoxes)
{
  if (!showMessageBoxes) {
    qWarning() << "[LuaScriptEngine] Source" << sourceId << "syntax error:" << errorMsg;
    return;
  }

  const QString fixed = compilableMigration(L, script);
  if (!fixed.isEmpty()) {
    offerLuaMigration(sourceId, errorMsg, script, fixed);
    return;
  }

  Misc::Utilities::showMessageBox(
    QObject::tr("Lua Syntax Error"),
    QObject::tr("The parser code contains an error:\n\n%1").arg(errorMsg),
    QMessageBox::Critical);
}

[[nodiscard]] static UI::Layouts::LayoutEnv subEnv(const UI::Layouts::LayoutEnv& env,
                                                   const int w,
                                                   const int h)
{
  UI::Layouts::LayoutEnv sub = env;
  sub.margin                 = 0;
  sub.availW                 = w;
  sub.availH                 = h;
  sub.isLandscape            = w >= h;
  return sub;
}

static void translateAll(QVector<QRect>& rects, const int dx, const int dy)
{
  for (auto& rect : rects)
    rect.translate(dx, dy);
}

[[nodiscard]] static QVector<QRect> tileStrip(const int n,
                                              const UI::Layouts::LayoutEnv& env,
                                              const bool horizontal)
{
  const int spacingForSizing = qMax(env.spacing, 0);
  const int axis             = horizontal ? env.availW : env.availH;
  const int total            = qMax(1, axis - (n - 1) * spacingForSizing);
  const int base             = total / n;
  const int extra            = total % n;

  QVector<QRect> out;
  out.reserve(n);

  int running = env.margin;
  for (int i = 0; i < n; ++i) {
    const int size = base + (i < extra ? 1 : 0);
    out.append(horizontal ? QRect(running, env.margin, size, env.availH)
                          : QRect(env.margin, running, env.availW, size));
    running += size + env.spacing;
  }

  return out;
}

[[nodiscard]] static QVector<QRect> tileMaster(const int n,
                                               const UI::Layouts::LayoutEnv& env,
                                               const bool gridRemainder)
{
  if (n == 1)
    return {wholeCanvas(env)};

  const bool vertical = env.isLandscape;
  const int axis      = vertical ? env.availW : env.availH;
  const int cross     = vertical ? env.availH : env.availW;
  const int primary =
    qBound(1, axis * env.ratio / UI::Layouts::kRatioDenominator, qMax(1, axis - 1));
  const int rest = axis - primary - env.spacing;
  if (rest < 1)
    return {};

  QVector<QRect> out;
  out.reserve(n);
  out.append(vertical ? QRect(env.margin, env.margin, primary, cross)
                      : QRect(env.margin, env.margin, cross, primary));

  const auto region = vertical ? subEnv(env, rest, cross) : subEnv(env, cross, rest);
  auto remainder    = gridRemainder ? tileGrid(n - 1, region) : tileStrip(n - 1, region, !vertical);
  translateAll(remainder,
               vertical ? env.margin + primary + env.spacing : env.margin,
               vertical ? env.margin : env.margin + primary + env.spacing);

  out.append(remainder);
  return out;
}

[[nodiscard]] static QVector<QRect> tileSpiral(const int n, const UI::Layouts::LayoutEnv& env)
{
  QVector<QRect> out;
  out.reserve(n);

  QRect remaining = wholeCanvas(env);
  for (int i = 0; i < n - 1; ++i) {
    const bool vertical = remaining.width() >= remaining.height();
    const int axis      = vertical ? remaining.width() : remaining.height();
    const int take =
      qBound(1, axis * env.ratio / UI::Layouts::kRatioDenominator, qMax(1, axis - 1));
    const int rest = axis - take - env.spacing;
    if (rest < 1)
      return {};

    if (vertical) {
      out.append(QRect(remaining.x(), remaining.y(), take, remaining.height()));
      remaining.setX(remaining.x() + take + env.spacing);
      remaining.setWidth(rest);
    }

    else {
      out.append(QRect(remaining.x(), remaining.y(), remaining.width(), take));
      remaining.setY(remaining.y() + take + env.spacing);
      remaining.setHeight(rest);
    }
  }

  out.append(remaining);
  return out;
}

[[nodiscard]] static bool meetsFloor(const QVector<QRect>& rects, const UI::Layouts::LayoutEnv& env)
{
  for (const auto& rect : rects)
    if (rect.width() < env.minWidth || rect.height() < env.minHeight)
      return false;

  return true;
}

[[nodiscard]] static QVector<QRect> dispatchPattern(const int n,
                                                    const UI::Layouts::Pattern pattern,
                                                    const UI::Layouts::LayoutEnv& env)
{
  switch (pattern) {
    case UI::Layouts::Pattern::MasterStack:
      return tileMaster(n, env, false);
    case UI::Layouts::Pattern::MasterGrid:
      return tileMaster(n, env, true);
    case UI::Layouts::Pattern::Row:
      return tileStrip(n, env, true);
    case UI::Layouts::Pattern::Column:
      return tileStrip(n, env, false);
    case UI::Layouts::Pattern::Spiral:
      return tileSpiral(n, env);
    case UI::Layouts::Pattern::Grid:
      return tileGrid(n, env);
  }

  return tileGrid(n, env);
}

[[nodiscard]] static QHash<int, int> clusterEdges(const QVector<int>& values, const int canvasEnd)
{
  QVector<int> edges = values;
  edges.append(0);
  edges.append(canvasEnd);
  std::sort(edges.begin(), edges.end());
  edges.erase(std::unique(edges.begin(), edges.end()), edges.end());

  QHash<int, int> mapping;
  int index = 0;
  while (index < edges.size()) {
    int last      = index;
    long long sum = edges[index];
    while (last + 1 < edges.size()
           && edges[last + 1] - edges[last] <= UI::Layouts::kSeamTolerance) {
      ++last;
      sum += edges[last];
    }

    const int count    = last - index + 1;
    int representative = static_cast<int>(sum / count);
    if (edges[index] <= 0 && edges[last] >= 0)
      representative = 0;

    else if (edges[index] <= canvasEnd && edges[last] >= canvasEnd)
      representative = canvasEnd;

    for (int k = index; k <= last; ++k)
      mapping.insert(edges[k], representative);

    index = last + 1;
  }

  return mapping;
}

[[nodiscard]] static QSet<int> gapConsumingSeams(const QHash<int, int>& mapping,
                                                 const QVector<int>& leads,
                                                 const QVector<int>& trails,
                                                 const int canvasEnd)
{
  QSet<int> leading;
  QSet<int> trailing;
  for (const int edge : leads)
    leading.insert(mapping.value(edge));

  for (const int edge : trails)
    trailing.insert(mapping.value(edge));

  QSet<int> seams;
  for (const int seam : std::as_const(leading))
    if (seam > 0 && seam < canvasEnd && trailing.contains(seam))
      seams.insert(seam);

  return seams;
}

[[nodiscard]] static int effectiveSpacing(const int spacing, const int seams, const int extent)
{
  if (seams <= 0 || extent - seams * spacing > 0)
    return spacing;

  return qBound(0, (extent - 1) / seams, spacing);
}

[[nodiscard]] static QHash<int, int> seamPositions(const QVector<int>& seams,
                                                   const QSet<int>& gapSeams,
                                                   const int refExtent,
                                                   const int newExtent,
                                                   const int spacing)
{
  const int count    = static_cast<int>(gapSeams.size());
  const int refSpan  = refExtent - count * spacing;
  const int newSpan  = newExtent - count * spacing;
  const bool spanned = refSpan > 0 && newSpan > 0;
  const double scale =
    spanned ? double(newSpan) / double(refSpan) : double(newExtent) / double(refExtent);
  const int gap = spanned ? spacing : 0;

  QHash<int, int> positions;
  int preceding = 0;
  int previous  = std::numeric_limits<int>::min();
  for (const int seam : seams) {
    const int deflated = seam - preceding * gap;
    const int scaled   = seam >= refExtent ? newExtent : qRound(deflated * scale) + preceding * gap;
    const int placed   = qMax(scaled, previous);
    positions.insert(seam, placed);
    previous = placed;
    if (gapSeams.contains(seam))
      ++preceding;
  }

  return positions;
}

[[nodiscard]] static QVector<Span> rescaleAxis(const QVector<Span>& spans,
                                               const int refExtent,
                                               const int newExtent,
                                               const int spacing)
{
  QVector<int> leads;
  QVector<int> trails;
  leads.reserve(spans.size());
  trails.reserve(spans.size());
  for (const auto& span : spans) {
    leads.append(span.lo > 0 ? span.lo - spacing : 0);
    trails.append(span.hi);
  }

  const auto mapping  = clusterEdges(leads + trails, refExtent);
  const auto gapSeams = gapConsumingSeams(mapping, leads, trails, refExtent);
  const int gap       = effectiveSpacing(spacing, static_cast<int>(gapSeams.size()), newExtent);

  QVector<int> seams;
  seams.reserve(mapping.size());
  for (auto it = mapping.cbegin(); it != mapping.cend(); ++it)
    seams.append(it.value());

  std::sort(seams.begin(), seams.end());
  seams.erase(std::unique(seams.begin(), seams.end()), seams.end());
  const auto positions = seamPositions(seams, gapSeams, refExtent, newExtent, gap);

  QVector<Span> out;
  out.reserve(spans.size());
  for (int i = 0; i < spans.size(); ++i) {
    const int seam  = mapping.value(leads[i]);
    const int trail = positions.value(mapping.value(trails[i]));
    const int lo    = positions.value(seam) + (seam > 0 ? gap : 0);
    out.append(Span{lo, qMax(trail, lo + 1)});
  }

  return out;
}

QVector<QRect> UI::Layouts::rescaleManual(const QVector<QRect>& rects,
                                          const QSize& refCanvas,
                                          const QSize& newCanvas,
                                          const int spacing)
{
  const bool sized = refCanvas.width() > 0 && refCanvas.height() > 0 && newCanvas.width() > 0
                  && newCanvas.height() > 0;
  if (rects.isEmpty() || !sized)
    return rects;

  QVector<Span> horizontal;
  QVector<Span> vertical;
  horizontal.reserve(rects.size());
  vertical.reserve(rects.size());
  for (const auto& rect : rects) {
    horizontal.append(Span{rect.x(), rect.x() + rect.width()});
    vertical.append(Span{rect.y(), rect.y() + rect.height()});
  }

  const auto x = rescaleAxis(horizontal, refCanvas.width(), newCanvas.width(), spacing);
  const auto y = rescaleAxis(vertical, refCanvas.height(), newCanvas.height(), spacing);

  QVector<QRect> out;
  out.reserve(rects.size());
  for (int i = 0; i < rects.size(); ++i)
    out.append(QRect(x[i].lo, y[i].lo, x[i].hi - x[i].lo, y[i].hi - y[i].lo));

  return out;
}

void UI::WindowManager::refreshLayoutChoice()
{
  if (!m_taskbar)
    return;

  static auto& project = DataModel::ProjectModel::instance();
  const auto choice    = project.layoutChoice(m_taskbar->layoutScope(), m_taskbar->activeGroupId());

  m_layoutPattern = choice.value(QStringLiteral("pattern")).toString();
  m_layoutRatio   = qBound(1, choice.value(QStringLiteral("ratio")).toInt(), 15);
}

QVariantList UI::WindowManager::patternPreview(
  const int pattern, const int count, const int width, const int height, const int ratio) const
{
  Layouts::LayoutEnv env;
  env.margin      = 0;
  env.spacing     = 1;
  env.availW      = qMax(1, width);
  env.availH      = qMax(1, height);
  env.isLandscape = env.availW >= env.availH;
  env.minWidth    = 1;
  env.minHeight   = 1;
  env.ratio       = qBound(1, ratio, Layouts::kRatioDenominator - 1);

  QVariantList out;
  const auto rects = Layouts::tile(qMax(1, count), static_cast<Layouts::Pattern>(pattern), env);
  for (const auto& rect : rects) {
    QVariantMap entry;
    entry["x"]      = rect.x();
    entry["y"]      = rect.y();
    entry["width"]  = rect.width();
    entry["height"] = rect.height();
    out.append(entry);
  }

  return out;
}

void UI::WindowManager::computeMergedEdges()
{
  QVector<int> ids;
  QVector<QRect> rects;
  for (auto it = m_windows.constBegin(); it != m_windows.constEnd(); ++it) {
    if (!it.value() || it.value()->state() != "normal")
      continue;

    ids.append(it.key());
    rects.append(extractGeometry(it.value()));
  }

  QVariantMap merged;
  for (int i = 0; i < ids.size(); ++i) {
    int mask = 0;
    for (int j = 0; j < ids.size(); ++j) {
      if (i == j)
        continue;

      const QRect a = rects[i];
      const QRect b = rects[j];
      const bool rows =
        qMin(a.y() + a.height(), b.y() + b.height()) - qMax(a.y(), b.y()) > kMergeOverlap;
      const bool cols =
        qMin(a.x() + a.width(), b.x() + b.width()) - qMax(a.x(), b.x()) > kMergeOverlap;

      if (rows && qAbs(a.x() - (b.x() + b.width())) <= kMergeTolerance)
        mask |= 1;

      if (rows && qAbs(b.x() - (a.x() + a.width())) <= kMergeTolerance)
        mask |= 2;

      if (cols && qAbs(a.y() - (b.y() + b.height())) <= kMergeTolerance)
        mask |= 4;

      if (cols && qAbs(b.y() - (a.y() + a.height())) <= kMergeTolerance)
        mask |= 8;
    }

    merged.insert(QString::number(ids[i]), mask);
  }

  if (m_mergedEdges == merged)
    return;

  m_mergedEdges = merged;
  Q_EMIT mergedEdgesChanged();
}

QVariantList UI::WindowManager::layoutRatioStops() const
{
  QVariantList out;
  for (const int stop : Layouts::ratioStops())
    out.append(stop);

  return out;
}

void UI::WindowManager::selectLayoutPattern(const QString& pattern, const int ratio)
{
  m_layoutPattern = pattern.trimmed().toLower();
  m_layoutRatio   = qBound(1, ratio, Layouts::kRatioDenominator - 1);

  if (m_taskbar) {
    static auto& project = DataModel::ProjectModel::instance();
    project.setLayoutChoice(
      m_taskbar->layoutScope(), m_taskbar->activeGroupId(), m_layoutPattern, m_layoutRatio);
  }

  Q_EMIT layoutChoiceChanged();

  if (!m_autoLayoutEnabled)
    setAutoLayoutEnabled(true);

  else
    autoLayout();
}

[[nodiscard]] static QVector<QRect> grid2x2(const QSize& canvas, const int spacing)
{
  const int cw = (canvas.width() - spacing) / 2;
  const int ch = (canvas.height() - spacing) / 2;
  const int rw = canvas.width() - cw - spacing;
  const int rh = canvas.height() - ch - spacing;

  return {QRect(0, 0, cw, ch),
          QRect(cw + spacing, 0, rw, ch),
          QRect(0, ch + spacing, cw, rh),
          QRect(cw + spacing, ch + spacing, rw, rh)};
}

[[nodiscard]] static QVector<QRect> masterStack(const QSize& canvas, const int spacing)
{
  const int mw = (canvas.width() - spacing) / 2;
  const int sw = canvas.width() - mw - spacing;
  const int sh = (canvas.height() - 2 * spacing) / 3;

  return {QRect(0, 0, mw, canvas.height()),
          QRect(mw + spacing, 0, sw, sh),
          QRect(mw + spacing, sh + spacing, sw, sh),
          QRect(mw + spacing, 2 * (sh + spacing), sw, canvas.height() - 2 * (sh + spacing))};
}

[[nodiscard]] static QVector<QRect> joinedWithFloater(const QSize& canvas, const int spacing)
{
  const int lw = (canvas.width() - spacing) / 2;

  return {QRect(0, 0, lw, canvas.height()),
          QRect(lw + spacing, 0, canvas.width() - lw - spacing, canvas.height()),
          QRect(200, 150, 260, 180)};
}

[[nodiscard]] static QVector<QRect> overlappingPair(const QSize& canvas, const int spacing)
{
  Q_UNUSED(canvas)
  Q_UNUSED(spacing)

  return {QRect(120, 90, 400, 300), QRect(300, 200, 400, 300)};
}

[[nodiscard]] static QVector<QRect> build(const int layout, const QSize& canvas, const int spacing)
{
  switch (layout) {
    case 1:
      return masterStack(canvas, spacing);
    case 2:
      return joinedWithFloater(canvas, spacing);
    case 3:
      return overlappingPair(canvas, spacing);
    default:
      return grid2x2(canvas, spacing);
  }
}

[[nodiscard]] static QHash<int, int> joins(const QVector<QRect>& rects, const bool horizontal)
{
  QHash<int, int> out;
  for (int i = 0; i < rects.size(); ++i) {
    for (int j = 0; j < rects.size(); ++j) {
      if (i == j)
        continue;

      const QRect a     = rects[i];
      const QRect b     = rects[j];
      const int overlap = horizontal
                          ? qMin(a.y() + a.height(), b.y() + b.height()) - qMax(a.y(), b.y())
                          : qMin(a.x() + a.width(), b.x() + b.width()) - qMax(a.x(), b.x());
      if (overlap <= 0)
        continue;

      const int distance = horizontal ? b.x() - (a.x() + a.width()) : b.y() - (a.y() + a.height());
      out.insert(static_cast<int>(i * rects.size() + j), distance);
    }
  }

  return out;
}

[[nodiscard]] static bool joinsHold(const QVector<QRect>& before,
                                    const QVector<QRect>& after,
                                    const int spacing)
{
  for (const bool horizontal : {true, false}) {
    const auto was = joins(before, horizontal);
    const auto now = joins(after, horizontal);
    for (auto it = was.cbegin(); it != was.cend(); ++it)
      if (it.value() == spacing && now.value(it.key(), spacing + 1) != spacing)
        return false;
  }

  return true;
}

[[nodiscard]] static bool edgesAreFlush(const QVector<QRect>& rects, const QSize& canvas)
{
  int left   = rects.first().x();
  int top    = rects.first().y();
  int right  = 0;
  int bottom = 0;
  for (const auto& rect : rects) {
    left   = qMin(left, rect.x());
    top    = qMin(top, rect.y());
    right  = qMax(right, rect.x() + rect.width());
    bottom = qMax(bottom, rect.y() + rect.height());
  }

  return left == 0 && top == 0 && right == canvas.width() && bottom == canvas.height();
}

[[nodiscard]] static int worstEdgeShift(const QVector<QRect>& a, const QVector<QRect>& b)
{
  int worst = 0;
  for (int i = 0; i < qMin(a.size(), b.size()); ++i) {
    worst = qMax(worst, qAbs(a[i].x() - b[i].x()));
    worst = qMax(worst, qAbs(a[i].y() - b[i].y()));
    worst = qMax(worst, qAbs(a[i].width() - b[i].width()));
    worst = qMax(worst, qAbs(a[i].height() - b[i].height()));
  }

  return worst;
}

void TstLayoutPatterns::rescaleHoldsJoinsAndOuterEdges_data()
{
  QTest::addColumn<int>("layout");
  QTest::addColumn<int>("spacing");
  QTest::addColumn<QSize>("target");

  const QVector<QSize> targets = {
    QSize(2000, 1400), QSize(500, 350), kSquashed, QSize(317, 911), kReference};

  for (int layout = 0; layout < 4; ++layout)
    for (const int spacing : spacings())
      for (const auto& target : targets)
        QTest::newRow(qPrintable(QStringLiteral("layout=%1 spacing=%2 %3x%4")
                                   .arg(layout)
                                   .arg(spacing)
                                   .arg(target.width())
                                   .arg(target.height())))
          << layout << spacing << target;
}

void TstLayoutPatterns::rescaleHoldsJoinsAndOuterEdges()
{
  QFETCH(int, layout);
  QFETCH(int, spacing);
  QFETCH(QSize, target);

  const auto base = fixtures::build(layout, kReference, spacing);
  const auto out  = UI::Layouts::rescaleManual(base, kReference, target, spacing);

  QCOMPARE(out.size(), base.size());
  QVERIFY2(fixtures::joinsHold(base, out, spacing), "a join stopped measuring the spacing");

  if (fixtures::spansTheCanvas(layout))
    QVERIFY2(fixtures::edgesAreFlush(out, target), "an outer edge left the canvas bound");

  for (const auto& rect : out)
    QVERIFY2(rect.width() >= 1 && rect.height() >= 1, "rescale emitted an empty rect");
}

void TstLayoutPatterns::rescaleFromTheReferenceIsLossless()
{
  for (int layout = 0; layout < 4; ++layout) {
    for (const int spacing : spacings()) {
      const auto base = fixtures::build(layout, kReference, spacing);
      for (int i = 0; i < 10; ++i) {
        const auto away = UI::Layouts::rescaleManual(base, kReference, kSquashed, spacing);
        QCOMPARE(away.size(), base.size());
        QCOMPARE(UI::Layouts::rescaleManual(base, kReference, kReference, spacing), base);
      }
    }
  }
}

void TstLayoutPatterns::rescaleSettlesWhenReDerived()
{
  for (int layout = 0; layout < 4; ++layout) {
    for (const int spacing : spacings()) {
      const auto base = fixtures::build(layout, kReference, spacing);
      auto current    = base;
      for (int i = 0; i < 50; ++i) {
        const auto away = UI::Layouts::rescaleManual(current, kReference, kSquashed, spacing);
        current         = UI::Layouts::rescaleManual(away, kSquashed, kReference, spacing);

        QVERIFY2(fixtures::joinsHold(base, current, spacing), "a join drifted while cycling");
        QVERIFY2(fixtures::worstEdgeShift(current, base) <= kSettleTolerance,
                 "geometry kept drifting instead of settling");
      }
    }
  }
}

void TstLayoutPatterns::rescaleLeavesUntouchedWidgetsAlone()
{
  for (int layout = 0; layout < 4; ++layout) {
    for (const int spacing : spacings()) {
      const auto base = fixtures::build(layout, kReference, spacing);
      auto edited     = UI::Layouts::rescaleManual(base, kReference, kSquashed, spacing);
      edited[0].setWidth(qMax(20, edited[0].width() - 30));

      const auto back = UI::Layouts::rescaleManual(edited, kSquashed, kReference, spacing);
      QCOMPARE(back.size(), base.size());

      for (int i = 1; i < back.size(); ++i)
        QVERIFY2(fixtures::worstEdgeShift({back[i]}, {base[i]}) <= kSettleTolerance,
                 "an untouched widget moved when a neighbour was edited");
    }
  }
}

void TstLayoutPatterns::rescaleDegradesOnACrampedCanvas()
{
  for (const int spacing : spacings()) {
    const auto base = fixtures::grid2x2(kReference, spacing);
    const auto out  = UI::Layouts::rescaleManual(base, kReference, QSize(12, 10), spacing);

    QCOMPARE(out.size(), base.size());
    for (const auto& rect : out)
      QVERIFY2(rect.width() >= 1 && rect.height() >= 1, "degrade emitted an empty rect");

    const int slack = qMax(0, -spacing);
    for (int i = 0; i < out.size(); ++i)
      for (int j = i + 1; j < out.size(); ++j)
        QVERIFY2(!out[i].adjusted(slack, slack, -slack, -slack).intersects(out[j]),
                 "degrade overlapped two widgets");
  }
}

void TstLuaMigration::detectsOperatorsInCodePosition_data()
{
  QTest::addColumn<QString>("script");
  QTest::addColumn<bool>("detected");

  QTest::newRow("band") << QStringLiteral("local v = a & b") << true;
  QTest::newRow("bor") << QStringLiteral("local v = a | b") << true;
  QTest::newRow("bxor") << QStringLiteral("local v = a ~ b") << true;
  QTest::newRow("bnot") << QStringLiteral("local v = ~a") << true;
  QTest::newRow("lshift") << QStringLiteral("local v = a << 1") << true;
  QTest::newRow("rshift") << QStringLiteral("local v = a >> 1") << true;
  QTest::newRow("idiv") << QStringLiteral("local v = a // 8") << true;

  QTest::newRow("not-equal") << QStringLiteral("if a ~= b then end") << false;
  QTest::newRow("compare") << QStringLiteral("if a <= b and c >= d then end") << false;
  QTest::newRow("short string") << QStringLiteral("local s = \"a << b & c // d\"") << false;
  QTest::newRow("line comment") << QStringLiteral("-- a << b & c\nlocal v = 1") << false;
  QTest::newRow("long comment") << QStringLiteral("--[[ a & b\n c << d ]]\nlocal v = 1") << false;
  QTest::newRow("long string") << QStringLiteral("local s = [==[ x | y ]==]") << false;
  QTest::newRow("already migrated") << QStringLiteral("local v = bit.band(a, b)") << false;
}

