bool API::ServerWorker::underWriteCap(QTcpSocket* socket)
{
  SS_ASSERT(socket != nullptr, return false);

  if (socket->bytesToWrite() <= kMaxApiPendingWriteBytes) [[likely]]
    return true;

  ++m_droppedBroadcasts;
  if (!m_warnedBackpressure) {
    m_warnedBackpressure = true;
    qWarning() << "[API] Client" << socket->peerAddress().toString() << ":" << socket->peerPort()
               << "is not reading the broadcast stream; dropping its broadcasts while the socket"
               << "backlog exceeds" << kMaxApiPendingWriteBytes << "bytes";
  }

  return false;
}

void Widgets::AudioExport::ingestStreamBlock(const IO::StreamBlockItemPtr& block)
{
  SS_ASSERT(block != nullptr, return);
  SS_ASSERT_LOG(block->uniqueIds.size() == block->channels.size());

  if (m_sessionDatasets.isEmpty())
    return;

  const std::size_t count = std::min(block->uniqueIds.size(), block->channels.size());
  for (std::size_t c = 0; c < count; ++c) {
    const int uid = block->uniqueIds[c];
    for (auto it = m_sessionDatasets.cbegin(); it != m_sessionDatasets.cend(); ++it) {
      if (it.value() != uid || uid < 0)
        continue;

      for (const double sample : block->channels[c])
        enqueueSample(it.key(), sample);
    }
  }
}

static QString applyDatasetFlagFields3(DataModel::Dataset& d,
                                       const QJsonObject& params,
                                       bool& rebuildTree,
                                       QSet<QString>& consumed)
{
  if (auto err = applyDatasetFlagFields3(d, params, rebuildTree, consumed); !err.isEmpty())
    return err;

  props.insert(Keys::ExtremeHold,
               datasetSchemaProperty("boolean",
                                     "Show hold markers at the lowest and highest values observed "
                                     "since the last data reset",
                                     QJsonArray()));
  props.insert(Keys::TransformLanguage,
               datasetSchemaProperty("integer",
                                     "Transform script language: -1 inherit, 0 JavaScript, 1 Lua",
                                     QJsonArray()));

void API::Handlers::StreamHandler::registerCommands()
{
  static auto& registry = CommandRegistry::instance();

  const auto empty = emptySchema();
  registry.registerCommand(
    QStringLiteral("stream.getInfo"),
    QStringLiteral(
      "Report the typed sample-stream surface: how many stream sources are live, the wire "
      "encoding of a streamBlock line (base64 float32le), the per-subscriber queue depth "
      "before the oldest block is dropped and counted, and the names of the connection-scoped "
      "commands (stream.subscribe / stream.unsubscribe) a subscriber sends on its own socket."),
    empty,
    &getInfo);

  registry.registerCommand(
    QStringLiteral("stream.getSources"),
    QStringLiteral("List every live stream source: sourceId, channel count, sample rate, and "
                   "the dataset uniqueIds its blocks carry."),
    empty,
    &getSources);
}

API::CommandResponse API::Handlers::StreamHandler::getInfo(const QString& id,
                                                           const QJsonObject& params)
{
  Q_UNUSED(params)

  static auto& manager = IO::ConnectionManager::instance();

  QJsonObject result;
  result.insert(QStringLiteral("sourceCount"), static_cast<int>(manager.streamWorkers().size()));
  result.insert(QStringLiteral("encoding"), QStringLiteral("base64:float32le"));
  result.insert(QStringLiteral("queueDepth"), 8);
  result.insert(QStringLiteral("subscribeCommand"), QStringLiteral("stream.subscribe"));
  result.insert(QStringLiteral("unsubscribeCommand"), QStringLiteral("stream.unsubscribe"));
  result.insert(QStringLiteral("pushLine"), QStringLiteral("streamBlock"));
  result.insert(
    QStringLiteral("_summary"),
    QStringLiteral("Send {\"type\":\"command\",\"command\":\"stream.subscribe\"} on this socket "
                   "(optionally with params.sources = [sourceId,...]) to receive streamBlock "
                   "NDJSON lines; each line carries missed, the blocks dropped since the last "
                   "delivery."));
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::StreamHandler::getSources(const QString& id,
                                                              const QJsonObject& params)
{
  Q_UNUSED(params)

  static auto& manager = IO::ConnectionManager::instance();

  QJsonArray sources;
  for (const auto& worker : manager.streamWorkers()) {
    if (!worker)
      continue;

    const auto& config = worker->config();

    QJsonArray datasets;
    for (const auto& dataset : config.datasets) {
      QJsonObject entry;
      entry.insert(Keys::UniqueId, dataset.uniqueId);
      entry.insert(QStringLiteral("channel"), dataset.channel);
      entry.insert(QStringLiteral("fft"), dataset.fft);
      entry.insert(QStringLiteral("plot"), dataset.plot);
      datasets.append(entry);
    }

    QJsonObject source;
    source.insert(Keys::SourceId, config.sourceId);
    source.insert(QStringLiteral("channels"), config.channels);
    source.insert(QStringLiteral("sampleRate"), config.sampleRate);
    source.insert(QStringLiteral("datasets"), datasets);

    if (auto* processor = worker->processor()) {
      source.insert(QStringLiteral("samplesProcessed"),
                    static_cast<double>(processor->samplesProcessed()));
      source.insert(QStringLiteral("blocksProcessed"),
                    static_cast<double>(processor->blocksProcessed()));
      source.insert(QStringLiteral("transformErrors"),
                    static_cast<double>(processor->transformErrorCount()));
      source.insert(QStringLiteral("displayDrops"),
                    static_cast<double>(processor->displayDropCount()));
    }

    sources.append(source);
  }

  QJsonObject result;
  result.insert(QStringLiteral("count"), sources.size());
  result.insert(QStringLiteral("sources"), sources);
  return CommandResponse::makeSuccess(id, result);
}

void API::ServerWorker::writeStreamBlock(QTcpSocket* socket,
                                         const QString& sessionId,
                                         const QByteArray& data)
{
  SS_ASSERT(!data.isEmpty(), return);

  if (socket && m_sockets.value(socket) == sessionId && socket->isWritable())
    socket->write(data);

  Q_EMIT streamWriteDone(socket, sessionId);
}

bool API::Server::isStreamCommand(const QString& command)
{
  return command == QLatin1String("stream.subscribe")
      || command == QLatin1String("stream.unsubscribe");
}

void API::Server::handleStreamCommand(QTcpSocket* socket,
                                      ConnectionState& state,
                                      const QJsonObject& json)
{
  SS_ASSERT(socket != nullptr, return);
  SS_ASSERT_LOG(!state.sessionId.isEmpty());

  const auto request = CommandRequest::fromJson(json);
  if (request.command == QLatin1String("stream.subscribe"))
    sendResponseToSocket(socket, streamSubscribe(state, request).toJsonBytes());
  else
    sendResponseToSocket(socket, streamUnsubscribe(state, request).toJsonBytes());
}

API::CommandResponse API::Server::streamSubscribe(ConnectionState& state,
                                                  const CommandRequest& request)
{
  SS_ASSERT_LOG(state.authenticated);

  state.streamSources.clear();
  const auto sources = request.params.value(QStringLiteral("sources")).toArray();
  for (const auto& value : sources)
    state.streamSources.insert(value.toInt(-1));

  state.streamSubscribed = true;
  state.streamSeq        = 0;
  state.streamMissed     = 0;
  state.streamPending.clear();

  QJsonArray subscribed;
  for (const int sourceId : std::as_const(state.streamSources))
    subscribed.append(sourceId);

  QJsonObject result;
  result.insert(QStringLiteral("connectionId"), state.sessionId);
  result.insert(QStringLiteral("subscribed"), true);
  result.insert(QStringLiteral("sources"), subscribed);
  result.insert(QStringLiteral("queueDepth"), static_cast<int>(kStreamQueueDepth));
  result.insert(QStringLiteral("encoding"), QStringLiteral("base64:float32le"));
  return CommandResponse::makeSuccess(request.id, result);
}

API::CommandResponse API::Server::streamUnsubscribe(ConnectionState& state,
                                                    const CommandRequest& request)
{
  if (!state.streamSubscribed) {
    return CommandResponse::makeError(request.id,
                                      ErrorCode::ExecutionError,
                                      QStringLiteral("This connection holds no stream "
                                                     "subscription"));
  }

  state.streamSubscribed = false;
  state.streamPending.clear();

  QJsonObject result;
  result.insert(QStringLiteral("subscribed"), false);
  result.insert(QStringLiteral("missed"), static_cast<double>(state.streamMissed));
  return CommandResponse::makeSuccess(request.id, result);
}

void API::Server::ingestStreamBlock(const IO::StreamBlockItemPtr& block)
{
  if (!block || !enabled())
    return;

  for (auto it = m_connections.begin(); it != m_connections.end(); ++it) {
    auto& state = it.value();
    if (!state.streamSubscribed)
      continue;

    if (!state.streamSources.isEmpty() && !state.streamSources.contains(block->sourceId))
      continue;

    state.streamPending.push_back(block);
    while (state.streamPending.size() > kStreamQueueDepth) {
      state.streamPending.pop_front();
      ++state.streamMissed;
    }

    pumpStreamQueue(it.key(), state);
  }
}

void API::Server::pumpStreamQueue(QTcpSocket* socket, ConnectionState& state)
{
  SS_ASSERT(socket != nullptr, return);

  if (state.streamWriteInFlight || state.streamPending.empty())
    return;

  const auto block = state.streamPending.front();
  state.streamPending.pop_front();
  if (!block)
    return;

  const qint64 t0Ms =
    std::chrono::duration_cast<std::chrono::milliseconds>(block->t0.time_since_epoch()).count();

  QByteArray payload;
  const auto missed  = state.streamMissed;
  state.streamMissed = 0;
  ++state.streamSeq;

  const std::size_t channelCount = std::min(block->uniqueIds.size(), block->channels.size());
  for (std::size_t c = 0; c < channelCount; ++c) {
    const auto& samples = block->channels[c];

    QByteArray raw;
    raw.resize(static_cast<qsizetype>(samples.size() * sizeof(float)));
    auto* out = reinterpret_cast<float*>(raw.data());
    for (std::size_t i = 0; i < samples.size(); ++i)
      out[i] = static_cast<float>(samples[i]);

    QJsonObject entry;
    entry.insert(Keys::SourceId, block->sourceId);
    entry.insert(Keys::UniqueId, block->uniqueIds[c]);
    entry.insert(QStringLiteral("seq"), static_cast<double>(state.streamSeq));
    entry.insert(QStringLiteral("missed"), static_cast<double>(missed));
    entry.insert(QStringLiteral("t0Ms"), static_cast<double>(t0Ms));
    entry.insert(QStringLiteral("dtNs"), static_cast<double>(block->dt.count()));
    entry.insert(QStringLiteral("count"), static_cast<double>(samples.size()));
    entry.insert(QStringLiteral("data"), QString::fromLatin1(raw.toBase64()));

    QJsonObject line;
    line.insert(QStringLiteral("streamBlock"), entry);
    payload += QJsonDocument(line).toJson(QJsonDocument::Compact) + '\n';
  }

  if (payload.isEmpty())
    return;

  state.streamWriteInFlight = true;
  auto* worker              = static_cast<ServerWorker*>(m_worker);
  QMetaObject::invokeMethod(worker,
                            "writeStreamBlock",
                            Qt::QueuedConnection,
                            Q_ARG(QTcpSocket*, socket),
                            Q_ARG(QString, state.sessionId),
                            Q_ARG(QByteArray, payload));
}

void API::Server::onStreamWriteDone(QTcpSocket* socket, const QString& sessionId)
{
  const auto it = m_connections.find(socket);
  if (it == m_connections.end() || it->sessionId != sessionId)
    return;

  it->streamWriteInFlight = false;
  pumpStreamQueue(socket, it.value());
}

bool BenchmarkRunner::deviceConnected() const
{
  static auto& ioManager = IO::ConnectionManager::instance();
  return ioManager.isConnected();
}

void BenchmarkRunner::abortSession()
{
  if (!m_running)
    return;

  m_running = false;
  m_phases.clear();
  HotpathBenchmark::setActive(false);
  restoreEnvironment();
}

static double streamPhaseThroughput(const QString& transformCode, bool fastMode, double seconds)
{
  IO::StreamConfig config;
  config.sourceId    = 0;
  config.channels    = 2;
  config.sampleRate  = 96000.0;
  config.luaFastMode = fastMode;
  for (int channel = 0; channel < 2; ++channel) {
    IO::StreamChannelConfig dataset;
    dataset.uniqueId          = channel;
    dataset.channel           = channel;
    dataset.plot              = true;
    dataset.transformLanguage = SerialStudio::Lua;
    dataset.transformCode     = transformCode;
    config.datasets.push_back(dataset);
  }

  moodycamel::ReaderWriterQueue<IO::StreamDisplayUpdatePtr> ring(4096);
  std::atomic<int> pixelWidth{512};
  std::atomic<double> windowSec{10.0};
  std::atomic<bool> exportActive{false};
  IO::StreamProcessor processor(config, &ring, &pixelWidth, &windowSec, &exportActive);
  processor.compileEngines();

  constexpr qsizetype kFrames = 960;
  auto block                  = std::make_shared<IO::SampleBlock>();
  block->channels             = 2;
  block->frames               = kFrames;
  block->t0                   = IO::SampleBlock::SteadyTimePoint(std::chrono::seconds(1));
  block->dt                   = std::chrono::nanoseconds(1'000'000'000 / 96'000);
  block->samples.resize(static_cast<std::size_t>(kFrames) * 2);
  for (qsizetype i = 0; i < kFrames * 2; ++i)
    block->samples[static_cast<std::size_t>(i)] = std::sin(static_cast<float>(i) * 0.01f) * 1000.0f;

  using Clock      = std::chrono::steady_clock;
  const auto start = Clock::now();
  double elapsed   = 0.0;
  IO::StreamDisplayUpdatePtr drained;
  // code-verify off
  // Wall-clock-bounded drive loop; the inner drain is bounded by the ring capacity.
  while (elapsed < seconds) {
    processor.onSampleBlock(block);

    while (ring.try_dequeue(drained)) {
    }

    elapsed = std::chrono::duration<double>(Clock::now() - start).count();
  }
  // code-verify on

  const auto frames = processor.samplesProcessed();
  return elapsed > 0.0 ? static_cast<double>(frames) / elapsed : 0.0;
}

static void runStreamPhase(double minSeconds)
{
  const double window = std::max(1.0, minSeconds * 0.25);

  const QString heavy = QStringLiteral("function transform_block(samples, info)\n"
                                       "  local b0, b1, b2 = 0.2, 0.4, 0.2\n"
                                       "  local x1, x2 = 0, 0\n"
                                       "  for i = 1, info.count do\n"
                                       "    local x = samples[i]\n"
                                       "    samples[i] = b0 * x + b1 * x1 + b2 * x2\n"
                                       "    x2 = x1\n"
                                       "    x1 = x\n"
                                       "  end\n"
                                       "  return samples\n"
                                       "end\n");

  const double raw  = streamPhaseThroughput(QString(), false, window);
  const double safe = streamPhaseThroughput(heavy, false, window);
  const double fast = streamPhaseThroughput(heavy, true, window);

  // code-verify off
  // Benchmark report lines must reach raw stdout (CI parses them); qDebug would detour through
  // the message handler and the console widget.
  std::printf("hotpath-stream: raw %.0f frames/s, lua-block safe %.0f frames/s, "
              "lua-block fast %.0f frames/s (2 ch, 96 kHz target per source)\n",
              raw,
              safe,
              fast);
  std::printf("HOTPATH_STREAM_RAW_FPS=%.0f HOTPATH_STREAM_SAFE_FPS=%.0f "
              "HOTPATH_STREAM_FAST_FPS=%.0f\n",
              raw,
              safe,
              fast);
  std::fflush(stdout);
  // code-verify on
}

void CSV::StreamExportWorker::closeResources()
{
  for (auto& [sourceId, state] : m_files) {
    if (state.stream)
      state.stream->flush();

    if (state.file)
      state.file->close();
  }

  m_files.clear();
}

CSV::StreamExportWorker::FileState* CSV::StreamExportWorker::fileFor(
  const IO::StreamBlockItem& block)
{
  auto it = m_files.find(block.sourceId);
  if (it != m_files.end())
    return &it->second;

  const auto dt       = QDateTime::currentDateTime();
  const auto fileName = dt.toString(QStringLiteral("yyyy-MM-dd_HH-mm-ss"))
                      + QStringLiteral("_stream_source%1.csv").arg(block.sourceId);

  static auto& workspaceManager = Misc::WorkspaceManager::instance();
  QDir dir(workspaceManager.path(QStringLiteral("CSV")));

  FileState state;
  state.file = std::make_unique<QFile>(dir.filePath(fileName));
  if (!state.file->open(QIODevice::WriteOnly | QIODevice::Text)) {
    qWarning() << "[CSV] cannot open stream export file" << state.file->fileName();
    return nullptr;
  }

  state.stream = std::make_unique<QTextStream>(state.file.get());
  state.start  = block.t0;

  *state.stream << "Time (s)";
  for (const int uniqueId : block.uniqueIds)
    *state.stream << ",ds" << uniqueId;

  *state.stream << '\n';

  auto [inserted, ok] = m_files.emplace(block.sourceId, std::move(state));
  return ok ? &inserted->second : nullptr;
}

void CSV::StreamExportWorker::writeBlock(FileState& state, const IO::StreamBlockItem& block)
{
  const double baseSec = std::chrono::duration<double>(block.t0 - state.start).count();
  const double dtSec   = std::chrono::duration<double>(block.dt).count();
  auto& stream         = *state.stream;

  for (qsizetype i = 0; i < block.frames; ++i) {
    stream << QString::number(baseSec + static_cast<double>(i) * dtSec, 'f', 9);
    for (const auto& channel : block.channels) {
      stream << ',';
      if (static_cast<std::size_t>(i) < channel.size())
        stream << QString::number(channel[static_cast<std::size_t>(i)], 'g', 10);
    }

    stream << '\n';
  }
}

void CSV::StreamExportWorker::processItems(const std::vector<IO::StreamBlockItemPtr>& items)
{
  for (const auto& block : items) {
    if (!block || block->frames <= 0)
      continue;

    auto* state = fileFor(*block);
    if (!state)
      continue;

    writeBlock(*state, *block);
  }

  for (auto& [sourceId, state] : m_files)
    if (state.stream)
      state.stream->flush();
}

CSV::StreamExport::StreamExport()
  : DataModel::FrameConsumer<IO::StreamBlockItemPtr>(
      {.queueCapacity = 4096, .flushThreshold = 256, .timerIntervalMs = 500})
{
  initializeWorker();
  setConsumerEnabled(false);
}

void CSV::StreamExport::ingestBlock(const IO::StreamBlockItemPtr& block)
{
  if (block)
    enqueueData(block);
}

void CSV::StreamExport::closeFiles()
{
  if (m_worker)
    QMetaObject::invokeMethod(m_worker, "close", Qt::QueuedConnection);
}

DataModel::DataTableSnapshotPtr DataModel::DataTableStore::makeSnapshot() const
{
  auto snapshot = std::make_shared<DataTableSnapshot>();
  if (!m_initialized)
    return snapshot;

  snapshot->generation   = m_generation;
  snapshot->writeClock   = m_writeClock;
  snapshot->values       = m_storage;
  snapshot->index        = m_index;
  snapshot->datasetIndex = m_datasetIndex;
  snapshot->aliasIndex   = m_aliasIndex;
  return snapshot;
}

[[nodiscard]] static const DataModel::RegisterValue* snapshotSlot(
  const DataModel::DataTableSnapshot& snapshot, int slot)
{
  if (slot < 0 || slot >= static_cast<int>(snapshot.values.size())) [[unlikely]]
    return nullptr;

  return &snapshot.values[static_cast<size_t>(slot)];
}

const DataModel::RegisterValue* DataModel::DataTableSnapshot::get(const QString& table,
                                                                  const QString& reg) const
{
  const auto it = index.constFind(qMakePair(table, reg));
  if (it == index.constEnd()) [[unlikely]]
    return nullptr;

  return snapshotSlot(*this, it.value());
}

qint64 DataModel::DataTableSnapshot::handleOf(const QString& table, const QString& reg) const
{
  const auto it = index.constFind(qMakePair(table, reg));
  if (it == index.constEnd()) [[unlikely]]
    return -1;

  return (static_cast<qint64>(generation) << kHandleIndexBits) | static_cast<qint64>(it.value());
}

const DataModel::RegisterValue* DataModel::DataTableSnapshot::getByHandle(qint64 handle) const
{
  if (handle < 0) [[unlikely]]
    return nullptr;

  if (static_cast<int>(handle >> kHandleIndexBits) != generation) [[unlikely]]
    return nullptr;

  return snapshotSlot(*this, static_cast<int>(handle & kHandleIndexMask));
}

const DataModel::RegisterValue* DataModel::DataTableSnapshot::getDatasetRaw(int uniqueId) const
{
  const auto it = datasetIndex.constFind(uniqueId);
  if (it == datasetIndex.constEnd()) [[unlikely]]
    return nullptr;

  return snapshotSlot(*this, it->first);
}

const DataModel::RegisterValue* DataModel::DataTableSnapshot::getDatasetFinal(int uniqueId) const
{
  const auto it = datasetIndex.constFind(uniqueId);
  if (it == datasetIndex.constEnd()) [[unlikely]]
    return nullptr;

  return snapshotSlot(*this, it->second);
}

const DataModel::RegisterValue* DataModel::DataTableSnapshot::getDatasetRawByAlias(
  const QString& alias) const
{
  const auto it = aliasIndex.constFind(alias);
  if (it == aliasIndex.constEnd()) [[unlikely]]
    return nullptr;

  return snapshotSlot(*this, it->first);
}

const DataModel::RegisterValue* DataModel::DataTableSnapshot::getDatasetFinalByAlias(
  const QString& alias) const
{
  const auto it = aliasIndex.constFind(alias);
  if (it == aliasIndex.constEnd()) [[unlikely]]
    return nullptr;

  return snapshotSlot(*this, it->second);
}

QVariant DataModel::TableApiBridge::tableGet(const QString& t, const QString& r)
{
  SS_ASSERT(context.store != nullptr, return {});
  QVariant out;
  readTableView(context, [&](const auto& view) { out = registerVariant(view.get(t, r)); });
  return out;
  SS_ASSERT(context.store != nullptr, return);
  auto* target = context.store;
  writeTableStore(context, [target, t, r, rv = std::move(rv)] { (void)target->set(t, r, rv); });
  SS_ASSERT(context.store != nullptr, return -1);

  qint64 handle = -1;
  readTableView(context, [&](const auto& view) { handle = view.handleOf(t, r); });
  return handle;
  SS_ASSERT(context.store != nullptr, return {});
  readTableView(context, [&](const auto& view) {
    for (const QVariant& reg : regs)
      handles.append(QVariant(view.handleOf(t, reg.toString())));
  });
  SS_ASSERT(context.store != nullptr, return {});
  QVariant out;
  readTableView(context, [&](const auto& view) { out = registerVariant(view.getByHandle(h)); });
  return out;
  SS_ASSERT(context.store != nullptr, return);
  auto* target = context.store;
  writeTableStore(context, [target, h, rv = std::move(rv)] { (void)target->setByHandle(h, rv); });
  SS_ASSERT(context.store != nullptr, return {});

  const bool isString = sel.isString();
  const bool isNumber = sel.isNumber();
  const QString alias = isString ? sel.toString() : QString();
  const int uniqueId  = isNumber ? sel.toInt() : -1;

  QVariant out;
  readTableView(context, [&](const auto& view) {
    if (isString)
      out = registerVariant(view.getDatasetRawByAlias(alias));
    else if (isNumber)
      out = registerVariant(view.getDatasetRaw(uniqueId));
  });

  return out;
  SS_ASSERT(context.store != nullptr, return {});

  const bool isString = sel.isString();
  const bool isNumber = sel.isNumber();
  const QString alias = isString ? sel.toString() : QString();
  const int uniqueId  = isNumber ? sel.toInt() : -1;

  QVariant out;
  readTableView(context, [&](const auto& view) {
    if (isString)
      out = registerVariant(view.getDatasetFinalByAlias(alias));
    else if (isNumber)
      out = registerVariant(view.getDatasetFinal(uniqueId));
  });

  return out;

void DataModel::FrameBuilder::publishSourceTemplate(int sourceId)
{
  SS_ASSERT(sourceId >= 0, return);

  if (m_operationMode != SerialStudio::ProjectFile || m_frame.groups.empty())
    return;

  for (const auto& src : m_frame.sources)
    if (src.sourceId == sourceId) {
      publishSourceTemplateFrame(src);
      return;
    }
}

void DataModel::FrameBuilder::publishQuickPlotAudioTemplate(int channels)
{
  SS_ASSERT(channels > 0, return);

  if (m_operationMode != SerialStudio::QuickPlot)
    return;

  QStringList channelValues;
  channelValues.reserve(channels);
  for (int i = 0; i < channels; ++i)
    channelValues.append(QStringLiteral("0"));

  invalidateFramePool();
  buildQuickPlotAudioFrame(channelValues);
  m_quickPlotChannels = channels;

  if (!m_quickPlotFrame.groups.empty())
    hotpathTxFrame(acquireFrame(m_quickPlotFrame));
}

void DataModel::FrameBuilder::ingestStreamValues(int sourceId,
                                                 const QList<QPair<int, double>>& values)
{
  SS_ASSERT(sourceId >= 0, return);
  SS_ASSERT_LOG(QThread::currentThread() == thread());

  if (!m_tableStore.isInitialized() || values.isEmpty())
    return;

  for (const auto& [uniqueId, value] : values) {
    m_tableStore.setDatasetRaw(uniqueId, value, QString(), true);
    m_tableStore.setDatasetFinal(uniqueId, value, QString(), true);
    m_streamDatasetIds.insert(uniqueId);
  }

  m_streamValuesDirty = true;
}

void DataModel::FrameBuilder::setStreamSourceIds(const QSet<int>& sourceIds)
{
  if (QThread::currentThread() != thread()) {
    invokeOnBuilderThreadBlocking([this, sourceIds] { setStreamSourceIds(sourceIds); });
    return;
  }

  m_streamSourceIds = sourceIds;
  m_streamDatasetIds.clear();
}

void DataModel::FrameBuilder::refreshStreamDrivenFrames()
{
  if (!m_streamValuesDirty)
    return;

  m_streamValuesDirty = false;
  if (m_operationMode != SerialStudio::ProjectFile)
    return;

  (void)republishFrames(false);
}

void DataModel::FrameBuilder::drainTableSnapshot()
{
  SS_ASSERT(qApp != nullptr, return);
  SS_ASSERT(QThread::currentThread() == qApp->thread(), return);

  if (!m_guiTableApiUsers.load(std::memory_order_relaxed)) [[likely]]
    return;

  DataModel::DataTableSnapshotPtr snapshot;
  // code-verify off
  // Ring drain: bounded by the mirror ring capacity (4), provably finite per tick.
  while (m_tableMirrorRing.try_dequeue(snapshot))
    if (snapshot)
      m_guiTableSnapshot = snapshot;
  // code-verify on

  snapshot.reset();

  if (!m_tableSnapshotRequested.exchange(true, std::memory_order_acq_rel))
    invokeOnBuilderThread([this] { publishTableSnapshot(); });
}

void DataModel::FrameBuilder::noteGuiTableApiUser()
{
  if (qApp && QThread::currentThread() == qApp->thread())
    m_guiTableApiUsers.store(true, std::memory_order_relaxed);
}

const DataModel::TableApiContext& DataModel::FrameBuilder::guiTableApiContext()
{
  noteGuiTableApiUser();
  return m_luaTableContext;
}

void DataModel::FrameBuilder::publishTableSnapshot()
{
  SS_ASSERT(QThread::currentThread() == thread(), return);

  m_tableSnapshotRequested.store(false, std::memory_order_release);

  const int generation = m_tableStore.isInitialized() ? m_tableStore.generation() : -1;
  const quint64 clock  = m_tableStore.writeClock();
  if (generation == m_publishedTableGeneration && clock == m_publishedTableClock)
    return;

  if (!m_tableMirrorRing.try_enqueue(m_tableStore.makeSnapshot())) [[unlikely]]
    return;

  m_publishedTableGeneration = generation;
  m_publishedTableClock      = clock;
}

std::vector<DataModel::FrameBuilder::ParseLoad> DataModel::FrameBuilder::guiParseLoads()
{
  ParseLoadsPtr sample;
  // code-verify off
  // Ring drain: bounded by the mirror ring capacity (4), provably finite per call.
  while (m_parseLoadMirrorRing.try_dequeue(sample))
    if (sample)
      m_guiParseLoads = sample;
  // code-verify on

  sample.reset();
  return m_guiParseLoads ? *m_guiParseLoads : std::vector<ParseLoad>();
}

DataModel::FrameBuilder::LatestFrameInfo DataModel::FrameBuilder::latestFrameSnapshot(int sourceId)
{
  if (QThread::currentThread() == thread()) {
    const auto* info = latestFrame(sourceId);
    return info ? *info : LatestFrameInfo();
  }

  if (qApp && QThread::currentThread() == qApp->thread())
    return guiLatestFrame(sourceId);

  LatestFrameInfo copy;
  invokeOnBuilderThreadBlocking([this, sourceId, &copy] {
    const auto* info = latestFrame(sourceId);
    if (info)
      copy = *info;
  });

  return copy;
}

DataModel::FrameBuilder::LatestFrameInfo DataModel::FrameBuilder::guiLatestFrame(int sourceId)
{
  m_guiLatestFrameUsers.store(true, std::memory_order_relaxed);

  const auto mirror = m_guiLatestFrameMirror;
  if (!mirror)
    return LatestFrameInfo();

  const int key = (sourceId >= 0) ? sourceId : mirror->newestSourceId;
  if (key < 0)
    return LatestFrameInfo();

  const auto it = mirror->frames.constFind(key);
  return (it != mirror->frames.constEnd()) ? it.value() : LatestFrameInfo();
}

void DataModel::FrameBuilder::publishLatestFrameSnapshot()
{
  SS_ASSERT(QThread::currentThread() == thread(), return);

  m_latestFrameSnapshotRequested.store(false, std::memory_order_release);

  if (m_latestFrameSeq == m_publishedLatestFrameSeq)
    return;

  auto mirror            = std::make_shared<LatestFrameMirror>();
  mirror->newestSourceId = m_latestFrameSourceId;
  mirror->frames         = m_latestFrames;

  if (!m_latestFrameMirrorRing.try_enqueue(LatestFrameMirrorPtr(std::move(mirror)))) [[unlikely]]
    return;

  m_publishedLatestFrameSeq = m_latestFrameSeq;
}

void DataModel::FrameBuilder::drainLatestFrameSnapshot()
{
  SS_ASSERT(qApp != nullptr, return);
  SS_ASSERT(QThread::currentThread() == qApp->thread(), return);

  if (!m_guiLatestFrameUsers.load(std::memory_order_relaxed)) [[likely]]
    return;

  LatestFrameMirrorPtr mirror;
  // code-verify off
  // Ring drain: bounded by the mirror ring capacity (4), provably finite per tick.
  while (m_latestFrameMirrorRing.try_dequeue(mirror))
    if (mirror)
      m_guiLatestFrameMirror = mirror;
  // code-verify on

  mirror.reset();

  if (!m_latestFrameSnapshotRequested.exchange(true, std::memory_order_acq_rel))
    invokeOnBuilderThread([this] { publishLatestFrameSnapshot(); });
}

static void luaPushRegister(lua_State* L, const DataModel::RegisterValue* val)
{
  if (!val) {
    lua_pushnil(L);
    return;
  }

  if (val->isNumeric) {
    lua_pushnumber(L, val->numericValue);
    return;
  }

  const auto utf8 = val->stringValue.toUtf8();
  lua_pushlstring(L, utf8.constData(), static_cast<size_t>(utf8.size()));
}

void DataModel::ProjectEditor::applyGroupLogAxisEdit(bool xAxis, bool enabled, int groupId)
{
  for (auto& dataset : m_selectedGroup.datasets)
    if (xAxis)
      dataset.pltLogX = enabled;
    else
      dataset.pltLogY = enabled;

  m_projectModelRef.updateGroup(groupId, m_selectedGroup);
}

void DataModel::ProjectEditor::applyGroupBarPanelStyleEdit(int styleIdx, int groupId)
{
  static const QStringList kStyles = {
    QLatin1String(""), QStringLiteral("horizontal"), QStringLiteral("vertical")};

  m_selectedGroup.barPanelStyle = kStyles.value(styleIdx);
  m_projectModelRef.setNextUndoHint(tr("Edit Group"),
                                    QStringLiteral("group-barstyle:%1").arg(groupId));
  m_projectModelRef.updateGroup(groupId, m_selectedGroup, false);
}

void DataModel::ProjectEditor::buildGroupBarPanelStyleRow(const DataModel::Group& group)
{
  int index = 0;
  if (group.barPanelStyle == QLatin1String("horizontal"))
    index = 1;
  else if (group.barPanelStyle == QLatin1String("vertical"))
    index = 2;

  auto* item = new QStandardItem();
  item->setEditable(true);
  item->setData(true, Active);
  item->setData(ComboBox, WidgetType);
  item->setData(QStringList{tr("Auto"), tr("Horizontal"), tr("Vertical")}, ComboBoxData);
  item->setData(index, EditableValue);
  item->setData(kGroupView_BarPanelStyle, ParameterType);
  item->setData(tr("Bar Style"), ParameterName);
  item->setData(tr("Bar orientation: automatic, horizontal rows, or vertical columns"),
                ParameterDescription);
  m_groupModel->appendRow(item);
}

void DataModel::ProjectModel::updateSourceStreamLane(int sourceId, const QString& lane)
{
  const QString effective = (lane == QLatin1String("auto")) ? QString() : lane;
  if (!effective.isEmpty() && effective != QLatin1String("on") && effective != QLatin1String("off"))
    return;

  const ProjectUndoScope undo_scope{*this, tr("Change Stream Lane")};
  auto it =
    std::find_if(m_sources.begin(), m_sources.end(), [sourceId](const DataModel::Source& src) {
      return src.sourceId == sourceId;
    });

  if (it == m_sources.end() || it->streamLane == effective)
    return;

  it->streamLane = effective;
  setModified(true);

  Q_EMIT sourceStreamLaneChanged(sourceId);
  Q_EMIT sourceChanged(sourceId);
}

