}

QList<DataModel::ScriptStat> DataModel::FrameParser::guiScriptStats()
{
  ScriptStatsPtr sample;
  // code-verify off
  // Ring drain: bounded by the mirror ring capacity (4), provably finite per call.
  while (m_statsMirrorRing.try_dequeue(sample))
