void IO::ConnectionManager::dropUnavailablePrimaryDevice(SerialStudio::BusType type)
{
  auto existing = m_devices.find(0);
  if (existing != m_devices.end()) {
    if (existing->second)
      disconnect(existing->second.get(), nullptr, this, nullptr);

    m_devices.erase(existing);
  }

  if (uiDriverForBusType(type) != nullptr) {
    QMetaObject::invokeMethod(
      this,
      [] {
        Misc::Utilities::showMessageBox(
          tr("This connection type requires an active license or trial."),
          tr("Activate Serial Studio Pro or start a trial to use this device type."));
      },
      Qt::QueuedConnection);
  }
}

QString IO::ConnectionManager::streamLaneForSource(int deviceId) const
{
  static auto& appState = AppState::instance();
  if (appState.operationMode() != SerialStudio::ProjectFile)
    return QString();

  static auto& projectModel = DataModel::ProjectModel::instance();
  for (const auto& src : projectModel.sources())
    if (src.sourceId == deviceId)
      return src.streamLane;

  return QString();
}

IO::StreamConfig IO::ConnectionManager::buildStreamConfig(int deviceId, HAL_Driver* driver) const
{
  SS_ASSERT(driver != nullptr, return {});
  SS_ASSERT_LOG(deviceId >= 0);

  StreamConfig config;
  config.sourceId = deviceId;

#ifdef BUILD_COMMERCIAL
  if (auto* audioDriver = qobject_cast<IO::Drivers::Audio*>(driver)) {
    config.channels   = std::max(1u, audioDriver->config().capture.channels);
    config.sampleRate = static_cast<double>(audioDriver->config().sampleRate);
  }
#endif

  static auto& appState     = AppState::instance();
  static auto& projectModel = DataModel::ProjectModel::instance();
  config.luaFastMode        = projectModel.luaFastMode();

  const auto appendGroupChannels = [&config](const DataModel::Group& group) {
    for (const auto& dataset : group.datasets) {
      if (!dataset.enabled || dataset.index <= 0)
        continue;

      StreamChannelConfig channel;
      channel.uniqueId =
        dataset.uniqueId >= 0 ? dataset.uniqueId : DataModel::dataset_unique_id(group, dataset);
      channel.channel = dataset.index - 1;
      channel.plot    = dataset.plt;
#ifdef BUILD_COMMERCIAL
      channel.fft = dataset.fft || dataset.waterfall;
#else
      channel.fft = dataset.fft;
#endif
      channel.fftSamples        = dataset.fftSamples;
      channel.transformLanguage = dataset.transformLanguage;
      channel.transformCode     = dataset.transformCode;
      config.datasets.push_back(std::move(channel));
    }
  };

  if (appState.operationMode() == SerialStudio::ProjectFile) {
    for (const auto& group : projectModel.groups())
      if (group.sourceId == deviceId)
        appendGroupChannels(group);
  } else {
    const int targetSamples = static_cast<int>(config.sampleRate * 0.05);
    int fftSamples          = 256;
    while (fftSamples < targetSamples && fftSamples < 8192)
      fftSamples *= 2;

    for (int i = 0; i < config.channels; ++i) {
      StreamChannelConfig channel;
      channel.uniqueId   = DataModel::dataset_unique_id(0, 0, i);
      channel.channel    = i;
      channel.plot       = true;
      channel.fft        = true;
      channel.fftSamples = fftSamples;
      config.datasets.push_back(std::move(channel));
    }
  }

  return config;
}

void IO::ConnectionManager::rebuildStreamWorkers()
{
  stopStreamWorkers();

  for (const auto& [deviceId, dm] : m_devices) {
    if (!dm || !dm->driver())
      continue;

    HAL_Driver* halDriver = dm->driver();
    const bool laneOn     = IO::streamLaneOn(halDriver, streamLaneForSource(deviceId));

    auto config       = laneOn ? buildStreamConfig(deviceId, halDriver) : StreamConfig{};
    const bool active = laneOn && !config.datasets.empty();

#ifdef BUILD_COMMERCIAL
    if (auto* audioDriver = qobject_cast<IO::Drivers::Audio*>(halDriver))
      audioDriver->setStreamLaneActive(active);
#endif

    if (!active)
      continue;

    auto worker = std::make_unique<StreamWorker>(halDriver, config, nullptr);
    wireStreamWorkerSinks(*worker);
    m_streamWorkers.push_back(std::move(worker));
  }

  refreshStreamExportFlags();

  QSet<int> streamSourceIds;
  for (const auto& worker : m_streamWorkers)
    if (worker)
      streamSourceIds.insert(worker->sourceId());

  static auto& frameBuilder = DataModel::FrameBuilder::instance();
  frameBuilder.setStreamSourceIds(streamSourceIds);

  if (!m_streamWorkers.empty() && isConnected())
    publishStreamTemplates();
}

void IO::ConnectionManager::wireStreamWorkerSinks(StreamWorker& worker)
{
  auto* processor = worker.processor();
  SS_ASSERT(processor != nullptr, return);

  static auto& csvSink = CSV::Export::instance().streamSink();
  connect(processor,
          &IO::StreamProcessor::blockReady,
          &csvSink,
          &CSV::StreamExport::ingestBlock,
          Qt::QueuedConnection);

#ifdef BUILD_COMMERCIAL
  static auto& mdf4Sink = MDF4::Export::instance().streamSink();
  connect(processor,
          &IO::StreamProcessor::blockReady,
          &mdf4Sink,
          &MDF4::StreamExport::ingestBlock,
          Qt::QueuedConnection);
#endif

  static auto& frameBuilder = DataModel::FrameBuilder::instance();
  connect(processor,
          &IO::StreamProcessor::latestValuesReady,
          &frameBuilder,
          &DataModel::FrameBuilder::ingestStreamValues,
          Qt::QueuedConnection);

  static auto& apiServer = API::Server::instance();
  connect(processor,
          &IO::StreamProcessor::blockReady,
          &apiServer,
          &API::Server::ingestStreamBlock,
          Qt::QueuedConnection);
}

void IO::ConnectionManager::refreshStreamExportFlags()
{
  static auto& csvExport = CSV::Export::instance();
  static auto& apiServer = API::Server::instance();
  bool exportOn          = csvExport.exportEnabled() || apiServer.enabled();
#ifdef BUILD_COMMERCIAL
  static auto& mdf4Export = MDF4::Export::instance();
  exportOn                = exportOn || mdf4Export.exportEnabled();
#endif

  for (auto& worker : m_streamWorkers)
    if (worker)
      worker->setExportActive(exportOn);
}

void IO::ConnectionManager::publishStreamTemplates()
{
  static auto& appState     = AppState::instance();
  static auto& frameBuilder = DataModel::FrameBuilder::instance();

  if (appState.operationMode() == SerialStudio::ProjectFile) {
    for (const auto& worker : m_streamWorkers) {
      const int sourceId = worker->sourceId();
      frameBuilder.invokeOnBuilderThread(
        [sourceId] { frameBuilder.publishSourceTemplate(sourceId); });
    }

    return;
  }

  for (const auto& worker : m_streamWorkers) {
    const int channels = worker->config().channels;
    frameBuilder.invokeOnBuilderThread(
      [channels] { frameBuilder.publishQuickPlotAudioTemplate(channels); });
  }
}

void IO::ConnectionManager::stopStreamWorkers()
{
  for (auto& worker : m_streamWorkers)
    if (worker)
      worker->stop();

  m_streamWorkers.clear();
}

const std::vector<std::unique_ptr<IO::StreamWorker>>& IO::ConnectionManager::streamWorkers()
  const noexcept
{
  return m_streamWorkers;
}

void IO::Drivers::Audio::setDiscoveryPaused(const bool paused)
{
  if (m_discoveryPaused == paused)
    return;

  m_discoveryPaused = paused;
  if (!paused)
    refreshAudioDevices();
}

void IO::Drivers::HID::setDiscoveryPaused(const bool paused)
{
  if (paused) {
    m_enumTimer.stop();
    return;
  }

  if (!m_enumTimer.isActive()) {
    enumerateDevices();
    m_enumTimer.start();
  }
}

void IO::PipelineHost::setupExternalConnections()
{
  auto& appState  = AppState::instance();
  auto& ioManager = IO::ConnectionManager::instance();

  m_frameBuilder = &DataModel::FrameBuilder::instance();
  m_frameParser  = &DataModel::FrameParser::instance();

  connect(&appState, &AppState::operationModeChanged, this, [this, &appState] {
    m_operationMode.store(static_cast<int>(appState.operationMode()), std::memory_order_relaxed);
  });
  connect(&ioManager, &IO::ConnectionManager::connectedChanged, this, [this, &ioManager] {
    m_connected.store(ioManager.isConnected(), std::memory_order_relaxed);
  });
  connect(&ioManager, &IO::ConnectionManager::pausedChanged, this, [this, &ioManager] {
    m_paused.store(ioManager.paused(), std::memory_order_relaxed);
  });

  m_paused.store(ioManager.paused(), std::memory_order_relaxed);
  m_connected.store(ioManager.isConnected(), std::memory_order_relaxed);
  m_operationMode.store(static_cast<int>(appState.operationMode()), std::memory_order_relaxed);
}

void IO::PipelineHost::registerFrameReader(int deviceId, FrameReader* reader)
{
  SS_ASSERT(reader != nullptr, return);
  SS_ASSERT(deviceId >= 0, return);
  SS_ASSERT(reader->parent() == nullptr, return);

  reader->moveToThread(m_thread.get());
  connect(
    reader,
    &IO::FrameReader::readyRead,
    reader,
    [this, deviceId, reader] { routeFrames(deviceId, reader); },
    Qt::DirectConnection);
}

void IO::PipelineHost::moveProcessingObjectsTo(QThread* target)
{
  SS_ASSERT(target != nullptr, return);
  SS_ASSERT(m_frameBuilder != nullptr, return);
  SS_ASSERT(m_frameParser != nullptr, return);

  if (m_frameParser->thread() == target)
    return;

  if (target != qApp->thread() && !target->isRunning())
    return;

  runOnObjectThread(m_frameParser, [this, target] {
    m_frameParser->releaseEngines();
    m_frameParser->moveToThread(target);
    m_frameBuilder->moveToThread(target);
  });

  QMetaObject::invokeMethod(m_frameParser, &DataModel::FrameParser::readCode);
}

void IO::PipelineHost::routeFrames(int deviceId, FrameReader* reader)
{
  SS_ASSERT(reader != nullptr, return);
  SS_ASSERT(deviceId >= 0, return);

  static auto& frameBuilder = DataModel::FrameBuilder::instance();
#ifdef BUILD_COMMERCIAL
  static auto& mqttPublisher = MQTT::Publisher::instance();
#endif

  const bool paused = m_paused.load(std::memory_order_relaxed);
  const auto mode   = operationMode();

  auto& queue = reader->queue();
  IO::CapturedDataPtr frame;
  while (queue.try_dequeue(frame)) {
    if (paused) [[unlikely]]
      continue;

    if (mode == SerialStudio::ProjectFile)
      frameBuilder.hotpathRxSourceFrame(deviceId, frame);
    else
      frameBuilder.hotpathRxFrame(frame);

#ifdef BUILD_COMMERCIAL
    mqttPublisher.hotpathTxRawFrame(deviceId, frame);
#endif
  }
}

void IO::PipelineHost::publishFrameToDashboard(const DataModel::TimestampedFramePtr& frame)
{
  SS_ASSERT(frame != nullptr, return);

  if (!m_dashboardAccepting.load(std::memory_order_relaxed))
    return;

  if (!m_dashboardRing.try_enqueue(frame)) [[unlikely]]
    ++m_dashboardDrops;
}

void IO::PipelineHost::shutdown()
{
  constexpr int kJoinTimeoutMs = 5000;

  beginTeardown();

  if (!m_thread || !m_thread->isRunning())
    return;

  if (m_frameBuilder)
    QMetaObject::invokeMethod(
      m_frameBuilder, &DataModel::FrameBuilder::prepareShutdown, Qt::QueuedConnection);

  if (m_frameParser)
    QMetaObject::invokeMethod(
      m_frameParser, &DataModel::FrameParser::prepareShutdown, Qt::QueuedConnection);

  m_thread->quit();
  if (!m_thread->wait(kJoinTimeoutMs)) [[unlikely]] {
    m_abandoned = true;
    qWarning() << "[PipelineHost] processing thread did not stop within" << kJoinTimeoutMs
               << "ms (hung script?) -- abandoning it (R21)";
  }
}

static void openSafeStreamLibs(lua_State* L)
{
  static const luaL_Reg kSafeLibs[] = {
    {    "_G",   luaopen_base},
    { "table",  luaopen_table},
    {"string", luaopen_string},
    {  "math",   luaopen_math},
    {   "bit",    luaopen_bit},
    { nullptr,        nullptr}
  };

  for (const luaL_Reg* lib = kSafeLibs; lib->func; ++lib) {
    luaL_requiref(L, lib->name, lib->func, 1);
    lua_pop(L, 1);
  }

  for (const char* name : {"dofile", "loadfile", "load"}) {
    lua_pushnil(L);
    lua_setglobal(L, name);
  }

  lua_getglobal(L, "string");
  if (lua_istable(L, -1)) {
    lua_pushnil(L);
    lua_setfield(L, -2, "dump");
  }
  lua_pop(L, 1);
}

IO::StreamProcessor::StreamProcessor(
  const StreamConfig& config,
  moodycamel::ReaderWriterQueue<StreamDisplayUpdatePtr>* displayOut,
  std::atomic<int>* pixelWidth,
  std::atomic<double>* windowSec,
  std::atomic<bool>* exportActive)
  : m_config(config)
  , m_displayOut(displayOut)
  , m_pixelWidth(pixelWidth)
  , m_windowSec(windowSec)
  , m_exportActive(exportActive)
  , m_lua(nullptr)
  , m_js(nullptr)
  , m_luaDeadline(QDeadlineTimer::Forever)
  , m_samplesProcessed(0)
  , m_blocksProcessed(0)
  , m_transformErrors(0)
  , m_displayDrops(0)
{
  SS_ASSERT_LOG(displayOut != nullptr);
  SS_ASSERT_LOG(pixelWidth != nullptr && windowSec != nullptr);

  m_channels.reserve(m_config.datasets.size());
  for (const auto& dataset : m_config.datasets) {
    ChannelState state;
    state.config = dataset;
    if (dataset.fft && dataset.fftSamples > 0)
      state.fftRing.resize(static_cast<std::size_t>(dataset.fftSamples), 0.0);

    state.envelope.reserve(64);
    m_channels.push_back(std::move(state));
  }
}

void IO::StreamProcessor::luaWatchdogHook(lua_State* L, lua_Debug* ar)
{
  Q_UNUSED(ar)

  lua_getfield(L, LUA_REGISTRYINDEX, "__ss_stream__");
  auto* self = static_cast<StreamProcessor*>(lua_touserdata(L, -1));
  lua_pop(L, 1);

  if (!self) [[unlikely]]
    return;

  if (self->m_luaDeadline.hasExpired()) [[unlikely]]
    luaL_error(L, "stream transform timed out after %d ms", kWatchdogMs);
}

void IO::StreamProcessor::setupLuaState()
{
  lua_State* L = luaL_newstate();
  if (!L) [[unlikely]]
    return;

  lua_atpanic(L, [](lua_State* state) -> int {
    const char* msg = lua_tostring(state, -1);
    qWarning() << "[StreamWorker] Lua panic:" << (msg ? msg : "<unknown>");
    throw std::runtime_error(msg ? msg : "stream lua panic");
  });

  const auto bootstrap = [](lua_State* state) -> int {
    auto* self = static_cast<StreamProcessor*>(lua_touserdata(state, 1));
    openSafeStreamLibs(state);
    DataModel::installLuaCompat(state);
    lua_pushlightuserdata(state, self);
    lua_setfield(state, LUA_REGISTRYINDEX, "__ss_stream__");
    return 0;
  };

  lua_pushcfunction(L, bootstrap);
  lua_pushlightuserdata(L, this);
  if (lua_pcall(L, 1, 0, 0) != LUA_OK) [[unlikely]] {
    qWarning() << "[StreamWorker] Lua bootstrap failed:" << lua_tostring(L, -1);
    lua_close(L);
    return;
  }

  if (m_config.luaFastMode) {
    luaJIT_setmode(L, 0, LUAJIT_MODE_ENGINE | LUAJIT_MODE_ON);
  } else {
    luaJIT_setmode(L, 0, LUAJIT_MODE_ENGINE | LUAJIT_MODE_OFF);
    lua_sethook(L, &StreamProcessor::luaWatchdogHook, LUA_MASKCOUNT, kHookInstrCount);
  }

  m_lua = L;
}

void IO::StreamProcessor::compileEngines()
{
  for (auto& state : m_channels) {
    if (state.config.transformCode.isEmpty())
      continue;

    if (state.config.transformLanguage == SerialStudio::Lua)
      compileLuaEntry(state);
    else if (state.config.transformLanguage == SerialStudio::JavaScript)
      compileJsEntry(state);
  }
}

void IO::StreamProcessor::compileLuaEntry(ChannelState& state)
{
  if (!m_lua)
    setupLuaState();

  if (!m_lua) [[unlikely]]
    return;

  lua_State* L          = m_lua;
  const QByteArray utf8 = state.config.transformCode.toUtf8();
  const QByteArray name = QByteArray("=stream[") + QByteArray::number(state.config.uniqueId) + "]";
  lua_newtable(L);
  lua_createtable(L, 0, 1);
  lua_pushglobaltable(L);
  lua_setfield(L, -2, "__index");
  lua_setmetatable(L, -2);

  if (luaL_loadbufferx(L, utf8.constData(), utf8.size(), name.constData(), "t") != LUA_OK) {
    qWarning() << "[StreamWorker] transform compile error for dataset" << state.config.uniqueId
               << ":" << lua_tostring(L, -1);
    lua_pop(L, 2);
    return;
  }

  lua_pushvalue(L, -2);
  luacompatSetChunkEnv(L);
  if (lua_pcall(L, 0, 0, 0) != LUA_OK) {
    qWarning() << "[StreamWorker] transform runtime error for dataset" << state.config.uniqueId
               << ":" << lua_tostring(L, -1);
    lua_pop(L, 2);
    return;
  }

  lua_getfield(L, -1, "transform_block");
  if (lua_isfunction(L, -1))
    state.luaBlockRef = luaL_ref(L, LUA_REGISTRYINDEX);
  else
    lua_pop(L, 1);

  lua_getfield(L, -1, "transform");
  if (lua_isfunction(L, -1))
    state.luaRef = luaL_ref(L, LUA_REGISTRYINDEX);
  else
    lua_pop(L, 1);

  lua_pop(L, 1);
}

void IO::StreamProcessor::compileJsEntry(ChannelState& state)
{
  if (!m_js)
    setupJsEngine();

  const QString wrapped =
    QStringLiteral("(function() {%1\n"
                   ";return { block: (typeof transform_block === 'function') ? "
                   "transform_block : null, sample: (typeof transform === 'function') ? "
                   "transform : null };\n"
                   "})();")
      .arg(state.config.transformCode);

  auto evalResult = m_js->evaluate(wrapped);
  if (evalResult.isError()) {
    qWarning() << "[StreamWorker] JS transform compile error for dataset" << state.config.uniqueId
               << ":" << evalResult.property(QStringLiteral("message")).toString();
    return;
  }

  state.jsBlockFn    = evalResult.property(QStringLiteral("block"));
  state.jsFn         = evalResult.property(QStringLiteral("sample"));
  state.jsBlockValid = state.jsBlockFn.isCallable();
  state.jsValid      = state.jsFn.isCallable();
}

void IO::StreamProcessor::teardownEngines()
{
  for (auto& state : m_channels) {
    if (m_lua) {
      if (state.luaRef >= 0)
        luaL_unref(m_lua, LUA_REGISTRYINDEX, state.luaRef);

      if (state.luaBlockRef >= 0)
        luaL_unref(m_lua, LUA_REGISTRYINDEX, state.luaBlockRef);
    }

    state.luaRef       = -1;
    state.luaBlockRef  = -1;
    state.jsValid      = false;
    state.jsBlockValid = false;
    state.jsFn         = QJSValue();
    state.jsBlockFn    = QJSValue();
  }

  if (m_lua) {
    lua_close(m_lua);
    m_lua = nullptr;
  }

  delete m_js;
  m_js = nullptr;
}

void IO::StreamProcessor::onSampleBlock(const IO::SampleBlockPtr& block)
{
  SS_ASSERT(block != nullptr, return);
  SS_ASSERT(block->channels > 0, return);

  if (block->frames <= 0 || block->samples.empty()) [[unlikely]]
    return;

  const quint64 blockNumber = ++m_blocksProcessed;

  std::shared_ptr<StreamBlockItem> exportItem;
  if (m_exportActive && m_exportActive->load(std::memory_order_relaxed)) {
    exportItem              = std::make_shared<StreamBlockItem>();
    exportItem->sourceId    = m_config.sourceId;
    exportItem->blockNumber = blockNumber;
    exportItem->t0          = block->t0;
    exportItem->dt          = block->dt;
    exportItem->frames      = block->frames;
    exportItem->uniqueIds.reserve(m_channels.size());
    exportItem->channels.reserve(m_channels.size());
  }

  for (auto& state : m_channels)
    processChannel(state, *block, blockNumber, exportItem.get());

  m_samplesProcessed += static_cast<quint64>(block->frames);
  publishDisplayUpdate(*block, blockNumber);

  QList<QPair<int, double>> latest;
  latest.reserve(static_cast<qsizetype>(m_channels.size()));
  for (const auto& state : m_channels)
    latest.append({state.config.uniqueId, state.latest});

  Q_EMIT latestValuesReady(m_config.sourceId, latest);

  if (exportItem)
    Q_EMIT blockReady(StreamBlockItemPtr(std::move(exportItem)));
}

void IO::StreamProcessor::processChannel(ChannelState& state,
                                         const IO::SampleBlock& block,
                                         quint64 blockNumber,
                                         StreamBlockItem* exportItem)
{
  const int channel  = state.config.channel;
  const int channels = std::max(1, block.channels);
  if (channel < 0 || channel >= channels) [[unlikely]]
    return;

  const qsizetype frames = block.frames;
  m_scratch.resize(static_cast<std::size_t>(frames));

  const float* interleaved = block.samples.data();
  SS_NO_UNROLL
  for (qsizetype i = 0; i < frames; ++i)
    m_scratch[static_cast<std::size_t>(i)] =
      static_cast<double>(interleaved[i * channels + channel]);

  const double t0Ms = std::chrono::duration_cast<std::chrono::duration<double, std::milli>>(
                        block.t0.time_since_epoch())
                        .count();

  const bool hasBlockForm = (state.luaBlockRef >= 0) || state.jsBlockValid;
  if (hasBlockForm) {
    if (!runBlockTransform(state, blockNumber, t0Ms))
      ++m_transformErrors;
  } else if (state.luaRef >= 0 || state.jsValid) {
    runSampleTransform(state);
  }

  state.firstSampleIndex += static_cast<quint64>(frames);
  reduceChannel(state, block);

  if (exportItem) {
    exportItem->uniqueIds.push_back(state.config.uniqueId);
    exportItem->channels.push_back(m_scratch);
  }
}

bool IO::StreamProcessor::runBlockTransform(ChannelState& state, quint64 blockNumber, double t0Ms)
{
  if (state.luaBlockRef >= 0 && m_lua)
    return runLuaBlockTransform(state, blockNumber, t0Ms);

  if (state.jsBlockValid && m_js)
    return runJsBlockTransform(state, blockNumber, t0Ms);

  return false;
}

static void readBackLuaSamples(lua_State* L, qsizetype count, std::vector<double>& scratch)
{
  for (qsizetype i = 0; i < count; ++i) {
    lua_rawgeti(L, -1, static_cast<int>(i + 1));
    if (lua_isnumber(L, -1))
      scratch[static_cast<std::size_t>(i)] = lua_tonumber(L, -1);

    lua_pop(L, 1);
  }
}

bool IO::StreamProcessor::runLuaBlockTransform(ChannelState& state,
                                               quint64 blockNumber,
                                               double t0Ms)
{
  const qsizetype count = static_cast<qsizetype>(m_scratch.size());
  lua_State* L          = m_lua;
  m_luaDeadline.setRemainingTime(kWatchdogMs);

  try {
    lua_rawgeti(L, LUA_REGISTRYINDEX, state.luaBlockRef);
    lua_createtable(L, static_cast<int>(count), 0);
    for (qsizetype i = 0; i < count; ++i) {
      lua_pushnumber(L, m_scratch[static_cast<std::size_t>(i)]);
      lua_rawseti(L, -2, static_cast<int>(i + 1));
    }

    lua_createtable(L, 0, 7);
    lua_pushinteger(L, m_config.sourceId);
    lua_setfield(L, -2, "sourceId");
    lua_pushinteger(L, state.config.uniqueId);
    lua_setfield(L, -2, "uniqueId");
    lua_pushinteger(L, static_cast<lua_Integer>(blockNumber));
    lua_setfield(L, -2, "blockNumber");
    lua_pushnumber(L, t0Ms);
    lua_setfield(L, -2, "timestampMs");
    lua_pushnumber(L, m_config.sampleRate);
    lua_setfield(L, -2, "sampleRate");
    lua_pushinteger(L, static_cast<lua_Integer>(count));
    lua_setfield(L, -2, "count");
    lua_pushinteger(L, static_cast<lua_Integer>(state.firstSampleIndex));
    lua_setfield(L, -2, "firstSampleIndex");

    if (lua_pcall(L, 2, 1, 0) != LUA_OK) [[unlikely]] {
      qWarning() << "[StreamWorker] transform_block failed for dataset" << state.config.uniqueId
                 << ":" << lua_tostring(L, -1);
      lua_pop(L, 1);
      m_luaDeadline = QDeadlineTimer(QDeadlineTimer::Forever);
      return false;
    }

    if (lua_istable(L, -1))
      readBackLuaSamples(L, count, m_scratch);

    lua_pop(L, 1);
    m_luaDeadline = QDeadlineTimer(QDeadlineTimer::Forever);
    return true;
  } catch (const std::exception& e) {
    qWarning() << "[StreamWorker] transform_block exception for dataset" << state.config.uniqueId
               << ":" << e.what();
    lua_settop(L, 0);
    m_luaDeadline = QDeadlineTimer(QDeadlineTimer::Forever);
    return false;
  }
}

bool IO::StreamProcessor::runJsBlockTransform(ChannelState& state, quint64 blockNumber, double t0Ms)
{
  const qsizetype count = static_cast<qsizetype>(m_scratch.size());
  QJSValue samples      = m_js->newArray(static_cast<quint32>(count));
  for (qsizetype i = 0; i < count; ++i)
    samples.setProperty(static_cast<quint32>(i), m_scratch[static_cast<std::size_t>(i)]);

  QJSValue info = m_js->newObject();
  info.setProperty(QStringLiteral("sourceId"), m_config.sourceId);
  info.setProperty(QStringLiteral("uniqueId"), state.config.uniqueId);
  info.setProperty(QStringLiteral("blockNumber"), static_cast<double>(blockNumber));
  info.setProperty(QStringLiteral("timestampMs"), t0Ms);
  info.setProperty(QStringLiteral("sampleRate"), m_config.sampleRate);
  info.setProperty(QStringLiteral("count"), static_cast<double>(count));
  info.setProperty(QStringLiteral("firstSampleIndex"), static_cast<double>(state.firstSampleIndex));

  const QJSValue result = state.jsBlockFn.call({samples, info});
  if (result.isError()) [[unlikely]] {
    qWarning() << "[StreamWorker] JS transform_block failed for dataset" << state.config.uniqueId
               << ":" << result.toString();
    return false;
  }

  if (result.isArray()) {
    const quint32 n =
      std::min(static_cast<quint32>(count), result.property(QStringLiteral("length")).toUInt());
    for (quint32 i = 0; i < n; ++i)
      m_scratch[i] = result.property(i).toNumber();
  }

  return true;
}

void IO::StreamProcessor::runSampleTransform(ChannelState& state)
{
  const std::size_t count = m_scratch.size();

  if (state.luaRef >= 0 && m_lua) {
    lua_State* L = m_lua;
    m_luaDeadline.setRemainingTime(kWatchdogMs);
    try {
      SS_NO_UNROLL
      for (std::size_t i = 0; i < count; ++i) {
        lua_rawgeti(L, LUA_REGISTRYINDEX, state.luaRef);
        lua_pushnumber(L, m_scratch[i]);
        if (lua_pcall(L, 1, 1, 0) != LUA_OK) [[unlikely]] {
          ++m_transformErrors;
          lua_pop(L, 1);
          break;
        }

        if (lua_isnumber(L, -1))
          m_scratch[i] = lua_tonumber(L, -1);

        lua_pop(L, 1);
      }
    } catch (const std::exception&) {
      ++m_transformErrors;
      lua_settop(L, 0);
    }

    m_luaDeadline = QDeadlineTimer(QDeadlineTimer::Forever);
    return;
  }

  if (state.jsValid) {
    SS_NO_UNROLL
    for (std::size_t i = 0; i < count; ++i) {
      const QJSValue result = state.jsFn.call({QJSValue(m_scratch[i])});
      if (result.isError()) [[unlikely]] {
        ++m_transformErrors;
        break;
      }

      if (result.isNumber())
        m_scratch[i] = result.toNumber();
    }
  }
}

void IO::StreamProcessor::reduceChannel(ChannelState& state, const IO::SampleBlock& block)
{
  const std::size_t count = m_scratch.size();
  if (count == 0) [[unlikely]]
    return;

  const double dtSec     = std::chrono::duration<double>(block.dt).count();
  const int px           = std::max(1, m_pixelWidth->load(std::memory_order_relaxed));
  const double win       = std::max(1.0e-3, m_windowSec->load(std::memory_order_relaxed));
  const double bucketSec = win / static_cast<double>(px > 0 ? px : kDefaultBuckets);

  double bucketEnd = bucketSec;
  double vMin      = m_scratch[0];
  double vMax      = m_scratch[0];
  double tMin      = 0.0;
  double tMax      = 0.0;

  SS_NO_UNROLL
  for (std::size_t i = 0; i < count; ++i) {
    const double t = static_cast<double>(i) * dtSec;
    const double v = m_scratch[i];
    if (t >= bucketEnd) {
      if (tMin <= tMax) {
        state.envelope.emplace_back(tMin, vMin);
        state.envelope.emplace_back(tMax, vMax);
      } else {
        state.envelope.emplace_back(tMax, vMax);
        state.envelope.emplace_back(tMin, vMin);
      }

      bucketEnd = (std::floor(t / bucketSec) + 1.0) * bucketSec;
      vMin      = v;
      vMax      = v;
      tMin      = t;
      tMax      = t;
      continue;
    }

    if (v < vMin) {
      vMin = v;
      tMin = t;
    }

    if (v > vMax) {
      vMax = v;
      tMax = t;
    }
  }

  if (tMin <= tMax) {
    state.envelope.emplace_back(tMin, vMin);
    state.envelope.emplace_back(tMax, vMax);
  } else {
    state.envelope.emplace_back(tMax, vMax);
    state.envelope.emplace_back(tMin, vMin);
  }

  state.latest = m_scratch[count - 1];

  if (!state.fftRing.empty()) {
    const std::size_t cap = state.fftRing.size();
    SS_NO_UNROLL
    for (std::size_t i = 0; i < count; ++i) {
      state.fftRing[state.fftHead] = m_scratch[i];
      state.fftHead                = (state.fftHead + 1) % cap;
      if (state.fftFill < cap)
        ++state.fftFill;
    }
  }
}

void IO::StreamProcessor::publishDisplayUpdate(const IO::SampleBlock& block, quint64 blockNumber)
{
  auto update         = std::make_shared<StreamDisplayUpdate>();
  update->sourceId    = m_config.sourceId;
  update->blockNumber = blockNumber;
  update->t0          = block.t0;
  update->dt          = block.dt;
  update->frames      = block.frames;
  update->channels.reserve(m_channels.size());

  for (auto& state : m_channels) {
    StreamDisplayUpdate::ChannelUpdate channel;
    channel.uniqueId = state.config.uniqueId;
    channel.latest   = state.latest;
    channel.envelope = std::move(state.envelope);
    state.envelope.clear();
    state.envelope.reserve(64);

    if (!state.fftRing.empty() && state.fftFill == state.fftRing.size()) {
      channel.hasFft = true;
      channel.fftWindow.resize(state.fftRing.size());
      const std::size_t cap = state.fftRing.size();
      for (std::size_t i = 0; i < cap; ++i)
        channel.fftWindow[i] = state.fftRing[(state.fftHead + i) % cap];
    }

    update->channels.push_back(std::move(channel));
  }

  if (!m_displayOut->try_enqueue(StreamDisplayUpdatePtr(std::move(update)))) [[unlikely]]
    ++m_displayDrops;
}

IO::StreamWorker::StreamWorker(HAL_Driver* driver, const StreamConfig& config, QObject* parent)
  : QObject(parent)
  , m_config(config)
  , m_abandoned(false)
  , m_processor(nullptr)
  , m_pixelWidth(kDefaultPixelWidth)
  , m_windowSec(10.0)
  , m_exportActive(false)
  , m_displayRing(kDisplayRingSlots)
{
  SS_ASSERT(driver != nullptr, return);
  SS_ASSERT_LOG(!config.datasets.empty());

  m_thread.setObjectName(QStringLiteral("StreamWorker-%1").arg(config.sourceId));

  m_processor =
    new StreamProcessor(config, &m_displayRing, &m_pixelWidth, &m_windowSec, &m_exportActive);
  m_processor->moveToThread(&m_thread);
  m_thread.start();

  m_feed = connect(driver,
                   &IO::HAL_Driver::sampleBlockReceived,
                   m_processor,
                   &IO::StreamProcessor::onSampleBlock,
                   Qt::QueuedConnection);

  QMetaObject::invokeMethod(
    m_processor, &IO::StreamProcessor::compileEngines, Qt::QueuedConnection);
}

IO::StreamWorker::~StreamWorker()
{
  stop();

  if (!m_abandoned)
    delete m_processor;

  m_processor = nullptr;
}

void IO::StreamWorker::stop()
{
  if (!m_thread.isRunning())
    return;

  if (m_feed)
    disconnect(m_feed);

  if (m_processor)
    QMetaObject::invokeMethod(
      m_processor, &IO::StreamProcessor::teardownEngines, Qt::QueuedConnection);

  m_thread.quit();
  if (!m_thread.wait(kJoinTimeoutMs)) [[unlikely]] {
    m_abandoned = true;
    qWarning() << "[StreamWorker] source" << m_config.sourceId << "worker did not stop within"
               << kJoinTimeoutMs << "ms (hung script?) -- abandoning it (R21)";
  }
}

void MDF4::StreamExportWorker::closeResources()
{
  for (auto& [sourceId, state] : m_files) {
    if (!state.writer)
      continue;

    try {
      const auto now = std::chrono::system_clock::now();
      const auto stopNs =
        std::chrono::duration_cast<std::chrono::nanoseconds>(now.time_since_epoch()).count();
      state.writer->StopMeasurement(static_cast<uint64_t>(stopNs));
      state.writer->FinalizeMeasurement();
    } catch (const std::exception& e) {
      qWarning() << "[MDF4] stream close failed for source" << sourceId << ":" << e.what();
    }
  }

  m_files.clear();
}

MDF4::StreamExportWorker::StreamFile* MDF4::StreamExportWorker::fileFor(
  const IO::StreamBlockItem& block)
{
  auto it = m_files.find(block.sourceId);
  if (it != m_files.end())
    return &it->second;

  const auto& token = Licensing::CommercialToken::current();
  if (!token.isValid() || !SS_LICENSE_GUARD())
    return nullptr;

  const auto dateTime = QDateTime::currentDateTime();
  const auto fileName = dateTime.toString(QStringLiteral("yyyy-MM-dd_HH-mm-ss"))
                      + QStringLiteral("_stream_source%1.mf4").arg(block.sourceId);

  static auto& workspaceManager = Misc::WorkspaceManager::instance();
  QDir dir(workspaceManager.path(QStringLiteral("MDF4")));

  StreamFile state;
  state.writer = mdf::MdfFactory::CreateMdfWriter(mdf::MdfWriterType::Mdf4Basic);
  if (!state.writer)
    return nullptr;

  try {
    state.writer->Init(dir.filePath(fileName).toStdString());

    auto* header = state.writer->Header();
    if (!header)
      return nullptr;

    header->Author("Serial Studio");
    header->Description("Typed stream capture - https://serial-studio.com/");
    header->Subject(QStringLiteral("Stream source %1").arg(block.sourceId).toStdString());
    header->Project("Telemetry Data");
    header->StartTime(dateTime.toMSecsSinceEpoch() * 1000000);

    auto* dataGroup = state.writer->CreateDataGroup();
    if (!dataGroup)
      return nullptr;

    dataGroup->Description("Serial Studio Stream Data");
    auto* channelGroup = dataGroup->CreateChannelGroup();
    if (!channelGroup)
      return nullptr;

    channelGroup->Name(QStringLiteral("Stream source %1").arg(block.sourceId).toStdString());
    state.channelGroup = channelGroup;
    state.timeChannel  = createTimeChannel(channelGroup);

    for (const int uniqueId : block.uniqueIds) {
      auto* channel = channelGroup->CreateChannel();
      if (!channel)
        return nullptr;

      channel->Name(QStringLiteral("ds%1").arg(uniqueId).toStdString());
      channel->Type(mdf::ChannelType::FixedLength);
      channel->DataType(mdf::ChannelDataType::FloatLe);
      channel->DataBytes(8);
      state.channels.push_back(channel);
    }

    state.writer->InitMeasurement();
    state.writer->StartMeasurement(dateTime.toMSecsSinceEpoch() * 1000000);
  } catch (const std::exception& e) {
    qWarning() << "[MDF4] stream file creation failed:" << e.what();
    return nullptr;
  }

  state.steadyBaseline = block.t0;
  state.systemBaseline = std::chrono::system_clock::now();

  auto [inserted, ok] = m_files.emplace(block.sourceId, std::move(state));
  return ok ? &inserted->second : nullptr;
}

void MDF4::StreamExportWorker::writeBlock(StreamFile& state, const IO::StreamBlockItem& block)
{
  const auto systemEpochNs =
    std::chrono::duration_cast<std::chrono::nanoseconds>(state.systemBaseline.time_since_epoch())
      .count();
  const qint64 baseOffsetNs =
    std::chrono::duration_cast<std::chrono::nanoseconds>(block.t0 - state.steadyBaseline).count();
  const qint64 dtNs = block.dt.count();

  const std::size_t channelCount = std::min(state.channels.size(), block.channels.size());

  constexpr double kNsToSec = 1.0e-9;
  for (qsizetype i = 0; i < block.frames; ++i) {
    const qint64 timestampNs = systemEpochNs + baseOffsetNs + static_cast<qint64>(i) * dtNs;
    const double timestampS  = static_cast<double>(timestampNs) * kNsToSec;

    if (state.timeChannel)
      state.timeChannel->SetChannelValue(timestampS);

    for (std::size_t c = 0; c < channelCount; ++c) {
      const auto& samples = block.channels[c];
      const double value =
        (static_cast<std::size_t>(i) < samples.size()) ? samples[static_cast<std::size_t>(i)] : 0.0;
      state.channels[c]->SetChannelValue(value);
    }

    state.writer->SaveSample(*state.channelGroup, static_cast<uint64_t>(timestampNs));
  }
}

void MDF4::StreamExportWorker::processItems(const std::vector<IO::StreamBlockItemPtr>& items)
{
  for (const auto& block : items) {
    if (!block || block->frames <= 0)
      continue;

    auto* state = fileFor(*block);
    if (!state)
      continue;

    try {
      writeBlock(*state, *block);
    } catch (const std::exception& e) {
      qWarning() << "[MDF4] stream write failed:" << e.what();
    }
  }
}

MDF4::StreamExport::StreamExport()
  : DataModel::FrameConsumer<IO::StreamBlockItemPtr>(
      {.queueCapacity = 4096, .flushThreshold = 256, .timerIntervalMs = 500})
{
  initializeWorker();
  setConsumerEnabled(false);
}

void MDF4::StreamExport::ingestBlock(const IO::StreamBlockItemPtr& block)
{
  if (block)
    enqueueData(block);
}

void MDF4::StreamExport::closeFiles()
{
  if (m_worker)
    QMetaObject::invokeMethod(m_worker, "close", Qt::QueuedConnection);
}

void SessionContext::adoptPipelineHost(std::unique_ptr<IO::PipelineHost> module)
{
  SS_ASSERT(!m_pipelineHost, return);
  SS_ASSERT(module != nullptr, return);
  m_pipelineHost = std::move(module);
}

IO::PipelineHost& SessionContext::pipelineHost() const
{
  SS_ASSERT(m_pipelineHost != nullptr,
            qFatal("SessionContext: %s accessed before adoption", "pipelineHost"));
  return *m_pipelineHost;
}

void UI::Dashboard::onDisplayTick()
{
  QElapsedTimer clock;
  clock.start();

  SS_ASSERT(m_drainBudgetNs > 0, return);

  drainDashboardRing(clock, m_drainBudgetNs);
  drainStreamWorkers(clock, m_drainBudgetNs);

  static auto& frameBuilder = DataModel::FrameBuilder::instance();
  frameBuilder.drainTableSnapshot();
  frameBuilder.drainLatestFrameSnapshot();

  if (m_updateRequired) {
    m_updateRequired = false;
    Q_EMIT updated();
  }
}

void UI::Dashboard::drainDashboardRing(const QElapsedTimer& clock, const qint64 budgetNs)
{
  static auto& pipeline = IO::PipelineHost::instance();

  const int max_drain = pipeline.dashboardRingCapacity();
  SS_ASSERT(max_drain > 0, return);
  SS_ASSERT(budgetNs > 0, return);

  quint64 discarded = 0;
  bool over_budget  = false;
  DataModel::TimestampedFramePtr frame;
  DataModel::TimestampedFramePtr newest;

  for (int drained = 0; drained < max_drain && pipeline.dequeueDashboardFrame(frame); ++drained) {
    if (over_budget) [[unlikely]] {
      newest = frame;
      ++discarded;
      continue;
    }

    hotpathRxFrame(frame);
    if ((drained & kBudgetCheckMask) == kBudgetCheckMask)
      over_budget = clock.nsecsElapsed() >= budgetNs;
  }

  if (newest) [[unlikely]] {
    hotpathRxFrame(newest);
    --discarded;
    newest.reset();
  }

  frame.reset();
  pipeline.noteDisplayDrops(discarded);
}

void UI::Dashboard::drainStreamWorkers(const QElapsedTimer& clock, const qint64 budgetNs)
{
  static auto& ioManager = IO::ConnectionManager::instance();
  const auto& workers    = ioManager.streamWorkers();
  if (workers.empty()) [[likely]]
    return;

  for (const auto& worker : workers) {
    if (!worker)
      continue;

    worker->setPixelWidth(qMax(1, m_points / 2));
    worker->setWindowSec(m_plotTimeRange);
    drainStreamWorker(*worker, clock, budgetNs);
  }
}

void UI::Dashboard::drainStreamWorker(IO::StreamWorker& worker,
                                      const QElapsedTimer& clock,
                                      const qint64 budgetNs)
{
  const int max_drain = worker.displayRingCapacity();
  SS_ASSERT(max_drain > 0, return);
  SS_ASSERT(budgetNs > 0, return);

  IO::StreamDisplayUpdatePtr update;

  for (int drained = 0; drained < max_drain && worker.dequeueDisplayUpdate(update); ++drained) {
    if (update)
      applyStreamUpdate(*update);

    if ((drained & kBudgetCheckMask) == kBudgetCheckMask && clock.nsecsElapsed() >= budgetNs)
      break;
  }

  update.reset();
}

void UI::Dashboard::applyStreamUpdate(const IO::StreamDisplayUpdate& update)
{
  if (!m_layoutValid || !m_streamAvailable) [[unlikely]]
    return;

  const double baseSec = advancePlotClock(update.sourceId, update.t0);

  for (const auto& channel : update.channels)
    applyStreamChannel(channel, baseSec);

  for (auto it = m_multiplotSweep.begin(); it != m_multiplotSweep.end(); ++it)
    if (it.value().enabled && m_activeMultiplots.value(it.key(), false))
      feedMultiplotStreamSweep(it.key(), update, baseSec);

  m_updateRequired = true;
}

void UI::Dashboard::applyStreamChannel(const IO::StreamDisplayUpdate::ChannelUpdate& channel,
                                       double baseSec)
{
  const auto refs = m_datasetReferences.constFind(channel.uniqueId);
  if (refs != m_datasetReferences.cend()) {
    const QString text = QString::number(channel.latest, 'g', 10);
    for (auto* dataset : refs.value()) {
      dataset->isNumeric    = true;
      dataset->numericValue = channel.latest;
      dataset->value        = text;
    }
  }

  const auto ext_it = m_datasetExtremes.find(channel.uniqueId);
  if (ext_it != m_datasetExtremes.end()) [[unlikely]] {
    auto& slot = ext_it.value();
    if (std::isfinite(channel.latest)) {
      slot.min   = slot.valid ? qMin(slot.min, channel.latest) : channel.latest;
      slot.max   = slot.valid ? qMax(slot.max, channel.latest) : channel.latest;
      slot.valid = true;
    }

    for (const auto& pair : channel.envelope) {
      if (!std::isfinite(pair.second))
        continue;

      slot.min   = slot.valid ? qMin(slot.min, pair.second) : pair.second;
      slot.max   = slot.valid ? qMax(slot.max, pair.second) : pair.second;
      slot.valid = true;
    }
  }

  const StreamTargets& targets = streamTargetsFor(channel.uniqueId);

  for (const int plotIndex : targets.plotIndexes) {
    if (!m_activePlots.value(plotIndex, false))
      continue;

    auto ringIt = m_plotTimeRings.find(plotIndex);
    if (ringIt == m_plotTimeRings.end()) [[unlikely]]
      continue;

    for (const auto& pair : channel.envelope)
      ringIt.value().appendDecimated(baseSec + pair.first, pair.second);

    feedPlotStreamSweep(plotIndex, channel, baseSec);
  }

  for (const auto& [groupIndex, curveIndex] : targets.multiplotCurves) {
    if (!m_activeMultiplots.value(groupIndex, false))
      continue;

    auto ringsIt = m_multiplotTimeRings.find(groupIndex);
    if (ringsIt == m_multiplotTimeRings.end()) [[unlikely]]
      continue;

    auto& rings = ringsIt.value();
    if (curveIndex < 0 || static_cast<std::size_t>(curveIndex) >= rings.size()) [[unlikely]]
      continue;

    for (const auto& pair : channel.envelope)
      rings[curveIndex].appendDecimated(baseSec + pair.first, pair.second);
  }

  if (!channel.hasFft)
    return;

  for (const int fftIndex : targets.fftIndexes) {
    if (!m_activeFFTPlots.value(fftIndex, false))
      continue;

    if (fftIndex < 0 || fftIndex >= m_fftValues.size()) [[unlikely]]
      continue;

    auto& series = m_fftValues[fftIndex];
    series.clear();
    for (const double sample : channel.fftWindow)
      series.push(sample);
  }

#ifdef BUILD_COMMERCIAL
  for (const int fallIndex : targets.waterfallIndexes) {
    if (!m_activeWaterfalls.value(fallIndex, false))
      continue;

    if (fallIndex < 0 || fallIndex >= m_waterfallValues.size()) [[unlikely]]
      continue;

    auto& series = m_waterfallValues[fallIndex];
    series.clear();
    for (const double sample : channel.fftWindow)
      series.push(sample);
  }
#endif
}

void UI::Dashboard::feedPlotStreamSweep(int plotIndex,
                                        const IO::StreamDisplayUpdate::ChannelUpdate& channel,
                                        double baseSec)
{
  auto sweepIt = m_plotSweep.find(plotIndex);
  if (sweepIt == m_plotSweep.end())
    return;

  DSP::SweepEngine& sweep = sweepIt.value();
  if (!sweep.enabled || sweep.back.empty())
    return;

  for (const auto& pair : channel.envelope) {
    const double st = sweep.advance(baseSec + pair.first, pair.second);
    if (st >= 0)
      sweep.back[0].appendDecimated(st, pair.second);
  }
}

void UI::Dashboard::feedMultiplotStreamSweep(int groupIndex,
                                             const IO::StreamDisplayUpdate& update,
                                             double baseSec)
{
  auto sweepIt = m_multiplotSweep.find(groupIndex);
  if (sweepIt == m_multiplotSweep.end())
    return;

  DSP::SweepEngine& sweep = sweepIt.value();
  if (!sweep.enabled || sweep.back.empty())
    return;

  m_streamSweepCurves.assign(sweep.back.size(), nullptr);
  for (const auto& channel : update.channels) {
    for (const auto& [group, curve] : streamTargetsFor(channel.uniqueId).multiplotCurves) {
      if (group != groupIndex || curve < 0)
        continue;

      if (static_cast<std::size_t>(curve) < m_streamSweepCurves.size())
        m_streamSweepCurves[static_cast<std::size_t>(curve)] = &channel;
    }
  }

  const int last      = static_cast<int>(m_streamSweepCurves.size()) - 1;
  const int trigCurve = qBound(0, sweep.triggerCurve, last);
  const auto* trigger = m_streamSweepCurves[static_cast<std::size_t>(trigCurve)];
  if (!trigger)
    return;

  std::size_t count = trigger->envelope.size();
  for (const auto* curve : m_streamSweepCurves)
    if (curve)
      count = std::min(count, curve->envelope.size());

  for (std::size_t i = 0; i < count; ++i) {
    const double st =
      sweep.advance(baseSec + trigger->envelope[i].first, trigger->envelope[i].second);
    if (st < 0)
      continue;

    for (std::size_t j = 0; j < m_streamSweepCurves.size(); ++j)
      if (m_streamSweepCurves[j])
        sweep.back[j].appendDecimated(st, m_streamSweepCurves[j]->envelope[i].second);
  }
}

const UI::Dashboard::StreamTargets& UI::Dashboard::streamTargetsFor(int uniqueId)
{
  auto it = m_streamTargets.find(uniqueId);
  if (it != m_streamTargets.end()) [[likely]]
    return it.value();

  StreamTargets targets;

  const auto plots = m_widgetDatasets.constFind(SerialStudio::DashboardPlot);
  if (plots != m_widgetDatasets.cend())
    for (int i = 0; i < plots.value().size(); ++i)
      if (plots.value()[i].uniqueId == uniqueId)
        targets.plotIndexes.push_back(i);

  const auto ffts = m_widgetDatasets.constFind(SerialStudio::DashboardFFT);
  if (ffts != m_widgetDatasets.cend())
    for (int i = 0; i < ffts.value().size(); ++i)
      if (ffts.value()[i].uniqueId == uniqueId)
        targets.fftIndexes.push_back(i);

#ifdef BUILD_COMMERCIAL
  const auto falls = m_widgetDatasets.constFind(SerialStudio::DashboardWaterfall);
  if (falls != m_widgetDatasets.cend())
    for (int i = 0; i < falls.value().size(); ++i)
      if (falls.value()[i].uniqueId == uniqueId)
        targets.waterfallIndexes.push_back(i);
#endif

  const auto groups    = m_widgetGroups.constFind(SerialStudio::DashboardMultiPlot);
  const int groupCount = (groups != m_widgetGroups.cend()) ? groups.value().size() : 0;
  for (int g = 0; g < groupCount; ++g) {
    const auto& datasets = groups.value()[g].datasets;
    for (std::size_t c = 0; c < datasets.size(); ++c)
      if (datasets[c].uniqueId == uniqueId)
        targets.multiplotCurves.emplace_back(g, static_cast<int>(c));
  }

  return m_streamTargets.insert(uniqueId, std::move(targets)).value();
}

void UI::Dashboard::setManualLayoutSpacing(const int spacing)
{
  const int clamped = qMax(-1, spacing);
  if (m_manualLayoutSpacing == clamped)
    return;

  m_manualLayoutSpacing = clamped;
  if (m_persistSettings)
    m_settings.setValue("Dashboard/ManualLayoutSpacing", m_manualLayoutSpacing);

  Q_EMIT manualLayoutSpacingChanged();
}

double UI::Dashboard::advancePlotClock(int sourceId,
                                       const std::chrono::steady_clock::time_point& ts)
{
  // code-verify off
  // Scoped tight: reconfigureDashboard move-assigns m_plotClocks, so this reference must not
  // survive past this function.
  PlotClock& clk = m_plotClocks[sourceId];
  // code-verify on

  if (!clk.originSet) [[unlikely]] {
    clk.origin          = ts;
    clk.originSet       = true;
    clk.groupCount      = 0;
    clk.groupStartSec   = 0;
    clk.displayTimeSec  = 0;
    clk.samplePeriodSec = 0;
  }
  clk.relativeFrameTimeSec = std::chrono::duration<double>(ts - clk.origin).count();

  ++clk.groupCount;
  if (clk.relativeFrameTimeSec > clk.groupStartSec) {
    const int n      = (clk.groupCount > 1) ? (clk.groupCount - 1) : 1;
    const double gap = clk.relativeFrameTimeSec - clk.groupStartSec;

    // code-verify off
    // Divide only for rare multi-sample coarse-clock groups; fine-timestamp sources hit n == 1.
    const double period = (n > 1) ? (gap / n) : gap;
    // code-verify on

    clk.samplePeriodSec =
      (clk.samplePeriodSec > 0) ? (0.8 * clk.samplePeriodSec + 0.2 * period) : period;
    clk.groupStartSec = clk.relativeFrameTimeSec;
    clk.groupCount    = 1;
  }
  const double expected = clk.displayTimeSec + clk.samplePeriodSec;

  double displayNext = qMax(expected, clk.relativeFrameTimeSec);

  const double forwardError = clk.relativeFrameTimeSec - expected;
  if (clk.samplePeriodSec > 0 && clk.samplePeriodSec < kSmoothMaxPeriodSec && forwardError > 0
      && forwardError < kSmoothMaxForwardSec)
    displayNext = expected;

  clk.displayTimeSec   = displayNext;
  m_plotDisplayTimeSec = displayNext;
  return displayNext;
}

void UI::Dashboard::foldExtremes(int sourceId)
{
  const auto it = m_extremePushes.constFind(sourceId);
  if (it == m_extremePushes.cend()) [[likely]]
    return;

  for (const auto& push : it.value()) {
    if (!*push.numeric || !std::isfinite(*push.value))
      continue;

    const double value = *push.value;
    if (!push.slot->valid) {
      push.slot->min   = value;
      push.slot->max   = value;
      push.slot->valid = true;
      continue;
    }

    push.slot->min = qMin(push.slot->min, value);
    push.slot->max = qMax(push.slot->max, value);
  }
}

void UI::Dashboard::buildExtremePushes()
{
  m_extremePushes.clear();

  for (auto it = m_sourceRawFrames.cbegin(); it != m_sourceRawFrames.cend(); ++it)
    for (const auto& group : it.value().groups)
      for (const auto& dataset : group.datasets)
        appendExtremePush(it.key(), dataset);
}

void UI::Dashboard::appendExtremePush(int sourceId, const DataModel::Dataset& dataset)
{
  if (!dataset.extremeHold)
    return;

  const auto ds_it = m_datasets.constFind(dataset.uniqueId);
  if (ds_it == m_datasets.cend())
    return;

  ExtremePush push;
  push.slot    = &m_datasetExtremes[dataset.uniqueId];
  push.value   = &ds_it.value().numericValue;
  push.numeric = &ds_it.value().isNumeric;
  m_extremePushes[sourceId].push_back(push);

static bool plotClassDatasetWidget(const SerialStudio::DashboardWidget w)
{
  if (w == SerialStudio::DashboardPlot || w == SerialStudio::DashboardFFT)
    return true;

#ifdef BUILD_COMMERCIAL
  if (w == SerialStudio::DashboardWaterfall)
    return true;
#endif

  return false;
}

nodiscard]] static int autoLayoutColumnCount(const int n, const UI::Layouts::LayoutEnv& env)
{
  static constexpr int kLandscapeCols[] = {1, 1, 2, 2, 2, 3, 3};
  static constexpr int kPortraitCols[]  = {1, 1, 1, 1, 2, 2, 2};
  if (n <= 6)
    return env.isLandscape ? kLandscapeCols[n] : kPortraitCols[n];

  const double safeW = qMax(1, env.availW);
  const double safeH = qMax(1, env.availH);

  int cols;
  if (env.isLandscape) {
    cols = qCeil(qSqrt(static_cast<double>(n) * safeW / safeH));
  } else {
    const int rows = qBound(1, qCeil(qSqrt(static_cast<double>(n) * safeH / safeW)), n);
    cols           = qCeil(static_cast<double>(n) / rows);
  }

  return qBound(1, cols, n);
}

nodiscard]] static QVector<QRect> tileExactGrid(const int n,
                                                  const UI::Layouts::LayoutEnv& env,
                                                  const int cols)
{
  const int rows             = n / cols;
  const int spacingForSizing = qMax(env.spacing, 0);
  const int totalCellsW      = qMax(1, env.availW - (cols - 1) * spacingForSizing);
  const int totalCellsH      = qMax(1, env.availH - (rows - 1) * spacingForSizing);
  const int baseCellW        = totalCellsW / cols;
  const int baseCellH        = totalCellsH / rows;
  const int extraW           = totalCellsW % cols;
  const int extraH           = totalCellsH % rows;

  QVector<int> colWidths(cols), colXs(cols);
  QVector<int> rowHeights(rows), rowYs(rows);

  int runningX = env.margin;
  for (int c = 0; c < cols; ++c) {
    colWidths[c]  = baseCellW + (c < extraW ? 1 : 0);
    colXs[c]      = runningX;
    runningX     += colWidths[c] + env.spacing;
  }

  int runningY = env.margin;
  for (int r = 0; r < rows; ++r) {
    rowHeights[r]  = baseCellH + (r < extraH ? 1 : 0);
    rowYs[r]       = runningY;
    runningY      += rowHeights[r] + env.spacing;
  }

  QVector<QRect> out;
  out.reserve(n);
  for (int i = 0; i < n; ++i)
    out.append(QRect(colXs[i % cols], rowYs[i / cols], colWidths[i % cols], rowHeights[i / cols]));

  return out;
}

nodiscard]] static QVector<QRect> tileUnevenColumns(const int n,
                                                      const UI::Layouts::LayoutEnv& env,
                                                      const int cols)
{
  const int spacingForSizing = qMax(env.spacing, 0);
  const int totalCellsW      = qMax(1, env.availW - (cols - 1) * spacingForSizing);
  const int baseCellW        = totalCellsW / cols;
  const int extraW           = totalCellsW % cols;
  const int baseCount        = n / cols;
  const int extraCount       = n % cols;

  QVector<QRect> out;
  out.reserve(n);

  int runningX = env.margin;
  for (int c = 0; c < cols; ++c) {
    const int colW        = baseCellW + (c < extraW ? 1 : 0);
    const int count       = baseCount + (c >= cols - extraCount ? 1 : 0);
    const int totalCellsH = qMax(1, env.availH - (count - 1) * spacingForSizing);
    const int baseCellH   = totalCellsH / count;
    const int extraH      = totalCellsH % count;

    int runningY = env.margin;
    for (int r = 0; r < count; ++r) {
      const int cellH = baseCellH + (r < extraH ? 1 : 0);
      out.append(QRect(runningX, runningY, colW, cellH));
      runningY += cellH + env.spacing;
    }

    runningX += colW + env.spacing;
  }

  return out;
}

nodiscard]] static QVector<QRect> tileGrid(const int n, const UI::Layouts::LayoutEnv& env)
{
  const int cols = autoLayoutColumnCount(n, env);
  if (n % cols == 0)
    return tileExactGrid(n, env, cols);

  return tileUnevenColumns(n, env, cols);
}

ector<QRect> UI::Layouts::tile(const int count, const Pattern pattern, const LayoutEnv& env)
{
  if (count <= 0 || env.availW <= 0 || env.availH <= 0)
    return {};

  Q_UNUSED(pattern);
  return tileGrid(count, env);
}

tring UI::Layouts::patternId(const Pattern pattern)
{
  switch (pattern) {
    case Pattern::MasterStack:
      return QStringLiteral("master-stack");
    case Pattern::MasterGrid:
      return QStringLiteral("master-grid");
    case Pattern::Row:
      return QStringLiteral("row");
    case Pattern::Column:
      return QStringLiteral("column");
    case Pattern::Spiral:
      return QStringLiteral("spiral");
    case Pattern::Grid:
      return {};
  }

  return {};
}

::Layouts::Pattern UI::Layouts::patternFromId(const QString& id)
{
  const auto key = id.trimmed().toLower();
  if (key == QLatin1String("master-stack"))
    return Pattern::MasterStack;

  if (key == QLatin1String("master-grid"))
    return Pattern::MasterGrid;

  if (key == QLatin1String("row"))
    return Pattern::Row;

  if (key == QLatin1String("column"))
    return Pattern::Column;

  if (key == QLatin1String("spiral"))
    return Pattern::Spiral;

  return Pattern::Grid;
}

ol UI::Layouts::patternHasPrimary(const Pattern pattern)
{
  return pattern == Pattern::MasterStack || pattern == Pattern::MasterGrid
      || pattern == Pattern::Spiral;
}

int UI::Snap::snapToFraction(const int value, const int extent, const int tolerance)
{
  if (extent <= 0)
    return value;

  int best     = value;
  int bestDist = tolerance + 1;
  for (const int den : kFractionDenominators) {
    if (extent / den < kMinFractionSpacing)
      continue;

    for (int num = 0; num <= den; ++num) {
      const int stop = extent * num / den;
      const int dist = qAbs(stop - value);
      if (dist < bestDist) {
        bestDist = dist;
        best     = stop;
      }
    }
  }

  return bestDist <= tolerance ? best : value;
}

QString UI::Snap::fractionLabel(const int size, const int extent)
{
  if (size <= 0 || extent <= 0)
    return {};

  for (const int den : kFractionDenominators) {
    if (extent / den < kMinFractionSpacing)
      continue;

    for (int num = 1; num <= den; ++num) {
      if (qAbs(size - extent * num / den) > 1)
        continue;

      const int divisor = std::gcd(num, den);
      return QStringLiteral("%1/%2").arg(QString::number(num / divisor),
                                         QString::number(den / divisor));
    }
  }

  return {};
}

dgets::BarPanel::BarPanel(const int index, QQuickItem* parent)
  : QQuickItem(parent), m_index(index), m_dashboard(UI::Dashboard::instance())
{
  if (VALIDATE_WIDGET(SerialStudio::DashboardBarPanel, m_index)) {
    buildRows();

    connect(&m_dashboard, &UI::Dashboard::updated, this, &BarPanel::updateData);
  }
}

nodiscard]] static int rowDecimals(const DataModel::Dataset& dataset, double span)
{
  if (dataset.decimalPoints >= 0)
    return qMin(dataset.decimalPoints, 6);

  if (span >= 100.0)
    return 0;

  return span >= 10.0 ? 1 : 2;
}

id Widgets::BarPanel::buildRows()
{
  const auto& group = GET_GROUP(SerialStudio::DashboardBarPanel, m_index);
  const auto n      = static_cast<int>(group.datasets.size());

  m_styleMode = group.barPanelStyle;
  m_rows.resize(group.datasets.size());
  m_titles.resize(n);
  m_units.resize(n);
  m_valueTexts.resize(n);
  m_ranged.resize(n);
  m_numeric.resize(n);
  m_extremesOk.resize(n);
  m_severities.resize(n);
  m_fracs.resize(n);
  m_minSeenFracs.resize(n);
  m_maxSeenFracs.resize(n);
  m_bandsAsVariant.clear();
  m_bandsAsVariant.reserve(n);

  for (size_t i = 0; i < group.datasets.size(); ++i) {
    const auto& dataset = group.datasets[i];
    const auto idx      = static_cast<int>(i);

    auto& row       = m_rows[i];
    row.hint        = -1;
    row.uniqueId    = dataset.uniqueId;
    row.extremeHold = dataset.extremeHold;
    row.min         = qMin(dataset.wgtMin, dataset.wgtMax);
    row.max         = qMax(dataset.wgtMin, dataset.wgtMax);
    row.ranged      = !DSP::isZero(row.max - row.min);
    row.decimals    = rowDecimals(dataset, row.max - row.min);

    m_titles[idx]       = dataset.title;
    m_units[idx]        = dataset.units;
    m_valueTexts[idx]   = QStringLiteral("--");
    m_ranged[idx]       = row.ranged;
    m_numeric[idx]      = false;
    m_extremesOk[idx]   = false;
    m_severities[idx]   = -1;
    m_fracs[idx]        = 0.0;
    m_minSeenFracs[idx] = 0.0;
    m_maxSeenFracs[idx] = 0.0;

    const double span = row.ranged ? (row.max - row.min) : 1.0;
    QVariantList rowBands;
    row.bands.reserve(dataset.alarmBands.size());
    for (const auto& src : dataset.alarmBands) {
      const double lo = qBound(row.min, qMin(src.min, src.max), row.max);
      const double hi = qBound(row.min, qMax(src.min, src.max), row.max);
      if (hi <= lo)
        continue;

      RowBand band;
      band.min      = lo;
      band.max      = hi;
      band.severity = static_cast<int>(src.severity);
      row.bands.push_back(band);

      QVariantMap entry;
      entry.insert(QStringLiteral("fracMin"), qBound(0.0, (lo - row.min) / span, 1.0));
      entry.insert(QStringLiteral("fracMax"), qBound(0.0, (hi - row.min) / span, 1.0));
      entry.insert(QStringLiteral("severity"), band.severity);
      entry.insert(QStringLiteral("customColor"), src.color);
      rowBands.append(entry);
    }

    m_bandsAsVariant.append(QVariant(rowBands));
  }
}

uble Widgets::BarPanel::rowFraction(const Row& row, double value) const noexcept
{
  if (!row.ranged)
    return 0.0;

  const double clamped = qBound(row.min, value, row.max);
  return qBound(0.0, (clamped - row.min) / (row.max - row.min), 1.0);
}

ol Widgets::BarPanel::refreshRow(int index, const DataModel::Dataset& dataset)
{
  auto& row          = m_rows[static_cast<size_t>(index)];
  const bool numeric = dataset.isNumeric && std::isfinite(dataset.numericValue);

  int severity = -1;
  double frac  = 0.0;
  QString text = QStringLiteral("--");
  if (numeric) {
    frac     = rowFraction(row, dataset.numericValue);
    int band = bandIndexFor(row, dataset.numericValue);
    if (band < 0 && !row.bands.empty())
      band = nearestBandIndex(row, dataset.numericValue);

    if (band >= 0) {
      row.hint = band;
      severity = row.bands[static_cast<size_t>(band)].severity;
    }

    text = QString::number(dataset.numericValue, 'f', row.decimals);
    if (!dataset.units.isEmpty())
      text += QChar(' ') + dataset.units;
  } else {
    severity = row.bands.empty() ? -1 : 2;
    if (!dataset.value.isEmpty())
      text = dataset.value;
  }

  bool extremesOk    = false;
  double minSeenFrac = 0.0;
  double maxSeenFrac = 0.0;
  if (row.extremeHold) {
    const auto extremes = m_dashboard.datasetExtremes(row.uniqueId);
    extremesOk          = extremes.valid;
    if (extremesOk) {
      minSeenFrac = rowFraction(row, extremes.min);
      maxSeenFrac = rowFraction(row, extremes.max);
    }
  }

  const bool changed = (numeric != m_numeric[index]) || (severity != m_severities[index])
                    || (extremesOk != m_extremesOk[index]) || (text != m_valueTexts[index])
                    || DSP::notEqual(frac, m_fracs[index])
                    || DSP::notEqual(minSeenFrac, m_minSeenFracs[index])
                    || DSP::notEqual(maxSeenFrac, m_maxSeenFracs[index]);
  m_numeric[index]      = numeric;
  m_severities[index]   = severity;
  m_extremesOk[index]   = extremesOk;
  m_valueTexts[index]   = text;
  m_fracs[index]        = frac;
  m_minSeenFracs[index] = minSeenFrac;
  m_maxSeenFracs[index] = maxSeenFrac;
  return changed;
}

id Widgets::BarPanel::updateData()
{
  if (!isEnabled())
    return;

  if (VALIDATE_WIDGET(SerialStudio::DashboardBarPanel, m_index)) {
    bool changed      = false;
    const auto& group = GET_GROUP(SerialStudio::DashboardBarPanel, m_index);
    const size_t n    = qMin(m_rows.size(), group.datasets.size());
    for (size_t i = 0; i < n; ++i)
      changed |= refreshRow(static_cast<int>(i), group.datasets[i]);

    if (changed)
      Q_EMIT updated();
  }
}

[[nodiscard]] static QRect scaledManualGeometry(const QRect& preferred,
                                                const QMargins& margins,
                                                const int refW,
                                                const int refH,
                                                const int canvasW,
                                                const int canvasH)
{
  const double scaleX = refW > 0 ? double(canvasW) / double(refW) : 1.0;
  const double scaleY = refH > 0 ? double(canvasH) / double(refH) : 1.0;

  const QMargins scaled(qRound(margins.left() * scaleX),
                        qRound(margins.top() * scaleY),
                        qRound(margins.right() * scaleX),
                        qRound(margins.bottom() * scaleY));

  const int maxW = qMax(0, canvasW - scaled.left() - scaled.right());
  const int maxH = qMax(0, canvasH - scaled.top() - scaled.bottom());
  const int w    = qMin(qRound(preferred.width() * scaleX), maxW);
  const int h    = qMin(qRound(preferred.height() * scaleY), maxH);

  return anchoredGeometry(QRect(0, 0, w, h), scaled, canvasW, canvasH);
}

[[nodiscard]] static QHash<int, int> clusterEdges(const QVector<int>& edgeValues,
                                                  const int canvasEnd,
                                                  const int tolerance)
{
  QHash<int, int> mapping;
  QVector<int> edges = edgeValues;
  edges.append(0);
  edges.append(canvasEnd);
  std::sort(edges.begin(), edges.end());

  int index = 0;
  while (index < edges.size()) {
    int last      = index;
    long long sum = edges[index];
    while (last + 1 < edges.size() && edges[last + 1] - edges[last] <= tolerance) {
      ++last;
      sum += edges[last];
    }

    const int count    = last - index + 1;
    int representative = static_cast<int>(sum / count);
    if (edges[index] == 0)
      representative = 0;
    else if (edges[last] == canvasEnd)
      representative = canvasEnd;

    for (int k = index; k <= last; ++k)
      mapping.insert(edges[k], representative);

    index = last + 1;
  }

  return mapping;
}

void UI::WindowManager::publishFractionPreview(const QRect& geometry)
{
  const bool guidesOn = m_dashboard.showAlignmentGuides();
  const QString widthLabel =
    guidesOn ? Snap::fractionLabel(geometry.width(), static_cast<int>(width())) : QString();
  const QString heightLabel =
    guidesOn ? Snap::fractionLabel(geometry.height(), static_cast<int>(height())) : QString();

  QRect rect;
  QString label;
  if (!widthLabel.isEmpty() && !heightLabel.isEmpty())
    label = tr("Width: %1    Height: %2").arg(widthLabel, heightLabel);
  else if (!widthLabel.isEmpty())
    label = tr("Width: %1").arg(widthLabel);
  else if (!heightLabel.isEmpty())
    label = tr("Height: %1").arg(heightLabel);

  if (!label.isEmpty())
    rect = geometry;

  if (m_fractionPreviewRect == rect && m_fractionPreviewLabel == label)
    return;

  m_fractionPreviewRect  = rect;
  m_fractionPreviewLabel = label;
  Q_EMIT fractionPreviewChanged();
}

d::vector<TestBand> TstBarBands::apuOilBands()
{
  return {
    { 0,  25, 3},
    {25,  55, 2},
    {55,  75, 1},
    {75,  80, 2},
    {80, 150, 3},
  };
}

