  QCOMPARE(Widgets::Bands::indexFor(bands, 40.0), 1);
  QCOMPARE(Widgets::Bands::indexFor(bands, 60.0), 2);
  QCOMPARE(Widgets::Bands::indexFor(bands, 78.0), 3);
