  QCOMPARE(Widgets::Bands::indexFor(bands, 60.0, 2), 2);
  QCOMPARE(Widgets::Bands::indexFor(bands, 60.0, 0), 2);
  QCOMPARE(Widgets::Bands::indexFor(bands, 60.0, 99), 2);
  QCOMPARE(Widgets::Bands::indexFor(bands, 60.0, -5), 2);
