  QCOMPARE(Widgets::Bands::indexFor(bands, 0.0), 0);
  QCOMPARE(Widgets::Bands::indexFor(bands, 25.0), 0);
  QCOMPARE(Widgets::Bands::indexFor(bands, 150.0), 4);
