[[nodiscard]] static QHash<QString, bool>& fdCapabilityCache()
{
  static QHash<QString, bool> cache;
  return cache;
}

[[nodiscard]] static bool probeFdCapability(libusb_device* device)
{
  SS_ASSERT(device != nullptr, return false);

  libusb_device_handle* handle = nullptr;
  if (libusb_open(device, &handle) < 0)
    return false;

  GsDeviceBtConst bt{};
  const std::uint8_t type =
    static_cast<std::uint8_t>(static_cast<unsigned>(LIBUSB_REQUEST_TYPE_VENDOR)
                              | static_cast<unsigned>(LIBUSB_RECIPIENT_INTERFACE)
                              | static_cast<unsigned>(LIBUSB_ENDPOINT_IN));
  const int rc = libusb_control_transfer(handle,
                                         type,
                                         kBreqBtConst,
                                         0,
                                         0,
                                         reinterpret_cast<unsigned char*>(&bt),
                                         sizeof(bt),
                                         kCtrlTimeoutMs);
  libusb_close(handle);

  return rc == static_cast<int>(sizeof(bt)) && (bt.feature & kFeatureFd) != 0;
}

[[nodiscard]] static HotplugNotifier& hotplugNotifier()
{
  static HotplugNotifier notifier;
  return notifier;
}

static int LIBUSB_CALL onGsUsbHotplug(libusb_context* context,
                                      libusb_device* device,
                                      libusb_hotplug_event event,
                                      void* user_data)
{
  Q_UNUSED(context)
  Q_UNUSED(event)
  Q_UNUSED(user_data)

  libusb_device_descriptor desc{};
  if (libusb_get_device_descriptor(device, &desc) < 0 || !isGsUsbDevice(desc))
    return 0;

  HotplugNotifier& notifier = hotplugNotifier();
  const std::lock_guard<std::mutex> guard(notifier.lock);
  if (notifier.context && notifier.notify)
    QMetaObject::invokeMethod(notifier.context, notifier.notify, Qt::QueuedConnection);

  return 0;
}

static void startHotplugPump(libusb_context* ctx)
{
  static std::once_flag once;
  std::call_once(once, [ctx] {
    std::thread([ctx] {
      timeval timeout{1, 0};
      // code-verify off
      // Intentional process-lifetime service loop, like the readLoop worker: the thread dies
      // with the process, mirroring the never-libusb_exit shared-context invariant.
      while (true)
        libusb_handle_events_timeout(ctx, &timeout);
      // code-verify on
    }).detach();
  });
}

void IO::Drivers::GsUsbCanBackend::setHotplugNotifier(QObject* context,
                                                      std::function<void()> notifier)
{
  SS_ASSERT(context != nullptr, return);

  libusb_context* ctx = sharedUsbContext();
  if (!ctx || !libusb_has_capability(LIBUSB_CAP_HAS_HOTPLUG))
    return;

  static const bool registered = [ctx] {
    libusb_hotplug_callback_handle handle = 0;
    return libusb_hotplug_register_callback(
             ctx,
             static_cast<libusb_hotplug_event>(LIBUSB_HOTPLUG_EVENT_DEVICE_ARRIVED
                                               | LIBUSB_HOTPLUG_EVENT_DEVICE_LEFT),
             static_cast<libusb_hotplug_flag>(0),
             LIBUSB_HOTPLUG_MATCH_ANY,
             LIBUSB_HOTPLUG_MATCH_ANY,
             LIBUSB_HOTPLUG_MATCH_ANY,
             &onGsUsbHotplug,
             nullptr,
             &handle)
        == LIBUSB_SUCCESS;
  }();
  if (!registered)
    return;

  {
    const std::lock_guard<std::mutex> guard(hotplugNotifier().lock);
    SS_ASSERT(hotplugNotifier().context == nullptr, return);
    hotplugNotifier().context = context;
    hotplugNotifier().notify  = std::move(notifier);
  }

  startHotplugPump(ctx);
}

void IO::Drivers::GsUsbCanBackend::clearHotplugNotifier(QObject* context)
{
  HotplugNotifier& notifier = hotplugNotifier();
  const std::lock_guard<std::mutex> guard(notifier.lock);
  if (notifier.context != context)
    return;

  notifier.context = nullptr;
  notifier.notify  = nullptr;
}

bool IO::Drivers::GsUsbCanBackend::configureFdDataTiming(quint32 feature)
{
  SS_ASSERT(m_handle != nullptr, return false);

  const auto configured  = configurationParameter(QCanBusDevice::DataBitRateKey).toUInt();
  const quint32 dataRate = configured == 0 ? kDefaultFdDataBitrate : configured;

  GsDeviceBtConst limits{};
  if ((feature & kFeatureBtConstExt) != 0) {
    GsDeviceBtConstExt ext{};
    if (controlIn(kBreqBtConstExt, 0, &ext, sizeof(ext)) != static_cast<int>(sizeof(ext))) {
      setError(tr("Could not read CANable FD timing constants."),
               QCanBusDevice::ConfigurationError);
      return false;
    }

    limits = timingLimits(ext, true);
  } else if (controlIn(kBreqBtConst, 0, &limits, sizeof(limits))
             != static_cast<int>(sizeof(limits))) {
    setError(tr("Could not read CANable timing constants."), QCanBusDevice::ConfigurationError);
    return false;
  }

  GsDeviceBitTiming timing{};
  if (!solveBitTiming(limits, dataRate, timing)) {
    setError(tr("The data bitrate %1 bps is not supported by this CANable adapter.").arg(dataRate),
             QCanBusDevice::ConfigurationError);
    return false;
  }

  if (controlOut(kBreqDataBitTiming, 0, &timing, sizeof(timing))
      != static_cast<int>(sizeof(timing))) {
    setError(tr("CANable adapter rejected the requested data bitrate."),
             QCanBusDevice::ConfigurationError);
    return false;
  }

  return true;
}

static void queueErrorBox(QObject* context, const QString& title, const QString& text)
{
  QMetaObject::invokeMethod(
    context,
    [title, text] { Misc::Utilities::showMessageBox(title, text, QMessageBox::Critical); },
    Qt::QueuedConnection);
}

CLI::ProcessResult CLI::runSessionRegression()
{
  Sessions::Verifier::Options options;
  options.mode                 = Sessions::Verifier::Mode::Regress;
  options.dbPath               = m_parser.value(m_opts.regressSessionOpt).trimmed();
  options.candidateProjectPath = m_parser.value(m_opts.regressProjectOpt).trimmed();
  options.keepRegenerated      = m_parser.isSet(m_opts.regressKeepRegenOpt);

  if (options.candidateProjectPath.isEmpty()) {
    std::fputs("{\"verdict\":\"error\",\"errorCode\":\"regress-candidate-unreadable\","
               "\"error\":\"missing --regress-project\",\"hint\":\"Pass the candidate project "
               "file to compare the archived session against.\"}\n",
               stdout);
    std::fflush(stdout);
    return ProcessResult::ExitFailure;
  }

  if (m_parser.isSet(m_opts.regressSessionIdOpt)) {
    bool ok       = false;
    const int val = m_parser.value(m_opts.regressSessionIdOpt).toInt(&ok);
    if (!ok || val < 0) {
      std::fputs("{\"verdict\":\"error\",\"error\":\"invalid --regress-session-id\"}\n", stdout);
      std::fflush(stdout);
      return ProcessResult::ExitFailure;
    }

    options.sessionId = val;
  }

  Misc::ModuleManager::instantiateCoreModules();
  Misc::ModuleManager::setupHeadlessSessionConnections();

  Sessions::Verifier verifier(options);
  const int code = verifier.run();

  std::fputs(QJsonDocument(verifier.report()).toJson(QJsonDocument::Indented).constData(), stdout);
  std::fflush(stdout);

  Misc::ModuleManager::teardownHeadlessSessionModules();

void Misc::ModuleManager::teardownHeadlessSessionModules()
{
#ifdef BUILD_COMMERCIAL
  Sessions::Export::instance().closeFile();
  Sessions::Player::instance().closeFile();
  Sessions::Player::instance().shutdown();
  Sessions::DatabaseManager::instance().closeDatabase(false);
  Sessions::DatabaseManager::instance().shutdown();
#endif
}

static QVariantMap childFailureReport(const QString& code,
                                      int exitCode,
                                      const QByteArray& stderrData)
{
  static const struct {
    const char* code;
    const char* error;
    const char* hint;
  } kFailures[] = {
    {  "child-spawn-failed",
     "The check could not be started.",                                               "Restart Serial Studio and try again."        },
    {       "child-crashed",
     "The check stopped unexpectedly.", "Try again. If this keeps happening, please report it and include the session file."        },
    {"child-output-invalid",
     "The check did not return a readable result.",                                                "Try again. If this keeps happening, other software on this computer may be "
                                                "interfering with Serial Studio."},
  };

  QVariantMap map;
  map.insert(QStringLiteral("verdict"), QStringLiteral("error"));
  map.insert(QStringLiteral("errorCode"), code);
  map.insert(QStringLiteral("exitCode"), exitCode);
  for (const auto& entry : kFailures) {
    if (code == QLatin1String(entry.code)) {
      map.insert(QStringLiteral("error"), QString::fromLatin1(entry.error));
      map.insert(QStringLiteral("hint"), QString::fromLatin1(entry.hint));
      break;
    }
  }

  const QString tail = QString::fromUtf8(stderrData.right(kStderrTailBytes)).trimmed();
  if (!tail.isEmpty())
    map.insert(QStringLiteral("stderrTail"), tail);

  return map;
}

bool Sessions::DatabaseManager::publishRegressStartFailure(int sessionId,
                                                           const QString& code,
                                                           const QString& error,
                                                           const QString& hint)
{
  QVariantMap map;
  map.insert(QStringLiteral("verdict"), QStringLiteral("error"));
  map.insert(QStringLiteral("errorCode"), code);
  map.insert(QStringLiteral("error"), error);
  map.insert(QStringLiteral("hint"), hint);

  m_lastRegressionReport = map;
  Q_EMIT regressionReportChanged();
  Q_EMIT regressionFinished(sessionId, false, map);
  return false;
}

static bool writeCandidateSnapshot(const QString& path)
{
  static auto& project = DataModel::ProjectModel::instance();
  const auto json      = QJsonDocument(project.serializeToJson()).toJson(QJsonDocument::Compact);

  QFile file(path);
  if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate) || file.write(json) != json.size()) {
    file.close();
    QFile::remove(path);
    return false;
  }

  return true;
}

bool Sessions::DatabaseManager::regressSession(int sessionId, const QString& candidatePath)
{
  SS_ASSERT(m_open, return false);
  SS_ASSERT(!m_filePath.isEmpty(), return false);

  if (m_verifyProcess)
    return false;

  QString candidate = candidatePath;
  m_regressCandidateTemp.clear();
  if (candidate.isEmpty()) {
    candidate = QDir::temp().filePath(
      QStringLiteral("ss-regress-candidate-%1.json").arg(QCoreApplication::applicationPid()));
    if (!writeCandidateSnapshot(candidate))
      return publishRegressStartFailure(
        sessionId,
        QStringLiteral("candidate-write-failed"),
        QStringLiteral("The current project could not be saved for comparison."),
        QStringLiteral("Check that there is enough free disk space, then try again."));

    m_regressCandidateTemp = candidate;
  }

  auto* process   = new QProcess(this);
  m_verifyProcess = process;
  m_regressActive = true;
  m_lastRegressionReport.clear();
  Q_EMIT verificationBusyChanged();
  Q_EMIT regressionBusyChanged();
  Q_EMIT regressionReportChanged();

  QStringList args{QStringLiteral("--regress-session"),
                   m_filePath,
                   QStringLiteral("--headless"),
                   QStringLiteral("--regress-project"),
                   candidate};
  if (sessionId >= 0)
    args << QStringLiteral("--regress-session-id") << QString::number(sessionId);

  connect(process,
          &QProcess::finished,
          this,
          [this, process, sessionId](int exitCode, QProcess::ExitStatus status) {
            const auto doc = QJsonDocument::fromJson(process->readAllStandardOutput());
            const bool ok  = status == QProcess::NormalExit && doc.isObject();
            auto map       = doc.object().toVariantMap();
            if (!ok)
              map = childFailureReport(status != QProcess::NormalExit
                                         ? QStringLiteral("child-crashed")
                                         : QStringLiteral("child-output-invalid"),
                                       exitCode,
                                       process->readAllStandardError());

            int resolvedId = sessionId;
            if (resolvedId < 0 && map.contains(QStringLiteral("sessionId")))
              resolvedId = map.value(QStringLiteral("sessionId")).toInt();

            concludeRegression(resolvedId, ok && exitCode == 0, map);
          });
  connect(process, &QProcess::errorOccurred, this, [this, sessionId](QProcess::ProcessError err) {
    if (err != QProcess::FailedToStart)
      return;

    QMetaObject::invokeMethod(
      this,
      [this, sessionId]() {
        concludeRegression(
          sessionId,
          false,
          childFailureReport(QStringLiteral("child-spawn-failed"), -1, QByteArray()));
      },
      Qt::QueuedConnection);
  });

  process->start(QCoreApplication::applicationFilePath(), args);
  return true;
}

void Sessions::DatabaseManager::concludeRegression(int sessionId,
                                                   bool success,
                                                   const QVariantMap& report)
{
  if (!m_verifyProcess)
    return;

  m_verifyProcess->deleteLater();
  m_verifyProcess = nullptr;
  m_regressActive = false;

  if (!m_regressCandidateTemp.isEmpty()) {
    QFile::remove(m_regressCandidateTemp);
    m_regressCandidateTemp.clear();
  }

  m_lastRegressionReport = report;
  if (m_sweepActive)
    advanceRegressionSweep(sessionId, report);

  Q_EMIT verificationBusyChanged();
  Q_EMIT regressionBusyChanged();
  Q_EMIT regressionReportChanged();
  Q_EMIT regressionFinished(sessionId, success, report);
}

bool Sessions::DatabaseManager::regressSessionsByTag(const QString& tag,
                                                     const QString& candidatePath)
{
  SS_ASSERT(m_open, return false);

  if (m_verifyProcess || m_sweepActive || tag.trimmed().isEmpty())
    return false;

  bool queryOk = false;
  QList<int> ids;
  const QString connName = QStringLiteral("ss_dbm_sweep_read");
  {
    auto db = QSqlDatabase::addDatabase(QStringLiteral("QSQLITE"), connName);
    db.setDatabaseName(m_filePath);
    db.setConnectOptions(QStringLiteral("QSQLITE_OPEN_READONLY"));
    if (db.open()) {
      QSqlQuery q(db);
      q.prepare(QStringLiteral("SELECT s.session_id FROM sessions s "
                               "JOIN session_tags st ON st.session_id = s.session_id "
                               "JOIN tags t ON t.tag_id = st.tag_id "
                               "WHERE t.label = ? AND s.ended_at IS NOT NULL "
                               "ORDER BY s.session_id"));
      q.bindValue(0, tag.trimmed());
      queryOk = q.exec();
      while (queryOk && q.next())
        ids.append(q.value(0).toInt());

      db.close();
    }
  }

  QSqlDatabase::removeDatabase(connName);

  if (!queryOk)
    return publishRegressStartFailure(-1,
                                      QStringLiteral("sweep-query-failed"),
                                      QStringLiteral("The tagged sessions could not be listed."),
                                      QStringLiteral("Reopen the session file and try again."));

  QString candidate   = candidatePath;
  bool owns_candidate = false;
  if (candidate.isEmpty() && !ids.isEmpty()) {
    candidate = QDir::temp().filePath(
      QStringLiteral("ss-regress-sweep-%1.json").arg(QCoreApplication::applicationPid()));
    if (!writeCandidateSnapshot(candidate))
      return publishRegressStartFailure(
        -1,
        QStringLiteral("candidate-write-failed"),
        QStringLiteral("The current project could not be saved for comparison."),
        QStringLiteral("Check that there is enough free disk space, then try again."));

    owns_candidate = true;
  }

  m_sweepTag           = tag.trimmed();
  m_sweepReports       = QVariantList();
  m_sweepOwnsCandidate = owns_candidate;
  m_sweepCandidate     = candidate;
  m_sweepQueue         = ids;
  m_sweepActive        = true;
  Q_EMIT regressionSweepChanged();

  if (m_sweepQueue.isEmpty()) {
    finishRegressionSweep();
    return true;
  }

  const int first = m_sweepQueue.takeFirst();
  if (!regressSession(first, m_sweepCandidate)) {
    finishRegressionSweep();
    return false;
  }

  return true;
}

void Sessions::DatabaseManager::advanceRegressionSweep(int sessionId, const QVariantMap& report)
{
  QVariantMap entry;
  entry.insert(QStringLiteral("sessionId"), sessionId);
  entry.insert(QStringLiteral("report"), report);
  m_sweepReports.append(entry);

  if (m_sweepQueue.isEmpty() || !m_open) {
    finishRegressionSweep();
    return;
  }

  const int next = m_sweepQueue.takeFirst();
  if (!regressSession(next, m_sweepCandidate))
    finishRegressionSweep();
}

void Sessions::DatabaseManager::finishRegressionSweep()
{
  if (m_sweepOwnsCandidate && !m_sweepCandidate.isEmpty())
    QFile::remove(m_sweepCandidate);

  m_sweepActive        = false;
  m_sweepOwnsCandidate = false;
  m_sweepCandidate.clear();
  m_sweepQueue.clear();
  Q_EMIT regressionSweepChanged();
}

static void countSweepVerdict(
  const QString& verdict, int& passed, int& drifted, int& notVerifiable, int& failed)
{
  if (verdict == QLatin1String("identical"))
    ++passed;
  else if (verdict.endsWith(QLatin1String("-drift")))
    ++drifted;
  else if (verdict == QLatin1String("not_verifiable"))
    ++notVerifiable;
  else
    ++failed;
}

QVariantMap Sessions::DatabaseManager::regressionSweepStatus() const
{
  int passed = 0, drifted = 0, notVerifiable = 0, failed = 0;
  for (const auto& entryVariant : m_sweepReports) {
    const auto report = entryVariant.toMap().value(QStringLiteral("report")).toMap();
    countSweepVerdict(
      report.value(QStringLiteral("verdict")).toString(), passed, drifted, notVerifiable, failed);
  }

  QVariantMap summary;
  summary.insert(QStringLiteral("passed"), passed);
  summary.insert(QStringLiteral("drifted"), drifted);
  summary.insert(QStringLiteral("notVerifiable"), notVerifiable);
  summary.insert(QStringLiteral("failed"), failed);

  QVariantMap status;
  status.insert(QStringLiteral("active"), m_sweepActive);
  status.insert(QStringLiteral("tag"), m_sweepTag);
  status.insert(QStringLiteral("remaining"), m_sweepQueue.size());
  status.insert(QStringLiteral("summary"), summary);
  status.insert(QStringLiteral("reports"), m_sweepReports);
  return status;
}

void Sessions::Verifier::reparseFailureText(const QString& code, QString& reason, QString& hint)
{
  static const struct {
    const char* code;
    const char* reason;
    const char* hint;
  } kFailures[] = {
    { "stored-project-invalid",
     "The project settings saved with this session are damaged.",   "The session cannot be checked. Restore the session file from a backup copy."},
    {"stored-project-rejected",
     "The project settings saved with this session cannot be loaded by this version of "
     "Serial Studio.",                                                  "Update Serial Studio to a version at least as new as the one that recorded the "
                                                  "session, then try again."                                               },
    {    "export-not-licensed",
     "Session recording is not activated on this computer.",                                                           "Checking a session requires a Pro license. Activate a license or start a trial, "
                                                           "then try again."         },
    {    "export-start-failed",
     "A temporary working file could not be created.",                   "Check that there is enough free disk space, then try again."           },
    {            "feed-failed",
     "The recorded data in this session could not be replayed.", "The session file may be incomplete or damaged. Restore it from a backup copy." },
  };

  for (const auto& entry : kFailures) {
    if (code == QLatin1String(entry.code)) {
      reason = QString::fromLatin1(entry.reason);
      hint   = QString::fromLatin1(entry.hint);
      return;
    }
  }

  reason = QStringLiteral("The session could not be checked.");
  hint   = QStringLiteral("Try again. If this keeps happening, the session file may be "
                          "damaged.");
}

[[nodiscard]] bool open(QSqlDatabase& db, int sessionId, qint64 uniqueId, qint64 firstChunk)
  {
    first_chunk = firstChunk;
    query       = QSqlQuery(db);
    query.prepare(QStringLiteral("SELECT timestamp_ns, raw_numeric_value, raw_string_value, "
                                 "final_numeric_value, final_string_value, is_numeric "
                                 "FROM readings WHERE session_id = ? AND unique_id = ? "
                                 "ORDER BY timestamp_ns, reading_id"));
    query.bindValue(0, sessionId);
    query.bindValue(1, uniqueId);
    if (!query.exec())
      return false;

    advance();
    return true;
  }

void advance()
  {
    valid = query.next();
    if (!valid)
      return;

    const qint64 ns = query.value(0).toLongLong();
    chunk           = ns / Sessions::Verifier::kChunkStepNs + first_chunk;
    rank            = ns % Sessions::Verifier::kChunkStepNs;
    raw_numeric     = SerialStudio::toDouble(query.value(1));
    raw_string      = query.value(2).toString();
    final_numeric   = SerialStudio::toDouble(query.value(3));
    final_string    = query.value(4).toString();
    is_numeric      = query.value(5).toInt() != 0;
  }

static bool loadRegenColumns(QSqlDatabase& db,
                             int sessionId,
                             std::map<qint64, QString>& titles,
                             QSet<qint64>& virtuals)
{
  QSqlQuery q(db);
  q.prepare(
    QStringLiteral("SELECT unique_id, title, is_virtual FROM columns WHERE session_id = ?"));
  q.bindValue(0, sessionId);
  if (!q.exec())
    return false;

  while (q.next()) {
    titles[q.value(0).toLongLong()] = q.value(1).toString();
    if (q.value(2).toInt() != 0)
      virtuals.insert(q.value(0).toLongLong());
  }

  return true;
}

static bool openRegen(const QString& path, const QString& connName, int& sessionId)
{
  auto db = QSqlDatabase::addDatabase(QStringLiteral("QSQLITE"), connName);
  db.setDatabaseName(path);
  db.setConnectOptions(QStringLiteral("QSQLITE_OPEN_READONLY"));
  if (!db.open())
    return false;

  QSqlQuery q(db);
  if (!q.exec(QStringLiteral("SELECT COUNT(*), MAX(session_id) FROM sessions")) || !q.next()
      || q.value(0).toInt() != 1)
    return false;

  sessionId = q.value(1).toInt();
  return true;
}

static QSet<int> projectSourceIds(const QString& projectJson)
{
  QSet<int> ids;
  const auto doc = QJsonDocument::fromJson(projectJson.toUtf8());
  if (!doc.isObject())
    return ids;

  const auto sources = doc.object().value(Keys::Sources).toArray();
  if (sources.isEmpty()) {
    ids.insert(0);
    return ids;
  }

  for (const auto& src : sources)
    ids.insert(src.toObject().value(Keys::SourceId).toInt());

  return ids;
}

static QMap<int, QString> parserCodeBySource(const QJsonObject& project)
{
  QMap<int, QString> code;
  code.insert(-1, project.value(Keys::FrameParserCode).toString());

  const auto sources = project.value(Keys::Sources).toArray();
  for (const auto& src : sources) {
    const auto obj = src.toObject();
    code.insert(obj.value(Keys::SourceId).toInt(), obj.value(Keys::FrameParserCode).toString());
  }

  return code;
}

static QStringList transformCodes(const QJsonObject& project)
{
  QStringList codes;
  const auto groups = project.value(Keys::Groups).toArray();
  for (const auto& group : groups) {
    const auto datasets = group.toObject().value(Keys::Datasets).toArray();
    for (const auto& dataset : datasets)
      codes.append(dataset.toObject().value(Keys::TransformCode).toString());
  }

  return codes;
}

static QJsonObject compareProjectCode(const QString& baseJson, const QString& candJson)
{
  const auto base = QJsonDocument::fromJson(baseJson.toUtf8()).object();
  const auto cand = QJsonDocument::fromJson(candJson.toUtf8()).object();

  QJsonObject result;
  result.insert(QStringLiteral("controlScriptChanged"),
                base.value(Keys::ControlScriptCode).toString()
                  != cand.value(Keys::ControlScriptCode).toString());
  result.insert(QStringLiteral("frameParserChanged"),
                parserCodeBySource(base) != parserCodeBySource(cand));
  result.insert(QStringLiteral("transformsChanged"), transformCodes(base) != transformCodes(cand));
  return result;
}

int Sessions::Verifier::runRegression()
{
  SS_ASSERT(m_options.mode == Mode::Regress, return kExitError);
  SS_ASSERT(!m_options.dbPath.isEmpty(), return kExitError);

  if (!openArchive())
    return failRegress(QStringLiteral("open-archive-failed"),
                       QStringLiteral("The session file could not be opened."),
                       QStringLiteral("Check that the file still exists and that you have "
                                      "permission to read it, then try again."));

  if (!loadSession())
    return failRegress(QStringLiteral("session-not-found"),
                       QStringLiteral("That session could not be found in this file."),
                       QStringLiteral("Choose a completed session from the list and try "
                                      "again."));

  classifySession();

  if (sessionIsConsoleOnly()) {
    m_verdict = QStringLiteral("not_verifiable");
    m_notes.append(QStringLiteral("This session contains raw console data only, so there "
                                  "is nothing to compare."));
    return settleRegressVerdict();
  }

  if (m_controlScriptSeen)
    m_notes.append(QStringLiteral("This session used a control script while recording. "
                                  "Scripts do not run during this comparison; values they "
                                  "provided are skipped, and everything parsed from the "
                                  "recorded data is compared."));

  const QString candidateError = loadCandidate();
  if (!candidateError.isEmpty())
    return failRegress(candidateError,
                       QStringLiteral("The project to compare against could not be loaded."),
                       QStringLiteral("Choose a readable Serial Studio project file, or open "
                                      "a valid project in the editor, then try again."));

  m_codeChanges = compareProjectCode(m_projectJson, m_candidateJson);
  if (m_codeChanges.value(QStringLiteral("controlScriptChanged")).toBool())
    m_notes.append(QStringLiteral("The control script differs between the recorded project "
                                  "and the current project."));

  if (m_codeChanges.value(QStringLiteral("frameParserChanged")).toBool())
    m_notes.append(QStringLiteral("The frame parser differs between the recorded project "
                                  "and the current project."));

  if (m_codeChanges.value(QStringLiteral("transformsChanged")).toBool())
    m_notes.append(QStringLiteral("One or more value transforms differ between the recorded "
                                  "project and the current project."));

  DataModel::ControlScript::instance().shutdown();

  const QString replayError = replayBothSides();
  if (replayError == QLatin1String("chunk-budget-exceeded") || m_chunkBudgetExceeded)
    return failRegress(QStringLiteral("chunk-budget-exceeded"),
                       QStringLiteral("This session is too dense to compare reliably."),
                       QStringLiteral("The check was stopped instead of showing results "
                                      "that could be wrong."));

  if (!replayError.isEmpty()) {
    QString reason, hint;
    reparseFailureText(replayError, reason, hint);
    return failRegress(replayError, reason, hint);
  }

  if (!regressDiff())
    return failRegress(QStringLiteral("diff-failed"),
                       QStringLiteral("The results could not be compared."),
                       QStringLiteral("Try again. If this keeps happening, the session file "
                                      "may be damaged."));

  const int code = settleRegressVerdict();
  cleanupRegenerated();
  return code;
}

QString Sessions::Verifier::loadCandidate()
{
  SS_ASSERT(!m_options.candidateProjectPath.isEmpty(),
            return QStringLiteral("regress-candidate-unreadable"));

  QFile file(m_options.candidateProjectPath);
  if (!file.open(QIODevice::ReadOnly))
    return QStringLiteral("regress-candidate-unreadable");

  if (file.size() > kMaxCandidateBytes)
    return QStringLiteral("regress-candidate-invalid");

  const QByteArray bytes = file.readAll();
  const auto doc         = QJsonDocument::fromJson(bytes);
  if (!doc.isObject())
    return QStringLiteral("regress-candidate-invalid");

  m_candidateJson = QString::fromUtf8(bytes);
  m_candidateSha256 =
    QString::fromLatin1(QCryptographicHash::hash(bytes, QCryptographicHash::Sha256).toHex());
  m_candidateTitle = doc.object().value(Keys::Title).toString();
  return QString();
}

QSet<int> Sessions::Verifier::archivedDeviceIds(bool& ok)
{
  QSet<int> ids;
  QSqlQuery q(m_db);
  q.prepare(QStringLiteral("SELECT DISTINCT device_id FROM raw_bytes WHERE session_id = ?"));
  q.bindValue(0, m_sessionId);
  ok = q.exec();
  while (ok && q.next())
    ids.insert(q.value(0).toInt());

  return ids;
}

QString Sessions::Verifier::replayBothSides()
{
  SS_ASSERT(m_db.isOpen(), return QStringLiteral("feed-failed"));
  SS_ASSERT(!m_candidateJson.isEmpty(), return QStringLiteral("regress-candidate-invalid"));

  bool devicesOk          = false;
  const QSet<int> devices = archivedDeviceIds(devicesOk);
  if (!devicesOk)
    return QStringLiteral("feed-failed");

  const QString pidSuffix = QString::number(QCoreApplication::applicationPid());

  m_feedExcludedDevices = devices - projectSourceIds(m_projectJson);
  const QString baselineError =
    reparseSession(m_projectJson,
                   QDir::temp().filePath(QStringLiteral("ss-regress-base-%1.db").arg(pidSuffix)),
                   true);
  if (!baselineError.isEmpty())
    return baselineError;

  if (m_chunkBudgetExceeded)
    return QStringLiteral("chunk-budget-exceeded");

  m_baselineFirstChunk = m_firstFrameChunk;
  m_replayStats.insert(QStringLiteral("baseline"), replaySideStats());

  m_readers.clear();
  const QSet<int> candidateExcluded = devices - projectSourceIds(m_candidateJson);
  m_candidateRemovedDevices = QList<int>(candidateExcluded.begin(), candidateExcluded.end());
  std::sort(m_candidateRemovedDevices.begin(), m_candidateRemovedDevices.end());

  m_feedExcludedDevices = candidateExcluded;
  const QString candidateError =
    reparseSession(m_candidateJson,
                   QDir::temp().filePath(QStringLiteral("ss-regress-cand-%1.db").arg(pidSuffix)),
                   true);
  if (!candidateError.isEmpty())
    return candidateError;

  m_candidateFirstChunk = m_firstFrameChunk;
  m_replayStats.insert(QStringLiteral("candidate"), replaySideStats());
  m_feedExcludedDevices.clear();
  return QString();
}

QJsonObject Sessions::Verifier::replaySideStats() const
{
  static auto& builder = DataModel::FrameBuilder::instance();
  return QJsonObject{
    {      QStringLiteral("chunksFed"),                                   m_lastFeedChunks},
    {QStringLiteral("framesExtracted"),                                   m_lastFeedFrames},
    {QStringLiteral("firstFrameChunk"),                                  m_firstFrameChunk},
    {   QStringLiteral("framesParsed"),    static_cast<qint64>(builder.parsedFrameCount())},
    {  QStringLiteral("framesSkipped"),   static_cast<qint64>(builder.skippedFrameCount())},
    {QStringLiteral("transformErrors"), static_cast<qint64>(builder.transformErrorCount())}
  };
}

std::vector<qint64> Sessions::Verifier::chunkTimestamps()
{
  std::vector<qint64> stamps;
  QSqlQuery q(m_db);
  q.prepare(
    QStringLiteral("SELECT timestamp_ns FROM raw_bytes WHERE session_id = ? ORDER BY raw_id"));
  q.bindValue(0, m_sessionId);
  if (q.exec())
    while (q.next())
      stamps.push_back(q.value(0).toLongLong());

  return stamps;
}

static QJsonObject diffRegressDataset(const QString& title,
                                      qint64 uniqueId,
                                      bool compareFinals,
                                      const std::vector<qint64>& stamps,
                                      RegenCursor& base,
                                      RegenCursor& cand)
{
  SS_ASSERT_LOG(uniqueId >= 0);

  qint64 compared = 0, changed = 0, onlyBaseline = 0, onlyCandidate = 0;
  double maxDelta = 0.0;
  QJsonArray divergenceSamples;

  // code-verify off -- every branch advances at least one finite SQL cursor
  while (base.valid && cand.valid) {
    const auto keyOrder = (base.chunk != cand.chunk)
                          ? (base.chunk < cand.chunk ? -1 : 1)
                          : (base.rank == cand.rank ? 0 : (base.rank < cand.rank ? -1 : 1));
    if (keyOrder < 0) {
      ++onlyBaseline;
      base.advance();
      continue;
    }

    if (keyOrder > 0) {
      ++onlyCandidate;
      cand.advance();
      continue;
    }

    ++compared;
    const bool rawMatch =
      regressBitEqual(base.raw_numeric, cand.raw_numeric) && base.raw_string == cand.raw_string;
    const bool finalMatch = !compareFinals
                         || (regressBitEqual(base.final_numeric, cand.final_numeric)
                             && base.final_string == cand.final_string);
    if (!rawMatch || !finalMatch) {
      ++changed;
      if (base.is_numeric && cand.is_numeric)
        maxDelta = std::max(maxDelta, std::fabs(base.final_numeric - cand.final_numeric));

      if (divergenceSamples.size() < kMaxDivergenceSamples) {
        const qint64 captureNs =
          (base.chunk >= 0 && base.chunk < static_cast<qint64>(stamps.size())) ? stamps[base.chunk]
                                                                               : -1;
        divergenceSamples.append(QJsonObject{
          {   QStringLiteral("captureTimestampNs"),captureNs                                                   },
          {                QStringLiteral("stage"),
           !rawMatch ? QStringLiteral("parse") : QStringLiteral("transform")},
          {          QStringLiteral("baselineRaw"),          base.raw_string},
          {         QStringLiteral("candidateRaw"),          cand.raw_string},
          {        QStringLiteral("baselineFinal"),        base.final_string},
          {       QStringLiteral("candidateFinal"),        cand.final_string},
          { QStringLiteral("baselineFinalNumeric"),       base.final_numeric},
          {QStringLiteral("candidateFinalNumeric"),       cand.final_numeric}
        });
      }
    }

    base.advance();
    cand.advance();
  }

  while (base.valid) {
    ++onlyBaseline;
    base.advance();
  }

  while (cand.valid) {
    ++onlyCandidate;
    cand.advance();
  }
  // code-verify on

  QJsonObject result;
  result.insert(Keys::UniqueId, uniqueId);
  result.insert(QStringLiteral("title"), title);
  result.insert(QStringLiteral("finalsCompared"), compareFinals);
  result.insert(QStringLiteral("compared"), compared);
  result.insert(QStringLiteral("changed"), changed);
  result.insert(QStringLiteral("onlyBaseline"), onlyBaseline);
  result.insert(QStringLiteral("onlyCandidate"), onlyCandidate);
  if (changed > 0)
    result.insert(QStringLiteral("maxDelta"), maxDelta);

  if (!divergenceSamples.isEmpty()) {
    result.insert(QStringLiteral("firstDivergence"), divergenceSamples.first().toObject());
    result.insert(QStringLiteral("divergences"), divergenceSamples);
  }

  return result;
}

bool Sessions::Verifier::reportOneSidedStructural(const QString& regenPath, bool sideIsBaseline)
{
  const QString connName = QStringLiteral("ss_regress_onesided");
  bool ok                = false;
  {
    int sessionId = -1;
    if (openRegen(regenPath, connName, sessionId)) {
      auto db = QSqlDatabase::database(connName);
      std::map<qint64, QString> titles;
      QSet<qint64> virtuals;
      ok = loadRegenColumns(db, sessionId, titles, virtuals);
      if (ok)
        for (const auto& [uid, title] : titles)
          m_datasetReports.append(QJsonObject{
            {              Keys::UniqueId,uid                                          },
            {     QStringLiteral("title"),                                  title},
            {QStringLiteral("structural"),
             sideIsBaseline ? QStringLiteral("removed") : QStringLiteral("added")}
          });

      db.close();
    }
  }

  QSqlDatabase::removeDatabase(connName);
  return ok;
}

bool Sessions::Verifier::regressDiff()
{
  SS_ASSERT(m_regenPaths.size() == 2, return false);

  const bool baseExists = QFile::exists(m_regenPaths[0]);
  const bool candExists = QFile::exists(m_regenPaths[1]);
  if (!baseExists && !candExists) {
    m_notes.append(QStringLiteral("Neither the saved project nor the current project "
                                  "produced any values from this recording."));
    return true;
  }

  if (baseExists != candExists) {
    m_notes.append(candExists ? QStringLiteral("The project saved with this session no longer "
                                               "produces any values, so every dataset from the "
                                               "current project is shown as added.")
                              : QStringLiteral("The current project produces no values from this "
                                               "recording, so every recorded dataset is shown as "
                                               "removed."));
    return reportOneSidedStructural(baseExists ? m_regenPaths[0] : m_regenPaths[1], baseExists);
  }

  const QString baseConn = QStringLiteral("ss_regress_base");
  const QString candConn = QStringLiteral("ss_regress_cand");
  bool ok                = false;
  {
    int baseSession = -1, candSession = -1;
    if (openRegen(m_regenPaths[0], baseConn, baseSession)
        && openRegen(m_regenPaths[1], candConn, candSession)) {
      auto baseDb = QSqlDatabase::database(baseConn);
      auto candDb = QSqlDatabase::database(candConn);
      ok          = diffRegenPair(baseDb, candDb, baseSession, candSession);
      baseDb.close();
      candDb.close();
    }
  }

  QSqlDatabase::removeDatabase(baseConn);
  QSqlDatabase::removeDatabase(candConn);
  return ok;
}

bool Sessions::Verifier::diffRegenPair(QSqlDatabase& baseDb,
                                       QSqlDatabase& candDb,
                                       int baseSession,
                                       int candSession)
{
  SS_ASSERT(baseDb.isOpen(), return false);
  SS_ASSERT(candDb.isOpen(), return false);

  std::map<qint64, QString> baseTitles, candTitles;
  QSet<qint64> baseVirtuals, candVirtuals;
  if (!loadRegenColumns(baseDb, baseSession, baseTitles, baseVirtuals)
      || !loadRegenColumns(candDb, candSession, candTitles, candVirtuals))
    return false;

  const auto stamps = chunkTimestamps();
  for (const auto& [uid, title] : candTitles) {
    if (baseTitles.contains(uid))
      continue;

    m_datasetReports.append(QJsonObject{
      {              Keys::UniqueId,                     uid},
      {     QStringLiteral("title"),                   title},
      {QStringLiteral("structural"), QStringLiteral("added")}
    });
  }

  for (const auto& [uid, title] : baseTitles) {
    if (!candTitles.contains(uid)) {
      m_datasetReports.append(QJsonObject{
        {              Keys::UniqueId,                       uid},
        {     QStringLiteral("title"),                     title},
        {QStringLiteral("structural"), QStringLiteral("removed")}
      });
      continue;
    }

    if (baseVirtuals.contains(uid) || candVirtuals.contains(uid)
        || m_virtualDatasets.contains(uid)) {
      m_datasetReports.append(QJsonObject{
        {           Keys::UniqueId,                               uid},
        {  QStringLiteral("title"),                             title},
        {QStringLiteral("skipped"), QStringLiteral("virtual-dataset")}
      });
      continue;
    }

    RegenCursor base, cand;
    if (!base.open(baseDb, baseSession, uid, m_baselineFirstChunk)
        || !cand.open(candDb, candSession, uid, m_candidateFirstChunk))
      return false;

    m_datasetReports.append(diffRegressDataset(title, uid, m_finalsVerifiable, stamps, base, cand));
  }

  return true;
}

int Sessions::Verifier::settleRegressVerdict()
{
  SS_ASSERT_LOG(m_sessionId >= 0);
  SS_ASSERT_LOG(m_options.mode == Mode::Regress);

  bool structural = !m_candidateRemovedDevices.isEmpty();
  bool coverage   = false;
  bool value      = false;
  bool anySkipped = false;

  for (const auto& entryRef : std::as_const(m_datasetReports)) {
    const auto entry = entryRef.toObject();
    if (entry.contains(QStringLiteral("structural")))
      structural = true;

    if (entry.value(QStringLiteral("onlyBaseline")).toInteger() > 0
        || entry.value(QStringLiteral("onlyCandidate")).toInteger() > 0)
      coverage = true;

    if (entry.value(QStringLiteral("changed")).toInteger() > 0)
      value = true;

    if (entry.contains(QStringLiteral("skipped"))
        || (entry.contains(QStringLiteral("finalsCompared"))
            && !entry.value(QStringLiteral("finalsCompared")).toBool()))
      anySkipped = true;
  }

  int code = kExitNotVerifiable;
  if (m_verdict.isEmpty()) {
    const bool drifted = structural || coverage || value;
    m_verdict          = structural ? QStringLiteral("structural-drift")
                       : coverage   ? QStringLiteral("coverage-drift")
                       : value      ? QStringLiteral("value-drift")
                                    : QStringLiteral("identical");
    code               = drifted ? kExitDiverged : kExitReproduced;
  }

  if (anySkipped)
    m_notes.append(QStringLiteral("Some values were skipped because they depend on data "
                                  "that is not stored in the session."));

  if (m_legacyCapture)
    m_notes.append(QStringLiteral("This session was recorded by an older version of "
                                  "Serial Studio, so the comparison is best-effort."));

  for (const int deviceId : std::as_const(m_candidateRemovedDevices))
    m_notes.append(
      QStringLiteral("Recorded device %1 has no matching device in the current project, so "
                     "its data was left out of the comparison.")
        .arg(deviceId));

  QJsonObject candidate;
  candidate.insert(QStringLiteral("path"), m_options.candidateProjectPath);
  if (!m_candidateSha256.isEmpty()) {
    candidate.insert(QStringLiteral("title"), m_candidateTitle);
    candidate.insert(QStringLiteral("sha256"), m_candidateSha256);
  }

  m_report = QJsonObject();
  m_report.insert(QStringLiteral("mode"), QStringLiteral("regression"));
  m_report.insert(QStringLiteral("verdict"), m_verdict);
  m_report.insert(QStringLiteral("archive"), m_options.dbPath);
  m_report.insert(QStringLiteral("sessionId"), m_sessionId);
  m_report.insert(QStringLiteral("appVersion"), QStringLiteral(APP_VERSION));
  m_report.insert(QStringLiteral("captureAppVersion"), m_captureAppVersion);
  m_report.insert(QStringLiteral("legacyCapture"), m_legacyCapture);
  m_report.insert(QStringLiteral("candidate"), candidate);
  m_report.insert(QStringLiteral("replay"), m_replayStats);
  m_report.insert(QStringLiteral("codeChanges"), m_codeChanges);
  m_report.insert(QStringLiteral("baselineReproduction"), latestStoredVerdict());
  m_report.insert(QStringLiteral("datasets"), m_datasetReports);
  m_report.insert(QStringLiteral("notes"), m_notes);

  if (m_options.keepRegenerated && m_regenPaths.size() == 2) {
    m_report.insert(QStringLiteral("baselineDb"), m_regenPaths[0]);
    m_report.insert(QStringLiteral("candidateDb"), m_regenPaths[1]);
  }

  return code;
}

QString Sessions::Verifier::latestStoredVerdict()
{
  QSqlQuery q(m_db);
  q.prepare(QStringLiteral("SELECT verdict FROM verifications WHERE session_id = ? "
                           "ORDER BY verification_id DESC LIMIT 1"));
  q.bindValue(0, m_sessionId);
  if (q.exec() && q.next())
    return q.value(0).toString();

  return QStringLiteral("never-verified");
}

int Sessions::Verifier::failRegress(const QString& code, const QString& reason, const QString& hint)
{
  m_verdict = QStringLiteral("error");
  m_report  = QJsonObject{
     {     QStringLiteral("mode"), QStringLiteral("regression")},
     {  QStringLiteral("verdict"),                    m_verdict},
     {    QStringLiteral("error"),                       reason},
     {QStringLiteral("errorCode"),                         code},
     {     QStringLiteral("hint"),                         hint},
     {  QStringLiteral("archive"),             m_options.dbPath},
     {QStringLiteral("sessionId"),                  m_sessionId}
  };
  cleanupRegenerated();
  return kExitError;
}

id TstGsUsbProtocol::dlcToLengthTable()
{
  const int expected[16] = {0, 1, 2, 3, 4, 5, 6, 7, 8, 12, 16, 20, 24, 32, 48, 64};
  for (int dlc = 0; dlc < 16; ++dlc)
    QCOMPARE(dlc2len(static_cast<std::uint8_t>(dlc)), expected[dlc]);

  QCOMPARE(dlc2len(static_cast<std::uint8_t>(0xFF)), 64);
}

id TstGsUsbProtocol::lengthToDlcRoundsUp()
{
  QCOMPARE(dlc2len(len2dlc(0)), 0);
  QCOMPARE(dlc2len(len2dlc(8)), 8);
  QCOMPARE(dlc2len(len2dlc(9)), 12);
  QCOMPARE(dlc2len(len2dlc(13)), 16);
  QCOMPARE(dlc2len(len2dlc(20)), 20);
  QCOMPARE(dlc2len(len2dlc(21)), 24);
  QCOMPARE(dlc2len(len2dlc(49)), 64);
  QCOMPARE(dlc2len(len2dlc(64)), 64);
  QCOMPARE(dlc2len(len2dlc(-3)), 0);
  QCOMPARE(dlc2len(len2dlc(1000)), 64);
}

id TstGsUsbProtocol::dlcRoundTrip()
{
  for (int dlc = 0; dlc < 16; ++dlc) {
    const int length = dlc2len(static_cast<std::uint8_t>(dlc));
    QCOMPARE(len2dlc(length), static_cast<std::uint8_t>(dlc));
  }
}

id TstGsUsbProtocol::classicTimingIsPinned_data()
{
  QTest::addColumn<quint32>("bitrate");
  QTest::addColumn<quint32>("brp");
  QTest::addColumn<quint32>("propSeg");
  QTest::addColumn<quint32>("phaseSeg1");
  QTest::addColumn<quint32>("phaseSeg2");
  QTest::addColumn<quint32>("sjw");

  QTest::newRow("10k") << 10000u << 240u << 8u << 8u << 3u << 3u;
  QTest::newRow("20k") << 20000u << 120u << 8u << 8u << 3u << 3u;
  QTest::newRow("50k") << 50000u << 48u << 8u << 8u << 3u << 3u;
  QTest::newRow("100k") << 100000u << 24u << 8u << 8u << 3u << 3u;
  QTest::newRow("125k") << 125000u << 24u << 7u << 6u << 2u << 2u;
  QTest::newRow("250k") << 250000u << 12u << 7u << 6u << 2u << 2u;
  QTest::newRow("500k") << 500000u << 6u << 7u << 6u << 2u << 2u;
  QTest::newRow("800k") << 800000u << 3u << 8u << 8u << 3u << 3u;
  QTest::newRow("1M") << 1000000u << 3u << 7u << 6u << 2u << 2u;
}

id TstGsUsbProtocol::classicTimingIsPinned()
{
  QFETCH(quint32, bitrate);
  QFETCH(quint32, brp);
  QFETCH(quint32, propSeg);
  QFETCH(quint32, phaseSeg1);
  QFETCH(quint32, phaseSeg2);
  QFETCH(quint32, sjw);

  GsDeviceBitTiming timing{};
  QVERIFY(solveBitTiming(kClassicLimits, bitrate, timing));
  QCOMPARE(timing.brp, brp);
  QCOMPARE(timing.propSeg, propSeg);
  QCOMPARE(timing.phaseSeg1, phaseSeg1);
  QCOMPARE(timing.phaseSeg2, phaseSeg2);
  QCOMPARE(timing.sjw, sjw);
}

id TstGsUsbProtocol::fdDataTimingSolves_data()
{
  QTest::addColumn<quint32>("bitrate");

  QTest::newRow("1M") << 1000000u;
  QTest::newRow("2M") << 2000000u;
  QTest::newRow("4M") << 4000000u;
  QTest::newRow("5M") << 5000000u;
  QTest::newRow("8M") << 8000000u;
}

id TstGsUsbProtocol::fdDataTimingSolves()
{
  QFETCH(quint32, bitrate);

  const GsDeviceBtConst limits = timingLimits(kFdLimits, true);
  GsDeviceBitTiming timing{};
  QVERIFY(solveBitTiming(limits, bitrate, timing));

  QVERIFY(timing.brp >= limits.brpMin && timing.brp <= limits.brpMax);
  const quint32 tseg1 = timing.propSeg + timing.phaseSeg1;
  QVERIFY(tseg1 >= limits.tseg1Min && tseg1 <= limits.tseg1Max);
  QVERIFY(timing.phaseSeg2 >= limits.tseg2Min && timing.phaseSeg2 <= limits.tseg2Max);
  QVERIFY(timing.sjw >= 1 && timing.sjw <= limits.sjwMax);

  const quint32 total = 1 + tseg1 + timing.phaseSeg2;
  QCOMPARE(limits.fclkCan / (timing.brp * total), bitrate);
  QCOMPARE(limits.fclkCan % (timing.brp * total), 0u);
}

id TstGsUsbProtocol::timingLimitsSelectsPhase()
{
  const GsDeviceBtConst nominal = timingLimits(kFdLimits, false);
  QCOMPARE(nominal.fclkCan, kFdLimits.fclkCan);
  QCOMPARE(nominal.tseg1Max, kFdLimits.tseg1Max);
  QCOMPARE(nominal.brpMax, kFdLimits.brpMax);

  const GsDeviceBtConst data = timingLimits(kFdLimits, true);
  QCOMPARE(data.fclkCan, kFdLimits.fclkCan);
  QCOMPARE(data.tseg1Max, kFdLimits.dtseg1Max);
  QCOMPARE(data.tseg2Max, kFdLimits.dtseg2Max);
  QCOMPARE(data.sjwMax, kFdLimits.dsjwMax);
  QCOMPARE(data.brpMax, kFdLimits.dbrpMax);
}

id TstGsUsbProtocol::solverRejectsImpossibleRates()
{
  GsDeviceBitTiming timing{};
  QVERIFY(!solveBitTiming(kClassicLimits, 0, timing));

  GsDeviceBtConst dead = kClassicLimits;
  dead.fclkCan         = 0;
  QVERIFY(!solveBitTiming(dead, 500000, timing));

  QVERIFY(!solveBitTiming(kClassicLimits, 48000000, timing));

  GsDeviceBtConst hostile = kClassicLimits;
  hostile.brpMax          = 0xFFFFFFFFu;
  hostile.brpInc          = 0;
  QVERIFY(!solveBitTiming(hostile, 999983, timing));

  GsDeviceBtConst inverted = kClassicLimits;
  inverted.brpMin          = 10;
  inverted.brpMax          = 5;
  QVERIFY(!solveBitTiming(inverted, 500000, timing));

  GsDeviceBtConst wrap = kClassicLimits;
  QVERIFY(!solveBitTiming(wrap, 0xFFFFFFF0u, timing));
}

atic QVariantMap wrapResponse(const API::CommandResponse& response)
{
  QVariantMap out;
  out.insert(QStringLiteral("ok"), response.success);
  if (response.success) {
    if (!response.result.isEmpty())
      out.insert(QStringLiteral("result"), response.result.toVariantMap());
  } else {
    out.insert(QStringLiteral("error"), response.errorMessage);
    out.insert(QStringLiteral("errorCode"), response.errorCode);
    if (!response.errorData.isEmpty())
      out.insert(QStringLiteral("errorData"), response.errorData.toVariantMap());
  }

  return out;
}

atic QVariantMap localError(const QString& message, const char* code)
{
  QVariantMap out;
  out.insert(QStringLiteral("ok"), false);
  out.insert(QStringLiteral("error"), message);
  out.insert(QStringLiteral("errorCode"), QString::fromLatin1(code));
  return out;
}

ariantMap API::TerminalBridge::run(const QString& input)
{
  const QString line = input.trimmed();
  if (line.isEmpty())
    return localError(tr("Empty command line"), ErrorCode::InvalidMessageType);

  qsizetype split = -1;
  for (qsizetype i = 0; i < line.size(); ++i) {
    if (line.at(i).isSpace()) {
      split = i;
      break;
    }
  }

  const QString command   = (split < 0) ? line : line.left(split);
  const QString params_in = (split < 0) ? QString() : line.mid(split + 1).trimmed();

  QJsonObject params;
  if (!params_in.isEmpty()) {
    QJsonParseError parse_error;
    const auto doc = QJsonDocument::fromJson(params_in.toUtf8(), &parse_error);
    if (parse_error.error != QJsonParseError::NoError)
      return localError(tr("Invalid parameter JSON: %1").arg(parse_error.errorString()),
                        ErrorCode::InvalidJson);

    if (!doc.isObject())
      return localError(tr("Parameters must be a JSON object"), ErrorCode::InvalidJson);

    params = doc.object();
  }

  CommandRequest request;
  request.id      = QUuid::createUuid().toString(QUuid::WithoutBraces);
  request.command = command;
  request.params  = params;
  SS_ASSERT(request.isValid(),
            return localError(tr("Empty command line"), ErrorCode::InvalidMessageType));

  try {
    return wrapResponse(m_handler.processCommand(request));
  } catch (const std::exception& e) {
    return localError(QString::fromUtf8(e.what()), ErrorCode::ExecutionError);
  } catch (...) {
    return localError(tr("Unknown exception while executing command"), ErrorCode::ExecutionError);
  }
}

ariantList API::TerminalBridge::catalog() const
{
  QVariantList out;
  const auto& commands = m_registry.commands();
  out.reserve(commands.size());

  for (auto it = commands.constBegin(); it != commands.constEnd(); ++it) {
    const auto& definition = it.value();
    SS_ASSERT_LOG(!definition.name.isEmpty());
    if (definition.name.isEmpty())
      continue;

    const qsizetype dot = definition.name.indexOf(QLatin1Char('.'));
    QVariantMap entry;
    entry.insert(QStringLiteral("name"), definition.name);
    entry.insert(QStringLiteral("scope"), (dot < 0) ? QString() : definition.name.left(dot));
    entry.insert(QStringLiteral("verb"),
                 (dot < 0) ? definition.name : definition.name.mid(dot + 1));
    entry.insert(QStringLiteral("description"), definition.description);

    const auto properties = definition.inputSchema.value(QStringLiteral("properties")).toObject();
    const auto required   = definition.inputSchema.value(QStringLiteral("required")).toArray();
    QVariantList params;
    for (auto prop = properties.constBegin(); prop != properties.constEnd(); ++prop) {
      const auto schema = prop.value().toObject();
      QVariantMap param;
      param.insert(QStringLiteral("name"), prop.key());
      param.insert(QStringLiteral("type"), schema.value(QStringLiteral("type")).toString());
      param.insert(QStringLiteral("description"),
                   schema.value(QStringLiteral("description")).toString());
      param.insert(QStringLiteral("required"), required.contains(QJsonValue(prop.key())));
      params.append(param);
    }

    entry.insert(QStringLiteral("params"), params);
    out.append(entry);
  }

  return out;
}

DataModel::MacroEditor::MacroEditor(QQuickItem* parent)
  : QQuickPaintedItem(parent)
  , m_language(0)
  , m_themeManager(Misc::ThemeManager::instance())
  , m_commonFonts(Misc::CommonFonts::instance())
  , m_timerEvents(Misc::TimerEvents::instance())
{
  setMipmap(false);
  setAntialiasing(false);
  setOpaquePainting(true);
  setAcceptTouchEvents(true);
  setFlag(ItemHasContents, true);
  setFlag(ItemIsFocusScope, true);
  setFlag(ItemAcceptsInputMethod, true);
  setAcceptedMouseButtons(Qt::AllButtons);
  setFillColor(m_themeManager.getColor(QStringLiteral("base")));

  m_widget.setTabReplace(true);
  m_widget.setTabReplaceSize(2);
  m_widget.setAutoIndentation(true);
  m_widget.setHighlighter(new QJavascriptHighlighter());
  m_widget.setFont(m_commonFonts.monoFont());
  m_widget.setLayoutDirection(Qt::LeftToRight);
  m_widget.setLanguageHint(QCodeEditor::LanguageHint::JavaScript);
  m_widget.setCompleter(new DataModel::SerialStudioCompleter(false, &m_widget));

  onThemeChanged();
  connect(&m_themeManager,
          &Misc::ThemeManager::themeChanged,
          this,
          &DataModel::MacroEditor::onThemeChanged);

  connect(&m_widget, &QCodeEditor::textChanged, this, [this] { Q_EMIT modifiedChanged(); });
  connect(&m_widget, &QCodeEditor::textChanged, this, &DataModel::MacroEditor::textChanged);

  connect(this, &QQuickPaintedItem::widthChanged, this, &DataModel::MacroEditor::resizeWidget);
  connect(this, &QQuickPaintedItem::heightChanged, this, &DataModel::MacroEditor::resizeWidget);
  connect(
    &m_timerEvents, &Misc::TimerEvents::uiTimeout, this, &DataModel::MacroEditor::renderWidget);
}

bool DataModel::MacroEditor::isModified() const noexcept
{
  if (m_widget.document())
    return m_widget.document()->isModified();

  return false;
}

void DataModel::MacroEditor::clear()
{
  m_widget.setPlainText(QString());
  m_widget.document()->clearUndoRedoStacks();
  m_widget.document()->setModified(false);
  Q_EMIT modifiedChanged();
}

void DataModel::MacroEditor::setLanguage(int language)
{
  if (m_language == language)
    return;

  m_language            = language;
  auto* old_completer   = m_widget.completer();
  auto* old_highlighter = m_widget.highlighter();

  if (language == SerialStudio::Lua) {
    m_widget.setHighlighter(new QLuaHighlighter());
    m_widget.setLanguageHint(QCodeEditor::LanguageHint::Lua);
    m_widget.setCompleter(new DataModel::SerialStudioCompleter(true, &m_widget));
  } else {
    m_widget.setHighlighter(new QJavascriptHighlighter());
    m_widget.setLanguageHint(QCodeEditor::LanguageHint::JavaScript);
    m_widget.setCompleter(new DataModel::SerialStudioCompleter(false, &m_widget));
  }

  if (old_completer)
    old_completer->deleteLater();

  if (old_highlighter)
    old_highlighter->deleteLater();

  Q_EMIT languageChanged();
  renderWidget();
}

void DataModel::MacroEditor::setText(const QString& text)
{
  if (m_widget.toPlainText() != text)
    m_widget.setPlainText(text);

  m_widget.document()->clearUndoRedoStacks();
  m_widget.document()->setModified(false);
  Q_EMIT modifiedChanged();
  renderWidget();
}

void DataModel::MacroEditor::markSaved()
{
  m_widget.document()->setModified(false);
  Q_EMIT modifiedChanged();
}

void DataModel::MacroEditor::onThemeChanged()
{
  static const auto* t = &Misc::ThemeManager::instance();
  const auto name      = t->parameters().value(QStringLiteral("code-editor-theme")).toString();

  const auto path =
    QDir::isAbsolutePath(name) ? name : QStringLiteral(":/themes/code-editor/%1.xml").arg(name);

  QFile file(path);
  if (file.open(QFile::ReadOnly)) {
    m_style.load(QString::fromUtf8(file.readAll()));
    m_widget.setSyntaxStyle(&m_style);
    file.close();
  }
}

void DataModel::MacroEditor::renderWidget()
{
  if (isVisible()) {
    syncWidgetPosition();
    m_pixmap = m_widget.grab();
    update();
  }
}

void DataModel::MacroEditor::syncWidgetPosition()
{
  if (!window())
    return;

  const QPoint global = mapToGlobal(QPointF(0, 0)).toPoint();
  if (m_widget.pos() != global)
    m_widget.move(global);
}

void DataModel::MacroEditor::resizeWidget()
{
  if (width() > 0 && height() > 0) {
    m_widget.setFixedSize(static_cast<int>(width()), static_cast<int>(height()));
    renderWidget();
  }
}

void DataModel::MacroEditor::paint(QPainter* painter)
{
  if (painter && isVisible())
    painter->drawPixmap(0, 0, m_pixmap);
}

bool DataModel::MacroEditor::event(QEvent* event)
{
  if (event->type() == QEvent::ShortcutOverride) {
    QCoreApplication::sendEvent(&m_widget, event);
    if (event->isAccepted())
      return true;
  }

  return QQuickPaintedItem::event(event);
}

void DataModel::MacroEditor::keyPressEvent(QKeyEvent* event)
{
  auto* completer = m_widget.completer();
  if (completer && completer->popup() && completer->popup()->isVisible()
      && SerialStudioCompleter::popupHandlesKey(event->key()))
    QCoreApplication::sendEvent(completer->popup(), event);
  else
    QCoreApplication::sendEvent(&m_widget, event);

  renderWidget();
}

void DataModel::MacroEditor::inputMethodEvent(QInputMethodEvent* event)
{
  QCoreApplication::sendEvent(&m_widget, event);
  renderWidget();
}

void DataModel::MacroEditor::mousePressEvent(QMouseEvent* event)
{
  const auto lineNumWidth = m_widget.lineNumberArea()->sizeHint().width();
  QMouseEvent copy(event->type(),
                   event->position() - QPointF(lineNumWidth, 0),
                   event->globalPosition(),
                   event->button(),
                   event->buttons(),
                   event->modifiers(),
                   event->pointingDevice());
  QCoreApplication::sendEvent(m_widget.viewport(), &copy);
  forceActiveFocus();
  renderWidget();
