static int macroLuaPanic(lua_State* L)
{
  const char* msg = lua_tostring(L, -1);
  throw std::runtime_error(msg ? msg : "lua panic");
}

static MacroLuaContext* macroLuaContext(lua_State* L)
{
  lua_getfield(L, LUA_REGISTRYINDEX, "__ss_macro_ctx__");
  auto* ctx = static_cast<MacroLuaContext*>(lua_touserdata(L, -1));
  lua_pop(L, 1);
  return ctx;
}

static void macroLuaHook(lua_State* L, lua_Debug* ar)
{
  Q_UNUSED(ar)

  auto* ctx = macroLuaContext(L);
  if (!ctx) [[unlikely]]
    return;

  if (ctx->deadline.hasExpired()) [[unlikely]]
    luaL_error(L, "macro exceeded the %d ms safety deadline", kLuaDeadlineMs);
}

static int macroLuaPrint(lua_State* L)
{
  auto* ctx = macroLuaContext(L);
  if (!ctx || !ctx->runner)
    return 0;

  QStringList parts;
  const int argc = lua_gettop(L);
  for (int i = 1; i <= argc; ++i) {
    const char* text = luaL_tolstring(L, i, nullptr);
    parts.append(QString::fromUtf8(text ? text : ""));
    lua_pop(L, 1);
  }

  ctx->runner->postLog(parts.join(QStringLiteral("\t")));
  return 0;
}

DataModel::MacroRunner::MacroRunner(QObject* parent)
  : QObject(parent)
  , m_busy(false)
  , m_jsRunning(false)
  , m_thread(nullptr)
  , m_worker(nullptr)
  , m_marshaller(nullptr)
  , m_frameBuilder(DataModel::FrameBuilder::instance())
{
  m_thread     = new QThread;
  m_marshaller = new ControlApiMarshaller(this);
  m_worker     = new MacroWorker(m_marshaller);
  m_worker->moveToThread(m_thread);

  connect(m_thread, &QThread::finished, m_worker, &QObject::deleteLater);
  connect(m_worker, &MacroWorker::finished, this, &MacroRunner::onWorkerFinished);
  connect(m_worker, &MacroWorker::scriptError, this, &MacroRunner::onWorkerError);
  connect(m_worker, &MacroWorker::logMessage, this, &MacroRunner::logMessage);

  m_thread->start();
}

DataModel::MacroRunner::~MacroRunner()
{
  if (m_worker)
    m_worker->requestTeardown();

  m_thread->quit();
  for (int i = 0; i < kShutdownWaitSlices; ++i) {
    if (m_thread->wait(kShutdownWaitSliceMs))
      break;

    if (qApp)
      QCoreApplication::sendPostedEvents(m_marshaller);
  }

  if (m_thread->isRunning()) {
    qWarning() << "[MacroRunner] Worker thread did not stop within the shutdown budget";
    m_marshaller->setParent(nullptr);
    connect(m_thread, &QThread::finished, m_thread, &QObject::deleteLater);
    return;
  }

  delete m_thread;
}

void DataModel::MacroRunner::runJs(const QString& source)
{
  if (m_busy)
    return;

  m_worker->resetStop();
  m_busy      = true;
  m_jsRunning = true;
  Q_EMIT busyChanged();

  const bool queued =
    QMetaObject::invokeMethod(m_worker, "run", Qt::QueuedConnection, Q_ARG(QString, source));
  SS_ASSERT(queued, {
    m_busy      = false;
    m_jsRunning = false;
    Q_EMIT busyChanged();
    Q_EMIT scriptError(tr("Failed to queue the macro onto the worker thread"));
    return;
  });
}

void DataModel::MacroRunner::runLua(const QString& source)
{
  if (m_busy)
    return;

  if (source.trimmed().isEmpty()) {
    Q_EMIT scriptError(tr("Macro is empty"));
    return;
  }

  m_busy      = true;
  m_jsRunning = false;
  Q_EMIT busyChanged();

  lua_State* state = luaL_newstate();
  SS_ASSERT(state != nullptr, {
    m_busy = false;
    Q_EMIT busyChanged();
    Q_EMIT scriptError(tr("Failed to create the Lua state"));
    return;
  });

  lua_atpanic(state, macroLuaPanic);

  MacroLuaContext context;
  context.runner   = this;
  context.deadline = QDeadlineTimer(kLuaDeadlineMs);

  QString error;
  QString result;
  bool ok = false;
  try {
    luaL_openlibs(state);
    DataModel::installLuaConsole(state);
    DataModel::installLuaCompat(state);
    DataModel::ScriptApiCall::installAll(state, 0);

    lua_pushlightuserdata(state, &context);
    lua_setfield(state, LUA_REGISTRYINDEX, "__ss_macro_ctx__");
    lua_pushcfunction(state, macroLuaPrint);
    lua_setglobal(state, "print");
    lua_sethook(state, macroLuaHook, LUA_MASKCOUNT, kLuaHookInstructions);

    const QByteArray utf8 = source.toUtf8();
    if (luaL_loadbuffer(state, utf8.constData(), static_cast<size_t>(utf8.size()), "macro")
        != LUA_OK) {
      const char* msg = lua_tostring(state, -1);
      error           = QString::fromUtf8(msg ? msg : "syntax error");
    } else if (lua_pcall(state, 0, LUA_MULTRET, 0) != LUA_OK) {
      const char* msg = lua_tostring(state, -1);
      error           = QString::fromUtf8(msg ? msg : "runtime error");
    } else {
      ok = true;
    }

    if (ok && lua_gettop(state) > 0) {
      const char* text = luaL_tolstring(state, 1, nullptr);
      result           = QString::fromUtf8(text ? text : "");
      lua_pop(state, 1);
    }
  } catch (const std::exception& e) {
    ok    = false;
    error = QString::fromUtf8(e.what());
  } catch (...) {
    ok    = false;
    error = tr("Unknown Lua error");
  }

  closeMacroLuaState(state);

  m_busy = false;
  Q_EMIT busyChanged();
  if (ok)
    Q_EMIT finished(result);
  else
    Q_EMIT scriptError(error);
}

void DataModel::MacroRunner::stop()
{
  if (m_worker && canStop())
    m_worker->requestStop();
}

QVariantMap DataModel::MacroRunner::verifyJs(const QString& source) const
{
  QJSEngine engine;
  const QJSValue result =
    engine.evaluate(QStringLiteral("(function() {\n%1\n})").arg(source), QStringLiteral("macro"));

  QVariantMap out;
  out.insert(QStringLiteral("ok"), !result.isError());
  if (result.isError()) {
    const int source_lines = static_cast<int>(source.count(QLatin1Char('\n'))) + 1;
    const int line         = result.property(QStringLiteral("lineNumber")).toInt() - 1;
    out.insert(QStringLiteral("line"), qBound(1, line, source_lines));
    out.insert(QStringLiteral("error"), result.toString());
  }

  return out;
}

QVariantMap DataModel::MacroRunner::verifyLua(const QString& source) const
{
  QVariantMap out;
  lua_State* state = luaL_newstate();
  SS_ASSERT(state != nullptr, {
    out.insert(QStringLiteral("ok"), false);
    out.insert(QStringLiteral("error"), tr("Failed to create the Lua state"));
    return out;
  });

  const QByteArray utf8 = source.toUtf8();
  const int status =
    luaL_loadbuffer(state, utf8.constData(), static_cast<size_t>(utf8.size()), "macro");

  out.insert(QStringLiteral("ok"), status == LUA_OK);
  if (status != LUA_OK) {
    const char* msg     = lua_tostring(state, -1);
    const QString error = QString::fromUtf8(msg ? msg : "syntax error");
    out.insert(QStringLiteral("error"), error);

    static const QRegularExpression line_re(QStringLiteral(":(\\d+):"));
    const auto match = line_re.match(error);
    if (match.hasMatch())
      out.insert(QStringLiteral("line"), match.captured(1).toInt());
  }

  lua_close(state);
  return out;
}

QString DataModel::MacroRunner::macrosDirectory() const
{
  const QString base = QStandardPaths::writableLocation(QStandardPaths::AppDataLocation);
  const QString dir  = base + QStringLiteral("/Macros");
  QDir().mkpath(dir);
  return dir;
}

void DataModel::MacroRunner::loadMacro()
{
  auto* dialog = new QFileDialog(
    nullptr, tr("Select macro to load"), macrosDirectory(), QStringLiteral("*.js *.lua"));
  dialog->setFileMode(QFileDialog::ExistingFile);
  dialog->setAttribute(Qt::WA_DeleteOnClose);

  connect(dialog, &QFileDialog::fileSelected, this, [this](const QString& path) {
    if (path.isEmpty())
      return;

    QMetaObject::invokeMethod(
      this,
      [this, path]() {
        QFile file(path);
        if (!file.open(QFile::ReadOnly)) {
          Q_EMIT scriptError(tr("Cannot open %1").arg(path));
          return;
        }

        const int language = path.endsWith(QStringLiteral(".lua"), Qt::CaseInsensitive)
                             ? SerialStudio::Lua
                             : SerialStudio::JavaScript;
        Q_EMIT macroLoaded(QString::fromUtf8(file.readAll()), language, QFileInfo(path).fileName());
      },
      Qt::QueuedConnection);
  });

  dialog->open();
}

void DataModel::MacroRunner::saveMacro(const QString& source, int language)
{
  const bool lua = (language == SerialStudio::Lua);
  auto* dialog   = new QFileDialog(nullptr,
                                 tr("Save macro"),
                                 macrosDirectory(),
                                 lua ? QStringLiteral("*.lua") : QStringLiteral("*.js"));
  dialog->setAcceptMode(QFileDialog::AcceptSave);
  dialog->setDefaultSuffix(lua ? QStringLiteral("lua") : QStringLiteral("js"));
  dialog->setAttribute(Qt::WA_DeleteOnClose);

  connect(dialog, &QFileDialog::fileSelected, this, [this, source](const QString& path) {
    if (path.isEmpty())
      return;

    QMetaObject::invokeMethod(
      this,
      [this, source, path]() {
        QSaveFile file(path);
        if (!file.open(QFile::WriteOnly | QFile::Truncate)) {
          Q_EMIT scriptError(tr("Cannot write %1").arg(path));
          return;
        }

        const QByteArray payload = source.toUtf8();
        if (file.write(payload) != payload.size() || !file.commit()) {
          Q_EMIT scriptError(tr("Failed to save %1: %2").arg(path, file.errorString()));
          return;
        }

        Q_EMIT macroSaved(QFileInfo(path).fileName());
      },
      Qt::QueuedConnection);
  });

  dialog->open();
}

void DataModel::MacroRunner::onWorkerFinished(const QString& result)
{
  m_busy      = false;
  m_jsRunning = false;
  Q_EMIT busyChanged();
  Q_EMIT finished(result);
}

void DataModel::MacroRunner::onWorkerError(const QString& message)
{
  m_busy      = false;
  m_jsRunning = false;
  Q_EMIT busyChanged();
  Q_EMIT scriptError(message);
}

void DataModel::MacroRunner::closeMacroLuaState(lua_State* state)
{
  if (!state)
    return;

  m_frameBuilder.tableStore().clearLookupCache();
  lua_close(state);
}

DataModel::MacroApiBridge::MacroApiBridge(ControlApiMarshaller* marshaller,
                                          const std::atomic<bool>* stopFlag,
                                          QObject* parent)
  : QObject(parent)
  , m_marshaller(marshaller)
  , m_watchdog(nullptr)
  , m_stop(stopFlag)
  , m_registry(API::CommandRegistry::instance())
{
  SS_ASSERT_LOG(marshaller != nullptr);
  SS_ASSERT_LOG(stopFlag != nullptr);
}

QVariantMap DataModel::MacroApiBridge::call(const QString& method, const QVariantMap& params)
{
  QVariantMap out;
  if (method.isEmpty()) {
    out.insert(QStringLiteral("ok"), false);
    out.insert(QStringLiteral("error"), QStringLiteral("apiCall: method must not be empty"));
    return out;
  }

  if (stopRequested()) {
    out.insert(QStringLiteral("ok"), false);
    out.insert(QStringLiteral("error"), QStringLiteral("apiCall: macro stop requested"));
    return out;
  }

  const bool ok = QMetaObject::invokeMethod(m_marshaller,
                                            "dispatch",
                                            Qt::BlockingQueuedConnection,
                                            Q_RETURN_ARG(QVariantMap, out),
                                            Q_ARG(QString, method),
                                            Q_ARG(QVariantMap, params));
  if (m_watchdog && !stopRequested())
    m_watchdog->arm();

  if (!ok) {
    out.insert(QStringLiteral("ok"), false);
    out.insert(QStringLiteral("error"), QStringLiteral("apiCall: GUI dispatch failed"));
  }

  return out;
}

QVariantList DataModel::MacroApiBridge::listCommands()
{
  QVariantList result;
  const auto& commands = m_registry.commands();
  result.reserve(commands.size());
  for (auto it = commands.constBegin(); it != commands.constEnd(); ++it)
    result.append(it.key());

  return result;
}

QVariantMap DataModel::MacroApiBridge::writeAndWait(const QJSValue& data,
                                                    int timeoutMs,
                                                    const QJSValue& until,
                                                    int sourceId)
{
  QVariantMap out;
  out.insert(QStringLiteral("ok"), false);
  out.insert(QStringLiteral("data"), QString());
  out.insert(QStringLiteral("bytesRead"), 0);
  out.insert(QStringLiteral("timedOut"), false);

  QByteArray payload;
  if (data.isString()) {
    payload = data.toString().toUtf8();
  } else if (data.isArray()) {
    const int len = data.property(QStringLiteral("length")).toInt();
    payload.reserve(len);
    for (int i = 0; i < len; ++i)
      payload.append(static_cast<char>(data.property(static_cast<quint32>(i)).toInt() & 0xff));
  }

  if (sourceId < 0 || payload.isEmpty()) {
    out.insert(QStringLiteral("error"), QStringLiteral("deviceWriteAndWait: bad source or data"));
    return out;
  }

  if (stopRequested()) {
    out.insert(QStringLiteral("error"), QStringLiteral("deviceWriteAndWait: macro stop requested"));
    return out;
  }

  QByteArray terminator;
  int expectedLen = 0;
  if (until.isString())
    terminator = until.toString().toUtf8();
  else if (until.isNumber())
    expectedLen = until.toInt();

  qint64 written = -1;
  QMetaObject::invokeMethod(m_marshaller,
                            "writeAndArm",
                            Qt::BlockingQueuedConnection,
                            Q_RETURN_ARG(qint64, written),
                            Q_ARG(int, sourceId),
                            Q_ARG(QByteArray, payload));

  if (written <= 0) {
    QMetaObject::invokeMethod(
      m_marshaller, "disarmReply", Qt::BlockingQueuedConnection, Q_ARG(int, sourceId));
    out.insert(QStringLiteral("error"), QStringLiteral("deviceWriteAndWait: write failed"));
    if (m_watchdog && !stopRequested())
      m_watchdog->arm();

    return out;
  }

  const auto satisfies = [&](const QByteArray& reply) {
    if (!terminator.isEmpty())
      return reply.contains(terminator);

    if (expectedLen > 0)
      return reply.size() >= expectedLen;

    return !reply.isEmpty();
  };

  const int budget = qBound(0, timeoutMs, kMaxReplyWaitMs);
  QByteArray reply;
  bool satisfied = false;
  for (int waited = 0; waited <= budget && !satisfied; waited += kReplyPollSliceMs) {
    if (stopRequested())
      break;

    QThread::msleep(static_cast<unsigned long>(kReplyPollSliceMs));
    QMetaObject::invokeMethod(m_marshaller,
                              "pollReply",
                              Qt::BlockingQueuedConnection,
                              Q_RETURN_ARG(QByteArray, reply),
                              Q_ARG(int, sourceId));
    satisfied = satisfies(reply);
  }

  QMetaObject::invokeMethod(
    m_marshaller, "disarmReply", Qt::BlockingQueuedConnection, Q_ARG(int, sourceId));

  if (m_watchdog && !stopRequested())
    m_watchdog->arm();

  out.insert(QStringLiteral("ok"), satisfied);
  out.insert(QStringLiteral("data"), QString::fromUtf8(reply));
  out.insert(QStringLiteral("bytesRead"), reply.size());
  out.insert(QStringLiteral("timedOut"), !satisfied);
  return out;
}

void DataModel::MacroApiBridge::delay(int milliseconds)
{
  const int total = qBound(0, milliseconds, kMacroMaxDelayMs);
  for (int slept = 0; slept < total; slept += kMacroDelaySliceMs) {
    if (stopRequested())
      return;

    QThread::msleep(static_cast<unsigned long>(qMin(kMacroDelaySliceMs, total - slept)));
  }

  if (m_watchdog && !stopRequested())
    m_watchdog->arm();
}

DataModel::MacroWorker::MacroWorker(ControlApiMarshaller* marshaller, QObject* parent)
  : QObject(parent)
  , m_teardown(false)
  , m_bridge(nullptr)
  , m_stopRequested(false)
  , m_marshaller(marshaller)
{
  SS_ASSERT_LOG(marshaller != nullptr);
}

void DataModel::MacroWorker::requestTeardown() noexcept
{
  m_teardown.store(true, std::memory_order_release);
  m_stopRequested.store(true, std::memory_order_release);
}

void DataModel::MacroWorker::run(const QString& source)
{
  if (m_teardown.load(std::memory_order_acquire))
    return;

  if (source.trimmed().isEmpty()) {
    Q_EMIT scriptError(QStringLiteral("Macro is empty"));
    return;
  }

  m_engine = std::make_unique<QJSEngine>();
  m_engine->installExtensions(QJSEngine::ConsoleExtension | QJSEngine::GarbageCollectionExtension);
  m_watchdog = std::make_unique<DataModel::JsWatchdog>(
    m_engine.get(), kMacroWatchdogMs, QStringLiteral("Macro"));

  m_bridge = new MacroApiBridge(m_marshaller, &m_stopRequested, m_engine.get());
  m_bridge->setWatchdog(m_watchdog.get());
  connect(m_bridge, &MacroApiBridge::logMessage, this, &MacroWorker::logMessage);

  auto bridge_value = m_engine->newQObject(m_bridge);
  m_engine->globalObject().setProperty(QStringLiteral("__ss_bridge"), bridge_value);
  m_engine->globalObject().setProperty(QStringLiteral("__ss_control"), QJSValue(true));

  QFile sdk_file(QStringLiteral(":/api/SerialStudio.js"));
  if (sdk_file.open(QFile::ReadOnly))
    m_engine->evaluate(QString::fromUtf8(sdk_file.readAll()));

  m_engine->evaluate(QStringLiteral("(function() {"
                                    "  var ssLog = function() {"
                                    "    var parts = [];"
                                    "    for (var i = 0; i < arguments.length; ++i)"
                                    "      parts.push(String(arguments[i]));"
                                    "    __ss_bridge.log(parts.join(' '));"
                                    "  };"
                                    "  console.log = ssLog;"
                                    "  console.info = ssLog;"
                                    "  console.warn = ssLog;"
                                    "  console.error = ssLog;"
                                    "  globalThis.print = ssLog;"
                                    "})();"));

  m_watchdog->arm();
  const QJSValue result = m_engine->evaluate(source, QStringLiteral("macro.js"));
  m_watchdog->disarm();

  if (m_engine->isInterrupted()) {
    m_engine->setInterrupted(false);
    const bool stopped = m_stopRequested.load(std::memory_order_acquire);
    Q_EMIT scriptError(stopped
                         ? QStringLiteral("Macro stopped by user")
                         : QStringLiteral("Macro exceeded the %1 ms script budget between API "
                                          "calls and was interrupted")
                             .arg(kMacroWatchdogMs));
    releaseEngine();
    return;
  }

  if (result.isError()) {
    Q_EMIT scriptError(QStringLiteral("Line %1: %2")
                         .arg(result.property(QStringLiteral("lineNumber")).toInt())
                         .arg(result.toString()));
    releaseEngine();
    return;
  }

  Q_EMIT finished(result.isUndefined() || result.isNull() ? QString() : result.toString());
  releaseEngine();
}

void DataModel::MacroWorker::releaseEngine()
{
  m_bridge = nullptr;
  m_watchdog.reset();
  m_engine.reset();
}

