/**
 * @brief Remembered token for @p endpoint, empty when none was stored. Stored plaintext in the
 *        application settings, the same protection the publisher gives its own token.
 */
QString API::MirrorSession::tokenFor(const QString& endpoint) const
{
  const auto map = m_settings.value(QStringLiteral("Mirror/EndpointTokens")).toMap();
  return map.value(endpoint).toString();
}

API::CommandResponse API::Handlers::SessionsHandler::verify(const QString& id,
                                                            const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("sessionId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: sessionId"));

  static auto& db = Sessions::DatabaseManager::instance();
  if (!db.isOpen())
    return CommandResponse::makeError(
      id,
      ErrorCode::ExecutionError,
      QStringLiteral("No database open. Call sessions.openDatabase first."));

  if (db.verificationBusy())
    return CommandResponse::makeError(
      id, ErrorCode::ExecutionError, QStringLiteral("A verification is already running."));

  const auto idValue = params.value(QStringLiteral("sessionId"));
  if (!idValue.isDouble() || idValue.toInt() < 1)
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("sessionId must be a positive integer"));

  const int sessionId = idValue.toInt();
  db.verifySession(sessionId);

  QJsonObject result;
  result[QStringLiteral("sessionId")] = sessionId;
  result[QStringLiteral("verifying")] = true;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::SessionsHandler::getVerification(const QString& id,
                                                                     const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("sessionId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: sessionId"));

  static auto& db = Sessions::DatabaseManager::instance();
  if (!db.isOpen())
    return CommandResponse::makeError(
      id,
      ErrorCode::ExecutionError,
      QStringLiteral("No database open. Call sessions.openDatabase first."));

  const auto idValue = params.value(QStringLiteral("sessionId"));
  if (!idValue.isDouble() || idValue.toInt() < 1)
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("sessionId must be a positive integer"));

  const int sessionId = idValue.toInt();

  QJsonObject result;
  result[QStringLiteral("sessionId")] = sessionId;
  result[QStringLiteral("verifying")] = db.verificationBusy();
  result[QStringLiteral("verification")] =
    QJsonObject::fromVariantMap(db.latestVerification(sessionId));
  return CommandResponse::makeSuccess(id, result);
}

void API::ProcessLauncher::onProjectFileChanged()
{
  SS_ASSERT(m_projectModel != nullptr, return);
  const auto path = m_projectModel->jsonFilePath();
  if (path == m_lastProjectPath)
    return;

  if (!m_processes.isEmpty())
    qInfo() << "[ProcessLauncher] project changed to" << path << ", stopping" << m_processes.size()
            << "helper process(es)";

  m_lastProjectPath = path;
  killAll();
}

CLI::ProcessResult CLI::runSessionVerification()
{
  Sessions::Verifier::Options options;
  options.dbPath          = m_parser.value(m_opts.verifySessionOpt).trimmed();
  options.keepRegenerated = m_parser.isSet(m_opts.verifyKeepRegenOpt);

  if (m_parser.isSet(m_opts.verifySessionIdOpt)) {
    bool ok       = false;
    const int val = m_parser.value(m_opts.verifySessionIdOpt).toInt(&ok);
    if (!ok || val < 0) {
      std::fputs("{\"verdict\":\"error\",\"error\":\"invalid --verify-session-id\"}\n", stdout);
      std::fflush(stdout);
      return ProcessResult::ExitFailure;
    }

    options.sessionId = val;
  }

  Misc::ModuleManager::instantiateCoreModules();
  Misc::ModuleManager::setupHeadlessSessionConnections();

  Sessions::Verifier verifier(options);
  const int code = verifier.run();

  std::fputs(QJsonDocument(verifier.report()).toJson(QJsonDocument::Indented).constData(), stdout);
  std::fflush(stdout);

  return code == Sessions::Verifier::kExitReproduced ? ProcessResult::ExitSuccess
                                                     : ProcessResult::ExitFailure;
}

void Misc::ModuleManager::setupHeadlessSessionConnections()
{
  DataModel::FrameBuilder::instance().setupExternalConnections();
#ifdef BUILD_COMMERCIAL
  Sessions::Export::instance().setupExternalConnections();
#endif
}

void Sessions::DatabaseManager::setDbPathOverride(const QString& path)
{
  // code-verify off: the only caller overrides the path after the pinned order built Export
  SS_ASSERT_LOG(!Sessions::Export::instance().isOpen());
  // code-verify on
  s_dbPathOverride = path;
}

QVariantMap Sessions::DatabaseManager::latestVerification(int sessionId) const
{
  QVariantMap result;
  if (!m_open || m_filePath.isEmpty())
    return result;

  const QString connName = QStringLiteral("ss_dbm_verification_read");
  {
    auto db = QSqlDatabase::addDatabase(QStringLiteral("QSQLITE"), connName);
    db.setDatabaseName(m_filePath);
    db.setConnectOptions(QStringLiteral("QSQLITE_OPEN_READONLY"));
    if (db.open()) {
      QSqlQuery q(db);
      q.prepare(
        QStringLiteral("SELECT verified_at, app_version, verdict, detail_json FROM verifications "
                       "WHERE session_id = ? ORDER BY verification_id DESC LIMIT 1"));
      q.bindValue(0, sessionId);
      if (q.exec() && q.next()) {
        result.insert(QStringLiteral("verified_at"), q.value(0).toString());
        result.insert(QStringLiteral("app_version"), q.value(1).toString());
        result.insert(QStringLiteral("verdict"), q.value(2).toString());
        result.insert(
          QStringLiteral("detail"),
          QJsonDocument::fromJson(q.value(3).toString().toUtf8()).object().toVariantMap());
      }

      db.close();
    }
  }

  QSqlDatabase::removeDatabase(connName);
  return result;
}

QVariantMap Sessions::DatabaseManager::latestVerdicts() const
{
  QVariantMap result;
  if (!m_open || m_filePath.isEmpty())
    return result;

  const QString connName = QStringLiteral("ss_dbm_verdicts_read");
  {
    auto db = QSqlDatabase::addDatabase(QStringLiteral("QSQLITE"), connName);
    db.setDatabaseName(m_filePath);
    db.setConnectOptions(QStringLiteral("QSQLITE_OPEN_READONLY"));
    if (db.open()) {
      QSqlQuery q(db);
      const bool ok = q.exec(QStringLiteral(
        "SELECT v.session_id, v.verdict FROM verifications v JOIN "
        "(SELECT session_id, MAX(verification_id) AS latest_id FROM verifications "
        " GROUP BY session_id) latest "
        "ON v.session_id = latest.session_id AND v.verification_id = latest.latest_id"));
      while (ok && q.next())
        result.insert(q.value(0).toString(), q.value(1).toString());

      db.close();
    }
  }

  QSqlDatabase::removeDatabase(connName);
  return result;
}

void Sessions::DatabaseManager::verifySession(int sessionId)
{
  SS_ASSERT(m_open, return);
  SS_ASSERT(!m_filePath.isEmpty(), return);

  if (m_verifyProcess)
    return;

  auto* process   = new QProcess(this);
  m_verifyProcess = process;
  Q_EMIT verificationBusyChanged();

  QStringList args{QStringLiteral("--verify-session"), m_filePath, QStringLiteral("--headless")};
  if (sessionId >= 0)
    args << QStringLiteral("--verify-session-id") << QString::number(sessionId);

  connect(process,
          &QProcess::finished,
          this,
          [this, process, sessionId](int exitCode, QProcess::ExitStatus status) {
            const auto doc = QJsonDocument::fromJson(process->readAllStandardOutput());
            const bool ok  = status == QProcess::NormalExit && doc.isObject();
            const auto map = doc.object().toVariantMap();

            int resolvedId = sessionId;
            if (resolvedId < 0 && map.contains(QStringLiteral("sessionId")))
              resolvedId = map.value(QStringLiteral("sessionId")).toInt();

            concludeVerification(resolvedId, ok && exitCode == 0, map);
          });
  connect(process, &QProcess::errorOccurred, this, [this, sessionId](QProcess::ProcessError err) {
    if (err == QProcess::FailedToStart)
      concludeVerification(sessionId, false, QVariantMap());
  });

  process->start(QCoreApplication::applicationFilePath(), args);
}

void Sessions::DatabaseManager::concludeVerification(int sessionId,
                                                     bool success,
                                                     const QVariantMap& verdict)
{
  if (!m_verifyProcess)
    return;

  m_verifyProcess->deleteLater();
  m_verifyProcess = nullptr;
  Q_EMIT verificationBusyChanged();
  Q_EMIT verificationFinished(sessionId, success, verdict);
  Q_EMIT sessionsChanged();
}

void Sessions::DatabaseManager::migrateSessionsTable(QSqlQuery& q)
{
  auto columnExists = [&q](const QString& column) {
    if (!q.exec(QStringLiteral("PRAGMA table_info(\"sessions\")"))) {
      qWarning() << "[Sessions] PRAGMA table_info failed:" << q.lastError().text();
      return false;
    }
    while (q.next())
      if (q.value(1).toString().compare(column, Qt::CaseInsensitive) == 0)
        return true;

    return false;
  };

  static constexpr struct {
    const char* name;
    const char* type;
  } kColumns[] = {
    {     "raw_sha256",    "TEXT"},
    {"readings_sha256",    "TEXT"},
    {    "app_version",    "TEXT"},
    { "capture_format", "INTEGER"},
    {    "repro_class",    "TEXT"},
    { "frames_dropped", "INTEGER"},
    { "overflow_bytes", "INTEGER"},
  };

  for (const auto& col : kColumns) {
    if (columnExists(QLatin1String(col.name)))
      continue;

    const auto sql = QStringLiteral("ALTER TABLE \"sessions\" ADD COLUMN %1 %2")
                       .arg(QLatin1String(col.name), QLatin1String(col.type));
    if (!q.exec(sql))
      qWarning() << "[Sessions] ALTER add" << col.name << "failed:" << q.lastError().text();
  }
}

void Sessions::DatabaseManager::createSchemaVerifications(QSqlQuery& q)
{
  q.exec("CREATE TABLE IF NOT EXISTS verifications ("
         "  verification_id INTEGER PRIMARY KEY AUTOINCREMENT,"
         "  session_id      INTEGER NOT NULL REFERENCES sessions,"
         "  verified_at     TEXT NOT NULL,"
         "  app_version     TEXT NOT NULL,"
         "  verdict         TEXT NOT NULL,"
         "  detail_json     TEXT"
         ")");
  q.exec("CREATE INDEX IF NOT EXISTS idx_verifications_session "
         "ON verifications (session_id, verification_id)");
}

static void hashLe64(QCryptographicHash& hash, quint64 value)
{
  char buffer[sizeof(quint64)];
  qToLittleEndian(value, buffer);
  hash.addData(QByteArrayView(buffer, sizeof(buffer)));
}

static void hashDouble(QCryptographicHash& hash, double value)
{
  const double canonical = std::isnan(value) ? 0.0 : value;
  hashLe64(hash, std::bit_cast<quint64>(canonical));
}

static void hashString(QCryptographicHash& hash, const QString& value)
{
  const QByteArray utf8 = value.toUtf8();
  hashLe64(hash, static_cast<quint64>(utf8.size()));
  hash.addData(utf8);
}

void Sessions::hashRawChunk(QCryptographicHash& hash,
                            qint64 ns,
                            int deviceId,
                            const QByteArray& data)
{
  hashLe64(hash, static_cast<quint64>(ns));
  hashLe64(hash, static_cast<quint64>(deviceId));
  hashLe64(hash, static_cast<quint64>(data.size()));
  hash.addData(data);
}

void Sessions::hashReadingRow(QCryptographicHash& hash,
                              qint64 ns,
                              qint64 uniqueId,
                              double rawNumeric,
                              const QString& rawString,
                              double finalNumeric,
                              const QString& finalString,
                              bool isNumeric)
{
  hashLe64(hash, static_cast<quint64>(ns));
  hashLe64(hash, static_cast<quint64>(uniqueId));
  hashDouble(hash, rawNumeric);
  hashString(hash, rawString);
  hashDouble(hash, finalNumeric);
  hashString(hash, finalString);
  hashLe64(hash, isNumeric ? 1 : 0);
}

static QVariant fieldOr(const QSqlQuery& query, const char* column)
{
  const int index = query.record().indexOf(QLatin1String(column));
  return index >= 0 ? query.value(index) : QVariant();
}

Sessions::Verifier::~Verifier()
{
  m_readers.clear();
  m_db = QSqlDatabase();
  if (!m_archiveConnName.isEmpty())
    QSqlDatabase::removeDatabase(m_archiveConnName);
}

int Sessions::Verifier::run()
{
  if (!openArchive())
    return fail(QStringLiteral("cannot open archive: %1").arg(m_options.dbPath));

  if (!loadSession())
    return fail(QStringLiteral("session not found in archive"));

  if (!verifyIntegrity())
    return fail(QStringLiteral("archive raw_bytes/readings tables are unreadable"));

  classifySession();

  const bool consoleOnly = sessionIsConsoleOnly();
  if (!consoleOnly && !m_controlScriptSeen) {
    if (!reparseSession())
      return fail(QStringLiteral("re-parse failed (project load or export not licensed)"));

    if (!diffReadings())
      return fail(QStringLiteral("regenerated database diff failed"));
  }

  const int code = settleVerdict();
  appendVerificationRecord();
  cleanupRegenerated();
  return code;
}

int Sessions::Verifier::fail(const QString& reason)
{
  m_verdict = QStringLiteral("error");
  m_report  = QJsonObject{
     {  QStringLiteral("verdict"),        m_verdict},
     {    QStringLiteral("error"),           reason},
     {  QStringLiteral("archive"), m_options.dbPath},
     {QStringLiteral("sessionId"),      m_sessionId}
  };
  appendVerificationRecord();
  cleanupRegenerated();
  return kExitError;
}

bool Sessions::Verifier::openArchive()
{
  SS_ASSERT(!m_options.dbPath.isEmpty(), return false);

  if (!QFile::exists(m_options.dbPath))
    return false;

  m_archiveConnName = QStringLiteral("ss_verify_archive");
  m_db              = QSqlDatabase::addDatabase(QStringLiteral("QSQLITE"), m_archiveConnName);
  m_db.setDatabaseName(m_options.dbPath);
  m_db.setConnectOptions(QStringLiteral("QSQLITE_OPEN_READONLY"));
  return m_db.open();
}

bool Sessions::Verifier::loadSession()
{
  SS_ASSERT(m_db.isOpen(), return false);

  QSqlQuery q(m_db);
  if (m_options.sessionId >= 0) {
    q.prepare(QStringLiteral("SELECT * FROM sessions WHERE session_id = ?"));
    q.bindValue(0, m_options.sessionId);
  } else {
    q.prepare(QStringLiteral(
      "SELECT * FROM sessions WHERE ended_at IS NOT NULL ORDER BY session_id DESC LIMIT 1"));
  }

  if (!q.exec() || !q.next())
    return false;

  m_sessionId            = q.value(QStringLiteral("session_id")).toInt();
  m_projectJson          = q.value(QStringLiteral("project_json")).toString();
  m_storedRawSha256      = fieldOr(q, "raw_sha256").toString();
  m_storedReadingsSha256 = fieldOr(q, "readings_sha256").toString();
  m_captureAppVersion    = fieldOr(q, "app_version").toString();
  m_reproClassJson       = fieldOr(q, "repro_class").toString();
  m_legacyCapture        = fieldOr(q, "capture_format").isNull();

  const auto dropped  = fieldOr(q, "frames_dropped");
  const auto overflow = fieldOr(q, "overflow_bytes");
  m_framesDropped     = dropped.isNull() ? -1 : dropped.toLongLong();
  m_overflowBytes     = overflow.isNull() ? -1 : overflow.toLongLong();

  if (m_projectJson.isEmpty()) {
    QSqlQuery meta(m_db);
    meta.prepare(QStringLiteral("SELECT value FROM project_metadata WHERE key = 'project_json'"));
    if (meta.exec() && meta.next())
      m_projectJson = meta.value(0).toString();
  }

  QSqlQuery cols(m_db);
  cols.prepare(QStringLiteral("SELECT unique_id, is_virtual FROM columns WHERE session_id = ?"));
  cols.bindValue(0, m_sessionId);
  if (cols.exec()) {
    while (cols.next())
      if (cols.value(1).toInt() != 0)
        m_virtualDatasets.insert(cols.value(0).toLongLong());
  }

  return true;
}

bool Sessions::Verifier::sessionIsConsoleOnly() const
{
  const auto doc = QJsonDocument::fromJson(m_projectJson.toUtf8());
  if (!doc.isObject())
    return true;

  return doc.object().value(Keys::Groups).toArray().isEmpty();
}

bool Sessions::Verifier::verifyIntegrity()
{
  SS_ASSERT(m_db.isOpen(), return false);
  SS_ASSERT(m_sessionId >= 0, return false);

  QCryptographicHash rawHash(QCryptographicHash::Sha256);
  QSqlQuery raw(m_db);
  raw.prepare(QStringLiteral("SELECT timestamp_ns, device_id, data FROM raw_bytes "
                             "WHERE session_id = ? ORDER BY raw_id"));
  raw.bindValue(0, m_sessionId);
  if (!raw.exec())
    return false;

  while (raw.next())
    hashRawChunk(
      rawHash, raw.value(0).toLongLong(), raw.value(1).toInt(), raw.value(2).toByteArray());

  QCryptographicHash readingsHash(QCryptographicHash::Sha256);
  QSqlQuery readings(m_db);
  readings.prepare(
    QStringLiteral("SELECT timestamp_ns, unique_id, raw_numeric_value, raw_string_value, "
                   "final_numeric_value, final_string_value, is_numeric FROM readings "
                   "WHERE session_id = ? ORDER BY reading_id"));
  readings.bindValue(0, m_sessionId);
  if (!readings.exec())
    return false;

  while (readings.next())
    hashReadingRow(readingsHash,
                   readings.value(0).toLongLong(),
                   readings.value(1).toLongLong(),
                   SerialStudio::toDouble(readings.value(2)),
                   readings.value(3).toString(),
                   SerialStudio::toDouble(readings.value(4)),
                   readings.value(5).toString(),
                   readings.value(6).toInt() != 0);

  const auto rawHex      = QString::fromLatin1(rawHash.result().toHex());
  const auto readingsHex = QString::fromLatin1(readingsHash.result().toHex());

  if (!m_storedRawSha256.isEmpty())
    m_rawIntegrity =
      rawHex == m_storedRawSha256 ? QStringLiteral("verified") : QStringLiteral("mismatch");

  if (!m_storedReadingsSha256.isEmpty())
    m_readingsIntegrity = readingsHex == m_storedReadingsSha256 ? QStringLiteral("verified")
                                                                : QStringLiteral("mismatch");
}

void Sessions::Verifier::classifySession()
{
  const auto doc = QJsonDocument::fromJson(m_reproClassJson.toUtf8());
  if (!doc.isObject())
    return;

  const auto obj           = doc.object();
  m_controlScriptSeen      = obj.value(QStringLiteral("controlScript")).toBool();
  const bool transformsFed = obj.value(QStringLiteral("transformsPresent")).toBool()
                          && obj.value(QStringLiteral("tablesPresent")).toBool();
  m_finalsVerifiable = !transformsFed;
}

bool Sessions::Verifier::reparseSession()
{
  SS_ASSERT(!m_projectJson.isEmpty(), return false);

  const auto doc = QJsonDocument::fromJson(m_projectJson.toUtf8());
  if (!doc.isObject())
    return false;

  static auto& appState = AppState::instance();
  appState.setOperationMode(SerialStudio::ProjectFile);

  static auto& project = DataModel::ProjectModel::instance();
  project.setSuppressMessageBoxes(true);
  if (!project.loadFromJsonDocument(doc))
    return false;

  static auto& parser = DataModel::FrameParser::instance();
  parser.setSuppressMessageBoxes(true);
  parser.readCode();

  static auto& builder = DataModel::FrameBuilder::instance();
  builder.syncFromProjectModel();

  m_regenPath = QDir::temp().filePath(
    QStringLiteral("ss-verify-regen-%1.db").arg(QCoreApplication::applicationPid()));
  QFile::remove(m_regenPath);
  DatabaseManager::setDbPathOverride(m_regenPath);

  static auto& exporter = Sessions::Export::instance();
  exporter.setSettingsPersistent(false);
  exporter.setExportEnabled(true);
  if (!exporter.exportEnabled())
    return false;

  const bool fed = feedArchivedBytes();

  exporter.flushWorker();
  exporter.closeFile();
  exporter.setExportEnabled(false);
  DatabaseManager::setDbPathOverride(QString());
  return fed;
}

bool Sessions::Verifier::feedArchivedBytes()
{
  SS_ASSERT(m_db.isOpen(), return false);
  SS_ASSERT(m_sessionId >= 0, return false);

  QSqlQuery rows(m_db);
  rows.prepare(
    QStringLiteral("SELECT device_id, data FROM raw_bytes WHERE session_id = ? ORDER BY raw_id"));
  rows.bindValue(0, m_sessionId);
  if (!rows.exec())
    return false;

  static auto& builder  = DataModel::FrameBuilder::instance();
  static auto& exporter = Sessions::Export::instance();

  quint64 sinceFlush = 0;
  IO::CapturedDataPtr drained;
  while (rows.next()) {
    const int deviceId = rows.value(0).toInt();
    if (!m_readers.contains(deviceId)
        && m_readers.size() >= static_cast<size_t>(kMaxArchiveDevices))
      return false;

    auto& reader = readerForDevice(deviceId);
    reader.processData(IO::makeCapturedData(rows.value(1).toByteArray()));

    auto& queue = reader.queue();
    while (queue.try_dequeue(drained)) {
      builder.hotpathRxSourceFrame(deviceId, drained);
      ++sinceFlush;
    }

    if (sinceFlush >= kFlushEveryFrames) {
      exporter.flushWorker();
      QCoreApplication::processEvents();
      sinceFlush = 0;
    }
  }

  QCoreApplication::processEvents();
  return true;
}

IO::FrameReader& Sessions::Verifier::readerForDevice(int deviceId)
{
  auto it = m_readers.find(deviceId);
  if (it != m_readers.end())
    return *it->second;

  static auto& manager = IO::ConnectionManager::instance();
  const auto config    = manager.buildFrameConfig(deviceId);

  auto reader = std::make_unique<IO::FrameReader>();
  reader->setOperationMode(config.operationMode);
  reader->setFrameDetectionMode(config.frameDetection);
  reader->setStartSequences(config.startSequences);
  reader->setFinishSequences(config.finishSequences);
  reader->setChecksum(config.checksumAlgorithm);

  auto& slot = m_readers[deviceId];
  slot       = std::move(reader);
  return *slot;
}

static bool regenSanityCheck(QSqlDatabase& regen,
                             QSqlDatabase& archive,
                             int archiveSessionId,
                             int& regenSessionId)
{
  QSqlQuery sessions(regen);
  if (!sessions.exec(QStringLiteral("SELECT COUNT(*), MAX(session_id) FROM sessions"))
      || !sessions.next() || sessions.value(0).toInt() != 1)
    return false;

  regenSessionId = sessions.value(1).toInt();

  QSqlQuery archived(archive);
  archived.prepare(QStringLiteral("SELECT COUNT(*) FROM readings WHERE session_id = ?"));
  archived.bindValue(0, archiveSessionId);
  if (!archived.exec() || !archived.next())
    return false;

  QSqlQuery regenerated(regen);
  regenerated.prepare(QStringLiteral("SELECT COUNT(*) FROM readings WHERE session_id = ?"));
  regenerated.bindValue(0, regenSessionId);
  if (!regenerated.exec() || !regenerated.next())
    return false;

  return archived.value(0).toLongLong() == 0 || regenerated.value(0).toLongLong() > 0;
}

bool Sessions::Verifier::diffReadings()
{
  SS_ASSERT(!m_regenPath.isEmpty(), return false);

  const QString connName = QStringLiteral("ss_verify_regen");
  bool ok                = false;
  {
    auto regen = QSqlDatabase::addDatabase(QStringLiteral("QSQLITE"), connName);
    regen.setDatabaseName(m_regenPath);
    regen.setConnectOptions(QStringLiteral("QSQLITE_OPEN_READONLY"));
    ok = regen.open();

    int regenSessionId = -1;
    if (ok)
      ok = regenSanityCheck(regen, m_db, m_sessionId, regenSessionId);

    if (ok) {
      QSqlQuery uids(m_db);
      uids.prepare(QStringLiteral("SELECT DISTINCT unique_id FROM columns WHERE session_id = ?"));
      uids.bindValue(0, m_sessionId);
      ok = uids.exec();

      while (ok && uids.next()) {
        const qint64 uid = uids.value(0).toLongLong();
        if (m_virtualDatasets.contains(uid)) {
          QJsonObject skipped;
          skipped.insert(Keys::UniqueId, uid);
          skipped.insert(QStringLiteral("skipped"), QStringLiteral("virtual-dataset"));
          m_datasetReports.append(skipped);
          continue;
        }

        m_datasetReports.append(diffDataset(regen, regenSessionId, uid, m_finalsVerifiable));
      }

      regen.close();
    }
  }

  QSqlDatabase::removeDatabase(connName);
  return ok;
}

QJsonObject Sessions::Verifier::diffDataset(QSqlDatabase& regen,
                                            int regenSessionId,
                                            qint64 uniqueId,
                                            bool compareFinals)
{
  SS_ASSERT(regen.isOpen(), return QJsonObject());
  SS_ASSERT(m_sessionId >= 0, return QJsonObject());

  const auto select =
    QStringLiteral("SELECT timestamp_ns, raw_numeric_value, raw_string_value, "
                   "final_numeric_value, final_string_value, is_numeric FROM readings "
                   "WHERE session_id = ? AND unique_id = ? ORDER BY timestamp_ns, reading_id");

  QSqlQuery archived(m_db);
  archived.prepare(select);
  archived.bindValue(0, m_sessionId);
  archived.bindValue(1, uniqueId);

  QSqlQuery regenerated(regen);
  regenerated.prepare(select);
  regenerated.bindValue(0, regenSessionId);
  regenerated.bindValue(1, uniqueId);

  QJsonObject result;
  result.insert(Keys::UniqueId, uniqueId);
  result.insert(QStringLiteral("finalsCompared"), compareFinals);
  if (!archived.exec() || !regenerated.exec()) {
    result.insert(QStringLiteral("error"), QStringLiteral("query failed"));
    return result;
  }

  qint64 recordedRows = 0, regenRows = 0, mismatches = 0, row = 0;
  QJsonObject firstMismatch;

  while (archived.next()) {
    ++recordedRows;
    if (!regenerated.next())
      continue;

    ++regenRows;
    ++row;

    const bool rawMatch = bitEqual(SerialStudio::toDouble(archived.value(1)),
                                   SerialStudio::toDouble(regenerated.value(1)))
                       && archived.value(2).toString() == regenerated.value(2).toString();
    const bool finalMatch = !compareFinals
                         || (bitEqual(SerialStudio::toDouble(archived.value(3)),
                                      SerialStudio::toDouble(regenerated.value(3)))
                             && archived.value(4).toString() == regenerated.value(4).toString());

    if (rawMatch && finalMatch)
      continue;

    ++mismatches;
    if (!firstMismatch.isEmpty())
      continue;

    const bool parseStage = !rawMatch;
    firstMismatch         = QJsonObject{
              {                    QStringLiteral("row"),                                                                row},
              {    QStringLiteral("recordedTimestampNs"),                                     archived.value(0).toLongLong()},
              {                  QStringLiteral("stage"), parseStage ? QStringLiteral("parse") : QStringLiteral("transform")},
              {            QStringLiteral("recordedRaw"),                                       archived.value(2).toString()},
              {         QStringLiteral("regeneratedRaw"),                                    regenerated.value(2).toString()},
              {     QStringLiteral("recordedRawNumeric"),                          SerialStudio::toDouble(archived.value(1))},
              {  QStringLiteral("regeneratedRawNumeric"),                       SerialStudio::toDouble(regenerated.value(1))},
              {          QStringLiteral("recordedFinal"),                                       archived.value(4).toString()},
              {       QStringLiteral("regeneratedFinal"),                                    regenerated.value(4).toString()},
              {   QStringLiteral("recordedFinalNumeric"),                          SerialStudio::toDouble(archived.value(3))},
              {QStringLiteral("regeneratedFinalNumeric"),                       SerialStudio::toDouble(regenerated.value(3))}
    };
  }

  while (regenerated.next())
    ++regenRows;

  result.insert(QStringLiteral("recordedRows"), recordedRows);
  result.insert(QStringLiteral("regeneratedRows"), regenRows);
  result.insert(QStringLiteral("mismatches"), mismatches);
  if (!firstMismatch.isEmpty())
    result.insert(QStringLiteral("firstMismatch"), firstMismatch);

  if (recordedRows != regenRows)
    result.insert(QStringLiteral("countMismatch"), true);

  return result;
}

int Sessions::Verifier::decideVerdict(bool diverged, bool anySkipped, bool consoleOnly)
{
  if (m_controlScriptSeen && !diverged) {
    m_verdict = QStringLiteral("not_verifiable");
    m_notes.append(QStringLiteral("control script ran during capture: interpretation state "
                                  "could change mid-session, re-parse would be misleading"));
    return kExitNotVerifiable;
  }

  if (diverged) {
    m_verdict = QStringLiteral("diverged");
    return kExitDiverged;
  }

  if (consoleOnly) {
    const bool verified = m_rawIntegrity == QStringLiteral("verified");
    m_verdict = verified ? QStringLiteral("reproduced") : QStringLiteral("not_verifiable");
    m_notes.append(QStringLiteral("console-only session: raw-integrity check only, no "
                                  "interpretation pipeline to re-run"));
    return verified ? kExitReproduced : kExitNotVerifiable;
  }

  if (anySkipped) {
    m_verdict = QStringLiteral("partial");
    m_notes.append(QStringLiteral("reproduced except datasets whose inputs are not archived "
                                  "(see skipped / finalsCompared entries)"));
    return kExitNotVerifiable;
  }

  m_verdict = QStringLiteral("reproduced");
  return kExitReproduced;
}

int Sessions::Verifier::settleVerdict()
{
  bool diverged = m_rawIntegrity == QStringLiteral("mismatch")
               || m_readingsIntegrity == QStringLiteral("mismatch");

  bool anyError   = false;
  bool anySkipped = false;
  for (const auto& entryRef : std::as_const(m_datasetReports)) {
    const auto entry = entryRef.toObject();
    if (entry.contains(QStringLiteral("error")))
      anyError = true;

    if (entry.value(QStringLiteral("mismatches")).toInteger() > 0
        || entry.value(QStringLiteral("countMismatch")).toBool())
      diverged = true;

    if (entry.contains(QStringLiteral("skipped"))
        || !entry.value(QStringLiteral("finalsCompared")).toBool())
      anySkipped = true;
  }

  int code = decideVerdict(diverged, anySkipped, sessionIsConsoleOnly());
  if (anyError && !diverged) {
    m_verdict = QStringLiteral("error");
    m_notes.append(QStringLiteral("one or more dataset queries failed: verification is "
                                  "inconclusive, not a verdict on the data"));
    code = kExitError;
  }

  if (m_legacyCapture)
    m_notes.append(QStringLiteral("legacy capture: no fingerprints or classification stored; "
                                  "verdict is best-effort (spec 0044 R8)"));

  QJsonObject integrity;
  integrity.insert(QStringLiteral("rawBytes"), m_rawIntegrity);
  integrity.insert(QStringLiteral("readings"), m_readingsIntegrity);

  m_report = QJsonObject();
  m_report.insert(QStringLiteral("verdict"), m_verdict);
  m_report.insert(QStringLiteral("archive"), m_options.dbPath);
  m_report.insert(QStringLiteral("sessionId"), m_sessionId);
  m_report.insert(QStringLiteral("verifyingAppVersion"), QStringLiteral(APP_VERSION));
  m_report.insert(QStringLiteral("captureAppVersion"), m_captureAppVersion);
  m_report.insert(QStringLiteral("legacyCapture"), m_legacyCapture);
  m_report.insert(QStringLiteral("integrity"), integrity);
  m_report.insert(QStringLiteral("classification"),
                  QJsonDocument::fromJson(m_reproClassJson.toUtf8()).object());
  m_report.insert(QStringLiteral("captureFramesDropped"), m_framesDropped);
  m_report.insert(QStringLiteral("captureOverflowBytes"), m_overflowBytes);
  m_report.insert(QStringLiteral("datasets"), m_datasetReports);
  m_report.insert(QStringLiteral("notes"), m_notes);

  if (m_options.keepRegenerated && !m_regenPath.isEmpty())
    m_report.insert(QStringLiteral("regeneratedDb"), m_regenPath);

  return code;
}

void Sessions::Verifier::appendVerificationRecord()
{
  if (m_sessionId < 0)
    return;

  const QString connName = QStringLiteral("ss_verify_record");
  {
    auto db = QSqlDatabase::addDatabase(QStringLiteral("QSQLITE"), connName);
    db.setDatabaseName(m_options.dbPath);
    if (db.open()) {
      QSqlQuery q(db);
      q.exec(QStringLiteral("PRAGMA busy_timeout=5000"));
      DatabaseManager::createSchemaVerifications(q);

      q.prepare(
        QStringLiteral("INSERT INTO verifications (session_id, verified_at, app_version, verdict, "
                       "detail_json) VALUES (?, ?, ?, ?, ?)"));
      q.bindValue(0, m_sessionId);
      q.bindValue(1, QDateTime::currentDateTime().toString(Qt::ISODate));
      q.bindValue(2, QStringLiteral(APP_VERSION));
      q.bindValue(3, m_verdict);
      q.bindValue(4, QString::fromUtf8(QJsonDocument(m_report).toJson(QJsonDocument::Compact)));
      if (!q.exec())
        qWarning() << "[Verifier] verification record append failed:" << q.lastError().text();

      db.close();
    } else {
      qWarning() << "[Verifier] cannot open archive for record append:" << db.lastError().text();
    }
  }
  QSqlDatabase::removeDatabase(connName);
}

void Sessions::Verifier::cleanupRegenerated()
{
  DatabaseManager::setDbPathOverride(QString());

  if (m_options.keepRegenerated || m_regenPath.isEmpty())
    return;

  QFile::remove(m_regenPath);
  QFile::remove(m_regenPath + QStringLiteral("-wal"));
  QFile::remove(m_regenPath + QStringLiteral("-shm"));
  m_regenPath.clear();
}

void IO::ConnectionManager::settlePendingDialVerdicts()
{
  if (m_pendingDialVerdicts.isEmpty())
    return;

  const auto pending = m_pendingDialVerdicts;
  for (const int deviceId : pending) {
    HAL_Driver* halDriver = driver(deviceId);
    if (halDriver == nullptr) {
      m_pendingDialVerdicts.remove(deviceId);
      continue;
    }

    if (halDriver->isOpen()) {
      m_pendingDialVerdicts.remove(deviceId);
      onDeviceOpenFinished(deviceId, true, QString());
    }
  }
}

void Misc::ConnectionDiagnostics::restoreStanding(BusMask scope, const ResultCache& standing)
{
  for (int i = 0; i < kBusCount; ++i) {
    if (!scopeCovers(scope, static_cast<Bus>(i)))
      continue;

    auto& fresh = m_results[static_cast<size_t>(i)];
    for (const auto& result : standing[static_cast<size_t>(i)]) {
      const bool duplicate = std::any_of(
        fresh.cbegin(), fresh.cend(), [&result](const Result& r) { return r.code == result.code; });
      if (!duplicate)
        fresh.append(result);
    }
  }
}

void IO::Drivers::Audio::notificationCallback(const ma_device_notification* notification)
{
  SS_ASSERT(notification != nullptr, return);
  SS_ASSERT(notification->pDevice != nullptr, return);

  if (notification->type != ma_device_notification_type_stopped)
    return;

  auto* self = static_cast<Audio*>(notification->pDevice->pUserData);
  if (!self || !self->m_stopNotifyArmed.exchange(false, std::memory_order_acq_rel))
    return;

  QMetaObject::invokeMethod(self, "onBackendStopped", Qt::QueuedConnection);
}

void IO::Drivers::Audio::onBackendStopped()
{
  if (!m_isOpen)
    return;

  static auto& connectionManager = IO::ConnectionManager::instance();
  connectionManager.disconnectDevice(this);

  QMetaObject::invokeMethod(
    this,
    [] {
      Misc::Utilities::showMessageBox(
        tr("Audio Device Stopped"),
        tr("The audio backend stopped the stream. The device may have been "
           "unplugged or claimed by another application."),
        QMessageBox::Warning);
    },
    Qt::QueuedConnection);
}

void IO::Drivers::Modbus::wireConfigurationSignals()
{
  static constexpr void (Modbus::* kEndpointSignals[])() = {&Modbus::hostChanged,
                                                            &Modbus::portChanged,
                                                            &Modbus::baudRateChanged,
                                                            &Modbus::parityIndexChanged,
                                                            &Modbus::dataBitsIndexChanged,
                                                            &Modbus::stopBitsIndexChanged,
                                                            &Modbus::protocolIndexChanged,
                                                            &Modbus::serialPortIndexChanged};

  for (const auto signal : kEndpointSignals) {
    connect(this, signal, this, &IO::Drivers::Modbus::scheduleReopenIfActive);
    connect(this, signal, this, &IO::Drivers::Modbus::configurationChanged);
  }

  m_reopenTimer.stop();
/**
 * @brief Debounces a reopen while the link is live so an endpoint edit (host, port, protocol,
 *        serial parameters) takes effect without a manual disconnect/reconnect cycle. A closed
 *        driver stays closed: configuration edits never dial on their own.
 */
void IO::Drivers::Modbus::scheduleReopenIfActive()
{
  if (!isOpen() && !isConnecting())
    return;

  m_reopenTimer.start();
}

/**
 * @brief Applies a debounced endpoint change by redialing with the new configuration.
 */
void IO::Drivers::Modbus::reopenAfterConfigChange()
{
  if (!isOpen() && !isConnecting())
    return;

  (void)open(QIODevice::ReadWrite);
}

void IO::Drivers::Modbus::scheduleReopenIfActive()
{
  if (!isOpen() && !isConnecting())
    return;

  m_reopenTimer.start();
}

void IO::Drivers::Modbus::reopenAfterConfigChange()
{
  if (!isOpen() && !isConnecting())
    return;

  (void)open(QIODevice::ReadWrite);
}

void IO::Drivers::USB::notifyDrainWaiter()
{
  if (!m_drainWaiting.load(std::memory_order_acquire))
    return;

  {
    std::lock_guard<std::mutex> lock(m_drainMutex);
  }
  m_drainCv.notify_all();
    self->notifyDrainWaiter();
    self->notifyDrainWaiter();
    self->notifyDrainWaiter();
  self->notifyDrainWaiter();

static void queueErrorBox(QObject* context, const QString& title, const QString& text)
{
  QMetaObject::invokeMethod(
    context,
    [title, text] { Misc::Utilities::showMessageBox(title, text, QMessageBox::Critical); },
    Qt::QueuedConnection);
}

void IO::Drivers::Modbus::handleDialSetback()
{
  if (!m_connecting)
    return;

  m_dialTimeoutTimer.stop();
  const int max_attempts = (m_protocolIndex == 1) ? kTcpConnectAttempts : 1;
  if (m_dialAttempts < max_attempts)
    m_dialRetryTimer.start();
  else
    failDial(m_device ? m_device->errorString() : QString());
}

static void queueWarningBox(QObject* context, const QString& title, const QString& text)
{
  QMetaObject::invokeMethod(
    context,
    [title, text] { Misc::Utilities::showMessageBox(title, text, QMessageBox::Warning); },
    Qt::QueuedConnection);
}

bool IO::Drivers::Process::isConnecting() const noexcept
{
  if (m_mode == Mode::Launch)
    return m_process && m_process->state() == QProcess::Starting;

  return m_pipeRunning.load() && !m_pipeConnected.load();
      queueWarningBox(this,
                      tr("Failed to start process"),
                      tr("Executable \"%1\" not found in PATH.").arg(m_executable));
  m_pipeConnected = false;
  m_pipeRunning   = true;
 * @brief Handles QProcess termination. The teardown is queued before the box so the UI never
 *        claims a dead process is a connected device while the modal is up.

  queueWarningBox(
    this, tr("Process \"%1\" stopped").arg(QFileInfo(m_executable).fileName()), reason);
 * @brief Handles a QProcess-level error during execution. The teardown is queued before the box
 *        so the UI never claims a failed process is a connected device while the modal is up.

  queueWarningBox(this, tr("Process Error"), detail);
 * @brief Called on the main thread when pipeReadLoop() fails to open the pipe. The teardown is
 *        queued before the box so the UI never claims a dead pipe is a connected device.
  queuePipeTeardown();

  m_pipeConnected = true;

  m_pipeConnected = false;
  m_pipeConnected = true;

  m_pipeConnected = false;

static void queueErrorBox(QObject* context,
                          const QString& title,
                          const QString& text,
                          const QMessageBox::Icon icon = QMessageBox::Critical)
{
  QMetaObject::invokeMethod(
    context,
    [title, text, icon] { Misc::Utilities::showMessageBox(title, text, icon); },
    Qt::QueuedConnection);
}

void IO::Drivers::Network::scheduleReopenIfActive()
{
  if (!isOpen() && !isConnecting())
    return;

  m_reopenTimer.start();
}

void IO::Drivers::Network::reopenAfterConfigChange()
{
  if (!isOpen() && !isConnecting())
    return;

  const auto mode = m_dialMode;
  close();
  (void)open(mode);
}

void IO::ConnectionManager::notifyConnectedStateChanged()
{
  const bool connected = isConnected();
  const int count      = connectedDeviceCount();
  if (m_lastConnectedState == connected && m_lastConnectedCount == count)
    return;

  m_lastConnectedState = connected;
  m_lastConnectedCount = count;
 * @brief Disconnects the primary device and any other project sources, settling a connect request
 *        the user gave up on. The id list is snapshotted first: a close can spin the event loop
 *        (error boxes), and a rebuild landing there would invalidate a live m_devices iterator.
    std::vector<int> ids;
    ids.reserve(m_devices.size());
    for (const auto& [id, dm] : m_devices)
        ids.push_back(id);

    for (const int id : ids)
      disconnectDevice(id);
  Q_EMIT driverChanged();
  notifyConnectedStateChanged();
 * @brief Connects all devices with deviceId > 0 (project sources). Iterates a snapshot of the id
 *        list: an open can spin the event loop (error boxes, control scripts), and a rebuild
 *        landing there would invalidate a live iterator over m_devices.
  std::vector<int> ids;
  ids.reserve(m_devices.size());
  for (const auto& [id, dm] : m_devices)
      ids.push_back(id);

  for (const int id : ids)
    connectDevice(id);
 * @brief Disconnects every registered device, iterating a snapshot for the same reentrancy
 *        reason as connectAllDevices().
  std::vector<int> ids;
  ids.reserve(m_devices.size());
  for (const auto& [id, dm] : m_devices)
    ids.push_back(id);

  for (const int id : ids)
  notifyConnectedStateChanged();
 * @brief Disconnects the source owned by @p driver, keeping other sources alive. The state change
 *        is published by the per-device teardown; only the session-level signals remain here.
  }

void IO::Drivers::BluetoothLE::onControllerError(QLowEnergyController::Error controllerError)
{
  if (controllerError == QLowEnergyController::NoError)
    return;

  Q_EMIT error(tr("BLE connection error: %1")
                 .arg(m_controller ? m_controller->errorString() : tr("Unknown error")));
  close();
}

bool IO::Drivers::CANBus::isConnecting() const noexcept
{
  if (m_device)
    return m_device->state() == QCanBusDevice::ConnectingState;

  return false;
}

void IO::Drivers::Modbus::pauseBetweenAttempts()
{
  QEventLoop pause;
  QTimer::singleShot(kTcpConnectBackoffMs, &pause, &QEventLoop::quit);
  pause.exec();
}

void IO::Drivers::Network::onDialTimeout()
{
  if (!m_dialInProgress)
    return;

  m_dialInProgress = false;
  m_dialRetryTimer.stop();
  m_tcpSocket.abort();

  static auto& connectionManager = ConnectionManager::instance();
  queueErrorBox(&connectionManager,
                tr("Network socket error"),
                tr("Connection to %1:%2 timed out.").arg(m_dialHost, QString::number(tcpPort())));
  connectionManager.disconnectDevice(this);
}

void IO::Drivers::Network::onTcpStateChanged()
{
  if (m_tcpSocket.state() == QAbstractSocket::ConnectedState) {
    m_dialInProgress = false;
    m_dialRetryTimer.stop();
    m_dialTimeoutTimer.stop();
  Q_EMIT configurationChanged();
 * @brief Handles socket errors by disconnecting and reporting. A refused dial retries with a
 *        short backoff before failing for real; the teardown destroys this driver, so the box is
 *        queued on the connection manager: raising it here would outlive the object it was raised
 *        from and block the very disconnect it is reporting.
  if (m_dialInProgress && socketType() == QAbstractSocket::TcpSocket) {
    m_dialTimeoutTimer.stop();
    if (socketError == QAbstractSocket::ConnectionRefusedError
        && m_dialAttempts < kTcpConnectAttempts) {
      m_dialRetryTimer.start();
      return;
    }

    m_dialInProgress = false;
  }

void IO::Drivers::Process::onPipeClosed()
{
  if (!m_pipeRunning.load())
    return;

  m_pipeRunning = false;
  queuePipeTeardown();

  Misc::Utilities::showMessageBox(
    tr("Pipe Closed"),
    tr("The named pipe \"%1\" was closed on the other end.").arg(m_pipePath),
    QMessageBox::Warning);
}

void IO::Drivers::Process::queuePipeTeardown()
{

  if (m_pipeRunning.load())
    QMetaObject::invokeMethod(this, "onPipeClosed", Qt::QueuedConnection);

  if (m_pipeRunning.load())
    QMetaObject::invokeMethod(this, "onPipeClosed", Qt::QueuedConnection);

void IO::Drivers::UART::pollAutoReconnect()
{
  if (!m_pendingReconnect || !autoReconnect() || isOpen()) {
    m_reconnectTimer.stop();
    return;
  }

  refreshSerialDevices();
  if (m_lastPortName.isEmpty() || !portList().contains(m_lastPortName))
    return;

  m_pendingReconnect = false;
  m_reconnectTimer.stop();
  setPortIndex(static_cast<quint8>(portList().indexOf(m_lastPortName)));

  static auto& connectionManager = ConnectionManager::instance();
  connectionManager.connectDevice();
}

void Licensing::LemonSqueezy::notifyEntitlementMaybeChanged()
