void IO::Drivers::MQTT::reloadTlsIdentity(const bool interactive)
{
  const auto result = ::MQTT::loadTlsIdentity(
    m_clientCertificatePath, m_privateKeyPath, m_keyPassphrase, m_tlsIdentity);

  const auto alpn = m_alpnEnabled ? m_alpnProtocol.toUtf8() : QByteArray();
  ::MQTT::applyTlsIdentity(m_sslConfiguration, m_tlsIdentity, alpn);

  if (result.ok())
    return;

  qCWarning(lcMqttSub) << "TLS identity rejected:" << ::MQTT::tlsIdentityErrorString(result);
  if (interactive)
    Misc::Utilities::showMessageBox(tr("MQTT Client Certificate Error"),
                                    ::MQTT::tlsIdentityErrorString(result),
                                    QMessageBox::Warning);
}

QString MQTT::CredentialVault::keyPassphrase(const QString& host, quint16 port) const
{
  if (host.isEmpty())
    return QString();

  const auto key = settingsKey(host, port);
  m_settings.beginGroup(QStringLiteral("mqtt/credentials"));
  const auto cipher = m_settings.value(key + QStringLiteral("/keyPass")).toString();
  m_settings.endGroup();

  if (cipher.isEmpty())
    return QString();

  auto plain = m_simpleCrypt.decryptToString(cipher);
  if (m_simpleCrypt.lastError() != Licensing::SimpleCrypt::ErrorNoError) {
    qCWarning(lcMqttVault) << "Key passphrase decrypt failed for" << key;
    return QString();
  }

  return plain;
}

void MQTT::CredentialVault::setKeyPassphrase(const QString& host,
                                             quint16 port,
                                             const QString& passphrase)
{
  if (host.isEmpty())
    return;

  const auto key = settingsKey(host, port);
  m_settings.beginGroup(QStringLiteral("mqtt/credentials"));

  if (passphrase.isEmpty())
    m_settings.remove(key + QStringLiteral("/keyPass"));
  else
    m_settings.setValue(key + QStringLiteral("/keyPass"),
                        m_simpleCrypt.encryptToString(passphrase));

  m_settings.endGroup();
}

