void TstTlsIdentity::applyWritesConfiguration()
{
  MQTT::TlsIdentity identity;
  QVERIFY(MQTT::loadTlsIdentity(m_certPath, m_keyPath, QString(), identity).ok());

  QSslConfiguration config;
  MQTT::applyTlsIdentity(config, identity, QByteArrayLiteral("x-amzn-mqtt-ca"));
  QCOMPARE(config.localCertificate(), identity.certificate);
  QCOMPARE(config.privateKey(), identity.privateKey);
  QCOMPARE(config.allowedNextProtocols(), QList<QByteArray>{QByteArrayLiteral("x-amzn-mqtt-ca")});
}

void TstTlsIdentity::applyClearsWithInvalidIdentity()
{
  MQTT::TlsIdentity identity;
  QVERIFY(MQTT::loadTlsIdentity(m_certPath, m_keyPath, QString(), identity).ok());

  QSslConfiguration config;
  MQTT::applyTlsIdentity(config, identity, QByteArrayLiteral("x-amzn-mqtt-ca"));
  MQTT::applyTlsIdentity(config, MQTT::TlsIdentity(), QByteArray());
  QVERIFY(config.localCertificate().isNull());
  QVERIFY(config.privateKey().isNull());
  QVERIFY(config.allowedNextProtocols().isEmpty());
}

void TstTlsIdentity::errorStringsNeverEchoPassphrase()
{
  const auto secret = QStringLiteral("s3cr3t-passphrase");

  MQTT::TlsIdentity identity;
  const auto wrong = MQTT::loadTlsIdentity(m_certPath, m_encKeyPath, secret, identity);
  QCOMPARE(wrong.error, MQTT::TlsIdentityError::PassphraseWrong);
  QVERIFY(!MQTT::tlsIdentityErrorString(wrong).contains(secret));

  const auto required = MQTT::loadTlsIdentity(m_certPath, m_encKeyPath, QString(), identity);
  QVERIFY(!MQTT::tlsIdentityErrorString(required).contains(secret));
}

void Licensing::LemonSqueezy::revalidateCachedLicense()
{
  if (!canActivate() || isOnlineActivated())
    return;

  m_revalidatingCache = true;
  validate();
  if (!busy())
    m_revalidatingCache = false;
}

[[nodiscard]] static bool busRequiresCommercial(const int busType)
{
  switch (static_cast<SerialStudio::BusType>(busType)) {
    case SerialStudio::BusType::UART:
    case SerialStudio::BusType::Network:
    case SerialStudio::BusType::BluetoothLE:
      return false;
    default:
      return true;
  }
}

static void checkUnlicensedSources(QList<Finding>& out)
{
  if (!projectAvailable())
    return;

  if (SerialStudio::activated())
    return;

  static auto& project = DataModel::ProjectModel::instance();
  for (const auto& src : project.sources()) {
    if (!busRequiresCommercial(src.busType))
      continue;

    const auto label = src.title.isEmpty() ? trProblem("Source %1").arg(src.sourceId) : src.title;
    out.append(makeFinding(Misc::ProblemCenter::Warning,
                           "unlicensed-source",
                           trProblem("Data source requires Serial Studio Pro"),
                           trProblem("\"%1\" uses a data source that needs a license or an "
                                     "active trial, so it cannot connect in this session.")
                             .arg(label),
                           trProblem("Activate Serial Studio Pro or start the free trial, then "
                                     "reconnect."),
                           -1,
                           QString()));
  }

  capFindings(out);
}

nodiscard]] Async::TimerId schedule(int msec, Callback cb) override
  {
    Entry entry;
    entry.due      = m_now + msec;
    entry.callback = std::move(cb);

    const Async::TimerId id = ++m_nextId;
    m_entries.insert(id, entry);
    m_delays.append(msec);
    return id;
  }

id advance(qint64 msec)
  {
    m_now += msec;
    for (int guard = 0; guard < 4096; ++guard) {
      const Async::TimerId next = dueEntry();
      if (next == Async::kInvalidTimerId)
        return;

      const Entry entry = m_entries.take(next);
      entry.callback();
    }
  }

nodiscard]] Async::TimerId dueEntry() const
  {
    Async::TimerId winner = Async::kInvalidTimerId;
    qint64 best           = 0;
    for (auto it = m_entries.cbegin(); it != m_entries.cend(); ++it) {
      if (it.value().due > m_now)
        continue;

      if (winner == Async::kInvalidTimerId || it.value().due < best) {
        winner = it.key();
        best   = it.value().due;
      }
    }

    return winner;
  }

id complete(Async::Outcome outcome, const QString& reason = QStringLiteral("boom"))
  {
    if (!isRunning())
      return;

    if (outcome == Async::Outcome::Success)
      reportFinished(outcome, Async::StepError());
    else
      reportFinished(outcome, errorHere(reason));
  }

id doStart() override
  {
    ++m_starts;
    if (m_log != nullptr)
      m_log->append(name() + QStringLiteral("/start"));
  }

id doCancel() override
  {
    ++m_cancels;
    if (m_log != nullptr)
      m_log->append(name() + QStringLiteral("/cancel"));
  }

id attach(Async::Task* task)
  {
    QObject::connect(task,
                     &Async::Task::finished,
                     task,
                     [this](Async::Outcome result, const Async::StepError& step) {
                       ++count;
                       outcome = result;
                       error   = step;
                     });
  }
}

atic Async::Task* buildNestedTree(
  Async::AsyncClock& clock, FakeStep*& a, FakeStep*& b, FakeStep*& c, FakeStep*& d)
{
  a = new FakeStep(QStringLiteral("a"), nullptr);
  b = new FakeStep(QStringLiteral("b"), nullptr);
  c = new FakeStep(QStringLiteral("c"), nullptr);
  d = new FakeStep(QStringLiteral("d"), nullptr);

  auto* par = Async::parallel(QStringLiteral("par"));
  par->addChild(a)->addChild(b);

  auto* root = Async::sequential(QStringLiteral("root"));
  root->addChild(par)
    ->addChild(Async::timeout(c, 500, clock))
    ->addChild(Async::retry(d, Async::RetryPolicy(3, 100, 400, 2.0), clock));

  return root;
}

id AsyncCombinatorTests::sequentialFactoryOrdersChildrenAndReportsFailureStep()
{
  Watcher watcher;
  auto* group = Async::sequential(QStringLiteral("open"));
  auto* one   = new FakeStep(QStringLiteral("resolve"), nullptr);
  auto* two   = new FakeStep(QStringLiteral("connect"), nullptr);
  group->addChild(one)->addChild(two);
  std::unique_ptr<Async::Task> task(group);
  watcher.attach(task.get());

  task->start();
  QCOMPARE(one->starts(), 1);
  QCOMPARE(two->starts(), 0);

  one->complete(Async::Outcome::Success);
  QCOMPARE(two->starts(), 1);

  two->complete(Async::Outcome::Failure, QStringLiteral("connection refused"));

  QCOMPARE(watcher.outcome, Async::Outcome::Failure);
  QCOMPARE(watcher.error.step, QStringLiteral("connect"));
  QCOMPARE(watcher.error.reason, QStringLiteral("connection refused"));
}

id AsyncCombinatorTests::parallelFactoryCancelsSiblingsOnFirstFailure()
{
  Watcher watcher;
  auto* group = Async::parallel(QStringLiteral("probe"));
  auto* a     = new FakeStep(QStringLiteral("a"), nullptr);
  auto* b     = new FakeStep(QStringLiteral("b"), nullptr);
  auto* c     = new FakeStep(QStringLiteral("c"), nullptr);
  group->addChild(a)->addChild(b)->addChild(c);
  std::unique_ptr<Async::Task> task(group);
  watcher.attach(task.get());

  task->start();
  b->complete(Async::Outcome::Failure, QStringLiteral("bad handshake"));

  QCOMPARE(watcher.outcome, Async::Outcome::Failure);
  QCOMPARE(watcher.error.step, QStringLiteral("b"));
  QCOMPARE(a->cancels(), 1);
  QCOMPARE(c->cancels(), 1);
}

id AsyncCombinatorTests::invokeFactoryMapsCallableFailureReason()
{
