id AsyncCombinatorTests::retryPolicyBackoffStepCapPlateausPastTwentyFourSteps()
{
  const Async::RetryPolicy policy(100, 1, 100000000, 2.0);

  const int atCap      = policy.delayForAttempt(25);
  const int wayPastCap = policy.delayForAttempt(100000);

  QCOMPARE(atCap, 16777216);
  QCOMPARE(wayPastCap, atCap);
  QVERIFY(atCap > 0);
  QVERIFY(atCap < policy.maxDelayMsec());
}

id AsyncCombinatorTests::retryTaskSetPolicySwapsScheduleBeforeNextRun()
{
  VirtualClock clock;
  Watcher watcher;
  const Async::RetryPolicy original(5, 300, 1200, 2.0);
  const Async::RetryPolicy swapped(5, 50, 200, 2.0);
  auto* child = new FakeStep(QStringLiteral("connect"), nullptr);
  auto task   = std::make_unique<Async::RetryTask>(child, original, clock);
  watcher.attach(task.get());

  task->setPolicy(swapped);
  QCOMPARE(task->policy().initialDelayMsec(), 50);

  task->start();
  child->complete(Async::Outcome::Failure);

  QCOMPARE(clock.delays(), QList<int>({50}));
  QCOMPARE(watcher.count, 0);
}

id AsyncCombinatorTests::signalTaskFailsWhenSenderDestroyedBeforeStart()
{
  Watcher watcher;
  auto sender = std::make_unique<FakeSender>();
  auto task   = std::make_unique<Async::SignalTask>(QStringLiteral("connect"));
  task->onSuccess(sender.get(), &FakeSender::connected);
  watcher.attach(task.get());

  sender.reset();
  task->start();

  QCOMPARE(watcher.count, 1);
  QCOMPARE(watcher.outcome, Async::Outcome::Failure);
  QCOMPARE(watcher.error.step, QStringLiteral("connect"));
  QCOMPARE(watcher.error.reason, QStringLiteral("signal source is gone"));
}

id AsyncCombinatorTests::nestedTreeAggregatesSuccessThroughEveryCombinator()
{
  VirtualClock clock;
  Watcher watcher;
  FakeStep* a = nullptr;
  FakeStep* b = nullptr;
  FakeStep* c = nullptr;
  FakeStep* d = nullptr;
  std::unique_ptr<Async::Task> root(buildNestedTree(clock, a, b, c, d));
  watcher.attach(root.get());

  root->start();
  QCOMPARE(a->starts(), 1);
  QCOMPARE(b->starts(), 1);
  QCOMPARE(c->starts(), 0);
  QCOMPARE(d->starts(), 0);

  a->complete(Async::Outcome::Success);
  b->complete(Async::Outcome::Success);
  QCOMPARE(c->starts(), 1);
  QCOMPARE(clock.pendingCount(), 1);

  c->complete(Async::Outcome::Success);
  QCOMPARE(clock.pendingCount(), 0);
  QCOMPARE(d->starts(), 1);

  d->complete(Async::Outcome::Success);

  QCOMPARE(watcher.count, 1);
  QCOMPARE(watcher.outcome, Async::Outcome::Success);
}

id AsyncCombinatorTests::nestedTreeCancelDuringParallelStagePropagatesToActiveChildren()
{
  VirtualClock clock;
  Watcher watcher;
  FakeStep* a = nullptr;
  FakeStep* b = nullptr;
  FakeStep* c = nullptr;
  FakeStep* d = nullptr;
  std::unique_ptr<Async::Task> root(buildNestedTree(clock, a, b, c, d));
  watcher.attach(root.get());

  root->start();
  root->cancel();

  QCOMPARE(watcher.count, 1);
  QCOMPARE(watcher.outcome, Async::Outcome::Cancelled);
  QCOMPARE(a->cancels(), 1);
  QCOMPARE(b->cancels(), 1);
  QCOMPARE(c->starts(), 0);
  QCOMPARE(d->starts(), 0);
}

id AsyncCombinatorTests::nestedTreeCancelDuringRetryStagePropagatesToActiveChild()
{
  VirtualClock clock;
  Watcher watcher;
  FakeStep* a = nullptr;
  FakeStep* b = nullptr;
  FakeStep* c = nullptr;
  FakeStep* d = nullptr;
  std::unique_ptr<Async::Task> root(buildNestedTree(clock, a, b, c, d));
  watcher.attach(root.get());

  root->start();
  a->complete(Async::Outcome::Success);
  b->complete(Async::Outcome::Success);
  c->complete(Async::Outcome::Success);
  QCOMPARE(d->starts(), 1);

  root->cancel();

  QCOMPARE(watcher.count, 1);
  QCOMPARE(watcher.outcome, Async::Outcome::Cancelled);
  QCOMPARE(d->cancels(), 1);
  QCOMPARE(a->cancels(), 0);
  QCOMPARE(b->cancels(), 0);
  QCOMPARE(c->cancels(), 0);
}

[[nodiscard]] static bool load(DataModel::CFrameParser& parser,
                               const QString& id,
                               const QJsonObject& params)
{
  return parser.loadScript(DataModel::CFrameParser::buildDescriptor(id, params), 0, false);
}

[[nodiscard]] static QJsonObject paramEntry(const QJsonObject& schema, const QString& key)
{
  const auto params = schema.value(QStringLiteral("params")).toArray();
  for (const auto& value : params) {
    const auto entry = value.toObject();
    if (entry.value(QStringLiteral("key")).toString() == key)
      return entry;
  }

  return QJsonObject();
}

static void appendI32Le(QByteArray& bytes, qint32 value)
{
  const auto raw = static_cast<quint32>(value);
  bytes.append(static_cast<char>(raw & 0xFF));
  bytes.append(static_cast<char>((raw >> 8) & 0xFF));
  bytes.append(static_cast<char>((raw >> 16) & 0xFF));
  bytes.append(static_cast<char>((raw >> 24) & 0xFF));
}

void TstCFrameParser::catalogIsCompleteAndUnique()
{
  const auto catalog = DataModel::CFrameParser::templateCatalog();

  QVERIFY(!catalog.isEmpty());
  QCOMPARE(catalog.size(), kTotalTemplateCount);
  QCOMPARE(catalog.size(), DataModel::nativeTemplates().size());

  QStringList ids;
  for (const auto& value : catalog) {
    const QString id = value.toObject().value(QStringLiteral("id")).toString();
    QVERIFY(!id.isEmpty());
    QVERIFY(!ids.contains(id));
    QVERIFY(DataModel::nativeTemplateById(id) != nullptr);
    ids.append(id);
  }

  QCOMPARE(ids.size(), kTotalTemplateCount);
}

