  QFETCH(qint64, expectedNanos);

  const auto captured = IO::makeCapturedData(QByteArray("x"),
                                             IO::CapturedData::SteadyClock::now(),
                                             std::chrono::nanoseconds(requestedNanos));

  QCOMPARE(captured->frameStep.count(), expectedNanos);
}

