id TstLuaCompat::runtimeErrorSurfacesWithoutAborting()
{
  LuaState lua;
  DataModel::installLuaCompat(lua.raw());

  const int status = luaL_dostring(lua.raw(), "error('boom')");
  QVERIFY(status != LUA_OK);

  const char* message = lua_tostring(lua.raw(), -1);
  QVERIFY(message != nullptr);
  QVERIFY(QByteArray(message).contains("boom"));
  lua_pop(lua.raw(), 1);

  const auto error = runOk(lua.raw(), "assert(math.log10(100) == 2)");
  QVERIFY2(error.isEmpty(), error.constData());
}

atic std::vector<API::Mirror::DatasetId> smallFixtureDatasets()
{
  return {
    {0,     0},
    {0,     1},
    {0,     2},
    {0, 10000},
    {0, 10001},
    {0, 10002}
  };
}

atic QJsonObject sampleStructurePayload()
{
  QJsonObject project;
  project.insert(QLatin1String("title"), QLatin1String("Lorenz Attractor"));

  return API::Mirror::encodeStructure(
    7, smallFixtureDatasets(), {0}, project, 0, 10.0, false, 1753459200000);
