  const double inf = std::numeric_limits<double>::infinity();

  QVERIFY(API::Mirror::roundSignificant(0.0, 3) == 0.0);
  QVERIFY(std::isnan(API::Mirror::roundSignificant(nan, 3)));
  QVERIFY(std::isinf(API::Mirror::roundSignificant(inf, 3)));
