  QCOMPARE(static_cast<quint8>(writeAt(writes, 254).at(2)), quint8(0x00));
  QCOMPARE(static_cast<quint8>(writeAt(writes, 255).at(1)), quint8(0x00));
  QCOMPARE(static_cast<quint8>(writeAt(writes, 255).at(2)), quint8(0xFF));
