  Sessions::Export::instance().stopWorker();
  MQTT::Publisher::instance().stopWorker();
  Widgets::AudioExport::instance().stopWorker();
  Widgets::ImageExport::instance().stopWorker();
#endif
}

const QJsonObject& API::GRPC::ProtoGenerator::ledger()
{
  static const QJsonObject entries = [] {
    QFile file(QStringLiteral(":/api/proto-fields.json"));
    if (!file.open(QIODevice::ReadOnly))
      return QJsonObject();

    const auto document = QJsonDocument::fromJson(file.readAll());
    return document.object().value(QStringLiteral("commands")).toObject();
  }();

  return entries;
}

QString API::GRPC::ProtoGenerator::jsonScalar(const QJsonValue& value)
{
  if (value.isString()) {
    auto text = value.toString();
    text.replace(QStringLiteral("\\"), QStringLiteral("\\\\"));
    text.replace(QStringLiteral("\""), QStringLiteral("\\\""));
    return QStringLiteral("\"%1\"").arg(text);
  }

  if (value.isBool())
    return value.toBool() ? QStringLiteral("true") : QStringLiteral("false");

  if (value.isDouble()) {
    const double number = SerialStudio::toDouble(value);
    if (number == std::trunc(number))
      return QString::number(static_cast<qint64>(number));

    return QString::number(number);
  }

  return QStringLiteral("null");
}

QString API::GRPC::ProtoGenerator::commentBlock(const QString& text)
{
  QString folded = text;
  folded.replace(QStringLiteral("\r\n"), QStringLiteral("\n"));
  folded.replace(QStringLiteral("\n"), QStringLiteral("\n  // "));
  return QStringLiteral("  // ") + folded;
}

QString API::GRPC::ProtoGenerator::protoFieldName(const QString& param)
{
  if (param == QStringLiteral("id"))
    return QStringLiteral("id_param");

  return param;
}

QString API::GRPC::ProtoGenerator::fieldComment(const QString& param, const QJsonObject& schema)
{
  QStringList parts;
  if (protoFieldName(param) != param)
    parts.append(QStringLiteral("JSON name: %1").arg(param));

  const auto domain = schema.value(QStringLiteral("enum")).toArray();
  if (!domain.isEmpty()) {
    QStringList values;
    for (const auto& value : domain)
      values.append(jsonScalar(value));

    parts.append(QStringLiteral("enum: ") + values.join(QStringLiteral(", ")));
  }

  if (parts.isEmpty())
    return QString();

  return QStringLiteral("  // ") + parts.join(QStringLiteral("; "));
}

QMap<int, QString> API::GRPC::ProtoGenerator::numberedFields(const QJsonObject& props,
                                                             const QJsonObject& entry)
{
  const auto numbers  = entry.value(QStringLiteral("fields")).toObject();
  const auto reserved = entry.value(QStringLiteral("reserved")).toArray();

  int next = 1;
  for (const auto& value : reserved)
    next = qMax(next, value.toInt());

  for (auto it = numbers.begin(); it != numbers.end(); ++it)
    next = qMax(next, it.value().toInt());

  QMap<int, QString> assigned;
  QStringList pending;
  for (auto it = props.begin(); it != props.end(); ++it) {
    const int number = numbers.value(it.key()).toInt(0);
    if (number > 1)
      assigned.insert(number, it.key());
    else
      pending.append(it.key());
  }

  for (const auto& param : std::as_const(pending))
    assigned.insert(++next, param);

  return assigned;
}

QString API::GRPC::ProtoGenerator::buildMessage(const QString& name,
                                                const QJsonObject& schema,
                                                const QJsonObject& entry)
{
  QString msg;
  QTextStream out(&msg);
  out << "message " << name << " {\n";

  const auto reserved = entry.value(QStringLiteral("reserved")).toArray();
  if (!reserved.isEmpty()) {
    QStringList numbers;
    for (const auto& value : reserved)
      numbers.append(QString::number(value.toInt()));

    out << "  reserved " << numbers.join(QStringLiteral(", ")) << ";\n";
  }

  out << "  string id = 1;\n";

  const auto props  = schema.value(QStringLiteral("properties")).toObject();
  const auto fields = numberedFields(props, entry);
  for (auto it = fields.begin(); it != fields.end(); ++it) {
    const auto field_schema = props.value(it.value()).toObject();
    const auto field_type   = jsonTypeToProtoType(field_schema.value("type").toString());
    out << "  " << field_type << " " << protoFieldName(it.value()) << " = " << it.key() << ";"
        << fieldComment(it.value(), field_schema) << "\n";
  }

  out << "}\n";
  return msg;
}

static QString takeDatasetField(const QJsonObject& params,
                                QSet<QString>& consumed,
                                const QStringList& names)
{
  QString found;
  for (const auto& name : names) {
    if (!params.contains(name))
      continue;

    consumed.insert(name);
    if (found.isEmpty())
      found = name;
  }

  return found;
}

static QString applyDatasetStringFields1(DataModel::Dataset& d,
                                         const QJsonObject& params,
                                         bool& rebuildTree,
                                         QSet<QString>& consumed)
{
  static auto& project = DataModel::ProjectModel::instance();

  const auto key_title = takeDatasetField(params, consumed, {Keys::Title});
  if (!key_title.isEmpty()) {
    d.title = params.value(key_title).toString();
    rebuildTree = true;
  }

  const auto key_units = takeDatasetField(params, consumed, {Keys::Units});
  if (!key_units.isEmpty())
    d.units = params.value(key_units).toString();

  const auto key_alias = takeDatasetField(params, consumed, {Keys::Alias});
  if (!key_alias.isEmpty()) {
    const auto candidate = params.value(key_alias).toString().simplified();
    if (!candidate.isEmpty()
        && PropertyHooks::aliasInUseByOtherDataset(project, candidate, d.uniqueId))
      return QStringLiteral("Alias '%1' is already used by another dataset; aliases must be "
                            "unique across the project").arg(candidate);

    d.alias = candidate;
  }

  const auto key_color = takeDatasetField(params, consumed, {Keys::Color});
  if (!key_color.isEmpty()) {
    const auto candidate = params.value(key_color).toString().simplified();
    if (!PropertyHooks::isValidColor(candidate))
      return QStringLiteral("Invalid color '%1': use '#rrggbb' or a valid color name; empty "
                            "string restores the automatic theme color").arg(candidate);

    d.color = candidate;
  }

  const auto key_widget = takeDatasetField(params, consumed, {Keys::Widget});
  if (!key_widget.isEmpty()) {
    d.widget = params.value(key_widget).toString();
    rebuildTree = true;
  }

  const auto key_display_format = takeDatasetField(params, consumed, {Keys::DisplayFormat});
  if (!key_display_format.isEmpty())
    d.displayFormat = params.value(key_display_format).toString();

  return QString();
}

static QString applyDatasetStringFields2(DataModel::Dataset& d,
                                         const QJsonObject& params,
                                         bool& rebuildTree,
                                         QSet<QString>& consumed)
{
  const auto key_transform_code = takeDatasetField(params, consumed, {Keys::TransformCode});
  if (!key_transform_code.isEmpty())
    d.transformCode = params.value(key_transform_code).toString();

  return QString();
}

static QString applyDatasetNumberFields1(DataModel::Dataset& d,
                                         const QJsonObject& params,
                                         bool& rebuildTree,
                                         QSet<QString>& consumed)
{
  const auto key_index = takeDatasetField(params, consumed, {Keys::Index});
  if (!key_index.isEmpty()) {
    const auto candidate = params.value(key_index).toInt();
    if (!PropertyHooks::isValidDatasetIndex(candidate))
      return QStringLiteral("Invalid index: must be >= 0 (0 = unassigned, 1+ = parser slot)");

    d.index = candidate;
    rebuildTree = true;
  }

  const auto key_plt_min = takeDatasetField(
    params, consumed,
    {QStringLiteral("pltMin"), Keys::PltMin});
  if (!key_plt_min.isEmpty())
    d.pltMin = SerialStudio::toDouble(params.value(key_plt_min));

  const auto key_plt_max = takeDatasetField(
    params, consumed,
    {QStringLiteral("pltMax"), Keys::PltMax});
  if (!key_plt_max.isEmpty())
    d.pltMax = SerialStudio::toDouble(params.value(key_plt_max));

  const auto key_x_axis_id = takeDatasetField(
    params, consumed,
    {QStringLiteral("xAxisId"), Keys::XAxis});
  if (!key_x_axis_id.isEmpty())
    d.xAxisId = params.value(key_x_axis_id).toInt();

  const auto key_fft_ballistics_release = takeDatasetField(
    params, consumed,
    {Keys::FFTBallisticsRelease});
  if (!key_fft_ballistics_release.isEmpty())
    d.fftBallisticsRelease = qBound(50, params.value(key_fft_ballistics_release).toInt(), 5000);

  const auto key_waterfall_y_axis = takeDatasetField(params, consumed, {Keys::WaterfallYAxis});
  if (!key_waterfall_y_axis.isEmpty())
    d.waterfallYAxis = params.value(key_waterfall_y_axis).toInt();

  return QString();
}

static QString applyDatasetNumberFields2(DataModel::Dataset& d,
                                         const QJsonObject& params,
                                         bool& rebuildTree,
                                         QSet<QString>& consumed)
{
  const auto key_fft_samples = takeDatasetField(params, consumed, {Keys::FFTSamples});
  if (!key_fft_samples.isEmpty())
    d.fftSamples = params.value(key_fft_samples).toInt();

  const auto key_fft_window = takeDatasetField(params, consumed, {Keys::FFTWindow});
  if (!key_fft_window.isEmpty()) {
    const auto candidate = params.value(key_fft_window).toInt();
    if (!PropertyHooks::isValidFftWindow(candidate))
      return QStringLiteral("Invalid fftWindow: must be 0-14 (5 = Blackman-Harris)");

    d.fftWindow = candidate;
  }

  const auto key_fft_sampling_rate = takeDatasetField(params, consumed, {Keys::FFTSamplingRate});
  if (!key_fft_sampling_rate.isEmpty())
    d.fftSamplingRate = params.value(key_fft_sampling_rate).toInt();

  const auto key_fft_min = takeDatasetField(params, consumed, {Keys::FFTMin});
  if (!key_fft_min.isEmpty())
    d.fftMin = SerialStudio::toDouble(params.value(key_fft_min));

  const auto key_fft_max = takeDatasetField(params, consumed, {Keys::FFTMax});
  if (!key_fft_max.isEmpty())
    d.fftMax = SerialStudio::toDouble(params.value(key_fft_max));

  const auto key_display_tick_count = takeDatasetField(params, consumed, {Keys::DisplayTickCount});
  if (!key_display_tick_count.isEmpty())
    d.displayTickCount = qMax(0, params.value(key_display_tick_count).toInt());

  return QString();
}

static QString applyDatasetNumberFields3(DataModel::Dataset& d,
                                         const QJsonObject& params,
                                         bool& rebuildTree,
                                         QSet<QString>& consumed)
{
  const auto key_decimal_points = takeDatasetField(params, consumed, {Keys::DecimalPoints});
  if (!key_decimal_points.isEmpty())
    d.decimalPoints = qBound(-1, params.value(key_decimal_points).toInt(), 15);

  const auto key_wgt_min = takeDatasetField(
    params, consumed,
    {QStringLiteral("wgtMin"), Keys::WgtMin});
  if (!key_wgt_min.isEmpty())
    d.wgtMin = SerialStudio::toDouble(params.value(key_wgt_min));

  const auto key_wgt_max = takeDatasetField(
    params, consumed,
    {QStringLiteral("wgtMax"), Keys::WgtMax});
  if (!key_wgt_max.isEmpty())
    d.wgtMax = SerialStudio::toDouble(params.value(key_wgt_max));

  const auto key_led_high = takeDatasetField(params, consumed, {Keys::LedHigh});
  if (!key_led_high.isEmpty())
    d.ledHigh = SerialStudio::toDouble(params.value(key_led_high));

  const auto key_transform_language = takeDatasetField(params, consumed, {Keys::TransformLanguage});
  if (!key_transform_language.isEmpty()) {
    const auto candidate = params.value(key_transform_language).toInt();
    if (!PropertyHooks::isValidTransformLanguage(candidate))
      return QStringLiteral("Invalid transformLanguage: must be -1 (inherit), 0 (JS), or 1 (Lua)");

    d.transformLanguage = candidate;
  }

  const auto key_source_id = takeDatasetField(
    params, consumed,
    {Keys::SourceId, Keys::DatasetSourceId});
  if (!key_source_id.isEmpty())
    d.sourceId = params.value(key_source_id).toInt();

  return QString();
}

static QString applyDatasetFlagFields1(DataModel::Dataset& d,
                                       const QJsonObject& params,
                                       bool& rebuildTree,
                                       QSet<QString>& consumed)
{
  const auto key_virtual = takeDatasetField(params, consumed, {Keys::Virtual});
  if (!key_virtual.isEmpty())
    d.virtual_ = params.value(key_virtual).toBool();

  const auto key_hide_on_dashboard = takeDatasetField(params, consumed, {Keys::HideOnDashboard});
  if (!key_hide_on_dashboard.isEmpty()) {
    d.hideOnDashboard = params.value(key_hide_on_dashboard).toBool();
    rebuildTree = true;
  }

  const auto key_plt = takeDatasetField(params, consumed, {Keys::Graph});
  if (!key_plt.isEmpty()) {
    d.plt = params.value(key_plt).toBool();
    rebuildTree = true;
  }

  const auto key_log = takeDatasetField(params, consumed, {Keys::Log});
  if (!key_log.isEmpty())
    d.log = params.value(key_log).toBool();

  const auto key_plt_log_x = takeDatasetField(params, consumed, {Keys::PltLogX});
  if (!key_plt_log_x.isEmpty())
    d.pltLogX = params.value(key_plt_log_x).toBool();

  const auto key_plt_log_y = takeDatasetField(params, consumed, {Keys::PltLogY});
  if (!key_plt_log_y.isEmpty())
    d.pltLogY = params.value(key_plt_log_y).toBool();

  return QString();
}

static QString applyDatasetFlagFields2(DataModel::Dataset& d,
                                       const QJsonObject& params,
                                       bool& rebuildTree,
                                       QSet<QString>& consumed)
{
  const auto key_fft = takeDatasetField(params, consumed, {Keys::FFT});
  if (!key_fft.isEmpty()) {
    d.fft = params.value(key_fft).toBool();
    rebuildTree = true;
  }

  const auto key_waterfall = takeDatasetField(params, consumed, {Keys::Waterfall});
  if (!key_waterfall.isEmpty()) {
    d.waterfall = params.value(key_waterfall).toBool();
    rebuildTree = true;
  }

  const auto key_fft_ballistics = takeDatasetField(params, consumed, {Keys::FFTBallistics});
  if (!key_fft_ballistics.isEmpty())
    d.fftBallistics = params.value(key_fft_ballistics).toBool();

  const auto key_fft_log_x = takeDatasetField(params, consumed, {Keys::FFTLogX});
  if (!key_fft_log_x.isEmpty())
    d.fftLogX = params.value(key_fft_log_x).toBool();

  const auto key_led = takeDatasetField(params, consumed, {Keys::LED});
  if (!key_led.isEmpty()) {
    d.led = params.value(key_led).toBool();
    rebuildTree = true;
  }

  const auto key_overview_display = takeDatasetField(params, consumed, {Keys::Overview});
  if (!key_overview_display.isEmpty()) {
    d.overviewDisplay = params.value(key_overview_display).toBool();
    rebuildTree = true;
  }

  return QString();
}

static void applyDatasetSubEntityFields(DataModel::Dataset& d,
                                        const QJsonObject& params,
                                        QSet<QString>& consumed)
{
  const auto key_alarm_bands = takeDatasetField(params, consumed, {Keys::AlarmBands});
  const auto key_alarm_enabled = takeDatasetField(params, consumed, {Keys::AlarmEnabled});
  const auto key_alarm_low = takeDatasetField(params, consumed, {Keys::AlarmLow});
  const auto key_alarm_high = takeDatasetField(params, consumed, {Keys::AlarmHigh});
  if (!key_alarm_bands.isEmpty()) {
    d.alarmBands.clear();
    const auto entries = params.value(key_alarm_bands).toArray();
    d.alarmBands.reserve(entries.size());
    for (const auto& entry : entries) {
      DataModel::AlarmBand parsed;
      if (DataModel::read(parsed, entry.toObject()))
        d.alarmBands.push_back(std::move(parsed));
    }
  }
  else if (!key_alarm_enabled.isEmpty() || !key_alarm_low.isEmpty() || !key_alarm_high.isEmpty()) {
    std::optional<bool> enabled;
    if (!key_alarm_enabled.isEmpty())
      enabled = params.value(key_alarm_enabled).toBool();

    std::optional<double> low;
    if (!key_alarm_low.isEmpty())
      low = SerialStudio::toDouble(params.value(key_alarm_low));

    std::optional<double> high;
    if (!key_alarm_high.isEmpty())
      high = SerialStudio::toDouble(params.value(key_alarm_high));

    applySimpleAlarmFields(d, enabled, low, high);
  }

  const auto key_fft_markers = takeDatasetField(params, consumed, {Keys::FFTMarkers});
  if (!key_fft_markers.isEmpty()) {
    d.fftMarkers.clear();
    const auto entries = params.value(key_fft_markers).toArray();
    d.fftMarkers.reserve(entries.size());
    for (const auto& entry : entries) {
      DataModel::FrequencyMarker parsed;
      if (DataModel::read(parsed, entry.toObject()))
        d.fftMarkers.push_back(std::move(parsed));
    }
  }
}

QString API::Handlers::ProjectHandler::applyDatasetUpdateParams(DataModel::Dataset& d,
                                                                const QJsonObject& params,
                                                                bool& rebuildTree,
                                                                QSet<QString>& consumed)
{
  if (auto err = applyDatasetStringFields1(d, params, rebuildTree, consumed); !err.isEmpty())
    return err;

  if (auto err = applyDatasetStringFields2(d, params, rebuildTree, consumed); !err.isEmpty())
    return err;

  if (auto err = applyDatasetNumberFields1(d, params, rebuildTree, consumed); !err.isEmpty())
    return err;

  if (auto err = applyDatasetNumberFields2(d, params, rebuildTree, consumed); !err.isEmpty())
    return err;

  if (auto err = applyDatasetNumberFields3(d, params, rebuildTree, consumed); !err.isEmpty())
    return err;

  if (auto err = applyDatasetFlagFields1(d, params, rebuildTree, consumed); !err.isEmpty())
    return err;

  if (auto err = applyDatasetFlagFields2(d, params, rebuildTree, consumed); !err.isEmpty())
    return err;

  applyDatasetSubEntityFields(d, params, consumed);
  return QString();
}

static QJsonObject datasetSchemaProperty(const char* type,
                                         const char* description,
                                         const QJsonArray& domain)
{
  QJsonObject prop;
  prop.insert(QStringLiteral("type"), QString::fromUtf8(type));
  prop.insert(QStringLiteral("description"), QString::fromUtf8(description));
  if (!domain.isEmpty())
    prop.insert(QStringLiteral("enum"), domain);

  return prop;
}

static void datasetSchemaPart4(QJsonObject& props)
{
  props.insert(Keys::SourceId,
               datasetSchemaProperty("integer",
                                     "Source (device) this dataset belongs to",
                                     QJsonArray()));
}

QJsonObject API::Handlers::datasetFieldSchema()
{
  QJsonObject props;
  datasetSchemaPart1(props);
  datasetSchemaPart2(props);
  datasetSchemaPart3(props);
  datasetSchemaPart4(props);
  return props;
}

[[nodiscard]] static QJsonArray busArray(BusMask scope)
{
  QJsonArray buses;
  for (int i = 0; i < kBusCount; ++i)
    if (scopeCovers(scope, static_cast<Bus>(i)))
      buses.append(busSlug(static_cast<Bus>(i)));

  return buses;
}

[[nodiscard]] static QString supportedSlugs()
{
  QStringList slugs;
  for (int i = 0; i < kBusCount; ++i)
    if (scopeCovers(ConnectionDiagnostics::supportedBuses(), static_cast<Bus>(i)))
      slugs.append(busSlug(static_cast<Bus>(i)));

  return slugs.join(QStringLiteral(", "));
}

[[nodiscard]] static QJsonObject resultToJson(const Result& result)
{
  QJsonObject row;
  row[QStringLiteral("bus")]         = busSlug(result.bus);
  row[QStringLiteral("verdict")]     = verdictName(result.verdict);
  row[QStringLiteral("code")]        = result.code;
  row[QStringLiteral("title")]       = result.title;
  row[QStringLiteral("explanation")] = result.explanation;
  row[QStringLiteral("remedy")]      = result.remedy;
  return row;
}

[[nodiscard]] static QJsonObject countsFor(BusMask scope)
{
  int info    = 0;
  int warning = 0;
  int failure = 0;

  static auto& diagnostics = ConnectionDiagnostics::instance();

  const auto results = diagnostics.results(scope);
  for (const auto& result : results)
    if (result.verdict == Verdict::Failure)
      ++failure;
    else if (result.verdict == Verdict::Warning)
      ++warning;
    else
      ++info;

  QJsonObject counts;
  counts[QStringLiteral("info")]    = info;
  counts[QStringLiteral("warning")] = warning;
  counts[QStringLiteral("failure")] = failure;
  return counts;
}

API::CommandResponse API::Handlers::DiagnosticsHandler::run(const QString& id,
                                                            const QJsonObject& params)
{
  static auto& diagnostics = ConnectionDiagnostics::instance();

  BusMask scope     = ConnectionDiagnostics::supportedBuses();
  const auto busArg = params.value(QStringLiteral("bus")).toString();
  if (!busArg.isEmpty()) {
    Bus bus = Bus::Serial;
    if (!busFromSlug(busArg, bus) || !scopeCovers(scope, bus))
      return CommandResponse::makeError(
        id,
        ErrorCode::InvalidParam,
        QStringLiteral("Unknown bus: %1. Valid values: %2.").arg(busArg, supportedSlugs()));

    scope = busBit(bus);
  }

  const auto probing = ConnectionDiagnostics::probingBuses(scope);
  const int estimate = ConnectionDiagnostics::estimatedMsec(scope);
  diagnostics.run(scope);

  QJsonArray instant;
  const auto results = diagnostics.results(scope);
  for (const auto& result : results)
    instant.append(resultToJson(result));

  QJsonObject result;
  result[QStringLiteral("started")]     = true;
  result[QStringLiteral("running")]     = diagnostics.running();
  result[QStringLiteral("buses")]       = busArray(scope);
  result[QStringLiteral("probing")]     = busArray(probing);
  result[QStringLiteral("instant")]     = instant;
  result[QStringLiteral("estimatedMs")] = estimate;
  result[QStringLiteral("hint")] =
    QStringLiteral("Each instant result has {bus, verdict, code, title, explanation, remedy}; "
                   "remedy holds any shell command verbatim. Poll diagnostics.status until "
                   "running is false, then read every finding with problems.list.");
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::DiagnosticsHandler::status(const QString& id,
                                                               const QJsonObject& params)
{
  Q_UNUSED(params)

  static const auto& diagnostics = ConnectionDiagnostics::instance();
  const auto scope               = ConnectionDiagnostics::supportedBuses();

  QJsonObject result;
  result[QStringLiteral("running")] = diagnostics.running();
  result[QStringLiteral("lastRun")] = diagnostics.lastRunTime();
  result[QStringLiteral("buses")]   = busArray(scope);
  result[QStringLiteral("counts")]  = countsFor(scope);
  result[QStringLiteral("hint")] =
    QStringLiteral("running false means every probe settled. Findings are read with "
                   "problems.list, filtered by checkerId 'diagnostics.serial', "
                   "'diagnostics.bluetooth', 'diagnostics.network', 'diagnostics.broker' or "
                   "'diagnostics.audio'.");
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::MirrorHandler::getInfo(const QString& id,
                                                           const QJsonObject& params)
{
  Q_UNUSED(params)

  static auto& publisher = MirrorPublisher::instance();

  return CommandResponse::makeSuccess(id, publisher.info());
}

API::CommandResponse API::Handlers::MirrorHandler::getStructure(const QString& id,
                                                                const QJsonObject& params)
{
  static auto& publisher = MirrorPublisher::instance();

  const int parts = publisher.structureParts();
  if (parts < 1) {
    return CommandResponse::makeError(
      id,
      Mirror::ErrorCode::StructureTooLarge,
      QStringLiteral("Project is too large to mirror (over %1 structure parts)")
        .arg(Mirror::kMaxStructureParts));
  }

  if (parts == 1 && !params.contains(QStringLiteral("part")))
    return CommandResponse::makeSuccess(id, publisher.structure());

  const int part          = params.value(QStringLiteral("part")).toInt(0);
  const auto chunkPayload = publisher.structureChunk(part);
  if (chunkPayload.isEmpty()) {
    return CommandResponse::makeError(id,
                                      ErrorCode::InvalidParam,
                                      QStringLiteral("Structure part %1 does not exist (parts: %2)")
                                        .arg(QString::number(part), QString::number(parts)));
  }

  return CommandResponse::makeSuccess(id, chunkPayload);
}

static QString severityName(int severity)
{
  if (severity == Misc::ProblemCenter::Error)
    return QStringLiteral("error");

  if (severity == Misc::ProblemCenter::Warning)
    return QStringLiteral("warning");

  return QStringLiteral("info");
}

static int severityFromName(const QString& name)
{
  if (name.compare(QStringLiteral("info"), Qt::CaseInsensitive) == 0)
    return Misc::ProblemCenter::Info;

  if (name.compare(QStringLiteral("warning"), Qt::CaseInsensitive) == 0)
    return Misc::ProblemCenter::Warning;

  if (name.compare(QStringLiteral("error"), Qt::CaseInsensitive) == 0)
    return Misc::ProblemCenter::Error;

  return -1;
}

static QJsonObject findingToJson(const Misc::ProblemCenter::Finding& finding)
{
  QJsonObject row;
  row[QStringLiteral("severity")]       = severityName(finding.severity);
  row[QStringLiteral("checkerId")]      = finding.checkerId;
  row[QStringLiteral("code")]           = finding.code;
  row[QStringLiteral("title")]          = finding.title;
  row[QStringLiteral("explanation")]    = finding.explanation;
  row[QStringLiteral("remedy")]         = finding.remedy;
  row[QStringLiteral("entityUniqueId")] = finding.entityUniqueId;
  row[QStringLiteral("jump")]           = finding.jump;
  return row;
}

static QJsonObject buildFindingsResult(int severity, const QString& checker_id, int limit)
{
  static const auto& center = Misc::ProblemCenter::instance();

  const auto& findings = center.findings();

  int matched = 0;
  QJsonArray rows;
  for (const auto& finding : findings) {
    if (severity >= 0 && static_cast<int>(finding.severity) != severity)
      continue;

    if (!checker_id.isEmpty() && finding.checkerId != checker_id)
      continue;

    ++matched;
    if (rows.size() < limit)
      rows.append(findingToJson(finding));
  }

  QJsonObject counts;
  counts[QStringLiteral("info")]    = center.infoCount();
  counts[QStringLiteral("error")]   = center.errorCount();
  counts[QStringLiteral("warning")] = center.warningCount();

  QJsonObject result;
  result[QStringLiteral("findings")]   = rows;
  result[QStringLiteral("counts")]     = counts;
  result[QStringLiteral("total")]      = center.totalCount();
  result[QStringLiteral("matchCount")] = matched;
  result[QStringLiteral("lastRun")]    = center.lastRunTime();
  result[QStringLiteral("hint")] =
    QStringLiteral("Each finding has {severity, checkerId, code, title, explanation, remedy, "
                   "entityUniqueId, jump}. entityUniqueId >= 0 names the project entity to fix "
                   "-- read it with project.dataset.getByUniqueId or project.group.get. Call "
                   "problems.run to refresh after an edit.");
  return result;
}

API::CommandResponse API::Handlers::ProblemsHandler::list(const QString& id,
                                                          const QJsonObject& params)
{
  int severity           = -1;
  const auto severityStr = params.value(QStringLiteral("severity")).toString();
  if (!severityStr.isEmpty()) {
    severity = severityFromName(severityStr);
    if (severity < 0)
      return CommandResponse::makeError(
        id,
        ErrorCode::InvalidParam,
        QStringLiteral("Unknown severity: %1. Valid values: info, warning, error.")
          .arg(severityStr));
  }

  int limit = params.value(QStringLiteral("limit")).toInt(kDefaultFindings);
  if (limit <= 0)
    limit = kDefaultFindings;

  limit = qMin(limit, kMaxFindings);

  const auto checkerId = params.value(QStringLiteral("checkerId")).toString();
  return CommandResponse::makeSuccess(id, buildFindingsResult(severity, checkerId, limit));
}

API::CommandResponse API::Handlers::ProblemsHandler::run(const QString& id,
                                                         const QJsonObject& params)
{
  Q_UNUSED(params)

  static auto& center = Misc::ProblemCenter::instance();

  center.runNow();
  return CommandResponse::makeSuccess(id, buildFindingsResult(-1, QString(), kDefaultFindings));
}

API::CommandResponse API::Handlers::ProblemsHandler::listCheckers(const QString& id,
                                                                  const QJsonObject& params)
{
  Q_UNUSED(params)

  static const auto& center = Misc::ProblemCenter::instance();

  QJsonArray rows;
  const auto catalog = center.checkerCatalog();
  for (const auto& entry : catalog) {
    const auto map        = entry.toMap();
    const auto triggerIds = map.value(QStringLiteral("triggers")).toStringList();

    QJsonArray triggers;
    for (const auto& trigger : triggerIds)
      triggers.append(trigger);

    QJsonObject row;
    row[QStringLiteral("id")]       = map.value(QStringLiteral("id")).toString();
    row[QStringLiteral("triggers")] = triggers;
    rows.append(row);
  }

  QJsonObject result;
  result[QStringLiteral("checkers")] = rows;
  result[QStringLiteral("total")]    = rows.size();
  result[QStringLiteral("hint")] =
    QStringLiteral("projectChanged runs on project load/edit/save, linkSample on the shared "
                   "1 Hz tick, onDemand only via problems.run.");
  return CommandResponse::makeSuccess(id, result);
}

[[nodiscard]] static QJsonObject datasetUpdateSchema()
{
  auto schema = API::makeSchema({
    {QStringLiteral("groupId"), QStringLiteral("integer"),   QStringLiteral("Target group id")},
    {          Keys::DatasetId, QStringLiteral("integer"), QStringLiteral("Target dataset id")}
  });

  auto properties   = schema.value(QStringLiteral("properties")).toObject();
  const auto fields = API::Handlers::datasetFieldSchema();
  for (auto it = fields.constBegin(); it != fields.constEnd(); ++it)
    properties.insert(it.key(), it.value());

  schema.insert(QStringLiteral("properties"), properties);
  return schema;
}

API::CommandResponse API::Handlers::ProjectHandler::projectRedo(const QString& id,
                                                                const QJsonObject& params)
{
  Q_UNUSED(params);
  static auto& projectModel = DataModel::ProjectModel::instance();

  QJsonObject result;
  if (!projectModel.canRedo()) {
    result[QStringLiteral("performed")] = false;
    result[QStringLiteral("reason")]    = QStringLiteral("nothing to redo");
    attachProjectEpoch(result);
    return CommandResponse::makeSuccess(id, result);
  }

  const QString label = projectModel.redoText();
  projectModel.setSuppressMessageBoxes(true);
  const bool performed = projectModel.redo();
  projectModel.setSuppressMessageBoxes(false);

  if (!performed) {
    result[QStringLiteral("performed")] = false;
    result[QStringLiteral("reason")]    = QStringLiteral("snapshot apply failed");
    attachProjectEpoch(result);
    return CommandResponse::makeSuccess(id, result);
  }

  result[QStringLiteral("performed")] = true;
  result[QStringLiteral("redone")]    = label;
  attachProjectEpoch(result);
  return CommandResponse::makeSuccess(id, result);
}

API::MirrorClient::MirrorClient(QObject* parent)
  : QObject(parent)
  , m_port(0)
  , m_hz(Mirror::kHzDefault)
  , m_attempt(0)
  , m_live(false)
  , m_stale(true)
  , m_authSent(false)
  , m_structurePending(false)
  , m_userClosed(false)
  , m_epoch(0)
  , m_requestCounter(0)
  , m_valueCount(0)
  , m_stage(Stage::Offline)
  , m_chunkParts(0)
  , m_chunkEpoch(0)
{
  m_watchdog.setSingleShot(false);
  m_reconnect.setSingleShot(true);

  connect(&m_watchdog, &QTimer::timeout, this, &MirrorClient::onWatchdog);
  connect(&m_reconnect, &QTimer::timeout, this, &MirrorClient::onReconnect);
  connect(&m_socket, &QTcpSocket::connected, this, &MirrorClient::onConnected);
  connect(&m_socket, &QTcpSocket::readyRead, this, &MirrorClient::onReadyRead);
  connect(&m_socket, &QTcpSocket::disconnected, this, &MirrorClient::onDisconnected);
  connect(&m_socket, &QTcpSocket::errorOccurred, this, &MirrorClient::onSocketError);
}

void API::MirrorClient::open(const QString& host,
                             const quint16 port,
                             const QString& token,
                             const int hz)
{
  SS_ASSERT(!host.isEmpty(), return);
  SS_ASSERT(port > 0, return);

  close();

  m_host          = host;
  m_port          = port;
  m_token         = token;
  m_hz            = qBound(Mirror::kHzMin, hz, Mirror::kHzMax);
  m_endpoint      = QStringLiteral("%1:%2").arg(host, QString::number(port));
  m_attempt       = 0;
  m_userClosed    = false;
  m_lastError     = QString();
  m_lastErrorCode = QString();
  m_stage         = Stage::Connecting;

  m_socket.connectToHost(m_host, m_port);
}

void API::MirrorClient::close()
{
  m_userClosed = true;
  m_reconnect.stop();
  m_watchdog.stop();

  if (m_socket.state() != QAbstractSocket::UnconnectedState)
    m_socket.abort();

  const bool wasLinked = linked();
  m_stage              = Stage::Offline;
  resetStreamState();

  if (wasLinked)
    Q_EMIT linkedChanged();
}

void API::MirrorClient::resetStreamState()
{
  m_buffer.clear();
  m_chunks.clear();
  m_info = QJsonObject();

  m_epoch            = 0;
  m_valueCount       = 0;
  m_chunkParts       = 0;
  m_chunkEpoch       = 0;
  m_authSent         = false;
  m_structurePending = false;
  m_pendingId        = QString();
  m_pendingCommand   = QString();
  m_pendingParams    = QJsonObject();

  setLive(false);
  setStale(true);
}

void API::MirrorClient::onConnected()
{
  SS_ASSERT_LOG(m_stage == Stage::Connecting);

  m_attempt = 0;
  m_stage   = Stage::Subscribing;

  QJsonObject params;
  params.insert(QStringLiteral("wireVersion"), Mirror::kWireVersion);
  params.insert(QStringLiteral("hz"), m_hz);
  params.insert(QStringLiteral("frames"), false);
  sendCommand(QLatin1String(Mirror::Command::Subscribe), params);
}

void API::MirrorClient::onDisconnected()
{
  const bool wasLinked = linked();
  m_stage              = Stage::Offline;
  resetStreamState();

  if (wasLinked)
    Q_EMIT linkedChanged();

  if (!m_userClosed)
    scheduleReconnect();
}

void API::MirrorClient::onSocketError(const QAbstractSocket::SocketError error)
{
  if (m_userClosed)
    return;

  const auto code = (error == QAbstractSocket::ConnectionRefusedError)
                    ? QStringLiteral("MIRROR_REFUSED")
                    : QStringLiteral("MIRROR_UNREACHABLE");
  fail(code, m_socket.errorString());
}

void API::MirrorClient::onReadyRead()
{
  m_buffer += m_socket.readAll();
  if (m_buffer.size() > kMaxBufferBytes) {
    fail(QStringLiteral("MIRROR_OVERFLOW"), tr("Remote sent more data than this viewer can hold"));
    return;
  }

  int lines = 0;
  while (lines < kMaxLinesPerRead) {
    const int newline = m_buffer.indexOf('\n');
    if (newline < 0)
      return;

    ++lines;
    const auto line = m_buffer.left(newline).trimmed();
    m_buffer.remove(0, newline + 1);

    if (!line.isEmpty() && line.size() <= kMaxLineBytes)
      handleLine(line);
  }
}

void API::MirrorClient::handleLine(const QByteArray& line)
{
  QJsonParseError parseError;
  const auto document = QJsonDocument::fromJson(line, &parseError);
  if (parseError.error != QJsonParseError::NoError || !document.isObject())
    return;

  const auto object = document.object();
  const auto push   = object.value(QLatin1String(Mirror::kPushKey));
  if (push.isObject()) {
    handlePush(push.toObject());
    return;
  }

  if (object.value(QStringLiteral("type")).toString() == QStringLiteral("response"))
    handleResponse(object);
}

void API::MirrorClient::handleResponse(const QJsonObject& message)
{
  const bool success = message.value(QStringLiteral("success")).toBool(false);
  const auto result  = message.value(QStringLiteral("result")).toObject();
  const auto error   = message.value(QStringLiteral("error")).toObject();
  const auto id      = message.value(QStringLiteral("id")).toString();

  if (success && result.contains(QStringLiteral("authenticated"))) {
    sendCommand(m_pendingCommand, m_pendingParams);
    return;
  }

  const bool challenge = !success && id.isEmpty() && !m_authSent && isAuthChallenge(error);
  if (challenge) {
    sendAuth();
    return;
  }

  if (id != m_pendingId || m_pendingId.isEmpty())
    return;

  if (!success) {
    fail(error.value(QStringLiteral("code")).toString(),
         error.value(QStringLiteral("message")).toString());
    return;
  }

  if (m_pendingCommand == QLatin1String(Mirror::Command::Subscribe))
    onSubscribed(result);
  else if (m_pendingCommand == QLatin1String(Mirror::Command::GetStructure))
    onStructureFetched(result);
}

void API::MirrorClient::onSubscribed(const QJsonObject& result)
{
  const int version = result.value(QStringLiteral("wireVersion")).toInt(0);
  if (version != Mirror::kWireVersion) {
    fail(QLatin1String(Mirror::ErrorCode::VersionMismatch),
         tr("The remote speaks mirror version %1; this build speaks %2")
           .arg(QString::number(version), QString::number(Mirror::kWireVersion)));
    return;
  }

  m_info      = result;
  m_pendingId = QString();
  m_hz =
    qBound(Mirror::kHzMin, result.value(QStringLiteral("effectiveHz")).toInt(m_hz), Mirror::kHzMax);
  m_stage = Stage::Fetching;

  armWatchdog();
  requestStructure();
}

void API::MirrorClient::onStructureFetched(const QJsonObject& result)
{
  m_pendingId     = QString();
  const auto kind = result.value(QStringLiteral("kind")).toString();

  if (kind == QLatin1String(Mirror::Kind::Structure)) {
    m_structurePending = false;
    adoptStructure(result);
    return;
  }

  if (kind != QLatin1String(Mirror::Kind::StructureChunk)) {
    fail(QStringLiteral("MIRROR_BAD_STRUCTURE"), tr("Remote returned an unreadable structure"));
    return;
  }

  handleChunk(result);
  if (!m_structurePending)
    return;

  QJsonObject params;
  params.insert(QStringLiteral("part"), m_chunks.size());
  sendCommand(QLatin1String(Mirror::Command::GetStructure), params);
}

void API::MirrorClient::handlePush(const QJsonObject& payload)
{
  setStale(false);
  armWatchdog();

  const auto kind = payload.value(QStringLiteral("kind")).toString();
  if (kind == QLatin1String(Mirror::Kind::Snapshot)) {
    handleSnapshot(payload);
    return;
  }

  if (kind == QLatin1String(Mirror::Kind::Structure)) {
    adoptStructure(payload);
    return;
  }

  if (kind == QLatin1String(Mirror::Kind::StructureChunk)) {
    handleChunk(payload);
    return;
  }

  if (kind == QLatin1String(Mirror::Kind::Heartbeat))
    setLive(false);
}

void API::MirrorClient::handleChunk(const QJsonObject& payload)
{
  const auto epoch = static_cast<quint64>(payload.value(QStringLiteral("epoch")).toInteger(0));
  const int parts  = payload.value(QStringLiteral("parts")).toInt(0);
  const int part   = payload.value(QStringLiteral("part")).toInt(-1);

  if (parts < 1 || parts > Mirror::kMaxStructureParts || part < 0 || part >= parts) {
    fail(QLatin1String(Mirror::ErrorCode::StructureTooLarge),
         tr("The remote project is too large to mirror"));
    return;
  }

  if (m_chunkEpoch != epoch) {
    m_chunks.clear();
    m_chunkEpoch = epoch;
    m_chunkParts = parts;
  }

  m_chunks.insert(part, payload.value(QStringLiteral("data")).toString());
  if (m_chunks.size() < m_chunkParts)
    return;

  QString blob;
  for (int i = 0; i < m_chunkParts; ++i)
    blob += m_chunks.value(i);

  m_chunks.clear();
  m_chunkEpoch       = 0;
  m_structurePending = false;

  const auto decoded = QJsonDocument::fromJson(QByteArray::fromBase64(blob.toLatin1()));
  if (!decoded.isObject()) {
    fail(QStringLiteral("MIRROR_BAD_STRUCTURE"), tr("Remote returned an unreadable structure"));
    return;
  }

  adoptStructure(decoded.object());
}

void API::MirrorClient::adoptStructure(const QJsonObject& payload)
{
  if (!verifyStructure(payload))
    return;

  const bool wasLinked = linked();
  m_epoch              = static_cast<quint64>(payload.value(QStringLiteral("epoch")).toInteger(0));
  m_valueCount         = payload.value(QStringLiteral("datasets")).toArray().size();
  m_stage              = Stage::Streaming;

  Q_EMIT structureReceived(payload);

  if (!wasLinked)
    Q_EMIT linkedChanged();
}

bool API::MirrorClient::verifyStructure(const QJsonObject& payload)
{
  const int version = payload.value(QStringLiteral("wireVersion")).toInt(0);
  if (version != Mirror::kWireVersion) {
    fail(QLatin1String(Mirror::ErrorCode::VersionMismatch),
         tr("The remote speaks mirror version %1; this build speaks %2")
           .arg(QString::number(version), QString::number(Mirror::kWireVersion)));
    return false;
  }

  const auto entries = payload.value(QStringLiteral("datasets")).toArray();
  std::vector<Mirror::DatasetId> datasets;
  datasets.reserve(static_cast<std::size_t>(entries.size()));
  for (const auto& entry : entries) {
    const auto pair = entry.toArray();
    datasets.push_back({pair.at(0).toInt(0), pair.at(1).toInt(0)});
  }

  const auto announced = payload.value(QStringLiteral("layoutHash")).toString();
  if (announced != Mirror::layoutHash(datasets)) {
    fail(QStringLiteral("MIRROR_LAYOUT_MISMATCH"),
         tr("The remote's dataset layout does not match its announced hash"));
    return false;
  }

  return true;
}

void API::MirrorClient::handleSnapshot(const QJsonObject& payload)
{
  const auto epoch = static_cast<quint64>(payload.value(QStringLiteral("epoch")).toInteger(0));
  const int count  = payload.value(QStringLiteral("values")).toArray().size();

  if (m_stage != Stage::Streaming || epoch != m_epoch || count != m_valueCount) {
    requestStructure();
    return;
  }

  setLive(true);
  Q_EMIT snapshotReceived(payload);
}

void API::MirrorClient::sendCommand(const QString& command, const QJsonObject& params)
{
  SS_ASSERT(!command.isEmpty(), return);

  if (m_socket.state() != QAbstractSocket::ConnectedState)
    return;

  m_pendingId      = QStringLiteral("mirror-%1").arg(QString::number(++m_requestCounter));
  m_pendingCommand = command;
  m_pendingParams  = params;

  QJsonObject message;
  message.insert(QStringLiteral("type"), QStringLiteral("command"));
  message.insert(QStringLiteral("id"), m_pendingId);
  message.insert(QStringLiteral("command"), command);
  if (!params.isEmpty())
    message.insert(QStringLiteral("params"), params);

  m_socket.write(QJsonDocument(message).toJson(QJsonDocument::Compact) + '\n');
}

void API::MirrorClient::sendAuth()
{
  if (m_token.isEmpty()) {
    fail(QStringLiteral("MIRROR_UNAUTHORIZED"),
         tr("The remote requires a token and none was provided"));
    return;
  }

  m_authSent = true;

  QJsonObject message;
  message.insert(QStringLiteral("type"), QStringLiteral("auth"));
  message.insert(QStringLiteral("token"), m_token);
  m_socket.write(QJsonDocument(message).toJson(QJsonDocument::Compact) + '\n');
}

void API::MirrorClient::requestStructure()
{
  if (m_structurePending)
    return;

  m_structurePending = true;
  sendCommand(QLatin1String(Mirror::Command::GetStructure), QJsonObject());
}

void API::MirrorClient::armWatchdog()
{
  const int ticks = (kWatchdogTicks * 1000) / qMax(1, m_hz);
  m_watchdog.start(qBound(kWatchdogMinMs, ticks, kWatchdogMaxMs));
}

void API::MirrorClient::onWatchdog()
{
  m_watchdog.stop();
  setLive(false);
  setStale(true);
}

void API::MirrorClient::setLive(const bool value)
{
  if (m_live == value)
    return;

  m_live = value;
  Q_EMIT liveChanged();
}

void API::MirrorClient::setStale(const bool value)
{
  if (m_stale == value)
    return;

  m_stale = value;
  Q_EMIT staleChanged();
}

void API::MirrorClient::fail(const QString& code, const QString& message)
{
  m_lastErrorCode = code;
  m_lastError     = message;

  const bool fatal = code == QLatin1String(Mirror::ErrorCode::VersionMismatch)
                  || code == QStringLiteral("MIRROR_UNAUTHORIZED")
                  || code == QLatin1String(Mirror::ErrorCode::ViewerLimit);

  qWarning() << "[Mirror] " << code << message;
  Q_EMIT failed(code, message, fatal);

  if (fatal) {
    close();
    return;
  }

  if (m_socket.state() != QAbstractSocket::UnconnectedState)
    m_socket.abort();
  else if (!m_userClosed)
    scheduleReconnect();
}

void API::MirrorClient::scheduleReconnect()
{
  SS_ASSERT_LOG(!m_userClosed);

  if (m_reconnect.isActive())
    return;

  const int index = qMin(m_attempt, kBackoffMax);
  ++m_attempt;

  m_watchdog.stop();
  setStale(true);
  m_reconnect.start(kBackoffMs[index]);
}

void API::MirrorClient::onReconnect()
{
  if (m_userClosed || m_host.isEmpty())
    return;

  resetStreamState();
  m_stage = Stage::Connecting;
  m_socket.connectToHost(m_host, m_port);
}

static int wireUniqueId(const DataModel::Dataset& dataset)
{
  if (dataset.uniqueId >= 0)
    return dataset.uniqueId;

  return DataModel::dataset_unique_id(dataset.sourceId, dataset.groupId, dataset.datasetId);
}

static QString nonFiniteTag(const double value)
{
  if (std::isnan(value))
    return QString::fromLatin1(API::Mirror::NonFinite::NaN);

  return QString::fromLatin1(value > 0 ? API::Mirror::NonFinite::Infinity
                                       : API::Mirror::NonFinite::NegInfinity);
}

static API::Mirror::SnapshotValue snapshotValue(const DataModel::Dataset& dataset)
{
  API::Mirror::SnapshotValue value;

  if (dataset.isNumeric && std::isfinite(dataset.numericValue)) {
    value.kind   = API::Mirror::SnapshotValue::Kind::Number;
    value.number = dataset.numericValue;
    return value;
  }

  if (dataset.isNumeric) {
    value.kind = API::Mirror::SnapshotValue::Kind::NonFinite;
    value.text = nonFiniteTag(dataset.numericValue);
    return value;
  }

  if (!dataset.value.isEmpty()) {
    value.kind = API::Mirror::SnapshotValue::Kind::Text;
    value.text = dataset.value;
  }

  return value;
}

API::MirrorPublisher::MirrorPublisher(SessionContext& ctx)
  : m_ctx(ctx), m_epoch(1), m_seq(0), m_structureValid(false), m_lastSnapshot(0)
{
  m_clock.start();
  m_heartbeat.setInterval(Mirror::kHeartbeatIntervalMs);
  connect(&m_heartbeat, &QTimer::timeout, this, &MirrorPublisher::onHeartbeatTimeout);
}

API::MirrorPublisher& API::MirrorPublisher::instance()
{
  static MirrorPublisher singleton(SessionContext::current());
  return singleton;
}

int API::MirrorPublisher::maxViewers() const
{
  const int configured = m_settings.value(QStringLiteral("API/MaxViewers"), -1).toInt();
  if (configured < 0)
    return Server::maxClients();

  return qMin(configured, Server::maxClients());
}

int API::MirrorPublisher::effectiveHz(const int hz) const
{
  const int uiHz = m_settings.value(QStringLiteral("uiRefreshRate"), kDefaultUiHz).toInt();
  return qBound(Mirror::kHzMin, qMin(hz, qMax(Mirror::kHzMin, uiHz)), Mirror::kHzMax);
}

bool API::MirrorPublisher::subscribe(QTcpSocket* socket,
                                     const QString& sessionId,
                                     const int hz,
                                     const int precision)
{
  SS_ASSERT(socket != nullptr, return false);
  SS_ASSERT(!sessionId.isEmpty(), return false);

  const bool renewal = m_subscribers.contains(sessionId);
  if (!renewal && m_subscribers.size() >= maxViewers())
    return false;

  Subscriber subscriber;
  subscriber.socket    = socket;
  subscriber.sessionId = sessionId;
  subscriber.hz        = effectiveHz(hz);
  subscriber.precision = qBound(Mirror::kPrecisionMin, precision, Mirror::kPrecisionMax);

  const bool first = m_subscribers.isEmpty();
  m_subscribers.insert(sessionId, subscriber);

  if (first)
    activate();

  Q_EMIT viewersChanged();
  return true;
}

bool API::MirrorPublisher::setRate(const QString& sessionId, const int hz)
{
  SS_ASSERT(!sessionId.isEmpty(), return false);
  SS_ASSERT_LOG(hz >= Mirror::kHzMin && hz <= Mirror::kHzMax);

  const auto it = m_subscribers.find(sessionId);
  if (it == m_subscribers.end())
    return false;

  it->hz = effectiveHz(hz);
  return true;
}

void API::MirrorPublisher::unsubscribe(const QString& sessionId)
{
  if (m_subscribers.remove(sessionId) == 0)
    return;

  if (m_subscribers.isEmpty())
    deactivate();

  Q_EMIT viewersChanged();
}

void API::MirrorPublisher::clearSubscribers()
{
  if (m_subscribers.isEmpty())
    return;

  m_subscribers.clear();
  deactivate();

  Q_EMIT viewersChanged();
}

void API::MirrorPublisher::activate()
{
  SS_ASSERT(!m_subscribers.isEmpty(), return);
  SS_ASSERT_LOG(!m_updatedLink);

  auto* dashboard = &m_ctx.dashboard();
  m_updatedLink =
    connect(dashboard, &UI::Dashboard::updated, this, &MirrorPublisher::onDashboardUpdated);
  m_widgetCountLink = connect(
    dashboard, &UI::Dashboard::widgetCountChanged, this, &MirrorPublisher::onStructureChanged);
  m_dataResetLink =
    connect(dashboard, &UI::Dashboard::dataReset, this, &MirrorPublisher::onStructureChanged);

  invalidateStructure();
  m_lastSnapshot = m_clock.elapsed();
  m_heartbeat.start();
}

void API::MirrorPublisher::deactivate()
{
  SS_ASSERT(m_subscribers.isEmpty(), return);
  SS_ASSERT_LOG(m_heartbeat.isActive() || !m_updatedLink);

  m_heartbeat.stop();
  disconnect(m_updatedLink);
  disconnect(m_widgetCountLink);
  disconnect(m_dataResetLink);

  m_updatedLink     = QMetaObject::Connection();
  m_widgetCountLink = QMetaObject::Connection();
  m_dataResetLink   = QMetaObject::Connection();
}

void API::MirrorPublisher::onStructureChanged()
{
  ++m_epoch;
  invalidateStructure();
}

void API::MirrorPublisher::invalidateStructure()
{
  m_structureValid = false;
  m_structure      = QJsonObject();
  m_structureLines.clear();
}

void API::MirrorPublisher::ensureStructure()
{
  if (m_subscribers.isEmpty())
    invalidateStructure();

  if (!m_structureValid)
    rebuildStructure();
}

void API::MirrorPublisher::rebuildStructure()
{
  auto& dashboard   = m_ctx.dashboard();
  const auto& frame = dashboard.rawFrame();

  m_datasets.clear();
  m_sourceIds.clear();
  for (const auto& group : frame.groups)
    for (const auto& dataset : group.datasets) {
      m_datasets.push_back({dataset.sourceId, wireUniqueId(dataset)});
      m_sourceIds.push_back(dataset.sourceId);
    }

  std::sort(m_sourceIds.begin(), m_sourceIds.end());
  m_sourceIds.erase(std::unique(m_sourceIds.begin(), m_sourceIds.end()), m_sourceIds.end());

  const auto hash = Mirror::layoutHash(m_datasets);
  if (!m_layoutHash.isEmpty() && hash != m_layoutHash)
    ++m_epoch;

  m_layoutHash = hash;
  m_tNs.assign(m_sourceIds.size(), 0);
  m_sourceOrigins.assign(m_sourceIds.size(), -1);

  m_structure = Mirror::encodeStructure(m_epoch,
                                        m_datasets,
                                        m_sourceIds,
                                        m_ctx.projectModel().serializeToJson(),
                                        static_cast<int>(m_ctx.appState().operationMode()),
                                        dashboard.plotTimeRange(),
                                        dashboard.frozen(),
                                        QDateTime::currentMSecsSinceEpoch());

  const auto line = Mirror::encodeLine(m_structure);
  m_structureLines.clear();
  if (line.size() <= Mirror::kStructureChunkBytes)
    m_structureLines.push_back(line);
  else
    for (const auto& chunk : Mirror::chunkStructure(m_structure))
      m_structureLines.push_back(Mirror::encodeLine(chunk));

  m_structureValid = true;
}

int API::MirrorPublisher::structureParts()
{
  ensureStructure();
  return static_cast<int>(m_structureLines.size());
}

QJsonObject API::MirrorPublisher::structure()
{
  ensureStructure();
  return m_structure;
}

QJsonObject API::MirrorPublisher::structureChunk(const int part)
{
  ensureStructure();

  const auto chunks = Mirror::chunkStructure(m_structure);
  if (part < 0 || part >= static_cast<int>(chunks.size()))
    return QJsonObject();

  return chunks[static_cast<std::size_t>(part)];
}

QJsonObject API::MirrorPublisher::info()
{
  const int parts = structureParts();

  QJsonArray sources;
  for (const int sourceId : m_sourceIds)
    sources.append(sourceId);

  QJsonArray commands;
  commands.append(QLatin1String(Mirror::Command::Subscribe));
  commands.append(QLatin1String(Mirror::Command::SetRate));
  commands.append(QLatin1String(Mirror::Command::Unsubscribe));

  QJsonObject result;
  result.insert(QStringLiteral("wireVersion"), Mirror::kWireVersion);
  result.insert(QStringLiteral("appVersion"), QStringLiteral(APP_VERSION));
  result.insert(QStringLiteral("sessionId"), QString::number(m_ctx.sessionId()));
  result.insert(QStringLiteral("epoch"), static_cast<qint64>(m_epoch));
  result.insert(QStringLiteral("layoutHash"), m_layoutHash);
  result.insert(QStringLiteral("operationMode"),
                static_cast<int>(m_ctx.appState().operationMode()));
  result.insert(QStringLiteral("datasetCount"), static_cast<int>(m_datasets.size()));
  result.insert(QStringLiteral("sourceIds"), sources);
  result.insert(QStringLiteral("viewersAllowed"), viewersAllowed());
  result.insert(QStringLiteral("maxViewers"), maxViewers());
  result.insert(QStringLiteral("viewers"), viewers());
  result.insert(QStringLiteral("structureParts"), parts);
  result.insert(QStringLiteral("commands"), commands);
  return result;
}

bool API::MirrorPublisher::due(const Subscriber& subscriber, const qint64 now) const
{
  SS_ASSERT_LOG(subscriber.hz >= Mirror::kHzMin);
  SS_ASSERT_LOG(now >= 0);

  return (now - subscriber.lastSnapshot + kRateSlackMs) * subscriber.hz >= 1000;
}

QByteArray API::MirrorPublisher::snapshotLine(const int precision)
{
  const auto cached = m_tickLines.constFind(precision);
  if (cached != m_tickLines.constEnd())
    return cached.value();

  const auto line =
    Mirror::encodeLine(Mirror::encodeSnapshot(m_epoch, m_seq, m_tNs, m_values, precision));
  m_tickLines.insert(precision, line);
  return line;
}

void API::MirrorPublisher::publishStructure(Subscriber& subscriber)
{
  SS_ASSERT(m_structureValid, return);
  SS_ASSERT(!subscriber.sessionId.isEmpty(), return);

  if (m_structureLines.empty()) {
    qWarning() << "[Mirror] Structure needs more than" << Mirror::kMaxStructureParts
               << "parts - viewer" << subscriber.sessionId << "cannot be served";
    return;
  }

  for (const auto& line : m_structureLines)
    Q_EMIT payloadReady(subscriber.socket, subscriber.sessionId, line);

  subscriber.lastEpoch = m_epoch;
}

bool API::MirrorPublisher::collectValues()
{
  const auto& frame = m_ctx.dashboard().rawFrame();

  m_values.clear();
  m_values.reserve(m_datasets.size());

  for (const auto& group : frame.groups)
    for (const auto& dataset : group.datasets) {
      const auto index = m_values.size();
      if (index >= m_datasets.size() || m_datasets[index].uniqueId != wireUniqueId(dataset))
        return false;

      m_values.push_back(snapshotValue(dataset));
    }

  if (m_values.size() != m_datasets.size())
    return false;

  const qint64 nowNs = m_clock.nsecsElapsed();
  for (std::size_t i = 0; i < m_sourceOrigins.size(); ++i) {
    if (m_sourceOrigins[i] < 0)
      m_sourceOrigins[i] = nowNs;

    m_tNs[i] = nowNs - m_sourceOrigins[i];
  }

  return true;
}

void API::MirrorPublisher::onDashboardUpdated()
{
  SS_ASSERT(!m_subscribers.isEmpty(), return);
  SS_ASSERT_LOG(m_epoch > 0);

  const qint64 now = m_clock.elapsed();
  if (std::none_of(m_subscribers.cbegin(), m_subscribers.cend(), [this, now](const Subscriber& s) {
        return due(s, now);
      }))
    return;

  ensureStructure();
  if (!collectValues()) {
    onStructureChanged();
    return;
  }

  ++m_seq;
  m_lastSnapshot = now;
  m_tickLines.clear();

  for (auto& subscriber : m_subscribers) {
    if (!due(subscriber, now))
      continue;

    if (subscriber.lastEpoch != m_epoch)
      publishStructure(subscriber);

    subscriber.lastSnapshot = now;
    Q_EMIT payloadReady(
      subscriber.socket, subscriber.sessionId, snapshotLine(subscriber.precision));
  }
}

void API::MirrorPublisher::onHeartbeatTimeout()
{
  SS_ASSERT(!m_subscribers.isEmpty(), return);
  SS_ASSERT_LOG(m_heartbeat.isActive());

  if (m_clock.elapsed() - m_lastSnapshot < Mirror::kHeartbeatIntervalMs)
    return;

  const auto line = Mirror::encodeLine(Mirror::encodeHeartbeat(m_epoch, m_seq));
  for (const auto& subscriber : std::as_const(m_subscribers))
    Q_EMIT payloadReady(subscriber.socket, subscriber.sessionId, line);
}

static QString sideValue(const QJsonObject& map, const int index)
{
  if (map.isEmpty())
    return QString();

  return map.value(QString::number(index)).toString();
}

static int wireIndexOf(const QJsonArray& sourceIds, const int sourceId)
{
  for (int i = 0; i < sourceIds.size(); ++i)
    if (sourceIds.at(i).toInt(-1) == sourceId)
      return i;

  return 0;
}

static double nonFiniteValue(const QString& tag)
{
  if (tag == QLatin1String(API::Mirror::NonFinite::NaN))
    return std::numeric_limits<double>::quiet_NaN();

  if (tag == QLatin1String(API::Mirror::NonFinite::NegInfinity))
    return -std::numeric_limits<double>::infinity();

  return std::numeric_limits<double>::infinity();
}

API::MirrorSession::MirrorSession(SessionContext& ctx)
  : m_ctx(ctx)
  , m_client(new MirrorClient(this))
  , m_attached(false)
  , m_canAttach(true)
  , m_anchored(false)
  , m_epoch(0)
{
  connect(m_client, &MirrorClient::failed, this, &MirrorSession::onFailed);
  connect(m_client, &MirrorClient::snapshotReceived, this, &MirrorSession::onSnapshot);
  connect(m_client, &MirrorClient::structureReceived, this, &MirrorSession::onStructure);
  connect(m_client, &MirrorClient::liveChanged, this, &MirrorSession::onLinkStatusChanged);
  connect(m_client, &MirrorClient::staleChanged, this, &MirrorSession::onLinkStatusChanged);
  connect(m_client, &MirrorClient::linkedChanged, this, &MirrorSession::onLinkStatusChanged);

  connect(this,
          &MirrorSession::attachedChanged,
          &m_ctx.dashboard(),
          &UI::Dashboard::updateStreamAvailable,
          Qt::DirectConnection);

  connect(&m_ctx.connectionManager(),
          &IO::ConnectionManager::connectedChanged,
          this,
          &MirrorSession::refreshCanAttach);
  connect(&m_ctx.dashboard(), &UI::Dashboard::dataReset, this, &MirrorSession::refreshCanAttach);

  refreshCanAttach();
}

API::MirrorSession& API::MirrorSession::instance()
{
  static MirrorSession singleton(SessionContext::current());
  return singleton;
}

void API::MirrorSession::attach(const QString& host,
                                const int port,
                                const QString& token,
                                const int hz)
{
  if (host.isEmpty() || port <= 0 || port > 65535) {
    setError(QStringLiteral("MIRROR_BAD_ENDPOINT"), tr("Enter a host name and a port to attach"));
    return;
  }

  refreshCanAttach();
  if (!m_canAttach) {
    setError(QStringLiteral("MIRROR_LOCAL_BUSY"),
             tr("Disconnect the local device or close the open recording before attaching to a "
                "remote dashboard"));
    return;
  }

  if (m_attached)
    detach();

  captureLocalState();
  setError(QString(), QString());
  setAttached(true);

  m_client->open(host, static_cast<quint16>(port), token, hz);
  rememberEndpoint(QStringLiteral("%1:%2").arg(host, QString::number(port)));
}

void API::MirrorSession::detach()
{
  m_client->close();

  if (!m_attached)
    return;

  setAttached(false);
  restoreLocalState();
  refreshCanAttach();
}

void API::MirrorSession::setAttached(const bool value)
{
  if (m_attached == value)
    return;

  m_attached  = value;
  s_mirroring = value;

  if (!value) {
    m_epoch    = 0;
    m_anchored = false;
    m_slots.clear();
    m_frames.clear();
    m_tNsIndex.clear();
    m_tNsAnchor.clear();
  }

  Q_EMIT attachedChanged();
  Q_EMIT statusChanged();
}

void API::MirrorSession::refreshCanAttach()
{
  const bool value = m_attached || !m_ctx.dashboard().streamAvailable();
  if (m_canAttach == value)
    return;

  m_canAttach = value;
  Q_EMIT canAttachChanged();
}

void API::MirrorSession::captureLocalState()
{
  auto& project = m_ctx.projectModel();

  m_local.valid         = true;
  m_local.path          = project.jsonFilePath();
  m_local.project       = project.serializeToJson();
  m_local.frozen        = project.frozen();
  m_local.modified      = project.modified();
  m_local.plotRange     = project.plotTimeRange();
  m_local.operationMode = static_cast<int>(m_ctx.appState().operationMode());
}

void API::MirrorSession::restoreLocalState()
{
  if (!m_local.valid)
    return;

  auto& project   = m_ctx.projectModel();
  auto& appState  = m_ctx.appState();
  const auto mode = static_cast<SerialStudio::OperationMode>(m_local.operationMode);

  appState.setOperationMode(SerialStudio::ProjectFile);
  if (!project.loadFromJsonDocument(QJsonDocument(m_local.project), m_local.path))
    project.newJsonFile();

  project.setPlotTimeRange(m_local.plotRange);
  project.setFrozen(m_local.frozen);
  project.setModified(m_local.modified);
  appState.setOperationMode(mode);

  m_local = LocalState();
}

void API::MirrorSession::rememberEndpoint(const QString& endpoint)
{
  SS_ASSERT(!endpoint.isEmpty(), return);

  auto list = recentEndpoints();
  list.removeAll(endpoint);
  list.prepend(endpoint);
  while (list.size() > kMaxRecentEndpoints)
    list.removeLast();

  m_settings.setValue(QStringLiteral("Mirror/RecentEndpoints"), list);
  Q_EMIT recentEndpointsChanged();
}

void API::MirrorSession::forgetEndpoint(const QString& endpoint)
{
  auto list = recentEndpoints();
  if (list.removeAll(endpoint) <= 0)
    return;

  m_settings.setValue(QStringLiteral("Mirror/RecentEndpoints"), list);
  Q_EMIT recentEndpointsChanged();
}

void API::MirrorSession::onStructure(const QJsonObject& structure)
{
  if (!m_attached)
    return;

  m_epoch    = static_cast<quint64>(structure.value(QStringLiteral("epoch")).toInteger(0));
  m_anchored = false;

  if (!applyRemoteState(structure) || !buildTemplates(structure)) {
    detach();
    return;
  }

  Q_EMIT attachedChanged();
  Q_EMIT statusChanged();
}

bool API::MirrorSession::applyRemoteState(const QJsonObject& structure)
{
  auto& project = m_ctx.projectModel();

  m_ctx.appState().setOperationMode(SerialStudio::ProjectFile);
  const auto document = QJsonDocument(structure.value(QStringLiteral("project")).toObject());
  if (!project.loadFromJsonDocument(document)) {
    setError(QStringLiteral("MIRROR_BAD_PROJECT"),
             tr("The remote sent a project this build cannot load"));
    return false;
  }

  const auto range = SerialStudio::toDouble(structure.value(QStringLiteral("plotTimeRange")));
  if (range > 0)
    project.setPlotTimeRange(range);

  project.setFrozen(structure.value(QStringLiteral("frozen")).toBool(false));
  return true;
}

DataModel::Frame API::MirrorSession::buildSourceFrame(const int sourceId) const
{
  const auto& project = m_ctx.projectModel();

  DataModel::Frame frame;
  frame.sourceId = sourceId;
  frame.title    = project.title();
  frame.actions  = project.actions();

  for (const auto& group : project.groups()) {
    if (!group.enabled || group.sourceId != sourceId)
      continue;

    DataModel::Group runtime = group;
    runtime.datasets.clear();
    for (const auto& dataset : group.datasets)
      if (dataset.enabled)
        runtime.datasets.push_back(dataset);

    frame.groups.push_back(std::move(runtime));
  }

  DataModel::finalize_frame(frame);
  return frame;
}

bool API::MirrorSession::buildTemplates(const QJsonObject& structure)
{
  const auto wireSources = structure.value(QStringLiteral("sourceIds")).toArray();

  std::vector<int> sourceIds;
  for (const auto& value : wireSources)
    sourceIds.push_back(value.toInt(0));

  std::sort(sourceIds.begin(), sourceIds.end());
  sourceIds.erase(std::unique(sourceIds.begin(), sourceIds.end()), sourceIds.end());

  m_slots.clear();
  m_frames.clear();
  m_tNsIndex.clear();

  std::vector<Mirror::DatasetId> identities;
  for (const int sourceId : sourceIds) {
    auto frame = buildSourceFrame(sourceId);
    if (frame.groups.empty())
      continue;

    const int frameIndex = static_cast<int>(m_frames.size());
    for (std::size_t g = 0; g < frame.groups.size(); ++g)
      for (std::size_t d = 0; d < frame.groups[g].datasets.size(); ++d) {
        m_slots.push_back({frameIndex, static_cast<int>(g), static_cast<int>(d)});
        identities.push_back({sourceId, frame.groups[g].datasets[d].uniqueId});
      }

    auto pointer                 = std::make_shared<DataModel::TimestampedFrame>(std::move(frame));
    pointer->structureGeneration = kMirrorGenerationBase + m_epoch;
    m_frames.push_back(std::move(pointer));
    m_tNsIndex.push_back(wireIndexOf(wireSources, sourceId));
  }

  m_tNsAnchor.assign(m_frames.size(), 0);

  const auto announced = structure.value(QStringLiteral("layoutHash")).toString();
  if (announced == Mirror::layoutHash(identities))
    return true;

  setError(QStringLiteral("MIRROR_LAYOUT_MISMATCH"),
           tr("This build resolves the remote project to a different dataset layout"));
  return false;
}

void API::MirrorSession::onSnapshot(const QJsonObject& snapshot)
{
  const auto epoch  = static_cast<quint64>(snapshot.value(QStringLiteral("epoch")).toInteger(0));
  const auto values = snapshot.value(QStringLiteral("values")).toArray();

  if (!m_attached || m_frames.empty() || epoch != m_epoch)
    return;

  if (static_cast<std::size_t>(values.size()) != m_slots.size())
    return;

  assignValues(snapshot);
  publishFrames(snapshot);
}

DataModel::Dataset* API::MirrorSession::datasetAt(const std::size_t index)
{
  SS_ASSERT(index < m_slots.size(), return nullptr);

  const auto& slot = m_slots[index];
  auto& groups     = m_frames[static_cast<std::size_t>(slot.frame)]->data.groups;
  auto& datasets   = groups[static_cast<std::size_t>(slot.group)].datasets;
  return &datasets[static_cast<std::size_t>(slot.dataset)];
}

void API::MirrorSession::assignValues(const QJsonObject& snapshot)
{
  const auto values    = snapshot.value(QStringLiteral("values")).toArray();
  const auto strings   = snapshot.value(QStringLiteral("strings")).toObject();
  const auto nonFinite = snapshot.value(QStringLiteral("nonFinite")).toObject();

  for (int i = 0; i < values.size(); ++i) {
    auto* dataset = datasetAt(static_cast<std::size_t>(i));
    if (!dataset)
      return;

    const auto entry = values.at(i);
    if (entry.isDouble()) {
      dataset->isNumeric       = true;
      dataset->numericValue    = SerialStudio::toDouble(entry);
      dataset->rawNumericValue = dataset->numericValue;
      dataset->value           = QString::number(dataset->numericValue, 'g', kValueDigits);
      dataset->rawValue        = dataset->value;
      continue;
    }

    const auto tag = sideValue(nonFinite, i);
    if (!tag.isEmpty()) {
      dataset->isNumeric       = true;
      dataset->numericValue    = nonFiniteValue(tag);
      dataset->rawNumericValue = dataset->numericValue;
      dataset->value           = tag;
      dataset->rawValue        = tag;
      continue;
    }

    const auto text = sideValue(strings, i);
    if (!text.isEmpty()) {
      dataset->isNumeric    = false;
      dataset->value        = text;
      dataset->rawValue     = text;
      dataset->numericValue = (dataset->wgtMax > dataset->wgtMin) ? dataset->wgtMin : 0.0;
    }
  }
}

void API::MirrorSession::publishFrames(const QJsonObject& snapshot)
{
  const auto times = snapshot.value(QStringLiteral("tNs")).toArray();

  if (!m_anchored) {
    m_anchored    = true;
    m_localAnchor = std::chrono::steady_clock::now();
    for (std::size_t i = 0; i < m_frames.size(); ++i)
      m_tNsAnchor[i] = times.at(m_tNsIndex[i]).toInteger(0);
  }

  auto& dashboard = m_ctx.dashboard();
  for (std::size_t i = 0; i < m_frames.size(); ++i) {
    const qint64 stamp = times.at(m_tNsIndex[i]).toInteger(m_tNsAnchor[i]);
    const auto delta   = std::chrono::nanoseconds(qMax<qint64>(0, stamp - m_tNsAnchor[i]));

    m_frames[i]->timestamp = m_localAnchor + delta;
    dashboard.hotpathRxFrame(m_frames[i]);
  }
}

void API::MirrorSession::onFailed(const QString& code, const QString& message, const bool fatal)
{
  setError(code, message);

  if (fatal && m_attached) {
    detach();
    return;
  }

  Q_EMIT statusChanged();
}

void API::MirrorSession::setError(const QString& code, const QString& message)
{
  if (m_lastErrorCode == code && m_lastError == message)
    return;

  m_lastErrorCode = code;
  m_lastError     = message;
  Q_EMIT lastErrorChanged();
}

void API::ServerWorker::setSocketStreamFrames(QTcpSocket* socket,
                                              const QString& sessionId,
                                              const bool enabled)
{
  SS_ASSERT(socket != nullptr, return);
  SS_ASSERT_LOG(!sessionId.isEmpty());

  if (m_sockets.value(socket) != sessionId)
    return;

  if (enabled)
    m_mutedSockets.remove(socket);
  else
    m_mutedSockets.insert(socket);
}

void API::Server::allowExternalConnections()
{
  if (m_externalConnections) {
    ensureAuthToken();
    return;
  }

  applyExternalConnections(true);
}

bool API::Server::setAuthToken(const QString& token)
{
  const auto trimmed = token.trimmed().toLower();
  if (trimmed.size() < kMinAuthTokenChars)
    return false;

  for (const QChar character : trimmed)
    if (!character.isDigit() && (character < QLatin1Char('a') || character > QLatin1Char('f')))
      return false;

  if (m_authToken == trimmed)
    return true;

  m_authToken = trimmed;
  m_settings.setValue("API/AuthToken", m_authToken);
  Q_EMIT authTokenChanged();
  return true;
}

bool API::Server::isMirrorCommand(const QString& command)
{
  return command == QLatin1String(Mirror::Command::Subscribe)
      || command == QLatin1String(Mirror::Command::SetRate)
      || command == QLatin1String(Mirror::Command::Unsubscribe);
}

API::MirrorPublisher& API::Server::mirrorPublisher()
{
  static auto& publisher = MirrorPublisher::instance();
  if (!m_mirrorLinked) {
    m_mirrorLinked = true;
    connect(&publisher, &MirrorPublisher::payloadReady, this, &Server::sendMirrorPayload);
  }

  return publisher;
}

void API::Server::setStreamFrames(QTcpSocket* socket, ConnectionState& state, const bool enabled)
{
  SS_ASSERT(socket != nullptr, return);
  SS_ASSERT_LOG(!state.sessionId.isEmpty());

  if (state.streamFrames == enabled)
    return;

  state.streamFrames = enabled;
  auto* worker       = static_cast<ServerWorker*>(m_worker);
  QMetaObject::invokeMethod(worker,
                            "setSocketStreamFrames",
                            Qt::QueuedConnection,
                            Q_ARG(QTcpSocket*, socket),
                            Q_ARG(QString, state.sessionId),
                            Q_ARG(bool, enabled));
}

void API::Server::sendMirrorPayload(QTcpSocket* socket,
                                    const QString& sessionId,
                                    const QByteArray& payload)
{
  SS_ASSERT(socket != nullptr, return);
  SS_ASSERT(!payload.isEmpty(), return);

  const auto it = m_connections.constFind(socket);
  if (it == m_connections.constEnd() || it->sessionId != sessionId || !it->mirrorSubscribed)
    return;

  auto* worker = static_cast<ServerWorker*>(m_worker);
  QMetaObject::invokeMethod(worker,
                            "writeToSocket",
                            Qt::QueuedConnection,
                            Q_ARG(QTcpSocket*, socket),
                            Q_ARG(QString, sessionId),
                            Q_ARG(QByteArray, payload));
}

void API::Server::handleMirrorCommand(QTcpSocket* socket,
                                      ConnectionState& state,
                                      const QJsonObject& json)
{
  SS_ASSERT(socket != nullptr, return);
  SS_ASSERT_LOG(!state.sessionId.isEmpty());

  const auto request = CommandRequest::fromJson(json);

  if (request.command == QLatin1String(Mirror::Command::Subscribe))
    sendResponseToSocket(socket, mirrorSubscribe(socket, state, request).toJsonBytes());
  else if (request.command == QLatin1String(Mirror::Command::SetRate))
    sendResponseToSocket(socket, mirrorSetRate(state, request).toJsonBytes());
  else
    sendResponseToSocket(socket, mirrorUnsubscribe(state, request).toJsonBytes());
}

API::CommandResponse API::Server::mirrorSubscribe(QTcpSocket* socket,
                                                  ConnectionState& state,
                                                  const CommandRequest& request)
{
  SS_ASSERT(socket != nullptr,
            return CommandResponse::makeError(
              request.id, ErrorCode::ExecutionError, QStringLiteral("No connection")));
  SS_ASSERT_LOG(state.authenticated);

  const int version = request.params.value(QStringLiteral("wireVersion")).toInt(0);
  if (version != Mirror::kWireVersion) {
    return CommandResponse::makeError(
      request.id,
      QLatin1String(Mirror::ErrorCode::VersionMismatch),
      QStringLiteral("This instance speaks mirror wire version %1, the client asked for %2")
        .arg(QString::number(Mirror::kWireVersion), QString::number(version)));
  }

  const auto hzValue = request.params.value(QStringLiteral("hz"));
  const int hz       = hzValue.isUndefined() ? Mirror::kHzDefault : hzValue.toInt(0);
  if (hz < Mirror::kHzMin || hz > Mirror::kHzMax) {
    return CommandResponse::makeError(
      request.id,
      QLatin1String(Mirror::ErrorCode::RateOutOfRange),
      QStringLiteral("Mirror rate %1 Hz is outside the supported range").arg(QString::number(hz)));
  }

  const int precision = request.params.value(QStringLiteral("precision")).toInt(0);
  if (precision < Mirror::kPrecisionMin || precision > Mirror::kPrecisionMax) {
    return CommandResponse::makeError(
      request.id,
      ErrorCode::InvalidParam,
      QStringLiteral("Value precision %1 is outside 0 (full) to 17 significant digits")
        .arg(QString::number(precision)));
  }

  auto& publisher = mirrorPublisher();
  if (!publisher.subscribe(socket, state.sessionId, hz, precision)) {
    return CommandResponse::makeError(
      request.id,
      QLatin1String(Mirror::ErrorCode::ViewerLimit),
      QStringLiteral("This instance is not accepting more mirror viewers"));
  }

  state.mirrorSubscribed = true;
  state.mirrorHz         = hz;
  state.mirrorPrecision  = precision;
  setStreamFrames(socket, state, request.params.value(QStringLiteral("frames")).toBool(false));

  auto result = publisher.info();
  result.insert(QStringLiteral("connectionId"), state.sessionId);
  result.insert(QStringLiteral("hz"), hz);
  result.insert(QStringLiteral("effectiveHz"), publisher.effectiveHz(hz));
  result.insert(QStringLiteral("frames"), state.streamFrames);
  result.insert(QStringLiteral("precision"), precision);
  return CommandResponse::makeSuccess(request.id, result);
}

API::CommandResponse API::Server::mirrorSetRate(ConnectionState& state,
                                                const CommandRequest& request)
{
  if (!state.mirrorSubscribed) {
    return CommandResponse::makeError(request.id,
                                      QLatin1String(Mirror::ErrorCode::NotSubscribed),
                                      QStringLiteral("This connection holds no mirror "
                                                     "subscription"));
  }

  const int hz = request.params.value(QStringLiteral("hz")).toInt(0);
  if (hz < Mirror::kHzMin || hz > Mirror::kHzMax) {
    return CommandResponse::makeError(
      request.id,
      QLatin1String(Mirror::ErrorCode::RateOutOfRange),
      QStringLiteral("Mirror rate %1 Hz is outside the supported range").arg(QString::number(hz)));
  }

  auto& publisher = mirrorPublisher();
  if (!publisher.setRate(state.sessionId, hz)) {
    return CommandResponse::makeError(request.id,
                                      QLatin1String(Mirror::ErrorCode::NotSubscribed),
                                      QStringLiteral("This connection holds no mirror "
                                                     "subscription"));
  }

  state.mirrorHz = hz;

  QJsonObject result;
  result.insert(QStringLiteral("hz"), hz);
  result.insert(QStringLiteral("effectiveHz"), publisher.effectiveHz(hz));
  return CommandResponse::makeSuccess(request.id, result);
}

API::CommandResponse API::Server::mirrorUnsubscribe(ConnectionState& state,
                                                    const CommandRequest& request)
{
  if (!state.mirrorSubscribed) {
    return CommandResponse::makeError(request.id,
                                      QLatin1String(Mirror::ErrorCode::NotSubscribed),
                                      QStringLiteral("This connection holds no mirror "
                                                     "subscription"));
  }

  mirrorPublisher().unsubscribe(state.sessionId);
  state.mirrorSubscribed = false;

  QJsonObject result;
  result.insert(QStringLiteral("mirrorSubscribed"), false);
  return CommandResponse::makeSuccess(request.id, result);
}

ync::RetryPolicy::RetryPolicy(int max_attempts,
                                int initial_delay_msec,
                                int max_delay_msec,
                                double multiplier)
  : m_multiplier(multiplier)
  , m_maxAttempts(max_attempts)
  , m_maxDelayMsec(max_delay_msec)
  , m_initialDelayMsec(initial_delay_msec)
{
  SS_ASSERT(max_attempts >= 1, m_maxAttempts = 1);
  SS_ASSERT(initial_delay_msec >= 0, m_initialDelayMsec = 0);
  SS_ASSERT(max_delay_msec >= initial_delay_msec, m_maxDelayMsec = m_initialDelayMsec);
  SS_ASSERT(multiplier >= 1.0, m_multiplier = 1.0);
}

ync::RetryPolicy Async::RetryPolicy::autoReconnect()
{
  return RetryPolicy(
    kReconnectAttempts, kReconnectInitialMsec, kReconnectCeilingMsec, kReconnectGrowth);
}

ol Async::RetryPolicy::shouldRetry(int completed_attempts) const noexcept
{
  SS_ASSERT(completed_attempts >= 0, return false);
  SS_ASSERT(m_maxAttempts >= 1, return false);

  return completed_attempts >= 1 && completed_attempts < m_maxAttempts;
}

t Async::RetryPolicy::delayForAttempt(int completed_attempts) const noexcept
{
  SS_ASSERT(completed_attempts >= 1, return m_initialDelayMsec);
  SS_ASSERT(m_maxDelayMsec >= m_initialDelayMsec, return m_maxDelayMsec);

  const int steps  = qBound(0, completed_attempts - 1, kBackoffStepCap);
  const double top = static_cast<double>(m_maxDelayMsec);
  double delay     = static_cast<double>(m_initialDelayMsec);

  for (int i = 0; i < steps && delay < top; ++i)
    delay *= m_multiplier;

  return qBound(0, static_cast<int>(delay), m_maxDelayMsec);
}

ync::Task::Task(QString name, QObject* parent)
  : QObject(parent), m_running(false), m_finished(false), m_name(std::move(name))
{
  SS_ASSERT(!m_name.isEmpty(), m_name = QStringLiteral("task"));
  SS_ASSERT_LOG(!m_running);
}

id Async::Task::start()
{
  SS_ASSERT(!m_running, return);
  SS_ASSERT(thread() == QThread::currentThread(), return);

  m_running  = true;
  m_finished = false;
  doStart();
}

id Async::Task::cancel()
{
  SS_ASSERT(thread() == QThread::currentThread(), return);

  if (!m_running)
    return;

  doCancel();

  if (m_running)
    reportFinished(Outcome::Cancelled, errorHere(QStringLiteral("cancelled")));
}

ync::StepError Async::Task::errorHere(const QString& reason) const
{
  SS_ASSERT_LOG(!m_name.isEmpty());
  SS_ASSERT_LOG(!reason.isEmpty());

  StepError error;
  error.step   = m_name;
  error.reason = reason;
  return error;
}

id Async::Task::reportFinished(Outcome outcome, const StepError& error)
{
  SS_ASSERT(m_running, return);
  SS_ASSERT(!m_finished, return);

  m_running  = false;
  m_finished = true;
  Q_EMIT finished(outcome, error);
}

ync::Group::Group(QString name, QObject* parent)
  : Task(std::move(name), parent), m_cancelling(false)
{
  SS_ASSERT_LOG(!m_cancelling);
  SS_ASSERT_LOG(m_children.isEmpty());
}

ync::Group* Async::Group::addChild(Task* child)
{
  SS_ASSERT(child != nullptr, return this);
  SS_ASSERT_LOG(!child->isRunning());

  child->setParent(this);
  m_children.append(child);
  connect(child, &Task::finished, this, [this, child](Outcome outcome, const StepError& error) {
    onChildFinished(child, outcome, error);
  });

  return this;
}

ync::Task* Async::Group::childAt(int index) const
{
  SS_ASSERT(index >= 0, return nullptr);
  SS_ASSERT(index < m_children.size(), return nullptr);

  return m_children.at(index);
}

id Async::Group::doCancel()
{
  SS_ASSERT_LOG(isRunning());

  cancelChildren();
}

id Async::Group::cancelChildren()
{
  SS_ASSERT(!m_cancelling, return);

  m_cancelling = true;
  for (int i = 0; i < m_children.size(); ++i) {
    Task* child = m_children.at(i);
    if (child->isRunning())
      child->cancel();
  }

  m_cancelling = false;
}

ync::SequentialGroup::SequentialGroup(QString name, QObject* parent)
  : Group(std::move(name), parent), m_index(0)
{
  SS_ASSERT_LOG(m_index == 0);
  SS_ASSERT_LOG(childCount() == 0);
}

id Async::SequentialGroup::doStart()
{
  SS_ASSERT_LOG(isRunning());

  m_index = 0;
  if (childCount() == 0) {
    reportFinished(Outcome::Success, StepError());
    return;
  }

  childAt(m_index)->start();
}

id Async::SequentialGroup::onChildFinished(Task* child, Outcome outcome, const StepError& error)
{
  SS_ASSERT_LOG(child != nullptr);

  if (!isRunning() || isCancelling())
    return;

  SS_ASSERT_LOG(m_index < childCount());
  if (outcome != Outcome::Success) {
    reportFinished(outcome, error);
    return;
  }

  ++m_index;
  if (m_index >= childCount()) {
    reportFinished(Outcome::Success, StepError());
    return;
  }

  childAt(m_index)->start();
}

ync::ParallelGroup::ParallelGroup(QString name, QObject* parent)
  : Group(std::move(name), parent), m_pending(0)
{
  SS_ASSERT_LOG(m_pending == 0);
  SS_ASSERT_LOG(childCount() == 0);
}

id Async::ParallelGroup::doStart()
{
  SS_ASSERT_LOG(isRunning());

  m_pending = childCount();
  if (m_pending == 0) {
    reportFinished(Outcome::Success, StepError());
    return;
  }

  for (int i = 0; i < childCount() && isRunning(); ++i)
    childAt(i)->start();
}

id Async::ParallelGroup::onChildFinished(Task* child, Outcome outcome, const StepError& error)
{
  SS_ASSERT_LOG(child != nullptr);

  if (!isRunning() || isCancelling())
    return;

  SS_ASSERT_LOG(m_pending > 0);
  --m_pending;
  if (outcome != Outcome::Success) {
    cancelChildren();
    reportFinished(outcome, error);
    return;
  }

  if (m_pending <= 0)
    reportFinished(Outcome::Success, StepError());
}

ync::TimeoutTask::TimeoutTask(Task* child, int msec, AsyncClock& clock, QObject* parent)
  : Task(child != nullptr ? child->name() : QStringLiteral("timeout"), parent)
  , m_expired(false)
  , m_msec(msec)
  , m_timer(kInvalidTimerId)
  , m_child(child)
  , m_clock(&clock)
{
  SS_ASSERT(child != nullptr, return);
  SS_ASSERT(msec >= 0, m_msec = 0);

  m_child->setParent(this);
  connect(m_child, &Task::finished, this, &TimeoutTask::onChildFinished);
}

id Async::TimeoutTask::doStart()
{
  SS_ASSERT(m_child != nullptr, {
    reportFinished(Outcome::Failure, errorHere(QStringLiteral("no child")));
    return;
  });
  SS_ASSERT(m_timer == kInvalidTimerId, stopTimer());

  m_expired = false;
  m_timer   = m_clock->schedule(m_msec, [this]() { onExpired(); });
  m_child->start();
}

id Async::TimeoutTask::doCancel()
{
  SS_ASSERT(m_child != nullptr, {
    stopTimer();
    return;
  });
  SS_ASSERT_LOG(isRunning());

  stopTimer();
  if (m_child->isRunning())
    m_child->cancel();
}

id Async::TimeoutTask::stopTimer()
{
  SS_ASSERT(m_clock != nullptr, {
    m_timer = kInvalidTimerId;
    return;
  });

  if (m_timer == kInvalidTimerId)
    return;

  m_clock->cancel(m_timer);
  m_timer = kInvalidTimerId;
}

id Async::TimeoutTask::onExpired()
{
  SS_ASSERT(m_child != nullptr, {
    m_timer = kInvalidTimerId;
    return;
  });

  m_timer = kInvalidTimerId;
  if (!isRunning())
    return;

  m_expired = true;
  if (m_child->isRunning())
    m_child->cancel();

  const QString reason = QStringLiteral("timed out after %1 ms").arg(m_msec);
  reportFinished(Outcome::TimedOut, errorHere(reason));
}

id Async::TimeoutTask::onChildFinished(Outcome outcome, const StepError& error)
{
  SS_ASSERT_LOG(m_child != nullptr);

  if (!isRunning() || m_expired)
    return;

  stopTimer();
  reportFinished(outcome, error);
}

ync::RetryTask::RetryTask(Task* child,
                            const RetryPolicy& policy,
                            AsyncClock& clock,
                            QObject* parent)
  : Task(child != nullptr ? child->name() : QStringLiteral("retry"), parent)
  , m_attempt(0)
  , m_timer(kInvalidTimerId)
  , m_child(child)
  , m_clock(&clock)
  , m_policy(policy)
{
  SS_ASSERT(child != nullptr, return);
  SS_ASSERT_LOG(policy.maxAttempts() >= 1);

  m_child->setParent(this);
  connect(m_child, &Task::finished, this, &RetryTask::onChildFinished);
}

id Async::RetryTask::setPolicy(const RetryPolicy& policy)
{
  SS_ASSERT(!isRunning(), return);
  SS_ASSERT(policy.maxAttempts() >= 1, return);

  m_policy = policy;
}

id Async::RetryTask::doStart()
{
  SS_ASSERT(m_child != nullptr, {
    reportFinished(Outcome::Failure, errorHere(QStringLiteral("no child")));
    return;
  });
  SS_ASSERT(m_timer == kInvalidTimerId, stopTimer());

  m_attempt = 0;
  beginAttempt();
}

id Async::RetryTask::doCancel()
{
  SS_ASSERT(m_child != nullptr, {
    stopTimer();
    return;
  });
  SS_ASSERT_LOG(isRunning());

  stopTimer();
  if (m_child->isRunning())
    m_child->cancel();
}

id Async::RetryTask::stopTimer()
{
  SS_ASSERT(m_clock != nullptr, {
    m_timer = kInvalidTimerId;
    return;
  });

  if (m_timer == kInvalidTimerId)
    return;

  m_clock->cancel(m_timer);
  m_timer = kInvalidTimerId;
}

id Async::RetryTask::beginAttempt()
{
  SS_ASSERT(m_child != nullptr, return);
  SS_ASSERT(!m_child->isRunning(), return);

  ++m_attempt;
  m_child->start();
}

id Async::RetryTask::onBackoffElapsed()
{
  SS_ASSERT(m_child != nullptr, {
    m_timer = kInvalidTimerId;
    return;
  });

  m_timer = kInvalidTimerId;
  if (!isRunning())
    return;

  beginAttempt();
}

id Async::RetryTask::onChildFinished(Outcome outcome, const StepError& error)
{
  SS_ASSERT_LOG(m_child != nullptr);

  if (!isRunning())
    return;

  SS_ASSERT(m_attempt >= 1, m_attempt = 1);
  if (outcome == Outcome::Success) {
    resetAttempts();
    reportFinished(Outcome::Success, StepError());
    return;
  }

  if (outcome == Outcome::Cancelled || !m_policy.shouldRetry(m_attempt)) {
    reportFinished(outcome, error);
    return;
  }

  const int delay = m_policy.delayForAttempt(m_attempt);
  m_timer         = m_clock->schedule(delay, [this]() { onBackoffElapsed(); });
}

ync::SignalTask::SignalTask(QString name, QObject* parent) : Task(std::move(name), parent)
{
  SS_ASSERT_LOG(m_factories.isEmpty());
  SS_ASSERT_LOG(m_connections.isEmpty());
}

id Async::SignalTask::setAbortHandler(AbortHandler handler)
{
  SS_ASSERT(!isRunning(), return);
  SS_ASSERT(static_cast<bool>(handler), return);

  m_abort = std::move(handler);
}

id Async::SignalTask::doStart()
{
  SS_ASSERT(!m_factories.isEmpty(), {
    reportFinished(Outcome::Failure, errorHere(QStringLiteral("no source")));
    return;
  });
  SS_ASSERT(m_connections.isEmpty(), releaseConnections());

  for (int i = 0; i < m_factories.size(); ++i) {
    const QMetaObject::Connection link = m_factories.at(i)();
    if (link)
      m_connections.append(link);
  }

  if (m_connections.size() != m_factories.size()) {
    releaseConnections();
    reportFinished(Outcome::Failure, errorHere(QStringLiteral("signal source is gone")));
    return;
  }

  for (int i = 0; i < m_senders.size(); ++i) {
    QObject* sender = m_senders.at(i).data();
    if (sender == nullptr)
      continue;

    m_connections.append(connect(sender, &QObject::destroyed, this, [this]() {
      fail(QStringLiteral("signal source destroyed"));
    }));
  }
}

id Async::SignalTask::doCancel()
{
  SS_ASSERT_LOG(isRunning());

  releaseConnections();
  if (m_abort)
    m_abort();
}

id Async::SignalTask::succeed()
{
  SS_ASSERT_LOG(!m_factories.isEmpty());

  if (!isRunning())
    return;

  releaseConnections();
  reportFinished(Outcome::Success, StepError());
}

id Async::SignalTask::releaseConnections()
{
  for (int i = 0; i < m_connections.size(); ++i)
    QObject::disconnect(m_connections.at(i));

  m_connections.clear();
  SS_ASSERT_LOG(m_connections.isEmpty());
}

id Async::SignalTask::fail(const QString& reason)
{
  SS_ASSERT_LOG(!reason.isEmpty());

  if (!isRunning())
    return;

  releaseConnections();
  reportFinished(Outcome::Failure, errorHere(reason));
}

id Async::SignalTask::trackSender(QObject* sender)
{
  SS_ASSERT(sender != nullptr, return);
  SS_ASSERT(!isRunning(), return);

  const QPointer<QObject> guard(sender);
  if (!m_senders.contains(guard))
    m_senders.append(guard);
}

ync::InvokeTask::InvokeTask(QString name, Callable callable, QObject* parent)
  : Task(std::move(name), parent), m_callable(std::move(callable))
{
  SS_ASSERT_LOG(static_cast<bool>(m_callable));
  SS_ASSERT_LOG(!isRunning());
}

id Async::InvokeTask::doStart()
{
  SS_ASSERT_LOG(isRunning());
  SS_ASSERT(static_cast<bool>(m_callable), {
    reportFinished(Outcome::Failure, errorHere(QStringLiteral("no action")));
    return;
  });

  QString reason;
  const bool ok = m_callable(reason);
  if (ok) {
    reportFinished(Outcome::Success, StepError());
    return;
  }

  if (reason.isEmpty())
    reason = QStringLiteral("step failed");

  reportFinished(Outcome::Failure, errorHere(reason));
}

ync::TaskRunner::TaskRunner(AsyncClock* clock, QObject* parent)
  : QObject(parent)
  , m_thread(QThread::currentThread())
  , m_clock(clock)
  , m_ownedClock(clock != nullptr ? nullptr : std::make_unique<SystemClock>())
{
  SS_ASSERT_LOG(m_thread != nullptr);
  SS_ASSERT_LOG(m_thread == thread());

  if (m_clock == nullptr)
    m_clock = m_ownedClock.get();
}

ync::AsyncClock& Async::TaskRunner::clock() const noexcept
{
  SS_ASSERT_LOG(m_clock != nullptr);

  return *m_clock;
}

id Async::TaskRunner::cancel()
{
  SS_ASSERT(m_thread == QThread::currentThread(), return);

  if (m_root == nullptr || !m_root->isRunning())
    return;

  m_root->cancel();
}

id Async::TaskRunner::run(Task* root)
{
  SS_ASSERT(root != nullptr, return);
  SS_ASSERT(m_thread == QThread::currentThread(), return);

  stopRoot();
  m_root.reset(root);
  m_rootConnection = connect(m_root.get(), &Task::finished, this, &TaskRunner::onRootFinished);
  m_root->start();
}

id Async::TaskRunner::stopRoot()
{
  if (m_root == nullptr)
    return;

  QObject::disconnect(m_rootConnection);
  m_rootConnection = QMetaObject::Connection();

  if (m_root->isRunning())
    m_root->cancel();

  m_root.reset();
}

id Async::TaskRunner::onRootFinished(Outcome outcome, const StepError& error)
{
  SS_ASSERT_LOG(m_root != nullptr);
  SS_ASSERT_LOG(m_thread == QThread::currentThread());

  Q_EMIT finished(outcome, error);
}

ync::Task* Async::onDone(Task* task, std::function<void(Outcome, const StepError&)> handler)
{
  SS_ASSERT(task != nullptr, return nullptr);
  SS_ASSERT(static_cast<bool>(handler), return task);

  QObject::connect(task, &Task::finished, task, std::move(handler));
  return task;
}

