static bool applyDatasetStringEdit(int formId, const QVariant& value, DataModel::Dataset& d)
{
  switch (formId) {
    case kDatasetView_Title:
      d.title = value.toString();
      return true;
    case kDatasetView_Units:
      d.units = value.toString();
      return true;
    case kDatasetView_Alias:
      d.alias = value.toString().simplified();
      return true;
    case kDatasetView_Color:
      d.color = value.toString().simplified();
      return true;
    case kDatasetView_TransformCode:
      d.transformCode = value.toString();
      return true;
    default:
      return false;
  }
}

static bool applyDatasetChoiceEdit(int formId,
                                   const QVariant& value,
                                   DataModel::Dataset& d,
                                   const DataModel::ProjectModel& pm)
{
  switch (formId) {
    case kDatasetView_Plot:
      d.plt = Registry::plotOptions().firstForIndex(value.toInt());
      d.log = Registry::plotOptions().secondForIndex(value.toInt());
      return true;
    case kDatasetView_xAxis:
      d.xAxisId = Registry::xAxisSourcesOptions().valueForIndex(pm, value.toInt()).toInt();
      return true;
    case kDatasetView_WaterfallYAxis:
      d.waterfallYAxis =
        Registry::waterfallYSourcesOptions().valueForIndex(pm, value.toInt()).toInt();
      return true;
    case kDatasetView_FFT_Samples:
      d.fftSamples = Registry::fftSampleCountsOptions().valueForIndex(pm, value.toInt()).toInt();
      return true;
    case kDatasetView_FFT_Window:
      d.fftWindow = Registry::fftWindowsOptions().valueForIndex(pm, value.toInt()).toInt();
      return true;
    case kDatasetView_Widget:
      d.widget = Registry::datasetWidgetsOptions().valueForIndex(pm, value.toInt()).toString();
      return true;
    case kDatasetView_DisplayFormat:
      d.displayFormat =
        Registry::displayFormatsOptions().valueForIndex(pm, value.toInt()).toString();
      return true;
    default:
      return false;
  }
}

static bool applyDatasetNumberEdit(int formId, const QVariant& value, DataModel::Dataset& d)
{
  switch (formId) {
    case kDatasetView_Index:
      d.index = value.toInt();
      return true;
    case kDatasetView_PltMin:
      d.pltMin = SerialStudio::toDouble(value);
      return true;
    case kDatasetView_PltMax:
      d.pltMax = SerialStudio::toDouble(value);
      return true;
    case kDatasetView_FFT_BallisticsRelease:
      d.fftBallisticsRelease = qBound(50, value.toInt(), 5000);
      return true;
    case kDatasetView_FFT_SamplingRate:
      d.fftSamplingRate = value.toInt();
      return true;
    case kDatasetView_FFTMin:
      d.fftMin = SerialStudio::toDouble(value);
      return true;
    case kDatasetView_FFTMax:
      d.fftMax = SerialStudio::toDouble(value);
      return true;
    case kDatasetView_DisplayTickCount:
      d.displayTickCount = qMax(0, value.toInt());
      return true;
    case kDatasetView_DecimalPoints:
      d.decimalPoints = qMax(-1, value.toInt());
      return true;
    case kDatasetView_WgtMin:
      d.wgtMin = SerialStudio::toDouble(value);
      return true;
    case kDatasetView_WgtMax:
      d.wgtMax = SerialStudio::toDouble(value);
      return true;
    case kDatasetView_LED_High:
      d.ledHigh = SerialStudio::toDouble(value);
      return true;
    default:
      return false;
  }
}

static bool applyDatasetFlagEdit(int formId, const QVariant& value, DataModel::Dataset& d)
{
  switch (formId) {
    case kDatasetView_Virtual:
      d.virtual_ = value.toBool();
      return true;
    case kDatasetView_HideOnDashboard:
      d.hideOnDashboard = value.toBool();
      return true;
    case kDatasetView_Plt_LogX:
      d.pltLogX = value.toBool();
      return true;
    case kDatasetView_Plt_LogY:
      d.pltLogY = value.toBool();
      return true;
    case kDatasetView_FFT:
      d.fft = value.toBool();
      return true;
    case kDatasetView_Waterfall:
      d.waterfall = value.toBool();
      return true;
    case kDatasetView_FFT_Ballistics:
      d.fftBallistics = value.toBool();
      return true;
    case kDatasetView_FFT_LogX:
      d.fftLogX = value.toBool();
      return true;
    case kDatasetView_LED:
      d.led = value.toBool();
      return true;
    default:
      return false;
  }
}

static RebuildHint datasetCommitHook(int formId, DataModel::Dataset& d)
{
  switch (formId) {
    case kDatasetView_Title:
      return PropertyHooks::onTitleChanged(d);
    case kDatasetView_Virtual:
      return PropertyHooks::onVirtualChanged(d);
    case kDatasetView_Plot:
      return PropertyHooks::onReshape(d);
    case kDatasetView_xAxis:
      return PropertyHooks::onXAxisChanged(d);
    case kDatasetView_FFT:
      return PropertyHooks::onReshape(d);
    case kDatasetView_Waterfall:
      return PropertyHooks::onReshape(d);
    case kDatasetView_Widget:
      return PropertyHooks::onWidgetChanged(d);
    case kDatasetView_LED:
      return PropertyHooks::onReshape(d);
    default:
      return RebuildHint::None;
  }
}

RebuildHint Registry::applyDatasetFormEdit(int formId,
                                          const QVariant& value,
                                          DataModel::Dataset& d,
                                          const DataModel::ProjectModel& pm)
{
  const bool handled = applyDatasetStringEdit(formId, value, d)
                       || applyDatasetChoiceEdit(formId, value, d, pm)
                       || applyDatasetNumberEdit(formId, value, d)
                       || applyDatasetFlagEdit(formId, value, d);
  if (!handled)
    return RebuildHint::None;

  return datasetCommitHook(formId, d);
}

static bool datasetRowVisible(int formId,
                              const DataModel::Dataset& d,
                              const DataModel::ProjectModel& pm)
{
  switch (formId) {
    case kDatasetView_HideOnDashboard:
      return PropertyHooks::insidePainterGroup(d, pm);
    case kDatasetView_WaterfallYAxis:
      return PropertyHooks::waterfallEnabled(d, pm);
    case kDatasetView_LED_High:
      return PropertyHooks::ledBandsAbsent(d, pm);
    default:
      return true;
  }
}

QVariant Registry::datasetFormValue(int formId,
                                    const DataModel::Dataset& d,
                                    const DataModel::ProjectModel& pm)
{
  if (!datasetRowVisible(formId, d, pm))
    return {};

  switch (formId) {
    case kDatasetView_Title:
      return d.title;
    case kDatasetView_Virtual:
      return d.virtual_;
    case kDatasetView_HideOnDashboard:
      return d.hideOnDashboard;
    case kDatasetView_Index:
      return d.index;
    case kDatasetView_Units:
      return d.units;
    case kDatasetView_Alias:
      return d.alias;
    case kDatasetView_Color:
      return d.color;
    case kDatasetView_PltMin:
      return d.pltMin;
    case kDatasetView_PltMax:
      return d.pltMax;
    case kDatasetView_Plot:
      return Registry::plotOptions().indexForPair(d.plt, d.log);
    case kDatasetView_xAxis:
      return Registry::xAxisSourcesOptions().indexForValue(pm, d.xAxisId);
    case kDatasetView_Plt_LogX:
      return d.pltLogX;
    case kDatasetView_Plt_LogY:
      return d.pltLogY;
    case kDatasetView_FFT:
      return d.fft;
    case kDatasetView_Waterfall:
      return d.waterfall;
    case kDatasetView_FFT_Ballistics:
      return d.fftBallistics;
    case kDatasetView_FFT_BallisticsRelease:
      return d.fftBallisticsRelease;
    case kDatasetView_WaterfallYAxis:
      return Registry::waterfallYSourcesOptions().indexForValue(pm, d.waterfallYAxis);
    case kDatasetView_FFT_Samples:
      return Registry::fftSampleCountsOptions().indexForValue(pm, d.fftSamples);
    case kDatasetView_FFT_Window:
      return Registry::fftWindowsOptions().indexForValue(pm, d.fftWindow);
    case kDatasetView_FFT_SamplingRate:
      return d.fftSamplingRate;
    case kDatasetView_FFT_LogX:
      return d.fftLogX;
    case kDatasetView_FFTMin:
      return d.fftMin;
    case kDatasetView_FFTMax:
      return d.fftMax;
    case kDatasetView_Widget:
      return Registry::datasetWidgetsOptions().indexForValue(pm, d.widget);
    case kDatasetView_DisplayTickCount:
      return d.displayTickCount;
    case kDatasetView_DisplayFormat:
      return Registry::displayFormatsOptions().indexForValue(pm, d.displayFormat);
    case kDatasetView_DecimalPoints:
      return d.decimalPoints;
    case kDatasetView_WgtMin:
      return d.wgtMin;
    case kDatasetView_WgtMax:
      return d.wgtMax;
    case kDatasetView_LED:
      return d.led;
    case kDatasetView_LED_High:
      return d.ledHigh;
    default:
      return {};
  }
}

static void writeDatasetFlags(QJsonObject& obj, const Dataset& d)
{
  if (d.virtual_)
    obj.insert(Keys::Virtual, true);

  if (d.hideOnDashboard)
    obj.insert(Keys::HideOnDashboard, true);

  obj.insert(Keys::Graph, d.plt);
  obj.insert(Keys::Log, d.log);
  if (d.pltLogX)
    obj.insert(Keys::PltLogX, true);

  if (d.pltLogY)
    obj.insert(Keys::PltLogY, true);

  obj.insert(Keys::FFT, d.fft);
  if (d.waterfall)
    obj.insert(Keys::Waterfall, true);

  if (d.fftBallistics)
    obj.insert(Keys::FFTBallistics, true);

  if (d.fftLogX)
    obj.insert(Keys::FFTLogX, true);

  obj.insert(Keys::LED, d.led);
  if (d.overviewDisplay)
    obj.insert(Keys::Overview, true);

  if (!d.enabled)
    obj.insert(Keys::Disabled, true);
}

static void writeDatasetNumbers(QJsonObject& obj, const Dataset& d)
{
  obj.insert(Keys::Index, d.index);
  obj.insert(Keys::PltMin, qMin(d.pltMin, d.pltMax));
  obj.insert(Keys::PltMax, qMax(d.pltMin, d.pltMax));
  obj.insert(Keys::XAxis, d.xAxisId);
  if (d.fftBallistics)
    obj.insert(Keys::FFTBallisticsRelease, d.fftBallisticsRelease);

  if (d.waterfallYAxis != 0)
    obj.insert(Keys::WaterfallYAxis, d.waterfallYAxis);

  obj.insert(Keys::FFTSamples, d.fftSamples);
  obj.insert(Keys::FFTWindow, d.fftWindow);
  obj.insert(Keys::FFTSamplingRate, d.fftSamplingRate);
  obj.insert(Keys::FFTMin, qMin(d.fftMin, d.fftMax));
  obj.insert(Keys::FFTMax, qMax(d.fftMin, d.fftMax));
  if (d.displayTickCount > 0)
    obj.insert(Keys::DisplayTickCount, d.displayTickCount);

  if (d.decimalPoints >= 0)
    obj.insert(Keys::DecimalPoints, d.decimalPoints);

  obj.insert(Keys::WgtMin, qMin(d.wgtMin, d.wgtMax));
  obj.insert(Keys::WgtMax, qMax(d.wgtMin, d.wgtMax));
  obj.insert(Keys::LedHigh, d.ledHigh);
  if (!d.transformCode.isEmpty())
    obj.insert(Keys::TransformLanguage, d.transformLanguage);

  obj.insert(Keys::GroupId, d.groupId);
  obj.insert(Keys::DatasetId, d.datasetId);
  if (d.uniqueId >= 0)
    obj.insert(Keys::UniqueId, d.uniqueId);

  obj.insert(Keys::NumericValue, d.numericValue);
}

static void writeDatasetStrings(QJsonObject& obj, const Dataset& d)
{
  obj.insert(Keys::Title, d.title.simplified());
  obj.insert(Keys::Units, d.units.simplified());
  if (!d.alias.isEmpty())
    obj.insert(Keys::Alias, d.alias);

  if (!d.color.isEmpty())
    obj.insert(Keys::Color, d.color);

  obj.insert(Keys::Widget, d.widget.simplified());
  if (!d.displayFormat.isEmpty())
    obj.insert(Keys::DisplayFormat, d.displayFormat);

  if (!d.transformCode.isEmpty())
    obj.insert(Keys::TransformCode, d.transformCode);

  obj.insert(Keys::Value, d.value.simplified());
}

static void writeDatasetSubEntities(QJsonObject& obj, const Dataset& d)
{
  if (!d.alarmBands.empty()) {
    QJsonArray alarm_bands;
    for (const auto& entry : d.alarmBands)
      alarm_bands.append(serialize(entry));

    obj.insert(Keys::AlarmBands, alarm_bands);
  }

  if (!d.fftMarkers.empty()) {
    QJsonArray fft_markers;
    for (const auto& entry : d.fftMarkers)
      fft_markers.append(serialize(entry));

    obj.insert(Keys::FFTMarkers, fft_markers);
  }
}

static void readDatasetFlags(Dataset& d, const QJsonObject& obj)
{
  d.virtual_ = ss_jsr(obj, Keys::Virtual, false).toBool();
  d.hideOnDashboard = ss_jsr(obj, Keys::HideOnDashboard, false).toBool();
  d.plt = ss_jsr(obj, Keys::Graph, false).toBool();
  d.log = ss_jsr(obj, Keys::Log, false).toBool();
  d.pltLogX = ss_jsr(obj, Keys::PltLogX, false).toBool();
  d.pltLogY = ss_jsr(obj, Keys::PltLogY, false).toBool();
  d.fft = ss_jsr(obj, Keys::FFT, false).toBool();
  d.waterfall = ss_jsr(obj, Keys::Waterfall, false).toBool();
  d.fftBallistics = ss_jsr(obj, Keys::FFTBallistics, false).toBool();
  d.fftLogX = ss_jsr(obj, Keys::FFTLogX, false).toBool();
  d.led = ss_jsr(obj, Keys::LED, false).toBool();
  d.overviewDisplay = ss_jsr(obj, Keys::Overview, false).toBool();
  d.enabled = !ss_jsr(obj, Keys::Disabled, false).toBool();
}

static void readDatasetNumbers(Dataset& d, const QJsonObject& obj)
{
  d.index = ss_jsr(obj, Keys::Index, 0).toInt();
  d.pltMin = SerialStudio::toDouble(ss_jsr(obj, Keys::PltMin, 0));
  d.pltMax = SerialStudio::toDouble(ss_jsr(obj, Keys::PltMax, 0));
  d.xAxisId = ss_jsr(obj, Keys::XAxis, -2).toInt();
  d.fftBallisticsRelease = ss_jsr(obj, Keys::FFTBallisticsRelease, 300).toInt();
  d.waterfallYAxis = ss_jsr(obj, Keys::WaterfallYAxis, 0).toInt();
  d.fftSamples = ss_jsr(obj, Keys::FFTSamples, 256).toInt();
  d.fftWindow = ss_jsr(obj, Keys::FFTWindow, 5).toInt();
  d.fftSamplingRate = ss_jsr(obj, Keys::FFTSamplingRate, 100).toInt();
  d.fftMin = SerialStudio::toDouble(ss_jsr(obj, Keys::FFTMin, 0));
  d.fftMax = SerialStudio::toDouble(ss_jsr(obj, Keys::FFTMax, 0));
  d.displayTickCount = ss_jsr(obj, Keys::DisplayTickCount, 5).toInt();
  d.decimalPoints = ss_jsr(obj, Keys::DecimalPoints, -1).toInt();
  d.wgtMin = SerialStudio::toDouble(ss_jsr(obj, Keys::WgtMin, 0));
  d.wgtMax = SerialStudio::toDouble(ss_jsr(obj, Keys::WgtMax, 0));
  d.ledHigh = SerialStudio::toDouble(ss_jsr(obj, Keys::LedHigh, 80));
  d.transformLanguage = ss_jsr(obj, Keys::TransformLanguage, -1).toInt();
  d.uniqueId = ss_jsr(obj, Keys::UniqueId, -1).toInt();
  d.sourceId = ss_jsr(obj, Keys::DatasetSourceId, 0).toInt();
}

static void readDatasetStrings(Dataset& d, const QJsonObject& obj)
{
  d.title = ss_jsr(obj, Keys::Title, "").toString().simplified();
  d.units = ss_jsr(obj, Keys::Units, "").toString().simplified();
  d.alias = ss_jsr(obj, Keys::Alias, "").toString().simplified();
  d.color = ss_jsr(obj, Keys::Color, "").toString().simplified();
  d.widget = ss_jsr(obj, Keys::Widget, "").toString().simplified();
  d.displayFormat = ss_jsr(obj, Keys::DisplayFormat, "0d").toString();
  d.transformCode = ss_jsr(obj, Keys::TransformCode, "").toString();
  d.value = ss_jsr(obj, Keys::Value, "").toString().simplified();
}

static void finalizeDatasetRead(Dataset& d, const QJsonObject& obj)
{
  if (!PropertyHooks::isValidColor(d.color))
    d.color.clear();

  if (!d.value.isEmpty())
    d.numericValue = SerialStudio::toDouble(d.value, &d.isNumeric);

  if (!PropertyHooks::isValidFftWindow(d.fftWindow))
    d.fftWindow = 5;

  if (!obj.contains(Keys::PltMin) || !obj.contains(Keys::PltMax)) {
    d.pltMin = SerialStudio::toDouble(ss_jsr(obj, Keys::Min, 0));
    d.pltMax = SerialStudio::toDouble(ss_jsr(obj, Keys::Max, 0));
  }

  if (!obj.contains(Keys::FFTMin) || !obj.contains(Keys::FFTMax)) {
    d.fftMin = SerialStudio::toDouble(ss_jsr(obj, Keys::Min, 0));
    d.fftMax = SerialStudio::toDouble(ss_jsr(obj, Keys::Max, 0));
  }

  if (!obj.contains(Keys::WgtMin) || !obj.contains(Keys::WgtMax)) {
    d.wgtMin = SerialStudio::toDouble(ss_jsr(obj, Keys::Min, 0));
    d.wgtMax = SerialStudio::toDouble(ss_jsr(obj, Keys::Max, 0));
  }

  readDatasetAlarmBands(d, obj);
  readDatasetFrequencyMarkers(d, obj);
  normalizeDatasetRanges(d);
}

QJsonObject DataModel::serialize(const Dataset& d)
{
  QJsonObject obj;
  writeDatasetFlags(obj, d);
  writeDatasetNumbers(obj, d);
  writeDatasetStrings(obj, d);
  writeDatasetSubEntities(obj, d);
  return obj;
}

bool DataModel::read(Dataset& d, const QJsonObject& obj)
{
  if (obj.isEmpty())
    return false;

  readDatasetFlags(d, obj);
  readDatasetNumbers(d, obj);
  readDatasetStrings(d, obj);
  finalizeDatasetRead(d, obj);
  return true;
}

QJsonObject DataModel::ProtoImporter::projectFromProtoFile(const QString& path)
{
  static constexpr qsizetype kMaxProtoBytes = 10 * 1024 * 1024;

  QFile file(path);
  if (!file.open(QIODevice::ReadOnly | QIODevice::Text) || file.size() > kMaxProtoBytes)
    return QJsonObject();

  QTextStream stream(&file);
  const QString src = stream.readAll();
  file.close();

  QString package;
  QVector<ProtoMessage> messages;
  ParseError err{0, QString()};
  Parser parser(src, package, messages);
  if (!parser.parseFile(err) || messages.isEmpty())
    return QJsonObject();

  m_messages      = messages;
  m_protoFilePath = path;
  return projectFromMessages();
}

void DataModel::ProjectEditor::onDatasetItemChanged(QStandardItem* item)
{
  if (!item)
    return;

  const auto idInt = static_cast<DatasetItem>(item->data(ParameterType).toInt());
  const auto value = item->data(EditableValue);
  const int formId = static_cast<int>(idInt);
  if (!datasetFormEditAccepted(formId, value))
    return;

  const auto hint =
    Registry::applyDatasetFormEdit(formId, value, m_selectedDataset, m_projectModelRef);
  if (idInt == kDatasetView_Virtual)
    syncDatasetTreeVirtualFlag(m_selectedDataset);

  const bool rebuildNow   = !m_batchApplying && hint == PropertyHooks::RebuildHint::Sync;
  const bool rebuildLater = !m_batchApplying && hint == PropertyHooks::RebuildHint::Deferred;
  if (rebuildNow)
    buildDatasetModel(m_selectedDataset);

  if (rebuildLater) {
    const int uid = m_selectedDataset.uniqueId;
    QTimer::singleShot(0, this, [this, uid] {
      if (m_selectedDataset.uniqueId == uid)
        buildDatasetModel(m_selectedDataset);
    });
  }

  commitDatasetFormEdit(formId);
}

static bool multiSelectionEditKeepsModel(QStandardItem* item,
                                         DataModel::PropertyHooks::RebuildHint hint)
{
  using Editor = DataModel::ProjectEditor;
  if (hint != DataModel::PropertyHooks::RebuildHint::None)
    return false;

  const int wt     = item->data(Editor::WidgetType).toInt();
  const bool typed = wt == Editor::TextField || wt == Editor::IntField || wt == Editor::FloatField
                  || wt == Editor::HexTextField || wt == Editor::PasswordField;
  if (!typed)
    return false;

  if (item->data(Editor::PlaceholderValue).toString() == Editor::tr("Mixed"))
    item->setData(QString(), Editor::PlaceholderValue);

  return true;
}

void DataModel::ProjectHistory::setApplying(const bool applying)
{
  SS_ASSERT_LOG(m_applying != applying);
  m_applying = applying;
}

QString DataModel::ProjectHistory::undoText() const
{
  if (!canUndo())
    return QString();

  return m_steps[m_position - 1].label;
}

QString DataModel::ProjectHistory::redoText() const
{
  if (!canRedo())
    return QString();

  return m_steps[m_position].label;
}

void DataModel::ProjectHistory::setNextHint(const QString& label, const QString& coalesceKey)
{
  m_hintLabel = label;
  m_hintKey   = coalesceKey;
}

void DataModel::ProjectHistory::pushFrame(const QString& label)
{
  if (m_depth == 0)
    m_rootLabel = label;

  ++m_depth;
}

DataModel::ProjectHistory::ScopeAction DataModel::ProjectHistory::enterScope(
  const QString& slotLabel, const QString& slotKey)
{
  ++m_depth;

  const QString hintLabel = m_hintLabel;
  const QString hintKey   = m_hintKey.isEmpty() ? slotKey : m_hintKey;
  m_hintLabel.clear();
  m_hintKey.clear();

  if (!m_enabled || m_applying || m_stackCaptured || m_pendingStaged)
    return ScopeAction::None;

  const bool noRedoTail = m_position == m_steps.size();
  if (!hintKey.isEmpty() && noRedoTail && !m_steps.empty()) {
    const auto& top = m_steps.back();
    if (top.coalesceKey == hintKey && m_clock.elapsed() - top.timestampMs <= kCoalesceWindowMs) {
      m_pendingStaged   = true;
      m_pendingCoalesce = true;
      return ScopeAction::Coalesce;
    }
  }

  if (!m_rootLabel.isEmpty())
    m_pendingLabel = m_rootLabel;
  else if (!hintLabel.isEmpty())
    m_pendingLabel = hintLabel;
  else
    m_pendingLabel = slotLabel;

  m_pendingKey = hintKey;
  return ScopeAction::Capture;
}

void DataModel::ProjectHistory::stageCapture(QByteArray preState)
{
  SS_ASSERT(m_depth > 0, return);
  SS_ASSERT(!m_stackCaptured, return);
  SS_ASSERT(!m_pendingStaged, return);

  m_pendingStaged   = true;
  m_pendingCoalesce = false;
  m_pendingState    = std::move(preState);
}

void DataModel::ProjectHistory::commitPending()
{
  if (!m_pendingStaged)
    return;

  m_pendingStaged = false;
  m_stackCaptured = true;

  if (m_pendingCoalesce) {
    m_pendingCoalesce = false;
    SS_ASSERT(!m_steps.empty(), return);
    auto& top = m_steps.back();
    if (!top.postState.isEmpty()) {
      m_totalBytes  -= top.postState.size();
      top.postState  = QByteArray();
    }

    top.timestampMs = m_clock.elapsed();
    return;
  }

  if (m_savePosition > static_cast<qint64>(m_position))
    m_savePosition = kSaveUnreachable;

  while (m_steps.size() > m_position) {
    m_totalBytes -= m_steps.back().preState.size() + m_steps.back().postState.size();
    m_steps.pop_back();
  }

  Step step;
  step.label        = m_pendingLabel;
  step.coalesceKey  = m_pendingKey;
  step.preState     = std::move(m_pendingState);
  step.timestampMs  = m_clock.elapsed();
  m_totalBytes     += step.preState.size();
  m_steps.push_back(std::move(step));
  m_position = m_steps.size();

  m_pendingState = QByteArray();
  dropOverflow();
}

bool DataModel::ProjectHistory::leave()
{
  SS_ASSERT(m_depth > 0, return false);
  --m_depth;
  if (m_depth > 0)
    return false;

  const bool changed = m_stackCaptured;
  m_stackCaptured    = false;
  m_pendingStaged    = false;
  m_pendingCoalesce  = false;
  m_pendingState     = QByteArray();
  m_rootLabel.clear();
  return changed;
}

QByteArray DataModel::ProjectHistory::peekUndoState() const
{
  SS_ASSERT_LOG(canUndo());
  if (m_position == 0)
    return QByteArray();

  return m_steps[m_position - 1].preState;
}

QByteArray DataModel::ProjectHistory::peekRedoState() const
{
  SS_ASSERT(canRedo(), return QByteArray());
  return m_steps[m_position].postState;
}

void DataModel::ProjectHistory::confirmUndo(const QByteArray& currentState)
{
  SS_ASSERT_LOG(canUndo());
  if (m_position == 0)
    return;

  auto& step = m_steps[m_position - 1];
  if (step.postState.isEmpty()) {
    step.postState  = currentState;
    m_totalBytes   += step.postState.size();
  }

  --m_position;
  dropOverflow();
}

void DataModel::ProjectHistory::confirmRedo()
{
  SS_ASSERT(canRedo(), return);
  ++m_position;
}

void DataModel::ProjectHistory::markSaved()
{
  m_savePosition = static_cast<qint64>(m_position);
  if (!m_steps.empty() && m_position == m_steps.size())
    m_steps.back().coalesceKey.clear();
}

void DataModel::ProjectHistory::clear()
{
  m_steps.clear();
  m_position      = 0;
  m_savePosition  = 0;
  m_totalBytes    = 0;
  m_stackCaptured = false;
}

void DataModel::ProjectHistory::dropOverflow()
{
  while ((m_steps.size() > static_cast<size_t>(kMaxUndoSteps) || m_totalBytes > kMaxUndoBytes)
         && m_position > 0 && m_steps.size() > 1)
    dropFront();
}

void DataModel::ProjectHistory::dropFront()
{
  SS_ASSERT(!m_steps.empty(), return);
  SS_ASSERT(m_position > 0, return);

  m_totalBytes -= m_steps.front().preState.size() + m_steps.front().postState.size();
  m_steps.pop_front();
  --m_position;

  if (m_savePosition == 0)
    m_savePosition = kSaveUnreachable;
  else if (m_savePosition > 0)
    --m_savePosition;
}

DataModel::ProjectUndoFrame::ProjectUndoFrame(ProjectModel& model, const QString& label)
  : m_model(model)
{
  m_model.history().pushFrame(label);
}

DataModel::ProjectUndoFrame::~ProjectUndoFrame()
{
  if (m_model.history().leave())
    Q_EMIT m_model.projectHistoryChanged();
}

DataModel::ProjectUndoScope::ProjectUndoScope(ProjectModel& model,
                                              const QString& label,
                                              const QString& coalesceKey)
  : m_model(model)
{
  auto& history     = m_model.history();
  const auto action = history.enterScope(label, coalesceKey);
  if (action == ProjectHistory::ScopeAction::Capture) {
    const auto json = QJsonDocument(m_model.serializeToJson()).toJson(QJsonDocument::Compact);
    history.stageCapture(json);
  }
}

DataModel::ProjectUndoScope::~ProjectUndoScope()
{
  if (m_model.history().leave())
    Q_EMIT m_model.projectHistoryChanged();
}

static void resolveAllWorkspaceRefs(std::vector<DataModel::Workspace>& workspaces,
                                    const QHash<int, std::vector<detail::RefAnchor>>& anchors,
                                    const std::vector<DataModel::Group>& groups)
{
  for (auto& ws : workspaces) {
    const auto it = anchors.constFind(ws.workspaceId);
    if (it == anchors.constEnd())
      continue;

    resolveOneWorkspaceRefs(ws, it.value(), groups);
  }
}

DataModel::PropertyHooks::StaticMapOptions::StaticMapOptions(const StaticOptionEntry* entries,
                                                             int count,
                                                             const char* context)
  : m_entries(entries), m_context(context), m_count(count)
{
  SS_ASSERT_LOG(entries != nullptr);
  SS_ASSERT_LOG(count > 0);
}

QStringList DataModel::PropertyHooks::StaticMapOptions::labels(const ProjectModel& pm) const
{
  Q_UNUSED(pm);
  SS_ASSERT_LOG(m_entries != nullptr);

  QStringList out;
  out.reserve(m_count);
  for (int i = 0; i < m_count; ++i)
    out.append(QCoreApplication::translate(m_context, m_entries[i].label));

  return out;
}

int DataModel::PropertyHooks::StaticMapOptions::indexForValue(const ProjectModel& pm,
                                                              const QVariant& val) const
{
  Q_UNUSED(pm);
  SS_ASSERT_LOG(m_entries != nullptr);

  const auto key = val.toString();
  for (int i = 0; i < m_count; ++i)
    if (key == QLatin1StringView(m_entries[i].value))
      return i;

  return 0;
}

QVariant DataModel::PropertyHooks::StaticMapOptions::valueForIndex(const ProjectModel& pm,
                                                                   int index) const
{
  Q_UNUSED(pm);
  SS_ASSERT_LOG(m_entries != nullptr);

  if (index < 0 || index >= m_count)
    return QString();

  return QString::fromLatin1(m_entries[index].value);
}

DataModel::PropertyHooks::ExtensibleMapOptions::ExtensibleMapOptions(
  const StaticOptionEntry* entries, int count, const char* context, EntryProvider provider)
  : m_entries(entries), m_context(context), m_count(count), m_provider(provider)
{
  SS_ASSERT_LOG(entries != nullptr);
  SS_ASSERT_LOG(provider != nullptr);
  SS_ASSERT_LOG(count > 0);
}

QStringList DataModel::PropertyHooks::ExtensibleMapOptions::labels(const ProjectModel& pm) const
{
  Q_UNUSED(pm);
  SS_ASSERT_LOG(m_entries != nullptr);
  SS_ASSERT_LOG(m_provider != nullptr);

  QStringList out;
  out.reserve(m_count);
  for (int i = 0; i < m_count; ++i)
    out.append(QCoreApplication::translate(m_context, m_entries[i].label));

  const auto appended = m_provider();
  for (const auto& entry : appended)
    out.append(entry.second);

  return out;
}

int DataModel::PropertyHooks::ExtensibleMapOptions::indexForValue(const ProjectModel& pm,
                                                                  const QVariant& val) const
{
  Q_UNUSED(pm);
  SS_ASSERT_LOG(m_entries != nullptr);
  SS_ASSERT_LOG(m_provider != nullptr);

  const auto key = val.toString();
  for (int i = 0; i < m_count; ++i)
    if (key == QLatin1StringView(m_entries[i].value))
      return i;

  const auto appended = m_provider();
  for (int i = 0; i < appended.size(); ++i)
    if (key == appended.at(i).first)
      return m_count + i;

  return 0;
}

QVariant DataModel::PropertyHooks::ExtensibleMapOptions::valueForIndex(const ProjectModel& pm,
                                                                       int index) const
{
  Q_UNUSED(pm);
  SS_ASSERT_LOG(m_entries != nullptr);
  SS_ASSERT_LOG(m_provider != nullptr);

  if (index >= 0 && index < m_count)
    return QString::fromLatin1(m_entries[index].value);

  const auto appended = m_provider();
  const int offset    = index - m_count;
  if (offset < 0 || offset >= appended.size())
    return QString();

  return appended.at(offset).first;
}

DataModel::PropertyHooks::ParallelValueOptions::ParallelValueOptions(const IntOptionEntry* entries,
                                                                     int count,
                                                                     const char* context,
                                                                     int notFoundIndex)
  : m_entries(entries), m_context(context), m_count(count), m_notFound(notFoundIndex)
{
  SS_ASSERT_LOG(entries != nullptr);
  SS_ASSERT_LOG(count > 0);
}

QStringList DataModel::PropertyHooks::ParallelValueOptions::labels(const ProjectModel& pm) const
{
  Q_UNUSED(pm);
  SS_ASSERT_LOG(m_entries != nullptr);

  QStringList out;
  out.reserve(m_count);
  for (int i = 0; i < m_count; ++i)
    if (m_context)
      out.append(QCoreApplication::translate(m_context, m_entries[i].label));
    else
      out.append(QString::fromLatin1(m_entries[i].label));

  return out;
}

int DataModel::PropertyHooks::ParallelValueOptions::indexForValue(const ProjectModel& pm,
                                                                  const QVariant& val) const
{
  Q_UNUSED(pm);
  SS_ASSERT_LOG(m_entries != nullptr);

  const int wanted = val.toInt();
  for (int i = 0; i < m_count; ++i)
    if (m_entries[i].value == wanted)
      return i;

  return m_notFound;
}

QVariant DataModel::PropertyHooks::ParallelValueOptions::valueForIndex(const ProjectModel& pm,
                                                                       int index) const
{
  Q_UNUSED(pm);
  SS_ASSERT_LOG(m_entries != nullptr);

  if (index < 0 || index >= m_count)
    return m_entries[m_notFound].value;

  return m_entries[index].value;
}

DataModel::PropertyHooks::LiveProviderOptions::LiveProviderOptions(LabelProvider labelProvider,
                                                                   ValueProvider valueProvider,
                                                                   int notFoundValue)
  : m_labels(labelProvider), m_values(valueProvider), m_notFoundValue(notFoundValue)
{
  SS_ASSERT_LOG(labelProvider != nullptr);
  SS_ASSERT_LOG(valueProvider != nullptr);
}

QStringList DataModel::PropertyHooks::LiveProviderOptions::labels(const ProjectModel& pm) const
{
  SS_ASSERT_LOG(m_labels != nullptr);
  return (pm.*m_labels)();
}

int DataModel::PropertyHooks::LiveProviderOptions::indexForValue(const ProjectModel& pm,
                                                                 const QVariant& val) const
{
  SS_ASSERT_LOG(m_values != nullptr);

  const auto ids   = (pm.*m_values)();
  const int wanted = val.toInt();
  for (int i = 0; i < ids.size(); ++i)
    if (ids.at(i) == wanted)
      return i;

  return 0;
}

QVariant DataModel::PropertyHooks::LiveProviderOptions::valueForIndex(const ProjectModel& pm,
                                                                      int index) const
{
  SS_ASSERT_LOG(m_values != nullptr);

  const auto ids = (pm.*m_values)();
  if (index < 0 || index >= ids.size())
    return m_notFoundValue;

  return ids.at(index);
}

DataModel::PropertyHooks::TupleOptions::TupleOptions(const TupleOptionEntry* entries,
                                                     int count,
                                                     const char* context)
  : m_entries(entries), m_context(context), m_count(count)
{
  SS_ASSERT_LOG(entries != nullptr);
  SS_ASSERT_LOG(count > 0);
}

QStringList DataModel::PropertyHooks::TupleOptions::labels(const ProjectModel& pm) const
{
  Q_UNUSED(pm);
  SS_ASSERT_LOG(m_entries != nullptr);

  QStringList out;
  out.reserve(m_count);
  for (int i = 0; i < m_count; ++i)
    out.append(QCoreApplication::translate(m_context, m_entries[i].label));

  return out;
}

int DataModel::PropertyHooks::TupleOptions::indexForValue(const ProjectModel& pm,
                                                          const QVariant& val) const
{
  Q_UNUSED(pm);
  SS_ASSERT_LOG(m_entries != nullptr);

  const auto pair = val.toList();
  if (pair.size() != 2)
    return 0;

  return indexForPair(pair.at(0).toBool(), pair.at(1).toBool());
}

QVariant DataModel::PropertyHooks::TupleOptions::valueForIndex(const ProjectModel& pm,
                                                               int index) const
{
  Q_UNUSED(pm);
  SS_ASSERT_LOG(m_entries != nullptr);

  QVariantList out;
  out.append(firstForIndex(index));
  out.append(secondForIndex(index));
  return out;
}

int DataModel::PropertyHooks::TupleOptions::indexForPair(bool first, bool second) const
{
  SS_ASSERT_LOG(m_entries != nullptr);
  SS_ASSERT_LOG(m_count > 0);

  for (int i = 0; i < m_count; ++i)
    if (m_entries[i].first == first && m_entries[i].second == second)
      return i;

  return 0;
}

bool DataModel::PropertyHooks::TupleOptions::firstForIndex(int index) const
{
  SS_ASSERT_LOG(m_entries != nullptr);

  if (index < 0 || index >= m_count)
    return false;

  return m_entries[index].first;
}

bool DataModel::PropertyHooks::TupleOptions::secondForIndex(int index) const
{
  SS_ASSERT_LOG(m_entries != nullptr);

  if (index < 0 || index >= m_count)
    return false;

  return m_entries[index].second;
}

QList<QPair<QString, QString>> DataModel::PropertyHooks::widgetExtensionOptions()
{
  static auto& catalog = UI::WidgetExtensions::instance();

  QList<QPair<QString, QString>> out;
  const auto packages = catalog.idsForScope(UI::WidgetExtensions::DatasetScope);
  for (const auto& id : packages) {
    const auto& package = catalog.descriptor(id);
    if (package.replaces.isEmpty() && !package.title.isEmpty())
      out.append({id, package.title});
  }

  return out;
}

bool DataModel::PropertyHooks::aliasInUseByOtherDataset(const ProjectModel& pm,
                                                        const QString& alias,
                                                        int selfUniqueId)
{
  SS_ASSERT_LOG(!alias.isEmpty());

  for (const auto& group : pm.groups()) {
    for (const auto& other : group.datasets)
      if (other.uniqueId != selfUniqueId && other.alias == alias)
        return true;
  }

  return false;
}

bool DataModel::PropertyHooks::insidePainterGroup(const Dataset& d, const ProjectModel& pm)
{
  const auto& groups = pm.groups();
  if (d.groupId < 0 || static_cast<size_t>(d.groupId) >= groups.size())
    return false;

  return groups[d.groupId].widget == QLatin1String("painter");
}

bool DataModel::PropertyHooks::notVirtual(const Dataset& d, const ProjectModel& pm)
{
  Q_UNUSED(pm);
  return !d.virtual_;
}

bool DataModel::PropertyHooks::plotEnabled(const Dataset& d, const ProjectModel& pm)
{
  Q_UNUSED(pm);
  return d.plt;
}

bool DataModel::PropertyHooks::plotEnabledNonTimeX(const Dataset& d, const ProjectModel& pm)
{
  Q_UNUSED(pm);
  return d.plt && d.xAxisId != kXAxisTime;
}

bool DataModel::PropertyHooks::fftEnabled(const Dataset& d, const ProjectModel& pm)
{
  Q_UNUSED(pm);
  return d.fft;
}

bool DataModel::PropertyHooks::fftOrWaterfallEnabled(const Dataset& d, const ProjectModel& pm)
{
  Q_UNUSED(pm);
  return d.fft || d.waterfall;
}

bool DataModel::PropertyHooks::waterfallEnabled(const Dataset& d, const ProjectModel& pm)
{
  Q_UNUSED(pm);
  return d.waterfall;
}

bool DataModel::PropertyHooks::widgetSelectable(const Dataset& d, const ProjectModel& pm)
{
  const auto& groups = pm.groups();
  if (d.groupId >= 0 && static_cast<size_t>(d.groupId) < groups.size()) {
    const auto& widget = groups[d.groupId].widget;
    if (widget != "" && widget != "multiplot" && widget != "datagrid" && widget != "painter")
      return false;
  }

  return true;
}

bool DataModel::PropertyHooks::widgetRangeApplicable(const Dataset& d, const ProjectModel& pm)
{
  if (!widgetSelectable(d, pm))
    return false;

  return d.widget == "bar" || d.widget == "gauge" || d.widget == "meter";
}

bool DataModel::PropertyHooks::ledEnabled(const Dataset& d, const ProjectModel& pm)
{
  Q_UNUSED(pm);
