void DataModel::ProjectEditor::appendExtensionWidgets()
{
  static auto& catalog = UI::WidgetExtensions::instance();

  const auto packages = catalog.ids();
  for (const auto& id : packages) {
    const auto& package = catalog.descriptor(id);
    if (!package.replaces.isEmpty() || package.title.isEmpty())
      continue;

    if (package.scope == UI::WidgetExtensions::GroupScope)
      m_groupWidgets.insert(id, package.title);

    else
      m_datasetWidgets.insert(id, package.title);
  }
}

bool DataModel::ProjectModel::undo()
{
  if (!m_history.canUndo() || m_history.applying())
    return false;

  const auto current = QJsonDocument(serializeToJson()).toJson(QJsonDocument::Compact);
  const auto state   = m_history.peekUndoState();
  if (!applyHistorySnapshot(state)) {
    qWarning() << "[ProjectModel] Undo failed to apply the stored snapshot";
    return false;
  }

  m_history.confirmUndo(current);
  setModified(!m_history.isAtSavePoint());
  Q_EMIT projectHistoryChanged();
  return true;
}

bool DataModel::ProjectModel::redo()
{
  if (!m_history.canRedo() || m_history.applying())
    return false;

  const auto state = m_history.peekRedoState();
  if (!applyHistorySnapshot(state)) {
    qWarning() << "[ProjectModel] Redo failed to apply the stored snapshot";
    return false;
  }

  m_history.confirmRedo();
  setModified(!m_history.isAtSavePoint());
  Q_EMIT projectHistoryChanged();
  return true;
}

static QString extension_scope_key(int widgetType,
                                   int uniqueId,
                                   const std::vector<DataModel::Group>& groups)
{
  if (widgetType != static_cast<int>(SerialStudio::DashboardExtension))
    return widget_scope_key(widgetType, uniqueId);

  QString package;
  for (const auto& group : groups) {
    if (group.uniqueId == uniqueId)
      package = group.widget;

    for (const auto& dataset : group.datasets)
      if (dataset.uniqueId == uniqueId)
        package = dataset.widget;
  }

  if (package.isEmpty())
    return widget_scope_key(widgetType, uniqueId);

  return UI::WidgetExtensions::persistedTypeToken(package) + QLatin1Char(':')
       + QString::number(uniqueId);
}

void DataModel::RowFilterProxy::setSourceModel(QAbstractItemModel* model)
{
  rebuildRoleCache(model);
  QSortFilterProxyModel::setSourceModel(model);
}

void DataModel::RowFilterProxy::setQuery(const QString& query)
{
  if (m_query == query)
    return;

  beginFilterChange();
  m_query = query;
  endFilterChange(Direction::Rows);
  Q_EMIT queryChanged();
}

void DataModel::RowFilterProxy::setFilterRoles(const QStringList& roles)
{
  if (m_filterRoles == roles)
    return;

  beginFilterChange();
  m_filterRoles = roles;
  rebuildRoleCache(sourceModel());
  endFilterChange(Direction::Rows);
  Q_EMIT filterRolesChanged();
}

bool DataModel::RowFilterProxy::rowMatches(const QAbstractItemModel* model,
                                           int row,
                                           const QModelIndex& parent,
                                           const QString& needle) const
{
  const QModelIndex index = model->index(row, 0, parent);
  SS_ASSERT(index.isValid(), return true);

  for (const int role : m_roleIds)
    if (SerialStudio::searchMatches(needle, model->data(index, role).toString()))
      return true;

  return false;
}

bool DataModel::RowFilterProxy::rowIsSectionHeader(const QAbstractItemModel* model,
                                                   int row,
                                                   const QModelIndex& parent) const
{
  if (m_widgetTypeRole < 0)
    return false;

  const QModelIndex index = model->index(row, 0, parent);
  return model->data(index, m_widgetTypeRole).toInt() == ProjectEditor::SectionHeader;
}

bool DataModel::RowFilterProxy::filterAcceptsRow(int row, const QModelIndex& parent) const
{
  const QString needle = m_query.trimmed();
  if (needle.isEmpty())
    return true;

  const auto* model = sourceModel();
  if (!model)
    return true;

  SS_ASSERT(!m_roleIds.isEmpty(), return true);
  if (!rowIsSectionHeader(model, row, parent))
    return rowMatches(model, row, parent, needle);

  const int count = model->rowCount(parent);
  for (int r = row + 1; r < count; ++r) {
    if (rowIsSectionHeader(model, r, parent))
      return false;

    if (rowMatches(model, r, parent, needle))
      return true;
  }

  return false;
}

void DataModel::RowFilterProxy::rebuildRoleCache(const QAbstractItemModel* model)
{
  m_roleIds.clear();
  m_widgetTypeRole = -1;
  if (!model)
    return;

  const auto roles = model->roleNames();
  for (auto it = roles.constBegin(); it != roles.constEnd(); ++it) {
    if (m_filterRoles.contains(QString::fromUtf8(it.value())))
      m_roleIds.append(it.key());

    if (it.value() == QByteArrayLiteral("widgetType"))
      m_widgetTypeRole = it.key();
  }
}

QList<DataModel::ScriptStat> DataModel::FrameParser::scriptStats() const
{
  QList<ScriptStat> stats;
  stats.reserve(static_cast<qsizetype>(m_engines.size()));

  for (const auto& [sourceId, engine] : m_engines) {
    if (!engine)
      continue;

    ScriptStat stat{};
    stat.sourceId            = sourceId;
    stat.language            = engine->language();
    stat.disabled            = engine->disabled();
    stat.consecutiveTimeouts = engine->consecutiveTimeouts();
    stat.errorCount          = engine->errorCount();
    stat.lastError           = engine->lastError();
    stats.append(stat);
  }

  return stats;
}

void DataModel::JsScriptEngine::noteError(const QString& message)
{
