  m_consecutiveTimeouts = 0;
}

static Async::Task* failedStep(const QString& name, const QString& reason)
{
  return Async::invoke(name, [reason](QString& out) {
    out = reason;
    return false;
  });
}

IO::DriverOpenTask::DriverOpenTask(HAL_Driver* driver, QIODevice::OpenMode mode, QObject* parent)
  : Async::Task(QStringLiteral("driver-open"), parent), m_mode(mode), m_driver(driver)
{
  SS_ASSERT_LOG(driver != nullptr);
  SS_ASSERT_LOG(mode != QIODevice::NotOpen);
}

void IO::DriverOpenTask::doStart()
{
  SS_ASSERT(isRunning(), return);
  SS_ASSERT(m_mode != QIODevice::NotOpen, {
    reportFinished(Async::Outcome::Failure, errorHere(QStringLiteral("invalid open mode")));
    return;
  });

  if (m_driver.isNull()) {
    reportFinished(Async::Outcome::Failure, errorHere(QStringLiteral("driver is gone")));
    return;
  }

  m_connection =
    connect(m_driver.data(), &HAL_Driver::openFinished, this, &IO::DriverOpenTask::onOpenFinished);

  m_driver->beginOpen(m_mode);
}

void IO::DriverOpenTask::doCancel()
{
  SS_ASSERT_LOG(isRunning());

  releaseConnection();
  if (!m_driver.isNull())
    m_driver->abortOpen();
}

void IO::DriverOpenTask::releaseConnection()
{
  QObject::disconnect(m_connection);
  m_connection = QMetaObject::Connection();
}

void IO::DriverOpenTask::onOpenFinished(bool ok, const QString& reason)
{
  SS_ASSERT_LOG(!m_driver.isNull());

  if (!isRunning())
    return;

  releaseConnection();
  if (ok) {
    reportFinished(Async::Outcome::Success, Async::StepError());
    return;
  }

  const QString why = reason.isEmpty() ? QStringLiteral("open failed") : reason;
  reportFinished(Async::Outcome::Failure, errorHere(why));
}

IO::SocketConnectTask::SocketConnectTask(QAbstractSocket* socket,
                                         QString host,
                                         quint16 port,
                                         QObject* parent)
  : Async::Task(QStringLiteral("socket-connect"), parent)
  , m_port(port)
  , m_generation(0)
  , m_host(std::move(host))
  , m_socket(socket)
{
  SS_ASSERT_LOG(port > 0);
  SS_ASSERT_LOG(socket != nullptr);
}

void IO::SocketConnectTask::doStart()
{
  SS_ASSERT(isRunning(), return);
  SS_ASSERT(!m_host.isEmpty(), {
    reportFinished(Async::Outcome::Failure, errorHere(QStringLiteral("no host to connect to")));
    return;
  });

  if (m_socket.isNull()) {
    reportFinished(Async::Outcome::Failure, errorHere(QStringLiteral("socket is gone")));
    return;
  }

  m_socket->abort();

  const int generation = ++m_generation;
  QMetaObject::invokeMethod(
    this, [this, generation] { beginDial(generation); }, Qt::QueuedConnection);
}

void IO::SocketConnectTask::beginDial(int generation)
{
  if (!isRunning() || generation != m_generation)
    return;

  if (m_socket.isNull()) {
    reportFinished(Async::Outcome::Failure, errorHere(QStringLiteral("socket is gone")));
    return;
  }

  m_okConnection = connect(
    m_socket.data(), &QAbstractSocket::connected, this, &IO::SocketConnectTask::onConnected);
  m_errorConnection = connect(
    m_socket.data(), &QAbstractSocket::errorOccurred, this, &IO::SocketConnectTask::onSocketError);

  m_socket->connectToHost(m_host, m_port);

  if (isRunning() && !m_socket.isNull() && hasLiveConnection())
    onConnected();
}

bool IO::SocketConnectTask::hasLiveConnection() const
{
  return !m_socket.isNull() && m_socket->state() == QAbstractSocket::ConnectedState
      && m_socket->peerPort() != 0;
}

void IO::SocketConnectTask::doCancel()
{
  SS_ASSERT_LOG(isRunning());

  ++m_generation;
  releaseConnections();
  if (!m_socket.isNull())
    m_socket->abort();
}

void IO::SocketConnectTask::onConnected()
{
  if (!isRunning())
    return;

  if (!hasLiveConnection())
    return;

  releaseConnections();
  reportFinished(Async::Outcome::Success, Async::StepError());
}

void IO::SocketConnectTask::onSocketError()
{
  if (!isRunning())
    return;

  QString why = m_socket.isNull() ? QString() : m_socket->errorString();
  if (why.isEmpty())
    why = QStringLiteral("socket connect failed");

  releaseConnections();
  reportFinished(Async::Outcome::Failure, errorHere(why));
}

void IO::SocketConnectTask::releaseConnections()
{
  QObject::disconnect(m_okConnection);
  QObject::disconnect(m_errorConnection);
  m_okConnection    = QMetaObject::Connection();
  m_errorConnection = QMetaObject::Connection();
}

IO::SupervisorTask::SupervisorTask(HAL_Driver* driver,
                                   Async::Task* child,
                                   const Async::RetryPolicy& recovery,
                                   QObject* parent)
  : Async::Task(QStringLiteral("link-supervisor"), parent)
  , m_child(child)
  , m_driver(driver)
  , m_recovery(recovery)
{
  SS_ASSERT_LOG(driver != nullptr);
  SS_ASSERT(child != nullptr, return);

  m_child->setParent(this);
  connect(m_child, &Async::Task::finished, this, &IO::SupervisorTask::onChildFinished);
}

int IO::SupervisorTask::attempt() const
{
  if (!isRunning())
    return 0;

  const auto* retry = qobject_cast<const Async::RetryTask*>(m_child);
  return retry ? retry->attempt() : 0;
}

void IO::SupervisorTask::doStart()
{
  SS_ASSERT(isRunning(), return);
  SS_ASSERT(m_child != nullptr, {
    reportFinished(Async::Outcome::Failure, errorHere(QStringLiteral("no flow to supervise")));
    return;
  });

  if (m_driver.isNull()) {
    reportFinished(Async::Outcome::Failure, errorHere(QStringLiteral("driver is gone")));
    return;
  }

  releaseConnection();
  m_connection =
    connect(m_driver.data(), &HAL_Driver::linkDropped, this, &IO::SupervisorTask::onLinkDropped);

  m_child->start();
}

void IO::SupervisorTask::doCancel()
{
  SS_ASSERT_LOG(isRunning());

  releaseConnection();
  SS_ASSERT(m_child != nullptr, return);

  if (m_child->isRunning())
    m_child->cancel();
}

void IO::SupervisorTask::onLinkDropped()
{
  SS_ASSERT(m_child != nullptr, return);

  if (!isRunning() || m_child->isRunning())
    return;

  if (!m_driver.isNull() && m_driver->isOpen())
    return;

  auto* retry = qobject_cast<Async::RetryTask*>(m_child);
  if (retry)
    retry->setPolicy(m_recovery);

  m_child->start();
}

void IO::SupervisorTask::releaseConnection()
{
  QObject::disconnect(m_connection);
  m_connection = QMetaObject::Connection();
}

void IO::SupervisorTask::onChildFinished(Async::Outcome outcome, const Async::StepError& error)
{
  SS_ASSERT_LOG(m_child != nullptr);

  if (!isRunning())
    return;

  if (outcome != Async::Outcome::Success) {
    releaseConnection();
    reportFinished(outcome, error);
    return;
  }

  if (m_driver.isNull()) {
    releaseConnection();
    reportFinished(Async::Outcome::Failure, errorHere(QStringLiteral("driver is gone")));
    return;
  }
}

Async::Task* IO::Flows::makeOpenFlow(HAL_Driver* driver,
                                     QIODevice::OpenMode mode,
                                     Async::AsyncClock& clock)
{
  SS_ASSERT_LOG(driver != nullptr);
  SS_ASSERT_LOG(mode != QIODevice::NotOpen);

  const int declared = driver->openTimeoutMsec();
  const int msec     = declared > 0 ? declared : kOpenTimeoutMsec;
  return Async::timeout(new DriverOpenTask(driver, mode), msec, clock);
}

Async::Task* IO::Flows::makeSupervised(HAL_Driver* driver,
                                       Async::Task* flow,
                                       const Async::RetryPolicy& policy,
                                       const Async::RetryPolicy& recovery,
                                       Async::AsyncClock& clock)
{
  SS_ASSERT_LOG(driver != nullptr);
  SS_ASSERT(
    flow != nullptr,
    return failedStep(QStringLiteral("link-supervisor"), QStringLiteral("no flow to supervise")));

  return new SupervisorTask(driver, Async::retry(flow, policy, clock), recovery);
}

Async::Task* IO::Flows::makeSocketConnect(QAbstractSocket* socket,
                                          const QString& host,
                                          quint16 port,
                                          int timeout_msec,
                                          Async::AsyncClock& clock)
{
  SS_ASSERT_LOG(port > 0);
  SS_ASSERT_LOG(socket != nullptr);
  SS_ASSERT(
    timeout_msec > 0,
    return failedStep(QStringLiteral("socket-connect"), QStringLiteral("invalid connect timeout")));

  return Async::timeout(new SocketConnectTask(socket, host, port), timeout_msec, clock);
}

int IO::ConnectionManager::activeFlowCount() const
{
  int count = 0;
  for (const auto& [id, dm] : m_devices)
    if (dm && dm->hasActiveFlow())
      ++count;

  return count;
}

int IO::ConnectionManager::reconnectAttempt() const
{
  int attempt = 0;
  for (const auto& [id, dm] : m_devices)
    if (dm)
      attempt = qMax(attempt, dm->reconnectAttempt());

  return attempt;
}

QString IO::ConnectionManager::linkState() const
{
  if (isConnected())
    return QStringLiteral("connected");

  const int attempt = reconnectAttempt();
  if (attempt > 1)
    return QStringLiteral("retrying");

  if (attempt > 0 || hasPendingOpen())
    return QStringLiteral("connecting");

  return QStringLiteral("idle");
}

IO::LinkStats IO::ConnectionManager::linkStats() const
{
  LinkStats stats{};
  for (const auto& [id, dm] : m_devices) {
    const auto* reader = dm ? dm->frameReader() : nullptr;
    if (!reader)
      continue;

    stats.bytesIn         += reader->bytesReceived();
    stats.droppedFrames   += reader->droppedFrameCount();
    stats.overflowBytes   += reader->overflowBytes();
    stats.checksumErrors  += reader->checksumErrorCount();
    stats.framesExtracted += reader->framesExtracted();
  }

  return stats;
}

void IO::ConnectionManager::concludeConnectRequest()
{
  if (!m_connectPending || m_connectFanOut)
    return;

  if (hasPendingOpen())
    return;

  m_connectPending = false;
  endWaitCursor();
 * @brief Raises the wait cursor at most once, so two overlapping requests cannot stack it.
void IO::ConnectionManager::beginWaitCursor()
  if (m_waitCursorActive)
    return;

  m_waitCursorActive = true;
}

void IO::ConnectionManager::endWaitCursor()
{
  if (!m_waitCursorActive)
    return;

  m_waitCursorActive = false;
  QApplication::restoreOverrideCursor();
}

bool IO::ConnectionManager::hasPendingOpen() const
{
  for (const auto& [id, dm] : m_devices)
    if (dm && dm->isOpening())
      return true;

  return false;
}

void IO::ConnectionManager::disconnectDevice()
{
  const bool had_request = m_connectPending;
  beginWaitCursor();
  concludeConnectRequest();
  const bool settled = had_request && !m_connectPending;

  endWaitCursor();

  if (!settled)
    Q_EMIT connectedChanged();

  Q_EMIT sessionClosed();
  SS_ASSERT(driver != nullptr, return);
  m_linkLossNotified             = false;
 * @brief Disconnects the device with the given @p deviceId. Closing cancels an open still in
 *        flight, so the pending request is settled here too: a device closed mid-open would
 *        otherwise strand the request flag and its wait cursor.

  concludeConnectRequest();
 * @brief Disconnects the source owned by @p driver, keeping other sources alive. The teardown may
 *        settle a pending connect request, which reports the state change itself.
  const bool had_request = m_connectPending;
  const bool settled = had_request && !m_connectPending;
  if (!settled)
    Q_EMIT connectedChanged();

  if (!isConnected())
    Q_EMIT sessionClosed();
 * @brief Connects a DeviceManager's output signals to ConnectionManager's routing slots; the data
 * hops are DirectConnection to avoid per-frame postEvent overhead on the main-thread hotpath hop,
 * while the open-completion hop fires once per attempt and stays on the default. The lost-link hop
 * is queued so its teardown and modal cannot run inside the finishing flow's own emission.
  SS_ASSERT(dm != nullptr, return);
  SS_ASSERT_LOG(dm->driver() != nullptr);

  connect(dm, &IO::DeviceManager::openFinished, this, &IO::ConnectionManager::onDeviceOpenFinished);

  connect(dm,
          &IO::DeviceManager::linkStateChanged,
          this,
          &IO::ConnectionManager::onDeviceLinkStateChanged);

  connect(dm,
          &IO::DeviceManager::linkLost,
          this,
          &IO::ConnectionManager::onDeviceLinkLost,
          Qt::QueuedConnection);
}

bool IO::ConnectionManager::diagnosticsBusFor(int deviceId, Misc::Diagnostics::Bus& bus) const
{
  HAL_Driver* halDriver = driver(deviceId);
  if (halDriver == nullptr)
    return false;

  if (qobject_cast<IO::Drivers::UART*>(halDriver) != nullptr)
    bus = Misc::Diagnostics::Bus::Serial;
  else if (qobject_cast<IO::Drivers::Network*>(halDriver) != nullptr)
    bus = Misc::Diagnostics::Bus::Network;
  else if (qobject_cast<IO::Drivers::BluetoothLE*>(halDriver) != nullptr)
    bus = Misc::Diagnostics::Bus::Bluetooth;
#ifdef BUILD_COMMERCIAL
  else if (qobject_cast<IO::Drivers::MQTT*>(halDriver) != nullptr)
    bus = Misc::Diagnostics::Bus::Broker;
  else if (qobject_cast<IO::Drivers::Audio*>(halDriver) != nullptr)
    bus = Misc::Diagnostics::Bus::Audio;
#endif
  else
    return false;

  return true;
}

void IO::ConnectionManager::onDeviceOpenFinished(int deviceId, bool ok, const QString& reason)
{
  SS_ASSERT_LOG(deviceId >= 0);
  SS_ASSERT_LOG(ok || !reason.isEmpty());

  Misc::Diagnostics::Bus bus = Misc::Diagnostics::Bus::Serial;
  if (diagnosticsBusFor(deviceId, bus)) {
    static auto& diagnostics = Misc::ConnectionDiagnostics::instance();
    if (ok)
      diagnostics.onOpenSucceeded(bus);
    else
      diagnostics.onOpenFailed(bus, reason);
  }

  const bool had_request = m_connectPending;
  concludeConnectRequest();

  if (!ok && !had_request)
    Q_EMIT connectedChanged();
}

void IO::ConnectionManager::onDeviceLinkLost(int deviceId, const QString& reason)
{
  SS_ASSERT_LOG(deviceId >= 0);
  SS_ASSERT_LOG(!m_connectFanOut);

  const auto it = m_devices.find(deviceId);
  if (it == m_devices.end() || !it->second)
    return;

  if (it->second->isOpen() || it->second->isOpening())
    return;

  disconnectDevice(deviceId);
  if (!isConnected()) {
    static auto& frameBuilder = DataModel::FrameBuilder::instance();
    frameBuilder.registerQuickPlotHeaders(QStringList());
    Q_EMIT driverChanged();
    Q_EMIT sessionClosed();
  }

  if (m_linkLossNotified)
    return;

  m_linkLossNotified = true;
  Misc::Utilities::showMessageBox(
    tr("Connection Lost"),
    reason.isEmpty() ? tr("The connection was lost and could not be restored.") : reason,
    QMessageBox::Critical);
}

void IO::ConnectionManager::onDeviceLinkStateChanged(int deviceId)
{
  Q_EMIT connectedChanged();

  static auto& notificationCenter = DataModel::NotificationCenter::instance();
  const QString name              = deviceDisplayName(deviceId);

  if (!isDeviceConnected(deviceId)) {
    m_droppedDevices.insert(deviceId);
    notificationCenter.postWarning(QStringLiteral("ConnectionManager"),
                                   tr("%1: link lost").arg(name),
                                   tr("Attempting to reconnect automatically"));
    return;
  }

  if (m_droppedDevices.remove(deviceId)) {
    notificationCenter.postInfo(QStringLiteral("ConnectionManager"),
                                tr("%1: link restored").arg(name),
                                tr("The connection recovered automatically"));
  }
}

QString IO::ConnectionManager::deviceDisplayName(int deviceId) const
{
  static auto& projectModel = DataModel::ProjectModel::instance();
  for (const auto& src : projectModel.sources())
    if (src.sourceId == deviceId && !src.title.isEmpty())
      return src.title;

  return tr("Device %1").arg(deviceId);
 * @brief Rebuilds DeviceManagers for all sources when the project source list changes. Closing the
 *        old devices cancels an open still in flight, so a pending connect request can settle here
 *        and report the state change itself; the transition emission below then runs only when
 *        nothing settled.
  const bool had_request  = m_connectPending;
  m_droppedDevices.clear();
  concludeConnectRequest();
  const bool settled = had_request && !m_connectPending;


  if (!settled && wasConnected != isConnected())
  if (wasConnected && !isConnected())
    Q_EMIT sessionClosed();

  SS_ASSERT(frame != nullptr, return);
  SS_ASSERT_LOG(deviceId >= 0);
  SS_ASSERT_LOG(!frame->data.isEmpty());
  SS_ASSERT(data != nullptr, return);
  SS_ASSERT_LOG(!data->data.isEmpty());
  SS_ASSERT_LOG(deviceId >= 0);
  SS_ASSERT(static_cast<int>(type) >= static_cast<int>(SerialStudio::BusType::UART),
            return nullptr);

int IO::DeviceManager::reconnectAttempt() const
{
  const auto* supervisor = qobject_cast<const IO::SupervisorTask*>(m_runner.root());
  return supervisor ? supervisor->attempt() : 0;
}

void IO::DeviceManager::onDriverOpenFinished(bool ok, const QString& reason)
{
  SS_ASSERT_LOG(m_driver != nullptr);
  SS_ASSERT_LOG(ok || !reason.isEmpty());

  if (!ok && m_runner.isRunning())
    return;

  m_opening = false;
  if (ok)
    m_linkEstablished = true;

  Q_EMIT openFinished(m_deviceId, ok, reason);

  if (ok && !m_linkUp) {
    m_linkUp = true;
    Q_EMIT linkStateChanged(m_deviceId);
  }
}

void IO::DeviceManager::onDriverLinkDropped()
{
  if (!m_linkUp)
    return;

  m_linkUp = false;
  Q_EMIT linkStateChanged(m_deviceId);
}

void IO::DeviceManager::onFlowFinished(Async::Outcome outcome, const Async::StepError& error)
{
  SS_ASSERT_LOG(m_driver != nullptr);

  m_opening = false;
  if (outcome == Async::Outcome::Success || outcome == Async::Outcome::Cancelled)
    return;

  m_linkUp          = false;
  const bool lost   = m_linkEstablished;
  m_linkEstablished = false;

  Q_EMIT openFinished(m_deviceId, false, error.reason);
  if (lost)
    Q_EMIT linkLost(m_deviceId, error.reason);
}

bool IO::Drivers::BluetoothLE::open(const QIODevice::OpenMode mode)
{
  beginOpen(mode);
  return isOpen() || m_runner.isRunning();
}

void IO::Drivers::BluetoothLE::abortOpen()
{
  ++m_openEpoch;
  m_connecting    = false;
  m_userWantsOpen = false;
  m_runner.cancel();
  close();
}

bool IO::Drivers::BluetoothLE::adapterPoweredOn()
{
  initializeSharedState();
  return s_adapterAvailable;
}

Async::Task* IO::Drivers::BluetoothLE::buildOpenFlow()
{
  auto* group = Async::sequential(QStringLiteral("ble-open"));
  group->addChild(makeDiscoveryStep());
  group->addChild(Async::invoke(QStringLiteral("ble-dial"),
                                [this](QString& reason) { return dialSelectedDevice(reason); }));
  group->addChild(makeConnectStep());
  group->addChild(makeGattStep());

  return group;
}

Async::Task* IO::Drivers::BluetoothLE::makeDiscoveryStep()
{
  if (m_deviceIndex >= 0 && m_deviceIndex < s_devices.count())
    return Async::invoke(QStringLiteral("ble-discovery"), [](QString& reason) {
      Q_UNUSED(reason);
      return true;
    });

  startDiscovery();
  if (!s_adapterAvailable)
    return Async::invoke(QStringLiteral("ble-discovery"), [](QString& reason) {
      reason = QStringLiteral("the Bluetooth adapter is off");
      return false;
    });

  auto* step = Async::awaitSignal(QStringLiteral("ble-discovery"));
  step->onSuccess(this, &IO::Drivers::BluetoothLE::deviceIndexChanged);

  return Async::timeout(step, discoveryWindowMs(), m_runner.clock());
}

Async::Task* IO::Drivers::BluetoothLE::makeConnectStep()
{
  auto* step = Async::awaitSignal(QStringLiteral("ble-connect"));
  step->onSuccess(this, &IO::Drivers::BluetoothLE::linkEstablished);
  step->onFailure(
    this, &IO::Drivers::BluetoothLE::linkFailed, QStringLiteral("BLE controller error"));

  return Async::timeout(step, kBleConnectTimeoutMs, m_runner.clock());
}

Async::Task* IO::Drivers::BluetoothLE::makeGattStep()
{
  auto* services = Async::awaitSignal(QStringLiteral("ble-services"));
  services->onSuccess(this, &IO::Drivers::BluetoothLE::servicesResolved);
  services->onFailure(
    this, &IO::Drivers::BluetoothLE::linkFailed, QStringLiteral("BLE controller error"));

  auto* subscribe = Async::awaitSignal(QStringLiteral("ble-subscribe"));
  subscribe->onSuccess(this, &IO::Drivers::BluetoothLE::gattReady);
  subscribe->onFailure(
    this, &IO::Drivers::BluetoothLE::linkFailed, QStringLiteral("BLE controller error"));

  auto* group = Async::parallel(QStringLiteral("ble-gatt"));
  group->addChild(Async::timeout(services, kBleServicesTimeoutMs, m_runner.clock()));
  group->addChild(Async::timeout(subscribe, kBleSubscribeTimeoutMs, m_runner.clock()));

  return group;
}

bool IO::Drivers::BluetoothLE::dialSelectedDevice(QString& reason)
{
  if (m_deviceIndex < 0 || m_deviceIndex >= s_devices.count()) {
    reason = QStringLiteral("no BLE device selected");
    return false;
  }

  const auto device = s_devices.at(m_deviceIndex);
  m_controller      = QLowEnergyController::createCentral(device, this);
  if (!m_controller) {
    reason = QStringLiteral("could not create a BLE controller for the selected device");
    return false;
  }

  connect(m_controller,
          &QLowEnergyController::discoveryFinished,
          this,
          &IO::Drivers::BluetoothLE::onServiceDiscoveryFinished);
  connect(m_controller,
          &QLowEnergyController::connected,
          this,
          &IO::Drivers::BluetoothLE::onControllerConnected);
  connect(m_controller,
          &QLowEnergyController::disconnected,
          this,
          &IO::Drivers::BluetoothLE::onControllerDisconnected);
  connect(m_controller,
          &QLowEnergyController::errorOccurred,
          this,
          &IO::Drivers::BluetoothLE::onControllerError);

  const quint64 epoch = m_openEpoch;
  QMetaObject::invokeMethod(this, [this, epoch]() { dialController(epoch); }, Qt::QueuedConnection);

  return true;
}

void IO::Drivers::BluetoothLE::dialController(const quint64 epoch)
{
  if (epoch != m_openEpoch || !m_controller)
    return;

  m_controller->connectToDevice();
}

int IO::Drivers::BluetoothLE::discoveryWindowMs() const
{
  if (s_discoveryAgent && s_discoveryAgent->lowEnergyDiscoveryTimeout() > 0)
    return s_discoveryAgent->lowEnergyDiscoveryTimeout();

  return kBleScanWindowMs;
}

void IO::Drivers::BluetoothLE::onControllerConnected()
{
  if (!m_controller)
    return;

  m_deviceConnected = true;
  m_controller->discoverServices();
  Q_EMIT deviceConnectedChanged();
  Q_EMIT linkEstablished();
}

void IO::Drivers::BluetoothLE::onControllerDisconnected()
{
  const bool attempting = m_connecting;
  const bool dropped    = m_userWantsOpen && !attempting;
  close();

  if (attempting) {
    m_openFailure = QStringLiteral("the peripheral closed the connection");
    Q_EMIT linkFailed();
    return;
  }

  if (dropped)
    Q_EMIT linkDropped();
}

void IO::Drivers::BluetoothLE::onControllerError(QLowEnergyController::Error controllerError)
{
  if (controllerError == QLowEnergyController::NoError)
    return;

  m_openFailure = m_controller ? m_controller->errorString() : QString();
  if (m_openFailure.isEmpty())
    m_openFailure = QStringLiteral("BLE controller error");

  Q_EMIT linkFailed();
}

void IO::Drivers::BluetoothLE::onOpenFlowFinished(Async::Outcome outcome,
                                                  const Async::StepError& error)
{
  m_connecting = false;
  if (outcome == Async::Outcome::Cancelled)
    return;

  if (outcome == Async::Outcome::Success) {
    Q_EMIT openFinished(true, QString());
    return;
  }

  QString reason = m_openFailure.isEmpty() ? error.reason : m_openFailure;
  if (reason.isEmpty())
    reason = QStringLiteral("BLE open failed");

  close();
  Q_EMIT openFinished(false, reason);
}

bool IO::Drivers::MQTT::claimFailureReport()
{
  if (m_failureNotified || m_sessionEstablished)
    return false;

  m_failureNotified = true;
  return true;
}

bool IO::Drivers::MQTT::openRequestAccepted(QString& reason)
{
    if (claimFailureReport())
      Misc::Utilities::showMessageBox(
        tr("MQTT Feature Requires a Commercial License"),
        tr("Subscribing to an MQTT broker is only available with a valid Serial Studio license "
           "or an active trial."),
        QMessageBox::Warning);

    reason = QStringLiteral("a commercial license is required");
    reason = QStringLiteral("the broker hostname or port is missing");
    reason = QStringLiteral("the topic filter is empty");
  return true;
}

Async::Task* IO::Drivers::MQTT::buildOpenFlow()
{
  auto* group = Async::sequential(QStringLiteral("mqtt-open"));

  if (m_client.state() == QMqttClient::Disconnected)
    group->addChild(Async::invoke(QStringLiteral("broker-dial"),
                                  [this](QString& reason) { return dialBroker(reason); }));

  group->addChild(makeConnectStep());
  group->addChild(Async::invoke(QStringLiteral("broker-subscribe"),
                                [this](QString& reason) { return subscribeToTopic(reason); }));

  return group;
}

Async::Task* IO::Drivers::MQTT::buildReconnectFlow()
{
  auto* group = Async::sequential(QStringLiteral("mqtt-reconnect"));

    auto* wait = Async::awaitSignal(QStringLiteral("broker-disconnect"));
    wait->onSuccess(&m_client, &QMqttClient::disconnected);
    group->addChild(Async::timeout(wait, kBrokerDisconnectTimeoutMs, m_runner.clock()));
  if (!m_userWantsOpen)
    return group;

  group->addChild(Async::invoke(QStringLiteral("broker-dial"),
                                [this](QString& reason) { return dialBroker(reason); }));
  group->addChild(makeConnectStep());
  group->addChild(Async::invoke(QStringLiteral("broker-subscribe"),
                                [this](QString& reason) { return subscribeToTopic(reason); }));

  return group;
}

Async::Task* IO::Drivers::MQTT::makeConnectStep()
{
  auto* step = Async::awaitSignal(QStringLiteral("broker-connect"));
  step->onSuccess(&m_client, &QMqttClient::connected);
  step->onFailure(
    &m_client, &QMqttClient::disconnected, QStringLiteral("the broker closed the connection"));
  step->setAbortHandler([this]() { m_client.disconnectFromHost(); });

  return Async::timeout(step, kBrokerConnectTimeoutMs, m_runner.clock());
}

bool IO::Drivers::MQTT::subscribeToTopic(QString& reason)
{
  if (m_topicFilter.isEmpty())
    return true;

  QMqttTopicFilter filter;
  filter.setFilter(m_topicFilter);

  auto* sub = m_client.subscribe(filter, 0);
  if (!sub || sub->state() == QMqttSubscription::Error) {
    qCCritical(lcMqttSub) << "subscribe failed for filter" << m_topicFilter;
    m_client.disconnectFromHost();
    reason = tr("Failed to subscribe to topic \"%1\".").arg(m_topicFilter);
    return false;
  }

  qCInfo(lcMqttSub) << "subscribed to" << m_topicFilter << "initial state:" << sub->state();
  connect(
    sub, &QMqttSubscription::stateChanged, this, [this](QMqttSubscription::SubscriptionState s) {
      qCInfo(lcMqttSub) << "subscription state for" << m_topicFilter << "->" << s;
    });

  return true;
}

void IO::Drivers::MQTT::onOpenFlowFinished(Async::Outcome outcome, const Async::StepError& error)
{
  if (outcome == Async::Outcome::Cancelled)
    return;

  m_connecting = false;
  if (outcome == Async::Outcome::Success) {
    if (isOpen())
      Q_EMIT openFinished(true, QString());
    else if (m_userWantsOpen)
      Q_EMIT openFinished(false, tr("The broker closed the connection."));

    return;
  }

  const QString reason = error.reason.isEmpty() ? QStringLiteral("open failed") : error.reason;
  Q_EMIT openFinished(false, reason);
}

[[nodiscard]] static bool firstOpenAttempt()
{
  static auto& connectionManager = IO::ConnectionManager::instance();
  return connectionManager.reconnectAttempt() <= 1;
}

static void queueErrorBox(QObject* context, const QString& title, const QString& text)
{
  QMetaObject::invokeMethod(
    context,
    [title, text] { Misc::Utilities::showMessageBox(title, text, QMessageBox::Critical); },
    Qt::QueuedConnection);
}

Async::Task* IO::Drivers::Modbus::makeConnectStep()
{
  auto* step = Async::awaitSignal(QStringLiteral("modbus-connect"));
  step->onSuccess(this, &IO::Drivers::Modbus::deviceConnected);
  step->onFailure(this,
                  &IO::Drivers::Modbus::deviceDisconnected,
                  QStringLiteral("the device refused the connection"));
  step->setAbortHandler([this]() {
    if (m_device)
      m_device->disconnectDevice();
  });
  return Async::timeout(step, kConnectTimeoutMs, m_runner.clock());
    if (firstOpenAttempt())
      queueErrorBox(this,
                    tr("Invalid Serial Port"),
                    tr("The selected serial port \"%1\" is no longer available. "
                       "Refresh the port list and try again.")
                      .arg(ports.value(portId)));

 * @brief Creates and wires the Modbus client for one attempt, reporting why the request cannot be
 *        started when the settings or the platform refuse it.
bool IO::Drivers::Modbus::prepareDevice(QString& reason)
  if (!configurationOk()) {
    reason = QStringLiteral("the Modbus connection settings are incomplete");
    return false;
  }

void IO::Drivers::Network::beginOpen(const QIODevice::OpenMode mode)
{
  SS_ASSERT(mode != QIODevice::NotOpen, {
    Q_EMIT openFinished(false, QStringLiteral("invalid open mode"));
    return;
  });

  m_connecting    = true;
  m_userWantsOpen = true;
  m_runner.run(buildOpenFlow(mode));
}

Async::Task* IO::Drivers::Network::buildOpenFlow(const QIODevice::OpenMode mode)
{
  SS_ASSERT_LOG(mode != QIODevice::NotOpen);

  auto* group = Async::sequential(QStringLiteral("network-open"));
  group->addChild(makeLookupStep());
    auto host = remoteAddress();
    if (host.isEmpty())
      host = defaultAddress();
    group->addChild(Flows::makeSocketConnect(
      &m_tcpSocket, host, tcpPort(), kTcpConnectTimeoutMs, m_runner.clock()));
  else
    group->addChild(Async::invoke(QStringLiteral("udp-bind"),
                                  [this](QString& reason) { return bindUdpSocket(reason); }));
  group->addChild(Async::invoke(QStringLiteral("socket-activate"), [this, mode](QString& reason) {
    return activateSocket(mode, reason);
  }));
  return group;
}

Async::Task* IO::Drivers::Network::makeLookupStep()
{
  if (!m_lookupActive)
    return Async::invoke(QStringLiteral("dns-lookup"), [](QString& reason) {
      Q_UNUSED(reason);
      return true;
    });

  auto* step = Async::awaitSignal(QStringLiteral("dns-lookup"));
  step->onSuccess(this, &IO::Drivers::Network::lookupActiveChanged);
  step->setAbortHandler([this]() { abortLookup(); });

  return Async::timeout(step, kLookupTimeoutMs, m_runner.clock());
}

disconnect during an attempt is the attempt's own
 *        business and is not a drop.
 */
void IO::Drivers::Network::onSocketDisconnected()
{
  if (!m_userWantsOpen || m_connecting)
    return;

  Q_EMIT linkDropped();
}

void IO::Drivers::Network::onOpenFlowFinished(Async::Outcome outcome, const Async::StepError& error)
{
  if (outcome == Async::Outcome::Cancelled)
    return;

  m_connecting = false;
  if (outcome == Async::Outcome::Success) {
    Q_EMIT openFinished(true, QString());
    return;
  }

  const QString reason = error.reason.isEmpty() ? QStringLiteral("open failed") : error.reason;
  close();
  Q_EMIT openFinished(false, reason);
}

bool IO::Drivers::UART::applyErrorPolicy(QSerialPort::SerialPortError error)
{
    return false;
  if (!isOpen() || error == QSerialPort::NoError)
    return false;
  if (m_usingCustomSerialPort
      && (error == QSerialPort::UnsupportedOperationError || error == QSerialPort::ResourceError))
    return false;
  if (m_autoReconnect && error == QSerialPort::ResourceError)
    return true;
  static auto& connectionManager = ConnectionManager::instance();
  connectionManager.disconnectDevice(this);
  const auto name = serialPort ? serialPort->portName() : tr("Unknown");
  Misc::Utilities::showMessageBox(tr("Critical error on serial port \"%1\"").arg(name),
                                  m_errorDescriptions.value(error, tr("Unknown error")),
                                  QMessageBox::Critical);
  return false;

void IO::FrameReader::resetDiagnosticCounters() noexcept
{
  m_bytesIn            = 0;
  m_droppedFrames      = 0;
  m_checksumErrors     = 0;
  m_framesExtracted    = 0;
  m_totalOverflowBytes = 0;
}

CLI::ProcessResult CLI::runSelfTests()
{
  const QString suite = m_parser.value(m_opts.selftestSuiteOpt).trimmed();
  const int rc        = SelfTest::Runner::runAndReport(suite);
  return rc == EXIT_SUCCESS ? ProcessResult::ExitSuccess : ProcessResult::ExitFailure;
}

void CLI::applyApiServerOptions()
{
  if (!apiServerEnabled() && !apiExternalEnabled() && !m_parser.isSet(m_opts.apiTokenOpt))
    return;

  static auto& apiServer = API::Server::instance();

  if (m_parser.isSet(m_opts.apiTokenOpt)
      && !apiServer.setAuthToken(m_parser.value(m_opts.apiTokenOpt)))
    qWarning() << "[CLI] --api-token ignored: expected at least 32 hexadecimal characters";

  if (apiExternalEnabled())
    apiServer.allowExternalConnections();

  if (apiServerEnabled())
    apiServer.setEnabled(true);
}

Misc::detail::ProbeTask::ProbeTask(Async::Task* child, Reporter reporter)
  : Async::Task(child != nullptr ? child->name() : QStringLiteral("probe"))
  , m_child(child)
  , m_reporter(std::move(reporter))
{
  SS_ASSERT_LOG(m_child != nullptr);
  SS_ASSERT_LOG(static_cast<bool>(m_reporter));

  m_child->setParent(this);
  connect(m_child, &Async::Task::finished, this, &ProbeTask::onChildFinished);
}

void Misc::detail::ProbeTask::doStart()
{
  SS_ASSERT(m_child != nullptr, {
    reportFinished(Async::Outcome::Success, Async::StepError());
    return;
  });
  SS_ASSERT_LOG(!m_child->isRunning());

  m_child->start();
}

void Misc::detail::ProbeTask::doCancel()
{
  SS_ASSERT(m_child != nullptr, return);

  if (m_child->isRunning())
    m_child->cancel();
}

void Misc::detail::ProbeTask::onChildFinished(Async::Outcome outcome, const Async::StepError& error)
{
  SS_ASSERT_LOG(m_child != nullptr);

  if (!isRunning())
    return;

  if (outcome == Async::Outcome::Cancelled) {
    reportFinished(outcome, error);
    return;
  }

  m_reporter(outcome, error);
  reportFinished(Async::Outcome::Success, Async::StepError());
}

Misc::ConnectionDiagnostics& Misc::ConnectionDiagnostics::instance()
{
  static ConnectionDiagnostics singleton;
  return singleton;
}

bool Misc::ConnectionDiagnostics::hasFailure() const noexcept
{
  const Result* top = topResult();
  return top != nullptr && top->verdict >= Diagnostics::Verdict::Warning;
}

QString Misc::ConnectionDiagnostics::lastRunTime() const
{
  if (!m_lastRun.isValid())
    return QString();

  return QLocale::system().toString(m_lastRun.time(), QLocale::ShortFormat);
}

QString Misc::ConnectionDiagnostics::failureTitle() const
{
  const Result* top = topResult();
  return top != nullptr ? top->title : QString();
}

QString Misc::ConnectionDiagnostics::failureRemedy() const
{
  const Result* top = topResult();
  return top != nullptr ? top->remedy : QString();
}

QList<Misc::ConnectionDiagnostics::Result> Misc::ConnectionDiagnostics::results(BusMask scope) const
{
  QList<Result> list;
  for (int i = 0; i < kBusCount; ++i)
    if (scopeCovers(scope, static_cast<Bus>(i)))
      list.append(m_results[static_cast<size_t>(i)]);

  return list;
}

Misc::ConnectionDiagnostics::BusMask Misc::ConnectionDiagnostics::supportedBuses() noexcept
{
  BusMask mask = busBit(Bus::Serial) | busBit(Bus::Bluetooth) | busBit(Bus::Network);

#ifdef BUILD_COMMERCIAL
  mask |= busBit(Bus::Broker) | busBit(Bus::Audio);
#endif

  return mask;
}

Misc::ConnectionDiagnostics::BusMask Misc::ConnectionDiagnostics::probingBuses(BusMask scope)
{
  BusMask mask                 = kBusNone;
  const Bus candidates[]       = {Bus::Network, Bus::Broker};
  constexpr int kCandidateSize = 2;

  for (int i = 0; i < kCandidateSize; ++i) {
    QString host;
    quint16 port = 0;
    if (!scopeCovers(scope, candidates[i]))
      continue;

    if (!Diagnostics::NetworkChecks::endpoint(candidates[i], host, port))
      continue;

    if (!host.isEmpty() && port != 0)
      mask |= busBit(candidates[i]);
  }

  return mask;
}

int Misc::ConnectionDiagnostics::estimatedMsec(BusMask scope)
{
  const auto probing = probingBuses(scope);

  int count = 0;
  for (int i = 0; i < kBusCount; ++i)
    if (scopeCovers(probing, static_cast<Bus>(i)))
      ++count;

  return qMin(count * Diagnostics::NetworkChecks::probeBudgetMsec(), kRunTimeoutMs);
}

void Misc::ConnectionDiagnostics::run(BusMask scope)
{
  scope &= supportedBuses();
  if (scope == kBusNone)
    return;

  if (m_running && (m_activeScope & scope) == scope)
    return;

  runInstant(scope);

  Async::Task* root = buildProbeTree(scope);
  if (root == nullptr)
    return;

  m_running     = true;
  m_activeScope = scope;
  Q_EMIT runningChanged();

  m_runner.run(root);
}

void Misc::ConnectionDiagnostics::runInstant(BusMask scope)
{
  scope &= supportedBuses();
  if (scope == kBusNone)
    return;

  clearScope(scope);

  QList<Result> scratch;
  if (scopeCovers(scope, Bus::Serial))
    Diagnostics::SerialChecks::collect(scratch);

  if (scopeCovers(scope, Bus::Bluetooth))
    Diagnostics::BluetoothChecks::collect(scratch);

  if (scopeCovers(scope, Bus::Network))
    Diagnostics::NetworkChecks::collectInstant(Bus::Network, scratch);

#ifdef BUILD_COMMERCIAL
  if (scopeCovers(scope, Bus::Broker))
    Diagnostics::NetworkChecks::collectInstant(Bus::Broker, scratch);

  if (scopeCovers(scope, Bus::Audio))
    Diagnostics::AudioChecks::collect(scratch);
#endif

  for (const auto& result : std::as_const(scratch))
    store(result);

  m_lastRun = QDateTime::currentDateTime();
  publish();
}

void Misc::ConnectionDiagnostics::onOpenFailed(Bus bus, const QString& reason)
{
  Q_UNUSED(reason)

  const BusMask scope = busBit(bus) & supportedBuses();
  if (scope == kBusNone)
    return;

  if (allowAutoProbe(bus)) {
    run(scope);
    return;
  }

  runInstant(scope);
}

void Misc::ConnectionDiagnostics::onOpenSucceeded(Bus bus)
{
  const auto index = static_cast<size_t>(bus);
  m_autoRunClocks[index].invalidate();

  if (m_results[index].isEmpty())
    return;

  m_results[index].clear();
  publish();
}

void Misc::ConnectionDiagnostics::setupExternalConnections()
{
  connect(&m_runner, &Async::TaskRunner::finished, this, &ConnectionDiagnostics::onRunFinished);

  auto& center = Misc::ProblemCenter::instance();
  m_problems   = &center;
  for (int i = 0; i < kBusCount; ++i) {
    const auto bus = static_cast<Bus>(i);
    center.registerChecker(
      Diagnostics::checkerId(bus),
      Misc::ProblemCenter::OnDemand,
      [this, bus](QList<ProblemCenter::Finding>& out) { appendCached(bus, out); });
  }
}

void Misc::ConnectionDiagnostics::publish()
{
  SS_ASSERT(m_problems != nullptr, return);

  m_problems->runNow();
  Q_EMIT resultsChanged();
}

void Misc::ConnectionDiagnostics::clearScope(BusMask scope)
{
  for (int i = 0; i < kBusCount; ++i)
    if (scopeCovers(scope, static_cast<Bus>(i)))
      m_results[static_cast<size_t>(i)].clear();
}

void Misc::ConnectionDiagnostics::store(const Result& result)
{
  if (result.verdict == Diagnostics::Verdict::Pass)
    return;

  const auto index = static_cast<size_t>(result.bus);
  SS_ASSERT(index < m_results.size(), return);

  m_results[index].append(result);
}

void Misc::ConnectionDiagnostics::appendCached(Bus bus, QList<ProblemCenter::Finding>& out) const
{
  const auto index = static_cast<size_t>(bus);
  SS_ASSERT(index < m_results.size(), return);

  for (const auto& result : m_results[index])
    out.append(Diagnostics::toFinding(result));
}

const Misc::ConnectionDiagnostics::Result* Misc::ConnectionDiagnostics::topResult() const noexcept
{
  const Result* best = nullptr;
  for (const auto& slice : m_results) {
    for (const auto& result : slice)
      if (best == nullptr || result.verdict > best->verdict)
        best = &result;
  }

  return best;
}

bool Misc::ConnectionDiagnostics::allowAutoProbe(Bus bus)
{
  auto& clock = m_autoRunClocks[static_cast<size_t>(bus)];
  if (clock.isValid() && clock.elapsed() < kAutoRunWindowMs)
    return false;

  clock.start();
  return true;
}

void Misc::ConnectionDiagnostics::addReachabilityProbe(Async::SequentialGroup* group, Bus bus)
{
  SS_ASSERT(group != nullptr, return);

  QString host;
  quint16 port = 0;
  if (!Diagnostics::NetworkChecks::endpoint(bus, host, port))
    return;

  if (host.isEmpty() || port == 0)
    return;

  auto* flow = Diagnostics::NetworkChecks::makeReachabilityFlow(host, port, m_runner.clock());
  ProbeTask::Reporter reporter = [this, bus, host, port](Async::Outcome outcome,
                                                         const Async::StepError& error) {
    store(Diagnostics::NetworkChecks::reachabilityResult(bus, host, port, outcome, error));
  };

  group->addChild(new ProbeTask(flow, std::move(reporter)));
}

Async::Task* Misc::ConnectionDiagnostics::buildProbeTree(BusMask scope)
{
  auto* group = Async::sequential(QStringLiteral("connection-diagnostics"));

  if (scopeCovers(scope, Bus::Network))
    addReachabilityProbe(group, Bus::Network);

  if (scopeCovers(scope, Bus::Broker))
    addReachabilityProbe(group, Bus::Broker);

  if (group->childCount() > 0)
    return Async::timeout(group, kRunTimeoutMs, m_runner.clock());

  delete group;
  return nullptr;
}

void Misc::ConnectionDiagnostics::onRunFinished(Async::Outcome outcome,
                                                const Async::StepError& error)
{
  Q_UNUSED(outcome)
  Q_UNUSED(error)

  m_running     = false;
  m_activeScope = kBusNone;
  m_lastRun     = QDateTime::currentDateTime();

  publish();
  Q_EMIT runningChanged();
  Q_EMIT runFinished();
}

static void reportPermission(QList<Result>& out)
{
#if QT_CONFIG(permissions)
  auto* app = QCoreApplication::instance();
  if (app == nullptr)
    return;

  if (app->checkPermission(QMicrophonePermission{}) != Qt::PermissionStatus::Denied)
    return;

  out.append(makeResult(Bus::Audio,
                        Verdict::Failure,
                        "audio-permission-denied",
                        trDiag("Microphone access is not permitted"),
                        trDiag("The system has refused Serial Studio permission to record "
                               "audio, so no input device can be opened."),
                        trDiag("Allow Serial Studio to use the microphone in the system's "
                               "privacy settings, then restart the application.")));
#else
  Q_UNUSED(out)
#endif
}

static void reportMissingSelection(const QStringList& devices, QList<Result>& out)
{
  QSettings settings;
  const auto key      = QStringLiteral("AudioDriver/inputDeviceName");
  const auto selected = settings.value(key).toString();
  if (selected.isEmpty() || devices.contains(selected))
    return;

  out.append(makeResult(Bus::Audio,
                        Verdict::Warning,
                        "audio-input-missing",
                        trDiag("The selected audio input is gone"),
                        trDiag("Input device %1 was selected previously and the audio backend "
                               "does not report it any more.")
                          .arg(selected),
                        trDiag("Reconnect the device, or select another input in the device "
                               "setup pane.")));
}

static void reportBackend(QList<Result>& out)
{
  static auto& manager = IO::ConnectionManager::instance();

  auto* audio = manager.audio();
  if (audio == nullptr)
    return;

  if (!audio->backendReady()) {
    out.append(makeResult(Bus::Audio,
                          Verdict::Failure,
                          "audio-backend-failed",
                          trDiag("The audio backend did not start"),
                          trDiag("Serial Studio could not initialize the system's audio "
                                 "backend, so no input or output device is available."),
                          trDiag("Confirm the system's audio service is running, then restart "
                                 "the application.")));
    return;
  }

  const auto devices = audio->inputDeviceList();
  if (devices.isEmpty()) {
    out.append(makeResult(Bus::Audio,
                          Verdict::Warning,
                          "no-audio-inputs",
                          trDiag("No audio input devices were found"),
                          trDiag("The audio backend reports no capture device, so there is "
                                 "nothing for this bus to record from."),
                          trDiag("Connect a microphone or line-in device, then run the check "
                                 "again.")));
    return;
  }

  reportMissingSelection(devices, out);
}

void Misc::Diagnostics::AudioChecks::collect(QList<Result>& out)
{
  reportPermission(out);
  reportBackend(out);
}

[[nodiscard]] static QString powerOnRemedy()
{
#if defined(Q_OS_WINDOWS)
  return trDiag("Turn Bluetooth on in Settings > Bluetooth & devices.");
#elif defined(Q_OS_MACOS)
  return trDiag("Turn Bluetooth on in System Settings > Bluetooth.");
#else
  return trDiag("Turn Bluetooth on in the desktop's Bluetooth settings, or run %1.")
    .arg(QStringLiteral("rfkill unblock bluetooth"));
#endif
}

[[nodiscard]] static QString permissionRemedy()
{
#if defined(Q_OS_MACOS)
  return trDiag("Allow Serial Studio under System Settings > Privacy & Security > Bluetooth, "
                "then restart the application.");
#else
  return trDiag("Grant Serial Studio the Bluetooth permission in the system's privacy settings, "
                "then restart the application.");
#endif
}

static void reportPermission(QList<Result>& out)
{
#if QT_CONFIG(permissions)
  auto* app = QCoreApplication::instance();
  if (app == nullptr)
    return;

  if (app->checkPermission(QBluetoothPermission{}) != Qt::PermissionStatus::Denied)
    return;

  out.append(makeResult(Bus::Bluetooth,
                        Verdict::Failure,
                        "ble-permission-denied",
                        trDiag("Bluetooth access is not permitted"),
                        trDiag("The system has refused Serial Studio permission to use "
                               "Bluetooth, so no device can be discovered."),
                        permissionRemedy()));
#else
  Q_UNUSED(out)
#endif
}

static void reportAdapter(QList<Result>& out)
{
  if (IO::Drivers::BluetoothLE::adapterPoweredOn())
    return;

  out.append(makeResult(Bus::Bluetooth,
                        Verdict::Failure,
                        "ble-adapter-off",
                        trDiag("Bluetooth is turned off"),
                        trDiag("No powered-on Bluetooth adapter was found, so no device can be "
                               "discovered or connected."),
                        powerOnRemedy()));
}

[[nodiscard]] static bool reportPlatformSupport(QList<Result>& out)
{
  static auto& manager = IO::ConnectionManager::instance();

  auto* ble = manager.bluetoothLE();
  if (ble != nullptr && ble->operatingSystemSupported())
    return true;

  out.append(makeResult(Bus::Bluetooth,
                        Verdict::Warning,
                        "ble-unsupported",
                        trDiag("Bluetooth Low Energy is not available"),
                        trDiag("This build of the operating system does not provide the "
                               "Bluetooth Low Energy support Serial Studio needs."),
                        trDiag("Use another bus, or run Serial Studio on a system with "
                               "Bluetooth Low Energy support.")));
  return false;
}

void Misc::Diagnostics::BluetoothChecks::collect(QList<Result>& out)
{
  if (!reportPlatformSupport(out))
    return;

  reportPermission(out);
  reportAdapter(out);
}

[[nodiscard]] static bool sessionHasGid(gid_t gid)
{
  if (::getgid() == gid || ::getegid() == gid)
    return true;

  std::vector<gid_t> groups(kMaxSupplementaryGroups, 0);
  const int count = ::getgroups(kMaxSupplementaryGroups, groups.data());
  if (count <= 0)
    return false;

  SS_ASSERT_LOG(count <= kMaxSupplementaryGroups);

  for (int i = 0; i < count && i < kMaxSupplementaryGroups; ++i)
    if (groups[static_cast<size_t>(i)] == gid)
      return true;

  return false;
}

static void describeGroup(gid_t gid, Misc::Diagnostics::DeviceAccess& result)
{
  const struct group* entry = ::getgrgid(gid);
  if (entry == nullptr || entry->gr_name == nullptr)
    return;

  result.ownerGroup      = QString::fromLocal8Bit(entry->gr_name);
  result.sessionHasGroup = sessionHasGid(gid);

  const auto account = Misc::Diagnostics::currentAccountName();
  if (account.isEmpty() || entry->gr_mem == nullptr)
    return;

  for (int i = 0; i < kMaxGroupMembers && entry->gr_mem[i] != nullptr; ++i) {
    if (account == QString::fromLocal8Bit(entry->gr_mem[i])) {
      result.accountInGroup = true;
      return;
    }
  }
}

QString Misc::Diagnostics::currentAccountName()
{
#ifdef Q_OS_UNIX
  const struct passwd* entry = ::getpwuid(::getuid());
  if (entry != nullptr && entry->pw_name != nullptr)
    return QString::fromLocal8Bit(entry->pw_name);
#endif

  return QString();
}

Misc::Diagnostics::DeviceAccess Misc::Diagnostics::probeDeviceNode(const QString& path)
{
  DeviceAccess result;
  if (path.isEmpty())
    return result;

#ifdef Q_OS_UNIX
  const QByteArray native = QFile::encodeName(path);
  SS_ASSERT(!native.isEmpty(), return result);

  struct stat node = {};
  if (::stat(native.constData(), &node) != 0)
    return result;

  result.exists      = true;
  result.accessKnown = true;
  result.readable    = ::access(native.constData(), R_OK) == 0;
  result.writable    = ::access(native.constData(), W_OK) == 0;
  describeGroup(node.st_gid, result);
#else
  result.exists = QFileInfo::exists(path);
#endif

  return result;
}

Misc::Diagnostics::NetworkChecks::HostLookupTask::HostLookupTask(QString host, QObject* parent)
  : Async::Task(QString::fromLatin1(kHostLookupStep), parent)
  , m_lookupId(kInvalidLookup)
  , m_host(std::move(host))
{
  SS_ASSERT_LOG(!m_host.isEmpty());
}

void Misc::Diagnostics::NetworkChecks::HostLookupTask::doStart()
{
  SS_ASSERT(!m_host.isEmpty(), {
    reportFinished(Async::Outcome::Failure, errorHere(QStringLiteral("no host configured")));
    return;
  });
  SS_ASSERT_LOG(m_lookupId == kInvalidLookup);

  QHostAddress literal;
  if (literal.setAddress(m_host)) {
    reportFinished(Async::Outcome::Success, Async::StepError());
    return;
  }

  m_lookupId =
    QHostInfo::lookupHost(m_host, this, [this](const QHostInfo& info) { onLookupFinished(info); });
}

void Misc::Diagnostics::NetworkChecks::HostLookupTask::abortLookup()
{
  if (m_lookupId == kInvalidLookup)
    return;

  QHostInfo::abortHostLookup(m_lookupId);
  m_lookupId = kInvalidLookup;
}

void Misc::Diagnostics::NetworkChecks::HostLookupTask::onLookupFinished(const QHostInfo& info)
{
  m_lookupId = kInvalidLookup;
  if (!isRunning())
    return;

  if (info.error() == QHostInfo::NoError && !info.addresses().isEmpty()) {
    reportFinished(Async::Outcome::Success, Async::StepError());
    return;
  }

  auto reason = info.errorString();
  if (reason.isEmpty())
    reason = QStringLiteral("host not found");

  reportFinished(Async::Outcome::Failure, errorHere(reason));
}

Misc::Diagnostics::NetworkChecks::TcpProbeTask::TcpProbeTask(QString host,
                                                             quint16 port,
                                                             QObject* parent)
  : Async::Task(QString::fromLatin1(kTcpProbeStep), parent), m_port(port), m_host(std::move(host))
{
  SS_ASSERT_LOG(!m_host.isEmpty());
  SS_ASSERT_LOG(m_port != 0);
}

Misc::Diagnostics::NetworkChecks::TcpProbeTask::~TcpProbeTask()
{
  releaseConnections();
  m_socket.abort();
}

void Misc::Diagnostics::NetworkChecks::TcpProbeTask::doStart()
{
  SS_ASSERT(!m_host.isEmpty() && m_port != 0, {
    reportFinished(Async::Outcome::Failure, errorHere(QStringLiteral("no endpoint configured")));
    return;
  });

  m_connectedConnection =
    connect(&m_socket, &QTcpSocket::connected, this, &TcpProbeTask::onConnected);
  m_errorConnection =
    connect(&m_socket, &QAbstractSocket::errorOccurred, this, &TcpProbeTask::onErrorOccurred);

  m_socket.connectToHost(m_host, m_port, QIODevice::ReadOnly);
}

void Misc::Diagnostics::NetworkChecks::TcpProbeTask::doCancel()
{
  releaseConnections();
  m_socket.abort();
}

void Misc::Diagnostics::NetworkChecks::TcpProbeTask::releaseConnections()
{
  QObject::disconnect(m_errorConnection);
  QObject::disconnect(m_connectedConnection);
  m_errorConnection     = QMetaObject::Connection();
  m_connectedConnection = QMetaObject::Connection();
}

void Misc::Diagnostics::NetworkChecks::TcpProbeTask::onConnected()
{
  if (!isRunning())
    return;

  releaseConnections();
  m_socket.abort();
  reportFinished(Async::Outcome::Success, Async::StepError());
}

void Misc::Diagnostics::NetworkChecks::TcpProbeTask::onErrorOccurred(
  QAbstractSocket::SocketError error)
{
  Q_UNUSED(error)

  if (!isRunning())
    return;

  auto reason = m_socket.errorString();
  if (reason.isEmpty())
    reason = QStringLiteral("connection failed");

  releaseConnections();
  m_socket.abort();
  reportFinished(Async::Outcome::Failure, errorHere(reason));
}

[[nodiscard]] static bool networkEndpoint(QString& host, quint16& port)
{
  static auto& manager = IO::ConnectionManager::instance();

  auto* network = manager.network();
  if (network == nullptr || network->socketType() != QAbstractSocket::TcpSocket)
    return false;

  host = network->remoteAddress();
  port = network->tcpPort();
  return true;
}

[[nodiscard]] static bool brokerEndpoint(QString& host, quint16& port)
{
#ifdef BUILD_COMMERCIAL
  static auto& manager = IO::ConnectionManager::instance();

  auto* mqtt = manager.mqtt();
  if (mqtt == nullptr)
    return false;

  host = mqtt->hostname();
  port = mqtt->port();
  return true;
#else
  Q_UNUSED(host)
  Q_UNUSED(port)
  return false;
#endif
}

bool Misc::Diagnostics::NetworkChecks::endpoint(Bus bus, QString& host, quint16& port)
{
  if (bus == Bus::Network)
    return networkEndpoint(host, port);

  if (bus == Bus::Broker)
    return brokerEndpoint(host, port);

  return false;
}

void Misc::Diagnostics::NetworkChecks::collectInstant(Bus bus, QList<Result>& out)
{
  QString host;
  quint16 port = 0;
  if (!endpoint(bus, host, port))
    return;

  if (host.isEmpty()) {
    out.append(makeResult(bus,
                          Verdict::Warning,
                          "host-not-configured",
                          trDiag("No host is configured"),
                          trDiag("This source has no host name or address, so there is nothing "
                                 "to connect to."),
                          trDiag("Enter the host name or IP address of the device in the device "
                                 "setup pane.")));
    return;
  }

  if (port == 0)
    out.append(
      makeResult(bus,
                 Verdict::Warning,
                 "port-not-configured",
                 trDiag("No port is configured"),
                 trDiag("Host %1 has no port number, so no connection can be opened.").arg(host),
                 trDiag("Enter the port the device listens on in the device setup "
                        "pane.")));
}

Async::Task* Misc::Diagnostics::NetworkChecks::makeReachabilityFlow(const QString& host,
                                                                    quint16 port,
                                                                    Async::AsyncClock& clock)
{
  SS_ASSERT_LOG(!host.isEmpty());
  SS_ASSERT_LOG(port != 0);

  auto* flow = Async::sequential(QStringLiteral("reachability"));
  flow->addChild(Async::timeout(new HostLookupTask(host), kLookupTimeoutMs, clock));
  flow->addChild(Async::timeout(new TcpProbeTask(host, port), kConnectTimeoutMs, clock));
  return flow;
}

[[nodiscard]] static Result unresolvedResult(Bus bus, const QString& host)
{
  return makeResult(bus,
                    Verdict::Failure,
                    "host-not-resolved",
                    trDiag("The host name did not resolve"),
                    trDiag("The name %1 could not be resolved to an address.").arg(host),
                    trDiag("Check the host name for a typo, or use the device's IP address "
                           "instead."));
}

[[nodiscard]] static Result refusedResult(Bus bus, const QString& host, quint16 port)
{
  return makeResult(bus,
                    Verdict::Failure,
                    "connection-refused",
                    trDiag("The connection was refused"),
                    trDiag("%1 resolved and answered, and refused a connection on that port.")
                      .arg(endpointLabel(host, port)),
                    trDiag("Confirm the port number, and that the service on the device is "
                           "running and accepting connections."));
}

[[nodiscard]] static Result timedOutResult(Bus bus, const QString& host, quint16 port)
{
  return makeResult(
    bus,
    Verdict::Failure,
    "endpoint-timed-out",
    trDiag("The connection timed out"),
    trDiag("%1 did not answer within the time allowed for the check.")
      .arg(endpointLabel(host, port)),
    trDiag("Check that the device is powered and on the same network, and that no firewall is "
           "dropping the connection."));
}

Result Misc::Diagnostics::NetworkChecks::reachabilityResult(
  Bus bus, const QString& host, quint16 port, Async::Outcome outcome, const Async::StepError& error)
{
  if (outcome == Async::Outcome::TimedOut)
    return timedOutResult(bus, host, port);

  if (outcome != Async::Outcome::Failure) {
    Result pass;
    pass.bus = bus;
    return pass;
  }

  if (error.step == QLatin1String(kHostLookupStep))
    return unresolvedResult(bus, host);

  return refusedResult(bus, host, port);
}

[[nodiscard]] static QString driverFamilyRemedy()
{
#if defined(Q_OS_WINDOWS)
  return trDiag("Install the USB-serial driver for the adapter's chip (%1), then unplug and "
                "reconnect the adapter.")
    .arg(QStringLiteral("CH340/CH341, CP210x, FTDI FT232"));
#elif defined(Q_OS_MACOS)
  return trDiag("Install the USB-serial driver for the adapter's chip (%1), allow it in System "
                "Settings > Privacy & Security, then reconnect the adapter.")
    .arg(QStringLiteral("CH340/CH341, CP210x, FTDI FT232"));
#else
  return trDiag("Confirm the adapter is detected with %1 and that its kernel module (%2) is "
                "loaded, then reconnect the adapter.")
    .arg(QStringLiteral("lsusb"), QStringLiteral("ch341, cp210x, ftdi_sio"));
#endif
}

[[nodiscard]] static QString usermodCommand(const QString& group)
{
  const auto account = Misc::Diagnostics::currentAccountName();
  if (account.isEmpty())
    return QStringLiteral("sudo usermod -aG %1 $USER").arg(group);

  return QStringLiteral("sudo usermod -aG %1 %2").arg(group, account);
}

[[nodiscard]] static QString describeGroupRemedy(const QString& group, const GroupBlock& block)
{
  if (group.isEmpty())
    return trDiag("Check the owner and mode of the device node, and add a udev rule that grants "
                  "this account access to it.");

  if (block.accountInGroup && block.sessionHasGroup)
    return trDiag("Group membership is not the cause: this session already belongs to %1. Check "
                  "the owner and mode of the device node, or add a udev rule for it.")
      .arg(group);

  if (block.accountInGroup)
    return trDiag("This account already belongs to %1, but the running session does not. Log out "
                  "and back in for the membership to take effect.")
      .arg(group);

  return trDiag("Run %1, then log out and back in.").arg(usermodCommand(group));
}

[[nodiscard]] static Result describeBlockedGroup(const QString& group, const GroupBlock& block)
{
  const auto names = block.ports.join(QStringLiteral(", "));

  QString explanation = trDiag("This account cannot read and write %1.").arg(names);
  if (!group.isEmpty())
    explanation = trDiag("This account cannot read and write %1, whose device node belongs to "
                         "group %2.")
                    .arg(names, group);

  return makeResult(Bus::Serial,
                    Verdict::Failure,
                    "port-access-denied",
                    trDiag("Serial port access is denied"),
                    explanation,
                    describeGroupRemedy(group, block));
}

static void reportNoPorts(QList<Result>& out)
{
  if (!QSerialPortInfo::availablePorts().isEmpty())
    return;

  out.append(makeResult(Bus::Serial,
                        Verdict::Warning,
                        "no-serial-ports",
                        trDiag("No serial ports were found"),
                        trDiag("The system reports no serial ports, so there is nothing for this "
                               "bus to connect to."),
                        driverFamilyRemedy()));
}

static void reportMissingSelection(QList<Result>& out)
{
  QSettings settings;
  const auto selected = settings.value(QStringLiteral("IO_Serial_SelectedDevice")).toString();
  if (selected.isEmpty())
    return;

  if (selected.startsWith(QLatin1Char('/')) && QFile::exists(selected))
    return;

  const auto port_name = selected.section(QStringLiteral("  "), 0, 0).trimmed();
  const auto ports     = QSerialPortInfo::availablePorts();
  for (const auto& info : ports)
    if (info.portName() == port_name || info.systemLocation() == selected)
      return;

  out.append(makeResult(Bus::Serial,
                        Verdict::Warning,
                        "selected-port-missing",
                        trDiag("The selected serial port is gone"),
                        trDiag("Port %1 was selected previously and the system does not report "
                               "it any more.")
                          .arg(selected),
                        trDiag("Reconnect the adapter, or select another port in the device "
                               "setup pane.")));
}

static void reportInaccessiblePorts(QList<Result>& out)
{
  QMap<QString, GroupBlock> blocked;
  const auto ports = QSerialPortInfo::availablePorts();

  for (int i = 0; i < ports.size() && i < kMaxProbedPorts; ++i) {
    const auto probe = Misc::Diagnostics::probeDeviceNode(ports.at(i).systemLocation());
    if (!probe.accessKnown || !probe.exists || (probe.readable && probe.writable))
      continue;

    auto& block           = blocked[probe.ownerGroup];
    block.accountInGroup  = probe.accountInGroup;
    block.sessionHasGroup = probe.sessionHasGroup;
    block.ports.append(ports.at(i).portName());
  }

  for (auto it = blocked.constBegin(); it != blocked.constEnd(); ++it)
    out.append(describeBlockedGroup(it.key(), it.value()));
}

void Misc::Diagnostics::SerialChecks::collect(QList<Result>& out)
{
  reportNoPorts(out);
  reportMissingSelection(out);
  reportInaccessiblePorts(out);
}

bool Misc::ProblemCenter::Finding::operator==(const Finding& other) const noexcept
{
  return severity == other.severity && entityUniqueId == other.entityUniqueId && code == other.code
      && jump == other.jump && title == other.title && remedy == other.remedy
      && checkerId == other.checkerId && explanation == other.explanation;
}

Misc::ProblemCenter& Misc::ProblemCenter::instance()
{
  static ProblemCenter singleton;
  return singleton;
}

QString Misc::ProblemCenter::lastRunTime() const
{
  if (!m_lastRun.isValid())
    return QString();

  return QLocale::system().toString(m_lastRun.time(), QLocale::ShortFormat);
}

QVariantList Misc::ProblemCenter::checkerCatalog() const
{
  QVariantList list;
  list.reserve(static_cast<qsizetype>(m_checkers.size()));

  for (const auto& entry : m_checkers) {
    QStringList triggers;
    if (entry.triggers & ProjectChanged)
      triggers.append(QStringLiteral("projectChanged"));

    if (entry.triggers & LinkSample)
      triggers.append(QStringLiteral("linkSample"));

    if (entry.triggers & OnDemand)
      triggers.append(QStringLiteral("onDemand"));

    QVariantMap map;
    map.insert(QStringLiteral("id"), entry.id);
    map.insert(QStringLiteral("triggers"), triggers);
    list.append(map);
  }

  return list;
}

int Misc::ProblemCenter::rowCount(const QModelIndex& parent) const
{
  Q_UNUSED(parent)
  return static_cast<int>(m_findings.size());
}

QVariant Misc::ProblemCenter::data(const QModelIndex& index, int role) const
{
  const int row = index.row();
  if (row < 0 || row >= static_cast<int>(m_findings.size()))
    return QVariant();

  const auto& finding = m_findings.at(row);
  switch (role) {
    case SeverityRole:
      return static_cast<int>(finding.severity);
    case CodeRole:
      return finding.code;
    case JumpRole:
      return finding.jump;
    case TitleRole:
      return finding.title;
    case RemedyRole:
      return finding.remedy;
    case EntityIdRole:
      return finding.entityUniqueId;
    case CheckerIdRole:
      return finding.checkerId;
    case ExplanationRole:
      return finding.explanation;
    default:
      return QVariant();
  }
}

QHash<int, QByteArray> Misc::ProblemCenter::roleNames() const
{
  return QHash<int, QByteArray>{
    {   SeverityRole,    "severity"},
    {       CodeRole,        "code"},
    {       JumpRole,        "jump"},
    {      TitleRole,       "title"},
    {     RemedyRole,      "remedy"},
    {   EntityIdRole,    "entityId"},
    {  CheckerIdRole,   "checkerId"},
    {ExplanationRole, "explanation"},
  };
}

void Misc::ProblemCenter::registerChecker(const QString& id, quint8 triggers, Checker checker)
{
  SS_ASSERT(!id.isEmpty(), return);
  SS_ASSERT(triggers != NoTrigger, return);

  if (!checker)
    return;

  m_checkers.push_back(CheckerEntry{id, triggers, std::move(checker)});
  m_checkerFindings.emplace_back();
}

void Misc::ProblemCenter::run(quint8 trigger)
{
  SS_ASSERT(trigger != NoTrigger, return);
  SS_ASSERT(m_checkers.size() == m_checkerFindings.size(), return);

  QList<Finding> scratch;
  for (size_t i = 0; i < m_checkers.size(); ++i) {
    if ((m_checkers[i].triggers & trigger) == 0)
      continue;

    scratch.clear();
    m_checkers[i].checker(scratch);
    if (scratch.size() > kMaxFindingsPerChecker)
      scratch.resize(kMaxFindingsPerChecker);

    for (auto& finding : scratch)
      finding.checkerId = m_checkers[i].id;

    m_checkerFindings[i] = scratch;
  }

  m_lastRun = QDateTime::currentDateTime();
  rebuildFindings();
  Q_EMIT lastRunChanged();
}

void Misc::ProblemCenter::rebuildFindings()
{
  SS_ASSERT(m_checkers.size() == m_checkerFindings.size(), return);

  QList<Finding> flattened;
  for (const auto& slice : m_checkerFindings)
    flattened.append(slice);

  if (flattened == m_findings)
    return;

  beginResetModel();
  m_findings = std::move(flattened);
  endResetModel();

  m_infoCount    = 0;
  m_errorCount   = 0;
  m_warningCount = 0;
  for (const auto& finding : m_findings)
    if (finding.severity == Error)
      ++m_errorCount;
    else if (finding.severity == Warning)
      ++m_warningCount;
    else
      ++m_infoCount;

  notifyNewFindings();
  Q_EMIT findingsChanged();
}

QString Misc::ProblemCenter::findingKey(const Finding& finding)
{
  return QStringLiteral("%1/%2/%3")
    .arg(finding.checkerId, finding.code, QString::number(finding.entityUniqueId));
}

void Misc::ProblemCenter::notifyNewFindings()
{
  QSet<QString> keys;
  keys.reserve(m_findings.size());

  int added = 0;
  int level = Info;
  for (const auto& finding : m_findings) {
    const auto key = findingKey(finding);
    keys.insert(key);
    if (m_previousKeys.contains(key))
      continue;

    ++added;
    level = std::max(level, static_cast<int>(finding.severity));
  }

  m_previousKeys = std::move(keys);
  if (added == 0)
    return;

  SS_ASSERT(m_notifications != nullptr, return);

  m_notifications->post(
    level,
    QStringLiteral("Problems"),
    tr("Problems detected"),
    tr("%1 new problem(s) were detected. Open the problem center to review them.").arg(added));
}

void Misc::ProblemCenter::clear()
{
  SS_ASSERT(m_checkers.size() == m_checkerFindings.size(), return);

  for (auto& slice : m_checkerFindings)
    slice.clear();

  if (m_findings.isEmpty())
    return;

  beginResetModel();
  m_findings.clear();
  endResetModel();

  m_infoCount    = 0;
  m_errorCount   = 0;
  m_warningCount = 0;
  Q_EMIT findingsChanged();
}

bool Misc::ProblemCenter::activate(int row)
{
  if (row < 0 || row >= static_cast<int>(m_findings.size()))
    return false;

  const auto& finding = m_findings.at(row);
  if (finding.jump.isEmpty())
    return false;

  Q_EMIT jumpRequested(finding.jump, finding.entityUniqueId);
  return true;
}

void Misc::ProblemCenter::setupExternalConnections()
{
  Misc::ProjectCheckers::registerAll();
  Misc::LinkCheckers::registerAll();
  Misc::ScriptCheckers::registerAll();
  Misc::ExtensionCheckers::registerAll();

  m_notifications = &DataModel::NotificationCenter::instance();

  auto* project = &DataModel::ProjectModel::instance();
  connect(
    project, &DataModel::ProjectModel::groupsChanged, this, &Misc::ProblemCenter::onProjectChanged);
  connect(project,
          &DataModel::ProjectModel::jsonFileChanged,
          this,
          &Misc::ProblemCenter::onProjectChanged);
  connect(project,
          &DataModel::ProjectModel::frameDetectionChanged,
          this,
          &Misc::ProblemCenter::onProjectChanged);

  connect(&Misc::TimerEvents::instance(),
          &Misc::TimerEvents::timeout1Hz,
          this,
          &Misc::ProblemCenter::onLinkSample);
}

[[nodiscard]] static Finding makeEntityFinding(Severity severity,
                                               const QString& code,
                                               const QString& title,
                                               const QString& explanation,
                                               const QString& remedy,
                                               int entityUniqueId,
                                               const QString& jump)
{
  Finding finding;
  finding.severity       = severity;
  finding.entityUniqueId = entityUniqueId;
  finding.code           = code;
  finding.jump           = jump;
  finding.title          = title;
  finding.remedy         = remedy;
  finding.explanation    = explanation;
  return finding;
}

static void checkEntityReference(const QString& widget,
                                 const QString& entityTitle,
                                 int uniqueId,
                                 const QString& jump,
                                 QList<Finding>& out)
{
  static auto& catalog = UI::WidgetExtensions::instance();

  if (!catalog.contains(widget)) {
    out.append(makeEntityFinding(
      Misc::ProblemCenter::Error,
      QStringLiteral("widget-not-installed"),
      trProblem("Project uses a widget extension that is not installed"),
      trProblem("\"%1\" is set to the widget extension \"%2\", which is not installed, so the "
                "dashboard shows a placeholder instead.")
        .arg(entityTitle, widget),
      trProblem("Install the extension from the extension manager, or choose another widget."),
      uniqueId,
      jump));
    return;
  }

  if (!catalog.consentGranted(widget))
    out.append(makeEntityFinding(
      Misc::ProblemCenter::Warning,
      QStringLiteral("widget-consent-required"),
      trProblem("Widget extension is waiting for your permission"),
      trProblem("\"%1\" uses the widget extension \"%2\". Extensions run with the same privileges "
                "as Serial Studio itself, so it stays inactive until you allow it.")
        .arg(entityTitle, widget),
      trProblem("Open the widget and allow the extension to run, or choose another widget."),
      uniqueId,
      jump));
}

static void checkCatalogFindings(QList<Finding>& out)
{
  static auto& catalog = UI::WidgetExtensions::instance();
  out.append(catalog.findings());
}

static void checkProjectReferences(QList<Finding>& out)
{
  static auto& project = DataModel::ProjectModel::instance();

  const auto& groups = project.groups();
  for (const auto& group : groups) {
    if (!group.widget.isEmpty() && !UI::WidgetExtensions::isReservedId(group.widget))
      checkEntityReference(group.widget, group.title, group.uniqueId, kJumpGroup, out);

    for (const auto& dataset : group.datasets)
      if (!dataset.widget.isEmpty() && !UI::WidgetExtensions::isReservedId(dataset.widget))
        checkEntityReference(dataset.widget, dataset.title, dataset.uniqueId, kJumpDataset, out);
  }
}

static void checkWidgetExtensions(QList<Finding>& out)
{
  checkCatalogFindings(out);
  checkProjectReferences(out);
}

void Misc::ExtensionCheckers::registerAll()
{
  static auto& center   = Misc::ProblemCenter::instance();
  const quint8 triggers = Misc::ProblemCenter::ProjectChanged | Misc::ProblemCenter::OnDemand;

  center.registerChecker(QStringLiteral("extension.widget"), triggers, checkWidgetExtensions);
}

[[nodiscard]] static Finding makeFinding(Severity severity,
                                         const char* code,
                                         const QString& title,
                                         const QString& explanation,
                                         const QString& remedy)
{
  Finding finding;
  finding.severity    = severity;
  finding.code        = QString::fromLatin1(code);
  finding.title       = title;
  finding.remedy      = remedy;
  finding.explanation = explanation;
  return finding;
}

[[nodiscard]] static QString bucketLabel(quint64 value)
{
  if (value >= 1000000)
    return trProblem("more than a million");

  if (value >= 100000)
    return trProblem("more than 100,000");

  if (value >= 10000)
    return trProblem("more than 10,000");

  if (value >= 1000)
    return trProblem("more than 1,000");

  if (value >= 100)
    return trProblem("more than 100");

  if (value >= 10)
    return trProblem("more than 10");

  return trProblem("a few");
}

[[nodiscard]] static QString rateBand(double rate)
{
  if (rate >= 0.5)
    return trProblem("More than half");

  if (rate >= 0.2)
    return trProblem("More than a fifth");

  return trProblem("More than one in twenty");
}

static void resetWindows()
{
  s_noFrameTicks        = 0;
  s_noParseTicks        = 0;
  s_windowBytes         = 0;
  s_windowExtracted     = 0;
  s_totalExtracted      = 0;
  s_totalDroppedFrames  = 0;
  s_totalChecksumErrors = 0;
  s_totalOverflowBytes  = 0;
}

static void resetSampler()
{
  resetWindows();
  s_haveBaseline         = false;
  s_previousStats        = IO::LinkStats{};
  s_previousParsedFrames = 0;
}

[[nodiscard]] static bool linkSuppressed()
{
  if (SerialStudio::isAnyPlayerOpen())
    return true;

  static auto& manager = IO::ConnectionManager::instance();

  return !manager.isConnected();
}

[[nodiscard]] static bool countersWereReset(const IO::LinkStats& stats, quint64 parsed)
{
  return stats.bytesIn < s_previousStats.bytesIn
      || stats.framesExtracted < s_previousStats.framesExtracted
      || stats.checksumErrors < s_previousStats.checksumErrors
      || stats.droppedFrames < s_previousStats.droppedFrames
      || stats.overflowBytes < s_previousStats.overflowBytes || parsed < s_previousParsedFrames;
}

static void accumulate(const IO::LinkStats& stats, quint64 parsed)
{
  const quint64 bytes     = stats.bytesIn - s_previousStats.bytesIn;
  const quint64 extracted = stats.framesExtracted - s_previousStats.framesExtracted;
  const quint64 parsedNow = parsed - s_previousParsedFrames;

  s_totalExtracted      += extracted;
  s_totalDroppedFrames  += stats.droppedFrames - s_previousStats.droppedFrames;
  s_totalChecksumErrors += stats.checksumErrors - s_previousStats.checksumErrors;
  s_totalOverflowBytes  += stats.overflowBytes - s_previousStats.overflowBytes;

  if (bytes > 0 && extracted == 0) {
    ++s_noFrameTicks;
    s_windowBytes += bytes;
  } else {
    s_noFrameTicks = 0;
    s_windowBytes  = 0;
  }

  if (extracted > 0 && parsedNow == 0) {
    ++s_noParseTicks;
    s_windowExtracted += extracted;
  } else {
    s_noParseTicks    = 0;
    s_windowExtracted = 0;
  }
}

static void advanceSampler()
{
  const qint64 now = QDateTime::currentMSecsSinceEpoch();
  if (s_haveBaseline && (now - s_lastSampleMs) < kMinSampleMs)
    return;

  static auto& manager = IO::ConnectionManager::instance();
  static auto& builder = DataModel::FrameBuilder::instance();

  const auto stats  = manager.linkStats();
  const auto parsed = builder.parsedFrameCount();
  if (!s_haveBaseline || countersWereReset(stats, parsed))
    resetWindows();
  else
    accumulate(stats, parsed);

  s_lastSampleMs         = now;
  s_haveBaseline         = true;
  s_previousStats        = stats;
  s_previousParsedFrames = parsed;
}

static void reportNoFrames(QList<Finding>& out)
{
  if (s_noFrameTicks < kSustainTicks)
    return;

  out.append(makeFinding(Misc::ProblemCenter::Error,
                         "bytes-without-frames",
                         trProblem("Data is arriving but no frames are extracted"),
                         trProblem("The link has received %1 bytes over the last few seconds "
                                   "without completing a single frame.")
                           .arg(bucketLabel(s_windowBytes)),
                         trProblem("Check the frame detection mode and the start/end delimiters "
                                   "of the source; they must match what the device sends.")));
}

static void reportNoParsedFrames(QList<Finding>& out)
{
  if (s_noParseTicks < kSustainTicks)
    return;

  out.append(makeFinding(Misc::ProblemCenter::Error,
                         "frames-without-values",
                         trProblem("Frames are arriving but none are parsed"),
                         trProblem("%1 frames were extracted from the link over the last few "
                                   "seconds, and none of them produced dataset values.")
                           .arg(bucketLabel(s_windowExtracted)),
                         trProblem("Open the frame parser and confirm it returns one value per "
                                   "dataset for the frames the device sends.")));
}

static void reportChecksumFailures(QList<Finding>& out)
{
  const quint64 total = s_totalChecksumErrors + s_totalExtracted;
  if (total < kMinChecksumSamples || s_totalChecksumErrors == 0)
    return;

  const double rate = static_cast<double>(s_totalChecksumErrors) / static_cast<double>(total);
  if (rate < kChecksumWarnRate)
    return;

  out.append(makeFinding(Misc::ProblemCenter::Warning,
                         "checksum-failures",
                         trProblem("Frames are failing the checksum"),
                         trProblem("%1 of the frames received on this link failed the configured "
                                   "checksum and were discarded.")
                           .arg(rateBand(rate)),
                         trProblem("Confirm the checksum algorithm of the source matches the "
                                   "device, and check the link for noise or a baud-rate "
                                   "mismatch.")));
}

static void reportDroppedFrames(QList<Finding>& out)
{
  if (s_totalDroppedFrames == 0)
    return;

  out.append(makeFinding(Misc::ProblemCenter::Warning,
                         "dropped-frames",
                         trProblem("Frames are being dropped"),
                         trProblem("The frame queue overflowed and %1 frames were discarded "
                                   "before they could be processed.")
                           .arg(bucketLabel(s_totalDroppedFrames)),
                         trProblem("Lower the data rate, simplify the frame parser, or reduce the "
                                   "number of widgets on the dashboard.")));
}

static void reportBufferOverflow(QList<Finding>& out)
{
  if (s_totalOverflowBytes == 0)
    return;

  out.append(makeFinding(Misc::ProblemCenter::Warning,
                         "buffer-overflow",
                         trProblem("The receive buffer is overflowing"),
                         trProblem("%1 bytes were discarded because the receive buffer filled up "
                                   "before the data could be read.")
                           .arg(bucketLabel(s_totalOverflowBytes)),
                         trProblem("Lower the data rate, or confirm the frames end with the "
                                   "configured delimiter so the buffer is drained.")));
}

static void checkLinkStatistics(QList<Finding>& out)
{
  if (linkSuppressed()) {
    resetSampler();
    return;
  }

  advanceSampler();
  reportNoFrames(out);
  reportNoParsedFrames(out);
  reportChecksumFailures(out);
  reportDroppedFrames(out);
  reportBufferOverflow(out);
}

void Misc::LinkCheckers::registerAll()
{
  static auto& center   = Misc::ProblemCenter::instance();
  const quint8 triggers = Misc::ProblemCenter::LinkSample | Misc::ProblemCenter::OnDemand;

  center.registerChecker(QStringLiteral("link.statistics"), triggers, checkLinkStatistics);
}

[[nodiscard]] static Finding makeFinding(Severity severity,
                                         const char* code,
                                         const QString& title,
                                         const QString& explanation,
                                         const QString& remedy,
                                         int entityUniqueId,
                                         const QString& jump)
{
  Finding finding;
  finding.severity       = severity;
  finding.entityUniqueId = entityUniqueId;
  finding.code           = QString::fromLatin1(code);
  finding.jump           = jump;
  finding.title          = title;
  finding.remedy         = remedy;
  finding.explanation    = explanation;
  return finding;
}

static void capFindings(QList<Finding>& out)
{
  if (out.size() <= kMaxFindings)
    return;

  const int hidden = out.size() - (kMaxFindings - 1);
  out.resize(kMaxFindings - 1);
  out.append(makeFinding(Misc::ProblemCenter::Info,
                         "and-more",
                         trProblem("More problems of this kind"),
                         trProblem("%1 further problems of this kind were found and are not "
                                   "listed individually.")
                           .arg(hidden),
                         trProblem("Fix the listed problems and run the checks again."),
                         -1,
                         QString()));
}

[[nodiscard]] static bool projectAvailable()
{
  static auto& state   = AppState::instance();
  static auto& project = DataModel::ProjectModel::instance();

  if (state.operationMode() != SerialStudio::ProjectFile)
    return false;

  return project.groupCount() > 0;
}

[[nodiscard]] static QString datasetLabel(const DataModel::Dataset& dataset)
{
  if (!dataset.title.isEmpty())
    return dataset.title;

  return trProblem("Dataset %1").arg(dataset.uniqueId);
}

[[nodiscard]] static QString groupLabel(const DataModel::Group& group)
{
  if (!group.title.isEmpty())
    return group.title;

  return trProblem("Group %1").arg(group.uniqueId);
}

[[nodiscard]] static bool datasetReadsFrame(const DataModel::Group& group,
                                            const DataModel::Dataset& dataset)
{
  return group.enabled && dataset.enabled && !dataset.virtual_;
}

static void inspectDatasetIndex(const DataModel::Group& group,
                                const DataModel::Dataset& dataset,
                                QHash<quint64, QString>& seen,
                                QList<Finding>& out)
{
  if (!datasetReadsFrame(group, dataset))
    return;

  if (dataset.index <= 0) {
    out.append(makeFinding(Misc::ProblemCenter::Error,
                           "unreachable-frame-index",
                           trProblem("Dataset reads no frame position"),
                           trProblem("\"%1\" has frame index %2, but frame positions start at 1, "
                                     "so no incoming frame can ever supply a value for it.")
                             .arg(datasetLabel(dataset))
                             .arg(dataset.index),
                           trProblem("Set the dataset's index to the position of its value in the "
                                     "frame, or mark the dataset as virtual."),
                           dataset.uniqueId,
                           kJumpDataset));
    return;
  }

  const auto source = static_cast<quint64>(static_cast<quint32>(group.sourceId));
  const auto index  = static_cast<quint64>(static_cast<quint32>(dataset.index));
  const quint64 key = (source << 32) | index;

  const auto it = seen.constFind(key);
  if (it == seen.constEnd()) {
    seen.insert(key, datasetLabel(dataset));
    return;
  }

  out.append(makeFinding(Misc::ProblemCenter::Warning,
                         "duplicate-frame-index",
                         trProblem("Two datasets share a frame index"),
                         trProblem("\"%1\" and \"%2\" both read frame index %3 of the same source, "
                                   "so they will always show the same value.")
                           .arg(it.value(), datasetLabel(dataset))
                           .arg(dataset.index),
                         trProblem("Give one of them the frame index of its own value, or delete "
                                   "the duplicate if the repetition is intentional."),
                         dataset.uniqueId,
                         kJumpDataset));
}

static void checkFrameIndices(QList<Finding>& out)
{
  if (!projectAvailable())
    return;

  static auto& project = DataModel::ProjectModel::instance();

  QHash<quint64, QString> seen;
  const auto& groups = project.groups();
  for (const auto& group : groups)
    for (const auto& dataset : group.datasets)
      inspectDatasetIndex(group, dataset, seen, out);

  capFindings(out);
}

static void checkEmptyGroups(QList<Finding>& out)
{
  if (!projectAvailable())
    return;

  static auto& project = DataModel::ProjectModel::instance();

  const auto& groups = project.groups();
  for (const auto& group : groups) {
    const bool selfDrawing =
      group.widget == QStringLiteral("painter") || group.widget == QStringLiteral("webview");
    if (selfDrawing || !group.datasets.empty() || !group.outputWidgets.empty())
      continue;

    out.append(makeFinding(Misc::ProblemCenter::Warning,
                           "empty-group",
                           trProblem("Group contains nothing to show"),
                           trProblem("\"%1\" has no datasets and no output widgets, so it renders "
                                     "as an empty panel on the dashboard.")
                             .arg(groupLabel(group)),
                           trProblem("Add a dataset or an output widget to the group, or delete "
                                     "the group."),
                           group.uniqueId,
                           kJumpGroup));
  }

  capFindings(out);
}

static void inspectWorkspaceReferences(const DataModel::Workspace& workspace,
                                       const QSet<int>& groupIds,
                                       QList<Finding>& out)
{
  for (const auto& ref : workspace.widgetRefs) {
    if (ref.groupUniqueId < 0 || groupIds.contains(ref.groupUniqueId))
      continue;

    out.append(makeFinding(Misc::ProblemCenter::Warning,
                           "dangling-workspace-widget",
                           trProblem("Workspace shows a deleted widget"),
                           trProblem("Workspace \"%1\" places a widget from group %2, which is not "
                                     "part of this project any more.")
                             .arg(workspace.title)
                             .arg(ref.groupUniqueId),
                           trProblem("Open the workspace editor and remove the missing tile."),
                           -1,
                           QString()));
  }
}

static void inspectSourceReferences(const QSet<int>& sourceIds, QList<Finding>& out)
{
  if (sourceIds.isEmpty())
    return;

  static auto& project = DataModel::ProjectModel::instance();
  for (const auto& action : project.actions()) {
    if (sourceIds.contains(action.sourceId))
      continue;

    out.append(makeFinding(Misc::ProblemCenter::Error,
                           "dangling-action-source",
                           trProblem("Action targets a missing source"),
                           trProblem("Action \"%1\" transmits to source %2, which is not defined "
                                     "in this project.")
                             .arg(action.title)
                             .arg(action.sourceId),
                           trProblem("Point the action at one of the project's sources."),
                           action.actionId,
                           kJumpAction));
  }

  for (const auto& group : project.groups()) {
    for (const auto& widget : group.outputWidgets) {
      if (sourceIds.contains(widget.sourceId))
        continue;

      out.append(makeFinding(Misc::ProblemCenter::Error,
                             "dangling-output-source",
                             trProblem("Output widget targets a missing source"),
                             trProblem("\"%1\" in group \"%2\" transmits to source %3, which is "
                                       "not defined in this project.")
                               .arg(widget.title, groupLabel(group))
                               .arg(widget.sourceId),
                             trProblem("Point the output widget at one of the project's sources."),
                             group.uniqueId,
                             kJumpGroup));
    }
  }
}

static void checkDanglingReferences(QList<Finding>& out)
{
  if (!projectAvailable())
    return;

  static auto& project = DataModel::ProjectModel::instance();

  QSet<int> groupIds;
  QSet<int> datasetIds;
  for (const auto& group : project.groups()) {
    groupIds.insert(group.uniqueId);
    for (const auto& dataset : group.datasets)
      datasetIds.insert(dataset.uniqueId);
  }

  QSet<int> sourceIds;
  for (const auto& source : project.sources())
    sourceIds.insert(source.sourceId);

  for (const auto& group : project.groups())
    for (const auto& dataset : group.datasets)
      inspectDatasetReferences(dataset, datasetIds, out);

  for (const auto& workspace : project.editorWorkspaces())
    inspectWorkspaceReferences(workspace, groupIds, out);

  inspectSourceReferences(sourceIds, out);
  capFindings(out);
}

[[nodiscard]] static bool rangeIsBroken(double min, double max)
{
  if (min == 0.0 && max == 0.0)
    return false;

  return min >= max;
}

static void checkWidgetRange(const DataModel::Dataset& dataset, QList<Finding>& out)
{
  const auto widget = SerialStudio::datasetWidgetFromId(dataset.widget);
  const bool scaled =
    widget == SerialStudio::Bar || widget == SerialStudio::Gauge || widget == SerialStudio::Meter;
  if (!scaled || !rangeIsBroken(dataset.wgtMin, dataset.wgtMax))
    return;

  out.append(makeFinding(Misc::ProblemCenter::Warning,
                         "inverted-widget-range",
                         trProblem("Widget range is inverted or empty"),
                         trProblem("\"%1\" has a widget minimum of %2 and a maximum of %3, so the "
                                   "indicator has no scale to move along.")
                           .arg(datasetLabel(dataset))
                           .arg(dataset.wgtMin)
                           .arg(dataset.wgtMax),
                         trProblem("Set the widget maximum above the widget minimum."),
                         dataset.uniqueId,
                         kJumpDataset));
}

static void checkLedThreshold(const DataModel::Dataset& dataset, QList<Finding>& out)
{
  if (!dataset.led || dataset.wgtMin >= dataset.wgtMax || !dataset.alarmBands.empty())
    return;

  if (dataset.ledHigh >= dataset.wgtMin && dataset.ledHigh <= dataset.wgtMax)
    return;

  out.append(makeFinding(Misc::ProblemCenter::Warning,
                         "led-threshold-outside-range",
                         trProblem("LED threshold is outside the value range"),
                         trProblem("\"%1\" lights its LED at %2, which lies outside its value "
                                   "range of %3 to %4.")
                           .arg(datasetLabel(dataset))
                           .arg(dataset.ledHigh)
                           .arg(dataset.wgtMin)
                           .arg(dataset.wgtMax),
                         trProblem("Move the LED threshold inside the dataset's value range."),
                         dataset.uniqueId,
                         kJumpDataset));
}

static void checkAlarmBands(const DataModel::Dataset& dataset, QList<Finding>& out)
{
  for (const auto& band : dataset.alarmBands) {
    if (!rangeIsBroken(band.min, band.max))
      continue;

    out.append(makeFinding(Misc::ProblemCenter::Warning,
                           "inverted-alarm-band",
                           trProblem("Alarm band is inverted or empty"),
                           trProblem("An alarm band on \"%1\" runs from %2 to %3, so no value can "
                                     "ever fall inside it.")
                             .arg(datasetLabel(dataset))
                             .arg(band.min)
                             .arg(band.max),
                           trProblem("Set the band's upper bound above its lower bound."),
                           dataset.uniqueId,
                           kJumpDataset));
    return;
  }
}

static void checkNumericRanges(QList<Finding>& out)
{
  if (!projectAvailable())
    return;

  static auto& project = DataModel::ProjectModel::instance();

  const auto& groups = project.groups();
  for (const auto& group : groups) {
    for (const auto& dataset : group.datasets) {
      checkPlotRange(dataset, out);
      checkWidgetRange(dataset, out);
      checkFftRange(dataset, out);
      checkLedThreshold(dataset, out);
      checkAlarmBands(dataset, out);
    }
  }

  capFindings(out);
}

static void checkDuplicateAliases(QList<Finding>& out)
{
  if (!projectAvailable())
    return;

  static auto& project = DataModel::ProjectModel::instance();

  QHash<QString, QString> seen;
  const auto& groups = project.groups();
  for (const auto& group : groups) {
    for (const auto& dataset : group.datasets) {
      if (dataset.alias.isEmpty())
        continue;

      const auto it = seen.constFind(dataset.alias);
      if (it == seen.constEnd()) {
        seen.insert(dataset.alias, datasetLabel(dataset));
        continue;
      }

      out.append(makeFinding(Misc::ProblemCenter::Warning,
                             "duplicate-dataset-alias",
                             trProblem("Two datasets share an alias"),
                             trProblem("\"%1\" and \"%2\" both use the alias \"%3\", so scripts "
                                       "and the API can only reach one of them by name.")
                               .arg(it.value(), datasetLabel(dataset), dataset.alias),
                             trProblem("Give one of the datasets a different alias."),
                             dataset.uniqueId,
                             kJumpDataset));
    }
  }

  capFindings(out);
}

void Misc::ProjectCheckers::registerAll()
{
  static auto& center   = Misc::ProblemCenter::instance();
  const quint8 triggers = Misc::ProblemCenter::ProjectChanged | Misc::ProblemCenter::OnDemand;

  center.registerChecker(QStringLiteral("project.frame-index"), triggers, checkFrameIndices);
  center.registerChecker(QStringLiteral("project.empty-group"), triggers, checkEmptyGroups);
  center.registerChecker(QStringLiteral("project.reference"), triggers, checkDanglingReferences);
  center.registerChecker(QStringLiteral("project.numeric-range"), triggers, checkNumericRanges);
  center.registerChecker(QStringLiteral("project.alias"), triggers, checkDuplicateAliases);
}

[[nodiscard]] static Finding makeFinding(Severity severity,
                                         const char* code,
                                         const QString& title,
                                         const QString& explanation,
                                         const QString& remedy,
                                         int entityUniqueId,
                                         const QString& jump)
{
  Finding finding;
  finding.severity       = severity;
  finding.entityUniqueId = entityUniqueId;
  finding.code           = QString::fromLatin1(code);
  finding.jump           = jump;
  finding.title          = title;
  finding.remedy         = remedy;
  finding.explanation    = explanation;
  return finding;
}

[[nodiscard]] static QString bucketLabel(quint64 value)
{
  if (value >= 1000000)
    return trProblem("more than a million times");

  if (value >= 100000)
    return trProblem("more than 100,000 times");

  if (value >= 10000)
    return trProblem("more than 10,000 times");

  if (value >= 1000)
    return trProblem("more than 1,000 times");

  if (value >= 100)
    return trProblem("more than 100 times");

  if (value >= 10)
    return trProblem("more than 10 times");

  if (value > 1)
    return trProblem("a few times");

  return trProblem("once");
}

[[nodiscard]] static QString sourceLabel(int sourceId)
{
  static auto& project = DataModel::ProjectModel::instance();

  const auto& sources = project.sources();
  for (const auto& source : sources)
    if (source.sourceId == sourceId && !source.title.isEmpty())
      return source.title;

  return trProblem("Source %1").arg(sourceId);
}

[[nodiscard]] static QString datasetLabel(int uniqueId)
{
  static auto& project = DataModel::ProjectModel::instance();

  const auto& groups = project.groups();
  for (const auto& group : groups) {
    for (const auto& dataset : group.datasets)
      if (dataset.uniqueId == uniqueId && !dataset.title.isEmpty())
        return dataset.title;
  }

  return trProblem("Dataset %1").arg(uniqueId);
}

static void checkParserErrors(QList<Finding>& out)
{
  static auto& parser = DataModel::FrameParser::instance();

  const auto stats = parser.scriptStats();
  for (const auto& stat : stats) {
    if (stat.disabled) {
      reportDisabledEngine(stat, out);
      continue;
    }

    if (stat.errorCount > 0)
      reportParserErrors(stat, out);
  }
}

static void checkTransformErrors(QList<Finding>& out)
{
  static auto& builder = DataModel::FrameBuilder::instance();

  const quint64 fails = builder.transformErrorCount();
  if (fails == 0)
    return;

  const int uniqueId = builder.lastTransformDataset();
  out.append(
    makeFinding(Misc::ProblemCenter::Warning,
                "transform-errors",
                trProblem("A value transform is failing"),
                trProblem("The transform of \"%1\" has failed %2, so the dataset shows "
                          "its untransformed value. Last error: %3")
                  .arg(datasetLabel(uniqueId), bucketLabel(fails), builder.lastTransformError()),
                trProblem("Open the dataset's transform and fix the reported error."),
                uniqueId,
                kJumpDataset));
}

void Misc::ScriptCheckers::registerAll()
{
  static auto& center   = Misc::ProblemCenter::instance();
  const quint8 triggers = Misc::ProblemCenter::LinkSample | Misc::ProblemCenter::OnDemand;

  center.registerChecker(QStringLiteral("script.parser"), triggers, checkParserErrors);
  center.registerChecker(QStringLiteral("script.transform"), triggers, checkTransformErrors);
}

static void openProjectFile(const QString& path)
{
  static auto& appState     = AppState::instance();
  static auto& projectModel = DataModel::ProjectModel::instance();
  appState.setOperationMode(SerialStudio::ProjectFile);
  projectModel.openJsonFile(path);
}

bool FileOpenEventFilter::eventFilter(QObject* obj, QEvent* event)
{
  if (event->type() == QEvent::FileOpen) {
    auto* fileEvent    = static_cast<QFileOpenEvent*>(event);
    const QString path = fileEvent->file();
    if (path.endsWith(QStringLiteral(".ssproj"), Qt::CaseInsensitive)) {
      QMetaObject::invokeMethod(qApp, [path] { openProjectFile(path); }, Qt::QueuedConnection);
      return true;
    }
  }

  return QObject::eventFilter(obj, event);
}

SS_COLD SS_NEVER_INLINE void SSAssertDetail::reportSoftAssert(const char* expr,
                                                              const char* file,
                                                              int line,
                                                              const char* func)
{
  qCWarning(lcSoftAssert) << "assertion failed:" << expr << "at" << file << ':' << line << "in"
                          << func;
}

bool SSAssertDetail::softAssertIsFatal()
{
#ifdef QT_NO_DEBUG
  return false;
#else
  static const bool fatal = !qEnvironmentVariableIsSet("SS_ASSERT_NONFATAL");
  return fatal;
#endif
}

static void check(SuiteResult& result, bool ok, const char* what)
{
  SS_ASSERT(what != nullptr, return);
  SS_ASSERT_LOG(result.checks >= 0);

  ++result.checks;
  if (ok)
    return;

  ++result.failures;
  qCritical().noquote() << "[selftest]" << result.name << "FAILED:" << QString::fromLatin1(what);
}

static void runSmokeSuite(SuiteResult& result)
{
  const auto compiled = QVersionNumber::fromString(QStringLiteral(QT_VERSION_STR));
  const auto running  = QVersionNumber::fromString(QString::fromLatin1(qVersion()));
  SS_ASSERT_LOG(!compiled.isNull());

  check(result, !running.isNull(), "runtime Qt version is readable");
  check(result, compiled.majorVersion() == running.majorVersion(), "Qt major version matches");
  check(result, compiled.minorVersion() == running.minorVersion(), "Qt minor version matches");
  check(result, !QCoreApplication::applicationName().isEmpty(), "application metadata is set");
}

QStringList Runner::suiteNames()
{
  SS_ASSERT_LOG(std::size(kSuites) > 0);

  QStringList names;
  names.reserve(static_cast<qsizetype>(std::size(kSuites)));
  for (const auto& entry : kSuites) {
    SS_ASSERT_LOG(entry.name != nullptr);
    if (entry.name == nullptr)
      continue;

    names.append(QString::fromLatin1(entry.name));
  }

  return names;
}

int Runner::runAndReport(const QString& suiteFilter)
{
  SS_ASSERT_LOG(std::size(kSuites) > 0);

  int suitesRun = 0;
  int checks    = 0;
  int failures  = 0;

  for (const auto& entry : kSuites) {
    SS_ASSERT_LOG(entry.run != nullptr);
    if (entry.run == nullptr || entry.name == nullptr)
      continue;

    SuiteResult result{QString::fromLatin1(entry.name), 0, 0};
    if (!suiteFilter.isEmpty() && suiteFilter != result.name)
      continue;

    entry.run(result);
    ++suitesRun;
    checks   += result.checks;
    failures += result.failures;

    qInfo().noquote() << QStringLiteral("[selftest] %1: %2 (%3 checks, %4 failures)")
                           .arg(result.name,
                                result.failures == 0 ? QStringLiteral("PASS")
                                                     : QStringLiteral("FAIL"))
                           .arg(result.checks)
                           .arg(result.failures);
  }

  if (suitesRun == 0) {
    qCritical().noquote() << "[selftest] unknown suite:" << suiteFilter
                          << "| available:" << suiteNames().join(QStringLiteral(", "));
    return EXIT_FAILURE;
  }

  qInfo().noquote() << QStringLiteral("[selftest] %1 suite(s), %2 checks, %3 failures")
                         .arg(suitesRun)
                         .arg(checks)
                         .arg(failures);

  return failures == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

int SerialStudio::extensionGroupWidgetCount(const std::vector<DataModel::Group>& groups)
{
  int count = 0;
  for (const auto& group : groups)
    if (getDashboardWidget(group) == DashboardExtension)
