void UI::Dashboard::addExtensionStringTargets(QSet<const DataModel::Dataset*>& targets) const
{
  static auto& catalog = UI::WidgetExtensions::instance();

  const auto groups = m_widgetGroups.constFind(SerialStudio::DashboardExtension);
  if (groups != m_widgetGroups.cend()) {
    for (int i = 0; i < groups->count(); ++i) {
      if (!catalog.descriptor(extensionIdAt(true, i)).readsStringValues)
        continue;

      for (const auto& dataset : groups->at(i).datasets)
        targets.insert(&dataset);
    }
  }

  const auto datasets = m_widgetDatasets.constFind(SerialStudio::DashboardExtension);
  if (datasets != m_widgetDatasets.cend()) {
    for (int i = 0; i < datasets->count(); ++i)
      if (catalog.descriptor(extensionIdAt(false, i)).readsStringValues)
        targets.insert(&datasets->at(i));
  }
}

[[nodiscard]] static QString builtinWidgetId(SerialStudio::DashboardWidget type)
{
  static const QHash<SerialStudio::DashboardWidget, QString> kIds = {
    {     SerialStudio::DashboardDataGrid,      QStringLiteral("datagrid")},
    {    SerialStudio::DashboardMultiPlot,     QStringLiteral("multiplot")},
    {SerialStudio::DashboardAccelerometer, QStringLiteral("accelerometer")},
    {    SerialStudio::DashboardGyroscope,          QStringLiteral("gyro")},
    {          SerialStudio::DashboardGPS,           QStringLiteral("gps")},
    {      SerialStudio::DashboardWebView,       QStringLiteral("webview")},
    {          SerialStudio::DashboardLED,     QStringLiteral("led-panel")},
    {          SerialStudio::DashboardBar,           QStringLiteral("bar")},
    {        SerialStudio::DashboardGauge,         QStringLiteral("gauge")},
    {      SerialStudio::DashboardCompass,       QStringLiteral("compass")},
    {        SerialStudio::DashboardMeter,         QStringLiteral("meter")},
  };
  return kIds.value(type);
}

QQuickItem* UI::DashboardWidget::createExtensionItem(QQuickItem* parent,
                                                     const QVariantMap& properties)
{
  m_extensionError.clear();
  if (m_extensionId.isEmpty())
    return nullptr;

  auto* engine = qmlEngine(this);
  if (!engine || m_qmlPath.isEmpty()) {
    failExtension(tr("The package is not installed, or has not been allowed to run."));
    return nullptr;
  }

  QQmlComponent component(engine, QUrl(m_qmlPath), QQmlComponent::PreferSynchronous);
  if (component.isError()) {
    failExtension(component.errorString().trimmed());
    return nullptr;
  }

  static auto& catalog = UI::WidgetExtensions::instance();

  auto* context = new QQmlContext(qmlContext(this), this);
  if (!catalog.descriptor(m_extensionId).bundled) {
    const auto names = UI::WidgetExtensions::hostContextNames();
    for (const auto& name : names)
      context->setContextProperty(name, QVariant());
  }

  auto* object = component.createWithInitialProperties(properties, context);
  auto* item   = qobject_cast<QQuickItem*>(object);
  if (!item) {
    delete object;
    failExtension(component.errorString().trimmed());
    return nullptr;
  }

  item->setParentItem(parent);
  QQmlEngine::setObjectOwnership(item, QQmlEngine::JavaScriptOwnership);
  return item;
}

void UI::DashboardWidget::failExtension(const QString& error)
{
  static auto& catalog = UI::WidgetExtensions::instance();

  m_extensionError = error;
  catalog.reportLoadFailure(m_extensionId, error);
  Q_EMIT widgetExtensionErrorChanged();
}

bool UI::DashboardWidget::buildExtensionModel()
{
  static auto& catalog = UI::WidgetExtensions::instance();

  if (widgetType() == SerialStudio::DashboardExtension)
    m_extensionId = m_dashboard.extensionSlot(relativeIndex()).extensionId;

  else
    m_extensionId = catalog.builtinReplacement(builtinWidgetId(widgetType()));

  if (m_extensionId.isEmpty())
    return false;

  m_qmlPath = catalog.qmlUrl(m_extensionId);
  if (m_qmlPath.isEmpty())
    catalog.requestConsent(m_extensionId);

  m_dbWidget = new Widgets::ExtensionData(m_extensionId, widgetType(), relativeIndex(), this);
  return true;
}

[[nodiscard]] static Finding makeFinding(Severity severity,
                                         const char* code,
                                         const QString& title,
                                         const QString& explanation,
                                         const QString& remedy)
{
  Finding finding;
  finding.severity    = severity;
  finding.code        = QString::fromLatin1(code);
  finding.title       = title;
  finding.remedy      = remedy;
  finding.explanation = explanation;
  return finding;
}

[[nodiscard]] static bool clauseSatisfied(const QString& clause, const QVersionNumber& host)
{
  static const QRegularExpression pattern(
    QStringLiteral("^(>=|<=|==|=|>|<)?\\s*([0-9]+(?:\\.[0-9]+)*)$"));

  const auto match = pattern.match(clause.trimmed());
  if (!match.hasMatch())
    return false;

  const auto op    = match.captured(1);
  const auto bound = QVersionNumber::fromString(match.captured(2));
  const int order  = QVersionNumber::compare(host, bound);

  if (op == QStringLiteral(">="))
    return order >= 0;

  if (op == QStringLiteral("<="))
    return order <= 0;

  if (op == QStringLiteral(">"))
    return order > 0;

  if (op == QStringLiteral("<"))
    return order < 0;

  return order == 0;
}

bool UI::widgetVersionInRange(const QString& version, const QString& range)
{
  const auto trimmed = range.trimmed();
  if (trimmed.isEmpty() || trimmed == QStringLiteral("*"))
    return true;

  const auto target = QVersionNumber::fromString(version);
  if (target.isNull())
    return false;

  static const QRegularExpression separator(QStringLiteral("\\s+"));
  const auto clauses = trimmed.split(separator, Qt::SkipEmptyParts);
  for (const auto& clause : clauses)
    if (!clauseSatisfied(clause, target))
      return false;

  return !clauses.isEmpty();
}

static void readPackageFields(const QJsonObject& manifest, Descriptor& out)
{
  out.id          = manifest.value(QStringLiteral("id")).toString().trimmed();
  out.title       = manifest.value(QStringLiteral("title")).toString().trimmed();
  out.author      = manifest.value(QStringLiteral("author")).toString().trimmed();
  out.license     = manifest.value(QStringLiteral("license")).toString().trimmed();
  out.version     = manifest.value(QStringLiteral("version")).toString().trimmed();
  out.category    = manifest.value(QStringLiteral("category")).toString().trimmed();
  out.description = manifest.value(QStringLiteral("description")).toString().trimmed();
}

[[nodiscard]] static UI::WidgetExtensions::Accepts readAccepts(const QJsonObject& block)
{
  UI::WidgetExtensions::Accepts accepts;

  const auto obj      = block.value(QStringLiteral("accepts")).toObject();
  const auto datasets = obj.value(QStringLiteral("datasets")).toObject();

  accepts.minDatasets = qMax(0, datasets.value(QStringLiteral("min")).toInt(1));
  accepts.maxDatasets = datasets.value(QStringLiteral("max")).toInt(-1);
  if (accepts.maxDatasets >= 0 && accepts.maxDatasets < accepts.minDatasets)
    accepts.maxDatasets = accepts.minDatasets;

  const auto value = obj.value(QStringLiteral("value")).toString();
  if (value == QStringLiteral("numeric"))
    accepts.value = UI::WidgetExtensions::NumericValue;
  else if (value == QStringLiteral("string"))
    accepts.value = UI::WidgetExtensions::StringValue;
  else
    accepts.value = UI::WidgetExtensions::AnyValue;

  return accepts;
}

static void readConfigProperty(const QJsonObject& obj, Descriptor& out, QList<Finding>& findings)
{
  static const QStringList kTypes = {
    QStringLiteral("bool"),
    QStringLiteral("int"),
    QStringLiteral("double"),
    QStringLiteral("string"),
    QStringLiteral("choice"),
  };

  UI::WidgetExtensions::ConfigProperty property;
  property.id           = obj.value(QStringLiteral("id")).toString().trimmed();
  property.type         = obj.value(QStringLiteral("type")).toString().trimmed();
  property.label        = obj.value(QStringLiteral("label")).toString();
  property.description  = obj.value(QStringLiteral("description")).toString();
  property.defaultValue = obj.value(QStringLiteral("default")).toVariant();
  property.minimum      = obj.value(QStringLiteral("min")).toVariant();
  property.maximum      = obj.value(QStringLiteral("max")).toVariant();

  const auto options = obj.value(QStringLiteral("options")).toArray();
  for (const auto& option : options)
    property.options.append(option.toString());

  const bool badChoice = property.type == QStringLiteral("choice") && property.options.isEmpty();
  if (property.id.isEmpty() || !kTypes.contains(property.type) || badChoice) {
    findings.append(makeFinding(
      Misc::ProblemCenter::Error,
      "widget-config-invalid",
      trProblem("Widget extension declares an unusable setting"),
      trProblem("Package \"%1\" declares a setting that has no id, an unsupported type, or an "
                "empty choice list, so its settings form cannot be built.")
        .arg(out.id),
      trProblem("Ask the package author to declare each setting with an id and one of the "
                "supported types: bool, int, double, string, choice.")));
    return;
  }

  if (property.label.isEmpty())
    property.label = property.id;

  out.config.append(property);
}

static void readDependencies(const QJsonObject& block, Descriptor& out)
{
  const auto obj = block.value(QStringLiteral("dependencies")).toObject();

  const QList<QPair<QString, bool>> lists = {
    {QStringLiteral("required"),  true},
    {QStringLiteral("optional"), false},
  };

  for (const auto& list : lists) {
    const auto entries = obj.value(list.first).toArray();
    for (const auto& entry : entries) {
      if (out.dependencies.count() >= kMaxDependencies)
        return;

      UI::WidgetExtensions::Dependency dependency;
      dependency.required     = list.second;
      dependency.id           = entry.toObject().value(QStringLiteral("id")).toString().trimmed();
      dependency.versionRange = entry.toObject().value(QStringLiteral("version")).toString();

      if (!dependency.id.isEmpty())
        out.dependencies.append(dependency);
    }
  }
}

[[nodiscard]] static bool validateShape(const QJsonObject& manifest,
                                        const Descriptor& out,
                                        const QString& directory,
                                        QList<Finding>& findings)
{
  const bool isWidget =
    manifest.value(QStringLiteral("type")).toString() == QStringLiteral("widget");
  const bool hasBlock = manifest.value(QStringLiteral("widget")).isObject();

  if (!isWidget || !hasBlock || out.id.isEmpty() || out.title.isEmpty()) {
    findings.append(makeFinding(
      Misc::ProblemCenter::Error,
      "widget-manifest-invalid",
      trProblem("Widget extension manifest is not usable"),
      trProblem("The manifest in \"%1\" is missing its id, title, \"type\": \"widget\", or the "
                "\"widget\" block, so the package cannot be registered.")
        .arg(directory),
      trProblem("Compare the manifest against the widget manifest reference and reinstall the "
                "package.")));
    return false;
  }

  return true;
}

[[nodiscard]] static bool validateIdentity(const QJsonObject& block,
                                           Descriptor& out,
                                           bool bundled,
                                           QList<Finding>& findings)
{
  const auto replaces = block.value(QStringLiteral("replaces")).toString().trimmed();
  if (!replaces.isEmpty() && !bundled) {
    findings.append(makeFinding(
      Misc::ProblemCenter::Error,
      "widget-replaces-forbidden",
      trProblem("Widget extension may not replace a built-in widget"),
      trProblem("Package \"%1\" declares that it replaces the built-in widget \"%2\". Only "
                "packages shipped inside the application may do that.")
        .arg(out.id, replaces),
      trProblem("Remove the \"replaces\" key from the package, or uninstall the package.")));
    return false;
  }

  const bool claimsBuiltin = UI::WidgetExtensions::isReservedId(out.id);
  if (claimsBuiltin && !(bundled && replaces == out.id)) {
    findings.append(makeFinding(
      Misc::ProblemCenter::Error,
      "widget-id-reserved",
      trProblem("Widget extension uses a reserved identifier"),
      trProblem("Package \"%1\" claims an identifier that belongs to a built-in widget, so it was "
                "not registered.")
        .arg(out.id),
      trProblem("Ask the package author to publish it under a unique identifier, such as a "
                "reverse-domain name.")));
    return false;
  }

  out.replaces = bundled ? replaces : QString();
  return true;
}

[[nodiscard]] static bool validateCompatibility(const QJsonObject& block,
                                                const Descriptor& out,
                                                QList<Finding>& findings)
{
  const auto host = QVersionNumber::fromString(UI::WidgetExtensions::hostApiVersion());
  SS_ASSERT(!host.isNull(), return false);

  const auto apiVersion = block.value(QStringLiteral("apiVersion")).toString().trimmed();
  const auto declared   = QVersionNumber::fromString(apiVersion);
  if (!apiVersion.isEmpty()
      && (declared.isNull() || declared.majorVersion() > host.majorVersion())) {
    findings.append(makeFinding(
      Misc::ProblemCenter::Error,
      "widget-api-version",
      trProblem("Widget extension needs a newer manifest format"),
      trProblem("Package \"%1\" declares manifest version %2, which this build (%3) cannot read.")
        .arg(out.id, apiVersion, UI::WidgetExtensions::hostApiVersion()),
      trProblem("Update Serial Studio, or install a build of the package that targets this "
                "version.")));
    return false;
  }

  const auto compat = block.value(QStringLiteral("hostCompat")).toString();
  if (!UI::widgetVersionInRange(UI::WidgetExtensions::hostApiVersion(), compat)) {
    findings.append(makeFinding(
      Misc::ProblemCenter::Error,
      "widget-host-incompatible",
      trProblem("Widget extension is not compatible with this version"),
      trProblem("Package \"%1\" supports widget API %2, but this build provides %3, so it was not "
                "loaded.")
        .arg(out.id, compat, UI::WidgetExtensions::hostApiVersion()),
      trProblem("Check the package for an update, or keep using the Serial Studio version it was "
                "built for.")));
    return false;
  }

  return true;
}

[[nodiscard]] static bool validateEntryPoint(const QJsonObject& block,
                                             Descriptor& out,
                                             const QString& directory,
                                             QList<Finding>& findings)
{
  const auto entry = block.value(QStringLiteral("qml")).toString().trimmed();
  const auto base  = QFileInfo(directory).absoluteFilePath() + QStringLiteral("/");
  const auto path  = QFileInfo(directory + QStringLiteral("/") + entry).absoluteFilePath();

  const bool contained = !entry.isEmpty() && !entry.startsWith(QStringLiteral("/"))
                      && !entry.contains(QStringLiteral("..")) && path.startsWith(base);
  if (!contained || !QFileInfo::exists(directory + QStringLiteral("/") + entry)) {
    findings.append(makeFinding(
      Misc::ProblemCenter::Error,
      "widget-qml-missing",
      trProblem("Widget extension has no usable QML file"),
      trProblem("Package \"%1\" declares \"%2\" as its widget file, but that file is missing from "
                "the package or points outside it.")
        .arg(out.id, entry),
      trProblem("Reinstall the package; if the problem persists, report it to its author.")));
    return false;
  }

  out.qmlFile = entry;
  return true;
}

static void readWidgetBlock(const QJsonObject& block, Descriptor& out)
{
  out.scope = block.value(QStringLiteral("scope")).toString() == QStringLiteral("group")
              ? UI::WidgetExtensions::GroupScope
              : UI::WidgetExtensions::DatasetScope;

  out.iconId            = block.value(QStringLiteral("icon")).toString().trimmed();
  out.experimental      = block.value(QStringLiteral("experimental")).toBool(false);
  out.readsStringValues = block.value(QStringLiteral("readsStringValues")).toBool(false);

  const auto size   = block.value(QStringLiteral("defaultSize")).toObject();
  out.defaultWidth  = qBound(48, size.value(QStringLiteral("width")).toInt(400), 8192);
  out.defaultHeight = qBound(48, size.value(QStringLiteral("height")).toInt(300), 8192);

  out.accepts = readAccepts(block);
}

UI::WidgetManifestResult UI::parseWidgetManifest(const QJsonObject& manifest,
                                                 const QString& directory,
                                                 bool bundled)
{
  SS_ASSERT(!directory.isEmpty(), return UI::WidgetManifestResult());

  UI::WidgetManifestResult result;
  auto& out   = result.descriptor;
  out.bundled = bundled;

  readPackageFields(manifest, out);
  if (!validateShape(manifest, out, directory, result.findings))
    return result;

  out.directory    = directory;
  const auto block = manifest.value(QStringLiteral("widget")).toObject();

  if (!validateIdentity(block, out, bundled, result.findings))
    return result;

  if (!validateCompatibility(block, out, result.findings))
    return result;

  if (!validateEntryPoint(block, out, directory, result.findings))
    return result;

  readWidgetBlock(block, out);
  readDependencies(block, out);

  const auto config = block.value(QStringLiteral("config")).toArray();
  for (const auto& property : config) {
    if (out.config.count() >= kMaxConfigProperties)
      break;

    readConfigProperty(property.toObject(), out, result.findings);
  }

  result.ok = result.findings.isEmpty() && out.isValid();
  return result;
}

[[nodiscard]] static Finding makeFinding(Misc::ProblemCenter::Severity severity,
                                         const QString& code,
                                         const QString& title,
                                         const QString& explanation,
                                         const QString& remedy)
{
  Finding finding;
  finding.severity    = severity;
  finding.code        = code;
  finding.title       = title;
  finding.remedy      = remedy;
  finding.explanation = explanation;
  return finding;
}

UI::WidgetExtensions& UI::WidgetExtensions::instance()
{
  static WidgetExtensions singleton;
  return singleton;
}

QString UI::WidgetExtensions::hostApiVersion()
{
  return QStringLiteral("%1.%2")
    .arg(SerialStudio::kWidgetApiVersionMajor)
    .arg(SerialStudio::kWidgetApiVersionMinor);
}

QStringList UI::WidgetExtensions::idsForScope(Scope scope) const
{
  QStringList list;
  for (const auto& id : m_order) {
    const auto it = m_descriptors.constFind(id);
    if (it != m_descriptors.constEnd() && it->scope == scope)
      list.append(id);
  }

  return list;
}

const UI::WidgetExtensions::Descriptor& UI::WidgetExtensions::descriptor(const QString& id) const
{
  static const Descriptor invalid;

  const auto it = m_descriptors.constFind(id);
  return it != m_descriptors.constEnd() ? it.value() : invalid;
}

bool UI::WidgetExtensions::acceptsEntity(const QString& id,
                                         Scope scope,
                                         int datasetCount,
                                         bool numericValues) const
{
  const auto& package = descriptor(id);
  if (!package.isValid() || package.scope != scope)
    return false;

  if (datasetCount < package.accepts.minDatasets)
    return false;

  if (package.accepts.maxDatasets >= 0 && datasetCount > package.accepts.maxDatasets)
    return false;

  if (package.accepts.value == NumericValue && !numericValues)
    return false;

  return !(package.accepts.value == StringValue && numericValues);
}

bool UI::WidgetExtensions::consentRequired(const QString& id) const
{
  const auto& package = descriptor(id);
  return package.isValid() && !package.bundled;
}

bool UI::WidgetExtensions::consentGranted(const QString& id) const
{
  if (!consentRequired(id))
    return descriptor(id).isValid();

  const auto approved = m_settings.value(kConsentPrefix + id).toString();
  return !approved.isEmpty() && approved == descriptor(id).version;
}

bool UI::WidgetExtensions::consentDeclined(const QString& id) const
{
  if (!consentRequired(id))
    return false;

  const auto refused = m_settings.value(kDeclinePrefix + id).toString();
  return !refused.isEmpty() && refused == descriptor(id).version;
}

void UI::WidgetExtensions::requestConsent(const QString& id)
{
  if (!consentRequired(id) || consentGranted(id) || consentDeclined(id))
    return;

  if (m_prompted.contains(id))
    return;

  m_prompted.insert(id);
  Q_EMIT consentRequested(id);
}

void UI::WidgetExtensions::grantConsent(const QString& id)
{
  if (!consentRequired(id))
    return;

  m_settings.remove(kDeclinePrefix + id);
  m_settings.setValue(kConsentPrefix + id, descriptor(id).version);
  Q_EMIT catalogChanged();
}

void UI::WidgetExtensions::declineConsent(const QString& id)
{
  if (!consentRequired(id))
    return;

  m_settings.remove(kConsentPrefix + id);
  m_settings.setValue(kDeclinePrefix + id, descriptor(id).version);
  Q_EMIT catalogChanged();
}

void UI::WidgetExtensions::reportLoadFailure(const QString& id, const QString& error)
{
  const auto title = descriptor(id).title.isEmpty() ? id : descriptor(id).title;
  const auto finding =
    makeFinding(Misc::ProblemCenter::Error,
                QStringLiteral("widget-load-failed"),
                trProblem("Widget extension failed to load"),
                trProblem("The widget \"%1\" could not be created: %2").arg(title, error),
                trProblem("Update or reinstall the package, then reload the project."));

  if (m_findings.contains(finding))
    return;

  m_findings.append(finding);

  static auto& center = Misc::ProblemCenter::instance();
  center.runNow();
}

void UI::WidgetExtensions::revokeConsent(const QString& id)
{
  m_prompted.remove(id);
  m_settings.remove(kConsentPrefix + id);
  m_settings.remove(kDeclinePrefix + id);
  Q_EMIT catalogChanged();
}

QString UI::WidgetExtensions::qmlUrl(const QString& id) const
{
  if (!canInstantiate(id))
    return {};

  const auto& package = descriptor(id);
  const auto path     = package.directory + QStringLiteral("/") + package.qmlFile;

  if (package.bundled)
    return QStringLiteral("qrc") + path;

  return QUrl::fromLocalFile(path).toString();
}

QVariantList UI::WidgetExtensions::configProperties(const QString& id) const
{
  QVariantList list;
  const auto& package = descriptor(id);

  for (const auto& property : package.config) {
    QVariantMap entry;
    entry[QStringLiteral("id")]          = property.id;
    entry[QStringLiteral("type")]        = property.type;
    entry[QStringLiteral("label")]       = property.label;
    entry[QStringLiteral("description")] = property.description;
    entry[QStringLiteral("default")]     = property.defaultValue;
    entry[QStringLiteral("min")]         = property.minimum;
    entry[QStringLiteral("max")]         = property.maximum;
    entry[QStringLiteral("options")]     = property.options;
    list.append(entry);
  }

  return list;
}

QString UI::WidgetExtensions::iconUrl(const QString& id, const int px) const
{
  const auto& package = descriptor(id);
  if (!package.isValid() || package.iconId.isEmpty())
    return {};

  static auto& icons = Misc::IconRegistry::instance();
  if (!package.iconId.contains(QStringLiteral(".")))
    return icons.iconById(package.iconId, px);

  const auto path = package.directory + QStringLiteral("/") + package.iconId;
  if (package.bundled)
    return QStringLiteral("qrc") + path;

  return QUrl::fromLocalFile(path).toString();
}

QVariantMap UI::WidgetExtensions::packageInfo(const QString& id) const
{
  const auto& package = descriptor(id);

  QVariantMap map;
  map[QStringLiteral("id")]           = package.id;
  map[QStringLiteral("title")]        = package.title;
  map[QStringLiteral("author")]       = package.author;
  map[QStringLiteral("version")]      = package.version;
  map[QStringLiteral("license")]      = package.license;
  map[QStringLiteral("description")]  = package.description;
  map[QStringLiteral("path")]         = package.directory;
  map[QStringLiteral("width")]        = package.defaultWidth;
  map[QStringLiteral("height")]       = package.defaultHeight;
  map[QStringLiteral("bundled")]      = package.bundled;
  map[QStringLiteral("experimental")] = package.experimental;
  map[QStringLiteral("consented")]    = consentGranted(id);
  return map;
}

void UI::WidgetExtensions::rescan()
{
  m_order.clear();
  m_prompted.clear();
  m_findings.clear();
  m_descriptors.clear();
  m_replacements.clear();

  scanDirectory(kBundledRoot, true);

  static auto& workspaceManager = Misc::WorkspaceManager::instance();
  scanDirectory(workspaceManager.path(QStringLiteral("Extensions/widget")), false);

  resolveDependencies();

  Q_EMIT catalogChanged();
}

void UI::WidgetExtensions::scanDirectory(const QString& root, bool bundled)
{
  QDir dir(root);
  if (!dir.exists())
    return;

  const auto packages = dir.entryList(QDir::Dirs | QDir::NoDotAndDotDot, QDir::Name);
  for (const auto& package : packages) {
    if (m_order.count() >= kMaxPackages)
      return;

    loadPackage(root + QStringLiteral("/") + package, bundled);
  }
}

void UI::WidgetExtensions::loadPackage(const QString& directory, bool bundled)
{
  QFile file(directory + QStringLiteral("/info.json"));
  if (!file.exists())
    return;

  if (!file.open(QFile::ReadOnly)) {
    m_findings.append(
      makeFinding(Misc::ProblemCenter::Error,
                  QStringLiteral("widget-manifest-unreadable"),
                  trProblem("Widget extension manifest cannot be read"),
                  trProblem("The manifest in \"%1\" could not be opened.").arg(directory),
                  trProblem("Check the file permissions of the package folder, then reinstall "
                            "the extension.")));
    return;
  }

  Misc::JsonValidator::Limits limits;
  limits.maxFileSize = kMaxManifest;

  const auto parsed = Misc::JsonValidator::parseAndValidate(file.readAll(), limits);
  if (!parsed.valid || !parsed.document.isObject()) {
    m_findings.append(
      makeFinding(Misc::ProblemCenter::Error,
                  QStringLiteral("widget-manifest-invalid"),
                  trProblem("Widget extension manifest is not valid JSON"),
                  trProblem("The manifest in \"%1\" could not be parsed: %2")
                    .arg(directory, parsed.errorMessage),
                  trProblem("Reinstall the package; if the problem persists, report it to its "
                            "author.")));
    return;
  }

  auto result = UI::parseWidgetManifest(parsed.document.object(), directory, bundled);
  m_findings.append(result.findings);
  if (!result.ok)
    return;

  const auto& id = result.descriptor.id;
  if (m_descriptors.contains(id)) {
    m_findings.append(
      makeFinding(Misc::ProblemCenter::Warning,
                  QStringLiteral("widget-package-shadowed"),
                  trProblem("Widget extension is already registered"),
                  trProblem("A package with the identifier \"%1\" is already loaded, so the copy "
                            "in \"%2\" was ignored.")
                    .arg(id, directory),
                  trProblem("Uninstall the duplicate copy from the workspace extensions "
                            "folder.")));
    return;
  }

  if (!result.descriptor.replaces.isEmpty())
    m_replacements.insert(result.descriptor.replaces, id);

  m_order.append(id);
  m_descriptors.insert(id, result.descriptor);
}

void UI::WidgetExtensions::resolveDependencies()
{
  QStringList dropped;

  for (const auto& id : std::as_const(m_order)) {
    const auto& package = m_descriptors.value(id);
    for (const auto& dependency : package.dependencies) {
      const bool present = m_descriptors.contains(dependency.id);
      const bool usable  = present
                       && widgetVersionInRange(m_descriptors.value(dependency.id).version,
                                               dependency.versionRange);
      if (usable)
        continue;

      const auto severity =
        dependency.required ? Misc::ProblemCenter::Error : Misc::ProblemCenter::Info;
      const auto code  = dependency.required ? QStringLiteral("widget-dependency-missing")
                                             : QStringLiteral("widget-dependency-optional");
      const auto title = dependency.required
                         ? trProblem("Widget extension is missing a required extension")
                         : trProblem("Widget extension is missing an optional extension");

      m_findings.append(
        makeFinding(severity,
                    code,
                    title,
                    trProblem("Package \"%1\" depends on \"%2\" %3, which is not installed or is "
                              "a different version.")
                      .arg(id, dependency.id, dependency.versionRange),
                    trProblem("Install \"%1\" from the extension manager.").arg(dependency.id)));

      if (dependency.required)
        dropped.append(id);
    }
  }

  for (const auto& id : std::as_const(dropped)) {
    m_order.removeAll(id);
    const auto replaces = m_descriptors.value(id).replaces;
    if (!replaces.isEmpty())
      m_replacements.remove(replaces);

    m_descriptors.remove(id);
  }
}

[[nodiscard]] static int activeAlarmSeverity(const DataModel::Dataset& dataset)
{
  if (dataset.alarmBands.empty() || !dataset.isNumeric)
    return -1;

  const double low  = std::min(dataset.wgtMin, dataset.wgtMax);
  const double high = std::max(dataset.wgtMin, dataset.wgtMax);
  const double v = low < high ? std::clamp(dataset.numericValue, low, high) : dataset.numericValue;

  for (const auto& band : dataset.alarmBands)
    if (v >= band.min && v <= band.max)
      return static_cast<int>(band.severity);

  return -1;
}

[[nodiscard]] static bool volatileFieldsDiffer(const Widgets::ExtensionRow& a,
                                               const Widgets::ExtensionRow& b)
{
  return a.title != b.title || a.text != b.text || a.value != b.value || a.isNumeric != b.isNumeric
      || a.alarmSeverity != b.alarmSeverity || DSP::notEqual(a.numericValue, b.numericValue);
}

[[nodiscard]] static QString formatDatasetValue(const DataModel::Dataset& dataset)
{
  if (dataset.value.isEmpty())
    return QString();

  if (!dataset.isNumeric)
    return dataset.value;

  QString value = (dataset.decimalPoints < 0)
                  ? FMT_VAL(dataset.numericValue, dataset)
                  : QString::number(dataset.numericValue, 'f', dataset.decimalPoints);
  if (!dataset.units.isEmpty())
    value += QStringLiteral(" ") + dataset.units;

  return value;
}

int Widgets::ExtensionRowsModel::rowCount(const QModelIndex& parent) const
{
  if (parent.isValid())
    return 0;

  return m_rows.size();
}

QVariant Widgets::ExtensionRowsModel::data(const QModelIndex& index, int role) const
{
  if (!index.isValid() || index.row() < 0 || index.row() >= m_rows.size())
    return {};

  const auto& row = m_rows.at(index.row());
  switch (role) {
    case TitleRole:
      return row.title;
    case TextRole:
      return row.text;
    case ValueRole:
      return row.value;
    case UnitsRole:
      return row.units;
    case IndexRole:
      return row.index;
    case MinimumRole:
      return row.minValue;
    case MaximumRole:
      return row.maxValue;
    case UniqueIdRole:
      return row.uniqueId;
    case IsNumericRole:
      return row.isNumeric;
    case NumericValueRole:
      return row.numericValue;
    case DecimalPointsRole:
      return row.decimalPoints;
    case DisplayFormatRole:
      return row.displayFormat;
    case AlarmsDefinedRole:
      return row.alarmsDefined;
    case AlarmSeverityRole:
      return row.alarmSeverity;
    case WidgetsRole:
      return row.widgets;
    default:
      return {};
  }
}

void Widgets::ExtensionRowsModel::reset(const QVector<ExtensionRow>& rows)
{
  beginResetModel();
  m_rows = rows;
  endResetModel();
}

bool Widgets::ExtensionRowsModel::updateRow(int row, const ExtensionRow& fresh)
{
  if (row < 0 || row >= m_rows.size())
    return false;

  auto& entry = m_rows[row];
  if (!volatileFieldsDiffer(entry, fresh))
    return false;

  static const QVector<int> kRoles = {
    TitleRole, TextRole, ValueRole, IsNumericRole, NumericValueRole, AlarmSeverityRole};

  entry.text          = fresh.text;
  entry.title         = fresh.title;
  entry.value         = fresh.value;
  entry.isNumeric     = fresh.isNumeric;
  entry.numericValue  = fresh.numericValue;
  entry.alarmSeverity = fresh.alarmSeverity;

  const auto idx = index(row);
  Q_EMIT dataChanged(idx, idx, kRoles);
  return true;
}

Widgets::ExtensionData::ExtensionData(const QString& extensionId,
                                      const SerialStudio::DashboardWidget type,
                                      const int index,
                                      QQuickItem* parent)
  : QQuickItem(parent)
  , m_paused(false)
  , m_groupScope(false)
  , m_index(index)
  , m_bucketIndex(index)
  , m_lastRowCount(-1)
  , m_type(type)
  , m_extensionId(extensionId)
  , m_rowsModel(new ExtensionRowsModel(this))
  , m_dashboard(UI::Dashboard::instance())
{
  const auto slot = m_dashboard.widgetSlot(m_type, m_index);
  m_groupScope    = slot.group;
  m_bucketIndex   = slot.bucketIndex;
  if (m_extensionId.isEmpty())
    m_extensionId = slot.extensionId;

  if (!valid())
    return;

  reloadConfig();
  rebuildRows();

  static auto& projectModel = DataModel::ProjectModel::instance();
  connect(&m_dashboard, &UI::Dashboard::updated, this, &Widgets::ExtensionData::updateData);
  connect(&projectModel,
          &DataModel::ProjectModel::widgetSettingsChanged,
          this,
          &Widgets::ExtensionData::reloadConfig);
}

int Widgets::ExtensionData::groupId() const
{
  if (!valid())
    return -1;

  if (m_groupScope)
    return GET_GROUP(m_type, m_bucketIndex).groupId;

  return GET_DATASET(m_type, m_bucketIndex).groupId;
}

int Widgets::ExtensionData::sourceId() const
{
  if (!valid())
    return 0;

  if (m_groupScope)
    return GET_GROUP(m_type, m_bucketIndex).sourceId;

  return GET_DATASET(m_type, m_bucketIndex).sourceId;
}

int Widgets::ExtensionData::uniqueId() const
{
  if (!valid())
    return -1;

  if (m_groupScope)
    return GET_GROUP(m_type, m_bucketIndex).uniqueId;

  return GET_DATASET(m_type, m_bucketIndex).uniqueId;
}

void Widgets::ExtensionData::setPaused(const bool paused)
{
  if (m_paused == paused)
    return;

  m_paused = paused;

  if (!m_paused)
    updateData();

  Q_EMIT pausedChanged();
}

void Widgets::ExtensionData::setConfigValue(const QString& key, const QVariant& value)
{
  if (key.isEmpty() || !valid())
    return;

  static auto& projectModel = DataModel::ProjectModel::instance();
  projectModel.saveWidgetSetting(widgetId(), key, value);
  reloadConfig();
}

void Widgets::ExtensionData::updateData()
{
  if (m_paused || !valid())
    return;

  const auto rows = collectRows();
  if (rows.count() != m_lastRowCount) [[unlikely]] {
    rebuildRows();
    return;
  }

  bool changed = false;
  for (int i = 0; i < rows.count(); ++i)
    changed |= m_rowsModel->updateRow(i, rows.at(i));

  const auto title = currentTitle();
  if (m_title != title) {
    m_title = title;
    changed = true;
  }

  changed |= refreshLead(rows.isEmpty() ? ExtensionRow() : rows.first());

  if (changed)
    Q_EMIT updated();
}

void Widgets::ExtensionData::reloadConfig()
{
  static auto& catalog      = UI::WidgetExtensions::instance();
  static auto& projectModel = DataModel::ProjectModel::instance();

  QVariantMap merged;
  const auto& descriptor = catalog.descriptor(m_extensionId);
  for (const auto& property : descriptor.config)
    merged.insert(property.id, property.defaultValue);

  const auto stored = projectModel.widgetSettings(widgetId());
  for (auto it = stored.constBegin(); it != stored.constEnd(); ++it)
    merged.insert(it.key(), it.value().toVariant());

  if (merged == m_config)
    return;

  m_config = merged;
  Q_EMIT configChanged();
}

QString Widgets::ExtensionData::widgetId() const
{
  static auto& registry = UI::WidgetRegistry::instance();

  const auto id   = registry.widgetIdByTypeAndIndex(m_type, m_index);
  const auto info = registry.widgetInfo(id);
  return QStringLiteral("%1:%2:%3")
    .arg(static_cast<int>(m_type))
    .arg(info.groupId)
    .arg(info.datasetIndex);
}

QString Widgets::ExtensionData::currentTitle() const
{
  if (!valid())
    return {};

  if (m_groupScope)
    return GET_GROUP(m_type, m_bucketIndex).title;

  return GET_DATASET(m_type, m_bucketIndex).title;
}

QVector<Widgets::ExtensionRow> Widgets::ExtensionData::collectRows() const
{
  QVector<ExtensionRow> rows;
  if (!valid())
    return rows;

  if (!m_groupScope) {
    rows.append(buildRow(GET_DATASET(m_type, m_bucketIndex)));
    return rows;
  }

  const auto& group = GET_GROUP(m_type, m_bucketIndex);
  rows.reserve(static_cast<int>(group.datasets.size()));
  for (const auto& dataset : group.datasets)
    rows.append(buildRow(dataset));

  return rows;
}

Widgets::ExtensionRow Widgets::ExtensionData::buildRow(const DataModel::Dataset& dataset) const
{
  ExtensionRow row;
  row.index         = dataset.index;
  row.title         = dataset.title;
  row.units         = dataset.units;
  row.value         = dataset.value;
  row.uniqueId      = dataset.uniqueId;
  row.minValue      = dataset.wgtMin;
  row.maxValue      = dataset.wgtMax;
  row.isNumeric     = dataset.isNumeric;
  row.numericValue  = dataset.numericValue;
  row.decimalPoints = dataset.decimalPoints;
  row.displayFormat = dataset.displayFormat;
  row.alarmsDefined = !dataset.alarmBands.empty();
  row.alarmSeverity = activeAlarmSeverity(dataset);
  row.text          = formatDatasetValue(dataset);
  row.widgets       = datasetWidgets(dataset);
  return row;
}

QVariantList Widgets::ExtensionData::datasetWidgets(const DataModel::Dataset& dataset) const
{
  QVariantList widgets;
  QVariantList plots;

  const auto& map = m_dashboard.widgetMap();
  for (auto it = map.constBegin(); it != map.constEnd(); ++it) {
    const auto type = it.value().first;
    if (!SerialStudio::isDatasetWidget(type))
      continue;

    const auto& shown = GET_DATASET(type, it.value().second);
    if (shown.sourceId != dataset.sourceId || shown.groupId != dataset.groupId
        || shown.datasetId != dataset.datasetId)
      continue;

    QVariantMap entry;
    entry.insert(QStringLiteral("windowId"), it.key());
    entry.insert(QStringLiteral("icon"), SerialStudio::dashboardWidgetIcon(type));
    entry.insert(QStringLiteral("title"), SerialStudio::dashboardWidgetTitle(type));

    if (type == SerialStudio::DashboardPlot)
      plots.append(entry);

    else
      widgets.append(entry);
  }

  widgets += plots;
  return widgets;
}

bool Widgets::ExtensionData::refreshLead(const ExtensionRow& row)
{
  if (!volatileFieldsDiffer(m_lead, row) && m_lead.uniqueId == row.uniqueId)
    return false;

  m_lead = row;
  return true;
}

void Widgets::ExtensionData::rebuildRows()
{
  const auto rows = collectRows();

  m_rowsModel->reset(rows);
  m_lastRowCount = rows.count();
  m_title        = currentTitle();
  m_lead         = rows.isEmpty() ? ExtensionRow() : rows.first();

  Q_EMIT updated();
}

