  zero.insert(Keys::Frequency, 0);
  QVERIFY(!fromJson<FrequencyMarker>(zero).has_value());

  QJsonObject negative;
  negative.insert(Keys::Frequency, -5);
  QVERIFY(!fromJson<FrequencyMarker>(negative).has_value());
