static void applyTreeExpansion(QStandardItem* item, int depth, int maxExpandDepth)
{
  Q_ASSERT(item != nullptr);
  if (depth > 64)
    return;

  if (item->hasChildren())
    item->setData(depth < maxExpandDepth, ProjectEditor::TreeViewExpanded);

  const int rows = item->rowCount();
  for (int r = 0; r < rows; ++r)
    applyTreeExpansion(item->child(r), depth + 1, maxExpandDepth);
}

void DataModel::ProjectEditor::expandAllTreeItems()
{
  if (!m_treeModel)
    return;

  auto* root = m_treeModel->invisibleRootItem();
  Q_ASSERT(root != nullptr);
  for (int r = 0; r < root->rowCount(); ++r)
    applyTreeExpansion(root->child(r), 0, std::numeric_limits<int>::max());

  persistTreeExpansion();
}

void DataModel::ProjectEditor::collapseTreeToOverview()
{
  if (!m_treeModel)
    return;

  auto* root = m_treeModel->invisibleRootItem();
  Q_ASSERT(root != nullptr);
  for (int r = 0; r < root->rowCount(); ++r)
    applyTreeExpansion(root->child(r), 0, 2);

  persistTreeExpansion();
}

static QString formIcon(const char* id)
{
  static auto& registry = Misc::IconRegistry::instance();
  return registry.iconById(QLatin1String(id), 16);
}

sc::IconRegistry::IconRegistry()
{
  QDirIterator it(QStringLiteral(":/icons"), QDirIterator::Subdirectories);
  while (it.hasNext()) {
    const auto path  = it.next();
    const auto parts = path.mid(8).split(QChar('/'), Qt::SkipEmptyParts);
    if (parts.size() != 3 || !parts[2].endsWith(QStringLiteral(".svg")))
      continue;

    bool numeric  = false;
    const int px  = parts[1].toInt(&numeric);
    const auto id = parts[2].chopped(4);
    if (!numeric || px <= 0 || id.isEmpty())
      continue;

    auto& tiers = m_catalog[parts[0]][id];
    tiers.append(px);
    std::sort(tiers.begin(), tiers.end());
  }

  Q_ASSERT(!m_catalog.isEmpty());
  Q_ASSERT(m_catalog.contains(QStringLiteral("system")));
}

sc::IconRegistry& Misc::IconRegistry::instance()
{
  static IconRegistry s;
  return s;
}

tring Misc::IconRegistry::iconById(const QString& id, int px) const
{
  const auto slash = id.indexOf(QChar('/'));
  if (slash <= 0 || slash == id.length() - 1)
    return QStringLiteral("qrc:") + missingIcon(QStringLiteral("(malformed)"), id);

  return icon(id.left(slash), id.mid(slash + 1), px);
}

tring Misc::IconRegistry::resolve(const QString& category, const QString& name, int px) const
{
  Q_ASSERT(!category.isEmpty());
  Q_ASSERT(!name.isEmpty());

  const auto cat = m_catalog.constFind(category);
  if (cat == m_catalog.constEnd())
    return missingIcon(category, name);

  const auto entry = cat->constFind(name);
  if (entry == cat->constEnd())
    return missingIcon(category, name);

  const auto url = QStringLiteral("/icons/%1/%2/%3.svg");
  for (const int tier : *entry)
    if (tier >= px)
      return url.arg(category, QString::number(tier), name);

  return url.arg(category, QString::number(entry->constLast()), name);
}

tring Misc::IconRegistry::missingIcon(const QString& category, const QString& name) const
{
  const auto key = QStringLiteral("%1/%2").arg(category, name);
  if (!m_warned.contains(key)) {
    m_warned.insert(key);
    qWarning() << "IconRegistry: unknown icon" << key << "- serving placeholder";
  }

  return QStringLiteral("/icons/system/16/missing.svg");
}

::CommandRegistry::CommandRegistry() : m_translator(Misc::Translator::instance())
{
  loadManifest(QStringLiteral(":/commands/app.json"));
  loadManifest(QStringLiteral(":/commands/dashboard.json"));
  loadManifest(QStringLiteral(":/commands/projecteditor.json"));
  loadManifest(QStringLiteral(":/commands/database.json"));
  loadLayout(QStringLiteral(":/commands/layouts/main-toolbar.json"));
  loadLayout(QStringLiteral(":/commands/layouts/project-toolbar.json"));
  loadLayout(QStringLiteral(":/commands/layouts/start-menu.json"));
  loadLayout(QStringLiteral(":/commands/layouts/database-toolbar.json"));

  QHash<QString, QString> claimed;
  for (const auto& command : m_commands) {
    const auto shortcut = command.value(QStringLiteral("shortcut")).toString();
    if (shortcut.isEmpty())
      continue;

    const auto windows = command.value(QStringLiteral("shortcutWindows")).toArray();
    for (const auto& window : windows) {
      const auto key = window.toString() + QChar('|') + shortcut;
      if (claimed.contains(key)) {
        qWarning() << "CommandRegistry: duplicate shortcut" << shortcut << "in window"
                   << window.toString() << "claimed by" << claimed.value(key) << "and"
                   << command.value(QStringLiteral("id")).toString();
      }

      claimed.insert(key, command.value(QStringLiteral("id")).toString());
    }
  }

  connect(
    &m_translator, &Misc::Translator::languageChanged, this, &CommandRegistry::commandsChanged);
}

::CommandRegistry& UI::CommandRegistry::instance()
{
  static CommandRegistry s;
  return s;
}

id UI::CommandRegistry::loadManifest(const QString& path)
{
  QFile file(path);
  if (!file.open(QFile::ReadOnly)) {
    qWarning() << "CommandRegistry: cannot open" << path;
    return;
  }

  QJsonParseError error{};
  const auto document = QJsonDocument::fromJson(file.readAll(), &error);
  if (error.error != QJsonParseError::NoError || !document.isObject()) {
    qWarning() << "CommandRegistry: invalid manifest" << path << error.errorString();
    return;
  }

  const auto commands = document.object().value(QStringLiteral("commands")).toArray();
  for (const auto& entry : commands) {
    auto command  = entry.toObject();
    const auto id = command.value(QStringLiteral("id")).toString();
    if (id.isEmpty() || m_commandIndex.contains(id)) {
      qWarning() << "CommandRegistry: missing or duplicate id in" << path << id;
      continue;
    }

#ifndef BUILD_COMMERCIAL
    if (command.value(QStringLiteral("pro")).toBool())
      continue;
#endif

    m_commandIndex.insert(id, m_commands.size());
    m_commands.append(command);
  }
}

id UI::CommandRegistry::loadLayout(const QString& path)
{
  QFile file(path);
  if (!file.open(QFile::ReadOnly)) {
    qWarning() << "CommandRegistry: cannot open" << path;
    return;
  }

  QJsonParseError error{};
  const auto document = QJsonDocument::fromJson(file.readAll(), &error);
  if (error.error != QJsonParseError::NoError || !document.isObject()) {
    qWarning() << "CommandRegistry: invalid layout" << path << error.errorString();
    return;
  }

  auto layout        = document.object();
  const auto surface = layout.value(QStringLiteral("surface")).toString();
  if (surface.isEmpty()) {
    qWarning() << "CommandRegistry: layout without surface name" << path;
    return;
  }

  for (const auto key : {"sections", "items", "pinnedEnd"})
    if (layout.contains(QLatin1String(key)))
      layout.insert(QLatin1String(key),
                    filterLayoutNodes(layout.value(QLatin1String(key)).toArray()));

  m_layouts.insert(surface, layout);
}

sonArray UI::CommandRegistry::filterLayoutNodes(const QJsonArray& nodes) const
{
  QJsonArray result;
  for (const auto& entry : nodes) {
    auto node = entry.toObject();
#ifdef BUILD_COMMERCIAL
    if (node.value(QStringLiteral("gplOnly")).toBool())
      continue;
#else
    if (node.value(QStringLiteral("pro")).toBool())
      continue;
#endif

    if (node.contains(QStringLiteral("items")))
      node.insert(QStringLiteral("items"),
                  filterLayoutNodes(node.value(QStringLiteral("items")).toArray()));

    result.append(node);
  }

  return result;
}

ariantList UI::CommandRegistry::commands(const QString& context) const
{
  Q_ASSERT(!context.isEmpty());

  QList<QPair<int, int>> selected;
  for (int i = 0; i < m_commands.size(); ++i) {
    const auto& command = m_commands.at(i);
    const auto contexts = command.value(QStringLiteral("contexts")).toArray();
    for (const auto& entry : contexts) {
      if (entry.toString() == context) {
        const auto order = command.value(QStringLiteral("order")).toInt(1000);
        selected.append({order, i});
        break;
      }
    }
  }

  std::stable_sort(selected.begin(), selected.end());

  QVariantList result;
  result.reserve(selected.size());
  for (const auto& [order, index] : selected)
    result.append(toVariant(m_commands.at(index)));

  return result;
}

ariantMap UI::CommandRegistry::command(const QString& id) const
{
  Q_ASSERT(!id.isEmpty());

  const auto index = m_commandIndex.value(id, -1);
  if (index < 0) {
    qWarning() << "CommandRegistry: unknown command" << id;
    return {};
  }

  return toVariant(m_commands.at(index));
}

ariantMap UI::CommandRegistry::layout(const QString& surface) const
{
  Q_ASSERT(!surface.isEmpty());

  const auto stored = m_layouts.value(surface);
  if (stored.isEmpty()) {
    qWarning() << "CommandRegistry: unknown surface" << surface;
    return {};
  }

  QVariantMap result;
  result.insert(QStringLiteral("surface"), surface);
  for (const auto key : {"sections", "items", "pinnedEnd"})
    if (stored.contains(QLatin1String(key)))
      result.insert(QLatin1String(key), layoutNodes(stored.value(QLatin1String(key)).toArray()));

  return result;
}

ariantList UI::CommandRegistry::shortcutCommands(const QString& window) const
{
  Q_ASSERT(!window.isEmpty());

  QVariantList result;
  for (const auto& command : m_commands) {
    const auto shortcut = command.value(QStringLiteral("shortcut")).toString();
    if (shortcut.isEmpty())
      continue;

    bool applies       = false;
    const auto windows = command.value(QStringLiteral("shortcutWindows")).toArray();
    for (const auto& entry : windows)
      applies = applies || (entry.toString() == window);

    if (!applies)
      continue;

    result.append(toVariant(command));
  }

  return result;
}

ariantMap UI::CommandRegistry::toVariant(const QJsonObject& command) const
{
  QVariantMap map;
  map.insert(QStringLiteral("id"), command.value(QStringLiteral("id")).toString());
  map.insert(QStringLiteral("kind"),
             command.value(QStringLiteral("kind")).toString(QStringLiteral("action")));
  map.insert(QStringLiteral("title"), translated(command, "title"));
  map.insert(QStringLiteral("tooltip"), translated(command, "tooltip"));
  map.insert(QStringLiteral("titleChecked"), translated(command, "titleChecked"));
  map.insert(QStringLiteral("icon"), command.value(QStringLiteral("icon")).toString());
  map.insert(QStringLiteral("iconChecked"),
             command.value(QStringLiteral("iconChecked")).toString());
  map.insert(QStringLiteral("category"), command.value(QStringLiteral("category")).toString());

  const auto shortcut  = command.value(QStringLiteral("shortcut")).toString();
  const auto sequences = sequencesFor(shortcut);
  map.insert(QStringLiteral("sequences"), sequences);
  map.insert(QStringLiteral("shortcutContext"),
             command.value(QStringLiteral("shortcutContext")).toString());
  if (!sequences.isEmpty())
    map.insert(QStringLiteral("shortcutText"),
               QKeySequence(sequences.first()).toString(QKeySequence::NativeText));
  else
    map.insert(QStringLiteral("shortcutText"), QString());

  return map;
}

ariantList UI::CommandRegistry::layoutNodes(const QJsonArray& nodes) const
{
  QVariantList result;
  for (const auto& entry : nodes) {
    const auto node = entry.toObject();
    const auto type = node.value(QStringLiteral("type")).toString();
    auto map        = (type == QStringLiteral("command")) ? commandNode(node) : containerNode(node);
    if (map.isEmpty())
      continue;

    map.insert(QStringLiteral("type"), type);
    result.append(map);
  }

  return result;
}

ariantMap UI::CommandRegistry::commandNode(const QJsonObject& node) const
{
  const auto index = m_commandIndex.value(node.value(QStringLiteral("id")).toString(), -1);
  if (index < 0)
    return {};

  auto map = toVariant(m_commands.at(index));
  if (node.contains(QStringLiteral("title")))
    map.insert(QStringLiteral("title"), translated(node, "title"));

  if (node.contains(QStringLiteral("tooltip")))
    map.insert(QStringLiteral("tooltip"), translated(node, "tooltip"));

  if (node.contains(QStringLiteral("icon")))
    map.insert(QStringLiteral("icon"), node.value(QStringLiteral("icon")).toString());

  if (node.contains(QStringLiteral("hints")))
    map.insert(QStringLiteral("hints"),
               node.value(QStringLiteral("hints")).toObject().toVariantMap());

  map.insert(QStringLiteral("role"), node.value(QStringLiteral("role")).toString());
  return map;
}

ariantMap UI::CommandRegistry::containerNode(const QJsonObject& node) const
{
  auto map = node.toVariantMap();
  if (node.contains(QStringLiteral("title")))
    map.insert(QStringLiteral("title"), translated(node, "title"));

  if (node.contains(QStringLiteral("items")))
    map.insert(QStringLiteral("items"), layoutNodes(node.value(QStringLiteral("items")).toArray()));

  const auto collapsed = node.value(QStringLiteral("collapsedCommands")).toArray();
  for (const auto& candidate : collapsed) {
    const auto index = m_commandIndex.value(candidate.toString(), -1);
    if (index < 0)
      continue;

    const auto resolved = toVariant(m_commands.at(index));
    map.insert(QStringLiteral("collapsedTitle"), resolved.value(QStringLiteral("title")));
    map.insert(QStringLiteral("collapsedIcon"), resolved.value(QStringLiteral("icon")));
    break;
  }

  return map;
}

tringList UI::CommandRegistry::sequencesFor(const QString& shortcut)
{
  if (shortcut.isEmpty())
    return {};

  const auto prefix = QStringLiteral("StandardKey.");
  if (!shortcut.startsWith(prefix))
    return {shortcut};

  const auto name = shortcut.mid(prefix.length());
  if (!kStandardKeys.contains(name)) {
    qWarning() << "CommandRegistry: unknown standard key" << shortcut;
    return {};
  }

  QStringList result;
  const auto bindings = QKeySequence::keyBindings(kStandardKeys.value(name));
  for (const auto& binding : bindings)
    result.append(binding.toString(QKeySequence::PortableText));

  return result;
}

tring UI::CommandRegistry::translated(const QJsonObject& object, const char* key)
{
  const auto value = object.value(QLatin1String(key)).toString();
  if (value.isEmpty())
    return {};

  return QCoreApplication::translate("Commands", value.toUtf8().constData());
}

int UI::Taskbar::resolveWorkspaceRefWindowId(const DataModel::WidgetRef& ref) const
{
  const int windowId = findWindowIdByGroupAndIndex(ref.widgetType, ref.relativeIndex);
  if (windowId < 0)
    return -1;

  const int refGid = m_dashboard.groupIdForUniqueId(ref.groupUniqueId);
  auto* item       = findItemByWindowId(windowId);
  if (!item || item->data(TaskbarModel::GroupIdRole).toInt() != refGid)
    return -1;

  return windowId;
}

int UI::Taskbar::workspaceContainingWidget(int windowId) const
{
  const auto& workspaces = m_projectModel.activeWorkspaces();

  int firstMatch = -1;
  for (const auto& ws : workspaces) {
    if (ws.workspaceId < WorkspaceIds::AutoStart)
      continue;

    bool contains = false;
    for (const auto& ref : ws.widgetRefs)
      if (resolveWorkspaceRefWindowId(ref) == windowId) {
        contains = true;
        break;
      }

    if (!contains)
      continue;

    if (ws.workspaceId == m_activeGroupId)
      return ws.workspaceId;

    if (firstMatch < 0)
      firstMatch = ws.workspaceId;
  }

  return firstMatch;
}

static QStandardItem* navFind(const Map& map, Pred&& pred)
{
  for (auto it = map.begin(); it != map.end(); ++it)
    if (pred(it.value()))
      return it.key();

  return nullptr;
}

auto DataModel::ProjectEditor::captureNavEntry(QStandardItem* item) const -> NavEntry
{
  Q_ASSERT(item != nullptr);

  NavEntry entry;
  if (!item)
    return entry;

  const int kindRole = item->data(TreeItemKind).toInt();
  if (kindRole != KindNone) {
    entry.valid    = true;
    entry.kind     = static_cast<ItemKind>(kindRole);
    entry.id       = item->data(TreeItemId).toInt();
    entry.parentId = item->data(TreeItemParentId).toInt();
    if (entry.kind == KindUserTable)
      entry.key = m_userTableItems.value(item);

    return entry;
  }

  entry.container = true;
  entry.valid     = true;
  if (m_rootItems.contains(item)) {
    entry.view = ProjectView;
    return entry;
  }
  if (item == m_groupsRootItem) {
    entry.view = GroupsView;
    return entry;
  }
  if (item == m_tablesRootItem) {
    entry.view = DataTablesView;
    return entry;
  }
  if (item == m_systemDatasetsItem) {
    entry.view = SystemDatasetsView;
    return entry;
  }
  if (item == m_workspacesRootItem) {
    entry.view = WorkspacesView;
    return entry;
  }

  entry.valid = false;
  return entry;
}

QStandardItem* DataModel::ProjectEditor::resolveNavEntry(const NavEntry& entry) const
{
  if (!entry.valid)
    return nullptr;

  if (entry.container) {
    switch (entry.view) {
      case ProjectView:        return m_rootItems.isEmpty() ? nullptr : m_rootItems.firstKey();
      case GroupsView:         return m_groupsRootItem;
      case DataTablesView:     return m_tablesRootItem;
      case SystemDatasetsView: return m_systemDatasetsItem;
      case WorkspacesView:     return m_workspacesRootItem;
      default:                 return nullptr;
    }
  }

  const int id  = entry.id;
  const int pid = entry.parentId;
  switch (entry.kind) {
    case KindGroup:
      return navFind(m_groupItems, [id](const auto& v) { return v.groupId == id; });
    case KindDataset:
      return navFind(m_datasetItems,
                     [id, pid](const auto& v) { return v.groupId == pid && v.datasetId == id; });
    case KindAction:
      return navFind(m_actionItems, [id](const auto& v) { return v.actionId == id; });
    case KindOutputWidget:
      return navFind(m_outputWidgetItems,
                     [id, pid](const auto& v) { return v.groupId == pid && v.widgetId == id; });
    case KindSource:
      return navFind(m_sourceItems, [id](const auto& v) { return v.sourceId == id; });
    case KindGroupFolder:
      return navFind(m_groupFolderItems, [id](const auto& v) { return v == id; });
    case KindTableFolder:
      return navFind(m_tableFolderItems, [id](const auto& v) { return v == id; });
    case KindWorkspace:
      return navFind(m_workspaceItems, [id](const auto& v) { return v == id; });
    case KindWorkspaceFolder:
      return navFind(m_workspaceFolderItems, [id](const auto& v) { return v == id; });
    case KindUserTable: {
      const QString& key = entry.key;
      return navFind(m_userTableItems, [&key](const auto& v) { return v == key; });
    }
    case KindMqttPublisher:
      return m_mqttPublisherItem;
    case KindControlScript:
      return m_controlScriptItem;
    default:
      return nullptr;
  }
}

bool DataModel::ProjectEditor::sameNavTarget(const NavEntry& a, const NavEntry& b) noexcept
{
  if (a.container != b.container)
    return false;

  if (a.container)
    return a.view == b.view;

  return a.kind == b.kind && a.id == b.id && a.parentId == b.parentId && a.key == b.key;
}

void DataModel::ProjectEditor::pushNavEntry(const NavEntry& entry)
{
  if (!entry.valid)
  const int size = static_cast<int>(m_navHistory.size());
  if (m_navCursor >= 0 && m_navCursor < size
      && sameNavTarget(m_navHistory[static_cast<size_t>(m_navCursor)], entry))
  if (m_navCursor + 1 < size)
    m_navHistory.erase(m_navHistory.begin() + (m_navCursor + 1), m_navHistory.end());

  m_navHistory.push_back(entry);
  m_navCursor = static_cast<int>(m_navHistory.size()) - 1;

  if (static_cast<int>(m_navHistory.size()) > kMaxNavHistory) {
    const int drop = static_cast<int>(m_navHistory.size()) - kMaxNavHistory;
    m_navHistory.erase(m_navHistory.begin(), m_navHistory.begin() + drop);
    m_navCursor -= drop;
  }

  Q_ASSERT(static_cast<int>(m_navHistory.size()) <= kMaxNavHistory);
  Q_ASSERT(m_navCursor >= 0 && m_navCursor < static_cast<int>(m_navHistory.size()));
  Q_EMIT navHistoryChanged();
}

void DataModel::ProjectEditor::clearNavHistory()
{
  if (m_navHistory.empty() && m_navCursor == -1)
  m_navHistory.clear();
  m_navCursor = -1;
  Q_EMIT navHistoryChanged();
}

void DataModel::ProjectEditor::navigateBack()
{
  if (!canGoBack() || !m_selectionModel)
  Q_ASSERT(m_navCursor > 0);

  int idx               = m_navCursor - 1;
  QStandardItem* target = nullptr;
  for (int guard = static_cast<int>(m_navHistory.size()); idx >= 0 && guard > 0; --guard, --idx) {
    target = resolveNavEntry(m_navHistory[static_cast<size_t>(idx)]);
    if (target)
      break;
  }

  if (!target)
  m_navCursor         = idx;
  m_navigatingHistory = true;
  m_navDirection      = -1;
  m_selectionModel->setCurrentIndex(target->index(), QItemSelectionModel::ClearAndSelect);
  m_navDirection      = 0;
  m_navigatingHistory = false;
  Q_EMIT navHistoryChanged();
}

bool DataModel::ProjectEditor::canMoveCurrent(int direction) const
{
  const int step = direction < 0 ? -1 : 1;

  if (m_currentView == GroupView) {
    const int target = m_selectedGroup.groupId + step;
    return m_selectedGroup.groupId >= 0 && target >= 0 && target < m_projectModelRef.groupCount();
  }

  if (m_currentView == ActionView) {
    const int target = m_selectedAction.actionId + step;
    return m_selectedAction.actionId >= 0 && target >= 0
           && target < static_cast<int>(m_projectModelRef.actions().size());
  }

  const auto& groups = m_projectModelRef.groups();

  if (m_currentView == DatasetView) {
    const int gid = m_selectedDataset.groupId;
    if (gid < 0 || static_cast<size_t>(gid) >= groups.size())
      return false;

    const int target = m_selectedDataset.datasetId + step;
    return m_selectedDataset.datasetId >= 0 && target >= 0
           && target < static_cast<int>(groups[static_cast<size_t>(gid)].datasets.size());
  }

  if (m_currentView == OutputWidgetView) {
    const int gid = m_selectedOutputWidget.groupId;
    if (gid < 0 || static_cast<size_t>(gid) >= groups.size())
      return false;

    const int target = m_selectedOutputWidget.widgetId + step;
    return m_selectedOutputWidget.widgetId >= 0 && target >= 0
           && target < static_cast<int>(groups[static_cast<size_t>(gid)].outputWidgets.size());
  }

  if (m_currentView == WorkspaceView) {
    const auto& ws = m_projectModelRef.editorWorkspaces();
    const int n    = static_cast<int>(ws.size());
    int from       = -1;
    for (int i = 0; i < n; ++i)
      if (ws[static_cast<size_t>(i)].workspaceId == m_selectedWorkspaceId) {
        from = i;
        break;
      }

    if (from < 0)
      return false;

    const int parent = ws[static_cast<size_t>(from)].parentFolderId;
    for (int j = from + step; j >= 0 && j < n; j += step)
      if (ws[static_cast<size_t>(j)].parentFolderId == parent)
        return true;

    return false;
  }

  return m_currentView == GroupFolderView || m_currentView == TableFolderView
         || m_currentView == WorkspaceFolderView;
}

void DataModel::ProjectEditor::setTreeIndexExpanded(const QModelIndex& index, bool expanded)
{
  if (!m_treeModel)
    return;

  if (auto* item = m_treeModel->itemFromIndex(index))
    item->setData(expanded, TreeViewExpanded);
}

bool DataModel::ProjectEditor::treeIndexHasChildren(const QModelIndex& index) const
{
  const auto* item = m_treeModel ? m_treeModel->itemFromIndex(index) : nullptr;
  return item && item->hasChildren();
}

bool DataModel::ProjectEditor::treeIndexExpanded(const QModelIndex& index) const
{
  const auto* item = m_treeModel ? m_treeModel->itemFromIndex(index) : nullptr;
  return item && item->data(TreeViewExpanded).toBool();
}

quint64 peakResidentBytes()
{
#if defined(Q_OS_WIN)
  PROCESS_MEMORY_COUNTERS pmc = {};
  if (K32GetProcessMemoryInfo(GetCurrentProcess(), &pmc, sizeof(pmc)))
    return static_cast<quint64>(pmc.PeakWorkingSetSize);

  return 0;
#elif defined(Q_OS_MACOS)
  struct rusage usage = {};
  if (getrusage(RUSAGE_SELF, &usage) != 0)
    return 0;

  return static_cast<quint64>(usage.ru_maxrss);
#elif defined(Q_OS_LINUX)
  struct rusage usage = {};
  if (getrusage(RUSAGE_SELF, &usage) != 0)
    return 0;

  return static_cast<quint64>(usage.ru_maxrss) * 1024ull;
#else
  return 0;
#endif
}

[[nodiscard]] static libusb_context* sharedUsbContext()
{
  static libusb_context* const ctx = [] {
    libusb_context* c = nullptr;
    if (libusb_init(&c) != 0)
      c = nullptr;

    return c;
  }();

  return ctx;
}

QString Misc::WorkspaceManager::sanitizeName(const QString& name)
{
  static const QRegularExpression unsafe(QStringLiteral("[/\\\\:*?\"<>|\\x00-\\x1F]"));
  static const QRegularExpression edges(QStringLiteral("^[ .]+|[ .]+$"));

  QString out = name;
  out.replace(unsafe, QStringLiteral("_"));
  out.replace(QStringLiteral(".."), QStringLiteral("_"));
  out.replace(edges, QString());
  if (out.isEmpty())
    out = QStringLiteral("untitled");

  return out;
}

void UI::Dashboard::setFftAudioTap(const int index, const bool enabled, const quint32 key)
{
  Q_ASSERT(index >= 0);
  Q_ASSERT(static_cast<int>(m_fftPushes.size()) == m_fftValues.size());
  if (index < 0 || index >= static_cast<int>(m_fftPushes.size()))
    return;

  m_fftPushes[index].record     = enabled;
  m_fftPushes[index].sessionKey = key;
}

void UI::Dashboard::setWaterfallAudioTap(const int index, const bool enabled, const quint32 key)
{
  Q_ASSERT(index >= 0);
  Q_ASSERT(static_cast<int>(m_waterfallPushes.size()) == m_waterfallValues.size());
  if (index < 0 || index >= static_cast<int>(m_waterfallPushes.size()))
    return;

  m_waterfallPushes[index].record     = enabled;
  m_waterfallPushes[index].sessionKey = key;
}

static void appendLE16(QByteArray& buffer, quint16 value)
{
  buffer.append(static_cast<char>(value & 0xFF));
  buffer.append(static_cast<char>((value >> 8) & 0xFF));
}

static void appendLE32(QByteArray& buffer, quint32 value)
{
  buffer.append(static_cast<char>(value & 0xFF));
  buffer.append(static_cast<char>((value >> 8) & 0xFF));
  buffer.append(static_cast<char>((value >> 16) & 0xFF));
  buffer.append(static_cast<char>((value >> 24) & 0xFF));
}

static void appendFloatLE(QByteArray& buffer, float value)
{
  quint32 bits = 0;
  std::memcpy(&bits, &value, sizeof(bits));
  appendLE32(buffer, bits);
}

static QString audioKindSlug(SerialStudio::DashboardWidget kind)
{
  Q_ASSERT(kind != SerialStudio::DashboardNoWidget);
  switch (kind) {
    case SerialStudio::DashboardFFT:
      return QStringLiteral("fft");
    case SerialStudio::DashboardWaterfall:
      return QStringLiteral("waterfall");
    default:
      return QStringLiteral("widget");
  }
}

Widgets::AudioExportWorker::~AudioExportWorker()
{
  for (auto& [key, session] : m_sessions)
    finalizeSession(session);

  m_sessions.clear();
}

void Widgets::AudioExportWorker::closeResources()
{
  for (auto& [key, session] : m_sessions)
    finalizeSession(session);

  m_sessions.clear();
}

void Widgets::AudioExportWorker::openSession(quint32 key, AudioSessionConfig config)
{
  Q_ASSERT(config.sampleRate > 0);
  Q_ASSERT(!config.outputPath.isEmpty());

  auto existing = m_sessions.find(key);
  if (existing != m_sessions.end()) {
    finalizeSession(existing->second);
    m_sessions.erase(existing);
  }

  AudioSession session;
  session.config = std::move(config);
  if (!openWavFile(session)) {
    Q_EMIT sessionOpenFailed(key);
    return;
  }

  m_sessions.emplace(key, std::move(session));
  Q_EMIT resourceOpenChanged();
}

void Widgets::AudioExportWorker::closeSession(quint32 key)
{
  processData();

  auto it = m_sessions.find(key);
  if (it == m_sessions.end())
    return;

  Q_ASSERT(it->first == key);
  finalizeSession(it->second);
  m_sessions.erase(it);
  Q_EMIT resourceOpenChanged();
}

void Widgets::AudioExportWorker::closeAllSessions()
{
  processData();

  const bool wasOpen = !m_sessions.empty();
  for (auto& [key, session] : m_sessions)
    finalizeSession(session);

  m_sessions.clear();
  if (wasOpen)
    Q_EMIT resourceOpenChanged();
}

void Widgets::AudioExportWorker::processItems(const std::vector<AudioExportItem>& items)
{
  Q_ASSERT(items.size() <= 10000);
  Q_ASSERT(kBytesPerSample == 4);
  if (m_sessions.empty())
    return;

  std::unordered_map<quint32, QByteArray> pending;
  const size_t count = items.size();
  for (size_t i = 0; i < count; ++i) {
    const auto& item = items[i];
    auto it          = m_sessions.find(item.sessionKey);
    if (it == m_sessions.end())
      continue;

    auto& session = it->second;
    float mapped  = item.value;
    if (session.config.useScale) {
      const double norm =
        (static_cast<double>(item.value) - session.config.center) / session.config.halfRange;
      mapped = static_cast<float>(std::clamp(norm, -1.0, 1.0));
    } else {
      const float magnitude = std::fabs(mapped);
      if (magnitude > session.runningPeak)
        session.runningPeak = magnitude;
    }

    appendFloatLE(pending[item.sessionKey], mapped);
    ++session.sampleCount;
  }

  for (auto& [key, buffer] : pending) {
    auto it = m_sessions.find(key);
    if (it == m_sessions.end() || !it->second.file)
      continue;

    auto& session      = it->second;
    const qint64 wrote = session.file->write(buffer);
    const qint64 good  = std::max<qint64>(0, wrote);
    Q_ASSERT(session.bytesOnDisk >= 0);
    session.bytesOnDisk += good;
    if (wrote != buffer.size())
      session.droppedSamples += (buffer.size() - good) / kBytesPerSample;

    patchWavSizes(*session.file, session.bytesOnDisk);
  }
}

bool Widgets::AudioExportWorker::openWavFile(AudioSession& session)
{
  Q_ASSERT(session.config.sampleRate > 0);
  Q_ASSERT(!session.config.outputPath.isEmpty());

  const QFileInfo info(session.config.outputPath);
  if (!QDir().mkpath(info.absolutePath())) {
    qWarning() << "AudioExport: failed to create directory" << info.absolutePath();
    return false;
  }

  session.file = std::make_unique<QFile>(session.config.outputPath);
  if (!session.file->open(QIODevice::ReadWrite | QIODevice::Truncate)) {
    qWarning() << "AudioExport: failed to open" << session.config.outputPath;
    session.file.reset();
    return false;
  }

  writeWavHeader(*session.file, session.config.sampleRate);
  return true;
}

void Widgets::AudioExportWorker::writeWavHeader(QFile& file, int sampleRate)
{
  Q_ASSERT(file.isOpen());
  Q_ASSERT(sampleRate > 0);

  const quint16 channels   = 1;
  const quint16 bits       = 32;
  const quint16 blockAlign = static_cast<quint16>(channels * bits / 8);
  const quint32 byteRate   = static_cast<quint32>(sampleRate) * blockAlign;

  QByteArray header;
  header.reserve(kWavHeaderBytes);
  header.append("RIFF", 4);
  appendLE32(header, 0);
  header.append("WAVE", 4);
  header.append("fmt ", 4);
  appendLE32(header, 16);
  appendLE16(header, 3);
  appendLE16(header, channels);
  appendLE32(header, static_cast<quint32>(sampleRate));
  appendLE32(header, byteRate);
  appendLE16(header, blockAlign);
  appendLE16(header, bits);
  header.append("data", 4);
  appendLE32(header, 0);

  const qint64 wrote = file.write(header);
  Q_ASSERT(wrote == kWavHeaderBytes);
  Q_UNUSED(wrote);
}

void Widgets::AudioExportWorker::patchWavSizes(QFile& file, qint64 dataBytes)
{
  Q_ASSERT(file.isOpen());
  Q_ASSERT(dataBytes >= 0);

  QByteArray riffSize;
  QByteArray dataSize;
  appendLE32(riffSize, static_cast<quint32>(kRiffChunkOverhead + dataBytes));
  appendLE32(dataSize, static_cast<quint32>(dataBytes));

  bool ok = file.seek(kRiffSizeOffset) && file.write(riffSize) == riffSize.size();
  ok      = ok && file.seek(kDataSizeOffset) && file.write(dataSize) == dataSize.size();
  ok      = ok && file.seek(kWavHeaderBytes + dataBytes);
  if (!ok)
    qWarning() << "AudioExport: failed to patch WAV sizes for" << file.fileName();
}

void Widgets::AudioExportWorker::rescaleDataChunk(AudioSession& session, float gain)
{
  Q_ASSERT(session.file != nullptr);
  Q_ASSERT(gain > 0.0f);

  const qint64 dataBytes = session.bytesOnDisk;
  const qint64 chunks    = (dataBytes + kRescaleChunk - 1) / kRescaleChunk;
  for (qint64 c = 0; c < chunks; ++c) {
    const qint64 offset = kWavHeaderBytes + c * kRescaleChunk;
    const qint64 length = std::min(kRescaleChunk, dataBytes - c * kRescaleChunk);
    if (!session.file->seek(offset)) {
      qWarning() << "AudioExport: seek failed while rescaling" << session.config.outputPath;
      break;
    }

    QByteArray buffer = session.file->read(length);
    if (buffer.size() != length) {
      qWarning() << "AudioExport: short read while rescaling" << session.config.outputPath;
      break;
    }

    const qint64 samples = length / kBytesPerSample;
    for (qint64 s = 0; s < samples; ++s) {
      float value = 0.0f;
      std::memcpy(&value, buffer.constData() + s * kBytesPerSample, sizeof(value));
      value *= gain;
      std::memcpy(buffer.data() + s * kBytesPerSample, &value, sizeof(value));
    }

    if (!session.file->seek(offset) || session.file->write(buffer) != buffer.size()) {
      qWarning() << "AudioExport: short write while rescaling" << session.config.outputPath;
      break;
    }
  }
}

void Widgets::AudioExportWorker::writeAudibleCompanion(AudioSession& session, int factor)
{
  Q_ASSERT(session.file != nullptr);
  Q_ASSERT(factor >= 1);

  QString base = session.config.outputPath;
  if (base.endsWith(QStringLiteral(".wav"), Qt::CaseInsensitive))
    base.chop(4);

  const QString path = QStringLiteral("%1-audible-%2x.wav").arg(base, QString::number(factor));
  QFile companion(path);
  if (!companion.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
    qWarning() << "AudioExport: failed to open companion" << path;
    return;
  }

  writeWavHeader(companion, session.config.sampleRate * factor);

  const qint64 dataBytes = session.bytesOnDisk;
  const qint64 chunks    = (dataBytes + kRescaleChunk - 1) / kRescaleChunk;
  for (qint64 c = 0; c < chunks; ++c) {
    const qint64 offset = kWavHeaderBytes + c * kRescaleChunk;
    const qint64 length = std::min(kRescaleChunk, dataBytes - c * kRescaleChunk);
    if (!session.file->seek(offset)) {
      qWarning() << "AudioExport: seek failed for companion" << path;
      break;
    }

    const QByteArray buffer = session.file->read(length);
    if (buffer.size() != length) {
      qWarning() << "AudioExport: short read for companion" << path;
      break;
    }

    if (companion.write(buffer) != buffer.size()) {
      qWarning() << "AudioExport: short write for companion" << path;
      break;
    }
  }

  patchWavSizes(companion, dataBytes);
  companion.close();
}

void Widgets::AudioExportWorker::finalizeSession(AudioSession& session)
{
  Q_ASSERT(session.config.sampleRate > 0);
  if (!session.file)
    return;

  if (session.sampleCount == 0) {
    session.file->close();
    QFile::remove(session.config.outputPath);
    session.file.reset();
    return;
  }

  Q_ASSERT(session.runningPeak >= 0.0f);
  if (!session.config.useScale && session.runningPeak > 0.0f)
    rescaleDataChunk(session, kHeadroomFullScale / session.runningPeak);

  patchWavSizes(*session.file, session.bytesOnDisk);

  if (session.config.sampleRate < kAudibleFloorHz) {
    const int factor =
      static_cast<int>(std::ceil(static_cast<double>(kAudibleFloorHz) / session.config.sampleRate));
    writeAudibleCompanion(session, factor);
  }

  if (session.droppedSamples > 0)
    qWarning() << "AudioExport: dropped" << session.droppedSamples << "samples for"
               << session.config.outputPath;

  session.file->close();
  session.file.reset();
}

Widgets::AudioExport::AudioExport()
  : DataModel::FrameConsumer<AudioExportItem>(
      {.queueCapacity = 65536, .flushThreshold = 4096, .timerIntervalMs = 33})
{
  initializeWorker();

  auto* worker = static_cast<AudioExportWorker*>(m_worker);
  connect(worker, &AudioExportWorker::sessionOpenFailed, this, &AudioExport::onSessionOpenFailed);

  setConsumerEnabled(true);
}

Widgets::AudioExport& Widgets::AudioExport::instance()
{
  static AudioExport singleton;
  return singleton;
}

quint32 Widgets::AudioExport::sessionKey(SerialStudio::DashboardWidget kind, int index)
{
  Q_ASSERT(index >= 0);
  return (static_cast<quint32>(kind) << 16) | (static_cast<quint32>(index) & 0xFFFFu);
}

QString Widgets::AudioExport::audioPath(const QString& datasetTitle,
                                        const QString& projectTitle) const
{
  static auto& workspaceManager = Misc::WorkspaceManager::instance();
  const auto base               = workspaceManager.path(QStringLiteral("Audio Recordings"));
  return QStringLiteral("%1/%2/%3")
    .arg(base,
         Misc::WorkspaceManager::sanitizeName(projectTitle),
         Misc::WorkspaceManager::sanitizeName(datasetTitle));
}

void Widgets::AudioExport::openSession(SerialStudio::DashboardWidget kind,
                                       int index,
                                       AudioSessionConfig config)
{
  Q_ASSERT(m_worker != nullptr);
  Q_ASSERT(config.sampleRate > 0);

  const quint32 key = sessionKey(kind, index);
  const auto dir    = audioPath(config.datasetTitle, config.projectTitle);
  const auto stamp =
    QDateTime::currentDateTime().toString(QStringLiteral("yyyy-MM-dd_HH-mm-ss-zzz"));
  const auto slug = audioKindSlug(kind);
  config.outputPath =
    QStringLiteral("%1/%2-%3%4.wav").arg(dir, stamp, slug, QString::number(index));
  m_activeSessions.insert(key);

  auto* worker = static_cast<AudioExportWorker*>(m_worker);
  QMetaObject::invokeMethod(
    worker, [worker, key, config] { worker->openSession(key, config); }, Qt::QueuedConnection);
}

void Widgets::AudioExport::closeSession(SerialStudio::DashboardWidget kind, int index)
{
  Q_ASSERT(m_worker != nullptr);
  const quint32 key = sessionKey(kind, index);
  m_activeSessions.remove(key);

  auto* worker = static_cast<AudioExportWorker*>(m_worker);
  QMetaObject::invokeMethod(
    worker, [worker, key] { worker->closeSession(key); }, Qt::QueuedConnection);
}

void Widgets::AudioExport::closeAllSessions()
{
  Q_ASSERT(m_worker != nullptr);
  m_activeSessions.clear();

  auto* worker = static_cast<AudioExportWorker*>(m_worker);
  QMetaObject::invokeMethod(worker, [worker] { worker->closeAllSessions(); }, Qt::QueuedConnection);

  Q_EMIT sessionsClosed();
}

void Widgets::AudioExport::onSessionOpenFailed(quint32 key)
{
  Q_ASSERT(m_worker != nullptr);
  Q_ASSERT(thread() == QThread::currentThread());

  m_activeSessions.remove(key);
  Q_EMIT sessionClosed(key);
}

void Widgets::AudioExport::setupExternalConnections()
{
  connect(
    &IO::ConnectionManager::instance(), &IO::ConnectionManager::connectedChanged, this, [this] {
      if (!IO::ConnectionManager::instance().isConnected())
        closeAllSessions();
    });

  connect(&IO::ConnectionManager::instance(), &IO::ConnectionManager::pausedChanged, this, [this] {
    if (IO::ConnectionManager::instance().paused())
      closeAllSessions();
  });

  connect(&CSV::Player::instance(), &CSV::Player::openChanged, this, [this] {
    if (CSV::Player::instance().isOpen())
      closeAllSessions();
  });

  connect(&MDF4::Player::instance(), &MDF4::Player::openChanged, this, [this] {
    if (MDF4::Player::instance().isOpen())
      closeAllSessions();
  });

  connect(&Sessions::Player::instance(), &Sessions::Player::openChanged, this, [this] {
    if (Sessions::Player::instance().isOpen())
      closeAllSessions();
  });

  connect(
    &Licensing::LemonSqueezy::instance(), &Licensing::LemonSqueezy::activatedChanged, this, [this] {
      if (!SerialStudio::proWidgetsEnabled())
        closeAllSessions();
    });
}

Widgets::FFTPlot::~FFTPlot()
{
#ifdef BUILD_COMMERCIAL
  if (m_audioRecordingEnabled) {
