[[nodiscard]] static std::vector<DataModel::AlarmBand>
parseAlarmBandList(const QVariantList& bands)
{
  std::vector<DataModel::AlarmBand> out;
  out.reserve(bands.size());
  for (const auto& v : bands) {
    const auto m = v.toMap();
    DataModel::AlarmBand band;
    band.min   = SerialStudio::toDouble(m.value(QStringLiteral("min")));
    band.max   = SerialStudio::toDouble(m.value(QStringLiteral("max")));
    band.blink = m.value(QStringLiteral("blink"), false).toBool();
    band.color = m.value(QStringLiteral("color")).toString().simplified();
    band.label = m.value(QStringLiteral("label")).toString().simplified();
    const int sev =
      m.value(QStringLiteral("severity"), static_cast<int>(DataModel::AlarmSeverity::Warning))
        .toInt();
    band.severity = static_cast<DataModel::AlarmSeverity>(qBound(0, sev, 3));
    if (band.max > band.min)
      out.push_back(std::move(band));
  }

  return out;
}

void DataModel::ProjectEditor::commitAlarmBandsForSelection(
  const std::vector<DataModel::AlarmBand>& bands)
{
  auto& pm = m_projectModelRef;

  QVector<DataModel::Dataset> sel;
  QVector<QPair<int, int>> ids;
  {
    const auto& groups = pm.groups();
    for (const auto& pr : m_batchItems) {
      const int gid = pr.first, dsid = pr.second;
      if (gid < 0 || static_cast<size_t>(gid) >= groups.size())
        continue;

      for (const auto& d : groups[gid].datasets)
        if (d.datasetId == dsid) {
          sel.append(d);
          ids.append(pr);
          break;
        }
    }
  }

  pm.setAutoSaveSuspended(true);
  for (int i = 0; i < sel.size(); ++i) {
    DataModel::Dataset ds = sel[i];
    ds.alarmBands         = bands;
    pm.updateDataset(ids[i].first, ids[i].second, ds, false);
  }
  pm.setAutoSaveSuspended(false);

  buildMultiDatasetModel();
  pm.flushAutoSave();
}

[[nodiscard]] static QVariantList bandsToVariantList(const std::vector<DataModel::AlarmBand>& bands)
{
  QVariantList out;
  out.reserve(static_cast<int>(bands.size()));
  for (const auto& b : bands) {
    QVariantMap entry;
    entry.insert(QStringLiteral("min"), qMin(b.min, b.max));
    entry.insert(QStringLiteral("max"), qMax(b.min, b.max));
    entry.insert(QStringLiteral("severity"), static_cast<int>(b.severity));
    entry.insert(QStringLiteral("color"), b.color);
    entry.insert(QStringLiteral("label"), b.label);
    entry.insert(QStringLiteral("blink"), b.blink);
    out.append(entry);
  }

  return out;
}

[[nodiscard]] static bool alarmBandsEqual(const std::vector<DataModel::AlarmBand>& a,
                                          const std::vector<DataModel::AlarmBand>& b)
{
  if (a.size() != b.size())
    return false;

  for (size_t i = 0; i < a.size(); ++i)
    if (a[i].min != b[i].min || a[i].max != b[i].max || a[i].severity != b[i].severity
        || a[i].blink != b[i].blink || a[i].color != b[i].color || a[i].label != b[i].label)
      return false;

  return true;
}

void DataModel::ProjectEditor::openAlarmBandsEditorForMultiSelection()
{
  auto& pm = m_projectModelRef;

  QVector<DataModel::Dataset> sel;
  {
    const auto& groups = pm.groups();
    for (const auto& pr : m_batchItems) {
      const int gid = pr.first, dsid = pr.second;
      if (gid < 0 || static_cast<size_t>(gid) >= groups.size())
        continue;

      for (const auto& d : groups[gid].datasets)
        if (d.datasetId == dsid) {
          sel.append(d);
          break;
        }
    }
  }

  if (sel.isEmpty())
    return;

  bool haveRange   = false;
  double range_min = 0, range_max = 100;
  for (const auto& d : sel) {
    double lo = qMin(d.wgtMin, d.wgtMax);
    double hi = qMax(d.wgtMin, d.wgtMax);
    if (hi <= lo) {
      lo = qMin(d.pltMin, d.pltMax);
      hi = qMax(d.pltMin, d.pltMax);
    }

    if (hi <= lo)
      continue;

    range_min = haveRange ? qMin(range_min, lo) : lo;
    range_max = haveRange ? qMax(range_max, hi) : hi;
    haveRange = true;
  }

  if (!haveRange) {
    range_min = 0;
    range_max = 100;
  }

  bool shared            = true;
  const auto& firstBands = sel.first().alarmBands;
  for (int i = 1; i < sel.size() && shared; ++i)
    shared = alarmBandsEqual(sel[i].alarmBands, firstBands);

  const QVariantList bands = shared ? bandsToVariantList(firstBands) : QVariantList();
  Q_EMIT openAlarmBandsEditor(-1, -1, range_min, range_max, bands);
}

QHash<int, QVariant>
DataModel::ProjectEditor::outputWidgetEditValues(const DataModel::OutputWidget& widget)
{
  QHash<int, QVariant> out;
  out.insert(kOutputWidget_Title, widget.title);
  out.insert(kOutputWidget_Icon, widget.icon);
  out.insert(kOutputWidget_MonoIcon, widget.monoIcon);
  out.insert(kOutputWidget_MinValue, widget.minValue);
  out.insert(kOutputWidget_MaxValue, widget.maxValue);
  out.insert(kOutputWidget_StepSize, widget.stepSize);
  out.insert(kOutputWidget_InitialValue, widget.initialValue);
  out.insert(kOutputWidget_TxEncoding, widget.txEncoding);
  return out;
}

void DataModel::ProjectEditor::buildMultiOutputWidgetModel()
{
  auto& pm           = m_projectModelRef;
  const auto& groups = pm.groups();

  QVector<DataModel::OutputWidget> sel;
  sel.reserve(static_cast<qsizetype>(m_batchItems.size()));
  for (const auto& pr : m_batchItems) {
    const int gid = pr.first, wid = pr.second;
    if (gid < 0 || static_cast<size_t>(gid) >= groups.size())
      continue;

    for (const auto& w : groups[gid].outputWidgets)
      if (w.widgetId == wid) {
        sel.append(w);
        break;
      }
  }

  if (sel.isEmpty())
    return;

  QVector<QHash<int, QVariant>> maps;
  maps.reserve(sel.size());
  for (const auto& w : sel)
    maps.append(outputWidgetEditValues(w));

  if (m_outputWidgetModel) {
    m_outputWidgetModel->disconnect(this);
    m_outputWidgetModel->deleteLater();
  }

  m_selectedOutputWidget = sel.first();
  m_outputWidgetModel    = new CustomModel(this);

  buildOutputWidgetCommonRows(m_selectedOutputWidget);
  buildOutputWidgetTransmitRow(m_selectedOutputWidget);
  buildOutputWidgetValueRows(m_selectedOutputWidget);

  const int rows = m_outputWidgetModel->rowCount();
  for (int r = 0; r < rows; ++r) {
    auto* it = m_outputWidgetModel->item(r);
    if (!it)
      continue;

    const auto ptVar = it->data(ParameterType);
    if (!ptVar.isValid())
      continue;

    const int wt         = it->data(WidgetType).toInt();
    const bool intWidget = (wt == ComboBox || wt == CheckBox);
    const QVariant blank = intWidget ? QVariant(-1) : QVariant(QString());

    const int pt = ptVar.toInt();
    if (pt == kOutputWidget_Title) {
      it->setEditable(false);
      it->setData(false, Active);
      it->setData(blank, EditableValue);
      it->setData(tr("(multiple)"), PlaceholderValue);
      continue;
    }

    const QVariant first = maps.first().value(pt);
    bool mixed           = false;
    for (int i = 1; i < maps.size(); ++i)
      if (maps[i].contains(pt) && maps[i].value(pt) != first) {
        mixed = true;
        break;
      }

    if (mixed) {
      it->setData(blank, EditableValue);
      it->setData(tr("Mixed"), PlaceholderValue);
    }
  }

  connect(m_outputWidgetModel,
          &CustomModel::itemChanged,
          this,
          &DataModel::ProjectEditor::onMultiSelectionItemChanged);

  Q_EMIT outputWidgetModelChanged();
}

PHONEME_TAB *TonePhoneme(const PHONEME_LIST *plist)
{
	// Prefer the phoneme resolved while the word's own table was current.
	// tone_ph on its own is table-local, so looking it up in phoneme_tab is
	// only correct for words which did not switch language.
	if (plist->tone_ph_data != NULL)
		return plist->tone_ph_data;
	return phoneme_tab[plist->tone_ph];
}

int IsRegionalIndicator(unsigned int c)
{
	// Regional Indicator Symbol Letter A..Z. A flag emoji is exactly two of
	// these (e.g. U+1F1F0 U+1F1FF = KZ), so they are kept in the same token
	// in pairs.
	return (c >= 0x1f1e6) && (c <= 0x1f1ff);
}

int IsEmojiModifier(unsigned int c)
{
	// Emoji skin tone modifiers, which attach to the preceding emoji.
	return (c >= 0x1f3fb) && (c <= 0x1f3ff);
}

int IsEmojiTag(unsigned int c)
{
	// Tag characters, including the cancel tag U+E007F. They spell out a
	// subdivision code after a base emoji in a tag sequence, such as
	// U+1F3F4 + "gbsct" + cancel = flag of Scotland.
	return (c >= 0xe0020) && (c <= 0xe007f);
}

static void SegmentReplacement(Translator *tr, const char *text, char *out, int out_size)
{
	// Apply the word-splitting rules of the clause tokenizer (TranslateClause)
	// to dictionary replacement text, so that a $textmode replacement is
	// re-translated in the same word units as if it had been normal input:
	// for languages with langopts.ideographs each CJK character is a separate
	// word (so that hanzi words can match their multi-word *_list entries),
	// and a non-alpha mark such as a Thai tone mark terminates a word instead
	// of derailing the letter-to-phoneme rules mid-word.
	// ASCII characters are always kept in-word: for Latin-script replacement
	// text ("t-rex", "cai3hong2") the existing single-word behaviour is kept.
	int ix = 0, out_ix = 0;
	int c = 0;

	while (text[ix] != 0) {
		int prev = c;
		int nbytes = utf8_in(&c, &text[ix]);
		bool insert_space = false;

		if (IsAlpha(prev)) {
			if (IsAlpha(c)) {
				if (tr->langopts.ideographs && ((c > 0x3040) || (prev > 0x3040)))
					insert_space = true; // each ideograph is a separate word
			} else if (!IsSpace(c) && (c >= 0x80) && (wcschr(tr->punct_within_word, c) == 0))
				insert_space = true; // eg. a Thai tone mark ends the word, as in the clause tokenizer
		} else if ((prev >= 0x80) && !IsSpace(prev) && IsAlpha(c) && (wcschr(tr->punct_within_word, prev) == 0))
			insert_space = true; // a letter after such a mark starts a new word

		if (out_ix + nbytes + 2 > out_size)
			break;
		if (insert_space)
			out[out_ix++] = ' ';
		memcpy(&out[out_ix], &text[ix], nbytes);
		out_ix += nbytes;
		ix += nbytes;
	}
	out[out_ix] = 0;
}

static bool LookupEmojiSkinTone(Translator *tr, char **wordptr, unsigned int *flags, WORD_TAB *wtab, int wtab_remaining)
{
	// An emoji sequence containing skin tone modifiers (U+1F3FB..U+1F3FF)
	// usually has no dictionary entry of its own.  Retry the lookup with the
	// modifiers removed, and speak the modifier names after the base sequence:
	// woman + medium skin tone + ZWJ + microscope -> "woman scientist medium skin tone"

	static char replacement[N_WORD_BYTES];
	char stripped[N_WORD_BYTES + 2];
	int modifiers[8];
	int n_modifiers = 0;
	int c;
	int nbytes;
	int length = 0;
	int len2;
	int ix;
	const char *p;
	char *wp;
	char ph_buf[N_WORD_PHONEMES];
	unsigned int flags2[2];

	p = *wordptr;
	utf8_in(&c, p);
	if (!IsEmoji(c))
		return false;

	while ((*p != 0) && (*p != ' ')) {
		nbytes = utf8_in(&c, p);
		if ((c >= 0x1f3fb) && (c <= 0x1f3ff)) {
			if (n_modifiers < 8)
				modifiers[n_modifiers++] = c;
		} else if (length + nbytes < N_WORD_BYTES) {
			memcpy(&stripped[length], p, nbytes);
			length += nbytes;
		}
		p += nbytes;
	}

	if ((n_modifiers == 0) || (length == 0))
		return false;

	stripped[length] = ' ';
	stripped[length+1] = 0;

	flags2[0] = 0;
	flags2[1] = 0;
	wp = stripped;
	LookupDictList(tr, &wp, ph_buf, flags2, FLAG_ALLOW_TEXTMODE, wtab, wtab_remaining);
	if (!(flags2[0] & FLAG_TEXTMODE))
		return false; // the base sequence has no replacement text either

	// wp now points into a static buffer which the modifier lookups below
	// will overwrite, so copy the base replacement text out immediately
	length = strlen(wp); // includes a trailing space
	if (length > N_WORD_BYTES-4)
		return false;
	replacement[0] = 0;
	replacement[1] = ' ';
	memcpy(&replacement[2], wp, length+1);
	length += 2;

	for (ix = 0; ix < n_modifiers; ix++) {
		char modifier_word[8];

		len2 = utf8_out(modifiers[ix], modifier_word);
		modifier_word[len2] = ' ';
		modifier_word[len2+1] = 0;

		flags2[0] = 0;
		flags2[1] = 0;
		wp = modifier_word;
		LookupDictList(tr, &wp, ph_buf, flags2, FLAG_ALLOW_TEXTMODE, wtab, wtab_remaining);
		if (!(flags2[0] & FLAG_TEXTMODE))
			continue; // no replacement text for the modifier in this language

		len2 = strlen(wp);
		if (length + len2 >= N_WORD_BYTES-1)
			break;
		memcpy(&replacement[length], wp, len2+1);
		length += len2;
	}

	if (option_phonemes & espeakPHONEMES_TRACE) {
		char word_buf[N_WORD_BYTES];

		for (len2 = 0; len2 < N_WORD_BYTES-1; len2++) {
			if (((c = (*wordptr)[len2]) == 0) || (c == ' '))
				break;
			word_buf[len2] = c;
		}
		word_buf[len2] = 0;
		fprintf(f_trans, "Replace: %s  %s\n", word_buf, &replacement[2]);
	}

	*wordptr = &replacement[2];
	*flags |= FLAG_TEXTMODE;
	return true;
}

int IsEmoji(unsigned int c)
{
	// Returns true for codepoints in the emoji/symbol ranges that IsAlpha()
	// admits as word characters. Used by the clause tokenizer to force a
	// word boundary between emoji and adjacent letters, so that a regular
	// word followed directly by an emoji (e.g. "дыму🐠") is not merged
	// into one token — that would defeat dictionary lookup for the word
	// and trigger letter-by-letter spelling of its alphabetic part.
		return 1; // Emoji blocks (Emoticons, Transport, Supplemental, etc.),
		          // includes Regional Indicator Symbols at U+1F1E0..U+1F1FF

static int hiTokCaseEq(const char *p, const char *tok, size_t n) {
    size_t i;
    for (i = 0; i < n; i++) {
        if (tolower((unsigned char)p[i]) != (unsigned char)tok[i]) return 0;
    }
    return 1;
}

