            CHECK(m.Lc[i][(int64_t)p*m.c.kv_lora+j]==fill(i,p,j), "v1 Lc[%d] p%d j%d", i,p,j);

    /* ---- v1 file + KV8: quantize-on-load; il file v1 resta INTATTO (un crash
     * prima del primo save non deve perdere la conversazione) ---- */
    if(m.kv->disk_fp){ fclose(m.kv->disk_fp); m.kv->disk_fp=NULL; }  /* "riavvio" del processo */
    g_kv8=1; kv_alloc(&m,16); m.kv->disk_nrec=0;
    CHECK(kv_disk_load(&m,hist2,16)==NP, "v1->kv8 load");
    CHECK(m.kv->disk_nrec==0, "v1->kv8 leaves disk_nrec=0 for the full rewrite");
    { FILE *f=fopen(PATH,"rb"); char mg[8]={0};
      CHECK(f && fread(mg,1,8,f)==8 && !memcmp(mg,KV_MAGIC,8),
            "v1 file must survive the upgrade load untouched");
      if(f) fclose(f); }
    for(int i=0;i<m.c.n_layers;i++) for(int p=0;p<NP;p++){
        float sc=m.Lsc[i][p];
        for(int j=0;j<m.c.kv_lora;j++){
            float want=fill(i,p,j), got=coli_fp8_lut[m.Lc8[i][(int64_t)p*m.c.kv_lora+j]]*sc;
            CHECK(fabsf(got-want)<=fabsf(want)/16.f+sc*0x1p-10f+1e-7f,
                  "v1->kv8 Lc[%d] p%d j%d: %g vs %g", i,p,j,got,want);
        }
    }

    /* ---- v2: fp8 append + load must round-trip BYTE-identical ---- */
    kv_disk_append(&m,hist,NP);
    CHECK(m.kv->disk_nrec==NP, "v2 append nrec=%d", m.kv->disk_nrec);
    { FILE *f=fopen(PATH,"rb"); char mg[8]={0};
      CHECK(f && fread(mg,1,8,f)==8 && !memcmp(mg,KV_MAGIC2,8), "v2 magic on disk");
      if(f) fclose(f); }
    uint8_t keepL[2][5*8]; float keepS[2][5];
    for(int i=0;i<m.c.n_layers;i++) for(int p=0;p<NP;p++){
        memcpy(keepL[i]+(size_t)p*m.c.kv_lora, m.Lc8[i]+(int64_t)p*m.c.kv_lora, m.c.kv_lora);
        keepS[i][p]=m.Lsc[i][p];
    }
    kv_alloc(&m,16); m.kv->disk_nrec=0;
    CHECK(kv_disk_load(&m,hist2,16)==NP, "v2 load");
    for(int i=0;i<m.c.n_layers;i++) for(int p=0;p<NP;p++){
        CHECK(!memcmp(m.Lc8[i]+(int64_t)p*m.c.kv_lora, keepL[i]+(size_t)p*m.c.kv_lora, m.c.kv_lora),
              "v2 Lc8 bytes layer %d pos %d", i,p);
        CHECK(m.Lsc[i][p]==keepS[i][p], "v2 Lsc layer %d pos %d", i,p);
    }

    /* ---- v2 sotto f32: si riparte da zero, il file NON va creduto ---- */
    if(m.kv->disk_fp){ fclose(m.kv->disk_fp); m.kv->disk_fp=NULL; }  /* "riavvio" del processo */
    g_kv8=0; kv_alloc(&m,16); m.kv->disk_nrec=0;
    CHECK(kv_disk_load(&m,hist2,16)==0, "v2 under f32 must be rejected");

    /* ---- append con formato diverso dal file: riscrittura dal record 0 ---- */
    for(int i=0;i<m.c.n_layers;i++) for(int p=0;p<NP;p++){
        for(int j=0;j<m.c.kv_lora;j++) m.Lc[i][(int64_t)p*m.c.kv_lora+j]=fill(i,p,j);
        for(int j=0;j<m.c.qk_rope;j++) m.Rc[i][(int64_t)p*m.c.qk_rope+j]=fill(i+9,p,j);
    }
    if(m.kv->disk_fp){ fclose(m.kv->disk_fp); m.kv->disk_fp=NULL; }  /* "riavvio" del processo */
    m.kv->disk_nrec=3;                              /* stantio: la magic v2 lo invalida */
    kv_disk_append(&m,hist,NP);
    { FILE *f=fopen(PATH,"rb"); char mg[8]={0};
      CHECK(f && fread(mg,1,8,f)==8 && !memcmp(mg,KV_MAGIC,8), "self-heal rewrote v1 magic");
      if(f) fclose(f); }
    kv_alloc(&m,16); m.kv->disk_nrec=0;
    CHECK(kv_disk_load(&m,hist2,16)==NP, "self-healed v1 load");
    for(int p=0;p<NP;p++) CHECK(hist2[p]==hist[p], "self-heal hist[%d]", p);

    /* ---- v3: KV_TQ PolarQuant append + load must round-trip BYTE-identical, plus
     * the reject paths (v3 under f32; v3 under a different bit width). Same tiny
     * synthetic config: kv_lora=8, qk_rope=4 (both powers of two, as TQ requires). */
    if(m.kv->disk_fp){ fclose(m.kv->disk_fp); m.kv->disk_fp=NULL; }
    remove(PATH);
    g_kv8=0; g_tq=1; g_tq_bits=4;
    kv_alloc(&m,16); m.kv->disk_nrec=0;
    int lbb=coli_tq_row_bytes(m.c.kv_lora,g_tq_bits), rbb=coli_tq_row_bytes(m.c.qk_rope,g_tq_bits);
    for(int i=0;i<m.c.n_layers;i++) for(int p=0;p<NP;p++){       /* populate via the producer's PolarQuant */
        float lr[8], rr[4];
        for(int j=0;j<m.c.kv_lora;j++) lr[j]=fill(i,p,j);
        for(int j=0;j<m.c.qk_rope;j++) rr[j]=fill(i+9,p,j);
        m.Lsc[i][p]=coli_tq_quant_row(lr, coli_kv_row8(m.Lc8[i],p,lbb), m.c.kv_lora, g_tq_bits);
        m.Rsc[i][p]=coli_tq_quant_row(rr, coli_kv_row8(m.Rc8[i],p,rbb), m.c.qk_rope, g_tq_bits);
    }
    kv_disk_append(&m,hist,NP);
    CHECK(m.kv->disk_nrec==NP, "v3 append nrec=%d", m.kv->disk_nrec);
    { FILE *f=fopen(PATH,"rb"); char mg[8]={0};
      CHECK(f && fread(mg,1,8,f)==8 && !memcmp(mg,KV_MAGIC3,8), "v3 magic on disk");
      if(f) fclose(f); }
    uint8_t keepL3[2][5*8], keepR3[2][5*4]; float keepLs3[2][5], keepRs3[2][5];
    for(int i=0;i<m.c.n_layers;i++) for(int p=0;p<NP;p++){
        memcpy(keepL3[i]+(size_t)p*lbb, coli_kv_row8(m.Lc8[i],p,lbb), lbb);
        memcpy(keepR3[i]+(size_t)p*rbb, coli_kv_row8(m.Rc8[i],p,rbb), rbb);
        keepLs3[i][p]=m.Lsc[i][p]; keepRs3[i][p]=m.Rsc[i][p];
    }
    kv_alloc(&m,16); m.kv->disk_nrec=0;
    CHECK(kv_disk_load(&m,hist2,16)==NP, "v3 load");
    for(int i=0;i<m.c.n_layers;i++) for(int p=0;p<NP;p++){
        CHECK(!memcmp(coli_kv_row8(m.Lc8[i],p,lbb), keepL3[i]+(size_t)p*lbb, lbb), "v3 Lc8 bytes layer %d pos %d", i,p);
        CHECK(!memcmp(coli_kv_row8(m.Rc8[i],p,rbb), keepR3[i]+(size_t)p*rbb, rbb), "v3 Rc8 bytes layer %d pos %d", i,p);
        CHECK(m.Lsc[i][p]==keepLs3[i][p], "v3 Lsc layer %d pos %d", i,p);
        CHECK(m.Rsc[i][p]==keepRs3[i][p], "v3 Rsc layer %d pos %d", i,p);
    }
    /* v3 under f32: reject (the file must not be believed) */
    if(m.kv->disk_fp){ fclose(m.kv->disk_fp); m.kv->disk_fp=NULL; }
    g_tq=0; g_kv8=0; kv_alloc(&m,16); m.kv->disk_nrec=0;
    CHECK(kv_disk_load(&m,hist2,16)==0, "v3 under f32 must be rejected");
    /* v3 under a DIFFERENT bit width: reject (can't decode 4-bit angles as 3-bit) */
    if(m.kv->disk_fp){ fclose(m.kv->disk_fp); m.kv->disk_fp=NULL; }
    g_tq=1; g_tq_bits=3; kv_alloc(&m,16); m.kv->disk_nrec=0;
    CHECK(kv_disk_load(&m,hist2,16)==0, "v3 under different bit width must be rejected");
    g_tq=0;

    remove(PATH);
    if(fails){ fprintf(stderr,"%d failure(s)\n",fails); return 1; }
    printf("OK kv_disk v1/v2 round-trip + upgrade + reject + self-heal\n");
    return 0;
}

nt main(void){
    coli_fp8_lut_init();

    /* exhaustive round-trip on every code except the NaN patterns (0x7F/0xFF,
     * decoded as 0 by design, never produced by the encoder) */
    for(int b=0;b<256;b++){
        if((b&0x7F)==0x7F) continue;             /* NaN codes: decoded as 0, never produced */
        uint8_t e=coli_fp8_enc(coli_fp8_lut[b]);
        CHECK(e==(uint8_t)b, "roundtrip byte 0x%02x -> %g -> 0x%02x", b, coli_fp8_lut[b], e);
    }

    /* saturation and specials */
    CHECK(coli_fp8_enc(448.f)==0x7E, "448 is the max normal");
    CHECK(coli_fp8_enc(-448.f)==0xFE, "-448");
    CHECK(coli_fp8_enc(1000.f)==0x7E, "overflow saturates");
    CHECK(coli_fp8_enc(-1e30f)==0xFE, "negative overflow saturates");
    CHECK(coli_fp8_enc(INFINITY)==0x7E, "+inf saturates");
    CHECK(coli_fp8_enc(NAN)==0x00, "NaN stored as inert 0");
    CHECK(coli_fp8_enc(0.f)==0x00 && coli_fp8_enc(-0.f)==0x80, "signed zeros preserved");

    /* round-to-nearest-even at midpoints: steps of 2 in [16,32) (E=11).
     * 17 ties between 16 (mant 0, even) and 18 (mant 1, odd) -> 16;
     * 19 ties between 18 (mant 1) and 20 (mant 2, even) -> 20. */
    CHECK(coli_fp8_lut[coli_fp8_enc(17.f)]==16.f, "RNE tie 17 -> 16, got %g", coli_fp8_lut[coli_fp8_enc(17.f)]);
    CHECK(coli_fp8_lut[coli_fp8_enc(19.f)]==20.f, "RNE tie 19 -> 20, got %g", coli_fp8_lut[coli_fp8_enc(19.f)]);
    CHECK(coli_fp8_lut[coli_fp8_enc(17.1f)]==18.f, "17.1 -> 18");
    /* denormal boundary: half of the smallest denormal (2^-10) ties to 0 (even) */
    CHECK(coli_fp8_enc(0x1p-10f)==0x00, "2^-10 ties to even 0");
    CHECK(coli_fp8_enc(0x1.8p-10f)==0x01, "0.75*2^-9 rounds up to the first denormal");
    /* mantissa overflow across the exponent boundary: just below 2^-6 */
    CHECK(coli_fp8_lut[coli_fp8_enc(0x1.fcp-7f)]==0x1p-6f, "denormal grid rounds up into the first normal");
    /* binade-boundary tie WITH mantissa carry (k==16 -> k=8,E++): 15.5 lies exactly
     * between 15 (M=7, odd) and 16 (next binade, M=0, even) -> RNE must carry to 16.
     * The exhaustive roundtrip never triggers this (grid points encode carry-free). */
    CHECK(coli_fp8_lut[coli_fp8_enc(15.5f)]==16.f, "RNE tie 15.5 -> 16 (mantissa carry), got %g",
          coli_fp8_lut[coli_fp8_enc(15.5f)]);
    CHECK(coli_fp8_lut[coli_fp8_enc(15.9f)]==16.f, "15.9 rounds up across the binade");
    CHECK(coli_fp8_lut[coli_fp8_enc(0x1.dp3f)]==14.f, "14.5 ties down to even 14");

    /* per-row quantizer: amax maps exactly to ±448*scale, error bounded by
     * |x|/16 (3 mantissa bits) + half a denormal step (scale*2^-10) */
    enum { N=576 };
    float row[N]; uint8_t q[N]; float deq[N];
    for(int i=0;i<N;i++) row[i]=sinf(0.7f*i)*expf(-((i%37)*0.21f))*(i%2?1.f:-1.f)*3.7f;
    row[123]=-9.25f;                              /* the amax, negative on purpose */
    float scale=coli_kv8_quant_row(row,q,N);
    CHECK(fabsf(scale-9.25f/448.f)<1e-9f, "scale = amax/448 (got %g)", scale);
    coli_kv8_dequant_row(q,scale,deq,N);
    CHECK(deq[123]==-9.25f || fabsf(deq[123]+9.25f)<=9.25f*1e-6f, "amax survives the trip (got %g)", deq[123]);
    for(int i=0;i<N;i++){
        float err=fabsf(deq[i]-row[i]), bound=fabsf(row[i])/16.f+scale*0x1p-10f+1e-7f;
        CHECK(err<=bound, "elem %d: |%g - %g| = %g > bound %g", i, deq[i], row[i], err, bound);
    }

    /* all-zero row: bytes 0, scale 1 (no fabricated 1/0) */
    float zrow[8]={0}; uint8_t zq[8];
    CHECK(coli_kv8_quant_row(zrow,zq,8)==1.f, "zero row keeps scale 1");
    for(int i=0;i<8;i++) CHECK(zq[i]==0, "zero row byte %d", i);
    /* subnormal amax: 448/amax would overflow to +inf and saturate every nonzero
     * element to ±448 — the guard must treat the row as zero instead */
    float tiny[4]={1e-38f,-1e-38f,0,1e-40f}; uint8_t tq[4];
    CHECK(coli_kv8_quant_row(tiny,tq,4)==1.f, "subnormal row keeps scale 1");
    for(int i=0;i<4;i++) CHECK(tq[i]==0, "subnormal row byte %d", i);

    /* row accessor twin: same arithmetic as coli_kv_row, byte-typed */
    uint8_t buf[7*5];
    CHECK(coli_kv_row8(buf,4,7)==buf+28, "coli_kv_row8 arithmetic");
    CHECK(coli_kv_row8(buf,0,7)==buf, "coli_kv_row8 row 0");

    if(fails){ fprintf(stderr,"%d failure(s)\n",fails); return 1; }
    printf("OK kv_fp8 e4m3 (exhaustive roundtrip + RNE + row quant)\n");
    return 0;
}

static float avg_relerr(int n,int bits,int rows){
    int rb=coli_tq_row_bytes(n,bits);
    float *x=malloc(sizeof(float)*n), *y=malloc(sizeof(float)*n); uint8_t *q=malloc(rb);
    double acc=0;
    for(int r=0;r<rows;r++){
        for(int i=0;i<n;i++) x[i]=gauss()*3.7f;
        float rad=coli_tq_quant_row(x,q,n,bits);
        coli_tq_dequant_row(q,rad,y,n,bits);
        float nx=norm2(x,n); acc += (nx>0)? l2diff(x,y,n)/nx : 0;
    }
    free(x); free(y); free(q);
    return (float)(acc/rows);
}

static bool dwarf_type_is_fp(const char *type) {
	if (R_STR_ISEMPTY (type) || strchr (type, '*') || strchr (type, '[')) {
		return false;
	}
	while (r_str_startswith (type, "const ") || r_str_startswith (type, "volatile ")) {
		type = strchr (type, ' ') + 1;
	}
	const char *const names[] = {
		"float", "double", "long double", "_Float16", "__float128",
		"f32", "f64", "float32", "float64",
		"complex64", "complex128", NULL
	};
	int i;
	for (i = 0; names[i]; i++) {
		if (!strcmp (type, names[i])) {
			return true;
		}
	}
	return false;
}

static void arm64_esil_zero_extend_dst(RAnalOp *op, csh *handle, cs_insn *insn) {
	if (!insn->detail || insn->detail->arm64.op_count < 1) {
		return;
	}
	const cs_arm64_op *dst = &insn->detail->arm64.operands[0];
	if (dst->type != ARM64_OP_REG || !(dst->access & CS_AC_WRITE)) {
		return;
	}
	const char *wide = cs_reg_name (*handle, dst->reg);
	if (!wide || *wide != 'w' || !isdigit ((ut8)wide[1])) {
		return;
	}
	if (r_strbuf_length (&op->esil) < 1) {
		return;
	}
	/* Storing through the 64-bit name clears the top half without reading it,
	 * so the register-access analysis still reports only what is really read. */
	r_strbuf_appendf (&op->esil, ",%s,x%s,=", wide, wide + 1);
}

static void styles_init(void)
{
    static bool inited = false;
    if(inited) return;
    inited = true;

    /*Window background: a flat, edge-to-edge column with the base object's card
     *flattened away (no padding, border or radius).*/
    lv_style_init(&style_win);
    lv_style_set_pad_all(&style_win, 0);
    lv_style_set_pad_gap(&style_win, 0);
    lv_style_set_border_width(&style_win, 0);
    lv_style_set_radius(&style_win, 0);

    /*Title bar: a grey header with tight padding.*/
    lv_style_init(&style_header);
    lv_style_set_bg_opa(&style_header, LV_OPA_COVER);
    lv_style_set_bg_color(&style_header, lv_palette_lighten(LV_PALETTE_GREY, 2));
    lv_style_set_text_color(&style_header, lv_palette_darken(LV_PALETTE_GREY, 4));
    lv_style_set_pad_all(&style_header, 2);
    lv_style_set_pad_gap(&style_header, 2);
    lv_style_set_border_width(&style_header, 0);
    lv_style_set_radius(&style_header, 0);

    /*Content area: a screen-coloured body with normal padding.*/
    lv_style_init(&style_content);
    lv_style_set_bg_opa(&style_content, LV_OPA_COVER);
    lv_style_set_bg_color(&style_content, lv_palette_lighten(LV_PALETTE_GREY, 4));
    lv_style_set_pad_all(&style_content, 16);
    lv_style_set_border_width(&style_content, 0);
    lv_style_set_radius(&style_content, 0);
}

static lv_obj_t * win_create(lv_obj_t * parent)
{
    lv_obj_t * win = lv_obj_create(parent);
    lv_obj_set_size(win, lv_obj_get_width(parent), lv_obj_get_height(parent));
    lv_obj_set_flex_flow(win, LV_FLEX_FLOW_COLUMN);
    lv_obj_add_style(win, &style_win, 0);

    lv_obj_t * header = lv_obj_create(win);
    lv_obj_set_size(header, lv_pct(100), lv_display_get_dpi(lv_obj_get_display(win)) / 2);
    lv_obj_set_flex_flow(header, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(header, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_add_style(header, &style_header, 0);

    lv_obj_t * content = lv_obj_create(win);
    lv_obj_set_width(content, lv_pct(100));
    lv_obj_set_flex_grow(content, 1);
    lv_obj_add_style(content, &style_content, 0);

    return win;
}

static lv_obj_t * win_add_title(lv_obj_t * win, const char * txt)
{
    lv_obj_t * title = lv_label_create(win_get_header(win));
    lv_label_set_long_mode(title, LV_LABEL_LONG_MODE_DOTS);
    lv_label_set_text(title, txt);
    lv_obj_set_flex_grow(title, 1);
    return title;
}

static lv_obj_t * win_add_button(lv_obj_t * win, const void * icon, int32_t btn_w)
{
    lv_obj_t * btn = lv_button_create(win_get_header(win));
    lv_obj_set_size(btn, btn_w, lv_pct(100));

#if LV_USE_IMAGE == 1
    if(icon) {
        lv_obj_t * img = lv_image_create(btn);
        lv_image_set_src(img, icon);
        lv_obj_align(img, LV_ALIGN_CENTER, 0, 0);
    }
#endif

    return btn;
}

static void event_handler(lv_event_t * e)
{
    lv_obj_t * obj = lv_event_get_target_obj(e);
    LV_LOG_USER("Button %d clicked", (int)lv_obj_get_index(obj));
}

void lv_example_flex_win(void)
{
    styles_init();

    lv_obj_t * win = win_create(lv_screen_active());
    lv_obj_t * btn;
    btn = win_add_button(win, LV_SYMBOL_LEFT, 40);
    lv_obj_add_event_cb(btn, event_handler, LV_EVENT_CLICKED, NULL);

    win_add_title(win, "A title");

    btn = win_add_button(win, LV_SYMBOL_RIGHT, 40);
    lv_obj_add_event_cb(btn, event_handler, LV_EVENT_CLICKED, NULL);

    btn = win_add_button(win, LV_SYMBOL_CLOSE, 60);
    lv_obj_add_event_cb(btn, event_handler, LV_EVENT_CLICKED, NULL);

    lv_obj_t * content = win_get_content(win);  /*Content can be added here*/
    lv_obj_t * label = lv_label_create(content);
    lv_label_set_text(label, "This is\n"
                      "a pretty\n"
                      "long text\n"
                      "to see how\n"
                      "the window\n"
                      "becomes\n"
                      "scrollable.\n"
                      "\n"
                      "\n"
                      "Some more\n"
                      "text to be\n"
                      "sure it\n"
                      "overflows. :)");
}

static void styles_init(void)
{
    static bool inited = false;
    if(inited) return;
    inited = true;

    /*List background: flatten the base object's card into a tight, edge-clipped column.*/
    lv_style_init(&style_list);
    lv_style_set_pad_ver(&style_list, 0);
    lv_style_set_pad_gap(&style_list, 0);
    lv_style_set_clip_corner(&style_list, true);

    /*Section header: a full-width grey bar with dark text. The transform makes the
     *grey reach the list edges despite the list's horizontal padding.*/
    lv_style_init(&style_header);
    lv_style_set_bg_opa(&style_header, LV_OPA_COVER);
    lv_style_set_bg_color(&style_header, lv_palette_lighten(LV_PALETTE_GREY, 2));
    lv_style_set_text_color(&style_header, lv_palette_darken(LV_PALETTE_GREY, 4));
    lv_style_set_transform_width(&style_header, 16);

    /*List button: a flat white row with a grey bottom divider, overriding the
     *default blue button look.*/
    lv_style_init(&style_button);
    lv_style_set_radius(&style_button, 0);
    lv_style_set_shadow_width(&style_button, 0);
    lv_style_set_bg_opa(&style_button, LV_OPA_COVER);
    lv_style_set_bg_color(&style_button, lv_color_white());
    lv_style_set_text_color(&style_button, lv_palette_darken(LV_PALETTE_GREY, 4));
    lv_style_set_border_width(&style_button, 1);
    lv_style_set_border_color(&style_button, lv_palette_lighten(LV_PALETTE_GREY, 2));
    lv_style_set_border_side(&style_button, LV_BORDER_SIDE_BOTTOM);
    lv_style_set_pad_all(&style_button, 8);
    lv_style_set_pad_column(&style_button, 8);

    /*Pressed feedback: a subtle dark recolor.*/
    lv_style_init(&style_button_pressed);
    lv_style_set_recolor(&style_button_pressed, lv_color_black());
    lv_style_set_recolor_opa(&style_button_pressed, LV_OPA_20);
}

static lv_obj_t * flex_list_create(lv_obj_t * parent)
{
    lv_obj_t * list = lv_obj_create(parent);
    lv_obj_set_flex_flow(list, LV_FLEX_FLOW_COLUMN);
    lv_obj_add_style(list, &style_list, 0);
    return list;
}

static lv_obj_t * flex_list_add_text(lv_obj_t * list, const char * txt)
{
    lv_obj_t * label = lv_label_create(list);
    lv_obj_set_width(label, lv_pct(100));
    lv_obj_add_style(label, &style_header, 0);
    lv_label_set_text(label, txt);
    return label;
}

static lv_obj_t * flex_list_add_button(lv_obj_t * list, const void * icon, const char * txt)
{
    lv_obj_t * btn = lv_button_create(list);
    lv_obj_set_size(btn, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(btn, LV_FLEX_FLOW_ROW);
    lv_obj_add_style(btn, &style_button, 0);
    lv_obj_add_style(btn, &style_button_pressed, LV_STATE_PRESSED);

#if LV_USE_IMAGE == 1
    if(icon) {
        lv_obj_t * img = lv_image_create(btn);
        lv_image_set_src(img, icon);
    }
#endif

    if(txt) {
        lv_obj_t * label = lv_label_create(btn);
        lv_label_set_text(label, txt);
        lv_label_set_long_mode(label, LV_LABEL_LONG_MODE_SCROLL_CIRCULAR);
        lv_obj_set_flex_grow(label, 1);
    }

    return btn;
}

static const char * flex_list_get_button_text(lv_obj_t * btn)
{
    uint32_t i;
    for(i = 0; i < lv_obj_get_child_count(btn); i++) {
        lv_obj_t * child = lv_obj_get_child(btn, i);
        if(lv_obj_check_type(child, &lv_label_class)) {
            return lv_label_get_text(child);
        }
    }
    return "";
}

static void event_handler(lv_event_t * e)
{
    lv_event_code_t code = lv_event_get_code(e);
    lv_obj_t * obj = lv_event_get_target_obj(e);
    if(code == LV_EVENT_CLICKED) {
        LV_LOG_USER("Clicked: %s", flex_list_get_button_text(obj));
    }
}

void lv_example_flex_list(void)
{
    styles_init();

    /*Create a list from a flex column*/
    flex_list = flex_list_create(lv_screen_active());
