void* subghz_protocol_decoder_telcoma_edge_alloc(SubGhzEnvironment* environment) {
    UNUSED(environment);
    SubGhzProtocolDecoderTelcomaEdge* instance = malloc(sizeof(SubGhzProtocolDecoderTelcomaEdge));
    instance->base.protocol = &subghz_protocol_telcoma_edge;
    instance->generic.protocol_name = instance->base.protocol->name;
    instance->half_pending = false;
    return instance;
}

void subghz_protocol_decoder_telcoma_edge_free(void* context) {
    furi_assert(context);
    SubGhzProtocolDecoderTelcomaEdge* instance = context;
    free(instance);
}

void subghz_protocol_decoder_telcoma_edge_reset(void* context) {
    furi_assert(context);
    SubGhzProtocolDecoderTelcomaEdge* instance = context;
    instance->decoder.decode_data = 0;
    instance->decoder.decode_count_bit = 0;
    instance->half_pending = false;
}

static void subghz_protocol_decoder_telcoma_edge_add_half(
    SubGhzProtocolDecoderTelcomaEdge* instance,
    bool level) {
    if(!instance->half_pending) {
        instance->half_pending = true;
        instance->half_level = level;
        return;
    }
    instance->half_pending = false;
    if(instance->half_level && !level) {
        subghz_protocol_blocks_add_bit(&instance->decoder, 1); /* high -> low = 1 */
    } else if(!instance->half_level && level) {
        subghz_protocol_blocks_add_bit(&instance->decoder, 0); /* low -> high = 0 */
    }
    /* same-level pair: phase violation, emit no bit (matches the reference) */
}

void subghz_protocol_decoder_telcoma_edge_feed(void* context, bool level, uint32_t duration) {
    furi_assert(context);
    SubGhzProtocolDecoderTelcomaEdge* instance = context;

    if(DURATION_DIFF(duration, subghz_protocol_telcoma_edge_const.te_short) <
       subghz_protocol_telcoma_edge_const.te_delta) {
        subghz_protocol_decoder_telcoma_edge_add_half(instance, level);
    } else if(
        DURATION_DIFF(duration, subghz_protocol_telcoma_edge_const.te_long) <
        subghz_protocol_telcoma_edge_const.te_delta) {
        subghz_protocol_decoder_telcoma_edge_add_half(instance, level);
        subghz_protocol_decoder_telcoma_edge_add_half(instance, level);
    } else {
        /* End of a burst (inter-frame gap): publish a complete frame.
         *
         * Channel framing (derived from clean multi-channel captures): the gate
         * channel decodes as 32 Manchester bits; every other channel carries a
         * one-hot marker that adds one bit, so it decodes as 33 bits. Normalise
         * both to a canonical 32-bit key (drop the extra trailing bit on 33-bit
         * frames) so data/count stay uniform; the channel then lives in the low
         * bits. The encoder reverses this exactly (see get_upload). */
        uint32_t count = instance->decoder.decode_count_bit;
        if(count == 32 || count == 33) {
            uint32_t key = (count == 33) ? (uint32_t)(instance->decoder.decode_data >> 1) :
                                           (uint32_t)instance->decoder.decode_data;
            /* Reject noise/partial frames: a valid frame starts with 0xFF. */
            if((key >> 24) == 0xFF) {
                instance->generic.data = key;
                instance->generic.data_count_bit =
                    subghz_protocol_telcoma_edge_const.min_count_bit_for_found;
                if(instance->base.callback) {
                    instance->base.callback(&instance->base, instance->base.context);
                }
            }
        }
        instance->decoder.decode_data = 0;
        instance->decoder.decode_count_bit = 0;
        instance->half_pending = false;
    }
}

uint8_t subghz_protocol_decoder_telcoma_edge_get_hash_data(void* context) {
    furi_assert(context);
    SubGhzProtocolDecoderTelcomaEdge* instance = context;
    return subghz_protocol_blocks_get_hash_data(
        &instance->decoder, (instance->decoder.decode_count_bit / 8) + 1);
}

SubGhzProtocolStatus subghz_protocol_decoder_telcoma_edge_serialize(
    void* context,
    FlipperFormat* flipper_format,
    SubGhzRadioPreset* preset) {
    furi_assert(context);
    SubGhzProtocolDecoderTelcomaEdge* instance = context;
    return subghz_block_generic_serialize(&instance->generic, flipper_format, preset);
}

SubGhzProtocolStatus
    subghz_protocol_decoder_telcoma_edge_deserialize(void* context, FlipperFormat* flipper_format) {
    furi_assert(context);
    SubGhzProtocolDecoderTelcomaEdge* instance = context;
    return subghz_block_generic_deserialize_check_count_bit(
        &instance->generic,
        flipper_format,
        subghz_protocol_telcoma_edge_const.min_count_bit_for_found);
}

void subghz_protocol_decoder_telcoma_edge_get_string(void* context, FuriString* output) {
    furi_assert(context);
    SubGhzProtocolDecoderTelcomaEdge* instance = context;
    uint32_t data = (uint32_t)(instance->generic.data & 0xFFFFFFFF);
    uint32_t payload = data & 0xFFFFFF; /* 24-bit, 0xFF preamble stripped */
    /* Canonical 32-bit key layout: payload[23:3] = per-remote serial/address,
     * payload[2:0] = one-hot channel select (gate = 0, others = 0x1/0x2/0x4).
     * The channel is a position-encoded one-hot marker on the wire that the
     * decoder folds into these low bits (and the encoder restores). */
    uint32_t serial = (payload >> 3) & 0x1FFFFF;
    uint8_t channel = payload & 0x07;
    furi_string_cat_printf(
        output,
        "%s %db\r\n"
        "Key:0x%08lX\r\n"
        "Serial:0x%05lX\r\n"
        "Ch:0x%01X\r\n",
        instance->generic.protocol_name,
        instance->generic.data_count_bit,
        (unsigned long)data,
        (unsigned long)serial,
        channel);
}

void* subghz_protocol_encoder_telcoma_edge_alloc(SubGhzEnvironment* environment) {
    UNUSED(environment);
    SubGhzProtocolEncoderTelcomaEdge* instance = malloc(sizeof(SubGhzProtocolEncoderTelcomaEdge));
    instance->base.protocol = &subghz_protocol_telcoma_edge;
    instance->generic.protocol_name = instance->base.protocol->name;
    instance->encoder.repeat = 10;
    instance->encoder.size_upload = TELCOMA_EDGE_UPLOAD_SIZE;
    instance->encoder.upload = malloc(TELCOMA_EDGE_UPLOAD_SIZE * sizeof(LevelDuration));
    instance->encoder.front = 0;
    instance->encoder.is_running = false;
    return instance;
}

void subghz_protocol_encoder_telcoma_edge_free(void* context) {
    furi_assert(context);
    SubGhzProtocolEncoderTelcomaEdge* instance = context;
    free(instance->encoder.upload);
    free(instance);
}

static bool
    subghz_protocol_encoder_telcoma_edge_get_upload(SubGhzProtocolEncoderTelcomaEdge* instance) {
    furi_assert(instance);
    size_t index = 0;
    uint32_t te = subghz_protocol_telcoma_edge_const.te_short;

    /* Channel-aware reconstruction (validated to reproduce every captured
     * channel pulse-for-pulse):
     *   - gate (channel field 0): 32 Manchester bits + 1 HIGH stop half-bit.
     *   - any other channel:      33 Manchester bits (key << 1), NO stop.
     * The << 1 restores the on-wire one-hot channel marker that the decoder
     * folded into the canonical key's low bits. */
    uint32_t key = (uint32_t)(instance->generic.data & 0xFFFFFFFF);
    uint8_t channel = key & 0x07;
    uint64_t value;
    uint8_t nbits;
    bool add_stop;
    if(channel == 0) {
        value = key;
        nbits = 32;
        add_stop = true;
    } else {
        value = (uint64_t)key << 1;
        nbits = 33;
        add_stop = false;
    }

    /* Worst case: 2 half-bits per bit + 1 stop half-bit + 1 guard gap.
     * Coalescing (below) only reduces this, so this is a safe upper bound. */
    if((size_t)(nbits * 2 + 2) > TELCOMA_EDGE_UPLOAD_SIZE) {
        FURI_LOG_E(TAG, "Upload buffer too small");
        return false;
    }

    /* Emit a half-bit at the given level, COALESCING with the previous entry
     * when the level matches. Manchester naturally produces 2*TE runs at
     * same-bit boundaries; merging them reproduces the exact waveform that
     * was verified on hardware (a strictly level-alternating upload). */
#define TELCOMA_EDGE_PUSH(lvl)                                                                    \
    do {                                                                                          \
        if(index > 0 && level_duration_get_level(instance->encoder.upload[index - 1]) == (lvl)) { \
            instance->encoder.upload[index - 1] = level_duration_make(                            \
                (lvl), level_duration_get_duration(instance->encoder.upload[index - 1]) + te);    \
        } else {                                                                                  \
            instance->encoder.upload[index++] = level_duration_make((lvl), te);                   \
        }                                                                                         \
    } while(0)

    for(int i = nbits - 1; i >= 0; i--) {
        uint8_t bit = (value >> i) & 1;
        if(bit) {
            /* 1 -> high, then low (matches the validated decoder convention) */
            TELCOMA_EDGE_PUSH(true);
            TELCOMA_EDGE_PUSH(false);
        } else {
            /* 0 -> low, then high */
            TELCOMA_EDGE_PUSH(false);
            TELCOMA_EDGE_PUSH(true);
        }
    }
    if(add_stop) {
        /* Trailing HIGH stop half-bit — only the gate channel carries it; it
         * completes the gate's 65-half-bit frame and is REQUIRED there (a frame
         * without it was rejected by the gate, verified on hardware). */
        TELCOMA_EDGE_PUSH(true);
    }
#undef TELCOMA_EDGE_PUSH

    /* inter-frame guard (~4 * TE low), matches the gap seen between bursts */
    instance->encoder.upload[index++] = level_duration_make(false, te * 4);

    instance->encoder.size_upload = index;
    return true;
}

bGhzProtocolStatus
    subghz_protocol_encoder_telcoma_edge_deserialize(void* context, FlipperFormat* flipper_format) {
    furi_assert(context);
    SubGhzProtocolEncoderTelcomaEdge* instance = context;
    SubGhzProtocolStatus ret = SubGhzProtocolStatusError;
    do {
        ret = subghz_block_generic_deserialize_check_count_bit(
            &instance->generic,
            flipper_format,
            subghz_protocol_telcoma_edge_const.min_count_bit_for_found);
        if(ret != SubGhzProtocolStatusOk) break;

        if(!subghz_protocol_encoder_telcoma_edge_get_upload(instance)) {
            ret = SubGhzProtocolStatusErrorEncoderGetUpload;
            break;
        }
        instance->encoder.front = 0;
        instance->encoder.is_running = true;
    } while(false);
    return ret;
}

velDuration subghz_protocol_encoder_telcoma_edge_yield(void* context) {
    SubGhzProtocolEncoderTelcomaEdge* instance = context;

    if(instance->encoder.repeat == 0 || !instance->encoder.is_running) {
        instance->encoder.is_running = false;
        return level_duration_reset();
    }

    LevelDuration ret = instance->encoder.upload[instance->encoder.front];
    if(++instance->encoder.front == instance->encoder.size_upload) {
        instance->encoder.front = 0;
        instance->encoder.repeat--;
    }
    return ret;
}

static DS4_MAYBE_UNUSED bool weights_streaming_layer_experts_uniform(
        const ds4_weights *w,
        uint32_t           il) {
    uint64_t base = 0;
    const ds4_layer_weights *l = &w->layer[il];
    if (!l->ffn_gate_exps || !l->ffn_up_exps || !l->ffn_down_exps) return true;
    if (!ds4_streaming_routed_expert_bytes(w, &base)) return true;
    const uint64_t bytes =
        l->ffn_gate_exps->dim[1] * routed_expert_row_bytes(l->ffn_gate_exps) +
        l->ffn_up_exps->dim[1]   * routed_expert_row_bytes(l->ffn_up_exps) +
        l->ffn_down_exps->dim[1] * routed_expert_row_bytes(l->ffn_down_exps);
    return bytes == base;
}

atic void model_map_span_vec_include_layer_decode(
        ds4_model_map_span_vec *spans,
        const ds4_weights      *w,
        uint32_t                il) {
    const ds4_layer_weights *l = &w->layer[il];
    model_map_span_vec_include_layer_decode_static(spans, l);
    if (!weights_streaming_layer_experts_uniform(w, il)) {
        model_map_span_vec_include_one(spans, l->ffn_gate_exps);
        model_map_span_vec_include_one(spans, l->ffn_up_exps);
        model_map_span_vec_include_one(spans, l->ffn_down_exps);
    }
}

static inline int
levenshtein_result(int64 res)
{
	if (unlikely(res < PG_INT32_MIN || res > PG_INT32_MAX))
		ereport(ERROR,
				(errcode(ERRCODE_NUMERIC_VALUE_OUT_OF_RANGE),
				 errmsg("levenshtein distance out of range")));
	return res;
}

size_t todd(char *dst, const char *src, size_t dsize) {
  const char *osrc = src;
  size_t nleft = dsize;
  if (nleft != 0)
    while (--nleft != 0)
      if ((*dst++ = *src++) == '\0')
        break;
  if (nleft == 0) {
    if (dsize != 0)
      *dst = '\0';
    while (*src++)
      ;
  }
  return src - osrc - 1;
}

static Rect PlacementPreviewScreenRect(DisplayModel* dm, int pageNo, Point pt, PointF pagePt, RectF pageRect) {
    Rect r = dm->CvtToScreen(pageNo, pageRect);
    if (r.IsEmpty()) {
        return {};
    }
    Point anchor = dm->CvtToScreen(pageNo, pagePt);
    r.Offset(pt.x - anchor.x, pt.y - anchor.y);
    return r;
}

static bool SelectAllInFocusedEditControl() {
    bool isCombo = false;
    HWND focus = FocusedEditControl(&isCombo);
    if (!focus) {
        return false;
    }
    if (isCombo) {
        SendMessageW(focus, CB_SETEDITSEL, 0, MAKELPARAM(0, -1));
    } else {
        SendMessageW(focus, EM_SETSEL, 0, (LPARAM)-1);
    }
    return true;
}

bool IsEditingFreeTextInPlace(MainWindow* win) {
    if (!gInPlace.hwnd) {
        return false;
    }
    return !win || gInPlace.win == win;
}

static const WCHAR* WinFontForPdfFontName(Str pdfName) {
    if (str::EqI(pdfName, StrL("Cour"))) {
        return L"Courier New";
    }
    if (str::EqI(pdfName, StrL("TiRo"))) {
        return L"Times New Roman";
    }
    return L"Arial";
}

static Size MeasureInPlaceText(Str text) {
    if (!gInPlace.hwnd) {
        return {};
    }
    HDC hdc = GetDC(gInPlace.hwnd);
    uint format = DT_CALCRECT | DT_NOPREFIX | DT_EDITCONTROL | DT_NOCLIP;
    Size s = HdcMeasureText(hdc, text, 0, format, gInPlace.font);
    ReleaseDC(gInPlace.hwnd, hdc);
    return s;
}

static void SizeInPlaceEditToText() {
    if (!gInPlace.hwnd || !gInPlace.win) {
        return;
    }
    TempStr text = HwndGetTextTemp(gInPlace.hwnd);
    Size ts = MeasureInPlaceText(text);
    int pad = gInPlace.padding;
    // room for the caret past the last glyph
    int caret = std::max(DpiScale(3), 2);
    Size want;
    want.dx = ts.dx + (2 * pad) + caret;
    want.dy = ts.dy + (2 * pad);
    want.dx = std::max(want.dx, gInPlace.minSize.dx);
    want.dy = std::max(want.dy, gInPlace.minSize.dy);
    Rect canvas = HwndClientRect(gInPlace.win->hwndCanvas);
    Rect cur = ChildPosWithinParent(gInPlace.hwnd);
    want.dx = std::min(want.dx, std::max(canvas.dx - cur.x, gInPlace.minSize.dx));
    want.dy = std::min(want.dy, std::max(canvas.dy - cur.y, gInPlace.minSize.dy));
    if (want == gInPlace.size) {
        return;
    }
    gInPlace.size = want;
    SetWindowPos(gInPlace.hwnd, nullptr, 0, 0, want.dx, want.dy, SWP_NOMOVE | SWP_NOZORDER | SWP_NOACTIVATE);
}

void RepositionFreeTextInPlaceEdit(MainWindow* win) {
    if (!IsEditingFreeTextInPlace(win)) {
        return;
    }
    DisplayModel* dm = gInPlace.win->AsFixed();
    Annotation* annot = gInPlace.annot;
    if (!dm || !AnnotationIsLive(annot) || !dm->PageVisible(PageNo(annot))) {
        return;
    }
    Rect r = dm->CvtToScreen(PageNo(annot), GetRect(annot));
    Rect cur = ChildPosWithinParent(gInPlace.hwnd);
    if (cur.x == r.x && cur.y == r.y) {
        return;
    }
    SetWindowPos(gInPlace.hwnd, nullptr, r.x, r.y, 0, 0, SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
}

void EndFreeTextInPlaceEdit(bool accept) {
    if (!gInPlace.hwnd || gInPlaceEnding) {
        return;
    }
    gInPlaceEnding = true;
    HWND hwnd = gInPlace.hwnd;
    HFONT font = gInPlace.font;
    MainWindow* win = gInPlace.win;
    WindowTab* tab = gInPlace.tab;
    Annotation* annot = gInPlace.annot;
    Rect editRect = ChildPosWithinParent(hwnd);
    TempStr text{};
    if (accept) {
        text = str::DupTemp(HwndGetTextTemp(hwnd));
        text = str::ReplaceTemp(text, StrL("\r\n"), StrL("\n"));
    }
    // clear the state and unsubclass before destroying, so the destroy-time
    // WM_KILLFOCUS doesn't come back through the commit path
    gInPlace = {};
    SetWindowLongPtrW(hwnd, GWLP_WNDPROC, (LONG_PTR)gInPlaceDefProc);
    DestroyWindow(hwnd);
    if (font) {
        DeleteObject(font);
    }
    bool winOk = win && IsMainWindowValidAndNotClosing(win);
    if (winOk) {
        HwndSetFocus(win->hwndCanvas);
    }
    if (accept && AnnotationIsLive(annot)) {
        DisplayModel* dm = winOk ? win->AsFixed() : nullptr;
        int pageNo = PageNo(annot);
        if (dm && dm->ValidPageNo(pageNo)) {
            // the box was sized to the text while typing; keep that room so
            // MuPDF doesn't clip what was just written
            RectF cur = GetRect(annot);
            RectF grown = cur.Union(dm->CvtFromScreen(editRect, pageNo));
            if (grown != cur) {
                SetRect(annot, grown);
            }
        }
        SetContents(annot, text);
        AnnotChanged(tab);
    } else if (winOk) {
        MainWindowRerender(win);
    }
    gInPlaceEnding = false;
}

static LRESULT CALLBACK WndProcFreeTextInPlaceEdit(HWND hwnd, UINT msg, WPARAM wp, LPARAM lp) {
    switch (msg) {
        case WM_GETDLGCODE:
            // Enter is a new line and Esc cancels, so we want every key
            return DLGC_WANTALLKEYS;
        case WM_KEYDOWN:
            if (wp == VK_ESCAPE) {
                EndFreeTextInPlaceEdit(false);
                return 0;
            }
            if (wp == VK_RETURN && IsCtrlPressed()) {
                EndFreeTextInPlaceEdit(true);
                return 0;
            }
            break;
        case WM_CHAR:
            // Ctrl+Enter reaches an edit control as LF. That, not the key-down
            // above, is what a real keyboard delivers here.
            if (wp == 0x0A) {
                EndFreeTextInPlaceEdit(true);
                return 0;
            }
            // Esc was handled on key down; don't also insert it
            if (wp == VK_ESCAPE) {
                return 0;
            }
            break;
        case WM_KILLFOCUS:
            EndFreeTextInPlaceEdit(true);
            return 0;
    }
    LRESULT res = CallWindowProcW(gInPlaceDefProc, hwnd, msg, wp, lp);
    switch (msg) {
        case WM_CHAR:
        case WM_KEYDOWN:
        case WM_PASTE:
        case WM_CUT:
        case WM_CLEAR:
        case WM_UNDO:
        case WM_SETTEXT:
        case EM_REPLACESEL:
            SizeInPlaceEditToText();
            break;
    }
    return res;
}

bool StartFreeTextInPlaceEdit(MainWindow* win, Annotation* annot) {
    if (!win || !win->hwndCanvas || !AnnotationIsLive(annot)) {
        return false;
    }
    if (Type(annot) != AnnotationType::FreeText) {
        return false;
    }
    if (gInPlace.annot == annot) {
        return true;
    }
    EndFreeTextInPlaceEdit(true);
    DisplayModel* dm = win->AsFixed();
    int pageNo = PageNo(annot);
    if (!dm || !dm->ValidPageNo(pageNo) || !dm->PageVisible(pageNo)) {
        return false;
    }
    RectF pageRect = GetRect(annot);
    Rect rc = dm->CvtToScreen(pageNo, pageRect);
    if (rc.IsEmpty()) {
        return false;
    }

    // screen pixels per PDF point, so the box matches the rendered text
    float scale = pageRect.dy > 0 ? ((float)rc.dy / pageRect.dy) : 1.f;
    int textSize = DefaultAppearanceTextSize(annot);
    if (textSize <= 0) {
        textSize = 12;
    }
    int fontPx = std::max(6, (int)((float)textSize * scale));
    HFONT font = CreateFontW(-fontPx, 0, 0, 0, FW_NORMAL, FALSE, FALSE, FALSE, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS,
                             CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH,
                             WinFontForPdfFontName(DefaultAppearanceTextFont(annot)));
    if (!font) {
        return false;
    }

    // lines don't wrap: the box grows to fit them instead
    DWORD style = WS_CHILD | WS_VISIBLE | WS_BORDER | ES_MULTILINE | ES_WANTRETURN | ES_AUTOHSCROLL | ES_AUTOVSCROLL;
    HMODULE hmod = GetModuleHandleW(nullptr);
    HWND hwnd =
        CreateWindowExW(0, WC_EDITW, L"", style, rc.x, rc.y, rc.dx, rc.dy, win->hwndCanvas, nullptr, hmod, nullptr);
    if (!hwnd) {
        DeleteObject(font);
        return false;
    }
    SetWindowFont(hwnd, font, TRUE);
    int pad = std::max(DpiScale(2), 1);
    SendMessageW(hwnd, EM_SETMARGINS, EC_LEFTMARGIN | EC_RIGHTMARGIN, MAKELPARAM(pad, pad));
    TempStr text = str::ReplaceTemp(Contents(annot), StrL("\r\n"), StrL("\n"));
    text = str::ReplaceTemp(text, StrL("\n"), StrL("\r\n"));
    HwndSetText(hwnd, text);

    gInPlaceDefProc = (WNDPROC)GetWindowLongPtrW(hwnd, GWLP_WNDPROC);
    SetWindowLongPtrW(hwnd, GWLP_WNDPROC, (LONG_PTR)WndProcFreeTextInPlaceEdit);

    gInPlace.hwnd = hwnd;
    gInPlace.font = font;
    gInPlace.win = win;
    gInPlace.tab = win->CurrentTab();
    gInPlace.annot = annot;
    gInPlace.size = rc.Size();
    gInPlace.minSize = rc.Size();
    gInPlace.padding = pad;

    HwndSetFocus(hwnd);
    // caret at the end, nothing selected: this is editing what is there, not
    // replacing it
    int end = (int)SendMessageW(hwnd, WM_GETTEXTLENGTH, 0, 0);
    Edit_SetSel(hwnd, end, end);
    SizeInPlaceEditToText();
    return true;
}

bool StartFreeTextInPlaceEditAt(MainWindow* win, Point pt) {
    if (!win || !win->pdfAnnotationsToolbarEnabled) {
        return false;
    }
    WindowTab* tab = win->CurrentTab();
    DisplayModel* dm = win->AsFixed();
    if (!tab || !dm) {
        return false;
    }
    Annotation* annot = dm->GetAnnotationAtPos(pt, nullptr);
    if (!annot || Type(annot) != AnnotationType::FreeText) {
        return false;
    }
    SetSelectedAnnotation(tab, annot);
    return StartFreeTextInPlaceEdit(win, annot);
}

TempStr FreeTextInPlaceEditStateTemp(MainWindow* win) {
    if (!IsEditingFreeTextInPlace(win)) {
        return StrL("freeTextEdit active=0 rect=0,0,0,0 text=\n");
    }
    Rect r = ChildPosWithinParent(gInPlace.hwnd);
    TempStr text = HwndGetTextTemp(gInPlace.hwnd);
    text = str::ReplaceTemp(text, StrL("\r\n"), StrL("|"));
    return fmt("freeTextEdit active=1 rect=%d,%d,%d,%d text=%s\n", r.x, r.y, r.dx, r.dy, text);
}

void SetModificationDateToNow(Annotation* annot) {
    if (!AnnotationIsLive(annot)) {
        return;
    }
    EngineMupdf* e = annot->engine;
    auto* a = annot->pdfannot;
    auto* ctx = e->Ctx();
    ScopedRecursiveMutex cs(&e->docLock);
    fz_try(ctx) {
        pdf_set_annot_modification_date(ctx, a, time(nullptr));
    }
    fz_catch(ctx) {
        fz_report_error(ctx);
    }
}

static void RefreshWrapperBounds(EngineMupdf* e, Annotation* w) {
    if (!w || !w->pdfannot) {
        return;
    }
    fz_context* ctx = e->Ctx();
    ScopedRecursiveMutex docScope(&e->docLock);
    fz_rect bounds = {};
    fz_try(ctx) {
        bounds = pdf_bound_annot(ctx, w->pdfannot);
    }
    fz_catch(ctx) {
        fz_report_error(ctx);
        return;
    }
    w->bounds = ToRectF(bounds);
}

static Str FreeTextPlacementContent(const AnnotCreateArgs& args) {
    if (str::IsEmptyOrWhiteSpace(args.content)) {
        return StrL(kDefaultFreeTextContent);
    }
    return args.content;
}

static SizeF FreeTextPlacementPageSize(const AnnotCreateArgs& args) {
    float fontSize = (float)FreeTextFontSize(args);
    float pad = FreeTextPadding(args);
    float dx = 0;
    HDC hdc = GetDC(nullptr);
    {
        Gdiplus::Graphics gs(hdc);
        // Arial has Helvetica's metrics, which is what MuPDF's "Helv" is
        Gdiplus::Font font(L"Arial", kFreeTextMeasureSize, Gdiplus::FontStyleRegular, Gdiplus::UnitPixel);
        WStr text = ToWStrTemp(FreeTextPlacementContent(args));
        // MeasureString with no layout rect: no wrapping, and its generous
        // side bearings keep us from under-measuring vs MuPDF's Helvetica
        RectF measured = MeasureTextStandard(&gs, &font, text);
        dx = measured.dx * fontSize / kFreeTextMeasureSize;
    }
    ReleaseDC(nullptr, hdc);
    dx = (dx * kFreeTextWidthSlack) + (2 * pad) + 2.f;
    float dy = (kFreeTextLineHeight * fontSize) + (2 * pad);
    return {dx, dy};
}

int EngineMupdfUndoPos(EngineMupdf* e, int* stepsOut) {
    if (stepsOut) {
        *stepsOut = 0;
    }
    if (!e || !e->pdfdoc || e->journalNesting > 0) {
        return -1;
    }
    auto* ctx = e->Ctx();
    ScopedRecursiveMutex docScope(&e->docLock);
    int steps = 0;
    int pos = -1;
    fz_try(ctx) {
        pos = pdf_undoredo_state(ctx, e->pdfdoc, &steps);
    }
    fz_catch(ctx) {
        fz_report_error(ctx);
        pos = -1;
    }
    if (stepsOut && pos >= 0) {
        *stepsOut = steps;
    }
    return pos;
}

void EngineMupdfBeginOperation(EngineBase* engine, const char* name) {
    EngineMupdf* e = AsEngineMupdf(engine);
    if (!e || !e->pdfdoc) {
        return;
    }
    auto* ctx = e->Ctx();
    ScopedRecursiveMutex docScope(&e->docLock);
    fz_try(ctx) {
        pdf_begin_operation(ctx, e->pdfdoc, name);
        e->journalNesting++;
    }
    fz_catch(ctx) {
        fz_report_error(ctx);
    }
}

void EngineMupdfEndOperation(EngineBase* engine) {
    EngineMupdf* e = AsEngineMupdf(engine);
    if (!e || !e->pdfdoc || e->journalNesting <= 0) {
        return;
    }
    auto* ctx = e->Ctx();
    ScopedRecursiveMutex docScope(&e->docLock);
    fz_try(ctx) {
        pdf_end_operation(ctx, e->pdfdoc);
        e->journalNesting--;
    }
    fz_catch(ctx) {
        fz_report_error(ctx);
        e->journalNesting--;
    }
}

bool EngineMupdfCanUndo(EngineBase* engine) {
    EngineMupdf* e = AsEngineMupdf(engine);
    int pos = EngineMupdfUndoPos(e, nullptr);
    return pos > 0;
}

bool EngineMupdfCanRedo(EngineBase* engine) {
    EngineMupdf* e = AsEngineMupdf(engine);
    int steps = 0;
    int pos = EngineMupdfUndoPos(e, &steps);
    return pos >= 0 && pos < steps;
}

static Annotation* FindWrapperForPdfAnnot(const Vec<Annotation*>& annots, pdf_annot* a) {
    for (Annotation* w : annots) {
        if (w && w->pdfannot == a) {
            return w;
        }
    }
    return nullptr;
}

static void ResyncWrapperList(EngineMupdf* e, int pageNo, Vec<Annotation*>& wrappers, const Vec<pdf_annot*>& live,
                              Vec<Annotation*>& removedOut) {
    Vec<Annotation*> res;
    for (pdf_annot* a : live) {
        Annotation* w = FindWrapperForPdfAnnot(wrappers, a);
        if (!w) {
            w = MakeAnnotationWrapper(e, a, pageNo);
            if (!w) {
                continue;
            }
        }
        res.Append(w);
    }
    for (Annotation* w : wrappers) {
        if (!w || res.Contains(w)) {
            continue;
        }
        // its pdf_annot is gone; the wrapper must not reach MuPDF again
        w->pdfannot = nullptr;
        removedOut.Append(w);
    }
    wrappers = res;
}

static void SyncPagesAfterUndoRedo(EngineMupdf* e, Vec<Annotation*>& removedOut) {
    auto* ctx = e->Ctx();
    ScopedRecursiveMutex pagesScope(&e->pagesLock);
    ScopedMutex renderScope(&e->renderLock);
    for (FzPageInfo* pi : e->pages) {
        if (!pi || !pi->page) {
            continue;
        }
        if (pi->annotsLoaded) {
            Vec<pdf_annot*> liveAnnots;
            Vec<pdf_annot*> liveWidgets;
            {
                ScopedRecursiveMutex docScope(&e->docLock);
                fz_try(ctx) {
                    pdf_page* page = pdf_page_from_fz_page(ctx, pi->page);
                    for (pdf_annot* a = page ? pdf_first_annot(ctx, page) : nullptr; a; a = pdf_next_annot(ctx, a)) {
                        liveAnnots.Append(a);
                    }
                    for (pdf_annot* a = page ? pdf_first_widget(ctx, page) : nullptr; a; a = pdf_next_widget(ctx, a)) {
                        liveWidgets.Append(a);
                    }
                }
                fz_catch(ctx) {
                    fz_report_error(ctx);
                    continue;
                }
            }
            ResyncWrapperList(e, pi->pageNo, pi->annotations, liveAnnots, removedOut);
            ResyncWrapperList(e, pi->pageNo, pi->widgets, liveWidgets, removedOut);
            {
                ScopedRecursiveMutex docScope(&e->docLock);
                RebuildCommentsFromAnnotations(ctx, pi);
            }
        }
        InvalidateFzPageAfterContentChange(e, pi);
        e->InvalidateTextForPage(pi->pageNo);
    }
}

fz_try(ctx) {
                    pdf_page* page = pdf_page_from_fz_page(ctx, pi->page);
                    for (pdf_annot* a = page ? pdf_first_annot(ctx, page) : nullptr; a; a = pdf_next_annot(ctx, a)) {
                        liveAnnots.Append(a);
                    }
                    for (pdf_annot* a = page ? pdf_first_widget(ctx, page) : nullptr; a; a = pdf_next_widget(ctx, a)) {
                        liveWidgets.Append(a);
                    }
                }

static bool EngineMupdfUndoRedo(EngineBase* engine, bool redo, Vec<Annotation*>& removedOut) {
    removedOut.Reset();
    EngineMupdf* e = AsEngineMupdf(engine);
    if (!e || !e->pdfdoc) {
        return false;
    }
    bool can = redo ? EngineMupdfCanRedo(engine) : EngineMupdfCanUndo(engine);
    if (!can) {
        return false;
    }
    auto* ctx = e->Ctx();
    bool ok = false;
    {
        ScopedRecursiveMutex docScope(&e->docLock);
        fz_try(ctx) {
            if (redo) {
                pdf_redo(ctx, e->pdfdoc);
            } else {
                pdf_undo(ctx, e->pdfdoc);
            }
            ok = true;
        }
        fz_catch(ctx) {
            fz_report_error(ctx);
            logf("EngineMupdfUndoRedo: pdf_%s() failed\n", redo ? StrL("redo") : StrL("undo"));
        }
    }
    if (!ok) {
        return false;
    }
    SyncPagesAfterUndoRedo(e, removedOut);
    return true;
}

fz_try(ctx) {
            if (redo) {
                pdf_redo(ctx, e->pdfdoc);
            } else {
                pdf_undo(ctx, e->pdfdoc);
            }
            ok = true;
        }

void EngineMupdfRefreshModifiedState(EngineBase* engine) {
    EngineMupdf* e = AsEngineMupdf(engine);
    if (!e || !e->pdfdoc) {
        return;
    }
    int pos = EngineMupdfUndoPos(e, nullptr);
    if (pos < 0) {
        return;
    }
    e->modifiedAnnotations = (pos != e->savedUndoPos);
}

void BeginPdfEditOperation(MainWindow* win, const char* name) {
    if (!win || win->pdfEditOperationActive) {
        return;
    }
    DisplayModel* dm = win->AsFixed();
    EngineBase* engine = dm ? dm->GetEngine() : nullptr;
    if (!engine || !EngineSupportsAnnotations(engine)) {
        return;
    }
    EngineMupdfBeginOperation(engine, name);
    win->pdfEditOperationActive = true;
}

void EndPdfEditOperation(MainWindow* win) {
    if (!win || !win->pdfEditOperationActive) {
        return;
    }
    win->pdfEditOperationActive = false;
    DisplayModel* dm = win->AsFixed();
    EngineBase* engine = dm ? dm->GetEngine() : nullptr;
    if (engine) {
        EngineMupdfEndOperation(engine);
    }
}

static void UndoRedoInTab(WindowTab* tab, bool redo) {
    if (!tab) {
        return;
    }
    MainWindow* win = tab->win;
    DisplayModel* dm = tab->AsFixed();
    if (!win || !dm) {
        return;
    }
    EngineBase* engine = dm->GetEngine();
    if (!engine || !EngineSupportsAnnotations(engine)) {
        return;
    }
    bool can = redo ? EngineMupdfCanRedo(engine) : EngineMupdfCanUndo(engine);
    if (!can) {
        return;
    }

    // an in-flight placement or drag would write to what we are about to undo
    CancelAnnotationPlacement(win);
    CancelDrag(win);
    SetSelectedAnnotation(tab, nullptr);
    if (gRenderCache) {
        gRenderCache->AbortRendering(dm);
    }

    Vec<Annotation*> removed;
    bool ok = redo ? EngineMupdfRedo(engine, removed) : EngineMupdfUndo(engine, removed);
    for (Annotation* a : removed) {
        DetachAnnotationFromUI(a);
        DeleteAnnotation(a);
    }
    // the wrapper deletes above mark the document modified; the journal knows better
    EngineMupdfRefreshModifiedState(engine);
    DeleteOldSelectionInfo(win, true);
    RefreshAnnotationLists(tab);
    NotifyAnnotationsChanged(tab);
    ToolbarUpdateStateForWindow(win, true);
    MainWindowRerender(win, true);
    if (!ok) {
        ShowWarningNotification(win->hwndCanvas, redo ? _TRA("Nothing to redo") : _TRA("Nothing to undo"),
                                kNotif5SecsTimeOut);
    }
}

bool CutAnnotation(Annotation* annot) {
    if (!CopyAnnotation(annot)) {
        return false;
    }
    gPendingCutAnnotation = annot;
    return true;
}

Annotation* TakeCutAnnotation() {
    Annotation* res = gPendingCutAnnotation;
    gPendingCutAnnotation = nullptr;
    return res;
}

bool EngineOwnsAnnotation(EngineBase* engine, Annotation* annot) {
    if (!engine || !annot) {
        return false;
    }
    return AsEngineMupdf(engine) == annot->engine;
}

static bool CopyOrCutAnnotationInTab(WindowTab* tab, LPARAM lp, bool cut) {
    if (!tab || !HasPermission(Perm::CopySelection)) {
        return false;
    }
    Annotation* annot = GetAnnotionUnderCursor(tab, nullptr, lp);
    bool ok = CopyAnnotationToClipboard(annot, cut);
    if (!ok) {
        ok = CopyAnnotationToClipboard(tab->selectedAnnotation, cut);
    }
    if (ok && cut && tab->win) {
        // a cut annotation stays on the page until the paste removes it, so
        // without this Ctrl+X looks like it did nothing
        NotificationCreateArgs args;
        args.hwndParent = tab->win->hwndCanvas;
        args.msg = _TRA("Annotation cut. Paste to move it.");
        args.timeoutMs = 3000;
        ShowNotification(args);
    }
    return ok;
}

static WindowTab* FindTabForAnnotation(Annotation* annot) {
    if (!annot) {
        return nullptr;
    }
    for (MainWindow* w : gWindows) {
        for (WindowTab* t : w->Tabs()) {
            DisplayModel* dm = t->AsFixed();
            EngineBase* engine = dm ? dm->GetEngine() : nullptr;
            if (EngineOwnsAnnotation(engine, annot)) {
                return t;
            }
        }
    }
    return nullptr;
}

static void DeleteCutAnnotationAfterPaste() {
    Annotation* cut = TakeCutAnnotation();
    WindowTab* tab = FindTabForAnnotation(cut);
    if (!tab) {
        return;
    }
    DeleteAnnotationAndUpdateUI(tab, cut);
}

static void GetInkList(Annotation* annot, Vec<int>& strokeCounts, Vec<PointF>& points) {
    strokeCounts.Reset();
    points.Reset();
    if (!AnnotationIsLive(annot) || annot->type != AnnotationType::Ink) {
        return;
    }
    EngineMupdf* e = annot->engine;
    auto* a = annot->pdfannot;
    auto* ctx = e->Ctx();
    ScopedRecursiveMutex cs(&e->docLock);
    fz_try(ctx) {
        int nStrokes = pdf_annot_ink_list_count(ctx, a);
        for (int i = 0; i < nStrokes; i++) {
            int nv = pdf_annot_ink_list_stroke_count(ctx, a, i);
            strokeCounts.Append(nv);
            for (int k = 0; k < nv; k++) {
                fz_point p = pdf_annot_ink_list_stroke_vertex(ctx, a, i, k);
                points.Append({p.x, p.y});
            }
        }
    }
    fz_catch(ctx) {
        fz_report_error(ctx);
        logf("GetInkList: pdf_annot_ink_list() failed\n");
        strokeCounts.Reset();
        points.Reset();
    }
}

fz_try(ctx) {
        int nStrokes = pdf_annot_ink_list_count(ctx, a);
        for (int i = 0; i < nStrokes; i++) {
            int nv = pdf_annot_ink_list_stroke_count(ctx, a, i);
            strokeCounts.Append(nv);
            for (int k = 0; k < nv; k++) {
                fz_point p = pdf_annot_ink_list_stroke_vertex(ctx, a, i, k);
                points.Append({p.x, p.y});
            }
        }
    }

fz_catch(ctx) {
        fz_report_error(ctx);
        logf("GetInkList: pdf_annot_ink_list() failed\n");
        strokeCounts.Reset();
        points.Reset();
    }

bool AnnotationCanBeCopied(AnnotationType tp) {
    switch (tp) {
        case AnnotationType::Text:
        case AnnotationType::FreeText:
        case AnnotationType::Line:
        case AnnotationType::Square:
        case AnnotationType::Circle:
        case AnnotationType::Polygon:
        case AnnotationType::PolyLine:
        case AnnotationType::Redact:
        case AnnotationType::Stamp:
        case AnnotationType::Caret:
        case AnnotationType::Ink:
            return true;
        default:
            return false;
    }
}

static void ClearAnnotationClipboard() {
    str::FreePtr(&gAnnotClipboard.contents);
    str::FreePtr(&gAnnotClipboard.iconName);
    str::FreePtr(&gAnnotClipboard.fontName);
    FreePixmap(gAnnotClipboard.stampImage);
    gAnnotClipboard.stampImage = nullptr;
    gAnnotClipboard.valid = false;
    gAnnotClipboard.type = AnnotationType::Unknown;
    gAnnotClipboard.rect = {};
    gAnnotClipboard.color = 0;
    gAnnotClipboard.hasColor = false;
    gAnnotClipboard.interiorColor = 0;
    gAnnotClipboard.hasInteriorColor = false;
    gAnnotClipboard.textColor = 0;
    gAnnotClipboard.hasTextColor = false;
    gAnnotClipboard.opacity = 255;
    gAnnotClipboard.borderWidth = -1;
    gAnnotClipboard.quadding = -1;
    gAnnotClipboard.textSize = -1;
    gAnnotClipboard.lineStartStyle = 0;
    gAnnotClipboard.lineEndStyle = 0;
    gAnnotClipboard.hasLine = false;
    gAnnotClipboard.lineStart = {};
    gAnnotClipboard.lineEnd = {};
    gAnnotClipboard.vertices.Reset();
    gAnnotClipboard.quads.Reset();
    gAnnotClipboard.inkStrokeCounts.Reset();
    gAnnotClipboard.inkPoints.Reset();
}

static Pixmap* PixmapFromRgbFzPixmap(fz_context* ctx, fz_pixmap* src) {
    if (!src || src->w <= 0 || src->h <= 0 || !src->samples) {
        return nullptr;
    }
    fz_pixmap* rgb = nullptr;
    fz_try(ctx) {
        rgb = fz_convert_pixmap(ctx, src, fz_device_rgb(ctx), nullptr, nullptr, fz_default_color_params, 1);
    }
    fz_catch(ctx) {
        fz_report_error(ctx);
        rgb = nullptr;
    }
    fz_pixmap* use = rgb ? rgb : src;
    int n = use->n;
    if (n < 3 || !use->samples) {
        fz_drop_pixmap(ctx, rgb);
        return nullptr;
    }
    Pixmap* p = AllocPixmap(use->w, use->h, PixmapFormat::RGBA8);
    if (!p) {
        fz_drop_pixmap(ctx, rgb);
        return nullptr;
    }
    p->xres = (float)use->xres;
    p->yres = (float)use->yres;
    p->hasAlpha = true;
    int alphaOff = use->alpha ? n - 1 : -1;
    for (int y = 0; y < use->h; y++) {
        const u8* s = use->samples + y * use->stride;
        u8* d = p->data + y * p->stride;
        for (int x = 0; x < use->w; x++) {
            d[0] = s[0];
            d[1] = s[1];
            d[2] = s[2];
            d[3] = alphaOff >= 0 ? s[alphaOff] : 255;
            s += n;
            d += 4;
        }
    }
    fz_drop_pixmap(ctx, rgb);
    return p;
}

static Pixmap* GetStampImage(Annotation* annot) {
    if (!AnnotationIsLive(annot) || annot->type != AnnotationType::Stamp) {
        return nullptr;
    }
    EngineMupdf* e = annot->engine;
    if (!e || !e->pdfdoc) {
        return nullptr;
    }
    auto* ctx = e->Ctx();
    ScopedRecursiveMutex cs(&e->docLock);
    fz_image* img = nullptr;
    fz_pixmap* pix = nullptr;
    fz_var(img);
    fz_var(pix);
    fz_try(ctx) {
        pdf_obj* obj = pdf_annot_stamp_image_obj(ctx, annot->pdfannot);
        if (obj) {
            img = pdf_load_image(ctx, e->pdfdoc, obj);
            if (img) {
                pix = fz_get_pixmap_from_image(ctx, img, nullptr, nullptr, nullptr, nullptr);
            }
        }
    }
    fz_always(ctx) {
        fz_drop_image(ctx, img);
    }
    fz_catch(ctx) {
        fz_report_error(ctx);
        fz_drop_pixmap(ctx, pix);
        pix = nullptr;
    }
    if (!pix) {
        return nullptr;
    }
    Pixmap* res = PixmapFromRgbFzPixmap(ctx, pix);
    fz_drop_pixmap(ctx, pix);
    return res;
}

fz_try(ctx) {
        pdf_obj* obj = pdf_annot_stamp_image_obj(ctx, annot->pdfannot);
        if (obj) {
            img = pdf_load_image(ctx, e->pdfdoc, obj);
            if (img) {
                pix = fz_get_pixmap_from_image(ctx, img, nullptr, nullptr, nullptr, nullptr);
            }
        }
    }

fz_catch(ctx) {
        fz_report_error(ctx);
        fz_drop_pixmap(ctx, pix);
        pix = nullptr;
    }

static RectF GetAnnotRect(Annotation* annot) {
    if (!AnnotationIsLive(annot)) {
        return annot ? annot->bounds : RectF{};
    }
    EngineMupdf* e = annot->engine;
    auto* ctx = e->Ctx();
    ScopedRecursiveMutex cs(&e->docLock);
    fz_rect rc = {};
    bool ok = true;
    fz_try(ctx) {
        rc = pdf_annot_rect(ctx, annot->pdfannot);
    }
    fz_catch(ctx) {
        fz_report_error(ctx);
        ok = false;
    }
    if (!ok) {
        return GetBounds(annot);
    }
    return ToRectF(rc);
}

bool CopyAnnotation(Annotation* annot) {
    if (!AnnotationIsLive(annot) || !AnnotationCanBeCopied(annot->type)) {
        return false;
    }
    ClearAnnotationClipboard();
    gAnnotClipboard.valid = true;
    gAnnotClipboard.type = annot->type;
    gAnnotClipboard.rect = GetAnnotRect(annot);
    gAnnotClipboard.contents = str::Dup(Contents(annot));
    gAnnotClipboard.iconName = str::Dup(IconName(annot));
    gAnnotClipboard.opacity = Opacity(annot);
    if (AnnotationSupportsBorder(annot->type)) {
        gAnnotClipboard.borderWidth = BorderWidth(annot);
    }
    if (annot->type == AnnotationType::FreeText) {
        gAnnotClipboard.quadding = Quadding(annot);
        gAnnotClipboard.textSize = DefaultAppearanceTextSize(annot);
        gAnnotClipboard.fontName = str::Dup(DefaultAppearanceTextFont(annot));
        gAnnotClipboard.textColor = DefaultAppearanceTextColor(annot);
        gAnnotClipboard.hasTextColor = true;
        gAnnotClipboard.color = GetColor(annot);
        gAnnotClipboard.hasColor = true;
    } else if (AnnotationSupportsColor(annot->type)) {
        gAnnotClipboard.color = GetColor(annot);
        gAnnotClipboard.hasColor = true;
    }
    if (AnnotationSupportsInteriorColor(annot->type)) {
        gAnnotClipboard.interiorColor = InteriorColor(annot);
        gAnnotClipboard.hasInteriorColor = true;
    }
    GetLineEndingStyles(annot, &gAnnotClipboard.lineStartStyle, &gAnnotClipboard.lineEndStyle);
    gAnnotClipboard.hasLine = GetLinePoints(annot, gAnnotClipboard.lineStart, gAnnotClipboard.lineEnd);
    gAnnotClipboard.vertices = GetVertices(annot);
    gAnnotClipboard.quads = GetQuadPointsAsRect(annot);
    GetInkList(annot, gAnnotClipboard.inkStrokeCounts, gAnnotClipboard.inkPoints);
    gAnnotClipboard.stampImage = GetStampImage(annot);
    return true;
}

static void OffsetPoints(Vec<PointF>& pts, float dx, float dy) {
    for (int i = 0; i < len(pts); i++) {
        pts[i].x += dx;
        pts[i].y += dy;
    }
}

static void OffsetRects(Vec<RectF>& rects, float dx, float dy) {
    for (int i = 0; i < len(rects); i++) {
        rects[i].x += dx;
        rects[i].y += dy;
    }
}

Annotation* PasteCopiedAnnotation(EngineBase* engine, int pageNo, PointF topLeft) {
    if (!gAnnotClipboard.valid || !engine) {
        return nullptr;
    }
    AnnotationClipboard& clip = gAnnotClipboard;
    float dx = topLeft.x - clip.rect.x;
    float dy = topLeft.y - clip.rect.y;
    RectF newRect{topLeft.x, topLeft.y, clip.rect.dx, clip.rect.dy};

    Vec<PointF> vertices = clip.vertices;
    OffsetPoints(vertices, dx, dy);
    Vec<PointF> inkPoints = clip.inkPoints;
    OffsetPoints(inkPoints, dx, dy);
    Vec<RectF> quads = clip.quads;
    OffsetRects(quads, dx, dy);

    AnnotCreateArgs args{clip.type};
    args.content = clip.contents;
    if (clip.type == AnnotationType::FreeText) {
        if (clip.hasTextColor) {
            args.col.parsedOk = true;
            args.col.pdfCol = clip.textColor;
        }
        if (clip.hasColor) {
            args.bgCol.parsedOk = true;
            args.bgCol.pdfCol = clip.color;
        }
        args.textSize = clip.textSize;
        args.borderWidth = clip.borderWidth;
        args.quadding = clip.quadding;
    } else if (clip.hasColor) {
        args.col.parsedOk = true;
        args.col.pdfCol = clip.color;
    }
    if (clip.hasInteriorColor) {
        args.interiorCol.parsedOk = true;
        args.interiorCol.pdfCol = clip.interiorColor;
    }
    args.stampImage = clip.stampImage;
    if (clip.hasLine) {
        args.hasLineEnd = true;
        args.lineEnd = {clip.lineEnd.x + dx, clip.lineEnd.y + dy};
    }
    if (len(vertices) >= 2) {
        args.polyLinePoints = &vertices;
    }
    if (len(clip.inkStrokeCounts) > 0) {
        args.inkStrokeCounts = &clip.inkStrokeCounts;
        args.inkPoints = &inkPoints;
    }
    bool useRect = clip.type == AnnotationType::Square || clip.type == AnnotationType::Circle ||
                   (clip.type == AnnotationType::Redact && len(quads) == 0);
    if (useRect) {
        args.hasRect = true;
        args.rect = newRect;
    }

    PointF pos = topLeft;
    if (clip.hasLine) {
        pos = {clip.lineStart.x + dx, clip.lineStart.y + dy};
    }
    Annotation* annot = EngineMupdfCreateAnnotation(engine, pageNo, pos, &args);
    if (!annot) {
        return nullptr;
    }
    if (clip.iconName) {
        SetIconName(annot, clip.iconName);
    }
    if (clip.fontName) {
        SetDefaultAppearanceTextFont(annot, clip.fontName);
    }
    if (clip.hasLine || clip.type == AnnotationType::PolyLine || clip.type == AnnotationType::Line) {
        SetLineStartStyles(annot, clip.lineStartStyle);
        SetLineEndStyles(annot, clip.lineEndStyle);
    }
    if (clip.type == AnnotationType::FreeText) {
        SetContents(annot, clip.contents);
        if (clip.hasTextColor) {
            SetDefaultAppearanceTextColor(annot, clip.textColor);
        }
        if (clip.textSize > 0) {
            SetDefaultAppearanceTextSize(annot, clip.textSize);
        }
        if (clip.quadding >= 0) {
            SetQuadding(annot, clip.quadding);
        }
    } else if (clip.contents) {
        SetContents(annot, clip.contents);
    }
    if (clip.opacity < 255) {
        SetOpacity(annot, clip.opacity);
    }
    if (AnnotationSupportsBorder(clip.type) && clip.borderWidth >= 0) {
        SetBorderWidth(annot, clip.borderWidth);
    }
    if (len(quads) > 0) {
        SetQuadPointsAsRect(annot, quads);
    }
    switch (clip.type) {
        case AnnotationType::Text:
        case AnnotationType::FreeText:
        case AnnotationType::Stamp:
        case AnnotationType::Caret:
        case AnnotationType::FileAttachment:
            SetRect(annot, newRect);
            break;
        default:
            break;
    }
    return annot;
}

static bool CopyFromFocusedEditControl() {
    HWND focus = GetFocus();
    if (!focus) {
        return false;
    }
    WCHAR cls[64];
    int n = GetClassNameW(focus, cls, dimof(cls));
    if (n <= 0) {
        return false;
    }
    if (!wstr::EqI(cls, WC_EDITW) && !wstr::EqI(cls, WC_COMBOBOX) && !wstr::EqI(cls, L"ComboLBox")) {
        return false;
    }
    SendMessageW(focus, WM_COPY, 0, 0);
    return true;
}

static bool CopyAnnotationToClipboard(Annotation* annot) {
    if (!CopyAnnotation(annot)) {
        return false;
    }
    Str contents = Contents(annot);
    if (!str::IsEmptyOrWhiteSpace(contents)) {
        CopyTextToClipboard(contents);
    }
    gAnnotClipboardSeqNo = GetClipboardSequenceNumber();
    return true;
}

static bool CopiedAnnotationIsFresh() {
    if (!HasCopiedAnnotation()) {
        return false;
    }
    return GetClipboardSequenceNumber() == gAnnotClipboardSeqNo;
}

static Annotation* TryPasteCopiedAnnotation(MainWindow* win, WindowTab* tab, DisplayModel* dm, LPARAM lp) {
    if (!HasCopiedAnnotation() || !win || !tab || !dm) {
        return nullptr;
    }
    EngineBase* engine = dm->GetEngine();
    if (!engine || !EngineSupportsAnnotations(engine)) {
        return nullptr;
    }
    Point pt = HwndGetCursorPos(win->hwndCanvas);
    if (lp != 0) {
        pt.x = GET_X_LPARAM(lp);
        pt.y = GET_Y_LPARAM(lp);
    }
    int pageNoUnderCursor = dm->GetPageNoByPoint(pt);
    if (pageNoUnderCursor < 0) {
        if (!SetPointToVisiblePage(dm, pt, pageNoUnderCursor)) {
            return nullptr;
        }
    }
    PointF ptOnPage = dm->CvtFromScreen(pt, pageNoUnderCursor);
    return PasteCopiedAnnotation(engine, pageNoUnderCursor, ptOnPage);
}

void siwx91x_on_join_work(struct k_work *work)
{
	struct siwx91x_dev *sidev = CONTAINER_OF(work, struct siwx91x_dev, on_join_work);

	if (sidev->state != WIFI_STATE_COMPLETED) {
		return;
