static GHashTable *_crawler_read_dir(const char *folder)
{
  GError *error = NULL;
  GDir *dir = g_dir_open(folder, 0, &error);
  if(!dir)
  {
    if(error) g_error_free(error);
    return NULL;
  }

  GHashTable *entries = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);
  const gchar *name;
  while((name = g_dir_read_name(dir)))
    g_hash_table_add(entries, g_strdup(name));

  g_dir_close(dir);
  return entries;
}

static GList *_crawler_scan_claimed_roll(const dt_filmid_t filmid,
                                         const gboolean take)
{
  int flags_changed = 0;
  GList *found = _crawler_run_filmroll(filmid, NULL, NULL,
                                       &_crawler_bg.abort, &flags_changed);

  g_mutex_lock(&_crawler_bg_lock);
  if(!take)
    _crawler_bg.conflicts = g_list_concat(_crawler_bg.conflicts, found);
  _crawler_bg.num_done++;
  _crawler_bg.scanning = FALSE;
  _crawler_bg.current = NO_FILMID;
  g_cond_broadcast(&_crawler_bg_cond);
  g_mutex_unlock(&_crawler_bg_lock);

  // the .txt/.wav flags are drawn as thumbnail overlays, so a change
  // needs to reach the screen.  this practically never fires.
  if(flags_changed) dt_control_queue_redraw_center();

  return take ? found : NULL;
}

static void _crawler_report(GList *found)
{
  if(!found) return;

  const guint count = g_list_length(found);
  dt_control_log(ngettext("%u updated XMP sidecar file found",
                          "%u updated XMP sidecar files found", count), count);
  _crawler_show_image_list(found, FALSE);
}

static void _crawler_examine(dt_crawler_item_t *item,
                             const gboolean look_for_xmp)
{
  // if the image is missing we ignore it.
  if(!g_file_test(item->image_path, G_FILE_TEST_EXISTS))
    item->missing = TRUE;
    return;
  // no need to look for xmp files if none get written anyway.
  if(look_for_xmp)
  {
    // construct the xmp filename for this image
    gchar xmp_path[PATH_MAX] = { 0 };
    g_strlcpy(xmp_path, item->image_path, sizeof(xmp_path));
    dt_image_path_append_version_no_db(item->version, xmp_path, sizeof(xmp_path));
    size_t len = strlen(xmp_path);
    if(len + 4 >= PATH_MAX) return;
    xmp_path[len++] = '.';
    xmp_path[len++] = 'x';
    xmp_path[len++] = 'm';
    xmp_path[len++] = 'p';
    xmp_path[len] = '\0';

    // on Windows the encoding might not be UTF8
    gchar *xmp_path_locale = dt_util_normalize_path(xmp_path);
    int stat_res = -1;
#ifdef _WIN32
    // UTF8 paths fail in this context, but converting to UTF16 works
    struct _stati64 statbuf;
    if(xmp_path_locale) // in Windows dt_util_normalize_path returns
                        // NULL if file does not exist
    {
      wchar_t *wfilename = g_utf8_to_utf16(xmp_path_locale, -1, NULL, NULL, NULL);
      stat_res = _wstati64(wfilename, &statbuf);
      g_free(wfilename);
    }
#else
    struct stat statbuf;
    stat_res = stat(xmp_path_locale, &statbuf);
#endif
    g_free(xmp_path_locale);
    if(stat_res) return; // TODO: shall we report these?
    // step 1: check if the xmp is newer than our db entry
    if(item->timestamp_db + MAX_TIME_SKEW < statbuf.st_mtime)
    {
      item->xmp_newer = TRUE;
      item->timestamp_xmp = statbuf.st_mtime;
      item->xmp_path = g_strdup(xmp_path);
    }
    // older timestamps are the case for all images after the db
    // upgrade. better not report these
  }

  // step 2: check if the image has associated files (.txt, .wav)
  size_t len = strlen(item->image_path);
  const char *c = item->image_path + len;
  while((c > item->image_path) && (*c != '.')) c--;
  len = c - item->image_path + 1;

  char *extra_path = calloc(len + 3 + 1, sizeof(char));
  if(extra_path)
  {
    g_strlcpy(extra_path, item->image_path, len + 1);

    extra_path[len] = 't';
    extra_path[len + 1] = 'x';
    extra_path[len + 2] = 't';
    gboolean has_txt = g_file_test(extra_path, G_FILE_TEST_EXISTS);

    if(!has_txt)
    {
      extra_path[len] = 'T';
      extra_path[len + 1] = 'X';
      extra_path[len + 2] = 'T';
      has_txt = g_file_test(extra_path, G_FILE_TEST_EXISTS);
    }

    extra_path[len] = 'w';
    extra_path[len + 1] = 'a';
    extra_path[len + 2] = 'v';
    gboolean has_wav = g_file_test(extra_path, G_FILE_TEST_EXISTS);

    if(!has_wav)
    {
      extra_path[len] = 'W';
      extra_path[len + 1] = 'A';
      extra_path[len + 2] = 'V';
      has_wav = g_file_test(extra_path, G_FILE_TEST_EXISTS);
    }

    // TODO: decide if we want to remove the flag for images that lost
    // their extra file. currently we do (the else cases)
    int new_flags = item->flags;
    if(has_txt)
      new_flags |= DT_IMAGE_HAS_TXT;
    else
      new_flags &= ~DT_IMAGE_HAS_TXT;
    if(has_wav)
      new_flags |= DT_IMAGE_HAS_WAV;
    else
      new_flags &= ~DT_IMAGE_HAS_WAV;
    item->new_flags = new_flags;

    free(extra_path);
  }
}

static gpointer _crawler_scan_thread(gpointer arg)
{
  dt_crawler_scan_t *scan = (dt_crawler_scan_t *)arg;

  while(!_crawler_aborted(scan))
  {
    const int idx = g_atomic_int_add(&scan->next, 1);
    if(idx >= scan->num_items) break;
    _crawler_examine(&scan->items[idx], scan->look_for_xmp);
    g_atomic_int_inc(&scan->completed);
  }
  return NULL;
}

static int _crawler_num_threads(void)
{
  int num_threads = dt_conf_get_int("crawler_threads");
  if(num_threads < 1) num_threads = DEFAULT_CRAWLER_THREADS;
  return MIN(num_threads, MAX_CRAWLER_THREADS);
}

static void _crawler_scan_items(dt_crawler_scan_t *scan,
                                const dt_crawler_progress_cb progress,
                                void *progress_data)
{
  if(scan->num_items <= 0) return;

  const int num_threads = MIN(_crawler_num_threads(), scan->num_items);
  double last_time = start_time - (FAST_UPDATE - 0.01);
  if(num_threads <= 1)
  {
    // serial path, kept so that crawler_threads=1 reproduces the
    // original behaviour exactly for comparison purposes
    for(int i = 0; i < scan->num_items && !_crawler_aborted(scan); i++)
    {
      _crawler_examine(&scan->items[i], scan->look_for_xmp);
      scan->completed = i + 1;

      const double curr_time = dt_get_wtime();
      if(progress
         && curr_time >= last_time + ((curr_time - start_time > 4.0)
                                      ? SLOW_UPDATE : FAST_UPDATE))
      {
        progress((i + 1) / (double)scan->num_items,
                 curr_time - start_time, progress_data);
        last_time = curr_time;
      }
    }
    return;
  }

  GThread **threads = calloc(num_threads, sizeof(GThread *));
  if(!threads)
  {
    // out of memory: fall back to examining everything inline
    for(int i = 0; i < scan->num_items; i++)
      _crawler_examine(&scan->items[i], scan->look_for_xmp);
    scan->completed = scan->num_items;
    return;
  }

  for(int t = 0; t < num_threads; t++)
    threads[t] = g_thread_new("crawler", _crawler_scan_thread, scan);

  // drive the progress display while the workers do the waiting
  while(g_atomic_int_get(&scan->completed) < scan->num_items
        && !_crawler_aborted(scan))
    if(progress
       && curr_time >= last_time + ((curr_time - start_time > 4.0)
                                    ? SLOW_UPDATE : FAST_UPDATE))
      progress(g_atomic_int_get(&scan->completed) / (double)scan->num_items,
               curr_time - start_time, progress_data);
    g_usleep(20000);
  }

static dt_crawler_item_t *_crawler_collect_items(const dt_filmid_t filmid,
                                                 int *num_items)
{
  sqlite3_stmt *stmt;
  int capacity = 1024;

  // reserve based on the number of images we expect to see
  // clang-format off
  if(dt_is_valid_filmid(filmid))
    DT_DEBUG_SQLITE3_PREPARE_V2(dt_database_get(darktable.db),
                                "SELECT COUNT(*) FROM main.images WHERE film_id = ?1",
                                -1, &stmt, 0);
  else
    DT_DEBUG_SQLITE3_PREPARE_V2(dt_database_get(darktable.db),
                                "SELECT COUNT(*) FROM main.images", -1, &stmt, 0);
  // clang-format on
  if(dt_is_valid_filmid(filmid)) DT_DEBUG_SQLITE3_BIND_INT(stmt, 1, filmid);
  if(sqlite3_step(stmt) == SQLITE_ROW)
    capacity = MAX(1, sqlite3_column_int(stmt, 0));
  sqlite3_finalize(stmt);

  dt_crawler_item_t *items = calloc(capacity, sizeof(dt_crawler_item_t));
  if(!items)
  {
    *num_items = 0;
    return NULL;
  }

  // clang-format off
  if(dt_is_valid_filmid(filmid))
    sqlite3_prepare_v2(dt_database_get(darktable.db),
                       "SELECT i.id, write_timestamp, version,"
                       "       folder || '" G_DIR_SEPARATOR_S "' || filename, flags"
                       " FROM main.images i, main.film_rolls f"
                       " ON i.film_id = f.id"
                       " WHERE f.id = ?1"
                       " ORDER BY f.id, filename",
                       -1, &stmt, NULL);
  else
    sqlite3_prepare_v2(dt_database_get(darktable.db),
                       "SELECT i.id, write_timestamp, version,"
                       "       folder || '" G_DIR_SEPARATOR_S "' || filename, flags"
                       " FROM main.images i, main.film_rolls f"
                       " ON i.film_id = f.id"
                       " ORDER BY f.id, filename",
                       -1, &stmt, NULL);
  // clang-format on
  if(dt_is_valid_filmid(filmid)) DT_DEBUG_SQLITE3_BIND_INT(stmt, 1, filmid);

  int count = 0;
  while(sqlite3_step(stmt) == SQLITE_ROW)
  {
    if(count >= capacity)
    {
      // the database changed underneath us, grow to fit
      const int new_capacity = capacity * 2;
      dt_crawler_item_t *grown =
        realloc(items, new_capacity * sizeof(dt_crawler_item_t));
      if(!grown) break;
      memset(grown + capacity, 0,
             (new_capacity - capacity) * sizeof(dt_crawler_item_t));
      items = grown;
      capacity = new_capacity;
    }

    dt_crawler_item_t *item = &items[count];
    item->id = sqlite3_column_int(stmt, 0);
    item->timestamp_db = sqlite3_column_int64(stmt, 1);
    item->version = sqlite3_column_int(stmt, 2);
    item->image_path = g_strdup((const char *)sqlite3_column_text(stmt, 3));
    item->flags = sqlite3_column_int(stmt, 4);
    item->new_flags = item->flags;
    if(!item->image_path) continue;
    count++;
  }
  sqlite3_finalize(stmt);

  *num_items = count;
  return items;
}

static void _crawler_free_items(dt_crawler_item_t *items,
                                const int num_items)
{
  for(int i = 0; i < num_items; i++)
  {
    g_free(items[i].image_path);
    g_free(items[i].xmp_path);
  }
  free(items);
}

static GList *_crawler_apply_results(dt_crawler_item_t *items,
                                     const int num_items,
                                     int *flags_changed)
{
  GList *result = NULL;
  sqlite3_stmt *inner_stmt;
  int changed = 0;

  sqlite3_prepare_v2(dt_database_get(darktable.db),
                     "UPDATE main.images SET flags = ?1 WHERE id = ?2", -1,
                     &inner_stmt, NULL);

  // let's wrap this into a transaction, it might make it a little faster.
  dt_database_start_transaction(darktable.db);

  for(int i = 0; i < num_items; i++)
  {
    dt_crawler_item_t *item = &items[i];
    if(item->missing)
      dt_print(DT_DEBUG_CONTROL, "[crawler] `%s' (id: %d) is missing",
               item->image_path, item->id);
    if(item->xmp_newer)
      dt_control_crawler_result_t *entry = malloc(sizeof(dt_control_crawler_result_t));
      if(entry)
        entry->id = item->id;
        entry->timestamp_xmp = item->timestamp_xmp;
        entry->timestamp_db = item->timestamp_db;
        entry->image_path = g_strdup(item->image_path);
        entry->xmp_path = g_strdup(item->xmp_path);
        result = g_list_prepend(result, entry);
                 "[crawler] `%s' (id: %d) is a newer XMP file",
                 item->xmp_path, item->id);
    if(item->new_flags != item->flags)
    {
      sqlite3_bind_int(inner_stmt, 1, item->new_flags);
      sqlite3_bind_int(inner_stmt, 2, item->id);
      sqlite3_step(inner_stmt);
      sqlite3_reset(inner_stmt);
      sqlite3_clear_bindings(inner_stmt);
      changed++;
    }
  }

  dt_database_release_transaction(darktable.db);
  sqlite3_finalize(inner_stmt);

  if(flags_changed) *flags_changed = changed;

  return g_list_reverse(result); // list was built in reverse order, so un-reverse it
}

static void _splash_progress(const double fraction,
                             const double elapsed,
                             void *data)
{
  dt_splash_screen_set_progress_percent(_("checking for updated sidecar files (%d%%)"),
                                        fraction, elapsed);
}

static GList *_crawler_run_filmroll(const dt_filmid_t filmid,
                                    const dt_crawler_progress_cb progress,
                                    void *progress_data,
                                    const gint *abort,
                                    int *flags_changed)
{
  dt_crawler_scan_t scan = { 0 };
  scan.look_for_xmp = dt_image_get_xmp_mode() != DT_WRITE_XMP_NEVER;
  scan.abort = abort;
  scan.items = _crawler_collect_items(filmid, &scan.num_items);
  if(!scan.items) return NULL;

  const double start_time = dt_get_wtime();
  _crawler_scan_items(&scan, progress, progress_data);
  const double scan_time = dt_get_wtime() - start_time;

  GList *result = _crawler_apply_results(scan.items, scan.num_items, flags_changed);
  _crawler_free_items(scan.items, scan.num_items);

  if(dt_is_valid_filmid(filmid))
    dt_print(DT_DEBUG_CONTROL,
             "[crawler] film roll %d: examined %d images in %.2fs,"
             " %d updated XMP files found",
             filmid, scan.num_items, scan_time, g_list_length(result));
  else
    dt_print(DT_DEBUG_CONTROL,
             "[crawler] examined %d images in %.2fs using %d threads,"
             " %d updated XMP files found",
             scan.num_items, scan_time,
             MIN(_crawler_num_threads(), MAX(scan.num_items, 1)),
             g_list_length(result));

  return result;
}

static void _crawler_free_result_full(gpointer data)
{
  dt_control_crawler_result_t *item = (dt_control_crawler_result_t *)data;
  _free_crawler_result(item);
  free(item);
}

static gboolean _crawler_bg_finished(gpointer data)
{
  GList *conflicts = (GList *)data;

  // nothing left to reprioritize
  DT_CONTROL_SIGNAL_DISCONNECT(_crawler_collection_changed, NULL);

  if(conflicts)
  {
    const guint count = g_list_length(conflicts);
    dt_control_log(ngettext("%u updated XMP sidecar file found",
                            "%u updated XMP sidecar files found", count), count);

    // shown non-modally: the crawl finishes long after startup, so this
    // must not interrupt whatever the user is currently doing
    _crawler_show_image_list(conflicts, FALSE);
  }
  return G_SOURCE_REMOVE;
}

static int32_t _crawler_bg_job_run(dt_job_t *job)
{
  dt_control_job_set_progress_message(job, "%s",
                                      _("checking for updated sidecar files"));

  while(TRUE)
  {
    g_mutex_lock(&_crawler_bg_lock);
    if(g_atomic_int_get(&_crawler_bg.abort) || !_crawler_bg.pending)
      g_mutex_unlock(&_crawler_bg_lock);
      break;
    }
    const dt_filmid_t filmid = GPOINTER_TO_INT(_crawler_bg.pending->data);
    _crawler_bg.pending = g_list_delete_link(_crawler_bg.pending,
                                             _crawler_bg.pending);
    g_mutex_unlock(&_crawler_bg_lock);

    int flags_changed = 0;
    GList *found = _crawler_run_filmroll(filmid, NULL, NULL,
                                         &_crawler_bg.abort, &flags_changed);

    g_mutex_lock(&_crawler_bg_lock);
    _crawler_bg.conflicts = g_list_concat(_crawler_bg.conflicts, found);
    _crawler_bg.num_done++;
    const double fraction =
      _crawler_bg.num_done / (double)MAX(_crawler_bg.num_rolls, 1);
    g_mutex_unlock(&_crawler_bg_lock);

    dt_control_job_set_progress(job, fraction);

    // the .txt/.wav flags are drawn as thumbnail overlays, so a change
    // needs to reach the screen.  this practically never fires.
    if(flags_changed) dt_control_queue_redraw_center();
  }

static dt_job_t *_crawler_bg_job_create(void)
{
  dt_job_t *job = dt_control_job_create(&_crawler_bg_job_run, "crawl for updated sidecar files");
  if(!job) return NULL;
  dt_control_job_set_params(job, NULL, NULL);
  return job;
}

void dt_control_crawler_start_background(void)
{
  if(!dt_conf_get_bool("run_crawler_on_start") || dt_gimpmode()) return;

  g_mutex_lock(&_crawler_bg_lock);
  if(_crawler_bg.running)
  {
    g_mutex_unlock(&_crawler_bg_lock);
    return;
  }

  // most recently opened film rolls first -- those are the ones the user
  // is most likely to look at in this session.  rolls that have never
  // been opened have a NULL access_timestamp and sort last.
  sqlite3_stmt *stmt;
  // clang-format off
  DT_DEBUG_SQLITE3_PREPARE_V2(dt_database_get(darktable.db),
                              "SELECT id FROM main.film_rolls"
                              " ORDER BY access_timestamp DESC, id DESC",
                              -1, &stmt, NULL);
  // clang-format on
  GList *rolls = NULL;
  while(sqlite3_step(stmt) == SQLITE_ROW)
    rolls = g_list_prepend(rolls, GINT_TO_POINTER(sqlite3_column_int(stmt, 0)));
  sqlite3_finalize(stmt);

  _crawler_bg.pending = g_list_reverse(rolls);
  _crawler_bg.num_rolls = g_list_length(_crawler_bg.pending);
  _crawler_bg.num_done = 0;
  _crawler_bg.conflicts = NULL;
  g_atomic_int_set(&_crawler_bg.abort, 0);
  _crawler_bg.running = _crawler_bg.num_rolls > 0;
  const gboolean start = _crawler_bg.running;
  const int num_rolls = _crawler_bg.num_rolls;
  g_mutex_unlock(&_crawler_bg_lock);

  if(!start) return;

  dt_print(DT_DEBUG_CONTROL,
           "[crawler] queued %d film rolls for background crawling", num_rolls);

  // follow the user around the library while the crawl runs
  DT_CONTROL_SIGNAL_CONNECT(DT_SIGNAL_COLLECTION_CHANGED,
                            _crawler_collection_changed, NULL);

  // the collection restored at startup was set up before the signal above
  // was connected, and it is the one the user is looking at right now
  _crawler_prioritize_current_collection();

  // note: dt_control_add_job() returns TRUE to report a *failure*
  if(dt_control_add_job(DT_JOB_QUEUE_SYSTEM_BG, _crawler_bg_job_create()))
  {
    // nothing will run, so do not leave the queue looking busy -- that
    // would make dt_control_crawler_stop() wait for a job that never was
    dt_print(DT_DEBUG_CONTROL, "[crawler] could not queue the background job");
    DT_CONTROL_SIGNAL_DISCONNECT(_crawler_collection_changed, NULL);
    g_mutex_lock(&_crawler_bg_lock);
    g_list_free(_crawler_bg.pending);
    _crawler_bg.pending = NULL;
    _crawler_bg.running = FALSE;
    g_mutex_unlock(&_crawler_bg_lock);
  }
}

static void _crawler_prioritize_current_collection(void)
{
  g_mutex_lock(&_crawler_bg_lock);
  const gboolean running = _crawler_bg.running;
  g_mutex_unlock(&_crawler_bg_lock);
  if(!running) return;
  GList *images = dt_collection_get_all(darktable.collection,
                                        CRAWLER_COLLECTION_SAMPLE);
  if(!images) return;

  // collect the distinct film rolls, keeping the order in which they
  // appear in the collection
  GList *rolls = NULL;
  int num_rolls = 0;
  sqlite3_stmt *stmt;
  // clang-format off
  DT_DEBUG_SQLITE3_PREPARE_V2(dt_database_get(darktable.db),
                              "SELECT film_id FROM main.images WHERE id = ?1",
                              -1, &stmt, NULL);
  // clang-format on
  for(GList *iter = images;
      iter && num_rolls < CRAWLER_COLLECTION_ROLLS;
      iter = g_list_next(iter))
  {
    DT_DEBUG_SQLITE3_BIND_INT(stmt, 1, GPOINTER_TO_INT(iter->data));
    if(sqlite3_step(stmt) == SQLITE_ROW)
    {
      gpointer filmid = GINT_TO_POINTER(sqlite3_column_int(stmt, 0));
      if(!g_list_find(rolls, filmid))
      {
        rolls = g_list_prepend(rolls, filmid);
        num_rolls++;
      }
    }
    sqlite3_reset(stmt);
    sqlite3_clear_bindings(stmt);
  }
  g_list_free(images);
  // `rolls' is in reverse order of appearance, and each call puts its
  // film roll at the head, so this leaves the first film roll of the
  // collection at the very front of the queue
  for(GList *iter = rolls; iter; iter = g_list_next(iter))
    dt_control_crawler_prioritize_filmroll(GPOINTER_TO_INT(iter->data));

  g_list_free(rolls);
}

static void _crawler_collection_changed(gpointer instance,
                                        dt_collection_change_t query_change,
                                        dt_collection_properties_t changed_property,
                                        gpointer imgs,
                                        const int next,
                                        gpointer user_data)
{
  _crawler_prioritize_current_collection();
}

static void _crawler_show_image_list(GList *images, const gboolean modal)
     GTK_DIALOG_DESTROY_WITH_PARENT | (modal ? GTK_DIALOG_MODAL : 0), _("_close"),
void dt_control_crawler_show_image_list(GList *images)
{
  // the synchronous startup crawl blocks the ui anyway, so keep it modal
  _crawler_show_image_list(images, TRUE);
}

void
InitializeCitusBackgroundWorker(BackgroundWorker *worker,
								const CitusBackgroundWorkerConfig *config)
{
	Assert(worker != NULL);
	Assert(config != NULL);
	Assert(config->workerName != NULL);
	Assert(config->functionName != NULL);

	/* Initialize the worker structure */
	memset(worker, 0, sizeof(BackgroundWorker));

	/* Set worker name */
	strcpy_s(worker->bgw_name, sizeof(worker->bgw_name), config->workerName);

	/* Set worker type if provided */
	if (config->workerType != NULL)
	{
		strcpy_s(worker->bgw_type, sizeof(worker->bgw_type), config->workerType);
	}

	/* Set standard flags for Citus workers */
	worker->bgw_flags = BGWORKER_SHMEM_ACCESS | BGWORKER_BACKEND_DATABASE_CONNECTION;

	/* Set start time - use custom start time if provided, otherwise use default */
	worker->bgw_start_time = (config->startTime != 0) ? config->startTime :
							 CITUS_BGW_DEFAULT_START_TIME;

	/* Set restart behavior */
	worker->bgw_restart_time = config->restartTime;

	/* Set library and function names */
	strcpy_s(worker->bgw_library_name, sizeof(worker->bgw_library_name), "citus");
	strcpy_s(worker->bgw_function_name, sizeof(worker->bgw_function_name),
			 config->functionName);

	/* Set main argument */
	worker->bgw_main_arg = config->mainArg;

	/* Set extension owner if provided */
	if (OidIsValid(config->extensionOwner))
	{
		memcpy_s(worker->bgw_extra, sizeof(worker->bgw_extra),
				 &config->extensionOwner, sizeof(Oid));
	}

	/* Set additional extra data if provided */
	if (config->extraData != NULL && config->extraDataSize > 0)
	{
		size_t remainingSpace = sizeof(worker->bgw_extra);
		size_t usedSpace = OidIsValid(config->extensionOwner) ? sizeof(Oid) : 0;

		if (usedSpace + config->extraDataSize <= remainingSpace)
		{
			memcpy_s(((char *) worker->bgw_extra) + usedSpace,
					 remainingSpace - usedSpace,
					 config->extraData,
					 config->extraDataSize);
		}
	}

	/* Set notification PID if needed */
	if (config->needsNotification)
	{
		worker->bgw_notify_pid = MyProcPid;
	}
}

BackgroundWorkerHandle *
RegisterCitusBackgroundWorker(const CitusBackgroundWorkerConfig *config)
{
	BackgroundWorker worker;
	BackgroundWorkerHandle *handle = NULL;

	/* Initialize the worker structure */
	InitializeCitusBackgroundWorker(&worker, config);

	/* Register the background worker */
	if (!RegisterDynamicBackgroundWorker(&worker, &handle))
	{
		return NULL;
	}

	/* Wait for startup if requested */
	if (config->waitForStartup && handle != NULL)
	{
		pid_t pid = 0;
		WaitForBackgroundWorkerStartup(handle, &pid);
	}

	return handle;
}

static void tty_ptmx_buffer_bounds_tc(void)
{
    /* Simulate the allocation and snprintf call from lwp_ptmx_init(). */
    struct
    {
        const char *root_path;
        int         should_fit; /* 1 = expect no truncation */
    } cases[] = {
        { "/dev",                          1 },
        { "/dev/pts",                      1 },
        { "/",                             1 },
        /* Oversized: root alone is longer than reasonable device name */
        { "/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", 0 },
    };

    for (rt_size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
    {
        const char *root_path   = cases[i].root_path;
        rt_size_t   root_len    = strlen(root_path);
        rt_size_t   buf_size    = root_len + sizeof(DEV_REL_PATH); /* mirrors kernel alloc */

        /* Allocate one extra byte as a canary to detect overflow. */
        char *raw = (char *)rt_malloc(buf_size + 1);
        uassert_not_null(raw);

        raw[buf_size] = (char)CANARY;

        int written = snprintf(raw, buf_size, "%s%s", root_path, DEV_REL_PATH);

        /* Canary must be intact regardless of input size. */
        uassert_int_equal((unsigned char)raw[buf_size], CANARY);

        if (cases[i].should_fit)
        {
            /* snprintf returns number of chars that would be written (excl. NUL). */
            uassert_true(written >= 0 && (rt_size_t)written < buf_size);
            /* Result must be null-terminated. */
            uassert_int_equal(raw[written], '\0');
        }

        rt_free(raw);
    }
}

static void cancel_qpack_blocked_stream(struct st_h2o_http3_server_stream_t *stream)
{
    if (!stream->qpack_blocked)
        return;
    stream->qpack_blocked = 0;
    h2o_qpack_decoder_cancel_stream(get_conn(stream)->h3.qpack.dec, stream->quic->stream_id);
    h2o_http3_send_qpack_stream_cancel(&get_conn(stream)->h3, stream->quic->stream_id);
}

static h2o_iovec_t log_qpack_blocked(h2o_req_t *_req)
{
    struct st_h2o_http3_server_stream_t *stream = H2O_STRUCT_FROM_MEMBER(struct st_h2o_http3_server_stream_t, req, _req);
    return stream->qpack_blocked_ever ? h2o_iovec_init(H2O_STRLIT("1")) : h2o_iovec_init(H2O_STRLIT("0"));
}

static void handle_qpack_unblocked_streams(h2o_http3_conn_t *_conn, const int64_t *stream_ids, size_t num_streams)
{
    struct st_h2o_http3_server_conn_t *conn = H2O_STRUCT_FROM_MEMBER(struct st_h2o_http3_server_conn_t, h3, _conn);

    for (size_t i = 0; i != num_streams; ++i) {
        quicly_stream_t *qs = quicly_get_stream(conn->h3.super.quic, stream_ids[i]);
        if (qs == NULL || qs->data == NULL)
            continue;
        struct st_h2o_http3_server_stream_t *stream = qs->data;
        if (!stream->qpack_blocked)
            continue;
        stream->qpack_blocked = 0;
        handle_buffered_input(stream, 0);
    }
}

static int decoder_is_blocked(h2o_qpack_decoder_t *qpack, int64_t stream_id)
{
    for (size_t i = qpack->blocked_streams.num_unblocked; i != qpack->blocked_streams.list.size; ++i)
        if (qpack->blocked_streams.list.entries[i].stream_id == stream_id)
            return 1;
    return 0;
}

static size_t decoder_num_blocked(h2o_qpack_decoder_t *qpack)
{
    assert(qpack->blocked_streams.num_unblocked <= qpack->blocked_streams.list.size);
    return qpack->blocked_streams.list.size - qpack->blocked_streams.num_unblocked;
}

void h2o_qpack_decoder_cancel_stream(h2o_qpack_decoder_t *qpack, int64_t stream_id)
{
    size_t src, dst = 0;

    for (src = 0; src != qpack->blocked_streams.list.size; ++src) {
        if (qpack->blocked_streams.list.entries[src].stream_id == stream_id) {
            if (src < qpack->blocked_streams.num_unblocked)
                --qpack->blocked_streams.num_unblocked;
            continue;
        }
        if (dst != src)
            qpack->blocked_streams.list.entries[dst] = qpack->blocked_streams.list.entries[src];
        ++dst;
    }
    qpack->blocked_streams.list.size = dst;
}

static void test_decode_edge_cases(void)
{
    note("partial encoder stream instruction");
    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(4096, 10);
        int64_t *unblocked_stream_ids;
        size_t num_unblocked;
        static const uint8_t input[] = {
            0xc0, 5, 'a', /* Insert With Name Reference, Static Table, Index=0, partial value */
        };
        const uint8_t *src = input;
        const char *err_desc = NULL;
        int ret = h2o_qpack_decoder_handle_input(dec, &unblocked_stream_ids, &num_unblocked, &src, input + sizeof(input),
                                                 &err_desc);
        ok(ret == 0);
        ok(err_desc == NULL);
        ok(src == input);
        ok(num_unblocked == 0);
        h2o_qpack_destroy_decoder(dec);
    }

    note("dynamic table exact-capacity insertion and eviction");
    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(42, 10);
        static const uint8_t input[] = {
            0x3f, 0x0b, /* Set Dynamic Table Capacity=42 */
            0xc0, 0,    /* Insert :authority with empty value; size = 10 + 0 + 32 */
            0xc0, 0,    /* Insert another exact-size entry, evicting the first */
        };
        feed_encoder_stream(dec, input, sizeof(input));
        ok(dec->table.num_bytes == 42);
        ok(dec->table.last - dec->table.first == 1);
        ok(dec->table.base_offset == 2);
        h2o_qpack_destroy_decoder(dec);
    }

    note("required insert count reconstruction across full range");
    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(32, 10);
        struct st_h2o_qpack_decode_header_ctx_t ctx;
        static const uint8_t input[] = {1, 0}; /* MaxEntries=1, FullRange=2, reconstructed RIC=2 */
        const uint8_t *src = input;

        dec->total_inserts = 2;
        dec->table.base_offset = 3;

        ok(parse_decode_context(dec, &ctx, 0, &src, input + sizeof(input)) == 0);
        ok(ctx.req_insert_count == 2);
        ok(ctx.base_index == 2);
        ok(src == input + sizeof(input));
        h2o_qpack_destroy_decoder(dec);
    }

    note("blocked stream limit boundary");
    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(4096, 1);
        struct st_h2o_qpack_decode_header_ctx_t ctx;
        static const uint8_t input[] = {2, 0}; /* RIC=1, Base=1, blocked until first insert arrives */
        const uint8_t *src = input;

        ok(parse_decode_context(dec, &ctx, 0, &src, input + sizeof(input)) == H2O_HTTP3_ERROR_INCOMPLETE);
        ok(dec->blocked_streams.list.size == 1);
        ok(dec->blocked_streams.list.entries[0].stream_id == 0);
        ok(dec->blocked_streams.list.entries[0].largest_ref == 1);
        h2o_qpack_destroy_decoder(dec);
    }
}

static void do_test_decoder_stream_error(h2o_qpack_decoder_t *dec, h2o_iovec_t input, const char *expected_err_desc)
{
    int64_t *unblocked_stream_ids;
    size_t num_unblocked;
    const uint8_t *src = (const uint8_t *)input.base, *src_end = src + input.len;
    const char *err_desc = NULL;
    int ret = h2o_qpack_decoder_handle_input(dec, &unblocked_stream_ids, &num_unblocked, &src, src_end, &err_desc);

    ok(ret == H2O_HTTP3_ERROR_QPACK_DECOMPRESSION_FAILED);
    ok(err_desc == expected_err_desc);
}

static void do_test_decode_context_error(h2o_qpack_decoder_t *dec, h2o_iovec_t input)
{
    struct st_h2o_qpack_decode_header_ctx_t ctx;
    const uint8_t *src = (const uint8_t *)input.base, *src_end = src + input.len;

    ok(parse_decode_context(dec, &ctx, 0, &src, src_end) == H2O_HTTP3_ERROR_QPACK_DECOMPRESSION_FAILED);
}

static void do_test_decode_header_error(h2o_qpack_decoder_t *dec, h2o_iovec_t input, const char *expected_err_desc)
{
    h2o_mem_pool_t pool;
    struct st_h2o_qpack_decode_header_ctx_t ctx;
    h2o_iovec_t *name = NULL, value = {};
    const uint8_t *src = (const uint8_t *)input.base, *src_end = src + input.len;
    const char *err_desc = NULL;

    h2o_mem_init_pool(&pool);

    ok(parse_decode_context(dec, &ctx, 0, &src, src_end) == 0);
    ok(decode_header(&pool, &ctx, &name, &value, &src, src_end, &err_desc) == H2O_HTTP3_ERROR_QPACK_DECOMPRESSION_FAILED);
    ok(err_desc == expected_err_desc);

    h2o_mem_clear_pool(&pool);
}

static void test_decode_errors(void)
{
    note("encoder stream errors");
    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(31, 10);
        /* RFC 9204 Section 4.3.1: capacity greater than the decoder's maximum dynamic table capacity is invalid. */
        static const uint8_t input[] = {0x3f, 0x01}; /* Set Dynamic Table Capacity=32 */
        do_test_decoder_stream_error(dec, h2o_iovec_init(input, sizeof(input)), h2o_qpack_err_invalid_max_size);
        h2o_qpack_destroy_decoder(dec);
    }

    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(4096, 10);
        /* RFC 9204 Appendix A defines static table indices 0..98; Section 3.1 forbids invalid static indices. */
        static const uint8_t input[] = {0xff, 0x24, 0}; /* Insert With Name Reference, Static Table, Index=99 */
        do_test_decoder_stream_error(dec, h2o_iovec_init(input, sizeof(input)), h2o_qpack_err_invalid_static_reference);
        h2o_qpack_destroy_decoder(dec);
    }

    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(4096, 10);
        /* RFC 9204 Section 2.2.3: an encoder-stream reference to an evicted dynamic entry is invalid. */
        static const uint8_t input[] = {0x80, 0}; /* Insert With Name Reference, Dynamic Table, Index=0 */
        do_test_decoder_stream_error(dec, h2o_iovec_init(input, sizeof(input)), h2o_qpack_err_invalid_dynamic_reference);
        h2o_qpack_destroy_decoder(dec);
    }

    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(4096, 10);
        /* RFC 9204 Section 4.3.4 duplicates an existing entry; index 0 is invalid when the table is empty. */
        static const uint8_t input[] = {0}; /* Duplicate, Relative Index=0 */
        do_test_decoder_stream_error(dec, h2o_iovec_init(input, sizeof(input)), h2o_qpack_err_invalid_duplicate);
        h2o_qpack_destroy_decoder(dec);
    }

    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(40, 10);
        /*
         * RFC 9204 Section 3.2.1: entry size is name length + value length + 32.
         * Section 3.2.2: adding an entry larger than the dynamic table capacity is invalid.
         */
        static const uint8_t input[] = {
            0x3f, 0x09, /* Set Dynamic Table Capacity=40 */
            0xc0, 9,    't', 'o', 'o', '-', 'l', 'a', 'r', 'g', 'e', /* :authority value; 10 + 9 + 32 > 40 */
        };
        do_test_decoder_stream_error(dec, h2o_iovec_init(input, sizeof(input)), h2o_qpack_err_header_exceeds_table_size);
        h2o_qpack_destroy_decoder(dec);
    }

    note("field section prefix errors");
    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(32, 10);
        /* RFC 9204 Section 4.5.1.1: EncodedInsertCount greater than FullRange=2*MaxEntries is invalid. */
        static const uint8_t input[] = {3, 0}; /* MaxEntries=1, FullRange=2, EncodedInsertCount=3 */
        do_test_decode_context_error(dec, h2o_iovec_init(input, sizeof(input)));
        h2o_qpack_destroy_decoder(dec);
    }

    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(4096, 10);
        /* RFC 9204 Section 4.5.1.2: Base MUST NOT be negative; RIC <= DeltaBase with Sign=1 is invalid. */
        static const uint8_t input[] = {0, 0x80}; /* negative Base */
        do_test_decode_context_error(dec, h2o_iovec_init(input, sizeof(input)));
        h2o_qpack_destroy_decoder(dec);
    }

    note("field line reference errors");
    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(4096, 10);
        /* RFC 9204 Appendix A defines static table indices 0..98; Section 3.1 forbids invalid static indices. */
        static const uint8_t input[] = {
            0,    0,      /* Required Insert Count=0, Base=0 */
            0xff, 0x24,   /* Indexed Field Line, Static Table, Index=99 */
        };
        do_test_decode_header_error(dec, h2o_iovec_init(input, sizeof(input)), h2o_qpack_err_invalid_static_reference);
        h2o_qpack_destroy_decoder(dec);
    }

    {
        h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(4096, 10);
        /* RFC 9204 Section 2.2.3 forbids dynamic references with absolute index >= Required Insert Count. */
        static const uint8_t input[] = {
            0,    1,      /* Required Insert Count=0, Base=1 */
            0x80,         /* Indexed Field Line, Dynamic Table, Relative Index=0 */
        };
        do_test_decode_header_error(dec, h2o_iovec_init(input, sizeof(input)), h2o_qpack_err_invalid_dynamic_reference);
        h2o_qpack_destroy_decoder(dec);
    }
}

static void feed_encoder_stream(h2o_qpack_decoder_t *dec, const uint8_t *input, size_t len)
{
    int64_t *unblocked_stream_ids;
    size_t num_unblocked;
    const uint8_t *p = input;
    const char *err_desc = NULL;
    int ret = h2o_qpack_decoder_handle_input(dec, &unblocked_stream_ids, &num_unblocked, &p, p + len, &err_desc);

    ok(ret == 0);
    ok(err_desc == NULL);
    ok(p == input + len);
    ok(num_unblocked == 0);
}

static void do_test_decode_field_section(h2o_qpack_decoder_t *dec, int64_t stream_id, h2o_iovec_t input,
                                         const h2o_header_t *expected_headers, size_t expected_num_headers,
                                         h2o_iovec_t expected_header_ack)
{
    h2o_mem_pool_t pool;
    struct st_h2o_qpack_decode_header_ctx_t ctx;
    const uint8_t *src = (const uint8_t *)input.base, *src_end = src + input.len;
    const char *err_desc = NULL;
    uint8_t header_ack[H2O_HPACK_ENCODE_INT_MAX_LENGTH];

    h2o_mem_init_pool(&pool);

    ok(parse_decode_context(dec, &ctx, stream_id, &src, src_end) == 0);
    for (size_t i = 0; i < expected_num_headers; ++i) {
        h2o_iovec_t *name = NULL, value = {};
        ok(decode_header(&pool, &ctx, &name, &value, &src, src_end, &err_desc) == 0);
        ok(err_desc == NULL);
        ok(h2o_iovec_is_token(name) == h2o_iovec_is_token(expected_headers[i].name));
        ok(h2o_memis(name->base, name->len, expected_headers[i].name->base, expected_headers[i].name->len));
        ok(h2o_memis(value.base, value.len, expected_headers[i].value.base, expected_headers[i].value.len));
    }
    ok(src == src_end);

    size_t header_ack_len = send_header_ack(dec, &ctx, header_ack, stream_id);
    ok(h2o_memis(header_ack, header_ack_len, expected_header_ack.base, expected_header_ack.len));

    h2o_mem_clear_pool(&pool);
}

static void test_rfc9204_appendix_b(void)
{
    h2o_qpack_decoder_t *dec = h2o_qpack_create_decoder(220, 10);

    note("B.1. Literal Field Line with Name Reference");
    {
        static const uint8_t input[] = {
            0x00, 0x00,                                                 /* Required Insert Count = 0, Base = 0 */
            0x51, 0x0b, '/',  'i',  'n',  'd',  'e', 'x', '.', 'h', 't', 'm', 'l' /* :path=/index.html */
        };
        static const h2o_header_t expected[] = {
            {.name = &H2O_TOKEN_PATH->buf, .value = {H2O_STRLIT("/index.html")}},
        };
        do_test_decode_field_section(dec, 0, h2o_iovec_init(input, sizeof(input)), expected, PTLS_ELEMENTSOF(expected),
                                     h2o_iovec_init(NULL, 0));
    }

    note("B.2. Dynamic Table");
    {
        static const uint8_t encoder[] = {
            0x3f, 0xbd, 0x01,                                           /* Set Dynamic Table Capacity=220 */
            0xc0, 0x0f, 'w',  'w',  'w',  '.',  'e',  'x', 'a', 'm', 'p',
            'l',  'e',  '.',  'c',  'o',  'm',                          /* :authority=www.example.com */
            0xc1, 0x0c, '/',  's',  'a',  'm',  'p',  'l', 'e', '/', 'p',
            'a',  't',  'h'                                             /* :path=/sample/path */
        };
        static const uint8_t input[] = {
            0x03, 0x81,                                                 /* Required Insert Count = 2, Base = 0 */
            0x10,                                                       /* :authority=www.example.com */
            0x11,                                                       /* :path=/sample/path */
        };
        static const h2o_header_t expected[] = {
            {.name = &H2O_TOKEN_AUTHORITY->buf, .value = {H2O_STRLIT("www.example.com")}},
            {.name = &H2O_TOKEN_PATH->buf, .value = {H2O_STRLIT("/sample/path")}},
        };
        static const uint8_t expected_ack[] = {0x84};
        feed_encoder_stream(dec, encoder, sizeof(encoder));
        do_test_decode_field_section(dec, 4, h2o_iovec_init(input, sizeof(input)), expected, PTLS_ELEMENTSOF(expected),
                                     h2o_iovec_init(expected_ack, sizeof(expected_ack)));
        dec->insert_count = 0; /* The Section Acknowledgment above implies receipt of the referenced inserts. */
    }

    note("B.3. Speculative Insert");
    {
        static const uint8_t encoder[] = {
            0x4a, 'c', 'u', 's', 't', 'o', 'm', '-', 'k', 'e', 'y',
            0x0c, 'c', 'u', 's', 't', 'o', 'm', '-', 'v', 'a', 'l', 'u', 'e',
        };
        static const uint8_t expected_state_sync[] = {0x01};
        uint8_t state_sync[H2O_HPACK_ENCODE_INT_MAX_LENGTH];
        feed_encoder_stream(dec, encoder, sizeof(encoder));
        size_t state_sync_len = h2o_qpack_decoder_send_state_sync(dec, state_sync);
        ok(h2o_memis(state_sync, state_sync_len, expected_state_sync, sizeof(expected_state_sync)));
    }

    note("B.4. Duplicate Instruction, Stream Cancellation");
    {
        static const uint8_t encoder[] = {0x02}; /* Duplicate (Relative Index = 2) */
        static const uint8_t expected_cancel[] = {0x48};
        uint8_t cancel[H2O_HPACK_ENCODE_INT_MAX_LENGTH];
        feed_encoder_stream(dec, encoder, sizeof(encoder));
        ok(dec->table.last - dec->table.first == 4);
        ok(h2o_memis(dec->table.first[3]->name->base, dec->table.first[3]->name->len, H2O_STRLIT(":authority")));
        ok(h2o_memis(dec->table.first[3]->value, dec->table.first[3]->value_len, H2O_STRLIT("www.example.com")));
        size_t cancel_len = h2o_qpack_decoder_send_stream_cancel(dec, cancel, 8);
        ok(h2o_memis(cancel, cancel_len, expected_cancel, sizeof(expected_cancel)));
    }

    note("B.5. Dynamic Table Insert, Eviction");
    {
        static const uint8_t encoder[] = {
            0x81, 0x0d, 'c', 'u', 's', 't', 'o', 'm', '-', 'v', 'a', 'l', 'u', 'e', '2',
        };
        feed_encoder_stream(dec, encoder, sizeof(encoder));
        ok(dec->table.num_bytes == 215);
        ok(dec->table.last - dec->table.first == 4);
        ok(h2o_memis(dec->table.first[0]->name->base, dec->table.first[0]->name->len, H2O_STRLIT(":path")));
        ok(h2o_memis(dec->table.first[0]->value, dec->table.first[0]->value_len, H2O_STRLIT("/sample/path")));
        ok(h2o_memis(dec->table.first[3]->name->base, dec->table.first[3]->name->len, H2O_STRLIT("custom-key")));
        ok(h2o_memis(dec->table.first[3]->value, dec->table.first[3]->value_len, H2O_STRLIT("custom-value2")));
    }

    h2o_qpack_destroy_decoder(dec);
}

static int decode_header_block(h2o_qpack_decoder_t *dec, h2o_mem_pool_t *pool, FILE *outp, uint64_t stream_id, const uint8_t *buf,
                               size_t chunk_size, int is_resp)
{
    int ret;

    if (!is_resp) {
        /* request */
        h2o_iovec_t method = {NULL}, authority = {NULL}, path = {NULL}, protocol = {NULL}, expect = {NULL},
                    datagram_flow_id = {NULL};
        const h2o_url_scheme_t *scheme = NULL;
        h2o_headers_t headers = {NULL};
        int pseudo_header_exists_map = 0;
        size_t content_length = SIZE_MAX, header_ack_len, i;
        uint8_t header_ack[H2O_HPACK_ENCODE_INT_MAX_LENGTH];
        const char *err_desc = NULL;
        if ((ret = h2o_qpack_parse_request(pool, dec, stream_id, &method, &scheme, &authority, &path, &protocol, &headers,
                                           &pseudo_header_exists_map, &content_length, &expect, NULL, &datagram_flow_id, header_ack,
                                           &header_ack_len, buf, chunk_size, &err_desc)) != 0) {
            if (ret == H2O_HTTP3_ERROR_INCOMPLETE)
                return ret;
            fprintf(stderr, "failed to decode stream %" PRIu64 ":%s\n", stream_id, err_desc);
            return ret;
        }
#define REQUIRED_PSEUDO_HEADERS                                                                                                    \
    (H2O_HPACK_PARSE_HEADERS_METHOD_EXISTS | H2O_HPACK_PARSE_HEADERS_SCHEME_EXISTS | H2O_HPACK_PARSE_HEADERS_AUTHORITY_EXISTS |    \
     H2O_HPACK_PARSE_HEADERS_PATH_EXISTS)
        if ((pseudo_header_exists_map & REQUIRED_PSEUDO_HEADERS) != REQUIRED_PSEUDO_HEADERS) {
            fprintf(stderr, "some of the required pseudo headers are missing in stream id %" PRIu64 "\n", stream_id);
            return H2O_HTTP3_ERROR_QPACK_DECOMPRESSION_FAILED;
        }
#undef REQUIRED_PSEUDO_HEADERS
        fprintf(outp, "#stream\t%" PRIu64 "\n:method\t%.*s\n:scheme\t%.*s\n:authority\t%.*s\n:path\t%.*s\n", stream_id,
                (int)method.len, method.base, (int)scheme->name.len, scheme->name.base, (int)authority.len, authority.base,
                (int)path.len, path.base);
        if (protocol.base != NULL)
            fprintf(outp, ":protocol\t%.*s\n", (int)protocol.len, protocol.base);
        if (content_length != SIZE_MAX)
            fprintf(outp, "content-length\t%zu\n", content_length);
        if (datagram_flow_id.base != NULL)
            fprintf(outp, "datagram-flow-id\t%.*s\n", (int)datagram_flow_id.len, datagram_flow_id.base);
        for (i = 0; i != headers.size; ++i) {
            const h2o_header_t *header = headers.entries + i;
            fprintf(outp, "%.*s\t%.*s\n", (int)header->name->len, header->name->base, (int)header->value.len, header->value.base);
        }
        fputc('\n', outp);
    } else {
        /* response */
        int status;
        h2o_headers_t headers = {NULL};
        h2o_iovec_t datagram_flow_id = {NULL};
        uint8_t header_ack[H2O_HPACK_ENCODE_INT_MAX_LENGTH];
        size_t header_ack_len, i;
        const char *err_desc = NULL;
        if ((ret = h2o_qpack_parse_response(pool, dec, stream_id, &status, &headers, &datagram_flow_id, header_ack, &header_ack_len,
                                            buf, chunk_size, &err_desc)) != 0) {
            if (ret == H2O_HTTP3_ERROR_INCOMPLETE)
                return ret;
            fprintf(stderr, "failed to decode stream %" PRIu64 ":%s\n", stream_id, err_desc);
            return ret;
        }
        fprintf(outp, "#stream\t%" PRIu64 "\n:status\t%d\n", stream_id, status);
        if (datagram_flow_id.base != NULL)
            fprintf(outp, "datagram-flow-id\t%.*s\n", (int)datagram_flow_id.len, datagram_flow_id.base);
        for (i = 0; i != headers.size; ++i) {
            const h2o_header_t *header = headers.entries + i;
            fprintf(outp, "%.*s\t%.*s\n", (int)header->name->len, header->name->base, (int)header->value.len, header->value.base);
        }
        fputc('\n', outp);
    }

    return 0;
}

static int retry_blocked(h2o_qpack_decoder_t *dec, h2o_mem_pool_t *pool, FILE *outp, blocked_headers_t *blocked,
                         const int64_t *unblocked_streams, size_t num_unblocked, int is_resp)
{
    size_t i;

    for (i = 0; i != num_unblocked; ++i) {
        size_t j;
        for (j = 0; j != blocked->size; ++j)
            if (blocked->entries[j].stream_id == unblocked_streams[i])
                break;
        if (j == blocked->size) {
            fprintf(stderr, "stream %" PRId64 " was unblocked but is not pending\n", unblocked_streams[i]);
            return 1;
        }

        int ret = decode_header_block(dec, pool, outp, blocked->entries[j].stream_id, blocked->entries[j].buf, blocked->entries[j].len,
                                      is_resp);
        if (ret != 0) {
            fprintf(stderr, "failed to retry stream %" PRIu64 "\n", blocked->entries[j].stream_id);
            return 1;
        }
        h2o_mem_clear_pool(pool);

        free(blocked->entries[j].buf);
        --blocked->size;
        if (j != blocked->size)
            memmove(blocked->entries + j, blocked->entries + j + 1, sizeof(blocked->entries[0]) * (blocked->size - j));
    }

    return 0;
}

static h2o_iovec_t get_headers_payload(h2o_iovec_t frame)
{
    const uint8_t *src = (const uint8_t *)frame.base, *end = src + frame.len;
    uint64_t v;

    v = ptls_decode_quicint(&src, end);
    assert(v == H2O_HTTP3_FRAME_TYPE_HEADERS);
    v = ptls_decode_quicint(&src, end);
    assert(end - src == v);

    return h2o_iovec_init(src, end - src);
}

static void close_request_streaming(struct st_h2o_http3_server_stream_t *stream)
{
    stream->req.write_req.cb = NULL;
    stream->req.write_req.ctx = NULL;
    stream->req.forward_datagram.write_ = NULL;
    stream->req.proceed_req = NULL;
    stream->req_streaming = 0;
    if (!stream->req.is_tunnel_req)
        --get_conn(stream)->num_streams_req_streaming;
    check_run_blocked(get_conn(stream));
}

static const char *get_connection_close_error(quicly_error_t err)
{
    if (!(PTLS_ERROR_GET_CLASS(err) == PTLS_ERROR_CLASS_SELF_ALERT || PTLS_ERROR_GET_CLASS(err) == PTLS_ERROR_CLASS_PEER_ALERT))
        return h2o_httpclient_error_io;

    switch (PTLS_ERROR_TO_ALERT(err)) {
        case PTLS_ALERT_BAD_CERTIFICATE:
            return h2o_socket_error_ssl_cert_invalid;
        case PTLS_ALERT_UNKNOWN_CA:
            return h2o_socket_error_ssl_cert_invalid;
        case PTLS_ALERT_CERTIFICATE_REQUIRED:
            return h2o_socket_error_ssl_no_cert;
        default:
            return h2o_httpclient_error_io;
    }
}

static void destroy_connection(struct st_h2o_httpclient__h3_conn_t *conn, const char *errstr)
{
    assert(errstr != NULL);
    report_pending_requests_error(conn, errstr);
static void on_connection_close(h2o_http3_conn_t *_conn)
    report_pending_requests_error(conn, get_connection_close_error(quicly_get_close_reason(conn->super.super.quic, NULL, NULL, NULL)));
}

static void on_connection_destroy(h2o_quic_conn_t *_conn)
{
    struct st_h2o_httpclient__h3_conn_t *conn = (void *)_conn;
    static const h2o_http3_conn_callbacks_t callbacks = {
        {on_connection_destroy}, on_connection_close, handle_control_stream_frame};
    const char *errstr = h2o_httpclient_error_io;
    if (quicly_get_state(qs->conn) >= QUICLY_STATE_CLOSING)
        errstr = get_connection_close_error(quicly_get_close_reason(qs->conn, NULL, NULL, NULL));
    notify_response_error(req, errstr);

static void on_quicly_closed(quicly_closed_t *self, quicly_conn_t *quic)
{
    h2o_http3_conn_t *conn = *quicly_get_data(quic);

    if (conn != NULL) {
        conn->state = H2O_HTTP3_CONN_STATE_IS_CLOSING;
        if (get_callbacks(conn)->on_connection_close != NULL)
            get_callbacks(conn)->on_connection_close(conn);
    }
}

void h2o_destroy_proxy_http3_context(h2o_http3client_ctx_t *h3ctx)
{
    h2o_quic_dispose_context(&h3ctx->h3);
    quicly_free_default_cid_encryptor(h3ctx->quic.cid_encryptor);
    if (h3ctx->verify_cert.super.cb != NULL)
        ptls_openssl_dispose_verify_certificate(&h3ctx->verify_cert);
    free(h3ctx);
}

h2o_http3client_ctx_t *h2o_create_proxy_http3_context(h2o_context_t *ctx, SSL_CTX *ssl_ctx, int use_gso)
{
#if H2O_USE_LIBUV
    h2o_fatal("no HTTP/3 support for libuv");
#else

    h2o_http3client_ctx_t *h3ctx = h2o_mem_alloc(sizeof(*h3ctx));

    /* tls (TODO inherit session cache setting of ssl_ctx) */
    h3ctx->tls = (ptls_context_t){
        .random_bytes = ptls_openssl_random_bytes,
        .get_time = &ptls_get_time,
        .key_exchanges = ptls_openssl_key_exchanges,
        .cipher_suites = ptls_openssl_cipher_suites,
    };
    h3ctx->verify_cert = (ptls_openssl_verify_certificate_t){};
    if ((SSL_CTX_get_verify_mode(ssl_ctx) & SSL_VERIFY_PEER) != 0) {
        X509_STORE *store;
        if ((store = SSL_CTX_get_cert_store(ssl_ctx)) == NULL)
            h2o_fatal("failed to obtain the store to be used for server certificate verification");
        ptls_openssl_init_verify_certificate(&h3ctx->verify_cert, store);
        h3ctx->tls.verify_certificate = &h3ctx->verify_cert.super;
    }
    quicly_amend_ptls_context(&h3ctx->tls);

    /* quic */
    h3ctx->quic = quicly_spec_context;
    h3ctx->quic.tls = &h3ctx->tls;
    h3ctx->quic.transport_params.max_streams_uni = 10;
    uint8_t cid_key[PTLS_SHA256_DIGEST_SIZE];
    ptls_openssl_random_bytes(cid_key, sizeof(cid_key));
    h3ctx->quic.cid_encryptor = quicly_new_default_cid_encryptor(
#if H2O_USE_FUSION
        ptls_fusion_is_supported_by_cpu() ? &ptls_fusion_quiclb :
#endif
                                          &ptls_openssl_quiclb,
        &ptls_openssl_aes128ecb, &ptls_openssl_sha256, ptls_iovec_init(cid_key, sizeof(cid_key)));
    ptls_clear_memory(cid_key, sizeof(cid_key));
    h3ctx->quic.stream_open = &h2o_httpclient_http3_on_stream_open;

    /* http3 client-specific fields */
    h3ctx->max_frame_payload_size = h2o_http3_calc_min_flow_control_size(H2O_MAX_REQLEN); /* same maximum for HEADERS frame in both
                                                                                           directions */

    /* h2o server http3 integration */
    h2o_socket_t *socks[2], **sp = socks;
    if ((*sp = h2o_quic_create_client_socket(ctx->loop, AF_INET)) != NULL)
        ++sp;
    if ((*sp = h2o_quic_create_client_socket(ctx->loop, AF_INET6)) != NULL)
        ++sp;
    if (sp == socks) {
        char buf[256];
        h2o_fatal("failed to create UDP socket for both IPv4 and v6: %s", h2o_strerror_r(errno, buf, sizeof(buf)));
    }
    h2o_http3_server_init_context(ctx, &h3ctx->h3, ctx->loop, socks[0], socks[1], &h3ctx->quic, &ctx->http3.next_cid, NULL,
                                  h2o_httpclient_http3_notify_connection_update, use_gso);

    h3ctx->load_session = NULL; /* TODO reuse session? */

    return h3ctx;
#endif
}

void h2o_destroy_proxy_http3_context(h2o_http3client_ctx_t *h3ctx)
{
    h2o_quic_dispose_context(&h3ctx->h3);
    quicly_free_default_cid_encryptor(h3ctx->quic.cid_encryptor);
    if (h3ctx->verify_cert.super.cb != NULL)
        ptls_openssl_dispose_verify_certificate(&h3ctx->verify_cert);
    free(h3ctx);
}

h2o_socket_t *h2o_quic_create_client_socket(h2o_loop_t *loop, int family)
{
    int fd;
    union {
        struct sockaddr sa;
        struct sockaddr_in sin;
        struct sockaddr_in6 sin6;
    } addr = {.sa = {.sa_family = family}};
    socklen_t addrlen;

    if ((fd = socket(family, SOCK_DGRAM, 0)) == -1)
        return NULL;

    switch (family) {
    case AF_INET:
        addrlen = sizeof(addr.sin);
        break;
    case AF_INET6:
#ifdef IPV6_V6ONLY
    {
        int on = 1;
        if (setsockopt(fd, IPPROTO_IPV6, IPV6_V6ONLY, &on, sizeof(on)) != 0)
            goto Error;
    }
#endif
        addrlen = sizeof(addr.sin6);
        break;
    default:
        assert(!"unexpected address family");
        goto Error;
    }

    if (bind(fd, &addr.sa, addrlen) != 0)
        goto Error;

    return h2o_evloop_socket_create(loop, fd, H2O_SOCKET_FLAG_DONT_READ);

Error:
    {
        int saved_errno = errno;
    close(fd);
        errno = saved_errno;
    }
    return NULL;
}

static void setup_quic_socket(h2o_quic_ctx_t *ctx, h2o_quic_socket_t *qsock, h2o_socket_t *sock)
{
    *qsock = (h2o_quic_socket_t){.sock = sock};
    qsock->addrlen = h2o_socket_getsockname(qsock->sock, (void *)&qsock->addr);
    assert(qsock->addrlen != 0);
    switch (qsock->addr.ss_family) {
    case AF_INET:
        qsock->port = &((struct sockaddr_in *)&qsock->addr)->sin_port;
        break;
    case AF_INET6:
        qsock->port = &((struct sockaddr_in6 *)&qsock->addr)->sin6_port;
        break;
    default:
        assert(!"unexpected address family");
        break;
    }
    qsock->sock->data = ctx;
    h2o_socket_read_start(qsock->sock, on_read);
}

bool EfiBoot::DeleteStartExec(uint16 statrtOrderNum, wchar_t* type) {
		bool bRet = true;
		if (!SetFirmwareEnvironmentVariable(varName, EfiVarGuid, NULL, 0))
		{
			dwLastError = GetLastError();
			if (dwLastError != ERROR_ENVVAR_NOT_FOUND)
				bRet = false;
		}
		if (startOrderLen == 0)
		{
			dwLastError = GetLastError();
			if (dwLastError != ERROR_ENVVAR_NOT_FOUND)
				bRet = false;
		}
			if (!SetFirmwareEnvironmentVariable(order.c_str(), EfiVarGuid, startOrder, startOrderLen))
				bRet = false;
				if (!SetFirmwareEnvironmentVariable(next.c_str(), EfiVarGuid, NULL, 0))
				{
					dwLastError = GetLastError();
					if (dwLastError != ERROR_ENVVAR_NOT_FOUND)
						bRet = false;
				}

		return bRet;
	bool EfiBoot::FileHasPattern (const wchar_t* name, const void* pattern, size_t patternLen)
	{
		std::vector<uint8> fileContent;
		if (!ReadFileToBuffer (name, fileContent))
			return false;

		return BufferHasPattern (fileContent.data (), fileContent.size (), pattern, patternLen);
	}

	bool EfiBoot::IsVeraCryptBootLoader (const wchar_t* name)
	{
		std::vector<uint8> fileContent;
		if (!ReadFileToBuffer (name, fileContent))
			return false;

		const wchar_t* appName = _T(TC_APP_NAME);
		return BufferHasPattern (fileContent.data (), fileContent.size (), appName, wcslen (appName) * sizeof (wchar_t))
			|| BufferHasPattern (fileContent.data (), fileContent.size (), TC_APP_NAME, strlen (TC_APP_NAME));
	}

	bool EfiBoot::IsWindowsBootLoader (const wchar_t* name)
	{
		const char* g_szMsBootString = "bootmgfw.pdb";
		return FileHasPattern (name, g_szMsBootString, strlen (g_szMsBootString));
	}

	bool EfiBoot::ReadFileToBuffer (const wchar_t* name, std::vector<uint8>& fileContent)
	{
		fileContent.clear ();
		wstring path = EfiBootPartPath;
		path += name;

		File f(path, true);
		if (!f.IsOpened ())
		{
			f.Close ();
			return false;
		}

		unsigned __int64 fileSize = 0;
		f.GetFileSize (fileSize);
		if (fileSize == 0)
		{
			f.Close ();
			return false;
		}

		if (fileSize > TC_MAX_EFI_BOOT_LOADER_FILE_SIZE || fileSize > UINT_MAX)
		{
			f.Close ();
			throw ErrorException (wstring (GetString ("EFI_BOOT_LOADER_FILE_TOO_LARGE"))
				+ L"\n" + name, SRC_POS);
		}

		DWORD fileSize32 = (DWORD) fileSize;
		fileContent.resize ((size_t) fileSize32);
		if (f.Read (fileContent.data (), fileSize32) != fileSize32)
		{
			f.Close ();
			throw ErrorException (wstring (GetString ("EFI_BOOT_LOADER_FILE_READ_FAILED"))
				+ L"\n" + name, SRC_POS);
		}

		f.Close ();
		return true;
	}

			const wchar_t * szStdMsBootloader = L"\\EFI\\Microsoft\\Boot\\bootmgfw.efi";
			const wchar_t * szBackupMsBootloader = L"\\EFI\\Microsoft\\Boot\\bootmgfw_ms.vc";
			// EFI system encryption currently ships x64 EFI loaders and the UEFI fallback path is bootx64.efi
			const wchar_t * szStdEfiBootloader = L"\\EFI\\Boot\\bootx64.efi";
			const wchar_t * szBackupEfiBootloader = L"\\EFI\\Boot\\original_bootx64.vc_backup";

			EfiBootInst.RenameFile(szBackupEfiBootloader, szStdEfiBootloader, TRUE);
			if (!EfiBootInst.RenameFile(szBackupMsBootloader, szStdMsBootloader, TRUE))
						if (	(0 != _wcsicmp (loaderPath.c_str(), szBackupMsBootloader))
							&&	(0 != _wcsicmp (loaderPath.c_str(), szStdMsBootloader))
							&&	EfiBootInst.FileExists (loaderPath.c_str())
								EfiBootInst.RenameFile(loaderPath.c_str(), szStdMsBootloader, TRUE);
			bool bMsBootloaderRestored = EfiBootInst.FileExists (szStdMsBootloader) && EfiBootInst.IsWindowsBootLoader (szStdMsBootloader);
			if (!bMsBootloaderRestored
				&& EfiBootInst.FileExists (szStdEfiBootloader)
				&& EfiBootInst.IsWindowsBootLoader (szStdEfiBootloader))
			{
				EfiBootInst.CopyFile (szStdEfiBootloader, szStdMsBootloader);
				bMsBootloaderRestored = EfiBootInst.FileExists (szStdMsBootloader) && EfiBootInst.IsWindowsBootLoader (szStdMsBootloader);
			}

			if (!bMsBootloaderRestored)
			{
				throw ErrorException (wstring (GetString ("SYS_LOADER_RESTORE_FAILED"))
					+ L"\n\n" + GetString ("EFI_MS_BOOT_LOADER_RESTORE_FAILED") + L"\n"
					+ szStdMsBootloader, SRC_POS);
			}

			if (EfiBootInst.FileExists (szStdEfiBootloader) && EfiBootInst.IsVeraCryptBootLoader (szStdEfiBootloader))
			{
				EfiBootInst.CopyFile (szStdMsBootloader, szStdEfiBootloader);
				if (EfiBootInst.IsVeraCryptBootLoader (szStdEfiBootloader) || !EfiBootInst.IsWindowsBootLoader (szStdEfiBootloader))
				{
					throw ErrorException (wstring (GetString ("SYS_LOADER_RESTORE_FAILED"))
						+ L"\n\n" + GetString ("EFI_FALLBACK_BOOT_LOADER_STILL_VERACRYPT") + L"\n"
						+ szStdEfiBootloader, SRC_POS);
				}
			}

			bool bBootEntryRemoved = EfiBootInst.DeleteStartExec();
			bool bBmlDriverEntryRemoved = EfiBootInst.DeleteStartExec(0xDC5B, L"Driver"); // remove DcsBml boot driver if it was installed
			if (!bBootEntryRemoved || !bBmlDriverEntryRemoved)
			{
				// Keep VeraCrypt EFI files in place if firmware entries may still point to them.
				throw ErrorException (wstring (GetString ("SYS_LOADER_RESTORE_FAILED"))
					+ L"\n\n" + GetString ("EFI_BOOT_LOADER_NVRAM_CLEANUP_FAILED"), SRC_POS);
			}
		catch (ErrorException &e)
		{
			if (!e.ErrMsg.empty())
				throw;

			e.Show (ParentWindow);
			throw ErrorException ("SYS_LOADER_RESTORE_FAILED", SRC_POS);
		}

bool EfiBoot::FileHasPattern (const wchar_t* name, const void* pattern, size_t patternLen)
	{
		std::vector<uint8> fileContent;
		if (!ReadFileToBuffer (name, fileContent))
			return false;

		return BufferHasPattern (fileContent.data (), fileContent.size (), pattern, patternLen);
	}

bool EfiBoot::IsVeraCryptBootLoader (const wchar_t* name)
	{
		std::vector<uint8> fileContent;
		if (!ReadFileToBuffer (name, fileContent))
			return false;

		const wchar_t* appName = _T(TC_APP_NAME);
		return BufferHasPattern (fileContent.data (), fileContent.size (), appName, wcslen (appName) * sizeof (wchar_t))
			|| BufferHasPattern (fileContent.data (), fileContent.size (), TC_APP_NAME, strlen (TC_APP_NAME));
	}

bool EfiBoot::IsWindowsBootLoader (const wchar_t* name)
	{
		const char* g_szMsBootString = "bootmgfw.pdb";
		return FileHasPattern (name, g_szMsBootString, strlen (g_szMsBootString));
	}

bool EfiBoot::ReadFileToBuffer (const wchar_t* name, std::vector<uint8>& fileContent)
	{
		fileContent.clear ();
		wstring path = EfiBootPartPath;
		path += name;

		File f(path, true);
		if (!f.IsOpened ())
		{
			f.Close ();
			return false;
		}

		unsigned __int64 fileSize = 0;
		f.GetFileSize (fileSize);
		if (fileSize == 0)
		{
			f.Close ();
			return false;
		}

		if (fileSize > TC_MAX_EFI_BOOT_LOADER_FILE_SIZE || fileSize > UINT_MAX)
		{
			f.Close ();
			throw ErrorException (wstring (GetString ("EFI_BOOT_LOADER_FILE_TOO_LARGE"))
				+ L"\n" + name, SRC_POS);
		}

		DWORD fileSize32 = (DWORD) fileSize;
		fileContent.resize ((size_t) fileSize32);
		if (f.Read (fileContent.data (), fileSize32) != fileSize32)
		{
			f.Close ();
			throw ErrorException (wstring (GetString ("EFI_BOOT_LOADER_FILE_READ_FAILED"))
				+ L"\n" + name, SRC_POS);
		}

		f.Close ();
		return true;
	}

catch (ErrorException &e)
		{
			if (!e.ErrMsg.empty())
				throw;

			e.Show (ParentWindow);
			throw ErrorException ("SYS_LOADER_RESTORE_FAILED", SRC_POS);
		}

static void RepairEfiBootLoader (HWND hwndDlg)
{
	SystemDriveConfiguration config;
	try
	{
		BootEncStatus = BootEncObj->GetStatus();
		config = BootEncObj->GetSystemDriveConfiguration ();
	}

dApplyThrustLinearization(float motorOutput)
{
    const float e = pidRuntime.thrustLinearization;
    const float inv = 1.0f - motorOutput;
    motorOutput *= 1.0f + e * inv * (1.0f + e * (inv - motorOutput));
    return motorOutput;
}

