proto_reg_handoff_dect_nr_tap(void)
{
    dissector_add_uint("wtap_encap", WTAP_ENCAP_DECT_NR_TAP, dect_nr_tap_handle);

    dect_nr_handle = find_dissector_add_dependency("dect_nr", proto_dect_nr_tap);
}

