static int
compare_nmea0183_sentence_decoder(const void *key, const void *element)
{
    uint32_t sentence_key = *(const uint32_t *)key;
    const nmea0183_sentence_decoder_t *decoder = element;

    return (sentence_key > decoder->id) - (sentence_key < decoder->id);
}

static char* readFileDynamic(openat_arg_t procFd, const char* filename, ssize_t* amtRead) {
   size_t bufferSize = 4096 + 1;
   char* buffer = xMalloc(bufferSize);

   *amtRead = Compat_readfileat(procFd, filename, buffer, bufferSize);

   // If buffer was full, the file might be larger, so retry with a bigger buffer
   // Limit to MAX_CMDLINE_BUFFER_SIZE to prevent excessive memory allocation
   while (*amtRead > 0 && (size_t)*amtRead == bufferSize - 1 && bufferSize < MAX_CMDLINE_BUFFER_SIZE) {
      bufferSize *= 2;
      buffer = xRealloc(buffer, bufferSize);
      *amtRead = Compat_readfileat(procFd, filename, buffer, bufferSize);
   }

   if (*amtRead <= 0) {
      free(buffer);
      return NULL;
   }

   return buffer;
}

static int recursive_delete_directory(const char *dir_path)
{
#ifdef FLB_SYSTEM_WINDOWS
    WIN32_FIND_DATAA ffd;
    HANDLE hFind = INVALID_HANDLE_VALUE;
    char search_path[PATH_MAX];
    char file_path[PATH_MAX];
    int ret = 0;

    if (dir_path == NULL) {
        return -1;
    }

    /* Create search path: dir_path\* */
    snprintf(search_path, sizeof(search_path), "%s\\*", dir_path);
    search_path[sizeof(search_path) - 1] = '\0';

    hFind = FindFirstFileA(search_path, &ffd);
    if (hFind == INVALID_HANDLE_VALUE) {
        /* Directory doesn't exist or can't be opened, consider it success */
        return 0;
    }

    do {
        /* Skip . and .. */
        if (strcmp(ffd.cFileName, ".") == 0 ||
            strcmp(ffd.cFileName, "..") == 0) {
            continue;
        }

        /* Build full path */
        snprintf(file_path, sizeof(file_path), "%s\\%s", dir_path,
                 ffd.cFileName);
        file_path[sizeof(file_path) - 1] = '\0';

        /* Recursively delete subdirectories */
        if (ffd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) {
            if (recursive_delete_directory(file_path) != 0) {
                ret = -1;
            }
        }
        else {
            /* Delete file - clear read-only if needed */
            if (ffd.dwFileAttributes & FILE_ATTRIBUTE_READONLY) {
                SetFileAttributesA(file_path, ffd.dwFileAttributes &
                                                  ~FILE_ATTRIBUTE_READONLY);
            }
            if (DeleteFileA(file_path) == 0) {
                ret = -1;
            }
        }
    } while (FindNextFileA(hFind, &ffd) != 0);

    FindClose(hFind);

    /* Remove the directory itself */
    if (RemoveDirectoryA(dir_path) == 0) {
        ret = -1;
    }

    return ret;
#else
    DIR *dir;
    struct dirent *entry;
    struct stat statbuf;
    char path[PATH_MAX];
    int ret = 0;

    if (dir_path == NULL) {
        return -1;
    }

    /* Check if directory exists */
    if (stat(dir_path, &statbuf) != 0) {
        /* Directory doesn't exist, consider it success */
        return 0;
    }

    /* Check if it's actually a directory */
    if (!S_ISDIR(statbuf.st_mode)) {
        /* Not a directory, try to remove as file */
        return remove(dir_path);
    }

    /* Open directory */
    dir = opendir(dir_path);
    if (dir == NULL) {
        return -1;
    }

    /* Iterate through directory entries */
    while ((entry = readdir(dir)) != NULL) {
        /* Skip . and .. */
        if (strcmp(entry->d_name, ".") == 0 ||
            strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        /* Build full path */
        snprintf(path, sizeof(path), "%s/%s", dir_path, entry->d_name);

        /* Get file status */
        if (stat(path, &statbuf) != 0) {
            continue;
        }

        /* Recursively delete subdirectories */
        if (S_ISDIR(statbuf.st_mode)) {
            if (recursive_delete_directory(path) != 0) {
                ret = -1;
            }
        }
        else {
            /* Delete file */
            if (unlink(path) != 0) {
                ret = -1;
            }
        }
    }

    closedir(dir);

    /* Remove the directory itself */
    if (rmdir(dir_path) != 0) {
        ret = -1;
    }

    return ret;
#endif
}

static int count_files_in_directory(const char *dir_path, const char *prefix)
{
    WIN32_FIND_DATAA ffd;
    HANDLE hFind = INVALID_HANDLE_VALUE;
    char search_path[PATH_MAX];
    int count = 0;

    snprintf(search_path, sizeof(search_path), "%s\\*", dir_path);
    hFind = FindFirstFileA(search_path, &ffd);
    if (hFind == INVALID_HANDLE_VALUE) {
        return -1;
    }

    do {
        if (strncmp(ffd.cFileName, prefix, strlen(prefix)) == 0) {
            count++;
        }
    } while (FindNextFileA(hFind, &ffd) != 0);

    FindClose(hFind);
    return count;
}

static int count_files_in_directory(const char *dir_path, const char *prefix)
{
    DIR *dir;
    struct dirent *entry;
    int count = 0;

    dir = opendir(dir_path);
    if (dir == NULL) {
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, prefix, strlen(prefix)) == 0) {
            count++;
        }
    }

    closedir(dir);
    return count;
}

static int wait_for_file_pattern(const char *dir_path, const char *prefix,
                                 const char *suffix, int time_limit)
{
    int elapsed_time;
    int found = 0;
    WIN32_FIND_DATAA ffd;
    HANDLE hFind = INVALID_HANDLE_VALUE;
    char search_path[PATH_MAX];
    size_t prefix_len = strlen(prefix);
    size_t suffix_len = strlen(suffix);
    size_t name_len;

    snprintf(search_path, sizeof(search_path), "%s\\*", dir_path);

    for (elapsed_time = 0; elapsed_time < time_limit && !found;
         elapsed_time++) {
        hFind = FindFirstFileA(search_path, &ffd);
        if (hFind != INVALID_HANDLE_VALUE) {
            do {
                name_len = strlen(ffd.cFileName);
                if (strncmp(ffd.cFileName, prefix, prefix_len) == 0 &&
                    name_len > prefix_len + suffix_len &&
                    (suffix_len == 0 ||
                     strcmp(ffd.cFileName + name_len - suffix_len,
                            suffix) == 0)) {
                    found = 1;
                    break;
                }
            } while (FindNextFileA(hFind, &ffd) != 0);
            FindClose(hFind);
        }
        if (!found) {
            flb_time_msleep(1000);
        }
    }
    return found;
}

static int wait_for_file_pattern(const char *dir_path, const char *prefix,
                                 const char *suffix, int time_limit)
{
    int elapsed_time;
    int found = 0;
    DIR *dir;
    struct dirent *entry;
    size_t prefix_len = strlen(prefix);
    size_t suffix_len = strlen(suffix);
    size_t name_len;

    for (elapsed_time = 0; elapsed_time < time_limit && !found;
         elapsed_time++) {
        dir = opendir(dir_path);
        if (dir) {
            while ((entry = readdir(dir)) != NULL) {
                name_len = strlen(entry->d_name);
                if (strncmp(entry->d_name, prefix, prefix_len) == 0 &&
                    name_len > prefix_len + suffix_len &&
                    (suffix_len == 0 ||
                     strcmp(entry->d_name + name_len - suffix_len,
                            suffix) == 0)) {
                    found = 1;
                    break;
                }
            }
            closedir(dir);
        }
        if (!found) {
            flb_time_msleep(1000);
        }
    }
    return found;
}

static int find_file_pattern(const char *dir_path, const char *prefix,
                             const char *suffix, char *out_path,
                             size_t out_path_size)
{
    WIN32_FIND_DATAA ffd;
    HANDLE hFind = INVALID_HANDLE_VALUE;
    char search_path[PATH_MAX];
    size_t prefix_len = strlen(prefix);
    size_t suffix_len = strlen(suffix);
    size_t name_len;
    int found = 0;

    if (!dir_path || !prefix || !suffix || !out_path || out_path_size == 0) {
        return 0;
    }

    snprintf(search_path, sizeof(search_path), "%s\\*", dir_path);
    hFind = FindFirstFileA(search_path, &ffd);
    if (hFind == INVALID_HANDLE_VALUE) {
        return 0;
    }

    do {
        name_len = strlen(ffd.cFileName);
        if (strncmp(ffd.cFileName, prefix, prefix_len) == 0 &&
            name_len > prefix_len + suffix_len &&
            (suffix_len == 0 ||
             strcmp(ffd.cFileName + name_len - suffix_len, suffix) == 0)) {
            snprintf(out_path, out_path_size, "%s\\%s", dir_path,
                     ffd.cFileName);
            out_path[out_path_size - 1] = '\0';
            found = 1;
            break;
        }
    } while (FindNextFileA(hFind, &ffd) != 0);

    FindClose(hFind);
    return found;
}

static int find_file_pattern(const char *dir_path, const char *prefix,
                             const char *suffix, char *out_path,
                             size_t out_path_size)
{
    DIR *dir;
    struct dirent *entry;
    size_t prefix_len = strlen(prefix);
    size_t suffix_len = strlen(suffix);
    size_t name_len;

    if (!dir_path || !prefix || !suffix || !out_path || out_path_size == 0) {
        return 0;
    }

    dir = opendir(dir_path);
    if (dir == NULL) {
        return 0;
    }

    while ((entry = readdir(dir)) != NULL) {
        name_len = strlen(entry->d_name);
        if (strncmp(entry->d_name, prefix, prefix_len) == 0 &&
            name_len > prefix_len + suffix_len &&
            (suffix_len == 0 ||
             strcmp(entry->d_name + name_len - suffix_len, suffix) == 0)) {
            snprintf(out_path, out_path_size, "%s/%s", dir_path,
                     entry->d_name);
            out_path[out_path_size - 1] = '\0';
            closedir(dir);
            return 1;
        }
    }

    closedir(dir);
    return 0;
}

static int wait_for_file_size(const char *path, size_t min_size, int time_limit)
{
    int elapsed_time;
    struct stat st;

    for (elapsed_time = 0; elapsed_time < time_limit; elapsed_time++) {
        if (stat(path, &st) == 0 && st.st_size >= min_size) {
            return 0;
        }
        flb_time_msleep(1000);
    }
    return -1;
}

static char *read_file_content(const char *filename, size_t *out_size)
{
    FILE *fp;
    char *buffer;
    struct stat st;
    size_t size;

    if (stat(filename, &st) != 0) {
        return NULL;
    }

    size = st.st_size;
    fp = fopen(filename, "rb");
    if (!fp) {
        return NULL;
    }

    buffer = flb_malloc(size + 1);
    if (!buffer) {
        fclose(fp);
        return NULL;
    }

    if (fread(buffer, 1, size, fp) != size) {
        flb_free(buffer);
        fclose(fp);
        return NULL;
    }

    buffer[size] = '\0';
    fclose(fp);
    *out_size = size;
    return buffer;
}

static const char *test_basename(const char *path)
{
    const char *p;

    p = strrchr(path, '/');
#ifdef FLB_SYSTEM_WINDOWS
    {
        const char *p2 = strrchr(path, '\\');

        if (p2 != NULL && (p == NULL || p2 > p)) {
            p = p2;
        }
    }
#endif
    return (p != NULL) ? (p + 1) : path;
}

static int new_rotation_suffix_valid(const char *suf)
{
    int i;

    if (strlen(suf) != 24) {
        return 0;
    }
    for (i = 0; i < 8; i++) {
        if (suf[i] < '0' || suf[i] > '9') {
            return 0;
        }
    }
    if (suf[8] != '_') {
        return 0;
    }
    for (i = 9; i < 15; i++) {
        if (suf[i] < '0' || suf[i] > '9') {
            return 0;
        }
    }
    if (suf[15] != '_') {
        return 0;
    }
    for (i = 16; i < 24; i++) {
        if (!((suf[i] >= '0' && suf[i] <= '9') ||
              (suf[i] >= 'a' && suf[i] <= 'f'))) {
            return 0;
        }
    }
    return 1;
}

static char *decompress_gzip_file(const char *path, size_t *out_size)
{
    char *raw;
    char *acc = NULL;
    char *tmp;
    void *member = NULL;
    size_t raw_size = 0;
    size_t member_size = 0;
    size_t remaining;
    size_t next_remaining;
    size_t acc_size = 0;
    unsigned char *cursor;

    raw = read_file_content(path, &raw_size);
    if (raw == NULL) {
        return NULL;
    }

    cursor = (unsigned char *) raw;
    remaining = raw_size;

    while (remaining > 0) {
        if (flb_gzip_uncompress_multi(cursor, remaining, &member,
                                      &member_size, &next_remaining) != 0) {
            flb_free(acc);
            flb_free(raw);
            return NULL;
        }

        tmp = flb_realloc(acc, acc_size + member_size + 1);
        if (tmp == NULL) {
            flb_free(member);
            flb_free(acc);
            flb_free(raw);
            return NULL;
        }
        acc = tmp;
        memcpy(acc + acc_size, member, member_size);
        acc_size += member_size;
        acc[acc_size] = '\0';
        flb_free(member);

        cursor += (remaining - next_remaining);
        remaining = next_remaining;
    }

    flb_free(raw);
    *out_size = acc_size;

    return acc;
}

void flb_test_file_rotation_basic(void)
{
    int i;
    int ret;
    int bytes;
    char *p = (char *) JSON_SMALL;
    flb_ctx_t *ctx;
    int in_ffd;
    int out_ffd;
    char logfile[512];
    char rotated[PATH_MAX];

    recursive_delete_directory(TEST_LOGPATH);
    TEST_MKDIR(TEST_LOGPATH);
    snprintf(logfile, sizeof(logfile), "%s" PATH_SEPARATOR "%s", TEST_LOGPATH,
             TEST_LOGFILE);

    ctx = flb_create();
    TEST_ASSERT(flb_service_set(ctx, "Flush", "1", "Grace", "1", "Log_Level",
                                "error", NULL) == 0);

    in_ffd = flb_input(ctx, (char *) "lib", NULL);
    TEST_CHECK(in_ffd >= 0);
    flb_input_set(ctx, in_ffd, "tag", "test", NULL);

    out_ffd = flb_output(ctx, (char *) "file", NULL);
    TEST_CHECK(out_ffd >= 0);
    TEST_ASSERT(flb_output_set(ctx, out_ffd, "match", "test",
                               "file", logfile,
                               "rotate", "true",
                               "rotate_max_size", "1",
                               "rotate_max_files", "3",
                               "rotate_gzip", "false", NULL) == 0);

    ret = flb_start(ctx);
    TEST_CHECK(ret == 0);

    /* Two flush cycles: the first creates the file, the second rotates it. */
    for (i = 0; i < 3; i++) {
        bytes = flb_lib_push(ctx, in_ffd, p, strlen(p));
        TEST_CHECK(bytes == strlen(p));
    }
    flb_time_msleep(1500);

    for (i = 0; i < 3; i++) {
        bytes = flb_lib_push(ctx, in_ffd, p, strlen(p));
        TEST_CHECK(bytes == strlen(p));
    }
    flb_time_msleep(1500);

    flb_stop(ctx);
    flb_destroy(ctx);

    /* A rotated file is the base name plus '.' and the generated suffix. */
    TEST_CHECK(wait_for_file_pattern(TEST_LOGPATH, TEST_LOGFILE ".", "",
                                     TEST_TIMEOUT) == 1);
    TEST_CHECK(find_file_pattern(TEST_LOGPATH, TEST_LOGFILE ".", "",
                                 rotated, sizeof(rotated)) == 1);

    recursive_delete_directory(TEST_LOGPATH);
}

void flb_test_file_rotation_format_csv(void)
{
    int i;
    int ret;
    int bytes;
    char *p = (char *)JSON_SMALL;
    flb_ctx_t *ctx;
    int in_ffd;
    int out_ffd;
    char logfile[512];
    char *content;
    size_t content_size;

    /* Clean up any existing directory and contents */
    recursive_delete_directory(TEST_LOGPATH);
    TEST_MKDIR(TEST_LOGPATH);
    snprintf(logfile, sizeof(logfile), "%s" PATH_SEPARATOR "%s", TEST_LOGPATH,
             "test_csv.log");

    ctx = flb_create();
    TEST_ASSERT(flb_service_set(ctx, "Flush", "1", "Grace", "1", "Log_Level",
                                "error", NULL) == 0);

    in_ffd = flb_input(ctx, (char *)"lib", NULL);
    TEST_CHECK(in_ffd >= 0);
    flb_input_set(ctx, in_ffd, "tag", "test", NULL);

    out_ffd = flb_output(ctx, (char *)"file", NULL);
    TEST_CHECK(out_ffd >= 0);
    TEST_ASSERT(flb_output_set(ctx, out_ffd, "match", "test", "file", logfile,
                               "format", "csv", "rotate", "true",
                               "rotate_max_size", "100M", "rotate_gzip",
                               "false", NULL) == 0);

    ret = flb_start(ctx);
    TEST_CHECK(ret == 0);

    /* Write some data */
    for (i = 0; i < 3; i++) {
        bytes = flb_lib_push(ctx, in_ffd, p, strlen(p));
        TEST_CHECK(bytes == strlen(p));
    }

    flb_time_msleep(1500);

    flb_stop(ctx);
    flb_destroy(ctx);

    /* Verify CSV format - should contain commas as delimiters */
    content = read_file_content(logfile, &content_size);
    TEST_CHECK(content != NULL);
    if (content) {
        /* CSV should contain commas */
        TEST_CHECK(strstr(content, ",") != NULL);
        /* CSV should contain timestamp */
        TEST_CHECK(strstr(content, "1448403340") != NULL);
        flb_free(content);
    }

    /* Clean up directory and all contents */
    recursive_delete_directory(TEST_LOGPATH);
}

