void flb_test_file_rotation_repeated_flush_all_formats(void)
{
    int i;
    int f;
    int ret;
    int bytes;
    char *p = (char *) JSON_SMALL;
    /*
     * upstream cb_file_init() accepts "out_file" (equivalent to json) but
     * rejects an explicit "json" string; use "out_file" for the JSON case.
     */
    const char *formats[] = {"out_file", "csv", "ltsv", "plain", "template",
                             "msgpack"};
    flb_ctx_t *ctx;
    int in_ffd;
    int out_ffd;
    char logfile[512];
    struct stat first;
    struct stat last;

    for (f = 0; f < 6; f++) {
        recursive_delete_directory(TEST_LOGPATH);
        TEST_MKDIR(TEST_LOGPATH);
        snprintf(logfile, sizeof(logfile), "%s" PATH_SEPARATOR "%s.log",
                 TEST_LOGPATH, formats[f]);

        ctx = flb_create();
        TEST_ASSERT(flb_service_set(ctx, "Flush", "1", "Grace", "1",
                                    "Log_Level", "error", NULL) == 0);

        in_ffd = flb_input(ctx, (char *) "lib", NULL);
        TEST_CHECK(in_ffd >= 0);
        flb_input_set(ctx, in_ffd, "tag", "test", NULL);

        out_ffd = flb_output(ctx, (char *) "file", NULL);
        TEST_CHECK(out_ffd >= 0);
        /* A large limit means no rotation; this only exercises the locking. */
        TEST_ASSERT(flb_output_set(ctx, out_ffd, "match", "test",
                                   "file", logfile,
                                   "format", formats[f],
                                   "rotate", "true",
                                   "rotate_max_size", "100M",
                                   "rotate_max_files", "3",
                                   "rotate_gzip", "false", NULL) == 0);

        ret = flb_start(ctx);
        TEST_CHECK(ret == 0);

        for (i = 0; i < 3; i++) {
            bytes = flb_lib_push(ctx, in_ffd, p, strlen(p));
            TEST_CHECK(bytes == strlen(p));
        }
        flb_time_msleep(1500);
        TEST_ASSERT(stat(logfile, &first) == 0);

        for (i = 0; i < 3; i++) {
            bytes = flb_lib_push(ctx, in_ffd, p, strlen(p));
            TEST_CHECK(bytes == strlen(p));
        }
        flb_time_msleep(1500);

        for (i = 0; i < 3; i++) {
            bytes = flb_lib_push(ctx, in_ffd, p, strlen(p));
            TEST_CHECK(bytes == strlen(p));
        }
        flb_time_msleep(1500);

        flb_stop(ctx);
        flb_destroy(ctx);

        /* Later cycles must have appended, proving the lock was released. */
        TEST_ASSERT(stat(logfile, &last) == 0);
        TEST_CHECK(last.st_size > first.st_size);

        recursive_delete_directory(TEST_LOGPATH);
    }
}

void flb_test_file_rotation_open_failure_releases_lock(void)
{
    int i;
    int ret;
    int bytes;
    char *p = (char *) JSON_SMALL;
    flb_ctx_t *ctx;
    int in_ffd;
    int out_ffd;
    char logfile[512];
    struct stat st;

    recursive_delete_directory(TEST_LOGPATH);
    TEST_MKDIR(TEST_LOGPATH);
    snprintf(logfile, sizeof(logfile), "%s" PATH_SEPARATOR "open_fail.log",
             TEST_LOGPATH);

    /* Occupy the destination path so the first open fails. */
    TEST_MKDIR(logfile);

    ctx = flb_create();
    TEST_ASSERT(flb_service_set(ctx, "Flush", "1", "Grace", "1", "Log_Level",
                                "error", NULL) == 0);

    in_ffd = flb_input(ctx, (char *) "lib", NULL);
    TEST_CHECK(in_ffd >= 0);
    flb_input_set(ctx, in_ffd, "tag", "test", NULL);

    out_ffd = flb_output(ctx, (char *) "file", NULL);
    TEST_CHECK(out_ffd >= 0);
    TEST_ASSERT(flb_output_set(ctx, out_ffd, "match", "test",
                               "file", logfile,
                               "mkdir", "false",
                               "rotate", "true",
                               "rotate_max_size", "100M",
                               "rotate_max_files", "3",
                               "rotate_gzip", "false", NULL) == 0);

    ret = flb_start(ctx);
    TEST_CHECK(ret == 0);

    for (i = 0; i < 3; i++) {
        bytes = flb_lib_push(ctx, in_ffd, p, strlen(p));
        TEST_CHECK(bytes == strlen(p));
    }
    flb_time_msleep(1500);

    /* Path is still a directory: open failed and must have released the lock. */
    TEST_ASSERT(stat(logfile, &st) == 0);
    TEST_CHECK(S_ISDIR(st.st_mode));

#ifdef FLB_SYSTEM_WINDOWS
    TEST_ASSERT(RemoveDirectoryA(logfile) != 0);
#else
    TEST_ASSERT(rmdir(logfile) == 0);
#endif

    for (i = 0; i < 3; i++) {
        bytes = flb_lib_push(ctx, in_ffd, p, strlen(p));
        TEST_CHECK(bytes == strlen(p));
    }
    flb_time_msleep(1500);

    flb_stop(ctx);
    flb_destroy(ctx);

    /*
     * A second flush after clearing the blocker must write a regular file.
     * If the first open left the entry lock held, this would time out /
     * fail instead of creating the log.
     */
    TEST_ASSERT(stat(logfile, &st) == 0);
    TEST_CHECK(S_ISREG(st.st_mode));
    TEST_CHECK(st.st_size > 0);

    recursive_delete_directory(TEST_LOGPATH);
}

static void close_output_file(FILE *fp, struct file_rotate_entry *entry)
{
    file_rotate_update(entry, fp);
    fclose(fp);
    file_rotate_release(entry);
}

struct file_rotate_ctx *file_rotate_create(struct flb_output_instance *ins,
                                           int enabled, size_t max_size,
                                           int max_files, int gzip)
{
    struct file_rotate_ctx *rot;

    if (enabled == FLB_TRUE) {
        if (max_size == 0) {
            flb_plg_error(ins, "rotate_max_size must be greater than zero");
            return NULL;
        }
        if (max_files < 1) {
            flb_plg_error(ins, "invalid rotate_max_files=%d; must be >= 1",
                          max_files);
            return NULL;
        }
    }

    rot = flb_calloc(1, sizeof(struct file_rotate_ctx));
    if (rot == NULL) {
        flb_errno();
        return NULL;
    }

    rot->ins = ins;
    rot->enabled = enabled;
    rot->max_size = max_size;
    rot->max_files = max_files;
    rot->gzip = gzip;
    mk_list_init(&rot->entries);

    if (enabled == FLB_FALSE) {
        return rot;
    }

    if (flb_lock_init(&rot->index_lock) != 0) {
        flb_plg_error(ins, "could not initialize rotation index lock");
        flb_free(rot);
        return NULL;
    }

    rot->index = flb_hash_table_create(FLB_HASH_TABLE_EVICT_NONE,
                                       FILE_ROTATE_INDEX_BUCKETS, 0);
    if (rot->index == NULL) {
        flb_plg_error(ins, "could not create rotation index");
        flb_lock_destroy(&rot->index_lock);
        flb_free(rot);
        return NULL;
    }

    flb_plg_info(ins, "file rotation enabled: rotate_max_size=%zu, "
                 "rotate_max_files=%d, rotate_gzip=%s",
                 max_size, max_files, gzip == FLB_TRUE ? "true" : "false");

    return rot;
}

void file_rotate_destroy(struct file_rotate_ctx *rot)
{
    struct mk_list *head;
    struct mk_list *tmp;
    struct file_rotate_entry *entry;

    if (rot == NULL) {
        return;
    }

    mk_list_foreach_safe(head, tmp, &rot->entries) {
        entry = mk_list_entry(head, struct file_rotate_entry, _head);
        mk_list_del(&entry->_head);
        flb_lock_destroy(&entry->lock);
        flb_sds_destroy(entry->path);
        flb_free(entry);
    }

    if (rot->enabled == FLB_TRUE) {
        flb_hash_table_destroy(rot->index);
        flb_lock_destroy(&rot->index_lock);
    }

    flb_free(rot);
}

static void generate_rotation_suffix(char *suffix, size_t size)
{
    static const char hex[] = "0123456789abcdef";
    unsigned char rnd[4];
    time_t now;
    struct tm tm_info;
    char date_part[16];
    int ok;
    uint32_t v;

    now = time(NULL);
    if (localtime_r(&now, &tm_info) == NULL ||
        strftime(date_part, sizeof(date_part), "%Y%m%d_%H%M%S", &tm_info) == 0) {
        snprintf(date_part, sizeof(date_part), "19700101_000000");
    }

    ok = (flb_random_bytes(rnd, sizeof(rnd)) == 0);
    if (!ok) {
        v = (uint32_t)now ^ (uint32_t)(uintptr_t)suffix;
        rnd[0] = (unsigned char)(v & 0xffU);
        rnd[1] = (unsigned char)((v >> 8) & 0xffU);
        rnd[2] = (unsigned char)((v >> 16) & 0xffU);
        rnd[3] = (unsigned char)((v >> 24) & 0xffU);
    }

    snprintf(suffix, size, "%s_%c%c%c%c%c%c%c%c", date_part,
             hex[(rnd[0] >> 4) & 0xf], hex[rnd[0] & 0xf],
             hex[(rnd[1] >> 4) & 0xf], hex[rnd[1] & 0xf],
             hex[(rnd[2] >> 4) & 0xf], hex[rnd[2] & 0xf],
             hex[(rnd[3] >> 4) & 0xf], hex[rnd[3] & 0xf]);
}

static int rotation_suffix_char_is_hex(unsigned char c)
{
    return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') ||
           (c >= 'A' && c <= 'F');
}

static int is_valid_rotation_filename(const char *filename, const char *pattern)
{
    size_t pattern_len = strlen(pattern);
    size_t filename_len = strlen(filename);
    const char *suffix;
    size_t suffix_len;
    const char *body;
    int i;

    /* Check that filename starts with pattern */
    if (strncmp(filename, pattern, pattern_len) != 0) {
        return 0;
    }

    /* Get the suffix after the pattern */
    suffix = filename + pattern_len;
    suffix_len = filename_len - pattern_len;

    body = suffix;

    if (suffix_len != 15 && suffix_len != 18 && suffix_len != 24 &&
        suffix_len != 27) {
        return 0;
    }

    /* Variants ending in .gz */
    if (suffix_len == 18) {
        if (strcmp(suffix + 15, ".gz") != 0) {
            return 0;
        }
    }
    else if (suffix_len == 27) {
        if (strcmp(suffix + 24, ".gz") != 0) {
            return 0;
        }
    }

    /* Validate timestamp format: YYYYMMDD_HHMMSS (first 15 chars of body) */
    for (i = 0; i < 8; i++) {
        if (body[i] < '0' || body[i] > '9') {
            return 0;
        }
    }
    if (body[8] != '_') {
        return 0;
    }
    for (i = 9; i < 15; i++) {
        if (body[i] < '0' || body[i] > '9') {
            return 0;
        }
    }

    /* New format: extra _ + 8 hex digits after the timestamp */
    if (suffix_len == 24 || suffix_len == 27) {
        if (body[15] != '_') {
            return 0;
        }
        for (i = 16; i < 24; i++) {
            if (!rotation_suffix_char_is_hex((unsigned char)body[i])) {
                return 0;
            }
        }
    }

    return 1;
}

static int file_rotate_compress(struct file_rotate_ctx *rot,
                                const char *src_path, const char *dst_path)
{
    int ret = -1;
    size_t in_len;
    size_t out_len;
    size_t total_in = 0;
    char *in_buf = NULL;
    void *out_buf = NULL;
    FILE *src = NULL;
    FILE *dst = NULL;

    src = fopen(src_path, "rb");
    if (src == NULL) {
        flb_errno();
        flb_plg_error(rot->ins, "could not open %s for compression", src_path);
        return -1;
    }

    dst = fopen(dst_path, "wb");
    if (dst == NULL) {
        flb_errno();
        flb_plg_error(rot->ins, "could not create %s", dst_path);
        fclose(src);
        return -1;
    }

    in_buf = flb_malloc(FILE_ROTATE_GZIP_CHUNK_SIZE);
    if (in_buf == NULL) {
        flb_errno();
        goto cleanup;
    }

    while ((in_len = fread(in_buf, 1, FILE_ROTATE_GZIP_CHUNK_SIZE, src)) > 0) {
        total_in += in_len;
        if (flb_gzip_compress(in_buf, in_len, &out_buf, &out_len) != 0) {
            flb_plg_error(rot->ins, "compression failed for %s", src_path);
            goto cleanup;
        }
        if (fwrite(out_buf, 1, out_len, dst) != out_len) {
            flb_errno();
            flb_free(out_buf);
            goto cleanup;
        }
        flb_free(out_buf);
    }

    if (ferror(src) != 0) {
        flb_plg_error(rot->ins, "read error on %s", src_path);
        goto cleanup;
    }

    /*
     * An empty source would otherwise produce a zero byte file, which is not
     * valid gzip. Emit a single empty member instead.
     */
    if (total_in == 0) {
        if (flb_gzip_compress(in_buf, 0, &out_buf, &out_len) != 0) {
            goto cleanup;
        }
        if (fwrite(out_buf, 1, out_len, dst) != out_len) {
            flb_errno();
            flb_free(out_buf);
            goto cleanup;
        }
        flb_free(out_buf);
    }

    ret = 0;

cleanup:
    flb_free(in_buf);

    if (dst != NULL) {
        if (fclose(dst) != 0) {
            flb_errno();
            flb_plg_error(rot->ins, "could not close %s", dst_path);
            ret = -1;
        }
    }
    fclose(src);

    if (ret != 0) {
        remove(dst_path);
    }

    return ret;
}

static int file_rotate_candidate_cmp(const void *a, const void *b)
{
    const struct file_rotate_candidate *ca = a;
    const struct file_rotate_candidate *cb = b;

    if (ca->mtime < cb->mtime) {
        return -1;
    }
    if (ca->mtime > cb->mtime) {
        return 1;
    }

    return strcmp(ca->path, cb->path);
}

static int file_rotate_candidate_add(struct file_rotate_candidate **list,
                                     int *count, int *capacity,
                                     const char *path)
{
    int new_capacity;
    struct stat st;
    struct file_rotate_candidate *tmp;

    if (stat(path, &st) != 0) {
        /* Vanished between listing and stat; nothing to retain. */
        return 0;
    }

    /* Only regular files are rotation candidates; skip directories etc. */
    if (!S_ISREG(st.st_mode)) {
        return 0;
    }

    if (*count == *capacity) {
        new_capacity = (*capacity == 0) ? 16 : (*capacity * 2);
        tmp = flb_realloc(*list,
                          new_capacity * sizeof(struct file_rotate_candidate));
        if (tmp == NULL) {
            flb_errno();
            return -1;
        }
        *list = tmp;
        *capacity = new_capacity;
    }

    (*list)[*count].path = flb_sds_create(path);
    if ((*list)[*count].path == NULL) {
        flb_errno();
        return -1;
    }

    (*list)[*count].mtime = st.st_mtime;
    (*count)++;

    return 0;
}

static void file_rotate_do(struct file_rotate_entry *entry)
{
    int ret;
    char suffix[FILE_ROTATE_SUFFIX_SIZE];
    char *rotated = NULL;
    char *compressed = NULL;
    char *directory = NULL;
    char *base = NULL;
    char *path_copy = NULL;
    char *last_sep;
    size_t len;
    struct file_rotate_ctx *rot = entry->rot;

    generate_rotation_suffix(suffix, sizeof(suffix));

    len = flb_sds_len(entry->path) + sizeof(suffix) + 8;
    rotated = flb_malloc(len);
    if (rotated == NULL) {
        flb_errno();
        return;
    }

    snprintf(rotated, len, "%s.%s", entry->path, suffix);

#ifdef FLB_SYSTEM_WINDOWS
    if (MoveFileExA(entry->path, rotated, MOVEFILE_REPLACE_EXISTING) == 0) {
        flb_plg_warn(rot->ins, "could not rotate %s", entry->path);
        flb_free(rotated);
        return;
    }
#else
    if (rename(entry->path, rotated) != 0) {
        flb_errno();
        flb_plg_warn(rot->ins, "could not rotate %s", entry->path);
        flb_free(rotated);
        return;
    }
#endif

    flb_plg_info(rot->ins, "rotated %s to %s", entry->path, rotated);
    entry->size = 0;

    if (rot->gzip == FLB_TRUE) {
        compressed = flb_malloc(len + 4);
        if (compressed != NULL) {
            snprintf(compressed, len + 4, "%s.gz", rotated);
            ret = file_rotate_compress(rot, rotated, compressed);
            if (ret == 0) {
                remove(rotated);
            }
            else {
                flb_plg_warn(rot->ins,
                             "keeping uncompressed rotated file %s", rotated);
            }
            flb_free(compressed);
        }
        else {
            flb_errno();
            flb_plg_warn(rot->ins,
                         "keeping uncompressed rotated file %s", rotated);
        }
    }

    path_copy = flb_strdup(entry->path);
    if (path_copy == NULL) {
        flb_errno();
        flb_free(rotated);
        return;
    }

    directory = flb_malloc(PATH_MAX);
    base = flb_malloc(PATH_MAX);
    if (directory == NULL || base == NULL) {
        flb_errno();
        flb_free(directory);
        flb_free(base);
        flb_free(path_copy);
        flb_free(rotated);
        return;
    }

#ifdef FLB_SYSTEM_WINDOWS
    PathRemoveFileSpecA(path_copy);
    snprintf(directory, PATH_MAX, "%s", path_copy);
#else
    snprintf(directory, PATH_MAX, "%s", dirname(path_copy));
#endif

    last_sep = strrchr(entry->path, FLB_PATH_SEPARATOR[0]);
    if (last_sep != NULL) {
        snprintf(base, PATH_MAX, "%s", last_sep + 1);
    }
    else {
        snprintf(base, PATH_MAX, "%s", entry->path);
    }

    /*
     * A trim failure is non-fatal: retention just is not enforced this
     * round and the attempt is retried on the next rotation.
     */
    file_rotate_trim(rot, directory, base);

    flb_free(base);
    flb_free(directory);
    flb_free(path_copy);
    flb_free(rotated);
}

static struct file_rotate_entry *file_rotate_entry_create(
    struct file_rotate_ctx *rot, const char *path)
{
    int ret;
    struct file_rotate_entry *entry;

    entry = flb_calloc(1, sizeof(struct file_rotate_entry));
    if (entry == NULL) {
        flb_errno();
        return NULL;
    }

    entry->path = flb_sds_create(path);
    if (entry->path == NULL) {
        flb_errno();
        flb_free(entry);
        return NULL;
    }

    if (flb_lock_init(&entry->lock) != 0) {
        flb_plg_error(rot->ins, "could not initialize lock for %s", path);
        flb_sds_destroy(entry->path);
        flb_free(entry);
        return NULL;
    }

    entry->rot = rot;

    ret = flb_hash_table_add(rot->index, path, strlen(path), entry, 0);
    if (ret < 0) {
        flb_lock_destroy(&entry->lock);
        flb_sds_destroy(entry->path);
        flb_free(entry);
        return NULL;
    }

    mk_list_add(&entry->_head, &rot->entries);

    return entry;
}

int file_rotate_acquire(struct file_rotate_ctx *rot, const char *path,
                        struct file_rotate_entry **entry)
{
    struct file_rotate_entry *tmp;
    struct stat st;

    *entry = NULL;

    if (rot == NULL || rot->enabled == FLB_FALSE) {
        return 0;
    }

    if (flb_lock_acquire(&rot->index_lock, FLB_LOCK_DEFAULT_RETRY_LIMIT,
                         FLB_LOCK_DEFAULT_RETRY_DELAY) != 0) {
        flb_plg_error(rot->ins, "could not acquire rotation index lock");
        return -1;
    }

    tmp = (struct file_rotate_entry *)
          flb_hash_table_get_ptr(rot->index, path, strlen(path));
    if (tmp == NULL) {
        tmp = file_rotate_entry_create(rot, path);
        if (tmp == NULL) {
            flb_lock_release(&rot->index_lock, FLB_LOCK_DEFAULT_RETRY_LIMIT,
                             FLB_LOCK_DEFAULT_RETRY_DELAY);
            return -1;
        }
    }

    if (flb_lock_acquire(&tmp->lock, FLB_LOCK_DEFAULT_RETRY_LIMIT,
                         FLB_LOCK_DEFAULT_RETRY_DELAY) != 0) {
        flb_plg_error(rot->ins, "could not acquire rotation lock for %s", path);
        flb_lock_release(&rot->index_lock, FLB_LOCK_DEFAULT_RETRY_LIMIT,
                         FLB_LOCK_DEFAULT_RETRY_DELAY);
        return -1;
    }

    flb_lock_release(&rot->index_lock, FLB_LOCK_DEFAULT_RETRY_LIMIT,
                     FLB_LOCK_DEFAULT_RETRY_DELAY);

    /*
     * Seed the size from disk the first time this destination is seen so a
     * file that was already oversized at startup rotates immediately.
     */
    if (tmp->seeded == FLB_FALSE) {
        tmp->seeded = FLB_TRUE;
        if (stat(path, &st) == 0) {
            tmp->size = (size_t) st.st_size;
        }
    }

    if (tmp->size >= rot->max_size) {
        file_rotate_do(tmp);
    }

    *entry = tmp;

    return 0;
}

void file_rotate_update(struct file_rotate_entry *entry, FILE *fp)
{
    struct stat st;

    if (entry == NULL) {
        return;
    }

    if (fp != NULL && fflush(fp) != 0) {
        flb_errno();
        flb_plg_warn(entry->rot->ins, "could not flush %s", entry->path);
        return;
    }

    if (stat(entry->path, &st) == 0) {
        entry->size = (size_t) st.st_size;
    }
}

void file_rotate_release(struct file_rotate_entry *entry)
{
    if (entry == NULL) {
        return;
    }

    flb_lock_release(&entry->lock, FLB_LOCK_DEFAULT_RETRY_LIMIT,
                     FLB_LOCK_DEFAULT_RETRY_DELAY);
}

static inline int tail_file_open(struct flb_tail_config *ctx, const char *path,
                                 int flags)
{
    if (ctx->windows_path_encoding == FLB_TAIL_WINDOWS_PATH_ENCODING_UTF8) {
        return win32_open_utf8(path, flags);
    }

    return open(path, flags);
}

static inline int tail_file_stat(struct flb_tail_config *ctx, const char *path,
                                 struct stat *st)
{
    if (ctx->windows_path_encoding == FLB_TAIL_WINDOWS_PATH_ENCODING_UTF8) {
        return win32_stat_utf8(path, st);
    }

    return stat(path, st);
}

static inline int tail_file_lstat(struct flb_tail_config *ctx, const char *path,
                                  struct stat *st)
{
    if (ctx->windows_path_encoding == FLB_TAIL_WINDOWS_PATH_ENCODING_UTF8) {
        return win32_lstat_utf8(path, st);
    }

    return lstat(path, st);
}

static inline int tail_file_open(struct flb_tail_config *ctx, const char *path,
                                 int flags)
{
    (void) ctx;

    return open(path, flags);
}

static inline int tail_file_stat(struct flb_tail_config *ctx, const char *path,
                                 struct stat *st)
{
    (void) ctx;

    return stat(path, st);
}

static inline int tail_file_lstat(struct flb_tail_config *ctx, const char *path,
                                  struct stat *st)
{
    (void) ctx;

    return lstat(path, st);
}

static int tail_fs_stat_path(struct flb_tail_config *ctx, const char *path,
                             struct stat *st)
{
#ifdef FLB_SYSTEM_WINDOWS
    if (ctx->windows_path_encoding == FLB_TAIL_WINDOWS_PATH_ENCODING_UTF8) {
        return win32_stat_utf8(path, st);
    }
#endif

    return stat(path, st);
}

int win32_open_utf8(const char *path, int flags)
{
    int fd;
    HANDLE h;
    wchar_t *wide_path;

    wide_path = win32_utf8_to_wide(path);
    if (wide_path == NULL) {
        errno = EINVAL;
        return -1;
    }

    h = CreateFileW(wide_path,
                    GENERIC_READ,
                    FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,
                    NULL,           /* lpSecurityAttributes */
                    OPEN_EXISTING,  /* dwCreationDisposition */
                    0,              /* dwFlagsAndAttributes */
                    NULL);          /* hTemplateFile */

    if (h == INVALID_HANDLE_VALUE) {
        win32_propagate_last_error_to_errno();
        flb_free(wide_path);
        return -1;
    }

    flb_free(wide_path);
    fd = _open_osfhandle((intptr_t) h, _O_RDONLY);
    if (fd == -1) {
        CloseHandle(h);
    }

    return fd;
}

wchar_t *win32_utf8_to_wide(const char *str)
{
    int len;
    wchar_t *buf;

    if (str == NULL) {
        return NULL;
    }

    len = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS,
                              str, -1, NULL, 0);
    if (len == 0) {
        return NULL;
    }

    buf = flb_calloc(len, sizeof(wchar_t));
    if (buf == NULL) {
        return NULL;
    }

    if (MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS,
                            str, -1, buf, len) == 0) {
        flb_free(buf);
        return NULL;
    }

    return buf;
}

char *win32_wide_to_utf8(const wchar_t *str)
{
    int len;
    char *buf;

    if (str == NULL) {
        return NULL;
    }

    len = WideCharToMultiByte(CP_UTF8, WC_ERR_INVALID_CHARS,
                              str, -1, NULL, 0, NULL, NULL);
    if (len == 0) {
        return NULL;
    }

    buf = flb_calloc(len, sizeof(char));
    if (buf == NULL) {
        return NULL;
    }

    if (WideCharToMultiByte(CP_UTF8, WC_ERR_INVALID_CHARS,
                            str, -1, buf, len, NULL, NULL) == 0) {
        flb_free(buf);
        return NULL;
    }

    return buf;
}

size_t win32_remove_extended_path_prefix(wchar_t *path, size_t length)
{
    if (path == NULL) {
        return 0;
    }

    if (length >= 8 && wcsncmp(path, L"\\\\?\\UNC\\", 8) == 0) {
        memmove(path + 2, path + 8, (length - 7) * sizeof(wchar_t));
        path[0] = L'\\';
        path[1] = L'\\';

        return length - 6;
    }

    if (length >= 4 && wcsncmp(path, L"\\\\?\\", 4) == 0) {
        memmove(path, path + 4, (length - 3) * sizeof(wchar_t));

        return length - 4;
    }

    return length;
}

char *win32_fullpath_utf8(const char *path)
{
    DWORD len;
    DWORD ret;
    wchar_t *wide_path;
    wchar_t *wide_fullpath;
    char *fullpath;

    wide_path = win32_utf8_to_wide(path);
    if (wide_path == NULL) {
        return NULL;
    }

    len = GetFullPathNameW(wide_path, 0, NULL, NULL);
    if (len == 0) {
        flb_free(wide_path);
        return NULL;
    }

    wide_fullpath = flb_calloc(len, sizeof(wchar_t));
    if (wide_fullpath == NULL) {
        flb_free(wide_path);
        return NULL;
    }

    ret = GetFullPathNameW(wide_path, len, wide_fullpath, NULL);
    flb_free(wide_path);

    if (ret == 0 || ret >= len) {
        flb_free(wide_fullpath);
        return NULL;
    }

    fullpath = win32_wide_to_utf8(wide_fullpath);
    flb_free(wide_fullpath);

    return fullpath;
}

static int is_symlink_utf8(const char *path)
{
    WIN32_FIND_DATAW data;
    HANDLE h;
    wchar_t *wide_path;

    SetLastError(0);
    reset_errno();

    wide_path = win32_utf8_to_wide(path);
    if (wide_path == NULL) {
        errno = EINVAL;
        return 0;
    }

    h = FindFirstFileW(wide_path, &data);
    flb_free(wide_path);

    if (h == INVALID_HANDLE_VALUE) {
        win32_propagate_last_error_to_errno();

        return 0;
    }

    FindClose(h);

    if (data.dwFileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) {
        if (data.dwReserved0 == IO_REPARSE_TAG_SYMLINK) {
            return 1;
        }
    }

    return 0;
}

int win32_lstat_utf8(const char *path, struct win32_stat *wst)
{
    HANDLE h;
    wchar_t *wide_path;

    SetLastError(0);
    reset_errno();

    wide_path = win32_utf8_to_wide(path);
    if (wide_path == NULL) {
        errno = EINVAL;
        return -1;
    }

    h = CreateFileW(wide_path,
                    GENERIC_READ,
                    FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,
                    NULL,           /* lpSecurityAttributes */
                    OPEN_EXISTING,  /* dwCreationDisposition */
                    FILE_FLAG_OPEN_REPARSE_POINT,
                    NULL);          /* hTemplateFile */
    flb_free(wide_path);

    if (h == INVALID_HANDLE_VALUE) {
        win32_propagate_last_error_to_errno();

        return -1;
    }

    if (hstat(h, wst)) {
        CloseHandle(h);
        return -1;
    }

    if (is_symlink_utf8(path)) {
        wst->st_mode = WIN32_S_IFLNK;
    }

    CloseHandle(h);
    return 0;
}

void flb_test_windows_extended_path_prefixes(void)
{
    size_t length;
    wchar_t local_path[] = L"\\\\?\\C:\\logs\\unicode.log";
    wchar_t unc_path[] = L"\\\\?\\UNC\\server\\share\\unicode.log";
    const wchar_t expected_local_path[] = L"C:\\logs\\unicode.log";
    const wchar_t expected_unc_path[] = L"\\\\server\\share\\unicode.log";

    length = win32_remove_extended_path_prefix(local_path, wcslen(local_path));
    TEST_CHECK(length == wcslen(expected_local_path));
    TEST_CHECK(wcscmp(local_path, expected_local_path) == 0);

    length = win32_remove_extended_path_prefix(unc_path, wcslen(unc_path));
    TEST_CHECK(length == wcslen(expected_unc_path));
    TEST_CHECK(wcscmp(unc_path, expected_unc_path) == 0);
}

int main(void)
{
    unsigned passed = 0;
    unsigned failed = 0;
    abuf_t b;
    char buf[16];

    fprintf(stderr, "abuf:: test\n");

    // A plain append that fits the whole string and no overflow, and returns
    // the source length (excluding the NUL), like abuf_printf().
    fprintf(stderr, "abuf::abuf_cat(): fits\n");
    abuf_init(&b, buf, sizeof(buf));
    ASSERT_EQUALS(abuf_cat(&b, "abc"), 3);
    ASSERT_STR(buf, "abc");
    ASSERT_EQUALS(b.overflow, 0);

    // Boundary: an exact fit (len + 1 == avail, the reserved NUL lands on the
    // last byte) keeps the whole string and is NOT flagged as overflow.
    fprintf(stderr, "abuf::abuf_cat(): exact fit\n");
    char four[4];
    abuf_init(&b, four, sizeof(four));
    ASSERT_EQUALS(abuf_cat(&b, "abc"), 3);
    ASSERT_STR(four, "abc");
    ASSERT_EQUALS(b.overflow, 0);

    // Boundary: one byte over (len + 1 > avail) truncates to fit, always
    // NUL-terminates, sets overflow, and still returns the would-be length.
    fprintf(stderr, "abuf::abuf_cat(): one over\n");
    char three[3];
    abuf_init(&b, three, sizeof(three));
    ASSERT_EQUALS(abuf_cat(&b, "abc"), 3);
    ASSERT_STR(three, "ab");
    ASSERT_EQUALS(b.overflow, 1);

    // Regression for the get_stats JSON corruption: once a chunk is truncated,
    // a later smaller chunk must NOT slip into the leftover room. The result is
    // a clean prefix and overflow stays sticky.
    fprintf(stderr, "abuf::abuf_cat(): no append after truncation\n");
    abuf_init(&b, buf, sizeof(buf));
    abuf_cat(&b, "0123456789ABCDEF"); // 16 chars into a 16-byte buf: truncates
    ASSERT_EQUALS(b.overflow, 1);
    ASSERT_STR(buf, "0123456789ABCDE"); // last byte reserved for the NUL
    abuf_cat(&b, "}");                  // the small closing chunk must not land
    ASSERT_STR(buf, "0123456789ABCDE");
    ASSERT_EQUALS(b.overflow, 1);

    // A zero-length buffer can hold nothing, not even the NUL: every append
    // overflows and writes nothing, but still reports the source length.
    fprintf(stderr, "abuf::abuf_cat(): zero-length buffer\n");
    abuf_init(&b, buf, 0);
    ASSERT_EQUALS(abuf_cat(&b, "x"), 1);
    ASSERT_EQUALS(b.overflow, 1);

    fprintf(stderr, "abuf:: test (%u passed, %u failed)\n", passed, failed);
    return failed;
}

R_API char *data_print_jsons_dup(data_t *data)
{
    // Grow the buffer until the whole document fits, so reports that scale with
    // configuration (e.g. get_stats with many enabled decoders) are never
    // truncated into invalid JSON. A fixed buffer silently corrupts the output
    // once it overflows: abuf drops the oversized chunk but keeps appending the
    // smaller ones that follow.
    size_t len = 8192;
    for (;;) {
        char *buf = malloc(len);
        if (!buf) {
            WARN_MALLOC("data_print_jsons_dup()");
            return NULL;
        }
        int overflow = 0;
        data_print_jsons_buf(data, buf, len, &overflow);
        if (!overflow) {
            return buf; // complete and NUL-terminated
        }
        free(buf);
        if (len > ((size_t)1 << 26)) { // 64 MiB sanity cap; no report is this big
            return NULL;
        }
        len *= 2;
    }
}

static int test_jsons_large_report(void)
{
    int failed = 0;
    int n      = 230; // more than enough to exceed any reasonable fixed buffer

    data_t **objs = calloc(n, sizeof(*objs));
    for (int i = 0; i < n; ++i) {
        objs[i] = data_make(
                "device",       "", DATA_INT,    i,
                "name",         "", DATA_STRING, "Some Reasonably Long Decoder Name For A Protocol",
                "events",       "", DATA_INT,    8256,
                "abort_length", "", DATA_INT,    8256,
                NULL);
    }
    data_t *data = data_make(
            "enabled", "", DATA_INT,   n,
            "stats",   "", DATA_ARRAY, data_array(n, DATA_DATA, objs),
            NULL);

    // The grown buffer must hold the whole document: starts with '{', ends with
    // '}', and is far larger than the smallest fixed buffer we test below.
    char *full = data_print_jsons_dup(data);
    if (!full) {
        fprintf(stderr, "FAIL: data_print_jsons_dup returned NULL\n");
        failed++;
    }
    else {
        size_t full_len = strlen(full);
        if (full[0] != '{' || full[full_len - 1] != '}') {
            fprintf(stderr, "FAIL: grown JSON is not a complete object: ...%.20s\n",
                    full + (full_len > 20 ? full_len - 20 : 0));
            failed++;
        }
        if (full_len <= 20480) {
            fprintf(stderr, "FAIL: test report (%zu bytes) too small to exercise growth\n", full_len);
            failed++;
        }

        // Confirm the failure mode the fix addresses: a fixed buffer that is too
        // small yields a truncated document that does NOT end with '}'.
        char small[1024];
        size_t w = data_print_jsons(data, small, sizeof(small));
        if (w > 0 && w <= sizeof(small) && small[w - 1] == '}') {
            fprintf(stderr, "FAIL: undersized buffer unexpectedly produced a complete object\n");
            failed++;
        }
    }

    free(full);
    free(objs);
    data_free(data);
    return failed;
}

static size_t *openblas_cancel_slot_addr(void) {
  size_t *slot;
  pthread_once(&openblas_cancel_key_once, openblas_cancel_key_init);
  if (!openblas_cancel_key_ok) return NULL;
  slot = (size_t *)pthread_getspecific(openblas_cancel_key);
  if (slot == NULL) {
    slot = (size_t *)calloc(1, sizeof(size_t));
    if (slot == NULL) return NULL;
    if (pthread_setspecific(openblas_cancel_key, slot) != 0) {
      free(slot);
      return NULL;
    }
  }
  return slot;
}

static int openblas_cancel_cas_fallback(size_t *ptr, size_t *expp, size_t val) {
  if (*(volatile size_t *)ptr != *expp) return 0;
  WMB;
  *(volatile size_t *)ptr = val;
  return 1;
}

size_t openblas_cancel_begin(void) {
  size_t *slot = openblas_cancel_slot_addr();
  size_t gen;
  if (slot == NULL) return 0;
  gen = (*slot | (size_t)1) + 1;
  OPENBLAS_CANCEL_STORE(slot, gen);
  return gen;
}

void IntervalSelectionActivity::drawStepHintLine(const int y, const StrId labelId, const int step) {
  char stepText[24];
  if (valueFormatId != StrId::STR_NONE_OPT) {
    snprintf(stepText, sizeof(stepText), I18N.get(valueFormatId), static_cast<unsigned int>(step));
  } else {
    snprintf(stepText, sizeof(stepText), "%d", step);
  }
  char line[64];
  snprintf(line, sizeof(line), "%s %s", I18N.get(labelId), stepText);
  renderer.drawCenteredText(SMALL_FONT_ID, y, line, true);
}

