LOCAL void websocket_save(ArkimeSession_t *session, void *uw, int UNUSED(final))
{
    WebSocketInfo_t *ws = uw;
    if (!ws)
        return;
    if (ws->frameCnt) {
        arkime_field_int_add(frameCntField, session, (int)ws->frameCnt);
    }
    if (ws->payloadBytes) {
        int v = (ws->payloadBytes > 0x7fffffff) ? 0x7fffffff : (int)ws->payloadBytes;
        arkime_field_int_add(payloadBytesField, session, v);
    }
    if (ws->maskedFrames) {
        arkime_field_int_add(maskedFromClientField, session, (int)ws->maskedFrames);
    }
}

LOCAL void websocket_free(ArkimeSession_t *session, void *uw)
{
    WebSocketInfo_t *ws = uw;
    if (!ws)
        return;

    websocket_save(session, ws, 1);

    if (ws->buf) {
        arkime_parser_buf_free(ws->buf);
        ws->buf = NULL;
    }
    ARKIME_TYPE_FREE(WebSocketInfo_t, ws);
}

LOCAL int websocket_header_len(const uint8_t *p, int avail, uint64_t *outPayLen, int *outMasked, int *outOpcode, int *outFin)
{
    if (avail < 2)
        return 0;
    *outFin    = (p[0] & 0x80) ? 1 : 0;
    *outOpcode = p[0] & 0x0F;
    *outMasked = (p[1] & 0x80) ? 1 : 0;
    int len7   = p[1] & 0x7F;

    int hdr = 2;
    uint64_t payLen = 0;

    if (len7 < 126) {
        payLen = len7;
    } else if (len7 == 126) {
        if (avail < hdr + 2)
            return 0;
        payLen = ((uint64_t)p[2] << 8) | p[3];
        hdr += 2;
    } else { // 127
        if (avail < hdr + 8)
            return 0;
        payLen = 0;
        for (int i = 0; i < 8; i++)
            payLen = (payLen << 8) | p[2 + i];
        hdr += 8;
    }

    if (*outMasked) {
        if (avail < hdr + 4)
            return 0;
        hdr += 4;
    }

    *outPayLen = payLen;
    return hdr;
}

LOCAL int websocket_tcp_parser(ArkimeSession_t *session, void *uw, const uint8_t *data, int len, int which)
{
    WebSocketInfo_t   *ws  = uw;
    ArkimeParserBuf_t *buf = ws->buf;

    arkime_parser_buf_add(buf, which, data, len);

    while (buf->len[which] >= 2) {
        uint64_t payLen = 0;
        int masked = 0, opcode = 0, fin = 0;

        int hdrLen = websocket_header_len(buf->buf[which], buf->len[which],
                                          &payLen, &masked, &opcode, &fin);
        if (hdrLen == 0)
            return 0; // need more data for header

        // Sanity: cap payloads we'll attempt to handle. Anything within
        // RFC limits is fine. We just don't want to wedge on absurd values.
        if (payLen > (uint64_t)0x7fffffff) {
            arkime_session_add_tag(session, "websocket:bad-length");
            arkime_parsers_unregister(session, ws);
            return 0;
        }

        const uint8_t *hdr = buf->buf[which];
        uint8_t maskKey[4] = {0};
        if (masked) {
            const int koff = hdrLen - 4;
            for (int i = 0; i < 4; i++) maskKey[i] = hdr[koff + i];
        }

        if (opcode != 0) {
            ws->curOpcode[which & 1] = opcode;
            if (opcode < (int)ARRAY_LEN(opcodeNames))
                arkime_field_string_add(opcodeField, session, opcodeNames[opcode], -1, TRUE);
        }

        ws->frameCnt++;
        ws->payloadBytes += payLen;
        if (masked) ws->maskedFrames++;

        const int effOpcode = (opcode == 0) ? ws->curOpcode[which & 1] : opcode;

        // If this is a text frame and full payload fits in buf, extract a sample
        // (after unmasking).  Same handling for close frames.
        const int needFull = (effOpcode == 1 || opcode == 8);
        if (needFull && (uint64_t)(buf->len[which] - hdrLen) >= payLen) {
            const uint8_t *pay = buf->buf[which] + hdrLen;

            if (effOpcode == 1 && ws->textSampleCnt < websocketTextSampleCnt && payLen > 0) {
                int sampleLen = (payLen > WEBSOCKET_TEXT_SAMPLE_MAX) ?
                                WEBSOCKET_TEXT_SAMPLE_MAX : (int)payLen;
                char sample[WEBSOCKET_TEXT_SAMPLE_MAX];
                for (int i = 0; i < sampleLen; i++) {
                    uint8_t c = pay[i];
                    if (masked) c ^= maskKey[i & 3];
                    if (c < 0x20 && c != '\t' && c != '\n' && c != '\r')
                        c = '.';
                    sample[i] = (char)c;
                }
                // RFC 6455 §5.6 requires Text frames to be UTF-8; skip sample if
                // the peer sent something else (binary blob mislabeled as Text,
                // or a payload truncated mid-multibyte sequence at sampleLen).
                const gchar *utf8End = NULL;
                if (g_utf8_validate(sample, sampleLen, &utf8End)) {
                    arkime_field_string_add(textSampleField, session, sample, sampleLen, TRUE);
                    ws->textSampleCnt++;
                } else if (utf8End && utf8End > sample) {
                    int validLen = (int)(utf8End - sample);
                    arkime_field_string_add(textSampleField, session, sample, validLen, TRUE);
                    ws->textSampleCnt++;
                }
            } else if (opcode == 8) {
                if (payLen >= 2) {
                    uint8_t b0 = pay[0], b1 = pay[1];
                    if (masked) { b0 ^= maskKey[0]; b1 ^= maskKey[1]; }
                    int code = (b0 << 8) | b1;
                    arkime_field_int_add(closeCodeField, session, code);

                    if (payLen > 2) {
                        int rlen = (int)payLen - 2;
                        if (rlen > 123) rlen = 123; // RFC max for close reason
                        char reason[128];
                        for (int i = 0; i < rlen; i++) {
                            uint8_t c = pay[2 + i];
                            if (masked) c ^= maskKey[(2 + i) & 3];
                            if (c < 0x20 && c != '\t')
                                c = '.';
                            reason[i] = (char)c;
                        }
                        // RFC 6455 §5.5.1 requires close reason text to be UTF-8.
                        const gchar *utf8End = NULL;
                        if (g_utf8_validate(reason, rlen, &utf8End)) {
                            if (rlen > 0)
                                arkime_field_string_add(closeReasonField, session, reason, rlen, TRUE);
                        } else if (utf8End && utf8End > reason) {
                            arkime_field_string_add(closeReasonField, session, reason, (int)(utf8End - reason), TRUE);
                        }
                    }
                }
            }
        }

        // Advance past this frame.  Use _skip so payloads larger than the
        // buffer still drain across subsequent segments.
        uint64_t total = (uint64_t)hdrLen + payLen;
        if (total <= (uint64_t)buf->len[which]) {
            arkime_parser_buf_del(buf, which, (int)total);
        } else {
            arkime_parser_buf_skip(buf, which, (int)total);
            // After a partial skip we have no more bytes buffered; return.
            return 0;
        }
    }

    return 0;
}
/

CAL int websocket_register_sub(ArkimeSession_t *session,
                                 void *UNUSED(uw),
                                 const uint8_t *UNUSED(data),
                                 int UNUSED(remaining),
                                 int UNUSED(which))
{
    if (arkime_parsers_has_registered(session, websocket_tcp_parser))
        return 0;

    WebSocketInfo_t *ws = ARKIME_TYPE_ALLOC0(WebSocketInfo_t);
    ws->buf = arkime_parser_buf_create();
    arkime_parsers_register2(session, websocket_tcp_parser, ws, websocket_free, websocket_save);
    return 0;
}
/

FILE *arkime_state_file_open(const char *name, const char *mode)
{
    static const char *stateDir = NULL;
    if (!stateDir) {
        stateDir = arkime_config_str(NULL, "stateDir", "/tmp");
    }

    char path[PATH_MAX];
    int  plen = snprintf(path, sizeof(path), "%s/%s", stateDir, name);
    if (plen <= 0 || plen >= (int)sizeof(path)) {
        LOG("ERROR - state file path too long for `%s/%s`", stateDir, name);
        return NULL;
    }

    int flags;
    if (mode[0] == 'w') {
        flags = O_WRONLY | O_CREAT | O_TRUNC | O_NOFOLLOW | O_CLOEXEC;
    } else if (mode[0] == 'r') {
        flags = O_RDONLY | O_NOFOLLOW | O_CLOEXEC;
    } else {
        LOG("ERROR - unsupported mode `%s` for state file `%s`", mode, path);
        return NULL;
    }

    int fd = open(path, flags, 0600);
    if (fd < 0) {
        if (errno == ENOENT && mode[0] == 'r') {
            return NULL;
        }
        LOG("ERROR - Couldn't open state file `%s` (%s): %s", path, mode, strerror(errno));
        return NULL;
    }

    FILE *fp = fdopen(fd, mode);
    if (!fp) {
        LOG("ERROR - fdopen failed for state file `%s`: %s", path, strerror(errno));
        close(fd);
        return NULL;
    }
    return fp;
}

gboolean arkime_parsers_has_registered(ArkimeSession_t *session, ArkimeParserFunc func)
{
    for (int i = 0; i < session->parserNum; i++) {
        if (session->parserInfo[i].parserFunc == func)
            return TRUE;
    }
    return FALSE;
}

gboolean arkime_session_rm_protocol(ArkimeSession_t *session, const char *protocol)
{
    if (!session->fields[protocolField])
        return FALSE;

    ArkimeStringHashStd_t   *shash = session->fields[protocolField]->shash;
    ArkimeString_t          *hstring;
    HASH_FIND(s_, *shash, protocol, hstring);
    if (!hstring)
        return FALSE;

    HASH_REMOVE(s_, *shash, hstring);
    g_free(hstring->str);
    ARKIME_TYPE_FREE(ArkimeString_t, hstring);
    return TRUE;
}

LOCAL void scheme_s3_done(int code, uint8_t *data, int data_len, gpointer uw)
    if (code < 200 || code >= 300) {
        LOG("ERROR - S3 list request failed with HTTP %d for %s", code, req->url);
        ARKIME_LOCK(s3Items->lock);
        s3Items->done = 1;
        ARKIME_COND_BROADCAST(s3Items->lock);
        ARKIME_UNLOCK(s3Items->lock);
        return;
    }

ArkimeParserBuf_t *arkime_parser_buf_create2(uint16_t initialSize, uint16_t maxSize)
{
    if (initialSize == 0)
        initialSize = 1;
    if (maxSize < initialSize)
        maxSize = initialSize;

    ArkimeParserBuf_t *pb = ARKIME_TYPE_ALLOC0(ArkimeParserBuf_t);
    pb->buf[0] = malloc(initialSize);
    pb->buf[1] = malloc(initialSize);
    pb->bufSize[0] = pb->bufSize[1] = initialSize;
    pb->bufMax = maxSize;
LOCAL void arkime_parser_buf_grow(ArkimeParserBuf_t *pb, int which, int needed)
{
    if (needed <= pb->bufSize[which])
        return;

    // Double until we have enough, then clamp to bufMax
    int newSize = pb->bufSize[which];
    while (newSize < needed)
        newSize *= 2;
    if (newSize > pb->bufMax)
        newSize = pb->bufMax;
    if (newSize <= pb->bufSize[which])
        return;

    uint8_t *nb = realloc(pb->buf[which], newSize);
    if (!nb)
        return; // keep old buffer
    pb->buf[which] = nb;
    pb->bufSize[which] = newSize;
}
/******************************************************************************/
    // Grow the buffer if needed (up to bufMax)
    if (pb->len[which] + len > pb->bufSize[which]) {
        arkime_parser_buf_grow(pb, which, pb->len[which] + len);
    }

    int available = (int)pb->bufSize[which] - pb->len[which];
    if (pb->buf[0]) free(pb->buf[0]);
    if (pb->buf[1]) free(pb->buf[1]);
    ArkimeParserBuf_t *pb = uw;
    if (pb->buf[0]) free(pb->buf[0]);
    if (pb->buf[1]) free(pb->buf[1]);
    ARKIME_TYPE_FREE(ArkimeParserBuf_t, pb);

LOCAL void arkime_parser_buf_grow(ArkimeParserBuf_t *pb, int which, int needed)
{
    if (needed <= pb->bufSize[which])
        return;

    // Double until we have enough, then clamp to bufMax
    int newSize = pb->bufSize[which];
    while (newSize < needed)
        newSize *= 2;
    if (newSize > pb->bufMax)
        newSize = pb->bufMax;
    if (newSize <= pb->bufSize[which])
        return;

    uint8_t *nb = realloc(pb->buf[which], newSize);
    if (!nb)
        return; // keep old buffer
    pb->buf[which] = nb;
    pb->bufSize[which] = newSize;
}

LOCAL int c1222_peek_total_len(const uint8_t *data, int len)
{
    if (len < 2)
        return 0;

    // Multi-byte tags (low 5 bits == 0x1f) are not expected for the outer 0x60
    // C12.22 wrapper; treat them as malformed.
    if ((data[0] & 0x1f) == 0x1f)
        return -1;

    int idx = 1; // skip tag
    uint8_t lb = data[idx++];
    uint32_t content_len;

    if ((lb & 0x80) == 0) {
        content_len = lb;
    } else {
        int cnt = lb & 0x7f;
        if (cnt == 0 || cnt > 4)
            return -1; // indefinite or unsupported
        if (idx + cnt > len)
            return 0; // need more data to decode length
        content_len = 0;
        for (int i = 0; i < cnt; i++) {
            content_len = (content_len << 8) | data[idx++];
        }
    }

    uint64_t total = (uint64_t)idx + content_len;
    if (total > (uint64_t)INT_MAX)
        return -1;
    return (int)total;
}

API::CommandResponse API::Handlers::CSVExportHandler::setInterval(const QString& id,
                                                                  const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("intervalMs"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: intervalMs"));
  }

  const int interval = params.value(QStringLiteral("intervalMs")).toInt(-1);
  if (interval < 0) {
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("Invalid intervalMs: must be an integer >= 0 (0 = one row per frame)"));
  }

  static auto& csvExport = CSV::Export::instance();
  csvExport.setExportInterval(interval);

  QJsonObject result;
  result[QStringLiteral("intervalMs")] = csvExport.exportInterval();
  return CommandResponse::makeSuccess(id, result);
}

CSV::ExportWorker::ExportWorker(
  moodycamel::ReaderWriterQueue<DataModel::TimestampedFramePtr>* queue,
  std::atomic<bool>* enabled,
  std::atomic<size_t>* queueSize)
  : DataModel::FrameConsumerWorker<DataModel::TimestampedFramePtr>(queue, enabled, queueSize)
  , m_snapshotIntervalMs(0)
  , m_snapshotTimer(new QTimer(this))
{
  m_snapshotTimer->setTimerType(Qt::PreciseTimer);
  connect(m_snapshotTimer, &QTimer::timeout, this, &ExportWorker::writeSnapshotRow);
}

void CSV::ExportWorker::setSnapshotIntervalMs(int interval)
{
  m_snapshotIntervalMs = qMax(0, interval);

  if (m_snapshotIntervalMs > 0) {
    m_snapshotTimer->setInterval(m_snapshotIntervalMs);
    m_snapshotTimer->start();
  }

  else
    m_snapshotTimer->stop();
}

void CSV::ExportWorker::writeSnapshotRow()
{
  if (!consumerEnabled() || m_snapshotIntervalMs <= 0)
    return;

  processData();

  if (!m_csvFile.isOpen() || m_schema.columns.empty())
    return;

  writeRow(DataModel::TimestampedFrame::SteadyClock::now());
  m_textStream.flush();
}

void CSV::Export::setExportInterval(const int interval)
{
  const int clamped = qMax(0, interval);
  m_exportInterval  = clamped;

  auto* worker = static_cast<ExportWorker*>(m_worker);
  QMetaObject::invokeMethod(
    worker, [worker, clamped] { worker->setSnapshotIntervalMs(clamped); }, Qt::QueuedConnection);

  if (m_persistSettings)
    m_settings.setValue("CSVExportInterval", clamped);

  Q_EMIT intervalChanged();
}

void DataModel::FrameBuilder::drainPendingTick()
{
  if (!m_tickPending)
    return;

  m_tickPending = false;
  (void)republishFrames(true);
    m_tickPending = false;

[[nodiscard]] static QString formatTimestamp(double seconds)
{
  constexpr double kInvHour = 1.0 / 3600.0;
  constexpr double kInvMin  = 1.0 / 60.0;

  int hours   = static_cast<int>(seconds * kInvHour);
  int minutes = static_cast<int>((seconds - hours * 3600.0) * kInvMin);
  double secs = seconds - hours * 3600.0 - minutes * 60.0;

  return QString("%1:%2:%3")
    .arg(hours, 2, 10, QChar('0'))
    .arg(minutes, 2, 10, QChar('0'))
    .arg(secs, 6, 'f', 3, QChar('0'));
}

static void fillSeekGaps(QVector<double>& values)
{
  int firstSet = -1;
  const int n  = values.size();
  for (int k = 0; k < n; ++k)
    if (std::isnan(values[k]))
      values[k] = (k > 0) ? values[k - 1] : values[k];
    else if (firstSet < 0)
      firstSet = k;

  const double seed = (firstSet >= 0) ? values[firstSet] : 0.0;
  for (int k = 0; k < n && std::isnan(values[k]); ++k)
    values[k] = seed;
}

[[nodiscard]] static double seekCellValue(const QByteArrayView* spans, qsizetype count, int column)
{
  Q_ASSERT(spans != nullptr || count == 0);
  Q_ASSERT(column >= 0);

  if (column >= count || spans[column].isEmpty())
    return std::numeric_limits<double>::quiet_NaN();

  bool ok             = false;
  const double parsed = SerialStudio::toDouble(spans[column], &ok);
  return ok ? parsed : std::numeric_limits<double>::quiet_NaN();
}

[[nodiscard]] static qsizetype firstTopLevelComma(QByteArrayView row)
{
  bool in_quotes       = false;
  bool was_quoted      = false;
  bool only_space_seen = true;

  const qsizetype length = row.size();
  for (qsizetype i = 0; i < length; ++i) {
    const char c = row.at(i);

    if (in_quotes) {
      const bool escaped = c == '"' && i + 1 < length && row.at(i + 1) == '"';
      if (escaped) {
        ++i;
        continue;
      }

      if (c == '"')
        in_quotes = false;

      continue;
    }

    if (c == ',')
      return i;

    if (c == '"' && !was_quoted && only_space_seen) {
      in_quotes  = true;
      was_quoted = true;
      continue;
    }

    if (c != ' ' && c != '\t' && c != '\n' && c != '\v' && c != '\f' && c != '\r')
      only_space_seen = false;
  }

  return -1;
}

double CSV::Player::indexProgress() const
{
  if (m_mappedSize <= 0)
    return 1.0;

  return std::clamp(static_cast<double>(m_bytesIndexed) / m_mappedSize, 0.0, 1.0);
}

void CSV::Player::frontierPause()
{
  m_pausedAtFrontier = m_indexing;
  pause();
}

void CSV::Player::startIndexing()
{
  Q_ASSERT(m_mapped != nullptr);
  Q_ASSERT(m_loaderThread == nullptr);

  ++m_indexGeneration;
  m_loaderThread = new QThread(this);
  m_loaderThread->setObjectName(QStringLiteral("CSV::PlayerLoader"));
  m_loader = new PlayerLoaderWorker();
  m_loader->moveToThread(m_loaderThread);

  connect(m_loader,
          &PlayerLoaderWorker::batchReady,
          this,
          &CSV::Player::onIndexBatch,
          Qt::QueuedConnection);
  connect(m_loader,
          &PlayerLoaderWorker::finished,
          this,
          &CSV::Player::onIndexFinished,
          Qt::QueuedConnection);

  m_loaderThread->start();

  auto request                = std::make_shared<PlayerIndexRequest>();
  request->data               = m_mapped;
  request->size               = m_mappedSize;
  request->dataOffset         = m_dataOffset;
  request->timestampColumn    = m_timestampColumn;
  request->intervalSeconds    = m_intervalSeconds;
  request->anchorMsSinceEpoch = m_anchorMs;
  request->generation         = m_indexGeneration;
  request->mode               = m_tsMode;

  m_indexing         = true;
  m_pausedAtFrontier = false;
  m_bytesIndexed     = m_dataOffset;

  auto* loader = m_loader;
  QMetaObject::invokeMethod(
    loader, [loader, request]() { loader->indexFile(request); }, Qt::QueuedConnection);
}

bool CSV::Player::stopIndexing()
{
  if (!m_loaderThread)
    return true;

  constexpr int kJoinTimeoutMs = 5000;

  if (m_loader)
    m_loader->requestCancel();

  m_loaderThread->quit();
  const bool joined = m_loaderThread->wait(kJoinTimeoutMs);
  if (joined) {
    delete m_loader;
    delete m_loaderThread;
    qWarning() << "[CSV::Player] Indexer thread did not stop in time; detaching it.";
    disconnect(m_loader, nullptr, this, nullptr);
    m_loaderThread->setParent(nullptr);
    connect(m_loaderThread, &QThread::finished, m_loader, &QObject::deleteLater);
    connect(m_loaderThread, &QThread::finished, m_loaderThread, &QObject::deleteLater);
  }

  m_loader       = nullptr;
  m_loaderThread = nullptr;
  m_indexing     = false;
  return joined;
}

void CSV::Player::onIndexBatch(const CSV::PlayerIndexBatchPtr& batch)
{
  Q_ASSERT(batch != nullptr);

  if (!isOpen() || batch->generation != m_indexGeneration)
    return;

  const bool was_empty = m_rowOffsets.isEmpty();
  if (was_empty && !batch->rowOffsets.isEmpty() && batch->bytesIndexed > m_dataOffset) {
    const double avg_row =
      static_cast<double>(batch->bytesIndexed - m_dataOffset) / batch->rowOffsets.size();
    const double estimate   = static_cast<double>(m_mappedSize - m_dataOffset) / qMax(1.0, avg_row);
    const auto reserve_rows = static_cast<qsizetype>(estimate * 1.1) + 1024;
    m_rowOffsets.reserve(reserve_rows);
    m_rowSeconds.reserve(reserve_rows);
  }

  m_rowOffsets   += batch->rowOffsets;
  m_rowSeconds   += batch->rowSeconds;
  m_bytesIndexed  = batch->bytesIndexed;

  if (!m_playing && m_pausedAtFrontier
      && (frameCount() > m_framePos + 1 || (was_empty && frameCount() > 0))) {
    m_pausedAtFrontier = false;
    play();
  }

  Q_EMIT playerStateChanged();
  Q_EMIT indexingChanged();
  Q_EMIT timestampChanged();

  if (was_empty && frameCount() > 0)
    updateData();
}

[[nodiscard]] static bool parseIntField(QByteArrayView cell, qsizetype& i, int digits, int& out)
{
  Q_ASSERT(digits > 0);
  Q_ASSERT(i >= 0);

  int parsed = 0;
  int value  = 0;
  for (; i < cell.size() && parsed < digits; ++parsed, ++i) {
    const char c = cell.at(i);
    if (c < '0' || c > '9')
      break;

    value = value * 10 + (c - '0');
  }

  if (parsed != digits)
    return false;

  out = value;
  return true;
}

[[nodiscard]] static bool parseLiteral(QByteArrayView cell, qsizetype& i, char literal)
{
  if (i >= cell.size() || cell.at(i) != literal)
    return false;

  ++i;
  return true;
}

bool CSV::parseLegacyDateTimeMs(QByteArrayView cell, qint64& msOut)
{
  qsizetype i = 0;
  int year = 0, month = 0, day = 0, hour = 0, minute = 0, second = 0, milli = 0;

  const bool date_ok = parseIntField(cell, i, 4, year) && parseLiteral(cell, i, '/')
                    && parseIntField(cell, i, 2, month) && parseLiteral(cell, i, '/')
                    && parseIntField(cell, i, 2, day);

  bool fast_ok = date_ok;
  if (fast_ok && i < cell.size() && cell.at(i) == '/')
    ++i;

  fast_ok = fast_ok && parseLiteral(cell, i, ' ') && parseIntField(cell, i, 2, hour)
         && parseLiteral(cell, i, ':') && parseIntField(cell, i, 2, minute)
         && parseLiteral(cell, i, ':') && parseIntField(cell, i, 2, second);

  if (fast_ok && i < cell.size()) {
    fast_ok = parseLiteral(cell, i, ':') && parseLiteral(cell, i, ':')
           && parseIntField(cell, i, 3, milli) && i == cell.size();
  }

  if (fast_ok) {
    const QDateTime dt(QDate(year, month, day), QTime(hour, minute, second, milli));
    if (dt.isValid()) {
      msOut = dt.toMSecsSinceEpoch();
      return true;
    }
  }

  static const QStringList kFormats = {QStringLiteral("yyyy/MM/dd HH:mm:ss::zzz"),
                                       QStringLiteral("yyyy/MM/dd/ HH:mm:ss::zzz"),
                                       QStringLiteral("yyyy/MM/dd HH:mm:ss"),
                                       QStringLiteral("yyyy/MM/dd/ HH:mm:ss")};

  const QString text = QString::fromUtf8(cell);
  for (const auto& format : kFormats) {
    const QDateTime dt = QDateTime::fromString(text, format);
    if (dt.isValid()) {
      msOut = dt.toMSecsSinceEpoch();
      return true;
    }
  }

  return false;
}

double CSV::PlayerLoaderWorker::secondsForRow(const PlayerIndexRequest& request,
                                              const DataModel::ReplayCellViews& cells) const
{
  Q_ASSERT(!cells.isEmpty());

  switch (request.mode) {
    case PlayerTimestampMode::Interval:
      return static_cast<double>(m_validRows) * request.intervalSeconds;

    case PlayerTimestampMode::Numeric: {
      bool ok            = false;
      const double value = SerialStudio::toDouble(cells.first(), &ok);
      return (ok && value >= 0.0 && std::isfinite(value)) ? value : -1.0;
    }

    case PlayerTimestampMode::DateTime:
    case PlayerTimestampMode::DateTimeColumn: {
      const qsizetype column =
        (request.mode == PlayerTimestampMode::DateTime) ? 0 : request.timestampColumn;
      if (column < 0 || column >= cells.size())
        return -1.0;

      qint64 ms = 0;
      if (!parseLegacyDateTimeMs(cells.at(column), ms))
        return -1.0;

      return static_cast<double>(ms - request.anchorMsSinceEpoch) * 0.001;
    }
  }

  return -1.0;
}

void CSV::PlayerLoaderWorker::processRow(const PlayerIndexRequest& request,
                                         qint64 begin,
                                         qint64 end,
                                         DataModel::ReplayCellViews& cells,
                                         QByteArray& scratch,
                                         PlayerIndexBatch& batch)
{
  Q_ASSERT(begin >= 0);
  Q_ASSERT(begin <= end);

  if (begin >= end)
    return;

  if (end - begin > kMaxCsvRowBytes) [[unlikely]]
    return;

  if (m_validRows >= kMaxIndexedRows) [[unlikely]] {
    m_rowLimitHit = true;
    return;
  }

  DataModel::splitReplayRowSpans(
    QByteArrayView(request.data + begin, static_cast<qsizetype>(end - begin)), cells, scratch);

  const bool valid = std::any_of(
    cells.cbegin(), cells.cend(), [](const QByteArrayView& cell) { return !cell.isEmpty(); });
  if (!valid)
    return;

  batch.rowOffsets.append(static_cast<quint64>(begin));
  batch.rowSeconds.append(secondsForRow(request, cells));
  ++m_validRows;
}

void CSV::PlayerLoaderWorker::indexFile(const CSV::PlayerIndexRequestPtr& request)
{
  Q_ASSERT(request != nullptr);
  Q_ASSERT(request->data != nullptr || request->size == 0);
  Q_ASSERT(request->dataOffset >= 0 && request->dataOffset <= request->size);

  m_validRows = 0;

  DataModel::ReplayCellViews cells;
  QByteArray scratch;
  auto batch = std::make_shared<PlayerIndexBatch>();

  constexpr qint64 kScanChunkBytes = 4 * 1024 * 1024;

  const qint64 size = request->size;
  const char* data  = request->data;
  qint64 rowStart   = request->dataOffset;
  bool stopped      = false;

  for (qint64 chunkStart  = request->dataOffset; chunkStart < size && !stopped;
       chunkStart        += kScanChunkBytes) {
    const qint64 chunkLen = qMin(kScanChunkBytes, size - chunkStart);
    const bool scanned =
      DSP::simdForEachByteMatch(data + chunkStart, chunkLen, '\n', [&](qsizetype pos) {
        const qint64 rowEnd = chunkStart + pos;
        processRow(*request, rowStart, rowEnd, cells, scratch, *batch);
        rowStart = rowEnd + 1;

        if (batch->rowOffsets.size() >= kBatchRows) {
          batch->bytesIndexed = rowStart;
          batch->generation   = request->generation;
          Q_EMIT batchReady(batch);
          batch = std::make_shared<PlayerIndexBatch>();
        }

        return !m_cancelRequested.load(std::memory_order_relaxed) && !m_rowLimitHit;
      });

    stopped = !scanned || m_cancelRequested.load(std::memory_order_relaxed) || m_rowLimitHit;
  }

  if (m_cancelRequested.load(std::memory_order_relaxed)) {
    Q_EMIT finished(false, request->generation);
    return;
  }

  if (!m_rowLimitHit)
    processRow(*request, rowStart, size, cells, scratch, *batch);

  if (m_rowLimitHit) [[unlikely]]
    qWarning() << "[CSV::PlayerLoaderWorker] Row limit reached (" << kMaxIndexedRows
               << "); file indexed partially.";

  batch->bytesIndexed = m_rowLimitHit ? rowStart : size;
  batch->generation   = request->generation;
  Q_EMIT batchReady(batch);
  Q_EMIT finished(true, request->generation);
}

static void assignFormattedDouble(QString& dst, double value)
{
  char buf[32];
  const auto res = std::to_chars(buf, buf + sizeof(buf), value, std::chars_format::general, 10);
  Q_ASSERT(res.ec == std::errc());
  DataModel::assign_utf8_in_place(dst, QByteArrayView(buf, static_cast<qsizetype>(res.ptr - buf)));
  Q_ASSERT(dst == QString::number(value, 'g', 10));
}

const std::unordered_map<int, int>* DataModel::FrameBuilder::replayColumnsFor(int sourceId) const
{
  Q_ASSERT(sourceId >= 0);
  Q_ASSERT(SerialStudio::isFinalValuePlayerOpen());

  const auto it = m_replayColumnMap.find(sourceId);
  return (it != m_replayColumnMap.end()) ? &it->second : nullptr;
}

void DataModel::FrameBuilder::applyReplaySpanValue(Dataset& dataset,
                                                   const QByteArrayView* cells,
                                                   qsizetype count,
                                                   const std::unordered_map<int, int>* columns)
{
  Q_ASSERT(cells != nullptr);
  Q_ASSERT(count > 0);

  if (columns) [[likely]] {
    const auto it       = columns->find(dataset.uniqueId);
    const qsizetype col = (it != columns->end()) ? it->second : -1;
    if (col >= 0 && col < count) {
      DataModel::assign_utf8_in_place(dataset.value, cells[col]);
      dataset.numericValue = SerialStudio::toDouble(cells[col], &dataset.isNumeric);
    } else {
      dataset.numericValue = 0.0;
      dataset.value.clear();
      dataset.isNumeric = true;
    }
  } else if (dataset.virtual_) {
    dataset.numericValue = 0.0;
    dataset.value.clear();
    dataset.isNumeric = true;
  } else {
    const qsizetype idx = dataset.index;
    if (idx <= 0 || idx > count) [[unlikely]]
      return;

    DataModel::assign_utf8_in_place(dataset.value, cells[idx - 1]);
    dataset.numericValue = SerialStudio::toDouble(cells[idx - 1], &dataset.isNumeric);
  }

  dataset.rawNumericValue = dataset.numericValue;
  DataModel::assign_string_in_place(dataset.rawValue, dataset.value);

  if (m_captureDatasetValues)
    m_tableStore.setDatasetRaw(
      dataset.uniqueId, dataset.numericValue, dataset.value, dataset.isNumeric);

  if (!dataset.isNumeric)
    dataset.numericValue = (dataset.wgtMax > dataset.wgtMin) ? dataset.wgtMin : 0.0;

  if (m_captureDatasetValues)
    m_tableStore.setDatasetFinal(
      dataset.uniqueId, dataset.numericValue, dataset.value, dataset.isNumeric);
}

void DataModel::FrameBuilder::applyReplayTypedValue(Dataset& dataset,
                                                    const ReplayCell* cells,
                                                    qsizetype count,
                                                    const std::unordered_map<int, int>* columns)
{
  Q_ASSERT(cells != nullptr);
  Q_ASSERT(count > 0);

  const auto applyCell = [&](const ReplayCell& cell) {
    if (cell.text) {
      DataModel::assign_string_in_place(dataset.value, *cell.text);
      dataset.numericValue = SerialStudio::toDouble(dataset.value, &dataset.isNumeric);
    } else {
      assignFormattedDouble(dataset.value, cell.number);
      dataset.numericValue = cell.number;
      dataset.isNumeric    = true;
    }
  };

  if (columns) [[likely]] {
    const auto it       = columns->find(dataset.uniqueId);
    const qsizetype col = (it != columns->end()) ? it->second : -1;
    if (col >= 0 && col < count) {
      applyCell(cells[col]);
    } else {
      dataset.numericValue = 0.0;
      dataset.value.clear();
      dataset.isNumeric = true;
    }
  } else if (dataset.virtual_) {
    dataset.numericValue = 0.0;
    dataset.value.clear();
    dataset.isNumeric = true;
  } else {
    const qsizetype idx = dataset.index;
    if (idx <= 0 || idx > count) [[unlikely]]
      return;

    applyCell(cells[idx - 1]);
  }

  dataset.rawNumericValue = dataset.numericValue;
  DataModel::assign_string_in_place(dataset.rawValue, dataset.value);

  if (m_captureDatasetValues)
    m_tableStore.setDatasetRaw(
      dataset.uniqueId, dataset.numericValue, dataset.value, dataset.isNumeric);

  if (!dataset.isNumeric)
    dataset.numericValue = (dataset.wgtMax > dataset.wgtMin) ? dataset.wgtMin : 0.0;

  if (m_captureDatasetValues)
    m_tableStore.setDatasetFinal(
      dataset.uniqueId, dataset.numericValue, dataset.value, dataset.isNumeric);
}

void DataModel::FrameBuilder::replayChannelSpans(
  int sourceId,
  const QByteArrayView* cells,
  qsizetype count,
  const DataModel::TimestampedFrame::SteadyTimePoint& timestamp)
{
  Q_ASSERT(sourceId >= 0);
  Q_ASSERT(cells != nullptr || count == 0);
  Q_ASSERT(m_playerOpen);
  Q_ASSERT(m_operationMode == SerialStudio::ProjectFile);

  if (count <= 0 || m_frame.groups.empty()) [[unlikely]]
    return;

  DataModel::Frame& srcFrame = ensureSourceFrame(sourceId);
  if (srcFrame.groups.empty() || srcFrame.title.isEmpty()) [[unlikely]]
    return;

  const auto* columns = replayColumnsFor(sourceId);

  TransformFrameInfo info;
  info.sourceId = sourceId;

  const bool armedWatchdog = beginDatasetPass(info);
  for (auto& group : srcFrame.groups) {
    SS_NO_UNROLL
    for (auto& dataset : group.datasets)
      applyReplaySpanValue(dataset, cells, count, columns);
  }

  endDatasetPass(armedWatchdog);

  publishReplayFrame(acquireFrame(srcFrame, timestamp));
  ++m_parsedFrameCount;
}

void DataModel::FrameBuilder::replayChannelsTyped(
  int sourceId,
  const ReplayCell* cells,
  qsizetype count,
  const DataModel::TimestampedFrame::SteadyTimePoint& timestamp)
{
  Q_ASSERT(sourceId >= 0);
  Q_ASSERT(cells != nullptr || count == 0);
  Q_ASSERT(m_playerOpen);
  Q_ASSERT(m_operationMode == SerialStudio::ProjectFile);

  if (count <= 0 || m_frame.groups.empty()) [[unlikely]]
    return;

  DataModel::Frame& srcFrame = ensureSourceFrame(sourceId);
  if (srcFrame.groups.empty() || srcFrame.title.isEmpty()) [[unlikely]]
    return;

  const auto* columns = replayColumnsFor(sourceId);

  TransformFrameInfo info;
  info.sourceId = sourceId;

  const bool armedWatchdog = beginDatasetPass(info);
  for (auto& group : srcFrame.groups) {
    SS_NO_UNROLL
    for (auto& dataset : group.datasets)
      applyReplayTypedValue(dataset, cells, count, columns);
  }

  endDatasetPass(armedWatchdog);

  publishReplayFrame(acquireFrame(srcFrame, timestamp));
  ++m_parsedFrameCount;
}

[[nodiscard]] static bool allAsciiSpace(QByteArrayView row, qsizetype begin, qsizetype end)
{
  for (qsizetype i = begin; i < end; ++i) {
    const char c = row.at(i);
    if (c != ' ' && c != '\t' && c != '\n' && c != '\v' && c != '\f' && c != '\r')
      return false;
  }

  return true;
}

[[nodiscard]] static QByteArrayView trimmedCellView(QByteArrayView v)
{
  qsizetype b = 0;
  qsizetype e = v.size();
  while (b < e && allAsciiSpace(v, b, b + 1))
    ++b;
  while (e > b && allAsciiSpace(v, e - 1, e))
    --e;

  return v.sliced(b, e - b);
}

[[nodiscard]] static QByteArrayView stripGuardView(QByteArrayView v)
{
  if (v.size() < 2 || v.at(0) != '\'')
    return v;

  const char c      = v.at(1);
  const bool danger = c == '=' || c == '+' || c == '-' || c == '@' || c == '\t' || c == '\r';
  return danger ? v.sliced(1) : v;
}

static void appendRewrittenCell(QByteArrayView row,
                                qsizetype begin,
                                qsizetype end,
                                QByteArray& scratch)
{
  Q_ASSERT(begin <= end);
  Q_ASSERT(end <= row.size());

  bool in_quotes            = false;
  bool was_quoted           = false;
  const qsizetype cell_base = scratch.size();
  for (qsizetype i = begin; i < end; ++i) {
    const char c = row.at(i);
    if (in_quotes) {
      const bool escaped = c == '"' && i + 1 < end && row.at(i + 1) == '"';
      if (escaped) {
        scratch.append('"');
        ++i;
        continue;
      }

      if (c == '"') {
        in_quotes = false;
        continue;
      }

      scratch.append(c);
      continue;
    }

    if (c == '"' && !was_quoted
        && allAsciiSpace(QByteArrayView(scratch), cell_base, scratch.size())) {
      in_quotes  = true;
      was_quoted = true;
      scratch.resize(cell_base);
      continue;
    }

    scratch.append(c);
  }
}

void DataModel::splitReplayRowSpans(QByteArrayView row, ReplayCellViews& out, QByteArray& scratch)
{
  out.clear();
  scratch.resize(0);
  if (row.endsWith('\r'))
    row.chop(1);

  if (scratch.capacity() < row.size())
    scratch.reserve(row.size());

  Q_ASSERT(scratch.capacity() >= row.size());

  const qsizetype length  = row.size();
  qsizetype cell_start    = 0;
  qsizetype interior_from = -1;
  qsizetype interior_to   = -1;
  bool in_quotes          = false;
  bool was_quoted         = false;
  bool needs_rewrite      = false;

  const auto finalize = [&](qsizetype end) {
    QByteArrayView value;
    if (!was_quoted)
      value = trimmedCellView(row.sliced(cell_start, end - cell_start));
    else if (!needs_rewrite) {
      const qsizetype to = (interior_to >= 0) ? interior_to : end;
      value              = row.sliced(interior_from, to - interior_from);
    } else {
      const qsizetype base = scratch.size();
      appendRewrittenCell(row, cell_start, end, scratch);
      Q_ASSERT(scratch.size() <= row.size());
      value = QByteArrayView(scratch).sliced(base);
    }

    out.append(stripGuardView(value));
    interior_from = -1;
    interior_to   = -1;
    was_quoted    = false;
    needs_rewrite = false;
  };

  for (qsizetype i = 0; i < length; ++i) {
    const char c = row.at(i);

    if (in_quotes) {
      const bool escaped = c == '"' && i + 1 < length && row.at(i + 1) == '"';
      if (escaped) {
        needs_rewrite = true;
        ++i;
        continue;
      }

      if (c == '"') {
        in_quotes   = false;
        interior_to = i;
      }

      continue;
    }

    if (c == ',') {
      finalize(i);
      cell_start = i + 1;
      continue;
    }

    if (c == '"' && !was_quoted && allAsciiSpace(row, cell_start, i)) {
      in_quotes     = true;
      was_quoted    = true;
      interior_from = i + 1;
      continue;
    }

    if (was_quoted)
      needs_rewrite = true;
  }

  finalize(length);
}

void MDF4::Player::startDecoding(const QString& filePath)
{
  Q_ASSERT(!filePath.isEmpty());
  Q_ASSERT(m_loaderThread == nullptr);

  ++m_decodeGeneration;
  m_loaderThread = new QThread(this);
  m_loaderThread->setObjectName(QStringLiteral("MDF4::PlayerLoader"));
  m_loader = new PlayerLoaderWorker();
  m_loader->moveToThread(m_loaderThread);

  connect(m_loader,
          &PlayerLoaderWorker::progressUpdate,
          this,
          &MDF4::Player::onDecodeProgress,
          Qt::QueuedConnection);
  connect(m_loader,
          &PlayerLoaderWorker::finished,
          this,
          &MDF4::Player::onDecodeFinished,
          Qt::QueuedConnection);

  m_loaderThread->start();

  m_decoding       = true;
  m_decodeProgress = 0.0;

  auto* loader             = m_loader;
  const quint64 generation = m_decodeGeneration;
  QMetaObject::invokeMethod(
    loader,
    [loader, filePath, generation]() { loader->decodeFile(filePath, generation); },
    Qt::QueuedConnection);

  Q_EMIT indexingChanged();
}

static void fillSeekGaps(QVector<double>& values)
{
  int firstSet = -1;
  const int n  = values.size();
  for (int k = 0; k < n; ++k)
    if (std::isnan(values[k]))
      values[k] = (k > 0) ? values[k - 1] : values[k];
    else if (firstSet < 0)
      firstSet = k;

  const double seed = (firstSet >= 0) ? values[firstSet] : 0.0;
  for (int k = 0; k < n && std::isnan(values[k]); ++k)
    values[k] = seed;
}

static bool isStringChannel(const mdf::IChannel* channel)
{
  if (!channel)
    return false;

  const auto type = channel->DataType();
  return type == mdf::ChannelDataType::StringAscii || type == mdf::ChannelDataType::StringUTF8
      || type == mdf::ChannelDataType::StringUTF16Le || type == mdf::ChannelDataType::StringUTF16Be;
}

static bool hasRawSuffix(const std::string& chName)
{
  static constexpr const char* kRawSuffix = " (raw)";
  return chName.size() >= 6 && chName.compare(chName.size() - 6, 6, kRawSuffix) == 0;
}

static void scanChannelGroup(mdf::IChannelGroup* cg,
                             bool isSerialStudioFile,
                             std::vector<mdf::IChannel*>& allChannels,
                             std::map<mdf::IChannelGroup*, mdf::IChannel*>& groupTimeChannels,
                             int& masterChannelCount)
{
  mdf::IChannel* groupMaster = nullptr;
  for (auto* ch : cg->Channels()) {
    if (!ch)
      continue;

    if (isSerialStudioFile && ch->Type() == mdf::ChannelType::Master) {
      groupMaster = ch;
      ++masterChannelCount;
      continue;
    }

    if (hasRawSuffix(ch->Name())) [[unlikely]]
      continue;

    if (std::find(allChannels.begin(), allChannels.end(), ch) == allChannels.end())
      allChannels.push_back(ch);
  }

  if (groupMaster)
    groupTimeChannels[cg] = groupMaster;
}

static void collectAllChannels(const std::vector<mdf::IDataGroup*>& dataGroups,
                               bool isSerialStudioFile,
                               std::vector<mdf::IChannel*>& allChannels,
                               std::map<mdf::IChannelGroup*, mdf::IChannel*>& groupTimeChannels,
                               int& masterChannelCount)
{
  for (auto* dg : dataGroups) {
    if (!dg)
      continue;

    for (auto* cg : dg->ChannelGroups()) {
      if (!cg)
        continue;

      scanChannelGroup(cg, isSerialStudioFile, allChannels, groupTimeChannels, masterChannelCount);
    }
  }
}

static std::vector<CgInfo> buildCgInfos(
  mdf::IDataGroup* dg,
  bool perGroupTime,
  const std::map<mdf::IChannelGroup*, mdf::IChannel*>& groupTimeChannels)
{
  std::vector<CgInfo> cgInfos;
  for (auto* cg : dg->ChannelGroups()) {
    if (!cg)
      continue;

    auto cgChannels      = cg->Channels();
    uint64_t recordCount = cg->NofSamples();
    if (cgChannels.empty() || recordCount == 0)
      continue;

    CgInfo ci;
    ci.cg     = cg;
    ci.timeCh = nullptr;

    if (perGroupTime) {
      auto tit = groupTimeChannels.find(cg);
      if (tit != groupTimeChannels.end())
        ci.timeCh = tit->second;
    }

    for (auto* ch : cgChannels) {
      if (!ch || ch->Type() == mdf::ChannelType::Master)
        continue;

      if (hasRawSuffix(ch->Name())) [[unlikely]]
        continue;

      ci.dataChs.push_back(ch);
    }

    cgInfos.push_back(std::move(ci));
  }

  return cgInfos;
}

SampleCacheObserver(const mdf::IDataGroup& dataGroup,
                      MDF4::PlayerLoaderWorker* worker,
                      std::map<uint64_t, std::vector<double>>& cache,
                      std::map<uint64_t, std::vector<QString>>& stringCache,
                      std::map<uint64_t, double>& timestampCache,
                      std::map<uint64_t, std::vector<bool>>& activeChannels,
                      const std::vector<mdf::IChannel*>& allChannels,
                      const std::vector<mdf::IChannel*>& groupChannels,
                      mdf::IChannel* groupTimeChannel,
                      uint64_t recordId)
    : mdf::ISampleObserver(dataGroup)
    , m_worker(worker)
    , m_cache(cache)
    , m_stringCache(stringCache)
    , m_timestampCache(timestampCache)
    , m_activeChannels(activeChannels)
    , m_allChannels(allChannels)
    , m_groupChannels(groupChannels)
    , m_groupTimeChannel(groupTimeChannel)
    , m_recordId(recordId)
    , m_hasStringChannels(false)
  {
    for (size_t i = 0; i < m_allChannels.size(); ++i) {
      for (auto* ch : m_groupChannels) {
        if (m_allChannels[i] == ch) {
          m_channelIndexMap[ch] = i;
          break;
        }
      }
    }

    for (auto* ch : m_groupChannels)
      m_hasStringChannels = m_hasStringChannels || isStringChannel(ch);
  }

bool OnSample(uint64_t sample, uint64_t record_id, const std::vector<uint8_t>& record) override
  {
    if (record_id != m_recordId)
      return true;

    uint64_t cacheKey = sample;
    if (m_groupTimeChannel) {
      double ts          = 0.0;
      const bool success = GetEngValue(*m_groupTimeChannel, record_id, record, ts);
      if (!success)
        GetChannelValue(*m_groupTimeChannel, record_id, record, ts);

      cacheKey                   = static_cast<uint64_t>(ts * 1'000'000'000.0);
      m_timestampCache[cacheKey] = ts;
    }

    auto cacheIt = m_cache.find(cacheKey);
    if (cacheIt == m_cache.end())
      cacheIt = m_cache.emplace(cacheKey, std::vector<double>(m_allChannels.size(), 0.0)).first;

    auto activeIt = m_activeChannels.find(cacheKey);
    if (activeIt == m_activeChannels.end())
      activeIt =
        m_activeChannels.emplace(cacheKey, std::vector<bool>(m_allChannels.size(), false)).first;

    auto& values = cacheIt->second;
    auto& active = activeIt->second;

    std::vector<QString>* strings = nullptr;
    if (m_hasStringChannels) {
      auto strIt = m_stringCache.find(cacheKey);
      if (strIt == m_stringCache.end())
        strIt = m_stringCache.emplace(cacheKey, std::vector<QString>(m_allChannels.size())).first;

      strings = &strIt->second;
    }

    for (auto* channel : m_groupChannels) {
      if (!channel)
        continue;

      auto it = m_channelIndexMap.find(channel);
      if (it == m_channelIndexMap.end())
        continue;

      if (strings && isStringChannel(channel)) {
        std::string text;
        const bool success = GetEngValue(*channel, record_id, record, text);
        if (!success)
          (void)GetChannelValue(*channel, record_id, record, text);

        (*strings)[it->second] = QString::fromStdString(text);
        active[it->second]     = true;
        continue;
      }

      double value       = 0.0;
      const bool success = GetEngValue(*channel, record_id, record, value);

      if (!success) {
        const bool channelSuccess = GetChannelValue(*channel, record_id, record, value);
        if (!channelSuccess)
          value = 0.0;
      }

      values[it->second] = value;
      active[it->second] = true;
    }

    return m_worker->recordTick();
  }

bool OnSample(uint64_t sample, uint64_t record_id, const std::vector<uint8_t>& record) override
  {
    if (record_id != m_recordId)
      return true;

    if (!m_masterTimeChannel || m_timestampCache.find(sample) != m_timestampCache.end())
      return true;

    double timestamp   = 0.0;
    const bool success = GetEngValue(*m_masterTimeChannel, record_id, record, timestamp);

    if (!success) {
      const bool channelSuccess =
        GetChannelValue(*m_masterTimeChannel, record_id, record, timestamp);
      if (!channelSuccess)
        timestamp = 0.0;
    }

    m_timestampCache[sample] = timestamp;
    return m_worker->recordTick();
  }

bool MDF4::PlayerLoaderWorker::recordTick()
{
  ++m_recordsSeen;
  if (m_recordsSeen % kProgressTickRecords == 0 && m_recordsTotal > 0) {
    const double fraction =
      std::min(1.0, static_cast<double>(m_recordsSeen) / static_cast<double>(m_recordsTotal));
    Q_EMIT progressUpdate(fraction, m_activeGeneration);
  }

  return !m_cancelRequested.load(std::memory_order_relaxed);
}

static void appendFrameColumns(MDF4::PlayerDecodePayload& payload,
                               const DecodeCaches& caches,
                               uint64_t key,
                               const std::vector<double>& values,
                               uint64_t sampleIndex)
{
  const auto strIt = caches.strings.find(key);
  const auto actIt = caches.active.find(key);

  const size_t channelCount = payload.channelIsString.size();
  for (size_t c = 0; c < channelCount && c < values.size(); ++c) {
    if (!payload.channelIsString[c])
      payload.numeric[c][sampleIndex] = values[c];
    else if (strIt != caches.strings.end() && c < strIt->second.size())
      payload.text[c][sampleIndex] = strIt->second[c];

    if (actIt != caches.active.end() && c < actIt->second.size())
      payload.active[c][sampleIndex] = actIt->second[c];
  }
}

static void convertToColumnar(MDF4::PlayerDecodePayload& payload, DecodeCaches& caches)
{
  const size_t channelCount = payload.channelIsString.size();
  const size_t frameCount   = caches.samples.size();
  const bool useTimestamps  = payload.isSerialStudioFile && !caches.timestamps.empty();

  payload.timestamps.reserve(frameCount);
  payload.numeric.resize(channelCount);
  payload.text.resize(channelCount);
  payload.active.resize(channelCount);
  for (size_t c = 0; c < channelCount; ++c) {
    if (payload.channelIsString[c])
      payload.text[c].resize(frameCount);
    else
      payload.numeric[c].resize(frameCount, 0.0);

    payload.active[c].resize(frameCount, false);
  }

  for (uint64_t sampleIndex = 0; sampleIndex < frameCount && !caches.samples.empty();
       ++sampleIndex) {
    const auto it      = caches.samples.begin();
    const uint64_t key = it->first;

    double ts = static_cast<double>(sampleIndex) * 0.001;
    if (useTimestamps) {
      const auto timeIt = caches.timestamps.find(key);
      if (timeIt != caches.timestamps.end())
        ts = timeIt->second;
    }

    payload.timestamps.push_back(ts);
    appendFrameColumns(payload, caches, key, it->second, sampleIndex);

    caches.samples.erase(it);
    caches.strings.erase(key);
    caches.active.erase(key);
    caches.timestamps.erase(key);
  }
}

static std::unique_ptr<mdf::MdfReader> openStructure(const QString& filePath,
                                                     MDF4::PlayerDecodePayload& payload)
{
  auto reader = std::make_unique<mdf::MdfReader>(filePath.toStdString());
  if (!reader->IsOk()) {
    payload.errorTitle = QObject::tr("Cannot open MDF4 file");
    payload.errorBody  = QObject::tr("The file may be corrupted or in an unsupported format.");
    return nullptr;
  }

  if (!reader->ReadEverythingButData()) {
    payload.errorTitle = QObject::tr("Invalid MDF4 file");
    payload.errorBody  = QObject::tr("Failed to read file structure. The file may be corrupted.");
    return nullptr;
  }

  if (auto* header = reader->GetHeader())
    payload.isSerialStudioFile = QString::fromStdString(header->Author()) == "Serial Studio";

  return reader;
}

static bool readAllGroups(MDF4::PlayerLoaderWorker* worker,
                          mdf::MdfReader& reader,
                          const std::vector<mdf::IDataGroup*>& dataGroups,
                          const std::vector<mdf::IChannel*>& allChannels,
                          const TimeConfig& timeConfig,
                          DecodeCaches& caches)
{
  bool read_ok = true;
  for (auto* dg : dataGroups) {
    if (!dg || worker->cancelRequested())
      continue;

    auto cgInfos = buildCgInfos(dg, timeConfig.perGroupTime, timeConfig.groupTimeChannels);
    std::vector<std::unique_ptr<SampleCacheObserver>> observers;
    observers.reserve(cgInfos.size());
    for (auto& ci : cgInfos) {
      auto obs = std::make_unique<SampleCacheObserver>(*dg,
                                                       worker,
                                                       caches.samples,
                                                       caches.strings,
                                                       caches.timestamps,
                                                       caches.active,
                                                       allChannels,
                                                       ci.dataChs,
                                                       ci.timeCh,
                                                       ci.cg->RecordId());
      obs->AttachObserver();
      observers.push_back(std::move(obs));
    }

    read_ok = reader.ReadData(*dg) && read_ok;

    for (auto& obs : observers)
      obs->DetachObserver();
  }

  const bool wantLegacyTs =
    !timeConfig.perGroupTime && timeConfig.legacyMasterTimeChannel && !worker->cancelRequested();
  if (wantLegacyTs) {
    for (auto* dg : dataGroups) {
      if (!dg)
        continue;

      LegacyTimestampObserver tsObs(*dg,
                                    worker,
                                    caches.timestamps,
                                    timeConfig.legacyMasterTimeChannel,
                                    timeConfig.legacyTimeRecId);
      tsObs.AttachObserver();
      read_ok = reader.ReadData(*dg) && read_ok;
      tsObs.DetachObserver();
      break;
    }
  }

  return read_ok;
}

void MDF4::PlayerLoaderWorker::decodeFile(const QString& filePath, quint64 generation)
{
  Q_ASSERT(!filePath.isEmpty());

  m_recordsSeen      = 0;
  m_recordsTotal     = 0;
  m_activeGeneration = generation;

  auto payload        = std::make_shared<PlayerDecodePayload>();
  payload->filePath   = filePath;
  payload->generation = generation;

  auto reader = openStructure(filePath, *payload);
  if (!reader) {
    Q_EMIT finished(payload);
    return;
  }

  auto* file = reader->GetFile();
  mdf::DataGroupList dataGroups;
  if (file)
    file->DataGroups(dataGroups);

  std::vector<mdf::IChannel*> allChannels;
  TimeConfig timeConfig;
  int masterChannelCount = 0;
  collectAllChannels(dataGroups,
                     payload->isSerialStudioFile,
                     allChannels,
                     timeConfig.groupTimeChannels,
                     masterChannelCount);

  timeConfig.perGroupTime = (masterChannelCount > 1);
  if (masterChannelCount == 1) {
    auto it                            = timeConfig.groupTimeChannels.begin();
    timeConfig.legacyMasterTimeChannel = payload->isSerialStudioFile ? it->second : nullptr;
    timeConfig.legacyTimeRecId         = it->first->RecordId();
    timeConfig.groupTimeChannels.clear();
  }

  for (auto* dg : dataGroups) {
    if (!dg)
      continue;

    for (auto* cg : dg->ChannelGroups())
      if (cg)
        m_recordsTotal += cg->NofSamples();
  }

  payload->channelNames.reserve(static_cast<qsizetype>(allChannels.size()));
  payload->channelIsString.reserve(allChannels.size());
  for (const auto* ch : allChannels) {
    payload->channelNames.append(ch ? QString::fromStdString(ch->Name()) : QString());
    payload->channelIsString.push_back(isStringChannel(ch));
  }

  DecodeCaches caches;
  const bool read_ok = readAllGroups(this, *reader, dataGroups, allChannels, timeConfig, caches);

  if (m_cancelRequested.load(std::memory_order_relaxed)) {
    payload->cancelled = true;
    Q_EMIT finished(payload);
    return;
  }

  convertToColumnar(*payload, caches);
  payload->ok          = true;
  payload->partialData = !read_ok;
  Q_EMIT finished(payload);
}

void AI::Conversation::scheduleUiFlush()
{
  m_uiDirty = true;
  if (!m_streamFlushTimer->isActive())
    m_streamFlushTimer->start();
}

static bool helpUrlAllowed(const QUrl& url)
{
  if (!url.isValid() || url.scheme() != QStringLiteral("https") || !url.userInfo().isEmpty())
    return false;

  static const QStringList kHosts = {
    QStringLiteral("githubusercontent.com"),
    QStringLiteral("github.com"),
    QStringLiteral("serial-studio.com"),
  };

  const auto host = url.host().toLower();
  for (const auto& allowed : kHosts)
    if (host == allowed || host.endsWith(QLatin1Char('.') + allowed))
      return true;

  return false;
}

static void hardenHelpReply(QNetworkReply* reply, qint64 maxBytes)
{
  QObject::connect(reply, &QNetworkReply::redirected, reply, [reply](const QUrl& target) {
    if (helpUrlAllowed(target))
      Q_EMIT reply->redirectAllowed();
    else
      reply->abort();
  });

  QObject::connect(reply, &QNetworkReply::readyRead, reply, [reply, maxBytes]() {
    if (reply->bytesAvailable() > maxBytes)
      reply->abort();
  });
}

bool AI::AnthropicReply::streamBudgetBreached(qsizetype bytes)
{
  if (!chargeStreamBudget(bytes))
    return false;

  finishWithError(
    tr("Reply exceeded the %1 MB stream limit").arg(kMaxStreamedReplyBytes / (1024 * 1024)));
  abort();
  return true;
}

bool AI::GeminiReply::streamBudgetBreached(qsizetype bytes)
{
  if (!chargeStreamBudget(bytes))
    return false;

  finishWithError(
    tr("Reply exceeded the %1 MB stream limit").arg(kMaxStreamedReplyBytes / (1024 * 1024)));
  abort();
  return true;
}

bool AI::OpenAIReply::streamBudgetBreached(qsizetype bytes)
{
  if (!chargeStreamBudget(bytes))
    return false;

  finishWithError(
    tr("Reply exceeded the %1 MB stream limit").arg(kMaxStreamedReplyBytes / (1024 * 1024)));
  abort();
  return true;
}

bool AI::SseEventReader::fatalReason(const QString& reason)
{
  return reason == QLatin1String(kErrBufferOverflow)
      || reason == QLatin1String(kErrPayloadTooLarge);
}

QByteArray AI::SseEventReader::normalizeNewlines(const QByteArray& chunk)
{
  QByteArray input;
  input.reserve(chunk.size() + 1);
  if (m_pendingCr) {
    input.append('\r');
    m_pendingCr = false;
  }

  input.append(chunk);
  if (input.endsWith('\r')) {
    m_pendingCr = true;
    input.chop(1);
  }

  input.replace("\r\n", "\n");
  input.replace('\r', '\n');
  return input;
}

int CSV::Player::seekWindowStartRow(int target)
{
  Q_ASSERT(target >= 0);
  Q_ASSERT(target < frameCount());
  static auto& dashboard = UI::Dashboard::instance();
  const double range     = dashboard.plotTimeRange();
  const double targetSec = rowSecondsSinceStart(target);
  const int minStart = qMax(0, target - qMax(1, dashboard.points()) + 1);
  const int capStart = qMax(0, target - kMaxSeekWindowRows + 1);

  int start = minStart;
  for (int i = 0; i < kMaxSeekWindowRows && targetSec >= 0.0 && start > capStart; ++i) {
    const double sec = rowSecondsSinceStart(start - 1);
    if (sec < 0.0 || targetSec - sec > range)
      break;

    --start;
  }

  return start;
}

void CSV::Player::performSeekTick()
{
  if (!isOpen() || isPlaying())
    return;

  Q_ASSERT(m_framePos >= 0);
  Q_ASSERT(m_framePos < frameCount());

  if (m_seekColumnByKey.isEmpty()) {
    performSeekSettle();
    return;
  }

  static auto& dashboard = UI::Dashboard::instance();
  const int target       = m_framePos;
  const int start        = seekWindowStartRow(target);

  QVector<double> times;
  QHash<qint64, QVector<double>> series;
  buildSeekWindow(start, target, times, series);
  dashboard.bulkLoadPlotWindow(times, series);

  anchorSteadyBase(target);
  injectRow(target);
}

void CSV::Player::performSeekSettle()
{
  if (!isOpen() || isPlaying())
    return;

  Q_ASSERT(m_framePos >= 0);
  Q_ASSERT(m_framePos < frameCount());

  static auto& dashboard = UI::Dashboard::instance();
  dashboard.clearPlotData();

  const int window = qMin(dashboard.points(), m_framePos + 1);
  const int start  = qMax(0, m_framePos - window + 1);
  processFrameBatch(start, m_framePos);

  if (!m_seekColumnByKey.isEmpty()) {
    QVector<double> times;
    QHash<qint64, QVector<double>> series;
    const int fillStart = seekWindowStartRow(m_framePos);
    buildSeekWindow(fillStart, m_framePos, times, series);
    dashboard.bulkLoadPlotWindow(times, series);
  }

  updateData();
}

void CSV::Player::buildDateTimeSecondsCache()
{
  m_dateTimeSecondsCache.clear();
  if (m_useHighPrecisionTimestamps || m_csvData.isEmpty())
    return;

  const QDateTime anchor = getDateTime(0);
  if (!anchor.isValid())
    return;

  m_dateTimeSecondsCache.reserve(m_csvData.count());
  for (int i = 0; i < m_csvData.count(); ++i) {
    const auto dateTime = getDateTime(i);
    m_dateTimeSecondsCache.append(dateTime.isValid() ? anchor.msecsTo(dateTime) * kInvMs : -1.0);
  }
}

double CSV::Player::rowSecondsSinceStart(int row)
{
  Q_ASSERT(row >= 0);

  const double seconds = getTimestampSeconds(row);
  if (seconds >= 0.0)
    return seconds;

  if (row < m_dateTimeSecondsCache.size())
    return m_dateTimeSecondsCache[row];

  const auto dateTime = getDateTime(row);
  if (dateTime.isValid() && m_startTimestamp.isValid())
    return m_startTimestamp.msecsTo(dateTime) * kInvMs;

  return -1.0;
}

void CSV::Player::anchorSteadyBase(int row)
{
  Q_ASSERT(row >= 0);

  m_steadyBase           = std::chrono::steady_clock::now();
  const double seconds   = rowSecondsSinceStart(row);
  m_steadyBaseRowSeconds = (seconds >= 0.0) ? seconds : 0.0;
}

std::chrono::steady_clock::time_point CSV::Player::rowSteadyTimestamp(int row)
{
  Q_ASSERT(row >= 0);

  const double seconds = rowSecondsSinceStart(row);
  if (seconds < 0.0) [[unlikely]]
    return std::chrono::steady_clock::now();

  const auto delta = std::chrono::duration<double>(seconds - m_steadyBaseRowSeconds);
  return m_steadyBase + std::chrono::duration_cast<std::chrono::steady_clock::duration>(delta);
}

void CSV::Player::injectRow(int row)
{
  Q_ASSERT(row >= 0);
  Q_ASSERT(row < m_csvData.count());

  static auto& appState = AppState::instance();
  if (appState.operationMode() != SerialStudio::ProjectFile) {
    injectFrame(getFrame(row));
    return;
  }

  const auto& list = m_csvData[row];
  if (list.count() <= 1) [[unlikely]]
    return;

  static auto& frameBuilder = DataModel::FrameBuilder::instance();
  const auto timestamp      = rowSteadyTimestamp(row);

  if (!m_multiSource) {
    frameBuilder.replayChannels(0, list.mid(1), timestamp);
    return;
  }

  for (auto it = m_sourceColumnsByIndex.constBegin(); it != m_sourceColumnsByIndex.constEnd();
       ++it) {
    const auto& orderedCols = it.value();
    QStringList cells;
    cells.reserve(orderedCols.size());
    bool present = false;
    for (int col : orderedCols) {
      const int fieldIdx = col + 1;
      const QString cell = (fieldIdx >= 1 && fieldIdx < list.size()) ? list[fieldIdx] : QString();
      present            = present || !cell.isEmpty();
      cells.append(cell);
    }

    if (present)
      frameBuilder.replayChannels(it.key(), cells, timestamp);
  }
}

void DataModel::FrameBuilder::replayChannels(
  int sourceId,
  const QStringList& channels,
  const DataModel::TimestampedFrame::SteadyTimePoint& timestamp)
{
  Q_ASSERT(sourceId >= 0);
  Q_ASSERT(m_playerOpen);
  Q_ASSERT(m_operationMode == SerialStudio::ProjectFile);

  if (channels.isEmpty() || m_frame.groups.empty()) [[unlikely]]
    return;

  DataModel::Frame& srcFrame = ensureSourceFrame(sourceId);
  if (srcFrame.groups.empty() || srcFrame.title.isEmpty()) [[unlikely]]
    return;

  TransformFrameInfo info;
  info.sourceId = sourceId;

  applyDatasetValues(srcFrame, channels, info);
  publishReplayFrame(acquireFrame(srcFrame, timestamp));
  ++m_parsedFrameCount;
}

void DataModel::FrameBuilder::publishReplayFrame(const DataModel::TimestampedFramePtr& frame)
{
  Q_ASSERT(frame);
  Q_ASSERT(m_playerOpen);
  Q_ASSERT(!frame->data.groups.empty());

  static auto& dashboard = UI::Dashboard::instance();
  dashboard.hotpathRxFrame(frame);

  static auto& pluginsServer = API::Server::instance();
  bool observers             = pluginsServer.enabled() && pluginsServer.clientCount() > 0;
#ifdef ENABLE_GRPC
  static auto& grpcServer = API::GRPC::GRPCServer::instance();
  observers               = observers || (grpcServer.enabled() && grpcServer.clientCount() > 0);
#endif
  if (!observers)
    return;

  const auto detached =
    std::make_shared<DataModel::TimestampedFrame>(frame->data, frame->timestamp);
  if (pluginsServer.enabled() && pluginsServer.clientCount() > 0)
    pluginsServer.hotpathTxFrame(detached);
#ifdef ENABLE_GRPC
  if (grpcServer.enabled() && grpcServer.clientCount() > 0)
    grpcServer.hotpathTxFrame(detached);
#endif
}

static void stripCsvInjectionGuard(QString& cell)
{
  if (cell.size() < 2 || cell.at(0) != QChar('\''))
    return;

  const QChar c     = cell.at(1);
  const bool danger = c == QChar('=') || c == QChar('+') || c == QChar('-') || c == QChar('@')
                   || c == QChar('\t') || c == QChar('\r');
  if (danger)
    cell.remove(0, 1);
}

int MDF4::Player::seekWindowStartRow(int target) const
{
  Q_ASSERT(target >= 0);
  Q_ASSERT(target < static_cast<int>(m_frameIndex.size()));
  static auto& dashboard = UI::Dashboard::instance();
  const double range     = dashboard.plotTimeRange();
  const double targetSec = m_frameIndex[static_cast<size_t>(target)].timestamp;

  const int minStart = qMax(0, target - qMax(1, dashboard.points()) + 1);
  const int capStart = qMax(0, target - kMaxSeekWindowRows + 1);

  int start = minStart;
  for (int i = 0; i < kMaxSeekWindowRows && start > capStart; ++i) {
    const double sec = m_frameIndex[static_cast<size_t>(start - 1)].timestamp;
    if (targetSec - sec > range)
      break;

    --start;
  }

  return start;
}

void MDF4::Player::performSeekTick()
{
  if (!isOpen() || isPlaying())
    return;

  Q_ASSERT(m_framePos >= 0);
  Q_ASSERT(m_framePos < frameCount());

  if (m_seekColumnByKey.isEmpty()) {
    performSeekSettle();
    return;
  }

  static auto& dashboard = UI::Dashboard::instance();
  const int target       = m_framePos;
  const int start        = seekWindowStartRow(target);

  QVector<double> times;
  QHash<qint64, QVector<double>> series;
  buildSeekWindow(start, target, times, series);
  dashboard.bulkLoadPlotWindow(times, series);

  anchorSteadyBase(target);
  injectRow(target);
}

void MDF4::Player::performSeekSettle()
{
  if (!isOpen() || isPlaying())
    return;

  Q_ASSERT(m_framePos >= 0);
  Q_ASSERT(m_framePos < frameCount());

  static auto& dashboard = UI::Dashboard::instance();
  dashboard.clearPlotData();

  const int window = qMin(dashboard.points(), m_framePos + 1);
  const int start  = qMax(0, m_framePos - window + 1);
  processFrameBatch(start, m_framePos);

  if (!m_seekColumnByKey.isEmpty()) {
    QVector<double> times;
    QHash<qint64, QVector<double>> series;
    const int fillStart = seekWindowStartRow(m_framePos);
    buildSeekWindow(fillStart, m_framePos, times, series);
    dashboard.bulkLoadPlotWindow(times, series);
  }

  updateData();
}

void MDF4::Player::anchorSteadyBase(int frameIndex)
{
  Q_ASSERT(frameIndex >= 0);

  m_steadyBase           = std::chrono::steady_clock::now();
  m_steadyBaseRowSeconds = (frameIndex < frameCount()) ? m_frameIndex[frameIndex].timestamp : 0.0;
}

std::chrono::steady_clock::time_point MDF4::Player::rowSteadyTimestamp(int frameIndex) const
{
  Q_ASSERT(frameIndex >= 0);
  Q_ASSERT(frameIndex < static_cast<int>(m_frameIndex.size()));

  const auto delta =
    std::chrono::duration<double>(m_frameIndex[frameIndex].timestamp - m_steadyBaseRowSeconds);
  return m_steadyBase + std::chrono::duration_cast<std::chrono::steady_clock::duration>(delta);
}

void MDF4::Player::injectRow(int frameIndex)
{
  Q_ASSERT(frameIndex >= 0);
  Q_ASSERT(frameIndex < frameCount());

  static auto& appState = AppState::instance();
  if (appState.operationMode() != SerialStudio::ProjectFile) {
    injectFrame(getFrame(frameIndex), frameIndex);
    return;
  }

  QStringList cells;
  if (!buildRowCells(frameIndex, cells) || cells.isEmpty())
    return;

  static auto& frameBuilder = DataModel::FrameBuilder::instance();
  const auto timestamp      = rowSteadyTimestamp(frameIndex);

  if (!m_multiSource) {
    frameBuilder.replayChannels(0, cells, timestamp);
    return;
  }

  const std::vector<bool>* active = nullptr;
  const auto ait                  = m_activeChannels.find(m_frameIndex[frameIndex].recordIndex);
  if (ait != m_activeChannels.end())
    active = &ait->second;

  for (auto it = m_sourceChannelsByIndex.constBegin(); it != m_sourceChannelsByIndex.constEnd();
       ++it) {
    const auto& orderedChs = it.value();
    QStringList sourceCells;
    sourceCells.reserve(orderedChs.size());
    bool anyActive = !active;
    for (int ch : orderedChs) {
      sourceCells.append((ch >= 0 && ch < cells.size()) ? cells[ch] : QString());
      if (active && ch >= 0 && ch < static_cast<int>(active->size()) && (*active)[ch])
        anyActive = true;
    }

    if (anyActive)
      frameBuilder.replayChannels(it.key(), sourceCells, timestamp);
  }
}

static void showNativeSystemMenu(QWindow* window)
{
  Q_ASSERT(window != nullptr);
  if (!window)
    return;

  auto* hwnd = reinterpret_cast<HWND>(window->winId());
  Q_ASSERT(hwnd != nullptr);
  if (!hwnd)
    return;

  HMENU menu = GetSystemMenu(hwnd, FALSE);
  if (!menu)
    return;

  const auto flags       = window->flags();
  const bool custom      = flags & Qt::CustomizeWindowHint;
  const bool maximized   = IsZoomed(hwnd);
  const bool resizable   = !isFixedSizeWindow(window);
  const bool canMinimize = !custom || (flags & Qt::WindowMinimizeButtonHint);

  const UINT on  = MF_BYCOMMAND | MF_ENABLED;
  const UINT off = MF_BYCOMMAND | MF_GRAYED;
  (void)EnableMenuItem(menu, SC_RESTORE, maximized ? on : off);
  (void)EnableMenuItem(menu, SC_MOVE, maximized ? off : on);
  (void)EnableMenuItem(menu, SC_SIZE, (resizable && !maximized) ? on : off);
  (void)EnableMenuItem(menu, SC_MINIMIZE, canMinimize ? on : off);
  (void)EnableMenuItem(menu, SC_MAXIMIZE, (resizable && !maximized) ? on : off);
  (void)EnableMenuItem(menu, SC_CLOSE, on);
  (void)SetMenuDefaultItem(menu, SC_CLOSE, FALSE);

  POINT cursor{};
  if (!GetCursorPos(&cursor))
    return;

  const UINT trackFlags = TPM_RETURNCMD | TPM_RIGHTBUTTON;
  const auto command    = TrackPopupMenu(menu, trackFlags, cursor.x, cursor.y, 0, hwnd, nullptr);
  if (command != 0)
    (void)PostMessage(hwnd, WM_SYSCOMMAND, static_cast<WPARAM>(command), 0);
}

int Sessions::Player::seekWindowStartRow(int target) const
{
  Q_ASSERT(target >= 0);
  Q_ASSERT(target < static_cast<int>(m_timestampsNs.size()));

  static auto& dashboard = UI::Dashboard::instance();
  const double range     = dashboard.plotTimeRange();
  const double targetSec = m_timestampsNs[static_cast<size_t>(target)] / 1e9;

  const int minStart = qMax(0, target - qMax(1, dashboard.points()) + 1);
  const int capStart = qMax(0, target - kMaxSeekWindowRows + 1);

  int start = minStart;
  for (int i = 0; i < kMaxSeekWindowRows && start > capStart; ++i) {
    const double sec = m_timestampsNs[static_cast<size_t>(start - 1)] / 1e9;
    if (targetSec - sec > range)
      break;

    --start;
  }

  return start;
}

void Sessions::Player::performSeekTick()
{
  if (!isOpen() || isPlaying())
    return;

  Q_ASSERT(m_framePos >= 0);
  Q_ASSERT(m_framePos < frameCount());

  static auto& appState = AppState::instance();
  if (appState.operationMode() != SerialStudio::ProjectFile || m_uidToColumn.isEmpty()) {
    performSeekSettle();
    return;
  }

  static auto& dashboard = UI::Dashboard::instance();
  const int target       = m_framePos;
  const int start        = seekWindowStartRow(target);

  QVector<double> times;
  QHash<qint64, QVector<double>> series;
  buildSeekWindow(start, target, times, series);
  dashboard.bulkLoadPlotWindow(times, series);

  anchorSteadyBase(target);
  injectFrame(buildFrameAt(m_timestampsNs[static_cast<size_t>(target)]),
              m_timestampsNs[static_cast<size_t>(target)]);
}

static void fillSeekGaps(QVector<double>& values)
{
  int firstSet = -1;
  const int n  = values.size();
  for (int k = 0; k < n; ++k)
    if (std::isnan(values[k]))
      values[k] = (k > 0) ? values[k - 1] : values[k];
    else if (firstSet < 0)
      firstSet = k;

  const double seed = (firstSet >= 0) ? values[firstSet] : 0.0;
  for (int k = 0; k < n && std::isnan(values[k]); ++k)
    values[k] = seed;
}

void Sessions::Player::buildSeekWindow(int startRow,
                                       int endRow,
                                       QVector<double>& times,
                                       QHash<qint64, QVector<double>>& series)
{
  Q_ASSERT(startRow >= 0);
  Q_ASSERT(startRow <= endRow);
  Q_ASSERT(endRow < frameCount());

  const int n = endRow - startRow + 1;
  times.resize(n);
  for (int k = 0; k < n; ++k)
    times[k] = m_timestampsNs[static_cast<size_t>(startRow + k)] / 1e9;

  if (!m_db) [[unlikely]]
    return;

  static auto& dashboard = UI::Dashboard::instance();
  const auto pairs       = dashboard.replaySeekSeries();
  QHash<int, qint64> keyByUid;
  for (const auto& pair : pairs) {
    const auto colIt = m_uidToColumn.constFind(pair.second);
    if (colIt == m_uidToColumn.constEnd())
      continue;

    const qint64 key = UI::Dashboard::replaySeekKey(pair.first, pair.second);
    keyByUid.insert(pair.second, key);
    series.insert(key, QVector<double>(n, std::numeric_limits<double>::quiet_NaN()));
  }

  if (keyByUid.isEmpty())
    return;

  if (!m_seekQueryPrepared) {
    m_seekQuery.emplace(*m_db);
    m_seekQuery->setForwardOnly(true);
    const bool prepared = m_seekQuery->prepare(
      m_hasFinalValues ? QStringLiteral("SELECT unique_id, final_numeric_value, timestamp_ns "
                                        "FROM readings WHERE session_id = ? AND timestamp_ns "
                                        "BETWEEN ? AND ? ORDER BY timestamp_ns, reading_id")
                       : QStringLiteral("SELECT unique_id, raw_numeric_value, timestamp_ns "
                                        "FROM readings WHERE session_id = ? AND timestamp_ns "
                                        "BETWEEN ? AND ? ORDER BY timestamp_ns, reading_id"));
    if (!prepared) [[unlikely]] {
      qWarning() << "[Sessions::Player] seek query prepare failed:"
                 << m_seekQuery->lastError().text();
      m_seekQuery.reset();
      series.clear();
      return;
    }

    m_seekQueryPrepared = true;
  }

  m_seekQuery->bindValue(0, m_sessionId);
  m_seekQuery->bindValue(1, m_timestampsNs[static_cast<size_t>(startRow)]);
  m_seekQuery->bindValue(2, m_timestampsNs[static_cast<size_t>(endRow)]);

  if (!m_seekQuery->exec()) [[unlikely]] {
    qWarning() << "[Sessions::Player] seek window query failed:" << m_seekQuery->lastError().text();
    series.clear();
    return;
  }

  const auto begin = m_timestampsNs.cbegin() + startRow;
  const auto end   = m_timestampsNs.cbegin() + endRow + 1;
  while (m_seekQuery->next()) {
    const auto keyIt = keyByUid.constFind(m_seekQuery->value(0).toInt());
    if (keyIt == keyByUid.constEnd())
      continue;

    const qint64 tsNs = m_seekQuery->value(2).toLongLong();
    const auto pos    = std::lower_bound(begin, end, tsNs);
    if (pos == end || *pos != tsNs)
      continue;

    const int idx              = static_cast<int>(pos - begin);
    series[keyIt.value()][idx] = SerialStudio::toDouble(m_seekQuery->value(1));
  }

  m_seekQuery->finish();

  for (auto it = series.begin(); it != series.end(); ++it)
    fillSeekGaps(it.value());
}

QList<std::pair<int, int>> UI::Dashboard::replaySeekSeries() const
{
  QList<std::pair<int, int>> out;
  QSet<qint64> seen;

  auto add = [&](int sourceId, int uniqueId) {
    const qint64 key = replaySeekKey(sourceId, uniqueId);
    if (seen.contains(key))
      return;

    seen.insert(key);
    out.append({sourceId, uniqueId});
  };

  const int plotCount = widgetCount(SerialStudio::DashboardPlot);
  for (int i = 0; i < plotCount; ++i) {
    const auto& ds = getDatasetWidget(SerialStudio::DashboardPlot, i);
    add(ds.sourceId, ds.uniqueId);

    if (useTimeXAxis(ds) || !SerialStudio::datasetXAxisEnabled())
      continue;

    const auto xIt = m_datasets.constFind(ds.xAxisId);
    if (xIt != m_datasets.constEnd())
      add(xIt.value().sourceId, ds.xAxisId);
  }

  const int multiCount = widgetCount(SerialStudio::DashboardMultiPlot);
  for (int i = 0; i < multiCount; ++i) {
    const auto& group = getGroupWidget(SerialStudio::DashboardMultiPlot, i);
    for (const auto& ds : group.datasets)
      add(group.sourceId, ds.uniqueId);
  }

  return out;
}

void UI::Dashboard::fillSeekPlotSingle(int index,
                                       const QVector<double>& timesSec,
                                       const QHash<qint64, QVector<double>>& series,
                                       double timeOffset,
                                       QSet<const DSP::AxisData*>& filled)
{
  Q_ASSERT(index >= 0);
  Q_ASSERT(index < widgetCount(SerialStudio::DashboardPlot));

  const auto& ds     = getDatasetWidget(SerialStudio::DashboardPlot, index);
  const auto& values = series.value(replaySeekKey(ds.sourceId, ds.uniqueId));
  const int count    = qMin(timesSec.size(), values.size());

  if (useTimeXAxis(ds)) {
    const auto rIt = m_plotTimeRings.find(index);
    if (rIt == m_plotTimeRings.end()) [[unlikely]]
      return;

    rIt.value().clear();
    for (int k = 0; k < count; ++k)
      rIt.value().appendDecimated(timesSec[k] + timeOffset, values[k]);

    return;
  }

  const auto yIt = m_yAxisData.find(ds.uniqueId);
  if (yIt != m_yAxisData.end() && !filled.contains(&yIt.value())) {
    filled.insert(&yIt.value());
    yIt.value().clear();
    for (int k = 0; k < count; ++k)
      yIt.value().push(values[k]);
  }

  if (!SerialStudio::datasetXAxisEnabled())
    return;

  const auto xDsIt = m_datasets.constFind(ds.xAxisId);
  if (xDsIt == m_datasets.constEnd())
    return;

  const auto xIt = m_xAxisData.find(ds.xAxisId);
  if (xIt == m_xAxisData.end() || filled.contains(&xIt.value()))
    return;

  const auto& xValues = series.value(replaySeekKey(xDsIt.value().sourceId, ds.xAxisId));
  const int xCount    = qMin(timesSec.size(), xValues.size());
  filled.insert(&xIt.value());
  xIt.value().clear();
  for (int k = 0; k < xCount; ++k)
    xIt.value().push(xValues[k]);
}

void UI::Dashboard::fillSeekPlotMulti(int index,
                                      const QVector<double>& timesSec,
                                      const QHash<qint64, QVector<double>>& series,
                                      double timeOffset)
{
  Q_ASSERT(index >= 0);
  Q_ASSERT(index < widgetCount(SerialStudio::DashboardMultiPlot));

  const auto& group = getGroupWidget(SerialStudio::DashboardMultiPlot, index);

  const auto rIt = m_multiplotTimeRings.find(index);
  if (rIt != m_multiplotTimeRings.end()) {
    auto& rings        = rIt.value();
    const size_t count = std::min(group.datasets.size(), rings.size());
    for (size_t j = 0; j < count; ++j) {
      const auto& ds     = group.datasets[j];
      const auto& values = series.value(replaySeekKey(group.sourceId, ds.uniqueId));
      const int n        = qMin(timesSec.size(), values.size());
      rings[j].clear();
      for (int k = 0; k < n; ++k)
        rings[j].appendDecimated(timesSec[k] + timeOffset, values[k]);
    }

    return;
  }

  if (index >= m_multipltValues.size()) [[unlikely]]
    return;

  auto& multiSeries  = m_multipltValues[index];
  const size_t count = std::min(group.datasets.size(), multiSeries.y.size());
  for (size_t j = 0; j < count; ++j) {
    const auto& ds     = group.datasets[j];
    const auto& values = series.value(replaySeekKey(group.sourceId, ds.uniqueId));
    const int n        = qMin(timesSec.size(), values.size());
    multiSeries.y[j].clear();
    for (int k = 0; k < n; ++k)
      multiSeries.y[j].push(values[k]);
  }
}

void UI::Dashboard::bulkLoadPlotWindow(const QVector<double>& timesSec,
                                       const QHash<qint64, QVector<double>>& series)
{
  Q_ASSERT(std::is_sorted(timesSec.cbegin(), timesSec.cend()));

  if (!m_layoutValid || timesSec.isEmpty()) [[unlikely]]
    return;

  const double timeOffset = -timesSec.last();

  QSet<const DSP::AxisData*> filled;
  const int plotCount = widgetCount(SerialStudio::DashboardPlot);
  for (int i = 0; i < plotCount; ++i)
    fillSeekPlotSingle(i, timesSec, series, timeOffset, filled);

  const int multiCount = widgetCount(SerialStudio::DashboardMultiPlot);
  for (int i = 0; i < multiCount; ++i)
    fillSeekPlotMulti(i, timesSec, series, timeOffset);

  for (auto it = m_plotSweep.begin(); it != m_plotSweep.end(); ++it)
    it.value().resetState();

  for (auto it = m_multiplotSweep.begin(); it != m_multiplotSweep.end(); ++it)
    it.value().resetState();

  m_plotClocks.clear();
  m_plotDisplayTimeSec = 0.0;
  m_updateRequired     = true;
}

API::CommandResponse API::Handlers::ProjectHandler::datasetGetFFTMarkers(const QString& id,
                                                                         const QJsonObject& params)
{
  const QStringList required{QString(Keys::GroupId), QString(Keys::DatasetId)};
  for (const auto& key : required)
    if (!params.contains(key))
      return CommandResponse::makeError(
        id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: %1").arg(key));

  const int groupId   = params.value(Keys::GroupId).toInt();
  const int datasetId = params.value(Keys::DatasetId).toInt();

  static auto& pm    = DataModel::ProjectModel::instance();
  const auto& groups = pm.groups();
  const auto git     = std::find_if(
    groups.begin(), groups.end(), [groupId](const auto& g) { return g.groupId == groupId; });

  if (git == groups.end())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  const auto& datasets = git->datasets;
  const auto dit       = std::find_if(datasets.begin(), datasets.end(), [datasetId](const auto& d) {
    return d.datasetId == datasetId;
  });

  if (dit == datasets.end())
    return CommandResponse::makeError(id,
                                      ErrorCode::InvalidParam,
                                      QStringLiteral("Dataset id not found in group: %1/%2")
                                        .arg(QString::number(groupId), QString::number(datasetId)));

  QJsonArray markers;
  for (const auto& m : dit->fftMarkers)
    markers.append(DataModel::serialize(m));

  QJsonObject result;
  result[Keys::GroupId]             = groupId;
  result[Keys::DatasetId]           = datasetId;
  result[Keys::FFTMarkers]          = markers;
  result[QStringLiteral("count")]   = markers.size();
  result[QStringLiteral("nyquist")] = qMax(1, dit->fftSamplingRate) * 0.5;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::datasetSetFFTMarkers(const QString& id,
                                                                         const QJsonObject& params)
{
  const QStringList required{
    QString(Keys::GroupId), QString(Keys::DatasetId), QString(Keys::FFTMarkers)};
  for (const auto& key : required)
    if (!params.contains(key))
      return CommandResponse::makeError(
        id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: %1").arg(key));

  const int groupId   = params.value(Keys::GroupId).toInt();
  const int datasetId = params.value(Keys::DatasetId).toInt();
  const auto arr      = params.value(Keys::FFTMarkers).toArray();

  static auto& pm    = DataModel::ProjectModel::instance();
  const auto& groups = pm.groups();
  const auto git     = std::find_if(
    groups.begin(), groups.end(), [groupId](const auto& g) { return g.groupId == groupId; });

  if (git == groups.end())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  const auto& datasets = git->datasets;
  const auto dit       = std::find_if(datasets.begin(), datasets.end(), [datasetId](const auto& d) {
    return d.datasetId == datasetId;
  });

  if (dit == datasets.end())
    return CommandResponse::makeError(id,
                                      ErrorCode::InvalidParam,
                                      QStringLiteral("Dataset id not found in group: %1/%2")
                                        .arg(QString::number(groupId), QString::number(datasetId)));

  DataModel::Dataset updated = *dit;
  updated.fftMarkers.clear();
  updated.fftMarkers.reserve(arr.size());

  int dropped = 0;
  for (const auto& v : arr) {
    DataModel::FrequencyMarker m;
    if (DataModel::read(m, v.toObject()))
      updated.fftMarkers.push_back(std::move(m));
    else
      ++dropped;
  }

  pm.updateDataset(groupId, datasetId, updated, true);

  QJsonObject result;
  result[Keys::GroupId]             = groupId;
  result[Keys::DatasetId]           = datasetId;
  result[QStringLiteral("count")]   = static_cast<int>(updated.fftMarkers.size());
  result[QStringLiteral("updated")] = true;
  if (dropped > 0)
    result[QStringLiteral("droppedInvalid")] = dropped;

  return CommandResponse::makeSuccess(id, result);
}

static void applyDatasetFrequencyMarkerField(DataModel::Dataset& d,
                                             const QJsonObject& params,
                                             QSet<QString>& consumed)
{
  if (!takeParam(params, consumed, Keys::FFTMarkers))
    return;

  d.fftMarkers.clear();
  const auto arr = params.value(Keys::FFTMarkers).toArray();
  d.fftMarkers.reserve(arr.size());
  for (const auto& v : arr) {
    DataModel::FrequencyMarker m;
    if (DataModel::read(m, v.toObject()))
      d.fftMarkers.push_back(std::move(m));
  }
}

bool DataModel::read(FrequencyMarker& m, const QJsonObject& obj)
{
  constexpr double nan        = std::numeric_limits<double>::quiet_NaN();
  constexpr double max_freqHz = 2147483648.0;
  if (obj.isEmpty())
    return false;

  m.frequency    = SerialStudio::toDouble(ss_jsr(obj, Keys::Frequency, 0));
  m.endFrequency = SerialStudio::toDouble(ss_jsr(obj, Keys::EndFrequency, 0));
  m.warningDb =
    obj.contains(Keys::WarningDb) ? SerialStudio::toDouble(obj.value(Keys::WarningDb)) : nan;
  m.alarmDb = obj.contains(Keys::AlarmDb) ? SerialStudio::toDouble(obj.value(Keys::AlarmDb)) : nan;
  m.color   = ss_jsr(obj, Keys::Color, "").toString().simplified();
  m.label   = ss_jsr(obj, Keys::Label, "").toString().simplified();

  if (!std::isfinite(m.frequency) || m.frequency <= 0.0 || m.frequency > max_freqHz)
    return false;

  if (!std::isfinite(m.endFrequency) || m.endFrequency <= m.frequency)
    m.endFrequency = 0.0;
  else
    m.endFrequency = qMin(m.endFrequency, max_freqHz);

  if (std::isfinite(m.warningDb) && std::isfinite(m.alarmDb) && m.warningDb > m.alarmDb)
    std::swap(m.warningDb, m.alarmDb);

  if (!m.color.isEmpty() && !QColor::fromString(m.color).isValid())
    m.color.clear();

  return true;
}

void DataModel::readDatasetFrequencyMarkers(Dataset& d, const QJsonObject& obj)
{
  d.fftMarkers.clear();
  if (!obj.contains(Keys::FFTMarkers))
    return;

  const auto arr = obj.value(Keys::FFTMarkers).toArray();
  d.fftMarkers.reserve(arr.size());
  for (const auto& v : arr) {
    FrequencyMarker m;
    if (read(m, v.toObject()))
      d.fftMarkers.push_back(std::move(m));
  }
}

void DataModel::ProjectEditor::commitFrequencyMarkers(const QVariantList& markers)
{
  constexpr double nan        = std::numeric_limits<double>::quiet_NaN();
  constexpr double max_freqHz = 2147483648.0;

  m_selectedDataset.fftMarkers.clear();
  m_selectedDataset.fftMarkers.reserve(markers.size());
  for (const auto& v : markers) {
    const auto m = v.toMap();
    DataModel::FrequencyMarker marker;
    marker.frequency    = SerialStudio::toDouble(m.value(QStringLiteral("freq")));
    marker.endFrequency = SerialStudio::toDouble(m.value(QStringLiteral("endFreq")));
    marker.label        = m.value(QStringLiteral("label")).toString().simplified();
    marker.color        = m.value(QStringLiteral("color")).toString().simplified();

    const auto warning = m.value(QStringLiteral("warningDb"));
    const auto alarm   = m.value(QStringLiteral("alarmDb"));
    marker.warningDb   = warning.isValid() ? SerialStudio::toDouble(warning) : nan;
    marker.alarmDb     = alarm.isValid() ? SerialStudio::toDouble(alarm) : nan;

    if (!std::isfinite(marker.frequency) || marker.frequency <= 0.0
        || marker.frequency > max_freqHz)
      continue;

    if (!std::isfinite(marker.endFrequency) || marker.endFrequency <= marker.frequency)
      marker.endFrequency = 0.0;
    else
      marker.endFrequency = qMin(marker.endFrequency, max_freqHz);

    if (std::isfinite(marker.warningDb) && std::isfinite(marker.alarmDb)
        && marker.warningDb > marker.alarmDb)
      std::swap(marker.warningDb, marker.alarmDb);

    m_selectedDataset.fftMarkers.push_back(std::move(marker));
  }

  auto& pm = m_projectModelRef;
  pm.updateDataset(
    m_selectedDataset.groupId, m_selectedDataset.datasetId, m_selectedDataset, false);
  buildDatasetModel(m_selectedDataset);
}

double Widgets::FFTPlot::markerPeakDb(int index) const
{
  if (index < 0 || index >= static_cast<int>(m_markerRt.size()))
    return kSpectrumFloorDb;

  return m_markerRt[static_cast<std::size_t>(index)].peakDb;
}

int Widgets::FFTPlot::markerState(int index) const
{
  if (index < 0 || index >= static_cast<int>(m_markerRt.size()))
    return 0;

  return m_markerRt[static_cast<std::size_t>(index)].state;
}

void Widgets::FFTPlot::loadMarkers()
{
  if (!VALIDATE_WIDGET(SerialStudio::DashboardFFT, m_index))
    return;

  const auto& dataset = GET_DATASET(SerialStudio::DashboardFFT, m_index);
  m_markerRt.clear();
  m_markerConfig.clear();
  m_markerRt.reserve(dataset.fftMarkers.size());
  m_markerConfig.reserve(static_cast<int>(dataset.fftMarkers.size()));
  for (const auto& m : dataset.fftMarkers) {
    MarkerRuntime rt;
    rt.freqLo    = m.frequency;
    rt.freqHi    = m.endFrequency;
    rt.warningDb = static_cast<float>(m.warningDb);
    rt.alarmDb   = static_cast<float>(m.alarmDb);
    rt.peakDb    = kSpectrumFloorDb;
    rt.state     = 0;
    rt.binLo     = 0;
    rt.binHi     = 0;
    m_markerRt.push_back(rt);

    QVariantMap entry;
    entry.insert(QStringLiteral("freq"), m.frequency);
    entry.insert(QStringLiteral("endFreq"), m.endFrequency);
    entry.insert(QStringLiteral("label"), m.label);
    entry.insert(QStringLiteral("color"), m.color);
    entry.insert(QStringLiteral("hasThresholds"),
                 std::isfinite(m.warningDb) || std::isfinite(m.alarmDb));
    m_markerConfig.append(entry);
  }
}

void Widgets::FFTPlot::rebuildMarkerBins()
{
  constexpr double pointHalfWindow = 2.0;
  Q_ASSERT(m_size > 0);
  Q_ASSERT(m_samplingRate > 0);

  const int spectrumSize = m_size / 2;
  const double freqStep  = static_cast<double>(m_samplingRate) / qMax(1, m_size);
  const double lastBin   = qMax(0, spectrumSize - 1);
  for (auto& rt : m_markerRt) {
    double lo = 0.0;
    double hi = 0.0;
    if (rt.freqHi > rt.freqLo) {
      lo = std::floor(rt.freqLo / freqStep);
      hi = std::ceil(rt.freqHi / freqStep);
    } else {
      const double center = std::round(rt.freqLo / freqStep);
      lo                  = center - pointHalfWindow;
      hi                  = center + pointHalfWindow;
    }

    rt.binLo = static_cast<int>(qBound(0.0, lo, lastBin));
    rt.binHi = static_cast<int>(qBound(static_cast<double>(rt.binLo), hi, lastBin));
  }
}

void Widgets::FFTPlot::updateMarkerValues(const int spectrumSize)
{
  Q_ASSERT(spectrumSize > 0);
  Q_ASSERT(m_binDb.size() >= static_cast<std::size_t>(spectrumSize));

  for (auto& rt : m_markerRt) {
    const int hi = qMin(rt.binHi, spectrumSize - 1);
    float peak   = kSpectrumFloorDb;
    for (int i = qMin(rt.binLo, hi); i <= hi; ++i)
      peak = std::max(peak, m_binDb[static_cast<std::size_t>(i)]);

    rt.peakDb = peak;
    if (std::isfinite(rt.alarmDb) && peak >= rt.alarmDb)
      rt.state = 2;
    else if (std::isfinite(rt.warningDb) && peak >= rt.warningDb)
      rt.state = 1;
    else
      rt.state = 0;
  }
}

void Widgets::Waterfall::loadMarkers()
{
  if (!VALIDATE_WIDGET(SerialStudio::DashboardWaterfall, m_index))
    return;

  const auto& dataset = GET_DATASET(SerialStudio::DashboardWaterfall, m_index);
  m_markers.clear();
  m_markers.reserve(dataset.fftMarkers.size());
  for (const auto& m : dataset.fftMarkers) {
    MarkerData d;
    d.freqLo      = m.frequency;
    d.freqHi      = m.endFrequency;
    d.warningDb   = static_cast<float>(m.warningDb);
    d.alarmDb     = static_cast<float>(m.alarmDb);
    d.peakDb      = kFloorDb;
    d.state       = 0;
    d.customColor = m.color.isEmpty() ? QColor() : QColor::fromString(m.color);
    d.label       = m.label;
    m_markers.push_back(std::move(d));
  }
}

void Widgets::Waterfall::updateMarkerStates(const int spectrumSize)
{
  constexpr double pointHalfWindow = 2.0;
  Q_ASSERT(spectrumSize > 0);
  Q_ASSERT(m_smoothed.size() >= static_cast<std::size_t>(spectrumSize));

  const double freqStep = static_cast<double>(m_samplingRate) / qMax(1, m_size);
  const double lastBin  = qMax(0, spectrumSize - 1);
  for (auto& m : m_markers) {
    double loF = 0.0;
    double hiF = 0.0;
    if (m.freqHi > m.freqLo) {
      loF = std::floor(m.freqLo / freqStep);
      hiF = std::ceil(m.freqHi / freqStep);
    } else {
      const double center = std::round(m.freqLo / freqStep);
      loF                 = center - pointHalfWindow;
      hiF                 = center + pointHalfWindow;
    }

    const int lo = static_cast<int>(qBound(0.0, loF, lastBin));
    const int hi = static_cast<int>(qBound(static_cast<double>(lo), hiF, lastBin));

    float peak = kFloorDb;
    for (int i = lo; i <= hi; ++i)
      peak = std::max(peak, m_smoothed[i]);

    m.peakDb = peak;
    if (std::isfinite(m.alarmDb) && peak >= m.alarmDb)
      m.state = 2;
    else if (std::isfinite(m.warningDb) && peak >= m.warningDb)
      m.state = 1;
    else
      m.state = 0;
  }
}

void Widgets::Waterfall::rebuildLogColumnTable()
{
  const int width       = qMax(1, m_size / 2);
  const double freqStep = static_cast<double>(m_samplingRate) / qMax(1, m_size);
  const double nyquist  = m_samplingRate * 0.5;

  m_logActive = m_logX && width >= 4 && nyquist > freqStep;
  markAxisDirty();
  if (!m_logActive)
    return;

  m_logMin = std::log10(freqStep);
  m_logMax = std::log10(nyquist);

  m_logRow.resize(static_cast<std::size_t>(width));
  m_logColBin.resize(static_cast<std::size_t>(width));
  m_logColFrac.resize(static_cast<std::size_t>(width));

  const double logRange = m_logMax - m_logMin;
  const int lastPair    = width - 2;
  for (int x = 0; x < width; ++x) {
    const double t   = (x + 0.5) / width;
    const double f   = std::exp((m_logMin + t * logRange) * kLn10);
    const double pos = qBound(1.0, f / freqStep, static_cast<double>(width - 1));
    const int idx    = qBound(1, static_cast<int>(pos), lastPair);
    m_logColBin[static_cast<std::size_t>(x)]  = idx;
    m_logColFrac[static_cast<std::size_t>(x)] = static_cast<float>(qBound(0.0, pos - idx, 1.0));
  }
}

const float* Widgets::Waterfall::imageRow(const float* dbValues, int bins)
{
  Q_ASSERT(dbValues);
  if (!m_logActive || m_logColBin.size() != static_cast<std::size_t>(bins)
      || m_logRow.size() != static_cast<std::size_t>(bins))
    return dbValues;

  for (int x = 0; x < bins; ++x) {
    const int idx                         = m_logColBin[static_cast<std::size_t>(x)];
    const float fr                        = m_logColFrac[static_cast<std::size_t>(x)];
    const float lo                        = dbValues[idx];
    const float hi                        = dbValues[idx + 1];
    m_logRow[static_cast<std::size_t>(x)] = lo + (hi - lo) * fr;
  }

  return m_logRow.data();
}

double Widgets::Waterfall::worldFromFreq(double hz) const
{
  if (!m_logActive)
    return hz;

  const double freqStep = static_cast<double>(m_samplingRate) / qMax(1, m_size);
  return std::log10(qMax(hz, freqStep));
}

double Widgets::Waterfall::freqFromWorld(double w) const
{
  if (!m_logActive)
    return w;

  return std::exp(w * kLn10);
/**
 * @brief Converts the FFT output to smoothed display dB per bin (shared 1/N^2 power norm,
 *        3-bin boxcar) into m_smoothed.
 */
void Widgets::Waterfall::computeSmoothedRow(const int spectrumSize)
{
  Q_ASSERT(spectrumSize > 0);
  Q_ASSERT(m_fftOutput.size() >= static_cast<std::size_t>(spectrumSize));

  const float normFactor = static_cast<float>(m_size) * static_cast<float>(m_size);
  const float invNorm    = 1.0f / normFactor;
  for (int i = 0; i < spectrumSize; ++i) {
    const float re    = m_fftOutput[i].r;
    const float im    = m_fftOutput[i].i;
    const float power = std::max((re * re + im * im) * invNorm, kEpsSquared);
    m_dbCache[i]      = std::max(10.0f * std::log10(power), kFloorDb);
  }

  if (m_smoothed.size() < static_cast<size_t>(spectrumSize))
    m_smoothed.resize(spectrumSize);

  static constexpr float kInvSmoothingTaps[] = {
    0.0f,
    1.0f / 1.0f,
    1.0f / 2.0f,
    1.0f / 3.0f,
    1.0f / 4.0f,
    1.0f / 5.0f,
  };
  for (int i = 0; i < spectrumSize; ++i) {
    const int lo = std::max(0, i - kHalfSmoothWindow);
    const int hi = std::min(spectrumSize - 1, i + kHalfSmoothWindow);
    float sum    = 0.0f;
    for (int k = lo; k <= hi; ++k)
      sum += m_dbCache[k];

    const int taps = hi - lo + 1;
    m_smoothed[i]  = sum * kInvSmoothingTaps[taps];
  }
}

  computeSmoothedRow(spectrumSize);
  if (!m_markers.empty() && spectrumSize > 0)
    updateMarkerStates(spectrumSize);
  const float* row_data = imageRow(m_smoothed.data(), spectrumSize);
        writeRowAt(row, row_data, spectrumSize);
    writeRow(row_data, spectrumSize);
  if (m_markersVisible && !m_markers.empty())
    drawMarkers(painter, plotRect);

 * @brief Computes the visible frequency window [wMin, wMax] in axis WORLD units (Hz linear,
 *        log10-Hz log) from the zoom/pan view state; single source of truth for the axis,
 *        hover cursor, and marker Hz-to-pixel mapping.
 */
void Widgets::Waterfall::visibleFreqWindow(double& wMin, double& wMax) const
{
  const double w0     = m_logActive ? m_logMin : 0.0;
  const double w1     = m_logActive ? m_logMax : m_samplingRate * 0.5;
  const double range  = w1 - w0;
  const double srcW   = range / m_xZoom;
  const double maxPan = qMax(0.0, (range - srcW) * 0.5);
  const double center = (w0 + w1) * 0.5 + qBound(-maxPan, m_xPan * range, maxPan);
  wMin                = center - srcW * 0.5;
  wMax                = center + srcW * 0.5;
}

void Widgets::Waterfall::computeSmoothedRow(const int spectrumSize)
{
  Q_ASSERT(spectrumSize > 0);
  Q_ASSERT(m_fftOutput.size() >= static_cast<std::size_t>(spectrumSize));

  const float normFactor = static_cast<float>(m_size) * static_cast<float>(m_size);
  const float invNorm    = 1.0f / normFactor;
  for (int i = 0; i < spectrumSize; ++i) {
    const float re    = m_fftOutput[i].r;
    const float im    = m_fftOutput[i].i;
    const float power = std::max((re * re + im * im) * invNorm, kEpsSquared);
    m_dbCache[i]      = std::max(10.0f * std::log10(power), kFloorDb);
  }

  if (m_smoothed.size() < static_cast<size_t>(spectrumSize))
    m_smoothed.resize(spectrumSize);

  static constexpr float kInvSmoothingTaps[] = {
    0.0f,
    1.0f / 1.0f,
    1.0f / 2.0f,
    1.0f / 3.0f,
    1.0f / 4.0f,
    1.0f / 5.0f,
  };
  for (int i = 0; i < spectrumSize; ++i) {
    const int lo = std::max(0, i - kHalfSmoothWindow);
    const int hi = std::min(spectrumSize - 1, i + kHalfSmoothWindow);
    float sum    = 0.0f;
    for (int k = lo; k <= hi; ++k)
      sum += m_dbCache[k];

    const int taps = hi - lo + 1;
    m_smoothed[i]  = sum * kInvSmoothingTaps[taps];
  }
}

std::vector<double> Widgets::Waterfall::collectFreqTicks(double wMin, double wMax) const
{
  std::vector<double> out;
  if (!m_logActive) {
    const AxisTicks ticks = computeFreqTicks(wMax - wMin, kAxisTickCount);
    const double step     = ticks.step;
    const double first    = std::ceil(wMin / step - 1e-9) * step;
    for (double v = first; v <= wMax + 1e-6; v += step)
      out.push_back(v);

    return out;
  }

  constexpr double mants[] = {1.0, 2.0, 5.0};
  const int dLo            = static_cast<int>(std::floor(wMin)) - 1;
  const int dHi            = static_cast<int>(std::ceil(wMax)) + 1;
  for (int d = dLo; d <= dHi; ++d) {
    for (const double m : mants) {
      const double w = d + std::log10(m);
      if (w >= wMin - 1e-9 && w <= wMax + 1e-9)
        out.push_back(m * fastPow10(d));
    }
  }

  if (static_cast<int>(out.size()) > kAxisTickCount + 2) {
    std::vector<double> decades;
    decades.reserve(out.size());
    for (const double v : out) {
      const double lg = std::log10(v);
      if (std::abs(lg - std::round(lg)) < 1e-9)
        decades.push_back(v);
    }

    if (!decades.empty())
      out = std::move(decades);
  }

  if (static_cast<int>(out.size()) < 2) {
    out.clear();
    const double fLo      = freqFromWorld(wMin);
    const double fHi      = freqFromWorld(wMax);
    const AxisTicks ticks = computeFreqTicks(fHi - fLo, kAxisTickCount);
    const double first    = std::ceil(fLo / ticks.step - 1e-9) * ticks.step;
    for (double v = first; v <= fHi + 1e-6; v += ticks.step)
      out.push_back(v);
  }

  return out;
}

void Widgets::Waterfall::drawMarkers(QPainter* painter, const QRectF& plotRect) const
{
  Q_ASSERT(painter);
  Q_ASSERT(!m_markers.empty());
  m_chipHitRects.clear();
  if (plotRect.isEmpty() || m_samplingRate <= 0)
    return;

  double wMin = 0.0;
  double wMax = 0.0;
  visibleFreqWindow(wMin, wMax);
  const double range = wMax - wMin;
  if (range <= 0.0)
    return;

  painter->save();
  painter->setClipRect(plotRect);
  painter->setFont(m_commonFonts.widgetFont(0.8, false));

  const QFontMetrics fm(painter->font());
  double rowEnd[kMarkerChipRows] = {-1e18, -1e18, -1e18};
  const double invRange          = 1.0 / range;
  for (std::size_t i = 0; i < m_markers.size(); ++i) {
    const auto& m      = m_markers[i];
    const int idx      = static_cast<int>(i);
    const bool band    = m.freqHi > m.freqLo;
    const bool spotlit = m_selectedMarker == idx;
    const bool dimmed  = m_selectedMarker >= 0 && !spotlit;
    const double xLo =
      plotRect.left() + (worldFromFreq(m.freqLo) - wMin) * invRange * plotRect.width();
    const double xHi =
      band ? plotRect.left() + (worldFromFreq(m.freqHi) - wMin) * invRange * plotRect.width() : xLo;
    if (xHi < plotRect.left() || xLo > plotRect.right())
      continue;

    QColor base = m.customColor.isValid() ? m.customColor : m_accentColor;
    if (m.state == 2)
      base = m_alarmColor;
    else if (m.state == 1)
      base = m_warningColor;

    painter->setOpacity(dimmed ? 0.22 : 1.0);

    if (band) {
      QColor fill = base;
      fill.setAlpha(spotlit ? 78 : (m.state > 0 ? 64 : 40));
      painter->fillRect(QRectF(xLo, plotRect.top(), xHi - xLo, plotRect.height()), fill);

      QColor edge = base;
      edge.setAlpha(spotlit ? 200 : 120);
      const double ew = spotlit ? 2.0 : 1.0;
      painter->fillRect(QRectF(xLo, plotRect.top(), ew, plotRect.height()), edge);
      painter->fillRect(QRectF(xHi - ew, plotRect.top(), ew, plotRect.height()), edge);
    } else {
      QColor line = base;
      line.setAlpha(spotlit ? 255 : (m.state > 0 ? 240 : 170));
      const double lw = spotlit ? 3.0 : 2.0;
      painter->fillRect(QRectF(xLo - lw * 0.5, plotRect.top(), lw, plotRect.height()), line);
    }

    const QString name = m.label.isEmpty() ? formatFreqTick(m.freqLo) : m.label;
    const QString text = QObject::tr("%1  %2 dB").arg(name, QString::number(m.peakDb, 'f', 1));
    drawMarkerChip(painter, plotRect, fm, rowEnd, idx, spotlit, (xLo + xHi) * 0.5, text, base);
  }

  painter->setOpacity(1.0);
  painter->restore();
}

void Widgets::Waterfall::drawMarkerChip(QPainter* painter,
                                        const QRectF& plotRect,
                                        const QFontMetrics& fm,
                                        double* rowEnd,
                                        const int markerIndex,
                                        const bool spotlit,
                                        double cx,
                                        const QString& text,
                                        const QColor& color) const
{
  Q_ASSERT(painter);
  Q_ASSERT(rowEnd);

  const double w = fm.horizontalAdvance(text) + 8;
  const double h = fm.height() + 4;
  const double x =
    qBound(plotRect.left() + 2, cx - w * 0.5, qMax(plotRect.left() + 2, plotRect.right() - w - 2));

  int row = 0;
  while (row < kMarkerChipRows - 1 && rowEnd[row] > x - 4)
    ++row;

  rowEnd[row]    = qMax(rowEnd[row], x + w);
  const double y = plotRect.top() + 4 + row * (h + 2);
  const QRectF chipRect(x, y, w, h);
  m_chipHitRects.emplace_back(markerIndex, chipRect);

  QColor bg = color;
  bg.setAlpha(spotlit ? 255 : 230);
  painter->setPen(Qt::NoPen);
  painter->setBrush(bg);
  painter->drawRoundedRect(chipRect, 3, 3);

  if (spotlit) {
    painter->setPen(QPen(m_textColor, 1.5));
    painter->setBrush(Qt::NoBrush);
    painter->drawRoundedRect(chipRect, 3, 3);
  }

  painter->setPen(m_innerBg);
  painter->drawText(QPointF(x + 4, y + 2 + fm.ascent()), text);
}

int Widgets::Waterfall::markerChipAt(const QPointF& pos) const
{
  for (auto it = m_chipHitRects.rbegin(); it != m_chipHitRects.rend(); ++it)
    if (it->second.contains(pos))
      return it->first;

  return -1;
}

void Widgets::Waterfall::setMarkersVisible(const bool enabled)
{
  if (m_markersVisible == enabled)
    return;

  m_markersVisible = enabled;
  if (!enabled) {
    m_selectedMarker = -1;
    m_chipHitRects.clear();
  }

  Q_EMIT markersVisibleChanged();
  update();
}

void Widgets::FFTPlot::rebuildLogBinTable()
{
  Q_ASSERT(m_size > 0);
  Q_ASSERT(m_samplingRate > 0);

  const int spectrumSize = m_size / 2;
  const double freqStep  = static_cast<double>(m_samplingRate) / m_size;
  m_logBinX.resize(static_cast<std::size_t>(spectrumSize));
  m_pchipSlope.resize(static_cast<std::size_t>(spectrumSize));
  for (int i = 0; i < spectrumSize; ++i) {
    const double freq = i * freqStep;
    m_logBinX[static_cast<std::size_t>(i)] =
      static_cast<float>(LogScale::clampedLog10(freq, freqStep));
  }

  if (m_xData.size() != static_cast<std::size_t>(kLogRenderPoints)) {
    m_xData.resize(kLogRenderPoints);
    m_xData.clear();
    m_yData.resize(kLogRenderPoints);
    m_yData.clear();
  }
}

void Widgets::FFTPlot::buildLogRenderCurve(const int spectrumSize)
{
  const int first = 1;
  const int last  = spectrumSize - 1;
  Q_ASSERT(spectrumSize >= 4);
  Q_ASSERT(m_logBinX.size() == static_cast<std::size_t>(spectrumSize));

  const float* xs = m_logBinX.data();
  const float* ys = m_binDb.data();
  float* slope    = m_pchipSlope.data();

  float hPrev  = xs[first + 1] - xs[first];
  float dPrev  = (ys[first + 1] - ys[first]) / hPrev;
  slope[first] = dPrev;
  for (int i = first + 1; i < last; ++i) {
    const float h = xs[i + 1] - xs[i];
    const float d = (ys[i + 1] - ys[i]) / h;
    if (dPrev * d <= 0.0f)
      slope[i] = 0.0f;
    else {
      const float w1 = 2.0f * h + hPrev;
      const float w2 = h + 2.0f * hPrev;
      slope[i]       = (w1 + w2) / (w1 / dPrev + w2 / d);
    }

    hPrev = h;
    dPrev = d;
  }
  slope[last] = dPrev;

  const float x0 = xs[first];
  const float x1 = xs[last];
  const float dx = (x1 - x0) / static_cast<float>(kLogRenderPoints - 1);
  int seg        = first;
  for (int j = 0; j < kLogRenderPoints; ++j) {
    const float x = x0 + static_cast<float>(j) * dx;
    // code-verify off
    while (seg + 1 < last && xs[seg + 1] < x)
      ++seg;
    // code-verify on

    const float h   = xs[seg + 1] - xs[seg];
    const float t   = qBound(0.0f, (x - xs[seg]) / h, 1.0f);
    const float t2  = t * t;
    const float t3  = t2 * t;
    const float h00 = 2.0f * t3 - 3.0f * t2 + 1.0f;
    const float h10 = t3 - 2.0f * t2 + t;
    const float h01 = -2.0f * t3 + 3.0f * t2;
    const float h11 = t3 - t2;
    const float y =
      h00 * ys[seg] + h10 * h * slope[seg] + h01 * ys[seg + 1] + h11 * h * slope[seg + 1];

    m_xData.push(x);
    m_yData.push(y);
  }
}

void Widgets::FFTPlot::updateBallisticsAlpha()
{
  if (!m_ballistics)
    return;

  if (!m_ballisticsClock.isValid()) {
    m_ballisticsClock.start();
    m_releaseAlpha = 1.0f;
    return;
  }

  const double dt  = m_ballisticsClock.nsecsElapsed() * 1e-9;
  const double tau = m_releaseMs * 1e-3;
  m_ballisticsClock.restart();
  m_releaseAlpha = static_cast<float>(1.0 - std::exp(-dt / tau));
}

void Widgets::FFTPlot::resetBallistics(const int bins)
{
  Q_ASSERT(bins > 0);
  m_displayDb.assign(static_cast<std::size_t>(bins), kSpectrumFloorDb);
  m_ballisticsClock.invalidate();
}

float Widgets::FFTPlot::applyBallistics(const std::size_t idx, const float freshDb)
{
  if (!m_ballistics)
    return freshDb;

  Q_ASSERT(idx < m_displayDb.size());
  float& shown = m_displayDb[idx];
  shown        = freshDb >= shown ? freshDb : shown + (freshDb - shown) * m_releaseAlpha;
  return shown;
}

void Widgets::MultiPlot::applyLogYToCurve(QList<QPointF>& curve)
{
  if (!m_logY)
    return;

  QPointF* points = curve.data();
  for (qsizetype i = 0; i < curve.size(); ++i)
    points[i].setY(LogScale::clampedLog10(points[i].y()));
}

void Widgets::MultiPlot::buildLogXScratch(const DSP::AxisData& x, const double floor)
{
  if (m_logXScratch.capacity() == x.capacity() && m_logXScratch.size() == x.size())
    return;

  if (m_logXScratch.capacity() != x.capacity())
    m_logXScratch.resize(x.capacity());

  Q_ASSERT(x.raw() != nullptr);
  Q_ASSERT(x.size() <= m_logXScratch.capacity());

  m_logXScratch.clear();

  const auto* data       = x.raw();
  const std::size_t mask = x.storageMask();
  std::size_t idx        = x.frontIndex();
  const std::size_t n    = x.size();
  for (std::size_t i = 0; i < n; ++i) {
    m_logXScratch.push(LogScale::clampedLog10(data[idx], floor));
    idx = (idx + 1) & mask;
  }
}

void Widgets::Plot::applyLogYToRender()
{
  if (!m_logY)
    return;

  QPointF* points = m_data.data();
  for (qsizetype i = 0; i < m_data.size(); ++i)
    points[i].setY(LogScale::clampedLog10(points[i].y()));
}

void Widgets::Plot::buildLogXScratch(const DSP::AxisData& x, const double floor)
{
  if (m_logXScratch.capacity() == x.capacity() && m_logXScratch.size() == x.size())
    return;

  if (m_logXScratch.capacity() != x.capacity())
    m_logXScratch.resize(x.capacity());

  Q_ASSERT(x.raw() != nullptr);
  Q_ASSERT(x.size() <= m_logXScratch.capacity());

  m_logXScratch.clear();

  const auto* data       = x.raw();
  const std::size_t mask = x.storageMask();
  std::size_t idx        = x.frontIndex();
  const std::size_t n    = x.size();
  for (std::size_t i = 0; i < n; ++i) {
    m_logXScratch.push(LogScale::clampedLog10(data[idx], floor));
    idx = (idx + 1) & mask;
  }
}

void Widgets::Plot::applyDatasetXRange(const DataModel::Dataset& dx)
{
  double lo = qMin(dx.pltMin, dx.pltMax);
  double hi = qMax(dx.pltMin, dx.pltMax);
  if (m_logX && !LogScale::resolveLogBounds(lo, hi))
    return;

  m_minX = lo;
  m_maxX = hi;
}

void API::Handlers::DashboardHandler::registerWidgetDisplayCommands()
{
  static auto& registry = CommandRegistry::instance();

  QJsonObject emptySchema;
  emptySchema.insert(QStringLiteral("type"), QStringLiteral("object"));
  emptySchema.insert(QStringLiteral("properties"), QJsonObject());

  QJsonObject uidProp;
  uidProp.insert(QStringLiteral("type"), QStringLiteral("integer"));
  uidProp.insert(QStringLiteral("description"),
                 QStringLiteral("Stable uniqueId of the dataset or group the widget displays"));

  QJsonObject typeProp;
  typeProp.insert(QStringLiteral("type"), QStringLiteral("integer"));
  typeProp.insert(QStringLiteral("description"),
                  QStringLiteral("SerialStudio::DashboardWidget enum value of the widget"));

  QJsonObject titleProp;
  titleProp.insert(QStringLiteral("type"), QStringLiteral("string"));
  titleProp.insert(QStringLiteral("description"),
                   QStringLiteral("Display title override; empty or absent clears the override"));

  QJsonObject titleProps;
  titleProps.insert(Keys::UniqueId, uidProp);
  titleProps.insert(QStringLiteral("title"), titleProp);
  titleProps.insert(QStringLiteral("widgetType"), typeProp);

  QJsonObject setTitleSchema;
  setTitleSchema.insert(QStringLiteral("type"), QStringLiteral("object"));
  setTitleSchema.insert(QStringLiteral("properties"), titleProps);
  setTitleSchema.insert(QStringLiteral("required"), QJsonArray{QString(Keys::UniqueId)});

  registry.registerCommand(
    QStringLiteral("project.dashboard.setWidgetTitle"),
    QStringLiteral("Set a display-title override for the dataset/group with the given uniqueId. "
                   "Without widgetType the override is entity-level (every widget of that "
                   "dataset/group); with widgetType it targets only that widget kind (e.g. only "
                   "the FFT of a dataset) and wins over the entity-level entry. Display-only: "
                   "widget captions, freeze headers, painted instrument titles and taskbar "
                   "entries show it, while exports, dashboard.getData and project.* responses "
                   "keep the canonical title. Empty/absent title clears the override."),
    setTitleSchema,
    &setWidgetTitle);

  registry.registerCommand(
    QStringLiteral("project.dashboard.getWidgetTitles"),
    QStringLiteral("Get every display-title override (entity-level rows carry only uniqueId; "
                   "widget-level rows also carry widgetType), each annotated with the canonical "
                   "title it shadows (canonical:null when the target no longer exists)."),
    emptySchema,
    &getWidgetTitles);

  QJsonObject modeProp;
  modeProp.insert(QStringLiteral("type"), QStringLiteral("string"));
  modeProp.insert(
    QStringLiteral("enum"),
    QJsonArray{QStringLiteral("bar"), QStringLiteral("painted"), QStringLiteral("hidden")});
  modeProp.insert(QStringLiteral("description"),
                  QStringLiteral("Freeze-title mode: bar (panel header), painted (title on the "
                                 "instrument face; Bar/Gauge/Meter only), hidden (no title "
                                 "while frozen)"));

  QJsonObject modeProps;
  modeProps.insert(QStringLiteral("widgetType"), typeProp);
  modeProps.insert(Keys::UniqueId, uidProp);
  modeProps.insert(QStringLiteral("mode"), modeProp);

  QJsonObject setModeSchema;
  setModeSchema.insert(QStringLiteral("type"), QStringLiteral("object"));
  setModeSchema.insert(QStringLiteral("properties"), modeProps);
  setModeSchema.insert(
    QStringLiteral("required"),
    QJsonArray{QStringLiteral("widgetType"), QString(Keys::UniqueId), QStringLiteral("mode")});

  registry.registerCommand(
    QStringLiteral("project.dashboard.setWidgetFreezeTitle"),
    QStringLiteral("Set the freeze-mode title presentation for one widget (widgetType + "
                   "uniqueId): bar shows the panel header, painted shows the title on the "
                   "instrument face (Bar/Gauge/Meter only, their default), hidden shows no "
                   "title while the dashboard is frozen. Every other widget type defaults to "
                   "bar; writing a widget's default clears its stored entry."),
    setModeSchema,
    &setWidgetFreezeTitle);
}

static QString canonicalTitleForUniqueId(int uniqueId, bool& found)
{
  static auto& projectModel = DataModel::ProjectModel::instance();

  found = false;
  for (const auto& group : projectModel.groups()) {
    if (group.uniqueId == uniqueId) {
      found = true;
      return group.title;
    }

    for (const auto& dataset : group.datasets) {
      if (dataset.uniqueId == uniqueId) {
        found = true;
        return dataset.title;
      }
    }
  }

  return QString();
}

API::CommandResponse API::Handlers::DashboardHandler::setWidgetTitle(const QString& id,
                                                                     const QJsonObject& params)
{
  if (!params.contains(Keys::UniqueId)) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: uniqueId"));
  }

  static auto& appState = AppState::instance();
  if (appState.operationMode() != SerialStudio::ProjectFile) {
    return CommandResponse::makeError(
      id,
      ErrorCode::OperationFailed,
      QStringLiteral("Display-title overrides require ProjectFile mode with a loaded project."));
  }

  const int uniqueId = params.value(Keys::UniqueId).toInt(-1);
  bool found         = false;
  const auto canon   = canonicalTitleForUniqueId(uniqueId, found);
  if (!found) {
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("No dataset or group with uniqueId %1 exists in this project.").arg(uniqueId));
  }

  static auto& projectModel = DataModel::ProjectModel::instance();
  const bool widgetScoped   = params.contains(QStringLiteral("widgetType"));
  const int widgetType      = params.value(QStringLiteral("widgetType")).toInt(-1);
  const auto title          = params.value(QStringLiteral("title")).toString().trimmed();

  QString previous;
  if (widgetScoped) {
    previous = projectModel.widgetDisplayTitle(widgetType, uniqueId);
    projectModel.setWidgetDisplayTitle(widgetType, uniqueId, title);
  } else {
    previous = projectModel.displayTitle(uniqueId);
    projectModel.setDisplayTitle(uniqueId, title);
  }

  QJsonObject result;
  result[Keys::UniqueId]              = uniqueId;
  result[QStringLiteral("title")]     = title;
  result[QStringLiteral("previous")]  = previous;
  result[QStringLiteral("canonical")] = canon;
  result[QStringLiteral("cleared")]   = title.isEmpty();
  result[QStringLiteral("scope")] =
    widgetScoped ? QStringLiteral("widget") : QStringLiteral("entity");
  if (widgetScoped)
    result[QStringLiteral("widgetType")] = widgetType;

  result[QStringLiteral("_summary")] =
    title.isEmpty()
      ? QStringLiteral("Cleared the %1-level display title for uniqueId %2.")
          .arg(widgetScoped ? QStringLiteral("widget") : QStringLiteral("entity"))
          .arg(uniqueId)
      : QStringLiteral("%1 for uniqueId %2 now displays \"%3\" (canonical title \"%4\" is "
                       "unchanged in exports and API data).")
          .arg(widgetScoped ? QStringLiteral("The selected widget kind")
                            : QStringLiteral("Every widget"))
          .arg(uniqueId)
          .arg(title)
          .arg(canon);

  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::DashboardHandler::getWidgetTitles(const QString& id,
                                                                      const QJsonObject& params)
{
  Q_UNUSED(params)

  static auto& projectModel = DataModel::ProjectModel::instance();
  const auto overrides      = projectModel.displayTitles();

  QJsonArray titles;
  for (auto it = overrides.constBegin(); it != overrides.constEnd(); ++it) {
    const auto key     = it.key();
    const int sep      = key.indexOf(QLatin1Char(':'));
    const bool scoped  = sep > 0;
    const int uniqueId = scoped ? key.mid(sep + 1).toInt() : key.toInt();
    bool found         = false;
    const auto canon   = canonicalTitleForUniqueId(uniqueId, found);

    QJsonObject row;
    row[Keys::UniqueId]              = uniqueId;
    row[QStringLiteral("title")]     = it.value().toString();
    row[QStringLiteral("scope")]     = scoped ? QStringLiteral("widget") : QStringLiteral("entity");
    row[QStringLiteral("canonical")] = found ? QJsonValue(canon) : QJsonValue();
    if (scoped)
      row[QStringLiteral("widgetType")] = key.left(sep).toInt();

    titles.append(row);
  }

  QJsonObject result;
  result[QStringLiteral("titles")] = titles;
  result[QStringLiteral("count")]  = titles.size();

  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::DashboardHandler::setWidgetFreezeTitle(
  const QString& id, const QJsonObject& params)
{
  const QStringList required = {
    QStringLiteral("widgetType"), QString(Keys::UniqueId), QStringLiteral("mode")};
  for (const auto& key : required) {
    if (!params.contains(key)) {
      return CommandResponse::makeError(
        id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: %1").arg(key));
    }
  }

  static auto& appState = AppState::instance();
  if (appState.operationMode() != SerialStudio::ProjectFile) {
    return CommandResponse::makeError(
      id,
      ErrorCode::OperationFailed,
      QStringLiteral("Freeze-title modes require ProjectFile mode with a loaded project."));
  }

  const int widgetType = params.value(QStringLiteral("widgetType")).toInt(-1);
  const bool paints    = SerialStudio::dashboardWidgetPaintsTitle(
    static_cast<SerialStudio::DashboardWidget>(widgetType));

  const auto mode = params.value(QStringLiteral("mode")).toString();
  if (mode != QLatin1String("bar") && mode != QLatin1String("painted")
      && mode != QLatin1String("hidden")) {
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("Invalid mode \"%1\": must be bar, painted or hidden.").arg(mode));
  }

  if (mode == QLatin1String("painted") && !paints) {
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("Mode \"painted\" is only valid for Bar, Gauge and Meter widgets."));
  }

  const int uniqueId = params.value(Keys::UniqueId).toInt(-1);
  bool found         = false;
  (void)canonicalTitleForUniqueId(uniqueId, found);
  if (!found) {
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("No dataset or group with uniqueId %1 exists in this project.").arg(uniqueId));
  }

  static auto& projectModel = DataModel::ProjectModel::instance();
  const auto previous       = projectModel.freezeTitleMode(widgetType, uniqueId);
  projectModel.setFreezeTitleMode(widgetType, uniqueId, mode);

  QJsonObject result;
  result[QStringLiteral("widgetType")] = widgetType;
  result[Keys::UniqueId]               = uniqueId;
  result[QStringLiteral("mode")]       = mode;
  result[QStringLiteral("previous")]   = previous;

  return CommandResponse::makeSuccess(id, result);
}

QString DataModel::ProjectModel::displayTitle(int uniqueId) const
{
  const auto titles = m_widgetDisplay.value(Keys::Titles).toObject();
  return titles.value(QString::number(uniqueId)).toString();
}

QString DataModel::ProjectModel::widgetDisplayTitle(int widgetType, int uniqueId) const
{
  const auto titles = m_widgetDisplay.value(Keys::Titles).toObject();
  return titles.value(widget_scope_key(widgetType, uniqueId)).toString();
}

QString DataModel::ProjectModel::freezeTitleMode(int widgetType, int uniqueId) const
{
  const auto modes = m_widgetDisplay.value(Keys::FreezeTitle).toObject();
  const auto mode  = modes.value(widget_scope_key(widgetType, uniqueId)).toString();
  if (!mode.isEmpty())
    return mode;

  const auto widget = static_cast<SerialStudio::DashboardWidget>(widgetType);
  return SerialStudio::dashboardWidgetPaintsTitle(widget) ? QStringLiteral("painted")
                                                          : QStringLiteral("bar");
}

void DataModel::ProjectModel::stageDisplayTitle(const QString& key, const QString& title)
{
  static auto& appState = AppState::instance();
  if (appState.operationMode() != SerialStudio::ProjectFile)
    return;

  auto titles    = m_widgetDisplay.value(Keys::Titles).toObject();
  const auto old = titles.value(key).toString();
  if (old == title)
    return;

  if (title.isEmpty())
    titles.remove(key);
  else
    titles.insert(key, title);

  if (titles.isEmpty())
    m_widgetDisplay.remove(Keys::Titles);
  else
    m_widgetDisplay.insert(Keys::Titles, titles);

  setModified(true);
  Q_EMIT widgetDisplayChanged();
}

void DataModel::ProjectModel::setWidgetDisplayTitle(int widgetType,
                                                    int uniqueId,
                                                    const QString& title)
{
  stageDisplayTitle(widget_scope_key(widgetType, uniqueId), title);
}

void DataModel::ProjectModel::promptRenameWidget(int widgetType,
                                                 int uniqueId,
                                                 const QString& currentTitle)
{
  if (widgetType < 0 || uniqueId < 0)
    return;

  bool ok            = false;
  const QString name = QInputDialog::getText(nullptr,
                                             tr("Rename Widget"),
                                             tr("Display title (empty restores the original):"),
                                             QLineEdit::Normal,
                                             currentTitle,
                                             &ok);

  if (!ok || name.trimmed() == currentTitle)
    return;

  setWidgetDisplayTitle(widgetType, uniqueId, name.trimmed());
}

void DataModel::ProjectModel::setFreezeTitleMode(int widgetType, int uniqueId, const QString& mode)
{
  static auto& appState = AppState::instance();
  if (appState.operationMode() != SerialStudio::ProjectFile)
    return;

  const auto widget = static_cast<SerialStudio::DashboardWidget>(widgetType);
  const bool paints = SerialStudio::dashboardWidgetPaintsTitle(widget);
  if (mode != QLatin1String("bar") && mode != QLatin1String("hidden")
      && !(mode == QLatin1String("painted") && paints))
    return;

  const auto fallback = paints ? QLatin1String("painted") : QLatin1String("bar");
  const auto key      = widget_scope_key(widgetType, uniqueId);
  auto modes          = m_widgetDisplay.value(Keys::FreezeTitle).toObject();
  const auto old      = modes.value(key).toString();
  const auto now      = (mode == fallback) ? QString() : mode;
  if (old == now)
    return;

  if (now.isEmpty())
    modes.remove(key);
  else
    modes.insert(key, now);

  if (modes.isEmpty())
    m_widgetDisplay.remove(Keys::FreezeTitle);
  else
    m_widgetDisplay.insert(Keys::FreezeTitle, modes);

  setModified(true);
  Q_EMIT widgetDisplayChanged();
}

void UI::Dashboard::restorePersistedSettings()
{
  m_showAlignmentGuides    = m_settings.value("Dashboard/ShowAlignmentGuides", false).toBool();
  applyDisplayTitles();
/**
 * @brief Applies display-title overrides to the widget copies in m_widgetGroups and
 *        m_widgetDatasets: widget-level entries ("type:uid") beat entity-level ones ("uid"),
 *        canonical titles resolve from m_lastFrame so a removed override restores the
 *        original text; m_lastFrame stays canonical (exports and dashboard.getData serialize it).
 */
void UI::Dashboard::applyDisplayTitles()
{
  static auto& appState     = AppState::instance();
  static auto& projectModel = DataModel::ProjectModel::instance();
  if (appState.operationMode() != SerialStudio::ProjectFile)
    return;

  Q_ASSERT(!m_lastFrame.groups.empty());
  const auto overrides = projectModel.displayTitles();

  QHash<int, QString> canonical;
  for (const auto& group : m_lastFrame.groups) {
    canonical.insert(group.uniqueId, group.title);
    for (const auto& dataset : group.datasets)
      canonical.insert(dataset.uniqueId, dataset.title);
  }

  const auto widgetOverride = [&](int type, int uniqueId) {
    return overrides.value(QString::number(type) + QLatin1Char(':') + QString::number(uniqueId))
      .toString();
  };

  const auto entityResolve = [&](int uniqueId, const QString& current) {
    const auto over = overrides.value(QString::number(uniqueId)).toString();
    if (!over.isEmpty())
      return over;

    return canonical.value(uniqueId, current);
  };

  const auto resolve = [&](int type, int uniqueId, const QString& current) {
    const auto scoped = widgetOverride(type, uniqueId);
    return scoped.isEmpty() ? entityResolve(uniqueId, current) : scoped;
  };

  for (auto i = m_widgetGroups.begin(); i != m_widgetGroups.end(); ++i) {
    const int type = static_cast<int>(i.key());
    for (auto& group : i.value()) {
      if (group.widget != QLatin1String("led-panel")) {
        group.title = resolve(type, group.uniqueId, group.title);
        continue;
      }

      const auto scoped = widgetOverride(type, group.uniqueId);
      group.title       = scoped.isEmpty()
                          ? tr("LED Panel (%1)").arg(entityResolve(group.uniqueId, group.title))
                          : scoped;
    }
  }

  for (auto i = m_widgetDatasets.begin(); i != m_widgetDatasets.end(); ++i) {
    const int type = static_cast<int>(i.key());
    for (auto& dataset : i.value())
      dataset.title = resolve(type, dataset.uniqueId, dataset.title);
  }
}

/**
 * @brief Re-applies display titles after an override edit without rebuilding the dashboard:
 *        patches the widget copies in place, pushes the new titles into the WidgetRegistry
 *        and notifies QML. Never emits widgetCountChanged (that would trigger a full
 *        delegate rebuild mid-stream).
 */
void UI::Dashboard::refreshDisplayTitles()
{
  if (m_widgetCount == 0 || m_lastFrame.groups.empty() || !m_layoutValid)
    return;

  applyDisplayTitles();

  static auto& registry = WidgetRegistry::instance();
  for (auto i = m_widgetGroups.constBegin(); i != m_widgetGroups.constEnd(); ++i) {
    const auto key = i.key();
    for (int j = 0; j < i.value().size(); ++j)
      registry.updateWidget(registry.widgetIdByTypeAndIndex(key, j), i.value().at(j).title);
  }

  for (auto i = m_widgetDatasets.constBegin(); i != m_widgetDatasets.constEnd(); ++i) {
    const auto key = i.key();
    for (int j = 0; j < i.value().size(); ++j)
      registry.updateWidget(registry.widgetIdByTypeAndIndex(key, j), i.value().at(j).title);
  }

  Q_EMIT displayTitlesChanged();
}

void UI::Dashboard::applyDisplayTitles()
{
