    }
  }

  for (auto i = m_widgetDatasets.begin(); i != m_widgetDatasets.end(); ++i) {
    const int type = static_cast<int>(i.key());
    for (auto& dataset : i.value())
      dataset.title = resolve(type, dataset.uniqueId, dataset.title);
  }
}

void UI::Dashboard::refreshDisplayTitles()
{
  if (m_widgetCount == 0 || m_lastFrame.groups.empty() || !m_layoutValid)
    return;

  applyDisplayTitles();

  static auto& registry = WidgetRegistry::instance();
  for (auto i = m_widgetGroups.constBegin(); i != m_widgetGroups.constEnd(); ++i) {
    const auto key = i.key();
    for (int j = 0; j < i.value().size(); ++j)
      registry.updateWidget(registry.widgetIdByTypeAndIndex(key, j), i.value().at(j).title);
  }

  for (auto i = m_widgetDatasets.constBegin(); i != m_widgetDatasets.constEnd(); ++i) {
    const auto key = i.key();
    for (int j = 0; j < i.value().size(); ++j)
      registry.updateWidget(registry.widgetIdByTypeAndIndex(key, j), i.value().at(j).title);
  }

  Q_EMIT displayTitlesChanged();
}

int UI::DashboardWidget::widgetUniqueId() const
{
  if (!VALIDATE_WIDGET(m_widgetType, m_relativeIndex))
    return -1;

  if (SerialStudio::isGroupWidget(m_widgetType))
    return GET_GROUP(m_widgetType, m_relativeIndex).uniqueId;

  if (SerialStudio::isDatasetWidget(m_widgetType))
    return GET_DATASET(m_widgetType, m_relativeIndex).uniqueId;

  return -1;
}

void UI::Taskbar::onWidgetUpdated(UI::WidgetID id, const UI::WidgetInfo& info)
{
  auto* item = findItemByWidgetId(id);
  if (!item)
    return;

  if (item->data(TaskbarModel::WidgetNameRole).toString() != info.title)
    item->setData(info.title, TaskbarModel::WidgetNameRole);
}

void UI::WindowManager::focusWindowUnderCursor(const QPointF& pos)
{
  if (!m_frozen || !m_taskbar)
    return;

  auto* target = topmostWindowAt(pos);
  if (target && m_taskbar->activeWindow() != target)
    m_taskbar->setActiveWindow(target);
}

static QJsonObject withDefaultListLimit(const QString& name, const QJsonObject& args)
{
  static const QHash<QString, int> kDefaultLimits = {
    {             QStringLiteral("project.dataset.list"),  4},
    {               QStringLiteral("project.group.list"),  5},
    {QStringLiteral("project.dataset.getExecutionOrder"), 20},
  };

  const int defaultLimit = kDefaultLimits.value(name, 0);
  if (defaultLimit == 0 || args.contains(QStringLiteral("limit")))
    return args;

  QJsonObject bounded              = args;
  bounded[QStringLiteral("limit")] = defaultLimit;
  return bounded;
}

static QString groupsListSummary(const std::vector<DataModel::Group>& groups,
                                 const API::Handlers::ListWindow& window,
                                 int total)
{
  if (groups.empty())
    return QStringLiteral("No groups configured.");

  if (window.count == 0)
    return QStringLiteral("%1 groups; the requested offset is past the end.")
      .arg(QString::number(total));

  QStringList names;
  for (int g = window.start; g < window.start + window.count; ++g) {
    const auto& grp      = groups[static_cast<size_t>(g)];
    const auto widgetStr = grp.widget.simplified();
    names.append(
      QStringLiteral("\"%1\"%2")
        .arg(grp.title, widgetStr.isEmpty() ? QString() : QStringLiteral(" (%1)").arg(widgetStr)));
  }

  const QString shown =
    window.count < total
      ? QStringLiteral(" (showing %1-%2)")
          .arg(QString::number(window.start), QString::number(window.start + window.count - 1))
      : QString();
  return QStringLiteral("%1 group%2%3: %4.")
    .arg(QString::number(total),
         total == 1 ? QString() : QStringLiteral("s"),
         shown,
         names.join(QStringLiteral(", ")));
}

[[nodiscard]] static bool parseTypeFilter(const QJsonValue& value, QSet<QString>& out)
{
  static const QSet<QString> kValidTypes = {QStringLiteral("dataset"),
                                            QStringLiteral("group"),
                                            QStringLiteral("action"),
                                            QStringLiteral("source"),
                                            QStringLiteral("workspace"),
                                            QStringLiteral("table")};

  QStringList requested;
  if (value.isString())
    requested.append(value.toString());
  else if (value.isArray())
    for (const auto& v : value.toArray())
      requested.append(v.toString());
  else if (!value.isUndefined() && !value.isNull())
    return false;

  for (const auto& type : requested) {
    const auto clean = type.trimmed().toLower();
    if (!kValidTypes.contains(clean))
      return false;

    out.insert(clean);
  }

  return true;
}

static void appendSourceRows(const SearchFilters& filters, QJsonArray& out)
{
  static auto& projectModel = DataModel::ProjectModel::instance();
  for (const auto& source : projectModel.sources()) {
    if (filters.hasSourceId && source.sourceId != filters.sourceId)
      continue;

    if (!matchesQuery(source.title, filters.query))
      continue;

    QJsonObject row;
    row[QStringLiteral("type")] = QStringLiteral("source");
    row[Keys::SourceId]         = source.sourceId;
    row[Keys::Title]            = source.title;
    out.append(row);
  }
}

static void appendGroupRows(const SearchFilters& filters, QJsonArray& out)
{
  static auto& projectModel = DataModel::ProjectModel::instance();
  for (const auto& group : projectModel.groups()) {
    if (filters.hasSourceId && group.sourceId != filters.sourceId)
      continue;

    if (!matchesQuery(group.title, filters.query))
      continue;

    QJsonObject row;
    row[QStringLiteral("type")]         = QStringLiteral("group");
    row[Keys::GroupId]                  = group.groupId;
    row[Keys::UniqueId]                 = group.uniqueId;
    row[Keys::Title]                    = group.title;
    row[QStringLiteral("datasetCount")] = static_cast<int>(group.datasets.size());
    out.append(row);
  }
}

static void appendDatasetRow(const DataModel::Group& group,
                             const DataModel::Dataset& dataset,
                             const SearchFilters& filters,
                             QJsonArray& out)
{
  const bool titleHit = matchesQuery(dataset.title, filters.query);
  const bool aliasHit = !titleHit && matchesQuery(dataset.alias, filters.query);
  const bool unitsHit = !titleHit && !aliasHit && matchesQuery(dataset.units, filters.query);
  if (!titleHit && !aliasHit && !unitsHit)
    return;

  QJsonObject row;
  row[QStringLiteral("type")]       = QStringLiteral("dataset");
  row[Keys::UniqueId]               = dataset.uniqueId;
  row[Keys::Title]                  = dataset.title;
  row[QStringLiteral("path")]       = QStringLiteral("%1/%2").arg(group.title, dataset.title);
  row[Keys::GroupId]                = group.groupId;
  row[QStringLiteral("groupTitle")] = group.title;
  row[QStringLiteral("index")]      = dataset.index;
  if (!dataset.units.isEmpty())
    row[QStringLiteral("units")] = dataset.units;

  if (aliasHit)
    row[QStringLiteral("matchedField")] = QStringLiteral("alias");
  else if (unitsHit)
    row[QStringLiteral("matchedField")] = QStringLiteral("units");

  out.append(row);
}

static void appendDatasetRows(const SearchFilters& filters, QJsonArray& out)
{
  static auto& projectModel = DataModel::ProjectModel::instance();
  for (const auto& group : projectModel.groups()) {
    if (filters.hasGroupId && group.groupId != filters.groupId)
      continue;

    for (const auto& dataset : group.datasets) {
      if (filters.hasSourceId && dataset.sourceId != filters.sourceId)
        continue;

      appendDatasetRow(group, dataset, filters, out);
    }
  }
}

static void appendActionRows(const SearchFilters& filters, QJsonArray& out)
{
  static auto& projectModel = DataModel::ProjectModel::instance();
  for (const auto& action : projectModel.actions()) {
    if (filters.hasSourceId && action.sourceId != filters.sourceId)
      continue;

    if (!matchesQuery(action.title, filters.query))
      continue;

    QJsonObject row;
    row[QStringLiteral("type")] = QStringLiteral("action");
    row[Keys::ActionId]         = action.actionId;
    row[Keys::Title]            = action.title;
    out.append(row);
  }
}

static void appendWorkspaceRows(const SearchFilters& filters, QJsonArray& out)
{
  static auto& projectModel = DataModel::ProjectModel::instance();
  for (const auto& workspace : projectModel.activeWorkspaces()) {
    if (!matchesQuery(workspace.title, filters.query))
      continue;

    QJsonObject row;
    row[QStringLiteral("type")]        = QStringLiteral("workspace");
    row[QStringLiteral("workspaceId")] = workspace.workspaceId;
    row[Keys::Title]                   = workspace.title;
    out.append(row);
  }
}

static void appendTableRows(const SearchFilters& filters, QJsonArray& out)
{
  static auto& projectModel = DataModel::ProjectModel::instance();
  for (const auto& table : projectModel.tables()) {
    if (!matchesQuery(table.name, filters.query))
      continue;

    QJsonObject row;
    row[QStringLiteral("type")] = QStringLiteral("table");
    row[QStringLiteral("name")] = table.name;
    row[Keys::Title]            = table.name;
    out.append(row);
  }
}

[[nodiscard]] static QJsonArray collectSearchRows(const SearchFilters& filters)
{
  QJsonArray rows;
  if (filters.wantsType(QStringLiteral("source")))
    appendSourceRows(filters, rows);

  if (filters.wantsType(QStringLiteral("group")))
    appendGroupRows(filters, rows);

  if (filters.wantsType(QStringLiteral("dataset")))
    appendDatasetRows(filters, rows);

  if (filters.wantsType(QStringLiteral("action")))
    appendActionRows(filters, rows);

  if (filters.wantsType(QStringLiteral("workspace")))
    appendWorkspaceRows(filters, rows);

  if (filters.wantsType(QStringLiteral("table")))
    appendTableRows(filters, rows);

  return rows;
}

API::CommandResponse API::Handlers::ProjectHandler::projectSearch(const QString& id,
                                                                  const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("query")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: query"));

  SearchFilters filters;
  filters.query = params.value(QStringLiteral("query")).toString().trimmed();
  if (filters.query.isEmpty())
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("query cannot be empty. To enumerate everything, use project.group.list / "
                     "project.dataset.list (with offset/limit) or project.snapshot instead."));

  if (!parseTypeFilter(params.value(QStringLiteral("type")), filters.types))
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("type must be one (or an array) of: dataset, group, action, source, "
                     "workspace, table."));

  filters.hasGroupId  = params.contains(Keys::GroupId);
  filters.hasSourceId = params.contains(Keys::SourceId);
  if ((filters.hasGroupId && !params.value(Keys::GroupId).isDouble())
      || (filters.hasSourceId && !params.value(Keys::SourceId).isDouble()))
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("groupId / sourceId filters must be JSON numbers, not strings -- a "
                     "string-typed filter would silently match the wrong group/source."));

  filters.groupId  = params.value(Keys::GroupId).toInt();
  filters.sourceId = params.value(Keys::SourceId).toInt();

  const QJsonArray matches = collectSearchRows(filters);
  const int matchCount     = matches.size();

  const int wantedLimit = params.value(QStringLiteral("limit")).toInt(kSearchDefaultLimit);
  const int limit = qBound(1, wantedLimit > 0 ? wantedLimit : kSearchDefaultLimit, kSearchMaxLimit);
  const auto window =
    applyWindow(matchCount, params.value(QStringLiteral("offset")).toInt(0), limit);

  QJsonArray rows;
  for (int i = window.start; i < window.start + window.count; ++i)
    rows.append(matches.at(i));

  QString summary;
  if (matchCount > 0 && window.count == 0)
    summary = QStringLiteral("%1 matches for \"%2\"; the requested offset is past the end.")
                .arg(QString::number(matchCount), filters.query);
  else
    summary =
      QStringLiteral("%1 match%2 for \"%3\"%4.")
        .arg(QString::number(matchCount),
             matchCount == 1 ? QString() : QStringLiteral("es"),
             filters.query,
             window.count < matchCount ? QStringLiteral(" (showing %1-%2)")
                                           .arg(QString::number(window.start),
                                                QString::number(window.start + window.count - 1))
                                       : QString());

  QJsonObject result;
  result[QStringLiteral("_summary")]   = summary;
  result[QStringLiteral("query")]      = filters.query;
  result[QStringLiteral("matchCount")] = matchCount;
  result[QStringLiteral("rows")]       = rows;
  attachWindowInfo(result, window, matchCount);
  attachProjectEpoch(result);
  if (matchCount > 0)
    result[QStringLiteral("_hint")] =
      QStringLiteral("Drill into a match: project.dataset.getByUniqueId{uniqueId} or "
                     "project.dataset.getByPath{path} for datasets, project.group.get{groupId "
                     "or uniqueId} for groups.");

  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::groupGet(const QString& id,
                                                             const QJsonObject& params)
{
  const bool byGroupId  = params.contains(Keys::GroupId);
  const bool byUniqueId = params.contains(Keys::UniqueId);
  if (!byGroupId && !byUniqueId)
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing selector. ") + kGroupIdSpacesHint);

  if (byGroupId && byUniqueId)
    return CommandResponse::makeError(id,
                                      ErrorCode::InvalidParam,
                                      QStringLiteral("Pass either groupId or uniqueId, not both. ")
                                        + kGroupIdSpacesHint);

  const auto selectorValue = params.value(byGroupId ? Keys::GroupId : Keys::UniqueId);
  if (!selectorValue.isDouble())
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("The selector must be a JSON number, not a string -- a string-typed id "
                     "would silently resolve to group 0. ")
        + kGroupIdSpacesHint);

  static auto& projectModel     = DataModel::ProjectModel::instance();
  const auto& groups            = projectModel.groups();
  const int selector            = selectorValue.toInt();
  const DataModel::Group* match = nullptr;
  for (const auto& group : groups) {
    if ((byGroupId ? group.groupId : group.uniqueId) == selector) {
      match = &group;
      break;
    }
  }

  if (match == nullptr)
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("No group matched %1=%2. ")
          .arg(QString(byGroupId ? Keys::GroupId : Keys::UniqueId), QString::number(selector))
        + kGroupIdSpacesHint);

  const int total       = static_cast<int>(match->datasets.size());
  const int wantedLimit = params.value(QStringLiteral("limit")).toInt(kGroupGetDefaultLimit);
  const int limit =
    qBound(1, wantedLimit > 0 ? wantedLimit : kGroupGetDefaultLimit, kGroupGetMaxLimit);
  const auto window = applyWindow(total, params.value(QStringLiteral("offset")).toInt(0), limit);

  QJsonArray summary;
  for (int i = window.start; i < window.start + window.count; ++i) {
    const auto& dataset = match->datasets[static_cast<size_t>(i)];
    QJsonObject row;
    row[Keys::DatasetId]         = dataset.datasetId;
    row[Keys::UniqueId]          = dataset.uniqueId;
    row[QStringLiteral("index")] = dataset.index;
    row[Keys::Title]             = dataset.title;
    if (!dataset.units.isEmpty())
      row[QStringLiteral("units")] = dataset.units;

    summary.append(row);
  }

  QJsonObject result;
  result[Keys::GroupId]                    = match->groupId;
  result[Keys::UniqueId]                   = match->uniqueId;
  result[Keys::Title]                      = match->title;
  result[QStringLiteral("widget")]         = match->widget;
  result[Keys::SourceId]                   = match->sourceId;
  result[QStringLiteral("datasetCount")]   = total;
  result[QStringLiteral("datasetSummary")] = summary;
  result[QStringLiteral("_summary")] =
    QStringLiteral("Group \"%1\" (groupId %2, uniqueId %3): %4 dataset%5.")
      .arg(match->title,
           QString::number(match->groupId),
           QString::number(match->uniqueId),
           QString::number(total),
           total == 1 ? QString() : QStringLiteral("s"));
  attachWindowInfo(result, window, total);
  attachProjectEpoch(result);
  return CommandResponse::makeSuccess(id, result);
}

void UI::Dashboard::setShowAlignmentGuides(const bool enabled)
{
  if (m_showAlignmentGuides != enabled) {
    m_showAlignmentGuides = enabled;
    if (m_persistSettings)
      m_settings.setValue("Dashboard/ShowAlignmentGuides", m_showAlignmentGuides);

    Q_EMIT showAlignmentGuidesChanged();
  }
}

QIcon Misc::Utilities::coloredSvgIcon(const QString& svgPath, const QColor& color)
{
  QSvgRenderer renderer(svgPath);
  if (!renderer.isValid())
    return QIcon(svgPath);

  const qreal dpr         = qApp->devicePixelRatio();
  const QRectF logical    = QRectF(0, 0, 32, 32);
  const QSize pixelSize   = (logical.size() * dpr).toSize();

  QPixmap pixmap(pixelSize);
  pixmap.setDevicePixelRatio(dpr);
  pixmap.fill(Qt::transparent);

  QPainter painter(&pixmap);
  painter.setRenderHint(QPainter::Antialiasing);
  painter.setRenderHint(QPainter::SmoothPixmapTransform);
  renderer.render(&painter, logical);
  painter.setCompositionMode(QPainter::CompositionMode_SourceIn);
  painter.fillRect(logical, color);
  painter.end();

  return QIcon(pixmap);
}

static QJsonObject makeMultiTypeProperty(const QString& typeA,
                                         const QString& typeB,
                                         const QString& description)
{
  QJsonObject prop;
  prop[QStringLiteral("type")]        = QJsonArray{typeA, typeB};
  prop[QStringLiteral("description")] = description;
  return prop;
}

static void insertTailFrameFilterUid(const QJsonValue& selector, QSet<int>& out)
{
  if (!selector.isString()) {
    out.insert(selector.toInt());
    return;
  }

  QString error;
  const auto match = API::Handlers::resolveDatasetSelector(selector, error);
  if (match.dataset)
    out.insert(match.dataset->uniqueId);
}

static bool aliasInUseByOtherDataset(const QString& alias, int selfUniqueId)
{
  static auto& project = DataModel::ProjectModel::instance();
  for (const auto& group : project.groups()) {
    for (const auto& other : group.datasets)
      if (other.uniqueId != selfUniqueId && other.alias == alias)
        return true;
  }

  return false;
}

const DataModel::RegisterValue* DataModel::DataTableStore::getDatasetRawByAlias(
  const QString& alias) const
{
  Q_ASSERT(m_initialized);

  const auto it = m_aliasIndex.constFind(alias);
  if (it == m_aliasIndex.constEnd()) [[unlikely]] {
    noteMissingAlias(alias, "raw");
    return nullptr;
  }

  captureRead(it->first);
  return &m_storage[static_cast<size_t>(it->first)];
}

const DataModel::RegisterValue* DataModel::DataTableStore::getDatasetFinalByAlias(
  const QString& alias) const
{
  Q_ASSERT(m_initialized);

  const auto it = m_aliasIndex.constFind(alias);
  if (it == m_aliasIndex.constEnd()) [[unlikely]] {
    noteMissingAlias(alias, "final");
    return nullptr;
  }

  captureRead(it->second);
  return &m_storage[static_cast<size_t>(it->second)];
}

std::pair<int, int> DataModel::DataTableStore::resolveAliasSlotsInterned(const char* alias,
                                                                         const char* kind) const
{
  Q_ASSERT(m_initialized);

  for (const auto& entry : m_internedAliasCache)
    if (entry.aliasPtr == alias)
      return {entry.rawSlot, entry.finSlot};

  const auto it     = m_aliasIndex.constFind(QString::fromUtf8(alias));
  const bool found  = (it != m_aliasIndex.constEnd());
  const int rawSlot = found ? it->first : -1;
  const int finSlot = found ? it->second : -1;

  m_internedAliasCache[m_internedAliasCacheNext] = {alias, rawSlot, finSlot};
  m_internedAliasCacheNext = (m_internedAliasCacheNext + 1) % kInternedAliasCacheSize;

  if (!found) [[unlikely]]
    noteMissingAlias(QString::fromUtf8(alias), kind);

  return {rawSlot, finSlot};
}

const DataModel::RegisterValue* DataModel::DataTableStore::getDatasetRawByAliasInterned(
  const char* alias) const
{
  const auto slotPair = resolveAliasSlotsInterned(alias, "raw");
  if (slotPair.first < 0) [[unlikely]]
    return nullptr;

  captureRead(slotPair.first);
  return &m_storage[static_cast<size_t>(slotPair.first)];
}

const DataModel::RegisterValue* DataModel::DataTableStore::getDatasetFinalByAliasInterned(
  const char* alias) const
{
  const auto slotPair = resolveAliasSlotsInterned(alias, "final");
  if (slotPair.second < 0) [[unlikely]]
    return nullptr;

  captureRead(slotPair.second);
  return &m_storage[static_cast<size_t>(slotPair.second)];
}

void DataModel::DataTableStore::registerDatasetAlias(const QString& alias, int uniqueId)
{
  const auto ds = m_datasetIndex.constFind(uniqueId);
  if (ds == m_datasetIndex.constEnd()) [[unlikely]]
    return;

  if (m_aliasIndex.constFind(alias) != m_aliasIndex.constEnd()) [[unlikely]] {
    qWarning().noquote() << "[DataTableStore] Duplicate dataset alias" << alias
                         << "-- alias lookups resolve to the first dataset that declared it";
    return;
  }

  m_aliasIndex.insert(alias, ds.value());

  const auto rawKey = qMakePair(kSystemTable, kRawPrefix + alias);
  const auto finKey = qMakePair(kSystemTable, kFinalPrefix + alias);
  if (m_index.constFind(rawKey) == m_index.constEnd())
    m_index.insert(rawKey, ds->first);

  if (m_index.constFind(finKey) == m_index.constEnd())
    m_index.insert(finKey, ds->second);
}

void DataModel::DataTableStore::noteMissingAlias(const QString& alias, const char* kind) const
{
  if (m_warnedMissingAliases.contains(alias))
    return;

  m_warnedMissingAliases.insert(alias);
  qWarning().noquote() << "[DataTableStore] datasetGet" << kind << "called with unknown alias"
                       << alias << "-- returns nil/empty";
}

void DataModel::ProjectEditor::addDatasetAliasRow(CustomModel* model,
                                                  const DataModel::Dataset& dataset)
{
  auto* aliasItem = new QStandardItem();
  aliasItem->setEditable(true);
  aliasItem->setData(true, Active);
  aliasItem->setData(TextField, WidgetType);
  aliasItem->setData(dataset.alias, EditableValue);
  aliasItem->setData(kDatasetView_Alias, ParameterType);
  aliasItem->setData(tr("Stable name"), PlaceholderValue);
  aliasItem->setData(tr("Script Alias"), ParameterName);
  aliasItem->setData(tr("Stable name for getDataset-style script/API lookups; must be unique "
                        "(optional)"),
                     ParameterDescription);
  model->appendRow(aliasItem);
}

static QString uniqueAliasCandidate(const QString& base, const QSet<QString>& used)
{
  if (!used.contains(base))
    return base;

  const int maxTries = static_cast<int>(used.size()) + 2;
  for (int suffix = 2; suffix < maxTries + 2; ++suffix) {
    const QString candidate = QStringLiteral("%1-%2").arg(base, QString::number(suffix));
    if (!used.contains(candidate))
      return candidate;
  }

  return base;
}

int DataModel::ProjectModel::seedDatasetAliases()
{
  QSet<QString> used;
  for (const auto& group : m_groups)
    for (const auto& ds : group.datasets)
      if (!ds.alias.isEmpty())
        used.insert(ds.alias);

  int seeded = 0;
  for (auto& group : m_groups) {
    for (auto& ds : group.datasets) {
      const QString base = ds.title.simplified();
      if (!ds.alias.isEmpty() || base.isEmpty())
        continue;

      ds.alias = uniqueAliasCandidate(base, used);
      used.insert(ds.alias);
      ++seeded;
    }
  }

  if (seeded > 0) {
    m_runtimeDirty = true;
    setModified(true);
    Q_EMIT groupsChanged();
    scheduleAutoSave();
  }

  return seeded;
}

int Misc::HighDpiScaling::readPersistedMode()
{
  QSettings settings;
  const int configured = settings.value(modeKey(), Mode::Fractional).toInt();
  if (!isModeAvailable(configured))
    return Mode::Fractional;

  return configured;
}

int Misc::HighDpiScaling::readPersistedPercent()
{
  QSettings settings;
  return clampPercent(settings.value(percentKey(), kDefaultPercent).toInt());
}

void Misc::HighDpiScaling::applyConfiguredPolicy()
{
  const int mode = readPersistedMode();

  qunsetenv("QT_SCALE_FACTOR");
  qunsetenv("QT_ENABLE_HIGHDPI_SCALING");

  if (mode == Mode::Disabled) {
    qputenv("QT_ENABLE_HIGHDPI_SCALING", "0");
    return;
  }

  if (mode == Mode::Custom) {
    constexpr double kPercentToFactor = 1.0 / 100.0;
    const double factor               = readPersistedPercent() * kPercentToFactor;
    qputenv("QT_SCALE_FACTOR", QByteArray::number(factor, 'g', 4));
    return;
  }

  auto policy = Qt::HighDpiScaleFactorRoundingPolicy::Unset;
  switch (mode) {
    case Mode::Fractional:
      policy = Qt::HighDpiScaleFactorRoundingPolicy::PassThrough;
      break;
    case Mode::RoundNearest:
      policy = Qt::HighDpiScaleFactorRoundingPolicy::Round;
      break;
    case Mode::RoundUp:
      policy = Qt::HighDpiScaleFactorRoundingPolicy::Ceil;
      break;
    case Mode::RoundDown:
      policy = Qt::HighDpiScaleFactorRoundingPolicy::Floor;
      break;
    default:
      break;
  }

  QApplication::setHighDpiScaleFactorRoundingPolicy(policy);
}

Misc::HighDpiScaling& Misc::HighDpiScaling::instance()
{
  static HighDpiScaling singleton;
  return singleton;
}

Misc::HighDpiScaling::HighDpiScaling()
  : m_currentMode(Mode::Fractional), m_customPercent(kDefaultPercent)
{
  m_currentMode = m_settings.value(modeKey(), Mode::Fractional).toInt();
  if (!isModeAvailable(m_currentMode))
    m_currentMode = Mode::Fractional;

  m_customPercent = clampPercent(m_settings.value(percentKey(), kDefaultPercent).toInt());
  rebuildAvailableModes();
}

bool Misc::HighDpiScaling::configurable() const noexcept
{
#if defined(Q_OS_MACOS)
  return false;
#else
  return true;
#endif
}

void Misc::HighDpiScaling::setCurrentMode(int mode)
{
  if (m_currentMode == mode)
    return;

  if (!isModeAvailable(mode))
    return;

  m_currentMode = mode;
  m_settings.setValue(modeKey(), mode);
  m_settings.sync();
  Q_EMIT currentModeChanged();
}

void Misc::HighDpiScaling::setCustomPercent(int percent)
{
  const int clamped = clampPercent(percent);
  if (m_customPercent == clamped)
    return;

  m_customPercent = clamped;
  m_settings.setValue(percentKey(), clamped);
  m_settings.sync();
  Q_EMIT customPercentChanged();
}

void Misc::HighDpiScaling::promptRestartAndQuit()
{
  const int choice = Misc::Utilities::showMessageBox(
    tr("Restart Required"),
    tr("The new display scaling setting will take effect after restarting Serial Studio. "
       "Restart now to apply the change?"),
    QMessageBox::Question,
    qAppName(),
    QMessageBox::Yes | QMessageBox::No,
    QMessageBox::Yes);

  if (choice != QMessageBox::Yes)
    return;

  static auto& crashTracker = Misc::CrashTracker::instance();
  crashTracker.markCleanExit();
  Misc::Utilities::rebootApplication();
}

void Misc::HighDpiScaling::rebuildAvailableModes()
{
  m_availableModes.clear();

  auto add = [this](int id, const QString& label) {
    QVariantMap entry;
    entry.insert(QStringLiteral("id"), id);
    entry.insert(QStringLiteral("label"), label);
    m_availableModes.append(entry);
  };

  add(Mode::SystemDefault, QObject::tr("Automatic (System Default)"));
  add(Mode::Fractional, QObject::tr("Fractional"));
  add(Mode::RoundNearest, QObject::tr("Round to Nearest"));
  add(Mode::RoundUp, QObject::tr("Round Up"));
  add(Mode::RoundDown, QObject::tr("Round Down"));
  add(Mode::Disabled, QObject::tr("Disable Scaling"));
  add(Mode::Custom, QObject::tr("Custom…"));
}

static void appendIfViable(const Candidate& candidate,
                           const UI::Snap::SnapInput& input,
                           const bool horiz,
                           QVector<Candidate>& out)
{
  if (qAbs(candidate.delta) > input.threshold)
    return;

  const int extent = horiz ? input.canvas.width() : input.canvas.height();
  const int newLo  = rectLo(input.rect, horiz) + candidate.delta;
  if (!fitsCanvas(newLo, rectSize(input.rect, horiz), extent))
    return;

  out.append(candidate);
}

static void appendAlignCandidates(const UI::Snap::SnapInput& input,
                                  const bool horiz,
                                  QVector<Candidate>& out)
{
  const int lo     = rectLo(input.rect, horiz);
  const int hi     = rectHi(input.rect, horiz);
  const int mid    = rectMid(input.rect, horiz);
  const int extent = horiz ? input.canvas.width() : input.canvas.height();

  for (const auto& sibling : input.siblings) {
    const int sLo  = rectLo(sibling, horiz);
    const int sHi  = rectHi(sibling, horiz);
    const int sMid = rectMid(sibling, horiz);

    appendIfViable({sLo - lo, sLo, kRankEdge}, input, horiz, out);
    appendIfViable({sHi - lo, sHi, kRankEdge}, input, horiz, out);
    appendIfViable({sLo - hi, sLo, kRankEdge}, input, horiz, out);
    appendIfViable({sHi - hi, sHi, kRankEdge}, input, horiz, out);
    appendIfViable({sMid - mid, sMid, kRankCenter}, input, horiz, out);
  }

  appendIfViable({0 - lo, 0, kRankEdge, 0, true}, input, horiz, out);
  appendIfViable({extent - hi, extent, kRankEdge, 0, true}, input, horiz, out);
  appendIfViable({extent / 2 - mid, extent / 2, kRankCenter, 0, true}, input, horiz, out);
}

static void appendSpacingCandidates(const UI::Snap::SnapInput& input,
                                    const bool horiz,
                                    QVector<Candidate>& out)
{
  QVector<QRect> row;
  row.reserve(input.siblings.size());
  for (const auto& sibling : input.siblings)
    if (crossOverlaps(sibling, input.rect, horiz))
      row.append(sibling);

  std::sort(row.begin(), row.end(), [horiz](const QRect& a, const QRect& b) {
    return rectLo(a, horiz) < rectLo(b, horiz);
  });

  const int lo   = rectLo(input.rect, horiz);
  const int size = rectSize(input.rect, horiz);

  for (int i = 0; i + 1 < row.size(); ++i) {
    const QRect& a = row[i];
    const QRect& b = row[i + 1];
    const int gap  = rectLo(b, horiz) - rectHi(a, horiz);
    if (gap <= 0)
      continue;

    Candidate after{rectHi(b, horiz) + gap - lo, 0, kRankSpacing, gap, false, true, a, b};
    appendIfViable(after, input, horiz, out);

    Candidate before{rectLo(a, horiz) - gap - size - lo, 0, kRankSpacing, gap, false, false, a, b};
    appendIfViable(before, input, horiz, out);
  }
}

static std::optional<Candidate> pickCandidate(const QVector<Candidate>& candidates)
{
  std::optional<Candidate> best;
  for (const auto& candidate : candidates) {
    if (!best.has_value()) {
      best = candidate;
      continue;
    }

    const int bestDist = qAbs(best->delta);
    const int dist     = qAbs(candidate.delta);
    if (dist < bestDist || (dist == bestDist && candidate.rank < best->rank))
      best = candidate;
  }

  return best;
}

static UI::Snap::GuideLine buildGuide(const UI::Snap::SnapInput& input,
                                      const QRect& snapped,
                                      const bool horiz,
                                      const Candidate& pick)
{
  int spanLo = rectLo(snapped, !horiz);
  int spanHi = rectHi(snapped, !horiz);

  if (pick.canvasTarget) {
    spanLo = 0;
    spanHi = horiz ? input.canvas.height() : input.canvas.width();
  }

  else {
    for (const auto& sibling : input.siblings) {
      const bool matches = rectLo(sibling, horiz) == pick.line
                        || rectHi(sibling, horiz) == pick.line
                        || rectMid(sibling, horiz) == pick.line;
      if (!matches)
        continue;

      spanLo = qMin(spanLo, rectLo(sibling, !horiz));
      spanHi = qMax(spanHi, rectHi(sibling, !horiz));
    }
  }

  const QRect rect = horiz ? QRect(pick.line, spanLo, 1, spanHi - spanLo)
                           : QRect(spanLo, pick.line, spanHi - spanLo, 1);
  const auto kind =
    pick.rank == kRankCenter ? UI::Snap::GuideKind::Center : UI::Snap::GuideKind::Edge;
  return {rect, kind};
}

static QRect gapRect(const QRect& first,
                     const QRect& second,
                     const QRect& fallback,
                     const bool horiz)
{
  int crossLo = qMax(rectLo(first, !horiz), rectLo(second, !horiz));
  int crossHi = qMin(rectHi(first, !horiz), rectHi(second, !horiz));
  if (crossLo >= crossHi) {
    crossLo = rectLo(fallback, !horiz);
    crossHi = rectHi(fallback, !horiz);
  }

  const int gapLo  = rectHi(first, horiz);
  const int gapLen = rectLo(second, horiz) - gapLo;
  return horiz ? QRect(gapLo, crossLo, gapLen, crossHi - crossLo)
               : QRect(crossLo, gapLo, crossHi - crossLo, gapLen);
}

static void appendSpacingIndicators(const QRect& snapped,
                                    const bool horiz,
                                    const Candidate& pick,
                                    QVector<UI::Snap::SpacingIndicator>& out)
{
  out.append({gapRect(pick.pairA, pick.pairB, snapped, horiz), pick.gap});

  if (pick.afterPair)
    out.append({gapRect(pick.pairB, snapped, snapped, horiz), pick.gap});
  else
    out.append({gapRect(snapped, pick.pairA, snapped, horiz), pick.gap});
}

static void appendIfViableResize(const Candidate& candidate,
                                 const UI::Snap::SnapInput& input,
                                 const bool horiz,
                                 const bool movingLo,
                                 QVector<Candidate>& out)
{
  if (qAbs(candidate.delta) > input.threshold)
    return;

  const int extent  = horiz ? input.canvas.width() : input.canvas.height();
  const int lo      = rectLo(input.rect, horiz);
  const int hi      = rectHi(input.rect, horiz);
  const int newLo   = movingLo ? lo + candidate.delta : lo;
  const int newHi   = movingLo ? hi : hi + candidate.delta;
  const int minSize = qMax(1, input.minSize);
  if (newLo < 0 || newHi > extent || newHi - newLo < minSize)
    return;

  out.append(candidate);
}

static void appendResizeCandidates(const UI::Snap::SnapInput& input,
                                   const bool horiz,
                                   const bool movingLo,
                                   QVector<Candidate>& out)
{
  const int lo     = rectLo(input.rect, horiz);
  const int hi     = rectHi(input.rect, horiz);
  const int edge   = movingLo ? lo : hi;
  const int extent = horiz ? input.canvas.width() : input.canvas.height();

  for (const auto& sibling : input.siblings) {
    const int sLo = rectLo(sibling, horiz);
    const int sHi = rectHi(sibling, horiz);

    appendIfViableResize({sLo - edge, sLo, kRankEdge}, input, horiz, movingLo, out);
    appendIfViableResize({sHi - edge, sHi, kRankEdge}, input, horiz, movingLo, out);

    const int sSize  = rectSize(sibling, horiz);
    const int target = movingLo ? hi - sSize : lo + sSize;
    Candidate size{target - edge, 0, kRankSize, 0, false, false, sibling};
    appendIfViableResize(size, input, horiz, movingLo, out);
  }

  const int canvasEdge = movingLo ? 0 : extent;
  appendIfViableResize(
    {canvasEdge - edge, canvasEdge, kRankEdge, 0, true}, input, horiz, movingLo, out);
}

static void applyResizePick(const std::optional<Candidate>& pick,
                            const UI::Snap::SnapInput& input,
                            const bool horiz,
                            const bool movingLo,
                            QRect& rect)
{
  const int lo = rectLo(rect, horiz);
  const int hi = rectHi(rect, horiz);

  int edge = movingLo ? lo : hi;
  if (pick.has_value())
    edge += pick->delta;
  else if (input.gridEnabled)
    edge = UI::Snap::snapToGrid(edge, input.gridSize);
  else
    return;

  const int newLo   = movingLo ? edge : lo;
  const int newHi   = movingLo ? hi : edge;
  const int minSize = qMax(1, input.minSize);
  if (newHi - newLo < minSize)
    return;

  if (horiz) {
    rect.moveLeft(newLo);
    rect.setWidth(newHi - newLo);
  } else {
    rect.moveTop(newLo);
    rect.setHeight(newHi - newLo);
  }
}

int UI::Snap::snapToGrid(const int value, const int gridSize)
{
  if (gridSize <= 1)
    return value;

  const int offset = value >= 0 ? gridSize / 2 : -(gridSize / 2);
  return ((value + offset) / gridSize) * gridSize;
}

UI::Snap::SnapResult UI::Snap::resolveMoveSnap(const SnapInput& input)
{
  SnapResult result;
  result.rect = input.rect;
  if (input.canvas.isEmpty())
    return result;

  QVector<Candidate> horizontal;
  QVector<Candidate> vertical;
  horizontal.reserve(input.siblings.size() * 5 + 3);
  vertical.reserve(input.siblings.size() * 5 + 3);

  appendAlignCandidates(input, true, horizontal);
  appendAlignCandidates(input, false, vertical);
  appendSpacingCandidates(input, true, horizontal);
  appendSpacingCandidates(input, false, vertical);

  const auto pickX = pickCandidate(horizontal);
  const auto pickY = pickCandidate(vertical);

  if (pickX.has_value())
    result.rect.moveLeft(result.rect.x() + pickX->delta);
  else if (input.gridEnabled)
    result.rect.moveLeft(snapToGrid(result.rect.x(), input.gridSize));

  if (pickY.has_value())
    result.rect.moveTop(result.rect.y() + pickY->delta);
  else if (input.gridEnabled)
    result.rect.moveTop(snapToGrid(result.rect.y(), input.gridSize));

  result.guides.reserve(2);
  result.spacings.reserve(4);

  if (pickX.has_value()) {
    if (pickX->rank == kRankSpacing)
      appendSpacingIndicators(result.rect, true, *pickX, result.spacings);
    else
      result.guides.append(buildGuide(input, result.rect, true, *pickX));
  }

  if (pickY.has_value()) {
    if (pickY->rank == kRankSpacing)
      appendSpacingIndicators(result.rect, false, *pickY, result.spacings);
    else
      result.guides.append(buildGuide(input, result.rect, false, *pickY));
  }

  return result;
}

UI::Snap::SnapResult UI::Snap::resolveResizeSnap(const SnapInput& input, const MovingEdges& edges)
{
  SnapResult result;
  result.rect = input.rect;
  if (input.canvas.isEmpty() || (edges.left && edges.right) || (edges.top && edges.bottom))
    return result;

  std::optional<Candidate> pickX;
  std::optional<Candidate> pickY;
  const bool horizMoving = edges.left || edges.right;
  const bool vertMoving  = edges.top || edges.bottom;

  QVector<Candidate> candidates;
  candidates.reserve(input.siblings.size() * 3 + 1);

  if (horizMoving) {
    appendResizeCandidates(input, true, edges.left, candidates);
    pickX = pickCandidate(candidates);
    applyResizePick(pickX, input, true, edges.left, result.rect);
  }

  if (vertMoving) {
    candidates.clear();
    appendResizeCandidates(input, false, edges.top, candidates);
    pickY = pickCandidate(candidates);
    applyResizePick(pickY, input, false, edges.top, result.rect);
  }

  result.guides.reserve(2);

  if (pickX.has_value()) {
    if (pickX->rank == kRankSize)
      result.sizeMatch = pickX->pairA;
    else
      result.guides.append(buildGuide(input, result.rect, true, *pickX));
  }

  if (pickY.has_value()) {
    if (pickY->rank == kRankSize) {
      if (!result.sizeMatch.isValid())
        result.sizeMatch = pickY->pairA;
    } else
      result.guides.append(buildGuide(input, result.rect, false, *pickY));
  }

  return result;
}

static void snapVisualsToVariants(const UI::Snap::SnapResult& result,
                                  QVariantList& guides,
                                  QVariantList& spacings)
{
  guides.reserve(result.guides.size());
  for (const auto& guide : result.guides) {
    QVariantMap entry;
    entry["x"]      = guide.rect.x();
    entry["y"]      = guide.rect.y();
    entry["width"]  = guide.rect.width();
    entry["height"] = guide.rect.height();
    entry["center"] = guide.kind == UI::Snap::GuideKind::Center;
    guides.append(entry);
  }
  spacings.reserve(result.spacings.size());
  for (const auto& spacing : result.spacings) {
    QVariantMap entry;
    entry["x"]      = spacing.rect.x();
    entry["y"]      = spacing.rect.y();
    entry["width"]  = spacing.rect.width();
    entry["height"] = spacing.rect.height();
    entry["gap"]    = spacing.gap;
    spacings.append(entry);
  }
  , m_gridEnabled(false)
  , m_gridSize(16)
  , m_manualGestureActive(false)
  m_gridEnabled     = m_settings.value("WindowManager_GridEnabled", false).toBool();
  m_gridSize        = qBound(2, m_settings.value("WindowManager_GridSize", 16).toInt(), 256);
/**
 * @brief Returns the grid cell size in pixels for manual-mode grid snapping.
 */
int UI::WindowManager::gridSize() const
{
  return m_gridSize;
}

/**
 * @brief Returns whether the manual-mode layout grid (render + snap) is enabled.
 */
bool UI::WindowManager::gridEnabled() const
{
  return m_gridEnabled;
}

/**
 * @brief Returns whether a size-matched sibling should be highlighted.
