void UI::WindowManager::publishSnapGuides(const Snap::SnapResult& result)
{
  QVariantList guides;
  QVariantList spacings;
  snapVisualsToVariants(result, guides, spacings);

  if (m_alignmentGuides != guides) {
    m_alignmentGuides = std::move(guides);
    Q_EMIT alignmentGuidesChanged();
  }

  if (m_spacingIndicators != spacings) {
    m_spacingIndicators = std::move(spacings);
    Q_EMIT spacingIndicatorsChanged();
  }

  if (m_sizeMatchRect != result.sizeMatch) {
    m_sizeMatchRect = result.sizeMatch;
    Q_EMIT sizeMatchRectChanged();
  }
}

void UI::WindowManager::clearSnapGuides()
{
  if (!m_alignmentGuides.isEmpty()) {
    m_alignmentGuides.clear();
    Q_EMIT alignmentGuidesChanged();
  }

  if (!m_spacingIndicators.isEmpty()) {
    m_spacingIndicators.clear();
    Q_EMIT spacingIndicatorsChanged();
  }

  if (m_sizeMatchRect.isValid()) {
    m_sizeMatchRect = QRect();
    Q_EMIT sizeMatchRectChanged();
  }
}

void UI::WindowManager::publishManualGesture(const QRect& geometry)
{
  if (m_manualGestureActive && m_manualGestureGeometry == geometry)
  m_manualGestureActive   = true;
  m_manualGestureGeometry = geometry;
  Q_EMIT manualGestureChanged();
}

void AI::Conversation::maybeProposeMemory(const QString& userText)
{
  static auto& assistant = Assistant::instance();
  if (!assistant.memoryEnabled())
    return;

  static const QStringList kTriggers = {
    QStringLiteral("remember that"),
    QStringLiteral("remember this"),
    QStringLiteral("remember my"),
    QStringLiteral("please remember"),
    QStringLiteral("don't forget"),
    QStringLiteral("do not forget"),
    QStringLiteral("keep in mind"),
    QStringLiteral("from now on"),
    QStringLiteral("i always"),
    QStringLiteral("i never"),
    QStringLiteral("i prefer"),
    QStringLiteral("always use"),
    QStringLiteral("never use"),
    QStringLiteral("my preference"),
  };

  const auto lower = userText.toLower();
  bool matched     = false;
  for (const auto& trigger : kTriggers) {
    if (lower.contains(trigger)) {
      matched = true;
      break;
    }
  }

  if (!matched)
    return;

  static const QStringList kCorrectionCues = {
    QStringLiteral("never"),
    QStringLiteral("don't"),
    QStringLiteral("do not"),
    QStringLiteral("stop "),
    QStringLiteral("instead"),
  };

  QString category = QStringLiteral("user");
  for (const auto& cue : kCorrectionCues) {
    if (lower.contains(cue)) {
      category = QStringLiteral("feedback");
      break;
    }
  }

  const auto fact = userText.simplified().left(400);
  Q_EMIT memoryProposed(category, fact);
  qCDebug(serialStudioAI) << "MemoryTrigger: deterministic proposal surfaced, category="
                          << category;
}

QJsonObject AI::Conversation::verifySourceUpdate(const QJsonObject& arguments)
{
  QJsonObject v;
  v[QStringLiteral("method")] = QStringLiteral("project.source.list");

  const auto check =
    m_dispatcher->executeCommand(QStringLiteral("project.source.list"), QJsonObject(), true);
  if (!check.value(QStringLiteral("ok")).toBool()) {
    v[QStringLiteral("ok")]     = false;
    v[QStringLiteral("detail")] = tr("Source list read-back failed");
    qCDebug(serialStudioAI) << "AutoVerify: project.source.update via project.source.list "
                               "ok= false (list failed)";
    return v;
  }

  const int source_id = arguments.value(Keys::SourceId).toInt(-1);
  const auto rows =
    check.value(QStringLiteral("result")).toObject().value(QStringLiteral("sources")).toArray();

  QJsonObject row;
  for (const auto& r : rows) {
    const auto obj = r.toObject();
    if (obj.value(Keys::SourceId).toInt(-1) == source_id) {
      row = obj;
      break;
    }
  }

  if (row.isEmpty()) {
    v[QStringLiteral("ok")]     = false;
    v[QStringLiteral("detail")] = tr("Source %1 not found after update").arg(source_id);
    qCDebug(serialStudioAI) << "AutoVerify: project.source.update via project.source.list "
                               "ok= false (source missing)";
    return v;
  }

  QStringList mismatched;
  for (auto it = arguments.constBegin(); it != arguments.constEnd(); ++it) {
    if (it.key() == Keys::SourceId || !row.contains(it.key()))
      continue;

    if (row.value(it.key()) != it.value())
      mismatched.append(it.key());
  }

  v[QStringLiteral("ok")] = mismatched.isEmpty();
  if (!mismatched.isEmpty())
    v[QStringLiteral("detail")] =
      tr("Fields did not round-trip: %1").arg(mismatched.join(QStringLiteral(", ")));

  qCDebug(serialStudioAI) << "AutoVerify: project.source.update via project.source.list ok="
                          << mismatched.isEmpty();
  return v;
}

static QJsonObject frameConfigArgsFor(const QJsonObject& args)
{
  QJsonObject config;
  if (args.contains(Keys::FrameStart))
    config[QStringLiteral("startSequence")] = args.value(Keys::FrameStart).toString();

  if (args.contains(Keys::FrameEnd))
    config[QStringLiteral("endSequence")] = args.value(Keys::FrameEnd).toString();

  if (args.contains(Keys::FrameDetection))
    config[Keys::FrameDetection] = args.value(Keys::FrameDetection).toInt();

  if (args.contains(Keys::DecoderMethod))
    config[Keys::DecoderMethod] = args.value(Keys::DecoderMethod).toInt();

  if (args.contains(Keys::HexadecimalDelimiters))
    config[Keys::HexadecimalDelimiters] = args.value(Keys::HexadecimalDelimiters).toBool();

  if (args.contains(Keys::ChecksumAlgorithm))
    config[Keys::ChecksumAlgorithm] = args.value(Keys::ChecksumAlgorithm).toString();

  if (!config.isEmpty() && args.contains(Keys::SourceId))
    config[Keys::SourceId] = args.value(Keys::SourceId).toInt();

  return config;
}

QString applyDatasetTextAndToggleFields(DataModel::Dataset& d,
                                               const QJsonObject& params,
                                               bool& rebuildTree,
                                               QSet<QString>& consumed)
  if (takeParam(params, consumed, Keys::Color)) {
    const auto color = params.value(Keys::Color).toString().simplified();
    if (!color.isEmpty() && !QColor::fromString(color).isValid())
      return QStringLiteral("Invalid color '%1': use '#rrggbb' or a valid color name; "
                            "empty string restores the automatic theme color")
        .arg(color);

    d.color = color;
  }

QColor SerialStudio::getDatasetColor(const DataModel::Dataset& dataset)
{
  if (!dataset.color.isEmpty()) {
    const auto color = QColor::fromString(dataset.color);
    if (color.isValid())
      return color;
  }

  return getDatasetColor(dataset.index);
}

QColor SerialStudio::getGroupColorOverride(const DataModel::Group& group)
{
  for (const auto& dataset : group.datasets) {
    if (dataset.color.isEmpty())
      continue;

    const auto color = QColor::fromString(dataset.color);
    if (color.isValid())
      return color;
  }

  return {};
}

