void AI::Assistant::newChatFromHandoff(const QString& id)
{
  QString digest;
  if (m_handoffSeedingEnabled) {
    if (id == m_activeChatId && m_conversation)
      digest = m_conversation->buildHandoffDigest();
    else if (m_chats.contains(id))
      digest = m_chats.loadChat(id).value(QStringLiteral("handoff")).toString();
  }

  newChat();
  if (m_conversation && !digest.isEmpty()) {
    m_conversation->setHandoffSeed(digest);
    qCDebug(serialStudioAI) << "Handoff seed carried into new chat (" << digest.size() << "chars )";
  }
}

static AI::Assistant& assistantRef()
{
  static auto& singleton = AI::Assistant::instance();
  return singleton;
}

QString AI::ContextBuilder::memoryIndexBlock()
{
  const auto index = assistantRef().memoryIndex();
  if (index.isEmpty())
    return {};

  QString out;
  out += QStringLiteral("# Remembered facts (user-approved, from earlier chats)\n\n");
  out += QStringLiteral("<untrusted source=\"assistant_memory\">\n");
  out += neutralizeUntrustedDelimiter(index);
  out += QStringLiteral("</untrusted>\n");
  return out;
}

QString AI::ContextBuilder::handoffBlock()
{
  const auto seed = assistantRef().handoffSeedText();
  if (seed.isEmpty())
    return {};

  QString out;
  out += QStringLiteral("# Previous chat handoff (continue from here)\n\n");
  out += QStringLiteral("<untrusted source=\"previous_chat\">\n");
  out += neutralizeUntrustedDelimiter(seed);
  out += QStringLiteral("\n</untrusted>\n");
  return out;
}

QString AI::Conversation::probeComplianceKey() const
{
  if (!m_provider)
    return QStringLiteral("none");

  return m_provider->displayName() + QLatin1Char('/') + m_provider->currentModel();
}

void AI::Conversation::evaluateProbe()
{
  static auto& assistant = Assistant::instance();
  if (!assistant.contextProbeEnabled())
    return;

  if (m_assistantText.isEmpty() || !m_pendingToolUseBlocks.isEmpty())
    return;

  const bool was_degraded = m_probe.degraded();
  const auto was_failure  = m_probe.lastFailure();
  const auto was_drifted  = m_probe.driftedSegment();
  const auto outcome      = m_probe.evaluateReply(m_assistantText);
  qCDebug(serialStudioAI) << "SentinelProbe: outcome" << static_cast<int>(outcome);

  if (m_probe.degraded() != was_degraded || m_probe.lastFailure() != was_failure
      || m_probe.driftedSegment() != was_drifted)
    Q_EMIT probeStateChanged();
}

void AI::Conversation::injectRoutedSkill(const QString& userText)
{
  static auto& assistant = Assistant::instance();
  if (!assistant.skillRoutingEnabled())
    return;

  static const SkillRouter router;
  const auto skill = router.match(userText, m_loadedSkills);
  if (skill.isEmpty())
    return;

  const int budget = m_provider ? m_provider->capabilities().toolResultByteBudget : 4096;
  const auto pair  = SkillRouter::buildInjectionPair(skill, budget);
  if (pair.isEmpty())
    return;

  for (const auto& msg : pair)
    m_history.append(msg);

  m_loadedSkills.insert(skill);

  auto row                              = m_uiMessages.last().toMap();
  row[QStringLiteral("loadedSkill")]    = skill;
  m_uiMessages[m_uiMessages.size() - 1] = row;
  Q_EMIT messagesChanged();

  qCDebug(serialStudioAI) << "SkillRouter: injected" << skill << "for this turn";
}

static bool readBackCommandFor(const QString& name,
                               const QJsonObject& arguments,
                               QString& cmd,
                               QJsonObject& args)
{
  if (name == QStringLiteral("project.frameParser.setCode")) {
    cmd  = QStringLiteral("project.frameParser.dryCompile");
    args = arguments;
    return true;
  }

  if (name == QStringLiteral("project.dataset.setTransformCode")) {
    cmd  = QStringLiteral("project.dataset.transform.dryRun");
    args = arguments;
    if (!args.contains(QStringLiteral("values")))
      args[QStringLiteral("values")] = QJsonArray{0.0};

    return true;
  }

  if (name == QStringLiteral("project.painter.setCode")) {
    cmd  = QStringLiteral("project.painter.dryRun");
    args = arguments;
    return true;
  }

  if (name == QStringLiteral("project.outputWidget.update")
      && arguments.contains(QStringLiteral("transmitFunction"))) {
    cmd  = QStringLiteral("project.outputWidget.dryRun");
    args = QJsonObject{
      {QStringLiteral("code"), arguments.value(QStringLiteral("transmitFunction"))}
    };
    return true;
  }

  return false;
}

QJsonObject AI::Conversation::runAutoVerify(const QString& name,
                                            const QJsonObject& arguments,
                                            const QJsonObject& reply)
{
  static auto& assistant = Assistant::instance();
  if (!assistant.autoVerifyEnabled() || !reply.value(QStringLiteral("ok")).toBool())
    return {};

  if (name == QStringLiteral("assistant.script.apply")) {
    QJsonObject v;
    v[QStringLiteral("ok")]     = true;
    v[QStringLiteral("method")] = QStringLiteral("internal dry-run");
    return v;
  }

  if (name == QStringLiteral("assistant.project.bulkApply")) {
    const int failures = reply.value(QStringLiteral("failureCount")).toInt();
    QJsonObject v;
    v[QStringLiteral("ok")]     = failures == 0;
    v[QStringLiteral("method")] = QStringLiteral("batch failure scan");
    if (failures > 0)
      v[QStringLiteral("detail")] = tr("%n operation(s) failed", nullptr, failures);

    return v;
  }

  QString cmd;
  QJsonObject args;
  if (!readBackCommandFor(name, arguments, cmd, args))
    return {};

  static auto& registry = AI::CommandRegistry::instance();
  const bool safe       = registry.safetyOf(cmd) == Safety::Safe;
  Q_ASSERT(safe);
  if (!safe) {
    qCWarning(serialStudioAI) << "AutoVerify: refusing non-Safe read-back" << cmd;
    return {};
  }

  const auto check = m_dispatcher->executeCommand(cmd, args, true);
  bool check_ok    = check.value(QStringLiteral("ok")).toBool();
  const auto inner = check.value(QStringLiteral("result")).toObject();
  if (check_ok && inner.contains(QStringLiteral("ok")))
    check_ok = inner.value(QStringLiteral("ok")).toBool();

  QJsonObject v;
  v[QStringLiteral("ok")]     = check_ok;
  v[QStringLiteral("method")] = cmd;
  if (!check_ok)
    v[QStringLiteral("detail")] =
      QString::fromUtf8(QJsonDocument(check).toJson(QJsonDocument::Compact)).left(300);

  qCDebug(serialStudioAI) << "AutoVerify:" << name << "via" << cmd << "ok=" << check_ok;
  return v;
}

QString AI::Conversation::buildHandoffDigest() const
{
  if (m_uiMessages.isEmpty())
    return {};

  QStringList asks;
  QStringList actions;
  QString last_reply;
  for (int i = static_cast<int>(m_uiMessages.size()) - 1; i >= 0; --i) {
    if (asks.size() >= 3 && !last_reply.isEmpty())
      break;

    const auto map  = m_uiMessages.at(i).toMap();
    const auto role = map.value(QStringLiteral("role")).toString();
    if (role == QStringLiteral("user") && asks.size() < 3) {
      const auto text =
        map.value(QStringLiteral("text")).toString().left(480).simplified().left(120);
      if (!text.isEmpty())
        asks.prepend(text);
    }

    if (role != QStringLiteral("assistant"))
      continue;

    if (last_reply.isEmpty())
      last_reply = map.value(QStringLiteral("text")).toString().left(800).simplified().left(200);

    const auto calls = map.value(QStringLiteral("toolCalls")).toList();
    for (const auto& c : calls) {
      const auto card = c.toMap();
      const auto name = card.value(QStringLiteral("name")).toString();
      const auto done =
        card.value(QStringLiteral("status")).toInt() == static_cast<int>(CallStatus::Done);
      if (done && !name.startsWith(QStringLiteral("meta.")) && !actions.contains(name)
          && actions.size() < 10)
        actions.append(name);
    }
  }

  QString out;
  out += QStringLiteral("Asked: ") + asks.join(QStringLiteral(" | ")) + QLatin1Char('\n');
  if (!actions.isEmpty())
    out += QStringLiteral("Actions: ") + actions.join(QStringLiteral(", ")) + QLatin1Char('\n');

  if (!last_reply.isEmpty())
    out += QStringLiteral("Last reply: ") + last_reply + QLatin1Char('\n');

  (void)Redactor::scrub(out);
  out.truncate(kMaxDigestChars);
  return out;
}

QString AI::Conversation::probeDetail() const
{
  if (!m_probe.degraded())
    return {};

  if (m_probe.lastFailure() == SentinelProbe::Outcome::Missing)
    return tr("The model stopped reproducing its context-integrity line. Long "
              "conversations degrade silently; recent replies may be less reliable.");

  return tr("The model altered its context-integrity line (drifted segment: %1). Long "
            "conversations degrade silently; recent replies may be less reliable.")
    .arg(m_probe.driftedSegment());
}

QString AI::MemoryStore::memoryPath()
{
  const auto base = QStandardPaths::writableLocation(QStandardPaths::AppLocalDataLocation);
  return base + QStringLiteral("/ai/memory.json");
}

QStringList AI::MemoryStore::categories()
{
  return {
    QStringLiteral("user"),
    QStringLiteral("feedback"),
    QStringLiteral("project"),
    QStringLiteral("reference"),
  };
}

QVariantList AI::MemoryStore::list() const
{
  QVariantList out;
  for (const auto& fact : m_facts) {
    QVariantMap row;
    row[QStringLiteral("id")]          = fact.id;
    row[QStringLiteral("category")]    = fact.category;
    row[QStringLiteral("text")]        = fact.text;
    row[QStringLiteral("projectPath")] = fact.projectPath;
    row[QStringLiteral("createdAt")]   = fact.createdAt;
    out.append(row);
  }
  return out;
}

QString AI::MemoryStore::indexBlock(const QString& projectPath) const
{
  QString out;
  for (const auto& fact : m_facts) {
    if (!fact.projectPath.isEmpty() && fact.projectPath != projectPath)
      continue;

    const auto line = QStringLiteral("- [%1] %2\n").arg(fact.category, fact.text);
    if (out.size() + line.size() > kMaxIndexBytes)
      break;

    out += line;
  }
  return out;
}

int AI::MemoryStore::indexOf(const QString& id) const
{
  for (int i = 0; i < m_facts.size(); ++i)
    if (m_facts.at(i).id == id)
      return i;

  return -1;
}

bool AI::MemoryStore::sanitizeText(QString& text)
{
  text = text.trimmed();
  if (text.isEmpty())
    return false;

  (void)Redactor::scrub(text);

  auto probe = text;
  static const QRegularExpression kRedacted(QStringLiteral("\\[REDACTED:[^\\]]*\\]"));
  probe.remove(kRedacted);
  if (probe.trimmed().isEmpty())
    return false;

  if (text.size() > kMaxFactChars) {
    text.truncate(kMaxFactChars - 3);
    text += QStringLiteral("...");
  }

  return true;
}

bool AI::MemoryStore::addFact(const QString& category,
                              const QString& text,
                              const QString& projectPath)
{
  if (!categories().contains(category))
    return false;

  auto clean = text;
  if (!sanitizeText(clean))
    return false;

  Fact fact;
  fact.id          = QUuid::createUuid().toString(QUuid::WithoutBraces);
  fact.category    = category;
  fact.text        = clean;
  fact.projectPath = category == QStringLiteral("project") ? projectPath : QString();
  fact.createdAt   = QDateTime::currentMSecsSinceEpoch();
  fact.lastUsedAt  = fact.createdAt;

  m_facts.prepend(fact);
  evictOverflow();
  return writeStore();
}

bool AI::MemoryStore::updateFact(const QString& id, const QString& text)
{
  const int idx = indexOf(id);
  if (idx < 0)
    return false;

  auto clean = text;
  if (!sanitizeText(clean))
    return false;

  m_facts[idx].text       = clean;
  m_facts[idx].lastUsedAt = QDateTime::currentMSecsSinceEpoch();
  return writeStore();
}

void AI::MemoryStore::removeFact(const QString& id)
{
  const int idx = indexOf(id);
  if (idx < 0)
    return;

  m_facts.removeAt(idx);
  (void)writeStore();
}

void AI::MemoryStore::evictOverflow()
{
  while (m_facts.size() > kMaxFacts) {
    int oldest = 0;
    for (int i = 1; i < m_facts.size(); ++i)
      if (m_facts.at(i).lastUsedAt < m_facts.at(oldest).lastUsedAt)
        oldest = i;

    qCDebug(serialStudioAI) << "MemoryStore: evicting" << m_facts.at(oldest).id;
    m_facts.removeAt(oldest);
  }
}

void AI::MemoryStore::readStore()
{
  m_facts.clear();

  QFile f(memoryPath());
  if (!f.exists() || !f.open(QIODevice::ReadOnly))
    return;

  if (f.size() > kMaxFileBytes) {
    qCWarning(serialStudioAI) << "MemoryStore: refusing oversized memory file (" << f.size()
                              << "bytes )";
    f.close();
    return;
  }

  const auto bytes = f.readAll();
  f.close();

  const auto doc = QJsonDocument::fromJson(bytes);
  if (!doc.isObject())
    return;

  if (doc.object().value(QStringLiteral("schema")).toInt() != 1) {
    qCWarning(serialStudioAI) << "MemoryStore: unknown schema, ignoring file";
    return;
  }

  const auto arr = doc.object().value(QStringLiteral("facts")).toArray();
  for (const auto& v : arr) {
    if (m_facts.size() >= kMaxFacts)
      break;

    const auto obj = v.toObject();
    Fact fact;
    fact.id          = obj.value(QStringLiteral("id")).toString();
    fact.category    = obj.value(QStringLiteral("category")).toString();
    fact.text        = obj.value(QStringLiteral("text")).toString();
    fact.projectPath = obj.value(QStringLiteral("projectPath")).toString();
    fact.createdAt =
      static_cast<qint64>(SerialStudio::toDouble(obj.value(QStringLiteral("createdAt"))));
    fact.lastUsedAt =
      static_cast<qint64>(SerialStudio::toDouble(obj.value(QStringLiteral("lastUsedAt"))));
    if (!fact.id.isEmpty() && categories().contains(fact.category) && sanitizeText(fact.text))
      m_facts.append(fact);
  }
}

bool AI::MemoryStore::writeStore() const
{
  QJsonArray arr;
  for (const auto& fact : m_facts) {
    QJsonObject obj;
    obj[QStringLiteral("id")]          = fact.id;
    obj[QStringLiteral("category")]    = fact.category;
    obj[QStringLiteral("text")]        = fact.text;
    obj[QStringLiteral("projectPath")] = fact.projectPath;
    obj[QStringLiteral("createdAt")]   = static_cast<double>(fact.createdAt);
    obj[QStringLiteral("lastUsedAt")]  = static_cast<double>(fact.lastUsedAt);
    arr.append(obj);
  }

  QJsonObject root;
  root[QStringLiteral("schema")] = 1;
  root[QStringLiteral("facts")]  = arr;

  QDir().mkpath(QFileInfo(memoryPath()).absolutePath());
  QFile f(memoryPath());
  if (!f.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
    qCWarning(serialStudioAI) << "MemoryStore: cannot write" << f.errorString();
    return false;
  }

  const auto bytes   = QJsonDocument(root).toJson(QJsonDocument::Compact);
  const auto written = f.write(bytes);
  f.close();
  if (written != bytes.size()) {
    qCWarning(serialStudioAI) << "MemoryStore: short write" << written << "of" << bytes.size();
    return false;
  }

  return true;
}

static const QString& sentinelMarker()
{
  static const QString kMarker = QStringLiteral("[[SS-CHECK");
  return kMarker;
}

static const QStringList& sentinelTokens()
{
  static const QStringList kTokens = {
    QStringLiteral("tools=approved"),
    QStringLiteral("untrusted=data"),
    QStringLiteral("ids=fresh"),
    QStringLiteral("batch=bulk"),
    QStringLiteral("save=auto"),
  };
  return kTokens;
}

static QString firstDriftedToken(const QString& body)
{
  for (const auto& token : sentinelTokens())
    if (!body.contains(token))
      return token;

  return QStringLiteral("(format)");
}

QString AI::SentinelProbe::sentinelLine()
{
  static const QString kLine = sentinelMarker() + QLatin1Char(' ')
                             + sentinelTokens().join(QLatin1Char(' ')) + QStringLiteral("]]");
  return kLine;
}

QString AI::SentinelProbe::stripForDisplay(const QString& text)
{
  const auto& marker = sentinelMarker();

  const int idx = text.lastIndexOf(marker);
  if (idx >= 0) {
    const int close     = text.indexOf(QStringLiteral("]]"), idx);
    const bool complete = close >= 0;
    if (complete && !QStringView(text).mid(close + 2).trimmed().isEmpty())
      return text;

    if (!complete && text.indexOf(QLatin1Char('\n'), idx) >= 0)
      return text;

    QString out = text.left(idx);
    while (!out.isEmpty() && (out.endsWith(QLatin1Char('\n')) || out.endsWith(QLatin1Char(' '))))
      out.chop(1);

    return out;
  }

  const int maxPrefix = qMin(marker.size() - 1, static_cast<int>(text.size()));
  for (int len = maxPrefix; len >= 1; --len)
    if (text.endsWith(marker.left(len)))
      return text.left(text.size() - len);

  return text;
}

QString AI::SentinelProbe::sanitizeKey(const QString& key)
{
  auto out = key;
  out.replace(QLatin1Char('/'), QLatin1Char('_'));
  out.replace(QLatin1Char('\\'), QLatin1Char('_'));
  return out;
}

void AI::SentinelProbe::reset(const QString& complianceKey)
{
  m_key = sanitizeKey(complianceKey);
  m_drifted.clear();
  m_lastFailure = Outcome::Muted;
  m_replyCount  = 0;
  m_sawSentinel = false;
  m_degraded    = false;
}

void AI::SentinelProbe::ensureKey(const QString& complianceKey)
{
  if (sanitizeKey(complianceKey) == m_key)
    return;

  reset(complianceKey);
}

void AI::SentinelProbe::restoreLatch(bool degraded, Outcome failure, const QString& drifted)
{
  m_degraded    = degraded;
  m_lastFailure = failure;
  m_drifted     = drifted;
}

AI::SentinelProbe::Outcome AI::SentinelProbe::evaluateReply(const QString& completedText)
{
  Q_ASSERT(!m_key.isEmpty());
  if (m_key.isEmpty())
    return Outcome::Muted;

  ++m_replyCount;

  QString drifted;
  const auto verdict = classify(completedText, &drifted);

  if (verdict == Outcome::Healthy) {
    m_sawSentinel = true;
    if (storedCompliance() != 1)
      persistCompliance(true);

    return Outcome::Healthy;
  }

  const bool known_compliant = m_sawSentinel || storedCompliance() == 1;
  if (known_compliant) {
    m_degraded    = true;
    m_lastFailure = verdict;
    m_drifted     = drifted;
    qCWarning(serialStudioAI) << "SentinelProbe: degradation detected," << int(verdict)
                              << "drifted:" << drifted;
    return verdict;
  }

  if (storedCompliance() < 0 && m_replyCount >= kComplianceWindow)
    persistCompliance(false);

  return Outcome::Muted;
}

AI::SentinelProbe::Outcome AI::SentinelProbe::classify(const QString& text, QString* drifted)
{
  const int idx = text.lastIndexOf(sentinelMarker());
  if (idx < 0)
    return Outcome::Missing;

  const int close = text.indexOf(QStringLiteral("]]"), idx);
  if (close < 0) {
    if (drifted)
      *drifted = QStringLiteral("(truncated)");

    return Outcome::Mutated;
  }

  const auto body = text.mid(idx, close + 2 - idx);
  if (body == sentinelLine())
    return Outcome::Healthy;

  if (drifted)
    *drifted = firstDriftedToken(body);

  return Outcome::Mutated;
}

int AI::SentinelProbe::storedCompliance() const
{
  QSettings settings;
  const auto value = settings.value(QStringLiteral("ai/compliance/") + m_key);
  if (!value.isValid())
    return -1;

  return value.toBool() ? 1 : 0;
}

void AI::SentinelProbe::persistCompliance(bool compliant) const
{
  QSettings settings;
  settings.setValue(QStringLiteral("ai/compliance/") + m_key, compliant);
  qCDebug(serialStudioAI) << "SentinelProbe: compliance" << m_key << "=" << compliant;
}

static QString neutralizeDelimiter(const QString& payload)
{
  QString out = payload;
  out.replace(QStringLiteral("</untrusted"), QStringLiteral("< /untrusted"), Qt::CaseInsensitive);
  out.replace(QStringLiteral("<untrusted"), QStringLiteral("< untrusted"), Qt::CaseInsensitive);
  return out;
}

void AI::SkillRouter::loadTriggers()
{
  QFile file(QStringLiteral(":/ai/skill_triggers.json"));
  if (!file.open(QIODevice::ReadOnly)) {
    qCWarning(serialStudioAI) << "SkillRouter: trigger resource not readable";
    return;
  }

  QJsonParseError parse_error;
  const auto doc = QJsonDocument::fromJson(file.readAll(), &parse_error);
  file.close();
  if (!doc.isObject()) {
    qCWarning(serialStudioAI) << "SkillRouter: invalid trigger resource:"
                              << parse_error.errorString();
    return;
  }

  const auto known  = ContextBuilder::skillIds();
  const auto skills = doc.object().value(QStringLiteral("skills")).toObject();
  for (auto it = skills.constBegin(); it != skills.constEnd(); ++it) {
    if (!known.contains(it.key())) {
      qCWarning(serialStudioAI) << "SkillRouter: unknown skill id in triggers:" << it.key();
      continue;
    }

    QStringList phrases;
    for (const auto& v : it.value().toArray()) {
      const auto phrase = v.toString().toLower().trimmed();
      if (!phrase.isEmpty())
        phrases.append(phrase);
    }

    if (!phrases.isEmpty())
      m_triggers.insert(it.key(), phrases);
  }
}

QString AI::SkillRouter::match(const QString& userText, const QSet<QString>& alreadyLoaded) const
{
  const auto haystack = userText.toLower();

  QString best;
  int bestLen = 0;
  for (auto it = m_triggers.constBegin(); it != m_triggers.constEnd(); ++it) {
    if (alreadyLoaded.contains(it.key()))
      continue;

    for (const auto& phrase : it.value()) {
      if (!haystack.contains(phrase))
        continue;

      const int len   = static_cast<int>(phrase.size());
      const bool wins = len > bestLen || (len == bestLen && it.key() < best);
      if (wins) {
        best    = it.key();
        bestLen = len;
      }
    }
  }

  if (!best.isEmpty())
    qCDebug(serialStudioAI) << "SkillRouter: matched" << best;

  return best;
}

QJsonArray AI::SkillRouter::buildInjectionPair(const QString& skillId, int byteBudget)
{
  auto body = ContextBuilder::skillBody(skillId);
  if (body.isEmpty())
    return {};

  const int budget = qBound(2048, byteBudget, 16 * 1024);
  if (body.toUtf8().size() > budget) {
    while (body.toUtf8().size() > budget && !body.isEmpty())
      body.chop(body.size() / 8 + 1);

    body += QStringLiteral("\n... [skill truncated to fit the model context]");
  }

  const auto callId = QStringLiteral("synthetic-skill-") + skillId;

  QJsonObject toolUse;
  toolUse[QStringLiteral("type")]  = QStringLiteral("tool_use");
  toolUse[QStringLiteral("id")]    = callId;
  toolUse[QStringLiteral("name")]  = QStringLiteral("meta.loadSkill");
  toolUse[QStringLiteral("input")] = QJsonObject{
    {QStringLiteral("name"), skillId}
  };
  toolUse[QStringLiteral("_synthetic")] = true;

  QJsonObject assistant;
  assistant[QStringLiteral("role")]    = QStringLiteral("assistant");
  assistant[QStringLiteral("content")] = QJsonArray{toolUse};

  QJsonObject payload;
  payload[QStringLiteral("ok")]         = true;
  payload[QStringLiteral("skill")]      = skillId;
  payload[QStringLiteral("body")]       = body;
  payload[QStringLiteral("autoLoaded")] = true;

  const auto payloadBytes = QJsonDocument(payload).toJson(QJsonDocument::Compact);
  QString wrapped;
  wrapped += QStringLiteral("<untrusted source=\"meta.loadSkill\">\n");
  wrapped += neutralizeDelimiter(QString::fromUtf8(payloadBytes));
  wrapped += QStringLiteral("\n</untrusted>");

  QJsonObject toolResult;
  toolResult[QStringLiteral("type")]                  = QStringLiteral("tool_result");
  toolResult[QStringLiteral("tool_use_id")]           = callId;
  toolResult[QStringLiteral("content")]               = wrapped;
  QJsonObject geminiPayload                           = payload;
  geminiPayload[QStringLiteral("__untrusted_source")] = QStringLiteral("meta.loadSkill");
  toolResult[QStringLiteral("_gemini_response")]      = geminiPayload;
  toolResult[QStringLiteral("_tool_name")]            = QStringLiteral("meta.loadSkill");

  QJsonObject user;
  user[QStringLiteral("role")]    = QStringLiteral("user");
  user[QStringLiteral("content")] = QJsonArray{toolResult};

  return QJsonArray{assistant, user};
}

static QJsonObject memoryProposeInputSchema()
{
  QJsonObject props;
  props[QStringLiteral("category")] = makeProperty(
    QStringLiteral("string"), QStringLiteral("One of: user, feedback, project, reference."));
  props[QStringLiteral("text")] =
    makeProperty(QStringLiteral("string"),
                 QStringLiteral("The fact to remember, stated plainly, under 400 characters."));
  return makeObjectSchema(props, QJsonArray{QStringLiteral("category"), QStringLiteral("text")});
}

API::CommandResponse API::Handlers::AssistantHandler::memoryPropose(const QString& id,
                                                                    const QJsonObject& params)
{
  const auto category = params.value(QStringLiteral("category")).toString();
  const auto text     = params.value(QStringLiteral("text")).toString().trimmed();

  if (!AI::MemoryStore::categories().contains(category))
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("Unknown category: '%1'. Use one of: user, feedback, project, reference.")
        .arg(category));

  if (text.isEmpty() || text.size() > AI::MemoryStore::kMaxFactChars)
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("Provide a non-empty fact under %1 characters.")
        .arg(AI::MemoryStore::kMaxFactChars));

  QJsonObject result;
  result[QStringLiteral("queued")] = true;
  result[QStringLiteral("note")] =
    QStringLiteral("Proposal shown to the user for confirmation; nothing has been stored.");
  return CommandResponse::makeSuccess(id, result);
}

void API::Handlers::AssistantHandler::registerMemoryCommands()
{
  static auto& registry = CommandRegistry::instance();
  registry.registerCommand(
    QStringLiteral("assistant.memory.propose"),
    QStringLiteral("Propose remembering a small durable fact for future chats (a stated "
                   "preference, a correction you were given, a project convention). The "
                   "user sees a confirmation chip and decides; this call NEVER stores "
                   "anything by itself. Categories: user (who they are / preferences), "
                   "feedback (corrections), project (facts about the open project), "
                   "reference (where to find things)."),
    API::makeSchema(
      {
        {QStringLiteral("category"),
         QStringLiteral("string"),
         QStringLiteral("One of: user, feedback, project, reference.")                },
        {    QStringLiteral("text"),
         QStringLiteral("string"),
         QStringLiteral("The fact to remember, stated plainly, under 400 characters.")}
  },
      {}),
    &API::Handlers::AssistantHandler::memoryPropose);
}

