void Widgets::Terminal::drawRepeatBadge(
  QPainter* painter, int count, int segmentWidth, int y, bool rtlMode)
{
  Q_ASSERT(painter);
  Q_ASSERT(count > 1);

  const QString label   = QStringLiteral("\u00D7 %1").arg(count);
  const int padX        = qMax(2, m_cWidth / 2);
  const int badgeWidth  = m_badgeMetrics.horizontalAdvance(label) + padX * 2;
  const int badgeHeight = qMax(2, m_cHeight - 2);
  const int rightEdge   = width() - m_borderX;

  const int x =
    rtlMode ? (rightEdge - segmentWidth - padX - badgeWidth) : (m_borderX + segmentWidth + padX);
  if (x < m_borderX || x + badgeWidth > rightEdge)
    return;

  const QRect rect(x, y + (m_cHeight - badgeHeight) / 2, badgeWidth, badgeHeight);
  painter->save();
  painter->setRenderHint(QPainter::Antialiasing);
  painter->setPen(Qt::NoPen);
  painter->setBrush(m_palette.color(QPalette::Highlight));
  painter->drawRoundedRect(rect, badgeHeight / 2.0, badgeHeight / 2.0);
  painter->setPen(m_palette.color(QPalette::Text));
  painter->setFont(m_badgeFont);
  painter->drawText(rect, Qt::AlignCenter, label);
  painter->restore();
}

void Widgets::Terminal::drawSegmentMatch(QPainter* painter,
                                         const QFontMetrics& fm,
                                         const QString& line,
                                         const QPoint& match,
                                         bool isCurrent,
                                         int segStart,
                                         int segEnd,
                                         int y)
{
  const int matchStart = match.x();
  const int matchEnd   = matchStart + static_cast<int>(m_searchQuery.length());
  const int selStartX  = qMax(matchStart, segStart);
  const int selEndX    = qMin(matchEnd, segEnd);
  if (selStartX >= selEndX)
    return;

  int leadingOffset = 0;
  int matchWidth    = 0;
  for (int j = segStart; j < selEndX; ++j) {
    const int charWidth = fm.horizontalAdvance(line[j]);
    if (j < selStartX)
      leadingOffset += charWidth;
    else
      matchWidth += charWidth;
  }

  const bool rtl     = m_translator.rtl();
  const int maxWidth = width() - 2 * m_borderX;

  int startX = 0;
  if (rtl) {
    const int rightEdge = width() - m_borderX;
    startX              = rightEdge - leadingOffset - matchWidth;
    matchWidth          = qMin(matchWidth, maxWidth);
  }

  else {
    startX     = m_borderX + leadingOffset;
    matchWidth = qMin(matchWidth, maxWidth - leadingOffset);
  }

  QColor fill = m_palette.color(QPalette::Highlight);
  if (!isCurrent)
    fill.setAlpha(110);

  painter->fillRect(QRect(startX, y, matchWidth, m_cHeight), fill);
}

void Widgets::Terminal::paintSearchHighlights(QPainter* painter,
                                              int firstLine,
                                              int lastVLine,
                                              int lineHeight)
{
  if (m_searchMatches.isEmpty())
    return;

  const QFontMetrics fm = painter->fontMetrics();

  const qsizetype matchCount = m_searchMatches.size();
  qsizetype k                = 0;
  while (k < matchCount && m_searchMatches[k].y() < firstLine)
    ++k;

  int y = m_borderY;
  for (int i = firstLine; i <= lastVLine && y < height() - m_borderY; ++i) {
    const QString& line = m_data[i];

    const qsizetype lineFirst = k;
    while (k < matchCount && m_searchMatches[k].y() <= i)
      ++k;

    if (line.isEmpty()) {
      y += lineHeight;
      continue;
    }

    int start = 0;
    while (start < line.length()) {
      const int segEnd = qMin<int>(start + maxCharsPerLine(), line.length());
      for (qsizetype m = lineFirst; m < k; ++m)
        drawSegmentMatch(painter,
                         fm,
                         line,
                         m_searchMatches[m],
                         m == static_cast<qsizetype>(m_searchCurrent),
                         start,
                         segEnd,
                         y);

      y     += lineHeight;
      start  = segEnd;
    }
  }
}

void Widgets::Terminal::setSearchQuery(const QString& query, const bool caseSensitive)
{
  if (m_searchQuery == query && m_searchCaseSensitive == caseSensitive)
    return;

  m_searchQuery         = query;
  m_searchCaseSensitive = caseSensitive;
  m_searchCurrent       = 0;
  refreshSearchMatches();
  update();
}

void Widgets::Terminal::searchNext()
{
  if (m_searchDirty)
    refreshSearchMatches();

  if (m_searchMatches.isEmpty())
    return;

  m_searchCurrent = (m_searchCurrent + 1) % static_cast<int>(m_searchMatches.size());
  Q_EMIT searchResultsChanged();
  scrollToCurrentMatch();
}

void Widgets::Terminal::searchPrevious()
{
  if (m_searchDirty)
    refreshSearchMatches();

  if (m_searchMatches.isEmpty())
    return;

  const int count = static_cast<int>(m_searchMatches.size());
  m_searchCurrent = (m_searchCurrent <= 0) ? count - 1 : m_searchCurrent - 1;
  Q_EMIT searchResultsChanged();
  scrollToCurrentMatch();
}

void Widgets::Terminal::clearSearch()
{
  if (m_searchQuery.isEmpty() && m_searchMatches.isEmpty())
    return;

  m_searchQuery.clear();
  m_searchMatches.clear();
  m_searchCurrent = -1;
  m_searchDirty   = false;
  Q_EMIT searchResultsChanged();
  m_stateChanged = true;
  update();
}

void Widgets::Terminal::refreshSearchMatches()
{
  m_searchDirty = false;
  m_searchMatches.clear();

  if (m_searchQuery.isEmpty()) {
    m_searchCurrent = -1;
    Q_EMIT searchResultsChanged();
    return;
  }

  const auto cs = m_searchCaseSensitive ? Qt::CaseSensitive : Qt::CaseInsensitive;
  for (int i = 0; i < m_data.size(); ++i) {
    const QString& line = m_data[i];

    qsizetype from = 0;
    while (from < line.length()) {
      const qsizetype index = line.indexOf(m_searchQuery, from, cs);
      if (index < 0)
        break;

      m_searchMatches.append(QPoint(static_cast<int>(index), i));
      from = index + qMax<qsizetype>(1, m_searchQuery.length());
    }
  }

  if (m_searchMatches.isEmpty())
    m_searchCurrent = -1;
  else
    m_searchCurrent = qBound(0, m_searchCurrent, static_cast<int>(m_searchMatches.size()) - 1);

  Q_ASSERT(m_searchCurrent >= -1);
  Q_ASSERT(m_searchCurrent < m_searchMatches.size());

  m_stateChanged = true;
  Q_EMIT searchResultsChanged();
}

void Widgets::Terminal::scrollToCurrentMatch()
{
  if (m_searchCurrent < 0 || m_searchCurrent >= m_searchMatches.size())
    return;

  setAutoscroll(false);

  const int row = m_searchMatches[m_searchCurrent].y();
  Q_ASSERT(row >= 0);
  Q_ASSERT(row < lineCount());

  int offset = m_scrollOffsetY;
  if (row < offset)
    offset = row;
  else if (row >= offset + linesPerPage())
    offset = row - linesPerPage() + 1;

  setScrollOffsetY(qBound(0, offset, qMax(0, lineCount() - 1)));
  m_stateChanged = true;
  update();
}

bool Widgets::Terminal::hasTimestampPrefix(QStringView line)
{
  constexpr int kStampLen        = 16;
  constexpr int kDigitIndices[9] = {0, 1, 3, 4, 6, 7, 9, 10, 11};

  if (line.size() < kStampLen)
    return false;

  if (line[2] != QLatin1Char(':') || line[5] != QLatin1Char(':') || line[8] != QLatin1Char('.'))
    return false;

  if (line[12] != QLatin1Char(' ') || line[13] != QLatin1Char('-') || line[14] != QLatin1Char('>')
      || line[15] != QLatin1Char(' '))
    return false;

  for (const int index : kDigitIndices)
    if (!line[index].isDigit())
      return false;

  return true;
}

QStringView Widgets::Terminal::lineContentView(QStringView line) const
{
  constexpr int kStampLen = 16;

  if (!m_consoleHandler.showTimestamp() || !hasTimestampPrefix(line))
    return line;

  return line.mid(kStampLen);
}

bool Widgets::Terminal::collapseCompletedLine()
{
  if (!m_collapseDuplicates)
    return false;

  const int y = m_cursorPosition.y();
  if (y < 1 || y != m_data.size() - 1)
    return false;

  const auto current  = lineContentView(m_data[y]);
  const auto previous = lineContentView(m_data[y - 1]);
  if (current.trimmed().isEmpty() || current != previous)
    return false;

  m_data.removeLast();
  if (m_colorData.size() > m_data.size())
    m_colorData.resize(m_data.size());

  if (m_repeatCounts.size() > m_data.size())
    m_repeatCounts.resize(m_data.size());

  Q_ASSERT(y - 1 < m_repeatCounts.size());
  if (y - 1 < m_repeatCounts.size() && m_repeatCounts[y - 1] < INT_MAX)
    ++m_repeatCounts[y - 1];

  m_searchDirty = true;

  if (autoscroll()) {
    const int lastRow = m_data.size() - 1;
    const int length  = m_data[lastRow].length();
    const int wrapped = qMax(1, (length + maxCharsPerLine() - 1) / maxCharsPerLine());

    m_scrollOffsetY = qMax(0, lastRow + wrapped - linesPerPage());
    if (isVisible())
      Q_EMIT scrollOffsetYChanged();
  }

  m_stateChanged = true;
  return true;
}

void API::ProcessLauncher::reapAsync(QProcess* process)
{
  if (!process)
    return;

  connect(process, &QProcess::finished, process, &QObject::deleteLater);
  process->terminate();

  QPointer<QProcess> guard(process);
  QTimer::singleShot(kTerminateGraceMs, process, [guard] {
    if (guard && guard->state() != QProcess::NotRunning)
      guard->kill();
  });
}

static int batchDatasetUidAt(const std::vector<Group>& groups, int gid, int did)
{
  if (gid < 0 || static_cast<size_t>(gid) >= groups.size())
    return -1;

  const auto& datasets = groups[gid].datasets;
  return (did >= 0 && static_cast<size_t>(did) < datasets.size()) ? datasets[did].uniqueId : -1;
}

static int batchResolveGroupId(const std::vector<Group>& groups, int groupUid, int staleGid)
{
  if (groupUid < 0)
    return staleGid;

  for (const auto& group : groups)
    if (group.uniqueId == groupUid)
      return group.groupId;

  return -1;
}

static int batchResolveDatasetId(const std::vector<Group>& groups,
                                 int gid,
                                 int datasetUid,
                                 int staleDid)
{
  if (datasetUid < 0)
    return staleDid;

  if (gid < 0 || static_cast<size_t>(gid) >= groups.size())
    return -1;

  const auto& datasets = groups[gid].datasets;
  for (size_t d = 0; d < datasets.size(); ++d)
    if (datasets[d].uniqueId == datasetUid)
      return static_cast<int>(d);

  return -1;
}

void DataModel::FrameParser::reloadSourceCode(int sourceId)
{
  if (sourceId < 0)
    return;

  static auto& model  = ProjectModel::instance();
  const auto& sources = model.sources();

  const DataModel::Source* target = nullptr;
  for (const auto& src : sources)
    if (src.sourceId == sourceId) {
      target = &src;
      break;
    }

  if (!target) {
    const auto it = m_engines.find(sourceId);
    if (it != m_engines.end()) {
      m_engines.erase(it);
      refreshEngineCaches();
    }

    Q_EMIT modifiedChanged();
    return;
  }

  const bool suppress  = m_suppressMessageBoxes || model.suppressMessageBoxes();
  const QString script = scriptForSource(*target);
  if (!script.isEmpty())
    (void)loadScript(sourceId, script, sourceId == 0 && !suppress);

  Q_EMIT modifiedChanged();
}

bool DataModel::JsWatchdog::finishCall(qint64 startNs) noexcept
{
  disarm();

  if (!m_engine->isInterrupted()) [[likely]]
    return false;

  m_engine->setInterrupted(false);

  const qint64 elapsedNs = steadyNowNs() - startNs;
  if (elapsedNs < qint64(m_budgetMs) * 1000000)
    return false;

  qWarning().noquote() << "[JsWatchdog]" << (m_tag.isEmpty() ? QStringLiteral("script") : m_tag)
                       << "timed out after" << m_budgetMs << "ms -- interrupted";
  return true;
}

[[nodiscard]] static int expect(const QString& name, bool condition)
{
  if (condition) {
    qInfo().noquote() << "  PASS" << name;
    return 0;
  }

  qCritical().noquote() << "  FAIL" << name;
  return 1;
}

[[nodiscard]] static int runGuardTableChecks()
{
  int fails         = 0;
  const auto& table = Licensing::Guards::guardTable();
  for (std::size_t i = 0; i < table.size(); ++i)
    fails += expect(QStringLiteral("guard %1 passes").arg(i), table[i]());

  return fails;
}

[[nodiscard]] static int runDispatchChecks()
{
  bool ok           = true;
  const auto& table = Licensing::Guards::guardTable();
  const auto sites  = static_cast<unsigned int>(table.size() * 2);
  for (unsigned int site = 0; site < sites; ++site)
    ok = Licensing::Guards::runGuard(site) && ok;

  return expect(QStringLiteral("runGuard() dispatch passes for %1 sites").arg(sites), ok);
}

[[nodiscard]] static int runGateChainChecks()
{
  const auto previous = Licensing::CommercialToken::current();

  Licensing::CommercialToken token;
  token.setFeatureTier(Licensing::FeatureTier::Trial);
  token.setVariantName(QStringLiteral("Guard Self-Test"));
  token.setInstanceName(QStringLiteral("validate-guards"));
  token.setGraceDaysRemaining(0);
  token.seal();
  Licensing::CommercialToken::setCurrent(token);

  int fails  = 0;
  fails     += expect(QStringLiteral("synthetic trial token validates"),
                  Licensing::CommercialToken::current().isValid());
  fails += expect(QStringLiteral("activated() opens with trial token"), SerialStudio::activated());
  fails += expect(QStringLiteral("proWidgetsEnabled() opens with trial token"),
                  SerialStudio::proWidgetsEnabled());
  fails += expect(QStringLiteral("datasetXAxisEnabled() opens with trial token"),
                  SerialStudio::datasetXAxisEnabled());

  auto tampered = token;
  tampered.setFeatureTier(Licensing::FeatureTier::Enterprise);
  Licensing::CommercialToken::setCurrent(tampered);
  fails += expect(QStringLiteral("tier mutated after seal() is rejected"),
                  !SerialStudio::activated() && !SerialStudio::proWidgetsEnabled());

  Licensing::CommercialToken::clearCurrent();
  fails += expect(QStringLiteral("cleared token closes all gates"),
                  !SerialStudio::activated() && !SerialStudio::proWidgetsEnabled()
                    && !SerialStudio::datasetXAxisEnabled());

  Licensing::CommercialToken::setCurrent(previous);
  return fails;
}

int Licensing::runGuardSelfTest()
{
  qInfo().noquote() << "[validate-guards] verifying license guards in this binary";
  const int fails = runGuardTableChecks() + runDispatchChecks() + runGateChainChecks();

  if (fails == 0)
    qInfo().noquote() << "[validate-guards] all guard checks passed";
  else
    qCritical().noquote() << "[validate-guards]" << fails << "check(s) failed";

  return fails == 0 ? 0 : 1;
}

[[nodiscard]] static int guardedPcall(lua_State* L, int nargs, int nresults, int msgh) noexcept
{
  try {
    return lua_pcall(L, nargs, nresults, msgh);
  } catch (...) {
    qWarning() << "[PublisherScript] Uncaught C++ exception escaped lua_pcall -- "
                  "treating as LUA_ERRRUN. Check Lua build unwind tables.";
    try {
      lua_settop(L, 0);
      lua_pushstring(L, "uncaught Lua exception (escaped lua_pcall)");
    } catch (...) {
    }
    return LUA_ERRRUN;
  }
}

static int luaPanicHandler(lua_State* L)
{
  const char* msg = lua_tostring(L, -1);
  qWarning() << "[PublisherScript] Lua panic:" << (msg ? msg : "<unknown>");
  throw std::runtime_error(msg ? msg : "lua panic");
}

