void DataModel::installLuaRestrictedOs(lua_State* L)
{
  Q_ASSERT(L != nullptr);

  static const char* const kSafeOsFields[] = {"time", "date", "clock", "difftime"};

  luaL_requiref(L, "os", luaopen_os, 0);
  Q_ASSERT(lua_istable(L, -1));

  lua_createtable(L, 0, 4);
  for (const char* name : kSafeOsFields) {
    lua_getfield(L, -2, name);
    lua_setfield(L, -2, name);
  }

  lua_setglobal(L, "os");
  lua_pop(L, 1);
}

QString IO::Drivers::USB::enrichDeviceLabel(libusb_device* dev,
                                            const libusb_device_descriptor& desc,
                                            const QString& base) const
{
  Q_ASSERT(dev != nullptr);
  Q_ASSERT(m_ctx != nullptr);

  QString label             = base;
  libusb_device_handle* tmp = nullptr;
  if (libusb_open(dev, &tmp) != 0)
    return label;

  const auto fetchStr = [tmp](uint8_t idx) -> QString {
    if (!idx)
      return {};

    unsigned char buf[256] = {};
    const int rc = libusb_get_string_descriptor_ascii(tmp, idx, buf, static_cast<int>(sizeof(buf)));

    if (rc > 0)
      return QString::fromLatin1(reinterpret_cast<const char*>(buf), rc).trimmed();

    return {};
  };

  const QString mfr  = fetchStr(desc.iManufacturer);
  const QString prod = fetchStr(desc.iProduct);

  // code-verify off
  if (!mfr.isEmpty() || !prod.isEmpty())
    label += QStringLiteral(" – %1 %2").arg(mfr, prod).trimmed();
  // code-verify on

  libusb_close(tmp);
  return label;
}

static QStandardItem* findMappedItem(const Map& map, Pred&& pred)
{
  for (auto it = map.begin(); it != map.end(); ++it)
    if (pred(it.value()))
      return it.key();

  return nullptr;
}

QStandardItem* DataModel::ProjectEditor::containerSelectionItem() const
{
    return m_tablesRootItem;
    return m_systemDatasetsItem;
    auto* item = findMappedItem(m_userTableItems, [&name](const auto& v) { return v == name; });
    return item ? item : m_tablesRootItem;
    return m_workspacesRootItem;
    auto* item    = findMappedItem(m_workspaceItems, [wid](const auto& v) { return v == wid; });
    return item ? item : m_workspacesRootItem;
    return m_groupsRootItem;
    auto* item    = findMappedItem(m_groupFolderItems, [fid](const auto& v) { return v == fid; });
    return item ? item : m_groupsRootItem;
    auto* item    = findMappedItem(m_tableFolderItems, [fid](const auto& v) { return v == fid; });
    return item ? item : m_tablesRootItem;
    auto* item = findMappedItem(m_workspaceFolderItems, [fid](const auto& v) { return v == fid; });
    return item ? item : m_workspacesRootItem;
  if (m_currentView == MqttPublisherView)
    return m_mqttPublisherItem;
  if (m_currentView == ControlScriptView)
    return m_controlScriptItem;
  return nullptr;
}

