API::CommandResponse API::Handlers::ProjectHandler::parserSetTemplate(const QString& id,
                                                                      const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("template")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: template"));

  const int sourceId  = params.contains(Keys::SourceId) ? params.value(Keys::SourceId).toInt() : 0;
  const auto& sources = DataModel::ProjectModel::instance().sources();
  const auto it =
    std::find_if(sources.begin(), sources.end(), [sourceId](const DataModel::Source& s) {
      return s.sourceId == sourceId;
    });

  if (it == sources.end())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Unknown sourceId"));

  const QString template_id  = params.value(QStringLiteral("template")).toString();
  const auto template_params = params.value(QStringLiteral("params")).toObject();

  QString error;
  if (!validateNativeTemplate(template_id, template_params, error))
    return CommandResponse::makeError(id, ErrorCode::InvalidParam, error);

  applyNativeTemplate(sourceId, template_id, template_params);

  const auto& model = DataModel::ProjectModel::instance();
  QJsonObject result;
  result[Keys::SourceId]             = sourceId;
  result[QStringLiteral("language")] = static_cast<int>(SerialStudio::Native);
  result[QStringLiteral("template")] = template_id;
  result[QStringLiteral("params")]   = model.frameParserParams(sourceId);
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::frameParserConfigure(const QString& id,
                                                                         const QJsonObject& params)
{
  auto& model   = DataModel::ProjectModel::instance();
  auto& manager = IO::ConnectionManager::instance();
  bool updated  = false;

  const int sourceId = params.contains(Keys::SourceId) ? params.value(Keys::SourceId).toInt() : 0;
  const int srcCount = static_cast<int>(model.sources().size());

  if (sourceId < 0 || (!model.sources().empty() && sourceId >= srcCount))
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Invalid sourceId"));

  if (params.contains(QStringLiteral("operationMode"))) {
    const int modeIdx = params.value(QStringLiteral("operationMode")).toInt();
    if (modeIdx >= 0 && modeIdx <= 2) {
      AppState::instance().setOperationMode(static_cast<SerialStudio::OperationMode>(modeIdx));
      updated = true;
    }
  }

  if (sourceId == 0) {
    if (params.contains(QStringLiteral("startSequence"))) {
      const QString start = params.value(QStringLiteral("startSequence")).toString();
      manager.setStartSequence(start.toUtf8());
      model.setFrameStartSequence(start);
      updated = true;
    }

    if (params.contains(QStringLiteral("endSequence"))) {
      const QString end = params.value(QStringLiteral("endSequence")).toString();
      manager.setFinishSequence(end.toUtf8());
      model.setFrameEndSequence(end);
      updated = true;
    }

    if (params.contains(Keys::ChecksumAlgorithm)) {
      const QString checksumName = params.value(Keys::ChecksumAlgorithm).toString();
      manager.setChecksumAlgorithm(checksumName);
      model.setChecksumAlgorithm(checksumName);
      updated = true;
    }

    if (params.contains(Keys::FrameDetection)) {
      const int detectionIdx = params.value(Keys::FrameDetection).toInt();
      if (detectionIdx >= 0 && detectionIdx <= 3) {
        model.setFrameDetection(static_cast<SerialStudio::FrameDetection>(detectionIdx));
        updated = true;
      }
    }
  } else {
    DataModel::Source src = model.sources()[sourceId];

    if (params.contains(QStringLiteral("startSequence"))) {
      src.frameStart = params.value(QStringLiteral("startSequence")).toString();
      updated        = true;
    }

    if (params.contains(QStringLiteral("endSequence"))) {
      src.frameEnd = params.value(QStringLiteral("endSequence")).toString();
      updated      = true;
    }

    if (params.contains(Keys::ChecksumAlgorithm)) {
      src.checksumAlgorithm = params.value(Keys::ChecksumAlgorithm).toString();
      updated               = true;
    }

    if (params.contains(Keys::FrameDetection)) {
      const int detectionIdx = params.value(Keys::FrameDetection).toInt();
      if (detectionIdx >= 0 && detectionIdx <= 3) {
        src.frameDetection = detectionIdx;
        updated            = true;
      }
    }

    if (updated)
      model.updateSource(sourceId, src);
  }

  if (updated && sourceId == 0)
    manager.resetFrameReader();

  QJsonObject result;
  result[QStringLiteral("updated")] = updated;
  result[Keys::SourceId]            = sourceId;
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::frameParserGetConfig(const QString& id,
                                                                         const QJsonObject& params)
{
  Q_UNUSED(params)

  const auto& cfg = AppState::instance().frameConfig();

  QJsonArray startArr, endArr;
  for (const auto& s : cfg.startSequences)
    startArr.append(QString::fromUtf8(s));

  for (const auto& f : cfg.finishSequences)
    endArr.append(QString::fromUtf8(f));

  const QString primaryStart =
    cfg.startSequences.isEmpty() ? QString() : QString::fromUtf8(cfg.startSequences.first());
  const QString primaryEnd =
    cfg.finishSequences.isEmpty() ? QString() : QString::fromUtf8(cfg.finishSequences.first());

  QJsonObject result;
  result[QStringLiteral("startSequence")]  = primaryStart;
  result[QStringLiteral("endSequence")]    = primaryEnd;
  result[QStringLiteral("startSequences")] = startArr;
  result[QStringLiteral("endSequences")]   = endArr;
  result[Keys::ChecksumAlgorithm]          = cfg.checksumAlgorithm;
  result[QStringLiteral("operationMode")]  = static_cast<int>(cfg.operationMode);
  result[Keys::FrameDetection]             = static_cast<int>(cfg.frameDetection);

  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::painterSetCode(const QString& id,
                                                                   const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("groupId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: groupId"));

  if (!params.contains(QStringLiteral("code")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: code"));

  const int groupId  = params.value(QStringLiteral("groupId")).toInt();
  const QString code = params.value(QStringLiteral("code")).toString();
  auto& project      = DataModel::ProjectModel::instance();
  const auto& groups = project.groups();

  if (groupId < 0 || static_cast<size_t>(groupId) >= groups.size())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  DataModel::Group g = groups[groupId];
  g.painterCode      = code;
  project.updateGroup(groupId, g, true);

  QJsonObject result;
  result[QStringLiteral("groupId")]    = groupId;
  result[QStringLiteral("codeLength")] = code.size();
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::painterGetCode(const QString& id,
                                                                   const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("groupId")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: groupId"));

  const int groupId  = params.value(QStringLiteral("groupId")).toInt();
  const auto& groups = DataModel::ProjectModel::instance().groups();
  if (groupId < 0 || static_cast<size_t>(groupId) >= groups.size())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Group id not found: %1").arg(groupId));

  QJsonObject result;
  result[QStringLiteral("groupId")] = groupId;
  result[QStringLiteral("code")]    = groups[groupId].painterCode;
  return CommandResponse::makeSuccess(id, result);
}

static std::unique_ptr<DataModel::IScriptEngine> makeScriptEngine(int language)
{
  if (language == SerialStudio::Native)
    return std::make_unique<DataModel::CFrameParser>();

  if (language == SerialStudio::Lua)
    return std::make_unique<DataModel::LuaScriptEngine>();

  return std::make_unique<DataModel::JsScriptEngine>();
}

static QByteArray dryRunDelimiter(const QJsonObject& params, const QString& key, bool hex)
{
  const auto raw = params.value(key).toString();
  if (raw.isEmpty())
    return {};

  if (hex) {
    const auto resolved = SerialStudio::resolveEscapeSequences(raw);
    return QByteArray::fromHex(QString(resolved).remove(' ').toUtf8());
  }

  return SerialStudio::resolveEscapeSequences(raw).toUtf8();
}

static QByteArray dryRunInputBytes(const QJsonObject& params)
{
  const auto hex = params.value(QStringLiteral("inputBytesHex")).toString();
  if (!hex.trimmed().isEmpty())
    return SerialStudio::hexToBytes(hex);

  return params.value(QStringLiteral("inputBytes")).toString().toUtf8();
}

static QJsonObject dryRunSerializeFrame(const DataModel::PipelineFrame& frame)
{
  QJsonArray rows;
  for (const auto& row : frame.rows) {
    QJsonArray cells;
    for (const auto& cell : row)
      cells.append(cell);

    rows.append(cells);
  }

  QJsonObject obj;
  obj[QStringLiteral("rawHex")]          = QString::fromLatin1(frame.rawBytes.toHex(' '));
  obj[QStringLiteral("rawByteCount")]    = static_cast<int>(frame.rawBytes.size());
  obj[QStringLiteral("decoderOutput")]   = frame.decoderOutput;
  obj[QStringLiteral("decoderIsBinary")] = frame.decoderProducedBinary;
  obj[QStringLiteral("rows")]            = rows;
  obj[QStringLiteral("rowCount")]        = rows.size();
  return obj;
}

API::CommandResponse API::Handlers::ProjectHandler::frameParserDryRun(const QString& id,
                                                                      const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("code")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: code"));

  if (!params.contains(QStringLiteral("language")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: language"));

  if (!params.contains(QStringLiteral("inputBytes"))
      && !params.contains(QStringLiteral("inputBytesHex")))
    return CommandResponse::makeError(
      id,
      ErrorCode::MissingParam,
      QStringLiteral("Missing required parameter: inputBytesHex (preferred, binary-safe) or "
                     "inputBytes (UTF-8 text)."));

  const auto bytes = dryRunInputBytes(params);
  if (bytes.isEmpty())
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("inputBytes / inputBytesHex were provided but decoded to zero bytes. "
                     "Pass the raw stream in exactly one of them: inputBytesHex as hex digits "
                     "(e.g. '61 2C 62') or inputBytes as UTF-8 text. Empty strings count as "
                     "absent."));

  const auto code     = params.value(QStringLiteral("code")).toString();
  const auto language = params.value(QStringLiteral("language")).toInt();

  DataModel::PipelineSpec spec;
  spec.operationMode = static_cast<SerialStudio::OperationMode>(
    params.value(QStringLiteral("operationMode")).toInt(int(SerialStudio::ProjectFile)));
  spec.frameDetection = static_cast<SerialStudio::FrameDetection>(
    params.value(Keys::FrameDetection).toInt(int(SerialStudio::EndDelimiterOnly)));
  spec.decoderMethod = static_cast<SerialStudio::DecoderMethod>(
    params.value(Keys::DecoderMethod).toInt(int(SerialStudio::PlainText)));
  spec.checksumAlgorithm = params.value(Keys::ChecksumAlgorithm).toString();

  const bool hexDelims = params.value(Keys::HexadecimalDelimiters).toBool(false);
  const auto start     = dryRunDelimiter(params, QString(Keys::FrameStart), hexDelims);
  const auto end       = dryRunDelimiter(params, QString(Keys::FrameEnd), hexDelims);
  if (!start.isEmpty())
    spec.startSequences.append(start);

  if (!end.isEmpty())
    spec.finishSequences.append(end);

  if (spec.operationMode == SerialStudio::QuickPlot && spec.finishSequences.isEmpty()) {
    spec.finishSequences = {QByteArray("\n"), QByteArray("\r\n"), QByteArray("\r")};
    spec.frameDetection  = SerialStudio::EndDelimiterOnly;
  }

  const auto run = DataModel::runFrameParserPipelineWithCode(bytes, spec, code, language);
  if (!run.stageError.isEmpty()) {
    QString message = run.stageError;
    if (run.stageWhere == QStringLiteral("compile"))
      message += frameParserCompileHint(code, language);

    return CommandResponse::makeError(id, ErrorCode::ExecutionError, message);
  }

  QJsonArray frameResults;
  int totalRows = 0;
  for (const auto& f : run.frames) {
    frameResults.append(dryRunSerializeFrame(f));
    totalRows += f.rows.size();
  }

  QJsonObject result;
  result[QStringLiteral("ok")]             = true;
  result[QStringLiteral("frames")]         = frameResults;
  result[QStringLiteral("frameCount")]     = frameResults.size();
  result[QStringLiteral("extractedCount")] = run.extractedCount;
  result[QStringLiteral("consumedBytes")]  = static_cast<int>(run.consumedBytes);
  result[QStringLiteral("remainingBytes")] = static_cast<int>(run.remainingBytes);
  result[QStringLiteral("droppedFrames")]  = static_cast<qint64>(run.droppedFrames);
  result[QStringLiteral("totalRows")]      = totalRows;
  result[QStringLiteral("hint")]           = QStringLiteral(
    "Bytes flow through extraction (delimiters / detection) -> decoder method -> parser, the "
              "same path the live FrameBuilder uses. Pick the Binary decoder for non-text streams "
              "(COBS, Modbus, custom binary) -- PlainText / Hex / Base64 route through "
              "QString::fromUtf8 and mojibake non-ASCII bytes.");

  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::frameParserDryCompile(const QString& id,
                                                                          const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("code")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: code"));

  if (!params.contains(QStringLiteral("language")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: language"));

  const auto code     = params.value(QStringLiteral("code")).toString();
  const auto language = params.value(QStringLiteral("language")).toInt();

  if (language != SerialStudio::JavaScript && language != SerialStudio::Lua
      && language != SerialStudio::Native)
    return CommandResponse::makeError(
      id,
      ErrorCode::InvalidParam,
      QStringLiteral("Invalid language: must be 0 (JavaScript), 1 (Lua) or 2 (Built-In)"));

  auto engine   = makeScriptEngine(language);
  const bool ok = engine->loadScript(code, 0, false);

  QJsonObject result;
  result[QStringLiteral("ok")] = ok;
  if (language == SerialStudio::Native)
    result[QStringLiteral("language")] = QStringLiteral("native");
  else
    result[QStringLiteral("language")] =
      (language == SerialStudio::Lua ? QStringLiteral("lua") : QStringLiteral("javascript"));

  if (!ok) {
    if (language == SerialStudio::Native)
      result[QStringLiteral("error")] = QStringLiteral(
        "Invalid native parser descriptor: expected {\"template\": id, \"params\": {...}} "
        "with a known template id and valid params.");
    else
      result[QStringLiteral("error")] =
        QStringLiteral("Compile failed or parse(frame) is not defined.");

    if (language != SerialStudio::Native) {
      const auto warning = detectLanguageMismatch(code, language);
      if (!warning.isEmpty())
        result[QStringLiteral("warning")] = warning;
    }
  }

  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::transformDryRun(const QString& id,
                                                                    const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("code")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: code"));

  if (!params.contains(QStringLiteral("language")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: language"));

  if (!params.contains(QStringLiteral("values")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: values"));

  const auto code     = params.value(QStringLiteral("code")).toString();
  const auto language = params.value(QStringLiteral("language")).toInt();
  const auto values   = params.value(QStringLiteral("values")).toArray();

  QString wrapped;
  if (language == 1) {
    wrapped = code
            + QStringLiteral("\n\nfunction parse(frame)\n"
                             "  local v = tonumber(frame)\n"
                             "  if v == nil then v = frame end\n"
                             "  local out = transform(v)\n"
                             "  return { tostring(out) }\n"
                             "end\n");
  } else {
    wrapped = code
            + QStringLiteral("\n\nfunction parse(frame) {\n"
                             "  var v = parseFloat(frame);\n"
                             "  if (isNaN(v)) v = frame;\n"
                             "  return [String(transform(v))];\n"
                             "}\n");
  }

  auto engine = makeScriptEngine(language);
  if (!engine->loadScript(wrapped, 0, false))
    return CommandResponse::makeError(
      id,
      ErrorCode::ExecutionError,
      QStringLiteral("Transform failed to compile or define transform(value)"));

  QJsonArray outputs;
  for (const auto& v : values) {
    QString sample;
    if (v.isDouble())
      sample = QString::number(SerialStudio::toDouble(v), 'g', 17);
    else
      sample = v.toString();

    const auto rows = engine->parseString(sample);
    if (rows.isEmpty() || rows.first().isEmpty()) {
      outputs.append(QJsonValue::Null);
      continue;
    }

    const auto cell = rows.first().first();
    bool isNum      = false;
    const auto num  = SerialStudio::toDouble(cell, &isNum);
    if (isNum)
      outputs.append(num);
    else
      outputs.append(cell);
  }

  QJsonObject result;
  result[QStringLiteral("ok")]      = true;
  result[QStringLiteral("outputs")] = outputs;
  result[QStringLiteral("hint")] =
    QStringLiteral("outputs[i] is the result of transform(values[i]). null means transform "
                   "returned a non-finite value -- the live runtime falls back to the raw "
                   "value in that case.");
  return CommandResponse::makeSuccess(id, result);
}

API::CommandResponse API::Handlers::ProjectHandler::painterDryRun(const QString& id,
                                                                  const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("code")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: code"));

  const auto code = params.value(QStringLiteral("code")).toString();

  QJSEngine engine;
  engine.installExtensions(QJSEngine::ConsoleExtension | QJSEngine::GarbageCollectionExtension);

  auto stub = engine.evaluate(
    QStringLiteral("var datasets = []; datasets.length = 0;"
                   "var group = { id: 0, title: '', columns: 0, sourceId: 0 };"
                   "var frame = { number: 0, timestampMs: 0 };"
                   "var theme = new Proxy({}, { get: function() { return '#000000'; } });"
                   "function tableGet() { return 0; }"
                   "function tableSet() {}"
                   "function datasetGetRaw() { return 0; }"
                   "function datasetGetFinal() { return 0; }"));
  if (stub.isError())
    return CommandResponse::makeError(id,
                                      ErrorCode::ExecutionError,
                                      QStringLiteral("Painter dry-run bootstrap failed: %1")
                                        .arg(stub.property(QStringLiteral("message")).toString()));

  const auto compiled = engine.evaluate(code, QStringLiteral("painter_dryrun.js"));
  if (compiled.isError()) {
    QJsonObject result;
    result[QStringLiteral("ok")] = false;
    result[QStringLiteral("compileError")] =
      compiled.property(QStringLiteral("message")).toString();
    result[QStringLiteral("line")] = compiled.property(QStringLiteral("lineNumber")).toInt();
    return CommandResponse::makeSuccess(id, result);
  }

  const auto paintFn = engine.globalObject().property(QStringLiteral("paint"));
  if (!paintFn.isCallable()) {
    QJsonObject result;
    result[QStringLiteral("ok")] = false;
    result[QStringLiteral("compileError")] =
      QStringLiteral("Script compiled but did not define paint(ctx, w, h). Painter scripts "
                     "MUST define `function paint(ctx, w, h)`. The function is named "
                     "`paint`, not `draw` or `render`.");
    return CommandResponse::makeSuccess(id, result);
  }

  const auto onFrameFn = engine.globalObject().property(QStringLiteral("onFrame"));
  QJsonObject result;
  result[QStringLiteral("ok")]         = true;
  result[QStringLiteral("hasPaint")]   = true;
  result[QStringLiteral("hasOnFrame")] = onFrameFn.isCallable();
  result[QStringLiteral("hint")] =
    QStringLiteral("Compile + paint() lookup succeeded. Note: dry-run does NOT actually "
                   "render -- runtime errors inside paint() (out-of-bounds reads, missing "
                   "moveTo before arc, etc.) only surface when the live widget mounts.");
  return CommandResponse::makeSuccess(id, result);
}

static QJsonObject runOutputWidgetSample(QJSEngine& engine,
                                         QJSValue& transmitFn,
                                         const QJsonValue& inputValue,
                                         bool hex)
{
  QJSValue jsValue;
  if (hex)
    jsValue =
      engine.toScriptValue(QString::fromLatin1(SerialStudio::hexToBytes(inputValue.toString())));
  else if (inputValue.isDouble())
    jsValue = engine.toScriptValue(SerialStudio::toDouble(inputValue));
  else {
    const auto text = inputValue.toString();
    bool numeric    = false;
    const auto num  = SerialStudio::toDouble(text, &numeric);
    jsValue         = numeric ? engine.toScriptValue(num) : engine.toScriptValue(text);
  }

  const auto called = transmitFn.call(QJSValueList{jsValue});
  QJsonObject out;
  if (called.isError()) {
    out[QStringLiteral("ok")]           = false;
    out[QStringLiteral("runtimeError")] = called.toString();
    out[QStringLiteral("line")]         = called.property(QStringLiteral("lineNumber")).toInt();
    return out;
  }

  const QByteArray payload =
    called.isString() ? called.toString().toLatin1() : called.toVariant().toByteArray();
  out[QStringLiteral("ok")]        = true;
  out[QStringLiteral("byteCount")] = payload.size();
  out[QStringLiteral("outputHex")] = QString::fromLatin1(payload.toHex(' ')).toUpper();
  return out;
}

API::CommandResponse API::Handlers::ProjectHandler::outputWidgetDryRun(const QString& id,
                                                                       const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("code")))
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: code"));

  const auto code = params.value(QStringLiteral("code")).toString();
  DataModel::FrameBuilder::instance().refreshTableStoreFromProjectModel();

  QJSEngine engine;
  engine.installExtensions(QJSEngine::ConsoleExtension | QJSEngine::GarbageCollectionExtension);
#ifdef BUILD_COMMERCIAL
  Widgets::Output::Base::installProtocolHelpers(engine);
#endif
  DataModel::FrameBuilder::instance().injectTableApiJS(&engine);

  const auto wrapped =
    QStringLiteral("(function() { %1\n"
                   "return typeof transmit === 'function' ? transmit : undefined; })()")
      .arg(code);
  auto transmitFn = engine.evaluate(wrapped, QStringLiteral("output_widget_dryrun.js"));
  if (transmitFn.isError()) {
    QJsonObject result;
    result[QStringLiteral("ok")] = false;
    result[QStringLiteral("compileError")] =
      transmitFn.property(QStringLiteral("message")).toString();
    result[QStringLiteral("line")] = transmitFn.property(QStringLiteral("lineNumber")).toInt();
    return CommandResponse::makeSuccess(id, result);
  }

  if (!transmitFn.isCallable()) {
    QJsonObject result;
    result[QStringLiteral("ok")] = false;
    result[QStringLiteral("compileError")] =
      QStringLiteral("Script compiled but did not define transmit(value). Output-widget "
                     "transmit scripts MUST define `function transmit(value)` returning the "
                     "bytes to send (a Uint8Array, a byte array, or a string). The function "
                     "is named `transmit`, not `output` or `send`.");
    return CommandResponse::makeSuccess(id, result);
  }

  QJsonObject result;
  result[QStringLiteral("ok")]          = true;
  result[QStringLiteral("hasTransmit")] = true;
  if (params.contains(QStringLiteral("inputValue")))
    result[QStringLiteral("sampleRun")] =
      runOutputWidgetSample(engine,
                            transmitFn,
                            params.value(QStringLiteral("inputValue")),
                            params.value(QStringLiteral("hex")).toBool());
  else
    result[QStringLiteral("hint")] =
      QStringLiteral("Compiled and transmit(value) is defined. Pass inputValue (and hex:true "
                     "for hex byte input) to also execute it and see the produced bytes.");

  return CommandResponse::makeSuccess(id, result);
}

static QJsonValue applyTransformForDryRun(
  const DataModel::Dataset& dataset,
  int defaultLanguage,
  const QString& rawCell,
  std::map<int, std::unique_ptr<DataModel::IScriptEngine>>& engines,
  std::map<int, bool>& engineOk)
{
  const int datasetKey = dataset.uniqueId;
  const int language =
    (dataset.transformLanguage == -1) ? defaultLanguage : dataset.transformLanguage;

  auto it = engines.find(datasetKey);
  if (it == engines.end()) {
    auto engine    = makeScriptEngine(language);
    const auto src = wrapTransformForParser(dataset.transformCode, language);
    const bool ok  = engine->loadScript(src, dataset.sourceId, false);

    engineOk[datasetKey] = ok;
    engines[datasetKey]  = std::move(engine);
    it                   = engines.find(datasetKey);
  }

  if (!engineOk[datasetKey])
    return QJsonValue::Null;

  const auto rows = it->second->parseString(rawCell);
  if (rows.isEmpty() || rows.first().isEmpty())
    return QJsonValue::Null;

  const auto cell = rows.first().first();
  bool isNum      = false;
  const auto num  = SerialStudio::toDouble(cell, &isNum);
  if (isNum)
    return num;

  return cell;
}

static QJsonObject buildDryRunDatasetEntry(
  const DataModel::Dataset& dataset,
  int groupId,
  const QStringList& row,
  int language,
  bool verbose,
  std::map<int, std::unique_ptr<DataModel::IScriptEngine>>& transformEngines,
  std::map<int, bool>& transformEngineOk)
{
  const int idx = dataset.index;
  QString rawCell;
  if (idx >= 1 && idx <= row.size())
    rawCell = row.at(idx - 1);

  QJsonObject entry;
  entry[Keys::UniqueId]              = dataset.uniqueId;
  entry[Keys::Title]                 = dataset.title;
  entry[Keys::GroupId]               = groupId;
  entry[Keys::DatasetId]             = dataset.datasetId;
  entry[Keys::Index]                 = idx;
  entry[QStringLiteral("isVirtual")] = dataset.virtual_;

  if (verbose)
    entry[QStringLiteral("raw")] = rawCell;

  if (!dataset.transformCode.isEmpty()) {
    entry[QStringLiteral("final")] =
      applyTransformForDryRun(dataset, language, rawCell, transformEngines, transformEngineOk);
    entry[QStringLiteral("transformApplied")] = true;
    return entry;
  }

  bool isNum                                = false;
  const auto num                            = SerialStudio::toDouble(rawCell, &isNum);
  entry[QStringLiteral("final")]            = isNum ? QJsonValue(num) : QJsonValue(rawCell);
  entry[QStringLiteral("transformApplied")] = false;
  return entry;
}

static QJsonObject buildDryRunRow(
  const QStringList& row,
  int sourceId,
  const std::vector<DataModel::Group>& groups,
  int language,
  bool verbose,
  std::map<int, std::unique_ptr<DataModel::IScriptEngine>>& transformEngines,
  std::map<int, bool>& transformEngineOk)
{
  QJsonArray datasetResults;
  for (const auto& group : groups) {
    for (const auto& dataset : group.datasets) {
      if (dataset.sourceId != sourceId)
        continue;

      datasetResults.append(buildDryRunDatasetEntry(
        dataset, group.groupId, row, language, verbose, transformEngines, transformEngineOk));
    }
  }

  QJsonArray rawCells;
  for (const auto& cell : row)
    rawCells.append(cell);

  QJsonObject rowOut;
  rowOut[QStringLiteral("rawCells")] = rawCells;
  rowOut[QStringLiteral("datasets")] = datasetResults;
  return rowOut;
}

API::CommandResponse API::Handlers::ProjectHandler::endToEndDryRun(const QString& id,
                                                                   const QJsonObject& params)
{
  auto& pm           = DataModel::ProjectModel::instance();
  const auto sources = pm.sources();
  const int sourceId = params.value(Keys::SourceId).toInt(0);
  if (sources.empty())
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Project has no sources to dry-run against"));

  if (sourceId < 0 || sourceId >= static_cast<int>(sources.size()))
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("Source id out of range: %1").arg(sourceId));

  const auto& source = sources[sourceId];

  const bool hasFrame  = params.contains(QStringLiteral("sampleFrame"));
  const bool hasFrames = params.contains(QStringLiteral("sampleFrames"));
  if (!hasFrame && !hasFrames)
    return CommandResponse::makeError(
      id,
      ErrorCode::MissingParam,
      QStringLiteral("Missing required parameter: sampleFrame (string) or sampleFrames (array)"));

  QStringList frames;
  if (hasFrames)
    for (const auto& v : params.value(QStringLiteral("sampleFrames")).toArray())
      frames.append(v.toString());
  else
    frames.append(params.value(QStringLiteral("sampleFrame")).toString());

  const bool verbose = params.value(QStringLiteral("verbose")).toBool(false);
  const QString code = params.contains(QStringLiteral("code"))
                       ? params.value(QStringLiteral("code")).toString()
                       : source.frameParserCode;
  const int language = params.contains(QStringLiteral("language"))
                       ? params.value(QStringLiteral("language")).toInt()
                       : source.frameParserLanguage;

  auto parser = makeScriptEngine(language);
  if (!parser->loadScript(code, sourceId, false))
    return CommandResponse::makeError(
      id,
      ErrorCode::ExecutionError,
      QStringLiteral("Frame parser failed to compile or define parse(frame).")
        + frameParserCompileHint(code, language));

  std::map<int, std::unique_ptr<DataModel::IScriptEngine>> transformEngines;
  std::map<int, bool> transformEngineOk;
  const auto& groups = pm.groups();

  QJsonArray frameResults;
  for (const auto& sample : frames) {
    const auto parsed = parser->parseString(sample);

    QJsonArray rowResults;
    for (const auto& row : parsed)
      rowResults.append(buildDryRunRow(
        row, sourceId, groups, language, verbose, transformEngines, transformEngineOk));

    QJsonObject perFrame;
    perFrame[QStringLiteral("rows")]     = rowResults;
    perFrame[QStringLiteral("rowCount")] = rowResults.size();
    frameResults.append(perFrame);
  }

  QJsonArray failedTransforms;
  for (const auto& [uid, ok] : transformEngineOk)
    if (!ok)
      failedTransforms.append(uid);

  QJsonObject result;
  result[QStringLiteral("ok")]         = true;
  result[Keys::SourceId]               = sourceId;
  result[QStringLiteral("frames")]     = frameResults;
  result[QStringLiteral("frameCount")] = frameResults.size();

  if (!failedTransforms.isEmpty()) {
    result[QStringLiteral("transformCompileFailures")] = failedTransforms;
    result[QStringLiteral("warning")] =
      QStringLiteral("One or more dataset transforms failed to compile. Their `final` "
                     "values are null. Iterate the failing transforms via "
                     "project.dataset.transform.dryRun, then setTransformCode.");
  }

  result[QStringLiteral("hint")] =
    QStringLiteral("rawCells[i] maps to dataset.index = i+1. The table API "
                   "(tableGet/tableSet/datasetGetRaw/datasetGetFinal) is NOT injected in "
                   "this dry-run -- transforms that read other datasets will see 0/null. "
                   "Virtual datasets show their transform applied to the raw cell at "
                   "their index (which is normally 0/unset for virtual entries).");
  return CommandResponse::makeSuccess(id, result);
}

void DataModel::ProjectEditor::handleSourceTitleChange(QStandardItem* item)
{
  const QString newTitle = item->data(EditableValue).toString();
  if (m_selectedSource.title == newTitle)
    return;

  m_selectedSource.title = newTitle;
  DataModel::ProjectModel::instance().updateSourceTitle(m_selectedSource.sourceId, newTitle, false);

  for (auto it = m_sourceItems.begin(); it != m_sourceItems.end(); ++it) {
    if (it.value().sourceId != m_selectedSource.sourceId)
      continue;

    auto* treeItem = it.key();
    treeItem->setText(newTitle);
    treeItem->setData(newTitle, TreeViewText);
    m_sourceItems[treeItem].title = newTitle;
    break;
  }

  Q_EMIT selectedTextChanged();
}

void DataModel::ProjectEditor::handleSourceBusTypeChange(QStandardItem* item)
{
  const int busType = item->data(EditableValue).toInt();
  DataModel::ProjectModel::instance().updateSourceBusType(m_selectedSource.sourceId, busType);
  m_selectedSource.busType = busType;
  auto conn                = std::make_shared<QMetaObject::Connection>();
  *conn                    = connect(
    &IO::ConnectionManager::instance(),
    &IO::ConnectionManager::contextsRebuilt,
    this,
    [this, conn] {
      disconnect(*conn);
      buildSourceModel(m_selectedSource);
    },
    Qt::QueuedConnection);
}

void DataModel::ProjectEditor::handleSourcePropertyChange(QStandardItem* item)
{
  const QString key  = item->data(ParameterKey).toString();
  const QVariant val = item->data(EditableValue);
  IO::HAL_Driver* drv =
    IO::ConnectionManager::instance().driverForEditing(m_selectedSource.sourceId);
  if (drv)
    drv->setDriverProperty(key, val);

  DataModel::ProjectModel::instance().captureSourceSettings(m_selectedSource.sourceId);

  static const QStringList kModeKeys = {
    QStringLiteral("socketTypeIndex"),
    QStringLiteral("protocolIndex"),
  };
  if (kModeKeys.contains(key))
    buildSourceModel(m_selectedSource);
}

void DataModel::ProjectEditor::onSourceItemChanged(QStandardItem* item)
{
  if (!item)
    return;

  const int id = item->data(ParameterType).toInt();

  if (id == kSourceView_Title) {
    handleSourceTitleChange(item);
    return;
  }

  if (id == kSourceView_BusType) {
    handleSourceBusTypeChange(item);
    return;
  }

  if (id == kSourceView_Property) {
    handleSourcePropertyChange(item);
    return;
  }

  DataModel::Source updated = m_selectedSource;
  switch (static_cast<SourceItem>(id)) {
    case kSourceView_FrameDetection:
    case kSourceView_HexadecimalSequence:
      handleSourceFrameDetectionChange(item, updated);
      break;
    case kSourceView_FrameStartSequence:
    case kSourceView_FrameEndSequence:
      handleSourceFrameStartEndChange(item, updated);
      break;
    case kSourceView_FrameDecoder:
    case kSourceView_ChecksumFunction:
      handleSourceDecoderChecksumChange(item, updated);
      break;
    default:
      break;
  }
}

void DataModel::ProjectEditor::handleSourceFrameDetectionChange(QStandardItem* item,
                                                                DataModel::Source& updated)
{
  const int id  = item->data(ParameterType).toInt();
  const int sid = m_selectedSource.sourceId;

  if (id == kSourceView_FrameDetection) {
    const int idx = item->data(EditableValue).toInt();
    if (idx < 0 || idx >= m_frameDetectionMethodsValues.size())
      return;

    updated.frameDetection = static_cast<int>(m_frameDetectionMethodsValues.at(idx));
  } else {
    updated.hexadecimalDelimiters = item->data(EditableValue).toBool();
  }

  DataModel::ProjectModel::instance().updateSource(sid, updated);
  m_selectedSource = updated;

  buildSourceModel(m_selectedSource);
}

void DataModel::ProjectEditor::handleSourceFrameStartEndChange(QStandardItem* item,
                                                               DataModel::Source& updated)
{
  const int id  = item->data(ParameterType).toInt();
  const int sid = m_selectedSource.sourceId;

  if (id == kSourceView_FrameStartSequence)
    updated.frameStart = item->data(EditableValue).toString();
  else
    updated.frameEnd = item->data(EditableValue).toString();

  DataModel::ProjectModel::instance().updateSource(sid, updated, false);
  m_selectedSource = updated;
}

void DataModel::ProjectEditor::handleSourceDecoderChecksumChange(QStandardItem* item,
                                                                 DataModel::Source& updated)
{
  const int id  = item->data(ParameterType).toInt();
  const int sid = m_selectedSource.sourceId;

  if (id == kSourceView_FrameDecoder) {
    updated.decoderMethod = item->data(EditableValue).toInt();
    DataModel::ProjectModel::instance().updateSource(sid, updated);
    m_selectedSource = updated;
    return;
  }

  const auto checksums = IO::availableChecksums();
  const int checksumId = item->data(EditableValue).toInt();
  if (checksumId < 0 || checksumId >= checksums.size())
    return;

  updated.checksumAlgorithm = checksums.at(checksumId);
  DataModel::ProjectModel::instance().updateSource(sid, updated);
  m_selectedSource = updated;
}

void DataModel::ProjectEditor::onGroupItemChanged(QStandardItem* item)
{
  if (!item)
    return;

  const auto id      = static_cast<GroupItem>(item->data(ParameterType).toInt());
  const auto value   = item->data(EditableValue);
  auto& pm           = DataModel::ProjectModel::instance();
  const auto groupId = m_selectedGroup.groupId;

  if (id == kGroupView_Title) {
    if (!applyGroupTitleEdit(value.toString(), groupId))
      return;

    Q_EMIT editableOptionsChanged();
    return;
  }

  if (id == kGroupView_Source) {
    applyGroupSourceEdit(value.toInt(), groupId);
    Q_EMIT editableOptionsChanged();
    return;
  }

  if (id == kGroupView_Widget) {
    if (!applyGroupWidgetEdit(value.toInt(), groupId))
      return;

    Q_EMIT editableOptionsChanged();
    return;
  }

  if (id == kGroupView_xAxis) {
    const int xAxisId = (value.toInt() == 1) ? kXAxisSamples : kXAxisTime;
    for (auto& dataset : m_selectedGroup.datasets)
      dataset.xAxisId = xAxisId;

    pm.updateGroup(groupId, m_selectedGroup);
    Q_EMIT editableOptionsChanged();
    return;
  }

  if (id == kGroupView_WebUrl) {
    m_selectedGroup.webViewUrl = value.toString();
    pm.updateGroup(groupId, m_selectedGroup, false);
    Q_EMIT editableOptionsChanged();
    return;
  }

#ifdef BUILD_COMMERCIAL
  if (id == kGroupView_ImgMode) {
    if (applyGroupImgModeEdit(value.toInt(), groupId))
      return;

    Q_EMIT editableOptionsChanged();
    return;
  }

  if (id == kGroupView_ImgStart) {
    m_selectedGroup.imgStartSequence = value.toString();
    pm.updateGroup(groupId, m_selectedGroup, false);
  }

  if (id == kGroupView_ImgEnd) {
    m_selectedGroup.imgEndSequence = value.toString();
    pm.updateGroup(groupId, m_selectedGroup, false);
  }
#endif

  Q_EMIT editableOptionsChanged();
}

bool DataModel::ProjectEditor::applyGroupTitleEdit(const QString& newTitle, int groupId)
{
  if (m_selectedGroup.title == newTitle)
    return false;

  m_selectedGroup.title = newTitle;
  DataModel::ProjectModel::instance().updateGroup(groupId, m_selectedGroup, false);

  for (auto it = m_groupItems.begin(); it != m_groupItems.end(); ++it) {
    if (it.value().groupId != groupId)
      continue;

    auto* treeItem = it.key();
    treeItem->setText(newTitle);
    treeItem->setData(newTitle, TreeViewText);
    m_groupItems[treeItem].title = newTitle;
    break;
  }

  Q_EMIT selectedTextChanged();
  return true;
}

void DataModel::ProjectEditor::applyGroupSourceEdit(int srcIdx, int groupId)
{
  const auto& sources = DataModel::ProjectModel::instance().sources();
  if (srcIdx < 0 || srcIdx >= static_cast<int>(sources.size()))
    return;

  m_selectedGroup.sourceId = sources[srcIdx].sourceId;
  for (auto& ds : m_selectedGroup.datasets)
    ds.sourceId = m_selectedGroup.sourceId;

  DataModel::ProjectModel::instance().updateGroup(groupId, m_selectedGroup, true);
}

bool DataModel::ProjectEditor::applyGroupWidgetEdit(int widgetIdx, int groupId)
{
  const auto keys = m_groupWidgets.keys();
  if (widgetIdx < 0 || widgetIdx >= keys.size())
    return false;

  const auto widgetStr = keys.at(widgetIdx);

  static const QMap<QString, SerialStudio::GroupWidget> kWidgetEnumMap = {
    {"accelerometer", SerialStudio::Accelerometer},
    {    "multiplot",     SerialStudio::MultiPlot},
    {         "gyro",     SerialStudio::Gyroscope},
    {          "map",           SerialStudio::GPS},
    {     "datagrid",      SerialStudio::DataGrid},
    {       "plot3d",        SerialStudio::Plot3D},
    {        "image",     SerialStudio::ImageView},
    {      "painter",       SerialStudio::Painter},
    {      "webview",       SerialStudio::WebView},
    {             "", SerialStudio::NoGroupWidget},
  };

  const auto widget = kWidgetEnumMap.value(widgetStr, SerialStudio::NoGroupWidget);
  if (DataModel::ProjectModel::instance().setGroupWidget(groupId, widget)) {
    m_selectedGroup.widget = widgetStr;
    return true;
  }

  QTimer::singleShot(0, this, [this, groupId] {
    buildTreeModel();
    for (auto g = m_groupItems.begin(); g != m_groupItems.end(); ++g) {
      if (g.value().groupId != groupId)
        continue;

      if (m_selectionModel)
        m_selectionModel->setCurrentIndex(g.key()->index(), QItemSelectionModel::ClearAndSelect);

      break;
    }
  });

  return false;
}

bool DataModel::ProjectEditor::applyGroupImgModeEdit(int modeIdx, int groupId)
{
  const QStringList kImgModeValues = {QStringLiteral("autodetect"), QStringLiteral("manual")};
  if (modeIdx < 0 || modeIdx >= kImgModeValues.size())
    return false;

  m_selectedGroup.imgDetectionMode = kImgModeValues.at(modeIdx);
  DataModel::ProjectModel::instance().updateGroup(groupId, m_selectedGroup);
  buildGroupModel(m_selectedGroup);
  return true;
}

void DataModel::ProjectEditor::onActionItemChanged(QStandardItem* item)
{
  if (!item)
    return;

  static QStringList eolKeys;
  if (eolKeys.isEmpty())
    for (auto i = m_eolSequences.begin(); i != m_eolSequences.end(); ++i)
      eolKeys.append(i.key());

  const auto id    = item->data(ParameterType);
  const auto value = item->data(EditableValue);

  switch (static_cast<ActionItem>(id.toInt())) {
    case kActionView_Title:
      m_selectedAction.title = value.toString();
      break;
    case kActionView_Data:
      m_selectedAction.txData = value.toString();
      break;
    case kActionView_EOL: {
      const int eolIdx = value.toInt();
      if (eolIdx < 0 || eolIdx >= eolKeys.size())
        return;

      m_selectedAction.eolSequence = eolKeys.at(eolIdx);
      break;
    }
    case kActionView_Icon:
      m_selectedAction.icon = value.toString();
      Q_EMIT actionModelChanged();
      break;
    case kActionView_Binary:
      m_selectedAction.binaryData = value.toBool();
      buildActionModel(m_selectedAction);
      break;
    case kActionView_TxEncoding:
      m_selectedAction.txEncoding = value.toInt();
      break;
    case kActionView_SourceId: {
      const auto& sources = DataModel::ProjectModel::instance().sources();
      const int srcIdx    = value.toInt();
      if (srcIdx >= 0 && srcIdx < static_cast<int>(sources.size()))
        m_selectedAction.sourceId = sources[srcIdx].sourceId;

      break;
    }
    case kActionView_AutoExecute:
      m_selectedAction.autoExecuteOnConnect = value.toBool();
      break;
    case kActionView_TimerMode:
      m_selectedAction.timerMode = static_cast<DataModel::TimerMode>(value.toInt());
      buildActionModel(m_selectedAction);
      break;
    case kActionView_TimerInterval:
      m_selectedAction.timerIntervalMs = value.toInt();
      break;
    case kActionView_RepeatCount:
      m_selectedAction.repeatCount = qMax(1, value.toInt());
      break;
    default:
      break;
  }

  auto& pm            = DataModel::ProjectModel::instance();
  const auto actionId = m_selectedAction.actionId;
  pm.setSelectedAction(m_selectedAction);
  pm.updateAction(actionId, m_selectedAction, false);

  if (static_cast<ActionItem>(id.toInt()) == kActionView_Title) {
    const auto newTitle = value.toString();
    for (auto it = m_actionItems.begin(); it != m_actionItems.end(); ++it) {
      if (it.value().actionId != actionId)
        continue;

      auto* treeItem = it.key();
      treeItem->setText(newTitle);
      treeItem->setData(newTitle, TreeViewText);
      m_actionItems[treeItem].title = newTitle;
      break;
    }

    Q_EMIT selectedTextChanged();
  } else {
    for (auto it = m_actionItems.begin(); it != m_actionItems.end(); ++it) {
      if (it.value().actionId == actionId) {
        m_actionItems[it.key()] = m_selectedAction;
        break;
      }
    }
  }
}

void DataModel::ProjectEditor::onProjectItemChanged(QStandardItem* item)
{
  if (!item)
    return;

  const auto id    = item->data(ParameterType);
  const auto value = item->data(EditableValue);
  auto& pm         = DataModel::ProjectModel::instance();

  switch (static_cast<ProjectItem>(id.toInt())) {
    case kProjectView_Title:
      pm.setTitle(value.toString());
      break;
    default:
      break;
  }

  pm.setModified(true);
}

void DataModel::ProjectEditor::onDatasetCommonItemChanged(QStandardItem* item,
                                                          DataModel::Dataset& dataset)
{
  const auto id    = static_cast<DatasetItem>(item->data(ParameterType).toInt());
  const auto value = item->data(EditableValue);

  switch (id) {
    case kDatasetView_Title:
      dataset.title = value.toString();
      break;
    case kDatasetView_Index:
      dataset.index = value.toInt();
      break;
    case kDatasetView_Units:
      dataset.units = value.toString();
      break;
    case kDatasetView_TransformCode:
      dataset.transformCode = value.toString();
      break;
    default:
      break;
  }
}

void DataModel::ProjectEditor::onDatasetWidgetItemChanged(QStandardItem* item,
                                                          DataModel::Dataset& dataset)
{
  static QStringList datasetWidgetKeys;
  static QList<QPair<bool, bool>> plotOptionKeys;

  if (datasetWidgetKeys.isEmpty())
    for (auto i = m_datasetWidgets.begin(); i != m_datasetWidgets.end(); ++i)
      datasetWidgetKeys.append(i.key());

  if (plotOptionKeys.isEmpty())
    for (auto i = m_plotOptions.begin(); i != m_plotOptions.end(); ++i)
      plotOptionKeys.append(i.key());

  const auto id    = static_cast<DatasetItem>(item->data(ParameterType).toInt());
  const auto value = item->data(EditableValue);

  if (id == kDatasetView_Widget) {
    const int widgetIdx = value.toInt();
    if (widgetIdx < 0 || widgetIdx >= datasetWidgetKeys.size())
      return;

    dataset.widget = datasetWidgetKeys.at(widgetIdx);
    if (dataset.widget == "compass") {
      dataset.wgtMin = 0;
      dataset.wgtMax = 360;
      dataset.alarmBands.clear();
    }

    if (!m_batchApplying)
      buildDatasetModel(dataset);

    return;
  }

  if (id == kDatasetView_Plot) {
    const int plotIdx = value.toInt();
    if (plotIdx < 0 || plotIdx >= plotOptionKeys.size())
      return;

    dataset.plt = plotOptionKeys.at(plotIdx).first;
    dataset.log = plotOptionKeys.at(plotIdx).second;
    if (!m_batchApplying)
      buildDatasetModel(dataset);

    return;
  }

  if (id == kDatasetView_DisplayFormat) {
    static QStringList formatKeys;
    if (formatKeys.isEmpty())
      for (auto i = m_displayFormats.begin(); i != m_displayFormats.end(); ++i)
        formatKeys.append(i.key());

    const int formatIdx = value.toInt();
    if (formatIdx < 0 || formatIdx >= formatKeys.size())
      return;

    dataset.displayFormat = formatKeys.at(formatIdx);
    return;
  }

  if (id == kDatasetView_Virtual) {
    dataset.virtual_ = value.toBool();

    for (auto it = m_datasetItems.begin(); it != m_datasetItems.end(); ++it) {
      if (it.value().groupId == dataset.groupId && it.value().datasetId == dataset.datasetId) {
        it.key()->setData(dataset.virtual_, TreeViewVirtual);
        break;
      }
    }

    if (m_batchApplying)
      return;

    const int uid = dataset.uniqueId;
    QTimer::singleShot(0, this, [this, uid] {
      if (m_selectedDataset.uniqueId == uid)
        buildDatasetModel(m_selectedDataset);
    });
  }
}

void DataModel::ProjectEditor::onDatasetRangeItemChanged(QStandardItem* item,
                                                         DataModel::Dataset& dataset)
{
  const auto id    = static_cast<DatasetItem>(item->data(ParameterType).toInt());
  const auto value = item->data(EditableValue);

  switch (id) {
    case kDatasetView_xAxis: {
      const auto xUids = DataModel::ProjectModel::instance().xDataSourceUniqueIds();
      const int pos    = value.toInt();
      dataset.xAxisId  = (pos >= 0 && pos < xUids.size()) ? xUids.at(pos) : kXAxisTime;
      break;
    }
    case kDatasetView_PltMin:
      dataset.pltMin = SerialStudio::toDouble(value);
      break;
    case kDatasetView_PltMax:
      dataset.pltMax = SerialStudio::toDouble(value);
      break;
    case kDatasetView_WgtMin:
      dataset.wgtMin = SerialStudio::toDouble(value);
      break;
    case kDatasetView_WgtMax:
      dataset.wgtMax = SerialStudio::toDouble(value);
      break;
    case kDatasetView_DisplayTickCount:
      dataset.displayTickCount = qMax(0, value.toInt());
      break;
    case kDatasetView_DecimalPoints:
      dataset.decimalPoints = qMax(-1, value.toInt());
      break;
    default:
      break;
  }
}

void DataModel::ProjectEditor::onDatasetFftItemChanged(QStandardItem* item,
                                                       DataModel::Dataset& dataset)
{
  const auto id    = static_cast<DatasetItem>(item->data(ParameterType).toInt());
  const auto value = item->data(EditableValue);

  switch (id) {
    case kDatasetView_FFTMin:
      dataset.fftMin = SerialStudio::toDouble(value);
      break;
    case kDatasetView_FFTMax:
      dataset.fftMax = SerialStudio::toDouble(value);
      break;
    case kDatasetView_WaterfallYAxis: {
      const auto yUids       = DataModel::ProjectModel::instance().yWaterfallSourceUniqueIds();
      const int pos          = value.toInt();
      dataset.waterfallYAxis = (pos >= 0 && pos < yUids.size()) ? yUids.at(pos) : 0;
      break;
    }
    case kDatasetView_FFT_Samples: {
      const int sampleIdx = value.toInt();
      if (sampleIdx < 0 || sampleIdx >= m_fftSamples.size())
        return;

      dataset.fftSamples = m_fftSamples.at(sampleIdx).toInt();
      break;
    }
    case kDatasetView_FFT_SamplingRate:
      dataset.fftSamplingRate = value.toInt();
      break;
    default:
      break;
  }
}

void DataModel::ProjectEditor::onDatasetFlagItemChanged(QStandardItem* item,
                                                        DataModel::Dataset& dataset)
{
  const auto id    = static_cast<DatasetItem>(item->data(ParameterType).toInt());
  const auto value = item->data(EditableValue);

  bool reshape = false;
  switch (id) {
    case kDatasetView_FFT:
      dataset.fft = value.toBool();
      reshape     = true;
      break;
    case kDatasetView_Waterfall:
      dataset.waterfall = value.toBool();
      reshape           = true;
      break;
    case kDatasetView_LED:
      dataset.led = value.toBool();
      reshape     = true;
      break;
    case kDatasetView_LED_High:
      dataset.ledHigh = SerialStudio::toDouble(value);
      break;
    case kDatasetView_HideOnDashboard:
      dataset.hideOnDashboard = value.toBool();
      break;
    default:
      break;
  }

  if (reshape && !m_batchApplying)
    buildDatasetModel(dataset);
}

void DataModel::ProjectEditor::commitAlarmBands(const QVariantList& bands)
{
  m_selectedDataset.alarmBands.clear();
  m_selectedDataset.alarmBands.reserve(bands.size());
  for (const auto& v : bands) {
    const auto m = v.toMap();
    DataModel::AlarmBand band;
    band.min   = SerialStudio::toDouble(m.value(QStringLiteral("min")));
    band.max   = SerialStudio::toDouble(m.value(QStringLiteral("max")));
    band.blink = m.value(QStringLiteral("blink"), false).toBool();
    band.color = m.value(QStringLiteral("color")).toString().simplified();
    band.label = m.value(QStringLiteral("label")).toString().simplified();
    const int sev =
      m.value(QStringLiteral("severity"), static_cast<int>(DataModel::AlarmSeverity::Warning))
        .toInt();
    band.severity = static_cast<DataModel::AlarmSeverity>(qBound(0, sev, 3));
    if (band.max > band.min)
      m_selectedDataset.alarmBands.push_back(std::move(band));
  }

  auto& pm = DataModel::ProjectModel::instance();
  pm.updateDataset(
    m_selectedDataset.groupId, m_selectedDataset.datasetId, m_selectedDataset, false);
  buildDatasetModel(m_selectedDataset);
}

void DataModel::ProjectEditor::onDatasetItemChanged(QStandardItem* item)
{
  if (!item)
    return;

  const auto idInt = static_cast<DatasetItem>(item->data(ParameterType).toInt());
  const auto value = item->data(EditableValue);

  if (idInt == kDatasetView_Widget) {
    const int widgetIdx = value.toInt();
    if (widgetIdx < 0 || widgetIdx >= m_datasetWidgets.size())
      return;
  }
  if (idInt == kDatasetView_Plot) {
    const int plotIdx = value.toInt();
    if (plotIdx < 0 || plotIdx >= m_plotOptions.size())
      return;
  }
  if (idInt == kDatasetView_FFT_Samples) {
    const int sampleIdx = value.toInt();
    if (sampleIdx < 0 || sampleIdx >= m_fftSamples.size())
      return;
  }

  onDatasetCommonItemChanged(item, m_selectedDataset);
  onDatasetWidgetItemChanged(item, m_selectedDataset);
  onDatasetRangeItemChanged(item, m_selectedDataset);
  onDatasetFftItemChanged(item, m_selectedDataset);
  onDatasetFlagItemChanged(item, m_selectedDataset);

  auto& pm             = DataModel::ProjectModel::instance();
  const auto groupId   = m_selectedDataset.groupId;
  const auto datasetId = m_selectedDataset.datasetId;

  if (idInt == kDatasetView_Title) {
    const auto newTitle = m_selectedDataset.title;
    pm.updateDataset(groupId, datasetId, m_selectedDataset, false);

    for (auto it = m_datasetItems.begin(); it != m_datasetItems.end(); ++it) {
      if (it.value().groupId != groupId || it.value().datasetId != datasetId)
        continue;

      auto* treeItem = it.key();
      treeItem->setText(newTitle);
      treeItem->setData(newTitle, TreeViewText);
      m_datasetItems[treeItem].title = newTitle;
      break;
    }

    Q_EMIT selectedTextChanged();
    Q_EMIT datasetOptionsChanged();
    Q_EMIT editableOptionsChanged();
    return;
  }

  const bool rebuildTree = (idInt == kDatasetView_Index);
  pm.updateDataset(groupId, datasetId, m_selectedDataset, rebuildTree);
  if (!rebuildTree)
    syncDatasetItemCache(groupId, datasetId);

  Q_EMIT datasetOptionsChanged();
  Q_EMIT editableOptionsChanged();
}

void DataModel::ProjectEditor::syncDatasetItemCache(int groupId, int datasetId)
{
  for (auto it = m_datasetItems.begin(); it != m_datasetItems.end(); ++it) {
    if (it.value().groupId != groupId || it.value().datasetId != datasetId)
      continue;

    m_datasetItems[it.key()] = m_selectedDataset;
    break;
  }
}

void DataModel::ProjectEditor::onOutputWidgetItemChanged(QStandardItem* item)
{
  if (!item)
    return;

  const auto id    = item->data(ParameterType);
  const auto value = item->data(EditableValue);

  switch (static_cast<OutputWidgetItem>(id.toInt())) {
    case kOutputWidget_Title:
      m_selectedOutputWidget.title = value.toString();
      break;
    case kOutputWidget_Icon:
      m_selectedOutputWidget.icon = value.toString();
      break;
    case kOutputWidget_MonoIcon:
      m_selectedOutputWidget.monoIcon = value.toBool();
      break;
    case kOutputWidget_Type: {
      const auto newType = static_cast<DataModel::OutputWidgetType>(value.toInt());
      if (m_selectedOutputWidget.type != newType) {
        m_selectedOutputWidget.type = newType;
        buildOutputWidgetModel(m_selectedOutputWidget);
      }
      break;
    }
    case kOutputWidget_MinValue:
      m_selectedOutputWidget.minValue = SerialStudio::toDouble(value);
      break;
    case kOutputWidget_MaxValue:
      m_selectedOutputWidget.maxValue = SerialStudio::toDouble(value);
      break;
    case kOutputWidget_StepSize:
      m_selectedOutputWidget.stepSize = SerialStudio::toDouble(value);
      break;
    case kOutputWidget_InitialValue:
      m_selectedOutputWidget.initialValue = SerialStudio::toDouble(value);
      break;
    case kOutputWidget_TransmitFunction:
      m_selectedOutputWidget.transmitFunction = value.toString();
      break;
    case kOutputWidget_TxEncoding:
      m_selectedOutputWidget.txEncoding = value.toInt();
      break;
  }

  if (static_cast<OutputWidgetItem>(id.toInt()) == kOutputWidget_Title) {
    const auto newTitle = value.toString();
    for (auto it = m_outputWidgetItems.begin(); it != m_outputWidgetItems.end(); ++it) {
      if (it.value().groupId == m_selectedOutputWidget.groupId
          && it.value().widgetId == m_selectedOutputWidget.widgetId) {
        it.key()->setData(newTitle, TreeViewText);
        m_outputWidgetItems[it.key()].title = newTitle;
        Q_EMIT selectedTextChanged();
        break;
      }
    }
  } else {
    for (auto it = m_outputWidgetItems.begin(); it != m_outputWidgetItems.end(); ++it) {
      if (it.value().groupId == m_selectedOutputWidget.groupId
          && it.value().widgetId == m_selectedOutputWidget.widgetId) {
        m_outputWidgetItems[it.key()] = m_selectedOutputWidget;
        break;
      }
    }
  }

  DataModel::ProjectModel::instance().updateOutputWidget(
    m_selectedOutputWidget.groupId, m_selectedOutputWidget.widgetId, m_selectedOutputWidget, false);
}

void DataModel::ProjectEditor::buildProjectModel()
{
  if (m_projectModel) {
    m_projectModel->disconnect(this);
    m_projectModel->deleteLater();
  }

  m_projectModel = new CustomModel(this);
  const auto& pm = DataModel::ProjectModel::instance();

  auto* hdr = new QStandardItem();
  hdr->setData(SectionHeader, WidgetType);
  hdr->setData(tr("Project Information"), PlaceholderValue);
  hdr->setData("qrc:/icons/project-editor/model/project.svg", ParameterIcon);
  m_projectModel->appendRow(hdr);

  auto* title = new QStandardItem();
  title->setEditable(true);
  title->setData(true, Active);
  title->setData(TextField, WidgetType);
  title->setData(pm.title(), EditableValue);
  title->setData(kProjectView_Title, ParameterType);
  title->setData(tr("Project Title"), ParameterName);
  title->setData(tr("Untitled Project"), PlaceholderValue);
  title->setData(tr("Name or description of the project"), ParameterDescription);
  m_projectModel->appendRow(title);

  connect(m_projectModel,
          &CustomModel::itemChanged,
          this,
          &DataModel::ProjectEditor::onProjectItemChanged);

  Q_EMIT projectModelChanged();
}

