  peerModeItem->setData(ComboBox, WidgetType);
  peerModeItem->setData(pub.peerVerifyModes(), ComboBoxData);
  peerModeItem->setData(static_cast<int>(pub.peerVerifyMode()), EditableValue);
  peerModeItem->setData(kMqttPublisher_PeerVerifyMode, ParameterType);
  peerModeItem->setData(tr("Peer Verify"), ParameterName);
  peerModeItem->setData(tr("How strictly the broker's certificate chain is validated"),
                        ParameterDescription);
  m_mqttPublisherModel->appendRow(peerModeItem);

  auto* peerDepthItem = new QStandardItem();
  peerDepthItem->setEditable(true);
  peerDepthItem->setData(enabled, Active);
  peerDepthItem->setData(IntField, WidgetType);
  peerDepthItem->setData(pub.peerVerifyDepth(), EditableValue);
  peerDepthItem->setData(kMqttPublisher_PeerVerifyDepth, ParameterType);
  peerDepthItem->setData(tr("Verify Depth"), ParameterName);
  peerDepthItem->setData(tr("Maximum certificate chain length accepted (0 = unlimited)"),
                         ParameterDescription);
  m_mqttPublisherModel->appendRow(peerDepthItem);
}

void DataModel::ProjectEditor::onMqttPublisherItemChanged(QStandardItem* item)
{
  if (!item)
    return;

#ifdef BUILD_COMMERCIAL
  auto& pub        = MQTT::Publisher::instance();
  const auto type  = item->data(ParameterType).toInt();
  const auto value = item->data(EditableValue);

  switch (type) {
    case kMqttPublisher_Enabled:
      pub.setEnabled(value.toBool());
      buildMqttPublisherModel();
      return;
    case kMqttPublisher_Mode:
      pub.setMode(value.toInt());
      buildMqttPublisherModel();
      return;
    case kMqttPublisher_PublishFrequency:
      pub.setPublishFrequency(value.toInt());
      break;
    case kMqttPublisher_TopicBase:
      pub.setTopicBase(value.toString());
      break;
    case kMqttPublisher_ScriptTopic:
      pub.setScriptTopic(value.toString());
      break;
    case kMqttPublisher_ScriptCode:
      pub.setScriptCode(value.toString());
      break;
    case kMqttPublisher_PublishNotifications:
      pub.setPublishNotifications(value.toBool());
      buildMqttPublisherModel();
      return;
    case kMqttPublisher_NotificationTopic:
      pub.setNotificationTopic(value.toString());
      break;
    case kMqttPublisher_Hostname:
      pub.setHostname(value.toString());
      break;
    case kMqttPublisher_Port:
      pub.setPort(static_cast<quint16>(value.toInt()));
      break;
    case kMqttPublisher_CustomClientId:
      pub.setCustomClientId(value.toBool());
      buildMqttPublisherModel();
      return;
    case kMqttPublisher_ClientId:
      pub.setClientId(value.toString());
      break;
    case kMqttPublisher_Username:
      pub.setUsername(value.toString());
      break;
    case kMqttPublisher_Password:
      pub.setPassword(value.toString());
      break;
    case kMqttPublisher_MqttVersion:
      pub.setMqttVersion(static_cast<quint8>(value.toInt()));
      break;
    case kMqttPublisher_KeepAlive:
      pub.setKeepAlive(static_cast<quint16>(value.toInt()));
      break;
    case kMqttPublisher_CleanSession:
      pub.setCleanSession(value.toBool());
      break;
    case kMqttPublisher_SslEnabled:
      pub.setSslEnabled(value.toBool());
      buildMqttPublisherModel();
      return;
    case kMqttPublisher_SslProtocol:
      pub.setSslProtocol(static_cast<quint8>(value.toInt()));
      break;
    case kMqttPublisher_PeerVerifyMode:
      pub.setPeerVerifyMode(static_cast<quint8>(value.toInt()));
      break;
    case kMqttPublisher_PeerVerifyDepth:
      pub.setPeerVerifyDepth(value.toInt());
      break;
    default:
      break;
  }
#else
  Q_UNUSED(item);
#endif
}

bool DataModel::ProjectEditor::tryMultiSelection()
{
  if (!m_selectionModel || !m_treeModel)
    return false;

  int kind = KindNone;
  QSet<qint64> seen;
  QVector<QPair<int, int>> items;
  const auto indexes = m_selectionModel->selectedIndexes();
  for (const auto& idx : indexes) {
    if (!idx.isValid() || idx.column() != 0)
      continue;

    const auto key =
      (static_cast<qint64>(idx.row()) << 32) ^ reinterpret_cast<qint64>(idx.internalPointer());
    if (seen.contains(key))
      continue;

    seen.insert(key);

    const int k = m_treeModel->data(idx, TreeItemKind).toInt();
    if (k != KindDataset)
      return false;

    if (kind == KindNone)
      kind = k;
    else if (kind != k)
      return false;

    const int id     = m_treeModel->data(idx, TreeItemId).toInt();
    const int parent = m_treeModel->data(idx, TreeItemParentId).toInt();
    items.append(qMakePair(parent, id));
  }

  if (items.size() < 2)
    return false;

  if (m_currentView == MultiSelectionView && m_batchKind == static_cast<ItemKind>(kind)
      && m_batchItems == items)
    return true;

  m_batchKind  = static_cast<ItemKind>(kind);
  m_batchItems = items;
  setCurrentView(MultiSelectionView);
  buildMultiSelectionModel();
  Q_EMIT currentViewChanged();
  return true;
}

void DataModel::ProjectEditor::buildMultiSelectionModel()
{
  if (m_batchKind == KindDataset)
    buildMultiDatasetModel();
}

QHash<int, QVariant> DataModel::ProjectEditor::datasetEditValues(const DataModel::Dataset& dataset)
{
  CustomModel tmp;
  addGeneralSection(&tmp, dataset);
  addPlotSection(&tmp, dataset);
  addFFTSection(&tmp, dataset);
  addWidgetSection(&tmp, dataset);
  addLEDSection(&tmp, dataset);

  QHash<int, QVariant> out;
  const int rows = tmp.rowCount();
  for (int r = 0; r < rows; ++r) {
    auto* it = tmp.item(r);
    if (!it)
      continue;

    const auto pt = it->data(ParameterType);
    if (pt.isValid())
      out.insert(pt.toInt(), it->data(EditableValue));
  }

  return out;
}

void DataModel::ProjectEditor::buildMultiDatasetModel()
{
  auto& pm           = DataModel::ProjectModel::instance();
  const auto& groups = pm.groups();

  QVector<DataModel::Dataset> sel;
  sel.reserve(static_cast<qsizetype>(m_batchItems.size()));
  for (const auto& pr : m_batchItems) {
    const int gid = pr.first, dsid = pr.second;
    if (gid < 0 || static_cast<size_t>(gid) >= groups.size())
      continue;

    for (const auto& d : groups[gid].datasets)
      if (d.datasetId == dsid) {
        sel.append(d);
        break;
      }
  }

  if (sel.isEmpty())
    return;

  QVector<QHash<int, QVariant>> maps;
  maps.reserve(sel.size());
  for (const auto& d : sel)
    maps.append(datasetEditValues(d));

  if (m_datasetModel) {
    m_datasetModel->disconnect(this);
    m_datasetModel->deleteLater();
  }

  m_selectedDataset = sel.first();
  m_datasetModel    = new CustomModel(this);

  addGeneralSection(m_datasetModel, m_selectedDataset);
  addPlotSection(m_datasetModel, m_selectedDataset);
  addFFTSection(m_datasetModel, m_selectedDataset);
  addWidgetSection(m_datasetModel, m_selectedDataset);
  addLEDSection(m_datasetModel, m_selectedDataset);

  const int rows = m_datasetModel->rowCount();
  for (int r = 0; r < rows; ++r) {
    auto* it = m_datasetModel->item(r);
    if (!it)
      continue;

    const auto ptVar = it->data(ParameterType);
    if (!ptVar.isValid())
      continue;

    const int wt         = it->data(WidgetType).toInt();
    const bool intWidget = (wt == ComboBox || wt == CheckBox || wt == AutoIntField);
    const QVariant blank = intWidget ? QVariant(-1) : QVariant(QString());

    const int pt = ptVar.toInt();
    if (pt == kDatasetView_Title || pt == kDatasetView_Index) {
      it->setEditable(false);
      it->setData(false, Active);
      it->setData(blank, EditableValue);
      it->setData(tr("(multiple)"), PlaceholderValue);
      continue;
    }

    const QVariant first = maps.first().value(pt);
    bool mixed           = false;
    for (int i = 1; i < maps.size(); ++i)
      if (maps[i].contains(pt) && maps[i].value(pt) != first) {
        mixed = true;
        break;
      }

    if (mixed) {
      it->setData(blank, EditableValue);
      it->setData(tr("Mixed"), PlaceholderValue);
    }
  }

  connect(m_datasetModel,
          &CustomModel::itemChanged,
          this,
          &DataModel::ProjectEditor::onMultiSelectionItemChanged);

  Q_EMIT datasetModelChanged();
  Q_EMIT datasetOptionsChanged();
}

void DataModel::ProjectEditor::onMultiSelectionItemChanged(QStandardItem* item)
{
  if (!item || m_batchApplying || m_batchKind != KindDataset)
    return;

  const auto idInt = static_cast<DatasetItem>(item->data(ParameterType).toInt());
  const auto value = item->data(EditableValue);
  const int vIdx   = value.toInt();
  if (idInt == kDatasetView_Widget && (vIdx < 0 || vIdx >= m_datasetWidgets.size()))
    return;

  if (idInt == kDatasetView_Plot && (vIdx < 0 || vIdx >= m_plotOptions.size()))
    return;

  if (idInt == kDatasetView_FFT_Samples && (vIdx < 0 || vIdx >= m_fftSamples.size()))
    return;

  auto& pm = DataModel::ProjectModel::instance();

  QVector<DataModel::Dataset> sel;
  QVector<QPair<int, int>> ids;
  {
    const auto& groups = pm.groups();
    for (const auto& pr : m_batchItems) {
      const int gid = pr.first, dsid = pr.second;
      if (gid < 0 || static_cast<size_t>(gid) >= groups.size())
        continue;

      for (const auto& d : groups[gid].datasets)
        if (d.datasetId == dsid) {
          sel.append(d);
          ids.append(pr);
          break;
        }
    }
  }

  pm.setAutoSaveSuspended(true);
  m_batchApplying = true;
  for (int i = 0; i < sel.size(); ++i) {
    DataModel::Dataset ds = sel[i];
    onDatasetCommonItemChanged(item, ds);
    onDatasetWidgetItemChanged(item, ds);
    onDatasetRangeItemChanged(item, ds);
    onDatasetFftItemChanged(item, ds);
    onDatasetFlagItemChanged(item, ds);
    pm.updateDataset(ids[i].first, ids[i].second, ds, false);
  }

  m_batchApplying = false;
  pm.setAutoSaveSuspended(false);

  buildMultiDatasetModel();
  pm.flushAutoSave();
}

void DataModel::ProjectEditor::changeDatasetOptionForSelection(int option, bool checked)
{
  if (m_batchKind != KindDataset)
    return;

  const auto opt = static_cast<SerialStudio::DatasetOption>(option);
  auto& pm       = DataModel::ProjectModel::instance();

  QVector<DataModel::Dataset> sel;
  QVector<QPair<int, int>> ids;
  {
    const auto& groups = pm.groups();
    for (const auto& pr : m_batchItems) {
      const int gid = pr.first, dsid = pr.second;
      if (gid < 0 || static_cast<size_t>(gid) >= groups.size())
        continue;

      for (const auto& d : groups[gid].datasets)
        if (d.datasetId == dsid) {
          sel.append(d);
          ids.append(pr);
          break;
        }
    }
  }

  pm.setAutoSaveSuspended(true);
  for (int i = 0; i < sel.size(); ++i) {
    DataModel::Dataset ds = sel[i];
    switch (opt) {
      case SerialStudio::DatasetPlot:
        ds.plt = checked;
        break;
      case SerialStudio::DatasetFFT:
        ds.fft = checked;
        break;
      case SerialStudio::DatasetBar:
        ds.widget = checked ? QStringLiteral("bar") : QString();
        break;
      case SerialStudio::DatasetGauge:
        ds.widget = checked ? QStringLiteral("gauge") : QString();
        break;
      case SerialStudio::DatasetCompass:
        ds.widget = checked ? QStringLiteral("compass") : QString();
        break;
      case SerialStudio::DatasetMeter:
        ds.widget = checked ? QStringLiteral("meter") : QString();
        break;
      case SerialStudio::DatasetLED:
        ds.led = checked;
        break;
      case SerialStudio::DatasetWaterfall:
        ds.waterfall = checked;
        break;
      default:
        break;
    }

    pm.updateDataset(ids[i].first, ids[i].second, ds, false);
  }
  pm.setAutoSaveSuspended(false);

  buildMultiDatasetModel();
  Q_EMIT datasetOptionsChanged();
  pm.flushAutoSave();
}

void DataModel::ProjectEditor::setCurrentView(const DataModel::ProjectEditor::CurrentView view)
{
  if (m_suppressViewChange) [[unlikely]]
    return;

  if (m_currentView == view)
    return;

  m_currentView = view;
  Q_EMIT currentViewChanged();
  Q_EMIT selectedTextChanged();
}

bool DataModel::ProjectEditor::selectSourceParserItem(QStandardItem* item)
{
  if (!m_sourceParserItems.contains(item))
    return false;

  const auto cached      = m_sourceParserItems.value(item);
  const auto& srcs       = DataModel::ProjectModel::instance().sources();
  DataModel::Source live = cached;
  for (const auto& s : srcs) {
    if (s.sourceId == cached.sourceId) {
      live = s;
      break;
    }
  }
  m_selectedSource = live;
  setCurrentView(SourceFrameParserView);
  Q_EMIT selectedSourceFrameParserCodeChanged();
  Q_EMIT sourceModelChanged();
  return true;
}

bool DataModel::ProjectEditor::selectSourceItem(QStandardItem* item)
{
  if (!m_sourceItems.contains(item))
    return false;

  const auto cached      = m_sourceItems.value(item);
  const auto& srcs       = DataModel::ProjectModel::instance().sources();
  DataModel::Source live = cached;
  for (const auto& s : srcs) {
    if (s.sourceId == cached.sourceId) {
      live = s;
      break;
    }
  }

  if (m_currentView == SourceView && live.sourceId == m_selectedSource.sourceId)
    return true;

  setCurrentView(SourceView);
  buildSourceModel(live);
  return true;
}

bool DataModel::ProjectEditor::selectGroupItem(QStandardItem* item)
{
  if (!m_groupItems.contains(item))
    return false;

  auto& pm              = DataModel::ProjectModel::instance();
  const auto cached     = m_groupItems.value(item);
  const auto& groups    = pm.groups();
  DataModel::Group live = cached;
  if (cached.groupId >= 0 && static_cast<size_t>(cached.groupId) < groups.size())
    live = groups[cached.groupId];

  pm.setSelectedGroup(live);
  setCurrentView(GroupView);
  buildGroupModel(live);
  return true;
}

bool DataModel::ProjectEditor::selectGroupFolderItem(QStandardItem* item)
{
  if (item == m_groupsRootItem) {
    setCurrentView(GroupsView);
    return true;
  }

  if (m_groupFolderItems.contains(item)) {
    const int fid = m_groupFolderItems.value(item);
    if (m_selectedGroupFolderId != fid) {
      m_selectedGroupFolderId = fid;
      Q_EMIT selectedGroupFolderIdChanged();
    }
    setCurrentView(GroupFolderView);
    return true;
  }

  return false;
}

bool DataModel::ProjectEditor::selectDatasetItem(QStandardItem* item)
{
  if (!m_datasetItems.contains(item))
    return false;

  auto& pm                = DataModel::ProjectModel::instance();
  const auto cached       = m_datasetItems.value(item);
  const auto& groups      = pm.groups();
  DataModel::Dataset live = cached;
  if (cached.groupId >= 0 && static_cast<size_t>(cached.groupId) < groups.size()) {
    for (const auto& d : groups[cached.groupId].datasets) {
      if (d.datasetId == cached.datasetId) {
        live = d;
        break;
      }
    }
  }

  pm.setSelectedDataset(live);
  setCurrentView(DatasetView);
  buildDatasetModel(live);
  return true;
}

bool DataModel::ProjectEditor::selectActionItem(QStandardItem* item)
{
