//-

c int folderParentId(const std::vector<Folder>& folders, int folderId)
{
  for (const auto& f : folders)
    if (f.folderId == folderId)
      return f.parentFolderId;

  return -1;
}

/**

c bool folderHasSelectedAncestor(const std::vector<Folder>& folders,
                                      int folderId,
                                      const QSet<int>& chosen)
{
  int parent     = folderParentId(folders, folderId);
  const int kMax = static_cast<int>(folders.size());
  for (int i = 0; i < kMax && parent != -1; ++i) {
    if (chosen.contains(parent))
      return true;

    parent = folderParentId(folders, parent);
  }

  return false;
}

}

DataModel::ProjectModel::duplicateSelectedItems(const QVariantList& items)
{
  QSet<int> selectedGroupFolders;
  QSet<int> selectedTableFolders;
  for (const auto& v : items) {
    const auto m   = v.toMap();
    const int kind = m.value(QStringLiteral("kind"), -1).toInt();
    const int id   = m.value(QStringLiteral("id"), -1).toInt();
    if (kind == ProjectEditor::KindGroupFolder)
      selectedGroupFolders.insert(id);
    else if (kind == ProjectEditor::KindTableFolder)
      selectedTableFolders.insert(id);
  }

  QSet<int> coveredGroupFolders;
  QSet<int> coveredTableFolders;
  for (const auto& v : items) {
    const auto m   = v.toMap();
    const int kind = m.value(QStringLiteral("kind"), -1).toInt();
    const int id   = m.value(QStringLiteral("id"), -1).toInt();

    if (kind == ProjectEditor::KindGroupFolder
        && !folderHasSelectedAncestor(m_groupFolders, id, selectedGroupFolders))
      coveredGroupFolders.unite(duplicateGroupFolderSubtree(id));

    else if (kind == ProjectEditor::KindTableFolder
             && !folderHasSelectedAncestor(m_tableFolders, id, selectedTableFolders))
      coveredTableFolders.unite(duplicateTableFolderSubtree(id));
  }

  for (const auto& v : items) {
    const auto entry   = v.toMap();
    const int kind     = entry.value(QStringLiteral("kind"), -1).toInt();
    const int id       = entry.value(QStringLiteral("id"), -1).toInt();
    const int parent   = entry.value(QStringLiteral("parentId"), -1).toInt();
    const QString path = entry.value(QStringLiteral("path")).toString();

    if (kind == ProjectEditor::KindGroup && coveredGroupFolders.contains(parent))
      continue;

    if (kind == ProjectEditor::KindUserTable && coveredTableFolders.contains(parent))
      continue;

    switch (kind) {
      case ProjectEditor::KindGroup:
        duplicateGroup(id);
        break;
      case ProjectEditor::KindDataset:
        duplicateDataset(parent, id);
        break;
      case ProjectEditor::KindAction:
        duplicateAction(id);
        break;
      case ProjectEditor::KindOutputWidget:
        duplicateOutputWidget(parent, id);
        break;
      case ProjectEditor::KindUserTable:
        duplicateTableByPath(path);
        break;
      default:
        break;
    }
  }
}

/**

DataModel::ProjectModel::deleteSelectedItems(const QVariantList& items)
{
  struct Entry {
    int kind;
    int id;
    int parentId;
    QString path;
  };

  QList<Entry> entries;
  entries.reserve(items.size());
  for (const auto& v : items) {
    const auto m = v.toMap();
    Entry e;
    e.kind     = m.value(QStringLiteral("kind"), -1).toInt();
    e.id       = m.value(QStringLiteral("id"), -1).toInt();
    e.parentId = m.value(QStringLiteral("parentId"), -1).toInt();
    e.path     = m.value(QStringLiteral("path")).toString();
    entries.append(e);
  }

  std::sort(entries.begin(), entries.end(), [](const Entry& a, const Entry& b) {
    if (a.kind != b.kind)
      return a.kind > b.kind;

    if (a.parentId != b.parentId)
      return a.parentId > b.parentId;

    return a.id > b.id;
  });

  for (const auto& e : entries) {
    switch (e.kind) {
      case ProjectEditor::KindGroup:
        deleteGroup(e.id, false);
        break;
      case ProjectEditor::KindDataset:
        deleteDataset(e.parentId, e.id, false);
        break;
      case ProjectEditor::KindAction:
        deleteAction(e.id, false);
        break;
      case ProjectEditor::KindOutputWidget:
        deleteOutputWidget(e.parentId, e.id, false);
        break;
      case ProjectEditor::KindWorkspace:
        deleteWorkspace(e.id);
        break;
      case ProjectEditor::KindWorkspaceFolder:
        deleteWorkspaceFolder(e.id);
        break;
      case ProjectEditor::KindGroupFolder:
        deleteGroupFolder(e.id);
        break;
      case ProjectEditor::KindUserTable:
        deleteTable(e.path);
        break;
      case ProjectEditor::KindTableFolder:
        deleteTableFolder(e.id);
        break;
      default:
        break;
    }
  }
}

/**

DataModel::ProjectModel::confirmDeleteSelectedItems(const QVariantList& items)
{
  if (items.isEmpty())
    return;

  const int count = static_cast<int>(items.size());
  if (count > 1) {
    const int choice = Misc::Utilities::showMessageBox(tr("Delete %1 selected items?").arg(count),
                                                       tr("This action cannot be undone."),
                                                       QMessageBox::Warning,
                                                       tr("Delete Items"),
                                                       QMessageBox::Yes | QMessageBox::Cancel,
                                                       QMessageBox::Cancel);

    if (choice != QMessageBox::Yes)
      return;
  }

  deleteSelectedItems(items);
}

/**

DataModel::ProjectModel::moveSelectedItemsToFolder(const QVariantList& items, int folderId)
{
  for (const auto& v : items) {
    const auto m       = v.toMap();
    const int kind     = m.value(QStringLiteral("kind"), -1).toInt();
    const int id       = m.value(QStringLiteral("id"), -1).toInt();
    const QString path = m.value(QStringLiteral("path")).toString();

    switch (kind) {
      case ProjectEditor::KindWorkspace:
        moveWorkspaceToFolder(id, folderId);
        break;
      case ProjectEditor::KindWorkspaceFolder:
        moveFolderToFolder(id, folderId);
        break;
      case ProjectEditor::KindGroup:
        moveGroupToFolder(id, folderId);
        break;
      case ProjectEditor::KindGroupFolder:
        moveGroupFolderToFolder(id, folderId);
        break;
      case ProjectEditor::KindUserTable:
        moveTableToFolder(path, folderId);
        break;
      case ProjectEditor::KindTableFolder:
        moveTableFolderToFolder(id, folderId);
        break;
      default:
        break;
    }
  }
}

/**

DataModel::ProjectModel::setGroupsInFolderEnabled(const int folderId, const bool enabled)
{
  bool changed = false;
  for (auto& g : m_groups) {
    if (g.parentFolderId == -1)
      continue;

    if (!folderIsSelfOrDescendant(m_groupFolders, folderId, g.parentFolderId))
      continue;

    if (g.enabled == enabled)
      continue;

    g.enabled = enabled;
    changed   = true;
  }

  return changed;
}

/**

DataModel::ProjectModel::setItemsEnabled(const QVariantList& items, const bool enabled)
{
  if (items.isEmpty())
    return;

  const int groupCount = static_cast<int>(m_groups.size());

  setAutoSaveSuspended(true);
  bool changed = false;
  for (const auto& v : items) {
    const auto m     = v.toMap();
    const int kind   = m.value(QStringLiteral("kind"), -1).toInt();
    const int id     = m.value(QStringLiteral("id"), -1).toInt();
    const int parent = m.value(QStringLiteral("parentId"), -1).toInt();

    if (kind == ProjectEditor::KindGroupFolder) {
      changed |= setGroupsInFolderEnabled(id, enabled);
      continue;
    }

    if (kind == ProjectEditor::KindGroup && id >= 0 && id < groupCount
        && m_groups[id].enabled != enabled) {
      m_groups[id].enabled = enabled;
      changed              = true;
      continue;
    }

    if (kind == ProjectEditor::KindDataset && parent >= 0 && parent < groupCount) {
      auto& datasets = m_groups[parent].datasets;
      if (id < 0 || static_cast<size_t>(id) >= datasets.size() || datasets[id].enabled == enabled)
        continue;

      datasets[id].enabled = enabled;
      changed              = true;
    }
  }

  setAutoSaveSuspended(false);
  if (!changed)
    return;

  Q_EMIT groupsChanged();
  setModified(true);
  syncRuntime();
  flushAutoSave();
}

static void sanitizeFolderTree(std::vector<Folder>& folders, std::vector<Entity>& entities)
{
  QHash<int, int> parentOf;
  QSet<int> validFolders;
  for (const auto& f : std::as_const(folders)) {
    validFolders.insert(f.folderId);
    parentOf.insert(f.folderId, f.parentFolderId);
  }

  for (auto& f : folders) {
    if (f.parentFolderId != -1 && !validFolders.contains(f.parentFolderId)) {
      f.parentFolderId = -1;
      continue;
    }

    QSet<int> seen;
    int p          = f.parentFolderId;
    const int kMax = static_cast<int>(folders.size());
    for (int i = 0; i < kMax && p != -1; ++i) {
      if (p == f.folderId || seen.contains(p)) {
        f.parentFolderId = -1;
        break;
      }

      seen.insert(p);
      p = parentOf.value(p, -1);
    }
  }

  for (auto& e : entities)
    if (e.parentFolderId != -1 && !validFolders.contains(e.parentFolderId))
      e.parentFolderId = -1;
}

static std::vector<int> collectFolderSubtreeOrdered(const std::vector<Folder>& folders, int rootId)
{
  std::vector<int> ordered;
  if (!folderExists(folders, rootId))
    return ordered;

  QSet<int> seen;
  ordered.push_back(rootId);
  seen.insert(rootId);

  const int kMax = static_cast<int>(folders.size());
  for (size_t head = 0; head < ordered.size() && static_cast<int>(ordered.size()) <= kMax; ++head) {
    const int parent = ordered[head];
    for (const auto& f : folders)
      if (f.parentFolderId == parent && !seen.contains(f.folderId)) {
        seen.insert(f.folderId);
        ordered.push_back(f.folderId);
      }
  }

  return ordered;
}

static bool folderFields(const std::vector<Folder>& folders, int id, int& parent, QString& title)
{
  for (const auto& f : folders)
    if (f.folderId == id) {
      parent = f.parentFolderId;
      title  = f.title;
      return true;
    }

  return false;
}

static QStringList siblingFolderTitles(const std::vector<Folder>& folders, int parentFolderId)
{
  QStringList titles;
  for (const auto& f : folders)
    if (f.parentFolderId == parentFolderId)
      titles.append(f.title);

  return titles;
}

static QHash<int, int> cloneFolderSubtree(const std::vector<Folder>& folders,
                                          const std::vector<int>& ordered,
                                          int rootFolderId,
                                          AddFn addFolder)
{
  QHash<int, int> idMap;
  for (const int oldId : ordered) {
    int oldParent = -1;
    QString oldTitle;
    if (!folderFields(folders, oldId, oldParent, oldTitle))
      continue;

    const bool isRoot   = (oldId == rootFolderId);
    const int newParent = isRoot ? oldParent : idMap.value(oldParent, -1);
    const QString title =
      isRoot ? nextDuplicateTitle(oldTitle, siblingFolderTitles(folders, oldParent)) : oldTitle;

    idMap.insert(oldId, addFolder(newParent, title));
  }

  return idMap;
}

QString DataModel::ProjectModel::workspaceFolderTitle(int folderId) const
{
  for (const auto& f : m_workspaceFolders)
    if (f.folderId == folderId)
      return f.title;

  return QString();
}

int DataModel::ProjectModel::addWorkspaceFolder(int parentFolderId, const QString& title)
{
  if (AppState::instance().operationMode() != SerialStudio::ProjectFile)
    return -1;

  if (!m_customizeWorkspaces)
    setCustomizeWorkspaces(true);

  if (parentFolderId != -1 && !folderExists(m_workspaceFolders, parentFolderId))
    parentFolderId = -1;

  int newId = 1;
  for (const auto& f : std::as_const(m_workspaceFolders))
    if (f.folderId >= newId)
      newId = f.folderId + 1;

  DataModel::WorkspaceFolder folder;
  folder.folderId       = newId;
  folder.parentFolderId = parentFolderId;
  folder.title          = title.simplified().isEmpty() ? tr("Folder") : title.simplified();
  m_workspaceFolders.push_back(folder);

  setModified(true);
  Q_EMIT editorWorkspacesChanged();
  Q_EMIT activeWorkspacesChanged();
  return newId;
}

void DataModel::ProjectModel::renameWorkspaceFolder(int folderId, const QString& title)
{
  if (title.simplified().isEmpty())
    return;

  for (auto& f : m_workspaceFolders) {
    if (f.folderId != folderId)
      continue;

    f.title = title.simplified();
    setModified(true);
    Q_EMIT editorWorkspacesChanged();
    Q_EMIT activeWorkspacesChanged();
    return;
  }
}

void DataModel::ProjectModel::deleteWorkspaceFolder(int folderId)
{
  if (!m_customizeWorkspaces)
    setCustomizeWorkspaces(true);

  auto it = std::find_if(m_workspaceFolders.begin(),
                         m_workspaceFolders.end(),
                         [folderId](const auto& f) { return f.folderId == folderId; });
  if (it == m_workspaceFolders.end())
    return;

  const int promoteTo = it->parentFolderId;
  for (auto& f : m_workspaceFolders)
    if (f.parentFolderId == folderId)
      f.parentFolderId = promoteTo;

  for (auto& ws : m_workspaces)
    if (ws.parentFolderId == folderId)
      ws.parentFolderId = promoteTo;

  m_workspaceFolders.erase(it);

  setModified(true);
  Q_EMIT editorWorkspacesChanged();
  Q_EMIT activeWorkspacesChanged();
}

void DataModel::ProjectModel::moveWorkspaceToFolder(int workspaceId, int parentFolderId)
{
  if (!m_customizeWorkspaces)
    setCustomizeWorkspaces(true);

  if (parentFolderId != -1 && !folderExists(m_workspaceFolders, parentFolderId))
    return;

  for (auto& ws : m_workspaces) {
    if (ws.workspaceId != workspaceId)
      continue;

    if (ws.parentFolderId == parentFolderId)
      return;

    ws.parentFolderId = parentFolderId;
    setModified(true);
    Q_EMIT editorWorkspacesChanged();
    Q_EMIT activeWorkspacesChanged();
    return;
  }
}

void DataModel::ProjectModel::moveFolderToFolder(int folderId, int parentFolderId)
{
  if (!m_customizeWorkspaces)
    setCustomizeWorkspaces(true);

  if (parentFolderId != -1 && !folderExists(m_workspaceFolders, parentFolderId))
    return;

  if (folderIsSelfOrDescendant(m_workspaceFolders, folderId, parentFolderId))
    return;

  for (auto& f : m_workspaceFolders) {
    if (f.folderId != folderId)
      continue;

    if (f.parentFolderId == parentFolderId)
      return;

    f.parentFolderId = parentFolderId;
    setModified(true);
    Q_EMIT editorWorkspacesChanged();
    Q_EMIT activeWorkspacesChanged();
    return;
  }
}

void DataModel::ProjectModel::moveWorkspaceInFolder(int workspaceId, int direction)
{
  if (!m_customizeWorkspaces)
    setCustomizeWorkspaces(true);

  const int n = static_cast<int>(m_workspaces.size());
  int from    = -1;
  for (int i = 0; i < n; ++i)
    if (m_workspaces[static_cast<size_t>(i)].workspaceId == workspaceId) {
      from = i;
      break;
    }

  if (from < 0)
    return;

  const int parent = m_workspaces[static_cast<size_t>(from)].parentFolderId;
  const int step   = (direction < 0) ? -1 : 1;
  for (int j = from + step; j >= 0 && j < n; j += step) {
    if (m_workspaces[static_cast<size_t>(j)].parentFolderId != parent)
      continue;

    std::swap(m_workspaces[static_cast<size_t>(from)], m_workspaces[static_cast<size_t>(j)]);
    setModified(true);
    Q_EMIT editorWorkspacesChanged();
    Q_EMIT activeWorkspacesChanged();
    return;
  }
}

