QSet<int> DataModel::ProjectModel::duplicateGroupFolderSubtree(int rootFolderId)
{
  const auto ordered = collectFolderSubtreeOrdered(m_groupFolders, rootFolderId);
  if (ordered.empty())
    return QSet<int>();

  const auto idMap = cloneFolderSubtree(
    m_groupFolders, ordered, rootFolderId, [this](int parent, const QString& title) {
      return addGroupFolder(parent, title);
    });

  QSet<int> covered;
  for (const int oldId : ordered)
    covered.insert(oldId);

  std::vector<int> groupIds;
  for (const auto& g : m_groups)
    if (covered.contains(g.parentFolderId))
      groupIds.push_back(g.groupId);

  for (const int gid : groupIds) {
    const int oldParent = m_groups[static_cast<size_t>(gid)].parentFolderId;
    duplicateGroup(gid);
    m_groups.back().parentFolderId = idMap.value(oldParent, -1);
  }

  if (!groupIds.empty()) {
    Q_EMIT groupsChanged();
    setModified(true);
  }

  return covered;
}

QSet<int> DataModel::ProjectModel::duplicateTableFolderSubtree(int rootFolderId)
{
  const auto ordered = collectFolderSubtreeOrdered(m_tableFolders, rootFolderId);
  if (ordered.empty())
    return QSet<int>();

  const auto idMap = cloneFolderSubtree(
    m_tableFolders, ordered, rootFolderId, [this](int parent, const QString& title) {
      return addTableFolder(parent, title);
    });

  QSet<int> covered;
  for (const int oldId : ordered)
    covered.insert(oldId);

  std::vector<DataModel::TableDef> copies;
  std::vector<int> targetParents;
  for (const auto& t : m_tables)
    if (covered.contains(t.parentFolderId)) {
      copies.push_back(t);
      targetParents.push_back(idMap.value(t.parentFolderId, -1));
    }

  for (size_t i = 0; i < copies.size(); ++i)
    appendTableCopyToFolder(copies[i], targetParents[i]);

  if (!copies.empty()) {
    Q_EMIT tablesChanged();
    setModified(true);
  }

  return covered;
}

void DataModel::ProjectModel::seedNextUniqueIdFromGroups()
{
  int maxUid = 0;

  for (auto& group : m_groups) {
    for (auto& dataset : group.datasets) {
      if (dataset.uniqueId < 0)
        dataset.uniqueId = dataset_unique_id(group.sourceId, dataset.groupId, dataset.datasetId);

      if (dataset.uniqueId > maxUid)
        maxUid = dataset.uniqueId;
    }

    if (group.uniqueId > maxUid)
      maxUid = group.uniqueId;
  }

  if (m_nextUniqueId <= maxUid)
    m_nextUniqueId = maxUid + 1;

  for (auto& group : m_groups)
    if (group.uniqueId < 0)
      group.uniqueId = m_nextUniqueId++;

  deduplicateUniqueIds();
}

void DataModel::ProjectModel::deduplicateUniqueIds()
{
  QSet<int> seenGroups;
  QSet<int> seenDatasets;
  QMap<int, int> datasetRemap;
  for (auto& group : m_groups) {
    if (seenGroups.contains(group.uniqueId)) {
      qWarning() << "ProjectModel: duplicate group uniqueId" << group.uniqueId
                 << "- reassigning to keep per-source maps unambiguous";
      group.uniqueId = m_nextUniqueId++;
    }
    seenGroups.insert(group.uniqueId);

    for (auto& dataset : group.datasets) {
      dataset.sourceId = group.sourceId;
      if (seenDatasets.contains(dataset.uniqueId)) {
        qWarning() << "ProjectModel: duplicate dataset uniqueId" << dataset.uniqueId
                   << "- reassigning to keep per-source maps unambiguous";
        const int newId = m_nextUniqueId++;
        datasetRemap.insert(dataset.uniqueId, newId);
        dataset.uniqueId = newId;
      }
      seenDatasets.insert(dataset.uniqueId);
    }
  }

  if (datasetRemap.isEmpty())
    return;

  for (auto& group : m_groups)
    for (auto& dataset : group.datasets) {
      if (dataset.xAxisId > 0)
        dataset.xAxisId = datasetRemap.value(dataset.xAxisId, dataset.xAxisId);

      if (dataset.waterfallYAxis > 0)
        dataset.waterfallYAxis = datasetRemap.value(dataset.waterfallYAxis, dataset.waterfallYAxis);
    }
}

void DataModel::ProjectModel::migrateLegacyWorkspaceRefs()
{
  for (auto& ws : m_workspaces) {
    for (auto& ref : ws.widgetRefs) {
      const int pos = ref.groupUniqueId;
      if (pos < 0 || static_cast<size_t>(pos) >= m_groups.size())
        continue;

      ref.groupUniqueId = m_groups[static_cast<size_t>(pos)].uniqueId;
    }
  }
}

void DataModel::ProjectModel::migrateLegacyXAxisIds()
{
  QMap<int, QMap<int, int>> uidByIndex;
  for (const auto& group : m_groups)
    for (const auto& dataset : group.datasets)
      uidByIndex[group.sourceId].insert(dataset.index, dataset.uniqueId);

  for (auto& group : m_groups) {
    const auto indexMap = uidByIndex.value(group.sourceId);
    for (auto& dataset : group.datasets) {
      if (dataset.xAxisId == kXAxisTime || dataset.xAxisId == kXAxisSamples)
        continue;

      if (dataset.xAxisId <= 0)
        dataset.xAxisId = kXAxisTime;
      else
        dataset.xAxisId = indexMap.value(dataset.xAxisId, kXAxisTime);
    }
  }
}

static void remapWaterfallYAxisId(DataModel::Dataset& dataset,
                                  const QSet<int>& liveUids,
                                  const QMap<int, int>& indexMap)
{
  if (dataset.waterfallYAxis <= 0)
    dataset.waterfallYAxis = 0;
  else if (!liveUids.contains(dataset.waterfallYAxis))
    dataset.waterfallYAxis = indexMap.value(dataset.waterfallYAxis, 0);
}

void DataModel::ProjectModel::migrateLegacyWaterfallYAxisIds()
{
  QSet<int> liveUids;
  QMap<int, QMap<int, int>> uidByIndex;
  for (const auto& group : m_groups)
    for (const auto& dataset : group.datasets) {
      liveUids.insert(dataset.uniqueId);
      uidByIndex[group.sourceId].insert(dataset.index, dataset.uniqueId);
    }

  for (auto& group : m_groups) {
    const auto indexMap = uidByIndex.value(group.sourceId);
    for (auto& dataset : group.datasets)
      remapWaterfallYAxisId(dataset, liveUids, indexMap);
  }
}

void DataModel::ProjectModel::openJsonFile()
{
  auto* dialog = new QFileDialog(qApp->activeWindow(),
                                 tr("Select Project File"),
                                 jsonProjectsPath(),
                                 tr("Project Files (*.json *.ssproj)"));

  dialog->setFileMode(QFileDialog::ExistingFile);
  dialog->setAttribute(Qt::WA_DeleteOnClose);

  connect(dialog, &QFileDialog::fileSelected, this, [this](const QString& path) {
    if (path.isEmpty())
      return;

    QMetaObject::invokeMethod(this, [this, path]() { openJsonFile(path); }, Qt::QueuedConnection);
  });

  dialog->open();
}

bool DataModel::ProjectModel::openJsonFile(const QString& path)
{
  if (path.isEmpty())
    return false;

  QString resolved = path;
  if (!QFileInfo::exists(resolved)) {
    const QString remapped = Misc::WorkspaceManager::instance().remapLegacyPath(path);
    if (remapped != path && QFileInfo::exists(remapped))
      resolved = remapped;
  }

  if (m_filePath == resolved && !m_groups.empty())
    return true;

  AppState::instance().setOperationMode(SerialStudio::ProjectFile);

  QFile file(resolved);
  QJsonDocument document;
  if (file.open(QFile::ReadOnly)) {
    auto result = Misc::JsonValidator::parseAndValidate(file.readAll());
    if (!result.valid) [[unlikely]] {
      if (m_suppressMessageBoxes)
        qWarning() << "[ProjectModel] JSON validation error:" << result.errorMessage;
      else
        Misc::Utilities::showMessageBox(
          tr("JSON validation error"), result.errorMessage, QMessageBox::Critical);

      return false;
    }

    document = result.document;
    file.close();
  }

  return loadFromJsonDocument(document, resolved);
}

bool DataModel::ProjectModel::loadFromJsonDocument(const QJsonDocument& document,
                                                   const QString& sourcePath)
{
  if (document.isEmpty())
    return false;

  m_autoSaveSuspended = true;
  if (m_autoSaveTimer)
    m_autoSaveTimer->stop();

  m_groups.clear();
  m_actions.clear();
  m_sources.clear();
  m_workspaces.clear();
  m_widgetSettings  = QJsonObject();
  m_treeExpansion   = QJsonObject();
  m_diagramCollapse = QJsonObject();

  m_filePath = sourcePath;

  const auto json                = document.object();
  const QString legacyParserCode = json.value(QLatin1StringView("frameParser")).toString();
  const bool legacyUniqueIds     = !json.contains(Keys::NextUniqueId);

  const int loadedSchema = ss_jsr(json, Keys::SchemaVersion, 0).toInt();
  const bool olderSchema = loadedSchema < DataModel::kSchemaVersion;

  m_apiCallAllowFullSurface = ss_jsr(json, Keys::ApiCallAllowFullSurface, false).toBool();
  DataModel::ScriptApiCall::setAllowFullSurface(m_apiCallAllowFullSurface);

  m_controlScriptCode = ss_jsr(json, Keys::ControlScriptCode, "").toString();
  DataModel::ControlScript::instance().setCode(m_controlScriptCode);

  loadProjectRootScalars(json);
  loadProjectArrays(json, legacyParserCode);
  enforceGplSingleSource();
  resolveDatasetTransformLanguages();
  resolveDatasetVirtualFlags();

  seedNextUniqueIdFromGroups();
  loadWidgetSettingsAndWorkspaces(json);

  if (olderSchema) {
    m_customizeWorkspaces = false;
    m_workspaces.clear();
  }

  if (legacyUniqueIds) {
    migrateLegacyWorkspaceRefs();
    migrateLegacyXAxisIds();
  }

  migrateLegacyWaterfallYAxisIds();

  loadPointCount(json);
  loadPlotTimeRange(json);
  loadChangeDrivenTransforms(json);
  migrateLegacyLayoutKeys();
  migrateLegacyDashboardLayout(json);

  setModified(false);
  watchProjectFile();

  if (migrateLegacySeparator(json))
    return true;

  m_autoSnapshot = buildAutoWorkspaces();
  emitProjectLoadedSignals();

  if (legacyUniqueIds && !m_filePath.isEmpty())
    persistLegacyMigration();

  m_autoSaveSuspended = false;
  m_runtimeDirty      = false;

  if (olderSchema && !sourcePath.isEmpty()) {
    const QString title = tr("Project upgraded from an earlier file format");
    const QString body  = tr("This project was saved with schema version %1; the current version "
                             "is %2. Defaults have been applied to any new fields. Save the "
                             "project to lock in the upgrade.")
                           .arg(loadedSchema)
                           .arg(DataModel::kSchemaVersion);
    QTimer::singleShot(0, this, [title, body] {
      DataModel::NotificationCenter::instance().postInfo(
        QStringLiteral("ProjectModel"), title, body);
    });
  }

  return true;
}

void DataModel::ProjectModel::importProjectFromJson(const QJsonObject& project,
                                                    const QString& suggestedFileName)
{
  QMetaObject::invokeMethod(
    this,
    [this, project, suggestedFileName]() {
      QString suggested = suggestedFileName.isEmpty() ? tr("Untitled Project") : suggestedFileName;
      if (!suggested.endsWith(QStringLiteral(".ssproj"), Qt::CaseInsensitive))
        suggested += QStringLiteral(".ssproj");

      const QString defaultPath = jsonProjectsPath() + QStringLiteral("/") + suggested;

      auto* dialog = new QFileDialog(qApp->activeWindow(),
                                     tr("Save Imported Project"),
                                     defaultPath,
                                     tr("Serial Studio Project Files (*.ssproj)"));

      dialog->setAcceptMode(QFileDialog::AcceptSave);
      dialog->setFileMode(QFileDialog::AnyFile);
      dialog->setAttribute(Qt::WA_DeleteOnClose);

      auto accepted   = std::make_shared<bool>(false);
      auto chosenPath = std::make_shared<QString>();
      connect(
        dialog, &QFileDialog::fileSelected, this, [accepted, chosenPath](const QString& path) {
          if (path.isEmpty())
            return;

          *accepted   = true;
          *chosenPath = path;
          if (!chosenPath->endsWith(QStringLiteral(".ssproj"), Qt::CaseInsensitive))
            *chosenPath += QStringLiteral(".ssproj");
        });

      connect(dialog, &QFileDialog::finished, this, [this, accepted, chosenPath, project](int) {
        if (!*accepted) {
          Q_EMIT importCompleted(false, QString());
          return;
        }

        QMetaObject::invokeMethod(
          this,
          [this, chosenPath, project]() {
            QFile file(*chosenPath);
            if (!file.open(QFile::WriteOnly)) {
              if (m_suppressMessageBoxes)
                qWarning() << "[ProjectModel] Import save error:" << file.errorString();
              else
                Misc::Utilities::showMessageBox(
                  tr("File open error"), file.errorString(), QMessageBox::Critical);

              Q_EMIT importCompleted(false, QString());
              return;
            }

            file.write(QJsonDocument(project).toJson(QJsonDocument::Indented));
            file.close();

            AppState::instance().setOperationMode(SerialStudio::ProjectFile);

            // code-verify off
            // Clear cached path so openJsonFile()'s redundant-reload guard doesn't skip the open.
            m_filePath.clear();
            // code-verify on
            const bool ok = openJsonFile(*chosenPath);
            Q_EMIT importCompleted(ok, ok ? *chosenPath : QString());
          },
          Qt::QueuedConnection);
      });

      dialog->open();
    },
    Qt::QueuedConnection);
}

void DataModel::ProjectModel::loadProjectRootScalars(const QJsonObject& json)
{
  m_title                 = json.value(Keys::Title).toString();
  m_frameEndSequence      = json.value(Keys::FrameEnd).toString();
  m_frameStartSequence    = json.value(Keys::FrameStart).toString();
  m_hexadecimalDelimiters = json.value(Keys::HexadecimalDelimiters).toBool();
  m_frameDetection =
    static_cast<SerialStudio::FrameDetection>(json.value(Keys::FrameDetection).toInt());

  if (json.contains(Keys::ChecksumAlgorithm))
    m_checksumAlgorithm = json.value(Keys::ChecksumAlgorithm).toString();
  else
    m_checksumAlgorithm = json.value(Keys::Checksum).toString();

  if (json.contains(Keys::DecoderMethod))
    m_frameDecoder =
      static_cast<SerialStudio::DecoderMethod>(json.value(Keys::DecoderMethod).toInt());
  else
    m_frameDecoder = static_cast<SerialStudio::DecoderMethod>(json.value(Keys::Decoder).toInt());

  m_writerVersionAtCreation = json.value(Keys::WriterVersionAtCreation).toString();

  m_nextUniqueId = ss_jsr(json, Keys::NextUniqueId, 1).toInt();

  m_passwordHash       = json.value(Keys::PasswordHash).toString();
  const bool wasLocked = m_locked;
  m_locked             = !m_passwordHash.isEmpty();
  if (m_locked != wasLocked)
    Q_EMIT lockedChanged();

  if (!json.contains(Keys::FrameDetection))
    m_frameDetection = SerialStudio::StartAndEndDelimiter;
}

void DataModel::ProjectModel::loadProjectArrays(const QJsonObject& json,
                                                const QString& legacyParserCode)
{
  auto groups = json.value(Keys::Groups).toArray();
  for (int g = 0; g < groups.count(); ++g) {
    DataModel::Group group;
    group.groupId = g;
    if (DataModel::read(group, groups.at(g).toObject()))
      m_groups.push_back(group);
  }

  auto actions = json.value(Keys::Actions).toArray();
  for (int a = 0; a < actions.count(); ++a) {
    DataModel::Action action;
    action.actionId = a;
    if (DataModel::read(action, actions.at(a).toObject()))
      m_actions.push_back(action);
  }

  m_sources.clear();
  if (json.contains(Keys::Sources)) {
    auto sourcesArr = json.value(Keys::Sources).toArray();
    for (int s = 0; s < sourcesArr.count(); ++s) {
      DataModel::Source source;
      if (DataModel::read(source, sourcesArr.at(s).toObject()))
        m_sources.push_back(source);
    }
  }

  if (m_sources.empty()) {
    seedDefaultSourceFromUi(legacyParserCode);
    return;
  }

  if (m_sources[0].frameParserCode.isEmpty())
    m_sources[0].frameParserCode =
      legacyParserCode.isEmpty() ? FrameParser::defaultTemplateCode() : legacyParserCode;
}

void DataModel::ProjectModel::seedDefaultSourceFromUi(const QString& legacyParserCode)
{
  DataModel::Source defaultSource;
  defaultSource.sourceId              = 0;
  defaultSource.title                 = tr("Device A");
  auto& cm                            = IO::ConnectionManager::instance();
  defaultSource.busType               = static_cast<int>(cm.busType());
  defaultSource.frameStart            = m_frameStartSequence;
  defaultSource.frameEnd              = m_frameEndSequence;
  defaultSource.checksumAlgorithm     = m_checksumAlgorithm;
  defaultSource.frameDetection        = static_cast<int>(m_frameDetection);
  defaultSource.decoderMethod         = static_cast<int>(m_frameDecoder);
  defaultSource.hexadecimalDelimiters = m_hexadecimalDelimiters;
  defaultSource.frameParserCode =
    legacyParserCode.isEmpty() ? FrameParser::defaultTemplateCode() : legacyParserCode;

  IO::HAL_Driver* uiDriver = cm.uiDriverForBusType(cm.busType());
  if (uiDriver) {
    QJsonObject settings;
    for (const auto& prop : uiDriver->driverProperties())
      settings.insert(prop.key, QJsonValue::fromVariant(prop.value));

    const auto deviceId = uiDriver->deviceIdentifier();
    if (!deviceId.isEmpty())
      settings.insert(QStringLiteral("deviceId"), deviceId);

    defaultSource.connectionSettings = settings;
  }

  m_sources.push_back(defaultSource);
}

void DataModel::ProjectModel::enforceGplSingleSource()
{
#ifndef BUILD_COMMERCIAL
  if (m_sources.size() <= 1)
    return;

  m_sources.resize(1);
  for (auto& g : m_groups) {
    if (g.sourceId > 0)
      g.sourceId = 0;

    for (auto& widget : g.outputWidgets)
      if (widget.sourceId > 0)
        widget.sourceId = 0;
  }

  for (auto& action : m_actions)
    if (action.sourceId > 0)
      action.sourceId = 0;

  if (!m_suppressMessageBoxes)
    Misc::Utilities::showMessageBox(
      tr("Multi-source projects require a Pro license"),
      tr("This project contains multiple data sources. Only the first source "
         "has been loaded. A Serial Studio Pro license is required to use "
         "multi-source projects."),
      QMessageBox::Information);
  else
    qWarning() << "[ProjectModel] Multi-source project truncated to 1 source (GPL build)";
#endif
}

void DataModel::ProjectModel::resolveDatasetTransformLanguages()
{
  const auto languageForSource = [&](int sourceId) {
    for (const auto& src : m_sources)
      if (src.sourceId == sourceId)
        return src.frameParserLanguage == SerialStudio::Native ? static_cast<int>(SerialStudio::Lua)
                                                               : src.frameParserLanguage;

    return 0;
  };

  for (auto& group : m_groups)
    for (auto& dataset : group.datasets)
      if (dataset.transformLanguage < 0 && !dataset.transformCode.isEmpty())
        dataset.transformLanguage = languageForSource(dataset.sourceId);
}

static bool tryEnterComment(const QString& code, int n, int& i, bool isLua, TransformScanner& s)
{
  const QChar c    = code[i];
  const QChar next = (i + 1 < n) ? code[i + 1] : QChar();

  if (isLua && c == '-' && next == '-') {
    const bool isBlock  = (i + 3 < n && code[i + 2] == '[' && code[i + 3] == '[');
    s.inBlockComment    = isBlock;
    s.inLineComment     = !isBlock;
    i                  += isBlock ? 4 : 2;
    return true;
  }
  if (!isLua && c == '/' && next == '/') {
    s.inLineComment  = true;
    i               += 2;
    return true;
  }
  if (!isLua && c == '/' && next == '*') {
    s.inBlockComment  = true;
    i                += 2;
    return true;
  }

  return false;
}

static bool advanceInsideToken(const QString& code, int n, int& i, bool isLua, TransformScanner& s)
{
  const QChar c    = code[i];
  const QChar next = (i + 1 < n) ? code[i + 1] : QChar();

  if (s.inLineComment) {
    if (c == '\n')
      s.inLineComment = false;

    ++i;
    return true;
  }

  if (s.inBlockComment) {
    const bool luaEnd = (isLua && c == ']' && next == ']');
    const bool cEnd   = (!isLua && c == '*' && next == '/');
    if (luaEnd || cEnd) {
      s.inBlockComment  = false;
      i                += 2;
      return true;
    }
    ++i;
    return true;
  }

  if (s.inStr) {
    if (c == '\\' && i + 1 < n) {
      i += 2;
      return true;
    }
    if (c == s.quote)
      s.inStr = false;

    ++i;
    return true;
  }

  return false;
}

static bool identifierIsFreeValueRef(const QString& code, int n, int& i)
{
  const auto isIdCont = [](QChar c) {
    return c.isLetterOrNumber() || c == '_';
  };

  const int start = i;
  while (i < n && isIdCont(code[i]))
    ++i;

  const QStringView ident(code.constData() + start, i - start);
  if (ident != QLatin1String("value"))
    return false;

  const QChar prev = start > 0 ? code[start - 1] : QChar();
  return prev != '.' && prev != ':';
}

static bool transformBodyReferencesValue(const QString& code, int language)
{
  if (code.isEmpty())
    return true;

  const int n      = code.size();
  const bool isLua = (language == 1);
  TransformScanner s;
  int i = 0;

  const auto isIdStart = [](QChar c) {
    return c.isLetter() || c == '_';
  };

  while (i < n) {
    if (advanceInsideToken(code, n, i, isLua, s))
      continue;

    if (tryEnterComment(code, n, i, isLua, s))
      continue;

    const QChar c = code[i];
    if (c == '"' || c == '\'' || (isLua && c == '`')) {
      s.inStr = true;
      s.quote = c;
      ++i;
      continue;
    }

    if (isIdStart(c)) {
      if (identifierIsFreeValueRef(code, n, i))
        return true;

      continue;
    }

    ++i;
  }

  return false;
}

void DataModel::ProjectModel::resolveDatasetVirtualFlags()
{
  for (auto& group : m_groups) {
    for (auto& dataset : group.datasets) {
      if (dataset.virtual_)
        continue;

      if (dataset.transformCode.isEmpty())
        continue;

      const int lang = dataset.transformLanguage < 0 ? 0 : dataset.transformLanguage;
      if (!transformBodyReferencesValue(dataset.transformCode, lang))
        dataset.virtual_ = true;
    }
  }
}

void DataModel::ProjectModel::loadWidgetSettingsAndWorkspaces(const QJsonObject& json)
{
  m_widgetSettings  = json.value(Keys::WidgetSettings).toObject();
  m_treeExpansion   = json.value(Keys::TreeExpansion).toObject();
  m_diagramCollapse = json.value(Keys::DiagramCollapse).toObject();

  m_workspaces.clear();
  m_workspaceFolders.clear();
  m_groupFolders.clear();
  m_tableFolders.clear();
  m_customizeWorkspaces = json.value(Keys::CustomizeWorkspaces).toBool(false);

  if (m_customizeWorkspaces && json.contains(Keys::Workspaces)) {
    const auto wsArray = json.value(Keys::Workspaces).toArray();
    for (const auto& val : wsArray) {
      DataModel::Workspace ws;
      if (DataModel::read(ws, val.toObject()))
        m_workspaces.push_back(ws);
    }

    int collisions = 0;
    int nextId     = WorkspaceIds::UserStart;
    for (const auto& ws : std::as_const(m_workspaces))
      if (ws.workspaceId >= WorkspaceIds::UserStart && ws.workspaceId >= nextId)
        nextId = ws.workspaceId + 1;

    for (auto& ws : m_workspaces) {
      if (ws.workspaceId >= WorkspaceIds::AutoStart && ws.workspaceId < WorkspaceIds::UserStart) {
        ws.workspaceId = nextId++;
        ++collisions;
      }
    }

    if (collisions > 0) {
      const int n = collisions;
      QTimer::singleShot(0, this, [n] {
        DataModel::NotificationCenter::instance().postWarning(
          QStringLiteral("ProjectModel"),
          tr("Workspace IDs remapped on load"),
          tr("%1 custom workspace ID(s) overlapped the new reserved auto range and were "
             "moved into the user range. Save the project to make the remap permanent.")
            .arg(n));
      });
    }
  }

  if (m_customizeWorkspaces && json.contains(Keys::WorkspaceFolders)) {
    const auto folderArray = json.value(Keys::WorkspaceFolders).toArray();
    for (const auto& val : folderArray) {
      DataModel::WorkspaceFolder folder;
      if (DataModel::read(folder, val.toObject()))
        m_workspaceFolders.push_back(folder);
    }
  }

  sanitizeWorkspaceFolders();

  if (json.contains(Keys::GroupFolders)) {
    const auto folderArray = json.value(Keys::GroupFolders).toArray();
    for (const auto& val : folderArray) {
      DataModel::GroupFolder folder;
      if (DataModel::read(folder, val.toObject()))
        m_groupFolders.push_back(folder);
    }
  }

  sanitizeGroupFolders();

  m_hiddenGroupIds.clear();
  if (json.contains(Keys::HiddenGroups)) {
    const auto hiddenArray = json.value(Keys::HiddenGroups).toArray();
    for (const auto& val : hiddenArray)
      m_hiddenGroupIds.insert(val.toInt());
  }

  m_tables.clear();
  if (json.contains(Keys::Tables)) {
    const auto tablesArray = json.value(Keys::Tables).toArray();
    for (const auto& val : tablesArray) {
      DataModel::TableDef table;
      if (DataModel::read(table, val.toObject()))
        m_tables.push_back(table);
    }
  }

  if (json.contains(Keys::TableFolders)) {
    const auto folderArray = json.value(Keys::TableFolders).toArray();
    for (const auto& val : folderArray) {
      DataModel::TableFolder folder;
      if (DataModel::read(folder, val.toObject()))
        m_tableFolders.push_back(folder);
    }
  }

  sanitizeTableFolders();

  m_mqttPublisher = json.value(Keys::MqttPublisher).toObject();
  Q_EMIT mqttPublisherChanged();
}

void DataModel::ProjectModel::loadPointCount(const QJsonObject& json)
{
  m_pointCount = UI::Dashboard::instance().points();
  if (json.contains(Keys::PointCount)) {
    const int pts = json.value(Keys::PointCount).toInt();
    if (pts > 0)
      m_pointCount = pts;
  } else if (m_widgetSettings.contains(QStringLiteral("__pointCount__"))) {
    const int pts = m_widgetSettings.value(QStringLiteral("__pointCount__")).toInt();
    if (pts > 0)
      m_pointCount = pts;

    m_widgetSettings.remove(QStringLiteral("__pointCount__"));
  }

  if (AppState::instance().operationMode() == SerialStudio::ProjectFile)
    UI::Dashboard::instance().setPoints(m_pointCount);
}

void DataModel::ProjectModel::loadPlotTimeRange(const QJsonObject& json)
{
  m_plotTimeRange = UI::Dashboard::instance().plotTimeRange();
  if (json.contains(Keys::PlotTimeRange)) {
    const double secs = SerialStudio::toDouble(json.value(Keys::PlotTimeRange));
    if (secs > 0)
      m_plotTimeRange = secs;
  }

  if (AppState::instance().operationMode() == SerialStudio::ProjectFile)
    UI::Dashboard::instance().setPlotTimeRange(m_plotTimeRange);
}

void DataModel::ProjectModel::migrateLegacyLayoutKeys()
{
  const auto keys = m_widgetSettings.keys();
  for (const auto& key : keys) {
    const bool isOldFormat = key.startsWith(QStringLiteral("__layout__:"));
    const bool isNewFormat = key.startsWith(QStringLiteral("layout:"));
    if (!isOldFormat && !isNewFormat)
      continue;

    auto entry = m_widgetSettings.value(key).toObject();
    if (!entry.contains(QStringLiteral("data")))
      continue;

    QJsonObject cleaned;
    cleaned[QStringLiteral("data")] = entry[QStringLiteral("data")];

    if (!isOldFormat) {
      m_widgetSettings.insert(key, cleaned);
      continue;
    }

    m_widgetSettings.remove(key);
    auto id = key.mid(11);
    id.chop(2);
    m_widgetSettings.insert(QStringLiteral("layout:") + id, cleaned);
  }
}

void DataModel::ProjectModel::migrateLegacyDashboardLayout(const QJsonObject& json)
{
  if (!json.contains(QStringLiteral("dashboardLayout")))
    return;

  const int legacy_group_id = json.value(QStringLiteral("activeGroupId")).toInt(-1);
  const auto layout         = json.value(QStringLiteral("dashboardLayout")).toObject();
  if (legacy_group_id >= 0 && !layout.isEmpty())
    m_widgetSettings.insert(Keys::layoutKey(legacy_group_id), layout);

  if (legacy_group_id >= 0)
    m_widgetSettings.insert(Keys::kActiveGroupSubKey, legacy_group_id);
}

bool DataModel::ProjectModel::migrateLegacySeparator(const QJsonObject& json)
{
  if (!json.contains("separator"))
    return false;

  const auto separator = json.value("separator").toString();
  static QRegularExpression legacyRegex(
    R"(function\s+parse\s*\(\s*frame\s*,\s*separator\s*\)\s*\{\s*return\s+frame\.split\(separator\);\s*\})");

  if (m_sources.empty() || !legacyRegex.match(m_sources[0].frameParserCode).hasMatch())
    return false;

  if (separator.length() > 1)
    m_sources[0].frameParserCode =
      QStringLiteral("/**\n * Automatically migrated frame parser function.\n"
                     " */\nfunction parse(frame) {\n    return frame.split(\"%1\");\n}")
        .arg(separator);
  else
    m_sources[0].frameParserCode =
      QStringLiteral("/**\n * Automatically migrated frame parser function.\n"
                     " */\nfunction parse(frame) {\n    return frame.split(\'%1\');\n}")
        .arg(separator);

  if (!m_suppressMessageBoxes)
    Misc::Utilities::showMessageBox(
      tr("Legacy frame parser function updated"),
      tr("Your project used a legacy frame parser function with a 'separator' argument. "
         "It has been automatically migrated to the new format."),
      QMessageBox::Information);
  else
    qWarning() << "[ProjectModel] Legacy frame parser function automatically migrated";

  if (!m_filePath.isEmpty())
    (void)saveJsonFile(false);

  return true;
}

void DataModel::ProjectModel::emitProjectLoadedSignals()
{
  Q_EMIT groupsChanged();
  Q_EMIT actionsChanged();
  Q_EMIT sourcesChanged();
  Q_EMIT titleChanged();
  Q_EMIT jsonFileChanged();
  Q_EMIT tablesChanged();
  Q_EMIT editorWorkspacesChanged();
  Q_EMIT activeWorkspacesChanged();
  Q_EMIT customizeWorkspacesChanged();
  Q_EMIT frameDetectionChanged();
  Q_EMIT frameParserCodeChanged();
  Q_EMIT controlScriptChanged();
  Q_EMIT pointCountChanged();
  Q_EMIT plotTimeRangeChanged();
  Q_EMIT changeDrivenTransformsChanged();

  if (!m_silentReload)
    Q_EMIT sourceStructureChanged();

  if (m_widgetSettings.contains(Keys::kActiveGroupSubKey))
    Q_EMIT activeGroupIdChanged();

  if (!m_widgetSettings.isEmpty())
    Q_EMIT widgetSettingsChanged();
}

void DataModel::ProjectModel::persistLegacyMigration()
{
  qInfo() << "[ProjectModel] Migrating legacy project to current schema, saving...";
  if (!writeProjectFile(m_filePath))
    qWarning() << "[ProjectModel] Legacy-migration save failed";
}

static QJsonArray serializeFolders(const std::vector<Folder>& folders)
{
  QJsonArray arr;
  for (const auto& f : std::as_const(folders))
    arr.append(DataModel::serialize(f));

  return arr;
}

bool DataModel::ProjectModel::askSave()
{
  if (!modified())
    return true;

  const auto opMode = AppState::instance().operationMode();
  if (opMode != SerialStudio::ProjectFile && m_filePath.isEmpty())
    return true;

  if (m_suppressMessageBoxes) {
    qWarning() << "[ProjectModel] Discarding unsaved changes (API mode)";
    if (jsonFilePath().isEmpty())
      newJsonFile();
    else {
      const auto path = m_filePath;
      m_silentReload  = true;
      m_filePath.clear();
      openJsonFile(path);
      m_silentReload = false;
      if (opMode != SerialStudio::ProjectFile)
        AppState::instance().setOperationMode(opMode);
    }

    return true;
  }

  auto ret =
    Misc::Utilities::showMessageBox(tr("Do you want to save your changes?"),
                                    tr("You have unsaved modifications in this project!"),
                                    QMessageBox::Question,
                                    APP_NAME,
                                    QMessageBox::Save | QMessageBox::Discard | QMessageBox::Cancel);

  if (ret == QMessageBox::Cancel)
    return false;

  if (ret == QMessageBox::Discard) {
    if (jsonFilePath().isEmpty())
      newJsonFile();
    else {
      const auto path = m_filePath;
      m_silentReload  = true;
      m_filePath.clear();
      openJsonFile(path);
      m_silentReload = false;
      if (opMode != SerialStudio::ProjectFile)
        AppState::instance().setOperationMode(opMode);
    }

    return true;
  }

  return saveJsonFile(false);
}

bool DataModel::ProjectModel::saveJsonFile(const bool askPath)
{
  if (!validateProject(m_suppressMessageBoxes))
    return false;

  if (jsonFilePath().isEmpty() || askPath) {
    auto* dialog = new QFileDialog(qApp->activeWindow(),
                                   tr("Save Serial Studio Project"),
                                   jsonProjectsPath() + "/" + title() + ".ssproj",
                                   tr("Serial Studio Project Files (*.ssproj)"));

    dialog->setAcceptMode(QFileDialog::AcceptSave);
    dialog->setFileMode(QFileDialog::AnyFile);
    dialog->setAttribute(Qt::WA_DeleteOnClose);

    auto accepted = std::make_shared<bool>(false);
    connect(dialog, &QFileDialog::fileSelected, this, [this, accepted](const QString& path) {
      if (path.isEmpty())
        return;

      *accepted = true;

      QMetaObject::invokeMethod(
        this,
        [this, path]() {
          QString finalPath = path;
          if (!finalPath.endsWith(QStringLiteral(".ssproj"), Qt::CaseInsensitive))
            finalPath += QStringLiteral(".ssproj");

          const QString chosenTitle = QFileInfo(finalPath).completeBaseName();
          if (m_title == tr("Untitled Project") && !chosenTitle.isEmpty()
              && chosenTitle != m_title) {
            m_title = chosenTitle;
            Q_EMIT titleChanged();
          }

          m_filePath = finalPath;
          (void)finalizeProjectSave();
        },
        Qt::QueuedConnection);
    });

    connect(dialog, &QFileDialog::finished, this, [this, accepted](int) {
      Q_EMIT saveDialogCompleted(*accepted);
    });

    dialog->open();
    return false;
  }

  return finalizeProjectSave();
}

bool DataModel::ProjectModel::apiSaveJsonFile(const QString& path)
{
  if (path.isEmpty())
    return false;

  if (m_title.isEmpty()) {
    qWarning() << "[ProjectModel] Project title cannot be empty";
    return false;
  }

  if (groupCount() <= 0) {
    qWarning() << "[ProjectModel] Project needs at least one group";
    return false;
  }

  const bool hasImageGroup = std::any_of(m_groups.begin(), m_groups.end(), [](const Group& g) {
    return g.widget == QLatin1String("image");
  });

  if (datasetCount() <= 0 && !hasImageGroup) {
    qWarning() << "[ProjectModel] Project needs at least one dataset";
    return false;
  }

  QString finalPath = path;
  if (!finalPath.endsWith(QStringLiteral(".ssproj"), Qt::CaseInsensitive))
    finalPath += QStringLiteral(".ssproj");

  m_filePath = finalPath;
  return finalizeProjectSave();
}

QJsonObject DataModel::ProjectModel::serializeToJson() const
{
  QJsonObject json;
  json.insert(Keys::Title, m_title);
  json.insert(Keys::PointCount, m_pointCount);
  json.insert(Keys::PlotTimeRange, m_plotTimeRange);
  json.insert(Keys::ChangeDrivenTransforms, m_changeDrivenTransforms);
  json.insert(Keys::HexadecimalDelimiters, m_hexadecimalDelimiters);

  const QString writer  = DataModel::current_writer_version();
  const QString creator = m_writerVersionAtCreation.isEmpty() ? writer : m_writerVersionAtCreation;
  json.insert(Keys::SchemaVersion, DataModel::kSchemaVersion);
  json.insert(Keys::WriterVersion, writer);
  json.insert(Keys::WriterVersionAtCreation, creator);
  json.insert(Keys::NextUniqueId, m_nextUniqueId);

  if (!m_passwordHash.isEmpty())
    json.insert(Keys::PasswordHash, m_passwordHash);

  if (m_apiCallAllowFullSurface)
    json.insert(Keys::ApiCallAllowFullSurface, true);

  if (!m_controlScriptCode.isEmpty())
    json.insert(Keys::ControlScriptCode, m_controlScriptCode);

  QJsonArray groupArray;
  for (const auto& group : std::as_const(m_groups))
    groupArray.append(DataModel::serialize(group));

  json.insert(Keys::Groups, groupArray);

  if (!m_groupFolders.empty())
    json.insert(Keys::GroupFolders, serializeFolders(m_groupFolders));

  QJsonArray actionsArray;
  for (const auto& action : std::as_const(m_actions))
    actionsArray.append(DataModel::serialize(action));

  json.insert(Keys::Actions, actionsArray);

  QJsonArray sourcesArray;
  for (const auto& source : std::as_const(m_sources))
    sourcesArray.append(DataModel::serialize(source));

  json.insert(Keys::Sources, sourcesArray);

  if (m_customizeWorkspaces) {
    json.insert(Keys::CustomizeWorkspaces, true);

    QJsonArray workspacesArray;
    for (const auto& ws : std::as_const(m_workspaces))
      workspacesArray.append(DataModel::serialize(ws));

    json.insert(Keys::Workspaces, workspacesArray);

    QJsonArray foldersArray;
    for (const auto& folder : std::as_const(m_workspaceFolders))
      foldersArray.append(DataModel::serialize(folder));

    if (!foldersArray.isEmpty())
      json.insert(Keys::WorkspaceFolders, foldersArray);
  }

  if (!m_hiddenGroupIds.isEmpty()) {
    QJsonArray hiddenArray;
    for (const int id : std::as_const(m_hiddenGroupIds))
      hiddenArray.append(id);

    json.insert(Keys::HiddenGroups, hiddenArray);
  }

  if (!m_tables.empty()) {
    QJsonArray tablesArray;
    for (const auto& table : std::as_const(m_tables))
      tablesArray.append(DataModel::serialize(table));

    json.insert(Keys::Tables, tablesArray);
  }

  if (!m_tableFolders.empty())
    json.insert(Keys::TableFolders, serializeFolders(m_tableFolders));

  if (!m_widgetSettings.isEmpty())
    json.insert(Keys::WidgetSettings, m_widgetSettings);

  if (!m_treeExpansion.isEmpty())
    json.insert(Keys::TreeExpansion, m_treeExpansion);

  if (!m_diagramCollapse.isEmpty())
    json.insert(Keys::DiagramCollapse, m_diagramCollapse);

  if (!m_mqttPublisher.isEmpty())
    json.insert(Keys::MqttPublisher, m_mqttPublisher);

  return json;
}

void DataModel::ProjectModel::autoSave()
{
  if (m_autoSaveSuspended)
    return;

  if (m_filePath.isEmpty() || m_locked || !m_modified)
    return;

  if (AppState::instance().operationMode() != SerialStudio::ProjectFile)
    return;

  if (!writeProjectFile(m_filePath)) {
    qWarning() << "[ProjectModel] Auto-save failed";
    return;
  }

  setModified(false);

  if (m_runtimeDirty)
    syncRuntime();
}

void DataModel::ProjectModel::syncRuntime()
{
  m_runtimeDirty = false;
  DataModel::FrameBuilder::instance().syncFromProjectModel();
}

void DataModel::ProjectModel::flushAutoSave()
{
  if (m_autoSaveTimer && m_autoSaveTimer->isActive())
    m_autoSaveTimer->stop();

  autoSave();
}

void DataModel::ProjectModel::scheduleAutoSave()
{
  if (m_autoSaveSuspended || m_filePath.isEmpty() || m_locked)
    return;

  if (AppState::instance().operationMode() != SerialStudio::ProjectFile)
    return;

  m_autoSaveTimer->start();
}

void DataModel::ProjectModel::setAutoSaveSuspended(bool suspend)
{
  if (m_autoSaveSuspended == suspend)
    return;

  m_autoSaveSuspended = suspend;
  if (suspend && m_autoSaveTimer)
    m_autoSaveTimer->stop();
}

bool DataModel::ProjectModel::writeProjectFile(const QString& path)
{
  Q_ASSERT(!path.isEmpty());

  QSaveFile file(path);
  if (!file.open(QFile::WriteOnly)) {
    qWarning() << "[ProjectModel] File open error:" << file.errorString();
    return false;
  }

  const QByteArray payload = QJsonDocument(serializeToJson()).toJson(QJsonDocument::Indented);
  if (file.write(payload) != payload.size()) {
    qWarning() << "[ProjectModel] Short write:" << file.errorString();
    file.cancelWriting();
    return false;
  }

  if (!file.commit()) {
    qWarning() << "[ProjectModel] Commit failed:" << file.errorString();
    return false;
  }

  watchProjectFile();
  return true;
}

QByteArray DataModel::ProjectModel::hashProjectFile(const QString& path)
{
  QFile file(path);
  if (!file.open(QFile::ReadOnly))
    return {};

  return QCryptographicHash::hash(file.readAll(), QCryptographicHash::Sha256);
}

void DataModel::ProjectModel::watchProjectFile()
{
  const auto watched = m_fileWatcher->files();
  if (!watched.isEmpty())
    m_fileWatcher->removePaths(watched);

  m_diskFileHash.clear();
  if (m_filePath.isEmpty() || !QFile::exists(m_filePath))
    return;

  m_fileWatcher->addPath(m_filePath);
  m_diskFileHash = hashProjectFile(m_filePath);
}

void DataModel::ProjectModel::resolveDiskFileChange()
{
  m_diskCheckPending = false;
  if (m_diskPromptActive || m_filePath.isEmpty())
    return;

  if (!QFile::exists(m_filePath)) {
    m_diskFileHash.clear();
    m_modified = true;
    Q_EMIT modifiedChanged();
    Q_EMIT projectFileChangedOnDisk();
    DataModel::NotificationCenter::instance().postWarning(
      QStringLiteral("ProjectModel"),
      tr("Project file removed from disk"),
      tr("%1 was deleted or renamed by another program. Save the project to recreate it.")
        .arg(jsonFileName()));
    return;
  }

  if (!m_fileWatcher->files().contains(m_filePath))
    m_fileWatcher->addPath(m_filePath);

  const auto hash = hashProjectFile(m_filePath);
  if (hash.isEmpty() || hash == m_diskFileHash)
    return;

  m_diskFileHash = hash;
  Q_EMIT projectFileChangedOnDisk();

  if (m_suppressMessageBoxes) {
    qWarning() << "[ProjectModel] Project file changed on disk; keeping in-memory state";
    m_modified = true;
    Q_EMIT modifiedChanged();
    DataModel::NotificationCenter::instance().postWarning(
      QStringLiteral("ProjectModel"),
      tr("Project file changed on disk"),
      tr("%1 was modified by another program. The in-memory project was kept; reopen the "
         "file to load the external changes.")
        .arg(jsonFileName()));
    return;
  }

  promptDiskFileReload();
}

void DataModel::ProjectModel::promptDiskFileReload()
{
  m_diskPromptActive  = true;
  const auto question = m_modified ? tr("The project file was modified by another program.\n\n"
                                        "Reload it and discard your unsaved changes?")
                                   : tr("The project file was modified by another program.\n\n"
                                        "Reload it?");
  const auto ret      = Misc::Utilities::showMessageBox(tr("Project file changed on disk"),
                                                   question,
                                                   QMessageBox::Question,
                                                   APP_NAME,
                                                   QMessageBox::Yes | QMessageBox::No);
  m_diskPromptActive  = false;

  if (ret != QMessageBox::Yes) {
    m_modified = true;
    Q_EMIT modifiedChanged();
    return;
  }

  const auto path = m_filePath;
  m_filePath.clear();
  if (!openJsonFile(path))
    qWarning() << "[ProjectModel] Reload after on-disk change failed:" << path;
}

bool DataModel::ProjectModel::finalizeProjectSave()
{
  resolveDatasetTransformLanguages();
  resolveDatasetVirtualFlags();

  if (!writeProjectFile(m_filePath)) {
    if (!m_suppressMessageBoxes)
      Misc::Utilities::showMessageBox(tr("File save error"), m_filePath, QMessageBox::Critical);

    return false;
  }

  AppState::instance().setOperationMode(SerialStudio::ProjectFile);
  setModified(false);
  Q_EMIT jsonFileChanged();
  return true;
}

void DataModel::ProjectModel::addSource()
{
#ifndef BUILD_COMMERCIAL
  if (!m_sources.empty()) {
    if (!m_suppressMessageBoxes)
      Misc::Utilities::showMessageBox(
        tr("Multiple data sources require a Pro license"),
        tr("Serial Studio Pro allows connecting to multiple devices simultaneously. "
           "Please upgrade to unlock this feature."),
        QMessageBox::Information);

    return;
  }
#endif

  const int newId = static_cast<int>(m_sources.size());

  DataModel::Source source;
  source.sourceId              = newId;
  source.title                 = tr("Device %1").arg(QChar('A' + newId));
  source.busType               = static_cast<int>(SerialStudio::BusType::UART);
  source.frameStart            = m_frameStartSequence;
  source.frameEnd              = m_frameEndSequence;
  source.checksumAlgorithm     = m_checksumAlgorithm;
  source.frameDetection        = static_cast<int>(m_frameDetection);
  source.decoderMethod         = static_cast<int>(m_frameDecoder);
  source.hexadecimalDelimiters = m_hexadecimalDelimiters;
  seedDefaultFrameParser(source);

  m_sources.push_back(source);
  setModified(true);
  Q_EMIT sourcesChanged();
  Q_EMIT sourceStructureChanged();
  Q_EMIT sourceAdded(newId);
}

void DataModel::ProjectModel::deleteSource(int sourceId, bool confirm)
{
#ifndef BUILD_COMMERCIAL
  (void)sourceId;
  (void)confirm;
  return;
#else
  if (sourceId <= 0 || sourceId >= static_cast<int>(m_sources.size()))
    return;

  if (confirm && !m_suppressMessageBoxes) {
    const auto ret = Misc::Utilities::showMessageBox(
      tr("Do you want to delete data source \"%1\"?").arg(m_sources[sourceId].title),
      tr("Groups using this source will move to the default source. "
         "This action cannot be undone."),
      QMessageBox::Question,
      APP_NAME,
      QMessageBox::Yes | QMessageBox::No);
    if (ret != QMessageBox::Yes)
      return;
  }

  m_sources.erase(m_sources.begin() + sourceId);

  const auto remapSourceId = [sourceId](int& id) {
    if (id == sourceId)
      id = 0;
    else if (id > sourceId)
      --id;
  };

  for (auto& group : m_groups) {
    remapSourceId(group.sourceId);
    for (auto& widget : group.outputWidgets)
      remapSourceId(widget.sourceId);
  }

  for (auto& action : m_actions)
    remapSourceId(action.sourceId);

  for (size_t i = 0; i < m_sources.size(); ++i)
    m_sources[i].sourceId = static_cast<int>(i);

  setModified(true);
  Q_EMIT groupsChanged();
  Q_EMIT sourcesChanged();
  Q_EMIT sourceStructureChanged();
  Q_EMIT sourceDeleted();
#endif
}

void DataModel::ProjectModel::duplicateSource(int sourceId)
{
#ifndef BUILD_COMMERCIAL
  (void)sourceId;
  return;
#else
  if (sourceId < 0 || sourceId >= static_cast<int>(m_sources.size()))
    return;

  DataModel::Source copy  = m_sources[sourceId];
  copy.sourceId           = static_cast<int>(m_sources.size());
  copy.connectionSettings = QJsonObject();

  QStringList existingTitles;
  existingTitles.reserve(static_cast<int>(m_sources.size()));
  for (const auto& s : m_sources)
    existingTitles.append(s.title);

  copy.title = nextDuplicateTitle(m_sources[sourceId].title, existingTitles);

  m_sources.push_back(copy);
  setModified(true);
  Q_EMIT sourcesChanged();
  Q_EMIT sourceStructureChanged();
  Q_EMIT sourceAdded(copy.sourceId);
#endif
}

void DataModel::ProjectModel::updateSource(int sourceId,
                                           const DataModel::Source& source,
                                           const bool rebuildTree)
{
  if (sourceId < 0 || sourceId >= static_cast<int>(m_sources.size()))
    return;

  m_sources[sourceId]          = source;
  m_sources[sourceId].sourceId = sourceId;

  if (sourceId == 0) {
    m_frameStartSequence    = source.frameStart;
    m_frameEndSequence      = source.frameEnd;
    m_checksumAlgorithm     = source.checksumAlgorithm;
    m_hexadecimalDelimiters = source.hexadecimalDelimiters;
    m_frameDetection        = static_cast<SerialStudio::FrameDetection>(source.frameDetection);
    m_frameDecoder          = static_cast<SerialStudio::DecoderMethod>(source.decoderMethod);
    Q_EMIT frameDetectionChanged();
  }

  setModified(true);
  if (rebuildTree)
    Q_EMIT sourcesChanged();

  Q_EMIT sourceChanged(sourceId);
}

void DataModel::ProjectModel::updateSourceTitle(int sourceId,
                                                const QString& title,
                                                const bool rebuildTree)
{
  if (sourceId < 0 || sourceId >= static_cast<int>(m_sources.size()))
    return;

  m_sources[sourceId].title = title.simplified();
  setModified(true);
  if (rebuildTree)
    Q_EMIT sourcesChanged();
}

void DataModel::ProjectModel::updateSourceBusType(int sourceId, int busType)
{
  if (sourceId < 0 || sourceId >= static_cast<int>(m_sources.size()))
    return;

  m_sources[sourceId].busType = busType;
  setModified(true);
  Q_EMIT sourcesChanged();
  Q_EMIT sourceStructureChanged();
}

void DataModel::ProjectModel::updateSourceFrameParser(int sourceId, const QString& code)
{
  if (sourceId < 0 || sourceId >= static_cast<int>(m_sources.size()))
    return;

  m_sources[sourceId].frameParserCode = code;
  DataModel::FrameParser::instance().setSourceCode(sourceId, code);
  setModified(true);

  Q_EMIT sourceFrameParserCodeChanged(sourceId);
}

void DataModel::ProjectModel::captureSourceSettings(int sourceId)
{
  if (sourceId < 0 || sourceId >= static_cast<int>(m_sources.size()))
    return;

  const auto busType     = static_cast<SerialStudio::BusType>(m_sources[sourceId].busType);
  IO::HAL_Driver* driver = IO::ConnectionManager::instance().uiDriverForBusType(busType);
  if (!driver)
    return;

  QJsonObject settings;
  for (const auto& prop : driver->driverProperties())
    settings.insert(prop.key, QJsonValue::fromVariant(prop.value));

  const auto deviceId = driver->deviceIdentifier();
  if (!deviceId.isEmpty())
    settings.insert(QStringLiteral("deviceId"), deviceId);

  m_sources[sourceId].connectionSettings = settings;
  setModified(true);
}

void DataModel::ProjectModel::restoreSourceSettings(int sourceId)
{
  if (sourceId < 0 || sourceId >= static_cast<int>(m_sources.size()))
    return;

  const auto& source = m_sources[sourceId];
  if (source.connectionSettings.isEmpty())
    return;

  IO::HAL_Driver* driver = IO::ConnectionManager::instance().driverForEditing(sourceId);
  if (!driver)
    return;

  driver->applyConnectionSettings(source.connectionSettings);
}

void DataModel::ProjectModel::setSource0ConnectionSettings(const QJsonObject& settings)
{
  if (m_sources.empty())
    return;

  m_sources[0].connectionSettings = settings;
  setModified(true);
}

void DataModel::ProjectModel::setSource0BusType(int busType)
{
  if (m_sources.empty())
    return;

  m_sources[0].busType = busType;
  setModified(true);
}

void DataModel::ProjectModel::setFrameParserCode(const QString& code)
{
  if (m_sources.empty() || code == m_sources[0].frameParserCode)
    return;

  m_sources[0].frameParserCode = code;
  setModified(true);
  Q_EMIT frameParserCodeChanged();
  Q_EMIT sourceFrameParserCodeChanged(0);
}

void DataModel::ProjectModel::setFrameParserLanguage(int language)
{
  if (m_sources.empty() || language == m_sources[0].frameParserLanguage)
    return;

  m_sources[0].frameParserLanguage = language;
  setModified(true);
  Q_EMIT frameParserLanguageChanged();
  Q_EMIT sourceFrameParserLanguageChanged(0);
}

void DataModel::ProjectModel::updateSourceFrameParserLanguage(int sourceId, int language)
{
  auto it =
    std::find_if(m_sources.begin(), m_sources.end(), [sourceId](const DataModel::Source& src) {
      return src.sourceId == sourceId;
    });

  if (it == m_sources.end())
    return;

  if (it->frameParserLanguage == language)
    return;

  it->frameParserLanguage = language;
  setModified(true);

  if (sourceId == 0)
    Q_EMIT frameParserLanguageChanged();

  Q_EMIT sourceFrameParserLanguageChanged(sourceId);
}

void DataModel::ProjectModel::setFrameParserTemplate(const QString& templateId)
{
  if (m_sources.empty())
    return;

  updateSourceFrameParserTemplate(m_sources[0].sourceId, templateId);
}

void DataModel::ProjectModel::setFrameParserParams(const QJsonObject& params)
{
  if (m_sources.empty())
    return;

  updateSourceFrameParserParams(m_sources[0].sourceId, params);
}

void DataModel::ProjectModel::updateSourceFrameParserTemplate(int sourceId,
                                                              const QString& templateId)
{
  auto it =
    std::find_if(m_sources.begin(), m_sources.end(), [sourceId](const DataModel::Source& src) {
      return src.sourceId == sourceId;
    });

  if (it == m_sources.end() || it->frameParserTemplate == templateId)
    return;

  it->frameParserTemplate = templateId;
  setModified(true);

  if (sourceId == 0)
    Q_EMIT frameParserTemplateChanged();

  Q_EMIT sourceFrameParserTemplateChanged(sourceId);
}

void DataModel::ProjectModel::updateSourceFrameParserParams(int sourceId, const QJsonObject& params)
{
  auto it =
    std::find_if(m_sources.begin(), m_sources.end(), [sourceId](const DataModel::Source& src) {
      return src.sourceId == sourceId;
    });

  if (it == m_sources.end() || it->frameParserParams == params)
    return;

  it->frameParserParams = params;
  setModified(true);

  if (sourceId == 0)
    Q_EMIT frameParserParamsChanged();

  Q_EMIT sourceFrameParserParamsChanged(sourceId);
}

void DataModel::ProjectModel::storeFrameParserCode(int sourceId, const QString& code)
{
  if (sourceId < 0 || sourceId >= static_cast<int>(m_sources.size()))
    return;

  if (m_sources[sourceId].frameParserCode == code)
    return;

  m_sources[sourceId].frameParserCode = code;
  setModified(true);
}

int DataModel::ProjectModel::findTableIndexByPath(const QString& tablePath) const
{
  for (size_t i = 0; i < m_tables.size(); ++i)
    if (tablePathFor(m_tables[i]) == tablePath)
      return static_cast<int>(i);

  return -1;
}

QString DataModel::ProjectModel::addTable(const QString& name, int parentFolderId)
{
  if (parentFolderId != -1 && !folderExists(m_tableFolders, parentFolderId))
    parentFolderId = -1;

  QString base = name.simplified().remove(QLatin1Char('/'));
  if (base.isEmpty())
    base = tr("Shared Table");

  QString unique     = base;
  int suffix         = 2;
  const auto hasLeaf = [this, parentFolderId](const QString& n) {
    for (const auto& t : m_tables)
      if (t.parentFolderId == parentFolderId && t.name == n)
        return true;

    return false;
  };

  while (hasLeaf(unique))
    unique = QStringLiteral("%1 %2").arg(base, QString::number(suffix++));

  DataModel::TableDef table;
  table.name           = unique;
  table.parentFolderId = parentFolderId;
  m_tables.push_back(table);
  setModified(true);
  Q_EMIT tablesChanged();
  return tablePathFor(table);
}

void DataModel::ProjectModel::deleteTable(const QString& name)
{
  const int idx = findTableIndexByPath(name);
  if (idx < 0)
    return;

  m_tables.erase(m_tables.begin() + idx);
  setModified(true);
  Q_EMIT tablesChanged();
}

void DataModel::ProjectModel::renameTable(const QString& oldName, const QString& newName)
{
  const QString n = newName.simplified().remove(QLatin1Char('/'));
  if (n.isEmpty())
    return;

  const int idx = findTableIndexByPath(oldName);
  if (idx < 0)
    return;

  const int parent = m_tables[static_cast<size_t>(idx)].parentFolderId;
  for (size_t i = 0; i < m_tables.size(); ++i)
    if (static_cast<int>(i) != idx && m_tables[i].parentFolderId == parent && m_tables[i].name == n)
      return;

  m_tables[static_cast<size_t>(idx)].name = n;
  setModified(true);
  Q_EMIT tablesChanged();
}

void DataModel::ProjectModel::appendTableCopyToFolder(const DataModel::TableDef& src,
                                                      int parentFolderId)
{
  QStringList taken;
  for (const auto& t : m_tables)
    if (t.parentFolderId == parentFolderId)
      taken.append(t.name);

  DataModel::TableDef copy = src;
  copy.parentFolderId      = parentFolderId;
  copy.name = taken.contains(src.name) ? nextDuplicateTitle(src.name, taken) : src.name;
  m_tables.push_back(std::move(copy));
}

void DataModel::ProjectModel::duplicateTableByPath(const QString& tablePath)
{
  const int idx = findTableIndexByPath(tablePath);
  if (idx < 0)
    return;

  const DataModel::TableDef src = m_tables[static_cast<size_t>(idx)];

  QStringList taken;
  for (const auto& t : m_tables)
    if (t.parentFolderId == src.parentFolderId)
      taken.append(t.name);

  DataModel::TableDef copy = src;
  copy.name                = nextDuplicateTitle(src.name, taken);
  m_tables.push_back(std::move(copy));

  setModified(true);
  Q_EMIT tablesChanged();
}

void DataModel::ProjectModel::addRegister(const QString& table,
                                          const QString& registerName,
                                          bool computed,
                                          const QVariant& defaultValue)
{
  const int idx = findTableIndexByPath(table);
  if (idx < 0)
    return;

  auto it = m_tables.begin() + idx;

  QString base = registerName.simplified();
  if (base.isEmpty())
    base = tr("register");

  QString unique     = base;
  int suffix         = 2;
  const auto hasName = [it](const QString& n) {
    for (const auto& r : it->registers)
      if (r.name == n)
        return true;

    return false;
  };

  while (hasName(unique))
    unique = QStringLiteral("%1_%2").arg(base, QString::number(suffix++));

  DataModel::RegisterDef reg;
  reg.name         = unique;
  reg.type         = computed ? RegisterType::Computed : RegisterType::Constant;
  reg.defaultValue = defaultValue.isValid() ? defaultValue : QVariant(0.0);
  it->registers.push_back(reg);

  setModified(true);
  Q_EMIT tablesChanged();
}

void DataModel::ProjectModel::deleteRegister(const QString& table, const QString& registerName)
{
  const int idx = findTableIndexByPath(table);
  if (idx < 0)
    return;

  auto it = m_tables.begin() + idx;

  auto rit = std::find_if(it->registers.begin(),
                          it->registers.end(),
                          [&registerName](const auto& r) { return r.name == registerName; });

  if (rit == it->registers.end())
    return;

  it->registers.erase(rit);
  setModified(true);
  Q_EMIT tablesChanged();
}

bool DataModel::ProjectModel::updateRegister(const QString& table,
                                             const QString& registerName,
                                             const QString& newName,
                                             bool computed,
                                             const QVariant& defaultValue)
{
  const int idx = findTableIndexByPath(table);
  if (idx < 0)
    return false;

  auto it = m_tables.begin() + idx;

  const QString n = newName.simplified();
  if (n.isEmpty())
    return false;

  if (n != registerName) {
    for (const auto& r : it->registers)
      if (r.name == n)
        return false;
  }

  for (auto& r : it->registers) {
    if (r.name == registerName) {
      r.name         = n;
      r.type         = computed ? RegisterType::Computed : RegisterType::Constant;
      r.defaultValue = defaultValue.isValid() ? defaultValue : r.defaultValue;
      setModified(true);
      Q_EMIT tablesChanged();
      return true;
    }
  }

  return false;
}

QVariantList DataModel::ProjectModel::registersForTable(const QString& table) const
{
  QVariantList result;
  const int idx = findTableIndexByPath(table);
  if (idx < 0)
    return result;

  auto it = m_tables.begin() + idx;

  for (const auto& r : it->registers) {
    QVariantMap row;
    row["name"] = r.name;
    row["type"] =
      r.type == RegisterType::Computed ? QStringLiteral("computed") : QStringLiteral("constant");
    row["value"]     = r.defaultValue;
    row["valueType"] = r.defaultValue.typeId() == QMetaType::Double ? QStringLiteral("number")
                                                                    : QStringLiteral("string");
    result.append(row);
  }

  return result;
}

void DataModel::ProjectModel::promptAddTable()
{
  bool ok            = false;
  const QString name = QInputDialog::getText(
    nullptr, tr("New Shared Table"), tr("Name:"), QLineEdit::Normal, tr("Shared Table"), &ok);

  if (!ok || name.trimmed().isEmpty())
    return;

  const QString added = addTable(name.trimmed());
  QTimer::singleShot(
    0, this, [added] { DataModel::ProjectEditor::instance().selectUserTable(added); });
}

void DataModel::ProjectModel::promptRenameTable(const QString& oldName)
{
  const int idx = findTableIndexByPath(oldName);
  if (idx < 0)
    return;

  const QString currentLeaf = m_tables[static_cast<size_t>(idx)].name;

  bool ok            = false;
  const QString name = QInputDialog::getText(
    nullptr, tr("Rename Table"), tr("Name:"), QLineEdit::Normal, currentLeaf, &ok);

  if (!ok || name.trimmed().isEmpty() || name.trimmed() == currentLeaf)
    return;

  renameTable(oldName, name.trimmed());
}

void DataModel::ProjectModel::promptAddRegister(const QString& table)
{
  if (table.isEmpty())
    return;

  bool okName           = false;
  const QString regName = QInputDialog::getText(nullptr,
                                                tr("New Register"),
                                                tr("Name:"),
                                                QLineEdit::Normal,
                                                QStringLiteral("register"),
                                                &okName);

  if (!okName || regName.trimmed().isEmpty())
    return;

  addRegister(table, regName.trimmed(), true, QVariant(0.0));
}

void DataModel::ProjectModel::promptRenameRegister(const QString& table,
                                                   const QString& registerName)
{
  if (table.isEmpty() || registerName.isEmpty())
    return;

  bool ok            = false;
  const QString name = QInputDialog::getText(
    nullptr, tr("Rename Register"), tr("Name:"), QLineEdit::Normal, registerName, &ok);

  if (!ok || name.trimmed().isEmpty() || name.trimmed() == registerName)
    return;

  const int idx = findTableIndexByPath(table);
  if (idx < 0)
    return;

  for (const auto& r : m_tables[static_cast<size_t>(idx)].registers) {
    if (r.name == registerName) {
      (void)updateRegister(
        table, registerName, name.trimmed(), r.type == RegisterType::Computed, r.defaultValue);
      return;
    }
  }
}

void DataModel::ProjectModel::confirmDeleteTable(const QString& name)
{
  if (name.isEmpty())
    return;

  const int idx      = findTableIndexByPath(name);
  const QString leaf = idx >= 0 ? m_tables[static_cast<size_t>(idx)].name : name;
  int registerCount  = 0;
  if (idx >= 0)
    registerCount = static_cast<int>(m_tables[static_cast<size_t>(idx)].registers.size());

  const QString informative =
    registerCount == 0
      ? tr("This action cannot be undone.")
      : tr("This removes %1 register(s) along with the table. This action cannot be undone.")
          .arg(registerCount);

  const int choice = Misc::Utilities::showMessageBox(tr("Delete \"%1\"?").arg(leaf),
                                                     informative,
                                                     QMessageBox::Warning,
                                                     tr("Delete Table"),
                                                     QMessageBox::Yes | QMessageBox::Cancel,
                                                     QMessageBox::Cancel);

  if (choice == QMessageBox::Yes)
    deleteTable(name);
}

void DataModel::ProjectModel::confirmDeleteRegister(const QString& table,
                                                    const QString& registerName)
{
  if (table.isEmpty() || registerName.isEmpty())
    return;

  const int choice = Misc::Utilities::showMessageBox(tr("Delete \"%1\"?").arg(registerName),
                                                     tr("This action cannot be undone."),
                                                     QMessageBox::Warning,
                                                     tr("Delete Register"),
                                                     QMessageBox::Yes | QMessageBox::Cancel,
                                                     QMessageBox::Cancel);

  if (choice == QMessageBox::Yes)
    deleteRegister(table, registerName);
}

void DataModel::ProjectModel::exportTableToCsv(const QString& tableName)
{
  const int idx = findTableIndexByPath(tableName);
  if (idx < 0)
    return;

  const auto it = m_tables.begin() + idx;

  const auto path = QFileDialog::getSaveFileName(
    nullptr,
    tr("Export Table"),
    QStringLiteral("%1/%2.csv").arg(Misc::WorkspaceManager::instance().path("CSV"), it->name),
    tr("CSV files (*.csv)"));

  if (path.isEmpty())
    return;

  QFile file(path);
  if (!file.open(QIODevice::WriteOnly | QIODevice::Text))
    return;

  QTextStream out(&file);
  out << "name,permissions,value\n";
  for (const auto& reg : it->registers) {
    const auto permissions = (reg.type == DataModel::RegisterType::Computed)
                             ? QStringLiteral("read-write")
                             : QStringLiteral("read-only");

    auto val = reg.defaultValue.toString();
    if (val.contains(',') || val.contains('"') || val.contains('\n'))
      val = QStringLiteral("\"%1\"").arg(val.replace('"', "\"\""));

    out << reg.name << ',' << permissions << ',' << val << '\n';
  }

  file.close();
}

void DataModel::ProjectModel::importTableFromCsv(const QString& tableName)
{
  const int idx = findTableIndexByPath(tableName);
  if (idx < 0)
    return;

  auto it = m_tables.begin() + idx;

  const auto path = QFileDialog::getOpenFileName(nullptr,
                                                 tr("Import Table"),
                                                 Misc::WorkspaceManager::instance().path("CSV"),
                                                 tr("CSV files (*.csv)"));

  if (path.isEmpty())
    return;

  QFile file(path);
  if (!file.open(QIODevice::ReadOnly | QIODevice::Text))
    return;

  QTextStream in(&file);

  if (!in.atEnd())
    in.readLine();

  constexpr int kMaxImportRows = 1'000'000;

  int imported = 0;
  int rowsRead = 0;
  while (!in.atEnd() && rowsRead < kMaxImportRows) {
    ++rowsRead;
    const auto line = in.readLine().trimmed();
    if (line.isEmpty())
      continue;

    const auto parts = line.split(',');
    if (parts.size() < 3)
      continue;

    const auto name     = parts[0].trimmed();
    const auto permsStr = parts[1].trimmed().toLower();
    auto valStr         = parts.mid(2).join(',').trimmed();
    if (valStr.size() >= 2 && valStr.startsWith('"') && valStr.endsWith('"')) {
      valStr = valStr.mid(1, valStr.size() - 2);
      valStr.replace(QStringLiteral("\"\""), QStringLiteral("\""));
    }

    if (name.isEmpty())
      continue;

    const bool computed =
      (permsStr == QStringLiteral("read-write")) || (permsStr == QStringLiteral("read/write"))
      || (permsStr == QStringLiteral("rw")) || (permsStr == QStringLiteral("computed"));

    bool isNumeric              = false;
    const double dval           = SerialStudio::toDouble(valStr, &isNumeric);
    const QVariant defaultValue = isNumeric ? QVariant(dval) : QVariant(valStr);

    auto regIt = std::find_if(it->registers.begin(),
                              it->registers.end(),
                              [&](const DataModel::RegisterDef& r) { return r.name == name; });

    if (regIt != it->registers.end()) {
      regIt->type =
        computed ? DataModel::RegisterType::Computed : DataModel::RegisterType::Constant;
      regIt->defaultValue = defaultValue;
    } else {
      DataModel::RegisterDef reg;
      reg.name = name;
      reg.type = computed ? DataModel::RegisterType::Computed : DataModel::RegisterType::Constant;
      reg.defaultValue = defaultValue;
      it->registers.push_back(reg);
    }

    ++imported;
  }

  file.close();

  if (imported > 0) {
    setModified(true);
    Q_EMIT tablesChanged();
  }
}

bool SerialStudio::datasetXAxisEnabled()
{
#ifdef BUILD_COMMERCIAL
  const auto& token = Licensing::CommercialToken::current();
  return token.isValid() && SS_LICENSE_GUARD()
      && token.featureTier() >= Licensing::FeatureTier::Trial;
#else
  return false;
#endif
}

SerialStudio::XAxisMode SerialStudio::groupXAxisMode(const DataModel::Group& g)
{
  if (g.datasets.empty())
    return XAxisMode::Time;

  const int frontXAxisId = g.datasets.front().xAxisId;
  if (frontXAxisId == DataModel::kXAxisSamples)
    return XAxisMode::Samples;

  if (frontXAxisId == DataModel::kXAxisTime)
    return XAxisMode::Time;

  return XAxisMode::Dataset;
}

SerialStudio::XAxisPolicy SerialStudio::resolveXAxisPolicy(
  const DataModel::Dataset& d, const QMap<int, DataModel::Dataset>& datasets)
{
  if (d.xAxisId == DataModel::kXAxisTime)
    return {XAxisMode::Time, -1};

  if (d.xAxisId >= 0 && datasetXAxisEnabled() && datasets.contains(d.xAxisId))
    return {XAxisMode::Dataset, d.xAxisId};

  return {XAxisMode::Samples, -1};
}

void Sessions::DatabaseManager::addTagAndAssign(int sessionId, const QString& label)
{
  if (!isOpen() || label.trimmed().isEmpty())
    return;

  setBusy(true);
  QMetaObject::invokeMethod(m_worker,
                            "addTagAndAssign",
                            Qt::QueuedConnection,
                            Q_ARG(int, sessionId),
                            Q_ARG(QString, label),
                            Q_ARG(quint64, nextToken()));
}

void Sessions::DatabaseWorker::addTagAndAssign(int sessionId, const QString& label, quint64 token)
{
  if (!m_db.isOpen() || label.trimmed().isEmpty()) {
    Q_EMIT mutationFinished(token, false, tr("Database not open or empty label"));
    return;
  }

  if (!m_db.transaction()) {
    Q_EMIT mutationFinished(token, false, m_db.lastError().text());
    return;
  }

  const QString trimmed = label.trimmed();
  QSqlQuery q(m_db);
  q.prepare("INSERT INTO tags (label) VALUES (?) ON CONFLICT(label) DO NOTHING");
  q.bindValue(0, trimmed);
  if (!q.exec()) {
    m_db.rollback();
    Q_EMIT mutationFinished(token, false, q.lastError().text());
    return;
  }

  q.prepare("SELECT tag_id FROM tags WHERE label = ? COLLATE NOCASE");
  q.bindValue(0, trimmed);
  if (!q.exec() || !q.next()) {
    m_db.rollback();
    Q_EMIT mutationFinished(token, false, q.lastError().text());
    return;
  }

  const int tagId = q.value(0).toInt();
  q.prepare("INSERT INTO session_tags (session_id, tag_id) VALUES (?, ?) "
            "ON CONFLICT(session_id, tag_id) DO NOTHING");
  q.bindValue(0, sessionId);
  q.bindValue(1, tagId);
  if (!q.exec()) {
    m_db.rollback();
    Q_EMIT mutationFinished(token, false, q.lastError().text());
    return;
  }

  if (!m_db.commit()) {
    m_db.rollback();
    Q_EMIT mutationFinished(token, false, m_db.lastError().text());
    return;
  }

  refreshTagListInternal();
  refreshSessionListInternal();
  Q_EMIT tagListRefreshed(m_tagList);
  Q_EMIT sessionListRefreshed(m_sessionList);
  Q_EMIT mutationFinished(token, true, QString());
}

Widgets::GPS::~GPS()
{
  s_instances.removeAll(this);

  const auto owned = m_network.findChildren<QNetworkReply*>();
  for (auto it = s_pending.begin(); it != s_pending.end();)
    if (owned.contains(it.value()))
      it = s_pending.erase(it);
    else
      ++it;
}

static int deviceIndexById(const QVector<ma_device_info>& list, const ma_device_id& id)
{
  for (int i = 0; i < list.size(); ++i)
    if (memcmp(&list[i].id, &id, sizeof(ma_device_id)) == 0)
      return i;

  return -1;
}

static void replaceDeviceList(ma_context* context,
                              ma_device_type type,
                              QVector<ma_device_info>& currentList,
                              const QVector<ma_device_info>& newList,
                              int& selectedIndex,
                              QVector<IO::Drivers::Audio::AudioDeviceInfo>& capabilities)
{
  ma_device_id selectedId = {};
  const bool hadSelection = selectedIndex >= 0 && selectedIndex < currentList.size();
  if (hadSelection)
    selectedId = currentList[selectedIndex].id;

  currentList = newList;
  capabilities.clear();
  for (const auto& info : std::as_const(currentList))
    capabilities.append(extractCapabilities(context, info, type));

  if (hadSelection)
    selectedIndex = deviceIndexById(currentList, selectedId);
}

[[nodiscard]] static QString updaterArchSuffix()
{
  const auto arch = QSysInfo::buildCpuArchitecture();
  if (arch == QStringLiteral("x86_64") || arch == QStringLiteral("i386"))
    return QStringLiteral("x64");

  if (arch == QStringLiteral("arm64") || arch == QStringLiteral("aarch64"))
    return QStringLiteral("arm64");

  return QString();
}

[[nodiscard]] static QString packageStampKey()
{
  constexpr qint64 kMaxStampBytes = 4096;

  QStringList candidates = {QCoreApplication::applicationDirPath()
                            + QStringLiteral("/ss-config.json")};
#if defined(Q_OS_MACOS)
  candidates.append(QCoreApplication::applicationDirPath()
                    + QStringLiteral("/../Resources/ss-config.json"));
#endif

  for (const auto& path : std::as_const(candidates)) {
    QFile file(path);
    if (file.size() > kMaxStampBytes || !file.open(QIODevice::ReadOnly))
      continue;

    const auto stamp = QJsonDocument::fromJson(file.readAll()).object();
    const auto type  = stamp.value(QStringLiteral("packageType")).toString();

#if defined(Q_OS_WIN)
    if (type == QStringLiteral("msi"))
      return QStringLiteral("windows-msi");

    if (type == QStringLiteral("portable"))
      return QStringLiteral("windows-portable");

    if (type == QStringLiteral("msix"))
      return QStringLiteral("windows-msix");
#elif defined(Q_OS_MACOS)
    if (type == QStringLiteral("dmg"))
      return QStringLiteral("osx-dmg");
#elif defined(Q_OS_LINUX)
    const auto arch = stamp.value(QStringLiteral("arch")).toString();

    QString suffix;
    if (arch == QStringLiteral("x86_64"))
      suffix = QStringLiteral("x64");
    else if (arch == QStringLiteral("arm64"))
      suffix = QStringLiteral("arm64");

    const bool linux_type = (type == QStringLiteral("appimage") || type == QStringLiteral("deb")
                             || type == QStringLiteral("rpm"));
    if (linux_type && !suffix.isEmpty())
      return QStringLiteral("linux-%1-%2").arg(type, suffix);
#endif
  }

  return QString();
}

[[nodiscard]] static bool sameRegisterValue(const DataModel::RegisterValue& a,
                                            const DataModel::RegisterValue& b)
{
  if (a.isNumeric != b.isNumeric)
    return false;

  return a.isNumeric ? (a.numericValue == b.numericValue) : (a.stringValue == b.stringValue);
}

void Licensing::OfflineLicense::deactivate()
{
  if (!m_activated)
    return;

  const int answer = Misc::Utilities::showMessageBox(
    tr("Remove the offline license from this device?"),
    tr("This deletes the local activation certificate, but it does not free up "
       "your license seat automatically.\n\nTo reuse this seat on another device, "
       "email alex@serial-studio.com with your device ID or your .ssmachine file "
       "so the seat can be released manually."),
    QMessageBox::Question,
    tr("Offline Activation"),
    QMessageBox::Yes | QMessageBox::No,
    QMessageBox::No);
  if (answer != QMessageBox::Yes)
    return;

  if (!LemonSqueezy::instance().isOnlineActivated())
    CommercialToken::clearCurrent();

  clearOfflineLicense();
}

void Licensing::OfflineLicense::resetActivationState()
{
  m_activated   = false;
  m_variantName = QString();
  m_expiresAt   = QDateTime();

API::CommandResponse API::Handlers::SystemHandler::startDemo(const QString& id,
                                                             const QJsonObject& params)
{
  Q_UNUSED(params)

  if (AppState::instance().ephemeralSession()) {
    return CommandResponse::makeError(
      id, ErrorCode::ExecutionError, QStringLiteral("Demo is unavailable in operator mode"));
  }

  if (!Misc::DemoLauncher::instance().startDemo()) {
    return CommandResponse::makeError(
      id, ErrorCode::OperationFailed, QStringLiteral("Failed to start the demo project"));
  }

  return CommandResponse::makeSuccess(id, QJsonObject());
}

void AppState::setDemoSession(const QString& demoDir)
{
  if (demoDir.isEmpty())
    m_demoSessionDir.clear();
  else
    m_demoSessionDir = QDir::cleanPath(demoDir) + QStringLiteral("/");
}

Misc::DemoLauncher& Misc::DemoLauncher::instance()
{
  static DemoLauncher singleton;
  return singleton;
}

bool Misc::DemoLauncher::startDemo()
{
  auto& state = AppState::instance();
  if (state.ephemeralSession())
    return false;

  auto& io          = IO::ConnectionManager::instance();
  const auto& model = DataModel::ProjectModel::instance();

  if (model.jsonFilePath() == demoProjectPath()) {
    state.setDemoSession(demoDirectory());
    state.setOperationMode(SerialStudio::ProjectFile);
    applyProGating();

    if (io.isConnected())
      io.disconnectDevice();

    io.connectDevice();
    return true;
  }

  QString projectPath;
  if (!stageDemoProject(projectPath)) {
    showStartFailure();
    return false;
  }

  const auto previousMode = state.operationMode();
  state.setDemoSession(demoDirectory());

  if (!DataModel::ProjectModel::instance().openJsonFile(projectPath)) {
    state.setDemoSession(QString());
    state.setOperationMode(previousMode);
    qWarning() << "[Demo] Failed to open staged demo project:" << projectPath;
    showStartFailure();
    return false;
  }

  applyProGating();

  if (io.isConnected())
    io.disconnectDevice();

  io.connectDevice();
  return true;
}

QString Misc::DemoLauncher::demoDirectory() const
{
  const auto base = QStandardPaths::writableLocation(QStandardPaths::AppDataLocation);
  return base + QStringLiteral("/demo");
}

bool Misc::DemoLauncher::stageDemoProject(QString& projectPath) const
{
  const QString dir = demoDirectory();
  if (!QDir().mkpath(dir)) {
    qWarning() << "[Demo] Cannot create demo directory:" << dir;
    return false;
  }

  const auto permissions = QFileDevice::ReadOwner | QFileDevice::WriteOwner | QFileDevice::ReadGroup
                         | QFileDevice::ReadOther;

  projectPath = demoProjectPath();
  if (QFile::exists(projectPath) && !QFile::remove(projectPath)) {
    QFile::setPermissions(projectPath, permissions);
    if (!QFile::remove(projectPath)) {
      qWarning() << "[Demo] Cannot replace staged demo project:" << projectPath;
      return false;
    }
  }

  if (!QFile::copy(QStringLiteral(":/demo/RocketLaunch.ssproj"), projectPath)) {
    qWarning() << "[Demo] Cannot stage demo project:" << projectPath;
    return false;
  }

  if (!QFile::setPermissions(projectPath, permissions)) {
    qWarning() << "[Demo] Cannot make staged demo project writable:" << projectPath;
    return false;
  }

  return true;
}

void Misc::DemoLauncher::applyProGating() const
{
  auto& model        = DataModel::ProjectModel::instance();
  const auto& groups = model.groups();

  for (size_t i = 0; i < groups.size(); ++i)
    if (groups[i].widget == QStringLiteral("painter")
        || groups[i].widget == QStringLiteral("plot3d"))
      model.setGroupEnabled(static_cast<int>(i), SerialStudio::proWidgetsEnabled());
}

void Misc::DemoLauncher::showStartFailure() const
{
  Misc::Utilities::showMessageBox(tr("Cannot start the demo"),
                                  tr("The demo project could not be staged or opened. Check "
                                     "the application data directory permissions."),
                                  QMessageBox::Critical);
}

bool ed25519_verify(const std::uint8_t signature[64],
                    const std::uint8_t* message,
                    std::size_t length,
                    const std::uint8_t publicKey[32])
{
  const std::size_t signedLength = 64 + length;
  std::vector<unsigned char> signedMessage(signedLength);
  std::vector<unsigned char> recovered(signedLength);

  std::memcpy(signedMessage.data(), signature, 64);
  if (length > 0)
    std::memcpy(signedMessage.data() + 64, message, length);

  unsigned long long recoveredLength = 0;
  const int rc                       = crypto_sign_ed25519_tweet_open(recovered.data(),
                                                &recoveredLength,
                                                signedMessage.data(),
                                                static_cast<unsigned long long>(signedLength),
                                                publicKey);

  return rc == 0 && recoveredLength == length;
}

static u32 ld32(const u8* x)
{
  u32 u = x[3];
  u     = (u << 8) | x[2];
  u     = (u << 8) | x[1];
  return (u << 8) | x[0];
}

static u64 dl64(const u8* x)
{
  u64 i, u = 0;
  FOR(i, 8) u = (u << 8) | x[i];
  return u;
}

sv st32(u8* x, u32 u)
{
  int i;
  FOR(i, 4)
  {
    x[i]   = u;
    u    >>= 8;
  }
}

static int vn(const u8* x, const u8* y, int n)
{
  u32 i, d = 0;
  FOR(i, n) d |= x[i] ^ y[i];
  return (1 & ((d - 1) >> 8)) - 1;
}

int crypto_core_salsa20(u8* out, const u8* in, const u8* k, const u8* c)
{
  core(out, in, k, c, 0);
  return 0;
}

int crypto_core_hsalsa20(u8* out, const u8* in, const u8* k, const u8* c)
{
  core(out, in, k, c, 1);
  return 0;
}

int crypto_stream_salsa20_xor(u8* c, const u8* m, u64 b, const u8* n, const u8* k)
{
  u8 z[16], x[64];
  u32 u, i;
  if (!b)
    return 0;
  FOR(i, 16) z[i] = 0;
  FOR(i, 8) z[i]  = n[i];
  while (b >= 64) {
    crypto_core_salsa20(x, z, k, sigma);
    FOR(i, 64) c[i] = (m ? m[i] : 0) ^ x[i];
    u               = 1;
    for (i = 8; i < 16; ++i) {
      u     += (u32)z[i];
      z[i]   = u;
      u    >>= 8;
    }
    b -= 64;
    c += 64;
    if (m)
      m += 64;
  }
  if (b) {
    crypto_core_salsa20(x, z, k, sigma);
    FOR(i, b) c[i] = (m ? m[i] : 0) ^ x[i];
  }
  return 0;
}

int crypto_stream(u8* c, u64 d, const u8* n, const u8* k)
{
  u8 s[32];
  crypto_core_hsalsa20(s, n, k, sigma);
  return crypto_stream_salsa20(c, d, n + 16, s);
}

int crypto_stream_xor(u8* c, const u8* m, u64 d, const u8* n, const u8* k)
{
  u8 s[32];
  crypto_core_hsalsa20(s, n, k, sigma);
  return crypto_stream_salsa20_xor(c, m, d, n + 16, s);
}

int crypto_onetimeauth_verify(const u8* h, const u8* m, u64 n, const u8* k)
{
  u8 x[16];
  crypto_onetimeauth(x, m, n, k);
  return crypto_verify_16(h, x);
}

int crypto_secretbox(u8* c, const u8* m, u64 d, const u8* n, const u8* k)
{
  int i;
  if (d < 32)
    return -1;
  crypto_stream_xor(c, m, d, n, k);
  crypto_onetimeauth(c + 16, c + 32, d - 32, c);
  FOR(i, 16) c[i] = 0;
  return 0;
}

int crypto_secretbox_open(u8* m, const u8* c, u64 d, const u8* n, const u8* k)
{
  int i;
  u8 x[32];
  if (d < 32)
    return -1;
  crypto_stream(x, 32, n, k);
  if (crypto_onetimeauth_verify(c + 16, c + 32, d - 32, x) != 0)
    return -1;
  crypto_stream_xor(m, c, d, n, k);
  FOR(i, 32) m[i] = 0;
  return 0;
}

sv set25519(gf r, const gf a)
{
  int i;
  FOR(i, 16) r[i] = a[i];
}

sv sel25519(gf p, gf q, int b)
{
  i64 t, i, c = ~(b - 1);
  FOR(i, 16)
  {
    t     = c & (p[i] ^ q[i]);
    p[i] ^= t;
    q[i] ^= t;
  }
}

static int neq25519(const gf a, const gf b)
{
  u8 c[32], d[32];
  pack25519(c, a);
  pack25519(d, b);
  return crypto_verify_32(c, d);
}

static u8 par25519(const gf a)
{
  u8 d[32];
  pack25519(d, a);
  return d[0] & 1;
}

sv unpack25519(gf o, const u8* n)
{
  int i;
  FOR(i, 16) o[i]  = n[2 * i] + ((i64)n[2 * i + 1] << 8);
  o[15]           &= 0x7fff;
}

sv A(gf o, const gf a, const gf b)
{
  int i;
  FOR(i, 16) o[i] = a[i] + b[i];
}

sv Z(gf o, const gf a, const gf b)
{
  int i;
  FOR(i, 16) o[i] = a[i] - b[i];
}

sv M(gf o, const gf a, const gf b)
{
  i64 i, j, t[31];
  FOR(i, 31) t[i]                 = 0;
  FOR(i, 16) FOR(j, 16) t[i + j] += a[i] * b[j];
  FOR(i, 15) t[i]                += 38 * t[i + 16];
  FOR(i, 16) o[i]                 = t[i];
  car25519(o);
  car25519(o);
}

sv inv25519(gf o, const gf i)
{
  gf c;
  int a;
  FOR(a, 16) c[a] = i[a];
  for (a = 253; a >= 0; a--) {
    S(c, c);
    if (a != 2 && a != 4)
      M(c, c, i);
  }
  FOR(a, 16) o[a] = c[a];
}

sv pow2523(gf o, const gf i)
{
  gf c;
  int a;
  FOR(a, 16) c[a] = i[a];
  for (a = 250; a >= 0; a--) {
    S(c, c);
    if (a != 1)
      M(c, c, i);
  }
  FOR(a, 16) o[a] = c[a];
}

int crypto_box_keypair(u8* y, u8* x)
{
  randombytes(x, 32);
  return crypto_scalarmult_base(y, x);
}

int crypto_box_beforenm(u8* k, const u8* y, const u8* x)
{
  u8 s[32];
  crypto_scalarmult(s, x, y);
  return crypto_core_hsalsa20(k, _0, s, sigma);
}

int crypto_box(u8* c, const u8* m, u64 d, const u8* n, const u8* y, const u8* x)
{
  u8 k[32];
  crypto_box_beforenm(k, y, x);
  return crypto_box_afternm(c, m, d, n, k);
}

int crypto_box_open(u8* m, const u8* c, u64 d, const u8* n, const u8* y, const u8* x)
{
  u8 k[32];
  crypto_box_beforenm(k, y, x);
  return crypto_box_open_afternm(m, c, d, n, k);
}

int crypto_hash(u8* out, const u8* m, u64 n)
{
  u8 h[64], x[256];
  u64 i, b = n;

  FOR(i, 64) h[i] = iv[i];

  crypto_hashblocks(h, m, n);
  m += n;
  n &= 127;
  m -= n;

  FOR(i, 256) x[i] = 0;
  FOR(i, n) x[i]   = m[i];
  x[n]             = 128;

  n        = 256 - 128 * (n < 112);
  x[n - 9] = b >> 61;
  ts64(x + n - 8, b << 3);
  crypto_hashblocks(h, x, n);

  FOR(i, 64) out[i] = h[i];

  return 0;
}

sv cswap(gf p[4], gf q[4], u8 b)
{
  int i;
  FOR(i, 4)
  sel25519(p[i], q[i], b);
}

sv pack(u8* r, gf p[4])
{
  gf tx, ty, zi;
  inv25519(zi, p[2]);
  M(tx, p[0], zi);
  M(ty, p[1], zi);
  pack25519(r, ty);
  r[31] ^= par25519(tx) << 7;
}

sv scalarmult(gf p[4], gf q[4], const u8* s)
{
  int i;
  set25519(p[0], gf0);
  set25519(p[1], gf1);
  set25519(p[2], gf1);
  set25519(p[3], gf0);
  for (i = 255; i >= 0; --i) {
    u8 b = (s[i / 8] >> (i & 7)) & 1;
    cswap(p, q, b);
    add(q, p);
    add(p, p);
    cswap(p, q, b);
  }
}

sv scalarbase(gf p[4], const u8* s)
{
  gf q[4];
  set25519(q[0], X);
  set25519(q[1], Y);
  set25519(q[2], gf1);
  M(q[3], X, Y);
  scalarmult(p, q, s);
}

int crypto_sign_keypair(u8* pk, u8* sk)
{
  u8 d[64];
  gf p[4];
  int i;

  randombytes(sk, 32);
  crypto_hash(d, sk, 32);
  d[0]  &= 248;
  d[31] &= 127;
  d[31] |= 64;

  scalarbase(p, d);
  pack(pk, p);

  FOR(i, 32) sk[32 + i] = pk[i];
  return 0;
}

sv reduce(u8* r)
{
  i64 x[64], i;
  FOR(i, 64) x[i] = (u64)r[i];
  FOR(i, 64) r[i] = 0;
  modL(r, x);
}

int crypto_sign(u8* sm, u64* smlen, const u8* m, u64 n, const u8* sk)
{
  u8 d[64], h[64], r[64];
  i64 i, j, x[64];
  gf p[4];

  crypto_hash(d, sk, 32);
  d[0]  &= 248;
  d[31] &= 127;
  d[31] |= 64;

  *smlen                = n + 64;
  FOR(i, n) sm[64 + i]  = m[i];
  FOR(i, 32) sm[32 + i] = d[32 + i];

  crypto_hash(r, sm + 32, n + 32);
  reduce(r);
  scalarbase(p, r);
  pack(sm, p);

  FOR(i, 32) sm[i + 32] = sk[i + 32];
  crypto_hash(h, sm, n + 64);
  reduce(h);

  FOR(i, 64) x[i]                 = 0;
  FOR(i, 32) x[i]                 = (u64)r[i];
  FOR(i, 32) FOR(j, 32) x[i + j] += h[i] * (u64)d[j];
  modL(sm + 32, x);

  return 0;
}

static int unpackneg(gf r[4], const u8 p[32])
{
  gf t, chk, num, den, den2, den4, den6;
  set25519(r[2], gf1);
  unpack25519(r[1], p);
  S(num, r[1]);
  M(den, num, D);
  Z(num, num, r[2]);
  A(den, r[2], den);

  S(den2, den);
  S(den4, den2);
  M(den6, den4, den2);
  M(t, den6, num);
  M(t, t, den);

  pow2523(t, t);
  M(t, t, num);
  M(t, t, den);
  M(t, t, den);
  M(r[0], t, den);

  S(chk, r[0]);
  M(chk, chk, den);
  if (neq25519(chk, num))
    M(r[0], r[0], I);

  S(chk, r[0]);
  M(chk, chk, den);
  if (neq25519(chk, num))
    return -1;

  if (par25519(r[0]) == (p[31] >> 7))
    Z(r[0], gf0, r[0]);

  M(r[3], r[0], r[1]);
  return 0;
}

int crypto_sign_open(u8* m, u64* mlen, const u8* sm, u64 n, const u8* pk)
{
  int i;
  u8 t[32], h[64];
  gf p[4], q[4];

  *mlen = -1;
  if (n < 64)
    return -1;

  if (unpackneg(q, pk))
    return -1;

  FOR(i, n) m[i]       = sm[i];
  FOR(i, 32) m[i + 32] = pk[i];
  crypto_hash(h, m, n);
  reduce(h);
  scalarmult(p, q, h);

  scalarbase(q, sm + 32);
  add(p, q);
  pack(t, p);

  n -= 64;
  if (crypto_verify_32(sm, t)) {
    FOR(i, n) m[i] = 0;
    return -1;
  }

  FOR(i, n) m[i] = sm[i + 64];
  *mlen          = n;
  return 0;
}

void API::Handlers::LicensingHandler::registerOfflineCommand()
{
  auto& registry = CommandRegistry::instance();

  QJsonObject props;
  props[QStringLiteral("path")] = QJsonObject{
    {       QStringLiteral("type"),                       QStringLiteral("string")},
    {QStringLiteral("description"), QStringLiteral("Path to a .sslic certificate")}
  };

  QJsonObject schema;
  schema[QStringLiteral("type")]       = QStringLiteral("object");
  schema[QStringLiteral("properties")] = props;
  schema[QStringLiteral("required")]   = QJsonArray{QStringLiteral("path")};

  registry.registerCommand(
    QStringLiteral("licensing.activateOffline"),
    QStringLiteral("Activate Pro from an offline license certificate (params: path)"),
    schema,
    &activateOffline);
}

API::CommandResponse API::Handlers::LicensingHandler::activateOffline(const QString& id,
                                                                      const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("path"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: path"));
  }

  auto& offline = Licensing::OfflineLicense::instance();
  if (!offline.activateFromFile(params.value(QStringLiteral("path")).toString()))
    return CommandResponse::makeError(id, ErrorCode::ExecutionError, offline.lastError());

  return CommandResponse::makeSuccess(id, {});
}

QDateTime Licensing::MonotonicClock::nowFloored(QSettings& settings, SimpleCrypt& crypt)
{
  auto effective = QDateTime::currentDateTime();

  settings.beginGroup("licensing");
  const auto stored = settings.value("lastSeen", "").toString();
  settings.endGroup();

  if (!stored.isEmpty()) {
    const auto seen = QDateTime::fromString(crypt.decryptToString(stored), Qt::RFC2822Date);
    if (seen.isValid() && seen > effective)
      effective = seen;
  }

  const auto encoded = crypt.encryptToString(effective.toString(Qt::RFC2822Date));
  settings.beginGroup("licensing");
  settings.setValue("lastSeen", encoded);
  settings.endGroup();

  return effective;
}

QDateTime Licensing::MonotonicClock::now()
{
  QSettings settings;
  SimpleCrypt crypt(MachineID::instance().machineSpecificKey());
  crypt.setIntegrityProtectionMode(SimpleCrypt::ProtectionHash);
  return nowFloored(settings, crypt);
}

Licensing::FeatureTier Licensing::tierFromCertVariant(const QString& variant)
{
  const auto lower = variant.toLower();

  if (lower.startsWith("enterprise"))
    return FeatureTier::Enterprise;

  if (!lower.isEmpty())
    return FeatureTier::Pro;

  return FeatureTier::None;
}

bool Licensing::parseCertificate(const QByteArray& framed,
                                 QByteArray& payload,
                                 QByteArray& signature)
{
  const auto decoded =
    QByteArray::fromBase64(framed.trimmed(), QByteArray::AbortOnBase64DecodingErrors);
  if (decoded.size() <= kSignatureBytes)
    return false;

  payload   = decoded.left(decoded.size() - kSignatureBytes);
  signature = decoded.right(kSignatureBytes);
  return true;
}

[[nodiscard]] static bool verifySignature(const QByteArray& payload,
                                          const QByteArray& signature,
                                          const std::array<std::uint8_t, 32>& publicKey)
{
  EVP_PKEY* key =
    EVP_PKEY_new_raw_public_key(EVP_PKEY_ED25519, nullptr, publicKey.data(), publicKey.size());
  if (!key)
    return false;

  EVP_MD_CTX* ctx = EVP_MD_CTX_new();
  bool ok         = false;
  if (ctx && EVP_DigestVerifyInit(ctx, nullptr, nullptr, nullptr, key) == 1) {
    const auto* sig = reinterpret_cast<const unsigned char*>(signature.constData());
    const auto* msg = reinterpret_cast<const unsigned char*>(payload.constData());
    ok =
      EVP_DigestVerify(
        ctx, sig, static_cast<size_t>(signature.size()), msg, static_cast<size_t>(payload.size()))
      == 1;
  }

  EVP_MD_CTX_free(ctx);
  EVP_PKEY_free(key);
  return ok;
}

[[nodiscard]] static bool decodeFields(const QByteArray& payload,
                                       Licensing::CertificateFields& fields)
{
  const auto value = QCborValue::fromCbor(payload);
  if (!value.isMap())
    return false;

  const auto map     = value.toMap();
  const auto version = map[QStringLiteral("v")];
  const auto machine = map[QStringLiteral("mid")];
  const auto variant = map[QStringLiteral("var")];
  const auto inst    = map[QStringLiteral("iid")];
  const auto issued  = map[QStringLiteral("iat")];
  const auto expires = map[QStringLiteral("exp")];

  if (!version.isInteger() || !machine.isString() || !variant.isString() || !issued.isInteger()
      || !expires.isInteger())
    return false;

  fields.version    = static_cast<int>(version.toInteger());
  fields.machineId  = machine.toString();
  fields.variant    = variant.toString();
  fields.instanceId = inst.isString() ? inst.toString() : QString();
  fields.issuedAt   = issued.toInteger();
  fields.expiresAt  = expires.toInteger();
  return true;
}

Licensing::CertStatus Licensing::verifyCertificate(const QByteArray& framed,
                                                   const std::array<std::uint8_t, 32>& publicKey,
                                                   const QString& machineId,
                                                   qint64 nowSecs,
                                                   CertificateFields& fields)
{
  QByteArray payload;
  QByteArray signature;
  if (!parseCertificate(framed, payload, signature))
    return CertStatus::Malformed;

  if (!verifySignature(payload, signature, publicKey))
    return CertStatus::BadSignature;

  if (!decodeFields(payload, fields) || fields.version != kFormatVersion)
    return CertStatus::Malformed;

  if (fields.machineId != machineId)
    return CertStatus::MachineMismatch;

  if (fields.expiresAt <= nowSecs)
    return CertStatus::Expired;

  if (tierFromCertVariant(fields.variant) == FeatureTier::None)
    return CertStatus::WrongTier;

  return CertStatus::Valid;
}

QString Licensing::certStatusReason(CertStatus status)
{
  switch (status) {
    case CertStatus::Valid:
      return QCoreApplication::translate("OfflineLicense", "License certificate is valid.");
    case CertStatus::BadSignature:
      return QCoreApplication::translate("OfflineLicense",
                                         "The certificate signature is invalid or corrupted.");
    case CertStatus::MachineMismatch:
      return QCoreApplication::translate("OfflineLicense",
                                         "This certificate was issued for a different device.");
    case CertStatus::Expired:
      return QCoreApplication::translate("OfflineLicense", "This certificate has expired.");
    case CertStatus::WrongTier:
      return QCoreApplication::translate("OfflineLicense",
                                         "This certificate does not grant a valid license tier.");
    case CertStatus::Malformed:
    default:
      return QCoreApplication::translate("OfflineLicense",
                                         "The certificate file is malformed or unreadable.");
  }
}

static void installOfflineToken(const Licensing::CertificateFields& fields, int daysRemaining)
{
  Licensing::CommercialToken token;
  token.setVariantName(fields.variant);
  token.setInstanceName(Licensing::MachineID::instance().machineId());
  token.setGraceDaysRemaining(daysRemaining);
  token.setFeatureTier(Licensing::tierFromCertVariant(fields.variant));
  token.seal();
  Licensing::CommercialToken::setCurrent(token);
}

Licensing::OfflineLicense::OfflineLicense() : m_activated(false)
{
  m_simpleCrypt.setKey(MachineID::instance().machineSpecificKey());
  m_simpleCrypt.setIntegrityProtectionMode(SimpleCrypt::ProtectionHash);

  connect(&LemonSqueezy::instance(),
          &LemonSqueezy::activatedChanged,
          this,
          &OfflineLicense::onOnlineActivationChanged);

  connect(this,
          &OfflineLicense::activatedChanged,
          &LemonSqueezy::instance(),
          &LemonSqueezy::activatedChanged);
  connect(this,
          &OfflineLicense::activatedChanged,
          &LemonSqueezy::instance(),
          &LemonSqueezy::licenseDataChanged);

  readSettings();
}

Licensing::OfflineLicense& Licensing::OfflineLicense::instance()
{
  static OfflineLicense instance;
  return instance;
}

int Licensing::OfflineLicense::daysRemaining() const
{
  if (!m_activated)
    return 0;

  return qMax(0, static_cast<int>(QDateTime::currentDateTime().daysTo(m_expiresAt)));
}

bool Licensing::OfflineLicense::activateFromFile(const QString& path)
{
  const QString local = path.startsWith(QStringLiteral("file:")) ? QUrl(path).toLocalFile() : path;

  QFile file(local);
  if (!file.open(QIODevice::ReadOnly)) {
    m_lastError = tr("Could not open the certificate file.");
    showOfflineError(m_lastError, QMessageBox::Critical);
    return false;
  }

  constexpr qint64 kMaxCertBytes = 64 * 1024;
  if (file.size() > kMaxCertBytes) {
    m_lastError = tr("The certificate file is too large to be valid.");
    showOfflineError(m_lastError, QMessageBox::Critical);
    return false;
  }

  const QByteArray framed = file.readAll();
  file.close();
  return applyCertificate(framed, true);
}

bool Licensing::OfflineLicense::exportMachineInfo(const QString& path)
{
  const QString local = path.startsWith(QStringLiteral("file:")) ? QUrl(path).toLocalFile() : path;

  QJsonObject info;
  info.insert(QStringLiteral("type"), QStringLiteral("serial-studio-machine"));
  info.insert(QStringLiteral("version"), 1);
  info.insert(QStringLiteral("machineId"), machineId());
  info.insert(QStringLiteral("app"), QStringLiteral(APP_NAME));
  info.insert(QStringLiteral("appVersion"), QStringLiteral(APP_VERSION));
  info.insert(QStringLiteral("generatedAt"), QDateTime::currentDateTimeUtc().toString(Qt::ISODate));

  QFile file(local);
  if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
    m_lastError = tr("Could not write the device file.");
    showOfflineError(m_lastError, QMessageBox::Critical);
    return false;
  }

  file.write(QJsonDocument(info).toJson(QJsonDocument::Indented));
  file.close();
  return true;
}

void Licensing::OfflineLicense::readSettings()
{
  m_settings.beginGroup("offlineLicense");
  const auto stored = m_settings.value("cert", "").toString();
  m_settings.endGroup();

  if (stored.isEmpty())
    return;

  const auto framed = m_simpleCrypt.decryptToByteArray(stored);
  if (framed.isEmpty() || !applyCertificate(framed, false))
    clearOfflineLicense();
}

void Licensing::OfflineLicense::writeSettings(const QByteArray& framedCert)
{
  m_settings.beginGroup("offlineLicense");
  m_settings.setValue("cert", m_simpleCrypt.encryptToString(framedCert));
  m_settings.endGroup();
}

void Licensing::OfflineLicense::onOnlineActivationChanged()
{
  if (m_activated && !CommercialToken::current().isValid())
    readSettings();
}

void Licensing::OfflineLicense::clearOfflineLicense()
{
  m_activated   = false;
  m_variantName = QString();
  m_expiresAt   = QDateTime();

  m_settings.beginGroup("offlineLicense");
  m_settings.setValue("cert", "");
  m_settings.endGroup();

  Q_EMIT activatedChanged();
}

bool Licensing::OfflineLicense::applyCertificate(const QByteArray& framedCert, bool persist)
{
  const qint64 nowSecs = MonotonicClock::now().toSecsSinceEpoch();

  CertificateFields fields;
  const auto status =
    verifyCertificate(framedCert, kOfflinePublicKey, machineId(), nowSecs, fields);
  if (status != CertStatus::Valid) {
    m_lastError = certStatusReason(status);
    if (persist)
      showOfflineError(m_lastError);

    return false;
  }

  m_activated   = true;
  m_lastError   = QString();
  m_variantName = fields.variant;
  m_expiresAt   = QDateTime::fromSecsSinceEpoch(fields.expiresAt);

  if (!LemonSqueezy::instance().isOnlineActivated()) {
    const int days = qMax(0, static_cast<int>((fields.expiresAt - nowSecs) / 86400));
    installOfflineToken(fields, days);
  }

  if (persist)
    writeSettings(framedCert);

  Q_EMIT activatedChanged();
  return true;
}

[[nodiscard]] static int expect(const char* name, bool condition)
{
  if (condition) {
    qInfo().noquote() << "  PASS" << name;
    return 0;
  }

  qCritical().noquote() << "  FAIL" << name;
  return 1;
}

[[nodiscard]] static bool statusIs(const QByteArray& framed,
                                   const QString& machine,
                                   qint64 nowSecs,
                                   Licensing::CertStatus expected)
{
  Licensing::CertificateFields fields;
  return Licensing::verifyCertificate(framed, kTestPublicKey, machine, nowSecs, fields) == expected;
}

[[nodiscard]] static int runVerifierChecks()
{
  const QByteArray good(kGoodCert);
  const QString machine(kTestMachineId);

  int fails  = 0;
  fails     += expect("good certificate accepted",
                  statusIs(good, machine, kTestNowSecs, Licensing::CertStatus::Valid));

  auto decoded  = QByteArray::fromBase64(good);
  decoded[3]    = static_cast<char>(decoded[3] ^ 0x01);
  fails        += expect(
    "payload bit-flip rejected (bad signature)",
    statusIs(decoded.toBase64(), machine, kTestNowSecs, Licensing::CertStatus::BadSignature));

  fails += expect(
    "wrong machine rejected",
    statusIs(
      good, QStringLiteral("SS-OTHER"), kTestNowSecs, Licensing::CertStatus::MachineMismatch));

  fails += expect(
    "expired certificate rejected",
    statusIs(QByteArray(kExpiredCert), machine, kTestNowSecs, Licensing::CertStatus::Expired));

  fails += expect(
    "empty-tier certificate rejected",
    statusIs(QByteArray(kWrongTierCert), machine, kTestNowSecs, Licensing::CertStatus::WrongTier));

  fails += expect("garbage input rejected (malformed)",
                  statusIs(QByteArray("!!not a certificate!!"),
                           machine,
                           kTestNowSecs,
                           Licensing::CertStatus::Malformed));

  fails += expect("truncated certificate rejected (malformed)",
                  statusIs(good.left(8), machine, kTestNowSecs, Licensing::CertStatus::Malformed));
  return fails;
}

[[nodiscard]] static int runClockRewindCheck()
{
  QSettings settings(QStringLiteral("SerialStudioSelfTest"), QStringLiteral("OfflineClock"));
  settings.clear();

  Licensing::SimpleCrypt crypt(0x0123456789abcdefULL);
  crypt.setIntegrityProtectionMode(Licensing::SimpleCrypt::ProtectionHash);

  const auto future = QDateTime::currentDateTime().addYears(5);
  settings.beginGroup("licensing");
  settings.setValue("lastSeen", crypt.encryptToString(future.toString(Qt::RFC2822Date)));
  settings.endGroup();

  const auto floored = Licensing::MonotonicClock::nowFloored(settings, crypt);
  settings.clear();

  return expect("clock floored to previously observed future (rewind blocked)",
                floored >= future.addSecs(-60));
}

int Licensing::runOfflineSelfTest()
{
  qInfo().noquote() << "[offline-license] running self-test vectors";
  const int fails = runVerifierChecks() + runClockRewindCheck();

  if (fails == 0)
    qInfo().noquote() << "[offline-license] all checks passed";
  else
    qCritical().noquote() << "[offline-license]" << fails << "check(s) failed";

  return fails == 0 ? 0 : 1;
}

void UART0_RX_TX_IRQHandler(void) {
  if (UART_DEV->S1 & UART_S1_RDRF_MASK) {
    uint8_t byte = UART_DEV->D; // reading S1 then D clears RDRF (and any overrun)
    tu_fifo_write(&uart_rx_ff, &byte);
  }
}

size_t board_get_unique_id(uint8_t id[], size_t max_len) {
  (void) max_len;
  // Kinetis 128-bit Unique Identification Register (SIM->UIDH/UIDMH/UIDML/UIDL)
  uint32_t* id32 = (uint32_t*) (uintptr_t) id;
  uint8_t const len = 16;

  id32[0] = SIM->UIDH;
  id32[1] = SIM->UIDMH;
  id32[2] = SIM->UIDML;
  id32[3] = SIM->UIDL;

  return len;
}

ic void pipe_xfer_complete(uint8_t rhport, unsigned num, bool in_isr) {
  pipe_state_t *pipe = &_dcd.pipe[num];
  pipe->queued = false;
  dcd_event_xfer_complete(rhport, pipe->ep, pipe->length - pipe->remaining,
                          XFER_RESULT_SUCCESS, in_isr);
}

