uint16_t const* tud_descriptor_string_cb(uint8_t index, uint16_t langid) {
  (void) langid;
  size_t chr_count;

  switch (index) {
    case STRID_LANGID:
      memcpy(&_desc_str[1], string_desc_arr[0], 2);
      chr_count = 1;
      break;

    case STRID_SERIAL:
      chr_count = board_usb_get_serial(_desc_str + 1, 32);
      break;

    default:
      if (!(index < sizeof(string_desc_arr) / sizeof(string_desc_arr[0]))) return NULL;

      const char* str = string_desc_arr[index];

      // Cap at max char
      chr_count = strlen(str);
      size_t const max_count = sizeof(_desc_str) / sizeof(_desc_str[0]) - 1; // -1 for string type
      if (chr_count > max_count) chr_count = max_count;

      // Convert ASCII string into UTF-16
      for (size_t i = 0; i < chr_count; i++) {
        _desc_str[1 + i] = str[i];
      }
      break;
  }

  // first byte is length (including header), second byte is string type
  _desc_str[0] = (uint16_t) ((TUSB_DESC_STRING << 8) | (2 * chr_count + 2));

  return _desc_str;
}

size_t board_get_unique_id(uint8_t id[], size_t max_len) {
  volatile uint32_t* ch32_uuid = ((volatile uint32_t*) 0x1FFFF7E8UL); // ESIG unique ID
  uint32_t uid[3] = { ch32_uuid[0], ch32_uuid[1], ch32_uuid[2] };
  const size_t len = max_len < sizeof(uid) ? max_len : sizeof(uid);
  memcpy(id, uid, len); // byte copy: id[] need not be 4-byte aligned
  return len;
}

ic void edpt_skip_active(uint8_t rhport, uint8_t ep_id) {
  ep_cmd_sts_t* ep_cs = get_ep_cs(ep_id);
  if ( ep_cs[0].cmd_sts.active || ep_cs[1].cmd_sts.active ) {
    dcd_registers_t* dcd_reg = _dcd_controller[rhport].regs;
    dcd_reg->EPSKIP |= TU_BIT(ep_id);
    uint32_t guard = IP3511_EPSKIP_SPIN;
    while ( (dcd_reg->EPSKIP & TU_BIT(ep_id)) && guard-- ) {}
  }
  ep_cs[0].cmd_sts.active = ep_cs[1].cmd_sts.active = 0;
}

dcd_edpt_iso_alloc(uint8_t rhport, uint8_t ep_addr, uint16_t largest_packet_size) {
  (void) largest_packet_size;
  // Reserve the endpoint command/status entry once (persists across altsetting changes); the
  // buffer pointer is filled per-transfer, so nothing to pre-allocate. Mirrors the ISO branch of
  // dcd_edpt_open().
  ep_cmd_sts_t* ep_cs = get_ep_cs(ep_id);
  TU_ASSERT( ep_cs[0].cmd_sts.disable && ep_cs[1].cmd_sts.disable );
  edpt_reset(rhport, ep_id);
  ep_cs[0].cmd_sts.type = 1; // ISO

  dcd_registers_t* dcd_reg = _dcd_controller[rhport].regs;
  dcd_reg->INTEN |= TU_BIT(ep_id);
  return true;
  // (Re)activate on altsetting selection: retire a buffer still armed from the previous altsetting
  // (the hardware keeps servicing an Active buffer across SET_INTERFACE, fighting the class's fresh
  // transfer), clear stall and reset the data toggle. The class re-arms via dcd_edpt_xfer().
  uint8_t ep_id = ep_addr2id(desc_ep->bEndpointAddress);
  ep_cmd_sts_t* ep_cs = get_ep_cs(ep_id);
  edpt_skip_active(rhport, ep_id);
  ep_cs[0].cmd_sts.stall        = 0;
  ep_cs[0].cmd_sts.toggle_reset = 1;
  ep_cs[0].cmd_sts.rf_tv        = 0;
  return true;

atic bool pipe_zlp_in(rusb2_reg_t *rusb, unsigned num) {
  rusb->D0FIFOSEL = (uint16_t) num;
  const bool ready = pipe_wait_for_ready(rusb, num);
  if (ready) {
    rusb->D0FIFOCTR = RUSB2_CFIFOCTR_BVAL_Msk;
  }
  rusb->D0FIFOSEL = 0;
  // deselect completes within a few bus cycles (not host-dependent), but bound it anyway: this
  // runs with the USB IRQ masked, where any stuck spin freezes the whole stack
  uint32_t spin = RUSB2_FIFO_READY_SPIN;
  while (rusb->D0FIFOSEL_b.CURPIPE) {
    if (!spin--) { break; }
  }
  return ready;
}

