uint32_t tud_vendor_n_iso_write(uint8_t idx, const void *buffer, uint32_t bufsize) {
  TU_VERIFY(idx < CFG_TUD_VENDOR, 0);
  vendord_interface_t *p_itf = &_vendord_itf[idx];
  return vendord_ep_write(p_itf, p_itf->ep_iso_in, _vendord_iso_epbuf[idx].iso_in, CFG_TUD_VENDOR_EP_ISO_IN_BUFSIZE, buffer, bufsize);
}

uint32_t tud_vendor_n_iso_write_available(uint8_t idx) {
  TU_VERIFY(idx < CFG_TUD_VENDOR, 0);
  vendord_interface_t *p_itf = &_vendord_itf[idx];
  return vendord_ep_write_available(p_itf, p_itf->ep_iso_in, CFG_TUD_VENDOR_EP_ISO_IN_BUFSIZE);
}

static inline bool vendord_iso_ep_alloc(uint8_t rhport, const tusb_desc_endpoint_t* desc_ep) {
  #ifdef TUP_DCD_EDPT_ISO_ALLOC
  return usbd_edpt_iso_alloc(rhport, desc_ep->bEndpointAddress, tu_edpt_packet_size(desc_ep));
  #else
  return usbd_edpt_open(rhport, desc_ep);
  #endif
}

static inline bool vendord_iso_ep_activate(uint8_t rhport, const tusb_desc_endpoint_t* desc_ep) {
  #ifdef TUP_DCD_EDPT_ISO_ALLOC
  return usbd_edpt_iso_activate(rhport, desc_ep); // resets ep_status, aborting any stale transfer
  #else
  // No iso alloc/activate API: close (which zeros ep_status and frees a stale claim left by a
  // prior selection) then re-open, so a re-selected altsetting starts from a clean state.
  usbd_edpt_close(rhport, desc_ep->bEndpointAddress);
  return usbd_edpt_open(rhport, desc_ep);
  #endif
}

static inline void vendord_abort_ep(uint8_t rhport, uint8_t ep_addr) {
  if (ep_addr) {
    usbd_edpt_stall(rhport, ep_addr);
    usbd_edpt_clear_stall(rhport, ep_addr);
  }
}

static bool vendord_set_alt(uint8_t rhport, uint8_t idx, uint8_t alt) {
  vendord_interface_t *p_vendor = &_vendord_itf[idx];
  const uint8_t* p_desc = p_vendor->p_itf_desc;
  const uint8_t* desc_end = p_desc + p_vendor->itf_desc_len;
  bool in_target_alt = false;
  bool alt_found = false;

  while (tu_desc_in_bounds(p_desc, desc_end)) {
    const uint8_t desc_type = tu_desc_type(p_desc);
    if (desc_type == TUSB_DESC_INTERFACE) {
      in_target_alt = (((const tusb_desc_interface_t*)p_desc)->bAlternateSetting == alt);
      if (in_target_alt && !alt_found) {
        alt_found = true;
        // target altsetting confirmed present: abort then drop the previous altsetting's endpoints,
        // so a bulk/interrupt endpoint absent from the target altsetting can't stay armed and keep
        // its usbd claim in the dcd. (Endpoints the target altsetting reuses are reset again below;
        // a double reset is harmless. Iso endpoints are re-activated on reselection.)
        vendord_abort_ep(rhport, p_vendor->ep_in);
        vendord_abort_ep(rhport, p_vendor->ep_out);
  #if CFG_TUD_VENDOR_EP_INT_OUT
        vendord_abort_ep(rhport, p_vendor->ep_int_out);
  #endif
  #if CFG_TUD_VENDOR_EP_INT_IN
        vendord_abort_ep(rhport, p_vendor->ep_int_in);
  #endif
        p_vendor->ep_in = 0;
        p_vendor->ep_out = 0;
  #if CFG_TUD_VENDOR_EP_INT_OUT
        p_vendor->ep_int_out = 0;
  #endif
  #if CFG_TUD_VENDOR_EP_INT_IN
        p_vendor->ep_int_in = 0;
  #endif
  #if CFG_TUD_VENDOR_EP_ISO_OUT
        p_vendor->ep_iso_out = 0;
  #endif
  #if CFG_TUD_VENDOR_EP_ISO_IN
        p_vendor->ep_iso_in = 0;
  #endif
      }
    } else if (in_target_alt && desc_type == TUSB_DESC_ENDPOINT) {
      const tusb_desc_endpoint_t* desc_ep = (const tusb_desc_endpoint_t*) p_desc;
      const uint8_t ep_addr = desc_ep->bEndpointAddress;
      const bool is_in = tu_edpt_dir(ep_addr) == TUSB_DIR_IN;
      (void) is_in;

      switch (desc_ep->bmAttributes.xfer) {
        case TUSB_XFER_BULK:
          // abort in-flight transfer + reset data toggle
          usbd_edpt_stall(rhport, ep_addr);
          usbd_edpt_clear_stall(rhport, ep_addr);
          if (is_in) {
            p_vendor->ep_in = ep_addr;
          } else {
            p_vendor->ep_out = ep_addr;
            p_vendor->rx_xfer_len =
              CFG_TUD_VENDOR_RX_NEED_ZLP ? CFG_TUD_VENDOR_RX_EPSIZE : tu_edpt_packet_size(desc_ep);
  #if CFG_TUD_VENDOR_RX_MANUAL_XFER == 0
            TU_ASSERT(usbd_edpt_xfer(rhport, p_vendor->ep_out, _vendord_epbuf[idx].epout,
                                     p_vendor->rx_xfer_len, false));
  #endif
          }
          break;

  #if CFG_TUD_VENDOR_EP_INT_IN || CFG_TUD_VENDOR_EP_INT_OUT
        case TUSB_XFER_INTERRUPT:
          // stall/clear only for the enabled direction (an endpoint of a disabled
          // direction was never opened, so must not be poked in the dcd)
    #if CFG_TUD_VENDOR_EP_INT_IN
          if (is_in) {
            usbd_edpt_stall(rhport, ep_addr);
            usbd_edpt_clear_stall(rhport, ep_addr);
            p_vendor->ep_int_in = ep_addr;
          }
    #endif
    #if CFG_TUD_VENDOR_EP_INT_OUT
          if (!is_in) {
            usbd_edpt_stall(rhport, ep_addr);
            usbd_edpt_clear_stall(rhport, ep_addr);
            p_vendor->ep_int_out = ep_addr;
            p_vendor->int_rx_xfer_len = tu_edpt_packet_size(desc_ep);
          }
    #endif
          break;
  #endif

  #if CFG_TUD_VENDOR_EP_ISO_IN || CFG_TUD_VENDOR_EP_ISO_OUT
        case TUSB_XFER_ISOCHRONOUS:
    #if CFG_TUD_VENDOR_EP_ISO_IN
          if (is_in) {
            TU_ASSERT(vendord_iso_ep_activate(rhport, desc_ep));
            p_vendor->ep_iso_in = ep_addr;
          }
    #endif
    #if CFG_TUD_VENDOR_EP_ISO_OUT
          if (!is_in) {
            TU_ASSERT(vendord_iso_ep_activate(rhport, desc_ep));
            p_vendor->ep_iso_out = ep_addr;
            p_vendor->iso_rx_xfer_len = tu_edpt_packet_size(desc_ep);
          }
    #endif
          break;
  #endif

        default:
          break; // unsupported endpoint type / direction gate disabled: ignore
      }
    }
    p_desc = tu_desc_next(p_desc);
  }

  TU_VERIFY(alt_found); // unknown alt: endpoints were never cleared, current altsetting intact
  p_vendor->cur_alt = alt;
  return true;
}

uint16_t vendord_open(uint8_t rhport, const tusb_desc_interface_t *desc_itf, uint16_t max_len) {
  TU_VERIFY(TUSB_CLASS_VENDOR_SPECIFIC == desc_itf->bInterfaceClass, 0);
  const uint8_t* desc_end = (const uint8_t*)desc_itf + max_len;

  const uint8_t idx = find_vendor_itf(0);
  TU_ASSERT(idx < CFG_TUD_VENDOR, 0);
  vendord_interface_t *p_vendor = &_vendord_itf[idx];
  p_vendor->rhport     = rhport;
  p_vendor->itf_num    = desc_itf->bInterfaceNumber;
  // p_itf_desc is assigned only after the parse succeeds: find_vendor_itf() treats a non-NULL
  // p_itf_desc as an occupied slot, so setting it before a mid-parse TU_ASSERT could fail would
  // leak the slot (a retry would find no free interface until the next bus reset).

  // Consume every altsetting of this interface and hardware-open each endpoint exactly once
  // (bulk/interrupt via usbd_edpt_open, isochronous FIFO-allocated; iso activation and the
  // toggle reset happen on altsetting selection). An endpoint address that recurs in another
  // altsetting must carry an identical configuration, since it is opened only on first sight;
  // reconfiguring the same address per-alt is not supported and is rejected here.
  uint8_t seen_type[CFG_TUD_ENDPPOINT_MAX][2];
  uint16_t seen_mps[CFG_TUD_ENDPPOINT_MAX][2];
  tu_memclr(seen_type, sizeof(seen_type)); // 0 == TUSB_XFER_CONTROL, never used as a data ep here
  const uint8_t* p_desc = tu_desc_next(desc_itf);
  while (tu_desc_in_bounds(p_desc, desc_end)) {
    const uint8_t desc_type = tu_desc_type(p_desc);
    if (desc_type == TUSB_DESC_INTERFACE_ASSOCIATION) {
      break;
    }
    if (desc_type == TUSB_DESC_INTERFACE) {
      if (((const tusb_desc_interface_t*)p_desc)->bInterfaceNumber != p_vendor->itf_num) {
        break; // next interface
      }
    } else if (desc_type == TUSB_DESC_ENDPOINT) {
      const tusb_desc_endpoint_t* desc_ep = (const tusb_desc_endpoint_t*) p_desc;
      const uint8_t epnum = tu_edpt_number(desc_ep->bEndpointAddress);
      const uint8_t dir = tu_edpt_dir(desc_ep->bEndpointAddress);
      const uint8_t xfer = desc_ep->bmAttributes.xfer;
      const uint16_t mps = tu_edpt_packet_size(desc_ep);
      TU_ASSERT(epnum < CFG_TUD_ENDPPOINT_MAX, 0);

      if (seen_type[epnum][dir] != 0) {
        // reused address in a later altsetting: must be an exact match (opened only once)
        TU_ASSERT(seen_type[epnum][dir] == xfer && seen_mps[epnum][dir] == mps, 0);
      } else {
        switch (xfer) {
          case TUSB_XFER_BULK:
            TU_ASSERT(usbd_edpt_open(rhport, desc_ep), 0);
            break;

  #if CFG_TUD_VENDOR_EP_INT_IN || CFG_TUD_VENDOR_EP_INT_OUT
          case TUSB_XFER_INTERRUPT:
    #if CFG_TUD_VENDOR_EP_INT_IN
            if (dir == TUSB_DIR_IN) {
              TU_ASSERT(mps <= CFG_TUD_VENDOR_EP_INT_IN_BUFSIZE, 0);
              TU_ASSERT(usbd_edpt_open(rhport, desc_ep), 0);
            }
    #endif
    #if CFG_TUD_VENDOR_EP_INT_OUT
            if (dir == TUSB_DIR_OUT) {
              TU_ASSERT(mps <= CFG_TUD_VENDOR_EP_INT_OUT_BUFSIZE, 0);
              TU_ASSERT(usbd_edpt_open(rhport, desc_ep), 0);
            }
    #endif
            break;
  #endif

  #if CFG_TUD_VENDOR_EP_ISO_IN || CFG_TUD_VENDOR_EP_ISO_OUT
          case TUSB_XFER_ISOCHRONOUS:
    #if CFG_TUD_VENDOR_EP_ISO_IN
            if (dir == TUSB_DIR_IN) {
              TU_ASSERT(mps <= CFG_TUD_VENDOR_EP_ISO_IN_BUFSIZE, 0);
              TU_ASSERT(vendord_iso_ep_alloc(rhport, desc_ep), 0);
            }
    #endif
    #if CFG_TUD_VENDOR_EP_ISO_OUT
            if (dir == TUSB_DIR_OUT) {
              TU_ASSERT(mps <= CFG_TUD_VENDOR_EP_ISO_OUT_BUFSIZE, 0);
              TU_ASSERT(vendord_iso_ep_alloc(rhport, desc_ep), 0);
            }
    #endif
            break;
  #endif

          default:
            break; // unsupported endpoint type / direction gate disabled: ignore
        }
        seen_type[epnum][dir] = xfer;
        seen_mps[epnum][dir] = mps;
      }
    }
    p_desc = tu_desc_next(p_desc);
  }
  // parse succeeded: commit the descriptor pointer (marks the slot occupied) before selecting alt 0
  p_vendor->p_itf_desc   = (const uint8_t*) desc_itf;
  p_vendor->itf_desc_len = (uint16_t)((uintptr_t)p_desc - (uintptr_t)desc_itf);

  // default altsetting active until the host selects another
  TU_ASSERT(vendord_set_alt(rhport, idx, 0), 0);
  return p_vendor->itf_desc_len;
}

bool vendord_control_xfer_cb(uint8_t rhport, uint8_t stage, tusb_control_request_t const *request) {
#if CFG_TUD_VENDOR_ALT_SETTINGS
  if (request->bmRequestType_bit.type == TUSB_REQ_TYPE_STANDARD &&
      request->bmRequestType_bit.recipient == TUSB_REQ_RCPT_INTERFACE) {
    const uint8_t itf_num = tu_u16_low(request->wIndex);
    uint8_t idx;
    for (idx = 0; idx < CFG_TUD_VENDOR; idx++) {
      if (_vendord_itf[idx].itf_num == itf_num && _vendord_itf[idx].p_itf_desc != NULL) {
        break;
      }
    }
    if (idx < CFG_TUD_VENDOR) {
      if (request->bRequest == TUSB_REQ_SET_INTERFACE) {
        if (stage == CONTROL_STAGE_SETUP) {
          TU_VERIFY(vendord_set_alt(rhport, idx, tu_u16_low(request->wValue)));
          return tud_control_status(rhport, request);
        }
        return true;
      } else if (request->bRequest == TUSB_REQ_GET_INTERFACE) {
        if (stage == CONTROL_STAGE_SETUP) {
          return tud_control_xfer(rhport, request, &_vendord_itf[idx].cur_alt, 1);
        }
        return true;
      }
    }
  }
#endif
  return tud_vendor_control_xfer_cb(rhport, stage, request);
}

static wchar_t* U2Wdup(const char* s)
{
    if (!s) s = "";
    int n = MultiByteToWideChar(CP_UTF8, 0, s, -1, NULL, 0);
    wchar_t* w = (wchar_t*)malloc((size_t)n * sizeof(wchar_t));
    if (w) MultiByteToWideChar(CP_UTF8, 0, s, -1, w, n);
    return w;
}

static void PBLogCb(const char* message)
{
    if (!g_hMain) return;
    wchar_t* body = U2Wdup(message);
    if (!body) return;
    wchar_t ts[16]; GetTimePrefix(ts, 16);
    size_t n = wcslen(ts) + wcslen(body) + 3;
    wchar_t* line = (wchar_t*)malloc(n * sizeof(wchar_t));
    if (line) { _snwprintf_s(line, n, _TRUNCATE, L"%s%s\r\n", ts, body); PostMessageW(g_hMain, WM_APP_LOG, 0, (LPARAM)line); }
    free(body);
}

static void PBConnCb(const char* proc, DWORD pid, const char* ip, unsigned short port, const char* info)
{
    if (!g_hMain || !g_trafficLog) return;
    wchar_t *wp = U2Wdup(proc), *wi = U2Wdup(ip), *wf = U2Wdup(info);
    // Connection-log filters: derive protocol/action from the proxy_info and drop non-matches.
    if (g_fltCount > 0)
    {
        wchar_t wport[16]; _snwprintf_s(wport, 16, _TRUNCATE, L"%u", port);
        const wchar_t* proto  = (info && strstr(info, "(UDP)")) ? L"UDP" : L"TCP";
        const wchar_t* action = (info && _strnicmp(info, "Direct", 6) == 0) ? L"Direct"
                              : (info && _strnicmp(info, "Block",  5) == 0) ? L"Blocked" : L"Proxy";
        if (!PassesLogFilters(wp ? wp : L"", wi ? wi : L"", wport, proto, action))
        { free(wp); free(wi); free(wf); return; }
    }
    wchar_t ts[16]; GetTimePrefix(ts, 16);
    size_t n = 64 + (wp ? wcslen(wp) : 0) + (wi ? wcslen(wi) : 0) + (wf ? wcslen(wf) : 0);
    wchar_t* line = (wchar_t*)malloc(n * sizeof(wchar_t));
    if (line)
    {
        _snwprintf_s(line, n, _TRUNCATE, L"%s%s (PID:%lu) -> %s:%u  via %s\r\n",
                   ts, wp ? wp : L"?", pid, wi ? wi : L"?", port, wf ? wf : L"?");
        PostMessageW(g_hMain, WM_APP_CONN, 0, (LPARAM)line);
    }
    free(wp); free(wi); free(wf);
}

static UINT32 ResolveNativeCfg(UINT32 storedId)
{
    for (int i = 0; i < g_profile.cfgCount; i++)
        if (g_profile.cfg[i].storedId == storedId) return g_profile.cfg[i].nativeId;
    return 0; // 0 => DLL uses first available config
}

static void ApplyConfigs(void)
{
    for (int i = 0; i < g_profile.cfgCount; i++)
    {
        PBConfig* c = &g_profile.cfg[i];
        int type = (_wcsicmp(c->type, L"HTTP") == 0) ? PB_PROXY_HTTP : PB_PROXY_SOCKS5;
        char h[256], u[256], p[256];
        W2Ux(c->host, h, sizeof(h)); W2Ux(c->user, u, sizeof(u)); W2Ux(c->pass, p, sizeof(p));
        c->nativeId = g_api.AddProxyConfig((PBProxyType)type, h, (unsigned short)_wtoi(c->port), u, p);
        if (c->storedId == 0) c->storedId = c->nativeId;
    }
}

static void ApplyRules(void)
{
    for (int i = 0; i < g_profile.ruleCount; i++)
    {
        PBRule* r = &g_profile.rule[i];
        char proc[512], hosts[512], ports[256], domains[512];
        W2Ux(r->proc, proc, sizeof(proc)); W2Ux(r->hosts, hosts, sizeof(hosts));
        W2Ux(r->ports, ports, sizeof(ports)); W2Ux(r->domains, domains, sizeof(domains));
        r->nativeId = g_api.AddRule(proc, hosts, ports, domains,
                                    (PBRuleProtocol)ProtoIdx(r->proto), (PBRuleAction)ActionIdx(r->action),
                                    ResolveNativeCfg(r->cfgStoredId));
        if (r->nativeId && !r->enabled) g_api.DisableRule(r->nativeId);
    }
}

static UINT32 EngineAddRule(PBRule* r)
{
    char proc[512], hosts[512], ports[256], domains[512];
    W2Ux(r->proc, proc, sizeof(proc)); W2Ux(r->hosts, hosts, sizeof(hosts));
    W2Ux(r->ports, ports, sizeof(ports)); W2Ux(r->domains, domains, sizeof(domains));
    UINT32 id = g_api.AddRule(proc, hosts, ports, domains,
                              (PBRuleProtocol)ProtoIdx(r->proto), (PBRuleAction)ActionIdx(r->action),
                              ResolveNativeCfg(r->cfgStoredId));
    if (id && !r->enabled) g_api.DisableRule(id);
    return id;
}

static void EngineEditRule(PBRule* r)
{
    char proc[512], hosts[512], ports[256], domains[512];
    W2Ux(r->proc, proc, sizeof(proc)); W2Ux(r->hosts, hosts, sizeof(hosts));
    W2Ux(r->ports, ports, sizeof(ports)); W2Ux(r->domains, domains, sizeof(domains));
    g_api.EditRule(r->nativeId, proc, hosts, ports, domains,
                   (PBRuleProtocol)ProtoIdx(r->proto), (PBRuleAction)ActionIdx(r->action),
                   ResolveNativeCfg(r->cfgStoredId));
    if (r->enabled) g_api.EnableRule(r->nativeId); else g_api.DisableRule(r->nativeId);
}

static void UnapplyProfile(void)
{
    for (int i = 0; i < g_profile.ruleCount; i++) if (g_profile.rule[i].nativeId) g_api.DeleteRule(g_profile.rule[i].nativeId);
    for (int i = 0; i < g_profile.cfgCount; i++) if (g_profile.cfg[i].nativeId) g_api.DeleteProxyConfig(g_profile.cfg[i].nativeId);
}

static void SwitchToProfile(const wchar_t* name)
{
    UnapplyProfile();
    PB_SetActiveProfile(name);
    lstrcpynW(g_activeProfile, name, PB_NAME_MAX);
    PB_ProfileLoad(name, &g_profile);
    g_localhost = g_profile.localhostViaProxy;
    g_trafficLog = g_profile.trafficLogging;
    g_closeToTray = g_profile.closeToTray;
    g_autoClear = g_profile.autoClearLogs;
    ApplyFilterSnapshot();
    g_api.SetLocalhostViaProxy(g_localhost);
    g_api.SetTrafficLoggingEnabled(g_trafficLog);
    ApplyConfigs();
    ApplyRules();
    SyncMenuChecks(g_hMain);
    RebuildProfileMenu(g_hMain);
    UpdateTitle();
}

static void UpdateTitle(void)
{
    wchar_t t[128]; _snwprintf_s(t, 128, _TRUNCATE, L"%s - %s", APP_TITLE, g_activeProfile);
    SetWindowTextW(g_hMain, t);
}

static void BuildMainMenu(HWND hwnd)
{
    HMENU bar = CreateMenu();

    HMENU proxy = CreatePopupMenu();
    AppendMenuW(proxy, MF_STRING, IDM_PROXY_SETTINGS, T(S_M_PROXY_SETTINGS));
    AppendMenuW(proxy, MF_STRING, IDM_PROXY_RULES,    T(S_M_PROXY_RULES));
    AppendMenuW(proxy, MF_STRING, IDM_LOG_FILTERS,    T(S_M_LOGFILTERS));
    AppendMenuW(bar, MF_POPUP, (UINT_PTR)proxy, T(S_M_PROXY));

    HMENU profile = CreatePopupMenu();
    AppendMenuW(profile, MF_STRING, IDM_PROFILE_NEW,    T(S_M_NEWPROFILE));
    AppendMenuW(profile, MF_STRING, IDM_PROFILE_RENAME, T(S_M_RENAME));
    AppendMenuW(profile, MF_STRING, IDM_PROFILE_DELETE, T(S_M_DELPROFILE));
    AppendMenuW(profile, MF_SEPARATOR, 0, NULL);
    AppendMenuW(profile, MF_STRING, IDM_PROFILE_IMPORT, T(S_M_IMPORT));
    AppendMenuW(profile, MF_STRING, IDM_PROFILE_EXPORT, T(S_M_EXPORT));
    AppendMenuW(profile, MF_SEPARATOR, 0, NULL);
    g_switchMenu = CreatePopupMenu();
    AppendMenuW(profile, MF_POPUP, (UINT_PTR)g_switchMenu, T(S_M_SWITCH));
    AppendMenuW(bar, MF_POPUP, (UINT_PTR)profile, T(S_M_PROFILE));

    HMENU settings = CreatePopupMenu();
    AppendMenuW(settings, MF_STRING, IDM_SET_LOCALHOST,   T(S_M_LOCALHOST));
    AppendMenuW(settings, MF_STRING, IDM_SET_TRAFFICLOG,  T(S_M_TRAFFIC));
    AppendMenuW(settings, MF_STRING, IDM_SET_CLOSETOTRAY, T(S_M_TRAY));
    AppendMenuW(settings, MF_STRING, IDM_SET_STARTUP,     T(S_M_STARTUP));
    AppendMenuW(settings, MF_STRING, IDM_SET_AUTOCLEAR,   T(S_M_AUTOCLEAR));
    AppendMenuW(settings, MF_SEPARATOR, 0, NULL);
    HMENU lang = CreatePopupMenu();
    AppendMenuW(lang, MF_STRING, IDM_LANG_EN, T(S_M_LANG_EN));
    AppendMenuW(lang, MF_STRING, IDM_LANG_ZH, T(S_M_LANG_ZH));
    AppendMenuW(settings, MF_POPUP, (UINT_PTR)lang, T(S_M_LANG));
    AppendMenuW(bar, MF_POPUP, (UINT_PTR)settings, T(S_M_SETTINGS));

    HMENU help = CreatePopupMenu();
    AppendMenuW(help, MF_STRING, IDM_HELP_DOCS,   T(S_M_DOCS));
    AppendMenuW(help, MF_STRING, IDM_HELP_UPDATE, T(S_M_UPDATE));
    AppendMenuW(help, MF_SEPARATOR, 0, NULL);
    AppendMenuW(help, MF_STRING, IDM_HELP_ABOUT,  T(S_M_ABOUT));
    AppendMenuW(bar, MF_POPUP, (UINT_PTR)help, T(S_M_HELP));

    HMENU old = GetMenu(hwnd);
    SetMenu(hwnd, bar);
    if (old) DestroyMenu(old);
}

static void RebuildProfileMenu(HWND hwnd)
{
    if (!g_switchMenu) return;
    while (GetMenuItemCount(g_switchMenu) > 0) DeleteMenu(g_switchMenu, 0, MF_BYPOSITION);
    g_profCount = PB_ProfileList(g_profNames, 64);
    for (int i = 0; i < g_profCount; i++)
    {
        UINT flags = MF_STRING | (_wcsicmp(g_profNames[i], g_activeProfile) == 0 ? MF_CHECKED : 0);
        AppendMenuW(g_switchMenu, flags, (UINT_PTR)(IDM_PROFILE_SWITCH_BASE + i), g_profNames[i]);
    }
    if (g_profCount == 0) AppendMenuW(g_switchMenu, MF_STRING | MF_GRAYED, IDM_PROFILE_SWITCH_BASE, L"-");
    DrawMenuBar(hwnd);
}

static void RelocalizeUI(HWND hwnd)
{
    BuildMainMenu(hwnd);
    RebuildProfileMenu(hwnd);
    SyncMenuChecks(hwnd);
    TCITEMW ti; ti.mask = TCIF_TEXT;
    ti.pszText = (LPWSTR)T(S_TAB_CONN); TabCtrl_SetItem(g_hTab, 0, &ti);
    ti.pszText = (LPWSTR)T(S_TAB_ACT);  TabCtrl_SetItem(g_hTab, 1, &ti);
    UpdateTitle();
    DrawMenuBar(hwnd);
}

static void TrayAdd(HWND hwnd)
{
    ZeroMemory(&g_tray, sizeof(g_tray));
    g_tray.cbSize = sizeof(g_tray);
    g_tray.hWnd = hwnd; g_tray.uID = 1;
    g_tray.uFlags = NIF_ICON | NIF_MESSAGE | NIF_TIP;
    g_tray.uCallbackMessage = WM_APP_TRAY;
    g_tray.hIcon = (HICON)LoadImageW(g_hInst, MAKEINTRESOURCEW(IDI_APPICON), IMAGE_ICON,
                                     GetSystemMetrics(SM_CXSMICON), GetSystemMetrics(SM_CYSMICON), 0);
    lstrcpynW(g_tray.szTip, APP_TITLE, ARRAYSIZE(g_tray.szTip));
    Shell_NotifyIconW(NIM_ADD, &g_tray);
    g_trayAdded = TRUE;
}

static void LayoutMain(HWND hwnd)
{
    RECT rc; GetClientRect(hwnd, &rc);
    int tabTop = 6, tabH = 32;               // small gap below the menu bar
    MoveWindow(g_hTab, 0, tabTop, rc.right, tabH, TRUE);
    int top = tabTop + tabH + 6;
    int barH = 30, clearW = 130, gap = 6;
    int searchW = rc.right - 4 - clearW - gap - 4;
    int logTop = top + barH + 4;
    int logH = rc.bottom - logTop - 4; if (logH < 0) logH = 0;
    // search box + Clear button row, then the log below (both tabs share the same rect)
    MoveWindow(g_hConnSearch, 4, top, searchW, barH - 6, TRUE);
    MoveWindow(g_hActSearch,  4, top, searchW, barH - 6, TRUE);
    MoveWindow(g_hConnClear,  4 + searchW + gap, top - 1, clearW, barH - 2, TRUE);
    MoveWindow(g_hActClear,   4 + searchW + gap, top - 1, clearW, barH - 2, TRUE);
    MoveWindow(g_hConnLog, 2, logTop, rc.right - 4, logH, TRUE);
    MoveWindow(g_hActLog,  2, logTop, rc.right - 4, logH, TRUE);
}

static void SelectTab(int idx)
{
    int c = (idx == 0) ? SW_SHOW : SW_HIDE;
    int a = (idx == 1) ? SW_SHOW : SW_HIDE;
    ShowWindow(g_hConnLog, c); ShowWindow(g_hConnSearch, c); ShowWindow(g_hConnClear, c);
    ShowWindow(g_hActLog,  a); ShowWindow(g_hActSearch,  a); ShowWindow(g_hActClear,  a);
}

static void SyncMenuChecks(HWND hwnd)
{
    HMENU m = GetMenu(hwnd);
    CheckMenuItem(m, IDM_SET_LOCALHOST,   MF_BYCOMMAND | (g_localhost  ? MF_CHECKED : MF_UNCHECKED));
    CheckMenuItem(m, IDM_SET_TRAFFICLOG,  MF_BYCOMMAND | (g_trafficLog ? MF_CHECKED : MF_UNCHECKED));
    CheckMenuItem(m, IDM_SET_CLOSETOTRAY, MF_BYCOMMAND | (g_closeToTray? MF_CHECKED : MF_UNCHECKED));
    CheckMenuItem(m, IDM_SET_STARTUP,     MF_BYCOMMAND | (g_startup    ? MF_CHECKED : MF_UNCHECKED));
    CheckMenuItem(m, IDM_SET_AUTOCLEAR,   MF_BYCOMMAND | (g_autoClear  ? MF_CHECKED : MF_UNCHECKED));
    int zh = (_wcsicmp(g_profile.language, L"zh") == 0);
    CheckMenuItem(m, IDM_LANG_EN, MF_BYCOMMAND | (zh ? MF_UNCHECKED : MF_CHECKED));
    CheckMenuItem(m, IDM_LANG_ZH, MF_BYCOMMAND | (zh ? MF_CHECKED : MF_UNCHECKED));
}

static BOOL PickFile(HWND owner, BOOL save, wchar_t* path, int cch)
{
    OPENFILENAMEW ofn; ZeroMemory(&ofn, sizeof(ofn));
    path[0] = 0;
    ofn.lStructSize = sizeof(ofn);
    ofn.hwndOwner = owner;
    ofn.lpstrFilter = L"ProxyBridge Profile (*.pbprofile)\0*.pbprofile\0All Files\0*.*\0";
    ofn.lpstrFile = path; ofn.nMaxFile = cch;
    ofn.lpstrDefExt = L"pbprofile";
    ofn.Flags = save ? (OFN_OVERWRITEPROMPT | OFN_PATHMUSTEXIST)
                     : (OFN_FILEMUSTEXIST | OFN_PATHMUSTEXIST);
    return save ? GetSaveFileNameW(&ofn) : GetOpenFileNameW(&ofn);
}

int WINAPI wWinMain(HINSTANCE hInst, HINSTANCE hPrev, PWSTR cmd, int show)
{
    (void)hPrev;
    g_hInst = hInst;
    BOOL startMinimized = (cmd && wcsstr(cmd, L"--minimized") != NULL);

    INITCOMMONCONTROLSEX icc = { sizeof(icc), ICC_TAB_CLASSES | ICC_LISTVIEW_CLASSES | ICC_BAR_CLASSES | ICC_STANDARD_CLASSES | ICC_LINK_CLASS | ICC_PROGRESS_CLASS };
    InitCommonControlsEx(&icc);

    if (!PB_Load(&g_api))
    {
        MessageBoxW(NULL, L"Could not load ProxyBridgeCore.dll.\n"
                          L"Make sure it is in the same folder as this executable.",
                    APP_TITLE, MB_OK | MB_ICONERROR);
        return 1;
    }

    // Load the active profile.
    PB_GetActiveProfile(g_activeProfile, PB_NAME_MAX);
    PB_ProfileLoad(g_activeProfile, &g_profile);
    g_localhost   = g_profile.localhostViaProxy;
    g_trafficLog  = g_profile.trafficLogging;
    g_closeToTray = g_profile.closeToTray;
    g_lang        = (_wcsicmp(g_profile.language, L"zh") == 0) ? 1 : 0;

    // Refuse to start if another GUI or the CLI is already running - they'd both grab the
    // WinDivert driver and the same relay ports.
    if (AnotherInstanceRunning())
    {
        MessageBoxW(NULL, T(S_ERR_RUNNING), APP_TITLE, MB_OK | MB_ICONWARNING);
        return 0;
    }

    g_autoClear   = g_profile.autoClearLogs;
    g_startup     = StartupIsEnabled();
    ApplyFilterSnapshot();

    CreateDarkBrushes();   // needed for the window class background below

    WNDCLASSEXW wc; ZeroMemory(&wc, sizeof(wc));
    wc.cbSize = sizeof(wc);
    wc.lpfnWndProc = WndProc;
    wc.hInstance = hInst;
    wc.hIcon = (HICON)LoadImageW(hInst, MAKEINTRESOURCEW(IDI_APPICON), IMAGE_ICON, 0, 0, LR_DEFAULTSIZE);
    wc.hIconSm = wc.hIcon;
    wc.hCursor = LoadCursorW(NULL, IDC_ARROW);
    wc.hbrBackground = g_brBg;
    wc.lpszClassName = WND_CLASS;
    wc.lpszMenuName = NULL;   // menu is built programmatically (localizable)
    if (!RegisterClassExW(&wc)) return 1;

    g_hMain = CreateWindowExW(0, WND_CLASS, APP_TITLE, WS_OVERLAPPEDWINDOW,
                              CW_USEDEFAULT, CW_USEDEFAULT, 1200, 820, NULL, NULL, hInst, NULL);
    if (!g_hMain) return 1;

    // Center on the working area of the monitor the window landed on (CW_USEDEFAULT places
    // it top-left otherwise).
    {
        RECT wr; GetWindowRect(g_hMain, &wr);
        int ww = wr.right - wr.left, wh = wr.bottom - wr.top;
        HMONITOR mon = MonitorFromWindow(g_hMain, MONITOR_DEFAULTTONEAREST);
        MONITORINFO mi; mi.cbSize = sizeof(mi);
        if (GetMonitorInfoW(mon, &mi))
        {
            int x = mi.rcWork.left + (mi.rcWork.right - mi.rcWork.left - ww) / 2;
            int y = mi.rcWork.top  + (mi.rcWork.bottom - mi.rcWork.top - wh) / 2;
            SetWindowPos(g_hMain, NULL, x, y, 0, 0, SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
        }
    }

    BuildMainMenu(g_hMain);
    DrawMenuBar(g_hMain);
    TrayAdd(g_hMain);
    SyncMenuChecks(g_hMain);
    RebuildProfileMenu(g_hMain);
    UpdateTitle();

    // Wire callbacks + toggles, add configs (before Start so the UDP relay starts), start,
    // then add rules - mirroring the C# startup order.
    g_api.SetLocalhostViaProxy(g_localhost);
    g_api.SetTrafficLoggingEnabled(g_trafficLog);
    g_api.SetLogCallback(PBLogCb);
    g_api.SetConnectionCallback(PBConnCb);
    ApplyConfigs();
    g_started = g_api.Start();
    if (g_started) { ApplyRules(); LogStoreAdd(&g_actStore, T(S_STARTED)); }
    else LogStoreAdd(&g_actStore, T(S_STARTFAIL));

    if (startMinimized) ShowWindow(g_hMain, SW_HIDE);   // launched by the logon task
    else { ShowWindow(g_hMain, show); UpdateWindow(g_hMain); }

    // Silent update check on startup (opt-out via the notification's "Don't Ask Again").
    if (PB_GetCheckUpdates()) UpdStartCheck(g_hMain, FALSE);

    MSG msg;
    while (GetMessageW(&msg, NULL, 0, 0) > 0)
    {
        if (IsDialogMessageW(g_hMain, &msg)) continue;
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }
    return (int)msg.wParam;
}

static void u2w(const char* s, wchar_t* out, int cch)
{
    if (!s) { if (cch) out[0] = 0; return; }
    MultiByteToWideChar(CP_UTF8, 0, s, -1, out, cch);
}

static void w2u(const wchar_t* w, char* out, int cch)
{
    if (!w) { if (cch) out[0] = 0; return; }
    WideCharToMultiByte(CP_UTF8, 0, w, -1, out, cch, NULL, NULL);
}

static void base_dir(wchar_t* out, int cch)
{
    wchar_t appdata[MAX_PATH];
    if (!GetEnvironmentVariableW(L"APPDATA", appdata, MAX_PATH)) appdata[0] = 0;
    _snwprintf_s(out, cch, _TRUNCATE, L"%s\\ProxyBridge", appdata);
}

static void ensure_dirs(void)
{
    wchar_t b[MAX_PATH], d[MAX_PATH];
    base_dir(b, MAX_PATH); CreateDirectoryW(b, NULL);
    profiles_dir(d, MAX_PATH); CreateDirectoryW(d, NULL);
}

static char* read_file(const wchar_t* path, DWORD* outLen)
{
    HANDLE h = CreateFileW(path, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (h == INVALID_HANDLE_VALUE) return NULL;
    DWORD sz = GetFileSize(h, NULL);
    if (sz == INVALID_FILE_SIZE || sz > (64u * 1024u * 1024u)) { CloseHandle(h); return NULL; }
    char* buf = (char*)malloc(sz + 1);
    if (!buf) { CloseHandle(h); return NULL; }
    DWORD rd = 0;
    BOOL ok = ReadFile(h, buf, sz, &rd, NULL);
    CloseHandle(h);
    if (!ok) { free(buf); return NULL; }
    buf[rd] = 0;
    if (rd >= 3 && (unsigned char)buf[0] == 0xEF && (unsigned char)buf[1] == 0xBB && (unsigned char)buf[2] == 0xBF)
    { memmove(buf, buf + 3, rd - 3 + 1); rd -= 3; }
    if (outLen) *outLen = rd;
    return buf;
}

static BOOL write_file_atomic(const wchar_t* path, const char* data, size_t len)
{
    wchar_t tmp[MAX_PATH]; _snwprintf_s(tmp, MAX_PATH, _TRUNCATE, L"%s.tmp", path);
    HANDLE h = CreateFileW(tmp, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);
    if (h == INVALID_HANDLE_VALUE) return FALSE;
    DWORD wr = 0;
    BOOL ok = WriteFile(h, data, (DWORD)len, &wr, NULL) && wr == (DWORD)len;
    CloseHandle(h);
    if (!ok) { DeleteFileW(tmp); return FALSE; }
    if (!MoveFileExW(tmp, path, MOVEFILE_REPLACE_EXISTING)) { DeleteFileW(tmp); return FALSE; }
    return TRUE;
}

static void settings_load(Settings* s)
{
    s->checkUpd = 1; s->startWin = 0;
    strcpy_s(s->lastCheck,  sizeof(s->lastCheck),  "0001-01-01T00:00:00");
    strcpy_s(s->activeName, sizeof(s->activeName), "Default");
    wchar_t sp[MAX_PATH]; settings_path(sp, MAX_PATH);
    DWORD len = 0; char* txt = read_file(sp, &len);
    if (!txt) return;
    JVal* root = json_parse(txt, len);
    if (root)
    {
        s->checkUpd = json_bool(root, "CheckForUpdatesOnStartup", 1);
        s->startWin = json_bool(root, "StartWithWindows", 0);
        const char* lc = json_str(root, "LastUpdateCheck", NULL);
        if (lc) strncpy_s(s->lastCheck, sizeof(s->lastCheck), lc, _TRUNCATE);
        const char* an = json_str(root, "ActiveProfileName", NULL);
        if (an) strncpy_s(s->activeName, sizeof(s->activeName), an, _TRUNCATE);
        json_free(root);
    }
    free(txt);
}

static void settings_save(const Settings* s)
{
    ensure_dirs();
    wchar_t sp[MAX_PATH]; settings_path(sp, MAX_PATH);
    StrBuf b; sb_init(&b);
    sb_put(&b, "{\n");
    sb_put(&b, "  \"CheckForUpdatesOnStartup\": "); sb_put(&b, s->checkUpd ? "true" : "false"); sb_put(&b, ",\n");
    sb_put(&b, "  \"LastUpdateCheck\": "); sb_json_str(&b, s->lastCheck); sb_put(&b, ",\n");
    sb_put(&b, "  \"StartWithWindows\": "); sb_put(&b, s->startWin ? "true" : "false"); sb_put(&b, ",\n");
    sb_put(&b, "  \"ActiveProfileName\": "); sb_json_str(&b, s->activeName); sb_put(&b, "\n}\n");
    write_file_atomic(sp, b.buf, b.len);
    sb_free(&b);
}

void PB_GetActiveProfile(wchar_t* out, int cch)
{
    Settings s; settings_load(&s);
    u2w(s.activeName, out, cch);
}

void PB_SetActiveProfile(const wchar_t* name)
{
    Settings s; settings_load(&s);
    w2u(name, s.activeName, sizeof(s.activeName));
    settings_save(&s);
}

BOOL PB_GetCheckUpdates(void)
{
    Settings s; settings_load(&s);
    return s.checkUpd ? TRUE : FALSE;
}

void PB_SetCheckUpdates(BOOL enable)
{
    Settings s; settings_load(&s);
    s.checkUpd = enable ? 1 : 0;
    settings_save(&s);
}

void PB_ProfileDefaults(PBProfile* p, const wchar_t* name)
{
    (void)name;
    ZeroMemory(p, sizeof(*p));
    p->localhostViaProxy = 0;
    p->trafficLogging    = 1;
    p->autoClearLogs     = 1;
    p->closeToTray       = 1;
    lstrcpynW(p->language, L"en", 8);
}

void PB_ProfileLoad(const wchar_t* name, PBProfile* p)
{
    PB_ProfileDefaults(p, name);
    wchar_t pp[MAX_PATH]; profile_path(name, pp, MAX_PATH);
    DWORD len = 0; char* txt = read_file(pp, &len);
    if (!txt) return;
    JVal* root = json_parse(txt, len);
    if (root && root->type == J_OBJ)
    {
        p->localhostViaProxy = json_bool(root, "LocalhostViaProxy", 0);
        p->trafficLogging    = json_bool(root, "IsTrafficLoggingEnabled", 1);
        p->autoClearLogs     = json_bool(root, "AutoClearConnectionLogs", 1);
        p->closeToTray       = json_bool(root, "CloseToTray", 1);
        u2w(json_str(root, "Language", "en"), p->language, 8);

        JVal* cfgs = json_get(root, "ProxyConfigs");
        if (cfgs && cfgs->type == J_ARR)
            for (JVal* c = cfgs->child; c && p->cfgCount < PB_MAX_CFG; c = c->next)
            {
                if (c->type != J_OBJ) continue;
                PBConfig* cf = &p->cfg[p->cfgCount++];
                cf->storedId = (UINT32)json_long(c, "Id", 0);
                u2w(json_str(c, "Type", "SOCKS5"), cf->type, 16);
                u2w(json_str(c, "Host", ""), cf->host, 128);
                u2w(json_str(c, "Port", ""), cf->port, 16);
                u2w(json_str(c, "Username", ""), cf->user, 128);
                u2w(json_str(c, "Password", ""), cf->pass, 128);
            }

        JVal* rules = json_get(root, "ProxyRules");
        if (rules && rules->type == J_ARR)
            for (JVal* r = rules->child; r && p->ruleCount < PB_MAX_RULE; r = r->next)
            {
                if (r->type != J_OBJ) continue;
                PBRule* ru = &p->rule[p->ruleCount++];
                u2w(json_str(r, "ProcessName", "*"), ru->proc, 256);
                u2w(json_str(r, "TargetHosts", "*"), ru->hosts, 256);
                u2w(json_str(r, "TargetPorts", "*"), ru->ports, 128);
                u2w(json_str(r, "TargetDomains", "*"), ru->domains, 256);
                u2w(json_str(r, "Protocol", "TCP"), ru->proto, 8);
                u2w(json_str(r, "Action", "PROXY"), ru->action, 16);
                ru->enabled = json_bool(r, "IsEnabled", 1);
                ru->cfgStoredId = (UINT32)json_long(r, "ProxyConfigId", 0);
            }

        JVal* filters = json_get(root, "LogFilters");
        if (filters && filters->type == J_ARR)
            for (JVal* f = filters->child; f && p->filterCount < PB_MAX_FILTER; f = f->next)
            {
                if (f->type != J_OBJ) continue;
                PBFilter* fi = &p->filter[p->filterCount++];
                u2w(json_str(f, "Mode", "Include"), fi->mode, 16);
                u2w(json_str(f, "ProcessName", ""), fi->proc, 256);
                u2w(json_str(f, "Ip", ""), fi->ip, 64);
                u2w(json_str(f, "Port", ""), fi->port, 16);
                u2w(json_str(f, "Protocol", "All"), fi->proto, 8);
                u2w(json_str(f, "Action", "All"), fi->action, 16);
            }
    }
    if (root) json_free(root);
    free(txt);
}

static void put_kv_str(StrBuf* b, const char* indent, const char* key, const wchar_t* wval, const char* trail)
{
    char tmp[1024]; w2u(wval, tmp, sizeof(tmp));
    sb_put(b, indent); sb_put(b, "\""); sb_put(b, key); sb_put(b, "\": ");
    sb_json_str(b, tmp); sb_put(b, trail);
}

BOOL PB_ProfileSave(const wchar_t* name, const PBProfile* p)
{
    ensure_dirs();
    char tmp[1024];
    StrBuf b; sb_init(&b);
    sb_put(&b, "{\n");
    sb_put(&b, "  \"Version\": \"1.0\",\n");
    put_kv_str(&b, "  ", "Name", name, ",\n");
    sb_put(&b, "  \"LocalhostViaProxy\": ");       sb_put(&b, p->localhostViaProxy ? "true" : "false"); sb_put(&b, ",\n");
    sb_put(&b, "  \"IsTrafficLoggingEnabled\": ");  sb_put(&b, p->trafficLogging ? "true" : "false");    sb_put(&b, ",\n");
    sb_put(&b, "  \"AutoClearConnectionLogs\": ");  sb_put(&b, p->autoClearLogs ? "true" : "false");     sb_put(&b, ",\n");
    put_kv_str(&b, "  ", "Language", p->language, ",\n");
    sb_put(&b, "  \"CloseToTray\": ");              sb_put(&b, p->closeToTray ? "true" : "false");       sb_put(&b, ",\n");

    sb_put(&b, "  \"ProxyConfigs\": [");
    for (int i = 0; i < p->cfgCount; i++)
    {
        const PBConfig* c = &p->cfg[i];
        sb_put(&b, i ? ",\n" : "\n"); sb_put(&b, "    {\n");
        snprintf(tmp, sizeof(tmp), "%u", c->storedId);
        sb_put(&b, "      \"Id\": "); sb_put(&b, tmp); sb_put(&b, ",\n");
        put_kv_str(&b, "      ", "Type", c->type, ",\n");
        put_kv_str(&b, "      ", "Host", c->host, ",\n");
        put_kv_str(&b, "      ", "Port", c->port, ",\n");
        put_kv_str(&b, "      ", "Username", c->user, ",\n");
        put_kv_str(&b, "      ", "Password", c->pass, "\n");
        sb_put(&b, "    }");
    }
    sb_put(&b, p->cfgCount ? "\n  ],\n" : "],\n");

    sb_put(&b, "  \"ProxyRules\": [");
    for (int i = 0; i < p->ruleCount; i++)
    {
        const PBRule* r = &p->rule[i];
        sb_put(&b, i ? ",\n" : "\n"); sb_put(&b, "    {\n");
        put_kv_str(&b, "      ", "ProcessName", r->proc, ",\n");
        put_kv_str(&b, "      ", "TargetHosts", r->hosts, ",\n");
        put_kv_str(&b, "      ", "TargetPorts", r->ports, ",\n");
        put_kv_str(&b, "      ", "TargetDomains", r->domains, ",\n");
        put_kv_str(&b, "      ", "Protocol", r->proto, ",\n");
        put_kv_str(&b, "      ", "Action", r->action, ",\n");
        sb_put(&b, "      \"IsEnabled\": "); sb_put(&b, r->enabled ? "true" : "false"); sb_put(&b, ",\n");
        snprintf(tmp, sizeof(tmp), "%u", r->cfgStoredId);
        sb_put(&b, "      \"ProxyConfigId\": "); sb_put(&b, tmp); sb_put(&b, "\n");
        sb_put(&b, "    }");
    }
    sb_put(&b, p->ruleCount ? "\n  ],\n" : "],\n");

    sb_put(&b, "  \"LogFilters\": [");
    for (int i = 0; i < p->filterCount; i++)
    {
        const PBFilter* f = &p->filter[i];
        sb_put(&b, i ? ",\n" : "\n"); sb_put(&b, "    {\n");
        put_kv_str(&b, "      ", "Mode", f->mode, ",\n");
        put_kv_str(&b, "      ", "ProcessName", f->proc, ",\n");
        put_kv_str(&b, "      ", "Ip", f->ip, ",\n");
        put_kv_str(&b, "      ", "Port", f->port, ",\n");
        put_kv_str(&b, "      ", "Protocol", f->proto, ",\n");
        put_kv_str(&b, "      ", "Action", f->action, "\n");
        sb_put(&b, "    }");
    }
    sb_put(&b, p->filterCount ? "\n  ]\n" : "]\n");
    sb_put(&b, "}\n");

    wchar_t pp[MAX_PATH]; profile_path(name, pp, MAX_PATH);
    BOOL ok = write_file_atomic(pp, b.buf, b.len);
    sb_free(&b);
    return ok;
}

int PB_ProfileList(wchar_t names[][PB_NAME_MAX], int maxNames)
{
    ensure_dirs();
    wchar_t dir[MAX_PATH], pat[MAX_PATH];
    profiles_dir(dir, MAX_PATH);
    _snwprintf_s(pat, MAX_PATH, _TRUNCATE, L"%s\\*.pbprofile", dir);
    WIN32_FIND_DATAW fd; HANDLE h = FindFirstFileW(pat, &fd);
    int n = 0;
    if (h != INVALID_HANDLE_VALUE)
    {
        do {
            if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) continue;
            wchar_t nm[PB_NAME_MAX]; lstrcpynW(nm, fd.cFileName, PB_NAME_MAX);
            size_t l = wcslen(nm);
            if (l > 10 && _wcsicmp(nm + l - 10, L".pbprofile") == 0) nm[l - 10] = 0;
            if (n < maxNames) lstrcpynW(names[n++], nm, PB_NAME_MAX);
        } while (FindNextFileW(h, &fd));
        FindClose(h);
    }
    return n;
}

BOOL PB_ProfileDelete(const wchar_t* name)
{
    wchar_t pp[MAX_PATH]; profile_path(name, pp, MAX_PATH);
    return DeleteFileW(pp);
}

BOOL PB_ProfileRename(const wchar_t* oldName, const wchar_t* newName)
{
    if (!newName || !newName[0]) return FALSE;
    wchar_t src[MAX_PATH], dst[MAX_PATH];
    profile_path(oldName, src, MAX_PATH);
    profile_path(newName, dst, MAX_PATH);
    if (GetFileAttributesW(dst) != INVALID_FILE_ATTRIBUTES) return FALSE;   // target exists
    if (!MoveFileW(src, dst)) return FALSE;
    // Repoint the active-profile setting if we just renamed the active one.
    wchar_t active[PB_NAME_MAX]; PB_GetActiveProfile(active, PB_NAME_MAX);
    if (_wcsicmp(active, oldName) == 0) PB_SetActiveProfile(newName);
    return TRUE;
}

BOOL PB_ProfileExport(const wchar_t* name, const wchar_t* destPath)
{
    wchar_t pp[MAX_PATH]; profile_path(name, pp, MAX_PATH);
    return CopyFileW(pp, destPath, FALSE);
}

BOOL PB_ProfileImport(const wchar_t* srcPath, wchar_t* assignedName, int cch)
{
    const wchar_t* fn = wcsrchr(srcPath, L'\\'); fn = fn ? fn + 1 : srcPath;
    wchar_t base[PB_NAME_MAX]; lstrcpynW(base, fn, PB_NAME_MAX);
    size_t l = wcslen(base);
    if (l > 10 && _wcsicmp(base + l - 10, L".pbprofile") == 0) base[l - 10] = 0;
    if (!base[0]) lstrcpynW(base, L"Imported", PB_NAME_MAX);
    for (wchar_t* q = base; *q; q++) if (wcschr(L"<>:\"/\\|?*", *q)) *q = L'_';

    wchar_t name[PB_NAME_MAX]; lstrcpynW(name, base, PB_NAME_MAX);
    for (int i = 2; i <= 99; i++)
    {
        wchar_t pp[MAX_PATH]; profile_path(name, pp, MAX_PATH);
        if (GetFileAttributesW(pp) == INVALID_FILE_ATTRIBUTES) break;
        _snwprintf_s(name, PB_NAME_MAX, _TRUNCATE, L"%s (%d)", base, i);
    }
    ensure_dirs();
    wchar_t dpp[MAX_PATH]; profile_path(name, dpp, MAX_PATH);
    if (!CopyFileW(srcPath, dpp, FALSE)) return FALSE;
    lstrcpynW(assignedName, name, cch);
    return TRUE;
}

PROXYBRIDGE_API int ProxyBridge_TestProxyConfigEx(UINT32 config_id, const char* target_host, UINT16 target_port,
                                                  ProxyTestLogCallback cb, void* user)
{
    #define TLOG(...) do { if (cb) { char _l[300]; _snprintf_s(_l, sizeof(_l), _TRUNCATE, __VA_ARGS__); cb(_l, user); } } while (0)

    PROXY_CONFIG *cfg = find_proxy_config(config_id);
    if (cfg == NULL) { TLOG("[FAIL] No proxy config found"); return -1; }
    if (target_host == NULL || target_host[0] == '\0') target_host = "www.google.com";
    if (target_port == 0) target_port = 80;

    BOOL is_socks = (cfg->type == PROXY_TYPE_SOCKS5);
    BOOL use_auth = (cfg->username[0] != '\0');

    TLOG("Proxy:    %s:%u", cfg->host, cfg->port);
    TLOG("Protocol: %s", is_socks ? "SOCKS5" : "HTTP");
    TLOG("Auth:     %s", use_auth ? "yes" : "no");
    TLOG("Target:   %s:%u", target_host, target_port);

    UINT32 proxy_ip = resolve_hostname(cfg->host);
    if (proxy_ip == 0) { TLOG(""); TLOG("[FAIL] Could not resolve proxy host '%s'", cfg->host); return -1; }
    struct in_addr pa; pa.s_addr = proxy_ip;
    TLOG("Proxy IP: %s", inet_ntoa(pa));

    int overall = 0;

    // ── Test 1: TCP connection to the proxy server ───────────────────────────
    TLOG("");
    TLOG("Test 1: Connection to the proxy server");
    SOCKET s = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (s == INVALID_SOCKET) { TLOG("  [FAIL] Failed to create socket"); return -1; }
    DWORD to = 10000;
    setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, (const char*)&to, sizeof(to));
    setsockopt(s, SOL_SOCKET, SO_SNDTIMEO, (const char*)&to, sizeof(to));
    struct sockaddr_in paddr; memset(&paddr, 0, sizeof(paddr));
    paddr.sin_family = AF_INET; paddr.sin_port = htons(cfg->port); paddr.sin_addr.s_addr = proxy_ip;
    ULONGLONG c0 = GetTickCount64();
    if (connect(s, (struct sockaddr*)&paddr, sizeof(paddr)) != 0)
    {
        TLOG("  [FAIL] Could not connect to the proxy server");
        closesocket(s);
        TLOG(""); TLOG("Testing finished: proxy is NOT reachable.");
        return -1;
    }
    ULONGLONG c1 = GetTickCount64();
    ULONGLONG connect_ms = c1 - c0;
    TLOG("  Connection established (%llu ms)", connect_ms);
    TLOG("  Test 1 passed");

    // ── Test 2: Connection through the proxy server ──────────────────────────
    TLOG("");
    TLOG("Test 2: Connection through the proxy server");
    UINT32 dest_ip = resolve_hostname(target_host);
    if (dest_ip == 0)
    {
        TLOG("  [FAIL] Could not resolve target host '%s'", target_host);
        closesocket(s);
        overall = -1;
    }
    else
    {
        ULONGLONG h0 = GetTickCount64();
        int rc = is_socks ? socks5_connect(s, dest_ip, target_port, cfg)
                          : http_connect(s, dest_ip, target_port, cfg);
        ULONGLONG h1 = GetTickCount64();
        if (rc != 0)
        {
            TLOG("  [FAIL] Could not establish a tunnel through the proxy (code %d)", rc);
            if (use_auth) TLOG("  Hint: verify the proxy credentials");
            overall = -1;
        }
        else
        {
            if (use_auth) TLOG("  Authentication was successful");
            TLOG("  Connection to %s:%u established through the proxy (%llu ms)", target_host, target_port, h1 - h0);

            // Try to load a default web page (best-effort; needs a web server on the target).
            char req[256];
            int rn = _snprintf_s(req, sizeof(req), _TRUNCATE,
                                 "GET / HTTP/1.0\r\nHost: %s\r\nUser-Agent: ProxyBridge-Check\r\nConnection: close\r\n\r\n",
                                 target_host);
            if (rn > 0 && send(s, req, rn, 0) == rn)
            {
                char resp[512]; int got = recv(s, resp, sizeof(resp) - 1, 0);
                if (got > 0)
                {
                    resp[got] = '\0';
                    if (strncmp(resp, "HTTP/", 5) == 0)
                    {
                        char status[64] = {0};
                        const char* nl = strchr(resp, '\r'); size_t sl = nl ? (size_t)(nl - resp) : 0;
                        if (sl > 0 && sl < sizeof(status)) { memcpy(status, resp, sl); status[sl] = 0; }
                        TLOG("  Default web page loaded: %s", status[0] ? status : "HTTP response received");
                    }
                    else TLOG("  Received %d bytes (non-HTTP target)", got);
                }
                else TLOG("  Note: no page data returned (target may not run a web server)");
            }
            TLOG("  Test 2 passed");
        }
    }
    closesocket(s);

    // ── Test 3: Proxy server latency ─────────────────────────────────────────
    TLOG("");
    TLOG("Test 3: Proxy server latency");
    TLOG("  Latency = %llu ms", connect_ms);
    TLOG("  Test 3 passed");

    // ── Test 4: SOCKS5 UDP ASSOCIATE support ─────────────────────────────────
    if (is_socks)
    {
        TLOG("");
        TLOG("Test 4: SOCKS5 UDP ASSOCIATE support");
        SOCKET us = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
        if (us != INVALID_SOCKET)
        {
            setsockopt(us, SOL_SOCKET, SO_RCVTIMEO, (const char*)&to, sizeof(to));
            setsockopt(us, SOL_SOCKET, SO_SNDTIMEO, (const char*)&to, sizeof(to));
            if (connect(us, (struct sockaddr*)&paddr, sizeof(paddr)) == 0)
            {
                struct sockaddr_in relay; memset(&relay, 0, sizeof(relay));
                int urc = socks5_udp_associate_with_config(us, &relay, cfg);
                if (urc == 0)
                {
                    TLOG("  UDP ASSOCIATE granted; relay = %s:%u", inet_ntoa(relay.sin_addr), ntohs(relay.sin_port));
                    TLOG("  UDP is supported by this proxy");
                }
                else TLOG("  UDP ASSOCIATE refused — this proxy does not support UDP");
            }
            else TLOG("  Could not open a control connection for the UDP test");
            closesocket(us);
        }
    }

    TLOG("");
    TLOG(overall == 0 ? "Testing finished: proxy is ready to work." : "Testing finished with errors.");
    return overall;

    #undef TLOG
}

static BOOL match_domain_pattern(const char *pattern, const char *domain)
{
    if (pattern == NULL || pattern[0] == '\0' || strcmp(pattern, "*") == 0)
        return TRUE;
    if (domain == NULL || domain[0] == '\0')
        return FALSE;

    // "*.example.com" should also match the bare apex "example.com" (Proxifier/Clash convention).
    if (pattern[0] == '*' && pattern[1] == '.' && pattern[2] != '\0')
    {
        if (_stricmp(pattern + 2, domain) == 0)
            return TRUE;
    }

    if (strchr(pattern, '*') != NULL)
        return wildcard_match(pattern, domain);

    return _stricmp(pattern, domain) == 0;
}

static BOOL match_domain_list(const char *domain_list, const char *domain)
{
    if (domain_list == NULL || domain_list[0] == '\0' || strcmp(domain_list, "*") == 0)
        return TRUE;
    if (domain == NULL || domain[0] == '\0')
        return FALSE;

    size_t len = strnlen_s(domain_list, MAX_LIST_SIZE) + 1;
    char *list_copy = (char *)malloc(len);
    if (list_copy == NULL)
        return FALSE;

    strncpy_s(list_copy, len, domain_list, _TRUNCATE);
    BOOL matched = FALSE;
    char *context = NULL;
    char *token = strtok_s(list_copy, ",;", &context);
    while (token != NULL)
    {
        while (*token == ' ' || *token == '\t')
            token++;
        char *end = token + strnlen_s(token, MAX_LIST_SIZE);
        while (end > token && (end[-1] == ' ' || end[-1] == '\t'))
            *(--end) = '\0';

        if (token[0] != '\0' && match_domain_pattern(token, domain))
        {
            matched = TRUE;
            break;
        }
        token = strtok_s(NULL, ",;", &context);
    }
    free(list_copy);
    return matched;
}

static BOOL rule_has_domain_filter(const PROCESS_RULE *rule)
{
    return rule->target_domains != NULL &&
           rule->target_domains[0] != '\0' &&
           strcmp(rule->target_domains, "*") != 0;
}

static BOOL match_domain_filter(const PROCESS_RULE *rule, const char *domain)
{
    if (!rule_has_domain_filter(rule))
        return TRUE;
    if (domain == NULL || domain[0] == '\0')
        return FALSE;
    return match_domain_list(rule->target_domains, domain);
}

static void flush_dns_resolver_cache(void)
{
    HMODULE dnsapi = LoadLibraryA("dnsapi.dll");
    if (dnsapi == NULL)
        return;
    typedef BOOL (WINAPI *DnsFlushFn)(void);
    DnsFlushFn fn = (DnsFlushFn)GetProcAddress(dnsapi, "DnsFlushResolverCache");
    if (fn != NULL)
        fn();
    FreeLibrary(dnsapi);
}

void write_tor_nat_rules6(char *lan_if)
{
	char *nv, *nvp, *b;
	char addr_new[32];
	int addr_type;
	const char *lan6_ip;
	char lan6_class[64];
	char *dnsport, *transport;
	int plen;

	if (!ipv6_enabled() || !nvram_match("Tor_enable", "1"))
		return;

	lan6_ip = ipv6_router_address(NULL);
	if (!lan6_ip || !*lan6_ip)
		return;

	plen = nvram_get_int(ipv6_nvname("ipv6_prefix_length"));
	if (plen <= 0 || plen > 128)
		plen = 64;
	snprintf(lan6_class, sizeof(lan6_class), "%s/%d", lan6_ip, plen);

	dnsport = nvram_safe_get("Tor_dnsport");
	transport = nvram_safe_get("Tor_transport");

	nv = nvp = strdup(nvram_safe_get("Tor_redir_list"));
	if (!nv)
		return;

	if (strlen(nv) == 0) {
		eval("ip6tables", "-t", "nat", "-I", "PREROUTING", "-i", lan_if,
			"-p", "udp", "--dport", "53", "-j", "REDIRECT", "--to-ports", dnsport);
		eval("ip6tables", "-t", "nat", "-I", "PREROUTING", "-i", lan_if,
			"-p", "udp", "--dport", "123", "-j", "REDIRECT", "--to-ports", "123");
		eval("ip6tables", "-t", "nat", "-I", "PREROUTING", "-i", lan_if,
			"-p", "tcp", "--syn", "!", "-d", lan6_class, "-j", "REDIRECT", "--to-ports", transport);
	} else {
		while ((b = strsep(&nvp, "<")) != NULL) {
			if (strlen(b) == 0)
				continue;
			memset(addr_new, 0, sizeof(addr_new));
			addr_type = addr_type_parse(b, addr_new, sizeof(addr_new));
			if (addr_type != TYPE_MAC)
				continue;

			eval("ip6tables", "-t", "nat", "-I", "PREROUTING", "-i", lan_if,
				"-p", "udp", "--dport", "53", "-m", "mac", "--mac-source", addr_new,
				"-j", "REDIRECT", "--to-ports", dnsport);
			eval("ip6tables", "-t", "nat", "-I", "PREROUTING", "-i", lan_if,
				"-p", "udp", "--dport", "123", "-m", "mac", "--mac-source", addr_new,
				"-j", "REDIRECT", "--to-ports", "123");
			eval("ip6tables", "-t", "nat", "-I", "PREROUTING", "-i", lan_if,
				"-p", "tcp", "--syn", "!", "-d", lan6_class, "-m", "mac", "--mac-source", addr_new,
				"-j", "REDIRECT", "--to-ports", transport);
		}
	}
	free(nv);
}

static void reap_orphaned_requests(struct libusb_context *ctx)
{
	struct hub_ioctl_request *req, *next_req;

	usbi_mutex_static_lock(&orphaned_requests_lock);
	list_for_each_entry_safe(req, next_req, &orphaned_requests, list, struct hub_ioctl_request) {
		if (HasOverlappedIoCompleted(&req->overlapped)) {
			usbi_dbg(ctx, "orphaned hub request %p has completed, freeing it", (void *)req);
			list_del(&req->list);
			CloseHandle(req->overlapped.hEvent);
			free(req);
		}
	}
	usbi_mutex_static_unlock(&orphaned_requests_lock);
}

static BOOL hub_device_io_control(struct libusb_context *ctx, HANDLE handle, DWORD ioctl_code,
	const void *in_buf, DWORD in_size, void *out_buf, DWORD out_size, DWORD *bytes_returned)
{
	struct hub_ioctl_request *req;
	unsigned char *req_buf;
	DWORD error, bytes;
	BOOL ret;

	*bytes_returned = 0;

	reap_orphaned_requests(ctx);

	// All hub IOCTLs are METHOD_BUFFERED: the kernel uses a single intermediate
	// buffer for input and output, so one request buffer can stand in for both
	// of the caller's (possibly aliased) buffers
	assert((ioctl_code & 0x3) == METHOD_BUFFERED);

	req = (struct hub_ioctl_request *)calloc(1, sizeof(*req) + MAX(in_size, out_size));
	if (req == NULL) {
		SetLastError(ERROR_NOT_ENOUGH_MEMORY);
		return FALSE;
	}
	req_buf = (unsigned char *)(req + 1);

	// Manual-reset, so that waiting on it does not consume the completion state
	req->overlapped.hEvent = CreateEventA(NULL, TRUE, FALSE, NULL);
	if (req->overlapped.hEvent == NULL) {
		error = GetLastError();
		free(req);
		SetLastError(error);
		return FALSE;
	}

	if (in_size != 0)
		memcpy(req_buf, in_buf, in_size);

	if (!DeviceIoControl(handle, ioctl_code, (in_size != 0) ? req_buf : NULL, in_size,
			req_buf, out_size, NULL, &req->overlapped)) {
		error = GetLastError();
		if (error != ERROR_IO_PENDING) {
			// Failed synchronously - no I/O was ever queued
			CloseHandle(req->overlapped.hEvent);
			free(req);
			SetLastError(error);
			return FALSE;
		}
	}
	// Even on synchronous success the completion state and event are set,
	// so a single wait-and-collect path handles both cases

	if (WaitForSingleObject(req->overlapped.hEvent, HUB_IOCTL_TIMEOUT_MS) == WAIT_OBJECT_0) {
		ret = GetOverlappedResult(handle, &req->overlapped, &bytes, FALSE);
		error = ret ? ERROR_SUCCESS : GetLastError();
		if (ret) {
			if (bytes > out_size)	// should not happen for METHOD_BUFFERED
				bytes = out_size;
			memcpy(out_buf, req_buf, bytes);
			*bytes_returned = bytes;
		}
		CloseHandle(req->overlapped.hEvent);
		free(req);
		SetLastError(error);
		return ret;
	}

	usbi_warn(ctx, "IOCTL 0x%08lX timed out after %d ms, cancelling it",
		ULONG_CAST(ioctl_code), HUB_IOCTL_TIMEOUT_MS);
	CancelIoEx(handle, &req->overlapped);
	if (WaitForSingleObject(req->overlapped.hEvent, HUB_IOCTL_CANCEL_GRACE_MS) == WAIT_OBJECT_0) {
		CloseHandle(req->overlapped.hEvent);
		free(req);
	} else {
		// The kernel still owns the request state: park it and free it once a
		// later call (or winusb_exit()) observes it reached a terminal state
		usbi_mutex_static_lock(&orphaned_requests_lock);
		list_add_tail(&req->list, &orphaned_requests);
		usbi_mutex_static_unlock(&orphaned_requests_lock);
	}
	SetLastError(ERROR_SEM_TIMEOUT);
	return FALSE;
}

static void windows_iocp_teardown(struct libusb_context *ctx)
{
	struct windows_context_priv *priv = (struct windows_context_priv *)usbi_get_context_priv(ctx);

	if (priv->completion_port_thread != NULL) {
		// Request the thread to exit. While the context is still
		// initializing the thread waits with a finite timeout and checks
		// this state, so it exits even if posting the exit completion
		// packet below fails.
		usbi_atomic_store(&priv->completion_port_state, WINDOWS_IOCP_EXIT_REQUESTED);

		// A NULL completion status will indicate to the thread that it is time to exit
		if (!PostQueuedCompletionStatus(priv->completion_port, 0, (ULONG_PTR)ctx, NULL))
			usbi_err(ctx, "failed to post I/O completion: %s", windows_error_str(0));

		if (WaitForSingleObject(priv->completion_port_thread, INFINITE) == WAIT_FAILED)
			usbi_err(ctx, "failed to wait for I/O completion port thread: %s", windows_error_str(0));

		CloseHandle(priv->completion_port_thread);
		priv->completion_port_thread = NULL;
	}

	// The I/O completion port must stay open until the thread has been
	// joined, so that the thread never waits on a closed or recycled handle
	if (priv->completion_port != NULL) {
		CloseHandle(priv->completion_port);
		priv->completion_port = NULL;
	}
}

static int get_config_descriptor_for_value(libusb_device *dev,
	uint8_t config_value, struct libusb_config_descriptor **config)
{
	if (config_value == 0)
		return libusb_get_active_config_descriptor(dev, config);
	return libusb_get_config_descriptor_by_value(dev, config_value, config);
}

int usbi_get_config_string_index(libusb_device *dev,
	uint8_t config_value, uint8_t *index_out)
{
	struct libusb_config_descriptor *config = NULL;
	int r;

	r = get_config_descriptor_for_value(dev, config_value, &config);
	if (r < 0)
		return r;

	*index_out = config->iConfiguration;
	libusb_free_config_descriptor(config);
	return LIBUSB_SUCCESS;
}

int usbi_get_interface_string_index(libusb_device *dev,
	uint8_t config_value, uint8_t interface_number, uint8_t alt_setting,
	uint8_t *index_out)
{
	struct libusb_config_descriptor *config = NULL;
	int r, i, j;

	r = get_config_descriptor_for_value(dev, config_value, &config);
	if (r < 0)
		return r;

	r = LIBUSB_ERROR_NOT_FOUND;
	for (i = 0; i < config->bNumInterfaces; i++) {
		const struct libusb_interface *intf = &config->interface[i];
		for (j = 0; j < intf->num_altsetting; j++) {
			const struct libusb_interface_descriptor *as = &intf->altsetting[j];
			if (as->bInterfaceNumber == interface_number &&
			    as->bAlternateSetting == alt_setting) {
				*index_out = as->iInterface;
				r = LIBUSB_SUCCESS;
				break;
			}
		}
		if (r == LIBUSB_SUCCESS)
			break;
	}

	libusb_free_config_descriptor(config);
	return r;
}

int API_EXPORTED libusb_get_config_string(libusb_device *dev,
	uint8_t config_value, char *data, int length)
{
	char buf[LIBUSB_DEVICE_STRING_BYTES_MAX];
	int r;

	if (NULL == dev)
		return LIBUSB_ERROR_INVALID_PARAM;
	if (length <= 0)
		return LIBUSB_ERROR_INVALID_PARAM;

	/* as in libusb_get_device_string(), data may be NULL to query the
	 * required buffer size */
	if (NULL != data)
		*data = 0;  /* return an empty string on errors when possible */

	if (NULL == usbi_backend.get_config_string)
		return LIBUSB_ERROR_NOT_SUPPORTED;

	/* Fetch into a full-size buffer, then copy out via usbi_utf8_copy() for
	 * UTF-8-safe truncation, as libusb_get_device_string() does. */
	r = usbi_backend.get_config_string(dev, config_value, buf, sizeof(buf));
	if (r < 0)
		return r;

	return usbi_utf8_copy(data, buf, length);
}

int API_EXPORTED libusb_get_interface_string(libusb_device *dev,
	uint8_t config_value, uint8_t interface_number, uint8_t alt_setting,
	char *data, int length)
{
	char buf[LIBUSB_DEVICE_STRING_BYTES_MAX];
	int r;

	if (NULL == dev)
		return LIBUSB_ERROR_INVALID_PARAM;
	if (length <= 0)
		return LIBUSB_ERROR_INVALID_PARAM;

	/* as in libusb_get_device_string(), data may be NULL to query the
	 * required buffer size */
	if (NULL != data)
		*data = 0;  /* return an empty string on errors when possible */

	if (NULL == usbi_backend.get_interface_string)
		return LIBUSB_ERROR_NOT_SUPPORTED;

	/* Fetch into a full-size buffer, then copy out via usbi_utf8_copy() for
	 * UTF-8-safe truncation, as libusb_get_device_string() does. */
	r = usbi_backend.get_interface_string(dev, config_value,
		interface_number, alt_setting, buf, sizeof(buf));
	if (r < 0)
		return r;

	return usbi_utf8_copy(data, buf, length);
}

static int darwin_fetch_string_descriptor (struct libusb_context *ctx,
    struct darwin_cached_device *dpriv, uint8_t string_index, char *buffer, int length) {
  usb_device_t device;
  IOUSBDevRequestTO req;
  IOReturn kresult;
  int is_open = 0;
  UInt16 langid;
  uint8_t desc[256];
  CFStringRef cf;
  long used = 0;
  int desc_len;

  /* Hold the device lock for the whole open/request/close sequence: it keeps
   * the open_count check below stable, so a concurrent libusb_open() or
   * libusb_close() cannot interleave with the temporary open.  Since
   * re-enumeration also runs with this lock held, the device interface read
   * below cannot be swapped or released underneath the requests. */
  usbi_mutex_lock(&dpriv->lock);

  device = dpriv->device;
  if (NULL == device) {
    usbi_mutex_unlock(&dpriv->lock);
    return LIBUSB_ERROR_NO_DEVICE;
  }

  /* According to Apple's documentation the device must be open to issue a
   * control request, but (as in darwin_cache_device_descriptor) we may not be
   * able to open every device, so the request is attempted regardless.  Never
   * open (or later close) the device here when the application already has it
   * open via libusb_open(): dpriv->device is shared, and USBDeviceClose()
   * would tear down that open state under the active handle. */
  if (0 == dpriv->open_count)
    is_open = ((*device)->USBDeviceOpen (device) == kIOReturnSuccess);

  /* Fetch the supported language IDs (string descriptor 0) and cache the
   * first (primary) one for this and subsequent requests. */
  langid = dpriv->langid;
  if (0 == langid) {
    memset (desc, 0, sizeof(desc));
    req.bmRequestType = USBmakebmRequestType (kUSBIn, kUSBStandard, kUSBDevice);
    req.bRequest      = kUSBRqGetDescriptor;
    req.wValue        = (UInt16)(LIBUSB_DT_STRING << 8);
    req.wIndex        = 0;
    req.wLength       = (UInt16)sizeof(desc);
    req.pData         = desc;
    req.noDataTimeout = 20;
    req.completionTimeout = 100;
    kresult = (*device)->DeviceRequestTO (device, &req);
    if (kIOReturnSuccess == kresult && req.wLenDone >= 4) {
      langid = (UInt16)desc[2] | ((UInt16)desc[3] << 8);
      dpriv->langid = langid;
    }
  }

  /* Fetch the requested string descriptor. */
  memset (desc, 0, sizeof(desc));
  req.bmRequestType = USBmakebmRequestType (kUSBIn, kUSBStandard, kUSBDevice);
  req.bRequest      = kUSBRqGetDescriptor;
  req.wValue        = (UInt16)((LIBUSB_DT_STRING << 8) | string_index);
  req.wIndex        = langid;
  req.wLength       = (UInt16)sizeof(desc);
  req.pData         = desc;
  req.noDataTimeout = 20;
  req.completionTimeout = 100;
  kresult = (*device)->DeviceRequestTO (device, &req);

  if (is_open)
    (void)(*device)->USBDeviceClose (device);

  usbi_mutex_unlock(&dpriv->lock);

  if (kIOReturnSuccess != kresult) {
    usbi_warn (ctx, "could not retrieve string descriptor %u: %s", string_index, darwin_error_str (kresult));
    return darwin_to_libusb (kresult);
  }

  if (req.wLenDone < 2 || desc[1] != LIBUSB_DT_STRING)
    return LIBUSB_ERROR_IO;

  desc_len = desc[0];  /* bLength */
  if (desc_len > (int)req.wLenDone)
    desc_len = (int)req.wLenDone;
  if (desc_len < 2)
    return LIBUSB_ERROR_IO;

  cf = CFStringCreateWithBytes (kCFAllocatorDefault, desc + 2, desc_len - 2,
    kCFStringEncodingUTF16LE, false);
  if (NULL == cf)
    return LIBUSB_ERROR_OTHER;

  CFStringGetBytes (cf, CFRangeMake(0, CFStringGetLength(cf)), kCFStringEncodingUTF8,
    '?', false, (uint8_t *) buffer, length - 1, &used);
  CFRelease (cf);

  buffer[used] = '\0';
  return (int) used + 1;
}

static int darwin_get_config_string (struct libusb_device *dev,
    uint8_t config_value, char *buffer, int length) {
  struct darwin_cached_device *dpriv = DARWIN_CACHED_DEVICE(dev);
  uint8_t string_index = 0;
  int r;

  assert (NULL != buffer && length > 0);  /* guaranteed by the core */

  r = usbi_get_config_string_index (dev, config_value, &string_index);
  if (r < 0)
    return r;
  if (0 == string_index)
    return LIBUSB_ERROR_NOT_FOUND;

  return darwin_fetch_string_descriptor (DEVICE_CTX(dev), dpriv, string_index, buffer, length);
}

static int darwin_get_interface_string (struct libusb_device *dev,
    uint8_t config_value, uint8_t interface_number, uint8_t alt_setting,
    char *buffer, int length) {
  struct darwin_cached_device *dpriv = DARWIN_CACHED_DEVICE(dev);
  uint8_t string_index = 0;
  int r;

  assert (NULL != buffer && length > 0);  /* guaranteed by the core */

  r = usbi_get_interface_string_index (dev, config_value, interface_number,
    alt_setting, &string_index);
  if (r < 0)
    return r;
  if (0 == string_index)
    return LIBUSB_ERROR_NOT_FOUND;

  return darwin_fetch_string_descriptor (DEVICE_CTX(dev), dpriv, string_index, buffer, length);
}

static int read_sysfs_attr_fd(struct libusb_context *ctx, int fd,
	const char *attr, char *buffer, int length)
{
	ssize_t r;
	int e;

	UNUSED(attr);  /* only referenced by usbi_err(), a no-op without logging */

	if (length <= 0) {
		close(fd);
		return LIBUSB_ERROR_INVALID_PARAM;
	}

	r = read(fd, buffer, length - 1);  // leave space for null terminator
	if (r < 0) {
		e = errno;
		close(fd);
		if (e == ENODEV)
			return LIBUSB_ERROR_NO_DEVICE;
		usbi_err(ctx, "attribute %s read failed, errno=%d", attr, e);
		return LIBUSB_ERROR_IO;
	}
	close(fd);
	buffer[r] = 0;  // add null terminator
	while (r && ((buffer[r] == 0) || (buffer[r] == '\n'))) {
		buffer[r--] = 0;
	}
	return (int)strlen(buffer) + 1;
}

static int windows_get_config_string(libusb_device *dev,
	uint8_t config_value, char *data, int length)
{
	struct windows_context_priv* priv = (struct windows_context_priv *)usbi_get_context_priv(DEVICE_CTX(dev));
	if (NULL != priv->backend->get_config_string) {
		return priv->backend->get_config_string(dev, config_value, data, length);
	}
	return LIBUSB_ERROR_NOT_SUPPORTED;
}

static int windows_get_interface_string(libusb_device *dev,
	uint8_t config_value, uint8_t interface_number, uint8_t alt_setting,
	char *data, int length)
{
	struct windows_context_priv* priv = (struct windows_context_priv *)usbi_get_context_priv(DEVICE_CTX(dev));
	if (NULL != priv->backend->get_interface_string) {
		return priv->backend->get_interface_string(dev, config_value,
			interface_number, alt_setting, data, length);
	}
	return LIBUSB_ERROR_NOT_SUPPORTED;
}

static int winusb_get_config_string(libusb_device *dev,
	uint8_t config_value, char *data, int length)
{
	uint8_t string_descriptor_idx = 0;
	int r;

	assert(NULL != data && length > 0);  /* guaranteed by the core */

	r = usbi_get_config_string_index(dev, config_value, &string_descriptor_idx);
	if (r < 0) {
		return r;
	}
	if (0 == string_descriptor_idx) {
		return LIBUSB_ERROR_NOT_FOUND;
	}

	return winusb_fetch_string_descriptor(dev, string_descriptor_idx, data, length);
}

static int winusb_get_interface_string(libusb_device *dev,
	uint8_t config_value, uint8_t interface_number, uint8_t alt_setting,
	char *data, int length)
{
	uint8_t string_descriptor_idx = 0;
	int r;

	assert(NULL != data && length > 0);  /* guaranteed by the core */

	r = usbi_get_interface_string_index(dev, config_value, interface_number,
		alt_setting, &string_descriptor_idx);
	if (r < 0) {
		return r;
	}
	if (0 == string_descriptor_idx) {
		return LIBUSB_ERROR_NOT_FOUND;
	}

	return winusb_fetch_string_descriptor(dev, string_descriptor_idx, data, length);
}

