static uint8_t t55xx_measure_broadcast_blocks_once(bool usepwd, uint32_t password, uint8_t downlink_mode) {

    // the acquisition misses often enough to be worth a couple of retries
    bool got = false;
    for (uint8_t t = 0; t < T55XX_PSK3_PROBE_TRIES && got == false; t++) {
        if (AcquireData(T55x7_PAGE0, REGULAR_READ_MODE_BLOCK, usepwd, password, downlink_mode) == false) {
            continue;
        }
        if (DecodeT55xxBlock() == false) {
            continue;
        }
        got = (g_DemodBufferLen >= 64);
    }

    if (got == false) {
        return 0;
    }

    for (uint8_t n = 1; n <= 7; n++) {

        const size_t stride = (size_t)n * 32;

        // two full periods, or it is not a demonstrated repeat
        if (g_DemodBufferLen < stride * 2) {
            break;
        }

        const size_t cmp = g_DemodBufferLen - stride;
        size_t bad = 0;
        for (size_t i = 0; i < cmp; i++) {
            if (g_DemodBuffer[i] != g_DemodBuffer[i + stride]) {
                bad++;
            }
        }

        // the stream carries the odd bit error, so this cannot want an exact
        // repeat - but the allowance has to be absolute, not proportional: a
        // real difference between blocks recurs every period, bit errors do not
        if (bad <= 2) {
            // a one block period rules nothing out, and also catches an
            // acquisition that never left block 0.  report it as unmeasured
            return (n > 1) ? n : 0;
        }
    }

    return 0;
}

static uint8_t t55xx_measure_broadcast_blocks(bool usepwd, uint32_t password, uint8_t downlink_mode) {

    uint8_t seen = 0;

    for (uint8_t t = 0; t < T55XX_PSK3_PERIOD_TRIES; t++) {

        const uint8_t n = t55xx_measure_broadcast_blocks_once(usepwd, password, downlink_mode);

        // an attempt that could not measure at all says nothing either way
        if (n == 0) {
            continue;
        }

        if (seen == 0) {
            seen = n;
            continue;
        }

        if (seen == n) {
            return n;
        }

        // measured twice and disagreed, nothing here says which is wrong
        return 0;
    }

    return 0;
}

void walkCommandsRecursive(const command_t cmds[], command_visitor_t visitor, void *ctx) {
    if (cmds == NULL || cmds[0].Name == NULL || visitor == NULL) return;

    // Leaf commands first, then categories: same order as dumpCommandsRecursive()
    for (int i = 0; cmds[i].Name; i++) {
        if (cmds[i].Name[0] == '-' || strlen(cmds[i].Name) == 0) continue;
        if (cmds[i].Help[0] == '{') continue;

        s_walk_path[s_walk_depth] = &cmds[i];
        visitor(s_walk_path, s_walk_depth + 1, ctx);
    }

    for (int i = 0; cmds[i].Name; i++) {
        if (cmds[i].Name[0] == '-' || strlen(cmds[i].Name) == 0) continue;
        if (cmds[i].Help[0] != '{') continue;

        if (s_walk_depth + 1 >= CMD_WALK_MAX_DEPTH) {
            PrintAndLogEx(DEBUG, "command tree too deep, skipping category %s", cmds[i].Name);
            continue;
        }

        command_visitor_t old_visitor = s_walk_visitor;
        void *old_ctx = s_walk_ctx;
        size_t dispatches = s_walk_dispatches;
        s_walk_visitor = visitor;
        s_walk_ctx = ctx;
        s_walk_path[s_walk_depth++] = &cmds[i];

        // This is what causes the recursion, since the category Parse-implementation
        // in turn calls CmdsParse() on its own table.
        cmds[i].Parse("XX_internal_command_walk_XX");

        s_walk_depth--;
        s_walk_visitor = old_visitor;
        s_walk_ctx = old_ctx;

        // A few commands (e.g. "reveng") are shown like a category but are
        // plain commands with their own parser. They never reach CmdsParse(),
        // so report them as leaves.
        if (s_walk_dispatches == dispatches) {
            s_walk_path[s_walk_depth] = &cmds[i];
            visitor(s_walk_path, s_walk_depth + 1, ctx);
        }
    }
}

static vocabulary_t *vocab_add(const char *name) {

    for (size_t i = 0; i < s_count; i++) {
        if (strcmp(s_vocab[i].name, name) == 0) {
            return NULL;
        }
    }

    if (s_count == s_capacity) {
        size_t new_capacity = s_capacity ? s_capacity * 2 : VOCAB_INITIAL_CAPACITY;
        vocabulary_t *tmp = realloc(s_vocab, new_capacity * sizeof(vocabulary_t));
        if (tmp == NULL) {
            PrintAndLogEx(WARNING, "Failed to allocate memory for completion vocabulary");
            return NULL;
        }
        s_vocab = tmp;
        s_capacity = new_capacity;
    }

    vocabulary_t *entry = &s_vocab[s_count];
    memset(entry, 0, sizeof(*entry));
    entry->name = str_dup(name);
    if (entry->name == NULL) {
        return NULL;
    }
    s_count++;
    return entry;
}

static void vocab_visit_command(const command_t *const path[], size_t depth, void *ctx) {
    (void) ctx;

    char name[MAX_PM3_INPUT_ARGS_LENGTH] = {0};
    size_t pos = 0;
    for (size_t i = 0; i < depth; i++) {
        int n = snprintf(name + pos, sizeof(name) - pos, "%s%s", i ? " " : "", path[i]->Name);
        if (n < 0 || (size_t)n >= sizeof(name) - pos) {
            return;
        }
        pos += (size_t)n;
    }

    vocabulary_t *entry = vocab_add(name);
    if (entry == NULL) {
        return;
    }

    entry->depth = (uint8_t)depth;
    for (size_t i = 0; i < depth; i++) {
        entry->is_available[i] = path[i]->IsAvailable;
    }
}

static void vocab_add_scripts_dir(const char *dir, const char *rel, const char *ext, const vocabulary_t *script_run) {

    struct dirent **namelist;
    int n = scandir(dir, &namelist, NULL, alphasort);
    if (n < 0) {
        return;
    }

    for (int i = 0; i < n; i++) {

        const char *fname = namelist[i]->d_name;

        if (strcmp(fname, ".") == 0 || strcmp(fname, "..") == 0) {
            free(namelist[i]);
            continue;
        }

        char fullpath[VOCAB_MAX_PATH] = {0};
        int len = snprintf(fullpath, sizeof(fullpath), "%s%s", dir, fname);
        if (len < 0 || (size_t)len >= sizeof(fullpath) - 1) {
            free(namelist[i]);
            continue;
        }

        if (path_is_directory(fullpath)) {
            fullpath[len] = PATHSEP[0];
            fullpath[len + 1] = '\0';

            char subrel[VOCAB_MAX_PATH] = {0};
            len = snprintf(subrel, sizeof(subrel), "%s%s%s", rel, fname, PATHSEP);
            if (len > 0 && (size_t)len < sizeof(subrel)) {
                vocab_add_scripts_dir(fullpath, subrel, ext, script_run);
            }
            free(namelist[i]);
            continue;
        }

        if (str_endswith(fname, ext)) {
            char name[MAX_PM3_INPUT_ARGS_LENGTH] = {0};
            len = snprintf(name, sizeof(name), "%s %s%s", script_run->name, rel, fname);
            if (len > 0 && (size_t)len < sizeof(name)) {
                vocabulary_t *entry = vocab_add(name);
                if (entry != NULL) {
                    entry->depth = script_run->depth;
                    memcpy(entry->is_available, script_run->is_available, sizeof(entry->is_available));
                }
            }
        }
        free(namelist[i]);
    }
    free(namelist);
}

static void vocab_add_scripts(const char *pm3dir, const char *ext, const vocabulary_t *script_run) {

    const char *exec_path = get_my_executable_directory();
    const char *user_path = get_my_user_directory();

    if (exec_path != NULL) {
        char path[VOCAB_MAX_PATH] = {0};
        int n = snprintf(path, sizeof(path), "%s%s", exec_path, pm3dir);
        if (n > 0 && (size_t)n < sizeof(path)) {
            vocab_add_scripts_dir(path, "", ext, script_run);
        }
    }

    if (user_path != NULL) {
        char path[VOCAB_MAX_PATH] = {0};
        int n = snprintf(path, sizeof(path), "%s%s%s", user_path, PM3_USER_DIRECTORY, pm3dir);
        if (n > 0 && (size_t)n < sizeof(path)) {
            vocab_add_scripts_dir(path, "", ext, script_run);
        }
    }

    if (exec_path != NULL) {
        char path[VOCAB_MAX_PATH] = {0};
        int n = snprintf(path, sizeof(path), "%s%s%s", exec_path, PM3_SHARE_RELPATH, pm3dir);
        if (n > 0 && (size_t)n < sizeof(path)) {
            vocab_add_scripts_dir(path, "", ext, script_run);
        }
    }
}

void pm3line_vocabulary_build(void) {

    pm3line_vocabulary_free();

    // The walk goes through the Parse() of every category. Keep it silent:
    // a few commands shown like categories (e.g. "reveng") run their own
    // parser on the walk token and would complain about it.
    uint8_t old_printAndLog = g_printAndLog;
    g_printAndLog = 0;
    walkCommandsRecursive(getTopLevelCommandTable(), vocab_visit_command, NULL);
    g_printAndLog = old_printAndLog;

    // Script files complete as "script run <file>", with the availability of "script run".
    // Take a copy: vocab_add() may realloc the array while scripts are being added.
    vocabulary_t script_run = {0};
    for (size_t i = 0; i < s_count; i++) {
        if (strcmp(s_vocab[i].name, "script run") == 0) {
            script_run = s_vocab[i];
            break;
        }
    }

    if (script_run.name != NULL) {
        vocab_add_scripts(LUA_SCRIPTS_SUBDIR, ".lua", &script_run);
        vocab_add_scripts(CMD_SCRIPTS_SUBDIR, ".cmd", &script_run);
#ifdef HAVE_PYTHON
        vocab_add_scripts(PYTHON_SCRIPTS_SUBDIR, ".py", &script_run);
#endif
    }

    s_built = true;
}

void pm3line_vocabulary_free(void) {
    for (size_t i = 0; i < s_count; i++) {
        free(s_vocab[i].name);
    }
    free(s_vocab);
    s_vocab = NULL;
    s_count = 0;
    s_capacity = 0;
    s_built = false;
}

const vocabulary_t *pm3line_vocabulary_get(size_t *count) {
    if (s_built == false) {
        pm3line_vocabulary_build();
    }
    if (count != NULL) {
        *count = s_count;
    }
    return s_vocab;
}

bool pm3line_vocabulary_is_available(const vocabulary_t *entry) {
    if (entry == NULL) {
        return false;
    }
    for (uint8_t i = 0; i < entry->depth; i++) {
        if (entry->is_available[i] != NULL && entry->is_available[i]() == false) {
            return false;
        }
    }
    return true;
}

void gc_collect(void)
{
    gc_collect_start();

    /* Spill the callee-saved registers onto the stack so that they are scanned
     * as part of the stack below, then scan from the current stack pointer up
     * to the top of the stack recorded at startup. */
    jmp_buf regs;
    setjmp(regs);

    void **sp = (void **)&regs;
    gc_collect_root(sp,
                    ((uintptr_t)MP_STATE_THREAD(stack_top) - (uintptr_t)sp) / sizeof(uintptr_t));

    gc_collect_end();
}

static void machine_adc_print(const mp_print_t *print,
                              mp_obj_t self_in, mp_print_kind_t kind)
{
    machine_adc_obj_t *self = self_in;
    mp_printf(print, "ADC(%u)", self->channel);
}

static mp_obj_t machine_adc_read_u16(mp_obj_t self_in)
{
    machine_adc_obj_t *self = self_in;

    /* Iterate over the possible resolutions until a valid resolution is
     * used */
    for (size_t i = 0; i < MP_ARRAY_SIZE(adc_res_helper); i++) {
        int val = adc_sample(self->channel, adc_res_helper[i].res_symbol);
        if (val >= 0) {
            int resolution = adc_res_helper[i].resolution;
            /* Taylor expansion to scale the result to the full 16 bit range */
            uint16_t scaled = val << (16 - resolution) |
                              val >> (2 * resolution - 16);
            return MP_OBJ_NEW_SMALL_INT(scaled);
        }
    }
    nlr_raise(mp_obj_new_exception_msg_varg(&mp_type_ValueError,
        "ADC(%u) sampling error", self->channel));
    return mp_const_none;
}

static mp_obj_t machine_adc_make_new(const mp_obj_type_t *type, size_t n_args,
                                     size_t n_kw, const mp_obj_t *all_args)
{
    enum { ARG_id };
    static const mp_arg_t allowed_args[] = {
        { MP_QSTR_id, MP_ARG_REQUIRED | MP_ARG_INT, {.u_int = -1} },
    };

    mp_arg_val_t args[MP_ARRAY_SIZE(allowed_args)];
    mp_arg_parse_all_kw_array(n_args, n_kw, all_args, MP_ARRAY_SIZE(allowed_args),
                              allowed_args, args);

    int line = args[ARG_id].u_int;

    if ((line < 0) || ((size_t)line >= ADC_NUMOF)) {
        nlr_raise(mp_obj_new_exception_msg_varg(&mp_type_ValueError,
            "ADC(%d) is an invalid line for port", line));
    }

    machine_adc_obj_t *self = &machine_adc_obj[(size_t)line];
    self->base.type = &machine_adc_type;
    self->channel = (adc_t)line;

    if (adc_init(line) < 0) {
        nlr_raise(mp_obj_new_exception_msg_varg(&mp_type_ValueError,
            "Unable to initialize ADC(%d)", line));
    }

    return MP_OBJ_FROM_PTR(self);
}

static spi_mode_t _to_riot_mode(bool polarity, bool phase)
{
    if (polarity) {
        if (phase) {
            return SPI_MODE_3;
        } else {
            return SPI_MODE_2;
        }
    } else {
        if (phase) {
            return SPI_MODE_1;
        } else {
            return SPI_MODE_0;
        }
    }
}

static void machine_hw_spi_print(const mp_print_t *print, mp_obj_t self_in,
                                 mp_print_kind_t kind)
{
    machine_hw_spi_obj_t *self = MP_OBJ_TO_PTR(self_in);
    mp_printf(print, "SPI(id=%u, baudrate=%u, polarity=%u, phase=%u, sck=?, mosi=?, miso=?)",
              self->bus, self->baudrate,
              _spi_polarity(self->mode), _spi_phase(self->mode));
}

static void machine_hw_spi_init(mp_obj_base_t *self_in, size_t n_args,
                                const mp_obj_t *pos_args, mp_map_t *kw_args)
{
    machine_hw_spi_obj_t *self = (machine_hw_spi_obj_t *) self_in;

    enum { ARG_baudrate, ARG_polarity, ARG_phase, ARG_bits, ARG_firstbit };
    static const mp_arg_t allowed_args[] = {
        { MP_QSTR_baudrate, MP_ARG_KW_ONLY | MP_ARG_INT, {.u_int = -1} },
        { MP_QSTR_polarity, MP_ARG_KW_ONLY | MP_ARG_INT, {.u_int = -1} },
        { MP_QSTR_phase,    MP_ARG_KW_ONLY | MP_ARG_INT, {.u_int = -1} },
        { MP_QSTR_bits,     MP_ARG_KW_ONLY | MP_ARG_INT, {.u_int = -1} },
        { MP_QSTR_firstbit, MP_ARG_KW_ONLY | MP_ARG_INT, {.u_int = -1} },
    };
    mp_arg_val_t args[MP_ARRAY_SIZE(allowed_args)];
    mp_arg_parse_all(n_args, pos_args, kw_args, MP_ARRAY_SIZE(allowed_args),
                     allowed_args, args);

    self->mode = _to_riot_mode(args[ARG_polarity].u_int, args[ARG_phase].u_int);
    self->baudrate = args[ARG_baudrate].u_int;
}

mp_obj_t machine_hw_spi_make_new(const mp_obj_type_t *type, size_t n_args,
                                 size_t n_kw, const mp_obj_t *all_args)
{
    enum { ARG_id, ARG_baudrate, ARG_polarity, ARG_phase, ARG_bits,
           ARG_firstbit, ARG_sck, ARG_mosi, ARG_miso };
    static const mp_arg_t allowed_args[] = {
        { MP_QSTR_id,       MP_ARG_REQUIRED | MP_ARG_INT, {.u_int = -1} },
        { MP_QSTR_baudrate, MP_ARG_KW_ONLY | MP_ARG_INT, {.u_int = -1} },
        { MP_QSTR_polarity, MP_ARG_KW_ONLY | MP_ARG_INT, {.u_int = -1} },
        { MP_QSTR_phase,    MP_ARG_KW_ONLY | MP_ARG_INT, {.u_int = -1} },
        { MP_QSTR_bits,     MP_ARG_KW_ONLY | MP_ARG_INT, {.u_int = -1} },
        { MP_QSTR_firstbit, MP_ARG_KW_ONLY | MP_ARG_INT, {.u_int = -1} },
        { MP_QSTR_sck,      MP_ARG_KW_ONLY | MP_ARG_OBJ, {.u_obj = MP_OBJ_NULL} },
        { MP_QSTR_mosi,     MP_ARG_KW_ONLY | MP_ARG_OBJ, {.u_obj = MP_OBJ_NULL} },
        { MP_QSTR_miso,     MP_ARG_KW_ONLY | MP_ARG_OBJ, {.u_obj = MP_OBJ_NULL} },
    };

    mp_arg_val_t args[MP_ARRAY_SIZE(allowed_args)];
    mp_arg_parse_all_kw_array(n_args, n_kw, all_args, MP_ARRAY_SIZE(allowed_args),
                              allowed_args, args);

    /* here we would check the sck/mosi/miso pins and configure them,
     * but it is not supported by RIOT  */
    if (args[ARG_sck].u_obj != MP_OBJ_NULL
        || args[ARG_mosi].u_obj != MP_OBJ_NULL
        || args[ARG_miso].u_obj != MP_OBJ_NULL) {
        mp_raise_ValueError("explicit choice of sck/mosi/miso is not allowed by port");
    }

    /* get static peripheral object */
    int spi_id = args[ARG_id].u_int;
    if (spi_id < 0 || spi_id >= (int)SPI_NUMOF) {
        nlr_raise(mp_obj_new_exception_msg_varg(&mp_type_ValueError,
            "SPI(%d) doesn't exist (max id=%u)", spi_id, SPI_NUMOF - 1));
    }
    machine_hw_spi_obj_t *self = &machine_hw_spi_obj[spi_id];
    self->base.type = &machine_hw_spi_type;

    self->bus = SPI_DEV(spi_id);
    self->mode = _to_riot_mode(args[ARG_polarity].u_int, args[ARG_phase].u_int);
    self->baudrate = args[ARG_baudrate].u_int;
    return MP_OBJ_FROM_PTR(self);
}

static void machine_hw_spi_transfer(mp_obj_base_t *self_in, size_t len,
                                    const uint8_t *src, uint8_t *dest)
{
    machine_hw_spi_obj_t *self = (machine_hw_spi_obj_t*)self_in;
    spi_acquire(self->bus, SPI_CS_UNDEF, self->mode, self->baudrate);
    spi_transfer_bytes(self->bus, SPI_CS_UNDEF, true, src, dest, len);
    spi_release(self->bus);
}

static void machine_pin_print(const mp_print_t *print, mp_obj_t self_in, mp_print_kind_t kind)
{
    machine_pin_obj_t *self = self_in;
    mp_printf(print, "<Pin %u>", (unsigned)self->pin);
}

static mp_obj_t machine_pin_obj_init_helper(machine_pin_obj_t *self, size_t n_args,
                                            const mp_obj_t *pos_args, mp_map_t *kw_args)
{
    enum { ARG_mode, ARG_value };
    static const mp_arg_t allowed_args[] = {
        { MP_QSTR_mode, MP_ARG_REQUIRED | MP_ARG_INT, { .u_int = GPIO_IN } },
        { MP_QSTR_value, MP_ARG_KW_ONLY | MP_ARG_OBJ, {.u_obj = mp_const_none}},
    };

    mp_arg_val_t args[MP_ARRAY_SIZE(allowed_args)];
    mp_arg_parse_all(n_args, pos_args, kw_args, MP_ARRAY_SIZE(allowed_args), allowed_args, args);

    /* get io mode */
    uint mode = args[ARG_mode].u_int;

    int ret = gpio_init(self->pin, mode);
    if (ret) {
        mp_raise_ValueError("invalid pin");
    }

    /* get initial value */
    if (args[ARG_value].u_obj != MP_OBJ_NULL) {
        (void)gpio_write(self->pin, mp_obj_is_true(args[ARG_value].u_obj));
    }

    return mp_const_none;
}

mp_obj_t mp_pin_make_new(const mp_obj_type_t *type, size_t n_args, size_t n_kw,
                         const mp_obj_t *args)
{
    mp_arg_check_num(n_args, n_kw, 1, MP_OBJ_FUN_ARGS_MAX, true);

    mp_obj_t *elem;
    mp_obj_get_array_fixed_n(args[0], 2, &elem);

    gpio_t wanted_pin = GPIO_PIN(mp_obj_get_int(elem[0]),
                                 mp_obj_get_int(elem[1]));

    machine_pin_obj_t *pin = m_new_obj(machine_pin_obj_t);
    pin->base = machine_pin_obj_template;
    pin->pin = wanted_pin;

    if (n_args > 1 || n_kw > 0) {
        /* pin mode given, so configure this GPIO */
        mp_map_t kw_args;
        mp_map_init_fixed_table(&kw_args, n_kw, args + n_args);
        machine_pin_obj_init_helper(pin, n_args - 1, args + 1, &kw_args);
    }

    return (mp_obj_t)pin;
}

static mp_obj_t machine_pin_call(mp_obj_t self_in, size_t n_args, size_t n_kw,
                                 const mp_obj_t *args)
{
    mp_arg_check_num(n_args, n_kw, 0, 1, false);
    machine_pin_obj_t *self = self_in;
    if (n_args == 0) {
        unsigned pin_val = gpio_read(self->pin);
        return MP_OBJ_NEW_SMALL_INT(pin_val);
    } else {
        gpio_write(self->pin, mp_obj_is_true(args[0]));
        return mp_const_none;
    }
}

static mp_obj_t machine_pin_off(mp_obj_t self_in)
{
    machine_pin_obj_t *self = self_in;
    (void)gpio_write(self->pin, 0);
    return mp_const_none;
}

static mp_obj_t machine_pin_on(mp_obj_t self_in)
{
    machine_pin_obj_t *self = self_in;
    (void)gpio_write(self->pin, 1);
    return mp_const_none;
}

static mp_uint_t machine_pin_ioctl(mp_obj_t self_in, mp_uint_t request, uintptr_t arg,
                                   int *errcode)
{
    (void)errcode;
    machine_pin_obj_t *self = self_in;

    switch (request) {
    case MP_PIN_READ:
        return gpio_read(self->pin);
    case MP_PIN_WRITE:
        gpio_write(self->pin, arg);
        return 0;
    }

    return -1;
}

