void mp_hal_stdout_tx_strn_cooked(const char *str, mp_uint_t len)
{
    while (len--) {
        if (*str == '\n') {
            mp_hal_stdout_tx_strn("\r", 1);
        }
        mp_hal_stdout_tx_strn(str++, 1);
    }
}

static int _cmd_get_slice(int argc, char **argv)
{
    if ((argc < 3) || (argc > 5)) {
        printf("Usage: %s <URI> <LEN_BYTE> [OFFSET_BYTE] [BLOCK_SIZE_BYTE]\n",
               argv[0]);
        return 1;
    }

    size_t len = atoi(argv[2]);
    if (len > sizeof(_client_buf)) {
        printf("LEN_BYTE must be <= %u\n", (unsigned)sizeof(_client_buf));
        return 1;
    }
    size_t offset = 0;
    size_t blocksize = 64;
    coap_blksize_t szx = COAP_BLOCKSIZE_64;
    if (argc >= 4) {
        offset = atoi(argv[3]);
    }

    if (argc >= 5) {
        blocksize = atoi(argv[4]);
        szx = coap_size2szx(blocksize);
        if (blocksize != coap_szx2size(szx)) {
            printf("Blocksize \"%s\" invalid. Use a power of two with "
                "16 <= blocksize <= 1024.\n",
                argv[4]);
            return 1;
        }
    }


    nanocoap_sock_t sock;
    int res = nanocoap_sock_url_connect(argv[1], &sock);
    if (res) {
        printf("nanocoap_sock_url_connect(\"%s\", &sock): %s\n",
               argv[1], tiny_strerror(res));
        return 1;
    }

    const char *path = sock_urlpath(argv[1]);

    res = nanocoap_sock_get_slice(&sock, path, szx, offset, _client_buf,
                                  len);
    nanocoap_sock_close(&sock);

    if (res < 0) {
        printf("nanocoap_sock_get_slice(&sock, \"%s\", %u, %u, buf, %u): %s\n",
               path, (unsigned)blocksize, (unsigned)offset, (unsigned)len,
               tiny_strerror(res));
        return 1;
    }

    assert((size_t)res <= len);
    if (res == 0) {
        puts("No data received (requested slice behind payload)");
        return 0;
    }

    od_hex_dump(_client_buf, res, 0);

    return 0;
}

int coap_block_slicer_init(coap_block_slicer_t *slicer, size_t blknum,
    if (__builtin_mul_overflow(blknum, blksize, &slicer->start) ||
        __builtin_add_overflow(slicer->start, blksize, &slicer->end)) {
        *slicer = (coap_block_slicer_t){0};
        return -EINVAL;
    }

sock < 0) {
        ESP_LOGE(TAG, "DNS socket error");
        vTaskDelete(NULL);
        return;
    }

    struct sockaddr_in addr = {
        .sin_family = AF_INET,
        .sin_port = htons(53),
        .sin_addr.s_addr = htonl(INADDR_ANY),
    };

    int opt = 1;
    setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    if (bind(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        ESP_LOGE(TAG, "DNS bind failed");
        close(sock);
        vTaskDelete(NULL);
        return;
    }

    ESP_LOGI(TAG, "DNS hijack listening on :53");

    uint8_t buf[512];
    struct sockaddr_in client;
    socklen_t client_len;

    while (1) {
        client_len = sizeof(client);
        int len = recvfrom(sock, buf, sizeof(buf), 0,
                           (struct sockaddr *)&client, &client_len);
        if (len < 12) continue;  /* too short for DNS header */

        /* Build response: copy query, set response flags, append answer */
        uint8_t resp[512];
        if (len + 16 > (int)sizeof(resp)) continue;

        memcpy(resp, buf, len);

        /* Set QR=1 (response), AA=1 (authoritative), RA=1 */
        resp[2] = 0x85;  /* QR=1, Opcode=0, AA=1, TC=0, RD=1 */
        resp[3] = 0x80;  /* RA=1, Z=0, RCODE=0 (no error) */

        /* Answer count = 1 */
        resp[6] = 0x00;
        resp[7] = 0x01;

        /* Append answer: pointer to name + A record with 192.168.4.1 */
        int off = len;
        resp[off++] = 0xC0;  /* pointer */
        resp[off++] = 0x0C;  /* offset to question name */
        resp[off++] = 0x00; resp[off++] = 0x01;  /* type A */
        resp[off++] = 0x00; resp[off++] = 0x01;  /* class IN */
        resp[off++] = 0x00; resp[off++] = 0x00;
        resp[off++] = 0x00; resp[off++] = 0x3C;  /* TTL = 60 */
        resp[off++] = 0x00; resp[off++] = 0x04;  /* data length = 4 */
        resp[off++] = 192; resp[off++] = 168;
        resp[off++] = 4;   resp[off++] = 1;

        sendto(sock, resp, off, 0,
               (struct sockaddr *)&client, client_len);
    }
}

