    raw[raw_len] = '\0';
    proxy_conn_close(conn);

    /* Parse status line */
    *out_status = 0;
    if (strncmp(raw, "HTTP/", 5) == 0) {
        const char *sp = strchr(raw, ' ');
        if (sp) *out_status = atoi(sp + 1);
    }

    /* Find body after \r\n\r\n */
    char *body = strstr(raw, "\r\n\r\n");
    if (body) {
        body += 4;
