            size_t copy_len = body_len < ctx->resp_cap - 1 ? body_len : ctx->resp_cap - 1;
            memcpy(ctx->response, body, copy_len);
            ctx->response[copy_len] = '\0';
            ctx->resp_len = copy_len;
            ESP_LOGE(TAG, "API error body: %.500s", body);
        }
    }

    free(raw);
    return ESP_OK;
}

