esp_err_t http_proxy_clear(void)
{
    nvs_handle_t nvs;
    ESP_ERROR_C

CK(nvs_open(MIMI_NVS_PROXY, NVS_READWRITE, &nvs));
    nvs_erase_key(nvs, MIMI_NVS_KEY_PROXY_HOST);
    nvs_erase_key(nvs, MIMI_NVS_KEY_PROXY_PORT);
    nvs_commit(nvs);
    nvs_close(nvs);

    s_proxy_host[0] = '\0';
    s_proxy_port = 0;
    ESP_LOGI(TAG, "Proxy cleared");
    return ESP_OK;
}

