static const char** prepare_spawn_argv(const char* const* argv)
{
    if (!argv || !argv[0]) return NULL;
    int x86 = my_context->box86path ? FileIsX86ELF(argv[0]) : 0;
    if (!x86 && !FileIsX64ELF(argv[0])) return NULL;
    int n = 0;
    while (argv[n]) ++n;
    const char** newargv = (const char**)box_malloc((n + 2) * sizeof(char*));
    newargv[0] = x86 ? my_context->box86path : my_context->box64path;
    memcpy(newargv + 1, argv, (n + 1) * sizeof(char*));
    printf_log(LOG_DEBUG, "gio spawn of \"%s\" redirected through \"%s\"\n", argv[0], newargv[0]);
    return newargv;
}

EXPORT void* my_g_subprocess_launcher_spawnv(x64emu_t* emu, void* launcher, const char* const* argv, void* error)
{
    const char** newargv = prepare_spawn_argv(argv);
    void* ret = my->g_subprocess_launcher_spawnv(launcher, (void*)(newargv ? newargv : argv), error);
    box_free(newargv);
    return ret;
}

EXPORT void* my_g_subprocess_newv(x64emu_t* emu, const char* const* argv, uint32_t flags, void* error)
{
    const char** newargv = prepare_spawn_argv(argv);
    void* ret = my->g_subprocess_newv((void*)(newargv ? newargv : argv), flags, error);
    box_free(newargv);
    return ret;
}

static const char** prepare_spawn_argv(const char* const* argv)
{
    if (!argv || !argv[0]) return NULL;
    int x86 = my_context->box86path ? FileIsX86ELF(argv[0]) : 0;
    if (!x86 && !FileIsX64ELF(argv[0])) return NULL;
    int n = 0;
    while (argv[n]) ++n;
    const char** newargv = (const char**)box_malloc((n + 2) * sizeof(char*));
    newargv[0] = x86 ? my_context->box86path : my_context->box64path;
    memcpy(newargv + 1, argv, (n + 1) * sizeof(char*));
    printf_log(LOG_DEBUG, "g_spawn of \"%s\" redirected through \"%s\"\n", argv[0], newargv[0]);
    return newargv;
}

static void* findext_hookFct(void* fct)
{
    if(!fct) return fct;
    if(GetNativeFnc((uintptr_t)fct))  return GetNativeFnc((uintptr_t)fct);
    #define GO(A) if(my_ext_hook_fct_##A == (uintptr_t)fct) return my_ext_hook_##A;
    SUPER_EXT()
    #undef GO
    #define GO(A) if(my_ext_hook_fct_##A == 0) {my_ext_hook_fct_##A = (uintptr_t)fct; return my_ext_hook_##A; }
    SUPER_EXT()
    #undef GO
    printf_log(LOG_NONE, "Warning, no more slot for libX11 ext_hook callback\n");
    return NULL;
}

static void* reverse_ext_hookFct(library_t* lib, void* fct)
{
    if(!fct) return fct;
    if(CheckBridged(lib->w.bridge, iFppp, fct))
        return (void*)CheckBridged(lib->w.bridge, iFppp, fct);
    #define GO(A) if(my_ext_hook_##A == fct) return (void*)my_ext_hook_fct_##A;
    SUPER_EXT()
    #undef GO
    return (void*)AddBridge(lib->w.bridge, iFppp, fct, 0, NULL);
}

static void* findext_error_stringFct(void* fct)
{
    if(!fct) return fct;
    if(GetNativeFnc((uintptr_t)fct))  return GetNativeFnc((uintptr_t)fct);
    #define GO(A) if(my_ext_error_string_fct_##A == (uintptr_t)fct) return my_ext_error_string_##A;
    SUPER()
    #undef GO
    #define GO(A) if(my_ext_error_string_fct_##A == 0) {my_ext_error_string_fct_##A = (uintptr_t)fct; return my_ext_error_string_##A; }
    SUPER()
    #undef GO
    printf_log(LOG_NONE, "Warning, no more slot for libX11 ext_error_string callback\n");
    return NULL;
}

static void* reverse_ext_error_stringFct(library_t* lib, void* fct)
{
    if(!fct) return fct;
    if(CheckBridged(lib->w.bridge, pFpippi, fct))
        return (void*)CheckBridged(lib->w.bridge, pFpippi, fct);
    #define GO(A) if(my_ext_error_string_##A == fct) return (void*)my_ext_error_string_fct_##A;
    SUPER()
    #undef GO
    return (void*)AddBridge(lib->w.bridge, pFpippi, fct, 0, NULL);
}

