ectView::on_timer() {
    ++frame_counter_;

    if (detect_state_ != DetectState::Scanning) {
        return;
    }

    if (scan_dwell_frames_ > 0) {
        --scan_dwell_frames_;
        return;
    }

    step_scan();
}

