void Si5351PLLBDebugView::refresh() {
    uint8_t r34 = portapack::clock_manager.si5351_read_register(34);  // P3[15:8]
    uint8_t r35 = portapack::clock_manager.si5351_read_register(35);  // P3[7:0]
    uint8_t r36 = portapack::clock_manager.si5351_read_register(36);  // P1[17:16]
    uint8_t r37 = portapack::clock_manager.si5351_read_register(37);  // P1[15:8]
    uint8_t r38 = portapack::clock_manager.si5351_read_register(38);  // P1[7:0]
    uint8_t r39 = portapack::clock_manager.si5351_read_register(39);  // P3[19:16] | P2[19:16]
    uint8_t r40 = portapack::clock_manager.si5351_read_register(40);  // P2[15:8]
    uint8_t r41 = portapack::clock_manager.si5351_read_register(41);  // P2[7:0]

    text_r34_35.set("R34-35: " + to_string_hex(r34, 2) + " " + to_string_hex(r35, 2));
    text_r36_38.set("R36-38: " + to_string_hex(r36, 2) + " " + to_string_hex(r37, 2) + " " + to_string_hex(r38, 2));
    text_r39_41.set("R39-41: " + to_string_hex(r39, 2) + " " + to_string_hex(r40, 2) + " " + to_string_hex(r41, 2));

    uint32_t p1 = ((uint32_t)(r36 & 0x03) << 16) | ((uint32_t)r37 << 8) | r38;
    uint32_t p2 = ((uint32_t)(r39 & 0x0F) << 16) | ((uint32_t)r40 << 8) | r41;
    uint32_t p3 = ((uint32_t)(r39 >> 4) << 16) | ((uint32_t)r34 << 8) | r35;

    text_p1.set(to_string_dec_uint(p1) + " (0x" + to_string_hex(p1, 5) + ")");
    text_p2.set(to_string_dec_uint(p2) + " (0x" + to_string_hex(p2, 5) + ")");
    text_p3.set(to_string_dec_uint(p3) + " (0x" + to_string_hex(p3, 5) + ")");

    if (p3 > 0) {
        uint64_t vco_num = (uint64_t)p2 + (uint64_t)p3 * (p1 + 512);
        uint64_t vco_den = 128ULL * p3;
        uint32_t vco_khz = (uint32_t)((25000ULL * vco_num) / vco_den);
        text_vco.set(to_string_dec_uint(vco_khz / 1000) + "." + to_string_dec_uint(vco_khz % 1000, 3) + " MHz");

        bool ok = (vco_khz >= 600000 && vco_khz <= 900000);
        text_vco.set_style(ok ? Theme::getInstance()->fg_green : Theme::getInstance()->fg_red);
        text_status.set(ok ? "PLL B VCO OK" : "VCO OUT OF RANGE!");
    }
}

void write_pll_single_byte(const uint8_t pll_n, const PLL& pll_config) {
        const auto regs = pll_config.reg(pll_n);
        // regs[0] is base register address, regs[1-8] are data
        const uint8_t base_reg = regs[0];
        for (size_t i = 1; i < regs.size(); i++) {
            write_register(base_reg + i - 1, regs[i]);
        }
    }

static void RegisterSkipWarpHooks() {
    COND_ID_HOOK(ShouldActorInit, ACTOR_DEMO_KANKYO, CVAR_SKIP_WARP_VALUE, [](void* refActor, bool* should) {
        Actor* actor = static_cast<Actor*>(refActor);
        if (actor->params != DEMOKANKYO_WARP_OUT_PARAM) {
            return;
        }
        // Leaves right away, and settles the destination: entrance rando redirects from inside it.
        Environment_WarpSongLeave(gPlayState);
        // Switch arrival spawn mode from WARP_SONG to IDLE so DEMO_KANKYO WARP_IN is never spawned.
        // Another mode means something else owns the arrival (a rando grotto return), with no cutscene.
        RespawnData* respawn = &gSaveContext.respawn[RESPAWN_MODE_RETURN];
        if (((respawn->playerParams & 0xF00) >> 8) == PLAYER_START_MODE_WARP_SONG) {
            respawn->playerParams = (respawn->playerParams & ~0xF00) | (PLAYER_START_MODE_IDLE << 8);
        }
        *should = false;
    });
}

static s16 Item_GetSlot(u8 item) {
    if ((item >= ITEM_STICKS_5) && (item < ITEM_STICKS_5 + ARRAY_COUNT(sExtraItemBases))) {
        return SLOT(sExtraItemBases[item - ITEM_STICKS_5]);
    }
    if (item < ARRAY_COUNT(gItemSlots)) {
        return SLOT(item);
    }
    return SLOT_NONE;
}

static void SyncButtonItemsForSlot(uint8_t slot) {
    for (size_t i = 1; i < ARRAY_COUNT(gSaveContext.equips.buttonItems); i++) {
        if (gSaveContext.equips.cButtonSlots[i - 1] == slot) {
            gSaveContext.equips.buttonItems[i] = gSaveContext.inventory.items[slot];
            if (gPlayState != nullptr) {
                Interface_LoadItemIcon1(gPlayState, static_cast<u16>(i));
            }
        }
    }
}

TextureType TypeFromString(const std::string& format) {
    if (format == "rgba32") return TextureType::RGBA32bpp;
    if (format == "rgb5a1") return TextureType::RGBA16bpp;
    if (format == "ci4")    return TextureType::Palette4bpp;
    if (format == "ci8")    return TextureType::Palette8bpp;
    if (format == "i4")     return TextureType::Grayscale4bpp;
    if (format == "i8")     return TextureType::Grayscale8bpp;
    if (format == "ia4")    return TextureType::GrayscaleAlpha4bpp;
    if (format == "ia8")    return TextureType::GrayscaleAlpha8bpp;
    if (format == "ia16")   return TextureType::GrayscaleAlpha16bpp;
    return TextureType::Error;
}

std::vector<uint8_t> Encode(const uint8_t* rgba, int w, int h, TextureType type) {
    auto px = [&](int y, int x, int c) -> uint8_t { return rgba[(((size_t)y * w) + x) * 4 + c]; };
    std::vector<uint8_t> out(TextureUtils::CalculateTextureSize(type, w, h));

    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            const size_t i = (size_t)y * w + x;

            switch (type) {
                case TextureType::RGBA32bpp:
                    out[i * 4 + 0] = px(y, x, 0);
                    out[i * 4 + 1] = px(y, x, 1);
                    out[i * 4 + 2] = px(y, x, 2);
                    out[i * 4 + 3] = px(y, x, 3);
                    break;

                case TextureType::RGBA16bpp: {
                    const uint16_t data = ((px(y, x, 0) >> 3) << 11) | ((px(y, x, 1) >> 3) << 6) |
                                          ((px(y, x, 2) >> 3) << 1) | (px(y, x, 3) != 0);
                    out[i * 2 + 0] = (data & 0xFF00) >> 8;
                    out[i * 2 + 1] = (data & 0x00FF);
                    break;
                }

                case TextureType::Grayscale4bpp:
                    if (x % 2 == 0) {
                        out[i / 2] = (uint8_t)(((px(y, x, 0) / 16) << 4) + (px(y, x + 1, 0) / 16));
                    }
                    break;

                case TextureType::Grayscale8bpp:
                    out[i] = px(y, x, 0);
                    break;

                case TextureType::GrayscaleAlpha4bpp:
                    if (x % 2 == 0) {
                        const uint8_t hi = ((px(y, x, 0) >> 5) << 1) | (px(y, x, 3) != 0);
                        const uint8_t lo = ((px(y, x + 1, 0) >> 5) << 1) | (px(y, x + 1, 3) != 0);
                        out[i / 2] = (uint8_t)((hi << 4) | lo);
                    }
                    break;

                case TextureType::GrayscaleAlpha8bpp:
                    out[i] = (uint8_t)((((px(y, x, 0) >> 4) & 0xF) << 4) | ((px(y, x, 3) >> 4) & 0xF));
                    break;

                case TextureType::GrayscaleAlpha16bpp:
                    out[i * 2 + 0] = px(y, x, 0);
                    out[i * 2 + 1] = px(y, x, 3);
                    break;

                // Palettes need a TLUT this packer has no way to build.
                default:
                    return {};
            }
        }
    }

    return out;
}

bool Convert(const fs::path& png, const fs::path& dest, const std::string& format) {
    const TextureType type = TypeFromString(format);

    int w = 0, h = 0, channels = 0;
    uint8_t* pixels = stbi_load(png.string().c_str(), &w, &h, &channels, 4);
    if (pixels == nullptr) {
        fprintf(stderr, "%s: %s\n", png.string().c_str(), stbi_failure_reason());
        return false;
    }

    const std::vector<uint8_t> encoded = Encode(pixels, w, h, type);
    stbi_image_free(pixels);

    if (encoded.empty()) {
        fprintf(stderr, "%s: cannot encode %s\n", png.string().c_str(), format.c_str());
        return false;
    }

    LUS::BinaryWriter writer;
    BaseExporter::WriteHeader(writer, Torch::ResourceType::Texture, 0);
    writer.Write((uint32_t)type);
    writer.Write((uint32_t)w);
    writer.Write((uint32_t)h);
    writer.Write((uint32_t)encoded.size());
    writer.Write((char*)encoded.data(), encoded.size());

    const std::vector<char> payload = writer.ToVector();
    writer.Close();

    fs::create_directories(dest.parent_path());
    std::ofstream out(dest, std::ios::binary);
    out.write(payload.data(), payload.size());

    return out.good();
}

int main(int argc, char** argv) {
    if (argc != 4) {
        fprintf(stderr, "usage: %s <custom assets dir> <out.o2r> <M.m.p>\n", argv[0]);
        return 1;
    }

    const fs::path assetsDir = argv[1];
    const fs::path outPath = argv[2];
    const std::string version = argv[3];

    if (!fs::is_directory(assetsDir)) {
        fprintf(stderr, "not a directory: %s\n", assetsDir.string().c_str());
        return 1;
    }

    // Companion::Pack archives a directory as-is, so stage the assets in the shape the archive
    // should have and let torch do the rest.
    const fs::path stage = outPath.string() + ".stage";
    std::error_code ec;
    fs::remove_all(stage, ec);
    fs::create_directories(stage);

    for (const auto& entry : fs::recursive_directory_iterator(assetsDir)) {
        if (!entry.is_regular_file()) {
            continue;
        }

        const fs::path& path = entry.path();
        const std::string rel = fs::relative(path, assetsDir).generic_string();
        const std::string filename = path.filename().string();

        // <name>.<format>.png becomes a texture resource archived as <name>
        if (std::count(filename.begin(), filename.end(), '.') >= 2 && path.extension() == ".png") {
            const std::string stem = path.stem().string();
            const std::string format = stem.substr(stem.find_last_of('.') + 1);

            if (PngTexture::IsFormat(format)) {
                const std::string arc = rel.substr(0, rel.size() - (format.size() + 5));
                if (!PngTexture::Convert(path, stage / arc, format)) {
                    return 1;
                }
                continue;
            }
        }

        // Only json is carried over from accessibility
        if (rel.find("accessibility") != std::string::npos && path.extension() != ".json") {
            continue;
        }

        fs::create_directories((stage / rel).parent_path());
        fs::copy_file(path, stage / rel, fs::copy_options::overwrite_existing);
    }

    fs::create_directories(outPath.parent_path(), ec);
    fs::remove(outPath, ec);
    Companion::Pack(stage.string(), outPath.string(), ArchiveType::O2R, version);
    fs::remove_all(stage, ec);

    return 0;
}

static std::vector<std::string> CollectRoms(const std::vector<std::string>& args) {
    std::vector<std::string> roms;

    for (const auto& arg : args) {
        std::error_code ec;
        if (fs::is_directory(arg, ec)) {
            std::vector<std::string> found;
            for (fs::directory_iterator it(arg, ec), end; it != end; it.increment(ec)) {
                if (ec) {
                    break;
                }
                if (it->is_regular_file(ec) && IsRom(it->path())) {
                    found.push_back(it->path().string());
                }
            }
            std::sort(found.begin(), found.end());
            roms.insert(roms.end(), found.begin(), found.end());
        } else {
            roms.push_back(arg);
        }
    }

    return roms;
}

int main(int argc, char** argv) {
    std::string src, dest, version;
    std::vector<std::string> romArgs;

    for (int i = 1; i < argc; i++) {
        const std::string arg = argv[i];
        auto next = [&](const char* what) -> std::string {
            if (i + 1 >= argc) {
                fprintf(stderr, "missing argument after %s\n", what);
                exit(1);
            }
            return argv[++i];
        };

        if (arg == "--src") {
            src = next("--src");
        } else if (arg == "--dest") {
            dest = next("--dest");
        } else if (arg == "--version") {
            version = next("--version");
        } else if (!arg.empty() && arg[0] == '-') {
            fprintf(stderr, "unknown option: %s\n", arg.c_str());
            Usage(argv[0]);
            return 1;
        } else {
            romArgs.push_back(arg);
        }
    }

    if (src.empty() || dest.empty() || version.empty() || romArgs.empty()) {
        Usage(argv[0]);
        return 1;
    }

    const std::vector<std::string> roms = CollectRoms(romArgs);
    if (roms.empty()) {
        fprintf(stderr, "no roms found in: ");
        for (const auto& arg : romArgs) {
            fprintf(stderr, "%s ", arg.c_str());
        }
        fprintf(stderr, "\n");
        return 1;
    }

    for (const auto& rom : roms) {
        // A fresh extraction per ROM; torch names the archive from config.yml.
        const std::string archive = SohTorch::Extract(rom, src, dest, version, nullptr);
        if (archive.empty()) {
            fprintf(stderr, "failed to extract %s\n", rom.c_str());
            return 1;
        }
        printf("%s -> %s/%s\n", rom.c_str(), dest.c_str(), archive.c_str());
    }

    return 0;
}

bool IsHintRead(RandomizerHint hintKey) {
    std::lock_guard<std::mutex> lock(readHintsMutex);
    return readHints.contains(hintKey);
}

stat

void MarkHintAsRead(RandomizerHint hintKey) {
    if (hintKey == RH_NONE || !OTRGlobals::Instance->gRandoContext->GetHint(hintKey)->IsEnabled()) {
        return;
    }
    {
        std::lock_guard<std::mutex> lock(readHintsMutex);
        if (!readHints.insert(hintKey).second) {
            return;
        }
    }
    if (sectionId >= 0) {
        SaveManager::Instance->SaveSection(gSaveContext.fileNum, sectionId, true);
    }
}

void

nitHintTrackerData(bool isDebug) {
    std::lock_guard<std::mutex> lock(readHintsMutex);
    readHints.clear();
    hintTextCache.clear();
}

void

aveHintTrackerData(SaveContext* saveContext, int sectionID, bool fullSave) {
    std::vector<RandomizerHint> hints;
    {
        std::lock_guard<std::mutex> lock(readHintsMutex);
        hints.assign(readHints.begin(), readHints.end());
    }
    // Hints are stored by canonical name rather than enum value so saved
    // flags survive hints being added to or removed from the enum. find()
    // rather than operator[] so a missing name can't mutate the shared table
    // from the save thread.
    SaveManager::Instance->SaveArray("readHints", hints.size(), [&](size_t i) {
        auto name = Rando::StaticData::hintNames.find(hints[i]);
        if (name != Rando::StaticData::hintNames.end()) {
            SaveManager::Instance->SaveData("", name->second.GetEnglish(MF_CLEAN));
        }
    });
}

void

oadHintTrackerData() {
    std::set<RandomizerHint> loaded;
    SaveManager::Instance->LoadArray("readHints", RH_MAX, [&](size_t i) {
        // Read type-agnostically and skip anything that isn't a known hint
        // name, so malformed or outdated entries can't abort the save load.
        nlohmann::json value;
        SaveManager::Instance->LoadData("", value, nlohmann::json());
        if (!value.is_string()) {
            return;
        }
        auto it = Rando::StaticData::hintNameToEnum.find(value.get<std::string>());
        if (it != Rando::StaticData::hintNameToEnum.end()) {
            loaded.insert(static_cast<RandomizerHint>(it->second));
        }
    });
    std::lock_guard<std::mutex> lock(readHintsMutex);
    readHints = std::move(loaded);
}

// D

std::string GetPlayerName() {
    std::string name;
    for (int i = 0; i < 8; i++) {
        if (gSaveContext.ship.filenameLanguage == NAME_LANGUAGE_PAL) {
            name += z2ASCII(gSaveContext.playerName[i]);
        } else {
            name += decodeNTSCPlayerNameChar(gSaveContext.playerName[i]);
        }
    }
    while (!name.empty() && name.back() == ' ') {
        name.pop_back();
    }
    return name;
}

// V

std::string NormalizeForCompare(const std::string& text) {
    std::string key;
    for (unsigned char c : text) {
        if (std::isalnum(c)) {
            key += static_cast<char>(std::tolower(c));
        }
    }
    return key;
}

// A

const std::string& GetJoinedHintText(RandomizerHint hintKey) {
    auto cached = hintTextCache.find(hintKey);
    if (cached != hintTextCache.end()) {
        return cached->second;
    }
    Rando::Hint* hint = OTRGlobals::Instance->gRandoContext->GetHint(hintKey);
    const std::string playerName = GetPlayerName();
    std::vector<std::string> parts;
    std::vector<std::string> keys;
    size_t numMessages = hint->GetNumberOfMessages();
    for (size_t i = 0; i < numMessages; i++) {
        CustomMessage msg = hint->GetHintMessage(MF_CLEAN, i);
        msg.Replace("Buy ", "");
        msg.Replace("Acheter: ", "");
        msg.Replace(" kaufen ", "");
        msg.Replace(" kaufen", "");
        msg.Replace("@", playerName);
        std::string part = msg.GetForCurrentLanguage(MF_CLEAN);
        // Variants of a hint often share the same wording give or take
        // punctuation (e.g. Saria's in-person and ocarina messages); show
        // each distinct wording once.
        std::string key = NormalizeForCompare(part);
        if (std::find(keys.begin(), keys.end(), key) == keys.end()) {
            keys.push_back(key);
            parts.push_back(part);
        }
    }
    std::string text;
    for (const std::string& part : parts) {
        if (!text.empty()) {
            text += "\n";
        }
        text += part;
    }
    return hintTextCache[hintKey] = text;
}

