static R

void RegisterFreeLookDoorCamRelease() {
    COND_VB_SHOULD(VB_RELEASE_DOORC_CAMERA, CVarGetInteger(CVAR_SETTING("FreeLook.Enabled"), 0), {
        Camera* camera = va_arg(args, Camera*);

        // Also release the door peek camera when free look moves it, reusing SetCameraManual's threshold.
        f32 freeLookX = -camera->play->state.input[0].cur.right_stick_x * 10.0f;
        f32 freeLookY = camera->play->state.input[0].cur.right_stick_y * 10.0f;
        Mouse_HandleThirdPerson(&freeLookX, &freeLookY);

        if (fabsf(freeLookX) >= 15.0f || fabsf(freeLookY) >= 15.0f) {
            *should = true;
        }
    });
}

static u8 Audio_GetSeqFlags(u16 seqId) {
    if (seqId >= ARRAY_COUNT(sSeqFlags)) {
        return 0;
    }
    return sSeqFlags[seqId];
}

static bool feed_msp_bytes(MSP &protocol, const std::string &buf)
{
    bool packetComplete = false;
    for (const char c : buf)
    {
        packetComplete = protocol.processReceivedByte(c);
    }
    return packetComplete;
}

static bool write_msp_packet(mspPacket_t &packet, std::string &buf)
{
    StringStream ss(buf);
    return MSP::sendPacket(&packet, &ss);
}

void test_msp_receive_rejects_oversized_payload(void)
{
    const uint8_t header[] = {'$', 'X', '<', 0, 1, 0, MSP_PORT_INBUF_SIZE + 1, 0};
    bool packetComplete = false;
    for (const uint8_t c : header)
    {
        packetComplete = MSPOversizeProtocol.processReceivedByte(c);
        TEST_ASSERT_FALSE(packetComplete);
    }

    for (uint8_t i = 0; i < MSP_PORT_INBUF_SIZE + 2; ++i)
    {
        packetComplete = MSPOversizeProtocol.processReceivedByte('A');
        TEST_ASSERT_FALSE(packetComplete);
    }

    mspPacket_t validPacket;
    validPacket.reset();
    validPacket.makeCommand();
    validPacket.flags = 0;
    validPacket.function = 1;
    validPacket.addByte('B');

    std::string buf;
    StringStream ss(buf);
    TEST_ASSERT_TRUE(MSP::sendPacket(&validPacket, &ss));
    TEST_ASSERT_TRUE(feed_msp_bytes(MSPOversizeProtocol, buf));
}

void test_msp_receive_accepts_max_payload(void)
{
    mspPacket_t packet;
    packet.reset();
    packet.makeCommand();
    packet.flags = 0;
    packet.function = 1;
    for (uint8_t i = 0; i < MSP_PORT_INBUF_SIZE; ++i)
    {
        packet.addByte(i);
    }

    std::string buf;
    StringStream ss(buf);
    TEST_ASSERT_TRUE(MSP::sendPacket(&packet, &ss));
    TEST_ASSERT_TRUE(feed_msp_bytes(MSPMaxPayloadProtocol, buf));

    mspPacket_t *received = MSPMaxPayloadProtocol.getReceivedPacket();
    TEST_ASSERT_EQUAL(MSP_PORT_INBUF_SIZE, received->payloadSize);
    TEST_ASSERT_EQUAL(0, received->payload[0]);
    TEST_ASSERT_EQUAL(MSP_PORT_INBUF_SIZE - 1, received->payload[MSP_PORT_INBUF_SIZE - 1]);
}

void test_msp_receive_recovers_from_invalid_header_start(void)
{
    TEST_ASSERT_FALSE(MSPInvalidHeaderProtocol.processReceivedByte('$'));
    TEST_ASSERT_FALSE(MSPInvalidHeaderProtocol.processReceivedByte('M'));

    mspPacket_t packet;
    packet.reset();
    packet.makeCommand();
    packet.flags = 0;
    packet.function = 1;
    packet.addByte('C');

    std::string buf;
    TEST_ASSERT_TRUE(write_msp_packet(packet, buf));
    TEST_ASSERT_TRUE(feed_msp_bytes(MSPInvalidHeaderProtocol, buf));
}

void test_msp_receive_accepts_response_packets(void)
{
    mspPacket_t packet;
    packet.reset();
    packet.makeResponse();
    packet.flags = 0;
    packet.function = 1;
    packet.addByte(7);

    std::string buf;
    TEST_ASSERT_TRUE(write_msp_packet(packet, buf));
    TEST_ASSERT_TRUE(feed_msp_bytes(MSPResponseProtocol, buf));

    mspPacket_t *received = MSPResponseProtocol.getReceivedPacket();
    TEST_ASSERT_EQUAL(MSP_PACKET_RESPONSE, received->type);
    TEST_ASSERT_EQUAL(7, received->payload[0]);
}

void test_msp_receive_ignores_unknown_packet_type(void)
{
    TEST_ASSERT_FALSE(MSPUnknownTypeProtocol.processReceivedByte('$'));
    TEST_ASSERT_FALSE(MSPUnknownTypeProtocol.processReceivedByte('X'));
    TEST_ASSERT_FALSE(MSPUnknownTypeProtocol.processReceivedByte('?'));

    mspPacket_t packet;
    packet.reset();
    packet.makeCommand();
    packet.flags = 0;
    packet.function = 1;
    packet.addByte('D');

    std::string buf;
    TEST_ASSERT_TRUE(write_msp_packet(packet, buf));
    TEST_ASSERT_TRUE(feed_msp_bytes(MSPUnknownTypeProtocol, buf));
}

void test_msp_receive_accepts_zero_payload_command(void)
{
    mspPacket_t packet;
    packet.reset();
    packet.makeCommand();
    packet.flags = 0;
    packet.function = 2;

    std::string buf;
    TEST_ASSERT_TRUE(write_msp_packet(packet, buf));
    TEST_ASSERT_TRUE(feed_msp_bytes(MSPZeroPayloadProtocol, buf));

    mspPacket_t *received = MSPZeroPayloadProtocol.getReceivedPacket();
    TEST_ASSERT_EQUAL(MSP_PACKET_COMMAND, received->type);
    TEST_ASSERT_EQUAL(0, received->payloadSize);
}

void test_msp_receive_rejects_bad_crc_and_recovers(void)
{
    mspPacket_t packet;
    packet.reset();
    packet.makeCommand();
    packet.flags = 0;
    packet.function = 1;
    packet.addByte('E');

    std::string badCrcBuf;
    TEST_ASSERT_TRUE(write_msp_packet(packet, badCrcBuf));
    badCrcBuf[badCrcBuf.size() - 1] ^= 0xff;
    TEST_ASSERT_FALSE(feed_msp_bytes(MSPCrcFailureProtocol, badCrcBuf));

    std::string validBuf;
    TEST_ASSERT_TRUE(write_msp_packet(packet, validBuf));
    TEST_ASSERT_TRUE(feed_msp_bytes(MSPCrcFailureProtocol, validBuf));
}

void test_msp_mark_packet_received_allows_next_packet(void)
{
    mspPacket_t firstPacket;
    firstPacket.reset();
    firstPacket.makeCommand();
    firstPacket.flags = 0;
    firstPacket.function = 1;
    firstPacket.addByte('F');

    std::string firstBuf;
    TEST_ASSERT_TRUE(write_msp_packet(firstPacket, firstBuf));
    TEST_ASSERT_TRUE(feed_msp_bytes(MSPMarkReceivedProtocol, firstBuf));

    MSPMarkReceivedProtocol.markPacketReceived();

    mspPacket_t secondPacket;
    secondPacket.reset();
    secondPacket.makeCommand();
    secondPacket.flags = 0;
    secondPacket.function = 1;
    secondPacket.addByte('G');

    std::string secondBuf;
    TEST_ASSERT_TRUE(write_msp_packet(secondPacket, secondBuf));
    TEST_ASSERT_TRUE(feed_msp_bytes(MSPMarkReceivedProtocol, secondBuf));
}

void test_msp_receive_recovers_if_not_marked_before_next_byte(void)
{
    mspPacket_t packet;
    packet.reset();
    packet.makeCommand();
    packet.flags = 0;
    packet.function = 1;
    packet.addByte('H');

    std::string buf;
    TEST_ASSERT_TRUE(write_msp_packet(packet, buf));
    TEST_ASSERT_TRUE(feed_msp_bytes(MSPUnmarkedProtocol, buf));
    TEST_ASSERT_FALSE(MSPUnmarkedProtocol.processReceivedByte('$'));
    TEST_ASSERT_TRUE(feed_msp_bytes(MSPUnmarkedProtocol, buf));
}

void test_msp_send_rejects_unknown_packet_type(void)
{
    mspPacket_t packet;
    packet.reset();

    std::string buf;
    TEST_ASSERT_FALSE(write_msp_packet(packet, buf));
    TEST_ASSERT_TRUE(buf.empty());
}

void test_msp_send_rejects_empty_response(void)
{
    mspPacket_t packet;
    packet.reset();
    packet.makeResponse();
    packet.flags = 0;
    packet.function = 1;

    std::string buf;
    TEST_ASSERT_FALSE(write_msp_packet(packet, buf));
    TEST_ASSERT_TRUE(buf.empty());
}

static WPARAM ResizeToWMSZ(struct resizeXY rz)
{
    static const WPARAM map[4][4] = {
    //             XNONE            LEFT              RIGHT             XCENTER
    /* YNONE */  { WMSZ_BOTTOMRIGHT, WMSZ_LEFT,        WMSZ_RIGHT,       WMSZ_BOTTOMRIGHT },
    /* TOP */    { WMSZ_TOP,         WMSZ_TOPLEFT,     WMSZ_TOPRIGHT,    WMSZ_TOP         },
    /* BOTTOM */ { WMSZ_BOTTOM,      WMSZ_BOTTOMLEFT,  WMSZ_BOTTOMRIGHT, WMSZ_BOTTOM      },
    /* CENTER */ { WMSZ_BOTTOMRIGHT, WMSZ_LEFT,        WMSZ_RIGHT,       WMSZ_BOTTOMRIGHT },
    };
    return map[rz.y][rz.x];
}

static void expect_int(const char *name, int got, int want)
{
    if (got != want) {
        printf("FAIL %s: got %d want %d\n", name, got, want);
        failures++;
    }
}

static void expect_str(const char *name, const char *got, const char *want)
{
    if (strcmp(got, want) != 0) {
        printf("FAIL %s: got '%s' want '%s'\n", name, got, want);
        failures++;
    }
}

static void expect_true(const char *name, int cond)
{
    if (!cond) {
        printf("FAIL %s\n", name);
        failures++;
    }
}

int main(void)
{
    char path[OS_FLSIZE + 1];
    char loc_path[OS_FLSIZE + 1];
    char tmp[] = "/tmp/ossec-fim-maint-test.XXXXXX";
    int fd;
    syscheck_maint_info info;
    syscheck_maint_info empty;

    /* Path builders */
    syscheck_maint_path(NULL, NULL, path, sizeof(path));
    expect_str("local path", path, SYSCHECK_DIR "/.syscheck.maint");

    syscheck_maint_path("web1", "10.0.0.5", path, sizeof(path));
    expect_str("agent path", path, SYSCHECK_DIR "/.(web1) 10.0.0.5.maint");

    syscheck_maint_path_from_location("syscheck", loc_path, sizeof(loc_path));
    expect_str("loc syscheck", loc_path, SYSCHECK_DIR "/.syscheck.maint");

    syscheck_maint_path_from_location("(web1) 10.0.0.5->syscheck",
                                      loc_path, sizeof(loc_path));
    expect_str("loc agent", loc_path,
               SYSCHECK_DIR "/.(web1) 10.0.0.5.maint");

    /* Round-trip marker I/O on a tempfile (DecodeSyscheck uses these helpers). */
    fd = mkstemp(tmp);
    expect_true("mkstemp", fd >= 0);
    if (fd >= 0) {
        close(fd);
        unlink(tmp);
    }

    memset(&empty, 0, sizeof(empty));
    expect_int("missing marker", syscheck_maint_read_path(tmp, &empty), 0);

    memset(&info, 0, sizeof(info));
    info.enabled = 1;
    info.enabled_at = 1700000000;
    info.pending_end = 0;
    info.silent_updates = 3;
    expect_int("write marker", syscheck_maint_write_path(tmp, &info), 1);

    memset(&empty, 0, sizeof(empty));
    expect_int("read marker", syscheck_maint_read_path(tmp, &empty), 1);
    expect_int("enabled", empty.enabled, 1);
    expect_true("enabled_at", empty.enabled_at == (time_t)1700000000);
    expect_int("pending_end off", empty.pending_end, 0);
    expect_true("silent_updates", empty.silent_updates == 3UL);

    /* pending_end flip mirrors DecodeSyscheck HC_SK_DB_COMPLETED clear path */
    empty.pending_end = 1;
    expect_int("write pending_end", syscheck_maint_write_path(tmp, &empty), 1);
    memset(&info, 0, sizeof(info));
    expect_int("read pending_end", syscheck_maint_read_path(tmp, &info), 1);
    expect_int("pending_end on", info.pending_end, 1);

    expect_str("list tag pending", syscheck_maint_list_tag(&info),
               "Maint(pending-end)");
    info.pending_end = 0;
    expect_str("list tag on", syscheck_maint_list_tag(&info), "Maint");
    info.enabled = 0;
    expect_str("list tag off", syscheck_maint_list_tag(&info), "");

    /* Clear marker (same as clear_location / end-after-baseline) */
    expect_true("unlink marker", unlink(tmp) == 0 || errno == ENOENT);
    expect_int("gone after clear", syscheck_maint_read_path(tmp, &info), 0);

    /* set_pending_end must fail without an existing marker */
    expect_int("pending_end without marker",
               syscheck_maint_set_pending_end("no-such-agent", "127.0.0.1", 1),
               0);

    if (failures) {
        printf("FAILED: %d assertion(s)\n", failures);
        return (1);
    }

    printf("PASS: fim_maint_test\n");
    return (0);
}

static void expect_int(const char *name, int got, int want)
{
    if (got != want) {
        printf("FAIL %s: got %d want %d\n", name, got, want);
        failures++;
