static Node *reduce_var_to_param_mutator(Node *node, void *context)
{
    reduce_var_param_context *ctx = (reduce_var_param_context *) context;

    if (node == NULL)
    {
        return NULL;
    }

    if (IsA(node, Var))
    {
        Var *var = (Var *) node;

        /*
         * Only the dummy (acc, elem) RTE at this level is rewritten. The
         * varlevelsup == 0 check is essential: an outer-query RTE can share
         * the same varno (each parse state's range table is numbered from 1),
         * so without it a correlated outer reference at attno 1/2 would be
         * silently rewritten into the accumulator/element param. Outer Vars
         * are instead left in place and rejected by reduce_body_check_walker.
         */
        if (var->varno == ctx->varno && var->varlevelsup == 0 &&
            (var->varattno == 1 || var->varattno == 2))
        {
            Param *param = makeNode(Param);

            param->paramkind = PARAM_EXEC;
            param->paramid = var->varattno - 1;
            param->paramtype = AGTYPEOID;
            param->paramtypmod = -1;
            param->paramcollid = InvalidOid;
            param->location = -1;

            return (Node *) param;
        }
    }

    return expression_tree_mutator(node, reduce_var_to_param_mutator, context);
}

static Query *make_reduce_var_subquery(char *acc_name, char *elem_name)
{
    Query *subquery = makeNode(Query);
    Const *acc_const;
    Const *elem_const;
    TargetEntry *acc_te;
    TargetEntry *elem_te;

    acc_const = makeConst(AGTYPEOID, -1, InvalidOid, -1, (Datum) 0, true, false);
    elem_const = makeConst(AGTYPEOID, -1, InvalidOid, -1, (Datum) 0, true, false);

    acc_te = makeTargetEntry((Expr *) acc_const, 1, acc_name, false);
    elem_te = makeTargetEntry((Expr *) elem_const, 2, elem_name, false);

    subquery->commandType = CMD_SELECT;
    subquery->targetList = list_make2(acc_te, elem_te);
    subquery->jointree = makeFromExpr(NIL, NULL);
    subquery->rtable = NIL;
    subquery->rteperminfos = NIL;

    return subquery;
}

static bool reduce_body_check_walker(Node *node, void *context)
{
    if (node == NULL)
    {
        return false;
    }

    if (IsA(node, Var))
    {
        ereport(ERROR,
                (errcode(ERRCODE_FEATURE_NOT_SUPPORTED),
                 errmsg("a reduce() expression may only reference its accumulator and element variables")));
    }

    if (IsA(node, Param))
    {
        Param *param = (Param *) node;

        if (param->paramkind != PARAM_EXEC ||
            (param->paramid != 0 && param->paramid != 1))
        {
            ereport(ERROR,
                    (errcode(ERRCODE_FEATURE_NOT_SUPPORTED),
                     errmsg("a reduce() expression may not reference query parameters")));
        }
    }

    if (IsA(node, Aggref) || IsA(node, GroupingFunc) || IsA(node, WindowFunc))
    {
        ereport(ERROR,
                (errcode(ERRCODE_FEATURE_NOT_SUPPORTED),
                 errmsg("aggregate functions are not supported in a reduce() expression")));
    }

    if (IsA(node, SubLink))
    {
        ereport(ERROR,
                (errcode(ERRCODE_FEATURE_NOT_SUPPORTED),
                 errmsg("subqueries (including a nested reduce()) are not supported in a reduce() expression")));
    }

    return expression_tree_walker(node, reduce_body_check_walker, context);
}

static Datum reduce_agtype_null(void)
{
    agtype_value agtv;

    agtv.type = AGTV_NULL;
    return AGTYPE_P_GET_DATUM(agtype_value_to_agtype(&agtv));
}

Datum age_reduce_transfn(PG_FUNCTION_ARGS)
{
    MemoryContext aggcontext;
    MemoryContext oldctx;
    reduce_eval_ctx *rc;
    Datum acc;
    Datum element;
    Datum result;
    bool result_isnull;

    if (!AggCheckCallContext(fcinfo, &aggcontext))
    {
        ereport(ERROR,
                (errcode(ERRCODE_FEATURE_NOT_SUPPORTED),
                 errmsg("age_reduce_transfn called in a non-aggregate context")));
    }

    /* the fold can run over a large list; stay responsive to cancellation */
    CHECK_FOR_INTERRUPTS();

    /*
     * One-time per-FmgrInfo setup: deserialize and compile the fold body, and
     * build the standalone ExprContext plus its two PARAM_EXEC slots. The body
     * text is a query constant, so caching the compiled state across groups is
     * correct.
     */
    rc = (reduce_eval_ctx *) fcinfo->flinfo->fn_extra;
    if (rc == NULL)
    {
        text *body_txt;
        char *body_str;
        Node *body_node;

        if (PG_ARGISNULL(2))
        {
            ereport(ERROR,
                    (errcode(ERRCODE_INTERNAL_ERROR),
                     errmsg("age_reduce: missing fold expression")));
        }

        oldctx = MemoryContextSwitchTo(fcinfo->flinfo->fn_mcxt);
        rc = (reduce_eval_ctx *) palloc0(sizeof(reduce_eval_ctx));
        body_txt = PG_GETARG_TEXT_PP(2);
        body_str = text_to_cstring(body_txt);
        body_node = (Node *) stringToNode(body_str);

        /*
         * age_reduce() is SQL-callable, so the serialized body argument is
         * not guaranteed to have come from transform_cypher_reduce(). The
         * running state is stored as an agtype varlena (the datumCopy() below
         * uses typbyval=false, typlen=-1), so a body that evaluates to a
         * by-value type (e.g. a bare boolean or integer) would have its Datum
         * misread as a pointer and could crash the backend. Reject any body
         * whose result type is not agtype. transform_cypher_reduce() always
         * normalizes the fold body to agtype, so a planner-generated reduce()
         * is never rejected here.
         */
        if (exprType(body_node) != AGTYPEOID)
        {
            ereport(ERROR,
                    (errcode(ERRCODE_FEATURE_NOT_SUPPORTED),
                     errmsg("age_reduce: fold expression must return agtype")));
        }

        rc->body_state = ExecInitExpr((Expr *) body_node, NULL);
        rc->econtext = CreateStandaloneExprContext();
        rc->params = (ParamExecData *) palloc0(sizeof(ParamExecData) * 2);
        rc->econtext->ecxt_param_exec_vals = rc->params;
        fcinfo->flinfo->fn_extra = rc;
        MemoryContextSwitchTo(oldctx);
    }

    /*
     * Seed the accumulator. The aggregate declares no initcond, so on the
     * first element the running state (arg 0) is NULL and we use `init`
     * (arg 1); thereafter the accumulator is the prior state. A NULL init is
     * normalized to agtype 'null'.
     */
    if (PG_ARGISNULL(0))
    {
        acc = PG_ARGISNULL(1) ? reduce_agtype_null() : PG_GETARG_DATUM(1);
    }
    else
    {
        acc = PG_GETARG_DATUM(0);
    }

    /* a NULL element is likewise normalized to agtype 'null' */
    element = PG_ARGISNULL(3) ? reduce_agtype_null() : PG_GETARG_DATUM(3);

    /* bind PARAM_EXEC 0 = accumulator, 1 = current element */
    rc->params[0].value = acc;
    rc->params[0].isnull = false;
    rc->params[0].execPlan = NULL;
    rc->params[1].value = element;
    rc->params[1].isnull = false;
    rc->params[1].execPlan = NULL;

    /* evaluate the fold body for this element */
    ResetExprContext(rc->econtext);
    result = ExecEvalExpr(rc->body_state, rc->econtext, &result_isnull);

    /*
     * Never let the running state become a SQL NULL: a null fold result is
     * stored as agtype 'null' so the next element is not mistaken for the
     * first one (see PG_ARGISNULL(0) above).
     */
    if (result_isnull)
    {
        result = reduce_agtype_null();
    }

    /* the new state must survive in the aggregate context across elements */
    oldctx = MemoryContextSwitchTo(aggcontext);
    result = datumCopy(result, false, -1);
    MemoryContextSwitchTo(oldctx);

    PG_RETURN_DATUM(result);
}

atic void sp_queue_init(sp_queue *q)
{
    q->cap = 1024;
    q->head = 0;
    q->tail = 0;
    q->data = palloc(sizeof(graphid) * q->cap);
}

atic void sp_queue_push(sp_queue *q, graphid v)
{
    if (q->tail == q->cap)
    {
        q->cap = q->cap * 2;
        q->data = repalloc(q->data, sizeof(graphid) * q->cap);
    }
    q->data[q->tail] = v;
    q->tail = q->tail + 1;
}

atic graphid sp_queue_pop(sp_queue *q)
{
    graphid v = q->data[q->head];

    q->head = q->head + 1;
    return v;
}

atic graphid sp_agtype_to_graphid(agtype *agt, const char *argname)
{
    agtype_value *agtv = NULL;

    agtv = get_agtype_value("age_shortest_path", agt, AGTV_VERTEX, false);

    if (agtv != NULL && agtv->type == AGTV_VERTEX)
    {
        agtv = GET_AGTYPE_VALUE_OBJECT_VALUE(agtv, "id");
    }
    else if (agtv == NULL || agtv->type != AGTV_INTEGER)
    {
        ereport(ERROR,
                (errcode(ERRCODE_INVALID_PARAMETER_VALUE),
                 errmsg("%s argument must be a vertex or the integer id",
                        argname)));
    }

    return agtv->val.int_value;
}

atic cypher_rel_dir sp_agtype_to_direction(agtype *agt)
{
    agtype_value *agtv = NULL;
    char *s = NULL;
    cypher_rel_dir dir = CYPHER_REL_DIR_NONE;

    if (agt == NULL)
    {
        return CYPHER_REL_DIR_NONE;
    }

    agtv = get_agtype_value("age_shortest_path", agt, AGTV_STRING, true);
    s = pnstrdup(agtv->val.string.val, agtv->val.string.len);

    if (pg_strcasecmp(s, "out") == 0)
    {
        dir = CYPHER_REL_DIR_RIGHT;
    }
    else if (pg_strcasecmp(s, "in") == 0)
    {
        dir = CYPHER_REL_DIR_LEFT;
    }
    else if (pg_strcasecmp(s, "any") == 0)
    {
        dir = CYPHER_REL_DIR_NONE;
    }
    else
    {
        ereport(ERROR,
                (errcode(ERRCODE_INVALID_PARAMETER_VALUE),
                 errmsg("direction argument must be one of 'out', 'in', or 'any'")));
    }

    pfree_if_not_null(s);
    return dir;
}

atic Datum sp_build_path_datum(Oid graph_oid, graphid *alt, int64 alt_len)
{
    VLE_path_container *vpc = NULL;
    graphid *arr = NULL;
    agtype_value *agtv_path = NULL;
    agtype *agt = NULL;

    vpc = create_VLE_path_container(alt_len);
    vpc->graph_oid = graph_oid;

    arr = GET_GRAPHID_ARRAY_FROM_CONTAINER(vpc);
    memcpy(arr, alt, sizeof(graphid) * alt_len);

    vpc->start_vid = alt[0];
    vpc->end_vid = alt[alt_len - 1];

    agtv_path = build_path(vpc);
    agt = agtype_value_to_agtype(agtv_path);

    return AGTYPE_P_GET_DATUM(agt);
}

atic void sp_enumerate(HTAB *visited, graphid source, graphid cur,
                         graphid *alt, int64 alt_len, int64 pos, List **out)
{
    sp_visit_entry *e = NULL;
    ListCell *lc = NULL;

    /*
     * Enumerating every shortest path can be combinatorially expensive, so
     * allow the user to cancel (Ctrl-C / statement_timeout) at each step.
     */
    CHECK_FOR_INTERRUPTS();

    alt[pos] = cur;

    if (cur == source)
    {
        /* a complete path only when we have consumed the whole array */
        if (pos == 0)
        {
            graphid *copy = palloc(sizeof(graphid) * alt_len);

            memcpy(copy, alt, sizeof(graphid) * alt_len);
            *out = lappend(*out, copy);
        }
        return;
    }

    e = (sp_visit_entry *) hash_search(visited, &cur, HASH_FIND, NULL);
    if (e == NULL)
    {
        return;
    }

    foreach(lc, e->preds)
    {
        sp_pred *p = (sp_pred *) lfirst(lc);

        alt[pos - 1] = p->edge;
        sp_enumerate(visited, source, p->parent_vertex, alt, alt_len, pos - 2,
                     out);
    }
}

atic Datum sp_srf_impl(FunctionCallInfo fcinfo, bool collect_all)
{
    FuncCallContext *funcctx = NULL;
    sp_srf_state *state = NULL;

    if (SRF_IS_FIRSTCALL())
    {
        MemoryContext oldctx;
        agtype *a_graph = NULL;
        agtype *a_start = NULL;
        agtype *a_end = NULL;
        agtype *a_label = NULL;
        agtype *a_dir = NULL;
        agtype *a_min = NULL;
        agtype *a_max = NULL;

        funcctx = SRF_FIRSTCALL_INIT();
        oldctx = MemoryContextSwitchTo(funcctx->multi_call_memory_ctx);

        /*
         * Argument order mirrors the Cypher shortestPath() pattern
         * (a)-[:type*min_hops..max_hops]->(b):
         *   0 graph, 1 start, 2 end, 3 edge_types, 4 direction,
         *   5 min_hops, 6 max_hops
         */
        a_graph = PG_ARGISNULL(0) ? NULL : AG_GET_ARG_AGTYPE_P(0);
        a_start = PG_ARGISNULL(1) ? NULL : AG_GET_ARG_AGTYPE_P(1);
        a_end = PG_ARGISNULL(2) ? NULL : AG_GET_ARG_AGTYPE_P(2);
        a_label = PG_ARGISNULL(3) ? NULL : AG_GET_ARG_AGTYPE_P(3);
        a_dir = PG_ARGISNULL(4) ? NULL : AG_GET_ARG_AGTYPE_P(4);
        a_min = PG_ARGISNULL(5) ? NULL : AG_GET_ARG_AGTYPE_P(5);
        a_max = PG_ARGISNULL(6) ? NULL : AG_GET_ARG_AGTYPE_P(6);

        /* treat an explicit agtype null the same as a SQL NULL */
        if (a_start != NULL && is_agtype_null(a_start))
        {
            a_start = NULL;
        }
        if (a_end != NULL && is_agtype_null(a_end))
        {
            a_end = NULL;
        }
        if (a_label != NULL && is_agtype_null(a_label))
        {
            a_label = NULL;
        }
        if (a_dir != NULL && is_agtype_null(a_dir))
        {
            a_dir = NULL;
        }
        if (a_min != NULL && is_agtype_null(a_min))
        {
            a_min = NULL;
        }
        if (a_max != NULL && is_agtype_null(a_max))
        {
            a_max = NULL;
        }

        state = palloc0(sizeof(sp_srf_state));
        state->next = 0;
        state->paths = sp_compute_paths(a_graph, a_start, a_end, a_label,
                                        a_dir, a_min, a_max, collect_all,
                                        &state->npaths);
        funcctx->user_fctx = state;

        MemoryContextSwitchTo(oldctx);
    }

    funcctx = SRF_PERCALL_SETUP();
    state = (sp_srf_state *) funcctx->user_fctx;

    if (state->next < state->npaths)
    {
        Datum d = state->paths[state->next];

        state->next = state->next + 1;
        SRF_RETURN_NEXT(funcctx, d);
    }

    SRF_RETURN_DONE(funcctx);
}

else if (tok == WAGT_BEGIN_ARRAY)
        {
            /* push raw_scalar state for the matching END token */
            raw_scalar_top++;
            if (raw_scalar_top >= HASH_RAW_SCALAR_STACK_DEPTH)
            {
                ereport(ERROR,
                        (errcode(ERRCODE_PROGRAM_LIMIT_EXCEEDED),
                         errmsg("agtype_hash_cmp: array nesting depth exceeds %d",
                                HASH_RAW_SCALAR_STACK_DEPTH)));
            }
            raw_scalar_stack[raw_scalar_top] = r->val.array.raw_scalar;
            if (!r->val.array.raw_scalar)
            {
                seed = LEFT_ROTATE(seed, 4);
            }
        }

else if (tok == WAGT_END_ARRAY)
        {
            bool was_raw_scalar;

            /* pop matching BEGIN's raw_scalar state */
            if (raw_scalar_top < 0)
            {
                ereport(ERROR,
                        (errcode(ERRCODE_DATA_CORRUPTED),
                         errmsg("agtype_hash_cmp: WAGT_END_ARRAY without matching WAGT_BEGIN_ARRAY")));
            }
            was_raw_scalar = raw_scalar_stack[raw_scalar_top];
            raw_scalar_top--;
            if (!was_raw_scalar)
            {
                seed = RIGHT_ROTATE(seed, 4);
            }
        }

MemoryContext agt_arena_begin(void)
{
    /*
     * ALLOCSET_SMALL_SIZES (initial=1KB, max=8KB). Most agtype value trees
     * fit in a single 1KB block.
     */
    return AllocSetContextCreate(CurrentMemoryContext,
                                 "agtype build arena",
                                 ALLOCSET_SMALL_SIZES);
}

void agt_arena_reset(MemoryContext arena)
{
    if (arena != NULL)
    {
        MemoryContextReset(arena);
    }
}

void agt_arena_end(MemoryContext arena)
{
    if (arena != NULL)
    {
        MemoryContextDelete(arena);
    }
}

static bool extract_composite_id_fast(const agtype_container *outer_scalar,
                                      graphid *out)
{
    const char *base_addr;
    const agtype_container *obj;
    int n_pairs;
    const agtentry *children;
    uint32 id_value_offset;
    char *id_value_base;
    char *id_extended_base;
    AGT_HEADER_TYPE id_header;
    int id_value_index;

    /* outer_scalar is a single-element pseudo-array; element 0 is our extended type */
    base_addr = (const char *)&outer_scalar->children[1];

    /*
     * Element 0 is an extended type. Its data starts at base_addr + 0 and
     * begins with AGT_HEADER_VERTEX or AGT_HEADER_EDGE; the inner
     * agtype_container follows immediately.
     */
    obj = (const agtype_container *)((const char *)base_addr + AGT_HEADER_SIZE);
    n_pairs = AGTYPE_CONTAINER_SIZE(obj);
    children = obj->children;

    /*
     * Pair value 0 ("id") lives at child index n_pairs (values come after
     * keys). Compute its offset within the object's data area.
     */
    id_value_index = n_pairs;
    id_value_offset = get_agtype_offset(obj, id_value_index);

    /* Data area for this object starts after children[2*n_pairs] */
    id_value_base = (char *)&children[2 * n_pairs];

    /*
     * The id value is an extended AGTV_INTEGER: AGT_HEADER (aligned) followed
     * by the int64. INTALIGN matches what ag_deserialize_extended_type does.
     */
    id_extended_base = id_value_base + INTALIGN(id_value_offset);
    /*
     * The header is uint32 (4-byte) and lives at a 4-byte-aligned address,
     * so a typed load is fine. The int64 that follows starts at offset
     * AGT_HEADER_SIZE = 4 from id_extended_base, so it is 4-byte- but not
     * necessarily 8-byte-aligned; use memcpy to avoid alignment UB.
     */
    memcpy(&id_header, id_extended_base, sizeof(AGT_HEADER_TYPE));

    /*
     * Defensive: if the value isn't actually an extended integer, fall back
     * to the slow deserialize path by signaling. AGT_HEADER_INTEGER is the
     * only valid header for the id field of a well-formed VERTEX/EDGE.
     */
    if (id_header != AGT_HEADER_INTEGER)
    {
        return false;
    }

    {
        graphid id;

        memcpy(&id, id_extended_base + AGT_HEADER_SIZE, sizeof(int64));
        *out = id;
        return true;
    }
}

