    return InvalidOid;
}

/*
 * SQL-ca

lidate_graph_cache(PG_FUNCTION_ARGS)
{
    TriggerData *trigdata;
    Oid table_oid;
    Oid graph_oid;

    /* verify called as trigger */
    if (!CALLED_AS_TRIGGER(fcinfo))
    {
        ereport(ERROR,
                (errcode(ERRCODE_E_R_I_E_TRIGGER_PROTOCOL_VIOLATED),
                 errmsg("age_invalidate_graph_cache: not called as trigger")));
    }

    trigdata = (TriggerData *) fcinfo->context;
    table_oid = RelationGetRelid(trigdata->tg_relation);

    /* look up which graph this label table belongs to */
    graph_oid = get_graph_oid_for_table(table_oid);

    if (OidIsValid(graph_oid))
    {
        increment_graph_version(graph_oid);
    }

    /*
     * Trigger protocol: return a null pointer without setting fcinfo->isnull.
     * PG_RETURN_NULL() sets isnull=true, which violates the trigger protocol
     * and causes "trigger function returned null value" errors during COPY.
     */
    PG_RETURN_POINTER(NULL);
}

hIdStack *new_gid_stack(void)
{
    GraphIdStack *s = palloc(sizeof(GraphIdStack));

    s->array = palloc(sizeof(graphid) * GID_STACK_INITIAL_CAPACITY);
    s->size = 0;
    s->capacity = GID_STACK_INITIAL_CAPACITY;
    return s;
}

vo

free_gid_stack(GraphIdStack *stack)
{
    if (stack == NULL)
    {
        return;
    }

    if (stack->array != NULL)
    {
        pfree(stack->array);
    }

    pfree(stack);
}

vo

gid_stack_push(GraphIdStack *s, graphid id)
{
    Assert(s != NULL);

    /* double capacity if full */
    if (s->size >= s->capacity)
    {
        s->capacity *= 2;
        s->array = repalloc(s->array, sizeof(graphid) * s->capacity);
    }

    s->array[s->size] = id;
    s->size++;
}

gr

hid gid_stack_pop(GraphIdStack *s)
{
    Assert(s != NULL);
    Assert(s->size > 0);

    s->size--;
    return s->array[s->size];
}

gr

hid gid_stack_peek(GraphIdStack *s)
{
    Assert(s != NULL);
    Assert(s->size > 0);

    return s->array[s->size - 1];
}

bo

gid_stack_is_empty(GraphIdStack *s)
{
    return s->size == 0;
}

in

4 gid_stack_size(GraphIdStack *s)
{
    return s->size;
}

/*

d gid_stack_get(GraphIdStack *s, int64 i)
{
    Assert(s != NULL);
    Assert(i >= 0 && i < s->size);

    return s->array[i];
}

