QUIC_STATUS
CxPlatDataPathGetLocalAddressForRemote(
    _In_ const QUIC_ADDR* RemoteAddress,
    _Out_ QUIC_ADDR* LocalAddress
    )
{
    UNREFERENCED_PARAMETER(RemoteAddress);
    UNREFERENCED_PARAMETER(LocalAddress);
    return QUIC_STATUS_NOT_SUPPORTED;
}

_IRQL_requires_max_(PASSIVE_LEVEL)
QUIC_STATUS
CxPlatDataPathGetLocalAddressForRemote(
    _In_ const QUIC_ADDR* RemoteAddress,
    _Out_ QUIC_ADDR* LocalAddress
    )
{
    UNREFERENCED_PARAMETER(RemoteAddress);
    UNREFERENCED_PARAMETER(LocalAddress);
    return QUIC_STATUS_NOT_SUPPORTED;
}

_IRQL_requires_max_(PASSIVE_LEVEL)
QUIC_STATUS
CxPlatDataPathGetLocalAddressForRemote(
    _In_ const QUIC_ADDR* RemoteAddress,
    _Out_ QUIC_ADDR* LocalAddress
    )
{
    QUIC_STATUS Status = QUIC_STATUS_SUCCESS;
    SOCKET Socket = socket(RemoteAddress->si_family, SOCK_DGRAM, IPPROTO_UDP);
    if (Socket == INVALID_SOCKET) {
        return HRESULT_FROM_WIN32(WSAGetLastError());
    }

    const int RemoteAddressLength =
        RemoteAddress->si_family == AF_INET ?
            sizeof(RemoteAddress->Ipv4) :
            sizeof(RemoteAddress->Ipv6);
    if (connect(Socket, (PSOCKADDR)RemoteAddress, RemoteAddressLength) == SOCKET_ERROR) {
        Status = HRESULT_FROM_WIN32(WSAGetLastError());
        goto Error;
    }

    CxPlatZeroMemory(LocalAddress, sizeof(*LocalAddress));
    int LocalAddressLength = sizeof(*LocalAddress);
    if (getsockname(Socket, (PSOCKADDR)LocalAddress, &LocalAddressLength) == SOCKET_ERROR) {
        Status = HRESULT_FROM_WIN32(WSAGetLastError());
        goto Error;
    }

Error:
    closesocket(Socket);
    return Status;
}

static BOOLEAN
ParseArgs(
    int ArgC,
    char** ArgV
    )
{
    int i = 1;
    TargetPid = 0;
    IfIndex = MAXUINT32;
    UdpPort = 0;
    CidServerIdLength = 0;
    HasCibirId = FALSE;

    while (i < ArgC) {
        if (!_stricmp(ArgV[i], "-TargetPid") || !_stricmp(ArgV[i], "-pid")) {
            if (++i >= ArgC) {
                LOGERR("Missing TargetPid value");
                return FALSE;
            }
            TargetPid = (UINT32)atoi(ArgV[i]);
        } else if (!_stricmp(ArgV[i], "-IfIndex")) {
            if (++i >= ArgC) {
                LOGERR("Missing IfIndex value");
                return FALSE;
            }
            IfIndex = (UINT32)atoi(ArgV[i]);
            if (IfIndex == 0) {
                LOGERR("Invalid IfIndex value '%s' (must be a non-zero integer)", ArgV[i]);
                return FALSE;
            }
        } else if (!_stricmp(ArgV[i], "-UdpPort")) {
            if (++i >= ArgC) {
                LOGERR("Missing UdpPort value");
                return FALSE;
            }
            UdpPort = (UINT16)atoi(ArgV[i]);
        } else if (!_stricmp(ArgV[i], "-CidServerIdLength")) {
            if (++i >= ArgC) {
                LOGERR("Missing CidServerIdLength value");
                return FALSE;
            }
            CidServerIdLength = (UINT8)atoi(ArgV[i]);
        } else if (!_stricmp(ArgV[i], "-CibirId")) {
            if (++i >= ArgC) {
                LOGERR("Missing CibirId value");
                return FALSE;
            }
            UINT8 CibirRaw[XDPMAP_CIBIR_RAW_MAX_LEN]; // offset (1 byte) + max CID bytes
            UINT32 CibirRawLen = XdpMapDecodeHexBuffer(ArgV[i], sizeof(CibirRaw), CibirRaw);
            if (CibirRawLen < 2) {
                LOGERR("CIBIR ID too short (need at least offset + 1 byte CID)");
                return FALSE;
            }
            CibirIdLength = (UINT8)(CibirRawLen - 1);
            memcpy(CibirIdData, &CibirRaw[1], CibirIdLength);
            HasCibirId = TRUE;
        } else {
            LOGERR("Unexpected parameter \"%s\"", ArgV[i]);
            return FALSE;
        }
        ++i;
    }

    if (TargetPid == 0) {
        LOGERR("-TargetPid is required");
        return FALSE;
    }
    if (IfIndex == MAXUINT32) {
        LOGERR("-IfIndex is required");
        return FALSE;
    }
    if (UdpPort == 0) {
        LOGERR("-UdpPort is required");
        return FALSE;
    }

    return TRUE;
}

static
BOOLEAN
GetFlag(
    _In_ int argc,
    _In_reads_(argc) _Null_terminated_ char* argv[],
    _In_z_ const char* name
    )
{
    const size_t nameLen = strlen(name);
    for (int i = 0; i < argc; i++) {
        if (_strnicmp(argv[i] + 1, name, nameLen) == 0 && strlen(argv[i]) == nameLen + 1) {
            return TRUE;
        }
    }
    return FALSE;
}

const char*
GetValue(
    _In_ int argc,
    _In_reads_(argc) _Null_terminated_ char* argv[],
    _In_z_ const char* name
    )
{
    const size_t nameLen = strlen(name);
    for (int i = 0; i < argc; i++) {
        if (_strnicmp(argv[i] + 1, name, nameLen) == 0 &&
            strlen(argv[i]) > 1 + nameLen + 1 &&
            *(argv[i] + 1 + nameLen) == ':') {
            return argv[i] + 1 + nameLen + 1;
        }
    }
    return NULL;
}

static
BOOLEAN
ParseArgs(
    _In_ int argc,
    _In_reads_(argc) _Null_terminated_ char* argv[],
    _Out_ SERVER_ARGS* Args
    )
{
    memset(Args, 0, sizeof(*Args));

    const char* IfIndexStr = GetValue(argc, argv, "xdp_map_ifindex");
    if (IfIndexStr == NULL) {
        printf("Missing required argument '-xdp_map_ifindex:<N>'.\n");
        return FALSE;
    }
    Args->XdpMapIfIndex = (UINT32)atoi(IfIndexStr);
    if (Args->XdpMapIfIndex == 0) {
        printf("Invalid interface index '%s'.\n", IfIndexStr);
        return FALSE;
    }

    Args->CertHash = GetValue(argc, argv, "cert_hash");
    Args->CertFile = GetValue(argc, argv, "cert_file");
    Args->KeyFile = GetValue(argc, argv, "key_file");
    Args->Password = GetValue(argc, argv, "password");
    Args->CibirIdHex = GetValue(argc, argv, "cibir_id");

    if (Args->CertHash == NULL &&
        (Args->CertFile == NULL || Args->KeyFile == NULL)) {
        printf("Must specify '-cert_hash' or '-cert_file' with '-key_file'.\n");
        return FALSE;
    }

    return TRUE;
}

static
QUIC_STATUS
QUIC_API
ServerStreamCallback(
    _In_ HQUIC Stream,
    _In_opt_ void* Context,
    _Inout_ QUIC_STREAM_EVENT* Event
    )
{
    UNREFERENCED_PARAMETER(Context);

    switch (Event->Type) {
    case QUIC_STREAM_EVENT_RECEIVE:
        MsQuic->StreamShutdown(Stream, QUIC_STREAM_SHUTDOWN_FLAG_GRACEFUL, 0);
        break;
    case QUIC_STREAM_EVENT_PEER_SEND_ABORTED:
    case QUIC_STREAM_EVENT_PEER_SEND_SHUTDOWN:
        MsQuic->StreamShutdown(Stream, QUIC_STREAM_SHUTDOWN_FLAG_GRACEFUL, 0);
        break;
    case QUIC_STREAM_EVENT_SHUTDOWN_COMPLETE:
        MsQuic->StreamClose(Stream);
        break;
    default:
        break;
    }

    return QUIC_STATUS_SUCCESS;
}

static
QUIC_STATUS
QUIC_API
ServerConnectionCallback(
    _In_ HQUIC Connection,
    _In_opt_ void* Context,
    _Inout_ QUIC_CONNECTION_EVENT* Event
    )
{
    UNREFERENCED_PARAMETER(Context);

    switch (Event->Type) {
    case QUIC_CONNECTION_EVENT_CONNECTED:
        printf("[conn][%p] Connected\n", Connection);
        break;
    case QUIC_CONNECTION_EVENT_SHUTDOWN_INITIATED_BY_TRANSPORT:
        printf("[conn][%p] Shutdown by transport, 0x%x\n", Connection, Event->SHUTDOWN_INITIATED_BY_TRANSPORT.Status);
        break;
    case QUIC_CONNECTION_EVENT_SHUTDOWN_INITIATED_BY_PEER:
        printf("[conn][%p] Shutdown by peer, 0x%llx\n", Connection, (unsigned long long)Event->SHUTDOWN_INITIATED_BY_PEER.ErrorCode);
        break;
    case QUIC_CONNECTION_EVENT_PEER_STREAM_STARTED:
        MsQuic->SetCallbackHandler(Event->PEER_STREAM_STARTED.Stream, (void*)ServerStreamCallback, NULL);
        break;
    case QUIC_CONNECTION_EVENT_SHUTDOWN_COMPLETE:
        MsQuic->ConnectionClose(Connection);
        break;
    default:
        break;
    }

    return QUIC_STATUS_SUCCESS;
}

static
QUIC_STATUS
QUIC_API
ServerListenerCallback(
    _In_ HQUIC Listener,
    _In_opt_ void* Context,
    _Inout_ QUIC_LISTENER_EVENT* Event
    )
{
    UNREFERENCED_PARAMETER(Listener);

    if (Event->Type == QUIC_LISTENER_EVENT_NEW_CONNECTION) {
        HQUIC Config = (HQUIC)Context;
        MsQuic->SetCallbackHandler(Event->NEW_CONNECTION.Connection, (void*)ServerConnectionCallback, NULL);
        return MsQuic->ConnectionSetConfiguration(Event->NEW_CONNECTION.Connection, Config);
    }

    return QUIC_STATUS_NOT_SUPPORTED;
}

static
BOOLEAN
LoadServerConfiguration(
    _In_ const SERVER_ARGS* Args,
    _Out_ HQUIC* ConfigurationOut
    )
{
    *ConfigurationOut = NULL;
    QUIC_SETTINGS Settings = {0};
    QUIC_STATUS Status;
    HQUIC Config = NULL;

    QUIC_SETTINGS XdpSettings = {0};
    XdpSettings.XdpEnabled = TRUE;
    XdpSettings.IsSet.XdpEnabled = TRUE;
    Status = MsQuic->SetParam(NULL, QUIC_PARAM_GLOBAL_SETTINGS, sizeof(XdpSettings), &XdpSettings);
    if (QUIC_FAILED(Status)) {
        printf("Failed to enable XDP globally, 0x%x!\n", Status);
        return FALSE;
    }

    QUIC_CREDENTIAL_CONFIG_HELPER CredHelper;
    memset(&CredHelper, 0, sizeof(CredHelper));
    CredHelper.CredConfig.Flags = QUIC_CREDENTIAL_FLAG_NONE;

    if (Args->CertHash != NULL) {
        uint32_t CertHashLen =
            XdpMapDecodeHexBuffer(
                Args->CertHash,
                sizeof(CredHelper.CertHash.ShaHash),
                CredHelper.CertHash.ShaHash);
        if (CertHashLen != sizeof(CredHelper.CertHash.ShaHash)) {
            printf("Invalid cert hash length.\n");
            return FALSE;
        }
        CredHelper.CredConfig.Type = QUIC_CREDENTIAL_TYPE_CERTIFICATE_HASH;
        CredHelper.CredConfig.CertificateHash = &CredHelper.CertHash;
    } else {
        if (Args->Password != NULL) {
            CredHelper.CertFileProtected.CertificateFile = (char*)Args->CertFile;
            CredHelper.CertFileProtected.PrivateKeyFile = (char*)Args->KeyFile;
            CredHelper.CertFileProtected.PrivateKeyPassword = (char*)Args->Password;
            CredHelper.CredConfig.Type = QUIC_CREDENTIAL_TYPE_CERTIFICATE_FILE_PROTECTED;
            CredHelper.CredConfig.CertificateFileProtected = &CredHelper.CertFileProtected;
        } else {
            CredHelper.CertFile.CertificateFile = (char*)Args->CertFile;
            CredHelper.CertFile.PrivateKeyFile = (char*)Args->KeyFile;
            CredHelper.CredConfig.Type = QUIC_CREDENTIAL_TYPE_CERTIFICATE_FILE;
            CredHelper.CredConfig.CertificateFile = &CredHelper.CertFile;
        }
    }

    Status = MsQuic->ConfigurationOpen(Registration, &Alpn, 1, &Settings, sizeof(Settings), NULL, &Config);
    if (QUIC_FAILED(Status)) {
        printf("ConfigurationOpen failed, 0x%x!\n", Status);
        return FALSE;
    }

    Status = MsQuic->ConfigurationLoadCredential(Config, &CredHelper.CredConfig);
    if (QUIC_FAILED(Status)) {
        printf("ConfigurationLoadCredential failed, 0x%x!\n", Status);
        MsQuic->ConfigurationClose(Config);
        return FALSE;
    }

    *ConfigurationOut = Config;
    return TRUE;
}

static
BOOLEAN
PromptForXdpMapHandle(
    _In_ const SERVER_ARGS* Args,
    _Out_ UINT_PTR* HandleValueOut
    )
{
    *HandleValueOut = 0;
    char InputBuf[64];

    printf("=== XDP Map Mode (Consumer) ===\n");
    printf("  PID: %u\n", (unsigned)GetCurrentProcessId());
    printf("  IfIndex: %u\n\n", Args->XdpMapIfIndex);
    printf("Start orchestrator in another terminal:\n");

    if (Args->CibirIdHex != NULL) {
        printf("  ./orchestrator.exe -TargetPid %u -IfIndex %u -UdpPort %u -CibirId %s\n",
            (unsigned)GetCurrentProcessId(), Args->XdpMapIfIndex, UdpPort, Args->CibirIdHex);
    } else {
        printf("  ./orchestrator.exe -TargetPid %u -IfIndex %u -UdpPort %u\n",
            (unsigned)GetCurrentProcessId(), Args->XdpMapIfIndex, UdpPort);
    }

    printf("\nPaste XSKMAP handle value here (hex): ");
    fflush(stdout);

    if (fgets(InputBuf, sizeof(InputBuf), stdin) == NULL) {
        printf("Failed to read input.\n");
        return FALSE;
    }

    *HandleValueOut = (UINT_PTR)_strtoui64(InputBuf, NULL, 16);
    if (*HandleValueOut == 0 || *HandleValueOut == (UINT_PTR)INVALID_HANDLE_VALUE) {
        printf("Invalid handle value: %s\n", InputBuf);
        return FALSE;
    }

    return TRUE;
}

static
BOOLEAN
ConfigureXdpMap(
    _In_ UINT32 IfIndex,
    _In_ QUIC_XDP_MAP_HANDLE MapHandle
    )
{
    QUIC_XDP_MAP_CONFIG MapConfig;
    MapConfig.InterfaceIndex = IfIndex;
    MapConfig.MapHandle = MapHandle;

    QUIC_STATUS Status = MsQuic->SetParam(
        NULL,
        QUIC_PARAM_GLOBAL_XDP_MAP_CONFIG,
        sizeof(MapConfig),
        &MapConfig);
    if (QUIC_FAILED(Status)) {
        printf("SetParam(QUIC_PARAM_GLOBAL_XDP_MAP_CONFIG) failed, 0x%x!\n", Status);
        return FALSE;
    }

    printf("XDP map config set (IfIndex=%u, MapHandle=0x%IX).\n\n", IfIndex, (UINT_PTR)MapHandle);
    return TRUE;
}

static
void
RunServer(
    _In_ const SERVER_ARGS* Args
    )
{
    QUIC_STATUS Status;
    HQUIC Listener = NULL;
    HQUIC Configuration = NULL;

    if (!LoadServerConfiguration(Args, &Configuration)) {
        return;
    }

    QUIC_ADDR Address = {0};
    QuicAddrSetFamily(&Address, QUIC_ADDRESS_FAMILY_UNSPEC);
    QuicAddrSetPort(&Address, UdpPort);

    if (QUIC_FAILED(Status = MsQuic->ListenerOpen(Registration, ServerListenerCallback, Configuration, &Listener))) {
        printf("ListenerOpen failed, 0x%x!\n", Status);
        goto Error;
    }

    if (Args->CibirIdHex != NULL) {
        uint8_t CibirId[XDPMAP_CIBIR_RAW_MAX_LEN];
        uint32_t CibirIdLen = XdpMapDecodeHexBuffer(Args->CibirIdHex, sizeof(CibirId), CibirId);
        if (CibirIdLen < 2) {
            printf("CIBIR ID too short (need offset + >=1 CID byte).\n");
            goto Error;
        }

        if (QUIC_FAILED(Status = MsQuic->SetParam(Listener, QUIC_PARAM_LISTENER_CIBIR_ID, CibirIdLen, CibirId))) {
            printf("SetParam(QUIC_PARAM_LISTENER_CIBIR_ID) failed, 0x%x!\n", Status);
            goto Error;
        }
    }

    if (QUIC_FAILED(Status = MsQuic->ListenerStart(Listener, &Alpn, 1, &Address))) {
        printf("ListenerStart failed, 0x%x!\n", Status);
        goto Error;
    }

    printf("Listening on UDP/%u with XDP map mode enabled.\n", UdpPort);
    printf("Press Enter to exit.\n");
    (void)getchar();

Error:
    if (Listener != NULL) {
        MsQuic->ListenerClose(Listener);
    }
    if (Configuration != NULL) {
        MsQuic->ConfigurationClose(Configuration);
    }
}

int
QUIC_MAIN_EXPORT
main(
    _In_ int argc,
    _In_reads_(argc) _Null_terminated_ char* argv[]
    )
{
    QUIC_STATUS Status = QUIC_STATUS_SUCCESS;

    if (GetFlag(argc, argv, "help") || GetFlag(argc, argv, "?")) {
        PrintUsage();
        return 0;
    }

    SERVER_ARGS Args;
    if (!ParseArgs(argc, argv, &Args)) {
        PrintUsage();
        return (int)QUIC_STATUS_INVALID_PARAMETER;
    }

    if (QUIC_FAILED(Status = MsQuicOpen2(&MsQuic))) {
        printf("MsQuicOpen2 failed, 0x%x!\n", Status);
        goto Error;
    }

    UINT_PTR MapHandleValue;
    if (!PromptForXdpMapHandle(&Args, &MapHandleValue)) {
        Status = QUIC_STATUS_INVALID_PARAMETER;
        goto Error;
    }

    if (!ConfigureXdpMap(Args.XdpMapIfIndex, (QUIC_XDP_MAP_HANDLE)MapHandleValue)) {
        Status = QUIC_STATUS_INVALID_PARAMETER;
        goto Error;
    }

    if (QUIC_FAILED(Status = MsQuic->RegistrationOpen(&RegConfig, &Registration))) {
        printf("RegistrationOpen failed, 0x%x!\n", Status);
        goto Error;
    }

    RunServer(&Args);

Error:
    if (MsQuic != NULL) {
        if (Registration != NULL) {
            MsQuic->RegistrationClose(Registration);
        }
        MsQuicClose(MsQuic);
    }

    return (int)Status;
}

_IRQL_requires_max_(PASSIVE_LEVEL)
QUIC_STATUS
QuicConnExportKeyingMaterial(
    _In_ QUIC_CONNECTION* Connection,
    _In_ const QUIC_KEYING_MATERIAL_CONFIG* Config,
    _Out_writes_bytes_(Config->OutputLength)
        uint8_t* Output
    )
{
    //
    // The keying material is derived from the connection's TLS secrets: the
    // handshake must be complete and the TLS context must still be present.
    //
    if (!Connection->State.Connected ||
        !Connection->Crypto.TlsState.HandshakeComplete ||
        Connection->Crypto.TLS == NULL) {
        QuicTraceLogConnWarning(
            ExportKeyingMaterialInvalidState,
            Connection,
            "Cannot export keying material [Connected=%hhu, HandshakeComplete=%hhu, HasTls=%hhu]",
            Connection->State.Connected,
            Connection->Crypto.TlsState.HandshakeComplete,
            (uint8_t)(Connection->Crypto.TLS != NULL));
        return QUIC_STATUS_INVALID_STATE;
    }

    return
        CxPlatTlsExportKeyingMaterial(
            Connection->Crypto.TLS,
            Config->Label,
            Config->Context,
            Config->ContextLength,
            Output,
            Config->OutputLength);
}

QUIC_STATUS
    ExportKeyingMaterial(
        _In_ const QUIC_KEYING_MATERIAL_CONFIG* Config,
        _Out_writes_bytes_(Config->OutputLength)
            uint8_t* Output
        ) noexcept {
        return MsQuic->ConnectionExportKeyingMaterial(Handle, Config, Output);
    }

_IRQL_requires_max_(PASSIVE_LEVEL)
QUIC_STATUS
CxPlatTlsExportKeyingMaterial(
    _In_ CXPLAT_TLS* TlsContext,
    _In_z_ const char* Label,
    _In_reads_bytes_opt_(ContextLength)
        const uint8_t* Context,
    _In_ uint32_t ContextLength,
    _Out_writes_bytes_(OutputLength)
        uint8_t* Output,
    _In_ uint32_t OutputLength
    )
{
    if (SSL_export_keying_material(
            TlsContext->Ssl,
            Output,
            OutputLength,
            Label,
            strlen(Label),
            Context,
            ContextLength,
            Context != NULL ? 1 : 0) != 1) {
        QuicTraceEvent(
            TlsError,
            "[ tls][%p] ERROR, %s.",
            TlsContext->Connection,
            "SSL_export_keying_material failed");
        return QUIC_STATUS_TLS_ERROR;
    }

    return QUIC_STATUS_SUCCESS;
}

_IRQL_requires_max_(PASSIVE_LEVEL)
QUIC_STATUS
CxPlatTlsExportKeyingMaterial(
    _In_ CXPLAT_TLS* TlsContext,
    _In_z_ const char* Label,
    _In_reads_bytes_opt_(ContextLength)
        const uint8_t* Context,
    _In_ uint32_t ContextLength,
    _Out_writes_bytes_(OutputLength)
        uint8_t* Output,
    _In_ uint32_t OutputLength
    )
{
    if (SSL_export_keying_material(
            TlsContext->Ssl,
            Output,
            OutputLength,
            Label,
            strlen(Label),
            Context,
            ContextLength,
            Context != NULL ? 1 : 0) != 1) {
        QuicTraceEvent(
            TlsError,
            "[ tls][%p] ERROR, %s.",
            TlsContext->Connection,
            "SSL_export_keying_material failed");
        return QUIC_STATUS_TLS_ERROR;
    }

    return QUIC_STATUS_SUCCESS;
}

_IRQL_requires_max_(PASSIVE_LEVEL)
QUIC_STATUS
CxPlatTlsExportKeyingMaterial(
    _In_ CXPLAT_TLS* TlsContext,
    _In_z_ const char* Label,
    _In_reads_bytes_opt_(ContextLength)
        const uint8_t* Context,
    _In_ uint32_t ContextLength,
    _Out_writes_bytes_(OutputLength)
        uint8_t* Output,
    _In_ uint32_t OutputLength
    )
{
#ifdef _KERNEL_MODE
    //
    // Exporting keying material relies on the SecPkgContext_KeyingMaterial[Info]
    // structures and the SECPKG_ATTR_KEYING_MATERIAL[_INFO] attributes, which
    // are only defined in the user-mode <schannel.h> and not available to
    // kernel-mode Schannel.
    //
    UNREFERENCED_PARAMETER(TlsContext);
    UNREFERENCED_PARAMETER(Label);
    UNREFERENCED_PARAMETER(Context);
    UNREFERENCED_PARAMETER(ContextLength);
    UNREFERENCED_PARAMETER(Output);
    UNREFERENCED_PARAMETER(OutputLength);
    return QUIC_STATUS_NOT_SUPPORTED;
#else
    QUIC_STATUS Status;
    SecPkgContext_KeyingMaterialInfo Info;
    SecPkgContext_KeyingMaterial Material;
    size_t LabelLength = strlen(Label);

    CxPlatZeroMemory(&Material, sizeof(Material));

    //
    // Schannel's label length (which includes the NUL terminator) and context
    // length are 16-bit fields, so validate they fit.
    //
    if (LabelLength == 0 || LabelLength + 1 > 0xFFFF || ContextLength > 0xFFFF) {
        Status = QUIC_STATUS_INVALID_PARAMETER;
        goto Error;
    }

    Info.cbLabel = (WORD)(LabelLength + 1);
    Info.pszLabel = (LPSTR)Label;
    Info.cbContextValue = (WORD)ContextLength;
    Info.pbContextValue = ContextLength != 0 ? (PBYTE)Context : NULL;
    Info.cbKeyingMaterial = OutputLength;

    Status =
        SecStatusToQuicStatus(
            SetContextAttributesW(
                &TlsContext->SchannelContext,
                SECPKG_ATTR_KEYING_MATERIAL_INFO,
                &Info,
                sizeof(Info)));
    if (QUIC_FAILED(Status)) {
        QuicTraceEvent(
            TlsErrorStatus,
            "[ tls][%p] ERROR, %u, %s.",
            TlsContext->Connection,
            Status,
            "Set keying material info");
        goto Error;
    }

    Status =
        SecStatusToQuicStatus(
            QueryContextAttributesW(
                &TlsContext->SchannelContext,
                SECPKG_ATTR_KEYING_MATERIAL,
                &Material));
    if (QUIC_FAILED(Status)) {
        QuicTraceEvent(
            TlsErrorStatus,
            "[ tls][%p] ERROR, %u, %s.",
            TlsContext->Connection,
            Status,
            "Query keying material");
        goto Error;
    }

    CXPLAT_DBG_ASSERT(Material.pbKeyingMaterial != NULL);
    CXPLAT_DBG_ASSERT(Material.cbKeyingMaterial == OutputLength);

    CxPlatCopyMemory(Output, Material.pbKeyingMaterial, OutputLength);
    Status = QUIC_STATUS_SUCCESS;

Error:

    if (Material.pbKeyingMaterial != NULL) {
        FreeContextBuffer(Material.pbKeyingMaterial);
    }

    return Status;
#endif // _KERNEL_MODE
}

TEST_F(TlsTest, ExportKeyingMaterial)
{
    CxPlatClientSecConfig ClientConfig;
    CxPlatServerSecConfig ServerConfig;
    TlsContext ServerContext, ClientContext;
    ClientContext.InitializeClient(ClientConfig);
    ServerContext.InitializeServer(ServerConfig);
    DoHandshake(ServerContext, ClientContext);

    const char* Label = "EXPORTER-MsQuicTest";
    const char* OtherLabel = "EXPORTER-Other";
    const uint8_t Context[] = { 1, 2, 3, 4, 5 };
    const uint8_t OtherContext[] = { 9, 8, 7, 6, 5 };
    const uint32_t Length = 32;

    uint8_t ServerKm[Length];
    uint8_t ClientKm[Length];

    //
    // Both peers derive identical material for the same label with no context.
    //
    ASSERT_EQ(
        QUIC_STATUS_SUCCESS,
        CxPlatTlsExportKeyingMaterial(
            ServerContext.Ptr, Label, nullptr, 0, ServerKm, Length));
    ASSERT_EQ(
        QUIC_STATUS_SUCCESS,
        CxPlatTlsExportKeyingMaterial(
            ClientContext.Ptr, Label, nullptr, 0, ClientKm, Length));
    ASSERT_EQ(0, memcmp(ServerKm, ClientKm, Length));

    //
    // Both peers derive identical material for the same label with a context,
    // and that material differs from the no-context result.
    //
    uint8_t ServerCtxKm[Length];
    uint8_t ClientCtxKm[Length];
    ASSERT_EQ(
        QUIC_STATUS_SUCCESS,
        CxPlatTlsExportKeyingMaterial(
            ServerContext.Ptr, Label, Context, sizeof(Context), ServerCtxKm, Length));
    ASSERT_EQ(
        QUIC_STATUS_SUCCESS,
        CxPlatTlsExportKeyingMaterial(
            ClientContext.Ptr, Label, Context, sizeof(Context), ClientCtxKm, Length));
    ASSERT_EQ(0, memcmp(ServerCtxKm, ClientCtxKm, Length));
    ASSERT_NE(0, memcmp(ClientKm, ClientCtxKm, Length));

    //
    // A different label yields different material.
    //
    uint8_t OtherKm[Length];
    ASSERT_EQ(
        QUIC_STATUS_SUCCESS,
        CxPlatTlsExportKeyingMaterial(
            ClientContext.Ptr, OtherLabel, nullptr, 0, OtherKm, Length));
    ASSERT_NE(0, memcmp(ClientKm, OtherKm, Length));

    //
    // A different context yields different material.
    //
    uint8_t OtherCtxKm[Length];
    ASSERT_EQ(
        QUIC_STATUS_SUCCESS,
        CxPlatTlsExportKeyingMaterial(
            ClientContext.Ptr, Label, OtherContext, sizeof(OtherContext), OtherCtxKm, Length));
    ASSERT_NE(0, memcmp(ClientCtxKm, OtherCtxKm, Length));
}

