_IRQL_requires_max_(PASSIVE_LEVEL)
static
QUIC_STATUS
CxPlatDpRawInsertXskInMap(
    _In_ XDP_INTERFACE* Interface,
    _In_ HANDLE XskMap
    )
{
    for (uint32_t j = 0; j < Interface->QueueCount; j++) {
        CXPLAT_QUEUE* Queue = &Interface->Queues[j];
        if (Queue->RxXsk == NULL) {
            continue;
        }
        HRESULT Hr = XdpMapInsert(XskMap, &j, &Queue->RxXsk);
        if (FAILED(Hr)) {
            QuicTraceLogVerbose(
                XdpMapInsertFailed,
                "[ixdp][%p] XdpMapInsert failed for IfIndex=%u, QueueId=%u, XskMap=%p, RxXsk=%p, Hr=0x%x",
                Interface,
                Interface->IfIndex,
                j,
                XskMap,
                Queue->RxXsk,
                Hr);
            //
            // On failure, best-effort removal of XSKs already inserted for this interface.
            //
            for (uint32_t k = 0; k < j; k++) {
                if (Interface->Queues[k].RxXsk != NULL) {
                    HRESULT DeleteHr = XdpMapDelete(XskMap, &k);
                    if (FAILED(DeleteHr)) {
                        QuicTraceLogVerbose(
                            XdpMapDeleteFailed,
                            "[ixdp][%p] XdpMapDelete failed for IfIndex=%u, QueueId=%u, XskMap=%p, RxXsk=%p, Hr=0x%x",
                            Interface,
                            Interface->IfIndex,
                            k,
                            XskMap,
                            Interface->Queues[k].RxXsk,
                            DeleteHr);
                    }
                }
            }
            return (QUIC_STATUS)Hr;
        }
    }
    Interface->XskMap = XskMap;
    return QUIC_STATUS_SUCCESS;
}

_IRQL_requires_max_(PASSIVE_LEVEL)
static
void
CxPlatDpRawRemoveXskFromMap(
    _In_ XDP_INTERFACE* Interface
    )
{
    if (Interface->XskMap == NULL) {
        return;
    }
    for (uint32_t j = 0; j < Interface->QueueCount; j++) {
        CXPLAT_QUEUE* Queue = &Interface->Queues[j];
        if (Queue->RxXsk == NULL) {
            continue;
        }
        HRESULT DeleteHr = XdpMapDelete(Interface->XskMap, &j);
        if (FAILED(DeleteHr)) {
            QuicTraceLogVerbose(
                XdpMapDeleteFailed,
                "[ixdp][%p] XdpMapDelete failed for IfIndex=%u, QueueId=%u, XskMap=%p, RxXsk=%p, Hr=0x%x",
                Interface,
                Interface->IfIndex,
                j,
                Interface->XskMap,
                Queue->RxXsk,
                DeleteHr);
        }
    }
    Interface->XskMap = NULL;
}

_IRQL_requires_max_(PASSIVE_LEVEL)
QUIC_STATUS
CxPlatDpRawApplyMapConfigs(
    _In_ CXPLAT_DATAPATH_RAW* RawDataPath,
    _In_reads_(MapConfigCount) const CXPLAT_XDP_MAP_CONFIG* MapConfigs,
    _In_ uint32_t MapConfigCount
    )
{
    XDP_DATAPATH* Xdp = (XDP_DATAPATH*)RawDataPath;
    QUIC_STATUS Status = QUIC_STATUS_SUCCESS;

    for (CXPLAT_LIST_ENTRY* Entry = Xdp->Interfaces.Flink; Entry != &Xdp->Interfaces; Entry = Entry->Flink) {
        XDP_INTERFACE* Interface = CONTAINING_RECORD(Entry, XDP_INTERFACE, Link);

        HANDLE XskMap = NULL;
        for (uint32_t i = 0; i < MapConfigCount; i++) {
            if (MapConfigs[i].InterfaceIndex == Interface->IfIndex) {
                XskMap = (HANDLE)MapConfigs[i].MapHandle;
                break;
            }
        }

        if (XskMap == NULL) {
            continue;
        }

        Status = CxPlatDpRawInsertXskInMap(Interface, XskMap);
        if (QUIC_FAILED(Status)) {
            //
            // On failure, best-effort removal of all XSKs on all interfaces.
            //
            CxPlatDpRawCleanupMapConfigs(RawDataPath);
            goto Exit;
        }
        QuicTraceLogVerbose(
            XdpMapModeConfigured,
            "[ixdp][%p] Map mode configured for IfIndex=%u (MapHandle=%p)",
            Interface,
            Interface->IfIndex,
            XskMap);
    }

Exit:

    return Status;
}

_IRQL_requires_max_(PASSIVE_LEVEL)
void
CxPlatDpRawCleanupMapConfigs(
    _In_ CXPLAT_DATAPATH_RAW* RawDataPath
    )
{
    XDP_DATAPATH* Xdp = (XDP_DATAPATH*)RawDataPath;

    for (CXPLAT_LIST_ENTRY* Entry = Xdp->Interfaces.Flink; Entry != &Xdp->Interfaces; Entry = Entry->Flink) {
        XDP_INTERFACE* Interface = CONTAINING_RECORD(Entry, XDP_INTERFACE, Link);
        CxPlatDpRawRemoveXskFromMap(Interface);
    }
}

uint32_t
CxPlatDpRawGetTotalRuleCount(
    _In_ const CXPLAT_DATAPATH_RAW* RawDataPath
    )
{
    const XDP_DATAPATH* Xdp = (const XDP_DATAPATH*)RawDataPath;
    uint32_t TotalRuleCount = 0;
    for (const CXPLAT_LIST_ENTRY* Entry = Xdp->Interfaces.Flink; Entry != &Xdp->Interfaces; Entry = Entry->Flink) {
        const XDP_INTERFACE* Interface = CONTAINING_RECORD(Entry, XDP_INTERFACE, Link);
        TotalRuleCount += Interface->RuleCount;
    }
    return TotalRuleCount;
}

static
QUIC_STATUS
RawOnlyDataPathInitialize(
    _In_ uint32_t ClientRecvContextLength,
    _In_ const CXPLAT_UDP_DATAPATH_CALLBACKS* UdpCallbacks,
    _In_ CXPLAT_WORKER_POOL* WorkerPool,
    _In_ const CXPLAT_DATAPATH_INIT_CONFIG* InitConfig,
    _Out_ CXPLAT_DATAPATH** NewDataPath
    )
{
    CXPLAT_DBG_ASSERT(InitConfig->XdpMapConfigs != NULL);

    CXPLAT_DATAPATH* Datapath =
        CXPLAT_ALLOC_PAGED(sizeof(CXPLAT_DATAPATH), QUIC_POOL_DATAPATH);
    if (Datapath == NULL) {
        QuicTraceEvent(
            AllocFailure,
            "Allocation of '%s' failed. (%llu bytes)",
            "CXPLAT_DATAPATH (raw-only)",
            sizeof(CXPLAT_DATAPATH));
        return QUIC_STATUS_OUT_OF_MEMORY;
    }
    CxPlatZeroMemory(Datapath, sizeof(CXPLAT_DATAPATH));
    Datapath->UdpHandlers = *UdpCallbacks;
    Datapath->WorkerPool = WorkerPool;

    RawDataPathInitialize(
        ClientRecvContextLength,
        Datapath,
        WorkerPool,
        InitConfig,
        &Datapath->RawDataPath);
    if (Datapath->RawDataPath == NULL) {
        QuicTraceLogVerbose(
            DatapathRawInitFailRawOnly,
            "[  dp] Raw-only mode: raw datapath required but failed to initialize");
        CXPLAT_FREE(Datapath, QUIC_POOL_DATAPATH);
        *NewDataPath = NULL;
        return QUIC_STATUS_NOT_SUPPORTED;
    }
    *NewDataPath = Datapath;
    return QUIC_STATUS_SUCCESS;
}

_IRQL_requires_max_(PASSIVE_LEVEL)
uint32_t
CxPlatDataPathGetXdpRuleCount(
    _In_ CXPLAT_DATAPATH* Datapath
    )
{
    if (Datapath->RawDataPath == NULL) {
        return 0;
    }
    return CxPlatDpRawGetTotalRuleCount(Datapath->RawDataPath);
    BOOLEAN IsRawDatapathOnly = CxPlatDpRawIsRawDatapathOnly(Datapath->RawDataPath);

    //
    // When the raw (XDP) datapath is the only datapath, create raw sockets for all cxplat sockets
    // and treat any failure as fatal (no fallback to OS sockets, no QTIP TCP port retry).
    //
    BOOLEAN CreateRaw = IsRawDatapathOnly || (Config->Flags & CXPLAT_SOCKET_FLAG_XDP);
        CXPLAT_DBG_ASSERT(!IsRawDatapathOnly || Datapath->RawDataPath);

                if (IsRawDatapathOnly) {
                    //
                    // Raw-only mode: no fallback allowed.
                    //
                    CxPlatSocketDelete(*NewSocket);
                    *NewSocket = NULL;
                    goto Error;
                }

TEST_F(DataPathTest, XdpMapMode_ZeroConfigUsesNormalPath)
{
    //
    // XdpMapConfigCount == 0 falls through to the normal initialization path.
    //
    CXPLAT_WORKER_POOL* WorkerPool =
        CxPlatWorkerPoolCreate(nullptr, CXPLAT_WORKER_POOL_REF_TOOL);
    ASSERT_NE(nullptr, WorkerPool);

    CXPLAT_DATAPATH_INIT_CONFIG InitConfig = {0};
    InitConfig.XdpMapConfigs = nullptr;
    InitConfig.XdpMapConfigCount = 0;

    CXPLAT_DATAPATH* Datapath = nullptr;
    QUIC_STATUS Status =
        CxPlatDataPathInitialize(
            0,
            &EmptyUdpCallbacks,
            nullptr,
            WorkerPool,
            &InitConfig,
            &Datapath);
    VERIFY_QUIC_SUCCESS(Status);
    ASSERT_NE(nullptr, Datapath);

    //
    // Normal path initializes the platform datapath, which reports features.
    // Raw-only mode skips platform init and features remain NONE.
    //
    CXPLAT_DATAPATH_FEATURES Features =
        CxPlatDataPathGetSupportedFeatures(Datapath, CXPLAT_SOCKET_FLAG_NONE);
    ASSERT_NE(CXPLAT_DATAPATH_FEATURE_NONE, Features);

    CxPlatDataPathUninitialize(Datapath);
    CxPlatWorkerPoolDelete(WorkerPool, CXPLAT_WORKER_POOL_REF_TOOL);
}

TEST_F(DataPathTest, XdpMapMode_InitFailsWithoutRawDatapath)
{
    //
    // Map mode is a hard failure without XDP/DuoNic (raw datapath required).
    //
    if (UseDuoNic) {
        GTEST_SKIP_NO_RETURN_("DuoNic is available; raw datapath will succeed");
        return;
    }

    const uint32_t FakeIfIndex = 0xDEAD;
    const QUIC_XDP_MAP_HANDLE FakeHandle = (QUIC_XDP_MAP_HANDLE)QUIC_INVALID_FILE_HANDLE;
    CXPLAT_XDP_MAP_CONFIG MapConfig = { FakeIfIndex, FakeHandle };

    CXPLAT_WORKER_POOL* WorkerPool =
        CxPlatWorkerPoolCreate(nullptr, CXPLAT_WORKER_POOL_REF_TOOL);
    ASSERT_NE(nullptr, WorkerPool);

    CXPLAT_DATAPATH_INIT_CONFIG InitConfig = {0};
    InitConfig.XdpMapConfigs = &MapConfig;
    InitConfig.XdpMapConfigCount = 1;

    CXPLAT_DATAPATH* Datapath = nullptr;
    QUIC_STATUS Status =
        CxPlatDataPathInitialize(
            0,
            &EmptyUdpCallbacks,
            nullptr,
            WorkerPool,
            &InitConfig,
            &Datapath);
    ASSERT_TRUE(QUIC_FAILED(Status));
    ASSERT_EQ(nullptr, Datapath);

    CxPlatWorkerPoolDelete(WorkerPool, CXPLAT_WORKER_POOL_REF_TOOL);
}

