std::vector<uint32_t>
DiscoverDuoNicInterfaces()
{
    std::vector<uint32_t> Result;
    ULONG Flags = GAA_FLAG_INCLUDE_PREFIX | GAA_FLAG_SKIP_ANYCAST |
                  GAA_FLAG_SKIP_MULTICAST | GAA_FLAG_SKIP_DNS_SERVER;
    ULONG BufSize = 0;
    GetAdaptersAddresses(AF_INET, Flags, NULL, NULL, &BufSize);
    if (BufSize == 0) {
        return Result;
    }

    std::vector<uint8_t> Buffer(BufSize);
    auto* Adapters = (IP_ADAPTER_ADDRESSES*)Buffer.data();

    if (GetAdaptersAddresses(AF_INET, Flags, NULL, Adapters, &BufSize) != NO_ERROR) {
        return Result;
    }

    QUIC_ADDR DuoNicServer = {};
    QUIC_ADDR DuoNicClient = {};
    QuicAddrFromString("192.168.1.11", 0, &DuoNicServer);
    QuicAddrFromString("192.168.1.12", 0, &DuoNicClient);

    for (auto* Adapter = Adapters;
         Adapter != nullptr && Result.size() < XDP_MAP_MODE_MAX_INTERFACES;
         Adapter = Adapter->Next) {

        if (Adapter->IfType != IF_TYPE_ETHERNET_CSMACD ||
            Adapter->OperStatus != IfOperStatusUp) {
            continue;
        }
        for (auto* Unicast = Adapter->FirstUnicastAddress; Unicast != nullptr; Unicast = Unicast->Next) {
            if (Unicast->Address.lpSockaddr->sa_family != AF_INET) {
                continue;
            }
            auto* Addr = (QUIC_ADDR*)Unicast->Address.lpSockaddr;
            if (QuicAddrCompareIp(Addr, &DuoNicServer) ||
                QuicAddrCompareIp(Addr, &DuoNicClient)) {
                Result.push_back(Adapter->IfIndex);
                break;
            }
        }
    }
    return Result;
}

XdpMapModeRuleScope::~XdpMapModeRuleScope()
{
    for (uint32_t i = 0; i < XdpMapState.InterfaceCount; i++) {
        for (uint32_t q = 0; q < QueueCounts[i]; q++) {
            if (XdpPrograms[i][q]) {
                CloseHandle(XdpPrograms[i][q]);
                XdpPrograms[i][q] = nullptr;
            }
        }
    }
    for (int i = 0; i < PortCount; i++) {
        if (PortSocksUdp[i] != INVALID_SOCKET) {
            closesocket(PortSocksUdp[i]);
            PortSocksUdp[i] = INVALID_SOCKET;
        }
        if (PortSocksTcp[i] != INVALID_SOCKET) {
            closesocket(PortSocksTcp[i]);
            PortSocksTcp[i] = INVALID_SOCKET;
        }
    }
    if (WsaInitialized) {
        WSACleanup();
    }
}

static ::std::vector<XdpMapModeArgs> Generate() {
        ::std::vector<XdpMapModeArgs> list;
        for (int Family : { 4, 6 })
        for (bool UseCibir : { false, true })
            list.push_back({ Family, 0, 0, UseCibir });
        return list;
    }

std::ostream& operator << (std::ostream& o, const XdpMapModeArgs& args) {
    return o <<
        (args.Family == 4 ? "v4" : "v6") << "/" <<
        (args.UseCibir ? "Cibir" : "NoCibir") << "/" <<
        "ServerPort:" << (args.ServerPort) << "/" <<
        "ClientPort:" << (args.ClientPort);
}

TEST_P(WithXdpMapModeArgs, Handshake) {

    if (TestingKernelMode) {
        GTEST_SKIP() << "QuicTestXdpMapModeHandshake doesn't apply to kernel mode.";
    }

    if (!UseXdpMapMode) {
        GTEST_SKIP() << "QuicTestXdpMapModeHandshake: XDP Map Mode not enabled (use --xdpMapMode)";
    }

    auto Params = GetParam();
    XdpMapModeRuleScope Scope(Params.UseCibir, UseQTIP);
    Params.ClientPort = Scope.GetClientPort();
    Params.ServerPort = Scope.GetServerPort();

    TestLoggerT<ParamType> Logger("QuicTestXdpMapModeHandshake", Params);

    QuicTestXdpMapModeHandshake(Params);
}

void
QuicTestXdpMapModeHandshake(
    const XdpMapModeArgs& Params
    )
{
    QUIC_ADDRESS_FAMILY QuicAddrFamily =
        (Params.Family == 4) ? QUIC_ADDRESS_FAMILY_INET : QUIC_ADDRESS_FAMILY_INET6;

    MsQuicRegistration Registration;
    TEST_TRUE(Registration.IsValid());

    MsQuicAlpn Alpn("MsQuicTest");

    MsQuicSettings Settings;
    Settings.SetPeerBidiStreamCount(1);
    Settings.SetIdleTimeoutMs(10000);

    MsQuicConfiguration ServerConfiguration(Registration, Alpn, Settings, ServerSelfSignedCredConfig);
    TEST_TRUE(ServerConfiguration.IsValid());

    MsQuicCredentialConfig ClientCredConfig;
    MsQuicConfiguration ClientConfiguration(Registration, Alpn, Settings, ClientCredConfig);
    TEST_TRUE(ClientConfiguration.IsValid());

    //
    // CIBIR ID in API format: {offset, id_byte0, ...}
    //
    const uint8_t CibirId[] = { 0 /* offset */, 4, 3, 2, 1 };
    const uint8_t CibirIdLength = sizeof(CibirId);

    UniquePtr<TestConnection> Server;
    ServerAcceptContext ServerAcceptCtx(&Server);
    TestListener Listener(Registration, ListenerAcceptConnection, ServerConfiguration);
    TEST_TRUE(Listener.IsValid());

    Listener.Context = &ServerAcceptCtx;
    if (Params.UseCibir) {
        TEST_QUIC_SUCCEEDED(Listener.SetCibirId(CibirId, CibirIdLength));
    }

    QuicAddr ServerLocalAddr(QuicAddrFamily);
    QuicAddrSetPort(&ServerLocalAddr.SockAddr, Params.ServerPort);
    TEST_QUIC_SUCCEEDED(Listener.Start(Alpn, &ServerLocalAddr.SockAddr));
    TEST_QUIC_SUCCEEDED(Listener.GetLocalAddr(ServerLocalAddr));

    TestConnection Client(Registration);
    TEST_TRUE(Client.IsValid());

    if (Params.UseCibir) {
        TEST_QUIC_SUCCEEDED(Client.SetShareUdpBinding(true));
        TEST_QUIC_SUCCEEDED(
            MsQuic->SetParam(
                Client.GetConnection(),
                QUIC_PARAM_CONN_CIBIR_ID,
                CibirIdLength,
                CibirId));
    }

    QuicAddr ClientLocalAddr(QuicAddrFamily);
    QuicAddrSetToDuoNicClient(&ClientLocalAddr.SockAddr);
    QuicAddrSetPort(&ClientLocalAddr.SockAddr, Params.ClientPort);
    TEST_QUIC_SUCCEEDED(Client.SetLocalAddr(ClientLocalAddr));

    QuicAddr RemoteAddr{QuicAddrGetFamily(&ServerLocalAddr.SockAddr), ServerLocalAddr.GetPort()};
    QuicAddrSetToDuoNic(&RemoteAddr.SockAddr);
    TEST_QUIC_SUCCEEDED(Client.SetRemoteAddr(RemoteAddr));

    TEST_QUIC_SUCCEEDED(
        Client.Start(
            ClientConfiguration,
            QuicAddrFamily,
            QUIC_LOCALHOST_FOR_AF(QuicAddrFamily),
            ServerLocalAddr.GetPort()));

    if (!Client.WaitForConnectionComplete()) {
        return;
    }
    TEST_TRUE(Client.GetIsConnected());

    TEST_NOT_EQUAL(nullptr, Server);
    if (!Server->WaitForConnectionComplete()) {
        return;
    }
    TEST_TRUE(Server->GetIsConnected());

    Client.Shutdown(QUIC_CONNECTION_SHUTDOWN_FLAG_NONE, 0);
}

QUIC_STATUS
TestListener::SetCibirId(
    _In_reads_(Length) const uint8_t* CibirId,
    _In_ uint8_t Length
    )
{
    return
        MsQuic->SetParam(
            QuicListener,
            QUIC_PARAM_LISTENER_CIBIR_ID,
            Length,
            CibirId);
}

_IRQL_requires_max_(PASSIVE_LEVEL)
void
QuicConnUpdateOperQueueDelay(
    _Inout_ QUIC_CONNECTION* Connection,
    _In_ const QUIC_OPERATION* Oper
    )
{
    uint32_t DelayUs = CxPlatTimeDiff32(Oper->QueueTimeUs, CxPlatTimeUs32());

    switch (Oper->Type) {

    case QUIC_OPER_TYPE_FLUSH_RECV:
        Connection->Stats.Schedule.ReceiveQueueDelayAvgUs =
            (uint32_t)CxPlatEwma(Connection->Stats.Schedule.ReceiveQueueDelayAvgUs, DelayUs, 8);
        Connection->Stats.Schedule.ReceiveQueueDelayMaxUs =
            CXPLAT_MAX(Connection->Stats.Schedule.ReceiveQueueDelayMaxUs, DelayUs);
        break;
    case QUIC_OPER_TYPE_FLUSH_SEND:
        Connection->Stats.Schedule.SendQueueDelayAvgUs =
            (uint32_t)CxPlatEwma(Connection->Stats.Schedule.SendQueueDelayAvgUs, DelayUs, 8);
        Connection->Stats.Schedule.SendQueueDelayMaxUs =
            CXPLAT_MAX(Connection->Stats.Schedule.SendQueueDelayMaxUs, DelayUs);
        break;
    default:
        break;
    }
}

TEST(ParameterValidation, ConnQueueDelayStatistics) {
    TestLogger Logger("QuicTestConnQueueDelayStatistics");
    if (TestingKernelMode) {
        ASSERT_TRUE(InvokeKernelTest(FUNC(QuicTestConnQueueDelayStatistics)));
    } else {
        QuicTestConnQueueDelayStatistics();
    }
}

void
QuicTestConnQueueDelayStatistics()
{
    MsQuicRegistration Registration;
    TEST_TRUE(Registration.IsValid());

    MsQuicAlpn Alpn("MsQuicTest");
    MsQuicSettings Settings;
    Settings.SetIdleTimeoutMs(10000);
    Settings.SetPeerBidiStreamCount(1);

    MsQuicConfiguration ServerConfiguration(Registration, Alpn, Settings, ServerSelfSignedCredConfig);
    TEST_TRUE(ServerConfiguration.IsValid());

    MsQuicCredentialConfig ClientCredConfig;
    MsQuicConfiguration ClientConfiguration(Registration, Alpn, Settings, ClientCredConfig);
    TEST_TRUE(ClientConfiguration.IsValid());

    UniquePtr<TestConnection> Server;
    TestListener Listener(Registration, ListenerAcceptCallback, ServerConfiguration);
    TEST_TRUE(Listener.IsValid());
    Listener.Context = &Server;
    TEST_QUIC_SUCCEEDED(Listener.Start(Alpn, Alpn.Length()));
    QuicAddr ServerLocalAddr;
    TEST_QUIC_SUCCEEDED(Listener.GetLocalAddr(ServerLocalAddr));

    {
        TestConnection Client(Registration);
        TEST_TRUE(Client.IsValid());

        TEST_QUIC_SUCCEEDED(
            Client.Start(
                ClientConfiguration,
                QuicAddrGetFamily(&ServerLocalAddr.SockAddr),
                QUIC_TEST_LOOPBACK_FOR_AF(
                    QuicAddrGetFamily(&ServerLocalAddr.SockAddr)),
                ServerLocalAddr.GetPort()));

        TEST_TRUE(Client.WaitForConnectionComplete());
        TEST_TRUE(Client.GetIsConnected());

        TEST_NOT_EQUAL(nullptr, Server);
        TEST_TRUE(Server->WaitForConnectionComplete());
        TEST_TRUE(Server->GetIsConnected());

        //
        // Send and receive some data.
        //
        UniquePtr<TestStream> Stream(
            Client.NewStream(
                nullptr,
                QUIC_STREAM_OPEN_FLAG_NONE,
                NEW_STREAM_START_SYNC));
        TEST_NOT_EQUAL(nullptr, Stream.get());
        TEST_TRUE(Stream->IsValid());
        TEST_TRUE(Stream->StartPing(100 * 1024));
        TEST_TRUE(Stream->WaitForSendShutdownComplete());

        //
        // Read the full V2 statistics and verify the new per-connection queue
        // delay fields are reported (i.e. the returned buffer covers them).
        //
        QUIC_STATISTICS_V2 Stats = {};
        uint32_t BufferLength = sizeof(Stats);
        TEST_QUIC_SUCCEEDED(
            MsQuic->GetParam(
                Client.GetConnection(),
                QUIC_PARAM_CONN_STATISTICS_V2,
                &BufferLength,
                &Stats));
        TEST_TRUE(BufferLength >= QUIC_STATISTICS_V2_SIZE_5);

        //
        // The sliding average can never exceed the observed maximum for any of
        // the queue delay metrics. This invariant holds regardless of timing.
        //
        TEST_TRUE(Stats.ConnectionQueueDelayAvgUs <= Stats.ConnectionQueueDelayMaxUs);
        TEST_TRUE(Stats.SendQueueDelayAvgUs <= Stats.SendQueueDelayMaxUs);
        TEST_TRUE(Stats.ReceiveQueueDelayAvgUs <= Stats.ReceiveQueueDelayMaxUs);
    }
}

