HTSNET_API hts_boolean SOCaddr_inetntoa_port_(char *namebuf, size_t namebuflen,
                                              SOCaddr *const ss,
                                              const char *file,
                                              const int line) {
  const size_t reserved = sizeof(":65535") - 1;
  size_t used;

  assertf_(namebuf != NULL && namebuflen != 0, file, line);
  namebuf[0] = '\0';
  if (namebuflen <= reserved)
    return HTS_FALSE;
  SOCaddr_inetntoa_(namebuf, namebuflen - reserved, ss, file, line);
  used = strlen(namebuf);
  return slcatprintfbuff(
      namebuf, namebuflen, &used, ":%u",
      (unsigned int) ntohs(*SOCaddr_sinport_(ss, file, line)));
}

static hts_boolean st_addrport_intact(const char *p, size_t n) {
  size_t i;

  for (i = 0; i < n; i++) {
    if (p[i] != 'Z')
      return HTS_FALSE;
  }
  return HTS_TRUE;
}

static void st_addrport_longest(SOCaddr *addr, int family, unsigned int port) {
  (void) family;
  memset(addr, 0, sizeof(*addr));
#if HTS_INET6 != 0
  if (family == AF_INET6) {
    addr->m_addr.in6.sin6_family = AF_INET6;
    memset(&addr->m_addr.in6.sin6_addr, 0xff,
           sizeof(addr->m_addr.in6.sin6_addr));
  } else
#endif
  {
    addr->m_addr.in.sin_family = AF_INET;
    memset(&addr->m_addr.in.sin_addr, 0xff, sizeof(addr->m_addr.in.sin_addr));
  }
  SOCaddr_initport(*addr, port);
}

static void st_addrport_case(int family, unsigned int port,
                             const char *expected) {
  const size_t guard = 16;
  const size_t reserved = sizeof(":65535") - 1;
  const size_t full = SOCADDR_INETNTOA_PORT_SIZE;
  char *arena = malloct(full + guard);
  char wantport[8];
  SOCaddr addr;
  size_t size;

  assertf(arena != NULL);
  st_addrport_longest(&addr, family, port);
  snprintf(wantport, sizeof(wantport), ":%u", port);

  /* the declared capacity holds the longest host AND the longest port */
  memset(arena, 'Z', full + guard);
  assertf(SOCaddr_inetntoa_port(arena, full, addr));
  assertf(strcmp(arena, expected) == 0);
  assertf(st_addrport_intact(arena + full, guard));

  /* no capacity is written past, and none silently drops the port, which is
     what a host let loose on the whole buffer does */
  for (size = 1; size <= full; size++) {
    const hts_boolean ok = SOCaddr_inetntoa_port(arena, size, addr);

    memset(arena, 'Z', full + guard);
    (void) SOCaddr_inetntoa_port(arena, size, addr);
    /* before strlen, or a run with no terminator reads off the allocation */
    assertf(memchr(arena, '\0', size) != NULL);
    assertf(strlen(arena) < size);
    assertf(st_addrport_intact(arena + size, full + guard - size));
    if (size <= reserved) {
      /* too small for the port at all: refuse, rather than clip it to "6553" */
      assertf(!ok);
      assertf(arena[0] == '\0');
    } else {
      assertf(strstr(arena, wantport) != NULL);
    }
  }
  freet(arena);
}

static int st_addrport(httrackp *opt, int argc, char **argv) {
  (void) opt;
  (void) argc;
  (void) argv;
  st_addrport_case(AF_INET, 65535, "255.255.255.255:65535");
  /* 65535 is byte-swap invariant, so a dropped ntohs() needs this one */
  st_addrport_case(AF_INET, 8080, "255.255.255.255:8080");
#if HTS_INET6 != 0
  st_addrport_case(AF_INET6, 65535,
                   "ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff:65535");
  st_addrport_case(AF_INET6, 8080,
                   "ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff:8080");
#endif
  printf("addrport self-test OK\n");
  return 0;
}

static void lowcase(char *s) {
  size_t i;

  for (i = 0; s[i] != '\0'; i++)
    if ((s[i] >= 'A') && (s[i] <= 'Z'))
      s[i] += ('a' - 'A');
}

struct tm *convert_time_rfc822(struct tm *result, const char *s) {
  char months[] = "jan feb mar apr may jun jul aug sep oct nov dec";
  char str[256];
  char *a;

  /* The numbers in order of appearance, dd first. n1..n4 are then year, hour,
     min, sec, or hour, min, sec, year when n4 is four digits. */
  int result_mm = -1;
  int result_dd = -1;
  int result_n1 = -1;
  int result_n2 = -1;
  int result_n3 = -1;
  int result_n4 = -1;

  if ((int) strlen(s) > 200)
    return NULL;
  strcpybuff(str, s);
  lowcase(str);

  while ((a = strchr(str, '-')))
    *a = ' ';
  while ((a = strchr(str, ':')))
    *a = ' ';
  while ((a = strchr(str, ',')))
    *a = ' ';
  /* tokenise */
  a = str;
  while (*a) {
    char *first, *last;
    char tok[256];

    while (*a == ' ')
      a++;
    first = a;
    while ((*a) && (*a != ' '))
      a++;
    last = a;
    tok[0] = '\0';
    if (first != last) {
      char *pos;

      strncatbuff(tok, first, (int) (last - first));
      /* classify it */
      if ((pos = strstr(months, tok))) { /* month always in letters */
        result_mm = ((int) (pos - months)) / 4;
      } else {
        int number;

        if (sscanf(tok, "%d", &number) == 1) { /* number token */
          if (result_dd < 0)                   /* day always first number */
            result_dd = number;
          else if (result_n1 < 0)
            result_n1 = number;
          else if (result_n2 < 0)
            result_n2 = number;
          else if (result_n3 < 0)
            result_n3 = number;
          else if (result_n4 < 0)
            result_n4 = number;
        } /* anything else is noise, "+1GMT" for example */
      }
    }
  }
  if ((result_n1 >= 0) && (result_mm >= 0) && (result_dd >= 0) &&
      (result_n2 >= 0) && (result_n3 >= 0) && (result_n4 >= 0)) {
    if (result_n4 >= 1000) { /* Sun Nov  6 08:49:37 1994 */
      result->tm_year = result_n4 - 1900;
      result->tm_hour = result_n1;
      result->tm_min = result_n2;
      result->tm_sec = result_n3 > 0 ? result_n3 : 0;
    } else { /* Sun, 06 Nov 1994 08:49:37 GMT or Sunday, 06-Nov-94 08:49:37 GMT
              */
      result->tm_hour = result_n2;
      result->tm_min = result_n3;
      result->tm_sec = result_n4 > 0 ? result_n4 : 0;
      if (result_n1 <= 50) /* 00 means 2000 */
        result->tm_year = result_n1 + 100;
      else if (result_n1 < 1000) /* 99 means 1999 */
        result->tm_year = result_n1;
      else /* 2000 */
        result->tm_year = result_n1 - 1900;
    }
    result->tm_isdst = 0; /* assume GMT */
    result->tm_yday = -1; /* don't know */
    result->tm_wday = -1; /* don't know */
    result->tm_mon = result_mm;
    result->tm_mday = result_dd;
    return result;
  }
  return NULL;
}

