static int seekfail_capped(int64_t offset) {
  const char *const cap = getenv("SEEKFAIL_CAP");
  const char *const kind = getenv("SEEKFAIL_ERROR");
  char *end;

  /* a cap that is not a number would otherwise read as zero and refuse
   * everything */
  if (cap == NULL || *cap == '\0') {
    return 0;
  }
  if (offset <= (int64_t) strtoll(cap, &end, 10) || *end != '\0') {
    return 0;
  }
  errno = kind != NULL && strcmp(kind, "eio") == 0 ? EIO : EFBIG;
  return 1;
}

SHIM_EXPORT int fseeko(FILE *stream, off_t offset, int whence) {
  static int (*real_fseeko)(FILE *, off_t, int) = NULL;

  if (whence == SEEK_SET && seekfail_capped((int64_t) offset)) {
    return -1;
  }
  if (real_fseeko == NULL) {
    *(void **) &real_fseeko = dlsym(RTLD_NEXT, "fseeko");
    if (real_fseeko == NULL) {
      errno = ENOSYS;
      return -1;
    }
  }
  return real_fseeko(stream, offset, whence);
}

SHIM_EXPORT int fseeko64(FILE *stream, int64_t offset, int whence) {
  static int (*real_fseeko64)(FILE *, int64_t, int) = NULL;

  if (whence == SEEK_SET && seekfail_capped(offset)) {
    return -1;
  }
  if (real_fseeko64 == NULL) {
    *(void **) &real_fseeko64 = dlsym(RTLD_NEXT, "fseeko64");
    if (real_fseeko64 == NULL) {
      errno = ENOSYS;
      return -1;
    }
  }
  return real_fseeko64(stream, offset, whence);
}

unsigned int hts_print_num(char *buffer, int num) {
  const int neg = num < 0;
  /* negate in unsigned: INT_MIN has no positive counterpart */
  unsigned int val = neg ? -(unsigned int) num : (unsigned int) num;
  unsigned int i, j;

  if (neg) {
    *(buffer++) = '-';
  }
  for (i = 0; val != 0 || i == 0; i++, val /= 10) {
    buffer[i] = '0' + (val % 10);
  }
  /* j stops at i/2: going to i swaps each pair twice and undoes the reversal */
  for (j = 0; j < i / 2; j++) {
    const char c = buffer[i - j - 1];
    buffer[i - j - 1] = buffer[j];
    buffer[j] = c;
  }
  buffer[i] = '\0';
  return i + (unsigned int) neg;
}

int main(int argc, char **argv) {
  int i;

  for (i = 1; i < argc; i++) {
    char buf[64];
    char *end;
    const long value = strtol(argv[i], &end, 10);
    unsigned int len;

    if (*end != '\0') {
      fprintf(stderr, "printnumprobe: '%s' is not a number\n", argv[i]);
      return 1;
    }
    /* poisoned, so a stray terminator one past the end is visible */
    memset(buf, 'X', sizeof(buf));
    len = hts_print_num(buf, (int) value);
    if (len >= sizeof(buf) - 2) {
      fprintf(stderr, "printnumprobe: '%s' wrote %u bytes\n", argv[i], len);
      return 1;
    }
    if (buf[len] != '\0' || buf[len + 1] != 'X') {
      fprintf(stderr, "printnumprobe: '%s' wrote past its %u bytes\n", argv[i],
              len);
      return 1;
    }
    printf("%u:%s\n", len, buf);
  }
  return 0;
}

static const char *skip_separators(const char *p) {
  for (;;) {
    if (*p == '/')
      p++;
    else if (p[0] == '.' && p[1] == '/')
      p += 2;
    else
      return p;
  }
}

static hts_boolean is_wizard_pane(const char *file) {
  const char *page;

  file = skip_separators(file);
  if (strfield(file, "server/") == 0)
    return HTS_FALSE;
  page = skip_separators(file + 7);
  return strcmpnocase(page, "about.html") != 0;
}

static void optparam_error(optparam_state state, const char *spelling,
                           const char *real, const char *next,
                           char *return_error, size_t return_error_size) {
  const int pos = optreal_find(real);
  char help[256];

  /* by long name: optalias_help() looks the short form up in vain */
  optalias_help_line(help, sizeof(help),
                     pos >= 0 ? hts_optalias[pos][0] : real);
  if (state == OPTPARAM_ABSENT)
    slprintfbuff_clip(return_error, return_error_size,
                      "Syntax error:\n\tOption %s needs to be followed by a "
                      "parameter: %s <param>\n%s",
                      spelling, spelling, help);
  else if (optreal_or_alias(next))
    slprintfbuff_clip(return_error, return_error_size,
                      "Syntax error:\n\tOption %s takes a value, and the next "
                      "word \"%s\" names an option\n%s",
                      spelling, next, help);
  else
    slprintfbuff_clip(return_error, return_error_size,
                      "Syntax error:\n\tOption %s takes a value, and the next "
                      "word \"%s\" begins with '-', so it was read as the next "
                      "option\n%s",
                      spelling, next, help);
}

void cache_keep_previous(httrackp *opt, cache_back *cache, const char *url_adr,
                         const char *url_fil, const char *url_save) {
  char BIGSTK previous_save[HTS_URLMAXSIZE * 2];
  htsblk r;

  if (!opt->cache || !cache_writable(cache) || url_save == NULL ||
      !strnotempty(url_save) || IS_DELAYED_EXT(url_save))
    return;
  if (cache->kept != NULL) {
    const char *const key =
        concat(OPT_GET_BUFF(opt), OPT_GET_BUFF_SIZE(opt), url_adr, url_fil);

    if (coucal_read(cache->kept, key, NULL) != 0)
      return; /* another attempt at the same link already stored it */
    coucal_add(cache->kept, key, 1);
  }
  /* Headers only: a kept entry carries no body, so nothing is read from the
     previous cache or from disk, whatever the file's size. */
  previous_save[0] = '\0';
  r = cache_readex_(opt, cache, url_adr, url_fil, NULL, NULL, previous_save, 1,
                    HTS_TRUE);
  /* The entry must name this very file: fexist() upstream proves only that
     something occupies the name, which a collision flip fills with another
     URL's file. */
  if (r.statuscode > 0 && strcmp(previous_save, url_save) == 0) {
    hts_log_print(opt, LOG_DEBUG, "keeping the previous cache entry for %s%s",
                  url_adr, url_fil);
    cache_add_ex(opt, cache, &r, url_adr, url_fil, url_save, opt->all_in_cache,
                 StringBuff(opt->path_html_utf8), HTS_TRUE);
  }
}

void cache_add(httrackp *opt, cache_back *cache, const htsblk *r,
               const char *url_adr, const char *url_fil, const char *url_save,
               int all_in_cache, const char *path_prefix) {
  cache_add_ex(opt, cache, r, url_adr, url_fil, url_save, all_in_cache,
               path_prefix, HTS_FALSE);
}

htsblk cache_readex(httrackp *opt, cache_back *cache, const char *adr,
                    const char *fil, const char *save, char *location,
                    char *return_save, int readonly) {
  return cache_readex_(opt, cache, adr, fil, save, location, return_save,
                       readonly, HTS_FALSE);
}

static hts_boolean st_getext_case(char *arena, size_t cap, size_t guard,
                                  const char *fil, const char *want) {
  hts_boolean ok = HTS_TRUE;
  const char *ext;
  size_t from;

  memset(arena, ST_POISON, cap + guard);
  ext = get_ext(arena, cap, fil);
  /* every check runs: a wrong answer must not stop the canary from reporting */
  if (strcmp(ext, want) != 0) {
    fprintf(stderr, "getext: [%s] in %d bytes gave [%s], wanted [%s]\n", fil,
            (int) cap, ext, want);
    ok = HTS_FALSE;
  }
  /* the answer is built in the caller's buffer, and only the refusal is not */
  if ((ext == arena) != (*want != '\0')) {
    fprintf(stderr, "getext: [%s] in %d bytes answered from the wrong buffer\n",
            fil, (int) cap);
    ok = HTS_FALSE;
  }
  /* an extension that did not fit leaves the whole arena poisoned; one that
     fitted ends on its own NUL */
  from = ext == arena ? strlen(ext) + 1 : 0;
  if (!st_poison_intact("getext: inside the destination", arena, from, cap))
    ok = HTS_FALSE;
  if (!st_poison_intact("getext: past the destination", arena, cap,
                        cap + guard))
    ok = HTS_FALSE;
  return ok;
}

static int st_getext(httrackp *opt, int argc, char **argv) {
  static const struct {
    const char *fil;
    const char *want;
  } cases[] = {
      {"x.php", "php"},
      {"x.php?id=3", "php"},
      /* the query is not scanned for dots */
      {"x.php?id=3.txt", "php"},
      {"/a/b.c?Q123456789012345678901234567890", "c"},
      {"x.PHP?a", "PHP"}, /* no case folding */
      {"x.php?", "php"},
      {"foo", ""},
      {"x.", ""},
      {"?x.php", ""},
  };

  /* dodging sizeof(void *), which RUNTIME_TIME_CHECK_SIZE takes for a caller
     that passed sizeof() of a pointer */
  static const size_t caps[] = {1, 2, 3, 5, 6, 16, 64};
  /* longer than any capacity below, so a size-bounded copy runs off the end */
  static const char query[] = "?q=00000000001111111111222222222233333333334"
                              "4444444445555555555666666666677777777778888";
  const size_t guard = 64;
  size_t c, k;
  int rc = 0;

  (void) opt;
  (void) argc;
  (void) argv;

  /* the semantics, in a destination nothing here comes close to filling */
  {
    char *arena = malloct(256 + guard);

    assertf(arena != NULL);
    for (k = 0; k < sizeof(cases) / sizeof(cases[0]); k++) {
      if (!st_getext_case(arena, 256, guard, cases[k].fil, cases[k].want))
        rc = 1;
    }
    freet(arena);
  }

  /* the point of the query half: a parameterised URL types as the bare one */
  {
    char buf[16];

    if (!is_dyntype(get_ext(buf, sizeof(buf), "x.php?id=3")) ||
        !is_dyntype(get_ext(buf, sizeof(buf), "x.php"))) {
      fprintf(stderr, "getext: a parameterised .php is not a dynamic type\n");
      rc = 1;
    }
  }

  /* every capacity against extensions straddling its bound, with and without a
     query behind them: a one-size-fits-all bound shows up as the wrong verdict
     on the small ones */
  for (c = 0; c < sizeof(caps) / sizeof(caps[0]); c++) {
    const size_t cap = caps[c];
    const size_t maxext = cap + guard;
    char *arena = malloct(cap + guard);
    char *fil = malloct(5 + maxext + sizeof(query));
    char *want = malloct(maxext + 1);

    assertf(arena != NULL && fil != NULL && want != NULL);
    for (k = 1; k <= maxext; k++) {
      size_t i;

      /* bytes that vary, or a copy taken from the wrong offset would match */
      memcpy(fil, "/d/f.", 5);
      for (i = 0; i < k; i++)
        fil[5 + i] = (char) ('a' + i % 26);
      fil[5 + k] = '\0';
      memcpy(want, fil + 5, k + 1);
      if (k >= cap) /* k characters plus the NUL do not fit */
        want[0] = '\0';
      if (!st_getext_case(arena, cap, guard, fil, want))
        rc = 1;
      memcpy(fil + 5 + k, query, sizeof(query));
      if (!st_getext_case(arena, cap, guard, fil, want))
        rc = 1;
    }
    freet(arena);
    freet(fil);
    freet(want);
  }

  printf("getext self-test %s\n", rc == 0 ? "OK" : "FAILED");
  return rc;
}

static void st_mirror_wiring(httrackp *opt, struct_back **sback,
                             hash_struct *hash, hts_boolean backing) {
  *sback = backing ? back_new(opt, opt->maxsoc * 32 + 1024) : NULL;
  hash_init(opt, hash, opt->urlhack);
  hash->liens = (const lien_url *const *const *) &opt->liens;
  opt->hash = hash;
  hts_record_init(opt);
}

static void st_cache_close(httrackp *opt, cache_back *cache) {
  if (cache->zipOutput != NULL) {
    zipClose(cache->zipOutput, NULL);
    cache->zipOutput = NULL;
  }
  if (cache->zipInput != NULL) {
    unzClose(cache->zipInput);
    cache->zipInput = NULL;
  }
  if (cache->lst != NULL) {
    fclose(cache->lst);
    cache->lst = opt->state.strc.lst = NULL;
  }
  if (cache->txt != NULL) {
    fclose(cache->txt);
    cache->txt = NULL;
  }
  if (cache->hashtable != NULL)
    coucal_delete(&cache->hashtable);
}

static void st_mirror_wiring_free(httrackp *opt, cache_back *cache,
                                  struct_back **sback, hash_struct *hash) {
  hts_record_free(opt);
  back_free(sback);
  st_cache_close(opt, cache);
  hash_free(hash);
  opt->hash = NULL; /* it pointed at the caller's stack frame */
}

