static int st_nobestfit(httrackp *opt, int argc, char **argv) {
#ifdef _WIN32
  /* internal, not in htscharset.h: ties cp below to cs by name, not by guess */
  extern UINT hts_getCodepage(const char *name);
  static const char *const yen = "\xC2\xA5";      /* U+00A5 */
  static const char *const micro = "\xC2\xB5";    /* U+00B5, best-fit 83 CA */
  static const char *const hira = "\xE3\x81\x82"; /* U+3042, CP932 82 A0 */
  /* yen + micro + hira + ASCII: a best-fit-shorter, a best-fit-longer, a
     native and an untouched code point in one string */
  static const char *const mixed = "\xC2\xA5\xC2\xB5\xE3\x81\x82"
                                   "A";
  const char *const cs = "shift_jis";
  const UINT cp = hts_getCodepage(cs);
  BOOL usedDefault = TRUE;
  BOOL gotCpInfo;
  CPINFO cpi;
  WCHAR wide[4];
  char raw[8];
  char *s;
  int wn, n;

  (void) opt;
  (void) argc;
  (void) argv;
  assertf(cp == 932);
  if (!IsValidCodePage(cp)) {
    printf("nobestfit: CP932 is not installed\n");
    return 77;
  }
  /* the trap, asserted rather than assumed: left to itself the codepage hands
     back a path separator and reports no substitution at all */
  wn = MultiByteToWideChar(CP_UTF8, 0, yen, (int) strlen(yen), wide,
                           (int) (sizeof(wide) / sizeof(wide[0])));
  assertf(wn == 1);
  n = WideCharToMultiByte(cp, 0, wide, wn, raw, (int) sizeof(raw), NULL,
                          &usedDefault);
  assertf(n == 1 && raw[0] == '\\' && !usedDefault);
  /* U+00B5 best-fits to two bytes where the substitute is one, so a flag
     carried by only one of the two calls shows up as a length disagreement */
  wn = MultiByteToWideChar(CP_UTF8, 0, micro, (int) strlen(micro), wide,
                           (int) (sizeof(wide) / sizeof(wide[0])));
  assertf(wn == 1);
  n = WideCharToMultiByte(cp, 0, wide, wn, raw, (int) sizeof(raw), NULL, NULL);
  assertf(n == 2);
  /* the sizing passes disagree, and the shorter one under-allocates: banning
     best-fit sizes to the substitute but converts into room for the best-fit */
  n = WideCharToMultiByte(cp, WC_NO_BEST_FIT_CHARS, wide, wn, NULL, 0, NULL,
                          NULL);
  assertf(n == 1);
  /* same disagreement, summed over 4 code points instead of 1: a flag gated
     on wsize==1 would leave yen/micro best-fit instead of substituted here */
  wn = MultiByteToWideChar(CP_UTF8, 0, mixed, (int) strlen(mixed), wide,
                           (int) (sizeof(wide) / sizeof(wide[0])));
  assertf(wn == 4);
  n = WideCharToMultiByte(cp, 0, wide, wn, NULL, 0, NULL, NULL);
  assertf(n == 6); /* yen 1 + micro best-fit 2 + hira 2 + 'A' 1 */
  n = WideCharToMultiByte(cp, WC_NO_BEST_FIT_CHARS, wide, wn, NULL, 0, NULL,
                          NULL);
  assertf(n == 5); /* yen 1 + micro default 1 + hira 2 + 'A' 1 */
  /* control: banning best-fit must not break what the codepage does hold */
  s = hts_convertStringFromUTF8Strict(hira, strlen(hira), cs);
  assertf(s != NULL);
  assertf(strcmp(s, "\x82\xA0") == 0);
  freet(s);
  s = hts_convertStringFromUTF8Strict(yen, strlen(yen), cs);
  assertf(s == NULL);
  /* the non-strict caller still substitutes, but with the codepage's own
     default character rather than a lookalike */
  gotCpInfo = GetCPInfo(cp, &cpi);
  assertf(gotCpInfo);
  s = hts_convertStringFromUTF8(yen, strlen(yen), cs);
  assertf(s != NULL);
  assertf(s[0] == (char) cpi.DefaultChar[0] && s[1] == '\0');
  freet(s);
  s = hts_convertStringFromUTF8Strict(micro, strlen(micro), cs);
  assertf(s == NULL);
  s = hts_convertStringFromUTF8(micro, strlen(micro), cs);
  assertf(s != NULL);
  assertf(s[0] == (char) cpi.DefaultChar[0] && s[1] == '\0');
  freet(s);
  /* the mixed string, asserted byte-exact: both mutants above would either
     mis-size the buffer (undersized usize) or mis-gate flags (best-fit
     leaking through for a >1 code point string), and either shows up here */
  s = hts_convertStringFromUTF8Strict(mixed, strlen(mixed), cs);
  assertf(s == NULL); /* yen and micro are both lossy */
  s = hts_convertStringFromUTF8(mixed, strlen(mixed), cs);
  assertf(s != NULL);
  assertf(s[0] == (char) cpi.DefaultChar[0]);
  assertf(s[1] == (char) cpi.DefaultChar[0]);
  assertf((unsigned char) s[2] == 0x82 && (unsigned char) s[3] == 0xA0);
  assertf(s[4] == 'A' && s[5] == '\0');
  freet(s);
  /* the other arm of the gate: a codepage that refuses a non-zero dwFlags must
     still convert, so UTF-7 encodes the yen instead of failing */
  s = hts_convertStringFromUTF8(yen, strlen(yen), "utf-7");
  assertf(s != NULL && s[0] == '+');
  freet(s);
  printf("nobestfit: OK\n");
  return 0;
#else
  (void) opt;
  (void) argc;
  (void) argv;
  return 77; /* WIN32-only entry point */
#endif
}

static void back_report_write_failure(httrackp *opt, lien_back *const back) {
  const hts_boolean fatal = check_fatal_io_errno() ? HTS_TRUE : HTS_FALSE;

  /* the read path already named and classed a write error it saw itself */
  if (!statuscode_is_write_error(back->r.statuscode)) {
    hts_log_print(opt, LOG_ERROR | LOG_ERRNO, "Unable to write file %s",
                  back->url_sav);
    /* a slot still claiming success would be cached as mirrored; a
       STATUSCODE_INVALID must survive, the decode site's purge rests on it */
    if (back->r.statuscode > 0) {
      back->r.statuscode = fatal ? STATUSCODE_IO_FATAL : STATUSCODE_IO_ERROR;
      strcpybuff(back->r.msg, "Write error on disk");
    }
  }
  if (fatal && opt->state.exit_xh == 0) {
    hts_log_print(opt, LOG_ERROR,
                  "Mirror aborted: disk full or filesystem problems");
    opt->state.exit_xh = -1;
  }
}

static void classify_write_error(htsblk *r) {
  r->statuscode =
      check_fatal_io_errno() ? STATUSCODE_IO_FATAL : STATUSCODE_IO_ERROR;
  strcpybuff(r->msg, "Write error on disk");
}

static int st_codecerrno(httrackp *opt, int argc, char **argv) {
  static const unsigned char body[] = "codec errno contract, round-tripped";
  const size_t len = sizeof(body) - 1;
  char inpath[HTS_URLMAXSIZE], outpath[HTS_URLMAXSIZE];
  FILE *fp;

  (void) opt;
  if (argc < 2) {
    fprintf(stderr, "usage: -#test=codecerrno <dir> <doomed-out>\n");
    return 1;
  }
  snprintf(inpath, sizeof(inpath), "%s/ce-in.z", argv[0]);
  snprintf(outpath, sizeof(outpath), "%s/ce-out", argv[0]);
  assertf(ae_write_packed(inpath, 16 + MAX_WBITS, body, len) == 0);
  errno = ENOSPC;
  assertf(hts_zunpack(inpath, outpath) == (int) len);
  errno = 0;
  assertf(hts_zunpack(inpath, argv[1]) == -1);
  assertf(errno == ENOSPC);
  errno = 0;
  assertf(hts_codec_unpack(HTS_CODEC_DEFLATE, inpath, argv[1]) == -1);
  assertf(errno == ENOSPC);
  errno = ENOSPC;
  assertf(hts_codec_unpack(HTS_CODEC_UNSUPPORTED, inpath, outpath) == -1);
  assertf(errno == 0);
  /* Past the gzip magic, so the header still parses and the identity fallback
     stays out of it: the stream itself is what fails. */
  fp = FOPEN(inpath, "r+b");
  assertf(fp != NULL);
  assertf(fseek(fp, 12, SEEK_SET) == 0);
  assertf(hts_fwrite_exact("\xff\xff\xff\xff\xff\xff\xff\xff", 8, fp));
  assertf(fclose(fp) == 0);
  errno = ENOSPC;
  assertf(hts_zunpack(inpath, outpath) == -1);
  assertf(errno == 0);
  errno = ENOSPC;
  assertf(hts_codec_unpack(HTS_CODEC_DEFLATE, inpath, outpath) == -1);
  assertf(errno == 0);
#if HTS_USEBROTLI
  /* and a backend of its own, where the write goes through codec_sink() */
  assertf(ae_write_raw(inpath, cc_br_text, sizeof(cc_br_text)) == 0);
  errno = 0;
  assertf(hts_codec_unpack(HTS_CODEC_BROTLI, inpath, argv[1]) == -1);
  assertf(errno == ENOSPC);
  assertf(ae_write_raw(inpath, cc_br_text, sizeof(cc_br_text) - 4) == 0);
  errno = ENOSPC;
  assertf(hts_codec_unpack(HTS_CODEC_BROTLI, inpath, outpath) == -1);
  assertf(errno == 0);
#endif
  printf("codecerrno: write failure kept, refused stream cleared\n");
  return 0;
}

static hts_boolean optalias_clusters(const char *type, const char *command) {
  size_t i;

  if (strcmp(type, "single") != 0 && strcmp(type, "onoff") != 0 &&
      strcmp(type, "level") != 0)
    return HTS_FALSE;
  if (command[0] != '-' || command[1] == '\0' || strcmp(command, "-h") == 0)
    return HTS_FALSE;
  for (i = 1; command[i] != '\0'; i++) {
    if (command[i] == 'c' || !isalnum((unsigned char) command[i]))
      return HTS_FALSE;
  }
  return HTS_TRUE;
}

tic hts_boolean st_mkdir_at(const char *path, size_t n, const char *who) {
  if (MKDIR(path) != 0 && errno != EEXIST) {
    fprintf(stderr, "%s: mkdir failed at %u chars: %s\n", who, (unsigned) n,
            strerror(errno));
    return HTS_FALSE;
  }
  return HTS_TRUE;
}

/

tic size_t st_utf16_units(const char *s, size_t n) {
  size_t units = 0;

  for (size_t i = 0; i < n; i++) {
    const unsigned char c = (unsigned char) s[i];

    if ((c & 0xC0) == 0x80) {
      continue; /* continuation byte: charged with its lead */
    }
    units += c >= 0xF0 ? 2 : 1; /* outside the BMP is a surrogate pair */
  }
  return units;
}

/

tic size_t st_mkdeep(char *buf, size_t bufsize, const char *dir,
                        const char *nseg, const char *who, size_t *baselen) {
  // 40-char segments: each under the 255 per-component limit \\?\ can't lift.
  static const char seg[] = "/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
  const size_t room = bufsize - (sizeof(seg) + ST_LEAF_ROOM);
  size_t n = (size_t) snprintf(buf, bufsize, "%s", dir);

  assertf(bufsize > sizeof(seg) + ST_LEAF_ROOM);
  if (baselen != NULL) {
    *baselen = 0;
  }
  if (n >= room) {
    goto too_long;
  }
  while (n > 0 && (buf[n - 1] == '/' || buf[n - 1] == '\\')) {
    buf[--n] = '\0';
  }
  if (baselen != NULL) {
    *baselen = n;
  }
  if (nseg != NULL) {
    const size_t nseglen = strlen(nseg);

    if (nseglen >= room - n) { /* room - n > 0 above */
      goto too_long;
    }
    memcpybuff(buf + n, nseg, nseglen + 1);
    n += nseglen;
    if (!st_mkdir_at(buf, n, who)) {
      return 0;
    }
  }
  // Loop on the limit itself, over the whole path: an arithmetic bound landed
  // exactly on 260 for some base lengths, a byte count on a non-ASCII base.
  while (st_utf16_units(buf, n) <= 260) {
    if (n >= room) {
      goto too_long;
    }
    memcpybuff(buf + n, seg, sizeof(seg));
    n += sizeof(seg) - 1;
    if (!st_mkdir_at(buf, n, who)) {
      return 0;
    }
  }
  assertf(st_utf16_units(buf, n) > 260); /* what every caller depends on */
  return n;

too_long:
  fprintf(stderr, "%s: base dir too long (%u chars)\n", who, (unsigned) n);
  return 0;
}

static int ZCALLBACK selftest_counting_ztruncate(voidpf opaque, voidpf stream,
                                                 ZPOS64_T size) {
  writefail_inject *inj = (writefail_inject *) opaque;

  inj->truncates++;
  if (inj->truncate == NULL)
    return -1;
  return inj->truncate(opaque, stream, size);
}

static int zip_abandon_build_table(const char *path, size_t doomed,
                                   hts_boolean truncatable, int *abandon_err) {
  char catbuff[CATBUFF_SIZE];
  zlib_filefunc64_def ff;
  zipFile zf;
  int ret;

  hts_zip_filefunc64(&ff);
  if (!truncatable)
    ff.ztruncate64_file = NULL;
  zf = zipOpen2_64(fconv(catbuff, sizeof(catbuff), path), APPEND_STATUS_CREATE,
                   NULL, &ff);
  if (zf == NULL)
    return -1;
  ret = zip_abandon_fill(zf, doomed, abandon_err);
  return zipClose(zf, NULL) == ZIP_OK ? ret : -1;
}

static int zip_abandon_build(const char *path, size_t doomed) {
  int abandon_err = ZIP_OK;

  if (zip_abandon_build_table(path, doomed, HTS_TRUE, &abandon_err) != 0)
    return -1;
  return abandon_err == ZIP_OK ? 0 : -1;
}

static int st_zip_abandon_notrunc(httrackp *opt, int argc, char **argv) {
  static const size_t doomed = 200000; /* a tail past unzip.c's 64KB backscan */
  char refpath[HTS_URLMAXSIZE], path[HTS_URLMAXSIZE];
  char *ref = NULL, *got = NULL;
  size_t reflen = 0, gotlen = 0;
  int abandon_err = ZIP_OK;
  int fail = 0;
  unzFile uf;

  (void) opt;
  if (argc < 1) {
    fprintf(stderr, "zip-abandon-notrunc: needs a writable directory\n");
    return 1;
  }
  fconcat(refpath, sizeof(refpath), argv[0], "zip-notrunc-ref.zip");
  fconcat(path, sizeof(path), argv[0], "zip-notrunc.zip");

  /* control: the table the cache opens with truncates, and reports ZIP_OK */
  if (zip_abandon_build_table(refpath, doomed, HTS_TRUE, &abandon_err) != 0 ||
      zip_abandon_slurp(refpath, &ref, &reflen) != 0 || reflen == 0) {
    fprintf(stderr, "zip-abandon-notrunc: cannot build the reference\n");
    freet(ref);
    return 1;
  }
  freet(ref);
  if (abandon_err != ZIP_OK) {
    fprintf(stderr,
            "zip-abandon-notrunc: a truncating backend returned %d, want %d\n",
            abandon_err, ZIP_OK);
    fail++;
  }
  /* a flushed-but-kept member shows up as more than a backscan of leftovers,
     which is the size that matters, not the member's nominal one */
  if (reflen > 65535) {
    fprintf(stderr,
            "zip-abandon-notrunc: the reference kept %d byte(s), so the "
            "abandoned member was not truncated away\n",
            (int) reflen);
    fail++;
  }

  abandon_err = ZIP_OK;
  if (zip_abandon_build_table(path, doomed, HTS_FALSE, &abandon_err) != 0 ||
      zip_abandon_slurp(path, &got, &gotlen) != 0) {
    fprintf(stderr, "zip-abandon-notrunc: cannot build '%s'\n", path);
    freet(got);
    return fail + 1;
  }
  freet(got);
  if (abandon_err == ZIP_OK) {
    fprintf(stderr, "zip-abandon-notrunc: a backend with no truncate reported "
                    "the rollback as done\n");
    fail++;
  }
  /* only what the member had flushed stays, and it takes more than a reader's
     64KB backscan (unzip.c uMaxBack) to bury the directory behind it */
  if (gotlen <= reflen + 65535) {
    fprintf(stderr,
            "zip-abandon-notrunc: %d byte(s) left over the reference's %d, too "
            "few to outgrow a 64KB backscan\n",
            (int) gotlen, (int) reflen);
    fail++;
  }
  /* what the wrong return hides: the tail buries the directory written after */
  uf = hts_unzOpen_utf8(path);
  if (uf != NULL) {
    fprintf(stderr,
            "zip-abandon-notrunc: '%s' still opens, so the case proves "
            "nothing\n",
            path);
    unzClose(uf);
    fail++;
  }
  printf("zip-abandon-notrunc: %s\n", fail ? "FAIL" : "OK");
  return fail;
}

int ZCALLBACK win32_flush_file_func(voidpf opaque, voidpf stream) {
  HANDLE hFile = NULL;

  (void) opaque;
  if (stream != NULL)
    hFile = ((WIN32FILE_IOWIN *) stream)->hf;
  if (hFile == NULL)
    return -1;
  if (!FlushFileBuffers(hFile)) {
    ((WIN32FILE_IOWIN *) stream)->error = (int) GetLastError();
    return -1;
  }
  return 0;
}

int ZCALLBACK win32_truncate64_file_func(voidpf opaque, voidpf stream,
                                         ZPOS64_T size) {
  HANDLE hFile = NULL;
  LARGE_INTEGER cur, want;

  (void) opaque;
  if (stream != NULL)
    hFile = ((WIN32FILE_IOWIN *) stream)->hf;
  if (hFile == NULL)
    return -1;
  cur.QuadPart = 0;
  want.QuadPart = (LONGLONG) size;
  if (!MySetFilePointerEx(hFile, cur, &cur, FILE_CURRENT) ||
      !MySetFilePointerEx(hFile, want, NULL, FILE_BEGIN) ||
      !SetEndOfFile(hFile) ||
      !MySetFilePointerEx(hFile, cur, NULL, FILE_BEGIN)) {
    ((WIN32FILE_IOWIN *) stream)->error = (int) GetLastError();
    return -1;
  }
  return 0;
}

static void add_self_name(const char *name) {
  size_t i;

  if (name == NULL || *name == '\0' ||
      strlen(name) >= sizeof(server_self_names[0]) ||
      server_self_names_count == SELF_NAMES_MAX) {
    return;
  }
  for (i = 0; i < server_self_names_count; i++) {
    if (strfield2(server_self_names[i], name) != 0) {
      return;
    }
  }
  strcpybuff(server_self_names[server_self_names_count++], name);
}

static void add_resolved_self_names(const char *hostname) {
#if HTS_INET6 == 0
  const struct hostent *const hp = gethostbyname(hostname);

  if (hp != NULL) {
    add_self_name(hp->h_name);
  }
#else
  struct addrinfo *res = NULL;
  struct addrinfo hints;
  const struct addrinfo *ai;

  memset(&hints, 0, sizeof(hints));
  hints.ai_family = PF_UNSPEC;
  hints.ai_socktype = SOCK_STREAM;
  hints.ai_protocol = IPPROTO_TCP;
  hints.ai_flags = AI_CANONNAME;
  if (getaddrinfo(hostname, NULL, &hints, &res) == 0) {
    for (ai = res; ai != NULL; ai = ai->ai_next) {
      add_self_name(ai->ai_canonname);
    }
  }
  if (res != NULL) {
    freeaddrinfo(res);
  }
#endif
}

static void add_reverse_self_name(SOCaddr *bound) {
  char name[256];
  char addr[256];
  char back[256];
  SOCaddr resolved;

  SOCaddr_inetntoa(addr, sizeof(addr), *bound);
  /* a wildcard is no address to ask about, and none can confirm back to it */
  if (addr[0] == '\0' || strcmp(addr, "0.0.0.0") == 0 ||
      strcmp(addr, "::") == 0 ||
      getnameinfo(&SOCaddr_sockaddr(*bound), SOCaddr_size(*bound), name,
                  sizeof(name), NULL, 0, NI_NAMEREQD) != 0) {
    return;
  }
  memset(&resolved, 0, sizeof(resolved));
  if (!gethost(name, &resolved)) {
    return;
  }
  SOCaddr_inetntoa(back, sizeof(back), resolved);
  if (back[0] != '\0' && strcmp(addr, back) == 0) {
    add_self_name(name);
  }
}

static void collect_self_names(T_SOC soc) {
  SOCaddr bound;
  SOClen len = SOCaddr_capacity(bound);
  char host[256];

  server_self_names_count = 0;
  if (getsockname(soc, &SOCaddr_sockaddr(bound), &len) != 0) {
    return;
  }
  if (gethostname(host, sizeof(host)) == 0) {
    host[sizeof(host) - 1] = '\0';
    add_self_name(host);
    add_resolved_self_names(host);
  }
  add_reverse_self_name(&bound);
}

static void forward(int sig, siginfo_t *info, void *ctx) {
  const int saved = errno;

  (void) ctx;
  if (child > 0 && info != NULL && sig != SIGCHLD && info->si_code <= 0) {
    kill((pid_t) child, sig);
  }
  if (wakefd[1] >= 0) {
    const ssize_t ignored = write(wakefd[1], "!", 1);

    (void) ignored;
  }
  errno = saved;
}

static void catch_signals(void) {
  struct sigaction sa;
  int i;

  memset(&sa, 0, sizeof sa);
  sa.sa_sigaction = forward;
  sa.sa_flags = SA_SIGINFO | SA_RESTART;
  sigfillset(&sa.sa_mask);
  for (i = 0; i < NHANDLED; i++) {
    if (handled[i] == SIGPIPE) {
      struct sigaction ign;
      memset(&ign, 0, sizeof ign);
      ign.sa_handler = SIG_IGN;
      sigaction(SIGPIPE, &ign, &inherited[i]);
    } else {
      sigaction(handled[i], &sa, &inherited[i]);
    }
  }
}

static void restore_signals(void) {
  int i;

  for (i = 0; i < NHANDLED; i++) {
    sigaction(handled[i], &inherited[i], NULL);
  }
}

static void block_signals(int how) {
  sigset_t set;
  int i;

  sigemptyset(&set);
  for (i = 0; i < NHANDLED; i++) {
    sigaddset(&set, handled[i]);
  }
  sigprocmask(how, &set, NULL);
}

static void run_bare(char **argv) {
  execvp(argv[0], argv);
  fprintf(stderr, "stderrwrap: %s: %s\n", argv[0], strerror(errno));
  fflush(stderr);
  _exit(127);
}

static int open_log(const char *dir) {
  const char *tag = getenv("HTTRACK_STDERR_CAPTURE_TAG");
  char path[4096];
  int i;

  if (tag == NULL || tag[0] == '\0') {
    tag = "engine";
  }
  for (i = 0; tag[i] != '\0'; i++) {
    if (!isalnum((unsigned char) tag[i]) && strchr("._-", tag[i]) == NULL) {
      tag = "engine";
      break;
    }
  }
  if (snprintf(path, sizeof path, "%s/%s.%ld.log", dir, tag, (long) getpid()) >=
      (int) sizeof path) {
    return -1;
  }
  return open(path, O_WRONLY | O_CREAT | O_APPEND, 0600);
}

static int write_all(int fd, const char *buf, size_t len) {
  while (len > 0) {
    const ssize_t n = write(fd, buf, len);

    if (n < 0) {
      if (errno == EINTR) {
        continue;
      }
      return 0;
    }
    buf += n;
    len -= (size_t) n;
  }
  return 1;
}

int cache_zip_store_stream(zipFile zf, FILE *fp) {
  char BIGSTK buff[32768];
  size_t nl;

  do {
    int zErr;

    nl = fread(buff, 1, sizeof(buff), fp);
    if (nl > 0 && (zErr = zipWriteInFileInZip(zf, buff, (int) nl)) != Z_OK)
      return zErr;
  } while (nl > 0);
  return ferror(fp) ? CACHE_ZIP_READ_ERROR : Z_OK;
}

static int readfail_roundtrip(const char *path, FILE *src, int want_status,
                              char *out, size_t outsz) {
  zipFile zf = hts_zipOpen_utf8(path, APPEND_STATUS_CREATE);
  zip_fileinfo fi;
  unzFile uf;
  int got, n;

  if (zf == NULL)
    return -1;
  memset(&fi, 0, sizeof(fi));
  if (zipOpenNewFileInZip(zf, "entry.bin", &fi, NULL, 0, NULL, 0, NULL,
                          Z_DEFLATED, Z_DEFAULT_COMPRESSION) != ZIP_OK) {
    zipClose(zf, NULL);
    return -1;
  }
  got = cache_zip_store_stream(zf, src);
  if (got == Z_OK)
    zipCloseFileInZip(zf);
  else
    zipAbandonFileInZip(zf);
  zipClose(zf, NULL);
  if (got != want_status) {
    fprintf(stderr, "cache-readfail: status %d, want %d\n", got, want_status);
    return -1;
  }
  uf = hts_unzOpen_utf8(path);
  if (uf == NULL || unzLocateFile(uf, "entry.bin", 1) != UNZ_OK ||
      unzOpenCurrentFile(uf) != UNZ_OK) {
    if (uf != NULL)
      unzClose(uf);
    return -1;
  }
  n = unzReadCurrentFile(uf, out, (unsigned) outsz);
  unzCloseCurrentFile(uf);
  unzClose(uf);
  return n;
}

static void readfail_store_file(httrackp *opt, cache_back *cache,
                                const char *fil, const char *save,
                                LLint declared) {
  htsblk r;
  char locbuf[4];

  hts_init_htsblk(&r);
  r.statuscode = 200;
  r.size = declared;
  strcpybuff(r.msg, "OK");
  strcpybuff(r.contenttype, "application/octet-stream");
  locbuf[0] = '\0';
  r.location = locbuf;
  r.is_write = 1;
  cache_add(opt, cache, &r, "example.com", fil, save, 1, NULL);
}

static int readfail_write_source(const char *save, const char *body,
                                 size_t len) {
  char catbuff[HTS_URLMAXSIZE * 2];
  char *path = fconv(catbuff, sizeof(catbuff), save);
  FILE *fp;

  (void) structcheck(path);
  fp = FOPEN(path, "wb");
  if (fp == NULL)
    return -1;
  if (len != 0 && !hts_fwrite_exact(body, len, fp)) {
    fclose(fp);
    return -1;
  }
  fclose(fp);
  return 0;
}

static const char *readfail_unreadable_source(void) {
  static const char path[] = "/proc/self/mem";
  char catbuff[HTS_URLMAXSIZE * 2];
  char probe[1];
  FILE *fp;
  int usable;

  if (fsize_utf8(fconv(catbuff, sizeof(catbuff), path)) < 0)
    return NULL;
  fp = FOPEN(fconv(catbuff, sizeof(catbuff), path), "rb");
  if (fp == NULL)
    return NULL;
  usable = fread(probe, 1, sizeof(probe), fp) == 0 && ferror(fp) != 0;
  fclose(fp);
  return usable ? path : NULL;
}

static int st_cache_readfail(httrackp *opt, int argc, char **argv) {
  int err;

  if (argc < 1) {
    fprintf(stderr, "cache-readfail: needs a directory\n");
    return 1;
  }
  err = cache_readfail_selftest(opt, argv[0]);
  printf("cache-readfail: %s\n", err ? "FAIL" : "OK");
  return err;
}

static int zip_abandon_build(const char *path, size_t doomed) {
  char catbuff[CATBUFF_SIZE];
  char chunk[4096];
  zip_fileinfo fi;
  zipFile zf = hts_zipOpen_utf8(fconv(catbuff, sizeof(catbuff), path),
                                APPEND_STATUS_CREATE);
  size_t i;

  if (zf == NULL)
    return -1;
  memset(&fi, 0, sizeof(fi));
  memset(chunk, 'Z', sizeof(chunk));
  for (i = 0; i < sizeof(zip_abandon_kept) / sizeof(zip_abandon_kept[0]); i++) {
    size_t left;

    if (zipOpenNewFileInZip(zf, zip_abandon_kept[i], &fi, NULL, 0, NULL, 0,
                            NULL, Z_DEFLATED,
                            Z_DEFAULT_COMPRESSION) != ZIP_OK ||
        zipWriteInFileInZip(zf, zip_abandon_body,
                            (unsigned) (sizeof(zip_abandon_body) - 1)) !=
            ZIP_OK ||
        zipCloseFileInZip(zf) != ZIP_OK)
      goto fail;
    if (i != 0 || doomed == 0)
      continue;
    if (zipOpenNewFileInZip(zf, "doomed.bin", &fi, NULL, 0, NULL, 0, NULL,
                            0 /* stored */, Z_NO_COMPRESSION) != ZIP_OK)
      goto fail;
    for (left = doomed; left != 0;) {
      const size_t n = left < sizeof(chunk) ? left : sizeof(chunk);

      if (zipWriteInFileInZip(zf, chunk, (unsigned) n) != ZIP_OK)
        goto fail;
      left -= n;
    }
    if (zipAbandonFileInZip(zf) != ZIP_OK)
      goto fail;
  }
  return zipClose(zf, NULL) == ZIP_OK ? 0 : -1;

fail:
  zipClose(zf, NULL);
  return -1;
}

static int zip_abandon_slurp(const char *path, char **out, size_t *len) {
  char catbuff[CATBUFF_SIZE];
  const LLint size = fsize_utf8(fconv(catbuff, sizeof(catbuff), path));
  FILE *fp;

  *out = NULL;
  *len = 0;
  if (size < 0)
    return -1;
  fp = FOPEN(fconv(catbuff, sizeof(catbuff), path), "rb");
  if (fp == NULL)
    return -1;
  *out = malloct((size_t) size + 1);
  if (*out == NULL ||
      (size != 0 && !hts_fread_exact(*out, (size_t) size, fp))) {
    freet(*out);
    fclose(fp);
    return -1;
  }
  fclose(fp);
  *len = (size_t) size;
  return 0;
}

static int zip_abandon_check_members(unzFile uf) {
  char got[sizeof(zip_abandon_body)];
  size_t i;

  for (i = 0; i < sizeof(zip_abandon_kept) / sizeof(zip_abandon_kept[0]); i++) {
    const int want = (int) sizeof(zip_abandon_body) - 1;
    int n;

    if (unzLocateFile(uf, zip_abandon_kept[i], 1) != UNZ_OK ||
        unzOpenCurrentFile(uf) != UNZ_OK) {
      fprintf(stderr, "zip-abandon: '%s' is missing\n", zip_abandon_kept[i]);
      return -1;
    }
    n = unzReadCurrentFile(uf, got, (unsigned) sizeof(got));
    unzCloseCurrentFile(uf);
    if (n != want || memcmp(got, zip_abandon_body, (size_t) want) != 0) {
      fprintf(stderr, "zip-abandon: '%s' read back %d byte(s), want %d\n",
              zip_abandon_kept[i], n, want);
      return -1;
    }
  }
  return 0;
}

static int st_zip_abandon(httrackp *opt, int argc, char **argv) {
  static const size_t doomed[] = {
      70000,  /* one 64KB flush: a leftover tail a reader still scans past */
      200000, /* three of them: a tail that buries the directory for good */
  };
  char refpath[HTS_URLMAXSIZE], path[HTS_URLMAXSIZE], name[64];
  char *ref = NULL;
  size_t reflen = 0;
  size_t i;
  int fail = 0;

  (void) opt;
  if (argc < 1) {
    fprintf(stderr, "zip-abandon: needs a writable directory\n");
    return 1;
  }
  fconcat(refpath, sizeof(refpath), argv[0], "zip-abandon-ref.zip");
  if (zip_abandon_build(refpath, 0) != 0 ||
      zip_abandon_slurp(refpath, &ref, &reflen) != 0 || reflen == 0) {
    fprintf(stderr, "zip-abandon: cannot build the reference archive\n");
    freet(ref);
    return 1;
  }
  for (i = 0; i < sizeof(doomed) / sizeof(doomed[0]); i++) {
    unz_global_info64 gi;
    unzFile uf;
    char *got = NULL;
    size_t gotlen = 0;

    snprintf(name, sizeof(name), "zip-abandon-%d.zip", (int) doomed[i]);
    fconcat(path, sizeof(path), argv[0], name);
    if (zip_abandon_build(path, doomed[i]) != 0 ||
        zip_abandon_slurp(path, &got, &gotlen) != 0) {
      fprintf(stderr, "zip-abandon: cannot build '%s'\n", path);
      fail++;
      freet(got);
      continue;
    }
    if (gotlen != reflen || memcmp(got, ref, reflen) != 0) {
      fprintf(stderr,
              "zip-abandon: %d abandoned byte(s) left a %d-byte archive, want "
              "%d byte(s) identical to the reference\n",
              (int) doomed[i], (int) gotlen, (int) reflen);
      fail++;
    }
    freet(got);
    uf = hts_unzOpen_utf8(path);
    if (uf == NULL) {
      fprintf(stderr,
              "zip-abandon: '%s' does not open: no directory found within the "
              "backscan\n",
              path);
      fail++;
      continue;
    }
    if (unzGetGlobalInfo64(uf, &gi) != UNZ_OK ||
        gi.number_entry !=
            sizeof(zip_abandon_kept) / sizeof(zip_abandon_kept[0])) {
      fprintf(stderr,
              "zip-abandon: '%s' holds %" PRIu64 " entr(ies), want %d\n", path,
              (uint64_t) gi.number_entry,
              (int) (sizeof(zip_abandon_kept) / sizeof(zip_abandon_kept[0])));
      fail++;
    } else if (zip_abandon_check_members(uf) != 0)
      fail++;
    unzClose(uf);
  }
  freet(ref);
  printf("zip-abandon: %s\n", fail ? "FAIL" : "OK");
  return fail;
}

static int st_warc_offset(httrackp *opt, int argc, char **argv) {
  static const uint64_t cases[] = {
      0,
      2147483647ULL, /* LONG_MAX where long is 32 bits */
      2147483648ULL, /* first offset a 32-bit signed tell cannot hold */
      4294967295ULL,
      4294967296ULL,
      1099511627775ULL, /* 1TB - 1: a plausible archive on a big mirror */
  };
  char path[HTS_URLMAXSIZE];
  char catbuff[CATBUFF_SIZE];
  FILE *fp;
  int err = 0;
  size_t i;

  (void) opt;
  if (argc < 1) {
    fprintf(stderr, "warc-offset: needs a writable directory\n");
    return 1;
  }
  fconcat(path, sizeof(path), argv[0], "warc-offset.bin");
  fp = FOPEN(fconv(catbuff, sizeof(catbuff), path), "wb");
  if (fp == NULL) {
    fprintf(stderr, "warc-offset: cannot create '%s': %s\n", path,
            strerror(errno));
    return 1;
  }
  for (i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
    const uint64_t want = cases[i];
    uint64_t got;

    if (fseeko(fp, (LLint) want, SEEK_SET) != 0) {
      fprintf(stderr, "warc-offset: cannot seek to %" PRIu64 ": %s\n", want,
              strerror(errno));
      err = 1;
      continue;
    }
    /* the sentinel must never survive: a failed tell would leak it back */
    got = warc_stream_offset(fp, 0xdeadbeefULL);
    if (got != want) {
      fprintf(stderr, "warc-offset: tell at %" PRIu64 " reported %" PRIu64 "\n",
              want, got);
      err = 1;
    }
  }
  fclose(fp);
  /* seeking never wrote: a several-GB file here would mean a real write */
  if (fsize_utf8(path) != 0) {
    fprintf(stderr, "warc-offset: the probe file is not empty (%" PRIu64 ")\n",
            (uint64_t) fsize_utf8(path));
    err = 1;
  }
  UNLINK(fconv(catbuff, sizeof(catbuff), path));

  /* The width has to survive all the way to the CDXJ text: 01_zlib-warc-cdx
     covers the wiring, but only at offsets a 32-bit field would also hold. */
  {
    static const struct {
      uint64_t length, offset;
      const char *want;
    } extents[] = {
        {0, 0, ", \"length\": \"0\", \"offset\": \"0\""},
        {4096, 4294967295ULL,
         ", \"length\": \"4096\", \"offset\": \"4294967295\""},
        {4294967296ULL, 4294967296ULL,
         ", \"length\": \"4294967296\", \"offset\": \"4294967296\""},
        {18446744073709551615ULL, 1099511627776ULL,
         ", \"length\": \"18446744073709551615\", \"offset\": "
         "\"1099511627776\""},
    };

    for (i = 0; i < sizeof(extents) / sizeof(extents[0]); i++) {
      char got[WARC_CDX_EXTENT_SIZE];

      got[0] = '\0';
      if (warc_cdx_extent(got, sizeof(got), extents[i].length,
                          extents[i].offset) < 0 ||
          strcmp(got, extents[i].want) != 0) {
        fprintf(stderr, "warc-offset: CDXJ extent is '%s', want '%s'\n", got,
                extents[i].want);
        err = 1;
      }
    }

    /* the truncation return, which no WARC_CDX_EXTENT_SIZE buffer reaches: the
       widest pair fits it, and a clipped extent must be refused, not indexed */
    {
      struct {
        char buf[24];
        char canary[8];
      } tight;

      char full[WARC_CDX_EXTENT_SIZE];
      int n;

      memset(&tight, 'C', sizeof(tight));
      if (warc_cdx_extent(tight.buf, sizeof(tight.buf), 4294967296ULL,
                          1099511627776ULL) != -1) {
        fprintf(stderr, "warc-offset: a clipped CDXJ extent was not refused\n");
        err = 1;
      }
      if (memcmp(tight.canary, "CCCCCCCC", sizeof(tight.canary)) != 0) {
        fprintf(stderr, "warc-offset: the CDXJ extent overran its buffer\n");
        err = 1;
      }
      n = warc_cdx_extent(full, sizeof(full), UINT64_MAX, UINT64_MAX);
      if (n < 0 || (size_t) n != strlen(full)) {
        fprintf(stderr,
                "warc-offset: the widest CDXJ extent does not fit %d bytes\n",
                (int) sizeof(full));
        err = 1;
      }
    }
  }
  printf("warc-offset: %s\n", err ? "FAIL" : "OK");
  return err;
}

int warc_cdx_extent(char *out, size_t outsz, uint64_t length, uint64_t offset) {
  const int n = snprintf(
      out, outsz, ", \"length\": \"%" PRIu64 "\", \"offset\": \"%" PRIu64 "\"",
      length, offset);

  return (n < 0 || (size_t) n >= outsz) ? -1 : n;
}

uint64_t warc_stream_offset(FILE *f, uint64_t current) {
  const LLint pos = ftello(f);

  /* ftell/long would compile here and cap at 2GB on LLP64 and 32-bit hosts */
  HTS_STATIC_ASSERT(sizeof(pos) >= 8 && sizeof(ftello(f)) >= 8,
                    warc_tell_is_64bit);
  return pos >= 0 ? (uint64_t) pos : current;
}

static voidpf ZCALLBACK hts_zip_fopen_utf8(voidpf opaque, const void *filename,
                                           int mode) {
  const char *mode_fopen = NULL;

  (void) opaque;
  if ((mode & ZLIB_FILEFUNC_MODE_READWRITEFILTER) == ZLIB_FILEFUNC_MODE_READ)
    mode_fopen = "rb";
  else if (mode & ZLIB_FILEFUNC_MODE_EXISTING)
    mode_fopen = "r+b";
  else if (mode & ZLIB_FILEFUNC_MODE_CREATE)
    mode_fopen = "wb";
  if (filename == NULL || mode_fopen == NULL)
    return NULL;
  return (voidpf) FOPEN((const char *) filename, mode_fopen);
}

unzFile hts_unzOpen_utf8(const char *path) {
  zlib_filefunc64_def ff;

  fill_fopen64_filefunc(&ff);
  ff.zopen64_file = hts_zip_fopen_utf8;
  return unzOpen2_64(path, &ff);
}

zipFile hts_zipOpen_utf8(const char *path, int append) {
  zlib_filefunc64_def ff;

  fill_fopen64_filefunc(&ff);
  ff.zopen64_file = hts_zip_fopen_utf8;
  return zipOpen2_64(path, append, NULL, &ff);
}

int call_ztruncate64(const zlib_filefunc64_32_def *pfilefunc, voidpf filestream,
                     ZPOS64_T size) {
  /* a backend with no truncate keeps its tail: better than failing a rollback
     the caller has already performed */
  if (pfilefunc->zfile_func64.ztruncate64_file == NULL)
    return 0;
  return (*(pfilefunc->zfile_func64.ztruncate64_file))(
      pfilefunc->zfile_func64.opaque, filestream, size);
}

static int ZCALLBACK ftruncate64_file_func(voidpf opaque, voidpf stream,
                                           ZPOS64_T size) {
  FILE *file = (FILE *) stream;
  (void) opaque;
  /* buffered bytes would otherwise be written back past the new end */
  if (fflush(file) != 0)
    return -1;
#if defined(_WIN32) || defined(WIN32)
  return _chsize_s(_fileno(file), (__int64) size);
#else
  return ftruncate(fileno(file), (off_t) size);
#endif
}

extern int ZEXPORT zipAbandonFileInZip(zipFile file) {
  zip64_internal *zi;

  if (file == NULL)
    return ZIP_PARAMERROR;
  zi = (zip64_internal *) file;
  if (zi->in_opened_file_inzip == 0)
    return ZIP_PARAMERROR;

  if (zi->ci.stream_initialised) {
    if ((zi->ci.method == Z_DEFLATED) && (!zi->ci.raw))
      (void) deflateEnd(&zi->ci.stream);
#ifdef HAVE_BZIP2
    else if ((zi->ci.method == Z_BZIP2ED) && (!zi->ci.raw))
      (void) BZ2_bzCompressEnd(&zi->ci.bstream);
#endif
    zi->ci.stream_initialised = 0;
  }
  free(zi->ci.central_header);
  zi->ci.central_header = NULL;
  zi->in_opened_file_inzip = 0;

  /* not counted in zi->number_entry: the member never existed */
  if (ZSEEK64(zi->z_filefunc, zi->filestream, zi->ci.pos_local_header,
              ZLIB_FILEFUNC_SEEK_SET) != 0)
    return ZIP_ERRNO;
  /* the rewind alone leaves what the member flushed past the end-of-central-
     directory written later, which no reader finds once that tail outgrows the
     64KB backscan */
  if (ZTRUNCATE64(zi->z_filefunc, zi->filestream, zi->ci.pos_local_header) != 0)
    return ZIP_ERRNO;
  return ZIP_OK;
}

static void back_report_write_failure(httrackp *opt, const char *save) {
  if (!check_fatal_io_errno())
    return;
  hts_log_print(opt, LOG_ERROR | LOG_ERRNO, "Unable to write file %s", save);
  if (opt->state.exit_xh == 0) {
    hts_log_print(opt, LOG_ERROR,
                  "Mirror aborted: disk full or filesystem problems");
    opt->state.exit_xh = -1;
  }
}

static int st_filesave(httrackp *opt, int argc, char **argv) {
  static const char body[] = "DISKFULL-FILESAVE";
  const int len = (int) sizeof(body) - 1;
  int rc, err;

  if (argc < 2) {
    fprintf(stderr, "usage: -#test=filesave <doomed-save> <control-save>\n");
    return 1;
  }
  errno = 0;
  rc = filesave(opt, body, len, argv[0], "127.0.0.1", "/x.bin");
  err = errno;
  assertf(rc == -1);
  assertf(err == ENOSPC);
  /* control: the same call succeeds on a name that can take the bytes */
  assertf(filesave(opt, body, len, argv[1], "127.0.0.1", "/x.bin") == 0);
  printf("filesave: refused with ENOSPC, control saved\n");
  return 0;
}

int hts_dns_negative_failures(httrackp *opt, const char *host) {
  void *ptr;
  int failures = 0;

  hts_mutexlock(&opt->state.lock);
  if (coucal_read_pvoid(hts_cache(opt), host, &ptr))
    failures = ((const t_dnscache *) ptr)->failures;
  hts_mutexrelease(&opt->state.lock);
  return failures;
}

void hts_dns_test_move_clock(httrackp *opt, const char *host, TStamp ms) {
  void *ptr;

  hts_mutexlock(&opt->state.lock);
  if (coucal_read_pvoid(hts_cache(opt), host, &ptr)) {
    t_dnscache *const record = (t_dnscache *) ptr;

    if (record->expiry != 0) { /* a positive record carries no stamps */
      record->expiry -= ms;
      record->stored -= ms;
    }
  }
  hts_mutexrelease(&opt->state.lock);
}

int hts_dns_negative_wait_ms(int failures) {
  int wait = hts_dns_negative_ttl_ms;
  int i;

  for (i = 1; i < failures && wait < HTS_DNS_NEGATIVE_TTL_MAX_MS; i++)
    wait *= 2;
  return wait < HTS_DNS_NEGATIVE_TTL_MAX_MS ? wait
                                            : HTS_DNS_NEGATIVE_TTL_MAX_MS;
}

static hts_boolean hts_link_may_carry_links(httrackp *opt, cache_back *cache,
                                            const char *adr, const char *fil) {
  char BIGSTK prev_save[HTS_URLMAXSIZE * 2];
  htsblk prev;

  prev_save[0] = '\0'; /* a cache miss leaves it untouched */
  prev = cache_read_including_broken(opt, cache, adr, fil, prev_save);

  return HTTP_IS_OK(prev.statuscode) && strnotempty(prev_save) &&
                 is_hypertext_mime(opt, prev.contenttype, prev_save)
             ? HTS_TRUE
             : HTS_FALSE;
}

hts_boolean hts_body_missing_unexpectedly(const htsblk *r) {
  if (r->adr != NULL || r->is_write != 0)
    return HTS_FALSE;
  if (HTTP_IS_REDIRECT(r->statuscode) ||
      r->statuscode == HTTP_PRECONDITION_FAILED ||
      r->statuscode == HTTP_REQUESTED_RANGE_NOT_SATISFIABLE)
    return HTS_FALSE;
  return HTS_TRUE;
}

static int st_nobody(httrackp *opt, int argc, char **argv) {
  /* every status the engine excuses, and near misses that it must not */
  static const struct {
    int code;
    hts_boolean excused;
  } cases[] = {
      {301, HTS_TRUE},  {302, HTS_TRUE},  {303, HTS_TRUE},  {304, HTS_FALSE},
      {305, HTS_FALSE}, {306, HTS_FALSE}, {307, HTS_TRUE},  {308, HTS_TRUE},
      {309, HTS_FALSE}, {300, HTS_FALSE}, {411, HTS_FALSE}, {412, HTS_TRUE},
      {413, HTS_FALSE}, {415, HTS_FALSE}, {416, HTS_TRUE},  {417, HTS_FALSE},
      {200, HTS_FALSE}, {204, HTS_FALSE}, {404, HTS_FALSE}, {500, HTS_FALSE},
  };

  char body[] = "body";
  size_t i;
  htsblk r;
  (void) opt;
  (void) argc;
  (void) argv;

  for (i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
    memset(&r, 0, sizeof(r));
    r.statuscode = cases[i].code;
    if (hts_body_missing_unexpectedly(&r) == cases[i].excused) {
      fprintf(stderr, "status %d: expected %s\n", cases[i].code,
              cases[i].excused ? "excused" : "unexpected");
      return 1;
    }
  }

  /* a stored body is never missing, whatever the status */
  memset(&r, 0, sizeof(r));
  r.statuscode = 404;
  r.adr = body;
  assertf(!hts_body_missing_unexpectedly(&r));
  memset(&r, 0, sizeof(r));
  r.statuscode = 404;
  r.is_write = 1;
  assertf(!hts_body_missing_unexpectedly(&r));

  printf("nobody self-test OK\n");
  return 0;
}

void hts_unescapehttp(const char *s, String *tempo) {
  size_t i;

  for (i = 0; s[i] != '\0'; i++) {
    int h;

    if (s[i] == '%' && s[i + 1] == '%') {
      i++;
      StringAddchar(*tempo, '%');
    } else if (s[i] == '%' && s[i + 1] != '\0' && s[i + 2] != '\0' &&
               (h = hts_ehex(&s[i + 1])) >= 0) {
      StringAddchar(*tempo, (char) h);
      i += 2;
    } else if (s[i] == '+') {
      StringAddchar(*tempo, ' ');
    } else {
      StringAddchar(*tempo, s[i]);
    }
  }
}

void hts_unescapeini(const char *s, String *tempo) {
  size_t i;
  char lastc = 0;

  for (i = 0; s[i] != '\0'; i++) {
    int h;

    if (s[i] == '%' && s[i + 1] == '%') {
      i++;
      StringAddchar(*tempo, lastc = '%');
    } else if (s[i] == '%' && s[i + 1] != '\0' && s[i + 2] != '\0' &&
               (h = hts_ehex(&s[i + 1])) >= 0) {
      const char hc = (char) h;

      if (!hts_is_retorsep(hc) || !hts_is_retorsep(lastc)) {
        StringAddchar(*tempo, lastc = hc);
      }
      i += 2;
    } else {
      StringAddchar(*tempo, lastc = s[i]);
    }
  }
}

static int st_unescape_form(httrackp *opt, int argc, char **argv) {
  /* compared by length, so a decoded NUL is not mistaken for a short string */
  static const struct {
    const char *in;
    const char *expected;
    size_t len;
    int ini; /* run hts_unescapeini() rather than http */
  } cases[] = {
      {"", "", 0, 0},
      {"a%41b", "aAb", 3, 0},
      {"%c3%a9", "\xc3\xa9", 2, 0},
      {"%C3%A9", "\xc3\xa9", 2, 0}, /* hex case does not matter */
      {"a+b", "a b", 3, 0},
      {"100%%", "100%", 4, 0},
      {"%00", "\0", 1, 0},  /* well-formed, so it really does decode to NUL */
      {"%ZZ", "%ZZ", 3, 0}, /* not hex: kept literal, not decoded to NUL */
      {"%zz", "%zz", 3, 0}, /* lower case too, or a widened 'a'-'f' arm hides */
      {"%4", "%4", 2, 0},   /* truncated: no second digit to read */
      {"%", "%", 1, 0},
      {"%%%", "%%", 2, 0},
      {"a%2Gb", "a%2Gb", 5, 0}, /* second digit not hex */
      {"", "", 0, 1},
      {"a+b", "a+b", 3, 1},          /* the ini form has no '+' rule */
      {"a%0d%0ab", "a\rb", 3, 1},    /* a decoded separator run collapses */
      {"a%0d%0a%0db", "a\rb", 3, 1}, /* however long the run is */
      {"a\r\nb", "a\r\nb", 4, 1},    /* but raw separators pass through */
      {"a%ZZb", "a%ZZb", 5, 1},
  };

  size_t i;

  (void) opt;
  (void) argc;
  (void) argv;
  for (i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
    String out = STRING_EMPTY;
    const char *got;

    if (cases[i].ini) {
      hts_unescapeini(cases[i].in, &out);
    } else {
      hts_unescapehttp(cases[i].in, &out);
    }
    got = StringBuff(out);
    /* callers read the result with strcmp(), so the terminator is part of the
       contract */
    if (StringLength(out) != cases[i].len ||
        (cases[i].len != 0 &&
         memcmp(got, cases[i].expected, cases[i].len) != 0) ||
        (got != NULL && got[cases[i].len] != '\0')) {
      fprintf(stderr, "unescape-form: %s gave %d bytes, expected %d\n",
              cases[i].in, (int) StringLength(out), (int) cases[i].len);
      StringFree(out);
      return 1;
    }
    StringFree(out);
  }
  printf("unescape-form self-test OK\n");
  return 0;
}

char *ftp_jump_authority(char *url_adr) {
  char *a = jump_protocol(url_adr);

  while (*a == '/')
    a++;
  return a;
}

hts_boolean ftp_split_hostport(const char *adr, char *host, size_t host_size,
                               int *port, char *err, size_t err_size) {
  static const char portmsg[] = "Invalid port: ";
  const char *const a = jump_toport_const(adr);
  const size_t len = a != NULL ? (size_t) (a - adr) : strlen(adr);

  /* the caller owns err[], so a size too small for either message is a bug */
  assertf(host_size > 0 && err_size > sizeof("Host name too long"));
  host[0] = err[0] = '\0';
  /* no resolvable name is this long, and clipping would query another host */
  if (len >= host_size) {
    strlcpybuff(err, "Host name too long", err_size);
    return HTS_FALSE;
  }
  /* folding a nonsense port into 1..65535 fetches one the link never named */
  if (a != NULL && a[1] != '\0' && !hts_parse_url_port(a + 1, port)) {
    strlcpybuff(err, portmsg, err_size);
    /* wire data: clip the echoed port rather than abort on an over-long one */
    strlncatbuff(err, a + 1, err_size, err_size - sizeof(portmsg));
    return HTS_FALSE;
  }
  strlncatbuff(host, adr, host_size, len);
  return HTS_TRUE;
}

static int st_toport(httrackp *opt, int argc, char **argv) {
  int i;

  (void) opt;
  if (argc < 1) {
    fprintf(stderr, "toport: needs a URL\n");
    return 1;
  }
  for (i = 0; i < argc; i++) {
    const char *const port = jump_toport_const(argv[i]);

    printf("%s\n", port != NULL ? port : "(none)");
  }
  return 0;
}

static int st_ftpaddr(httrackp *opt, int argc, char **argv) {
  int i;

  (void) opt;
  if (argc < 1) {
    fprintf(stderr, "ftpaddr: needs a URL address\n");
    return 1;
  }
  for (i = 0; i < argc; i++) {
    char BIGSTK url[HTS_URLMAXSIZE * 2];
    char host[256];
    char err[128];
    int port = 21;

    strcpybuff(url, argv[i]);
    if (ftp_split_hostport(jump_identification(ftp_jump_authority(url)), host,
                           sizeof(host), &port, err, sizeof(err)))
      printf("host=%s port=%d\n", host, port);
    else
      printf("error=%s\n", err);
  }
  return 0;
}

static void advertised_host(char *dst, size_t size, const char *bound) {
  const char *host = bound;

  /* every address reaches us, and loopback is the one the local browser has */
  if (strcmp(host, "0.0.0.0") == 0) {
    host = "127.0.0.1";
  } else if (strcmp(host, "::") == 0) {
    host = "::1";
  }
  if (strchr(host, ':') != NULL) {
    strlcpybuff(dst, "[", size);
    strlcatbuff(dst, host, size);
    strlcatbuff(dst, "]", size);
  } else {
    strlcpybuff(dst, host, size);
  }
}

static hts_boolean host_hostname(char *dst, size_t size, const char *host) {
  const char *start = host;
  const char *end;

  dst[0] = '\0';
  if (*start == '[') {
    end = strchr(++start, ']');
    if (end == NULL || (end[1] != '\0' && end[1] != ':')) {
      return HTS_FALSE;
    }
  } else if ((end = strchr(start, ':')) == NULL) {
    end = start + strlen(start);
  }
  if (end == start || (size_t) (end - start) >= size) {
    return HTS_FALSE;
  }
  memcpy(dst, start, (size_t) (end - start));
  dst[end - start] = '\0';
  return HTS_TRUE;
}

static hts_boolean host_is_address(const char *name) {
  size_t i;

  if (strchr(name, ':') != NULL) {
    return HTS_TRUE;
  }
  for (i = 0; name[i] != '\0'; i++) {
    if (!isdigit((unsigned char) name[i]) && name[i] != '.') {
      return HTS_FALSE;
    }
  }
  return i != 0 ? HTS_TRUE : HTS_FALSE;
}

static hts_boolean host_is_self(const char *host, const char *bound) {
  char name[256];

  if (!host_hostname(name, sizeof(name), host)) {
    return HTS_FALSE;
  }
  return strfield2(name, "localhost") != 0 || host_is_address(name) ||
                 (bound[0] != '\0' && strfield2(name, bound) != 0)
             ? HTS_TRUE
             : HTS_FALSE;
}

static hts_boolean hts_path_is_contained(const char *path) {
  const char *s;

  for (s = path; *s != '\0';) {
    while (IS_PATH_SEP(*s)) {
      s++;
    }
    if (s[0] == '.' && s[1] == '.' && (s[2] == '\0' || IS_PATH_SEP(s[2]))) {
      return HTS_FALSE;
    }
    while (*s != '\0' && !IS_PATH_SEP(*s)) {
      s++;
    }
  }
  return HTS_TRUE;
}

static int st_cookiecap(httrackp *opt, int argc, char **argv) {
  static t_cookie cookie;
  /* Above the 256 bytes of headroom cookie_add reserves, or it refuses all. */
  const size_t cap = 512;
  static const char NAME[] = "n", DOM[] = "www.example.com", PATH[] = "/";
  char big[1024];
  int err = 0;
  size_t i;

  (void) opt;
  (void) argc;
  (void) argv;

  /* A non-zero canary: a stray NUL from an off-by-one terminator is invisible
     against a zero fill, which is the exact bug a capacity check guards. */
  memset(cookie.data, 'C', sizeof(cookie.data));
  cookie.max_len = cap;
  cookie.data[0] = '\0';

  memset(big, 'v', sizeof(big) - 1);
  big[sizeof(big) - 1] = '\0';

  /* Far past the capacity: refused, and nothing written. */
  if (cookie_add(&cookie, NAME, big, DOM, PATH) == 0) {
    printf("cookie-cap: FAIL (a value %u bytes long was accepted into %u)\n",
           (unsigned) strlen(big), (unsigned) cap);
    err = 1;
  }
  if (cookie.data[0] != '\0') {
    printf("cookie-cap: FAIL (the store was written despite the refusal)\n");
    err = 1;
  }
  for (i = cap; i < sizeof(cookie.data); i++) {
    if (cookie.data[i] != 'C') {
      printf("cookie-cap: FAIL (byte %u past max_len was modified)\n",
             (unsigned) i);
      err = 1;
      break;
    }
  }

  /* The exact boundary, derived rather than hardcoded so it survives a change
     to the fixture strings: cookie_add reserves 256 bytes beyond the parts. */
  {
    const size_t fixed = strlen(NAME) + strlen(DOM) + strlen(PATH) + 256;
    const size_t fits = cap - fixed;

    /* Exactly filling max_len is accepted... */
    memset(big, 'v', fits);
    big[fits] = '\0';
    cookie.data[0] = '\0';
    if (cookie_add(&cookie, NAME, big, DOM, PATH) != 0) {
      printf("cookie-cap: FAIL (a value of %u, exactly max_len, was refused)\n",
             (unsigned) fits);
      err = 1;
    } else if (strlen(cookie.data) == 0 || strlen(cookie.data) >= cap) {
      printf("cookie-cap: FAIL (accepted, store is %u against max_len %u)\n",
             (unsigned) strlen(cookie.data), (unsigned) cap);
      err = 1;
    }

    /* ...and one byte more is not. */
    memset(big, 'v', fits + 1);
    big[fits + 1] = '\0';
    cookie.data[0] = '\0';
    if (cookie_add(&cookie, NAME, big, DOM, PATH) == 0) {
      printf(
          "cookie-cap: FAIL (a value of %u, one past max_len, was accepted)\n",
          (unsigned) (fits + 1));
      err = 1;
    } else if (cookie.data[0] != '\0') {
      printf("cookie-cap: FAIL (the store was written despite the refusal)\n");
      err = 1;
    }
  }

  /* The canary again, after the accepted write: an insert bounded by
     sizeof(data) rather than max_len would show up here. */
  for (i = cap; i < sizeof(cookie.data); i++) {
    if (cookie.data[i] != 'C') {
      printf("cookie-cap: FAIL (byte %u past max_len was modified)\n",
             (unsigned) i);
      err = 1;
      break;
    }
  }

  printf("cookie-cap: %s\n", err ? "FAIL" : "OK");
  return err;
}

static int st_ioexact(httrackp *opt, int argc, char **argv) {
  const size_t payload_size = 70000; /* past any stdio buffer */
  const unsigned char poison = 0xa5;
  char path[HTS_URLMAXSIZE * 2];
  char *payload, *readback;
  FILE *fp;
  int plen;
  size_t i;

  (void) opt;
  if (argc < 1) {
    fprintf(stderr, "ioexact: needs a writable dir\n");
    return 1;
  }
  plen = snprintf(path, sizeof(path), "%s/ioexact.bin", argv[0]);
  assertf(plen > 0 && (size_t) plen < sizeof(path));
  payload = malloct(payload_size);
  readback = malloct(payload_size + 1);
  for (i = 0; i < payload_size; i++)
    payload[i] = (char) (i * 7 + (i >> 8));

  /* Round trip: a helper that swapped fwrite's size and nmemb would report a
     count of 1 here and die. */
  fp = FOPEN(path, "wb");
  assertf(fp != NULL);
  assertf(hts_fwrite_exact(payload, payload_size, fp) == HTS_TRUE);
  assertf(fclose(fp) == 0);
  memset(readback, poison, payload_size + 1);
  fp = FOPEN(path, "rb");
  assertf(fp != NULL);
  assertf(hts_fread_exact(readback, payload_size, fp) == HTS_TRUE);
  assertf(memcmp(readback, payload, payload_size) == 0);
  assertf((unsigned char) readback[payload_size] == poison);
  assertf(hts_fread_exact(readback, 1, fp) == HTS_FALSE); /* at EOF */
  assertf(hts_fread_exact(readback, 0, fp) == HTS_TRUE);
  assertf(fclose(fp) == 0);

  /* Short read: four of the eight bytes asked for, so a failure, and the tail
     of the destination keeps its poison. */
  fp = FOPEN(path, "wb");
  assertf(fp != NULL);
  assertf(hts_fwrite_exact(payload, 4, fp) == HTS_TRUE);
  assertf(fclose(fp) == 0);
  memset(readback, poison, 16);
  fp = FOPEN(path, "rb");
  assertf(fp != NULL);
  assertf(hts_fread_exact(readback, 8, fp) == HTS_FALSE);
  assertf(memcmp(readback, payload, 4) == 0);
  for (i = 4; i < 16; i++)
    assertf((unsigned char) readback[i] == poison);
  assertf(fclose(fp) == 0);

  /* Wrong direction: an I/O error is a failure, not a silent no-op. */
  fp = FOPEN(path, "wb");
  assertf(fp != NULL);
  assertf(hts_fread_exact(readback, 4, fp) == HTS_FALSE);
  assertf(fclose(fp) == 0);
  fp = FOPEN(path, "rb");
  assertf(fp != NULL);
  assertf(hts_fwrite_exact(payload, 4, fp) == HTS_FALSE);
  assertf(hts_fwrite_exact(payload, 0, fp) == HTS_TRUE);
  assertf(fclose(fp) == 0);

  /* Short WRITE: the cases above only ever get 0 back, so a helper accepting
     any non-zero count survives them. fmemopen's buffer is smaller than the
     payload, which yields a partial count instead. */
#if !defined(_WIN32)
  {
    char small[8];
    /* Short by many, then by exactly one: only the second catches a helper
       that accepts an off-by-one count. */
    const size_t over[2] = {sizeof(small) * 2, sizeof(small) + 1};

    for (i = 0; i < 2; i++) {
      /* Unbuffered, or stdio takes the whole payload and reports the overflow
         only at flush, leaving fwrite's own count complete. */
      FILE *mem = fmemopen(small, sizeof(small), "wb");

      if (mem != NULL && setvbuf(mem, NULL, _IONBF, 0) == 0)
        assertf(hts_fwrite_exact(payload, over[i], mem) == HTS_FALSE);
      if (mem != NULL)
        (void) fclose(mem);
    }
  }
#endif

  /* A zero size must leave dest alone rather than write a terminator. */
  memset(readback, poison, 4);
  fp = FOPEN(path, "rb");
  assertf(fp != NULL);
  assertf(hts_fread_exact(readback, 0, fp) == HTS_TRUE);
  for (i = 0; i < 4; i++)
    assertf((unsigned char) readback[i] == poison);
  assertf(hts_fread_exact(NULL, 0, fp) == HTS_TRUE);
  assertf(fclose(fp) == 0);

  assertf(UNLINK(path) == 0);
  freet(payload);
  freet(readback);
  printf("ioexact: a partial transfer is a failure: OK\n");
  return 0;
}

static int joker_class_end(const char *joker, char right) {
  const int len = (int) strlen(joker);
  int i = 2;

  while (i < len && joker[i] != right)
    i++;
  return i;
}

static void append_custom_headers(buff_struct *bstr, const char *headers) {
  const size_t base = bstr->pos;
  hts_boolean keep = HTS_TRUE;
  const char *line;

  for (line = headers; *line != '\0';) {
    const char *eol = line;
    const char *next;

    while (*eol != '\0' && *eol != '\r' && *eol != '\n')
      eol++;
    next = eol;
    if (next[0] == '\r' && next[1] == '\n')
      next += 2;
    else if (*next != '\0')
      next++;

    if (*line != ' ' && *line != '\t') { /* not a folded continuation */
      const char *colon = line;
      char field[128];

      keep = HTS_TRUE;
      while (colon < eol && *colon != ':')
        colon++;
      if (colon > line && colon < eol &&
          (size_t) (colon - line) < sizeof(field)) {
        const size_t len = (size_t) (colon - line);
        const char cut = bstr->buffer[base];

        memcpy(field, line, len);
        field[len] = '\0';
        /* only what the engine wrote, so the box may repeat its own fields */
        bstr->buffer[base] = '\0';
        keep = !http_headers_have_field(bstr->buffer, field);
        bstr->buffer[base] = cut;
      }
    }
    if (keep)
      print_buffer(bstr, "%.*s", (int) (next - line), line);
    line = next;
  }
}

void http_append_custom_headers(char *dst, size_t dst_size,
                                const char *headers) {
  buff_struct bstr = {dst, dst_size, 0};

  assertf(dst != NULL && dst_size > 0);
  bstr.pos = strlen(dst);
  append_custom_headers(&bstr, headers);
}

static int st_headerdedup(httrackp *opt, int argc, char **argv) {
  const size_t half = 8192;
  char *req, *tmp, *headers;
  const char *appended;
  size_t i, reqlen, blocklen;

  (void) opt;
  if (argc < 2) {
    fprintf(stderr, "headerdedup: needs a request and a header block\n");
    return 1;
  }
  req = malloct(2 * half);
  tmp = malloct(half);
  reqlen = st_decode_body(argv[0], req, half);
  blocklen = st_decode_body(argv[1], tmp, half);
  /* st_decode_body clips, and a clipped case grades an input nobody wrote */
  if (reqlen + 1 >= half || blocklen + 1 >= half) {
    fprintf(stderr, "headerdedup: argument longer than %d bytes\n",
            (int) half - 2);
    freet(tmp);
    freet(req);
    return 1;
  }
  appended = req + reqlen;
  /* exact-size copy so a sanitizer traps an over-read of the block */
  headers = strdupt(tmp);
  freet(tmp);
  http_append_custom_headers(req, 2 * half, headers);
  for (i = 0; appended[i] != '\0'; i++) {
    if (appended[i] == '\r')
      printf("\\r");
    else if (appended[i] == '\n')
      printf("\\n");
    else
      putchar(appended[i]);
  }
  printf("\n");
  freet(headers);
  freet(req);
  return 0;
}

hts_boolean http_headers_have_field(const char *headers,
                                    const char *field_name) {
  size_t len;
  const char *line;

  if (headers == NULL || field_name == NULL)
    return HTS_FALSE;
  len = strlen(field_name);
  if (len != 0 && field_name[len - 1] == ':') /* the tree spells it both ways */
    len--;
  if (len == 0)
    return HTS_FALSE;
  /* anchored, so a folded line or a name inside a value cannot match */
  for (line = headers; *line != '\0';) {
    size_t i = 0;

    while (i < len && streql(line[i], field_name[i]))
      i++;
    /* RFC 7230 forbids a space before the colon: tolerating one would drop our
       line for a malformed one the server then ignores */
    if (i == len && line[len] == ':')
      return HTS_TRUE;
    while (*line != '\0' && *line != '\n' && *line != '\r')
      line++;
    while (*line == '\n' || *line == '\r')
      line++;
  }
  return HTS_FALSE;
}

static int st_headerfield(httrackp *opt, int argc, char **argv) {
  char *headers, *field;

  (void) opt;
  if (argc < 2) {
    fprintf(stderr, "headerfield: needs a header block and a field name\n");
    return 1;
  }
  /* exact-size heap copies so a sanitizer traps an over-read */
  headers = strdupt(argv[0]);
  field = strdupt(argv[1]);
  printf("%s\n",
         http_headers_have_field(headers, field) ? "present" : "absent");
  freet(headers);
  freet(field);
  return 0;
}

static const char *ini_value_of(const char *name) {
  intptr_t adr = 0;

  return coucal_readptr(NewLangList, name, &adr) && adr != 0
             ? (const char *) adr
             : "";
}

static void ini_publish_gated_values(void) {
  size_t i;

  for (i = 0; ini_gated_values[i].value != NULL; i++) {
    const hts_boolean on = *ini_value_of(ini_gated_values[i].gate) != '\0';
    char name[64];

    snprintf(name, sizeof(name), "%s_eff", ini_gated_values[i].value);
    coucal_write(
        NewLangList, name,
        (intptr_t) strdup(on ? ini_value_of(ini_gated_values[i].value) : ""));
  }
}

static hts_boolean topindex_commit(httrackp *opt, const char *tmp,
                                   const char *dst) {
#ifdef _WIN32
  char *tmp_utf8 = hts_convertStringSystemToUTF8(tmp, strlen(tmp));
  char *dst_utf8 = hts_convertStringSystemToUTF8(dst, strlen(dst));
  const hts_boolean moved =
      hts_rename_over(opt, tmp_utf8 != NULL ? tmp_utf8 : tmp,
                      dst_utf8 != NULL ? dst_utf8 : dst);
  /* the caller logs with LOG_ERRNO, and freet() may clobber errno */
  const int err = errno;

  freet(tmp_utf8);
  freet(dst_utf8);
  errno = err;
  return moved;
#else
  return hts_rename_over(opt, tmp, dst);
#endif
}

static int ini_list_shift(const char *value, size_t len, int delta) {
  char digits[16];
  char *end;
  long id;

  if (len == 0 || len >= sizeof(digits))
    return -1;
  memcpy(digits, value, len);
  digits[len] = '\0';
  id = strtol(digits, &end, 10);
  if (*end != '\0' || id < 0 || id > INT_MAX - 1)
    return -1;
  return (int) id + delta;
}

static void ini_rebase_lists(const char *ini, int delta, String *out) {
  const char *line;

  StringClear(*out);
  for (line = ini; *line != '\0';) {
    const char *const nl = strchr(line, '\n');
    const size_t len = nl != NULL ? (size_t) (nl - line) + 1 : strlen(line);
    const char *const eq = (const char *) memchr(line, '=', len);
    char key[64];
    char shifted[16];
    size_t klen = 0;
    size_t vlen = 0;
    int id = -1;

    if (eq != NULL) {
      klen = (size_t) (eq - line);
      vlen = len - klen - 1;
      /* Trim the CRLF a textarea posts, which the file keeps. */
      while (vlen != 0 && (eq[vlen] == '\r' || eq[vlen] == '\n'))
        vlen--;
      if (klen < sizeof(key)) {
        memcpy(key, line, klen);
        key[klen] = '\0';
        if (ini_key_is_list(key))
          id = ini_list_shift(eq + 1, vlen, delta);
      }
    }
    if (id >= 0) {
      snprintf(shifted, sizeof(shifted), "%d", id);
      StringMemcat(*out, line, klen + 1);
      StringCat(*out, shifted);
      StringMemcat(*out, eq + 1 + vlen, len - klen - 1 - vlen);
    } else {
      StringMemcat(*out, line, len);
    }
    line += len;
  }
}

void hts_addurl_free(char **url) {
  if (url != NULL) {
    size_t i;

    for (i = 0; url[i] != NULL; i++) {
      freet(url[i]);
    }
    freet(url);
  }
}

static char **hts_addurl_swap_(httrackp *opt, char **url) {
  char **const old = opt->state._hts_addurl;

  opt->state._hts_addurl = url;
  return old;
}

char **hts_addurl_take(httrackp *opt) {
  char **old;

  hts_mutexlock(&opt->state.lock);
  old = hts_addurl_swap_(opt, NULL);
  hts_mutexrelease(&opt->state.lock);
  return old;
}

static size_t cat_html_ncr(String *dst, const char *s) {
  const unsigned char *const p = (const unsigned char *) s;
  unsigned int uc;
  size_t extra, i;
  char tmp[16];

  if (p[0] >= 0xc2 && p[0] <= 0xdf) {
    uc = p[0] & 0x1f;
    extra = 1;
  } else if ((p[0] & 0xf0) == 0xe0) {
    uc = p[0] & 0x0f;
    extra = 2;
  } else if (p[0] >= 0xf0 && p[0] <= 0xf4) {
    uc = p[0] & 0x07;
    extra = 3;
  } else {
    return 0;
  }
  /* A NUL fails this before the next byte is read, so a sequence truncated at
     the end of the string cannot run past it. */
  for (i = 1; i <= extra; i++) {
    if ((p[i] & 0xc0) != 0x80)
      return 0;
    uc = (uc << 6) | (p[i] & 0x3f);
  }
  /* Overlong and surrogate forms name nothing a browser will render. */
  if (uc < 0x80 || (uc >= 0xd800 && uc <= 0xdfff))
    return 0;
  snprintf(tmp, sizeof(tmp), "&#%u;", uc);
  StringCat(*dst, tmp);
  return extra + 1;
}

static void tmpl_catn(char *d, size_t dsize, const char *s, size_t n) {
  size_t i = strlen(d);

  if (i + 1 >= dsize) /* nothing fits, and d already carries its NUL */
    return;
  for (; *s != '\0' && n != 0 && i + 1 < dsize; n--)
    d[i++] = *s++;
  d[i] = '\0';
}

static void tmpl_catc(char *d, size_t dsize, char c) {
  char s[2];

  s[0] = c;
  s[1] = '\0';
  tmpl_catn(d, dsize, s, 1);
}

hts_boolean socinput(T_SOC soc, char *s, int max) {
  hts_boolean cut = HTS_FALSE;
        if (j < max - 1)
          s[j++] = (char) c;
        else
          cut = HTS_TRUE; // keep draining: the tail is not a new line
  }

static int st_binputline(httrackp *opt, int argc, char **argv) {
  static const char fixture[] = "Disallow: 0123456789abcdefghij\n"
                                "Allow: /open/\n";
  char block[256], line[64];
  size_t blocklen;
  int max, ptr = 0, i;

  (void) opt;
  if (argc < 1) {
    fprintf(stderr, "binputline: needs a read size\n");
    return 1;
  }
  max = atoi(argv[0]);
  if (max < 1 || (size_t) max >= sizeof(line)) {
    fprintf(stderr, "binputline: read size out of probe range\n");
    return 1;
  }
  if (argc < 2) {
    memcpy(block, fixture, sizeof(fixture));
    blocklen = sizeof(fixture) - 1;
  } else {
    const char *a = argv[1];

    if (strlen(a) >= sizeof(block)) {
      fprintf(stderr, "binputline: block too long\n");
      return 1;
    }
    for (blocklen = 0; *a != '\0'; a++) {
      if (*a == '\\' && a[1] == 'n')
        block[blocklen++] = '\n', a++;
      else if (*a == '\\' && a[1] == 'r')
        block[blocklen++] = '\r', a++;
      else
        block[blocklen++] = *a;
    }
    block[blocklen] = '\0';
  }
  /* one read past the block, to show the walk stops on its terminating NUL */
  for (i = 0; i < 3; i++) {
    const int adv = binput(block + ptr, line, max);

    printf("adv=%d line=%s\n", adv, line);
    ptr += adv;
    if (ptr > (int) blocklen)
      ptr = (int) blocklen;
  }
  return 0;
}

static void cat_list_option(String *output, const char *label, int id,
                            int listDefault, int listHidden) {
  char tag[48];

  if (id == listHidden) {
    return;
  }
  snprintf(tag, sizeof(tag), "<option value=%d%s>", id,
           id == listDefault ? " selected" : "");
  StringCat(*output, tag);
  StringCat(*output, label);
  StringCat(*output, "</option>\r\n");
}

static char *st_batch_slurp(size_t *size) {
  size_t capa = 65536, len = 0;
  char *buff = malloct(capa);

  if (buff == NULL)
    return NULL;
  for (;;) {
    size_t n;

    if (len + 1 >= capa) {
      char *grown;

      if (capa > (size_t) -1 / 2) {
        freet(buff);
        return NULL;
      }
      grown = realloct(buff, capa * 2);
      if (grown == NULL) {
        freet(buff);
        return NULL;
      }
      buff = grown;
      capa *= 2;
    }
    n = fread(&buff[len], 1, capa - len - 1, stdin);
    if (n == 0) {
      /* Else a read error reads as EOF, and the tail of the script is dropped
         as silently as if it had never been written. */
      if (ferror(stdin)) {
        freet(buff);
        return NULL;
      }
      break;
    }
    len += n;
  }
  buff[len] = '\0';
  *size = len;
  return buff;
}

static int st_batch_nargs(const char *field) {
  char *tail;
  long n;

  errno = 0;
  n = strtol(field, &tail, 10);
  if (field[0] == '\0' || *tail != '\0' || errno != 0 || n < 0 ||
      n > ST_BATCH_MAXARGS)
    return -1;
  return (int) n;
}

static char *st_batch_field(char **pos, const char *end) {
  char *const field = *pos;

  if (field >= end)
    return NULL;
  *pos = field + strlen(field) + 1;
  return field;
}

static httrackp *st_batch_opt(const httrackp *from) {
  httrackp *const opt = hts_create_opt();

  StringCopy(opt->path_html, StringBuff(from->path_html));
  StringCopy(opt->path_html_utf8, StringBuff(from->path_html_utf8));
  StringCopy(opt->path_log, StringBuff(from->path_log));
  StringCopy(opt->path_bin, StringBuff(from->path_bin));
  opt->dir_topindex = from->dir_topindex;
  opt->quiet = from->quiet;
  opt->verbosedisplay = from->verbosedisplay;
  return opt;
}

static int st_batch(httrackp *opt, int argc, char **argv) {
  char *buff, *pos;
  const char *end;
  char *field;
  size_t len = 0;
  int err = 0;

  (void) argc;
  (void) argv;
  buff = st_batch_slurp(&len);
  if (buff == NULL) {
    fprintf(stderr, "batch: could not read the script on stdin\n");
    return 1;
  }
  pos = buff;
  end = &buff[len];
  while (!err && (field = st_batch_field(&pos, end)) != NULL) {
    const int nargs = st_batch_nargs(field);
    char *const name = st_batch_field(&pos, end);
    char **args;
    int i, code;

    if (nargs < 0 || name == NULL) {
      fprintf(stderr, "batch: malformed case header\n");
      err = 1;
      break;
    }
    args = calloct((size_t) nargs + 1, sizeof(char *));
    if (args == NULL) {
      fprintf(stderr, "batch: not enough memory\n");
      err = 1;
      break;
    }
    for (i = 0; i < nargs; i++) {
      args[i] = st_batch_field(&pos, end);
      if (args[i] == NULL) {
        fprintf(stderr, "batch: case '%s' is missing arguments\n", name);
        err = 1;
        break;
      }
    }
    if (err) {
      freet(args);
      break;
    }
    /* Nesting would re-read a stdin already at EOF and silently run nothing. */
    if (strcmp(name, "batch") == 0) {
      fprintf(stderr, "batch: cannot nest\n");
      code = 1;
    } else {
      httrackp *const copt = st_batch_opt(opt);

      code = hts_selftest(copt, name, nargs, args);
      hts_free_opt(copt);
    }
    freet(args);
    fflush(stdout);
    printf(ST_BATCH_RS "%d" ST_BATCH_RS, code);
    fflush(stdout);
  }
  freet(buff);
  return err;
}

static void makeindex_run(httrackp *opt, const char *path, const char *footer,
                          int links, const char *firstlink, char *buf,
                          size_t size) {
  FILE *fp = fopen(path, "wb");
  int done = 0;
  hts_finish_makeindex(opt, &done, &fp, links, firstlink, footer, "", "");
  n = fread(buf, 1, size - 1, fp);
}

static char *makeindex_slurp(const char *path) {
  FILE *fp = fopen(path, "rb");
  long size;
  char *buf;

  if (fp == NULL)
    return NULL;
  assertf(fseek(fp, 0, SEEK_END) == 0);
  size = ftell(fp);
  assertf(size >= 0);
  rewind(fp);
  buf = malloct((size_t) size + 1);
  /* a read error would otherwise render a silently truncated template */
  assertf(fread(buf, 1, (size_t) size, fp) == (size_t) size);
  buf[size] = '\0';
  fclose(fp);
  return buf;
}

static hts_boolean makeindex_outside_comment(const char *buf, const char *at) {
  const char *open = NULL, *close = NULL, *p;

  for (p = buf; (p = strstr(p, "<!--")) != NULL && p < at; p += 4)
    open = p;
  for (p = buf; (p = strstr(p, "-->")) != NULL && p < at; p += 3)
    close = p;
  return open == NULL || (close != NULL && close > open) ? HTS_TRUE : HTS_FALSE;
}

static void makeindex_template_contract(const char *name, const char *tmpl,
                                        size_t slots) {
  size_t i, n;

  for (i = 0, n = 0; tmpl[i] != '\0'; i++) {
    if (tmpl[i] != '%')
      continue;
    if (tmpl[i + 1] == 's')
      n++;
    else if (tmpl[i + 1] != '%') {
      fprintf(stderr, "%s: stray %%%c escape\n", name, tmpl[i + 1]);
      assertf(!"built-in template carries an escape that is neither %s nor %%");
    }
    i++;
  }
  if (n != slots) {
    fprintf(stderr, "%s: %d %%s slots, expected %d\n", name, (int) n,
            (int) slots);
    assertf(!"built-in template slot count drifted from its caller");
  }
}

static int st_makeindex(httrackp *opt, int argc, char **argv) {
  /* the minimal template is the control: it proves an assertion below can only
     fail on the real one because that template lost a slot */
  const char *footers[] = {"%s%s", HTS_INDEX_FOOTER, NULL};
  size_t nfooters = sizeof(footers) / sizeof(*footers) - 1;
  char *ondisk = NULL;
  char path[HTS_URLMAXSIZE];
  char BIGSTK buf[8192];
  size_t t;
  assertf(argc >= 1);
  snprintf(path, sizeof(path), "%s/index.html", argv[0]);

  /* heap-allocated so a sanitizer sees an overrun, and poisoned so the stray
     NUL one writes cannot pass for the terminator */
    char *trailing = strdupt("credit %s, then a stray %");
    const char *const want = "credit X, then a stray %";
    char out[64];
    size_t i;
    memset(out, 'Z', sizeof(out));
    assertf(hts_template_format_str(out, sizeof(out), trailing, "X", NULL) >=
            0);
    assertf(strcmp(out, want) == 0);
    for (i = strlen(want) + 1; i < sizeof(out); i++)
      assertf(out[i] == 'Z');
    freet(trailing);
  }

hts_boolean hts_scan_token(char **ptr, char *dest, size_t destsize) {
  char *a = *ptr;
  size_t len = 0; /* the token's real length, which may exceed the room */

  assertf(destsize != 0);
  while (*a != '\0' && !isspace((unsigned char) *a)) {
    if (len < destsize - 1)
      dest[len] = *a;
    len++;
    a++;
  }
  dest[len < destsize ? len : destsize - 1] = '\0';
  while (isspace((unsigned char) *a))
    a++;
  *ptr = a;
  return len < destsize ? HTS_TRUE : HTS_FALSE;
}

static hts_boolean st_scantoken_run(char *src, size_t destsize, char *arena,
                                    size_t guard, hts_boolean *fit,
                                    size_t *advance) {
  char *p = src;
  size_t i;

  /* poisoned with '#', not 0, or the stray NUL of an off-by-one would read as
     untouched */
  memset(arena, '#', destsize + guard);
  *fit = hts_scan_token(&p, arena, destsize);
  *advance = (size_t) (p - src);
  for (i = destsize; i < destsize + guard; i++) {
    if (arena[i] != '#')
      return HTS_FALSE;
  }
  return HTS_TRUE;
}

static int st_scantoken(httrackp *opt, int argc, char **argv) {
  /* the engine's own filter bound, and a small one the same code must honour */
  const size_t caps[] = {8, HTS_URLMAXSIZE * 2 - 1};
  const size_t guard = 64;
  size_t c;

  (void) opt;
  (void) argc;
  (void) argv;
  for (c = 0; c < sizeof(caps) / sizeof(caps[0]); c++) {
    const size_t destsize = caps[c];
    const size_t room = destsize - 1; /* characters, the NUL aside */
    /* empty, short, and the four lengths that straddle the bound */
    const size_t lens[] = {0, 1, room - 1, room, room + 1, room + guard};
    char *arena = malloct(destsize + guard);
    char *src = malloct(room + guard + 8);
    size_t k;

    assertf(arena != NULL && src != NULL);
    for (k = 0; k < sizeof(lens) / sizeof(lens[0]); k++) {
      const size_t len = lens[k];
      const size_t kept = len < room ? len : room;
      hts_boolean fit;
      size_t advance, i;

      /* the token, the whitespace run after it, and the token to land on. Its
         bytes vary, or a copy landing on the wrong index would still match */
      for (i = 0; i < len; i++)
        src[i] = (char) ('a' + i % 26);
      memcpy(src + len, " \tb", 4);
      assertf(st_scantoken_run(src, destsize, arena, guard, &fit, &advance));
      assertf(fit == (len <= room ? HTS_TRUE : HTS_FALSE));
      assertf(strlen(arena) == kept && memcmp(arena, src, kept) == 0);
      assertf(advance == len + 2);

      /* the same token ending the string: the cursor stops on its NUL */
      src[len] = '\0';
      assertf(st_scantoken_run(src, destsize, arena, guard, &fit, &advance));
      assertf(fit == (len <= room ? HTS_TRUE : HTS_FALSE));
      assertf(strlen(arena) == kept && memcmp(arena, src, kept) == 0);
      assertf(advance == len);
    }
    freet(arena);
    freet(src);
  }
  printf("scantoken self-test OK\n");
  return 0;
}

static void wizardfilter_want(htsbuff *w, int n, const char *adr,
                              const char *fil, hts_boolean up) {
  htsbuff_cpy(w, n <= 2 ? "-" : "+");
  htsbuff_cat(w, adr);
  if (n == 2 || n == 6 || (n == 5 && up)) {
    htsbuff_cat(w, "/*");
    return;
  }
  if (*fil != '/')
    htsbuff_cat(w, "/");
  htsbuff_cat(w, fil);
  if (n == 1 || n == 5)
    htsbuff_cat(w, "*");
  else if (n == 7)
    htsbuff_cat(w, HTS_WIZARD_FILTER_SUFFIX);
}

static void wizardfilter_link(char *adr, size_t adrlen, char *fil,
                              size_t fillen, hts_boolean slash) {
  memset(adr, 'a', adrlen);
  adr[adrlen] = '\0';
  memset(fil, 'b', fillen);
  fil[0] = slash ? '/' : 'b';
  fil[fillen - 1] = '/';
  fil[fillen] = '\0';
}

static size_t wizardfilter_emits(htsbuff *f, char *expect, const char *adr,
                                 const char *fil) {
  static const int answers[] = {0, 1, 2, 5, 6, 7};
  size_t i, up, longest = 0;

  for (i = 0; i < sizeof(answers) / sizeof(answers[0]); i++) {
    for (up = 0; up < 2; up++) {
      const hts_boolean seek = up != 0 ? HTS_TRUE : HTS_FALSE;
      htsbuff w = htsbuff_ptr(expect, HTS_FILTER_SLOT_SIZE);

      wizardfilter_want(&w, answers[i], adr, fil, seek);
      hts_wizard_answer_filter(f, 0, answers[i], adr, fil, seek);
      assertf(strcmp(f->buf, expect) == 0);
      longest = f->len > longest ? f->len : longest;
    }
  }
  return longest;
}

static int fast_header_selftest(httrackp *opt, const char *location) {
  const char *const adr = "example.com";
  const char *const fil = "/moved-fast";
  cache_back cache;
  htsblk r;
  char *locbuf = malloct(HTS_LOCATION_SIZE);
  char *want = malloct(HTS_LOCATION_SIZE + 32);
  intptr_t stored = 0;
  int fail = 0;

  selftest_open_for_write(&cache, opt);
  cache.cached_tests = coucal_new(0);
  assertf(cache.cached_tests != NULL);
  coucal_value_is_malloc(cache.cached_tests, 1);

  hts_init_htsblk(&r);
  r.statuscode = 301;
  r.size = 0;
  strcpybuff(r.msg, "Moved Permanently");
  strcpybuff(r.contenttype, "text/html");
  strlcpybuff(locbuf, location, HTS_LOCATION_SIZE);
  r.location = locbuf;
  r.is_write = 0;
  cache_mayadd(opt, &cache, &r, adr, fil, NULL);

  snprintf(want, HTS_LOCATION_SIZE + 32, "%d\n%s", (int) r.statuscode,
           location);
  if (!coucal_read(cache.cached_tests,
                   concat(OPT_GET_BUFF(opt), OPT_GET_BUFF_SIZE(opt), adr, fil),
                   &stored)) {
    fprintf(stderr, "%s: fast-header: nothing recorded for %s%s\n",
            selftest_tag, adr, fil);
    fail++;
  } else if (strcmp((const char *) stored, want) != 0) {
    fprintf(stderr, "%s: fast-header: recorded %d bytes, expected %d\n",
            selftest_tag, (int) strlen((const char *) stored),
            (int) strlen(want));
    fail++;
  }

  selftest_close(&cache);
  freet(locbuf);
  freet(want);
  return fail;
}

hts_boolean binput_header(const char *buff, const char *end, char *s, int max,
                          int *offset) {
  hts_boolean cut = HTS_FALSE;
  const char *p;
  int j = 0;

  *offset = 0;
  s[0] = '\0';
  if (buff == NULL || buff >= end)
    return HTS_FALSE;
  for (p = buff; p < end && *p != '\0' && *p != '\n'; p++) {
    if (*p == '\r')
      continue;
    if (j < max - 1)
      s[j++] = *p;
    else
      cut = HTS_TRUE; /* keep walking: the tail must not become more headers */
  }
  s[j] = '\0';
  *offset = (int) (p - buff) + 1; /* binput's convention: step over the \n */
  return cut;
}

hts_boolean finput_header(T_SOC fd, char *s, int max) {
  hts_boolean cut = HTS_FALSE;
  int j = 0;
  char c;

  for (;;) {
    if (read((int) fd, &c, 1) <= 0 || c == 10)
      break;
    if (c == 13)
      continue;
    if (j < max - 1)
      s[j++] = c;
    else
      cut = HTS_TRUE; /* keep draining: the tail must not become more headers */
  }
  s[j] = '\0';
  return cut;
}

static int st_headerline(httrackp *opt, int argc, char **argv) {
  static const char fixture[] = "X-First: 0123456789abcdefghij\r\n"
                                "X-Second: ok\r\n"
                                "\r\n";
  char block[256], line[64];
  size_t blocklen;
  int max, ptr = 0, i;

  (void) opt;
  if (argc < 1) {
    fprintf(stderr, "headerline: needs a read size\n");
    return 1;
  }
  max = atoi(argv[0]);
  if (max < 2 || (size_t) max > sizeof(line)) {
    fprintf(stderr, "headerline: read size out of probe range\n");
    return 1;
  }
  if (argc < 2) {
    memcpy(block, fixture, sizeof(fixture));
    blocklen = sizeof(fixture) - 1;
  } else {
    const char *a = argv[1];

    if (strlen(a) >= sizeof(block)) {
      fprintf(stderr, "headerline: block too long\n");
      return 1;
    }
    for (blocklen = 0; *a != '\0'; a++) {
      if (*a == '\\' && a[1] == 'n')
        block[blocklen++] = '\n', a++;
      else if (*a == '\\' && a[1] == 'r')
        block[blocklen++] = '\r', a++;
      else
        block[blocklen++] = *a;
    }
    block[blocklen] = '\0';
  }
  /* one read past the block's lines, to show the walk stops at its end */
  for (i = 0; i < 4; i++) {
    int adv;
    const hts_boolean cut =
        binput_header(block + ptr, block + blocklen, line, max, &adv);

    ptr += adv;
    printf("cut=%d over=%d line=%s\n", cut != HTS_FALSE,
           ptr > (int) blocklen + 1, line);
  }
  return 0;
}

static void st_location_log(httrackp *opt, int type, const char *format,
                            va_list args) {
  (void) opt;
  (void) type;
  (void) format;
  (void) args;
  st_location_logged++;
}

static int st_location(httrackp *opt, int argc, char **argv) {
  struct {
    char loc[HTS_LOCATION_SIZE];
    char canary[64];
  } probe;

  char BIGSTK line[HTS_LOCATION_SIZE + 1024];
  const char *const prefix = "http://www.example.com/";
  const char *url, *want;
  htsblk r;
  size_t n, urllen, kept, i;
  int asked, smashed = 0;

  (void) opt;
  if (argc < 1) {
    fprintf(stderr, "location: needs a Location URL length\n");
    return 1;
  }
  /* subtract, never add: a negative argument must not wrap the range check */
  asked = atoi(argv[0]);
  if (asked <= (int) strlen(prefix) ||
      (size_t) asked > sizeof(line) - sizeof("Location: ")) {
    fprintf(stderr, "location: length out of probe range\n");
    return 1;
  }
  urllen = (size_t) asked;

  memset(probe.loc, 0, sizeof(probe.loc));
  memset(probe.canary, '#', sizeof(probe.canary));
  memset(&r, 0, sizeof(r));
  r.location = probe.loc;

  n = (size_t) snprintf(line, sizeof(line), "Location: %s", prefix);
  memset(line + n, 'a', urllen - strlen(prefix));
  line[n + urllen - strlen(prefix)] = '\0';
  url = line + n - strlen(prefix);

  st_location_logged = 0;
  hts_set_log_vprint_callback(st_location_log);
  treathead(NULL, "www.example.com", "/", &r, line);
  hts_set_log_vprint_callback(NULL);

  for (i = 0; i < sizeof(probe.canary); i++) {
    if (probe.canary[i] != '#')
      smashed++;
  }
  /* bounded: an unterminated buffer reports capacity, never reads past it */
  for (kept = 0; kept < sizeof(probe.loc) && probe.loc[kept] != '\0'; kept++)
    ;
  /* the wanted value comes from the contract, not from what treathead did */
  want = urllen < HTS_LOCATION_SIZE ? url : "";
  printf("asked=%d kept=%d value_ok=%d canary_smashed=%d logged=%d\n", asked,
         (int) kept, strcmp(probe.loc, want) == 0, smashed,
         st_location_logged != 0);
  return 0;
}

tatic char *rb_bulk(size_t blobsize) {
  const size_t capa = blobsize * 2 + 4096;
  char *const txt = (char *) malloct(capa);
  size_t n, blob;
  int i;

  assertf(txt != NULL);
  n = (size_t) snprintf(txt, capa, "User-agent: *\n");
  for (i = 0, blob = 0; blob + 12 <= blobsize; i++, blob += 12) {
    assertf(i < 100000); // past that "/padNNNNNN/" costs 13, not 12
    n += (size_t) snprintf(txt + n, capa - n, "Disallow: /pad%05d/\n", i);
    assertf(n < capa);
  }
  n += (size_t) snprintf(txt + n, capa - n, "Allow: /pad00000/open/\n");
  assertf(n < capa);
  (void) snprintf(txt + n, capa - n, "Disallow: /secret/\n");
  return txt;
}

static size_t utf8_cut(const char *s, size_t len) {
  while (len > 0 && ((unsigned char) s[len] & 0xC0) == 0x80)
    len--;
  return len;
}

void url_savename_addtail(char *d, size_t dsize, const char *sep,
                          const char *s) {
  const size_t slen = strlen(sep) + strlen(s);

  if (slen + 1 > dsize) /* the tail alone does not fit: leave d alone */
    return;
  if (strlen(d) + slen + 1 > dsize)
    d[utf8_cut(d, dsize - slen - 1)] = '\0';
  strlcatbuff(d, sep, dsize);
  strlcatbuff(d, s, dsize);
}

static hts_boolean st_poison_intact(const char *label, const char *buf,
                                    size_t from, size_t size) {
  size_t i;

  for (i = size; i > from; i--) {
    if (buf[i - 1] != (char) ST_SAVENAME_POISON) {
      fprintf(stderr, "%s: wrote %d byte(s) past the end\n", label,
              (int) (i - from));
      return HTS_FALSE;
    }
  }
  return HTS_TRUE;
}

static int st_savename_addstr(httrackp *opt, int argc, char **argv) {
  static const struct {
    size_t dsize;
    const char *seed;
    const char *add;
    const char *want;
  } cases[] = {
      {8, "", "a\\b", "a/b"},
      {8, "ab/", "cd", "ab/cd"},
      {8, "", "abcdefg", "abcdefg"}, /* exact fit, NUL on the last byte */
      {8, "", "abcdefgh", "abcdefg"},
      {8, "", "abcdefghijklmnop", "abcdefg"},
      {8, "ab", "\\\\\\\\\\\\\\\\", "ab/////"}, /* clip inside a '\' run */
      {8, "abcdefg", "xy", "abcdefg"},
      {1, "", "abc", ""},
      {2, "", "a\\c", "a"},
      {4, "abcdefghij", "xy", "abcdefghij"}, /* seed past dsize: left alone */
      {0, "abc", "xy", "abc"},
  };

  /* last entry is the naming path's own destination, sizeof(afs->save) */
  static const size_t bigcaps[] = {64, 255, HTS_URLMAXSIZE, HTS_URLMAXSIZE * 2};
  char buf[64];
  size_t k;
  int rc = 0;

  (void) opt;
  (void) argc;
  (void) argv;
  for (k = 0; k < sizeof(cases) / sizeof(cases[0]); k++) {
    const size_t seedlen = strlen(cases[k].seed);
    /* the appender may write up to dsize, and never past a longer seed */
    const size_t guard =
        cases[k].dsize > seedlen + 1 ? cases[k].dsize : seedlen + 1;
    char label[64];

    snprintf(label, sizeof(label), "savename-addstr: '%s' at dsize %d",
             cases[k].add, (int) cases[k].dsize);
    memset(buf, ST_SAVENAME_POISON, sizeof(buf));
    memcpy(buf, cases[k].seed, seedlen + 1);
    url_savename_addstr(buf, cases[k].dsize, cases[k].add);
    if (strcmp(buf, cases[k].want) != 0) {
      fprintf(stderr, "savename-addstr: '%s' + '%s' (%d) -> '%s' want '%s'\n",
              cases[k].seed, cases[k].add, (int) cases[k].dsize, buf,
              cases[k].want);
      rc = 1;
    }
    if (!st_poison_intact(label, buf, guard, sizeof(buf)))
      rc = 1;
  }

  /* Oversized buffers, so an unclipped append lands on poison rather than
     smashing the stack. */
  for (k = 0; k < sizeof(bigcaps) / sizeof(bigcaps[0]); k++) {
    const size_t dsize = bigcaps[k];
    char BIGSTK src[HTS_URLMAXSIZE * 4];
    char BIGSTK big[sizeof(src) + ST_SAVENAME_CANARY];
    char label[64];

    snprintf(label, sizeof(label), "savename-addstr: long link at dsize %d",
             (int) dsize);
    memset(big, ST_SAVENAME_POISON, sizeof(big));
    big[0] = '\0';
    memset(src, 'a', sizeof(src) - 1);
    src[sizeof(src) - 1] = '\0';
    url_savename_addstr(big, dsize, src);
    if (strlen(big) != dsize - 1) {
      fprintf(stderr, "savename-addstr: dsize %d filled %d byte(s)\n",
              (int) dsize, (int) strlen(big));
      rc = 1;
    }
    if (!st_poison_intact(label, big, dsize, sizeof(big)))
      rc = 1;
  }

  printf("savename-addstr self-test %s\n", rc == 0 ? "OK" : "FAILED");
  return rc;
}

static int st_savename_addtail(httrackp *opt, int argc, char **argv) {
  static const struct {
    size_t dsize;
    const char *seed;
    const char *sep;
    const char *add;
    const char *want;
  } cases[] = {
      {16, "/a/", "", "index.html", "/a/index.html"}, /* room to spare */
      {16, "/aaaaa/", "", "index.html", "/aaaaindex.html"},
      {8, "/ab/", ".", "gz", "/ab/.gz"},  /* exact fit, no byte given up */
      {8, "/abc/", ".", "gz", "/abc.gz"}, /* one byte of middle gives way */
      {8, "abcdefg", "", "xy", "abcdexy"},
      {8, "abcdefg", ".", "html", "ab.html"}, /* the tail arrives whole */
      {8, "", ".", "html", ".html"},
      {6, "abc", ".", "html", ".html"}, /* the middle can give way entirely */
      {5, "abc", ".", "html", "abc"},   /* tail alone fills dsize: no-op */
      {0, "abc", "", "x", "abc"},
      /* the cut lands inside a 3-byte character and backs off it */
      {8, "a\342\202\254b", ".", "html", "a.html"},
      {10, "a\342\202\254b", ".", "html",
       "a\342\202\254.html"}, /* cut on a lead byte */
      {8, "\360\237\230\200x", ".", "gz",
       "\360\237\230\200.gz"},                    /* 4-byte kept */
      {7, "\360\237\230\200x", ".", "gz", ".gz"}, /* 4-byte cut away whole */
  };

  char buf[64];
  size_t k;
  int rc = 0;

  (void) opt;
  (void) argc;
  (void) argv;
  for (k = 0; k < sizeof(cases) / sizeof(cases[0]); k++) {
    const size_t seedlen = strlen(cases[k].seed);
    const size_t guard =
        cases[k].dsize > seedlen + 1 ? cases[k].dsize : seedlen + 1;
    char label[64];

    snprintf(label, sizeof(label), "savename-addtail: '%s%s' at dsize %d",
             cases[k].sep, cases[k].add, (int) cases[k].dsize);
    memset(buf, ST_SAVENAME_POISON, sizeof(buf));
    memcpy(buf, cases[k].seed, seedlen + 1);
    url_savename_addtail(buf, cases[k].dsize, cases[k].sep, cases[k].add);
    if (strcmp(buf, cases[k].want) != 0) {
      fprintf(stderr,
              "savename-addtail: '%s' + '%s%s' (%d) -> '%s' want '%s'\n",
              cases[k].seed, cases[k].sep, cases[k].add, (int) cases[k].dsize,
              buf, cases[k].want);
      rc = 1;
    }
    if (!st_poison_intact(label, buf, guard, sizeof(buf)))
      rc = 1;
  }

  /* A link filling the whole buffer still gets its extension. */
  {
    char BIGSTK big[HTS_URLMAXSIZE * 2 + ST_SAVENAME_CANARY];
    const size_t dsize = HTS_URLMAXSIZE * 2;

    memset(big, ST_SAVENAME_POISON, sizeof(big));
    memset(big, 'a', dsize - 1);
    big[dsize - 1] = '\0';
    url_savename_addtail(big, dsize, ".", "html");
    if (strlen(big) != dsize - 1 ||
        strcmp(big + dsize - 1 - strlen(".html"), ".html") != 0) {
      fprintf(stderr,
              "savename-addtail: full buffer kept %d byte(s), no .html\n",
              (int) strlen(big));
      rc = 1;
    }
    if (!st_poison_intact("savename-addtail: full buffer", big, dsize,
                          sizeof(big)))
      rc = 1;
  }

  /* The .test's pads are chosen against this size; printing it reds them when
     it moves rather than letting them quietly stop reaching the end. */
  printf("savename-addtail self-test %s, save %d bytes\n",
         rc == 0 ? "OK" : "FAILED", (int) (HTS_URLMAXSIZE * 2));
  return rc;
}

const char *hts_footer_field_list(char *buffer, size_t size) {
  htsbuff fields = htsbuff_ptr(buffer, size);
  size_t i;

  for (i = 0; i < HTS_FOOTER_FIELD_COUNT; i++) {
    if (i != 0)
      htsbuff_catc(&fields, ' ');
    htsbuff_catc(&fields, '{');
    htsbuff_cat(&fields, footer_field_names[i]);
    htsbuff_catc(&fields, '}');
  }
  return htsbuff_str(&fields);
}

static hts_boolean cookie_load_field(httrackp *opt, char *dst, size_t dst_size,
                                     char *buffer, const char *line, int param,
                                     const char *field_name, const char *file) {
  const char *const value = cookie_get(buffer, line, param);
  const size_t len = strlen(value);

  if (len >= dst_size) {
    hts_log_print(opt, LOG_WARNING,
                  "Cookies: ignoring a line whose %s field is %d bytes "
                  "(maximum %d): %s",
                  field_name, (int) len, (int) dst_size - 1, file);
    return HTS_FALSE;
  }
  strlcpybuff(dst, value, dst_size);
  return HTS_TRUE;
}

static void savebounds_path(char *s, size_t size, size_t len) {
  assertf(len >= 2);
  fill_str(s, size, len, 'd');
  s[0] = s[len - 1] = '/';
}

static int savebounds_expect(httrackp *opt, const char *path, const char *adr,
                             const char *fil, const char *want,
                             const char *body) {
  int failures = 0;
  cache_back cache;
  htsblk r;
  char *got = malloct(SAVEBOUNDS_CAP + SAVEBOUNDS_GUARD);
  size_t k;

  /* guard past the capacity the reader is handed, poisoned non-zero so a stray
     NUL shows up too */
  memset(got, SAVEBOUNDS_GUARD_BYTE, SAVEBOUNDS_CAP + SAVEBOUNDS_GUARD);
  got[0] = '\0';

  StringCopy(opt->path_html_utf8, path);
  selftest_open_for_read(&cache, opt);
  r = cache_readex(opt, &cache, adr, fil, "", NULL, got, 1);
  selftest_close(&cache);

  if (want != NULL) {
    if (r.statuscode != 200) {
      fprintf(stderr,
              "%s: html path of %d bytes: statuscode %d, expected 200 (%s)\n",
              selftest_tag, (int) strlen(path), r.statuscode, r.msg);
      failures++;
    }
    if (strcmp(got, want) != 0) {
      fprintf(stderr,
              "%s: html path of %d bytes: save name is %d bytes '%.48s...',"
              " expected %d bytes '%.48s...'\n",
              selftest_tag, (int) strlen(path), (int) strlen(got), got,
              (int) strlen(want), want);
      failures++;
    }
    if (r.adr == NULL || (size_t) r.size != strlen(body) ||
        memcmp(r.adr, body, strlen(body)) != 0) {
      fprintf(stderr, "%s: html path of %d bytes: body mismatch\n",
              selftest_tag, (int) strlen(path));
      failures++;
    }
  } else {
    if (r.statuscode != STATUSCODE_INVALID) {
      fprintf(stderr,
              "%s: html path of %d bytes: statuscode %d, expected the entry to"
              " be refused\n",
              selftest_tag, (int) strlen(path), r.statuscode);
      failures++;
    }
    /* the point of the refusal: a clipped name would name another file */
    if (got[0] != '\0') {
      fprintf(stderr,
              "%s: html path of %d bytes: refused entry still returns a %d-byte"
              " save name '%.48s...'\n",
              selftest_tag, (int) strlen(path), (int) strlen(got), got);
      failures++;
    }
    if (r.adr != NULL) {
      fprintf(stderr,
              "%s: html path of %d bytes: refused entry returns a body\n",
              selftest_tag, (int) strlen(path));
      failures++;
    }
  }
  for (k = SAVEBOUNDS_CAP; k < SAVEBOUNDS_CAP + SAVEBOUNDS_GUARD; k++) {
    if (got[k] != SAVEBOUNDS_GUARD_BYTE) {
      fprintf(stderr, "%s: html path of %d bytes: guard byte %d overwritten\n",
              selftest_tag, (int) strlen(path), (int) (k - SAVEBOUNDS_CAP));
      failures++;
      break;
    }
  }

  if (r.adr != NULL) {
    freet(r.adr);
  }
  freet(got);
  return failures;
}

static void savebounds_store(httrackp *opt, cache_back *cache, const char *adr,
                             const char *fil, const char *save,
                             const char *path_prefix, const char *body) {
  htsblk w;
  char locw[4];
  char *bodycopy = strdupt(body);

  hts_init_htsblk(&w);
  w.statuscode = 200;
  w.size = (LLint) strlen(body);
  strcpybuff(w.msg, "OK");
  strcpybuff(w.contenttype, "text/html");
  strcpybuff(w.charset, "utf-8");
  locw[0] = '\0';
  w.location = locw;
  w.is_write = 0;
  w.adr = bodycopy;
  cache_add(opt, cache, &w, adr, fil, save, 1, path_prefix);
  freet(bodycopy);
}

int cache_savename_bounds_selftest(httrackp *opt, const char *dir) {
  int failures = 0;
  cache_back cache;
  static const char rel_head[] = "example.com/";
  static const char rel_tail[] = ".html";
  const char *const adr = "example.com";
  const char *const fil = "/deep.html";
  /* second entry, stored with an absolute X-Save: exercises the branch that
     copies the stored name verbatim instead of prepending */
  const char *const flat_fil = "/flat.html";
  static const char body[] = "<html><body>deep</body></html>";
  static const char flat_body[] = "<html><body>flat</body></html>";
  static char rel[SAVEBOUNDS_REL_LEN + 1];
  /* the rebuilt name ends on the last byte that fits, then one byte past it */
  static char path_fit[SAVEBOUNDS_CAP], path_over[SAVEBOUNDS_CAP];
  /* the html path the issue reported against */
  static char path_huge[SAVEBOUNDS_CAP];
  char BIGSTK writepath[HTS_URLMAXSIZE * 2];
  char BIGSTK save[HTS_URLMAXSIZE * 2];
  char BIGSTK flat_save[HTS_URLMAXSIZE * 2];
  /* concat() refuses a result that only just fits, and the longest expected
     name here is exactly SAVEBOUNDS_CAP - 1 bytes */
  char BIGSTK expected[SAVEBOUNDS_CAP + 8];

  selftest_tag = "cache-savebounds";
  selftest_setup_dir(opt, dir);
  strcpybuff(writepath, StringBuff(opt->path_html_utf8));

  memset(rel, 'p', SAVEBOUNDS_REL_LEN);
  rel[SAVEBOUNDS_REL_LEN] = '\0';
  memcpy(rel, rel_head, sizeof(rel_head) - 1);
  memcpy(rel + SAVEBOUNDS_REL_LEN - (sizeof(rel_tail) - 1), rel_tail,
         sizeof(rel_tail) - 1);
  savebounds_path(path_fit, sizeof(path_fit),
                  SAVEBOUNDS_CAP - 1 - SAVEBOUNDS_REL_LEN);
  savebounds_path(path_over, sizeof(path_over),
                  SAVEBOUNDS_CAP - SAVEBOUNDS_REL_LEN);
  savebounds_path(path_huge, sizeof(path_huge), 1500);
  concat(save, sizeof(save), writepath, rel);
  concat(flat_save, sizeof(flat_save), writepath, "example.com/flat.html");

  selftest_open_for_write(&cache, opt);
  savebounds_store(opt, &cache, adr, fil, save, writepath, body);
  savebounds_store(opt, &cache, adr, flat_fil, flat_save, NULL, flat_body);
  selftest_close(&cache);

  /* same html path as the write: the stripped prefix goes back on unchanged */
  failures += savebounds_expect(opt, writepath, adr, fil, save, body);
  /* an absolute stored name is used as-is, not prefixed a second time */
  failures +=
      savebounds_expect(opt, writepath, adr, flat_fil, flat_save, flat_body);

  /* deeper path, rebuilt name still fits to the last byte */
  concat(expected, sizeof(expected), path_fit, rel);
  failures += savebounds_expect(opt, path_fit, adr, fil, expected, body);

  /* one byte past: refuse and re-fetch rather than name another file */
  failures += savebounds_expect_refused(opt, path_over, adr, fil);
  failures += savebounds_expect_refused(opt, path_huge, adr, fil);

  return failures;
}

static int st_cache_savebounds(httrackp *opt, int argc, char **argv) {
  int err;

  if (argc < 1) {
    fprintf(stderr, "cache-savebounds: needs a directory\n");
    return 1;
  }
  err = cache_savename_bounds_selftest(opt, argv[0]);
  printf("cache-savebounds: %s\n", err ? "FAIL" : "OK");
  return err;
}

static void st_assume_rule(httrackp *opt, size_t value_len) {
  size_t i;

  StringCopy(opt->mimedefs, "\ncgi=");
  for (i = 0; i < value_len; i++)
    StringAddchar(opt->mimedefs, 'B');
  StringCat(opt->mimedefs, "\n");
}

static void st_assume_log(httrackp *opt, int type, const char *format,
                          va_list args) {
  (void) opt;
  (void) format;
  (void) args;
  if ((type & 0xff) == LOG_WARNING)
    st_assume_clips++;
}

static int st_assumemime(httrackp *opt, int argc, char **argv) {
  static const size_t values[] = {200, 300, 1100};
  /* pre-fix every destination smashes and only the first assertion to fire is
     visible, so each is selectable by its capacity */
  const char *const only = argc >= 1 ? argv[0] : "";
  const int save_debug = opt->debug;
  char canary[ST_ASSUME_CANARY];
  size_t v;

  if (!st_assume_wants(only, "128") && !st_assume_wants(only, "256") &&
      !st_assume_wants(only, "1024")) {
    fprintf(stderr, "assumemime: want one of 128, 256, 1024\n");
    return 1;
  }
  memset(canary, '#', sizeof(canary));
  /* the callback runs above the level filter, so the warnings can be counted
     while the log itself stays quiet and stdout carries one line */
  opt->debug = LOG_ERROR;
  hts_set_log_vprint_callback(st_assume_log);

  for (v = 0; v < sizeof(values) / sizeof(values[0]); v++) {
    const size_t len = values[v];

    st_assume_rule(opt, len);

    /* ishtml()'s mime[256] */
    if (st_assume_wants(only, "256")) {
      struct {
        char dst[256];
        char canary[ST_ASSUME_CANARY];
      } s;

      memset(&s, '#', sizeof(s));
      st_assume_clips = 0;
      assertf(get_userhttptype(opt, s.dst, sizeof(s.dst), "/x.cgi"));
      assertf(strlen(s.dst) == (len < sizeof(s.dst) ? len : sizeof(s.dst) - 1));
      assertf(memcmp(s.canary, canary, sizeof(s.canary)) == 0);
      assertf(st_assume_clips == (len < sizeof(s.dst) ? 0u : 1u));
      /* the frame ishtml() owns, which is where #1276 was reported */
      assertf(ishtml(opt, "/x.cgi") == 0);
    }

    /* url_savename()'s mime[1024] */
    if (st_assume_wants(only, "1024")) {
      struct {
        char dst[1024];
        char canary[ST_ASSUME_CANARY];
      } l;

      memset(&l, '#', sizeof(l));
      st_assume_clips = 0;
      assertf(get_userhttptype(opt, l.dst, sizeof(l.dst), "/x.cgi"));
      assertf(strlen(l.dst) == (len < sizeof(l.dst) ? len : sizeof(l.dst) - 1));
      assertf(memcmp(l.canary, canary, sizeof(l.canary)) == 0);
      assertf(st_assume_clips == (len < sizeof(l.dst) ? 0u : 1u));
    }

    /* htsblk.contenttype[128]: charset and contentencoding follow it in the
       same struct, so an overrun stays intra-object and neither ASan nor
       _FORTIFY_SOURCE reports it */
    if (st_assume_wants(only, "128")) {
      htsblk r;

      memset(&r, '#', sizeof(r));
      r.contenttype[0] = '\0';
      st_assume_clips = 0;
      assertf(get_httptype_sized(opt, r.contenttype, sizeof(r.contenttype),
                                 "/x.cgi", 0));
      assertf(strlen(r.contenttype) == sizeof(r.contenttype) - 1);
      assertf(memcmp(r.charset, canary, sizeof(r.charset)) == 0);
      assertf(memcmp(r.contentencoding, canary, sizeof(r.contentencoding)) ==
              0);
      assertf(st_assume_clips == 1);
    }
  }

  /* control: a value every destination holds is written whole, unclipped and
     unreported, and still reaches ishtml() as the type it names */
  StringCopy(opt->mimedefs, "\ncgi=text/html\n");
  {
    char mime[256];

    st_assume_clips = 0;
    assertf(get_userhttptype(opt, mime, sizeof(mime), "/x.cgi"));
    assertf(strcmp(mime, "text/html") == 0);
    assertf(st_assume_clips == 0);
    assertf(ishtml(opt, "/x.cgi") == 1);
  }

  hts_set_log_vprint_callback(NULL);
  opt->debug = save_debug;
  printf("assumemime ok\n");
  return 0;
}

hts_boolean filters_insert(httrackp *opt, int pos, const char *pattern) {
  char **const filters = *opt->filters.filters;
  const size_t len = strlen(pattern);
  int i;

  assertf(pos >= 0 && pos <= *opt->filters.filptr);
  if (len > HTS_FILTER_MAXLEN) {
    hts_log_print(opt, LOG_WARNING,
                  "Filter rule dropped: %d bytes is past the %d-byte limit, so "
                  "it could never match: %s",
                  (int) len, (int) HTS_FILTER_MAXLEN, pattern);
    return HTS_FALSE;
  }
  for (i = *opt->filters.filptr; i > pos; i--)
    strlcpybuff(filters[i], filters[i - 1], HTS_FILTER_SLOT_SIZE);
  strlcpybuff(filters[pos], pattern, HTS_FILTER_SLOT_SIZE);
  (*opt->filters.filptr)++;
  assertf((*opt->filters.filptr) < opt->maxfilter);
  return HTS_TRUE;
}

static int st_filtercap(httrackp *opt, int argc, char **argv) {
  const htsfilters saved = opt->filters;
  const int savedwizard = opt->wizard_filters;
  const int saveddebug = opt->debug;
  FILE *const projectlog = opt->log;
  char BIGSTK atcap[HTS_FILTER_MAXLEN + 1];   /* "+a..a*", the longest rule */
  char BIGSTK overcap[HTS_FILTER_MAXLEN + 2]; /* the same, one byte too long */
  char BIGSTK toolong[STRJOKER_MAXLEN + 3];   /* and one the matcher skips */
  char BIGSTK subject[HTS_FILTER_MAXLEN];     /* a URL all three would match */
  char BIGSTK line[STRJOKER_MAXLEN + 256]; /* room for a warning quoting one */
  char **filters = NULL;
  int filptr = 0;
  int taken, verdict, warned;

  (void) argc;
  (void) argv;
  memset(atcap, 'a', sizeof(atcap) - 1);
  atcap[0] = '+';
  atcap[sizeof(atcap) - 2] = '*';
  atcap[sizeof(atcap) - 1] = '\0';
  memset(overcap, 'a', sizeof(overcap) - 1);
  overcap[0] = '-';
  overcap[sizeof(overcap) - 2] = '*';
  overcap[sizeof(overcap) - 1] = '\0';
  memset(toolong, 'a', sizeof(toolong) - 1);
  toolong[0] = '-';
  toolong[sizeof(toolong) - 2] = '*';
  toolong[sizeof(toolong) - 1] = '\0';
  memset(subject, 'a', sizeof(subject) - 1);
  subject[sizeof(subject) - 1] = '\0';
  assertf(strlen(atcap) == HTS_FILTER_MAXLEN);
  assertf(strlen(overcap) == HTS_FILTER_MAXLEN + 1);
  assertf(strlen(toolong) > STRJOKER_MAXLEN);
  assertf(strlen(subject) <= STRJOKER_MAXLEN); /* else none could match */
  assertf(strjoker(subject, toolong + 1, NULL, NULL) == NULL);

  assertf(filters_init(&filters, opt->maxfilter, 0) != 0);
  opt->filters.filters = &filters;
  opt->filters.filptr = &filptr;
  opt->wizard_filters = 0;
  opt->debug = LOG_NOTICE;
/* non-zero, so a stray write into the slot above the last rule shows up */
#define POISON "-poison/*"
/* offer `pattern` to the array, and report what it did with it */
#define TRY(label, pattern)                                                    \
  do {                                                                         \
    FILE *const log = tmpfile();                                               \
    char want[64];                                                             \
    assertf(log != NULL);                                                      \
    opt->log = log;                                                            \
    taken = filters_insert(opt, filptr, (pattern));                            \
    verdict = fa_strjoker(0, filters, filptr, subject, NULL, NULL, NULL);      \
    rewind(log);                                                               \
    if (fgets(line, (int) sizeof(line), log) == NULL)                          \
      line[0] = '\0';                                                          \
    /* the reason, this rule's own length, and the rule itself */              \
    snprintf(want, sizeof(want), "%d bytes", (int) strlen(pattern));           \
    warned = strstr(line, "could never match") != NULL &&                      \
             strstr(line, want) != NULL && strstr(line, (pattern)) != NULL;    \
    assertf(line[0] == '\0' || warned); /* nothing else may be logged */       \
    fclose(log);                                                               \
    printf("%s: stored=%d rules=%d verdict=%d warned=%d\n", (label),           \
           taken != 0, filptr, verdict, warned);                               \
  }

static int st_wizardprompt(httrackp *opt, int argc, char **argv) {
  char prompt[HTS_URLMAXSIZE * 2];
  char adr[HTS_URLMAXSIZE], fil[HTS_URLMAXSIZE * 2];

  (void) opt;
  if (argc >= 2) {
    hts_wizard_prompt_url(prompt, sizeof(prompt), argv[0], argv[1]);
    printf("%s\n", prompt);
    return 0;
  }
#define ASKS(adr_, fil_, expect)                                               \
  do {                                                                         \
    hts_wizard_prompt_url(prompt, sizeof(prompt), (adr_), (fil_));             \
    assertf(strcmp(prompt, (expect)) == 0);                                    \
  } while (0)
  ASKS("foo.com", "/dir/page.html", "foo.com/dir/page.html");
  ASKS("foo.com:8080", "/", "foo.com:8080/");
  ASKS("user:pass@foo.com", "/x", "user:pass@foo.com/x");
  /* the separator, for the slash-less forms the parser does not emit today */
  ASKS("foo.com", "index.html", "foo.com/index.html");
  ASKS("foo.com", "", "foo.com/");
#undef ASKS

  /* #1251: a link too long for the prompt is clipped, not fatal, and what is
     left still names the host it came from */
  memset(adr, 'a', sizeof(adr) - 1);
  adr[sizeof(adr) - 1] = '\0';
  memset(fil, 'b', sizeof(fil) - 1);
  fil[sizeof(fil) - 1] = '\0';
  fil[0] = '/';
  hts_wizard_prompt_url(prompt, sizeof(prompt), adr, fil);
  assertf(strlen(prompt) == sizeof(prompt) - 1);
  assertf(strncmp(prompt, adr, sizeof(adr) - 1) == 0);
  assertf(prompt[sizeof(adr) - 1] == '/');
  /* and again with the separator to insert, which eats one more byte */
  fil[0] = 'b';
  hts_wizard_prompt_url(prompt, sizeof(prompt), adr, fil);
  assertf(strlen(prompt) == sizeof(prompt) - 1);
  assertf(strncmp(prompt, adr, sizeof(adr) - 1) == 0);
  assertf(prompt[sizeof(adr) - 1] == '/');
  assertf(prompt[sizeof(adr)] == 'b');
  /* a host alone long enough to fill it leaves no room for either */
  memset(fil, 'b', sizeof(fil) - 1);
  fil[0] = '/';
  hts_wizard_prompt_url(prompt, sizeof(prompt), fil, fil);
  assertf(strlen(prompt) == sizeof(prompt) - 1);
  assertf(strncmp(prompt, fil, sizeof(prompt) - 1) == 0);

  printf("wizardprompt self-test OK\n");
  return 0;
}

void hts_wizard_prompt_url(char *dst, size_t dstsize, const char *adr,
                           const char *fil) {
  if (dst == NULL || dstsize == 0)
    return;
  /* clipped, never aborting: adr and fil are cut from a crawled link and
     together outgrow any prompt buffer */
  dst[0] = '\0';
  strlncatbuff(dst, adr, dstsize, dstsize - 1);
  if (*fil != '/')
    strlncatbuff(dst, "/", dstsize, dstsize - 1 - strlen(dst));
  strlncatbuff(dst, fil, dstsize, dstsize - 1 - strlen(dst));
}

static hts_boolean wizard_answer_scope(const char *adr, int n, char *dst,
                                       size_t dstsize) {
  const int k =
      n - (hts_wizard_scope_answer(n) == HTS_TRUE ? HTS_WIZARD_SCOPE_EXCLUDE
                                                  : HTS_WIZARD_SCOPE_INCLUDE);

  return hts_wizard_host_scope(adr, k, dst, dstsize);
}

hts_boolean cmdl_ins_unquoted(cmdl_argv *cmd, const char *token, int pos) {
  if (!cmdl_ins(cmd, token, pos))
    return HTS_FALSE;
  cmd->unquoted[pos] = HTS_TRUE;
  return HTS_TRUE;
}

void filters_bind(httrackp *opt, char ***ptrfilters, int *filptr) {
  opt->filters.filters = ptrfilters;
  opt->filters.filptr = filptr;
  opt->wizard_filters = 0;
}

static void wz_seed(httrackp *opt, char **filters, int *filptr,
                    const char *const *cmd) {
  int i;

  *filptr = 0;
  opt->wizard_filters = 0;
  for (i = 0; cmd != NULL && cmd[i] != NULL; i++)
    strlcpybuff(filters[(*filptr)++], cmd[i], HTS_FILTER_SLOT_SIZE);
}

static void wz_holds(char **filters, int filptr, const char *const *want) {
  int i;

  for (i = 0; want[i] != NULL; i++) {
    if (i >= filptr || strcmp(filters[i], want[i]) != 0)
      fprintf(stderr, "filter %d: got [%s], want [%s]\n", i,
              i < filptr ? filters[i] : "<past the end>", want[i]);
    assertf(i < filptr);
    assertf(strcmp(filters[i], want[i]) == 0);
  }
  if (filptr != i)
    fprintf(stderr, "filter %d: got [%s], want nothing\n", i,
            i < filptr ? filters[i] : "<past the end>");
  assertf(filptr == i);
}

static int st_wizardinsert(httrackp *opt, int argc, char **argv) {
  const htsfilters saved = opt->filters;
  const int savedwizard = opt->wizard_filters;
  const int savedmax = opt->maxfilter;
  char **filters = NULL;
  int filptr = 0;
  int i;

  assertf(filters_init(&filters, opt->maxfilter, 0) != 0);
  opt->filters.filters = &filters;
  opt->filters.filptr = &filptr;
  opt->wizard_filters = 0;
/* Answers, from httrack.c's question: 0 this link, 1 this directory, 2 the
   host, 3 the parent, 4 this page only, 5 the directory and below, 6 the host,
   7 the directory's files, 50 nothing. seeker_up is pinned off, so answer 5
   takes its directory branch; 264 covers the host one. */
#define INSERT(n, adr, fil)                                                    \
  hts_wizard_insert_filters(opt, (n), (adr), (fil), HTS_FALSE)
#define HOLDS(...)                                                             \
  do {                                                                         \
    const char *const want[] = {__VA_ARGS__, NULL};                            \
    wz_holds(filters, filptr, want);                                           \
  } while (0)
#define SEED(...)                                                              \
  do {                                                                         \
    const char *const cmd[] = {__VA_ARGS__, NULL};                             \
    wz_seed(opt, filters, &filptr, cmd);                                       \
  } while (0)
#define RESET() wz_seed(opt, filters, &filptr, NULL)
/* what the array as it stands decides for `url` */
#define VERDICT(url) fa_strjoker(0, filters, filptr, (url), NULL, NULL, NULL)

  if (argc >= 2) {
    int sep = argc;

    for (i = 2; i < argc; i++) {
      if (strcmp(argv[i], "@") == 0) {
        sep = i;
        break;
      }
    }
    for (i = sep + 1;
         i < argc && filptr + HTS_WIZARD_MAX_FILTERS < opt->maxfilter; i++)
      strlcpybuff(filters[filptr++], argv[i], HTS_FILTER_SLOT_SIZE);
    for (i = 2; i < sep; i++)
      INSERT(atoi(argv[i]), argv[0], argv[1]);
    for (i = 0; i < filptr; i++)
      printf("%s%s", i != 0 ? " " : "", filters[i]);
    printf("\n");
    goto done;
  }

  /* the block size indexes one crawl's array, so binding an array empties it */
  {
    char **other = NULL;
    int otherptr = 7;

    opt->wizard_filters = 3;
    filters_bind(opt, &other, &otherptr);
    assertf(opt->wizard_filters == 0);
    assertf(opt->filters.filters == &other && opt->filters.filptr == &otherptr);
    filters_bind(opt, &filters, &filptr);
  }

  /* and a counter that outlived its array still cannot index past the end */
  SEED("-*.zip");
  opt->wizard_filters = 99;
  INSERT(6, "h", "/dir/two.html");
  assertf(opt->wizard_filters <= filptr);

  /* the correction case: "ignore this link", then "mirror the whole host" */
  RESET();
  INSERT(0, "h", "/dir/one.html");
  HOLDS("-h/dir/one.html");
  assertf(opt->wizard_filters == 1);
  assertf(VERDICT("h/dir/one.html") == -1);
  INSERT(6, "h", "/dir/two.html");
  HOLDS("-h/dir/one.html", "+h/*");
  assertf(opt->wizard_filters == 2);
  assertf(VERDICT("h/dir/one.html") == 1);

  /* reversing the answers reverses the outcome, or the block is not ordered */
  RESET();
  INSERT(6, "h", "/dir/two.html");
  INSERT(0, "h", "/dir/one.html");
  HOLDS("+h/*", "-h/dir/one.html");
  assertf(VERDICT("h/dir/one.html") == -1);
  assertf(VERDICT("h/dir/two.html") == 1);

  /* no answer reaches above the command line */
  SEED("-h/*.zip", "+h/keep/*");
  INSERT(6, "h", "/dir/two.html");
  HOLDS("+h/*", "-h/*.zip", "+h/keep/*");
  assertf(opt->wizard_filters == 1);
  assertf(VERDICT("h/a.zip") == -1);
  assertf(VERDICT("h/dir/two.html") == 1);

  /* the primary link records its scope first, so a later answer overrides it */
  RESET();
  INSERT(7, "h", "/dir/index.html");
  INSERT(0, "h", "/dir/one.html");
  HOLDS("+h/dir/*[file]", "-h/dir/one.html");
  assertf(VERDICT("h/dir/one.html") == -1);

  /* both halves of a host-scope answer land in the block, in emission order */
  SEED("-*.zip");
  INSERT(HTS_WIZARD_SCOPE_INCLUDE + 1, "www.example.co.uk", "/x.html");
  HOLDS("+*.example.co.uk/*", "+example.co.uk/*", "-*.zip");
  assertf(opt->wizard_filters == 2);

  /* an answer that emits nothing leaves the block and the array unchanged */
  SEED("-*.zip");
  INSERT(4, "h", "/dir/one.html");
  INSERT(50, "h", "/dir/one.html");
  INSERT(3, "h", "/dir/one.html");
  HOLDS("-*.zip");
  assertf(opt->wizard_filters == 0);

  /* answers 1, 5 and 7 emit nothing when the file part has no directory */
  RESET();
  INSERT(1, "h", "one.html");
  INSERT(5, "h", "one.html");
  INSERT(7, "h", "one.html");
  assertf(filptr == 0 && opt->wizard_filters == 0);

  printf("wizardinsert self-test OK\n");
done:
#undef INSERT
#undef HOLDS
#undef SEED
#undef RESET
#undef VERDICT
  freet(filters[0]);
  freet(filters);
  opt->filters = saved;
  opt->wizard_filters = savedwizard;
  opt->maxfilter = savedmax;
  return 0;
}

static void filters_insert_at(httrackp *opt, int pos, const char *pattern) {
  char **const filters = *opt->filters.filters;
  int i;

  assertf(pos >= 0 && pos <= *opt->filters.filptr);
  for (i = *opt->filters.filptr; i > pos; i--)
    strlcpybuff(filters[i], filters[i - 1], HTS_FILTER_SLOT_SIZE);
  strlcpybuff(filters[pos], pattern, HTS_FILTER_SLOT_SIZE);
  (*opt->filters.filptr)++;
  assertf((*opt->filters.filptr) < opt->maxfilter);
}

int hts_wizard_insert_filters(httrackp *opt, int n, const char *adr,
                              const char *fil, hts_boolean seeker_up) {
  char BIGSTK pattern[HTS_FILTER_SLOT_SIZE];
  htsbuff f = htsbuff_array(pattern);
  int slot;

  /* grow first: a host-scope answer emits two filters */
  if ((*opt->filters.filptr) + 2 >= opt->maxfilter) {
    opt->maxfilter += HTS_FILTERSINC;
    if (filters_init(opt->filters.filters, opt->maxfilter, HTS_FILTERSINC) ==
        0) {
      printf("PANIC! : Too many filters : >%d [%d]\n", *opt->filters.filptr,
             __LINE__);
      fflush(stdout);
      hts_log_print(opt, LOG_PANIC, "Too many filters, giving up..(>%d)",
                    *opt->filters.filptr);
      hts_log_print(
          opt, LOG_INFO,
          "To avoid that: use #F option for more filters (example: -#F5000)");
      assertf("too many filters - giving up" == NULL); // wild..
    }
  }
  /* a counter outliving its array (an opt reused for a second crawl) would
     index past the end */
  if (opt->wizard_filters > *opt->filters.filptr)
    opt->wizard_filters = *opt->filters.filptr;
  for (slot = 0; slot < HTS_WIZARD_MAX_FILTERS; slot++) {
    hts_wizard_answer_filter(&f, slot, n, adr, fil, seeker_up);
    if (f.len == 0)
      break;
    filters_insert_at(opt, opt->wizard_filters++, pattern);
  }
  return slot;
}

static int st_wizardverdict(httrackp *opt, int argc, char **argv) {
  const hts_wizard asked = opt->wizard;
  FILE *const projectlog = opt->log;
  char line[HTS_URLMAXSIZE];
  FILE *log;
  int url, depth;

  url = 0;
  depth = PRIO_UNSET;
  opt->wizard = HTS_WIZARD_ASK;
  if (argc >= 1) {
    hts_wizard_apply_verdict(opt, atoi(argv[0]), "foo.com", "/a/b.html", &url,
                             &depth);
    printf("forbidden=%d stop=%d prio=%d\n", url,
           opt->wizard == HTS_WIZARD_AUTO, depth);
    opt->wizard = asked;
    return 0;
  }
  opt->log = NULL; /* the battery walks the answers that warn */
/* answer `n` over a link the crawl had left at `in`: the verdict it must leave,
   whether it stops the questions, and the recursion cap it must set. */
#define APPLIES(n, in, forbidden, stop, prio)                                  \
  do {                                                                         \
    url = (in);                                                                \
    depth = PRIO_UNSET;                                                        \
    opt->wizard = HTS_WIZARD_ASK;                                              \
    hts_wizard_apply_verdict(opt, (n), "foo.com", "/a/b.html", &url, &depth);  \
    assertf(url == (forbidden));                                               \
    assertf(opt->wizard == ((stop) ? HTS_WIZARD_AUTO : HTS_WIZARD_ASK));       \
    assertf(depth == (prio));                                                  \
  } while (0)
  /* '*' refuses and stops the questions */
  APPLIES(-1, 0, 1, 1, PRIO_UNSET);
  APPLIES(-1, 1, 1, 1, PRIO_UNSET);
  /* the refusing answers, 3 included although it emits no filter yet */
  APPLIES(0, 0, 1, 0, PRIO_UNSET);
  APPLIES(1, 0, 1, 0, PRIO_UNSET);
  APPLIES(2, 0, 1, 0, PRIO_UNSET);
  APPLIES(3, 0, 1, 0, PRIO_UNSET);
  /* 4 caps the recursion and decides the link neither way */
  APPLIES(4, 0, 0, 0, 1);
  APPLIES(4, 1, 1, 0, 1);
  /* an accepting answer never clears a refusal the crawl already computed */
  APPLIES(5, 1, 1, 0, PRIO_UNSET);
  APPLIES(6, 1, 1, 0, PRIO_UNSET);
  APPLIES(7, 1, 1, 0, PRIO_UNSET);
  APPLIES(50, 1, 1, 0, PRIO_UNSET);
  APPLIES(-999, 1, 1, 0, PRIO_UNSET);
  APPLIES(6, 0, 0, 0, PRIO_UNSET);
  /* both ends of each scope range: include allows, exclude forbids */
  APPLIES(HTS_WIZARD_SCOPE_INCLUDE, 0, 0, 0, PRIO_UNSET);
  APPLIES(HTS_WIZARD_SCOPE_EXCLUDE - 1, 0, 0, 0, PRIO_UNSET);
  APPLIES(HTS_WIZARD_SCOPE_EXCLUDE, 0, 1, 0, PRIO_UNSET);
  APPLIES(INT_MAX, 0, 1, 0, PRIO_UNSET);
  /* an answer in no range is not taken for an accept, nor for a refusal */
  APPLIES(8, 0, 0, 0, PRIO_UNSET);
  APPLIES(8, 1, 1, 0, PRIO_UNSET);
  APPLIES(999, 0, 0, 0, PRIO_UNSET);
  APPLIES(-2, 0, 0, 0, PRIO_UNSET);
  APPLIES(-1000, 0, 0, 0, PRIO_UNSET);
  APPLIES(INT_MIN, 0, 0, 0, PRIO_UNSET);
  APPLIES(HTS_WIZARD_SCOPE_INCLUDE - 1, 0, 0, 0, PRIO_UNSET);
#undef APPLIES

  /* the warning is all an unknown answer does, so a known one must be silent */
  log = tmpfile();
  assertf(log != NULL);
  opt->log = log;
  hts_wizard_apply_verdict(opt, 6, "foo.com", "/a/b.html", &url, &depth);
  hts_wizard_apply_verdict(opt, 8, "foo.com", "/a/b.html", &url, &depth);
  rewind(log);
  assertf(fgets(line, (int) sizeof(line), log) != NULL);
  assertf(strstr(line, "unknown answer 8") != NULL);
  assertf(fgets(line, (int) sizeof(line), log) == NULL);
  fclose(log);

  opt->log = projectlog;
  opt->wizard = asked;
  printf("wizardverdict self-test OK\n");
  return 0;
}

void hts_wizard_apply_verdict(httrackp *opt, int n, const char *adr,
                              const char *fil, int *forbidden_url,
                              int *set_prio_to) {
  switch (n) {
  case -1: /* skip this link and every question after it */
    *forbidden_url = 1;
    opt->wizard = HTS_WIZARD_AUTO;
    break;

  case 0: /* this link */
  case 1: /* this directory and below */
  case 2: /* the whole host */
  case 3: /* the parent directory, which emits no filter yet */
    *forbidden_url = 1;
    break;

  case 4: /* wizard filters both allow and forbid, so an isolated link taken
             with no depth limit would mirror the whole site */
    *set_prio_to = 0 + 1; /* recursion level 0 */
    break;

  case 5:    /* this directory and below, or the whole host */
  case 6:    /* the whole host */
  case 7:    /* this directory, files only */
  case 50:   /* nothing to do */
  case -999: /* the "!" answer, and anything the front end could not parse */
    break;

  default: /* a scope answer forbids like 2 or allows like 6 */
    if (hts_wizard_scope_answer(n) == HTS_TRUE)
      *forbidden_url = 1;
    else if (hts_wizard_scope_answer(n) == HTS_DEFAULT)
      hts_log_print(opt, LOG_WARNING,
                    "(wizard) unknown answer %d at %s%s, keeping the computed "
                    "verdict",
                    n, adr, fil);
    break;
  }
}

hts_boolean hts_host_is_ipv4(const char *host, size_t len) {
  size_t i;
  int dots = 0;

  for (i = 0; i < len; i++) {
    if (host[i] == '.')
      dots++;
    else if (host[i] < '0' || host[i] > '9')
      return HTS_FALSE;
  }
  return dots > 0 ? HTS_TRUE : HTS_FALSE;
}

static int st_wizardscope(httrackp *opt, int argc, char **argv) {
  char scope[HTS_URLMAXSIZE];
  int k;

  (void) opt;
  if (argc >= 1) {
    for (k = 0; hts_wizard_host_scope(argv[0], k, scope, sizeof(scope)); k++)
      printf("%d %s\n", k, scope);
    return 0;
  }
#define SCOPE(question, k, expect)                                             \
  do {                                                                         \
    assertf(hts_wizard_host_scope((question), (k), scope, sizeof(scope)));     \
    assertf(strcmp(scope, (expect)) == 0);                                     \
  } while (0)
/* poisoned first: comparing against '\0' cannot see a clear that never ran */
#define NOSCOPE_SIZED(question, k, size)                                       \
  do {                                                                         \
    memset(scope, 'X', sizeof(scope));                                         \
    assertf(!hts_wizard_host_scope((question), (k), scope, (size)));           \
    assertf(scope[0] == '\0');                                                 \
  } while (0)
#define NOSCOPE(question, k) NOSCOPE_SIZED((question), (k), sizeof(scope))

  /* k widens by one label at a time, starting at the host itself */
  SCOPE("download.example.co.uk/x", 0, "download.example.co.uk");
  SCOPE("download.example.co.uk/x", 1, "example.co.uk");
  SCOPE("download.example.co.uk/x", 2, "co.uk");
  NOSCOPE("download.example.co.uk/x", 3); /* "uk" is a bare TLD */
  SCOPE("example.com", 0, "example.com"); /* an adr with no fil works */
  NOSCOPE("example.com", 1);
  NOSCOPE("localhost/x", 0); /* nothing to widen into */
  NOSCOPE("download.example.co.uk/x", -1);

  /* protocol and credentials are stripped, the port kept */
  SCOPE("ftp://user:pass@www.foo.com/x", 1, "foo.com");
  SCOPE("www.foo.com:8080/x", 0, "www.foo.com:8080");
  SCOPE("www.foo.com:8080/x", 1, "foo.com:8080");
  NOSCOPE("www.foo.com:8080/x", 2);
  /* a path that carries dots or a colon must not be read as host labels */
  SCOPE("foo.com/a.b.c/d:e", 0, "foo.com");
  NOSCOPE("foo.com/a.b.c/d:e", 1);

  /* the shared predicate: a dotless run of digits is a hostname, not an IP */
  assertf(hts_host_is_ipv4("1.2.3.4", 7));
  assertf(!hts_host_is_ipv4("12345", 5));
  assertf(!hts_host_is_ipv4("foo.com", 7));

  /* an IP literal splits on dots without being a domain */
  NOSCOPE("192.168.1.1/x", 0);
  NOSCOPE("192.168.1.1:8080/x", 0);
  NOSCOPE("[3ffe:b80:1234::1]/x", 0);
  /* the dots inside this one reach the label walk unless brackets are refused
   */
  NOSCOPE("[::ffff:1.2.3.4]/x", 0);

  /* the root label of a fully-qualified host is not a label */
  SCOPE("www.foo.com./x", 0, "www.foo.com.");
  SCOPE("www.foo.com./x", 1, "foo.com.");
  NOSCOPE("www.foo.com./x", 2); /* "com." is still a bare TLD */
  NOSCOPE(".", 0);

  /* the destination must fit the scope and its terminator, and never truncate
   */
  {
    const char *q = "www.example.com/x";
    const size_t need = strlen("www.example.com");

    memset(scope, 'X', sizeof(scope));
    assertf(hts_wizard_host_scope(q, 0, scope, need + 1));
    assertf(strcmp(scope, "www.example.com") == 0);
    NOSCOPE_SIZED(q, 0, need);
    NOSCOPE_SIZED(q, 0, 4);
    NOSCOPE_SIZED(q, 0, 1);
  }
#undef SCOPE
#undef NOSCOPE
#undef NOSCOPE_SIZED
  printf("wizardscope self-test OK\n");
  return 0;
}

static int st_wizardscopeanswer(httrackp *opt, int argc, char **argv) {
  (void) opt;
  (void) argc;
  (void) argv;
#define ANSWER(n, expect) assertf(hts_wizard_scope_answer(n) == (expect))
  /* the plain answers, and the boundary just below the first range */
  ANSWER(-999, HTS_DEFAULT);
  ANSWER(-1, HTS_DEFAULT);
  ANSWER(0, HTS_DEFAULT);
  ANSWER(7, HTS_DEFAULT);
  ANSWER(50, HTS_DEFAULT);
  ANSWER(HTS_WIZARD_SCOPE_INCLUDE - 1, HTS_DEFAULT);
  /* include runs up to the exclude base, and exclude has no upper end */
  ANSWER(HTS_WIZARD_SCOPE_INCLUDE, HTS_FALSE);
  ANSWER(HTS_WIZARD_SCOPE_EXCLUDE - 1, HTS_FALSE);
  ANSWER(HTS_WIZARD_SCOPE_EXCLUDE, HTS_TRUE);
  ANSWER(INT_MAX, HTS_TRUE);
#undef ANSWER
  printf("wizardscopeanswer self-test OK\n");
  return 0;
}

HTSEXT_API hts_boolean hts_wizard_host_scope(const char *question, int k,
                                             char *dst, size_t dstsize) {
  const char *host, *port, *slash, *end, *scope;
  size_t len;

  if (dst == NULL || dstsize == 0)
    return HTS_FALSE;
  dst[0] = '\0';
  if (question == NULL || k < 0)
    return HTS_FALSE;

  host = jump_identification_const(question);
  port = jump_toport_const(question);
  slash = strchr(host, '/');
  end = host + strlen(host);
  scope = host;
  if (slash != NULL && slash < end)
    end = slash;
  /* the port belongs to the filter, so keep it and only bound the label walk */
  if (port != NULL && port < end)
    slash = port;
  else
    slash = end;
  /* a fully-qualified "foo.com." ends on the root label, which is not one */
  if (slash > host && slash[-1] == '.')
    slash--;
  if (slash == host || *host == '[') /* no host, or an IPv6 literal */
    return HTS_FALSE;
  if (hts_host_is_ipv4(host, (size_t) (slash - host)))
    return HTS_FALSE;

  /* widen by dropping one leading label per step, and never offer a bare TLD */
  for (; k > 0; k--) {
    const char *dot = memchr(scope, '.', (size_t) (slash - scope));

    if (dot == NULL)
      return HTS_FALSE;
    scope = dot + 1;
  }
  if (memchr(scope, '.', (size_t) (slash - scope)) == NULL)
    return HTS_FALSE;

  len = (size_t) (end - scope);
  if (len >= dstsize)
    return HTS_FALSE;
  memcpy(dst, scope, len);
  dst[len] = '\0';
  return HTS_TRUE;
}

hts_tristate hts_wizard_scope_answer(int n) {
  if (n >= HTS_WIZARD_SCOPE_EXCLUDE)
    return HTS_TRUE;
  if (n >= HTS_WIZARD_SCOPE_INCLUDE)
    return HTS_FALSE;
  return HTS_DEFAULT;
}

static void wizard_cat_scope(htsbuff *f, const char *sign, const char *adr,
                             int n, int slot) {
  char scope[HTS_URLMAXSIZE];
  const int k =
      n - (hts_wizard_scope_answer(n) == HTS_TRUE ? HTS_WIZARD_SCOPE_EXCLUDE
                                                  : HTS_WIZARD_SCOPE_INCLUDE);

  if (slot >= HTS_WIZARD_MAX_FILTERS ||
      !hts_wizard_host_scope(adr, k, scope, sizeof(scope)))
    return;
  htsbuff_cpy(f, sign);
  if (slot == 0)
    htsbuff_cat(f, "*.");
  htsbuff_cat(f, scope);
  htsbuff_cat(f, "/*");
}

void hts_wizard_answer_filter(htsbuff *f, int slot, int n, const char *adr,
  if (hts_wizard_scope_answer(n) != HTS_DEFAULT) {
    wizard_cat_scope(f, hts_wizard_scope_answer(n) == HTS_TRUE ? "-" : "+", adr,
                     n, slot);
    return;
  }

static void client_event(smallserver_client_event ev, const char *window) {
  if (pingFun != NULL) {
    pingFun(pingFunArg, ev, window);
  }
}

static hts_boolean query_alnum_value(char *dst, size_t size, const char *query,
                                     const char *name) {
  const size_t namelen = strlen(name);
  const char *s = query;

  dst[0] = '\0';
  while (*s != '\0') {
    const char *const amp = strchr(s, '&');

    if (strncmp(s, name, namelen) == 0 && s[namelen] == '=') {
      const char *v = s + namelen + 1;
      size_t n = 0;

      while (*v != '\0' && *v != '&' && n + 1 < size &&
             isalnum((unsigned char) *v)) {
        dst[n++] = *v++;
      }
      dst[n] = '\0';
      /* Truncated, or not alphanumeric to its end, is no value at all: it must
         not reach a caller that trusted the return. */
      if (n > 0 && (*v == '\0' || *v == '&')) {
        return HTS_TRUE;
      }
      dst[0] = '\0';
      return HTS_FALSE;
    }
    if (amp == NULL) {
      break;
    }
    s = amp + 1;
  }
  return HTS_FALSE;
}

static hts_boolean parent_is_alive(uintptr_t ppid) {
#ifdef _WIN32
  (void) ppid;
  return HTS_TRUE; /* no cheap probe; the heartbeat carries this */
#else
  /* kill(0) would signal our own process group, never a parent. */
  return ppid == 0 || kill((pid_t) ppid, 0) == 0 ? HTS_TRUE : HTS_FALSE;
#endif
}

static int st_arena(httrackp *opt, int argc, char **argv) {
  enum { count = 4096 };

  hts_arena arena = {NULL, 0, 0};
  char **kept = (char **) calloct(count, sizeof(*kept));
  char BIGSTK big[HTS_ARENA_MIN * 2];
  char token[256];
  int i;

  (void) opt;
  (void) argc;
  (void) argv;
  assertf(kept != NULL);

  /* Enough tokens to span many chunks, each holding its own index. */
  for (i = 0; i < count; i++) {
    snprintf(token, sizeof(token), "%d-%*s", i, 200, "x");
    kept[i] = hts_arena_strdup(&arena, token);
    assertf(kept[i] != NULL);
  }
  /* One allocation larger than a whole chunk takes one of its own. */
  memset(big, 'b', sizeof(big) - 1);
  big[sizeof(big) - 1] = '\0';
  assertf(hts_arena_strdup(&arena, big) != NULL);
  /* An aligned allocation is aligned whatever the byte-sized ones did to it. */
  for (i = 0; i < 8; i++) {
    void *const p = hts_arena_alloc(&arena, sizeof(hts_arena_align));

    assertf(p != NULL);
    assertf(((size_t) (char *) p) % HTS_ARENA_ALIGN == 0);
    assertf(hts_arena_strdup(&arena, "x") != NULL);
  }
  /* Nothing moved: every token still reads back as itself. */
  for (i = 0; i < count; i++) {
    snprintf(token, sizeof(token), "%d-%*s", i, 200, "x");
    assertf(strcmp(kept[i], token) == 0);
  }
  /* A size no allocation could hold is refused, not truncated. */
  assertf(hts_arena_alloc(&arena, (size_t) -1) == NULL);
  /* Strings are packed: alignment is charged where it is needed, not to every
     allocation, which would cost several bytes on each link a mirror records.
   */
  {
    hts_arena packed = {NULL, 0, 0};
    const char *const a = hts_arena_strdup(&packed, "abc");
    const char *const b = hts_arena_strdup(&packed, "de");

    assertf(a != NULL && b == a + sizeof("abc"));
    hts_arena_free(&packed);
  }

  freet(kept);
  hts_arena_free(&arena);
  assertf(arena.chunks == NULL && arena.size == 0 && arena.used == 0);
  hts_arena_free(&arena); /* releasing an empty arena is a no-op */
  printf("arena self-test OK\n");
  return 0;
}

static void cmdl_print_args(httrackp *opt, const cmdl_argv *cmd) {
  /* what the caller still has to append: "?", the line break, the NUL */
  static const size_t tail = sizeof("?" LF);
  int i;

  for (i = 1; i < cmd->argc; i++) {
    const size_t spare = sizeof(opt->state.HTbuff) - tail - sizeof(" ...");
    const size_t used = strlen(opt->state.HTbuff);

    if (used >= spare || strlen(cmd->argv[i]) >= spare - used) {
      /* clipped rather than HT_PRINT'd, so the mark fits whatever the caller
         wrote before it */
      strlncatbuff(opt->state.HTbuff, " ...", sizeof(opt->state.HTbuff),
                   sizeof(opt->state.HTbuff) - 1 - used);
      return;
    }
    HT_PRINT(" ");
    HT_PRINT(cmd->argv[i]);
  }
}

static const char *st_optalias_expand(char *dest, size_t dest_size,
                                      const char *word, const char *next,
                                      int *used) {
  char BIGSTK out[2][HTS_CDLMAXSIZE];
  char *outv[2] = {out[0], out[1]};
  const char *argv[2];
  char error[256];
  const int argc = next != NULL ? 2 : 1;
  int outc = 0;

  argv[0] = word;
  argv[1] = next;
  out[0][0] = out[1][0] = dest[0] = '\0';
  *used = optalias_check(argc, argv, 0, &outc, outv, sizeof(out[0]), error,
                         sizeof(error));
  if (*used == 0) {
    assertf(error[0] != '\0'); /* a refusal has to say why */
    return NULL;
  }
  assertf(outc >= 1 && outc <= 2);
  strlcpybuff(dest, out[0], dest_size);
  if (outc == 2) {
    strlcatbuff(dest, " ", dest_size);
    strlcatbuff(dest, out[1], dest_size);
  }
  return dest;
}

static int st_optalias(httrackp *opt, int argc, char **argv) {
  char got[HTS_CDLMAXSIZE * 2];
  int i, used;

  (void) opt;
  /* -list gives 282 the whole table: the rows to try against the engine's
     own parser, and the class of every name the wizard writes a value to */
  if (argc == 1 && strcmp(argv[0], "-list") == 0) {
    for (i = 0; optalias_value(i)[0] != '\0'; i++)
      printf("%s %s\n", opttype_value(i), optalias_value(i));
    return 0;
  }
  if (argc >= 1) {
    const char *const out = st_optalias_expand(
        got, sizeof(got), argv[0], argc >= 2 ? argv[1] : NULL, &used);

    printf("%s\n", out != NULL ? out : "(refused)");
    return out != NULL ? 0 : 1;
  }
#define EXPANDS(want, word, next)                                              \
  do {                                                                         \
    const char *const out__ =                                                  \
        st_optalias_expand(got, sizeof(got), (word), (next), &used);           \
    assertf(out__ != NULL && strcmp(out__, (want)) == 0);                      \
  } while (0)
#define REFUSES(word, next)                                                    \
  assertf(st_optalias_expand(got, sizeof(got), (word), (next), &used) == NULL)

  /* -I0 has always disabled the index; now the long form can say it too */
  EXPANDS("-I0", "--index=0", NULL);
  EXPANDS("-I0", "--index=off", NULL);
  EXPANDS("-I0", "--noindex", NULL);
  EXPANDS("-I", "--index=1", NULL);
  EXPANDS("-I", "--index=on", NULL);
  /* detached, as a config file writes it ("index off"), and never a URL */
  EXPANDS("-I0", "--index", "off");
  assertf(used == 2);
  EXPANDS("-I", "--index", "http://foo/");
  assertf(used == 1);
  EXPANDS("-I", "--index", NULL);
  assertf(used == 1);
  /* -I takes 0 alone, so an out-of-range value is an error, not a bare -I */
  REFUSES("--index=2", NULL);
  REFUSES("--index=yes", NULL);

  /* a numeric level reaches the short form whole */
  EXPANDS("-%I0", "--search-index=0", NULL);
  EXPANDS("-%I2", "--search-index=2", NULL);
  EXPANDS("-%v2", "--display=2", NULL);
  EXPANDS("-%N0", "--delayed-type-check=0", NULL);
  EXPANDS("-o0", "--generate-errors=0", NULL);
  REFUSES("--display=full", NULL);
  REFUSES("--display=99999999999999999999", NULL);

  /* three rows were "param", a class that demands a following token: the URL
     after --purge-old became its value, and =1 died on "invalid option 1" */
  EXPANDS("-X", "--purge-old", NULL);
  EXPANDS("-X", "--purge-old", "http://foo/");
  assertf(used == 1);
  EXPANDS("-X0", "--purge-old=0", NULL);
  EXPANDS("-X", "--purge-old=1", NULL);
  EXPANDS("-X0", "--purge-old", "0");
  assertf(used == 2);
  EXPANDS("-X", "--purge-old", "1");
  EXPANDS("-X0", "--nopurge-old", NULL);
  EXPANDS("-%f0", "--httpproxy-ftp=0", NULL);
  EXPANDS("-%f", "--httpproxy-ftp=1", NULL);
  EXPANDS("-%P0", "--extended-parsing=0", NULL);
  EXPANDS("-%P", "--extended-parsing=1", NULL);

  /* a flag that takes no value refuses one rather than dropping it */
  REFUSES("--mirror=0", NULL);
  REFUSES("--nomirror", NULL);
  REFUSES("--warc=0", NULL);
  REFUSES("--single-file=s", NULL);
  /* ...and so does a compound alias, whose value would land in the cluster */
  REFUSES("--spider=0", NULL);

  /* an alias whose own name begins with "no" is not a negation */
  EXPANDS("-%T0", "--no-utf8-conversion", NULL);
  EXPANDS("-y0", "--no-background-on-suspend", NULL);
  EXPANDS("-%T", "--utf8-conversion", NULL);

  /* the value-taking classes are untouched */
  EXPANDS("-C0", "--cache=0", NULL);
  EXPANDS("-C0", "--nocache", NULL);
  EXPANDS("-C2", "--cache", "2");
  EXPANDS("-P proxy:8080", "--proxy", "proxy:8080");
  EXPANDS("+*.gif", "--allow", "*.gif");

  /* invariant: every name's bare long form still emits its short form, and a
     param name still demands its own value. A duplicate name (test, continue)
     resolves to its first row */
  for (i = 0; optalias_value(i)[0] != '\0'; i++) {
    const int p = optalias_find(optalias_value(i));
    char word[HTS_CDLMAXSIZE];

    assertf(p >= 0);
    snprintf(word, sizeof(word), "--%s", optalias_value(i));
    if (strncmp(opttype_value(p), "param", 5) == 0) {
      REFUSES(word, NULL);
    } else {
      EXPANDS(optreal_value(p), word, NULL);
      assertf(used == 1);
    }
  }
  assertf(i > 100); /* the table was walked, not skipped */
#undef EXPANDS
#undef REFUSES

  printf("optalias self-test OK\n");
  return 0;
}

static hts_boolean cmdl_grow(cmdl_argv *cmd, size_t need) {
  size_t size = need > CMDL_CHUNK_MIN ? need : CMDL_CHUNK_MIN;
  cmdl_chunk *chunk;

  if (size > (size_t) -1 - sizeof(cmdl_chunk))
    return HTS_FALSE;
  chunk = (cmdl_chunk *) malloct(sizeof(cmdl_chunk) + size);
  if (chunk == NULL)
    return HTS_FALSE;
  chunk->next = cmd->chunks;
  cmd->chunks = chunk;
  cmd->chunk_size = size;
  cmd->chunk_used = 0;
  return HTS_TRUE;
}

static hts_boolean ini_key_is_checkbox(const char *key) {
  size_t i;

  for (i = 0; ini_checkbox_keys[i] != NULL; i++) {
    if (strcmp(key, ini_checkbox_keys[i]) == 0)
      return HTS_TRUE;
  }
  return HTS_FALSE;
}

static hts_boolean cmdl_reserve(cmdl_argv *cmd, int count) {
  char **slots;
  int capacity;

  if (count <= cmd->capacity)
    return HTS_TRUE;
  if (count > CMDL_MAX_SLOTS) /* count alone: the product below can not wrap */
    return HTS_FALSE;
  /* double, so rebuilding an n-token command line stays amortized O(n) */
  capacity =
      cmd->capacity <= CMDL_MAX_SLOTS / 2 ? cmd->capacity * 2 : CMDL_MAX_SLOTS;
  if (capacity < count)
    capacity = count;
  slots = (char **) realloct(cmd->argv, sizeof(char *) * (size_t) capacity);
  if (slots == NULL)
    return HTS_FALSE;
  cmd->argv = slots;
  cmd->capacity = capacity;
  return HTS_TRUE;
}

hts_boolean cmdl_init(cmdl_argv *cmd, size_t blk_size, int slots) {
  memset(cmd, 0, sizeof(*cmd));
  cmd->blk = blk_size != 0 ? (char *) malloct(blk_size) : NULL;
  if (cmd->blk == NULL || !cmdl_reserve(cmd, slots)) {
    cmdl_free(cmd);
    return HTS_FALSE;
  }
  cmd->blk_size = blk_size;
  cmd->blk[0] = '\0';
  return HTS_TRUE;
}

void cmdl_free(cmdl_argv *cmd) {
  freet(cmd->blk);
  freet(cmd->argv);
  memset(cmd, 0, sizeof(*cmd));
}

hts_boolean cmdl_ins(cmdl_argv *cmd, const char *token, int pos) {
  int i;

  assertf(pos >= 0 && pos <= cmd->argc);
  /* argc <= capacity <= CMDL_MAX_SLOTS holds here, so argc + 1 can not wrap */
  if (!cmdl_reserve(cmd, cmd->argc + 1))
    return HTS_FALSE;
  for (i = cmd->argc; i > pos; i--)
    cmd->argv[i] = cmd->argv[i - 1];
  cmd->argv[pos] = cmd->blk + cmd->blk_used;
  strlcpybuff(cmd->argv[pos], token, cmdl_room(cmd));
  cmd->blk_used += strlen(cmd->argv[pos]) + 1;
  cmd->argc++;
  return HTS_TRUE;
}

static hts_boolean optreal_or_alias(const char *token) {
  char name[64];
  const char *eq;
  size_t len;

  if (optreal_find(token) >= 0)
    return HTS_TRUE;
  if (token[0] != '-' || token[1] != '-')
    return HTS_FALSE;
  eq = strchr(token + 2, '=');
  len = eq != NULL ? (size_t) (eq - (token + 2)) : strlen(token + 2);
  if (len == 0 || len >= sizeof(name))
    return HTS_FALSE;
  memcpy(name, token + 2, len);
  name[len] = '\0';
  if (optalias_find(name) >= 0)
    return HTS_TRUE;
  if (strncmp(name, "no", 2) == 0 && optalias_find(name + 2) >= 0)
    return HTS_TRUE;
  return (strncmp(name, "wide-", 5) == 0 || strncmp(name, "tiny-", 5) == 0) &&
         optalias_find(name + 5) >= 0;
}

static hts_boolean optparam_missing(int argc, const char *const *argv,
                                    int n_arg, const char *opt) {
  /* keep in sync with the strip-query and host-alias cases in htscoremain.c */
  static const char *const rule_opt[] = {"-%g", "-%C", NULL};
  int i;

  if (n_arg + 1 >= argc)
    return HTS_TRUE;
  if (argv[n_arg + 1][0] != '-')
    return HTS_FALSE;
  for (i = 0; rule_opt[i] != NULL; i++) {
    if (strcmp(opt, rule_opt[i]) == 0)
      return optreal_or_alias(argv[n_arg + 1]);
  }
  return HTS_TRUE;
}

static int socket_last_error(void) {
#ifdef _WIN32
  return WSAGetLastError();
#else
  return errno;
#endif
}

static const char *socket_error_string(int err, char *buf, size_t size) {
#ifdef _WIN32
  DWORD len =
      FormatMessageA(FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
                     NULL, (DWORD) err, 0, buf, (DWORD) size, NULL);

  /* the table punctuates its strings with a trailing ".\r\n" */
  while (len != 0 && (unsigned char) buf[len - 1] <= ' ') {
    buf[--len] = '\0';
  }
  if (len == 0) {
    strclipbuff(buf, size, "unknown error");
  }
#else
  strclipbuff(buf, size, strerror(err));
#endif
  return buf;
}

static void cat_cmdline_argn(String *output, const char *value, size_t len) {
  size_t i;

  for (i = 0; i < len; i++) {
    if (value[i] == '\\' || value[i] == '\"') {
      StringCat(*output, "\\");
    }
    if (!cat_html_escaped(output, value[i])) {
      StringMemcat(*output, &value[i], 1);
    }
  }
}

static hts_boolean st_hashkey(httrackp *opt, const char *adr, const char *fil,
                              char *arena, size_t keysize, size_t guard) {
  hash_struct hash;
  size_t i;

  /* poisoned with '#', not 0, or the stray NUL of an off-by-one would read as
     untouched */
  memset(arena, '#', keysize + guard);
  hash_init(opt, &hash, opt->urlhack);
  hash_url_key(&hash, adr, fil, arena, keysize);
  hash_free(&hash);
  for (i = keysize; i < keysize + guard; i++) {
    if (arena[i] != '#')
      return HTS_FALSE;
  }
  return HTS_TRUE;
}

static int st_hashkey_bounds(httrackp *opt, int argc, char **argv) {
  /* what lien_adrfil.adr / .fil hold, and what a whole key needs */
  enum { field = HTS_URLMAXSIZE * 2, keysize = 2 * field, guard = 64 };

  char *adr = malloct(2 * keysize);
  char *fil = malloct(2 * keysize);
  char *cat = malloct(4 * keysize);
  char *arena = malloct(keysize + guard);
  int hack;

  (void) argc;
  (void) argv;
  assertf(adr != NULL && fil != NULL && cat != NULL && arena != NULL);
  opt->no_www_dedup = opt->no_slash_dedup = opt->no_query_dedup = HTS_FALSE;
  /* the crawler's own key buffer, or every maximal URL would collide */
  assertf(sizeof(((hash_struct *) NULL)->normfil) >= (size_t) keysize);

  /* a host and a path one byte short of their own buffers: nothing here
     normalizes away, so the key is the plain concatenation */
  memset(adr, 'a', field - 1);
  adr[field - 1] = '\0';
  fil[0] = '/';
  memset(fil + 1, 'b', field - 2);
  fil[field - 1] = '\0';
  snprintf(cat, 4 * keysize, "%s%s", adr, fil);
  for (hack = 0; hack < 2; hack++) {
    opt->urlhack = hack != 0 ? HTS_TRUE : HTS_FALSE;
    assertf(st_hashkey(opt, adr, fil, arena, keysize, guard));
    assertf(strcmp(arena, cat) == 0);
  }

  /* either half alone past the whole key: each copy is bounded on its own */
  for (hack = 0; hack < 4; hack++) {
    const hts_boolean longadr = (hack & 1) != 0 ? HTS_TRUE : HTS_FALSE;

    memset(adr, 'a', longadr ? keysize + 32 : 8);
    adr[longadr ? keysize + 32 : 8] = '\0';
    fil[0] = '/';
    memset(fil + 1, 'b', longadr ? 8 : keysize + 32);
    fil[(longadr ? 8 : keysize + 32) + 1] = '\0';
    snprintf(cat, 4 * keysize, "%s%s", adr, fil);
    opt->urlhack = (hack & 2) != 0 ? HTS_TRUE : HTS_FALSE;
    assertf(st_hashkey(opt, adr, fil, arena, keysize, guard));
    /* clipped and terminated, and a prefix of the pair rather than garbage */
    assertf(strlen(arena) == keysize - 1);
    assertf(strncmp(arena, cat, strlen(arena)) == 0);
  }

  /* --strip-query builds its match string from the same two halves, and used
     to abort on a maximal pair. Past STRJOKER_MAXLEN no rule can match, so a
     clipped string would answer where the whole one must stay silent. */
  {
    const char *const rules = "*=other\n*bbz=sid";
    char keys[64];
    const char *k;

    /* control: the rules do match a short URL */
    k = hts_query_strip_keys(rules, "h.com", "/bbz", keys, sizeof(keys));
    assertf(k != NULL && strcmp(k, "sid") == 0);
    memset(adr, 'a', field - 1);
    adr[field - 1] = '\0';
    fil[0] = '/';
    memset(fil + 1, 'b', field - 3);
    fil[field - 2] = 'z';
    fil[field - 1] = '\0';
    assertf(hts_query_strip_keys(rules, adr, fil, keys, sizeof(keys)) == NULL);
    opt->urlhack = HTS_TRUE; /* and the key builder survives the same pair */
    StringCopy(opt->strip_query, rules);
    assertf(st_hashkey(opt, adr, fil, arena, keysize, guard));

    /* a matching rule plus a query longer than the normalizer's own scratch:
       the key builder must clip instead of handing it over */
    snprintf(fil, 2 * keysize, "/bbz?");
    memset(&fil[5], 'q', field + 64); /* past the normalizer, inside the key */
    fil[5 + field + 64] = '\0';
    assertf(st_hashkey(opt, "h.com", fil, arena, keysize, guard));
    StringCopy(opt->strip_query, "");
  }

  freet(adr);
  freet(fil);
  freet(cat);
  freet(arena);
  printf("hashkey-bounds self-test OK\n");
  return 0;
}

static void back_abort_slot(httrackp *opt, struct_back *sback, const int p,
                            const int statuscode, const char *msg,
                            const int trunc) {
  lien_back *const back = &sback->lnk[p];

  /* A cap-truncated body is deliberate, not broken: archive what arrived with
     WARC-Truncated before the abort overwrites the slot's real 2xx status.
     HTTrack still treats the slot as incomplete afterwards. */
  if (trunc != WARC_TRUNC_NONE && StringNotEmpty(opt->warc_file) &&
      back->r.statuscode > 0 && back->r.warc_resphdr != NULL &&
      back->r.size > 0 &&
      !(back->r.is_write && IS_DELAYED_EXT(back->url_sav))) {
    if (back->r.is_write && back->r.out != NULL)
      fflush(back->r.out);
    back->r.warc_truncated = trunc;
    warc_write_backtransaction(opt, back);
  }
  if (back->r.soc != INVALID_SOCKET)
    deletehttp(&back->r);
  back->r.soc = INVALID_SOCKET;
  /* drop a .delayed placeholder; real partials survive for resume */
  if (back->r.is_write && IS_DELAYED_EXT(back->url_sav))
    back_delayed_discard(opt, back);
  back->r.statuscode = statuscode;
  strcpybuff(back->r.msg, msg);
  back->status = STATUS_READY;
  back_set_finished(sback, p);
}

static int back_abort_stopped(httrackp *opt, struct_back *sback) {
  const hts_boolean grace = back_mirror_capped(opt);
    const int status = sback->lnk[i].status;

    if (!back_is_live(status) || (grace && !back_is_preconnect(status)))
    /* fatal, as back_add() reports a stop: no retry may reschedule the link */
    back_abort_slot(opt, sback, i, STATUSCODE_INVALID, "mirror stopped by user",
                    WARC_TRUNC_NONE);
    aborted++;
  }

static int st_random(httrackp *opt, int argc, char **argv) {
  enum { want = 64, pad = 16, rounds = 8 };

  unsigned char buf[want + pad], first[want], touched[want], varies[want];
  int err = 0, live = 0, r, i;

  (void) opt;
  (void) argc;
  (void) argv;
  memset(touched, 0, sizeof(touched));
  memset(varies, 0, sizeof(varies));
  for (r = 0; r < rounds; r++) {
    /* A fresh non-zero filler each round: a byte the fill skips keeps every one
       of them, which a single canary value cannot tell from a written byte. */
    const unsigned char filler = (unsigned char) (0xa5 + r);

    memset(buf, filler, sizeof(buf));
    if (!hts_random_bytes(buf, want))
      err = 1;
    for (i = 0; i < want; i++) {
      if (buf[i] != filler)
        touched[i] = 1;
    }
    for (i = 0; i < pad; i++) {
      if (buf[want + i] != filler)
        err = 1; /* wrote past the requested length */
    }
    if (r == 0) {
      memcpy(first, buf, want);
    } else {
      for (i = 0; i < want; i++) {
        if (buf[i] != first[i])
          varies[i] = 1;
      }
    }
  }
  for (i = 0; i < want; i++) {
    if (!touched[i])
      err = 1; /* a short fill left this byte alone in every round */
    live += varies[i];
  }
  /* Over 8 draws a live source moves all 64 bytes; half is a floor no real one
     misses, and a source stuck on one byte or a constant cannot reach it. */
  if (live < want / 2)
    err = 1;
  /* a zero-length ask succeeds and writes nothing */
  memset(buf, 0x5a, sizeof(buf));
  if (!hts_random_bytes(buf, 0))
    err = 1;
  for (i = 0; i < (int) sizeof(buf); i++) {
    if (buf[i] != 0x5a)
      err = 1;
  }
  printf("random: %s\n", err ? "FAIL" : "OK");
  return err;
}

static int st_wizardfilter(httrackp *opt, int argc, char **argv) {
  char pattern[HTS_URLMAXSIZE * 2];
  htsbuff f = htsbuff_array(pattern);

  (void) opt;
  if (argc >= 3) {
    hts_wizard_answer_filter(&f, atoi(argv[0]), argv[1], argv[2],
                             argc >= 4 && atoi(argv[3]) != 0 ? HTS_TRUE
                                                             : HTS_FALSE);
    printf("%s\n", pattern);
    return 0;
  }
#define EMITS(n, adr, fil, up, expect)                                         \
  do {                                                                         \
    hts_wizard_answer_filter(&f, (n), (adr), (fil), (up));                     \
    assertf(strcmp(pattern, (expect)) == 0);                                   \
  } while (0)

  /* the host-wide answers: 2 forbids, 5 (allowed to go up) and 6 authorize */
  EMITS(2, "foo.com", "/index.html", HTS_FALSE, "-foo.com/*");
  EMITS(5, "foo.com", "/dir/page.html", HTS_TRUE, "+foo.com/*");
  EMITS(6, "foo.com", "/dir/page.html", HTS_FALSE, "+foo.com/*");
  /* the port is part of the host, the credentials are not */
  EMITS(2, "foo.com:8080", "/x", HTS_FALSE, "-foo.com:8080/*");
  EMITS(2, "user:pass@foo.com", "/x", HTS_FALSE, "-foo.com/*");
  EMITS(5, "foo.com:8080", "/x", HTS_TRUE, "+foo.com:8080/*");
  EMITS(5, "user:pass@foo.com", "/x", HTS_TRUE, "+foo.com/*");
  EMITS(6, "foo.com:8080", "/x", HTS_FALSE, "+foo.com:8080/*");
  EMITS(6, "user:pass@foo.com", "/x", HTS_FALSE, "+foo.com/*");

  /* the trailing slash is what keeps a longer host out */
  assertf(strjoker("foo.com/index.html", pattern + 1, NULL, NULL) != NULL);
  assertf(strjoker("foo.com/", pattern + 1, NULL, NULL) != NULL);
  assertf(strjoker("foo.com.evil.org/x", pattern + 1, NULL, NULL) == NULL);
  assertf(strjoker("foo.com:8080/x", pattern + 1, NULL, NULL) == NULL);

  /* the link and directory answers */
  EMITS(0, "foo.com", "/dir/page.html", HTS_FALSE, "-foo.com/dir/page.html");
  EMITS(0, "foo.com", "index.html", HTS_FALSE, "-foo.com/index.html");
  EMITS(1, "foo.com", "/dir/page.html", HTS_FALSE, "-foo.com/dir/*");
  EMITS(1, "foo.com", "/page.html", HTS_FALSE, "-foo.com/*");
  EMITS(5, "foo.com", "/dir/page.html", HTS_FALSE, "+foo.com/dir/*");
  EMITS(7, "foo.com", "/dir/page.html", HTS_FALSE, "+foo.com/dir/*[file]");
  /* answer 1 collapses a doubled trailing slash, answers 5 and 7 keep it */
  EMITS(1, "foo.com", "/dir//page.html", HTS_FALSE, "-foo.com/dir/*");
  EMITS(5, "foo.com", "/dir//page.html", HTS_FALSE, "+foo.com/dir//*");
  EMITS(7, "foo.com", "/dir//page.html", HTS_FALSE, "+foo.com/dir//*[file]");
  /* no directory to anchor on, so answers 1, 5 and 7 emit nothing */
  EMITS(1, "foo.com", "page.html", HTS_FALSE, "");
  EMITS(5, "foo.com", "page.html", HTS_FALSE, "");
  EMITS(7, "foo.com", "page.html", HTS_FALSE, "");

  /* the answers that add no filter at all */
  EMITS(-1, "foo.com", "/x", HTS_FALSE, "");
  EMITS(3, "foo.com", "/x", HTS_FALSE, "");
  EMITS(4, "foo.com", "/x", HTS_FALSE, "");
  EMITS(50, "foo.com", "/x", HTS_FALSE, "");
#undef EMITS
  printf("wizardfilter self-test OK\n");
  return 0;
}

static void wizard_cat_path(htsbuff *f, const char *sign, const char *adr,
                            const char *fil, size_t len) {
  wizard_cat_host(f, sign, adr);
  if (*fil != '/')
    htsbuff_cat(f, "/");
  htsbuff_catn(f, fil, len);
}

void hts_wizard_answer_filter(htsbuff *f, int n, const char *adr,
                              const char *fil, hts_boolean seeker_up) {
  size_t dir = hts_lastcharoffset(fil);

  while (fil[dir] != '/' && dir > 0)
    dir--;

  htsbuff_cpy(f, "");
  switch (n) {
  case 0: /* this link only */
    wizard_cat_path(f, "-", adr, fil, (size_t) -1);
    break;

  case 1: /* this directory and below */
    if (fil[dir] == '/') {
      /* stops before the last slash, so a doubled one collapses */
      wizard_cat_path(f, "-", adr, fil, dir);
      if (f->buf[f->len - 1] != '/')
        htsbuff_cat(f, "/");
      htsbuff_cat(f, "*");
    }
    break;

  case 2: /* the whole host */
    wizard_cat_host(f, "-", adr);
    htsbuff_cat(f, "/*");
    break;

  case 5: /* this directory and below, or the whole host */
    if (!seeker_up) {
      if (fil[dir] == '/') {
        wizard_cat_path(f, "+", adr, fil, dir + 1);
        htsbuff_cat(f, "*");
      }
    } else {
      wizard_cat_host(f, "+", adr);
      htsbuff_cat(f, "/*");
    }
    break;

  case 6: /* the whole host */
    wizard_cat_host(f, "+", adr);
    htsbuff_cat(f, "/*");
    break;

  case 7: /* this directory, files only */
    if (fil[dir] == '/') {
      wizard_cat_path(f, "+", adr, fil, dir + 1);
      htsbuff_cat(f, "*[file]");
    }
    break;

  default: /* the other answers add no filter */
    break;
  }
}

hts_boolean hts_link_is_foreign_asset(httrackp *opt, int ptr) {
  int parent;

  if (ptr <= 0)
    return HTS_FALSE;
  parent = heap(ptr)->precedent;
  /* Seeds hang off the synthetic primary link 0: the user asked for those. */
  if (parent <= 0 || parent >= opt->lien_tot)
    return HTS_FALSE;
  if (ishtml(opt, heap(ptr)->fil) != 0) /* hypertext, or no telling */
    return HTS_FALSE;
  /* adr carries the scheme and any user:pw@, so compare bare authorities. */
  return strfield2(jump_identification_const(heap(ptr)->adr),
                   jump_identification_const(heap(parent)->adr))
             ? HTS_FALSE
             : HTS_TRUE;
}

static T_SOC ftp_accept(lien_back *back, T_SOC soc, int timeout,
                        const httrackp *opt) {
  const TStamp started = time_local();
  T_SOC soc_dat;

  timeout = ftp_wait_left(opt, timeout);
  if (!socket_set_nonblocking(soc, HTS_TRUE))
    return INVALID_SOCKET;
  /* state.stop counts as in ftp_connect: nothing is established yet */
  while (check_socket(soc) == 0) {
    if (back->stop_ftp || (opt != NULL && opt->state.stop) ||
        (int) (time_local() - started) >= timeout)
      return INVALID_SOCKET;
    Sleep(100);
  }
  soc_dat = accept(soc, NULL, NULL);
  /* BSD hands the listener's non-blocking flag down to the accepted socket,
     which the transfer below reads blocking. */
  if (soc_dat != INVALID_SOCKET &&
      !socket_set_nonblocking(soc_dat, HTS_FALSE)) {
    deletesoc(soc_dat);
    return INVALID_SOCKET;
  }
  return soc_dat;
}

static void __attribute__((constructor)) closetrack_open(void) {
  const char *const path = getenv("CLOSETRACK_LOG");

  if (path != NULL) {
    closetrack_log =
        open(path, O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0600);
  }
}

static int closetrack_is_engine(void) {
  if (!closetrack_engine && dlsym(RTLD_DEFAULT, "hts_init") != NULL) {
    closetrack_engine = 1;
  }
  return closetrack_engine;
}

static const char *closetrack_status(int rc, int err) {
  if (rc == 0) {
    return "ok";
  }
  return err == EBADF ? "EBADF" : "other";
}

SHIM_EXPORT int close(int fd) {
  static int (*real_close)(int) = NULL;
  int rc, err;

  if (real_close == NULL) {
    *(void **) &real_close = dlsym(RTLD_NEXT, "close");
    if (real_close == NULL) {
      errno = ENOSYS;
      return -1;
    }
  }
  if (fd == closetrack_log) {
    /* Refused rather than obeyed: losing the log would blind the test. */
    rc = -1;
    err = EBADF;
  } else {
    rc = real_close(fd);
    err = errno;
  }
  if (closetrack_log != -1 && closetrack_is_engine()) {
    char line[64];
    const int len = snprintf(line, sizeof(line), "%d %d %s\n", fd, rc,
                             closetrack_status(rc, err));

    if (len > 0) {
      const ssize_t written = write(closetrack_log, line, (size_t) len);

      (void) written;
    }
  }
  errno = err;
  return rc;
}

static void *ftpcancel_thread(void *unused) {
  int (*push)(void *, const char *) = NULL;
  const char *const trigger = getenv("FTPCANCEL_TRIGGER");
  int left = 600;

  (void) unused;
  *(void **) &push = dlsym(RTLD_DEFAULT, "hts_cancel_file_push");
  if (trigger == NULL || push == NULL) {
    return NULL;
  }
  while (left-- > 0) {
    FILE *const fp = fopen(trigger, "rb");

    if (fp != NULL) {
      char url[2048];
      const char *const got = fgets(url, (int) sizeof(url), fp);
      char *const eol = got != NULL ? strchr(url, '\n') : NULL;

      fclose(fp);
      if (eol != NULL) {
        *eol = '\0';
        push(ftpcancel_opt, url);
        return NULL;
      }
    }
    usleep(100000);
  }
  return NULL;
}

SHIM_EXPORT void *hts_create_opt(void) {
  static void *(*real_create)(void) = NULL;
  pthread_t thread;

  if (real_create == NULL) {
    *(void **) &real_create = dlsym(RTLD_NEXT, "hts_create_opt");
    if (real_create == NULL) {
      return NULL;
    }
  }
  ftpcancel_opt = real_create();
  if (ftpcancel_opt != NULL &&
      pthread_create(&thread, NULL, ftpcancel_thread, NULL) == 0) {
    pthread_detach(thread);
  }
  return ftpcancel_opt;
}

static int saturate_case(void) {
  StringCapacity(room) = ((size_t) -1) / 2 + 1;
  alloc_fails = oom_jumps = 1;
  if (setjmp(oom_jump) == 0) {
    StringRoomTotal(room, (size_t) -1);
    printf("saturate: FAIL (grew through a failing allocator)\n");
    return 1;
  }
  if (!failure_reported("saturate")) {
    return 1;
  }
  if (last_request != (size_t) -1) {
    printf("saturate: FAIL (allocator asked for %lu bytes, want SIZE_MAX)\n",
           (unsigned long) last_request);
    return 1;
  }
  alloc_fails = 0;
  StringBuffRW(room) = NULL;
  StringFree(room);
  printf("saturate: OK\n");
  return 0;
}

static int growloop_case(void) {
  enum { maxSteps = 8 * sizeof(size_t) + 4 };

  alloc_pretends = oom_jumps = 1;
  alloc_budget = maxSteps;
  alloc_calls = 0;
  if (setjmp(oom_jump) != 0) {
    printf("growloop: FAIL (still growing after %d steps)\n", maxSteps);
    return 1;
  }
  StringRoomTotal(room, (size_t) -1);
  if (StringCapacity(room) != (size_t) -1) {
    printf("growloop: FAIL (stopped at capacity %lu)\n",
           (unsigned long) StringCapacity(room));
    return 1;
  }
  alloc_pretends = 0;
  StringBuffRW(room) = NULL; /* the stub's pointer never came from malloc */
  StringFree(room);
  printf("growloop: OK\n");
  return 0;
}

static void back_stop_preconnect(httrackp *opt, struct_back *sback) {
  lien_back *const back = sback->lnk;
  int aborted = 0;
  int i;

  for (i = 0; i < sback->count; i++) {
    if (!back_is_preconnect(back[i].status))
      continue;
    if (back[i].r.soc != INVALID_SOCKET)
      deletehttp(&back[i].r);
    back[i].r.soc = INVALID_SOCKET;
    /* fatal, as back_add() reports it: a stop must not schedule a retry */
    back[i].r.statuscode = STATUSCODE_INVALID;
    strcpybuff(back[i].r.msg, "mirror stopped by user");
    back_set_finished(sback, i);
    aborted++;
  }
  if (aborted > 0)
    hts_log_print(opt, LOG_WARNING,
                  "Mirror stopped by user, %d pending connection(s) aborted",
                  aborted);
}

static T_SOC st_backstop_pending(httrackp *opt, htsblk *r) {
  T_SOC soc;

  hts_init_htsblk(r);
  soc = newhttp_addr(opt, ST_BACKSTOP_DEADHOST, r, 80, 0, 0, NULL);
  if (soc == INVALID_SOCKET)
    return INVALID_SOCKET;
  r->soc = soc;
  if (check_socket_connect(soc) != 0) {
    strcpybuff(r->msg, "the network answers for this address");
    deletehttp(r);
    return INVALID_SOCKET;
  }
  return soc;
}

static hts_boolean st_backstop_soc_open(T_SOC soc) {
  int type = 0;
  socklen_t len = (socklen_t) sizeof(type);

  return getsockopt(soc, SOL_SOCKET, SO_TYPE, (char *) &type, &len) == 0
             ? HTS_TRUE
             : HTS_FALSE;
}

static void st_backstop_slot(struct_back *sback, int p, int status,
                             const htsblk *r) {
  lien_back *const back = &sback->lnk[p];

  back->r = *r;
  back->r.location = back->location_buffer;
  back->status = status;
  back->timeout = -1; /* only the stop may end these slots */
  back->rateout = -1;
  /* poisoned, so the expected outcome cannot be the value the slot came with */
  back->r.statuscode = STATUSCODE_TIMEOUT;
  strcpybuff(back->r.msg, "untouched");
  strcpybuff(back->url_adr, ST_BACKSTOP_DEADHOST);
  strcpybuff(back->url_fil, "/stalled.html");
  /* address list already probed, as it is for a live connect: re-probing it
     would resolve, and the fd churn would spoil the closed-socket check */
  sback->connect_fallback[p].addr_count = 1;
}

static hts_boolean st_backstop_arm(httrackp *opt, struct_back *sback,
                                   const int *status, htsblk *r, int slots,
                                   int dnsslot) {
  int i;

  for (i = 0; i < slots; i++) {
    deletehttp(&sback->lnk[i].r); /* whatever the previous round left */
    if (i == dnsslot) {
      hts_init_htsblk(&r[i]);
    } else if (st_backstop_pending(opt, &r[i]) == INVALID_SOCKET) {
      printf("backstop: SKIP (no stalled connect to " ST_BACKSTOP_DEADHOST
             ": %s)\n",
             r[i].msg);
      return HTS_FALSE;
    }
    st_backstop_slot(sback, i, status[i], &r[i]);
  }
  return HTS_TRUE;
}

static int st_backstop(httrackp *opt, int argc, char **argv) {
  /* pre-connect first, then the states a stop must leave running: two of the
     receive automaton, and the FTP one whose socket another thread owns */
  enum {
    SLOT_DNS = 0,
    SLOT_CONNECT,
    SLOT_SSL,
    SLOT_LAST_PRECONNECT = SLOT_SSL,
    SLOT_HEADERS,
    SLOT_XFER,
    SLOT_CHUNK,
    SLOT_FTP,
    SLOTS
  };

  static const int status[SLOTS] = {
      STATUS_WAIT_DNS,     STATUS_CONNECTING, STATUS_SSL_WAIT_HANDSHAKE,
      STATUS_WAIT_HEADERS, STATUS_TRANSFER,   STATUS_CHUNK_WAIT,
      STATUS_FTP_TRANSFER};
  T_SOC swept[SLOTS];
  htsblk r[SLOTS];
  struct_back *sback = NULL;
  cache_back cache;
  lien_back *back;
  int err = 0;
  int skipped = 0;
  int round;
  int i;

  (void) argc;
  (void) argv;

  /* no quota may fire instead of the stop, and no slot may time out */
  opt->maxtime = opt->maxsite = 0;
  opt->timeout = 0;
  opt->state.stop = 0;

  memset(&cache, 0, sizeof(cache));

#define CHECK(cond)                                                            \
  do {                                                                         \
    if (!(cond)) {                                                             \
      printf("  FAIL line %d: %s\n", __LINE__, #cond);                         \
      err = 1;                                                                 \
    }                                                                          \
  } while (0)

  cache.hashtable = coucal_new(0);
  sback = back_new(opt, SLOTS);
  back = sback->lnk;
  if (!st_backstop_arm(opt, sback, status, r, SLOTS, SLOT_DNS)) {
    skipped = 1;
    goto cleanup;
  }

  /* Control: with the mirror running, back_wait ends nothing. A sweep that
     fired unconditionally would strand every connect the crawl opens. Only the
     states back_wait leaves alone are checked; it advances the resolution and
     handshake waits by itself, the first to connect and the second to an error
     for want of a TLS session this fixture cannot build. */
  back_wait(sback, opt, &cache, 0);
  CHECK(back[SLOT_CONNECT].status == STATUS_CONNECTING);
  for (i = SLOT_HEADERS; i < SLOTS; i++)
    CHECK(back[i].status == status[i]);
  for (i = SLOT_CONNECT; i < SLOTS; i++) {
    if (i == SLOT_SSL)
      continue;
    CHECK(back[i].r.statuscode == STATUSCODE_TIMEOUT);
    CHECK(strcmp(back[i].r.msg, "untouched") == 0);
  }

  /* Twice, re-armed in between: the sweep runs on every wait, not once. A slot
     that was connecting when the user hit ^C is the case under test, so the
     flag goes up after the slots are in place. */
  for (round = 0; round < 2 && !err; round++) {
    opt->state.stop = 0;
    if (!st_backstop_arm(opt, sback, status, r, SLOTS, SLOT_DNS)) {
      skipped = 1;
      goto cleanup;
    }
    for (i = 0; i < SLOTS; i++)
      swept[i] = r[i].soc;
    hts_request_stop(opt, 0);

    back_wait(sback, opt, &cache, 0);

    /* every pre-connect slot is gone, its socket closed rather than merely
       forgotten, and reported as fatal so the link is not queued again */
    for (i = SLOT_DNS; i <= SLOT_LAST_PRECONNECT; i++) {
      CHECK(back[i].status == STATUS_READY);
      CHECK(back[i].r.soc == INVALID_SOCKET);
      CHECK(back[i].r.statuscode == STATUSCODE_INVALID);
      CHECK(strcmp(back[i].r.msg, "mirror stopped by user") == 0);
      if (swept[i] != INVALID_SOCKET)
        CHECK(!st_backstop_soc_open(swept[i]));
    }
    /* control: a started transfer is what the stop lets finish, and the FTP
       socket belongs to another thread; a wider sweep is the wrong fix */
    for (i = SLOT_HEADERS; i < SLOTS; i++) {
      CHECK(back[i].status == status[i]);
      CHECK(back[i].r.soc == swept[i]);
      CHECK(st_backstop_soc_open(back[i].r.soc));
      CHECK(back[i].r.statuscode == STATUSCODE_TIMEOUT);
      CHECK(strcmp(back[i].r.msg, "untouched") == 0);
    }
  }
#undef CHECK

cleanup:
  opt->state.stop = 0;
  for (i = 0; i < SLOTS; i++)
    deletehttp(&back[i].r);
  back_free(&sback);
  coucal_delete(&cache.hashtable);
  if (skipped)
    return 77;

  printf("backstop self-test: %s\n", err ? "FAIL" : "OK");
  return err;
}

static void st_warc_emit(httrackp *opt, const char *body) {
  lien_back *back = calloct(1, sizeof(lien_back));

  assertf(back != NULL);
  strcpybuff(back->url_adr, "example.com");
  strcpybuff(back->url_fil, "/teardown.html");
  back->r.statuscode = 200;
  strcpybuff(back->r.msg, "OK");
  strcpybuff(back->r.contenttype, "text/html");
  back->r.adr = strdupt(body);
  back->r.size = (LLint) strlen(body);
  warc_write_backtransaction(opt, back);
  freet(back->r.adr);
  freet(back);
}

static hts_boolean st_blob_has(const unsigned char *blob, size_t len,
                               const char *s) {
  const size_t n = strlen(s);
  size_t i;

  for (i = 0; n <= len && i <= len - n; i++) {
    if (memcmp(blob + i, s, n) == 0)
      return HTS_TRUE;
  }
  return HTS_FALSE;
}

static int st_warc_holds(const char *name, const char *path, const char *want,
                         const char *absent1, const char *absent2) {
  const char *const absent[2] = {absent1, absent2};
  size_t len = 0, i;
  unsigned char *blob = warc_slurp(path, &len);
  int err = 0;

  if (blob == NULL) {
    fprintf(stderr, "warc-teardown: %s: cannot read %s\n", name, path);
    return 1;
  }
  /* shape, not validity: the first record's version line, nothing more */
  if (len < 8 || memcmp(blob, "WARC/1.1", 8) != 0) {
    fprintf(stderr, "warc-teardown: %s: %s does not open on a WARC record\n",
            name, path);
    err++;
  }
  if (!st_blob_has(blob, len, want)) {
    fprintf(stderr, "warc-teardown: %s: %s lost the run holding \"%s\"\n", name,
            path, want);
    err++;
  }
  for (i = 0; i < 2; i++) {
    if (st_blob_has(blob, len, absent[i])) {
      fprintf(stderr, "warc-teardown: %s: %s took \"%s\"\n", name, path,
              absent[i]);
      err++;
    }
  }
  freet(blob);
  return err;
}

static int st_warc_teardown_case(httrackp *opt, const char *name,
                                 const char *path, hts_boolean abort_run) {
  static const char run1[] = "teardown-run-1-body";
  static const char run2[] = "teardown-run-2-body-longer";
  static const char late[] = "teardown-late-body";
  char tmp[HTS_URLMAXSIZE * 2 + 8];
  char catbuff[CATBUFF_SIZE];
  int err = 0;

  snprintf(tmp, sizeof(tmp), "%s.tmp", path);
  (void) UNLINK(fconv(catbuff, sizeof(catbuff), path));
  (void) UNLINK(fconv(catbuff, sizeof(catbuff), tmp));
  StringCopy(opt->warc_file, path);

  /* stands in for the per-mirror memset in hts_create_opt(): this test reuses
     the dispatcher's opt where the engine always has a fresh one */
  opt->state.warc = NULL;
  st_warc_emit(opt, run1);
  warc_close_opt(opt);
  if (fsize_utf8(path) <= 0) {
    fprintf(stderr, "warc-teardown: %s: the hook opened no archive\n", name);
    return 1;
  }

  /* a previous archive is now there, so this run goes through the temporary */
  opt->state.warc = NULL;
  st_warc_emit(opt, run2);
  if (!fexist_utf8(tmp)) {
    fprintf(stderr, "warc-teardown: %s: no temporary beside %s\n", name, path);
    return 1;
  }
  if (abort_run)
    warc_abort_opt(opt);
  else
    warc_close_opt(opt);

  st_warc_emit(opt, late); /* what back_finalize emits during teardown */
  if (fexist_utf8(tmp)) {
    fprintf(stderr, "warc-teardown: %s: orphan temporary %s\n", name, tmp);
    err++;
  }
  /* abort keeps run 1, close commits run 2; the late body guards against an
     append, no reopen can reach the archive without losing that run first */
  err += abort_run ? st_warc_holds(name, path, run1, run2, late)
                   : st_warc_holds(name, path, run2, run1, late);
  return err;
}

static int st_warc_teardown(httrackp *opt, int argc, char **argv) {
  char path[HTS_URLMAXSIZE], saved_file[HTS_URLMAXSIZE];
  void *saved_state;
  int err = 0;

  if (argc < 1) {
    fprintf(stderr, "warc-teardown: needs a writable directory\n");
    return 1;
  }
  saved_state = opt->state.warc;
  strlcpybuff(saved_file, StringBuff(opt->warc_file), sizeof(saved_file));

  fconcat(path, sizeof(path), argv[0], "teardown-close.warc");
  err += st_warc_teardown_case(opt, "close", path, HTS_FALSE);
  fconcat(path, sizeof(path), argv[0], "teardown-abort.warc");
  err += st_warc_teardown_case(opt, "abort", path, HTS_TRUE);

  StringCopy(opt->warc_file, saved_file);
  opt->state.warc = saved_state;
  printf("warc-teardown: %s\n", err ? "FAIL" : "OK");
  return err;
}

static int ftp_wait_left(const httrackp *opt, int timeout) {
  if (opt != NULL && opt->maxtime > 0) {
    const TStamp left =
        (TStamp) opt->maxtime - (time_local() - HTS_STAT.stat_timestart);

    if (left < (TStamp) timeout)
      timeout = left > 0 ? (int) left : 0;
  }
  return timeout;
}

static hts_boolean ftp_connect(lien_back *back, T_SOC soc, SOCaddr *server,
                               int timeout, const httrackp *opt) {
  const TStamp started = time_local();

  timeout = ftp_wait_left(opt, timeout);
  if (!socket_set_nonblocking(soc, HTS_TRUE))
    return HTS_FALSE;
  if (connect(soc, &SOCaddr_sockaddr(*server), SOCaddr_size(*server)) != 0) {
#ifdef _WIN32
    if (WSAGetLastError() != WSAEWOULDBLOCK)
#else
    if (errno != EINPROGRESS && errno != EINTR)
#endif
      return HTS_FALSE;
    /* state.stop counts here, unlike in the waits below: a mirror the user
       stopped has nothing to finish on a connection never established. */
    while (check_socket_connect(soc) == 0) {
      if (back->stop_ftp || (opt != NULL && opt->state.stop) ||
          (int) (time_local() - started) >= timeout)
        return HTS_FALSE;
      Sleep(100);
    }
    if (connect_socket_error(soc) != 0)
      return HTS_FALSE;
  }
  /* the rest of the session reads and writes this socket blocking */
  return socket_set_nonblocking(soc, HTS_FALSE);
}

static SOCaddr *ftp_dns_resolve(httrackp *opt, lien_back *back,
                                const char *host, SOCaddr *addr, int timeout,
                                const char **error) {
  const int left = ftp_wait_left(opt, timeout);

  SOCaddr_clear(*addr);
  if (left <= 0) {
    if (error != NULL)
      *error = "mirror deadline reached";
    return NULL;
  }
  if (hts_dns_resolve_all_bounded(opt, host, addr, 1, left, &back->stop_ftp,
                                  error) > 0)
    return SOCaddr_is_valid(*addr) ? addr : NULL;
  return NULL;
}

hts_boolean socket_set_nonblocking(T_SOC soc, hts_boolean nonblocking) {
#ifdef _WIN32
  unsigned long p = nonblocking ? 1 : 0;

  return ioctlsocket(soc, FIONBIO, &p) == 0 ? HTS_TRUE : HTS_FALSE;
#else
  const int flags = fcntl(soc, F_GETFL, 0);
  const int wanted = nonblocking ? (flags | O_NONBLOCK) : (flags & ~O_NONBLOCK);

  if (flags == -1 || fcntl(soc, F_SETFL, wanted) == -1)
    return HTS_FALSE;
  return HTS_TRUE;
#endif
}

int connect_socket_error(T_SOC soc) {
  int soerr = 0;
  socklen_t len = (socklen_t) sizeof(soerr);

  if (getsockopt(soc, SOL_SOCKET, SO_ERROR, (char *) &soerr, &len) != 0)
    return -1;
  return soerr;
}

static int hts_dns_resolve_nocache_list_bounded(
    const char *hostname, SOCaddr *const out, const int max, const int timeout,
    const volatile hts_boolean *cancel, const char **error) {
  /* no bound asked for (--timeout 0), and nobody to cut it short either */
  if (timeout <= 0 && cancel == NULL)
  /* timeout <= 0 got here only for a cancellable resolve: no deadline then */
  deadline = timeout > 0 ? mtime_local() + (TStamp) timeout * 1000 : 0;
    if (done || (cancel != NULL && *cancel) ||
        (deadline != 0 && mtime_local() >= deadline))
  assertf(opt != NULL);
  return hts_dns_resolve_all_bounded(opt, iadr, out, max, opt->timeout, NULL,
                                     error);
}

static int unlinkfail_held_open(const char *pathname) {
  struct stat target;
  DIR *dir;
  struct dirent *ent;
  int held = 0;

  if (stat(pathname, &target) != 0) {
    return 0;
  }
  dir = opendir("/proc/self/fd");
  if (dir == NULL) {
    return 0;
  }
  while (!held && (ent = readdir(dir)) != NULL) {
    char path[64];
    struct stat st;

    if (ent->d_name[0] == '.') {
      continue;
    }
    snprintf(path, sizeof(path), "/proc/self/fd/%s", ent->d_name);
    if (stat(path, &st) == 0 && st.st_dev == target.st_dev &&
        st.st_ino == target.st_ino) {
      held = 1;
    }
  }
  closedir(dir);
  return held;
}

static void unlinkfail_log(const char *state, const char *pathname) {
  const char *const log = getenv("UNLINKFAIL_LOG");
  FILE *fp;

  if (log == NULL || (fp = fopen(log, "ab")) == NULL) {
    return;
  }
  fprintf(fp, "%s %s\n", state, pathname);
  fclose(fp);
}

SHIM_EXPORT int unlink(const char *pathname) {
  static int (*real_unlink)(const char *) = NULL;
  const char *const match = getenv("UNLINKFAIL_MATCH");
  const char *const slash = strrchr(pathname, '/');
  const char *const base = slash != NULL ? slash + 1 : pathname;

  if (match != NULL && strcmp(base, match) == 0) {
    if (unlinkfail_held_open(pathname)) {
      unlinkfail_log("open", pathname);
      errno = EACCES;
      return -1;
    }
    unlinkfail_log("closed", pathname);
  }
  if (real_unlink == NULL) {
    *(void **) &real_unlink = dlsym(RTLD_NEXT, "unlink");
    if (real_unlink == NULL) {
      errno = ENOSYS;
      return -1;
    }
  }
  return real_unlink(pathname);
}

static int array_growth_selftests(void) {
  TypedArray(char) a = EMPTY_TYPED_ARRAY;
  TypedArray(arrays_wide_t) w = EMPTY_TYPED_ARRAY;
  size_t i;
  int err = 0;

  TypedArrayEnsureRoom(a, 1);
  if (TypedArrayRoom(a) < 1 || TypedArrayCapa(a) < 16)
    err = 1;

  /* A request past the current capacity must be met, not landed short of. */
  TypedArrayAppend(a, "0123456789", 10);
  TypedArrayEnsureRoom(a, 1000);
  if (TypedArrayRoom(a) < 1000 || TypedArraySize(a) != 10)
    err = 1;
  if (memcmp(TypedArrayElts(a), "0123456789", 10) != 0)
    err = 1;

  /* Capacity must always keep capa*width representable. */
  TypedArrayEnsureRoom(w, 3);
  if (TypedArrayRoom(w) < 3 ||
      TypedArrayCapa(w) > ((size_t) -1) / sizeof(arrays_wide_t))
    err = 1;

  /* Many small growths, checking the payload survives every reallocation. */
  for (i = 0; i < 5000; i++) {
    TypedArrayAdd(a, (char) ('a' + (i % 26)));
  }
  if (TypedArraySize(a) != 5010)
    err = 1;
  else {
    for (i = 0; i < 5000; i++) {
      if (TypedArrayNth(a, 10 + i) != (char) ('a' + (i % 26)))
        err = 1;
    }
  }

  TypedArrayFree(a);
  TypedArrayFree(w);
  return err;
}

static int st_arrays(httrackp *opt, int argc, char **argv) {
  /* volatile keeps the sizes below opaque, so these stay runtime checks rather
     than compile-time allocation warnings. */
  volatile size_t room;

  (void) opt;
  if (argc >= 1 && strcmp(argv[0], "overflow-capa") == 0) {
    /* Room whose byte size cannot fit a size_t: capa*width used to wrap and
       hand back a short allocation. */
    TypedArray(arrays_wide_t) w = EMPTY_TYPED_ARRAY;

    room = ((size_t) -1) / sizeof(arrays_wide_t) + 1;
    TypedArrayEnsureRoom(w, room);
    /* Unreachable, and printing the pointer is what keeps it so: an allocation
       reaching nobody is removable, and its "== NULL" folds away with it. */
    printf("arrays: NOT aborted (%p)\n", TypedArrayPtr(w));
    return 1;
  } else if (argc >= 1 && strcmp(argv[0], "overflow-loop") == 0) {
    /* Doubling past SIZE_MAX used to wrap capa to 0 and spin forever. */
    TypedArray(char) a = EMPTY_TYPED_ARRAY;

    room = (size_t) -1;
    TypedArrayEnsureRoom(a, room);
    printf("arrays: NOT aborted (%p)\n", TypedArrayPtr(a)); /* unreachable */
    return 1;
  } else {
    const int err = array_growth_selftests();

    printf("arrays: %s\n", err ? "FAIL" : "OK");
    return err;
  }
}

static void st_cdx_log_cb(httrackp *opt, int type, const char *format,
                          va_list args) {
  char line[512];
  (void) opt;
  (void) type;
  (void) vsnprintf(line, sizeof(line), format, args);
  if (strncmp(line, "WARC:", 5) == 0)
    strlncatbuff(st_cdx_log, line, sizeof(st_cdx_log),
                 sizeof(st_cdx_log) - strlen(st_cdx_log) - 1);
}

static int st_cdx_logged(const char *name, const char *want) {
  const int bad =
      want != NULL ? strstr(st_cdx_log, want) == NULL : st_cdx_log[0] != '\0';
  if (bad)
    fprintf(stderr, "warc-cdx-errors: %s logged \"%s\", want \"%s\"\n", name,
            st_cdx_log, want != NULL ? want : "(nothing)");
  st_cdx_log[0] = '\0';
  return bad;
}

static void st_cdx_leave(const char *path, const char *content) {
  FILE *const fp = FOPEN(path, "wb");

  assertf(fp != NULL);
  fputs(content, fp);
  fclose(fp);
}

static void st_cdx_fill(warc_writer *w, int n, size_t pad) {
  char url[1024], req[1100];
  int i;

  for (i = 0; i < n; i++) {
    size_t l =
        (size_t) snprintf(url, sizeof(url), "http://e%d.example.com/", i);

    while (l + 1 < sizeof(url) && l < pad)
      url[l++] = 'p';
    url[l] = '\0';
    snprintf(req, sizeof(req),
             "GET / HTTP/1.1\r\nHost: e%d.example.com\r\n\r\n", i);
    warc_write_transaction(w, url, "127.0.0.1", req,
                           "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n",
                           "body\n", 5, NULL, NULL, 200, 0, 0);
  }
}

static int st_warc_cdx_errors(httrackp *opt, int argc, char **argv) {
  char path[HTS_URLMAXSIZE], cdx[HTS_URLMAXSIZE];
  static const char stale[] = "no record was indexed";
  static const char unwritable[] = "could not write the index";
  hts_boolean saved_cdx;
  void *saved_state;
  warc_writer *w;
  int err = 0;

  if (argc < 1) {
    fprintf(stderr, "warc-cdx-errors: needs a writable directory\n");
    return 1;
  }
  saved_state = opt->state.warc;
  saved_cdx = opt->warc_cdx;
  opt->warc_cdx = 1;
  st_cdx_log[0] = '\0';
  hts_set_log_vprint_callback(st_cdx_log_cb);

  /* No previous archive and nothing indexed: nothing on disk went stale. */
  fconcat(path, sizeof(path), argv[0], "cdxerr-first.warc.gz");
  w = warc_open(opt, path);
  assertf(w != NULL);
  warc_close(w);
  err |= st_cdx_logged("first run", NULL);

  /* A previous archive and its index: this run swapped over the first, so the
     second now describes an archive that is gone. */
  fconcat(path, sizeof(path), argv[0], "cdxerr-prev.warc.gz");
  fconcat(cdx, sizeof(cdx), argv[0], "cdxerr-prev.cdx");
  st_cdx_leave(path, "previous archive");
  st_cdx_leave(cdx, "com,example)/ 20240101000000 {}\n");
  w = warc_open(opt, path);
  assertf(w != NULL);
  warc_close(w);
  err |= st_cdx_logged("swap over a previous archive", stale);

  /* Mirror case: written in place, then abandoned, so the archive is clobbered
     and the index beside it describes what used to be there. */
  fconcat(path, sizeof(path), argv[0], "cdxerr-abort.warc.gz");
  fconcat(cdx, sizeof(cdx), argv[0], "cdxerr-abort.cdx");
  st_cdx_leave(cdx, "com,example)/ 20240101000000 {}\n");
  w = warc_open(opt, path);
  assertf(w != NULL);
  opt->state.warc = w;
  warc_abort_opt(opt);
  err |= st_cdx_logged("abandoned in-place run", stale);

  /* Same, with no index left behind: the message would name a file that never
     existed, which is the false alarm the gate is there to avoid. */
  fconcat(path, sizeof(path), argv[0], "cdxerr-abort-noidx.warc.gz");
  w = warc_open(opt, path);
  assertf(w != NULL);
  opt->state.warc = w;
  warc_abort_opt(opt);
  err |= st_cdx_logged("abandoned run with no index", NULL);

  /* An archive that never opened replaced nothing, so the index beside it
     still describes what is there: the failed open is the only error. */
  fconcat(path, sizeof(path), argv[0], "cdxerr-noopen.warc.gz");
  fconcat(cdx, sizeof(cdx), argv[0], "cdxerr-noopen.cdx");
  st_cdx_leave(cdx, "com,example)/ 20240101000000 {}\n");
  if (MKDIR(path) != 0 && errno != EEXIST) {
    fprintf(stderr, "warc-cdx-errors: mkdir %s failed: %s\n", path,
            strerror(errno));
    err = 1;
  } else {
    assertf(warc_open(opt, path) == NULL);
    err |= st_cdx_logged("archive that never opened", NULL);
  }

  /* The index path cannot be opened at all. */
  fconcat(path, sizeof(path), argv[0], "cdxerr-fopen.warc.gz");
  fconcat(cdx, sizeof(cdx), argv[0], "cdxerr-fopen.cdx");
  if (MKDIR(cdx) != 0 && errno != EEXIST) {
    fprintf(stderr, "warc-cdx-errors: mkdir %s failed: %s\n", cdx,
            strerror(errno));
    err = 1;
  } else {
    w = warc_open(opt, path);
    assertf(w != NULL);
    st_cdx_fill(w, 1, 0);
    warc_close(w);
    err |= st_cdx_logged("unopenable index path", unwritable);
  }

#ifndef _WIN32
  /* /dev/full fails every write with ENOSPC. An index below one stdio buffer
     never reaches the device until fclose, and a larger one errors before it,
     which is the difference the two messages carry. */
  if (access("/dev/full", W_OK) == 0) {
    fconcat(path, sizeof(path), argv[0], "cdxerr-short.warc.gz");
    fconcat(cdx, sizeof(cdx), argv[0], "cdxerr-short.cdx");
    (void) UNLINK(cdx);
    if (symlink("/dev/full", cdx) != 0) {
      fprintf(stderr, "warc-cdx-errors: symlink %s failed: %s\n", cdx,
              strerror(errno));
      err = 1;
    } else {
      w = warc_open(opt, path);
      assertf(w != NULL);
      st_cdx_fill(w, 1, 0);
      warc_close(w);
      err |= st_cdx_logged("index lost at fclose", unwritable);

      fconcat(path, sizeof(path), argv[0], "cdxerr-partial.warc.gz");
      fconcat(cdx, sizeof(cdx), argv[0], "cdxerr-partial.cdx");
      (void) UNLINK(cdx);
      if (symlink("/dev/full", cdx) != 0) {
        fprintf(stderr, "warc-cdx-errors: symlink %s failed: %s\n", cdx,
                strerror(errno));
        err = 1;
      } else {
        w = warc_open(opt, path);
        assertf(w != NULL);
        st_cdx_fill(w, 64, 512); /* well over any stdio buffer */
        warc_close(w);
        err |= st_cdx_logged("index truncated mid-write", "is incomplete");
      }
    }
  } else {
    printf("warc-cdx-errors: no /dev/full, skipping the write-failure cases\n");
  }
#endif

  hts_set_log_vprint_callback(NULL);
  opt->warc_cdx = saved_cdx;
  opt->state.warc = saved_state;
  printf("warc-cdx-errors: %s\n", err ? "FAIL" : "OK");
  return err;
}

void warc_abort_opt(httrackp *opt) {
  if (opt->state.warc != NULL && opt->state.warc != WARC_DISABLED) {
    warc_writer *const w = (warc_writer *) opt->state.warc;
    /* the session is rolling back, so this run must replace nothing */
    w->failed = HTS_TRUE;
    warc_close(w);
  }
  opt->state.warc = NULL;
}

