	}
}

inline __attribute__((always_inline)) uint64_t util_rdtsc_begin() {
	uint64_t a, d;
	asm volatile ("mfence\n\t"
			"RDTSCP\n\t"
			"mov %%rdx, %0\n\t"
			"mov %%rax, %1\n\t"
			"xor %%rax, %%rax\n\t"
			"lfence\n\t"
			: "=r" (d), "=r" (a)
			:
			: "%rax", "%rbx", "%rcx", "%rdx");
	a = (d<<32) | a;
	return a;
}

inline __attribute__((always_inline)) uint64_t util_rdtsc_end() {
	uint64_t a, d;
	asm volatile(
			"xor %%rax, %%rax\n\t"
			"lfence\n\t"
			"RDTSCP\n\t"
			"mov %%rdx, %0\n\t"
			"mov %%rax, %1\n\t"
			"mfence\n\t"
			: "=r" (d), "=r" (a)
			:
			: "%rax", "%rbx", "%rcx", "%rdx");
	a = (d<<32) | a;
	return a;
}

void util_prefetch(void* p)
{
	asm volatile (
			"prefetchnta (%0)\n"
			"prefetcht2 (%0)\n"
			: : "r" (p));
}

size_t util_flushandreload(void* addr) // row miss
{
	size_t time = util_rdtsc_begin();
	util_prefetch(addr);
	size_t delta = util_rdtsc_end() - time;
	return delta;
}

