static bool is_coz_header(const line* l) {
  auto f = l->get_file();
  if(!f) return false;
  const auto& name = f->get_name();
  if(name.length() < 6) return false;
  // Check for coz.h preceded by a directory separator (/ on Unix, \ on Windows)
  char sep = name[name.length() - 6];
  return (sep == '/' || sep == '\\') && name.compare(name.length() - 5, 5, "coz.h") == 0;
}

id critical_work() {
  for (volatile int i = 0; i < 5000000; i++) {
    shared_counter++;  // line 14 — should be the bottleneck
  }
}

//

local_work() {
  volatile unsigned long long x = 0;
  for (volatile int i = 0; i < 1000000; i++) {
    x++;  // line 22 — should show ~0% impact
  }
}

stru

worker(void* arg) {
  int iters = ((thread_arg*)arg)->iterations;
  for (int i = 0; i < iters; i++) {
    local_work();

    pthread_mutex_lock(&the_lock);
    critical_work();
    pthread_mutex_unlock(&the_lock);

    COZ_PROGRESS;
  }
  return nullptr;
}

int

in() {
  const int NUM_THREADS = 4;
  const int ITERS_PER_THREAD = 500;

  printf("Lock contention test: %d threads, %d iterations each\n", NUM_THREADS, ITERS_PER_THREAD);

  pthread_t threads[NUM_THREADS];
  thread_arg args[NUM_THREADS];

  for (int i = 0; i < NUM_THREADS; i++) {
    args[i].iterations = ITERS_PER_THREAD;
    pthread_create(&threads[i], nullptr, worker, &args[i]);
  }

  for (int i = 0; i < NUM_THREADS; i++) {
    pthread_join(threads[i], nullptr);
  }

  printf("Done.\n");
}

int coz_pthread_mutex_lock(pthread_mutex_t* mutex) {
  if (!coz_initialized()) return orig_pthread_mutex_lock(mutex);
  coz_pre_block();
  int result = orig_pthread_mutex_lock(mutex);
  coz_post_block(true);
  return result;
}

int coz_pthread_cond_wait(pthread_cond_t* cond, pthread_mutex_t* mutex) {
  if (!coz_initialized()) return orig_pthread_cond_wait(cond, mutex);
  coz_pre_block();
  int result = orig_pthread_cond_wait(cond, mutex);
  coz_post_block(true);
  return result;
}

int coz_pthread_cond_timedwait(pthread_cond_t* cond, pthread_mutex_t* mutex,
                               const struct timespec* abstime) {
  if (!coz_initialized()) return orig_pthread_cond_timedwait(cond, mutex, abstime);
  coz_pre_block();
  int result = orig_pthread_cond_timedwait(cond, mutex, abstime);
  coz_post_block(result == 0);
  return result;
}

int coz_pthread_rwlock_rdlock(pthread_rwlock_t* rwlock) {
  if (!coz_initialized()) return orig_pthread_rwlock_rdlock(rwlock);
  coz_pre_block();
  int result = orig_pthread_rwlock_rdlock(rwlock);
  coz_post_block(true);
