ig_sigaction(int signum, const struct sigaction* act, struct sigaction* oldact) {
  return orig_sigaction(signum, act, oldact);
}

int coz_

ig_sigprocmask(int how, const sigset_t* set, sigset_t* oldset) {
  return orig_sigprocmask(how, set, oldset);
}

int coz_

static bool is_internal_thread(mach_port_t port) {
  if (port == g_sampling_thread_port) return true;
  spinlock& lock = get_internal_lock();
  std::vector<mach_port_t>& ports = get_internal_ports();
  lock.lock();
  bool found = std::find(ports.begin(), ports.end(), port) != ports.end();
  lock.unlock();
  return found;
}

void macos_register_internal_thread(mach_port_t port) {
  spinlock& lock = get_internal_lock();
  std::vector<mach_port_t>& ports = get_internal_ports();
  lock.lock();
  ports.push_back(port);
  lock.unlock();
}

void _coz_add_delays() {
  if(initialized) {
    profiler::get_instance().catch_up();
  }
}

int coz_handle_pthread_create(pthread_t* thread,
                                          const pthread_attr_t* attr,
                                          thread_fn_t fn,
                                          void* arg) {
  return profiler::get_instance().handle_pthread_create(thread, attr, fn, arg);
}

int coz_pthread_create(pthread_t* thread,
                       const pthread_attr_t* attr,
                       void* (*fn)(void*),
                       void* arg) {
  if (!coz_initialized()) {
    return orig_pthread_create(thread, attr, fn, arg);
  }

  // Call profiler's handle_pthread_create
  extern int coz_handle_pthread_create(pthread_t*, const pthread_attr_t*, thread_fn_t, void*);
  return coz_handle_pthread_create(thread, attr, (thread_fn_t)fn, arg);
}

void __attribute__((noreturn)) coz_pthread_exit(void* result) {
  if (coz_initialized()) {
    extern void coz_handle_pthread_exit(void*);
    coz_handle_pthread_exit(result);
    // handle_pthread_exit doesn't return
  }
  orig_pthread_exit(result);
  __builtin_unreachable();
}

int coz_pthread_join(pthread_t t, void** retval) {
  if (!coz_initialized()) {
    return orig_pthread_join(t, retval);
  }

  extern void coz_pre_block();
  extern void coz_post_block(bool);

  coz_pre_block();
  int result = orig_pthread_join(t, retval);
  coz_post_block(true);

  return result;
}

int coz_orig_pthread_create(pthread_t* thread,
                            const pthread_attr_t* attr,
                            void* (*fn)(void*),
                            void* arg) {
  return orig_pthread_create(thread, attr, fn, arg);
}

static bool is_thread_suspendable(mach_port_t thread_port) {
  thread_basic_info_data_t info;
  mach_msg_type_number_t count = THREAD_BASIC_INFO_COUNT;
  kern_return_t kr = thread_info(thread_port, THREAD_BASIC_INFO,
                                  (thread_info_t)&info, &count);
  if (kr != KERN_SUCCESS) {
    return false;
  }
  // TH_STATE_RUNNING = 1 (currently executing)
  // TH_STATE_STOPPED = 2 (stopped, not runnable)
  // TH_STATE_WAITING = 3 (waiting/blocked)
  // TH_STATE_UNINTERRUPTIBLE = 4 (waiting uninterruptibly)
  // TH_STATE_HALTED = 5 (halted at clean point)
  // Don't suspend threads that are already waiting/blocked - they may be holding locks
  // or in system calls. Only suspend running threads.
  return info.run_state == TH_STATE_RUNNING || info.run_state == TH_STATE_STOPPED;
}

static size_t apply_delay_via_suspension(mach_port_t thread_port, size_t delay_ns) {
  if (thread_port == MACH_PORT_NULL || delay_ns == 0) {
    return 0;
  }

  g_suspension_attempts.fetch_add(1, std::memory_order_relaxed);

  // Try to suspend the thread directly.
  // If it's in a blocked state, it will already be "suspended" from a timing perspective,
  // so we can just add the delay to its local counter without actually suspending.
  kern_return_t kr = thread_suspend(thread_port);
  if (kr != KERN_SUCCESS) {
    // Thread couldn't be suspended - check if it's already blocked/waiting
    thread_basic_info_data_t info;
    mach_msg_type_number_t count = THREAD_BASIC_INFO_COUNT;
    kern_return_t info_kr = thread_info(thread_port, THREAD_BASIC_INFO,
                                        (thread_info_t)&info, &count);
    if (info_kr == KERN_SUCCESS &&
        (info.run_state == TH_STATE_WAITING || info.run_state == TH_STATE_UNINTERRUPTIBLE)) {
      // Thread is already blocked - it will naturally "catch up" when it unblocks
      g_suspension_state_blocked.fetch_add(1, std::memory_order_relaxed);
      return delay_ns;  // Credit the delay anyway since thread is effectively paused
    }
    g_suspension_failed.fetch_add(1, std::memory_order_relaxed);
    return 0;
  }

  // Wait for the delay duration
  struct timespec ts;
  ts.tv_sec = delay_ns / 1000000000;
  ts.tv_nsec = delay_ns % 1000000000;
  nanosleep(&ts, nullptr);

  // Resume the thread
  thread_resume(thread_port);

  g_mach_suspensions.fetch_add(1, std::memory_order_relaxed);
  return delay_ns;
}

static string json_escape(const string& s) {
  string result;
  result.reserve(s.size() + 8);
  for(char c : s) {
    switch(c) {
      case '"':  result += "\\\""; break;
      case '\\': result += "\\\\"; break;
      case '\b': result += "\\b"; break;
      case '\f': result += "\\f"; break;
      case '\n': result += "\\n"; break;
      case '\r': result += "\\r"; break;
      case '\t': result += "\\t"; break;
      default:   result += c; break;
    }
  }
  return result;
}

void profiler::process_all_samples() {
  _thread_states.for_each([this](pid_t tid, thread_state* state) {
    // Process samples for this thread state
    // Note: We don't call add_delays here since that's thread-specific
    for(perf_event::record r : state->sampler) {
      if(r.is_sample()) {
        std::pair<line*, bool> sampled_line = match_line(r);
        if(sampled_line.first) {
          sampled_line.first->add_sample();
        }
      }
    }
  });
}

const void* load(dwarf::section_type section, size_t* size_out) override {
    auto it = _sections.find(section);
    if (it == _sections.end())
      return nullptr;
    if (size_out)
      *size_out = it->second.size;
    return it->second.data;
  }

bool section_name_to_type(const std::string& name, dwarf::section_type* out) {
  // ELF uses .debug_*, Mach-O uses __debug_*
  const char* suffix = nullptr;

  if (name.compare(0, 7, ".debug_") == 0) {
    suffix = name.c_str() + 7;
  } else if (name.compare(0, 8, "__debug_") == 0) {
    suffix = name.c_str() + 8;
  } else {
    return false;
  }

  // Map suffix to section_type (includes DWARF 5 sections)
  if (std::strcmp(suffix, "abbrev") == 0) {
    *out = dwarf::section_type::abbrev;
  } else if (std::strcmp(suffix, "addr") == 0) {
    *out = dwarf::section_type::addr;
  } else if (std::strcmp(suffix, "aranges") == 0) {
    *out = dwarf::section_type::aranges;
  } else if (std::strcmp(suffix, "frame") == 0) {
    *out = dwarf::section_type::frame;
  } else if (std::strcmp(suffix, "info") == 0) {
    *out = dwarf::section_type::info;
  } else if (std::strcmp(suffix, "line") == 0) {
    *out = dwarf::section_type::line;
  } else if (std::strcmp(suffix, "line_str") == 0) {
    *out = dwarf::section_type::line_str;
  } else if (std::strcmp(suffix, "loc") == 0) {
    *out = dwarf::section_type::loc;
  } else if (std::strcmp(suffix, "macinfo") == 0) {
    *out = dwarf::section_type::macinfo;
  } else if (std::strcmp(suffix, "pubnames") == 0) {
    *out = dwarf::section_type::pubnames;
  } else if (std::strcmp(suffix, "pubtypes") == 0) {
    *out = dwarf::section_type::pubtypes;
  } else if (std::strcmp(suffix, "ranges") == 0) {
    *out = dwarf::section_type::ranges;
  } else if (std::strcmp(suffix, "rnglists") == 0) {
    *out = dwarf::section_type::rnglists;
  } else if (std::strcmp(suffix, "str") == 0) {
    *out = dwarf::section_type::str;
  // DWARF 5 str_offsets - handle both full name and Mach-O truncated name (16-char limit)
  } else if (std::strcmp(suffix, "str_offsets") == 0 || std::strcmp(suffix, "str_offs") == 0) {
    *out = dwarf::section_type::str_offsets;
  } else if (std::strcmp(suffix, "types") == 0) {
    *out = dwarf::section_type::types;
  } else {
    return false;
  }

  return true;
}

std::map<dwarf::section_type, section_view> extract_elf_sections(LIEF::ELF::Binary* elf) {
  std::map<dwarf::section_type, section_view> result;

  for (const auto& section : elf->sections()) {
    dwarf::section_type type;
    if (section_name_to_type(section.name(), &type)) {
      auto content = section.content();
      if (!content.empty()) {
        result[type] = section_view{content.data(), content.size()};
      }
    }
  }

  return result;
}

std::map<dwarf::section_type, section_view> extract_macho_sections(LIEF::MachO::Binary* macho) {
  std::map<dwarf::section_type, section_view> result;

#if LIEF_LOADER_DEBUG
  std::cerr << "[lief_loader] Extracting Mach-O sections from binary" << std::endl;
#endif

  for (const auto& section : macho->sections()) {
    // Mach-O DWARF sections are in the __DWARF segment
    if (section.segment_name() != "__DWARF")
      continue;

#if LIEF_LOADER_DEBUG
    std::cerr << "[lief_loader] Found DWARF section: " << section.name()
              << " size=" << section.size() << std::endl;
#endif

    dwarf::section_type type;
    if (section_name_to_type(section.name(), &type)) {
      auto content = section.content();
      if (!content.empty()) {
        result[type] = section_view{content.data(), content.size()};
#if LIEF_LOADER_DEBUG
        std::cerr << "[lief_loader]   -> Mapped to type, content size=" << content.size() << std::endl;
#endif
      }
    }
  }

#if LIEF_LOADER_DEBUG
  std::cerr << "[lief_loader] Extracted " << result.size() << " DWARF sections" << std::endl;
#endif

  return result;
}

std::map<dwarf::section_type, section_view> extract_sections(LIEF::Binary* binary) {
  if (auto* elf = dynamic_cast<LIEF::ELF::Binary*>(binary)) {
    return extract_elf_sections(elf);
  }
#ifdef __APPLE__
  if (auto* macho = dynamic_cast<LIEF::MachO::Binary*>(binary)) {
    return extract_macho_sections(macho);
  }
#endif
  return {};
}

std::string dirname_of(const std::string& path) {
  auto pos = path.find_last_of('/');
  if (pos == std::string::npos)
    return ".";
  if (pos == 0)
    return "/";
  return path.substr(0, pos);
}

std::string basename_of(const std::string& path) {
  auto pos = path.find_last_of('/');
  if (pos == std::string::npos)
    return path;
  return path.substr(pos + 1);
}

std::string extract_build_id(LIEF::ELF::Binary* elf) {
  // Look for GNU build-id note
  for (const auto& note : elf->notes()) {
    if (note.type() == LIEF::ELF::Note::TYPE::GNU_BUILD_ID) {
      auto desc = note.description();
      if (desc.empty())
        continue;

      // Convert to hex string
      std::ostringstream ss;
      for (uint8_t byte : desc) {
        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(byte);
      }
      return ss.str();
    }
  }
  return std::string();
}

std::string extract_debuglink(LIEF::ELF::Binary* elf) {
  const auto* section = elf->get_section(".gnu_debuglink");
  if (!section)
    return std::string();

  auto content = section->content();
  if (content.empty())
    return std::string();

  // The section contains a null-terminated filename followed by padding and CRC
  return std::string(reinterpret_cast<const char*>(content.data()));
}

std::string find_debug_file(LIEF::ELF::Binary* elf, const std::string& binary_path) {
  std::vector<std::string> search_paths;
  std::string directory = dirname_of(binary_path);

  // 1. Try build-id based lookup first (most reliable)
  std::string build_id = extract_build_id(elf);
  if (build_id.length() >= 3) {
    std::string prefix = build_id.substr(0, 2);
    std::string suffix = build_id.substr(2);
    search_paths.push_back("/usr/lib/debug/.build-id/" + prefix + "/" + suffix + ".debug");
  }

  // 2. Try .gnu_debuglink based lookup
  std::string debuglink = extract_debuglink(elf);
  if (!debuglink.empty()) {
    // Standard search order per GDB documentation
    search_paths.push_back(directory + "/" + debuglink);
    search_paths.push_back(directory + "/.debug/" + debuglink);
    search_paths.push_back("/usr/lib/debug" + directory + "/" + debuglink);
  }

  // Search all paths
  for (const auto& path : search_paths) {
    if (file_exists(path)) {
      return path;
    }
  }

  return std::string();
}

std::string make_temp_dir() {
  std::string tmpl = "/tmp/coz-dsym-XXXXXX";
  std::vector<char> buffer(tmpl.begin(), tmpl.end());
  buffer.push_back('\0');
  char* created = mkdtemp(buffer.data());
  if (!created)
    return std::string();
  return std::string(created);
}

bool run_dsymutil(const std::string& binary_path, const std::string& bundle_path) {
  std::vector<const char*> args = {
    "dsymutil",
    binary_path.c_str(),
    "-o",
    bundle_path.c_str(),
    nullptr
  };

  // Filter out DYLD_* environment variables that could interfere with dsymutil
  std::vector<std::string> env_storage;
  std::vector<char*> envp;
  if (environ) {
    for (char** entry = environ; *entry != nullptr; ++entry) {
      if (std::strncmp(*entry, "DYLD_INSERT_LIBRARIES=", 22) == 0)
        continue;
      if (std::strncmp(*entry, "DYLD_FORCE_FLAT_NAMESPACE=", 26) == 0)
        continue;
      env_storage.emplace_back(*entry);
    }
  }
  for (auto& entry : env_storage) {
    envp.push_back(const_cast<char*>(entry.c_str()));
  }
  envp.push_back(nullptr);

  pid_t pid = 0;
  int rc = posix_spawnp(&pid, "dsymutil", nullptr, nullptr,
                        const_cast<char* const*>(args.data()),
                        envp.data());
  if (rc != 0) {
    return false;
  }

  int status = 0;
  if (waitpid(pid, &status, 0) == -1) {
    return false;
  }

  return WIFEXITED(status) && WEXITSTATUS(status) == 0;
}

std::string find_dsym_path(const std::string& binary_path) {
#ifdef __APPLE__
  std::string name = basename_of(binary_path);
  if (name.empty())
    return std::string();

  std::string bundle = binary_path + ".dSYM/Contents/Resources/DWARF/" + name;
  if (file_exists(bundle))
    return bundle;
#endif
  return std::string();
}

std::string generate_dsym(const std::string& binary_path) {
#ifdef __APPLE__
  static std::mutex mutex;
  static std::unordered_map<std::string, std::string> generated;

  // Check cache first
  {
    std::lock_guard<std::mutex> lock(mutex);
    auto it = generated.find(binary_path);
    if (it != generated.end())
      return it->second;
  }

  std::string temp_dir = make_temp_dir();
  if (temp_dir.empty())
    return std::string();

  std::string name = basename_of(binary_path);
  std::string bundle = temp_dir + "/" + name + ".dSYM";

  if (!run_dsymutil(binary_path, bundle))
    return std::string();

  std::string dwarf_path = bundle + "/Contents/Resources/DWARF/" + name;

  // Cache the result
  {
    std::lock_guard<std::mutex> lock(mutex);
    generated.emplace(binary_path, dwarf_path);
  }

  return dwarf_path;
#else
  (void)binary_path;
  return std::string();
#endif
}

bool is_static_executable(const std::string& path) {
#ifdef __APPLE__
  // macOS uses ASLR slide, always return false
  (void)path;
  return false;
#else
  auto binary = LIEF::Parser::parse(path);
  if (!binary)
    return false;

  auto* elf = dynamic_cast<LIEF::ELF::Binary*>(binary.get());
  if (!elf)
    return false;

  // ET_EXEC is a static executable (load at fixed address, typically 0)
  // ET_DYN is a shared library or PIE executable (use provided load address)
  return elf->header().file_type() == LIEF::ELF::Header::FILE_TYPE::EXEC;
#endif
}

std::shared_ptr<dwarf::loader> load(const std::string& path) {
#if LIEF_LOADER_DEBUG
  std::cerr << "[lief_loader] Loading: " << path << std::endl;
  std::cerr.flush();
#endif

  // Try loading the binary directly first
  std::unique_ptr<LIEF::Binary> binary;
#if LIEF_LOADER_DEBUG
  std::cerr << "[lief_loader] About to parse binary" << std::endl;
  std::cerr.flush();
#endif
  try {
#ifdef __APPLE__
    // On macOS, use Mach-O specific parser
    auto fat_binary = LIEF::MachO::Parser::parse(path);
    if (fat_binary && !fat_binary->empty()) {
      // Take the first (or only) binary from the fat archive
      binary = fat_binary->take(0);
    }
#else
    binary = LIEF::Parser::parse(path);
#endif
#if LIEF_LOADER_DEBUG
    std::cerr << "[lief_loader] Parse returned" << std::endl;
    std::cerr.flush();
#endif
  } catch (const std::exception& e) {
#if LIEF_LOADER_DEBUG
    std::cerr << "[lief_loader] Exception parsing binary: " << e.what() << std::endl;
#endif
    return nullptr;
  }

  if (!binary) {
#if LIEF_LOADER_DEBUG
    std::cerr << "[lief_loader] Failed to parse binary" << std::endl;
#endif
    return nullptr;
  }

#if LIEF_LOADER_DEBUG
  std::cerr << "[lief_loader] Binary parsed successfully, format="
            << static_cast<int>(binary->format()) << std::endl;
#endif

  std::map<dwarf::section_type, section_view> sections;
  try {
    sections = extract_sections(binary.get());
  } catch (const std::exception& e) {
#if LIEF_LOADER_DEBUG
    std::cerr << "[lief_loader] Exception extracting sections: " << e.what() << std::endl;
#endif
    return nullptr;
  }

#if LIEF_LOADER_DEBUG
  std::cerr << "[lief_loader] Extracted " << sections.size() << " sections" << std::endl;
  for (const auto& [type, view] : sections) {
    std::cerr << "[lief_loader]   section type " << static_cast<int>(type)
              << ": size=" << view.size << " data=" << (void*)view.data << std::endl;
  }
#endif

  // If we have debug info embedded, use it directly
  if (has_debug_info(sections)) {
#if LIEF_LOADER_DEBUG
    std::cerr << "[lief_loader] Found embedded debug info" << std::endl;
#endif
    return std::make_shared<lief_dwarf_loader>(std::move(binary), std::move(sections));
  }

#ifdef __APPLE__
  // === macOS: Try dSYM bundle ===
#if LIEF_LOADER_DEBUG
  std::cerr << "[lief_loader] No embedded debug info, trying dSYM" << std::endl;
#endif

  // Look for existing .dSYM bundle
  std::string dsym_path = find_dsym_path(path);
#if LIEF_LOADER_DEBUG
  std::cerr << "[lief_loader] find_dsym_path returned: " << dsym_path << std::endl;
#endif

  // Generate dSYM if needed
  if (dsym_path.empty()) {
    dsym_path = generate_dsym(path);
#if LIEF_LOADER_DEBUG
    std::cerr << "[lief_loader] generate_dsym returned: " << dsym_path << std::endl;
#endif
  }

  if (!dsym_path.empty()) {
    // LIEF::MachO::Parser handles fat binaries automatically
    auto dsym_binary = LIEF::Parser::parse(dsym_path);
    if (dsym_binary) {
#if LIEF_LOADER_DEBUG
      std::cerr << "[lief_loader] dSYM parsed successfully" << std::endl;
#endif
      auto dsym_sections = extract_sections(dsym_binary.get());
      if (has_debug_info(dsym_sections)) {
#if LIEF_LOADER_DEBUG
        std::cerr << "[lief_loader] Found debug info in dSYM" << std::endl;
#endif
        return std::make_shared<lief_dwarf_loader>(std::move(dsym_binary), std::move(dsym_sections));
      }
    }
  }

#else
  // === Linux: Try separate debug files ===

  auto* elf = dynamic_cast<LIEF::ELF::Binary*>(binary.get());
  if (elf) {
    std::string debug_path = find_debug_file(elf, path);
    if (!debug_path.empty()) {
      auto debug_binary = LIEF::Parser::parse(debug_path);
      if (debug_binary) {
        auto debug_sections = extract_sections(debug_binary.get());
        if (has_debug_info(debug_sections)) {
          return std::make_shared<lief_dwarf_loader>(std::move(debug_binary), std::move(debug_sections));
        }
      }
    }
  }
#endif

  // No debug info found
  return nullptr;
}

const void* load(dwarf::section_type section, size_t* size_out) override {
    auto it = _sections.find(section);
    if(it == _sections.end())
      return nullptr;
    if(size_out)
      *size_out = it->second.size;
    return it->second.data;
  }

bool assign_line_str(Enum* out, const char* suffix, std::true_type) {
  if(std::strcmp(suffix, "line_str") == 0) {
    *out = Enum::line_str;
    return true;
  }
  return false;
}

mapped_file map_file(const std::string& path) {
  mapped_file result;
  int fd = open(path.c_str(), O_RDONLY);
  if(fd < 0)
    return result;

  struct stat st {};
  if(fstat(fd, &st) != 0) {
    close(fd);
    return result;
  }

  if(st.st_size == 0) {
    close(fd);
    return result;
  }

  void* addr = mmap(nullptr, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
  close(fd);
  if(addr == MAP_FAILED)
    return result;

  size_t length = static_cast<size_t>(st.st_size);
  auto deleter = [length](void* ptr) {
    if(ptr && ptr != MAP_FAILED) {
      munmap(ptr, length);
    }
  };

  result.mapping.reset(addr, deleter);
  result.size = length;
  return result;
}

cpu_type_t preferred_cpu_type() {
  if(const mach_header* header = _dyld_get_image_header(0)) {
    return header->cputype;
  }
#if defined(__aarch64__) || defined(__arm64__)
  return CPU_TYPE_ARM64;
#elif defined(__x86_64__) || defined(__x86_64)
  return CPU_TYPE_X86_64;
#else
  return 0;
#endif
}

cpu_subtype_t preferred_cpu_subtype(cpu_type_t type) {
  if(const mach_header* header = _dyld_get_image_header(0)) {
    return header->cpusubtype;
  }
#if defined(__aarch64__) || defined(__arm64__)
  if(type == CPU_TYPE_ARM64)
    return CPU_SUBTYPE_ARM64_ALL;
#elif defined(__x86_64__) || defined(__x86_64)
  if(type == CPU_TYPE_X86_64)
    return CPU_SUBTYPE_X86_64_ALL;
#endif
  return CPU_SUBTYPE_MULTIPLE;
}

bool select_fat_slice(const fat_arch* archs,
                      uint32_t narch,
                      bool swap_bytes,
                      const uint8_t* base,
                      size_t file_size,
                      const mach_header_64** header_out,
                      size_t* remaining_out,
                      size_t* slice_offset_out) {
  cpu_type_t preferred = preferred_cpu_type();
  cpu_subtype_t preferred_subtype = preferred_cpu_subtype(preferred);
  const fat_arch* chosen = nullptr;

  for(uint32_t i = 0; i < narch; i++) {
    cpu_type_t cputype = swap_bytes ? OSSwapInt32(archs[i].cputype)
                                    : archs[i].cputype;
    cpu_subtype_t subtype = swap_bytes ? OSSwapInt32(archs[i].cpusubtype)
                                       : archs[i].cpusubtype;
    if(preferred == 0 || cputype == preferred) {
      // Mask out the flag bits (like CPU_SUBTYPE_LIB64) for comparison
      cpu_subtype_t subtype_masked = subtype & ~CPU_SUBTYPE_MASK;
      cpu_subtype_t preferred_masked = preferred_subtype & ~CPU_SUBTYPE_MASK;
      if(cputype == preferred &&
         (preferred_masked == CPU_SUBTYPE_MULTIPLE ||
          subtype_masked == preferred_masked)) {
        chosen = &archs[i];
        break;
      }
      if(!chosen) {
        chosen = &archs[i];
      }
    }
  }

  if(!chosen)
    return false;

  uint32_t offset = swap_bytes ? OSSwapInt32(chosen->offset) : chosen->offset;
  uint32_t size = swap_bytes ? OSSwapInt32(chosen->size) : chosen->size;

  if(offset + size > file_size || size < sizeof(mach_header_64))
    return false;

  const mach_header_64* header =
      reinterpret_cast<const mach_header_64*>(base + offset);
  if(header->magic != MH_MAGIC_64)
    return false;

  *header_out = header;
  *remaining_out = file_size - offset;
  if(slice_offset_out)
    *slice_offset_out = offset;
  return true;
}

bool select_fat_slice(const fat_arch_64* archs,
                      uint32_t narch,
                      bool swap_bytes,
                      const uint8_t* base,
                      size_t file_size,
                      const mach_header_64** header_out,
                      size_t* remaining_out,
                      size_t* slice_offset_out) {
  cpu_type_t preferred = preferred_cpu_type();
  cpu_subtype_t preferred_subtype = preferred_cpu_subtype(preferred);
  const fat_arch_64* chosen = nullptr;

  for(uint32_t i = 0; i < narch; i++) {
    cpu_type_t cputype = swap_bytes ? OSSwapInt32(archs[i].cputype)
                                    : archs[i].cputype;
    cpu_subtype_t subtype = swap_bytes ? OSSwapInt32(archs[i].cpusubtype)
                                       : archs[i].cpusubtype;
    if(preferred == 0 || cputype == preferred) {
      if(cputype == preferred &&
         (preferred_subtype == CPU_SUBTYPE_MULTIPLE ||
          subtype == preferred_subtype)) {
        chosen = &archs[i];
        break;
      }
      if(!chosen)
        chosen = &archs[i];
    }
  }

  if(!chosen)
    return false;

  uint64_t offset = swap_bytes ? OSSwapInt64(chosen->offset) : chosen->offset;
  uint64_t size = swap_bytes ? OSSwapInt64(chosen->size) : chosen->size;

  if(offset + size > file_size || size < sizeof(mach_header_64))
    return false;

  const mach_header_64* header =
      reinterpret_cast<const mach_header_64*>(base + offset);
  if(header->magic != MH_MAGIC_64)
    return false;

  *header_out = header;
  *remaining_out = file_size - offset;
  if(slice_offset_out)
    *slice_offset_out = static_cast<size_t>(offset);
  return true;
}

bool find_mach_header(const uint8_t* base,
                      size_t size,
                      const mach_header_64** header_out,
                      size_t* remaining_out,
                      size_t* slice_offset_out) {
  if(size < sizeof(uint32_t))
    return false;

  uint32_t magic = *reinterpret_cast<const uint32_t*>(base);
  switch(magic) {
    case MH_MAGIC_64:
      if(size < sizeof(mach_header_64))
        return false;
      *header_out = reinterpret_cast<const mach_header_64*>(base);
      *remaining_out = size;
      if(slice_offset_out)
        *slice_offset_out = 0;
      return true;
    case FAT_MAGIC:
    case FAT_CIGAM: {
      if(size < sizeof(fat_header))
        return false;
      const fat_header* header = reinterpret_cast<const fat_header*>(base);
      bool swap_bytes = (magic == FAT_CIGAM);
      uint32_t narch = swap_bytes ? OSSwapInt32(header->nfat_arch)
                                  : header->nfat_arch;
      if(size < sizeof(fat_header) + narch * sizeof(fat_arch))
        return false;
      const fat_arch* archs = reinterpret_cast<const fat_arch*>(header + 1);
      return select_fat_slice(archs,
                              narch,
                              swap_bytes,
                              base,
                              size,
                              header_out,
                              remaining_out,
                              slice_offset_out);
    }
    case FAT_MAGIC_64:
    case FAT_CIGAM_64: {
      if(size < sizeof(fat_header))
        return false;
      const fat_header* header = reinterpret_cast<const fat_header*>(base);
      bool swap_bytes = (magic == FAT_CIGAM_64);
      uint32_t narch = swap_bytes ? OSSwapInt32(header->nfat_arch)
                                  : header->nfat_arch;
      if(size < sizeof(fat_header) + narch * sizeof(fat_arch_64))
        return false;
      const fat_arch_64* archs =
          reinterpret_cast<const fat_arch_64*>(header + 1);
      return select_fat_slice(archs,
                              narch,
                              swap_bytes,
                              base,
                              size,
                              header_out,
                              remaining_out,
                              slice_offset_out);
    }
    default:
      return false;
  }
}

bool get_section_type(const char* sectname, dwarf::section_type* out) {
  if(std::strncmp(sectname, "__debug_", 8) != 0)
    return false;

  const char* suffix = sectname + 8;
  if(std::strcmp(suffix, "abbrev") == 0) *out = dwarf::section_type::abbrev;
  else if(std::strcmp(suffix, "aranges") == 0) *out = dwarf::section_type::aranges;
  else if(std::strcmp(suffix, "frame") == 0) *out = dwarf::section_type::frame;
  else if(std::strcmp(suffix, "info") == 0) *out = dwarf::section_type::info;
  else if(std::strcmp(suffix, "line") == 0) *out = dwarf::section_type::line;
  else if(std::strcmp(suffix, "loc") == 0) *out = dwarf::section_type::loc;
  else if(std::strcmp(suffix, "macinfo") == 0) *out = dwarf::section_type::macinfo;
  else if(std::strcmp(suffix, "pubnames") == 0) *out = dwarf::section_type::pubnames;
  else if(std::strcmp(suffix, "pubtypes") == 0) *out = dwarf::section_type::pubtypes;
  else if(std::strcmp(suffix, "ranges") == 0) *out = dwarf::section_type::ranges;
  else if(std::strcmp(suffix, "str") == 0) *out = dwarf::section_type::str;
  else if(std::strcmp(suffix, "types") == 0) *out = dwarf::section_type::types;
  else if(assign_line_str(out,
                          suffix,
                          std::integral_constant<bool, has_line_str<dwarf::section_type>::value>()))
    return true;
  else
    return false;

  return true;
}

bool collect_dwarf_sections(const uint8_t* base,
                            size_t size,
                            std::map<dwarf::section_type, section_view>& sections) {
  const mach_header_64* header = nullptr;
  size_t remaining = 0;
  size_t slice_offset = 0;
  if(!find_mach_header(base, size, &header, &remaining, &slice_offset))
    return false;

  const uint8_t* command_ptr =
      reinterpret_cast<const uint8_t*>(header) + sizeof(mach_header_64);
  if(command_ptr < base || command_ptr > base + size)
    return false;

  for(uint32_t i = 0; i < header->ncmds; i++) {
    if(command_ptr + sizeof(load_command) > base + size)
      return false;
    const load_command* cmd =
        reinterpret_cast<const load_command*>(command_ptr);
    if(cmd->cmdsize == 0 || command_ptr + cmd->cmdsize > base + size)
      return false;

    if(cmd->cmd == LC_SEGMENT_64) {
      const segment_command_64* seg =
          reinterpret_cast<const segment_command_64*>(command_ptr);
      const section_64* secs =
          reinterpret_cast<const section_64*>(seg + 1);
      for(uint32_t s = 0; s < seg->nsects; s++) {
        const section_64& sec = secs[s];
        if(std::strncmp(sec.segname, "__DWARF", sizeof(sec.segname)) != 0)
          continue;
        if(sec.offset + sec.size > size)
          continue;
        dwarf::section_type type;
        char section_name[sizeof(sec.sectname) + 1];
        memcpy(section_name, sec.sectname, sizeof(sec.sectname));
        section_name[sizeof(sec.sectname)] = '\0';
        if(get_section_type(section_name, &type)) {
          const void* data = base + slice_offset + sec.offset;
          sections[type] = section_view{data, static_cast<size_t>(sec.size)};
        }
      }
    }

    command_ptr += cmd->cmdsize;
  }

  return !sections.empty();
}

std::shared_ptr<dwarf::loader> load_dwarf_from_file(const std::string& path) {
  mapped_file file = map_file(path);
  if(!file.mapping || file.size == 0)
    return nullptr;

  std::map<dwarf::section_type, section_view> sections;
  if(!collect_dwarf_sections(static_cast<const uint8_t*>(file.mapping.get()),
                             file.size,
                             sections)) {
    return nullptr;
  }

  return std::make_shared<macho_dwarf_loader>(file.mapping, std::move(sections));
}

std::string find_dsym_bundle(const std::string& binary_path) {
  auto slash = binary_path.find_last_of('/');
  std::string name = (slash == std::string::npos)
                       ? binary_path
                       : binary_path.substr(slash + 1);
  if(name.empty())
    return std::string();

  std::string bundle =
      binary_path + ".dSYM/Contents/Resources/DWARF/" + name;
  struct stat st {};
  if(stat(bundle.c_str(), &st) == 0 && S_ISREG(st.st_mode))
    return bundle;
  return std::string();
}

std::string basename_for(const std::string& path) {
  auto slash = path.find_last_of('/');
  if(slash == std::string::npos)
    return path;
  return path.substr(slash + 1);
}

std::string make_temp_dir() {
  std::string tmpl = "/tmp/coz-dsym-XXXXXX";
  std::vector<char> buffer(tmpl.begin(), tmpl.end());
  buffer.push_back('\0');
  char* created = mkdtemp(buffer.data());
  if(!created)
    return std::string();
  return std::string(created);
}

bool run_dsymutil(const std::string& binary_path, const std::string& bundle_path) {
  std::array<char*, 5> args {
    const_cast<char*>("dsymutil"),
    const_cast<char*>(binary_path.c_str()),
    const_cast<char*>("-o"),
    const_cast<char*>(bundle_path.c_str()),
    nullptr
  };

  std::vector<std::string> env_storage;
  std::vector<char*> envp;
  if(environ) {
    for(char** entry = environ; *entry != nullptr; ++entry) {
      if(std::strncmp(*entry, "DYLD_INSERT_LIBRARIES=", 22) == 0)
        continue;
      if(std::strncmp(*entry, "DYLD_FORCE_FLAT_NAMESPACE=", 26) == 0)
        continue;
      env_storage.emplace_back(*entry);
    }
  }
  for(auto& entry : env_storage) {
    envp.push_back(const_cast<char*>(entry.c_str()));
  }
  envp.push_back(nullptr);

  pid_t pid = 0;
  int rc = posix_spawnp(&pid, "dsymutil", nullptr, nullptr, args.data(), envp.data());
  if(rc != 0) {
    fprintf(stderr,
            "dsymutil spawn failed for %s: %s\n",
            binary_path.c_str(),
            strerror(rc));
    return false;
  }

  int status = 0;
  if(waitpid(pid, &status, 0) == -1) {
    fprintf(stderr, "waitpid failed for dsymutil (%s)\n", binary_path.c_str());
    return false;
  }
  if(!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
    fprintf(stderr,
            "dsymutil exited with status %d for %s\n",
            status,
            binary_path.c_str());
    return false;
  }
  return true;
}

std::string generate_dsym_bundle(const std::string& binary_path) {
  static std::mutex mutex;
  static std::unordered_map<std::string, std::string> generated;

  {
    std::lock_guard<std::mutex> lock(mutex);
    auto it = generated.find(binary_path);
    if(it != generated.end())
      return it->second;
  }

  std::string temp_dir = make_temp_dir();
  if(temp_dir.empty())
    return std::string();

  std::string base = basename_for(binary_path);
  std::string bundle = temp_dir + "/" + base + ".dSYM";
  if(!run_dsymutil(binary_path, bundle))
    return std::string();

  std::string dwarf = bundle + "/Contents/Resources/DWARF/" + base;
  {
    std::lock_guard<std::mutex> lock(mutex);
    generated.emplace(binary_path, dwarf);
  }
  return dwarf;
}

std::shared_ptr<dwarf::loader> load_debug_info(const std::string& binary_path) {
  std::string dsym = find_dsym_bundle(binary_path);
  if(dsym.empty()) {
    dsym = generate_dsym_bundle(binary_path);
  }
  if(!dsym.empty()) {
    auto loader = load_dwarf_from_file(dsym);
    if(loader) {
      return loader;
    }
  }

  return load_dwarf_from_file(binary_path);
}

const char* get_last_shell_error(void){

    if(last_shell_error[0] != '\0')
        return last_shell_error;

    return last_shell_line[0] != '\0' ? last_shell_line : NULL;
}

void record_shell_error_line(const char *line){

    while (*line == ' ')
        line++;

    if(*line == '\0')
        return;

    // Not every failure is tagged: the root check, hostapd and pkexec all
    // print plain text, so keep the last real line as a fallback
    if(strncmp(line, "Doing cleanup", 13) != 0 && strcmp(line, "done") != 0)
        snprintf(last_shell_line, BUFSIZE, "%s", line);

    // The first ERROR: line names the actual cause, later ones are fallout
    if(last_shell_error[0] != '\0')
        return;

    if(strncmp(line, "ERROR:", 6) == 0){
        const char *msg = line + 6;
        while (*msg == ' ')
            msg++;
        snprintf(last_shell_error, BUFSIZE, "%s", msg);
    }
    else if(strstr(line, "Not authorized") != NULL || strstr(line, "dismissed") != NULL){
        snprintf(last_shell_error, BUFSIZE, "Authorization failed or was cancelled");
    }
}

const char* get_default_route_interface(){

    static char iface[64];
    FILE *fp;

    iface[0] = '\0';

    if ((fp = popen("ip -o route show default 2>/dev/null | awk '{print $5; exit}'", "r")) == NULL) {
        printf("Error opening pipe!\n");
        return NULL;
    }

    if (fgets(iface, sizeof(iface), fp) != NULL)
        iface[strcspn(iface, "\n")] = '\0';

    pclose(fp);

    return iface[0] != '\0' ? iface : NULL;
}

