}

static int ABI_ATTR
sum_bytes (big_struct s0, big_struct s1, big_struct s2, big_struct s3,
	   big_struct s4, big_struct s5, big_struct s6, big_struct s7,
	   big_struct s8, big_struct s9, big_struct s10, big_struct s11,
	   big_struct s12, big_struct s13, big_struct s14, big_struct s15)
{
  big_struct *all[NARGS];
  int i, j, sum = 0;

  all[0] = &s0;   all[1] = &s1;   all[2] = &s2;   all[3] = &s3;
  all[4] = &s4;   all[5] = &s5;   all[6] = &s6;   all[7] = &s7;
  all[8] = &s8;   all[9] = &s9;   all[10] = &s10; all[11] = &s11;
  all[12] = &s12; all[13] = &s13; all[14] = &s14; all[15] = &s15;

  for (i = 0; i < NARGS; i++)
    for (j = 0; j < SSIZE; j++)
      sum += all[i]->b[j];

  return sum;
}

int main (void)
{
  ffi_cif cif;
  ffi_type *args[NARGS];
  void *values[NARGS];
  ffi_type bs_type;
  ffi_type *bs_elements[SSIZE + 1];
  big_struct in[NARGS];
  ffi_arg result = 0;
  int i, j, expected = 0;

  bs_type.size = 0;
  bs_type.alignment = 0;
  bs_type.type = FFI_TYPE_STRUCT;
  for (i = 0; i < SSIZE; i++)
    bs_elements[i] = &ffi_type_uchar;
  bs_elements[SSIZE] = NULL;
  bs_type.elements = bs_elements;

  /* Fill struct i with the distinct byte value (i + 1) so any pointer
     mix-up between arguments changes the total.  */
  for (i = 0; i < NARGS; i++)
    {
      for (j = 0; j < SSIZE; j++)
	{
	  in[i].b[j] = (unsigned char) (i + 1);
	  expected += (i + 1);
	}
      args[i] = &bs_type;
      values[i] = &in[i];
    }

  CHECK(ffi_prep_cif(&cif, ABI_NUM, NARGS, &ffi_type_sint, args) == FFI_OK);

  ffi_call(&cif, FFI_FN(sum_bytes), &result, values);

  CHECK((int) result == expected);

  exit(0);
}

static uint64_t gp6(uint64_t a, uint64_t b, uint64_t c,
		    uint64_t d, uint64_t e, uint64_t f)
{
  return a + b * 2 + c * 3 + d * 4 + e * 5 + f * 6;
}

int main (void)
{
  ffi_cif cif;
  ffi_type *args[6];
  void *values[6];
  ffi_call_plan *plan;
  uint64_t a[6], r_call, r_plan;
  int i, k;

  /* Pure GP64: every argument is one 64-bit integer, so build_plan
     selects the ffi_plan_gpN direct thunk.  Reuse the plan across many
     invocations with changing values.  */
  for (i = 0; i < 6; i++)
    args[i] = &ffi_type_uint64;
  CHECK(ffi_prep_cif(&cif, FFI_DEFAULT_ABI, 6, &ffi_type_uint64, args)
	== FFI_OK);
  plan = ffi_call_plan_alloc(&cif);
  CHECK(plan != NULL);

  for (k = 0; k < 100; k++)
    {
      for (i = 0; i < 6; i++)
	{
	  a[i] = (uint64_t) (k * 7 + i + 1);
	  values[i] = &a[i];
	}
      ffi_call(&cif, FFI_FN(gp6), &r_call, values);
      ffi_call_plan_invoke(plan, FFI_FN(gp6), &r_plan, values);
      CHECK(r_call == r_plan);
      CHECK(r_plan == gp6(a[0], a[1], a[2], a[3], a[4], a[5]));
    }
  ffi_call_plan_free(plan);

  /* Pointer argument and pointer return. */
  {
    ffi_cif cifp;
    ffi_type *pargs[1];
    void *pvalues[1];
    void *in, *rc, *rp;
    ffi_call_plan *planp;

    pargs[0] = &ffi_type_pointer;
    CHECK(ffi_prep_cif(&cifp, FFI_DEFAULT_ABI, 1, &ffi_type_pointer, pargs)
	  == FFI_OK);
    planp = ffi_call_plan_alloc(&cifp);
    CHECK(planp != NULL);

    in = &cifp;
    pvalues[0] = &in;
    ffi_call(&cifp, FFI_FN(ptr_ident), &rc, pvalues);
    ffi_call_plan_invoke(planp, FFI_FN(ptr_ident), &rp, pvalues);
    CHECK(rc == in);
    CHECK(rp == in);
    ffi_call_plan_free(planp);
  }

  /* No fast path: a struct-by-value argument.  build_plan returns NULL for
     the fast plan, but ffi_call_plan_alloc must still hand back a valid plan
     whose invoke falls back to ffi_call and produces the same result.  */
  {
    ffi_cif cifs;
    ffi_type *sargs[1];
    ffi_type stype;
    ffi_type *selements[3];
    void *svalues[1];
    struct small_pair s;
    long rc, rp;
    ffi_call_plan *plans;

    selements[0] = &ffi_type_slong;
    selements[1] = &ffi_type_slong;
    selements[2] = NULL;
    stype.size = stype.alignment = 0;
    stype.type = FFI_TYPE_STRUCT;
    stype.elements = selements;

    sargs[0] = &stype;
    CHECK(ffi_prep_cif(&cifs, FFI_DEFAULT_ABI, 1, &ffi_type_slong, sargs)
	  == FFI_OK);
    plans = ffi_call_plan_alloc(&cifs);
    CHECK(plans != NULL);

    s.x = 123;
    s.y = 45;
    svalues[0] = &s;
    ffi_call(&cifs, FFI_FN(ssum), &rc, svalues);
    ffi_call_plan_invoke(plans, FFI_FN(ssum), &rp, svalues);
    CHECK(rc == rp);
    CHECK(rp == ssum(s));
    ffi_call_plan_free(plans);
  }

  /* Freeing NULL is documented to be harmless. */
  ffi_call_plan_free(NULL);

  exit(0);
}

static double mixed(int a, double b, long c, float d,
		    long long e, double f)
{
  return (double) a + b + (double) c + (double) d + (double) e + f;
}

int main (void)
{
  /* Mixed GP + SSE arguments, double return: exercises the fast local-image
     path with both integer and SSE moves and the ssecount (al) setup.  */
  {
    ffi_cif cif;
    ffi_type *args[6];
    void *values[6];
    ffi_call_plan *plan;
    int a = 3;
    double b = 1.5, f = -2.25, rc, rp;
    long c = 7;
    float d = 0.5f;
    long long e = -11;

    args[0] = &ffi_type_sint;
    args[1] = &ffi_type_double;
    args[2] = &ffi_type_slong;
    args[3] = &ffi_type_float;
    args[4] = &ffi_type_sint64;
    args[5] = &ffi_type_double;
    values[0] = &a; values[1] = &b; values[2] = &c;
    values[3] = &d; values[4] = &e; values[5] = &f;

    CHECK(ffi_prep_cif(&cif, FFI_DEFAULT_ABI, 6, &ffi_type_double, args)
	  == FFI_OK);
    plan = ffi_call_plan_alloc(&cif);
    CHECK(plan != NULL);

    ffi_call(&cif, FFI_FN(mixed), &rc, values);
    ffi_call_plan_invoke(plan, FFI_FN(mixed), &rp, values);
    CHECK_DOUBLE_EQ(rc, rp);
    CHECK_DOUBLE_EQ(rp, mixed(a, b, c, d, e, f));
    ffi_call_plan_free(plan);
  }

  /* Float arguments and float return. */
  {
    ffi_cif cif;
    ffi_type *args[2];
    void *values[2];
    ffi_call_plan *plan;
    float a = 1.25f, b = 2.5f, rc, rp;

    args[0] = &ffi_type_float;
    args[1] = &ffi_type_float;
    values[0] = &a;
    values[1] = &b;
    CHECK(ffi_prep_cif(&cif, FFI_DEFAULT_ABI, 2, &ffi_type_float, args)
	  == FFI_OK);
    plan = ffi_call_plan_alloc(&cif);
    CHECK(plan != NULL);

    ffi_call(&cif, FFI_FN(faddf), &rc, values);
    ffi_call_plan_invoke(plan, FFI_FN(faddf), &rp, values);
    CHECK_FLOAT_EQ(rc, rp);
    CHECK_FLOAT_EQ(rp, faddf(a, b));
    ffi_call_plan_free(plan);
  }

  /* Signed narrow argument and signed narrow return: the plan sign-extends
     the argument and widens the return to ffi_arg just as ffi_call does. */
  {
    ffi_cif cif;
    ffi_type *args[1];
    void *values[1];
    ffi_call_plan *plan;
    signed char in;
    ffi_arg rc, rp;
    int v;

    args[0] = &ffi_type_schar;
    CHECK(ffi_prep_cif(&cif, FFI_DEFAULT_ABI, 1, &ffi_type_schar, args)
	  == FFI_OK);
    plan = ffi_call_plan_alloc(&cif);
    CHECK(plan != NULL);

    for (v = -128; v < 128; v++)
      {
	in = (signed char) v;
	values[0] = &in;
	ffi_call(&cif, FFI_FN(ret_sc), &rc, values);
	ffi_call_plan_invoke(plan, FFI_FN(ret_sc), &rp, values);
	CHECK(rc == rp);
	CHECK((signed char) rp == ret_sc(in));
      }
    ffi_call_plan_free(plan);
  }

  /* Unsigned narrow argument and unsigned narrow return. */
  {
    ffi_cif cif;
    ffi_type *args[1];
    void *values[1];
    ffi_call_plan *plan;
    unsigned char in;
    ffi_arg rc, rp;
    int v;

    args[0] = &ffi_type_uchar;
    CHECK(ffi_prep_cif(&cif, FFI_DEFAULT_ABI, 1, &ffi_type_uchar, args)
	  == FFI_OK);
    plan = ffi_call_plan_alloc(&cif);
    CHECK(plan != NULL);

    for (v = 0; v < 256; v++)
      {
	in = (unsigned char) v;
	values[0] = &in;
	ffi_call(&cif, FFI_FN(ret_uc), &rc, values);
	ffi_call_plan_invoke(plan, FFI_FN(ret_uc), &rp, values);
	CHECK(rc == rp);
	CHECK((unsigned char) rp == ret_uc(in));
      }
    ffi_call_plan_free(plan);
  }

  exit(0);
}

static long long gp10(long long a1, long long a2, long long a3, long long a4,
		      long long a5, long long a6, long long a7, long long a8,
		      long long a9, long long a10)
{
  return a1 + a2 * 2 + a3 * 3 + a4 * 4 + a5 * 5
       + a6 * 6 + a7 * 7 + a8 * 8 + a9 * 9 + a10 * 10;
}

static double sse12(double a1, double a2, double a3, double a4,
		    double a5, double a6, double a7, double a8,
		    double a9, double a10, double a11, double a12)
{
  return a1 + a2 * 2 + a3 * 3 + a4 * 4 + a5 * 5 + a6 * 6
       + a7 * 7 + a8 * 8 + a9 * 9 + a10 * 10 + a11 * 11 + a12 * 12;
}

static double mix16(long i1, long i2, long i3, long i4,
		    long i5, long i6, long i7, long i8,
		    double d1, double d2, double d3, double d4,
		    double d5, double d6, double d7, double d8)
{
  double s = 0.0;
  s += (double) (i1 + i2 + i3 + i4 + i5 + i6 + i7 + i8);
  s += d1 + d2 + d3 + d4 + d5 + d6 + d7 + d8;
  return s;
}

int main (void)
{
  /* GP spill. */
  {
    ffi_cif cif;
    ffi_type *args[10];
    void *values[10];
    long long a[10];
    long long rc, rp;
    ffi_call_plan *plan;
    int i;

    for (i = 0; i < 10; i++)
      {
	args[i] = &ffi_type_sint64;
	a[i] = (long long) (i + 1) * 100 - 3;
	values[i] = &a[i];
      }
    CHECK(ffi_prep_cif(&cif, FFI_DEFAULT_ABI, 10, &ffi_type_sint64, args)
	  == FFI_OK);
    plan = ffi_call_plan_alloc(&cif);
    CHECK(plan != NULL);

    ffi_call(&cif, FFI_FN(gp10), &rc, values);
    ffi_call_plan_invoke(plan, FFI_FN(gp10), &rp, values);
    CHECK(rc == rp);
    CHECK(rp == gp10(a[0], a[1], a[2], a[3], a[4],
		     a[5], a[6], a[7], a[8], a[9]));
    ffi_call_plan_free(plan);
  }

  /* SSE spill. */
  {
    ffi_cif cif;
    ffi_type *args[12];
    void *values[12];
    double a[12];
    double rc, rp;
    ffi_call_plan *plan;
    int i;

    for (i = 0; i < 12; i++)
      {
	args[i] = &ffi_type_double;
	a[i] = (double) i + 0.25;
	values[i] = &a[i];
      }
    CHECK(ffi_prep_cif(&cif, FFI_DEFAULT_ABI, 12, &ffi_type_double, args)
	  == FFI_OK);
    plan = ffi_call_plan_alloc(&cif);
    CHECK(plan != NULL);

    ffi_call(&cif, FFI_FN(sse12), &rc, values);
    ffi_call_plan_invoke(plan, FFI_FN(sse12), &rp, values);
    CHECK_DOUBLE_EQ(rc, rp);
    CHECK_DOUBLE_EQ(rp, sse12(a[0], a[1], a[2], a[3], a[4], a[5],
			      a[6], a[7], a[8], a[9], a[10], a[11]));
    ffi_call_plan_free(plan);
  }

  /* Both classes spill. */
  {
    ffi_cif cif;
    ffi_type *args[16];
    void *values[16];
    long iv[8];
    double dv[8];
    double rc, rp;
    ffi_call_plan *plan;
    int i;

    for (i = 0; i < 8; i++)
      {
	args[i] = &ffi_type_slong;
	iv[i] = (long) (i + 1);
	values[i] = &iv[i];
      }
    for (i = 0; i < 8; i++)
      {
	args[8 + i] = &ffi_type_double;
	dv[i] = (double) (i + 1) * 0.5;
	values[8 + i] = &dv[i];
      }
    CHECK(ffi_prep_cif(&cif, FFI_DEFAULT_ABI, 16, &ffi_type_double, args)
	  == FFI_OK);
    plan = ffi_call_plan_alloc(&cif);
    CHECK(plan != NULL);

    ffi_call(&cif, FFI_FN(mix16), &rc, values);
    ffi_call_plan_invoke(plan, FFI_FN(mix16), &rp, values);
    CHECK_DOUBLE_EQ(rc, rp);
    CHECK_DOUBLE_EQ(rp, mix16(iv[0], iv[1], iv[2], iv[3],
			      iv[4], iv[5], iv[6], iv[7],
			      dv[0], dv[1], dv[2], dv[3],
			      dv[4], dv[5], dv[6], dv[7]));
    ffi_call_plan_free(plan);
  }

  exit(0);
}

static struct big3 make_big3(double a, double b, double c)
{
  struct big3 r;
  call_count++;
  r.a = a + 1.0;
  r.b = b + 2.0;
  r.c = c + 3.0;
  return r;
}

static struct pair2 make_pair2(long x, long y)
{
  struct pair2 r;
  r.x = x * 2;
  r.y = y * 3;
  return r;
}

int main (void)
{
  ffi_type *big3_elements[4];
  ffi_type big3_t;
  ffi_type *pair2_elements[3];
  ffi_type pair2_t;

  big3_elements[0] = &ffi_type_double;
  big3_elements[1] = &ffi_type_double;
  big3_elements[2] = &ffi_type_double;
  big3_elements[3] = NULL;
  big3_t.size = big3_t.alignment = 0;
  big3_t.type = FFI_TYPE_STRUCT;
  big3_t.elements = big3_elements;

  pair2_elements[0] = &ffi_type_slong;
  pair2_elements[1] = &ffi_type_slong;
  pair2_elements[2] = NULL;
  pair2_t.size = pair2_t.alignment = 0;
  pair2_t.type = FFI_TYPE_STRUCT;
  pair2_t.elements = pair2_elements;

  /* In-memory struct return with scalar arguments. */
  {
    ffi_cif cif;
    ffi_type *args[3];
    void *values[3];
    ffi_call_plan *plan;
    double a = 10.0, b = 20.0, c = 30.0;
    struct big3 rc, rp;
    int before;

    args[0] = &ffi_type_double;
    args[1] = &ffi_type_double;
    args[2] = &ffi_type_double;
    values[0] = &a;
    values[1] = &b;
    values[2] = &c;
    CHECK(ffi_prep_cif(&cif, FFI_DEFAULT_ABI, 3, &big3_t, args) == FFI_OK);
    plan = ffi_call_plan_alloc(&cif);
    CHECK(plan != NULL);

    ffi_call(&cif, FFI_FN(make_big3), &rc, values);
    ffi_call_plan_invoke(plan, FFI_FN(make_big3), &rp, values);
    CHECK_DOUBLE_EQ(rc.a, rp.a);
    CHECK_DOUBLE_EQ(rc.b, rp.b);
    CHECK_DOUBLE_EQ(rc.c, rp.c);
    CHECK_DOUBLE_EQ(rp.a, a + 1.0);
    CHECK_DOUBLE_EQ(rp.b, b + 2.0);
    CHECK_DOUBLE_EQ(rp.c, c + 3.0);

    /* A NULL rvalue for an in-memory struct return must not crash: libffi
       supplies scratch space and discards the result, but the callee still
       runs.  Confirm the call actually happened. */
    before = call_count;
    ffi_call_plan_invoke(plan, FFI_FN(make_big3), NULL, values);
    CHECK(call_count == before + 1);

    ffi_call_plan_free(plan);
  }

  /* Large struct argument: no fast path, falls back to ffi_call. */
  {
    ffi_cif cif;
    ffi_type *args[1];
    void *values[1];
    ffi_call_plan *plan;
    struct big3 s;
    double rc, rp;

    s.a = 1.5;
    s.b = 2.5;
    s.c = 3.5;
    args[0] = &big3_t;
    values[0] = &s;
    CHECK(ffi_prep_cif(&cif, FFI_DEFAULT_ABI, 1, &ffi_type_double, args)
	  == FFI_OK);
    plan = ffi_call_plan_alloc(&cif);
    CHECK(plan != NULL);

    ffi_call(&cif, FFI_FN(sum_big3), &rc, values);
    ffi_call_plan_invoke(plan, FFI_FN(sum_big3), &rp, values);
    CHECK_DOUBLE_EQ(rc, rp);
    CHECK_DOUBLE_EQ(rp, sum_big3(s));
    ffi_call_plan_free(plan);
  }

  /* Register-pair struct return. */
  {
    ffi_cif cif;
    ffi_type *args[2];
    void *values[2];
    ffi_call_plan *plan;
    long x = 7, y = 11;
    struct pair2 rc, rp;

    args[0] = &ffi_type_slong;
    args[1] = &ffi_type_slong;
    values[0] = &x;
    values[1] = &y;
    CHECK(ffi_prep_cif(&cif, FFI_DEFAULT_ABI, 2, &pair2_t, args) == FFI_OK);
    plan = ffi_call_plan_alloc(&cif);
    CHECK(plan != NULL);

    ffi_call(&cif, FFI_FN(make_pair2), &rc, values);
    ffi_call_plan_invoke(plan, FFI_FN(make_pair2), &rp, values);
    CHECK(rc.x == rp.x);
    CHECK(rc.y == rp.y);
    CHECK(rp.x == x * 2);
    CHECK(rp.y == y * 3);
    ffi_call_plan_free(plan);
  }

  exit(0);
}

static double vsum(int n, ...)
{
  va_list ap;
  double s = 0.0;
  int i;

  va_start(ap, n);
  for (i = 0; i < n; i++)
    s += va_arg(ap, double);
  va_end(ap);
  return s;
}

static void
run (int nvar)
{
  ffi_cif cif;
  ffi_type *args[1 + 8];
  void *values[1 + 8];
  double d[8];
  int n = nvar;
  double rc, rp, expect;
  ffi_call_plan *plan;
  int i;

  CHECK(nvar <= 8);

  args[0] = &ffi_type_sint;
  values[0] = &n;
  expect = 0.0;
  for (i = 0; i < nvar; i++)
    {
      d[i] = (double) (i + 1) * 1.5;
      args[1 + i] = &ffi_type_double;
      values[1 + i] = &d[i];
      expect += d[i];
    }

  CHECK(ffi_prep_cif_var(&cif, FFI_DEFAULT_ABI, 1, 1 + nvar,
			 &ffi_type_double, args) == FFI_OK);
  plan = ffi_call_plan_alloc(&cif);
  CHECK(plan != NULL);

  ffi_call(&cif, FFI_FN(vsum), &rc, values);
  ffi_call_plan_invoke(plan, FFI_FN(vsum), &rp, values);
  CHECK_DOUBLE_EQ(rc, rp);
  CHECK_DOUBLE_EQ(rp, expect);

  ffi_call_plan_free(plan);
}

int main (void)
{
  run (0);
  run (1);
  run (3);
  run (5);
  run (8);
  exit(0);
}

static int ABI_ATTR
sum_big (big_struct s)
{
  int i, sum = 0;
  for (i = 0; i < 8; i++)
    sum += s.v[i];
  return sum;
}

int main (void)
{
  ffi_cif cif;
  ffi_type *args[1];
  void *values[1];
  ffi_type bs_type;
  ffi_type *bs_elements[9];
  big_struct in;
  ffi_arg result = 0;
  int i, expected = 0;

  bs_type.size = 0;
  bs_type.alignment = 0;
  bs_type.type = FFI_TYPE_STRUCT;
  for (i = 0; i < 8; i++)
    bs_elements[i] = &ffi_type_sint;
  bs_elements[8] = NULL;
  bs_type.elements = bs_elements;

  for (i = 0; i < 8; i++)
    {
      in.v[i] = 0x1111 * (i + 1);
      expected += in.v[i];
    }

  args[0] = &bs_type;
  values[0] = &in;

  CHECK(ffi_prep_cif(&cif, ABI_NUM, 1, &ffi_type_sint, args) == FFI_OK);

  ffi_call(&cif, FFI_FN(sum_big), &result, values);

  CHECK((int) result == expected);

  exit(0);
}

static small_struct ABI_ATTR
many_small (small_struct s0, small_struct s1, small_struct s2, small_struct s3,
	    small_struct s4, small_struct s5, small_struct s6, small_struct s7,
	    small_struct s8, small_struct s9, small_struct s10, small_struct s11,
	    small_struct s12, small_struct s13, small_struct s14, small_struct s15)
{
  small_struct r;
  r.a = s0.a + s1.a + s2.a + s3.a + s4.a + s5.a + s6.a + s7.a
      + s8.a + s9.a + s10.a + s11.a + s12.a + s13.a + s14.a + s15.a;
  r.b = s0.b + s1.b + s2.b + s3.b + s4.b + s5.b + s6.b + s7.b
      + s8.b + s9.b + s10.b + s11.b + s12.b + s13.b + s14.b + s15.b;
  return r;
}

int main (void)
{
  ffi_cif cif;
  ffi_type *args[NARGS];
  void *values[NARGS];
  ffi_type ss_type;
  ffi_type *ss_elements[3];
  small_struct in[NARGS];
  small_struct result = { 0, 0 };
  int i, expected_a = 0, expected_b = 0;

  ss_type.size = 0;
  ss_type.alignment = 0;
  ss_type.type = FFI_TYPE_STRUCT;
  ss_type.elements = ss_elements;
  ss_elements[0] = &ffi_type_sint;
  ss_elements[1] = &ffi_type_sint;
  ss_elements[2] = NULL;

  for (i = 0; i < NARGS; i++)
    {
      in[i].a = i + 1;
      in[i].b = -(i + 1);
      expected_a += in[i].a;
      expected_b += in[i].b;
      args[i] = &ss_type;
      values[i] = &in[i];
    }

  CHECK(ffi_prep_cif(&cif, ABI_NUM, NARGS, &ss_type, args) == FFI_OK);

  ffi_call(&cif, FFI_FN(many_small), &result, values);

  CHECK(result.a == expected_a);
  CHECK(result.b == expected_b);

  exit(0);
}

ffi_call_plan *
ffi_call_plan_alloc (ffi_cif *cif)
{
  ffi_call_plan *plan = malloc (sizeof (struct ffi_call_plan));
  if (plan != NULL)
    plan->cif = cif;
  return plan;
}

void
ffi_call_plan_invoke (ffi_call_plan *plan, void (*fn) (void),
		      void *rvalue, void **avalue)
{
  ffi_call (plan->cif, fn, rvalue, avalue);
}

void
ffi_call_plan_free (ffi_call_plan *plan)
{
  free (plan);
}

ffi_call_plan *
ffi_call_plan_alloc (ffi_cif *cif)
{
  ffi_call_plan *plan = malloc (sizeof (struct ffi_call_plan));
  if (plan == NULL)
    return NULL;
  plan->cif  = cif;
  plan->fast = build_plan (cif);	/* NULL if this signature has no fast path */
  return plan;
}

void
ffi_call_plan_invoke (ffi_call_plan *plan, void (*fn) (void),
		      void *rvalue, void **avalue)
{
  if (plan->fast != NULL)
    plan_exec (plan->cif, plan->fast, fn, rvalue, avalue);
  else
    ffi_call (plan->cif, fn, rvalue, avalue);
}

void
ffi_call_plan_free (ffi_call_plan *plan)
  if (plan != NULL)
    {
      free (plan->fast);
      free (plan);
    }

void *
ffi_build_plan_arch (ffi_cif *cif)
{
  return ffi_w64_build_plan (cif);
}

static inline void
store_ret (void *rvalue, unsigned retcode, struct ffi_ret2 r)
{
  switch (retcode)
    {
    case UNIX64_RET_VOID:   break;
    case UNIX64_RET_UINT8:  *(UINT64 *) rvalue = (UINT8)  r.i; break;
    case UNIX64_RET_UINT16: *(UINT64 *) rvalue = (UINT16) r.i; break;
    case UNIX64_RET_UINT32: *(UINT64 *) rvalue = (UINT32) r.i; break;
    case UNIX64_RET_SINT8:  *(UINT64 *) rvalue = (UINT64)(SINT64)(SINT8)  r.i; break;
    case UNIX64_RET_SINT16: *(UINT64 *) rvalue = (UINT64)(SINT64)(SINT16) r.i; break;
    case UNIX64_RET_SINT32: *(UINT64 *) rvalue = (UINT64)(SINT64)(SINT32) r.i; break;
    case UNIX64_RET_INT64:  *(UINT64 *) rvalue = r.i; break;
    case UNIX64_RET_XMM32:  memcpy (rvalue, &r.d, 4); break;
    case UNIX64_RET_XMM64:  memcpy (rvalue, &r.d, 8); break;
    }
}

static void
build_demarshal (ffi_cif *cif, ffi_plan *plan)
{
  unsigned i, avn = cif->nargs;
  int gprcount, ssecount, ngpr, nsse, ok = 1;
  size_t argp_off = 0;
  enum x86_64_reg_class classes[MAX_CLASSES];
  ffi_dent *dem = plan->dem;	/* points inside the plan's own allocation */

  plan->dem_ok = 0;
  gprcount = ssecount = 0;
  if (plan->ret_in_mem)
    gprcount++;				/* sret pointer occupies gpr[0] */

  for (i = 0; i < avn; i++)
    {
      ffi_type *at = cif->arg_types[i];
      size_t n = examine_argument (at, classes, 0, &ngpr, &nsse);
      if (n == 0
	  || gprcount + ngpr > MAX_GPR_REGS
	  || ssecount + nsse > MAX_SSE_REGS)
	{
	  long align = at->alignment;
	  if (align > 8)			/* over-aligned incoming stack slot */
	    { ok = 0; break; }
	  if (align < 8)
	    align = 8;
	  argp_off = FFI_ALIGN (argp_off, align);
	  dem[i].on_stack = 1;
	  dem[i].off = (unsigned) argp_off;
	  argp_off += at->size;
	}
      else if (n == 1
	       || (n == 2 && !(SSE_CLASS_P (classes[0])
			       || SSE_CLASS_P (classes[1]))))
	{
	  dem[i].on_stack = 0;
	  if (SSE_CLASS_P (classes[0]))
	    {
	      dem[i].off = (unsigned) (offsetof (struct register_args, sse)
				       + ssecount * sizeof (union big_int_union));
	      ssecount += n;
	    }
	  else
	    {
	      dem[i].off = (unsigned) (gprcount * 8);
	      gprcount += n;
	    }
	}
      else
	{ ok = 0; break; }			/* split (gather) arg */
    }
  plan->dem_ok = ok;
}

static ffi_plan *
build_plan (ffi_cif *cif)
{
  unsigned i, avn = cif->nargs;
  enum x86_64_reg_class classes[MAX_CLASSES];
  unsigned nm, gprcount, ssecount;
  size_t argp_off;
  ffi_plan *plan;
  int all_gp64 = 1;	/* every arg is exactly one 64-bit GP move? */

  if (cif->abi != FFI_UNIX64)
    return NULL;

  /* Reject arg types this cut doesn't encode; returns are handled by flags. */
  for (i = 0; i < avn; i++)
    {
      int t = cif->arg_types[i]->type;
      if (t == FFI_TYPE_STRUCT || t == FFI_TYPE_COMPLEX)
	return NULL;
#if FFI_TYPE_LONGDOUBLE != FFI_TYPE_DOUBLE
      if (t == FFI_TYPE_LONGDOUBLE)
	return NULL;
#endif
    }

  /* One self-contained allocation: header + moves + inline demarshal array,
     so the plan cache can release an evicted plan with a plain free(). */
  plan = malloc (sizeof (ffi_plan) + sizeof (ffi_move) * (2 * avn + 1)
		 + sizeof (ffi_dent) * avn);
  if (plan == NULL)
    return NULL;
  plan->dem = (ffi_dent *) &plan->moves[2 * avn + 1];

  nm = gprcount = ssecount = 0;
  argp_off = 0;
  plan->ret_in_mem = (cif->flags & UNIX64_FLAG_RET_IN_MEM) ? 1 : 0;
  if (plan->ret_in_mem)
    gprcount++;				/* sret pointer occupies gpr[0] */

  for (i = 0; i < avn; i++)
    {
      ffi_type *at = cif->arg_types[i];
      size_t size = at->size, n, rem;
      int ngpr, nsse;
      unsigned j;

      n = examine_argument (at, classes, 0, &ngpr, &nsse);
      if (n == 0
	  || gprcount + ngpr > MAX_GPR_REGS
	  || ssecount + nsse > MAX_SSE_REGS)
	{
	  long align = at->alignment;
	  ffi_move *m = &plan->moves[nm++];
	  all_gp64 = 0;
	  if (align < 8)
	    align = 8;
	  argp_off = FFI_ALIGN (argp_off, align);
	  m->op = FFI_MOVE_STACK;
	  m->src_idx = i;
	  m->src_off = 0;
	  m->dst_off = (unsigned) (sizeof (struct register_args) + argp_off);
	  m->len = (unsigned) size;
	  argp_off += size;
	  continue;
	}

      for (j = 0, rem = size; j < n; j++, rem -= 8)
	{
	  ffi_move m;
	  m.src_idx = i;
	  m.src_off = j * 8;
	  switch (classes[j])
	    {
	    case X86_64_NO_CLASS:
	    case X86_64_SSEUP_CLASS:
	      continue;			/* nothing placed for this 8-byte */
	    case X86_64_INTEGER_CLASS:
	    case X86_64_INTEGERSI_CLASS:
	      m.dst_off = gprcount * 8;	/* offsetof(register_args,gpr) == 0 */
	      switch (at->type)
		{
		case FFI_TYPE_SINT8:  m.op = FFI_MOVE_SE8;  all_gp64 = 0; break;
		case FFI_TYPE_SINT16: m.op = FFI_MOVE_SE16; all_gp64 = 0; break;
		case FFI_TYPE_SINT32: m.op = FFI_MOVE_SE32; all_gp64 = 0; break;
		default:
		  if (rem >= 8)
		    m.op = FFI_MOVE_GP64;
		  else
		    { m.op = FFI_MOVE_GP; m.len = (unsigned) rem; all_gp64 = 0; }
		  break;
		}
	      gprcount++;
	      break;
	    case X86_64_SSE_CLASS:
	    case X86_64_SSEDF_CLASS:
	      m.dst_off = (unsigned) (offsetof (struct register_args, sse)
				      + ssecount * sizeof (union big_int_union));
	      m.op = FFI_MOVE_SSE64;
	      ssecount++;
	      all_gp64 = 0;
	      break;
	    case X86_64_SSESF_CLASS:
	      m.dst_off = (unsigned) (offsetof (struct register_args, sse)
				      + ssecount * sizeof (union big_int_union));
	      m.op = FFI_MOVE_SSE32;
	      ssecount++;
	      all_gp64 = 0;
	      break;
	    default:
	      free (plan);		/* X87 etc. in registers: bail */
	      return NULL;
	    }
	  plan->moves[nm++] = m;
	}
    }

  plan->nmoves = nm;
  plan->ssecount = ssecount;
  plan->bytes = cif->bytes;
  plan->flags = cif->flags;
  plan->retcode = cif->flags & 0xff;	/* UNIX64_RET_* */
  /* Lean-trampoline eligible: no spilled stack args and a simple return
     (VOID..XMM64, codes 0..9; RET_IN_MEM has low byte VOID).  Struct-in-regs
     (>=12) and x87 (10,11) returns stay on ffi_call_unix64. */
  plan->fast = (cif->bytes == 0 && plan->retcode <= UNIX64_RET_XMM64) ? 1 : 0;
  /* Pure-GP64 direct thunk: every arg is one 64-bit GP value (so a plain load
     per arg is exact), <=6 of them, no sret, simple return -> load avalue
     straight into the arg registers, no register image. */
  plan->thunk_n =
    (all_gp64 && !plan->ret_in_mem && nm == avn && avn <= MAX_GPR_REGS
     && plan->fast)
    ? (int) avn : -1;
  build_demarshal (cif, plan);		/* closure (upcall) fast path */
  return plan;
}

FFI_ASAN_NO_SANITIZE
static inline __attribute__ ((always_inline)) void
plan_exec (ffi_cif *cif, ffi_plan *plan, void (*fn) (void),
	   void *rvalue, void **avalue)
{
  unsigned flags = plan->flags;
  struct register_args local __attribute__ ((aligned (16)));
  char *stack = NULL;
  struct register_args *reg_args;
  unsigned k;

  if (rvalue == NULL)
    {
      if (flags & UNIX64_FLAG_RET_IN_MEM)
	rvalue = alloca (cif->rtype->size);
      else
	flags = UNIX64_RET_VOID;
    }

  if (plan->thunk_n >= 0)
    {
      /* Pure-GP64: load avalue straight into arg regs, no image at all. */
      struct ffi_ret2 r = ffi_gp_thunks[plan->thunk_n] (avalue, fn);
      if (rvalue != NULL)
	store_ret (rvalue, plan->retcode, r);
      return;
    }

  if (plan->fast)
    reg_args = &local;			/* no stack args: fixed local image */
  else
    {
      stack = alloca (sizeof (struct register_args) + plan->bytes + 4 * 8);
      reg_args = (struct register_args *) stack;
    }
  reg_args->r10 = 0;			/* closure (none for ffi_call) */
  if (plan->ret_in_mem)
    reg_args->gpr[0] = (UINT64) (uintptr_t) rvalue;

  for (k = 0; k < plan->nmoves; k++)
    {
      ffi_move *m = &plan->moves[k];
      char *src = (char *) avalue[m->src_idx] + m->src_off;
      char *dst = (char *) reg_args + m->dst_off;
      switch (m->op)
	{
	/* x86-64: unaligned scalar loads from avalue[] are fine. */
	case FFI_MOVE_SE8:   *(UINT64 *) dst = (UINT64) (SINT64) *(SINT8 *)  src; break;
	case FFI_MOVE_SE16:  *(UINT64 *) dst = (UINT64) (SINT64) *(SINT16 *) src; break;
	case FFI_MOVE_SE32:  *(UINT64 *) dst = (UINT64) (SINT64) *(SINT32 *) src; break;
	case FFI_MOVE_GP64:  *(UINT64 *) dst = *(UINT64 *) src;                   break;
	case FFI_MOVE_GP:    *(UINT64 *) dst = 0; memcpy (dst, src, m->len);     break;
	case FFI_MOVE_SSE64: *(UINT64 *) dst = *(UINT64 *) src;                   break;
	case FFI_MOVE_SSE32: *(UINT32 *) dst = *(UINT32 *) src;                   break;
	case FFI_MOVE_STACK: memcpy (dst, src, m->len);                          break;
	}
    }
  reg_args->rax = plan->ssecount;

  if (plan->fast)
    {
      /* No stack args; lean trampoline + return store replicating the
	 unix64.S store_table widths.  ret_in_mem already wrote gpr[0]. */
      struct ffi_ret2 r = ffi_plan_fast_call (reg_args, fn);
      if (rvalue != NULL)
	store_ret (rvalue, plan->retcode, r);
      return;
    }

  ffi_call_unix64 (stack, plan->bytes + sizeof (struct register_args),
		   flags, rvalue, fn);
}

void *
ffi_build_plan_arch (ffi_cif *cif)
{
  return (cif->abi == FFI_UNIX64)
    ? (void *) build_plan (cif)
    : ffi_w64_build_plan (cif);
}

void * FFI_HIDDEN
ffi_w64_build_plan (ffi_cif *cif)
{
  unsigned i, n = cif->nargs;
  w64_plan *p;
  int nreg, usable = 1;

  if (cif->abi != FFI_WIN64 && cif->abi != FFI_GNUW64)
    return NULL;

  p = malloc (sizeof (w64_plan) + n * sizeof (w64_aent));
  if (p == NULL)
    return NULL;

  p->flags = cif->flags;
  p->nargs = n;
  p->struct_ret = (cif->flags == FFI_TYPE_STRUCT);
  nreg = p->struct_ret;

  for (i = 0; i < n; i++, nreg++)
    {
      ffi_type *at = cif->arg_types[i];
      size_t size = at->size, type = at->type;

      if (type == FFI_TYPE_UINT128 || type == FFI_TYPE_SINT128
	  || (type == FFI_TYPE_STRUCT
	      && size != 1 && size != 2 && size != 4 && size != 8))
	{
	  /* Passed by reference; forward needs a by-value copy -> bail there,
	     but the demarshal can still point straight at the pointer slot. */
	  usable = 0;
	  p->e[i].width = 0;
	  p->e[i].dkind = W64_DK_BYREF;
	}
      else
	{
	  p->e[i].width = (unsigned char) size;		/* 1/2/4/8 */
	  p->e[i].dkind = ((type == FFI_TYPE_DOUBLE || type == FFI_TYPE_FLOAT)
			   && nreg < 4) ? W64_DK_FARGS : W64_DK_ARGS;
	}
    }
  p->usable = usable;
  p->dem_ok = 1;
  return p;
}

FFI_ASAN_NO_SANITIZE
static void
w64_plan_exec (ffi_cif *cif, w64_plan *p, void (*fn)(void),
	       void *rvalue, void **avalue)
{
  int i, j, n, flags = (int) p->flags;
  UINT64 *stack;
  size_t rsize = 0;
  struct win64_call_frame *frame;

  if (rvalue == NULL)
    {
      if (flags == FFI_TYPE_STRUCT)
	rsize = cif->rtype->size;
      else
	flags = FFI_TYPE_VOID;
    }

  stack = alloca (cif->bytes + sizeof (struct win64_call_frame) + rsize);
  frame = (struct win64_call_frame *) ((char *) stack + cif->bytes);
  if (rsize)
    rvalue = frame + 1;

  frame->fn = (uintptr_t) fn;
  frame->flags = flags;
  frame->rvalue = (uintptr_t) rvalue;

  j = 0;
  if (flags == FFI_TYPE_STRUCT)
    { stack[0] = (uintptr_t) rvalue; j = 1; }

  for (i = 0, n = (int) p->nargs; i < n; i++, j++)
    switch (p->e[i].width)
      {
      case 8: stack[j] = *(UINT64 *) avalue[i]; break;
      case 4: stack[j] = *(UINT32 *) avalue[i]; break;
      case 2: stack[j] = *(UINT16 *) avalue[i]; break;
      case 1: stack[j] = *(UINT8 *)  avalue[i]; break;
      }

  ffi_call_win64 (stack, frame, NULL);
}

static int utf8_byte_len(unsigned char c) {
    if ((c & 0x80) == 0) return 1;
    if ((c & 0xE0) == 0xC0) return 2;
    if ((c & 0xF0) == 0xE0) return 3;
    if ((c & 0xF8) == 0xF0) return 4;
    return 1;
}

static uint32_t utf8_decode(const char *s, int len) {
    unsigned char c = s[0];
    uint32_t cp;
    if (len == 1) {
        cp = c;
    } else if (len == 2) {
        cp = (c & 0x1F) << 6;
        cp |= (s[1] & 0x3F);
    } else if (len == 3) {
        cp = (c & 0x0F) << 12;
        cp |= (s[1] & 0x3F) << 6;
        cp |= (s[2] & 0x3F);
    } else if (len == 4) {
        cp = (c & 0x07) << 18;
        cp |= (s[1] & 0x3F) << 12;
        cp |= (s[2] & 0x3F) << 6;
        cp |= (s[3] & 0x3F);
    } else {
        cp = c;
    }
    return cp;
}

static void emu_clear_cell(int row, int col) {
    emu_screen[row][col].ch[0] = ' ';
    emu_screen[row][col].ch[1] = '\0';
    emu_screen[row][col].len = 1;
    emu_screen[row][col].width = 1;
}

static void emu_init(int rows, int cols) {
    emu_rows = rows < EMU_ROWS ? rows : EMU_ROWS;
    emu_cols = cols < EMU_COLS ? cols : EMU_COLS;
    emu_cursor_row = 0;
    emu_cursor_col = 0;
    emu_after_zwj = 0;
    parser_state = STATE_NORMAL;
    csi_len = 0;
    utf8_len = 0;
    utf8_expected = 0;
    for (int r = 0; r < emu_rows; r++) {
        for (int c = 0; c < emu_cols; c++) {
            emu_clear_cell(r, c);
        }
    }
}

static void emu_clear_to_eol(void) {
    for (int c = emu_cursor_col; c < emu_cols; c++) {
        emu_clear_cell(emu_cursor_row, c);
    }
}

static void emu_clear_screen(void) {
    for (int r = 0; r < emu_rows; r++) {
        for (int c = 0; c < emu_cols; c++) {
            emu_clear_cell(r, c);
        }
    }
    emu_cursor_row = 0;
    emu_cursor_col = 0;
}

static int csi_get_param(int def) {
    if (csi_len == 0) return def;
    csi_buf[csi_len] = '\0';
    int val = atoi(csi_buf);
    return val > 0 ? val : def;
}

static void emu_handle_csi(char cmd) {
    int n = csi_get_param(1);

    switch (cmd) {
    case 'A':  /* Cursor Up */
        emu_cursor_row -= n;
        if (emu_cursor_row < 0) emu_cursor_row = 0;
        break;
    case 'B':  /* Cursor Down */
        emu_cursor_row += n;
        if (emu_cursor_row >= emu_rows) emu_cursor_row = emu_rows - 1;
        break;
    case 'C':  /* Cursor Forward */
        emu_cursor_col += n;
        if (emu_cursor_col >= emu_cols) emu_cursor_col = emu_cols - 1;
        break;
    case 'D':  /* Cursor Backward */
        emu_cursor_col -= n;
        if (emu_cursor_col < 0) emu_cursor_col = 0;
        break;
    case 'H':  /* Cursor Home (or position if params given) */
        emu_cursor_row = 0;
        emu_cursor_col = 0;
        break;
    case 'J':  /* Erase Display */
        if (n == 2) emu_clear_screen();
        break;
    case 'K':  /* Erase Line */
        if (n == 0 || csi_len == 0) emu_clear_to_eol();
        break;
    case 'm':  /* SGR (colors/attributes) - ignore */
        break;
    default:
        /* Unknown CSI sequence, ignore */
        break;
    }
}

static int emu_find_prev_cell(int row, int col) {
    /* Move back to find the cell that owns this position. */
    while (col > 0) {
        col--;
        if (emu_screen[row][col].width != 0) {
            return col;
        }
    }
    return -1;  /* No previous cell found. */
}

static void emu_put_char(const char *ch, int chlen) {
    uint32_t cp = utf8_decode(ch, chlen);
    int width = codepoint_width(cp);

    /* If we're after a ZWJ, append this char to the previous cell
     * regardless of its width (it's being joined). */
    if (emu_after_zwj) {
        emu_after_zwj = 0;
        int prev_col = emu_find_prev_cell(emu_cursor_row, emu_cursor_col);
        if (prev_col >= 0) {
            emu_cell_t *cell = &emu_screen[emu_cursor_row][prev_col];
            if (cell->len + chlen < (int)sizeof(cell->ch) - 1) {
                memcpy(cell->ch + cell->len, ch, chlen);
                cell->len += chlen;
                cell->ch[cell->len] = '\0';
            }
        }
        /* Check if this char is also a ZWJ (unlikely but possible). */
        if (emu_is_zwj(cp)) {
            emu_after_zwj = 1;
        }
        return;
    }

    if (width == 0) {
        /* Zero-width character - append to previous cell if possible.
         * This handles variation selectors, skin tones, ZWJ sequences. */
        int prev_col = emu_find_prev_cell(emu_cursor_row, emu_cursor_col);
        if (prev_col >= 0) {
            emu_cell_t *cell = &emu_screen[emu_cursor_row][prev_col];
            /* Append if there's room in the buffer. */
            if (cell->len + chlen < (int)sizeof(cell->ch) - 1) {
                memcpy(cell->ch + cell->len, ch, chlen);
                cell->len += chlen;
                cell->ch[cell->len] = '\0';
            }
        }
        /* If this was a ZWJ, next char should also be appended. */
        if (emu_is_zwj(cp)) {
            emu_after_zwj = 1;
        }
        return;
    }

    /* Check if there's room for this character. */
    if (emu_cursor_col + width > emu_cols) {
        /* No room, don't display (clip at edge). */
        return;
    }

    /* Store the character in the current cell. */
    memcpy(emu_screen[emu_cursor_row][emu_cursor_col].ch, ch, chlen);
    emu_screen[emu_cursor_row][emu_cursor_col].ch[chlen] = '\0';
    emu_screen[emu_cursor_row][emu_cursor_col].len = chlen;
    emu_screen[emu_cursor_row][emu_cursor_col].width = width;
    emu_cursor_col++;

    /* For wide characters, mark the next cell as continuation. */
    if (width == 2 && emu_cursor_col < emu_cols) {
        emu_screen[emu_cursor_row][emu_cursor_col].ch[0] = '\0';
        emu_screen[emu_cursor_row][emu_cursor_col].len = 0;
        emu_screen[emu_cursor_row][emu_cursor_col].width = 0;
        emu_cursor_col++;
    }
}

static void emu_feed_byte(unsigned char c) {
    switch (parser_state) {
    case STATE_NORMAL:
        if (c == 0x1b) {
            parser_state = STATE_ESC;
            utf8_len = 0;  /* Cancel any pending UTF-8 sequence. */
        } else if (c == '\r') {
            emu_cursor_col = 0;
            utf8_len = 0;
        } else if (c == '\n') {
            emu_cursor_row++;
            if (emu_cursor_row >= emu_rows) {
                /* Scroll up: move all rows up, clear bottom row. */
                for (int r = 0; r < emu_rows - 1; r++) {
                    memcpy(emu_screen[r], emu_screen[r + 1],
                           sizeof(emu_cell_t) * emu_cols);
                }
                for (int c2 = 0; c2 < emu_cols; c2++) {
                    emu_clear_cell(emu_rows - 1, c2);
                }
                emu_cursor_row = emu_rows - 1;
            }
            utf8_len = 0;
        } else if (c == '\b') {
            if (emu_cursor_col > 0) {
                emu_cursor_col--;
                /* If we're on a continuation cell, back up one more. */
                if (emu_screen[emu_cursor_row][emu_cursor_col].width == 0 &&
                    emu_cursor_col > 0) {
                    emu_cursor_col--;
                }
            }
            utf8_len = 0;
        } else if (c >= 32 || (c & 0x80)) {
            /* Printable character or UTF-8 byte. */
            if ((c & 0x80) == 0) {
                /* ASCII character - display immediately. */
                char ch[2] = {c, '\0'};
                emu_put_char(ch, 1);
                utf8_len = 0;
            } else if ((c & 0xC0) == 0xC0) {
                /* Start of UTF-8 multi-byte sequence. */
                utf8_buf[0] = c;
                utf8_len = 1;
                utf8_expected = utf8_byte_len(c);
            } else if ((c & 0xC0) == 0x80 && utf8_len > 0) {
                /* Continuation byte. */
                utf8_buf[utf8_len++] = c;
                if (utf8_len >= utf8_expected) {
                    /* Complete UTF-8 character. */
                    utf8_buf[utf8_len] = '\0';
                    emu_put_char(utf8_buf, utf8_len);
                    utf8_len = 0;
                }
            } else {
                /* Invalid UTF-8 - reset. */
                utf8_len = 0;
            }
        }
        break;

    case STATE_ESC:
        if (c == '[') {
            parser_state = STATE_CSI;
            csi_len = 0;
        } else {
            /* Unknown escape, back to normal. */
            parser_state = STATE_NORMAL;
        }
        break;

    case STATE_CSI:
        if (c >= '0' && c <= '9') {
            if (csi_len < (int)sizeof(csi_buf) - 1) {
                csi_buf[csi_len++] = c;
            }
        } else if (c == ';') {
            /* Multiple params - for simplicity, just reset. */
            csi_len = 0;
        } else {
            /* End of CSI sequence. */
            emu_handle_csi(c);
            parser_state = STATE_NORMAL;
        }
        break;
    }
}

static void emu_feed(const char *buf, int len) {
    if (emu_debug) {
        printf("EMU_FEED (%d bytes): ", len);
        for (int i = 0; i < len && i < 200; i++) {
            unsigned char c = buf[i];
            if (c >= 32 && c < 127) printf("%c", c);
            else printf("<%02X>", c);
        }
        if (len > 200) printf("...");
        printf("\n");
    }
    for (int i = 0; i < len; i++) {
        emu_feed_byte((unsigned char)buf[i]);
    }
}

static const char *emu_get_row(int row) {
    static char buf[EMU_COLS * 4 + 1];  /* Each cell can be up to 4 UTF-8 bytes. */
    if (row < 0 || row >= emu_rows) {
        buf[0] = '\0';
        return buf;
    }
    /* Build the row string, skipping continuation cells. */
    int pos = 0;
    int last_non_space = -1;
    for (int c = 0; c < emu_cols; c++) {
        emu_cell_t *cell = &emu_screen[row][c];
        if (cell->width == 0) continue;  /* Skip continuation cells. */

        int chlen = strlen(cell->ch);
        if (pos + chlen < (int)sizeof(buf) - 1) {
            memcpy(buf + pos, cell->ch, chlen);
            if (!(chlen == 1 && cell->ch[0] == ' ')) {
                last_non_space = pos + chlen;
            }
            pos += chlen;
        }
    }
    /* Trim trailing spaces. */
    if (last_non_space >= 0) {
        buf[last_non_space] = '\0';
    } else {
        buf[0] = '\0';
    }
    return buf;
}

static void render_to_terminal(const char *test_name) {
    /* Clear real screen and move home. */
    printf("\x1b[2J\x1b[H");

    /* Header. */
    printf("\x1b[1;36m=== LINENOISE TEST: %s ===\x1b[0m\n\n", test_name);

    /* Draw screen with border. */
    printf("\x1b[33m+");
    for (int c = 0; c < emu_cols; c++) printf("-");
    printf("+\x1b[0m\n");

    for (int r = 0; r < emu_rows; r++) {
        printf("\x1b[33m|\x1b[0m");
        for (int c = 0; c < emu_cols; c++) {
            emu_cell_t *cell = &emu_screen[r][c];

            if (cell->width == 0) {
                /* Continuation cell - skip (already printed with wide char). */
                continue;
            }

            if (r == emu_cursor_row && c == emu_cursor_col) {
                /* Highlight cursor position. */
                printf("\x1b[7m%s\x1b[0m", cell->ch);
            } else {
                printf("%s", cell->ch);
            }
        }
        printf("\x1b[33m|\x1b[0m\n");
    }

    printf("\x1b[33m+");
    for (int c = 0; c < emu_cols; c++) printf("-");
    printf("+\x1b[0m\n");

    /* Cursor info. */
    printf("\nCursor: row=%d, col=%d\n", emu_cursor_row, emu_cursor_col);
    fflush(stdout);
}

static int test_start(const char *test_name, const char *program) {
    current_test = test_name;
    emu_init(EMU_ROWS, EMU_COLS);

    if (pipe(pipe_to_child) == -1) {
        perror("pipe");
        return -1;
    }
    if (pipe(pipe_from_child) == -1) {
        perror("pipe");
        return -1;
    }

    child_pid = fork();
    if (child_pid == -1) {
        perror("fork");
        return -1;
    }

    if (child_pid == 0) {
        /* Child process. */
        close(pipe_to_child[1]);   /* Close write end. */
        close(pipe_from_child[0]); /* Close read end. */

        dup2(pipe_to_child[0], STDIN_FILENO);
        dup2(pipe_from_child[1], STDOUT_FILENO);
        dup2(pipe_from_child[1], STDERR_FILENO);

        close(pipe_to_child[0]);
        close(pipe_from_child[1]);

        /* Set test environment variables. */
        setenv("LINENOISE_ASSUME_TTY", "1", 1);
        setenv("LINENOISE_COLS", "80", 1);

        /* Use shell to parse the command line arguments. */
        execl("/bin/sh", "sh", "-c", program, NULL);
        perror("exec");
        exit(1);
    }

    /* Parent process. */
    close(pipe_to_child[0]);   /* Close read end. */
    close(pipe_from_child[1]); /* Close write end. */

    /* Give child time to start and print prompt. */
    usleep(50000);  /* 50ms */

    /* Read initial output (prompt) with timeout. */
    char buf[4096];
    fd_set fds;
    struct timeval tv = {1, 0};  /* 1 second timeout */

    FD_ZERO(&fds);
    FD_SET(pipe_from_child[0], &fds);

    if (select(pipe_from_child[0] + 1, &fds, NULL, NULL, &tv) > 0) {
        int n = read(pipe_from_child[0], buf, sizeof(buf) - 1);
        if (n > 0) {
            buf[n] = '\0';
            emu_feed(buf, n);
        }
    }

    render_to_terminal(test_name);
    return 0;
}

static void test_end(void) {
    if (child_pid > 0) {
        /* Send Ctrl-D (EOF) to terminate cleanly. */
        write(pipe_to_child[1], "\x04", 1);
        usleep(50000);

        /* Close our end of the pipe to signal EOF. */
        close(pipe_to_child[1]);

        /* Wait briefly for child to exit. */
        int status;
        int wait_result = waitpid(child_pid, &status, WNOHANG);
        if (wait_result == 0) {
            /* Child didn't exit, send SIGTERM. */
            kill(child_pid, SIGTERM);
            usleep(10000);
            waitpid(child_pid, &status, WNOHANG);
        }
        child_pid = -1;
    } else {
        close(pipe_to_child[1]);
    }
    close(pipe_from_child[0]);
}

static void send_keys(const char *keys) {
    write(pipe_to_child[1], keys, strlen(keys));
    usleep(30000);  /* 30ms - give linenoise time to process. */

    /* Read response with timeout. */
    char buf[4096];
    fd_set fds;
    struct timeval tv;
    int max_reads = 10;  /* Prevent infinite loop. */

    while (max_reads-- > 0) {
        FD_ZERO(&fds);
        FD_SET(pipe_from_child[0], &fds);
        tv.tv_sec = 0;
        tv.tv_usec = 50000;  /* 50ms timeout */

        if (select(pipe_from_child[0] + 1, &fds, NULL, NULL, &tv) <= 0) {
            break;  /* Timeout or error. */
        }
        int n = read(pipe_from_child[0], buf, sizeof(buf) - 1);
        if (n <= 0) break;
        buf[n] = '\0';
        emu_feed(buf, n);
    }

    render_to_terminal(current_test);
}

static void assert_screen_row(int row, const char *expected) {
    tests_run++;
    const char *actual = emu_get_row(row);
    if (strcmp(actual, expected) == 0) {
        tests_passed++;
        printf("\x1b[32m[PASS]\x1b[0m Row %d == \"%s\"\n", row, expected);
    } else {
        tests_failed++;
        printf("\x1b[31m[FAIL]\x1b[0m Row %d:\n", row);
        printf("       Expected: \"%s\"\n", expected);
        printf("       Actual:   \"%s\"\n", actual);
    }
    fflush(stdout);
}

static void assert_cursor(int row, int col) {
    tests_run++;
    if (emu_cursor_row == row && emu_cursor_col == col) {
        tests_passed++;
        printf("\x1b[32m[PASS]\x1b[0m Cursor at (%d, %d)\n", row, col);
    } else {
        tests_failed++;
        printf("\x1b[31m[FAIL]\x1b[0m Cursor position:\n");
        printf("       Expected: (%d, %d)\n", row, col);
        printf("       Actual:   (%d, %d)\n", emu_cursor_row, emu_cursor_col);
    }
    fflush(stdout);
}

static void assert_row_contains(int row, const char *substr) {
    tests_run++;
    const char *actual = emu_get_row(row);
    if (strstr(actual, substr) != NULL) {
        tests_passed++;
        printf("\x1b[32m[PASS]\x1b[0m Row %d contains \"%s\"\n", row, substr);
    } else {
        tests_failed++;
        printf("\x1b[31m[FAIL]\x1b[0m Row %d doesn't contain \"%s\"\n", row, substr);
        printf("       Actual: \"%s\"\n", actual);
    }
    fflush(stdout);
}

static void assert_cell_content(int row, int col, const char *expected, int expected_len) {
    tests_run++;
    emu_cell_t *cell = &emu_screen[row][col];
    if (cell->len == expected_len && memcmp(cell->ch, expected, expected_len) == 0) {
        tests_passed++;
        printf("\x1b[32m[PASS]\x1b[0m Cell (%d,%d) contains %d bytes\n", row, col, expected_len);
    } else {
        tests_failed++;
        printf("\x1b[31m[FAIL]\x1b[0m Cell (%d,%d) content mismatch:\n", row, col);
        printf("       Expected: %d bytes [", expected_len);
        for (int i = 0; i < expected_len; i++) printf("%02X ", (unsigned char)expected[i]);
        printf("]\n");
        printf("       Actual:   %d bytes [", cell->len);
        for (int i = 0; i < cell->len; i++) printf("%02X ", (unsigned char)cell->ch[i]);
        printf("]\n");
    }
    fflush(stdout);
}

static void assert_cell_width(int row, int col, int expected_width) {
    tests_run++;
    emu_cell_t *cell = &emu_screen[row][col];
    if (cell->width == expected_width) {
        tests_passed++;
        printf("\x1b[32m[PASS]\x1b[0m Cell (%d,%d) width == %d\n", row, col, expected_width);
    } else {
        tests_failed++;
        printf("\x1b[31m[FAIL]\x1b[0m Cell (%d,%d) width:\n", row, col);
        printf("       Expected: %d\n", expected_width);
        printf("       Actual:   %d\n", cell->width);
    }
    fflush(stdout);
}

static void test_simple_typing(void) {
    if (test_start("Simple Typing", "./linenoise_example") == -1) return;

    send_keys("hello");
    assert_row_contains(0, "hello");
    assert_cursor(0, strlen("hello> ") + 5);

    send_keys(" world");
    assert_screen_row(0, "hello> hello world");

    test_end();
}

static void test_cursor_movement(void) {
    if (test_start("Cursor Movement", "./linenoise_example") == -1) return;

    send_keys("abcdef");
    int prompt_len = strlen("hello> ");

    /* Move left 3 times. */
    send_keys(KEY_LEFT KEY_LEFT KEY_LEFT);
    assert_cursor(0, prompt_len + 3);  /* After "abc" */

    /* Move right 1 time. */
    send_keys(KEY_RIGHT);
    assert_cursor(0, prompt_len + 4);  /* After "abcd" */

    /* Home. */
    send_keys(KEY_CTRL_A);
    assert_cursor(0, prompt_len);

    /* End. */
    send_keys(KEY_CTRL_E);
    assert_cursor(0, prompt_len + 6);

    test_end();
}

static void test_backspace_delete(void) {
    if (test_start("Backspace and Delete", "./linenoise_example") == -1) return;

    send_keys("hello");
    int prompt_len = strlen("hello> ");

    /* Backspace. */
    send_keys(KEY_BACKSPACE);
    assert_row_contains(0, "hell");
    assert_cursor(0, prompt_len + 4);

    /* Move left and delete forward. */
    send_keys(KEY_LEFT KEY_LEFT);
    send_keys(KEY_DELETE);
    assert_row_contains(0, "hel");

    test_end();
}

static void test_utf8_typing(void) {
    if (test_start("UTF-8 Typing", "./linenoise_example") == -1) return;

    /* Type some UTF-8 characters. */
    send_keys("caf\xc3\xa9");  /* "café" - é is 2 bytes */
    assert_row_contains(0, "café");

    test_end();
}

s

tic void test_utf8_emoji(void) {
    if (test_start("UTF-8 Emoji", "./linenoise_example") == -1) return;

    int prompt_len = strlen("hello> ");

    /* Type text with emoji (🎉 is 4 bytes, displays as 2 columns). */
    send_keys("hi \xf0\x9f\x8e\x89 there");  /* "hi 🎉 there" */
    assert_row_contains(0, "hi");

    /* The emoji takes 2 columns, so cursor should be at:
     * prompt(7) + "hi "(3) + emoji(2) + " there"(6) = 18 */
    assert_cursor(0, prompt_len + 3 + 2 + 6);

    test_end();
}

static

id test_utf8_cursor_over_emoji(void) {
    if (test_start("UTF-8 Cursor Over Emoji", "./linenoise_example") == -1) return;

    int prompt_len = strlen("hello> ");

    /* Type: "a🎉b" */
    send_keys("a\xf0\x9f\x8e\x89" "b");
    /* Cursor after 'b': prompt + 'a'(1) + emoji(2) + 'b'(1) = prompt + 4 */
    assert_cursor(0, prompt_len + 4);

    /* Move left over 'b'. */
    send_keys(KEY_LEFT);
    assert_cursor(0, prompt_len + 3);  /* After emoji */

    /* Move left over emoji (should move 2 columns in one keystroke). */
    send_keys(KEY_LEFT);
    assert_cursor(0, prompt_len + 1);  /* After 'a' */

    /* Move left over 'a'. */
    send_keys(KEY_LEFT);
    assert_cursor(0, prompt_len);  /* At start */

    test_end();
}

static voi

test_utf8_backspace_emoji(void) {
    if (test_start("UTF-8 Backspace Emoji", "./linenoise_example") == -1) return;

    /* Type: "x🎉y" then backspace should delete 'y', then emoji, then 'x'. */
    send_keys("x\xf0\x9f\x8e\x89" "y");
    assert_row_contains(0, "x");  /* Contains at least 'x' */

    send_keys(KEY_BACKSPACE);  /* Delete 'y' */
    /* Now should be "x🎉" */

    send_keys(KEY_BACKSPACE);  /* Delete emoji (4 bytes, one backspace) */
    assert_row_contains(0, "hello> x");

    send_keys(KEY_BACKSPACE);  /* Delete 'x' */
    /* Now should be empty after prompt */

    /* Type new text to verify buffer is truly empty (no orphaned bytes). */
    send_keys("ok");
    assert_row_contains(0, "hello> ok");

    test_end();
}

static void test

tf8_backspace_4byte_only(void) {
    if (test_start("UTF-8 Backspace 4-byte Only", "./linenoise_example") == -1) return;

    int prompt_len = strlen("hello> ");

    /* Type a single 4-byte emoji (robot 🤖 = F0 9F A4 96). */
    send_keys("\xf0\x9f\xa4\x96");
    assert_cursor(0, prompt_len + 2);  /* Emoji is 2 columns wide */

    /* Backspace should delete the entire 4-byte emoji in one keystroke. */
    send_keys(KEY_BACKSPACE);
    assert_cursor(0, prompt_len);  /* Cursor should be at prompt end */

    /* Type new text to verify no orphaned bytes remain in buffer. */
    send_keys("test");
    assert_row_contains(0, "hello> test");

    /* The row should NOT contain any garbage characters. */
    /* If there were orphaned bytes, "test" would appear after them. */

    test_end();
}

static void test_ut

_grapheme_clusters(void) {
    if (test_start("UTF-8 Grapheme Clusters", "./linenoise_example") == -1) return;

    int prompt_len = strlen("hello> ");

    /* Test 1: Heart with variation selector ❤️ (U+2764 + U+FE0F = 6 bytes).
     * Bytes: E2 9D A4 EF B8 8F */
    send_keys("\xe2\x9d\xa4\xef\xb8\x8f");
    assert_cursor(0, prompt_len + 2);  /* Emoji is 2 columns wide */

    /* Backspace should delete the entire grapheme cluster (6 bytes). */
    send_keys(KEY_BACKSPACE);
    assert_cursor(0, prompt_len);

    /* Verify buffer is clean by typing new text. */
    send_keys("a");
    assert_row_contains(0, "hello> a");
    send_keys(KEY_BACKSPACE);

    /* Test 2: Thumbs up with skin tone 👍🏻 (U+1F44D + U+1F3FB = 8 bytes).
     * Bytes: F0 9F 91 8D F0 9F 8F BB */
    send_keys("\xf0\x9f\x91\x8d\xf0\x9f\x8f\xbb");
    assert_cursor(0, prompt_len + 2);  /* Still 2 columns (skin tone is zero-width) */

    /* Backspace should delete the entire grapheme cluster (8 bytes). */
    send_keys(KEY_BACKSPACE);
    assert_cursor(0, prompt_len);

    /* Verify buffer is clean. */
    send_keys("b");
    assert_row_contains(0, "hello> b");
    send_keys(KEY_BACKSPACE);

    /* Test 3: Rainbow flag 🏳️‍🌈 (U+1F3F3 + U+FE0F + U+200D + U+1F308 = 14 bytes).
     * Bytes: F0 9F 8F B3 EF B8 8F E2 80 8D F0 9F 8C 88 */
    send_keys("\xf0\x9f\x8f\xb3\xef\xb8\x8f\xe2\x80\x8d\xf0\x9f\x8c\x88");
    /* This should render as 2 columns (single emoji).
     * The ZWJ-joined rainbow should not add extra width. */
    assert_cursor(0, prompt_len + 2);

    /* Backspace should delete the entire ZWJ sequence. */
    send_keys(KEY_BACKSPACE);
    assert_cursor(0, prompt_len);

    /* Verify buffer is clean. */
    send_keys("c");
    assert_row_contains(0, "hello> c");
    send_keys(KEY_BACKSPACE);

    /* Test 4: Family emoji 👨‍👩‍👧 (man + ZWJ + woman + ZWJ + girl = 18 bytes).
     * Bytes: F0 9F 91 A8 E2 80 8D F0 9F 91 A9 E2 80 8D F0 9F 91 A7
     * Should render as 2 columns despite having 3 emoji joined by ZWJ. */
    send_keys("\xf0\x9f\x91\xa8\xe2\x80\x8d\xf0\x9f\x91\xa9\xe2\x80\x8d\xf0\x9f\x91\xa7");
    assert_cursor(0, prompt_len + 2);

    /* Backspace should delete the entire ZWJ sequence. */
    send_keys(KEY_BACKSPACE);
    assert_cursor(0, prompt_len);

    /* Verify buffer is clean. */
    send_keys("ok");
    assert_row_contains(0, "hello> ok");

    test_end();
}

static void test_utf8_grapheme_cursor_movement(void)

if (test_start("UTF-8 Grapheme Cursor Movement", "./linenoise_example") == -1) return;

    int prompt_len = strlen("hello> ");

    /* Type: a + thumbs up with skin tone + b
     * 👍🏻 = F0 9F 91 8D F0 9F 8F BB (8 bytes, 2 columns)
     * Layout: prompt(7) + a(1) + 👍🏻(2) + b(1) = 11 total columns */
    send_keys("a\xf0\x9f\x91\x8d\xf0\x9f\x8f\xbb" "b");
    assert_cursor(0, prompt_len + 4);  /* 7 + 1 + 2 + 1 = 11 */

    /* Move left over 'b'. */
    send_keys(KEY_LEFT);
    assert_cursor(0, prompt_len + 3);  /* 7 + 1 + 2 = 10 */

    /* Move left over thumbs up (should move 2 columns in one keystroke). */
    send_keys(KEY_LEFT);
    assert_cursor(0, prompt_len + 1);  /* 7 + 1 = 8 */

    /* Move left over 'a'. */
    send_keys(KEY_LEFT);
    assert_cursor(0, prompt_len);  /* 7 */

    /* Move right over 'a'. */
    send_keys(KEY_RIGHT);
    assert_cursor(0, prompt_len + 1);  /* 7 + 1 = 8 */

    /* Move right over thumbs up (should move 2 columns in one keystroke). */
    send_keys(KEY_RIGHT);
    assert_cursor(0, prompt_len + 3);  /* 7 + 1 + 2 = 10 */

    /* Move right over 'b'. */
    send_keys(KEY_RIGHT);
    assert_cursor(0, prompt_len + 4);  /* 7 + 1 + 2 + 1 = 11 */

    test_end();
}

static void test_emulator_grapheme_storage(void) {
    if (test_

art("Emulator Grapheme Storage", "./linenoise_example") == -1) return;
    emu_debug = 1;  /* Enable debug output */

    int prompt_len = strlen("hello> ");

    /* Test 1: Thumbs up with skin tone 👍🏻 should be stored as single cell.
     * U+1F44D + U+1F3FB = 8 bytes.
     * Bytes: F0 9F 91 8D F0 9F 8F BB */
    const char thumbs_up[] = "\xf0\x9f\x91\x8d\xf0\x9f\x8f\xbb";
    send_keys(thumbs_up);

    /* Cell at column 7 should contain all 8 bytes. */
    assert_cell_content(0, prompt_len, thumbs_up, 8);
    assert_cell_width(0, prompt_len, 2);

    /* Cell at column 8 should be continuation (width=0). */
    assert_cell_width(0, prompt_len + 1, 0);

    send_keys(KEY_BACKSPACE);

    /* Test 2: Heart with variation selector ❤️ should be stored as single cell.
     * U+2764 + U+FE0F = 6 bytes.
     * Bytes: E2 9D A4 EF B8 8F */
    const char heart[] = "\xe2\x9d\xa4\xef\xb8\x8f";
    send_keys(heart);

    /* Cell at column 7 should contain all 6 bytes. */
    assert_cell_content(0, prompt_len, heart, 6);
    assert_cell_width(0, prompt_len, 2);

    /* Cell at column 8 should be continuation. */
    assert_cell_width(0, prompt_len + 1, 0);

    test_end();
}

