static int utf8ByteLen(char c) {
    unsigned char uc = (unsigned char)c;
    if ((uc & 0x80) == 0)    return 1;   /* 0xxxxxxx: ASCII */
    if ((uc & 0xE0) == 0xC0) return 2;   /* 110xxxxx: 2-byte seq */
    if ((uc & 0xF0) == 0xE0) return 3;   /* 1110xxxx: 3-byte seq */
    if ((uc & 0xF8) == 0xF0) return 4;   /* 11110xxx: 4-byte seq */
    return 1; /* Fallback for invalid encoding, treat as single byte. */
}

static uint32_t utf8DecodeChar(const char *s, size_t *len) {
    unsigned char *p = (unsigned char *)s;
    uint32_t cp;

    if ((*p & 0x80) == 0) {
        *len = 1;
        return *p;
    } else if ((*p & 0xE0) == 0xC0) {
        *len = 2;
        cp = (*p & 0x1F) << 6;
        cp |= (p[1] & 0x3F);
        return cp;
    } else if ((*p & 0xF0) == 0xE0) {
        *len = 3;
        cp = (*p & 0x0F) << 12;
        cp |= (p[1] & 0x3F) << 6;
        cp |= (p[2] & 0x3F);
        return cp;
    } else if ((*p & 0xF8) == 0xF0) {
        *len = 4;
        cp = (*p & 0x07) << 18;
        cp |= (p[1] & 0x3F) << 12;
        cp |= (p[2] & 0x3F) << 6;
        cp |= (p[3] & 0x3F);
        return cp;
    }
    *len = 1;
    return *p; /* Fallback for invalid sequences. */
}

static uint32_t utf8DecodePrev(const char *buf, size_t pos, size_t *cplen) {
    if (pos == 0) {
        *cplen = 0;
        return 0;
    }
    /* Scan backwards to find the start byte. */
    size_t i = pos;
    do {
        i--;
    } while (i > 0 && (pos - i) < 4 && ((unsigned char)buf[i] & 0xC0) == 0x80);
    *cplen = pos - i;
    size_t dummy;
    return utf8DecodeChar(buf + i, &dummy);
}

static size_t utf8PrevCharLen(const char *buf, size_t pos) {
    if (pos == 0) return 0;

    size_t total = 0;
    size_t curpos = pos;

    /* First, get the last codepoint. */
    size_t cplen;
    uint32_t cp = utf8DecodePrev(buf, curpos, &cplen);
    if (cplen == 0) return 0;
    total += cplen;
    curpos -= cplen;

    /* If we're at an extending character, we need to find what it extends.
     * Keep going back through the grapheme cluster. */
    while (curpos > 0) {
        size_t prevlen;
        uint32_t prevcp = utf8DecodePrev(buf, curpos, &prevlen);
        if (prevlen == 0) break;

        if (isZWJ(prevcp)) {
            /* ZWJ joins two emoji. Include the ZWJ and continue to get
             * the preceding character. */
            total += prevlen;
            curpos -= prevlen;
            /* Now get the character before ZWJ. */
            prevcp = utf8DecodePrev(buf, curpos, &prevlen);
            if (prevlen == 0) break;
            total += prevlen;
            curpos -= prevlen;
            cp = prevcp;
            continue;  /* Check if there's more extending before this. */
        } else if (isGraphemeExtend(cp)) {
            /* Current cp is an extending character; include previous. */
            total += prevlen;
            curpos -= prevlen;
            cp = prevcp;
            continue;
        } else if (isRegionalIndicator(cp) && isRegionalIndicator(prevcp)) {
            /* Two regional indicators form a flag. But we need to be careful:
             * flags are always pairs, so only join if we're at an even boundary.
             * For simplicity, just join one pair. */
            total += prevlen;
            curpos -= prevlen;
            break;
        } else {
            /* No more extending; we've found the start of the cluster. */
            break;
        }
    }

    return total;
}

static size_t utf8NextCharLen(const char *buf, size_t pos, size_t len) {
    if (pos >= len) return 0;

    size_t total = 0;
    size_t curpos = pos;

    /* Get the first codepoint. */
    size_t cplen;
    uint32_t cp = utf8DecodeChar(buf + curpos, &cplen);
    total += cplen;
    curpos += cplen;

    int isRI = isRegionalIndicator(cp);

    /* Consume any extending characters that follow. */
    while (curpos < len) {
        size_t nextlen;
        uint32_t nextcp = utf8DecodeChar(buf + curpos, &nextlen);

        if (isZWJ(nextcp) && curpos + nextlen < len) {
            /* ZWJ: include it and the following character. */
            total += nextlen;
            curpos += nextlen;
            /* Get the character after ZWJ. */
            nextcp = utf8DecodeChar(buf + curpos, &nextlen);
            total += nextlen;
            curpos += nextlen;
            continue;  /* Check for more extending after the joined char. */
        } else if (isGraphemeExtend(nextcp)) {
            /* Variation selector, skin tone, combining mark, etc. */
            total += nextlen;
            curpos += nextlen;
            continue;
        } else if (isRI && isRegionalIndicator(nextcp)) {
            /* Second regional indicator for a flag pair. */
            total += nextlen;
            curpos += nextlen;
            isRI = 0;  /* Only pair once. */
            continue;
        } else {
            break;
        }
    }

    return total;
}

ic size_t utf8StrWidth(const char *s, size_t len) {
    size_t width = 0;
    size_t i = 0;
    int after_zwj = 0;  /* Track if previous char was ZWJ */

    while (i < len) {
        size_t clen;
        uint32_t cp = utf8DecodeChar(s + i, &clen);

        if (after_zwj) {
            /* Character after ZWJ: don't add width, it's joined.
             * But do check for extending chars after it. */
            after_zwj = 0;
        } else {
            width += utf8CharWidth(cp);
        }

        /* Check if this is a ZWJ - next char will be joined. */
        if (isZWJ(cp)) {
            after_zwj = 1;
        }

        i += clen;
    }
    return width;
}

/*

ic int utf8SingleCharWidth(const char *s, size_t len) {
    if (len == 0) return 0;
    size_t clen;
    uint32_t cp = utf8DecodeChar(s, &clen);
    return utf8CharWidth(cp);
}

static bool lcui_app_id_is_valid(const char *app_id)
{
        const unsigned char *p;

        if (!app_id || app_id[0] == 0) {
                return false;
        }
        for (p = (const unsigned char *)app_id; *p; ++p) {
                if (isalnum(*p) || *p == '.' || *p == '_' || *p == '-') {
                        continue;
                }
                return false;
        }
        return true;
}

bool lcui_set_app_id(const char *app_id)
{
        size_t len;
        char *new_app_id;

        if (!lcui_app_id_is_valid(app_id)) {
                return false;
        }
        len = strlen(app_id);
        new_app_id = malloc(sizeof(char) * (len + 1));
        if (!new_app_id) {
                return false;
        }
        strcpy(new_app_id, app_id);
        free(lcui_app_id);
        lcui_app_id = new_app_id;
        return true;
}

static char *lcui_strdup(const char *str)
{
        size_t len;
        char *copy;

        if (!str) {
                return NULL;
        }
        len = strlen(str);
        copy = malloc(sizeof(char) * (len + 1));
        if (!copy) {
                return NULL;
        }
        strcpy(copy, str);
        return copy;
}

static int lcui_mkdir(const char *path)
{
#ifdef _WIN32
        return _mkdir(path);
#else
        return mkdir(path, 0700);
#endif
}

static bool lcui_mkdir_recursive(const char *path)
{
        size_t i, len;
        char ch;
        char *buffer;

        if (!path || path[0] == 0) {
                return false;
        }
        len = strlen(path);
        buffer = lcui_strdup(path);
        if (!buffer) {
                return false;
        }
        for (i = 1; i <= len; ++i) {
                if (buffer[i] != '/' && buffer[i] != '\\' && buffer[i] != 0) {
                        continue;
                }
                ch = buffer[i];
                if (ch != 0) {
                        buffer[i] = 0;
                }
                if (buffer[0] == 0) {
                        if (ch != 0) {
                                buffer[i] = ch;
                        }
                        continue;
                }
#ifdef _WIN32
                if (isalpha((unsigned char)buffer[0]) && buffer[1] == ':' &&
                    buffer[2] == 0) {
                        if (ch != 0) {
                                buffer[i] = ch;
                        }
                        continue;
                }
#endif
                if (lcui_mkdir(buffer) != 0 && errno != EEXIST) {
                        free(buffer);
                        return false;
                }
                if (ch != 0) {
                        buffer[i] = ch;
                }
        }
        free(buffer);
        return true;
}

static char *lcui_join_path(const char *left, const char *right)
{
        size_t left_len, right_len;
        char *path;

        if (!left || !right) {
                return NULL;
        }
        left_len = strlen(left);
        right_len = strlen(right);
        path = malloc(sizeof(char) * (left_len + right_len + 2));
        if (!path) {
                return NULL;
        }
        strcpy(path, left);
        if (left_len > 0 && path[left_len - 1] != '/' &&
            path[left_len - 1] != '\\') {
                path[left_len] = '/';
                path[left_len + 1] = 0;
        }
        strcat(path, right);
        return path;
}

static char *lcui_settings_get_config_root(void)
{
#ifdef _WIN32
        const char *base = getenv("APPDATA");
        if (base && base[0] != 0) {
                return lcui_strdup(base);
        }
        base = getenv("USERPROFILE");
        if (base && base[0] != 0) {
                return lcui_join_path(base, "AppData/Roaming");
        }
#elif defined(__APPLE__)
        const char *base = getenv("HOME");
        if (base && base[0] != 0) {
                return lcui_join_path(base, "Library/Application Support");
        }
#else
        const char *base = getenv("XDG_CONFIG_HOME");
        if (base && base[0] != 0) {
                return lcui_strdup(base);
        }
        base = getenv("HOME");
        if (base && base[0] != 0) {
                return lcui_join_path(base, ".config");
        }
#endif
        return NULL;
}

static bool lcui_settings_resolve_path(char **out_path)
{
        char *config_root, *app_dir, *settings_path;
        const char *app_id = lcui_get_app_id();

        if (!app_id || app_id[0] == 0) {
                return false;
        }
        config_root = lcui_settings_get_config_root();
        if (!config_root) {
                return false;
        }
        app_dir = lcui_join_path(config_root, app_id);
        free(config_root);
        if (!app_dir) {
                return false;
        }
        if (!lcui_mkdir_recursive(app_dir)) {
                free(app_dir);
                return false;
        }
        settings_path = lcui_join_path(app_dir, "settings.ini");
        free(app_dir);
        if (!settings_path) {
                return false;
        }
        *out_path = settings_path;
        return true;
}

static char *lcui_store_trim(char *str)
{
        size_t len;

        while (*str && isspace((unsigned char)*str)) {
                ++str;
        }
        len = strlen(str);
        while (len > 0 && isspace((unsigned char)str[len - 1])) {
                str[--len] = 0;
        }
        return str;
}

static bool lcui_store_parse_int(const char *str, int *out)
{
        long value;
        char *endptr;

        if (!str || !out) {
                return false;
        }
        errno = 0;
        value = strtol(str, &endptr, 10);
        if (errno != 0 || endptr == str || *endptr != 0 || value > INT_MAX ||
            value < INT_MIN) {
                return false;
        }
        *out = (int)value;
        return true;
}

static bool lcui_store_parse_bool(const char *str, bool *out)
{
        if (!str || !out) {
                return false;
        }
        if (strcmp(str, "1") == 0 || strcasecmp(str, "true") == 0) {
                *out = true;
                return true;
        }
        if (strcmp(str, "0") == 0 || strcasecmp(str, "false") == 0) {
                *out = false;
                return true;
        }
        return false;
}

static bool lcui_store_load(const char *path, lcui_store_rendering_t *settings,
                            bool *dirty, bool *exists)
{
        int value;
        bool flag;
        bool has_version = false;
        char line[1024];
        char section[64] = { 0 };
        FILE *fp = fopen(path, "r");

        if (!fp) {
                if (errno == ENOENT) {
                        *exists = false;
                        return true;
                }
                return false;
        }
        *exists = true;
        while (fgets(line, sizeof(line), fp)) {
                char *data = lcui_store_trim(line);
                char *equal;

                if (data[0] == 0 || data[0] == ';' || data[0] == '#') {
                        continue;
                }
                if (data[0] == '[') {
                        char *end = strchr(data, ']');
                        if (!end) {
                                continue;
                        }
                        *end = 0;
                        snprintf(section, sizeof(section), "%s", data + 1);
                        continue;
                }
                equal = strchr(data, '=');
                if (!equal) {
                        continue;
                }
                *equal++ = 0;
                data = lcui_store_trim(data);
                equal = lcui_store_trim(equal);
                if (strcasecmp(section, "meta") == 0 &&
                    strcasecmp(data, "version") == 0) {
                        has_version = true;
                        if (!lcui_store_parse_int(equal, &value) ||
                            value != 1) {
                                *dirty = true;
                        }
                        continue;
                }
                if (strcasecmp(section, "rendering") != 0) {
                        continue;
                }
                if (strcasecmp(data, "fps_cap") == 0) {
                        if (lcui_store_parse_int(equal, &value)) {
                                settings->fps_cap = value;
                        } else {
                                *dirty = true;
                        }
                        continue;
                }
                if (strcasecmp(data, "parallel_threads") == 0) {
                        if (lcui_store_parse_int(equal, &value)) {
                                settings->parallel_threads = value;
                        } else {
                                *dirty = true;
                        }
                        continue;
                }
                if (strcasecmp(data, "paint_flashing") == 0) {
                        if (lcui_store_parse_bool(equal, &flag)) {
                                settings->paint_flashing = flag;
                        } else {
                                *dirty = true;
                        }
                }
        }
        fclose(fp);
        if (!has_version) {
                *dirty = true;
        }
        return true;
}

static bool lcui_store_save(const char *path,
                            const lcui_store_rendering_t *settings)
{
        size_t path_len;
        char *tmp_path;
        FILE *fp;
        int ret;

        path_len = strlen(path);
        tmp_path = malloc(sizeof(char) * (path_len + 5));
        if (!tmp_path) {
                return false;
        }
        strcpy(tmp_path, path);
        strcat(tmp_path, ".tmp");
        fp = fopen(tmp_path, "w");
        if (!fp) {
                free(tmp_path);
                return false;
        }
        fprintf(fp, "[meta]\nversion=1\n\n");
        fprintf(fp, "[rendering]\n");
        fprintf(fp, "fps_cap=%d\n", settings->fps_cap);
        fprintf(fp, "parallel_threads=%d\n", settings->parallel_threads);
        fprintf(fp, "paint_flashing=%d\n", settings->paint_flashing ? 1 : 0);
        fclose(fp);
#ifdef _WIN32
        ret = MoveFileExA(tmp_path, path,
                          MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH)
                  ? 0
                  : -1;
#else
        ret = rename(tmp_path, path);
#endif
        free(tmp_path);
        return ret == 0;
}

static bool lcui_settings_repair_rendering(lcui_store_rendering_t *settings)
{
        bool valid = true;

        if (settings->fps_cap < LCUI_RENDERING_FPS_CAP_MIN ||
            settings->fps_cap > LCUI_RENDERING_FPS_CAP_MAX) {
                settings->fps_cap = lcui_default_rendering_settings.fps_cap;
                valid = false;
        }
        if (settings->parallel_threads < LCUI_RENDERING_PARALLEL_THREADS_MIN ||
            settings->parallel_threads > LCUI_RENDERING_PARALLEL_THREADS_MAX) {
                settings->parallel_threads =
                    lcui_default_rendering_settings.parallel_threads;
                valid = false;
        }
        return valid;
}

static bool lcui_settings_validate_rendering(
    const lcui_rendering_settings_t *settings)
{
        if (!settings) {
                return false;
        }
        if (settings->fps_cap < LCUI_RENDERING_FPS_CAP_MIN ||
            settings->fps_cap > LCUI_RENDERING_FPS_CAP_MAX) {
                return false;
        }
        if (settings->parallel_threads < LCUI_RENDERING_PARALLEL_THREADS_MIN ||
            settings->parallel_threads > LCUI_RENDERING_PARALLEL_THREADS_MAX) {
                return false;
        }
        return true;
}

static void lcui_settings_apply_rendering(void)
{
        ui_server_set_threads(lcui_settings.rendering.parallel_threads);
        ui_server_set_paint_flashing_enabled(
            lcui_settings.rendering.paint_flashing);
        lcui_set_fps_cap((unsigned)lcui_settings.rendering.fps_cap);
}

bool lcui_settings_load(void)
{
        bool exists = false;
        char *path;

        if (lcui_settings.loaded) {
                return true;
        }
        if (!lcui_settings_resolve_path(&path)) {
                return false;
        }
        lcui_settings.rendering = lcui_default_rendering_settings;
        lcui_settings.dirty = false;
        if (!lcui_store_load(path, &lcui_settings.rendering,
                             &lcui_settings.dirty, &exists)) {
                free(path);
                return false;
        }
        if (!exists ||
            !lcui_settings_repair_rendering(&lcui_settings.rendering)) {
                lcui_settings.dirty = true;
        }
        lcui_settings.loaded = true;
        lcui_settings.path = path;
        lcui_settings_apply_rendering();
        return true;
}

bool lcui_settings_flush(void)
{
        if (!lcui_settings.loaded || !lcui_settings.path) {
                return false;
        }
        if (!lcui_settings.dirty) {
                return true;
        }
        if (!lcui_store_save(lcui_settings.path, &lcui_settings.rendering)) {
                return false;
        }
        lcui_settings.dirty = false;
        return true;
}

void lcui_settings_unload(void)
{
        free(lcui_settings.path);
        lcui_settings.path = NULL;
        lcui_settings.loaded = false;
        lcui_settings.dirty = false;
        lcui_settings.rendering = lcui_default_rendering_settings;
}

bool lcui_settings_get_rendering(lcui_rendering_settings_t *out)
{
        if (!lcui_settings.loaded || !out) {
                return false;
        }
        out->fps_cap = lcui_settings.rendering.fps_cap;
        out->parallel_threads = lcui_settings.rendering.parallel_threads;
        out->paint_flashing = lcui_settings.rendering.paint_flashing;
        return true;
}

bool lcui_settings_set_rendering(const lcui_rendering_settings_t *in)
{
        if (!lcui_settings.loaded || !in ||
            !lcui_settings_validate_rendering(in)) {
                return false;
        }
        if (lcui_settings.rendering.fps_cap == in->fps_cap &&
            lcui_settings.rendering.parallel_threads == in->parallel_threads &&
            lcui_settings.rendering.paint_flashing == in->paint_flashing) {
                return true;
        }
        lcui_settings.rendering.fps_cap = in->fps_cap;
        lcui_settings.rendering.parallel_threads = in->parallel_threads;
        lcui_settings.rendering.paint_flashing = in->paint_flashing;
        lcui_settings_apply_rendering();
        lcui_settings.dirty = true;
        return true;
}

static bool test_prepare_env(char *base_dir, size_t base_dir_size,
                             const char *app_id)
{
        int ret;
        const char *tmp_root;
#ifdef _WIN32
        int pid = _getpid();
        tmp_root = getenv("TEMP");
        if (!tmp_root || tmp_root[0] == 0) {
                tmp_root = "C:/Temp";
        }
#else
        int pid = getpid();
        tmp_root = getenv("TMPDIR");
        if (!tmp_root || tmp_root[0] == 0) {
                tmp_root = "/tmp";
        }
#endif
        snprintf(base_dir, base_dir_size, "%s/lcui-settings-%d-%lu", tmp_root,
                 pid, (unsigned long)time(NULL) + ++test_path_counter);
        ret = test_mkdir(base_dir);
        if (ret != 0 && errno != EEXIST) {
                return false;
        }
#ifdef _WIN32
        if (!test_set_env("APPDATA", base_dir)) {
                return false;
        }
#else
        if (!test_set_env("XDG_CONFIG_HOME", base_dir)) {
                return false;
        }
#endif
        if (!lcui_set_app_id(app_id)) {
                return false;
        }
        return true;
static bool test_write_config(const char *base_dir, const char *app_id,
                              const char *content)
        bool ok = false;
        char app_dir[512];
        char config_file[600];
        FILE *fp;
        snprintf(app_dir, sizeof(app_dir), "%s/%s", base_dir, app_id);
        if (test_mkdir(app_dir) != 0 && errno != EEXIST) {
                return false;
        }
        snprintf(config_file, sizeof(config_file), "%s/settings.ini", app_dir);
        fp = fopen(config_file, "w");
        if (!fp) {
                return false;
        }
        if (fputs(content, fp) >= 0) {
                ok = true;
        }
        fclose(fp);
        return ok;
}

static bool test_read_file_contains(const char *base_dir, const char *app_id,
                                    const char *text)
{
        bool found = false;
        char config_file[600];
        char content[1024];
        FILE *fp;
        size_t len;
        snprintf(config_file, sizeof(config_file), "%s/%s/settings.ini",
                 base_dir, app_id);
        fp = fopen(config_file, "r");
        if (!fp) {
                return false;
        }
        len = fread(content, 1, sizeof(content) - 1, fp);
        fclose(fp);
        content[len] = 0;
        if (strstr(content, text)) {
                found = true;
        }
        return found;
}

static void test_settings_rendering_accessors(void)
{
        char base_dir[256];
        lcui_rendering_settings_t settings;
        ctest_equal_bool("prepare settings test env",
                         test_prepare_env(base_dir, sizeof(base_dir),
                                          "lcui-settings-rendering"),
                         true);
        lcui_init();
        ctest_equal_bool("should load settings", lcui_settings_load(), true);
        ctest_equal_bool("should get default rendering settings",
                         lcui_settings_get_rendering(&settings), true);
        ctest_equal_int("should default frame rate cap to 120",
                        settings.fps_cap, LCUI_DEFAULT_FPS_CAP);
        ctest_equal_int("should default parallel rendering threads to 4",
                        settings.parallel_threads,
                        LCUI_DEFAULT_PARALLEL_THREADS);
        ctest_equal_bool("should disable paint flashing by default",
                         settings.paint_flashing, false);
        settings.fps_cap = 240;
        settings.parallel_threads = 8;
        settings.paint_flashing = true;
        ctest_equal_bool("should set rendering settings",
                         lcui_settings_set_rendering(&settings), true);
        settings.fps_cap = 0;
        settings.parallel_threads = 0;
        settings.paint_flashing = false;
        ctest_equal_bool("should get updated rendering settings",
                         lcui_settings_get_rendering(&settings), true);
        ctest_equal_int("should apply frame rate cap", settings.fps_cap, 240);
        ctest_equal_int("should apply parallel rendering threads",
                        settings.parallel_threads, 8);
        ctest_equal_bool("should apply paint flashing", settings.paint_flashing,
                         true);
        settings.fps_cap = 20;
        ctest_equal_bool("should reject out-of-range frame rate cap",
                         lcui_settings_set_rendering(&settings), false);
        ctest_equal_bool("should keep current rendering settings",
                         lcui_settings_get_rendering(&settings), true);
        ctest_equal_int("should keep previous frame rate cap", settings.fps_cap,
                        240);
        lcui_destroy();
static void test_settings_load_merge_validate_flush(void)
        const char *app_id = "lcui-settings-load";
        char base_dir[256];
        lcui_rendering_settings_t settings;
        ctest_equal_bool("prepare settings test env",
                         test_prepare_env(base_dir, sizeof(base_dir), app_id),
                         true);
        ctest_equal_bool("write malformed settings file",
                         test_write_config(base_dir, app_id,
                                           "[meta]\nversion=abc\n\n"
                                           "[rendering]\n"
                                           "fps_cap=999\n"
                                           "parallel_threads=8\n"
                                           "paint_flashing=oops\n"),
                         true);
        ctest_equal_bool("should load settings", lcui_settings_load(), true);
        ctest_equal_bool("should get merged rendering settings",
                         lcui_settings_get_rendering(&settings), true);
        ctest_equal_int("should fallback fps_cap to default on invalid value",
                        settings.fps_cap, LCUI_DEFAULT_FPS_CAP);
        ctest_equal_int("should keep valid parallel_threads",
                        settings.parallel_threads, 8);
        ctest_equal_bool(
            "should fallback paint_flashing to default on invalid value",
            settings.paint_flashing, false);
        ctest_equal_bool("should flush normalized settings",
                         lcui_settings_flush(), true);
        ctest_equal_bool("should normalize version during flush",
                         test_read_file_contains(base_dir, app_id, "version=1"),
                         true);
        ctest_equal_bool(
            "should normalize fps_cap during flush",
            test_read_file_contains(base_dir, app_id, "fps_cap=120"), true);
        ctest_equal_bool(
            "should keep valid parallel_threads during flush",
            test_read_file_contains(base_dir, app_id, "parallel_threads=8"),
            true);
        ctest_equal_bool(
            "should normalize paint_flashing during flush",
            test_read_file_contains(base_dir, app_id, "paint_flashing=0"),
            true);
        lcui_settings_unload();
        ctest_equal_bool("write valid boolean rendering config",
                         test_write_config(base_dir, app_id,
                                           "[meta]\nversion=1\n\n"
                                           "[rendering]\n"
                                           "fps_cap=60\n"
                                           "parallel_threads=5\n"
                                           "paint_flashing=true\n"),
                         true);
        ctest_equal_bool("should reload valid rendering settings",
                         lcui_settings_load(), true);
        ctest_equal_bool("should get rendering settings after reload",
                         lcui_settings_get_rendering(&settings), true);
        ctest_equal_int("should parse fps_cap from user config",
                        settings.fps_cap, 60);
        ctest_equal_int("should parse parallel_threads from user config",
                        settings.parallel_threads, 5);
        ctest_equal_bool("should parse true bool values from user config",
                         settings.paint_flashing, true);
        lcui_destroy();
        ctest_describe("rendering settings accessors",
                       test_settings_rendering_accessors);
        ctest_describe("settings load/merge/validate/flush",
                       test_settings_load_merge_validate_flush);

