    test_ring_cleanup(&ring);
    printf("  PASSED - mmap access works\n");
}

static void test_io_uring_nop_via_ring(void)
{
    printf("Testing io_uring NOP via ring buffers...\n");

    struct test_ring ring;
    int ret = test_ring_init(&ring, 8);
    assert(ret == 0);

    /* Submit a NOP operation via ring buffers */
    unsigned int tail = ring.sq_ring->tail;
    unsigned int index = tail & ring.sq_ring->ring_mask;

    /* Fill in the SQE */
    struct io_uring_sqe *sqe = &ring.sqes[index];
    memset(sqe, 0, sizeof(*sqe));
    sqe->opcode = IORING_OP_NOP;
    sqe->user_data = 0xDEADBEEF;

    /* Update tail to submit */
    ring.sq_ring->tail = tail + 1;

    /* Call io_uring_enter to process */
    ret = sys_io_uring_enter(ring.fd, 1, 1, IORING_ENTER_GETEVENTS, NULL, 0);
    assert(ret == 1); /* returns count of submitted SQEs, not a 0/1 success flag */

    /* Check completion */
    unsigned int cq_head = ring.cq_ring->head;
    unsigned int cq_tail = ring.cq_ring->tail;

    assert(cq_tail > cq_head);

    /* Read the completion */
    struct io_uring_cqe *cqe = &ring.cq_ring->cqes[cq_head & ring.cq_ring->ring_mask];
    assert(cqe->user_data == 0xDEADBEEF);
    assert(cqe->res == 0); /* NOP should succeed */

    /* Update head to consume */
    ring.cq_ring->head = cq_head + 1;

    test_ring_cleanup(&ring);
    printf("  PASSED - NOP via ring buffers works\n");
}

static void test_io_uring_file_io(void)
{
    printf("Testing io_uring file I/O...\n");

    struct test_ring ring;
    int ret = test_ring_init(&ring, 8);
    assert(ret == 0);

    /* Create a temporary file */
    const char *test_file = "/tmp/io_uring_test.txt";
    int test_fd = open(test_file, O_RDWR | O_CREAT | O_TRUNC, 0644);
    assert(test_fd >= 0);

    /* Write some data via io_uring */
    const char *test_data = "Hello io_uring!";
    size_t test_len = strlen(test_data);

    unsigned int tail = ring.sq_ring->tail;
    unsigned int index = tail & ring.sq_ring->ring_mask;

    struct io_uring_sqe *sqe = &ring.sqes[index];
    memset(sqe, 0, sizeof(*sqe));
    sqe->opcode = IORING_OP_WRITE;
    sqe->fd = test_fd;
    sqe->addr = (uint64_t)test_data;
    sqe->len = test_len;
    sqe->off = 0;
    sqe->user_data = 0x1;

    ring.sq_ring->tail = tail + 1;

    ret = sys_io_uring_enter(ring.fd, 1, 1, IORING_ENTER_GETEVENTS, NULL, 0);
    assert(ret == 1); /* returns count of submitted SQEs */

    /* Check write completion */
    unsigned int cq_head = ring.cq_ring->head;
    unsigned int cq_tail = ring.cq_ring->tail;
    assert(cq_tail > cq_head);

    struct io_uring_cqe *cqe = &ring.cq_ring->cqes[cq_head & ring.cq_ring->ring_mask];
    assert(cqe->user_data == 0x1);
    assert(cqe->res == (int32_t)test_len);

    ring.cq_ring->head = cq_head + 1;

    /* Read back via io_uring */
    char read_buf[128] = {0};
    tail = ring.sq_ring->tail;
    index = tail & ring.sq_ring->ring_mask;

    sqe = &ring.sqes[index];
    memset(sqe, 0, sizeof(*sqe));
    sqe->opcode = IORING_OP_READ;
    sqe->fd = test_fd;
    sqe->addr = (uint64_t)read_buf;
    sqe->len = test_len;
    sqe->off = 0;
    sqe->user_data = 0x2;

    ring.sq_ring->tail = tail + 1;

    ret = sys_io_uring_enter(ring.fd, 1, 1, IORING_ENTER_GETEVENTS, NULL, 0);
    assert(ret == 1); /* returns count of submitted SQEs */

    /* Check read completion */
    cq_head = ring.cq_ring->head;
    cq_tail = ring.cq_ring->tail;
    assert(cq_tail > cq_head);

    cqe = &ring.cq_ring->cqes[cq_head & ring.cq_ring->ring_mask];
    assert(cqe->user_data == 0x2);
    assert(cqe->res == (int32_t)test_len);

    ring.cq_ring->head = cq_head + 1;

    /* Verify data */
    assert(memcmp(read_buf, test_data, test_len) == 0);

    close(test_fd);
    unlink(test_file);
    test_ring_cleanup(&ring);
    printf("  PASSED - file I/O via ring buffers works\n");
}

int main(int argc, char **argv)
{
    printf("===========================================\n");
    printf("OSv io_uring Test Suite\n");
    printf("===========================================\n\n");

    test_io_uring_setup();
    test_io_uring_init();
    test_io_uring_enter_basic();
    test_io_uring_register_buffers();
    test_io_uring_register_files();
    test_io_uring_multiple_rings();
    test_io_uring_invalid_params();
    test_io_uring_params_offsets();
    test_io_uring_fd_operations();

    printf("\nAdvanced tests (ring buffer access and I/O):\n");
    test_io_uring_mmap_access();
    test_io_uring_nop_via_ring();
    test_io_uring_enter_return_value();
    test_io_uring_file_io();
    test_io_uring_syscall_dispatch();

    printf("\n===========================================\n");
    printf("All io_uring tests PASSED!\n");
    printf("===========================================\n");
    return 0;
}

static inline uint32_t round_up_pow2(uint32_t v)
{
    if (v <= 1)
        return v;
    return 1U << (32 - __builtin_clz(v - 1));
}

static void io_uring_complete_op(struct io_uring_ctx *ctx,
                                 uint64_t user_data,
                                 int32_t  res,
                                 uint32_t cqe_flags)
{
    WITH_LOCK(ctx->mtx) {
        uint32_t head, tail, next;

        if (ctx->cq_ring) {
            auto *cq = static_cast<struct io_uring_cq_ring *>(ctx->cq_ring);
            head = cq->head.load(std::memory_order_acquire);
            tail = cq->tail.load(std::memory_order_acquire);
        } else {
            head = ctx->cq.head;
            tail = ctx->cq.tail;
        }

        next = tail + 1;
        if ((next - head) > ctx->cq.entries) {
            /* CQ overflow: increment the overflow counter */
            if (ctx->cq_ring) {
                auto *cq = static_cast<struct io_uring_cq_ring *>(ctx->cq_ring);
                cq->overflow.fetch_add(1, std::memory_order_relaxed);
            }
            ctx->pending_ops--;
            ctx->wait_cq.wake_all(ctx->mtx);
            return;
        }

        struct io_uring_cqe *cqe = &ctx->cqes[tail & ctx->cq.mask];
        cqe->user_data = user_data;
        cqe->res       = res;
        cqe->flags     = cqe_flags;

        std::atomic_thread_fence(std::memory_order_release);

        if (ctx->cq_ring) {
            auto *cq = static_cast<struct io_uring_cq_ring *>(ctx->cq_ring);
            cq->tail.store(next, std::memory_order_release);
        }
        ctx->cq.tail = next;
        ctx->pending_ops--;

        ctx->wait_cq.wake_all(ctx->mtx);
    }

    /* Notify the eventfd if registered */
    if (ctx->eventfd_fd >= 0) {
        uint64_t val = 1;
        /* Ignore write errors: eventfd notification is best-effort */
        (void)::write(ctx->eventfd_fd, &val, sizeof(val));
    }
}

static struct file *resolve_fd(struct io_uring_ctx *ctx,
                                int32_t fd,
                                uint8_t sqe_flags,
                                bool    &is_fixed)
{
    is_fixed = (sqe_flags & IOSQE_FIXED_FILE) != 0;
    if (is_fixed) {
        if ((unsigned)fd >= ctx->nr_registered_files)
            return nullptr;
        return ctx->registered_files[fd];
    }
    struct file *fp = nullptr;
    if (fget(fd, &fp) != 0)
        return nullptr;
    return fp;
}

static void exec_sqe_chain(struct io_uring_ctx *ctx,
                            std::vector<io_uring_work> chain)
{
    bool chain_failed = false;

    for (size_t i = 0; i < chain.size(); i++) {
        io_uring_work &w = chain[i];

        /* If this SQE is a LINK_TIMEOUT, it is handled by the previous op's
         * completion.  Just post -ECANCELED (op already done). */
        if (w.sqe.opcode == IORING_OP_LINK_TIMEOUT) {
            io_uring_complete_op(ctx, w.sqe.user_data, -ECANCELED, 0);
            continue;
        }

        /* Check for async-cancel of this work item */
        if (w.cancelled.load(std::memory_order_relaxed)) {
            io_uring_complete_op(ctx, w.sqe.user_data, -ECANCELED, 0);
            chain_failed = true;
            continue;
        }

        /* Propagate chain failure to non-hardlinked SQEs */
        if (chain_failed && !(w.sqe.flags & IOSQE_IO_HARDLINK)) {
            io_uring_complete_op(ctx, w.sqe.user_data, -ECANCELED, 0);
            continue;
        }

        uint32_t cqe_flags = 0;
        int32_t  res       = exec_single_sqe(ctx, &w.sqe, &cqe_flags);

        /* Remove from cancellable map */
        WITH_LOCK(ctx->mtx) {
            auto range = ctx->cancellable.equal_range(w.sqe.user_data);
            for (auto it = range.first; it != range.second; ++it) {
                if (it->second == &w.cancelled) {
                    ctx->cancellable.erase(it);
                    break;
                }
            }
        }

        bool suppress = (w.sqe.flags & IOSQE_CQE_SKIP_SUCCESS) && (res >= 0);
        if (!suppress)
            io_uring_complete_op(ctx, w.sqe.user_data, res, cqe_flags);
        else {
            /* Suppressed CQE: still decrement pending_ops */
            WITH_LOCK(ctx->mtx) {
                ctx->pending_ops--;
                ctx->wait_cq.wake_all(ctx->mtx);
            }
        }

        if (res < 0) chain_failed = true;
    }
}

static int io_uring_submit_sqes(struct io_uring_ctx *ctx, unsigned count)
{
    std::vector<io_uring_work> current_chain;
    unsigned submitted = 0;

    WITH_LOCK(ctx->mtx) {
        if (ctx->shutdown)
            return -EINVAL;

        uint32_t head, tail;
        if (ctx->sq_ring) {
            auto *sq = static_cast<struct io_uring_sq_ring *>(ctx->sq_ring);
            head = sq->head.load(std::memory_order_acquire);
            tail = sq->tail.load(std::memory_order_acquire);
        } else {
            head = ctx->sq.head;
            tail = ctx->sq.tail;
        }

        auto dispatch_chain = [&](std::vector<io_uring_work> chain) {
            ctx->pending_ops += (uint32_t)chain.size();

            /* Register all items in the chain as cancellable */
            for (auto &w : chain) {
                ctx->cancellable.emplace(w.sqe.user_data, &w.cancelled);
            }

            /* shared_ptr makes the lambda copyable for std::function */
            auto cp = std::make_shared<std::vector<io_uring_work>>(
                std::move(chain));
            sched::thread::make(
                [ctx, cp]() { exec_sqe_chain(ctx, std::move(*cp)); },
                sched::thread::attr().detached())->start();
        };

        while (submitted < count && head != tail) {
            uint32_t array_idx;
            if (ctx->sq_ring) {
                auto *sq = static_cast<struct io_uring_sq_ring *>(ctx->sq_ring);
                array_idx = sq->array[head & ctx->sq.mask];
            } else {
                array_idx = head & ctx->sq.mask;
            }

            if (array_idx >= ctx->sq.entries) {
                head++;
                submitted++;
                continue;
            }

            struct io_uring_sqe *sqe = &ctx->sqes[array_idx];

            /* IO_DRAIN: wait for all pending ops before this chain */
            if (sqe->flags & IOSQE_IO_DRAIN) {
                /* Flush any already-accumulated chain first */
                if (!current_chain.empty()) {
                    dispatch_chain(std::move(current_chain));
                    current_chain.clear();
                }
                /* Wait for pending_ops == 0 */
                while (ctx->pending_ops > 0)
                    ctx->wait_cq.wait(ctx->mtx);
            }

            io_uring_work w;
            w.ctx = ctx;
            w.sqe = *sqe;

            bool linked = (sqe->flags & (IOSQE_IO_LINK | IOSQE_IO_HARDLINK)) != 0;
            current_chain.push_back(std::move(w));

            head++;
            submitted++;

            if (!linked) {
                /* End of chain: dispatch */
                dispatch_chain(std::move(current_chain));
                current_chain.clear();
            }
        }

        /* Dispatch any trailing chain (last SQE had LINK but was the last in ring) */
        if (!current_chain.empty()) {
            dispatch_chain(std::move(current_chain));
            current_chain.clear();
        }

        /* Update ring head */
        if (ctx->sq_ring) {
            auto *sq = static_cast<struct io_uring_sq_ring *>(ctx->sq_ring);
            sq->head.store(head, std::memory_order_release);
        }
        ctx->sq.head = head;
    }

    return (int)submitted;
}

static int io_uring_wait_cqe(struct io_uring_ctx *ctx, unsigned min_complete)
{
    WITH_LOCK(ctx->mtx) {
        while (true) {
            if (ctx->shutdown)
                return -EINVAL;

            uint32_t head, tail;
            if (ctx->cq_ring) {
                auto *cq = static_cast<struct io_uring_cq_ring *>(ctx->cq_ring);
                head = cq->head.load(std::memory_order_acquire);
                tail = cq->tail.load(std::memory_order_acquire);
            } else {
                head = ctx->cq.head;
                tail = ctx->cq.tail;
            }

            if ((tail - head) >= min_complete)
                return 0;

            if (ctx->pending_ops == 0 && (tail - head) > 0)
                return 0;

            ctx->wait_cq.wait(ctx->mtx);
        }
    }
    return 0;
}

static void sq_poll_loop(io_uring_ctx *ctx)
{
    using clock = std::chrono::steady_clock;
    auto idle_limit = std::chrono::milliseconds(ctx->sq_idle_ms ? ctx->sq_idle_ms : 1000);
    auto last_active = clock::now();

    while (!ctx->shutdown) {
        uint32_t head, tail;
        if (ctx->sq_ring) {
            auto *sq = static_cast<struct io_uring_sq_ring *>(ctx->sq_ring);
            head = sq->head.load(std::memory_order_acquire);
            tail = sq->tail.load(std::memory_order_acquire);
        } else {
            WITH_LOCK(ctx->mtx) { head = ctx->sq.head; tail = ctx->sq.tail; }
        }

        if (head != tail) {
            if (ctx->sq_ring) {
                auto *sq = static_cast<struct io_uring_sq_ring *>(ctx->sq_ring);
                sq->flags.fetch_and(~IORING_SQ_NEED_WAKEUP, std::memory_order_release);
            }
            io_uring_submit_sqes(ctx, ctx->sq.entries);
            last_active = clock::now();
        } else {
            if (clock::now() - last_active >= idle_limit) {
                if (ctx->sq_ring) {
                    auto *sq = static_cast<struct io_uring_sq_ring *>(ctx->sq_ring);
                    sq->flags.fetch_or(IORING_SQ_NEED_WAKEUP, std::memory_order_release);
                }
                WITH_LOCK(ctx->mtx) {
                    while (!ctx->shutdown) {
                        if (ctx->sq_ring) {
                            auto *sq = static_cast<struct io_uring_sq_ring *>(ctx->sq_ring);
                            if (sq->tail.load(std::memory_order_acquire) != head)
                                break;
                        }
                        ctx->wait_sq.wait(ctx->mtx);
                    }
                }
                last_active = clock::now();
            } else {
                sched::thread::yield();
            }
        }
    }
}

virtual int stat(struct stat *buf) override {
        memset(buf, 0, sizeof(*buf));
        buf->st_mode  = S_IFREG;
        /* Large enough to cover all IORING_OFF_* mmap regions */
        buf->st_size  = 0x20000000LL;
        return 0;
    }

io_uring_file::io_uring_file(unsigned flags, struct io_uring_ctx *ctx)
    : file(FREAD | FWRITE | flags, DTYPE_UNSPEC), _ctx(ctx)
{
    f_data = ctx;
}

void *io_uring_file::region_base(struct io_uring_ctx *ctx, off_t offset)
{
    if (offset >= IORING_OFF_SQES)
        return reinterpret_cast<char *>(ctx->sqes) + (offset - IORING_OFF_SQES);
    if (offset >= IORING_OFF_CQ_RING)
        return reinterpret_cast<char *>(ctx->cq_ring) + (offset - IORING_OFF_CQ_RING);
    if (offset >= IORING_OFF_SQ_RING)
        return reinterpret_cast<char *>(ctx->sq_ring) + (offset - IORING_OFF_SQ_RING);
    return nullptr;
}

bool io_uring_file::map_page(uintptr_t offset, mmu::hw_ptep<0> ptep,
                              mmu::pt_element<0> pte, bool write, bool shared)
{
    if (!_ctx) return false;
    void *base = region_base(_ctx, (off_t)offset);
    if (!base) return false;
    return mmu::write_pte(base, ptep, pte);
}

bool io_uring_file::map_page(uintptr_t offset, mmu::hw_ptep<1> ptep,
                              mmu::pt_element<1> pte, bool write, bool shared)
{
    if (!_ctx) return false;
    void *base = region_base(_ctx, (off_t)offset);
    if (!base) return false;
    return mmu::write_pte(base, ptep, pte);
}

bool io_uring_file::put_page(void *addr, uintptr_t offset, mmu::hw_ptep<0> ptep)
{
    ptep.write(mmu::pt_element<0>());
    return false;
}

bool io_uring_file::put_page(void *addr, uintptr_t offset, mmu::hw_ptep<1> ptep)
{
    ptep.write(mmu::pt_element<1>());
    return false;
}

std::unique_ptr<mmu::file_vma>
io_uring_file::mmap(addr_range range, unsigned flags, unsigned perm, off_t offset)
{
    if (!_ctx)
        throw make_error(EINVAL);

    size_t size = range.end() - range.start();

    if (offset == IORING_OFF_SQ_RING) {
        size_t need = sizeof(struct io_uring_sq_ring) +
                      _ctx->sq.entries * sizeof(uint32_t);
        /* Reject a mapping that is smaller than the ring or larger than the
         * page-aligned allocation; an oversized mapping would let map_page()
         * map pages past the ring buffer and expose unrelated memory. */
        if (size < need || size > align_up(need, mmu::page_size))
            throw make_error(EINVAL);

        if (!_ctx->sq_ring) {
            size_t alloc = align_up(need, mmu::page_size);
            _ctx->sq_ring = memory::alloc_phys_contiguous_aligned(alloc, mmu::page_size);
            if (!_ctx->sq_ring)
                throw make_error(ENOMEM);
            memset(_ctx->sq_ring, 0, alloc);

            auto *sq = static_cast<struct io_uring_sq_ring *>(_ctx->sq_ring);
            sq->head         = 0;
            sq->tail         = 0;
            sq->ring_mask    = _ctx->sq.mask;
            sq->ring_entries = _ctx->sq.entries;
            sq->flags        = 0;
            sq->dropped      = 0;
            for (uint32_t i = 0; i < _ctx->sq.entries; i++)
                sq->array[i] = i;
        }

    } else if (offset == IORING_OFF_CQ_RING) {
        size_t need = sizeof(struct io_uring_cq_ring) +
                      _ctx->cq.entries * sizeof(struct io_uring_cqe);
        if (size < need || size > align_up(need, mmu::page_size))
            throw make_error(EINVAL);

        if (!_ctx->cq_ring) {
            size_t alloc = align_up(need, mmu::page_size);
            _ctx->cq_ring = memory::alloc_phys_contiguous_aligned(alloc, mmu::page_size);
            if (!_ctx->cq_ring)
                throw make_error(ENOMEM);
            memset(_ctx->cq_ring, 0, alloc);

            auto *cq = static_cast<struct io_uring_cq_ring *>(_ctx->cq_ring);
            cq->head         = 0;
            cq->tail         = 0;
            cq->ring_mask    = _ctx->cq.mask;
            cq->ring_entries = _ctx->cq.entries;
            cq->overflow     = 0;

            /* Point internal cqes at the ring's embedded array */
            memory::free_phys_contiguous_aligned(_ctx->cqes);
            _ctx->cqes = cq->cqes;
        }

    } else if (offset == IORING_OFF_SQES) {
        size_t need = _ctx->sq.entries * sizeof(struct io_uring_sqe);
        if (size < need || size > align_up(need, mmu::page_size))
            throw make_error(EINVAL);
        /* SQE memory was allocated in sys_io_uring_setup; nothing to do here */

    } else {
        throw make_error(EINVAL);
    }

    return mmu::map_file_mmap(this, range, flags, perm, offset);
}

int io_uring_file::close()
{
    if (!_ctx)
        return 0;

    WITH_LOCK(_ctx->mtx) {
        _ctx->shutdown = true;
        _ctx->wait_sq.wake_all(_ctx->mtx);
        _ctx->wait_cq.wake_all(_ctx->mtx);
    }

    if (_ctx->sq_poll_thread) {
        _ctx->sq_poll_thread->join();
        delete _ctx->sq_poll_thread;
        _ctx->sq_poll_thread = nullptr;
    }

    WITH_LOCK(_ctx->mtx) {
        while (_ctx->pending_ops > 0)
            _ctx->wait_cq.wait(_ctx->mtx);
    }

    if (_ctx->sq_ring) {
        memory::free_phys_contiguous_aligned(_ctx->sq_ring);
        _ctx->sq_ring = nullptr;
    }
    if (_ctx->cq_ring) {
        /* cqes points inside cq_ring; freed together */
        memory::free_phys_contiguous_aligned(_ctx->cq_ring);
        _ctx->cq_ring = nullptr;
        _ctx->cqes = nullptr;
    } else if (_ctx->cqes) {
        memory::free_phys_contiguous_aligned(_ctx->cqes);
        _ctx->cqes = nullptr;
    }
    if (_ctx->sqes) {
        memory::free_phys_contiguous_aligned(_ctx->sqes);
        _ctx->sqes = nullptr;
    }
    if (_ctx->registered_buffers) {
        delete[] _ctx->registered_buffers;
        _ctx->registered_buffers = nullptr;
    }
    if (_ctx->registered_files) {
        for (unsigned i = 0; i < _ctx->nr_registered_files; i++) {
            if (_ctx->registered_files[i])
                fdrop(_ctx->registered_files[i]);
        }
        delete[] _ctx->registered_files;
        _ctx->registered_files = nullptr;
    }
    if (_ctx->eventfd_fd >= 0) {
        ::close(_ctx->eventfd_fd);
        _ctx->eventfd_fd = -1;
    }

    delete _ctx;
    _ctx = nullptr;
    return 0;
}

OSV_LIBC_API
long sys_io_uring_setup(unsigned entries, struct io_uring_params *params)
{
    if (entries < MIN_ENTRIES || entries > MAX_ENTRIES)
        return -EINVAL;
    if (!params)
        return -EFAULT;

    const uint32_t supported_flags = IORING_SETUP_CQSIZE
                                   | IORING_SETUP_SQPOLL
                                   | IORING_SETUP_SQ_AFF
                                   | IORING_SETUP_CLAMP;
    if (params->flags & ~supported_flags)
        return -EINVAL;

    /* Round up to next power of two (1 stays 1; clz-based round-up below
     * would otherwise turn 1 into 2 because it feeds 1 into __builtin_clz). */
    entries = round_up_pow2(entries);
    if (entries > MAX_ENTRIES && (params->flags & IORING_SETUP_CLAMP))
        entries = MAX_ENTRIES;

    auto *ctx = new io_uring_ctx;

    ctx->sq.entries = entries;
    ctx->sq.mask    = entries - 1;
    ctx->sq.head    = 0;
    ctx->sq.tail    = 0;
    ctx->sq_ring    = nullptr;

    uint32_t cq_entries = entries * 2;
    if (params->flags & IORING_SETUP_CQSIZE) {
        cq_entries = params->cq_entries;
        if (cq_entries < entries || cq_entries > MAX_ENTRIES * 2) {
            delete ctx;
            return -EINVAL;
        }
        cq_entries = round_up_pow2(cq_entries);
    }

    ctx->cq.entries = cq_entries;
    ctx->cq.mask    = cq_entries - 1;
    ctx->cq.head    = 0;
    ctx->cq.tail    = 0;
    ctx->cq_ring    = nullptr;

    ctx->sqes = static_cast<struct io_uring_sqe *>(
        memory::alloc_phys_contiguous_aligned(
            align_up(entries * sizeof(struct io_uring_sqe), mmu::page_size),
            mmu::page_size));
    ctx->cqes = static_cast<struct io_uring_cqe *>(
        memory::alloc_phys_contiguous_aligned(
            align_up(cq_entries * sizeof(struct io_uring_cqe), mmu::page_size),
            mmu::page_size));

    if (!ctx->sqes || !ctx->cqes) {
        if (ctx->sqes) memory::free_phys_contiguous_aligned(ctx->sqes);
        if (ctx->cqes) memory::free_phys_contiguous_aligned(ctx->cqes);
        delete ctx;
        return -ENOMEM;
    }

    memset(ctx->sqes, 0, entries    * sizeof(struct io_uring_sqe));
    memset(ctx->cqes, 0, cq_entries * sizeof(struct io_uring_cqe));

    try {
        fileref f = make_file<io_uring_file>(O_RDWR, ctx);

        int fd;
        int error = fdalloc(f.get(), &fd);
        if (error) {
            memory::free_phys_contiguous_aligned(ctx->sqes);
            memory::free_phys_contiguous_aligned(ctx->cqes);
            delete ctx;
            return -error;
        }

        params->sq_entries = entries;
        params->cq_entries = cq_entries;
        params->features   = IORING_FEAT_NODROP
                           | IORING_FEAT_SUBMIT_STABLE
                           | IORING_FEAT_RW_CUR_POS
                           | IORING_FEAT_FAST_POLL
                           | IORING_FEAT_SQPOLL_NONFIXED;

        params->sq_off.head         = offsetof(struct io_uring_sq_ring, head);
        params->sq_off.tail         = offsetof(struct io_uring_sq_ring, tail);
        params->sq_off.ring_mask    = offsetof(struct io_uring_sq_ring, ring_mask);
        params->sq_off.ring_entries = offsetof(struct io_uring_sq_ring, ring_entries);
        params->sq_off.flags        = offsetof(struct io_uring_sq_ring, flags);
        params->sq_off.dropped      = offsetof(struct io_uring_sq_ring, dropped);
        params->sq_off.array        = offsetof(struct io_uring_sq_ring, array);

        params->cq_off.head         = offsetof(struct io_uring_cq_ring, head);
        params->cq_off.tail         = offsetof(struct io_uring_cq_ring, tail);
        params->cq_off.ring_mask    = offsetof(struct io_uring_cq_ring, ring_mask);
        params->cq_off.ring_entries = offsetof(struct io_uring_cq_ring, ring_entries);
        params->cq_off.overflow     = offsetof(struct io_uring_cq_ring, overflow);
        params->cq_off.cqes         = offsetof(struct io_uring_cq_ring, cqes);

        if (params->flags & IORING_SETUP_SQPOLL) {
            ctx->sq_idle_ms = params->sq_thread_idle;
            ctx->sq_poll_thread = sched::thread::make(
                [ctx] { sq_poll_loop(ctx); },
                sched::thread::attr());
            ctx->sq_poll_thread->start();
        }

        return fd;

    } catch (...) {
        memory::free_phys_contiguous_aligned(ctx->sqes);
        memory::free_phys_contiguous_aligned(ctx->cqes);
        delete ctx;
        return -ENOMEM;
    }
}

OSV_LIBC_API
int sys_io_uring_enter(int fd, unsigned to_submit, unsigned min_complete,
                       unsigned flags, const void *sig, size_t sigsz)
{
    struct file *fp;
    int error = fget(fd, &fp);
    if (error)
        return -error;

    auto *io_uring_fp = dynamic_cast<io_uring_file *>(fp);
    if (!io_uring_fp) {
        fdrop(fp);
        return -EINVAL;
    }

    auto *ctx = static_cast<struct io_uring_ctx *>(fp->f_data);

    if (ctx->sq_poll_thread && (flags & IORING_ENTER_SQ_WAKEUP)) {
        WITH_LOCK(ctx->mtx) {
            ctx->wait_sq.wake_all(ctx->mtx);
        }
    }

    int submitted = 0;
    if (to_submit > 0 && !ctx->sq_poll_thread) {
        submitted = io_uring_submit_sqes(ctx, to_submit);
        if (submitted < 0) {
            fdrop(fp);
            return submitted;
        }
    }

    if (flags & IORING_ENTER_GETEVENTS) {
        int err = io_uring_wait_cqe(ctx, min_complete);
        if (err) {
            fdrop(fp);
            return err;
        }
    }

    fdrop(fp);
    return submitted;
}

int io_uring_enter(int fd, unsigned to_submit, unsigned min_complete,
                   unsigned flags, const void *sig)
{
    return sys_io_uring_enter(fd, to_submit, min_complete, flags, sig, 0);
}

static int test_ring_init(struct test_ring *ring, unsigned entries)
{
    memset(ring, 0, sizeof(*ring));

    ring->fd = sys_io_uring_setup(entries, &ring->params);
    if (ring->fd < 0) {
        return ring->fd;
    }

    /* Calculate mmap sizes */
    ring->sq_size = sizeof(struct io_uring_sq_ring) +
                    ring->params.sq_entries * sizeof(uint32_t);
    ring->cq_size = sizeof(struct io_uring_cq_ring) +
                    ring->params.cq_entries * sizeof(struct io_uring_cqe);
    ring->sqe_size = ring->params.sq_entries * sizeof(struct io_uring_sqe);

    /* Note: mmap implementation is COMPLETE and functional.
     * All three regions (SQ ring, CQ ring, SQE array) are properly mapped.
     * Known limitations:
     * - Large page (2MB) support available but not fully tested
     * - io_uring_register() implemented for buffers and files
     * - Thread-per-op model (not thread pool) - acceptable for current use
     */

    /* Try to mmap SQ ring (offset 0) */
    ring->sq_ring = (struct io_uring_sq_ring*)mmap(NULL, ring->sq_size,
                                                     PROT_READ | PROT_WRITE,
                                                     MAP_SHARED, ring->fd, 0);
    if (ring->sq_ring == MAP_FAILED) {
        close(ring->fd);
        return -errno;
    }

    /* Try to mmap CQ ring (offset != 0) */
    ring->cq_ring = (struct io_uring_cq_ring*)mmap(NULL, ring->cq_size,
                                                     PROT_READ | PROT_WRITE,
                                                     MAP_SHARED, ring->fd, 0x8000000ULL);
    if (ring->cq_ring == MAP_FAILED) {
        munmap(ring->sq_ring, ring->sq_size);
        close(ring->fd);
        return -errno;
    }

    /* Try to mmap SQE array (offset 0x10000000) */
    ring->sqes = (struct io_uring_sqe*)mmap(NULL, ring->sqe_size,
                                             PROT_READ | PROT_WRITE,
                                             MAP_SHARED, ring->fd, 0x10000000ULL);
    if (ring->sqes == MAP_FAILED) {
        munmap(ring->cq_ring, ring->cq_size);
        munmap(ring->sq_ring, ring->sq_size);
        close(ring->fd);
        return -errno;
    }

    return 0;
}

static void test_ring_cleanup(struct test_ring *ring)
{
    if (ring->sqes && ring->sqes != MAP_FAILED) {
        munmap(ring->sqes, ring->sqe_size);
    }
    if (ring->sq_ring && ring->sq_ring != MAP_FAILED) {
        munmap(ring->sq_ring, ring->sq_size);
    }
    if (ring->cq_ring && ring->cq_ring != MAP_FAILED) {
        munmap(ring->cq_ring, ring->cq_size);
    }
    if (ring->fd >= 0) {
        close(ring->fd);
    }
}

static void test_io_uring_setup(void)
{
    printf("Testing io_uring_setup...\n");

    struct io_uring_params params = {};
    long fd = sys_io_uring_setup(32, &params);

    assert(fd >= 0);
    assert(params.sq_entries == 32);
    assert(params.cq_entries == 64);  /* Default is 2x SQ entries */

    close(fd);
    printf("  PASSED - setup syscall works\n");
}

static void test_io_uring_init(void)
{
    printf("Testing io_uring initialization...\n");

    struct test_ring ring;
    int ret = test_ring_init(&ring, 8);
    assert(ret == 0);

    /* Verify ring parameters were set correctly */
    assert(ring.params.sq_entries == 8);
    assert(ring.params.cq_entries == 16);

    /* Verify mmap succeeded (even if functionality is limited) */
    assert(ring.sq_ring != NULL && ring.sq_ring != MAP_FAILED);
    assert(ring.cq_ring != NULL && ring.cq_ring != MAP_FAILED);

    /* Verify ring metadata is initialized */
    assert(ring.sq_ring->ring_entries == 8);
    assert(ring.sq_ring->ring_mask == 7);
    assert(ring.cq_ring->ring_entries == 16);
    assert(ring.cq_ring->ring_mask == 15);

    test_ring_cleanup(&ring);
    printf("  PASSED - ring initialization works\n");
}

static void test_io_uring_enter_basic(void)
{
    printf("Testing io_uring_enter syscall...\n");

    struct test_ring ring;
    int ret = test_ring_init(&ring, 8);
    assert(ret == 0);

    /* Call io_uring_enter with no submissions: exercises the syscall
     * interface and the empty-submit fast path. */
    ret = sys_io_uring_enter(ring.fd, 0, 0, 0, NULL, 0);
    assert(ret == 0);

    test_ring_cleanup(&ring);
    printf("  PASSED - enter syscall works\n");
}

static void test_io_uring_register_buffers(void)
{
    printf("Testing io_uring_register syscall with buffers...\n");

    struct test_ring ring;
    int ret = test_ring_init(&ring, 8);
    assert(ret == 0);

    /* Test registering buffers */
    struct iovec bufs[2];
    char buf1[256], buf2[512];
    bufs[0].iov_base = buf1;
    bufs[0].iov_len = sizeof(buf1);
    bufs[1].iov_base = buf2;
    bufs[1].iov_len = sizeof(buf2);

    ret = sys_io_uring_register(ring.fd, IORING_REGISTER_BUFFERS, bufs, 2);
    assert(ret == 0);

    /* Test unregistering buffers */
    ret = sys_io_uring_register(ring.fd, IORING_UNREGISTER_BUFFERS, NULL, 0);
    assert(ret == 0);

    test_ring_cleanup(&ring);
    printf("  PASSED - buffer registration works\n");
}

static void test_io_uring_register_files(void)
{
    printf("Testing io_uring_register syscall with files...\n");

    struct test_ring ring;
    int ret = test_ring_init(&ring, 8);
    assert(ret == 0);

    /* Create temporary files */
    int test_fd1 = open("/tmp/io_uring_test1.txt", O_RDWR | O_CREAT | O_TRUNC, 0644);
    assert(test_fd1 >= 0);

    int test_fd2 = open("/tmp/io_uring_test2.txt", O_RDWR | O_CREAT | O_TRUNC, 0644);
    assert(test_fd2 >= 0);

    int fds[2] = { test_fd1, test_fd2 };

    /* Test registering files */
    ret = sys_io_uring_register(ring.fd, IORING_REGISTER_FILES, fds, 2);
    assert(ret == 0);

    /* Test unregistering files */
    ret = sys_io_uring_register(ring.fd, IORING_UNREGISTER_FILES, NULL, 0);
    assert(ret == 0);

    close(test_fd1);
    close(test_fd2);
    unlink("/tmp/io_uring_test1.txt");
    unlink("/tmp/io_uring_test2.txt");

    test_ring_cleanup(&ring);
    printf("  PASSED - file registration works\n");
}

static void test_io_uring_multiple_rings(void)
{
    printf("Testing multiple io_uring instances...\n");

    struct test_ring ring1, ring2;

    int ret1 = test_ring_init(&ring1, 8);
    assert(ret1 == 0);

    int ret2 = test_ring_init(&ring2, 16);
    assert(ret2 == 0);

    /* Verify both rings have correct parameters */
    assert(ring1.params.sq_entries == 8);
    assert(ring2.params.sq_entries == 16);
    assert(ring1.fd != ring2.fd);

    test_ring_cleanup(&ring1);
    test_ring_cleanup(&ring2);
    printf("  PASSED - multiple rings work\n");
}

static void test_io_uring_invalid_params(void)
{
    printf("Testing io_uring error handling...\n");

    struct io_uring_params params = {};

    /* Test entries too small */
    long fd = sys_io_uring_setup(0, &params);
    assert(fd == -EINVAL);

    /* Test entries too large */
    fd = sys_io_uring_setup(10000, &params);
    assert(fd == -EINVAL);

    /* Test NULL params */
    fd = sys_io_uring_setup(32, NULL);
    assert(fd == -EFAULT);

    /* Test unsupported flag IORING_SETUP_ATTACH_WQ (bit 5): not implemented */
    params.flags = IORING_SETUP_ATTACH_WQ;
    fd = sys_io_uring_setup(32, &params);
    assert(fd == -EINVAL);

    printf("  PASSED - error handling works\n");
}

static void test_io_uring_params_offsets(void)
{
    printf("Testing io_uring_params sq_off/cq_off are populated...\n");

    struct io_uring_params params = {};
    long fd = sys_io_uring_setup(8, &params);
    assert(fd >= 0);

    /* sq_off must point into the SQ ring mmap region */
    assert(params.sq_off.head         == 0);
    assert(params.sq_off.tail         == 4);
    assert(params.sq_off.ring_mask    == 8);
    assert(params.sq_off.ring_entries == 12);
    assert(params.sq_off.array        > 0);   /* array follows the header */

    /* cq_off must point into the CQ ring mmap region */
    assert(params.cq_off.head         == 0);
    assert(params.cq_off.tail         == 4);
    assert(params.cq_off.ring_mask    == 8);
    assert(params.cq_off.ring_entries == 12);
    assert(params.cq_off.cqes         > 0);   /* cqes follow the header */

    close(fd);
    printf("  PASSED - sq_off/cq_off populated correctly\n");
}

static void test_io_uring_enter_return_value(void)
{
    printf("Testing io_uring_enter return value...\n");

    struct test_ring ring;
    int ret = test_ring_init(&ring, 8);
    assert(ret == 0);

    /* Submit a NOP and verify enter returns the submitted count (1), not 0 */
    unsigned int tail = ring.sq_ring->tail;
    unsigned int index = tail & ring.sq_ring->ring_mask;
    struct io_uring_sqe *sqe = &ring.sqes[index];
    memset(sqe, 0, sizeof(*sqe));
    sqe->opcode = IORING_OP_NOP;
    sqe->user_data = 0xABCD;
    ring.sq_ring->tail = tail + 1;

    ret = sys_io_uring_enter(ring.fd, 1, 1, IORING_ENTER_GETEVENTS, NULL, 0);
    assert(ret == 1);  /* must return number of submitted SQEs */

    /* Consume the CQE */
    unsigned cq_head = ring.cq_ring->head;
    ring.cq_ring->head = cq_head + 1;

    test_ring_cleanup(&ring);
    printf("  PASSED - enter returns submitted count\n");
}

static void test_io_uring_syscall_dispatch(void)
{
    printf("Testing io_uring via syscall() dispatch path...\n");

    struct io_uring_params params = {};
    /* Use the real syscall() path to verify kernel dispatch is wired up */
    long fd = syscall(SYS_io_uring_setup, 8, &params);
    assert(fd >= 0);
    assert(params.sq_entries == 8);
    assert(params.sq_off.array > 0);   /* offsets must be populated */

    /* Enter with nothing to submit */
    int ret = syscall(SYS_io_uring_enter, (int)fd, 0, 0, 0, NULL, 0);
    assert(ret == 0);

    close(fd);
    printf("  PASSED - syscall() dispatch path works\n");
}

static void test_io_uring_fd_operations(void)
{
    printf("Testing io_uring file descriptor operations...\n");

    struct test_ring ring;
    int ret = test_ring_init(&ring, 8);
    assert(ret == 0);

    /* Verify FD is valid */
    assert(ring.fd >= 0);

    /* Verify FD can be closed (will be closed again by cleanup) */
    int fd_copy = dup(ring.fd);
    assert(fd_copy >= 0);
    close(fd_copy);

    test_ring_cleanup(&ring);
    printf("  PASSED - FD operations work\n");
}

static void test_io_uring_mmap_access(void)
{
    printf("Testing io_uring mmap access...\n");

    struct test_ring ring;
    int ret = test_ring_init(&ring, 8);
    assert(ret == 0);

    /* Verify SQE array is accessible */
    assert(ring.sqes != NULL && ring.sqes != MAP_FAILED);

    /* Write to first SQE */
    ring.sqes[0].opcode = IORING_OP_NOP;
    ring.sqes[0].user_data = 0x12345678;

    /* Verify we can read it back */
    assert(ring.sqes[0].opcode == IORING_OP_NOP);
    assert(ring.sqes[0].user_data == 0x12345678);

    /* Verify ring metadata is accessible and initialized */
    assert(ring.sq_ring->ring_entries == 8);
    assert(ring.sq_ring->ring_mask == 7);
    assert(ring.cq_ring->ring_entries == 16);
    assert(ring.cq_ring->ring_mask == 15);

    test_ring_cleanup(&ring);
    printf("  PASSED - mmap access works\n");
}

static void test_io_uring_nop_via_ring(void)
{
    printf("Testing io_uring NOP via ring buffers...\n");

    struct test_ring ring;
    int ret = test_ring_init(&ring, 8);
    assert(ret == 0);

    /* Submit a NOP operation via ring buffers */
    unsigned int tail = ring.sq_ring->tail;
    unsigned int index = tail & ring.sq_ring->ring_mask;

    /* Fill in the SQE */
    struct io_uring_sqe *sqe = &ring.sqes[index];
    memset(sqe, 0, sizeof(*sqe));
    sqe->opcode = IORING_OP_NOP;
    sqe->user_data = 0xDEADBEEF;

    /* Update tail to submit */
    ring.sq_ring->tail = tail + 1;

    /* Call io_uring_enter to process */
    ret = sys_io_uring_enter(ring.fd, 1, 1, IORING_ENTER_GETEVENTS, NULL, 0);
    assert(ret == 1); /* returns count of submitted SQEs, not a 0/1 success flag */

    /* Check completion */
    unsigned int cq_head = ring.cq_ring->head;
    unsigned int cq_tail = ring.cq_ring->tail;

    assert(cq_tail > cq_head);

    /* Read the completion */
    struct io_uring_cqe *cqe = &ring.cq_ring->cqes[cq_head & ring.cq_ring->ring_mask];
    assert(cqe->user_data == 0xDEADBEEF);
    assert(cqe->res == 0); /* NOP should succeed */

    /* Update head to consume */
    ring.cq_ring->head = cq_head + 1;

    test_ring_cleanup(&ring);
    printf("  PASSED - NOP via ring buffers works\n");
}

static void test_io_uring_file_io(void)
{
    printf("Testing io_uring file I/O...\n");

    struct test_ring ring;
    int ret = test_ring_init(&ring, 8);
    assert(ret == 0);

    /* Create a temporary file */
    const char *test_file = "/tmp/io_uring_test.txt";
    int test_fd = open(test_file, O_RDWR | O_CREAT | O_TRUNC, 0644);
    assert(test_fd >= 0);

    /* Write some data via io_uring */
    const char *test_data = "Hello io_uring!";
    size_t test_len = strlen(test_data);

    unsigned int tail = ring.sq_ring->tail;
    unsigned int index = tail & ring.sq_ring->ring_mask;

    struct io_uring_sqe *sqe = &ring.sqes[index];
    memset(sqe, 0, sizeof(*sqe));
    sqe->opcode = IORING_OP_WRITE;
    sqe->fd = test_fd;
    sqe->addr = (uint64_t)test_data;
    sqe->len = test_len;
    sqe->off = 0;
    sqe->user_data = 0x1;

    ring.sq_ring->tail = tail + 1;

    ret = sys_io_uring_enter(ring.fd, 1, 1, IORING_ENTER_GETEVENTS, NULL, 0);
    assert(ret == 1); /* returns count of submitted SQEs */

    /* Check write completion */
    unsigned int cq_head = ring.cq_ring->head;
    unsigned int cq_tail = ring.cq_ring->tail;
    assert(cq_tail > cq_head);

    struct io_uring_cqe *cqe = &ring.cq_ring->cqes[cq_head & ring.cq_ring->ring_mask];
    assert(cqe->user_data == 0x1);
    assert(cqe->res == (int32_t)test_len);

    ring.cq_ring->head = cq_head + 1;

    /* Read back via io_uring */
    char read_buf[128] = {0};
    tail = ring.sq_ring->tail;
    index = tail & ring.sq_ring->ring_mask;

    sqe = &ring.sqes[index];
    memset(sqe, 0, sizeof(*sqe));
    sqe->opcode = IORING_OP_READ;
    sqe->fd = test_fd;
    sqe->addr = (uint64_t)read_buf;
    sqe->len = test_len;
    sqe->off = 0;
    sqe->user_data = 0x2;

    ring.sq_ring->tail = tail + 1;

    ret = sys_io_uring_enter(ring.fd, 1, 1, IORING_ENTER_GETEVENTS, NULL, 0);
    assert(ret == 1); /* returns count of submitted SQEs */

    /* Check read completion */
    cq_head = ring.cq_ring->head;
    cq_tail = ring.cq_ring->tail;
    assert(cq_tail > cq_head);

    cqe = &ring.cq_ring->cqes[cq_head & ring.cq_ring->ring_mask];
    assert(cqe->user_data == 0x2);
    assert(cqe->res == (int32_t)test_len);

    ring.cq_ring->head = cq_head + 1;

    /* Verify data */
    assert(memcmp(read_buf, test_data, test_len) == 0);

    close(test_fd);
    unlink(test_file);
    test_ring_cleanup(&ring);
    printf("  PASSED - file I/O via ring buffers works\n");
}

int main(int argc, char **argv)
{
    printf("===========================================\n");
    printf("OSv io_uring Test Suite\n");
    printf("===========================================\n\n");

    test_io_uring_setup();
    test_io_uring_init();
    test_io_uring_enter_basic();
    test_io_uring_register_buffers();
    test_io_uring_register_files();
    test_io_uring_multiple_rings();
    test_io_uring_invalid_params();
    test_io_uring_params_offsets();
    test_io_uring_fd_operations();

    printf("\nAdvanced tests (ring buffer access and I/O):\n");
    test_io_uring_mmap_access();
    test_io_uring_nop_via_ring();
    test_io_uring_enter_return_value();
    test_io_uring_file_io();
    test_io_uring_syscall_dispatch();

    printf("\n===========================================\n");
    printf("All io_uring tests PASSED!\n");
    printf("===========================================\n");
    return 0;
}

void ElfFile<ElfFileParamNames>::removeResolutionCache()
{
    const unsigned int noteIndex = getSectionIndex(ldCacheSectionName);
    if (!noteIndex)
        return;

    const Elf_Shdr noteShdr = shdrs.at(noteIndex);
    const Elf_Off noteOffset = rdi(noteShdr.sh_offset);
    const Elf_Off noteSize = rdi(noteShdr.sh_size);

    /* Dropping the section and program headers below does not remove the note's
       bytes from the file. Its descriptor holds "=<store-path>" entries, so
       zero them on disk; otherwise Nix's reference scanner would keep picking
       up store paths that may already be stale after an rpath change (cf. the
       'X' tainting of removed rpaths in modifyRPath). */
    if (noteOffset <= fileContents->size() && noteSize <= fileContents->size() - noteOffset)
        memset(fileContents->data() + noteOffset, 0, noteSize);

    phdrs.erase(std::remove_if(phdrs.begin(), phdrs.end(), [&] (const Elf_Phdr & phdr) {
        const auto type = rdi(phdr.p_type);
        return (type == PT_LOAD || type == PT_NOTE)
            && rdi(phdr.p_offset) == noteOffset
            && rdi(phdr.p_filesz) == noteSize;
    }), phdrs.end());
    wri(hdr()->e_phnum, phdrs.size());

    shdrs.erase(shdrs.begin() + noteIndex);
    wri(hdr()->e_shnum, shdrs.size());

    const unsigned int shstrndx = rdi(hdr()->e_shstrndx);
    if (shstrndx == noteIndex)
        error("cannot remove resolution cache note: section name table index points to it");
    if (shstrndx > noteIndex)
        wri(hdr()->e_shstrndx, shstrndx - 1);

    for (auto & shdr : shdrs) {
        const unsigned int link = rdi(shdr.sh_link);
        if (link == noteIndex)
            wri(shdr.sh_link, 0);
        else if (link > noteIndex)
            wri(shdr.sh_link, link - 1);

        const auto type = rdi(shdr.sh_type);
        if (type == SHT_REL || type == SHT_RELA) {
            const unsigned int info = rdi(shdr.sh_info);
            if (info == noteIndex)
                wri(shdr.sh_info, 0);
            else if (info > noteIndex)
                wri(shdr.sh_info, info - 1);
        }
    }

    Elf_Addr phdrAddress = 0;
    for (const auto & phdr : phdrs)
        if (rdi(phdr.p_type) == PT_PHDR) {
            phdrAddress = rdi(phdr.p_vaddr);
            break;
        }
    rewriteHeaders(phdrAddress);
    changed = true;
}

static void die(const char * msg)
{
    fprintf(stderr, "pad-to-page: %s\n", msg);
    exit(2);
}

int main(int argc, char ** argv)
{
    if (argc != 2)
        die("usage: pad-to-page ELF");

    FILE * f = fopen(argv[1], "rb");
    if (!f)
        die("cannot open file");
    if (fseek(f, 0, SEEK_END))
        die("seek failed");
    long sz = ftell(f);
    if (sz < (long) sizeof(Elf64_Ehdr))
        die("file too small");
    rewind(f);

    unsigned char * buf = malloc(sz);
    if (!buf)
        die("out of memory");
    if (fread(buf, 1, sz, f) != (size_t) sz)
        die("short read");
    fclose(f);

    if (memcmp(buf, ELFMAG, SELFMAG) != 0)
        die("not an ELF file");

    /* Read e_shoff / e_shentsize / e_shnum for the file's ELF class. */
    uint64_t shoff;
    uint64_t shentsize;
    uint64_t shnum;
    int is64 = buf[EI_CLASS] == ELFCLASS64;
    if (is64) {
        Elf64_Ehdr * eh = (Elf64_Ehdr *) buf;
        shoff = eh->e_shoff;
        shentsize = eh->e_shentsize;
        shnum = eh->e_shnum;
    } else {
        Elf32_Ehdr * eh = (Elf32_Ehdr *) buf;
        shoff = eh->e_shoff;
        shentsize = eh->e_shentsize;
        shnum = eh->e_shnum;
    }

    /* The trigger requires the SHT to sit at the end of the file. */
    if (shoff + shnum * shentsize != (uint64_t) sz)
        die("section header table is not at end of file");

    long pad = (long) ((ALIGN - (sz % ALIGN)) % ALIGN);
    if (pad == 0) {
        free(buf);
        return 0; /* already page-aligned: trigger already holds */
    }

    /* Bump e_shoff by the padding we insert before the SHT. */
    if (is64)
        ((Elf64_Ehdr *) buf)->e_shoff = shoff + pad;
    else
        ((Elf32_Ehdr *) buf)->e_shoff = (Elf32_Off) (shoff + pad);

    FILE * out = fopen(argv[1], "wb");
    if (!out)
        die("cannot reopen file for writing");

    /* pad is in [0, ALIGN), so a single ALIGN-sized buffer covers it. */
    static const unsigned char zero[ALIGN] = {0};
    if (fwrite(buf, 1, shoff, out) != shoff)
        die("write failed");
    if (fwrite(zero, 1, (size_t) pad, out) != (size_t) pad)
        die("write failed");
    if (fwrite(buf + shoff, 1, sz - shoff, out) != (size_t) (sz - shoff))
        die("write failed");

    fclose(out);
    free(buf);
    return 0;
}

static std::string extractString(const FileContents & contents, size_t offset, size_t size)
{
    checkOffset(contents, offset, size);
    return { reinterpret_cast<const char *>(contents->data()) + offset, size };
}

void ElfFile<ElfFileParamNames>::modifyExecstack(ExecstackMode op)
{
    if (op == ExecstackMode::clear || op == ExecstackMode::set) {
        size_t nullhdr = (size_t)-1;

        for (size_t i = 0; i < phdrs.size(); i++) {
            auto & header = phdrs[i];
            const auto type = rdi(header.p_type);
            if (type != PT_GNU_STACK) {
                if (!nullhdr && type == PT_NULL)
                    nullhdr = i;
                continue;
            }

            if (op == ExecstackMode::clear && (rdi(header.p_flags) & PF_X) == PF_X) {
                debug("simple execstack clear of header %zu\n", i);

                wri(header.p_flags, rdi(header.p_flags) & ~PF_X);
                * ((Elf_Phdr *) (fileContents->data() + rdi(hdr()->e_phoff)) + i) = header;
                changed = true;
            } else if (op == ExecstackMode::set && (rdi(header.p_flags) & PF_X) != PF_X) {
                debug("simple execstack set of header %zu\n", i);

                wri(header.p_flags, rdi(header.p_flags) | PF_X);
                * ((Elf_Phdr *) (fileContents->data() + rdi(hdr()->e_phoff)) + i) = header;
                changed = true;
            } else {
                debug("execstack already in requested state\n");
            }

            return;
        }

        if (nullhdr != (size_t)-1) {
            debug("replacement execstack of header %zu\n", nullhdr);

            auto & header = phdrs[nullhdr];
            header = {};
            wri(header.p_type,  PT_GNU_STACK);
            wri(header.p_flags, PF_R | PF_W | (op == ExecstackMode::set ? PF_X : 0));
            wri(header.p_align, 0x1);

            * ((Elf_Phdr *) (fileContents->data() + rdi(hdr()->e_phoff)) + nullhdr) = header;
            changed = true;
            return;
        }

        debug("header addition for execstack\n");

        Elf_Phdr new_phdr = {};
        wri(new_phdr.p_type,  PT_GNU_STACK);
        wri(new_phdr.p_flags, PF_R | PF_W | (op == ExecstackMode::set ? PF_X : 0));
        wri(new_phdr.p_align, 0x1);
        phdrs.push_back(new_phdr);

        wri(hdr()->e_phnum, rdi(hdr()->e_phnum) + 1);

        changed = true;
        rewriteSections(true);
        return;
    }

    char result = '?';

    for (const auto & header : phdrs) {
        if (rdi(header.p_type) != PT_GNU_STACK)
            continue;

        if ((rdi(header.p_flags) & PF_X) == PF_X)
            result = 'X';
        else
            result = '-';
        break;
    }

    printf("execstack: %c\n", result);
}

static bool
img_is_same_historical_page(OBTreeFindPageContext *context, bool rightmost,
							OTuple hikey)
{
	OTuple		imgHikey;

	if (O_PAGE_IS(context->img, RIGHTMOST) != rightmost)
		return false;
	if (rightmost)
		return true;

	BTREE_PAGE_GET_HIKEY(imgHikey, context->img);
	return o_btree_cmp(context->desc, &imgHikey, BTreeKeyNonLeafKey,
					   &hikey, BTreeKeyNonLeafKey) == 0;
}

static Jsonb *
seq_int_next_key_stopevent_params(BTreeSeqScan *scan, Page page,
								  BTreePageItemLocator *loc, bool firstPass)
{
	JsonbParseState *state = NULL;
	PartialPageState *partial = &scan->context.partial;
	BTreePageItemLocator next = *loc;
	bool		lastInChunk;
	bool		nextChunkLoaded = true;
	Jsonb	   *res;
	MemoryContext mctx = MemoryContextSwitchTo(stopevents_cxt);

	lastInChunk = (loc->itemOffset + 1 >= loc->chunkItemsCount);
	if (lastInChunk)
	{
		BTREE_PAGE_LOCATOR_NEXT(page, &next);
		if (BTREE_PAGE_LOCATOR_IS_VALID(page, &next) && partial->isPartial)
			nextChunkLoaded = partial->chunkIsLoaded[next.chunkOffset];
	}

	pushJsonbValue(&state, WJB_BEGIN_OBJECT, NULL);
	btree_desc_stopevent_params_internal(scan->desc, &state);
	jsonb_push_int8_key(&state, "level", PAGE_GET_LEVEL(page));
	jsonb_push_int8_key(&state, "chunkOffset", loc->chunkOffset);
	jsonb_push_bool_key(&state, "isPartial", partial->isPartial);
	jsonb_push_bool_key(&state, "lastInChunk", lastInChunk);
	jsonb_push_bool_key(&state, "nextChunkLoaded", nextChunkLoaded);
	jsonb_push_bool_key(&state, "firstPass", firstPass);
	res = JsonbValueToJsonb(pushJsonbValue(&state, WJB_END_OBJECT, NULL));
	MemoryContextSwitchTo(mctx);

	return res;
}

bool
recovery_can_rollback_conflict(UndoLogType undoType, OXid oxid,
							   UndoLocation undoLocation)
{
	RecoveryXidState *state;
	UndoMeta   *meta;
	UndoLocation location;
	bool		found;

	Assert(is_recovery_process());

	state = hash_search(recovery_xid_state_hash, &oxid, HASH_FIND, &found);
	if (!found || !state->checkpoint_xid)
		return false;

	location = UndoLocationGetValue(undoLocation);
	meta = get_undo_meta_by_type(undoType);

	return location >= pg_atomic_read_u64(&meta->checkpointRetainStartLocation) &&
		location < pg_atomic_read_u64(&meta->checkpointRetainEndLocation);
}

bool
o_index_parallel_participant_failed(oIdxShared *btshared)
{
	bool		failed;

	SpinLockAcquire(&btshared->mutex);
	failed = btshared->participantfailed;
	SpinLockRelease(&btshared->mutex);

	return failed;
}

void
o_index_parallel_report_participant_failure(shm_toc *toc)
{
	oIdxShared *btshared = shm_toc_lookup(toc, PARALLEL_KEY_BTREE_SHARED, true);

	if (btshared == NULL)
		return;

	SpinLockAcquire(&btshared->mutex);
	btshared->participantfailed = true;
	SpinLockRelease(&btshared->mutex);

	/*
	 * The leader may be parked in either of its two waits -- for participants
	 * to join, or for them to finish sorting -- so wake both.
	 */
	ConditionVariableBroadcast(&btshared->recoveryjoinedcv);
	ConditionVariableBroadcast(&btshared->workersdonecv);
}

static inline void
iterator_materialize_cur_key(BTreeIterator *it)
{
	OTuple		tup;

	if (!it->curKeyLazy)
		return;

	Assert(it->curKeySet);
	Assert(BTREE_PAGE_LOCATOR_IS_VALID(it->context.img, &it->curKeyLoc));

	BTREE_PAGE_READ_LEAF_TUPLE(tup, it->context.img, &it->curKeyLoc);
	copy_fixed_leaf_key(it->context.desc, &it->curKey, tup);
	it->curKeyLazy = false;
}

void
btree_seq_scan_set_callbacks(BTreeSeqScan *scan,
							 BTreeSeqScanCallbacks *cb, void *arg)
{
	Assert(!scan->initialized);
	scan->cb = cb;
	scan->arg = arg;
}

static inline int
array_elem_cmp(OArrayDownlinkFilter *filter, Datum elem, Datum boundary)
{
	int			cmp = o_call_comparator(filter->comparator, elem, boundary);

	return filter->ascending ? cmp : -cmp;
}

static bool
o_array_downlink_is_valid(OTuple low, OTuple high, void *arg)
{
	OArrayDownlinkFilter *filter = (OArrayDownlinkFilter *) arg;
	OIndexDescr *id = filter->indexDescr;
	BTArrayKeyInfo *arrayKey = filter->arrayKey;
	int			attnum = OIndexKeyAttnumToTupleAttnum(BTreeKeyNonLeafKey, id, 1);
	Datum		boundary;
	bool		isnull;
	int			lo = 0,
				hi = arrayKey->num_elems - 1;

	Assert(arrayKey->num_elems > 0);

	/*
	 * Find the first element at or after the low boundary.  Elements are
	 * sorted in index order, so this is a binary search.
	 */
	if (!O_TUPLE_IS_NULL(low))
	{
		boundary = o_fastgetattr(low, attnum, id->nonLeafTupdesc,
								 &id->nonLeafSpec, &isnull);

		/* A NULL boundary sorts outside the elements; do not filter on it. */
		if (isnull)
			return true;

		while (lo <= hi)
		{
			int			mid = lo + (hi - lo) / 2;

			if (array_elem_cmp(filter, arrayKey->elem_values[mid], boundary) < 0)
				lo = mid + 1;
			else
				hi = mid - 1;
		}
	}

	/* Every element sorts below the page. */
	if (lo >= arrayKey->num_elems)
		return false;

	if (O_TUPLE_IS_NULL(high))
		return true;

	boundary = o_fastgetattr(high, attnum, id->nonLeafTupdesc,
							 &id->nonLeafSpec, &isnull);
	if (isnull)
		return true;

	return array_elem_cmp(filter, arrayKey->elem_values[lo], boundary) <= 0;
}

static OArrayDownlinkFilter *
o_make_array_downlink_filter(OScanState *ostate, OIndexDescr *indexDescr)
{
	BTScanOpaque so = (BTScanOpaque) ostate->scandesc.opaque;
	OIndexField *field = &indexDescr->fields[0];
	OBTreeValueBound *bound = &ostate->curKeyRange.low.keys[0];
	int			i;

	if (so->numArrayKeys <= 0 || ostate->curKeyRange.empty)
		return NULL;

	for (i = 0; i < so->numArrayKeys; i++)
	{
		BTArrayKeyInfo *arrayKey = &so->arrayKeys[i];
		ScanKey		key = so->keyData + arrayKey->scan_key;
		OArrayDownlinkFilter *filter;

		/* Only the leading index column gives page-level selectivity. */
		if (key->sk_attno != 1)
			continue;

		/* A skip array does not enumerate its elements. */
		if (arrayKey->num_elems <= 0)
			continue;

		/*
		 * ostate->cxt outlives the scan it is attached to: a rescan frees the
		 * scan before resetting the context (o_rescan_custom_scan()).
		 */
		filter = (OArrayDownlinkFilter *)
			MemoryContextAlloc(ostate->cxt, sizeof(OArrayDownlinkFilter));
		filter->indexDescr = indexDescr;
		filter->arrayKey = arrayKey;
		filter->ascending = field->ascending;

		/* Same comparator choice as the per-tuple test in is_tuple_valid(). */
		if (o_bound_is_coercible(bound, field))
			filter->comparator = field->comparator;
		else
			filter->comparator = bound->comparator;

		return filter;
	}

	return NULL;
}

static inline bool
scan_range_side_is_open(OBTreeKeyBound *bound)
{
	return bound->nkeys == 0 ||
		(bound->keys[0].flags & O_VALUE_BOUND_UNBOUNDED) != 0;
}

static inline double
o_index_path_pages(IndexPath *ipath)
{
	return (double) ipath->indexinfo->pages * ipath->indexselectivity;
}

static LockAcquireResult
lock_acquire_no_wait_no_memory_error(const LOCKTAG *locktag, LOCKMODE lockmode)
{
	return LockAcquireExtended(locktag, lockmode,
							   false,	/* sessionLock */
							   true,	/* dontWait */
							   false,	/* reportMemoryError */
							   NULL /* locallockp */
#if PG_VERSION_NUM >= 180000
							   ,false	/* logLockFailure */
#endif
		);
}

TransactionId
ensure_current_logical_xid(void)
{
	if (!TransactionIdIsValid(logicalXidContext.xid))
	{
		bool		isValidHeapXid = false;

		logicalXidContext.xid = acquire_logical_xid_wrapper(&isValidHeapXid);
		logicalXidContext.useHeap = isValidHeapXid;
		elog(DEBUG4, "ENSURE logical xid %u useHeap %d",
			 logicalXidContext.xid, logicalXidContext.useHeap);
	}

	return logicalXidContext.xid;
}

static List *
bridged_arbiter_indexes(ResultRelInfo *resultRelInfo, List *arbiterIndexes,
						TupleTableSlot *slot, EState *estate)
{
	List	   *result = NIL;
	int			i;

	for (i = 0; i < resultRelInfo->ri_NumIndices; i++)
	{
		Relation	indexRel = resultRelInfo->ri_IndexRelationDescs[i];
		IndexInfo  *indexInfo = resultRelInfo->ri_IndexRelationInfo[i];
		OBTOptions *options;

		if (indexRel == NULL || indexInfo == NULL)
			continue;

		if (arbiterIndexes != NIL &&
			!list_member_oid(arbiterIndexes, RelationGetRelid(indexRel)))
			continue;

		options = (OBTOptions *) indexRel->rd_options;
		if (indexRel->rd_rel->relam == BTREE_AM_OID &&
			!(options && !options->orioledb_index))
			continue;

		if (!indexInfo->ii_ReadyForInserts ||
			(!indexInfo->ii_Unique && indexInfo->ii_ExclusionOps == NULL))
			continue;

		/*
		 * Same refusal the loop over OrioleDB's own indexes makes: a named
		 * arbiter that is deferred cannot arbitrate anything.
		 */
		if (!indexRel->rd_index->indimmediate)
		{
			if (arbiterIndexes != NIL)
				ereport(ERROR,
						(errcode(ERRCODE_OBJECT_NOT_IN_PREREQUISITE_STATE),
						 errmsg("ON CONFLICT does not support deferrable unique constraints/exclusion constraints as arbiters"),
						 errtableconstraint(resultRelInfo->ri_RelationDesc,
											RelationGetRelationName(indexRel))));
			continue;
		}

		if (indexInfo->ii_Predicate != NIL)
		{
			ExprState  *predicate = indexInfo->ii_PredicateState;
			ExprContext *econtext = GetPerTupleExprContext(estate);

			if (predicate == NULL)
			{
				predicate = ExecPrepareQual(indexInfo->ii_Predicate, estate);
				indexInfo->ii_PredicateState = predicate;
			}
			econtext->ecxt_scantuple = slot;
			if (!ExecQual(predicate, econtext))
				continue;
		}

		result = lappend_oid(result, RelationGetRelid(indexRel));
	}

	return result;
}

from o_xact_redo_hook() on the builtin

	/*
	 * The transaction is settled, so it must not be settled a second time by
	 * a builtin commit record naming the same heap xid.  An oxid stays on
	 * joint_commit_list from its WAL_REC_JOINT_COMMIT until the builtin
	 * record arrives, and in that window it can perfectly well reach a finish
	 * record of its own: a subtransaction's joint commit is written long
	 * before the transaction ends, and the transaction may then abort.
	 * Deleting the current node here is safe for the dlist_foreach_modify()
	 * in o_xact_redo_hook(), which is the other caller.
	 */
	if (cur_recovery_xid_state->in_joint_commit_list)
	{
		dlist_delete_from_thoroughly(&joint_commit_list,
									 &cur_recovery_xid_state->joint_commit_list_node);
		cur_recovery_xid_state->in_joint_commit_list = false;
	}

static void
detoast_key_attrs(TupleTableSlot *slot, OTableDescr *descr)
{
	OTableSlot *oslot = (OTableSlot *) slot;
	OIndexDescr *id = GET_PRIMARY(descr);
	TupleDesc	tupleDesc = slot->tts_tupleDescriptor;
	int			i;
	int			ctid_off = id->primaryIsCtid ? 1 : 0;

	if (id->bridging)
		ctid_off++;

	for (i = 0; i < id->nonLeafTupdesc->natts; i++)
	{
		int			attnum = id->tableAttnums[i];
		int			attindex = attnum - 1 - ctid_off;
		Form_pg_attribute att;
		Datum		tmp;
		MemoryContext mctx;

		/* ctid and bridge ctid are not stored among the slot's values */
		if (attindex < 0 || attindex >= tupleDesc->natts)
			continue;

		att = TupleDescAttr(tupleDesc, attindex);
		if (slot->tts_isnull[attindex] || att->attlen != -1)
			continue;

		/*
		 * Only compressed and external values need expanding.  NOT
		 * VARATT_IS_EXTENDED(): that is also true of a short-header varlena,
		 * and rewriting those into 4-byte form would change the layout of
		 * every short key -- which shifted tuple sizes enough to alter
		 * row-lock and serialization outcomes in the isolation suite.
		 */
		if (!VARATT_IS_COMPRESSED(slot->tts_values[attindex]) &&
			!VARATT_IS_EXTERNAL(slot->tts_values[attindex]))
			continue;

		if (!oslot->vfree)
			alloc_to_toast_vfree_detoasted(slot);

		mctx = MemoryContextSwitchTo(slot->tts_mcxt);
		tmp = PointerGetDatum(PG_DETOAST_DATUM(slot->tts_values[attindex]));
		MemoryContextSwitchTo(mctx);
		if (oslot->vfree[attindex])
			pfree(DatumGetPointer(slot->tts_values[attindex]));
		slot->tts_values[attindex] = tmp;
		oslot->vfree[attindex] = true;
	}
}

static bool
prev_logical_xid_pushed_by(SubTransactionId subid)
{
	PrevLogicalXidEntry *entry;

	if (prevLogicalXids == NIL)
		return false;

	entry = (PrevLogicalXidEntry *) llast(prevLogicalXids);

	return entry != NULL && entry->subid == subid;
}

static Jsonb *
replay_record_stopevent_params(WalRecord *rec)
{
	JsonbParseState *state = NULL;
	Jsonb	   *res;
	int			sysTreeNum = -1;
	MemoryContext mctx = MemoryContextSwitchTo(stopevents_cxt);

	if (rec->type == WAL_REC_RELATION && IS_SYS_TREE_OIDS(rec->oids))
		sysTreeNum = rec->oids.relnode;

	pushJsonbValue(&state, WJB_BEGIN_OBJECT, NULL);
	jsonb_push_string_key(&state, "type", wal_type_name(rec->type));
	jsonb_push_int8_key(&state, "systree", sysTreeNum);
	res = JsonbValueToJsonb(pushJsonbValue(&state, WJB_END_OBJECT, NULL));
	MemoryContextSwitchTo(mctx);

	return res;
}

static inline int
o_tupdesc_fields_start(OTable *o_table)
{
	int			fields_start = o_table->has_primary ? 0 : 1;

	if (o_table->index_bridging)
		fields_start++;

	return fields_start;
}

static bool
o_tupdesc_matches_o_table(TupleDesc tupdesc, OTable *o_table)
{
	int			fields_start = o_tupdesc_fields_start(o_table);
	int			i;

	if (tupdesc->natts != o_table->nfields + fields_start)
		return false;

	for (i = 0; i < o_table->nfields; i++)
	{
		Form_pg_attribute att = TupleDescAttr(tupdesc, i + fields_start);
		OTableField *field = &o_table->fields[i];

		if (att->attbyval != field->byval || att->attlen != field->typlen)
			return false;
	}

	return true;
}

static bool
orioledb_debug_recovery_crash_lsn_check_hook(char **newval, void **extra,
											 GucSource source)
{
	if (strcmp(*newval, "") != 0)
	{
		XLogRecPtr	lsn;
		XLogRecPtr *myextra;
		bool		have_error = false;

		lsn = pg_lsn_in_internal(*newval, &have_error);
		if (have_error)
			return false;

		myextra = (XLogRecPtr *) guc_malloc(ERROR, sizeof(XLogRecPtr));
		*myextra = lsn;
		*extra = (void *) myextra;
	}
	return true;
}

static void
orioledb_debug_recovery_crash_lsn_assign_hook(const char *newval, void *extra)
{
	if (newval && strcmp(newval, "") != 0)
		debug_recovery_crash_lsn = *((XLogRecPtr *) extra);
}

bool
convert_fastpath_parent_to_img(OBTreeFindPageContext *context,
							   BTreePageItemLocator *locator)
{
	return convert_fastpath_locator_to_img(&context->parentPartial,
										   context->parentImg, locator);
}

static bool
convert_fastpath_target_to_img(OBTreeFindPageContext *context,
							   BTreePageItemLocator *locator)
{
	return convert_fastpath_locator_to_img(&context->partial,
										   context->img, locator);
}

void
assert_partial_chunk_loaded(PartialPageState *partial, Page img,
							BTreePageItemLocator *locator)
{
	BTreePageHeader *header = (BTreePageHeader *) img;
	LocationIndex chunkBegin,
				chunkEnd;

	/* Whole-page images have everything loaded by construction */
	if (partial == NULL || !partial->isPartial)
		return;

	/* An invalid locator is not going to be dereferenced */
	if (locator->chunk == NULL)
		return;

	/*
	 * A chunk which was never loaded holds whatever the image buffer happened
	 * to contain, so reading through such a locator is always wrong.
	 */
	Assert(locator->chunkOffset < BTREE_PAGE_MAX_CHUNKS);
	Assert(partial->chunkIsLoaded[locator->chunkOffset]);

	/*
	 * The chunk descriptors live in the hikeys chunk.  The fastpath descent
	 * loads a single data chunk without them (its locator comes from the
	 * fastpath hint instead), so the header-derived cross-checks below only
	 * apply once the hikeys chunk is there.
	 */
	if (!partial->hikeysChunkIsLoaded)
		return;

	Assert(header->chunksCount >= 1 &&
		   header->chunksCount <= BTREE_PAGE_MAX_CHUNKS);
	Assert(locator->chunkOffset < header->chunksCount);

	chunkBegin = SHORT_GET_LOCATION(header->chunkDesc[locator->chunkOffset].shortLocation);
	if (locator->chunkOffset + 1 < header->chunksCount)
		chunkEnd = SHORT_GET_LOCATION(header->chunkDesc[locator->chunkOffset + 1].shortLocation);
	else
		chunkEnd = header->dataSize;

	Assert(chunkBegin <= chunkEnd && chunkEnd <= ORIOLEDB_BLCKSZ);

	/*
	 * A locator addressing the live source page instead of the image is a
	 * different failure: the bytes are real, but they are read without the
	 * copy-then-validate protocol, so they can be torn.
	 */
	Assert((Pointer) locator->chunk == (Pointer) img + chunkBegin);

	/*
	 * An empty chunk (an empty page has one) gives a locator which is not
	 * valid: it is never dereferenced, so there is no item to check.
	 */
	if (locator->itemOffset < locator->chunkItemsCount)
		Assert(ITEM_GET_OFFSET(locator->chunk->items[locator->itemOffset]) <
			   chunkEnd - chunkBegin);
}

bool
try_lock_page_and_check(OInMemoryBlkno blkno, uint16 level,
						uint32 pageChangeCount)
{
	OPageWaiterShmemState *lockerState = &lockerStates[MYPROCNUMBER];
	uint64		prevState;
	int			extraWaits = 0;
	Page		p;

	/* Local pages do not need locking, but still validate the hint */
	if (O_PAGE_IS_LOCAL(blkno))
	{
		p = O_GET_IN_MEMORY_PAGE(blkno);
		return PAGE_GET_LEVEL(p) == level &&
			O_PAGE_GET_CHANGE_COUNT(p) == pageChangeCount;
	}

	Assert(get_my_locked_page_index(blkno) < 0);

	EA_LOCK_INC(blkno);

	while (true)
	{
		prevState = lock_page_or_queue(blkno, MYPROCNUMBER);

		if (!O_PAGE_STATE_IS_LOCKED(prevState))
			break;

		pgstat_report_wait_start(PG_WAIT_LWLOCK | LWTRANCHE_BUFFER_CONTENT);

		for (;;)
		{
			PGSemaphoreLock(MyProc->sem);
			if (lockerState->status == OPageWaitWakeUp)
				break;
			extraWaits++;
		}

		pgstat_report_wait_end();
	}

	my_locked_page_add(blkno, prevState | PAGE_STATE_LOCKED_FLAG);

	/*
	 * Fix the process wait semaphore's count for any absorbed wakeups.
	 */
	while (extraWaits-- > 0)
		PGSemaphoreUnlock(MyProc->sem);

	/*
	 * Now that we hold the lock, verify the page is still the one the caller
	 * expects.  A mismatch means the block was evicted and reused; bail out
	 * without applying any B-tree page invariants to it.
	 */
	p = O_GET_IN_MEMORY_PAGE(blkno);
	if (PAGE_GET_LEVEL(p) != level ||
		O_PAGE_GET_CHANGE_COUNT(p) != pageChangeCount)
	{
		unlock_page(blkno);
		return false;
	}

	return true;
}

void
reset_filling_descrs(void)
{
	if (filling_index_descr != NULL)
	{
		filling_index_descr->fill_in_progress = false;
		filling_index_descr = NULL;
	}
	if (filling_table_descr != NULL)
	{
		filling_table_descr->fill_in_progress = false;
		filling_table_descr = NULL;
	}
}

static RelFileLocator
o_bridge_marker_locator(Oid datoid, Oid tablespace, Oid relnode)
{
	RelFileLocator locator;

	locator.spcOid = OidIsValid(tablespace) ? tablespace : DEFAULTTABLESPACE_OID;
	locator.dbOid = (locator.spcOid == GLOBALTABLESPACE_OID) ? InvalidOid : datoid;
	locator.relNumber = relnode;

	return locator;
}

Oid
o_bridge_new_relnode(Oid tablespace, char relpersistence)
{
	RelFileLocator locator;
	SMgrRelation srel;
	Oid			spcOid;
	Oid			relnode;

	spcOid = OidIsValid(tablespace) ? tablespace : DEFAULTTABLESPACE_OID;
	relnode = GetNewRelFileNumber(spcOid, NULL, relpersistence);

	locator = o_bridge_marker_locator(MyDatabaseId, tablespace, relnode);
	srel = RelationCreateStorage(locator, relpersistence, true);
	smgrclose(srel);

	return relnode;
}

void
o_bridge_drop_relnode_marker(Oid datoid, Oid tablespace, Oid relnode)
{
	RelFileLocator locator = o_bridge_marker_locator(datoid, tablespace, relnode);
	SMgrRelation srel;

	srel = smgropen(locator, O_INVALID_PROCNUMBER);
	smgrdounlinkall(&srel, 1, false);
	smgrclose(srel);
}

BTreeDescr *
index_oids_get_btree_descr_cached(ORelOids oids)
{
	OIndexDescr *indexDescr;
	BTreeDescr *desc;

	indexDescr = get_cached_index_descr(oids);
	if (indexDescr == NULL)
		return NULL;

	desc = &indexDescr->desc;

	if (!o_btree_try_use_shmem(desc))
		return NULL;

	return desc;
}

bool
o_indices_move(OTable *table, OIndexNumber ixNum, Oid old_tablespace,
			   OXid oxid, CommitSeqNo csn)
{
	OIndex	   *oIndex;
	OIndex	   *oIndexOld;
	OIndexChunkKey oldKey;
	OIndexChunkKey newKey;
	bool		result;
	bool		wal = table->persistence != RELPERSISTENCE_TEMP;
	Pointer		data;
	int			len;
	BTreeDescr *sys_tree;

	/* `table` already carries the destination tablespace */
	oIndex = make_o_index(table, ixNum, OIndexVersionPass);
	Assert(oIndex->indexOids.spcoid != old_tablespace);

	oIndexOld = o_indices_get_extended(oIndex->indexOids,
									   oIndex->indexType,
									   default_table_fetch_context);
	if (oIndexOld)
	{
		oIndex->createOxid = oIndexOld->createOxid;
		free_o_index(oIndexOld);
	}
	data = serialize_o_index(oIndex, &len);

	oldKey.oids = oIndex->indexOids;
	oldKey.oids.spcoid = old_tablespace;
	oldKey.type = oIndex->indexType;
	oldKey.chunknum = 0;
	oldKey.version = oIndex->indexVersion;

	newKey = oldKey;
	newKey.oids.spcoid = oIndex->indexOids.spcoid;

	free_o_index(oIndex);

	systrees_modify_start();
	sys_tree = get_sys_tree(SYS_TREES_O_INDICES);
	(void) generic_toast_delete_optional_wal(&oIndicesToastAPI,
											 (Pointer) &oldKey, oxid, csn,
											 sys_tree, wal);
	result = generic_toast_insert_optional_wal(&oIndicesToastAPI,
											   (Pointer) &newKey, data, len,
											   oxid, csn, sys_tree, wal);
	systrees_modify_end(wal);

	pfree(data);

	return result;
}

void
o_move_latest_chkp_num(Oid datoid, Oid relnode, Oid old_tablespace,
					   Oid new_tablespace)
{
	OTuple		key_tuple,
				new_key_tuple,
				tuple,
				newTuple;
	SharedRootInfoKey key,
				new_key;
	ChkpNumTuple data;
	static BTreeModifyCallbackInfo callbackInfo =
	{
		.waitCallback = NULL,
		.modifyCallback = recovery_insert_overwrite_callback,
		.modifyDeletedCallback = NULL,
		.needsUndoForSelfCreated = false,
		.arg = NULL
	};
	BTreeDescr *desc = get_sys_tree(SYS_TREES_CHKP_NUM);
	OBTreeModifyResult result PG_USED_FOR_ASSERTS_ONLY;

	key.datoid = datoid;
	key.relnode = relnode;
	key.tablespace = old_tablespace;
	key_tuple.data = (Pointer) &key;
	key_tuple.formatFlags = 0;

	tuple = o_btree_find_tuple_by_key(desc, &key_tuple, BTreeKeyNonLeafKey,
									  &o_in_progress_snapshot, NULL,
									  CurrentMemoryContext, NULL);
	if (O_TUPLE_IS_NULL(tuple))
		return;

	data = *((ChkpNumTuple *) tuple.data);
	pfree(tuple.data);

	/* Remove the source-tablespace record and re-insert it verbatim. */
	o_delete_chkp_num(datoid, relnode, old_tablespace);

	new_key = key;
	new_key.tablespace = new_tablespace;
	data.key = new_key;
	new_key_tuple.data = (Pointer) &new_key;
	new_key_tuple.formatFlags = 0;
	newTuple.formatFlags = 0;
	newTuple.data = (Pointer) &data;

	result = o_btree_modify(desc, BTreeOperationInsert,
							newTuple, BTreeKeyLeafTuple,
							(Pointer) &new_key_tuple, BTreeKeyNonLeafKey,
							InvalidOXid, COMMITSEQNO_INPROGRESS,
							RowLockUpdate, NULL, &callbackInfo);
	Assert(result == OBTreeModifyResultInserted ||
		   result == OBTreeModifyResultUpdated);
}

void
o_move_tree_meta(Oid datoid, Oid relnode, Oid old_tablespace,
				 Oid new_tablespace)
{
	SharedRootInfoKey oldKey;
	SharedRootInfo *shared;
	EvictedTreeData *evicted;

	/*
	 * Move the tree's latest-checkpoint-number record so recovery finds the
	 * moved tree's map/tmp files under the destination tablespace.
	 */
	o_move_latest_chkp_num(datoid, relnode, old_tablespace, new_tablespace);

	oldKey.datoid = datoid;
	oldKey.relnode = relnode;
	oldKey.tablespace = old_tablespace;

	shared = o_find_shared_root_info(&oldKey);
	if (shared != NULL)
	{
		OTuple		tuple;
		bool		ok PG_USED_FOR_ASSERTS_ONLY;

		ok = o_drop_shared_root_info(datoid, relnode, old_tablespace);
		Assert(ok);

		shared->key.tablespace = new_tablespace;
		tuple.formatFlags = 0;
		tuple.data = (Pointer) shared;
		ok = o_btree_autonomous_insert(get_sys_tree(SYS_TREES_SHARED_ROOT_INFO),
									   tuple);
		Assert(ok);
		pfree(shared);
		return;
	}

	evicted = read_evicted_data(datoid, relnode, old_tablespace, true);
	if (evicted != NULL)
	{
		evicted->key.tablespace = new_tablespace;
		evicted->freeBuf.tag.key.oids.spcoid = new_tablespace;
		evicted->nextChkp.tag.key.oids.spcoid = new_tablespace;
		evicted->tmpBuf.tag.key.oids.spcoid = new_tablespace;
		insert_evicted_data(evicted);
	}
}

static void
o_index_expr_redirect_sql_funcs(ExprState *state)
{
	int			i;

	if (state == NULL || !o_is_syscache_hooks_set())
		return;

	for (i = 0; i < state->steps_len; i++)
	{
		ExprEvalStep *step = &state->steps[i];
		FmgrInfo   *finfo = NULL;

		switch (ExecEvalStepOp(state, step))
		{
			case EEOP_FUNCEXPR:
			case EEOP_FUNCEXPR_STRICT:
			case EEOP_FUNCEXPR_FUSAGE:
			case EEOP_FUNCEXPR_STRICT_FUSAGE:
#if PG_VERSION_NUM >= 180000
			case EEOP_FUNCEXPR_STRICT_1:
			case EEOP_FUNCEXPR_STRICT_2:
#endif
			case EEOP_DISTINCT:
			case EEOP_NOT_DISTINCT:
			case EEOP_NULLIF:
				finfo = step->d.func.finfo;
				break;
			default:
				break;
		}

		if (finfo != NULL && step->d.func.fn_addr == fmgr_sql)
		{
			/*
			 * ExecInterpExpr calls the cached step->d.func.fn_addr directly
			 * (the finfo indirection is bypassed for speed), so redirect that
			 * copy; keep finfo consistent too.  fn_extra is cleared because
			 * the SQLFunctionCache layout differs between fmgr_sql and
			 * o_fmgr_sql.
			 */
			step->d.func.fn_addr = o_fmgr_sql;
			finfo->fn_addr = o_fmgr_sql;
			finfo->fn_extra = NULL;
		}
	}
}

bool
o_proc_cache_delete_if_stale(Oid datoid, Oid procoid)
{
	XLogRecPtr	cur_lsn;
	OProc	   *o_proc;

	o_sys_cache_set_datoid_lsn(&cur_lsn, datoid == InvalidOid ? &datoid : NULL);
	o_proc = o_proc_cache_search(datoid, procoid, cur_lsn, proc_cache->nkeys);
	if (o_proc == NULL || !o_proc->node_format_stale)
		return false;

	o_proc_cache_delete(datoid, procoid);
	return true;
}

void
o_collect_funcexpr_refresh(Node *node)
{
	List	   *processed = NIL;

	if (!node)
		return;

	o_collect_funcs_refresh = true;
	PG_TRY();
	{
		expression_tree_walker(o_wrap_top_funcexpr(node), o_collect_function,
							   &processed);
	}
	PG_FINALLY();
	{
		o_collect_funcs_refresh = false;
	}
	PG_END_TRY();
	list_free_deep(processed);
}

static void
maybe_auto_upgrade_refresh(void)
{
	static bool attempted = false;

	if (attempted)
		return;

	if (checkpoint_state == NULL || !checkpoint_state->resetSysCaches)
		return;
	if (IsBinaryUpgrade ||
		RecoveryInProgress() ||
		!IsNormalProcessingMode() ||
		!IsTransactionState() ||
		!OidIsValid(MyDatabaseId))
		return;

	attempted = true;
	o_upgrade_refresh_database();
}

static void
maybe_auto_upgrade_refresh(void)
{
	static bool attempted = false;

	if (attempted)
		return;

	if (checkpoint_state == NULL || !checkpoint_state->resetSysCaches)
		return;
	if (IsBinaryUpgrade ||
		RecoveryInProgress() ||
		!IsNormalProcessingMode() ||
		!IsTransactionState() ||
		!OidIsValid(MyDatabaseId))
		return;

	attempted = true;
	o_upgrade_refresh_database();
}

