static void
o_refresh_table_expressions(Oid reloid)
{
	Relation	rel;
	ORelOids	oids;
	OTable	   *o_table;
	OXid		oxid;
	OSnapshot	oSnapshot;
	int			ix_num;

	rel = table_open(reloid, AccessExclusiveLock);
	if (!is_orioledb_rel(rel))
	{
		table_close(rel, AccessExclusiveLock);
		return;
	}

	ORelOidsSetFromRel(oids, rel);
	o_table = o_tables_get(oids);
	if (o_table == NULL)
	{
		table_close(rel, AccessExclusiveLock);
		return;
	}

	for (ix_num = 0; ix_num < o_table->nindices; ix_num++)
	{
		OTableIndex *index = &o_table->indices[ix_num];
		Relation	index_rel;

		/* ctid pseudo-index has no catalog relation */
		if (!OidIsValid(index->oids.reloid))
			continue;
		index_rel = index_open(index->oids.reloid, AccessShareLock);
		o_table_refresh_index_exprs(o_table, ix_num, index_rel);
		index_close(index_rel, AccessShareLock);
	}

	fill_current_oxid_osnapshot(&oxid, &oSnapshot);
	o_tables_rel_meta_lock(rel);
	for (ix_num = 0; ix_num < o_table->nindices; ix_num++)
	{
		int			ctid_idx_off = o_table->has_primary ? 0 : 1;
		OTableIndex *index = &o_table->indices[ix_num];

		o_indices_update(o_table, ix_num + ctid_idx_off, oxid, oSnapshot.csn);
		o_invalidate_oids(index->oids);
		o_add_invalidate_undo_item(index->oids, O_INVALIDATE_OIDS_ON_ABORT);
	}
	o_tables_update(o_table, oxid, oSnapshot.csn);
	o_tables_rel_meta_unlock(rel, InvalidOid);
	o_invalidate_oids(oids);
	o_add_invalidate_undo_item(oids, O_INVALIDATE_OIDS_ON_ABORT);

	o_table_free(o_table);
	table_close(rel, AccessExclusiveLock);
}

Datum
orioledb_upgrade_refresh(PG_FUNCTION_ARGS)
{
	Oid			orioledb_am = get_am_oid("orioledb", false);
	Relation	pgclass;
	SysScanDesc scan;
	HeapTuple	tup;
	List	   *reloids = NIL;
	ListCell   *lc;

	/* Collect the orioledb table OIDs first; refresh outside the scan. */
	pgclass = table_open(RelationRelationId, AccessShareLock);
	scan = systable_beginscan(pgclass, InvalidOid, false, NULL, 0, NULL);
	while (HeapTupleIsValid(tup = systable_getnext(scan)))
	{
		Form_pg_class cf = (Form_pg_class) GETSTRUCT(tup);

		if ((cf->relkind == RELKIND_RELATION ||
			 cf->relkind == RELKIND_MATVIEW) &&
			cf->relam == orioledb_am)
			reloids = lappend_oid(reloids, cf->oid);
	}
	systable_endscan(scan);
	table_close(pgclass, AccessShareLock);

	foreach(lc, reloids)
		o_refresh_table_expressions(lfirst_oid(lc));

	PG_RETURN_VOID();
}

static inline bool
o_node_version_compatible(int32 pg_version)
{
	return pg_version / 10000 == PG_VERSION_NUM / 10000;
}

static inline bool
o_node_str_is_empty(const char *node_str)
{
	return node_str[0] == '\0' || strcmp(node_str, "<>") == 0;
}

bool
o_table_refresh_index_exprs(OTable *o_table, OIndexNumber ix_num,
							Relation index_rel)
{
	OTableIndex *index = &o_table->indices[ix_num];
	MemoryContext mcxt,
				old_mcxt;
	ListCell   *lc;

	RelationGetIndexExpressions(index_rel);
	RelationGetIndexPredicate(index_rel);

	/* No node trees were persisted for this index: nothing to rewrite. */
	if (index_rel->rd_indexprs == NIL && index_rel->rd_indpred == NIL)
		return false;

	mcxt = OGetIndexContext(index);
	old_mcxt = MemoryContextSwitchTo(mcxt);

	index->predicate = (List *)
		expression_planner((Expr *) index_rel->rd_indpred);
	if (index->predicate)
		index->predicate_str =
			o_deparse_expression(nodeToString(index->predicate),
								 o_table->oids.reloid);

	index->expressions = NIL;
	foreach(lc, index_rel->rd_indexprs)
	{
		Expr	   *e = (Expr *) lfirst(lc);

		index->expressions = lappend(index->expressions,
									 expression_planner(e));
	}

	MemoryContextSwitchTo(old_mcxt);
	return true;
}

static bool
sys_tree_reset_on_major_upgrade(int tree_num)
{
	return tree_num == SYS_TREES_DATABASE_CACHE;
}

static Jsonb *
prepare_merge_before_free_extent_params(BTreeDescr *desc, int level, uint32 checkpoint_num, bool extent)
{
	JsonbParseState *state = NULL;
	Jsonb	   *res;
	MemoryContext mctx = MemoryContextSwitchTo(stopevents_cxt);

	pushJsonbValue(&state, WJB_BEGIN_OBJECT, NULL);
	btree_desc_stopevent_params_internal(desc, &state);
	jsonb_push_int8_key(&state, "level", level);
	jsonb_push_int8_key(&state, "checkpointNum", checkpoint_num);
	jsonb_push_bool_key(&state, "hadExtent", extent);
	res = JsonbValueToJsonb(pushJsonbValue(&state, WJB_END_OBJECT, NULL));
	MemoryContextSwitchTo(mctx);

	return res;
}

static void
apply_deferred_checkpoint_undo(void)
{
	dlist_mutable_iter miter;
	OXid		saved_recovery_oxid = recovery_oxid;
	bool		saved_oxid_needs_wal_flush = oxid_needs_wal_flush;
	UndoStackLocations saved_undo_locations[(int) UndoLogsCount];
	int			j;

	if (dlist_is_empty(&deferred_checkpoint_undo))
		return;

	for (j = 0; j < (int) UndoLogsCount; j++)
		get_cur_undo_locations(&saved_undo_locations[j], (UndoLogType) j);

	dlist_foreach_modify(miter, &deferred_checkpoint_undo)
	{
		DeferredCheckpointUndo *d = dlist_container(DeferredCheckpointUndo,
													node, miter.cur);
		UndoLogType undoType = (UndoLogType) d->kind;

		recovery_oxid = d->oxid;
		oxid_needs_wal_flush = d->needs_wal_flush;
		set_cur_undo_locations(undoType, d->undoStack);
		if (d->flush_undo_pos)
			flush_current_undo_stack();
		if (COMMITSEQNO_IS_ABORTED(d->csn))
		{
			if (d->parentSubid == InvalidSubTransactionId)
				apply_undo_stack(undoType, recovery_oxid, NULL, false);
			else
				rollback_to_savepoint(undoType, UndoStackHead,
									  d->parentSubid, false);
		}
		else
		{
			precommit_undo_stack(undoType, recovery_oxid, false);
			on_commit_undo_stack(undoType, recovery_oxid, false);
		}
		dlist_delete(miter.cur);
		pfree(d);
	}

	for (j = 0; j < (int) UndoLogsCount; j++)
		set_cur_undo_locations((UndoLogType) j, saved_undo_locations[j]);
	recovery_oxid = saved_recovery_oxid;
	oxid_needs_wal_flush = saved_oxid_needs_wal_flush;
}

static bool
recovery_apply_systree_modify(int sys_tree_num, uint16 type, OTuple tuple,
							  OXid oxid, XLogRecPtr xlogPtr, bool single)
{
	bool		success;

	if (!single)
		workers_synchronize(xlogPtr, true);

	success = apply_sys_tree_modify_record(sys_tree_num, type, tuple, oxid,
										   COMMITSEQNO_INPROGRESS);

	if (sys_tree_num == SYS_TREES_O_INDICES && success)
	{
		OIndexKey  *trees = NULL;
		ORelOids	tmp_oids;

		if (type == RecoveryMsgTypeDelete)
		{
			trees = o_indices_get_trees(tuple.data, &tmp_oids);
			if (trees)
				add_undo_drop_relnode(tmp_oids, trees, 1);
		}
		else if (type == RecoveryMsgTypeInsert)
		{
			trees = o_indices_get_trees(tuple.data, &tmp_oids);
			if (trees)
			{
				char	   *prefix;
				char	   *db_prefix;

				o_get_prefixes_for_tablespace(trees->oids.datoid,
											  trees->tablespace,
											  &prefix, &db_prefix);
				o_verify_dir_exists_or_create(prefix, NULL, NULL);
				o_verify_dir_exists_or_create(db_prefix, NULL, NULL);
				pfree(db_prefix);
				add_undo_create_relnode(tmp_oids, trees, 1, true);
			}
		}
	}

	return success;
}

static void
o_bt_array_set_low_or_high(Relation rel, ScanKey skey, BTArrayKeyInfo *array,
						   bool low_not_high)
{
	Assert(skey->sk_flags & SK_SEARCHARRAY);

	if (array->num_elems != -1)
	{
		int			set_elem = 0;

		Assert(!(skey->sk_flags & SK_BT_SKIP));

		if (!low_not_high)
			set_elem = array->num_elems - 1;

		array->cur_elem = set_elem;
		skey->sk_argument = array->elem_values[set_elem];
		return;
	}

	Assert(skey->sk_flags & SK_BT_SKIP);
	Assert(array->num_elems == -1);

	if (!array->attbyval && skey->sk_argument)
		pfree(DatumGetPointer(skey->sk_argument));

	skey->sk_argument = (Datum) 0;
	skey->sk_flags &= ~(SK_SEARCHNULL | SK_ISNULL |
						SK_BT_MINVAL | SK_BT_MAXVAL |
						SK_BT_NEXT | SK_BT_PRIOR);

	if (array->null_elem &&
		(low_not_high == ((skey->sk_flags & SK_BT_NULLS_FIRST) != 0)))
		skey->sk_flags |= (SK_SEARCHNULL | SK_ISNULL);
	else if (low_not_high)
		skey->sk_flags |= SK_BT_MINVAL;
	else
		skey->sk_flags |= SK_BT_MAXVAL;
}

static void
o_bt_skiparray_set_element_from_tuple(ScanKey skey, BTArrayKeyInfo *array,
									  Datum tupdatum, bool tupnull)
{
	Assert(skey->sk_flags & SK_BT_SKIP);
	Assert(skey->sk_flags & SK_SEARCHARRAY);
	Assert(array->num_elems == -1);

	if (tupnull)
	{
		Assert(array->null_elem);

		if (!array->attbyval && skey->sk_argument)
			pfree(DatumGetPointer(skey->sk_argument));
		skey->sk_argument = (Datum) 0;
		skey->sk_flags &= ~(SK_BT_MINVAL | SK_BT_MAXVAL |
							SK_BT_NEXT | SK_BT_PRIOR);
		skey->sk_flags |= (SK_SEARCHNULL | SK_ISNULL);
		return;
	}

	if (!array->attbyval && skey->sk_argument)
		pfree(DatumGetPointer(skey->sk_argument));
	skey->sk_flags &= ~(SK_SEARCHNULL | SK_ISNULL |
						SK_BT_MINVAL | SK_BT_MAXVAL |
						SK_BT_NEXT | SK_BT_PRIOR);
	skey->sk_argument = datumCopy(tupdatum, array->attbyval, array->attlen);
}

static bool
o_skip_arrays_observe_tuple(OIndexDescr *indexDescr, OScanState *ostate,
							OTuple tup)
{
	IndexScanDesc scan = &ostate->scandesc;
	BTScanOpaque so = (BTScanOpaque) scan->opaque;
	bool		transitioned = false;

	if (so->numArrayKeys == 0)
		return false;

	for (int i = 0; i < so->numArrayKeys; i++)
	{
		BTArrayKeyInfo *array = &so->arrayKeys[i];
		ScanKey		skey = &so->keyData[array->scan_key];
		AttrNumber	attnum;
		Datum		value;
		bool		isnull;

		if (!(skey->sk_flags & SK_BT_SKIP))
			continue;

		/* Only act on a skip array that is in sentinel or transition. */
		if (!(skey->sk_flags &
			  (SK_BT_MINVAL | SK_BT_MAXVAL | SK_ISNULL |
			   SK_BT_NEXT | SK_BT_PRIOR)))
			continue;

		attnum = OIndexKeyAttnumToTupleAttnum(BTreeKeyLeafTuple, indexDescr,
											  skey->sk_attno);
		value = o_fastgetattr(tup, attnum, indexDescr->leafTupdesc,
							  &indexDescr->leafSpec, &isnull);

		/*
		 * Don't transition on a NULL leading-column value.  Pinning
		 * sk_argument to NULL via set_element_from_tuple lands the skip array
		 * in the SK_ISNULL state, which is flag-indistinguishable from the
		 * initial sentinel-NULL state that _bt_start_array_keys uses for
		 * nulls-last + null_elem=true.  Without a way to tell those apart,
		 * o_key_data_to_key_range falls back to the broad range -- which
		 * would re-open the same iterator and re-emit the same NULL-leading
		 * tuple, infinite-looping.  Leave the array in its current
		 * (transition or sentinel) state and let the active iterator continue
		 * from this position, emitting any further NULL-leading tuples that
		 * match the trailing predicates and then exhausting.  Skip-scan
		 * optimization is forfeited for the NULL band, but correctness is
		 * preserved.
		 */
		if (isnull)
			continue;

		o_bt_skiparray_set_element_from_tuple(skey, array, value, isnull);
		transitioned = true;
	}

	return transitioned;
}

static const OPkFixedType *
o_pk_fixed_lookup(Oid typeoid)
{
	int			i;

	for (i = 0; i < lengthof(o_pk_fixed_types); i++)
		if (o_pk_fixed_types[i].typeoid == typeoid)
			return &o_pk_fixed_types[i];
	return NULL;
}

static GByteArray *
fu_synaptics_rmi_mock_device_read(FuSynapticsRmiDevice *device,
				  guint16 addr,
				  gsize req_sz,
				  GError **error)
{
	FuSynapticsRmiMockDevice *self = FU_SYNAPTICS_RMI_MOCK_DEVICE(device);
	const guint8 *src = pdt_end;

	if (self->scan_round == 0) {
		if (addr == 0x00e9)
			src = pdt_f34;
		else if (addr == 0x00e3)
			src = pdt_f01;
	} else if (self->scan_round == 1) {
		if (addr == 0x00e9)
			src = pdt_f34;
	} else if (self->scan_round == 2) {
		if (addr == 0x00e9)
			src = pdt_f01;
	}
	return g_byte_array_new_take(g_memdup2(src, req_sz), req_sz);
}

