static void
fu_synaptics_rmi_device_pdt_rescan_func(void)
{
	gboolean ret;
	g_autoptr(FuContext) ctx = fu_context_new();
	g_autoptr(FuSynapticsRmiMockDevice) device =
	    g_object_new(FU_TYPE_SYNAPTICS_RMI_MOCK_DEVICE, "context", ctx, NULL);
	g_autoptr(GError) error = NULL;

	fu_synaptics_rmi_device_set_max_page(FU_SYNAPTICS_RMI_DEVICE(device), 1);

	/* initial PDT has both F34 and F01 */
	ret = fu_synaptics_rmi_device_scan_pdt(FU_SYNAPTICS_RMI_DEVICE(device), &error);
	g_assert_no_error(error);
	g_assert_true(ret);

	/* caches F01 in round 0 */
	ret = fu_synaptics_rmi_device_reset(FU_SYNAPTICS_RMI_DEVICE(device), &error);
	g_assert_no_error(error);
	g_assert_true(ret);

	/* caches F34 in round 0 */
	ret = fu_synaptics_rmi_device_wait_for_idle(FU_SYNAPTICS_RMI_DEVICE(device),
						    0,
						    FU_SYNAPTICS_RMI_DEVICE_WAIT_FOR_IDLE_FLAG_NONE,
						    &error);
	g_assert_no_error(error);
	g_assert_true(ret);

	/* the device drops F01 and we rescan: cached functions are freed & refreshed */
	device->scan_round = 1;
	ret = fu_synaptics_rmi_device_scan_pdt(FU_SYNAPTICS_RMI_DEVICE(device), &error);
	g_assert_no_error(error);
	g_assert_true(ret);

	/* must fail cleanly with NOT_SUPPORTED rather than dereferencing freed/NULL F01 */
	ret = fu_synaptics_rmi_device_disable_irqs(FU_SYNAPTICS_RMI_DEVICE(device), &error);
	g_assert_error(error, FWUPD_ERROR, FWUPD_ERROR_NOT_SUPPORTED);
	g_assert_false(ret);

	/* the device drops F34 and keeps F01 on next rescan */
	g_clear_error(&error);
	device->scan_round = 2;
	ret = fu_synaptics_rmi_device_scan_pdt(FU_SYNAPTICS_RMI_DEVICE(device), &error);
	g_assert_no_error(error);
	g_assert_true(ret);

	/* must fail cleanly with NOT_SUPPORTED rather than dereferencing freed/NULL F34 */
	ret = fu_synaptics_rmi_device_disable_irqs(FU_SYNAPTICS_RMI_DEVICE(device), &error);
	g_assert_error(error, FWUPD_ERROR, FWUPD_ERROR_NOT_SUPPORTED);
	g_assert_false(ret);
}

static void
fu_lenovo_accessory_ble_device_finalize(GObject *object)
{
	FuLenovoAccessoryBleDevice *self = FU_LENOVO_ACCESSORY_BLE_DEVICE(object);
	if (self->notify_io != NULL)
		g_object_unref(self->notify_io);
	G_OBJECT_CLASS(fu_lenovo_accessory_ble_device_parent_class)->finalize(object);
}

static gboolean
fu_lenovo_accessory_hid_dual_device_set_quirk_kv(FuDevice *device,
						 const gchar *key,
						 const gchar *value,
						 GError **error)
{
	FuLenovoAccessoryHidDualDevice *self = FU_LENOVO_ACCESSORY_HID_DUAL_DEVICE(device);
	guint64 tmp = 0;

	if (g_strcmp0(key, "LenovoAccessoryInterface") == 0) {
		if (!fu_strtoull(value, &tmp, 0, G_MAXUINT8, FU_INTEGER_BASE_AUTO, error))
			return FALSE;
		fu_hid_device_set_interface(FU_HID_DEVICE(self), (guint8)tmp);
		return TRUE;
	}

	/* failed */
	g_set_error_literal(error,
			    FWUPD_ERROR,
			    FWUPD_ERROR_NOT_SUPPORTED,
			    "quirk key not supported");
	return FALSE;
}

static void
fu_device_event_copy_data_func(void)
{
	gboolean ret;
	gsize actual_length = 0;
	guint8 buf[8] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF};
	const guint8 data[4] = {0x11, 0x22, 0x33, 0x44};
	g_autoptr(FuDeviceEvent) event = fu_device_event_new("foo:bar:baz");
	g_autoptr(GError) error = NULL;

	fu_device_event_set_data(event, "Data", data, sizeof(data));

	/* copy 4-byte recorded event into an 8-byte buffer */
	ret = fu_device_event_copy_data(event, "Data", buf, sizeof(buf), &actual_length, &error);
	g_assert_no_error(error);
	g_assert_true(ret);
	g_assert_cmpint(actual_length, ==, 4);

	/* verify payload copied correctly */
	g_assert_cmpint(buf[0], ==, 0x11);
	g_assert_cmpint(buf[1], ==, 0x22);
	g_assert_cmpint(buf[2], ==, 0x33);
	g_assert_cmpint(buf[3], ==, 0x44);

	/* verify the tail was zeroed rather than retaining 0xFF */
	g_assert_cmpint(buf[4], ==, 0x00);
	g_assert_cmpint(buf[5], ==, 0x00);
	g_assert_cmpint(buf[6], ==, 0x00);
	g_assert_cmpint(buf[7], ==, 0x00);
}

static unsigned char
stream_byte (size_t i)
{
  return (unsigned char) ((i * 7 + 3) & 0xFF);
}

static int
rb_test_write_all (int fd, const unsigned char *buf, size_t n)
{
  size_t off = 0;
  while (off < n)
    {
      ssize_t r = write (fd, buf + off, n - off);
      if (r <= 0)
        return -1;
      off += (size_t) r;
    }
  return 0;
}

static int
rb_test_read_all (int fd, unsigned char *buf, size_t n)
{
  size_t off = 0;
  while (off < n)
    {
      ssize_t r = read (fd, buf + off, n - off);
      if (r <= 0)
        return -1;
      off += (size_t) r;
    }
  return 0;
}

static int
rb_test_discard (int fd, size_t n, unsigned char *scratch, size_t scratch_size)
{
  while (n > 0)
    {
      size_t chunk = n > scratch_size ? scratch_size : n;
      if (rb_test_read_all (fd, scratch, chunk) < 0)
        return -1;
      n -= chunk;
    }
  return 0;
}

static int
test_ring_buffer_stress_partial_drain ()
{
  long page_size = sysconf (_SC_PAGESIZE);

  if (page_size < 0)
    {
      fprintf (stderr, "failed to get page size\n");
      return 1;
    }

  size_t caps[] = { 4097, 6000, 8192, 8193, 12000, 16384,
                    (size_t) page_size, (size_t) page_size + 1 };
  size_t i;

  for (i = 0; i < sizeof (caps) / sizeof (caps[0]); i++)
    {
      int ret = do_stress_ring_buffer_partial_drain (caps[i]);
      if (ret != 0)
        return ret;
    }
  return 0;
}

static int
run_in_container_namespace (libcrun_container_status_t *status, int (*callback) (void *, libcrun_error_t *), void *arg, libcrun_error_t *err)
{
  cleanup_close int pidfd = -1;
  pid_t pid = status->pid;
  int ret;

  pidfd = syscall_pidfd_open (pid, 0);
  if (UNLIKELY (pidfd < 0))
    return crun_make_error (err, errno, "pidfd_open");

  /* Check if the container is still running after opening the pidfd.  */
  ret = libcrun_is_container_running (status, err);
  if (UNLIKELY (ret < 0))
    return ret;

  if (ret == 0)
    return crun_make_error (err, 0, "container not running");

  return run_callback_in_namespace (pidfd, callback, arg, err);
}

static int
setup_network_device_in_ns (char *buffer, size_t buffer_size, int netns_fd, const char *newifname,
                            struct ip_addr *ips, libcrun_error_t *err)

int
move_network_device (const char *ifname, const char *newifname, int netns_fd, libcrun_error_t *err)
{
  const size_t buffer_size = 8192;
  cleanup_ip_addrs struct ip_addr *ips = NULL;
  cleanup_free char *buffer = xmalloc (buffer_size);
  cleanup_close int sock = -1;
  int ifindex;
  int ret;

  sock = open_netlink_fd (err);
  if (sock < 0)
    return sock;

  ifindex = name_to_index (sock, ifname, buffer, buffer_size, err);
  if (UNLIKELY (ifindex < 0))
    return ifindex;

  ret = get_ip_addresses (sock, ifindex, &ips, buffer, buffer_size, err);
  if (UNLIKELY (ret < 0))
    return ret;

  /* Move the device to the target network namespace.  */
  ret = do_move_link_to_ns_and_wait (sock, buffer, buffer_size, ifindex, netns_fd, newifname, err);
  if (UNLIKELY (ret < 0))
    return ret;

  return setup_network_device_in_ns (buffer, buffer_size, netns_fd, newifname, ips, err);
}

static char *
parse_cgroup_subsystem (char *line, char **subpath_out)
{
  char *subsystem, *subpath, *it;

  subsystem = strchr (line, ':') + 1;
  subpath = strchr (subsystem, ':') + 1;
  *(subpath - 1) = '\0';

  if (subsystem[0] == '\0')
    return NULL;

  it = strstr (subsystem, "name=");
  if (it)
    subsystem = it + 5;

  if (strcmp (subsystem, "net_prio,net_cls") == 0)
    subsystem = "net_cls,net_prio";
  if (strcmp (subsystem, "cpuacct,cpu") == 0)
    subsystem = "cpu,cpuacct";

  if (subpath_out)
    *subpath_out = subpath;
  return subsystem;
}

static int
setup_criu_work_dir (libcrun_checkpoint_restore_t *cr_options, int *work_fd_out, libcrun_error_t *err)
{
  int work_fd;

  if (cr_options->work_path == NULL)
    {
      /* This is only for the error message later. */
      cr_options->work_path = cr_options->image_path;
      return 0;
    }

  if (UNLIKELY ((mkdir (cr_options->work_path, 0700) == -1) && (errno != EEXIST)))
    return crun_make_error (err, errno, "error creating CRIU work directory `%s`", cr_options->work_path);

  work_fd = open (cr_options->work_path, O_DIRECTORY | O_CLOEXEC);
  if (UNLIKELY (work_fd == -1))
    return crun_make_error (err, errno, "error opening CRIU work directory `%s`", cr_options->work_path);

  libcriu_wrapper->criu_set_work_dir_fd (work_fd);
  *work_fd_out = work_fd;
  return 0;
}

static int
stat_optional_device (const char *path, struct stat *st, bool *present, libcrun_error_t *err)
{
  int ret = stat (path, st);
  if (UNLIKELY (ret < 0))
    {
      if (errno != ENOENT)
        return crun_make_error (err, errno, "stat `%s`", path);
      *present = false;
    }
  return 0;
}

static bool
spec_has_device (runtime_spec_schema_config_schema *def, const char *path)
{
  size_t i;

  for (i = 0; i < def->linux->devices_len; i++)
    if (strcmp (def->linux->devices[i]->path, path) == 0)
      return true;
  return false;
}

static int
cleanup_sd_bus_and_return (sd_bus *bus, sd_bus_message *m, sd_bus_message *reply,
                           sd_bus_error *error, int ret)
{
  if (bus)
    sd_bus_unref (bus);
  if (m)
    sd_bus_message_unref (m);
  if (reply)
    sd_bus_message_unref (reply);
  sd_bus_error_free (error);
  return ret;
}

static int
compute_finalized_path (char **path, const char *from, const char *suffix, libcrun_error_t *err)
{
  if (suffix == NULL)
    {
      *path = xstrdup (from);
      return 0;
    }
  return append_paths (path, err, from, suffix, NULL);
}

static void
append_to_string_array (char ***arr, size_t *size, const char *arg)
{
  *arr = xrealloc (*arr, (*size + 2) * sizeof (**arr));
  (*arr)[*size + 1] = NULL;
  (*arr)[*size] = xstrdup (arg);
  (*size)++;
}

static int
open_seccomp_bpf_dirfd (libcrun_container_t *container, char **rel_path, libcrun_error_t *err)
{
  int ret;
  int dirfd;

  dirfd = open_rundir_dirfd (container->context ? container->context->state_root : NULL, err);
  if (UNLIKELY (dirfd < 0))
    return dirfd;

  /* relative path to dirfd.  */
  ret = append_paths (rel_path, err, container->context->id, "seccomp.bpf", NULL);
  if (UNLIKELY (ret < 0))
    {
      TEMP_FAILURE_RETRY (close (dirfd));
      return ret;
    }

  return dirfd;
}

static int
schedule_or_do_remount (libcrun_container_t *container, int *fd, int targetfd,
                        const char *target, const char *real_target,
                        bool single_instance, unsigned long mountflags,
                        const void *data, int extra_flags, libcrun_error_t *err)
{
  unsigned long remount_flags = MS_REMOUNT | (single_instance ? 0 : MS_BIND) | (mountflags & ~ALL_PROPAGATIONS);
  struct remount_s *r;

  if ((remount_flags & MS_RDONLY) == 0 || (extra_flags & MOUNT_NO_DEFERRED_REMOUNT))
    return do_remount (*fd >= 0 ? *fd : targetfd, real_target, remount_flags, data, err);

  if (*fd < 0)
    {
      *fd = dup (targetfd);
      if (UNLIKELY (*fd < 0))
        return crun_make_error (err, errno, "dup `%d`", targetfd);
    }

  /* The remount owns the fd.  */
  r = make_remount (get_and_reset (fd), target, remount_flags, data, get_private_data (container)->remounts);
  get_private_data (container)->remounts = r;

  return 0;
}

static void
apply_selinux_xattr (libcrun_container_t *container, int fd, int extra_flags, const char *label)
{
  libcrun_error_t tmp_err = NULL;
  int procfd;

  if ((extra_flags & LABEL_MASK) != LABEL_XATTR)
    return;

  /* Best-effort: swallow any error so it does not leak into the caller.  */
  procfd = get_procfd (get_private_data (container), &tmp_err);
  if (procfd >= 0)
    {
      proc_fd_path_t proc_self_path;
      cleanup_close int xfd = -1;

      get_self_fd_path (proc_self_path, fd);
      xfd = openat (procfd, proc_self_path, O_RDONLY | O_CLOEXEC);
      if (xfd >= 0)
        (void) fsetxattr (xfd, "security.selinux", label, strlen (label), 0);
    }
  crun_error_release (&tmp_err);
}

static int
do_mount_replace_rootfs (libcrun_container_t *container, int *fd, libcrun_error_t *err)
{
  int procfd = get_procfd (get_private_data (container), err);
  int tmp;
  int ret;

  if (UNLIKELY (procfd < 0))
    return procfd;

  {
    cleanup_close int nsfd = openat (procfd, "self/ns/mnt", O_RDONLY | O_CLOEXEC);
    if (UNLIKELY (nsfd < 0))
      return crun_make_error (err, errno, "open `/proc/self/ns/mnt`");

    ret = setns (nsfd, CLONE_NEWNS);
    if (UNLIKELY (ret < 0))
      return crun_make_error (err, errno, "setns `CLONE_NEWNS`");
  }

  close_and_reset (fd);
  *fd = open (get_private_data (container)->rootfs, O_PATH | O_CLOEXEC);
  if (UNLIKELY (*fd < 0))
    return crun_make_error (err, errno, "reopen rootfs after mount on /");

  tmp = dup (*fd);
  if (UNLIKELY (tmp < 0))
    return crun_make_error (err, errno, "dup");

  TEMP_FAILURE_RETRY (close (get_private_data (container)->rootfsfd));
  get_private_data (container)->rootfsfd = tmp;

  return 0;
}

static int
apply_propagation_flags (const char *target, int targetfd, const char *real_target,
                         unsigned long mountflags, libcrun_error_t *err)
{
  bool propagation_done = false;
  int ret;

  if (targetfd >= 0)
    {
      libcrun_error_t tmp_err = NULL;
      ret = do_mount_setattr (false, target, targetfd, 0, mountflags & ALL_PROPAGATIONS, &tmp_err);
      if (LIKELY (ret == 0))
        propagation_done = true;
      else
        crun_error_release (&tmp_err);
    }

  if (! propagation_done)
    {
      ret = mount (NULL, real_target, NULL, mountflags & ALL_PROPAGATIONS, NULL);
      if (UNLIKELY (ret < 0))
        return crun_make_error (err, errno, "set propagation for `%s`", target);
    }

  return 0;
}

static void
preopen_needed_devs_and_notify (libcrun_container_t *container)
{
  struct private_data_s *private_data = get_private_data (container);
  size_t i;

  if (private_data->needed_devs_fds)
    {
      struct libcrun_fd_map *dev_fds = private_data->needed_devs_fds;

      for (i = 0; needed_devs[i].path; i++)
        {
          if (i < dev_fds->nfds && dev_fds->fds[i] >= 0)
            continue;

          int fd = syscall_open_tree (AT_FDCWD, needed_devs[i].path,
                                      OPEN_TREE_CLONE | OPEN_TREE_CLOEXEC);
          if (fd >= 0 && i < dev_fds->nfds)
            dev_fds->fds[i] = fd;
          else if (fd >= 0)
            close (fd);
        }
    }

  if (private_data->notify_socket_tree_fd < 0
      && private_data->host_notify_socket_path)
    {
      int fd = syscall_open_tree (AT_FDCWD, private_data->host_notify_socket_path,
                                  OPEN_TREE_CLONE | AT_RECURSIVE | OPEN_TREE_CLOEXEC);
      if (fd >= 0)
        private_data->notify_socket_tree_fd = fd;
    }
}

static int
write_id_map (libcrun_container_t *container, pid_t pid, const char *map_name,
              int (*idmap_helper) (pid_t, const char *, libcrun_error_t *), const char *helper_name,
              bool warn_on_failure, const char *map, size_t map_len,
              runtime_spec_schema_defs_id_mapping **mappings, size_t mappings_len,
              uint32_t host_id, uint32_t container_id, bool skip_if_setgroups_denied,
              libcrun_error_t *err)
{
  int ret = 0;

  if (container->host_uid)
    ret = idmap_helper (pid, map, err);
  if (container->host_uid == 0 || ret < 0)
    {
      cleanup_close int fd = -1;

      if (ret < 0)
        {
          if (warn_on_failure)
            libcrun_warning ("unable to invoke `%s`, will try creating a user namespace with single mapping as an alternative", helper_name);
          crun_error_release (err);
        }

      fd = libcrun_open_proc_pid_file (container, pid, map_name, O_WRONLY, err);
      if (UNLIKELY (fd < 0))
        return fd;

      ret = safe_write (fd, map_name, map, map_len, err);
      if (ret < 0 && (! mappings_len || is_single_mapping (mappings, mappings_len, host_id, container_id)))
        {
          size_t single_mapping_len;
          cleanup_free char *single_mapping = NULL;
          crun_error_release (err);

          if (! skip_if_setgroups_denied || ! get_private_data (container)->deny_setgroups)
            {
              ret = deny_setgroups (container, pid, err);
              if (UNLIKELY (ret < 0))
                return ret;
            }

          ret = format_mount_mapping (&single_mapping, container_id, host_id, 1, &single_mapping_len, err);
          if (UNLIKELY (ret < 0))
            return ret;

          close_and_reset (&fd);

          fd = libcrun_open_proc_pid_file (container, pid, map_name, O_WRONLY, err);
          if (UNLIKELY (fd < 0))
            return fd;

          ret = safe_write (fd, map_name, single_mapping, single_mapping_len, err);
        }
    }
  return ret;
}

