static void
write_error_to_pipe (int fd, libcrun_error_t *err)
{
  const char *msg = (*err)->msg;
  int errcode = crun_error_get_errno (err);

  TEMP_FAILURE_RETRY (write (fd, &errcode, sizeof (errcode)));
  TEMP_FAILURE_RETRY (write (fd, msg, strlen (msg) + 1));
}

