static int
install_filter (void)
{
  struct sock_filter filter[] = {
    /* Load the syscall number.  */
    BPF_STMT (BPF_LD | BPF_W | BPF_ABS, offsetof (struct seccomp_data, nr)),
    /* If it is not openat2, allow it.  */
    BPF_JUMP (BPF_JMP | BPF_JEQ | BPF_K, __NR_openat2, 0, 1),
    BPF_STMT (BPF_RET | BPF_K, SECCOMP_RET_ERRNO | (ENOSYS & SECCOMP_RET_DATA)),
    BPF_STMT (BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
  };
  struct sock_fprog prog = {
    .len = (unsigned short) (sizeof (filter) / sizeof (filter[0])),
    .filter = filter,
  };

  if (syscall (__NR_seccomp, SECCOMP_SET_MODE_FILTER, 0, &prog) == 0)
    return 0;

  /* Without CAP_SYS_ADMIN the filter can only be installed after
     NO_NEW_PRIVS is set.  */
  if (errno != EACCES)
    return -1;

  if (prctl (PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) < 0)
    return -1;

  return syscall (__NR_seccomp, SECCOMP_SET_MODE_FILTER, 0, &prog);
}

int
main (int argc, char **argv)
{
  if (argc < 2)
    {
      fprintf (stderr, "usage: %s COMMAND [ARGS...]\n", argv[0]);
      return 2;
    }

  if (install_filter () < 0)
    {
      fprintf (stderr, "%s: cannot install seccomp filter: %s\n", argv[0], strerror (errno));
      return 2;
    }

  execvp (argv[1], argv + 1);

  fprintf (stderr, "%s: exec `%s`: %s\n", argv[0], argv[1], strerror (errno));
  return 127;
}

static int
make_symlink_tree (char *root, size_t root_size)
{
  char path[PATH_MAX];
  char *tmpdir;
  int fd;

  if (snprintf (root, root_size, "%s/crun-chroot-realpath-XXXXXX",
                getenv ("TMPDIR") ? getenv ("TMPDIR") : "/tmp")
      >= (int) root_size)
    return 77;

  tmpdir = mkdtemp (root);
  if (tmpdir == NULL)
    return 77;

  snprintf (path, sizeof (path), "%s/file", root);
  fd = creat (path, 0600);
  if (fd < 0)
    return 77;
  close (fd);

  snprintf (path, sizeof (path), "%s/link", root);
  if (symlink ("file", path) < 0)
    return 77;

  snprintf (path, sizeof (path), "%s/dir", root);
  if (mkdir (path, 0700) < 0)
    return 77;

  snprintf (path, sizeof (path), "%s/dir/file", root);
  fd = creat (path, 0600);
  if (fd < 0)
    return 77;
  close (fd);

  snprintf (path, sizeof (path), "%s/dir/link", root);
  if (symlink ("file", path) < 0)
    return 77;

  snprintf (path, sizeof (path), "%s/dir/up", root);
  if (symlink ("../file", path) < 0)
    return 77;

  snprintf (path, sizeof (path), "%s/dir/abs", root);
  if (symlink ("/file", path) < 0)
    return 77;

  return 0;
}

static void
cleanup_symlink_tree (const char *root)
{
  char path[PATH_MAX];
  const char *files[] = { "dir/abs", "dir/up", "dir/link", "dir/file", "dir", "link", "file", NULL };
  size_t i;

  for (i = 0; files[i]; i++)
    {
      snprintf (path, sizeof (path), "%s/%s", root, files[i]);
      if (remove (path) < 0)
        continue;
    }
  rmdir (root);
}

static int
test_symlinks ()
{
  struct
  {
    const char *path;
    const char *expected;
  } cases[] = {
    { "/link", "/file" },
    { "/dir/link", "/dir/file" },
    { "/dir/up", "/file" },
    { "/dir/abs", "/file" },
    { NULL, NULL },
  };
  char root[PATH_MAX];
  char resolved[PATH_MAX];
  char expected[PATH_MAX];
  int ret = 0;
  size_t i;

  ret = make_symlink_tree (root, sizeof (root));
  if (ret != 0)
    return ret;

  for (i = 0; cases[i].path; i++)
    {
      char *result = chroot_realpath (root, cases[i].path, resolved);
      if (result == NULL)
        {
          ret = -1;
          break;
        }

      snprintf (expected, sizeof (expected), "%s%s", root, cases[i].expected);
      if (strcmp (resolved, expected) != 0)
        {
          ret = -1;
          break;
        }
    }

  cleanup_symlink_tree (root);
  return ret;
}

static int
maybe_open_tree_namespace (const char *rootfs, int *out_fd, libcrun_error_t *err)
{
  cleanup_close int rootfs_fd = -1;
  int tree_fd;

  *out_fd = -1;

  rootfs_fd = open (rootfs, O_DIRECTORY | O_PATH | O_CLOEXEC);
  if (UNLIKELY (rootfs_fd < 0))
    return crun_make_error (err, errno, "open `%s`", rootfs);

  tree_fd = syscall_open_tree (rootfs_fd, "",
                               OPEN_TREE_NAMESPACE | OPEN_TREE_CLOEXEC
                                   | AT_EMPTY_PATH | AT_RECURSIVE);
  if (tree_fd < 0)
    {
      if (errno == EINVAL || errno == ENOSYS || errno == EPERM)
        return 0;
      return crun_make_error (err, errno, "open_tree `%s`", rootfs);
    }

  *out_fd = tree_fd;
  return 0;
}

static bool
can_use_open_tree_namespace (libcrun_container_t *container)
{
  runtime_spec_schema_config_schema *def = container->container_def;
  struct libcrun_fd_map *mount_fds;
  bool has_hooks = def->hooks
                   && (def->hooks->prestart_len || def->hooks->create_runtime_len);
  bool has_userns = get_private_data (container)->unshare_flags & CLONE_NEWUSER;
  size_t i;

  if (has_hooks || has_userns)
    return false;

  mount_fds = get_fd_map (container);
  for (i = 0; i < def->mounts_len; i++)
    {
      if (mount_fds->fds[i] < 0)
        {
          bool has_cached_target = get_private_data (container)->copy_symlink_targets
                                   && i < get_private_data (container)->n_copy_symlink_targets
                                   && get_private_data (container)->copy_symlink_targets[i];
          if (! has_cached_target)
            return false;
        }
    }

  return true;
}

static int
get_old_root_fd (struct private_data_s *data)
{
  if (data->old_root_fd >= 0)
    return data->old_root_fd;

  data->old_root_fd = open ("/", O_PATH | O_CLOEXEC);
  return data->old_root_fd;
}

static void
reclone_maskdir_fd (libcrun_container_t *container)
{
  struct private_data_s *pd = get_private_data (container);
  cleanup_close int new_fd = -1;

  if (pd->maskdir_fd < 0)
    return;

  new_fd = syscall_open_tree (pd->maskdir_fd, "",
                              AT_EMPTY_PATH | OPEN_TREE_CLONE | OPEN_TREE_CLOEXEC);
  if (new_fd >= 0)
    {
      proc_fd_path_t fd_path;

      close (pd->maskdir_fd);
      pd->maskdir_fd = new_fd;
      new_fd = -1;

      get_self_fd_path (fd_path, pd->maskdir_fd);
      free (pd->maskdir_proc_path);
      pd->maskdir_proc_path = xstrdup (fd_path);
    }
}

static struct libcrun_fd_map *
get_fd_map (libcrun_container_t *container)
{
  struct libcrun_fd_map *mount_fds = get_private_data (container)->mount_fds;

  if (mount_fds == NULL)
    {
      runtime_spec_schema_config_schema *def = container->container_def;
      mount_fds = make_libcrun_fd_map (def->mounts_len);
      get_private_data (container)->mount_fds = mount_fds;
    }
  return mount_fds;
}

static int
setup_mount_namespace (libcrun_container_t *container, bool no_pivot, char **rootfs, libcrun_error_t *err)
{
  runtime_spec_schema_config_schema *def = container->container_def;
  unsigned long rootfs_propagation = 0;
  libcrun_error_t tmp_err = NULL;
  size_t i;
  if (def->linux && def->linux->rootfs_propagation)
    rootfs_propagation = get_mount_flags (def->linux->rootfs_propagation, 0, NULL, NULL, NULL, NULL);

  if ((rootfs_propagation & ALL_PROPAGATIONS_NO_REC) == 0)
    rootfs_propagation = MS_REC | MS_PRIVATE;

  get_private_data (container)->rootfs_propagation = rootfs_propagation;

  ret = libcrun_container_enter_cgroup_ns (container, err);
  if (UNLIKELY (ret < 0))
    return ret;

  if (! get_private_data (container)->joined_mount_ns)
    {
      ret = unshare (CLONE_NEWNS);
      if (UNLIKELY (ret < 0))
        return crun_make_error (err, errno, "unshare `CLONE_NEWNS`");
    }

  ret = do_mount (container, NULL, -1, "/", NULL, rootfs_propagation, NULL, LABEL_MOUNT, err);
  if (UNLIKELY (ret < 0))
    return ret;

  ret = make_parent_mount_private (*rootfs, err);
  if (UNLIKELY (ret < 0))
    return ret;

  ret = do_mount (container, *rootfs, -1, *rootfs, NULL, MS_BIND | MS_REC | MS_PRIVATE, NULL, LABEL_MOUNT, err);
  if (UNLIKELY (ret < 0))
    return ret;

  /* Pre-create mounts and cache paths before pivot_root,
     while the host file system is still reachable.  */
  for (i = 0; i < def->mounts_len; i++)
      struct libcrun_fd_map *mount_fds = get_fd_map (container);
      cleanup_free char *dest_path = NULL;
      cleanup_close int mnt_fd = -1;
      bool recursive_bind, nofollow;
      struct stat st;

      if (mount_fds && mount_fds->fds[i] >= 0)
        continue;

      /* Pre-read symlink targets for copy-symlink mounts while the host file system is still reachable.  */
      if (def->mounts[i]->source != NULL
          && def->mounts[i]->source[0] == '/')
          cleanup_free char *mnt_data = NULL;
          unsigned long mnt_flags = 0;
          unsigned long mnt_extra = 0;
          uint64_t mnt_rec_clear = 0, mnt_rec_set = 0;
          size_t j;

          for (j = 0; j < def->mounts[i]->options_len; j++)
            mnt_flags |= get_mount_flags_or_option (def->mounts[i]->options[j],
                                                    mnt_flags, &mnt_extra, &mnt_data,
                                                    &mnt_rec_clear, &mnt_rec_set);

          if (mnt_extra & OPTION_COPY_SYMLINK)
            {
              cleanup_free char *target = NULL;
              libcrun_error_t tmp_err = NULL;
              ssize_t len;

              len = safe_readlinkat (AT_FDCWD, def->mounts[i]->source, &target, 0, &tmp_err);
              if (UNLIKELY (len < 0))
                crun_error_release (&tmp_err);

              if (get_private_data (container)->copy_symlink_targets == NULL)
                {
                  get_private_data (container)->copy_symlink_targets
                      = xmalloc0 (def->mounts_len * sizeof (char *));
                  get_private_data (container)->n_copy_symlink_targets = def->mounts_len;
                }
              get_private_data (container)->copy_symlink_targets[i] = target;
              target = NULL;
            }

      if (is_bind_mount (def->mounts[i], &recursive_bind, &nofollow))
        {
          if (mount_fds && def->mounts[i]->source != NULL)
            {
              libcrun_error_t tmp_err = NULL;

              mount_fds->fds[i] = get_bind_mount (AT_FDCWD, def->mounts[i]->source,
                                                  recursive_bind, false, nofollow,
                                                  MS_PRIVATE, &tmp_err);
              if (mount_fds->fds[i] < 0)
                crun_error_release (&tmp_err);
            }
          continue;
        }

      mnt_fd = open_mount_of_type (container, def->mounts[i], err);
      if (mnt_fd < 0)
        {
          crun_error_release (err);
          continue;
        }

      ret = append_paths (&dest_path, err, *rootfs, def->mounts[i]->destination, NULL);
      if (UNLIKELY (ret < 0))
        return ret;
      if (stat (dest_path, &st) == 0)
          proc_fd_path_t fd_path;
          int procfd = get_procfd (get_private_data (container), err);
          if (UNLIKELY (procfd < 0))
            return procfd;

          get_self_fd_path (fd_path, mnt_fd);
          ret = fchmodat (procfd, fd_path, st.st_mode & 07777, 0);
          (void) ret;
        }

static int
mknod_and_set_attrs (int dirfd, const char *name, struct device_s *device, mode_t type, dev_t dev, libcrun_error_t *err)
{
  int ret;

  ret = mknodat (dirfd, name, device->mode | type, dev);
  if (UNLIKELY (ret < 0 && errno == EEXIST))
    return 0;
  if (UNLIKELY (ret < 0))
    return crun_make_error (err, errno, "mknodat `%s`", device->path);

  ret = fchmodat (dirfd, name, device->mode, 0);
  if (UNLIKELY (ret < 0))
    return crun_make_error (err, errno, "fchmod `%s`", device->path);

  ret = fchownat (dirfd, name, device->uid, device->gid, AT_SYMLINK_NOFOLLOW);
  if (UNLIKELY (ret < 0))
    return crun_make_error (err, errno, "fchown `%s`", device->path);

  return 1;
}

static struct libcrun_fd_map *
get_needed_devs_fd_map (libcrun_container_t *container)
{
  struct libcrun_fd_map *fds = get_private_data (container)->needed_devs_fds;

  if (fds == NULL)
    {
      fds = make_libcrun_fd_map (NUM_NEEDED_DEVS);
      get_private_data (container)->needed_devs_fds = fds;
    }
  return fds;
}

static int
prepare_and_send_needed_dev_mounts (libcrun_container_t *container, int sync_socket_host, libcrun_error_t *err)
{
  cleanup_close_map struct libcrun_fd_map *fds = NULL;
  bool has_userns = (get_private_data (container)->unshare_flags & CLONE_NEWUSER) ? true : false;
  size_t how_many = 0;
  size_t i;

  fds = make_libcrun_fd_map (NUM_NEEDED_DEVS);

  if (! has_userns || geteuid () > 0)
    return send_mounts (sync_socket_host, fds, 0, NUM_NEEDED_DEVS, err);

  for (i = 0; i < NUM_NEEDED_DEVS && needed_devs[i].path; i++)
    {
      int fd = syscall_open_tree (AT_FDCWD, needed_devs[i].path,
                                  OPEN_TREE_CLONE | OPEN_TREE_CLOEXEC);
      if (fd >= 0)
        {
          fds->fds[i] = fd;
          how_many++;
        }
    }

  return send_mounts (sync_socket_host, fds, how_many, NUM_NEEDED_DEVS, err);
}

static uint64_t
ms_flags_to_mount_attr (uint64_t ms_flags)
{
  uint64_t attr = 0;

  if (ms_flags & MS_RDONLY)
    attr |= MOUNT_ATTR_RDONLY;
  if (ms_flags & MS_NOSUID)
    attr |= MOUNT_ATTR_NOSUID;
  if (ms_flags & MS_NODEV)
    attr |= MOUNT_ATTR_NODEV;
  if (ms_flags & MS_NOEXEC)
    attr |= MOUNT_ATTR_NOEXEC;
  if (ms_flags & MS_NOATIME)
    attr |= MOUNT_ATTR_NOATIME;
  if (ms_flags & MS_STRICTATIME)
    attr |= MOUNT_ATTR_STRICTATIME;
  if (ms_flags & MS_NODIRATIME)
    attr |= MOUNT_ATTR_NODIRATIME;
  if (ms_flags & MS_NOSYMFOLLOW)
    attr |= MOUNT_ATTR_NOSYMFOLLOW;

  return attr;
}

static int
get_cgroup_process_from_content (char *content, int cgroup_mode, char **path, bool absolute, libcrun_error_t *err)
int
libcrun_get_cgroup_process_at (int dirfd, char **path, bool absolute, libcrun_error_t *err)
{
  cleanup_free char *content = NULL;
  size_t content_size;
  int cgroup_mode;
  int ret;

  cgroup_mode = libcrun_get_cgroup_mode (err);
  if (UNLIKELY (cgroup_mode < 0))
    return cgroup_mode;

  ret = read_all_file_at (dirfd, SELF_CGROUP, &content, &content_size, err);
  if (UNLIKELY (ret < 0))
    return ret;

  return get_cgroup_process_from_content (content, cgroup_mode, path, absolute, err);
}

int
libcrun_get_cgroup_process (pid_t pid, char **path, bool absolute, libcrun_error_t *err)
{
  cleanup_free char *content = NULL;
  char proc_cgroup_file[64];
  size_t content_size;
  int cgroup_mode;
  int ret;

  cgroup_mode = libcrun_get_cgroup_mode (err);
  if (UNLIKELY (cgroup_mode < 0))
    return cgroup_mode;

  if (pid == 0)
    strcpy (proc_cgroup_file, PROC_SELF_CGROUP);
  else
    {
      int len = snprintf (proc_cgroup_file, sizeof (proc_cgroup_file), "/proc/%d/cgroup", pid);
      if (UNLIKELY (len >= (int) sizeof (proc_cgroup_file)))
        return crun_make_error (err, 0, "internal error: static buffer too small");
    }

  ret = read_all_file (proc_cgroup_file, &content, &content_size, err);
  if (UNLIKELY (ret < 0))
    return ret;

  return get_cgroup_process_from_content (content, cgroup_mode, path, absolute, err);
}

static int
get_procfd (struct private_data_s *data, libcrun_error_t *err)
{
  int fd;

  if (data->procfd >= 0)
    return data->procfd;

  fd = fsopen_mount ("proc", NULL, NULL);
  if (fd < 0)
    fd = open ("/proc", O_DIRECTORY | O_CLOEXEC);
  if (UNLIKELY (fd < 0))
    return crun_make_error (err, errno, "open `/proc`");

  data->procfd = fd;
  return fd;
}

else if (UNLIKELY (! json_object_is_type (tmp, json_type_int)))
      {
        ret = crun_make_error (err, 0, "`process-start-time` is not a numeric value in `%s`", file);
        goto exit;
      }

static apr_status_t systemd_stopping(void *unused)
{
    if (ap_state_query(AP_SQ_MAIN_STATE) == AP_SQ_MS_EXITING) {
        sd_notify(0, "STOPPING=1\n"
                  "STATUS=Shutting down.\n");
    }
    return APR_SUCCESS;
}

static apr_uint64_t monotonic_usec(void)
{
    struct timespec ts;

    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (apr_uint64_t)ts.tv_sec * APR_USEC_PER_SEC + ts.tv_nsec / 1000;
}

static int ap_systemd_listen_fds(int unset_environment)
{
    int *fds = ap_retained_data_get(retained_key);

    if (fds == NULL) {
        fds = ap_retained_data_create(retained_key, sizeof(*fds));
        *fds = sd_listen_fds(0);
    }
    if (unset_environment) {
        /* Take the variables out of the environment, keeping the count. */
        sd_listen_fds(1);
    }
    return *fds;
}

void board_autoled_on(int led)
{
  if (led == LED_STACKCREATED || led == LED_PANIC)
    {
      stm32_gpiowrite(GPIO_LD1, true);
    }
}

void board_autoled_off(int led)
{
  if (led == LED_PANIC)
    {
      stm32_gpiowrite(GPIO_LD1, false);
    }
}

int stm32_bringup(void)
{
  int ret;

#ifdef CONFIG_FS_PROCFS
  ret = mount(NULL, "/proc", "procfs", 0, NULL);
  if (ret < 0)
    {
      return ret;
    }
#endif

#ifdef CONFIG_INPUT_BUTTONS
  /* Register the BUTTON lower-half driver. */

  ret = btn_lower_initialize("/dev/buttons");
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: btn_lower_initialize() failed: %d\n", ret);
    }
#endif

  UNUSED(ret);
  return OK;
}

uint32_t board_button_initialize(void)
{
  stm32_configgpio(GPIO_BTN_USER);
  return NUM_BUTTONS;
}

int board_button_irq(int id, xcpt_t irqhandler, void *arg)
{
  if (id != BUTTON_USER)
    {
      return -EINVAL;
    }

  return stm32_gpiosetevent(GPIO_BTN_USER, true, true, true,
                            irqhandler, arg);
}

uint32_t board_userled_initialize(void)
{
  stm32_configgpio(GPIO_LD1);
  return BOARD_NLEDS;
}

void board_userled(int led, bool ledon)
{
  if (led == BOARD_LED_GREEN)
    {
      stm32_gpiowrite(GPIO_LD1, ledon);
    }
}

static void stm32_configureclock(void)
{
#ifdef CONFIG_ARCH_BOARD_STM32_CUSTOM_CLOCKCONFIG
  stm32_board_clockconfig();
#else
  stm32_stdclockconfig();
#endif
}

void stm32_clockconfig(void)
{
  stm32_configureclock();

  /* Enable peripheral clocking */

  stm32_rcc_enableperipherals();
}

void stm32_stdclockconfig(void)
{
  uint32_t regval;
  volatile int32_t timeout;

  /* Start the external oscillator used as the PSI reference. */

  regval  = getreg32(STM32_RCC_CR1);
  regval &= ~(RCC_CR1_HSEBYP | RCC_CR1_HSEEXT);

#ifdef STM32_HSEBYP_ENABLE
  regval |= RCC_CR1_HSEBYP;
#  ifdef STM32_HSEEXT_DIGITAL
  regval |= RCC_CR1_HSEEXT;
#  endif
#endif

  regval |= RCC_CR1_HSEON;
  putreg32(regval, STM32_RCC_CR1);

  for (timeout = CLOCK_READY_TIMEOUT; timeout > 0; timeout--)
    {
      if ((getreg32(STM32_RCC_CR1) & RCC_CR1_HSERDY) != 0)
        {
          break;
        }
    }

  if (timeout == 0)
    {
      return;
    }

  /* Configure the PSI reference and output frequency. */

  regval  = getreg32(STM32_RCC_CR2);
  regval &= ~(RCC_CR2_PSIREFSRC_MASK | RCC_CR2_PSIREF_MASK |
              RCC_CR2_PSIFREQ_MASK);
  regval |= STM32_RCC_CR2_PSIREFSRC | STM32_RCC_CR2_PSIREF |
            STM32_RCC_CR2_PSIFREQ;
  putreg32(regval, STM32_RCC_CR2);

  modifyreg32(STM32_RCC_CR1, 0, RCC_CR1_PSISON);
  for (timeout = CLOCK_READY_TIMEOUT; timeout > 0; timeout--)
    {
      if ((getreg32(STM32_RCC_CR1) & RCC_CR1_PSISRDY) != 0)
        {
          break;
        }
    }

  if (timeout == 0)
    {
      return;
    }

  /* Configure the AHB and APB prescalers. */

  modifyreg32(STM32_RCC_CFGR2,
              RCC_CFGR2_HPRE_MASK | RCC_CFGR2_PPRE1_MASK |
              RCC_CFGR2_PPRE2_MASK | RCC_CFGR2_PPRE3_MASK,
              STM32_RCC_CFGR2_HPRE | STM32_RCC_CFGR2_PPRE1 |
              STM32_RCC_CFGR2_PPRE2 | STM32_RCC_CFGR2_PPRE3);

  /* Configure FLASH before raising HCLK. */

  modifyreg32(STM32_FLASH_ACR, FLASH_ACR_LATENCY_MASK,
              STM32_FLASH_ACR_LATENCY);

  /* Use PSIS as the system clock and wait for the switch to complete. */

  modifyreg32(STM32_RCC_CFGR1, RCC_CFGR1_SW_MASK, RCC_CFGR1_SW_PSIS);
  for (timeout = CLOCK_READY_TIMEOUT; timeout > 0; timeout--)
    {
      if ((getreg32(STM32_RCC_CFGR1) & RCC_CFGR1_SWS_MASK) ==
          RCC_CFGR1_SWS_PSIS)
        {
          break;
        }
    }

  if (timeout == 0)
    {
      return;
    }

  /* Configure the FLASH programming delay for the resulting HCLK. */

  modifyreg32(STM32_FLASH_ACR, FLASH_ACR_WRHIGHFREQ_MASK,
              STM32_FLASH_ACR_WRHIGHFREQ);
}

void stm32_rcc_enableperipherals(void)
{
  uint32_t regval;

  /* Enable the GPIO ports implemented by STM32C5. */

  regval = RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOBEN |
           RCC_AHB2ENR_GPIOCEN | RCC_AHB2ENR_GPIODEN |
           RCC_AHB2ENR_GPIOEEN | RCC_AHB2ENR_GPIOHEN;
  modifyreg32(STM32_RCC_AHB2ENR, 0, regval);

#ifdef CONFIG_STM32_USART1
  modifyreg32(STM32_RCC_APB2ENR, 0, RCC_APB2ENR_USART1EN);
#endif

  regval = 0;
#ifdef CONFIG_STM32_USART2
  regval |= RCC_APB1LENR_USART2EN;
#endif
#ifdef CONFIG_STM32_USART3
  regval |= RCC_APB1LENR_USART3EN;
#endif
#ifdef CONFIG_STM32_UART4
  regval |= RCC_APB1LENR_UART4EN;
#endif
#ifdef CONFIG_STM32_UART5
  regval |= RCC_APB1LENR_UART5EN;
#endif
  modifyreg32(STM32_RCC_APB1LENR, 0, regval);

#ifdef CONFIG_STM32_LPUART1
  modifyreg32(STM32_RCC_APB3ENR, 0, RCC_APB3ENR_LPUART1EN);
#endif
}

static bool check_declaration(const char *line, int ndx)
{
  static const char *const nondecl[] =
  {
    "return", "if", "else", "while", "for", "do", "switch", "case",
    "default", "break", "continue", "goto", "sizeof", "asm", "__asm",
    "__asm__", NULL
  };

  const char *const *kw;
  int nident = 0;
  int i = ndx;

  /* Must open with a type name; keeps out '*ptr = x;' and comment lines */

  if (isalpha((int)line[ndx]) == 0 && line[ndx] != '_')
    {
      return false;
    }

  for (kw = nondecl; *kw != NULL; kw++)
    {
      if (check_keyword(line, ndx, *kw))
        {
          return false;
        }
    }

  while (line[i] != '\0' && line[i] != '\n')
    {
      if (isalpha((int)line[i]) != 0 || line[i] == '_')
        {
          nident++;
          while (isalnum((int)line[i]) != 0 || line[i] == '_')
            {
              i++;
            }
        }
      else if (line[i] == ' ' || line[i] == '*')
        {
          i++;
        }
      else
        {
          /* Only a terminator that can follow the declared name counts */

          /* '<type> (*<name>)(...)' declares a pointer to a function.  The
           * second parameter list tells it from a call like 'foo(*ptr)'.
           */

          if (line[i] == '(' && nident == 1)
            {
              int j = i + 1;

              while (line[j] == ' ')
                {
                  j++;
                }

              if (line[j] == '*')
                {
                  j++;
                  while (line[j] == ' ')
                    {
                      j++;
                    }

                  while (isalnum((int)line[j]) != 0 || line[j] == '_')
                    {
                      j++;
                    }

                  while (line[j] == ' ')
                    {
                      j++;
                    }

                  if (line[j] == ')' && line[j + 1] == '(')
                    {
                      return true;
                    }
                }
            }

          return nident >= 2 && strchr("=;[(,", line[i]) != NULL;
        }
    }

  return false;
}

static bool check_type_name(const char *line, int ndx)
{
  int i = ndx;

  while (isalnum((int)line[i]) != 0 || line[i] == '_')
    {
      i++;
    }

  return i >= ndx + 3 && line[i] == ' ' &&
         line[i - 1] == 't' && line[i - 2] == '_';
}

static int pci_enable_parent_bridges(FAR struct pci_device_s *dev)
{
  FAR struct pci_device_s *bridge;
  FAR struct pci_device_s *candidate;
  FAR struct pci_bus_s *bus = dev->bus;
  uint16_t command;
  int ret;

  while (bus != NULL && bus->parent_bus != NULL)
    {
      bridge = NULL;
      list_for_every_entry(&bus->parent_bus->devices, candidate,
                           struct pci_device_s, bus_list)
        {
          if (candidate->subordinate == bus)
            {
              bridge = candidate;
              break;
            }
        }

      if (bridge == NULL)
        {
          return -ENODEV;
        }

      ret = pci_read_config_word(bridge, PCI_COMMAND, &command);
      if (ret < 0)
        {
          return ret;
        }

      command |= PCI_COMMAND_MEMORY | PCI_COMMAND_MASTER;
      ret = pci_write_config_word(bridge, PCI_COMMAND, command);
      if (ret < 0)
        {
          return ret;
        }

      bus = bus->parent_bus;
    }

  return OK;
}

ioexpander_dev_s *board_ioexpander_initialize(void)
{
  FAR struct i2c_master_s *i2c;

  if (g_ioe != NULL)
    {
      return g_ioe;
    }

  i2c = esp32s3_i2cbus_initialize(BOARD_I2C_BUS);
  if (i2c == NULL)
    {
      syslog(LOG_ERR, "ERROR: Failed to initialize I2C%d\n", BOARD_I2C_BUS);
      return NULL;
    }

  g_ioe = ch422g_initialize(i2c, &g_ch422g_config);
  if (g_ioe == NULL)
    {
      syslog(LOG_ERR, "ERROR: Failed to initialize CH422G\n");
      esp32s3_i2cbus_uninitialize(i2c);
      return NULL;
    }

  return g_ioe;
}

int board_lcd_initialize(void)
{
  FAR struct ioexpander_dev_s *ioe;
  int ret;

  ioe = board_ioexpander_initialize();
  if (ioe == NULL)
    {
      return -ENODEV;
    }

  /* The panel reset and the display enable are outputs of the expander.
   * Drive the panel into reset and keep the display off while it settles.
   */

  ret = IOEXP_SETDIRECTION(ioe, BOARD_EXIO_LCD_RST,
                           IOEXPANDER_DIRECTION_OUT);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: Failed to configure LCD reset: %d\n", ret);
      return ret;
    }

  ret = IOEXP_SETDIRECTION(ioe, BOARD_EXIO_DISP, IOEXPANDER_DIRECTION_OUT);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: Failed to configure display enable: %d\n",
             ret);
      return ret;
    }

  IOEXP_WRITEPIN(ioe, BOARD_EXIO_DISP, false);
  IOEXP_WRITEPIN(ioe, BOARD_EXIO_LCD_RST, false);
  up_udelay(LCD_RESET_HOLD_US);

  ret = IOEXP_WRITEPIN(ioe, BOARD_EXIO_LCD_RST, true);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: Failed to release LCD reset: %d\n", ret);
      return ret;
    }

  up_udelay(LCD_RESET_WAIT_US);

  /* The framebuffer has to exist, and so be scanning out a defined buffer,
   * before the display is enabled.  Enabling it first shows whatever the
   * panel happens to latch until the first frame arrives.
   */

  ret = fb_register(0, 0);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: fb_register() failed: %d\n", ret);
      return ret;
    }

  ret = IOEXP_WRITEPIN(ioe, BOARD_EXIO_DISP, true);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: Failed to enable the display: %d\n", ret);
      return ret;
    }

  return OK;
}

static void IRAM_ATTR esp32s3_lcd_bounce_fill(struct esp32s3_lcd_s *priv,
                                              int bb)
{
  struct esp32s3_layer_s *layer = CURRENT_LAYER(priv);

  memcpy(g_bounce[bb],
         &layer->framebuffer[priv->yoffset * ESP32S3_LCD_STRIDE +
                             priv->bouncepos],
         ESP32S3_LCD_BB_SIZE);

  priv->bouncepos += ESP32S3_LCD_BB_SIZE;
  if (priv->bouncepos >= ESP32S3_LCD_FB_SIZE)
    {
      priv->bouncepos = 0;
    }
}

static int IRAM_ATTR esp32s3_lcd_dma_interrupt(int irq, void *context,
                                               void *arg)
{
  struct esp32s3_lcd_s *priv = &g_lcd_priv;
  int status = esp32s3_dma_get_interrupt(priv->dma_channel, true);

  if (status <= 0)
    {
      return 0;
    }

  esp32s3_dma_clear_interrupt(priv->dma_channel, true, status);

  if ((status & GDMA_LL_EVENT_TX_EOF) != 0)
    {
      /* The buffer that finished is the one this transfer started from */

      esp32s3_lcd_bounce_fill(priv, priv->bbeof & 1);
      priv->bbeof++;
    }

  return 0;
}

static int ch422g_write_reg(FAR struct ch422g_dev_s *priv, uint8_t addr,
                            uint8_t value)
{
  struct i2c_msg_s msg;

  msg.frequency = priv->config->frequency;
  msg.addr      = addr;
  msg.flags     = 0;
  msg.buffer    = &value;
  msg.length    = 1;

  return I2C_TRANSFER(priv->i2c, &msg, 1);
}

static int ch422g_read_io(FAR struct ch422g_dev_s *priv, FAR uint8_t *value)
{
  struct i2c_msg_s msg;

  msg.frequency = priv->config->frequency;
  msg.addr      = CH422G_ADDR_RD_IO;
  msg.flags     = I2C_M_READ;
  msg.buffer    = value;
  msg.length    = 1;

  return I2C_TRANSFER(priv->i2c, &msg, 1);
}

static int ch422g_setdir(FAR struct ch422g_dev_s *priv)
{
  uint8_t sysparam = priv->sysparam;

  if (priv->outmask != 0)
    {
      sysparam |= CH422G_SET_IO_OE;
    }
  else
    {
      sysparam &= ~CH422G_SET_IO_OE;
    }

  if (sysparam == priv->sysparam)
    {
      return OK;
    }

  priv->sysparam = sysparam;
  return ch422g_write_reg(priv, CH422G_ADDR_WR_SET, sysparam);
}

static int ch422g_direction(FAR struct ioexpander_dev_s *dev, uint8_t pin,
                            int dir)
{
  FAR struct ch422g_dev_s *priv = (FAR struct ch422g_dev_s *)dev;
  int ret;

  if (pin >= CH422G_NPINS)
    {
      return -ENXIO;
    }

  if (dir != IOEXPANDER_DIRECTION_IN && dir != IOEXPANDER_DIRECTION_OUT)
    {
      return -EINVAL;
    }

  /* OC0-OC3 are open-drain outputs and cannot be inputs */

  if (pin >= CH422G_NIO)
    {
      return dir == IOEXPANDER_DIRECTION_OUT ? OK : -EINVAL;
    }

  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      return ret;
    }

  if (dir == IOEXPANDER_DIRECTION_OUT)
    {
      priv->outmask |= (1 << pin);
    }
  else
    {
      priv->outmask &= ~(1 << pin);
    }

  ret = ch422g_setdir(priv);

  nxmutex_unlock(&priv->lock);
  return ret;
}

static int ch422g_option(FAR struct ioexpander_dev_s *dev, uint8_t pin,
                         int opt, FAR void *val)
{
  FAR struct ch422g_dev_s *priv = (FAR struct ch422g_dev_s *)dev;
  int ret = -ENOSYS;

  if (pin >= CH422G_NPINS)
    {
      return -ENXIO;
    }

  if (opt == IOEXPANDER_OPTION_INVERT)
    {
      ret = ((uintptr_t)val == IOEXPANDER_VAL_NORMAL) ? OK : -ENOSYS;
    }
  else if (opt == IOEXPANDER_OPTION_INTCFG)
    {
      ret = ((uintptr_t)val == IOEXPANDER_VAL_DISABLE) ? OK : -ENOSYS;
    }

  UNUSED(priv);
  return ret;
}

static int ch422g_writepin(FAR struct ioexpander_dev_s *dev, uint8_t pin,
                           bool value)
{
  FAR struct ch422g_dev_s *priv = (FAR struct ch422g_dev_s *)dev;
  FAR uint8_t *shadow;
  uint8_t addr;
  uint8_t bit;
  int ret;

  if (pin >= CH422G_NPINS)
    {
      return -ENXIO;
    }

  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      return ret;
    }

  if (pin < CH422G_NIO)
    {
      shadow = &priv->outio;
      addr   = CH422G_ADDR_WR_IO;
      bit    = 1 << pin;
    }
  else
    {
      shadow = &priv->outoc;
      addr   = CH422G_ADDR_WR_OC;
      bit    = 1 << (pin - CH422G_NIO);
    }

  if (value)
    {
      *shadow |= bit;
    }
  else
    {
      *shadow &= ~bit;
    }

  ret = ch422g_write_reg(priv, addr, *shadow);

  nxmutex_unlock(&priv->lock);
  return ret;
}

static int ch422g_readpin(FAR struct ioexpander_dev_s *dev, uint8_t pin,
                          FAR bool *value)
{
  FAR struct ch422g_dev_s *priv = (FAR struct ch422g_dev_s *)dev;
  uint8_t regval;
  int ret;

  if (pin >= CH422G_NPINS)
    {
      return -ENXIO;
    }

  DEBUGASSERT(value != NULL);

  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      return ret;
    }

  if (pin >= CH422G_NIO)
    {
      *value = ((priv->outoc >> (pin - CH422G_NIO)) & 1) != 0;
      ret    = OK;
    }
  else if ((priv->sysparam & CH422G_SET_IO_OE) != 0)
    {
      *value = ((priv->outio >> pin) & 1) != 0;
      ret    = OK;
    }
  else
    {
      ret = ch422g_read_io(priv, &regval);
      if (ret >= 0)
        {
          *value = ((regval >> pin) & 1) != 0;
        }
    }

  nxmutex_unlock(&priv->lock);
  return ret;
}

static int ch422g_readbuf(FAR struct ioexpander_dev_s *dev, uint8_t pin,
                          FAR bool *value)
{
  FAR struct ch422g_dev_s *priv = (FAR struct ch422g_dev_s *)dev;
  int ret;

  if (pin >= CH422G_NPINS)
    {
      return -ENXIO;
    }

  DEBUGASSERT(value != NULL);

  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      return ret;
    }

  if (pin < CH422G_NIO)
    {
      *value = ((priv->outio >> pin) & 1) != 0;
    }
  else
    {
      *value = ((priv->outoc >> (pin - CH422G_NIO)) & 1) != 0;
    }

  nxmutex_unlock(&priv->lock);
  return OK;
}

static int ch422g_multiwritepin(FAR struct ioexpander_dev_s *dev,
                                FAR const uint8_t *pins,
                                FAR const bool *values, int count)
{
  FAR struct ch422g_dev_s *priv = (FAR struct ch422g_dev_s *)dev;
  bool touchio = false;
  bool touchoc = false;
  int ret;
  int i;

  DEBUGASSERT(pins != NULL && values != NULL);

  for (i = 0; i < count; i++)
    {
      if (pins[i] >= CH422G_NPINS)
        {
          return -ENXIO;
        }
    }

  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      return ret;
    }

  for (i = 0; i < count; i++)
    {
      uint8_t pin = pins[i];

      if (pin < CH422G_NIO)
        {
          if (values[i])
            {
              priv->outio |= (1 << pin);
            }
          else
            {
              priv->outio &= ~(1 << pin);
            }

          touchio = true;
        }
      else
        {
          if (values[i])
            {
              priv->outoc |= (1 << (pin - CH422G_NIO));
            }
          else
            {
              priv->outoc &= ~(1 << (pin - CH422G_NIO));
            }

          touchoc = true;
        }
    }

  ret = OK;

  if (touchio)
    {
      ret = ch422g_write_reg(priv, CH422G_ADDR_WR_IO, priv->outio);
    }

  if (ret >= 0 && touchoc)
    {
      ret = ch422g_write_reg(priv, CH422G_ADDR_WR_OC, priv->outoc);
    }

  nxmutex_unlock(&priv->lock);
  return ret;
}

static int ch422g_multireadpin(FAR struct ioexpander_dev_s *dev,
                               FAR const uint8_t *pins, FAR bool *values,
                               int count)
{
  FAR struct ch422g_dev_s *priv = (FAR struct ch422g_dev_s *)dev;
  uint8_t regval = 0;
  bool haveinput = false;
  int ret;
  int i;

  DEBUGASSERT(pins != NULL && values != NULL);

  for (i = 0; i < count; i++)
    {
      if (pins[i] >= CH422G_NPINS)
        {
          return -ENXIO;
        }
    }

  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      return ret;
    }

  if ((priv->sysparam & CH422G_SET_IO_OE) == 0)
    {
      for (i = 0; i < count; i++)
        {
          if (pins[i] < CH422G_NIO)
            {
              haveinput = true;
              break;
            }
        }
    }

  if (haveinput)
    {
      ret = ch422g_read_io(priv, &regval);
      if (ret < 0)
        {
          nxmutex_unlock(&priv->lock);
          return ret;
        }
    }

  for (i = 0; i < count; i++)
    {
      uint8_t pin = pins[i];

      if (pin >= CH422G_NIO)
        {
          values[i] = ((priv->outoc >> (pin - CH422G_NIO)) & 1) != 0;
        }
      else if (haveinput)
        {
          values[i] = ((regval >> pin) & 1) != 0;
        }
      else
        {
          values[i] = ((priv->outio >> pin) & 1) != 0;
        }
    }

  nxmutex_unlock(&priv->lock);
  return OK;
}

static int ch422g_multireadbuf(FAR struct ioexpander_dev_s *dev,
                               FAR const uint8_t *pins, FAR bool *values,
                               int count)
{
  FAR struct ch422g_dev_s *priv = (FAR struct ch422g_dev_s *)dev;
  int ret;
  int i;

  DEBUGASSERT(pins != NULL && values != NULL);

  for (i = 0; i < count; i++)
    {
      if (pins[i] >= CH422G_NPINS)
        {
          return -ENXIO;
        }
    }

  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      return ret;
    }

  for (i = 0; i < count; i++)
    {
      uint8_t pin = pins[i];

      if (pin < CH422G_NIO)
        {
          values[i] = ((priv->outio >> pin) & 1) != 0;
        }
      else
        {
          values[i] = ((priv->outoc >> (pin - CH422G_NIO)) & 1) != 0;
        }
    }

  nxmutex_unlock(&priv->lock);
  return OK;
}

ioexpander_dev_s *
ch422g_initialize(FAR struct i2c_master_s *i2c,
                  FAR struct ch422g_config_s *config)
{
  FAR struct ch422g_dev_s *priv;
  int ret;

  DEBUGASSERT(i2c != NULL && config != NULL);

  priv = kmm_zalloc(sizeof(struct ch422g_dev_s));
  if (priv == NULL)
    {
      gpioerr("ERROR: Failed to allocate driver instance\n");
      return NULL;
    }

  priv->dev.ops = &g_ch422g_ops;
  priv->i2c     = i2c;
  priv->config  = config;

  nxmutex_init(&priv->lock);

  /* Leave the device in a known state: the open-drain outputs off, the
   * bi-directional pins low, and the group in input mode until a board
   * asks for an output.  Writing the system parameter register first also
   * confirms that the device is answering.
   */

  ret = ch422g_write_reg(priv, CH422G_ADDR_WR_SET, priv->sysparam);
  if (ret < 0)
    {
      gpioerr("ERROR: CH422G not responding: %d\n", ret);
      goto errout;
    }

  ret = ch422g_write_reg(priv, CH422G_ADDR_WR_OC, priv->outoc);
  if (ret < 0)
    {
      goto errout;
    }

  ret = ch422g_write_reg(priv, CH422G_ADDR_WR_IO, priv->outio);
  if (ret < 0)
    {
      goto errout;
    }

  return &priv->dev;

errout:
  nxmutex_destroy(&priv->lock);
  kmm_free(priv);
  return NULL;
}

else if (ctrl_brace >= 0)
                {
                  if (indent != ctrl_brace)
                    {
                      ERROR("Bad left brace alignment", lineno, indent);
                    }

                  /* Record what the brace should have been so that the brace
                   * closing it is held to the same alignment.
                   */

                  if (bnest >= 1 && bnest <= MAX_BRACE)
                    {
                      lbrace_indent[bnest - 1] = ctrl_brace;
                    }
                }

int stm32_usb_setpullup(bool enable)
{
  irqstate_t flags;
  uint16_t regval;

  flags = enter_critical_section();
  regval = getreg16(STM32_USB_BCDR);

  if (enable)
    {
      regval |= USB_BCDR_DPPU;
    }
  else
    {
      regval &= ~USB_BCDR_DPPU;
    }

  putreg16(regval, STM32_USB_BCDR);
  leave_critical_section(flags);

  return OK;
}

static bool check_keyword(const char *line, int ndx, const char *kw)
{
  size_t len = strlen(kw);

  if (strncmp(&line[ndx], kw, len) != 0)
    {
      return false;
    }

  return isalnum((int)line[ndx + len]) == 0 && line[ndx + len] != '_';
}

