static inline void rcc_resetbkp(void)
{
  uint32_t regval;

  /* Check if the RTC is already configured */

  stm32_pwr_initbkp(false);

  regval = getreg32(RTC_MAGIC_REG);
  if (regval != RTC_MAGIC && regval != RTC_MAGIC_TIME_SET)
    {
      stm32_pwr_enablebkp(true);

      /* We might be changing RTCSEL - to ensure such changes work, we must
       * reset the backup domain (having backed up the RTC_MAGIC token)
       */

      modifyreg32(STM32_RCC_BDCR, 0, RCC_BDCR_BDRST);
      modifyreg32(STM32_RCC_BDCR, RCC_BDCR_BDRST, 0);

      stm32_pwr_enablebkp(false);
    }
}

void stm32_clockconfig(void)
{
  /* Make sure that we are starting in the reset state */

  rcc_reset();

  /* Reset backup domain if appropriate */

  rcc_resetbkp();

#if defined(CONFIG_ARCH_BOARD_STM32_CUSTOM_CLOCKCONFIG)
  /* Invoke Board Custom Clock Configuration */

  stm32_board_clockconfig();

#else
  /* Invoke standard, fixed clock configuration based on definitions
   * in board.h
   */

  stm32_stdclockconfig();

#endif

  /* Enable peripheral clocking */

  rcc_enableperipherals();
}

void stm32_clockenable(void)
{
#if defined(CONFIG_ARCH_BOARD_STM32_CUSTOM_CLOCKCONFIG)
  /* Invoke Board Custom Clock Configuration */

  stm32_board_clockconfig();

#else
  /* Invoke standard, fixed clock configuration based on definitions
   * in board.h
   */

  stm32_stdclockconfig();

#endif
}

static inline void rcc_reset(void)
{
  uint32_t regval;

  /* Make sure that MSI is on and ready.  MSI is the default system clock
   * source after reset.
   */

  regval  = getreg32(STM32_RCC_CR);
  regval |= RCC_CR_MSION;
  putreg32(regval, STM32_RCC_CR);

  while ((getreg32(STM32_RCC_CR) & RCC_CR_MSIRDY) == 0);

  /* Reset CFGR register (MSI as the system clock) */

  putreg32(0, STM32_RCC_CFGR);

  /* Wait until MSI is used as the system clock */

  while ((getreg32(STM32_RCC_CFGR) & RCC_CFGR_SWS_MASK) !=
         RCC_CFGR_SWS_MSI);

  /* Turn off HSI, HSE and PLL, keep MSI on */

  putreg32(RCC_CR_MSION, STM32_RCC_CR);

  /* Reset PLLCFGR register */

  putreg32(0, STM32_RCC_PLLCFG);

  /* DBG clock enable */

  putreg32(RCC_DBGCFGR_DBGEN, STM32_RCC_DBGCFGR);
}

static inline void rcc_enableio(void)
{
  uint32_t regval = 0;

  regval |= (RCC_IOPENR_IOPAEN | RCC_IOPENR_IOPBEN | RCC_IOPENR_IOPCEN |
             RCC_IOPENR_IOPDEN | RCC_IOPENR_IOPEEN | RCC_IOPENR_IOPFEN);

  putreg32(regval, STM32_RCC_IOPENR);   /* Enable GPIO */
}

static inline void rcc_enableahb(void)
{
  uint32_t regval = 0;

  /* Set the appropriate bits in the AHBENR register to enabled the
   * selected AHBENR peripherals.
   */

  regval  = getreg32(STM32_RCC_AHBENR);

#ifdef CONFIG_STM32_DMA1
  /* DMA 1 clock enable */

  regval |= RCC_AHBENR_DMA1EN;
#endif

#ifdef CONFIG_STM32_DMA2
  /* DMA 2 clock enable */

  regval |= RCC_AHBENR_DMA2EN;
#endif

#ifdef CONFIG_STM32_CRC
  /* CRC clock enable */

  regval |= RCC_AHBENR_CRCEN;
#endif

#ifdef CONFIG_STM32_TSC
  /* Touch sensing controller clock enable */

  regval |= RCC_AHBENR_TSCEN;
#endif

#ifdef CONFIG_STM32_RNG
  /* Random number generator clock enable */

  regval |= RCC_AHBENR_RNGEN;
#endif

#ifdef CONFIG_STM32_AES
  /* AES modules clock enable */

  regval |= RCC_AHBENR_AESEN;
#endif

  putreg32(regval, STM32_RCC_AHBENR);   /* Enable peripherals */
}

static inline void rcc_enableapb2(void)
{
  uint32_t regval;

  /* Set the appropriate bits in the APB2ENR register to enabled the
   * selected APB2 peripherals.
   */

  regval = getreg32(STM32_RCC_APB2ENR);

#ifdef CONFIG_STM32_SYSCFG
  /* SYSCFG clock */

  regval |= RCC_APB2ENR_SYSCFGEN;
#endif

#ifdef CONFIG_STM32_TIM1
  /* TIM1 Timer clock enable */

  regval |= RCC_APB2ENR_TIM1EN;
#endif

#ifdef CONFIG_STM32_SPI1
  /* SPI 1 clock enable */

  regval |= RCC_APB2ENR_SPI1EN;
#endif

#ifdef CONFIG_STM32_USART1
  /* USART1 clock enable */

  regval |= RCC_APB2ENR_USART1EN;
#endif

#ifdef CONFIG_STM32_TIM15
  /* TIM15 Timer clock enable */

  regval |= RCC_APB2ENR_TIM15EN;
#endif

#ifdef CONFIG_STM32_TIM16
  /* TIM16 Timer clock enable */

  regval |= RCC_APB2ENR_TIM16EN;
#endif

#ifdef CONFIG_STM32_ADC1
  /* ADC 1 clock enable */

  regval |= RCC_APB2ENR_ADC1EN;
#endif

  putreg32(regval, STM32_RCC_APB2ENR);
}

static inline bool stm32_rcc_enablehse(void)
{
  uint32_t regval;
  volatile int32_t timeout;

  /* Enable External High-Speed Clock (HSE) */

  regval  = getreg32(STM32_RCC_CR);
#ifdef STM32_HSEBYP_ENABLE          /* May be defined in board.h header file */
  regval |= RCC_CR_HSEBYP;          /* Enable HSE clock bypass */
#else
  regval &= ~RCC_CR_HSEBYP;         /* Disable HSE clock bypass */
#endif
  regval |= RCC_CR_HSEON;           /* Enable HSE */
  putreg32(regval, STM32_RCC_CR);

  /* Wait until the HSE is ready (or until a timeout elapsed) */

  for (timeout = HSERDY_TIMEOUT; timeout > 0; timeout--)
    {
      /* Check if the HSERDY flag is set in the CR */

      if ((getreg32(STM32_RCC_CR) & RCC_CR_HSERDY) != 0)
        {
          /* If so, then return TRUE */

          return true;
        }
    }

  /* In the case of a timeout starting the HSE, we really don't have a
   * strategy.  This is almost always a hardware failure or misconfiguration.
   */

  return false;
}

static inline void rcc_enableperipherals(void)
{
  rcc_enableio();
  rcc_enableahb();
  rcc_enableapb2();
  rcc_enableapb1();
}

float SurgeStorage::tuningPeriodSemitones() const
{
#ifndef SURGE_SKIP_ODDSOUND_MTS
    if (oddsound_mts_client && oddsound_mts_active_as_client)
        return (float)MTS_GetPeriodSemitones(oddsound_mts_client);
#endif
    if (isStandardTuning)
        return 12.0f;
    // In RETUNE_ALL mode pitch values are in scale-note-index space, so scale.count
    // steps equal one period (e.g. 13 for ED3-13 Bohlen-Pierce, 19 for ED2-19).
    if (tuningApplicationMode == RETUNE_ALL)
        return (float)currentScale.count;
    // In RETUNE_MIDI_ONLY mode pitch values are in semitone space, so the period in
    // semitones (cents of the last scale tone / 100) is the correct step size.
    return currentScale.tones[currentScale.count - 1].cents / 100.0f;
}

static int append_cgroup_dir(char *path, size_t path_size, size_t off, const char *dir_name, size_t *new_off)
{
	int ret;

	if (off >= path_size) {
		pr_err("Cgroup path '%.*s' is too long\n", path_size > 0 ? (int)path_size - 1 : 0, path);
		return -1;
	}

	ret = snprintf(path + off, path_size - off, "/%s", dir_name);
	if (ret < 0 || (size_t)ret >= path_size - off) {
		pr_err("Cgroup path %.*s/%s is too long\n", (int)off, path, dir_name);
		return -1;
	}

	if (new_off)
		*new_off = off + ret;
	return 0;
}

static void *parked_thread(void *arg)
{
	pthread_mutex_lock(&mutex);
	while (!done)
		pthread_cond_wait(&cond, &mutex);
	pthread_mutex_unlock(&mutex);

	return NULL;
}

static int rm_entry(const char *path, const struct stat *st,
		    int flag, struct FTW *ftw)
{
	return remove(path);
}

static void cleanup_stale_ovl_dirs(const char *parent)
{
	DIR *d;
	struct dirent *de;
	char path[PATH_MAX];

	d = opendir(parent);
	if (!d)
		return;

	while ((de = readdir(d)) != NULL) {
		if (strncmp(de->d_name, "zdtm_inotify_ovl.",
			    strlen("zdtm_inotify_ovl.")) != 0)
			continue;
		snprintf(path, sizeof(path), "%s/%s", parent, de->d_name);
		nftw(path, rm_entry, 16, FTW_DEPTH | FTW_PHYS);
	}
	closedir(d);
}

int main(int argc, char **argv)
{
	char buf[BUF_LEN];
	int fd, wd, len, i;

	if (argc < 2) {
		fprintf(stderr, "Usage: %s <path>\n", argv[0]);
		return 1;
	}

	fd = inotify_init();
	if (fd < 0) {
		perror("inotify_init");
		return 1;
	}

	wd = inotify_add_watch(fd, argv[1],
			       IN_MODIFY | IN_CREATE | IN_DELETE |
			       IN_OPEN | IN_CLOSE);
	if (wd < 0) {
		perror("inotify_add_watch");
		close(fd);
		return 1;
	}

	printf("Watching %s for events...\n", argv[1]);

	while (1) {
		len = read(fd, buf, BUF_LEN);
		if (len < 0) {
			perror("read");
			break;
		}

		i = 0;
		while (i < len) {
			struct inotify_event *event;

			event = (struct inotify_event *)&buf[i];

			if (event->mask & IN_CREATE)
				printf("CREATE: %s\n", event->name);
			if (event->mask & IN_DELETE)
				printf("DELETE: %s\n", event->name);
			if (event->mask & IN_MODIFY)
				printf("MODIFY: %s\n", event->name);
			if (event->mask & IN_OPEN)
				printf("OPEN: %s\n", event->name);
			if (event->mask & IN_CLOSE)
				printf("CLOSE: %s\n", event->name);

			i += EVENT_SIZE + event->len;
		}
	}

	inotify_rm_watch(fd, wd);
	close(fd);

	return 0;
}

static char *__walk_overlay_dir(int dirfd, const char *base,
				unsigned int s_dev,
				unsigned long i_ino, int depth,
				unsigned long *visited)
{
	DIR *dfd;
	struct dirent *de;
	char *found = NULL;

	if (depth <= 0) {
		close(dirfd);
		return NULL;
	}

	dfd = fdopendir(dirfd);
	if (!dfd) {
		pr_perror("Can't fdopendir for overlay walk");
		close(dirfd);
		return NULL;
	}

	while (1) {
		struct stat st;

		errno = 0;
		de = readdir(dfd);
		if (!de)
			break;

		if (dir_dots(de))
			continue;

		if (fstatat(dirfd, de->d_name, &st,
			    AT_SYMLINK_NOFOLLOW) < 0) {
			pr_debug("overlay walk: fstatat(%s/%s) failed: %s\n",
				 base, de->d_name, strerror(errno));
			continue;
		}

		(*visited)++;
		if (*visited == OVL_WALK_WARN_THRESHOLD)
			pr_warn("overlay walk: examined %lu entries so far "
				"looking for ino %lx, mount may be large\n",
				*visited, i_ino);

		if (MKKDEV(major(st.st_dev), minor(st.st_dev)) == s_dev &&
		    st.st_ino == i_ino) {
			found = xsprintf("%s/%s", base, de->d_name);
			if (!found)
				pr_err("OOM building overlay path for ino %lx\n",
				       i_ino);
			break;
		}

		if (S_ISDIR(st.st_mode)) {
			int subfd;
			char *subbase;

			subfd = openat(dirfd, de->d_name,
				       O_RDONLY | O_DIRECTORY | O_CLOEXEC);
			if (subfd < 0)
				continue;

			subbase = xsprintf("%s/%s", base, de->d_name);
			if (!subbase) {
				close(subfd);
				continue;
			}

			found = __walk_overlay_dir(subfd, subbase,
						   s_dev, i_ino,
						   depth - 1,
						   visited);
			xfree(subbase);
			if (found)
				break;
		}
	}

	if (!de && errno)
		pr_perror("overlay walk: readdir failed on %s", base);

	closedir(dfd);
	return found;
}

static char *find_path_on_overlay(struct mount_info *m,
				  unsigned int s_dev,
				  unsigned long i_ino)
{
	int root_fd, mount_fd;
	unsigned long visited = 0;
	char *base, *found;
	struct stat st;

	root_fd = mntns_get_root_fd(m->nsid);
	if (root_fd < 0)
		return NULL;

	/*
	 * ns_mountpoint has a leading dot, e.g. "./tmp/merged",
	 * which makes it relative to mntns root for openat.
	 */
	mount_fd = openat(root_fd, m->ns_mountpoint, O_RDONLY | O_DIRECTORY);
	if (mount_fd < 0) {
		pr_perror("Can't open overlay mountpoint %s",
			  m->ns_mountpoint);
		return NULL;
	}

	/*
	 * The path stored in f_handle->path must be absolute so
	 * that get_mark_path() can strip the leading "/" and use
	 * openat(mntns_root, path + 1, O_PATH) on restore.
	 * ns_mountpoint + 1 gives us e.g. "/tmp/merged".
	 */
	base = m->ns_mountpoint + 1;

	/* Check if the mountpoint directory itself is the target */
	if (fstat(mount_fd, &st) == 0 &&
	    MKKDEV(major(st.st_dev), minor(st.st_dev)) == s_dev &&
	    st.st_ino == i_ino) {
		close(mount_fd);
		return xstrdup(base);
	}

	found = __walk_overlay_dir(mount_fd, base, s_dev, i_ino,
				   OVL_WALK_MAX_DEPTH, &visited);
	/* mount_fd is consumed by fdopendir inside __walk_overlay_dir */

	if (found)
		pr_debug("overlay walk: found ino %lx after %lu entries\n",
			 i_ino, visited);

	return found;
}

int main(int argc, char **argv)
{
	task_waiter_t lock;
	void *mem;
	pid_t pid;
	int status;
	uint32_t crc;

	test_init(argc, argv);
	task_waiter_init(&lock);

	/* Parent: reserve the range and never write to it. */
	mem = mmap(NULL, MEM_SIZE, PROT_NONE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	if (mem == MAP_FAILED) {
		pr_perror("Can't reserve memory");
		return 1;
	}

	pid = test_fork();
	if (pid < 0) {
		pr_perror("Can't fork");
		return 1;
	}

	if (pid == 0) {
		/* Child: make the reservation writable and fill it. */
		crc = ~0;

		if (mprotect(mem, MEM_SIZE, PROT_READ | PROT_WRITE)) {
			pr_perror("Child can't mprotect");
			return 1;
		}
		datagen(mem, MEM_SIZE, &crc);

		/* Ready for C/R. */
		task_waiter_complete(&lock, 1);

		/* Wait until the parent has been restored. */
		task_waiter_wait4(&lock, 2);

		crc = ~0;
		if (datachk(mem, MEM_SIZE, &crc)) {
			fail("Child data corrupted after restore");
			return 1;
		}
		return 0;
	}

	/* Parent: wait for the child to populate its copy, stay PROT_NONE. */
	task_waiter_wait4(&lock, 1);

	test_daemon();
	test_waitsig();

	/* Restore succeeded -- let the child verify its content. */
	task_waiter_complete(&lock, 2);

	if (waitpid(pid, &status, 0) != pid) {
		pr_perror("Can't wait for the child");
		return 1;
	}

	if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
		fail("Child exited abnormally (status %d)", status);
		return 1;
	}

	pass();
	return 0;
}

void
tp_segment_log_dirty_buffer(Relation index, Buffer buffer)
{
	START_CRIT_SECTION();
	MarkBufferDirty(buffer);
	if (RelationNeedsWAL(index))
		log_newpage_buffer(buffer, false);
	END_CRIT_SECTION();
}

void
tp_topk_init(TpTopKHeap *heap, int k, MemoryContext ctx)
{
	MemoryContext old_ctx = MemoryContextSwitchTo(ctx);

	heap->ctids	   = palloc(k * sizeof(ItemPointerData));
	heap->scores   = palloc(k * sizeof(float4));
	heap->capacity = k;
	heap->size	   = 0;

	MemoryContextSwitchTo(old_ctx);
}

void
tp_topk_free(TpTopKHeap *heap)
{
	if (heap->ctids)
	{
		pfree(heap->ctids);
		heap->ctids = NULL;
	}
	if (heap->scores)
	{
		pfree(heap->scores);
		heap->scores = NULL;
	}
	heap->capacity = 0;
	heap->size	   = 0;
}

static inline void
heap_swap(TpTopKHeap *heap, int i, int j)
{
	ItemPointerData tmp_ctid  = heap->ctids[i];
	float4			tmp_score = heap->scores[i];

	heap->ctids[i]	= heap->ctids[j];
	heap->scores[i] = heap->scores[j];
	heap->ctids[j]	= tmp_ctid;
	heap->scores[j] = tmp_score;
}

static inline bool
heap_less(TpTopKHeap *heap, int a, int b)
{
	if (heap->scores[a] != heap->scores[b])
		return heap->scores[a] < heap->scores[b];
	/* Tiebreaker: higher CTID is "smaller" for heap purposes */
	return ItemPointerCompare(&heap->ctids[a], &heap->ctids[b]) > 0;
}

static void
heap_sift_up(TpTopKHeap *heap, int i)
{
	while (i > 0)
	{
		int parent = (i - 1) / 2;
		if (heap_less(heap, parent, i) ||
			(!heap_less(heap, i, parent) && parent <= i))
			break;
		heap_swap(heap, i, parent);
		i = parent;
	}
}

static void
heap_sift_down(TpTopKHeap *heap, int i)
{
	while (true)
	{
		int left	 = 2 * i + 1;
		int right	 = 2 * i + 2;
		int smallest = i;

		if (left < heap->size && heap_less(heap, left, smallest))
			smallest = left;
		if (right < heap->size && heap_less(heap, right, smallest))
			smallest = right;

		if (smallest == i)
			break;

		heap_swap(heap, i, smallest);
		i = smallest;
	}
}

void
tp_topk_add(TpTopKHeap *heap, ItemPointerData ctid, float4 score)
{
	if (heap->size < heap->capacity)
	{
		/* Heap not full - just add */
		int i			= heap->size++;
		heap->ctids[i]	= ctid;
		heap->scores[i] = score;
		heap_sift_up(heap, i);
	}
	else if (
			score > heap->scores[0] ||
			(score == heap->scores[0] &&
			 ItemPointerCompare(&ctid, &heap->ctids[0]) < 0))
	{
		/*
		 * Heap full but new entry should replace root:
		 * - Score beats minimum, OR
		 * - Score equals minimum but new CTID is lower (we want to keep
		 *   docs with lower CTIDs, so evict higher CTID at root)
		 */
		heap->ctids[0]	= ctid;
		heap->scores[0] = score;
		heap_sift_down(heap, 0);
	}
	/* else: doesn't qualify for top-k, ignore */
}

int
tp_topk_extract(TpTopKHeap *heap, ItemPointerData *ctids, float4 *scores)
{
	int count = heap->size;

	/* Heapsort in place */
	while (heap->size > 0)
	{
		heap->size--;
		heap_swap(heap, 0, heap->size);
		heap_sift_down(heap, 0);
	}

	/* Copy to output - heapsort already produced descending order */
	for (int i = 0; i < count; i++)
	{
		ctids[i]  = heap->ctids[i];
		scores[i] = heap->scores[i];
	}

	return count;
}

float4
tp_compute_block_max_score(
		TpSkipEntry *skip, float4 idf, float4 k1, float4 b, float4 avg_doc_len)
{
	float4 tf = (float4)skip->block_max_tf;
	float4 dl = (float4)decode_fieldnorm(skip->block_max_norm);

	/* BM25 formula with max TF and min doc length in block */
	float4 len_norm		= 1.0f - b + b * (dl / avg_doc_len);
	float4 tf_component = (tf * (k1 + 1.0f)) / (tf + k1 * len_norm);

	return idf * tf_component;
}

static inline float4
compute_bm25_score(
		float4 idf,
		int32  tf,
		int32  doc_len,
		float4 k1,
		float4 b,
		float4 avg_doc_len)
{
	float4 len_norm		= 1.0f - b + b * ((float4)doc_len / avg_doc_len);
	float4 tf_component = ((float4)tf * (k1 + 1.0f)) /
						  ((float4)tf + k1 * len_norm);

	return idf * tf_component;
}

static void
score_memtable_single_term(
		TpTopKHeap		  *heap,
		TpLocalIndexState *local_state,
		const char		  *term,
		float4			   idf,
		float4			   k1,
		float4			   b,
		float4			   avg_doc_len,
		TpBMWStats		  *stats)
{
	TpDataSource  *source;
	TpPostingData *postings;
	int			   i;

	/* Create memtable data source */
	source = tp_memtable_source_create(local_state);
	if (!source)
		return;

	/* Get postings for this term */
	postings = tp_source_get_postings(source, term);
	if (!postings || postings->count == 0)
	{
		if (postings)
			tp_source_free_postings(source, postings);
		tp_source_close(source);
		return;
	}

	/* Score each posting */
	for (i = 0; i < postings->count; i++)
	{
		ItemPointerData *ctid = &postings->ctids[i];
		int32			 tf	  = postings->frequencies[i];
		int32			 doc_len;
		float4			 score;

		/* Get document length */
		doc_len = tp_source_get_doc_length(source, ctid);
		if (doc_len <= 0)
			doc_len = 1; /* Fallback for missing entries */

		score = compute_bm25_score(idf, tf, doc_len, k1, b, avg_doc_len);

		if (!tp_topk_dominated(heap, score))
			tp_topk_add(heap, *ctid, score);

		if (stats)
			stats->memtable_docs++;
	}

	tp_source_free_postings(source, postings);
	tp_source_close(source);
}

static void
score_segment_single_term_bmw(
		TpTopKHeap		*heap,
		TpSegmentReader *reader,
		const char		*term,
		float4			 idf,
		float4			 k1,
		float4			 b,
		float4			 avg_doc_len,
		TpBMWStats		*stats)
{
	TpSegmentPostingIterator iter;
	TpSegmentPosting		*posting;
	TpDictEntry				*dict_entry;
	uint16					 block_count;
	float4					*block_max_scores;
	uint16					 i;

	/* Initialize iterator for this term */
	if (!tp_segment_posting_iterator_init(&iter, reader, term))
		return; /* Term not found in segment */

	/* Get dictionary entry for block count and skip index */
	dict_entry	= &iter.dict_entry;
	block_count = dict_entry->block_count;

	/* Pre-compute block max scores */
	block_max_scores = palloc(block_count * sizeof(float4));
	for (i = 0; i < block_count; i++)
	{
		TpSkipEntry skip;
		tp_segment_read_skip_entry(reader, dict_entry, i, &skip);
		block_max_scores[i] =
				tp_compute_block_max_score(&skip, idf, k1, b, avg_doc_len);
	}

	/* Process blocks with BMW */
	for (i = 0; i < block_count; i++)
	{
		float4 threshold = tp_topk_threshold(heap);
		float4 block_max = block_max_scores[i];

		/* Skip block if it can't beat threshold */
		if (block_max < threshold)
		{
			if (stats)
				stats->blocks_skipped++;
			continue;
		}

		if (stats)
			stats->blocks_scanned++;

		/* Load and score this block */
		iter.current_block = i;
		iter.finished	   = false; /* Reset so we can process this block */
		tp_segment_posting_iterator_load_block(&iter);

		while (tp_segment_posting_iterator_next(&iter, &posting))
		{
			float4 score;

			/*
			 * Break if iterator auto-advanced to next block.
			 * This ensures we only process block i, allowing the outer
			 * for loop to apply threshold checks to subsequent blocks.
			 */
			if (iter.current_block != i)
				break;

			score = compute_bm25_score(
					idf,
					posting->frequency,
					posting->doc_length,
					k1,
					b,
					avg_doc_len);

			if (!tp_topk_dominated(heap, score))
			{
				tp_topk_add(heap, posting->ctid, score);
			}

			if (stats)
				stats->segment_docs_scored++;
		}
	}

	pfree(block_max_scores);
	tp_segment_posting_iterator_free(&iter);
}

int
tp_score_single_term_bmw(
		TpLocalIndexState *local_state,
		Relation		   index,
		const char		  *term,
		float4			   idf,
		float4			   k1,
		float4			   b,
		float4			   avg_doc_len,
		int				   max_results,
		ItemPointerData	  *result_ctids,
		float4			  *result_scores,
		TpBMWStats		  *stats)
{
	TpTopKHeap		heap;
	TpIndexMetaPage metap;
	BlockNumber		level_heads[TP_MAX_LEVELS];
	int				level;
	int				result_count;

	/* Initialize stats */
	if (stats)
		memset(stats, 0, sizeof(TpBMWStats));

	/* Initialize top-k heap */
	tp_topk_init(&heap, max_results, CurrentMemoryContext);

	/* Score memtable (exhaustive - no skip index) */
	score_memtable_single_term(
			&heap, local_state, term, idf, k1, b, avg_doc_len, stats);

	/* Get segment level heads from metapage */
	metap = tp_get_metapage(index);
	for (level = 0; level < TP_MAX_LEVELS; level++)
		level_heads[level] = metap->level_heads[level];
	pfree(metap);

	/* Score each segment level with BMW */
	for (level = 0; level < TP_MAX_LEVELS; level++)
	{
		BlockNumber seg_head = level_heads[level];

		while (seg_head != InvalidBlockNumber)
		{
			TpSegmentReader *reader = tp_segment_open(index, seg_head);

			score_segment_single_term_bmw(
					&heap, reader, term, idf, k1, b, avg_doc_len, stats);

			seg_head = reader->header->next_segment;
			tp_segment_close(reader);
		}
	}

	/* Extract sorted results */
	result_count = tp_topk_extract(&heap, result_ctids, result_scores);

	if (stats)
		stats->docs_in_results = result_count;

	return result_count;
}

static void
score_memtable_multi_term(
		TpTopKHeap		  *heap,
		TpLocalIndexState *local_state,
		TpTermState		  *terms,
		int				   term_count,
		float4			   k1,
		float4			   b,
		float4			   avg_doc_len,
		TpBMWStats		  *stats)
{
	TpDataSource *source;
	HTAB		 *doc_accum;
	HASHCTL		  hash_ctl;
	int			  term_idx;

	/* Create memtable data source */
	source = tp_memtable_source_create(local_state);
	if (!source)
		return;

	/* Create hash table for document score accumulation */
	memset(&hash_ctl, 0, sizeof(hash_ctl));
	hash_ctl.keysize   = sizeof(ItemPointerData);
	hash_ctl.entrysize = sizeof(DocumentScoreEntry);
	hash_ctl.hcxt	   = CurrentMemoryContext;
	doc_accum		   = hash_create(
			 "Memtable Doc Accum", 1024, &hash_ctl, HASH_ELEM | HASH_BLOBS);

	/* Process each term */
	for (term_idx = 0; term_idx < term_count; term_idx++)
	{
		TpTermState	  *ts = &terms[term_idx];
		TpPostingData *postings;
		int			   i;

		postings = tp_source_get_postings(source, ts->term);
		if (!postings || postings->count == 0)
		{
			if (postings)
				tp_source_free_postings(source, postings);
			continue;
		}

		/* Score each posting for this term */
		for (i = 0; i < postings->count; i++)
		{
			ItemPointerData	   *ctid = &postings->ctids[i];
			int32				tf	 = postings->frequencies[i];
			int32				doc_len;
			float4				term_score;
			DocumentScoreEntry *entry;
			bool				found;

			/* Get document length */
			doc_len = tp_source_get_doc_length(source, ctid);
			if (doc_len <= 0)
				doc_len = 1;

			/* Compute BM25 term contribution */
			term_score = compute_bm25_score(
								 ts->idf, tf, doc_len, k1, b, avg_doc_len) *
						 ts->query_freq;

			/* Accumulate in hash table */
			entry = (DocumentScoreEntry *)
					hash_search(doc_accum, ctid, HASH_ENTER, &found);

			if (!found)
			{
				entry->ctid		  = *ctid;
				entry->score	  = term_score;
				entry->doc_length = (float4)doc_len;
			}
			else
			{
				entry->score += term_score;
			}
		}

		tp_source_free_postings(source, postings);
	}

	/* Add accumulated documents to heap */
	{
		HASH_SEQ_STATUS		seq;
		DocumentScoreEntry *entry;

		hash_seq_init(&seq, doc_accum);
		while ((entry = hash_seq_search(&seq)) != NULL)
		{
			if (!tp_topk_dominated(heap, entry->score))
				tp_topk_add(heap, entry->ctid, entry->score);

			if (stats)
				stats->memtable_docs++;
		}
	}

	hash_destroy(doc_accum);
	tp_source_close(source);
}

static bool
advance_term_iterator(TpTermState *ts)
{
	ts->iter.current_in_block++;

	if (ts->iter.current_in_block >= ts->iter.skip_entry.doc_count)
	{
		ts->iter.current_block++;
		if (ts->iter.current_block >= ts->iter.dict_entry.block_count)
		{
			ts->iter.finished = true;
			return false;
		}
		ts->iter.current_in_block = 0;
		tp_segment_posting_iterator_load_block(&ts->iter);
	}
	return true;
}

static int
init_segment_term_states(
		TpTermState		*terms,
		int				 term_count,
		TpSegmentReader *reader,
		float4			 k1,
		float4			 b,
		float4			 avg_doc_len)
{
	int active_count = 0;
	int term_idx;

	for (term_idx = 0; term_idx < term_count; term_idx++)
	{
		TpTermState *ts = &terms[term_idx];

		ts->found			 = false;
		ts->block_max_scores = NULL;

		if (!tp_segment_posting_iterator_init(&ts->iter, reader, ts->term))
			continue;

		ts->found = true;

		/* Pre-compute block max scores for BMW threshold checks */
		if (ts->iter.dict_entry.block_count > 0)
		{
			uint16 block_idx;
			ts->block_max_scores = palloc(
					ts->iter.dict_entry.block_count * sizeof(float4));
			for (block_idx = 0; block_idx < ts->iter.dict_entry.block_count;
				 block_idx++)
			{
				TpSkipEntry skip;
				tp_segment_read_skip_entry(
						reader, &ts->iter.dict_entry, block_idx, &skip);
				ts->block_max_scores[block_idx] = tp_compute_block_max_score(
						&skip, ts->idf, k1, b, avg_doc_len);
			}
		}

		if (tp_segment_posting_iterator_load_block(&ts->iter))
			active_count++;
	}

	return active_count;
}

static void
cleanup_segment_term_states(TpTermState *terms, int term_count)
{
	int term_idx;

	for (term_idx = 0; term_idx < term_count; term_idx++)
	{
		if (terms[term_idx].found)
			tp_segment_posting_iterator_free(&terms[term_idx].iter);
		if (terms[term_idx].block_max_scores)
			pfree(terms[term_idx].block_max_scores);
	}
}

static uint32
find_pivot_doc_id(TpTermState *terms, int term_count)
{
	uint32 pivot = UINT32_MAX;
	int	   term_idx;

	for (term_idx = 0; term_idx < term_count; term_idx++)
	{
		TpTermState *ts = &terms[term_idx];
		uint32		 doc_id;

		if (!ts->found || ts->iter.finished)
			continue;

		doc_id = tp_segment_posting_iterator_current_doc_id(&ts->iter);
		if (doc_id < pivot)
			pivot = doc_id;
	}

	return pivot;
}

static float4
compute_pivot_max_score(
		TpTermState *terms, int term_count, uint32 pivot_doc_id)
{
	float4 max_possible = 0.0f;
	int	   term_idx;

	for (term_idx = 0; term_idx < term_count; term_idx++)
	{
		TpTermState *ts = &terms[term_idx];
		uint32		 doc_id;

		if (!ts->found || ts->iter.finished)
			continue;

		doc_id = tp_segment_posting_iterator_current_doc_id(&ts->iter);

		if (doc_id <= pivot_doc_id && ts->block_max_scores != NULL &&
			ts->iter.current_block < ts->iter.dict_entry.block_count)
		{
			max_possible += ts->block_max_scores[ts->iter.current_block] *
							ts->query_freq;
		}
	}

	return max_possible;
}

static float4
score_pivot_document(
		TpTermState		*terms,
		int				 term_count,
		uint32			 pivot_doc_id,
		TpSegmentReader *reader,
		float4			 k1,
		float4			 b,
		float4			 avg_doc_len,
		ItemPointerData *ctid_out,
		int				*active_count)
{
	float4 doc_score = 0.0f;
	bool   have_ctid = false;
	int	   term_idx;

	for (term_idx = 0; term_idx < term_count; term_idx++)
	{
		TpTermState *ts = &terms[term_idx];
		uint32		 doc_id;

		if (!ts->found || ts->iter.finished)
			continue;

		doc_id = tp_segment_posting_iterator_current_doc_id(&ts->iter);

		if (doc_id == pivot_doc_id)
		{
			TpBlockPosting *bp =
					&ts->iter.block_postings[ts->iter.current_in_block];
			float4 term_score = compute_bm25_score(
										ts->idf,
										bp->frequency,
										(int32)decode_fieldnorm(bp->fieldnorm),
										k1,
										b,
										avg_doc_len) *
								ts->query_freq;

			doc_score += term_score;

			if (!have_ctid)
			{
				Assert(reader->cached_ctid_pages != NULL);
				Assert(pivot_doc_id < reader->cached_num_docs);
				ItemPointerSet(
						ctid_out,
						reader->cached_ctid_pages[pivot_doc_id],
						reader->cached_ctid_offsets[pivot_doc_id]);
				have_ctid = true;
			}

			if (!advance_term_iterator(ts))
				(*active_count)--;
		}
	}

	if (!have_ctid)
		ItemPointerSetInvalid(ctid_out);

	return doc_score;
}

static void
skip_pivot_document(
		TpTermState *terms,
		int			 term_count,
		uint32		 pivot_doc_id,
		int			*active_count)
{
	int term_idx;

	for (term_idx = 0; term_idx < term_count; term_idx++)
	{
		TpTermState *ts = &terms[term_idx];
		uint32		 doc_id;

		if (!ts->found || ts->iter.finished)
			continue;

		doc_id = tp_segment_posting_iterator_current_doc_id(&ts->iter);
		if (doc_id == pivot_doc_id)
		{
			if (!advance_term_iterator(ts))
				(*active_count)--;
		}
	}
}

static void
score_segment_multi_term_bmw(
		TpTopKHeap		*heap,
		TpSegmentReader *reader,
		TpTermState		*terms,
		int				 term_count,
		float4			 k1,
		float4			 b,
		float4			 avg_doc_len,
		TpBMWStats		*stats)
{
	int active_count;

	active_count = init_segment_term_states(
			terms, term_count, reader, k1, b, avg_doc_len);

	/* WAND-style doc-ID ordered traversal */
	while (active_count > 0)
	{
		uint32			pivot_doc_id;
		float4			max_possible;
		float4			threshold;
		ItemPointerData pivot_ctid;
		float4			doc_score;

		pivot_doc_id = find_pivot_doc_id(terms, term_count);
		if (pivot_doc_id == UINT32_MAX)
			break;

		threshold = tp_topk_threshold(heap);
		max_possible =
				compute_pivot_max_score(terms, term_count, pivot_doc_id);

		if (max_possible < threshold)
		{
			skip_pivot_document(
					terms, term_count, pivot_doc_id, &active_count);
			if (stats)
				stats->blocks_skipped++;
			continue;
		}

		if (stats)
			stats->blocks_scanned++;

		doc_score = score_pivot_document(
				terms,
				term_count,
				pivot_doc_id,
				reader,
				k1,
				b,
				avg_doc_len,
				&pivot_ctid,
				&active_count);

		if (ItemPointerIsValid(&pivot_ctid) &&
			!tp_topk_dominated(heap, doc_score))
			tp_topk_add(heap, pivot_ctid, doc_score);

		if (stats)
			stats->segment_docs_scored++;
	}

	cleanup_segment_term_states(terms, term_count);
}

int
tp_score_multi_term_bmw(
		TpLocalIndexState *local_state,
		Relation		   index,
		char			 **query_terms,
		int				   term_count,
		int32			  *query_freqs,
		float4			  *idfs,
		float4			   k1,
		float4			   b,
		float4			   avg_doc_len,
		int				   max_results,
		ItemPointerData	  *result_ctids,
		float4			  *result_scores,
		TpBMWStats		  *stats)
{
	TpTopKHeap		heap;
	TpIndexMetaPage metap;
	BlockNumber		level_heads[TP_MAX_LEVELS];
	TpTermState	   *terms;
	int				level;
	int				result_count;
	int				i;

	/* Initialize stats */
	if (stats)
		memset(stats, 0, sizeof(TpBMWStats));

	/* Initialize top-k heap */
	tp_topk_init(&heap, max_results, CurrentMemoryContext);

	/* Initialize term states */
	terms = palloc(term_count * sizeof(TpTermState));
	for (i = 0; i < term_count; i++)
	{
		terms[i].term		= query_terms[i];
		terms[i].idf		= idfs[i];
		terms[i].query_freq = query_freqs[i];
	}

	/* Score memtable (exhaustive - no skip index) */
	score_memtable_multi_term(
			&heap, local_state, terms, term_count, k1, b, avg_doc_len, stats);

	/* Get segment level heads from metapage */
	metap = tp_get_metapage(index);
	for (level = 0; level < TP_MAX_LEVELS; level++)
		level_heads[level] = metap->level_heads[level];
	pfree(metap);

	/* Score each segment with block-based BMW */
	for (level = 0; level < TP_MAX_LEVELS; level++)
	{
		BlockNumber seg_head = level_heads[level];

		while (seg_head != InvalidBlockNumber)
		{
			TpSegmentReader *reader = tp_segment_open(index, seg_head);

			score_segment_multi_term_bmw(
					&heap,
					reader,
					terms,
					term_count,
					k1,
					b,
					avg_doc_len,
					stats);

			seg_head = reader->header->next_segment;
			tp_segment_close(reader);
		}
	}

	pfree(terms);

	/* Extract sorted results */
	result_count = tp_topk_extract(&heap, result_ctids, result_scores);

	if (stats)
		stats->docs_in_results = result_count;

	return result_count;
}

static uint32
tp_get_unified_doc_freq(
		TpLocalIndexState *local_state,
		Relation		   index,
		const char		  *term,
		BlockNumber		  *level_heads)
{
	uint32		   doc_freq = 0;
	TpPostingList *posting_list;
	int			   level;

	/* Get doc_freq from memtable */
	posting_list = tp_get_posting_list(local_state, term);
	if (posting_list && posting_list->doc_count > 0)
		doc_freq = posting_list->doc_count;

	/* Add doc_freq from all segment levels */
	for (level = 0; level < TP_MAX_LEVELS; level++)
	{
		if (level_heads[level] != InvalidBlockNumber)
		{
			doc_freq +=
					tp_segment_get_doc_freq(index, level_heads[level], term);
		}
	}

	return doc_freq;
}

static void
tp_batch_get_unified_doc_freq(
		TpLocalIndexState *local_state,
		Relation		   index,
		char			 **terms,
		int				   term_count,
		BlockNumber		  *level_heads,
		uint32			  *doc_freqs)
{
	int level;
	int i;

	/* Initialize doc_freqs with memtable counts */
	for (i = 0; i < term_count; i++)
	{
		TpPostingList *posting_list =
				tp_get_posting_list(local_state, terms[i]);
		doc_freqs[i] = (posting_list && posting_list->doc_count > 0)
							 ? posting_list->doc_count
							 : 0;
	}

	/* Add doc_freq from all segment levels (batch lookup) */
	for (level = 0; level < TP_MAX_LEVELS; level++)
	{
		if (level_heads[level] != InvalidBlockNumber)
		{
			tp_batch_get_segment_doc_freq(
					index, level_heads[level], terms, term_count, doc_freqs);
		}
	}
}

void
/*
 * Get current doc ID from iterator.
 * Returns UINT32_MAX if iterator is finished or not positioned.
 */
uint32
tp_segment_posting_iterator_current_doc_id(TpSegmentPostingIterator *iter)
{
	if (iter->finished || !iter->initialized || iter->block_postings == NULL)
		return UINT32_MAX;

	if (iter->current_in_block >= iter->skip_entry.doc_count)
		return UINT32_MAX;

	return iter->block_postings[iter->current_in_block].doc_id;
}

bool
tp_segment_posting_iterator_seek(
		TpSegmentPostingIterator *iter,
		uint32					  target_doc_id,
		TpSegmentPosting		**posting)
{
	uint16		block_count;
	int			left, right, mid;
	uint16		target_block;
	TpSkipEntry skip;

	if (!iter->initialized || iter->finished)
		return false;

	block_count = iter->dict_entry.block_count;

	/*
	 * Binary search skip entries to find block containing target_doc_id.
	 * Each skip entry has last_doc_id = maximum doc ID in that block.
	 * We want the first block where last_doc_id >= target_doc_id.
	 */
	left  = 0;
	right = block_count - 1;

	while (left < right)
	{
		mid = left + (right - left) / 2;

		/* Read skip entry to get last_doc_id */
		tp_segment_read_skip_entry(
				iter->reader, &iter->dict_entry, mid, &skip);

		if (skip.last_doc_id < target_doc_id)
		{
			/* Target is past this block */
			left = mid + 1;
		}
		else
		{
			/* Target might be in this block or earlier */
			right = mid;
		}
	}

	target_block = left;

	/* Check if target is past all blocks */
	if (target_block >= block_count)
	{
		iter->finished = true;
		return false;
	}

	/* Load the target block */
	iter->current_block	   = target_block;
	iter->current_in_block = 0;
	iter->finished		   = false;

	if (!tp_segment_posting_iterator_load_block(iter))
	{
		iter->finished = true;
		return false;
	}

	/* Linear scan within block to find target or first doc >= target */
	while (iter->current_in_block < iter->skip_entry.doc_count)
	{
		TpBlockPosting *bp = &iter->block_postings[iter->current_in_block];

		if (bp->doc_id >= target_doc_id)
		{
			/* Found it - convert to output posting */
			Assert(iter->reader->cached_ctid_pages != NULL);
			Assert(bp->doc_id < iter->reader->cached_num_docs);

			ItemPointerSet(
					&iter->output_posting.ctid,
					iter->reader->cached_ctid_pages[bp->doc_id],
					iter->reader->cached_ctid_offsets[bp->doc_id]);

			iter->output_posting.frequency	= bp->frequency;
			iter->output_posting.doc_length = (uint16)decode_fieldnorm(
					bp->fieldnorm);

			*posting = &iter->output_posting;
			return true;
		}

		iter->current_in_block++;
	}

	/*
	 * Exhausted this block without finding target.
	 * This shouldn't happen if last_doc_id was correct, but handle it
	 * by moving to next block and trying next().
	 */
	iter->current_block++;
	if (iter->current_block >= block_count)
	{
		iter->finished = true;
		return false;
	}

	/* Load next block and return first posting */
	iter->current_in_block = 0;
	return tp_segment_posting_iterator_next(iter, posting);
}

static void
score_term_postings(
		TpSegmentPostingIterator *iter,
		float4					  idf,
		float4					  query_freq,
		float4					  k1,
		float4					  b,
		float4					  avg_doc_len,
		HTAB					 *hash_table)
{
	TpSegmentPosting *posting;

	while (tp_segment_posting_iterator_next(iter, &posting))
	{
		process_posting(
				posting, idf, query_freq, k1, b, avg_doc_len, hash_table);
	}
}

static void
score_segment_for_all_terms(
		TpSegmentReader *reader,
		char		   **terms,
		int				 term_count,
		int32			*query_frequencies,
		uint32			*doc_freqs,
		int32			 total_docs,
		float4			 k1,
		float4			 b,
		float4			 avg_doc_len,
		HTAB			*hash_table)
{
	for (int term_idx = 0; term_idx < term_count; term_idx++)
	{
		TpSegmentPostingIterator iter;
		float4					 idf;

		if (!tp_segment_posting_iterator_init(&iter, reader, terms[term_idx]))
			continue;

		/* Accumulate doc_freq */
		doc_freqs[term_idx] += iter.dict_entry.doc_freq;

		/* Calculate IDF with current accumulated doc_freq */
		idf = tp_calculate_idf(doc_freqs[term_idx], total_docs);

		/* Process all postings for this term */
		score_term_postings(
				&iter,
				idf,
				(float4)query_frequencies[term_idx],
				k1,
				b,
				avg_doc_len,
				hash_table);

		tp_segment_posting_iterator_free(&iter);
	}
}

void
tp_score_all_terms_in_segment_chain(
		Relation	index,
		BlockNumber first_segment,
		char	  **terms,
		int			term_count,
		int32	   *query_frequencies,
		uint32	   *doc_freqs, /* OUT: filled with segment doc_freqs */
		int32		total_docs,
		float4		k1,
		float4		b,
		float4		avg_doc_len,
		void	   *doc_scores_hash)
{
	BlockNumber current	   = first_segment;
	HTAB	   *hash_table = (HTAB *)doc_scores_hash;

	while (current != InvalidBlockNumber)
	{
		TpSegmentReader *reader = tp_segment_open(index, current);
		if (!reader)
			break;

		score_segment_for_all_terms(
				reader,
				terms,
				term_count,
				query_frequencies,
				doc_freqs,
				total_docs,
				k1,
				b,
				avg_doc_len,
				hash_table);

		current = reader->header->next_segment;
		tp_segment_close(reader);
	}
}

static bool
tp_has_child_tables(Relation heap)
{
	bool		  has_children = false;
	Oid			  heap_oid	   = RelationGetRelid(heap);
	int			  spi_result;
	SPIPlanPtr	  plan = NULL;
	Datum		  values[1];
	char		 *nulls			= " "; /* No nulls */
	volatile bool spi_connected = false;

	/* First check if it's a partitioned table (quick check) */
	if (heap->rd_rel->relkind == RELKIND_PARTITIONED_TABLE)
		return true;

	/* Check for table inheritance using pg_inherits */
	PG_TRY();
	{
		spi_result	  = SPI_connect();
		spi_connected = (spi_result == SPI_OK_CONNECT);

		if (!spi_connected)
			elog(ERROR, "SPI_connect failed");

		/* Query to check if this table has any children */
		const char *query = "SELECT 1 FROM pg_catalog.pg_inherits "
							"WHERE inhparent = $1 LIMIT 1";

		/* Prepare the plan */
		Oid argtypes[1] = {OIDOID};
		plan			= SPI_prepare(query, 1, argtypes);

		if (plan == NULL)
			elog(ERROR, "SPI_prepare failed");

		values[0] = ObjectIdGetDatum(heap_oid);

		/* Execute the query */
		spi_result = SPI_execute_plan(plan, values, nulls, true, 1);

		if (spi_result == SPI_OK_SELECT && SPI_processed > 0)
			has_children = true;

		/* Clean up SPI */
		if (plan)
			SPI_freeplan(plan);
		SPI_finish();
		spi_connected = false;
	}
	PG_CATCH();
	{
		/* Make sure to finish SPI connection if it was established */
		if (spi_connected)
		{
			SPI_finish();
		}
		/* Re-throw the error */
		PG_RE_THROW();
	}
	PG_END_TRY();

	return has_children;
}

static int setup_streams(struct test_ctx *ctx)
{
	int i;

	for (i = 0; i < NR_STREAMS; i++) {
		int fds[2];
		int ret;

		ret = t_create_socket_pair(fds, true);
		if (ret) {
			fprintf(stderr, "socket pair %d: %d\n", i, ret);
			/* cleanup already created pairs */
			while (--i >= 0) {
				close(ctx->streams[i].recv_fd);
				close(ctx->streams[i].send_fd);
			}
			return -1;
		}
		ctx->streams[i].recv_fd = fds[0];
		ctx->streams[i].send_fd = fds[1];
		ctx->streams[i].bytes_sent = 0;
		ctx->streams[i].bytes_recv = 0;
	}

	return 0;
}

static void close_streams(struct test_ctx *ctx)
{
	int i;

	for (i = 0; i < NR_STREAMS; i++) {
		close(ctx->streams[i].recv_fd);
		close(ctx->streams[i].send_fd);
	}
}

static int setup_buf_ring(struct test_ctx *ctx, int nr_bufs)
{
	int ret, i;

	ctx->nr_bufs = nr_bufs;
	ctx->buf_base = malloc(nr_bufs * BUF_SIZE);
	if (!ctx->buf_base)
		return -ENOMEM;

	ctx->br = io_uring_setup_buf_ring(&ctx->ring, nr_bufs, BGID, 0, &ret);
	if (!ctx->br) {
		free(ctx->buf_base);
		ctx->buf_base = NULL;
		if (ret == -EINVAL || ret == -ENOENT)
			return ret;
		fprintf(stderr, "buf ring setup: %d\n", ret);
		return ret;
	}

	for (i = 0; i < nr_bufs; i++) {
		io_uring_buf_ring_add(ctx->br, ctx->buf_base + i * BUF_SIZE,
				      BUF_SIZE, i,
				      io_uring_buf_ring_mask(nr_bufs), i);
	}
	io_uring_buf_ring_advance(ctx->br, nr_bufs);

	return 0;
}

static void cleanup_buf_ring(struct test_ctx *ctx)
{
	if (ctx->br) {
		io_uring_free_buf_ring(&ctx->ring, ctx->br, ctx->nr_bufs, BGID);
		ctx->br = NULL;
	}
	free(ctx->buf_base);
	ctx->buf_base = NULL;
}

static void recycle_buffer(struct test_ctx *ctx, int bid)
{
	io_uring_buf_ring_add(ctx->br,
			      ctx->buf_base + bid * BUF_SIZE,
			      BUF_SIZE, bid,
			      io_uring_buf_ring_mask(ctx->nr_bufs), 0);
	io_uring_buf_ring_advance(ctx->br, 1);
}

static void arm_recv(struct io_uring *ring, int fd, int stream_id)
{
	struct io_uring_sqe *sqe;

	sqe = io_uring_get_sqe(ring);
	io_uring_prep_recv_multishot(sqe, fd, NULL, 0, 0);
	sqe->buf_group = BGID;
	sqe->flags |= IOSQE_BUFFER_SELECT;
	io_uring_sqe_set_data64(sqe, UDATA_STREAM(stream_id));
}

static void *sender_fn(void *data)
{
	struct sender_ctx *sc = data;
	struct stream *s = sc->stream;
	char buf[SEND_SIZE];
	int i;

	memset(buf, sc->stream_id & 0xff, sizeof(buf));

	pthread_barrier_wait(sc->barrier);

	for (i = 0; i < s->nr_sends; i++) {
		int ret = send(s->send_fd, buf, sizeof(buf), 0);

		if (ret < 0)
			break;
		s->bytes_sent += ret;
	}

	shutdown(s->send_fd, SHUT_WR);
	return NULL;
}

static int test_shared_basic(void)
{
	int sends[NR_STREAMS];
	int i;

	for (i = 0; i < NR_STREAMS; i++)
		sends[i] = NR_SENDS;

	return run_shared_test(NR_BUFS_BASIC, sends);
}

static int test_shared_exhaust(void)
{
	int sends[NR_STREAMS];
	int i;

	if (no_buf_ring || no_mshot_recv)
		return T_EXIT_SKIP;

	for (i = 0; i < NR_STREAMS; i++)
		sends[i] = NR_SENDS_EXHAUST;

	return run_shared_test(NR_BUFS_SMALL, sends);
}

static int test_shared_uneven(void)
{
	int sends[NR_STREAMS];
	int i;

	if (no_buf_ring || no_mshot_recv)
		return T_EXIT_SKIP;

	sends[0] = NR_SENDS_BIG;
	for (i = 1; i < NR_STREAMS; i++)
		sends[i] = NR_SENDS_SMALL;

	return run_shared_test(NR_BUFS_BASIC, sends);
}

int main(int argc, char *argv[])
{
	int ret;

	if (argc > 1)
		return T_EXIT_SKIP;

	ret = test_shared_basic();
	if (ret == T_EXIT_SKIP) {
		printf("Buffer rings or multishot recv not supported, skipping\n");
		return T_EXIT_SKIP;
	}
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_shared_basic failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_shared_exhaust();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_shared_exhaust failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_shared_uneven();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_shared_uneven failed\n");
		return T_EXIT_FAIL;
	}

	return T_EXIT_PASS;
}

static int create_listen_sock(struct sockaddr_in *addr)
{
	int fd, ret, val = 1;

	fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, IPPROTO_TCP);
	if (fd < 0) {
		perror("socket");
		return -1;
	}

	setsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &val, sizeof(val));
	setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &val, sizeof(val));

	addr->sin_family = AF_INET;
	addr->sin_addr.s_addr = inet_addr("127.0.0.1");
	ret = t_bind_ephemeral_port(fd, addr);
	if (ret) {
		close(fd);
		return -1;
	}

	ret = listen(fd, 256);
	if (ret < 0) {
		perror("listen");
		close(fd);
		return -1;
	}

	return fd;
}

static int arm_mshot_accept(struct io_uring *ring, int listen_fd)
{
	struct io_uring_sqe *sqe;

	sqe = io_uring_get_sqe(ring);
	if (!sqe)
		return -1;
	io_uring_prep_multishot_accept(sqe, listen_fd, NULL, NULL, 0);
	io_uring_sqe_set_data64(sqe, MSHOT_UDATA);
	return io_uring_submit(ring);
}

static void *stress_client_fn(void *data)
{
	struct stress_ctx *ctx = data;
	int i;

	pthread_barrier_wait(&ctx->barrier);

	for (i = 0; i < ctx->nr_conns; i++) {
		int fd;

		fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
		if (fd < 0)
			break;
		if (connect(fd, (struct sockaddr *)&ctx->addr,
			    sizeof(ctx->addr)) < 0) {
			close(fd);
			break;
		}
		close(fd);
	}

	return NULL;
}

static int test_accept_mshot_stress(void)
{
	struct io_uring ring;
	struct stress_ctx ctx;
	pthread_t thread;
	int listen_fd, ret, accepted = 0;
	struct __kernel_timespec ts = { .tv_sec = 5 };

	ret = io_uring_queue_init(512, &ring, 0);
	if (ret) {
		fprintf(stderr, "ring setup: %d\n", ret);
		return T_EXIT_FAIL;
	}

	listen_fd = create_listen_sock(&ctx.addr);
	if (listen_fd < 0) {
		io_uring_queue_exit(&ring);
		return T_EXIT_FAIL;
	}

	ctx.nr_conns = NR_CONNS;
	pthread_barrier_init(&ctx.barrier, NULL, 2);

	ret = arm_mshot_accept(&ring, listen_fd);
	if (ret < 0) {
		fprintf(stderr, "arm accept: %d\n", ret);
		goto err;
	}

	pthread_create(&thread, NULL, stress_client_fn, &ctx);
	pthread_barrier_wait(&ctx.barrier);

	while (accepted < NR_CONNS) {
		struct io_uring_cqe *cqe;

		ret = io_uring_wait_cqe_timeout(&ring, &cqe, &ts);
		if (ret == -ETIME)
			break;
		if (ret) {
			fprintf(stderr, "wait: %d\n", ret);
			goto err_thread;
		}

		if (cqe->res == -EINVAL) {
			no_mshot_accept = 1;
			io_uring_cqe_seen(&ring, cqe);
			pthread_join(thread, NULL);
			close(listen_fd);
			io_uring_queue_exit(&ring);
			return T_EXIT_SKIP;
		}

		if (cqe->res < 0) {
			fprintf(stderr, "accept res: %d\n", cqe->res);
			io_uring_cqe_seen(&ring, cqe);
			goto err_thread;
		}

		close(cqe->res);
		accepted++;

		if (!(cqe->flags & IORING_CQE_F_MORE)) {
			io_uring_cqe_seen(&ring, cqe);
			arm_mshot_accept(&ring, listen_fd);
			continue;
		}

		io_uring_cqe_seen(&ring, cqe);
	}

	pthread_join(thread, NULL);

	if (accepted < NR_CONNS) {
		fprintf(stderr, "stress: accepted %d, expected %d\n",
			accepted, NR_CONNS);
		goto err;
	}

	close(listen_fd);
	io_uring_queue_exit(&ring);
	return T_EXIT_PASS;

err_thread:
	pthread_join(thread, NULL);
err:
	close(listen_fd);
	io_uring_queue_exit(&ring);
	return T_EXIT_FAIL;
}

static void *burst_client_fn(void *data)
{
	struct burst_ctx *ctx = data;
	int round;

	pthread_barrier_wait(&ctx->barrier);

	for (round = 0; round < ctx->nr_rounds; round++) {
		int fds[NR_BURST];
		int i;

		for (i = 0; i < ctx->nr_burst; i++) {
			fds[i] = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
			if (fds[i] < 0)
				break;
			if (connect(fds[i], (struct sockaddr *)&ctx->addr,
				    sizeof(ctx->addr)) < 0) {
				close(fds[i]);
				fds[i] = -1;
				break;
			}
		}

		/* Signal server: all connections are open */
		pthread_barrier_wait(&ctx->round_barrier);
		/* Wait for server to drain */
		pthread_barrier_wait(&ctx->round_barrier);

		for (i = 0; i < ctx->nr_burst; i++) {
			if (fds[i] >= 0)
				close(fds[i]);
		}
	}

	return NULL;
}

static int test_accept_mshot_burst(void)
{
	struct io_uring ring;
	struct burst_ctx ctx;
	pthread_t thread;
	int listen_fd, ret, total = 0;
	struct __kernel_timespec ts = { .tv_sec = 5 };

	if (no_mshot_accept)
		return T_EXIT_SKIP;

	ret = io_uring_queue_init(256, &ring, 0);
	if (ret) {
		fprintf(stderr, "ring setup: %d\n", ret);
		return T_EXIT_FAIL;
	}

	listen_fd = create_listen_sock(&ctx.addr);
	if (listen_fd < 0) {
		io_uring_queue_exit(&ring);
		return T_EXIT_FAIL;
	}

	ctx.nr_burst = NR_BURST;
	ctx.nr_rounds = NR_BURST_ROUNDS;
	pthread_barrier_init(&ctx.barrier, NULL, 2);
	pthread_barrier_init(&ctx.round_barrier, NULL, 2);

	ret = arm_mshot_accept(&ring, listen_fd);
	if (ret < 0)
		goto err;

	pthread_create(&thread, NULL, burst_client_fn, &ctx);
	pthread_barrier_wait(&ctx.barrier);

	for (int round = 0; round < NR_BURST_ROUNDS; round++) {
		int round_accepted = 0;

		/* Wait for client to open all connections */
		pthread_barrier_wait(&ctx.round_barrier);

		while (round_accepted < NR_BURST) {
			struct io_uring_cqe *cqe;

			ret = io_uring_wait_cqe_timeout(&ring, &cqe, &ts);
			if (ret == -ETIME) {
				fprintf(stderr, "burst round %d timeout at %d\n",
					round, round_accepted);
				goto err_thread;
			}
			if (ret) {
				fprintf(stderr, "wait: %d\n", ret);
				goto err_thread;
			}

			if (cqe->res < 0) {
				fprintf(stderr, "accept res: %d\n", cqe->res);
				io_uring_cqe_seen(&ring, cqe);
				goto err_thread;
			}

			close(cqe->res);
			round_accepted++;
			total++;

			if (!(cqe->flags & IORING_CQE_F_MORE)) {
				io_uring_cqe_seen(&ring, cqe);
				arm_mshot_accept(&ring, listen_fd);
				continue;
			}
			io_uring_cqe_seen(&ring, cqe);
		}

		/* Signal client: done draining */
		pthread_barrier_wait(&ctx.round_barrier);
	}

	pthread_join(thread, NULL);

	if (total != NR_BURST * NR_BURST_ROUNDS) {
		fprintf(stderr, "burst: accepted %d, expected %d\n",
			total, NR_BURST * NR_BURST_ROUNDS);
		goto err;
	}

	close(listen_fd);
	io_uring_queue_exit(&ring);
	return T_EXIT_PASS;

err_thread:
	pthread_join(thread, NULL);
err:
	close(listen_fd);
	io_uring_queue_exit(&ring);
	return T_EXIT_FAIL;
}

static void *reconnect_client_fn(void *data)
{
	struct reconnect_ctx *ctx = data;
	unsigned char byte = SEND_BYTE;
	int i;

	pthread_barrier_wait(&ctx->barrier);

	for (i = 0; i < ctx->nr_reconnects; i++) {
		int fd;

		fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
		if (fd < 0)
			break;
		if (connect(fd, (struct sockaddr *)&ctx->addr,
			    sizeof(ctx->addr)) < 0) {
			close(fd);
			break;
		}
		send(fd, &byte, 1, 0);
		close(fd);
	}

	return NULL;
}

static int test_accept_mshot_reconnect(void)
{
	struct io_uring ring;
	struct reconnect_ctx ctx;
	pthread_t thread;
	int listen_fd, ret, accepted = 0;
	struct __kernel_timespec ts = { .tv_sec = 5 };

	if (no_mshot_accept)
		return T_EXIT_SKIP;

	ret = io_uring_queue_init(512, &ring, 0);
	if (ret) {
		fprintf(stderr, "ring setup: %d\n", ret);
		return T_EXIT_FAIL;
	}

	listen_fd = create_listen_sock(&ctx.addr);
	if (listen_fd < 0) {
		io_uring_queue_exit(&ring);
		return T_EXIT_FAIL;
	}

	ctx.nr_reconnects = NR_RECONNECTS;
	pthread_barrier_init(&ctx.barrier, NULL, 2);

	ret = arm_mshot_accept(&ring, listen_fd);
	if (ret < 0)
		goto err;

	pthread_create(&thread, NULL, reconnect_client_fn, &ctx);
	pthread_barrier_wait(&ctx.barrier);

	while (accepted < NR_RECONNECTS) {
		struct io_uring_cqe *cqe;
		unsigned char buf;
		int conn_fd;

		ret = io_uring_wait_cqe_timeout(&ring, &cqe, &ts);
		if (ret == -ETIME)
			break;
		if (ret) {
			fprintf(stderr, "wait: %d\n", ret);
			goto err_thread;
		}

		if (cqe->res < 0) {
			fprintf(stderr, "accept res: %d\n", cqe->res);
			io_uring_cqe_seen(&ring, cqe);
			goto err_thread;
		}

		conn_fd = cqe->res;

		if (!(cqe->flags & IORING_CQE_F_MORE)) {
			io_uring_cqe_seen(&ring, cqe);
			arm_mshot_accept(&ring, listen_fd);
		} else {
			io_uring_cqe_seen(&ring, cqe);
		}

		/* Read the byte the client sent */
		ret = read(conn_fd, &buf, 1);
		if (ret == 1 && buf != SEND_BYTE) {
			fprintf(stderr, "bad byte: 0x%x\n", buf);
			close(conn_fd);
			goto err_thread;
		}

		close(conn_fd);
		accepted++;
	}

	pthread_join(thread, NULL);

	if (accepted < NR_RECONNECTS) {
		fprintf(stderr, "reconnect: accepted %d, expected %d\n",
			accepted, NR_RECONNECTS);
		goto err;
	}

	close(listen_fd);
	io_uring_queue_exit(&ring);
	return T_EXIT_PASS;

err_thread:
	pthread_join(thread, NULL);
err:
	close(listen_fd);
	io_uring_queue_exit(&ring);
	return T_EXIT_FAIL;
}

int main(int argc, char *argv[])
{
	int ret;

	if (argc > 1)
		return T_EXIT_SKIP;

	ret = test_accept_mshot_stress();
	if (ret == T_EXIT_SKIP) {
		printf("Multishot accept not supported, skipping\n");
		return T_EXIT_SKIP;
	}
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_accept_mshot_stress failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_accept_mshot_burst();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_accept_mshot_burst failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_accept_mshot_reconnect();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_accept_mshot_reconnect failed\n");
		return T_EXIT_FAIL;
	}

	return T_EXIT_PASS;
}

static int register_task_restrictions(struct io_uring_restriction *res,
				      unsigned int nr_res)
{
	struct {
		__u16 flags;
		__u16 nr_res;
		__u32 resv[3];
		struct io_uring_restriction restrictions[];
	} *arg;
	size_t sz;
	int ret;

	sz = sizeof(*arg) + nr_res * sizeof(struct io_uring_restriction);
	arg = calloc(1, sz);
	if (!arg)
		return -ENOMEM;

	arg->nr_res = nr_res;
	memcpy(arg->restrictions, res, nr_res * sizeof(*res));

	ret = __sys_io_uring_register(-1, IORING_REGISTER_RESTRICTIONS, arg, 1);
	free(arg);
	return ret;
}

static int test_task_restrict_sqe_op(void)
{
	struct io_uring_restriction res[1];
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	struct io_uring ring;
	int ret;

	/* Allow only NOP */
	res[0].opcode = IORING_RESTRICTION_SQE_OP;
	res[0].sqe_op = IORING_OP_NOP;

	/*
	 * Task restrictions need to be tested in a child process since
	 * once set they can't be removed for the current task.
	 */
	pid_t pid = fork();
	if (pid < 0) {
		perror("fork");
		return T_EXIT_FAIL;
	}

	if (pid == 0) {
		/* Child: set no_new_privs (required like seccomp) */
		prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0);

		/* Register task restriction, then create ring */
		ret = register_task_restrictions(res, 1);
		if (ret == -EINVAL) {
			/* Kernel doesn't support per-task restrictions */
			_exit(T_EXIT_SKIP);
		}
		if (ret) {
			fprintf(stderr, "register task restrictions: %d\n", ret);
			_exit(T_EXIT_FAIL);
		}

		/* Create a new ring - should inherit task restrictions */
		ret = io_uring_queue_init(8, &ring, 0);
		if (ret) {
			fprintf(stderr, "ring setup failed: %d\n", ret);
			_exit(T_EXIT_FAIL);
		}

		/* NOP should be allowed */
		sqe = io_uring_get_sqe(&ring);
		io_uring_prep_nop(sqe);
		sqe->user_data = 1;

		/* Read should be denied */
		sqe = io_uring_get_sqe(&ring);
		io_uring_prep_read(sqe, 0, NULL, 0, 0);
		sqe->user_data = 2;

		ret = io_uring_submit(&ring);
		if (ret != 2) {
			fprintf(stderr, "submit: %d\n", ret);
			_exit(T_EXIT_FAIL);
		}

		for (int i = 0; i < 2; i++) {
			ret = io_uring_wait_cqe(&ring, &cqe);
			if (ret) {
				fprintf(stderr, "wait: %d\n", ret);
				_exit(T_EXIT_FAIL);
			}

			switch (cqe->user_data) {
			case 1: /* nop - should succeed */
				if (cqe->res != 0) {
					fprintf(stderr, "nop res: %d\n", cqe->res);
					_exit(T_EXIT_FAIL);
				}
				break;
			case 2: /* read - should be denied */
				if (cqe->res != -EACCES) {
					fprintf(stderr, "read res: %d (expected -EACCES)\n",
						cqe->res);
					_exit(T_EXIT_FAIL);
				}
				break;
			}
			io_uring_cqe_seen(&ring, cqe);
		}

		io_uring_queue_exit(&ring);
		_exit(T_EXIT_PASS);
	}

	/* Parent: wait for child */
	int status;
	waitpid(pid, &status, 0);
	if (!WIFEXITED(status))
		return T_EXIT_FAIL;
	return WEXITSTATUS(status);
}

static int test_task_restrict_fork_inherit(void)
{
	struct io_uring_restriction res[2];
	int ret;

	/* Allow only NOP and WRITE */
	res[0].opcode = IORING_RESTRICTION_SQE_OP;
	res[0].sqe_op = IORING_OP_NOP;
	res[1].opcode = IORING_RESTRICTION_SQE_OP;
	res[1].sqe_op = IORING_OP_WRITE;

	pid_t pid = fork();
	if (pid < 0) {
		perror("fork");
		return T_EXIT_FAIL;
	}

	if (pid == 0) {
		/* Child: set no_new_privs (required like seccomp) */
		prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0);

		/* Register task restriction then fork again */
		ret = register_task_restrictions(res, 2);
		if (ret == -EINVAL) {
			_exit(T_EXIT_SKIP);
		}
		if (ret) {
			fprintf(stderr, "register task restrictions: %d\n", ret);
			_exit(T_EXIT_FAIL);
		}

		/* Fork a grandchild - restrictions should be inherited */
		pid_t gpid = fork();
		if (gpid < 0) {
			perror("fork");
			_exit(T_EXIT_FAIL);
		}

		if (gpid == 0) {
			/* Grandchild: create ring and verify restrictions */
			struct io_uring ring;
			struct io_uring_sqe *sqe;
			struct io_uring_cqe *cqe;

			ret = io_uring_queue_init(8, &ring, 0);
			if (ret) {
				fprintf(stderr, "grandchild ring setup: %d\n", ret);
				_exit(T_EXIT_FAIL);
			}

			/* NOP should be allowed */
			sqe = io_uring_get_sqe(&ring);
			io_uring_prep_nop(sqe);
			sqe->user_data = 1;

			/* Read should be denied */
			sqe = io_uring_get_sqe(&ring);
			io_uring_prep_read(sqe, 0, NULL, 0, 0);
			sqe->user_data = 2;

			ret = io_uring_submit(&ring);
			if (ret != 2) {
				fprintf(stderr, "grandchild submit: %d\n", ret);
				_exit(T_EXIT_FAIL);
			}

			for (int i = 0; i < 2; i++) {
				ret = io_uring_wait_cqe(&ring, &cqe);
				if (ret) {
					fprintf(stderr, "grandchild wait: %d\n", ret);
					_exit(T_EXIT_FAIL);
				}

				switch (cqe->user_data) {
				case 1:
					if (cqe->res != 0) {
						fprintf(stderr, "grandchild nop: %d\n",
							cqe->res);
						_exit(T_EXIT_FAIL);
					}
					break;
				case 2:
					if (cqe->res != -EACCES) {
						fprintf(stderr, "grandchild read: %d\n",
							cqe->res);
						_exit(T_EXIT_FAIL);
					}
					break;
				}
				io_uring_cqe_seen(&ring, cqe);
			}

			io_uring_queue_exit(&ring);
			_exit(T_EXIT_PASS);
		}

		int status;
		waitpid(gpid, &status, 0);
		if (!WIFEXITED(status))
			_exit(T_EXIT_FAIL);
		_exit(WEXITSTATUS(status));
	}

	int status;
	waitpid(pid, &status, 0);
	if (!WIFEXITED(status))
		return T_EXIT_FAIL;
	return WEXITSTATUS(status);
}

static int test_task_restrict_double_register(void)
{
	struct io_uring_restriction res[1];
	int ret;

	res[0].opcode = IORING_RESTRICTION_SQE_OP;
	res[0].sqe_op = IORING_OP_NOP;

	pid_t pid = fork();
	if (pid < 0) {
		perror("fork");
		return T_EXIT_FAIL;
	}

	if (pid == 0) {
		prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0);

		ret = register_task_restrictions(res, 1);
		if (ret == -EINVAL) {
			_exit(T_EXIT_SKIP);
		}
		if (ret) {
			fprintf(stderr, "first register: %d\n", ret);
			_exit(T_EXIT_FAIL);
		}

		/* Second registration should fail with -EPERM */
		ret = register_task_restrictions(res, 1);
		if (ret != -EPERM) {
			fprintf(stderr, "second register: %d (expected -EPERM)\n", ret);
			_exit(T_EXIT_FAIL);
		}

		_exit(T_EXIT_PASS);
	}

	int status;
	waitpid(pid, &status, 0);
	if (!WIFEXITED(status))
		return T_EXIT_FAIL;
	return WEXITSTATUS(status);
}

static int test_task_restrict_register_op(void)
{
	struct io_uring_restriction res[1];
	int ret;

	/* Allow only IORING_REGISTER_FILES */
	res[0].opcode = IORING_RESTRICTION_REGISTER_OP;
	res[0].register_op = IORING_REGISTER_FILES;

	pid_t pid = fork();
	if (pid < 0) {
		perror("fork");
		return T_EXIT_FAIL;
	}

	if (pid == 0) {
		prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0);

		ret = register_task_restrictions(res, 1);
		if (ret == -EINVAL) {
			_exit(T_EXIT_SKIP);
		}
		if (ret) {
			fprintf(stderr, "register task restrictions: %d\n", ret);
			_exit(T_EXIT_FAIL);
		}

		struct io_uring ring;
		int pipe1[2];

		if (pipe(pipe1) != 0) {
			perror("pipe");
			_exit(T_EXIT_FAIL);
		}

		ret = io_uring_queue_init(8, &ring, 0);
		if (ret) {
			fprintf(stderr, "ring setup: %d\n", ret);
			_exit(T_EXIT_FAIL);
		}

		/* Register files should be allowed */
		ret = io_uring_register_files(&ring, pipe1, 2);
		if (ret) {
			fprintf(stderr, "register files: %d\n", ret);
			_exit(T_EXIT_FAIL);
		}

		/* Register buffers should be denied */
		uint64_t ptr;
		struct iovec vec = { .iov_base = &ptr, .iov_len = sizeof(ptr) };
		ret = io_uring_register_buffers(&ring, &vec, 1);
		if (ret != -EACCES) {
			fprintf(stderr, "register buffers: %d (expected -EACCES)\n", ret);
			_exit(T_EXIT_FAIL);
		}

		io_uring_queue_exit(&ring);
		close(pipe1[0]);
		close(pipe1[1]);
		_exit(T_EXIT_PASS);
	}

	int status;
	waitpid(pid, &status, 0);
	if (!WIFEXITED(status))
		return T_EXIT_FAIL;
	return WEXITSTATUS(status);
}

int main(int argc, char *argv[])
{
	int ret;

	if (argc > 1)
		return T_EXIT_SKIP;

	ret = test_task_restrict_sqe_op();
	if (ret == T_EXIT_SKIP) {
		printf("Per-task restrictions not supported, skipping\n");
		return T_EXIT_SKIP;
	} else if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_task_restrict_sqe_op failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_task_restrict_fork_inherit();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_task_restrict_fork_inherit failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_task_restrict_double_register();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_task_restrict_double_register failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_task_restrict_register_op();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_task_restrict_register_op failed\n");
		return T_EXIT_FAIL;
	}

	return T_EXIT_PASS;
}

static void provide_buffers(struct io_uring_buf_ring *br, void *base,
			    int nr_bufs, int buf_size, int start_bid)
{
	int i;

	for (i = 0; i < nr_bufs; i++) {
		void *addr = base + i * buf_size;
		io_uring_buf_ring_add(br, addr, buf_size, start_bid + i,
				      io_uring_buf_ring_mask(nr_bufs), i);
	}
	io_uring_buf_ring_advance(br, nr_bufs);
}

static void *send_thread(void *arg)
{
	struct thread_data *td = arg;
	struct sockaddr_in saddr;
	char buf[SEND_SIZE];
	int fd, ret, i;

	memset(buf, 0xaa, sizeof(buf));

	fd = socket(AF_INET, SOCK_STREAM, 0);
	if (fd < 0) {
		perror("socket");
		return (void *)(intptr_t)1;
	}

	memset(&saddr, 0, sizeof(saddr));
	saddr.sin_family = AF_INET;
	saddr.sin_port = htons(td->port);
	inet_pton(AF_INET, "127.0.0.1", &saddr.sin_addr);

	pthread_barrier_wait(&td->connect_barrier);

	ret = connect(fd, (struct sockaddr *)&saddr, sizeof(saddr));
	if (ret < 0) {
		perror("connect");
		close(fd);
		return (void *)(intptr_t)1;
	}

	/* Send more data than we have buffers for */
	for (i = 0; i < NR_SENDS; i++) {
		/* Fill pattern: iteration number */
		memset(buf, i & 0xff, sizeof(buf));
		ret = send(fd, buf, sizeof(buf), 0);
		if (ret < 0) {
			if (errno == EPIPE)
				break;
			perror("send");
			close(fd);
			return (void *)(intptr_t)1;
		}
		/* Small delay to spread sends over time */
		if (i % 8 == 7)
			usleep(1000);
	}

	close(fd);
	return NULL;
}

int main(int argc, char *argv[])
{
	int ret;

	if (argc > 1)
		return T_EXIT_SKIP;

	ret = test_recv_drain_refill();
	if (ret == T_EXIT_SKIP) {
		printf("Buffer rings not supported, skipping\n");
		return T_EXIT_SKIP;
	}
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_recv_drain_refill failed\n");
		return T_EXIT_FAIL;
	}

	return T_EXIT_PASS;
}

static int test_nop_detect(struct io_uring *ring)
{
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	int ret;

	sqe = io_uring_get_sqe(ring);
	io_uring_prep_nop(sqe);
	sqe->nop_flags = IORING_NOP_INJECT_RESULT;
	sqe->len = 42;
	sqe->user_data = 1;

	ret = io_uring_submit(ring);
	if (ret != 1) {
		fprintf(stderr, "submit detect: %d\n", ret);
		return T_EXIT_FAIL;
	}

	ret = io_uring_wait_cqe(ring, &cqe);
	if (ret) {
		fprintf(stderr, "wait detect: %d\n", ret);
		return T_EXIT_FAIL;
	}

	if (cqe->res != 42) {
		/* Kernel doesn't support NOP flags */
		no_nop_flags = 1;
		io_uring_cqe_seen(ring, cqe);
		return T_EXIT_SKIP;
	}

	io_uring_cqe_seen(ring, cqe);
	return T_EXIT_PASS;
}

static int test_nop_file_bad_fd(struct io_uring *ring)
{
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	int ret;

	if (no_nop_flags)
		return T_EXIT_SKIP;

	sqe = io_uring_get_sqe(ring);
	io_uring_prep_nop(sqe);
	sqe->nop_flags = IORING_NOP_FILE;
	sqe->fd = 9999; /* invalid fd */
	sqe->user_data = 1;

	ret = io_uring_submit(ring);
	if (ret != 1) {
		fprintf(stderr, "submit: %d\n", ret);
		return T_EXIT_FAIL;
	}

	ret = io_uring_wait_cqe(ring, &cqe);
	if (ret) {
		fprintf(stderr, "wait: %d\n", ret);
		return T_EXIT_FAIL;
	}

	if (cqe->res == 0) {
		/* Kernel doesn't support IORING_NOP_FILE */
		no_nop_file = 1;
		io_uring_cqe_seen(ring, cqe);
		return T_EXIT_SKIP;
	}

	if (cqe->res != -EBADF) {
		fprintf(stderr, "nop bad fd res: %d (expected -EBADF)\n", cqe->res);
		io_uring_cqe_seen(ring, cqe);
		return T_EXIT_FAIL;
	}

	io_uring_cqe_seen(ring, cqe);
	return T_EXIT_PASS;
}

static int test_nop_file(struct io_uring *ring)
{
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	int ret, fd;

	if (no_nop_flags || no_nop_file)
		return T_EXIT_SKIP;

	fd = open("/dev/null", O_RDWR);
	if (fd < 0) {
		perror("open /dev/null");
		return T_EXIT_FAIL;
	}

	sqe = io_uring_get_sqe(ring);
	io_uring_prep_nop(sqe);
	sqe->nop_flags = IORING_NOP_FILE;
	sqe->fd = fd;
	sqe->user_data = 1;

	ret = io_uring_submit(ring);
	if (ret != 1) {
		fprintf(stderr, "submit: %d\n", ret);
		close(fd);
		return T_EXIT_FAIL;
	}

	ret = io_uring_wait_cqe(ring, &cqe);
	if (ret) {
		fprintf(stderr, "wait: %d\n", ret);
		close(fd);
		return T_EXIT_FAIL;
	}

	if (cqe->res != 0) {
		fprintf(stderr, "nop file res: %d\n", cqe->res);
		io_uring_cqe_seen(ring, cqe);
		close(fd);
		return T_EXIT_FAIL;
	}

	io_uring_cqe_seen(ring, cqe);
	close(fd);
	return T_EXIT_PASS;
}

static int test_nop_fixed_file(struct io_uring *ring)
{
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	int ret, fd;

	if (no_nop_flags || no_nop_file)
		return T_EXIT_SKIP;

	fd = open("/dev/null", O_RDWR);
	if (fd < 0) {
		perror("open /dev/null");
		return T_EXIT_FAIL;
	}

	ret = io_uring_register_files(ring, &fd, 1);
	if (ret) {
		fprintf(stderr, "register files: %d\n", ret);
		close(fd);
		return T_EXIT_FAIL;
	}

	sqe = io_uring_get_sqe(ring);
	io_uring_prep_nop(sqe);
	sqe->nop_flags = IORING_NOP_FILE | IORING_NOP_FIXED_FILE;
	sqe->fd = 0; /* fixed file index */
	sqe->user_data = 1;

	ret = io_uring_submit(ring);
	if (ret != 1) {
		fprintf(stderr, "submit: %d\n", ret);
		goto err;
	}

	ret = io_uring_wait_cqe(ring, &cqe);
	if (ret) {
		fprintf(stderr, "wait: %d\n", ret);
		goto err;
	}

	if (cqe->res != 0) {
		fprintf(stderr, "nop fixed file res: %d\n", cqe->res);
		io_uring_cqe_seen(ring, cqe);
		goto err;
	}

	io_uring_cqe_seen(ring, cqe);

	/* Test with invalid fixed file index */
	sqe = io_uring_get_sqe(ring);
	io_uring_prep_nop(sqe);
	sqe->nop_flags = IORING_NOP_FILE | IORING_NOP_FIXED_FILE;
	sqe->fd = 999; /* invalid index */
	sqe->user_data = 2;

	ret = io_uring_submit(ring);
	if (ret != 1) {
		fprintf(stderr, "submit bad index: %d\n", ret);
		goto err;
	}

	ret = io_uring_wait_cqe(ring, &cqe);
	if (ret) {
		fprintf(stderr, "wait bad index: %d\n", ret);
		goto err;
	}

	if (cqe->res != -EBADF) {
		fprintf(stderr, "nop bad fixed file res: %d (expected -EBADF)\n",
			cqe->res);
		io_uring_cqe_seen(ring, cqe);
		goto err;
	}

	io_uring_cqe_seen(ring, cqe);
	io_uring_unregister_files(ring);
	close(fd);
	return T_EXIT_PASS;
err:
	io_uring_unregister_files(ring);
	close(fd);
	return T_EXIT_FAIL;
}

static int test_nop_fixed_buffer(struct io_uring *ring)
{
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	char buf[4096];
	struct iovec iov = { .iov_base = buf, .iov_len = sizeof(buf) };
	int ret;

	if (no_nop_flags)
		return T_EXIT_SKIP;

	ret = io_uring_register_buffers(ring, &iov, 1);
	if (ret) {
		fprintf(stderr, "register buffers: %d\n", ret);
		return T_EXIT_FAIL;
	}

	/* Valid buffer index */
	sqe = io_uring_get_sqe(ring);
	io_uring_prep_nop(sqe);
	sqe->nop_flags = IORING_NOP_FIXED_BUFFER;
	sqe->buf_index = 0;
	sqe->user_data = 1;

	ret = io_uring_submit(ring);
	if (ret != 1) {
		fprintf(stderr, "submit: %d\n", ret);
		goto err;
	}

	ret = io_uring_wait_cqe(ring, &cqe);
	if (ret) {
		fprintf(stderr, "wait: %d\n", ret);
		goto err;
	}

	if (cqe->res != 0) {
		fprintf(stderr, "nop fixed buffer res: %d\n", cqe->res);
		io_uring_cqe_seen(ring, cqe);
		goto err;
	}
	io_uring_cqe_seen(ring, cqe);

	/* Invalid buffer index */
	sqe = io_uring_get_sqe(ring);
	io_uring_prep_nop(sqe);
	sqe->nop_flags = IORING_NOP_FIXED_BUFFER;
	sqe->buf_index = 999;
	sqe->user_data = 2;

	ret = io_uring_submit(ring);
	if (ret != 1) {
		fprintf(stderr, "submit bad buf: %d\n", ret);
		goto err;
	}

	ret = io_uring_wait_cqe(ring, &cqe);
	if (ret) {
		fprintf(stderr, "wait bad buf: %d\n", ret);
		goto err;
	}

	if (cqe->res == 0) {
		/* Kernel doesn't support IORING_NOP_FIXED_BUFFER */
		io_uring_cqe_seen(ring, cqe);
		io_uring_unregister_buffers(ring);
		return T_EXIT_SKIP;
	}
	if (cqe->res != -EFAULT) {
		fprintf(stderr, "nop bad buffer res: %d (expected -EFAULT)\n",
			cqe->res);
		io_uring_cqe_seen(ring, cqe);
		goto err;
	}

	io_uring_cqe_seen(ring, cqe);
	io_uring_unregister_buffers(ring);
	return T_EXIT_PASS;
err:
	io_uring_unregister_buffers(ring);
	return T_EXIT_FAIL;
}

static int test_nop_tw(struct io_uring *ring)
{
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	int ret, i;

	if (no_nop_flags)
		return T_EXIT_SKIP;

	/* Submit several NOPs via task_work path */
	for (i = 0; i < 8; i++) {
		sqe = io_uring_get_sqe(ring);
		io_uring_prep_nop(sqe);
		sqe->nop_flags = IORING_NOP_TW;
		sqe->user_data = i + 1;
	}

	ret = io_uring_submit(ring);
	if (ret != 8) {
		fprintf(stderr, "submit tw: %d\n", ret);
		return T_EXIT_FAIL;
	}

	for (i = 0; i < 8; i++) {
		ret = io_uring_wait_cqe(ring, &cqe);
		if (ret) {
			fprintf(stderr, "wait tw: %d\n", ret);
			return T_EXIT_FAIL;
		}
		if (cqe->res != 0) {
			fprintf(stderr, "nop tw res: %d\n", cqe->res);
			io_uring_cqe_seen(ring, cqe);
			return T_EXIT_FAIL;
		}
		io_uring_cqe_seen(ring, cqe);
	}

	return T_EXIT_PASS;
}

static int test_nop_tw_inject(struct io_uring *ring)
{
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	int ret;

	if (no_nop_flags)
		return T_EXIT_SKIP;

	sqe = io_uring_get_sqe(ring);
	io_uring_prep_nop(sqe);
	sqe->nop_flags = IORING_NOP_TW | IORING_NOP_INJECT_RESULT;
	sqe->len = 42;
	sqe->user_data = 1;

	ret = io_uring_submit(ring);
	if (ret != 1) {
		fprintf(stderr, "submit: %d\n", ret);
		return T_EXIT_FAIL;
	}

	ret = io_uring_wait_cqe(ring, &cqe);
	if (ret) {
		fprintf(stderr, "wait: %d\n", ret);
		return T_EXIT_FAIL;
	}

	if (cqe->res != 42) {
		fprintf(stderr, "nop tw inject res: %d (expected 42)\n", cqe->res);
		io_uring_cqe_seen(ring, cqe);
		return T_EXIT_FAIL;
	}

	io_uring_cqe_seen(ring, cqe);
	return T_EXIT_PASS;
}

static int test_nop_cqe32(void)
{
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	struct io_uring ring;
	int ret;

	if (no_nop_flags)
		return T_EXIT_SKIP;

	ret = io_uring_queue_init(8, &ring, IORING_SETUP_CQE32);
	if (ret) {
		if (ret == -EINVAL)
			return T_EXIT_SKIP;
		fprintf(stderr, "ring setup cqe32: %d\n", ret);
		return T_EXIT_FAIL;
	}

	sqe = io_uring_get_sqe(&ring);
	io_uring_prep_nop(sqe);
	sqe->nop_flags = IORING_NOP_CQE32;
	sqe->off = 0xdeadbeef12345678ULL; /* extra1 */
	sqe->addr = 0xabcdef0011223344ULL; /* extra2 */
	sqe->user_data = 1;

	ret = io_uring_submit(&ring);
	if (ret != 1) {
		fprintf(stderr, "submit cqe32: %d\n", ret);
		goto err;
	}

	ret = io_uring_wait_cqe(&ring, &cqe);
	if (ret) {
		fprintf(stderr, "wait cqe32: %d\n", ret);
		goto err;
	}

	if (cqe->res != 0) {
		fprintf(stderr, "nop cqe32 res: %d\n", cqe->res);
		io_uring_cqe_seen(&ring, cqe);
		goto err;
	}

	if (cqe->big_cqe[0] != 0xdeadbeef12345678ULL) {
		fprintf(stderr, "cqe32 extra1: 0x%llx (expected 0xdeadbeef12345678)\n",
			(unsigned long long) cqe->big_cqe[0]);
		io_uring_cqe_seen(&ring, cqe);
		goto err;
	}

	if (cqe->big_cqe[1] != 0xabcdef0011223344ULL) {
		fprintf(stderr, "cqe32 extra2: 0x%llx (expected 0xabcdef0011223344)\n",
			(unsigned long long) cqe->big_cqe[1]);
		io_uring_cqe_seen(&ring, cqe);
		goto err;
	}

	io_uring_cqe_seen(&ring, cqe);
	io_uring_queue_exit(&ring);
	return T_EXIT_PASS;
err:
	io_uring_queue_exit(&ring);
	return T_EXIT_FAIL;
}

static int test_nop_cqe32_no_ring_support(void)
{
	struct io_uring_sqe *sqe;
