			cqe->res);
		io_uring_cqe_seen(&ring, cqe);
		io_uring_queue_exit(&ring);
		return T_EXIT_FAIL;
	}

	io_uring_cqe_seen(&ring, cqe);
	io_uring_queue_exit(&ring);
	return T_EXIT_PASS;
}

static int test_nop_combined(struct io_uring *ring)
{
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	char buf[4096];
	struct iovec iov = { .iov_base = buf, .iov_len = sizeof(buf) };
	int ret, fd;

	if (no_nop_flags || no_nop_file)
		return T_EXIT_SKIP;

	fd = open("/dev/null", O_RDWR);
	if (fd < 0) {
		perror("open /dev/null");
		return T_EXIT_FAIL;
	}

	ret = io_uring_register_files(ring, &fd, 1);
	if (ret) {
		fprintf(stderr, "register files: %d\n", ret);
		close(fd);
		return T_EXIT_FAIL;
	}

	ret = io_uring_register_buffers(ring, &iov, 1);
	if (ret) {
		fprintf(stderr, "register buffers: %d\n", ret);
		io_uring_unregister_files(ring);
		close(fd);
		return T_EXIT_FAIL;
	}

	/* All flags combined */
	sqe = io_uring_get_sqe(ring);
	io_uring_prep_nop(sqe);
	sqe->nop_flags = IORING_NOP_FILE | IORING_NOP_FIXED_FILE |
			 IORING_NOP_FIXED_BUFFER | IORING_NOP_TW;
	sqe->fd = 0;
	sqe->buf_index = 0;
	sqe->user_data = 1;

	ret = io_uring_submit(ring);
	if (ret != 1) {
		fprintf(stderr, "submit combined: %d\n", ret);
		goto err;
	}

	ret = io_uring_wait_cqe(ring, &cqe);
	if (ret) {
		fprintf(stderr, "wait combined: %d\n", ret);
		goto err;
	}

	if (cqe->res != 0) {
		fprintf(stderr, "nop combined res: %d\n", cqe->res);
		io_uring_cqe_seen(ring, cqe);
		goto err;
	}

	io_uring_cqe_seen(ring, cqe);
	io_uring_unregister_buffers(ring);
	io_uring_unregister_files(ring);
	close(fd);
	return T_EXIT_PASS;
err:
	io_uring_unregister_buffers(ring);
	io_uring_unregister_files(ring);
	close(fd);
	return T_EXIT_FAIL;
}

int main(int argc, char *argv[])
{
	struct io_uring ring;
	int ret;

	if (argc > 1)
		return T_EXIT_SKIP;

	ret = io_uring_queue_init(8, &ring, 0);
	if (ret) {
		fprintf(stderr, "ring setup failed: %d\n", ret);
		return T_EXIT_FAIL;
	}

	ret = test_nop_detect(&ring);
	if (ret == T_EXIT_SKIP) {
		printf("NOP flags not supported, skipping\n");
		io_uring_queue_exit(&ring);
		return T_EXIT_SKIP;
	} else if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_nop_detect failed\n");
		return T_EXIT_FAIL;
	}

	/* Use bad fd test to detect NOP_FILE support */
	ret = test_nop_file_bad_fd(&ring);
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_nop_file_bad_fd failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_nop_file(&ring);
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_nop_file failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_nop_fixed_file(&ring);
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_nop_fixed_file failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_nop_fixed_buffer(&ring);
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_nop_fixed_buffer failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_nop_tw(&ring);
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_nop_tw failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_nop_tw_inject(&ring);
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_nop_tw_inject failed\n");
		return T_EXIT_FAIL;
	}

	io_uring_queue_exit(&ring);

	ret = test_nop_cqe32();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_nop_cqe32 failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_nop_cqe32_no_ring_support();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_nop_cqe32_no_ring_support failed\n");
		return T_EXIT_FAIL;
	}

	/* New ring for combined test since we need fresh file/buffer tables */
	ret = io_uring_queue_init(8, &ring, 0);
	if (ret) {
		fprintf(stderr, "ring setup failed: %d\n", ret);
		return T_EXIT_FAIL;
	}

	ret = test_nop_combined(&ring);
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_nop_combined failed\n");
		return T_EXIT_FAIL;
	}

	io_uring_queue_exit(&ring);
	return T_EXIT_PASS;
}

static int test_poll_cancel_race(void)
{
	struct io_uring ring;
	int ret, i;
	int pipe_fds[2];
	int op_completions = 0;
	int cancel_completions = 0;

	if (pipe(pipe_fds) < 0) {
		perror("pipe");
		return T_EXIT_FAIL;
	}

	ret = io_uring_queue_init(RING_SIZE, &ring, 0);
	if (ret) {
		fprintf(stderr, "ring setup: %d\n", ret);
		close(pipe_fds[0]);
		close(pipe_fds[1]);
		return T_EXIT_FAIL;
	}

	for (i = 0; i < NR_ITERS; i++) {
		struct io_uring_sqe *sqe;
		struct io_uring_cqe *cqe;
		__u64 poll_ud = UD_OP_POLL | ((__u64)i << UD_SEQ_SHIFT);
		__u64 cancel_ud = UD_OP_CANCEL | ((__u64)i << UD_SEQ_SHIFT);
		bool got_poll = false, got_cancel = false;

		/* Submit poll */
		sqe = io_uring_get_sqe(&ring);
		io_uring_prep_poll_add(sqe, pipe_fds[0], POLLIN);
		sqe->user_data = poll_ud;

		/* Submit cancel immediately after */
		sqe = io_uring_get_sqe(&ring);
		io_uring_prep_cancel64(sqe, poll_ud, 0);
		sqe->user_data = cancel_ud;

		ret = io_uring_submit(&ring);
		if (ret != 2) {
			fprintf(stderr, "submit iter %d: %d\n", i, ret);
			goto err;
		}

		/* Must get exactly 2 CQEs */
		for (int j = 0; j < 2; j++) {
			ret = io_uring_wait_cqe(&ring, &cqe);
			if (ret) {
				fprintf(stderr, "wait iter %d/%d: %d\n", i, j, ret);
				goto err;
			}

			if ((cqe->user_data & 0xff) == UD_OP_POLL) {
				got_poll = true;
				/*
				 * Poll result: either -ECANCELED (cancel won)
				 * or 0/POLLIN (poll completed first, shouldn't
				 * happen here since nothing writes to pipe)
				 */
				if (cqe->res != -ECANCELED && cqe->res != 0) {
					fprintf(stderr, "poll res: %d\n", cqe->res);
					io_uring_cqe_seen(&ring, cqe);
					goto err;
				}
				op_completions++;
			} else if ((cqe->user_data & 0xff) == UD_OP_CANCEL) {
				got_cancel = true;
				/*
				 * Cancel result: 0 (cancelled successfully) or
				 * -ENOENT (poll already completed) or
				 * -EALREADY (in progress)
				 */
				if (cqe->res != 0 && cqe->res != -ENOENT &&
				    cqe->res != -EALREADY) {
					if (cqe->res == -EINVAL) {
						no_cancel = 1;
						io_uring_cqe_seen(&ring, cqe);
						goto out;
					}
					fprintf(stderr, "cancel res: %d\n", cqe->res);
					io_uring_cqe_seen(&ring, cqe);
					goto err;
				}
				cancel_completions++;
			}
			io_uring_cqe_seen(&ring, cqe);
		}

		if (!got_poll || !got_cancel) {
			fprintf(stderr, "missing CQE iter %d: poll=%d cancel=%d\n",
				i, got_poll, got_cancel);
			goto err;
		}
	}

out:
	close(pipe_fds[0]);
	close(pipe_fds[1]);
	io_uring_queue_exit(&ring);

	if (no_cancel)
		return T_EXIT_SKIP;

	return T_EXIT_PASS;

err:
	close(pipe_fds[0]);
	close(pipe_fds[1]);
	io_uring_queue_exit(&ring);
	return T_EXIT_FAIL;
}

static int test_read_cancel_race(void)
{
	struct io_uring ring;
	char buf[32];
	int ret, i;
	int pipe_fds[2];

	if (no_cancel)
		return T_EXIT_SKIP;

	if (pipe(pipe_fds) < 0) {
		perror("pipe");
		return T_EXIT_FAIL;
	}

	/* Make read end non-blocking so prep works, but reads will still
	 * go async since there's no data
	 */
	t_set_nonblock(pipe_fds[0]);

	ret = io_uring_queue_init(RING_SIZE, &ring, 0);
	if (ret) {
		fprintf(stderr, "ring setup: %d\n", ret);
		close(pipe_fds[0]);
		close(pipe_fds[1]);
		return T_EXIT_FAIL;
	}

	for (i = 0; i < NR_ITERS; i++) {
		struct io_uring_sqe *sqe;
		struct io_uring_cqe *cqe;
		__u64 read_ud = UD_OP_READ | ((__u64)i << UD_SEQ_SHIFT);
		__u64 cancel_ud = UD_OP_CANCEL | ((__u64)i << UD_SEQ_SHIFT);
		bool got_read = false, got_cancel = false;
		int nr_cqes;

		/* Submit read that will block (no data in pipe) */
		sqe = io_uring_get_sqe(&ring);
		io_uring_prep_read(sqe, pipe_fds[0], buf, sizeof(buf), 0);
		sqe->user_data = read_ud;

		/* Submit cancel */
		sqe = io_uring_get_sqe(&ring);
		io_uring_prep_cancel64(sqe, read_ud, 0);
		sqe->user_data = cancel_ud;

		ret = io_uring_submit(&ring);
		if (ret != 2) {
			fprintf(stderr, "submit iter %d: %d\n", i, ret);
			goto err;
		}

		/*
		 * We should get 2 CQEs, but the read may complete
		 * with -EAGAIN immediately (non-blocking pipe with no data),
		 * in which case cancel gets -ENOENT.
		 */
		nr_cqes = 0;
		while (nr_cqes < 2) {
			ret = io_uring_wait_cqe(&ring, &cqe);
			if (ret) {
				fprintf(stderr, "wait iter %d/%d: %d\n",
					i, nr_cqes, ret);
				goto err;
			}

			if ((cqe->user_data & 0xff) == UD_OP_READ) {
				got_read = true;
				/* -ECANCELED, -EAGAIN, or short read all OK */
				if (cqe->res != -ECANCELED &&
				    cqe->res != -EAGAIN &&
				    cqe->res < 0 && cqe->res != -EINTR) {
					fprintf(stderr, "read res iter %d: %d\n",
						i, cqe->res);
					io_uring_cqe_seen(&ring, cqe);
					goto err;
				}
			} else if ((cqe->user_data & 0xff) == UD_OP_CANCEL) {
				got_cancel = true;
				if (cqe->res != 0 && cqe->res != -ENOENT &&
				    cqe->res != -EALREADY) {
					fprintf(stderr, "cancel res iter %d: %d\n",
						i, cqe->res);
					io_uring_cqe_seen(&ring, cqe);
					goto err;
				}
			}
			io_uring_cqe_seen(&ring, cqe);
			nr_cqes++;
		}

		if (!got_read || !got_cancel) {
			fprintf(stderr, "missing CQE iter %d\n", i);
			goto err;
		}
	}

	close(pipe_fds[0]);
	close(pipe_fds[1]);
	io_uring_queue_exit(&ring);
	return T_EXIT_PASS;

err:
	close(pipe_fds[0]);
	close(pipe_fds[1]);
	io_uring_queue_exit(&ring);
	return T_EXIT_FAIL;
}

static void *cancel_thread_fn(void *arg)
{
	struct cancel_thread_data *ctd = arg;
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	int ret;

	while (!ctd->stop) {
		sqe = io_uring_get_sqe(ctd->ring);
		if (!sqe) {
			io_uring_submit(ctd->ring);
			continue;
		}
		io_uring_prep_cancel64(sqe, 0, IORING_ASYNC_CANCEL_ANY);
		sqe->user_data = 0xdead;

		ret = io_uring_submit(ctd->ring);
		if (ret < 0)
			continue;

		ret = io_uring_wait_cqe(ctd->ring, &cqe);
		if (ret)
			continue;

		if (cqe->res == 0)
			ctd->cancel_count++;
		io_uring_cqe_seen(ctd->ring, cqe);
	}

	return NULL;
}

static int test_concurrent_cancel(void)
{
	struct io_uring submit_ring, cancel_ring;
	struct cancel_thread_data ctd;
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	pthread_t thread;
	int ret, i;
	int pipe_fds[2];
	int submitted = 0, completed = 0;

	if (no_cancel)
		return T_EXIT_SKIP;

	if (pipe(pipe_fds) < 0) {
		perror("pipe");
		return T_EXIT_FAIL;
	}

	ret = io_uring_queue_init(RING_SIZE, &submit_ring, 0);
	if (ret) {
		fprintf(stderr, "submit ring setup: %d\n", ret);
		close(pipe_fds[0]);
		close(pipe_fds[1]);
		return T_EXIT_FAIL;
	}

	ret = io_uring_queue_init(RING_SIZE, &cancel_ring, 0);
	if (ret) {
		fprintf(stderr, "cancel ring setup: %d\n", ret);
		io_uring_queue_exit(&submit_ring);
		close(pipe_fds[0]);
		close(pipe_fds[1]);
		return T_EXIT_FAIL;
	}

	ctd.ring = &cancel_ring;
	ctd.cancel_count = 0;
	ctd.stop = 0;
	pthread_create(&thread, NULL, cancel_thread_fn, &ctd);

	/* Submit polls and let the other thread race cancels */
	for (i = 0; i < NR_ITERS; i++) {
		sqe = io_uring_get_sqe(&submit_ring);
		if (!sqe) {
			/* Flush and drain */
			io_uring_submit(&submit_ring);
			while (io_uring_peek_cqe(&submit_ring, &cqe) == 0) {
				completed++;
				io_uring_cqe_seen(&submit_ring, cqe);
			}
			sqe = io_uring_get_sqe(&submit_ring);
			if (!sqe)
				continue;
		}
		io_uring_prep_poll_add(sqe, pipe_fds[0], POLLIN);
		sqe->user_data = i + 1;
		submitted++;

		if (i % 16 == 15) {
			io_uring_submit(&submit_ring);
			/* Drain any completions */
			while (io_uring_peek_cqe(&submit_ring, &cqe) == 0) {
				completed++;
				io_uring_cqe_seen(&submit_ring, cqe);
			}
		}
	}

	io_uring_submit(&submit_ring);
	ctd.stop = 1;
	pthread_join(thread, NULL);

	/* Drain remaining CQEs from submit ring */
	while (completed < submitted) {
		/* Cancel anything remaining */
		sqe = io_uring_get_sqe(&submit_ring);
		if (sqe) {
			io_uring_prep_cancel64(sqe, 0, IORING_ASYNC_CANCEL_ANY);
			sqe->user_data = 0xbeef;
			io_uring_submit(&submit_ring);
		}

		ret = io_uring_peek_cqe(&submit_ring, &cqe);
		if (ret == -EAGAIN) {
			struct __kernel_timespec ts = { .tv_sec = 1 };
			ret = io_uring_wait_cqe_timeout(&submit_ring, &cqe, &ts);
			if (ret == -ETIME)
				break;
			if (ret)
				break;
		}
		if (cqe->user_data != 0xbeef)
			completed++;
		io_uring_cqe_seen(&submit_ring, cqe);
	}

	close(pipe_fds[0]);
	close(pipe_fds[1]);
	io_uring_queue_exit(&cancel_ring);
	io_uring_queue_exit(&submit_ring);
	return T_EXIT_PASS;
}

int main(int argc, char *argv[])
{
	int ret;

	if (argc > 1)
		return T_EXIT_SKIP;

	ret = test_poll_cancel_race();
	if (ret == T_EXIT_SKIP) {
		printf("cancel not supported, skipping\n");
		return T_EXIT_SKIP;
	}
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_poll_cancel_race failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_read_cancel_race();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_read_cancel_race failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_concurrent_cancel();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_concurrent_cancel failed\n");
		return T_EXIT_FAIL;
	}

	return T_EXIT_PASS;
}

static void provide_buffers(struct io_uring_buf_ring *br, void *base,
			    int nr_bufs, int buf_size)
{
	int i;

	for (i = 0; i < nr_bufs; i++) {
		void *addr = base + i * buf_size;
		io_uring_buf_ring_add(br, addr, buf_size, i,
				      io_uring_buf_ring_mask(nr_bufs), i);
	}
	io_uring_buf_ring_advance(br, nr_bufs);
}

static int test_read_overflow_refill(void)
{
	struct io_uring ring;
	struct io_uring_buf_ring *br;
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	void *buf_base;
	const char *fname = ".buf-ring-overflow-tmp";
	int fd, ret;
	int nr_success = 0, nr_enobufs = 0;

	ret = io_uring_queue_init(32, &ring, 0);
	if (ret) {
		fprintf(stderr, "ring setup: %d\n", ret);
		return T_EXIT_FAIL;
	}

	br = io_uring_setup_buf_ring(&ring, NR_BUFS, BGID, 0, &ret);
	if (!br) {
		if (ret == -EINVAL || ret == -ENOENT) {
			io_uring_queue_exit(&ring);
			return T_EXIT_SKIP;
		}
		fprintf(stderr, "buf ring setup: %d\n", ret);
		io_uring_queue_exit(&ring);
		return T_EXIT_FAIL;
	}

	buf_base = malloc(NR_BUFS * BUF_SIZE);
	if (!buf_base)
		goto err;

	/* Create test file */
	t_create_file(fname, NR_BUFS * BUF_SIZE * 4);
	fd = open(fname, O_RDONLY);
	if (fd < 0) {
		perror("open");
		goto err;
	}

	/* Provide only NR_BUFS buffers */
	provide_buffers(br, buf_base, NR_BUFS, BUF_SIZE);

	/* Submit more reads than we have buffers */
	for (int i = 0; i < NR_BUFS * 2; i++) {
		sqe = io_uring_get_sqe(&ring);
		io_uring_prep_read(sqe, fd, NULL, BUF_SIZE, i * BUF_SIZE);
		sqe->flags |= IOSQE_BUFFER_SELECT;
		sqe->buf_group = BGID;
		sqe->user_data = i;
	}

	ret = io_uring_submit(&ring);
	if (ret != NR_BUFS * 2) {
		fprintf(stderr, "submit: %d\n", ret);
		goto err_file;
	}

	/* Collect all completions */
	for (int i = 0; i < NR_BUFS * 2; i++) {
		ret = io_uring_wait_cqe(&ring, &cqe);
		if (ret) {
			fprintf(stderr, "wait: %d\n", ret);
			goto err_file;
		}

		if (cqe->res == -ENOBUFS) {
			nr_enobufs++;
		} else if (cqe->res > 0) {
			nr_success++;
		} else {
			fprintf(stderr, "unexpected res %d for ud %llu\n",
				cqe->res, (unsigned long long)cqe->user_data);
			io_uring_cqe_seen(&ring, cqe);
			goto err_file;
		}
		io_uring_cqe_seen(&ring, cqe);
	}

	/* We should have gotten exactly NR_BUFS successes */
	if (nr_success != NR_BUFS) {
		fprintf(stderr, "expected %d success, got %d\n", NR_BUFS, nr_success);
		goto err_file;
	}

	if (nr_enobufs != NR_BUFS) {
		fprintf(stderr, "expected %d ENOBUFS, got %d\n", NR_BUFS, nr_enobufs);
		goto err_file;
	}

	/* Now refill and do another round - should work fine */
	provide_buffers(br, buf_base, NR_BUFS, BUF_SIZE);

	nr_success = 0;
	for (int i = 0; i < NR_BUFS; i++) {
		sqe = io_uring_get_sqe(&ring);
		io_uring_prep_read(sqe, fd, NULL, BUF_SIZE, i * BUF_SIZE);
		sqe->flags |= IOSQE_BUFFER_SELECT;
		sqe->buf_group = BGID;
		sqe->user_data = 100 + i;
	}

	ret = io_uring_submit(&ring);
	if (ret != NR_BUFS) {
		fprintf(stderr, "refill submit: %d\n", ret);
		goto err_file;
	}

	for (int i = 0; i < NR_BUFS; i++) {
		ret = io_uring_wait_cqe(&ring, &cqe);
		if (ret) {
			fprintf(stderr, "refill wait: %d\n", ret);
			goto err_file;
		}

		if (cqe->res <= 0) {
			fprintf(stderr, "refill read res: %d\n", cqe->res);
			io_uring_cqe_seen(&ring, cqe);
			goto err_file;
		}
		nr_success++;
		io_uring_cqe_seen(&ring, cqe);
	}

	if (nr_success != NR_BUFS) {
		fprintf(stderr, "refill success: %d\n", nr_success);
		goto err_file;
	}

	close(fd);
	unlink(fname);
	free(buf_base);
	io_uring_free_buf_ring(&ring, br, NR_BUFS, BGID);
	io_uring_queue_exit(&ring);
	return T_EXIT_PASS;

err_file:
	close(fd);
	unlink(fname);
err:
	free(buf_base);
	io_uring_queue_exit(&ring);
	return T_EXIT_FAIL;
}

static int test_rapid_drain_refill(void)
{
	struct io_uring ring;
	struct io_uring_buf_ring *br;
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	void *buf_base;
	const char *fname = ".buf-ring-rapid-tmp";
	int fd, ret;
	int total_success = 0;

	ret = io_uring_queue_init(64, &ring, 0);
	if (ret) {
		fprintf(stderr, "ring setup: %d\n", ret);
		return T_EXIT_FAIL;
	}

	br = io_uring_setup_buf_ring(&ring, NR_BUFS, BGID, 0, &ret);
	if (!br) {
		if (ret == -EINVAL || ret == -ENOENT) {
			io_uring_queue_exit(&ring);
			return T_EXIT_SKIP;
		}
		fprintf(stderr, "buf ring setup: %d\n", ret);
		io_uring_queue_exit(&ring);
		return T_EXIT_FAIL;
	}

	buf_base = malloc(NR_BUFS * BUF_SIZE);
	if (!buf_base)
		goto err;

	t_create_file(fname, FILE_SIZE);
	fd = open(fname, O_RDONLY);
	if (fd < 0) {
		perror("open");
		goto err;
	}

	/*
	 * Do many rapid cycles: provide 1 buffer, submit 1 read,
	 * reap, repeat. This tests the fast path of single-buffer
	 * provide/consume cycles.
	 */
	for (int i = 0; i < NR_ROUNDS * NR_BUFS; i++) {
		/* Provide exactly 1 buffer */
		void *addr = buf_base + (i % NR_BUFS) * BUF_SIZE;
		io_uring_buf_ring_add(br, addr, BUF_SIZE, i % NR_BUFS,
				      io_uring_buf_ring_mask(NR_BUFS), 0);
		io_uring_buf_ring_advance(br, 1);

		sqe = io_uring_get_sqe(&ring);
		io_uring_prep_read(sqe, fd, NULL, BUF_SIZE,
				   (i * BUF_SIZE) % FILE_SIZE);
		sqe->flags |= IOSQE_BUFFER_SELECT;
		sqe->buf_group = BGID;
		sqe->user_data = i;

		ret = io_uring_submit(&ring);
		if (ret != 1) {
			fprintf(stderr, "rapid submit %d: %d\n", i, ret);
			goto err_file;
		}

		ret = io_uring_wait_cqe(&ring, &cqe);
		if (ret) {
			fprintf(stderr, "rapid wait %d: %d\n", i, ret);
			goto err_file;
		}

		if (cqe->res <= 0) {
			fprintf(stderr, "rapid read %d res: %d\n", i, cqe->res);
			io_uring_cqe_seen(&ring, cqe);
			goto err_file;
		}

		if (!(cqe->flags & IORING_CQE_F_BUFFER)) {
			fprintf(stderr, "rapid read %d: no buffer flag\n", i);
			io_uring_cqe_seen(&ring, cqe);
			goto err_file;
		}

		total_success++;
		io_uring_cqe_seen(&ring, cqe);
	}

	if (total_success != NR_ROUNDS * NR_BUFS) {
		fprintf(stderr, "rapid: %d success, expected %d\n",
			total_success, NR_ROUNDS * NR_BUFS);
		goto err_file;
	}

	close(fd);
	unlink(fname);
	free(buf_base);
	io_uring_free_buf_ring(&ring, br, NR_BUFS, BGID);
	io_uring_queue_exit(&ring);
	return T_EXIT_PASS;

err_file:
	close(fd);
	unlink(fname);
err:
	free(buf_base);
	io_uring_queue_exit(&ring);
	return T_EXIT_FAIL;
}

int main(int argc, char *argv[])
{
	int ret;

	if (argc > 1)
		return T_EXIT_SKIP;

	ret = test_read_drain_refill();
	if (ret == T_EXIT_SKIP) {
		printf("Buffer rings not supported, skipping\n");
		return T_EXIT_SKIP;
	}
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_read_drain_refill failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_read_overflow_refill();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_read_overflow_refill failed\n");
		return T_EXIT_FAIL;
	}

	ret = test_rapid_drain_refill();
	if (ret == T_EXIT_FAIL) {
		fprintf(stderr, "test_rapid_drain_refill failed\n");
		return T_EXIT_FAIL;
	}

	return T_EXIT_PASS;
}

static int test_openat(struct io_uring *ring, const char *path, int flags,
		       mode_t mode, const char *desc, int should_succeed)
{
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	int ret;

	sqe = io_uring_get_sqe(ring);
	io_uring_prep_openat(sqe, AT_FDCWD, path, flags, mode);
	sqe->user_data = 0xabcd;

	ret = io_uring_submit(ring);
	if (ret < 0) {
		printf("FAIL (submit: %s)\n", strerror(-ret));
		return ret;
	}

	ret = io_uring_wait_cqe(ring, &cqe);
	if (ret < 0) {
		printf("FAIL (wait: %s)\n", strerror(-ret));
		return ret;
	}

	if (should_succeed) {
		if (cqe->res >= 0) {
			close(cqe->res);
			ret = 0;
		} else {
			printf("FAIL (expected success, got %s)\n",
			       strerror(-cqe->res));
			ret = -1;
		}
	} else {
		if (cqe->res == -EACCES) {
			ret = 0;
		} else if (cqe->res < 0) {
			printf("FAIL (expected -EACCES, got %s)\n",
			       strerror(-cqe->res));
			ret = -1;
		} else {
			printf("FAIL (expected denial, got fd=%d)\n", cqe->res);
			close(cqe->res);
			ret = -1;
		}
	}

	if (ret)
		fprintf(stderr, "%s: %s: failed\n", __FUNCTION__, desc);
	io_uring_cqe_seen(ring, cqe);
	return ret;
}

