static int test_readv_fixed(struct buf_desc *bd, struct iovec *vecs, int nr_vec)
{
	unsigned buf_idx = bd->buf_idx;
	struct io_uring *ring = &bd->ring;
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	size_t total_len, i, offset;
	int ret, fd;
	char *expected;
	char filename[] = ".readv_fixed.XXXXXX";

	total_len = t_iovec_data_length(vecs, nr_vec);

	expected = malloc(total_len);
	if (!expected) {
		fprintf(stderr, "malloc failed\n");
		return 1;
	}

	/* Fill expected buffer with pattern */
	for (i = 0; i < total_len; i++)
		expected[i] = i & 0xff;

	fd = mkstemp(filename);
	if (fd < 0) {
		perror("mkstemp");
		free(expected);
		return 1;
	}
	unlink(filename);

	/* Write expected data to file */
	ret = write(fd, expected, total_len);
	if (ret != total_len) {
		fprintf(stderr, "file write failed: %d\n", ret);
		close(fd);
		free(expected);
		return 1;
	}

	/* Clear registered buffer before reading into it */
	memset(bd->buf_wr, 0, bd->size);

	/* Read using READV_FIXED - vecs already point to bd->buf_wr (registered) */
	sqe = io_uring_get_sqe(ring);
	io_uring_prep_readv_fixed(sqe, fd, vecs, nr_vec, 0, 0, buf_idx);

	ret = io_uring_submit(ring);
	if (ret != 1) {
		fprintf(stderr, "submit failed %i\n", ret);
		close(fd);
		free(expected);
		return 1;
	}

	ret = io_uring_wait_cqe(ring, &cqe);
	if (ret) {
		fprintf(stderr, "wait_cqe=%d\n", ret);
		close(fd);
		free(expected);
		return 1;
	}

	ret = cqe->res;
	io_uring_cqe_seen(ring, cqe);

	close(fd);

	if (ret != total_len) {
		fprintf(stderr, "readv_fixed: got %d, expected %zu\n", ret, total_len);
		free(expected);
		return 1;
	}

	/* Verify data across all iovec segments */
	offset = 0;
	for (i = 0; i < nr_vec; i++) {
		if (memcmp(vecs[i].iov_base, expected + offset, vecs[i].iov_len) != 0) {
			fprintf(stderr, "readv_fixed: data mismatch at segment %zu\n", i);
			free(expected);
			return 1;
		}
		offset += vecs[i].iov_len;
	}

	free(expected);
	return 0;
}

static int test_readv(struct buf_desc *bd)
{
	void *p = bd->buf_wr;
	int ret;
	struct iovec iov_page = { .iov_base = p, .iov_len = page_sz };
	struct iovec iov_multi[] = {
		{ .iov_base = p, .iov_len = page_sz },
		{ .iov_base = p + page_sz, .iov_len = page_sz },
		{ .iov_base = p + page_sz * 2, .iov_len = page_sz },
	};
	struct iovec iov_unalign = { .iov_base = p + 1, .iov_len = page_sz - 1 };

	reinit_ring(bd);

	/* Single page read */
	ret = test_readv_fixed(bd, &iov_page, 1);
	if (ret) {
		fprintf(stderr, "readv_fixed: single page failed\n");
		return ret;
	}

	/* Multi-segment read */
	reinit_ring(bd);
	ret = test_readv_fixed(bd, iov_multi, 3);
	if (ret) {
		fprintf(stderr, "readv_fixed: multi-segment failed\n");
		return ret;
	}

	/* Unaligned read */
	reinit_ring(bd);
	ret = test_readv_fixed(bd, &iov_unalign, 1);
	if (ret) {
		fprintf(stderr, "readv_fixed: unaligned failed\n");
		return ret;
	}

	return 0;
}

bool LinuxElevationChildIsElevated(qint64 Pid)
{
	const QMap<QString, QString> Status = ProcFs::ReadStatus((quint64)Pid);

	// "Uid:  real  effective  saved  fs", tab separated.
	const QString Uids = Status.value("Uid");
	if (Uids.isEmpty())
		return false;

	const QStringList Fields = Uids.split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
	if (Fields.isEmpty())
		return false;

	bool bOk = false;
	return Fields.first().toUInt(&bOk) == 0 && bOk;
}

static qint64 StartElevationChild(const QString& Program, const QStringList& Arguments, const QString& LogPath)
{
	//
	// Everything the child touches is prepared before forking: between fork and
	// exec only async-signal-safe calls are allowed, which rules out allocating.
	//
	QList<QByteArray> ArgBytes;
	ArgBytes.append(Program.toLocal8Bit());
	for (const QString& Argument : Arguments)
		ArgBytes.append(Argument.toLocal8Bit());

	QVector<char*> Argv;
	for (QByteArray& Bytes : ArgBytes)
		Argv.append(Bytes.data());
	Argv.append(nullptr);

	const QByteArray LogBytes = LogPath.toLocal8Bit();

	const pid_t Pid = fork();
	if (Pid < 0)
		return -1;

	if (Pid == 0)
	{
		const int Fd = open(LogBytes.constData(), O_WRONLY | O_CREAT | O_TRUNC, 0600);
		if (Fd >= 0)
		{
			dup2(Fd, STDERR_FILENO);
			close(Fd);
		}

		execv(Argv[0], Argv.data());
		_exit(127);	// exec failed; the parent sees this as an immediate exit
	}

	return Pid;
}

bool LinuxElevationChildAlive(qint64 Pid, int* pExitCode)
{
	if (pExitCode)
		*pExitCode = 0;

	int Status = 0;
	const pid_t Result = waitpid((pid_t)Pid, &Status, WNOHANG);

	if (Result == 0)
		return true;	// still running

	if (Result == (pid_t)Pid && pExitCode && WIFEXITED(Status))
		*pExitCode = WEXITSTATUS(Status);

	return false;
}

QString LinuxLastElevationError()
{
	QFile Log(ElevationLogPath());
	if (!Log.open(QIODevice::ReadOnly))
		return QString();

	// Only the last few lines are of interest, and a runaway file is not worth
	// pasting into a message box.
	const QString Text = QString::fromLocal8Bit(Log.read(4096)).trimmed();
	Log.close();

	return Text;
}

QString CTaskService::GetRunningWorker(bool bElevanted)
{
	QMutexLocker Locker(&m_Mutex);

#ifdef WIN32
	const QString SocketName = m_TempSocket;
#else
	const QString SocketName = bElevanted ? m_TempSocketRoot : m_TempSocket;
#endif

	if (SocketName.isEmpty())
		return QString();

	// A short probe: either it answers at once or it is gone.
	if (SendCommand(SocketName, "Refresh", 500).toBool() == true)
		return SocketName;

	return QString();
}

