void CLinuxAPI::FlushDnsCache()
{
	//
	// systemd-resolved is the only component on a stock Linux system that keeps
	// a DNS cache worth flushing. Where it is not running there is nothing to
	// do - glibc's resolver does not cache.
	//
	QDBusConnection Bus = QDBusConnection::systemBus();
	if (!Bus.isConnected())
		return;

	QDBusInterface Manager("org.freedesktop.resolve1", "/org/freedesktop/resolve1",
	                       "org.freedesktop.resolve1.Manager", Bus);
	if (!Manager.isValid())
		return;

	// FlushCaches is polkit-protected, so allow the prompt the same way service
	// control does.
	QDBusMessage Call = QDBusMessage::createMethodCall("org.freedesktop.resolve1",
	                                                   "/org/freedesktop/resolve1",
	                                                   "org.freedesktop.resolve1.Manager",
	                                                   "FlushCaches");
	Call.setInteractiveAuthorizationAllowed(true);
	Bus.call(Call, QDBus::Block, 120 * 1000);
}

void CLinuxAPI::OnHardwareChanged()
{
	m_HardwareChangePending = false;

	//
	// Re-enumerate whatever may have changed. Each of these rebuilds its device
	// list from /sys, so a disk or interface that has just appeared or gone
	// away is picked up.
	//
	m_pGpuMonitor->UpdateAdapters();
	m_pNetMonitor->UpdateAdapters();
	m_pDiskMonitor->UpdateDisks();
}

static QString ResolveModulePath(const QString& Name)
{
	static QMutex Lock;
	static QHash<QString, QString> Index;
	static bool bBuilt = false;

	QMutexLocker Locker(&Lock);

	if (!bBuilt)
	{
		bBuilt = true;

		struct utsname Uts;
		if (uname(&Uts) == 0)
		{
			const QString ModulesDir = QString("/lib/modules/%1").arg(QString::fromLocal8Bit(Uts.release));

			QFile Deps(ModulesDir + "/modules.dep");
			if (Deps.open(QIODevice::ReadOnly | QIODevice::Text))
			{
				while (!Deps.atEnd())
				{
					// "kernel/drivers/net/foo.ko.zst: kernel/drivers/bar.ko.zst ..."
					const QString Line = QString::fromUtf8(Deps.readLine());
					const QString Path = Line.section(':', 0, 0).trimmed();
					if (Path.isEmpty())
						continue;

					//
					// Strip the compression suffix and then ".ko" to recover the
					// module name. Distributions ship .ko, .ko.xz, .ko.gz and
					// .ko.zst, so this cannot assume one of them.
					//
					QString Base = Path.section('/', -1);
					if (Base.endsWith(".zst") || Base.endsWith(".xz") || Base.endsWith(".gz"))
						Base = Base.section('.', 0, -2);
					if (!Base.endsWith(".ko"))
						continue;
					Base.chop(3);

					Index.insert(Base.replace('-', '_'), ModulesDir + "/" + Path);
				}
			}
		}
	}

	QString Normalised = Name;
	return Index.value(Normalised.replace('-', '_'));
}

CLinuxDriver::CLinuxDriver(QObject *parent)
	: CDriverInfo(parent)
{
	m_Size = 0;
	m_RefCount = 0;
}

bool CLinuxDriver::InitStaticData(const QString& Name)
{
	//
	// Read before taking the lock: resolving the path can touch the filesystem.
	//
	const QString Path = ResolveModulePath(Name);

	//
	// An unresolved name is normal rather than an error: a module compiled into
	// the kernel image has no file of its own, and one loaded from outside the
	// modules tree (a locally built driver, or one inserted by full path) is not
	// in modules.dep either.
	//
	QWriteLocker Locker(&m_Mutex);

	m_Name = Name;
	m_FileName = Name;
	m_BinaryPath = Path;

	return true;
}

bool CLinuxDriver::UpdateDynamicData(quint64 Size, quint32 RefCount, const QString& UsedBy, const QString& State)
{
	QWriteLocker Locker(&m_Mutex);

	bool bChanged = (m_Size != Size) || (m_RefCount != RefCount) || (m_UsedBy != UsedBy) || (m_State != State);

	m_Size = Size;
	m_RefCount = RefCount;
	m_UsedBy = UsedBy;
	m_State = State;

	return bChanged;
}

void AppendNote(QByteArray& Notes, const char* Name, quint32 Type, const void* Desc, quint32 DescSize)
{
	const quint32 NameSize = (quint32)strlen(Name) + 1;

	Elf64_Nhdr Nhdr;
	Nhdr.n_namesz = NameSize;
	Nhdr.n_descsz = DescSize;
	Nhdr.n_type = Type;

	Notes.append((const char*)&Nhdr, sizeof(Nhdr));
	Notes.append(Name, NameSize);
	while (Notes.size() & 3)
		Notes.append('\0');
	if (DescSize)
		Notes.append((const char*)Desc, DescSize);
	while (Notes.size() & 3)
		Notes.append('\0');
}

bool IsUnreadableRegion(const ProcFs::SMapEntry& Map)
{
	if (Map.Path.startsWith("[vvar") || Map.Path == "[vsyscall]")
		return true;

	// A device mapping: has a device number but no filesystem inode.
	if (Map.Path.startsWith("/dev/"))
		return true;

	return false;
}

CLinuxDumper::CLinuxDumper(QObject* parent)
	: CMemDumper(parent)
{
	m_ProcessId = 0;
	m_DumpType = 0;
}

STATUS CLinuxDumper::PrepareDump(const CProcessPtr& pProcess, quint32 DumpType, const QString& DumpPath)
{
	if (pProcess.isNull())
		return ERR(tr("No process selected."));

	if (TE_CORE_MACHINE == 0)
		return ERR(tr("Creating a core dump is not supported on this architecture."));

	m_ProcessId = pProcess->GetProcessId();
	m_ProcessName = pProcess->GetName();
	m_DumpPath = DumpPath;
	m_DumpType = DumpType;
	m_Canceled.storeRelease(0);

	//
	// Dumping ourselves would mean this thread ptrace-stopping the thread it is
	// running on, which deadlocks.
	//
	if (m_ProcessId == (quint64)getpid())
		return ERR(tr("TaskExplorer cannot dump its own process."));

	if (!ProcFs::FileExists(ProcFs::ProcPath(m_ProcessId)))
		return ERR(tr("The process has exited."));

	const ProcFs::SStat Stat = ProcFs::ReadStat(m_ProcessId);
	if (Stat.Valid && Stat.IsKernelThread)
		return ERR(tr("Kernel threads have no user address space to dump."));

	//
	// A 32-bit target needs an ELF32 core with 32-bit register structures.
	// Writing a 64-bit core for it would produce a file gdb silently
	// misinterprets, so refuse rather than emit something misleading.
	//
	QFile Exe(ProcFs::ProcPath(m_ProcessId, "exe"));
	if (Exe.open(QIODevice::ReadOnly))
	{
		const QByteArray Ident = Exe.read(EI_NIDENT);
		Exe.close();
		if (Ident.size() >= EI_NIDENT && memcmp(Ident.constData(), ELFMAG, SELFMAG) == 0
			&& (unsigned char)Ident[EI_CLASS] == ELFCLASS32 && sizeof(void*) == 8)
			return ERR(tr("This is a 32-bit process; only 64-bit core dumps are supported."));
	}

	// Fail here, where the GUI shows a message box, rather than inside the
	// progress dialog after the process has already been stopped.
	QFile Test(m_DumpPath);
	if (!Test.open(QIODevice::WriteOnly | QIODevice::Truncate))
		return ERR(tr("Cannot write to %1: %2").arg(m_DumpPath).arg(Test.errorString()));
	Test.close();

	return OK;
}

foreach(quint64 Tid, Tids)
	{
		SThreadState Thread;
		memset(&Thread.Regs, 0, sizeof(Thread.Regs));
		memset(&Thread.FpRegs, 0, sizeof(Thread.FpRegs));
		Thread.Tid = Tid;

		//
		// PTRACE_SEIZE rather than PTRACE_ATTACH: it does not itself stop the
		// thread, so the stop is requested explicitly with PTRACE_INTERRUPT and
		// no queued SIGSTOP is left behind to confuse the target once detached.
		//
		if (ptrace(PTRACE_SEIZE, (pid_t)Tid, nullptr, nullptr) == 0)
		{
			if (ptrace(PTRACE_INTERRUPT, (pid_t)Tid, nullptr, nullptr) == 0)
			{
				int Status = 0;
				if (waitpid((pid_t)Tid, &Status, __WALL) >= 0)
				{
					Thread.Attached = true;

					struct iovec Iov;
					Iov.iov_base = &Thread.Regs;
					Iov.iov_len = sizeof(Thread.Regs);
					Thread.HaveRegs = (ptrace(PTRACE_GETREGSET, (pid_t)Tid, (void*)(uintptr_t)NT_PRSTATUS, &Iov) == 0);

					Iov.iov_base = &Thread.FpRegs;
					Iov.iov_len = sizeof(Thread.FpRegs);
					Thread.HaveFpRegs = (ptrace(PTRACE_GETREGSET, (pid_t)Tid, (void*)(uintptr_t)NT_PRFPREG, &Iov) == 0);
				}
			}

			if (!Thread.Attached)
				ptrace(PTRACE_DETACH, (pid_t)Tid, nullptr, nullptr);
		}

		if (!Thread.Attached)
		{
			// A thread that simply exited between the enumeration and the seize
			// is not a permission problem and should not be reported as one.
			if (errno != ESRCH)
			{
				AttachFailures++;
				AttachErrno = errno;
			}
		}

		// The main thread goes first: gdb treats the first NT_PRSTATUS as the
		// thread that "crashed" and selects it on load.
		if (Tid == Pid)
			Threads.prepend(Thread);
		else
			Threads.append(Thread);
	}

foreach(const SHelperDumpThread& Source, Info.Threads)
			{
				SThreadState Thread;
				memset(&Thread.Regs, 0, sizeof(Thread.Regs));
				memset(&Thread.FpRegs, 0, sizeof(Thread.FpRegs));

				Thread.Tid = Source.Tid;
				Thread.Attached = Source.Attached;

				//
				// Copied by size rather than cast: the helper ships the raw
				// struct, and a mismatch has to truncate rather than read past
				// the end of the reply.
				//
				if (Source.Regs.size() >= (int)sizeof(Thread.Regs))
				{
					memcpy(&Thread.Regs, Source.Regs.constData(), sizeof(Thread.Regs));
					Thread.HaveRegs = true;
				}
				if (Source.FpRegs.size() >= (int)sizeof(Thread.FpRegs))
				{
					memcpy(&Thread.FpRegs, Source.FpRegs.constData(), sizeof(Thread.FpRegs));
					Thread.HaveFpRegs = true;
				}

				// gdb selects the thread of the first NT_PRSTATUS, so the main
				// thread has to lead here as it does above.
				if (Thread.Tid == Pid)
					HelperThreads.prepend(Thread);
				else
					HelperThreads.append(Thread);
			}

foreach(const ProcFs::SMapEntry& Map, Maps)
	{
		SDumpRegion Region;
		Region.Start = Map.Start;
		Region.End = Map.End;
		Region.PageOffset = PageSize ? (Map.Offset / (quint64)PageSize) : 0;
		Region.Flags = (Map.Read ? PF_R : 0) | (Map.Write ? PF_W : 0) | (Map.Exec ? PF_X : 0);

		// A real file mapping, as opposed to "[heap]", "[stack]" or anonymous.
		const bool bFileBacked = (Map.Inode != 0) && Map.Path.startsWith('/');
		if (bFileBacked)
			Region.Path = Map.Path;

		const quint64 Size = Map.End - Map.Start;

		if (!Map.Read || IsUnreadableRegion(Map))
		{
			// Recorded in the core with the right address and size but no
			// contents, which is how the kernel represents them too.
			Region.DumpBytes = 0;
		}
		else if (bFullMemory)
		{
			Region.DumpBytes = Size;
		}
		else if (!bFileBacked)
		{
			// Anonymous memory: the heap, the stacks, and everything malloc'd.
			// This is where a program's actual state lives.
			Region.DumpBytes = Size;
		}
		else
		{
			//
			// A file-backed mapping whose contents can be recovered from the
			// file on disk. Only the first page is written, which is enough for
			// gdb to read the ELF header and identify the module - the same
			// trade-off as the kernel's coredump_filter "ELF headers" bit.
			//
			Region.DumpBytes = qMin<quint64>(Size, (quint64)PageSize);
		}

		Regions.append(Region);
	}

foreach(const SThreadState& Thread, Threads)
	{
		if (!Thread.HaveRegs)
			continue;	// a thread with no registers is worse than no entry at all

		const ProcFs::SStat ThreadStat = ProcFs::ReadThreadStat(Pid, Thread.Tid);

		struct elf_prstatus PrStatus;
		memset(&PrStatus, 0, sizeof(PrStatus));

		PrStatus.pr_pid = (pid_t)Thread.Tid;
		PrStatus.pr_ppid = (pid_t)Stat.PPid;
		PrStatus.pr_pgrp = (pid_t)Stat.PGrp;
		PrStatus.pr_sid = (pid_t)Stat.Session;

		if (ClockTicks > 0)
		{
			PrStatus.pr_utime.tv_sec = ThreadStat.UTime / ClockTicks;
			PrStatus.pr_utime.tv_usec = (ThreadStat.UTime % ClockTicks) * (1000000 / ClockTicks);
			PrStatus.pr_stime.tv_sec = ThreadStat.STime / ClockTicks;
			PrStatus.pr_stime.tv_usec = (ThreadStat.STime % ClockTicks) * (1000000 / ClockTicks);
		}

		memcpy(&PrStatus.pr_reg, &Thread.Regs, qMin(sizeof(PrStatus.pr_reg), sizeof(Thread.Regs)));
		PrStatus.pr_fpvalid = Thread.HaveFpRegs ? 1 : 0;

		AppendNote(Notes, "CORE", NT_PRSTATUS, &PrStatus, sizeof(PrStatus));

		if (Thread.HaveFpRegs)
			AppendNote(Notes, "CORE", NT_PRFPREG, &Thread.FpRegs, sizeof(Thread.FpRegs));
	}

foreach(const SDumpRegion& Region, Regions)
		{
			if (Region.Path.isEmpty())
				continue;

			const quint64 Triple[3] = { Region.Start, Region.End, Region.PageOffset };
			Table.append((const char*)Triple, sizeof(Triple));

			const QByteArray Path = Region.Path.toLocal8Bit();
			Paths.append(Path);
			Paths.append('\0');

			Count++;
		}

foreach(const SDumpRegion& Region, Regions)
	{
		Elf64_Phdr Phdr;
		memset(&Phdr, 0, sizeof(Phdr));
		Phdr.p_type = PT_LOAD;
		Phdr.p_flags = Region.Flags;
		Phdr.p_vaddr = Region.Start;
		Phdr.p_memsz = Region.End - Region.Start;
		// A region with no contents still gets an entry, with p_filesz 0, so
		// the debugger knows the address range existed.
		Phdr.p_offset = Region.DumpBytes ? Region.FileOffset : 0;
		Phdr.p_filesz = Region.DumpBytes;
		Phdr.p_align = PageSize;
		Core.write((const char*)&Phdr, sizeof(Phdr));
	}

QString ExtractString(const QByteArray& Table, quint64 Offset)
{
	if (Offset >= (quint64)Table.size())
		return QString();

	// The table is a run of NUL terminated strings; stop at the first one.
	const char* Start = Table.constData() + Offset;
	const quint64 Available = (quint64)Table.size() - Offset;
	const quint64 Length = qstrnlen(Start, Available);

	return QString::fromUtf8(Start, (int)Length);
}

void ParseNotes(const QByteArray& Segment, SElfInfo& Info)
{
	int Pos = 0;
	while (Pos + (int)sizeof(Elf64_Nhdr) <= Segment.size())
	{
		// Elf32_Nhdr and Elf64_Nhdr are both three 32-bit words, so one shape
		// covers either class.
		Elf32_Nhdr Nhdr;
		memcpy(&Nhdr, Segment.constData() + Pos, sizeof(Nhdr));
		Pos += sizeof(Nhdr);

		const int NameSize = (int)((Nhdr.n_namesz + 3) & ~3u);
		const int DescSize = (int)((Nhdr.n_descsz + 3) & ~3u);

		if (NameSize < 0 || DescSize < 0 || Pos + NameSize + DescSize > Segment.size())
			break;

		const QByteArray Name(Segment.constData() + Pos, (int)qMin<quint32>(Nhdr.n_namesz ? Nhdr.n_namesz - 1 : 0, (quint32)NameSize));
		const QByteArray Desc(Segment.constData() + Pos + NameSize, (int)Nhdr.n_descsz);

		if (Name == "GNU" && Nhdr.n_type == NT_GNU_BUILD_ID)
		{
			Info.BuildId = QString::fromLatin1(Desc.toHex());
		}
		else if (Name == "FDO" && Nhdr.n_type == NT_FDO_PACKAGING_METADATA)
		{
			//
			// The descriptor is NUL terminated JSON; the trailing NUL and any
			// alignment padding have to come off before parsing.
			//
			const QJsonObject Package = QJsonDocument::fromJson(
				QByteArray(Desc.constData(), (int)qstrnlen(Desc.constData(), Desc.size()))).object();

			Info.PackageName = Package.value("name").toString();
			Info.PackageVersion = Package.value("version").toString();
			Info.PackageOs = Package.value("os").toString();
		}

		Pos += NameSize + DescSize;
	}
}

bool ParseElf(QFile& File, SElfInfo& Info)
{
	TEhdr Ehdr;
	File.seek(0);
	if (File.read((char*)&Ehdr, sizeof(Ehdr)) != (qint64)sizeof(Ehdr))
		return false;

	Info.Type = Ehdr.e_type;
	Info.Machine = Ehdr.e_machine;

	if (Ehdr.e_phnum == 0 || Ehdr.e_phnum > MaxProgramHeaders || Ehdr.e_phentsize < sizeof(TPhdr))
		return false;

	QVector<TPhdr> Phdrs(Ehdr.e_phnum);
	for (int i = 0; i < (int)Ehdr.e_phnum; i++)
	{
		if (!File.seek((qint64)Ehdr.e_phoff + (qint64)i * Ehdr.e_phentsize))
			return false;
		if (File.read((char*)&Phdrs[i], sizeof(TPhdr)) != (qint64)sizeof(TPhdr))
			return false;
	}

	//
	// Addresses inside .dynamic are virtual, so they have to be translated back
	// into file offsets through the PT_LOAD segments that map them.
	//
	auto ToFileOffset = [&Phdrs](quint64 VAddr, quint64* pOffset) -> bool
	{
		foreach(const TPhdr& Phdr, Phdrs)
		{
			if (Phdr.p_type != PT_LOAD)
				continue;
			if (VAddr >= Phdr.p_vaddr && VAddr < Phdr.p_vaddr + Phdr.p_filesz)
			{
				*pOffset = Phdr.p_offset + (VAddr - Phdr.p_vaddr);
				return true;
			}
		}
		return false;
	};

	quint64 StrTabAddr = 0;
	quint64 StrTabSize = 0;
	quint64 SoNameOffset = 0;
	bool bHaveSoName = false;
	QList<quint64> NeededOffsets;

	foreach(const TPhdr& Phdr, Phdrs)
	{
		if (Phdr.p_type == PT_INTERP)
		{
			if (Phdr.p_filesz > 0 && Phdr.p_filesz < 4096 && File.seek(Phdr.p_offset))
			{
				const QByteArray Interp = File.read(Phdr.p_filesz);
				Info.Interpreter = QString::fromUtf8(Interp.constData(), (int)qstrnlen(Interp.constData(), Interp.size()));
			}
		}
		else if (Phdr.p_type == PT_NOTE)
		{
			if (Phdr.p_filesz > 0 && Phdr.p_filesz <= MaxNoteSegment && File.seek(Phdr.p_offset))
				ParseNotes(File.read(Phdr.p_filesz), Info);
		}
		else if (Phdr.p_type == PT_DYNAMIC)
		{
			if (!File.seek(Phdr.p_offset))
				continue;

			const quint64 Count = Phdr.p_filesz / sizeof(TDyn);
			for (quint64 i = 0; i < Count; i++)
			{
				TDyn Dyn;
				if (File.read((char*)&Dyn, sizeof(Dyn)) != (qint64)sizeof(Dyn))
					break;
				if (Dyn.d_tag == DT_NULL)
					break;

				switch (Dyn.d_tag)
				{
					case DT_STRTAB:	StrTabAddr = Dyn.d_un.d_ptr; break;
					case DT_STRSZ:	StrTabSize = Dyn.d_un.d_val; break;
					case DT_SONAME:	SoNameOffset = Dyn.d_un.d_val; bHaveSoName = true; break;
					case DT_NEEDED:	NeededOffsets.append(Dyn.d_un.d_val); break;
					default: break;
				}
			}
		}
	}

	//
	// The names live in the dynamic string table, which is only worth reading
	// once something actually referenced it.
	//
	if (StrTabAddr && StrTabSize && StrTabSize <= MaxStringTable && (bHaveSoName || !NeededOffsets.isEmpty()))
	{
		quint64 StrTabOffset = 0;
		if (ToFileOffset(StrTabAddr, &StrTabOffset) && File.seek(StrTabOffset))
		{
			const QByteArray StrTab = File.read(StrTabSize);

			if (bHaveSoName)
				Info.SoName = ExtractString(StrTab, SoNameOffset);

			foreach(quint64 Offset, NeededOffsets)
			{
				const QString Name = ExtractString(StrTab, Offset);
				if (!Name.isEmpty())
					Info.Needed.append(Name);
			}
		}
	}

	//
	// A position independent executable and a shared library are both ET_DYN,
	// so they have to be told apart by what else is present: an executable has
	// a program interpreter and no SONAME.
	//
	// The interpreter alone is not enough. Some libraries are also runnable and
	// carry one - glibc is the well known case, since "/lib/.../libc.so.6"
	// prints its version when executed - but they still declare a SONAME, which
	// no executable does.
	//
	Info.IsPie = (Ehdr.e_type == ET_DYN) && !Info.Interpreter.isEmpty() && Info.SoName.isEmpty();

	Info.Valid = true;
	return true;
}

foreach(const TPhdr& Phdr, Phdrs)
		{
			if (Phdr.p_type != PT_LOAD)
				continue;
			if (VAddr >= Phdr.p_vaddr && VAddr < Phdr.p_vaddr + Phdr.p_filesz)
			{
				*pOffset = Phdr.p_offset + (VAddr - Phdr.p_vaddr);
				return true;
			}
		}

foreach(const TPhdr& Phdr, Phdrs)
	{
		if (Phdr.p_type == PT_INTERP)
		{
			if (Phdr.p_filesz > 0 && Phdr.p_filesz < 4096 && File.seek(Phdr.p_offset))
			{
				const QByteArray Interp = File.read(Phdr.p_filesz);
				Info.Interpreter = QString::fromUtf8(Interp.constData(), (int)qstrnlen(Interp.constData(), Interp.size()));
			}
		}
		else if (Phdr.p_type == PT_NOTE)
		{
			if (Phdr.p_filesz > 0 && Phdr.p_filesz <= MaxNoteSegment && File.seek(Phdr.p_offset))
				ParseNotes(File.read(Phdr.p_filesz), Info);
		}
		else if (Phdr.p_type == PT_DYNAMIC)
		{
			if (!File.seek(Phdr.p_offset))
				continue;

			const quint64 Count = Phdr.p_filesz / sizeof(TDyn);
			for (quint64 i = 0; i < Count; i++)
			{
				TDyn Dyn;
				if (File.read((char*)&Dyn, sizeof(Dyn)) != (qint64)sizeof(Dyn))
					break;
				if (Dyn.d_tag == DT_NULL)
					break;

				switch (Dyn.d_tag)
				{
					case DT_STRTAB:	StrTabAddr = Dyn.d_un.d_ptr; break;
					case DT_STRSZ:	StrTabSize = Dyn.d_un.d_val; break;
					case DT_SONAME:	SoNameOffset = Dyn.d_un.d_val; bHaveSoName = true; break;
					case DT_NEEDED:	NeededOffsets.append(Dyn.d_un.d_val); break;
					default: break;
				}
			}
		}
	}

foreach(quint64 Offset, NeededOffsets)
			{
				const QString Name = ExtractString(StrTab, Offset);
				if (!Name.isEmpty())
					Info.Needed.append(Name);
			}

SElfInfo ReadElfInfo(const QString& Path)
{
	SElfInfo Info;

	QFile File(Path);
	if (!File.open(QIODevice::ReadOnly))
		return Info;

	unsigned char Ident[EI_NIDENT];
	if (File.read((char*)Ident, EI_NIDENT) != EI_NIDENT)
		return Info;

	if (memcmp(Ident, ELFMAG, SELFMAG) != 0)
		return Info;

	//
	// Only native-endian files are parsed. A cross-endian ELF would need every
	// field byte-swapped, and one cannot be mapped by a local process anyway,
	// so the effort would buy nothing.
	//
	const unsigned char Data = Ident[EI_DATA];
	const bool bNativeEndian = (Q_BYTE_ORDER == Q_LITTLE_ENDIAN) ? (Data == ELFDATA2LSB) : (Data == ELFDATA2MSB);
	if (!bNativeEndian)
		return Info;

	if (Ident[EI_CLASS] == ELFCLASS64)
	{
		Info.Is64Bit = true;
		ParseElf<Elf64_Ehdr, Elf64_Phdr, Elf64_Dyn>(File, Info);
	}
	else if (Ident[EI_CLASS] == ELFCLASS32)
	{
		Info.Is64Bit = false;
		ParseElf<Elf32_Ehdr, Elf32_Phdr, Elf32_Dyn>(File, Info);
	}

	return Info;
}

QString ElfVersionFromName(const QString& Path, const QString& SoName)
{
	//
	// Everything after ".so." is the version, by long standing convention:
	// "libc.so.6" -> "6", "libstdc++.so.6.0.33" -> "6.0.33".
	//
	static const QRegularExpression Version("\\.so\\.([0-9][0-9.]*)$");

	const QRegularExpressionMatch SoMatch = Version.match(SoName);
	if (SoMatch.hasMatch())
	{
		//
		// The SONAME usually carries only the ABI major ("libstdc++.so.6") while
		// the file it resolves to carries the full version. Prefer the longer
		// one when the resolved name agrees with the SONAME so far.
		//
		const QString Short = SoMatch.captured(1);

		const QString Resolved = QFileInfo(Path).canonicalFilePath();
		const QRegularExpressionMatch FileMatch = Version.match(Resolved);
		if (FileMatch.hasMatch())
		{
			const QString Long = FileMatch.captured(1);
			if (Long.startsWith(Short) && Long.length() > Short.length())
				return Long;
		}

		return Short;
	}

	const QRegularExpressionMatch FileMatch = Version.match(QFileInfo(Path).canonicalFilePath());
	if (FileMatch.hasMatch())
		return FileMatch.captured(1);

	return QString();
}

CLinuxHandle::CLinuxHandle(QObject *parent)
	: CHandleInfo(parent)
{
	m_Type = eUnknown;
	m_Inode = 0;
	m_Flags = 0;
}

bool CLinuxHandle::InitStaticData(quint64 Pid, quint64 Fd)
{
	//
	// The fd symlink resolves either to a path (regular files, directories,
	// devices) or to a pseudo target naming the kernel object kind:
	//   socket:[12345]  pipe:[12345]  anon_inode:[eventfd]  anon_inode:inotify
	// The number in brackets is the inode, which is how a socket fd is later
	// joined against the sock_diag/proc/net tables.
	//
	const QString Target = ProcFs::ReadLink(ProcFs::ProcPath(Pid, QString("fd/%1").arg(Fd)));
	if (Target.isEmpty())
		return false; // closed already, or not permitted

	// fdinfo gives the current offset and the open flags.
	const QByteArray FdInfo = ProcFs::ReadFile(ProcFs::ProcPath(Pid, QString("fdinfo/%1").arg(Fd)));

	return InitStaticData(Pid, Fd, Target, FdInfo);
}

bool CLinuxHandle::InitStaticData(quint64 Pid, quint64 Fd, const QString& Target, const QByteArray& FdInfo)
{
	if (Target.isEmpty())
		return false;

	EHandleType Type = eUnknown;
	quint64 Inode = 0;

	auto BracketInode = [](const QString& Text) -> quint64 {
		const int Open = Text.indexOf('[');
		const int Close = Text.lastIndexOf(']');
		if (Open < 0 || Close <= Open)
			return 0;
		return Text.mid(Open + 1, Close - Open - 1).toULongLong();
	};

	if (Target.startsWith("socket:"))
	{
		Type = eSocket;
		Inode = BracketInode(Target);
	}
	else if (Target.startsWith("pipe:"))
	{
		Type = ePipe;
		Inode = BracketInode(Target);
	}
	else if (Target.startsWith("anon_inode:"))
	{
		Type = eAnonInode;
	}
	else
	{
		// A real path. Statting it says whether it is a directory or a device;
		// this can fail for a deleted file, which keeps eFile.
		Type = eFile;
		QFileInfo Info(Target);
		if (Info.isDir())
			Type = eDirectory;
		else if (Target.startsWith("/dev/"))
			Type = eCharDevice;
	}

	quint64 Position = 0;
	quint32 Flags = 0;
	for (const QByteArray& Line : FdInfo.split('\n'))
	{
		const int Sep = Line.indexOf(':');
		if (Sep < 0)
			continue;
		const QByteArray Key = Line.left(Sep).trimmed();
		const QByteArray Value = Line.mid(Sep + 1).trimmed();

		if (Key == "pos")
			Position = Value.toULongLong();
		else if (Key == "flags")
			Flags = Value.toUInt(nullptr, 8); // octal, as the kernel prints it
		else if (Key == "ino" && Inode == 0)
			Inode = Value.toULongLong();
	}

	QWriteLocker Locker(&m_Mutex);

	m_ProcessId = Pid;
	m_HandleId = Fd;
	m_FileName = Target;
	m_Type = Type;
	m_Inode = Inode;
	m_Flags = Flags;
	m_Position = Position;

	// Only meaningful for regular files; a socket or pipe has no size.
	if (Type == eFile)
	{
		QFileInfo Info(Target);
		if (Info.exists())
			m_Size = Info.size();
	}

	return true;
}

bool CLinuxHandle::UpdateDynamicData()
{
	const quint64 Pid = GetProcessId();
	const quint64 Fd = GetHandleId();

	return UpdateDynamicData(ProcFs::ReadFile(ProcFs::ProcPath(Pid, QString("fdinfo/%1").arg(Fd))));
}

bool CLinuxHandle::UpdateDynamicData(const QByteArray& FdInfo)
{
	quint64 Position = 0;
	if (FdInfo.isEmpty())
		return false;

	for (const QByteArray& Line : FdInfo.split('\n'))
	{
		if (!Line.startsWith("pos:"))
			continue;
		Position = Line.mid(4).trimmed().toULongLong();
		break;
	}

	QWriteLocker Locker(&m_Mutex);
	const bool bChanged = (m_Position != Position);
	m_Position = Position;
	return bChanged;
}

quint32 CLinuxHandle::GetTypeIndex() const
{
	QReadLocker Locker(&m_Mutex);
	return (quint32)m_Type;
}

QString CLinuxHandle::GetTypeName() const
{
	QReadLocker Locker(&m_Mutex);
	switch (m_Type)
	{
		case eFile:		return "File";
		case eDirectory:	return "Directory";
		case eSocket:		return "Socket";
		case ePipe:		return "Pipe";
		case eAnonInode:	return "AnonInode";
		case eCharDevice:	return "CharDevice";
		case eBlockDevice:	return "BlockDevice";
		default:		break;
	}
	return "Unknown";
}

QString CLinuxHandle::GetTypeString() const
{
	QReadLocker Locker(&m_Mutex);
	switch (m_Type)
	{
		case eFile:		return tr("File");
		case eDirectory:	return tr("Directory");
		case eSocket:		return tr("Socket");
		case ePipe:		return tr("Pipe");
		case eAnonInode:	return tr("Anonymous Inode");
		case eCharDevice:	return tr("Character Device");
		case eBlockDevice:	return tr("Block Device");
		default:		break;
	}
	return tr("Unknown");
}

quint32 CLinuxHandle::GetGrantedAccess() const
{
	QReadLocker Locker(&m_Mutex);
	return m_Flags;
}

QString CLinuxHandle::GetGrantedAccessString() const
{
	QReadLocker Locker(&m_Mutex);

	QStringList Parts;

	//
	// The access mode is a two-bit field rather than a set of flags, so it is
	// switched on rather than tested.
	//
	// O_PATH is checked first because it changes what the others mean: such a
	// descriptor refers to a location in the filesystem and cannot read or write
	// at all, yet it has O_RDONLY's value of 0 in the access-mode field.
	//
	if (m_Flags & O_PATH)
	{
		Parts.append(tr("Path only"));
	}
	else
	{
		switch (m_Flags & O_ACCMODE)
		{
			case O_RDONLY:	Parts.append(tr("Read")); break;
			case O_WRONLY:	Parts.append(tr("Write")); break;
			case O_RDWR:	Parts.append(tr("Read/Write")); break;
		}
	}

	//
	// The remaining file status flags, in the order most likely to matter when
	// looking at what a process has open. Flags that only affected the original
	// open() call and are not retained by the kernel (O_CREAT, O_EXCL, O_TRUNC,
	// O_NOCTTY, O_NOFOLLOW) never appear in fdinfo, so they are not listed.
	//
	struct { int Flag; const char* Name; } static const Flags[] =
	{
		{ O_APPEND,		QT_TR_NOOP("Append")		},
		{ O_NONBLOCK,	QT_TR_NOOP("Non-blocking")	},
		{ O_DIRECT,		QT_TR_NOOP("Direct")		},	// bypasses the page cache
		{ O_SYNC,		QT_TR_NOOP("Sync")			},	// implies O_DSYNC, so test it first
		{ O_DSYNC,		QT_TR_NOOP("Data sync")		},
		{ O_ASYNC,		QT_TR_NOOP("Async")			},	// SIGIO on readiness
		{ O_NOATIME,	QT_TR_NOOP("No atime")		},
		{ O_DIRECTORY,	QT_TR_NOOP("Directory")		},
		{ O_CLOEXEC,	QT_TR_NOOP("Close on exec")	},
	};

	for (size_t i = 0; i < sizeof(Flags) / sizeof(Flags[0]); i++)
	{
		//
		// O_SYNC is O_DSYNC|__O_SYNC on Linux, so a plain bit test would report
		// "Sync, Data sync" for a single flag. Matching the whole value avoids
		// that for any such composite.
		//
		if ((m_Flags & Flags[i].Flag) == Flags[i].Flag)
		{
			if (Flags[i].Flag == O_DSYNC && (m_Flags & O_SYNC) == O_SYNC)
				continue;
			Parts.append(tr(Flags[i].Name));
		}
	}

	return Parts.join(", ");
}

STATUS CLinuxHandle::Close(bool bForce)
{
	// Linux has no equivalent of DuplicateHandle(DUPLICATE_CLOSE_SOURCE); an fd
	// belonging to another process can only be closed by ptrace-attaching and
	// issuing close() in its context.
	return ERR(tr("Closing a file descriptor of another process is not supported on Linux."));
}

STATUS ErrnoToStatus(const QString& Context, int Error)
{
	if (Error == 0)
		return OK;

	// strerror_r has two incompatible signatures; formatting the number
	// alongside the message keeps this portable and still useful.
	char Buffer[256] = { 0 };
	const char* pMessage = strerror_r(Error, Buffer, sizeof(Buffer));
	if (!pMessage)
		pMessage = Buffer;

	return ERR(QString("%1: %2 (errno %3)").arg(Context).arg(QString::fromLocal8Bit(pMessage)).arg(Error), Error);
}

QString LinuxStateToString(char State)
{
	switch (State)
	{
		case 'R': return QObject::tr("Running");
		case 'S': return QObject::tr("Sleeping");
		case 'D': return QObject::tr("Disk Sleep");
		case 'Z': return QObject::tr("Zombie");
		case 'T': return QObject::tr("Stopped");
		case 't': return QObject::tr("Tracing Stop");
		case 'X':
		case 'x': return QObject::tr("Dead");
		case 'K': return QObject::tr("Wakekill");
		case 'W': return QObject::tr("Waking");
		case 'P': return QObject::tr("Parked");
		case 'I': return QObject::tr("Idle");
	}
	return QObject::tr("Unknown");
}

QString LinuxSchedPolicyToString(int Policy)
{
	switch (Policy)
	{
		case SCHED_OTHER:	return QObject::tr("Normal");
		case SCHED_FIFO:	return QObject::tr("FIFO");
		case SCHED_RR:		return QObject::tr("Round Robin");
		case SCHED_BATCH:	return QObject::tr("Batch");
		case SCHED_IDLE:	return QObject::tr("Idle");
#ifdef SCHED_DEADLINE
		case SCHED_DEADLINE:	return QObject::tr("Deadline");
#endif
	}
	return QObject::tr("Unknown");
}

QString LinuxNiceToPriorityString(int Nice)
{
	//
	// The shared GUI expects Windows-style priority class names. Bucketing the
	// nice range onto them keeps the process list readable without inventing a
	// Linux-specific column, at the cost of being approximate by nature.
	//
	if (Nice <= -15)	return QObject::tr("Realtime");
	if (Nice <= -5)		return QObject::tr("High");
	if (Nice < 0)		return QObject::tr("Above Normal");
	if (Nice == 0)		return QObject::tr("Normal");
	if (Nice <= 9)		return QObject::tr("Below Normal");
	return QObject::tr("Idle");
}

quint64 LinuxGetAffinity(quint64 Pid, bool* pTruncated)
{
	if (pTruncated)
		*pTruncated = false;

	cpu_set_t Set;
	CPU_ZERO(&Set);

	if (sched_getaffinity((pid_t)Pid, sizeof(Set), &Set) != 0)
		return 0;

	quint64 Mask = 0;
	const int Count = CPU_SETSIZE;
	for (int i = 0; i < Count; i++)
	{
		if (!CPU_ISSET(i, &Set))
			continue;

		if (i >= 64)
		{
			// Beyond what the 64 bit interface can carry.
			if (pTruncated)
				*pTruncated = true;
			break;
		}
		Mask |= (1ULL << i);
	}

	return Mask;
}

bool LinuxSetAffinity(quint64 Pid, quint64 Mask)
{
	cpu_set_t Set;
	CPU_ZERO(&Set);

	for (int i = 0; i < 64; i++)
	{
		if (Mask & (1ULL << i))
			CPU_SET(i, &Set);
	}

	return sched_setaffinity((pid_t)Pid, sizeof(Set), &Set) == 0;
}

bool LinuxHelperNeeded()
{
	// Already privileged: a direct read is cheaper than an IPC round trip.
	return geteuid() != 0;
}

static QVariant LinuxHelperCall(const QString& Command, const QVariantMap& Parameters, int TimeoutMs = 10000)
{
	//
	// Elevated, unlike the stack tracer: the whole point of these calls is to see
	// what the current user cannot. If we are already root the helper inherits
	// that and no prompt appears.
	//
	const QString Socket = CTaskService::RunWorker(true);
	if (Socket.isEmpty())
		return QVariant();

	QVariantMap Request;
	Request["Command"] = Command;
	Request["Parameters"] = Parameters;

	const QVariant Reply = CTaskService::SendCommand(Socket, Request, TimeoutMs);

	//
	// The helper reports a rejected request as a bare string. Those must not reach
	// the callers, because QVariant will happily coerce one into whatever shape is
	// asked of it - toList() on "Invalid Parameters" yields eighteen elements, one
	// per character, and toMap() an empty map that reads as "no data" rather than
	// as an error. Turn them into an invalid variant, which every caller already
	// treats as "nothing came back".
	//
	if (Reply.typeId() == QMetaType::QString)
	{
		const QString Text = Reply.toString();
		if (Text == "Invalid Parameters" || Text == "Unknown Command")
		{
			qDebug() << "TaskHelper rejected" << Command << ":" << Text;
			return QVariant();
		}
	}

	return Reply;
}

QMap<quint64, QMap<QString, QByteArray>> LinuxHelperReadProcFiles(const QList<quint64>& Pids, const QStringList& Leaves)
{
	QMap<quint64, QMap<QString, QByteArray>> Result;
	if (Pids.isEmpty() || Leaves.isEmpty())
		return Result;

	QVariantList PidList;
	foreach(quint64 Pid, Pids)
		PidList.append(Pid);

	QVariantMap Parameters;
	Parameters["Pids"] = PidList;
	Parameters["Leaves"] = QVariant(Leaves);

	const QVariantMap Reply = LinuxHelperCall("ReadProcFiles", Parameters).toMap();

	for (auto I = Reply.begin(); I != Reply.end(); ++I)
	{
		bool bOk = false;
		const quint64 Pid = I.key().toULongLong(&bOk);
		if (!bOk)
			continue;

		QMap<QString, QByteArray> Files;
		const QVariantMap FileMap = I.value().toMap();
		for (auto J = FileMap.begin(); J != FileMap.end(); ++J)
			Files.insert(J.key(), J.value().toByteArray());

		Result.insert(Pid, Files);
	}

	return Result;
}

QByteArray LinuxHelperReadProcFile(quint64 Pid, const QString& Leaf)
{
	const QMap<quint64, QMap<QString, QByteArray>> Reply =
		LinuxHelperReadProcFiles(QList<quint64>() << Pid, QStringList() << Leaf);

	return Reply.value(Pid).value(Leaf);
}

QString LinuxHelperReadProcLink(quint64 Pid, const QString& Leaf)
{
	QVariantMap Parameters;
	Parameters["ProcessId"] = Pid;
	Parameters["Leaf"] = Leaf;

	return LinuxHelperCall("ReadProcLink", Parameters).toString();
}

foreach(const QVariant& Entry, LinuxHelperCall("ListProcFds", Parameters).toList())
		Result.append(Entry.toMap());

	return Result;
}

QByteArray LinuxHelperReadMemory(quint64 Pid, quint64 Address, quint64 Size)
{
	QVariantMap Parameters;
	Parameters["ProcessId"] = Pid;
	Parameters["Address"] = Address;
	Parameters["Size"] = Size;

	return LinuxHelperCall("ReadProcMemory", Parameters).toByteArray();
}

bool LinuxHelperDumpAttach(quint64 Pid, SHelperDumpInfo* pInfo)
{
	if (!pInfo)
		return false;

	*pInfo = SHelperDumpInfo();

	QVariantMap Parameters;
	Parameters["ProcessId"] = Pid;

	//
	// A generous timeout: this stops every thread of the target and reads its
	// register sets, which on a process with hundreds of threads takes noticeably
	// longer than an ordinary request.
	//
	const QVariant Reply = LinuxHelperCall("DumpAttach", Parameters, 60000);
	if (Reply.typeId() != QMetaType::QVariantMap)
		return false;

	const QVariantMap Map = Reply.toMap();

	foreach(const QVariant& Entry, Map.value("Threads").toList())
	{
		const QVariantMap ThreadMap = Entry.toMap();

		SHelperDumpThread Thread;
		Thread.Tid = ThreadMap.value("Tid").toULongLong();
		Thread.Attached = ThreadMap.value("Attached").toBool();
		Thread.Regs = ThreadMap.value("Regs").toByteArray();
		Thread.FpRegs = ThreadMap.value("FpRegs").toByteArray();

		if (Thread.Tid)
			pInfo->Threads.append(Thread);
	}

	pInfo->Maps = Map.value("Maps").toByteArray();
	pInfo->Auxv = Map.value("Auxv").toByteArray();
	pInfo->AttachErrno = Map.value("AttachErrno").toInt();
	pInfo->Valid = true;

	return true;
}

foreach(const QVariant& Entry, Map.value("Threads").toList())
	{
		const QVariantMap ThreadMap = Entry.toMap();

		SHelperDumpThread Thread;
		Thread.Tid = ThreadMap.value("Tid").toULongLong();
		Thread.Attached = ThreadMap.value("Attached").toBool();
		Thread.Regs = ThreadMap.value("Regs").toByteArray();
		Thread.FpRegs = ThreadMap.value("FpRegs").toByteArray();

		if (Thread.Tid)
			pInfo->Threads.append(Thread);
	}

void LinuxHelperDumpDetach(quint64 Pid)
{
	QVariantMap Parameters;
	Parameters["ProcessId"] = Pid;

	LinuxHelperCall("DumpDetach", Parameters);
}

QString LinuxDescribeContainer(quint64 Pid, const ProcFs::SNamespaces& Namespaces,
                               const QString& CGroupPath, const QString& Confinement)
{
	//
	// pid 1's namespaces define "the host". Read once: init does not change
	// namespaces, and this would otherwise be eight readlinks per process.
	//
	static const ProcFs::SNamespaces Host = ProcFs::ReadNamespaces(1);

	//
	// Runtime conventions first, because they can name the container rather
	// than merely detect it.
	//
	// The cgroup path is the usual giveaway. Docker uses
	// ".../docker-<64 hex>.scope" under systemd, or "/docker/<64 hex>"
	// otherwise; podman uses "libpod-<id>"; LXC and systemd-nspawn put their
	// machines under machine.slice.
	//
	for (const QString& Part : CGroupPath.split('/', Qt::SkipEmptyParts))
	{
		QString Id = Part;
		if (Id.endsWith(".scope"))
			Id.chop(6);

		// The ids are long hashes; the leading 12 characters are what the
		// runtimes themselves display.
		auto ShortId = [](const QString& Value) {
			return Value.length() > 12 ? Value.left(12) : Value;
		};

		if (Id.startsWith("docker-"))
			return QString("docker: %1").arg(ShortId(Id.mid(7)));
		if (Id.startsWith("libpod-"))
			return QString("podman: %1").arg(ShortId(Id.mid(7)));
		if (Id.startsWith("crio-"))
			return QString("cri-o: %1").arg(ShortId(Id.mid(5)));
		if (Id.startsWith("lxc.payload."))
			return QString("lxc: %1").arg(Id.mid(12));
		if (Id.startsWith("machine-"))
		{
			// systemd-nspawn escapes the machine name, "-" becoming "\x2d".
			QString Name = Id.mid(8);
			Name.replace("\\x2d", "-");
			return QString("machine: %1").arg(Name);
		}
	}

	// Docker without systemd cgroup driver.
	if (CGroupPath.startsWith("/docker/"))
		return QString("docker: %1").arg(CGroupPath.mid(8).left(12));

	//
	// Snap and flatpak are sandboxes rather than containers, but they are what
	// a desktop user actually encounters, and both are identifiable.
	//
	// The snap name comes from the AppArmor profile, which is where snapd puts
	// it; flatpak leaves a .flatpak-info in the sandbox's root.
	//
	if (Confinement.startsWith("snap."))
	{
		// "snap.firefox.firefox (enforce)" -> "firefox"
		const QString Profile = Confinement.section(' ', 0, 0);
		return QString("snap: %1").arg(Profile.section('.', 1, 1));
	}

	if (ProcFs::FileExists(ProcFs::ProcPath(Pid, "root/.flatpak-info")))
	{
		const QByteArray Info = ProcFs::ReadFile(ProcFs::ProcPath(Pid, "root/.flatpak-info"));
		for (const QByteArray& Line : Info.split('\n'))
		{
			if (Line.startsWith("name="))
				return QString("flatpak: %1").arg(QString::fromUtf8(Line.mid(5)).trimmed());
		}
		return "flatpak";
	}

	//
	// Nothing recognised. Fall back to reporting which namespaces differ from
	// the host's, which at least says how the process is isolated even when
	// what isolated it cannot be named.
	//
	// A zero means the link was unreadable rather than shared, so those are
	// skipped instead of being reported as differences.
	//
	QStringList Differing;
	auto Compare = [&Differing](quint64 Value, quint64 HostValue, const char* Name) {
		if (Value && HostValue && Value != HostValue)
			Differing.append(Name);
	};

	Compare(Namespaces.Pid, Host.Pid, "pid");
	Compare(Namespaces.Net, Host.Net, "net");
	Compare(Namespaces.Mnt, Host.Mnt, "mnt");
	Compare(Namespaces.User, Host.User, "user");
	Compare(Namespaces.Uts, Host.Uts, "uts");
	Compare(Namespaces.Ipc, Host.Ipc, "ipc");

	if (Differing.isEmpty())
		return QString();

	return QString("namespaced (%1)").arg(Differing.join(", "));
}

STATUS LinuxRunInTerminal(const QString& Program, const QStringList& Arguments)
{
	//
	// Terminals disagree on how a command is handed to them, so each candidate
	// carries its own separator. An empty separator means the terminal takes
	// the command as trailing arguments with no flag at all.
	//
	// "--" is the modern spelling and the only correct one for
	// gnome-terminal, whose -e was deprecated and re-parses its argument as a
	// shell word list.
	//
	static const struct { const char* Program; const char* Separator; } Terminals[] =
	{
		{ "x-terminal-emulator",	"-e" },		// the Debian alternative: whatever the user chose
		{ "konsole",				"-e" },
		{ "gnome-terminal",			"--" },
		{ "kgx",					"--" },		// GNOME Console
		{ "xfce4-terminal",			"-x" },		// -x takes the rest of the line as the command
		{ "mate-terminal",			"--" },
		{ "tilix",					"-e" },
		{ "alacritty",				"-e" },
		{ "kitty",					""   },
		{ "foot",					""   },
		{ "wezterm",				"start" },
		{ "xterm",					"-e" },
	};

	QStringList Tried;
	for (size_t i = 0; i < sizeof(Terminals) / sizeof(Terminals[0]); i++)
	{
		const QString Terminal = QStandardPaths::findExecutable(Terminals[i].Program);
		if (Terminal.isEmpty())
		{
			Tried.append(Terminals[i].Program);
			continue;
		}

		QStringList Args;
		if (Terminals[i].Separator[0])
			Args << Terminals[i].Separator;
		Args << Program << Arguments;

		if (QProcess::startDetached(Terminal, Args))
			return OK;

		Tried.append(Terminals[i].Program);
	}

	return ERR(QObject::tr("No terminal emulator could be started. Looked for: %1.").arg(Tried.join(", ")));
}

QString LinuxResolveAddress(quint64 Pid, quint64 Address, quint64* pOffset, QString* pModulePath)
{
	if (pOffset)
		*pOffset = 0;
	if (pModulePath)
		pModulePath->clear();

	if (!Address)
		return QString();

	//
	// A one-entry cache, which is all this needs: the callers walk the threads
	// of one process in a row, so the same mapping table is wanted many times
	// in immediate succession and then never again.
	//
	static QMutex Lock;
	static quint64 CachedPid = 0;
	static qint64 CachedAt = 0;
	static QList<ProcFs::SMapEntry> CachedMaps;

	QMutexLocker Locker(&Lock);

	const qint64 Now = QDateTime::currentMSecsSinceEpoch();
	if (CachedPid != Pid || Now - CachedAt > 2000)
	{
		CachedMaps = ProcFs::ReadMaps(Pid);
		CachedPid = Pid;
		CachedAt = Now;
	}

	foreach(const ProcFs::SMapEntry& Map, CachedMaps)
	{
		if (Address < Map.Start || Address >= Map.End)
			continue;

		if (Map.Path.isEmpty() || Map.Path.startsWith('['))
			break;	// anonymous or pseudo mapping; there is no module to name

		//
		// The offset is measured from the start of the *file*, not the start of
		// this mapping, so that it matches what a debugger or addr2line reports
		// for a binary whose segments are mapped separately.
		//
		const quint64 Offset = Map.Offset + (Address - Map.Start);

		if (pOffset)
			*pOffset = Offset;
		if (pModulePath)
			*pModulePath = Map.Path;

		return QString("%1+0x%2").arg(Map.Path.section('/', -1)).arg(Offset, 0, 16);
	}

	return "0x" + QString::number(Address, 16);
}

foreach(const ProcFs::SMapEntry& Map, CachedMaps)
	{
		if (Address < Map.Start || Address >= Map.End)
			continue;

		if (Map.Path.isEmpty() || Map.Path.startsWith('['))
			break;	// anonymous or pseudo mapping; there is no module to name

		//
		// The offset is measured from the start of the *file*, not the start of
		// this mapping, so that it matches what a debugger or addr2line reports
		// for a binary whose segments are mapped separately.
		//
		const quint64 Offset = Map.Offset + (Address - Map.Start);

		if (pOffset)
			*pOffset = Offset;
		if (pModulePath)
			*pModulePath = Map.Path;

		return QString("%1+0x%2").arg(Map.Path.section('/', -1)).arg(Offset, 0, 16);
	}

static QHash<QString, QString> BuildDesktopIndex()
{
	QHash<QString, QString> Index;

	//
	// XDG search order, least significant first, so that a user's own entry in
	// ~/.local/share overrides the packaged one.
	//
	QStringList Dirs = QStandardPaths::standardLocations(QStandardPaths::ApplicationsLocation);
	std::reverse(Dirs.begin(), Dirs.end());

	foreach(const QString& Dir, Dirs)
	{
		QDirIterator It(Dir, QStringList() << "*.desktop", QDir::Files, QDirIterator::Subdirectories);
		while (It.hasNext())
		{
			QFile File(It.next());
			if (!File.open(QIODevice::ReadOnly | QIODevice::Text))
				continue;

			QString Name;
			QString Exec;
			bool bInEntry = false;

			while (!File.atEnd())
			{
				const QString Line = QString::fromUtf8(File.readLine()).trimmed();

				if (Line.startsWith('['))
				{
					// Only the main group describes the application itself;
					// the "Desktop Action ..." groups describe menu entries.
					bInEntry = (Line == "[Desktop Entry]");
					if (!bInEntry && !Name.isEmpty() && !Exec.isEmpty())
						break;
					continue;
				}

				if (!bInEntry)
					continue;

				if (Name.isEmpty() && Line.startsWith("Name="))
					Name = Line.mid(5).trimmed();
				else if (Exec.isEmpty() && Line.startsWith("Exec="))
					Exec = Line.mid(5).trimmed();
			}

			if (Name.isEmpty() || Exec.isEmpty())
				continue;

			//
			// Exec is a command line: field codes (%u, %f, ...), arguments and
			// wrapper programs all have to come off to get at the program that
			// will actually be running. "env FOO=1 /usr/bin/foo %u" has to
			// yield "foo".
			//
			const QStringList Tokens = Exec.split(' ', Qt::SkipEmptyParts);
			for (int i = 0; i < Tokens.count(); i++)
			{
				QString Token = Tokens[i];

				if (Token.startsWith('%'))		// field code, and everything after it is arguments
					break;
				if (Token.contains('='))		// an environment assignment for "env"
					continue;

				const QString Base = Token.section('/', -1);
				if (Base == "env" || Base == "sh" || Base == "bash" || Base == "flatpak" || Base == "snap")
					continue;					// a wrapper; the real program is further along

				if (!Base.isEmpty())
					Index.insert(Base, Name);
				break;
			}
		}
	}

	return Index;
}

foreach(const QString& Dir, Dirs)
	{
		QDirIterator It(Dir, QStringList() << "*.desktop", QDir::Files, QDirIterator::Subdirectories);
		while (It.hasNext())
		{
			QFile File(It.next());
			if (!File.open(QIODevice::ReadOnly | QIODevice::Text))
				continue;

			QString Name;
			QString Exec;
			bool bInEntry = false;

			while (!File.atEnd())
			{
				const QString Line = QString::fromUtf8(File.readLine()).trimmed();

				if (Line.startsWith('['))
				{
					// Only the main group describes the application itself;
					// the "Desktop Action ..." groups describe menu entries.
					bInEntry = (Line == "[Desktop Entry]");
					if (!bInEntry && !Name.isEmpty() && !Exec.isEmpty())
						break;
					continue;
				}

				if (!bInEntry)
					continue;

				if (Name.isEmpty() && Line.startsWith("Name="))
					Name = Line.mid(5).trimmed();
				else if (Exec.isEmpty() && Line.startsWith("Exec="))
					Exec = Line.mid(5).trimmed();
			}

			if (Name.isEmpty() || Exec.isEmpty())
				continue;

			//
			// Exec is a command line: field codes (%u, %f, ...), arguments and
			// wrapper programs all have to come off to get at the program that
			// will actually be running. "env FOO=1 /usr/bin/foo %u" has to
			// yield "foo".
			//
			const QStringList Tokens = Exec.split(' ', Qt::SkipEmptyParts);
			for (int i = 0; i < Tokens.count(); i++)
			{
				QString Token = Tokens[i];

				if (Token.startsWith('%'))		// field code, and everything after it is arguments
					break;
				if (Token.contains('='))		// an environment assignment for "env"
					continue;

				const QString Base = Token.section('/', -1);
				if (Base == "env" || Base == "sh" || Base == "bash" || Base == "flatpak" || Base == "snap")
					continue;					// a wrapper; the real program is further along

				if (!Base.isEmpty())
					Index.insert(Base, Name);
				break;
			}
		}
	}

QString LinuxDescribeExecutable(const QString& Path)
{
	if (Path.isEmpty())
		return QString();

	static QMutex Lock;
	static QHash<QString, QString> Index;
	static bool bBuilt = false;

	QMutexLocker Locker(&Lock);
	if (!bBuilt)
	{
		//
		// Built once and kept. A desktop entry appearing while TaskExplorer is
		// running would be missed, which is a fair trade for not walking a few
		// thousand files on every process-list refresh.
		//
		Index = BuildDesktopIndex();
		bBuilt = true;
	}

	return Index.value(Path.section('/', -1));
}

STATUS LinuxRunElevated(const QString& Program, const QStringList& Arguments, qint64* pPid)
{
	if (pPid)
		*pPid = 0;

	const QByteArray SessionType = qgetenv("XDG_SESSION_TYPE");
	const QString Display = qEnvironmentVariable("DISPLAY");

	//
	// A Wayland compositor will not accept a connection from a process running
	// as a different user, so a root GUI instance has nothing to display on.
	// Under XWayland DISPLAY is still set and this can work, hence the check
	// for the display rather than the session type alone.
	//
	if (Display.isEmpty())
	{
		if (SessionType == "wayland")
		{
			return ERR(QObject::tr("Cannot restart elevated under a Wayland session: a compositor does not accept "
			                       "connections from a process running as another user. Run TaskExplorer from a "
			                       "terminal with 'sudo' instead."));
		}
		return ERR(QObject::tr("Cannot restart elevated: no X display is available."));
	}

	//
	// Helper preference:
	//
	//   pkexec     polkit's own, present wherever polkit is - which is a
	//              prerequisite for the service control anyway
	//   kdesu      KDE; handles X authority itself
	//   lxqt-sudo  LXQt equivalent
	//   gksudo     older GTK desktops, largely retired
	//
	struct SHelper { const char* Name; bool bNeedsEnv; };
	static const SHelper Helpers[] = {
		{ "pkexec",    true  },
		{ "kdesu",     false },
		{ "lxqt-sudo", false },
		{ "gksudo",    false },
		{ "gksu",      false },
	};

	for (const SHelper& Helper : Helpers)
	{
		const QString Path = QStandardPaths::findExecutable(Helper.Name);
		if (Path.isEmpty())
			continue;

		QStringList FullArgs;
		if (Helper.bNeedsEnv)
		{
			//
			// pkexec resets the environment for safety, which would leave a Qt
			// application with no way to reach the X server. Passing the few
			// variables it needs through env(1) is the documented idiom.
			//
			// XAUTHORITY is what actually grants access to the display; without
			// it the elevated process is refused by the X server.
			//
			FullArgs << "env" << ("DISPLAY=" + Display);

			//
			// XAUTHORITY must be passed explicitly even when it is unset in our
			// own environment. An X client with no XAUTHORITY falls back to
			// $HOME/.Xauthority - and the elevated process has root's HOME, so
			// it would look in /root and be refused by the X server.
			//
			QString XAuthority = qEnvironmentVariable("XAUTHORITY");
			if (XAuthority.isEmpty())
			{
				const QString Fallback = QDir::homePath() + "/.Xauthority";
				if (QFile::exists(Fallback))
					XAuthority = Fallback;
			}
			if (!XAuthority.isEmpty())
				FullArgs << ("XAUTHORITY=" + XAuthority);

			// Keep the platform plugin choice, so a session that forced xcb
			// does not get a different one as root.
			const QString Platform = qEnvironmentVariable("QT_QPA_PLATFORM");
			if (!Platform.isEmpty())
				FullArgs << ("QT_QPA_PLATFORM=" + Platform);
		}

		FullArgs << Program << Arguments;

		qint64 Pid = 0;
		if (QProcess::startDetached(Path, FullArgs, QString(), &Pid))
		{
			if (pPid)
				*pPid = Pid;
			return OK;
		}

		return ERR(QObject::tr("Failed to launch %1.").arg(Helper.Name));
	}

	return ERR(QObject::tr("Cannot restart elevated: no graphical privilege escalation helper was found. "
	                       "Install polkit (for pkexec), or run TaskExplorer from a terminal with 'sudo'."));
}

QString LinuxIoPrioToString(int IoPrio)
{
	if (IoPrio < 0)
		return QObject::tr("Unknown");

	const int Class = IoPrio >> IOPRIO_CLASS_SHIFT;
	const int Level = IoPrio & IOPRIO_PRIO_MASK;

	switch (Class)
	{
		case 0: return QObject::tr("None");
		case 1: return QObject::tr("Realtime (%1)").arg(Level);
		case 2: return QObject::tr("Best Effort (%1)").arg(Level);
		case 3: return QObject::tr("Idle");
	}
	return QObject::tr("Unknown");
}

CLinuxMemIO::CLinuxMemIO(quint64 BaseAddress, quint64 RegionSize, quint64 ProcessId, QObject* parent)
	: QIODevice(parent)
{
	m_BaseAddress = BaseAddress;
	m_RegionSize = RegionSize;
	m_ProcessId = ProcessId;
	m_MemFd = -1;
	m_bUseHelper = false;
}

bool CLinuxMemIO::open(OpenMode flags)
{
	//
	// Two mechanisms, tried in order:
	//
	//   /proc/<pid>/mem supports pread/pwrite at arbitrary offsets and is the
	//   more capable of the two, but opening it needs PTRACE_MODE_ATTACH, which
	//   Yama's ptrace_scope=1 (the Ubuntu default) restricts to descendants.
	//
	//   process_vm_readv/writev need only PTRACE_MODE_ATTACH_REALCREDS and work
	//   without an open fd, so they are the fallback. They cannot write to a
	//   read-only mapping, where /proc/<pid>/mem can.
	//
	// Failing to open the fd is therefore not an error; readData() falls back.
	//
	const QByteArray Path = ProcFs::ProcPath(m_ProcessId, "mem").toLocal8Bit();

	int OpenFlags = O_RDONLY;
	if (flags & QIODevice::WriteOnly)
		OpenFlags = (flags & QIODevice::ReadOnly) ? O_RDWR : O_WRONLY;

	m_MemFd = ::open(Path.constData(), OpenFlags | O_CLOEXEC);

	if (m_MemFd == -1)
	{
		// Probe the fallback; if even a single byte cannot be read, this process
		// is out of local reach entirely.
		char Probe = 0;
		iovec Local = { &Probe, 1 };
		iovec Remote = { (void*)(uintptr_t)m_BaseAddress, 1 };
		const bool bLocalReadable = process_vm_readv((pid_t)m_ProcessId, &Local, 1, &Remote, 1, 0) >= 0;

		if (!bLocalReadable)
		{
			//
			// Out of reach locally. An elevated helper can still read it, but it
			// cannot write - so a write request fails here rather than appearing
			// to open and then failing on the first write.
			//
			if ((flags & QIODevice::WriteOnly) || !LinuxHelperNeeded()
			 || !theConf->GetBool("Options/UseTaskHelper", false))
				return false;

			m_bUseHelper = true;
		}
		else if (flags & QIODevice::WriteOnly)
		{
			//
			// Readable through process_vm_readv, which means process_vm_writev is
			// permitted too - but it cannot write a read-only mapping, where the
			// fd could have. Nothing more to check here; the write itself reports
			// that case.
			//
		}
	}

	return QIODevice::open(flags);
}

void CLinuxMemIO::close()
{
	if (m_MemFd != -1)
	{
		::close(m_MemFd);
		m_MemFd = -1;
	}
	QIODevice::close();
}

bool CLinuxMemIO::seek(qint64 pos)
{
	if (pos < 0 || pos > (qint64)m_RegionSize)
		return false;
	return QIODevice::seek(pos);
}

qint64 CLinuxMemIO::readData(char *data, qint64 maxlen)
{
	if (maxlen <= 0)
		return 0;

	// Never read past the end of the region we were handed.
	const qint64 Remaining = (qint64)m_RegionSize - pos();
	if (Remaining <= 0)
		return 0;
	if (maxlen > Remaining)
		maxlen = Remaining;

	const quint64 Address = m_BaseAddress + (quint64)pos();

	if (m_bUseHelper)
	{
		const QByteArray Read = LinuxHelperReadMemory(m_ProcessId, Address, (quint64)maxlen);
		if (Read.isEmpty())
			return -1;

		const qint64 Length = qMin<qint64>(maxlen, Read.size());
		memcpy(data, Read.constData(), (size_t)Length);
		return Length;
	}

	if (m_MemFd != -1)
	{
		const ssize_t Length = pread(m_MemFd, data, (size_t)maxlen, (off_t)Address);
		if (Length >= 0)
			return Length;
		// Fall through: an unreadable page (a PROT_NONE guard) fails here but
		// process_vm_readv reports it identically, so there is nothing to gain
		// by retrying - return the error.
		return -1;
	}

	iovec Local = { data, (size_t)maxlen };
	iovec Remote = { (void*)(uintptr_t)Address, (size_t)maxlen };
	const ssize_t Length = process_vm_readv((pid_t)m_ProcessId, &Local, 1, &Remote, 1, 0);
	return (Length < 0) ? -1 : Length;
}

qint64 CLinuxMemIO::writeData(const char *data, qint64 len)
{
	if (len <= 0)
		return 0;

	const qint64 Remaining = (qint64)m_RegionSize - pos();
	if (Remaining <= 0)
		return 0;
	if (len > Remaining)
		len = Remaining;

	const quint64 Address = m_BaseAddress + (quint64)pos();

	if (m_MemFd != -1)
	{
		const ssize_t Length = pwrite(m_MemFd, data, (size_t)len, (off_t)Address);
		return (Length < 0) ? -1 : Length;
	}

	iovec Local = { (void*)data, (size_t)len };
	iovec Remote = { (void*)(uintptr_t)Address, (size_t)len };
	const ssize_t Length = process_vm_writev((pid_t)m_ProcessId, &Local, 1, &Remote, 1, 0);
	return (Length < 0) ? -1 : Length;
}

CLinuxMemory::CLinuxMemory(QObject *parent)
	: CMemoryInfo(parent)
{
	m_Readable = false;
	m_Writable = false;
	m_Executable = false;
	m_Shared = false;
}

bool CLinuxMemory::InitStaticData(quint64 Pid, const ProcFs::SMapEntry& Entry)
{
	QWriteLocker Locker(&m_Mutex);

	m_ProcessId = Pid;
	m_BaseAddress = Entry.Start;
	m_RegionSize = Entry.End - Entry.Start;
	m_Path = Entry.Path;

	m_Readable = Entry.Read;
	m_Writable = Entry.Write;
	m_Executable = Entry.Exec;
	m_Shared = Entry.Shared;

	if (Entry.Path == "[heap]")
		m_RegionType = eHeap;
	else if (Entry.Path == "[stack]")
		m_RegionType = eStack;
	else if (Entry.Path == "[vdso]" || Entry.Path == "[vsyscall]" || Entry.Path == "[vvar]")
		m_RegionType = eVdso;
	else if (Entry.Inode != 0)
		m_RegionType = Entry.Exec ? eImage : eMapped;
	else
		m_RegionType = ePrivate;

	// Working set fields are filled in by SetDetail() when smaps is read.
	return true;
}

void CLinuxMemory::SetDetail(const ProcFs::SMapDetail& Detail)
{
	QWriteLocker Locker(&m_Mutex);

	m_TotalWorkingSet = Detail.Rss;
	m_PrivateWorkingSet = Detail.PrivateClean + Detail.PrivateDirty;
	m_SharedWorkingSet = Detail.SharedClean + Detail.SharedDirty;
	// What is resident but not exclusively ours.
	m_ShareableWorkingSet = (Detail.Rss > m_PrivateWorkingSet) ? (Detail.Rss - m_PrivateWorkingSet) : 0;
	m_LockedWorkingSet = Detail.Locked;

	//
	// Committed and private size have no exact Linux counterpart. Rss is what
	// is actually backed by physical memory, which is the closest useful
	// meaning for the "committed" column.
	//
	m_CommittedSize = Detail.Rss;
	m_PrivateSize = m_PrivateWorkingSet;
}

QString CLinuxMemory::GetTypeString() const
{
	QReadLocker Locker(&m_Mutex);
	switch (m_RegionType)
	{
		case eImage:	return tr("Image");
		case eMapped:	return tr("Mapped");
		case ePrivate:	return tr("Private");
		case eHeap:	return tr("Heap");
		case eStack:	return tr("Stack");
		case eVdso:	return tr("Kernel");
		default:	break;
	}
	return tr("Unknown");
}

QString CLinuxMemory::GetProtectionString() const
{
	QReadLocker Locker(&m_Mutex);

	QString Protection;
	Protection += m_Readable   ? "r" : "-";
	Protection += m_Writable   ? "w" : "-";
	Protection += m_Executable ? "x" : "-";
	Protection += m_Shared     ? "s" : "p";
	return Protection;
}

QString CLinuxMemory::GetAllocProtectionString() const
{
	// Linux does not record the protection a mapping was originally created
	// with, only its current one.
	return GetProtectionString();
}

bool CLinuxMemory::IsFree() const
{
	// /proc/<pid>/maps only lists mapped regions, so nothing enumerated here is
	// free. Gaps between entries are synthesised by the caller if needed.
	return false;
}

bool CLinuxMemory::IsExecutable() const
{
	QReadLocker Locker(&m_Mutex);
	return m_Executable;
}

bool CLinuxMemory::IsMapped() const
{
	QReadLocker Locker(&m_Mutex);
	return m_RegionType == eImage || m_RegionType == eMapped;
}

bool CLinuxMemory::IsPrivate() const
{
	QReadLocker Locker(&m_Mutex);
	return !m_Shared;
}

QString CLinuxMemory::GetUseString() const
{
	QReadLocker Locker(&m_Mutex);
	return m_Path;
}

STATUS CLinuxMemory::SetProtect(quint32 Protect)
{
	// mprotect only acts on the calling process; changing another process's
	// protection needs ptrace.
	return ERR(tr("Changing memory protection of another process is not supported on Linux."));
}

STATUS CLinuxMemory::DumpMemory(QIODevice* pFile)
{
	if (!pFile)
		return ERR(tr("No output file."));

	QReadLocker Locker(&m_Mutex);
	const quint64 BaseAddress = m_BaseAddress;
	const quint64 RegionSize = m_RegionSize;
	const quint64 ProcessId = m_ProcessId;
	Locker.unlock();

	CLinuxMemIO Reader(BaseAddress, RegionSize, ProcessId);
	if (!Reader.open(QIODevice::ReadOnly))
		return ERR(tr("Failed to open process memory. This usually means ptrace access was denied; see /proc/sys/kernel/yama/ptrace_scope."));

	// Copied in chunks so a large region does not have to be held in memory.
	const qint64 ChunkSize = 64 * 1024;
	QByteArray Chunk;
	quint64 Total = 0;

	while (Total < RegionSize)
	{
		Chunk = Reader.read(ChunkSize);
		if (Chunk.isEmpty())
			break; // hit an unreadable page, or the end

		if (pFile->write(Chunk) != Chunk.size())
			return ERR(tr("Failed to write the dump file."));

		Total += Chunk.size();
	}

	if (Total == 0)
		return ERR(tr("Failed to read process memory."));

	return OK;
}

QIODevice* CLinuxMemory::MkDevice()
{
	QReadLocker Locker(&m_Mutex);
	return new CLinuxMemIO(m_BaseAddress, m_RegionSize, m_ProcessId);
}

CLinuxModule::CLinuxModule(QObject *parent)
	: CModuleInfo(parent)
{
	m_IsExecutable = false;
}

bool CLinuxModule::InitStaticData(const QString& FileName, quint64 BaseAddress, quint64 Size)
{
	QWriteLocker Locker(&m_Mutex);

	m_FileName = FileName;
	m_ModuleName = QFileInfo(FileName).fileName();
	m_BaseAddress = BaseAddress;
	m_Size = Size;

	QFileInfo Info(FileName);
	if (Info.exists())
	{
		m_FileSize = Info.size();
		m_ModificationTime = Info.lastModified().toMSecsSinceEpoch();

		//
		// ELF has no VERSIONINFO resource, so the three columns the shared GUI
		// expects are assembled from what the format does carry. See LinuxElf.h
		// for where each piece comes from; anything genuinely unavailable is
		// left blank rather than filled with a guess.
		//
		const SElfInfo Elf = ReadElfInfo(FileName);
		if (Elf.Valid)
		{
			m_FileDetails["FileVersion"] = !Elf.PackageVersion.isEmpty()
				? Elf.PackageVersion
				: ElfVersionFromName(FileName, Elf.SoName);

			// Only .note.package names a vendor; there is no other honest source.
			m_FileDetails["CompanyName"] = Elf.PackageOs;

			m_FileDetails["Description"] = !Elf.PackageName.isEmpty()
				? Elf.PackageName
				: LinuxDescribeExecutable(FileName);

			if (!Elf.SoName.isEmpty())
				m_FileDetails["InternalName"] = Elf.SoName;
			if (!Elf.BuildId.isEmpty())
				m_FileDetails["BuildId"] = Elf.BuildId;
		}
	}

	return true;
}

STATUS CLinuxModule::Unload(bool bForce)
{
	// Would require ptrace-injecting a dlclose() into the target.
	return ERR(tr("Unloading a module from a running process is not supported on Linux."));
}

CLinuxProcess::CLinuxProcess(QObject *parent)
	: CProcessInfo(parent)
{
	m_State = '\0';
	m_Nice = 0;
	m_SchedPolicy = 0;
	m_Uid = 0;
	m_CapEff = 0;
	m_Gid = 0;
	m_PeakNumberOfHandles = 0;
	m_StartTimeTicks = 0;
	m_IsKernelThread = false;
	m_LastSysTimePerCpu = 0;
	m_bSystemService = false;
	m_IoPrio = -1;
	m_RollupTime = 0;
	m_OomScore = 0;
	m_OomScoreAdj = 0;
	m_InotifyWatches = 0;
	m_InotifyTime = 0;
}

bool CLinuxProcess::InitStaticData(quint64 Pid)
{
	const ProcFs::SStat Stat = ProcFs::ReadStat(Pid);
	if (!Stat.Valid)
		return false; // process exited between enumeration and this read

	//
	// Read everything that needs no lock before taking one - these are all
	// separate /proc files and any of them can fail if the process exits
	// underneath us.
	//
	const QString ExePath = ProcFs::ReadLink(ProcFs::ProcPath(Pid, "exe"));
	const QStringList CmdLine = ProcFs::ReadNulList(ProcFs::ProcPath(Pid, "cmdline"));
	const QMap<QString, QString> Status = ProcFs::ReadStatus(Pid);
	const ProcFs::SServiceUnit ServiceUnit = ProcFs::ReadServiceUnit(Pid);

	//
	// Read once: a process does not normally change cgroup, namespaces or LSM
	// profile after it has started, and all three would otherwise cost extra
	// reads on every refresh of every process.
	//
	const QString CGroupPath = ProcFs::ReadCGroupPath(Pid);
	const ProcFs::SNamespaces Namespaces = ProcFs::ReadNamespaces(Pid);
	const QString Confinement = ProcFs::ReadProcSecurity(Pid).Confinement;
	const QString Container = LinuxDescribeContainer(Pid, Namespaces, CGroupPath, Confinement);

	//
	// The Uid line is "real effective saved filesystem"; the effective uid is
	// what determines what the process can do, so that is what is shown.
	//
	quint32 Uid = 0;
	quint32 Gid = 0;
	const QStringList UidFields = Status.value("Uid").split('\t', Qt::SkipEmptyParts);
	if (UidFields.size() > 1)
		Uid = UidFields[1].toUInt();
	const QStringList GidFields = Status.value("Gid").split('\t', Qt::SkipEmptyParts);
	if (GidFields.size() > 1)
		Gid = GidFields[1].toUInt();

	const quint64 StartTimeMs = ProcFs::StartTimeToEpochMs(Stat.StartTime);

	QWriteLocker Locker(&m_Mutex);

	m_ProcessId = Pid;
	m_ParentProcessId = Stat.PPid;
	m_ProcessUId = SProcessUID(Pid, StartTimeMs);

	m_FileName = ExePath;

	m_IsKernelThread = Stat.IsKernelThread;

	//
	// Naming. Neither source is right on its own:
	//
	//   comm is what the process calls itself and what ps/top/ss display, but
	//   the kernel truncates it to 15 characters ("systemd-journald" arrives as
	//   "systemd-journal").
	//
	//   The exe basename is never truncated, but it is the file name rather
	//   than the program name, and those diverge for version-directory layouts
	//   - Claude Code installs as ".../claude/versions/2.1.220", so the exe
	//   basename is "2.1.220" where comm correctly says "claude".
	//
	// So: use the exe basename only when comm looks like a truncation of it
	// (i.e. comm is a prefix), which recovers the untruncated name. When the
	// two genuinely disagree, comm is the program's own idea of its name and
	// wins.
	//
	// Kernel threads get the conventional [brackets]. Note that an unreadable
	// exe link does NOT mean kernel thread - see ProcFs::SStat::IsKernelThread.
	//
	if (Stat.IsKernelThread)
	{
		m_ProcessName = "[" + Stat.Comm + "]";
	}
	else if (!ExePath.isEmpty())
	{
		const QString ExeName = QFileInfo(ExePath).fileName();
		m_ProcessName = ExeName.startsWith(Stat.Comm) ? ExeName : Stat.Comm;
	}
	else
	{
		m_ProcessName = Stat.Comm;
	}

	// argv is NUL separated; joining with spaces matches what the Windows
	// backend shows, at the cost of being ambiguous for arguments containing
	// spaces. The raw list is still available from /proc if ever needed.
	m_CommandLine = CmdLine.join(' ');

	m_Uid = Uid;
	m_Gid = Gid;
	m_UserName = ProcFs::UserNameFromUid(Uid);

	// Read once: a process does not normally migrate between cgroups, and this
	// would otherwise be an extra file read per process per refresh.
	m_ServiceName = ServiceUnit.Name;
	m_bSystemService = ServiceUnit.bSystemSlice;

	m_CGroupPath = CGroupPath;
	m_Namespaces = Namespaces;
	m_Confinement = Confinement;
	m_Container = Container;

	m_StartTimeTicks = Stat.StartTime;
	// Real start time rather than "when we first saw it", so the new-process
	// highlight is correct for processes that predate our startup.
	m_CreateTimeStamp = StartTimeMs;

	m_LastStat = Stat;

	return true;
}

bool CLinuxProcess::UpdateDynamicData(bool bFullProcessInfo, quint64 SysTime, quint64 SysTimePerCpu)
{
	const quint64 Pid = GetProcessId();
	m_LastSysTimePerCpu = SysTimePerCpu;

	const ProcFs::SStat Stat = ProcFs::ReadStat(Pid);
	if (!Stat.Valid)
		return false;

	const ProcFs::SStatM StatM = ProcFs::ReadStatM(Pid);
	const ProcFs::SProcIo Io = ProcFs::ReadProcIo(Pid);
	// Refused for other users' processes unless privileged; the API layer
	// collects these and asks TaskHelper for them in one batch.
	const bool bIoUnreadable = !Io.Valid;
	const QMap<QString, QString> Status = ProcFs::ReadStatus(Pid);

	const quint64 PageSize = ProcFs::PageSize();

	// /proc/<pid>/status reports these in kB; VmPeak/VmHWM have no counterpart
	// in stat/statm, which is why status is read at all.
	auto StatusKb = [&Status](const char* Key) -> quint64 {
		const QString Value = Status.value(Key);
		if (Value.isEmpty())
			return 0;
		return Value.split(' ', Qt::SkipEmptyParts).value(0).toULongLong() * 1024;
	};

	// Both are syscalls rather than file reads, and both are cheap; sampling
	// them here keeps the const getters free of side effects.
	const quint64 AffinityMask = LinuxGetAffinity(Pid);
	const int IoPrio = LinuxGetIoPrio(Pid);

	//
	// The effective capability set, as a hex mask. A process can drop
	// capabilities at any time, so this is sampled per refresh rather than once
	// - and status is being read here anyway, so it is free.
	//
	const quint64 CapEff = Status.value("CapEff").trimmed().toULongLong(nullptr, 16);

	// Two tiny reads, and the score moves with memory usage, so it is sampled
	// every refresh like the rest of the counters.
	const ProcFs::SOomInfo OomInfo = ProcFs::ReadOomInfo(Pid);

	//
	// Counting inotify watches costs a readlink per open descriptor, so it runs
	// on a slow cadence of its own rather than on every refresh. The number
	// moves rarely, and the reason to look at it - finding what is exhausting
	// fs.inotify.max_user_watches - does not need second-by-second resolution.
	//
	quint64 InotifyWatches = m_InotifyWatches;
	const quint64 Now = QDateTime::currentMSecsSinceEpoch();
	const bool bCountInotify = (Now - m_InotifyTime > 10000);
	if (bCountInotify)
		InotifyWatches = ProcFs::CountInotifyWatches(Pid);

	const quint32 NumThreads = (quint32)Stat.NumThreads;
	// There is no cheap fd count; the kernel exposes it only by listing the
	// directory, which is a syscall per process per refresh.
	const quint32 NumHandles = (quint32)ProcFs::EnumFds(Pid).count();

	bool bChanged = false;

	QWriteLocker Locker(&m_Mutex);

	bChanged |= (m_State != Stat.State);
	m_State = Stat.State;
	m_Nice = (qint32)Stat.Nice;
	m_SchedPolicy = (qint32)Stat.Policy;

	bChanged |= (m_NumberOfThreads != NumThreads);
	m_NumberOfThreads = NumThreads;
	if (NumThreads > m_PeakNumberOfThreads)
		m_PeakNumberOfThreads = NumThreads;

	bChanged |= (m_NumberOfHandles != NumHandles);
	m_NumberOfHandles = NumHandles;
	if (NumHandles > m_PeakNumberOfHandles)
		m_PeakNumberOfHandles = NumHandles;

	m_VirtualSize = Stat.VSize;
	m_PeakVirtualSize = StatusKb("VmPeak");
	m_WorkingSetSize = (quint64)Stat.Rss * PageSize;
	m_PeakWorkingSetSize = StatusKb("VmHWM");
	// statm's "shared" counts pages backed by a file; the rest of the resident
	// set is private, which is the closest analogue to the Windows private
	// working set.
	if (StatM.Valid)
		m_WorkingSetPrivateSize = (StatM.Resident > StatM.Shared) ? (StatM.Resident - StatM.Shared) * PageSize : 0;
	m_PeakPagefileUsage = StatusKb("VmSwap");

	m_KernelTime = Stat.STime;
	m_UserTime = Stat.UTime;

	// The GUI shows the nice value where Windows shows a priority class.
	m_Priority = Stat.Nice;
	m_BasePriority = Stat.Priority;

	m_AffinityMask = AffinityMask;
	m_IoPrio = IoPrio;
	m_CapEff = CapEff;
	m_bIoUnreadable = bIoUnreadable;

	if (OomInfo.Valid)
	{
		m_OomScore = OomInfo.Score;
		m_OomScoreAdj = OomInfo.ScoreAdj;
	}

	if (bCountInotify)
	{
		m_InotifyWatches = InotifyWatches;
		m_InotifyTime = Now;
	}
	m_IOPriority = IoPrio;

	m_LastStat = Stat;

	Locker.unlock();

	QWriteLocker StatsLocker(&m_StatsMutex);

	m_CpuStats.CpuKernelDelta.Update(Stat.STime);
	m_CpuStats.CpuUserDelta.Update(Stat.UTime);
	// Faults are cumulative counters, so the delta is what is interesting.
	m_CpuStats.PageFaultsDelta.Update64(Stat.MinFlt + Stat.MajFlt);
	m_CpuStats.HardFaultsDelta.Update64(Stat.MajFlt);
	m_CpuStats.PrivateBytesDelta.Update(m_WorkingSetPrivateSize);
	m_CpuStats.UpdateStats(SysTime);

	if (Io.Valid)
	{
		// read_bytes/write_bytes are actual block layer traffic; rchar/wchar
		// include cache hits. Disk gets the former, Io the latter, matching how
		// the Windows backend separates disk from total I/O.
		m_Stats.Disk.SetRead(Io.ReadBytes, Io.SysCr);
		m_Stats.Disk.SetWrite(Io.WriteBytes, Io.SysCw);
		m_Stats.Io.SetRead(Io.RChar, Io.SysCr);
		m_Stats.Io.SetWrite(Io.WChar, Io.SysCw);
	}
	m_Stats.UpdateStats();

	return bChanged;
}

bool CLinuxProcess::ValidateParent(CProcessInfo* pParent) const
{
	if (!pParent)
		return false;

	// A process cannot be its own parent; pid 1 reports ppid 0, and pid 0 is
	// not a real process, so both would otherwise form a cycle in the tree.
	if (pParent->GetProcessId() == GetProcessId())
		return false;

	// A recycled pid shows up as a "parent" that started after its child.
	return pParent->GetCreateTimeStamp() <= GetCreateTimeStamp();
}

QString CLinuxProcess::GetArchString() const
{
	QString FileName = GetFileName();
	if (FileName.isEmpty())
		return QString(); // kernel thread

	//
	// EI_CLASS, the fifth byte of the ELF header: 1 = 32 bit, 2 = 64 bit.
	//
	QFile File(FileName);
	if (!File.open(QIODevice::ReadOnly))
		return QString();

	const QByteArray Header = File.read(5);
	if (Header.size() < 5 || !Header.startsWith("\x7f" "ELF"))
		return QString();

	switch (Header[4])
	{
		case 1: return "32-bit";
		case 2: return "64-bit";
	}
	return QString();
}

quint64 CLinuxProcess::GetSessionID() const
{
	// The session id from stat, i.e. the setsid() group. Not the same thing as
	// a logind/desktop session, which lives in /proc/<pid>/cgroup.
	QReadLocker Locker(&m_Mutex);
	return m_LastStat.Session;
}

quint16 CLinuxProcess::GetSubsystem() const
{
	// linux-todo: distinguish native / Wine / WSL-style processes.
	return 0;
}

QString CLinuxProcess::GetWorkingDirectory() const
{
	// Readable only for our own processes unless privileged; an empty string is
	// the correct answer for "not permitted".
	const quint64 Pid = GetProcessId();

	const QString Directory = ProcFs::ReadLink(ProcFs::ProcPath(Pid, "cwd"));
	if (!Directory.isEmpty())
		return Directory;

	// Another user's cwd needs privileges; ask the helper rather than show blank.
	if (LinuxHelperNeeded())
		return LinuxHelperReadProcLink(Pid, "cwd");

	return QString();
}

quint32 CLinuxProcess::GetPeakNumberOfHandles() const
{
	// The kernel does not track a peak fd count; this is accumulated by
	// UpdateDynamicData instead.
	QReadLocker Locker(&m_Mutex);
	return m_PeakNumberOfHandles;
}

ProcFs::SMapDetail CLinuxProcess::GetRollup() const
{
	//
	// smaps_rollup is aggregated by the kernel, so it is far cheaper than
	// summing smaps - but it is still a page table walk over the whole address
	// space, and these are column getters that the model calls for every
	// visible row on every repaint.
	//
	// So it is read on demand and cached briefly. The columns that use it are
	// off by default, which means an unprivileged user browsing the default
	// layout never pays for it at all.
	//
	const quint64 Now = GetCurTick();

	QReadLocker ReadLocker(&m_Mutex);
	if (m_RollupTime && (Now - m_RollupTime) < 1000)
		return m_Rollup;
	const quint64 Pid = m_ProcessId;
	ReadLocker.unlock();

	const ProcFs::SMapDetail Rollup = ProcFs::ReadMapRollup(Pid);

	QWriteLocker WriteLocker(&m_Mutex);
	m_Rollup = Rollup;
	m_RollupTime = Now;
	return m_Rollup;
}

quint64 CLinuxProcess::GetSharedWorkingSetSize() const
{
	const ProcFs::SMapDetail Rollup = GetRollup();
	return Rollup.SharedClean + Rollup.SharedDirty;
}

quint64 CLinuxProcess::GetShareableWorkingSetSize() const
{
	// Resident minus what is exclusively ours: the portion that is, or could
	// be, shared with another process.
	const ProcFs::SMapDetail Rollup = GetRollup();
	const quint64 Private = Rollup.PrivateClean + Rollup.PrivateDirty;
	return (Rollup.Rss > Private) ? (Rollup.Rss - Private) : 0;
}

quint64 CLinuxProcess::GetMinimumWS() const
{
	// No Linux equivalent of a working set minimum; RLIMIT_RSS is advisory and
	// unused by modern kernels.
	return 0;
}

quint64 CLinuxProcess::GetMaximumWS() const
{
	// linux-todo: RLIMIT_RSS from /proc/<pid>/limits, if it is ever meaningful.
	return 0;
}

QString CLinuxProcess::GetStatusString() const
{
	QReadLocker Locker(&m_Mutex);
	return LinuxStateToString(m_State);
}

bool CLinuxProcess::IsSystemProcess() const
{
	QReadLocker Locker(&m_Mutex);
	return m_IsKernelThread || m_Uid == 0;
}

bool CLinuxProcess::IsServiceProcess() const
{
	QReadLocker Locker(&m_Mutex);
	//
	// Only system.slice units count here. See ProcFs::SServiceUnit for why
	// simply "belongs to a .service" is too broad on a desktop session.
	// GetServiceName() still reports the unit for any process that has one.
	//
	return m_bSystemService;
}

bool CLinuxProcess::IsUserProcess() const
{
	QReadLocker Locker(&m_Mutex);
	// Below UID_MIN (1000 on most distributions) uids belong to system accounts.
	return !m_IsKernelThread && m_Uid >= 1000;
}

bool CLinuxProcess::IsElevated() const
{
	QReadLocker Locker(&m_Mutex);

	//
	// Root, or holding capabilities a normal user does not.
	//
	// A uid check alone would miss the interesting cases: ping, dumpcap and
	// anything else with file capabilities runs as an ordinary user but is
	// genuinely privileged, which is exactly what this column is meant to
	// surface. CapEff is sampled in UpdateDynamicData.
	//
	return m_Uid == 0 || m_CapEff != 0;
}

bool CLinuxProcess::IsPowerThrottled() const
{
	// No direct Linux counterpart; cgroup cpu throttling is the closest.
	return false;
}

bool CLinuxProcess::HasDebugger() const
{
	// TracerPid is 0 unless something is ptrace-attached to this process.
	return ProcFs::ReadStatus(GetProcessId()).value("TracerPid").toULongLong() != 0;
}

STATUS CLinuxProcess::AttachDebugger()
{
	const quint64 Pid = GetProcessId();

	if (Pid == (quint64)getpid())
		return ERR(tr("TaskExplorer cannot debug itself."));

	if (HasDebugger())
		return ERR(tr("This process is already being traced."));

	//
	// Windows looks up the system's postmortem debugger in the AeDebug registry
	// key. Linux has no such registry, so the debugger is whichever of the two
	// usual ones is installed - both take "-p <pid>" to attach.
	//
	QString Debugger = QStandardPaths::findExecutable("gdb");
	if (Debugger.isEmpty())
		Debugger = QStandardPaths::findExecutable("lldb");
	if (Debugger.isEmpty())
		return ERR(tr("No debugger is installed. Install gdb or lldb."));

	//
	// A debugger is an interactive program, so it needs a terminal of its own;
	// started without one it would attach and immediately have nowhere to read
	// commands from.
	//
	const STATUS Status = LinuxRunInTerminal(Debugger, QStringList() << "-p" << QString::number(Pid));
	if (Status.IsError())
		return Status;

	//
	// Whether the attach itself succeeds is up to the debugger and the kernel:
	// under the default Yama policy (ptrace_scope=1) gdb can only attach to its
	// own descendants unless it is privileged. It reports that in its own
	// window, which is a better place for it than a dialog here.
	//
	return OK;
}

STATUS CLinuxProcess::DetachDebugger()
{
	//
	// Not possible, and not a gap in this implementation: on Linux only the
	// tracer itself can call PTRACE_DETACH. There is no interface for a third
	// party to break someone else's ptrace attachment.
	//
	// Naming the tracer at least makes the message actionable.
	//
	const quint64 TracerPid = ProcFs::ReadStatus(GetProcessId()).value("TracerPid").toULongLong();
	if (!TracerPid)
		return ERR(tr("This process is not being traced."));

	const ProcFs::SStat Tracer = ProcFs::ReadStat(TracerPid);
	const QString Name = Tracer.Valid ? Tracer.Comm : tr("unknown");

	return ERR(tr("Only the debugger itself can detach. This process is being traced by %1 (pid %2); "
	              "quit it there, or terminate it.").arg(Name).arg(TracerPid));
}

bool CLinuxProcess::HasPriorityBoost() const
{
	// Linux has no per-process priority boost toggle.
	return false;
}

QString CLinuxProcess::GetPriorityString() const
{
	QReadLocker Locker(&m_Mutex);
	return LinuxNiceToPriorityString(m_Nice);
}

STATUS CLinuxProcess::SetPriority(qint32 Value)
{
	// Lowering the nice value (raising priority) requires CAP_SYS_NICE, so this
	// is expected to fail for unprivileged callers going below 0.
	errno = 0;
	if (setpriority(PRIO_PROCESS, (id_t)GetProcessId(), Value) != 0 && errno != 0)
		return ErrnoToStatus(tr("Failed to set process priority"));

	QWriteLocker Locker(&m_Mutex);
	m_Nice = Value;
	m_Priority = Value;
	return OK;
}

QString CLinuxProcess::GetBasePriorityString() const
{
	QReadLocker Locker(&m_Mutex);
	return LinuxSchedPolicyToString(m_SchedPolicy);
}

STATUS CLinuxProcess::SetBasePriority(qint32 Value)
{
	//
	// The scheduling policy would be sched_setscheduler, but nothing in the
	// shared GUI ever calls this - the Windows base priority is read only, so
	// no menu is wired to it. Left as an explicit refusal rather than an
	// unreachable implementation.
	//
	return ERR(tr("Setting the scheduling policy is not supported; use chrt(1)."));
}

QString CLinuxProcess::GetPagePriorityString() const
{
	// Linux exposes no page priority; oom_score_adj is the nearest analogue and
	// is reported separately.
	return QString();
}

QString CLinuxProcess::GetIOPriorityString() const
{
	// Sampled in UpdateDynamicData rather than queried here, so that repainting
	// the process list does not issue a syscall per visible row.
	QReadLocker Locker(&m_Mutex);
	return LinuxIoPrioToString(m_IoPrio);
}

STATUS CLinuxProcess::SetIOPriority(qint32 Value)
{
	//
	// The GUI hands over a raw ioprio value as produced by LinuxMakeIoPrio.
	// Raising into the realtime class needs CAP_SYS_ADMIN, so that is expected
	// to fail unprivileged.
	//
	if (LinuxSetIoPrio(GetProcessId(), Value) != 0)
		return ErrnoToStatus(tr("Failed to set the I/O priority"));

	QWriteLocker Locker(&m_Mutex);
	m_IoPrio = Value;
	m_IOPriority = Value;
	return OK;
}

STATUS CLinuxProcess::SetOomScoreAdj(int Value)
{
	if (Value < -1000 || Value > 1000)
		return ERR(tr("The OOM adjustment must be between -1000 and 1000."));

	if (!ProcFs::WriteOomScoreAdj(GetProcessId(), Value))
	{
		//
		// Raising the value is unprivileged; lowering it below what the process
		// already has needs CAP_SYS_RESOURCE, because that would protect a
		// process from the OOM killer at everyone else's expense.
		//
		if (errno == EACCES || errno == EPERM)
			return ERR(tr("Lowering the OOM adjustment requires root (CAP_SYS_RESOURCE)."), errno);
		return ErrnoToStatus(tr("Failed to set the OOM adjustment"));
	}

	QWriteLocker Locker(&m_Mutex);
	m_OomScoreAdj = Value;
	return OK;
}

STATUS CLinuxProcess::SetAffinityMask(quint64 Value)
{
	if (Value == 0)
		return ERR(tr("The affinity mask must select at least one CPU."));

	if (!LinuxSetAffinity(GetProcessId(), Value))
		return ErrnoToStatus(tr("Failed to set the affinity mask"));

	QWriteLocker Locker(&m_Mutex);
	m_AffinityMask = Value;
	return OK;
}

STATUS CLinuxProcess::Terminate(bool bForce)
{
	// SIGTERM asks politely and can be caught or ignored; SIGKILL cannot be,
	// which matches what "force" means on the Windows side.
	if (kill((pid_t)GetProcessId(), bForce ? SIGKILL : SIGTERM) != 0)
		return ErrnoToStatus(tr("Failed to terminate process"));
	return OK;
}

bool CLinuxProcess::IsSuspended() const
{
	QReadLocker Locker(&m_Mutex);
	return m_State == 'T';
}

STATUS CLinuxProcess::Suspend()
{
	if (kill((pid_t)GetProcessId(), SIGSTOP) != 0)
		return ErrnoToStatus(tr("Failed to suspend process"));
	return OK;
}

STATUS CLinuxProcess::Resume()
{
	if (kill((pid_t)GetProcessId(), SIGCONT) != 0)
		return ErrnoToStatus(tr("Failed to resume process"));
	return OK;
}

void CLinuxProcess::SetHelperProcIo(const QByteArray& IoText)
{
	const ProcFs::SProcIo Io = ProcFs::ParseProcIo(IoText);
	if (!Io.Valid)
		return;

	QWriteLocker Locker(&m_Mutex);
	m_bIoUnreadable = false;
	Locker.unlock();

	QWriteLocker StatsLocker(&m_StatsMutex);

	//
	// The same assignment UpdateDynamicData makes, so the delta and rate
	// machinery sees an uninterrupted series of cumulative counters.
	//
	m_Stats.Disk.SetRead(Io.ReadBytes, Io.SysCr);
	m_Stats.Disk.SetWrite(Io.WriteBytes, Io.SysCw);
	m_Stats.Io.SetRead(Io.RChar, Io.SysCr);
	m_Stats.Io.SetWrite(Io.WChar, Io.SysCw);
}

QMap<QString, CProcessInfo::SEnvVar> CLinuxProcess::GetEnvVariables() const
{
	QMap<QString, SEnvVar> Variables;

	//
	// Readable only for our own processes unless privileged, so an empty result
	// is asked of TaskHelper instead of being reported as "no environment".
	//
	const quint64 Pid = GetProcessId();
	QStringList Entries = ProcFs::ReadNulList(ProcFs::ProcPath(Pid, "environ"));
	if (Entries.isEmpty() && LinuxHelperNeeded())
	{
		QByteArray Data = LinuxHelperReadProcFile(Pid, "environ");
		while (Data.endsWith('\0'))
			Data.chop(1);
		if (!Data.isEmpty())
		{
			Entries.clear();
			for (const QByteArray& Part : Data.split('\0'))
				Entries.append(QString::fromUtf8(Part));
		}
	}

	for (const QString& Entry : Entries)
	{
		const int Sep = Entry.indexOf('=');
		if (Sep <= 0)
			continue;

		SEnvVar Var;
		Var.Name = Entry.left(Sep);
		Var.Value = Entry.mid(Sep + 1);
		Var.Type = SEnvVar::eProcess;
		Variables.insert(Var.Name, Var);
	}

	return Variables;
}

STATUS CLinuxProcess::DeleteEnvVariable(const QString& Name)
{
	// The environment of a running process cannot be edited from outside on
	// Linux without ptrace-injecting code; this is likely to stay unsupported.
	return ERR(tr("Editing the environment of a running process is not supported on Linux."));
}

QMap<quint64, CMemoryPtr> CLinuxProcess::GetMemoryMap() const
{
	QMap<quint64, CMemoryPtr> MemoryMap;

	const quint64 Pid = GetProcessId();

	//
	// smaps is expensive - the kernel walks the page tables of every region to
	// produce it - but this is only called when the memory view is populated,
	// not on the refresh path, so paying for the residency detail here is
	// worthwhile. An empty result (older kernel, or no permission) just leaves
	// the working set columns at zero.
	//
	const QMap<quint64, ProcFs::SMapDetail> Details = ProcFs::ReadMapDetails(Pid);

	for (const ProcFs::SMapEntry& Entry : ProcFs::ReadMaps(Pid))
	{
		QSharedPointer<CLinuxMemory> pMemory = QSharedPointer<CLinuxMemory>(new CLinuxMemory());
		pMemory->InitStaticData(Pid, Entry);

		auto Detail = Details.constFind(Entry.Start);
		if (Detail != Details.constEnd())
			pMemory->SetDetail(*Detail);

		MemoryMap.insert(Entry.Start, pMemory);
	}

	return MemoryMap;
}

QMap<quint64, CHeapPtr> CLinuxProcess::GetHeapList() const
{
	// glibc does not publish heap arenas the way the Windows heap manager does;
	// this may end up permanently empty.
	return QMap<quint64, CHeapPtr>();
}

QList<CWndPtr> CLinuxProcess::GetWindows() const
{
	QReadLocker Locker(&m_WindowMutex);
	return m_WindowList.values();
}

CWndPtr CLinuxProcess::GetMainWindow() const
{
	QReadLocker Locker(&m_WindowMutex);

	//
	// There is no "main window" concept in X11. The first visible top-level
	// window is the closest useful approximation, falling back to any window at
	// all so that a fully minimized application still resolves to something.
	//
	for (const CWndPtr& pWnd : m_WindowList)
	{
		if (pWnd->IsVisible())
			return pWnd;
	}
	return m_WindowList.isEmpty() ? CWndPtr() : m_WindowList.first();
}

STATUS CLinuxProcess::LoadModule(const QString& Path)
{
	// linux-todo: inject via ptrace + dlopen, mirroring the Windows InjectDll.
	return ERR(tr("Loading a module into a running process is not yet implemented on Linux."));
}

bool CLinuxProcess::UpdateThreads()
{
	const quint64 Pid = GetProcessId();

	const QList<quint64> Tids = ProcFs::EnumThreads(Pid);
	if (Tids.isEmpty())
		return false; // process is gone

	// Always the single-cpu total; see the note on UpdateDynamicData().
	const quint64 SysTime = m_LastSysTimePerCpu;

	QSet<quint64> Added;
	QSet<quint64> Changed;
	QSet<quint64> Removed;

	QMap<quint64, CThreadPtr> OldThreads = GetThreadList();

	for (quint64 Tid : Tids)
	{
		QSharedPointer<CLinuxThread> pThread = OldThreads.take(Tid).staticCast<CLinuxThread>();
		bool bAdd = false;
		if (pThread.isNull())
		{
			pThread = QSharedPointer<CLinuxThread>(new CLinuxThread());
			if (!pThread->InitStaticData(Pid, Tid))
				continue; // exited between the readdir and the stat read

			theAPI->AddThread(pThread);

			QWriteLocker Locker(&m_ThreadMutex);
			m_ThreadList.insert(Tid, pThread);
			Locker.unlock();

			bAdd = true;
		}

		const bool bChanged = pThread->UpdateDynamicData(SysTime);

		if (bAdd)
			Added.insert(Tid);
		else if (bChanged)
			Changed.insert(Tid);
	}

	QWriteLocker Locker(&m_ThreadMutex);
	foreach(quint64 Tid, OldThreads.keys())
	{
		CThreadPtr pThread = m_ThreadList.value(Tid);
		if (pThread.isNull())
			continue;

		if (pThread->CanBeRemoved())
		{
			m_ThreadList.remove(Tid);
			theAPI->ClearThread(Tid);
			Removed.insert(Tid);
		}
		else if (!pThread->IsMarkedForRemoval())
		{
			pThread->MarkForRemoval();
			Changed.insert(Tid);
		}
	}
	Locker.unlock();

	emit ThreadsUpdated(Added, Changed, Removed);

	return true;
}

foreach(quint64 Tid, OldThreads.keys())
	{
		CThreadPtr pThread = m_ThreadList.value(Tid);
		if (pThread.isNull())
			continue;

		if (pThread->CanBeRemoved())
		{
			m_ThreadList.remove(Tid);
			theAPI->ClearThread(Tid);
			Removed.insert(Tid);
		}
		else if (!pThread->IsMarkedForRemoval())
		{
			pThread->MarkForRemoval();
			Changed.insert(Tid);
		}
	}

bool CLinuxProcess::UpdateHandles()
{
	const quint64 Pid = GetProcessId();

	QSet<quint64> Added;
	QSet<quint64> Changed;
	QSet<quint64> Removed;

	QMap<quint64, CHandlePtr> OldHandles = GetHandleList();

	//
	// /proc/<pid>/fd is mode 500 and owned by the process's user, so for anything
	// belonging to someone else the directory cannot even be listed. When that
	// happens an elevated helper is asked for the whole set at once - the symlink
	// targets and the fdinfo text for every descriptor in one reply, rather than
	// the two round trips per descriptor a direct read would need.
	//
	QList<QMap<QString, QVariant>> HelperFds;
	QList<quint64> Fds;

	if (::access(ProcFs::ProcPath(Pid, "fd").toLocal8Bit().constData(), R_OK) == 0)
		Fds = ProcFs::EnumFds(Pid);
	else if (LinuxHelperNeeded() && theConf->GetBool("Options/UseTaskHelper", false))
		HelperFds = LinuxHelperListFds(Pid);

	if (!HelperFds.isEmpty())
	{
		for (const QMap<QString, QVariant>& Entry : HelperFds)
		{
			const quint64 Fd = Entry.value("Fd").toULongLong();
			const QString Target = Entry.value("Target").toString();
			const QByteArray FdInfo = Entry.value("Info").toByteArray();

			QSharedPointer<CLinuxHandle> pHandle = OldHandles.take(Fd).staticCast<CLinuxHandle>();
			bool bAdd = false;
			if (pHandle.isNull())
			{
				pHandle = QSharedPointer<CLinuxHandle>(new CLinuxHandle());
				if (!pHandle->InitStaticData(Pid, Fd, Target, FdInfo))
					continue;

				QWriteLocker Locker(&m_HandleMutex);
				m_HandleList.insert(Fd, pHandle);
				Locker.unlock();

				bAdd = true;
			}

			const bool bChanged = pHandle->UpdateDynamicData(FdInfo);

			if (bAdd)
				Added.insert(Fd);
			else if (bChanged)
				Changed.insert(Fd);
		}
	}

	for (quint64 Fd : Fds)
	{
		QSharedPointer<CLinuxHandle> pHandle = OldHandles.take(Fd).staticCast<CLinuxHandle>();
		bool bAdd = false;
		if (pHandle.isNull())
		{
			pHandle = QSharedPointer<CLinuxHandle>(new CLinuxHandle());
			if (!pHandle->InitStaticData(Pid, Fd))
				continue; // closed between the readdir and the readlink

			QWriteLocker Locker(&m_HandleMutex);
			m_HandleList.insert(Fd, pHandle);
			Locker.unlock();

			bAdd = true;
		}

		const bool bChanged = pHandle->UpdateDynamicData();

		if (bAdd)
			Added.insert(Fd);
		else if (bChanged)
			Changed.insert(Fd);
	}

	QWriteLocker Locker(&m_HandleMutex);
	foreach(quint64 Fd, OldHandles.keys())
	{
		CHandlePtr pHandle = m_HandleList.value(Fd);
		if (pHandle.isNull())
			continue;

		if (pHandle->CanBeRemoved())
		{
			m_HandleList.remove(Fd);
			Removed.insert(Fd);
		}
		else if (!pHandle->IsMarkedForRemoval())
		{
			pHandle->MarkForRemoval();
			Changed.insert(Fd);
		}
	}
	Locker.unlock();

	emit HandlesUpdated(Added, Changed, Removed);

	return true;
}

foreach(quint64 Fd, OldHandles.keys())
	{
		CHandlePtr pHandle = m_HandleList.value(Fd);
		if (pHandle.isNull())
			continue;

		if (pHandle->CanBeRemoved())
		{
			m_HandleList.remove(Fd);
			Removed.insert(Fd);
		}
		else if (!pHandle->IsMarkedForRemoval())
		{
			pHandle->MarkForRemoval();
			Changed.insert(Fd);
		}
	}

bool CLinuxProcess::UpdateModules()
{
	const quint64 Pid = GetProcessId();

	const QList<ProcFs::SMapEntry> Maps = ProcFs::ReadMaps(Pid);
	if (Maps.isEmpty())
		return false; // gone, or /proc/<pid>/maps not readable for us

	//
	// A single shared object contributes several consecutive mappings (text,
	// rodata, data, bss) with different protections, which have to be collapsed
	// into one module.
	//
	// Grouping purely by path is wrong: several unrelated mappings can share a
	// name - most visibly SysV shared memory, where every segment appears as
	// "/SYSVxxxxxxxx (deleted)" - and merging those produces one bogus module
	// spanning every address between them.
	//
	// /proc/<pid>/maps is ordered by address, so instead a run is only extended
	// while the path keeps matching. A different file-backed path closes the
	// current run; anonymous mappings in between (guard pages, bss) do not,
	// since those belong to the same load segment reservation.
	//
	struct SModuleRange
	{
		QString	Path;
		quint64	Start = 0;
		quint64	End = 0;
		bool	Executable = false;
	};
	QList<SModuleRange> Ranges;

	for (const ProcFs::SMapEntry& Entry : Maps)
	{
		// Pseudo-regions ([heap], [stack], [vdso]) are memory, not modules;
		// they show up in the memory view instead.
		const bool bFileBacked = (Entry.Inode != 0) && !Entry.Path.isEmpty() && !Entry.Path.startsWith('[');

		if (!bFileBacked)
			continue;

		if (!Ranges.isEmpty() && Ranges.last().Path == Entry.Path)
		{
			SModuleRange& Range = Ranges.last();
			if (Entry.End > Range.End)
				Range.End = Entry.End;
			Range.Executable |= Entry.Exec;
			continue;
		}

		SModuleRange Range;
		Range.Path = Entry.Path;
		Range.Start = Entry.Start;
		Range.End = Entry.End;
		Range.Executable = Entry.Exec;
		Ranges.append(Range);
	}

	QSet<quint64> Added;
	QSet<quint64> Changed;
	QSet<quint64> Removed;

	QMap<quint64, CModulePtr> OldModules = GetModuleList();

	// Keyed by base address, matching how the Windows backend keys modules.
	for (const SModuleRange& Range : Ranges)
	{
		const QString& Path = Range.Path;

		QSharedPointer<CLinuxModule> pModule = OldModules.take(Range.Start).staticCast<CLinuxModule>();
		if (!pModule.isNull() && pModule->GetFileName() != Path)
		{
			// Same base address, different file: the old one was unmapped and
			// something else took its place.
			pModule.clear();
		}

		if (pModule.isNull())
		{
			pModule = QSharedPointer<CLinuxModule>(new CLinuxModule());
			pModule->InitStaticData(Path, Range.Start, Range.End - Range.Start);
			pModule->SetLoaded(true);

			QWriteLocker Locker(&m_ModuleMutex);
			m_ModuleList.insert(Range.Start, pModule);
			Locker.unlock();

			Added.insert(Range.Start);
		}
	}

	//
	// The main executable is the module whose path matches the exe link; the
	// modules view uses it for the process's own file details.
	//
	const QString ExePath = GetFileName();
	if (!ExePath.isEmpty())
	{
		QReadLocker Locker(&m_ModuleMutex);
		for (const CModulePtr& pModule : m_ModuleList)
		{
			if (pModule->GetFileName() == ExePath)
			{
				pModule->SetFirst(true);
				Locker.unlock();
				QWriteLocker WriteLocker(&m_Mutex);
				m_pModuleInfo = pModule;
				break;
			}
		}
	}

	QWriteLocker Locker(&m_ModuleMutex);
	foreach(quint64 BaseAddress, OldModules.keys())
	{
		CModulePtr pModule = m_ModuleList.value(BaseAddress);
		if (pModule.isNull())
			continue;

		// CModuleInfo derives from CAbstractInfo rather than CAbstractInfoEx,
		// so it has no removal-persistence machinery - unmapped modules are
		// dropped immediately.
		m_ModuleList.remove(BaseAddress);
		Removed.insert(BaseAddress);
	}
	Locker.unlock();

	emit ModulesUpdated(Added, Changed, Removed);

	return true;
}

foreach(quint64 BaseAddress, OldModules.keys())
	{
		CModulePtr pModule = m_ModuleList.value(BaseAddress);
		if (pModule.isNull())
			continue;

		// CModuleInfo derives from CAbstractInfo rather than CAbstractInfoEx,
		// so it has no removal-persistence machinery - unmapped modules are
		// dropped immediately.
		m_ModuleList.remove(BaseAddress);
		Removed.insert(BaseAddress);
	}

bool CLinuxProcess::UpdateWindows()
{
	if (!X11Helper::IsAvailable())
		return false; // built without X11, or a Wayland session with no XWayland

	//
	// The list is refreshed for every process by CLinuxAPI::UpdateProcessList
	// via SetWindows(), so an explicit refresh only has to re-read the ones we
	// already know about. Enumerating the whole display again here would repeat
	// work that was just done.
	//
	QSet<quint64> Changed;

	QReadLocker ReadLocker(&m_WindowMutex);
	const QList<CWndPtr> Windows = m_WindowList.values();
	ReadLocker.unlock();

	for (const CWndPtr& pWnd : Windows)
	{
		if (pWnd.staticCast<CLinuxWnd>()->UpdateDynamicData())
			Changed.insert(pWnd->GetHWnd());
	}

	//
	// Emitted unconditionally, even when nothing changed.
	//
	// CWindowsView calls this as a "send me the current state" request and only
	// populates itself from the resulting signal - so staying silent because
	// there was no change leaves the view permanently empty, since the window
	// list was already filled in by SetWindows() before the view ever asked.
	//
	emit WindowsUpdated(QSet<quint64>(), Changed, QSet<quint64>());

	return true;
}

bool CLinuxProcess::SetWindows(const QList<X11Helper::SWindow>& Windows)
{
	QSet<quint64> Added;
	QSet<quint64> Changed;
	QSet<quint64> Removed;

	QMap<quint64, CWndPtr> OldWindows = GetWindowList();

	//
	// _NET_WM_PID is a hint the client sets voluntarily, so a window whose
	// application never set it has a pid of 0 and cannot be attributed to any
	// process. That is a protocol limitation, not a bug; such windows simply do
	// not appear under any process.
	//
	for (const X11Helper::SWindow& Info : Windows)
	{
		QSharedPointer<CLinuxWnd> pWnd = OldWindows.take(Info.Window).staticCast<CLinuxWnd>();
		bool bAdd = false;
		if (pWnd.isNull())
		{
			pWnd = QSharedPointer<CLinuxWnd>(new CLinuxWnd());
			if (!pWnd->InitStaticData(Info.Window))
				continue; // unmapped between the enumeration and the query

			QWriteLocker Locker(&m_WindowMutex);
			m_WindowList.insert(Info.Window, pWnd);
			Locker.unlock();

			bAdd = true;
		}

		const bool bChanged = pWnd->UpdateDynamicData();

		if (bAdd)
			Added.insert(Info.Window);
		else if (bChanged)
			Changed.insert(Info.Window);
	}

	QWriteLocker Locker(&m_WindowMutex);
	foreach(quint64 Window, OldWindows.keys())
	{
		// CWndInfo derives from CAbstractInfo, which has no removal-persistence
		// machinery, so closed windows are dropped immediately.
		m_WindowList.remove(Window);
		Removed.insert(Window);
	}
	Locker.unlock();

	emit WindowsUpdated(Added, Changed, Removed);

	return true;
}

foreach(quint64 Window, OldWindows.keys())
	{
		// CWndInfo derives from CAbstractInfo, which has no removal-persistence
		// machinery, so closed windows are dropped immediately.
		m_WindowList.remove(Window);
		Removed.insert(Window);
	}

CLinuxService::CLinuxService(QObject *parent)
	: CServiceInfo(parent)
{
	m_ProcessId = 0;
}

bool CLinuxService::InitStaticData(const QString& UnitName)
{
	QWriteLocker Locker(&m_Mutex);
	m_SvcName = UnitName;
	//
	// Only the name is set here. The unit properties (FragmentPath, ExecStart,
	// MainPID, ...) come from FetchProperties, which the API layer calls when
	// the service is actually displayed - fetching them for every unit on every
	// refresh would mean a D-Bus round trip per unit.
	//
	return true;
}

bool CLinuxService::FetchProperties(bool bFragmentPathOnly)
{
	const QString Path = GetObjectPath();
	if (Path.isEmpty())
		return false;

	QDBusConnection Bus = QDBusConnection::systemBus();
	if (!Bus.isConnected())
		return false;

	QDBusInterface Props("org.freedesktop.systemd1", Path, "org.freedesktop.DBus.Properties", Bus);
	if (!Props.isValid())
		return false;

	bool bChanged = false;

	//
	// FragmentPath is the unit file backing this service. It never changes for
	// the life of the unit, so it is read once and then left alone.
	//
	if (!m_bHaveFragmentPath)
	{
		QDBusReply<QVariant> Reply = Props.call("Get", "org.freedesktop.systemd1.Unit", "FragmentPath");
		if (Reply.isValid())
		{
			const QString FragmentPath = Reply.value().toString();
			QWriteLocker Locker(&m_Mutex);
			m_BinaryPath = FragmentPath;
			m_FileName = FragmentPath;
			m_bHaveFragmentPath = true;
			bChanged = true;
		}
	}

	if (bFragmentPathOnly)
		return bChanged;

	//
	// MainPID is 0 for anything not currently running, including oneshot units
	// that have already exited.
	//
	QDBusReply<QVariant> Reply = Props.call("Get", "org.freedesktop.systemd1.Service", "MainPID");
	if (Reply.isValid())
	{
		const quint64 MainPID = Reply.value().toUInt();
		QWriteLocker Locker(&m_Mutex);
		if (m_ProcessId != MainPID)
		{
			m_ProcessId = MainPID;
			bChanged = true;
		}
	}

	//
	// Whether the unit's cgroup is frozen, which is what IsPaused() reports.
	// Absent on systemd older than 246, in which case the unit is simply never
	// considered paused.
	//
	QDBusReply<QVariant> FreezerReply = Props.call("Get", "org.freedesktop.systemd1.Unit", "FreezerState");
	if (FreezerReply.isValid())
	{
		const QString FreezerState = FreezerReply.value().toString();
		QWriteLocker Locker(&m_Mutex);
		if (m_FreezerState != FreezerState)
		{
			m_FreezerState = FreezerState;
			bChanged = true;
		}
	}

	return bChanged;
}

bool CLinuxService::UpdateDynamicData(const QString& LoadState, const QString& ActiveState,
                                      const QString& SubState, const QString& Description)
{
	QWriteLocker Locker(&m_Mutex);

	bool bChanged = (m_LoadState != LoadState) || (m_ActiveState != ActiveState) || (m_SubState != SubState);

	m_LoadState = LoadState;
	m_ActiveState = ActiveState;
	m_SubState = SubState;
	m_DisplayName = Description;

	return bChanged;
}

bool CLinuxService::IsStopped() const
{
	QReadLocker Locker(&m_Mutex);
	return m_ActiveState == "inactive" || m_ActiveState == "failed";
}

bool CLinuxService::IsRunning(bool bStrict) const
{
	QReadLocker Locker(&m_Mutex);
	if (bStrict)
		return m_ActiveState == "active" && m_SubState == "running";
	return m_ActiveState == "active" || m_ActiveState == "activating";
}

bool CLinuxService::IsPaused() const
{
	//
	// systemd has no "paused" state as such; a unit frozen through the cgroup
	// freezer is the equivalent, and it reports that as FreezerState.
	//
	// Values are running / freezing / frozen / thawing.
	//
	QReadLocker Locker(&m_Mutex);
	return m_FreezerState == "frozen" || m_FreezerState == "freezing";
}

QString CLinuxService::GetStateString() const
{
	QReadLocker Locker(&m_Mutex);
	if (m_SubState.isEmpty())
		return m_ActiveState;
	return QString("%1 (%2)").arg(m_ActiveState).arg(m_SubState);
}

static STATUS DBusErrorToStatus(const QString& Unit, const QString& Action, const QDBusError& Error)
{
	const QString Name = Error.name();

	if (Name == "org.freedesktop.DBus.Error.InteractiveAuthorizationRequired")
	{
		return ERR(QObject::tr("Not authorised to %1 %2, and no interactive authentication agent is available. "
		                       "Run TaskExplorer from a desktop session with a polkit agent, or as root.")
		           .arg(Action).arg(Unit));
	}

	if (Name == "org.freedesktop.DBus.Error.AccessDenied")
		return ERR(QObject::tr("Not authorised to %1 %2.").arg(Action).arg(Unit));

	if (Name == "org.freedesktop.systemd1.NoSuchUnit")
		return ERR(QObject::tr("The unit %1 no longer exists.").arg(Unit));

	if (Name == "org.freedesktop.systemd1.UnitMasked")
		return ERR(QObject::tr("The unit %1 is masked and cannot be started.").arg(Unit));

	if (Name == "org.freedesktop.DBus.Error.UnknownMethod")
	{
		return ERR(QObject::tr("This operation is not supported by the running version of systemd."));
	}

	if (Name == "org.freedesktop.DBus.Error.NoReply" || Name == "org.freedesktop.DBus.Error.Timeout")
		return ERR(QObject::tr("Timed out waiting for systemd to %1 %2.").arg(Action).arg(Unit));

	// Anything else: systemd's own message is usually descriptive.
	const QString Message = Error.message();
	if (!Message.isEmpty())
		return ERR(QObject::tr("Failed to %1 %2: %3").arg(Action).arg(Unit).arg(Message));

	return ERR(QObject::tr("Failed to %1 %2: %3").arg(Action).arg(Unit).arg(Name));
}

STATUS CLinuxService::CallManager(const QString& Method, const QVariantList& Arguments)
{
	QDBusConnection Bus = QDBusConnection::systemBus();
	if (!Bus.isConnected())
		return ERR(tr("Cannot connect to the system bus."));

	QDBusMessage Call = QDBusMessage::createMethodCall("org.freedesktop.systemd1",
	                                                   "/org/freedesktop/systemd1",
	                                                   "org.freedesktop.systemd1.Manager",
	                                                   Method);
	Call.setArguments(Arguments);

	//
	// Without this flag polkit fails the call with
	// InteractiveAuthorizationRequired rather than asking the user to
	// authenticate, so an unprivileged user could never start or stop anything.
	//
	Call.setInteractiveAuthorizationAllowed(true);

	//
	// The reply arrives as soon as systemd has enqueued the job, not when the
	// job completes - so this is normally fast. The long timeout is for the
	// polkit prompt, which blocks until the user answers it.
	//
	const QDBusMessage Reply = Bus.call(Call, QDBus::Block, 120 * 1000);

	if (Reply.type() == QDBusMessage::ErrorMessage)
	{
		// Derive a readable verb from the method name for the error text.
		QString Action = Method;
		Action.remove("Unit");
		return DBusErrorToStatus(GetUnitName(), Action.toLower(), QDBusError(Reply));
	}

	return OK;
}

STATUS CLinuxService::Start()
{
	//
	// "replace" is the standard job mode: it displaces any conflicting queued
	// job rather than failing, which is what systemctl start does.
	//
	return CallManager("StartUnit", QVariantList() << GetUnitName() << "replace");
}

STATUS CLinuxService::Pause()
{
	//
	// Freezing suspends every process in the unit's cgroup, which is the
	// closest equivalent to pausing a Windows service. It needs systemd 246 or
	// newer and only applies to a unit that is actually running - both cases
	// surface as a D-Bus error.
	//
	return CallManager("FreezeUnit", QVariantList() << GetUnitName());
}

STATUS CLinuxService::Delete(bool bForce)
{
	//
	// Deliberately not implemented.
	//
	// On Windows deleting a service removes a registry registration this
	// application created a view of. A systemd unit is a file on disk that
	// almost always belongs to a distribution package, so "delete" would mean
	// removing a packaged file - destructive, not reversible from here, and
	// liable to be silently restored by the next package update.
	//
	// The two operations a user actually wants are offered by systemctl and
	// are named here rather than guessed at.
	//
	return ERR(tr("Deleting a systemd unit is not supported: the unit file usually belongs to a distribution package. "
	              "Use 'systemctl disable %1' to stop it starting at boot, or 'systemctl mask %1' to prevent it "
	              "from being started at all.").arg(GetUnitName()));
}

CLinuxSocket::CLinuxSocket(QObject *parent)
	: CSocketInfo(parent)
{
	m_Inode = 0;
	m_Uid = 0;
}

bool CLinuxSocket::InitStaticData(quint64 ProcessId, const ProcFs::SNetConnection& Conn)
{
	QWriteLocker Locker(&m_Mutex);

	m_ProcessId = ProcessId;
	m_ProtocolType = Conn.ProtocolType;
	m_LocalAddress = Conn.LocalAddress;
	m_LocalPort = Conn.LocalPort;
	m_RemoteAddress = Conn.RemoteAddress;
	m_RemotePort = Conn.RemotePort;

	m_Inode = Conn.Inode;
	m_Uid = Conn.Uid;

	// The hash keys the socket list; it must be derived from exactly the same
	// tuple that FindSocketEntry() looks the socket up by.
	m_HashID = MkHash(ProcessId, Conn.ProtocolType, Conn.LocalAddress, Conn.LocalPort,
	                  Conn.RemoteAddress, Conn.RemotePort);

	return true;
}

void CLinuxSocket::LinkProcess(const QSharedPointer<QObject>& pProcess)
{
	QWriteLocker Locker(&m_Mutex);
	m_pProcess = pProcess.toWeakRef();
	if (CProcessInfo* pInfo = qobject_cast<CProcessInfo*>(pProcess.data()))
		m_ProcessName = pInfo->GetName();
}

bool CLinuxSocket::UpdateDynamicData(const ProcFs::SNetConnection& Conn)
{
	QWriteLocker Locker(&m_Mutex);

	const bool bChanged = (m_State != Conn.State);
	m_State = Conn.State;

	Locker.unlock();

	//
	// Cumulative counters from sock_diag's tcp_info. SNetStats turns them into
	// deltas and rates, so they must be set before UpdateStats().
	//
	// Only TCP sockets carry a tcp_info, and the /proc/net fallback carries no
	// counters at all - in either case bHaveCounters is false and the totals
	// are left alone, so the rates stay at zero rather than being computed from
	// a bogus baseline.
	//
	if (Conn.bHaveCounters)
	{
		QWriteLocker StatsLocker(&m_StatsMutex);
		m_Stats.Net.SetReceive(Conn.BytesReceived, Conn.SegmentsReceived);
		m_Stats.Net.SetSend(Conn.BytesSent, Conn.SegmentsSent);
	}

	UpdateStats();

	return bChanged;
}

STATUS CLinuxSocket::Close()
{
	// linux-todo: SOCK_DESTROY via netlink closes a TCP socket, but only for
	// root and only for TCP.
	return ERR(tr("Closing a socket is not yet implemented on Linux."));
}

CLinuxThread::CLinuxThread(QObject *parent)
	: CThreadInfo(parent)
{
	m_State = '\0';
	m_Nice = 0;
	m_SchedPolicy = 0;
	m_IoPrio = -1;
	m_StartAddress = 0;
	m_StackTraceJob = 0;
}

bool CLinuxThread::InitStaticData(quint64 Pid, quint64 Tid)
{
	const ProcFs::SStat Stat = ProcFs::ReadThreadStat(Pid, Tid);
	if (!Stat.Valid)
		return false;

	// comm is per thread on Linux and is what pthread_setname_np() sets, so it
	// is usually more informative than the process name.
	const QString Name = ProcFs::ReadFileStr(ProcFs::TaskPath(Pid, Tid, "comm")).trimmed();

	QWriteLocker Locker(&m_Mutex);

	m_ProcessId = Pid;
	m_ThreadId = Tid;

	// The thread whose tid equals the pid is the one that ran main().
	m_IsMainThread = (Pid == Tid);

	m_ThreadName = Name.isEmpty() ? Stat.Comm : Name;
	m_CreateTimeStamp = ProcFs::StartTimeToEpochMs(Stat.StartTime);

	//
	// Note this is 0 on any current kernel, for everyone including root:
	// /proc/<pid>/stat's kstkeip and kstkesp fields were hardcoded to zero to
	// stop kernel addresses leaking, rather than merely gated on ptrace access.
	// Verified here - even reading our own stat gives 0. The same applies to
	// m_StackUsage below, which is derived from startstack and kstkesp.
	//
	// The code is kept because the field is still specified, costs nothing, and
	// will populate again on a kernel that provides it; GetStartAddressString()
	// renders 0 as blank so the column is simply empty meanwhile.
	//
	// Note what this actually is: the thread's *current* instruction pointer,
	// sampled the first time TaskExplorer saw the thread. Linux does not record
	// the function a thread was created to run - that argument to
	// pthread_create is never handed to the kernel - so there is no true
	// equivalent of the Windows start address. Sampling once at first sight is
	// the closest honest approximation, and for a thread caught early it is
	// usually still inside its entry function.
	//
	// It is deliberately resolved here, once, rather than on every refresh:
	// the value would otherwise chase the running thread around and the column
	// would never hold still long enough to read.
	//
	m_StartAddress = Stat.KstkEip;
	m_StartAddressString = m_StartAddress ? LinuxResolveAddress(Pid, m_StartAddress) : QString();

	return true;
}

bool CLinuxThread::UpdateDynamicData(quint64 SysTime)
{
	const quint64 Pid = GetProcessId();
	const quint64 Tid = GetThreadId();

	const ProcFs::SStat Stat = ProcFs::ReadThreadStat(Pid, Tid);
	if (!Stat.Valid)
		return false;

	bool bChanged = false;

	QWriteLocker Locker(&m_Mutex);

	bChanged |= (m_State != Stat.State);
	m_State = Stat.State;
	m_Nice = (qint32)Stat.Nice;
	m_SchedPolicy = (qint32)Stat.Policy;

	m_KernelTime = Stat.STime;
	m_UserTime = Stat.UTime;

	m_Priority = Stat.Nice;
	m_BasePriority = Stat.Priority;

	m_IoPrio = LinuxGetIoPrio(Tid);
	m_IOPriority = m_IoPrio;

	m_AffinityMask = LinuxGetAffinity(Tid);

	//
	// startstack is the base of the thread's user stack and kstkesp its current
	// stack pointer, so the difference is how much of the stack is in use. Both
	// are zeroed for processes we cannot ptrace, in which case this stays 0.
	//
	if (Stat.StartStack && Stat.KstkEsp && Stat.StartStack > Stat.KstkEsp)
		m_StackUsage = Stat.StartStack - Stat.KstkEsp;

	Locker.unlock();

	QWriteLocker StatsLocker(&m_StatsMutex);

	m_CpuStats.CpuKernelDelta.Update(Stat.STime);
	m_CpuStats.CpuUserDelta.Update(Stat.UTime);
	m_CpuStats.UpdateStats(SysTime);

	return bChanged;
}

QString CLinuxThread::GetName() const
{
	QReadLocker Locker(&m_Mutex);
	return m_ThreadName;
}

QString CLinuxThread::GetStartAddressString() const
{
	QReadLocker Locker(&m_Mutex);
	return m_StartAddressString;
}

QString CLinuxThread::GetStateString() const
{
	QReadLocker Locker(&m_Mutex);
	return LinuxStateToString(m_State);
}

QString CLinuxThread::GetPriorityString() const
{
	QReadLocker Locker(&m_Mutex);
	return LinuxNiceToPriorityString(m_Nice);
}

STATUS CLinuxThread::SetPriority(qint32 Value)
{
	//
	// Despite the PRIO_PROCESS name, the "who" argument of setpriority is a
	// tid on Linux, so this really does adjust one thread rather than the whole
	// thread group.
	//
	errno = 0;
	if (setpriority(PRIO_PROCESS, (id_t)GetThreadId(), Value) != 0 && errno != 0)
		return ErrnoToStatus(tr("Failed to set thread priority"));

	QWriteLocker Locker(&m_Mutex);
	m_Nice = Value;
	m_Priority = Value;
	return OK;
}

QString CLinuxThread::GetBasePriorityString() const
{
	QReadLocker Locker(&m_Mutex);
	return LinuxSchedPolicyToString(m_SchedPolicy);
}

STATUS CLinuxThread::SetBasePriority(qint32 Value)
{
	// See CLinuxProcess::SetBasePriority - the shared GUI never calls this.
	return ERR(tr("Setting the scheduling policy is not supported; use chrt(1)."));
}

QString CLinuxThread::GetIOPriorityString() const
{
	// Sampled in UpdateDynamicData so that repainting the thread list does not
	// issue a syscall per visible row.
	QReadLocker Locker(&m_Mutex);
	return LinuxIoPrioToString(m_IoPrio);
}

STATUS CLinuxThread::SetIOPriority(qint32 Value)
{
	//
	// IOPRIO_WHO_PROCESS is a misnomer: like setpriority, the "who" argument is
	// really a tid, so this sets one thread's I/O priority rather than the whole
	// thread group's.
	//
	if (LinuxSetIoPrio(GetThreadId(), Value) != 0)
		return ErrnoToStatus(tr("Failed to set the I/O priority"));

	QWriteLocker Locker(&m_Mutex);
	m_IoPrio = Value;
	m_IOPriority = Value;
	return OK;
}

STATUS CLinuxThread::SetAffinityMask(quint64 Value)
{
	if (Value == 0)
		return ERR(tr("The affinity mask must select at least one CPU."));

	// sched_setaffinity is per thread; passing a tid is the documented way to
	// pin one thread without touching its siblings.
	if (!LinuxSetAffinity(GetThreadId(), Value))
		return ErrnoToStatus(tr("Failed to set the affinity mask"));

	QWriteLocker Locker(&m_Mutex);
	m_AffinityMask = Value;
	return OK;
}

STATUS CLinuxThread::Terminate(bool bForce)
{
	// Linux offers no safe way to kill a single thread of another process;
	// tgkill with SIGKILL takes the whole thread group down.
	return ERR(tr("Terminating an individual thread is not supported on Linux."));
}

bool CLinuxThread::IsSuspended() const
{
	QReadLocker Locker(&m_Mutex);
	return m_State == 'T';
}

static CStackTracePtr MakeMessageTrace(quint64 Pid, quint64 Tid, const QString& Message)
{
	CStackTracePtr Trace(new CStackTrace(Pid, Tid));
	quint64 Params[4] = { 0, 0, 0, 0 };
	Trace->AddFrame(Message, 0, 0, 0, 0, 0, Params, 0);
	return Trace;
}

quint64 CLinuxThread::TraceStack()
{
	// One trace in flight at a time; the view will not ask again until this one
	// reports back anyway.
	if (m_StackTraceJob)
		return m_StackTraceJob;

	static quint64 NextJob = 0;
	m_StackTraceJob = ++NextJob;

	//
	// The unwinding is done by TaskHelper, which links libdwfl directly. The
	// previous implementation shelled out to eu-stack and then eu-addr2line and
	// parsed their output; see TaskHelper/LinuxMain.cpp for why that moved.
	//
	// TraceStack() is called from the GUI thread, but this object lives on the
	// API worker thread, and the request to the helper is synchronous. So the
	// work is bounced onto this object's own thread: blocking a refresh cycle for
	// a few tens of milliseconds is acceptable, blocking the window is not.
	//
	// A queued invocation is also the lifetime guarantee - if the thread object
	// is destroyed first, Qt drops the pending call rather than running it
	// against freed memory.
	//
	QMetaObject::invokeMethod(this, "RequestStackTrace", Qt::QueuedConnection);

	return m_StackTraceJob;
}

void CLinuxThread::RequestStackTrace()
{
	const quint64 Pid = GetProcessId();
	const quint64 Tid = GetThreadId();

	//
	// Unprivileged deliberately. Under the default Yama policy this can only
	// unwind descendants, which is exactly what the old eu-stack path could do -
	// and asking for elevation here would put a password prompt in the way of
	// merely selecting a thread. Running TaskExplorer elevated gives the helper
	// root by inheritance, with no prompt.
	//
	const QString Socket = CTaskService::RunWorker(false);
	if (Socket.isEmpty())
	{
		m_StackTraceJob = 0;
		emit StackTraced(MakeMessageTrace(Pid, Tid,
			tr("The TaskHelper process could not be started, so stacks cannot be unwound.")));
		return;
	}

	QVariantMap Parameters;
	Parameters["ProcessId"] = Pid;
	Parameters["ThreadId"] = Tid;
	Parameters["MaxFrames"] = (quint32)64;

	QVariantMap Command;
	Command["Command"] = "TraceStack";
	Command["Parameters"] = Parameters;

	const QVariantMap Reply = CTaskService::SendCommand(Socket, Command, 15000).toMap();

	m_StackTraceJob = 0;

	if (Reply.isEmpty())
	{
		emit StackTraced(MakeMessageTrace(Pid, Tid,
			tr("The TaskHelper process did not answer.")));
		return;
	}

	const QVariantList Frames = Reply["Frames"].toList();
	if (Frames.isEmpty())
	{
		//
		// The usual cause is ptrace being refused: Yama's ptrace_scope=1 (the
		// default on Ubuntu) only permits tracing descendants. The helper reports
		// that as a code so the wording can be decided here, where it is known
		// whether we are elevated.
		//
		const QString Error = Reply["Error"].toString();
		QString Message;
		if (Error == "ptrace" || Error.contains("not permitted", Qt::CaseInsensitive))
		{
			Message = tr("Cannot read this thread's stack: ptrace access was denied. "
			             "Restart TaskExplorer elevated, or lower kernel.yama.ptrace_scope.");
		}
		else if (!Error.isEmpty())
			Message = tr("Stack trace failed: %1").arg(Error);
		else
			Message = tr("No stack frames were returned.");

		emit StackTraced(MakeMessageTrace(Pid, Tid, Message));
		return;
	}

	CStackTracePtr Trace(new CStackTrace(Pid, Tid));

	foreach(const QVariant& FrameVar, Frames)
	{
		const QVariantMap Frame = FrameVar.toMap();

		const quint64 Address = Frame["Address"].toULongLong();
		const QString Module = Frame["Module"].toString();
		const quint64 Offset = Frame["Offset"].toULongLong();

		//
		// The name if one was found, otherwise the position - "libxul.so+0x4b2e7c"
		// is still something that can be looked up by hand, where a blank is not.
		//
		QString Symbol = Frame["Symbol"].toString();
		if (Symbol.isEmpty())
		{
			if (!Module.isEmpty())
				Symbol = QString("%1+0x%2").arg(Module.section('/', -1)).arg(Offset, 0, 16);
			else
				Symbol = QString("0x%1").arg(Address, 0, 16);
		}
		else if (Frame.contains("SymbolOffset"))
		{
			//
			// The offset into the symbol, which is what distinguishes a real match
			// from a nearest-preceding-symbol guess in a stripped library: a name
			// with a large offset is not to be trusted.
			//
			const quint64 SymbolOffset = Frame["SymbolOffset"].toULongLong();
			if (SymbolOffset)
				Symbol += QString("+0x%1").arg(SymbolOffset, 0, 16);
		}

		//
		// Source location where the debug information provided one, otherwise the
		// module and the offset into it.
		//
		QString FileInfo;
		if (Frame.contains("File"))
		{
			FileInfo = Frame["File"].toString();
			const int Line = Frame["Line"].toInt();
			if (Line)
				FileInfo += ":" + QString::number(Line);
		}
		else if (!Module.isEmpty())
		{
			FileInfo = Offset ? QString("%1+0x%2").arg(Module).arg(Offset, 0, 16) : Module;
		}

		quint64 Params[4] = { 0, 0, 0, 0 };
		Trace->AddFrame(Symbol, Address, 0, 0, 0, 0, Params, 0, FileInfo);
	}

	emit StackTraced(Trace);
}

foreach(const QVariant& FrameVar, Frames)
	{
		const QVariantMap Frame = FrameVar.toMap();

		const quint64 Address = Frame["Address"].toULongLong();
		const QString Module = Frame["Module"].toString();
		const quint64 Offset = Frame["Offset"].toULongLong();

		//
		// The name if one was found, otherwise the position - "libxul.so+0x4b2e7c"
		// is still something that can be looked up by hand, where a blank is not.
		//
		QString Symbol = Frame["Symbol"].toString();
		if (Symbol.isEmpty())
		{
			if (!Module.isEmpty())
				Symbol = QString("%1+0x%2").arg(Module.section('/', -1)).arg(Offset, 0, 16);
			else
				Symbol = QString("0x%1").arg(Address, 0, 16);
		}
		else if (Frame.contains("SymbolOffset"))
		{
			//
			// The offset into the symbol, which is what distinguishes a real match
			// from a nearest-preceding-symbol guess in a stripped library: a name
			// with a large offset is not to be trusted.
			//
			const quint64 SymbolOffset = Frame["SymbolOffset"].toULongLong();
			if (SymbolOffset)
				Symbol += QString("+0x%1").arg(SymbolOffset, 0, 16);
		}

		//
		// Source location where the debug information provided one, otherwise the
		// module and the offset into it.
		//
		QString FileInfo;
		if (Frame.contains("File"))
		{
			FileInfo = Frame["File"].toString();
			const int Line = Frame["Line"].toInt();
			if (Line)
				FileInfo += ":" + QString::number(Line);
		}
		else if (!Module.isEmpty())
		{
			FileInfo = Offset ? QString("%1+0x%2").arg(Module).arg(Offset, 0, 16) : Module;
		}

		quint64 Params[4] = { 0, 0, 0, 0 };
		Trace->AddFrame(Symbol, Address, 0, 0, 0, 0, Params, 0, FileInfo);
	}

CLinuxWnd::CLinuxWnd(QObject *parent)
	: CWndInfo(parent)
{
	m_IsMinimized = false;
	m_IsMaximized = false;
}

bool CLinuxWnd::InitStaticData(quint64 Window)
{
	X11Helper::SWindow Info;
	if (!X11Helper::QueryWindow(Window, Info))
		return false;

	QWriteLocker Locker(&m_Mutex);
	m_hWnd = Window;
	Apply(Info);
	return true;
}

void CLinuxWnd::Apply(const X11Helper::SWindow& Info)
{
	// Caller holds the write lock.
	m_hWnd = Info.Window;
	m_ParentWnd = Info.ParentWindow;
	m_ProcessId = Info.ProcessId;
	m_WindowTitle = Info.Title;
	m_WindowClass = Info.WindowClass;
	m_WindowVisible = Info.Visible;
	m_WindowOnTop = Info.AlwaysOnTop;
	m_WindowAlpha = Info.Alpha;
	m_IsMinimized = Info.Minimized;
	m_IsMaximized = Info.Maximized;

	//
	// X11 has no per-window enabled flag and no "not responding" state that is
	// cheap to sample - detecting a hung client means round-tripping _NET_WM_PING
	// and waiting for the reply, which is not worth doing on every refresh.
	//
	m_WindowEnabled = true;
	m_WindowHung = false;

	// The show command mirrors the Windows SW_* values the shared views expect:
	// 2 minimized, 3 maximized, 1 normal.
	m_ShowCommand = Info.Minimized ? 2 : (Info.Maximized ? 3 : 1);
}

bool CLinuxWnd::UpdateDynamicData()
{
	X11Helper::SWindow Info;
	if (!X11Helper::QueryWindow(GetHWnd(), Info))
		return false;

	QWriteLocker Locker(&m_Mutex);

	const bool bChanged = (m_WindowTitle != Info.Title)
		|| (m_WindowVisible != Info.Visible)
		|| (m_IsMinimized != Info.Minimized)
		|| (m_IsMaximized != Info.Maximized)
		|| (m_WindowOnTop != Info.AlwaysOnTop);

	Apply(Info);
	return bChanged;
}

STATUS CLinuxWnd::SetVisible(bool bSet)
{
	if (!X11Helper::SetVisible(GetHWnd(), bSet))
		return ERR(tr("Failed to change the window visibility."));
	return OK;
}

STATUS CLinuxWnd::SetEnabled(bool bSet)
{
	// X11 has no notion of a disabled top-level window; input is either grabbed
	// by the client or not.
	return ERR(tr("Enabling or disabling a window is not supported on X11."));
}

STATUS CLinuxWnd::SetAlwaysOnTop(bool bSet)
{
	if (!X11Helper::SetAlwaysOnTop(GetHWnd(), bSet))
		return ERR(tr("Failed to change the always-on-top state."));
	return OK;
}

STATUS CLinuxWnd::SetWindowAlpha(int iAlpha)
{
	if (!X11Helper::SetOpacity(GetHWnd(), iAlpha))
		return ERR(tr("Failed to set the window opacity."));
	// Without a compositing manager the property is set but has no visible
	// effect, which is not an error worth reporting.
	return OK;
}

STATUS CLinuxWnd::BringToFront()
{
	if (!X11Helper::Activate(GetHWnd()))
		return ERR(tr("Failed to activate the window."));
	return OK;
}

STATUS CLinuxWnd::Highlight()
{
	if (!X11Helper::Highlight(GetHWnd()))
		return ERR(tr("Failed to highlight the window."));
	return OK;
}

bool CLinuxWnd::IsNormal() const
{
	QReadLocker Locker(&m_Mutex);
	return !m_IsMinimized && !m_IsMaximized;
}

STATUS CLinuxWnd::Restore()
{
	// Un-minimize, then drop out of maximized if it was maximized.
	if (IsMinimized())
	{
		if (!X11Helper::SetMinimized(GetHWnd(), false))
			return ERR(tr("Failed to restore the window."));
		return OK;
	}

	if (!X11Helper::SetMaximized(GetHWnd(), false))
		return ERR(tr("Failed to restore the window."));
	return OK;
}

bool CLinuxWnd::IsMinimized() const
{
	QReadLocker Locker(&m_Mutex);
	return m_IsMinimized;
}

STATUS CLinuxWnd::Minimize()
{
	if (!X11Helper::SetMinimized(GetHWnd(), true))
		return ERR(tr("Failed to minimize the window."));
	return OK;
}

bool CLinuxWnd::IsMaximized() const
{
	QReadLocker Locker(&m_Mutex);
	return m_IsMaximized;
}

STATUS CLinuxWnd::Maximize()
{
	if (!X11Helper::SetMaximized(GetHWnd(), true))
		return ERR(tr("Failed to maximize the window."));
	return OK;
}

STATUS CLinuxWnd::Close()
{
	if (!X11Helper::Close(GetHWnd()))
		return ERR(tr("Failed to close the window."));
	return OK;
}

bool CLinuxDiskMonitor::Init()
{
	UpdateDisks();
	return true;
}

bool CLinuxDiskMonitor::UpdateDisks()
{
	const QList<ProcFs::SDiskStat> Stats = ProcFs::ReadDiskStats();

	QWriteLocker Locker(&m_StatsMutex);

	// Anything not seen in this pass has gone away (removable media, USB).
	QSet<QString> Seen;

	for (const ProcFs::SDiskStat& Stat : Stats)
	{
		Seen.insert(Stat.Name);

		SDiskInfo& Entry = m_DiskList[Stat.Name];

		Entry.DevicePath = "/dev/" + Stat.Name;
		Entry.DeviceIndex = Stat.Minor;
		Entry.DiskIndex = Stat.Minor;
		Entry.DevicePresent = true;

		//
		// /proc/diskstats reports the same counters for every block device, so
		// unlike the Windows backend - where some controllers refuse the
		// statistics IOCTL - there is no such thing as an unsupported disk.
		//
		Entry.DeviceSupported = true;

		// Re-read on every pass: capacity changes when removable media is
		// swapped, and an empty drive reports 0 which filters it from the view.
		Entry.TotalSize = ProcFs::ReadDiskSize(Stat.Name);

		if (Entry.DeviceName.isEmpty())
		{
			const QString Model = ProcFs::ReadDiskModel(Stat.Name);
			Entry.DeviceName = Model.isEmpty() ? Stat.Name : QString("%1 (%2)").arg(Model).arg(Stat.Name);
		}

		Entry.DeviceMountPoints = ProcFs::ReadDiskMountPoints(Stat.Name).join(", ");
	}

	for (auto I = m_DiskList.begin(); I != m_DiskList.end(); ++I)
	{
		if (!Seen.contains(I.key()))
			I.value().DevicePresent = false;
	}

	return true;
}

void CLinuxDiskMonitor::UpdateDiskStats()
{
	const QList<ProcFs::SDiskStat> Stats = ProcFs::ReadDiskStats();
	const quint64 CurTick = GetCurTick();

	QWriteLocker Locker(&m_StatsMutex);

	for (const ProcFs::SDiskStat& Stat : Stats)
	{
		auto I = m_DiskList.find(Stat.Name);
		if (I == m_DiskList.end())
			continue; // appeared since the last UpdateDisks(); picked up next pass

		SDiskInfo& Entry = I.value();

		Entry.SetRead(Stat.BytesRead, Stat.ReadsCompleted);
		Entry.SetWrite(Stat.BytesWritten, Stat.WritesCompleted);

		Entry.ReadTimeDelta.Update(Stat.ReadTimeMs);
		Entry.WriteTimeDelta.Update(Stat.WriteTimeMs);
		Entry.QueryTimeDelta.Update(Stat.IoTicksMs);

		const quint64 TimeMs = CurTick - Entry.LastStatUpdate;
		Entry.LastStatUpdate = CurTick;
		Entry.UpdateStats(TimeMs);

		//
		// Mean service time per request, in milliseconds. The kernel's read and
		// write time counters are already in ms, so unlike the Windows path
		// there is no tick conversion.
		//
		const quint64 Requests = Entry.ReadDelta.Delta + Entry.WriteDelta.Delta;
		if (Requests)
			Entry.ResponseTime = (float)(Entry.ReadTimeDelta.Delta + Entry.WriteTimeDelta.Delta) / Requests;
		else
			Entry.ResponseTime = 0.0f;

		//
		// io_ticks counts milliseconds during which the request queue was not
		// empty, so its delta over the elapsed wall time is utilisation.
		//
		// This is the same quantity iostat calls %util. It saturates at 100%
		// well before a modern SSD is actually saturated, because the kernel
		// only tracks "some request outstanding", not queue depth.
		//
		if (TimeMs)
			Entry.ActiveTime = (float)Entry.QueryTimeDelta.Delta / TimeMs * 100.0f;
		else
			Entry.ActiveTime = 0.0f;

		Entry.ActiveTime = qBound(0.0f, Entry.ActiveTime, 100.0f);

		Entry.QueueDepth = (quint32)Stat.IosInProgress;
		// The block layer does not expose a split-request counter.
		Entry.SplitCount = 0;
	}
}

bool CLinuxGpuMonitor::Init()
{
	UpdateAdapters();
	return true;
}

static QString VendorName(quint32 VendorId)
{
	switch (VendorId)
	{
		case 0x1002: return "AMD";
		case 0x10DE: return "NVIDIA";
		case 0x8086: return "Intel";
		case 0x1AF4: return "Virtio";
		case 0x1234: return "Bochs";		// QEMU's emulated VGA
		case 0x15AD: return "VMware";
		case 0x1414: return "Microsoft";	// Hyper-V synthetic
	}
	return QString("0x%1").arg(VendorId, 4, 16, QChar('0'));
}

bool CLinuxGpuMonitor::UpdateAdapters()
{
	//
	// /sys/class/drm contains both the cards themselves ("card0") and one entry
	// per connector ("card0-Virtual-1", "card0-HDMI-A-1"). Only the former are
	// adapters, and they are distinguished by having a "device" symlink.
	//
	const QStringList Entries = QDir("/sys/class/drm").entryList(QStringList("card*"), QDir::Dirs | QDir::System);

	QWriteLocker Locker(&m_StatsMutex);

	QMap<QString, SGpuInfo> NewList;

	for (const QString& Entry : Entries)
	{
		if (Entry.contains('-'))
			continue; // connector, not a card

		const QString Base = "/sys/class/drm/" + Entry;
		const QString Device = Base + "/device";
		if (!QFileInfo::exists(Device + "/vendor"))
			continue;

		SGpuInfo Info;
		Info.DeviceInterface = Entry;

		const quint32 VendorId = ProcFs::ReadFileStr(Device + "/vendor").trimmed().mid(2).toUInt(nullptr, 16);
		const quint32 DeviceId = ProcFs::ReadFileStr(Device + "/device").trimmed().mid(2).toUInt(nullptr, 16);
		Info.VendorID = VendorId;
		Info.DeviceID = DeviceId;

		// The kernel driver bound to the card, e.g. amdgpu / i915 / nvidia.
		const QString DriverPath = ProcFs::ReadLink(Device + "/driver");
		const QString DriverName = DriverPath.isEmpty() ? QString() : QFileInfo(DriverPath).fileName();

		Info.Description = QString("%1 %2 [%3:%4]")
			.arg(VendorName(VendorId))
			.arg(DriverName.isEmpty() ? QString("GPU") : DriverName)
			.arg(VendorId, 4, 16, QChar('0'))
			.arg(DeviceId, 4, 16, QChar('0'));

		Info.DriverVersion = DriverName;
		Info.LocationInfo = QFileInfo(ProcFs::ReadLink(Device)).fileName(); // PCI address

		//
		// VRAM size. Only amdgpu publishes this generically; Intel integrated
		// graphics has no dedicated memory to report, and NVIDIA's proprietary
		// driver exposes it through NVML rather than sysfs.
		//
		const QString VramTotal = ProcFs::ReadFileStr(Device + "/mem_info_vram_total").trimmed();
		if (!VramTotal.isEmpty())
		{
			Info.InstalledMemory = VramTotal.toULongLong();
			Info.Memory.DedicatedLimit = Info.InstalledMemory;
		}

		NewList.insert(Entry, Info);
	}

	// Preserve the usage figures already sampled for cards that still exist.
	for (auto I = NewList.begin(); I != NewList.end(); ++I)
	{
		auto Old = m_GpuList.constFind(I.key());
		if (Old != m_GpuList.constEnd())
		{
			I->TimeUsage = Old->TimeUsage;
			I->Memory.DedicatedUsage = Old->Memory.DedicatedUsage;
			I->Nodes = Old->Nodes;
		}
	}

	m_GpuList = NewList;

	return true;
}

bool CLinuxGpuMonitor::UpdateGpuStats()
{
	QWriteLocker Locker(&m_StatsMutex);

	for (auto I = m_GpuList.begin(); I != m_GpuList.end(); ++I)
	{
		const QString Device = "/sys/class/drm/" + I.key() + "/device";

		//
		// There is no vendor-neutral GPU utilisation counter in sysfs.
		//
		// amdgpu publishes gpu_busy_percent; Intel and NVIDIA do not, and the
		// portable alternative - summing the per-engine nanosecond counters in
		// each process's DRM fdinfo - needs a walk of every process's fd table
		// per refresh and is only present on newer kernels.
		//
		// Where nothing is available the usage stays at 0 rather than being
		// guessed at. This VM's emulated bochs-drm adapter is one such case.
		//
		const QString Busy = ProcFs::ReadFileStr(Device + "/gpu_busy_percent").trimmed();
		if (!Busy.isEmpty())
		{
			bool bOk = false;
			const int Percent = Busy.toInt(&bOk);
			if (bOk)
				I->TimeUsage = qBound(0.0f, (float)Percent / 100.0f, 1.0f);
		}

		const QString VramUsed = ProcFs::ReadFileStr(Device + "/mem_info_vram_used").trimmed();
		if (!VramUsed.isEmpty())
			I->Memory.DedicatedUsage = VramUsed.toULongLong();
	}

	return true;
}

QMap<QString, CGpuMonitor::SGpuInfo> CLinuxGpuMonitor::GetAllGpuList()
{
	QReadLocker Locker(&m_StatsMutex);
	return m_GpuList;
}

CGpuMonitor::SGpuMemory CLinuxGpuMonitor::GetGpuMemory()
{
	QReadLocker Locker(&m_StatsMutex);

	SGpuMemory Total;
	for (const SGpuInfo& Info : m_GpuList)
	{
		Total.DedicatedLimit += Info.Memory.DedicatedLimit;
		Total.DedicatedUsage += Info.Memory.DedicatedUsage;
		Total.SharedLimit += Info.Memory.SharedLimit;
		Total.SharedUsage += Info.Memory.SharedUsage;
	}
	return Total;
}

bool CLinuxNetMonitor::Init()
{
	UpdateAdapters();
	return true;
}

bool CLinuxNetMonitor::UpdateAdapters()
{
	const QList<ProcFs::SNetDevice> Devices = ProcFs::ReadNetDevices();

	//
	// Addresses come from Qt rather than sysfs: /sys/class/net has no address
	// listing, and the alternative is parsing /proc/net/if_inet6 plus an
	// rtnetlink dump for IPv4.
	//
	QMap<QString, QNetworkInterface> Interfaces;
	for (const QNetworkInterface& Interface : QNetworkInterface::allInterfaces())
		Interfaces.insert(Interface.name(), Interface);

	const QMap<QString, QList<QHostAddress> > Gateways = ProcFs::ReadDefaultGateways();

	//
	// DNS configuration is system-wide here. systemd-resolved does track it per
	// link, but reading that means a D-Bus round trip per interface against
	// org.freedesktop.resolve1; the system-wide view is what resolv.conf
	// describes and is what most setups actually have.
	//
	const ProcFs::SDnsConfig Dns = ProcFs::ReadDnsConfig();

	QWriteLocker Locker(&m_StatsMutex);

	QSet<QString> Seen;

	for (const ProcFs::SNetDevice& Device : Devices)
	{
		// The loopback interface carries no real traffic and would badly skew
		// the totals, since every local connection is counted twice on it.
		if (Device.IsLoopback)
			continue;

		Seen.insert(Device.Name);

		SNicInfo& Entry = m_NicList[Device.Name];

		Entry.DevicePresent = true;
		Entry.DeviceIndex = Device.Index;
		Entry.DeviceInterface = Device.Name;
		Entry.DeviceGuid = Device.MacAddress;
		Entry.DeviceName = Device.Name;
		Entry.DeviceSupported = 1;

		//
		// operstate is the authoritative link state; carrier alone is not,
		// because a "dormant" interface (associating wifi) has no carrier yet
		// is not disconnected.
		//
		if (Device.OperState == "up")
			Entry.LinkState = SNicInfo::eConnected;
		else if (Device.OperState == "down")
			Entry.LinkState = SNicInfo::eDisconnected;
		else
			Entry.LinkState = SNicInfo::eUnknown;

		// The GUI wants bits per second; sysfs reports megabits.
		Entry.LinkSpeed = (Device.SpeedMbit > 0) ? (quint64)Device.SpeedMbit * 1000 * 1000 : 0;

		// No dial-up/RAS concept on Linux.
		Entry.IsRAS = false;

		Entry.Addresses.clear();
		Entry.NetMasks.clear();
		auto FoundInterface = Interfaces.constFind(Device.Name);
		if (FoundInterface != Interfaces.constEnd())
		{
			for (const QNetworkAddressEntry& Address : FoundInterface->addressEntries())
			{
				Entry.Addresses.append(Address.ip());
				Entry.NetMasks.append(Address.netmask());
			}
		}

		Entry.Gateways = Gateways.value(Device.Name);

		//
		// Only interfaces that carry a default route get the DNS servers
		// attributed to them. Listing the resolver against every NIC - including
		// ones that are down - would be misleading.
		//
		if (!Entry.Gateways.isEmpty())
		{
			Entry.DNS = Dns.Servers;
			Entry.Domains = Dns.Domains;
		}
		else
		{
			Entry.DNS.clear();
			Entry.Domains.clear();
		}
	}

	for (auto I = m_NicList.begin(); I != m_NicList.end(); ++I)
	{
		if (!Seen.contains(I.key()))
			I.value().DevicePresent = false;
	}

	return true;
}

void CLinuxNetMonitor::UpdateNetStats()
{
	const QList<ProcFs::SNetDevice> Devices = ProcFs::ReadNetDevices();
	const quint64 CurTick = GetCurTick();

	QWriteLocker Locker(&m_StatsMutex);

	for (const ProcFs::SNetDevice& Device : Devices)
	{
		auto I = m_NicList.find(Device.Name);
		if (I == m_NicList.end())
			continue;

		SNicInfo& Entry = I.value();

		// These are cumulative byte/packet counters since the interface came
		// up; SNetStats turns them into deltas and rates.
		Entry.SetReceive(Device.RxBytes, Device.RxPackets);
		Entry.SetSend(Device.TxBytes, Device.TxPackets);

		const quint64 TimeMs = CurTick - Entry.LastStatUpdate;
		Entry.LastStatUpdate = CurTick;
		Entry.UpdateStats(TimeMs);
	}
}

QByteArray ReadFile(const QString& Path)
{
	QFile File(Path);
	if (!File.open(QIODevice::ReadOnly))
		return QByteArray();

	//
	// Files under /proc report a size of 0, so readAll() is the only correct
	// way to drain them - QFile::size() would yield an empty result.
	//
	return File.readAll();
}

QStringList ReadNulList(const QString& Path)
{
	QByteArray Data = ReadFile(Path);
	if (Data.isEmpty())
		return QStringList();

	// These files are NUL terminated, which would otherwise yield a trailing
	// empty entry on every read.
	while (Data.endsWith('\0'))
		Data.chop(1);
	if (Data.isEmpty())
		return QStringList();

	QStringList List;
	for (const QByteArray& Part : Data.split('\0'))
		List.append(QString::fromUtf8(Part));
	return List;
}

QString ReadLink(const QString& Path)
{
	//
	// Must be readlink(2) rather than QFile::symLinkTarget().
	//
	// The /proc/<pid>/fd links do not always point at a path: sockets, pipes
	// and anonymous inodes resolve to "socket:[12345]", "pipe:[12345]" and
	// "anon_inode:[eventfd]". Those are not absolute, so symLinkTarget()
	// helpfully rebases them against the link's own directory and hands back
	// "/proc/<pid>/fd/socket:[12345]" - which hides both the object kind and
	// the inode number that socket ownership is later resolved by.
	//
	const QByteArray Local = Path.toLocal8Bit();

	// /proc links report st_size 0, so the buffer has to be grown blindly.
	QByteArray Buffer(1024, '\0');
	for (;;)
	{
		const ssize_t Length = readlink(Local.constData(), Buffer.data(), Buffer.size());
		if (Length < 0)
			return QString(); // gone, or not permitted

		if (Length < Buffer.size())
			return QString::fromLocal8Bit(Buffer.constData(), (int)Length);

		// Truncated - readlink does not NUL terminate or report the full size.
		if (Buffer.size() > 64 * 1024)
			return QString::fromLocal8Bit(Buffer.constData(), (int)Length);
		Buffer.resize(Buffer.size() * 2);
	}
}

QString ProcPath(quint64 Pid, const QString& Leaf)
{
	QString Path = QString("/proc/%1").arg(Pid);
	if (!Leaf.isEmpty())
		Path += "/" + Leaf;
	return Path;
}

QString TaskPath(quint64 Pid, quint64 Tid, const QString& Leaf)
{
	QString Path = QString("/proc/%1/task/%2").arg(Pid).arg(Tid);
	if (!Leaf.isEmpty())
		Path += "/" + Leaf;
	return Path;
}

static QList<quint64> EnumNumericEntries(const QString& DirPath)
{
	QList<quint64> Entries;

	QDir Dir(DirPath);
	if (!Dir.exists())
		return Entries;

	const QStringList Names = Dir.entryList(QDir::Dirs | QDir::NoDotAndDotDot | QDir::System);
	for (const QString& Name : Names)
	{
		bool bOk = false;
		quint64 Value = Name.toULongLong(&bOk);
		if (bOk)
			Entries.append(Value);
	}
	return Entries;
}

QList<quint64> EnumFds(quint64 Pid)
{
	QList<quint64> Fds;

	QDir Dir(ProcPath(Pid, "fd"));
	// The fd entries are symlinks, not directories, so this needs a different
	// filter than EnumNumericEntries.
	const QStringList Names = Dir.entryList(QDir::Files | QDir::System | QDir::NoDotAndDotDot);
	for (const QString& Name : Names)
	{
		bool bOk = false;
		quint64 Value = Name.toULongLong(&bOk);
		if (bOk)
			Fds.append(Value);
	}
	return Fds;
}

SStat ParseStat(const QByteArray& Data)
{
	SStat Stat;
	if (Data.isEmpty())
		return Stat;

	//
	// Field 2 (comm) is wrapped in parentheses and may contain both spaces and
	// parentheses of its own - e.g. a process named ") evil (". Anchoring on
	// the LAST ')' is the only reliable split.
	//
	int Open = Data.indexOf('(');
	int Close = Data.lastIndexOf(')');
	if (Open < 0 || Close < 0 || Close < Open)
		return Stat;

	bool bOk = false;
	Stat.Pid = Data.left(Open).trimmed().toULongLong(&bOk);
	if (!bOk)
		return Stat;

	Stat.Comm = QString::fromUtf8(Data.mid(Open + 1, Close - Open - 1));

	const QList<QByteArray> F = Data.mid(Close + 1).simplified().split(' ');
	// F[0] is state, i.e. the original field 3; index i here == field (i + 3).
	auto U64 = [&F](int i) -> quint64 { return i < F.size() ? F[i].toULongLong() : 0; };
	auto I64 = [&F](int i) -> qint64  { return i < F.size() ? F[i].toLongLong()  : 0; };

	if (F.isEmpty() || F[0].isEmpty())
		return Stat;

	Stat.State		= F[0].at(0);
	Stat.PPid		= U64(1);
	Stat.PGrp		= U64(2);
	Stat.Session		= U64(3);
	Stat.TtyNr		= U64(4);
	Stat.TPGid		= U64(5);
	Stat.Flags		= U64(6);
	Stat.MinFlt		= U64(7);
	Stat.CMinFlt		= U64(8);
	Stat.MajFlt		= U64(9);
	Stat.CMajFlt		= U64(10);
	Stat.UTime		= U64(11);
	Stat.STime		= U64(12);
	Stat.CUTime		= I64(13);
	Stat.CSTime		= I64(14);
	Stat.Priority		= I64(15);
	Stat.Nice		= I64(16);
	Stat.NumThreads		= I64(17);
	// F[18] is itrealvalue, obsolete and always 0.
	Stat.StartTime		= U64(19);
	Stat.VSize		= U64(20);
	Stat.Rss		= I64(21);
	Stat.RssLim		= U64(22);
	Stat.StartCode		= U64(23);
	Stat.EndCode		= U64(24);
	Stat.StartStack		= U64(25);
	Stat.KstkEsp		= U64(26);
	Stat.KstkEip		= U64(27);
	// F[28..31] are the obsolete signal bitmaps.
	// F[32] is wchan, F[33..34] are obsolete.
	Stat.Processor		= U64(36);
	Stat.RtPriority		= U64(37);
	Stat.Policy		= U64(38);
	Stat.DelayAcctBlkIOTicks = U64(39);
	Stat.GuestTime		= U64(40);

	// PF_KTHREAD, from include/linux/sched.h. Defined locally because it is a
	// kernel-internal constant with no uapi header.
	static const quint64 PF_KTHREAD = 0x00200000;
	Stat.IsKernelThread = (Stat.Flags & PF_KTHREAD) != 0;

	Stat.Valid = true;
	return Stat;
}

QMap<QString, QString> ReadStatus(quint64 Pid)
{
	QMap<QString, QString> Status;

	const QByteArray Data = ReadFile(ProcPath(Pid, "status"));
	for (const QByteArray& Line : Data.split('\n'))
	{
		int Sep = Line.indexOf(':');
		if (Sep < 0)
			continue;
		Status.insert(QString::fromUtf8(Line.left(Sep)),
		              QString::fromUtf8(Line.mid(Sep + 1).trimmed()));
	}
	return Status;
}

SStatM ReadStatM(quint64 Pid)
{
	SStatM StatM;

	const QList<QByteArray> F = ReadFile(ProcPath(Pid, "statm")).simplified().split(' ');
	if (F.size() < 7)
		return StatM;

	StatM.Size	= F[0].toULongLong();
	StatM.Resident	= F[1].toULongLong();
	StatM.Shared	= F[2].toULongLong();
	StatM.Text	= F[3].toULongLong();
	StatM.Lib	= F[4].toULongLong();
	StatM.Data	= F[5].toULongLong();
	StatM.Dirty	= F[6].toULongLong();
	StatM.Valid	= true;
	return StatM;
}

SProcIo ParseProcIo(const QByteArray& Data)
{
	SProcIo Io;
	if (Data.isEmpty())
		return Io;

	for (const QByteArray& Line : Data.split('\n'))
	{
		int Sep = Line.indexOf(':');
		if (Sep < 0)
			continue;
		const QByteArray Key = Line.left(Sep);
		const quint64 Value = Line.mid(Sep + 1).trimmed().toULongLong();

		if      (Key == "rchar")                 Io.RChar = Value;
		else if (Key == "wchar")                 Io.WChar = Value;
		else if (Key == "syscr")                 Io.SysCr = Value;
		else if (Key == "syscw")                 Io.SysCw = Value;
		else if (Key == "read_bytes")            Io.ReadBytes = Value;
		else if (Key == "write_bytes")           Io.WriteBytes = Value;
		else if (Key == "cancelled_write_bytes") Io.CancelledWriteBytes = Value;
	}

	Io.Valid = true;
	return Io;
}

SProcIo ReadProcIo(quint64 Pid)
{
	//
	// Reading another user's /proc/<pid>/io needs PTRACE_MODE_READ, so this is
	// expected to fail for most processes when running unprivileged. Leaving
	// Valid false lets callers show "n/a" rather than a bogus 0 - and lets
	// CLinuxAPI collect the pid for a batched request to TaskHelper.
	//
	return ParseProcIo(ReadFile(ProcPath(Pid, "io")));
}

QList<SMapEntry> ParseMaps(const QByteArray& Data)
{
	QList<SMapEntry> Maps;

	for (const QByteArray& Line : Data.split('\n'))
	{
		if (Line.isEmpty())
			continue;

		// address           perms offset   dev   inode   pathname
		// 7f1c2a000000-7f1c2a021000 r-xp 00000000 08:01 1234  /usr/lib/libc.so
		const QList<QByteArray> F = Line.simplified().split(' ');
		if (F.size() < 5)
			continue;

		const int Dash = F[0].indexOf('-');
		if (Dash < 0)
			continue;

		SMapEntry Entry;
		Entry.Start	= F[0].left(Dash).toULongLong(nullptr, 16);
		Entry.End	= F[0].mid(Dash + 1).toULongLong(nullptr, 16);

		if (F[1].size() >= 4)
		{
			Entry.Read	= F[1][0] == 'r';
			Entry.Write	= F[1][1] == 'w';
			Entry.Exec	= F[1][2] == 'x';
			Entry.Shared	= F[1][3] == 's';
		}

		Entry.Offset = F[2].toULongLong(nullptr, 16);

		const int Colon = F[3].indexOf(':');
		if (Colon >= 0)
		{
			Entry.DevMajor = F[3].left(Colon).toUInt(nullptr, 16);
			Entry.DevMinor = F[3].mid(Colon + 1).toUInt(nullptr, 16);
		}

		Entry.Inode = F[4].toULongLong();

		// The path may legitimately contain spaces, so rejoin the remainder
		// instead of taking F[5] alone.
		if (F.size() > 5)
		{
			QByteArray Path;
			for (int i = 5; i < F.size(); i++)
			{
				if (i > 5)
					Path += ' ';
				Path += F[i];
			}
			Entry.Path = QString::fromUtf8(Path);
		}

		Maps.append(Entry);
	}

	return Maps;
}

static bool ApplyMapDetailLine(const QByteArray& Key, quint64 ValueBytes, SMapDetail& Detail)
{
	if      (Key == "Rss")            Detail.Rss = ValueBytes;
	else if (Key == "Pss")            Detail.Pss = ValueBytes;
	else if (Key == "Shared_Clean")   Detail.SharedClean = ValueBytes;
	else if (Key == "Shared_Dirty")   Detail.SharedDirty = ValueBytes;
	else if (Key == "Private_Clean")  Detail.PrivateClean = ValueBytes;
	else if (Key == "Private_Dirty")  Detail.PrivateDirty = ValueBytes;
	else if (Key == "Swap")           Detail.Swap = ValueBytes;
	else if (Key == "Locked")         Detail.Locked = ValueBytes;
	else return false;
	return true;
}

QMap<quint64, SMapDetail> ReadMapDetails(quint64 Pid)
{
	QMap<quint64, SMapDetail> Details;

	//
	// smaps repeats the maps header line for each region, followed by that
	// region's counters. A header is recognised by starting with a hex address
	// range rather than "Key:".
	//
	const QByteArray Data = ReadFile(ProcPath(Pid, "smaps"));

	quint64 CurrentStart = 0;
	bool bHaveRegion = false;
	SMapDetail Current;

	for (const QByteArray& Line : Data.split('\n'))
	{
		if (Line.isEmpty())
			continue;

		const int Colon = Line.indexOf(':');
		const int Dash = Line.indexOf('-');

		// Header lines have their '-' before any ':' (the address range).
		const bool bHeader = (Dash > 0) && (Colon < 0 || Dash < Colon);

		if (bHeader)
		{
			if (bHaveRegion)
				Details.insert(CurrentStart, Current);

			Current = SMapDetail();
			CurrentStart = Line.left(Dash).toULongLong(nullptr, 16);
			bHaveRegion = true;
			continue;
		}

		if (!bHaveRegion || Colon < 0)
			continue;

		const QByteArray Key = Line.left(Colon).trimmed();
		// Values are "<n> kB"; a few (VmFlags, THPeligible) are not numeric and
		// are simply not matched by ApplyMapDetailLine.
		const QList<QByteArray> F = Line.mid(Colon + 1).simplified().split(' ');
		if (F.isEmpty())
			continue;

		quint64 Value = F[0].toULongLong();
		if (F.size() > 1 && F[1] == "kB")
			Value *= 1024;

		ApplyMapDetailLine(Key, Value, Current);
	}

	if (bHaveRegion)
		Details.insert(CurrentStart, Current);

	return Details;
}

SMapDetail ReadMapRollup(quint64 Pid)
{
	SMapDetail Detail;

	// smaps_rollup has the same key/value lines as smaps but only one set,
	// already summed by the kernel. Present since Linux 4.14.
	const QByteArray Data = ReadFile(ProcPath(Pid, "smaps_rollup"));
	for (const QByteArray& Line : Data.split('\n'))
	{
		const int Colon = Line.indexOf(':');
		if (Colon < 0)
			continue;

		const QByteArray Key = Line.left(Colon).trimmed();
		const QList<QByteArray> F = Line.mid(Colon + 1).simplified().split(' ');
		if (F.isEmpty())
			continue;

		quint64 Value = F[0].toULongLong();
		if (F.size() > 1 && F[1] == "kB")
			Value *= 1024;

		ApplyMapDetailLine(Key, Value, Detail);
	}

	return Detail;
}

static SCpuTime ParseCpuLine(const QList<QByteArray>& F)
{
	SCpuTime Time;
	auto U64 = [&F](int i) -> quint64 { return i < F.size() ? F[i].toULongLong() : 0; };

	Time.User	= U64(1);
	Time.Nice	= U64(2);
	Time.System	= U64(3);
	Time.Idle	= U64(4);
	Time.IoWait	= U64(5);
	Time.Irq	= U64(6);
	Time.SoftIrq	= U64(7);
	Time.Steal	= U64(8);
	Time.Guest	= U64(9);
	Time.GuestNice	= U64(10);
	return Time;
}

SSysStat ReadSysStat()
{
	SSysStat Stat;

	const QByteArray Data = ReadFile("/proc/stat");
	if (Data.isEmpty())
		return Stat;

	for (const QByteArray& Line : Data.split('\n'))
	{
		if (Line.isEmpty())
			continue;

		const QList<QByteArray> F = Line.simplified().split(' ');
		const QByteArray& Key = F[0];

		if (Key == "cpu")
		{
			Stat.Total = ParseCpuLine(F);
		}
		else if (Key.startsWith("cpu"))
		{
			bool bOk = false;
			const int Index = Key.mid(3).toInt(&bOk);
			if (bOk)
			{
				if (Stat.PerCpu.size() <= Index)
					Stat.PerCpu.resize(Index + 1);
				Stat.PerCpu[Index] = ParseCpuLine(F);
			}
		}
		else if (Key == "ctxt" && F.size() > 1)		Stat.ContextSwitches = F[1].toULongLong();
		else if (Key == "btime" && F.size() > 1)	Stat.BootTime = F[1].toULongLong();
		else if (Key == "processes" && F.size() > 1)	Stat.Processes = F[1].toULongLong();
		else if (Key == "procs_running" && F.size() > 1) Stat.ProcsRunning = F[1].toULongLong();
		else if (Key == "procs_blocked" && F.size() > 1) Stat.ProcsBlocked = F[1].toULongLong();
		else if (Key == "intr" && F.size() > 1)		Stat.Interrupts = F[1].toULongLong();
	}

	Stat.Valid = true;
	return Stat;
}

QMap<QString, quint64> ReadMemInfo()
{
	QMap<QString, quint64> Info;

	const QByteArray Data = ReadFile("/proc/meminfo");
	for (const QByteArray& Line : Data.split('\n'))
	{
		int Sep = Line.indexOf(':');
		if (Sep < 0)
			continue;

		const QString Key = QString::fromUtf8(Line.left(Sep));
		const QByteArray Rest = Line.mid(Sep + 1).trimmed();

		// Almost every entry is "<number> kB"; a few (HugePages_*) are a bare
		// count. Normalise the former to bytes and leave the latter alone.
		const QList<QByteArray> F = Rest.simplified().split(' ');
		if (F.isEmpty())
			continue;

		quint64 Value = F[0].toULongLong();
		if (F.size() > 1 && F[1] == "kB")
			Value *= 1024;

		Info.insert(Key, Value);
	}
	return Info;
}

QList<SSwapArea> ReadSwaps()
{
	QList<SSwapArea> Areas;

	const QByteArray Data = ReadFile("/proc/swaps");
	const QList<QByteArray> Lines = Data.split('\n');

	// First line is the header: "Filename Type Size Used Priority"
	for (int i = 1; i < Lines.size(); i++)
	{
		if (Lines[i].isEmpty())
			continue;

		const QList<QByteArray> F = Lines[i].simplified().split(' ');
		if (F.size() < 4)
			continue;

		SSwapArea Area;
		Area.Path = QString::fromUtf8(F[0]);
		Area.Type = QString::fromUtf8(F[1]);
		// Size and Used are in 1 KiB units regardless of page size.
		Area.Size = F[2].toULongLong() * 1024;
		Area.Used = F[3].toULongLong() * 1024;
		Areas.append(Area);
	}

	return Areas;
}

SCpuInfo ReadCpuInfo()
{
	SCpuInfo Info;

	QSet<QString> Packages;
	QSet<QString> Cores;
	QString CurPhysicalId;

	const QByteArray Data = ReadFile("/proc/cpuinfo");
	for (const QByteArray& Line : Data.split('\n'))
	{
		const int Sep = Line.indexOf(':');
		if (Sep < 0)
			continue;

		const QByteArray Key = Line.left(Sep).trimmed();
		const QByteArray Value = Line.mid(Sep + 1).trimmed();

		if (Key == "processor")
		{
			Info.Logical++;
			// A new block starts here; forget the previous block's socket.
			CurPhysicalId.clear();
		}
		else if (Key == "model name" && Info.ModelName.isEmpty())
		{
			Info.ModelName = QString::fromUtf8(Value);
		}
		else if (Key == "cpu MHz" && Info.MHz == 0)
		{
			Info.MHz = Value.toDouble();
		}
		else if (Key == "physical id")
		{
			CurPhysicalId = QString::fromUtf8(Value);
			Packages.insert(CurPhysicalId);
		}
		else if (Key == "core id")
		{
			// Core ids repeat across sockets, so they only identify a physical
			// core when paired with the socket they belong to.
			Cores.insert(CurPhysicalId + ":" + QString::fromUtf8(Value));
		}
	}

	if (Info.Logical == 0)
	{
		long Online = sysconf(_SC_NPROCESSORS_ONLN);
		Info.Logical = (Online > 0) ? (int)Online : 1;
	}

	// arm64 and some virtualised x86 cpuinfo layouts omit physical/core id.
	Info.Packages = Packages.isEmpty() ? 1 : Packages.size();
	Info.Cores = Cores.isEmpty() ? Info.Logical : Cores.size();

	if (Info.ModelName.isEmpty())
	{
		// arm64 reports "CPU implementer"/"CPU part" instead of a model name.
		Info.ModelName = QString::fromUtf8(QSysInfo::currentCpuArchitecture().toUtf8());
	}

	return Info;
}

static QHostAddress ParseNetAddress(const QByteArray& Hex, bool bIPv6)
{
	if (!bIPv6)
	{
		if (Hex.size() < 8)
			return QHostAddress();
		bool bOk = false;
		const quint32 Raw = Hex.left(8).toUInt(&bOk, 16);
		if (!bOk)
			return QHostAddress();
		// Raw is host-order of a little-endian word: swap to get the address.
		return QHostAddress(qFromBigEndian<quint32>(qToLittleEndian<quint32>(Raw)));
	}

	if (Hex.size() < 32)
		return QHostAddress();

	quint8 Bytes[16];
	for (int Word = 0; Word < 4; Word++)
	{
		bool bOk = false;
		const quint32 Raw = Hex.mid(Word * 8, 8).toUInt(&bOk, 16);
		if (!bOk)
			return QHostAddress();
		const quint32 Swapped = qFromBigEndian<quint32>(qToLittleEndian<quint32>(Raw));
		Bytes[Word * 4 + 0] = (Swapped >> 24) & 0xFF;
		Bytes[Word * 4 + 1] = (Swapped >> 16) & 0xFF;
		Bytes[Word * 4 + 2] = (Swapped >> 8) & 0xFF;
		Bytes[Word * 4 + 3] = (Swapped) & 0xFF;
	}
	return QHostAddress(Bytes);
}

static void ReadNetTable(const QString& Path, quint32 ProtocolType, bool bIPv6, bool bTcp,
                         QList<SNetConnection>& Connections)
{
	const QByteArray Data = ReadFile(Path);
	const QList<QByteArray> Lines = Data.split('\n');

	// Line 0 is the column header.
	for (int i = 1; i < Lines.size(); i++)
	{
		if (Lines[i].isEmpty())
			continue;

		//  sl local_address rem_address st tx_queue:rx_queue tr tm->when retrnsmt uid timeout inode
		const QList<QByteArray> F = Lines[i].simplified().split(' ');
		if (F.size() < 10)
			continue;

		const QList<QByteArray> Local = F[1].split(':');
		const QList<QByteArray> Remote = F[2].split(':');
		if (Local.size() < 2 || Remote.size() < 2)
			continue;

		SNetConnection Conn;
		Conn.ProtocolType = ProtocolType;
		Conn.LocalAddress = ParseNetAddress(Local[0], bIPv6);
		Conn.LocalPort = Local[1].toUShort(nullptr, 16);
		Conn.RemoteAddress = ParseNetAddress(Remote[0], bIPv6);
		Conn.RemotePort = Remote[1].toUShort(nullptr, 16);

		const quint32 RawState = F[3].toUInt(nullptr, 16);
		//
		// The state column only means anything for TCP. UDP reuses it for its
		// own pseudo states, where 7 (TCP_CLOSE) is an ordinary unconnected
		// socket - reporting that as "Closed" would be misleading, so UDP is
		// pinned to ESTAB, which the shared code renders as "Open".
		//
		Conn.State = bTcp ? TcpStateToMib(RawState) : 5;

		const QList<QByteArray> Queues = F[4].split(':');
		if (Queues.size() >= 2)
		{
			Conn.TxQueue = Queues[0].toULongLong(nullptr, 16);
			Conn.RxQueue = Queues[1].toULongLong(nullptr, 16);
		}

		Conn.Uid = F[7].toUInt();
		Conn.Inode = F[9].toULongLong();

		Connections.append(Conn);
	}
}

QList<SNetConnection> ReadNetConnections()
{
	QList<SNetConnection> Connections;

	// NET_TYPE_* values, mirrored from SocketInfo.h to keep ProcFs free of
	// dependencies on the API layer.
	const quint32 NET_IPV4 = 0x1, NET_IPV6 = 0x2, NET_TCP = 0x10, NET_UDP = 0x20;

	ReadNetTable("/proc/net/tcp",  NET_IPV4 | NET_TCP, false, true,  Connections);
	ReadNetTable("/proc/net/tcp6", NET_IPV6 | NET_TCP, true,  true,  Connections);
	ReadNetTable("/proc/net/udp",  NET_IPV4 | NET_UDP, false, false, Connections);
	ReadNetTable("/proc/net/udp6", NET_IPV6 | NET_UDP, true,  false, Connections);

	return Connections;
}

QMap<quint64, quint64> BuildSocketInodeMap()
{
	QMap<quint64, quint64> InodeToPid;

	for (quint64 Pid : EnumProcesses())
	{
		const QString FdDir = ProcPath(Pid, "fd");

		//
		// Iterating with QDirIterator rather than EnumFds + ReadLink avoids
		// building an intermediate list per process; this loop runs over every
		// process on every socket refresh, so it is the hot path here.
		//
		QDirIterator It(FdDir, QDir::Files | QDir::System | QDir::NoDotAndDotDot);
		while (It.hasNext())
		{
			const QString Target = ReadLink(It.next());
			if (!Target.startsWith("socket:["))
				continue;

			const int Close = Target.lastIndexOf(']');
			if (Close < 8)
				continue;

			const quint64 Inode = Target.mid(8, Close - 8).toULongLong();
			if (!Inode)
				continue;

			// First writer wins. A socket shared across a fork appears under
			// several pids; the lowest enumerated one is as good a choice as
			// any and matches what ss reports first.
			if (!InodeToPid.contains(Inode))
				InodeToPid.insert(Inode, Pid);
		}
	}

	return InodeToPid;
}

QList<SDiskStat> ReadDiskStats()
{
	QList<SDiskStat> Stats;

	//
	// /proc/diskstats lists partitions alongside whole devices. Only names that
	// exist as a directory under /sys/block are whole devices, which is the
	// cheapest reliable way to tell them apart (sda is there, sda1 is not).
	//
	const QSet<QString> WholeDevices = [] {
		QSet<QString> Set;
		for (const QString& Name : QDir("/sys/block").entryList(QDir::Dirs | QDir::NoDotAndDotDot))
			Set.insert(Name);
		return Set;
	}();

	const QByteArray Data = ReadFile("/proc/diskstats");
	for (const QByteArray& Line : Data.split('\n'))
	{
		if (Line.isEmpty())
			continue;

		const QList<QByteArray> F = Line.simplified().split(' ');
		if (F.size() < 14)
			continue;

		const QString Name = QString::fromUtf8(F[2]);
		if (!WholeDevices.contains(Name))
			continue;

		// Virtual devices that would only clutter the disk view.
		if (Name.startsWith("loop") || Name.startsWith("ram") || Name.startsWith("zram"))
			continue;

		SDiskStat Stat;
		Stat.Major		= F[0].toUInt();
		Stat.Minor		= F[1].toUInt();
		Stat.Name		= Name;
		Stat.ReadsCompleted	= F[3].toULongLong();
		Stat.BytesRead		= F[5].toULongLong() * 512;
		Stat.ReadTimeMs		= F[6].toULongLong();
		Stat.WritesCompleted	= F[7].toULongLong();
		Stat.BytesWritten	= F[9].toULongLong() * 512;
		Stat.WriteTimeMs	= F[10].toULongLong();
		Stat.IosInProgress	= F[11].toULongLong();
		Stat.IoTicksMs		= F[12].toULongLong();

		Stats.append(Stat);
	}

	return Stats;
}

quint64 ReadDiskSize(const QString& Device)
{
	// /sys/block/<dev>/size is in 512 byte sectors, always, regardless of the
	// device's logical block size.
	const QByteArray Data = ReadFile(QString("/sys/block/%1/size").arg(Device));
	return Data.trimmed().toULongLong() * 512;
}

QString ReadDiskModel(const QString& Device)
{
	QString Model = ReadFileStr(QString("/sys/block/%1/device/model").arg(Device)).trimmed();
	if (Model.isEmpty())
	{
		// Virtual and NVMe devices often expose a model elsewhere or not at all.
		Model = ReadFileStr(QString("/sys/block/%1/device/name").arg(Device)).trimmed();
	}
	return Model;
}

QStringList ReadDiskMountPoints(const QString& Device)
{
	QStringList Mounts;

	//
	// mountinfo field 3 is "major:minor" of the source device and field 5 is
	// the mount point. Matching on the major of the whole device catches all of
	// its partitions, which is what "mount points of this disk" should mean.
	//
	const quint32 Major = ReadFileStr(QString("/sys/block/%1/dev").arg(Device)).section(':', 0, 0).toUInt();
	if (!Major)
		return Mounts;

	const QByteArray Data = ReadFile("/proc/self/mountinfo");
	for (const QByteArray& Line : Data.split('\n'))
	{
		const QList<QByteArray> F = Line.simplified().split(' ');
		if (F.size() < 5)
			continue;

		if (F[2].split(':').value(0).toUInt() != Major)
			continue;

		const QString Mount = QString::fromUtf8(F[4]);
		if (!Mounts.contains(Mount))
			Mounts.append(Mount);
	}

	return Mounts;
}

QList<SNetDevice> ReadNetDevices()
{
	QList<SNetDevice> Devices;

	const QStringList Names = QDir("/sys/class/net").entryList(QDir::Dirs | QDir::NoDotAndDotDot | QDir::System);
	for (const QString& Name : Names)
	{
		const QString Base = "/sys/class/net/" + Name;

		SNetDevice Device;
		Device.Name = Name;
		Device.MacAddress = ReadFileStr(Base + "/address").trimmed();
		Device.Index = ReadFileStr(Base + "/ifindex").trimmed().toUInt();
		Device.OperState = ReadFileStr(Base + "/operstate").trimmed();

		// ARPHRD_LOOPBACK is 772.
		Device.IsLoopback = (ReadFileStr(Base + "/type").trimmed().toUInt() == 772);

		//
		// speed and carrier return EINVAL for a down interface, and speed is
		// simply absent for virtual devices. An empty read leaves the -1
		// sentinel meaning "unknown" rather than reporting a link speed of 0.
		//
		const QString Speed = ReadFileStr(Base + "/speed").trimmed();
		if (!Speed.isEmpty())
		{
			bool bOk = false;
			const qint64 Value = Speed.toLongLong(&bOk);
			if (bOk && Value > 0)
				Device.SpeedMbit = Value;
		}
		Device.Carrier = (ReadFileStr(Base + "/carrier").trimmed() == "1");

		const QString Stats = Base + "/statistics/";
		Device.RxBytes	= ReadFileStr(Stats + "rx_bytes").trimmed().toULongLong();
		Device.RxPackets = ReadFileStr(Stats + "rx_packets").trimmed().toULongLong();
		Device.TxBytes	= ReadFileStr(Stats + "tx_bytes").trimmed().toULongLong();
		Device.TxPackets = ReadFileStr(Stats + "tx_packets").trimmed().toULongLong();

		Devices.append(Device);
	}

	return Devices;
}

QMap<QString, QList<QHostAddress> > ReadDefaultGateways()
{
	QMap<QString, QList<QHostAddress> > Gateways;

	//
	// IPv4: /proc/net/route. A destination of 0.0.0.0 with the gateway flag set
	// is a default route. Both fields are little-endian hex, like the socket
	// tables.
	//
	const QByteArray V4 = ReadFile("/proc/net/route");
	const QList<QByteArray> V4Lines = V4.split('\n');
	for (int i = 1; i < V4Lines.size(); i++)	// line 0 is the header
	{
		const QList<QByteArray> F = V4Lines[i].simplified().split(' ');
		if (F.size() < 4)
			continue;

		if (F[1] != "00000000")
			continue; // not a default route

		// RTF_GATEWAY is 0x0002.
		const quint32 Flags = F[3].toUInt(nullptr, 16);
		if (!(Flags & 0x0002))
			continue;

		bool bOk = false;
		const quint32 Raw = F[2].toUInt(&bOk, 16);
		if (!bOk || !Raw)
			continue;

		const QHostAddress Address(qFromBigEndian<quint32>(qToLittleEndian<quint32>(Raw)));
		Gateways[QString::fromUtf8(F[0])].append(Address);
	}

	//
	// IPv6: /proc/net/ipv6_route, whose columns are
	//   dest plen src plen nexthop metric refcnt use flags iface
	// all as plain hex with no separators. A destination prefix length of 0 is
	// the default route.
	//
	const QByteArray V6 = ReadFile("/proc/net/ipv6_route");
	for (const QByteArray& Line : V6.split('\n'))
	{
		if (Line.isEmpty())
			continue;

		const QList<QByteArray> F = Line.simplified().split(' ');
		if (F.size() < 10)
			continue;

		if (F[1] != "00")
			continue; // prefix length != 0, so not a default route

		const QByteArray NextHop = F[4];
		if (NextHop.size() < 32 || NextHop == QByteArray(32, '0'))
			continue; // no gateway (an on-link route)

		quint8 Bytes[16];
		bool bOk = true;
		for (int b = 0; b < 16 && bOk; b++)
			Bytes[b] = (quint8)NextHop.mid(b * 2, 2).toUShort(&bOk, 16);
		if (!bOk)
			continue;

		Gateways[QString::fromUtf8(F[9])].append(QHostAddress(Bytes));
	}

	return Gateways;
}

SDnsConfig ReadDnsConfig()
{
	SDnsConfig Config;

	auto Parse = [](const QString& Path, SDnsConfig& Out) {
		const QByteArray Data = ReadFile(Path);
		for (const QByteArray& Line : Data.split('\n'))
		{
			const QList<QByteArray> F = Line.simplified().split(' ');
			if (F.size() < 2)
				continue;

			if (F[0] == "nameserver")
			{
				const QHostAddress Address(QString::fromUtf8(F[1]));
				if (!Address.isNull())
					Out.Servers.append(Address);
			}
			else if (F[0] == "search" || F[0] == "domain")
			{
				for (int i = 1; i < F.size(); i++)
				{
					const QString Domain = QString::fromUtf8(F[i]);
					// resolved writes "search ." when there is no real domain.
					if (Domain != ".")
						Out.Domains.insert(Domain);
				}
			}
		}
	};

	Parse("/etc/resolv.conf", Config);

	//
	// If the only server is the systemd-resolved stub listener, the useful
	// answer is upstream of it. resolved publishes the real servers in its own
	// resolv.conf.
	//
	bool bStubOnly = !Config.Servers.isEmpty();
	for (const QHostAddress& Server : Config.Servers)
	{
		if (Server != QHostAddress("127.0.0.53"))
		{
			bStubOnly = false;
			break;
		}
	}

	if (bStubOnly)
	{
		SDnsConfig Upstream;
		Parse("/run/systemd/resolve/resolv.conf", Upstream);
		if (!Upstream.Servers.isEmpty())
		{
			Config.Servers = Upstream.Servers;
			Config.Domains.unite(Upstream.Domains);
		}
	}

	return Config;
}

QMap<QString, QString> ReadOsRelease()
{
	QMap<QString, QString> Values;

	QByteArray Data = ReadFile("/etc/os-release");
	if (Data.isEmpty())
		Data = ReadFile("/usr/lib/os-release");

	for (const QByteArray& Line : Data.split('\n'))
	{
		const int Equals = Line.indexOf('=');
		if (Equals <= 0)
			continue;

		const QByteArray Key = Line.left(Equals).trimmed();
		if (Key.startsWith('#'))
			continue;

		QByteArray Value = Line.mid(Equals + 1).trimmed();

		// Values may be quoted with either single or double quotes.
		if (Value.size() >= 2 &&
		    ((Value.startsWith('"') && Value.endsWith('"')) ||
		     (Value.startsWith('\'') && Value.endsWith('\''))))
		{
			Value = Value.mid(1, Value.size() - 2);
		}

		Values.insert(QString::fromUtf8(Key), QString::fromUtf8(Value));
	}

	return Values;
}

QString ReadCGroupPath(quint64 Pid)
{
	//
	// cgroup v2 has a single "0::<path>" line. v1 has one line per controller,
	// "<id>:<controllers>:<path>"; the systemd hierarchy is the one whose
	// controller field is "name=systemd" (or empty, on the unified hierarchy).
	//
	const QByteArray Data = ReadFile(ProcPath(Pid, "cgroup"));
	if (Data.isEmpty())
		return QString();

	QString CgroupPath;
	for (const QByteArray& Line : Data.split('\n'))
	{
		const QList<QByteArray> F = Line.split(':');
		if (F.size() < 3)
			continue;

		// Rejoin in case the path itself contains a colon.
		QByteArray Path = F.mid(2).join(':');

		if (F[0] == "0" && F[1].isEmpty())	// cgroup v2 unified
			return QString::fromUtf8(Path).trimmed();

		if (F[1] == "name=systemd")		// cgroup v1 systemd hierarchy
			CgroupPath = QString::fromUtf8(Path).trimmed();
	}

	return CgroupPath;
}

SServiceUnit ReadServiceUnit(quint64 Pid)
{
	SServiceUnit Unit;

	const QString CgroupPath = ReadCGroupPath(Pid);
	if (CgroupPath.isEmpty())
		return Unit;

	const QStringList Parts = CgroupPath.split('/', Qt::SkipEmptyParts);
	for (int i = Parts.size() - 1; i >= 0; i--)
	{
		// A scope is a separately tracked unit; anything enclosing it does not
		// own this process for the purpose of naming a service.
		if (Parts[i].endsWith(".scope"))
			return Unit;

		if (Parts[i].endsWith(".service"))
		{
			Unit.Name = Parts[i];
			Unit.bSystemSlice = !Parts.isEmpty() && Parts.first() == "system.slice";
			return Unit;
		}
	}

	return Unit;
}

quint64 ClockTicksPerSec()
{
	static const quint64 Ticks = []() -> quint64 {
		long Value = sysconf(_SC_CLK_TCK);
		return Value > 0 ? (quint64)Value : 100;
	}();
	return Ticks;
}

quint64 PageSize()
{
	static const quint64 Size = []() -> quint64 {
		long Value = sysconf(_SC_PAGESIZE);
		return Value > 0 ? (quint64)Value : 4096;
	}();
	return Size;
}

double UpTime()
{
	const QList<QByteArray> F = ReadFile("/proc/uptime").simplified().split(' ');
	if (F.isEmpty())
		return 0.0;
	return F[0].toDouble();
}

quint64 StartTimeToEpochMs(quint64 StartTimeTicks)
{
	//
	// stat.StartTime is measured in clock ticks since boot, so it needs the
	// boot wall-clock time from /proc/stat's btime to become an absolute
	// timestamp.
	//
	static const quint64 BootTimeSec = []() -> quint64 {
		return ReadSysStat().BootTime;
	}();

	if (!BootTimeSec)
		return 0;

	return (BootTimeSec * 1000ULL) + (StartTimeTicks * 1000ULL / ClockTicksPerSec());
}

QString UserNameFromUid(quint32 Uid)
{
	//
	// getpwuid_r needs a caller-supplied buffer; _SC_GETPW_R_SIZE_MAX is only a
	// hint, so fall back to a sane size and grow once on ERANGE.
	//
	long Hint = sysconf(_SC_GETPW_R_SIZE_MAX);
	size_t BufSize = (Hint > 0) ? (size_t)Hint : 4096;

	for (int Attempt = 0; Attempt < 2; Attempt++)
	{
		QByteArray Buffer(BufSize, '\0');
		struct passwd Pwd;
		struct passwd* pResult = nullptr;

		int Ret = getpwuid_r(Uid, &Pwd, Buffer.data(), Buffer.size(), &pResult);
		if (Ret == ERANGE)
		{
			BufSize *= 4;
			continue;
		}
		if (Ret != 0 || !pResult)
			break;

		return QString::fromUtf8(pResult->pw_name);
	}

	return QString::number(Uid);
}

QString GroupNameFromGid(quint32 Gid)
{
	long Hint = sysconf(_SC_GETGR_R_SIZE_MAX);
	size_t BufSize = (Hint > 0) ? (size_t)Hint : 4096;

	for (int Attempt = 0; Attempt < 2; Attempt++)
	{
		QByteArray Buffer(BufSize, '\0');
		struct group Grp;
		struct group* pResult = nullptr;

		int Ret = getgrgid_r(Gid, &Grp, Buffer.data(), Buffer.size(), &pResult);
		if (Ret == ERANGE)
		{
			BufSize *= 4;
			continue;
		}
		if (Ret != 0 || !pResult)
			break;

		return QString::fromUtf8(pResult->gr_name);
	}

	return QString::number(Gid);
}

QMap<QString, quint64> ReadVmStat()
{
	QMap<QString, quint64> Stats;

	// One "name value" pair per line, whitespace separated.
	const QByteArray Data = ReadFile("/proc/vmstat");
	for (const QByteArray& Line : Data.split('\n'))
	{
		const int Sep = Line.indexOf(' ');
		if (Sep < 0)
			continue;
		Stats.insert(QString::fromUtf8(Line.left(Sep)), Line.mid(Sep + 1).trimmed().toULongLong());
	}

	return Stats;
}

static quint64 ParseCGroupLimit(const QString& Value)
{
	const QString Trimmed = Value.trimmed();
	if (Trimmed.isEmpty() || Trimmed == "max")
		return 0;
	return Trimmed.toULongLong();
}

static QString CGroupFilePath(const QString& CGroupPath, const QString& Leaf)
{
	// The unified hierarchy is mounted at /sys/fs/cgroup, and the path from
	// /proc/<pid>/cgroup is relative to that mount point.
	return "/sys/fs/cgroup" + CGroupPath + "/" + Leaf;
}

SPressure ParsePressure(const QByteArray& Data)
{
	SPressure Pressure;

	//
	// Two lines, "some" and "full", each:
	//   some avg10=0.00 avg60=0.00 avg300=0.03 total=83030100
	//
	// "full" is absent for the cpu resource on some kernels, which is why each
	// line is matched by its leading keyword rather than by position.
	//
	for (const QByteArray& Line : Data.split('\n'))
	{
		const QList<QByteArray> Fields = Line.simplified().split(' ');
		if (Fields.size() < 2)
			continue;

		const bool bFull = (Fields[0] == "full");
		if (!bFull && Fields[0] != "some")
			continue;

		for (int i = 1; i < Fields.size(); i++)
		{
			const int Eq = Fields[i].indexOf('=');
			if (Eq < 0)
				continue;

			const QByteArray Key = Fields[i].left(Eq);
			const QByteArray Value = Fields[i].mid(Eq + 1);

			if (Key == "avg10")			(bFull ? Pressure.FullAvg10 : Pressure.SomeAvg10) = Value.toFloat();
			else if (Key == "avg60")	(bFull ? Pressure.FullAvg60 : Pressure.SomeAvg60) = Value.toFloat();
			else if (Key == "avg300")	(bFull ? Pressure.FullAvg300 : Pressure.SomeAvg300) = Value.toFloat();
			else if (Key == "total")	(bFull ? Pressure.FullTotal : Pressure.SomeTotal) = Value.toULongLong();
		}

		Pressure.Valid = true;
	}

	return Pressure;
}

SPressure ReadSysPressure(const QString& Resource)
{
	// Absent when the kernel was built without CONFIG_PSI or booted with
	// psi=0, in which case Valid stays false and the caller shows nothing.
	return ParsePressure(ReadFile("/proc/pressure/" + Resource));
}

SPressure ReadCGroupPressure(const QString& CGroupPath, const QString& Resource)
{
	if (CGroupPath.isEmpty())
		return SPressure();
	return ParsePressure(ReadFile(CGroupFilePath(CGroupPath, Resource + ".pressure")));
}

SCGroupStats ReadCGroupStats(const QString& CGroupPath)
{
	SCGroupStats Stats;
	if (CGroupPath.isEmpty())
		return Stats;

	//
	// Which files exist depends on which controllers are enabled for this
	// cgroup, so every read is optional and an absent file simply leaves its
	// fields at zero.
	//
	auto ReadValue = [&](const QString& Leaf) -> QString {
		return ReadFileStr(CGroupFilePath(CGroupPath, Leaf)).trimmed();
	};

	const QString MemoryCurrent = ReadValue("memory.current");
	if (!MemoryCurrent.isEmpty())
	{
		Stats.Valid = true;
		Stats.MemoryCurrent = MemoryCurrent.toULongLong();
		Stats.MemoryPeak = ReadValue("memory.peak").toULongLong();
		Stats.MemoryMax = ParseCGroupLimit(ReadValue("memory.max"));
		Stats.MemoryHigh = ParseCGroupLimit(ReadValue("memory.high"));
		Stats.MemorySwapCurrent = ReadValue("memory.swap.current").toULongLong();
		Stats.MemorySwapMax = ParseCGroupLimit(ReadValue("memory.swap.max"));
	}

	// cpu.stat is "key value" per line; the throttling keys appear only once a
	// cpu.max limit has been set.
	const QByteArray CpuStat = ReadFile(CGroupFilePath(CGroupPath, "cpu.stat"));
	for (const QByteArray& Line : CpuStat.split('\n'))
	{
		const QList<QByteArray> Fields = Line.simplified().split(' ');
		if (Fields.size() < 2)
			continue;

		const quint64 Value = Fields[1].toULongLong();
		if (Fields[0] == "usage_usec")				Stats.CpuUsageUs = Value;
		else if (Fields[0] == "user_usec")			Stats.CpuUserUs = Value;
		else if (Fields[0] == "system_usec")		Stats.CpuSystemUs = Value;
		else if (Fields[0] == "nr_periods")			Stats.NrPeriods = Value;
		else if (Fields[0] == "nr_throttled")		Stats.NrThrottled = Value;
		else if (Fields[0] == "throttled_usec")		Stats.ThrottledUs = Value;

		Stats.Valid = true;
	}

	const QString PidsCurrent = ReadValue("pids.current");
	if (!PidsCurrent.isEmpty())
	{
		Stats.Valid = true;
		Stats.PidsCurrent = PidsCurrent.toULongLong();
		Stats.PidsMax = ParseCGroupLimit(ReadValue("pids.max"));
	}

	//
	// io.stat has one line per block device:
	//   8:0 rbytes=123 wbytes=456 rios=7 wios=8 dbytes=0 dios=0
	// Summed here, because which device did the I/O is not what this view is
	// about.
	//
	const QByteArray IoStat = ReadFile(CGroupFilePath(CGroupPath, "io.stat"));
	for (const QByteArray& Line : IoStat.split('\n'))
	{
		for (const QByteArray& Field : Line.simplified().split(' '))
		{
			if (Field.startsWith("rbytes="))
				Stats.IoReadBytes += Field.mid(7).toULongLong();
			else if (Field.startsWith("wbytes="))
				Stats.IoWriteBytes += Field.mid(7).toULongLong();
		}
	}

	Stats.Controllers = ReadValue("cgroup.controllers").split(' ', Qt::SkipEmptyParts);

	return Stats;
}

SNamespaces ReadNamespaces(quint64 Pid)
{
	SNamespaces Namespaces;

	//
	// Each link reads as "<type>:[<inode>]"; the inode is the namespace's
	// identity. Two processes share a namespace exactly when the inodes match.
	//
	auto ReadOne = [Pid](const char* Name) -> quint64 {
		const QString Link = ReadLink(ProcPath(Pid, QString("ns/%1").arg(Name)));
		const int Open = Link.indexOf('[');
		if (Open < 0 || !Link.endsWith(']'))
			return 0;
		return QStringView(Link).mid(Open + 1, Link.length() - Open - 2).toULongLong();
	};

	Namespaces.Pid = ReadOne("pid");
	Namespaces.Net = ReadOne("net");
	Namespaces.Mnt = ReadOne("mnt");
	Namespaces.User = ReadOne("user");
	Namespaces.Uts = ReadOne("uts");
	Namespaces.Ipc = ReadOne("ipc");
	Namespaces.CGroup = ReadOne("cgroup");
	Namespaces.Time = ReadOne("time");

	return Namespaces;
}

SProcSecurity ReadProcSecurity(quint64 Pid)
{
	SProcSecurity Security;

	const QMap<QString, QString> Status = ReadStatus(Pid);
	if (Status.isEmpty())
		return Security;

	Security.Valid = true;

	// The capability sets are hexadecimal masks, without a 0x prefix.
	Security.CapInh = Status.value("CapInh").trimmed().toULongLong(nullptr, 16);
	Security.CapPrm = Status.value("CapPrm").trimmed().toULongLong(nullptr, 16);
	Security.CapEff = Status.value("CapEff").trimmed().toULongLong(nullptr, 16);
	Security.CapBnd = Status.value("CapBnd").trimmed().toULongLong(nullptr, 16);
	Security.CapAmb = Status.value("CapAmb").trimmed().toULongLong(nullptr, 16);

	Security.Seccomp = Status.value("Seccomp").trimmed().toInt();
	Security.SeccompFilters = Status.value("Seccomp_filters").trimmed().toULongLong();
	Security.NoNewPrivs = Status.value("NoNewPrivs").trimmed().toInt() != 0;

	//
	// attr/current is the active LSM label. The file does not exist when no LSM
	// is compiled in, and reading it for another user's process needs the same
	// access as the rest of /proc.
	//
	// The value is NUL terminated rather than newline terminated, which trips
	// up naive readers.
	//
	QString Confinement = QString::fromUtf8(ReadFile(ProcPath(Pid, "attr/current")));
	const int Nul = Confinement.indexOf(QChar('\0'));
	if (Nul >= 0)
		Confinement.truncate(Nul);
	Security.Confinement = Confinement.trimmed();

	return Security;
}

QStringList DecodeCapabilities(quint64 Mask)
{
	//
	// Indexed by capability number, as defined in <linux/capability.h>. Listed
	// literally rather than pulled from the header so that a kernel newer than
	// the build machine's headers still names everything it reports.
	//
	static const char* Names[] = {
		"CAP_CHOWN", "CAP_DAC_OVERRIDE", "CAP_DAC_READ_SEARCH", "CAP_FOWNER",
		"CAP_FSETID", "CAP_KILL", "CAP_SETGID", "CAP_SETUID",
		"CAP_SETPCAP", "CAP_LINUX_IMMUTABLE", "CAP_NET_BIND_SERVICE", "CAP_NET_BROADCAST",
		"CAP_NET_ADMIN", "CAP_NET_RAW", "CAP_IPC_LOCK", "CAP_IPC_OWNER",
		"CAP_SYS_MODULE", "CAP_SYS_RAWIO", "CAP_SYS_CHROOT", "CAP_SYS_PTRACE",
		"CAP_SYS_PACCT", "CAP_SYS_ADMIN", "CAP_SYS_BOOT", "CAP_SYS_NICE",
		"CAP_SYS_RESOURCE", "CAP_SYS_TIME", "CAP_SYS_TTY_CONFIG", "CAP_MKNOD",
		"CAP_LEASE", "CAP_AUDIT_WRITE", "CAP_AUDIT_CONTROL", "CAP_SETFCAP",
		"CAP_MAC_OVERRIDE", "CAP_MAC_ADMIN", "CAP_SYSLOG", "CAP_WAKE_ALARM",
		"CAP_BLOCK_SUSPEND", "CAP_AUDIT_READ", "CAP_PERFMON", "CAP_BPF",
		"CAP_CHECKPOINT_RESTORE",
	};
	static const int Count = (int)(sizeof(Names) / sizeof(Names[0]));

	QStringList Capabilities;
	for (int i = 0; i < 64; i++)
	{
		if (!(Mask & (1ULL << i)))
			continue;

		if (i < Count)
			Capabilities.append(Names[i]);
		else
			Capabilities.append(QString("CAP_%1").arg(i));	// added since this table
	}

	return Capabilities;
}

QString SeccompModeToString(int Mode)
{
	switch (Mode)
	{
		case 0:		return QObject::tr("Disabled");
		case 1:		return QObject::tr("Strict");
		case 2:		return QObject::tr("Filtered");
		default:	return QObject::tr("Unknown (%1)").arg(Mode);
	}
}

SOomInfo ReadOomInfo(quint64 Pid)
{
	SOomInfo Info;

	const QString Score = ReadFileStr(ProcPath(Pid, "oom_score")).trimmed();
	if (Score.isEmpty())
		return Info;

	Info.Valid = true;
	Info.Score = Score.toInt();
	Info.ScoreAdj = ReadFileStr(ProcPath(Pid, "oom_score_adj")).trimmed().toInt();

	return Info;
}

bool WriteOomScoreAdj(quint64 Pid, int Value)
{
	//
	// Written with the raw syscalls rather than QFile.
	//
	// QFile buffers, so a write the kernel is going to refuse still reports the
	// full byte count; the refusal only surfaces when the buffer is flushed at
	// close, long after the caller has been told it succeeded. Lowering this
	// value needs CAP_SYS_RESOURCE, so that refusal is the normal case for an
	// unprivileged user and must not be swallowed.
	//
	// Going direct also keeps errno intact for the caller's error message.
	//
	const QByteArray Path = ProcPath(Pid, "oom_score_adj").toLocal8Bit();

	const int Fd = ::open(Path.constData(), O_WRONLY | O_CLOEXEC);
	if (Fd < 0)
		return false;

	const QByteArray Data = QByteArray::number(Value);
	const ssize_t Written = ::write(Fd, Data.constData(), Data.size());

	// Preserve the write's errno across close(), which can overwrite it.
	const int Error = errno;
	::close(Fd);
	errno = Error;

	return Written == (ssize_t)Data.size();
}

quint64 CountInotifyWatches(quint64 Pid)
{
	quint64 Watches = 0;

	//
	// An inotify descriptor's fdinfo lists one "inotify wd:..." line per watch,
	// so the watches are counted by counting those lines.
	//
	// Descriptors are filtered by their link target first. A readlink is a
	// single syscall, where opening and reading fdinfo for every descriptor of
	// every process would mean thousands of file reads per refresh to find the
	// handful of descriptors that are actually inotify ones.
	//
	foreach(quint64 Fd, EnumFds(Pid))
	{
		if (ReadLink(ProcPath(Pid, QString("fd/%1").arg(Fd))) != "anon_inode:inotify")
			continue;

		const QByteArray Data = ReadFile(ProcPath(Pid, QString("fdinfo/%1").arg(Fd)));
		for (const QByteArray& Line : Data.split('\n'))
		{
			if (Line.startsWith("inotify wd:"))
				Watches++;
		}
	}

	return Watches;
}

foreach(quint64 Fd, EnumFds(Pid))
	{
		if (ReadLink(ProcPath(Pid, QString("fd/%1").arg(Fd))) != "anon_inode:inotify")
			continue;

		const QByteArray Data = ReadFile(ProcPath(Pid, QString("fdinfo/%1").arg(Fd)));
		for (const QByteArray& Line : Data.split('\n'))
		{
			if (Line.startsWith("inotify wd:"))
				Watches++;
		}
	}

static quint32 TcpStateToMib(quint32 LinuxState)
{
	switch (LinuxState)
	{
		case LinuxTcpEstablished: return 5;
		case LinuxTcpSynSent:     return 3;
		case LinuxTcpSynRecv:     return 4;
		case LinuxTcpFinWait1:    return 6;
		case LinuxTcpFinWait2:    return 7;
		case LinuxTcpTimeWait:    return 11;
		case LinuxTcpClose:       return 1;
		case LinuxTcpCloseWait:   return 8;
		case LinuxTcpLastAck:     return 10;
		case LinuxTcpListen:      return 2;
		case LinuxTcpClosing:     return 9;
	}
	return 0;
}

static QHostAddress ToAddress(const __be32* pRaw, bool bIPv6)
{
	if (!bIPv6)
		return QHostAddress(qFromBigEndian<quint32>(pRaw[0]));

	quint8 Bytes[16];
	memcpy(Bytes, pRaw, 16);
	return QHostAddress(Bytes);
}

bool IsAvailable()
{
	//
	// Probed once. A dump of TCP over IPv4 is the cheapest representative
	// request; if the kernel accepts that it will accept the rest.
	//
	static const bool bAvailable = []() -> bool {
		QList<ProcFs::SNetConnection> Probe;
		return DumpOne(AF_INET, IPPROTO_TCP, Probe);
	}();
	return bAvailable;
}

QList<ProcFs::SNetConnection> Enumerate()
{
	QList<ProcFs::SNetConnection> Connections;

	bool bAnyOk = false;
	bAnyOk |= DumpOne(AF_INET,  IPPROTO_TCP, Connections);
	bAnyOk |= DumpOne(AF_INET6, IPPROTO_TCP, Connections);
	bAnyOk |= DumpOne(AF_INET,  IPPROTO_UDP, Connections);
	bAnyOk |= DumpOne(AF_INET6, IPPROTO_UDP, Connections);

	// An outright failure returns empty so the caller falls back to /proc/net,
	// rather than silently reporting that the machine has no sockets.
	if (!bAnyOk)
		Connections.clear();

	return Connections;
}

CUdevMonitor::CUdevMonitor(QObject* parent)
	: QObject(parent)
{
	m_Socket = -1;
	m_pNotifier = nullptr;
}

CUdevMonitor::~CUdevMonitor()
{
	if (m_pNotifier)
	{
		m_pNotifier->setEnabled(false);
		delete m_pNotifier;
		m_pNotifier = nullptr;
	}

	if (m_Socket != -1)
	{
		close(m_Socket);
		m_Socket = -1;
	}
}

bool CUdevMonitor::Init()
{
	if (m_Socket != -1)
		return true;

	const int Socket = socket(AF_NETLINK, SOCK_DGRAM | SOCK_CLOEXEC | SOCK_NONBLOCK, NETLINK_KOBJECT_UEVENT);
	if (Socket < 0)
		return false;

	//
	// A hotplug burst can outrun us; a larger receive buffer makes a dropped
	// event less likely. Failure is not fatal - the default size still works.
	//
	const int BufferSize = 256 * 1024;
	setsockopt(Socket, SOL_SOCKET, SO_RCVBUF, &BufferSize, sizeof(BufferSize));

	sockaddr_nl Address;
	memset(&Address, 0, sizeof(Address));
	Address.nl_family = AF_NETLINK;
	// nl_pid 0 lets the kernel assign one, so several instances can coexist.
	Address.nl_pid = 0;

	bool bBound = false;
	for (unsigned Group : { 1u, 2u })
	{
		Address.nl_groups = Group;
		if (bind(Socket, (sockaddr*)&Address, sizeof(Address)) == 0)
		{
			bBound = true;
			break;
		}
	}

	if (!bBound)
	{
		close(Socket);
		return false;
	}

	m_Socket = Socket;

	m_pNotifier = new QSocketNotifier(m_Socket, QSocketNotifier::Read, this);
	connect(m_pNotifier, SIGNAL(activated(QSocketDescriptor)), this, SLOT(OnReadyRead()));

	return true;
}

void CUdevMonitor::OnReadyRead()
{
	bool bRelevant = false;

	//
	// Drain everything queued. A single plug event produces one uevent per
	// device node involved, so this commonly reads several at once - hence one
	// signal at the end rather than one per message.
	//
	char Buffer[8192];
	for (;;)
	{
		const ssize_t Length = recv(m_Socket, Buffer, sizeof(Buffer), 0);
		if (Length <= 0)
			break; // EAGAIN: nothing left

		//
		// The payload is NUL-separated KEY=VALUE. Only the subsystem matters
		// here, and it is matched against the three the monitors enumerate.
		// Anything else - input devices, USB interfaces, power supplies - would
		// only cause pointless re-enumeration.
		//
		const char* pEnd = Buffer + Length;
		for (const char* p = Buffer; p < pEnd; p += strnlen(p, pEnd - p) + 1)
		{
			if (strncmp(p, "SUBSYSTEM=", 10) != 0)
				continue;

			const char* pSubsystem = p + 10;
			if (strcmp(pSubsystem, "block") == 0 ||
			    strcmp(pSubsystem, "net") == 0 ||
			    strcmp(pSubsystem, "drm") == 0)
			{
				bRelevant = true;
			}
			break; // one SUBSYSTEM per message
		}
	}

	if (bRelevant)
		emit HardwareChanged();
}

static quint64 QueryPidViaXRes(quint64 WindowId)
{
	struct SXRes
	{
		Bool	(*QueryExtension)(Display*, int*, int*) = nullptr;
		Status	(*QueryVersion)(Display*, int*, int*) = nullptr;
		Status	(*QueryClientIds)(Display*, long, XResClientIdSpec*, long*, XResClientIdValue**) = nullptr;
		pid_t	(*GetClientPid)(XResClientIdValue*) = nullptr;
		void	(*IdsDestroy)(long, XResClientIdValue*) = nullptr;
		bool	bUsable = false;
	};

	// Resolved once; the result, including "not available", is cached.
	static const SXRes XRes = []() -> SXRes {
		SXRes Result;

		Display* pDisplay = GetDisplay();
		if (!pDisplay)
			return Result;

		void* pLib = dlopen("libXRes.so.1", RTLD_LAZY | RTLD_LOCAL);
		if (!pLib)
			return Result;

		*(void**)&Result.QueryExtension = dlsym(pLib, "XResQueryExtension");
		*(void**)&Result.QueryVersion = dlsym(pLib, "XResQueryVersion");
		*(void**)&Result.QueryClientIds = dlsym(pLib, "XResQueryClientIds");
		*(void**)&Result.GetClientPid = dlsym(pLib, "XResGetClientPid");
		*(void**)&Result.IdsDestroy = dlsym(pLib, "XResClientIdsDestroy");

		if (!Result.QueryExtension || !Result.QueryVersion || !Result.QueryClientIds
			|| !Result.GetClientPid || !Result.IdsDestroy)
			return Result;

		int EventBase = 0, ErrorBase = 0;
		if (!Result.QueryExtension(pDisplay, &EventBase, &ErrorBase))
			return Result;

		// QueryClientIds arrived in 1.2; earlier servers only report aggregate
		// resource usage, which cannot answer this question.
		int Major = 0, Minor = 0;
		if (!Result.QueryVersion(pDisplay, &Major, &Minor))
			return Result;
		if (Major < 1 || (Major == 1 && Minor < 2))
			return Result;

		Result.bUsable = true;
		return Result;
	}();

	if (!XRes.bUsable)
		return 0;

	Display* pDisplay = GetDisplay();
	if (!pDisplay)
		return 0;

	//
	// Any XID owned by the client identifies it - the server masks the id down
	// to the client's base - so the window itself is a valid specification.
	//
	XResClientIdSpec Spec;
	Spec.client = (XID)WindowId;
	Spec.mask = XRES_LOCAL_CLIENT_PID_MASK;

	long Count = 0;
	XResClientIdValue* pValues = nullptr;
	if (XRes.QueryClientIds(pDisplay, 1, &Spec, &Count, &pValues) != Success)
		return 0;

	quint64 Pid = 0;
	for (long i = 0; i < Count && !Pid; i++)
	{
		const pid_t Value = XRes.GetClientPid(&pValues[i]);
		// A remote client has no local pid, and the server reports -1.
		if (Value > 0)
			Pid = (quint64)Value;
	}

	if (pValues)
		XRes.IdsDestroy(Count, pValues);

	return Pid;
}

static Display* GetDisplay()
{
	static Display* pDisplay = []() -> Display* {
		// Honours $DISPLAY; returns null under a pure Wayland session with no
		// XWayland, which is the correct "no windows visible" answer.
		return XOpenDisplay(nullptr);
	}();
	return pDisplay;
}

static Atom GetAtom(const char* Name)
{
	Display* pDisplay = GetDisplay();
	if (!pDisplay)
		return None;
	return XInternAtom(pDisplay, Name, False);
}

static unsigned char* GetProperty(quint64 WindowId, Atom Property, Atom Type,
                                  unsigned long* pCount, int* pFormat = nullptr)
{
	Display* pDisplay = GetDisplay();
	if (!pDisplay || Property == None)
		return nullptr;

	Atom ActualType = None;
	int ActualFormat = 0;
	unsigned long Count = 0;
	unsigned long BytesAfter = 0;
	unsigned char* pData = nullptr;

	// Errors here are routine - windows disappear between enumeration and read.
	if (XGetWindowProperty(pDisplay, (::Window)WindowId, Property, 0, (~0L), False, Type,
	                       &ActualType, &ActualFormat, &Count, &BytesAfter, &pData) != Success)
		return nullptr;

	if (!pData)
		return nullptr;

	if (ActualType == None || Count == 0)
	{
		XFree(pData);
		return nullptr;
	}

	if (pCount)
		*pCount = Count;
	if (pFormat)
		*pFormat = ActualFormat;
	return pData;
}

static QString GetStringProperty(quint64 WindowId, const char* Name)
{
	unsigned long Count = 0;
	// AnyPropertyType, because _NET_WM_NAME is UTF8_STRING while the legacy
	// WM_NAME is STRING.
	unsigned char* pData = GetProperty(WindowId, GetAtom(Name), AnyPropertyType, &Count);
	if (!pData)
		return QString();

	const QString Value = QString::fromUtf8((const char*)pData, (int)Count);
	XFree(pData);
	return Value;
}

static quint64 GetCardinalProperty(quint64 WindowId, const char* Name, bool* pFound = nullptr)
{
	if (pFound)
		*pFound = false;

	unsigned long Count = 0;
	unsigned char* pData = GetProperty(WindowId, GetAtom(Name), XA_CARDINAL, &Count);
	if (!pData)
		return 0;

	// 32 bit properties come back as long, not quint32.
	const quint64 Value = (quint64)(*(unsigned long*)pData);
	XFree(pData);

	if (pFound)
		*pFound = true;
	return Value;
}

static QList<Atom> GetAtomListProperty(quint64 WindowId, const char* Name)
{
	QList<Atom> Atoms;

	unsigned long Count = 0;
	unsigned char* pData = GetProperty(WindowId, GetAtom(Name), XA_ATOM, &Count);
	if (!pData)
		return Atoms;

	const unsigned long* pValues = (const unsigned long*)pData;
	for (unsigned long i = 0; i < Count; i++)
		Atoms.append((Atom)pValues[i]);

	XFree(pData);
	return Atoms;
}

static bool SendRootMessage(quint64 WindowId, const char* MessageType,
                            long Data0 = 0, long Data1 = 0, long Data2 = 0)
{
	Display* pDisplay = GetDisplay();
	if (!pDisplay)
		return false;

	const Atom Type = GetAtom(MessageType);
	if (Type == None)
		return false;

	XEvent Event;
	memset(&Event, 0, sizeof(Event));
	Event.xclient.type = ClientMessage;
	Event.xclient.window = (::Window)WindowId;
	Event.xclient.message_type = Type;
	Event.xclient.format = 32;
	Event.xclient.data.l[0] = Data0;
	Event.xclient.data.l[1] = Data1;
	Event.xclient.data.l[2] = Data2;
	// Source indication: 2 means "a pager or task manager", which window
	// managers honour without the focus-stealing-prevention heuristics they
	// apply to ordinary applications.
	Event.xclient.data.l[3] = 2;

	const bool bOk = XSendEvent(pDisplay, DefaultRootWindow(pDisplay), False,
	                            SubstructureNotifyMask | SubstructureRedirectMask, &Event) != 0;
	XFlush(pDisplay);
	return bOk;
}

static void FillState(quint64 WindowId, SWindow& Info)
{
	const Atom Hidden = GetAtom("_NET_WM_STATE_HIDDEN");
	const Atom MaxHorz = GetAtom("_NET_WM_STATE_MAXIMIZED_HORZ");
	const Atom MaxVert = GetAtom("_NET_WM_STATE_MAXIMIZED_VERT");
	const Atom AtomAbove = GetAtom("_NET_WM_STATE_ABOVE");

	bool bMaxHorz = false, bMaxVert = false;
	for (Atom State : GetAtomListProperty(WindowId, "_NET_WM_STATE"))
	{
		if (State == Hidden)  Info.Minimized = true;
		if (State == MaxHorz) bMaxHorz = true;
		if (State == MaxVert) bMaxVert = true;
		if (State == AtomAbove) Info.AlwaysOnTop = true;
	}
	Info.Maximized = bMaxHorz && bMaxVert;

	//
	// _NET_WM_WINDOW_OPACITY is a 32 bit cardinal where 0xFFFFFFFF is opaque.
	// An absent property also means opaque.
	//
	bool bFound = false;
	const quint64 Opacity = GetCardinalProperty(WindowId, "_NET_WM_WINDOW_OPACITY", &bFound);
	Info.Alpha = bFound ? (int)((Opacity & 0xFFFFFFFFu) * 255 / 0xFFFFFFFFu) : 255;
}

bool QueryWindow(quint64 WindowId, SWindow& Info)
{
	Display* pDisplay = GetDisplay();
	if (!pDisplay)
		return false;

	XWindowAttributes Attributes;
	if (!XGetWindowAttributes(pDisplay, (::Window)WindowId, &Attributes))
		return false; // gone

	Info.Window = WindowId;

	//
	// _NET_WM_PID first, since it costs one property read and nearly every
	// modern toolkit sets it. Ask the X server itself only when the client did
	// not - see QueryPidViaXRes.
	//
	Info.ProcessId = GetCardinalProperty(WindowId, "_NET_WM_PID");
	if (!Info.ProcessId)
		Info.ProcessId = QueryPidViaXRes(WindowId);

	// _NET_WM_NAME is the UTF-8 modern one; WM_NAME is the latin-1 fallback
	// that older toolkits still set.
	Info.Title = GetStringProperty(WindowId, "_NET_WM_NAME");
	if (Info.Title.isEmpty())
		Info.Title = GetStringProperty(WindowId, "WM_NAME");

	//
	// WM_CLASS is two consecutive NUL terminated strings: instance then class.
	// The class is the more useful of the two for identification.
	//
	const QString WmClass = GetStringProperty(WindowId, "WM_CLASS");
	if (!WmClass.isEmpty())
	{
		const QStringList Parts = WmClass.split(QChar('\0'), Qt::SkipEmptyParts);
		Info.WindowClass = Parts.value(Parts.size() > 1 ? 1 : 0);
	}

	FillState(WindowId, Info);

	// IsViewable means mapped and all ancestors mapped. A minimized window is
	// still "managed" but not viewable.
	Info.Visible = (Attributes.map_state == IsViewable) && !Info.Minimized;

	::Window Root = 0, Parent = 0, *pChildren = nullptr;
	unsigned int ChildCount = 0;
	if (XQueryTree(pDisplay, (::Window)WindowId, &Root, &Parent, &pChildren, &ChildCount))
	{
		Info.ParentWindow = (quint64)Parent;
		if (pChildren)
			XFree(pChildren);
	}

	return true;
}

QList<SWindow> EnumWindows()
{
	QList<SWindow> Windows;

	Display* pDisplay = GetDisplay();
	if (!pDisplay)
		return Windows;

	//
	// _NET_CLIENT_LIST_STACKING is in stacking order (bottom to top);
	// _NET_CLIENT_LIST is in initial mapping order. Either is fine, but the
	// stacking one is preferred and some window managers only set one.
	//
	unsigned long Count = 0;
	unsigned char* pData = GetProperty((quint64)DefaultRootWindow(pDisplay),
	                                   GetAtom("_NET_CLIENT_LIST_STACKING"), XA_WINDOW, &Count);
	if (!pData)
	{
		pData = GetProperty((quint64)DefaultRootWindow(pDisplay),
		                    GetAtom("_NET_CLIENT_LIST"), XA_WINDOW, &Count);
	}
	if (!pData)
		return Windows; // no EWMH compliant window manager running

	const unsigned long* pWindows = (const unsigned long*)pData;
	for (unsigned long i = 0; i < Count; i++)
	{
		SWindow Info;
		if (QueryWindow((quint64)pWindows[i], Info))
			Windows.append(Info);
	}

	XFree(pData);
	return Windows;
}

bool Activate(quint64 WindowId)
{
	Display* pDisplay = GetDisplay();
	if (!pDisplay)
		return false;

	// Raising as well as activating, because a WM that declines the activation
	// may still honour the restack.
	XRaiseWindow(pDisplay, (::Window)WindowId);
	return SendRootMessage(WindowId, "_NET_ACTIVE_WINDOW", 2, CurrentTime, 0);
}

bool Close(quint64 WindowId)
{
	// Asks the window manager to close it, which lets the application run its
	// own shutdown path rather than having the connection killed.
	return SendRootMessage(WindowId, "_NET_CLOSE_WINDOW", CurrentTime, 2, 0);
}

static bool SetState(quint64 WindowId, bool bSet, const char* State1, const char* State2 = nullptr)
{
	const Atom Atom1 = GetAtom(State1);
	const Atom Atom2 = State2 ? GetAtom(State2) : None;
	if (Atom1 == None)
		return false;

	return SendRootMessage(WindowId, "_NET_WM_STATE", bSet ? 1 : 0, (long)Atom1, (long)Atom2);
}

bool SetMinimized(quint64 WindowId, bool bSet)
{
	Display* pDisplay = GetDisplay();
	if (!pDisplay)
		return false;

	if (bSet)
	{
		//
		// There is no _NET_WM_STATE_HIDDEN request - the hint is set by the
		// window manager to report state, not to change it. Iconifying is the
		// supported way to minimize.
		//
		return XIconifyWindow(pDisplay, (::Window)WindowId, DefaultScreen(pDisplay)) != 0;
	}

	// Restoring is just activating it again.
	return Activate(WindowId);
}

bool SetVisible(quint64 WindowId, bool bSet)
{
	Display* pDisplay = GetDisplay();
	if (!pDisplay)
		return false;

	//
	// Unmapping a window behind the window manager's back is not really
	// supported by EWMH, but it is what a task manager's "hide" does and the
	// window can be mapped again.
	//
	if (bSet)
		XMapWindow(pDisplay, (::Window)WindowId);
	else
		XUnmapWindow(pDisplay, (::Window)WindowId);

	XFlush(pDisplay);
	return true;
}

bool SetOpacity(quint64 WindowId, int Alpha)
{
	Display* pDisplay = GetDisplay();
	if (!pDisplay)
		return false;

	const Atom Property = GetAtom("_NET_WM_WINDOW_OPACITY");
	if (Property == None)
		return false;

	//
	// Requires a compositing manager to have any visible effect; without one
	// the property is set and simply ignored.
	//
	const unsigned long Opacity = (unsigned long)((double)qBound(0, Alpha, 255) / 255.0 * 0xFFFFFFFFu);
	XChangeProperty(pDisplay, (::Window)WindowId, Property, XA_CARDINAL, 32, PropModeReplace,
	                (unsigned char*)&Opacity, 1);
	XFlush(pDisplay);
	return true;
}

bool Highlight(quint64 WindowId)
{
	Display* pDisplay = GetDisplay();
	if (!pDisplay)
		return false;

	XWindowAttributes Attributes;
	if (!XGetWindowAttributes(pDisplay, (::Window)WindowId, &Attributes))
		return false;

	//
	// Draws directly on the root window with an inverting GC, twice, so the
	// frame appears and is then erased - the same trick Windows' own window
	// finder uses. Nothing is left behind.
	//
	::Window Root = DefaultRootWindow(pDisplay);
	int X = 0, Y = 0;
	::Window Child = 0;
	XTranslateCoordinates(pDisplay, (::Window)WindowId, Root, 0, 0, &X, &Y, &Child);

	XGCValues Values;
	Values.function = GXinvert;
	Values.subwindow_mode = IncludeInferiors;
	Values.line_width = 4;
	GC Gc = XCreateGC(pDisplay, Root, GCFunction | GCSubwindowMode | GCLineWidth, &Values);
	if (!Gc)
		return false;

	for (int i = 0; i < 2; i++)
	{
		XDrawRectangle(pDisplay, Root, Gc, X, Y, Attributes.width, Attributes.height);
		XFlush(pDisplay);
		QThread::msleep(120);
	}

	XFreeGC(pDisplay, Gc);
	XFlush(pDisplay);
	return true;
}

CGraphBar::CGraphBar()
{
	m_Rows = 0;

	this->setMinimumHeight(50);
	//this->setMaximumHeight(200);

	m_pMainLayout = new QGridLayout();
	this->setLayout(m_pMainLayout);

	m_pMainLayout->setContentsMargins(1,1,1,1);
	m_pMainLayout->setSpacing(2);

	QPalette pal = palette();
	pal.setColor(QPalette::Window, Qt::gray);
	this->setAutoFillBackground(true);
	this->setPalette(pal);


	m_pMenu = new QMenu();
	m_pResetPlot = m_pMenu->addAction(tr("Reset Plot"), this, SLOT(ClearGraphs()));
	m_pResetAll = m_pMenu->addAction(tr("Reset All Plots"), this, SLOT(ClearGraphs()));
	m_pCustomize = m_pMenu->addAction(tr("Customize Plots"), this, SLOT(CustomizeGraphs()));
	// Restores the layout, as opposed to the two entries above which only clear
	// the plotted history.
	m_pRestoreDefaults = m_pMenu->addAction(tr("Restore Default Plots"), this, SLOT(RestoreDefaultGraphs()));

	m_pLastTipGraph = NULL;


	int Rows = theConf->GetInt("Options/GraphRows", 2);
	QList<EGraph> Graphs;
	QStringList GraphList = theConf->GetStringList("Options/Graphs");
	if (GraphList.isEmpty())
		Graphs = GetDefaultGraphs();
	else
	{
		foreach(const QString& Graph, GraphList)
			Graphs.append((EGraph)Graph.toInt());
	}

	m_PlotLimit = theGUI->GetGraphLimit();
	connect(theGUI, SIGNAL(ReloadPlots()), this, SLOT(ReConfigurePlots()));

	AddGraphs(Graphs, Rows);
}

void CGraphBar::SaveGraphs()
{
	QStringList GraphList;
	foreach(const SGraph& Graph, m_Graphs)
		GraphList.append(QString::number(Graph.Type));
	theConf->SetValue("Options/GraphRows", m_Rows);
	theConf->SetValue("Options/Graphs", GraphList);
}

QList<CGraphBar::EGraph> CGraphBar::GetDefaultGraphs()
{
	QList<EGraph> Graphs;

	Graphs.append(eGpuMemPlot);
	Graphs.append(eMemoryPlot);
#ifdef WIN32
	Graphs.append(eObjectPlot);
	Graphs.append(eWindowsPlot);
#else
	//
	// The GDI/User object and window-object plots have no Linux counterpart and
	// would render as two permanently empty boxes, so the slot goes to the
	// pressure plot instead.
	//
	Graphs.append(ePressurePlot);
#endif
	Graphs.append(eHandledPlot);
	Graphs.append(eDiskIoPlot);
	Graphs.append(eMMapIoPlot);
	Graphs.append(eFileIoPlot);
#ifdef WIN32
	//Graphs.append(eSambaPlot);
	// The Samba and RAS counters come from Windows-specific providers, so on
	// Linux these three would sit at zero for ever.
	Graphs.append(eClientPlot);
	Graphs.append(eServerPlot);
	Graphs.append(eRasPlot);
#endif
	Graphs.append(eNetworkPlot);
	Graphs.append(eGpuPlot);
	Graphs.append(eCpuPlot);

	return Graphs;
}

void CGraphBar::RestoreDefaultGraphs()
{
	DeleteGraphs();
	AddGraphs(GetDefaultGraphs(), 2);

	//
	// Written out now rather than left to the destructor. The layout is
	// otherwise only saved on a clean shutdown, so restoring the defaults and
	// then having the process killed would silently lose the change - which is
	// exactly the state this action exists to get out of.
	//
	SaveGraphs();
}

void CGraphBar::AddGraphs(QList<EGraph> Graphs, int Rows)
{
	m_Rows = Rows;

	int Count = Graphs.count();
	int Columns = Count / Rows + (Count % Rows ? 1 : 0);

	for (int row = 0; row < Rows; row++)
	{
		for (int column = 0; column < Columns; column++)
		{
			int index = row * Columns + column;
			if (index >= Graphs.count())
				break;

			AddGraph(Graphs.at(index), row, column);
		}
	}

	emit Resized(m_Rows * 40);
}

void CGraphBar::ReConfigurePlots()
{
	m_PlotLimit = theGUI->GetGraphLimit();
	QColor Back = theGUI->GetColor(CTaskExplorer::eGraphBack);
	if (theGUI->GetTheme()->IsDarkTheme())
		Back = Qt::black;
	QColor Front = theGUI->GetColor(CTaskExplorer::eGraphFront);

	foreach(const SGraph& Graph, m_Graphs) {
		Graph.pPlot->SetLimit(m_PlotLimit);
		Graph.pPlot->SetColors(Back);
		Graph.pPlot->SetTextColor(Front);
	}
}

foreach(const SGraph& Graph, m_Graphs) {
		Graph.pPlot->SetLimit(m_PlotLimit);
		Graph.pPlot->SetColors(Back);
		Graph.pPlot->SetTextColor(Front);
	}

void CGraphBar::SetDarkMode(bool bDark)
{
	QPalette pal = palette();
	pal.setColor(QPalette::Window, bDark ? Qt::darkGray : Qt::gray);
	this->setPalette(pal);

	QColor Back = theGUI->GetColor(CTaskExplorer::eGraphBack);
	if (theGUI->GetTheme()->IsDarkTheme())
		Back = Qt::black;

	foreach(const SGraph& Graph, m_Graphs)
		Graph.pPlot->SetColors(Back);
}

void CGraphBar::AddGraph(EGraph Graph, int row, int column)
{
	QColor Back = theGUI->GetColor(CTaskExplorer::eGraphBack);
	QColor Front = theGUI->GetColor(CTaskExplorer::eGraphFront);

	CIncrementalPlot* pPlot = new CIncrementalPlot(Back);

	pPlot->SetLimit(m_PlotLimit);
	pPlot->SetTextColor(Front);

	switch (Graph)
	{
	case eMemoryPlot:
		pPlot->AddPlot("Commited", Qt::green, Qt::SolidLine, true);
		pPlot->AddPlot("Swapped", Qt::red, Qt::SolidLine, true);
		pPlot->AddPlot("Cache", Qt::blue, Qt::SolidLine, true);
		pPlot->AddPlot("Physical", Qt::yellow, Qt::SolidLine, true);
		pPlot->AddPlot("Limit", Qt::white, Qt::SolidLine);
		break;
	case eGpuMemPlot:
	{
		pPlot->SetRagne(100);
		pPlot->AddPlot("Dedicated", Qt::green, Qt::SolidLine, true);
		pPlot->AddPlot("Shared", Qt::red, Qt::SolidLine, true);
		break;
	}
	case eObjectPlot:
#ifdef WIN32
		pPlot->AddPlot("Gdi", Qt::green, Qt::SolidLine);
		pPlot->AddPlot("User", Qt::red, Qt::SolidLine);
#endif
		break;
	case eWindowsPlot:
#ifdef WIN32
		pPlot->AddPlot("Wnd", Qt::green, Qt::SolidLine);
#endif
		break;
#ifndef WIN32
	case ePressurePlot:
		//
		// All three are percentages of a 10 second window, so they share one
		// fixed 0..100 scale rather than autoscaling - the absolute level is
		// the point, and a rescaling axis would make 0.5% look alarming.
		//
		pPlot->SetRagne(100);
		pPlot->AddPlot("CPU", Qt::green, Qt::SolidLine);
		pPlot->AddPlot("Memory", Qt::red, Qt::SolidLine);
		pPlot->AddPlot("IO", Qt::blue, Qt::SolidLine);
		break;
#endif
	case eHandledPlot:
		pPlot->AddPlot("Handles", Qt::green, Qt::SolidLine);
		break;
	case eDiskIoPlot:
		pPlot->AddPlot("Read", Qt::green, Qt::SolidLine);
		pPlot->AddPlot("Write", Qt::red, Qt::SolidLine);
		break;
	case eMMapIoPlot:
		pPlot->AddPlot("Read", Qt::green, Qt::SolidLine);
		pPlot->AddPlot("Write", Qt::red, Qt::SolidLine);
		break;
	case eFileIoPlot:
		pPlot->AddPlot("Read", Qt::green, Qt::SolidLine);
		pPlot->AddPlot("Write", Qt::red, Qt::SolidLine);
#ifdef WIN32
		// "Other" counts operations that are neither reads nor writes; Linux
		// keeps no such tally, so the line would be flat at zero for ever.
		pPlot->AddPlot("Other", Qt::blue, Qt::SolidLine);
#endif
		break;
	case eSambaPlot:
		pPlot->AddPlot("RecvTotal", Qt::green, Qt::SolidLine);
		pPlot->AddPlot("SentTotal", Qt::red, Qt::SolidLine);
		pPlot->AddPlot("RecvServer", Qt::green, Qt::DashLine);
		pPlot->AddPlot("SentServer", Qt::red, Qt::DashLine);
		pPlot->AddPlot("RecvClient", Qt::green, Qt::DotLine);
		pPlot->AddPlot("SentClient", Qt::red, Qt::DotLine);
		break;
	case eClientPlot:
		pPlot->AddPlot("RecvClient", Qt::green, Qt::SolidLine);
		pPlot->AddPlot("SentClient", Qt::red, Qt::SolidLine);
		break;
	case eServerPlot:
		pPlot->AddPlot("RecvServer", Qt::green, Qt::SolidLine);
		pPlot->AddPlot("SentServer", Qt::red, Qt::SolidLine);
		break;
	case eRasPlot:
		pPlot->AddPlot("Recv", Qt::green, Qt::SolidLine);
		pPlot->AddPlot("Send", Qt::red, Qt::SolidLine);
		break;
	case eNetworkPlot:
		pPlot->AddPlot("Recv", Qt::green, Qt::SolidLine);
		pPlot->AddPlot("Send", Qt::red, Qt::SolidLine);
		pPlot->AddPlot("RecvL", Qt::blue, Qt::SolidLine);
		pPlot->AddPlot("SendL", Qt::yellow, Qt::SolidLine);
		break;
	case eGpuPlot:
		pPlot->SetRagne(100);
		break;
	case eCpuPlot:
		pPlot->SetRagne(100);
		pPlot->AddPlot("User", Qt::green, Qt::SolidLine, true);
		pPlot->AddPlot("Kernel", Qt::red, Qt::SolidLine, true);
		pPlot->AddPlot("DPC", Qt::blue, Qt::SolidLine, true);
		break;
	}

	FixPlotScale(pPlot);

	SGraph GraphData;
	GraphData.Type = Graph;
	GraphData.pPlot = pPlot;
	m_Graphs.append(GraphData);

	m_pMainLayout->addWidget(pPlot, row, column);

	pPlot->setContextMenuPolicy(Qt::CustomContextMenu);
	connect(pPlot, SIGNAL(customContextMenuRequested(const QPoint&)), this, SLOT(OnMenu(const QPoint &)));

	//connect(pPlot, SIGNAL(Entered()), this, SLOT(OnEntered()));
	//connect(pPlot, SIGNAL(Moveed(QMouseEvent*)), this, SLOT(OnMoveed(QMouseEvent*)));
	//connect(pPlot, SIGNAL(Exited()), this, SLOT(OnExited()));

	connect(pPlot, SIGNAL(ToolTipRequested(QEvent*)), this, SLOT(OnToolTipRequested(QEvent*)));
}

void CGraphBar::DeleteGraphs()
{
	foreach(const SGraph& Graph, m_Graphs)
		delete Graph.pPlot;
	m_Graphs.clear();
}

void CGraphBar::FixPlotScale(CIncrementalPlot* pPlot)
{
	// add a dummy curve that always stays at 0 in order to force autoscale to keep the lower bound always at 0
	pPlot->AddPlot("end", Qt::transparent, Qt::NoPen);
	pPlot->AddPlotPoint("end", 0.1);
	pPlot->AddPlotPoint("end", 0.0);
}

foreach(const CDiskMonitor::SDiskInfo& Disk, DiskList)
					{
						if (!Disk.DeviceSupported)
							continue;

						pPlot->AddPlot("Disk_" + QString::number(DiskPlotCount), Colors[DiskPlotCount % Colors.size()], Qt::SolidLine, true);
						DiskPlotCount++;
					}

foreach(const CDiskMonitor::SDiskInfo& Disk, DiskList)
				{
					if (!Disk.DeviceSupported)
						continue;

					int DiskUsage = Disk.ActiveTime;
					Texts.append(tr("%1%").arg(DiskUsage));
					pPlot->AddPlotPoint("Disk_" + QString::number(i), DiskUsage);
					if (DiskUsage > MaxDiskUsage)
						MaxDiskUsage = DiskUsage;
					i++;
				}

foreach(const CGpuMonitor::SGpuInfo &GpuInfo, GpuList)
				{
					pPlot->AddPlot("Gpu_" + QString::number(GpuPlotCount), Colors[GpuPlotCount % Colors.size()], Qt::SolidLine, true);
					GpuPlotCount++;
				}

foreach(const CGpuMonitor::SGpuInfo &GpuInfo, GpuList)
			{
				int GpuUsage = 100 * GpuInfo.TimeUsage;
				Texts.append(tr("%1%").arg(GpuUsage));
				pPlot->AddPlotPoint("Gpu_" + QString::number(i), GpuUsage);
				if (GpuUsage > MaxGpuUsage)
					MaxGpuUsage = GpuUsage;
				i++;
			}

void CGraphBar::OnMenu(const QPoint& Point)
{
	m_pCurPlot = qobject_cast<CIncrementalPlot*>(sender());
	m_pMenu->popup(QCursor::pos());	
}

void CGraphBar::ClearGraphs()
{
	if (sender() == m_pResetPlot)
	{
		if (m_pCurPlot)
		{
			m_pCurPlot->Reset();
			FixPlotScale(m_pCurPlot);
		}
	}
	else
	{
		foreach(const SGraph& Graph, m_Graphs)
		{
			Graph.pPlot->Reset();
			FixPlotScale(Graph.pPlot);
		}
	}
}

foreach(const SGraph& Graph, m_Graphs)
		{
			Graph.pPlot->Reset();
			FixPlotScale(Graph.pPlot);
		}

void CGraphBar::CustomizeGraphs()
{
	QWidget* pWidget = new QWidget();
	QHBoxLayout* pLayout = new QHBoxLayout();
	pWidget->setLayout(pLayout);
	pLayout->addWidget(new QLabel(tr("Graph Rows")));
	QSpinBox* pRows = new QSpinBox();
	pLayout->addWidget(pRows);
	pLayout->addItem(new QSpacerItem(10, 10, QSizePolicy::Expanding, QSizePolicy::Minimum));

	pRows->setMaximum(1);
	pRows->setMaximum(4);
	pRows->setValue(m_Rows);

	CItemChooser ItemChooser(tr("Select graphs that will be displayed in the graph bar."));
	ItemChooser.setWindowTitle(tr("Graph Chooser"));
	ItemChooser.AddWidget(pWidget);

	ItemChooser.AddItem(tr("GPU Memory"), eGpuMemPlot);
	ItemChooser.AddItem(tr("System Memory"), eMemoryPlot);
#ifdef WIN32
	// Both plot Windows kernel object counts, which do not exist on Linux;
	// offering them would only let the user add an empty box.
	ItemChooser.AddItem(tr("Object Usage"), eObjectPlot);
	ItemChooser.AddItem(tr("Window Usage"), eWindowsPlot);
#else
	ItemChooser.AddItem(tr("Pressure (PSI)"), ePressurePlot);
#endif
	ItemChooser.AddItem(tr("Handle Usage"), eHandledPlot);
	ItemChooser.AddItem(tr("Disk I/O"), eDiskIoPlot);
	ItemChooser.AddItem(tr("Memory Mapped I/O"), eMMapIoPlot);
	ItemChooser.AddItem(tr("File I/O"), eFileIoPlot);
#ifdef WIN32
	// Samba and RAS/VPN counters come from Windows-specific providers.
	ItemChooser.AddItem(tr("Samba Combined U/D"), eSambaPlot);
	ItemChooser.AddItem(tr("Samba Client U/D"), eClientPlot);
	ItemChooser.AddItem(tr("Samba Server U/D"), eServerPlot);
	ItemChooser.AddItem(tr("RAS / VPN"), eRasPlot);
#endif
	ItemChooser.AddItem(tr("Network U/D"), eNetworkPlot);
	ItemChooser.AddItem(tr("GPU Usage"), eGpuPlot);
	ItemChooser.AddItem(tr("CPU Usage"), eCpuPlot);

	QVariantList ChoosenItems;
	foreach(const SGraph& Graph, m_Graphs)
		ChoosenItems.append(Graph.Type);
	ItemChooser.ChooseItems(ChoosenItems);

	if (!ItemChooser.exec())
		return;

	DeleteGraphs();

	QList<EGraph> Graphs;
	foreach(const QVariant& Data, ItemChooser.GetChoosenItems())
		Graphs.append((EGraph)Data.toInt());
	AddGraphs(Graphs, pRows->value());
}

foreach(const SGraph& Graph, m_Graphs)
	{
		if (Graph.pPlot == m_pLastTipGraph)
		{
			Type = Graph.Type;
			Params = Graph.Params;
			break;
		}
	}

foreach(const CGpuMonitor::SGpuInfo &GpuInfo, GpuList)
		{
			TextLines.append(tr("%1 Memory Usage:").arg(GpuInfo.Description));
			TextLines.append(tr("    Dedicated memory: %1/%2").arg(FormatSize(GpuInfo.Memory.DedicatedUsage)).arg(FormatSize(GpuInfo.Memory.DedicatedLimit)));
			TextLines.append(tr("    Shared memory: %1/%2").arg(FormatSize(GpuInfo.Memory.SharedUsage)).arg(FormatSize(GpuInfo.Memory.SharedLimit)));

		}

CServiceModel::CServiceModel(QObject *parent)
:CListItemModel(parent)
{
#ifdef WIN32
	m_ShowDriver = true;
#endif
	m_bUseIcons = true;
}

foreach (const CServicePtr& pService, ServiceList)
	{
#ifdef WIN32
		CWinService* pWinService = qobject_cast<CWinService*>(pService.data());

		if (!m_ShowDriver && pWinService->IsDriver())
			continue;
#else
		CLinuxService* pLinuxService = qobject_cast<CLinuxService*>(pService.data());
#endif

		QVariant ID = pService->GetName();

		int Row = -1;
		QHash<QVariant, SListNode*>::iterator I = Old.find(ID);
		SServiceNode* pNode = I != Old.end() ? static_cast<SServiceNode*>(I.value()) : NULL;
		if(!pNode)
		{
			pNode = static_cast<SServiceNode*>(MkNode(ID));
			pNode->Values.resize(columnCount());
			pNode->pService = pService;
			New.append(pNode);
		}
		else
		{
			I.value() = NULL;
			Row = GetRow(pNode);
		}

		int Col = 0;
		bool State = false;
		int Changed = 0;

		CModulePtr pModule = pService->GetModuleInfo();
#ifdef WIN32
		QSharedPointer<CWinModule> pWinModule = pModule.staticCast<CWinModule>();
#endif

		// Note: icons are loaded asynchroniusly
#ifdef WIN32
		if (m_bUseIcons && !pNode->Icon.isValid() && !m_ColumnsOff.contains(eService))
		{
			QPixmap Icon;
			if (pWinService->IsDriver())
				Icon = g_DllIcon.pixmap(16, 16);
			else if (pModule)
				Icon = pModule->GetFileIcon(); 

			if (!Icon.isNull()) {
				Changed = 1; // set change for first column
				pNode->Icon = Icon;
			}
		}
#endif

		int RowColor = CTaskExplorer::eNone;
		if (pService->IsMarkedForRemoval() && CTaskExplorer::UseListColor(CTaskExplorer::eToBeRemoved))		RowColor = CTaskExplorer::eToBeRemoved;
		else if (pService->IsNewlyCreated() && CTaskExplorer::UseListColor(CTaskExplorer::eAdded))			RowColor = CTaskExplorer::eAdded;
#ifdef WIN32
		else if (pWinService->IsDriver() && CTaskExplorer::UseListColor(CTaskExplorer::eDriver))			RowColor = CTaskExplorer::eDriver;
#endif

		if (pNode->iColor != RowColor) {
			pNode->iColor = RowColor;
			pNode->Color = CTaskExplorer::GetListColor(RowColor);
			Changed = 2;
		}

		if (pNode->IsGray != pService->IsStopped())
		{
			pNode->IsGray = pService->IsStopped();
			Changed = 2;
		}


		for(int section = 0; section < columnCount(); section++)
		{
			if (m_ColumnsOff.contains(section))
				continue; // ignore columns which are hidden

			QVariant Value;
			switch(section)
			{
				case eService:				Value = pService->GetName().toLower(); break;
#ifdef WIN32
				case eDisplayName:			Value = pWinService->GetDisplayName(); break;
				case eType:					Value = pWinService->GetTypeString(); break;
#else
				case eDisplayName:			Value = pService->GetDisplayName(); break;
				case eType:					Value = pLinuxService->GetTypeString(); break;
#endif
				case eStatus:				Value = pService->GetStateString(); break;
#ifdef WIN32
				case eStartType:			Value = pWinService->GetStartTypeString(); break;
#endif
				case ePID:					Value = (int)pService->GetPID(); break;
				case eFileName:				Value = pService->GetFileName(); break;
#ifdef WIN32
				case eDescription:			Value = pModule ? pModule->GetFileInfo("Description") : ""; break;
				case eCompanyName:			Value = pModule ? pModule->GetFileInfo("CompanyName") : ""; break;
				case eVersion:				Value = pModule ? pModule->GetFileInfo("FileVersion") : ""; break;
				case eErrorControl:			Value = pWinService->GetErrorControlString(); break;
				case eGroupe:				Value = pWinService->GetGroupeName(); break;
#endif
				case eBinaryPath:			Value = pService->GetBinaryPath(); break;

				//case eKeyModificationTime:	

#ifdef WIN32
				case eVerificationStatus:	Value = pWinModule ? pWinModule->GetVerifyResultString() : ""; break;
				case eVerifiedSigner:		Value = pWinModule ? pWinModule->GetVerifySignerName() : ""; break;

				case eExitCode:				Value = pWinService->GetWin32ExitCode() == ERROR_SERVICE_SPECIFIC_ERROR ? pWinService->GetServiceSpecificExitCode() : pWinService->GetWin32ExitCode(); break;
#endif
			}

			SServiceNode::SValue& ColValue = pNode->Values[section];

			if (ColValue.Raw != Value)
			{
				if(Changed == 0)
					Changed = 1;
				ColValue.Raw = Value;

				switch (section)
				{
					case ePID:				if (Value.toLongLong() < 0) ColValue.Formatted = ""; 
											else ColValue.Formatted = theGUI->FormatID(Value.toLongLong()); 
											break;

					case eService:			ColValue.Formatted = pService->GetName(); break;
				}
			}

			if(State != (Changed != 0))
			{
				if(State && Row != -1)
					emit dataChanged(createIndex(Row, Col), createIndex(Row, section-1));
				State = (Changed != 0);
				Col = section;
			}
			if(Changed == 1)
				Changed = 0;
		}
		if(State && Row != -1)
			emit dataChanged(createIndex(Row, Col, pNode), createIndex(Row, columnCount()-1, pNode));

	}

CServicePtr CServiceModel::GetService(const QModelIndex &index) const
{
	if (!index.isValid())
        return CServicePtr();

	SServiceNode* pNode = static_cast<SServiceNode*>(index.internalPointer());
	return pNode->pService;
}

QVariant CServiceModel::headerData(int section, Qt::Orientation orientation, int role) const
{
    if (orientation == Qt::Horizontal && role == Qt::DisplayRole)
	{
		switch(section)
		{
			case eService:				return tr("Service");
			case eDisplayName:			return tr("Display Name");
			case eType:					return tr("Type");
			case eStatus:				return tr("Status");
#ifdef WIN32
			case eStartType:			return tr("Start type");
#endif
			case ePID:					return tr("PID");
			case eFileName:				return tr("File name");
#ifdef WIN32
			case eErrorControl:			return tr("Error control");
			case eGroupe:				return tr("Groupe");
			case eDescription:			return tr("Description");
			case eCompanyName:			return tr("Company name");
			case eVersion:				return tr("Version");
#endif
			case eBinaryPath:			return tr("Binary path");

			//case eKeyModificationTime:	return tr("Modification time");

			case eVerificationStatus:	return tr("Verification status");
			case eVerifiedSigner:		return tr("Verified signer");

			case eExitCode:				return tr("Exit code");
		}
	}
    return QVariant();
}

static bool CheckInternet()
{
	const QList<QNetworkInterface> Interfaces = QNetworkInterface::allInterfaces();
	for (const QNetworkInterface& Interface : Interfaces)
	{
		const QNetworkInterface::InterfaceFlags Flags = Interface.flags();
		if (!(Flags & QNetworkInterface::IsUp) || !(Flags & QNetworkInterface::IsRunning))
			continue;
		if (Flags & QNetworkInterface::IsLoopBack)
			continue;
		if (!Interface.addressEntries().isEmpty())
			return true;
	}
	return false;
}

CCGroupView::CCGroupView(QWidget *parent)
	:CPanelView(parent)
{
	m_pMainLayout = new QGridLayout();
	m_pMainLayout->setContentsMargins(0, 0, 0, 0);
