void CSecurityView::PruneStale()
{
	for (auto I = m_Items.begin(); I != m_Items.end(); )
	{
		if (m_LiveKeys.contains(I.key())) { ++I; continue; }
		delete I.value();
		I = m_Items.erase(I);
	}

	for (auto I = m_Groups.begin(); I != m_Groups.end(); )
	{
		if (I.value()->childCount() > 0) { ++I; continue; }
		delete I.value();
		I = m_Groups.erase(I);
	}
}

void CSecurityView::ShowProcesses(const QList<CProcessPtr>& Processes)
{
	QSharedPointer<CLinuxProcess> pProcess;
	if (Processes.count() == 1)
	{
		setEnabled(true);
		pProcess = Processes.first().objectCast<CLinuxProcess>();
	}
	else
		setEnabled(false);

	m_pCurProcess = pProcess;

	Refresh();
}

void CSecurityView::Refresh()
{
	m_LiveKeys.clear();

	if (m_pCurProcess.isNull())
	{
		PruneStale();
		return;
	}

	const quint64 Pid = m_pCurProcess->GetProcessId();
	const ProcFs::SProcSecurity Security = ProcFs::ReadProcSecurity(Pid);

	if (!Security.Valid)
	{
		SetValue(tr("Identity"), tr("Status"), tr("The process has exited."));
		PruneStale();
		return;
	}

	// ---- identity ----

	SetValue(tr("Identity"), tr("User"), tr("%1 (uid %2)")
		.arg(m_pCurProcess->GetUserName()).arg(m_pCurProcess->GetUid()));
	SetValue(tr("Identity"), tr("Group id"), QString::number(m_pCurProcess->GetGid()));

	const QString Container = m_pCurProcess->GetContainer();
	SetValue(tr("Identity"), tr("Container"), Container.isEmpty() ? tr("none (host)") : Container);

	// ---- confinement ----

	//
	// An absent label means no LSM is active at all, which is materially
	// different from an active LSM that has decided not to confine this
	// process - so the two are worded differently rather than both blank.
	//
	const QString Confinement = Security.Confinement;
	if (Confinement.isEmpty())
		SetValue(tr("Confinement"), tr("Profile"), tr("no LSM active"));
	else if (Confinement == "unconfined")
		SetValue(tr("Confinement"), tr("Profile"), tr("unconfined"));
	else
		SetValue(tr("Confinement"), tr("Profile"), Confinement);

	SetValue(tr("Confinement"), tr("Seccomp"), Security.SeccompFilters
		? tr("%1 (%2 filters)").arg(ProcFs::SeccompModeToString(Security.Seccomp)).arg(Security.SeccompFilters)
		: ProcFs::SeccompModeToString(Security.Seccomp));

	//
	// no_new_privs means the process can never gain privileges through execve,
	// so a setuid binary it runs stays unprivileged. It is what makes a sandbox
	// hold across exec.
	//
	SetValue(tr("Confinement"), tr("No new privileges"), Security.NoNewPrivs ? tr("Yes") : tr("No"));

	// ---- capabilities ----

	//
	// Five sets, but they answer different questions and only two are usually
	// worth reading:
	//
	//   Effective - what the process can use right now
	//   Permitted - what it may re-enable at will, so effectively the same power
	//   Bounding  - the ceiling; nothing outside it can ever be acquired
	//   Inheritable / Ambient - what survives an execve
	//
	auto Describe = [](quint64 Mask, quint64 FullSet) -> QString {
		if (Mask == 0)
			return CSecurityView::tr("none");
		// A full set is how an unconfined root process looks; listing all
		// forty names there would bury the cases that matter.
		if (FullSet && Mask == FullSet)
			return CSecurityView::tr("all");
		return ProcFs::DecodeCapabilities(Mask).join(", ");
	};

	// The bounding set of an unrestricted process is the full set the running
	// kernel supports, so it is the right reference for "all".
	const quint64 FullSet = Security.CapBnd;

	SetValue(tr("Capabilities"), tr("Effective"), Describe(Security.CapEff, FullSet));
	SetValue(tr("Capabilities"), tr("Permitted"), Describe(Security.CapPrm, FullSet));
	SetValue(tr("Capabilities"), tr("Inheritable"), Describe(Security.CapInh, FullSet));
	SetValue(tr("Capabilities"), tr("Ambient"), Describe(Security.CapAmb, FullSet));
	SetValue(tr("Capabilities"), tr("Bounding"), Describe(Security.CapBnd, 0));

	// ---- namespaces ----

	//
	// Shown against pid 1's, because the inode numbers themselves mean nothing
	// to a reader - what matters is whether this process shares the host's
	// namespace or has one of its own.
	//
	static const ProcFs::SNamespaces Host = ProcFs::ReadNamespaces(1);
	const ProcFs::SNamespaces Namespaces = m_pCurProcess->GetNamespaces();

	auto ShowNamespace = [this](const QString& Name, quint64 Value, quint64 HostValue) {
		if (!Value)
			SetValue(tr("Namespaces"), Name, tr("not readable"));
		else if (!HostValue || Value == HostValue)
			SetValue(tr("Namespaces"), Name, tr("host"));
		else
			SetValue(tr("Namespaces"), Name, tr("private (%1)").arg(Value));
	};

	ShowNamespace(tr("pid"), Namespaces.Pid, Host.Pid);
	ShowNamespace(tr("net"), Namespaces.Net, Host.Net);
	ShowNamespace(tr("mnt"), Namespaces.Mnt, Host.Mnt);
	ShowNamespace(tr("user"), Namespaces.User, Host.User);
	ShowNamespace(tr("uts"), Namespaces.Uts, Host.Uts);
	ShowNamespace(tr("ipc"), Namespaces.Ipc, Host.Ipc);
	ShowNamespace(tr("cgroup"), Namespaces.CGroup, Host.CGroup);

	// ---- out of memory killer ----

	SetValue(tr("Out of memory killer"), tr("Score"), QString::number(m_pCurProcess->GetOomScore()));
	SetValue(tr("Out of memory killer"), tr("Adjustment"), QString::number(m_pCurProcess->GetOomScoreAdj()));

	// ---- resources ----

	SetValue(tr("Resources"), tr("inotify watches"), FormatNumber(m_pCurProcess->GetInotifyWatches()));

	PruneStale();
}

bool fixLocalServerPermissions(QLocalServer *server)
{
    QString pipeName = server->fullServerName();

    HANDLE h = CreateNamedPipeA(pipeName.toStdString().c_str(), PIPE_ACCESS_DUPLEX | WRITE_DAC,
            PIPE_TYPE_MESSAGE, PIPE_UNLIMITED_INSTANCES, 1024*16, 1024*16, 0, NULL);

    if (h == INVALID_HANDLE_VALUE)
        return false;

    bool status = SetSecurityInfo(h, SE_KERNEL_OBJECT, DACL_SECURITY_INFORMATION, NULL, NULL, NULL, NULL) == ERROR_SUCCESS;
    CloseHandle(h);

    return status;
}

CTaskService::CTaskService(int argc, char **argv, const QString& svcName, int timeout)
	: QObject(nullptr), QtServiceBase(argc, argv, svcName)
{
    setServiceDescription("Task Explorer worker service");
    //setServiceFlags(QtServiceBase::CanBeSuspended);

	m_pServer = NULL;

	m_TimeOut = timeout;
	m_LastActivity = GetCurTick();
	m_TimerId = startTimer(1000);
}

void CTaskService::start()
{
	m_pServer = new QLocalServer(this);
	QObject::connect(m_pServer, SIGNAL(newConnection()), SLOT(receiveConnection()));
	m_pServer->listen(serviceName());
#ifdef WIN32
	fixLocalServerPermissions(m_pServer);
#endif
}

void CTaskService::stop()
{
	//QtServiceBase::stop(); // stop is empty anyways

	if (m_pServer) {
		m_pServer->close();
		m_pServer->deleteLater();
		m_pServer = NULL;
	}
}

void CTaskService::timerEvent(QTimerEvent *e)
{
	if (e->timerId() != m_TimerId) 
	{
		QObject::timerEvent(e);
		return;
	}

	if(m_TimeOut && GetCurTick() - m_LastActivity > m_TimeOut)
		QCoreApplication::instance()->quit();
}

bool CTaskService::SendXVariant(QLocalSocket* pSocket, const QVariant& Data, int timeout)
{
	if (!pSocket || !pSocket->isValid())
		return false;

	// Convert QVariant to XVariant
	XVariant xvar;
	if (!xvar.FromQVariant(Data))
		return false;

	// Serialize XVariant to CBuffer
	CBuffer buffer;
	xvar.ToPacket(&buffer);

	// Convert CBuffer to QByteArray
	QByteArray data = buffer.ToByteArray();

	// Send length prefix
	quint32 len = data.size();
	pSocket->write((char*)&len, sizeof(quint32));

	// Send serialized data
	pSocket->write(data);

	return pSocket->waitForBytesWritten(timeout);
}

QVariant CTaskService::RecvXVariant(QLocalSocket* pSocket, int timeout)
{
	if (!pSocket || !pSocket->isValid())
		return QVariant();

	// Read length prefix
	quint32 len = 0;
	if (!ReadFromDevice(pSocket, (char*)&len, sizeof(quint32), timeout))
		return QVariant();

	// Read serialized data
	QByteArray data;
	data.resize(len);
	if (!ReadFromDevice(pSocket, data.data(), len, timeout))
		return QVariant();

	// Convert QByteArray to CBuffer
	CBuffer buffer(data, true); // true = derive from existing data

	// Deserialize CBuffer to XVariant
	XVariant xvar;
	xvar.FromPacket(&buffer);

	// Convert XVariant to QVariant
	return xvar.ToQVariant();
}

foreach(const QString& service, Parameters.value("Dependencies").toStringList())
				{
					Dependencies.append(service.toStdWString());
					Dependencies.push_back(L'\0');
				}

bool CTaskService::CheckStatus(long Status)
{
#ifdef WIN32
    if (!(Status == STATUS_ACCESS_DENIED || Status == STATUS_PRIVILEGE_NOT_HELD ||
      (NT_NTWIN32(Status) && WIN32_FROM_NTSTATUS(Status) == ERROR_ACCESS_DENIED)))
        return false;
#endif

    if (theAPI->RootAvaiable())
        return false;

	return theConf->GetBool("Options/AutoElevate", true);
}

bool CTaskService::TaskAction(quint64 ProcessId, quint64 ThreadId, const QString& Action, const QVariant& Data)
{
	QString SocketName = CTaskService::RunWorker();

	if (SocketName.isEmpty())
		return false;

	QVariantMap Parameters;
	Parameters["ProcessId"] = ProcessId;
	Parameters["ThreadId"] = ThreadId;
	Parameters["Action"] = Action;
	Parameters["Data"] = Data;

	QVariantMap Request;
	Request["Command"] = "ExecTaskAction";
	Request["Parameters"] = Parameters;

	QVariant Response = CTaskService::SendCommand(SocketName, Request);

	if (Response.type() == QVariant::Int)
		return Response.toInt() == 0;
	return false;	
}

qint32 CTaskService::ExecTaskAction(quint64 ProcessId, const QString& Action, const QVariant& Data)
{
#ifdef WIN32
    NTSTATUS status = STATUS_INVALID_PARAMETER; // unknown action
	HANDLE processHandle = NULL;
	if (Action == "Terminate")
	{
		if (NT_SUCCESS(status = PhOpenProcess(&processHandle, PROCESS_TERMINATE, (HANDLE)ProcessId)))
		{
			// An exit status of 1 is used here for compatibility reasons:
			// 1. Both Task Manager and Process Explorer use 1.
			// 2. winlogon tries to restart explorer.exe if the exit status is not 1.

			status = PhTerminateProcess(processHandle, 1);
		}
	}
	else if (Action == "Suspend")
	{
		if (NT_SUCCESS(status = PhOpenProcess(&processHandle, PROCESS_SUSPEND_RESUME, (HANDLE)ProcessId)))
		{
			status = NtSuspendProcess(processHandle);
		}
	}
	else if (Action == "Resume")
	{
		if (NT_SUCCESS(status = PhOpenProcess(&processHandle, PROCESS_SUSPEND_RESUME, (HANDLE)ProcessId)))
		{
			status = NtResumeProcess(processHandle);
		}
	}
	else if (Action.left(3) == "Set")
	{
		if ((HANDLE)ProcessId != SYSTEM_PROCESS_ID)
		{
			// Changing the priority of System can lead to a BSOD on some versions of Windows,
			// so disallow this.
			status = STATUS_UNSUCCESSFUL;
		}
		else if (NT_SUCCESS(status = PhOpenProcess(&processHandle, PROCESS_SET_INFORMATION, (HANDLE)ProcessId)))
		{
			if (Action == "SetPriorityBoost")
			{
				status = PhSetProcessPriorityBoost(processHandle, Data.toBool());
			}
			else if (Action == "SetPriority")
			{
				status = PhSetProcessPriorityClass(processHandle, (UCHAR)Data.toUInt());
			}
			else if (Action == "SetPagePriority")
			{
				status = PhSetProcessPagePriority(processHandle, Data.toInt());
			}
			else if (Action == "SetIOPriority")
			{
				status = PhSetProcessIoPriority(processHandle, (IO_PRIORITY_HINT)Data.toInt());
			}
			else if (Action == "SetAffinityMask")
			{
				status = PhSetProcessAffinityMask(processHandle, Data.toULongLong());
			}
		}
	}
	if(processHandle)
		NtClose(processHandle);
    return status;
#else
    return 0;
#endif
}

qint32 CTaskService::ExecTaskAction(quint64 ProcessId, quint64 ThreadId, const QString& Action, const QVariant& Data)
{
#ifdef WIN32
    NTSTATUS status = STATUS_INVALID_PARAMETER; // unknown action
	HANDLE threadHandle = NULL;
	if (Action == "Terminate")
	{
		if (NT_SUCCESS(status = PhOpenThread(&threadHandle, THREAD_TERMINATE, (HANDLE)ThreadId)))
		{
			status = NtTerminateThread(threadHandle, STATUS_SUCCESS);
		}
	}
	else if (Action == "Suspend")
	{
		if (NT_SUCCESS(status = PhOpenThread(&threadHandle, THREAD_SUSPEND_RESUME, (HANDLE)ThreadId)))
		{
			status = NtSuspendThread(threadHandle, NULL);
		}
	}
	else if (Action == "Resume")
	{
		if (NT_SUCCESS(status = PhOpenThread(&threadHandle, THREAD_SUSPEND_RESUME, (HANDLE)ThreadId)))
		{
			status = NtResumeThread(threadHandle, NULL);
		}
	}
	else if (Action.left(3) == "Set")
	{
		if (NT_SUCCESS(status = PhOpenThread(&threadHandle, THREAD_SET_INFORMATION, (HANDLE)ThreadId)))
		{
			if (Action == "SetPriorityBoost")
			{
				status = PhSetThreadPriorityBoost(threadHandle, Data.toBool());
			}
			else if (Action == "SetPriority")
			{
				status = PhSetThreadBasePriority(threadHandle, Data.toInt());
			}
			else if (Action == "SetPagePriority")
			{
				status = PhSetThreadPagePriority(threadHandle, Data.toInt());
			}
			else if (Action == "SetIOPriority")
			{
				status = PhSetThreadIoPriority(threadHandle, (IO_PRIORITY_HINT)Data.toInt());
			}
			else if (Action == "SetAffinityMask")
			{
				status = PhSetThreadAffinityMask(threadHandle, Data.toULongLong());
			}
		}
	}
	if(threadHandle)
		NtClose(threadHandle);
    return status;
#else
    return 0;
#endif
}

bool CTaskService::ServiceAction(const QString& Name, const QString& Action, const QVariant& Data)
{
	QString SocketName = CTaskService::RunWorker();

	if (SocketName.isEmpty())
		return false;

	QVariantMap Parameters;
	Parameters["Name"] = Name;
	Parameters["Data"] = Data;
	Parameters["Action"] = Action;

	QVariantMap Request;
	Request["Command"] = "ServiceTaskAction";
	Request["Parameters"] = Parameters;

	QVariant Response = CTaskService::SendCommand(SocketName, Request);

	if (Response.type() == QVariant::Int)
		return Response.toInt() == 0;
	return false;	
}

qint32 CTaskService::ExecServiceAction(const QString& Name, const QString& Action, const QVariant& Data)
{
#ifdef WIN32
    NTSTATUS status = 0;
	std::wstring SvcName = Name.toStdWString();
	SC_HANDLE serviceHandle = NULL;
	if (Action == "Start")
	{
		if (NT_SUCCESS(PhOpenService(&serviceHandle, SERVICE_START, (wchar_t*)SvcName.c_str())))
		{
			if (!StartService(serviceHandle, 0, NULL))
				status = PhGetLastWin32ErrorAsNtStatus();
		}
	}
	else if (Action == "Pause")
	{
		if (NT_SUCCESS(PhOpenService(&serviceHandle, SERVICE_PAUSE_CONTINUE, (wchar_t*)SvcName.c_str())))
		{
			SERVICE_STATUS serviceStatus;
			if (!ControlService(serviceHandle, SERVICE_CONTROL_PAUSE, &serviceStatus))
				status = PhGetLastWin32ErrorAsNtStatus();
		}
	}
	else if (Action == "Continue")
	{
		if (NT_SUCCESS(PhOpenService(&serviceHandle, SERVICE_PAUSE_CONTINUE, (wchar_t*)SvcName.c_str())))
		{
			SERVICE_STATUS serviceStatus;
			if (!ControlService(serviceHandle, SERVICE_CONTROL_CONTINUE, &serviceStatus))
				status = PhGetLastWin32ErrorAsNtStatus();
		}
	}
	else if (Action == "Stop")
	{
		if (NT_SUCCESS(PhOpenService(&serviceHandle, SERVICE_STOP, (wchar_t*)SvcName.c_str())))
		{
			SERVICE_STATUS serviceStatus;
			if (!ControlService(serviceHandle, SERVICE_CONTROL_STOP, &serviceStatus))
				status = PhGetLastWin32ErrorAsNtStatus();
		}
	}
	else if (Action == "Delete")
	{
		if (NT_SUCCESS(PhOpenService(&serviceHandle, DELETE, (wchar_t*)SvcName.c_str())))
		{
			if (!DeleteService(serviceHandle))
				status = PhGetLastWin32ErrorAsNtStatus();
		}
	}
	else
		status = STATUS_INVALID_PARAMETER;
	if(serviceHandle)
		CloseServiceHandle(serviceHandle);
    return status;
#else
    return 0;
#endif
}

QString CTaskService::FindWorkerBinary(bool b32Bit)
{
#ifdef _WIN64
	if (b32Bit)
	{
#ifdef USE_TASK_HELPER	
		QString AppDir = QApplication::applicationDirPath();
		QString HemperExe = AppDir + "/x86/TaskHelper.exe";
		return HemperExe.replace("/", "\\");
#else
		static const char* relativeFileNames[] =
		{
			"\\x86\\TaskExplorer.exe",
			"\\..\\x86\\TaskExplorer.exe",
#ifdef DEBUG
			"\\..\\..\\Win32\\Debug\\TaskExplorer.exe"
#else
			"\\..\\..\\Win32\\Release\\TaskExplorer.exe"
#endif
		};

		QString AppDir = QApplication::applicationDirPath();

		for (int i = 0; i < RTL_NUMBER_OF(relativeFileNames); i++)
		{
			QString TestPath = QDir::cleanPath(AppDir + relativeFileNames[i]);
			if (QFile::exists(TestPath))
			{
				return TestPath.replace("/", "\\");
			}
		}

		return QString(); // Not found
#endif // USE_TASK_HELPER
	}
	else
#endif // _WIN64
	{
#ifdef USE_TASK_HELPER	
		QString AppDir = QApplication::applicationDirPath();
		QString HemperExe = AppDir + "/TaskHelper.exe";
		return HemperExe.replace("/", "\\");
#else
		return QApplication::applicationFilePath();
#endif // USE_TASK_HELPER
	}
}

QVariant CTaskService::SendCommand(const QString& socketName, const QVariant &Command, int timeout)
{
    QLocalSocket Socket;

    bool Ok = false;
    for(int i = 0; i < 4; i++)
	{
        Socket.connectToServer(socketName);
        Ok = Socket.waitForConnected(timeout == -1 ? 30000 : timeout/2);
        if (Ok)
            break;
		QThread::msleep(250);
    }

	if (!Ok)
		return QVariant(); // Connection failed

	// Use XVariant protocol (both TaskHelper and legacy TaskExplorer service modes)
	if (!SendXVariant(&Socket, Command, timeout))
		return QVariant(); // Send failed

	QVariant Response = RecvXVariant(&Socket, timeout);

#ifdef _DEBUG
	ASSERT(Response.toString() != "Unknown Command");
#endif

	Socket.disconnectFromServer();
	return Response;
}

QString CTaskService::RunWorker(bool bElevanted, bool b32Bit)
{
	QMutexLocker Locker(&m_Mutex);

#ifdef WIN32
	QString BinaryPath = FindWorkerBinary(b32Bit);
	if (BinaryPath.isEmpty())
		return QString();

	QString SocketName;
	{
#ifdef _WIN64
		if (b32Bit)
			SocketName = m_TempSocket32;
		else
#endif
			SocketName = m_TempSocket;
	}

	if (!SocketName.isEmpty())
	{
		if (SendCommand(SocketName, "Refresh", 500).toBool() == true)
			return SocketName;
	}

	SocketName = TASK_SERVICE_NAME;
	SocketName += "_" + GetRand64Str();

	std::wstring Arguments = L"-wrk \"" + SocketName.toStdWString() + L"\"";
#if _DEBUG
	//Arguments.append(L" -timeout 50000");
	//Arguments.append(L" -dbg_wait");
#else
	Arguments.append(L" -timeout 5000");
#endif

	HANDLE ProcessHandle = NULL;
	if (bElevanted && !PhGetOwnTokenAttributes().Elevated)
		PhShellProcessHackerEx(NULL, (wchar_t*)BinaryPath.toStdWString().c_str(), (wchar_t*)Arguments.c_str(), SW_HIDE, PH_SHELL_EXECUTE_ADMIN, 0, 0, &ProcessHandle);
	else
		PhShellProcessHackerEx(NULL, (wchar_t*)BinaryPath.toStdWString().c_str(), (wchar_t*)Arguments.c_str(), SW_HIDE, 0, 0, 0, &ProcessHandle);
	if (ProcessHandle == NULL)
		return QString();

#ifdef _WIN64
	if (b32Bit)
		m_TempSocket32 = SocketName;
	else
#endif
		m_TempSocket = SocketName;

	if (SendCommand(SocketName, "Refresh", 1000).toBool() == true)
		return SocketName;
#else
	//
	// Linux. The helper is a small Qt-free binary next to the application; see
	// TaskHelper/LinuxMain.cpp for why the privileged work lives in its own
	// process rather than in the GUI.
	//
	const QString BinaryPath = QCoreApplication::applicationDirPath() + "/TaskHelper";
	if (!QFile::exists(BinaryPath))
		return QString();

	QString& CachedSocket = bElevanted ? m_TempSocketRoot : m_TempSocket;

	//
	// Reuse a helper that is still alive. This is what keeps the elevation
	// prompt to once per session rather than once per request - and the helper
	// exits by itself when the conversation stops, so a stale name here simply
	// fails the probe and is replaced.
	//
	if (!CachedSocket.isEmpty())
	{
		if (SendCommand(CachedSocket, "Refresh", 500).toBool() == true)
			return CachedSocket;
		CachedSocket.clear();
	}

	//
	// The socket lives in the user's runtime directory, which is private to them
	// and cleaned up on logout. QLocalSocket treats an absolute path as exactly
	// that, so both ends agree on the location without depending on Qt's
	// name-to-path convention.
	//
	QString RuntimeDir = QString::fromLocal8Bit(qgetenv("XDG_RUNTIME_DIR"));
	if (RuntimeDir.isEmpty() || !QFile::exists(RuntimeDir))
		RuntimeDir = QDir::tempPath();

	const QString SocketPath = RuntimeDir + "/TaskExplorer-helper-" + GetRand64Str();

	QStringList Arguments;
	Arguments << "-wrk" << SocketPath;
	//
	// Idle timeout: the helper terminates on its own once nothing is talking to
	// it, so killing TaskExplorer cannot leave a privileged process behind.
	//
	Arguments << "-timeout" << "30000";

	bool bStarted = false;
	if (bElevanted && geteuid() != 0)
	{
		//
		// The helper must hand the socket to us after binding it: it will be
		// running as root, and connecting to a unix socket needs write access to
		// the file, which a root-owned 0600 socket would deny us.
		//
		Arguments << "-owner" << QString::number(geteuid());

		bStarted = !LinuxRunElevated(BinaryPath, Arguments).IsError();
	}
	else
	{
		bStarted = QProcess::startDetached(BinaryPath, Arguments);
	}

	if (!bStarted)
		return QString();

	//
	// Wait for the socket to appear rather than assuming it is ready. An
	// elevated start has an authentication prompt in the middle of it, so this
	// has to tolerate a human-scale delay; an ordinary one is ready in
	// milliseconds.
	//
	const int TimeoutMs = bElevanted ? 60000 : 5000;
	QElapsedTimer Timer;
	Timer.start();

	while (Timer.elapsed() < TimeoutMs)
	{
		if (QFile::exists(SocketPath) && SendCommand(SocketPath, "Refresh", 500).toBool() == true)
		{
			CachedSocket = SocketPath;
			return SocketPath;
		}
		QThread::msleep(100);
	}
#endif
	return QString();
}

void CTaskService::TerminateWorkers()
{
	QMutexLocker Locker(&m_Mutex);

	if (!m_TempName.isEmpty())
		Terminate(m_TempName);

	if (!m_TempSocket.isEmpty())
		Terminate(m_TempSocket);
#ifdef _WIN64
	if (!m_TempSocket32.isEmpty())
		Terminate(m_TempSocket32);
#endif
#ifndef WIN32
	// The elevated helper too - it would exit on its own timeout, but leaving a
	// root process running after the GUI has gone is not something to rely on a
	// timer for.
	if (!m_TempSocketRoot.isEmpty())
		Terminate(m_TempSocketRoot);
#endif
}

QString CTaskService::RunService()
{
	QMutexLocker Locker(&m_Mutex);

#ifdef WIN32
	QString ServiceName = TASK_SERVICE_NAME;

	/*// check if a persistent service is installed and running
	bool isRunning = false;
	bool isInstalled = false;
	SC_HANDLE serviceHandle;
	if (NT_SUCCESS(PhOpenService(&serviceHandle, SERVICE_QUERY_STATUS, (wchar_t*)ServiceName.toStdWString().c_str())))
	{
		isInstalled = true;
		SERVICE_STATUS serviceStatus;
		if (QueryServiceStatus(serviceHandle, &serviceStatus) && serviceStatus.dwCurrentState == SERVICE_RUNNING)
			isRunning = true;
		CloseServiceHandle(serviceHandle);
	}
	if (isRunning)
		return ServiceName;*/

	{
		if (!m_TempName.isEmpty())
		{
#ifdef _DEBUG
			if (SendCommand(m_TempName, "Refresh", INFINITE).toBool() == true)
#else
			if (SendCommand(m_TempName, "Refresh", 500).toBool() == true)
#endif
				return m_TempName;
		}
	}

	// if not, than start a new temporary service instance
	ServiceName += "_" + GetRand64Str();
	if (RunService(ServiceName))
	{
		m_TempName = ServiceName;
		return ServiceName;
	}
#endif
	return QString();
}

bool CTaskService::RunService(const QString& ServiceName, QString BinaryPath)
{
#ifdef WIN32
	// Note: this function may be invoked without prior calling InitPH() !!!

	if (BinaryPath.isEmpty())
	{
		BinaryPath = FindWorkerBinary(false); // Service always runs native architecture
		if (BinaryPath.isEmpty())
			return false;
	}

	if (!IsElevated())
	{
		int Ret = RunElevated(BinaryPath.toStdWString(), L"-runsvc " + ServiceName.toStdWString(), true);
		if (Ret == EXIT_SUCCESS);
			return true;
		return false;
	}

	BOOLEAN success = FALSE;

	// Try to start the service if its installed
	SC_HANDLE serviceHandle; 
	if (NT_SUCCESS(PhOpenService(&serviceHandle, SERVICE_QUERY_STATUS | SERVICE_START, (wchar_t*)ServiceName.toStdWString().c_str()))) // this is safe to call without InitPH
	{
		SERVICE_STATUS serviceStatus;
        if (QueryServiceStatus(serviceHandle, &serviceStatus) && serviceStatus.dwCurrentState == SERVICE_RUNNING)
			success = TRUE;
		else if (StartService(serviceHandle, 0, NULL))
			success = TRUE;

		CloseServiceHandle(serviceHandle);
	}
	//else return NTSTATUS_FROM_WIN32(win32Result);

	// when that fails, try to install a temporary service and start it
	if (!success)
	{
		SC_HANDLE scManagerHandle;
		if (!(scManagerHandle = OpenSCManager(NULL, NULL, SC_MANAGER_CREATE_SERVICE)))
			return false; //PhGetLastWin32ErrorAsNtStatus();

		std::wstring CommandLine = L"\"" + BinaryPath.toStdWString() + L"\" -svc \"" + ServiceName.toStdWString() + L"\"";
#if _DEBUG
		CommandLine.append(L" -timeout 50000");
		//CommandLine.append(L" -dbg_wait");
#else
		CommandLine.append(L" -timeout 5000");
#endif

		SC_HANDLE serviceHandle = CreateService(scManagerHandle, ServiceName.toStdWString().c_str(), ServiceName.toStdWString().c_str(), SERVICE_ALL_ACCESS, SERVICE_WIN32_OWN_PROCESS, SERVICE_DEMAND_START,
			SERVICE_ERROR_IGNORE, CommandLine.c_str(), NULL, NULL, NULL, L"LocalSystem", L"");
		//ULONG  win32Result = GetLastError();

		if (serviceHandle)
		{
			//PhSetDesktopWinStaAccess(); // can this work without InitPH?

			if (StartService(serviceHandle, 0, NULL))
				success = TRUE;

			DeleteService(serviceHandle);

			CloseServiceHandle(serviceHandle);
		}
		//else return NTSTATUS_FROM_WIN32(win32Result);
	}

	if (success)
		return true;
#endif
	return false;
}

static uint64 NowMs()
{
	struct timespec ts;
	clock_gettime(CLOCK_MONOTONIC, &ts);
	return (uint64)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

static bool ReadExact(int Fd, void* pBuffer, size_t Length, int TimeoutMs)
{
	char* p = (char*)pBuffer;
	size_t Done = 0;

	while (Done < Length)
	{
		struct pollfd Poll = { Fd, POLLIN, 0 };
		const int Ready = poll(&Poll, 1, TimeoutMs);
		if (Ready <= 0)
			return false;	// timed out, or the socket failed

		const ssize_t Read = recv(Fd, p + Done, Length - Done, 0);
		if (Read == 0)
			return false;	// peer closed
		if (Read < 0)
		{
			if (errno == EINTR)
				continue;
			return false;
		}

		Done += (size_t)Read;
	}

	return true;
}

static bool WriteExact(int Fd, const void* pBuffer, size_t Length)
{
	const char* p = (const char*)pBuffer;
	size_t Done = 0;

	while (Done < Length)
	{
		// MSG_NOSIGNAL: a client that has gone away must yield EPIPE rather than
		// killing the helper with SIGPIPE.
		const ssize_t Written = send(Fd, p + Done, Length - Done, MSG_NOSIGNAL);
		if (Written <= 0)
		{
			if (Written < 0 && errno == EINTR)
				continue;
			return false;
		}

		Done += (size_t)Written;
	}

	return true;
}

static bool RecvVariant(int Fd, CVariant& Variant, int TimeoutMs)
{
	uint32 Length = 0;
	if (!ReadExact(Fd, &Length, sizeof(Length), TimeoutMs))
		return false;

	// Same sanity bound the Windows side applies; a corrupt or hostile length
	// must not become a 4 GB allocation.
	if (Length == 0 || Length > 100 * 1024 * 1024)
		return false;

	std::vector<char> Data(Length);
	if (!ReadExact(Fd, Data.data(), Length, TimeoutMs))
		return false;

	CBuffer Buffer(Data.data(), Length, true);	// true = wrap, do not copy
	Variant.FromPacket(&Buffer);

	return true;
}

static bool SendVariant(int Fd, const CVariant& Variant)
{
	CBuffer Buffer;
	Variant.ToPacket(&Buffer);

	const uint32 Length = (uint32)Buffer.GetSize();
	if (!WriteExact(Fd, &Length, sizeof(Length)))
		return false;

	return WriteExact(Fd, Buffer.GetBuffer(), Length);
}

static int FrameCallback(Dwfl_Frame* pFrame, void* pArg)
{
	SFrameCollector* pCollector = (SFrameCollector*)pArg;
	if (pCollector->Count >= pCollector->MaxFrames)
		return DWARF_CB_ABORT;

	Dwarf_Addr Pc = 0;
	bool bActivation = false;
	if (!dwfl_frame_pc(pFrame, &Pc, &bActivation))
		return DWARF_CB_ABORT;

	//
	// For anything but the innermost frame the program counter is a *return*
	// address, which can land on the instruction after a call - and if that call
	// was the last instruction of a function, on the following function
	// entirely. Stepping back one byte before looking the address up is what
	// keeps such a frame attributed to the caller rather than to its neighbour.
	//
	// The address reported to the user stays the real one.
	//
	const Dwarf_Addr LookupPc = bActivation ? Pc : Pc - 1;

	CVariant Frame;
	Frame.BeginMap();
	Frame.Write("Address", (uint64)Pc);

	Dwfl* pDwfl = dwfl_thread_dwfl(dwfl_frame_thread(pFrame));
	Dwfl_Module* pModule = pDwfl ? dwfl_addrmodule(pDwfl, LookupPc) : NULL;

	if (pModule)
	{
		//
		// The module's file name, and the offset of this address within it -
		// which is what "eu-addr2line -e <module> <offset>" takes, so a frame
		// stays actionable even when no symbol could be found.
		//
		Dwarf_Addr ModuleStart = 0;
		const char* pModuleName = dwfl_module_info(pModule, NULL, &ModuleStart, NULL, NULL, NULL, NULL, NULL);
		if (pModuleName)
			Frame.Write("Module", pModuleName);
		Frame.Write("Offset", (uint64)(LookupPc - ModuleStart));

		//
		// dwfl_module_addrinfo rather than dwfl_module_addrname: it also reports
		// how far into the symbol the address is, which is the only way to tell a
		// real match from a nearest-preceding-symbol guess in a stripped library.
		//
		GElf_Off SymbolOffset = 0;
		GElf_Sym Symbol;
		const char* pName = dwfl_module_addrinfo(pModule, LookupPc, &SymbolOffset, &Symbol, NULL, NULL, NULL);
		if (pName)
		{
			Frame.Write("Symbol", pName);
			Frame.Write("SymbolOffset", (uint64)SymbolOffset);
		}

		// Source location, when the module carries (or points at) debug info.
		Dwfl_Line* pLine = dwfl_module_getsrc(pModule, LookupPc);
		if (pLine)
		{
			int LineNumber = 0;
			int Column = 0;
			const char* pFile = dwfl_lineinfo(pLine, NULL, &LineNumber, &Column, NULL, NULL);
			if (pFile)
			{
				Frame.Write("File", pFile);
				Frame.Write("Line", (uint32)LineNumber);
				Frame.Write("Column", (uint32)Column);
			}
		}
	}

	Frame.Finish();

	pCollector->pFrames->WriteVariant(Frame);
	pCollector->Count++;

	return DWARF_CB_OK;
}

static CVariant TraceStack(uint64 Pid, uint64 Tid, int MaxFrames)
{
	CVariant Result;
	Result.BeginMap();

	//
	// Zero initialised, then only the fields we mean to provide are set. libdwfl
	// treats a null callback as "not supplied", so this also means a future
	// elfutils that appends a field sees a null rather than garbage.
	//
	static char* pDebugInfoPath = NULL;
	Dwfl_Callbacks Callbacks;
	memset(&Callbacks, 0, sizeof(Callbacks));
	Callbacks.find_elf = dwfl_linux_proc_find_elf;
	Callbacks.find_debuginfo = dwfl_standard_find_debuginfo;
	Callbacks.debuginfo_path = &pDebugInfoPath;

	Dwfl* pDwfl = dwfl_begin(&Callbacks);
	if (!pDwfl)
	{
		Result.Write("Error", "libdwfl could not be initialised");
		Result.Finish();
		return Result;
	}

	int Error = dwfl_linux_proc_report(pDwfl, (pid_t)Pid);
	if (Error == 0)
		Error = dwfl_report_end(pDwfl, NULL, NULL) < 0 ? -1 : 0;

	if (Error != 0)
	{
		dwfl_end(pDwfl);
		Result.Write("Error", "the process could not be examined");
		Result.Finish();
		return Result;
	}

	//
	// false: let libdwfl do the ptrace attach and stop itself, and detach when
	// unwinding finishes. Holding the attachment for no longer than the unwind
	// matters - while it is held, no other debugger on the system can attach.
	//
	Error = dwfl_linux_proc_attach(pDwfl, (pid_t)Pid, false);
	if (Error != 0)
	{
		dwfl_end(pDwfl);
		//
		// The usual cause is ptrace being refused. Reported as a code so the GUI
		// can phrase it, since only it knows whether it is running elevated.
		//
		Result.Write("Error", "ptrace");
		Result.Write("Errno", (uint32)(Error > 0 ? Error : EPERM));
		Result.Finish();
		return Result;
	}

	CVariant Frames;
	Frames.BeginList();

	SFrameCollector Collector;
	Collector.pFrames = &Frames;
	Collector.MaxFrames = MaxFrames > 0 ? MaxFrames : 64;

	// The whole point: one thread, not the entire process.
	const int Walked = dwfl_getthread_frames(pDwfl, (pid_t)Tid, FrameCallback, &Collector);

	Frames.Finish();

	//
	// Report libdwfl's own diagnosis when nothing came back, rather than an empty
	// list the GUI cannot explain.
	//
	if (Collector.Count == 0)
	{
		const char* pMessage = dwfl_errmsg(-1);
		Result.Write("Error", pMessage ? pMessage : "no frames were unwound");
		Result.Write("Walked", (sint32)Walked);
	}
	dwfl_end(pDwfl);

	Result.WriteVariant("Frames", Frames);
	Result.Finish();
	return Result;
}

static bool IsReadableLeaf(const std::string& Leaf)
{
	static const char* Allowed[] = {
		"io",			// per-process read/write counters
		"cmdline",
		"environ",
		"status",
		"stat",
		"statm",
		"smaps_rollup",
		"limits",
		"wchan",
		"oom_score",
		"attr/current",	// LSM confinement label
	};

	for (size_t i = 0; i < sizeof(Allowed) / sizeof(Allowed[0]); i++)
	{
		if (Leaf == Allowed[i])
			return true;
	}

	return false;
}

static bool IsReadableLink(const std::string& Leaf)
{
	if (Leaf == "exe" || Leaf == "cwd" || Leaf == "root")
		return true;

	if (Leaf.compare(0, 3, "fd/") == 0 && Leaf.size() > 3)
	{
		for (size_t i = 3; i < Leaf.size(); i++)
		{
			if (Leaf[i] < '0' || Leaf[i] > '9')
				return false;
		}
		return true;
	}

	return false;
}

static uint64 ParseUInt(const char* pText, uint64 Fallback = 0)
{
	if (!pText)
		return Fallback;

	while (*pText == ' ' || *pText == '\t')
		pText++;

	if (*pText < '0' || *pText > '9')
		return Fallback;

	uint64 Value = 0;
	for (; *pText >= '0' && *pText <= '9'; pText++)
	{
		const uint64 Digit = (uint64)(*pText - '0');

		// Saturate rather than wrap; a pid or fd never comes near this.
		if (Value > (UINT64_MAX - Digit) / 10)
			return UINT64_MAX;

		Value = Value * 10 + Digit;
	}

	return Value;
}

static std::string ProcPath(uint64 Pid, const std::string& Leaf)
{
	char Buffer[64];
	snprintf(Buffer, sizeof(Buffer), "/proc/%llu/", (unsigned long long)Pid);
	return std::string(Buffer) + Leaf;
}

static bool ReadWholeFile(const std::string& Path, std::vector<char>& Data)
{
	const int Fd = open(Path.c_str(), O_RDONLY | O_CLOEXEC);
	if (Fd < 0)
		return false;

	//
	// Files under /proc report a size of zero, so this reads until EOF rather
	// than trusting stat. Bounded, because a few of them (environ on a process
	// with a pathological environment) can be large.
	//
	const size_t MaxSize = 8 * 1024 * 1024;
	char Chunk[8192];

	for (;;)
	{
		const ssize_t Read = read(Fd, Chunk, sizeof(Chunk));
		if (Read < 0)
		{
			if (errno == EINTR)
				continue;
			close(Fd);
			return false;
		}
		if (Read == 0)
			break;

		if (Data.size() + (size_t)Read > MaxSize)
			break;

		Data.insert(Data.end(), Chunk, Chunk + Read);
	}

	close(Fd);
	return true;
}

static CVariant ReadProcFiles(const CVariant& Parameters)
{
	CVariant Result;
	Result.BeginMap();

	const CVariant Pids = Parameters.Find("Pids");
	const CVariant Leaves = Parameters.Find("Leaves");

	std::vector<std::string> LeafNames;
	Leaves.ReadRawList([&LeafNames](const CVariant& Data) {
		LeafNames.push_back(Data.ToString());
	});

	std::vector<uint64> PidList;
	Pids.ReadRawList([&PidList](const CVariant& Data) {
		PidList.push_back(Data.To<uint64>());
	});

	for (size_t i = 0; i < PidList.size(); i++)
	{
		CVariant Files;
		Files.BeginMap();

		bool bAny = false;
		for (size_t j = 0; j < LeafNames.size(); j++)
		{
			if (!IsReadableLeaf(LeafNames[j]))
				continue;

			std::vector<char> Data;
			if (!ReadWholeFile(ProcPath(PidList[i], LeafNames[j]), Data))
				continue;	// the process exited, or even root cannot read it

			Files.WriteVariant(LeafNames[j].c_str(),
				CVariant((const byte*)Data.data(), Data.size(), VAR_TYPE_BYTES));
			bAny = true;
		}

		Files.Finish();

		if (bAny)
		{
			char Key[32];
			snprintf(Key, sizeof(Key), "%llu", (unsigned long long)PidList[i]);
			Result.WriteVariant(Key, Files);
		}
	}

	Result.Finish();
	return Result;
}

static CVariant ReadProcLink(const CVariant& Parameters)
{
	const uint64 Pid = Parameters.Find("ProcessId").To<uint64>();
	const std::string Leaf = Parameters.Find("Leaf").ToString();

	if (!Pid || !IsReadableLink(Leaf))
		return CVariant("Invalid Parameters");

	//
	// /proc symlinks report a size of zero, so the buffer has to be grown
	// blindly rather than sized from stat.
	//
	std::vector<char> Buffer(1024);
	for (;;)
	{
		const ssize_t Length = readlink(ProcPath(Pid, Leaf).c_str(), Buffer.data(), Buffer.size());
		if (Length < 0)
			return CVariant();	// gone, or not permitted even here

		if ((size_t)Length < Buffer.size())
			return CVariant(std::string(Buffer.data(), (size_t)Length));

		if (Buffer.size() > 64 * 1024)
			return CVariant(std::string(Buffer.data(), (size_t)Length));

		Buffer.resize(Buffer.size() * 2);
	}
}

static CVariant ListProcFds(const CVariant& Parameters)
{
	const uint64 Pid = Parameters.Find("ProcessId").To<uint64>();
	if (!Pid)
		return CVariant("Invalid Parameters");

	CVariant Result;
	Result.BeginList();

	const std::string DirPath = ProcPath(Pid, "fd");
	DIR* pDir = opendir(DirPath.c_str());
	if (pDir)
	{
		while (struct dirent* pEntry = readdir(pDir))
		{
			if (pEntry->d_name[0] < '0' || pEntry->d_name[0] > '9')
				continue;

			char LinkTarget[4096];
			const std::string LinkPath = DirPath + "/" + pEntry->d_name;
			const ssize_t Length = readlink(LinkPath.c_str(), LinkTarget, sizeof(LinkTarget) - 1);

			CVariant Entry;
			Entry.BeginMap();
			Entry.Write("Fd", ParseUInt(pEntry->d_name));
			if (Length > 0)
				Entry.Write("Target", std::string(LinkTarget, (size_t)Length).c_str());

			// fdinfo carries the open flags and file position.
			std::vector<char> Info;
			if (ReadWholeFile(ProcPath(Pid, std::string("fdinfo/") + pEntry->d_name), Info))
				Entry.WriteVariant("Info", CVariant((const byte*)Info.data(), Info.size(), VAR_TYPE_BYTES));

			Entry.Finish();
			Result.WriteVariant(Entry);
		}
		closedir(pDir);
	}

	Result.Finish();
	return Result;
}

static void DumpDetachAll()
{
	for (size_t i = 0; i < g_DumpAttached.size(); i++)
		ptrace(PTRACE_DETACH, g_DumpAttached[i], NULL, NULL);

	g_DumpAttached.clear();
}

static CVariant DumpAttach(const CVariant& Parameters)
{
	const uint64 Pid = Parameters.Find("ProcessId").To<uint64>();
	if (!Pid)
		return CVariant("Invalid Parameters");

	// Whatever was attached before is no longer being dumped.
	DumpDetachAll();

	CVariant Result;
	Result.BeginMap();

	CVariant Threads;
	Threads.BeginList();

	int AttachErrno = 0;

	DIR* pDir = opendir(ProcPath(Pid, "task").c_str());
	if (pDir)
	{
		while (struct dirent* pEntry = readdir(pDir))
		{
			if (pEntry->d_name[0] < '0' || pEntry->d_name[0] > '9')
				continue;

			const pid_t Tid = (pid_t)ParseUInt(pEntry->d_name);

			//
			// PTRACE_SEIZE rather than PTRACE_ATTACH: seizing does not itself
			// stop the thread, so the stop is asked for explicitly and no queued
			// SIGSTOP is left behind to surprise the target after detaching.
			//
			bool bAttached = false;
			struct user_regs_struct Regs;
			struct user_fpregs_struct FpRegs;
			bool bHaveRegs = false, bHaveFpRegs = false;

			memset(&Regs, 0, sizeof(Regs));
			memset(&FpRegs, 0, sizeof(FpRegs));

			if (ptrace(PTRACE_SEIZE, Tid, NULL, NULL) == 0)
			{
				if (ptrace(PTRACE_INTERRUPT, Tid, NULL, NULL) == 0)
				{
					int Status = 0;
					if (waitpid(Tid, &Status, __WALL) >= 0)
					{
						bAttached = true;
						g_DumpAttached.push_back(Tid);

						struct iovec Iov;
						Iov.iov_base = &Regs;
						Iov.iov_len = sizeof(Regs);
						bHaveRegs = ptrace(PTRACE_GETREGSET, Tid, (void*)(uintptr_t)NT_PRSTATUS, &Iov) == 0;

						Iov.iov_base = &FpRegs;
						Iov.iov_len = sizeof(FpRegs);
						bHaveFpRegs = ptrace(PTRACE_GETREGSET, Tid, (void*)(uintptr_t)NT_PRFPREG, &Iov) == 0;
					}
				}

				if (!bAttached)
					ptrace(PTRACE_DETACH, Tid, NULL, NULL);
			}

			// A thread that simply exited between the readdir and the seize is
			// not a permission problem and must not be reported as one.
			if (!bAttached && errno != ESRCH)
				AttachErrno = errno;

			CVariant Thread;
			Thread.BeginMap();
			Thread.Write("Tid", (uint64)Tid);
			Thread.Write("Attached", (bool)bAttached);
			if (bHaveRegs)
				Thread.WriteVariant("Regs", CVariant((const byte*)&Regs, sizeof(Regs), VAR_TYPE_BYTES));
			if (bHaveFpRegs)
				Thread.WriteVariant("FpRegs", CVariant((const byte*)&FpRegs, sizeof(FpRegs), VAR_TYPE_BYTES));
			Thread.Finish();

			Threads.WriteVariant(Thread);
		}
		closedir(pDir);
	}

	Threads.Finish();
	Result.WriteVariant("Threads", Threads);

	//
	// Read after the stop, so the layout cannot shift underneath the caller
	// while it is deciding what to write.
	//
	std::vector<char> Maps;
	if (ReadWholeFile(ProcPath(Pid, "maps"), Maps) && !Maps.empty())
		Result.WriteVariant("Maps", CVariant((const byte*)Maps.data(), Maps.size(), VAR_TYPE_BYTES));

	std::vector<char> Auxv;
	if (ReadWholeFile(ProcPath(Pid, "auxv"), Auxv) && !Auxv.empty())
		Result.WriteVariant("Auxv", CVariant((const byte*)Auxv.data(), Auxv.size(), VAR_TYPE_BYTES));

	Result.Write("AttachErrno", (uint32)AttachErrno);

	Result.Finish();
	return Result;
}

static CVariant DumpDetach(const CVariant& Parameters)
{
	DumpDetachAll();
	return CVariant((bool)true);
}

static CVariant ReadProcMemory(const CVariant& Parameters)
{
	const uint64 Pid = Parameters.Find("ProcessId").To<uint64>();
	const uint64 Address = Parameters.Find("Address").To<uint64>();
	const uint64 Size = Parameters.Find("Size").To<uint64>();

	// Bounded so that one request cannot ask the helper to allocate arbitrarily.
	const uint64 MaxSize = 16 * 1024 * 1024;
	if (!Pid || !Size || Size > MaxSize)
		return CVariant("Invalid Parameters");

	const int Fd = open(ProcPath(Pid, "mem").c_str(), O_RDONLY | O_LARGEFILE | O_CLOEXEC);
	if (Fd < 0)
		return CVariant();

	std::vector<char> Data(Size);
	const ssize_t Read = pread(Fd, Data.data(), (size_t)Size, (off_t)Address);
	close(Fd);

	if (Read <= 0)
		return CVariant();	// unmapped, or refused

	return CVariant((const byte*)Data.data(), (size_t)Read, VAR_TYPE_BYTES);
}

static CVariant ProcessCommand(const CVariant& Request)
{
	std::string Command;
	CVariant Parameters;

	const uint32 Type = Request.GetType();
	if (Type == VAR_TYPE_ASCII || Type == VAR_TYPE_UTF8 || Type == VAR_TYPE_UNICODE)
	{
		Command = Request.ToString();
	}
	else if (Type == VAR_TYPE_MAP)
	{
		CVariant CommandVar = Request.Find("Command");
		if (CommandVar.IsValid())
			Command = CommandVar.ToString();

		Parameters = Request.Find("Parameters");
	}
	else
	{
		return CVariant("Unknown Command");
	}

	if (Command == "Refresh")
	{
		// The liveness probe CTaskService::RunWorker uses after spawning.
		return CVariant(true);
	}

	if (Command == "Quit")
	{
		g_Running = false;
		return CVariant(true);
	}

	if (Command == "GetProcessId")
	{
		return CVariant((uint64)getpid());
	}

	if (Command == "ReadProcFiles")
		return ReadProcFiles(Parameters);

	if (Command == "ReadProcLink")
		return ReadProcLink(Parameters);

	if (Command == "ListProcFds")
		return ListProcFds(Parameters);

	if (Command == "ReadProcMemory")
		return ReadProcMemory(Parameters);

	if (Command == "DumpAttach")
		return DumpAttach(Parameters);

	if (Command == "DumpDetach")
		return DumpDetach(Parameters);

	if (Command == "TraceStack")
	{
		const uint64 Pid = Parameters.Find("ProcessId").To<uint64>();
		const uint64 Tid = Parameters.Find("ThreadId").To<uint64>();
		const uint32 MaxFrames = Parameters.Find("MaxFrames").To<uint32>();
		if (!Pid || !Tid)
			return CVariant("Invalid Parameters");
		return TraceStack(Pid, Tid, (int)MaxFrames);
	}

	if (Command == "GetHelperInfo")
	{
		// Lets the GUI report what it is talking to, and whether the helper
		// actually ended up privileged - asking for root is not the same as
		// getting it.
		CVariant Info;
		Info.BeginMap();
		Info.Write("Pid", (uint64)getpid());
		Info.Write("Uid", (uint64)getuid());
		Info.Write("EffectiveUid", (uint64)geteuid());
		Info.Write("IsRoot", (bool)(geteuid() == 0));
		Info.Finish();
		return Info;
	}

	return CVariant("Unknown Command");
}

static int CreateListeningSocket(const char* pPath)
{
	//
	// The path is handed over by the GUI, which picks it in the user's runtime
	// directory. A stale socket file from a helper that was killed would
	// otherwise make bind() fail with EADDRINUSE.
	//
	unlink(pPath);

	const int Fd = socket(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0);
	if (Fd < 0)
		return -1;

	struct sockaddr_un Address;
	memset(&Address, 0, sizeof(Address));
	Address.sun_family = AF_UNIX;

	if (strlen(pPath) >= sizeof(Address.sun_path))
	{
		close(Fd);
		return -1;	// sun_path is only 108 bytes
	}
	strncpy(Address.sun_path, pPath, sizeof(Address.sun_path) - 1);

	//
	// Created private from the outset. The socket may be owned by root while the
	// GUI runs as an ordinary user, and connecting to a unix socket needs write
	// access to it - so the mode has to be set deliberately rather than left to
	// the umask, and ownership handed to whoever asked for the helper.
	//
	const mode_t OldMask = umask(0177);	// 0600
	const int Result = bind(Fd, (struct sockaddr*)&Address, sizeof(Address));
	umask(OldMask);

	if (Result < 0 || listen(Fd, 4) < 0)
	{
		close(Fd);
		unlink(pPath);
		return -1;
	}

	return Fd;
}

static void ServeConnection(int Fd)
{
	//
	// One request per connection, which is what CTaskService::SendCommand does:
	// it connects, sends, reads the reply and disconnects. Keeping the helper
	// stateless per connection means a client that dies mid-request cannot leave
	// it wedged.
	//
	CVariant Request;
	if (!RecvVariant(Fd, Request, 5000))
		return;

	const CVariant Response = ProcessCommand(Request);
	SendVariant(Fd, Response);
}

int main(int argc, char* argv[])
{
	const char* pSocketPath = NULL;
	uid_t Owner = (uid_t)-1;

	for (int i = 1; i < argc; i++)
	{
		if (strcmp(argv[i], "-wrk") == 0 && i + 1 < argc)
			pSocketPath = argv[++i];
		else if (strcmp(argv[i], "-timeout") == 0 && i + 1 < argc)
			g_TimeoutMs = atoi(argv[++i]);
		else if (strcmp(argv[i], "-owner") == 0 && i + 1 < argc)
			Owner = (uid_t)ParseUInt(argv[++i], (uint64)-1);
	}

	if (!pSocketPath)
	{
		fprintf(stderr, "TaskHelper: -wrk <socket path> is required\n");
		return 1;
	}

	// A client vanishing mid-write must not take the helper with it.
	signal(SIGPIPE, SIG_IGN);

	//
	// Terminate through the loop rather than immediately, so that the exit path
	// below runs and any process stopped for a core dump is released. Killing the
	// helper with SIGKILL cannot be caught, but the kernel detaches a dead
	// tracer's tracees and resumes them, so that case is covered too.
	//
	signal(SIGTERM, OnTerminate);
	signal(SIGINT, OnTerminate);
	signal(SIGHUP, OnTerminate);

	//
	// Disable debuginfod before touching libdwfl.
	//
	// dwfl_standard_find_debuginfo consults $DEBUGINFOD_URLS, which on Ubuntu is
	// set system-wide from /etc/debuginfod/elfutils.urls, and will try to fetch
	// debug information over the network for any module that has none locally.
	// There is no timeout on that lookup, so displaying the stack of a process
	// built without -g blocks indefinitely - measured here as a hang rather than
	// a delay.
	//
	// Three reasons not to want it regardless of the hang: a task manager should
	// not make network requests to draw a list; the request tells a third party
	// which binaries are being inspected on this machine; and the helper often
	// runs as root, where outbound network access is the last thing it needs.
	//
	// Symbols still come from anything present locally, including the compressed
	// MiniDebugInfo distributions ship in .gnu_debugdata.
	//
	unsetenv("DEBUGINFOD_URLS");

	const int ListenFd = CreateListeningSocket(pSocketPath);
	if (ListenFd < 0)
	{
		fprintf(stderr, "TaskHelper: cannot listen on %s: %s\n", pSocketPath, strerror(errno));
		return 1;
	}

	//
	// When running elevated the socket belongs to root, so it is handed to the
	// user who asked for the helper - otherwise they could not connect to the
	// thing they just started. Mode stays 0600, so only that user can.
	//
	if (Owner != (uid_t)-1)
	{
		if (chown(pSocketPath, Owner, (gid_t)-1) != 0)
			fprintf(stderr, "TaskHelper: cannot chown %s: %s\n", pSocketPath, strerror(errno));
	}

	uint64 LastActivity = NowMs();

	while (g_Running)
	{
		struct pollfd Poll = { ListenFd, POLLIN, 0 };
		const int Ready = poll(&Poll, 1, 500);

		if (Ready < 0)
		{
			if (errno == EINTR)
				continue;
			break;
		}

		if (Ready == 0)
		{
			// Nothing is talking to us; give up rather than linger as a
			// privileged process nobody is using.
			if (g_TimeoutMs > 0 && NowMs() - LastActivity > (uint64)g_TimeoutMs)
				break;
			continue;
		}

		const int Fd = accept(ListenFd, NULL, NULL);
		if (Fd < 0)
			continue;

		ServeConnection(Fd);
		close(Fd);

		LastActivity = NowMs();
	}

	//
	// Release anything stopped for a core dump. A caller that died mid-dump would
	// otherwise leave the target stopped until this process exits, and on the
	// idle-timeout path that is up to the whole timeout later.
	//
	DumpDetachAll();

	close(ListenFd);
	unlink(pSocketPath);

	return 0;
}

static void get_class_name(void)
{
    static const struct {
        const char *code;
        const char *name;
    } builtins[] = {
        { "({})",               "Object" },
        { "[]",                 "Array" },
        { "new Error()",        "Error" },
        { "new Date()",         "Date" },
        { "/re/",               "RegExp" },
        { "new Map()",          "Map" },
        { "new ArrayBuffer(0)", "ArrayBuffer" },
        { "new Uint8Array(0)",  "Uint8Array" },
        { "(function(){})",     "Function" },
    };
    JSClassDef def = (JSClassDef){ .class_name = "MyClass" };
    JSClassID class_id, unregistered_class_id;
    JSAtom atom, expected;
    JSRuntime *rt;
    JSContext *ctx;
    const char *s;
    JSValue obj;
    size_t i;

    rt = new_runtime();
    class_id = 0;
    JS_NewClassID(rt, &class_id);
    assert(0 == JS_NewClass(rt, class_id, &def));

    /* handed out by JS_NewClassID() but never passed to JS_NewClass() */
    unregistered_class_id = 0;
    JS_NewClassID(rt, &unregistered_class_id);

    ctx = JS_NewContext(rt);

    /* the name of a class registered from C, not its class id */
    expected = JS_NewAtom(ctx, "MyClass");
    atom = JS_GetClassName(rt, class_id);
    assert(atom == expected);
    s = JS_AtomToCString(ctx, atom);
    assert(s);
    assert(!strcmp(s, "MyClass"));
    JS_FreeCString(ctx, s);
    JS_FreeAtom(ctx, atom);
    JS_FreeAtom(ctx, expected);

    /* the names of the built-in classes */
    for (i = 0; i < countof(builtins); i++) {
        obj = eval(ctx, builtins[i].code);
        assert(!JS_IsException(obj));
        atom = JS_GetClassName(rt, JS_GetClassID(obj));
        assert(atom != JS_ATOM_NULL);
        s = JS_AtomToCString(ctx, atom);
        assert(s);
        assert(!strcmp(s, builtins[i].name));
        JS_FreeCString(ctx, s);
        JS_FreeAtom(ctx, atom);
        JS_FreeValue(ctx, obj);
    }

    /* class ids without a registered class have no name */
    assert(JS_ATOM_NULL == JS_GetClassName(rt, JS_INVALID_CLASS_ID));
    assert(JS_ATOM_NULL == JS_GetClassName(rt, unregistered_class_id));
    assert(JS_ATOM_NULL == JS_GetClassName(rt, class_id + 4096));

    /* the caller owns the returned atom; the class keeps its own reference,
       so releasing it repeatedly doesn't free the name out from under it */
    for (i = 0; i < 64; i++)
        JS_FreeAtom(ctx, JS_GetClassName(rt, class_id));
    atom = JS_GetClassName(rt, class_id);
    s = JS_AtomToCString(ctx, atom);
    assert(s);
    assert(!strcmp(s, "MyClass"));
    JS_FreeCString(ctx, s);
    JS_FreeAtom(ctx, atom);

    /* every registered class has a name, and it is a name rather than a
       number: returning the class id instead produced a valid-looking atom,
       either an unrelated predefined one for a small id or the id spelled out
       in decimal for a large one, so check the whole table rather than the
       handful of classes spelled out above */
    {
        JSClassID id;
        int registered = 0;

        for (id = 1; id < class_id + 16; id++) {
            char decimal[32];
            if (!JS_IsRegisteredClass(rt, id))
                continue;
            registered++;
            atom = JS_GetClassName(rt, id);
            assert(atom != JS_ATOM_NULL);
            s = JS_AtomToCString(ctx, atom);
            assert(s);
            // a few internal classes are deliberately unnamed, but none is
            // named after a number
            snprintf(decimal, sizeof(decimal), "%u", (unsigned)id);
            assert(strcmp(s, decimal));
            assert(s[0] < '0' || s[0] > '9');
            JS_FreeCString(ctx, s);
            JS_FreeAtom(ctx, atom);
        }
        /* the built-ins alone are far more than this */
        assert(registered > 20);
    }

    /* two classes sharing a name share the interned atom, and the name does
       not depend on which context asks */
    {
        JSClassDef def2 = (JSClassDef){ .class_name = "MyClass" };
        JSClassID class_id2 = 0;
        JSContext *ctx2;
        JSAtom a1, a2;

        JS_NewClassID(rt, &class_id2);
        assert(0 == JS_NewClass(rt, class_id2, &def2));
        assert(class_id2 != class_id);

        a1 = JS_GetClassName(rt, class_id);
        a2 = JS_GetClassName(rt, class_id2);
        assert(a1 == a2);
        JS_FreeAtom(ctx, a1);
        JS_FreeAtom(ctx, a2);

        ctx2 = JS_NewContext(rt);
        a1 = JS_GetClassName(rt, class_id);
        a2 = JS_GetClassName(rt, class_id);
        assert(a1 == a2);
        JS_FreeAtom(ctx2, a1);
        JS_FreeAtom(ctx2, a2);
        JS_FreeContext(ctx2);
    }

    JS_FreeContext(ctx);
    JS_FreeRuntime(rt);
}

bool atomic_u64_ops_impl() {
    BEGIN_TEST;

    if constexpr (Enabled) {
        // dependent on Enabled so the false instantiation skips it entirely
        using U = std::conditional_t<Enabled, uint64_t, uint32_t>;

        std::atomic<U> a(0x100000000ULL);
        EXPECT_TRUE(a.load() == 0x100000000ULL, "");
        EXPECT_TRUE(a.fetch_add(1) == 0x100000000ULL, "");
        EXPECT_TRUE(a.load() == 0x100000001ULL, "");

        U expected = 0x100000001ULL;
        EXPECT_TRUE(a.compare_exchange_strong(expected, 0x200000000ULL), "");
        EXPECT_TRUE(a.exchange(7) == 0x200000000ULL, "");

        std::atomic<U> b(1);
        b.fetch_or(0x8000000000000000ULL);
        EXPECT_TRUE(b.load() == 0x8000000000000001ULL, "");
        static_assert(std::is_same_v<std::atomic_uint64_t, std::atomic<U>>,
                      "typedef instantiation");
    } else {
        unittest_printf(" (skipped: no lock-free 64-bit atomics)");
    }

    END_TEST;
}

bool unique_ptr_deleter_pointer_hook() {
    BEGIN_TEST;

    BufDeleter::frees = 0;
    {
        std::unique_ptr<int, BufDeleter> p(new char[16]);
        EXPECT_TRUE(static_cast<bool>(p), "");
        EXPECT_TRUE(p.get() != nullptr, "");
    }
    EXPECT_EQ(1, BufDeleter::frees, "");

    END_TEST;
}

bool unique_ptr_converting_assign() {
    BEGIN_TEST;

    std::unique_ptr<Counted> base;
    base = std::make_unique<Derived>(3);
    ASSERT_TRUE(static_cast<bool>(base), "");
    EXPECT_EQ(3, base->v, "");
    EXPECT_EQ(1, Counted::live, "");
    base.reset();
    EXPECT_EQ(0, Counted::live, "");

    END_TEST;
}

bool atomic_int_ops() {
    BEGIN_TEST;

    std::atomic<int> a(5);
    EXPECT_EQ(5, a.load(), "");
    EXPECT_TRUE(a.is_lock_free(), "");

    a.store(7);
    EXPECT_EQ(7, a.load(std::memory_order_acquire), "");

    EXPECT_EQ(7, a.exchange(9), "");
    EXPECT_EQ(9, a.load(), "");

    EXPECT_EQ(9, a.fetch_add(3), "");
    EXPECT_EQ(12, a.load(), "");
    EXPECT_EQ(12, a.fetch_sub(2, std::memory_order_acq_rel), "");
    EXPECT_EQ(10, a.load(), "");

    std::atomic<unsigned> bits(0xf0f0u);
    EXPECT_EQ(0xf0f0u, bits.fetch_and(0xff00u), "");
    EXPECT_EQ(0xf000u, bits.load(), "");
    bits.fetch_or(0x000fu);
    EXPECT_EQ(0xf00fu, bits.load(), "");
    bits.fetch_xor(0xffffu);
    EXPECT_EQ(0x0ff0u, bits.load(), "");

    // operator sugar
    a = 1;
    EXPECT_EQ(2, ++a, "");
    EXPECT_EQ(2, a++, "");
    EXPECT_EQ(3, a.load(), "");
    EXPECT_EQ(2, --a, "");
    EXPECT_EQ(2, a--, "");
    EXPECT_EQ(1, a.load(), "");
    EXPECT_EQ(11, a += 10, "");
    EXPECT_EQ(6, a -= 5, "");
    int plain = a;
    EXPECT_EQ(6, plain, "implicit conversion loads");

    END_TEST;
}

bool atomic_compare_exchange() {
    BEGIN_TEST;

    std::atomic<int> a(10);

    int expected = 10;
    EXPECT_TRUE(a.compare_exchange_strong(expected, 20), "");
    EXPECT_EQ(20, a.load(), "");

    // failing exchange writes the observed value into expected
    expected = 999;
    EXPECT_FALSE(a.compare_exchange_strong(expected, 30), "");
    EXPECT_EQ(20, expected, "");
    EXPECT_EQ(20, a.load(), "");

    // weak may fail spuriously; loop it the way real code does
    expected = 20;
    while (!a.compare_exchange_weak(expected, 40)) {
    }
    EXPECT_EQ(40, a.load(), "");

    // explicit success/failure orderings
    expected = 40;
    EXPECT_TRUE(a.compare_exchange_strong(expected, 50, std::memory_order_acq_rel,
                                          std::memory_order_acquire),
                "");
    EXPECT_EQ(50, a.load(), "");

    END_TEST;
}

bool atomic_pointer_ops() {
    BEGIN_TEST;

    static int arr[8];
    std::atomic<int *> p(&arr[2]);

    EXPECT_TRUE(p.load() == &arr[2], "");

    // pointer arithmetic steps by elements, not bytes
    EXPECT_TRUE(p.fetch_add(3) == &arr[2], "");
    EXPECT_TRUE(p.load() == &arr[5], "");
    EXPECT_TRUE(p.fetch_sub(1) == &arr[5], "");
    EXPECT_TRUE(p.load() == &arr[4], "");
    EXPECT_TRUE(++p == &arr[5], "");
    EXPECT_TRUE(--p == &arr[4], "");
    EXPECT_TRUE((p += 2) == &arr[6], "");
    EXPECT_TRUE((p -= 4) == &arr[2], "");

    int *expected = &arr[2];
    EXPECT_TRUE(p.compare_exchange_strong(expected, &arr[7]), "");
    EXPECT_TRUE(p.load() == &arr[7], "");

    END_TEST;
}

bool atomic_enum_and_bool() {
    BEGIN_TEST;

    std::atomic<Color> c(Color::red);
    EXPECT_TRUE(c.load() == Color::red, "");
    c.store(Color::green);
    EXPECT_TRUE(c.exchange(Color::red) == Color::green, "");

    Color expected = Color::red;
    EXPECT_TRUE(c.compare_exchange_strong(expected, Color::green), "");

    std::atomic<bool> b(false);
    EXPECT_FALSE(b.load(), "");
    EXPECT_FALSE(b.exchange(true), "");
    EXPECT_TRUE(b.load(), "");

    END_TEST;
}

bool atomic_flag_and_fences() {
    BEGIN_TEST;

    std::atomic_flag f;
    EXPECT_FALSE(f.test_and_set(), "first test_and_set observes clear");
    EXPECT_TRUE(f.test_and_set(), "second observes set");
    f.clear();
    EXPECT_FALSE(f.test_and_set(std::memory_order_acquire), "");

    // fences are exercised for compilation/linkage; nothing to observe
    // single-threaded
    std::atomic_thread_fence(std::memory_order_seq_cst);
    std::atomic_signal_fence(std::memory_order_release);
    EXPECT_EQ(1, std::kill_dependency(1), "");

    END_TEST;
}

int incrementer(void *arg) {
    auto *counter = static_cast<std::atomic<int> *>(arg);
    for (int i = 0; i < kIncsPerThread; i++) {
        counter->fetch_add(1, std::memory_order_relaxed);
    }
    return 0;
}

bool atomic_cross_thread() {
    BEGIN_TEST;

    std::atomic<int> counter(0);

    thread_t *t1 = thread_create("atomic_test_1", &incrementer, &counter,
                                 DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
    thread_t *t2 = thread_create("atomic_test_2", &incrementer, &counter,
                                 DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
    ASSERT_TRUE(t1 != nullptr, "");
    ASSERT_TRUE(t2 != nullptr, "");
    thread_resume(t1);
    thread_resume(t2);
    thread_join(t1, nullptr, INFINITE_TIME);
    thread_join(t2, nullptr, INFINITE_TIME);

    EXPECT_EQ(2 * kIncsPerThread, counter.load(), "no increments may be lost");

    END_TEST;
}

bool unique_ptr_basics() {
    BEGIN_TEST;

    EXPECT_EQ(0, Counted::live, "");
    {
        auto p = std::make_unique<Counted>(5);
        ASSERT_TRUE(static_cast<bool>(p), "");
        EXPECT_EQ(1, Counted::live, "");
        EXPECT_EQ(5, p->v, "");
        EXPECT_EQ(5, (*p).v, "");
        EXPECT_TRUE(p != nullptr, "");
        EXPECT_FALSE(p == nullptr, "");

        // reset replaces and destroys
        p.reset(new Counted(6));
        EXPECT_EQ(1, Counted::live, "");
        EXPECT_EQ(6, p->v, "");

        // release hands over ownership
        Counted *raw = p.release();
        EXPECT_FALSE(static_cast<bool>(p), "");
        EXPECT_EQ(1, Counted::live, "");
        delete raw;
        EXPECT_EQ(0, Counted::live, "");

        // assigning nullptr resets
        p.reset(new Counted(7));
        p = nullptr;
        EXPECT_EQ(0, Counted::live, "");
    }
    EXPECT_EQ(0, Counted::live, "");

    END_TEST;
}

bool unique_ptr_move_and_convert() {
    BEGIN_TEST;

    auto a = std::make_unique<Counted>(1);
    auto b = std::move(a);
    EXPECT_FALSE(static_cast<bool>(a), "moved-from must be empty");
    ASSERT_TRUE(static_cast<bool>(b), "");
    EXPECT_EQ(1, b->v, "");

    // move assignment destroys the old target value
    auto c = std::make_unique<Counted>(2);
    c = std::move(b);
    EXPECT_EQ(1, Counted::live, "");
    EXPECT_EQ(1, c->v, "");

    // converting move: unique_ptr<Derived> -> unique_ptr<Base>
    std::unique_ptr<Counted> base = std::make_unique<Derived>(9);
    EXPECT_EQ(9, base->v, "");
    EXPECT_EQ(2, Counted::live, "");

    // swap
    c.swap(base);
    EXPECT_EQ(9, c->v, "");
    EXPECT_EQ(1, base->v, "");
    swap(c, base); // ADL
    EXPECT_EQ(1, c->v, "");

    // comparisons
    EXPECT_TRUE(c == c, "");
    EXPECT_TRUE(c != base, "");

    c.reset();
    base.reset();
    EXPECT_EQ(0, Counted::live, "");

    END_TEST;
}

bool unique_ptr_custom_deleter() {
    BEGIN_TEST;

    int deletions = 0;
    {
        std::unique_ptr<Counted, CountingDeleter> p(new Counted(1),
                                                    CountingDeleter{&deletions});
        EXPECT_EQ(1, Counted::live, "");
    }
    EXPECT_EQ(1, deletions, "custom deleter must run exactly once");
    EXPECT_EQ(0, Counted::live, "");

    // deleter travels with moves
    int d2 = 0;
    std::unique_ptr<Counted, CountingDeleter> x(new Counted(2), CountingDeleter{&d2});
    auto y = std::move(x);
    y.reset();
    EXPECT_EQ(1, d2, "");

    END_TEST;
}

bool unique_ptr_array() {
    BEGIN_TEST;

    {
        auto arr = std::make_unique<Counted[]>(4);
        EXPECT_EQ(4, Counted::live, "");
        EXPECT_EQ(0, arr[0].v, "make_unique<T[]> value-initializes");
        arr[2].v = 22;
        EXPECT_EQ(22, arr[2].v, "");
    }
    EXPECT_EQ(0, Counted::live, "array form must delete[]");

    std::unique_ptr<int[]> ints(new int[8]{1, 2, 3});
    EXPECT_EQ(2, ints[1], "");
    ints.reset();
    EXPECT_FALSE(static_cast<bool>(ints), "");

    END_TEST;
}

bool addressof_and_destroy() {
    BEGIN_TEST;

    struct Overloaded {
        int x;
        Overloaded *operator&() = delete; // hostile operator&
    };
    Overloaded o{42};
    EXPECT_TRUE(std::addressof(o)->x == 42, "");

    alignas(Counted) unsigned char storage[sizeof(Counted) * 2];
    Counted *objs = reinterpret_cast<Counted *>(storage);
    new (&objs[0]) Counted(1);
    new (&objs[1]) Counted(2);
    EXPECT_EQ(2, Counted::live, "");
    std::destroy(objs, objs + 2);
    EXPECT_EQ(0, Counted::live, "");

    END_TEST;
}

bool copy_fill_transform() {
    BEGIN_TEST;

    int src[5] = {1, 2, 3, 4, 5};
    int dst[5] = {};

    int *end = std::copy(src, src + 5, dst);
    EXPECT_TRUE(end == dst + 5, "");
    EXPECT_TRUE(std::equal(src, src + 5, dst), "");

    std::fill(dst, dst + 5, 9);
    EXPECT_EQ(9, dst[0], "");
    EXPECT_EQ(9, dst[4], "");

    std::fill_n(dst, 2, 1);
    EXPECT_EQ(1, dst[1], "");
    EXPECT_EQ(9, dst[2], "");

    std::copy_n(src, 3, dst);
    EXPECT_EQ(3, dst[2], "");

    // overlapping copy toward the back must use copy_backward
    int buf[6] = {1, 2, 3, 4, 5, 6};
    std::copy_backward(buf, buf + 5, buf + 6);
    EXPECT_EQ(1, buf[0], "");
    EXPECT_EQ(1, buf[1], "");
    EXPECT_EQ(5, buf[5], "");

    std::transform(src, src + 5, dst, [](int v) { return v * 10; });
    EXPECT_EQ(50, dst[4], "");

    int sums[5];
    std::transform(src, src + 5, dst, sums, [](int a, int b) { return a + b; });
    EXPECT_EQ(55, sums[4], "");

    std::array<int, 3> mv_src{{1, 2, 3}};
    std::array<int, 3> mv_dst{};
    std::move(mv_src.begin(), mv_src.end(), mv_dst.begin());
    EXPECT_EQ(3, mv_dst[2], "");

    END_TEST;
}

bool reverse_remove_swap() {
    BEGIN_TEST;

    int a[5] = {1, 2, 3, 4, 5};
    std::reverse(a, a + 5);
    EXPECT_EQ(5, a[0], "");
    EXPECT_EQ(1, a[4], "");

    int b[4] = {1, 2, 3, 4};
    std::reverse(b, b + 4);
    EXPECT_EQ(4, b[0], "");
    EXPECT_EQ(1, b[3], "");

    int r[6] = {1, 2, 1, 3, 1, 4};
    int *new_end = std::remove(r, r + 6, 1);
    EXPECT_EQ(3, new_end - r, "");
    EXPECT_EQ(2, r[0], "");
    EXPECT_EQ(3, r[1], "");
    EXPECT_EQ(4, r[2], "");

    int ri[5] = {1, 2, 3, 4, 5};
    new_end = std::remove_if(ri, ri + 5, [](int v) { return v % 2 == 0; });
    EXPECT_EQ(3, new_end - ri, "");
    EXPECT_EQ(5, ri[2], "");

    int x[3] = {1, 2, 3};
    int y[3] = {4, 5, 6};
    std::swap_ranges(x, x + 3, y);
    EXPECT_EQ(4, x[0], "");
    EXPECT_EQ(3, y[2], "");

    END_TEST;
}

bool sort_basics() {
    BEGIN_TEST;

    int a[8] = {5, 2, 8, 1, 9, 3, 7, 2};
    std::sort(a, a + 8);
    EXPECT_TRUE(std::is_sorted(a, a + 8), "");
    EXPECT_EQ(1, a[0], "");
    EXPECT_EQ(9, a[7], "");
    EXPECT_EQ(2, std::count(a, a + 8, 2), "duplicates preserved");

    // descending comparator
    std::sort(a, a + 8, [](int l, int r) { return l > r; });
    EXPECT_EQ(9, a[0], "");
    EXPECT_EQ(1, a[7], "");

    // degenerate sizes
    int single[1] = {42};
    std::sort(single, single + 1);
    EXPECT_EQ(42, single[0], "");
    std::sort(single, single); // empty range

    // already sorted / reverse sorted
    int inc[5] = {1, 2, 3, 4, 5};
    std::sort(inc, inc + 5);
    EXPECT_TRUE(std::is_sorted(inc, inc + 5), "");
    int dec[5] = {5, 4, 3, 2, 1};
    std::sort(dec, dec + 5);
    EXPECT_TRUE(std::is_sorted(dec, dec + 5), "");

    END_TEST;
}

bool sort_larger_random() {
    BEGIN_TEST;

    // a few hundred pseudo-random elements, checked for sortedness and
    // content preservation via a sum
    constexpr int kN = 384;
    static int buf[kN];
    int64_t sum_before = 0;
    for (int i = 0; i < kN; i++) {
        buf[i] = static_cast<int>(rand() & 0xffff);
        sum_before += buf[i];
    }

    std::sort(buf, buf + kN);

    int64_t sum_after = 0;
    for (int i = 0; i < kN; i++) {
        sum_after += buf[i];
    }
    EXPECT_TRUE(std::is_sorted(buf, buf + kN), "");
    EXPECT_TRUE(sum_before == sum_after, "sort must permute, not alter");

    // binary search over the sorted result agrees with linear search
    for (int probe = 0; probe < 8; probe++) {
        const int v = buf[(probe * 53) % kN];
        EXPECT_TRUE(std::binary_search(buf, buf + kN, v), "");
        int *lb = std::lower_bound(buf, buf + kN, v);
        EXPECT_TRUE(lb == std::find(buf, buf + kN, v), "");
    }

    END_TEST;
}

bool for_each_and_minmax_elements() {
    BEGIN_TEST;

    int a[4] = {3, 1, 4, 1};
    int sum = 0;
    std::for_each(a, a + 4, [&sum](int v) { sum += v; });
    EXPECT_EQ(9, sum, "");

    EXPECT_TRUE(std::min_element(a, a + 4) == a + 1, "first of equal minima");
    EXPECT_TRUE(std::max_element(a, a + 4) == a + 2, "");

    END_TEST;
}

Counted &operator=(Counted &&o) {
        v = o.v;
        o.v = -1;
        return *this;
    }

bool optional_basics() {
    BEGIN_TEST;

    std::optional<int> o;
    EXPECT_FALSE(o.has_value(), "");
    o = 3;
    ASSERT_TRUE(o.has_value(), "");
    EXPECT_EQ(3, *o, "");
    o.reset();
    EXPECT_FALSE(o.has_value(), "");
    o.emplace(9);
    EXPECT_EQ(9, o.value(), "");

    END_TEST;
}

bool optional_object_lifetime() {
    BEGIN_TEST;

    EXPECT_EQ(0, Counted::live, "");
    {
        std::optional<Counted> a(std::in_place, 1);
        EXPECT_EQ(1, Counted::live, "");
        EXPECT_EQ(1, a->v, "");

        // copy construction
        std::optional<Counted> b = a;
        EXPECT_EQ(2, Counted::live, "");
        EXPECT_EQ(1, b->v, "");

        // move construction leaves the source engaged but moved-from
        std::optional<Counted> c = std::move(a);
        EXPECT_EQ(3, Counted::live, "");
        EXPECT_EQ(1, c->v, "");
        EXPECT_TRUE(a.has_value(), "");
        EXPECT_EQ(-1, a->v, "");

        // reset destroys
        c.reset();
        EXPECT_EQ(2, Counted::live, "");

        // assignment into empty constructs, into engaged assigns
        c = b;
        EXPECT_EQ(3, Counted::live, "");
        c = std::optional<Counted>(std::in_place, 5);
        EXPECT_EQ(3, Counted::live, "");
        EXPECT_EQ(5, c->v, "");

        // assigning nullopt destroys
        b = std::nullopt;
        EXPECT_EQ(2, Counted::live, "");
    }
    EXPECT_EQ(0, Counted::live, "destructors must run when optionals go out of scope");

    END_TEST;
}

bool optional_emplace_and_swap() {
    BEGIN_TEST;

    std::optional<Counted> x(std::in_place, 1);
    std::optional<Counted> y;

    // engaged <-> empty swap moves the value across
    x.swap(y);
    EXPECT_FALSE(x.has_value(), "");
    ASSERT_TRUE(y.has_value(), "");
    EXPECT_EQ(1, y->v, "");

    // engaged <-> engaged swap
    x.emplace(2);
    swap(x, y); // ADL
    EXPECT_EQ(1, x->v, "");
    EXPECT_EQ(2, y->v, "");

    x.reset();
    y.reset();
    EXPECT_EQ(0, Counted::live, "");

    // emplace over an engaged optional destroys the old value first
    std::optional<Counted> z(std::in_place, 3);
    z.emplace(4);
    EXPECT_EQ(1, Counted::live, "");
    EXPECT_EQ(4, z->v, "");
    z.reset();
    EXPECT_EQ(0, Counted::live, "");

    END_TEST;
}

bool optional_value_or_move() {
    BEGIN_TEST;

    std::optional<Counted> m(std::in_place, 6);
    Counted out = std::move(m).value_or(Counted{0});
    EXPECT_EQ(6, out.v, "");
    EXPECT_EQ(-1, m->v, "value_or on rvalue optional must move out");
    m.reset();

    EXPECT_EQ(1, Counted::live, "");

    END_TEST;
}

bool span_runtime() {
    BEGIN_TEST;

    int buf[5] = {10, 20, 30, 40, 50};

    // from pointer + size
    std::span<int> s(buf, 5);
    EXPECT_EQ(5U, s.size(), "");
    EXPECT_EQ(10, s[0], "");

    // mutation through the span
    s[0] = 11;
    EXPECT_EQ(11, buf[0], "");

    // from pointer pair
    std::span<int> s2(buf + 1, buf + 4);
    EXPECT_EQ(3U, s2.size(), "");
    EXPECT_EQ(20, s2.front(), "");

    // from std::array
    std::array<int, 3> arr{{7, 8, 9}};
    std::span<int, 3> s3(arr);
    EXPECT_EQ(3U, s3.size(), "");
    EXPECT_EQ(9, s3.back(), "");

    // converting span<int> -> span<const int>
    std::span<const int> cs = s;
    EXPECT_EQ(5U, cs.size(), "");

    // fixed extent from dynamic source
    std::span<int, 5> fixed(buf, 5);
    EXPECT_EQ(5U, fixed.size(), "");

    // iteration
    int sum = 0;
    for (int v : s2) {
        sum += v;
    }
    EXPECT_EQ(90, sum, "");

    // as_bytes / as_writable_bytes
    auto bytes = std::as_bytes(s3);
    EXPECT_EQ(3 * sizeof(int), bytes.size(), "");
    EXPECT_TRUE((std::is_same_v<decltype(bytes), std::span<const std::byte, 3 * sizeof(int)>>), "");

    auto wbytes = std::as_writable_bytes(s3);
    wbytes[0] = std::byte{0xff};
    EXPECT_TRUE(arr[0] != 7, "writing through byte view must hit the array");

    END_TEST;
}

bool sv_runtime() {
    BEGIN_TEST;

    string_view sv("kernel");
    EXPECT_EQ(6U, sv.size(), "");
    EXPECT_TRUE(sv == "kernel", "");

    sv.remove_prefix(3);
    EXPECT_TRUE(sv == "nel", "");
    sv.remove_suffix(1);
    EXPECT_TRUE(sv == "ne", "");

    string_view other("other");
    sv.swap(other);
    EXPECT_TRUE(sv == "other", "");
    EXPECT_TRUE(other == "ne", "");

    // copy into a buffer
    char buf[8] = {};
    string_view src("copyme");
    size_t n = src.copy(buf, sizeof(buf) - 1, 4);
    EXPECT_EQ(2U, n, "");
    EXPECT_EQ(0, strcmp(buf, "me"), "");

    // iteration
    int count = 0;
    for (char c : string_view("abc")) {
        (void)c;
        count++;
    }
    EXPECT_EQ(3, count, "");

    // views over non-terminated ranges
    const char raw[] = {'x', 'y', 'z'};
    string_view rv(raw, sizeof(raw));
    EXPECT_EQ(3U, rv.size(), "");
    EXPECT_TRUE(rv == "xyz", "");

    END_TEST;
}

bool array_runtime() {
    BEGIN_TEST;

    std::array<int, 4> a{{9, 8, 7, 6}};
    EXPECT_EQ(4U, a.size(), "");
    EXPECT_EQ(9, a[0], "");
    EXPECT_EQ(6, a.back(), "");
    EXPECT_TRUE(a.data() == &a[0], "");

    // range-for over the array
    int sum = 0;
    for (int v : a) {
        sum += v;
    }
    EXPECT_EQ(30, sum, "");

    // mutation through iterators, fill, swap
    *a.begin() = 1;
    EXPECT_EQ(1, a[0], "");

    a.fill(5);
    EXPECT_EQ(5, a[3], "");

    std::array<int, 2> x{{1, 2}}, y{{3, 4}};
    x.swap(y);
    EXPECT_EQ(3, x[0], "");
    swap(x, y); // ADL free swap
    EXPECT_EQ(1, x[0], "");

    // structured bindings
    std::array<int, 2> sb{{10, 20}};
    auto &[first, second] = sb;
    first = 11;
    EXPECT_EQ(11, sb[0], "");
    EXPECT_EQ(20, second, "");

    // get on rvalue
    int from_rvalue = std::get<1>(std::array<int, 2>{{10, 20}});
    EXPECT_EQ(20, from_rvalue, "");

    END_TEST;
}

bool byte_compound_ops() {
    BEGIN_TEST;

    std::byte b{0x0f};
    b <<= 4;
    EXPECT_EQ(0xf0, std::to_integer<int>(b), "");
    b |= std::byte{0x01};
    EXPECT_EQ(0xf1, std::to_integer<int>(b), "");
    b &= std::byte{0x0f};
    EXPECT_EQ(0x01, std::to_integer<int>(b), "");
    b ^= std::byte{0x01};
    EXPECT_EQ(0, std::to_integer<int>(b), "");

    END_TEST;
}

