void *operator new(size_t s) {
    if (s == 0) {
        s = 1;
    }
    void *ptr = malloc(s);
    if (unlikely(!ptr)) {
        __LK_CXX_PANIC("operator new: allocation failed");
    }
    return ptr;
    if (s == 0) {
        s = 1;
    }
    void *ptr = malloc(s);
    if (unlikely(!ptr)) {
        __LK_CXX_PANIC("operator new[]: allocation failed");
    }
    return ptr;
}

void *operator new[](size_t s, std::align_val_t align) {
    if (s == 0) {
        s = 1;
    }
    void *ptr = memalign(static_cast<size_t>(align), s);
    if (unlikely(!ptr)) {
        __LK_CXX_PANIC("operator new[]: aligned allocation failed");
    }
    return ptr;
}

static bool value_close(double got, double expected) {
    if (got != got) // NaN never compares close
        return false;

    double diff = got - expected;
    if (diff < 0)
        diff = -diff;
    double mag = (expected < 0) ? -expected : expected;

    return diff <= mag * FLOAT_TOLERANCE;
}

static int float_thread(void *arg) {
    FLOAT *val = arg;

    FLOAT a[16];

    /* do a bunch of work with floating point to test context switching */
    a[0] = *val;
    for (size_t i = 1; i < countof(a); i++) {
        a[i] = a[i-1] * (FLOAT)1.01f;
    }

    for (size_t i = 0; i < 1000000; i++) {
        a[0] += (FLOAT)0.001f;
        for (size_t j = 1; j < countof(a); j++) {
            a[j] += a[j-1] * (FLOAT)0.00001f;
        }
    }

    *val = a[countof(a) - 1];

    return 1;
}

