static void decode_pluses(char *str) {
    char *out = str;

    for (const char *in = str; *in != '\0'; in++) {
        if (*in != '+') {
            *out++ = *in;
        } else if (in[1] == '+') {
            *out++ = '+';
            in++;
        } else {
            *out++ = ' ';
        }
    }
    *out = '\0';
}

static void run_autorun_script(console_t *con) {
    char *script = malloc(AUTORUN_MAX_LEN);
    if (!script) {
        return;
    }

    status_t err = cmdline_get_string("lk.autorun", script, AUTORUN_MAX_LEN, NULL);
    if (err == NO_ERROR) {
        decode_pluses(script);
        dprintf(INFO, "shell: running autorun script '%s'\n", script);
        console_run_script(con, script);
    } else if (err != ERR_NOT_FOUND) {
        printf("shell: cannot run lk.autorun script (err %d), maximum length is %d\n",
               err, AUTORUN_MAX_LEN - 1);
    }

    free(script);
}

static bool value_close(double got, double expected) {
    if (got != got) // NaN never compares close
        return false;

    double diff = got - expected;
    if (diff < 0)
        diff = -diff;
    double mag = (expected < 0) ? -expected : expected;

    return diff <= mag * FLOAT_TOLERANCE;
}

static int float_thread(void *arg) {
    FLOAT *val = arg;

    FLOAT a[16];

    /* do a bunch of work with floating point to test context switching */
    a[0] = *val;
    for (size_t i = 1; i < countof(a); i++) {
        a[i] = a[i-1] * (FLOAT)1.01f;
    }

    for (size_t i = 0; i < 1000000; i++) {
        a[0] += (FLOAT)0.001f;
        for (size_t j = 1; j < countof(a); j++) {
            a[j] += a[j-1] * (FLOAT)0.00001f;
        }
    }

    *val = a[countof(a) - 1];

    return 1;
}

