static bool float_test(void) {
    BEGIN_TEST;

    /* test lazy fpu load on separate thread */
    thread_t *t[8];
    volatile FLOAT val[countof(t)];
    /* Exact results of the loop in float_thread(), which is pure IEEE754
     * arithmetic and so is bit reproducible on any architecture as long as the
     * compiler does not contract the multiply-adds into fma (see the
     * -ffp-contract=off in rules.mk). Cross checked against a host build. */
    const uint32_t test_results_32[8] = {
        0x473aced4,
        0x47889742,
        0x47b3c708,
        0x47def6b4,
        0x4805139b,
        0x481aaab4,
        0x4830432a,
        0x4845da11,
    };
    const uint64_t test_results_64[8] = {
        0x40e7570fc8092db9,
        0x40f1117b2a41e1dd,
        0x40f6776e707f2b8a,
        0x40fbdd61b6bc75d0,
        0x4100a1aa7e7cdfa2,
        0x410354a4219b8562,
        0x4106079dc4ba29ff,
        0x4108ba9767d8cf08,
    };


    for (uint i = 0; i < countof(t); i++) {
        val[i] = i;
        char name[32];
        snprintf(name, sizeof(name), "float %u", i);
        t[i] = thread_create(name, &float_thread, (void *)&val[i], LOW_PRIORITY, DEFAULT_STACK_SIZE);
        ASSERT_NONNULL(t[i], "could not create float thread");
        thread_resume(t[i]);
    }

    int res;
    for (uint i = 0; i < countof(t); i++) {
        thread_join(t[i], &res, INFINITE_TIME);
        EXPECT_EQ(1, res, "float thread returned the wrong value");

        if (sizeof(FLOAT) == 4) {
            float result = val[i];
            uint32_t result_u32;
            memcpy(&result_u32, &result, sizeof(result_u32));
            float expected;
            memcpy(&expected, &test_results_32[i], sizeof(expected));
            if (!value_close((double)result, (double)expected)) {
                UNITTEST_FAIL_TRACEF("float thread %u: got %#" PRIx32 ", expected %#" PRIx32 "\n",
                                     i, result_u32, test_results_32[i]);
                all_ok = false;
            }
        } else {
            double result = val[i];
            uint64_t result_u64;
            memcpy(&result_u64, &result, sizeof(result_u64));
            double expected;
            memcpy(&expected, &test_results_64[i], sizeof(expected));
            if (!value_close(result, expected)) {
                UNITTEST_FAIL_TRACEF("float thread %u: got %#" PRIx64 ", expected %#" PRIx64 "\n",
                                     i, result_u64, test_results_64[i]);
                all_ok = false;
            }
        }
    }

    END_TEST;
}

static int thread_bench(int argc, const console_cmd_args *argv) {

STATIC_COMMAND_START
STATIC_COMMAND("thread_tests", "scheduler benchmarks", &thread_bench)
STATIC_COMMAND_END(thread_tests);

static int mutex_thread(void *arg) {
    mutex_t *m = (mutex_t *)arg;

    for (int i = 0; i < MUTEX_ITERATIONS; i++) {
        mutex_acquire(m);

        /* nobody else may be inside the mutex with us */
        if (mutex_shared != 0)
            mutex_corrupted = true;

        mutex_shared = (intptr_t)get_current_thread();
        thread_yield();
        mutex_shared = 0;

        mutex_release(m);
        thread_yield();
    }

    return 0;
}

static bool test_mutex_static_init(void) {
    BEGIN_TEST;

    static mutex_t imutex = MUTEX_INITIAL_VALUE(imutex);

    EXPECT_EQ(MUTEX_MAGIC, imutex.magic, "statically initialized mutex magic");
    EXPECT_EQ(0, imutex.count, "statically initialized mutex is not held");
    EXPECT_NULL(imutex.holder, "statically initialized mutex has no holder");

    END_TEST;
}

static bool test_mutex_mutual_exclusion(void) {
    BEGIN_TEST;

    mutex_t m;
    mutex_init(&m);

    mutex_shared = 0;
    mutex_corrupted = false;

    thread_t *threads[MUTEX_THREADS];
    for (uint i = 0; i < countof(threads); i++) {
        threads[i] = thread_create("mutex tester", &mutex_thread, &m,
                                   DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
        ASSERT_NONNULL(threads[i], "could not create mutex tester thread");
        thread_resume(threads[i]);
    }

    for (uint i = 0; i < countof(threads); i++) {
        thread_join(threads[i], NULL, INFINITE_TIME);
    }

    EXPECT_FALSE(mutex_corrupted, "two threads held the mutex at the same time");
    EXPECT_EQ(0, mutex_shared, "shared value left dirty");

    mutex_destroy(&m);

    END_TEST;
}

static bool test_mutex_timeout(void) {
    BEGIN_TEST;

    mutex_t timeout_mutex;
    mutex_init(&timeout_mutex);
    mutex_acquire(&timeout_mutex);

    thread_t *threads[4];
    for (uint i = 0; i < 2; i++) {
        threads[i] = thread_create("mutex timeout tester", &mutex_timeout_thread,
                                   &timeout_mutex, DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
        ASSERT_NONNULL(threads[i], "could not create mutex timeout thread");
        thread_resume(threads[i]);
    }
    for (uint i = 2; i < 4; i++) {
        threads[i] = thread_create("mutex zerotimeout tester", &mutex_zerotimeout_thread,
                                   &timeout_mutex, DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
        ASSERT_NONNULL(threads[i], "could not create mutex zero timeout thread");
        thread_resume(threads[i]);
    }

    /* hold the mutex past every waiter's timeout */
    thread_sleep(MUTEX_TIMEOUT_MS * 2);
    mutex_release(&timeout_mutex);

    for (uint i = 0; i < countof(threads); i++) {
        int retcode = NO_ERROR;
        thread_join(threads[i], &retcode, INFINITE_TIME);
        EXPECT_EQ(ERR_TIMED_OUT, retcode, "mutex_acquire_timeout should have timed out");
    }

    mutex_destroy(&timeout_mutex);

    END_TEST;
}

static int semaphore_producer(void *unused) {
    for (int x = 0; x < SEM_TOTAL_ITS; x++) {
        sem_post(&sem, true);
    }
    return 0;
}

static int semaphore_consumer(void *arg) {
    unsigned int iterations = (unsigned int)(uintptr_t)arg;

    for (unsigned int x = 0; x < iterations; x++)
        sem_wait(&sem);

    return 0;
}

static bool test_semaphore_static_init(void) {
    BEGIN_TEST;

    static semaphore_t isem = SEMAPHORE_INITIAL_VALUE(isem, 99);

    EXPECT_EQ(SEMAPHORE_MAGIC, isem.magic, "statically initialized semaphore magic");
    EXPECT_EQ(99, isem.count, "statically initialized semaphore count");

    END_TEST;
}

static bool test_semaphore(void) {
    BEGIN_TEST;

    sem_init(&sem, SEM_START_VALUE);

    /* Hand out all SEM_TOTAL_ITS waits among a set of consumers, so that the
     * consumers between them wait exactly as many times as the producer posts.
     * The semaphore must therefore end up back at its starting value. */
    thread_t *consumers[SEM_MAX_CONSUMERS];
    uint consumer_count = 0;

    int remaining = SEM_TOTAL_ITS;
    while (remaining > 0) {
        /* the last slot soaks up whatever is left so every wait is accounted for */
        unsigned int iterations;
        if (consumer_count == countof(consumers) - 1 || remaining < SEM_THREAD_MAX_ITS) {
            iterations = remaining;
        } else {
            /* note: LK's rand() returns a full width value that may be
             * negative, so make it unsigned before taking the modulus */
            iterations = 1 + ((unsigned int)rand() % SEM_THREAD_MAX_ITS);
        }
        remaining -= iterations;

        consumers[consumer_count] = thread_create("semaphore consumer", &semaphore_consumer,
                                                  (void *)(uintptr_t)iterations,
                                                  DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
        ASSERT_NONNULL(consumers[consumer_count], "could not create semaphore consumer");
        thread_resume(consumers[consumer_count]);
        consumer_count++;
    }

    ASSERT_EQ(0, remaining, "did not distribute all the semaphore waits");

    thread_t *producer = thread_create("semaphore producer", &semaphore_producer, NULL,
                                       DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
    ASSERT_NONNULL(producer, "could not create semaphore producer");
    thread_resume(producer);

    for (uint i = 0; i < consumer_count; i++)
        thread_join(consumers[i], NULL, INFINITE_TIME);
    thread_join(producer, NULL, INFINITE_TIME);

    EXPECT_EQ(SEM_START_VALUE, sem.count, "semaphore did not return to its start value");

    sem_destroy(&sem);

    END_TEST;
}

static int event_waiter(void *arg) {
    status_t err = event_wait(&e);
    if (err == NO_ERROR)
        atomic_add(&event_woken, 1);
    return err;
}

static bool test_event_static_init(void) {
    BEGIN_TEST;

    static event_t ievent = EVENT_INITIAL_VALUE(ievent, true, 0x1234);

    EXPECT_EQ(EVENT_MAGIC, ievent.magic, "statically initialized event magic");
    EXPECT_TRUE(ievent.signaled, "statically initialized event is signaled");
    EXPECT_EQ(0x1234u, ievent.flags, "statically initialized event flags");

    END_TEST;
}

static bool test_event_broadcast(void) {
    BEGIN_TEST;

    event_init(&e, false, 0);
    event_woken = 0;

    thread_t *threads[EVENT_WAITERS];
    for (uint i = 0; i < countof(threads); i++) {
        threads[i] = thread_create("event waiter", &event_waiter, NULL,
                                   DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
        ASSERT_NONNULL(threads[i], "could not create event waiter");
        thread_resume(threads[i]);
    }

    event_signal(&e, true);

    for (uint i = 0; i < countof(threads); i++) {
        int retcode = -1;
        thread_join(threads[i], &retcode, INFINITE_TIME);
        EXPECT_EQ(NO_ERROR, retcode, "waiter did not wake cleanly");
    }

    EXPECT_EQ(EVENT_WAITERS, event_woken, "a broadcast event must wake every waiter");

    event_destroy(&e);

    END_TEST;
}

static bool test_event_autounsignal(void) {
    BEGIN_TEST;

    event_init(&e, false, EVENT_FLAG_AUTOUNSIGNAL);
    event_woken = 0;

    thread_t *threads[EVENT_WAITERS];
    for (uint i = 0; i < countof(threads); i++) {
        threads[i] = thread_create("event waiter", &event_waiter, NULL,
                                   DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
        ASSERT_NONNULL(threads[i], "could not create event waiter");
        thread_resume(threads[i]);
    }

    /* let every waiter reach the event before signalling it */
    thread_sleep(100);

    event_signal(&e, true);

    /* give a wrongly woken second thread a chance to show up */
    thread_sleep(100);

    EXPECT_EQ(1, event_woken, "an autounsignal event must wake exactly one waiter");

    /* release the rest so they can be joined */
    event_destroy(&e);

    for (uint i = 0; i < countof(threads); i++)
        thread_join(threads[i], NULL, INFINITE_TIME);

    EXPECT_EQ(1, event_woken, "only one waiter may have woken with NO_ERROR");

    END_TEST;
}

static int atomic_tester(void *arg) {
    int add = (intptr_t)arg;

    for (int i = 0; i < ATOMIC_ITERATIONS; i++) {
        atomic_add(&atomic_value, add);
    }

    return 0;
}

static bool test_atomic_add(void) {
    BEGIN_TEST;

    atomic_value = 0;

    /* half the threads count up, half count down, by the same amount */
    thread_t *threads[ATOMIC_THREADS];
    for (uint i = 0; i < countof(threads); i++) {
        intptr_t add = (i < countof(threads) / 2) ? 1 : -1;
        threads[i] = thread_create("atomic tester", &atomic_tester, (void *)add,
                                   LOW_PRIORITY, DEFAULT_STACK_SIZE);
        ASSERT_NONNULL(threads[i], "could not create atomic tester thread");
    }

    for (uint i = 0; i < countof(threads); i++)
        thread_resume(threads[i]);

    for (uint i = 0; i < countof(threads); i++)
        thread_join(threads[i], NULL, INFINITE_TIME);

    EXPECT_EQ(0, atomic_value, "atomic adds did not cancel out");

    END_TEST;
}

static bool test_thread_join(void) {
    BEGIN_TEST;

    thread_t *t = thread_create("join tester", &join_tester, (void *)1,
                                DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
    ASSERT_NONNULL(t, "could not create join tester thread");
    EXPECT_EQ(THREAD_MAGIC, t->magic, "new thread magic");
    thread_resume(t);

    int retcode = 99;
    status_t err = thread_join(t, &retcode, INFINITE_TIME);
    EXPECT_EQ(NO_ERROR, err, "thread_join failed");
    EXPECT_EQ(1, retcode, "thread_join returned the wrong exit code");

    END_TEST;
}

static bool test_thread_join_after_exit(void) {
    BEGIN_TEST;

    thread_t *t = thread_create("join tester", &join_tester, (void *)2,
                                DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
    ASSERT_NONNULL(t, "could not create join tester thread");
    thread_resume(t);

    /* let the thread run to completion before joining it */
    thread_sleep(100);

    int retcode = 99;
    status_t err = thread_join(t, &retcode, INFINITE_TIME);
    EXPECT_EQ(NO_ERROR, err, "joining an already exited thread failed");
    EXPECT_EQ(2, retcode, "thread_join returned the wrong exit code");

    END_TEST;
}

static bool test_thread_detach(void) {
    BEGIN_TEST;

    /* detach before the thread runs, then let it clean itself up */
    thread_t *t = thread_create("detach tester", &join_tester, (void *)3,
                                DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
    ASSERT_NONNULL(t, "could not create detach tester thread");
    EXPECT_EQ(NO_ERROR, thread_detach(t), "thread_detach failed");
    thread_resume(t);
    thread_sleep(100);

    /* and detach one that has already exited, which must also reap it */
    t = thread_create("detach tester", &join_tester, (void *)4,
                      DEFAULT_PRIORITY, DEFAULT_STACK_SIZE);
    ASSERT_NONNULL(t, "could not create detach tester thread");
    thread_resume(t);
    thread_sleep(100);
    EXPECT_EQ(THREAD_MAGIC, t->magic, "an unreaped exited thread keeps its magic");
    EXPECT_EQ(NO_ERROR, thread_detach(t), "detaching an exited thread failed");

    END_TEST;
}

bool test_fat_mount_rejects_malformed() {
    BEGIN_TEST;

    constexpr size_t kSize = 2 * 1024 * 1024;
    constexpr const char *kDev = "fatbadbpb";

    void *mem = memalign(CACHE_LINE, kSize);
    ASSERT_NONNULL(mem);
    auto free_mem = lk::make_auto_call([&]() { free(mem); });

    ASSERT_EQ(0, create_membdev(kDev, mem, kSize));
    bdev_t *dev = bio_open(kDev);
    ASSERT_NONNULL(dev);
    auto cleanup = lk::make_auto_call([&]() {
        bio_close(dev);
        bio_unregister_device(dev);
    });

    fat_format_args_t args = {};
    args.fat_bits = 12;
    args.bytes_per_sector = 512;
    args.sectors_per_cluster = 1;

    // A pristine volume, kept aside so each case starts from a good image.
    ASSERT_EQ(NO_ERROR, fs_format_device("fat", kDev, &args));
    auto *pristine = (uint8_t *)malloc(512);
    ASSERT_NONNULL(pristine);
    auto free_pristine = lk::make_auto_call([&]() { free(pristine); });
    ASSERT_EQ(512, bio_read(dev, pristine, 0, 512));

    // it must mount before we start breaking it, or the test proves nothing
    ASSERT_EQ(NO_ERROR, fs_mount("/badbpb", "fat", kDev, FS_MOUNT_OPTION_NONE));
    ASSERT_EQ(NO_ERROR, fs_unmount("/badbpb"));

    struct {
        const char *what;
        uint32_t offset;
        uint32_t width; // 1, 2 or 4 bytes
        uint32_t value;
    } const cases[] = {
        {"total sectors larger than the device", 0x20, 4, 0x00ffffff},
        {"total sectors (16 bit) larger than the device", 0x13, 2, 0xfffe},
        {"zero sectors per cluster", 0x0d, 1, 0},
        {"sectors per cluster not a power of two", 0x0d, 1, 3},
        {"sectors per cluster absurdly large", 0x0d, 1, 0xff},
        {"unsupported sector size", 0x0b, 2, 777},
        {"zero FAT count", 0x10, 1, 0},
        {"absurd FAT count", 0x10, 1, 200},
        {"bad media descriptor", 0x15, 1, 0xf0},
        {"root entries not a whole sector", 0x11, 2, 7},
        {"zero sectors per FAT", 0x16, 2, 0},
    };

    auto *sector = (uint8_t *)malloc(512);
    ASSERT_NONNULL(sector);
    auto free_sector = lk::make_auto_call([&]() { free(sector); });

    for (auto &c : cases) {
        memcpy(sector, pristine, 512);
        switch (c.width) {
            case 1:
                sector[c.offset] = (uint8_t)c.value;
                break;
            case 2:
                sector[c.offset] = (uint8_t)c.value;
                sector[c.offset + 1] = (uint8_t)(c.value >> 8);
                break;
            default:
                for (int i = 0; i < 4; i++) {
                    sector[c.offset + i] = (uint8_t)(c.value >> (i * 8));
                }
                break;
        }
        // a 32 bit total sector count is only consulted when the 16 bit one is
        // zero, so clear it for that case
        if (c.offset == 0x20) {
            sector[0x13] = sector[0x14] = 0;
        }
        ASSERT_EQ(512, bio_write(dev, sector, 0, 512));

        status_t err = fs_mount("/badbpb", "fat", kDev, FS_MOUNT_OPTION_NONE);
        if (err == NO_ERROR) {
            fs_unmount("/badbpb");
            UNITTEST_FAIL_TRACEF("mounted a volume with %s\n", c.what);
            all_ok = false;
        }
    }

    // restore, and confirm the volume is still good: a rejected mount must not
    // have left anything behind
    ASSERT_EQ(512, bio_write(dev, pristine, 0, 512));
    ASSERT_EQ(NO_ERROR, fs_mount("/badbpb", "fat", kDev, FS_MOUNT_OPTION_NONE));
    ASSERT_EQ(NO_ERROR, fs_unmount("/badbpb"));

    END_TEST;
}

bool stress_enabled() {
    static bool checked = false;
    static bool enabled = false;
    if (!checked) {
        checked = true;
        bool val = false;
        if (cmdline_get_bool("test.fat.stress", &val) == NO_ERROR) {
            enabled = val;
        }
    }
    return enabled;
}

uint32_t stress_seed() {
    uint32_t seed = 0;
    if (cmdline_get_uint32("test.fat.stress.seed", &seed) == NO_ERROR && seed != 0) {
        return seed;
    }
    return 0x5eed1234;
}

uint32_t stress_ops() {
    uint32_t ops = 0;
    if (cmdline_get_uint32("test.fat.stress.ops", &ops) == NO_ERROR && ops != 0) {
        return ops;
    }
    return 600;
}

uint32_t next() {
        // xorshift32
        state ^= state << 13;
        state ^= state >> 17;
        state ^= state << 5;
        return state;
    }

uint8_t pattern_byte(uint32_t seed, uint64_t offset) {
    uint32_t x = seed ^ (uint32_t)(offset * 2654435761u);
    x ^= x >> 15;
    x *= 2246822519u;
    x ^= x >> 13;
    return (uint8_t)x;
}

void fill_pattern(uint8_t *buf, size_t len, uint32_t seed, uint64_t offset) {
    for (size_t i = 0; i < len; i++) {
        buf[i] = pattern_byte(seed, offset + i);
    }
}

size_t first_mismatch(const uint8_t *buf, size_t len, uint32_t seed, uint64_t offset) {
    for (size_t i = 0; i < len; i++) {
        if (buf[i] != pattern_byte(seed, offset + i)) {
            return i;
        }
    }
    return len;
}

status_t make_volume(ram_volume *vol, uint32_t clusters = 6000) {
    const uint32_t fat_bits = (clusters < 4085) ? 12 : ((clusters < 65525) ? 16 : 32);
    fat_test::geometry g = {"stress", fat_bits, 512, 1, clusters};
    const auto args = fat_test::format_args_for(g);
    return vol->create(kDeviceName, kMountPath, fat_test::volume_size_for(g), args);
}

status_t write_at(const char *path, const void *buf, off_t off, size_t len) {
    filehandle *fh = nullptr;
    status_t err = fs_open_file(path, &fh);
    if (err < 0) {
        return err;
    }
    ssize_t written = fs_write_file(fh, buf, off, len);
    fs_close_file(fh);
    if (written < 0) {
        return (status_t)written;
    }
    return ((size_t)written == len) ? NO_ERROR : ERR_IO;
}

status_t create_empty(const char *path) {
    filehandle *fh = nullptr;
    status_t err = fs_create_file(path, &fh, 0);
    if (err < 0) {
        return err;
    }
    return fs_close_file(fh);
}

bool test_fat_stress_remount() {
    BEGIN_TEST;
    SKIP_UNLESS_STRESS();

    ram_volume vol;
    status_t err = make_volume(&vol);
    if (err == ERR_NO_MEMORY) {
        unittest_printf(" not enough memory for the stress volume ");
        END_TEST;
    }
    ASSERT_EQ(NO_ERROR, err);

    constexpr int kFiles = 24;
    constexpr size_t kLen = 3000;

    auto *buf = (uint8_t *)malloc(kLen);
    ASSERT_NONNULL(buf);
    auto free_buf = lk::make_auto_call([&]() { free(buf); });

    char path[FS_MAX_PATH_LEN];
    for (int i = 0; i < kFiles; i++) {
        snprintf(path, sizeof(path), "%s/remount_%02d", vol.path(), i);
        ASSERT_EQ(NO_ERROR, create_empty(path));
        fill_pattern(buf, kLen, 0x100 + i, 0);
        ASSERT_EQ(NO_ERROR, write_at(path, buf, 0, kLen));
    }

    // three round trips, verifying in full each time
    for (int round = 0; round < 3; round++) {
        ASSERT_EQ(NO_ERROR, vol.remount());

        for (int i = 0; i < kFiles; i++) {
            snprintf(path, sizeof(path), "%s/remount_%02d", vol.path(), i);

            filehandle *fh = nullptr;
            ASSERT_EQ(NO_ERROR, fs_open_file(path, &fh));
            auto close_fh = lk::make_auto_call([&]() { fs_close_file(fh); });

            struct file_stat st = {};
            ASSERT_EQ(NO_ERROR, fs_stat_file(fh, &st));
            if (st.size != kLen) {
                UNITTEST_FAIL_TRACEF("round %d file %d: size %llu, expected %zu\n",
                                     round, i, st.size, kLen);
                all_ok = false;
                continue;
            }

            memset(buf, 0, kLen);
            ASSERT_EQ((ssize_t)kLen, fs_read_file(fh, buf, 0, kLen));
            const size_t bad = first_mismatch(buf, kLen, 0x100 + i, 0);
            if (bad != kLen) {
                UNITTEST_FAIL_TRACEF("round %d file %d: content differs at byte %zu\n",
                                     round, i, bad);
                all_ok = false;
            }
        }
    }

    for (int i = 0; i < kFiles; i++) {
        snprintf(path, sizeof(path), "%s/remount_%02d", vol.path(), i);
        EXPECT_EQ(NO_ERROR, fs_remove_file(path));
    }

    END_TEST;
}

bool test_fat_stress_enospc() {
    BEGIN_TEST;
    SKIP_UNLESS_STRESS();

    ram_volume vol;
    status_t err = make_volume(&vol, 2000);
    if (err == ERR_NO_MEMORY) {
        unittest_printf(" not enough memory for the stress volume ");
        END_TEST;
    }
    ASSERT_EQ(NO_ERROR, err);

    struct fs_stat before = {};
    ASSERT_EQ(NO_ERROR, fs_stat_fs(vol.path(), &before));

    constexpr size_t kChunk = 4096;
    auto *buf = (uint8_t *)malloc(kChunk);
    ASSERT_NONNULL(buf);
    auto free_buf = lk::make_auto_call([&]() { free(buf); });

    char path[FS_MAX_PATH_LEN];
    int created = 0;
    status_t fill_err = NO_ERROR;

    // Bounded so a driver that never reports full cannot spin here forever.
    const int kMaxFiles = 600;
    for (; created < kMaxFiles; created++) {
        snprintf(path, sizeof(path), "%s/fill_%03d", vol.path(), created);
        status_t e = create_empty(path);
        if (e < 0) {
            fill_err = e;
            break;
        }
        fill_pattern(buf, kChunk, 0x900 + created, 0);
        e = write_at(path, buf, 0, kChunk);
        if (e < 0) {
            fill_err = e;
            // the file exists but is short; do not count it as fully written
            break;
        }
    }

    unittest_printf("\n        filled with %d files, stopped with %d ", created, fill_err);

    // It must actually have run out rather than claiming infinite space.
    EXPECT_LT(created, kMaxFiles);
    // and the failure has to be a sane error code, not a corrupted success
    EXPECT_LT(fill_err, 0);

    // Everything fully written before the failure must still read back correctly.
    for (int i = 0; i < created; i++) {
        snprintf(path, sizeof(path), "%s/fill_%03d", vol.path(), i);
        filehandle *fh = nullptr;
        ASSERT_EQ(NO_ERROR, fs_open_file(path, &fh));
        auto close_fh = lk::make_auto_call([&]() { fs_close_file(fh); });
        memset(buf, 0, kChunk);
        ASSERT_EQ((ssize_t)kChunk, fs_read_file(fh, buf, 0, kChunk));
        const size_t bad = first_mismatch(buf, kChunk, 0x900 + i, 0);
        if (bad != kChunk) {
            UNITTEST_FAIL_TRACEF("file %d damaged by the out of space condition "
                                 "at byte %zu\n", i, bad);
            all_ok = false;
            break;
        }
    }

    // A full volume must still survive a round trip through the device.
    ASSERT_EQ(NO_ERROR, vol.remount());

    // Free everything and confirm the space really comes back.
    for (int i = 0; i <= created && i < kMaxFiles; i++) {
        snprintf(path, sizeof(path), "%s/fill_%03d", vol.path(), i);
        fs_remove_file(path);
    }

    struct fs_stat after = {};
    ASSERT_EQ(NO_ERROR, fs_stat_fs(vol.path(), &after));
    EXPECT_EQ(before.free_space, after.free_space);

    END_TEST;
}

bool test_fat_stress_fragmentation() {
    BEGIN_TEST;
    SKIP_UNLESS_STRESS();

    ram_volume vol;
    status_t err = make_volume(&vol);
    if (err == ERR_NO_MEMORY) {
        unittest_printf(" not enough memory for the stress volume ");
        END_TEST;
    }
    ASSERT_EQ(NO_ERROR, err);

    constexpr int kFiles = 12;
    constexpr int kRounds = 8;
    constexpr size_t kChunk = 600; // not a multiple of the 512 byte cluster

    auto *buf = (uint8_t *)malloc(kChunk);
    ASSERT_NONNULL(buf);
    auto free_buf = lk::make_auto_call([&]() { free(buf); });

    char path[FS_MAX_PATH_LEN];
    for (int i = 0; i < kFiles; i++) {
        snprintf(path, sizeof(path), "%s/frag_%02d", vol.path(), i);
        ASSERT_EQ(NO_ERROR, create_empty(path));
    }

    // round robin: every file grows by one chunk before any grows by two, so the
    // clusters of all twelve chains end up interleaved on the volume
    for (int round = 0; round < kRounds; round++) {
        for (int i = 0; i < kFiles; i++) {
            snprintf(path, sizeof(path), "%s/frag_%02d", vol.path(), i);
            const uint64_t off = (uint64_t)round * kChunk;
            fill_pattern(buf, kChunk, 0x200 + i, off);
            ASSERT_EQ(NO_ERROR, write_at(path, buf, off, kChunk));
        }
    }

    ASSERT_EQ(NO_ERROR, vol.remount());

    auto verify_all = [&](const char *stage) {
        bool ok = true;
        for (int i = 0; i < kFiles; i++) {
            snprintf(path, sizeof(path), "%s/frag_%02d", vol.path(), i);
            filehandle *fh = nullptr;
            if (fs_open_file(path, &fh) < 0) {
                unittest_printf("\n        %s: cannot open frag_%02d ", stage, i);
                ok = false;
                continue;
            }
            for (int round = 0; round < kRounds; round++) {
                const uint64_t off = (uint64_t)round * kChunk;
                memset(buf, 0, kChunk);
                if (fs_read_file(fh, buf, off, kChunk) != (ssize_t)kChunk) {
                    unittest_printf("\n        %s: short read of frag_%02d at %llu ",
                                    stage, i, off);
                    ok = false;
                    break;
                }
                const size_t bad = first_mismatch(buf, kChunk, 0x200 + i, off);
                if (bad != kChunk) {
                    unittest_printf("\n        %s: frag_%02d differs at %llu ",
                                    stage, i, off + bad);
                    ok = false;
                    break;
                }
            }
            fs_close_file(fh);
        }
        return ok;
    };

    EXPECT_TRUE(verify_all("after interleaved growth"));

    // Punch holes by deleting every other file, then refill them. The new files
    // land in the freed clusters, which are scattered all over the volume.
    for (int i = 0; i < kFiles; i += 2) {
        snprintf(path, sizeof(path), "%s/frag_%02d", vol.path(), i);
        ASSERT_EQ(NO_ERROR, fs_remove_file(path));
    }
    for (int i = 0; i < kFiles; i += 2) {
        snprintf(path, sizeof(path), "%s/frag_%02d", vol.path(), i);
        ASSERT_EQ(NO_ERROR, create_empty(path));
        for (int round = 0; round < kRounds; round++) {
            const uint64_t off = (uint64_t)round * kChunk;
            fill_pattern(buf, kChunk, 0x200 + i, off);
            ASSERT_EQ(NO_ERROR, write_at(path, buf, off, kChunk));
        }
    }

    ASSERT_EQ(NO_ERROR, vol.remount());
    EXPECT_TRUE(verify_all("after refilling holes"));

    for (int i = 0; i < kFiles; i++) {
        snprintf(path, sizeof(path), "%s/frag_%02d", vol.path(), i);
        EXPECT_EQ(NO_ERROR, fs_remove_file(path));
    }

    END_TEST;
}

bool test_fat_stress_boundaries() {
    BEGIN_TEST;
    SKIP_UNLESS_STRESS();

    ram_volume vol;
    status_t err = make_volume(&vol);
    if (err == ERR_NO_MEMORY) {
        unittest_printf(" not enough memory for the stress volume ");
        END_TEST;
    }
    ASSERT_EQ(NO_ERROR, err);

    struct fs_stat fss = {};
    ASSERT_EQ(NO_ERROR, fs_stat_fs(vol.path(), &fss));

    // Offsets and lengths either side of the 512 byte sector and cluster edges,
    // plus a few multi-cluster ones.
    static const uint64_t offsets[] = {0, 1, 511, 512, 513, 1023, 1024, 1025,
                                       4095, 4096, 4097, 8191, 8192, 8193};
    static const size_t lengths[] = {1, 2, 511, 512, 513, 1024, 1025, 4096};

    char path[FS_MAX_PATH_LEN];
    snprintf(path, sizeof(path), "%s/boundary", vol.path());

    auto *wbuf = (uint8_t *)malloc(4096);
    auto *rbuf = (uint8_t *)malloc(4096);
    ASSERT_NONNULL(wbuf);
    ASSERT_NONNULL(rbuf);
    auto free_bufs = lk::make_auto_call([&]() { free(wbuf); free(rbuf); });

    uint32_t seed = 1;
    for (auto off : offsets) {
        for (auto len : lengths) {
            seed++;

            // a fresh file each time so the write is always into a hole
            fs_remove_file(path);
            ASSERT_EQ(NO_ERROR, create_empty(path));

            fill_pattern(wbuf, len, seed, off);
            status_t e = write_at(path, wbuf, (off_t)off, len);
            if (e < 0) {
                UNITTEST_FAIL_TRACEF("write at offset %llu length %zu failed: %d\n",
                                     off, len, e);
                all_ok = false;
                continue;
            }

            filehandle *fh = nullptr;
            ASSERT_EQ(NO_ERROR, fs_open_file(path, &fh));
            auto close_fh = lk::make_auto_call([&]() { fs_close_file(fh); });

            struct file_stat st = {};
            ASSERT_EQ(NO_ERROR, fs_stat_file(fh, &st));
            if (st.size != off + len) {
                UNITTEST_FAIL_TRACEF("offset %llu length %zu: size %llu, expected %llu\n",
                                     off, len, st.size, off + len);
                all_ok = false;
                continue;
            }

            memset(rbuf, 0, len);
            if (fs_read_file(fh, rbuf, (off_t)off, len) != (ssize_t)len) {
                UNITTEST_FAIL_TRACEF("short read at offset %llu length %zu\n", off, len);
                all_ok = false;
                continue;
            }
            const size_t bad = first_mismatch(rbuf, len, seed, off);
            if (bad != len) {
                UNITTEST_FAIL_TRACEF("offset %llu length %zu: differs at byte %zu\n",
                                     off, len, bad);
                all_ok = false;
                continue;
            }

            // everything before the write offset is a hole and must read zero
            if (off > 0) {
                const size_t gap = (size_t)MIN(off, 4096u);
                memset(rbuf, 0xaa, gap);
                if (fs_read_file(fh, rbuf, 0, gap) != (ssize_t)gap) {
                    UNITTEST_FAIL_TRACEF("short read of the hole before %llu\n", off);
                    all_ok = false;
                    continue;
                }
                for (size_t i = 0; i < gap; i++) {
                    if (rbuf[i] != 0) {
                        UNITTEST_FAIL_TRACEF("hole before offset %llu is not zero "
                                             "at byte %zu (%#x)\n", off, i, rbuf[i]);
                        all_ok = false;
                        break;
                    }
                }
            }
        }
    }

    fs_remove_file(path);

    END_TEST;
}

bool test_fat_stress_dir_slot_reuse() {
    BEGIN_TEST;
    SKIP_UNLESS_STRESS();

    ram_volume vol;
    status_t err = make_volume(&vol);
    if (err == ERR_NO_MEMORY) {
        unittest_printf(" not enough memory for the stress volume ");
        END_TEST;
    }
    ASSERT_EQ(NO_ERROR, err);

    char dir[FS_MAX_PATH_LEN];
    snprintf(dir, sizeof(dir), "%s/slots", vol.path());
    ASSERT_EQ(NO_ERROR, fs_make_dir(dir));

    constexpr int kNames = 120;
    char path[FS_MAX_PATH_LEN];

    // names of differing length so the LFN runs are of differing size, which is
    // what makes slot reuse interesting: a freed run may not fit the next name
    auto make_name = [&](int i, int generation) {
        snprintf(path, sizeof(path), "%s/gen%d_entry_with_a_longish_name_%03d.dat",
                 dir, generation, i);
    };

    for (int i = 0; i < kNames; i++) {
        make_name(i, 0);
        ASSERT_EQ(NO_ERROR, create_empty(path));
    }

    // delete every other one, leaving gaps of varying size
    for (int i = 0; i < kNames; i += 2) {
        make_name(i, 0);
        ASSERT_EQ(NO_ERROR, fs_remove_file(path));
    }

    // fill the gaps with names of a different length
    for (int i = 0; i < kNames; i += 2) {
        make_name(i, 11);
        ASSERT_EQ(NO_ERROR, create_empty(path));
    }

    ASSERT_EQ(NO_ERROR, vol.remount());

    // everything that should exist must resolve, and nothing else
    int found = 0;
    for (int i = 0; i < kNames; i++) {
        make_name(i, (i % 2 == 0) ? 11 : 0);
        filehandle *fh = nullptr;
        if (fs_open_file(path, &fh) != NO_ERROR) {
            UNITTEST_FAIL_TRACEF("entry %d missing after slot reuse: %s\n", i, path);
            all_ok = false;
            continue;
        }
        fs_close_file(fh);
        found++;

        // the deleted generation must be gone
        make_name(i, (i % 2 == 0) ? 0 : 11);
        fh = nullptr;
        if (fs_open_file(path, &fh) == NO_ERROR) {
            fs_close_file(fh);
            UNITTEST_FAIL_TRACEF("stale entry %d still resolves: %s\n", i, path);
            all_ok = false;
        }
    }
    EXPECT_EQ(kNames, found);

    // the directory listing must agree with that: kNames entries plus . and ..
    dirhandle *dh = nullptr;
    ASSERT_EQ(NO_ERROR, fs_open_dir(dir, &dh));
    int count = 0;
    dirent ent;
    while (fs_read_dir(dh, &ent) == NO_ERROR) {
        count++;
    }
    ASSERT_EQ(NO_ERROR, fs_close_dir(dh));
    EXPECT_EQ(kNames + 2, count);

    for (int i = 0; i < kNames; i++) {
        make_name(i, (i % 2 == 0) ? 11 : 0);
        EXPECT_EQ(NO_ERROR, fs_remove_file(path));
    }
    EXPECT_EQ(NO_ERROR, fs_remove_dir(dir));

    END_TEST;
}

bool test_fat_witness() {
    return test_mount_wrapper([]() {
        BEGIN_TEST;

        // start from a clean slate so a re-run reproduces the tree exactly
        fs_remove_file(test_path "/witness/nested/deep.txt");
        fs_remove_dir(test_path "/witness/nested");
        fs_remove_file(test_path "/witness/small.txt");
        fs_remove_file(test_path "/witness/pattern.bin");
        fs_remove_file(test_path "/witness/a_long_witness_file_name_that_needs_lfn.txt");
        fs_remove_dir(test_path "/witness");

        ASSERT_EQ(NO_ERROR, fs_make_dir(test_path "/witness"));
        ASSERT_EQ(NO_ERROR, fs_make_dir(test_path "/witness/nested"));

        struct {
            const char *path;
            const char *data;
            size_t len;
        } const simple[] = {
            {test_path "/witness/small.txt", "witness small", 13},
            {test_path "/witness/a_long_witness_file_name_that_needs_lfn.txt", "hello", 5},
            {test_path "/witness/nested/deep.txt", "deep", 4},
        };

        for (auto &s : simple) {
            filehandle *fh = nullptr;
            ASSERT_EQ(NO_ERROR, fs_create_file(s.path, &fh, 0));
            ASSERT_NONNULL(fh);
            auto close_fh = lk::make_auto_call([&]() { fs_close_file(fh); });
            ASSERT_EQ((ssize_t)s.len, fs_write_file(fh, s.data, 0, s.len));
            close_fh.cancel();
            ASSERT_EQ(NO_ERROR, fs_close_file(fh));
        }

        // A multi-cluster file with a position dependent pattern: this is the one
        // the host verifier compares byte for byte, so a cluster written to the
        // wrong place shows up as a specific bad offset rather than a size change.
        const size_t pattern_len = 9000;
        auto *buf = new uint8_t[pattern_len];
        auto delete_buf = lk::make_auto_call([&]() { delete[] buf; });
        for (size_t i = 0; i < pattern_len; i++) {
            buf[i] = (uint8_t)((i * 7 + 11) & 0xff);
        }

        filehandle *fh = nullptr;
        ASSERT_EQ(NO_ERROR, fs_create_file(test_path "/witness/pattern.bin", &fh, 0));
        ASSERT_NONNULL(fh);
        auto close_fh = lk::make_auto_call([&]() { fs_close_file(fh); });
        ASSERT_EQ((ssize_t)pattern_len, fs_write_file(fh, buf, 0, pattern_len));
        close_fh.cancel();
        ASSERT_EQ(NO_ERROR, fs_close_file(fh));

        // read it all back through a fresh open before handing off to the host
        fh = nullptr;
        ASSERT_EQ(NO_ERROR, fs_open_file(test_path "/witness/pattern.bin", &fh));
        auto close_fh2 = lk::make_auto_call([&]() { fs_close_file(fh); });
        auto *readback = new uint8_t[pattern_len];
        auto delete_readback = lk::make_auto_call([&]() { delete[] readback; });
        memset(readback, 0, pattern_len);
        ASSERT_EQ((ssize_t)pattern_len, fs_read_file(fh, readback, 0, pattern_len));
        EXPECT_EQ(0, memcmp(buf, readback, pattern_len));
        close_fh2.cancel();
        ASSERT_EQ(NO_ERROR, fs_close_file(fh));

        END_TEST;
    });
}

uint8_t pattern_byte(uint32_t seed, uint64_t offset) {
    uint32_t x = seed ^ (uint32_t)(offset * 2654435761u);
    x ^= x >> 15;
    x *= 2246822519u;
    x ^= x >> 13;
    return (uint8_t)x;
}

void fill_pattern(uint8_t *buf, size_t len, uint32_t seed, uint64_t offset) {
    for (size_t i = 0; i < len; i++) {
        buf[i] = pattern_byte(seed, offset + i);
    }
}

size_t check_pattern(const uint8_t *buf, size_t len, uint32_t seed, uint64_t offset) {
    for (size_t i = 0; i < len; i++) {
        if (buf[i] != pattern_byte(seed, offset + i)) {
            return i;
        }
    }
    return len;
}

bool write_and_verify(const char *path, uint32_t seed, uint64_t offset, size_t len) {
    BEGIN_TEST;

    auto *wbuf = (uint8_t *)malloc(len);
    auto *rbuf = (uint8_t *)malloc(len);
    ASSERT_NONNULL(wbuf);
    ASSERT_NONNULL(rbuf);
    auto free_bufs = lk::make_auto_call([&]() { free(wbuf); free(rbuf); });

    fill_pattern(wbuf, len, seed, offset);

    filehandle *fh = nullptr;
    ASSERT_EQ(NO_ERROR, fs_open_file(path, &fh));
    auto close_fh = lk::make_auto_call([&]() { fs_close_file(fh); });

    ASSERT_EQ((ssize_t)len, fs_write_file(fh, wbuf, offset, len));

    memset(rbuf, 0, len);
    ASSERT_EQ((ssize_t)len, fs_read_file(fh, rbuf, offset, len));

    const size_t bad = check_pattern(rbuf, len, seed, offset);
    if (bad != len) {
        unittest_printf("\n        content mismatch at offset %llu (byte %zu of %zu): "
                        "expected %#x got %#x\n",
                        offset + bad, bad, len, pattern_byte(seed, offset + bad), rbuf[bad]);
    }
    EXPECT_EQ(len, bad);

    END_TEST;
}

bool verify_file_contents(const char *path, uint32_t seed, uint64_t offset, size_t len,
                          uint64_t expected_size) {
    BEGIN_TEST;

    auto *rbuf = (uint8_t *)malloc(len);
    ASSERT_NONNULL(rbuf);
    auto free_buf = lk::make_auto_call([&]() { free(rbuf); });

    filehandle *fh = nullptr;
    ASSERT_EQ(NO_ERROR, fs_open_file(path, &fh));
    auto close_fh = lk::make_auto_call([&]() { fs_close_file(fh); });

    struct file_stat st = {};
    ASSERT_EQ(NO_ERROR, fs_stat_file(fh, &st));
    EXPECT_EQ(expected_size, st.size);

    memset(rbuf, 0, len);
    ASSERT_EQ((ssize_t)len, fs_read_file(fh, rbuf, offset, len));

    const size_t bad = check_pattern(rbuf, len, seed, offset);
    if (bad != len) {
        unittest_printf("\n        content mismatch after remount at offset %llu: "
                        "expected %#x got %#x\n",
                        offset + bad, pattern_byte(seed, offset + bad), rbuf[bad]);
    }
    EXPECT_EQ(len, bad);

    END_TEST;
}

bool exercise_volume(ram_volume &vol, const fat_test::geometry &g) {
    BEGIN_TEST;

    char path[FS_MAX_PATH_LEN];

    // the mounted volume must report the geometry it was formatted with
    struct fs_stat fss = {};
    ASSERT_EQ(NO_ERROR, fs_stat_fs(vol.path(), &fss));
    const uint64_t cluster_bytes = (uint64_t)g.bytes_per_sector * g.sectors_per_cluster;
    ASSERT_NE(0u, (uint)cluster_bytes);
    // a freshly formatted volume has everything free except the FAT32 root dir
    EXPECT_LE(fss.free_space, fss.total_space);
    EXPECT_GT(fss.total_space, 0u);

    // a file smaller than one cluster
    snprintf(path, sizeof(path), "%s/small", vol.path());
    filehandle *fh = nullptr;
    ASSERT_EQ(NO_ERROR, fs_create_file(path, &fh, 0));
    ASSERT_EQ(NO_ERROR, fs_close_file(fh));
    EXPECT_TRUE(write_and_verify(path, 0x1111, 0, 100));

    // a file spanning several clusters, written at an offset that crosses a
    // cluster boundary so the chain has to be walked
    snprintf(path, sizeof(path), "%s/multicluster", vol.path());
    fh = nullptr;
    ASSERT_EQ(NO_ERROR, fs_create_file(path, &fh, 0));
    ASSERT_EQ(NO_ERROR, fs_close_file(fh));
    const size_t span = (size_t)MIN(cluster_bytes * 3 + 17, 64u * 1024);
    EXPECT_TRUE(write_and_verify(path, 0x2222, 0, span));

    // a long file name, which needs the LFN path in both directions
    snprintf(path, sizeof(path), "%s/a_long_file_name_for_this_geometry.txt", vol.path());
    fh = nullptr;
    ASSERT_EQ(NO_ERROR, fs_create_file(path, &fh, 0));
    ASSERT_EQ(NO_ERROR, fs_close_file(fh));
    EXPECT_TRUE(write_and_verify(path, 0x3333, 0, 1234));

    // a subdirectory with a file in it
    char dirpath[FS_MAX_PATH_LEN];
    snprintf(dirpath, sizeof(dirpath), "%s/subdir", vol.path());
    ASSERT_EQ(NO_ERROR, fs_make_dir(dirpath));
    snprintf(path, sizeof(path), "%s/subdir/nested", vol.path());
    fh = nullptr;
    ASSERT_EQ(NO_ERROR, fs_create_file(path, &fh, 0));
    ASSERT_EQ(NO_ERROR, fs_close_file(fh));
    EXPECT_TRUE(write_and_verify(path, 0x4444, 0, 300));

    // . and .. must both be present in a new directory
    dirhandle *dh = nullptr;
    ASSERT_EQ(NO_ERROR, fs_open_dir(dirpath, &dh));
    bool saw_dot = false, saw_dotdot = false, saw_nested = false;
    dirent ent;
    while (fs_read_dir(dh, &ent) == NO_ERROR) {
        // "nested" fits 8.3 so it is stored as a short name with no long name
        // entry to preserve case; FAT short names are upper case, and lookup is
        // case insensitive, so compare the same way fat_find_file_in_dir does.
        if (!strcmp(ent.name, ".")) saw_dot = true;
        else if (!strcmp(ent.name, "..")) saw_dotdot = true;
        else if (!strnicmp(ent.name, "nested", sizeof("nested"))) saw_nested = true;
    }
    ASSERT_EQ(NO_ERROR, fs_close_dir(dh));
    EXPECT_TRUE(saw_dot);
    EXPECT_TRUE(saw_dotdot);
    EXPECT_TRUE(saw_nested);

    // everything written so far must survive a round trip through the device
    ASSERT_EQ(NO_ERROR, vol.remount());

    snprintf(path, sizeof(path), "%s/small", vol.path());
    EXPECT_TRUE(verify_file_contents(path, 0x1111, 0, 100, 100));
    snprintf(path, sizeof(path), "%s/multicluster", vol.path());
    EXPECT_TRUE(verify_file_contents(path, 0x2222, 0, span, span));
    snprintf(path, sizeof(path), "%s/a_long_file_name_for_this_geometry.txt", vol.path());
    EXPECT_TRUE(verify_file_contents(path, 0x3333, 0, 1234, 1234));
    snprintf(path, sizeof(path), "%s/subdir/nested", vol.path());
    EXPECT_TRUE(verify_file_contents(path, 0x4444, 0, 300, 300));

    // shrink, and confirm the tail is really gone rather than resurrected
    snprintf(path, sizeof(path), "%s/multicluster", vol.path());
    fh = nullptr;
    ASSERT_EQ(NO_ERROR, fs_open_file(path, &fh));
    ASSERT_EQ(NO_ERROR, fs_truncate_file(fh, 50));
    struct file_stat st = {};
    ASSERT_EQ(NO_ERROR, fs_stat_file(fh, &st));
    EXPECT_EQ(50u, st.size);
    ASSERT_EQ(NO_ERROR, fs_close_file(fh));

    ASSERT_EQ(NO_ERROR, vol.remount());
    fh = nullptr;
    ASSERT_EQ(NO_ERROR, fs_open_file(path, &fh));
    st = {};
    ASSERT_EQ(NO_ERROR, fs_stat_file(fh, &st));
    EXPECT_EQ(50u, st.size);
    // reading past the new end must return nothing, not the old contents
    uint8_t tail[64];
    memset(tail, 0xaa, sizeof(tail));
    EXPECT_EQ(0, fs_read_file(fh, tail, 50, sizeof(tail)));
    ASSERT_EQ(NO_ERROR, fs_close_file(fh));

    // tear it all down; a volume that cannot be emptied is a leak
    ASSERT_EQ(NO_ERROR, fs_remove_file(path));
    snprintf(path, sizeof(path), "%s/small", vol.path());
    ASSERT_EQ(NO_ERROR, fs_remove_file(path));
    snprintf(path, sizeof(path), "%s/a_long_file_name_for_this_geometry.txt", vol.path());
    ASSERT_EQ(NO_ERROR, fs_remove_file(path));
    snprintf(path, sizeof(path), "%s/subdir/nested", vol.path());
    ASSERT_EQ(NO_ERROR, fs_remove_file(path));
    ASSERT_EQ(NO_ERROR, fs_remove_dir(dirpath));

    END_TEST;
}

bool test_fat_ram_geometries() {
    BEGIN_TEST;

    uint ran = 0, skipped = 0;

    for (size_t i = 0; i < fat_test::kGeometryCount; i++) {
        const auto &g = fat_test::kGeometries[i];
        const size_t size = fat_test::volume_size_for(g);

        ram_volume vol;
        const auto args = fat_test::format_args_for(g);
        status_t err = vol.create(kDeviceName, kMountPath, size, args);
        if (err == ERR_NO_MEMORY) {
            // too large for this target: report it and move on rather than
            // failing, so the small architectures still run the rest
            unittest_printf("\n        skipping %s: %zu bytes would not allocate ",
                            g.name, size);
            skipped++;
            continue;
        }
        if (err < 0) {
            UNITTEST_FAIL_TRACEF("geometry %s (%zu bytes) failed to format/mount: %d\n",
                                 g.name, size, err);
            all_ok = false;
            continue;
        }

        if (!exercise_volume(vol, g)) {
            UNITTEST_FAIL_TRACEF("geometry %s failed\n", g.name);
            all_ok = false;
        }
        ran++;
    }

    unittest_printf("\n        %u geometries exercised, %u skipped ", ran, skipped);

    // If every single geometry skipped then this test proved nothing, which is
    // exactly the vacuous pass this file exists to prevent.
    EXPECT_GT(ran, 0u);

    END_TEST;
}

bool test_fat_ram_format_roundtrip() {
    BEGIN_TEST;

    struct {
        uint32_t fat_bits;
        uint32_t clusters;
    } cases[] = {{12, 1000}, {16, 5000}};

    for (auto &c : cases) {
        fat_test::geometry g = {"roundtrip", c.fat_bits, 512, 1, c.clusters};
        ram_volume vol;
        const auto args = fat_test::format_args_for(g);
        status_t err = vol.create(kDeviceName, kMountPath, fat_test::volume_size_for(g), args);
        if (err == ERR_NO_MEMORY) {
            continue;
        }
        ASSERT_EQ(NO_ERROR, err);

        struct fs_stat fss = {};
        ASSERT_EQ(NO_ERROR, fs_stat_fs(vol.path(), &fss));

        // a fresh volume of N clusters has at least N clusters free on FAT12/16
        // (FAT32 spends one on the root directory)
        EXPECT_GE(fss.free_space, (uint64_t)c.clusters * 512);
    }

    END_TEST;
}

bool test_fat_format_rejects_impossible_geometry() {
    BEGIN_TEST;

    void *mem = memalign(CACHE_LINE, 1 * 1024 * 1024);
    ASSERT_NONNULL(mem);
    auto free_mem = lk::make_auto_call([&]() { free(mem); });

    ASSERT_EQ(0, create_membdev("fatbadfmt", mem, 1 * 1024 * 1024));
    bdev_t *dev = bio_open("fatbadfmt");
    ASSERT_NONNULL(dev);
    auto cleanup = lk::make_auto_call([&]() {
        bio_close(dev);
        bio_unregister_device(dev);
    });

    // 1MB cannot hold the 65525 clusters FAT32 requires
    fat_format_args_t args = {};
    args.fat_bits = 32;
    args.bytes_per_sector = 512;
    args.sectors_per_cluster = 1;
    EXPECT_EQ(ERR_INVALID_ARGS, fs_format_device("fat", "fatbadfmt", &args));

    // nor is it big enough to be anything but FAT12, so asking for FAT16 fails
    args.fat_bits = 16;
    EXPECT_EQ(ERR_INVALID_ARGS, fs_format_device("fat", "fatbadfmt", &args));

    // invalid parameters
    args.fat_bits = 12;
    args.bytes_per_sector = 777;
    EXPECT_EQ(ERR_INVALID_ARGS, fs_format_device("fat", "fatbadfmt", &args));

    args.bytes_per_sector = 512;
    args.sectors_per_cluster = 3; // not a power of two
    EXPECT_EQ(ERR_INVALID_ARGS, fs_format_device("fat", "fatbadfmt", &args));

    args.sectors_per_cluster = 1;
    args.root_entries = 7; // not a whole number of sectors
    EXPECT_EQ(ERR_INVALID_ARGS, fs_format_device("fat", "fatbadfmt", &args));

    // and a sane request on the same device must still succeed
    args.root_entries = 0;
    EXPECT_EQ(NO_ERROR, fs_format_device("fat", "fatbadfmt", &args));

    END_TEST;
}

uint64_t fat_bytes_for_entries(uint64_t entries, uint32_t fat_bits) {
    switch (fat_bits) {
        case 12:
            return (entries * 3 + 1) / 2;
        case 16:
            return entries * 2;
        default:
            return entries * 4;
    }
}

uint32_t clusters_for_sectors(const geometry &g, uint64_t total_sectors) {
    const uint64_t reserved = (g.fat_bits == 32) ? 32 : 1;
    const uint64_t root_sectors =
        (g.fat_bits == 32) ? 0 : ((512 * 32 + g.bytes_per_sector - 1) / g.bytes_per_sector);

    uint64_t sectors_per_fat = 1;
    for (int i = 0; i < 16; i++) {
        const uint64_t overhead = reserved + 2 * sectors_per_fat + root_sectors;
        if (overhead >= total_sectors) {
            return 0;
        }
        const uint64_t clusters = (total_sectors - overhead) / g.sectors_per_cluster;
        const uint64_t needed = (fat_bytes_for_entries(clusters + 2, g.fat_bits) +
                                 g.bytes_per_sector - 1) / g.bytes_per_sector;
        if (needed <= sectors_per_fat) {
            return (uint32_t)clusters;
        }
        sectors_per_fat = needed;
    }
    return 0;
}

size_t volume_size_for(const geometry &g) {
    // The boundary rows only mean something if they land on the exact cluster
    // count they name, so solve for the volume size rather than estimating it.
    // A bigger FAT eats data sectors, so a naive estimate always undershoots.
    const uint64_t reserved = (g.fat_bits == 32) ? 32 : 1;
    const uint64_t root_sectors =
        (g.fat_bits == 32) ? 0 : ((512 * 32 + g.bytes_per_sector - 1) / g.bytes_per_sector);
    const uint64_t fat_sectors =
        (fat_bytes_for_entries((uint64_t)g.target_clusters + 2, g.fat_bits) +
         g.bytes_per_sector - 1) / g.bytes_per_sector;

    uint64_t total_sectors = reserved + 2 * fat_sectors + root_sectors +
                             (uint64_t)g.target_clusters * g.sectors_per_cluster;

    // Nudge the size until the layout yields exactly the target. Each extra
    // cluster's worth of sectors adds one cluster, except where it pushes the
    // FAT over a sector boundary, so this converges in a handful of rounds.
    for (int i = 0; i < 32; i++) {
        const uint32_t got = clusters_for_sectors(g, total_sectors);
        if (got == g.target_clusters) {
            break;
        }
        if (got < g.target_clusters) {
            total_sectors += (uint64_t)(g.target_clusters - got) * g.sectors_per_cluster;
        } else {
            total_sectors -= (uint64_t)(got - g.target_clusters) * g.sectors_per_cluster;
        }
    }

    return (size_t)(total_sectors * g.bytes_per_sector);
}

fat_format_args_t format_args_for(const geometry &g) {
    fat_format_args_t args = {};
    args.fat_bits = g.fat_bits;
    args.bytes_per_sector = g.bytes_per_sector;
    args.sectors_per_cluster = g.sectors_per_cluster;
    args.volume_label = g.name;
    return args;
}

void ram_volume::destroy() {
    if (mounted_) {
        fs_unmount(mount_path_);
        mounted_ = false;
    }
    if (dev_) {
        // drop our reference, then remove the device from the global list
        bio_close(dev_);
        bio_unregister_device(dev_);
        dev_ = nullptr;
    }
    if (mem_) {
        free(mem_);
        mem_ = nullptr;
    }
    size_ = 0;
}

status_t ram_volume::create(const char *name, const char *mount_path, size_t size,
                            const fat_format_args_t &args) {
    destroy();

    strlcpy(device_name_, name, sizeof(device_name_));
    strlcpy(mount_path_, mount_path, sizeof(mount_path_));

    mem_ = memalign(CACHE_LINE, size);
    if (!mem_) {
        printf("ram_volume: cannot allocate %zu bytes for '%s'\n", size, name);
        return ERR_NO_MEMORY;
    }
    size_ = size;

    // create_membdev keeps a pointer to the buffer; it does not copy it
    int err = create_membdev(device_name_, mem_, size_);
    if (err < 0) {
        destroy();
        return err;
    }

    // hold a reference so the device stays alive for the volume's lifetime and
    // so destroy() has a handle to unregister
    dev_ = bio_open(device_name_);
    if (!dev_) {
        destroy();
        return ERR_NOT_FOUND;
    }

    status_t st = fs_format_device("fat", device_name_, &args);
    if (st < 0) {
        printf("ram_volume: format of '%s' failed: %d\n", name, st);
        destroy();
        return st;
    }

    st = fs_mount(mount_path_, "fat", device_name_, FS_MOUNT_OPTION_NONE);
    if (st < 0) {
        printf("ram_volume: mount of '%s' failed: %d\n", name, st);
        destroy();
        return st;
    }
    mounted_ = true;

    return NO_ERROR;
}

status_t ram_volume::remount() {
    if (!mounted_) {
        return ERR_BAD_STATE;
    }

    status_t st = fs_unmount(mount_path_);
    if (st < 0) {
        return st;
    }
    mounted_ = false;

    st = fs_mount(mount_path_, "fat", device_name_, FS_MOUNT_OPTION_NONE);
    if (st < 0) {
        return st;
    }
    mounted_ = true;

    return NO_ERROR;
}

uint64_t fat_bytes_for_entries(uint64_t entries, uint32_t fat_bits) {
    switch (fat_bits) {
        case 12:
            return (entries * 3 + 1) / 2; // 1.5 bytes each, rounded up
        case 16:
            return entries * 2;
        default:
            return entries * 4;
    }
}

uint32_t fat_bits_for_cluster_count(uint32_t data_cluster_count) {
    if (data_cluster_count < 4085) {
        return 12;
    } else if (data_cluster_count < 65525) {
        return 16;
    }
    return 32;
}

status_t solve_layout(layout *out, uint32_t fat_bits) {
    out->fat_bits = fat_bits;
    out->root_dir_sectors =
        (fat_bits == 32)
            ? 0
            : ((out->root_entries * 32 + out->bytes_per_sector - 1) / out->bytes_per_sector);

    uint32_t sectors_per_fat = 1;
    for (int i = 0; i < 16; i++) {
        const uint64_t overhead = (uint64_t)out->reserved_sectors +
                                  (uint64_t)out->fat_count * sectors_per_fat +
                                  out->root_dir_sectors;
        if (overhead >= out->total_sectors) {
            return ERR_TOO_BIG;
        }

        const uint32_t data_sectors = out->total_sectors - (uint32_t)overhead;
        const uint32_t clusters = data_sectors / out->sectors_per_cluster;

        const uint64_t needed_bytes = fat_bytes_for_entries((uint64_t)clusters + 2, fat_bits);
        const uint32_t needed_sectors =
            (uint32_t)((needed_bytes + out->bytes_per_sector - 1) / out->bytes_per_sector);

        if (needed_sectors <= sectors_per_fat) {
            // Stable: this FAT holds every cluster the layout produces.
            out->sectors_per_fat = sectors_per_fat;
            out->data_start_sector = (uint32_t)overhead;
            out->data_cluster_count = clusters;
            return NO_ERROR;
        }
        sectors_per_fat = needed_sectors;
    }

    return ERR_NOT_VALID;
}

status_t verify_layout_mounts_as(const layout &l, uint32_t expected_fat_bits) {
    const uint32_t data_sectors = l.total_sectors - l.data_start_sector;
    const uint32_t total_clusters = data_sectors / l.sectors_per_cluster + 2;
    const uint32_t data_cluster_count = total_clusters - 2;

    if (data_cluster_count != l.data_cluster_count) {
        printf("fat_format: cluster count mismatch: layout %u, mount would see %u\n",
               l.data_cluster_count, data_cluster_count);
        return ERR_NOT_VALID;
    }

    const uint32_t selected = fat_bits_for_cluster_count(data_cluster_count);
    if (selected != expected_fat_bits) {
        printf("fat_format: %u data clusters would mount as FAT%u, not FAT%u\n",
               data_cluster_count, selected, expected_fat_bits);
        return ERR_INVALID_ARGS;
    }

    // The FAT must be able to address every cluster it claims to have.
    const uint64_t fat_capacity = (uint64_t)l.sectors_per_fat * l.bytes_per_sector;
    const uint64_t fat_needed = fat_bytes_for_entries((uint64_t)data_cluster_count + 2,
                                                      expected_fat_bits);
    if (fat_capacity < fat_needed) {
        printf("fat_format: FAT of %llu bytes cannot hold %u clusters (needs %llu)\n",
               fat_capacity, data_cluster_count, fat_needed);
        return ERR_NOT_VALID;
    }

    return NO_ERROR;
}

uint32_t default_sectors_per_cluster(uint32_t total_sectors, uint32_t bytes_per_sector) {
    const uint64_t total_bytes = (uint64_t)total_sectors * bytes_per_sector;
    uint32_t target_cluster_bytes;
    if (total_bytes <= 64ULL * 1024 * 1024) {
        target_cluster_bytes = 512;
    } else if (total_bytes <= 256ULL * 1024 * 1024) {
        target_cluster_bytes = 4096;
    } else if (total_bytes <= 8ULL * 1024 * 1024 * 1024) {
        target_cluster_bytes = 8192;
    } else {
        target_cluster_bytes = 32768;
    }

    uint32_t spc = target_cluster_bytes / bytes_per_sector;
    if (spc < 1) {
        spc = 1;
    }
    if (spc > 128) {
        spc = 128;
    }
    return spc;
}

void write_volume_label(uint8_t *buf, size_t offset, const char *label) {
    memset(buf + offset, ' ', 11);
    if (!label) {
        label = "NO NAME";
    }
    for (size_t i = 0; i < 11 && label[i]; i++) {
        buf[offset + i] = (uint8_t)label[i];
    }
}

void build_boot_sector(uint8_t *bs, const layout &l, const fat_format_args_t &args) {
    memset(bs, 0, l.bytes_per_sector);

    // short jump then nop, as every real formatter writes
    bs[0] = 0xeb;
    bs[1] = (l.fat_bits == 32) ? 0x58 : 0x3c;
    bs[2] = 0x90;
    memcpy(bs + 3, "MSWIN4.1", 8);

    fat_write16(bs, 0x0b, (uint16_t)l.bytes_per_sector);
    bs[0x0d] = (uint8_t)l.sectors_per_cluster;
    fat_write16(bs, 0x0e, (uint16_t)l.reserved_sectors);
    bs[0x10] = (uint8_t)l.fat_count;
    fat_write16(bs, 0x11, (uint16_t)l.root_entries);
    // total sectors goes in the 16 bit field when it fits, otherwise the 32 bit one
    if (l.total_sectors <= 0xffff && l.fat_bits != 32) {
        fat_write16(bs, 0x13, (uint16_t)l.total_sectors);
        fat_write32(bs, 0x20, 0);
    } else {
        fat_write16(bs, 0x13, 0);
        fat_write32(bs, 0x20, l.total_sectors);
    }
    bs[0x15] = kMediaDescriptor;
    fat_write16(bs, 0x16, (l.fat_bits == 32) ? 0 : (uint16_t)l.sectors_per_fat);
    fat_write16(bs, 0x18, 32); // sectors per track, geometry is not meaningful here
    fat_write16(bs, 0x1a, 8);  // number of heads, likewise
    fat_write32(bs, 0x1c, 0);  // hidden sectors

    const uint32_t volume_id = args.volume_id ? args.volume_id : kDefaultVolumeId;

    if (l.fat_bits == 32) {
        fat_write32(bs, 0x24, l.sectors_per_fat);
        fat_write16(bs, 0x28, 0); // ext flags: FAT mirroring enabled, active FAT 0
        fat_write16(bs, 0x2a, 0); // filesystem version
        fat_write32(bs, 0x2c, kFat32RootCluster);
        fat_write16(bs, 0x30, kFat32FsInfoSector);
        fat_write16(bs, 0x32, kFat32BackupBootSector);
        bs[0x40] = 0x80; // drive number
        bs[0x42] = 0x29; // extended boot signature
        fat_write32(bs, 0x43, volume_id);
        write_volume_label(bs, 0x47, args.volume_label);
        memcpy(bs + 0x52, "FAT32   ", 8);
    } else {
        bs[0x24] = 0x80;
        bs[0x26] = 0x29;
        fat_write32(bs, 0x27, volume_id);
        write_volume_label(bs, 0x2b, args.volume_label);
        memcpy(bs + 0x36, (l.fat_bits == 12) ? "FAT12   " : "FAT16   ", 8);
    }

    bs[0x1fe] = 0x55;
    bs[0x1ff] = 0xaa;
}

void build_fsinfo_sector(uint8_t *buf, const layout &l) {
    memset(buf, 0, l.bytes_per_sector);
    fat_write32(buf, 0x000, kFsInfoLeadSig);
    fat_write32(buf, 0x1e4, kFsInfoStructSig);
    // The root directory occupies one cluster already.
    fat_write32(buf, 0x1e8, l.data_cluster_count - 1);
    fat_write32(buf, 0x1ec, kFat32RootCluster + 1);
    fat_write32(buf, 0x1fc, kFsInfoTrailSig);
}

status_t zero_sectors(bdev_t *dev, const layout &l, uint32_t start_sector, uint32_t count) {
    if (count == 0) {
        return NO_ERROR;
    }

    const uint32_t chunk_sectors = MIN(count, MAX(1u, 65536u / l.bytes_per_sector));
    const size_t chunk_bytes = (size_t)chunk_sectors * l.bytes_per_sector;

    auto *buf = (uint8_t *)calloc(1, chunk_bytes);
    if (!buf) {
        return ERR_NO_MEMORY;
    }
    auto free_buf = lk::make_auto_call([&]() { free(buf); });

    uint32_t remaining = count;
    uint32_t sector = start_sector;
    while (remaining > 0) {
        const uint32_t this_count = MIN(remaining, chunk_sectors);
        const size_t this_bytes = (size_t)this_count * l.bytes_per_sector;
        ssize_t err = bio_write(dev, buf, (off_t)sector * l.bytes_per_sector, this_bytes);
        if (err < 0) {
            return (status_t)err;
        }
        if ((size_t)err != this_bytes) {
            return ERR_IO;
        }
        sector += this_count;
        remaining -= this_count;
    }

    return NO_ERROR;
}

status_t write_sector(bdev_t *dev, const layout &l, uint32_t sector, const void *buf) {
    ssize_t err = bio_write(dev, buf, (off_t)sector * l.bytes_per_sector, l.bytes_per_sector);
    if (err < 0) {
        return (status_t)err;
    }
    return ((size_t)err == l.bytes_per_sector) ? NO_ERROR : ERR_IO;
}

status_t write_fat_head_sectors(bdev_t *dev, const layout &l) {
    auto *buf = (uint8_t *)calloc(1, l.bytes_per_sector);
    if (!buf) {
        return ERR_NO_MEMORY;
    }
    auto free_buf = lk::make_auto_call([&]() { free(buf); });

    switch (l.fat_bits) {
        case 12:
            // entry 0 is the media descriptor extended with ones, entry 1 is EOC.
            // Packed 12 bit: 0xff8 then 0xfff -> f8 ff ff
            buf[0] = kMediaDescriptor;
            buf[1] = 0xff;
            buf[2] = 0xff;
            break;
        case 16:
            // entry 1 keeps both the clean-shutdown and no-hard-error bits set
            fat_write16(buf, 0, 0xff00 | kMediaDescriptor);
            fat_write16(buf, 2, 0xffff);
            break;
        default:
            fat_write32(buf, 0, 0x0fffff00 | kMediaDescriptor);
            fat_write32(buf, 4, 0x0fffffff);
            // the root directory is a one cluster chain that ends immediately
            fat_write32(buf, 8, 0x0fffffff);
            break;
    }

    for (uint32_t i = 0; i < l.fat_count; i++) {
        const uint32_t fat_start = l.reserved_sectors + i * l.sectors_per_fat;
        status_t err = write_sector(dev, l, fat_start, buf);
        if (err < 0) {
            return err;
        }
    }

    return NO_ERROR;
}

bool test_fat_write_reopened_file() {
    return test_mount_wrapper([]() {
        BEGIN_TEST;

        const char *path = test_path "/reopenwr";
        const uint8_t data[] = {'a', 'b', 'c'};

        // create it empty and close it
        filehandle *handle = nullptr;
        ASSERT_EQ(NO_ERROR, fs_create_file(path, &handle, 0));
        ASSERT_NONNULL(handle);
        ASSERT_EQ(NO_ERROR, fs_close_file(handle));

        // reopen and write
        handle = nullptr;
        ASSERT_EQ(NO_ERROR, fs_open_file(path, &handle));
        ASSERT_NONNULL(handle);
        ASSERT_EQ((ssize_t)sizeof(data), fs_write_file(handle, data, 0, sizeof(data)));

        // the size must be visible through this handle...
        struct file_stat st = {};
        ASSERT_EQ(NO_ERROR, fs_stat_file(handle, &st));
        EXPECT_EQ(sizeof(data), (size_t)st.size);
        ASSERT_EQ(NO_ERROR, fs_close_file(handle));

        // ...and must have reached the directory entry, so a fresh open sees it.
        // Close on every path: leaking a handle here makes fs_unmount trip its
        // "no open files" assert and every later test fail for the wrong reason.
        handle = nullptr;
        ASSERT_EQ(NO_ERROR, fs_open_file(path, &handle));
        ASSERT_NONNULL(handle);
        auto close_cleanup = lk::make_auto_call([&]() { fs_close_file(handle); });

        st = {};
        ASSERT_EQ(NO_ERROR, fs_stat_file(handle, &st));
        EXPECT_EQ(sizeof(data), (size_t)st.size);

        uint8_t readback[sizeof(data)] = {};
        ASSERT_EQ((ssize_t)sizeof(readback), fs_read_file(handle, readback, 0, sizeof(readback)));
        EXPECT_EQ(0, memcmp(data, readback, sizeof(data)));

        close_cleanup.cancel();
        ASSERT_EQ(NO_ERROR, fs_close_file(handle));

        ASSERT_EQ(NO_ERROR, fs_remove_file(path));

        END_TEST;
    });
}

bool device_required() {
    static bool checked = false;
    static bool required = false;

    if (!checked) {
        checked = true;
        bool val = false;
        if (cmdline_get_bool("test.fat.required", &val) == NO_ERROR) {
            required = val;
        }
    }
    return required;
}

status_t fat_fs::count_free_clusters_locked(uint32_t *out_free) {
    DEBUG_ASSERT(lock.is_held());
    DEBUG_ASSERT(out_free);

    uint32_t free_count = 0;
    for (uint32_t cluster = 2; cluster < info_.total_clusters; cluster++) {
        // fat_next_cluster_in_chain handles all three FAT widths, including the
        // FAT12 entry that straddles a sector boundary. A free entry reads as 0.
        if (fat_next_cluster_in_chain(this, cluster) == 0) {
            free_count++;
        }
    }

    *out_free = free_count;
    return NO_ERROR;
}

status_t fat_fs::fs_stat(fscookie *cookie, struct fs_stat *stat) {
    auto *fat = (fat_fs *)cookie;

    if (!stat) {
        return ERR_INVALID_ARGS;
    }

    AutoLock guard(fat->lock);

    const auto &info = fat->info();

    // clusters 0 and 1 are reserved, so the data area holds total_clusters - 2 clusters
    const uint64_t data_clusters = info.total_clusters - 2;
    stat->total_space = data_clusters * info.bytes_per_cluster;

    // On FAT32 a valid FSInfo free count is authoritative and avoids walking the
    // whole table; otherwise count the free entries directly.
    uint32_t free_clusters;
    if (info.fat_bits == 32 && info.fsinfo_valid &&
        info.fsinfo_free_clusters != UINT32_MAX) {
        free_clusters = info.fsinfo_free_clusters;
    } else {
        status_t err = fat->count_free_clusters_locked(&free_clusters);
        if (err < 0) {
            return err;
        }
    }
    stat->free_space = (uint64_t)free_clusters * info.bytes_per_cluster;

    // FAT has no inode table; directory entries are allocated out of the data area.
    stat->total_inodes = 0;
    stat->free_inodes = 0;

    return NO_ERROR;
}

static void
free_rpc_nvmf_subsystem_remove_listener_ext(
	struct rpc_nvmf_subsystem_remove_listener_ext *ereq)
{
	free_rpc_nvmf_subsystem_remove_listener(&ereq->req);
	free(ereq);
}

static void
nvmf_rpc_remove_listener_resumed(struct spdk_nvmf_subsystem *subsystem,
				 void *cb_arg, int status)
{
	struct rpc_nvmf_subsystem_remove_listener_ext *ereq = cb_arg;

	if (ereq->req.request) {
		spdk_jsonrpc_send_bool_response(ereq->req.request, true);
	}

	free_rpc_nvmf_subsystem_remove_listener_ext(ereq);
}

static void
rpc_nvmf_remove_listener_paused(struct spdk_nvmf_subsystem *subsystem,
				void *cb_arg, int status)
{
	struct rpc_nvmf_subsystem_remove_listener_ext *ereq = cb_arg;
	int rc;

	rc = spdk_nvmf_subsystem_remove_listener(subsystem, &ereq->trid);
	if (rc) {
		SPDK_ERRLOG("Unable to remove listener, rc %d\n", rc);
		spdk_jsonrpc_send_error_response(ereq->req.request, SPDK_JSONRPC_ERROR_INVALID_PARAMS,
						 "Invalid parameters");
		goto err;
	}

	rc = spdk_nvmf_transport_stop_listen_async(ereq->transport, &ereq->trid, subsystem,
			nvmf_rpc_stop_listen_async_done, ereq);
	if (rc) {
		SPDK_ERRLOG("Unable to stop listener, rc %d\n", rc);
		spdk_jsonrpc_send_error_response(ereq->req.request, SPDK_JSONRPC_ERROR_INTERNAL_ERROR,
						 "Internal error");
		goto err;
	}

	return;

err:
	ereq->req.request = NULL;

	if (spdk_nvmf_subsystem_resume(subsystem, nvmf_rpc_remove_listener_resumed, ereq)) {
		free_rpc_nvmf_subsystem_remove_listener_ext(ereq);
	}
}

static void
free_rpc_nvmf_subsystem_listener_set_ana_state_ext(
	struct rpc_nvmf_subsystem_listener_set_ana_state_ext *ereq)
{
	free_rpc_nvmf_subsystem_listener_set_ana_state(&ereq->req);
	free(ereq);
}

static void
nvmf_rpc_set_ana_state_resumed(struct spdk_nvmf_subsystem *subsystem,
			       void *cb_arg, int status)
{
	struct rpc_nvmf_subsystem_listener_set_ana_state_ext *ereq = cb_arg;

	if (ereq->req.request) {
		spdk_jsonrpc_send_bool_response(ereq->req.request, true);
	}

	free_rpc_nvmf_subsystem_listener_set_ana_state_ext(ereq);
}

static void
rpc_nvmf_set_ana_state_paused(struct spdk_nvmf_subsystem *subsystem,
			      void *cb_arg, int status)
{
	struct rpc_nvmf_subsystem_listener_set_ana_state_ext *ereq = cb_arg;

	spdk_nvmf_subsystem_set_ana_state(subsystem, &ereq->trid,
					  (enum spdk_nvme_ana_state)ereq->req.ana_state,
					  ereq->req.anagrpid,
					  nvmf_rpc_set_ana_state_done, ereq);
}

static struct spdk_nvmf_subsystem *
_rpc_nvmf_get_subsystem(struct spdk_jsonrpc_request *request,
			const char *tgt_name, const char *nqn,
			struct spdk_nvmf_tgt **tgt_out)
{
	struct spdk_nvmf_tgt *tgt;
	struct spdk_nvmf_subsystem *subsystem;

	if (tgt_out) {
		*tgt_out = NULL;
	}

	tgt = spdk_nvmf_get_tgt(tgt_name);
	if (!tgt) {
		SPDK_ERRLOG("Unable to find a target object.\n");
		spdk_jsonrpc_send_error_response_fmt(request,
						     tgt_name ? SPDK_JSONRPC_ERROR_INVALID_PARAMS : SPDK_JSONRPC_ERROR_INTERNAL_ERROR,
						     tgt_name ? "NVMf target '%s' not found" : "No default NVMf target found; specify tgt_name",
						     tgt_name);
		return NULL;
	}

	if (tgt_out) {
		*tgt_out = tgt;
	}

	if (!nqn) {
		return NULL;
	}

	subsystem = spdk_nvmf_tgt_find_subsystem(tgt, nqn);
	if (!subsystem) {
		SPDK_ERRLOG("Unable to find subsystem with NQN %s\n", nqn);
		spdk_jsonrpc_send_error_response_fmt(request, SPDK_JSONRPC_ERROR_INVALID_PARAMS,
						     "Subsystem with NQN '%s' not found", nqn);
		return NULL;
	}

	return subsystem;
}

static void
rpc_nvmf_ns_remove_host_resumed(struct spdk_nvmf_subsystem *subsystem,
				void *cb_arg, int status)
{
	struct rpc_nvmf_ns_remove_host_ext *ereq = cb_arg;

	if (!ereq->response_sent) {
		spdk_jsonrpc_send_bool_response(ereq->req.request, true);
	}

	free_rpc_nvmf_ns_remove_host_ext(ereq);
}

static void
rpc_nvmf_ns_remove_host_paused(struct spdk_nvmf_subsystem *subsystem,
			       void *cb_arg, int status)
{
	struct rpc_nvmf_ns_remove_host_ext *ereq = cb_arg;
	struct rpc_nvmf_ns_remove_host_ctx *req = &ereq->req;
	int ret;

	ret = spdk_nvmf_ns_remove_host(subsystem, req->nsid, req->host, 0);
	if (ret < 0) {
		SPDK_ERRLOG("Unable to remove %s from namespace ID %u\n", req->host, req->nsid);
		spdk_jsonrpc_send_error_response(req->request, SPDK_JSONRPC_ERROR_INVALID_PARAMS,
						 "Invalid parameters");
		ereq->response_sent = true;
	}

	if (spdk_nvmf_subsystem_resume(subsystem, rpc_nvmf_ns_remove_host_resumed, ereq)) {
		if (!ereq->response_sent) {
			spdk_jsonrpc_send_error_response(req->request, SPDK_JSONRPC_ERROR_INTERNAL_ERROR,
							 "Internal error");
		}
		free_rpc_nvmf_ns_remove_host_ext(ereq);
	}
}

static void
_net_ebpf_extension_sock_addr_apply_verdict(_Inout_ FWPS_CLASSIFY_OUT* classify_output, uint32_t verdict)
{
    switch (verdict) {
    case BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT:
        classify_output->actionType = FWP_ACTION_PERMIT;
        break;
    case BPF_SOCK_ADDR_VERDICT_PROCEED_HARD:
        classify_output->actionType = FWP_ACTION_PERMIT;
        classify_output->rights &= ~FWPS_RIGHT_ACTION_WRITE;
        break;
    default:
        classify_output->actionType = FWP_ACTION_BLOCK;
        classify_output->rights &= ~FWPS_RIGHT_ACTION_WRITE;
        break;
    }
}

_native_module_helper::_native_module_helper(_native_module_helper&& other) noexcept
    : _file_name(std::move(other._file_name)), _delete_file_on_destruction(other._delete_file_on_destruction),
      _is_main_thread(other._is_main_thread)
{
    other._delete_file_on_destruction = false;
}

_native_module_helper&
_native_module_helper::operator=(_native_module_helper&& other) noexcept
{
    if (this != &other) {
        if (_delete_file_on_destruction && !_file_name.empty()) {
            DeleteFileA(_file_name.c_str());
        }
        _file_name = std::move(other._file_name);
        _delete_file_on_destruction = other._delete_file_on_destruction;
        _is_main_thread = other._is_main_thread;
        other._delete_file_on_destruction = false;
    }
    return *this;
}

static module_spec
sock_addr_bind_module(ADDRESS_FAMILY family)
{
    return {
        .object_file = "cgroup_sock_addr_bind",
        .programs{
            {.program_name = (family == AF_INET) ? "authorize_bind4" : "authorize_bind6",
             .attach_type = (family == AF_INET) ? BPF_CGROUP_INET4_BIND : BPF_CGROUP_INET6_BIND}},
    };
}

static program_policy_spec
sock_addr_bind_verdict(size_t module_index, ebpf_sock_addr_verdict_t verdict)
{
    return {.target = {.module_index = module_index}, .sock_addr_bind_verdict = verdict};
}

static GUID
sock_addr_bind_wfp_layer(ADDRESS_FAMILY family)
{
    return (family == AF_INET) ? FWPM_LAYER_ALE_RESOURCE_ASSIGNMENT_V4 : FWPM_LAYER_ALE_RESOURCE_ASSIGNMENT_V6;
}

static int
_bind_multi_attach_try_bind(socket_family_t socket_family, ADDRESS_FAMILY address_family, IPPROTO protocol)
{
    int sock_type = (protocol == IPPROTO_TCP) ? SOCK_STREAM : SOCK_DGRAM;
    ADDRESS_FAMILY socket_address_family = (socket_family == socket_family_t::IPv4) ? AF_INET : AF_INET6;
    SOCKET sock = WSASocketW(socket_address_family, sock_type, protocol, nullptr, 0, 0);
    SAFE_REQUIRE(sock != INVALID_SOCKET);

    if (socket_family == socket_family_t::Dual) {
        DWORD v6only = 0;
        SAFE_REQUIRE(
            setsockopt(sock, IPPROTO_IPV6, IPV6_V6ONLY, reinterpret_cast<const char*>(&v6only), sizeof(v6only)) == 0);
    }

    int rc;
    if (socket_family == socket_family_t::IPv4) {
        sockaddr_in bind_addr = {};
        bind_addr.sin_family = AF_INET;
        bind_addr.sin_addr = in4addr_loopback;
        bind_addr.sin_port = htons(SOCKET_TEST_PORT);
        rc = bind(sock, reinterpret_cast<sockaddr*>(&bind_addr), sizeof(bind_addr));
    } else {
        sockaddr_in6 bind_addr = {};
        if (address_family == AF_INET) {
            // Dual-stack socket bound to a v4-mapped address, which selects the V4 bind layer.
            IN6ADDR_SETV4MAPPED(&bind_addr, &in4addr_loopback, scopeid_unspecified, htons(SOCKET_TEST_PORT));
        } else {
            IN6ADDR_SETLOOPBACK(&bind_addr);
            bind_addr.sin6_port = htons(SOCKET_TEST_PORT);
        }
        rc = bind(sock, reinterpret_cast<sockaddr*>(&bind_addr), sizeof(bind_addr));
    }

    int error = (rc == 0) ? 0 : WSAGetLastError();
    closesocket(sock);
    return error;
}

void
    detach()
    {
        SAFE_REQUIRE(attached);
        SAFE_REQUIRE(bpf_prog_detach2(bpf_program__fd(program), compartment_id, attach_type) == 0);
        attached = false;
    }

~_bind_attach_guard()
    {
        if (attached) {
            // Best effort: destructors must not throw, so the result is deliberately ignored.
            bpf_prog_detach2(bpf_program__fd(program), compartment_id, attach_type);
        }
    }

static void
test_bind_multi_attach_wildcard_and_specific(
    ADDRESS_FAMILY address_family,
    IPPROTO protocol,
    bool attach_wildcard_first,
    const bind_filter_scope_scenario (&scenarios)[scenario_count])
{
    // Loads program_count_per_group * 2 programs: program_count_per_group attached to a
    // specific compartment id, and program_count_per_group attached with the wildcard
    // compartment id. It then verifies that a reject from either group determines the
    // bind result, using both a dual-stack socket and a socket of the address family
    // under test.
    //
    // attach_wildcard_first verifies that the result does not depend on attach order.
    constexpr uint32_t program_count_per_group = 2;
    constexpr uint32_t program_count = program_count_per_group * 2;

    // The compartment the test process runs in, so that the compartment-specific filter
    // matches the same bind as the wildcard filter.
    constexpr uint32_t specific_compartment_id = DEFAULT_COMPARTMENT_ID;

    native_module_helper_t helpers[program_count];
    struct bpf_object* objects[program_count] = {nullptr};
    bpf_object_ptr object_ptrs[program_count];
    _bind_attach_guard attach_guards[program_count];
    fd_t verdict_map_fds[program_count] = {ebpf_fd_invalid};
    bool is_specific[program_count] = {false};

    const char* program_name = (address_family == AF_INET) ? "authorize_bind4" : "authorize_bind6";
    bpf_attach_type attach_type = (address_family == AF_INET) ? BPF_CGROUP_INET4_BIND : BPF_CGROUP_INET6_BIND;

    // Load the programs. Each helper mangles the file name so the same object loads as an
    // independent module with its own bind_verdict_map.
    for (uint32_t i = 0; i < program_count; i++) {
        helpers[i].initialize("cgroup_sock_addr_bind", _is_main_thread);
        objects[i] = bpf_object__open(helpers[i].get_file_name().c_str());
        SAFE_REQUIRE(objects[i] != nullptr);
        object_ptrs[i] = bpf_object_ptr(objects[i]);
        SAFE_REQUIRE(bpf_object__load(objects[i]) == 0);

        bpf_map* verdict_map = bpf_object__find_map_by_name(objects[i], "bind_verdict_map");
        SAFE_REQUIRE(verdict_map != nullptr);
        verdict_map_fds[i] = bpf_map__fd(verdict_map);
        SAFE_REQUIRE(verdict_map_fds[i] != ebpf_fd_invalid);
    }

    // Attach one group to a specific compartment and the other with the wildcard compartment
    // id, so both filter contexts match a bind in that compartment.
    for (uint32_t i = 0; i < program_count; i++) {
        bpf_program* program = bpf_object__find_program_by_name(objects[i], program_name);
        SAFE_REQUIRE(program != nullptr);

        const bool first_group = (i < program_count_per_group);
        is_specific[i] = attach_wildcard_first ? !first_group : first_group;
        const uint32_t compartment_id = is_specific[i] ? specific_compartment_id : UNSPECIFIED_COMPARTMENT_ID;

        CAPTURE(i, program_name, is_specific[i]);
        int result =
            bpf_prog_attach(bpf_program__fd(const_cast<const bpf_program*>(program)), compartment_id, attach_type, 0);
        SAFE_REQUIRE(result == 0);

        attach_guards[i].program = program;
        attach_guards[i].compartment_id = compartment_id;
        attach_guards[i].attach_type = attach_type;
        attach_guards[i].attached = true;
    }

    const socket_family_t socket_families[] = {
        socket_family_t::Dual, (address_family == AF_INET) ? socket_family_t::IPv4 : socket_family_t::IPv6};

    for (const auto& scenario : scenarios) {
        INFO("Scenario: " << scenario.name);
        ebpf_sock_addr_verdict_t verdicts[program_count] = {};
        uint32_t specific_index = 0;
        uint32_t wildcard_index = 0;
        for (uint32_t i = 0; i < program_count; i++) {
            verdicts[i] = is_specific[i] ? scenario.specific_verdicts[specific_index++]
                                         : scenario.wildcard_verdicts[wildcard_index++];
            _update_sock_addr_bind_verdict_map_entry(
                verdict_map_fds[i],
                htons(static_cast<uint16_t>(SOCKET_TEST_PORT)),
                static_cast<uint8_t>(protocol),
                verdicts[i]);
        }

        for (socket_family_t socket_family : socket_families) {
            CAPTURE(attach_wildcard_first, scenario.name, static_cast<uint32_t>(socket_family));
            SAFE_REQUIRE(
                _bind_multi_attach_try_bind(socket_family, address_family, protocol) == scenario.expected_error);
        }
    }

    // Explicitly verify successful cleanup. The guards remain as failure-path protection.
    for (auto& attach_guard : attach_guards) {
        attach_guard.detach();
    }
}

static _Must_inspect_result_ ebpf_result_t
netebpfext_unit_invoke_sock_addr_bind_program(
    _In_ const void* client_binding_context, _In_ const void* context, _Out_ uint32_t* result)
{
    auto client_context = (test_sock_addr_client_context_t*)client_binding_context;
    auto sock_addr_context = (bpf_sock_addr_t*)context;

    if (client_context->validate_sock_addr_entries) {
        REQUIRE((sock_addr_context->family == AF_INET || sock_addr_context->family == AF_INET6));
        // user_ip/user_port carry the local bind address (mirrors Linux bind semantics).
        REQUIRE(sock_addr_context->user_ip4 == htonl(0x01020304));
        REQUIRE(sock_addr_context->user_port == htons(1235));
        REQUIRE(sock_addr_context->protocol == IPPROTO_TCP);
        // No remote endpoint for bind; msg_src_* must be zero.
        REQUIRE(sock_addr_context->msg_src_ip4 == 0);
        REQUIRE(sock_addr_context->msg_src_port == 0);
        REQUIRE(sock_addr_context->compartment_id == 1);
    }

    int action = client_context->sock_addr_action;
    switch (action) {
    case SOCK_ADDR_TEST_ACTION_PERMIT_SOFT:
        *result = BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;
        break;
    case SOCK_ADDR_TEST_ACTION_PERMIT_HARD:
        *result = BPF_SOCK_ADDR_VERDICT_PROCEED_HARD;
        break;
    case SOCK_ADDR_TEST_ACTION_BLOCK:
        *result = BPF_SOCK_ADDR_VERDICT_REJECT;
        break;
    case SOCK_ADDR_TEST_ACTION_FAILURE:
        return EBPF_FAILED;
    default:
        *result = BPF_SOCK_ADDR_VERDICT_REJECT;
    }
    return EBPF_SUCCESS;
}

static _Must_inspect_result_ ebpf_result_t
netebpfext_unit_capture_sock_addr_bind_program(
    _In_ const void* client_binding_context, _In_ const void* context, _Out_ uint32_t* result)
{
    UNREFERENCED_PARAMETER(client_binding_context);
    auto sock_addr_context = (const bpf_sock_addr_t*)context;
    _captured_bind_context = *sock_addr_context;
    _captured_bind_invoked = true;
    *result = BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;
    return EBPF_SUCCESS;
}

static __forceinline uint32_t
_get_lru_partition(_In_ const ebpf_core_lru_map_t* map)
{
    uint32_t cpu = ebpf_get_current_cpu();

    if (cpu < map->partition_count) {
        return cpu;
    }

    if (map->partition_count == EBPF_LRU_MAXIMUM_PARTITIONS) {
        static_assert(
            (EBPF_LRU_MAXIMUM_PARTITIONS & (EBPF_LRU_MAXIMUM_PARTITIONS - 1)) == 0,
            "Maximum LRU partition count must be a power of two");
        return cpu & (EBPF_LRU_MAXIMUM_PARTITIONS - 1);
    }

    return cpu % map->partition_count;
}

static __forceinline void
_insert_into_hot_list(_Inout_ ebpf_core_lru_map_t* map, size_t partition, _Inout_ ebpf_lru_entry_t* entry)
{
    size_t generation = EBPF_LRU_ENTRY_GENERATION_PTR(map, entry)[partition];
    if (generation == map->partitions[partition].current_generation || generation == EBPF_LRU_INVALID_GENERATION) {
        return;
    }

    _insert_into_hot_list_slow(map, partition, entry);
}

static uint64_t
stack_frame_test(uint64_t r1, uint64_t r2, uint64_t r3, uint64_t r4, uint64_t r5, uint64_t r10, void* context, const program_runtime_context_t* runtime_context)
{
    register uint64_t r0 = 0;
    (void)r2;
    (void)r3;
    (void)r4;
    (void)r5;
    (void)r10;
    (void)context;
    UNREFERENCED_PARAMETER(runtime_context);

    // EBPF_OP_MOV64_REG pc=0 dst=r0 src=r1 offset=0 imm=0
#line 20 "sample/undocked/bpf2bpf_loop.c"
    r0 = r1;
    // EBPF_OP_ADD64_IMM pc=1 dst=r0 src=r0 offset=0 imm=1
#line 22 "sample/undocked/bpf2bpf_loop.c"
    r0 += IMMEDIATE(1);
    // EBPF_OP_EXIT pc=2 dst=r0 src=r0 offset=0 imm=0
#line 22 "sample/undocked/bpf2bpf_loop.c"
    return r0;
}

static uint64_t
stack_frame_test(uint64_t r1, uint64_t r2, uint64_t r3, uint64_t r4, uint64_t r5, uint64_t r10, void* context, const program_runtime_context_t* runtime_context)
{
    register uint64_t r0 = 0;
    (void)r2;
    (void)r3;
    (void)r4;
    (void)r5;
    (void)r10;
    (void)context;
    UNREFERENCED_PARAMETER(runtime_context);

    // EBPF_OP_MOV64_REG pc=0 dst=r0 src=r1 offset=0 imm=0
#line 20 "sample/undocked/bpf2bpf_loop.c"
    r0 = r1;
    // EBPF_OP_ADD64_IMM pc=1 dst=r0 src=r0 offset=0 imm=1
#line 22 "sample/undocked/bpf2bpf_loop.c"
    r0 += IMMEDIATE(1);
    // EBPF_OP_EXIT pc=2 dst=r0 src=r0 offset=0 imm=0
#line 22 "sample/undocked/bpf2bpf_loop.c"
    return r0;
}

static uint64_t
stack_frame_test(uint64_t r1, uint64_t r2, uint64_t r3, uint64_t r4, uint64_t r5, uint64_t r10, void* context, const program_runtime_context_t* runtime_context)
{
    register uint64_t r0 = 0;
    (void)r2;
    (void)r3;
    (void)r4;
    (void)r5;
