__attribute__((noinline)) uint64_t
stack_frame_test(uint64_t value)
{
    return value + 1;
}

int
stack_frame_test_entry(sample_program_context_t* ctx)
{
    (void)ctx;
    volatile uint64_t caller_value = 0x1234;
    uint64_t callee_result = stack_frame_test(caller_value);

    return caller_value == 0x1234 && callee_result == 0x1235 ? 0 : 1;
}

size_t
bpf_code_generator::get_maximum_call_depth(const unsafe_string& entry_name) const
{
    std::map<unsafe_string, size_t> maximum_depths;
    std::set<unsafe_string> active_calls;
    std::function<size_t(const unsafe_string&)> calculate_depth = [&](const unsafe_string& program_name) {
        if (const auto it = maximum_depths.find(program_name); it != maximum_depths.end()) {
            return it->second;
        }
        if (!active_calls.insert(program_name).second) {
            throw bpf_code_generator_exception("recursive local function call: " + program_name.raw());
        }

        const auto program = programs.find(program_name);
        if (program == programs.end()) {
            throw bpf_code_generator_exception("local function call target not found: " + program_name.raw());
        }

        size_t maximum_depth = 1;
        for (const auto& instruction : program->second.output_instructions) {
            if (instruction.instruction.opcode == INST_OP_CALL && instruction.instruction.src == INST_CALL_LOCAL) {
                if (instruction.relocation.empty()) {
                    throw bpf_code_generator_exception("local function call target not found: " + program_name.raw());
                }
                maximum_depth = std::max(maximum_depth, 1 + calculate_depth(instruction.relocation));
            }
        }

        active_calls.erase(program_name);
        maximum_depths.emplace(program_name, maximum_depth);
        return maximum_depth;
    };

    return calculate_depth(entry_name);
}

static _Must_inspect_result_ ebpf_result_t
_ebpf_epoch_initialize_cpu_entry(uint32_t cpu_id)
{
    ebpf_epoch_cpu_entry_t* cpu_entry = &_ebpf_epoch_cpu_table[cpu_id];

    if (cpu_entry->work_queue == NULL) {
        return EBPF_INVALID_ARGUMENT;
    }

    return ebpf_timed_work_queue_initialize(cpu_entry->work_queue, cpu_id);
}

_Acquires_exclusive_lock_(_ebpf_epoch_passive_synchronize_lock) static void _ebpf_epoch_quiesce_passive_synchronization(
    uint32_t cpu_id)
{
    ebpf_epoch_cpu_message_t message = {0};

    EBPF_EPOCH_ACQUIRE_PUSH_LOCK_EXCLUSIVE(&_ebpf_epoch_passive_synchronize_lock);
    EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, _ebpf_epoch_quiesced_cpu == UINT32_MAX);
    EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, _ebpf_epoch_quiesced_thread == NULL);
    _ebpf_epoch_quiesced_cpu = cpu_id;
    _ebpf_epoch_quiesced_thread = KeGetCurrentThread();

    message.message_type = EBPF_EPOCH_CPU_MESSAGE_TYPE_QUIESCE_TIMER_COMPUTATION;
    message.wake_behavior = EBPF_WORK_QUEUE_WAKEUP_ON_INSERT;
    _ebpf_epoch_send_message_and_wait(&message, 0);
}

_Releases_exclusive_lock_(_ebpf_epoch_passive_synchronize_lock) static void _ebpf_epoch_resume_passive_synchronization(
    uint32_t cpu_id)
{
    ebpf_epoch_cpu_message_t message = {0};

    EBPF_EPOCH_FAIL_FAST(
        FAST_FAIL_INVALID_ARG,
        _ebpf_epoch_quiesced_cpu == cpu_id && _ebpf_epoch_cpu_table[0].timer_computation_quiesced);
    EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, _ebpf_epoch_quiesced_thread == KeGetCurrentThread());
    message.message_type = EBPF_EPOCH_CPU_MESSAGE_TYPE_RESUME_TIMER_COMPUTATION;
    message.wake_behavior = EBPF_WORK_QUEUE_WAKEUP_ON_INSERT;
    _ebpf_epoch_send_message_and_wait(&message, 0);
    _ebpf_epoch_quiesced_cpu = UINT32_MAX;
    _ebpf_epoch_quiesced_thread = NULL;
    EBPF_EPOCH_RELEASE_PUSH_LOCK_EXCLUSIVE(&_ebpf_epoch_passive_synchronize_lock);
}

static _Must_inspect_result_ ebpf_result_t
_ebpf_epoch_admit_existing_cpus()
{
    uint32_t first_cpu = UINT32_MAX;
    uint32_t active_cpu_count = KeQueryActiveProcessorCountEx(ALL_PROCESSOR_GROUPS);
    uint32_t previous_cpu = UINT32_MAX;

    if (active_cpu_count == 0 || active_cpu_count > _ebpf_epoch_cpu_count) {
        return EBPF_OPERATION_NOT_SUPPORTED;
    }

    for (uint32_t cpu_id = 0; cpu_id < _ebpf_epoch_cpu_count; cpu_id++) {
        ebpf_epoch_cpu_entry_t* cpu_entry = &_ebpf_epoch_cpu_table[cpu_id];
        if (!cpu_entry->admitted) {
            continue;
        }

        if (cpu_entry->work_queue == NULL) {
            return EBPF_INVALID_ARGUMENT;
        }

        if (first_cpu == UINT32_MAX) {
            first_cpu = cpu_id;
        }

        if (previous_cpu != UINT32_MAX) {
            _ebpf_epoch_cpu_table[previous_cpu].next_active_cpu = cpu_id;
            cpu_entry->previous_active_cpu = previous_cpu;
        }

        previous_cpu = cpu_id;
    }

    if (first_cpu == UINT32_MAX || first_cpu != 0) {
        return EBPF_OPERATION_NOT_SUPPORTED;
    }

    _ebpf_epoch_cpu_table[first_cpu].previous_active_cpu = previous_cpu;
    _ebpf_epoch_cpu_table[previous_cpu].next_active_cpu = first_cpu;

    return EBPF_SUCCESS;
}

static uint32_t
_ebpf_epoch_get_next_active_cpu(uint32_t cpu_id)
{
    uint32_t next_cpu = _ebpf_epoch_cpu_table[cpu_id].next_active_cpu;

    // Bound the walk by the backing table size so a stale link during admission rollback cannot loop indefinitely.
    for (uint32_t attempt = 0; attempt < _ebpf_epoch_cpu_count; attempt++) {
        EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, next_cpu < _ebpf_epoch_cpu_count);
        if (_ebpf_epoch_cpu_table[next_cpu].admitted) {
            return next_cpu;
        }
        next_cpu = _ebpf_epoch_cpu_table[next_cpu].next_active_cpu;
    }

    EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, false);
    return cpu_id;
}

_Function_class_(PROCESSOR_CALLBACK_FUNCTION) static void _ebpf_epoch_processor_change_callback(
    _In_ void* callback_context,
    _In_ PKE_PROCESSOR_CHANGE_NOTIFY_CONTEXT change_context,
    _Inout_ PNTSTATUS operation_status)
{
    UNREFERENCED_PARAMETER(callback_context);

    // The processor-change contract invokes the start and matching completion/failure notifications on the same
    // callback thread, which preserves ownership of the passive synchronization push lock across the pair.
    if (_ebpf_epoch_cpu_table == NULL || change_context->NtNumber >= _ebpf_epoch_cpu_count) {
        return;
    }

    uint32_t cpu_id = change_context->NtNumber;
    ebpf_epoch_cpu_entry_t* cpu_entry = &_ebpf_epoch_cpu_table[cpu_id];

    switch (change_context->State) {
    case KeProcessorAddStartNotify: {
        ebpf_result_t result = _ebpf_epoch_allocate_cpu_entry(cpu_id);
        if (result != EBPF_SUCCESS) {
            *operation_status = STATUS_INSUFFICIENT_RESOURCES;
            return;
        }

        result = _ebpf_epoch_initialize_cpu_entry(cpu_id);
        if (result != EBPF_SUCCESS) {
            *operation_status = STATUS_INVALID_PARAMETER;
            return;
        }

        if (_ebpf_epoch_startup_registration_in_progress) {
            cpu_entry->admitted = true;
            return;
        }

        // Treat a repeated start notification for an admitted CPU as an idempotent no-op.
        if (cpu_entry->admitted) {
            return;
        }

        // Serialize hot-add transactions before patching the active-CPU ring. This helper acquires the
        // passive-synchronization push lock exclusive and keeps it held until add-complete/failure resumes,
        // so concurrent KeProcessorAddStartNotify callbacks cannot splice the ring at the same time.
        _ebpf_epoch_quiesce_passive_synchronization(cpu_id);

        uint32_t predecessor_cpu = UINT32_MAX;
        uint32_t first_cpu = UINT32_MAX;
        uint32_t last_cpu = UINT32_MAX;

        for (uint32_t candidate_cpu = 0; candidate_cpu < _ebpf_epoch_cpu_count; candidate_cpu++) {
            if (!_ebpf_epoch_cpu_table[candidate_cpu].admitted) {
                continue;
            }

            if (first_cpu == UINT32_MAX) {
                first_cpu = candidate_cpu;
            }

            last_cpu = candidate_cpu;

            if (candidate_cpu < cpu_id) {
                predecessor_cpu = candidate_cpu;
            }
        }
        if (first_cpu == UINT32_MAX) {
            *operation_status = STATUS_INVALID_DEVICE_STATE;
            _ebpf_epoch_resume_passive_synchronization(cpu_id);
            _ebpf_epoch_destroy_cpu_entry(cpu_entry);
            return;
        }

        if (predecessor_cpu == UINT32_MAX) {
            predecessor_cpu = last_cpu;
        }

        uint32_t successor_cpu = _ebpf_epoch_get_next_active_cpu(predecessor_cpu);
        cpu_entry->previous_active_cpu = predecessor_cpu;
        cpu_entry->next_active_cpu = successor_cpu;

        ebpf_epoch_cpu_message_t update_next_message = {0};
        update_next_message.message_type = EBPF_EPOCH_CPU_MESSAGE_TYPE_UPDATE_NEXT_ACTIVE_CPU;
        update_next_message.message.update_next_active_cpu.next_cpu = cpu_id;
        update_next_message.wake_behavior = EBPF_WORK_QUEUE_WAKEUP_ON_INSERT;
        _ebpf_epoch_send_message_and_wait(&update_next_message, predecessor_cpu);

        ebpf_epoch_cpu_message_t update_previous_message = {0};
        update_previous_message.message_type = EBPF_EPOCH_CPU_MESSAGE_TYPE_UPDATE_PREVIOUS_ACTIVE_CPU;
        update_previous_message.message.update_previous_active_cpu.previous_cpu = cpu_id;
        update_previous_message.wake_behavior = EBPF_WORK_QUEUE_WAKEUP_ON_INSERT;
        _ebpf_epoch_send_message_and_wait(&update_previous_message, successor_cpu);
        MemoryBarrier();
        cpu_entry->admitted = true;

        return;
    }

    case KeProcessorAddCompleteNotify:
        if (cpu_entry->work_queue != NULL && _ebpf_epoch_quiesced_cpu == cpu_id) {
            _ebpf_epoch_resume_passive_synchronization(cpu_id);
        }
        return;

    case KeProcessorAddFailureNotify: {
        if (_ebpf_epoch_startup_registration_in_progress) {
            cpu_entry->admitted = false;
            cpu_entry->next_active_cpu = cpu_id;
            cpu_entry->previous_active_cpu = cpu_id;
            return;
        }

        if (cpu_entry->work_queue == NULL) {
            return;
        }

        // Initialization can fail before the callback acquires the quiescent section, so only roll back the
        // participant links and resume synchronization when this add owns the section.
        if (_ebpf_epoch_quiesced_cpu == cpu_id) {
            if (cpu_entry->previous_active_cpu < _ebpf_epoch_cpu_count &&
                _ebpf_epoch_cpu_table[cpu_entry->previous_active_cpu].admitted) {
                ebpf_epoch_cpu_message_t update_next_message = {0};
                update_next_message.message_type = EBPF_EPOCH_CPU_MESSAGE_TYPE_UPDATE_NEXT_ACTIVE_CPU;
                update_next_message.message.update_next_active_cpu.next_cpu = cpu_entry->next_active_cpu;
                update_next_message.wake_behavior = EBPF_WORK_QUEUE_WAKEUP_ON_INSERT;
                _ebpf_epoch_send_message_and_wait(&update_next_message, cpu_entry->previous_active_cpu);
            }

            if (cpu_entry->next_active_cpu < _ebpf_epoch_cpu_count &&
                _ebpf_epoch_cpu_table[cpu_entry->next_active_cpu].admitted) {
                ebpf_epoch_cpu_message_t update_previous_message = {0};
                update_previous_message.message_type = EBPF_EPOCH_CPU_MESSAGE_TYPE_UPDATE_PREVIOUS_ACTIVE_CPU;
                update_previous_message.message.update_previous_active_cpu.previous_cpu =
                    cpu_entry->previous_active_cpu;
                update_previous_message.wake_behavior = EBPF_WORK_QUEUE_WAKEUP_ON_INSERT;
                _ebpf_epoch_send_message_and_wait(&update_previous_message, cpu_entry->next_active_cpu);
            }
        }

        _ebpf_epoch_destroy_cpu_entry(cpu_entry);
        if (_ebpf_epoch_quiesced_cpu == cpu_id) {
            _ebpf_epoch_resume_passive_synchronization(cpu_id);
        }
        return;
    }

    default:
        return;
    }
}

void
_ebpf_epoch_messenger_quiesce_timer_computation(
    _Inout_ ebpf_epoch_cpu_entry_t* cpu_entry, _Inout_ ebpf_epoch_cpu_message_t* message, uint32_t current_cpu)
{
    UNREFERENCED_PARAMETER(cpu_entry);

    EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, current_cpu == 0);
    EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, !_ebpf_epoch_cpu_table[0].timer_computation_quiesced);
    _ebpf_epoch_cpu_table[0].timer_computation_quiesced = true;

    if (_ebpf_epoch_cpu_table[0].epoch_computation_in_progress) {
        // The passive synchronization lock does not block the CPU 0 timer DPC, so wait for the active
        // computation through this message before allowing the hot-add transaction to patch the ring.
        EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, _ebpf_epoch_timer_quiesce_wait_message == NULL);
        _ebpf_epoch_timer_quiesce_wait_message = message;
        return;
    }

    KeSetEvent(&message->completion_event, 0, FALSE);
}

void
_ebpf_epoch_messenger_resume_timer_computation(
    _Inout_ ebpf_epoch_cpu_entry_t* cpu_entry, _Inout_ ebpf_epoch_cpu_message_t* message, uint32_t current_cpu)
{
    UNREFERENCED_PARAMETER(cpu_entry);

    EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, current_cpu == 0);
    EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, _ebpf_epoch_cpu_table[0].timer_computation_quiesced);
    EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, _ebpf_epoch_timer_quiesce_wait_message == NULL);
    _ebpf_epoch_cpu_table[0].timer_computation_quiesced = false;
    KeSetEvent(&message->completion_event, 0, FALSE);
}

void
_ebpf_epoch_messenger_update_next_active_cpu(
    _Inout_ ebpf_epoch_cpu_entry_t* cpu_entry, _Inout_ ebpf_epoch_cpu_message_t* message, uint32_t current_cpu)
{
    EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, current_cpu == ebpf_get_current_cpu());
    cpu_entry->next_active_cpu = message->message.update_next_active_cpu.next_cpu;
    KeSetEvent(&message->completion_event, 0, FALSE);
}

void
_ebpf_epoch_messenger_update_previous_active_cpu(
    _Inout_ ebpf_epoch_cpu_entry_t* cpu_entry, _Inout_ ebpf_epoch_cpu_message_t* message, uint32_t current_cpu)
{
    EBPF_EPOCH_FAIL_FAST(FAST_FAIL_INVALID_ARG, current_cpu == ebpf_get_current_cpu());
    cpu_entry->previous_active_cpu = message->message.update_previous_active_cpu.previous_cpu;
    KeSetEvent(&message->completion_event, 0, FALSE);
}

_Must_inspect_result_ ebpf_result_t
ebpf_timed_work_queue_initialize(_Inout_ ebpf_timed_work_queue_t* work_queue, uint32_t cpu_id)
{
        EBPF_LOG_NTSTATUS_API_FAILURE(EBPF_TRACELOG_KEYWORD_BASE, KeGetProcessorNumberFromIndex, status);
        return EBPF_INVALID_ARGUMENT;
    status = KeSetTargetProcessorDpcEx(&work_queue->dpc, &processor_number);
        EBPF_LOG_NTSTATUS_API_FAILURE(EBPF_TRACELOG_KEYWORD_BASE, KeSetTargetProcessorDpcEx, status);
        return EBPF_INVALID_ARGUMENT;
    work_queue->cpu_id = cpu_id;
    return EBPF_SUCCESS;

~_ebpf_cpu_affinity_scope()
    {
        if (_status == EBPF_SUCCESS) {
            ebpf_restore_current_thread_cpu_affinity(&_old_thread_affinity);
        }
    }

ebpf_result_t
    status() const
    {
        return _status;
    }

explicit _epoch_hot_add_synchronize_scope(uint32_t hot_add_cpu)
        : _hot_add_cpu(hot_add_cpu), _future(std::async(std::launch::async, []() {
              ebpf_cpu_affinity_scope_t cpu0_affinity(0);
              if (cpu0_affinity.status() != EBPF_SUCCESS) {
                  return cpu0_affinity.status();
              }
              ebpf_epoch_synchronize();
              return EBPF_SUCCESS;
          }))
    {
    }

std::future_status
    wait_for(const std::chrono::duration<rep, period>& timeout)
    {
        return _future.wait_for(timeout);
    }

NTSTATUS
    notify_complete()
    {
        NTSTATUS status = usersim_notify_processor_add_complete(_hot_add_cpu);
        _notification_completed = NT_SUCCESS(status);
        return status;
    }

NTSTATUS
    notify_failure()
    {
        NTSTATUS status = usersim_notify_processor_add_failure(_hot_add_cpu);
        _notification_completed = NT_SUCCESS(status);
        return status;
    }

ebpf_result_t
    get()
    {
        _joined = true;
        return _future.get();
    }

void
    _cleanup() noexcept
    {
        if (!_future.valid()) {
            return;
        }

        if (!_notification_completed) {
            _notification_completed = NT_SUCCESS(usersim_notify_processor_add_failure(_hot_add_cpu));
        }

        _future.wait();
        if (!_joined) {
            (void)_future.get();
        }
    }

_fuzz_core_lifetime()
    {
        ebpf_result_t result = ebpf_core_initiate();
        if (result != EBPF_SUCCESS) {
            throw std::runtime_error("ebpf_core_initiate failed");
        }
    }

static void
_ebpf_log_deprecated_program_type(
    _In_ const ebpf_program_type_t* program_type, _In_opt_z_ const char* program_name) noexcept
{
    if (IsEqualGUID(*program_type, EBPF_PROGRAM_TYPE_BIND)) {
        EBPF_LOG_MESSAGE_STRING(
            EBPF_TRACELOG_LEVEL_WARNING,
            EBPF_TRACELOG_KEYWORD_API,
            "Loading deprecated program type BPF_PROG_TYPE_BIND. "
            "Migrate to BPF_PROG_TYPE_CGROUP_SOCK_ADDR with BPF_CGROUP_INET4_BIND / BPF_CGROUP_INET6_BIND.",
            program_name != nullptr ? program_name : "");
    }
}

static _Must_inspect_result_ ebpf_result_t
_ebpf_ring_buffer_request_section_handle(
    ebpf_handle_t map_handle, uint64_t index, uint32_t section, _Out_ HANDLE* handle, _Out_ size_t* view_size)
    NO_EXCEPT_TRY
{
    ebpf_operation_ring_buffer_map_map_buffer_request_t request{
        sizeof(request), ebpf_operation_id_t::EBPF_OPERATION_RING_BUFFER_MAP_MAP_BUFFER, map_handle, index, section};
    ebpf_operation_ring_buffer_map_map_buffer_reply_t reply{};
    ebpf_result_t result = win32_error_code_to_ebpf_result(invoke_ioctl(request, reply));
    if (result != EBPF_SUCCESS) {
        return result;
    }

    *handle = reinterpret_cast<HANDLE>(static_cast<uintptr_t>(reply.section_handle));
    *view_size = reply.view_size;
    return EBPF_SUCCESS;
}

CATCH_NO_MEMORY_EBPF_RESULT

static _Must_inspect_result_ ebpf_result_t
_ebpf_ring_buffer_map_double_view(
    HANDLE section_handle, size_t view_size, _Outptr_ void** first_view, _Outptr_ void** second_view) NO_EXCEPT_TRY
{
    uint8_t* placeholder1 = nullptr;
    uint8_t* placeholder2 = nullptr;
    void* view1 = nullptr;
    void* view2 = nullptr;
    ebpf_result_t result = EBPF_SUCCESS;

    placeholder1 = reinterpret_cast<uint8_t*>(VirtualAlloc2(
        nullptr, nullptr, view_size * 2, MEM_RESERVE | MEM_RESERVE_PLACEHOLDER, PAGE_NOACCESS, nullptr, 0));
    if (placeholder1 == nullptr) {
        EBPF_LOG_WIN32_API_FAILURE(EBPF_TRACELOG_KEYWORD_API, VirtualAlloc2);
        return win32_error_code_to_ebpf_result(GetLastError());
    }

#pragma warning(push)
#pragma warning(disable : 6333)
#pragma warning(disable : 28160)
    if (!VirtualFree(placeholder1, view_size, MEM_RELEASE | MEM_PRESERVE_PLACEHOLDER)) {
        EBPF_LOG_WIN32_API_FAILURE(EBPF_TRACELOG_KEYWORD_API, VirtualFree);
        result = win32_error_code_to_ebpf_result(GetLastError());
        goto Exit;
    }
#pragma warning(pop)
    placeholder2 = placeholder1 + view_size;

    view1 = MapViewOfFile3(
        section_handle, nullptr, placeholder1, 0, view_size, MEM_REPLACE_PLACEHOLDER, PAGE_READONLY, nullptr, 0);
    if (view1 == nullptr) {
        EBPF_LOG_WIN32_API_FAILURE(EBPF_TRACELOG_KEYWORD_API, MapViewOfFile3);
        result = win32_error_code_to_ebpf_result(GetLastError());
        goto Exit;
    }

    placeholder1 = nullptr;
    view2 = MapViewOfFile3(
        section_handle, nullptr, placeholder2, 0, view_size, MEM_REPLACE_PLACEHOLDER, PAGE_READONLY, nullptr, 0);
    if (view2 == nullptr) {
        EBPF_LOG_WIN32_API_FAILURE(EBPF_TRACELOG_KEYWORD_API, MapViewOfFile3);
        result = win32_error_code_to_ebpf_result(GetLastError());
        goto Exit;
    }

    *first_view = view1;
    *second_view = view2;
    view1 = nullptr;
    view2 = nullptr;
    placeholder2 = nullptr;
    return EBPF_SUCCESS;

Exit:
    if (placeholder1 != nullptr) {
        VirtualFree(placeholder1, 0, MEM_RELEASE);
    }
    if (placeholder2 != nullptr) {
        VirtualFree(placeholder2, 0, MEM_RELEASE);
    }
    if (view1 != nullptr) {
        UnmapViewOfFileEx(view1, 0);
    }
    if (view2 != nullptr) {
        UnmapViewOfFileEx(view2, 0);
    }
    return result;
}

_Must_inspect_result_ ebpf_result_t
ebpf_map_get_user_mapping_handle(
    _In_ const ebpf_map_t* map,
    uint64_t index,
    ebpf_ring_buffer_user_section_t section,
    _Out_ ebpf_handle_t* handle,
    _Out_ size_t* view_size)
{
    const ebpf_ring_buffer_t* ring_buffer = NULL;

    if (map == NULL || handle == NULL || view_size == NULL) {
        return EBPF_INVALID_ARGUMENT;
    }

    switch (map->ebpf_map_definition.type) {
    case BPF_MAP_TYPE_RINGBUF:
        if (index != 0) {
            return EBPF_INVALID_ARGUMENT;
        }
        ring_buffer = (const ebpf_ring_buffer_t*)map->data;
        break;
    case BPF_MAP_TYPE_PERF_EVENT_ARRAY: {
        const ebpf_core_perf_event_array_map_t* perf_event_array_map =
            EBPF_FROM_FIELD(const ebpf_core_perf_event_array_map_t, core_map, map);
        if (index >= perf_event_array_map->ring_count) {
            return EBPF_INVALID_ARGUMENT;
        }
        ring_buffer = perf_event_array_map->rings[index].ring;
        break;
    }
    default:
        return EBPF_OPERATION_NOT_SUPPORTED;
    }

    return ebpf_ring_buffer_get_user_mapping_handle(ring_buffer, section, handle, view_size);
}

_Must_inspect_result_ ebpf_result_t
ebpf_ring_buffer_get_user_mapping_handle(
    _In_ const ebpf_ring_buffer_t* ring_buffer,
    ebpf_ring_buffer_user_section_t section,
    _Out_ ebpf_handle_t* handle,
    _Out_ size_t* view_size)
{
    return ebpf_ring_open_user_section(ring_buffer->ring_descriptor, section, handle, view_size);
}

static void
_ebpf_ring_cleanup_section(_Inout_ ebpf_ring_section_t* section)
    if (section->locked_kernel_view_mdl != NULL) {
        MmUnlockPages(section->locked_kernel_view_mdl);
        IoFreeMdl(section->locked_kernel_view_mdl);
        section->locked_kernel_view_mdl = NULL;
    }

void*
ebpf_ring_descriptor_get_producer_page_address(_In_ const ebpf_ring_descriptor_t* ring)
{
    return ring->composite_view + (2 * PAGE_SIZE);
}

uint8_t*
ebpf_ring_descriptor_get_data_address(_In_ const ebpf_ring_descriptor_t* ring)
{
    return ring->composite_view + (EBPF_RING_BUFFER_HEADER_PAGES * PAGE_SIZE);
}

static void
_ebpf_ring_cleanup_section(_Inout_ ebpf_ring_section_t* section)
{
    if (section->view != nullptr) {
        UnmapViewOfFile(section->view);
        section->view = nullptr;
    }

    if (section->section_handle != nullptr) {
        CloseHandle(section->section_handle);
        section->section_handle = nullptr;
    }

    section->view_size = 0;
}

static _Must_inspect_result_ ebpf_result_t
_ebpf_ring_create_section(size_t size, _Inout_ ebpf_ring_section_t* section)
{
    uint64_t section_size = size;

    section->section_handle = CreateFileMapping(
        INVALID_HANDLE_VALUE,
        nullptr,
        PAGE_READWRITE,
        static_cast<unsigned long>(section_size >> 32),
        static_cast<unsigned long>(section_size & MAXUINT32),
        nullptr);
    if (section->section_handle == nullptr) {
        EBPF_LOG_WIN32_API_FAILURE(EBPF_TRACELOG_KEYWORD_BASE, CreateFileMapping);
        return win32_error_code_to_ebpf_result(GetLastError());
    }

    section->view = MapViewOfFile(section->section_handle, FILE_MAP_READ | FILE_MAP_WRITE, 0, 0, size);
    if (section->view == nullptr) {
        EBPF_LOG_WIN32_API_FAILURE(EBPF_TRACELOG_KEYWORD_BASE, MapViewOfFile);
        _ebpf_ring_cleanup_section(section);
        return win32_error_code_to_ebpf_result(GetLastError());
    }

    section->view_size = size;
    return EBPF_SUCCESS;
}

static _Must_inspect_result_ ebpf_result_t
_ebpf_ring_create_composite_view(_Inout_ ebpf_ring_descriptor_t* descriptor)
{
    static const size_t _ring_header_size = EBPF_RING_BUFFER_HEADER_PAGES * PAGE_SIZE;
    uint8_t* current_address = nullptr;
    uint8_t* composite_base = nullptr;
    HANDLE section_handles[] = {
        descriptor->kernel.section_handle,
        descriptor->consumer.section_handle,
        descriptor->producer.section_handle,
        descriptor->data.section_handle,
        // Map the data section twice contiguously so wrapped records can be read linearly.
        descriptor->data.section_handle};
    size_t view_lengths[] = {PAGE_SIZE, PAGE_SIZE, PAGE_SIZE, descriptor->ring_capacity, descriptor->ring_capacity};
    void** target_views[] = {
        &descriptor->kernel.view,
        &descriptor->consumer.view,
        &descriptor->producer.view,
        &descriptor->data.view,
        &descriptor->data_secondary_view};
    ebpf_result_t return_value = EBPF_SUCCESS;

    descriptor->composite_view_size = _ring_header_size + (descriptor->ring_capacity * 2);
    composite_base = reinterpret_cast<uint8_t*>(VirtualAlloc2(
        nullptr,
        nullptr,
        descriptor->composite_view_size,
        MEM_RESERVE | MEM_RESERVE_PLACEHOLDER,
        PAGE_NOACCESS,
        nullptr,
        0));
    if (composite_base == nullptr) {
        EBPF_LOG_WIN32_API_FAILURE(EBPF_TRACELOG_KEYWORD_BASE, VirtualAlloc2);
        return win32_error_code_to_ebpf_result(GetLastError());
    }
    descriptor->composite_base = composite_base;
    current_address = composite_base;

    for (size_t index = 0; index < ARRAYSIZE(section_handles); index++) {
#pragma warning(push)
#pragma warning(disable : 6333)
#pragma warning(disable : 28160)
        if ((index + 1) < ARRAYSIZE(section_handles) &&
            !VirtualFree(current_address, view_lengths[index], MEM_RELEASE | MEM_PRESERVE_PLACEHOLDER)) {
            EBPF_LOG_WIN32_API_FAILURE(EBPF_TRACELOG_KEYWORD_BASE, VirtualFree);
            return_value = win32_error_code_to_ebpf_result(GetLastError());
            goto Exit;
        }
#pragma warning(pop)

        *target_views[index] = MapViewOfFile3(
            section_handles[index],
            nullptr,
            current_address,
            0,
            view_lengths[index],
            MEM_REPLACE_PLACEHOLDER,
            PAGE_READWRITE,
            nullptr,
            0);
        if (*target_views[index] == nullptr) {
            EBPF_LOG_WIN32_API_FAILURE(EBPF_TRACELOG_KEYWORD_BASE, MapViewOfFile3);
            return_value = win32_error_code_to_ebpf_result(GetLastError());
            goto Exit;
        }

        current_address += view_lengths[index];
    }

Exit:
    if (return_value != EBPF_SUCCESS) {
        if (descriptor->data_secondary_view != nullptr) {
            UnmapViewOfFileEx(descriptor->data_secondary_view, MEM_PRESERVE_PLACEHOLDER);
            descriptor->data_secondary_view = nullptr;
        }
        if (descriptor->data.view != nullptr) {
            UnmapViewOfFileEx(descriptor->data.view, MEM_PRESERVE_PLACEHOLDER);
            descriptor->data.view = nullptr;
        }
        if (descriptor->producer.view != nullptr) {
            UnmapViewOfFileEx(descriptor->producer.view, MEM_PRESERVE_PLACEHOLDER);
            descriptor->producer.view = nullptr;
        }
        if (descriptor->consumer.view != nullptr) {
            UnmapViewOfFileEx(descriptor->consumer.view, MEM_PRESERVE_PLACEHOLDER);
            descriptor->consumer.view = nullptr;
        }
        if (descriptor->kernel.view != nullptr) {
            UnmapViewOfFileEx(descriptor->kernel.view, MEM_PRESERVE_PLACEHOLDER);
            descriptor->kernel.view = nullptr;
        }
        if (descriptor->composite_base != nullptr) {
            const size_t composite_view_lengths[] = {
                PAGE_SIZE, PAGE_SIZE, PAGE_SIZE, descriptor->ring_capacity, descriptor->ring_capacity};
            _ebpf_ring_release_composite_placeholders(descriptor->composite_base, composite_view_lengths);
            descriptor->composite_base = nullptr;
        }
        descriptor->composite_view_size = 0;
    }

    EBPF_RETURN_RESULT(return_value);
}

static void
_ebpf_ring_release_composite_placeholders(_In_ uint8_t* composite_base, _In_reads_(5) const size_t* view_lengths)
{
    size_t offset = 0;
    for (size_t index = 0; index < 5; index++) {
        if (!VirtualFree(composite_base + offset, 0, MEM_RELEASE)) {
            EBPF_LOG_WIN32_API_FAILURE(EBPF_TRACELOG_KEYWORD_BASE, VirtualFree);
        }
        offset += view_lengths[index];
    }
}

void*
ebpf_ring_descriptor_get_producer_page_address(_In_ const ebpf_ring_descriptor_t* ring_descriptor)
{
    return ring_descriptor->producer.view;
}

uint8_t*
ebpf_ring_descriptor_get_data_address(_In_ const ebpf_ring_descriptor_t* ring_descriptor)
{
    return (uint8_t*)ring_descriptor->data.view;
}

static int
_ring_buffer_mmap_process_exit_child(_In_z_ const char* pin_path)
{
    fd_t map_fd = bpf_obj_get(pin_path);
    if (map_fd < 0) {
        return 1;
    }

    void* consumer = nullptr;
    const void* producer = nullptr;
    const uint8_t* data = nullptr;
    size_t data_size = 0;
    if (ebpf_ring_buffer_map_map_buffer(map_fd, &consumer, &producer, &data, &data_size) != EBPF_SUCCESS ||
        consumer == nullptr || producer == nullptr || data == nullptr || data_size == 0) {
        return 1;
    }

    // Intentionally leave the mapped views and map descriptor for process rundown to reclaim.
    return 0;
}

static NTSTATUS
    _net_ebpf_ext_try_delete_wfp_filter(_In_ HANDLE wfp_engine_handle, uint64_t filter_id, uint32_t max_attempts)
{
    NTSTATUS status = STATUS_UNSUCCESSFUL;
    NTSTATUS most_recent_failed_status = STATUS_SUCCESS;

    EBPF_EXT_LOG_ENTRY();

    for (uint32_t attempt = 1; attempt <= max_attempts; attempt++) {
        status = FwpmFilterDeleteById(wfp_engine_handle, filter_id);
        if (NT_SUCCESS(status) || WFP_ERROR(status, FILTER_NOT_FOUND)) {
            // FWP_E_FILTER_NOT_FOUND: the filter is already gone (the original delete may have completed but its
            // RPC reply was lost). Treat as success so the reference is not released twice.
            status = STATUS_SUCCESS;
            break;
        }

        // Remember the last failing status for the one-per-filter recovered-delete log below.
        most_recent_failed_status = status;
    }

    if (NT_SUCCESS(status) && most_recent_failed_status != STATUS_SUCCESS) {
        // Delete succeeded after an earlier attempt failed (a transient BFE outage the inline retry recovered).
        // Log once per filter with the last failed status.
        EBPF_EXT_LOG_MESSAGE_UINT64_UINT64(
            EBPF_EXT_TRACELOG_LEVEL_INFO,
            EBPF_EXT_TRACELOG_KEYWORD_EXTENSION,
            "FwpmFilterDeleteById recovered after one or more transient failures.",
            (uint64_t)most_recent_failed_status,
            filter_id);
    }

    EBPF_EXT_RETURN_NTSTATUS(status);
}

_IRQL_requires_(PASSIVE_LEVEL) static void _net_ebpf_ext_cleanup_zombie_filters(
    _In_ net_ebpf_extension_hook_provider_t* provider_context)
{
    EBPF_EXT_LOG_ENTRY();

    ACQUIRE_PUSH_LOCK_EXCLUSIVE(&provider_context->lock);

    while (!IsListEmpty(&provider_context->zombie_filter_context_list)) {
        PLIST_ENTRY entry = RemoveHeadList(&provider_context->zombie_filter_context_list);
        net_ebpf_extension_wfp_filter_context_t* filter_context =
            CONTAINING_RECORD(entry, net_ebpf_extension_wfp_filter_context_t, zombie_link);
        InitializeListHead(&filter_context->zombie_link);

        // Release the provider lock while processing: FwpmFilterDeleteById requires PASSIVE_LEVEL.
        RELEASE_PUSH_LOCK_EXCLUSIVE(&provider_context->lock);

#pragma warning(push)
#pragma warning(disable : 6001) // Using uninitialized memory 'filter_id'. filter_ids is initialized by add_wfp_filters.
        for (uint32_t index = 0; index < filter_context->filter_ids_count; index++) {
            net_ebpf_ext_wfp_filter_id_t* filter_id = &filter_context->filter_ids[index];
            NTSTATUS delete_status;

            // No lock is needed: the clients have detached and no callout is registered, so nothing else can
            // observe or modify this state.
            if (filter_id->state == NET_EBPF_EXT_WFP_FILTER_DELETED) {
                continue;
            }

            // Best-effort removal of the still-live WFP filter so it cannot outlive the filter context. The delete
            // is retried because BFE may have recovered since the attempt at detach failed.
            delete_status = _net_ebpf_ext_try_delete_wfp_filter(
                filter_context->wfp_engine_handle, filter_id->id, NET_EBPF_EXT_DELETE_RETRY_MAX_ATTEMPTS);
            filter_id->error_code = delete_status;
            if (NT_SUCCESS(delete_status)) {
                filter_id->state = NET_EBPF_EXT_WFP_FILTER_DELETED;
            } else {
                EBPF_EXT_LOG_MESSAGE_UINT64_UINT64(
                    EBPF_EXT_TRACELOG_LEVEL_ERROR,
                    EBPF_EXT_TRACELOG_KEYWORD_EXTENSION,
                    "Zombie WFP filter could not be deleted at unload; it is left installed.",
                    delete_status,
                    filter_id->id);
            }
        }
#pragma warning(pop)

        // Free the context outright. Its reference count is meaningless here: the references it still holds belong
        // to filters WFP never deleted, and nothing can release them. This also leaves the provider rundown.
        CLEAN_UP_FILTER_CONTEXT(filter_context);

        ACQUIRE_PUSH_LOCK_EXCLUSIVE(&provider_context->lock);
    }

    RELEASE_PUSH_LOCK_EXCLUSIVE(&provider_context->lock);

    EBPF_EXT_LOG_EXIT();
}

NPI client (a.k.a. eBPF link object) attaches.
    // No matching filter context found. Need to create a new filter context. It acquires its own rundown reference
    // on the provider context, which it releases when it is freed.
    // Set the filter context as the client's provider data. This is done only now that the context is guaranteed to
    // outlive the call: every failure path inside create_filter_context frees it.
    net_ebpf_extension_hook_client_set_provider_data(hook_client, new_filter_context);

            // new_filter_context is only non-NULL while the lock is held.
            if (new_filter_context != NULL) {
                _net_ebpf_ext_dispose_filter_context(local_provider_context, new_filter_context);
            }

static void
_preprocess_btf_resolved_functions(std::istream& stream, _In_z_ const char* stream_name)
{
    stream.clear();
    stream.seekg(0, std::ios::beg);
    if (!stream) {
        throw std::runtime_error(std::string("Failed to seek stream for BTF preprocessing: ") + stream_name);
    }

    ELFIO::elfio reader;
    if (!reader.load(stream)) {
        throw std::runtime_error(std::string("Failed to load ELF for BTF preprocessing: ") + stream_name);
    }
    ELFIO::section* btf_section = reader.sections[".BTF"];
    if (btf_section != nullptr && btf_section->get_data() != nullptr) {
        std::optional<libbtf::btf_type_data> btf_data = vector_of<byte>(*btf_section);
        cache_btf_resolved_functions(btf_data.value());
    }

    stream.clear();
    stream.seekg(0, std::ios::beg);
    if (!stream) {
        throw std::runtime_error(std::string("Failed to seek stream before verification: ") + stream_name);
    }
}

static void
_ebpf_pe_copy_program_entry(
    _Out_ program_entry_t* destination, _In_reads_bytes_(source_size) const void* source, size_t source_size) noexcept
{
    memset(destination, 0, sizeof(*destination));
    size_t program_copy_size = (source_size < sizeof(*destination)) ? source_size : sizeof(*destination);
    memcpy(destination, source, program_copy_size);
}

_Must_inspect_result_ ebpf_result_t
ebpf_get_btf_resolved_function_info_from_verifier(
    int32_t btf_id, _Outptr_ const ebpf_btf_resolved_function_info_t** function_info) NO_EXCEPT_TRY
{
    ebpf_result_t result = EBPF_SUCCESS;
    EBPF_LOG_ENTRY();

    result = get_btf_resolved_function_info_from_tls(btf_id, function_info);

    EBPF_RETURN_RESULT(result);
}

static void
_ebpf_store_free_btf_resolved_function(_Frees_ptr_opt_ ebpf_btf_resolved_function_info_t* function_info)
{
    if (function_info == nullptr) {
        return;
    }

    ebpf_free((void*)function_info->prototype.name);
    ebpf_free(function_info);
}

void
ebpf_store_free_btf_resolved_function(_Frees_ptr_opt_ ebpf_btf_resolved_function_info_t* function_info)
{
    _ebpf_store_free_btf_resolved_function(function_info);
}

_Must_inspect_result_ ebpf_result_t
ebpf_store_load_btf_resolved_function(
    _In_ const GUID* module_guid,
    _In_z_ const char* function_name,
    _Outptr_ ebpf_btf_resolved_function_info_t** function_info)
{
    ebpf_result_t result = EBPF_SUCCESS;
    ebpf_store_key_t store_key = nullptr;
    HKEY btf_resolved_functions_key = nullptr;
    HKEY provider_key = nullptr;
    HKEY function_collection_key = nullptr;
    HKEY function_key = nullptr;
    wchar_t guid_string[GUID_STRING_LENGTH + 1] = {};
    wchar_t* function_name_wide = nullptr;
    ebpf_btf_resolved_function_info_t* local_function_info = nullptr;
    ebpf_extension_header_t provider_header = {};

    EBPF_LOG_ENTRY();

    *function_info = nullptr;
    if (module_guid == nullptr || function_name == nullptr) {
        result = EBPF_INVALID_ARGUMENT;
        goto Exit;
    }

    result = _open_ebpf_store_key(&store_key);
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    result = ebpf_open_registry_key(
        store_key, EBPF_BTF_RESOLVED_FUNCTIONS_REGISTRY_KEY, KEY_READ, (ebpf_store_key_t*)&btf_resolved_functions_key);
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    result = ebpf_convert_guid_to_string(module_guid, guid_string, EBPF_COUNT_OF(guid_string));
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    result =
        ebpf_open_registry_key(btf_resolved_functions_key, guid_string, KEY_READ, (ebpf_store_key_t*)&provider_key);
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    result = _load_extension_header(provider_key, &provider_header);
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    result = ebpf_open_registry_key(
        provider_key, EBPF_BTF_FUNCTIONS_REGISTRY_KEY, KEY_READ, (ebpf_store_key_t*)&function_collection_key);
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    function_name_wide = ebpf_get_wstring_from_string(function_name);
    if (function_name_wide == nullptr) {
        result = EBPF_NO_MEMORY;
        goto Exit;
    }

    result =
        ebpf_open_registry_key(function_collection_key, function_name_wide, KEY_READ, (ebpf_store_key_t*)&function_key);
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    local_function_info = reinterpret_cast<ebpf_btf_resolved_function_info_t*>(
        ebpf_allocate_with_tag(sizeof(ebpf_btf_resolved_function_info_t), EBPF_POOL_TAG_DEFAULT));
    if (local_function_info == nullptr) {
        result = EBPF_NO_MEMORY;
        goto Exit;
    }
    memset(local_function_info, 0, sizeof(*local_function_info));
    local_function_info->module_guid = *module_guid;
    local_function_info->prototype.header = EBPF_BTF_RESOLVED_FUNCTION_PROTOTYPE_HEADER;

    try {
        local_function_info->prototype.name = cxplat_duplicate_string(function_name);
        if (local_function_info->prototype.name == nullptr) {
            result = EBPF_NO_MEMORY;
            goto Exit;
        }
    } catch (const std::exception&) {
        result = EBPF_FAILED;
        goto Exit;
    }

    result = ebpf_read_registry_value_dword(
        function_key,
        EBPF_BTF_FUNCTION_DATA_RETURN_TYPE,
        reinterpret_cast<uint32_t*>(&local_function_info->prototype.return_type));
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    result = ebpf_read_registry_value_binary(
        function_key,
        EBPF_BTF_FUNCTION_DATA_ARGUMENTS,
        reinterpret_cast<uint8_t*>(local_function_info->prototype.arguments),
        sizeof(local_function_info->prototype.arguments));
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    result = ebpf_read_registry_value_dword(
        function_key, EBPF_BTF_FUNCTION_DATA_FLAGS, &local_function_info->prototype.flags);
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    *function_info = local_function_info;
    local_function_info = nullptr;

Exit:
    ebpf_free_wstring(function_name_wide);
    _ebpf_store_free_btf_resolved_function(local_function_info);
    ebpf_close_registry_key(function_key);
    ebpf_close_registry_key(function_collection_key);
    ebpf_close_registry_key(provider_key);
    ebpf_close_registry_key(btf_resolved_functions_key);
    ebpf_close_registry_key(store_key);
    EBPF_RETURN_RESULT(result);
}

void
    operator()(_In_ _Post_invalid_ ebpf_btf_resolved_function_info_t* function_info)
    {
        ebpf_store_free_btf_resolved_function(function_info);
    }

static void
_clear_btf_resolved_function_state()
{
    _btf_resolved_function_name_to_id.clear();
    _btf_resolved_function_identities.clear();
    _btf_resolved_function_cache.clear();
    _next_btf_resolved_function_id = 1;
}

static void
_set_unsupported(_Out_opt_ std::string* why_not, _In_ const std::string& reason)
{
    if (why_not != nullptr) {
        *why_not = reason;
    }
}

_Ret_maybenull_ static ebpf_btf_resolved_function_info_t*
_get_btf_resolved_function_info(int32_t btf_id)
{
    auto cache_entry = _btf_resolved_function_cache.find(btf_id);
    if (cache_entry != _btf_resolved_function_cache.end()) {
        return cache_entry->second.get();
    }

    auto identity = _btf_resolved_function_identities.find(btf_id);
    if (identity == _btf_resolved_function_identities.end()) {
        return nullptr;
    }

    ebpf_btf_resolved_function_info_t* function_info = nullptr;
    if (ebpf_store_load_btf_resolved_function(
            &identity->second.module_guid, identity->second.function_name.c_str(), &function_info) != EBPF_SUCCESS) {
        return nullptr;
    }

    _btf_resolved_function_cache[btf_id] = ebpf_btf_resolved_function_info_ptr_t(function_info);
    return _btf_resolved_function_cache[btf_id].get();
}

static GUID
_parse_module_guid_or_throw(_In_ const std::string& tag_string)
{
    static constexpr std::string_view module_id_prefix{"module_id:"};
    GUID module_guid = GUID_NULL;
    wchar_t* guid_string = nullptr;

    if (tag_string.compare(0, module_id_prefix.size(), module_id_prefix) != 0) {
        throw std::runtime_error("Unsupported BTF decl_tag format: " + tag_string);
    }

    guid_string = ebpf_get_wstring_from_string(tag_string.substr(module_id_prefix.size()).c_str());
    if (guid_string == nullptr) {
        throw std::runtime_error("Out of memory parsing BTF module GUID");
    }

    ebpf_result_t result = ebpf_convert_string_to_guid(guid_string, &module_guid);
    ebpf_free_wstring(guid_string);
    if (result != EBPF_SUCCESS) {
        throw std::runtime_error("Invalid BTF module GUID decl_tag: " + tag_string);
    }

    return module_guid;
}

static bool
_is_module_guid_decl_tag(_In_ const std::string& tag_string)
{
    static constexpr std::string_view module_id_prefix{"module_id:"};
    return tag_string.compare(0, module_id_prefix.size(), module_id_prefix) == 0;
}

std::optional<prevail::KsymBtfId>
resolve_ksym_btf_id_windows(_In_ const std::string& name)
{
    auto identity = _btf_resolved_function_name_to_id.find(name);
    if (identity == _btf_resolved_function_name_to_id.end()) {
        return std::nullopt;
    }

    return prevail::KsymBtfId{.btf_id = identity->second, .module = 0};
}

std::optional<prevail::ResolvedCall>
resolve_kfunc_call_windows(
    int32_t btf_id, int16_t module, _In_ const prevail::EbpfProgramType& program_type, _Inout_opt_ std::string* why_not)
{
    UNREFERENCED_PARAMETER(program_type);
    UNREFERENCED_PARAMETER(module);

    auto function_info = _get_btf_resolved_function_info(btf_id);
    if (function_info == nullptr) {
        _set_unsupported(why_not, "kfunc prototype lookup failed for BTF id " + std::to_string(btf_id));
        return std::nullopt;
    }

    const auto& prototype = function_info->prototype;
    const std::string function_name = prototype.name != nullptr ? prototype.name : std::to_string(btf_id);

    if (prototype.flags != 0) {
        _set_unsupported(why_not, "kfunc has unsupported flags: " + function_name);
        return std::nullopt;
    }

    if (prototype.return_type == EBPF_RETURN_TYPE_UNSUPPORTED) {
        _set_unsupported(why_not, "kfunc prototype is unavailable on this platform: " + function_name);
        return std::nullopt;
    }

    const auto return_info = prevail::classify_call_return_type(prototype.return_type);
    if (!return_info.has_value()) {
        _set_unsupported(why_not, "kfunc return type is unsupported on this platform: " + function_name);
        return std::nullopt;
    }

    prevail::ResolvedCall result;
    result.call = prevail::Call{.func = btf_id, .kind = prevail::CallKind::kfunc, .module = module};
    result.name = function_name;
    result.contract.return_ptr_type = return_info->pointer_type;
    result.contract.return_nullable = return_info->pointer_nullable;
    result.contract.is_map_lookup = prototype.return_type == EBPF_RETURN_TYPE_PTR_TO_MAP_VALUE_OR_NULL;

    const std::array<ebpf_argument_type_t, 7> arguments = {
        {EBPF_ARGUMENT_TYPE_DONTCARE,
         prototype.arguments[0],
         prototype.arguments[1],
         prototype.arguments[2],
         prototype.arguments[3],
         prototype.arguments[4],
         EBPF_ARGUMENT_TYPE_DONTCARE}};

    for (size_t index = 1; index < arguments.size() - 1;) {
        switch (prevail::process_arg(result.contract, arguments, index)) {
        case prevail::ArgOutcome::Single:
            index += 1;
            break;
        case prevail::ArgOutcome::Pair:
            index += 2;
            break;
        case prevail::ArgOutcome::Stop:
            return result;
        case prevail::ArgOutcome::Unavailable:
            _set_unsupported(why_not, "kfunc argument type is unsupported on this platform: " + function_name);
            return std::nullopt;
        case prevail::ArgOutcome::MismatchedSize:
            _set_unsupported(
                why_not,
                "kfunc pointer argument not followed by EBPF_ARGUMENT_TYPE_CONST_SIZE or "
                "EBPF_ARGUMENT_TYPE_CONST_SIZE_OR_ZERO: " +
                    function_name);
            return std::nullopt;
        }
    }

    return result;
}

ebpf_result_t get_btf_resolved_function_info_from_tls(
    int32_t btf_id, _Outptr_ const ebpf_btf_resolved_function_info_t** function_info)
{
    auto* info = _get_btf_resolved_function_info(btf_id);
    if (info == nullptr) {
        return EBPF_OBJECT_NOT_FOUND;
    }

    *function_info = info;
    return EBPF_SUCCESS;
}

_Must_inspect_result_ ebpf_result_t
ebpf_core_resolve_btf_resolved_functions(
    ebpf_handle_t program_handle,
    size_t count_of_functions,
    _Out_writes_(count_of_functions) uint64_t* function_addresses)
{
    EBPF_LOG_ENTRY();
    ebpf_program_t* program = NULL;
    ebpf_result_t return_value =
        EBPF_OBJECT_REFERENCE_BY_HANDLE(program_handle, EBPF_OBJECT_PROGRAM, (ebpf_core_object_t**)&program);
    if (return_value != EBPF_SUCCESS) {
        goto Done;
    }

    return_value = ebpf_program_get_btf_resolved_function_addresses(program, count_of_functions, function_addresses);

Done:
    EBPF_OBJECT_RELEASE_REFERENCE((ebpf_core_object_t*)program);
    EBPF_RETURN_RESULT(return_value);
}

static void
_ebpf_copy_program_entry(
    _Out_ program_entry_t* destination, _In_reads_bytes_(source_size) const void* source, size_t source_size)
{
    memset(destination, 0, sizeof(*destination));
    memcpy(destination, source, min(source_size, sizeof(*destination)));
    destination->header = (ebpf_native_module_header_t)EBPF_NATIVE_PROGRAM_ENTRY_HEADER;
}

static bool
_ebpf_native_is_unused_btf_resolved_function_entry(_In_ const btf_resolved_function_entry_t* native_btf_entry)
{
    return (
        (native_btf_entry != NULL) && (native_btf_entry->name != NULL) && (native_btf_entry->name[0] == '\0') &&
        IsEqualGUID(&native_btf_entry->module_guid, &GUID_NULL));
}

static bool
_ebpf_validate_native_btf_resolved_function_entry(_In_ const btf_resolved_function_entry_t* native_btf_entry)
{
    bool valid_header = false;

    if (native_btf_entry == NULL) {
        return false;
    }

    valid_header =
        ((native_btf_entry->header.version == EBPF_NATIVE_BTF_RESOLVED_FUNCTION_ENTRY_CURRENT_VERSION) &&
         (native_btf_entry->header.size == EBPF_NATIVE_BTF_RESOLVED_FUNCTION_ENTRY_CURRENT_VERSION_SIZE) &&
         (native_btf_entry->header.total_size == EBPF_NATIVE_BTF_RESOLVED_FUNCTION_ENTRY_CURRENT_VERSION_TOTAL_SIZE));

    return (
        valid_header &&
        ((_ebpf_native_is_unused_btf_resolved_function_entry(native_btf_entry)) ||
         ((native_btf_entry->name != NULL) && !IsEqualGUID(&native_btf_entry->module_guid, &GUID_NULL))));
}

static bool
_ebpf_validate_native_btf_resolved_function_entry_array(
    _In_reads_(count) const btf_resolved_function_entry_t* native_btf_entry_array, uint16_t count)
{
    if (count > 0) {
        if (native_btf_entry_array == NULL) {
            return false;
        }

        size_t entry_size = native_btf_entry_array[0].header.total_size;
        for (uint16_t i = 0; i < count; i++) {
            const btf_resolved_function_entry_t* native_btf_entry =
                (const btf_resolved_function_entry_t*)ARRAY_ELEMENT_INDEX(native_btf_entry_array, i, entry_size);
            if (!_ebpf_validate_native_btf_resolved_function_entry(native_btf_entry)) {
                return false;
            }
        }
    } else if (native_btf_entry_array != NULL) {
        return false;
    }

    return true;
}

static void
_ebpf_copy_btf_resolved_function_entry(
    _Out_ btf_resolved_function_entry_t* destination, _In_ const btf_resolved_function_entry_t* source)
{
    destination->header = (ebpf_native_module_header_t)EBPF_NATIVE_BTF_RESOLVED_FUNCTION_ENTRY_HEADER;
    destination->name = source->name;
    destination->module_guid = source->module_guid;
}

static ebpf_result_t
_ebpf_native_resolve_btf_resolved_functions_for_program(_In_ const ebpf_native_program_t* program)
{
    EBPF_LOG_ENTRY();
    ebpf_result_t result;
    uint64_t* addresses = NULL;

    if (program->program_entry.btf_resolved_function_count == 0) {
        return EBPF_SUCCESS;
    }

    if (program->runtime_context.btf_resolved_function_data == NULL) {
        return EBPF_INVALID_ARGUMENT;
    }

    size_t addresses_length = 0;
    result = ebpf_safe_size_t_multiply(
        program->program_entry.btf_resolved_function_count, sizeof(*addresses), &addresses_length);
    if (result != EBPF_SUCCESS) {
        return result;
    }

    addresses = ebpf_allocate_with_tag(addresses_length, EBPF_POOL_TAG_NATIVE);
    if (addresses == NULL) {
        return EBPF_NO_MEMORY;
    }

    result = ebpf_core_resolve_btf_resolved_functions(
        program->handle, program->program_entry.btf_resolved_function_count, addresses);
    if (result != EBPF_SUCCESS) {
        goto Done;
    }

    result = _ebpf_native_btf_resolved_function_address_changed(
        program->program_entry.btf_resolved_function_count, addresses, program->addresses_changed_callback_context);

Done:
    ebpf_free(addresses);
    return result;
}

static ebpf_result_t
_ebpf_native_btf_resolved_function_address_changed(
    size_t address_count, _In_reads_opt_(address_count) uint64_t* addresses, _In_opt_ void* context)
{
    ebpf_native_helper_address_changed_context_t* helper_address_changed_context =
        (ebpf_native_helper_address_changed_context_t*)context;
    _Analysis_assume_(context != NULL);
    ebpf_native_program_t* native_program = helper_address_changed_context->native_program;
    size_t total_function_count = native_program->program_entry.btf_resolved_function_count;

    if (native_program->runtime_context.btf_resolved_function_data == NULL ||
        (address_count > 0 && addresses == NULL)) {
        return EBPF_INVALID_ARGUMENT;
    }

    for (size_t slot_index = 0; slot_index < total_function_count; slot_index++) {
        native_program->runtime_context.btf_resolved_function_data[slot_index].address = NULL;
    }

    if (address_count == 0) {
        return EBPF_SUCCESS;
    }

    if (address_count != total_function_count) {
        return EBPF_INVALID_ARGUMENT;
    }

    for (size_t slot_index = 0; slot_index < total_function_count; slot_index++) {
        const btf_resolved_function_entry_t* function_entry =
            &native_program->program_entry.btf_resolved_functions[slot_index];

        if (_ebpf_native_is_unused_btf_resolved_function_entry(function_entry)) {
            if (addresses[slot_index] != 0) {
                return EBPF_INVALID_ARGUMENT;
            }
            continue;
        }

        native_program->runtime_context.btf_resolved_function_data[slot_index].address =
            (helper_function_t)addresses[slot_index];
    }

    return EBPF_SUCCESS;
}

static void
_ebpf_program_free_btf_resolved_function_names(
    size_t btf_resolved_function_count,
    _In_reads_(btf_resolved_function_count) const btf_resolved_function_entry_t* btf_resolved_functions)
{
    for (size_t index = 0; index < btf_resolved_function_count; index++) {
#pragma warning(suppress : 6001)
        ebpf_free((void*)btf_resolved_functions[index].name);
    }
}

static void
_ebpf_program_clear_btf_resolved_function_entries(_Inout_ ebpf_program_t* program)
{
    if (program->btf_resolved_functions != NULL) {
        _ebpf_program_free_btf_resolved_function_names(
            program->btf_resolved_function_count, program->btf_resolved_functions);
        ebpf_free(program->btf_resolved_functions);
        program->btf_resolved_functions = NULL;
    }

    program->btf_resolved_function_count = 0;
    program->btf_resolved_functions_set = false;
}

static ebpf_result_t
_ebpf_program_update_hash_with_btf_resolved_function(
    _In_ void* hash_context, _In_ const ebpf_program_btf_hash_entry_t* function_entry)
{
    ebpf_result_t return_value;
    return_value = EBPF_CRYPTOGRAPHIC_HASH_APPEND_VALUE(hash_context, function_entry->module_guid);
    if (return_value != EBPF_SUCCESS) {
        return return_value;
    }

    return_value = EBPF_CRYPTOGRAPHIC_HASH_APPEND_STR(hash_context, function_entry->name);
    if (return_value != EBPF_SUCCESS) {
        return return_value;
    }

    return_value = EBPF_CRYPTOGRAPHIC_HASH_APPEND_VALUE(hash_context, function_entry->return_type);
    if (return_value != EBPF_SUCCESS) {
        return return_value;
    }

    for (uint32_t index = 0; index < EBPF_COUNT_OF(function_entry->arguments); index++) {
        return_value = EBPF_CRYPTOGRAPHIC_HASH_APPEND_VALUE(hash_context, function_entry->arguments[index]);
        if (return_value != EBPF_SUCCESS) {
            return return_value;
        }
    }

    return EBPF_CRYPTOGRAPHIC_HASH_APPEND_VALUE(hash_context, function_entry->flags);
}

static void
_ebpf_program_free_btf_hash_entries(
    _In_ size_t btf_hash_entry_count,
    _In_reads_opt_(btf_hash_entry_count) _Frees_ptr_opt_ ebpf_program_btf_hash_entry_t* btf_hash_entries)
{
    if (btf_hash_entries == NULL) {
        return;
    }

#pragma warning(push)
#pragma warning(disable : 6001)
    for (size_t index = 0; index < btf_hash_entry_count; index++) {
        ebpf_program_btf_hash_entry_t* hash_entry = &btf_hash_entries[index];
        if (hash_entry->name != NULL) {
            ebpf_free(hash_entry->name);
        }
    }
#pragma warning(pop)

    ebpf_free(btf_hash_entries);
}

static bool
_ebpf_program_is_unused_btf_resolved_function_entry(_In_ const btf_resolved_function_entry_t* function_entry)
{
    return (
        (function_entry != NULL) && (function_entry->name != NULL) && (function_entry->name[0] == '\0') &&
        IsEqualGUID(&function_entry->module_guid, &GUID_NULL));
}

_Ret_maybenull_ static ebpf_program_btf_provider_t*
_ebpf_program_find_btf_provider(_In_ const ebpf_program_t* program, _In_ const GUID* module_guid)
{
    for (size_t index = 0; index < program->btf_provider_count; index++) {
        ebpf_program_btf_provider_t* provider = program->btf_providers[index];
        if ((provider != NULL) && IsEqualGUID(module_guid, &provider->module_guid)) {
            return provider;
        }
    }

    return NULL;
}

static void _ebpf_program_update_btf_provider_state_under_lock(
    _Inout_ ebpf_program_t* program)
{
    bool all_attached = true;

    for (size_t index = 0; index < program->btf_provider_count; index++) {
        ebpf_program_btf_provider_t* provider = program->btf_providers[index];
        if ((provider == NULL) || !provider->attached || (provider->provider_data == NULL)) {
            all_attached = false;
            break;
        }
    }

    program->btf_resolved_function_providers_ready = (char)all_attached;
}

_Success_(return) static bool _ebpf_program_find_btf_provider_function_index(
    _In_ const ebpf_btf_resolved_function_provider_data_t* provider_data,
    _In_z_ const char* function_name,
    _Out_ uint32_t* function_index)
{
    for (uint32_t index = 0; index < provider_data->btf_resolved_function_count; index++) {
        if (strcmp(provider_data->btf_resolved_function_prototypes[index].name, function_name) == 0) {
            *function_index = index;
            return true;
        }
    }

    return false;
}

static ebpf_result_t
    _ebpf_program_copy_btf_resolved_function_hash_entries_under_lock(
        _In_ const ebpf_program_t* program,
        _Outptr_result_buffer_maybenull_(*btf_hash_entry_count) ebpf_program_btf_hash_entry_t** btf_hash_entries,
        _Out_ size_t* btf_hash_entry_count)
{
    ebpf_program_btf_hash_entry_t* local_btf_hash_entries = NULL;
    size_t local_btf_hash_entry_count = 0;
    size_t used_btf_resolved_function_count = 0;
    ebpf_result_t result = EBPF_SUCCESS;

    *btf_hash_entries = NULL;
    *btf_hash_entry_count = 0;

    for (size_t function_index = 0; function_index < program->btf_resolved_function_count; function_index++) {
        if (!_ebpf_program_is_unused_btf_resolved_function_entry(&program->btf_resolved_functions[function_index])) {
            used_btf_resolved_function_count++;
        }
    }

    if (used_btf_resolved_function_count == 0) {
        return EBPF_SUCCESS;
    }

    size_t btf_hash_entries_length = 0;
    result = ebpf_safe_size_t_multiply(
        used_btf_resolved_function_count, sizeof(ebpf_program_btf_hash_entry_t), &btf_hash_entries_length);
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    local_btf_hash_entries =
        (ebpf_program_btf_hash_entry_t*)ebpf_allocate_with_tag(btf_hash_entries_length, EBPF_POOL_TAG_PROGRAM);
    if (local_btf_hash_entries == NULL) {
        result = EBPF_NO_MEMORY;
        goto Exit;
    }
    memset(local_btf_hash_entries, 0, btf_hash_entries_length);

    for (size_t function_index = 0; function_index < program->btf_resolved_function_count; function_index++) {
        const btf_resolved_function_entry_t* function_entry = &program->btf_resolved_functions[function_index];
        const ebpf_btf_resolved_function_provider_data_t* provider_data = NULL;
        const ebpf_btf_resolved_function_prototype_t* provider_function_prototype = NULL;
        ebpf_program_btf_provider_t* provider = NULL;
        uint32_t provider_function_index = 0;
        size_t name_length = 0;

        if (_ebpf_program_is_unused_btf_resolved_function_entry(function_entry)) {
            continue;
        }

        if (local_btf_hash_entry_count >= used_btf_resolved_function_count) {
            result = EBPF_INVALID_ARGUMENT;
            goto Exit;
        }

        provider = _ebpf_program_find_btf_provider(program, &function_entry->module_guid);
        if ((provider == NULL) || !provider->attached || (provider->provider_data == NULL)) {
            result = EBPF_EXTENSION_FAILED_TO_LOAD;
            goto Exit;
        }

        provider_data = provider->provider_data;
        if (!_ebpf_program_find_btf_provider_function_index(
                provider_data, function_entry->name, &provider_function_index)) {
            result = EBPF_INVALID_ARGUMENT;
            goto Exit;
        }

        provider_function_prototype = &provider_data->btf_resolved_function_prototypes[provider_function_index];
        name_length = strlen(function_entry->name) + 1;
        ebpf_program_btf_hash_entry_t* hash_entry = &local_btf_hash_entries[local_btf_hash_entry_count];
        hash_entry->name = (char*)ebpf_allocate_with_tag(name_length, EBPF_POOL_TAG_PROGRAM);
        if (hash_entry->name == NULL) {
            result = EBPF_NO_MEMORY;
            goto Exit;
        }

        memcpy(hash_entry->name, function_entry->name, name_length);
        hash_entry->module_guid = function_entry->module_guid;
        hash_entry->return_type = provider_function_prototype->return_type;
        memcpy(
            hash_entry->arguments,
            provider_function_prototype->arguments,
            sizeof(provider_function_prototype->arguments));
        hash_entry->flags = provider_function_prototype->flags;
        local_btf_hash_entry_count++;
    }

    *btf_hash_entries = local_btf_hash_entries;
    *btf_hash_entry_count = local_btf_hash_entry_count;
    local_btf_hash_entries = NULL;
    local_btf_hash_entry_count = 0;

Exit:
    _ebpf_program_free_btf_hash_entries(local_btf_hash_entry_count, local_btf_hash_entries);
    return result;
}

static void
_ebpf_program_clear_btf_provider_bindings(_Inout_ ebpf_program_t* program)
{
    for (size_t index = 0; index < program->btf_provider_count; index++) {
        ebpf_free(program->btf_providers[index]);
    }

    ebpf_free(program->btf_providers);
    program->btf_providers = NULL;
    program->btf_provider_count = 0;
    program->btf_resolved_function_providers_ready = (char)false;
}

static ebpf_result_t
    _ebpf_program_initialize_btf_provider_bindings(_Inout_ ebpf_program_t* program)
{
    ebpf_program_btf_provider_t** local_providers = NULL;
    size_t provider_count = 0;
    size_t providers_length = 0;
    ebpf_result_t result = EBPF_SUCCESS;

    for (size_t function_index = 0; function_index < program->btf_resolved_function_count; function_index++) {
        const btf_resolved_function_entry_t* function_entry = &program->btf_resolved_functions[function_index];
        bool provider_found = false;

        if (_ebpf_program_is_unused_btf_resolved_function_entry(function_entry)) {
            continue;
        }

        for (size_t previous_index = 0; previous_index < function_index; previous_index++) {
            if (_ebpf_program_is_unused_btf_resolved_function_entry(&program->btf_resolved_functions[previous_index])) {
                continue;
            }
            if (IsEqualGUID(
                    &program->btf_resolved_functions[previous_index].module_guid, &function_entry->module_guid)) {
                provider_found = true;
                break;
            }
        }

        if (!provider_found) {
            provider_count++;
        }
    }

    if (provider_count == 0) {
        return EBPF_SUCCESS;
    }

    result = ebpf_safe_size_t_multiply(provider_count, sizeof(*local_providers), &providers_length);
    if (result != EBPF_SUCCESS) {
        return result;
    }

    local_providers = ebpf_allocate_with_tag(providers_length, EBPF_POOL_TAG_PROGRAM);
    if (local_providers == NULL) {
        return EBPF_NO_MEMORY;
    }
    memset(local_providers, 0, providers_length);

    provider_count = 0;
    for (size_t function_index = 0; function_index < program->btf_resolved_function_count; function_index++) {
        const btf_resolved_function_entry_t* function_entry = &program->btf_resolved_functions[function_index];
        bool provider_found = false;
        ebpf_program_btf_provider_t* local_provider = NULL;

        if (_ebpf_program_is_unused_btf_resolved_function_entry(function_entry)) {
            continue;
        }

        for (size_t index = 0; index < provider_count; index++) {
            if (IsEqualGUID(&local_providers[index]->module_guid, &function_entry->module_guid)) {
                provider_found = true;
                break;
            }
        }

        if (provider_found) {
            continue;
        }

        local_provider = ebpf_allocate_with_tag(sizeof(*local_provider), EBPF_POOL_TAG_PROGRAM);
        if (local_provider == NULL) {
            result = EBPF_NO_MEMORY;
            goto Exit;
        }
        memset(local_provider, 0, sizeof(*local_provider));
        local_provider->program = program;
        local_provider->module_guid = function_entry->module_guid;
        local_providers[provider_count] = local_provider;
        provider_count++;
    }

    program->btf_providers = local_providers;
    program->btf_provider_count = provider_count;
    _ebpf_program_update_btf_provider_state_under_lock(program);
    local_providers = NULL;
    return EBPF_SUCCESS;

Exit:
    for (size_t index = 0; index < provider_count; index++) {
        ebpf_free(local_providers[index]);
    }
    ebpf_free(local_providers);
    return result;
}

static void
_ebpf_program_deregister_btf_provider_client(_Inout_ ebpf_program_t* program)
{
    if (program->btf_nmr_client_handle != NULL) {
        NTSTATUS status = NmrDeregisterClient(program->btf_nmr_client_handle);
        if (status == STATUS_PENDING) {
            NmrWaitForClientDeregisterComplete(program->btf_nmr_client_handle);
        } else {
            ebpf_assert(status == STATUS_SUCCESS);
        }

        program->btf_nmr_client_handle = NULL;
    }
}

static NTSTATUS
_ebpf_program_btf_provider_attach_callback(
    _In_ HANDLE nmr_binding_handle,
    _In_ void* client_context,
    _In_ const NPI_REGISTRATION_INSTANCE* provider_registration_instance)
{
    ebpf_program_t* program = (ebpf_program_t*)client_context;
    const ebpf_btf_resolved_function_provider_data_t* provider_data =
        (const ebpf_btf_resolved_function_provider_data_t*)provider_registration_instance->NpiSpecificCharacteristics;
    ebpf_lock_state_t state = 0;
    bool lock_acquired = false;
    ebpf_program_btf_provider_t* provider = NULL;
    void* provider_binding_context = NULL;
    void* provider_dispatch = NULL;
    NTSTATUS status = STATUS_SUCCESS;

    if (provider_registration_instance->ModuleId == NULL ||
        provider_registration_instance->ModuleId->Type != MIT_GUID) {
        return STATUS_INVALID_PARAMETER;
    }

    if (!ebpf_validate_btf_resolved_function_provider_data(provider_data)) {
        return STATUS_INVALID_PARAMETER;
    }

    state = ebpf_lock_lock(&program->lock);
    lock_acquired = true;

    provider = _ebpf_program_find_btf_provider(program, &provider_registration_instance->ModuleId->Guid);
    if (provider == NULL) {
        status = STATUS_NOINTERFACE;
        goto Done;
    }

    if (provider->attached) {
        EBPF_LOG_MESSAGE_GUID(
            EBPF_TRACELOG_LEVEL_ERROR,
            EBPF_TRACELOG_KEYWORD_PROGRAM,
            "BTF provider already attached.",
            &provider->module_guid);
        status = STATUS_INVALID_DEVICE_STATE;
        goto Done;
    }

    ebpf_lock_unlock(&program->lock, state);
    lock_acquired = false;

#pragma warning(push)
#pragma warning(disable : 6387) // NULL is allowed for client dispatch.
    status = NmrClientAttachProvider(nmr_binding_handle, provider, NULL, &provider_binding_context, &provider_dispatch);
#pragma warning(pop)
    if (!NT_SUCCESS(status)) {
        EBPF_LOG_MESSAGE_NTSTATUS(
            EBPF_TRACELOG_LEVEL_ERROR,
            EBPF_TRACELOG_KEYWORD_PROGRAM,
            "NmrClientAttachProvider failed for BTF provider.",
            status);
        goto Done;
    }

    state = ebpf_lock_lock(&program->lock);
    lock_acquired = true;

    provider->provider_binding_context = provider_binding_context;
    provider->provider_data = provider_data;
    provider->nmr_binding_handle = nmr_binding_handle;
    provider->attached = true;
    _ebpf_program_update_btf_provider_state_under_lock(program);

Done:
    if (lock_acquired) {
        ebpf_lock_unlock(&program->lock, state);
    }
    if (NT_SUCCESS(status)) {
        (void)_ebpf_program_notify_btf_resolved_function_changes(program);
    }
    return status;
}

static NTSTATUS
_ebpf_program_btf_provider_detach_callback(_In_ void* client_binding_context)
{
    ebpf_program_btf_provider_t* provider = (ebpf_program_btf_provider_t*)client_binding_context;
    if (provider == NULL || provider->program == NULL) {
        return STATUS_SUCCESS;
    }

    ebpf_program_t* program = provider->program;

    ebpf_lock_state_t state = ebpf_lock_lock(&program->lock);
    provider->attached = false;
    provider->provider_data = NULL;
    provider->nmr_binding_handle = NULL;
    provider->provider_binding_context = NULL;
    _ebpf_program_update_btf_provider_state_under_lock(program);
    ebpf_lock_unlock(&program->lock, state);

    if (program->object.id != 0) {
        ebpf_epoch_synchronize();
    }

    (void)_ebpf_program_notify_btf_resolved_function_changes(program);

    return STATUS_SUCCESS;
}

static bool
_ebpf_program_are_btf_providers_ready(_In_ const ebpf_program_t* program)
{
    // Detach callbacks clear this flag before quiescing the current epoch so new invocations fail
    // before the native BTF-resolved function pointers are rewritten.
    return program->btf_provider_count == 0 ||
           ReadNoFence8((volatile const char*)&program->btf_resolved_function_providers_ready) != 0;
}

static ebpf_result_t _ebpf_program_get_btf_resolved_function_addresses_under_lock(
    _In_ const ebpf_program_t* program,
    size_t addresses_count,
    _Out_writes_(addresses_count) uint64_t* addresses,
    bool fail_if_unresolved)
{
    ebpf_result_t result = EBPF_SUCCESS;

    if (program->btf_resolved_function_count > addresses_count) {
        result = EBPF_INSUFFICIENT_BUFFER;
        goto Exit;
    }

    if (program->btf_resolved_function_count > 0) {
        memset(addresses, 0, program->btf_resolved_function_count * sizeof(*addresses));
    }

    for (size_t function_index = 0; function_index < program->btf_resolved_function_count; function_index++) {
        const btf_resolved_function_entry_t* function_entry = &program->btf_resolved_functions[function_index];
        const ebpf_btf_resolved_function_provider_data_t* provider_data = NULL;
        ebpf_program_btf_provider_t* provider = NULL;

        if (_ebpf_program_is_unused_btf_resolved_function_entry(function_entry)) {
            continue;
        }

        provider = _ebpf_program_find_btf_provider(program, &function_entry->module_guid);
        if (provider == NULL || !provider->attached || provider->provider_data == NULL) {
            result = fail_if_unresolved ? EBPF_EXTENSION_FAILED_TO_LOAD : EBPF_SUCCESS;
            if (result != EBPF_SUCCESS) {
                goto Exit;
            }
            continue;
        }

        provider_data = provider->provider_data;
        if (provider_data == NULL) {
            result = fail_if_unresolved ? EBPF_EXTENSION_FAILED_TO_LOAD : EBPF_SUCCESS;
            if (result != EBPF_SUCCESS) {
                goto Exit;
            }
            continue;
        }

        uint32_t provider_function_index = 0;
        if (!_ebpf_program_find_btf_provider_function_index(
                provider_data, function_entry->name, &provider_function_index)) {
            result = EBPF_INVALID_ARGUMENT;
            goto Exit;
        }

        addresses[function_index] = provider_data->btf_resolved_function_addresses[provider_function_index];
    }

Exit:
    return result;
}

static ebpf_result_t
_ebpf_program_notify_btf_resolved_function_changes(_Inout_ ebpf_program_t* program)
{
    ebpf_result_t result = EBPF_SUCCESS;
    ebpf_lock_state_t state = 0;
    uint64_t* addresses = NULL;
    ebpf_btf_resolved_function_addresses_changed_callback_t callback = NULL;
    void* callback_context = NULL;
    size_t btf_resolved_function_count = 0;

    state = ebpf_lock_lock((ebpf_lock_t*)&program->lock);

    callback = program->btf_resolved_function_addresses_changed_callback;
    callback_context = program->btf_resolved_function_addresses_changed_context;
    btf_resolved_function_count = program->btf_resolved_function_count;

    if (callback == NULL) {
        ebpf_lock_unlock((ebpf_lock_t*)&program->lock, state);
        return EBPF_SUCCESS;
    }

    if (btf_resolved_function_count > 0) {
        size_t addresses_length = 0;
        result = ebpf_safe_size_t_multiply(btf_resolved_function_count, sizeof(*addresses), &addresses_length);
        if (result != EBPF_SUCCESS) {
            goto Done;
        }

        addresses = ebpf_allocate_with_tag(addresses_length, EBPF_POOL_TAG_PROGRAM);
        if (addresses == NULL) {
            result = EBPF_NO_MEMORY;
            goto Done;
        }

        result = _ebpf_program_get_btf_resolved_function_addresses_under_lock(
            program, btf_resolved_function_count, addresses, false);
        if (result != EBPF_SUCCESS) {
            goto Done;
        }
    }

    result = callback(btf_resolved_function_count, addresses, callback_context);

Done:
    ebpf_lock_unlock((ebpf_lock_t*)&program->lock, state);
    ebpf_free(addresses);
    return result;
}

_Must_inspect_result_ ebpf_result_t
ebpf_program_get_btf_resolved_function_addresses(
    _In_ const ebpf_program_t* program, size_t addresses_count, _Out_writes_(addresses_count) uint64_t* addresses)
{
    EBPF_LOG_ENTRY();
    ebpf_lock_state_t state = ebpf_lock_lock((ebpf_lock_t*)&program->lock);
    ebpf_result_t result =
        _ebpf_program_get_btf_resolved_function_addresses_under_lock(program, addresses_count, addresses, true);
    ebpf_lock_unlock((ebpf_lock_t*)&program->lock, state);
    EBPF_RETURN_RESULT(result);
}

_Must_inspect_result_ ebpf_result_t
ebpf_program_set_btf_resolved_function_entries(
    _Inout_ ebpf_program_t* program,
    size_t btf_resolved_function_count,
    _In_reads_opt_(btf_resolved_function_count) const btf_resolved_function_entry_t* btf_resolved_functions)
{
    EBPF_LOG_ENTRY();

    ebpf_result_t result = EBPF_SUCCESS;
    ebpf_lock_state_t state = 0;
    bool has_used_btf_resolved_function = false;
    bool register_btf_provider_client = false;

    state = ebpf_lock_lock(&program->lock);

    if (btf_resolved_function_count == 0) {
        program->btf_resolved_functions_set = true;
        goto Exit;
    }

    if ((btf_resolved_functions == NULL) || (program->btf_resolved_functions != NULL)) {
        result = EBPF_INVALID_ARGUMENT;
        goto Exit;
    }

    for (size_t index = 0; index < btf_resolved_function_count; index++) {
        if (!_ebpf_program_is_unused_btf_resolved_function_entry(&btf_resolved_functions[index])) {
            has_used_btf_resolved_function = true;
            break;
        }
    }

    if (!has_used_btf_resolved_function) {
        program->btf_resolved_functions_set = true;
        goto Exit;
    }
    size_t entries_length = 0;
    result =
        ebpf_safe_size_t_multiply(sizeof(btf_resolved_function_entry_t), btf_resolved_function_count, &entries_length);
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    program->btf_resolved_functions = ebpf_allocate_with_tag(entries_length, EBPF_POOL_TAG_PROGRAM);
    if (program->btf_resolved_functions == NULL) {
        result = EBPF_NO_MEMORY;
        goto Exit;
    }
    memset(program->btf_resolved_functions, 0, entries_length);
    // Preserve the generated sparse slot layout so native callsites keep their global BTF-function indices.
    program->btf_resolved_function_count = btf_resolved_function_count;

    for (size_t index = 0; index < btf_resolved_function_count; index++) {
        size_t name_length = strlen(btf_resolved_functions[index].name) + 1;
        char* duplicated_name = ebpf_allocate_with_tag(name_length, EBPF_POOL_TAG_PROGRAM);
        if (duplicated_name == NULL) {
            result = EBPF_NO_MEMORY;
            goto Exit;
        }

        memcpy(duplicated_name, btf_resolved_functions[index].name, name_length);
        program->btf_resolved_functions[index] = btf_resolved_functions[index];
        program->btf_resolved_functions[index].name = duplicated_name;
    }

    result = _ebpf_program_initialize_btf_provider_bindings(program);
    if (result != EBPF_SUCCESS) {
        goto Exit;
    }

    program->btf_resolved_functions_set = true;
    register_btf_provider_client = (program->btf_provider_count > 0);

Exit:
    if (result != EBPF_SUCCESS) {
        _ebpf_program_clear_btf_provider_bindings(program);
        _ebpf_program_clear_btf_resolved_function_entries(program);
    }

    ebpf_lock_unlock(&program->lock, state);

    if (result == EBPF_SUCCESS && register_btf_provider_client) {
        result = _ebpf_program_register_btf_provider_client(program);
        if (result != EBPF_SUCCESS) {
            state = ebpf_lock_lock(&program->lock);
            _ebpf_program_clear_btf_provider_bindings(program);
            _ebpf_program_clear_btf_resolved_function_entries(program);
            ebpf_lock_unlock(&program->lock, state);
        }
    }

    EBPF_RETURN_RESULT(result);
}

void
ebpf_program_clear_btf_resolved_function_entries(_Inout_ ebpf_program_t* program)
{
    EBPF_LOG_ENTRY();
    ebpf_lock_state_t state = 0;

    state = ebpf_lock_lock(&program->lock);
    _ebpf_program_clear_btf_resolved_function_entries(program);
    ebpf_lock_unlock(&program->lock, state);
    EBPF_LOG_EXIT();
}

_Must_inspect_result_ ebpf_result_t
ebpf_program_register_for_btf_resolved_function_changes(
    _Inout_ ebpf_program_t* program,
    _In_opt_ ebpf_btf_resolved_function_addresses_changed_callback_t callback,
    _In_opt_ void* context)
{
    ebpf_lock_state_t state = ebpf_lock_lock((ebpf_lock_t*)&program->lock);

    program->btf_resolved_function_addresses_changed_callback = callback;
    program->btf_resolved_function_addresses_changed_context = context;
    ebpf_lock_unlock((ebpf_lock_t*)&program->lock, state);
    return EBPF_SUCCESS;
}

bool
_ebpf_validate_btf_resolved_function_prototype(_In_ const ebpf_btf_resolved_function_prototype_t* function_prototype)
{
    return (
        (function_prototype != NULL) &&
        _ebpf_validate_extension_object_header(EBPF_BTF_RESOLVED_FUNCTION_PROTOTYPE, &function_prototype->header) &&
        (function_prototype->header.total_size == EBPF_BTF_RESOLVED_FUNCTION_PROTOTYPE_CURRENT_VERSION_TOTAL_SIZE) &&
        (function_prototype->name != NULL));
}

bool
ebpf_validate_btf_resolved_function_prototype_array(
    _In_reads_(count) const ebpf_btf_resolved_function_prototype_t* function_prototype_array, uint32_t count)
{
    if (count > 0) {
        if (function_prototype_array == NULL) {
            return false;
        }

        if (!_ebpf_validate_btf_resolved_function_prototype(function_prototype_array)) {
            return false;
        }

        size_t function_prototype_size = function_prototype_array[0].header.total_size;
        for (uint32_t i = 0; i < count; i++) {
            const ebpf_btf_resolved_function_prototype_t* function_prototype =
                (const ebpf_btf_resolved_function_prototype_t*)ARRAY_ELEMENT_INDEX(
                    function_prototype_array, i, function_prototype_size);
            if (!_ebpf_validate_btf_resolved_function_prototype(function_prototype)) {
                return false;
            }
        }
    } else if (function_prototype_array != NULL) {
        return false;
    }

    return true;
}

bool
ebpf_validate_btf_resolved_function_provider_data(_In_ const ebpf_btf_resolved_function_provider_data_t* provider_data)
{
    return (
        (provider_data != NULL) &&
        _ebpf_validate_extension_object_header(EBPF_BTF_RESOLVED_FUNCTION_PROVIDER_DATA, &provider_data->header) &&
        (provider_data->btf_resolved_function_count > 0) &&
        ebpf_validate_btf_resolved_function_prototype_array(
            provider_data->btf_resolved_function_prototypes, provider_data->btf_resolved_function_count) &&
        (provider_data->btf_resolved_function_addresses != NULL));
}

static bool
_ebpf_validate_btf_resolved_function_provider_info(_In_ const ebpf_btf_resolved_function_provider_info_t* provider_info)
{
    if ((provider_info == NULL) ||
        (provider_info->header.version != EBPF_BTF_RESOLVED_FUNCTION_PROVIDER_INFO_CURRENT_VERSION) ||
        (provider_info->header.size != EBPF_BTF_RESOLVED_FUNCTION_PROVIDER_INFO_CURRENT_VERSION_SIZE) ||
        IsEqualGUID(&provider_info->module_guid, &GUID_NULL) || (provider_info->btf_resolved_function_count == 0) ||
        !ebpf_validate_btf_resolved_function_prototype_array(
            provider_info->btf_resolved_function_prototypes, provider_info->btf_resolved_function_count)) {
        return false;
    }

    return true;
}

static ebpf_result_t
_ebpf_store_update_btf_resolved_function(
    ebpf_store_key_t function_collection_key, _In_ const ebpf_btf_resolved_function_prototype_t* function_prototype)
{
    ebpf_result_t result = EBPF_SUCCESS;
    ebpf_store_key_t function_key = NULL;
    wchar_t* wide_function_name = NULL;

    wide_function_name = ebpf_get_wstring_from_string(function_prototype->name);
    if (wide_function_name == NULL) {
        result = EBPF_NO_MEMORY;
        goto Exit;
    }

    result = ebpf_create_registry_key(function_collection_key, wide_function_name, REG_CREATE_FLAGS, &function_key);
    if (!IS_SUCCESS(result)) {
        goto Exit;
    }

    result = ebpf_write_registry_value_dword(
        function_key, EBPF_BTF_FUNCTION_DATA_RETURN_TYPE, function_prototype->return_type);
    if (!IS_SUCCESS(result)) {
        goto Exit;
    }

    result = ebpf_write_registry_value_binary(
        function_key,
        EBPF_BTF_FUNCTION_DATA_ARGUMENTS,
        (uint8_t*)function_prototype->arguments,
        sizeof(function_prototype->arguments));
    if (!IS_SUCCESS(result)) {
        goto Exit;
    }

    result = ebpf_write_registry_value_dword(function_key, EBPF_BTF_FUNCTION_DATA_FLAGS, function_prototype->flags);
Exit:
    ebpf_free_wstring(wide_function_name);
    ebpf_close_registry_key(function_key);
    return result;
}

static ebpf_result_t
_ebpf_store_update_btf_resolved_function_provider_information(
    ebpf_store_key_t root_key, _In_ const ebpf_btf_resolved_function_provider_info_t* provider_info)
{
    ebpf_result_t result = EBPF_SUCCESS;
    ebpf_store_key_t provider_key = NULL;
    ebpf_store_key_t btf_resolved_functions_key = NULL;
    ebpf_store_key_t provider_info_key = NULL;
    ebpf_store_key_t function_collection_key = NULL;

    if (!_ebpf_validate_btf_resolved_function_provider_info(provider_info)) {
        return EBPF_INVALID_ARGUMENT;
    }

    result = _ebpf_store_open_or_create_provider_registry_key(root_key, &provider_key);
    if (!IS_SUCCESS(result)) {
        goto Exit;
    }

    result = ebpf_create_registry_key(
        provider_key, EBPF_BTF_RESOLVED_FUNCTIONS_REGISTRY_KEY, REG_CREATE_FLAGS, &btf_resolved_functions_key);
    if (!IS_SUCCESS(result)) {
        goto Exit;
    }

    wchar_t guid_string[GUID_STRING_LENGTH + 1];
    result = ebpf_convert_guid_to_string(&provider_info->module_guid, guid_string, GUID_STRING_LENGTH + 1);
    if (!IS_SUCCESS(result)) {
        goto Exit;
    }

    result = ebpf_create_registry_key(btf_resolved_functions_key, guid_string, REG_CREATE_FLAGS, &provider_info_key);
    if (!IS_SUCCESS(result)) {
        goto Exit;
    }

    result = _ebpf_store_update_extension_header_information(provider_info_key, &provider_info->header);
    if (!IS_SUCCESS(result)) {
        goto Exit;
    }

    result = ebpf_delete_registry_tree(provider_info_key, EBPF_BTF_FUNCTIONS_REGISTRY_KEY);
    if (result != EBPF_SUCCESS && result != EBPF_FILE_NOT_FOUND) {
        goto Exit;
    }
    result = ebpf_create_registry_key(
        provider_info_key, EBPF_BTF_FUNCTIONS_REGISTRY_KEY, REG_CREATE_FLAGS, &function_collection_key);
    if (!IS_SUCCESS(result)) {
        goto Exit;
    }

    for (uint32_t i = 0; i < provider_info->btf_resolved_function_count; i++) {
        result = _ebpf_store_update_btf_resolved_function(
            function_collection_key, &provider_info->btf_resolved_function_prototypes[i]);
        if (!IS_SUCCESS(result)) {
            goto Exit;
        }
    }

Exit:
    ebpf_close_registry_key(function_collection_key);
    ebpf_close_registry_key(provider_info_key);
    ebpf_close_registry_key(btf_resolved_functions_key);
    ebpf_close_registry_key(provider_key);
    return result;
}

ebpf_result_t
ebpf_store_update_btf_resolved_function_provider_information(
    _In_ const ebpf_btf_resolved_function_provider_info_t* provider_info)
{
    ebpf_result_t result = EBPF_SUCCESS;

    result = _ebpf_store_update_btf_resolved_function_provider_information(ebpf_store_hkcu_root_key, provider_info);
    if (!IS_SUCCESS(result)) {
        return result;
    }

    result = _ebpf_store_update_btf_resolved_function_provider_information(ebpf_store_hklm_root_key, provider_info);
    if (result == EBPF_ACCESS_DENIED) {
        result = EBPF_SUCCESS;
    }

    return result;
}

static bool
_ebpf_validate_btf_resolved_function_provider_identity(
    _In_ const ebpf_btf_resolved_function_provider_info_t* provider_info)
{
    return provider_info != NULL && !IsEqualGUID(&provider_info->module_guid, &GUID_NULL);
}

static ebpf_result_t
_ebpf_store_delete_btf_resolved_function_provider_information(
    ebpf_store_key_t root_key, _In_ const ebpf_btf_resolved_function_provider_info_t* provider_info)
{
    ebpf_result_t result = EBPF_SUCCESS;
    ebpf_store_key_t provider_key = NULL;
    ebpf_store_key_t btf_resolved_functions_key = NULL;

    if (!_ebpf_validate_btf_resolved_function_provider_identity(provider_info)) {
        return EBPF_INVALID_ARGUMENT;
    }

    result = _ebpf_store_open_or_create_provider_registry_key(root_key, &provider_key);
    if (!IS_SUCCESS(result)) {
        goto Exit;
    }

    result = ebpf_open_registry_key(
        provider_key, EBPF_BTF_RESOLVED_FUNCTIONS_REGISTRY_KEY, REG_DELETE_FLAGS, &btf_resolved_functions_key);
    if (!IS_SUCCESS(result)) {
        goto Exit;
    }

    wchar_t guid_string[GUID_STRING_LENGTH + 1];
    result = ebpf_convert_guid_to_string(&provider_info->module_guid, guid_string, GUID_STRING_LENGTH + 1);
    if (!IS_SUCCESS(result)) {
        goto Exit;
    }

    result = ebpf_delete_registry_tree(btf_resolved_functions_key, guid_string);

Exit:
    ebpf_close_registry_key(btf_resolved_functions_key);
    ebpf_close_registry_key(provider_key);
    return result;
}

ebpf_result_t
ebpf_store_delete_btf_resolved_function_provider_information(
    _In_ const ebpf_btf_resolved_function_provider_info_t* provider_info)
{
    ebpf_result_t result =
        _ebpf_store_delete_btf_resolved_function_provider_information(ebpf_store_hkcu_root_key, provider_info);
    if (!IS_SUCCESS(result)) {
        return result;
    }

    result = _ebpf_store_delete_btf_resolved_function_provider_information(ebpf_store_hklm_root_key, provider_info);
    if (result == EBPF_ACCESS_DENIED) {
        result = EBPF_SUCCESS;
    }

    return result;
}

static uint64_t
_my_driver_lookup(
    uint64_t key, uint64_t value, uint64_t value_size, uint64_t reserved1, uint64_t reserved2, _In_opt_ void* context)
{
    UNREFERENCED_PARAMETER(reserved1);
    UNREFERENCED_PARAMETER(reserved2);
    UNREFERENCED_PARAMETER(context);

    if (value != 0 && value_size >= sizeof(uint64_t)) {
        *reinterpret_cast<uint64_t*>(value) = key;
