static ebpf_store_key_t
_open_registry_key_or_require_success(_In_ ebpf_store_key_t root_key, _In_ const std::wstring& path)
{
    ebpf_store_key_t key = nullptr;
    REQUIRE(ebpf_open_registry_key(root_key, path.c_str(), KEY_READ, &key) == EBPF_SUCCESS);
    return key;
}

static void
_require_btf_function_metadata(
    _In_ ebpf_store_key_t function_collection_key,
    _In_ const ebpf_btf_resolved_function_prototype_t* function_prototype)
{
    ebpf_store_key_t function_key = nullptr;
    wchar_t* function_name = nullptr;
    uint32_t return_type = MAXUINT32;
    ebpf_argument_type_t arguments[5] = {};
    uint32_t flags = MAXUINT32;

    function_name = ebpf_get_wstring_from_string(function_prototype->name);
    REQUIRE(function_name != nullptr);

    REQUIRE(ebpf_open_registry_key(function_collection_key, function_name, KEY_READ, &function_key) == EBPF_SUCCESS);

    REQUIRE(
        ebpf_read_registry_value_dword(function_key, EBPF_BTF_FUNCTION_DATA_RETURN_TYPE, &return_type) == EBPF_SUCCESS);
    REQUIRE(return_type == static_cast<uint32_t>(function_prototype->return_type));

    REQUIRE(
        ebpf_read_registry_value_binary(
            function_key, EBPF_BTF_FUNCTION_DATA_ARGUMENTS, (uint8_t*)arguments, sizeof(arguments)) == EBPF_SUCCESS);
    REQUIRE(memcmp(arguments, function_prototype->arguments, sizeof(arguments)) == 0);

    REQUIRE(ebpf_read_registry_value_dword(function_key, EBPF_BTF_FUNCTION_DATA_FLAGS, &flags) == EBPF_SUCCESS);
    REQUIRE(flags == function_prototype->flags);
    ebpf_close_registry_key(function_key);
    ebpf_free_wstring(function_name);
}

static void
_require_btf_function_missing(
    _In_ ebpf_store_key_t function_collection_key,
    _In_ const ebpf_btf_resolved_function_prototype_t* function_prototype)
{
    ebpf_store_key_t function_key = nullptr;
    wchar_t* function_name = ebpf_get_wstring_from_string(function_prototype->name);
    REQUIRE(function_name != nullptr);

    REQUIRE(
        ebpf_open_registry_key(function_collection_key, function_name, KEY_READ, &function_key) == EBPF_FILE_NOT_FOUND);

    ebpf_free_wstring(function_name);
}

static bool
_guid_less(const GUID& left, const GUID& right)
{
    return memcmp(&left, &right, sizeof(GUID)) < 0;
}

static std::string
_btf_resolved_function_key(const GUID& module_guid, const std::string& name)
{
    std::string key(sizeof(GUID), '\0');
    memcpy(key.data(), &module_guid, sizeof(GUID));
    key.append(name);
    return key;
}

std::vector<bpf_code_generator::btf_resolved_function_dependency_t>
bpf_code_generator::get_btf_resolved_function_dependencies(const bpf_code_generator::unsafe_string& program_name)
{
    std::map<std::string, btf_resolved_function_dependency_t> dependency_map;

    auto append_dependencies = [&dependency_map](const bpf_code_generator_program& program) {
        for (const auto& [btf_id, function] : program.btf_resolved_functions) {
            btf_resolved_function_dependency_t dependency{function.name.raw(), function.module_guid, btf_id};
            dependency_map.try_emplace(_btf_resolved_function_key(function.module_guid, dependency.name), dependency);
        }
    };

    append_dependencies(programs[program_name]);

    auto reachable = get_reachable_subprograms(program_name);
    for (const auto& sub_name : reachable) {
        auto it = programs.find(sub_name);
        if (it != programs.end()) {
            append_dependencies(it->second);
        }
    }

    std::vector<btf_resolved_function_dependency_t> dependencies;
    dependencies.reserve(dependency_map.size());
    for (const auto& [_, dependency] : dependency_map) {
        dependencies.push_back(dependency);
    }

    std::sort(dependencies.begin(), dependencies.end(), [](const auto& left, const auto& right) {
        if (_guid_less(left.module_guid, right.module_guid)) {
            return true;
        }
        if (_guid_less(right.module_guid, left.module_guid)) {
            return false;
        }
        return left.name < right.name;
    });

    return dependencies;
}

static NTSTATUS
_sample_ebpf_extension_btf_provider_attach_client(
    _In_ HANDLE nmr_binding_handle,
    _In_ const void* provider_context,
    _In_ const NPI_REGISTRATION_INSTANCE* client_registration_instance,
    _In_ const void* client_binding_context,
    _In_ const void* client_dispatch,
    _Outptr_ void** provider_binding_context,
    _Outptr_result_maybenull_ const void** provider_dispatch)
{
    UNREFERENCED_PARAMETER(nmr_binding_handle);
    UNREFERENCED_PARAMETER(client_registration_instance);
    UNREFERENCED_PARAMETER(client_binding_context);
    UNREFERENCED_PARAMETER(client_dispatch);

    if (provider_binding_context == NULL || provider_dispatch == NULL || provider_context == NULL) {
        return STATUS_INVALID_PARAMETER;
    }

    // NMR passes the provider context as const void*, but the opaque binding context is returned via void**.
    *provider_binding_context = (void*)provider_context;
    *provider_dispatch = NULL;
    return STATUS_SUCCESS;
}

static NTSTATUS
_sample_ebpf_extension_btf_provider_detach_client(_In_ const void* provider_binding_context)
{
    UNREFERENCED_PARAMETER(provider_binding_context);
    return STATUS_SUCCESS;
}

void
sample_ebpf_extension_btf_provider_unregister()
{
    sample_ebpf_extension_btf_provider_t* provider_context = &_sample_ebpf_extension_btf_provider_context;

    if (provider_context->nmr_provider_handle != NULL) {
        NTSTATUS status = NmrDeregisterProvider(provider_context->nmr_provider_handle);
        if (status == STATUS_PENDING) {
            NmrWaitForProviderDeregisterComplete(provider_context->nmr_provider_handle);
        } else {
            CXPLAT_RUNTIME_ASSERT(status == STATUS_SUCCESS);
        }

        provider_context->nmr_provider_handle = NULL;
    }
}

NTSTATUS
sample_ebpf_extension_btf_provider_register()
{
    sample_ebpf_extension_btf_provider_t* local_provider_context = &_sample_ebpf_extension_btf_provider_context;
    NTSTATUS status = NmrRegisterProvider(
        &_sample_ebpf_extension_btf_provider_characteristics,
        local_provider_context,
        &local_provider_context->nmr_provider_handle);

    if (!NT_SUCCESS(status)) {
        sample_ebpf_extension_btf_provider_unregister();
    }

    return status;
}

static uint64_t
_sample_ebpf_extension_btf_lookup(
    uint64_t key, uint64_t value, uint64_t value_size, uint64_t reserved1, uint64_t reserved2, _In_opt_ void* context)
{
    UNREFERENCED_PARAMETER(reserved1);
    UNREFERENCED_PARAMETER(reserved2);
    UNREFERENCED_PARAMETER(context);

    if (value != 0 && value_size >= sizeof(uint64_t)) {
        *(uint64_t*)value = key;
    }

    return key + value_size;
}

