static void
_callgraph_bpf2bpf_test(ebpf_execution_type_t execution_type)
{
    _test_helper_end_to_end test_helper;
    test_helper.initialize();

    single_instance_hook_t hook(EBPF_PROGRAM_TYPE_BIND, EBPF_ATTACH_TYPE_BIND);
    REQUIRE(hook.initialize() == EBPF_SUCCESS);

    program_info_provider_t bind_program_info;
    REQUIRE(bind_program_info.initialize(EBPF_PROGRAM_TYPE_BIND) == EBPF_SUCCESS);

    const char* file_name =
        (execution_type == EBPF_EXECUTION_NATIVE ? "callgraph_bpf2bpf_um.dll" : "callgraph_bpf2bpf.o");

    std::function<ebpf_result_t(void*, uint32_t*)> invoke =
        [&hook](_Inout_ void* context, _Out_ uint32_t* result) -> ebpf_result_t { return hook.fire(context, result); };

    // Test entry_program1: calls S1 and S4 (helper call graph scenario).
    {
        program_load_attach_helper_t program_helper;
        program_helper.initialize(file_name, BPF_PROG_TYPE_BIND, "entry_program1", execution_type, nullptr, 0, hook);

        // entry_program1 calls S1 and S4. Expected result is BIND_REDIRECT.
        REQUIRE(emulate_bind(invoke, 1001, "callgraph_e1") == BIND_REDIRECT);
    }

    // Test entry_program2: calls S2 (which calls S3) (helper call chain scenario).
    {
        program_load_attach_helper_t program_helper;
        program_helper.initialize(file_name, BPF_PROG_TYPE_BIND, "entry_program2", execution_type, nullptr, 0, hook);

        // entry_program2 calls S2 (which calls S3). Expected result is BIND_PERMIT_SOFT.
        REQUIRE(emulate_bind(invoke, 2002, "callgraph_e2") == BIND_PERMIT_SOFT);
    }

    // Test entry_program3: calls update_map subprogram (map operations scenario).
    {
        const char* error_message = nullptr;
        bpf_object_ptr unique_object;
        fd_t program_fd;
        int result;

        result = ebpf_program_load(
            file_name, BPF_PROG_TYPE_UNSPEC, execution_type, &unique_object, &program_fd, &error_message);

        if (error_message) {
            printf("ebpf_program_load failed with %s\n", error_message);
            ebpf_free((void*)error_message);
        }
        REQUIRE(result == 0);

        // Find entry_program3 by name.
        struct bpf_program* prog = bpf_object__find_program_by_name(unique_object.get(), "entry_program3");
        REQUIRE(prog != nullptr);
        program_fd = bpf_program__fd(prog);
        REQUIRE(program_fd > 0);

        fd_t bind_count_map_fd = bpf_object__find_map_fd_by_name(unique_object.get(), "bind_count_map");
        REQUIRE(bind_count_map_fd > 0);

        bpf_link_ptr link;
        uint32_t ifindex = 0;
        REQUIRE(hook.attach_link(program_fd, &ifindex, sizeof(ifindex), &link) == EBPF_SUCCESS);

        uint64_t fake_pid = 12345;

        // First bind - should succeed and update map count to 1.
        REQUIRE(emulate_bind(invoke, fake_pid, "fake_app_1") == BIND_PERMIT_SOFT);

        // Verify map was updated by the subprogram.
        uint64_t count = 0;
        REQUIRE(bpf_map_lookup_elem(bind_count_map_fd, &fake_pid, &count) == 0);
        REQUIRE(count == 1);

        // Second bind - should succeed and update map count to 2.
        REQUIRE(emulate_bind(invoke, fake_pid, "fake_app_2") == BIND_PERMIT_SOFT);
        REQUIRE(bpf_map_lookup_elem(bind_count_map_fd, &fake_pid, &count) == 0);
        REQUIRE(count == 2);

        // Bind with a different PID - should create a new entry.
        uint64_t fake_pid2 = 67890;
        REQUIRE(emulate_bind(invoke, fake_pid2, "fake_app_3") == BIND_PERMIT_SOFT);
        REQUIRE(bpf_map_lookup_elem(bind_count_map_fd, &fake_pid2, &count) == 0);
        REQUIRE(count == 1);

        // Original PID count should still be 2.
        REQUIRE(bpf_map_lookup_elem(bind_count_map_fd, &fake_pid, &count) == 0);
        REQUIRE(count == 2);

        hook.detach_and_close_link(&link);
        bpf_object__close(unique_object.release());
    }
}

static void
_callgraph_bpf2bpf_extension_reload_test(ebpf_execution_type_t execution_type)
{
    _test_helper_end_to_end test_helper;
    test_helper.initialize();

    const char* file_name = "callgraph_bpf2bpf_um.dll";

    // Only meaningful for native execution (sentinels are a native-module concept).
    REQUIRE(execution_type == EBPF_EXECUTION_NATIVE);

    bpf_object_ptr unique_object;
    fd_t program_fd;
    const char* error_message = nullptr;
    int result;
    bpf_link_ptr link;

    // Load the program with the extension loaded.
    {
        single_instance_hook_t hook(EBPF_PROGRAM_TYPE_BIND, EBPF_ATTACH_TYPE_BIND);
        REQUIRE(hook.initialize() == EBPF_SUCCESS);
        program_info_provider_t bind_program_info;
        REQUIRE(bind_program_info.initialize(EBPF_PROGRAM_TYPE_BIND) == EBPF_SUCCESS);

        result = ebpf_program_load(
            file_name, BPF_PROG_TYPE_UNSPEC, execution_type, &unique_object, &program_fd, &error_message);

        if (error_message) {
            printf("ebpf_program_load failed with %s\n", error_message);
            ebpf_free((void*)error_message);
        }
        REQUIRE(result == 0);

        // Find entry_program2 — it has 3 sentinel + 1 real helper, making the
        // count mismatch most visible.
        struct bpf_program* prog = bpf_object__find_program_by_name(unique_object.get(), "entry_program2");
        REQUIRE(prog != nullptr);
        program_fd = bpf_program__fd(prog);
        REQUIRE(program_fd > 0);

        uint32_t ifindex = 0;
        REQUIRE(hook.attach_link(program_fd, &ifindex, sizeof(ifindex), &link) == EBPF_SUCCESS);

        // Program should run successfully.
        std::function<ebpf_result_t(void*, uint32_t*)> invoke =
            [&hook](_Inout_ void* context, _Out_ uint32_t* result) -> ebpf_result_t {
            return hook.fire(context, result);
        };
        REQUIRE(emulate_bind(invoke, 2002, "callgraph_e2") == BIND_PERMIT_SOFT);

        // Unload the extension (bind_program_info and hook will be destroyed).
    }

    // Reload the extension provider — this triggers _ebpf_native_helper_address_changed
    // for every loaded program. With sentinel helpers, the callback must correctly
    // map the (smaller) address array back to the right helper_data[] slots.
    {
        single_instance_hook_t hook(EBPF_PROGRAM_TYPE_BIND, EBPF_ATTACH_TYPE_BIND);
        REQUIRE(hook.initialize() == EBPF_SUCCESS);
        program_info_provider_t bind_program_info;
        REQUIRE(bind_program_info.initialize(EBPF_PROGRAM_TYPE_BIND) == EBPF_SUCCESS);

        // Re-attach and verify the program still works after the callback.
        std::function<ebpf_result_t(void*, uint32_t*)> invoke =
            [&hook](_Inout_ void* context, _Out_ uint32_t* result) -> ebpf_result_t {
            return hook.fire(context, result);
        };
        REQUIRE(emulate_bind(invoke, 2002, "callgraph_e2") == BIND_PERMIT_SOFT);
    }
}
DEC

__attribute__((noinline)) bind_action_t __attribute__((optnone))
ScenarioS3(uint64_t* pid)
{
    // S3 helper: get current pid/tgid.
    (void)bpf_get_current_pid_tgid();

    // Return based on caller-provided state so this function is not a compile-time constant.
    if (*pid != 0) {
        return BIND_REDIRECT;
    }
    return BIND_PERMIT_SOFT;
}

__attribute__((noinline)) bind_action_t __attribute__((optnone))
ScenarioS2(uint64_t* pid)
{
    // S2 intentionally uses no helpers.
    return ScenarioS3(pid);
}

__attribute__((noinline)) bind_action_t __attribute__((optnone))
ScenarioS1(uint64_t* pid)
{
    // S1 helper: get current pid/tgid.
    (void)bpf_get_current_pid_tgid();
    return ScenarioS2(pid);
}

__attribute__((noinline)) bind_action_t __attribute__((optnone))
ScenarioS4(uint64_t* pid)
{
    (void)pid;

    // S4 helper: monotonic clock.
    (void)bpf_ktime_get_ns();
    return BIND_PERMIT_SOFT;
}

__attribute__((noinline)) int __attribute__((optnone))
update_map(uint64_t* pid_ptr)
{
    uint64_t pid = *pid_ptr;

    // Call a helper function to get the current PID/TGID.
    uint64_t pid_tgid = bpf_get_current_pid_tgid();

    // Use pid_tgid to verify the helper was invoked (non-zero means success).
    if (pid_tgid == 0) {
        return -1;
    }

    // Perform map lookup and update.
    uint64_t* count = bpf_map_lookup_elem(&bind_count_map, &pid);
    if (count) {
        uint64_t new_count = *count + 1;
        return bpf_map_update_elem(&bind_count_map, &pid, &new_count, 0);
    } else {
        uint64_t initial_count = 1;
        return bpf_map_update_elem(&bind_count_map, &pid, &initial_count, 0);
    }
}

bind_action_t
entry_program1(bind_md_t* ctx)
{
    uint64_t pid = ctx->process_id;
    bind_action_t from_s1;
    bind_action_t from_s4;

    // entry_program1 directly calls two helpers.
    (void)bpf_get_current_pid_tgid();
    (void)bpf_ktime_get_ns();

    from_s1 = ScenarioS1(&pid);
    from_s4 = ScenarioS4(&pid);

    if (from_s1 == BIND_REDIRECT && from_s4 == BIND_PERMIT_SOFT) {
        return BIND_REDIRECT;
    }
    return BIND_DENY;
}

bind_action_t
entry_program2(bind_md_t* ctx)
{
    uint64_t pid = ctx->process_id;
    bind_action_t from_s2;

    // entry_program2 directly calls one helper.
    (void)bpf_get_current_pid_tgid();

    from_s2 = ScenarioS2(&pid);

    if (from_s2 == BIND_REDIRECT) {
        return BIND_PERMIT_SOFT;
    }
    return BIND_DENY;
}

bind_action_t
entry_program3(bind_md_t* ctx)
{
    uint64_t pid = ctx->process_id;

    // Call subprogram that invokes a helper function and performs map operations.
    int result = update_map(&pid);

    if (result != 0) {
        return BIND_DENY;
    }

    return BIND_PERMIT_SOFT;
}

std::set<bpf_code_generator::unsafe_string>
bpf_code_generator::get_reachable_subprograms(const unsafe_string& entry_name) const
{
    std::set<unsafe_string> reachable;
    std::vector<unsafe_string> worklist;
    worklist.push_back(entry_name);
    while (!worklist.empty()) {
        auto current = worklist.back();
        worklist.pop_back();
        auto it = programs.find(current);
        if (it == programs.end()) {
            continue;
        }
        for (const auto& inst : it->second.output_instructions) {
            if (inst.instruction.opcode == INST_OP_CALL && inst.instruction.src == INST_CALL_LOCAL &&
                !inst.relocation.empty() && reachable.find(inst.relocation) == reachable.end()) {
                reachable.insert(inst.relocation);
                worklist.push_back(inst.relocation);
            }
        }
    }
    return reachable;
}

void
bpf_code_generator::build_global_helper_index()
{
    // Check if the module has any subprograms (.text section functions).
    bool has_subprograms = false;
    for (const auto& [_, program] : programs) {
        if (is_subprogram(program)) {
            has_subprograms = true;
            break;
        }
    }

    if (!has_subprograms) {
        // No subprograms — encode instructions with original per-program ordering.
        global_helpers_ordered.clear();
        for (auto& [prog_name, program] : programs) {
            if (program.output_instructions.size() > 0) {
                program.encode_instructions(map_definitions, global_variable_sections);
            }
        }
        return;
    }

    // Module has subprograms. Build a global helper index so that entry programs
    // and their reachable subprograms share consistent helper_data[] indices.
    // Collect all unique helpers across all programs (entry + sub), keyed by helper_id.
    // Using std::map<int32_t, ...> gives us sorted-by-id order for deterministic output.
    std::map<int32_t, unsafe_string> all_helpers;
    for (const auto& [prog_name, program] : programs) {
        for (const auto& [name, helper] : program.helper_functions) {
            if (all_helpers.find(helper.id) == all_helpers.end()) {
                all_helpers[helper.id] = name;
            }
        }
    }

    // Build ordered list: position in vector = global index.
    global_helpers_ordered.clear();
    std::map<int32_t, size_t> id_to_global_index;
    size_t index = 0;
    for (const auto& [id, name] : all_helpers) {
        global_helpers_ordered.push_back({name, id});
        id_to_global_index[id] = index++;
    }

    // Remap each program's helper_functions to use global indices.
    for (auto& [prog_name, program] : programs) {
        for (auto& [name, helper] : program.helper_functions) {
            helper.index = id_to_global_index[helper.id];
        }
    }

    // Now encode instructions for all programs (deferred from generate()).
    for (auto& [prog_name, program] : programs) {
        if (program.output_instructions.size() > 0) {
            program.encode_instructions(map_definitions, global_variable_sections);
        }
    }

    // Propagate map references from reachable subprograms to entry programs.
    for (auto& [prog_name, program] : programs) {
        if (program.output_instructions.size() == 0 || is_subprogram(program)) {
            continue;
        }
        auto reachable = get_reachable_subprograms(prog_name);
        for (const auto& sub_name : reachable) {
            auto it = programs.find(sub_name);
            if (it != programs.end()) {
                program.referenced_map_indices.insert(
                    it->second.referenced_map_indices.begin(), it->second.referenced_map_indices.end());
            }
        }
    }
}

static _Must_inspect_result_ ebpf_result_t
_ebpf_safe_size_t_add3(size_t augend, size_t addend_1, size_t addend_2, _Out_ size_t* result) noexcept
{
    ebpf_result_t status = ebpf_safe_size_t_add(augend, addend_1, result);
    if (status != EBPF_SUCCESS) {
        return status;
    }

    return ebpf_safe_size_t_add(*result, addend_2, result);
}

static _Must_inspect_result_ ebpf_result_t
_ebpf_safe_size_t_multiply_add(size_t multiplicand, size_t multiplier, size_t addend, _Out_ size_t* result) noexcept
{
    ebpf_result_t status = ebpf_safe_size_t_multiply(multiplicand, multiplier, result);
    if (status != EBPF_SUCCESS) {
        return status;
    }

    return ebpf_safe_size_t_add(*result, addend, result);
}

_Must_inspect_result_ inline ebpf_result_t
ebpf_safe_size_t_to_uint16(size_t value, _Out_ uint16_t* result) noexcept
{
    if (value > static_cast<size_t>(UINT16_MAX)) {
        return EBPF_ARITHMETIC_OVERFLOW;
    }

    *result = static_cast<uint16_t>(value);
    return EBPF_SUCCESS;
}

static ebpf_result_t
_ebpf_hash_table_bucket_delete_validate(
    _In_ const ebpf_hash_table_t* hash_table, _In_ const ebpf_hash_bucket_header_t* old_bucket)
{
    ebpf_hash_bucket_entry_t* last_entry =
        _ebpf_hash_table_bucket_entry(hash_table->key_size, old_bucket, old_bucket->count - 1);
    if (last_entry == NULL) {
        return EBPF_ARITHMETIC_OVERFLOW;
    }

    if (old_bucket->count == 1) {
        return EBPF_SUCCESS;
    }

    ebpf_hash_bucket_header_t* backup_bucket = last_entry->backup_bucket;
    ebpf_assert_assume(backup_bucket != NULL);
    ebpf_assert(backup_bucket->count == old_bucket->count - 1);

    return (_ebpf_hash_table_bucket_entry(hash_table->key_size, backup_bucket, old_bucket->count - 2) == NULL)
               ? EBPF_ARITHMETIC_OVERFLOW
               : EBPF_SUCCESS;
}

uint32_t
ebpf_interlocked_increment_uint32(_Inout_ volatile uint32_t* addend)
