static __inline int
mutate_connect_authorization_context(bpf_sock_addr_t* ctx, uint32_t expected_family)
{
    if ((ctx->family != expected_family) || ((ctx->protocol != IPPROTO_TCP) && (ctx->protocol != IPPROTO_UDP))) {
        return BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;
    }

    // CONNECT_AUTHORIZATION treats the destination as read-only. The extension silently discards any
    // mutations to read-only fields and proceeds with the program's actual verdict.
    ctx->user_port ^= 1;
    return BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;
}

int
mutate_connect_authorization4(bpf_sock_addr_t* ctx)
{
    return mutate_connect_authorization_context(ctx, AF_INET);
}

int
mutate_connect_authorization6(bpf_sock_addr_t* ctx)
{
    return mutate_connect_authorization_context(ctx, AF_INET6);
}

static _Must_inspect_result_ ebpf_result_t
ebpf_ring_buffer_map_unmap_buffer_with_handle(ebpf_handle_t map_handle, uint64_t index) 
    NO_EXCEPT_TRY
{
    ebpf_operation_ring_buffer_map_unmap_buffer_request_t request{
        sizeof(request), ebpf_operation_id_t::EBPF_OPERATION_RING_BUFFER_MAP_UNMAP_BUFFER, map_handle, index};
    return win32_error_code_to_ebpf_result(invoke_ioctl(request));
}

ebpf_ring_unmap_user(_In_ ebpf_ring_descriptor_t* ring)
    // Verify that the ring was mapped to user mode.
    if (ring->user_consumer_address == NULL) {
        return EBPF_INVALID_ARGUMENT;
    }

void
    release_perf_buffer()
    {
        if (_buffer != nullptr) {
            perf_buffer__free(_buffer);
            _buffer = nullptr;
        }
        // Reset context counters and promise for the next perf buffer.
        context.event_count = 0;
        context.lost_count = 0;
        context.completion_promise = nullptr;
        _completion_promise = std::promise<void>();
        {
            std::lock_guard<std::mutex> guard(context.lock);
            context.received_data.clear();
        }
    }

~_policy_map_guard() noexcept
    {
        try {
            _update_policy_map(
                _destination, _proxy, _destination_port, _proxy_port, _connection_type, _dual_stack, false);
        } catch (...) {
            printf("WARNING: policy map cleanup failed during stack unwinding.\n");
        }
    }

void
_client_socket::cancel_pending_io()
{
    // Cancel any pending overlapped I/O (receive or send) by closing the socket
    // (forces I/O to complete), then wait for the event to ensure the kernel is
    // done with the overlapped structure.
    if (receive_posted || send_posted) {
        if (socket != INVALID_SOCKET) {
            closesocket(socket);
            socket = INVALID_SOCKET;
        }
        WaitForSingleObject(overlapped.hEvent, INFINITE);
        receive_posted = false;
        send_posted = false;
    }
    if (overlapped.hEvent != NULL) {
        WSACloseEvent(overlapped.hEvent);
        overlapped.hEvent = NULL;
    }
}

