static void
_update_authorization_policy_map(
    _In_ const sockaddr_storage& destination, uint16_t destination_port, uint32_t verdict, bool dual_stack, bool add)
{
    bpf_map* auth_map = bpf_object__find_map_by_name(_globals.bpf_object.get(), "authorization_policy_map");
    SAFE_REQUIRE(auth_map != nullptr);

    fd_t map_fd = bpf_map__fd(auth_map);

    destination_entry_key_t key = {0};
    destination_entry_value_t value = {.verdict = verdict};

    if (_globals.family == AF_INET && dual_stack) {
        struct sockaddr_in6* v6_destination = (struct sockaddr_in6*)&destination;
        INET_SET_ADDRESS(
            AF_INET6, (PUCHAR)&key.destination_ip, IN6_GET_ADDR_V4MAPPED((IN6_ADDR*)&v6_destination->sin6_addr));
    } else {
        INET_SET_ADDRESS(_globals.family, (PUCHAR)&key.destination_ip, INETADDR_ADDRESS((PSOCKADDR)&destination));
    }
    key.protocol = _get_ip_proto_from_connection_type(_globals.connection_type);
    key.destination_port = htons(destination_port);

    if (add) {
        SAFE_REQUIRE(bpf_map_update_elem(map_fd, &key, &value, 0) == 0);
    } else {
        SAFE_REQUIRE(bpf_map_delete_elem(map_fd, &key) == 0);
    }
}

void
redirect_then_auth_reject_test(
    bool dual_stack, _Inout_ sockaddr_storage& destination, _In_ const sockaddr_storage& proxy)
{
    client_socket_t* sender_socket = nullptr;
    get_client_socket(dual_stack, &sender_socket);

    // Set up redirect policy to allow and redirect.
    _update_policy_map(
        destination, proxy, _globals.destination_port, _globals.proxy_port, _globals.connection_type, dual_stack, true);

    // Set up authorization policy to REJECT the proxy (post-redirect) destination.
    _update_authorization_policy_map(proxy, _globals.proxy_port, BPF_SOCK_ADDR_VERDICT_REJECT, dual_stack, true);

    // Connection should fail because authorization rejects after redirect.
    {
        impersonation_helper_t helper(_globals.user_type);
        sender_socket->send_message_to_remote_host(CLIENT_MESSAGE, destination, _globals.destination_port);
        sender_socket->complete_async_send(1000, expected_result_t::FAILURE);
        sender_socket->post_async_receive(true);
        sender_socket->complete_async_receive(1000, true);
    }

    // Clean up policy maps.
    _update_authorization_policy_map(proxy, _globals.proxy_port, 0, dual_stack, false);
    _update_policy_map(
        destination,
        proxy,
        _globals.destination_port,
        _globals.proxy_port,
        _globals.connection_type,
        dual_stack,
        false);

    delete sender_socket;
}

void
redirect_then_auth_allow_test(
    bool dual_stack, _Inout_ sockaddr_storage& destination, _In_ const sockaddr_storage& proxy)
{
    client_socket_t* sender_socket = nullptr;
    get_client_socket(dual_stack, &sender_socket);

    // Set up redirect policy to allow and redirect.
    _update_policy_map(
        destination, proxy, _globals.destination_port, _globals.proxy_port, _globals.connection_type, dual_stack, true);

    // Set up authorization policy to ALLOW the proxy (post-redirect) destination.
    _update_authorization_policy_map(proxy, _globals.proxy_port, BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT, dual_stack, true);

    // Connection should succeed: redirect then authorized.
    {
        impersonation_helper_t helper(_globals.user_type);
        sender_socket->send_message_to_remote_host(CLIENT_MESSAGE, destination, _globals.destination_port);
        sender_socket->complete_async_send(1000, expected_result_t::SUCCESS);
        sender_socket->post_async_receive();
        sender_socket->complete_async_receive(2000, false);
    }

    // Clean up.
    _update_authorization_policy_map(proxy, _globals.proxy_port, 0, dual_stack, false);
    _update_policy_map(
        destination,
        proxy,
        _globals.destination_port,
        _globals.proxy_port,
        _globals.connection_type,
        dual_stack,
        false);

    delete sender_socket;
}

int
count_tcp_connect_authorization6(bpf_sock_addr_t* ctx)
{
    int retval = BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;

    if (ctx->protocol != IPPROTO_TCP) {
        // Allow non-TCP connections.
        retval = BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;
        goto exit;
    }

    // IP address, port #s in the context are in network byte order.
    if (ctx->user_port != ntohs(remote_port)) {
        // Allow connections to other ports.
        retval = BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;
        goto exit;
    }

    // Get the current counter value (create new entry if not present).
    uint16_t key = remote_port;
    uint64_t value = 0;
    uint64_t* count = bpf_map_lookup_elem(&connect_authorization6_count_map, &key);
    if (!count) {
        value = 1;
        bpf_map_update_elem(&connect_authorization6_count_map, &key, &value, BPF_ANY);
    } else {
        value = *count + 1;
        bpf_map_update_elem(&connect_authorization6_count_map, &key, &value, BPF_EXIST);
    }

    // Example authorization logic: block every 3rd connection.
    if (value % 3 == 0) {
        retval = BPF_SOCK_ADDR_VERDICT_REJECT;
    } else {
        retval = BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;
    }

exit:
    return retval;
}

int
connect_authorization4(bpf_sock_addr_t* ctx)
{
    return authorize_v4(ctx, &egress_connection_policy_map);
}

int
connect_authorization6(bpf_sock_addr_t* ctx)
{
    return authorize_v6(ctx, &egress_connection_policy_map);
}

__inline void
initialize_destination_entry_v4(bpf_sock_addr_t* ctx, destination_entry_key_t* entry)
{
    entry->destination_ip.ipv4 = ctx->user_ip4;
    entry->destination_port = ctx->user_port;
    entry->protocol = ctx->protocol;
}

__inline void
initialize_destination_entry_v6(bpf_sock_addr_t* ctx, destination_entry_key_t* entry)
{
    // Copy the IPv6 address. Note this has a design flaw for scoped IPv6 addresses
    // where the scope id or interface is not provided, so the policy can match the
    // wrong address.
    __builtin_memcpy(entry->destination_ip.ipv6, ctx->user_ip6, sizeof(ctx->user_ip6));
    entry->destination_port = ctx->user_port;
    entry->protocol = ctx->protocol;
}

__inline int
authorize_v4(bpf_sock_addr_t* ctx)
{
    destination_entry_key_t entry = {0};

    if (((ctx->protocol != IPPROTO_TCP) && (ctx->protocol != IPPROTO_UDP)) || (ctx->family != AF_INET)) {
        return BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;
    }

    initialize_destination_entry_v4(ctx, &entry);

    destination_entry_value_t* auth_policy = bpf_map_lookup_elem(&authorization_policy_map, &entry);
    if (auth_policy != NULL) {
        return auth_policy->verdict;
    }

    // No policy entry means allow by default.
    return BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;
}

__inline int
authorize_v6(bpf_sock_addr_t* ctx)
{
    destination_entry_key_t entry = {0};

    if (((ctx->protocol != IPPROTO_TCP) && (ctx->protocol != IPPROTO_UDP)) || (ctx->family != AF_INET6)) {
        return BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;
    }

    initialize_destination_entry_v6(ctx, &entry);

    destination_entry_value_t* auth_policy = bpf_map_lookup_elem(&authorization_policy_map, &entry);
    if (auth_policy != NULL) {
        return auth_policy->verdict;
    }

    return BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;
}

int
connect_authorization4(bpf_sock_addr_t* ctx)
{
    return authorize_v4(ctx);
}

int
connect_authorization6(bpf_sock_addr_t* ctx)
{
    return authorize_v6(ctx);
}

int
test_sock_addr_helpers_v4(bpf_sock_addr_t* ctx)
{
    int retval = BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;

    // Only process TCP connections for testing.
    if (ctx->protocol != IPPROTO_TCP) {
        goto exit;
    }

    // Generate a unique connection ID based on address and port.
    uint32_t connection_id = ctx->user_ip4 ^ (ctx->user_port << 16);

    // Retrieve network context using the struct-based helper.
    bpf_sock_addr_network_context_t net_ctx = {};
    if (bpf_sock_addr_get_network_context(ctx, &net_ctx, sizeof(net_ctx)) < 0) {
        // Network context unavailable; fail closed.
        retval = BPF_SOCK_ADDR_VERDICT_REJECT;
        goto exit;
    }

    // Store results for verification.
    bpf_map_update_elem(&network_context_map, &connection_id, &net_ctx, BPF_ANY);

    // Update connection counter.
    uint32_t counter_key = 1;
    uint64_t count = 1;
    uint64_t* existing_count = bpf_map_lookup_elem(&connection_count_map, &counter_key);
    if (existing_count) {
        count = *existing_count + 1;
    }
    bpf_map_update_elem(&connection_count_map, &counter_key, &count, BPF_ANY);

exit:
    return retval;
}

int
test_sock_addr_helpers_v6(bpf_sock_addr_t* ctx)
{
    int retval = BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;

    // Only process TCP connections for testing.
    if (ctx->protocol != IPPROTO_TCP) {
        goto exit;
    }

    // Generate a unique connection ID for IPv6 (simplified hash).
    uint32_t connection_id = (ctx->user_ip6[0] ^ ctx->user_ip6[3]) ^ (ctx->user_port << 16);

    // Retrieve network context using the struct-based helper.
    bpf_sock_addr_network_context_t net_ctx = {};
    if (bpf_sock_addr_get_network_context(ctx, &net_ctx, sizeof(net_ctx)) < 0) {
        retval = BPF_SOCK_ADDR_VERDICT_REJECT;
        goto exit;
    }

    // Store results for verification.
    bpf_map_update_elem(&network_context_map, &connection_id, &net_ctx, BPF_ANY);

    // Update connection counter.
    uint32_t counter_key = 2; // Different key for IPv6.
    uint64_t count = 1;
    uint64_t* existing_count = bpf_map_lookup_elem(&connection_count_map, &counter_key);
    if (existing_count) {
        count = *existing_count + 1;
    }
    bpf_map_update_elem(&connection_count_map, &counter_key, &count, BPF_ANY);

exit:
    return retval;
}

int
conditional_authorization_v4(bpf_sock_addr_t* ctx)
{
    int retval = BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;

    if (ctx->protocol != IPPROTO_TCP) {
        goto exit;
    }

    bpf_sock_addr_network_context_t net_ctx = {};
    if (bpf_sock_addr_get_network_context(ctx, &net_ctx, sizeof(net_ctx)) < 0) {
        retval = BPF_SOCK_ADDR_VERDICT_REJECT;
        goto exit;
    }

    // 1. Block connections through certain interface types.
    if (net_ctx.interface_type == IF_TYPE_PPP) {
        retval = BPF_SOCK_ADDR_VERDICT_REJECT;
        goto exit;
    }

    // 2. Log connections through tunnels.
    if (net_ctx.tunnel_type != 0) {
        uint32_t tunnel_key = 100;
        uint64_t tunnel_count = 1;
        uint64_t* existing_tunnel_count = bpf_map_lookup_elem(&connection_count_map, &tunnel_key);
        if (existing_tunnel_count) {
            tunnel_count = *existing_tunnel_count + 1;
        }
        bpf_map_update_elem(&connection_count_map, &tunnel_key, &tunnel_count, BPF_ANY);
    }

exit:
    return retval;
}

int
test_recv_accept_helpers_v4(bpf_sock_addr_t* ctx)
{
    int retval = BPF_SOCK_ADDR_VERDICT_PROCEED_SOFT;

    if (ctx->protocol != IPPROTO_TCP) {
        goto exit;
    }

    uint32_t connection_id = ctx->user_ip4 ^ (ctx->user_port << 16);

    bpf_sock_addr_network_context_t net_ctx = {};
    if (bpf_sock_addr_get_network_context(ctx, &net_ctx, sizeof(net_ctx)) < 0) {
        retval = BPF_SOCK_ADDR_VERDICT_REJECT;
        goto exit;
    }

    bpf_map_update_elem(&network_context_map, &connection_id, &net_ctx, BPF_ANY);

    uint32_t counter_key = 3; // Different key for recv_accept.
    uint64_t count = 1;
    uint64_t* existing_count = bpf_map_lookup_elem(&connection_count_map, &counter_key);
    if (existing_count) {
        count = *existing_count + 1;
    }
    bpf_map_update_elem(&connection_count_map, &counter_key, &count, BPF_ANY);

exit:
    return retval;
}

void
helper_functions_validation_test(
    ADDRESS_FAMILY address_family,
    _Inout_ client_socket_t& sender_socket,
    _Inout_ receiver_socket_t& receiver_socket,
    uint32_t protocol)
{
    UNREFERENCED_PARAMETER(protocol);

    native_module_helper_t helper;
    helper.initialize("cgroup_sock_addr_helpers", _is_main_thread);

    struct bpf_object* object = bpf_object__open(helper.get_file_name().c_str());
    bpf_object_ptr object_ptr(object);

    SAFE_REQUIRE(object != nullptr);
    // Load the programs.
    SAFE_REQUIRE(bpf_object__load(object) == 0);

    const char* connect_authorization_program_name =
        (address_family == AF_INET) ? "test_sock_addr_helpers_v4" : "test_sock_addr_helpers_v6";
    bpf_program* connect_authorization_program =
        bpf_object__find_program_by_name(object, connect_authorization_program_name);
    SAFE_REQUIRE(connect_authorization_program != nullptr);

    // Get maps to retrieve helper function results.
    bpf_map* network_context_map = bpf_object__find_map_by_name(object, "network_context_map");
    SAFE_REQUIRE(network_context_map != nullptr);
    bpf_map* connection_count_map = bpf_object__find_map_by_name(object, "connection_count_map");
    SAFE_REQUIRE(connection_count_map != nullptr);

    // Attach the connect authorization program at the appropriate CONNECT_AUTHORIZATION layer.
    bpf_attach_type connect_authorization_attach_type =
        (address_family == AF_INET) ? BPF_CGROUP_INET4_CONNECT_AUTHORIZATION : BPF_CGROUP_INET6_CONNECT_AUTHORIZATION;
    int result = bpf_prog_attach(
        bpf_program__fd(const_cast<const bpf_program*>(connect_authorization_program)),
        0,
        connect_authorization_attach_type,
        0);
    SAFE_REQUIRE(result == 0);

    // Post an asynchronous receive on the receiver socket.
    receiver_socket.post_async_receive();

    // Send message to trigger the CONNECT_AUTHORIZATION program.
    const char* message = CLIENT_MESSAGE;
    sockaddr_storage destination_address{};
    if (address_family == AF_INET) {
        IN6ADDR_SETV4MAPPED((PSOCKADDR_IN6)&destination_address, &in4addr_loopback, scopeid_unspecified, 0);
    } else {
        IN6ADDR_SETLOOPBACK((PSOCKADDR_IN6)&destination_address);
    }
    sender_socket.send_message_to_remote_host(message, destination_address, SOCKET_TEST_PORT);

    // Complete the connection to ensure CONNECT_AUTHORIZATION program was invoked.
    receiver_socket.complete_async_receive();

    // Calculate connection ID (same as in the eBPF program).
    uint32_t connection_id = 0;
    if (address_family == AF_INET) {
        connection_id = htonl(INADDR_LOOPBACK) ^ (htons(SOCKET_TEST_PORT) << 16);
    } else {
        // For IPv6, use simplified hash based on loopback address.
        // Must use 32-bit dwords to match the eBPF program's user_ip6[0] ^ user_ip6[3].
        const uint32_t* ip6_dwords = reinterpret_cast<const uint32_t*>(&in6addr_loopback);
        connection_id = (ip6_dwords[0] ^ ip6_dwords[3]) ^ (htons(SOCKET_TEST_PORT) << 16);
    }

    // Validate that the network context helper returned reasonable values.
    bpf_sock_addr_network_context_t net_ctx = {0};
    result = bpf_map_lookup_elem(bpf_map__fd(network_context_map), &connection_id, &net_ctx);
    SAFE_REQUIRE(result == 0);
    printf(
        "Network context - Version: %u, Interface: %u, Tunnel: %u, Next-hop: %llu, SubInterface: %u\n",
        net_ctx.version,
        net_ctx.interface_type,
        net_ctx.tunnel_type,
        net_ctx.next_hop_interface_luid,
        net_ctx.sub_interface_index);

    // Version should be 1.
    SAFE_REQUIRE(net_ctx.version == BPF_SOCK_ADDR_NETWORK_CONTEXT_VERSION);

    // Interface type should be a valid IANA-assigned value or 0 (unspecified).
    bool valid_interface_type =
        (net_ctx.interface_type == 0 || net_ctx.interface_type == IF_TYPE_ETHERNET_CSMACD ||
         net_ctx.interface_type == IF_TYPE_SOFTWARE_LOOPBACK || net_ctx.interface_type == IF_TYPE_IEEE80211 ||
         net_ctx.interface_type == IF_TYPE_TUNNEL);
    SAFE_REQUIRE(valid_interface_type);

    // Tunnel type should be TUNNEL_TYPE_NONE (no tunnel) or a valid IANA tunnel type.
    bool valid_tunnel_type =
        (net_ctx.tunnel_type == TUNNEL_TYPE_NONE || net_ctx.tunnel_type == TUNNEL_TYPE_OTHER ||
         net_ctx.tunnel_type == TUNNEL_TYPE_DIRECT || net_ctx.tunnel_type == TUNNEL_TYPE_6TO4 ||
         net_ctx.tunnel_type == TUNNEL_TYPE_ISATAP || net_ctx.tunnel_type == TUNNEL_TYPE_TEREDO ||
         net_ctx.tunnel_type == TUNNEL_TYPE_IPHTTPS);
    SAFE_REQUIRE(valid_tunnel_type);

    // Validate that at least some network context is available.
    bool has_network_context = (net_ctx.interface_type != 0) ||
                               (net_ctx.next_hop_interface_luid != NET_IFLUID_UNSPECIFIED) ||
                               (net_ctx.sub_interface_index != NET_IFINDEX_UNSPECIFIED);
    SAFE_REQUIRE(has_network_context);

    printf(
        "Helper functions validation test completed successfully for %s\n",
        (address_family == AF_INET) ? "IPv4" : "IPv6");
}

static void
_test_oob_invalid_parameter_handler(
