static void
_test_custom_maps_invalid(ebpf_execution_type_t execution_type)
{
    _test_helper_end_to_end test_helper;
    test_helper.initialize();
    bpf_object_ptr unique_object;
    int result;
    const char* error_message = nullptr;
    fd_t program_fd;

    program_info_provider_t sock_addr_program_info;
    REQUIRE(sock_addr_program_info.initialize(EBPF_PROGRAM_TYPE_CGROUP_SOCK_ADDR) == EBPF_SUCCESS);

    const char* file_name =
        (execution_type == EBPF_EXECUTION_NATIVE) ? "custom_map_invalid_um.dll" : "custom_map_invalid.o";

    test_sample_map_provider_t sample_map_provider;
    REQUIRE(sample_map_provider.initialize(BPF_MAP_TYPE_SAMPLE_HASH_MAP, true) == EBPF_SUCCESS);

    // Try to load the program with invalid custom map usage.
    result =
        ebpf_program_load(file_name, BPF_PROG_TYPE_UNSPEC, execution_type, &unique_object, &program_fd, &error_message);
    if (error_message) {
        printf("ebpf_program_load failed with %s\n", error_message);
        ebpf_free((void*)error_message);
    }
    REQUIRE(result != 0);

    bpf_object__close(unique_object.release());
}

uint32_t
test_ioctl_map_write(ebpf_handle_t map_handle, _In_reads_bytes_(data_length) const void* data, size_t data_length)
{
    uint32_t error = ERROR_SUCCESS;
    ebpf_protocol_buffer_t request_buffer;
    ebpf_operation_map_write_data_request_t* request;

    if (map_handle == ebpf_handle_invalid || data == nullptr || data_length == 0) {
        return ERROR_INVALID_PARAMETER;
    }

    try {
        size_t buffer_size = offsetof(ebpf_operation_map_write_data_request_t, data) + data_length;
        request_buffer.resize(buffer_size);

        request = reinterpret_cast<ebpf_operation_map_write_data_request_t*>(request_buffer.data());
        request->header.length = static_cast<uint16_t>(request_buffer.size());
        request->header.id = EBPF_OPERATION_MAP_WRITE_DATA;
        request->map_handle = (uint64_t)map_handle;
        memcpy(request->data, data, data_length);

        error = invoke_ioctl(request_buffer);
    } catch (const std::bad_alloc&) {
        error = ERROR_NOT_ENOUGH_MEMORY;
    }

    return error;
}

uint32_t
test_ioctl_map_update_element_with_handle(
    ebpf_handle_t map_handle,
    uint32_t key_size,
    _In_reads_bytes_(key_size) const uint8_t* key,
    ebpf_handle_t value_handle)
{
    uint32_t error = ERROR_SUCCESS;
    ebpf_protocol_buffer_t request_buffer;
    ebpf_operation_map_update_element_with_handle_request_t* request;

    if (map_handle == ebpf_handle_invalid || key == nullptr || key_size == 0 || value_handle == ebpf_handle_invalid) {
        return ERROR_INVALID_PARAMETER;
    }

    try {
        size_t buffer_size = offsetof(ebpf_operation_map_update_element_with_handle_request_t, key) + key_size;
        request_buffer.resize(buffer_size);

        request = reinterpret_cast<ebpf_operation_map_update_element_with_handle_request_t*>(request_buffer.data());
        request->header.length = static_cast<uint16_t>(request_buffer.size());
        request->header.id = EBPF_OPERATION_MAP_UPDATE_ELEMENT_WITH_HANDLE;
        request->map_handle = (uint64_t)map_handle;
        request->value_handle = (uint64_t)value_handle;
        memcpy(request->key, key, key_size);

        error = invoke_ioctl(request_buffer);
    } catch (const std::bad_alloc&) {
        error = ERROR_NOT_ENOUGH_MEMORY;
    }

    return error;
}

static inline void
set_result(uint32_t result)
{
    uint32_t key = 0;
    bpf_map_update_elem(&result_map, &key, &result, 0);
}

static inline void
set_result_value(uint32_t result)
{
    uint32_t key = 0;
    bpf_map_update_elem(&result_value_map, &key, &result, 0);
}

static inline void*
get_sample_map(void)
{
    uint32_t key = 0;
    void* map = NULL;

    uint32_t* config = bpf_map_lookup_elem(&config_map, &key);
    if (!config) {
        return NULL;
    }
    if (*config == CONFIG_USE_HASH_MAP) {
        map = &sample_hash_map;
    }
    return map;
}

uint32_t
test_map_read_increment(sample_program_context_t* ctx)
{
    void* sample_map = get_sample_map();
    if (!sample_map) {
        set_result(OPERATION_FAILURE);
        return 0;
    }
    uint32_t key = 0;
    uint32_t* value = bpf_map_lookup_elem(sample_map, &key);
    if (value) {
        (*value)++;
    }
    set_result(value ? OPERATION_SUCCESS : OPERATION_FAILURE);
    return 0;
}

