static __forceinline uint64_t
_ebpf_epoch_get_published_epoch()
{
    // ebpf_interlocked_compare_exchange_int64() (implemented using InterlockedCompareExchange64) provides a
    // sequentially consistent atomic read.
    return (uint64_t)ebpf_interlocked_compare_exchange_int64(&_ebpf_epoch_published_current_epoch, 0, 0);
}

static void
_epoch_skew_test_work_item_callback(_Inout_ void* context)
{
    auto* callback_context = (epoch_skew_test_callback_context_t*)context;
    callback_context->callback_invoked->store(true, std::memory_order_release);
    if (callback_context->reader_active->load(std::memory_order_acquire)) {
        callback_context->callback_while_reader_active->store(true, std::memory_order_release);
    }
}

static void
_epoch_spin_test_work_item_callback(_Inout_ void* context)
{
    auto* callback_context = (epoch_spin_test_context_t*)context;
    if (callback_context->object != nullptr && callback_context->object_size != 0) {
        // The test uses VirtualAlloc'd objects and turns them into a guard page before freeing.
        // This makes an unsafe early reclamation much more likely to manifest as an access violation
        // (reader touches freed memory) instead of silently reading stale bytes from an allocator pool.
        DWORD old_protection = 0;
        (void)VirtualProtect(callback_context->object, callback_context->object_size, PAGE_NOACCESS, &old_protection);
        (void)VirtualFree(callback_context->object, 0, MEM_RELEASE);
    }
    callback_context->work_items_invoked->fetch_add(1, std::memory_order_relaxed);
    if (callback_context->reader_active->load(std::memory_order_acquire)) {
        callback_context->callbacks_while_reader_active->fetch_add(1, std::memory_order_relaxed);
    }
    delete callback_context;
}

static bool _try_get_environment_variable_u32(_In_z_ const char* name, _Out_ uint32_t* value)
{
    char buffer[64] = {0};
    DWORD length = GetEnvironmentVariableA(name, buffer, static_cast<DWORD>(sizeof(buffer)));
    if (length == 0 || length >= sizeof(buffer)) {
        return false;
    }

    char* end = nullptr;
    unsigned long parsed = std::strtoul(buffer, &end, 10);
    if (end == buffer) {
        return false;
    }

    *value = static_cast<uint32_t>(parsed);
    return true;
}

static bool
_environment_variable_equals(_In_z_ const char* name, _In_z_ const char* expected)
{
    char buffer[64] = {0};
    DWORD length = GetEnvironmentVariableA(name, buffer, static_cast<DWORD>(sizeof(buffer)));
    if (length == 0 || length >= sizeof(buffer)) {
        return false;
    }

    return _stricmp(buffer, expected) == 0;
}

static uint32_t
_get_epoch_spin_test_duration_seconds()
{
    uint32_t seconds = 0;
    if (_try_get_environment_variable_u32("EBPF_EPOCH_SPIN_TEST_SECONDS", &seconds) && seconds > 0) {
        return seconds;
    }

    // In CI, run longer: 120s for PR/manual runs, 600s for scheduled.
    if (_environment_variable_equals("GITHUB_ACTIONS", "true")) {
        if (_environment_variable_equals("GITHUB_EVENT_NAME", "schedule")) {
            return 600;
        }
        return 120;
    }

    // Keep local runs short by default.
    return 5;
}

static void
    _terminate_handler()
    {
        std::cerr << "std::terminate() invoked" << std::endl;
        RaiseException(STATUS_ASSERTION_FAILURE, 0, 0, NULL);
    }

static unique_handle
create_signal_event(const char* event_name)
{
    unique_handle event(CreateEventA(nullptr, TRUE, FALSE, event_name));
    if (!event) {
        std::cerr << "Failed to create event: " << event_name << ", error: " << GetLastError() << std::endl;
    } else {
        // If event already existed, reset it to ensure known initial state
        DWORD last_error = GetLastError();
        if (last_error == ERROR_ALREADY_EXISTS) {
            std::cout << "Event " << event_name << " already exists, resetting to non-signaled state" << std::endl;
            ResetEvent(event.get());
        }
    }
    return event;
}

static bool
wait_for_signal(HANDLE event, const char* signal_name, DWORD timeout_ms = 30000)
{
    DWORD result = WaitForSingleObject(event, timeout_ms);

    if (result == WAIT_OBJECT_0) {
        std::cout << "Received signal: " << signal_name << std::endl;
        // Reset for potential reuse
        ResetEvent(event);
        return true;
    } else if (result == WAIT_TIMEOUT) {
        std::cerr << "Timeout waiting for signal: " << signal_name << std::endl;
        return false;
    } else {
        std::cerr << "Error waiting for signal: " << signal_name << ", error: " << GetLastError() << std::endl;
        return false;
    }
}

static HANDLE
spawn_child_process(const std::string& mode, PROCESS_INFORMATION& pi)
{
    STARTUPINFOA si = {0};
    si.cb = sizeof(si);

    // Get the path to the helper executable (should be in the same directory as the controller)
    char exe_path[MAX_PATH];
    DWORD path_len = GetModuleFileNameA(nullptr, exe_path, MAX_PATH);
    if (path_len == 0 || path_len >= MAX_PATH) {
        std::cerr << "Failed to get module filename, error: " << GetLastError() << std::endl;
        return nullptr;
    }

    std::string exe_dir = exe_path;
    size_t last_slash = exe_dir.find_last_of("\\/");
    if (last_slash != std::string::npos) {
        exe_dir = exe_dir.substr(0, last_slash);
    }

    std::string helper_path = exe_dir + "\\ebpf_restart_test_helper.exe";
    std::string command_line = "\"" + helper_path + "\" " + mode;
    std::cout << "Spawning child process: " << command_line << std::endl;

    // CreateProcessA may modify the command line buffer, so we need a mutable copy
    std::vector<char> command_line_buffer(command_line.begin(), command_line.end());
    command_line_buffer.push_back('\0');

    if (!CreateProcessA(nullptr, command_line_buffer.data(), nullptr, nullptr, FALSE, 0, nullptr, nullptr, &si, &pi)) {
        std::cerr << "Failed to spawn child process, error: " << GetLastError() << std::endl;
        return nullptr;
    }

    std::cout << "Child process spawned with PID: " << pi.dwProcessId << std::endl;
    return pi.hProcess;
}

static DWORD
attempt_stop_ebpfcore()
{
    unique_sc_handle scm(OpenSCManager(nullptr, nullptr, SC_MANAGER_CONNECT));
    if (!scm) {
        DWORD error = GetLastError();
        std::cerr << "Failed to open SCM, error: " << error << std::endl;
        return error;
    }

    unique_sc_handle service(OpenServiceW(scm.get(), L"ebpfcore", SERVICE_STOP | SERVICE_QUERY_STATUS));
    if (!service) {
        DWORD error = GetLastError();
        std::cerr << "Failed to open ebpfcore service, error: " << error << std::endl;
        return error;
    }

    SERVICE_STATUS status;
    if (!ControlService(service.get(), SERVICE_CONTROL_STOP, &status)) {
        DWORD error = GetLastError();
        std::cout << "Failed to stop ebpfcore service, error: " << error << std::endl;
        return error;
    }

    // Wait for service to stop
    for (int i = 0; i < 10; i++) {
        if (!QueryServiceStatus(service.get(), &status)) {
            DWORD error = GetLastError();
            std::cerr << "Failed to query service status, error: " << error << std::endl;
            return error;
        }

        if (status.dwCurrentState == SERVICE_STOPPED) {
            std::cout << "ebpfcore service stopped successfully" << std::endl;
            return 0;
        }

        Sleep(500);
    }

    std::cerr << "Timeout waiting for ebpfcore service to stop" << std::endl;
    return ERROR_SERVICE_REQUEST_TIMEOUT;
}

static DWORD
start_ebpfcore()
{
    unique_sc_handle scm(OpenSCManager(nullptr, nullptr, SC_MANAGER_CONNECT));
    if (!scm) {
        DWORD error = GetLastError();
        std::cerr << "Failed to open SCM, error: " << error << std::endl;
        return error;
    }

    unique_sc_handle service(OpenServiceW(scm.get(), L"ebpfcore", SERVICE_START | SERVICE_QUERY_STATUS));
    if (!service) {
        DWORD error = GetLastError();
        std::cerr << "Failed to open ebpfcore service, error: " << error << std::endl;
        return error;
    }

    if (!StartService(service.get(), 0, nullptr)) {
        DWORD error = GetLastError();
        if (error != ERROR_SERVICE_ALREADY_RUNNING) {
            std::cerr << "Failed to start ebpfcore service, error: " << error << std::endl;
            return error;
        }
    }

    // Wait for service to start
    SERVICE_STATUS status;
    for (int i = 0; i < 10; i++) {
        if (!QueryServiceStatus(service.get(), &status)) {
            DWORD error = GetLastError();
            std::cerr << "Failed to query service status, error: " << error << std::endl;
            return error;
        }

        if (status.dwCurrentState == SERVICE_RUNNING) {
            std::cout << "ebpfcore service started successfully" << std::endl;
            return 0;
        }

        Sleep(500);
    }

    std::cerr << "Timeout waiting for ebpfcore service to start" << std::endl;
    return ERROR_SERVICE_REQUEST_TIMEOUT;
}

static void
signal_controller(const char* signal_name)
{
    // Open the pre-created event from the controller
    unique_handle event(OpenEventA(EVENT_MODIFY_STATE, FALSE, signal_name));
    if (!event) {
        std::cerr << "Failed to open event: " << signal_name << ", error: " << GetLastError() << std::endl;
        return;
    }
    if (!SetEvent(event.get())) {
        std::cerr << "Failed to set event: " << signal_name << ", error: " << GetLastError() << std::endl;
    }
}

static void
wait_for_controller()
{
    // Open the pre-created event from the controller
    unique_handle event(OpenEventA(SYNCHRONIZE, FALSE, SIGNAL_CONTROLLER_DONE));
    if (!event) {
        std::cerr << "Failed to open controller done event, error: " << GetLastError() << std::endl;
        return;
    }

    DWORD wait_result = WaitForSingleObject(event.get(), INFINITE);
    if (wait_result != WAIT_OBJECT_0) {
        std::cerr << "Error waiting for controller event, result: " << wait_result << ", error: " << GetLastError()
                  << std::endl;
    }
}

static int
create_test_map()
{
    // Create a simple array map
    return bpf_map_create(BPF_MAP_TYPE_ARRAY, nullptr, sizeof(uint32_t), sizeof(uint64_t), 10, nullptr);
}

static int
load_test_program(int& program_fd, bpf_object*& object_out)
{
    char* program_path_env_raw = nullptr;
    size_t program_path_len = 0;
    errno_t env_error = _dupenv_s(&program_path_env_raw, &program_path_len, "EBPF_TEST_PROGRAM_PATH");
    std::unique_ptr<char, decltype(&free)> program_path_env(program_path_env_raw, free);

    const char* program_path = (env_error == 0 && program_path_env != nullptr && program_path_env.get()[0] != '\0')
                                   ? program_path_env.get()
                                   : "cgroup_sock_addr.o";

    // Verify program path exists for optional program load.
    if (_access(program_path, 0) != 0) {
        std::cerr << "eBPF test program not found at path: " << program_path << std::endl;
        return -1;
    }

    struct bpf_program* program = nullptr;
    int result;

    // Try to open and load the program
    bpf_object_ptr object(bpf_object__open(program_path));
    if (!object) {
        std::cerr << "Failed to open program: " << program_path << std::endl;
        return -1;
    }

    result = bpf_object__load(object.get());
    if (result < 0) {
        std::cerr << "Failed to load program: " << program_path << ", error: " << result << std::endl;
        return result;
    }

    // Get the first program
    program = bpf_object__next_program(object.get(), nullptr);
    if (program == nullptr) {
        std::cerr << "Failed to get program from object" << std::endl;
        return -1;
    }

    program_fd = bpf_program__fd(program);
    if (program_fd < 0) {
        std::cerr << "Failed to get program fd" << std::endl;
        return -1;
    }

    // Keep the object alive for caller to manage.
    object_out = object.release();
    return 0;
}

static int
mode_open_handles()
{
    std::cout << "Mode: OPEN_HANDLES - Creating objects and keeping handles open" << std::endl;

    // Create a map
    unique_fd map_fd(create_test_map());
    if (map_fd.get() < 0) {
        std::cerr << "Failed to create map, error: " << map_fd.get() << std::endl;
        // Signal controller even on failure to avoid timeout
        signal_controller(SIGNAL_READY_HANDLES_OPEN);
        return 1;
    }

    std::cout << "Created map with fd: " << map_fd.get() << std::endl;

    // Try to load a program (optional - may not be available)
    int program_fd = -1;
    bpf_object* program_object_raw = nullptr;
    load_test_program(program_fd, program_object_raw);
    bpf_object_ptr program_object(program_object_raw);
    if (program_fd >= 0) {
        std::cout << "Loaded program with fd: " << program_fd << std::endl;
    }

    // Signal that we're ready with handles open
    signal_controller(SIGNAL_READY_HANDLES_OPEN);
    std::cout << "Signaled controller: handles are open" << std::endl;

    // Wait for controller to signal us to exit
    std::cout << "Waiting for controller signal..." << std::endl;
    wait_for_controller();

    std::cout << "Controller signaled, exiting..." << std::endl;
    return 0;
}

static int
mode_pin_objects()
{
    std::cout << "Mode: PIN_OBJECTS - Creating, pinning, and releasing objects" << std::endl;

    // First, try to unpin any existing objects from previous runs to make this idempotent
    ebpf_result_t unpin_result = ebpf_object_unpin(PIN_PATH_MAP);
    if (unpin_result == EBPF_SUCCESS) {
        std::cout << "Unpinned existing map from previous run" << std::endl;
    }
    unpin_result = ebpf_object_unpin(PIN_PATH_PROGRAM);
    if (unpin_result == EBPF_SUCCESS) {
        std::cout << "Unpinned existing program from previous run" << std::endl;
    }

    // Create a map
    unique_fd map_fd(create_test_map());
    if (map_fd.get() < 0) {
        std::cerr << "Failed to create map, error: " << map_fd.get() << std::endl;
        // Signal controller even on failure to avoid timeout
        signal_controller(SIGNAL_READY_PINNED_OBJECTS);
        return 1;
    }

    std::cout << "Created map with fd: " << map_fd.get() << std::endl;

    // Pin the map
    int result = bpf_obj_pin(map_fd.get(), PIN_PATH_MAP);
    if (result < 0) {
        std::cerr << "Failed to pin map, error: " << result << std::endl;
        // Signal controller even on failure to avoid timeout
        signal_controller(SIGNAL_READY_PINNED_OBJECTS);
        return 1;
    }

    // Release the map handle after pinning.
    map_fd.reset();

    std::cout << "Pinned map at: " << PIN_PATH_MAP << std::endl;

    // Try to load and pin a program (optional)
    int program_fd = -1;
    bpf_object* program_object_raw = nullptr;
    if (load_test_program(program_fd, program_object_raw) == 0 && program_fd >= 0) {
        bpf_object_ptr program_object(program_object_raw);
        unique_fd program_handle(program_fd);
        result = bpf_obj_pin(program_handle.get(), PIN_PATH_PROGRAM);
        if (result < 0) {
            std::cerr << "Failed to pin program, error: " << result << std::endl;
        } else {
            std::cout << "Pinned program at: " << PIN_PATH_PROGRAM << std::endl;
        }
    }
    std::cout << "Released handles" << std::endl;

    // Signal that we're ready with pinned objects
    signal_controller(SIGNAL_READY_PINNED_OBJECTS);
    std::cout << "Signaled controller: objects are pinned and handles released" << std::endl;

    // Exit immediately - pinned objects should survive
    return 0;
}

static int
mode_unpin_objects()
{
    std::cout << "Mode: UNPIN_OBJECTS - Unpinning objects" << std::endl;

    // Unpin the map
    ebpf_result_t result = ebpf_object_unpin(PIN_PATH_MAP);
    if (result != EBPF_SUCCESS) {
        std::cerr << "Failed to unpin map at " << PIN_PATH_MAP << ", error: " << result << std::endl;
        // Continue anyway to try unpinning program
    } else {
        std::cout << "Unpinned map at: " << PIN_PATH_MAP << std::endl;
    }

    // Unpin the program
    result = ebpf_object_unpin(PIN_PATH_PROGRAM);
    if (result != EBPF_SUCCESS) {
        std::cerr << "Failed to unpin program at " << PIN_PATH_PROGRAM << ", error: " << result << std::endl;
    } else {
        std::cout << "Unpinned program at: " << PIN_PATH_PROGRAM << std::endl;
    }

    std::cout << "Unpin operation completed" << std::endl;
    return 0;
}

int
main(int argc, char* argv[])
{
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <mode>" << std::endl;
        std::cerr << "Modes:" << std::endl;
        std::cerr << "  open-handles  : Create objects and keep handles open" << std::endl;
        std::cerr << "  pin-objects   : Create and pin objects, then release handles" << std::endl;
        std::cerr << "  unpin-objects : Unpin objects" << std::endl;
        return 1;
    }

    std::string mode_str = argv[1];
    OperationMode mode;

    if (mode_str == "open-handles") {
        mode = OperationMode::OPEN_HANDLES;
    } else if (mode_str == "pin-objects") {
        mode = OperationMode::PIN_OBJECTS;
    } else if (mode_str == "unpin-objects") {
        mode = OperationMode::UNPIN_OBJECTS;
    } else {
        std::cerr << "Unknown mode: " << mode_str << std::endl;
        return 1;
    }

    int result = 0;
    switch (mode) {
    case OperationMode::OPEN_HANDLES:
        result = mode_open_handles();
        break;
    case OperationMode::PIN_OBJECTS:
        result = mode_pin_objects();
        break;
    case OperationMode::UNPIN_OBJECTS:
        result = mode_unpin_objects();
        break;
    }

    return result;
}

static std::string
_normalize_verifier_error(std::string error)
{
    // The verifier may change section indices (e.g., bind/5 -> bind/11) across versions.
    static const std::regex section_index_regex(R"(in section ([^/\s]+)/\d+)");
    return std::regex_replace(error, section_index_regex, "in section $1/<n>");
}

static void
_mt_load_stress_test_with_restart_timing(
    ebpf_execution_type_t program_type, const test_control_info& test_control_info, bool start_restart_before_load)
{
    constexpr uint32_t OBJECT_TABLE_SIZE{64};
    std::vector<object_table_entry> object_table(OBJECT_TABLE_SIZE);
    for (uint32_t index = 0; auto& entry : object_table) {
        entry.available = true;
        entry.lock = std::make_unique<std::mutex>();
        entry.object.reset();
        entry.attach = !(index % 2) ? true : false;
        entry.index = index++;
        entry.reuse_count = 0;
        entry.tag = 0xC001DEA1;
    }

    // We have 3 types of threads, so we need (test_control_info.threads_count * 3) total threads.
    size_t total_threads = ((size_t)test_control_info.threads_count * 3);
    std::vector<thread_context> thread_context_table(
        total_threads, {{}, {}, false, {}, thread_role_type::ROLE_NOT_SET, 0, 0, 0, false, 0, 0, object_table});
    std::vector<std::thread> test_thread_table(total_threads);

    // Extension restart thread setup.
    std::vector<std::string> extension_names;
    std::vector<std::thread> extension_restart_thread_table;
    std::vector<thread_context> extension_restart_thread_context_table;

    // An incrementing 'compartment Id' to ensure that _each_ 'Attacher' thread gets a unique compartment id.
    uint32_t compartment_id{1};

    // Get the single program info - we only have one program in km tests.
    const auto& program_info = _test_program_info.begin();
    const auto& program_name = program_info->first;
    const auto& program_attribs = program_info->second;
    extension_names.push_back(program_attribs.extension_name);

    // Configure context for each thread.
    for (size_t i = 0; i < total_threads; i++) {
        // First, prepare the context for this thread.
        auto& context_entry = thread_context_table[i];
        context_entry.program_name = program_name;

        if (!(compartment_id % 3)) {
            context_entry.role = thread_role_type::DESTROYER;
        } else if (!(compartment_id % 2)) {
            context_entry.role = thread_role_type::ATTACHER;
        } else {
            context_entry.role = thread_role_type::CREATOR;
        }

        if (program_type == EBPF_EXECUTION_NATIVE) {
            context_entry.is_native_program = true;
            if (test_control_info.use_unique_native_programs && context_entry.role == thread_role_type::CREATOR) {
                // Create unique native programs for 'creator' threads only.
                context_entry.file_name = _make_unique_file_copy(program_attribs.native_file_name);
            } else {
                context_entry.file_name = program_attribs.native_file_name;
            }
        } else {
            context_entry.file_name = program_attribs.jit_file_name;
        }
        context_entry.thread_index = (uint32_t)i;
        context_entry.compartment_id = compartment_id++;
        context_entry.duration_minutes = test_control_info.duration_minutes;
        context_entry.extension_restart_enabled = test_control_info.extension_restart_enabled;
    }

    // Handle extension restart timing.
    if (test_control_info.extension_restart_enabled) {
        if (start_restart_before_load) {
            // Start extension restart immediately, then start load threads.
            LOG_INFO("Starting extension restart BEFORE program loading threads");
            configure_extension_restart(
                test_control_info,
                extension_names,
                extension_restart_thread_table,
                extension_restart_thread_context_table,
                object_table);
            // Small delay to ensure restart thread is running before we start load threads.
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
        }
    }

    // Now create the program loading threads.
    for (size_t i = 0; i < total_threads; i++) {
        auto& context_entry = thread_context_table[i];
        auto& thread_entry = test_thread_table[i];
        thread_entry = std::move(std::thread(_test_thread_function, std::ref(context_entry)));
    }

    if (test_control_info.extension_restart_enabled && !start_restart_before_load) {
        // Wait for programs to load, then start extension restart.
        LOG_INFO("Waiting for programs to load, then starting extension restart");
        std::this_thread::sleep_for(std::chrono::seconds(5)); // Give programs time to load and attach
        configure_extension_restart(
            test_control_info,
            extension_names,
            extension_restart_thread_table,
            extension_restart_thread_context_table,
            object_table);
    }

    wait_and_verify_test_threads(
        test_control_info,
        test_thread_table,
        thread_context_table,
        extension_restart_thread_table,
        extension_restart_thread_context_table);
}

static void
_mt_invoke_stress_test_multiple_programs(ebpf_execution_type_t program_type, const test_control_info& test_control_info)
{
    WSAData data{};
    auto error = WSAStartup(MAKEWORD(2, 2), &data);
    REQUIRE(error == 0);

    // For testing different programs per thread, create multiple copies of programs.
    constexpr uint32_t MAX_PROGRAM_COPIES = 4;

    size_t actual_threads = std::min((size_t)test_control_info.threads_count, (size_t)MAX_PROGRAM_COPIES);
    std::vector<object_table_entry> object_table(actual_threads);
    for (uint32_t index = 0; auto& entry : object_table) {
        entry.available = true;
        entry.lock = std::make_unique<std::mutex>();
        entry.object.reset();
        entry.attach = !(index % 2) ? true : false;
        entry.index = index++;
        entry.reuse_count = 0;
        entry.tag = 0xC001DEA1;
    }

    std::vector<thread_context> thread_context_table(
        actual_threads, {{}, {}, false, {}, thread_role_type::ROLE_NOT_SET, 0, 0, 0, false, 0, 0, object_table});
    std::vector<std::thread> test_thread_table(actual_threads);

    for (uint32_t i = 0; i < actual_threads; i++) {
        // First, prepare the context for this thread.
        auto& context_entry = thread_context_table[i];

        if (program_type == EBPF_EXECUTION_NATIVE) {
            // For native programs, create unique file copies so each thread has a different program.
            context_entry.file_name = _make_unique_file_copy("cgroup_sock_addr.sys");
            context_entry.is_native_program = true;
        } else {
            // For JIT programs, all threads can load the same file (but get different instances).
            context_entry.file_name = "cgroup_sock_addr.o";
            context_entry.is_native_program = false;
        }

        context_entry.program_name = "cgroup_sock_addr";
        context_entry.role = thread_role_type::CREATOR; // All threads are creators for this test
        context_entry.thread_index = i;
        context_entry.compartment_id = i + 1; // Unique compartment IDs
        context_entry.duration_minutes = test_control_info.duration_minutes;
        context_entry.extension_restart_enabled = test_control_info.extension_restart_enabled;
    }

    // Now create all the threads after context setup is complete.
    for (uint32_t i = 0; i < actual_threads; i++) {
        auto& context_entry = thread_context_table[i];
        auto& thread_entry = test_thread_table[i];
        thread_entry = std::move(std::thread(_test_thread_function, std::ref(context_entry)));
    }

    // If requested, start the 'extension stop-and-restart' thread for extension for this program type.
    std::vector<std::string> extension_names = {"netebpfext"};
    std::vector<std::thread> extension_restart_thread_table;
    std::vector<thread_context> extension_restart_thread_context_table;
    if (test_control_info.extension_restart_enabled) {
        configure_extension_restart(
            test_control_info,
            extension_names,
            extension_restart_thread_table,
            extension_restart_thread_context_table,
            object_table);
    }

    wait_and_verify_test_threads(
        test_control_info,
        test_thread_table,
        thread_context_table,
        extension_restart_thread_table,
        extension_restart_thread_context_table);
}

int main()
{

    /* Enter the ThreadX kernel.  */
    tx_kernel_enter();
}

void    tx_application_define(void *first_unused_memory)
{

CHAR    *pointer = TX_NULL;


    /* Create a byte memory pool from which to allocate the thread stacks.  */
    tx_byte_pool_create(&byte_pool_0, "byte pool 0", memory_area, DEMO_BYTE_POOL_SIZE);

    /* Put system definition stuff in here, e.g. thread creates and other assorted
       create information.  */

    /* Allocate the stack for thread 0.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    /* Create the main thread.  */
    tx_thread_create(&thread_0, "thread 0", thread_0_entry, 0,
            pointer, DEMO_STACK_SIZE,
            1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);


    /* Allocate the stack for thread 1.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    /* Create threads 1 and 2. These threads pass information through a ThreadX
       message queue.  It is also interesting to note that these threads have a time
       slice.  */
    tx_thread_create(&thread_1, "thread 1", thread_1_entry, 1,
            pointer, DEMO_STACK_SIZE,
            16, 16, 4, TX_AUTO_START);

    /* Allocate the stack for thread 2.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    tx_thread_create(&thread_2, "thread 2", thread_2_entry, 2,
            pointer, DEMO_STACK_SIZE,
            16, 16, 4, TX_AUTO_START);

    /* Allocate the stack for thread 3.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    /* Create threads 3 and 4.  These threads compete for a ThreadX counting semaphore.
       An interesting thing here is that both threads share the same instruction area.  */
    tx_thread_create(&thread_3, "thread 3", thread_3_and_4_entry, 3,
            pointer, DEMO_STACK_SIZE,
            8, 8, TX_NO_TIME_SLICE, TX_AUTO_START);

    /* Allocate the stack for thread 4.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    tx_thread_create(&thread_4, "thread 4", thread_3_and_4_entry, 4,
            pointer, DEMO_STACK_SIZE,
            8, 8, TX_NO_TIME_SLICE, TX_AUTO_START);

    /* Allocate the stack for thread 5.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    /* Create thread 5.  This thread simply pends on an event flag which will be set
       by thread_0.  */
    tx_thread_create(&thread_5, "thread 5", thread_5_entry, 5,
            pointer, DEMO_STACK_SIZE,
            4, 4, TX_NO_TIME_SLICE, TX_AUTO_START);

    /* Allocate the stack for thread 6.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    /* Create threads 6 and 7.  These threads compete for a ThreadX mutex.  */
    tx_thread_create(&thread_6, "thread 6", thread_6_and_7_entry, 6,
            pointer, DEMO_STACK_SIZE,
            8, 8, TX_NO_TIME_SLICE, TX_AUTO_START);

    /* Allocate the stack for thread 7.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    tx_thread_create(&thread_7, "thread 7", thread_6_and_7_entry, 7,
            pointer, DEMO_STACK_SIZE,
            8, 8, TX_NO_TIME_SLICE, TX_AUTO_START);

    /* Allocate the message queue.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_QUEUE_SIZE*sizeof(ULONG), TX_NO_WAIT);

    /* Create the message queue shared by threads 1 and 2.  */
    tx_queue_create(&queue_0, "queue 0", TX_1_ULONG, pointer, DEMO_QUEUE_SIZE*sizeof(ULONG));

    /* Create the semaphore used by threads 3 and 4.  */
    tx_semaphore_create(&semaphore_0, "semaphore 0", 1);

    /* Create the event flags group used by threads 1 and 5.  */
    tx_event_flags_create(&event_flags_0, "event flags 0");

    /* Create the mutex used by thread 6 and 7 without priority inheritance.  */
    tx_mutex_create(&mutex_0, "mutex 0", TX_NO_INHERIT);

    /* Allocate the memory for a small block pool.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_BLOCK_POOL_SIZE, TX_NO_WAIT);

    /* Create a block memory pool to allocate a message buffer from.  */
    tx_block_pool_create(&block_pool_0, "block pool 0", sizeof(ULONG), pointer, DEMO_BLOCK_POOL_SIZE);

    /* Allocate a block and release the block memory.  */
    tx_block_allocate(&block_pool_0, (VOID **) &pointer, TX_NO_WAIT);

    /* Release the block back to the pool.  */
    tx_block_release(pointer);
}

void    thread_0_entry(ULONG thread_input)
{

UINT    status;


    /* This thread simply sits in while-forever-sleep loop.  */
    while(1)
    {

        /* Increment the thread counter.  */
        thread_0_counter++;

        /* Sleep for 10 ticks.  */
        tx_thread_sleep(10);

        /* Set event flag 0 to wakeup thread 5.  */
        status =  tx_event_flags_set(&event_flags_0, 0x1, TX_OR);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;
    }
}

void    thread_1_entry(ULONG thread_input)
{

UINT    status;


    /* This thread simply sends messages to a queue shared by thread 2.  */
    while(1)
    {

        /* Increment the thread counter.  */
        thread_1_counter++;

        /* Send message to queue 0.  */
        status =  tx_queue_send(&queue_0, &thread_1_messages_sent, TX_WAIT_FOREVER);

        /* Check completion status.  */
        if (status != TX_SUCCESS)
            break;

        /* Increment the message sent.  */
        thread_1_messages_sent++;
    }
}

void    thread_2_entry(ULONG thread_input)
{

ULONG   received_message;
UINT    status;

    /* This thread retrieves messages placed on the queue by thread 1.  */
    while(1)
    {

        /* Increment the thread counter.  */
        thread_2_counter++;

        /* Retrieve a message from the queue.  */
        status = tx_queue_receive(&queue_0, &received_message, TX_WAIT_FOREVER);

        /* Check completion status and make sure the message is what we
           expected.  */
        if ((status != TX_SUCCESS) || (received_message != thread_2_messages_received))
            break;

        /* Otherwise, all is okay.  Increment the received message count.  */
        thread_2_messages_received++;
    }
}

void    thread_3_and_4_entry(ULONG thread_input)
{

UINT    status;


    /* This function is executed from thread 3 and thread 4.  As the loop
       below shows, these function compete for ownership of semaphore_0.  */
    while(1)
    {

        /* Increment the thread counter.  */
        if (thread_input == 3)
            thread_3_counter++;
        else
            thread_4_counter++;

        /* Get the semaphore with suspension.  */
        status =  tx_semaphore_get(&semaphore_0, TX_WAIT_FOREVER);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;

        /* Sleep for 2 ticks to hold the semaphore.  */
        tx_thread_sleep(2);

        /* Release the semaphore.  */
        status =  tx_semaphore_put(&semaphore_0);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;
    }
}

void    thread_5_entry(ULONG thread_input)
{

UINT    status;
ULONG   actual_flags;


    /* This thread simply waits for an event in a forever loop.  */
    while(1)
    {

        /* Increment the thread counter.  */
        thread_5_counter++;

        /* Wait for event flag 0.  */
        status =  tx_event_flags_get(&event_flags_0, 0x1, TX_OR_CLEAR,
                                                &actual_flags, TX_WAIT_FOREVER);

        /* Check status.  */
        if ((status != TX_SUCCESS) || (actual_flags != 0x1))
            break;
    }
}

void    thread_6_and_7_entry(ULONG thread_input)
{

UINT    status;


    /* This function is executed from thread 6 and thread 7.  As the loop
       below shows, these function compete for ownership of mutex_0.  */
    while(1)
    {

        /* Increment the thread counter.  */
        if (thread_input == 6)
            thread_6_counter++;
        else
            thread_7_counter++;

        /* Get the mutex with suspension.  */
        status =  tx_mutex_get(&mutex_0, TX_WAIT_FOREVER);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;

        /* Get the mutex again with suspension.  This shows
           that an owning thread may retrieve the mutex it
           owns multiple times.  */
        status =  tx_mutex_get(&mutex_0, TX_WAIT_FOREVER);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;

        /* Sleep for 2 ticks to hold the mutex.  */
        tx_thread_sleep(2);

        /* Release the mutex.  */
        status =  tx_mutex_put(&mutex_0);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;

        /* Release the mutex again.  This will actually
           release ownership since it was obtained twice.  */
        status =  tx_mutex_put(&mutex_0);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;
    }
}

