atic DWORD WINAPI  _tx_win32_timer_thread_entry(LPVOID thread_input)
{
    TX_PARAMETER_NOT_USED(thread_input);

    while (1)
    {
        _tx_win32_wait_for_timer_object();
        _tx_win32_timer_interrupt();
        _tx_win32_timer_start();
    }
}

ID  _tx_win32_timer_interrupt(VOID)
{
    _tx_thread_context_save();
#if defined(CTEST) || defined(BATCH_TEST)
    test_interrupt_dispatch();
#if (TX_WIN32_ISR_PERIODIC < TX_TIMER_PERIODIC)
    _tx_win32_timer_tick_process();
#else
    _tx_timer_interrupt();
#endif
#else
    _tx_timer_interrupt();
#endif
    _tx_thread_context_restore();
}

atic VOID  _tx_win32_timer_tick_process(VOID)
{
    if (test_isr_dispatch != TX_NULL)
    {
        if (_tx_win32_timer_fast_active == TX_FALSE)
        {
            _tx_win32_timer_fast_active =  TX_TRUE;
            _tx_win32_timer_fast_count =   0U;
        }
        else
        {
            _tx_win32_timer_fast_count++;
            if (_tx_win32_timer_fast_count < TX_WIN32_TIMER_INTERRUPTS_PER_TICK)
            {
                return;
            }

            _tx_win32_timer_fast_count =  0U;
        }
    }
    else
    {
        _tx_win32_timer_fast_active =  TX_FALSE;
        _tx_win32_timer_fast_count =   0U;
    }

    _tx_timer_interrupt();
}
#

atic VOID  _tx_win32_timer_start(VOID)
{
LARGE_INTEGER   due_time;
LONGLONG        timer_period;

#if (defined(CTEST) || defined(BATCH_TEST)) && (TX_WIN32_ISR_PERIODIC < TX_TIMER_PERIODIC)
    if (test_isr_dispatch != TX_NULL)
    {
        timer_period =  (LONGLONG) TX_WIN32_ISR_PERIODIC;
    }
    else
#endif
    {
        timer_period =  (LONGLONG) TX_TIMER_PERIODIC;
    }

    due_time.QuadPart =  -(timer_period * 10000LL);
#if (TX_WIN32_USE_HIGH_RESOLUTION_TIMER != 0)
    if (SetWaitableTimerEx(_tx_win32_timer_handle, &due_time, 0, NULL, NULL, NULL, 0) == 0)
#else
    if (SetWaitableTimer(_tx_win32_timer_handle, &due_time, 0, NULL, NULL, FALSE) == 0)
#endif
    {
        printf("ThreadX SMP Win64 error starting timer!\n");
        while (1)
        {
        }
    }
}

VOID  _tx_thread_context_restore(VOID)
{
TX_THREAD   *current_thread;
TX_THREAD   *execute_thread;

    _tx_win32_debug_entry_insert("CONTEXT_RESTORE", __FILE__, __LINE__);

    _tx_thread_system_state[0]--;
    current_thread =  _tx_thread_current_ptr[0];
    execute_thread =  _tx_thread_execute_ptr[0];

    if (_tx_thread_system_state[0] == 0UL)
    {
        if (current_thread != TX_NULL)
        {
            if ((_tx_thread_preempt_disable == 0U) && (current_thread != execute_thread))
            {
                /* If context_save skipped SuspendThread because the thread was spinning
                 * on the Win32 CS (suspension_type == 4), suspend it now.  The ISR still
                 * holds the CS so the spinning thread cannot make forward progress, making
                 * SuspendThread safe to call here.  mutex_access remains TRUE; the thread
                 * will clear it naturally when it acquires the CS after being resumed. */
                if (current_thread -> tx_thread_win32_suspension_type == 4U)
                {
                    _tx_win32_thread_suspend(current_thread -> tx_thread_win32_thread_handle);
                }

                current_thread -> tx_thread_win32_suspension_type =  1U;

                if (_tx_timer_time_slice[0] != 0U)
                {
                    current_thread -> tx_thread_time_slice =  _tx_timer_time_slice[0];
                    _tx_timer_time_slice[0] =  0U;
                }

                _tx_thread_current_ptr[0] =  TX_NULL;
                _tx_win32_virtual_cores[0].tx_thread_smp_core_mapping_thread_handle = NULL;
                _tx_win32_virtual_cores[0].tx_thread_smp_core_mapping_thread_id =     0U;
                _tx_win32_virtual_cores[0].tx_thread_smp_core_mapping_thread =        TX_NULL;
                current_thread -> tx_thread_smp_core_control =  1U;

                /* Signal the scheduler to assign the next execute_thread.  Wait for the
                 * scheduler to signal isr_semaphore before returning: the scheduler holds
                 * the CS while waiting for start_ack from the execute_thread, which forces
                 * any thread calling TX_DISABLE to spin with mutex_access=TRUE while
                 * preempt_disable may be non-zero — exactly the window needed to satisfy
                 * the condition in tests such as wait_abort_and_isr. */
                _tx_win32_timer_waiting =  1U;
                MemoryBarrier();
                if (SetEvent(_tx_win32_scheduler_event) == 0)
                {
                    _tx_win32_system_error++;
                }

                if ((execute_thread != TX_NULL) &&
                    (execute_thread -> tx_thread_win32_suspension_type == 2U))
                {
                    _tx_win32_critical_section_release_all(&_tx_win32_critical_section);
                    _tx_win32_wait_for_isr_rendezvous();
                    _tx_win32_critical_section_obtain(&_tx_win32_critical_section);
                    _tx_win32_semaphore_reset(_tx_win32_isr_semaphore);
                }

                _tx_win32_timer_waiting =  0U;
            }
            else
            {
                if ((current_thread -> tx_thread_win32_suspension_type == 3U) ||
                    (current_thread -> tx_thread_win32_suspension_type == 4U))
                {
                    /* context_save did not call SuspendThread (type 3: preempt_disable≠0;
                     * type 4: thread was spinning on Win32 CS).  Clear the flag; do not
                     * issue a matching ResumeThread.  The thread will continue
                     * automatically once the ISR releases the Win32 critical section. */
                    current_thread -> tx_thread_win32_suspension_type =  0U;
                }
                else
                {
                    /* suspension_type 0: context_save called SuspendThread.  Always issue
                     * the matching ResumeThread here, regardless of mutex_access.
                     *
                     * Do NOT gate this on mutex_access: a thread on a different virtual core
                     * that happens to share the same stale TLS slot can momentarily stamp
                     * mutex_access = TRUE on this thread's struct while it is OS-suspended,
                     * which would otherwise cause context_restore to skip ResumeThread and
                     * leave the thread permanently suspended (deadlock). */
                    _tx_win32_thread_resume(current_thread -> tx_thread_win32_thread_handle);
                }
            }
        }
        else if (execute_thread != TX_NULL)
        {
            _tx_win32_timer_waiting =  1U;
            MemoryBarrier();
            if (SetEvent(_tx_win32_scheduler_event) == 0)
            {
                _tx_win32_system_error++;
            }

            if (execute_thread -> tx_thread_win32_suspension_type == 2U)
            {
                _tx_win32_critical_section_release_all(&_tx_win32_critical_section);
                _tx_win32_wait_for_isr_rendezvous();
                _tx_win32_critical_section_obtain(&_tx_win32_critical_section);
                _tx_win32_semaphore_reset(_tx_win32_isr_semaphore);
            }

            _tx_win32_timer_waiting =  0U;
        }
    }

    _tx_thread_smp_unprotect(TX_INT_ENABLE);
}

VOID  _tx_thread_context_save(VOID)
{
TX_THREAD   *thread_ptr;
UINT        interrupt_posture;

    interrupt_posture =  _tx_thread_smp_protect();
    if (interrupt_posture != TX_FALSE)
    {
        _tx_win32_system_error++;
    }

    _tx_win32_debug_entry_insert("CONTEXT_SAVE", __FILE__, __LINE__);

    thread_ptr =  _tx_thread_current_ptr[0];

    if ((thread_ptr != TX_NULL) && (_tx_thread_system_state[0] == 0UL))
    {
        if (thread_ptr -> tx_thread_win32_mutex_access == TX_FALSE)
        {
            if (_tx_thread_preempt_disable == 0U)
            {
                /* Thread is not in a preempt-disabled section; suspend it normally so
                 * context_restore can preempt it if a higher-priority thread is ready. */
                _tx_win32_thread_suspend(thread_ptr -> tx_thread_win32_thread_handle);
                _tx_win32_debug_entry_insert("CONTEXT_SAVE-suspend_thread", __FILE__, __LINE__);
            }
            else
            {
                /* Thread holds the SMP preemption lock (_tx_thread_preempt_disable != 0).
                 * Issuing SuspendThread/ResumeThread here would cost ~100 µs for zero
                 * benefit: context_restore will skip preemption anyway because
                 * _tx_thread_preempt_disable is still non-zero when it runs (the ISR
                 * cannot lower the count below its value at ISR entry while it holds the
                 * Win32 critical section).  Flag the thread so context_restore knows not
                 * to issue a matching ResumeThread.
                 *
                 * MISRA C 2012 Rule 10.3 deviation: suspension_type is a UINT field used
                 * as a small state tag; value 3 is a port-local extension of the existing
                 * 0/1/2 enumeration. */
                thread_ptr -> tx_thread_win32_suspension_type =  3U;
            }
        }
        else
        {
            /* Thread is spinning on the Win32 critical section (mutex_access TRUE).
             * It is blocked waiting to acquire the CS and cannot execute any protected
             * ThreadX code, so SuspendThread is unnecessary.  Tag the thread with
             * suspension_type 4 so context_restore handles it correctly:
             *   - no-preemption path: just clear the flag (no ResumeThread).
             *   - preemption path: call SuspendThread retrospectively and proceed.
             *
             * MISRA C 2012 Rule 10.3 deviation: value 4 is a port-local extension. */
            thread_ptr -> tx_thread_win32_suspension_type =  4U;
        }
    }

    _tx_thread_system_state[0]++;
}

UINT  _tx_thread_interrupt_disable(void)
{
UINT    previous_value;

    previous_value =  _tx_thread_interrupt_control(TX_INT_DISABLE);
    return(previous_value);
}

VOID  _tx_thread_interrupt_restore(UINT previous_posture)
{
    previous_posture =  _tx_thread_interrupt_control(previous_posture);
    TX_PARAMETER_NOT_USED(previous_posture);
}

UINT  _tx_thread_interrupt_control(UINT new_posture)
{
UINT        old_posture;
TX_THREAD   *thread_ptr;
DWORD       thread_id;
UINT        core;

    _tx_win32_critical_section_obtain(&_tx_win32_critical_section);

#ifdef TX_WIN32_DEBUG_ENABLE
    if (new_posture == TX_INT_ENABLE)
    {
        _tx_win32_debug_entry_insert("RESTORE", __FILE__, __LINE__);
    }
    else
    {
        _tx_win32_debug_entry_insert("DISABLE", __FILE__, __LINE__);
    }
#endif

    thread_id =  GetCurrentThreadId();
    core =       _tx_thread_smp_core_get();
    thread_ptr = _tx_thread_current_ptr[core];

    if ((_tx_win32_threadx_thread != 0) &&
        ((thread_ptr == TX_NULL) || (thread_ptr -> tx_thread_win32_thread_id != thread_id)))
    {
        _tx_win32_critical_section_release_all(&_tx_win32_critical_section);
        ExitThread(0);
    }

    if (_tx_win32_critical_section.tx_win32_critical_section_nested_count == 1U)
    {
        old_posture =  TX_INT_ENABLE;
    }
    else
    {
        old_posture =  TX_INT_DISABLE;
    }

    if (_tx_thread_system_state[core] != 0UL)
    {
        if (new_posture == TX_INT_ENABLE)
        {
            _tx_win32_global_int_disabled_flag =  TX_FALSE;
            _tx_win32_critical_section_release_all(&_tx_win32_critical_section);
        }
        else if (new_posture == TX_INT_DISABLE)
        {
            _tx_win32_global_int_disabled_flag =  TX_TRUE;
        }
    }
    else if (thread_ptr != TX_NULL)
    {
        if (new_posture == TX_INT_ENABLE)
        {
            thread_ptr -> tx_thread_win32_int_disabled_flag =  TX_FALSE;
            _tx_win32_critical_section_release_all(&_tx_win32_critical_section);
        }
        else if (new_posture == TX_INT_DISABLE)
        {
            thread_ptr -> tx_thread_win32_int_disabled_flag =  TX_TRUE;
        }
    }

    return(old_posture);
}

atic VOID  _tx_win32_thread_cleanup(TX_THREAD *thread_ptr)
{
DWORD   exit_code;
ULONG   wait_count;

    if (thread_ptr -> tx_thread_win32_thread_handle != NULL)
    {
        wait_count =  0U;

        do
        {
            if ((GetExitCodeThread(thread_ptr -> tx_thread_win32_thread_handle, &exit_code) != 0) &&
                (exit_code != STILL_ACTIVE))
            {
                break;
            }

            _tx_win32_thread_resume(thread_ptr -> tx_thread_win32_thread_handle);

            _tx_win32_thread_run_signal(thread_ptr);

            _tx_win32_thread_sleep(1U);
            wait_count++;
        } while (wait_count < 100U);

        if ((GetExitCodeThread(thread_ptr -> tx_thread_win32_thread_handle, &exit_code) != 0) &&
            (exit_code == STILL_ACTIVE))
        {
            (void) TerminateThread(thread_ptr -> tx_thread_win32_thread_handle, 0U);
            (void) WaitForSingleObject(thread_ptr -> tx_thread_win32_thread_handle, INFINITE);
        }

        CloseHandle(thread_ptr -> tx_thread_win32_thread_handle);
        thread_ptr -> tx_thread_win32_thread_handle =  NULL;
    }

    if (thread_ptr -> tx_thread_win32_thread_run_semaphore != NULL)
    {
        CloseHandle(thread_ptr -> tx_thread_win32_thread_run_semaphore);
        thread_ptr -> tx_thread_win32_thread_run_semaphore =  NULL;
    }

    if (thread_ptr -> tx_thread_win32_thread_start_semaphore != NULL)
    {
        CloseHandle(thread_ptr -> tx_thread_win32_thread_start_semaphore);
        thread_ptr -> tx_thread_win32_thread_start_semaphore =  NULL;
    }
}

id  _tx_thread_delete_port_completion(TX_THREAD *thread_ptr, UINT tx_interrupt_save)
{
    _tx_thread_smp_unprotect(tx_interrupt_save);

    _tx_win32_thread_cleanup(thread_ptr);

    tx_interrupt_save =  _tx_thread_smp_protect();
    TX_PARAMETER_NOT_USED(tx_interrupt_save);
}

void  _tx_thread_smp_core_preempt(UINT core)
{
TX_THREAD   *preempt_thread;

    preempt_thread =  _tx_thread_current_ptr[core];

    if (preempt_thread != TX_NULL)
    {
        preempt_thread -> tx_thread_win32_deferred_preempt =  TX_TRUE;
        _tx_win32_debug_entry_insert("CORE_PREEMPT_deferred", __FILE__, __LINE__);

        MemoryBarrier();
        if (SetEvent(_tx_win32_scheduler_event) == 0)
        {
            _tx_win32_system_error++;
        }
    }
    else if (_tx_thread_execute_ptr[core] != TX_NULL)
    {
        _tx_win32_debug_entry_insert("CORE_PREEMPT_wake_idle", __FILE__, __LINE__);

        MemoryBarrier();
        if (SetEvent(_tx_win32_scheduler_event) == 0)
        {
            _tx_win32_system_error++;
        }
    }
}

ULONG  _tx_thread_smp_current_state_get(void)
{
UINT    core;
DWORD   thread_id;
UINT    critical_section_owned;
ULONG   current_state;

    thread_id =  GetCurrentThreadId();
    critical_section_owned =  (UINT) (_tx_win32_critical_section.tx_win32_critical_section_owner == thread_id);

    if (critical_section_owned == TX_FALSE)
    {
        _tx_win32_critical_section_obtain(&_tx_win32_critical_section);
    }

    core =  _tx_win32_smp_current_core_get();
    current_state =  _tx_thread_system_state[core];

    if (critical_section_owned == TX_FALSE)
    {
        _tx_win32_critical_section_release(&_tx_win32_critical_section);
    }

    return(current_state);
}

TX_THREAD  *_tx_thread_smp_current_thread_get(void)
{
UINT        core;
DWORD       thread_id;
UINT        critical_section_owned;
TX_THREAD   *current_thread;

    thread_id =  GetCurrentThreadId();
    critical_section_owned =  (UINT) (_tx_win32_critical_section.tx_win32_critical_section_owner == thread_id);

    if (critical_section_owned == TX_FALSE)
    {
        _tx_win32_critical_section_obtain(&_tx_win32_critical_section);
    }

    core =  _tx_win32_smp_current_core_get();
    current_thread =  _tx_thread_current_ptr[core];

    if ((_tx_win32_threadx_thread != 0) && (current_thread == TX_NULL))
    {
        _tx_win32_debug_entry_insert("CURRENT_THREAD_GET_NULL", __FILE__, __LINE__);
    }

    if (critical_section_owned == TX_FALSE)
    {
        _tx_win32_critical_section_release(&_tx_win32_critical_section);
    }

    return(current_thread);
}

UINT  _tx_thread_smp_protect(void)
{
DWORD       current_thread_id;
UINT        core;
UINT        interrupt_posture;
TX_THREAD   *current_thread;
UINT        current_state;

    do
    {
        do
        {
            _tx_win32_critical_section_obtain(&_tx_win32_critical_section);

            current_thread_id =  GetCurrentThreadId();
            core =               _tx_thread_smp_core_get();
            current_thread =     _tx_thread_current_ptr[core];

            if ((_tx_win32_threadx_thread != 0) &&
                ((current_thread == TX_NULL) || (current_thread -> tx_thread_win32_thread_id != current_thread_id)))
            {
                _tx_win32_critical_section_release_all(&_tx_win32_critical_section);
                ExitThread(0);
            }

            if (_tx_win32_threadx_thread == 0)
            {
                break;
            }

            if ((current_thread != TX_NULL) && (_tx_thread_preempt_disable == 0U))
            {
                current_state =  current_thread -> tx_thread_state;
                if ((current_state == TX_TERMINATED) || (current_state == TX_COMPLETED))
                {
                    current_thread -> tx_thread_win32_deferred_preempt =  TX_FALSE;
                    current_thread -> tx_thread_win32_suspension_type =   1U;

                    if (_tx_timer_time_slice[core] != 0U)
                    {
                        current_thread -> tx_thread_time_slice =  _tx_timer_time_slice[core];
                        _tx_timer_time_slice[core] =  0U;
                    }

                    _tx_thread_current_ptr[core] =  TX_NULL;
                    _tx_win32_virtual_cores[core].tx_thread_smp_core_mapping_thread =        TX_NULL;
                    _tx_win32_virtual_cores[core].tx_thread_smp_core_mapping_thread_handle = NULL;
                    _tx_win32_virtual_cores[core].tx_thread_smp_core_mapping_thread_id =     0U;
                    current_thread -> tx_thread_smp_core_control =  1U;

                    _tx_win32_debug_entry_insert("SCHEDULE-thread_terminate_preempt_complete", __FILE__, __LINE__);
                    if (SetEvent(_tx_win32_scheduler_event) == 0)
                    {
                        _tx_win32_system_error++;
                    }
                    _tx_win32_critical_section_release_all(&_tx_win32_critical_section);
                    ExitThread(0);
                }
            }

            if ((current_thread != TX_NULL) && (current_thread -> tx_thread_win32_deferred_preempt != TX_FALSE))
            {
                if (SetEvent(_tx_win32_scheduler_event) == 0)
                {
                    _tx_win32_system_error++;
                }
                _tx_win32_critical_section_release_all(&_tx_win32_critical_section);
                _tx_win32_thread_yield();
            }
            else
            {
                break;
            }
        } while (1);

        interrupt_posture =  (UINT) _tx_win32_global_int_disabled_flag;

        if (_tx_thread_smp_protection.tx_thread_smp_protect_core == core)
        {
            _tx_thread_smp_protection.tx_thread_smp_protect_count++;
            _tx_win32_global_int_disabled_flag =  TX_TRUE;
            _tx_win32_debug_entry_insert("PROTECT-obtained-nested", __FILE__, __LINE__);
            break;
        }
        else if (_tx_thread_smp_protection.tx_thread_smp_protect_core == 0xFFFFFFFFUL)
        {
            _tx_thread_smp_protection.tx_thread_smp_protect_in_force =   TX_TRUE;
            _tx_thread_smp_protection.tx_thread_smp_protect_thread =     current_thread;
            _tx_thread_smp_protection.tx_thread_smp_protect_core =       core;
            _tx_thread_smp_protection.tx_thread_smp_protect_count =      1U;
            _tx_thread_smp_protection.tx_thread_smp_protect_thread_id =  current_thread_id;
            _tx_win32_global_int_disabled_flag =  TX_TRUE;
            _tx_win32_debug_entry_insert("PROTECT-obtained", __FILE__, __LINE__);
            break;
        }
        else
        {
            _tx_win32_critical_section_release(&_tx_win32_critical_section);
        }
    } while (1);

    _tx_win32_global_int_disabled_flag =  TX_TRUE;
    return(interrupt_posture);
}

ULONG  _tx_thread_smp_time_get(void)
{
    QueryPerformanceCounter((LARGE_INTEGER *) &_tx_win32_time_stamp);
    return((ULONG) _tx_win32_time_stamp.LowPart);
}

void  _tx_thread_smp_unprotect(UINT new_interrupt_posture)
{
UINT    core;
DWORD   current_thread_id;
UINT    critical_section_owned;

    current_thread_id =  GetCurrentThreadId();
    critical_section_owned =  (UINT) (_tx_win32_critical_section.tx_win32_critical_section_owner == current_thread_id);

    if (critical_section_owned == TX_FALSE)
    {
        _tx_win32_critical_section_obtain(&_tx_win32_critical_section);
    }

    core =  _tx_thread_smp_core_get();

    if (_tx_thread_smp_protection.tx_thread_smp_protect_core == core)
    {
        _tx_thread_smp_protection.tx_thread_smp_protect_count--;

        if (_tx_thread_smp_protection.tx_thread_smp_protect_count == 0U)
        {
            _tx_win32_global_int_disabled_flag =  new_interrupt_posture;

            if (_tx_thread_preempt_disable == 0U)
            {
                _tx_thread_smp_protection.tx_thread_smp_protect_in_force =   TX_FALSE;
                _tx_thread_smp_protection.tx_thread_smp_protect_thread =     TX_NULL;
                _tx_thread_smp_protection.tx_thread_smp_protect_core =       0xFFFFFFFFUL;
                _tx_thread_smp_protection.tx_thread_smp_protect_thread_id =  0U;
                _tx_win32_debug_entry_insert("UNPROTECT-keep", __FILE__, __LINE__);
            }
            else
            {
                _tx_win32_debug_entry_insert("UNPROTECT-released", __FILE__, __LINE__);
            }
        }
        else
        {
            _tx_win32_debug_entry_insert("UNPROTECT-nested", __FILE__, __LINE__);
        }

        _tx_win32_critical_section_release(&_tx_win32_critical_section);
    }
    else
    {
        _tx_win32_critical_section_release(&_tx_win32_critical_section);
    }
}

VOID  _tx_thread_stack_build(TX_THREAD *thread_ptr, VOID (*function_ptr)(VOID))
{
    TX_PARAMETER_NOT_USED(function_ptr);

#if (TX_WIN32_USE_ADDRESS_WAIT != 0)
    thread_ptr -> tx_thread_win32_thread_run_semaphore =    NULL;
    thread_ptr -> tx_thread_win32_thread_start_semaphore =  NULL;
#else
    thread_ptr -> tx_thread_win32_thread_run_semaphore =  CreateSemaphore(NULL, 0, 0x7FFFFFFF, NULL);
    if (thread_ptr -> tx_thread_win32_thread_run_semaphore == NULL)
    {
        printf("ThreadX SMP Win64 error creating thread run semaphore!\n");
        while (1)
        {
        }
    }

    thread_ptr -> tx_thread_win32_thread_start_semaphore =  CreateSemaphore(NULL, 0, 1, NULL);
    if (thread_ptr -> tx_thread_win32_thread_start_semaphore == NULL)
    {
        printf("ThreadX SMP Win64 error creating thread start semaphore!\n");
        while (1)
        {
        }
    }
#endif

    thread_ptr -> tx_thread_win32_thread_handle =  CreateThread(NULL,
                                                                TX_WIN32_THREAD_STACK_SIZE,
                                                                _tx_win32_thread_entry,
                                                                (LPVOID) thread_ptr,
                                                                CREATE_SUSPENDED,
                                                                &thread_ptr -> tx_thread_win32_thread_id);
    if (thread_ptr -> tx_thread_win32_thread_handle == NULL)
    {
        printf("ThreadX SMP Win64 error creating thread!\n");
        while (1)
        {
        }
    }

    SetThreadPriority(thread_ptr -> tx_thread_win32_thread_handle, TX_WIN32_PRIORITY_USER_THREAD);

    thread_ptr -> tx_thread_win32_suspension_type =    2U;
    thread_ptr -> tx_thread_win32_mutex_access =       TX_FALSE;
    thread_ptr -> tx_thread_win32_int_disabled_flag =  TX_FALSE;
    thread_ptr -> tx_thread_win32_deferred_preempt =   TX_FALSE;
    thread_ptr -> tx_thread_win32_virtual_core =       0U;
    thread_ptr -> tx_thread_win32_run_sequence =        0L;
    thread_ptr -> tx_thread_win32_run_sequence_seen =   0L;
    thread_ptr -> tx_thread_win32_start_sequence =      0L;

    thread_ptr -> tx_thread_stack_ptr =  (VOID *) (((CHAR *) thread_ptr -> tx_thread_stack_end) - 8);
    *(((ULONG *) thread_ptr -> tx_thread_stack_ptr) - 1) =  0UL;
    thread_ptr -> tx_thread_smp_core_control =  1U;

    ResumeThread(thread_ptr -> tx_thread_win32_thread_handle);
}

static DWORD WINAPI  _tx_win32_thread_entry(LPVOID ptr)
{
TX_THREAD   *thread_ptr;

    thread_ptr =  (TX_THREAD *) ptr;
    _tx_win32_threadx_thread =  1;

    _tx_win32_debug_entry_insert("THREAD_ENTRY_wait", __FILE__, __LINE__);
    _tx_win32_wait_for_thread_run(thread_ptr);
#ifdef TX_WIN32_PROFILE_ENABLE
    _tx_win32_profile_mark_run_wake(thread_ptr);
#endif
    _tx_win32_debug_entry_insert("THREAD_ENTRY_wake", __FILE__, __LINE__);

    /* A delete/reset cleanup may wake a host thread that was never scheduled.
       Only treat the wakeup as terminal if the ThreadX thread is already in a
       terminal state; otherwise allow the normal startup race to complete.  */
    if ((thread_ptr -> tx_thread_smp_core_control != 0U) &&
        ((thread_ptr -> tx_thread_state == TX_TERMINATED) ||
         (thread_ptr -> tx_thread_state == TX_COMPLETED)))
    {
        ExitThread(0U);
    }

    _tx_win32_current_virtual_core =  thread_ptr -> tx_thread_win32_virtual_core;
#ifdef TX_WIN32_PROFILE_ENABLE
    _tx_win32_profile_mark_start_ack(thread_ptr);
#endif
    _tx_win32_thread_start_ack_signal(thread_ptr);
    _tx_win32_debug_entry_insert("THREAD_ENTRY_ack", __FILE__, __LINE__);

    _tx_thread_shell_entry();

    return(0U);
}

VOID  _tx_thread_system_return(VOID)
{
TX_THREAD   *temp_thread_ptr;
UINT        temp_thread_state;
UINT        core;
DWORD       thread_id;

    _tx_win32_critical_section_obtain(&_tx_win32_critical_section);

    core =       _tx_thread_smp_core_get();
    thread_id =  GetCurrentThreadId();

    _tx_win32_debug_entry_insert("SYSTEM_RETURN", __FILE__, __LINE__);

    temp_thread_ptr =  _tx_thread_current_ptr[core];

    if ((_tx_win32_threadx_thread != 0) &&
        ((temp_thread_ptr == TX_NULL) || (temp_thread_ptr -> tx_thread_win32_thread_id != thread_id)))
    {
        _tx_win32_critical_section_release_all(&_tx_win32_critical_section);
        ExitThread(0);
    }

    if (_tx_timer_time_slice[core] != 0U)
    {
        temp_thread_ptr -> tx_thread_time_slice =  _tx_timer_time_slice[core];
        _tx_timer_time_slice[core] =  0U;
    }

    temp_thread_state =   temp_thread_ptr -> tx_thread_state;
    temp_thread_ptr -> tx_thread_win32_suspension_type =  2U;
    _tx_thread_current_ptr[core] =  TX_NULL;
    _tx_win32_virtual_cores[core].tx_thread_smp_core_mapping_thread_handle = NULL;
    _tx_win32_virtual_cores[core].tx_thread_smp_core_mapping_thread_id =     0U;
    _tx_win32_virtual_cores[core].tx_thread_smp_core_mapping_thread =        TX_NULL;

    _tx_win32_debug_entry_insert("SYSTEM_RETURN-release_sem", __FILE__, __LINE__);

    if (temp_thread_ptr != _tx_thread_smp_protection.tx_thread_smp_protect_thread)
    {
        _tx_win32_system_error++;
    }

    _tx_thread_smp_protection.tx_thread_smp_protect_count =      0U;
    _tx_thread_smp_protection.tx_thread_smp_protect_core =       0xFFFFFFFFUL;
    _tx_thread_smp_protection.tx_thread_smp_protect_thread =     TX_NULL;
    _tx_thread_smp_protection.tx_thread_smp_protect_in_force =   TX_FALSE;
    _tx_thread_smp_protection.tx_thread_smp_protect_thread_id =  0U;

    temp_thread_ptr -> tx_thread_smp_core_control =  1U;
    _tx_win32_global_int_disabled_flag =  TX_FALSE;
    _tx_thread_preempt_disable =          0U;

    MemoryBarrier();
    if (SetEvent(_tx_win32_scheduler_event) == 0)
    {
        _tx_win32_system_error++;
    }

    _tx_win32_critical_section_release_all(&_tx_win32_critical_section);

    if (temp_thread_state == TX_TERMINATED)
    {
        ExitThread(0);
    }

    _tx_win32_wait_for_thread_run(temp_thread_ptr);
#ifdef TX_WIN32_PROFILE_ENABLE
    _tx_win32_profile_mark_run_wake(temp_thread_ptr);
#endif
    _tx_win32_current_virtual_core =  temp_thread_ptr -> tx_thread_win32_virtual_core;
#ifdef TX_WIN32_PROFILE_ENABLE
    _tx_win32_profile_mark_start_ack(temp_thread_ptr);
#endif
    _tx_win32_thread_start_ack_signal(temp_thread_ptr);

    _tx_win32_critical_section_obtain(&_tx_win32_critical_section);

    _tx_win32_debug_entry_insert("SYSTEM_RETURN-wake_up", __FILE__, __LINE__);

    core =  _tx_thread_smp_core_get();
    temp_thread_ptr =  _tx_thread_current_ptr[core];

    if ((_tx_win32_threadx_thread != 0) &&
        ((temp_thread_ptr == TX_NULL) || (temp_thread_ptr -> tx_thread_win32_thread_id != thread_id)))
    {
        _tx_win32_critical_section_release_all(&_tx_win32_critical_section);
        ExitThread(0);
    }

    _tx_win32_debug_entry_insert("SYSTEM_RETURN-finish", __FILE__, __LINE__);
    _tx_win32_critical_section_release_all(&_tx_win32_critical_section);
}

VOID  _tx_timer_interrupt(VOID)
{
UINT    saved_posture;

    saved_posture =  _tx_thread_smp_protect();

    _tx_timer_interrupt_active++;
    _tx_win32_debug_entry_insert("TIMER INTERRUPT", __FILE__, __LINE__);

    _tx_timer_system_clock++;

    if (*_tx_timer_current_ptr)
    {
        _tx_timer_expired =  TX_TRUE;
    }
    else
    {
        _tx_timer_current_ptr++;
        if (_tx_timer_current_ptr == _tx_timer_list_end)
        {
            _tx_timer_current_ptr =  _tx_timer_list_start;
        }
    }

    if (_tx_timer_expired != TX_FALSE)
    {
        _tx_timer_expiration_process();
    }

    _tx_thread_time_slice();

    _tx_timer_interrupt_active++;
    _tx_thread_smp_unprotect(saved_posture);
}

void *memset(void *des, int c, size_t n)
{
    if ((des == NULL) || n == 0)
        return des;

    char *t = (char *)des;
    for (size_t i = 0; i < n; i++)
        t[i] = c;
    return t;
}

int board_init(void)
{
    int ret;

    ret = plic_init();
    if (ret)
        return ret;

    ret = uart_init();
    if (ret)
        return ret;

    ret = hwtimer_init();
    if (ret)
        return ret;

    return 0;
}

int main()
{

    /* Enter the ThreadX kernel.  */
    tx_kernel_enter();
}

void    tx_application_define(void *first_unused_memory)
{

CHAR    *pointer = TX_NULL;


    /* Create a byte memory pool from which to allocate the thread stacks.  */
    tx_byte_pool_create(&byte_pool_0, "byte pool 0", memory_area, DEMO_BYTE_POOL_SIZE);

    /* Put system definition stuff in here, e.g. thread creates and other assorted
       create information.  */

    /* Allocate the stack for thread 0.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    /* Create the main thread.  */
    tx_thread_create(&thread_0, "thread 0", thread_0_entry, 0,
            pointer, DEMO_STACK_SIZE,
            1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);


    /* Allocate the stack for thread 1.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    /* Create threads 1 and 2. These threads pass information through a ThreadX
       message queue.  It is also interesting to note that these threads have a time
       slice.  */
    tx_thread_create(&thread_1, "thread 1", thread_1_entry, 1,
            pointer, DEMO_STACK_SIZE,
            16, 16, 4, TX_AUTO_START);

    /* Allocate the stack for thread 2.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    tx_thread_create(&thread_2, "thread 2", thread_2_entry, 2,
            pointer, DEMO_STACK_SIZE,
            16, 16, 4, TX_AUTO_START);

    /* Allocate the stack for thread 3.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    /* Create threads 3 and 4.  These threads compete for a ThreadX counting semaphore.
       An interesting thing here is that both threads share the same instruction area.  */
    tx_thread_create(&thread_3, "thread 3", thread_3_and_4_entry, 3,
            pointer, DEMO_STACK_SIZE,
            8, 8, TX_NO_TIME_SLICE, TX_AUTO_START);

    /* Allocate the stack for thread 4.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    tx_thread_create(&thread_4, "thread 4", thread_3_and_4_entry, 4,
            pointer, DEMO_STACK_SIZE,
            8, 8, TX_NO_TIME_SLICE, TX_AUTO_START);

    /* Allocate the stack for thread 5.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    /* Create thread 5.  This thread simply pends on an event flag which will be set
       by thread_0.  */
    tx_thread_create(&thread_5, "thread 5", thread_5_entry, 5,
            pointer, DEMO_STACK_SIZE,
            4, 4, TX_NO_TIME_SLICE, TX_AUTO_START);

    /* Allocate the stack for thread 6.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    /* Create threads 6 and 7.  These threads compete for a ThreadX mutex.  */
    tx_thread_create(&thread_6, "thread 6", thread_6_and_7_entry, 6,
            pointer, DEMO_STACK_SIZE,
            8, 8, TX_NO_TIME_SLICE, TX_AUTO_START);

    /* Allocate the stack for thread 7.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_STACK_SIZE, TX_NO_WAIT);

    tx_thread_create(&thread_7, "thread 7", thread_6_and_7_entry, 7,
            pointer, DEMO_STACK_SIZE,
            8, 8, TX_NO_TIME_SLICE, TX_AUTO_START);

    /* Allocate the message queue.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_QUEUE_SIZE*sizeof(ULONG), TX_NO_WAIT);

    /* Create the message queue shared by threads 1 and 2.  */
    tx_queue_create(&queue_0, "queue 0", TX_1_ULONG, pointer, DEMO_QUEUE_SIZE*sizeof(ULONG));

    /* Create the semaphore used by threads 3 and 4.  */
    tx_semaphore_create(&semaphore_0, "semaphore 0", 1);

    /* Create the event flags group used by threads 1 and 5.  */
    tx_event_flags_create(&event_flags_0, "event flags 0");

    /* Create the mutex used by thread 6 and 7 without priority inheritance.  */
    tx_mutex_create(&mutex_0, "mutex 0", TX_NO_INHERIT);

    /* Allocate the memory for a small block pool.  */
    tx_byte_allocate(&byte_pool_0, (VOID **) &pointer, DEMO_BLOCK_POOL_SIZE, TX_NO_WAIT);

    /* Create a block memory pool to allocate a message buffer from.  */
    tx_block_pool_create(&block_pool_0, "block pool 0", sizeof(ULONG), pointer, DEMO_BLOCK_POOL_SIZE);

    /* Allocate a block and release the block memory.  */
    tx_block_allocate(&block_pool_0, (VOID **) &pointer, TX_NO_WAIT);

    /* Release the block back to the pool.  */
    tx_block_release(pointer);
}

void    thread_0_entry(ULONG thread_input)
{

UINT    status;


    /* This thread simply sits in while-forever-sleep loop.  */
    while(1)
    {
        puts("[Thread] : thread_0_entry is here!");
        /* Increment the thread counter.  */
        thread_0_counter++;

        /* Sleep for 10 ticks.  */
        tx_thread_sleep(10);

        /* Set event flag 0 to wakeup thread 5.  */
        status =  tx_event_flags_set(&event_flags_0, 0x1, TX_OR);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;
    }
}

void    thread_1_entry(ULONG thread_input)
{

UINT    status;


    /* This thread simply sends messages to a queue shared by thread 2.  */
    while(1)
    {
        puts("[Thread] : thread_1_entry is here!");
        /* Increment the thread counter.  */
        thread_1_counter++;

        /* Send message to queue 0.  */
        status =  tx_queue_send(&queue_0, &thread_1_messages_sent, TX_WAIT_FOREVER);

        /* Check completion status.  */
        if (status != TX_SUCCESS)
            break;

        /* Increment the message sent.  */
        thread_1_messages_sent++;
    }
}

void    thread_2_entry(ULONG thread_input)
{

ULONG   received_message;
UINT    status;

    /* This thread retrieves messages placed on the queue by thread 1.  */
    while(1)
    {
        puts("[Thread] : thread_2_entry is here!");
        /* Increment the thread counter.  */
        thread_2_counter++;

        /* Retrieve a message from the queue.  */
        status = tx_queue_receive(&queue_0, &received_message, TX_WAIT_FOREVER);

        /* Check completion status and make sure the message is what we
           expected.  */
        if ((status != TX_SUCCESS) || (received_message != thread_2_messages_received))
            break;

        /* Otherwise, all is okay.  Increment the received message count.  */
        thread_2_messages_received++;
    }
}

void    thread_3_and_4_entry(ULONG thread_input)
{

UINT    status;


    /* This function is executed from thread 3 and thread 4.  As the loop
       below shows, these function compete for ownership of semaphore_0.  */
    while(1)
    {
        puts("[Thread] : thread_3_and_4_entry is here!");

        /* Increment the thread counter.  */
        if (thread_input == 3)
            thread_3_counter++;
        else
            thread_4_counter++;

        /* Get the semaphore with suspension.  */
        status =  tx_semaphore_get(&semaphore_0, TX_WAIT_FOREVER);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;

        /* Sleep for 2 ticks to hold the semaphore.  */
        tx_thread_sleep(2);

        /* Release the semaphore.  */
        status =  tx_semaphore_put(&semaphore_0);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;
    }
}

void    thread_5_entry(ULONG thread_input)
{

UINT    status;
ULONG   actual_flags;


    /* This thread simply waits for an event in a forever loop.  */
    while(1)
    {
        puts("[Thread] : thread_5_entry is here!");
        /* Increment the thread counter.  */
        thread_5_counter++;

        /* Wait for event flag 0.  */
        status =  tx_event_flags_get(&event_flags_0, 0x1, TX_OR_CLEAR,
                                                &actual_flags, TX_WAIT_FOREVER);

        /* Check status.  */
        if ((status != TX_SUCCESS) || (actual_flags != 0x1))
            break;
    }
}

void    thread_6_and_7_entry(ULONG thread_input)
{

UINT    status;


    /* This function is executed from thread 6 and thread 7.  As the loop
       below shows, these function compete for ownership of mutex_0.  */
    while(1)
    {
        puts("[Thread] : thread_6_and_7_entry is here!");
        /* Increment the thread counter.  */
        if (thread_input == 6)
            thread_6_counter++;
        else
            thread_7_counter++;

        /* Get the mutex with suspension.  */
        status =  tx_mutex_get(&mutex_0, TX_WAIT_FOREVER);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;

        /* Get the mutex again with suspension.  This shows
           that an owning thread may retrieve the mutex it
           owns multiple times.  */
        status =  tx_mutex_get(&mutex_0, TX_WAIT_FOREVER);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;

        /* Sleep for 2 ticks to hold the mutex.  */
        tx_thread_sleep(2);

        /* Release the mutex.  */
        status =  tx_mutex_put(&mutex_0);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;

        /* Release the mutex again.  This will actually
           release ownership since it was obtained twice.  */
        status =  tx_mutex_put(&mutex_0);

        /* Check status.  */
        if (status != TX_SUCCESS)
            break;
    }
}

static inline void sbi_set_timer(uint64_t stime_value)
{
    register uint64_t a0 asm("a0") = stime_value;
    register uint64_t a7 asm("a7") = 0;  /* SBI_SET_TIMER */
    asm volatile("ecall"
                 : "+r"(a0)
                 : "r"(a7)
                 : "memory");
}

tatic inline uint64_t read_time(void)
{
    uint64_t t;
    asm volatile("rdtime %0" : "=r"(t));
    return t;
}

nt hwtimer_init(void)
{
    uint64_t now = read_time();
    sbi_set_timer(now + TICKNUM_PER_TIMER);
    return 0;
}

nt hwtimer_handler(void)
{
    uint64_t now = read_time();
    sbi_set_timer(now + TICKNUM_PER_TIMER);
    return 0;
}

void plic_irq_enable(int irqno)
{
    int hart = (int)riscv_get_core();
    uint32_t word = irqno / 32;
    uint32_t bit  = irqno % 32;
    volatile uint32_t *en = (volatile uint32_t *)(PLIC_ENABLE(hart) + word * 4);
    *en |= (1u << bit);
}

void plic_irq_disable(int irqno)
{
    int hart = (int)riscv_get_core();
    uint32_t word = irqno / 32;
    uint32_t bit  = irqno % 32;
    volatile uint32_t *en = (volatile uint32_t *)(PLIC_ENABLE(hart) + word * 4);
    *en &= ~(1u << bit);
}

int plic_register_callback(int irqno, irq_callback callback)
{
    if (!(irqno >= 0 && irqno < MAX_CALLBACK_NUM))
        return -1;
    callbacks[irqno] = callback;
    return 0;
}

int plic_init(void)
{
    int hart = (int)riscv_get_core();

    for (int i = 0; i < MAX_CALLBACK_NUM; i++)
        callbacks[i] = NULL;

    /* Mask everything for this hart. */
    for (int word = 0; word < (MAX_CALLBACK_NUM + 31) / 32; word++)
        *(volatile uint32_t *)(PLIC_ENABLE(hart) + word * 4) = 0;

    /* Set hart threshold to 0 so any non-zero priority IRQ can fire. */
    *(volatile uint32_t *)PLIC_PRIORITY_REG(hart) = 0;

    /*
     * Drain stale pending interrupts left over from a prior boot stage
     * (BootROM / OpenSBI / U-Boot).  We temporarily enable every source
     * so claim returns the actual highest-priority pending ID, then
     * complete whatever was claimed.  Loop until claim returns 0
     * (no more pending).  This follows the PLIC spec: claim returns 0
     * when nothing is pending for this context.
     */
    for (int word = 0; word < (PLIC_NUM_SOURCES + 31) / 32; word++)
        *(volatile uint32_t *)(PLIC_ENABLE(hart) + word * 4) = 0xFFFFFFFFu;

    for (;;) {
        uint32_t id = *(volatile uint32_t *)PLIC_CLAIM_REG(hart);
        if (id == 0)
            break;
        *(volatile uint32_t *)PLIC_COMPLETE_REG(hart) = id;
    }

    /* Re-mask everything; individual drivers will enable their sources. */
    for (int word = 0; word < (PLIC_NUM_SOURCES + 31) / 32; word++)
        *(volatile uint32_t *)(PLIC_ENABLE(hart) + word * 4) = 0;

    /*
     * Set default priority for every source to PLIC_DEFAULT_PRIORITY (2),
     * Priority 0 means "never pending" per the SiFive PLIC spec, so any 
     * source that should be active must have priority >= 1.  Individual 
     * drivers may override this with plic_prio_set() later.
     */
    for (int i = 1; i <= PLIC_NUM_SOURCES; i++)
        PLIC_SET_PRIO(i, PLIC_DEFAULT_PRIORITY);

    return 0;
}

int plic_claim(void)
{
    int hart = (int)riscv_get_core();
    return (int)*(volatile uint32_t *)PLIC_CLAIM_REG(hart);
}

void plic_complete(int irqno)
{
    int hart = (int)riscv_get_core();
    *(volatile uint32_t *)PLIC_COMPLETE_REG(hart) = (uint32_t)irqno;
}

int plic_irq_intr(void)
{
    int ret = -1;
    int irqno = plic_claim();
    if (irqno == 0)
        return ret;
    if (irqno < MAX_CALLBACK_NUM && callbacks[irqno] != NULL)
        ret = (callbacks[irqno])(irqno);
    plic_complete(irqno);
    return ret;
}

void trap_handler(uintptr_t cause, uintptr_t epc, uintptr_t tval)
{
    (void)epc;
    (void)tval;

    if (cause & SCAUSE_INTERRUPT)
    {
        if (cause == SCAUSE_S_TIMER_INT)
        {
            hwtimer_handler();
            _tx_timer_interrupt();
        }
        else if (cause == SCAUSE_S_EXTERNAL_INT)
        {
            if (plic_irq_intr() != 0)
            {
                puts("[trap] PLIC dispatch failed");
                while (1)
                    ;
            }
        }
        else
        {
            puts("[trap] unhandled S-mode interrupt");
            while (1)
                ;
        }
    }
    else
    {
        puts("[trap] unhandled synchronous exception");
        while (1)
            ;
    }
}

* configured the UART, keep its baud-rate divisor so we keep
     * a working console.  Just make sure interrupts are masked,
     * the FIFOs are clean and the unit-enable bit is set.
     */
    WriteReg(IER, 0x00);

    /*
     * Program the baud-rate divisor for 115200 baud.
     * The PXA UART functional clock on K1 is 14.7456 MHz:
     *   14,745,600 / (16 × 8) = 115,200 baud → DLL = 8, DLH = 0.
     */
    WriteReg(LCR, LCR_DLAB);
    WriteReg(DLL, 0x08);
    WriteReg(DLH, 0x00);

    WriteReg(LCR, LCR_WLS_8);
    WriteReg(FCR, FCR_TRFIFOE | FCR_FIFO_CLEAR);

    /* Enable the UART transmit/receive engines (K1-specific). */
    WriteReg(IER, IER_UUE);

    plic_irq_enable(UART0_IRQ);
    plic_prio_set(UART0_IRQ, 1);

    puts("[uart] UART0 initialized");
    return 0;
}

static inline void uart_putc_nolock(int ch)
{
    while ((ReadReg(LSR) & LSR_TDRQ) == 0)

WriteReg(THR, ch);
}

int uart_putc(int ch)
{
    int intr_enable = riscv_intr_get();
    riscv_intr_off();
    uart_pu

_nolock(ch);
    riscv_intr_restore(intr_enable);
    return 1;
}

int uart_puts(const char *str)
{
    int i;
    int intr_enable = riscv_intr_get();
    riscv_int

off();
    for (i = 0; str[i] != 0; i++)
        uart_putc_nolock(str[i]);
    uart_putc_nolock('\r');
    uart_putc_nolock('\n');
    riscv_intr_restore(intr_enable);
    return i;
}

static uint32_t fll_get_mult_div_from_frequency(uint32_t freq, uint32_t *mult,
                                                uint32_t *div)
{
    uint32_t fref = FLL_REF_CLK;
    uint32_t log2_m;
    uint32_t d;
    uint32_t m;
    uint32_t fres;

    if ((freq == 0U) || (mult == NULL) || (div == NULL))
    {
        if (mult != NULL)
        {
            *mult = 0U;
        }
        if (div != NULL)
        {
            *div = 0U;
        }
        return 0U;
    }

    if (freq > fref)
    {
        log2_m = fll_fl1(freq) - fll_fl1(fref);
    }
    else
    {
        log2_m = 0U;
    }

    if (FLL_LOG2_MAXM > log2_m)
    {
        d = fll_max_u32(1U, (FLL_LOG2_MAXM - log2_m) >> 1U);
    }
    else
    {
        d = 1U;
    }

    m = (freq << d) / fref;
    fres = (fref * m + (1UL << (d - 1U))) >> d;

    *mult = m;
    *div = d + 1U;
    return fres;
}

static uint32_t fll_get_frequency_from_mult_div(uint32_t mult, uint32_t div)
{
    uint32_t fref = FLL_REF_CLK;

    if (div == 0U)
    {
        return fref * mult;
    }

    return (fref * mult) >> (div - 1U);
}

int pi_fll_set_frequency(fll_type_t which_fll, uint32_t frequency, int check)
{
    uint32_t mult;
    uint32_t div;
    uint32_t reg1;
    uint32_t saved_irq;

    (void)check;

    if ((uint32_t)which_fll >= FLL_NUM)
    {
        return -1;
    }

    if (frequency == 0U)
    {
        return -1;
    }

    saved_irq = irq_clint_disable();
    (void)fll_get_mult_div_from_frequency(frequency, &mult, &div);

    reg1 = FLL_CTRL[which_fll].FLL_CONF1;
    reg1 &= ~FLL_CTRL_CONF1_MULTI_FACTOR_MASK;
    reg1 |= REG_SET(FLL_CTRL_CONF1_MULTI_FACTOR, mult);
    reg1 &= ~FLL_CTRL_CONF1_CLK_OUT_DIV_MASK;
    reg1 |= REG_SET(FLL_CTRL_CONF1_CLK_OUT_DIV, div);
    FLL_CTRL[which_fll].FLL_CONF1 = reg1;

    flls_frequency[which_fll] = frequency;
    if (which_fll == FLL_SOC)
    {
        system_core_clock = frequency;
    }

    if ((saved_irq & MSTATUS_IE) != 0U)
    {
        (void)irq_clint_enable();
    }

    return (int)frequency;
}

void pi_fll_init(fll_type_t which_fll, uint32_t ret_state)
{
    uint32_t reg1;

    if ((uint32_t)which_fll >= FLL_NUM)
    {
        return;
    }

    if (ret_state != 0U)
    {
        (void)pi_fll_get_frequency(which_fll, 1U);
        return;
    }

    reg1 = FLL_CTRL[which_fll].FLL_CONF1;
    if (REG_GET(FLL_CTRL_CONF1_MODE, reg1) == 0U)
    {
        uint32_t reg2 = FLL_CTRL[which_fll].FLL_CONF2;
        uint32_t regint = FLL_CTRL[which_fll].FLL_INTEGRATOR;

        reg2 &= ~FLL_CTRL_CONF2_ASSERT_CYCLES_MASK;
        reg2 |= REG_SET(FLL_CTRL_CONF2_ASSERT_CYCLES, 0x6U);
        reg2 &= ~FLL_CTRL_CONF2_LOCK_TOLERANCE_MASK;
        reg2 |= REG_SET(FLL_CTRL_CONF2_LOCK_TOLERANCE, 0x50U);
        FLL_CTRL[which_fll].FLL_CONF2 = reg2;

        regint &= ~FLL_CTRL_INTEGRATOR_INT_PART_MASK;
        regint |= REG_SET(FLL_CTRL_INTEGRATOR_INT_PART, 332U);
        FLL_CTRL[which_fll].FLL_INTEGRATOR = regint;

        reg1 &= ~FLL_CTRL_CONF1_OUTPUT_LOCK_EN_MASK;
        reg1 |= REG_SET(FLL_CTRL_CONF1_OUTPUT_LOCK_EN, 1U);
        reg1 &= ~FLL_CTRL_CONF1_MODE_MASK;
        reg1 |= REG_SET(FLL_CTRL_CONF1_MODE, 1U);
        FLL_CTRL[which_fll].FLL_CONF1 = reg1;
    }

    if (flls_frequency[which_fll] != 0U)
    {
        (void)pi_fll_set_frequency(which_fll, flls_frequency[which_fll], 0);
    }
    else
    {
        flls_frequency[which_fll] = fll_get_frequency_from_mult_div(
            REG_GET(FLL_CTRL_CONF1_MULTI_FACTOR, reg1),
            REG_GET(FLL_CTRL_CONF1_CLK_OUT_DIV, reg1));
    }
}

int pi_fll_get_frequency(fll_type_t which_fll, uint8_t real)
{
    if ((uint32_t)which_fll >= FLL_NUM)
    {
        return -1;
    }

    if (real != 0U)
    {
        flls_frequency[which_fll] = fll_get_frequency_from_mult_div(
            FLL_CTRL[which_fll].FLL_STATUS,
            REG_GET(FLL_CTRL_CONF1_CLK_OUT_DIV, FLL_CTRL[which_fll].FLL_CONF1));
    }

    return (int)flls_frequency[which_fll];
}

atic void gpio_pinmux_set_func_c(uint32_t pin_mask)
{
    for (uint32_t gpio_pin = 0U; gpio_pin < 32U; gpio_pin++)
    {
        if ((pin_mask & (1UL << gpio_pin)) == 0U)
        {
            continue;
        }
        uint32_t io_pad  = gpio_pin + GPIO_IO_PAD_OFFSET;
        uintptr_t reg    = PULP_APB_SOC_CTRL_ADDR + APB_SOC_PADMUX_BASE
                           + io_pad * 4U;
        writew(PINMUX_FUNC_C, reg);
    }
}

atic void gpio_foreach_pin(uint32_t pin_mask, uintptr_t reg_addr, uint32_t extra_bits)
{
    for (uint32_t pin = 0U; pin < 32U; pin++)
    {
        if ((pin_mask & (1UL << pin)) != 0U)
        {
            writew(pin | extra_bits, reg_addr);
        }
    }
}

id gpio_set_output(uint32_t pin_mask)
{
    /* Route physical pads to the GPIO controller via the pad-mux (FUNC_C). */
    gpio_pinmux_set_func_c(pin_mask);

    /* Configure each pin as push-pull output via SETDIR. */
    gpio_foreach_pin(pin_mask,
                     (uintptr_t)(PULP_GPIO_ADDR + GPIO_SETDIR_OFFSET),
                     GPIO_DIR_OUTPUT);
}

id gpio_toggle(uint32_t pin_mask)
{
    gpio_foreach_pin(pin_mask,
                     (uintptr_t)(PULP_GPIO_ADDR + GPIO_TOGGPIO_OFFSET),
                     0U);
}

id gpio_set(uint32_t pin_mask)
{
    gpio_foreach_pin(pin_mask,
                     (uintptr_t)(PULP_GPIO_ADDR + GPIO_SETGPIO_OFFSET),
                     0U);
}

id gpio_clear(uint32_t pin_mask)
{
    gpio_foreach_pin(pin_mask,
                     (uintptr_t)(PULP_GPIO_ADDR + GPIO_CLRGPIO_OFFSET),
                     0U);
}

id gpio_setpinmux(uint8_t io_pad, uint8_t mux)
{
    uintptr_t reg = PULP_APB_SOC_CTRL_ADDR + APB_SOC_PADMUX_BASE
                    + (uintptr_t)io_pad * 4U;
    writew((uint32_t)mux & 0x3U, reg);
}

nt8_t gpio_getpinmux(uint8_t io_pad)
{
    uintptr_t reg = PULP_APB_SOC_CTRL_ADDR + APB_SOC_PADMUX_BASE
                    + (uintptr_t)io_pad * 4U;
    return (uint8_t)(readw(reg) & 0x3U);
}

id gpio_pin_set_dir(uint8_t pin, uint8_t dir)
{
    uint32_t val = (uint32_t)pin;
    if (dir != 0U)
    {
        val |= GPIO_DIR_OUTPUT;
    }
    writew(val, (uintptr_t)(PULP_GPIO_ADDR + GPIO_SETDIR_OFFSET));
}

nt32_t gpio_pin_read_status(uint8_t pin)
{
    writew((uint32_t)pin, (uintptr_t)(PULP_GPIO_ADDR + GPIO_SETSEL_OFFSET));
    return readw((uintptr_t)(PULP_GPIO_ADDR + GPIO_RDSTAT_OFFSET));
}

int i2c_master_init(uint8_t id, uint32_t i2c_freq, uint32_t periph_freq)
{
    uint32_t cg;
    uint32_t clk_div;
    uintptr_t base;

    if ((id >= I2C_MASTER_COUNT) || (i2c_freq == 0U) || (periph_freq == 0U))
    {
        return -1;
    }

    cg = readw((uintptr_t)(UDMA_CH_ADDR_CTRL + UDMA_CTRL_CG_OFFSET));
    cg |= (id == 0U) ? UDMA_CTRL_I2CM0_CLKEN : UDMA_CTRL_I2CM1_CLKEN;
    writew(cg, (uintptr_t)(UDMA_CH_ADDR_CTRL + UDMA_CTRL_CG_OFFSET));

    clk_div = periph_freq / i2c_freq;
    if (clk_div == 0U)
    {
        clk_div = 1U;
    }
    else if (clk_div > 255U)
    {
        clk_div = 255U;
    }
    s_clkdiv[id] = (uint8_t)clk_div;

    base = i2c_master_base(id);
    writew(UDMA_I2C_SETUP_RESET_BIT, base + UDMA_I2C_SETUP_OFFSET);
    writew(0U, base + UDMA_I2C_SETUP_OFFSET);
    writew(0U, base + UDMA_I2C_RX_CFG_OFFSET);
    writew(0U, base + UDMA_I2C_TX_CFG_OFFSET);

    return 0;
}

int i2c_master_read_reg(uint8_t id, uint8_t dev_addr7, uint8_t reg_addr,
                        uint8_t *buf, uint8_t len)
{
    uintptr_t base;
    uint32_t timeout;
    uint32_t cmd_len;
    uint32_t status;

    if ((id >= I2C_MASTER_COUNT) || (dev_addr7 > 0x7FU) || (buf == NULL) || (len == 0U))
    {
        return -1;
    }

    cmd_len = 0U;
    s_cmd_buf[cmd_len++] = I2C_CMD_CFG;
    s_cmd_buf[cmd_len++] = 0U;
    s_cmd_buf[cmd_len++] = s_clkdiv[id];
    s_cmd_buf[cmd_len++] = I2C_CMD_START;
    s_cmd_buf[cmd_len++] = I2C_CMD_WR;
    s_cmd_buf[cmd_len++] = (uint8_t)(dev_addr7 << 1U);
    s_cmd_buf[cmd_len++] = I2C_CMD_WR;
    s_cmd_buf[cmd_len++] = reg_addr;
    s_cmd_buf[cmd_len++] = I2C_CMD_START;
    s_cmd_buf[cmd_len++] = I2C_CMD_WR;
    s_cmd_buf[cmd_len++] = (uint8_t)((dev_addr7 << 1U) | 1U);
    if (len > 1U)
    {
        s_cmd_buf[cmd_len++] = I2C_CMD_RPT;
        s_cmd_buf[cmd_len++] = (uint8_t)(len - 1U);
        s_cmd_buf[cmd_len++] = I2C_CMD_RD_ACK;
    }
    s_cmd_buf[cmd_len++] = I2C_CMD_RD_NACK;
    s_cmd_buf[cmd_len++] = I2C_CMD_STOP;
    s_cmd_buf[cmd_len++] = I2C_CMD_WAIT;
    s_cmd_buf[cmd_len++] = 0U;

    base = i2c_master_base(id);
    writew((uint32_t)(uintptr_t)buf, base + UDMA_I2C_RX_SADDR_OFFSET);
    writew((uint32_t)len, base + UDMA_I2C_RX_SIZE_OFFSET);
    writew(UDMA_CFG_EN_BIT, base + UDMA_I2C_RX_CFG_OFFSET);

    writew((uint32_t)(uintptr_t)s_cmd_buf, base + UDMA_I2C_TX_SADDR_OFFSET);
    writew(cmd_len, base + UDMA_I2C_TX_SIZE_OFFSET);
    writew(UDMA_CFG_EN_BIT, base + UDMA_I2C_TX_CFG_OFFSET);

    for (timeout = 0U; timeout < I2C_TIMEOUT_ITERATIONS; ++timeout)
    {
        status = readw(base + UDMA_I2C_STATUS_OFFSET);
        if ((status & UDMA_I2C_STATUS_AL_BIT) != 0U)
        {
            return -1;
        }
        if (((readw(base + UDMA_I2C_TX_CFG_OFFSET) & UDMA_CFG_PENDING_BIT) == 0U) &&
            ((readw(base + UDMA_I2C_RX_CFG_OFFSET) & UDMA_CFG_PENDING_BIT) == 0U))
        {
            return 0;
        }
    }

    return -1;
}

void *memcpy(void *dest, const void *src, size_t n)
{
    size_t index;
    uint8_t *dst = (uint8_t *)dest;
    const uint8_t *source = (const uint8_t *)src;

    for (index = 0U; index < n; ++index)
    {
        dst[index] = source[index];
    }

    return dest;
}

void *memset(void *dest, int c, size_t n)
{
    size_t index;
    uint8_t *dst = (uint8_t *)dest;
    uint8_t value = (uint8_t)c;

    for (index = 0U; index < n; ++index)
    {
        dst[index] = value;
    }

    return dest;
}

int memcmp(const void *lhs, const void *rhs, size_t n)
{
    size_t index;
    const uint8_t *left = (const uint8_t *)lhs;
    const uint8_t *right = (const uint8_t *)rhs;

    for (index = 0U; index < n; ++index)
    {
        if (left[index] != right[index])
        {
            return (left[index] < right[index]) ? -1 : 1;
        }
    }

    return 0;
}

static void uart_write_hex32(uint32_t value)
{
    static const char hex[] = "0123456789ABCDEF";
    int shift;

    uart_write_str(0U, "0x");
    for (shift = 28; shift >= 0; shift -= 4)
    {
        uart_write_byte(0U, (uint8_t)hex[(value >> (uint32_t)shift) & 0xFU]);
    }
}

void tx_undefined_irq_handler(void)
{
    if (uart_console_ready != 0U)
    {
        uart_write_str(0U, "\r\nUndefined IRQ\r\n");
    }

    /* MISRA deviation: intentional infinite loop used as a fault sink. */
    for (;;)
    {
    }
}

void system_init(void)
{
    uint32_t i;

    for (i = 0U; i < 32U; ++i)
    {
        isr_table[i] = tx_undefined_irq_handler;
    }

    isr_table[7U] = tx_timer_irq_handler;

    for (i = 0U; i < ARCHI_NB_FLL; ++i)
    {
        pi_fll_init((fll_type_t)i, 0U);
    }

    pulp_irq_init();
    (void)timer_irq_init(ARCHI_SOC_FREQUENCY / (uint32_t)TX_TIMER_TICKS_PER_SECOND);
    /* CV32E40P routes the FC Timer LO to irq_i[7] (MTI, bit 7), which maps
     * to mip[7].  IRQ_MASK in cv32e40p_cs_registers forces mie[10] to zero,
     * so bit 7 is the correct enable bit.  mcause will be 0x80000007. */
    (void)csr_read_set(CSR_MIE, BIT(7));

    gpio_init();
    if (uart_init(0U, 115200U, ARCHI_FPGA_FREQUENCY) == 0)
    {
        uart_console_ready = 1U;
    }
}

void tx_trap_handler(uint32_t mcause, uint32_t mepc, uint32_t mtval)
{
    last_trap_mcause = mcause;

    if ((mcause & 0x80000000UL) != 0UL)
    {
        uint32_t irq_id = mcause & 0x1FUL;

        if (isr_table[irq_id] != NULL)
        {
            isr_table[irq_id]();
        }
        else
        {
            tx_undefined_irq_handler();
        }
    }
    else
    {
        if (uart_console_ready != 0U)
        {
            uart_write_str(0U, "\r\nTrap mcause=");
            uart_write_hex32(mcause);
            uart_write_str(0U, " mepc=");
            uart_write_hex32(mepc);
            uart_write_str(0U, " mtval=");
            uart_write_hex32(mtval);
            uart_write_str(0U, "\r\n");
        }

        /* MISRA deviation: intentional infinite loop used as a fault sink. */
        for (;;)
        {
        }
    }
}

int16_t temp_read_celsius_x10(void)
{
    uint8_t buf[2];
    int16_t raw;
    int16_t value;

    if (i2c_master_read_reg(ADT7420_I2C_ID, ADT7420_ADDR7, ADT7420_TEMP_REG, &buf[0], 2U) != 0)
    {
        return INT16_MIN;
    }

    raw = (int16_t)(((uint16_t)buf[0] << 8U) | (uint16_t)buf[1]);
    value = (int16_t)(raw >> 3);
    return (int16_t)(((int32_t)value * 5) / 8);
}

int timer_irq_init(uint32_t ticks)
{
    (void)timer_irq_set_timeout(ticks);

    writew(TIMER_CFG_LO_ENABLE_MASK |
           TIMER_CFG_LO_RESET_MASK |
           TIMER_CFG_LO_MODE_MASK |
           TIMER_CFG_LO_IRQEN_MASK,
           (uintptr_t)(PULP_FC_TIMER_ADDR + TIMER_CFG_LO_OFFSET));

    last_count = 0U;
    return 0;
}

int timer_irq_set_timeout(uint32_t ticks)
{
    writew(1U, (uintptr_t)(PULP_FC_TIMER_ADDR + TIMER_RESET_LO_OFFSET));
    writew(ticks, (uintptr_t)(PULP_FC_TIMER_ADDR + TIMER_CMP_LO_OFFSET));
    last_count = 0U;
    return 0;
}

uint32_t timer_irq_clock_elapsed(void)
{
    uint32_t current = timer_irq_cycle_get_32();
    uint32_t elapsed = current - last_count;

    last_count = current;
    return elapsed;
}

int uart_init(uint8_t uart_id, uint32_t baudrate, uint32_t periph_freq)
{
    uint32_t clk_div;
    uint32_t setup;
    uint32_t cg;

    if ((uart_id >= N_UART) || (baudrate == 0U) || (periph_freq == 0U))
    {
        return -1;
    }

    cg = readw((uintptr_t)(UDMA_CH_ADDR_CTRL + UDMA_CTRL_CG_OFFSET));
    cg |= (uint32_t)(UDMA_CTRL_UART0_CLKEN << uart_id);
    writew(cg, (uintptr_t)(UDMA_CH_ADDR_CTRL + UDMA_CTRL_CG_OFFSET));

    clk_div = periph_freq / baudrate;
    if (clk_div == 0U)
    {
        clk_div = 1U;
    }

    setup = (clk_div << UDMA_UART_DIV_SHIFT) |
            UDMA_UART_TX_ENABLE_BIT |
            UDMA_UART_RX_ENABLE_BIT |
            UDMA_UART_RX_POLLING_BIT |
            UDMA_UART_RX_CLEAN_BIT |
            (UDMA_UART_WORDLEN_8_BITS << 1U);
    writew(setup, uart_base(uart_id) + UDMA_UART_SETUP_OFFSET);

    writew(0U, uart_base(uart_id) + UDMA_UART_RX_SADDR_OFFSET);
    writew(0U, uart_base(uart_id) + UDMA_UART_RX_SIZE_OFFSET);
    writew(0U, uart_base(uart_id) + UDMA_UART_RX_CFG_OFFSET);

    return 0;
}

void uart_write_byte(uint8_t uart_id, uint8_t c)
{
    if (uart_id >= N_UART)
    {
        return;
    }

    uart_tx_byte[uart_id] = c;
    uart_write_buf(uart_id, &uart_tx_byte[uart_id], 1U);
}

int uart_read_byte(uint8_t uart_id)
{
    if (uart_id >= N_UART)
    {
        return -1;
    }

    if ((readw(uart_base(uart_id) + UDMA_UART_VALID_OFFSET) & UDMA_UART_VALID_DATA_BIT) == 0U)
    {
        return -1;
    }

    return (int)(readw(uart_base(uart_id) + UDMA_UART_DATA_OFFSET) & 0xFFU);
}

void uart_write_str(uint8_t uart_id, const char *str)
{
    if (str == NULL)
    {
        return;
    }

    while (*str != '\0')
    {
        uart_write_byte(uart_id, (uint8_t)*str);
        ++str;
    }
}

void uart_write_buf(uint8_t uart_id, const uint8_t *buf, uint32_t len)
{
    uintptr_t base_addr;
    const uint8_t *current;
    uint32_t remaining;

    if ((uart_id >= N_UART) || (buf == NULL) || (len == 0U))
    {
        return;
    }

    base_addr = uart_base(uart_id);
    current = buf;
    remaining = len;

    while (remaining > 0U)
    {
        uint32_t chunk = (remaining > UDMA_UART_MAX_TRANSFER) ? UDMA_UART_MAX_TRANSFER : remaining;

        while ((readw(base_addr + UDMA_UART_STATUS_OFFSET) & UDMA_UART_STATUS_TX_BUSY) != 0U)
        {
        }

        writew((uint32_t)(uintptr_t)current, base_addr + UDMA_UART_TX_SADDR_OFFSET);
        writew(chunk, base_addr + UDMA_UART_TX_SIZE_OFFSET);
        writew(UDMA_UART_TX_CFG_ENABLE, base_addr + UDMA_UART_TX_CFG_OFFSET);

        while ((readw(base_addr + UDMA_UART_TX_CFG_OFFSET) & UDMA_CFG_EN_BIT) != 0U)
        {
        }

        current += chunk;
        remaining -= chunk;
    }
}

