	}

	MemoryContext currContext = MemoryContextSwitchTo(TopMemoryContext);
	InitializedVersionRefreshQuery = pstrdup(initVersionStr);
	MemoryContextSwitchTo(currContext);

	return InitializedVersionRefreshQuery;
}

