static gchar *string_lexicographic_successor(const gchar *value){
  if (value == NULL) {
    return NULL;
  }

  gsize len = strlen(value);
  if (len == 0) {
    return NULL;
  }

  gchar *next = g_strdup(value);
  for (gssize i = (gssize)len - 1; i >= 0; i--) {
    guchar byte = (guchar) next[i];
    if (byte < 255) {
      next[i] = (gchar)(byte + 1);
      next[i + 1] = '\0';
      return next;
    }
  }

  g_free(next);
  return NULL;
}

static gchar *escape_string_value(const gchar *value, gboolean like_pattern){
  GString *escaped = g_string_new("");
  for (const gchar *character = value; character != NULL && *character != '\0'; character++) {
    if (*character == '\\') {
      /* Preserve a literal backslash when MySQL parses the SQL string. */
      g_string_append(escaped, "\\\\\\\\");
    } else if (like_pattern && (*character == '%' || *character == '_')) {
      /* Escape LIKE wildcards so a key prefix is a literal prefix. */
      g_string_append(escaped, "\\\\");
      g_string_append_c(escaped, *character);
    } else if (*character == '\'') {
      g_string_append(escaped, "''");
    } else {
      g_string_append_c(escaped, *character);
    }
  }
  return g_string_free(escaped, FALSE);
}

static gchar *escape_like_sql_string(MYSQL *conn, const gchar *value){
  GString *pattern = g_string_new("");
  for (const gchar *character = value; character != NULL && *character != '\0'; character++) {
    if (*character == '\\' || *character == '%' || *character == '_') {
      g_string_append_c(pattern, '\\');
    }
    g_string_append_c(pattern, *character);
  }

  gchar *escaped = escape_sql_string(conn, pattern->str);
  g_string_free(pattern, TRUE);
  return escaped;
}

static gchar *get_probe_alphabet(MYSQL *conn, struct db_table *dbt){
  gchar *schema = escape_sql_string(conn, dbt->database->source_database);
  gchar *table = escape_sql_string(conn, dbt->table);
  gchar *column = escape_sql_string(conn, (const gchar *)dbt->primary_key->data);
  gchar *query = g_strdup_printf(
      "SELECT COLLATION_NAME FROM information_schema.COLUMNS "
      "WHERE TABLE_SCHEMA='%s' AND TABLE_NAME='%s' AND COLUMN_NAME='%s' LIMIT 1",
      schema, table, column);
  struct M_ROW *mr = m_store_result_row(conn, query, m_warning, m_warning,
                                        "Failed to determine collation for %s.%s",
                                        dbt->database->source_database, dbt->table);
  gchar *alphabet = g_strdup(string_pk_probe_alphabet);

  if (mr != NULL && mr->res != NULL && mr->row != NULL && mr->row[0] != NULL &&
      g_str_has_suffix(mr->row[0], "_ci")) {
    /*
     * LIKE uses the column collation.  Under a case-insensitive collation,
     * both A% and a% select the same rows.  Keep one representative so the
     * generated prefix roots remain disjoint.
     */
    g_free(alphabet);
    alphabet = g_strdup("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ_-");
  }

  if (mr != NULL) {
    m_store_result_row_free(mr);
  }
  g_free(query);
  g_free(schema);
  g_free(table);
  g_free(column);
  return alphabet;
}

static gboolean string_pk_planner_should_use_metadata_internal(guint64 rows){
  return string_pk_planner_should_use_metadata_mode(string_pk_planner_strategy,
                                                     string_pk_planner_metadata_enabled,
                                                     split_string_pk,
                                                     rows,
                                                     string_pk_planner_min_rows);
}

void string_pk_planner_reset_for_table(struct db_table *dbt, guint64 rows){
  if (dbt == NULL) {
    return;
  }

  dbt->string_planner_probe_count = 0;
  dbt->string_planner_budget_exhausted = FALSE;
  dbt->string_planner_started_us = g_get_monotonic_time();
  dbt->string_planner_deadline_us =
      string_pk_planner_timeout_seconds > 0 ?
      dbt->string_planner_started_us + ((gint64)string_pk_planner_timeout_seconds * G_USEC_PER_SEC) :
      0;
  dbt->string_planner_estimated_rows = rows;
}

gboolean string_pk_planner_budget_exhausted(struct db_table *dbt){
  if (dbt == NULL) {
    return TRUE;
  }

  if (dbt->string_planner_budget_exhausted) {
    return TRUE;
  }

  if (dbt->string_planner_deadline_us > 0 && g_get_monotonic_time() > dbt->string_planner_deadline_us) {
    dbt->string_planner_budget_exhausted = TRUE;
    g_warning("String PK planner exceeded the per-table timeout on %s.%s; falling back to the recursive splitter",
              dbt->database->source_database, dbt->table);
    return TRUE;
  }

  if (string_pk_planner_max_probes > 0 && dbt->string_planner_probe_count >= string_pk_planner_max_probes) {
    dbt->string_planner_budget_exhausted = TRUE;
    g_warning("String PK planner exceeded the probe budget on %s.%s; falling back to the recursive splitter",
              dbt->database->source_database, dbt->table);
    return TRUE;
  }

  return FALSE;
}

gboolean string_pk_planner_note_probe(struct db_table *dbt){
  if (dbt == NULL) {
    return FALSE;
  }

  if (string_pk_planner_budget_exhausted(dbt)) {
    return FALSE;
  }

  dbt->string_planner_probe_count++;
  return TRUE;
}

static gchar *escape_sql_string(MYSQL *conn, const gchar *value){
  gulong len = strlen(value);
  gchar *escaped = g_new(gchar, len * 2 + 1);
  mysql_real_escape_string(conn, escaped, value, len);
  return escaped;
}

static gchar *build_prefix_where_clause(MYSQL *conn, struct db_table *dbt, const gchar *prefix){
  gchar *escaped_prefix = escape_like_sql_string(conn, prefix);
  gchar *where_clause = g_strdup_printf("%s%s%s LIKE '%s%%'",
                                        identifier_quote_character_str,
                                        (const gchar *)dbt->primary_key->data,
                                        identifier_quote_character_str,
                                        escaped_prefix);
  gchar *escaped_where_clause = g_strdup_printf("%s ESCAPE '\\\\'", where_clause);
  g_free(where_clause);
  g_free(escaped_prefix);
  return escaped_where_clause;
}

static guint64 estimate_prefix_rows(MYSQL *conn, struct db_table *dbt, const gchar *prefix){
  if (!string_pk_planner_note_probe(dbt)) {
    return 0;
  }

  gchar *where_clause = build_prefix_where_clause(conn, dbt, prefix);
  GString *where = g_string_new(where_clause);
  guint64 rows = get_rows_from_explain(conn, dbt, where, (gchar *)dbt->primary_key->data);
  g_string_free(where, TRUE);
  g_free(where_clause);
  return rows;
}

static struct prefix_estimate *new_prefix_estimate(const gchar *prefix, guint64 rows){
  struct prefix_estimate *pe = g_new0(struct prefix_estimate, 1);
  pe->prefix = g_strdup(prefix);
  pe->rows = rows;
  pe->expandable = TRUE;
  return pe;
}

static void free_prefix_estimate_list(GList *estimates){
  for (GList *iter = estimates; iter != NULL; iter = iter->next) {
    struct prefix_estimate *pe = iter->data;
    g_free(pe->prefix);
    g_free(pe);
  }
  g_list_free(estimates);
}

static gint compare_prefix_estimate_prefix(gconstpointer a, gconstpointer b){
  const struct prefix_estimate *pa = a;
  const struct prefix_estimate *pb = b;
  return g_strcmp0(pa->prefix, pb->prefix);
}

static GList *seed_prefix_level(MYSQL *conn, struct db_table *dbt, const gchar *alphabet){
  GList *level = NULL;
  for (const gchar *character = alphabet; *character != '\0'; character++) {
    gchar candidate[64];
    g_snprintf(candidate, sizeof(candidate), "%c", *character);
    guint64 estimated_rows = estimate_prefix_rows(conn, dbt, candidate);
    if (string_pk_planner_budget_exhausted(dbt)) {
      free_prefix_estimate_list(level);
      return NULL;
    }
    if (estimated_rows == 0) {
      continue;
    }
    level = g_list_append(level, new_prefix_estimate(candidate, estimated_rows));
  }
  return level;
}

static GList *probe_prefix_children(MYSQL *conn, struct db_table *dbt,
                                    const struct prefix_estimate *victim,
                                    guint current_count, const gchar *alphabet,
                                    guint *child_count, gboolean *over_budget,
                                    gboolean *aborted){
  GList *children = NULL;
  *child_count = 0;
  *over_budget = FALSE;
  *aborted = FALSE;

  for (const gchar *character = alphabet; *character != '\0'; character++) {
    gchar child[64];
    g_snprintf(child, sizeof(child), "%s%c", victim->prefix, *character);
    guint64 estimated_rows = estimate_prefix_rows(conn, dbt, child);
    if (string_pk_planner_budget_exhausted(dbt)) {
      *aborted = TRUE;
      free_prefix_estimate_list(children);
      return NULL;
    }
    if (estimated_rows == 0) {
      continue;
    }
    children = g_list_append(children, new_prefix_estimate(child, estimated_rows));
    (*child_count)++;
    /* Replacing one prefix with child_count children is a net +(child_count - 1). */
    if (!string_pk_planner_level_fits_budget(current_count - 1 + *child_count,
                                             string_pk_planner_max_prefixes)) {
      *over_budget = TRUE;
      free_prefix_estimate_list(children);
      return NULL;
    }
  }

  return children;
}

static GList *build_prefix_roots(MYSQL *conn, struct db_table *dbt, guint64 target_rows_per_root, guint *chosen_depth){
  gchar *alphabet = get_probe_alphabet(conn, dbt);

  GList *cover = seed_prefix_level(conn, dbt, alphabet);
  if (cover == NULL || g_list_length(cover) == 0) {
    free_prefix_estimate_list(cover);
    g_free(alphabet);
    if (chosen_depth != NULL) {
      *chosen_depth = 0;
    }
    return NULL;
  }

  guint deepest = 1;
  while (!string_pk_planner_budget_exhausted(dbt)) {
    /* Pick the hottest prefix that is still over target and can be deepened. */
    struct prefix_estimate *victim = NULL;
    for (GList *iter = cover; iter != NULL; iter = iter->next) {
      struct prefix_estimate *pe = iter->data;
      if (!pe->expandable || pe->rows <= target_rows_per_root) {
        continue;
      }
      if (strlen(pe->prefix) >= max_char_size) {
        /* Reached the length ceiling: keep it as a root even if over target. */
        pe->expandable = FALSE;
        continue;
      }
      if (victim == NULL || pe->rows > victim->rows) {
        victim = pe;
      }
    }
    if (victim == NULL) {
      /* Every prefix is at/under target or can no longer be deepened. */
      break;
    }

    guint child_count = 0;
    gboolean over_budget = FALSE;
    gboolean aborted = FALSE;
    GList *children = probe_prefix_children(conn, dbt, victim, g_list_length(cover),
                                            alphabet, &child_count, &over_budget, &aborted);
    if (aborted) {
      /* Out of probe/time budget: keep the complete cover we already have. */
      break;
    }
    if (over_budget || child_count == 0) {
      /*
       * Either splitting this prefix would exceed the prefix budget, or every
       * row equals the prefix itself, so it cannot be split.  Keep it as a root
       * and stop reconsidering it; smaller prefixes and single-child chains
       * (which never grow the total count) may still be split.
       */
      victim->expandable = FALSE;
      continue;
    }

    guint victim_depth = (guint)strlen(victim->prefix) + 1;
    if (victim_depth > deepest) {
      deepest = victim_depth;
    }
    cover = g_list_remove(cover, victim);
    g_free(victim->prefix);
    g_free(victim);
    cover = g_list_concat(cover, children);
  }

  g_free(alphabet);

  if (cover == NULL || g_list_length(cover) == 0) {
    free_prefix_estimate_list(cover);
    if (chosen_depth != NULL) {
      *chosen_depth = 0;
    }
    return NULL;
  }

  cover = g_list_sort(cover, compare_prefix_estimate_prefix);
  if (chosen_depth != NULL) {
    *chosen_depth = deepest;
  }
  return cover;
}

static void append_string_chunk_root(struct db_table *dbt, GList **chunks, const gchar *prefix, guint64 part, guint64 step, guint64 rows_in_explain, guint prefix_len){
  struct chunk_step_item *csi = new_string_step_item(
      FALSE, NULL, (gchar *)dbt->primary_key->data, 0, dbt->is_fixed_length,
      prefix_len, g_strdup(prefix), g_strdup(prefix), step, part,
      FALSE, FALSE, NULL, 0, FALSE, rows_in_explain);
  csi->status = UNASSIGNED;
  *chunks = g_list_append(*chunks, csi);
}

gboolean string_pk_plan_prefix_chunks(MYSQL *conn, struct db_table *dbt, guint64 rows){
  if (!string_pk_planner_enabled_for_table(rows) || dbt == NULL || dbt->primary_key == NULL) {
    return FALSE;
  }

  if (string_pk_planner_budget_exhausted(dbt)) {
    return FALSE;
  }

  guint64 target_rows_per_root = string_pk_planner_compute_target(
      rows, string_pk_planner_target_rows_per_prefix,
      string_pk_planner_max_prefixes, dbt->min_chunk_step_size);

  guint chosen_depth = 0;
  GList *prefixes = build_prefix_roots(conn, dbt, target_rows_per_root, &chosen_depth);
  if (prefixes == NULL || g_list_length(prefixes) == 0) {
    return FALSE;
  }

  /*
   * The chunk step doubles as the per-chunk row target for the runtime string
   * splitter: process_string_chunk_step() dumps a root whole only when its
   * EXPLAIN estimate is at/under the step, and subdivides it further otherwise.
   * Tying the step to target_rows_per_root therefore makes the emitted chunks
   * honor --string-pk-planner-target-rows-per-prefix even for roots the planner
   * had to leave over target (max-char-size or max-prefixes bound), instead of
   * dumping each root as one huge statement.
   */
  guint64 root_step = target_rows_per_root;

  GList *chunks = NULL;
  guint64 part = 0;
  for (GList *iter = prefixes; iter != NULL; iter = iter->next) {
    struct prefix_estimate *pe = iter->data;
    /* Carry the real per-prefix estimate so the runtime split decision is accurate. */
    append_string_chunk_root(dbt, &chunks, pe->prefix, part++, root_step, pe->rows, strlen(pe->prefix));
  }
  free_prefix_estimate_list(prefixes);

  if (chunks == NULL) {
    return FALSE;
  }

  for (GList *iter = chunks; iter != NULL; iter = iter->next) {
    struct chunk_step_item *csi = iter->data;
    dbt->chunks = g_list_append(dbt->chunks, csi);
    g_async_queue_push(dbt->chunks_queue, csi);
  }
  dbt->status = READY;
  g_message("String PK planner selected metadata-assisted prefix chunks for %s.%s "
            "(%u roots, prefix length %u, target %"G_GUINT64_FORMAT" rows/prefix, max prefix length %u)",
            dbt->database->source_database, dbt->table, g_list_length(chunks),
            chosen_depth, target_rows_per_root, max_char_size);
  g_list_free(chunks);
  return TRUE;
}

const gchar *string_pk_planner_strategy_name(enum string_pk_planner_strategy strategy){
  switch (strategy) {
    case STRING_PK_PLANNER_METADATA:
      return "metadata";
    case STRING_PK_PLANNER_RECURSIVE:
      return "recursive";
    case STRING_PK_PLANNER_AUTO:
    default:
      return "auto";
  }
}

gboolean string_pk_planner_strategy_from_string(const gchar *value, enum string_pk_planner_strategy *strategy){
  if (strategy == NULL) {
    return FALSE;
  }

  if (value == NULL || !g_ascii_strcasecmp(value, "auto")) {
    *strategy = STRING_PK_PLANNER_AUTO;
    return TRUE;
  }

  if (!g_ascii_strcasecmp(value, "metadata")) {
    *strategy = STRING_PK_PLANNER_METADATA;
    return TRUE;
  }

  if (!g_ascii_strcasecmp(value, "recursive")) {
    *strategy = STRING_PK_PLANNER_RECURSIVE;
    return TRUE;
  }

  return FALSE;
}

gboolean string_pk_planner_should_use_metadata_mode(enum string_pk_planner_strategy strategy, gboolean metadata_enabled, gboolean split_pk, guint64 rows, guint64 min_rows){
  if (!split_pk || !metadata_enabled) {
    return FALSE;
  }

  switch (strategy) {
    case STRING_PK_PLANNER_METADATA:
      return TRUE;
    case STRING_PK_PLANNER_RECURSIVE:
      return FALSE;
    case STRING_PK_PLANNER_AUTO:
    default:
      return rows >= min_rows;
  }
}

guint64 string_pk_planner_compute_root_step(guint64 rows, guint prefix_count, guint64 min_chunk_step_size_value){
  guint64 root_step = rows > 0 && prefix_count > 0 ? rows / prefix_count : 0;
  if (root_step == 0) {
    root_step = min_chunk_step_size_value > 0 ? min_chunk_step_size_value : 1;
  }
  if (root_step < min_chunk_step_size_value) {
    root_step = min_chunk_step_size_value;
  }
  return root_step;
}

guint64 string_pk_planner_compute_target(guint64 rows, guint64 target_rows_per_prefix, guint max_prefixes, guint64 min_chunk_step_size_value){
  guint64 target = target_rows_per_prefix > 0 ?
      target_rows_per_prefix :
      (max_prefixes > 0 ? rows / max_prefixes : rows);
  if (target == 0) {
    target = 1;
  }
  if (target < min_chunk_step_size_value) {
    target = min_chunk_step_size_value;
  }
  return target;
}

static void test_strategy_parser(void){
  enum string_pk_planner_strategy strategy = STRING_PK_PLANNER_AUTO;

  ASSERT_TRUE("parse auto", string_pk_planner_strategy_from_string("auto", &strategy));
  ASSERT_EQUAL("auto enum", strategy, STRING_PK_PLANNER_AUTO);
  ASSERT_TRUE("parse metadata", string_pk_planner_strategy_from_string("metadata", &strategy));
  ASSERT_EQUAL("metadata enum", strategy, STRING_PK_PLANNER_METADATA);
  ASSERT_TRUE("parse recursive", string_pk_planner_strategy_from_string("recursive", &strategy));
  ASSERT_EQUAL("recursive enum", strategy, STRING_PK_PLANNER_RECURSIVE);
  ASSERT_TRUE("reject invalid", !string_pk_planner_strategy_from_string("nope", &strategy));
}

static void test_strategy_decision(void){
  ASSERT_TRUE("auto enabled on large tables",
              string_pk_planner_should_use_metadata_mode(STRING_PK_PLANNER_AUTO, TRUE, TRUE, 2000000, 1000000));
  ASSERT_TRUE("auto disabled on small tables",
              !string_pk_planner_should_use_metadata_mode(STRING_PK_PLANNER_AUTO, TRUE, TRUE, 100, 1000000));
  ASSERT_TRUE("recursive disables metadata",
              !string_pk_planner_should_use_metadata_mode(STRING_PK_PLANNER_RECURSIVE, TRUE, TRUE, 2000000, 1000000));
  ASSERT_TRUE("metadata forces planner",
              string_pk_planner_should_use_metadata_mode(STRING_PK_PLANNER_METADATA, TRUE, TRUE, 100, 1000000));
  ASSERT_TRUE("disabled string PK planner",
              !string_pk_planner_should_use_metadata_mode(STRING_PK_PLANNER_METADATA, TRUE, FALSE, 2000000, 1000000));
}

static void test_root_step(void){
  ASSERT_EQUAL("rows evenly divided", string_pk_planner_compute_root_step(1000, 10, 100), 100);
  ASSERT_EQUAL("minimum step enforced", string_pk_planner_compute_root_step(10, 100, 50), 50);
  ASSERT_EQUAL("fallback to one", string_pk_planner_compute_root_step(0, 0, 0), 1);
}

static void test_compute_target(void){
  /* target=0 -> derive rows/max_prefixes */
  ASSERT_EQUAL("derived from max-prefixes",
               string_pk_planner_compute_target(1000000, 0, 1000, 0), 1000);
  /* explicit target > 0 is used directly */
  ASSERT_EQUAL("explicit target used",
               string_pk_planner_compute_target(1000000, 5000, 1000, 0), 5000);
  /* explicit target overrides the derived value */
  ASSERT_EQUAL("explicit target overrides derived",
               string_pk_planner_compute_target(1000000, 250, 1000, 0), 250);
  /* min_chunk_step_size acts as a floor */
  ASSERT_EQUAL("min chunk step floor",
               string_pk_planner_compute_target(1000000, 10, 1000, 100), 100);
  /* never returns zero even when inputs would divide to zero */
  ASSERT_EQUAL("never zero",
               string_pk_planner_compute_target(10, 0, 1000, 0), 1);
  /* max_prefixes=0 with no explicit target -> whole table is the target */
  ASSERT_EQUAL("no prefixes cap falls back to rows",
               string_pk_planner_compute_target(777, 0, 0, 0), 777);
}

static void test_level_fits_budget(void){
  ASSERT_TRUE("within budget", string_pk_planner_level_fits_budget(100, 256));
  ASSERT_TRUE("equal to budget fits", string_pk_planner_level_fits_budget(256, 256));
  ASSERT_TRUE("over budget rejected", !string_pk_planner_level_fits_budget(257, 256));
  ASSERT_TRUE("zero budget is unbounded", string_pk_planner_level_fits_budget(1000000, 0));
}

int main(void){
  test_strategy_parser();
  test_strategy_decision();
  test_root_step();
  test_compute_target();
  test_level_fits_budget();

  if (total_failed != 0) {
    fprintf(stderr, "\nFAILED: %d assertion(s)\n", total_failed);
    return 1;
  }

  fprintf(stdout, "\nPASS\n");
  return 0;
}

static inline int
levenshtein_result(int64 res)
{
	if (unlikely(res < PG_INT32_MIN || res > PG_INT32_MAX))
		ereport(ERROR,
				(errcode(ERRCODE_NUMERIC_VALUE_OUT_OF_RANGE),
				 errmsg("levenshtein distance out of range")));
	return res;
}

static const TSK_TCHAR*
get_path_relative_to_base(const LOGICALFS_INFO* logical_fs_info, const TSK_TCHAR* path) {
	size_t base_len = TSTRLEN(logical_fs_info->base_path);
#ifdef TSK_WIN32
	assert(_wcsnicmp(path, logical_fs_info->base_path, base_len) == 0);
#else
	assert(strncmp(path, logical_fs_info->base_path, base_len) == 0);
#endif
	return path + base_len;
}

static TSK_RETVAL_ENUM
get_or_load_cached_dir_files(IMG_LOGICAL_INFO* logical_img_info, TSK_INUM_T dir_inum,
    const TSK_TCHAR* parent_path, vector<wstring>& file_names)
{
    TSK_IMG_INFO* img_info = &logical_img_info->img_info;

    // Search for existing cache entry
    tsk_take_lock(&img_info->cache_lock);

    for (int i = 0; i < DIR_FILE_LIST_CACHE_LEN; i++) {
        if (logical_img_info->dir_file_list_cache.entries[i].dir_inum == dir_inum) {
            // Cache hit: copy the cached file list
            DIR_FILE_CACHE_ENTRY* entry = &logical_img_info->dir_file_list_cache.entries[i];
            file_names.clear();
            for (size_t j = 0; j < entry->file_count; j++) {
                file_names.push_back(entry->file_names[j]);
            }
            tsk_release_lock(&img_info->cache_lock);
            return TSK_OK;
        }
    }

    tsk_release_lock(&img_info->cache_lock);

    // Cache miss: enumerate directory and sort
    vector<wstring> dir_names;
    if (TSK_OK != load_dir_and_file_lists_win(parent_path, file_names, dir_names, LOGICALFS_LOAD_FILES_ONLY)) {
        return TSK_ERR;
    }
    std::sort(file_names.begin(), file_names.end(), case_insensitive_compare);

    // Build the replacement data in local variables FIRST. We only evict the existing
    // slot once we know every allocation has succeeded. If we evicted first and then hit
    // a malloc failure, the slot would be left holding the previous dir_inum (the lookup
    // key) but with file_names = NULL / file_count = 0 - subsequent lookups for that
    // dir_inum would silently return "directory has no files" with TSK_OK, causing the
    // collector to lose every file in that directory.
    TSK_TCHAR** new_file_names = NULL;
    size_t new_file_count = file_names.size();

    if (new_file_count > 0) {
        new_file_names = (TSK_TCHAR**)malloc(sizeof(TSK_TCHAR*) * new_file_count);
        if (new_file_names == NULL) {
            return TSK_ERR;
        }

        for (size_t j = 0; j < new_file_count; j++) {
            size_t name_len = file_names[j].length() + 1;
            new_file_names[j] = (TSK_TCHAR*)malloc(sizeof(TSK_TCHAR) * name_len);
            if (new_file_names[j] == NULL) {
                // Free what we've allocated so far. The existing cache slot is untouched.
                for (size_t k = 0; k < j; k++) {
                    free(new_file_names[k]);
                }
                free(new_file_names);
                return TSK_ERR;
            }
            TSTRNCPY(new_file_names[j], file_names[j].c_str(), name_len);
        }
    }

    // All allocations succeeded - now safe to swap into the cache.
    tsk_take_lock(&img_info->cache_lock);

    int insert_idx = logical_img_info->dir_file_list_cache.next_insert_index;
    DIR_FILE_CACHE_ENTRY* entry = &logical_img_info->dir_file_list_cache.entries[insert_idx];

    // Free the previous occupant's data
    if (entry->file_names != NULL) {
        for (size_t j = 0; j < entry->file_count; j++) {
            free(entry->file_names[j]);
        }
        free(entry->file_names);
    }

    // Install the new data
    entry->file_names = new_file_names;
    entry->file_count = new_file_count;
    entry->dir_inum = dir_inum;

    // Advance to next FIFO slot with wraparound
    logical_img_info->dir_file_list_cache.next_insert_index =
        (insert_idx + 1) % DIR_FILE_LIST_CACHE_LEN;

    tsk_release_lock(&img_info->cache_lock);

    return TSK_OK;
}

SubkeyListRecord::SubkeyListRecordPtr Cell::getLIRecord() const {
        return std::make_unique<LIRecord>(_buf, getAbsoluteOffset(DATA_OFFSET));
        return std::make_unique<DBRecord>(_buf, getAbsoluteOffset(DATA_OFFSET));
        return std::make_unique<DBIndirectRecord>(_buf, getAbsoluteOffset(DATA_OFFSET));
        return std::make_unique<ValueListRecord>(_buf, getAbsoluteOffset(DATA_OFFSET), numValues);

static int elf_flags_to_prot(u32 p_flags)
{
   int prot = 0;

   if (p_flags & PF_R)
      prot |= PROT_READ;

   if (p_flags & PF_W)
      prot |= PROT_WRITE;

   if (p_flags & PF_X)
      prot |= PROT_EXEC;

   return prot;
}

static int
add_base_mapping(struct elf_program_info *pinfo,
                 enum user_mapping_type type,
                 ulong vaddr,
                 size_t len,
                 int prot)
{
   struct user_mapping *um;

   um = new_user_mapping(&pinfo->mi->mappings,
                         type,
                         NULL,        /* pi: assigned later, in setup_process */
                         NULL,        /* h: base regions are unbacked */
                         TO_PTR(vaddr),
                         len,
                         0,           /* off */
                         prot);
   if (!um)
      return -ENOMEM;

   if (type == USER_MAPPING_HEAP)
      pinfo->mi->brk_region = um;

   return 0;
}

void debug_kmalloc_inject_fail_next(void)
{
   if (DEBUG_CHECKS)
      kmalloc_inject_fail_next = true;
}

struct user_mapping *
process_add_user_mapping(fs_handle h,
                         void *vaddr,
                         size_t len,
                         size_t off,
                         int prot)
{
   struct process *pi = get_curr_proc();

   ASSERT(!is_preemption_enabled());
   ASSERT(!process_get_user_mapping(vaddr));
   ASSERT(pi->mi);

   return new_user_mapping(&pi->mi->mappings, USER_MAPPING_MMAP,
                           pi, h, vaddr, len, off, prot);
}

struct mappings_info *alloc_mappings_info(void)
{
   struct mappings_info *mi;

   if (!(mi = kalloc_obj(struct mappings_info)))
      return NULL;

   list_init(&mi->mappings);
   mi->mmap_heap = NULL;
   mi->mmap_heap_size = 0;
   mi->brk_region = NULL;
   return mi;
}

void free_mappings_info(struct mappings_info *mi)
{
   struct user_mapping *um, *tmp;

   if (mi->mmap_heap) {
      kmalloc_destroy_heap(mi->mmap_heap);
      kfree2(mi->mmap_heap, kmalloc_get_heap_struct_size());
   }

   list_for_each(um, tmp, &mi->mappings, pi_node) {
      list_remove(&um->pi_node);
      list_remove(&um->inode_node);
      kfree_obj(um, struct user_mapping);
   }

   kfree_obj(mi, struct mappings_info);
}

static long
ktimer_cmp(const void *a, const void *b)
{
   const struct ktimer *t1 = a;
   const struct ktimer *t2 = b;

   if (t1->wakeup_at_tick != t2->wakeup_at_tick)
      return t1->wakeup_at_tick < t2->wakeup_at_tick ? -1 : 1;

   /*
    * Pointer-address tiebreaker. Two ktimers with the same expiry
    * tick still need a strict ordering for the AVL key; addresses
    * are unique per ktimer instance, so any total order on them
    * works.
    */
   if ((uintptr_t)t1 != (uintptr_t)t2)
      return (uintptr_t)t1 < (uintptr_t)t2 ? -1 : 1;

   return 0;
}

void ktimer_init(struct ktimer *t,
                 void (*fire)(struct ktimer *, void *ctx),
                 void *ctx,
                 enum ktimer_mode mode)
{
   bintree_node_init(&t->tree_node);
   t->wakeup_at_tick = 0;
   t->fire = fire;
   t->ctx = ctx;
   t->mode = mode;
   list_node_init(&t->deferred_node);
}

bool ktimer_is_armed(struct ktimer *t)
{
   ulong var;
   bool armed;

   disable_interrupts(&var);
   {
      armed = t->wakeup_at_tick > 0 ||
              (t->mode == KTIMER_MODE_DEFERRED &&
               list_is_node_in_list(&t->deferred_node));
   }
   enable_interrupts(&var);
   return armed;
}

void task_cancel_wakeup_timer(struct task *ti)
{
   ulong var;
   disable_interrupts(&var);
   {
      ti->timer_ready = false;
   }
   enable_interrupts(&var);

   ktimer_cancel(&ti->primary_timer);
}

id run_pending_ktimers(void)
   ulong var;
   while (true) {

      struct ktimer *t;

      disable_interrupts(&var);
      {
         if (list_is_empty(&deferred_fire_list)) {
            enable_interrupts(&var);
            break;
         }

         t = list_first_obj(&deferred_fire_list,
                            struct ktimer,
                            deferred_node);
         list_remove(&t->deferred_node);
         list_node_init(&t->deferred_node);
      }
      enable_interrupts(&var);

      disable_preemption();
      {
         t->fire(t, t->ctx);
      }
      enable_preemption();
   }

static bool tty_char_echoed_as_caret(struct tty *t, char c)
{
   const struct termios *const ct = &t->c_term;

   return (c < ' ' || c == 0x7F)   &&
          (ct->c_lflag & ECHOCTL)  &&
          c != '\t' && c != '\n'   &&
          c != ct->c_cc[VSTART]    &&
          c != ct->c_cc[VSTOP];
}

bool user_access_resume_on_fault(regs_t *r, bool out_of_mem)
{
   struct task *curr = get_curr_task();

   if (!curr->user_access_fixup)
      return false;

   curr->fault_resume_reason = out_of_mem ? -ENOMEM : 0;
   regs_set_ip(r, (ulong)curr->user_access_fixup);
   return true;
}

void handle_cow_out_of_mem(regs_t *r)
{
   struct task *curr = get_curr_task();

   if (is_fault_resumable(regs_intnum(r))) {

      /*
       * The kernel hit OOM while servicing a CoW page during a fault-resumable
       * primitive (copy_to_user() & friends). Unwind to the caller with -ENOMEM
       * instead of crashing; the faulting page is left untouched (still CoW).
       */
      curr->fault_resume_reason = -ENOMEM;
      handle_resumable_fault(r);    /* NORETURN: unwinds into the primitive */
      NOT_REACHED();
   }

   if (!in_syscall(curr)) {

      /* User-mode CoW fault under memory pressure: kill the process. */
      printk("Out-of-memory: killing pid %d\n", get_curr_pid());
      send_signal(get_curr_pid(), SIGKILL, SIG_FL_PROCESS | SIG_FL_FAULT);
      return;
   }

   /* In-kernel CoW fault outside a resumable primitive == a real bug. */
   panic("Out-of-memory: can't service a CoW page [pid %d]", get_curr_pid());
}

void foo(void)
{
   /* Style 3 (violation): args on one indented line, ) glued to last
    * arg, not on its own line. Same pattern as in
    * tests/unit/avl_bintree.cpp before the using-namespace fix. */
   const auto start = std::chrono::steady_clock::now();
   const auto end = std::chrono::steady_clock::now();
   g_tot += (unsigned long)std::chrono::duration_cast<std::chrono::nanoseconds>(
               end - start).count();
}

void foo(void)
{
   /* 1 :: -- no penalty */
   auto a = std::vector<int>();
   (void)a;

   /* 2 :: -- COST_MINOR (0.10) */
   auto t = std::chrono::steady_clock();
   (void)t;

   /* 4 :: -- capped at COST_MODERATE (0.35) */
   const auto start = std::chrono::steady_clock::now();
   const auto end = std::chrono::steady_clock::now();
   g_tot += (unsigned long)std::chrono::duration_cast<std::chrono::nanoseconds>(
               end - start).count();
}

int style1_caller(void)
{
   return sum4(111, 222,
               333, 444);
}

int style2_caller(void)
{
   return sum4(
      111,
      222,
      333,
      444
   );
}

void foo(void)
{
   /* Single-line call: never wraps, must not trigger anything. */
   const auto start = steady_clock::now();
   const auto end = steady_clock::now();
   g_tot += (unsigned long)duration_cast<nanoseconds>(end - start).count();
}

void single_qualifier(void)
{
   /* Each statement has at most one `::` qualifier chain --
    * no gradient penalty. */
   auto v = stdc::vector<int>();
   (void)v;

   const auto start = steady_clock::now();
   const auto end = steady_clock::now();
   g_tot += (unsigned long)duration_cast<nanoseconds>(end - start).count();
}

void selftest_cow_oom(void)
{
   pdir_t *const pdir = get_curr_pdir();
   const ulong val = 0xcafef00d;
   ulong int_var;
   void *p;
   u32 r;

   if (!DEBUG_CHECKS) {
      printk("cow_oom: needs DEBUG_CHECKS=1 for kmalloc fail injection\n");
      se_regular_end();
      return;
   }

   p = hi_vmem_reserve(PAGE_SIZE);
   VERIFY(p != NULL);

   /* A writable zero page is mapped read-only + CoW: writing to it faults. */
   VERIFY(map_zero_page(pdir, p, PAGING_FL_RW) == 0);

   /*
    * Arm the one-shot failure and trigger the CoW write with interrupts off, so
    * the failure hits our page-copy allocation and not an unrelated kmalloc
    * from an interrupt handler (e.g. ACPICA).
    */
   disable_interrupts(&int_var);
   {
      debug_kmalloc_inject_fail_next();
      r = fault_resumable_call(1 << FAULT_PAGE_FAULT, memcpy, 3,
                               p, &val, sizeof(val));
   }
   enable_interrupts(&int_var);

   /* The write faulted (CoW) and we recovered with -ENOMEM (no panic). */
   VERIFY(r == 1u << FAULT_PAGE_FAULT);
   VERIFY(get_curr_task()->fault_resume_reason == -ENOMEM);

   /* The page was left untouched (still CoW): the same write now succeeds. */
   r = fault_resumable_call(1 << FAULT_PAGE_FAULT, memcpy, 3,
                            p, &val, sizeof(val));
   VERIFY(r == 0);
   VERIFY(*(volatile ulong *)p == val);

   unmap_page(pdir, p, true);
   hi_vmem_release(p, PAGE_SIZE);
   se_regular_end();
}

int cmd_test_hang(int argc, char **argv)
{
   const int kids = 3;
   int i, j, cpid;

   printf("test_hang: parent pid=%d, forking %d children\n",
          getpid(), kids);
   fflush(stdout);

   for (i = 0; i < kids; i++) {

      cpid = fork();

      if (cpid < 0) {
         perror("fork");
         exit(1);
      }

      if (!cpid) {

         /*
          * Grandchild: tick every 500 ms for 30 s. Each tick is a
          * usleep + print, so if SIGKILL reaches us mid-usleep we
          * stop printing immediately; if it doesn't, the ticks
          * keep landing in the output past the watchdog deadline.
          * The SURVIVED line at the end only fires if we complete
          * the full 30 s -- a stronger negative signal than just
          * missing ticks.
          */
         printf("test_hang: child %d pid=%d entered\n", i, getpid());
         fflush(stdout);

         for (j = 0; j < 60; j++) {
            usleep(500 * 1000);
            printf("test_hang: child %d pid=%d alive tick=%d\n",
                   i, getpid(), j);
            fflush(stdout);
         }

         printf("test_hang: child %d pid=%d SURVIVED kill!\n",
                i, getpid());
         fflush(stdout);
         exit(0);
      }
   }

   printf("test_hang: parent pid=%d entering pause()\n", getpid());
   fflush(stdout);
   pause();
   printf("test_hang: parent SURVIVED kill!\n");
   fflush(stdout);
   return 0;
}

void set_user_copy_fault(ulong lo, ulong hi, int fault_after)
{
   uc_fault_lo = lo;
   uc_fault_hi = hi;
   uc_fault_after = fault_after;
   uc_fault_seen = 0;
}

int arch_user_copy(void *dest, const void *src, size_t n)
{
   const ulong s = (ulong)src;
   const ulong d = (ulong)dest;
   char *cd = dest;
   const char *cs = src;
   bool overlap;
   size_t i;

   overlap = uc_fault_lo < uc_fault_hi &&
             ((s < uc_fault_hi && s + n > uc_fault_lo) ||
              (d < uc_fault_hi && d + n > uc_fault_lo));

   if (overlap && uc_fault_after >= 0) {
      if (uc_fault_seen++ >= uc_fault_after)
         return 1;                     /* simulate the unmapped-page fault */
   }

   for (i = 0; i < n; i++)
      cd[i] = cs[i];

   return 0;
}

void feed_key(u8 c) {
      struct key_event ke = {};
      ke.pressed = true;
      ke.print_char = (char)c;
      tty_send_keyevent(t, ke, false);
   }

TEST_F(console_test, scroll_blanks_bottom_row_before_redraw)
{
   /*
    * A newline at the bottom scrolls the screen up by one line. The ring slot
    * that becomes the new bottom row still holds the line that scrolled off the
    * top of the scrollback; the scroll must blank it before (re)drawing it, or
    * the redraw briefly shows that stale line. Fill the whole ring with
    * non-blank rows so the recycled slot is deterministically non-blank, then
    * capture what the next scroll draws for the bottom row: it must be blank.
    */
   /* > total_buffer_rows lines, so the ring buffer wraps around. */
   for (int i = 0; i < 1000; i++)
      console_write("XXXXXXXXXXXXXXXXXXX\r\n");

   capture_bottom_set_row = true;
   console_write("\n");
   capture_bottom_set_row = false;

   for (int j = 0; j < TEST_TERM_COLS; j++)
      ASSERT_EQ((char)vgaentry_get_char(captured_bottom_row[j]), ' ')
         << "bottom row col " << j << " redrawn with stale content";
}

TEST_F(console_test, scrollback_scroll_up_and_down)
{
   for (int i = 0; i < 14; i++) {
      char buf[8];
      snprintf(buf, sizeof(buf), "row%02d\r\n", i);
      console_write(buf);
   }

   check_screen_vs_expected(R"(
      +--------------------+
      |row10               |
      |row11               |
      |row12               |
      |row13               |
      |$                   |
      +--------------------+
   )");

   /* One line back into history: the cursor hides, an older line appears. */
   t->tintf->scroll_up(t->tstate, 1);
   check_screen_vs_expected(R"(
      +--------------------+
      |row09               |
      |row10               |
      |row11               |
      |row12               |
      |row13               |
      +--------------------+
   )");

   /* Three more lines back. */
   t->tintf->scroll_up(t->tstate, 3);
   check_screen_vs_expected(R"(
      +--------------------+
      |row06               |
      |row07               |
      |row08               |
      |row09               |
      |row10               |
      +--------------------+
   )");

   /* Forward two lines. */
   t->tintf->scroll_down(t->tstate, 2);
   check_screen_vs_expected(R"(
      +--------------------+
      |row08               |
      |row09               |
      |row10               |
      |row11               |
      |row12               |
      +--------------------+
   )");

   /* Forward past the end clamps to the bottom; the cursor returns. */
   t->tintf->scroll_down(t->tstate, 100);
   check_screen_vs_expected(R"(
      +--------------------+
      |row10               |
      |row11               |
      |row12               |
      |row13               |
      |$                   |
      +--------------------+
   )");
}

TEST_F(console_test, scrollback_clamps_at_the_top)
{
   for (int i = 0; i < 14; i++) {
      char buf[8];
      snprintf(buf, sizeof(buf), "row%02d\r\n", i);
      console_write(buf);
   }

   /* Scroll far past the top: ts_set_scroll() clamps at the oldest line. */
   t->tintf->scroll_up(t->tstate, 1000);
   check_screen_vs_expected(R"(
      +--------------------+
      |row00               |
      |row01               |
      |row02               |
      |row03               |
      |row04               |
      +--------------------+
   )");

   /* Already clamped: scrolling up further is a no-op. */
   t->tintf->scroll_up(t->tstate, 10);
   check_screen_vs_expected(R"(
      +--------------------+
      |row00               |
      |row01               |
      |row02               |
      |row03               |
      |row04               |
      +--------------------+
   )");
}

TEST_F(console_test, scroll_up_then_new_output_snaps_to_bottom)
{
