    */
   const char ww = (char)t->c_term.c_cc[VWERASE];

   console_write("hello world  ");
   console_write(&ww, 1);
   check_screen_vs_expected(R"(
      +--------------------+
      |hello $             |
      |                    |
      |                    |
      |                    |
      |                    |
      +--------------------+
   )");
}

void SetUp() override {
      saved_base_va = base_va;
      saved_current = __current;

      base_va = (void *)(1ul << 60);    /* every real address is "user" */
      memset(&tsk, 0, sizeof(tsk));     /* user_access_fixup == NULL */
      __current = &tsk;
      set_user_copy_fault(0, 0, -1);    /* no fault by default */
   }

void TearDown() override {
      set_user_copy_fault(0, 0, -1);
      __current = saved_current;
      base_va = saved_base_va;
   }

const char *const *build_argv(const vector<const char *> &args) {
      char **arr = (char **)(void *) ubuf;
      size_t soff = (args.size() + 1) * sizeof(char *);

      for (size_t i = 0; i < args.size(); i++) {
         strcpy(ubuf + soff, args[i]);
         arr[i] = ubuf + soff;
         soff += strlen(args[i]) + 1;
      }

      arr[args.size()] = nullptr;
      return (const char *const *) arr;
   }

TEST_F(user_copy_str, basic)
{
   char dst[64];
   size_t w = 0;
   int rc = __real_copy_str_from_user(dst, "hello", sizeof(dst), &w);

   EXPECT_EQ(rc, 0);
   EXPECT_STREQ(dst, "hello");
   EXPECT_EQ(w, 6u);                    /* "hello" + the NUL */
}

TEST_F(user_copy_str, null_written_ptr)
{
   char dst[16];
   int rc = __real_copy_str_from_user(dst, "hi", sizeof(dst), nullptr);

   EXPECT_EQ(rc, 0);
   EXPECT_STREQ(dst, "hi");
}

TEST_F(user_copy_str, multi_chunk)
{
   /* > USER_STR_COPY_CHUNK (64) forces several read chunks */
   const string big(200, 'a');
   char dst[256];
   size_t w = 0;
   int rc = __real_copy_str_from_user(dst, big.c_str(), sizeof(dst), &w);

   EXPECT_EQ(rc, 0);
   EXPECT_STREQ(dst, big.c_str());
   EXPECT_EQ(w, big.size() + 1);
}

TEST_F(user_copy_str, too_small)
{
   char dst[4];
   size_t w = 0;
   int rc = __real_copy_str_from_user(dst, "hello", sizeof(dst), &w);

   EXPECT_EQ(rc, 1);                    /* no room for the whole string */
}

TEST_F(user_copy_str, zero_max_size)
{
   char dst[1];
   size_t w = 0;
   int rc = __real_copy_str_from_user(dst, "x", 0, &w);

   EXPECT_EQ(rc, 1);
}

TEST_F(user_copy_str, ptr_past_base_va)
{
   char dst[16];
   size_t w = 0;
   int rc = __real_copy_str_from_user(dst, base_va, sizeof(dst), &w);

   EXPECT_EQ(rc, -1);                   /* walked off the user space */
}

TEST_F(user_copy_str, fault_on_unmapped_page)
{
   /*
    * A page-aligned buffer with no NUL: the string starts 8 bytes before the
    * page-0/page-1 boundary and page 1 is "unmapped". The first chunk must
    * stop at the page boundary (and succeed), the second must fault.
    */
   char *pg = (char *) aligned_alloc(PAGE_SIZE, 2 * PAGE_SIZE);
   ASSERT_NE(pg, nullptr);
   memset(pg, 'a', 2 * PAGE_SIZE);

   set_user_copy_fault((ulong)(pg + PAGE_SIZE), (ulong)(pg + 2 * PAGE_SIZE), 0);

   char dst[256];
   size_t w = 0;
   int rc = __real_copy_str_from_user(dst, pg + PAGE_SIZE - 8, sizeof(dst), &w);

   EXPECT_EQ(rc, -1);
   free(pg);
}

TEST_F(user_copy_str, array_basic)
{
   const char *const *argv = build_argv({"a", "bb", "ccc"});
   size_t w = 0;
   int rc = copy_str_array_from_user(dbuf, argv, sizeof(dbuf), &w);
   ASSERT_EQ(rc, 0);

   char **out = (char **)(void *) dbuf;
   EXPECT_STREQ(out[0], "a");
   EXPECT_STREQ(out[1], "bb");
   EXPECT_STREQ(out[2], "ccc");
   EXPECT_EQ(out[3], nullptr);
}

TEST_F(user_copy_str, array_empty)
{
   const char *const *argv = build_argv({});
   size_t w = 0;
   int rc = copy_str_array_from_user(dbuf, argv, sizeof(dbuf), &w);

   ASSERT_EQ(rc, 0);
   EXPECT_EQ(((char **)(void *) dbuf)[0], nullptr);
}

TEST_F(user_copy_str, array_ptr_out_of_range)
{
   /* A pointer array straddling base_va: user_out_of_range() rejects it. */
   const char *const *argv = (const char *const *)(void *)((char *)base_va - 4);
   size_t w = 0;
   int rc = copy_str_array_from_user(dbuf, argv, sizeof(dbuf), &w);

   EXPECT_EQ(rc, -1);
}

TEST_F(user_copy_str, array_ptr_fault)
{
   const char *const *argv = build_argv({"a"});
   size_t w = 0;

   /* The first pointer read faults. */
   set_user_copy_fault((ulong)argv, (ulong)argv + sizeof(void *), 0);
   int rc = copy_str_array_from_user(dbuf, argv, sizeof(dbuf), &w);

   EXPECT_EQ(rc, -1);
}

TEST_F(user_copy_str, array_dest_too_small)
{
   const char *const *argv = build_argv({"a", "b", "c"});
   size_t w = 0;

   /* room for fewer than the 4-pointer array */
   int rc = copy_str_array_from_user(dbuf, argv, 2 * sizeof(void *), &w);
   EXPECT_EQ(rc, 1);
}

TEST_F(user_copy_str, array_string_fault)
{
   const char *const *argv = build_argv({"abc"});
   size_t w = 0;

   /* The argv[0] string itself is "unmapped". */
   set_user_copy_fault((ulong)argv[0], (ulong)argv[0] + 4, 0);
   int rc = copy_str_array_from_user(dbuf, argv, sizeof(dbuf), &w);

   EXPECT_EQ(rc, -1);
}

TEST_F(user_copy_str, array_ptr_reread_fault)
{
   const char *const *argv = build_argv({"a"});
   size_t w = 0;

   /*
    * Let the first read of the pointer (argc loop) through, fault the second
    * (the per-string re-read) -- the only way to reach that defensive branch.
    */
   set_user_copy_fault((ulong)argv, (ulong)argv + sizeof(void *), 1);
   int rc = copy_str_array_from_user(dbuf, argv, sizeof(dbuf), &w);

   EXPECT_EQ(rc, -1);
}

ute_layout(int W)
{
   row_layout c;
   const int gap = 3, bar_min = 10;
   const int avail = W - PAD_L - PAD_R;
   int metrics_w =
      c.lpct_w + 1 + c.lcnt_w + gap + c.fpct_w + 1 + c.fcnt_w;

   c.name_w = std::min(46, avail - metrics_w - bar_min - 2);

   if (c.name_w < 12) {
      c.funcs = false;
      metrics_w = c.lpct_w + 1 + c.lcnt_w;
      c.name_w = std::min(46, avail - metrics_w - bar_min - 2);
   }

   if (c.name_w < 6)
      c.name_w = std::max(4, avail - metrics_w - 6);

   c.name_x = PAD_L;
   c.bar_x = c.name_x + c.name_w + 2;

   const int metrics_x = W - PAD_R - metrics_w;
   c.lpct_x = metrics_x;
   c.lcnt_x = c.lpct_x + c.lpct_w + 1;
   c.fpct_x = c.funcs ? c.lcnt_x + c.lcnt_w + gap : -1;
   c.fcnt_x = c.funcs ? c.fpct_x + c.fpct_w + 1 : -1;

   c.bar_w = metrics_x - 2 - c.bar_x;
   if (c.bar_w < 4)
      c.bar_w = 4;

   return c;
}

/* ---- small drawin

eat(const char *glyph, int n)
{
   std::string s;

   for (int i = 0; i < n; i++)
      s += glyph;

   return s;
}

/*
 * Place `s` in t

WINDOW *w, int y, int x, int fw, const std::string &s,
          chtype attr, bool right)
{
   if (fw <= 0)
      return;

   std::string out;
   const int len = static_cast<int>(s.size());

   if (right) {
      const std::string t = len > fw ? s.substr(0, fw) : s;
      out = std::string(fw - static_cast<int>(t.size()), ' ') + t;
   } else if (len > fw) {
      out = s.substr(0, fw - 1) + GL_ELL;   /* fw columns total */
   } else {
      out = s + std::string(fw - len, ' ');
   }

   wattron(w, attr);
   mvwaddstr(w, y, x, out.c_str());
   wattroff(w, attr);
}

/* Like put_field (l

hl(WINDOW *w, int y, int x, int fw, std::string text,
             chtype base, const std::string &needle, chtype hl)
{
   if (fw <= 0)
      return;

   if (needle.empty()) {
      put_field(w, y, x, fw, text, base, false);
      return;
   }

   if (static_cast<int>(text.size()) > fw)
      text = text.substr(0, fw);

   int col = 0;
   size_t pos = 0;

   const auto emit = [&](const std::string &s, chtype a) {
      if (s.empty())
         return;
      wattron(w, a);
      mvwaddstr(w, y, x + col, s.c_str());
      wattroff(w, a);
      col += static_cast<int>(s.size());
   };

   while (pos < text.size()) {

      const size_t mt = text.find(needle, pos);

      if (mt == std::string::npos) {
         emit(text.substr(pos), base);
         break;
      }

      emit(text.substr(pos, mt - pos), base);
      emit(text.substr(mt, needle.size()), hl);
      pos = mt + needle.size();
   }

   if (col < fw)
      put_field(w, y, x + col, fw - col, "", base, false);
}

static std::string
f

_pct(double p, int total)
{
   if (total <= 0)
      return "-";

   char buf[16];
   snprintf(buf, sizeof(buf), "%.1f%%", p);
   return buf;
}

static std::string
f

_count(int hit, int total)
{
   char buf[24];
   snprintf(buf, sizeof(buf), "%d/%d", hit, total);
   return buf;
}

/*
 * Coverage bar.

INDOW *w, int y, int x, int width, double p, bucket b, bool sel)
{
   if (width <= 0)
      return;

   const double frac = p < 0 ? 0 : (p > 100 ? 100 : p);
   int filled = static_cast<int>(frac / 100.0 * width + 0.5);

   if (filled > width)
      filled = width;

   const chtype fa = sel ? cv_attr(CVP_SEL) : bucket_attr(b);

   if (filled > 0) {
      wattron(w, fa);
      mvwaddstr(w, y, x, repeat(GL_BAR, filled).c_str());
      wattroff(w, fa);
   }

   /*
    * On the selected row the track is left blank -- only the highlight
    * background shows there -- so the white filled blocks stand out
    * cleanly. Off the selection it gets the faint grey track.
    */
   if (filled < width && !sel) {
      const chtype ta = cv_attr(CVP_TRACK);
      wattron(w, ta);
      mvwaddstr(w, y, x + filled, repeat(GL_BAR, width - filled).c_str());
      wattroff(w, ta);
   }
}

/* Clear a body row;

ound(WINDOW *w, int y, bool sel)
{
   const int width = getmaxx(w);

   wmove(w, y, 0);
   wclrtoeol(w);

   if (sel) {
      wattron(w, cv_attr(CVP_SEL));
      mvwhline(w, y, 1, ' ', width - 2);
      wattroff(w, cv_attr(CVP_SEL));
   }
}

/* Shared renderer f

ow(WINDOW *w, int y, const char *icon, const std::string &name,
             int lh, int lf, int fnh, int fnf, bool sel)
{
   const row_layout c = compute_layout(getmaxx(w));
   const chtype sa = cv_attr(CVP_SEL);

   row_background(w, y, sel);

   if (icon) {
      wattron(w, sel ? sa : cv_attr(CVP_ACCENT));
      mvwaddstr(w, y, c.name_x, icon);
      wattroff(w, sel ? sa : cv_attr(CVP_ACCENT));
   }

   const int nx = c.name_x + (icon ? 2 : 0);
   put_field(w, y, nx, c.name_w - (icon ? 2 : 0), name, sel ? sa : 0, false);

   draw_bar(w, y, c.bar_x, c.bar_w, cov_rate(lh, lf), cov_bucket(lh, lf), sel);

   const chtype la = sel ? sa : bucket_attr(cov_bucket(lh, lf));
   put_field(w, y, c.lpct_x, c.lpct_w, fmt_pct(cov_rate(lh, lf), lf), la, true);
   put_field(w, y, c.lcnt_x, c.lcnt_w, fmt_count(lh, lf), la, true);

   if (c.funcs) {
      const chtype fa = sel ? sa : bucket_attr(cov_bucket(fnh, fnf));
      put_field(w, y, c.fpct_x, c.fpct_w,
                fmt_pct(cov_rate(fnh, fnf), fnf), fa, true);
      put_field(w, y, c.fcnt_x, c.fcnt_w, fmt_count(fnh, fnf), fa, true);
   }
}

