void
app::toggle_source_func

)
{
   frame &c = cur();

   if (c.kind == view_kind::source)
      c.kind = view_kind::func_list;
   else if (c.kind == view_kind::func_list)
      c.kind = view_kind::source;
   else
      return;

   c.top = c.sel = c.hoff = 0;
   c.sort_mode = 0;
   enter_view();
}

void
app::on_enter()
{
   co

t frame &c = cur();

   if (c.kind == view_kind::dir_list) {

      push(view_kind::file_list, rows[sv.selected()], -1);

   } else if (c.kind == view_kind::file_list) {

      push(view_kind::source, c.dir_idx, rows[sv.selected()]);

   } else if (c.kind == view_kind::func_list) {

      const file_cov &f = m.files[c.file_idx];
      const int line = f.funcs[rows[sv.selected()]].line;

      cur().kind = view_kind::source;
      cur().top = cur().sel = cur().hoff = 0;
      cur().sort_mode = 0;
      enter_view();
      sv.goto_index(line > 0 ? line - 1 : 0);
      doupdate();
   }
}

void
app::handle_key(int ch)

const bool in_source = cur().kind == view_kind::source;

   /* A transient status message clears on the next keystroke. */
   if (!status.empty()) {
      status.clear();
      draw_footer();
      doupdate();
   }

   switch (ch) {

      case KEY_DOWN: case 'j': sv.move_sel(1); doupdate(); break;
      case KEY_UP:   case 'k': sv.move_sel(-1); doupdate(); break;
      case KEY_NPAGE: sv.page(1); doupdate(); break;
      case KEY_PPAGE: sv.page(-1); doupdate(); break;
      case '<': case KEY_HOME: sv.to_first(); doupdate(); break;
      case '>': case KEY_END:  sv.to_last(); doupdate(); break;

      case '\n': case '\r': case KEY_ENTER:
         on_enter();
         break;

      case '\t': case 'f':
         toggle_source_funcs();
         break;

      case 's':
         cycle_sort();
         break;

      case 'g':
         goto_line();
         break;

      case '/':
         start_search(1);
         break;

      case '?':
         if (in_source)
            start_search(-1);
         else
            show_help();
         break;

      case 'n': search_move(1); break;
      case 'N': search_move(-1); break;

      case 27:   /* ESC */
         clear_search();
         break;

      case KEY_BACKSPACE: case 127: case 'u':
         back();
         break;

      case KEY_RIGHT: case 'l':
         if (in_source) {
            sv.h_scroll(8);
            doupdate();
         } else {
            on_enter();
         }
         break;

      case KEY_LEFT: case 'h':
         if (in_source) {
            sv.h_scroll(-8);
            doupdate();
         } else {
            back();
         }
         break;

      case KEY_RESIZE:
         layout();
         enter_view();
         break;

      default:
         break;
   }
}

void
app::run()
{
   setloca

(LC_ALL, "");

   initscr();
   cbreak();
   noecho();
   keypad(stdscr, TRUE);
   curs_set(0);
   set_escdelay(25);   /* make a lone ESC responsive */
   colors_init();

   frame root;
   root.kind = view_kind::dir_list;
   stack.push_back(root);

   layout();
   enter_view();

   int ch;

   while ((ch = getch()) != 'q' && ch != 'Q')
      handle_key(ch);

   if (body)
      delwin(body);
   if (sbar)
      delwin(sbar);

   endwin();
}

bool
colors_enabled()
{
   return g_color;
}

static void
init_256()
{
   init_pair(CVP_TITLE, 254, 60);
   init_pair(CVP_LO, 167, -1);
   init_pair(CVP_MED, 179, -1);
   init_pair(CVP_HI, 108, -1);
   init_pair(CVP_DIM, 240, -1);
   init_pair(CVP_TRACK, 236, -1);   /* faint grey bar track */
   init_pair(CVP_SEL, 254, 24);
   init_pair(CVP_ACCENT, 110, -1);
   init_pair(CVP_MATCH, 232, 215);   /* dark on amber */
}

static void
init_16()
{
   init_pair(CVP_TITLE, COLOR_WHITE, COLOR_BLUE);
   init_pair(CVP_LO, COLOR_RED, -1);
   init_pair(CVP_MED, COLOR_YELLOW, -1);
   init_pair(CVP_HI, COLOR_GREEN, -1);
   init_pair(CVP_DIM, COLOR_WHITE, -1);
   init_pair(CVP_TRACK, COLOR_BLACK, -1);
   init_pair(CVP_SEL, COLOR_WHITE, COLOR_BLUE);
   init_pair(CVP_ACCENT, COLOR_CYAN, -1);
   init_pair(CVP_MATCH, COLOR_BLACK, COLOR_YELLOW);
}

void
colors_init()
{
   if (!has_colors()) {
      g_color = false;
      return;
   }

   g_color = true;
   start_color();
   use_default_colors();

   if (COLORS >= 256)
      init_256();
   else
      init_16();
}

chtype
cv_attr(cv_pair p)
{
   if (!g_color) {
      switch (p) {
         case CVP_TITLE: return A_REVERSE;
         case CVP_SEL:   return A_REVERSE;
         case CVP_LO:    return A_BOLD;
         case CVP_DIM:   return A_DIM;
         case CVP_TRACK: return A_DIM;
         case CVP_MATCH: return A_REVERSE;
         default:        return A_NORMAL;
      }
   }

   if (p == CVP_DIM && COLORS < 256)
      return COLOR_PAIR(p) | A_DIM;

   return COLOR_PAIR(p);
}

chtype
bucket_attr(bucket b)
{
   switch (b) {
      case bucket::lo:  return cv_attr(CVP_LO);
      case bucket::med: return cv_attr(CVP_MED);
      case bucket::hi:  return cv_attr(CVP_HI);
      case bucket::none: break;
   }

   return cv_attr(CVP_DIM);
}

static cli_args
parse_args(int argc, char **argv)
{
   cli_args a;

   for (int i = 1; i < argc; i++) {

      const std::string arg = argv[i];

      if (arg == "-h" || arg == "--help")
         a.help = true;
      else if (arg == "--dump")
         a.dump = true;
      else if (!arg.empty() && arg[0] == '-')
         a.bad = true;
      else
         a.info_path = arg;
   }

   if (a.info_path.empty())
      a.info_path = std::string(COVVIEW_BUILD_DIR) + "/coverage.info";

   return a;
}

static void
usage(const char *prog)
{
   printf("Usage: %s [OPTIONS] [coverage.info]\n\n", prog);
   printf("Browse LCOV coverage data in the terminal, a functional\n");
   printf("equivalent of the genhtml HTML report.\n\n");
   printf("Arguments:\n");
   printf("  coverage.info    LCOV tracefile to open\n");
   printf("                   (default: %s/coverage.info)\n\n",
          COVVIEW_BUILD_DIR);
   printf("Options:\n");
   printf("  -h, --help       show this help and exit\n");
   printf("      --dump       print parsed totals and exit (no UI)\n\n");
   printf("Keys:\n");
   printf("  arrows / j k     move          Enter / l   open\n");
   printf("  PgUp PgDn g G    page / ends    Backspace   back\n");
   printf("  Tab / f          source<->funcs  s          cycle sort\n");
   printf("  h l              pan source     ? / q       help / quit\n");
}

static void
dump_model(const coverage_model &m)
{
   printf("coverage.info: %s\n", m.info_path.c_str());
   printf("test: %s   date: %s\n", m.test_name.c_str(), m.date.c_str());
   printf("files: %zu   dirs: %zu\n", m.files.size(), m.dirs.size());
   printf("lines:     %d / %d  (%.1f %%)\n",
          m.lh, m.lf, cov_rate(m.lh, m.lf));
   printf("functions: %d / %d  (%.1f %%)\n",
          m.fnh, m.fnf, cov_rate(m.fnh, m.fnf));
}

int
main(int argc, char **argv)
{
   const cli_args args = parse_args(argc, argv);

   if (args.bad) {
      usage(argv[0]);
      return 1;
   }

   if (args.help) {
      usage(argv[0]);
      return 0;
   }

   coverage_model m;
   std::string err;

   if (!load_coverage(args.info_path, m, err)) {
      fprintf(stderr, "coverage-viewer: %s\n", err.c_str());
      return 1;
   }

   if (args.dump) {
      dump_model(m);
      return 0;
   }

   app a(m);
   a.run();
   return 0;
}

double
cov_rate(int hit, int total)
{
   return total > 0 ? 100.0 * hit / total : 0.0;
}

bucket
cov_bucket(int hit, int total)
{
   if (total <= 0)
      return bucket::none;

   const double p = cov_rate(hit, total);

   if (p >= 90.0)
      return bucket::hi;

   if (p >= 75.0)
      return bucket::med;

   return bucket::lo;
}

static bool
split_num_comma(const std::string &s, long long &num, std::string &rest)
{
   const size_t comma = s.find(',');

   if (comma == std::string::npos)
      return false;

   num = std::strtoll(s.c_str(), nullptr, 10);
   rest = s.substr(comma + 1);
   return true;
}

static void
format_file_mtime(const std::string &path, std::string &out)
{
   struct stat st;

   if (stat(path.c_str(), &st) != 0) {
      out = "(unknown)";
      return;
   }

   char buf[32];
   struct tm tm_buf;
   const time_t t = st.st_mtime;

   localtime_r(&t, &tm_buf);
   strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_buf);
   out = buf;
}

static void
aggregate(coverage_model &m)
{
   std::vector<std::string> abs_paths;
   abs_paths.reserve(m.files.size());

   for (const file_cov &f : m.files)
      abs_paths.push_back(f.abs_path);

   const std::string prefix = util::common_dir_prefix(abs_paths);
   std::map<std::string, int> dir_index;

   for (size_t i = 0; i < m.files.size(); i++) {

      file_cov &f = m.files[i];

      f.rel_path = util::starts_with(f.abs_path, prefix.c_str())
                      ? f.abs_path.substr(prefix.size())
                      : f.abs_path;
      f.dir = util::dir_of(f.rel_path);
      f.name = util::base_of(f.rel_path);

      f.lf = static_cast<int>(f.line_hits.size());
      f.lh = 0;

      for (const auto &kv : f.line_hits)
         if (kv.second > 0)
            f.lh++;

      f.fnf = static_cast<int>(f.funcs.size());
      f.fnh = 0;

      for (const func_cov &fn : f.funcs)
         if (fn.hits > 0)
            f.fnh++;

      auto it = dir_index.find(f.dir);

      if (it == dir_index.end()) {
         it = dir_index.emplace(f.dir, static_cast<int>(m.dirs.size())).first;
         m.dirs.emplace_back();
         m.dirs.back().path = f.dir;
      }

      dir_cov &d = m.dirs[it->second];
      d.files.push_back(static_cast<int>(i));
      d.lf += f.lf;
      d.lh += f.lh;
      d.fnf += f.fnf;
      d.fnh += f.fnh;

      m.lf += f.lf;
      m.lh += f.lh;
      m.fnf += f.fnf;
      m.fnh += f.fnh;
   }

   /* Default order: directories and files sorted by name. */
   std::sort(m.dirs.begin(), m.dirs.end(),
             [](const dir_cov &a, const dir_cov &b) {
                return a.path < b.path;
             });

   for (dir_cov &d : m.dirs)
      std::sort(d.files.begin(), d.files.end(),
                [&m](int a, int b) {
                   return m.files[a].name < m.files[b].name;
                });
}

bool
load_coverage(const std::string &path, coverage_model &m, std::string &err)
{
   std::ifstream f(path);

   if (!f) {
      err = "cannot open '" + path + "'";
      return false;
   }

   m.info_path = path;

   file_cov *cur = nullptr;
   std::map<std::string, size_t> fn_idx;   /* per-file name -> func index */
   std::string line;

   while (std::getline(f, line)) {

      if (!line.empty() && line.back() == '\r')
         line.pop_back();

      if (util::starts_with(line, "SF:")) {

         m.files.emplace_back();
         cur = &m.files.back();
         cur->abs_path = line.substr(3);
         fn_idx.clear();

      } else if (line == "end_of_record") {

         cur = nullptr;

      } else if (util::starts_with(line, "TN:")) {

         if (m.test_name.empty())
            m.test_name = line.substr(3);

      } else if (!cur) {

         continue;

      } else if (util::starts_with(line, "DA:")) {

         long long count;
         std::string rest;

         if (split_num_comma(line.substr(3), count, rest))
            cur->line_hits[static_cast<int>(count)] =
               std::strtoll(rest.c_str(), nullptr, 10);

      } else if (util::starts_with(line, "FNDA:")) {

         long long count;
         std::string name;

         if (split_num_comma(line.substr(5), count, name)) {

            auto it = fn_idx.find(name);

            if (it != fn_idx.end())
               cur->funcs[it->second].hits = count;
            else {
               fn_idx[name] = cur->funcs.size();
               cur->funcs.push_back(func_cov{name, 0, count});
            }
         }

      } else if (util::starts_with(line, "FN:")) {

         long long fline;
         std::string name;

         if (split_num_comma(line.substr(3), fline, name) &&
             fn_idx.find(name) == fn_idx.end())
         {
            fn_idx[name] = cur->funcs.size();
            cur->funcs.push_back(func_cov{name, static_cast<int>(fline), -1});
         }
      }
      /* LF/LH/FNF/FNH/BRDA and the rest are recomputed/ignored. */
   }

   if (m.test_name.empty())
      m.test_name = util::base_of(path);

   format_file_mtime(path, m.date);
   aggregate(m);
   return true;
}

void
scroll_view::init(WINDOW *win, draw_row_fn draw_cb)
{
   w = win;
   draw = std::move(draw_cb);

   /*
    * idlok lets ncurses use the terminal's insert/delete-line + scroll
    * region to satisfy our explicit wscrl() calls. scrollok stays OFF
    * here (so painting a row's rightmost cell can't auto-scroll the
    * list); apply() turns it on only momentarily around its wscrl().
    */
   idlok(w, TRUE);
   keypad(w, TRUE);
}

void
scroll_view::set_on_change(std::function<void()> cb)
{
   on_change = std::move(cb);
}

void
scroll_view::notify()
{
   if (on_change)
      on_change();
}

int
scroll_view::body_h() const
{
   return getmaxy(w);
}

int
scroll_view::max_top() const
{
   const int m = n - body_h();
   return m > 0 ? m : 0;
}

void
scroll_view::clear_line(int y)
{
   wmove(w, y, 0);
   wclrtoeol(w);
}

void
scroll_view::draw_at(int idx, bool selected)
{
   const int y = idx - tp;

   if (y < 0 || y >= body_h())
      return;

   if (idx < n)
      draw(w, y, idx, hoff, selected);
   else
      clear_line(y);
}

void
scroll_view::redraw()
{
   const int h = body_h();

   for (int y = 0; y < h; y++) {

      const int idx = tp + y;

      if (idx < n)
         draw(w, y, idx, hoff, idx == sel);
      else
         clear_line(y);
   }

   wnoutrefresh(w);
   notify();
}

void
scroll_view::apply(int new_top, int new_sel)
{
   const int h = body_h();

   new_top = std::max(0, std::min(new_top, max_top()));
   new_sel = std::max(0, std::min(new_sel, n > 0 ? n - 1 : 0));

   const int old_sel = sel;
   const int dt = new_top - tp;

   if (dt == 0) {

      tp = new_top;
      sel = new_sel;

      if (old_sel != new_sel) {
         draw_at(old_sel, false);
         draw_at(new_sel, true);
      }

      wnoutrefresh(w);
      notify();
      return;
   }

   if (std::abs(dt) >= h) {
      tp = new_top;
      sel = new_sel;
      redraw();   /* redraw() calls notify() */
      return;
   }

   /* Native scroll by dt, then repaint only the newly exposed rows.
    *
    * scrollok must be on for wscrl() to do anything, but it must be off
    * the rest of the time, otherwise drawing a row's rightmost cell
    * auto-scrolls the whole list. So enable it only around wscrl(). */
   tp = new_top;
   sel = new_sel;
   scrollok(w, TRUE);
   wscrl(w, dt);
   scrollok(w, FALSE);

   if (dt > 0) {
      for (int y = h - dt; y < h; y++)
         draw_at(tp + y, tp + y == sel);
   } else {
      for (int y = 0; y < -dt; y++)
         draw_at(tp + y, tp + y == sel);
   }

   /* Un-highlight the old selection (if still visible) and ensure the new
    * one is highlighted; both are no-ops if already handled above. */
   if (old_sel != sel)
      draw_at(old_sel, false);

   draw_at(sel, true);
   wnoutrefresh(w);
   notify();
}

void
scroll_view::set_rows(int count)
{
   n = count;

   if (sel >= n)
      sel = n > 0 ? n - 1 : 0;

   if (tp > max_top())
      tp = max_top();

   redraw();
}

void
scroll_view::move_sel(int delta)
{
   if (n == 0)
      return;

   const int new_sel = std::max(0, std::min(sel + delta, n - 1));

   if (new_sel == sel)
      return;

   int new_top = tp;
   const int h = body_h();

   if (new_sel < tp)
      new_top = new_sel;
   else if (new_sel >= tp + h)
      new_top = new_sel - h + 1;

   apply(new_top, new_sel);
}

void
scroll_view::scroll_rows(int delta)
{
   if (n == 0)
      return;

   int new_top = std::max(0, std::min(tp + delta, max_top()));
   int new_sel = sel;
   const int h = body_h();

   /* Keep the selection within the new viewport. */
   if (new_sel < new_top)
      new_sel = new_top;
   else if (new_sel >= new_top + h)
      new_sel = new_top + h - 1;

   apply(new_top, new_sel);
}

void
scroll_view::page(int dir)
{
   const int h = body_h();
   apply(tp + dir * h, sel + dir * h);
}

void
scroll_view::to_first()
{
   apply(0, 0);
}

void
scroll_view::to_last()
{
   apply(max_top(), n > 0 ? n - 1 : 0);
}

void
scroll_view::goto_index(int idx)
{
   idx = std::max(0, std::min(idx, n > 0 ? n - 1 : 0));

   int new_top = tp;
   const int h = body_h();

   if (idx < tp || idx >= tp + h)
      new_top = idx - h / 2;   /* center the target */

   apply(new_top, idx);
}

void
scroll_view::h_scroll(int delta)
{
   const int new_off = std::max(0, hoff + delta);

   if (new_off == hoff)
      return;

   hoff = new_off;
   redraw();
}

void
scroll_view::set_h_off(int off)
{
   hoff = std::max(0, off);
   redraw();
}

void
scroll_view::restore(int top_row, int sel_row, int h_off_)
{
   tp = std::max(0, std::min(top_row, max_top()));
   sel = std::max(0, std::min(sel_row, n > 0 ? n - 1 : 0));
   hoff = std::max(0, h_off_);
   redraw();
}

static std::string
expand_tabs(const std::string &in)
{
   std::string out;
   out.reserve(in.size());

   for (char c : in) {

      if (c == '\t') {

         do {
            out.push_back(' ');
         } while (out.size() % 8 != 0);

      } else if (c != '\r') {

         out.push_back(c);
      }
   }

   return out;
}

void
source_file::load(const std::string &path)
{
   std::ifstream f(path);

   if (!f) {
      loaded = false;
      return;
   }

   std::string line;

   while (std::getline(f, line))
      lines.push_back(expand_tabs(line));

   loaded = true;
}

std::string
common_dir_prefix(const std::vector<std::string> &paths)
{
   if (paths.empty())
      return std::string();

   std::string lcp = paths[0];

   for (const std::string &s : paths) {

      size_t i = 0;

      while (i < lcp.size() && i < s.size() && lcp[i] == s[i])
         i++;

      lcp.resize(i);
   }

   /* Keep the prefix up to and including the last '/'. */
   const size_t slash = lcp.rfind('/');
   return slash == std::string::npos ? std::string() : lcp.substr(0, slash + 1);
}

static int test_timeout_ms(enum timeout_type tt)
{
   switch (tt) {
      case TT_SHORT: return  12 * 1000;
      case TT_MED:   return  36 * 1000;
      case TT_LONG:  return 108 * 1000;
   }
   return 36 * 1000;
}

