	return create_invoicereq(cmd, ir);
}

bool str_to_u64(const char *buf, size_t buflen, u64 *num)
{
	u64 val = 0;

	if (buflen == 0)
		return false;

	for (size_t i = 0; i < buflen; i++) {
		u64 digit;
		if (buf[i] < '0' || buf[i] > '9')
			return false;
		digit = buf[i] - '0';
		if (val > (UINT64_MAX - digit) / 10)
			return false;
		val = val * 10 + digit;
	}
	*num = val;
	return true;
}

static void watch_newindex_scripts(struct lightningd *ld,
				   u64 keyidx,
				   enum addrtype addrtype)
{
	struct pubkey pubkey;
	const u8 *scriptpubkey;
	bool legacy = (ld->bip86_base == NULL);
	u32 start_block = UINT32_MAX;

	if (ld->bip86_base)
		bip86_pubkey(ld, &pubkey, keyidx);
	else
		bip32_pubkey(ld, &pubkey, keyidx);

	if (addrtype & ADDR_BECH32) {
		scriptpubkey = scriptpubkey_p2wpkh(tmpctx, &pubkey);
		wallet_add_bwatch_scriptpubkey(ld, keyidx, start_block,
					       scriptpubkey,
					       tal_bytelen(scriptpubkey));

		/* Pre-24.11 ADDR_ALL can include legacy wrapped form. */
		if (addrtype == ADDR_ALL && legacy) {
			const u8 *p2sh = scriptpubkey_p2sh(tmpctx, scriptpubkey);
			wallet_add_bwatch_scriptpubkey(ld, keyidx, start_block,
						       p2sh,
						       tal_bytelen(p2sh));
		}
	}

	if (addrtype & ADDR_P2TR) {
		scriptpubkey = scriptpubkey_p2tr(tmpctx, &pubkey);
		wallet_add_bwatch_scriptpubkey(ld, keyidx, start_block,
					       scriptpubkey,
					       tal_bytelen(scriptpubkey));
	}
}

void init_wallet_scriptpubkey_watches(struct wallet *w)
{
	struct wallet_address_htable_iter it;
	u64 bip32_max_index = db_get_intvar(w->db, "bip32_max_index", 0);
	u64 bip86_max_index = db_get_intvar(w->db, "bip86_max_index", 0);
	u64 max_index = bip32_max_index > bip86_max_index
		? bip32_max_index : bip86_max_index;
	u32 start_block = UINT32_MAX;

	/* Extend the table to cover every key we've derived plus lookahead;
	 * same rule wallet_can_spend applies. */
	while (w->our_addresses_maxindex < max_index + w->keyscan_gap)
		our_addresses_add_for_index(w, ++w->our_addresses_maxindex);

	for (struct wallet_address *waddr
		     = wallet_address_htable_first(w->our_addresses, &it);
	     waddr;
	     waddr = wallet_address_htable_next(w->our_addresses, &it)) {
		wallet_add_bwatch_scriptpubkey(w->ld, waddr->index, start_block,
					       waddr->swl.script, waddr->swl.len);
	}
}

static bool bwatch_enabled(const struct lightningd *ld)
{
	const char **names = tal_arr(tmpctx, const char *, 1);

	names[0] = "experimental-bwatch";
	return configvar_first(ld->configvars, names) != NULL;
}

static void test_set_p2sh_script(const tal_t *ctx, struct utxo *u, u8 fill)
{
	u->scriptPubkey = tal_arr(ctx, u8, BITCOIN_SCRIPTPUBKEY_P2SH_LEN);
	u->scriptPubkey[0] = OP_HASH160;
	u->scriptPubkey[1] = 20;
	memset(u->scriptPubkey + 2, fill, 20);
	u->scriptPubkey[22] = OP_EQUAL;
}

static void test_set_p2wpkh_script(const tal_t *ctx, struct utxo *u, u8 fill)
{
	u->scriptPubkey = tal_arr(ctx, u8, BITCOIN_SCRIPTPUBKEY_P2WPKH_LEN);
	u->scriptPubkey[0] = OP_0;
	u->scriptPubkey[1] = 20;
	memset(u->scriptPubkey + 2, fill, 20);
}

static void test_set_p2wsh_script(const tal_t *ctx, struct utxo *u, u8 fill)
{
	u->scriptPubkey = tal_arr(ctx, u8, BITCOIN_SCRIPTPUBKEY_P2WSH_LEN);
	u->scriptPubkey[0] = OP_0;
	u->scriptPubkey[1] = 32;
	memset(u->scriptPubkey + 2, fill, 32);
}

static bool test_add_hd_output(struct wallet *w, const struct utxo *u)
{
	u32 blockheight = u->blockheight ? *u->blockheight : 0;

	if (wallet_utxo_get(w, w, &u->outpoint))
		return false;

	wallet_add_our_output(w, &u->outpoint, blockheight, 1,
			      u->scriptPubkey, tal_bytelen(u->scriptPubkey),
			      u->amount, u->keyindex);
	return true;
}

