static bool addrtype_from_script(const u8 *script, size_t script_len,
				 enum addrtype *addrtype)
{
	if (is_p2wpkh(script, script_len, NULL))
		*addrtype = ADDR_BECH32;
	else if (is_p2tr(script, script_len, NULL))
		*addrtype = ADDR_P2TR;
	else if (is_p2sh(script, script_len, NULL))
		*addrtype = ADDR_P2SH_SEGWIT;
	else
		return false;
	return true;
}

static const char *spk_owner_form(enum addrtype addrtype)
{
	switch (addrtype) {
	case ADDR_BECH32:
		return "p2wpkh";
	case ADDR_P2TR:
		return "p2tr";
	case ADDR_P2SH_SEGWIT:
		return "p2sh_p2wpkh";
	case ADDR_ALL:
		break;
	}
	abort();
}

void wallet_add_bwatch_scriptpubkey(struct lightningd *ld,
				    u64 keyindex,
				    u32 start_block,
				    const u8 *script,
				    size_t script_len)
{
	enum addrtype addrtype;

	if (!addrtype_from_script(script, script_len, &addrtype)) {
		log_broken(ld->wallet->log,
			   "Not watching unrecognized wallet script %s (keyindex %"PRIu64")",
			   tal_hexstr(tmpctx, script, script_len), keyindex);
		return;
	}

	watchman_watch_scriptpubkey(ld,
				    owner_wallet_spk(tmpctx, keyindex,
						     spk_owner_form(addrtype)),
				    script, script_len, start_block);
}

void wallet_add_our_output(struct wallet *w,
			   const struct bitcoin_outpoint *outpoint,
			   u32 blockheight, u32 txindex,
			   const u8 *script, size_t script_len,
			   struct amount_sat sat,
			   u32 keyindex)
{
	struct db_stmt *stmt;

	stmt = db_prepare_v2(w->db,
		SQL("INSERT INTO our_outputs "
		    "(txid, outnum, blockheight, txindex, scriptpubkey, satoshis, keyindex) "
		    "VALUES (?, ?, ?, ?, ?, ?, ?) "
		    "ON CONFLICT(txid,outnum) DO NOTHING;"));
	db_bind_txid(stmt, &outpoint->txid);
	db_bind_int(stmt, outpoint->n);
	db_bind_int(stmt, blockheight);
	db_bind_int(stmt, txindex);
	db_bind_blob(stmt, script, script_len);
	db_bind_amount_sat(stmt, sat);
	db_bind_int(stmt, keyindex);
	db_exec_prepared_v2(take(stmt));

	if (blockheight != 0) {
		stmt = db_prepare_v2(w->db,
			SQL("UPDATE our_outputs SET blockheight = ?, txindex = ? "
			    "WHERE txid = ? AND outnum = ? AND blockheight < ?;"));
		db_bind_int(stmt, blockheight);
		db_bind_int(stmt, txindex);
		db_bind_txid(stmt, &outpoint->txid);
		db_bind_int(stmt, outpoint->n);
		db_bind_int(stmt, blockheight);
		db_exec_prepared_v2(take(stmt));
	}
}

void wallet_add_our_tx(struct wallet *w, const struct wally_tx *tx,
		       u32 blockheight, u32 txindex)
{
	struct db_stmt *stmt;
	struct bitcoin_txid txid;

	wally_txid(tx, &txid);

	stmt = db_prepare_v2(w->db,
			     SQL("INSERT OR REPLACE INTO our_txs "
				 "(txid, blockheight, txindex, rawtx) VALUES (?, ?, ?, ?);"));
	db_bind_txid(stmt, &txid);
	db_bind_int(stmt, blockheight);
	db_bind_int(stmt, txindex);
	db_bind_talarr(stmt, linearize_wtx(tmpctx, tx));
	db_exec_prepared_v2(take(stmt));
}

static bool wallet_watch_get_output(struct wallet *w,
				    const struct bitcoin_tx *tx,
				    size_t outnum,
				    struct wallet_watch_output *output)
{
	struct amount_asset asset;

	if (outnum >= tx->wtx->num_outputs) {
		log_broken(w->log, "Invalid outnum %zu for tx with %zu outputs",
			   outnum, tx->wtx->num_outputs);
		return false;
	}

	output->txout = &tx->wtx->outputs[outnum];
	asset = wally_tx_output_get_amount(output->txout);

	/* Elements outputs can hold arbitrary assets.  Only the chain's main
	 * asset belongs in our bitcoin-denominated wallet tables. */
	if (!amount_asset_is_main(&asset)) {
		log_debug(w->log, "Ignoring non-main asset output");
		return false;
	}

	bitcoin_txid(tx, &output->outpoint.txid);
	output->outpoint.n = outnum;
	output->amount = amount_asset_to_sat(&asset);
	return true;
}

static enum utxotype utxotype_from_addrtype(enum addrtype addrtype)
{
	/* No default: adding an address type should force this mapping to be
	 * considered.  ADDR_ALL is a selector, never a concrete output type. */
	switch (addrtype) {
	case ADDR_P2SH_SEGWIT:
		return UTXO_P2SH_P2WPKH;
	case ADDR_BECH32:
		return UTXO_P2WPKH;
	case ADDR_P2TR:
		return UTXO_P2TR;
	case ADDR_ALL:
		break;
	}
	abort();
}

static void bwatch_got_utxo(struct wallet *w,
			    u64 keyindex,
			    enum addrtype addrtype,
			    const struct wallet_watch_output *output,
			    bool is_coinbase,
			    u32 blockheight,
			    u32 txindex)
{
	enum utxotype utxotype = utxotype_from_addrtype(addrtype);
	u32 start_block;

	log_debug(w->log, "Owning output %u %s (%s) txid %s%s%s",
		  output->outpoint.n,
		  fmt_amount_sat(tmpctx, output->amount),
		  utxotype_to_str(utxotype),
		  fmt_bitcoin_txid(tmpctx, &output->outpoint.txid),
		  blockheight ? " CONFIRMED" : "",
		  is_coinbase ? " COINBASE" : "");

	/* Coin movements describe final ledger history, so an unconfirmed
	 * discovery is persisted below but does not emit one yet. */
	if (blockheight)
		wallet_save_chain_mvt(
			w->ld,
			new_coin_wallet_deposit(tmpctx, &output->outpoint,
						blockheight, output->amount,
						mk_mvt_tags(MVT_DEPOSIT)));

	wallet_add_our_output(w, &output->outpoint,
			      blockheight, txindex, output->txout->script,
			      output->txout->script_len, output->amount, keyindex);

	/* Start at the containing block when confirmed.  For a mempool
	 * discovery, start at today's tip so a later spend cannot be missed. */
	start_block = blockheight
		? blockheight : get_block_height(w->ld->topology);
	watchman_watch_outpoint(w->ld,
				owner_wallet_utxo(tmpctx, &output->outpoint),
				&output->outpoint, start_block);

	/* Unconfirmed: keep watching the scriptpubkey so bwatch tells us when
	 * the output confirms.  UINT32_MAX = perennial watch: never skip on
	 * reorg, never rescan. */
	if (!blockheight)
		wallet_add_bwatch_scriptpubkey(w->ld, keyindex, UINT32_MAX,
					       output->txout->script,
					       output->txout->script_len);
}

static bool spk_watch_suffix_to_keyindex(const char *suffix, u32 *keyindex)
{
	char *end;
	unsigned long long val;

	/* The keyindex is the decimal number before the '/'. */
	val = strtoull(suffix, &end, 10);

	/* There must be at least one digit... */
	if (end == suffix)
		return false;
	/* ...then the '/' separator and a non-empty form... */
	if (end[0] != '/' || end[1] == '\0')
		return false;
	/* ...and BIP32 key indexes fit in 32 bits. */
	if (val > UINT32_MAX)
		return false;

	*keyindex = val;
	return true;
}

void wallet_watch_spk(struct lightningd *ld,
		      const char *suffix,
		      const struct bitcoin_tx *tx,
		      size_t outnum,
		      u32 blockheight,
		      u32 txindex)
{
	struct wallet *w = ld->wallet;
	u32 keyindex;
	struct wallet_watch_output output;
	enum addrtype addrtype;
	bool is_coinbase = blockheight != 0 && txindex == 0;

	if (!spk_watch_suffix_to_keyindex(suffix, &keyindex)) {
		log_broken(w->log, "wallet/spk watch_found: invalid suffix %s",
			   suffix);
		return;
	}

	if (!wallet_watch_get_output(w, tx, outnum, &output))
		return;

	if (!addrtype_from_script(output.txout->script,
				  output.txout->script_len, &addrtype)) {
		log_broken(w->log, "wallet/spk watch_found: unrecognized script %s",
			   tal_hex(tmpctx, output.txout->script));
		return;
	}

	/* Invoice accounting and wallet persistence are separate consumers of
	 * the same discovery.  Check the invoice before recording the output,
	 * matching the ordering in the legacy scan path. */
	invoice_check_onchain_payment(ld, output.txout->script, output.amount,
				      &output.outpoint);

	/* Store the full transaction before the output that refers to it. */
	wallet_add_our_tx(w, tx->wtx, blockheight, txindex);

	/* Record the owned output, its deposit metadata and its spend watch. */
	bwatch_got_utxo(w, keyindex, addrtype, &output, is_coinbase,
			blockheight, txindex);
}

void wallet_scriptpubkey_watch_revert(struct lightningd *ld,
				      const char *suffix,
				      u32 blockheight)
{
	struct wallet *w = ld->wallet;
	struct db_stmt *stmt;
	u32 keyindex;

	if (!spk_watch_suffix_to_keyindex(suffix, &keyindex)) {
		log_broken(w->log, "wallet/spk watch_revert: invalid suffix %s",
			   suffix);
		return;
	}

	/* The tx confirmed at this height, so demote it wherever some
	 * output of it was recorded for this key.  Do this before the
	 * our_outputs demotion below wipes the height we match on. */
	stmt = db_prepare_v2(w->db,
		SQL("UPDATE our_txs SET blockheight = 0, txindex = 0 "
		    "WHERE blockheight = ? "
		    "AND txid IN (SELECT txid FROM our_outputs "
		    "             WHERE keyindex = ? AND blockheight = ?)"));
	db_bind_int(stmt, blockheight);
	db_bind_int(stmt, keyindex);
	db_bind_int(stmt, blockheight);
	db_exec_prepared_v2(take(stmt));

	stmt = db_prepare_v2(w->db,
		SQL("UPDATE our_outputs SET blockheight = 0, txindex = 0 "
		    "WHERE keyindex = ? AND blockheight = ?"));
	db_bind_int(stmt, keyindex);
	db_bind_int(stmt, blockheight);
	db_exec_prepared_v2(take(stmt));
}

static u64 wallet_max_addr_index(struct wallet *w, enum addrtype addrtype)
{
	if (addrtype == ADDR_P2TR)
		return w->bip86_max_index;
	return w->bip32_max_index;
}

static void wallet_set_max_addr_index(struct wallet *w, enum addrtype addrtype,
				      u64 index)
{
	if (addrtype == ADDR_P2TR) {
		w->bip86_max_index = index;
		db_set_intvar(w->db, "bip86_max_index", index);
	} else {
		w->bip32_max_index = index;
		db_set_intvar(w->db, "bip32_max_index", index);
	}
}

nt
cedulauy_select_app(struct sc_card *card)
{
	struct sc_apdu apdu;
	unsigned char resp[SC_MAX_APDU_RESP_SIZE];

	LOG_FUNC_CALLED(card->ctx);

	sc_format_apdu_ex(&apdu, card->cla, 0xA4, 0x04, 0x00,
			cedulauy_aid, sizeof cedulauy_aid, resp, sizeof resp);
	SC_TRANSMIT_TEST_RET(card, apdu, "Cannot select the eID application");

	LOG_FUNC_RETURN(card->ctx, SC_SUCCESS);
}

static

nt
cedulauy_match_card(struct sc_card *card)
{
	int i = _sc_match_atr(card, cedulauy_atrs, &card->type);

	if (i < 0)
		return 0;
	card->name = cedulauy_atrs[i].name;
	return 1;
}

static

nt
cedulauy_init(struct sc_card *card)
{
	unsigned long flags;
	int r;

	LOG_FUNC_CALLED(card->ctx);

	card->caps = SC_CARD_CAP_RNG;

	r = cedulauy_select_app(card);
	LOG_TEST_RET(card->ctx, r, "Cannot select the eID application");

	/* The card builds the DigestInfo on-card only for SHA-256 (algorithm
	 * reference 0x42).  Everything else is signed as raw PKCS#1 v1.5 over
	 * a DigestInfo built in software (algorithm reference 0x02). */
	flags = SC_ALGORITHM_RSA_PAD_PKCS1 | SC_ALGORITHM_RSA_HASH_NONE | SC_ALGORITHM_RSA_HASH_SHA256;
	r = _sc_card_add_rsa_alg(card, 2048, flags, 0);

	LOG_FUNC_RETURN(card->ctx, r);
}

static

nt
cedulauy_card_reader_lock_obtained(struct sc_card *card, int was_reset)
{
	if (was_reset)
		LOG_FUNC_RETURN(card->ctx, cedulauy_select_app(card));
	LOG_FUNC_RETURN(card->ctx, SC_SUCCESS);
}

static

onst sc_file_t *
cedulauy_get_mf()
{
	static sc_file_t *mf = NULL;
	if (!mf) {
		mf = sc_file_new();
		if (mf) {
			mf->path = *sc_get_mf_path();
			mf->id = 0x3F00;
			mf->type = SC_FILE_TYPE_DF;
			mf->magic = SC_FILE_MAGIC;
		}
	}
	return mf;
}

static

nt
cedulauy_select_file(struct sc_card *card, const struct sc_path *in_path,
		struct sc_file **file_out)
{
	struct sc_path path = *in_path;

	LOG_FUNC_CALLED(card->ctx);

	if (path.aid.len == sizeof cedulauy_aid && 0 == memcmp(path.aid.value, cedulauy_aid, sizeof cedulauy_aid)) {
		/* swallow cedula AID, it is always selected via init() */
		path.aid.len = 0;
	}
	if (path.type == SC_PATH_TYPE_PATH && path.len >= 2 && path.value[0] == 0x3F && path.value[1] == 0x00) {
		/* swallow MF, everything resides within the Application DF */
		memmove(path.value, path.value + 2, path.len - 2);
		path.len -= 2;
	}
	if (path.type == SC_PATH_TYPE_PATH && path.len == 0) {
		/* Selection of MF was requested */
		sc_file_dup(file_out, cedulauy_get_mf());
		LOG_FUNC_RETURN(card->ctx, SC_SUCCESS);
	}

	LOG_FUNC_RETURN(card->ctx, iso_ops->select_file(card, &path, file_out));
}

static

nt
cedulauy_set_security_env(struct sc_card *card, const struct sc_security_env *env,
		int se_num)
{
	struct sc_apdu apdu;
	/* MSE SET, Digital Signature Template: key reference and algorithm */
	unsigned char mse_data[] = {0x84, 0x01, 0xFF, 0x80, 0x01, CEDULAUY_ALGO_RSA_PKCS1};

	LOG_FUNC_CALLED(card->ctx);

	if (env == NULL)
		LOG_FUNC_RETURN(card->ctx, SC_ERROR_INVALID_ARGUMENTS);
	if (env->operation != SC_SEC_OPERATION_SIGN)
		LOG_FUNC_RETURN(card->ctx, SC_ERROR_NOT_SUPPORTED);
	if ((env->flags & SC_SEC_ENV_ALG_PRESENT) && env->algorithm != SC_ALGORITHM_RSA)
		LOG_FUNC_RETURN(card->ctx, SC_ERROR_NOT_SUPPORTED);
	if (env->key_ref_len != 1)
		LOG_FUNC_RETURN(card->ctx, SC_ERROR_NOT_SUPPORTED);

	mse_data[2] = env->key_ref[0];
	if (env->algorithm_flags & SC_ALGORITHM_RSA_HASH_SHA256)
		mse_data[5] = CEDULAUY_ALGO_RSA_PKCS1_SHA256;

	sc_format_apdu_ex(&apdu, card->cla, 0x22, 0x41, 0xB6,
			mse_data, sizeof mse_data, NULL, 0);
	SC_TRANSMIT_TEST_RET(card, apdu, "MSE SET DST failed");

	LOG_FUNC_RETURN(card->ctx, SC_SUCCESS);
}

static

nt
cedulauy_compute_signature(struct sc_card *card, const u8 *data, size_t datalen,
		u8 *out, size_t outlen)
{
	struct sc_apdu apdu;
	unsigned char sbuf[64];
	unsigned char rbuf[256]; /* RSA 2048 */
	size_t offs = 0;

	LOG_FUNC_CALLED(card->ctx);

	if (data == NULL || out == NULL)
		LOG_FUNC_RETURN(card->ctx, SC_ERROR_INVALID_ARGUMENTS);

	/* What is loaded here matches the algorithm set in set_security_env:
	 * for 0x42 'data' is the bare SHA-256 digest and the card builds the
	 * DigestInfo; for 0x02 'data' is a complete DigestInfo built in
	 * software, which the card pads (PKCS#1 v1.5) as-is. */
	if (datalen == 0 || datalen > sizeof(sbuf) - 2)
		LOG_TEST_RET(card->ctx, SC_ERROR_NOT_SUPPORTED,
				"Unsupported hash/DigestInfo length");

	/* PSO HASH: load the digest */
	sbuf[offs++] = 0x90;
	sbuf[offs++] = (unsigned char)datalen;
	memcpy(sbuf + offs, data, datalen);
	offs += datalen;
	sc_format_apdu_ex(&apdu, card->cla, 0x2A, 0x90, 0xA0, sbuf, offs, NULL, 0);
	SC_TRANSMIT_TEST_RET(card, apdu, "PSO HASH failed");

	/* PSO COMPUTE DIGITAL SIGNATURE */
	sc_format_apdu_ex(&apdu, card->cla, 0x2A, 0x9E, 0x9A, NULL, 0, rbuf, sizeof rbuf);
	SC_TRANSMIT_TEST_RET(card, apdu, "PSO COMPUTE DIGITAL SIGNATURE failed");

	if (apdu.resplen > outlen)
		LOG_TEST_RET(card->ctx, SC_ERROR_BUFFER_TOO_SMALL,
				"Signature buffer too small");
	memcpy(out, apdu.resp, apdu.resplen);
	LOG_FUNC_RETURN(card->ctx, (int)apdu.resplen);
}

static

nt
cedulauy_get_challenge(struct sc_card *card, u8 *rnd, size_t len)
{
	/* As on other IAS/ECC cards, GET CHALLENGE only handles a length of 8 */
	unsigned char rbuf[8];
	int r;

	LOG_FUNC_CALLED(card->ctx);

	r = iso_ops->get_challenge(card, rbuf, sizeof rbuf);
	LOG_TEST_RET(card->ctx, r, "GET CHALLENGE failed");

	if (len < (size_t)r)
		r = (int)len;
	memcpy(rnd, rbuf, (size_t)r);

	LOG_FUNC_RETURN(card->ctx, r);
}

static

nt
cedulauy_logout(struct sc_card *card)
{
	/* Re-selecting the application resets its security status. */
	LOG_FUNC_RETURN(card->ctx, cedulauy_select_app(card));
}

struct

c_card_driver *
sc_get_cedulauy_driver(void)
{
	struct sc_card_driver *iso_drv = sc_get_iso7816_driver();

	if (iso_ops == NULL)
		iso_ops = iso_drv->ops;

	cedulauy_ops = *iso_ops;
	cedulauy_ops.match_card = cedulauy_match_card;
	cedulauy_ops.init = cedulauy_init;
	cedulauy_ops.select_file = cedulauy_select_file;
	cedulauy_ops.set_security_env = cedulauy_set_security_env;
	cedulauy_ops.compute_signature = cedulauy_compute_signature;
	cedulauy_ops.decipher = NULL; /* the signing key is sign-only */
	cedulauy_ops.get_challenge = cedulauy_get_challenge;
	cedulauy_ops.logout = cedulauy_logout;
	cedulauy_ops.card_reader_lock_obtained = cedulauy_card_reader_lock_obtained;

	return &cedulauy_drv;
}

int
sc_pkcs15emu_cedulauy_init(struct sc_pkcs15_card *p15card)
{
	struct sc_context *ctx = p15card->card->ctx;
	struct sc_aid aid;
	int r;

	struct sc_pkcs15_auth_info pin_info = {0};
	struct sc_pkcs15_object pin_obj = {0};
	struct sc_pkcs15_cert_info cert_info = {0};
	struct sc_pkcs15_object cert_obj = {0};
	struct sc_pkcs15_prkey_info prkey_info = {0};
	struct sc_pkcs15_object prkey_obj = {0};
	struct sc_pkcs15_cert *cert = NULL;
	struct sc_app_info *appinfo;

	LOG_FUNC_CALLED(ctx);

	memcpy(aid.value, cedulauy_aid, sizeof cedulauy_aid);
	aid.len = sizeof cedulauy_aid;

	appinfo = calloc(1, sizeof(struct sc_app_info));
	if (appinfo == NULL) {
		LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
	}
	appinfo->aid = aid;
	appinfo->ddo.aid = aid;
	p15card->app = appinfo;

	/* Global PIN (reference 0x11, ASCII numeric, zero-padded to 12 bytes). */
	pin_info.auth_id.value[0] = CEDULAUY_OBJ_ID;
	pin_info.auth_id.len = 1;
	pin_info.auth_type = SC_PKCS15_PIN_AUTH_TYPE_PIN;
	pin_info.attrs.pin.reference = CEDULAUY_PIN_REF;
	pin_info.attrs.pin.flags = SC_PKCS15_PIN_FLAG_INITIALIZED | SC_PKCS15_PIN_FLAG_NEEDS_PADDING;
	pin_info.attrs.pin.type = SC_PKCS15_PIN_TYPE_ASCII_NUMERIC;
	pin_info.attrs.pin.min_length = 4;
	pin_info.attrs.pin.stored_length = 12;
	pin_info.attrs.pin.max_length = 12;
	pin_info.attrs.pin.pad_char = 0x00;
	pin_info.tries_left = -1;
	pin_info.max_tries = -1;
	strlcpy(pin_obj.label, "PIN", sizeof pin_obj.label);
	r = sc_pkcs15emu_add_pin_obj(p15card, &pin_obj, &pin_info);
	LOG_TEST_RET(ctx, r, "Cannot add Global PIN object");

	/* Signing certificate (EF B001 under the IAS application). */
	sc_format_path("i" CEDULAUY_CERT_FID, &cert_info.path); /* 'i' => select by file ID */
	cert_info.path.aid = aid;
	cert_info.id.value[0] = CEDULAUY_OBJ_ID;
	cert_info.id.len = 1;
	strlcpy(cert_obj.label, "Certificado de Firma", sizeof cert_obj.label);
	r = sc_pkcs15emu_add_x509_cert(p15card, &cert_obj, &cert_info);
	LOG_TEST_RET(ctx, r, "Cannot add signing certificate object");

	/* Set the token label and serial number from the certificate, when
	 * readable.  The serial number also keys the file cache. */
	if (sc_pkcs15_read_certificate(p15card, &cert_info, 0, &cert) == SC_SUCCESS) {
		static const struct sc_object_id cn_oid = {
				{2, 5, 4, 3, -1}
		};
		u8 *cn = NULL;
		size_t cn_len = 0;
		const u8 *serial = cert->serial;
		size_t serial_len = cert->serial_len;

		sc_pkcs15_get_name_from_dn(ctx, cert->subject, cert->subject_len,
				&cn_oid, &cn, &cn_len);
		if (cn_len > 0) {
			char *label = malloc(cn_len + 1);
			if (label) {
				memcpy(label, cn, cn_len);
				label[cn_len] = '\0';
				free(p15card->tokeninfo->label);
				p15card->tokeninfo->label = label;
			}
		}
		free(cn);

		/* strip the ASN.1 INTEGER header, if present */
		if (serial_len > 2 && serial[0] == 0x02 && serial[1] == serial_len - 2) {
			serial += 2;
			serial_len -= 2;
		}
		if (serial_len > 0) {
			char *sn = malloc(serial_len * 2 + 1);
			if (sn) {
				sc_bin_to_hex(serial, serial_len, sn, serial_len * 2 + 1, 0);
				free(p15card->tokeninfo->serial_number);
				p15card->tokeninfo->serial_number = sn;
			}
		}

		sc_pkcs15_free_certificate(cert);
	}

	/* Signing private key (reference 0x01, RSA 2048, PIN-protected). */
	prkey_info.id.value[0] = CEDULAUY_OBJ_ID;
	prkey_info.id.len = 1;
	prkey_info.usage = SC_PKCS15_PRKEY_USAGE_SIGN | SC_PKCS15_PRKEY_USAGE_NONREPUDIATION;
	prkey_info.native = 1;
	prkey_info.key_reference = CEDULAUY_KEY_REF;
	prkey_info.modulus_length = 2048;
	prkey_obj.auth_id.value[0] = CEDULAUY_OBJ_ID;
	prkey_obj.auth_id.len = 1;
	prkey_obj.flags = SC_PKCS15_CO_FLAG_PRIVATE;
	strlcpy(prkey_obj.label, "Clave de Firma", sizeof prkey_obj.label);
	r = sc_pkcs15emu_add_rsa_prkey(p15card, &prkey_obj, &prkey_info);
	LOG_TEST_RET(ctx, r, "Cannot add signing private key object");

	LOG_FUNC_RETURN(ctx, SC_SUCCESS);
}

int

_pkcs15emu_cedulauy_init_ex(struct sc_pkcs15_card *p15card, struct sc_aid *aid)
{
	if (p15card->card->type != SC_CARD_TYPE_CEDULAUY)
		return SC_ERROR_WRONG_CARD;

	return sc_pkcs15emu_cedulauy_init(p15card);
}

static bool IsAllowedExecName(const char *execName)
{
    static const char *allowedExecNames[] = { "gcore" };

    if(execName == NULL)
    {
        return false;
    }

    for(size_t i = 0; i < sizeof(allowedExecNames)/sizeof(allowedExecNames[0]); i++)
    {
        if(strcmp(execName, allowedExecNames[i]) == 0)
        {
            return true;
        }
    }

    return false;
}

