static idteck_codec *idteck_alloc(void) {
    idteck_codec *d = malloc(sizeof(idteck_codec));
    memset(d->data, 0, IDTECK_DATA_SIZE);
    return d;
}

static bool idteck_decoder_feed(idteck_codec *d, uint16_t val) {
    (void)d;
    (void)val;
    return false;
}

static const nrf_pwm_sequence_t *idteck_modulator(idteck_codec *d, uint8_t *buf) {
    (void)d;

    size_t n = lf_psk1_build_sequence(buf, IDTECK_BIT_COUNT,
                                      m_idteck_pwm_seq_vals, IDTECK_PWM_ENTRIES);
    m_idteck_pwm_seq.length = (uint16_t)(n * 4);   // 4 uint16 fields per wave-form entry
    return &m_idteck_pwm_seq;
}

uint8_t idteck_t55xx_writer(uint8_t *uid, uint32_t *blks) {
    uint32_t hi = 0, lo = 0;
    for (int i = 0; i < 4; i++) hi = (hi << 8) | uid[i];
    for (int i = 4; i < 8; i++) lo = (lo << 8) | uid[i];
    blks[0] = T5577_IDTECK_CONFIG;
    blks[1] = hi;
    blks[2] = lo;
    return IDTECK_T55XX_BLOCK_COUNT;
}

size_t lf_psk1_build_sequence(const uint8_t *frame_bytes,
                              size_t bit_count,
                              nrf_pwm_values_wave_form_t *out_buf,
                              size_t out_capacity) {
    size_t required = bit_count * LF_PSK1_RF32_SUBCYCLES_PER_BIT;
    if (required > out_capacity) {
        return 0;
    }

    bool phase = false;
    bool last_bit = read_last_bit(frame_bytes, bit_count);

    size_t k = 0;
    for (size_t bit_idx = 0; bit_idx < bit_count; bit_idx++) {
        bool cur_bit = read_bit_msb_first(frame_bytes, bit_idx);
        if (cur_bit != last_bit) {
            phase = !phase;
        }
        last_bit = cur_bit;

        uint16_t pol = phase ? (1U << 15) : 0;
        for (size_t c = 0; c < LF_PSK1_RF32_SUBCYCLES_PER_BIT; c++) {
            out_buf[k].channel_0 = pol | LF_PSK1_SUBCARRIER_DUTY;
            out_buf[k].channel_1 = 0;
            out_buf[k].channel_2 = 0;
            out_buf[k].counter_top = LF_PSK1_SUBCARRIER_TOP;
            k++;
        }
    }

    return k;
}

uint8_t write_idteck_to_t55xx(uint8_t *data, uint8_t *new_passwd, uint8_t *old_passwds, uint8_t old_passwd_count) {
    uint32_t blks[7] = {0x00};
    uint8_t blk_count = idteck_t55xx_writer(data, blks);
    if (blk_count == 0) return STATUS_PAR_ERR;
    return write_t55xx(blks, blk_count, new_passwd, old_passwds, old_passwd_count);
}

nt8_t lf_t55xx_write_block(uint8_t block, uint32_t word, uint32_t passwd, bool use_passwd, bool page1) {
    uint8_t opcode = page1 ? T5577_OPCODE_PAGE1 : T5577_OPCODE_PAGE0;
    uint32_t *pwd_ptr = use_passwd ? &passwd : NULL;

    start_lf_125khz_radio();
    bsp_delay_ms(1);  // Delay for a while after starting the field

    t55xx_send_cmd(opcode, pwd_ptr, 0, &word, block);
    t55xx_send_cmd(T5577_OPCODE_RESET, NULL, 0, NULL, 0);

    stop_lf_125khz_radio();
    return STATUS_LF_TAG_OK;
}
#

static data_frame_tx_t *cmd_processor_jablotron_scan(uint16_t cmd, uint16_t status, uint16_t length, uint8_t *data) {
    uint8_t card_buffer[5] = {0x00};
    status = scan_jablotron(card_buffer);
    if (status != STATUS_LF_TAG_OK) {
        return data_frame_make(cmd, status, 0, NULL);
    }
    return data_frame_make(cmd, STATUS_LF_TAG_OK, sizeof(card_buffer), card_buffer);
}

static data_frame_tx_t *cmd_processor_jablotron_write_to_t55xx(uint16_t cmd, uint16_t status, uint16_t length, uint8_t *data) {
    typedef struct {
        uint8_t id[5];
        uint8_t new_key[4];
        uint8_t old_keys[4];
    } PACKED payload_t;
    payload_t *payload = (payload_t *)data;
    if (length < sizeof(payload_t) || (length - offsetof(payload_t, old_keys)) % sizeof(payload->old_keys) != 0) {
        return data_frame_make(cmd, STATUS_PAR_ERR, 0, NULL);
    }
    status = write_jablotron_to_t55xx(payload->id, payload->new_key, payload->old_keys, (length - offsetof(payload_t, old_keys)) / sizeof(payload->old_keys));
    return data_frame_make(cmd, status, 0, NULL);
}

static data_frame_tx_t *cmd_processor_jablotron_set_emu_id(uint16_t cmd, uint16_t status, uint16_t length, uint8_t *data) {
    if (length != LF_JABLOTRON_TAG_ID_SIZE) {
        return data_frame_make(cmd, STATUS_PAR_ERR, 0, NULL);
    }
    tag_data_buffer_t *buffer = get_buffer_by_tag_type(TAG_TYPE_JABLOTRON);
    memcpy(buffer->buffer, data, LF_JABLOTRON_TAG_ID_SIZE);
    tag_emulation_load_by_buffer(TAG_TYPE_JABLOTRON, false);
    return data_frame_make(cmd, STATUS_SUCCESS, 0, NULL);
}

static data_frame_tx_t *cmd_processor_jablotron_get_emu_id(uint16_t cmd, uint16_t status, uint16_t length, uint8_t *data) {
    tag_slot_specific_type_t tag_types;
    tag_emulation_get_specific_types_by_slot(tag_emulation_get_slot(), &tag_types);
    if (tag_types.tag_lf != TAG_TYPE_JABLOTRON) {
        return data_frame_make(cmd, STATUS_PAR_ERR, 0, data);
    }
    tag_data_buffer_t *buffer = get_buffer_by_tag_type(TAG_TYPE_JABLOTRON);
    return data_frame_make(cmd, STATUS_SUCCESS, LF_JABLOTRON_TAG_ID_SIZE, buffer->buffer);
}

bool lf_tag_jablotron_data_factory(uint8_t slot, tag_specific_type_t tag_type) {
    // default id: 5 bytes (top bit must be 0)
    uint8_t tag_id[5] = {0x01, 0xB6, 0x69, 0x00, 0x00};
    return lf_tag_data_factory(slot, tag_type, tag_id, sizeof(tag_id));
}

static uint64_t jablotron_raw_data(uint8_t *uid) {
    uint64_t raw = (uint64_t)0xFFFF << 48;  // preamble

    // 40-bit data (5 bytes) at bits 47-8
    uint8_t chksum = 0;
    for (int i = 0; i < JABLOTRON_DATA_SIZE; i++) {
        raw |= ((uint64_t)uid[i]) << (40 - 8 * i);
        chksum += uid[i];
    }

    // 8-bit checksum at bits 7-0
    raw |= (uint64_t)((chksum ^ 0x3A) & 0xFF);

    return raw;
}

static uint8_t jablotron_period(uint8_t interval) {
    if (jablotron_get_time(interval, JABLOTRON_READ_TIME1_BASE)) {
        return 0;
    }
    if (jablotron_get_time(interval, JABLOTRON_READ_TIME2_BASE)) {
        return 1;
    }
    if (jablotron_get_time(interval, JABLOTRON_READ_TIME3_BASE)) {
        return 2;
    }
    return 3;
}

static jablotron_codec *jablotron_alloc(void) {
    jablotron_codec *codec = malloc(sizeof(jablotron_codec));
    codec->modem = malloc(sizeof(diphase));
    codec->modem->rp = jablotron_period;
    return codec;
}

static void jablotron_free(jablotron_codec *d) {
    if (d->modem) {
        free(d->modem);
        d->modem = NULL;
    }
    free(d);
}

static void jablotron_decoder_start(jablotron_codec *d, uint8_t format) {
    memset(d->data, 0, JABLOTRON_DATA_SIZE);
    d->raw = 0;
    d->raw_length = 0;
    diphase_reset(d->modem);
}

static bool jablotron_decode_feed(jablotron_codec *d, bool bit) {
    d->raw <<= 1;
    d->raw_length++;
    if (bit) {
        d->raw |= 0x01;
    }
    if (d->raw_length < JABLOTRON_RAW_SIZE) {
        return false;
    }

    // Check preamble: upper 16 bits must be 0xFFFF
    if (((d->raw >> 48) & 0xFFFF) != 0xFFFF) {
        return false;
    }

    // Bit 47 (MSB of data) must be 0 for preamble detection
    if ((d->raw >> 47) & 0x01) {
        return false;
    }

    // Validate checksum: sum of 5 data bytes XOR 0x3A
    uint8_t chksum = 0;
    for (int i = 0; i < JABLOTRON_DATA_SIZE; i++) {
        chksum += (d->raw >> (40 - 8 * i)) & 0xFF;
    }
    chksum ^= 0x3A;

    if (chksum != (d->raw & 0xFF)) {
        return false;
    }

    // Extract 5-byte data
    for (int i = 0; i < JABLOTRON_DATA_SIZE; i++) {
        d->data[i] = (d->raw >> (40 - 8 * i)) & 0xFF;
    }

    return true;
}

static bool jablotron_decoder_feed(jablotron_codec *d, uint16_t interval) {
    bool bits[2] = {0};
    int8_t bitlen = 0;
    diphase_feed(d->modem, (uint8_t)interval, bits, &bitlen);
    if (bitlen == -1) {
        d->raw = 0;
        d->raw_length = 0;
        return false;
    }
    for (int i = 0; i < bitlen; i++) {
        if (jablotron_decode_feed(d, bits[i])) {
            return true;
        }
    }
    return false;
}

static const nrf_pwm_sequence_t *jablotron_modulator(jablotron_codec *d, uint8_t *buf) {
    uint64_t raw = jablotron_raw_data(buf);
    bool level = false;  // carries across both passes

    int out = 0;
    for (int pass = 0; pass < 2; pass++) {
        for (int i = 0; i < JABLOTRON_RAW_SIZE; i++) {
            bool bit = (raw >> (JABLOTRON_RAW_SIZE - 1 - i)) & 0x01;

            // Boundary transition: always flip
            level = !level;

            // First half-bit
            m_jablotron_pwm_seq_vals[out].channel_0 = level ? 32 : 0;
            m_jablotron_pwm_seq_vals[out].counter_top = 31;
            out++;

            // Mid-bit transition for bit 0
            if (!bit) {
                level = !level;
            }

            // Second half-bit
            m_jablotron_pwm_seq_vals[out].channel_0 = level ? 32 : 0;
            m_jablotron_pwm_seq_vals[out].counter_top = 31;
            out++;
        }
    }

    return &m_jablotron_pwm_seq;
}

uint8_t jablotron_t55xx_writer(uint8_t *uid, uint32_t *blks) {
    uint64_t raw = jablotron_raw_data(uid);
    blks[0] = T5577_JABLOTRON_CONFIG;
    blks[1] = raw >> 32;
    blks[2] = raw & 0xFFFFFFFF;
    return JABLOTRON_T55XX_BLOCK_COUNT;
}

void diphase_feed(diphase *d, uint8_t interval, bool *bits, int8_t *bitlen) {
    uint8_t t = d->rp(interval);
    *bitlen = -1;
    if (t == 3) {
        diphase_reset(d);
        return;
    }

    if (d->boundary) {
        if (t == 0) {
            // 1T at boundary: complete bit with mid-bit transition -> 0
            *bitlen = 1;
            bits[0] = 0;
        } else if (t == 1) {
            // 1.5T at boundary: bit 1 (no mid-bit) + start of bit 0 (mid-bit)
            *bitlen = 2;
            bits[0] = 1;
            bits[1] = 0;
            d->boundary = false;
        } else if (t == 2) {
            // 2T at boundary: two bits without mid-bit transitions -> 1, 1
            *bitlen = 2;
            bits[0] = 1;
            bits[1] = 1;
        }
    } else {
        if (t == 0) {
            // 1T at mid-bit: next bit has mid-bit transition -> 0
            *bitlen = 1;
            bits[0] = 0;
        } else if (t == 1) {
            // 1.5T at mid-bit: next bit has no mid-bit transition -> 1
            *bitlen = 1;
            bits[0] = 1;
            d->boundary = true;
        } else {
            // 2T at mid-bit: impossible in clean diphase -> reset
            diphase_reset(d);
            return;
        }
    }
}

static void jablotron_gpio_int0_cb(void) {
    uint32_t cntr = get_lf_counter_value();
    uint16_t val = 0;
    if (cntr > 0xff) {
        val = 0xff;
    } else {
        val = cntr & 0xff;
    }
    cb_push_back(&cb, &val);
    clear_lf_counter_value();
}

bool jablotron_read(uint8_t *data, uint32_t timeout_ms) {
    void *codec = jablotron.alloc();
    jablotron.decoder.start(codec, 0);

    cb_init(&cb, JABLOTRON_BUFFER_SIZE, sizeof(uint16_t));
    init_jablotron_hw();
    start_lf_125khz_radio();

    bool ok = false;
    autotimer *p_at = bsp_obtain_timer(0);
    while (!ok && NO_TIMEOUT_1MS(p_at, timeout_ms)) {
        uint16_t val = 0;
        while (!ok && NO_TIMEOUT_1MS(p_at, timeout_ms) && cb_pop_front(&cb, &val)) {
            if (jablotron.decoder.feed(codec, val)) {
                memcpy(data, jablotron.get_data(codec), jablotron.data_size);
                ok = true;
                break;
            }
        }
    }

    bsp_return_timer(p_at);
    stop_lf_125khz_radio();
    uninit_jablotron_hw();
    cb_free(&cb);

    jablotron.free(codec);
    return ok;
}

uint8_t scan_jablotron(uint8_t *uid) {
    if (jablotron_read(uid, g_timeout_readem_ms)) {
        return STATUS_LF_TAG_OK;
    }
    return STATUS_LF_TAG_NO_FOUND;
}

uint8_t write_jablotron_to_t55xx(uint8_t *uid, uint8_t *new_passwd, uint8_t *old_passwds, uint8_t old_passwd_count) {
    uint32_t blks[7] = {0x00};
    uint8_t blk_count = jablotron_t55xx_writer(uid, blks);
    if (blk_count == 0) {
        return STATUS_PAR_ERR;
    }
    return write_t55xx(blks, blk_count, new_passwd, old_passwds, old_passwd_count);
}

void decodeCPRSurface(struct aircraft *a, int fflag, int raw_lat, int raw_lon) {
    const double SurfDlat0 = 90.0 / 60;
    const double SurfDlat1 = 90.0 / 59;
    double dlat = fflag ? SurfDlat1 : SurfDlat0;
    double ref_lat = Modes.ref_lat;
    double ref_lon = Modes.ref_lon;
    double lat, lon;
    int j, ni, m;

    /* No reference position yet, can't decode surface position. */
    if (Modes.ref_count == 0) return;

    /* Compute latitude index j from reference latitude. */
    j = (int)floor(ref_lat / dlat) +
        (int)floor(0.5 + cprModFunction((int)ref_lat, (int)dlat) / dlat -
                   (double)raw_lat / 131072);

    lat = dlat * (j + (double)raw_lat / 131072);

    /* Pick the latitude solution closest to the reference. We may need to
     * try ±90 degrees since surface encoding covers only 90 degrees. */
    if (fabs(lat - ref_lat) > 45) {
        if (lat > ref_lat) lat -= 90;
        else lat += 90;
    }

    /* Sanity check: latitude must be in valid range. */
    if (lat < -90 || lat > 90) return;

    /* Compute longitude. */
    ni = cprNFunction(lat, fflag);
    if (ni == 0) ni = 1;  /* Avoid division by zero near poles. */
    m = (int)floor(ref_lon / (90.0 / ni)) +
        (int)floor(0.5 + cprModFunction((int)ref_lon, (int)(90.0 / ni)) /
                   (90.0 / ni) - (double)raw_lon / 131072);
    lon = (90.0 / ni) * (m + (double)raw_lon / 131072);

    /* Pick the longitude solution closest to reference. Surface encoding
     * covers only 90 degrees, so we may need to adjust by ±90 or ±180. */
    while (lon > ref_lon + 45) lon -= 90;
    while (lon < ref_lon - 45) lon += 90;

    /* Normalize longitude to -180..180 range. */
    if (lon > 180) lon -= 360;
    if (lon < -180) lon += 360;

    a->lat = lat;
    a->lon = lon;
}

