static __always_inline int trace_go_target(struct pt_regs *ctx,
					   enum go_target_variant variant)
{
	struct event *event;
	__u64 len;

	if (gadget_should_discard_data_current())
		return 0;

	event = gadget_reserve_buf(&events, sizeof(*event));
	if (!event)
		return 0;

	gadget_process_populate(&event->proc);
	event->variant_raw = variant;

	/*
	 * Go strings are not NUL terminated: the data pointer is passed in the
	 * first argument register and the length in the second one.
	 */
	len = (__u64)GO_PARAM2(ctx);
	if (len > sizeof(event->name) - 1)
		len = sizeof(event->name) - 1;
	event->name[len] = '\0';
	if (bpf_probe_read_user(event->name, len, GO_PARAM1(ctx)) < 0)
		event->name[0] = '\0';

	gadget_submit_buf(ctx, &events, event, sizeof(*event));

	return 0;
}

static __always_inline bool gpu_device_underutilized(__u8 dev_idx,
						     __u32 max_pct)
{
	__u32 key = dev_idx;
	struct gpu_device_metrics *d = bpf_map_lookup_elem(&gpu_device, &key);
	if (!d)
		return false;
	return d->sm_util_pct < max_pct;
}

int ig_sched_switch_devlatch(void *ctx)
{
	__u32 zero = 0;
	struct gpu_meta *meta = bpf_map_lookup_elem(&gpu_meta, &zero);
	if (!meta)
		return 0;

		/* Constant trip count (verifier knows d < GPU_MAX_DEVICES) with unroll
	 * disabled keeps this a real, convergent loop. gpu_device is a 16-entry
	 * ARRAY, so unused slots read sm_util_pct == 0 and are skipped; a runtime
	 * n_devices bound is avoided because the verifier treats it as a
	 * full-range u32 and fails to converge the loop. */
#pragma clang loop unroll(disable)
	for (__u32 d = 0; d < GPU_MAX_DEVICES; d++) {
		/* Use a separate key variable for the map lookups: taking the
		 * address of the loop counter itself would spill it to the
		 * stack, where the verifier loses its bounds and rejects the
		 * loop as "infinite" (cannot prove the counter progresses). */
		__u32 key = d;
		struct gpu_device_metrics *dm =
			bpf_map_lookup_elem(&gpu_device, &key);
		if (!dm || dm->sm_util_pct == 0)
			continue;
		/* Device timestamp is CLOCK_REALTIME (bridge time.Now); convert
		 * to CLOCK_BOOTTIME: boottime = realtime - offset. Latch
		 * monotonically so a stale/racing read never rewinds it. */
		__u64 active_boot =
			dm->timestamp_ns - (__u64)meta->clock_offset_ns;
		__u64 *la = bpf_map_lookup_elem(&device_last_active, &key);
		if (la && active_boot > *la)
			*la = active_boot;
		__u64 *any =
			bpf_map_lookup_elem(&device_last_active_any, &zero);
		if (any && active_boot > *any)
			*any = active_boot;
	}
	return 0;
}

static __always_inline bool
gpu_holder(__u32 tgid, __u64 now, struct gpu_pid_metrics_aggregated **gm_out,
	   __u64 *idle_out)
{
	struct gpu_pid_metrics_aggregated *gm =
		gpu_pid_holder(tgid, min_gpu_mem_bytes);
	if (!gm)
		return false;

	if (!gpu_meta_fresh(now, stale_threshold_ms))
		return false;

	/* Per-PID GPU-idle is derived from the DEVICE this PID's memory lives
	 * on. device_last_active holds the newest CLOCK_BOOTTIME at which that
	 * device was observed active (maintained by ig_sched_switch_devlatch);
	 * idle is the time elapsed since. A device never seen active latches 0,
	 * so idle spans the whole uptime (matches "allocated but never ran a
	 * kernel"). No device loop here: the multi-device case reads the
	 * precomputed aggregate latch, so this (large) program stays loop-free. */
	__u64 last_active_boot = 0;
	__u8 dev = gm->gpu_device_primary;
	__u32 key = (dev == GPU_DEVICE_PRIMARY_MULTI) ? 0 : dev;
	__u64 *la = (dev == GPU_DEVICE_PRIMARY_MULTI) ?
			    bpf_map_lookup_elem(&device_last_active_any, &key) :
			    bpf_map_lookup_elem(&device_last_active, &key);
	if (la)
		last_active_boot = *la;

	*gm_out = gm;
	*idle_out = now - last_active_boot;
	return true;
}

int BPF_KPROBE(ig_finish_task_switch, struct task_struct *prev)
{
	__u64 now = bpf_ktime_get_boot_ns();
	__u32 zero = 0;

	/* ---- (A) schedule-OUT: account the slice prev just ran ---- */
	__u32 prev_pid = BPF_CORE_READ(prev, pid);
	struct oncpu_info *oi = bpf_map_lookup_elem(&oncpu, &prev_pid);
	if (oi) {
		__u64 duration = now - oi->start_ns;
		__u32 prev_tgid = BPF_CORE_READ(prev, tgid);

		struct gpu_pid_metrics_aggregated *gm;
		__u64 idle_ns;
		if (oi->gated && gpu_holder(prev_tgid, now, &gm, &idle_ns) &&
		    idle_ns >= min_idle_ms * 1000000ULL) {
			/* Starvation confirmed for this slice. Accumulate into
			 * the per-thread window and emit at most 1/s.
			 */
			struct thread_accum *ta =
				bpf_map_lookup_elem(&accum, &prev_pid);
			if (!ta) {
				struct thread_accum init = {
					.window_start_ns = now,
					.cpu_time_ns = duration,
					.hit_count = 1,
				};
				bpf_map_update_elem(&accum, &prev_pid, &init,
						    BPF_ANY);
			} else {
				ta->cpu_time_ns += duration;
				ta->hit_count += 1;

				if (now - ta->window_start_ns >=
				    EMIT_WINDOW_NS) {
					struct event *ev = gadget_reserve_buf(
						&events, sizeof(*ev));
					if (ev) {
						ev->timestamp_raw = now;
						ev->proc = oi->proc;
						ev->ustack = oi->ustack;
						ev->kstack_raw =
							collect_kstack ?
								gadget_get_kernel_stack(
									ctx) :
								-1;
						ev->cpu_time_ns =
							ta->cpu_time_ns;
						ev->idle_ns = idle_ns;
						ev->hit_count = ta->hit_count;
						gadget_submit_buf(ctx, &events,
								  ev,
								  sizeof(*ev));
					}
					/* Reset the window. */
					ta->window_start_ns = now;
					ta->cpu_time_ns = 0;
					ta->hit_count = 0;
				}
			}
		}
		bpf_map_delete_elem(&oncpu, &prev_pid);
	}

	/* ---- (B) schedule-IN: current == next ---- */
	__u64 pid_tgid = bpf_get_current_pid_tgid();
	__u32 next_pid = (__u32)pid_tgid;
	__u32 next_tgid = pid_tgid >> 32;
	if (next_pid == 0) /* swapper/idle */
		return 0;

	struct oncpu_info *ni = bpf_map_lookup_elem(&tmp_oncpu, &zero);
	if (!ni)
		return 0;
	ni->start_ns = now;
	ni->gated = 0;

	/* Capture the stack for any GPU-holding thread with fresh data. The
	 * idle threshold is deliberately NOT required here: it is re-checked at
	 * schedule-out (idle only grows), so capturing unconditionally for GPU
	 * holders avoids missing a thread whose GPU went idle mid-slice. GPU
	 * holders are few, so this is cheap.
	 */
	struct gpu_pid_metrics_aggregated *gm;
	__u64 idle_ns;
	if (!gadget_should_discard_data_current() &&
	    gpu_holder(next_tgid, now, &gm, &idle_ns)) {
		ni->gated = 1;
		gadget_process_populate(&ni->proc);
		gadget_get_user_stack(ctx, &ni->ustack);
	}

	bpf_map_update_elem(&oncpu, &next_pid, ni, BPF_ANY);
	return 0;
}

int trace_sched_process_exit(void *ctx)
{
	__u32 pid = (__u32)bpf_get_current_pid_tgid();
	bpf_map_delete_elem(&oncpu, &pid);
	bpf_map_delete_elem(&accum, &pid);
	return 0;
}

t dump_gpu_per_pid(struct bpf_iter__task *ctx)
{
	struct seq_file *seq = ctx->meta->seq;
	struct task_struct *task = ctx->task;

	if (task == NULL)
		return 0;

	/* Only look at main threads; gpu_per_pid is keyed by tgid.
	 * Also filters out the sentinel entry the iter emits at the end
	 * of the walk (task == NULL is handled above; task->tgid == 0
	 * is the swapper). */
	__u32 tgid = BPF_CORE_READ(task, tgid);
	__u32 pid = BPF_CORE_READ(task, pid);
	if (tgid == 0 || pid != tgid)
		return 0;

	struct gpu_pid_metrics_aggregated *val =
		bpf_map_lookup_elem(&gpu_per_pid, &tgid);
	if (!val)
		return 0;
	if (val->used_gpu_memory_total == 0)
		return 0;

	struct gpu_top_per_pid_event ev;
	__builtin_memset(&ev, 0, sizeof(ev));

	ev.proc.pid = tgid;
	ev.proc.tid = pid;
	ev.proc.mntns_id = BPF_CORE_READ(task, nsproxy, mnt_ns, ns.inum);
	bpf_probe_read_kernel_str(&ev.proc.comm, sizeof(ev.proc.comm),
				  BPF_CORE_READ(task, comm));
	ev.proc.creds.uid = BPF_CORE_READ(task, cred, uid.val);
	ev.proc.creds.gid = BPF_CORE_READ(task, cred, gid.val);

	struct task_struct *parent = BPF_CORE_READ(task, real_parent);
	if (parent) {
		ev.proc.parent.pid = BPF_CORE_READ(parent, tgid);
		ev.proc.parent.tid = BPF_CORE_READ(parent, pid);
		bpf_probe_read_kernel_str(&ev.proc.parent.comm,
					  sizeof(ev.proc.parent.comm),
					  BPF_CORE_READ(parent, comm));
	}

	ev.mem_used_raw = val->used_gpu_memory_total;
	ev.sm_util_pct_max = val->sm_util_pct_max;
	ev.mem_util_pct_max = val->mem_util_pct_max;
	ev.gpu_device_primary = val->gpu_device_primary;
	ev.device_count = val->device_count;
	ev.timestamp_ns = val->timestamp_ns;

	bpf_seq_write(seq, &ev, sizeof(ev));
	return 0;
}

int dump_gpu_devices(struct bpf_iter__bpf_map_elem *ctx)
{
	struct seq_file *seq = ctx->meta->seq;
	__u32 *key = ctx->key;
	struct gpu_device_metrics *val = ctx->value;

	if (!key || !val)
		return 0;

	/* The bridge publishes the map as ARRAY[16]; slots for devices
	 * the bridge did not write are zero-initialised. timestamp_ns is
	 * the freshness signal: skip slots the bridge has never touched. */
	if (val->timestamp_ns == 0)
		return 0;

	/* Aggregate initializers in C do not touch padding bytes between
	 * fields (e.g. the 4 bytes between the u32 mem_util_pct and the
	 * u64 mem_used_raw). Leaving them uninitialised trips the BPF
	 * verifier: "invalid indirect read from stack ... size 136".
	 * Zero the whole struct first, then fill in fields. */
	struct gpu_top_event ev;
	__builtin_memset(&ev, 0, sizeof(ev));
	ev.device = *key;
	ev.sm_util_pct = val->sm_util_pct;
	ev.mem_util_pct = val->mem_util_pct;
	ev.mem_used_raw = val->mem_used;
	ev.mem_total_raw = val->mem_total;
	ev.mem_reserved_raw = val->mem_reserved;
	ev.temp_c = val->temp_c;
	ev.power_mw = val->power_mw;
	ev.sm_clock_mhz = val->sm_clock_mhz;
	ev.mem_clock_mhz = val->mem_clock_mhz;
	ev.enc_util_pct = val->enc_util_pct;
	ev.dec_util_pct = val->dec_util_pct;
	ev.throttle_reasons = val->throttle_reasons;
	ev.pcie_tx_kbps = val->pcie_tx_kbps;
	ev.pcie_rx_kbps = val->pcie_rx_kbps;
	ev.nvlink_tx_kbps = val->nvlink_tx_kbps;
	ev.nvlink_rx_kbps = val->nvlink_rx_kbps;
	ev.ecc_corrected_total = val->ecc_corrected_total;
	ev.ecc_uncorrected_total = val->ecc_uncorrected_total;
	ev.fan_speed_pct = val->fan_speed_pct;
	ev.compute_mode = val->compute_mode;
	ev.timestamp_ns = val->timestamp_ns;

	bpf_seq_write(seq, &ev, sizeof(ev));
	return 0;
}

int dump_gpu_devices(struct bpf_iter__bpf_map_elem *ctx)
{
	struct seq_file *seq = ctx->meta->seq;
	__u32 *key = ctx->key;
	struct gpu_device_metrics *val = ctx->value;

	if (!key || !val)
		return 0;

	/* Skip unpopulated ARRAY slots (the bridge writes timestamp_ns
	 * on every update; a zero value means the slot was never
	 * touched). */
	if (val->timestamp_ns == 0)
		return 0;

	struct gpu_event ev = {
		.device = *key,
		.sm_util_pct = val->sm_util_pct,
		.mem_util_pct = val->mem_util_pct,
		.temp_c = val->temp_c,
		.power_mw = val->power_mw,
		.mem_used = val->mem_used,
		.mem_total = val->mem_total,
		.timestamp_ns = val->timestamp_ns,
	};

	bpf_seq_write(seq, &ev, sizeof(ev));
	return 0;
}

