static int UArray_hexDigitValue_(long c) {
    if (c >= '0' && c <= '9')
        return (int)(c - '0');
    if (c >= 'a' && c <= 'f')
        return (int)(c - 'a' + 10);
    if (c >= 'A' && c <= 'F')
        return (int)(c - 'A' + 10);
    return -1;
}

int IoMap_compare(IoMap *self, IoMap *other) {
    if (!ISMAP(other)) {
        return IoObject_defaultCompare(self, other);
    }

    size_t s1 = PHash_size(DATA(self));
    size_t s2 = PHash_size(DATA(other));

    if (s1 != s2) {
        return s1 > s2 ? 1 : -1;
    }

    int mismatch = 0;
    PHASH_FOREACH(DATA(self), k, v, {
        if (mismatch) continue;
        void *ov = PHash_at_(DATA(other), k);
        if (ov == NULL) {
            mismatch = 1;
        } else {
            int c = IoObject_compare((IoObject *)v, (IoObject *)ov);
            if (c) mismatch = c < 0 ? -1 : 1;
        }
    });
    return mismatch;
}

int IoMap_compare(IoMap *self, IoMap *other) {
    if (!ISMAP(other)) {
        return IoObject_defaultCompare(self, other);
    }

    size_t s1 = PHash_size(DATA(self));
    size_t s2 = PHash_size(DATA(other));

    if (s1 != s2) {
        return s1 > s2 ? 1 : -1;
    }

    int mismatch = 0;
    PHASH_FOREACH(DATA(self), k, v, {
        if (mismatch) continue;
        void *ov = PHash_at_(DATA(other), k);
        if (ov == NULL) {
            mismatch = 1;
        } else {
            int c = IoObject_compare((IoObject *)v, (IoObject *)ov);
            if (c) mismatch = c < 0 ? -1 : 1;
        }
    });
    return mismatch;
}

int mp_get_bit(const mp_int *a, int b)
{
   if (b < 0) {
      return MP_VAL;
