static void output_append(const char *data, size_t len) {
	if (output_len + len + 1 > output_cap) {
		output_cap = (output_len + len + 1) * 2;
		if (output_cap < 4096) output_cap = 4096;
		output_buf = realloc(output_buf, output_cap);
	}
	memcpy(output_buf + output_len, data, len);
	output_len += len;
	output_buf[output_len] = '\0';
}

static void browser_exception_callback(void *context, IoObject *coroutine) {
	(void)context;
	// Use the default backtrace printing — it goes through printCallback
	IoCoroutine_rawPrintBackTrace(coroutine);
}

attribute__((export_name("io_init")))
int io_init(void) {
	if (state) return 0; // already initialized

	state = IoState_new();
	IoState_init(state);

	// Wire output capture
	IoState_printCallback_(state, browser_print_callback);
	IoState_exceptionCallback_(state, browser_exception_callback);

	// Set minimal args so System args doesn't crash
	const char *argv[] = {"io"};
	IoState_argc_argv_(state, 1, argv);

	output_clear();
	return 0;
}

atic int do_eval(const char *code) {
	if (!state) return -1;

	output_clear();
	state->errorRaised = 0;

	IoObject *result = IoState_doCString_(state, code);

	if (state->errorRaised) {
		return 1;
	}

	// If there was no printed output but there is a result, show it
	if (output_len == 0 && result && result != state->ioNil) {
		IoSymbol *str = IoObject_asString_(result, NULL);
		if (str && !state->errorRaised) {
			const char *cstr = CSTRING(str);
			if (cstr && strlen(cstr) > 0) {
				output_append("==> ", 4);
				output_append(cstr, strlen(cstr));
				output_append("\n", 1);
			}
		}
	}

	return 0;
}

tribute__((export_name("io_eval_input")))
int io_eval_input(void) {
	input_buf[INPUT_BUF_SIZE - 1] = '\0'; // safety
	return do_eval(input_buf);
}

//

tribute__((export_name("io_eval")))
int io_eval(const char *code) {
	return do_eval(code);
}

//

tribute__((export_name("io_get_output")))
const char *io_get_output(void) {
	if (!output_buf) return "";
	return output_buf;
}

//

static void FileList_init(FileList *fl) {
	fl->count = 0;
	fl->capacity = 64;
	fl->paths = malloc(fl->capacity * sizeof(char *));
}

static void FileList_add(FileList *fl, const char *path) {
	if (fl->count == fl->capacity) {
		fl->capacity *= 2;
		fl->paths = realloc(fl->paths, fl->capacity * sizeof(char *));
	}
	fl->paths[fl->count++] = strdup(path);
}

static void FileList_free(FileList *fl) {
	for (size_t i = 0; i < fl->count; i++)
		free(fl->paths[i]);
	free(fl->paths);
}

static char *pathDir(const char *path) {
	const char *lastSlash = strrchr(path, '/');
	if (!lastSlash)
		return strdup("");
	size_t len = lastSlash - path;
	char *dir = malloc(len + 1);
	memcpy(dir, path, len);
	dir[len] = '\0';
	return dir;
}

static char *pathJoin(const char *dir, const char *file) {
	if (dir[0] == '\0')
		return strdup(file);
	size_t dlen = strlen(dir);
	size_t flen = strlen(file);
	char *result = malloc(dlen + 1 + flen + 1);
	memcpy(result, dir, dlen);
	result[dlen] = '/';
	memcpy(result + dlen + 1, file, flen);
	result[dlen + 1 + flen] = '\0';
	return result;
}

static int endsWith(const char *s, const char *suffix) {
	size_t slen = strlen(s);
	size_t sufflen = strlen(suffix);
	if (sufflen > slen) return 0;
	return strcmp(s + slen - sufflen, suffix) == 0;
}

static void collectFiles(const char *importsPath, FileList *fl) {
	JSON_Value *root = json_parse_file(importsPath);
	if (!root) {
		fprintf(stderr, "io2c: error parsing %s\n", importsPath);
		exit(1);
	}

	JSON_Array *arr = json_value_get_array(root);
	if (!arr) {
		fprintf(stderr, "io2c: %s is not a JSON array\n", importsPath);
		json_value_free(root);
		exit(1);
	}

	char *dir = pathDir(importsPath);
	size_t count = json_array_get_count(arr);

	for (size_t i = 0; i < count; i++) {
		const char *entry = json_array_get_string(arr, i);
		if (!entry) {
			fprintf(stderr, "io2c: non-string entry at index %zu in %s\n", i, importsPath);
			json_value_free(root);
			free(dir);
			exit(1);
		}

		char *fullPath = pathJoin(dir, entry);

		if (endsWith(entry, ".json")) {
			collectFiles(fullPath, fl);
		} else {
			FileList_add(fl, fullPath);
		}

		free(fullPath);
	}

	free(dir);
	json_value_free(root);
}

static void IoState_markSlotLazyArgs_(IoState *self, const char *protoId,
                                      const char *slotName) {
    IoObject *proto = IoState_protoWithId_(self, protoId);
    if (!proto) return;
    IoObject *f = IoObject_rawGetSlot_(proto, SIOSYMBOL(slotName));
    if (f && ISCFUNCTION(f)) {
        ((IoCFunctionData *)IoObject_dataPointer(f))->isLazyArgs = 1;
    }
}

static void IoState_markLazyArgsCFunctions_(IoState *self) {
    // Control flow
    IoState_markSlotLazyArgs_(self, "Object", "if");
    IoState_markSlotLazyArgs_(self, "Object", "while");
    IoState_markSlotLazyArgs_(self, "Object", "for");
    IoState_markSlotLazyArgs_(self, "Object", "loop");
    IoState_markSlotLazyArgs_(self, "Object", "callcc");
    // Block/method construction
    IoState_markSlotLazyArgs_(self, "Object", "method");
    IoState_markSlotLazyArgs_(self, "Object", "block");
    // Evaluation (body is lazy)
    IoState_markSlotLazyArgs_(self, "Object", "do");
    IoState_markSlotLazyArgs_(self, "Object", "lexicalDo");
    IoState_markSlotLazyArgs_(self, "Object", "message");
    IoState_markSlotLazyArgs_(self, "Object", "foreachSlot");
    // List
    IoState_markSlotLazyArgs_(self, "List", "foreach");
    IoState_markSlotLazyArgs_(self, "List", "reverseForeach");
    IoState_markSlotLazyArgs_(self, "List", "sortInPlace");
    // Number
    IoState_markSlotLazyArgs_(self, "Number", "repeat");
    // Date
    IoState_markSlotLazyArgs_(self, "Date", "cpuSecondsToRun");
    // Sequence
    IoState_markSlotLazyArgs_(self, "Sequence", "foreach");
    // Map
    IoState_markSlotLazyArgs_(self, "Map", "foreach");
    // File
    IoState_markSlotLazyArgs_(self, "File", "foreach");
    IoState_markSlotLazyArgs_(self, "File", "foreachLine");
}

void Collector_rcEnqueue_(Collector *self, CollectorMarker *m) {
    if (self->rcFreeCount >= self->rcFreeCapacity) {
        self->rcFreeCapacity = self->rcFreeCapacity ? self->rcFreeCapacity * 2 : 64;
        self->rcFreeList = (CollectorMarker **)io_realloc(self->rcFreeList,
            self->rcFreeCapacity * sizeof(CollectorMarker *));
    }
    self->rcFreeList[self->rcFreeCount++] = m;
}

void Collector_rcDrainFreeList_(Collector *self) {
    while (self->rcFreeCount > 0) {
        CollectorMarker *m = self->rcFreeList[--self->rcFreeCount];
        if (m->refCount != 0) continue;
        if (m->color == self->freed->color) continue;
        if (m->color != self->whites->color) continue;
        if (self->freeFunc) self->freeFunc(m);
        Collector_makeFree_(self, m);
        self->allocated--;
    }
}

