IoTag *IoEvalFrame_newTag(void *state) {
    IoTag *tag = IoTag_newWithName_(protoId);
    IoTag_state_(tag, state);
    IoTag_cloneFunc_(tag, (IoTagCloneFunc *)IoEvalFrame_rawClone);
    IoTag_markFunc_(tag, (IoTagMarkFunc *)IoEvalFrame_mark);
    IoTag_freeFunc_(tag, (IoTagFreeFunc *)IoEvalFrame_free);
    return tag;
}

IoEvalFrame *IoEvalFrame_rawClone(IoEvalFrame *proto) {
    IoObject *self = IoObject_rawClonePrimitive(proto);
    IoObject_setDataPointer_(self, io_calloc(1, sizeof(IoEvalFrameData)));
    IoEvalFrameData *fd = FRAME_DATA(self);
    memset(fd, 0, sizeof(IoEvalFrameData));

    return self;
}

FrameState IoEvalFrame_stateFromName(const char *name) {
	if (!name) return FRAME_STATE_START;
	if (strcmp(name, "start") == 0) return FRAME_STATE_START;
	if (strcmp(name, "evalArgs") == 0) return FRAME_STATE_EVAL_ARGS;
	if (strcmp(name, "lookupSlot") == 0) return FRAME_STATE_LOOKUP_SLOT;
	if (strcmp(name, "activate") == 0) return FRAME_STATE_ACTIVATE;
	if (strcmp(name, "continueChain") == 0) return FRAME_STATE_CONTINUE_CHAIN;
	if (strcmp(name, "return") == 0) return FRAME_STATE_RETURN;
	if (strcmp(name, "if:evalCondition") == 0) return FRAME_STATE_IF_EVAL_CONDITION;
	if (strcmp(name, "if:convertBoolean") == 0) return FRAME_STATE_IF_CONVERT_BOOLEAN;
	if (strcmp(name, "if:evalBranch") == 0) return FRAME_STATE_IF_EVAL_BRANCH;
	if (strcmp(name, "while:evalCondition") == 0) return FRAME_STATE_WHILE_EVAL_CONDITION;
	if (strcmp(name, "while:checkCondition") == 0) return FRAME_STATE_WHILE_CHECK_CONDITION;
	if (strcmp(name, "while:decide") == 0) return FRAME_STATE_WHILE_DECIDE;
	if (strcmp(name, "while:evalBody") == 0) return FRAME_STATE_WHILE_EVAL_BODY;
	if (strcmp(name, "loop:evalBody") == 0) return FRAME_STATE_LOOP_EVAL_BODY;
	if (strcmp(name, "loop:afterBody") == 0) return FRAME_STATE_LOOP_AFTER_BODY;
	if (strcmp(name, "for:evalSetup") == 0) return FRAME_STATE_FOR_EVAL_SETUP;
	if (strcmp(name, "for:evalBody") == 0) return FRAME_STATE_FOR_EVAL_BODY;
	if (strcmp(name, "for:afterBody") == 0) return FRAME_STATE_FOR_AFTER_BODY;
	if (strcmp(name, "foreach:evalBody") == 0) return FRAME_STATE_FOREACH_EVAL_BODY;
	if (strcmp(name, "foreach:afterBody") == 0) return FRAME_STATE_FOREACH_AFTER_BODY;
	if (strcmp(name, "callcc:evalBlock") == 0) return FRAME_STATE_CALLCC_EVAL_BLOCK;
	if (strcmp(name, "coro:waitChild") == 0) return FRAME_STATE_CORO_WAIT_CHILD;
	if (strcmp(name, "coro:yielded") == 0) return FRAME_STATE_CORO_YIELDED;
	if (strcmp(name, "do:eval") == 0) return FRAME_STATE_DO_EVAL;
	if (strcmp(name, "do:wait") == 0) return FRAME_STATE_DO_WAIT;
	return FRAME_STATE_START;
}

static IoObject *serializeObject_(IoState *state, IoObject *obj) {
    if (!obj) return state->ioNil;
    if (obj == state->ioNil) return state->ioNil;
    if (obj == state->ioTrue) return state->ioTrue;
    if (obj == state->ioFalse) return state->ioFalse;
    if (ISNUMBER(obj)) return obj;
    if (ISSEQ(obj)) return obj;

    // For complex objects, return a Map with type info and slots
    IoMap *map = IoMap_new(state);
    const char *tagName = IoObject_tag(obj)->name;
    IoMap_rawAtPut(map, SYM("_type"), SYM(tagName));

    // For objects with slots, serialize slot names (not values, to avoid cycles)
    if (IoObject_slots(obj)) {
        IoList *slotNames = IoList_new(state);
        PHASH_FOREACH(IoObject_slots(obj), k, v,
            IoList_rawAppend_(slotNames, k);
        );
        IoMap_rawAtPut(map, SYM("_slotNames"), slotNames);
    }
    return map;
}

static IoObject *serializeMessage_(IoState *state, IoMessage *msg) {
    if (!msg) return state->ioNil;

    IoMap *map = IoMap_new(state);

    // Message name
    IoMap_rawAtPut(map, SYM("name"),
                   SYM(CSTRING(IoMessage_name(msg))));

    // Full code representation (can be reparsed)
    UArray *codeUA = IoMessage_descriptionJustSelfAndArgs(msg);
    IoSeq *code = IoSeq_newWithUArray_copy_(state, codeUA, 0);
    IoMap_rawAtPut(map, SYM("code"), code);

    // Full chain code (including next messages)
    UArray *chainUA = IoMessage_description(msg);
    IoSeq *chainCode = IoSeq_newWithUArray_copy_(state, chainUA, 0);
    IoMap_rawAtPut(map, SYM("chainCode"), chainCode);

    // Cached result (literal value)
    IoObject *cached = IoMessage_rawCachedResult(msg);
    if (cached) {
        IoMap_rawAtPut(map, SYM("cachedResult"),
                       serializeObject_(state, cached));
    }

    // Line number and label
    IoMap_rawAtPut(map, SYM("lineNumber"),
                   NUM(IoMessage_rawLineNumber(msg)));
    IoSymbol *label = IoMessage_rawLabel(msg);
    if (label) {
        IoMap_rawAtPut(map, SYM("label"), label);
    }

    // Argument count
    IoMap_rawAtPut(map, SYM("argCount"),
                   NUM(IoMessage_argCount(msg)));

    return map;
}

static void serializeControlFlow_(IoState *state, IoEvalFrame *frame,
                                    IoMap *map) {
    switch (frame->state) {
        case FRAME_STATE_IF_EVAL_CONDITION:
        case FRAME_STATE_IF_CONVERT_BOOLEAN:
        case FRAME_STATE_IF_EVAL_BRANCH: {
            IoMap_rawAtPut(map, SYM("conditionResult"),
                           NUM(frame->controlFlow.ifInfo.conditionResult));
            if (frame->controlFlow.ifInfo.conditionMsg) {
                IoMap_rawAtPut(map, SYM("conditionMsg"),
                    serializeMessage_(state, frame->controlFlow.ifInfo.conditionMsg));
            }
            if (frame->controlFlow.ifInfo.trueBranch) {
                IoMap_rawAtPut(map, SYM("trueBranch"),
                    serializeMessage_(state, frame->controlFlow.ifInfo.trueBranch));
            }
            if (frame->controlFlow.ifInfo.falseBranch) {
                IoMap_rawAtPut(map, SYM("falseBranch"),
                    serializeMessage_(state, frame->controlFlow.ifInfo.falseBranch));
            }
            break;
        }

        case FRAME_STATE_WHILE_EVAL_CONDITION:
        case FRAME_STATE_WHILE_CHECK_CONDITION:
        case FRAME_STATE_WHILE_DECIDE:
        case FRAME_STATE_WHILE_EVAL_BODY: {
            IoMap_rawAtPut(map, SYM("conditionResult"),
                           NUM(frame->controlFlow.whileInfo.conditionResult));
            if (frame->controlFlow.whileInfo.conditionMsg) {
                IoMap_rawAtPut(map, SYM("conditionMsg"),
                    serializeMessage_(state, frame->controlFlow.whileInfo.conditionMsg));
            }
            if (frame->controlFlow.whileInfo.bodyMsg) {
                IoMap_rawAtPut(map, SYM("bodyMsg"),
                    serializeMessage_(state, frame->controlFlow.whileInfo.bodyMsg));
            }
            break;
        }

        case FRAME_STATE_LOOP_EVAL_BODY:
        case FRAME_STATE_LOOP_AFTER_BODY: {
            if (frame->controlFlow.loopInfo.bodyMsg) {
                IoMap_rawAtPut(map, SYM("bodyMsg"),
                    serializeMessage_(state, frame->controlFlow.loopInfo.bodyMsg));
            }
            break;
        }

        case FRAME_STATE_FOR_EVAL_SETUP:
        case FRAME_STATE_FOR_EVAL_BODY:
        case FRAME_STATE_FOR_AFTER_BODY: {
            IoMap_rawAtPut(map, SYM("startValue"),
                           NUM(frame->controlFlow.forInfo.startValue));
            IoMap_rawAtPut(map, SYM("endValue"),
                           NUM(frame->controlFlow.forInfo.endValue));
            IoMap_rawAtPut(map, SYM("increment"),
                           NUM(frame->controlFlow.forInfo.increment));
            IoMap_rawAtPut(map, SYM("currentValue"),
                           NUM(frame->controlFlow.forInfo.currentValue));
            IoMap_rawAtPut(map, SYM("initialized"),
                           NUM(frame->controlFlow.forInfo.initialized));
            if (frame->controlFlow.forInfo.counterName) {
                IoMap_rawAtPut(map, SYM("counterName"),
                               frame->controlFlow.forInfo.counterName);
            }
            if (frame->controlFlow.forInfo.bodyMsg) {
                IoMap_rawAtPut(map, SYM("bodyMsg"),
                    serializeMessage_(state, frame->controlFlow.forInfo.bodyMsg));
            }
            break;
        }

        case FRAME_STATE_FOREACH_EVAL_BODY:
        case FRAME_STATE_FOREACH_AFTER_BODY: {
            IoMap_rawAtPut(map, SYM("currentIndex"),
                           NUM(frame->controlFlow.foreachInfo.currentIndex));
            IoMap_rawAtPut(map, SYM("collectionSize"),
                           NUM(frame->controlFlow.foreachInfo.collectionSize));
            IoMap_rawAtPut(map, SYM("direction"),
                           NUM(frame->controlFlow.foreachInfo.direction));
            IoMap_rawAtPut(map, SYM("isEach"),
                           NUM(frame->controlFlow.foreachInfo.isEach));
            if (frame->controlFlow.foreachInfo.indexName) {
                IoMap_rawAtPut(map, SYM("indexName"),
                               frame->controlFlow.foreachInfo.indexName);
            }
            if (frame->controlFlow.foreachInfo.valueName) {
                IoMap_rawAtPut(map, SYM("valueName"),
                               frame->controlFlow.foreachInfo.valueName);
            }
            if (frame->controlFlow.foreachInfo.bodyMsg) {
                IoMap_rawAtPut(map, SYM("bodyMsg"),
                    serializeMessage_(state, frame->controlFlow.foreachInfo.bodyMsg));
            }
            break;
        }

        case FRAME_STATE_CALLCC_EVAL_BLOCK: {
            if (frame->controlFlow.callccInfo.continuation) {
                IoMap_rawAtPut(map, SYM("hasContinuation"),
                               state->ioTrue);
            }
            break;
        }

        default:
            break;
    }
}

static IoMap *serializeFrame_(IoState *state, IoEvalFrame *frame) {
    IoMap *map = IoMap_new(state);

    // Frame state
    IoMap_rawAtPut(map, SYM("state"),
                   SYM(IoEvalFrame_stateName(frame->state)));

    // Message info
    if (frame->message) {
        IoMap_rawAtPut(map, SYM("message"),
                       serializeMessage_(state, frame->message));
    }

    // Frame flags
    IoMap_rawAtPut(map, SYM("passStops"), NUM(frame->passStops));
    IoMap_rawAtPut(map, SYM("isNestedEvalRoot"),
                   NUM(frame->isNestedEvalRoot));

    // Argument evaluation state
    IoMap_rawAtPut(map, SYM("argCount"), NUM(frame->argCount));
    IoMap_rawAtPut(map, SYM("currentArgIndex"),
                   NUM(frame->currentArgIndex));

    // Evaluated arguments
    if (frame->argValues && frame->currentArgIndex > 0) {
        IoList *args = IoList_new(state);
        for (int i = 0; i < frame->currentArgIndex; i++) {
            IoList_rawAppend_(args,
                serializeObject_(state, frame->argValues[i]));
        }
        IoMap_rawAtPut(map, SYM("argValues"), args);
    }

    // Object references (type info + identity)
    if (frame->target) {
        IoMap_rawAtPut(map, SYM("targetType"),
                       SYM(IoObject_tag(frame->target)->name));
    }
    if (frame->locals) {
        IoMap_rawAtPut(map, SYM("localsType"),
                       SYM(IoObject_tag(frame->locals)->name));
    }
    if (frame->result) {
        IoMap_rawAtPut(map, SYM("result"),
                       serializeObject_(state, frame->result));
    }
    if (frame->slotValue) {
        IoMap_rawAtPut(map, SYM("slotValue"),
                       serializeObject_(state, frame->slotValue));
    }

    // Block activation info
    if (frame->blockLocals) {
        IoMap_rawAtPut(map, SYM("hasBlockLocals"), state->ioTrue);

        // Serialize the block locals' slot names and values where possible
        if (IoObject_slots(frame->blockLocals)) {
            IoMap *slotsMap = IoMap_new(state);
            PHASH_FOREACH(IoObject_slots(frame->blockLocals), k, v,
                IoMap_rawAtPut(slotsMap, k, serializeObject_(state, v));
            );
            IoMap_rawAtPut(map, SYM("blockLocalsSlots"), slotsMap);
        }
    }

    // Call stop status
    if (frame->call) {
        int stopStatus = IoCall_rawStopStatus((IoCall *)frame->call);
        IoMap_rawAtPut(map, SYM("callStopStatus"), NUM(stopStatus));
    }
    if (frame->savedCall) {
        int stopStatus = IoCall_rawStopStatus((IoCall *)frame->savedCall);
        IoMap_rawAtPut(map, SYM("savedCallStopStatus"),
                       NUM(stopStatus));
    }

    // Control flow specific state
    serializeControlFlow_(state, frame, map);

    return map;
}

int test_continuation_asMap(IoState *state) {
	printf("Test 30: Continuation asMap... ");

	// Capture a continuation inside a for loop
	testEvalCode(state,
		"captured2 := nil\n"
		"for(i, 1, 5, if(i == 3, callcc(block(cont, captured2 = cont))))");

	// Check asMap returns a Map
	IoObject *map = testEvalCode(state, "captured2 asMap");
	if (!IoObject_slots(map)) {
		printf("FAILED (asMap didn't return a Map)\n");
		return 0;
	}

	// Check frameCount
	IoObject *fc = testEvalCode(state, "captured2 asMap at(\"frameCount\")");
	if (!ISNUMBER(fc) || IoNumber_asInt(fc) < 1) {
		printf("FAILED (frameCount < 1)\n");
		return 0;
	}

	// Check first frame is callcc:evalBlock
	IoObject *firstState = testEvalCode(state,
		"captured2 asMap at(\"frames\") first at(\"state\")");
	if (!ISSEQ(firstState) ||
		strcmp(CSTRING(firstState), "callcc:evalBlock") != 0) {
		printf("FAILED (first frame state != callcc:evalBlock)\n");
		return 0;
	}

	// Check for loop state was captured (currentValue should be 3)
	IoObject *forValue = testEvalCode(state,
		"captured2 asMap at(\"frames\") detect(at(\"state\") beginsWithSeq(\"for\")) at(\"currentValue\")");
	if (!ISNUMBER(forValue) || IoNumber_asDouble(forValue) != 3.0) {
		printf("FAILED (for currentValue != 3, got %s)\n",
			ISNUMBER(forValue) ? "wrong number" : IoObject_name(forValue));
		return 0;
	}

	printf("PASSED\n");
	return 1;
}

const char *IoEvalFrame_stateName(IoFrameState state) {
    switch (state) {
        case FRAME_STATE_START: return "start";
        case FRAME_STATE_EVAL_ARGS: return "evalArgs";
        case FRAME_STATE_LOOKUP_SLOT: return "lookupSlot";
        case FRAME_STATE_ACTIVATE: return "activate";
        case FRAME_STATE_CONTINUE_CHAIN: return "continueChain";
        case FRAME_STATE_RETURN: return "return";
        case FRAME_STATE_IF_EVAL_CONDITION: return "if:evalCondition";
        case FRAME_STATE_IF_CONVERT_BOOLEAN: return "if:convertBoolean";
        case FRAME_STATE_IF_EVAL_BRANCH: return "if:evalBranch";
        case FRAME_STATE_WHILE_EVAL_CONDITION: return "while:evalCondition";
        case FRAME_STATE_WHILE_CHECK_CONDITION: return "while:checkCondition";
        case FRAME_STATE_WHILE_DECIDE: return "while:decide";
        case FRAME_STATE_WHILE_EVAL_BODY: return "while:evalBody";
        case FRAME_STATE_LOOP_EVAL_BODY: return "loop:evalBody";
        case FRAME_STATE_LOOP_AFTER_BODY: return "loop:afterBody";
        case FRAME_STATE_FOR_EVAL_SETUP: return "for:evalSetup";
        case FRAME_STATE_FOR_EVAL_BODY: return "for:evalBody";
        case FRAME_STATE_FOR_AFTER_BODY: return "for:afterBody";
        case FRAME_STATE_FOREACH_EVAL_BODY: return "foreach:evalBody";
        case FRAME_STATE_FOREACH_AFTER_BODY: return "foreach:afterBody";
        case FRAME_STATE_CALLCC_EVAL_BLOCK: return "callcc:evalBlock";
        case FRAME_STATE_CORO_WAIT_CHILD: return "coro:waitChild";
        case FRAME_STATE_CORO_YIELDED: return "coro:yielded";
        case FRAME_STATE_DO_EVAL: return "do:eval";
        case FRAME_STATE_DO_WAIT: return "do:wait";
        default: return "unknown";
    }
}

int test_tco_direct(IoState *state) {
	printf("Test 22: TCO direct tail recursion... ");

	// Direct tail recursion: last expression in method body is a self-call
	// Without TCO this would use 10000+ frames; with TCO it stays flat
	testEvalCode(state,
		"countdown := method(n, if(n <= 0, return n); countdown(n - 1))");
	IoObject *result = testEvalCode(state, "countdown(10000)");

	if (!ISNUMBER(result) || IoNumber_asInt(result) != 0) {
		printf("FAILED (got %d, expected 0)\n",
			   ISNUMBER(result) ? IoNumber_asInt(result) : -1);
		return 0;
	}

	printf("PASSED\n");
	return 1;
}

int test_deep_recursion(IoState *state) {
	printf("Test 23: deep recursion through if... ");

	// This recursion goes through if branches, so TCO may not apply,
	// but heap-allocated frames prevent C stack overflow
	testEvalCode(state,
		"sumTo := method(n, if(n <= 0, 0, n + sumTo(n - 1)))");
	IoObject *result = testEvalCode(state, "sumTo(100)");

	// sum of 1..100 = 5050
	if (!ISNUMBER(result) || IoNumber_asInt(result) != 5050) {
		printf("FAILED (got %d, expected 5050)\n",
			   ISNUMBER(result) ? IoNumber_asInt(result) : -1);
		return 0;
	}

	printf("PASSED\n");
	return 1;
}

int test_tco_accumulator(IoState *state) {
	printf("Test 24: TCO accumulator pattern... ");

	// Tail-recursive sum with accumulator
	// The recursive call is the last expression in the method
	testEvalCode(state,
		"sumAcc := method(n, acc, if(n <= 0, return acc); sumAcc(n - 1, acc + n))");
	IoObject *result = testEvalCode(state, "sumAcc(10000, 0)");

	// sum of 1..10000 = 50005000
	if (!ISNUMBER(result)) {
		printf("FAILED (not a number)\n");
		return 0;
	}

	double expected = 50005000.0;
	double got = IoNumber_asDouble(result);
	if (got != expected) {
		printf("FAILED (got %.0f, expected %.0f)\n", got, expected);
		return 0;
	}

	printf("PASSED\n");
	return 1;
}

int test_tco_through_if(IoState *state) {
	printf("Test 25: TCO through if branches... ");

	// Classic tail-recursive pattern: the recursive call is inside
	// an if branch, which is the last expression in the method.
	// This tests the tail position optimization in IF_EVAL_BRANCH.
	testEvalCode(state,
		"factorial := method(n, acc, if(n <= 1, acc, factorial(n - 1, n * acc)))");
	IoObject *result = testEvalCode(state, "factorial(20, 1)");

	if (!ISNUMBER(result)) {
		printf("FAILED (not a number)\n");
		return 0;
	}

	// 20! = 2432902008176640000 (fits in double)
	double expected = 2432902008176640000.0;
	double got = IoNumber_asDouble(result);
	if (got != expected) {
		printf("FAILED (got %.0f, expected %.0f)\n", got, expected);
		return 0;
	}

	printf("PASSED\n");
	return 1;
}

int test_tco_if_deep(IoState *state) {
	printf("Test 26: TCO through if (deep recursion)... ");

	// Without TCO through if, this would use 100000+ frames.
	// With TCO through if, the frame stack stays bounded.
	testEvalCode(state,
		"countDown := method(n, acc, if(n <= 0, acc, countDown(n - 1, acc + 1)))");
	IoObject *result = testEvalCode(state, "countDown(100000, 0)");

	if (!ISNUMBER(result)) {
		printf("FAILED (not a number)\n");
		return 0;
	}

	double expected = 100000.0;
	double got = IoNumber_asDouble(result);
	if (got != expected) {
		printf("FAILED (got %.0f, expected %.0f)\n", got, expected);
		return 0;
	}

	printf("PASSED\n");
	return 1;
}

int test_continuation_introspection(IoState *state) {
	printf("Test 27: Continuation introspection... ");

	// Capture a continuation and inspect it
	testEvalCode(state,
		"captured := nil\n"
		"callcc(block(cont, captured = cont))");

	IoObject *frameCount = testEvalCode(state, "captured frameCount");
	if (!ISNUMBER(frameCount) || IoNumber_asInt(frameCount) < 1) {
		printf("FAILED (frameCount=%d, expected >= 1)\n",
			ISNUMBER(frameCount) ? (int)IoNumber_asInt(frameCount) : -1);
		return 0;
	}

	IoObject *states = testEvalCode(state, "captured frameStates");
	if (!ISLIST(states)) {
		printf("FAILED (frameStates not a list)\n");
		return 0;
	}

	IoObject *messages = testEvalCode(state, "captured frameMessages");
	if (!ISLIST(messages)) {
		printf("FAILED (frameMessages not a list)\n");
		return 0;
	}

	// First frame state should be callcc:evalBlock
	IoObject *firstState = testEvalCode(state, "captured frameStates first");
	if (!ISSEQ(firstState)) {
		printf("FAILED (first state not a string)\n");
		return 0;
	}
	const char *stateName = CSTRING(firstState);
	if (strcmp(stateName, "callcc:evalBlock") != 0) {
		printf("FAILED (first state='%s', expected 'callcc:evalBlock')\n", stateName);
		return 0;
	}

	printf("PASSED\n");
	return 1;
}

int test_tco_if_stop_status(IoState *state) {
	printf("Test 28: TCO through if + stop status (? operator)... ");

	// This tests the savedCall mechanism: the ? operator uses
	// relayStopStatus which sets Call stop status. With the in-place
	// if optimization, TCO could replace frame->call and lose the
	// stop status. The savedCall field preserves it.
	//
	// Pattern from ObjectTest: x ?return "first" sends return to x (nil),
	// which triggers RETURN stop status. The ? method must propagate
	// this via relayStopStatus.
	testEvalCode(state,
		"a := method(x, x return \"first\"; \"second\")\n"
		"b := method(x, x ?return \"first\"; \"second\")");

	IoObject *resultA = testEvalCode(state, "a");
	IoObject *resultB = testEvalCode(state, "b");

	if (!ISSEQ(resultA)) {
		printf("FAILED (a not a string, got %s)\n", IoObject_name(resultA));
		return 0;
	}
	if (strcmp(CSTRING(resultA), "first") != 0) {
		printf("FAILED (a='%s', expected 'first')\n", CSTRING(resultA));
		return 0;
	}
	if (!ISSEQ(resultB)) {
		printf("FAILED (b not a string, got %s)\n", IoObject_name(resultB));
		return 0;
	}
	if (strcmp(CSTRING(resultA), CSTRING(resultB)) != 0) {
		printf("FAILED (a='%s' != b='%s')\n", CSTRING(resultA), CSTRING(resultB));
		return 0;
	}

	printf("PASSED\n");
	return 1;
}

int test_question_mark_continue(IoState *state) {
	printf("Test 29: ? operator with continue (stop status)... ");

	// From ObjectTest: ?continue in foreach should behave like continue
	testEvalCode(state,
		"a := method(\n"
		"    r := list\n"
		"    list(1,2,3,4,5) foreach(x,\n"
		"        if(x > 3, continue)\n"
		"        r append(x)\n"
		"    )\n"
		"    r\n"
		")\n"
		"b := method(\n"
		"    r := list\n"
		"    list(1,2,3,4,5) foreach(x,\n"
		"        if(x > 3, ?continue)\n"
		"        r append(x)\n"
		"    )\n"
		"    r\n"
		")");

	IoObject *resultA = testEvalCode(state, "a");
	IoObject *resultB = testEvalCode(state, "b");

	if (!ISLIST(resultA) || !ISLIST(resultB)) {
		printf("FAILED (not lists)\n");
		return 0;
	}

	// Both should be list(1, 2, 3) - items <= 3
	IoObject *sizeA = testEvalCode(state, "a size");
	IoObject *sizeB = testEvalCode(state, "b size");
	if (IoNumber_asInt(sizeA) != 3 || IoNumber_asInt(sizeB) != 3) {
		printf("FAILED (sizes: a=%d, b=%d, expected 3)\n",
			(int)IoNumber_asInt(sizeA), (int)IoNumber_asInt(sizeB));
		return 0;
	}

	printf("PASSED\n");
	return 1;
}

static void IoEvalFrame_markSingle_(IoEvalFrame *self) {
        case FRAME_STATE_FOREACH_EVAL_BODY:
        case FRAME_STATE_FOREACH_AFTER_BODY:
            IoObject_shouldMarkIfNonNull(self->controlFlow.foreachInfo.collection);
            IoObject_shouldMarkIfNonNull(self->controlFlow.foreachInfo.bodyMsg);
            IoObject_shouldMarkIfNonNull(self->controlFlow.foreachInfo.indexName);
            IoObject_shouldMarkIfNonNull(self->controlFlow.foreachInfo.valueName);
            IoObject_shouldMarkIfNonNull(self->controlFlow.foreachInfo.lastResult);
            IoObject_shouldMarkIfNonNull(self->controlFlow.foreachInfo.mapSource);
            break;

}

oid IoState_activateBlockTCO_(IoState *state, IoEvalFrame *blockFrame) {
    IoBlock *block = (IoBlock *)blockFrame->slotValue;
    IoBlockData *blockData = (IoBlockData *)IoObject_dataPointer(block);

    // Create new block locals for the tail-called block
    IoObject *blockLocals = IOCLONE(state->localsProto);
    IoObject_isLocals_(blockLocals, 1);

    // Determine scope
    IoObject *scope =
        blockData->scope ? blockData->scope : blockFrame->target;

    // Create Call object
    IoCall *callObject = IoCall_with(
        state, blockFrame->locals,     // sender (current block's locals)
        blockFrame->target,            // target
        blockFrame->message,           // message
        blockFrame->slotContext,       // slotContext
        block,                         // activated
        state->currentCoroutine        // coroutine
    );

    // Set up block locals slots
    IoObject_createSlotsIfNeeded(blockLocals);
    PHash *bslots = IoObject_slots(blockLocals);
    PHash_at_put_(bslots, state->callSymbol, callObject);
    PHash_at_put_(bslots, state->selfSymbol, scope);
    PHash_at_put_(bslots, state->updateSlotSymbol,
                  state->localsUpdateSlotCFunc);

    // Bind arguments (same as activateBlock_)
    List *argNames = blockData->argNames;
    IoMessage *m = blockFrame->message;
    int argCount = IoMessage_argCount(m);

    LIST_FOREACH(argNames, i, name,
                 IoObject *arg;
                 if ((int)i < argCount) {
                     if (blockFrame->argValues &&
                         (int)i < blockFrame->argCount &&
                         blockFrame->argValues[(int)i] != NULL) {
                         arg = blockFrame->argValues[(int)i];
                     } else {
                         arg = IoMessage_locals_valueArgAt_(
                             m, blockFrame->locals, (int)i);
                     }
                 } else {
                     // Unbound params (fewer args than params) default to nil
                     arg = state->ioNil;
                 }
                 IoObject_setSlot_to_(blockLocals, name, arg););

    IoObject_isReferenced_(blockLocals, 0);
    IoObject_isReferenced_(callObject, 0);

    // REUSE the current frame: replace context with the tail-called block
    blockFrame->message = blockData->message;
    blockFrame->target = blockLocals;
    blockFrame->locals = blockLocals;
    blockFrame->cachedTarget = blockLocals;
    blockFrame->state = FRAME_STATE_START;
    blockFrame->call = callObject;
    blockFrame->blockLocals = blockLocals;
    blockFrame->passStops = blockData->passStops;

    // Free pre-evaluated args from the previous call
    if (blockFrame->argValues) {
        io_free(blockFrame->argValues);
        blockFrame->argValues = NULL;
    }
    blockFrame->argCount = 0;
    blockFrame->currentArgIndex = 0;
    blockFrame->result = NULL;
    blockFrame->slotValue = NULL;
    blockFrame->slotContext = NULL;

    // Signal control flow handling so the eval loop restarts
    // with the updated frame (don't process stale ACTIVATE state)
    state->needsControlFlowHandling = 1;
}

