IoEvalFrame *IoEvalFrame_new(void) {
    IoEvalFrame *self = (IoEvalFrame *)io_calloc(1, sizeof(IoEvalFrame));
    IoEvalFrame_reset(self);
    return self;
}

void IoEvalFrame_free(IoEvalFrame *self) {
    if (!self) {
        return;
    }

    // Free argument values array if allocated
    if (self->argValues) {
        io_free(self->argValues);
        self->argValues = NULL;
    }

    io_free(self);
}

void IoEvalFrame_mark(IoEvalFrame *self) {
    if (!self) {
        return;
    }

    // Mark all IoObject pointers that might be in the frame
    IoObject_shouldMarkIfNonNull(self->message);
    IoObject_shouldMarkIfNonNull(self->target);
    IoObject_shouldMarkIfNonNull(self->locals);
    IoObject_shouldMarkIfNonNull(self->cachedTarget);
    IoObject_shouldMarkIfNonNull(self->result);
    IoObject_shouldMarkIfNonNull(self->slotValue);
    IoObject_shouldMarkIfNonNull(self->slotContext);
    IoObject_shouldMarkIfNonNull(self->call);
    IoObject_shouldMarkIfNonNull(self->blockLocals);

    // Mark evaluated arguments
    if (self->argValues) {
        int i;
        for (i = 0; i < self->currentArgIndex; i++) {
            IoObject_shouldMarkIfNonNull(self->argValues[i]);
        }
    }

    // Recursively mark parent frame
    if (self->parent) {
        IoEvalFrame_mark(self->parent);
    }
}

void IoEvalFrame_reset(IoEvalFrame *self) {
    if (!self) {
        return;
    }

    self->message = NULL;
    self->target = NULL;
    self->locals = NULL;
    self->cachedTarget = NULL;
    self->parent = NULL;
    self->state = FRAME_STATE_START;
    self->argCount = 0;
    self->currentArgIndex = 0;
    self->result = NULL;
    self->slotValue = NULL;
    self->slotContext = NULL;
    self->call = NULL;
    self->blockLocals = NULL;
    self->passStops = 0;

    // Free argument values if allocated
    if (self->argValues) {
        io_free(self->argValues);
        self->argValues = NULL;
    }
}

IoEvalFrame *IoState_pushFrame_(IoState *state) {
    IoEvalFrame *frame;

    // Try to get from pool first
    if (state->framePoolCount > 0) {
        frame = state->framePool[--state->framePoolCount];
        IoEvalFrame_reset(frame);
    } else {
        frame = IoEvalFrame_new();
    }

    frame->parent = state->currentFrame;
    state->currentFrame = frame;
    state->frameDepth++;

    if (state->frameDepth > state->maxFrameDepth) {
        IoState_error_(state, NULL, "Stack overflow: frame depth exceeded %d",
                      state->maxFrameDepth);
    }

    return frame;
}

void IoState_popFrame_(IoState *state) {
    IoEvalFrame *frame = state->currentFrame;
    if (frame) {
        state->currentFrame = frame->parent;
        state->frameDepth--;

        // Return to pool if there's space
        if (state->framePoolCount < 256) {
            IoEvalFrame_reset(frame);
            state->framePool[state->framePoolCount++] = frame;
        } else {
            IoEvalFrame_free(frame);
        }
    }
}

static void IoState_handleStopStatus_(IoState *state) {
    IoEvalFrame *frame = state->currentFrame;

    while (frame) {
        // If this frame is a block activation and it doesn't pass stops,
        // then it should catch the stop status
        if (frame->blockLocals && !frame->passStops) {
            // Caught the stop - return the returnValue and reset status
            frame->result = state->returnValue;
            frame->state = FRAME_STATE_RETURN;
            state->stopStatus = MESSAGE_STOP_STATUS_NORMAL;
            return;
        }

        // Keep unwinding
        frame = frame->parent;
    }

    // If we get here, the stop status wasn't caught
    // This is OK - it will propagate out of the eval loop
}

static void IoState_activateBlock_(IoState *state, IoEvalFrame *callerFrame) {
    IoBlock *block = (IoBlock *)callerFrame->slotValue;
    IoBlockData *blockData = (IoBlockData *)IoObject_dataPointer(block);

    // Create block locals
    IoObject *blockLocals = IOCLONE(state->localsProto);
    IoObject_isLocals_(blockLocals, 1);

    // Determine scope
    IoObject *scope =
        blockData->scope ? blockData->scope : callerFrame->target;

    // Create Call object
    IoCall *callObject = IoCall_with(
        state, callerFrame->locals, // sender
        callerFrame->target,        // target
        callerFrame->message,       // message
        callerFrame->slotContext,   // slotContext
        block,                      // activated
        state->currentCoroutine     // coroutine
    );

    // Set up block locals slots
    IoObject_createSlotsIfNeeded(blockLocals);
    PHash *bslots = IoObject_slots(blockLocals);
    PHash_at_put_(bslots, state->callSymbol, callObject);
    PHash_at_put_(bslots, state->selfSymbol, scope);
    PHash_at_put_(bslots, state->updateSlotSymbol,
                  state->localsUpdateSlotCFunc);

    // Bind arguments (they're already evaluated in callerFrame->argValues)
    List *argNames = blockData->argNames;
    if (callerFrame->argValues) {
        LIST_FOREACH(argNames, i, name,
                     if ((int)i < callerFrame->argCount) {
                         IoObject *arg = callerFrame->argValues[i];
                         IoObject_setSlot_to_(blockLocals, name, arg);
                     });
    }

    // Mark these as unreferenced for potential recycling
    IoObject_isReferenced_(blockLocals, 0);
    IoObject_isReferenced_(callObject, 0);

    // Push new frame for block body evaluation
    IoEvalFrame *blockFrame = IoState_pushFrame_(state);
    blockFrame->message = blockData->message;
    blockFrame->target = blockLocals;
    blockFrame->locals = blockLocals;
    blockFrame->cachedTarget = blockLocals;
    blockFrame->state = FRAME_STATE_START;
    blockFrame->call = callObject;
    blockFrame->blockLocals = blockLocals;
    blockFrame->passStops = blockData->passStops;

    // Caller frame will wait for block frame to return
    // Keep callerFrame in ACTIVATE state - when blockFrame returns,
    // the RETURN handler will move callerFrame to CONTINUE_CHAIN
}

IoObject *IoMessage_locals_performOn_iterative(IoMessage *self,
                                               IoObject *locals,
                                               IoObject *target) {
    IoState *state = IOSTATE;

    // Push initial frame
    IoEvalFrame *frame = IoState_pushFrame_(state);
    frame->message = self;
    frame->target = target;
    frame->locals = locals;
    frame->cachedTarget = target;
    frame->state = FRAME_STATE_START;

    // Run evaluation loop
    IoObject *result = IoState_evalLoop_(state);

    return result;
}

static void IoFramePool_init(IoFramePool *pool) {
    pool->freeCount = FRAME_POOL_SIZE;
    for (int i = 0; i < FRAME_POOL_SIZE; i++) {
        pool->freeList[i] = i;
        IoEvalFrame_reset(&pool->frames[i]);
    }
}

static inline IoEvalFrame *IoFramePool_alloc(IoFramePool *pool) {
    if (pool->freeCount > 0) {
        int idx = pool->freeList[--pool->freeCount];
        return &pool->frames[idx];
    }
    // Pool exhausted - fall back to malloc
    return IoEvalFrame_new();
}

static inline void IoFramePool_free(IoFramePool *pool, IoEvalFrame *frame) {
    // Check if frame is from pool
    if (frame >= &pool->frames[0] &&
        frame < &pool->frames[FRAME_POOL_SIZE]) {
        int idx = frame - &pool->frames[0];
        IoEvalFrame_reset(frame);
        pool->freeList[pool->freeCount++] = idx;
    } else {
        IoEvalFrame_free(frame);
    }
}

static inline IoEvalFrame *IoState_pushFrameFast_(IoState *state, IoFramePool *pool) {
    IoEvalFrame *frame = IoFramePool_alloc(pool);
    frame->parent = state->currentFrame;
    state->currentFrame = frame;
    state->frameDepth++;

    if (state->frameDepth > state->maxFrameDepth) {
        IoState_error_(state, NULL, "Stack overflow: frame depth exceeded %d",
                      state->maxFrameDepth);
    }

    return frame;
}

static inline void IoState_popFrameFast_(IoState *state, IoFramePool *pool) {
    IoEvalFrame *frame = state->currentFrame;
    if (frame) {
        state->currentFrame = frame->parent;
        state->frameDepth--;
        IoFramePool_free(pool, frame);
    }
}

static inline void IoState_activateBlockFast_(IoState *state, IoEvalFrame *callerFrame, IoFramePool *pool) {
    IoBlock *block = (IoBlock *)callerFrame->slotValue;
    IoBlockData *blockData = (IoBlockData *)IoObject_dataPointer(block);

    IoObject *blockLocals = IOCLONE(state->localsProto);
    IoObject_isLocals_(blockLocals, 1);

    IoObject *scope = blockData->scope ? blockData->scope : callerFrame->target;

    IoCall *callObject = IoCall_with(
        state, callerFrame->locals, callerFrame->target,
        callerFrame->message, callerFrame->slotContext,
        block, state->currentCoroutine
    );

    IoObject_createSlotsIfNeeded(blockLocals);
    PHash *bslots = IoObject_slots(blockLocals);
    PHash_at_put_(bslots, state->callSymbol, callObject);
    PHash_at_put_(bslots, state->selfSymbol, scope);
    PHash_at_put_(bslots, state->updateSlotSymbol, state->localsUpdateSlotCFunc);

    List *argNames = blockData->argNames;
    if (callerFrame->argValues) {
        LIST_FOREACH(argNames, i, name,
                     if ((int)i < callerFrame->argCount) {
                         IoObject *arg = callerFrame->argValues[i];
                         IoObject_setSlot_to_(blockLocals, name, arg);
                     });
    }

    IoObject_isReferenced_(blockLocals, 0);
    IoObject_isReferenced_(callObject, 0);

    IoEvalFrame *blockFrame = IoState_pushFrameFast_(state, pool);
    blockFrame->message = blockData->message;
    blockFrame->target = blockLocals;
    blockFrame->locals = blockLocals;
    blockFrame->cachedTarget = blockLocals;
    blockFrame->state = FRAME_STATE_START;
    blockFrame->call = callObject;
    blockFrame->blockLocals = blockLocals;
    blockFrame->passStops = blockData->passStops;
}

CASE(STATE_START) {
            m = frame->message;
            if (!m) {
                frame->result = state->ioNil;
                frame->state = FRAME_STATE_RETURN;
                DISPATCH();
            }

            md = IOMESSAGEDATA(m);

            // FAST PATH: Semicolon
            if (md->name == state->semicolonSymbol) {
                frame->target = frame->cachedTarget;
                frame->message = md->next;
                if (md->next) {
                    frame->state = FRAME_STATE_START;
                } else {
                    frame->result = frame->target;
                    frame->state = FRAME_STATE_RETURN;
                }
                DISPATCH();
            }

            // FAST PATH: Cached result (literals)
            if (md->cachedResult) {
                frame->result = md->cachedResult;
                if (!md->next) {
                    frame->state = FRAME_STATE_RETURN;
                } else {
                    frame->state = FRAME_STATE_CONTINUE_CHAIN;
                }
                DISPATCH();
            }

            // Need argument evaluation
            frame->argCount = List_size(md->args);
            frame->currentArgIndex = 0;

            if (frame->argCount > 0) {
                frame->argValues = io_calloc(frame->argCount, sizeof(IoObject *));
                frame->state = FRAME_STATE_EVAL_ARGS;
            } else {
                frame->state = FRAME_STATE_LOOKUP_SLOT;
            }
            DISPATCH();
        }

CASE(STATE_EVAL_ARGS) {
            if (frame->currentArgIndex >= frame->argCount) {
                frame->state = FRAME_STATE_LOOKUP_SLOT;
                DISPATCH();
            }

            IoMessage *argMsg = List_at_(IOMESSAGEDATA(frame->message)->args,
                                         frame->currentArgIndex);

            if (!argMsg) {
                frame->argValues[frame->currentArgIndex] = state->ioNil;
                frame->currentArgIndex++;
                DISPATCH();
            }

            // FAST PATH: Cached argument
            IoMessageData *argMd = IOMESSAGEDATA(argMsg);
            if (argMd->cachedResult && !argMd->next) {
                frame->argValues[frame->currentArgIndex] = argMd->cachedResult;
                frame->currentArgIndex++;
                DISPATCH();
            }

            // Need to evaluate - push frame
            IoEvalFrame *argFrame = IoState_pushFrameFast_(state, pool);
            argFrame->message = argMsg;
            argFrame->target = frame->locals;
            argFrame->locals = frame->locals;
            argFrame->cachedTarget = frame->locals;
            argFrame->state = FRAME_STATE_START;
            DISPATCH();
        }

CASE(STATE_LOOKUP_SLOT) {
            messageName = IoMessage_name(frame->message);
            slotValue = IoObject_rawGetSlot_context_(frame->target, messageName, &slotContext);

            if (slotValue) {
                frame->slotValue = slotValue;
                frame->slotContext = slotContext;
                frame->state = FRAME_STATE_ACTIVATE;
            } else {
                if (IoObject_isLocals(frame->target)) {
                    frame->result = IoObject_localsForward(frame->target, frame->locals, frame->message);
                } else {
                    frame->result = IoObject_forward(frame->target, frame->locals, frame->message);
                }
                frame->state = FRAME_STATE_CONTINUE_CHAIN;
            }
            DISPATCH();
        }

CASE(STATE_ACTIVATE) {
            slotValue = frame->slotValue;

            if (IoObject_isActivatable(slotValue)) {
                if (ISBLOCK(slotValue)) {
                    IoState_activateBlockFast_(state, frame, pool);
                    DISPATCH();
                } else {
                    // CFunction
                    IoTagActivateFunc *activateFunc = IoObject_tag(slotValue)->activateFunc;
                    IoState_pushRetainPool(state);
                    frame->result = activateFunc(slotValue, frame->target, frame->locals,
                                                 frame->message, frame->slotContext);
                    IoState_popRetainPoolExceptFor_(state, frame->result);
                    frame->state = FRAME_STATE_CONTINUE_CHAIN;
                }
            } else {
                frame->result = slotValue;
                frame->state = FRAME_STATE_CONTINUE_CHAIN;
            }
            DISPATCH();
        }

CASE(STATE_CONTINUE_CHAIN) {
            IoMessage *next = IOMESSAGEDATA(frame->message)->next;

            if (next) {
                frame->target = frame->result;
                frame->message = next;
                frame->state = FRAME_STATE_START;

                if (frame->argValues) {
                    io_free(frame->argValues);
                    frame->argValues = NULL;
                }
                frame->argCount = 0;
                frame->currentArgIndex = 0;
            } else {
                frame->state = FRAME_STATE_RETURN;
            }
            DISPATCH();
        }

CASE(STATE_RETURN) {
            result = frame->result;
            IoEvalFrame *parent = frame->parent;

            if (parent) {
                if (parent->state == FRAME_STATE_EVAL_ARGS) {
                    parent->argValues[parent->currentArgIndex] = result;
                    parent->currentArgIndex++;
                } else if (parent->state == FRAME_STATE_ACTIVATE) {
                    parent->result = result;
                    parent->state = FRAME_STATE_CONTINUE_CHAIN;
                }
            }

            IoState_popFrameFast_(state, pool);
            DISPATCH();
        }

IoObject *IoMessage_locals_performOn_fast(IoMessage *self, IoObject *locals, IoObject *target) {
    IoState *state = IOSTATE;

    // Initialize thread-local frame pool
    static __thread IoFramePool pool;
    static __thread int pool_initialized = 0;
    if (!pool_initialized) {
        IoFramePool_init(&pool);
        pool_initialized = 1;
    }

    // Push initial frame
    IoEvalFrame *frame = IoState_pushFrameFast_(state, &pool);
    frame->message = self;
    frame->target = target;
    frame->locals = locals;
    frame->cachedTarget = target;
    frame->state = FRAME_STATE_START;

    // Run optimized evaluation loop
    IoObject *result = IoState_evalLoopFast_(state, &pool);

    return result;
}

double benchmarkRecursive(IoState *state, const char *code, int iterations) {
    IoMessage *msg = parseCode(state, code);
    clock_t start = clock();

    for (int i = 0; i < iterations; i++) {
        IoMessage_locals_performOn_(msg, state->lobby, state->lobby);
    }

    clock_t end = clock();
    return ((double)(end - start)) / CLOCKS_PER_SEC;
}

double benchmarkIterative(IoState *state, const char *code, int iterations) {
    IoMessage *msg = parseCode(state, code);
    clock_t start = clock();

    for (int i = 0; i < iterations; i++) {
        IoMessage_locals_performOn_iterative(msg, state->lobby, state->lobby);
    }

    clock_t end = clock();
    return ((double)(end - start)) / CLOCKS_PER_SEC;
}

void runBenchmark(IoState *state, const char *name, const char *code, int iterations) {
    printf("\n%s:\n", name);
    printf("  Code: %s\n", code);

    // Warm up
    parseCode(state, code);

    // Benchmark recursive
    double recursiveTime = benchmarkRecursive(state, code, iterations);
    double recursiveOpsPerSec = iterations / recursiveTime;

    // Benchmark iterative (now with frame pooling!)
    double iterativeTime = benchmarkIterative(state, code, iterations);
    double iterativeOpsPerSec = iterations / iterativeTime;

    printf("  Recursive: %.3f sec (%.2f M ops/sec)\n",
           recursiveTime, recursiveOpsPerSec / 1000000.0);
    printf("  Pooled:    %.3f sec (%.2f M ops/sec) - %.2fx overhead\n",
           iterativeTime, iterativeOpsPerSec / 1000000.0, iterativeTime / recursiveTime);

    double speedup = recursiveOpsPerSec / iterativeOpsPerSec;
    printf("  Target:    Need %.2fx faster to match Ruby goal\n", speedup * 10.0);
}

int main(int argc, char **argv) {
    printf("=== Io Evaluator Performance Benchmark ===\n");
    printf("Iterations: %d\n", ITERATIONS);

    IoState *state = IoState_new();
    IoState_init(state);

    // Set up some test data
    IoMessage *msg = parseCode(state, "x := 42; y := 100");
    IoMessage_locals_performOn_(msg, state->lobby, state->lobby);

    msg = parseCode(state, "add := method(a, b, a + b)");
    IoMessage_locals_performOn_(msg, state->lobby, state->lobby);

    // Run benchmarks
    runBenchmark(state, "Local Access", "x", ITERATIONS);
    runBenchmark(state, "Local Set", "x = 123", ITERATIONS);
    runBenchmark(state, "Slot Access", "List", ITERATIONS);
    runBenchmark(state, "Simple Message", "2 + 3", ITERATIONS);
    runBenchmark(state, "Message Chain", "2 + 3 + 4", ITERATIONS);
    runBenchmark(state, "Block Activation", "block(42) call", ITERATIONS);
    runBenchmark(state, "Method Call", "add(10, 20)", ITERATIONS / 10);

    printf("\n=== Summary ===\n");
    printf("The iterative evaluator trades some performance for:\n");
    printf("  - No C stack dependence (enables continuations)\n");
    printf("  - Serializable execution state\n");
    printf("  - Better stack overflow handling\n");
    printf("  - Network-portable coroutines\n");

    return 0;
}

