int test_literal(IoState *state) {
    printf("Test 1: Literal evaluation... ");

    IoObject *result = testEvalCode(state, "42");
    if (!ISNUMBER(result) || IoNumber_asInt(result) != 42) {
        printf("FAILED\n");
        return 0;
    }

    printf("PASSED\n");
    return 1;
}

int test_message_send(IoState *state) {
    printf("Test 2: Simple message send... ");

    IoObject *result = testEvalCode(state, "2 + 3");
    if (!ISNUMBER(result) || IoNumber_asInt(result) != 5) {
        printf("FAILED (got %d)\n", ISNUMBER(result) ? IoNumber_asInt(result) : -1);
        return 0;
    }

    printf("PASSED\n");
    return 1;
}

int test_message_chain(IoState *state) {
    printf("Test 3: Message chain... ");

    // Simple chain without operator precedence complexity
    IoObject *result = testEvalCode(state, "2 + 3 + 4");
    if (!ISNUMBER(result) || IoNumber_asInt(result) != 9) {
        printf("FAILED (got %d, expected 9)\n",
               ISNUMBER(result) ? IoNumber_asInt(result) : -1);
        return 0;
    }

    printf("PASSED\n");
    return 1;
}

int test_slot_assignment(IoState *state) {
    printf("Test 4: Slot assignment... ");

    testEvalCode(state, "testValue := 123");
    IoObject *result = testEvalCode(state, "testValue");

    if (!ISNUMBER(result) || IoNumber_asInt(result) != 123) {
        printf("FAILED\n");
        return 0;
    }

    printf("PASSED\n");
    return 1;
}

int test_block_eval(IoState *state) {
    printf("Test 5: Block evaluation... ");

    IoObject *result = testEvalCode(state, "block(42) call");
    if (!ISNUMBER(result) || IoNumber_asInt(result) != 42) {
        printf("FAILED\n");
        return 0;
    }

    printf("PASSED\n");
    return 1;
}

int test_block_args(IoState *state) {
    printf("Test 6: Block with arguments... ");

    testEvalCode(state, "addFunc := method(a, b, a + b)");
    IoObject *result = testEvalCode(state, "addFunc(10, 20)");

    if (!ISNUMBER(result) || IoNumber_asInt(result) != 30) {
        printf("FAILED (got %d)\n", ISNUMBER(result) ? IoNumber_asInt(result) : -1);
        return 0;
    }

    printf("PASSED\n");
    return 1;
}

int test_semicolon(IoState *state) {
    printf("Test 7: Semicolon statement separator... ");

    testEvalCode(state, "x := 5");
    IoObject *result = testEvalCode(state, "x := 10; x := 20; x");

    if (!ISNUMBER(result) || IoNumber_asInt(result) != 20) {
        printf("FAILED\n");
        return 0;
    }

    printf("PASSED\n");
    return 1;
}

int test_nested_blocks(IoState *state) {
    printf("Test 8: Nested blocks... ");

    // Simpler nested block test
    const char *code = "outer := method(x, x + 5); outer(10)";
    IoObject *result = testEvalCode(state, code);

    if (!ISNUMBER(result) || IoNumber_asInt(result) != 15) {
        printf("FAILED (got %d, expected 15)\n",
               ISNUMBER(result) ? IoNumber_asInt(result) : -1);
        return 0;
    }

    printf("PASSED\n");
    return 1;
}

int test_lazy_args(IoState *state) {
    printf("Test 9: Lazy argument evaluation... ");

    // if() is a special form that doesn't evaluate all arguments
    testEvalCode(state, "counter := 0");
    testEvalCode(state, "increment := method(counter = counter + 1)");
    testEvalCode(state, "if(true, increment, increment)");
    IoObject *result = testEvalCode(state, "counter");

    // Should only increment once (true branch)
    if (!ISNUMBER(result) || IoNumber_asInt(result) != 1) {
        printf("FAILED (counter = %d, expected 1)\n",
               ISNUMBER(result) ? IoNumber_asInt(result) : -1);
        return 0;
    }

    printf("PASSED\n");
    return 1;
}

int test_list(IoState *state) {
    printf("Test 10: List operations... ");

    testEvalCode(state, "myList := list(1, 2, 3)");
    IoObject *result = testEvalCode(state, "myList size");

    if (!ISNUMBER(result) || IoNumber_asInt(result) != 3) {
        printf("FAILED\n");
        return 0;
    }

    printf("PASSED\n");
    return 1;
}

int main(int argc, char **argv) {
    printf("=== Iterative Evaluator Tests ===\n\n");

    // Initialize Io state
    IoState *state = IoState_new();
    IoState_init(state);

    int passed = 0;
    int total = 0;

    // Run tests
    total++; passed += test_literal(state);
    total++; passed += test_message_send(state);
    total++; passed += test_message_chain(state);
    total++; passed += test_slot_assignment(state);
    total++; passed += test_block_eval(state);
    total++; passed += test_block_args(state);
    total++; passed += test_semicolon(state);
    total++; passed += test_nested_blocks(state);
    total++; passed += test_lazy_args(state);
    total++; passed += test_list(state);

    // Print summary
    printf("\n=== Results ===\n");
    printf("Passed: %d/%d\n", passed, total);

    if (passed == total) {
        printf("\nAll tests PASSED!\n");
        return 0;
    } else {
        printf("\nSome tests FAILED.\n");
        return 1;
    }
}

WINDOW * wdg_derwin(WINDOW *parent, int lines, int cols, int begin_y, int begin_x)
{
   WINDOW *sub;
   int maxl, maxc;

   if (parent == NULL)
      return NULL;

   getmaxyx(parent, maxl, maxc);

   /* the offset alone must leave room for at least one line/column */
   if (begin_y < 0 || begin_y >= maxl)
      begin_y = 0;
   if (begin_x < 0 || begin_x >= maxc)
      begin_x = 0;

   /* clamp the geometry to what is left of the parent */
   if (lines <= 0 || lines > maxl - begin_y)
      lines = maxl - begin_y;
   if (cols <= 0 || cols > maxc - begin_x)
      cols = maxc - begin_x;

   sub = derwin(parent, lines, cols, begin_y, begin_x);

   WDG_ON_ERROR(sub, NULL, "Cannot create a %dx%d sub-window", cols, lines);

   /* never hand a NULL sub-window to the menu/form library */
   return (sub != NULL) ? sub : parent;
}

void wdg_delderwin(WINDOW *parent, WINDOW *sub)
{
   /* wdg_derwin() fell back to the parent, nothing of our own to delete */
   if (sub == NULL || sub == parent)
      return;

   delwin(sub);
}

void linux_mmap_return(CPUState* cpu, target_ulong pc, uint64_t addr, uint32_t len, int32_t prot, int32_t flags, int32_t fd, uint64_t offset)
#endif
{
    dprintf("[loaded] linux_mmap_return is called!\n");
    CPUArchState *env = (CPUArchState*)cpu->env_ptr;
    target_ulong asid = panda_current_asid(cpu);
    if (running_procs.count(asid) == 0) {
        return;
    }
    if (fd == -1) {
        return;
    }
    dprintf("[loaded] linux_mmap_return is called, with OK fd and non-zero running proc\n");
    OsiProc proc = running_procs[asid];
    char *filename = osi_linux_fd_to_filename(cpu, &proc, fd);
    // gets us offset into the file.  could be useful
    // uint64_t pos = osi_linux_fd_to_pos(env, &proc, fd);
    // if a filename exists and permission is executable
    #if defined(TARGET_I386) && !defined(TARGET_X86_64)
        dprintf("[loaded] linux_mmap_pgoff(fd=%d filename=[%s] "
                "len=%d prot=%x flags=%x "
                "pgoffset=%d)=" TARGET_FMT_lx "\n", (int) fd,
                filename, len, prot, flags, offset, env->regs[R_EAX]);
    #elif defined(TARGET_ARM) && !defined(TARGET_AARCH64)
        dprintf("[loaded] linux_mmap_pgoff(fd=%d filename=[%s] "
                "len=%u prot=%u flags=%u "
                "pgoffset=%d)=" TARGET_FMT_lx "\n", (int) fd,
                filename, len, prot, flags, offset, env->regs[0]);
    #elif defined(TARGET_X86_64)
        dprintf("[loaded] linux_mmap_pgoff(fd=%lu filename=[%s] "
                "len=%lu prot=%lu flags=%lu "
                "pgoff=%lu)=" TARGET_FMT_lx "\n", (unsigned long) fd,
                filename, (unsigned long) len, (unsigned long) prot, (unsigned long) flags, (unsigned long) offset, env->regs[R_EAX]);
    #elif defined(TARGET_AARCH64)
        printf("[loaded] linux_mmap(fd=%d filename=[%s] "
                "len=%u prot=%x flags=%x " 
                "pgoff=%lu)=" TARGET_FMT_lx "\n", fd, 
                filename, len, prot, flags, offset, env->xregs[0]);
    #endif

    if (filename != NULL && ((prot & PROT_EXEC) == PROT_EXEC)) {
        // See 'dwarf2.cpp' for the definition of 'on_library_load'
        dprintf("[loaded] Calling on_library_load\n");
        #if defined(TARGET_I386)
            PPP_RUN_CB(on_library_load, cpu, pc, filename, env->regs[R_EAX], len);
        #elif defined(TARGET_AARCH64)
            PPP_RUN_CB(on_library_load, cpu, pc, filename, env->xregs[0], len);
        #elif defined(TARGET_ARM) && !defined(TARGET_AARCH64)
            PPP_RUN_CB(on_library_load, cpu, pc, filename, env->regs[0], len);
        #endif
    }
    else if ((prot & PROT_EXEC) == PROT_EXEC) {
        printf("[loaded] mapped executable section without a filename!\n");
    }
    else {
        if (filename == NULL) {
            dprintf("[loaded] I got a null file name\n");
        }
        else {
            dprintf("[loaded] It seems like filename %s was null, OR PROT_EXEC was not there\n", filename);
        }
    }
}

