{
	for (unsigned i = 0; i < 17; i++) {
		const unsigned long scno = ARRAY_SIZE(syscallent) + i;

		(void) invoke_syscall(scno);
		printf("syscall_%#lx\n", scno | SYSCALL_BIT);
	}

