static void
unknown_init_slot(struct call_counts *cc)
{
	cc->time_min = max_ts;

	if (summary_needs_wall())
		cc->wall_time_min = max_ts;
}

static void
unknown_init(void)
{
	if (unknown_counts)
		return;

	unknown_counts = xmalloc(sizeof(*unknown_counts));

	unknown_counts->len = 0;
	unknown_counts->cap = UNKNOWN_COUNTS_ENTRIES;
	unknown_counts->entries = xcalloc(UNKNOWN_COUNTS_ENTRIES,
					  sizeof(*unknown_counts->entries));

	for (size_t i = 0; i < UNKNOWN_COUNTS_ENTRIES; i++)
		unknown_init_slot(&unknown_counts->entries[i].call_counts);
}

static struct unknown_call_counts *
get_unknown_by_scno(kernel_ulong_t scno)
{
	if (!unknown_counts)
		return NULL;

	for (size_t i = 0; i < unknown_counts->len; i++)
		if (unknown_counts->entries[i].scno == scno)
			return &unknown_counts->entries[i];

	return NULL;
}

static struct unknown_call_counts *
get_unknown_by_idx(size_t idx)
{
	if (!unknown_counts)
		return NULL;

	if (idx >= unknown_counts->len)
		return NULL;

	return &unknown_counts->entries[idx];
}

static size_t
get_unknown_bucket_size(void)
{
	return unknown_counts ? unknown_counts->len : 0;
}

static struct call_counts *
get_syscall_cc(kernel_ulong_t scno)
{
	if (scno_in_range(scno))
		return &counts[scno];

	struct unknown_call_counts *ucc = get_unknown_by_scno(scno);
	if (!ucc)
		error_msg_and_die("failed to get unknown syscall"
				  " counts by %#" PRI_klx " number", scno);

	return &ucc->call_counts;
}

static const char *
get_syscall_name(kernel_ulong_t scno)
{
	if (scno_in_range(scno))
		return sysent[scno].sys_name;

	struct unknown_call_counts *ucc = get_unknown_by_scno(scno);
	if (!ucc)
		error_msg_and_die("failed to get unknown syscall"
				  " name by %#" PRI_klx " number", scno);

	return ucc->sys_name;
}

static void
unknown_insert(kernel_ulong_t scno)
{
	if (get_unknown_by_scno(scno))
		return;

	unknown_init();

	if (unknown_counts->len == unknown_counts->cap) {
		unknown_counts->cap *= 2;
		unknown_counts->entries = xreallocarray(unknown_counts->entries,
							unknown_counts->cap,
							sizeof(*unknown_counts->entries));

		for (size_t i = unknown_counts->len; i < unknown_counts->cap; i++)
			unknown_init_slot(&unknown_counts->entries[i].call_counts);
	}

	unknown_counts->entries[unknown_counts->len].scno = scno;
	xsprintf(unknown_counts->entries[unknown_counts->len].sys_name,
		 "syscall_%#" PRI_klx, shuffle_scno(scno));
	unknown_counts->len++;
}

static void
call_summary_pers(FILE *outf)
{
	/*
	 * unknown system calls start at index nsyscalls
	 * and their index may differ from their number
	 */
	kernel_ulong_t *indices;
	size_t indices_size = nsyscalls + get_unknown_bucket_size();
	size_t last_column = 0;
	struct summary_stats stats = {
		.tv_cum      	 = zero_ts,
		.tv_min      	 = &max_ts,
		.tv_min_max  	 = &zero_ts,
		.tv_max      	 = &zero_ts,
		.tv_avg_max  	 = &zero_ts,
		.tv_wall_cum 	 = zero_ts,
		.tv_wall_min 	 = &max_ts,
		.tv_wall_min_max = &zero_ts,
		.tv_wall_max 	 = &zero_ts,
		.tv_wall_avg_max = &zero_ts,
		.call_cum    	 = 0,
		.error_cum   	 = 0,
		.sc_name_max 	 = 0
	};
	/* sort, calculate statistics (for known syscalls) */
	indices = xcalloc(indices_size, sizeof(indices[0]));
		calc_summary_stats(&stats, &counts[i], sysent[i].sys_name);
	}

static void
timespec_sub(struct timespec *res, const struct timespec *a,
	     const struct timespec *b)
{
	res->tv_sec = a->tv_sec - b->tv_sec;
	res->tv_nsec = a->tv_nsec - b->tv_nsec;
	if (res->tv_nsec < 0) {
		res->tv_sec--;
		res->tv_nsec += 1000000000L;
	}
}

static double
timespec_to_sec(const struct timespec *ts)
{
	return (double) ts->tv_sec + (double) ts->tv_nsec / 1e9;
}

static void
write_timing_file(const char *path, int requested, double nanosleep_sec)
{
	FILE *fp = fopen(path, "w");

	if (!fp)
		perror_msg_and_fail("fopen: %s", path);

	if (fprintf(fp,
		    "requested_sec=%d\n"
		    "nanosleep_sec=%.9f\n",
		    requested, nanosleep_sec) < 0)
		perror_msg_and_fail("fprintf: %s", path);

	if (fclose(fp))
		perror_msg_and_fail("fclose: %s", path);
}

int
main(int ac, char **av)
{
	struct timespec t0;
	struct timespec t1;
	struct timespec delta;
	const char *timing_file;
	double nanosleep_sec;
	int requested_sec;

	if (ac < 3)
		error_msg_and_fail("missing operand");

	if (ac > 3)
		error_msg_and_fail("extra operand");

	requested_sec = atoi(av[1]);
	timing_file = av[2];

	kernel_old_timespec_t ts = { requested_sec, 0 };

	if (!chdir(""))
		error_msg_and_fail("chdir");

	if (clock_gettime(CLOCK_MONOTONIC, &t0))
		perror_msg_and_fail("clock_gettime");

	if (syscall(__NR_nanosleep, (unsigned long) &ts, 0))
		perror_msg_and_fail("nanosleep");

	if (clock_gettime(CLOCK_MONOTONIC, &t1))
		perror_msg_and_fail("clock_gettime");

	if (chdir("."))
		perror_msg_and_fail("chdir");

	timespec_sub(&delta, &t1, &t0);
	nanosleep_sec = timespec_to_sec(&delta);

	write_timing_file(timing_file, requested_sec, nanosleep_sec);

	return 0;
}

static bool
summary_needs_wall(void)
{
	return summary_wall_columns || summary_sortby_wall;
}

static bool
column_is_wall(uint8_t column)
{
	return column >= CSC_TIME_WALL_TOTAL && column <= CSC_TIME_WALL_AVG;
}

static void
decode_fs_shutdown(struct tcb *const tcp, const kernel_ulong_t arg)
{
	uint32_t flags;

	if (umove_or_printaddr(tcp, arg, &flags))
		return;

	tprint_indirect_begin();
	printxval(fs_shutdown_flags, flags, "FS_SHUTDOWN_FLAGS_???");
	tprint_indirect_end();
}

static bool
pidfd_ioctl_is_namespace_fd(const unsigned int code)
{
	switch (code) {
		case PIDFD_GET_CGROUP_NAMESPACE:
		case PIDFD_GET_IPC_NAMESPACE:
		case PIDFD_GET_MNT_NAMESPACE:
		case PIDFD_GET_NET_NAMESPACE:
		case PIDFD_GET_PID_NAMESPACE:
		case PIDFD_GET_PID_FOR_CHILDREN_NAMESPACE:
		case PIDFD_GET_TIME_NAMESPACE:
		case PIDFD_GET_TIME_FOR_CHILDREN_NAMESPACE:
		case PIDFD_GET_USER_NAMESPACE:
		case PIDFD_GET_UTS_NAMESPACE:
			return true;
		default:
			return false;
	}
}

static int
do_ioctl(kernel_ulong_t cmd, kernel_ulong_t arg)
{
	int rc = ioctl(-1, cmd, arg);

	errstr = sprintrc(rc);

	return rc;
}

int
main(void)
{
	static const struct strval32 cmds[] = {
		{ ARG_STR(PIDFD_GET_CGROUP_NAMESPACE) },
		{ ARG_STR(PIDFD_GET_IPC_NAMESPACE) },
		{ ARG_STR(PIDFD_GET_MNT_NAMESPACE) },
		{ ARG_STR(PIDFD_GET_NET_NAMESPACE) },
		{ ARG_STR(PIDFD_GET_PID_NAMESPACE) },
		{ ARG_STR(PIDFD_GET_PID_FOR_CHILDREN_NAMESPACE) },
		{ ARG_STR(PIDFD_GET_TIME_NAMESPACE) },
		{ ARG_STR(PIDFD_GET_TIME_FOR_CHILDREN_NAMESPACE) },
		{ ARG_STR(PIDFD_GET_USER_NAMESPACE) },
		{ ARG_STR(PIDFD_GET_UTS_NAMESPACE) },
		{ ARG_STR(_IOC(_IOC_NONE, 0xff, 0xfe, 0xfd)) }
	};
	static const kernel_ulong_t args[] = {
		0,
		(kernel_ulong_t) 0xfacefeeddeadbeefULL
	};

	for (unsigned int i = 0; i < ARRAY_SIZE(cmds); ++i) {
		for (unsigned int j = 0; j < ARRAY_SIZE(args); ++j) {
			do_ioctl(cmds[i].val, args[j]);
			printf("ioctl(-1, " XLAT_FMT ", %#llx) = %s\n",
			       XLAT_SEL(cmds[i].val, cmds[i].str),
			       (unsigned long long) args[j],
			       errstr);
		}
	}

	puts("+++ exited with 0 +++");
	return 0;
}

static bool
pidfd_ioctl_is_get_info(const unsigned int code)
{
	return _IOC_TYPE(code) == PIDFS_IOCTL_MAGIC
	       && _IOC_NR(code) == _IOC_NR(PIDFD_GET_INFO);
}

static void
pidfd_ioctl_print_pidfd_info_fields(struct tcb *tcp,
				    const struct pidfd_info *info,
				    const unsigned int usize)
{
	const unsigned int len = MIN(sizeof(*info), usize);
	const uint64_t m = info->mask;

	if ((m & PIDFD_INFO_CGROUPID)
	    && len >= offsetofend(struct pidfd_info, cgroupid)) {
		tprint_struct_next();
		PRINT_FIELD_U(*info, cgroupid);
	}

	if ((m & PIDFD_INFO_PID)
	    && len >= offsetofend(struct pidfd_info, ppid)) {
		tprint_struct_next();
		PRINT_FIELD_TID(*info, pid, tcp);
		tprint_struct_next();
		PRINT_FIELD_TGID(*info, tgid, tcp);
		tprint_struct_next();
		PRINT_FIELD_TGID(*info, ppid, tcp);
	}

	if ((m & PIDFD_INFO_CREDS)
	    && len >= offsetofend(struct pidfd_info, fsgid)) {
		tprint_struct_next();
		tprints_field_name("ruid");
		printuid(info->ruid);
		tprint_struct_next();
		tprints_field_name("rgid");
		printuid(info->rgid);
		tprint_struct_next();
		tprints_field_name("euid");
		printuid(info->euid);
		tprint_struct_next();
		tprints_field_name("egid");
		printuid(info->egid);
		tprint_struct_next();
		tprints_field_name("suid");
		printuid(info->suid);
		tprint_struct_next();
		tprints_field_name("sgid");
		printuid(info->sgid);
		tprint_struct_next();
		tprints_field_name("fsuid");
		printuid(info->fsuid);
		tprint_struct_next();
		tprints_field_name("fsgid");
		printuid(info->fsgid);
	}

	if ((m & PIDFD_INFO_EXIT)
	    && len >= offsetofend(struct pidfd_info, exit_code)) {
		tprint_struct_next();
		tprints_field_name("exit_code");
		print_wait_status(info->exit_code);
	}

	if ((m & PIDFD_INFO_COREDUMP)
	    && len >= offsetofend(struct pidfd_info, coredump_mask)) {
		tprint_struct_next();
		PRINT_FIELD_FLAGS(*info, coredump_mask,
				  pidfd_coredump_mask,
				  "PIDFD_COREDUMP_???");
	}

	if ((m & PIDFD_INFO_COREDUMP_SIGNAL)
	    && len >= offsetofend(struct pidfd_info, coredump_signal)) {
		tprint_struct_next();
		tprints_field_name("coredump_signal");
		printsignal(info->coredump_signal);
	}

	if ((m & PIDFD_INFO_COREDUMP_CODE)
	    && len >= offsetofend(struct pidfd_info, coredump_code)) {
		tprint_struct_next();
		tprints_field_name("coredump_code");
		PRINT_VAL_U(info->coredump_code);
	}

	if ((m & PIDFD_INFO_SUPPORTED_MASK)
	    && len >= offsetofend(struct pidfd_info, supported_mask)) {
		tprint_struct_next();
		PRINT_FIELD_FLAGS(*info, supported_mask, pidfd_info_mask,
				  "PIDFD_INFO_???");
	}
}

static void
pidfd_ioctl_print_pidfd_get_info(struct tcb *tcp,
				 const kernel_ulong_t arg,
				 const unsigned int usize,
				 const uint64_t req_mask)
{
	struct pidfd_info info = { 0 };
	const unsigned int len = MIN(sizeof(info), usize);

	if (umoven_or_printaddr(tcp, arg, len, &info))
		return;

	tprint_struct_begin();
	tprints_field_name("mask");
	printflags64(pidfd_info_mask, req_mask, "PIDFD_INFO_???");

	if (info.mask != req_mask) {
		tprint_value_changed();
		printflags64(pidfd_info_mask, info.mask, "PIDFD_INFO_???");
	}

	pidfd_ioctl_print_pidfd_info_fields(tcp, &info, usize);

	tprint_struct_end();
}

int
pidfd_ioctl(struct tcb *tcp, unsigned int code, kernel_ulong_t arg)
{
	if (!pidfd_ioctl_is_get_info(code))
		return RVAL_DECODED;

	if (entering(tcp))
		tprints_arg_next_name("argp");

	const unsigned int usize = _IOC_SIZE(code);

	if (usize < PIDFD_INFO_SIZE_VER0) {
		printaddr(arg);
		return RVAL_IOCTL_DECODED;
	}

	struct pidfd_info info;

	if (entering(tcp)) {
		if (umove_or_printaddr(tcp, arg, &info.mask))
			return RVAL_IOCTL_DECODED;

		if (sizeof(info.mask) > sizeof(long)) {
			typeof(info.mask) *req_mask_p = xmalloc(sizeof(*req_mask_p));
			*req_mask_p = info.mask;
			set_tcb_priv_data(tcp, req_mask_p, free);
		} else {
			set_tcb_priv_ulong(tcp, (unsigned long) info.mask);
		}

		return 0;
	}

	if (sizeof(info.mask) > sizeof(long)) {
		typeof(info.mask) *req_mask_p = get_tcb_priv_data(tcp);
		if (!req_mask_p) {
			printaddr(arg);
			return RVAL_IOCTL_DECODED;
		}
		info.mask = *req_mask_p;
	} else {
		info.mask = get_tcb_priv_ulong(tcp);
	}

	pidfd_ioctl_print_pidfd_get_info(tcp, arg, usize, info.mask);

	return RVAL_IOCTL_DECODED;
}

static int
do_ioctl_fd(int fd, kernel_ulong_t cmd, kernel_ulong_t arg)
{
	int rc = ioctl(fd, cmd, arg);

	errstr = sprintrc(rc);

#ifdef INJECT_RETVAL
	if (rc != INJECT_RETVAL)
		error_msg_and_fail("Return value [%d] does not match"
				   " expectations [%d]", rc, INJECT_RETVAL);

	static char inj_errstr[4096];

	snprintf(inj_errstr, sizeof(inj_errstr), "%s (INJECTED)", errstr);
	errstr = inj_errstr;
#endif

	return rc;
}

static void
skip_ioctls(const char *const *argv)
{
	unsigned long num_skip;
	long inject_retval;

	num_skip = strtoul(argv[1], NULL, 0);
	inject_retval = strtol(argv[2], NULL, 0);
	if (inject_retval < 0)
		error_msg_and_fail("Expected non-negative INJECT_RETVAL, "
				   "but got %ld", inject_retval);

	for (size_t i = 0; i < num_skip; ++i) {
		int rc = ioctl(-1, PIDFD_GET_INFO, 0);

		printf("ioctl(-1, " XLAT_FMT ", NULL) = %s%s\n",
		       XLAT_SEL(pidfd_get_info_cmd.val, pidfd_get_info_cmd.str),
		       sprintrc(rc),
		       rc == inject_retval ? " (INJECTED)" : "");

		if (rc == inject_retval)
			return;
	}

	error_msg_and_fail("Issued %lu ioctl syscalls but failed"
			   " to detect an injected return code %ld",
			   num_skip, inject_retval);
}

int
main(int argc, const char *argv[])
{
	skip_if_unavailable("/proc/self/exe");

	TAIL_ALLOC_OBJECT_CONST_PTR(struct pidfd_info, info);

#ifdef INJECT_RETVAL
	if (argc == 1)
		return 0;

	if (argc < 3)
		error_msg_and_fail("Usage: %s NUM_SKIP INJECT_RETVAL", argv[0]);

	skip_ioctls(argv);

	injected_pidfd_get_info_decode_checks(info);
#else
	const int pidfd =
		syscall(__NR_pidfd_open, (kernel_ulong_t) getpid(), 0L);

	if (pidfd < 0)
		perror_msg_and_skip("pidfd_open");

	memset(info, 0, sizeof(*info));
	info->mask = PIDFD_INFO_PID;

	do_ioctl_fd(-1, pidfd_get_info_cmd.val, (uintptr_t) info);
	printf("ioctl(-1, " XLAT_FMT ", %p) = %s\n",
	       XLAT_SEL(pidfd_get_info_cmd.val, pidfd_get_info_cmd.str),
	       info, errstr);

	memset(info, 0, sizeof(*info));
	info->mask = PIDFD_INFO_PID;

	do_ioctl_fd(pidfd, PIDFD_GET_INFO_undersize_cmd.val, (uintptr_t) info);
	printf("ioctl(%d, " XLAT_FMT ", %p) = %s\n",
	       pidfd,
	       XLAT_SEL(PIDFD_GET_INFO_undersize_cmd.val,
		        PIDFD_GET_INFO_undersize_cmd.str),
	       info, errstr);

	memset(info, 0, sizeof(*info));
	info->mask = PIDFD_INFO_PID;

	do_ioctl_fd(pidfd, PIDFD_GET_INFO_oversize_cmd.val, (uintptr_t) info);
	printf("ioctl(%d, " XLAT_FMT ", %p) = %s\n",
	       pidfd,
	       XLAT_SEL(PIDFD_GET_INFO_oversize_cmd.val,
		        PIDFD_GET_INFO_oversize_cmd.str),
	       info, errstr);

	memset(info, 0, sizeof(*info));
	info->mask = PIDFD_INFO_PID;

	const int rc = do_ioctl_fd(pidfd, pidfd_get_info_cmd.val,
				    (uintptr_t) info);

	printf("ioctl(%d, " XLAT_FMT ", ",
	       pidfd,
	       XLAT_SEL(pidfd_get_info_cmd.val, pidfd_get_info_cmd.str));
	if (rc < 0) {
		printf("%p) = %s\n", info, errstr);
	} else {
		printf("{mask=%s", XLAT_KNOWN(0x1, "PIDFD_INFO_PID"));
		if (info->mask != PIDFD_INFO_PID) {
			fputs(" => ", stdout);
			switch (info->mask) {
			case PIDFD_INFO_PID | PIDFD_INFO_CREDS | PIDFD_INFO_CGROUPID:
				fputs(XLAT_KNOWN(0x7,
						 "PIDFD_INFO_PID|"
						 "PIDFD_INFO_CREDS|"
						 "PIDFD_INFO_CGROUPID"),
				      stdout);
				break;
			case PIDFD_INFO_PID | PIDFD_INFO_CREDS:
				fputs(XLAT_KNOWN(0x3,
						 "PIDFD_INFO_PID|"
						 "PIDFD_INFO_CREDS"),
				      stdout);
				break;
			default:
				error_msg_and_fail("unexpected PIDFD_GET_INFO result mask %#jx",
						   (uintmax_t) info->mask);
			}
		}

		if ((info->mask & PIDFD_INFO_CGROUPID))
			printf(", cgroupid=%llu",
			       (unsigned long long) info->cgroupid);

		if ((info->mask & PIDFD_INFO_PID))
			printf(", pid=%d, tgid=%d, ppid=%d",
			       info->pid, info->tgid, info->ppid);

		if ((info->mask & PIDFD_INFO_CREDS))
			printf(", ruid=%u, rgid=%u, euid=%u, egid=%u"
			       ", suid=%u, sgid=%u, fsuid=%u, fsgid=%u",
			       info->ruid, info->rgid, info->euid, info->egid,
			       info->suid, info->sgid, info->fsuid, info->fsgid);

		printf("}) = %s\n", errstr);
	}

	close(pidfd);
#endif /* !INJECT_RETVAL */

	puts("+++ exited with 0 +++");
	return 0;
}

static bool
decode_ifla_br_stp_mode(struct tcb *const tcp,
			const kernel_ulong_t addr,
			const unsigned int len,
