void bli_thrcomm_init_hpx( dim_t n_threads, thrcomm_t* comm )
{
	if ( comm == nullptr ) return;
	comm->barrier = new hpx:barrier<>();
}

void bli_thrcomm_cleanup_hpx( thrcomm_t* comm )
{
	if ( comm == nullptr ) return;
	delete comm->barrier;
}

void bli_thrcomm_init_hpx( dim_t n_threads, thrcomm_t* comm )
{
	if ( comm == nullptr ) return;
	comm->sent_object = nullptr;
	comm->n_threads = n_threads;
	comm->barrier_sense = 0;
	comm->barrier_threads_arrived = 0;
}

void bli_thread_launch_hpx
     (
             dim_t         n_threads,
             thread_func_t func,
       const void*         params
     )
{
	const timpl_t ti = BLIS_HPX;

	// Allocate a global communicator for the root thrinfo_t structures.
	pool_t*    gl_comm_pool = nullptr;
	thrcomm_t* gl_comm      = bli_thrcomm_create( ti, gl_comm_pool, n_threads );

	auto irange = hpx::util::detail::make_counting_shape(n_threads);

	hpx::for_each(hpx::execution::par, hpx::util::begin(irange), hpx::util::end(irange),
	[&gl_comm, &func, &params](const dim_t tid)
	{
		func( gl_comm, tid, params );
	});

	// Free the global communicator, because the root thrinfo_t node
	// never frees its communicator.
	bli_thrcomm_free( gl_comm_pool, gl_comm );
}

int bli_thread_finalize_hpx()
{
    hpx::apply([]() { hpx::finalize(); });
    return hpx::stop();
}

static pj_bool_t dlg_target_refresh_allowed(const pjsip_dialog *dlg,
                                            const pjsip_contact_hdr *contact)
{
    if (pjsip_cfg()->endpt.disable_secure_dlg_check == PJ_FALSE &&
        dlg->secure && !PJSIP_URI_SCHEME_IS_SIPS(contact->uri))
    {
        PJ_LOG(3, (dlg->obj_name, "Ignoring non-SIPS Contact in target "
                                  "refresh for a secure dialog"));
        return PJ_FALSE;
    }
    return PJ_TRUE;
}

static pj_str_t print_target(pjsip_dialog *dlg, char *buf, pj_size_t buf_len)
{
    pj_str_t s;
    pj_ssize_t len;

    len = pjsip_uri_print(PJSIP_URI_IN_CONTACT_HDR, dlg->target, buf,
                          buf_len);
    s.ptr = buf;
    s.slen = (len < 1)? 0 : len;
    return s;
}

static pj_bool_t on_rx_request(pjsip_rx_data *rdata)
{
    if (rdata->msg_info.msg->type == PJSIP_REQUEST_MSG &&
        rdata->msg_info.msg->line.req.method.id == PJSIP_INVITE_METHOD)
    {
        pjsip_dialog *dlg;
        pjsip_tx_data *tdata;
        pj_str_t uri;

        if (!is_user_equal(rdata->msg_info.from, "dlg_target_refresh_test"))
            return PJ_FALSE;

        uri = contact_uri;
        PJ_TEST_SUCCESS(pjsip_dlg_create_uas_and_inc_lock(pjsip_ua_instance(),
                                                          rdata, &uri, &dlg),
                        NULL, { pj_assert(0); return PJ_FALSE; });

        /* Simulate a dialog that was established as a secure (SIPS)
         * dialog, e.g. via "INVITE sips:... transport=tls". We don't spin
         * up a real TLS transport for this test: dlg->secure is the only
         * thing the target refresh code (and this fix) consults, so it is
         * set directly here.
         */
        dlg->secure = PJ_TRUE;
        dlg_tr_test.uas_dlg = dlg;
        dlg_tr_test.target_before = print_target(dlg, dlg_tr_test.target_buf,
                                                 sizeof(dlg_tr_test.target_buf));

        /* Keep the dialog alive for the duration of the test. */
        pjsip_dlg_inc_session(dlg, &mod_dlg_tr_test);

        /* Answer subsequent in-dialog UPDATE requests ourselves, instead
         * of letting them fall through to the dialog's default "500
         * Unhandled by dialog usages" (also lets Case 4 below control the
         * Contact of the 200 response).
         */
        PJ_TEST_SUCCESS(pjsip_dlg_add_usage(dlg, &mod_dlg_usage, NULL),
                        NULL, { pj_assert(0); return PJ_FALSE; });

        PJ_TEST_SUCCESS(pjsip_dlg_create_response(dlg, rdata, 200, NULL,
                                                  &tdata),
                        NULL, { pj_assert(0); return PJ_FALSE; });
        PJ_TEST_SUCCESS(pjsip_dlg_send_response(dlg, pjsip_rdata_get_tsx(rdata),
                                                tdata),
                        NULL, { pj_assert(0); return PJ_FALSE; });

        pjsip_dlg_dec_lock(dlg);
        return PJ_TRUE;
    }

    return PJ_FALSE;
}

static pj_bool_t on_rx_response(pjsip_rx_data *rdata)
{
    if (rdata->msg_info.msg->type == PJSIP_RESPONSE_MSG &&
        pj_stricmp2(&rdata->msg_info.cseq->method.name, "UPDATE") == 0 &&
        is_user_equal(rdata->msg_info.to, "dlg_target_refresh_test"))
    {
        dlg_tr_test.last_update_status = rdata->msg_info.msg->line.status.code;
    }

    return PJ_FALSE;
}

static void dlg_tr_send_response_timer(pj_timer_heap_t *timer_heap,
                                       struct pj_timer_entry *entry)
{
    struct dlg_tr_deferred_response *r =
        (struct dlg_tr_deferred_response*) entry->user_data;
    pjsip_transaction *tsx;

    PJ_UNUSED_ARG(timer_heap);

    tsx = pjsip_tsx_layer_find_tsx(&r->tsx_key, PJ_TRUE);
    if (!tsx) {
        pjsip_tx_data_dec_ref(r->tdata);
        return;
    }

    pjsip_tsx_send_msg(tsx, r->tdata);
    pj_grp_lock_release(tsx->grp_lock);
}

static pj_bool_t usage_on_rx_request(pjsip_rx_data *rdata)
{
    pjsip_dialog *dlg = pjsip_rdata_get_dlg(rdata);
    pjsip_transaction *tsx;
    pjsip_tx_data *tdata;
    pjsip_contact_hdr *contact;
    pj_size_t len;
    char *buf;
    struct dlg_tr_deferred_response *r;
    pj_timer_entry *timer;
    pj_time_val delay;

    /* mod_dlg_usage is registered as a normal endpoint module (so it has
     * a valid module id for pjsip_dlg_add_usage()), but it must only
     * ever act as a usage of dlg_tr_test.uas_dlg specifically -- other
     * pjsip-test cases share the same endpoint and may send UPDATE
     * requests of their own, in-dialog or not.
     */
    if (!dlg || dlg != dlg_tr_test.uas_dlg)
        return PJ_FALSE;

    if (pj_stricmp2(&rdata->msg_info.msg->line.req.method.name,
                    "UPDATE") != 0)
    {
        return PJ_FALSE;
    }

    tsx = pjsip_rdata_get_tsx(rdata);
    if (!tsx)
        return PJ_FALSE;

    if (pjsip_dlg_create_response(dlg, rdata, 200, NULL, &tdata) != PJ_SUCCESS)
        return PJ_FALSE;

    /* pjsip_dlg_create_response() doesn't add a Contact header on its
     * own (unlike pjsip_dlg_modify_response()); add one here so the
     * response-path target-refresh gate has a Contact to evaluate, and
     * optionally override its URI for Case 4.
     */
    contact = (pjsip_contact_hdr*)
              pjsip_hdr_clone(tdata->pool, dlg->local.contact);
    if (dlg_tr_test.uas_response_contact) {
        len = pj_ansi_strlen(dlg_tr_test.uas_response_contact);
        buf = (char*) pj_pool_alloc(tdata->pool, len+1);
        pj_memcpy(buf, dlg_tr_test.uas_response_contact, len+1);
        contact->uri = pjsip_parse_uri(tdata->pool, buf, len, 0);
    }
    pjsip_msg_add_hdr(tdata->msg, (pjsip_hdr*)contact);

    r = PJ_POOL_ALLOC_T(tdata->pool, struct dlg_tr_deferred_response);
    pj_strdup(tdata->pool, &r->tsx_key, &tsx->transaction_key);
    r->tdata = tdata;

    timer = PJ_POOL_ZALLOC_T(tdata->pool, pj_timer_entry);
    timer->user_data = r;
    timer->cb = &dlg_tr_send_response_timer;

    pj_bzero(&delay, sizeof(delay));
    if (pjsip_endpt_schedule_timer(dlg->endpt, timer, &delay) != PJ_SUCCESS) {
        pjsip_tx_data_dec_ref(tdata);
        return PJ_FALSE;
    }

    return PJ_TRUE;
}

static pj_status_t send_update_with_contact(pjsip_dialog *uac_dlg,
                                            const char *contact_uri_str)
{
    pjsip_method method;
    pj_str_t update_str = { "UPDATE", 6 };
    pjsip_tx_data *tdata;
    pjsip_contact_hdr *contact;
    char *uri_buf;
    pj_size_t uri_len;
    pj_status_t status;

    pjsip_method_init_np(&method, &update_str);

    status = pjsip_dlg_create_request(uac_dlg, &method, -1, &tdata);
    if (status != PJ_SUCCESS)
        return status;

    contact = (pjsip_contact_hdr*)
              pjsip_msg_find_hdr(tdata->msg, PJSIP_H_CONTACT, NULL);
    if (!contact) {
        pjsip_tx_data_dec_ref(tdata);
        return PJSIP_EMISSINGHDR;
    }

    uri_len = pj_ansi_strlen(contact_uri_str);
    uri_buf = (char*) pj_pool_alloc(tdata->pool, uri_len+1);
    pj_memcpy(uri_buf, contact_uri_str, uri_len+1);

    contact->uri = pjsip_parse_uri(tdata->pool, uri_buf, uri_len, 0);
    if (!contact->uri) {
        pjsip_tx_data_dec_ref(tdata);
        return PJSIP_EINVALIDURI;
    }

    return pjsip_dlg_send_request(uac_dlg, tdata, -1, NULL);
}

static pj_status_t send_forged_ack_with_contact(pjsip_dialog *uac_dlg,
                                                const char *contact_uri_str)
{
    pjsip_tx_data *tdata;
    pjsip_cseq_hdr *cseq;
    pjsip_contact_hdr *contact;
    char *uri_buf;
    pj_size_t uri_len;
    pj_status_t status;

    status = pjsip_dlg_create_request(uac_dlg, pjsip_get_ack_method(),
                                      99999, &tdata);
    if (status != PJ_SUCCESS)
        return status;

    cseq = (pjsip_cseq_hdr*)
           pjsip_msg_find_hdr(tdata->msg, PJSIP_H_CSEQ, NULL);
    if (!cseq) {
        pjsip_tx_data_dec_ref(tdata);
        return PJSIP_EMISSINGHDR;
    }
    pjsip_method_set(&cseq->method, PJSIP_INVITE_METHOD);

    uri_len = pj_ansi_strlen(contact_uri_str);
    uri_buf = (char*) pj_pool_alloc(tdata->pool, uri_len+1);
    pj_memcpy(uri_buf, contact_uri_str, uri_len+1);

    contact = pjsip_contact_hdr_create(tdata->pool);
    contact->uri = pjsip_parse_uri(tdata->pool, uri_buf, uri_len, 0);
    if (!contact->uri) {
        pjsip_tx_data_dec_ref(tdata);
        return PJSIP_EINVALIDURI;
    }
    pjsip_msg_add_hdr(tdata->msg, (pjsip_hdr*)contact);

    return pjsip_dlg_send_request(uac_dlg, tdata, -1, NULL);
}

static void endpt_respond_msg_too_large( pjsip_endpoint *endpt,
                                         pjsip_rx_data *rdata )
{
    const pj_str_t end_hdr = { "\n\r\n", 3 };
    pj_str_t received;
    pj_size_t hdr_len;
    char *pos;
    char *hdr_buf;
    pjsip_msg *msg;
    pjsip_warning_hdr *warn;
    pjsip_hdr hdr_list;
    char warn_text[80];
    pj_str_t warn_str;
    pj_status_t status;

    received.ptr = rdata->msg_info.msg_buf;
    received.slen = rdata->msg_info.len;
    if (received.ptr == NULL || received.slen <= 0)
        return;

    /* Locate the empty line that ends the header block, with the sentinel
     * pjsip_find_msg() uses, so the two cannot disagree on where the headers
     * end. Keep the line: the parser needs it to see that they are complete.
     */
    pos = pj_strstr(&received, &end_hdr);
    if (pos == NULL)
        return;
    hdr_len = (pj_size_t)(pos + 3 - received.ptr);

    /* Parse from a copy: the scanner writes into the buffer it is given, and
     * the transport still hands the original on to its dropped-data callback.
     */
    hdr_buf = (char*) pj_pool_alloc(rdata->tp_info.pool, hdr_len + 1);
    pj_memcpy(hdr_buf, received.ptr, hdr_len);
    hdr_buf[hdr_len] = '\0';

    pj_bzero(&rdata->msg_info, sizeof(rdata->msg_info));
    pj_list_init(&rdata->msg_info.parse_err);
    rdata->msg_info.msg_buf = hdr_buf;
    rdata->msg_info.len = (int)hdr_len;
    pj_bzero(&rdata->endpt_info, sizeof(rdata->endpt_info));

    msg = pjsip_parse_rdata(hdr_buf, hdr_len, rdata);
    if (msg == NULL || !pj_list_empty(&rdata->msg_info.parse_err) ||
        msg->type != PJSIP_REQUEST_MSG ||
        msg->line.req.method.id == PJSIP_ACK_METHOD ||
        rdata->msg_info.via == NULL || rdata->msg_info.from == NULL ||
        rdata->msg_info.to == NULL || rdata->msg_info.cseq == NULL ||
        rdata->msg_info.cid == NULL || rdata->msg_info.cid->id.slen == 0)
    {
        return;
    }

    /* The transport layer adds these for every request it accepts, and
     * pjsip_get_response_addr() relies on them. We bypassed it, so do it here.
     */
    pj_strdup2(rdata->tp_info.pool, &rdata->msg_info.via->recvd_param,
               rdata->pkt_info.src_name);
    if (rdata->msg_info.via->rport_param == 0)
        rdata->msg_info.via->rport_param = rdata->pkt_info.src_port;

    /* Name the actual limit, so the peer learns what to stay under. */
    pj_ansi_snprintf(warn_text, sizeof(warn_text),
                     "Message exceeds the %d byte receive buffer",
                     PJSIP_MAX_PKT_LEN);
    warn_str = pj_str(warn_text);

    pj_list_init(&hdr_list);
    warn = pjsip_warning_hdr_create(rdata->tp_info.pool, 399,
                                    pjsip_endpt_name(endpt), &warn_str);
    if (warn)
        pj_list_push_back(&hdr_list, (pjsip_hdr*)warn);

    status = pjsip_endpt_respond_stateless(endpt, rdata,
                                           PJSIP_SC_MESSAGE_TOO_LARGE, NULL,
                                           &hdr_list, NULL);
    if (status != PJ_SUCCESS) {
        char errmsg[PJ_ERR_MSG_SIZE];

        pj_strerror(status, errmsg, sizeof(errmsg));
        PJ_LOG(3, (THIS_FILE, "Unable to respond %d to the oversized request "
                              "from %s:%d: %s",
                   PJSIP_SC_MESSAGE_TOO_LARGE, rdata->pkt_info.src_name,
                   rdata->pkt_info.src_port, errmsg));
    }
}

int transport_rx_overflow_test(void)
{
    int rc;

    rc = rx_overflow_test("\r\n", "z9hG4bK-rxovf-crlf");
    if (rc != 0)
        return rc;

    return rx_overflow_test("\n", "z9hG4bK-rxovf-lf");
}

static pj_uint16_t get_query_id(pj_dns_resolver *resolver)
{
    unsigned n;

    for (n = 0; n < 1000; ++n) {
        pj_uint8_t digest[20];
        pj_uint32_t ctr = resolver->id_counter++;
        pj_uint16_t id;

        pj_hmac_sha1((const pj_uint8_t*)&ctr, sizeof(ctr),
                     resolver->id_key, sizeof(resolver->id_key), digest);
        id = (pj_uint16_t)((digest[0] << 8) | digest[1]);
        if (id != 0 &&
            pj_hash_get(resolver->hquerybyid, &id, sizeof(id), NULL) == NULL)
        {
            return id;
        }
    }

    return 0;
}

static pj_bool_t is_response_from_ns(pj_dns_resolver *resolver,
                                     const pj_sockaddr *src_addr)
{
    unsigned i;

    for (i = 0; i < resolver->ns_count; ++i) {
        if (pj_sockaddr_cmp(&resolver->ns[i].addr, src_addr) == 0)
            return PJ_TRUE;
    }

    return PJ_FALSE;
}

static void log_suspicious_drop(pj_dns_resolver *resolver, const char *reason,
                                const pj_sockaddr *src_addr)
{
    char addr[PJ_INET6_ADDRSTRLEN];
    pj_time_val now, diff;

    ++resolver->susp_count;

    pj_gettimeofday(&now);
    diff = now;
    PJ_TIME_VAL_SUB(diff, resolver->susp_last_log);

    if (resolver->susp_last_log.sec == 0 || diff.sec >= 1) {
        PJ_LOG(4,(resolver->name.ptr,
                  "Discarded %u suspicious DNS response(s); latest from "
                  "%s:%d (%s)",
                  resolver->susp_count,
                  pj_sockaddr_print(src_addr, addr, sizeof(addr), 2),
                  pj_sockaddr_get_port(src_addr), reason));
        resolver->susp_count = 0;
        resolver->susp_last_log = now;
    }
}

static void minimize_msg_size(msg_size_saved *sv)
{
    pjmedia_endpt *endpt = pjsua_get_pjmedia_endpt();
    pj_bool_t no = PJ_FALSE;
    const pj_str_t all = pj_str("*");
    const pj_str_t pcmu = pj_str("PCMU/8000");

    /* get the current settings... */
    sv->disable_tcp_switch  = pjsip_cfg()->endpt.disable_tcp_switch;
    sv->compact_form        = pjsip_cfg()->endpt.use_compact_form;
    sv->rtpmap_static       = pjmedia_add_rtpmap_for_static_pt;
    sv->bandw_tias          = pjmedia_add_bandwidth_tias_in_sdp;
    pjmedia_endpt_get_flag(endpt, PJMEDIA_ENDPT_HAS_TELEPHONE_EVENT_FLAG,
                           &sv->tel_event);
    sv->codec_count = PJ_ARRAY_SIZE(sv->codecs);
    if (pjsua_enum_codecs(sv->codecs, &sv->codec_count) != PJ_SUCCESS)
        sv->codec_count = 0;

    /* apply settings */
    pjsip_cfg()->endpt.disable_tcp_switch   = PJ_TRUE;
    pjsip_cfg()->endpt.use_compact_form     = PJ_TRUE;
    pjmedia_add_rtpmap_for_static_pt        = PJ_FALSE;
    pjmedia_add_bandwidth_tias_in_sdp       = PJ_FALSE;
    pjmedia_endpt_set_flag(endpt, PJMEDIA_ENDPT_HAS_TELEPHONE_EVENT_FLAG, &no);
    /* codec wise, we'll disable everything and allow only PCMU */
    pjsua_codec_set_priority(&all,  PJMEDIA_CODEC_PRIO_DISABLED);
    pjsua_codec_set_priority(&pcmu, PJMEDIA_CODEC_PRIO_HIGHEST);
}

static void restore_msg_size(const msg_size_saved *sv)
{
    pjmedia_endpt *endpt = pjsua_get_pjmedia_endpt();
    unsigned i;
    pjsip_cfg()->endpt.disable_tcp_switch   = sv->disable_tcp_switch;
    pjsip_cfg()->endpt.use_compact_form     = sv->compact_form;
    pjmedia_add_rtpmap_for_static_pt        = sv->rtpmap_static;
    pjmedia_add_bandwidth_tias_in_sdp       = sv->bandw_tias;
    pjmedia_endpt_set_flag(endpt, PJMEDIA_ENDPT_HAS_TELEPHONE_EVENT_FLAG,
                           &sv->tel_event);
    for (i = 0; i < sv->codec_count; ++i) {
        pjsua_codec_set_priority(&sv->codecs[i].codec_id,
                                 sv->codecs[i].priority);
    }
}

static void on_incoming_call(pjsua_acc_id acc_id, pjsua_call_id call_id,
                             pjsip_rx_data *rdata)
{
    pjsua_call_setting opt;
    pj_status_t status;

    PJ_UNUSED_ARG(acc_id);
    PJ_UNUSED_ARG(rdata);

    g_ctx.incoming_call_id = call_id;

    /* Probe: over-limit audio count must be rejected. answer2() leaves
     * call->opt_inited FALSE on failure, so the valid answer below still
     * applies.
     */
    pjsua_call_setting_default(&opt);
    opt.aud_cnt = PJSUA_MAX_CALL_MEDIA + 1;
    opt.vid_cnt = 0;
    opt.txt_cnt = 0;
    g_ctx.answer2_overlimit_status =
        pjsua_call_answer2(call_id, &opt, 200, NULL, NULL);

    /* Establish the call with a valid single-audio setting. */
    pjsua_call_setting_default(&opt);
    opt.aud_cnt = 1;
    opt.vid_cnt = 0;
    opt.txt_cnt = 0;
    status = pjsua_call_answer2(call_id, &opt, 200, NULL, NULL);
    if (status != PJ_SUCCESS)
        PJ_PERROR(1, (THIS_FILE, status, "  valid answer2 failed"));

    g_ctx.incoming_seen = PJ_TRUE;
}

static void on_call_sdp_created(pjsua_call_id call_id,
                                pjmedia_sdp_session *sdp,
                                pj_pool_t *pool,
                                const pjmedia_sdp_session *rem_sdp)
{
    pjmedia_sdp_media *m;

    PJ_UNUSED_ARG(call_id);

    if (!g_ctx.inject_app_mline || rem_sdp != NULL)
        return;
    if (sdp->media_count >= PJMEDIA_MAX_SDP_MEDIA)
        return;

    m = PJ_POOL_ZALLOC_T(pool, pjmedia_sdp_media);
    pj_strdup2(pool, &m->desc.media, "application");
    m->desc.port = 4000;
    pj_strdup2(pool, &m->desc.transport, "RTP/AVP");
    m->desc.fmt_count = 1;
    pj_strdup2(pool, &m->desc.fmt[0], "0");

    /* A connection line is required by SDP validation. Reuse the one from an
     * existing media (or the session), whichever is present.
     */
    if (sdp->media_count > 0 && sdp->media[0]->conn)
        m->conn = pjmedia_sdp_conn_clone(pool, sdp->media[0]->conn);
    else if (sdp->conn)
        m->conn = pjmedia_sdp_conn_clone(pool, sdp->conn);

    sdp->media[sdp->media_count++] = m;
}

static pj_bool_t wait_until(pj_bool_t (*predicate)(pjsua_call_id),
                            pjsua_call_id call_id, unsigned timeout_ms)
{
    pj_time_val t0, now;

    pj_gettimeofday(&t0);
    for (;;) {
        if (predicate && predicate(call_id))
            return PJ_TRUE;
        pj_gettimeofday(&now);
        PJ_TIME_VAL_SUB(now, t0);
        if ((unsigned)PJ_TIME_VAL_MSEC(now) >= timeout_ms)
            break;
        pjsua_handle_events(50);
    }
    return predicate ? predicate(call_id) : PJ_FALSE;
}

static pj_bool_t call_is_confirmed(pjsua_call_id call_id)
{
    pjsua_call_info ci;

    if (pjsua_call_get_info(call_id, &ci) != PJ_SUCCESS)
        return PJ_FALSE;
    return ci.state == PJSIP_INV_STATE_CONFIRMED;
}

static void drain_all_calls(void)
{
    unsigned i;

    for (i = 0; i < 60 && pjsua_call_get_count() > 0; ++i) {
        pjsua_call_hangup_all();
        pjsua_handle_events(50);
    }

    /* Closed media sockets keep their ioqueue slot for
     * PJ_IOQUEUE_KEY_FREE_DELAY msec (safe unregistration), and a max-media
     * loopback call uses 2 legs x PJSUA_MAX_CALL_MEDIA x 2 (RTP+RTCP) sockets
     * which equal the media ioqueue's whole capacity (PJ_IOQUEUE_MAX_HANDLES).
     * Wait out the delay so the slots are
     * recycled before the next sub-test creates new media sockets.
     */
    wait_until(NULL, PJSUA_INVALID_ID, PJ_IOQUEUE_KEY_FREE_DELAY + 200);
}

static int test_make_call_bounds(void)
{
    pjsua_call_setting opt;
    pj_str_t uri = pj_str(g_ctx.self_uri);
    pj_status_t status;
    pjsua_call_id cid = PJSUA_INVALID_ID;

    PJ_LOG(3, (THIS_FILE, "  outgoing make_call bounds"));

    /* Per-field over limit -> PJ_ETOOMANY. */
    pjsua_call_setting_default(&opt);
    opt.aud_cnt = PJSUA_MAX_CALL_MEDIA + 1;
    opt.vid_cnt = 0;
    opt.txt_cnt = 0;
    status = pjsua_call_make_call(g_ctx.acc_id, &uri, &opt, NULL, NULL, &cid);
    if (status != PJ_ETOOMANY) {
        PJ_LOG(1, (THIS_FILE, "    expected PJ_ETOOMANY (aud over limit), "
                   "got %d", status));
        return -1100;
    }

    /* Combined sum over limit (aud == max, +1 text) -> PJ_ETOOMANY. */
    pjsua_call_setting_default(&opt);
    opt.aud_cnt = PJSUA_MAX_CALL_MEDIA;
    opt.vid_cnt = 0;
    opt.txt_cnt = 1;
    status = pjsua_call_make_call(g_ctx.acc_id, &uri, &opt, NULL, NULL, &cid);
    if (status != PJ_ETOOMANY) {
        PJ_LOG(1, (THIS_FILE, "    expected PJ_ETOOMANY (sum over limit), "
                   "got %d", status));
        return -1101;
    }

    /* Combined sum exactly at the limit is accepted (not rejected by the
     * bounds check). Tear the resulting call down immediately.
     */
    pjsua_call_setting_default(&opt);
    opt.aud_cnt = PJSUA_MAX_CALL_MEDIA;
    opt.vid_cnt = 0;
    opt.txt_cnt = 0;
    status = pjsua_call_make_call(g_ctx.acc_id, &uri, &opt, NULL, NULL, &cid);
    if (status != PJ_SUCCESS) {
        PJ_LOG(1, (THIS_FILE, "    boundary count (== max) failed (%d)",
                   status));
        return -1102;
    }
    if (status == PJ_SUCCESS && cid != PJSUA_INVALID_ID)
        pjsua_call_hangup(cid, 0, NULL, NULL);

    /* Tear down the boundary call and its (possibly late) answered peer. */
    drain_all_calls();

    return 0;
}

static int test_reinvite_reinit_bounds(void)
{
    pjsua_call_setting opt;
    pj_str_t uri = pj_str(g_ctx.self_uri);
    pj_status_t status;
    pjsua_call_id cid = PJSUA_INVALID_ID;
    pjsua_call_info ci;

    PJ_LOG(3, (THIS_FILE, "  answer2 bounds + reinit/reoffer overflow guard"));

    g_ctx.answer2_overlimit_status = PJ_SUCCESS;
    g_ctx.incoming_seen = PJ_FALSE;

    /* Place a single-audio call to ourselves; on_incoming_call answers it. */
    pjsua_call_setting_default(&opt);
    opt.aud_cnt = 1;
    opt.vid_cnt = 0;
    opt.txt_cnt = 0;
    status = pjsua_call_make_call(g_ctx.acc_id, &uri, &opt, NULL, NULL, &cid);
    if (status != PJ_SUCCESS) {
        PJ_LOG(1, (THIS_FILE, "    make_call failed (%d)", status));
        return -1200;
    }

    if (!wait_until(&call_is_confirmed, cid, 8000)) {
        PJ_LOG(1, (THIS_FILE, "    call did not reach CONFIRMED in time"));
        pjsua_call_hangup_all();
        return -1201;
    }

    /* answer2() must have rejected the over-limit probe. */
    if (!g_ctx.incoming_seen) {
        PJ_LOG(1, (THIS_FILE, "    on_incoming_call never ran"));
        pjsua_call_hangup_all();
        return -1202;
    }
    if (g_ctx.answer2_overlimit_status != PJ_ETOOMANY) {
        PJ_LOG(1, (THIS_FILE, "    answer2 over-limit expected PJ_ETOOMANY, "
                   "got %d", g_ctx.answer2_overlimit_status));
        pjsua_call_hangup_all();
        return -1203;
    }

    /* Re-INVITE: disable audio and request PJSUA_MAX_CALL_MEDIA text m-lines.
     * apply_call_setting() accepts it (sum == max), but the existing audio
     * m-line is retained (media count never decreases) so the effective
     * count would be max+1. The reinit guard must reject with PJ_ETOOMANY.
     */
    pjsua_call_setting_default(&opt);
    opt.aud_cnt = 0;
    opt.vid_cnt = 0;
    opt.txt_cnt = PJSUA_MAX_CALL_MEDIA;
    status = pjsua_call_reinvite2(cid, &opt, NULL);
    if (status != PJ_ETOOMANY) {
        PJ_LOG(1, (THIS_FILE, "    reinvite reinit-overflow expected "
                   "PJ_ETOOMANY, got %d", status));
        pjsua_call_hangup_all();
        return -1204;
    }

    /* The call must survive the rejected re-INVITE. */
    if (pjsua_call_get_info(cid, &ci) != PJ_SUCCESS ||
        ci.state != PJSIP_INV_STATE_CONFIRMED)
    {
        PJ_LOG(1, (THIS_FILE, "    call not alive after rejected reinvite"));
        pjsua_call_hangup_all();
        return -1205;
    }

    /* Clean up. */
    drain_all_calls();

    return 0;
}

static int test_reinit_bounds_untyped_mline(void)
{
    pjsua_call_setting opt;
    pj_str_t uri = pj_str(g_ctx.self_uri);
    pj_status_t status;
    pjsua_call_id cid = PJSUA_INVALID_ID;
    pjsua_call_info ci;

    PJ_LOG(3, (THIS_FILE, "  reinit guard with untyped (application) m-line"));

    g_ctx.inject_app_mline = PJ_TRUE;

    /* Offer 1 audio + 1 application m-line to ourselves. */
    pjsua_call_setting_default(&opt);
    opt.aud_cnt = 1;
    opt.vid_cnt = 0;
    opt.txt_cnt = 0;
    status = pjsua_call_make_call(g_ctx.acc_id, &uri, &opt, NULL, NULL, &cid);
    if (status != PJ_SUCCESS) {
        PJ_LOG(1, (THIS_FILE, "    make_call failed (%d)", status));
        g_ctx.inject_app_mline = PJ_FALSE;
        drain_all_calls();
        return -1300;
    }

    if (!wait_until(&call_is_confirmed, cid, 8000)) {
        PJ_LOG(1, (THIS_FILE, "    call did not reach CONFIRMED in time"));
        g_ctx.inject_app_mline = PJ_FALSE;
        drain_all_calls();
        return -1301;
    }

    /* Stop injecting; the reinvite below must not add further m-lines. */
    g_ctx.inject_app_mline = PJ_FALSE;

    /* Sanity/diagnostic: the call should now carry the extra m-line. The
     * assertion below is self-validating regardless (PJ_ETOOMANY is only
     * returned when the retained untyped slot pushes the count over max).
     */
    if (pjsua_call_get_info(cid, &ci) == PJ_SUCCESS) {
        PJ_LOG(3, (THIS_FILE, "    established with media_cnt=%u",
                   ci.media_cnt));
    }

    pjsua_call_setting_default(&opt);
    opt.aud_cnt = 1;
    opt.vid_cnt = 0;
    opt.txt_cnt = PJSUA_MAX_CALL_MEDIA - 1;
    status = pjsua_call_reinvite2(cid, &opt, NULL);
    if (status != PJ_ETOOMANY) {
        PJ_LOG(1, (THIS_FILE, "    reinit overflow with untyped m-line "
                   "expected PJ_ETOOMANY, got %d", status));
        drain_all_calls();
        return -1302;
    }

    if (pjsua_call_get_info(cid, &ci) != PJ_SUCCESS ||
        ci.state != PJSIP_INV_STATE_CONFIRMED)
    {
        PJ_LOG(1, (THIS_FILE, "    call not alive after rejected reinvite"));
        drain_all_calls();
        return -1303;
    }

    drain_all_calls();
    return 0;
}

int pjsua_call_test(void)
{
    extern pjsip_endpoint *endpt;       /* test framework endpoint */
    extern pj_caching_pool  caching_pool;
    msg_size_saved          lib_settings;
    pjsua_config            ua_cfg;
    pjsua_logging_config    log_cfg;
    pjsua_media_config      media_cfg;
    pjsua_transport_config  tp_cfg;
    pjsua_transport_id      tp_id;
    pj_uint16_t             port;
    pj_status_t             status;
    int rc = 0;

    PJ_LOG(3, (THIS_FILE, "pjsua call media-count bounds test"));
    pj_bzero(&lib_settings, sizeof(lib_settings));

    /* pjsua creates its own endpoint and registers the (singleton) tsx layer
     * module; destroy the framework endpoint first to avoid the duplicate
     * registration assert, and recreate it afterwards. Same pattern as
     * pjsua_auth_test.c.
     */
    pjsip_endpt_destroy(endpt);
    endpt = NULL;

    status = pjsua_create();
    if (status != PJ_SUCCESS) {
        PJ_LOG(1, (THIS_FILE, "  pjsua_create failed (%d)", status));
        rc = -2001;
        goto on_restore;
    }

    pjsua_config_default(&ua_cfg);
    ua_cfg.cb.on_incoming_call = &on_incoming_call;
    ua_cfg.cb.on_call_sdp_created = &on_call_sdp_created;
    /* Single-threaded: event pumping happens on this thread, so callbacks
     * run here too and no locking races arise in the test itself. */
    ua_cfg.thread_cnt = 0;

    /* Make sure PRACK and session timer are off and don't bother with SRTP */
    ua_cfg.require_100rel   = PJSUA_100REL_NOT_USED;
    ua_cfg.use_timer        = PJSUA_SIP_TIMER_INACTIVE;
    ua_cfg.use_srtp         = PJMEDIA_SRTP_DISABLED;

    pjsua_logging_config_default(&log_cfg);
    log_cfg.level         = 3;
    log_cfg.console_level = 3;

    pjsua_media_config_default(&media_cfg);
    media_cfg.no_vad        = PJ_TRUE;
    media_cfg.enable_ice    = PJ_FALSE;

    status = pjsua_init(&ua_cfg, &log_cfg, &media_cfg);
    if (status != PJ_SUCCESS) {
        PJ_LOG(1, (THIS_FILE, "  pjsua_init failed (%d)", status));
        pjsua_destroy();
        rc = -2002;
        goto on_restore;
    }

    pjsua_transport_config_default(&tp_cfg);
    tp_cfg.port = 0;    /* ephemeral */
    status = pjsua_transport_create(PJSIP_TRANSPORT_UDP, &tp_cfg, &tp_id);
    if (status != PJ_SUCCESS) {
        PJ_LOG(1, (THIS_FILE, "  transport_create failed (%d)", status));
        pjsua_destroy();
        rc = -2003;
        goto on_restore;
    }

    status = pjsua_start();
    if (status != PJ_SUCCESS) {
        PJ_LOG(1, (THIS_FILE, "  pjsua_start failed (%d)", status));
        pjsua_destroy();
        rc = -2004;
        goto on_restore;
    }

    /* Use a null (dummy) sound device so calls with audio can be set up on
     * hosts/CI without real audio hardware.
     */
    status = pjsua_set_null_snd_dev();
    if (status != PJ_SUCCESS) {
        PJ_LOG(1, (THIS_FILE, "  set_null_snd_dev failed (%d)", status));
        pjsua_destroy();
        rc = -2005;
        goto on_restore;
    }

    /* Local account bound to the UDP transport, and a self URI to dial. */
    status = pjsua_acc_add_local(tp_id, PJ_TRUE, &g_ctx.acc_id);
    if (status != PJ_SUCCESS) {
        PJ_LOG(1, (THIS_FILE, "  acc_add_local failed (%d)", status));
        pjsua_destroy();
        rc = -2006;
        goto on_restore;
    }

    {
        pjsua_transport_info ti;
        status = pjsua_transport_get_info(tp_id, &ti);
        if (status != PJ_SUCCESS) {
            PJ_LOG(1, (THIS_FILE, "  transport_get_info failed (%d)", status));
            pjsua_destroy();
            rc = -2007;
            goto on_restore;
        }
        port = pj_sockaddr_get_port(&ti.local_addr);
    }
    pj_ansi_snprintf(g_ctx.self_uri, sizeof(g_ctx.self_uri),
                     "sip:%s@127.0.0.1:%u", TEST_USER, (unsigned)port);

    /* Adjust library settings to bring down the payload size before
     * running the sub-tests.
     */
    minimize_msg_size(&lib_settings);

    /* ---- Run sub-tests ---- */
    rc = test_make_call_bounds();
    if (rc != 0) goto on_return;

    rc = test_reinvite_reinit_bounds();
    if (rc != 0) goto on_return;

    rc = test_reinit_bounds_untyped_mline();
    if (rc != 0) goto on_return;

on_return:
    drain_all_calls();
    restore_msg_size(&lib_settings);
    pjsua_destroy2(PJSUA_DESTROY_NO_RX_MSG);

on_restore:
    /* Recreate the framework endpoint + tsx layer for subsequent tests. */
    status = pjsip_endpt_create(&caching_pool.factory, "endpt", &endpt);
    if (status != PJ_SUCCESS) {
        PJ_PERROR(1, (THIS_FILE, status, "Error recreating endpoint"));
        return -1000;
    }
    status = pjsip_tsx_layer_init_module(endpt);
    if (status != PJ_SUCCESS) {
        PJ_PERROR(1, (THIS_FILE, status, "Error re-initializing tsx layer"));
    }

    return rc;
}

static pj_uint64_t siphash24(pj_uint64_t k0, pj_uint64_t k1,
                             const void *data, unsigned len, pj_bool_t lower)
{
    pj_uint64_t v0, v1, v2, v3, m, b;
    const pj_uint8_t *in = (const pj_uint8_t*)data;
    unsigned i, left = len & 7;
    const pj_uint8_t *end = in + (len - left);

    v0 = SIP_U64(0x736f6d65, 0x70736575) ^ k0;
    v1 = SIP_U64(0x646f7261, 0x6e646f6d) ^ k1;
    v2 = SIP_U64(0x6c796765, 0x6e657261) ^ k0;
    v3 = SIP_U64(0x74656462, 0x79746573) ^ k1;

    for (; in != end; in += 8) {
        m = 0;
        for (i = 0; i < 8; ++i) {
            pj_uint8_t c = lower? (pj_uint8_t)pj_tolower(in[i]) : in[i];
            m |= (pj_uint64_t)c << (8*i);
        }
        v3 ^= m; SIP_ROUND; SIP_ROUND; v0 ^= m;
    }

    b = (pj_uint64_t)len << 56;
    for (i = 0; i < left; ++i) {
        pj_uint8_t c = lower? (pj_uint8_t)pj_tolower(in[i]) : in[i];
        b |= (pj_uint64_t)c << (8*i);
    }
    v3 ^= b; SIP_ROUND; SIP_ROUND; v0 ^= b;

    v2 ^= 0xff;
    SIP_ROUND; SIP_ROUND; SIP_ROUND; SIP_ROUND;

    return v0 ^ v1 ^ v2 ^ v3;
}

PJ_DEF(pj_uint64_t) pj_hash_test_siphash24(pj_uint64_t k0, pj_uint64_t k1,
                                           const void *data, unsigned len)
{
    return siphash24(k0, k1, data, len, PJ_FALSE);
}

static void mix_entropy(pj_uint8_t k[16], unsigned *idx,
                        const void *data, unsigned len)
{
    const pj_uint8_t *p = (const pj_uint8_t*)data;
    unsigned i;
    for (i = 0; i < len; ++i) {
        unsigned j = (*idx) & 15;
        k[j] = (pj_uint8_t)(k[j] * 33 + p[i]);
        ++(*idx);
    }
}

void pj_hash_init_key(void)
{
    pj_uint8_t k[16];
    char guidbuf[PJ_GUID_MAX_LENGTH];
    pj_str_t guid;
    pj_timestamp ts;
    pj_uint32_t u32;
    void *ptrs[2];
    unsigned n, idx = 0;

    if (sip_key_ready)
        return;

    /* Combine whatever entropy is portably available without an OS CSPRNG:
     * fresh GUID(s) (real OS entropy on proper UUID backends), a high-
     * resolution timestamp, the process id, address-space layout (ASLR)
     * via a couple of pointer values, and pj_rand(). No single source is
     * strong on its own, but together they make the per-process key hard
     * to predict remotely even on the weak guid_simple GUID backend; the
     * strongest entropy still comes from an OS UUID backend.
     */
    pj_bzero(k, sizeof(k));

    for (n = 0; n < 2; ++n) {
        guid.ptr = guidbuf;
        guid.slen = 0;
        if (pj_generate_unique_string(&guid) != NULL)
            mix_entropy(k, &idx, guidbuf, (unsigned)guid.slen);
    }
    if (pj_get_timestamp(&ts) == PJ_SUCCESS)
        mix_entropy(k, &idx, &ts, sizeof(ts));
    u32 = pj_getpid();
    mix_entropy(k, &idx, &u32, sizeof(u32));
    ptrs[0] = (void*)k;         /* stack address (ASLR) */
    ptrs[1] = (void*)&sip_k0;   /* data-segment address (ASLR) */
    mix_entropy(k, &idx, ptrs, sizeof(ptrs));
    for (n = 0; n < 4; ++n) {
        u32 = (pj_uint32_t)pj_rand();
        mix_entropy(k, &idx, &u32, sizeof(u32));
    }

    sip_k0 = SIP_U64(((pj_uint32_t)k[0]<<24)|(k[1]<<16)|(k[2]<<8)|k[3],
                     ((pj_uint32_t)k[4]<<24)|(k[5]<<16)|(k[6]<<8)|k[7]);
    sip_k1 = SIP_U64(((pj_uint32_t)k[8]<<24)|(k[9]<<16)|(k[10]<<8)|k[11],
                     ((pj_uint32_t)k[12]<<24)|(k[13]<<16)|(k[14]<<8)|k[15]);
    sip_key_ready = PJ_TRUE;
}

static pj_uint32_t calc_table_hash(const void *key, unsigned len,
                                   pj_bool_t lower)
{
    pj_uint64_t b = siphash24(sip_k0, sip_k1, key, len, lower);
    return (pj_uint32_t)b ^ (pj_uint32_t)(b >> 32);
}

static int siphash_vector_test(void)
{
    /* Reference vectors: key = bytes 00..0f (little endian), input =
     * bytes 00..len-1, for len = 0..32.
     */
    static const pj_uint64_t expected[] = {
        PJ_UINT64(0x726fdb47dd0e0e31), PJ_UINT64(0x74f839c593dc67fd),
        PJ_UINT64(0x0d6c8009d9a94f5a), PJ_UINT64(0x85676696d7fb7e2d),
        PJ_UINT64(0xcf2794e0277187b7), PJ_UINT64(0x18765564cd99a68d),
        PJ_UINT64(0xcbc9466e58fee3ce), PJ_UINT64(0xab0200f58b01d137),
        PJ_UINT64(0x93f5f5799a932462), PJ_UINT64(0x9e0082df0ba9e4b0),
        PJ_UINT64(0x7a5dbbc594ddb9f3), PJ_UINT64(0xf4b32f46226bada7),
        PJ_UINT64(0x751e8fbc860ee5fb), PJ_UINT64(0x14ea5627c0843d90),
        PJ_UINT64(0xf723ca908e7af2ee), PJ_UINT64(0xa129ca6149be45e5),
        PJ_UINT64(0x3f2acc7f57c29bdb), PJ_UINT64(0x699ae9f52cbe4794),
        PJ_UINT64(0x4bc1b3f0968dd39c), PJ_UINT64(0xbb6dc91da77961bd),
        PJ_UINT64(0xbed65cf21aa2ee98), PJ_UINT64(0xd0f2cbb02e3b67c7),
        PJ_UINT64(0x93536795e3a33e88), PJ_UINT64(0xa80c038ccd5ccec8),
        PJ_UINT64(0xb8ad50c6f649af94), PJ_UINT64(0xbce192de8a85b8ea),
        PJ_UINT64(0x17d835b85bbb15f3), PJ_UINT64(0x2f2e6163076bcfad),
        PJ_UINT64(0xde4daaaca71dc9a5), PJ_UINT64(0xa6a2506687956571),
        PJ_UINT64(0xad87a3535c49ef28), PJ_UINT64(0x32d892fad841c342),
        PJ_UINT64(0x7127512f72f27cce)
    };
    pj_uint64_t k0 = PJ_UINT64(0x0706050403020100);
    pj_uint64_t k1 = PJ_UINT64(0x0f0e0d0c0b0a0908);
    pj_uint8_t in[32];
    unsigned i;

    for (i=0; i<sizeof(in); ++i)
        in[i] = (pj_uint8_t)i;

    for (i=0; i<PJ_ARRAY_SIZE(expected); ++i) {
        pj_uint64_t h = pj_hash_test_siphash24(k0, k1, in, i);
        if (h != expected[i]) {
            PJ_LOG(1,(THIS_FILE,
                      "   error: SipHash-2-4 vector mismatch at len %u", i));
            return -300;
        }
    }
    return 0;
}

static int hash_lower_test(pj_pool_t *pool)
{
    pj_hash_table_t *ht;
    unsigned v1 = 111, v2 = 222, v3 = 333, v4 = 444;
    void *e;

    PJ_TEST_NOT_NULL((ht=pj_hash_create(pool, HASH_COUNT)), NULL, return -400);

    /* Insert a mixed-case key via the lower variant. */
    pj_hash_set_lower(pool, ht, "SIP:Alice@Example.COM", PJ_HASH_KEY_STRING,
                      0, &v1);

    /* Lookup with a different case must find the same entry. */
    e = pj_hash_get_lower(ht, "sip:alice@example.com", PJ_HASH_KEY_STRING,
                          NULL);
    if (e != &v1) return -410;

    /* Setting via yet another case updates the same single entry. */
    pj_hash_set_lower(pool, ht, "sip:ALICE@EXAMPLE.com", PJ_HASH_KEY_STRING,
                      0, &v2);
    PJ_TEST_EQ(pj_hash_count(ht), 1, NULL, return -430);
    e = pj_hash_get_lower(ht, "SIP:alice@example.COM", PJ_HASH_KEY_STRING,
                          NULL);
    if (e != &v2) return -440;

    /* The plain (case-sensitive) API keeps different-case keys distinct. This
     * does not rely on the two keys hashing differently: even on a hash
     * collision the differing key bytes fail the content comparison, so a
     * lookup of one case never resolves the other.
     */
    pj_hash_set(pool, ht, "Kk", 2, 0, &v3);
    pj_hash_set(pool, ht, "kK", 2, 0, &v4);
    PJ_TEST_EQ(pj_hash_count(ht), 3, NULL, return -450);
    if (pj_hash_get(ht, "Kk", 2, NULL) != &v3) return -460;
    if (pj_hash_get(ht, "kK", 2, NULL) != &v4) return -470;

    return 0;
}

static int hash_hval_test(pj_pool_t *pool)
{
    pj_hash_table_t *ht;
    unsigned value = 0x999;
    const char *KEY = "call-id-1234567890@host";
    pj_uint32_t hval, djb2;
    void *e;

    PJ_TEST_NOT_NULL((ht=pj_hash_create(pool, HASH_COUNT)), NULL, return -500);

    djb2 = pj_hash_calc(0, KEY, PJ_HASH_KEY_STRING);

    /* get() with a zero hval must fill it with the djb2 value, whether or not
     * the key is present.
     */
    hval = 0;
    e = pj_hash_get(ht, KEY, PJ_HASH_KEY_STRING, &hval);
    PJ_TEST_EQ(e, NULL, NULL, return -510);
    PJ_TEST_EQ(hval, djb2, NULL, return -520);

    /* get-then-set: the returned hval can be reused to insert. */
    pj_hash_set(pool, ht, KEY, PJ_HASH_KEY_STRING, hval, &value);
    PJ_TEST_EQ(pj_hash_count(ht), 1, NULL, return -530);
    e = pj_hash_get(ht, KEY, PJ_HASH_KEY_STRING, NULL);
    if (e != &value) return -540;

    /* A nonzero hval must be left untouched, and the lookup must still
     * succeed (bucketing does not depend on the supplied hval).
     */
#if TEST_SIPHASH
    hval = 1; /* Deliberately not the djb2 hash. */
#else
    hval = djb2;
#endif
    e = pj_hash_get(ht, KEY, PJ_HASH_KEY_STRING, &hval);
    if (e != &value) return -550;
#if TEST_SIPHASH
    PJ_TEST_EQ(hval, 1, NULL, return -560);
#else
    PJ_TEST_EQ(hval, djb2, NULL, return -560);
#endif

    return 0;
}

static unsigned max_slip(long duration)
{
    const unsigned SLIP_MIN = test_app.ut_app.prm_ci_mode? 400 : 20;
    const unsigned SLIP_PCT = test_app.ut_app.prm_ci_mode? 30 : 0;

    return PJ_MAX(SLIP_MIN, (unsigned)duration * SLIP_PCT / 100);
}

static int pool_buf_misaligned_test(void)
{
    pj_pool_t *pool;
    char bufmem[512];
    char *buf;
    void *ptr;
    int rc = 0;

    PJ_LOG(3,("test", "...pool_buf misaligned buffer test"));

    /* Offset by 1 to guarantee the start is not PJ_POOL_ALIGNMENT-aligned. */
    buf = bufmem + 1;

    pool = pj_pool_create_on_buf(NULL, buf, sizeof(bufmem) - 1);
    PJ_TEST_NOT_NULL(pool, NULL, return -450);

    /* The pool struct is placed at the start of the buffer, which must have
     * been aligned by pj_pool_create_on_buf().
     */
    PJ_TEST_TRUE(((pj_size_t)pool & (PJ_POOL_ALIGNMENT - 1)) == 0, NULL,
                 { rc = -451; goto on_return; });

    ptr = pj_pool_alloc(pool, 1);
    PJ_TEST_TRUE(IS_ALIGNED(ptr), NULL, { rc = -455; goto on_return; });

    ptr = pj_pool_alloc(pool, 32);
    PJ_TEST_TRUE(IS_ALIGNED(ptr), NULL, { rc = -456; goto on_return; });

on_return:
    pj_pool_release(pool);
    return rc;
}

static pj_status_t get_uac_addr_for_sip_uri(pjsua_acc_id acc_id,
                                            pj_pool_t *pool,
                                            pjsip_sip_uri *sip_uri,
                                            pjsip_host_port *addr,
                                            pjsip_transport_type_e *p_tp_type,
                                            int *secure,
                                            const void **p_tp)
pj_status_t pjsua_acc_get_uac_addr(pjsua_acc_id acc_id,
                                   pj_pool_t *pool,
                                   const pj_str_t *dst_uri,
                                   pjsip_host_port *addr,
                                   pjsip_transport_type_e *p_tp_type,
                                   int *secure,
                                   const void **p_tp)
{
    pjsua_acc *acc;
    pjsip_sip_uri *sip_uri;

    PJ_ASSERT_RETURN(pjsua_acc_is_valid(acc_id), PJ_EINVAL);
    acc = &pjsua_var.acc[acc_id];

    /* If route-set is configured for the account, then URI is the
     * first entry of the route-set.
     */
    if (!pj_list_empty(&acc->route_set)) {
        sip_uri = (pjsip_sip_uri*)
                  pjsip_uri_get_uri(acc->route_set.next->name_addr.uri);
    } else {
        pj_str_t tmp;
        pjsip_uri *uri;

        pj_strdup_with_null(pool, &tmp, dst_uri);

        uri = pjsip_parse_uri(pool, tmp.ptr, tmp.slen, 0);
        if (uri == NULL)
            return PJSIP_EINVALIDURI;

        /* For non-SIP scheme, route set should be configured */
        if (!PJSIP_URI_SCHEME_IS_SIP(uri) && !PJSIP_URI_SCHEME_IS_SIPS(uri))
            return PJSIP_ENOROUTESET;

        sip_uri = (pjsip_sip_uri*)pjsip_uri_get_uri(uri);
    }

    return get_uac_addr_for_sip_uri(acc_id, pool, sip_uri, addr,
                                    p_tp_type, secure, p_tp);
}

static pj_status_t get_dlg_via_addr(pjsua_acc_id acc_id,
                                    pj_pool_t *pool,
                                    pjsip_uri *next_hop,
                                    pjsip_host_port *addr,
                                    pjsip_transport_type_e *p_tp_type,
                                    int *secure,
                                    const void **p_tp)
{
    pjsip_host_info dest_info;

    if (!PJSIP_URI_SCHEME_IS_SIP(next_hop) &&
        !PJSIP_URI_SCHEME_IS_SIPS(next_hop))
    {
        return PJSIP_ENOROUTESET;
    }

    if (pjsip_get_dest_info(next_hop, NULL, pool, &dest_info) == PJ_SUCCESS &&
        (dest_info.flag & PJSIP_TRANSPORT_RELIABLE) != 0)
    {
        return PJ_ENOTFOUND;
    }

    return get_uac_addr_for_sip_uri(acc_id, pool,
                                    (pjsip_sip_uri*)pjsip_uri_get_uri(next_hop),
                                    addr, p_tp_type, secure, p_tp);
}

pj_status_t pjsua_acc_get_uas_addr(pjsua_acc_id acc_id,
                                   pj_pool_t *pool,
                                   pjsip_dialog *dlg,
                                   pjsip_host_port *addr,
                                   pjsip_transport_type_e *p_tp_type,
                                   int *secure,
                                   const void **p_tp)
{
    pjsip_uri *next_hop;

    PJ_ASSERT_RETURN(pjsua_acc_is_valid(acc_id) && dlg, PJ_EINVAL);

    if (!pj_list_empty(&dlg->route_set))
        next_hop = dlg->route_set.next->name_addr.uri;
    else
        next_hop = dlg->target;

    return get_dlg_via_addr(acc_id, pool, next_hop, addr,
                            p_tp_type, secure, p_tp);
}

pj_status_t pjsua_acc_get_uac_dlg_addr(pjsua_acc_id acc_id,
                                       pj_pool_t *pool,
                                       pjsip_dialog *dlg,
                                       pjsip_host_port *addr,
                                       pjsip_transport_type_e *p_tp_type,
                                       int *secure,
                                       const void **p_tp)
{
    pjsua_acc *acc;
    pjsip_uri *next_hop;

    PJ_ASSERT_RETURN(pjsua_acc_is_valid(acc_id) && dlg, PJ_EINVAL);
    acc = &pjsua_var.acc[acc_id];

    if (!pj_list_empty(&acc->route_set))
        next_hop = acc->route_set.next->name_addr.uri;
    else
        next_hop = dlg->target;

    return get_dlg_via_addr(acc_id, pool, next_hop, addr,
                            p_tp_type, secure, p_tp);
}

static void destroy_conf_port_resources(struct conf_port *conf_port)
{
    /* Destroy resample if this conf port has it. */
    if (conf_port->rx_resample) {
        pjmedia_resample_destroy(conf_port->rx_resample);
        conf_port->rx_resample = NULL;
    }
    if (conf_port->tx_resample) {
        pjmedia_resample_destroy(conf_port->tx_resample);
        conf_port->tx_resample = NULL;
    }

    /* Destroy pjmedia port if this conf port is passive port,
     * i.e: has delay buf.
     */
    if (conf_port->delay_buf) {
        pjmedia_delay_buf_destroy(conf_port->delay_buf);
        conf_port->delay_buf = NULL;

        if (conf_port->port)
            pjmedia_port_destroy(conf_port->port);
        conf_port->port = NULL;
    }
}

static void sa_build_reg_route_set(pjsua_acc *acc, pj_pool_t *pool,
                                   pjsip_route_hdr *route_set)
{
    const pjsip_route_hdr *r;

    pj_list_init(route_set);

    /* Hidden affinity Route first (UDP destination pin). */
    if (acc->sa_route_hdr && acc->sa_enabled && acc->sa_next_hop_tp != NULL &&
        ((acc->sa_next_hop_tp->key.type & ~PJSIP_TRANSPORT_IPV6)
         == PJSIP_TRANSPORT_UDP))
    {
        pj_list_push_back(route_set,
                          pjsip_hdr_shallow_clone(pool, acc->sa_route_hdr));
    }

    if (acc->cfg.reg_use_proxy & PJSUA_REG_USE_OUTBOUND_PROXY) {
        r = pjsua_var.outbound_proxy.next;
        while (r != &pjsua_var.outbound_proxy) {
            pj_list_push_back(route_set, pjsip_hdr_shallow_clone(pool, r));
            r = r->next;
        }
    }

    if ((acc->cfg.reg_use_proxy & PJSUA_REG_USE_ACC_PROXY) &&
        acc->cfg.proxy_cnt)
    {
        int cnt = acc->cfg.proxy_cnt;
        pjsip_route_hdr *pos = route_set->prev;
        int i;

        r = acc->route_set.prev;
        for (i=0; i<cnt; ++i) {
            pj_list_push_front(pos, pjsip_hdr_shallow_clone(pool, r));
            r = r->prev;
        }
    }
}

static pj_size_t tcp_get_crlf_ka_len(const char *data, pj_size_t size)
{
    pj_size_t i = 0;

    while (size - i >= 4 &&
           data[i+0] == '\r' && data[i+1] == '\n' &&
           data[i+2] == '\r' && data[i+3] == '\n')
    {
        i += 4;
    }
    return i;
}

static pj_size_t tls_get_crlf_ka_len(const char *data, pj_size_t size)
{
    pj_size_t i = 0;

    while (size - i >= 4 &&
           data[i+0] == '\r' && data[i+1] == '\n' &&
           data[i+2] == '\r' && data[i+3] == '\n')
    {
        i += 4;
    }
    return i;
}

static pj_status_t ka_send_raw(pj_sock_t sock, const void *data, pj_size_t len)
{
    pj_ssize_t sent = (pj_ssize_t)len;
    pj_status_t status;

    status = pj_sock_send(sock, data, &sent, 0);
    if (status == PJ_SUCCESS && sent != (pj_ssize_t)len)
        status = PJ_ETOOSMALL;

    /* Let the server read the data and produce any response. */
    flush_events(500);
    return status;
}

static pj_ssize_t ka_recv_timeout(pj_sock_t sock, void *buf,
                                  pj_size_t buf_size, unsigned timeout_ms)
{
    pj_fd_set_t rset;
    pj_time_val timeout;
    pj_ssize_t len;
    int n;
    pj_status_t status;

    PJ_FD_ZERO(&rset);
    PJ_FD_SET(sock, &rset);
    timeout.sec = timeout_ms / 1000;
    timeout.msec = timeout_ms % 1000;

    n = pj_sock_select((int)sock + 1, &rset, NULL, NULL, &timeout);
    if (n < 0)
        return -1;
    if (n == 0 || !PJ_FD_ISSET(sock, &rset))
        return 0;

    len = (pj_ssize_t)buf_size;
    status = pj_sock_recv(sock, buf, &len, 0);
    if (status != PJ_SUCCESS)
        return -1;
    return len;
}

int transport_tcp_keep_alive_test(void)
{
#if PJSIP_TCP_KEEP_ALIVE_RESPONSE
    enum { PONG_WAIT_MSEC = 2000, NO_PONG_WAIT_MSEC = 500 };
    pjsip_tpfactory *tpfactory = NULL;
    pj_sock_t sock = PJ_INVALID_SOCKET;
    pj_sockaddr_in rem_addr;
    const char ping[] = { '\r', '\n', '\r', '\n' };
    /* Non-ping data whose leading byte is not CRLF, followed by a double CRLF.
     * The double CRLF here is a continuation, not a ping, so it must be
     * ignored by the keep-alive responder.
     */
    const char not_ping[] = { 'X', '\r', '\n', '\r', '\n' };
    char buf[8];
    pj_ssize_t len;
    pj_status_t status;
    int ret = 0;

    PJ_LOG(3,(THIS_FILE, "  testing TCP CRLF keep-alive response"));

    /* Start TCP listener on arbitrary port. */
    status = pjsip_tcp_transport_start(endpt, NULL, 1, &tpfactory);
    if (status != PJ_SUCCESS) {
        app_perror("   Error: unable to start TCP transport", status);
        return -200;
    }

    /* Create a raw client socket and connect to the listener. */
    status = pj_sock_socket(pj_AF_INET(), pj_SOCK_STREAM(), 0, &sock);
    if (status != PJ_SUCCESS) {
        app_perror("   Error: unable to create socket", status);
        ret = -210;
        goto on_return;
    }

    status = pj_sockaddr_in_init(&rem_addr, &tpfactory->addr_name.host,
                                 (pj_uint16_t)tpfactory->addr_name.port);
    if (status != PJ_SUCCESS) {
        ret = -211;
        goto on_return;
    }

    status = pj_sock_connect(sock, &rem_addr, sizeof(rem_addr));
    if (status != PJ_SUCCESS) {
        app_perror("   Error: unable to connect to TCP listener", status);
        ret = -212;
        goto on_return;
    }

    /* Let the server accept the connection. */
    flush_events(100);

    /* Phase 1: a plain ping must be answered with exactly one CRLF pong. */
    status = ka_send_raw(sock, ping, sizeof(ping));
    if (status != PJ_SUCCESS) {
        app_perror("   Error: unable to send keep-alive ping", status);
        ret = -213;
        goto on_return;
    }
    len = ka_recv_timeout(sock, buf, sizeof(buf), PONG_WAIT_MSEC);
    if (len != 2 || buf[0] != '\r' || buf[1] != '\n') {
        PJ_LOG(3,(THIS_FILE, "   Error: expected a CRLF pong, got %d byte(s)",
                  (int)len));
        ret = -220;
        goto on_return;
    }

    /* Phase 2: a double CRLF that is not at the front of the stream must not
     * be treated as a ping, hence no pong.
     */
    status = ka_send_raw(sock, not_ping, sizeof(not_ping));
    if (status != PJ_SUCCESS) {
        app_perror("   Error: unable to send non-ping data", status);
        ret = -230;
        goto on_return;
    }
    len = ka_recv_timeout(sock, buf, sizeof(buf), NO_PONG_WAIT_MSEC);
    if (len != 0) {
        PJ_LOG(3,(THIS_FILE, "   Error: got %d byte(s) response to a non-ping "
                             "double CRLF (expected none)", (int)len));
        ret = -231;
        goto on_return;
    }

    /* Phase 3: a genuine ping after the non-ping data is still answered. */
    status = ka_send_raw(sock, ping, sizeof(ping));
    if (status != PJ_SUCCESS) {
        app_perror("   Error: unable to send keep-alive ping", status);
        ret = -240;
        goto on_return;
    }
    len = ka_recv_timeout(sock, buf, sizeof(buf), PONG_WAIT_MSEC);
    if (len != 2 || buf[0] != '\r' || buf[1] != '\n') {
        PJ_LOG(3,(THIS_FILE, "   Error: expected a CRLF pong, got %d byte(s)",
                  (int)len));
        ret = -241;
        goto on_return;
    }

    PJ_LOG(3,(THIS_FILE, "   TCP keep-alive response test OK"));

on_return:
    if (sock != PJ_INVALID_SOCKET)
        pj_sock_close(sock);
    if (tpfactory) {
        pjsip_tpmgr_unregister_tpfactory(pjsip_endpt_get_tpmgr(endpt),
                                         tpfactory);
    }
    flush_events(500);
    return ret;
#else
    PJ_LOG(3,(THIS_FILE, "  skipping TCP CRLF keep-alive response test "
                         "(PJSIP_TCP_KEEP_ALIVE_RESPONSE=0)"));
    return 0;
#endif  /* PJSIP_TCP_KEEP_ALIVE_RESPONSE */
}

static struct wvp_sess *wvp_find_dst(struct wvp_test *t,
                                     const pj_sockaddr_t *addr)
{
    if (t->caller && pj_sockaddr_cmp(addr, &t->caller->addr) == 0)
        return t->caller;
    if (t->callee && pj_sockaddr_cmp(addr, &t->callee->addr) == 0)
        return t->callee;
    return NULL;
}

static pj_status_t wvp_on_tx_pkt(pj_ice_sess *ice, unsigned comp_id,
                                 unsigned transport_id,
                                 const void *pkt, pj_size_t size,
                                 const pj_sockaddr_t *dst_addr,
                                 unsigned dst_addr_len)
{
    struct wvp_sess *src = (struct wvp_sess*) ice->user_data;
    struct wvp_test *t = src->test;
    struct wvp_sess *dst;
    struct wvp_pkt *p;

    PJ_UNUSED_ARG(dst_addr_len);

    /* Sends to the bogon address fail synchronously, as if the local route
     * to it is prohibited (EPERM).
     */
    if (pj_sockaddr_cmp(dst_addr, &t->bogon) == 0)
        return PJ_STATUS_FROM_OS(120); /* arbitrary non-success send error */

    /* An unknown destination or an oversized packet is not expected in this
     * controlled setup; flag it and fail the send so the test fails loudly
     * instead of silently masking the problem.
     */
    dst = wvp_find_dst(t, dst_addr);
    if (dst == NULL || size > sizeof(p->data)) {
        t->shim_err = PJ_TRUE;
        return PJ_EINVAL;
    }

    /* Enqueue a copy for delivery from the poll loop. */
    p = PJ_POOL_ZALLOC_T(t->pool, struct wvp_pkt);
    p->dst = dst;
    p->comp_id = comp_id;
    p->transport_id = transport_id;
    pj_sockaddr_cp(&p->src_addr, &src->addr);
    p->src_len = pj_sockaddr_get_len(&src->addr);
    p->len = size;
    pj_memcpy(p->data, pkt, size);
    pj_list_push_back(&t->txq, p);

    return PJ_SUCCESS;
}

static void wvp_on_ice_complete(pj_ice_sess *ice, pj_status_t status)
{
    struct wvp_sess *s = (struct wvp_sess*) ice->user_data;
    s->completed = PJ_TRUE;
    s->status = status;
}

static void wvp_on_rx_data(pj_ice_sess *ice, unsigned comp_id,
                           unsigned transport_id, void *pkt, pj_size_t size,
                           const pj_sockaddr_t *src_addr,
                           unsigned src_addr_len)
{
    PJ_UNUSED_ARG(ice); PJ_UNUSED_ARG(comp_id); PJ_UNUSED_ARG(transport_id);
    PJ_UNUSED_ARG(pkt); PJ_UNUSED_ARG(size);
    PJ_UNUSED_ARG(src_addr); PJ_UNUSED_ARG(src_addr_len);
}

static void wvp_poll(struct wvp_test *t, unsigned msec)
{
    pj_time_val stop, now;

    pj_gettimeofday(&stop);
    stop.msec += msec;
    pj_time_val_normalize(&stop);

    for (;;) {
        unsigned guard = 0;

        pj_timer_heap_poll(t->stun_cfg->timer_heap, NULL);

        while (!pj_list_empty(&t->txq) && ++guard < 1000) {
            struct wvp_pkt *p = t->txq.next;
            pj_list_erase(p);
            pj_ice_sess_on_rx_pkt(p->dst->ice, p->comp_id, p->transport_id,
                                  p->data, p->len, &p->src_addr, p->src_len);
        }

        pj_gettimeofday(&now);
        if (PJ_TIME_VAL_GTE(now, stop))
            break;
        pj_thread_sleep(1);
    }
}

static pj_status_t wvp_create_sess(struct wvp_test *t, struct wvp_sess *s,
                                   const char *name, pj_ice_sess_role role,
                                   pj_uint16_t port, int wait_pair_timeout)
{
    pj_ice_sess_cb cb;
    pj_ice_sess_options opt;
    pj_str_t loopback, fnd;
    unsigned cand_id;
    pj_status_t status;

    pj_bzero(&cb, sizeof(cb));
    cb.on_tx_pkt = &wvp_on_tx_pkt;
    cb.on_ice_complete = &wvp_on_ice_complete;
    cb.on_rx_data = &wvp_on_rx_data;

    s->test = t;
    s->completed = PJ_FALSE;
    s->status = PJ_EUNKNOWN;
    s->ufrag = pj_str((char*)(role==PJ_ICE_SESS_ROLE_CONTROLLING ?
                              "Lcaller0" : "Lcallee0"));
    s->pass  = pj_str((char*)"0123456789012345678901"); /* >=22 chars */

    loopback = pj_str((char*)"127.0.0.1");
    pj_sockaddr_init(pj_AF_INET(), &s->addr, &loopback, port);

    status = pj_ice_sess_create(t->stun_cfg, name, role, 1, &cb,
                                &s->ufrag, &s->pass, NULL, &s->ice);
    if (status != PJ_SUCCESS)
        return status;

    s->ice->user_data = s;

    if (wait_pair_timeout != -2) {
        pj_ice_sess_get_options(s->ice, &opt);
        opt.wait_valid_pair_timeout = wait_pair_timeout;
        pj_ice_sess_set_options(s->ice, &opt);
    }

    /* Add a single host candidate at this session's address. */
    fnd = pj_str((char*)"Hhost");
    status = pj_ice_sess_add_cand(s->ice, 1, WVP_TP_ID,
                                  PJ_ICE_CAND_TYPE_HOST, 65535, &fnd,
                                  &s->addr, &s->addr, &s->addr,
                                  pj_sockaddr_get_len(&s->addr), &cand_id);
    return status;
}

static void wvp_init_rcand(pj_ice_sess_cand *c, const pj_sockaddr *addr)
{
    pj_bzero(c, sizeof(*c));
    c->type = PJ_ICE_CAND_TYPE_HOST;
    c->comp_id = 1;
    c->transport_id = WVP_TP_ID;
    c->local_pref = 65535;
    c->foundation = pj_str((char*)"Hrhost");
    c->prio = 1862270975;       /* a valid host-candidate priority */
    pj_sockaddr_cp(&c->addr, addr);
    pj_sockaddr_cp(&c->base_addr, addr);
}

static pj_bool_t write_temp_file(const uint8_t *Data, size_t Size,
                                 char *name_buf, size_t name_buf_len)
{
    int fd;
    size_t total;

    if (name_buf_len < 1)
        return PJ_FALSE;

    strncpy(name_buf, "/tmp/pjsip-fuzz-wav-XXXXXX", name_buf_len - 1);
    name_buf[name_buf_len - 1] = '\0';

    fd = mkstemp(name_buf);
    if (fd < 0)
        return PJ_FALSE;

    /* write() may be interrupted (EINTR) or perform a short write; loop until
     * the whole buffer is written so valid inputs are not dropped. */
    total = 0;
    while (total < Size) {
        ssize_t n = write(fd, Data + total, Size - total);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            close(fd);
            unlink(name_buf);
            return PJ_FALSE;
        }
        total += (size_t)n;
    }

    close(fd);

    return PJ_TRUE;
}

extern int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
{
    static pj_bool_t initialized = PJ_FALSE;
    char filename[64];
    pj_pool_t *pool;
    pjmedia_port *wav_port;
    pjmedia_avi_streams *avi_streams;
    pj_status_t status;

    if (Size < kMinInputLength || Size > kMaxInputLength)
        return 0;

    /* One-time PJLIB / PJMEDIA initialisation. */
    if (!initialized) {
        pj_log_set_level(0);

        if (pj_init() != PJ_SUCCESS)
            return 0;

        pj_caching_pool_init(&caching_pool, &pj_pool_factory_default_policy, 0);

        /* A media endpoint registers codec/format managers; avoid audio init. */
        if (pjmedia_endpt_create2(&caching_pool.factory, NULL, 0,
                                  &med_endpt) != PJ_SUCCESS)
        {
            pj_caching_pool_destroy(&caching_pool);
            return 0;
        }

        /* pjmedia_endpt_create2() registers the video codec manager but not
         * the video format/converter/event managers. Without these, parsing an
         * AVI with a recognizable video stream calls pjmedia_get_video_format_info()
         * with a NULL manager and aborts (format.c: "Assertion mgr != NULL"),
         * so the AVI video header path could never be fuzzed. Create them here,
         * from a long-lived pool, so that path is actually exercised. */
        {
            pj_pool_t *vpool = pj_pool_create(&caching_pool.factory,
                                              "fuzz-wav-init",
                                              4000, 4000, NULL);
            if (vpool) {
                if (!pjmedia_video_format_mgr_instance())
                    pjmedia_video_format_mgr_create(vpool, 64, 0, NULL);
                if (!pjmedia_converter_mgr_instance())
                    pjmedia_converter_mgr_create(vpool, NULL);
                if (!pjmedia_event_mgr_instance())
                    pjmedia_event_mgr_create(vpool, 0, NULL);
            }
        }

        initialized = PJ_TRUE;
    }

    if (!write_temp_file(Data, Size, filename, sizeof(filename)))
        return 0;

    pool = pj_pool_create(&caching_pool.factory, "fuzz-wav", 4000, 4000, NULL);
    if (!pool) {
        unlink(filename);
        return 0;
    }

    /* Parse as a WAV/RIFF file. */
    wav_port = NULL;
    status = pjmedia_wav_player_port_create(pool, filename, 0, 0, 0, &wav_port);
    if (status == PJ_SUCCESS && wav_port) {
        pjmedia_wav_player_info info;
        pjmedia_wav_player_get_info(wav_port, &info);
        pjmedia_port_destroy(wav_port);
    }

    /* Parse as an AVI file. */
    avi_streams = NULL;
    status = pjmedia_avi_player_create_streams(pool, filename, 0, &avi_streams);
    if (status == PJ_SUCCESS && avi_streams) {
        unsigned i, num = pjmedia_avi_streams_get_num_streams(avi_streams);
        for (i = 0; i < num; ++i) {
            pjmedia_avi_stream *stream =
                pjmedia_avi_streams_get_stream(avi_streams, i);
            if (stream) {
                pjmedia_port *port = pjmedia_avi_stream_get_port(stream);
                if (port)
                    pjmedia_port_destroy(port);
            }
        }
    }

    pj_pool_release(pool);
    unlink(filename);

    return 0;
}

PJ_DEF(pj_status_t) pjsua_set_null_snd_dev2(
                            const pjsua_null_snd_dev_param *snd_param)
{
    PJ_UNUSED_ARG(snd_param);
    return PJ_SUCCESS;
}

static void close_snd_port(pjmedia_snd_port *old_snd)
{
    pjmedia_aud_stream *strm;
    pjmedia_aud_param param;
    pjmedia_aud_dev_info cap_info, play_info;
    pj_status_t st;

    if (!old_snd)
        return;

    strm = pjmedia_snd_port_get_snd_stream(old_snd);
    if (strm) {
        st = pjmedia_aud_stream_get_param(strm, &param);
    } else {
        st = PJ_EINVAL;
    }
    if (st != PJ_SUCCESS ||
        param.rec_id == PJSUA_SND_NO_DEV ||
        pjmedia_aud_dev_get_info(param.rec_id, &cap_info) != PJ_SUCCESS)
    {
        cap_info.name[0] = '\0';
    }
    if (st != PJ_SUCCESS ||
        pjmedia_aud_dev_get_info(param.play_id, &play_info) != PJ_SUCCESS)
    {
        play_info.name[0] = '\0';
    }

    PJ_LOG(4,(THIS_FILE, "Closing %s sound playback device and "
                         "%s sound capture device",
                         play_info.name, cap_info.name));

    if (strm) {
        pjmedia_event_unsubscribe(NULL, &on_media_event, NULL, strm);
    }

    pjmedia_snd_port_disconnect(old_snd);
    pjmedia_snd_port_destroy(old_snd);
}

PJ_DEF(pj_status_t) pjsua_set_null_snd_dev(void)
{
    pjsua_null_snd_dev_param null_snd_param;
    pjsua_null_snd_dev_param_default(&null_snd_param);
    return pjsua_set_null_snd_dev2(&null_snd_param);
}

PJSUA2_THROW(Error)
{
    pjsua_null_snd_dev_param param;

    pjsua_null_snd_dev_param_default(&param);
    param.avoid_clock_gap = avoidClockGap;
    PJSUA2_CHECK_EXPR( pjsua_set_null_snd_dev2(&param) );
}

static pj_bool_t on_call_tsx_terminate_session(pjsua_call_id call_id,
                                               pjsip_transaction *tsx,
                                               pjsip_event *e)
{
    PJ_UNUSED_ARG(e);
    PJ_LOG(3, (THIS_FILE,
               "Call %d: suppressing termination after %.*s %d",
               call_id,
               (int)tsx->method.name.slen, tsx->method.name.ptr,
               tsx->status_code));
    return PJ_TRUE;
}

static pj_bool_t pjsua_call_on_uac_tsx_terminate_session(
                                            pjsip_inv_session *inv,
                                            pjsip_transaction *tsx,
                                            pjsip_event *e)
{
    pjsua_call *call = (pjsua_call*) inv->dlg->mod_data[pjsua_var.mod.id];

    if (!call || call->hanging_up ||
        !pjsua_var.ua_cfg.cb.on_call_tsx_terminate_session)
    {
        return PJ_FALSE;
    }

    return (*pjsua_var.ua_cfg.cb.on_call_tsx_terminate_session)(call->index,
                                                                tsx, e);
}

pj_bool_t Endpoint::on_call_tsx_terminate_session(pjsua_call_id call_id,
                                                  pjsip_transaction *tsx,
                                                  pjsip_event *e)
{
    PJ_UNUSED_ARG(tsx);

    Call *call = Call::lookup(call_id);
    if (!call) {
        return PJ_FALSE;
    }

    OnCallTsxTerminateSessionParam prm;
    prm.e.fromPj(*e);

    call->onCallTsxTerminateSession(prm);

    return prm.suppressTermination ? PJ_TRUE : PJ_FALSE;
}

atic pj_bool_t sa_sync_mirror(pjsua_acc *acc, pjsip_hdr *dst,
                                 const pjsip_hdr *src)
{
    pjsip_hdr *di = dst->next;
    const pjsip_hdr *si = src->next;
    pj_bool_t differs = PJ_FALSE;

    while (di != dst && si != src) {
        if (pjsip_hdr_cmp(di, si) != 0) {
            differs = PJ_TRUE;
            break;
        }
        di = di->next;
        si = si->next;
    }
    if (!differs && (di != dst || si != src))
        differs = PJ_TRUE;     /* different sizes */

    if (differs) {
        if (acc->sa_mirror_pool)
            pj_pool_reset(acc->sa_mirror_pool);
        else
            acc->sa_mirror_pool = pjsua_pool_create("sa_mirror%p",
                                                   256, 256);
        if (!acc->sa_mirror_pool)
            return differs;

        pj_list_init(dst);
        for (si = src->next; si != src; si = si->next)
            pj_list_push_back(dst,
                              pjsip_hdr_clone(acc->sa_mirror_pool, si));
    }
    return differs;
}

atic void sa_sync_route_set(pjsua_acc *acc)
{
    pj_bool_t need_route;
    pj_bool_t hdr_rebuilt = PJ_FALSE;

    if (acc->sa_route_hdr)
        pj_list_erase(acc->sa_route_hdr);

    /* Use sa_next_hop_tp->key.type rather than acc->tp_type because
     * tp_type is only meaningful when transport_id is set, and
     * affinity is bypassed in that case anyway.
     */
    need_route =
        acc->sa_enabled && acc->sa_next_hop_tp != NULL &&
        ((acc->sa_next_hop_tp->key.type & ~PJSIP_TRANSPORT_IPV6)
         == PJSIP_TRANSPORT_UDP);

    if (need_route) {
        /* Reuse cached hdr when the address didn't change (skips parse
         * + acc->pool alloc on the acc_modify detach/reattach path).
         */
        if (acc->sa_route_hdr == NULL ||
            pj_sockaddr_cmp(&acc->sa_route_hdr_addr,
                            &acc->sa_next_hop_addr) != 0)
        {
            /* Build "<sip:host:port;lr;hide>". The angle brackets are
             * required so ;hide lands in URI params, where
             * pjsip_routing_hdr_print() looks for it.
             */
            char host_port[PJ_INET6_ADDRSTRLEN + 16];
            char buf[PJ_INET6_ADDRSTRLEN + 32];
            pj_str_t hname = { "Route", 5 };
            pj_str_t tmp;
            pjsip_route_hdr *hdr;
            int len;

            pj_sockaddr_print(&acc->sa_next_hop_addr, host_port,
                              sizeof(host_port),
                              3 /* port + IPv6 brackets */);
            len = pj_ansi_snprintf(buf, sizeof(buf),
                                   "<sip:%s;lr;hide>", host_port);
            if (len > 0 && len < (int)sizeof(buf)) {
                pj_strdup2(acc->pool, &tmp, buf);
                hdr = (pjsip_route_hdr*)pjsip_parse_hdr(
                          acc->pool, &hname, tmp.ptr, tmp.slen, NULL);
                if (hdr) {
                    acc->sa_route_hdr = hdr;
                    pj_sockaddr_cp(&acc->sa_route_hdr_addr,
                                   &acc->sa_next_hop_addr);
                    hdr_rebuilt = PJ_TRUE;
                } else {
                    PJ_LOG(2,(THIS_FILE, "Account %d: failed to parse "
                                         "hidden Route '%.*s' (#4964)",
                              acc->index, (int)tmp.slen, tmp.ptr));
                    acc->sa_route_hdr = NULL;
                }
            }
        }

        if (acc->sa_route_hdr)
            pj_list_push_front(&acc->route_set, acc->sa_route_hdr);
    }

    /* Push to regc when the route_set diffs from sa_pushed_route, OR
     * when we rebuilt the hidden hdr. The rebuild case is force-pushed
     * because pjsip_hdr_cmp compares headers by printed form, and
     * ;hide entries print empty — so a stale hidden Route clone in
     * the mirror would falsely match a fresh hidden Route built for a
     * different address. (#4964)
     */
    if (acc->regc) {
        pj_bool_t changed = sa_sync_mirror(
                                acc,
                                (pjsip_hdr*)&acc->sa_pushed_route,
                                (const pjsip_hdr*)&acc->route_set);
        if (changed || hdr_rebuilt)
            pjsip_regc_set_route_set(acc->regc, &acc->route_set);
    }
}

static int worker_thread(void *arg)
{
    enum { TIMEOUT = 10 };

    PJ_UNUSED_ARG(arg);

    while (!pjsua_var.thread_quit_flag) {
        int count;

        count = pjsua_handle_events(TIMEOUT);
        if (count < 0)
            pj_thread_sleep(TIMEOUT);
    }

    return 0;
}

int main (void) {
  unsigned char uc;
  signed char sc;
  unsigned short us;
  short ss;

  set_uchar (&uc);
  set_schar (&sc);
  set_ushort (&us);
  set_short (&ss);

  if (uc != 255) return 1;
  if (sc != -3) return 2;
  if (us != 65535) return 3;
  if (ss != -2) return 4;
  return 0;
}

static int check (int n, ...) {
  va_list ap; va_start (ap, n);
  double td = 0; long ti = 0;
  for (int k = 0; k < n; k++) { struct DL s = va_arg (ap, struct DL); td += s.d; ti += s.i; }
  va_end (ap);
  return (td == 6.0 && ti == 60) ? 0 : 1;
}

int main (void) {
  int n = 0, i = 5;
  while (i-- > 0) n++;
  return n == 5 ? 0 : 1;
}

int main (void) {
  int d = ({ struct large t; t.x = 2; t; }).x
        - ({ struct large t; t.x = 1; t; }).x;
  return d == 1 ? 0 : 1;
}

static int f (int i, ...) {
  va_list ap;
  va_start (ap, i);
  int a = va_arg (ap, struct S).c[0];
  int b = va_arg (ap, struct S).c[1];
  va_end (ap);
  return a + b;
}

static int reg_int_structs (struct IS s1, struct IS s2, int z, ...) {
  va_list ap;
  va_start (ap, z);
  int v = va_arg (ap, int);
  va_end (ap);
  return v;
}

static double reg_fp_structs (struct FS f1, struct FS f2, double z, ...) {
  va_list ap;
  va_start (ap, z);
  double v = va_arg (ap, double);
  va_end (ap);
  return v;
}

static int mem_structs (struct MS m1, struct MS m2, struct MS m3, struct MS m4, struct MS m5,
                        struct MS m6, struct MS m7, int g1, int g2, int g3, int g4, int g5,
                        int g6, ...) {
  /* All GPRs consumed by g1..g6: the vararg comes from the overflow area,
     right after the seven 24-byte-rounded structs. */
  va_list ap;
  va_start (ap, g6);
  int v = va_arg (ap, int);
  va_end (ap);
  return v;
}

int main (void) {
  struct IS s1 = {111}, s2 = {222};
  struct FS f1 = {1.5}, f2 = {2.5};
  struct MS m = {{0}};

  if (reg_int_structs (s1, s2, 3, 42) != 42) return 1;
  if (reg_fp_structs (f1, f2, 3.0, 43.0) != 43.0) return 2;
  if (mem_structs (m, m, m, m, m, m, m, 1, 2, 3, 4, 5, 6, 44) != 44) return 3;
  return 0;
}

static void redirect_thunk_by_reg (MIR_context_t ctx, void *thunk, void *to,
                                   unsigned temp_reg) {
    code[0] = 0x58000040 | temp_reg;        /* ldr x<temp_reg>,8 (pc-relative) */
    code[1] = 0xd61f0000 | (temp_reg << 5); /* br x<temp_reg> */
void _MIR_redirect_thunk (MIR_context_t ctx, void *thunk, void *to) {
  redirect_thunk_by_reg (ctx, thunk, to, 9);
}

  /* x9 carries bb_version to the handler, so the branch to the handler must
     not use _MIR_redirect_thunk's x9-based far form: when the thunk ends up
     farther than a direct branch can reach (+-128MB) from the handler, the
     handler would receive its own address instead of bb_version.  Use x10,
     the other fixed temp not used in machinized code.  */
  redirect_thunk_by_reg (ctx, (uint8_t *) res + offset, handler, 10);

long double vsum (int n, ...) {
  va_list ap;
  long double s = 0;

  va_start (ap, n);
  while (n--) s += va_arg (ap, long double);
  va_end (ap);
  return s;
}

long double fsum (long double a1, long double a2, long double a3, long double a4, long double a5,
                  long double a6, long double a7, long double a8, long double a9,
                  long double a10) {
  return a1 + a2 + a3 + a4 + a5 + a6 + a7 + a8 + a9 + a10;
}

int main (void) {
  if (vsum (9, 1.L, 2.L, 3.L, 4.L, 5.L, 6.L, 7.L, 8.L, 9.L) != 45.L) return 1;
  if (fsum (1.L, 2.L, 3.L, 4.L, 5.L, 6.L, 7.L, 8.L, 9.L, 10.L) != 55.L) return 2;
  return 0;
}

static void
stop_subscriber(pid_t pid, int fd)
{
	if (pid > 0) {
		kill(pid, SIGKILL);
	}
	if (fd >= 0) {
		close(fd);
	}
}

static void
capture_rule_id(const char *json_body)
{
    cJSON *root;
    cJSON *data;
    cJSON *id;

    if (json_body == NULL) {
        return;
    }
    root = cJSON_Parse(json_body);
    if (root == NULL) {
        return;
    }
    data = cJSON_GetObjectItemCaseSensitive(root, "data");
    id   = cJSON_GetObjectItemCaseSensitive(data, "id");
    if (cJSON_IsNumber(id)) {
        last_rule_id = id->valueint;
    }
    cJSON_Delete(root);
}

static bool
wait_for_http_server_ready(int timeout_ms)
{
	int waited_ms = 0;
	char *cmd = CURL_CMD_PREFIX "-X GET 'http://localhost:8081/api/v4'";

	while (waited_ms < timeout_ms) {
		FILE *fd = popen(cmd, "r");
		char  status[32] = { 0 };
		bool  ready = fd != NULL && fgets(status, sizeof(status), fd) != NULL &&
		    strncmp(status, STATUS_CODE_OK, strlen(STATUS_CODE_OK)) == 0;

		SAFE_POPEN_CLOSE(fd);
		if (ready) {
			return true;
		}
		nng_msleep(100);
		waited_ms += 100;
	}

	return false;
}

static bool
test_put_bridges_switch(bool bridge_switch)
