}

static bool
test_env_allows_ipv6_loopback(void)
{
#ifndef NANO_PLATFORM_WINDOWS
	int          rv;
	nng_listener listener = NNG_LISTENER_INITIALIZER;
	nng_socket   sock     = { 0 };

	if ((rv = nng_rep_open(&sock)) != 0 ||
	    (rv = nng_listener_create(&listener, sock, "tcp://[::1]:0")) != 0) {
		fprintf(stderr, "skip: NNG IPv6 loopback unavailable: %s\n",
		    nng_strerror(rv));
		if (listener.id != 0) {
			nng_listener_close(listener);
		}
		if (sock.id != 0) {
			nng_close(sock);
		}
		return false;
	}
	nng_listener_close(listener);
	nng_close(sock);
#endif
	return true;
}

static bool
wait_for_tcp_listener(uint16_t port, int timeout_ms)
{
#ifndef NANO_PLATFORM_WINDOWS
	int waited = 0;

	while (waited < timeout_ms) {
		int                fd;
		struct sockaddr_in addr;

		fd = socket(AF_INET, SOCK_STREAM, 0);
		if (fd >= 0) {
			memset(&addr, 0, sizeof(addr));
			addr.sin_family      = AF_INET;
			addr.sin_port        = htons(port);
			addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
			if (connect(fd, (struct sockaddr *) &addr, sizeof(addr)) == 0) {
				close(fd);
				return true;
			}
			close(fd);
		}
		nng_msleep(50);
		waited += 50;
	}
#else
	(void) port;
	(void) timeout_ms;
#endif
	fprintf(stderr, "[FAIL] websocket listener 127.0.0.1:%u was not ready\n",
	    port);
	return false;
}

static bool
wait_for_text(int fd, const char *needle, char *output, size_t output_size,
    int timeout_ms)
{
#ifndef NANO_PLATFORM_WINDOWS
	int    waited = 0;
	size_t used   = 0;

	if (fd < 0 || needle == NULL || output == NULL || output_size < 2) {
		return false;
	}
	output[0] = '\0';
	while (waited < timeout_ms) {
		fd_set         readfds;
		struct timeval timeout = { 0, 50000 };
		char           chunk[128];
		ssize_t        n;

		FD_ZERO(&readfds);
		FD_SET(fd, &readfds);
		if (select(fd + 1, &readfds, NULL, NULL, &timeout) < 0) {
			if (errno == EINTR) {
				continue;
			}
			break;
		}
		waited += 50;
		if (!FD_ISSET(fd, &readfds)) {
			continue;
		}
		n = read(fd, chunk, sizeof(chunk) - 1);
		if (n <= 0) {
			break;
		}
		chunk[n] = '\0';
		if (used + (size_t) n >= output_size) {
			size_t keep = output_size - 1;
			size_t drop = used + (size_t) n - keep;

			if (drop < used) {
				memmove(output, output + drop, used - drop);
				used -= drop;
			} else {
				used = 0;
			}
		}
		if (n > 0) {
			size_t copy = (size_t) n;
			if (used + copy >= output_size) {
				copy = output_size - used - 1;
			}
			memcpy(output + used, chunk, copy);
			used += copy;
			output[used] = '\0';
			if (strstr(output, needle) != NULL ||
			    strstr(chunk, needle) != NULL) {
				return true;
			}
		}
	}
#else
	(void) fd;
	(void) needle;
	(void) output;
	(void) output_size;
	(void) timeout_ms;
#endif
	fprintf(stderr, "[FAIL] MQTTX did not emit %s within %dms\n", needle,
	    timeout_ms);
	return false;
}

static bool
rule_response_has(const char *response, const char *status, int code)
{
	char code_text[32];

	if (response == NULL || strstr(response, status) == NULL) {
		fprintf(stderr, "[FAIL] rule API status mismatch; response: %s\n",
		    response == NULL ? "<null>" : response);
		return false;
	}
	snprintf(code_text, sizeof(code_text), "\"code\":%d", code);
	if (strstr(response, code_text) == NULL) {
		snprintf(code_text, sizeof(code_text), "\"code\": %d", code);
	}
	if (strstr(response, code_text) == NULL) {
		fprintf(stderr,
		    "[FAIL] rule API result mismatch; expected code %d; response: %s\n",
		    code, response);
		return false;
	}
	return true;
}

static bool
wait_for_rule_api(uint16_t rest_port)
{
	char request[256];

	snprintf(request, sizeof(request),
	    "curl -sS -i --basic -u admin_test:pw_test "
	    "--connect-timeout 1 --max-time 2 "
	    "'http://127.0.0.1:%hu/api/v4'", rest_port);
	for (int i = 0; i < 40; ++i) {
		FILE *fd = popen(request, "r");
		char  response[512] = { 0 };

		if (fd != NULL) {
			(void) fread(response, 1, sizeof(response) - 1, fd);
			pclose(fd);
			if (strstr(response, RULE_HTTP_OK) != NULL) {
				return true;
			}
		}
		nng_msleep(100);
	}
	fprintf(stderr, "[FAIL] rule API did not become ready on 127.0.0.1:%hu\n",
	    rest_port);
	return false;
}

int
main(void)
{
	char        test_port[16];
	char        rule_request[2048];
	nng_thread *nmq      = NULL;

	if (!test_env_allows_network_binds() || !test_env_allows_port_bind(8081)) {
		fprintf(stderr, "skip: test environment disallows listening sockets\n");
		return 0;
	}
	if (!test_env_has_executable("curl")) {
		fprintf(stderr, "skip: curl not found in PATH\n");
		return 0;
	}
#ifdef SUPP_RULE_ENGINE
	if (!test_env_has_executable("mosquitto_pub") ||
	    !test_env_has_executable("mosquitto_sub")) {
		fprintf(stderr,
		    "skip: required MQTT clients not found in PATH\n");
		return 0;
	}
#endif
	snprintf(test_port, sizeof(test_port), "%s", test_env_test_port_text());
	assert(nng_thread_create(&nmq, (void *) broker_start_with_conf,
	    (void *) nmq_conf) == 0);
	assert(wait_for_rule_api(8081));
	snprintf(rule_request, sizeof(rule_request),
	    "curl -sS -i --basic -u admin_test:pw_test --connect-timeout 1 "
	    "--max-time 5 'http://127.0.0.1:8081/api/v4/rules' -X POST -d "
	    "'{\"rawsql\":\"select * from \\\"rule/input\\\"\","
	    "\"actions\":[{\"name\":\"repub\",\"params\":{"
	    "\"topic\":\"rule/output\",\"address\":\"mqtt-tcp://127.0.0.1:%s\","
	    "\"clean_start\":true,\"proto_ver\":4,\"keepalive\":60}}],"
	    "\"description\":\"rule-engine-test\"}'",
	    test_port);
#ifndef SUPP_RULE_ENGINE
	assert(run_rule_request(rule_request, RULE_HTTP_OK, 111));
#else
	assert(run_rule_request(rule_request, RULE_HTTP_OK, 0));
	char sub_command[256];
	char pub_command[256];
	FILE *sub;
	FILE *pub;
	char  output[256] = { 0 };
	snprintf(sub_command, sizeof(sub_command),
	    "mosquitto_sub -h 127.0.0.1 -p %s -t rule/output -q 1 -C 1 -W 8",
	    test_port);
	snprintf(pub_command, sizeof(pub_command),
	    "mosquitto_pub -h 127.0.0.1 -p %s -t rule/input -m rule_message -q 1",
	    test_port);
	sub = test_env_popen(sub_command, "r");
	assert(sub != NULL);
	nng_msleep(300);
	pub = test_env_popen(pub_command, "r");
	assert(pub != NULL);
	assert(test_env_pclose(pub) == 0);
	assert(fgets(output, sizeof(output), sub) != NULL);
	assert(strstr(output, "rule_message") != NULL);
	assert(test_env_pclose(sub) == 0);
#endif

	broker_stop_for_test();
	assert(nmq != NULL);
	nng_thread_destroy(nmq);
	return 0;
}

static void
test_cleanup_preserves_reused_fd(bool nonblock)
{
	char *args[] = { "sh", "-c", "printf ready", NULL };
	int   outfd  = -1;
	pid_t pid;
	char  output[8] = { 0 };

	pid = nonblock ? popen_sub_with_cmd_nonblock(&outfd, args, "/bin/sh") :
	                 popen_with_cmd(&outfd, args, "/bin/sh");
	assert(pid > 0);
	assert(outfd >= 0);
	if (nonblock) {
		assert(test_env_wait_for_output(outfd, output, sizeof(output), 1000, 10));
	} else {
		assert(read(outfd, output, sizeof(output)) > 0);
	}
	close(outfd);

	int reused_fd = open("/dev/null", O_RDONLY);
	assert(reused_fd == outfd);

	test_env_test_cleanup();
	assert(fcntl(reused_fd, F_GETFD) != -1);
	close(reused_fd);
}

static void
test_child_closes_original_write_fd(bool nonblock)
{
	char *args[] = { "sh", "-c", "exec 1>&-; exec 2>&-; sleep 1", NULL };
	struct pollfd pollfd;
	int           outfd = -1;
	pid_t         pid;
	char          byte;

	pid = nonblock ? popen_sub_with_cmd_nonblock(&outfd, args, "/bin/sh") :
	                 popen_with_cmd(&outfd, args, "/bin/sh");
	assert(pid > 0);
	assert(outfd >= 0);
	pollfd.fd     = outfd;
	pollfd.events = POLLIN | POLLHUP;
	assert(poll(&pollfd, 1, 500) > 0);
	assert(read(outfd, &byte, sizeof(byte)) == 0);
	close(outfd);
	test_env_test_cleanup();
}

static void
test_reap_failed_popen_child(void)
{
	pid_t pid = fork();
	int   status;

	assert(pid >= 0);
	if (pid == 0) {
		for (;;) {
			pause();
		}
	}

	test_env_kill_and_reap(pid);
	errno = 0;
	assert(waitpid(pid, &status, WNOHANG) == -1);
	assert(errno == ECHILD);
}

int
main()
{
	test_cleanup_preserves_reused_fd(false);
	test_cleanup_preserves_reused_fd(true);
	test_child_closes_original_write_fd(false);
	test_child_closes_original_write_fd(true);
	test_reap_failed_popen_child();
	return 0;
}

