main()
{
	return 0;
}

static void
broker_release_workers(
    conf *nanomq_conf, struct work **works, uint64_t num_work, bool is_testing,
    nng_socket broker_sock, nng_socket inproc_sock)
{
	if (works == NULL || num_work == 0) {
		return;
	}
	if (is_testing) {
		// Bridge disconnect callbacks retain config until their NNG pipes finish
		// reaping. Keep the test process ownership model for bridge suites.
		if (nanomq_conf->bridge.count == 0 &&
		    nanomq_conf->aws_bridge.count == 0) {
			nng_close(broker_sock);
			nng_close(inproc_sock);
			nng_msleep(50);
		}
		return;
	}
#if defined(SUPP_RULE_ENGINE) && defined(FDB_SUPPORT)
	if (nanomq_conf->rule_eng.option & RULE_ENG_FDB) {
		fdb_database_destroy(nanomq_conf->rule_eng.rdb[1]);
		fdb_stop_network();
	}
#endif
	conf *conf = works[0]->config;

	for (size_t t = 0; t < conf->bridge.count; t++) {
		conf_bridge_node *node = conf->bridge.nodes[t];
		size_t            aio_count = conf->total_ctx;

		for (size_t i = 0; i < aio_count; i++) {
			nng_aio_stop(node->bridge_aio[i]);
		}
		if (node->resend_aio != NULL) {
			nng_aio_stop(node->resend_aio);
		}
		for (size_t i = 0; i < aio_count; i++) {
			nng_aio_free(node->bridge_aio[i]);
		}
		nng_free(node->bridge_aio, aio_count * sizeof(nng_aio *));
		nng_aio_free(node->resend_aio);
		node->resend_aio = NULL;
	}
	for (size_t i = 0; i < num_work; i++) {
		nng_free(works[i]->pipe_ct, sizeof(struct pipe_content));
		nng_free(works[i], sizeof(struct work));
	}
	nng_free(works, num_work * sizeof(struct work *));
}

void
broker_stop_for_test(void)
{
	keepRunning = 0;
}

static bool
bridge_properties_valid(cJSON *json_prop, bool allow_identifier)
{
	cJSON *identifier;

	if (json_prop == NULL) {
		return true;
	}
	if (!cJSON_IsObject(json_prop)) {
		return false;
	}
	identifier = cJSON_GetObjectItem(json_prop, "identifier");
	if (identifier == NULL) {
		return true;
	}
	return allow_identifier && cJSON_IsNumber(identifier) &&
	    identifier->valuedouble == (double) identifier->valueint &&
	    identifier->valueint > 0 && identifier->valueint <= 268435455;
}

static property *
bridge_properties_parse(cJSON *json_prop, bool include_identifier)
{
	if (json_prop == NULL) {
		return NULL;
	}
	if (!bridge_properties_valid(json_prop, include_identifier)) {
		return NULL;
	}

	property *prop_list = mqtt_property_alloc();
	if (prop_list == NULL) {
		return NULL;
	}

	cJSON *identifier = cJSON_GetObjectItem(json_prop, "identifier");
	if (include_identifier && cJSON_IsNumber(identifier)) {
		mqtt_property_append(prop_list,
		    mqtt_property_set_value_varint(
			SUBSCRIPTION_IDENTIFIER, identifier->valueint));
	}

	cJSON *up_array = cJSON_GetObjectItem(json_prop, "user_properties");
	if (cJSON_IsArray(up_array)) {
		cJSON *up_item = NULL;
		cJSON_ArrayForEach(up_item, up_array)
		{
			cJSON *key_item = cJSON_GetObjectItem(up_item, "key");
			cJSON *value_item = cJSON_GetObjectItem(up_item, "value");
			if (!cJSON_IsString(key_item) ||
			    !cJSON_IsString(value_item)) {
				continue;
			}
			mqtt_property_append(prop_list,
			    mqtt_property_set_value_strpair(
				USER_PROPERTY, key_item->valuestring,
				strlen(key_item->valuestring),
				value_item->valuestring,
				strlen(value_item->valuestring), true));
		}
	}

	return prop_list;
}

static properties_type
will_properties_type_parse(int val)
{
	properties_type prop_id = 0;

	switch (val) {
	case OPT_WILL_PAYLOAD_FORMAT_INDICATOR:
		prop_id = PAYLOAD_FORMAT_INDICATOR;
		break;
	case OPT_WILL_MESSAGE_EXPIRY_INTERVAL:
		prop_id = MESSAGE_EXPIRY_INTERVAL;
		break;
	case OPT_WILL_CONTENT_TYPE:
		prop_id = CONTENT_TYPE;
		break;
	case OPT_WILL_RESPONSE_TOPIC:
		prop_id = RESPONSE_TOPIC;
		break;
	case OPT_WILL_CORRELATION_DATA:
		prop_id = CORRELATION_DATA;
		break;
	case OPT_WILL_DELAY_INTERVAL:
		prop_id = WILL_DELAY_INTERVAL;
		break;
	case OPT_WILL_USER_PROPERTY:
		prop_id = USER_PROPERTY;
		break;
	default:
		break;
	}

	return prop_id;
}

static int
will_properties_parse(int argc, char **argv, client_opts *opts)
{
	int   idx = 1;
	char *arg;
	int   val;
	int   rv;

	uint8_t  u8;
	uint16_t u16;
	uint32_t u32;
	char *   str;
	char *   value;
	uint8_t *bin;
	property *prop_item;

	while ((rv = nng_opts_parse(
	            argc - 1, argv + 1, cmd_opts, &val, &arg, &idx)) == 0) {
		properties_type prop_id = will_properties_type_parse(val);
		if (prop_id == 0)
			continue;

		if (opts->will_properties == NULL) {
			opts->will_properties = mqtt_property_alloc();
		}

		property_type_enum type = mqtt_property_get_value_type(prop_id);
		switch (type) {
		case U8:
			u8        = (uint8_t) long_arg(arg, 0, UINT8_MAX);
			prop_item = mqtt_property_set_value_u8(prop_id, u8);
			break;
		case U16:
			u16       = (uint16_t) long_arg(arg, 0, UINT16_MAX);
			prop_item = mqtt_property_set_value_u16(prop_id, u16);
			break;
		case U32:
			u32       = (uint32_t) long_arg(arg, 0, UINT32_MAX);
			prop_item = mqtt_property_set_value_u32(prop_id, u32);
			break;
		case VARINT:
			u32 = (uint32_t) long_arg(arg, 0, UINT32_MAX);
			prop_item = mqtt_property_set_value_varint(prop_id, u32);
			break;
		case BINARY:
			bin       = (uint8_t *) arg;
			prop_item = mqtt_property_set_value_binary(
			    prop_id, bin, strlen(arg), true);
			break;
		case STR:
			str       = arg;
			prop_item = mqtt_property_set_value_str(
			    prop_id, str, strlen(str), true);
			break;
		case STR_PAIR:
			str   = nng_zalloc(strlen(arg) + 1);
			value = nng_zalloc(strlen(arg) + 1);
			int ret = sscanf(arg, "%[^=]=%s", str, value);
			if (ret != 2) {
				nng_free(str, strlen(str) + 1);
				nng_free(value, strlen(value) + 1);
				fatal("Invalid string pair: '%s', "
				      "Require "
				      "format: 'key=value'", arg);
			} else {
				prop_item = mqtt_property_set_value_strpair(
				    prop_id, str, strlen(str), value,
				    strlen(value), true);
				nng_free(str, strlen(str) + 1);
				nng_free(value, strlen(value) + 1);
			}
			break;
		default:
			fatal("Unknown property: %s", argv[idx]);
			break;
		}
		mqtt_property_append(opts->will_properties, prop_item);
	}

	switch (rv) {
	case NNG_EINVAL:
		fatal("Option %s is invalid.", argv[idx]);
		break;
	case NNG_EAMBIGUOUS:
		fatal("Option %s is ambiguous (specify in full).", argv[idx]);
		break;
	case NNG_ENOARG:
		fatal("Option %s requires argument.", argv[idx]);
		break;
	default:
		break;
	}

	return rv;
}

static void
run_clients_query_regression_cases(void)
{
	static const char *cases[] = {
		"/api/v4/clients?proto_ver=0",
		"/api/v4/clients?proto_ver=6",
		"/api/v4/clients?clean_start=maybe",
		"/api/v4/clients?foo=bar",
		"/api/v4/clients?proto_ver=3",
		"/api/v4/clients?proto_ver=4",
		"/api/v4/clients?proto_ver=5",
	};

	g_conf.http_server.auth_type = NONE_AUTH;
	set_http_server_conf(&g_conf.http_server);

	nng_socket sock = { 0 };
	g_conf.http_server.broker_sock = &sock;

	for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
		http_msg req = { 0 };
		put_http_msg(
		    &req, "application/json", "GET", cases[i], NULL, "", 0);

		http_msg resp = process_request(&req, &g_conf.http_server, &sock);
		destory_http_msg(&resp);
		destory_http_msg(&req);
	}
}

void buildLocalMatrix(const GltfNode* gn, GLfloat result[16])
{
GLfloat T[16], R[16], S[16], RS[16];

if (gn->hasMatrix)
{
memcpy(result, gn->localMatrix, 64);
return;
}

glusMatrix4x4Identityf(T);
T[12] = gn->translation[0];
T[13] = gn->translation[1];
T[14] = gn->translation[2];

glusQuaternionGetMatrix4x4f(R, (GLUSfloat*)gn->rotation);

glusMatrix4x4Identityf(S);
S[0]  = gn->scale[0];
S[5]  = gn->scale[1];
S[10] = gn->scale[2];

glusMatrix4x4Multiplyf(RS, R, S);
glusMatrix4x4Multiplyf(result, T, RS);
}

// Re

void computeWorldMatrix(GLint nodeIdx, const GLfloat parentWorld[16])
{
GLfloat local[16];
GLint   ci;

buildLocalMatrix(&g_nodes[nodeIdx], local);
glusMatrix4x4Multiplyf(g_nodes[nodeIdx].worldMatrix, parentWorld, local);

for (ci = 0; ci < g_nodes[nodeIdx].childCount; ci++)
computeWorldMatrix(g_nodes[nodeIdx].childIndices[ci],
                   g_nodes[nodeIdx].worldMatrix);
}

// Co

void buildNodeHierarchy(const cgltf_data* data)
{
GLint ni, ci, i;

g_numNodes = (GLint)data->nodes_count;
if (g_numNodes > MAX_NODES)
{
printf("Warning: node count %d exceeds MAX_NODES %d, clamping\n",
       g_numNodes, MAX_NODES);
g_numNodes = MAX_NODES;
}

for (ni = 0; ni < g_numNodes; ni++)
{
const cgltf_node* node = &data->nodes[ni];
GltfNode*         gn   = &g_nodes[ni];

gn->translation[0] = gn->translation[1] = gn->translation[2] = 0.0f;
gn->rotation[0] = gn->rotation[1] = gn->rotation[2] = 0.0f;
gn->rotation[3] = 1.0f;
gn->scale[0] = gn->scale[1] = gn->scale[2] = 1.0f;
gn->hasMatrix  = 0;
gn->parentIdx  = -1;
gn->childCount = 0;
glusMatrix4x4Identityf(gn->worldMatrix);

if (node->has_matrix)
{
gn->hasMatrix = 1;
for (i = 0; i < 16; i++)
gn->localMatrix[i] = (GLfloat)node->matrix[i];
}
else
{
if (node->has_translation)
{
gn->translation[0] = (GLfloat)node->translation[0];
gn->translation[1] = (GLfloat)node->translation[1];
gn->translation[2] = (GLfloat)node->translation[2];
}
if (node->has_rotation)
{
gn->rotation[0] = (GLfloat)node->rotation[0];
gn->rotation[1] = (GLfloat)node->rotation[1];
gn->rotation[2] = (GLfloat)node->rotation[2];
gn->rotation[3] = (GLfloat)node->rotation[3];
}
if (node->has_scale)
{
gn->scale[0] = (GLfloat)node->scale[0];
gn->scale[1] = (GLfloat)node->scale[1];
gn->scale[2] = (GLfloat)node->scale[2];
}
}

gn->childCount = (GLint)node->children_count;
if (gn->childCount > MAX_NODE_CHILDREN)
{
printf("Warning: node %d has %d children, clamping to %d\n",
       ni, gn->childCount, MAX_NODE_CHILDREN);
gn->childCount = MAX_NODE_CHILDREN;
}
for (ci = 0; ci < gn->childCount; ci++)
gn->childIndices[ci] = (GLint)(node->children[ci] - data->nodes);
}

// Set parent indices from child lists.
for (ni = 0; ni < g_numNodes; ni++)
for (ci = 0; ci < g_nodes[ni].childCount; ci++)
{
GLint childIdx = g_nodes[ni].childIndices[ci];
if (childIdx >= 0 && childIdx < g_numNodes)
g_nodes[childIdx].parentIdx = ni;
}
}

// Fi

void buildRootNodes(const cgltf_data* data)
{
GLint ri, ni;

g_numRootNodes = 0;

if (data->scene)
{
g_numRootNodes = (GLint)data->scene->nodes_count;
for (ri = 0; ri < g_numRootNodes; ri++)
g_rootNodes[ri] = (GLint)(data->scene->nodes[ri] - data->nodes);
}
else
{
for (ni = 0; ni < g_numNodes; ni++)
if (g_nodes[ni].parentIdx == -1 && g_numRootNodes < MAX_NODES)
g_rootNodes[g_numRootNodes++] = ni;
}
}

// Re

void computeAllWorldMatrices(void)
{
GLfloat identity[16];
GLint   ri;

glusMatrix4x4Identityf(identity);
for (ri = 0; ri < g_numRootNodes; ri++)
computeWorldMatrix(g_rootNodes[ri], identity);
}

//
//

void loadSkins(const cgltf_data* data)
{
GLint si, ji;

g_numSkins = (GLint)data->skins_count;
if (g_numSkins > MAX_SKINS)
{
printf("Warning: skin count %d exceeds MAX_SKINS %d, clamping\n",
       g_numSkins, MAX_SKINS);
g_numSkins = MAX_SKINS;
}

for (si = 0; si < g_numSkins; si++)
{
const cgltf_skin* skin = &data->skins[si];
GltfSkin*         gs   = &g_skins[si];

gs->jointCount = (GLint)skin->joints_count;
if (gs->jointCount > MAX_JOINTS)
{
printf("Warning: skin %d has %d joints, clamping to %d\n",
       si, gs->jointCount, MAX_JOINTS);
gs->jointCount = MAX_JOINTS;
}

for (ji = 0; ji < gs->jointCount; ji++)
gs->jointNodeIndices[ji] = (GLint)(skin->joints[ji] - data->nodes);

// Default IBM = identity; overwrite when accessor is present.
for (ji = 0; ji < gs->jointCount; ji++)
glusMatrix4x4Identityf(&gs->inverseBindMatrices[ji * 16]);

if (skin->inverse_bind_matrices)
{
GLint accessorCount = (GLint)skin->inverse_bind_matrices->count;
GLint readCount = (accessorCount < gs->jointCount) ? accessorCount : gs->jointCount;
for (ji = 0; ji < readCount; ji++)
cgltf_accessor_read_float(skin->inverse_bind_matrices, ji,
                          &gs->inverseBindMatrices[ji * 16], 16);
}
}
}

// Re

void computeJointMatrices(void)
{
GLint si, ji;

for (si = 0; si < g_numSkins; si++)
{
GltfSkin* gs = &g_skins[si];
for (ji = 0; ji < gs->jointCount; ji++)
{
GLint jni = gs->jointNodeIndices[ji];
glusMatrix4x4Multiplyf(&gs->jointMatrices[ji * 16],
                       g_nodes[jni].worldMatrix,
                       &gs->inverseBindMatrices[ji * 16]);
}
}
}

//
//

void loadAnimations(const cgltf_data* data)
{
GLint    ai, chi, kfi;
GLfloat  maxTime;

maxTime           = 0.0f;
g_numAnimChannels = 0;

for (ai = 0; ai < (GLint)data->animations_count; ai++)
{
const cgltf_animation* anim = &data->animations[ai];

for (chi = 0; chi < (GLint)anim->channels_count; chi++)
{
const cgltf_animation_channel* ch      = &anim->channels[chi];
const cgltf_animation_sampler* sampler = ch->sampler;
AnimChannel* ac;
GLint path, interp, components, outputCount;

if (!ch->target_node) continue;
if (g_numAnimChannels >= MAX_ANIM_CHANNELS) break;

switch (ch->target_path)
{
case cgltf_animation_path_type_translation: path = ANIM_PATH_TRANSLATION; break;
case cgltf_animation_path_type_rotation:    path = ANIM_PATH_ROTATION;    break;
case cgltf_animation_path_type_scale:       path = ANIM_PATH_SCALE;       break;
default: continue;
}

switch (sampler->interpolation)
{
case cgltf_interpolation_type_step:         interp = GLUS_ANIMATION_STEP;        break;
case cgltf_interpolation_type_cubic_spline: interp = GLUS_ANIMATION_CUBICSPLINE; break;
default:                                    interp = GLUS_ANIMATION_LINEAR;      break;
}

ac              = &g_animChannels[g_numAnimChannels++];
ac->nodeIdx     = (GLint)(ch->target_node - data->nodes);
ac->path        = path;
ac->interpolation = interp;
ac->count       = (GLint)sampler->input->count;
components      = (path == ANIM_PATH_ROTATION) ? 4 : 3;
outputCount     = (GLint)sampler->output->count;

ac->times  = (GLfloat*)malloc((size_t)ac->count * sizeof(GLfloat));
ac->values = (GLfloat*)malloc((size_t)outputCount * components * sizeof(GLfloat));

for (kfi = 0; kfi < ac->count; kfi++)
cgltf_accessor_read_float(sampler->input, kfi, &ac->times[kfi], 1);

for (kfi = 0; kfi < outputCount; kfi++)
cgltf_accessor_read_float(sampler->output, kfi,
                          &ac->values[kfi * components], components);

if (ac->count > 0 && ac->times[ac->count - 1] > maxTime)
maxTime = ac->times[ac->count - 1];
}
}

g_animDuration = maxTime;
}

ic GLUSint iblMipLevels(GLUSint size)
{
	GLUSint levels = 1;
	while (size > 1) { size >>= 1; ++levels; }
	return levels;
}

//

GLUSboolean buildSourceCubemap(GLUSuint *cubemapOut, GLUSuint panoramaTexture, GLUSint size)
{
	GLUSprogram program;
	GLUSuint    fbo, vao, tex;
	GLUSint     locPanorama, locFace;
	GLUSint     face;
	GLUSint     savedViewport[4];

	if (!iblBuildProgram(&program, "glus_ibl.vert.glsl", "glus_ibl_background.frag.glsl"))
	{
		return GLUS_FALSE;
	}

	locPanorama = glGetUniformLocation(program.program, "u_panoramaTexture");
	locFace     = glGetUniformLocation(program.program, "u_face");

	glGenTextures(1, &tex);
	glBindTexture(GL_TEXTURE_CUBE_MAP, tex);
	glTexStorage2D(GL_TEXTURE_CUBE_MAP, iblMipLevels(size), GL_RGB32F, size, size);
	glTexParameteri(GL_TEXTURE_CUBE_MAP, GL_TEXTURE_MIN_FILTER, GL_LINEAR_MIPMAP_LINEAR);
	glTexParameteri(GL_TEXTURE_CUBE_MAP, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
	glTexParameteri(GL_TEXTURE_CUBE_MAP, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
	glTexParameteri(GL_TEXTURE_CUBE_MAP, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
	glTexParameteri(GL_TEXTURE_CUBE_MAP, GL_TEXTURE_WRAP_R, GL_CLAMP_TO_EDGE);
	glBindTexture(GL_TEXTURE_CUBE_MAP, 0);

	glGenFramebuffers(1, &fbo);
	glGenVertexArrays(1, &vao);
	glBindVertexArray(vao);

	glUseProgram(program.program);

	glActiveTexture(GL_TEXTURE0);
	glBindTexture(GL_TEXTURE_2D, panoramaTexture);
	glUniform1i(locPanorama, 0);

	glBindFramebuffer(GL_FRAMEBUFFER, fbo);
	glGetIntegerv(GL_VIEWPORT, savedViewport);
	glViewport(0, 0, size, size);

	for (face = 0; face < 6; face++)
	{
		glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0,
		                       GL_TEXTURE_CUBE_MAP_POSITIVE_X + face, tex, 0);
		glUniform1i(locFace, face);
		glDrawArrays(GL_TRIANGLE_STRIP, 0, 4);
	}

	// Generate the full mip chain so specular/diffuse shaders can use textureLod.
	glBindTexture(GL_TEXTURE_CUBE_MAP, tex);
	glGenerateMipmap(GL_TEXTURE_CUBE_MAP);
	glBindTexture(GL_TEXTURE_CUBE_MAP, 0);

	glBindFramebuffer(GL_FRAMEBUFFER, 0);
	glBindVertexArray(0);
	glUseProgram(0);

	glDeleteFramebuffers(1, &fbo);
	glDeleteVertexArrays(1, &vao);
	glusProgramDestroy(&program);

	glViewport(savedViewport[0], savedViewport[1], savedViewport[2], savedViewport[3]);

	*cubemapOut = tex;
	return GLUS_TRUE;
}

	GLU

Texture1x1(GLubyte r, GLubyte g, GLubyte b, GLubyte a)
{
GLuint  tex;
GLubyte data[4];

data[0] = r; data[1] = g; data[2] = b; data[3] = a;

glGenTextures(1, &tex);
glBindTexture(GL_TEXTURE_2D, tex);
glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA8, 1, 1, 0, GL_RGBA, GL_UNSIGNED_BYTE, data);
glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
return tex;
}

// Register a text

ture(GLuint tex)
{
if (g_numTextures < MAX_TEXTURES)
g_textures[g_numTextures++] = tex;
}

// Load a 2-D text

ageTexture(cgltf_image* image, const GLUSchar* basePath, GLint sRGB)
{
GLint          w, h, comp;
GLubyte*       pixels;
GLuint         tex;
GLenum         internalFmt;
GLint          i;
GLUSchar       path[1024];
const GLubyte* embeddedBuf;

if (!image)
return g_defaultWhiteTexture;

// Check cache
for (i = 0; i < g_numCacheEntries; i++)
if (g_imageCache[i].image == image)
return g_imageCache[i].texture;

pixels      = NULL;
embeddedBuf = NULL;

if (image->buffer_view)
{
// Embedded image data (GLB)
embeddedBuf = (const GLubyte*)image->buffer_view->buffer->data
            + image->buffer_view->offset;
pixels = stbi_load_from_memory(embeddedBuf, (int)image->buffer_view->size,
                               &w, &h, &comp, 4);
}
else if (image->uri && strncmp(image->uri, "data:", 5) != 0)
{
// External file
if (basePath[0])
snprintf(path, sizeof(path), "%s%s", basePath, image->uri);
else
{
strncpy(path, image->uri, sizeof(path) - 1);
path[sizeof(path) - 1] = '\0';
}
pixels = stbi_load(path, &w, &h, &comp, 4);
}

if (!pixels)
{
printf("Warning: failed to load image '%s'\n",
       image->uri ? image->uri : "(embedded)");
return g_defaultWhiteTexture;
}

glGenTextures(1, &tex);
glBindTexture(GL_TEXTURE_2D, tex);

internalFmt = sRGB ? GL_SRGB8_ALPHA8 : GL_RGBA8;
glTexImage2D(GL_TEXTURE_2D, 0, internalFmt, w, h, 0,
             GL_RGBA, GL_UNSIGNED_BYTE, pixels);
glGenerateMipmap(GL_TEXTURE_2D);
glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR_MIPMAP_LINEAR);
glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_REPEAT);
glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_REPEAT);

stbi_image_free(pixels);

trackTexture(tex);

if (g_numCacheEntries < MAX_IMAGE_CACHE)
{
g_imageCache[g_numCacheEntries].image   = image;
g_imageCache[g_numCacheEntries].texture = tex;
g_numCacheEntries++;
}

return tex;
}

// Apply sampler p

fSampler(const cgltf_sampler* sampler)
{
if (!sampler) return;
if (sampler->min_filter)
glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, sampler->min_filter);
if (sampler->mag_filter)
glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, sampler->mag_filter);
if (sampler->wrap_s)
glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, sampler->wrap_s);
if (sampler->wrap_t)
glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, sampler->wrap_t);
}

//
// Scene bounds

undsWithPoint(const GLfloat p[3])
{
GLint i;
for (i = 0; i < 3; i++)
{
if (p[i] < g_sceneMin[i]) g_sceneMin[i] = p[i];
if (p[i] > g_sceneMax[i]) g_sceneMax[i] = p[i];
}
}

// Transform all 8

undsAABB(const GLfloat minP[3], const GLfloat maxP[3],
                              const GLfloat modelMatrix[16])
{
GLint  cx, cy, cz;
for (cx = 0; cx < 2; cx++)
for (cy = 0; cy < 2; cy++)
for (cz = 0; cz < 2; cz++)
{
GLfloat corner[4];
GLfloat world[4];
GLfloat wp3[3];

corner[0] = cx ? maxP[0] : minP[0];
corner[1] = cy ? maxP[1] : minP[1];
corner[2] = cz ? maxP[2] : minP[2];
corner[3] = 1.0f;

glusMatrix4x4MultiplyPoint4f(world, modelMatrix, corner);

wp3[0] = world[0]; wp3[1] = world[1]; wp3[2] = world[2];
expandBoundsWithPoint(wp3);
}
}

//
// glTF scene l

ode(const cgltf_data* data, const cgltf_node* node,
                        const GLfloat parentMatrix[16], const GLUSchar* basePath)
{
GLfloat localMatrix[16];
GLfloat worldMatrix[16];
GLint   ci;
GLint   i;
GLfloat T[16], R[16], S[16], RS[16];
GLfloat q[4];

glusMatrix4x4Identityf(localMatrix);

if (node->has_matrix)
{
// cgltf stores column-major — same layout as GLUS.
for (i = 0; i < 16; i++)
localMatrix[i] = (GLfloat)node->matrix[i];
}
else
{
// Compose TRS
glusMatrix4x4Identityf(T);
glusMatrix4x4Identityf(R);
glusMatrix4x4Identityf(S);

if (node->has_translation)
{
T[12] = (GLfloat)node->translation[0];
T[13] = (GLfloat)node->translation[1];
T[14] = (GLfloat)node->translation[2];
}

if (node->has_rotation)
{
// cgltf quaternion is [x,y,z,w] — same as GLUS.
q[0] = (GLfloat)node->rotation[0];
q[1] = (GLfloat)node->rotation[1];
q[2] = (GLfloat)node->rotation[2];
q[3] = (GLfloat)node->rotation[3];
glusQuaternionGetMatrix4x4f(R, q);
}

if (node->has_scale)
{
S[0]  = (GLfloat)node->scale[0];
S[5]  = (GLfloat)node->scale[1];
S[10] = (GLfloat)node->scale[2];
}

glusMatrix4x4Multiplyf(RS, R, S);
glusMatrix4x4Multiplyf(localMatrix, T, RS);
}

glusMatrix4x4Multiplyf(worldMatrix, parentMatrix, localMatrix);

if (node->mesh)
processMesh(data, node->mesh, worldMatrix, basePath);

for (ci = 0; ci < (GLint)node->children_count; ci++)
processNode(data, node->children[ci], worldMatrix, basePath);
}

//
// GLUS callbacks
/

idth, GLUSint height)
{
if (height == 0) height = 1;
g_windowWidth  = width;
g_windowHeight = height;

// (Re-)create MSAA framebuffer.
if (g_msaaFBO)
{
glDeleteFramebuffers(1, &g_msaaFBO);
glDeleteTextures(1, &g_msaaColor);
glDeleteRenderbuffers(1, &g_msaaDepth);
}

glGenFramebuffers(1, &g_msaaFBO);
glBindFramebuffer(GL_FRAMEBUFFER, g_msaaFBO);

glGenTextures(1, &g_msaaColor);
glBindTexture(GL_TEXTURE_2D_MULTISAMPLE, g_msaaColor);
glTexImage2DMultisample(GL_TEXTURE_2D_MULTISAMPLE, MSAA_SAMPLES,
                        GL_RGBA16F, width, height, GL_TRUE);
glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0,
                       GL_TEXTURE_2D_MULTISAMPLE, g_msaaColor, 0);

glGenRenderbuffers(1, &g_msaaDepth);
glBindRenderbuffer(GL_RENDERBUFFER, g_msaaDepth);
glRenderbufferStorageMultisample(GL_RENDERBUFFER, MSAA_SAMPLES,
                                 GL_DEPTH_COMPONENT24, width, height);
glFramebufferRenderbuffer(GL_FRAMEBUFFER, GL_DEPTH_ATTACHMENT,
                          GL_RENDERBUFFER, g_msaaDepth);

glBindFramebuffer(GL_FRAMEBUFFER, 0);
}

// Helper: bind all mate

aterial(const GltfPrimitive* gp)
{
glActiveTexture(GL_TEXTURE0); glBindTexture(GL_TEXTURE_2D, gp->baseColorTexture);
glActiveTexture(GL_TEXTURE1); glBindTexture(GL_TEXTURE_2D, gp->metallicRoughnessTexture);
glActiveTexture(GL_TEXTURE2); glBindTexture(GL_TEXTURE_2D, gp->normalTexture);
glActiveTexture(GL_TEXTURE3); glBindTexture(GL_TEXTURE_2D, gp->occlusionTexture);
glActiveTexture(GL_TEXTURE4); glBindTexture(GL_TEXTURE_2D, gp->emissiveTexture);

glUniformMatrix4fv(g_u_modelMatrix,  1, GL_FALSE, gp->modelMatrix);
glUniformMatrix3fv(g_u_normalMatrix, 1, GL_FALSE, gp->normalMatrix);
glUniform4fv(g_u_baseColorFactor, 1, gp->baseColorFactor);
glUniform1f(g_u_metallicFactor,    gp->metallicFactor);
glUniform1f(g_u_roughnessFactor,   gp->roughnessFactor);
glUniform3fv(g_u_emissiveFactor, 1, gp->emissiveFactor);
glUniform1f(g_u_occlusionStrength, gp->occlusionStrength);
glUniform1f(g_u_alphaCutoff,       gp->alphaCutoff);
glUniform1i(g_u_alphaMode,         gp->alphaMode);
glUniform1i(g_u_hasNormalMap,      gp->hasNormalMap);
}

static void drawPrimitiv

const GltfPrimitive* gp)
{
glBindVertexArray(gp->vao);
if (gp->ibo)
glDrawElements(GL_TRIANGLES, gp->indexCount, gp->indexType, 0);
else
glDrawArrays(GL_TRIANGLES, 0, gp->vertexCount);
glBindVertexArray(0);
}

GLUSboolean update(GLUSf

at time)
{
GLfloat rad;
GLfloat eyeX, eyeY, eyeZ;
GLfloat nearPlane, farPlane;
GLfloat viewMatrix[16];
GLfloat projMatrix[16];
GLfloat bgViewMatrix[16];
GLfloat bgVPMatrix[16];
GLint   i;

if (g_quit) return GLUS_FALSE;
if (!g_msaaFBO) return GLUS_TRUE;  // reshape not yet called

// --- Orbit camera ---
g_orbitAngle += g_orbitSpeed * time;
if (g_orbitAngle >= 360.0f) g_orbitAngle -= 360.0f;

rad  = g_orbitAngle * 3.14159265f / 180.0f;
eyeX = g_sceneCenterX + g_orbitRadius * sinf(rad);
eyeY = g_cameraY;
eyeZ = g_sceneCenterZ + g_orbitRadius * cosf(rad);

g_eye[0] = eyeX; g_eye[1] = eyeY; g_eye[2] = eyeZ; g_eye[3] = 1.0f;

nearPlane = g_sceneRadius * 0.005f;
farPlane  = g_orbitRadius + g_sceneRadius * 3.0f + 600.0f;
if (nearPlane < 0.001f) nearPlane = 0.001f;

glusMatrix4x4LookAtf(viewMatrix, eyeX, eyeY, eyeZ,
                     g_sceneCenterX, g_sceneCenterY, g_sceneCenterZ,
                     0.0f, 1.0f, 0.0f);
glusMatrix4x4Perspectivef(projMatrix, 45.0f,
                          (GLfloat)g_windowWidth / (GLfloat)g_windowHeight,
                          nearPlane, farPlane);
glusMatrix4x4Multiplyf(g_viewProjectionMatrix, projMatrix, viewMatrix);

// Rotation-only VP for background: strip camera translation so sphere is always centered on camera.
memcpy(bgViewMatrix, viewMatrix, 16 * sizeof(GLfloat));
bgViewMatrix[12] = 0.0f;
bgViewMatrix[13] = 0.0f;
bgViewMatrix[14] = 0.0f;
glusMatrix4x4Multiplyf(bgVPMatrix, projMatrix, bgViewMatrix);

// --- Render into MSAA FBO ---
glBindFramebuffer(GL_FRAMEBUFFER, g_msaaFBO);
glViewport(0, 0, g_windowWidth, g_windowHeight);
glEnable(GL_MULTISAMPLE);
glEnable(GL_DEPTH_TEST);
glDepthMask(GL_TRUE);
glDisable(GL_BLEND);
glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

// --- Background sphere (inside-facing, no depth write) ---
glFrontFace(GL_CW);
glDisable(GL_CULL_FACE);
glDepthMask(GL_FALSE);
glDepthFunc(GL_LEQUAL);
glUseProgram(g_bgProg.program);
glUniformMatrix4fv(g_u_vpMatrix_bg, 1, GL_FALSE, bgVPMatrix);
glActiveTexture(GL_TEXTURE0);
glBindTexture(GL_TEXTURE_CUBE_MAP, g_bgCubemapTexture);
glBindVertexArray(g_bgVAO);
glDrawElements(GL_TRIANGLES, g_bgIndexCount, GL_UNSIGNED_INT, 0);
glBindVertexArray(0);
glDepthFunc(GL_LESS);
glFrontFace(GL_CCW);
glDepthMask(GL_TRUE);

// --- PBR IBL textures on units 5-7 (persistent per frame) ---
glActiveTexture(GL_TEXTURE5);
glBindTexture(GL_TEXTURE_CUBE_MAP_ARRAY, g_specularTexture);
glActiveTexture(GL_TEXTURE6);
glBindTexture(GL_TEXTURE_CUBE_MAP, g_diffuseTexture);
glActiveTexture(GL_TEXTURE7);
glBindTexture(GL_TEXTURE_2D, g_brdfLutTexture);

glUseProgram(g_pbrProg.program);
glUniformMatrix4fv(g_u_vpMatrix, 1, GL_FALSE, g_viewProjectionMatrix);
glUniform4fv(g_u_eye_pbr, 1, g_eye);

// --- Pass A: Opaque + Mask ---
glEnable(GL_DEPTH_TEST);
for (i = 0; i < g_numPrimitives; i++)
{
const GltfPrimitive* gp = &g_primitives[i];
if (gp->alphaMode == 2) continue;  // skip blend

if (gp->doubleSided) glDisable(GL_CULL_FACE);
else                 glEnable(GL_CULL_FACE);

bindPrimitiveMaterial(gp);
drawPrimitive(gp);
}

// --- Pass B: Blend ---
glEnable(GL_BLEND);
glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
glDepthMask(GL_FALSE);

for (i = 0; i < g_numPrimitives; i++)
{
const GltfPrimitive* gp = &g_primitives[i];
if (gp->alphaMode != 2) continue;

if (gp->doubleSided) glDisable(GL_CULL_FACE);
else                 glEnable(GL_CULL_FACE);

bindPrimitiveMaterial(gp);
drawPrimitive(gp);
}

glDisable(GL_BLEND);
glDepthMask(GL_TRUE);
glEnable(GL_CULL_FACE);

// --- Fullscreen resolve: MSAA -> default FBO with tone-map ---
glBindFramebuffer(GL_FRAMEBUFFER, 0);
glViewport(0, 0, g_windowWidth, g_windowHeight);
glDisable(GL_DEPTH_TEST);
glDisable(GL_MULTISAMPLE);
glClear(GL_COLOR_BUFFER_BIT);

glUseProgram(g_fullscreenProg.program);
glUniform1f(g_u_exposure,    g_exposure);
glUniform1f(g_u_gamma,       g_gamma);
glUniform1i(g_u_msaaSamples, MSAA_SAMPLES);
glActiveTexture(GL_TEXTURE0);
glBindTexture(GL_TEXTURE_2D_MULTISAMPLE, g_msaaColor);
glBindVertexArray(g_fullscreenVAO);
glDrawArrays(GL_TRIANGLE_STRIP, 0, 4);
glBindVertexArray(0);

glEnable(GL_DEPTH_TEST);

return GLUS_TRUE;
}

GLUSvoid terminate(GLUSv

d)
{
GLint i;

// Primitives
for (i = 0; i < g_numPrimitives; i++)
{
GltfPrimitive* gp = &g_primitives[i];
glDeleteVertexArrays(1, &gp->vao);
glDeleteBuffers(1, &gp->vbo_pos);
glDeleteBuffers(1, &gp->vbo_nor);
glDeleteBuffers(1, &gp->vbo_tan);
glDeleteBuffers(1, &gp->vbo_uv0);
if (gp->ibo) glDeleteBuffers(1, &gp->ibo);
}

// Textures
for (i = 0; i < g_numTextures; i++)
glDeleteTextures(1, &g_textures[i]);
glDeleteTextures(1, &g_defaultWhiteTexture);
glDeleteTextures(1, &g_defaultNormalTexture);

// IBL
glDeleteTextures(1, &g_specularTexture);
glDeleteTextures(1, &g_diffuseTexture);
glDeleteTextures(1, &g_brdfLutTexture);
glDeleteTextures(1, &g_bgCubemapTexture);

// Background sphere
glDeleteVertexArrays(1, &g_bgVAO);
glDeleteBuffers(1, &g_bgVBO);
glDeleteBuffers(1, &g_bgIBO);

// VAOs
glDeleteVertexArrays(1, &g_fullscreenVAO);

// MSAA FBO
if (g_msaaFBO)
{
glDeleteFramebuffers(1, &g_msaaFBO);
glDeleteTextures(1, &g_msaaColor);
glDeleteRenderbuffers(1, &g_msaaDepth);
}

// Programs
glusProgramDestroy(&g_bgProg);
glusProgramDestroy(&g_fullscreenProg);
glusProgramDestroy(&g_pbrProg);
}

GLUSvoid key(const GLUSb

lean pressed, const GLUSint key)
{
if (!pressed) return;

switch (key)
{
case 256:  // Escape
case 'Q':
g_quit = 1;
break;
case 265:  // Arrow up   — camera higher
g_cameraY += g_sceneRadius * 0.1f;
break;
case 264:  // Arrow down — camera lower
g_cameraY -= g_sceneRadius * 0.1f;
break;
case 262:  // Arrow right — orbit faster
g_orbitSpeed += 5.0f;
break;
case 263:  // Arrow left  — orbit slower
g_orbitSpeed -= 5.0f;
if (g_orbitSpeed < 0.0f) g_orbitSpeed = 0.0f;
break;
case '+':
case '=':
g_orbitRadius *= 0.9f;
if (g_orbitRadius < g_sceneRadius * 0.2f)
g_orbitRadius = g_sceneRadius * 0.2f;
break;
case '-':
g_orbitRadius *= 1.1f;
break;
case 'E':
g_exposure *= 1.25f;
printf("Exposure: %.2f\n", g_exposure);
break;
case 'R':
g_exposure /= 1.25f;
printf("Exposure: %.2f\n", g_exposure);
break;
default:
break;
}
}

int main(int argc, char** argv)

EGLint eglConfigAttributes[] = {
EGL_RED_SIZE,        8,
EGL_GREEN_SIZE,      8,
EGL_BLUE_SIZE,       8,
EGL_DEPTH_SIZE,      24,
EGL_STENCIL_SIZE,    0,
EGL_RENDERABLE_TYPE, EGL_OPENGL_BIT,
EGL_NONE
};

EGLint eglContextAttributes[] = {
EGL_CONTEXT_MAJOR_VERSION,            4,
EGL_CONTEXT_MINOR_VERSION,            6,
EGL_CONTEXT_OPENGL_FORWARD_COMPATIBLE, EGL_TRUE,
EGL_CONTEXT_OPENGL_PROFILE_MASK,      EGL_CONTEXT_OPENGL_CORE_PROFILE_BIT,
EGL_NONE
};

g_gltfPath     = (argc > 1) ? argv[1] : "einstein/scene.gltf";
g_panoramaPath = (argc > 2) ? argv[2] : "doge2.hdr";

glusWindowSetInitFunc(init);
glusWindowSetReshapeFunc(reshape);
glusWindowSetUpdateFunc(update);
