if (!glusWindowCreate("Example 49 - glTF 2.0 PBR + IBL",
                      SCREEN_WIDTH, SCREEN_HEIGHT,
                      GLUS_FALSE, GLUS_FALSE,
                      eglConfigAttributes, eglContextAttributes, 0))
