static int
rtsp_incomplete(uint8_t *in, size_t in_len)
{
  const char *hdr_end;
  const char *cl;
  size_t hdr_len;
  size_t content_length;

  if (in_len > 65536)
    return -1;

  hdr_end = memmem(in, in_len, "\r\n\r\n", 4);
  if (!hdr_end)
    return 1;

  hdr_len = hdr_end + 4 - (const char *)in;

  cl = memmem(in, hdr_len, "Content-Length:", 15);
  if (!cl)
    return 0;

  // The header region always ends with "\r\n\r\n", so strtoul will stop
  // before the end of the buffer
  content_length = strtoul(cl + 15, NULL, 10);

  if (in_len < hdr_len + content_length)
    return 1;

  return 0;
}

static void test_gm2_bank_lsb_melodic(fluid_synth_t *synth)
{
    int bank = -1;
    int chan = 0;

    /* Force GM2 mode */
    synth->bank_select = FLUID_BANK_STYLE_GM2;

    /* Reset channel to melodic mode */
    fluid_synth_system_reset(synth);

    /* Set bank MSB to 121 (melodic in GM2) - should switch to melodic, MSB ignored */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_MSB, 121));

    /* Set bank LSB to 3 - should set bank to 3 */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_LSB, 3));

    fluid_channel_get_sfont_bank_prog(synth->channel[chan], NULL, &bank, NULL);
    TEST_ASSERT(bank == 3);
}

static void test_gm2_bank_msb_ignored_melodic(fluid_synth_t *synth)
{
    int bank = -1;
    int chan = 0;

    synth->bank_select = FLUID_BANK_STYLE_GM2;
    fluid_synth_system_reset(synth);

    /* Set bank MSB to some melodic value - should be ignored for bank num */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_MSB, 121));

    /* Set bank LSB to 5 */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_LSB, 5));

    fluid_channel_get_sfont_bank_prog(synth->channel[chan], NULL, &bank, NULL);
    /* Bank should be 5 (from LSB only) */
    TEST_ASSERT(bank == 5);
}

static void test_gm2_drum_switch(fluid_synth_t *synth)
{
    int bank = -1;
    int chan = 0;

    synth->bank_select = FLUID_BANK_STYLE_GM2;
    fluid_synth_system_reset(synth);

    /* Set MSB to 120 - should switch to drum mode and set bank to 128 */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_MSB, 120));

    TEST_ASSERT(synth->channel[chan]->channel_type == CHANNEL_TYPE_DRUM);

    fluid_channel_get_sfont_bank_prog(synth->channel[chan], NULL, &bank, NULL);
    TEST_ASSERT(bank == 128);
}

static void test_gm2_drum_lsb_ignored(fluid_synth_t *synth)
{
    int bank = -1;
    int chan = 0;

    synth->bank_select = FLUID_BANK_STYLE_GM2;
    fluid_synth_system_reset(synth);

    /* Switch to drum via MSB=120 */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_MSB, 120));

    /* Try setting LSB - should be ignored for drum channels */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_LSB, 10));

    fluid_channel_get_sfont_bank_prog(synth->channel[chan], NULL, &bank, NULL);
    /* Bank should still be 128 (drum) */
    TEST_ASSERT(bank == 128);
}

static void test_gm2_drum_to_melodic(fluid_synth_t *synth)
{
    int chan = 0;

    synth->bank_select = FLUID_BANK_STYLE_GM2;
    fluid_synth_system_reset(synth);

    /* Switch to drum */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_MSB, 120));
    TEST_ASSERT(synth->channel[chan]->channel_type == CHANNEL_TYPE_DRUM);

    /* Switch back to melodic via MSB=121 */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_MSB, 121));
    TEST_ASSERT(synth->channel[chan]->channel_type == CHANNEL_TYPE_MELODIC);
}

static void test_gm2_sysex_system_on(fluid_synth_t *synth)
{
    /* GM2 System ON: F0 7E 7F 09 03 F7
       In fluid_synth_sysex, data excludes F0 and F7 */
    char gm2_sysex[] = { MIDI_SYSEX_UNIV_NON_REALTIME, MIDI_SYSEX_DEVICE_ID_ALL, MIDI_SYSEX_GM_ID, MIDI_SYSEX_GM2_ON };

    /* First set to GM mode */
    synth->bank_select = FLUID_BANK_STYLE_GM;

    /* Send GM2 System ON */
    TEST_SUCCESS(fluid_synth_sysex(synth, gm2_sysex, sizeof(gm2_sysex), NULL, NULL, NULL, FALSE));

    /* Bank select should now be GM2, not GM */
    TEST_ASSERT(synth->bank_select == FLUID_BANK_STYLE_GM2);
}

static void test_gm_sysex_system_on(fluid_synth_t *synth)
{
    char gm_sysex[] = { MIDI_SYSEX_UNIV_NON_REALTIME, MIDI_SYSEX_DEVICE_ID_ALL, MIDI_SYSEX_GM_ID, MIDI_SYSEX_GM_ON };

    synth->bank_select = FLUID_BANK_STYLE_GS;

    TEST_SUCCESS(fluid_synth_sysex(synth, gm_sysex, sizeof(gm_sysex), NULL, NULL, NULL, FALSE));

    TEST_ASSERT(synth->bank_select == FLUID_BANK_STYLE_GM);
}

static void test_gm_then_gm2_reenables_bank_select(fluid_synth_t *synth)
{
    int bank = -1;
    int chan = 0;
    char gm_sysex[] = { MIDI_SYSEX_UNIV_NON_REALTIME, MIDI_SYSEX_DEVICE_ID_ALL, MIDI_SYSEX_GM_ID, MIDI_SYSEX_GM_ON };
    char gm2_sysex[] = { MIDI_SYSEX_UNIV_NON_REALTIME, MIDI_SYSEX_DEVICE_ID_ALL, MIDI_SYSEX_GM_ID, MIDI_SYSEX_GM2_ON };

    /* Start in GS mode */
    synth->bank_select = FLUID_BANK_STYLE_GS;

    /* GM System ON - disables bank select */
    TEST_SUCCESS(fluid_synth_sysex(synth, gm_sysex, sizeof(gm_sysex), NULL, NULL, NULL, FALSE));
    TEST_ASSERT(synth->bank_select == FLUID_BANK_STYLE_GM);

    /* Verify bank select is ignored in GM mode */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_LSB, 3));
    fluid_channel_get_sfont_bank_prog(synth->channel[chan], NULL, &bank, NULL);
    TEST_ASSERT(bank == 0);

    /* GM2 System ON - should re-enable bank select */
    TEST_SUCCESS(fluid_synth_sysex(synth, gm2_sysex, sizeof(gm2_sysex), NULL, NULL, NULL, FALSE));
    TEST_ASSERT(synth->bank_select == FLUID_BANK_STYLE_GM2);

    /* Verify bank select now works via LSB */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_MSB, 121));
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_LSB, 3));
    fluid_channel_get_sfont_bank_prog(synth->channel[chan], NULL, &bank, NULL);
    TEST_ASSERT(bank == 3);
}

static void test_gm2_setting(void)
{
    fluid_settings_t *settings = new_fluid_settings();
    fluid_synth_t *synth;
    int bank = -1;

    TEST_ASSERT(settings != NULL);
    TEST_SUCCESS(fluid_settings_setstr(settings, "synth.midi-bank-select", "gm2"));

    synth = new_fluid_synth(settings);
    TEST_ASSERT(synth != NULL);
    TEST_SUCCESS(fluid_synth_sfload(synth, TEST_SOUNDFONT, 1));

    TEST_ASSERT(synth->bank_select == FLUID_BANK_STYLE_GM2);

    /* Verify LSB works as bank number */
    TEST_SUCCESS(fluid_synth_cc(synth, 0, BANK_SELECT_MSB, 121));
    TEST_SUCCESS(fluid_synth_cc(synth, 0, BANK_SELECT_LSB, 7));
    fluid_channel_get_sfont_bank_prog(synth->channel[0], NULL, &bank, NULL);
    TEST_ASSERT(synth->channel[0]->channel_type == CHANNEL_TYPE_MELODIC);
    TEST_ASSERT(bank == 7);

    delete_fluid_synth(synth);
    delete_fluid_settings(settings);
}

static void test_gm2_only_120_is_drum(fluid_synth_t *synth)
{
    int chan = 0;

    synth->bank_select = FLUID_BANK_STYLE_GM2;
    fluid_synth_system_reset(synth);

    /* MSB 126 should NOT switch to drum in GM2 (unlike XG) */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_MSB, 126));
    TEST_ASSERT(synth->channel[chan]->channel_type == CHANNEL_TYPE_MELODIC);

    /* MSB 127 should NOT switch to drum in GM2 (unlike XG) */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_MSB, 127));
    TEST_ASSERT(synth->channel[chan]->channel_type == CHANNEL_TYPE_MELODIC);

    /* Only MSB 120 switches to drum in GM2 */
    TEST_SUCCESS(fluid_synth_cc(synth, chan, BANK_SELECT_MSB, 120));
    TEST_ASSERT(synth->channel[chan]->channel_type == CHANNEL_TYPE_DRUM);
}

int main(void)
{
    fluid_synth_t *synth;
    fluid_settings_t *settings = new_fluid_settings();
    TEST_ASSERT(settings != NULL);

    synth = new_fluid_synth(settings);
    TEST_ASSERT(synth != NULL);
    TEST_SUCCESS(fluid_synth_sfload(synth, TEST_SOUNDFONT, 1));

    test_gm2_bank_lsb_melodic(synth);
    fluid_synth_system_reset(synth);

    test_gm2_bank_msb_ignored_melodic(synth);
    fluid_synth_system_reset(synth);

    test_gm2_drum_switch(synth);
    fluid_synth_system_reset(synth);

    test_gm2_drum_lsb_ignored(synth);
    fluid_synth_system_reset(synth);

    test_gm2_drum_to_melodic(synth);
    fluid_synth_system_reset(synth);

    test_gm2_sysex_system_on(synth);
    fluid_synth_system_reset(synth);

    test_gm_sysex_system_on(synth);
    fluid_synth_system_reset(synth);

    test_gm_then_gm2_reenables_bank_select(synth);
    fluid_synth_system_reset(synth);

    test_gm2_only_120_is_drum(synth);

    delete_fluid_synth(synth);
    delete_fluid_settings(settings);

    /* Test setting-based initialization */
    test_gm2_setting();

    return EXIT_SUCCESS;
}

static int
fluid_synth_update_modulation_depth_range_LOCAL(fluid_synth_t *synth, int chan)
{
    return fluid_synth_modulate_voices_LOCAL(synth, chan, 1, MODULATION_MSB);
}

int main(void)
{
    fluid_settings_t *settings = new_fluid_settings();
    fluid_synth_t *synth = new_fluid_synth(settings);
    fluid_voice_t *voice;
    fluid_sample_t sample;
    int origpitch;
    int key;
    fluid_real_t root_pitch_cents;
    fluid_real_t pitch_no_adj_100, pitch_with_adj_100;
    fluid_real_t pitch_no_adj_50, pitch_with_adj_50;

    /* Zero-initialize to ensure clean state */
    FLUID_MEMSET(&sample, 0, sizeof(sample));

    /* Set up channel with no tuning (the common case) */
    voice = synth->voice[0];
    FLUID_MEMSET(voice->gen, 0, sizeof(voice->gen));
    FLUID_MEMSET(voice->mod, 0, sizeof(voice->mod));
    voice->channel = synth->channel[0];
    voice->sample = &sample;

    /* Use middle C (MIDI key 60) as the root key, and test with key 64 (E4) */
    sample.origpitch = origpitch = 60;       /* sample root key in MIDI note number */
    sample.pitchadj = 220;        /* sample fine tune in cents, i.e. must be correct by 20 cents sharp */
    sample.samplerate = 44100; // must be set to avoid div by zero
    key = 60;             /* the MIDI key to calculate pitch for */

    /* root_pitch_cents is the root pitch in cents without fine tune */
    root_pitch_cents = origpitch * 100.0f;

    voice->gen[GEN_KEYNUM].val = key;
    voice->gen[GEN_OVERRIDEROOTKEY].val = -1;
    /*
     * Test 1: With default SCALETUNE=100, pitchadj does not affect pitch (it cancels out)
     */
    voice->gen[GEN_SCALETUNE].val = 100;

    /* Force calculate pitch without pitchadj */
    voice->root_key = root_pitch_cents;
    pitch_no_adj_100 = fluid_voice_calculate_pitch(voice, key);

    /* Calculate pitch */
    fluid_voice_update_param(voice, GEN_OVERRIDEROOTKEY); /* This sets voice.root_key = root_pitch_cents - pitchadj in faulty fluidsynth */
    pitch_with_adj_100 = fluid_voice_calculate_pitch(voice, key);

    /* With SCALETUNE=100, both should give the same result: key*100 = 6400 */
    FLUID_LOG(FLUID_INFO,
              "SCALETUNE=100: pitch_no_adj=%.4f, pitch_with_adj=%.4f (expected both %.4f)",
              pitch_no_adj_100, pitch_with_adj_100, (fluid_real_t)(key * 100));
    TEST_ASSERT(pitch_no_adj_100 == pitch_with_adj_100);
    TEST_ASSERT(pitch_no_adj_100 == (key * 100.f));

    /*
     * Test 2: With non-default SCALETUNE=50, pitchadj should still NOT affect pitch.
     *         This test demonstrates the bug: the assertion will FAIL with current code.
     */
    voice->gen[GEN_SCALETUNE].val = 50;

    /* Force calculate pitch without pitchadj */
    voice->root_key = root_pitch_cents;
    pitch_no_adj_50 = fluid_voice_calculate_pitch(voice, key);
    /* Calculate pitch */
    fluid_voice_update_param(voice, GEN_OVERRIDEROOTKEY); /* This sets voice.root_key = root_pitch_cents - pitchadj in faulty fluidsynth */
    pitch_with_adj_50 = fluid_voice_calculate_pitch(voice, key);

    FLUID_LOG(FLUID_INFO,
              "SCALETUNE=50: pitch_no_adj=%.4f, pitch_with_adj=%.4f (should both be equal, diff %.4f)",
              pitch_no_adj_50, pitch_with_adj_50, pitch_with_adj_50 - pitch_no_adj_50);

    /* This assertion demonstrates the bug: with SCALETUNE != 100,
     * pitchadj incorrectly influences the calculated pitch.
     * The difference is: pitchadj * (SCALETUNE/100 - 1) = 20 * (50/100 - 1) = -10 */
    TEST_ASSERT(pitch_no_adj_50 == pitch_with_adj_50);
    TEST_ASSERT(pitch_no_adj_50 == 6000);

    /*
     * Test 3: With non-default SCALETUNE=50, pitchadj should still NOT affect pitch.
     *         This test demonstrates the bug: the assertion will FAIL with current code.
     */
    voice->gen[GEN_SCALETUNE].val = 50;
    voice->gen[GEN_KEYNUM].val = key = origpitch / 2;

    /* Force calculate pitch without pitchadj */
    voice->root_key = root_pitch_cents;
    pitch_no_adj_50 = fluid_voice_calculate_pitch(voice, key);
    /* Calculate pitch */
    fluid_voice_update_param(voice, GEN_OVERRIDEROOTKEY); /* This sets voice.root_key = root_pitch_cents - pitchadj in faulty fluidsynth */
    pitch_with_adj_50 = fluid_voice_calculate_pitch(voice, key);

    FLUID_LOG(FLUID_INFO,
              "SCALETUNE=50: pitch_no_adj=%.4f, pitch_with_adj=%.4f (should both be equal, diff %.4f)",
              pitch_no_adj_50, pitch_with_adj_50, pitch_with_adj_50 - pitch_no_adj_50);

    TEST_ASSERT(pitch_no_adj_50 == pitch_with_adj_50);
    TEST_ASSERT(pitch_no_adj_50 == 4500);

    /*
     * Test 4
     */
    voice->gen[GEN_SCALETUNE].val = 200;
    voice->root_key = root_pitch_cents;
    pitch_no_adj_50 = fluid_voice_calculate_pitch(voice, key);
    fluid_voice_update_param(voice, GEN_OVERRIDEROOTKEY);
    pitch_with_adj_50 = fluid_voice_calculate_pitch(voice, key);

    FLUID_LOG(FLUID_INFO,
              "SCALETUNE=50: pitch_no_adj=%.4f, pitch_with_adj=%.4f (should both be equal, diff %.4f)",
              pitch_no_adj_50, pitch_with_adj_50, pitch_with_adj_50 - pitch_no_adj_50);
    TEST_ASSERT(pitch_no_adj_50 == pitch_with_adj_50);
    TEST_ASSERT(pitch_no_adj_50 == 0);

    delete_fluid_synth(synth);
    delete_fluid_settings(settings);
    return EXIT_SUCCESS;
}

int fluid_server_socket_get_port(fluid_server_socket_t *server_socket)
{
    fluid_return_val_if_fail(server_socket != NULL, FLUID_FAILED);
    return server_socket->port;
}

void test_server_creation(fluid_settings_t* settings1, fluid_settings_t* settings2)
{
    fluid_server_t *server1, *server2;
    int port1, port2;

    server1 = new_fluid_server2(settings1, NULL, NULL, NULL);
    TEST_ASSERT(server1 != NULL);
    TEST_SUCCESS(fluid_settings_getint(settings1, "shell.port", &port1));
    TEST_ASSERT(port1 >= FLUID_SHELL_AUTO_PORT_START && port1 <= FLUID_TCP_PORT_MAX);

    server2 = new_fluid_server2(settings2, NULL, NULL, NULL);
    TEST_ASSERT(server2 != NULL);
    TEST_SUCCESS(fluid_settings_getint(settings2, "shell.port", &port2));
    TEST_ASSERT(port2 >= FLUID_SHELL_AUTO_PORT_START && port2 <= FLUID_TCP_PORT_MAX);
    TEST_ASSERT(port1 != port2);

    delete_fluid_server(server2);
    delete_fluid_server(server1);
}

int main(void)
{
#ifdef NETWORK_SUPPORT
    fluid_settings_t *settings1, *settings2;
    fluid_server_t *server1, *server2;

    settings1 = new_fluid_settings();
    settings2 = new_fluid_settings();
    TEST_ASSERT(settings1 != NULL);
    TEST_ASSERT(settings2 != NULL);

    // by default, auto-port probing should be enabled
    test_server_creation(settings1, settings2);

    TEST_SUCCESS(fluid_settings_setint(settings1, "shell.port", 0));
    TEST_SUCCESS(fluid_settings_setint(settings2, "shell.port", 0));

    // re-test by explicitly setting port to zero, should still work
    test_server_creation(settings1, settings2);

    TEST_SUCCESS(fluid_settings_setint(settings1, "shell.port", 12345));
    TEST_SUCCESS(fluid_settings_setint(settings2, "shell.port", 12345));

    server1 = new_fluid_server2(settings1, NULL, NULL, NULL);
    TEST_ASSERT(server1 != NULL);
    server2 = new_fluid_server2(settings2, NULL, NULL, NULL);
    TEST_ASSERT(server2 == NULL); // should fail since port 12345 is already in use by server1

    delete_fluid_server(server2);
    delete_fluid_server(server1);
    delete_fluid_settings(settings2);
    delete_fluid_settings(settings1);
#endif

    return EXIT_SUCCESS;
}

unsigned int fluid_channel_portamentotime_with_mode(fluid_channel_t *chan, enum fluid_portamento_time_mode time_mode, int lsb_seen, int fromkey, int tokey)
{
    int msb = fluid_channel_get_cc(chan, PORTAMENTO_TIME_MSB);
    int lsb = fluid_channel_get_cc(chan, PORTAMENTO_TIME_LSB);
    int res;
    fluid_real_t tmp;
    static const int Max = 480*1000; /*ms*/

    /* Use 7-bit MSB initially, switch to 14-bit if LSB has been seen */
    if(time_mode == FLUID_PORTAMENTO_TIME_MODE_AUTO)
    {
        if(lsb_seen)
        {
            time_mode = FLUID_PORTAMENTO_TIME_MODE_LINEAR;
        }
        else
        {
            time_mode = FLUID_PORTAMENTO_TIME_MODE_XG_GS;
        }
    }

    switch(time_mode)
    {
        case FLUID_PORTAMENTO_TIME_MODE_XG_GS:
            // Produce a curve similar to:
            /*
                CC 5 value  Portamento time
                ----------  ---------------
                    0            0.000 s
                    1            0.006 s
                    2            0.023 s
                    4            0.050 s
                    8            0.110 s
                    16           0.250 s
                    32           0.500 s
                    64           2.060 s
                    80           4.200 s
                    96           8.400 s
                    112         19.500 s
                    116         26.700 s
                    120         40.000 s
                    124         80.000 s
                    127        480.000 s
            */
            // Tests were performed by John Novak
            // https://github.com/dosbox-staging/dosbox-staging/pull/2705
            tmp = fluid_concave(msb);
            res = (fluid_real_t)(Max/2 * 2.5) * tmp * fluid_concave(128 * tmp) + 400 * fluid_convex(msb * (fluid_real_t)(1/4.0));
            res = res < Max ? res : Max;
            // Apply a similar scaling hack as SpessaSynth to fix Descent Game08, it's unclear why exactly
            // https://github.com/spessasus/spessasynth_core/blob/5a8730a80f8c0b74733ec193a968b36e2a0c0aee/src/synthesizer/audio_engine/engine_methods/portamento_time.ts#L84-87
            // https://github.com/FluidSynth/fluidsynth/pull/1656#issuecomment-3355759938
            res = (unsigned int)(res * abs(tokey - fromkey) / 36.0f + 0.5f);
            return res;

        case FLUID_PORTAMENTO_TIME_MODE_LINEAR:
            /* Always use 14-bit MSB+LSB */
            return msb * 128 + lsb;

        default:
            FLUID_LOG(FLUID_ERR, "THIS SHOULD NEVER HAPPEN! unknown portamento time mode %d", time_mode);
    }
    return 0;
}

void print_portamento_time7(fluid_channel_t *chan)
{
    for(int i = 0; i<128; i++)
    {
        fluid_channel_set_cc(chan, PORTAMENTO_TIME_MSB, i);
        auto ms = fluid_channel_portamentotime_with_mode(chan, FLUID_PORTAMENTO_TIME_MODE_XG_GS, false, 0, 36);
        std::cout << "CC5: " << i << " ^= " << ms/1000.0 << " s" << std::endl;
    }
}

void test_portamento_time7(fluid_channel_t *chan, enum fluid_portamento_time_mode time_mode, int lsb_seen)
{
    fluid_channel_set_cc(chan, PORTAMENTO_TIME_LSB, 80);
    fluid_channel_set_cc(chan, PORTAMENTO_TIME_MSB, 0);
    auto ms = fluid_channel_portamentotime_with_mode(chan, time_mode, lsb_seen, 0, 36);
    TEST_ASSERT(0 == ms);

    fluid_channel_set_cc(chan, PORTAMENTO_TIME_MSB, 127);
    ms = fluid_channel_portamentotime_with_mode(chan, time_mode, lsb_seen, 0, 36);
    TEST_ASSERT(480*1000 == ms);
    ms = fluid_channel_portamentotime_with_mode(chan, time_mode, lsb_seen, 36, 18);
    TEST_ASSERT(240*1000 == ms);
    ms = fluid_channel_portamentotime_with_mode(chan, time_mode, lsb_seen, 48, 48);
    TEST_ASSERT(0 == ms);
}

void test_portamento_time_lin(fluid_channel_t *chan, enum fluid_portamento_time_mode time_mode, int lsb_seen)
{
    fluid_channel_set_cc(chan, PORTAMENTO_TIME_LSB, 0);
    fluid_channel_set_cc(chan, PORTAMENTO_TIME_MSB, 8);
    auto ms = fluid_channel_portamentotime_with_mode(chan, time_mode, lsb_seen, 0, 24);
    TEST_ASSERT(1024 == ms);

    fluid_channel_set_cc(chan, PORTAMENTO_TIME_MSB, 0);
    fluid_channel_set_cc(chan, PORTAMENTO_TIME_LSB, 8);
    ms = fluid_channel_portamentotime_with_mode(chan, time_mode, lsb_seen, 0, 0);
    TEST_ASSERT(8 == ms);

    fluid_channel_set_cc(chan, PORTAMENTO_TIME_MSB, 0);
    fluid_channel_set_cc(chan, PORTAMENTO_TIME_LSB, 127);
    ms = fluid_channel_portamentotime_with_mode(chan, time_mode, lsb_seen, 12, 24);
    TEST_ASSERT(127 == ms);

    fluid_channel_set_cc(chan, PORTAMENTO_TIME_MSB, 0);
    fluid_channel_set_cc(chan, PORTAMENTO_TIME_LSB, 0);
    ms = fluid_channel_portamentotime_with_mode(chan, time_mode, lsb_seen, 0, 127);
    TEST_ASSERT(0 == ms);
}

int main(void)
{
    auto *settings = new_fluid_settings();
    auto *synth = new_fluid_synth(settings);
    auto *chan = new_fluid_channel(synth, 0);

    print_portamento_time7(chan);
    test_portamento_time7(chan, FLUID_PORTAMENTO_TIME_MODE_XG_GS, false);
    test_portamento_time7(chan, FLUID_PORTAMENTO_TIME_MODE_XG_GS, true);
    test_portamento_time7(chan, FLUID_PORTAMENTO_TIME_MODE_AUTO, false);

    test_portamento_time_lin(chan, FLUID_PORTAMENTO_TIME_MODE_LINEAR, false);
    test_portamento_time_lin(chan, FLUID_PORTAMENTO_TIME_MODE_LINEAR, true);
    test_portamento_time_lin(chan, FLUID_PORTAMENTO_TIME_MODE_AUTO, true);

    delete_fluid_channel(chan);
    delete_fluid_synth(synth);
    delete_fluid_settings(settings);
    return EXIT_SUCCESS;
}

