static void
test_decode_utf8(void)
{
    using namespace std::string_literals;

    /* UTF-8 encodings of the code points that a JSON parser hands us for a single byte. */
    const std::string utf8_0081{(char)0xc2, (char)0x81};
    const std::string utf8_00ff{(char)0xc3, (char)0xbf};
    const std::string utf8_20ac{(char)0xe2, (char)0x82, (char)0xac};

    testutil_assert(model::decode_utf8("") == "");
    testutil_assert(model::decode_utf8("Key 1") == "Key 1");

    /* Byte values above 0x7f arrive as two-byte sequences. */
    testutil_assert(model::decode_utf8(utf8_0081) == std::string(1, (char)0x81));
    testutil_assert(model::decode_utf8(utf8_00ff) == std::string(1, (char)0xff));

    /*
     * NUL bytes must survive the round trip: a metadata key unpacks with format "S", which requires
     * the terminator to be within the buffer.
     */
    testutil_assert(model::decode_utf8("file:WiredTigerHS.wt\0"s) == "file:WiredTigerHS.wt\0"s);
    testutil_assert(model::decode_utf8("a\0b"s) == "a\0b"s);
    testutil_assert(model::decode_utf8("\0"s) == "\0"s);

    /* The model only handles byte-long code points, so anything wider must be rejected. */
    bool caught = false;
    try {
        (void)model::decode_utf8(utf8_20ac);
    } catch (std::exception &) {
        caught = true;
    }
    testutil_assert(caught);

    /* Malformed input must be rejected rather than silently truncated. */
    caught = false;
    try {
        (void)model::decode_utf8(utf8_0081.substr(0, 1));
    } catch (std::exception &) {
        caught = true;
    }
    testutil_assert(caught);
}

static int
__disagg_defer_checkpoint(WT_SESSION_IMPL *session, char **meta_strp, uint64_t lsn)
{
    WT_DECL_RET;
    WT_DISAGG_DEFERRED_CKPT *entry, *newest;
    WT_DISAGGREGATED_STORAGE *disagg = &S2C(session)->disaggregated_storage;

    __wt_spin_lock(session, &disagg->deferred_ckpt_lock);

    /* A checkpoint at or behind the newest deferred one carries nothing new. */
    newest = TAILQ_LAST(&disagg->deferred_ckpt_qh, __wt_disagg_deferred_ckpt_qh);
    if (newest != NULL && lsn <= newest->lsn)
        goto err;

    /*
     * Remember every checkpoint not yet adopted, oldest first: a reader only blocks the checkpoints
     * newer than its snapshot, so keeping the intermediate ones lets the node adopt up to the
     * newest checkpoint its readers permit instead of waiting for all of them to finish. Adopting
     * an entry discards all older ones, which bounds the queue.
     */
    WT_ERR(__wt_calloc_one(session, &entry));
    entry->lsn = lsn;
    entry->meta = *meta_strp;
    *meta_strp = NULL;
    TAILQ_INSERT_TAIL(&disagg->deferred_ckpt_qh, entry, q);

err:
    __wt_spin_unlock(session, &disagg->deferred_ckpt_lock);
    return (ret);
}

static void
__disagg_clear_deferred_checkpoint(WT_SESSION_IMPL *session, uint64_t adopted_lsn)
{
    WT_DISAGG_DEFERRED_CKPT *entry;
    WT_DISAGGREGATED_STORAGE *disagg = &S2C(session)->disaggregated_storage;

    __wt_spin_lock(session, &disagg->deferred_ckpt_lock);
    while ((entry = TAILQ_FIRST(&disagg->deferred_ckpt_qh)) != NULL && entry->lsn <= adopted_lsn) {
        TAILQ_REMOVE(&disagg->deferred_ckpt_qh, entry, q);
        __wt_free(session, entry->meta);
        __wt_free(session, entry);
    }
    __wt_spin_unlock(session, &disagg->deferred_ckpt_lock);
}

void
__wti_disagg_clear_deferred_checkpoint_all(WT_SESSION_IMPL *session)
{
    __disagg_clear_deferred_checkpoint(session, UINT64_MAX);
}

static WT_INLINE bool
__disagg_deferred_ckpt_queued(WT_SESSION_IMPL *session)
{
    WT_DISAGGREGATED_STORAGE *disagg = &S2C(session)->disaggregated_storage;

    return (!TAILQ_EMPTY(&disagg->deferred_ckpt_qh));
}

static WT_INLINE bool
__disagg_deferred_pickup_run_chk(WT_SESSION_IMPL *session)
{
    return (FLD_ISSET(S2C(session)->server_flags, WT_CONN_SERVER_DISAGG_PICKUP));
}

static WT_THREAD_RET
__disagg_deferred_pickup_server(void *arg)
{
    WT_DECL_RET;
    WT_DISAGGREGATED_STORAGE *disagg;
    WT_SESSION_IMPL *session;
    int last_error;

    session = arg;
    disagg = &S2C(session)->disaggregated_storage;
    last_error = 0;

    for (;;) {
        /*
         * Sleep until signalled: a deferral arms the server and a pin release may unblock an
         * adoption. While anything is queued, wake periodically as a backstop against a wakeup lost
         * to a release racing a delivery; this is not an adoption deadline.
         */
        __wt_cond_wait(session, disagg->deferred_pickup_cond,
          __disagg_deferred_ckpt_queued(session) ? 10 * WT_MILLION : 0,
          __disagg_deferred_pickup_run_chk);

        /*
         * A conflict with a concurrent pickup (EBUSY) clears on its own, and the blockers that
         * would produce the next signal may already be gone, so spin here rather than returning to
         * an indefinite wait that could strand the queue. Back off so the conflict is not hot.
         *
         * Any other failure may well be permanent, so report it once and go back to waiting: the
         * queue stays armed and the backstop retries it, without a warning per retry.
         */
        while (__disagg_deferred_pickup_run_chk(session)) {
            ret = __wti_disagg_deferred_pickup_retry(session, false);
            if (ret != EBUSY)
                break;

            __wt_sleep(0, WT_DISAGG_RETRY_SLEEP_USECS);
        }
        if (ret != last_error) {
            last_error = ret;
            if (ret != 0)
                __wt_verbose_warning(session, WT_VERB_DISAGGREGATED_STORAGE,
                  "deferred checkpoint pickup failed: %s", __wt_strerror(session, ret, NULL, 0));
        }

        if (!__disagg_deferred_pickup_run_chk(session))
            break;
    }

    return (WT_THREAD_RET_VALUE);
}

void
__wt_disagg_deferred_pickup_signal(WT_SESSION_IMPL *session, uint64_t released_gen)
{
    WT_DISAGGREGATED_STORAGE *disagg = &S2C(session)->disaggregated_storage;

    /*
     * Every deferred checkpoint was delivered, so a pin taken at or after the newest delivered
     * checkpoint was blocking none of them. This needs no state of its own and skips the wakeup for
     * the common case: a reader that began after the last delivery, which is every reader once
     * nothing is deferred.
     */
    if (released_gen != 0 && released_gen >= __wt_gen(session, WT_GEN_DISAGG_CKPT))
        return;
    if (disagg->deferred_pickup_cond != NULL)
        __wt_cond_signal(session, disagg->deferred_pickup_cond);
}

int
__wti_disagg_deferred_pickup_server_create(WT_SESSION_IMPL *session)
{
    WT_CONNECTION_IMPL *conn = S2C(session);
    WT_DECL_RET;
    WT_DISAGGREGATED_STORAGE *disagg = &conn->disaggregated_storage;

    if (disagg->deferred_pickup_session != NULL)
        return (0);

    FLD_SET(conn->server_flags, WT_CONN_SERVER_DISAGG_PICKUP);

    WT_ERR(__wt_open_internal_session(
      conn, "disagg-pickup-server", false, 0, 0, &disagg->deferred_pickup_session));
    /* The condition variable survives a server stop: see the comment in the destroy function. */
    if (disagg->deferred_pickup_cond == NULL)
        WT_ERR(__wt_cond_alloc(disagg->deferred_pickup_session, "disagg deferred pickup",
          &disagg->deferred_pickup_cond));
    WT_ERR(__wt_thread_create(disagg->deferred_pickup_session, &disagg->deferred_pickup_tid,
      __disagg_deferred_pickup_server, disagg->deferred_pickup_session));
    disagg->deferred_pickup_tid_set = true;
    return (0);

err:
    WT_TRET(__wti_disagg_deferred_pickup_server_destroy(session));
    return (ret);
}

int
__wti_disagg_deferred_pickup_server_destroy(WT_SESSION_IMPL *session)
{
    WT_CONNECTION_IMPL *conn = S2C(session);
    WT_DECL_RET;
    WT_DISAGGREGATED_STORAGE *disagg = &conn->disaggregated_storage;

    FLD_CLR(conn->server_flags, WT_CONN_SERVER_DISAGG_PICKUP);
    if (disagg->deferred_pickup_tid_set) {
        __wt_cond_signal(session, disagg->deferred_pickup_cond);
        WT_TRET(__wt_thread_join(session, &disagg->deferred_pickup_tid));
        disagg->deferred_pickup_tid_set = false;
    }
    /*
     * Do not destroy the condition variable: a step-up stops the server on a live system, and any
     * session releasing a pinned snapshot may be signaling it concurrently. Signaling with no
     * waiter is harmless, so the condition variable lives until the connection tears down
     * disaggregated storage single-threaded.
     */
    if (disagg->deferred_pickup_session != NULL) {
        WT_TRET(__wt_session_close_internal(disagg->deferred_pickup_session));
        disagg->deferred_pickup_session = NULL;
    }
    return (ret);
}

static int
__disagg_deferred_copy(WT_SESSION_IMPL *session, bool force, char **metap, uint64_t *lsnp)
{
    WT_DECL_RET;
    WT_DISAGG_DEFERRED_CKPT *entry, *selected;
    WT_DISAGGREGATED_STORAGE *disagg = &S2C(session)->disaggregated_storage;
    uint64_t oldest_gen;

    *metap = NULL;
    *lsnp = WT_DISAGG_LSN_NONE;

    /*
     * The oldest pin decides the whole queue, so scan the sessions once, before taking the queue
     * lock. A snapshot established after the scan pins a generation newer than every delivered
     * checkpoint, so it cannot be one this selection needed to see.
     */
    oldest_gen = force ? 0 : __wt_gen_oldest(session, WT_GEN_DISAGG_CKPT);

    __wt_spin_lock(session, &disagg->deferred_ckpt_lock);
    selected = NULL;
    TAILQ_FOREACH (entry, &disagg->deferred_ckpt_qh, q) {
        /* A pin that does not cover the LSN means a snapshot predates it. */
        if (!force && oldest_gen <= entry->lsn)
            break;
        selected = entry;
    }
    if (selected == NULL)
        ret = WT_NOTFOUND;
    else {
        *lsnp = selected->lsn;
        /*
         * Copy the metadata: the adoption runs without this lock, and a concurrent adoption's
         * pruning may free the entry meanwhile.
         */
        ret = __wt_strdup(session, selected->meta, metap);
    }
    __wt_spin_unlock(session, &disagg->deferred_ckpt_lock);
    return (ret);
}

int
__wti_disagg_deferred_pickup_retry(WT_SESSION_IMPL *session, bool force)
{
    WT_DECL_RET;
    WT_DISAGGREGATED_STORAGE *disagg = &S2C(session)->disaggregated_storage;
    uint64_t deferred_lsn;
    char *meta_copy = NULL;

    deferred_lsn = WT_DISAGG_LSN_NONE;

    /* Having nothing to adopt is the common case, not a failure. */
    ret = __disagg_deferred_copy(session, force, &meta_copy, &deferred_lsn);
    if (ret == WT_NOTFOUND)
        return (0);
    WT_RET(ret);

    /*
     * Skip the deferral check in the adoption: the selection above already decided this checkpoint
     * may be adopted, and re-deferring it would loop.
     */
    ret = __wti_disagg_pick_up_checkpoint_meta(session, meta_copy, strlen(meta_copy), true);

    /*
     * A concurrent pickup may have adopted this checkpoint, or a newer one, between the copy above
     * and the adoption, which leaves the deferred pickup satisfied. That race has two outcomes: the
     * adoption rejects the now-older checkpoint (EINVAL), or its metadata merge conflicts with the
     * winner and unrolls (EBUSY). Anything else is a real failure, and a panic in particular must
     * not be swallowed here just because the winner published its LSN first.
     */
    if ((ret == EINVAL || ret == EBUSY) &&
      __wt_atomic_load_uint64_acquire(&disagg->last_checkpoint_meta_lsn) >= deferred_lsn) {
        /*
         * Prune the superseded entries: the copy above is not atomic with adoptions, so an entry
         * covered by a concurrent adoption may linger and would otherwise be selected again.
         */
        __disagg_clear_deferred_checkpoint(
          session, __wt_atomic_load_uint64_acquire(&disagg->last_checkpoint_meta_lsn));
        ret = 0;
    }

    __wt_free(session, meta_copy);
    return (ret);
}

static WT_INLINE void
__txn_snapshot_leave_disagg(WT_SESSION_IMPL *session)
{
    uint64_t released_gen;

    if ((released_gen = __wt_session_gen(session, WT_GEN_DISAGG_CKPT)) != 0) {
        __wt_session_gen_leave(session, WT_GEN_DISAGG_CKPT);
        __wt_disagg_deferred_pickup_signal(session, released_gen);
    }
    if (__wt_session_gen(session, WT_GEN_DISAGG_ROLE) != 0)
        __wt_session_gen_leave(session, WT_GEN_DISAGG_ROLE);
}

static WT_INLINE bool
__txn_snapshot_validate_disagg(WT_SESSION_IMPL *session)
{
    if (__wt_gen(session, WT_GEN_DISAGG_ROLE) != __wt_session_gen(session, WT_GEN_DISAGG_ROLE) ||
      __wt_atomic_load_bool_acquire(&S2C(session)->layered_table_manager.leader) !=
        session->txn->disagg_role_leader)
        return (false);
    if (session->txn->disagg_role_leader)
        return (true);
    return (__wt_gen(session, WT_GEN_DISAGG_CKPT) == __wt_session_gen(session, WT_GEN_DISAGG_CKPT));
}

static void
put(WT_SESSION *session, const std::vector<std::pair<const char *, const char *>> &kv,
  const char *commit_ts)
{
    WT_CURSOR *cursor;
    char cfg[64];

    REQUIRE(session->open_cursor(session, TABLE_URI.c_str(), nullptr, nullptr, &cursor) == 0);
    REQUIRE(session->begin_transaction(session, nullptr) == 0);
    for (const auto &pair : kv) {
        cursor->set_key(cursor, pair.first);
        cursor->set_value(cursor, pair.second);
        REQUIRE(cursor->insert(cursor) == 0);
    }
    testutil_snprintf(cfg, sizeof(cfg), "commit_timestamp=%s", commit_ts);
    REQUIRE(session->commit_transaction(session, cfg) == 0);
    REQUIRE(cursor->close(cursor) == 0);
}

static void
put_version(WT_SESSION *session, int version, uint32_t ts)
{
    WT_CURSOR *cursor;
    char cfg[64], key[64], value[64];

    REQUIRE(session->open_cursor(session, TABLE_URI.c_str(), nullptr, nullptr, &cursor) == 0);
    REQUIRE(session->begin_transaction(session, nullptr) == 0);
    for (int i = 0; i < NKEYS; i++) {
        testutil_snprintf(key, sizeof(key), "key_%d", i);
        testutil_snprintf(value, sizeof(value), "v_%d", version);
        cursor->set_key(cursor, key);
        cursor->set_value(cursor, value);
        REQUIRE(cursor->insert(cursor) == 0);
    }
    testutil_snprintf(cfg, sizeof(cfg), "commit_timestamp=%x", ts);
    REQUIRE(session->commit_transaction(session, cfg) == 0);
    REQUIRE(cursor->close(cursor) == 0);
}

static void
reader(WT_CONNECTION *conn, std::atomic<bool> *stop, std::mutex *errors_mutex,
  std::vector<std::string> *errors, std::atomic<uint64_t> *transactions)
{
    WT_CURSOR *cursor;
    WT_SESSION *session;
    int ret;
    char key[64];
    const char *value;
    std::string error, seen;

    if (conn->open_session(conn, nullptr, nullptr, &session) != 0) {
        std::lock_guard<std::mutex> lock(*errors_mutex);
        errors->push_back("reader failed to open a session");
        stop->store(true);
        return;
    }

    while (!stop->load() && error.empty()) {
        if ((ret = session->begin_transaction(session, nullptr)) != 0) {
            error = "begin_transaction failed: " + std::to_string(ret);
            break;
        }
        seen.clear();
        for (int pass = 0; pass < 2 && error.empty(); pass++) {
            if ((ret = session->open_cursor(
                   session, TABLE_URI.c_str(), nullptr, nullptr, &cursor)) != 0) {
                error = "open_cursor failed: " + std::to_string(ret);
                break;
            }
            for (int i = 0; i < NKEYS; i++) {
                testutil_snprintf(key, sizeof(key), "key_%d", i);
                cursor->set_key(cursor, key);
                if ((ret = cursor->search(cursor)) != 0) {
                    error = "search failed or was refused: " + std::to_string(ret);
                    break;
                }
                if (cursor->get_value(cursor, &value) != 0) {
                    error = "get_value failed";
                    break;
                }
                if (seen.empty())
                    seen = value;
                else if (seen != value) {
                    error = "torn or drifting read: " + std::string(value) + " != " + seen;
                    break;
                }
            }
            (void)cursor->close(cursor);
        }
        (void)session->rollback_transaction(session, nullptr);
        if (error.empty())
            transactions->fetch_add(1);
    }

    if (!error.empty()) {
        std::lock_guard<std::mutex> lock(*errors_mutex);
        errors->push_back(error);
        stop->store(true);
    }
    (void)session->close(session, nullptr);
}

static int
__disagg_adopt_checkpoint_meta(WT_SESSION_IMPL *session, const WT_DISAGG_CHECKPOINT_META *ckpt_meta,
  const WT_DISAGG_METADATA *metadata, bool is_startup)
{
    WT_DECL_RET;

    WT_ASSERT_SPINLOCK_OWNED(session, &S2C(session)->schema_lock);

    WT_RET(__wt_meta_track_on(session));

    /* Update our local metadata with the new checkpoint entry. */
    WT_ERR(__disagg_save_checkpoint_meta_local(session, metadata));

    /* Apply the metadata for the other tables from the shared metadata table. */
    WT_ERR(__disagg_apply_checkpoint_meta(session, ckpt_meta, metadata->schema_epoch, is_startup));

err:
    WT_TRET(__wt_meta_track_off(session, true, ret != 0));
    return (ret);
}

static int
__disagg_replace_checkpoint(
  WT_SESSION_IMPL *session, const char *base, const WT_CONFIG_ITEM *new_ckpt, char **config_ret)
{
    WT_CONFIG cparser;
    WT_CONFIG_ITEM k, last_ckpt_key, v;
    WT_DECL_ITEM(tmp);
    WT_DECL_RET;

    *config_ret = NULL;
    WT_CLEAR(last_ckpt_key);

    /* Find the last checkpoint= key; config lookups already take that final match. */
    __wt_config_init(session, &cparser, base);
    while ((ret = __wt_config_next(&cparser, &k, &v)) == 0) {
        if (k.type != WT_CONFIG_ITEM_STRING && k.type != WT_CONFIG_ITEM_ID)
            WT_RET_MSG(
              session, EINVAL, "Invalid configuration key found: '%.*s'", (int)k.len, k.str);
        if (WT_CONFIG_LIT_MATCH("checkpoint", k))
            last_ckpt_key = k;
    }
    WT_RET_NOTFOUND_OK(ret);
    if (last_ckpt_key.str == NULL)
        return (WT_NOTFOUND);

    WT_RET(__wt_scr_alloc(session, strlen(base) + new_ckpt->len + 32, &tmp));

    __wt_config_init(session, &cparser, base);
    while ((ret = __wt_config_next(&cparser, &k, &v)) == 0) {
        if (k.type != WT_CONFIG_ITEM_STRING && k.type != WT_CONFIG_ITEM_ID)
            WT_ERR_MSG(
              session, EINVAL, "Invalid configuration key found: '%.*s'", (int)k.len, k.str);
        if (k.str == last_ckpt_key.str)
            v = *new_ckpt;
        else {
            if (k.type == WT_CONFIG_ITEM_STRING)
                WT_CONFIG_PRESERVE_QUOTES(session, &k);
            if (v.type == WT_CONFIG_ITEM_STRING)
                WT_CONFIG_PRESERVE_QUOTES(session, &v);
        }
        WT_ERR(__wt_buf_catfmt(session, tmp, "%.*s=%.*s,", (int)k.len, k.str, (int)v.len, v.str));
    }
    WT_ERR_NOTFOUND_OK(ret, false);

    /* Each entry was emitted with a trailing comma; drop the final one. */
    --tmp->size;
    WT_ERR(__wt_strndup(session, tmp->data, tmp->size, config_ret));

err:
    __wt_scr_free(session, &tmp);
    return (ret);
}

int
__ut_disagg_replace_checkpoint(
  WT_SESSION_IMPL *session, const char *base, const WT_CONFIG_ITEM *new_ckpt, char **config_ret)
{
    return (__disagg_replace_checkpoint(session, base, new_ckpt, config_ret));
}

bool
__wti_verify_progress_due(WT_SESSION_IMPL *session, WT_TIMER *last_report, uint64_t interval_ms)
{
    uint64_t elapsed_ms;

    __wt_timer_evaluate_ms(session, last_report, &elapsed_ms);
    if (elapsed_ms < interval_ms)
        return (false);
    __wt_timer_start(session, last_report);
    return (true);
}

static int
__verify_one_checkpoint(
  WT_SESSION_IMPL *session, WT_VSTUFF *vs, WT_CKPT *ckpt, bool skip_hs, bool last_ckpt)
{
    WT_BTREE *btree = S2BT(session);
    WT_BM *bm = btree->bm;
    WT_DECL_RET;
    const char *name = session->dhandle->name;
    bool evict_off = false;

    if (WT_VRFY_DUMP(vs)) {
        WT_RET(__wt_msg(session, "%s", WT_DIVIDER));
        WT_RET(__wt_msg(session, "%s, ckpt_name: %s", name, ckpt->name));
    }

    size_t root_addr_size;
    uint8_t root_addr[WT_ADDR_MAX_COOKIE];
    WT_RET(bm->checkpoint_load(
      bm, session, ckpt->raw.data, ckpt->raw.size, root_addr, &root_addr_size, true));

    /* Skip trees with no root page. */
    if (root_addr_size == 0)
        goto done;

    WT_ERR(__wti_btree_tree_open(session, root_addr, root_addr_size));

    if (WT_VRFY_DUMP(vs))
        WT_ERR(__wt_msg(session, "Root:\n\t> addr: %s",
          __wt_addr_string(session, root_addr, root_addr_size, vs->tmp1)));

    /*
     * We currently hold an exclusive lock which means eviction cannot work on that tree. Eviction
     * must work on trees being verified (else we'd have to do our own eviction), so we release the
     * lock while verifying.
     */
    __wt_evict_file_exclusive_off(session);
    evict_off = true;

    /* Create a fake, unpacked parent cell for the tree based on the checkpoint information. */
    WT_CELL_UNPACK_ADDR addr_unpack;
    memset(&addr_unpack, 0, sizeof(addr_unpack));
    WT_TIME_AGGREGATE_COPY(&addr_unpack.ta, &ckpt->ta);
    if (ckpt->ta.prepare)
        addr_unpack.ta.prepare = 1;
    addr_unpack.raw = WT_CELL_ADDR_INT;

    /* Only verify HS entries against the last checkpoint. */
    vs->skip_hs = skip_hs || !last_ckpt;
    vs->hs_checkpoint_name = ckpt->name;

    /* Verify the tree. */
    WT_WITH_PAGE_INDEX(session, ret = __verify_tree(session, &btree->root, &addr_unpack, vs));
    WT_ERR(ret);

    /* Account for the root page in the accumulated total block size. */
    WT_ERR(__verify_disagg_accumulate_size(session, vs, ckpt->raw.data, ckpt->raw.size));

#ifdef HAVE_DIAGNOSTIC
    /* Validate the size of the btree. */
    if (F_ISSET(btree, WT_BTREE_DISAGGREGATED) && ckpt->size != vs->total_block_size)
        /*
         * FIXME-WT-18038: We are seeing mismatches due to nuanced reconciliation issues, where
         * bytes_total increments happen before the reconciliation panic boundary, leaving us in an
         * inconsistent state if reconciliation fails after the increment but before completion.
         * Only fail in diagnostic builds for now; enable this branch in production builds once this
         * is resolved.
         */
        WT_ERR_MSG(session, WT_ERROR,
          "checkpoint size %" PRIu64 " does not match accumulated block size %" PRIu64, ckpt->size,
          vs->total_block_size);
#endif

    /*
     * The checkpoints are in time-order, so the last one in the list is the most recent. If this is
     * the most recent checkpoint, verify the history store against it, also verify page discard
     * function if we're in disagg mode.
     */
    if (ret == 0 && last_ckpt) {
        if (F_ISSET(btree, WT_BTREE_DISAGGREGATED)) {
            /*
             * The page discard verification routine depends on get_page_ids being implemented.
             */
            WT_BLOCK_DISAGG *block_disagg = (WT_BLOCK_DISAGG *)bm->block;
            if (block_disagg->plhandle->plh_get_page_ids != NULL && ckpt->raw.data != NULL)
                WT_ERR(__verify_page_discard(session, bm));
        }

        if (!skip_hs) {
            __wt_verbose(session, WT_VERB_VERIFY, "%s: verify against history store", name);
            WT_ERR_MSG_CHK(
              session, __wt_hs_verify_one(session, btree->id), "history store verification failed");
        }
    }

    /*
     * If the read_corrupt mode was turned on, we may have continued traversing and verifying the
     * pages of the tree despite encountering an error. Set the error.
     */
    if (vs->verify_err != 0)
        ret = vs->verify_err;

done:
err:
    /*
     * If eviction was enabled to verify the tree, re-acquire the exclusive lock and discard the
     * tree before unloading the checkpoint.The discard must run while the lock is held and before
     * the unload, as the tree's pages reference this checkpoint's block manager.
     */
    if (evict_off) {
        WT_TRET(__wt_evict_file_exclusive_on(session));
        WT_TRET(__wt_evict_file(session, WT_SYNC_DISCARD));
    }

    /* Unload the checkpoint. */
    WT_TRET(bm->checkpoint_unload(bm, session));

    return (ret);
}

