uint32_t readTrims()
{
  uint32_t result = 0;
  uint32_t keys = bsp_get_fs_switches();

#define _TRIM(t) \
  if ((keys & BSP_##t) == 0) result |= 1 << t;

  _TRIM(TR1U);
  _TRIM(TR1D);
  _TRIM(TR3L);
  _TRIM(TR3R);
  _TRIM(TR2U);
  _TRIM(TR2D);
  _TRIM(TR4L);
  _TRIM(TR4R);
  if (!LL_GPIO_IsInputPinSet(GPIOH, LL_GPIO_PIN_15)) result |= (1 << TR5U);
  if (!LL_GPIO_IsInputPinSet(GPIOH, LL_GPIO_PIN_13)) result |= (1 << TR5D);
  _TRIM(TR6U);
  _TRIM(TR6D);

#undef _TRIM

  return result;
}

bool simuLocalTime(time_t t, struct tm* result)
{
  struct tm* tmp;
#if defined(__wasm__)
  t += simuUtcOffset;
  tmp = gmtime(&t);
#else
  tmp = localtime(&t);
#endif
  if (tmp == nullptr) return false;
  *result = *tmp;
  return true;
}

time_t simuLocalTimeToEpoch(struct tm* tm)
{
#if defined(__wasm__)
  // wasi-libc's mktime() is timezone-less, i.e. equivalent to timegm()
  time_t t = mktime(tm);
  return t == (time_t)-1 ? t : t - simuUtcOffset;
#else
  return mktime(tm);
#endif
}

