AFHDS3_Sensors::AFHDS3_Sensors(uint8_t moduleIdx) : Page(ICON_MODEL_SETUP)
{
  cfg = afhds3::getConfig(moduleIdx);
  std::string title =
      moduleIdx == INTERNAL_MODULE ? STR_INTERNALRF : STR_EXTERNALRF;
  header->setTitle(title);

  title = "AFHDS3 (";
  title += STR_TELEMETRY_SENSORS;
  title += ")";
  header->setTitle2(title);

  body->setFlexLayout(LV_FLEX_FLOW_COLUMN, PAD_TINY);

  FlexGridLayout grid(col_dsc, row_dsc, PAD_TINY);

  bool ibus2_mode = false;

  if (cfg->version == 0) {
    return;
  }
  auto vCfg = &cfg->v1;

  for (uint8_t j = 0; j < SES_NPT_NB_MAX_PORTS; j++) {
    if (vCfg->NewPortTypes[j] == afhds3::SES_NPT_IBUS2 || vCfg->NewPortTypes[j] == afhds3::SES_NPT_IBUS2_HUB_PORT) {
      ibus2_mode = true;
      break;
    }
  }
  std::string temp_str;
  auto line = body->newLine(grid);

  if (!ibus2_mode) {
    new StaticText(line, rect_t{}, STR_IBUS2_SENSORS_MODE_ONLY);
    return;
  }

  if (cfg->others.sensorOnLine & (1 << afhds3::DirtyIbus2Sensor::IBUS2_SENSOR_GPS)) 
  {
    temp_str = STR_IMU;
    temp_str += " ";
    temp_str += STR_CURRENTSENSOR;
    new StaticText(line, rect_t{}, temp_str);
    auto imu_btn = new TextButton(line, rect_t{}, STR_CALIBRATION);
    imu_btn->setPressHandler([=]() -> uint8_t {
      DIRTY_CMD(cfg, afhds3::DirtyConfig::DC_RX_CMD_CALIB_GYRO);
      return 0;
    });

    temp_str = STR_SENSOR_DIST;
    temp_str += " ";
    temp_str += STR_CURRENTSENSOR;
    line = body->newLine(grid);
    new StaticText(line, rect_t{}, temp_str);
    auto dist_btn = new TextButton(line, rect_t{}, STR_RESET);
    dist_btn->setPressHandler([=]() -> uint8_t {
      DIRTY_CMD(cfg, afhds3::DirtyConfig::DC_RX_CMD_CALIB_DIST);
      return 0;
    });
  }

  if (cfg->others.sensorOnLine & (1 << afhds3::DirtyIbus2Sensor::IBUS2_SENSOR_GPS) || cfg->others.sensorOnLine & (1 << afhds3::DirtyIbus2Sensor::IBUS2_SENSOR_PRES)) {
    line = body->newLine(grid);
    new StaticText(line, rect_t{}, STR_ALTSENSOR);
    auto alt_btn = new TextButton(line, rect_t{}, STR_RESET);
    alt_btn->setPressHandler([=]() -> uint8_t {
      DIRTY_CMD(cfg, afhds3::DirtyConfig::DC_RX_CMD_CALIB_ALT);
      return 0;
    });
  }

  // if (cfg->others.sensorOnLine & (1 << afhds3::DirtyIbus2Sensor::IBUS2_SENSOR_RPM)) {
  //   temp_str = "RPM";
  //   temp_str += " ";
  //   temp_str += STR_CURRENTSENSOR;
  //   line = body->newLine(grid);
  //   new StaticText(line, rect_t{}, temp_str);
  //   new NumberEdit(line, rect_t{0, 0, EdgeTxStyles::EDIT_FLD_WIDTH_NARROW, 0}, 1, 12, GET_SET_DEFAULT(cfg->others.calibData[afhds3::DirtyIbus2Sensor::IBUS2_SENSOR_RPM]));
  // }

  if (cfg->others.sensorOnLine & (1 << afhds3::DirtyIbus2Sensor::IBUS2_SENSOR_IBC)) {
    // temp_str = "IBC01";
    // temp_str += " Auto ";
    // temp_str += "Clear";
    // line = body->newLine(grid);
    // new StaticText(line, rect_t{}, temp_str);
    // new ToggleSwitch(line, rect_t{}, GET_SET_DEFAULT(cfg->others.calibData[afhds3::DirtyIbus2Sensor::IBUS2_SENSOR_IBC]));

    temp_str = "IBC01";
    temp_str += " ";
    temp_str += STR_CALIBRATION;
    line = body->newLine(grid);
    new StaticText(line, rect_t{}, temp_str);
    auto edit = new NumberEdit(line, rect_t{0, 0, EdgeTxStyles::EDIT_FLD_WIDTH_NARROW, 0}, 0, 120, GET_SET_DEFAULT(cfg->others.calibData[afhds3::DirtyIbus2Sensor::IBUS2_SENSOR_IBC]), PREC1);
    edit->setSuffix("v");
  }
}

void setIbusType(uint8_t* ibus_type_buf) 
{
  for(uint8_t i = 0; i< SES_NPT_NB_MAX_PORTS; i++) {
   if (ibus_type_buf[i] == afhds3::SES_NPT_IBUS2 || ibus_type_buf[i] == afhds3::SES_NPT_IBUS2_HUB_PORT) {
    ibus_type[i] = afhds3::SES_NPT_IBUS2;
   } else {
    ibus_type[i] = afhds3::SES_NPT_IBUS1_IN;
   }
  }
}

void processFlySkyIbus2AFHDS3Sensor(const uint8_t * packet, uint8_t len )
{
  uint16_t type = (packet[0] << 8) | packet[1];
  uint8_t id = packet[2];
  int32_t value=0;
  type = type ? type : IBDT_INT_VOLTAGE;  // Remapped

  // TRACE("[IBUS] type x%02X, len %d", type, len);
  if(len == 1)
  {
    value = packet[3];  // type 0xfe SIGNAL_STRENGTH
  }
  else if (len == 2)
  {
      value = (packet[4] << 8) | packet[3];
  }
  else if(len == 4)
  {
    value = (packet[6] << 24) | (packet[5] << 16) | (packet[4] << 8) | packet[3]; // PRESSURE
  } else {
    // gps & ibc01
  }

  if (IBDT_BK_NOISE == type || IBDT_RSSI == type)
  {
    value  = -value;
  }

  if ( (IBDT_EXT_VOLTAGE == type) )
  {
    if ( id&0x80 )
    {
      type = IBDT_EXT_BVD;
    }
  }
  else if(IBDT_RSSI == type || IBDT_BK_NOISE == type || IBDT_SNR == type)
  {
    if( value>=0 )
      value = (value+2)/4;
    else
      value = (value-2)/4;
  }
  else if (IBDT_SIGNAL_STRENGTH == type)
  {
    telemetryData.rssi.set( value );
    if (value > 0) telemetryStreaming = TELEMETRY_TIMEOUT10ms;
  }
  else if (IBDT_PRESSURE == type)
  {
      int32_t alt = getALT(value);
      // int16_t temp = (value >> 19);
      if (reset_baro_alt) {
        reset_baro_alt = !reset_baro_alt;
        StartPos.Boar_Altitude = alt;
      } else {
        int32_t RH =  alt - StartPos.Boar_Altitude;
        type = VIRTUAL_REL_ALT;
        sendFlyskytelemtry(type, id, RH);
        // TRACE("[IBUS2] RH = %d", RH);
      }

      type = VIRTUAL_ALT;
      sendFlyskytelemtry(type, id, alt);

      pres_update_tick = timersGetMsTick();
      value &= PRESSURE_MASK;
      type = IBDT_PRESSURE;
      sendFlyskytelemtry(type, id, value);
      return;
  } else if (IBDT_ROTATION_SPEED == type) {
    // Adjust the rotational speed based on the number of blades
    // RPM = value;
    flyskyRpmId = id;
    rpm_update_tick = timersGetMsTick();
  } else if (IBDT_GPS == type) {
    flyskyGpsId = id;
    flyskyIbus2GPS(&packet[3], len, id);
    return;
  } else if (IBDT_IBC01 == type) {
    flyskyIbus2IBC(&packet[3], len, id);
    return;
  }

  if(IBDT_TEMPERATURE == type)
  {
    value -= 400; // Temperature sensors have 40 degree offset
  }

  sendFlyskytelemtry(type, id, value);
}

void flyskyIbus2GPS(const uint8_t * pData, uint8_t len, uint8_t id) {
  static uint16_t	PSValue;
  uint16_t n = 0;
  int32_t value = 0;
  uint16_t type = 0;
  static bool get_start = true; // Get the location at startup

  gps_update_tick = timersGetMsTick();

  PSValue = pData[n] | (pData[n+1] << 8);
  if( GPS_MSG_TYPE_PACK1 == (PSValue & 0x000f) )
  {
    GPSData.NbSatellites 	= (PSValue >> 4) & 0x003F ;	n++;
    GPSData.PositionStatus 	= (PSValue >> 10) & 0x003F ;n++;
    value = GPSData.NbSatellites;
    type = VIRTUAL_GPS_STAS;
    sendFlyskytelemtry(type, id, value);

    PSValue = pData[n] | (pData[n+1] << 8);
    GPSData.DateDay 		= (PSValue & 0x001F);
    GPSData.DateMonth 		= (PSValue >> 5) & 0x000F;	n++;
    GPSData.DateYear 		= (PSValue >> 9) & 0x007F;	n++;
    value = GPSData.DateYear << 24 | GPSData.DateMonth << 16 | GPSData.DateDay << 8 | 0xff ;
    type = VIRTUAL_GPS_TIME;
    sendFlyskytelemtry(type, id, value);

    PSValue = pData[n] | (pData[n+1] << 8);
    GPSData.Speed 			= (PSValue);					n++;n++;
    value = GPSData.Speed;
    type = VIRTUAL_GPS_SPEED;
    sendFlyskytelemtry(type, id, value);

    GPSData.UTCTime 		= pData[n] | (pData[n+1] << 8) | (pData[n+2] << 16) | (pData[n+3] << 24);
    n++;n++;n++;n++;
    // value = GPSData.UTCTime;
    uint32_t total_seconds = GPSData.UTCTime;
    uint8_t sec = total_seconds % 60;
    uint32_t total_minutes = total_seconds / 60;
    uint8_t min = total_minutes % 60;
    uint8_t hour = total_minutes / 60;
    type = VIRTUAL_GPS_TIME;
    value = 0x00;
    value = hour << 24 | min << 16 | sec << 8;
    sendFlyskytelemtry(type, id, value);
    // TRACE("[IBUS2] utc %d %d %d %d ", GPSData.DateYear, GPSData.DateMonth, GPSData.DateDay, GPSData.UTCTime);

    PSValue = pData[n] | (pData[n+1] << 8);
    GPSData.Altitude 		= (PSValue);					n++;n++;
    type = VIRTUAL_GPS_ALT;
    value = PSValue;
    sendFlyskytelemtry(type, id, value);

    PSValue = pData[n] | (pData[n+1] << 8);
    GPSData.Direction 		= (PSValue);					n++;n++;

    type = VIRTUAL_GPS_REL_ALT;
    if (!get_start) {
      value = GpsSensorHeighthGet();
    } else {
      value = 0;
    }
    sendFlyskytelemtry(type, id, value);
  }
  else if( GPS_MSG_TYPE_PACK2 == (PSValue & 0x000f) )
  {
    GPSData.Pitch 			= (PSValue >> 4) & 0x0FFF ;		n++;n++;
    value = GPSData.Pitch - 1800;
    type = VIRTUAL_GPS_PITCH;
    sendFlyskytelemtry(type, id, value);

    PSValue = pData[n] | (pData[n+1] << 8);
    GPSData.Roll 			= (PSValue);					n++;n++;
    value = GPSData.Roll - 1800;
    type = VIRTUAL_GPS_ROLL;
    sendFlyskytelemtry(type, id, value);

    PSValue = pData[n] | (pData[n+1] << 8);
    GPSData.Yaw 			= (PSValue);					n++;n++;
    value = 3600 - GPSData.Yaw;
    type = VIRTUAL_GPS_YAW;
    sendFlyskytelemtry(type, id, value);

    GPSData.Latitude 		= (pData[n] | (pData[n+1] << 8) | (pData[n+2] << 16) | (pData[n+3] << 24));
    value = GPSData.Latitude;
    type = VIRTUAL_GPS_LAT;
    sendFlyskytelemtry(type, id, value);

    n++;n++;n++;n++;
    GPSData.Longitude 		= (pData[n] | (pData[n+1] << 8) | (pData[n+2] << 16) | (pData[n+3] << 24));
    value = GPSData.Longitude;
    type = VIRTUAL_GPS_LON;
    sendFlyskytelemtry(type, id, value);


    type = VIRTUAL_GPS_DIST;
    if (!get_start) {
      value = GpsSensorDistanceGet();
    } else {
      value = 0;
    }
    sendFlyskytelemtry(type, id, value);

  }

  if (get_start && GPSData.PositionStatus == 3) {
    get_start = false;
    StartPos.Altitude = GPSData.Altitude;
    StartPos.Latitude = GPSData.Latitude;
    StartPos.Longitude = GPSData.Longitude;
  } else {
    if (reset_gps_alt) {
      StartPos.Altitude = GPSData.Altitude;
      reset_gps_alt = false;
    }
    if (reset_gps_dist) {
      StartPos.Latitude = GPSData.Latitude;
      StartPos.Longitude = GPSData.Longitude;
      reset_gps_dist = false;
    }
  }
}

void flyskyIbus2IBC(const uint8_t * pData, uint8_t len, uint8_t id) {
  int32_t value = 0;
  uint16_t type = 0;
  memcpy(&IBCDate, pData, sizeof(IBCDate));

  ibc_update_tick = timersGetMsTick();

  type = VIRTUAL_IBC_VOLTS;
  value = IBCDate.Voltage;
  sendFlyskytelemtry(type, id, value);

  type = VIRTUAL_IBC_CURR;
  value = IBCDate.Current;
  sendFlyskytelemtry(type, id, value);

  type = VIRTUAL_IBC_CAPA;
  value = IBCDate.UsedCapacity;
  sendFlyskytelemtry(type, id, value);

  type = VIRTUAL_IBC_AVG_CURR;
  value = IBCDate.AverageCurrent;
  sendFlyskytelemtry(type, id, value);

  flyskyIbcId = id;
}

void sendFlyskytelemtry(uint16_t type, uint8_t id, int32_t value) {
  for (const FlySkySensor * sensor = flySkySensors; sensor->type; sensor++)
  {
    if (sensor->type != type) continue;

    if (sensor->unit == UNIT_VOLTS) value = (int16_t) value; // Voltage types are unsigned 16bit integers

    //  Remapped to single GPS sensor:
    if (type == VIRTUAL_GPS_LON) type = VIRTUAL_GPS_LAT;
    setFlyskyTelemetryValue(type, id, value, sensor->unit, sensor->precision);
    return;
  }
}

const FlySkySensor * getFlySkyIbus2Sensor(uint16_t id)
{
  for (const FlySkySensor * sensor = flySkySensors; sensor->type; sensor++) {
    if (id == sensor->type)
      return sensor;
  }
  return nullptr;
}

void flySkyIbus2SetDefault(int index, uint16_t id, uint8_t subId, uint8_t instance)
{
  TelemetrySensor &telemetrySensor = g_model.telemetrySensors[index];
  telemetrySensor.id = id;
  telemetrySensor.subId = subId;
  telemetrySensor.instance = instance;

  const FlySkySensor * sensor = getFlySkyIbus2Sensor(id);
  if (sensor) {
    TelemetryUnit unit = sensor->unit;
    uint8_t prec = min<uint8_t>(2, sensor->precision);
    telemetrySensor.init(sensor->name, unit, prec);

    if (unit == UNIT_RPMS) {
      telemetrySensor.custom.ratio = 1;
      telemetrySensor.custom.offset = 1;
    } else if (unit == UNIT_GPS_LATITUDE || unit == UNIT_GPS_LONGITUDE) {
      telemetrySensor.unit = UNIT_GPS;
    }
  }
  else {
    telemetrySensor.init(id);
  }

  storageDirty(EE_MODEL);
}

static double GetDistance(double lat1, double lng1, double lat2, double lng2)
{
  lat1 =lat1/1000000; lng1= lng1/1000000;
  lat2 =lat2/1000000; lng2= lng2/1000000;

  double radLat1 = deg2rad(lat1);
  double radLat2 = deg2rad(lat2);

  double a = radLat1 - radLat2;
  double b = deg2rad(lng1) - deg2rad(lng2);

  float s = 2.0f * asin(sqrt(pow(sin(a/2),2)
                    + cos(radLat1)*cos(radLat2)*pow(sin(b/2),2)));

  s = s * EARTH_RADIUS * 100; //cm
  return s;
}

int32_t GpsSensorDistanceGet()
{
  double lats ,lngs, late, lnge;

  lats = StartPos.Latitude;
  lngs = StartPos.Longitude;
  late = GPSData.Latitude;
  lnge = GPSData.Longitude;
  return GetDistance(lats, lngs, late, lnge);
}

void flySkyIbus2CalGpsGyro(uint8_t* packet, uint8_t* len)
{
  Ibus2DevPara.type = IBUS2_CALIB_SET_PARAM;
  Ibus2DevPara.id = flyskyGpsId;
  Ibus2DevPara.ParameterData[0] = 0x55;
  Ibus2DevPara.ParameterData[1] = 0x01;
  Ibus2DevPara.ParameterData[2] = 0x01;
  setIbus2Param(packet);
  *len = 22;
}

void flySkyIbus2CalGpsAlt()
{
  reset_gps_alt = true;
  reset_baro_alt = true;
}

void flySkyIbus2ReadParamRPM(uint8_t* packet, uint8_t* len)
{
  Ibus2DevPara.type = IBUS2_CALIB_RPM;
  Ibus2DevPara.id = flyskyRpmId;
  getIbus2Param(packet);
  *len = 6;
}

void flySkyIbus2CalibIBC(uint8_t* packet, uint8_t* len, short voltags)
{
  Ibus2DevPara.type = IBUS2_CALIB_SET_PARAM;
  Ibus2DevPara.id = flyskyIbcId;
  Ibus2DevPara.ParameterData[0] = (uint8_t)(voltags & 0xff);
  Ibus2DevPara.ParameterData[1] = (uint8_t)(voltags >> 8);
  setIbus2Param(packet);
  *len = 22;
}

void setIbus2Param(uint8_t* pData) {
  uint8_t n = 0;
  pData[n++] = ( uint8_t )( RX_CMD_CODE_IBUS2_SET_PARAM );
	pData[n++] = ( uint8_t )( RX_CMD_CODE_IBUS2_SET_PARAM >> 8 );
	pData[n++] = 19; //data length
	pData[n++] = Ibus2DevPara.id;
	pData[n++] = Ibus2DevPara.type;
	pData[n++] = Ibus2DevPara.type >> 8;
	pData[n++] = Ibus2DevPara.ParameterData[0];
	pData[n++] = Ibus2DevPara.ParameterData[1];
	pData[n++] = Ibus2DevPara.ParameterData[2];
	pData[n++] = Ibus2DevPara.ParameterData[3];
	pData[n++] = Ibus2DevPara.ParameterData[4];
	pData[n++] = Ibus2DevPara.ParameterData[5];
	pData[n++] = Ibus2DevPara.ParameterData[6];
	pData[n++] = Ibus2DevPara.ParameterData[7];
	pData[n++] = Ibus2DevPara.ParameterData[8];
	pData[n++] = Ibus2DevPara.ParameterData[9];
	pData[n++] = Ibus2DevPara.ParameterData[10];
	pData[n++] = Ibus2DevPara.ParameterData[11];
	pData[n++] = Ibus2DevPara.ParameterData[12];
	pData[n++] = Ibus2DevPara.ParameterData[13];
	pData[n++] = Ibus2DevPara.ParameterData[14];
	pData[n++] = Ibus2DevPara.ParameterData[15];
}

void getIbus2Param(uint8_t* pData) {
  uint8_t n = 0;
  pData[n++] = ( uint8_t )(RX_CMD_CODE_IBUS2_GET_PARAM);
  pData[n++] = ( uint8_t )(RX_CMD_CODE_IBUS2_GET_PARAM >> 8);
  pData[n++] = 3;//data length
  pData[n++] = Ibus2DevPara.id;
	pData[n++] = Ibus2DevPara.type;
	pData[n++] = Ibus2DevPara.type >> 8;
}

void Ibus2ParamCheck(uint8_t* packet, uint8_t len) {
  if (len != 4) {
    return;
  }
  uint8_t id = packet[0];
  uint8_t code = packet[3];
  if (id == flyskyIbcId) {
    ibc_state = code;
  } else if (id == flyskyGpsId) {
    // todo
  } else if (id == flyskyRpmId) {
    // todo
  }
}

uint8_t flyskyIbus2SensorOnLine() {
  uint32_t now = timersGetMsTick();
  uint8_t sensor_on_line = 0;
  if (now - ibc_update_tick < 2000) {
    sensor_on_line |= 1 << afhds3::IBUS2_SENSOR_IBC;
  }
  if (now - gps_update_tick < 2000) {
    sensor_on_line |= 1 << afhds3::IBUS2_SENSOR_GPS;
  }
  if (now - rpm_update_tick < 2000) {
    sensor_on_line |= 1 << afhds3::IBUS2_SENSOR_RPM;
  }
  if (now - pres_update_tick < 2000) {
    sensor_on_line |= 1 << afhds3::IBUS2_SENSOR_PRES;
  }

  return sensor_on_line;
}

void backlightLowInit()
{
  gpio_init(BACKLIGHT_GPIO, GPIO_OUT, GPIO_PIN_SPEED_LOW);
  gpio_clear(BACKLIGHT_GPIO);
}

void backlightInit()
{
  stm32_pulse_init(&_bl_timer, 1000000);

  stm32_pulse_config_output(&_bl_timer, true, LL_TIM_OCMODE_PWM1, 0);

  LL_TIM_SetAutoReload(_bl_timer.TIMx, BACKLIGHT_LEVEL_MAX);

  LL_TIM_EnableCounter(_bl_timer.TIMx);
}

void backlightEnable(uint8_t dutyCycle)
{
  stm32_pulse_set_cmp_val(&_bl_timer, dutyCycle);

  // The panel is LTDC-only and stays initialised; re-init the controller when
  // waking from a fully-off backlight.
  if (dutyCycle && !lastDutyCycle) {
    lcdInit();
  }

  lastDutyCycle = dutyCycle;
}

void lcdOn(){
  // backlightEnable() re-inits the LTDC on the 0->nonzero transition, so no
  // separate lcdInit() here (avoids a double init on wake).
  backlightEnable(BACKLIGHT_LEVEL_MAX);
}

id INTERNAL_MODULE_BOOTCMD(uint8_t enable)
{
  if (enable)
    bsp_output_clear(BSP_RF_BOOT0);
  else
    bsp_output_set(BSP_RF_BOOT0);
}

id boardBLEarlyInit()
{
  timersInit();
  bsp_io_init();
}

id boardBLPreJump()
{
  ExtFLASH_Init();
  SDRAM_Init();

  // Stop 1ms timer
  MS_TIMER->CR1 &= ~TIM_CR1_CEN;
}

id boardBLInit()
{
  ExtFLASH_Init();
  SDRAM_Init();

  // register external FLASH for DFU
  usbRegisterDFUMedia((void*)extflash_dfu_media);

  // register internal & external FLASH for UF2
  flashRegisterDriver(FLASH_BANK1_BASE, BOOTLOADER_SIZE, &stm32_flash_driver);
  flashRegisterDriver(QSPI_BASE, 8 * 1024 * 1024, &extflash_driver);
}

id boardInit()
{
  // enable interrupts
  __enable_irq();

  boardInitModulePorts();

  pwrInit();
  delaysInit();
  timersInit();

  bsp_io_init();
  bsp_output_set(BSP_PWR_LED);

  ExtFLASH_InitRuntime();

  // register internal & external FLASH for UF2
  flashRegisterDriver(FLASH_BANK1_BASE, BOOTLOADER_SIZE, &stm32_flash_driver);
  flashRegisterDriver(QSPI_BASE, QSPI_FLASH_SIZE, &extflash_driver);

  board_trainer_init();

  gpio_init(UCHARGER_CHARGE_END_GPIO, GPIO_IN_PD, GPIO_PIN_SPEED_LOW);

  usbInit();

  gimbalsDetect();

  ledInit();
  rgbLedInit();


  rgbLedClearAll();
  keysInit();
  rotaryEncoderInit();
  switchInit();
  touchPanelInit();
  audioInit();
  adcInit(&_adc_driver);
  hapticInit();

#if defined(RTCLOCK)
  rtcInit(); // RTC must be initialized before rambackupRestore() is called
#endif

  gyroInit();
}

id boardOff()
{
  lcdOff();

  while (pwrPressed()) {
    WDG_RESET();
  }

  SysTick->CTRL = 0; // turn off systick

  // Shutdown the Haptic
  hapticDone();

  rtcDisableBackupReg();

#if !defined(BOOT)
#if defined(LED_STRIP_GPIO)
  rgbLedClearAll();
#endif
#endif
  pwrOff();

  // We reach here only in forced power situations, such as hw-debugging with external power
  // Enter STM32 stop mode / deep-sleep
  // Code snippet from ST Nucleo PWR_EnterStopMode example
#define PDMode             0x00000000U
#if defined(PWR_CR1_MRUDS) && defined(PWR_CR1_LPUDS) && defined(PWR_CR1_FPDS)
  MODIFY_REG(PWR->CR1, (PWR_CR1_PDDS | PWR_CR1_LPDS | PWR_CR1_FPDS | PWR_CR1_LPUDS | PWR_CR1_MRUDS), PDMode);
#elif defined(PWR_CR_MRLVDS) && defined(PWR_CR_LPLVDS) && defined(PWR_CR_FPDS)
  MODIFY_REG(PWR->CR1, (PWR_CR1_PDDS | PWR_CR1_LPDS | PWR_CR1_FPDS | PWR_CR1_LPLVDS | PWR_CR1_MRLVDS), PDMode);
#endif

/* Set SLEEPDEEP bit of Cortex System Control Register */
  SET_BIT(SCB->SCR, ((uint32_t)SCB_SCR_SLEEPDEEP_Msk));

  // To avoid HardFault at return address, end in an endless loop.
  // __WFI() actually enters deep sleep (SLEEPDEEP alone keeps the core spinning).
  while (1) {
    __WFI();
  }
}

static void bsp_input_read()
{
  // this is a fall back, the interrupts from the port extender
  // are unreliable under some circumstances
  static int readCount = 0;
  readCount++;

  if (!updateInputState && readCount < 50) return;

  uint16_t value=0;

  readCount=0;
  updateInputState = false;

  if (pca95xx_read(&input_exp, BSP_IN_MASK, &value) < 0) return;
  inputState = value;
}

int bsp_io_init()
{
  // init outputs
  BSP_CHECK(pca95xx_init(&output_exp, BSP_OUT_I2C_BUS, BSP_OUT_I2C_ADDR));
  BSP_CHECK(pca95xx_write(&output_exp, BSP_OUT_MASK, BSP_RF_BOOT0));
  BSP_CHECK(pca95xx_set_direction(&output_exp, BSP_OUT_MASK, 0));

  bsp_output_set(BSP_EXT_PWR);

  // init inputs
  BSP_CHECK(pca95xx_init(&input_exp, BSP_IN_I2C_BUS, BSP_IN_I2C_ADDR));

  gpio_init_int(GPIO_PIN(GPIOH, 6), GPIO_IN, GPIO_FALLING,
                bsp_port_extender_irq_handler);
  updateInputState = true;
  bsp_input_read();

  return 0;
}

void bsp_output_set(uint16_t pin)
{
  if (pin == BSP_EXT_PWR) {
    pca95xx_write(&output_exp, pin, 0);
  } else {
    pca95xx_write(&output_exp, pin, pin);
  }
}

void bsp_output_clear(uint16_t pin)
{
  if (pin == BSP_EXT_PWR) {
    pca95xx_write(&output_exp, pin, pin);
  } else {
    pca95xx_write(&output_exp, pin, 0);
  }
}

uint16_t bsp_input_get()
{
  bsp_input_read();
  return inputState;
}

SwitchHwPos boardSwitchGetPosition(uint8_t idx)
{
  const stm32_switch_t* sw = boardGetSwitchDef(idx);

  if (sw->type == SWITCH_HW_ADC || sw->GPIOx_high != nullptr)
    return stm32_switch_get_position(sw);

  bool val = false;
  uint16_t pins = bsp_input_get();

  val = (pins & sw->Pin_high) != 0;

  if (sw->inverted) val = !val;

  return val ? SWITCH_HW_UP : SWITCH_HW_DOWN;
}

int32_t ExtFLASH_Init()
{
  if (stm32_qspi_nor_init() != 0) {
    return -1;
  }

  return stm32_qspi_nor_memory_mapped();
}

static uint32_t extflash_get_sector(uint32_t address)
{
  address -= QSPI_BASE;
  return address / (64 * 1024);
}

static uint32_t extflash_get_sector_size(uint32_t sector)
{
  (void)sector;
  return (64 * 1024);
}

static int extflash_erase_sector(uint32_t address)
{
  address -= QSPI_BASE;
  return stm32_qspi_nor_erase_sector(address);
}

static int extflash_program(uint32_t address, void* data, uint32_t len)
{
  address -= QSPI_BASE;

  int ret = 0;
  while (len > 0) {
    uint32_t size = (len > QSPI_NOR_PAGE_SIZE) ? QSPI_NOR_PAGE_SIZE : len;
    ret = stm32_qspi_nor_program(address, data, size);
    if (ret != 0) break;
    len -= size;
    address += size;
    data = (uint8_t*)data + size;
  }

  return ret;
}

static int extflash_read(uint32_t address, void* data, uint32_t len)
{
  address -= QSPI_BASE;
  return stm32_qspi_nor_read(address, data, len);
}

static uint16_t extflash_dfu_erase(uint32_t address)
{
  if (extflash_erase_sector(address) < 0) {
    return USBD_FAIL;
  }
  return USBD_OK;
}

static uint16_t extflash_dfu_write(uint8_t* src, uint8_t* dest, uint32_t len)
{
  if (extflash_program((intptr_t)dest, (void*)src, len) < 0) {
    return USBD_FAIL;
  }
  return USBD_OK;
}

static uint8_t* extflash_dfu_read(uint8_t* src, uint8_t* dest, uint32_t len)
{
  if (extflash_read((intptr_t)src, (void*)dest, len) < 0) {
    return nullptr;
  }
  return dest;
}

static uint16_t extflash_dfu_get_status(uint32_t address, uint8_t cmd, uint8_t *buffer)
{
  switch (cmd) {
    case DFU_MEDIA_PROGRAM:
      buffer[1] = 1;
      buffer[2] = 0;
      buffer[3] = 0;
      break;

    case DFU_MEDIA_ERASE:
    default:
      buffer[1] = 20;
      buffer[2] = 0;
      buffer[3] = 0;
      break;
  }

  return USBD_OK;
}

void hapticInit(void)
{
  stm32_pulse_init(&_haptic_timer, 10000);
  stm32_pulse_config_output(&_haptic_timer, true, LL_TIM_OCMODE_PWM1, 0);
  LL_TIM_SetAutoReload(_haptic_timer.TIMx, 100);
  LL_TIM_EnableCounter(_haptic_timer.TIMx);
}

void hapticOn(uint32_t pwmPercent)
{
  if (pwmPercent > 100) pwmPercent = 100;
  stm32_pulse_set_cmp_val(&_haptic_timer, pwmPercent);
}

uint32_t readTrims()
{
  uint32_t result = 0;

  if (suspendI2CTasks) return result;

  uint16_t keys = bsp_input_get();

#define _TRIM(t) \
  if ((keys & BSP_##t) == 0) result |= 1 << t;

  _TRIM(TR1U);
  _TRIM(TR1D);
  _TRIM(TR3L);
  _TRIM(TR3R);
  _TRIM(TR2U);
  _TRIM(TR2D);
  _TRIM(TR4L);
  _TRIM(TR4R);

#undef _TRIM

  return result;
}

static void startLcdRefresh(lv_disp_drv_t *disp_drv, uint16_t *buffer,
                            const rect_t &copy_area)
{
  (void)disp_drv;
  (void)copy_area;

  // given the data cache size, this is probably
  // faster than cleaning by address
  SCB_CleanDCache();

  LTDC_Layer1->CFBAR = (uint32_t)buffer;

  // reload shadow registers on vertical blank
  _frame_addr_reloaded = 0;
  LTDC->SRCR = LTDC_SRCR_VBR;

  __HAL_LTDC_ENABLE_IT(&hltdc, LTDC_IT_LI);

  // wait for reload
  // TODO: replace through some smarter mechanism without busy wait
  while(_frame_addr_reloaded == 0);
}

