void SDRAM_InitSequence(void)
{
  FMC_SDRAM_CommandTypeDef FMC_SDRAMCommandStructure;
  uint32_t tmpr = 0;

  /* Step 3: clock configuration enable command */
  FMC_SDRAMCommandStructure.CommandMode = FMC_SDRAM_CMD_CLK_ENABLE;
  FMC_SDRAMCommandStructure.CommandTarget = FMC_SDRAM_CMD_TARGET_BANK1;
  FMC_SDRAMCommandStructure.AutoRefreshNumber = 1;
  FMC_SDRAMCommandStructure.ModeRegisterDefinition = 0;
  FMC_SDRAM_SendCommand(FMC_Bank5_6_R, &FMC_SDRAMCommandStructure, 10);

  /* Step 4: insert delay */
  delay_ms(100);

  /* Step 5: PALL (precharge all) command */
  FMC_SDRAMCommandStructure.CommandMode = FMC_SDRAM_CMD_PALL;
  FMC_SDRAMCommandStructure.CommandTarget = FMC_SDRAM_CMD_TARGET_BANK1;
  FMC_SDRAMCommandStructure.AutoRefreshNumber = 1;
  FMC_SDRAMCommandStructure.ModeRegisterDefinition = 0;
  FMC_SDRAM_SendCommand(FMC_Bank5_6_R, &FMC_SDRAMCommandStructure, 10);

  /* Step 6: Auto-Refresh command */
  FMC_SDRAMCommandStructure.CommandMode = FMC_SDRAM_CMD_AUTOREFRESH_MODE;
  FMC_SDRAMCommandStructure.CommandTarget = FMC_SDRAM_CMD_TARGET_BANK1;
  FMC_SDRAMCommandStructure.AutoRefreshNumber = 8;
  FMC_SDRAMCommandStructure.ModeRegisterDefinition = 0;
  FMC_SDRAM_SendCommand(FMC_Bank5_6_R, &FMC_SDRAMCommandStructure, 10);

  /* Step 7: program the external memory mode register */
  tmpr = (uint32_t)SDRAM_MODEREG_BURST_LENGTH_2 |
         SDRAM_MODEREG_BURST_TYPE_SEQUENTIAL |
         SDRAM_MODEREG_CAS_LATENCY_3 |
         SDRAM_MODEREG_OPERATING_MODE_STANDARD |
         SDRAM_MODEREG_WRITEBURST_MODE_SINGLE;

  FMC_SDRAMCommandStructure.CommandMode = FMC_SDRAM_CMD_LOAD_MODE;
  FMC_SDRAMCommandStructure.CommandTarget = FMC_SDRAM_CMD_TARGET_BANK1;
  FMC_SDRAMCommandStructure.AutoRefreshNumber = 1;
  FMC_SDRAMCommandStructure.ModeRegisterDefinition = tmpr;
  FMC_SDRAM_SendCommand(FMC_Bank5_6_R, &FMC_SDRAMCommandStructure, 10);

  /* Step 8: refresh rate counter — (15.62 us x Freq) - 20 */
  FMC_SDRAM_SetAutoRefreshNumber(FMC_Bank5_6_R, 15);
  FMC_SDRAM_ProgramRefreshRate(FMC_Bank5_6_R, 1855);
}

id SDRAM_Init(void)
{
  //delay funcion needed
  delaysInit();

  /* GPIO configuration for FMC SDRAM bank */
  SDRAM_GPIOConfig();

  /* Enable FMC clock */
  LL_AHB3_GRP1_EnableClock(LL_AHB3_GRP1_PERIPH_FMC);

  /* FMC Configuration ---------------------------------------------------------*/
  FMC_SDRAM_InitTypeDef  FMC_SDRAMInitStructure;
  FMC_SDRAM_TimingTypeDef  FMC_SDRAMTimingInitStructure;

  /* FMC SDRAM Bank configuration */
  /* Timing configuration for 80 Mhz of SD clock */
  FMC_SDRAMTimingInitStructure.LoadToActiveDelay    = 2;
  FMC_SDRAMTimingInitStructure.ExitSelfRefreshDelay = 7;
  FMC_SDRAMTimingInitStructure.SelfRefreshTime      = 4;
  FMC_SDRAMTimingInitStructure.RowCycleDelay        = 7;
  FMC_SDRAMTimingInitStructure.WriteRecoveryTime    = 3;
  FMC_SDRAMTimingInitStructure.RPDelay              = 2;
  FMC_SDRAMTimingInitStructure.RCDDelay             = 2;

  /* FMC SDRAM control configuration */
  FMC_SDRAMInitStructure.SDBank = FMC_SDRAM_BANK1;
  FMC_SDRAMInitStructure.ColumnBitsNumber = FMC_SDRAM_COLUMN_BITS_NUM_8;
  FMC_SDRAMInitStructure.RowBitsNumber = FMC_SDRAM_ROW_BITS_NUM_12;
  FMC_SDRAMInitStructure.MemoryDataWidth = FMC_SDRAM_MEM_BUS_WIDTH_16;
  FMC_SDRAMInitStructure.InternalBankNumber = FMC_SDRAM_INTERN_BANKS_NUM_4;
  FMC_SDRAMInitStructure.CASLatency = FMC_SDRAM_CAS_LATENCY_3;
  FMC_SDRAMInitStructure.WriteProtection = FMC_SDRAM_WRITE_PROTECTION_DISABLE;
  FMC_SDRAMInitStructure.SDClockPeriod = FMC_SDRAM_CLOCK_PERIOD_2;
  FMC_SDRAMInitStructure.ReadBurst = FMC_SDRAM_RBURST_ENABLE;
  FMC_SDRAMInitStructure.ReadPipeDelay = FMC_SDRAM_RPIPE_DELAY_0;

  /* FMC SDRAM bank initialization */
  FMC_SDRAM_Init(FMC_Bank5_6_R, &FMC_SDRAMInitStructure);
  FMC_SDRAM_Timing_Init(FMC_Bank5_6_R, &FMC_SDRAMTimingInitStructure, FMC_SDRAM_BANK1);

  __FMC_ENABLE();

  /* FMC SDRAM device initialization sequence */
  SDRAM_InitSequence();
}

BOOTSTRAP void SystemClock_Config(void)
{
  /* Power Configuration */
  LL_PWR_ConfigSupply(LL_PWR_LDO_SUPPLY);
  LL_PWR_SetRegulVoltageScaling(LL_PWR_REGU_VOLTAGE_SCALE1);
  while (LL_PWR_IsActiveFlag_VOS() == 0){
  }

  /* Enable HSE oscillator */
  LL_RCC_HSE_Enable();
  while (LL_RCC_HSE_IsReady() != 1) {
  }

  /* Set FLASH latency */
  LL_FLASH_SetLatency(LL_FLASH_LATENCY_5);

  /* Main PLL configuration and activation */
  LL_RCC_PLL_SetSource(LL_RCC_PLLSOURCE_HSE);
  LL_RCC_PLL1P_Enable();
  LL_RCC_PLL1Q_Enable();
  LL_RCC_PLL1R_Enable();
  LL_RCC_PLL1FRACN_Disable();
  LL_RCC_PLL1_SetVCOInputRange(LL_RCC_PLLINPUTRANGE_2_4);
  LL_RCC_PLL1_SetVCOOutputRange(LL_RCC_PLLVCORANGE_WIDE);
  LL_RCC_PLL1_SetM(1);
  LL_RCC_PLL1_SetN(100);
  LL_RCC_PLL1_SetP(2);
  LL_RCC_PLL1_SetQ(4);
  LL_RCC_PLL1_SetR(2);
  LL_RCC_PLL1_Enable();
  while (LL_RCC_PLL1_IsReady() != 1) {
  }

  /* Set Sys & AHB & APB1 & APB2 & APB4  prescaler */
  LL_RCC_SetSysPrescaler(LL_RCC_SYSCLK_DIV_1);
  LL_RCC_SetAHBPrescaler(LL_RCC_AHB_DIV_2);
  LL_RCC_SetAPB1Prescaler(LL_RCC_APB1_DIV_2);
  LL_RCC_SetAPB2Prescaler(LL_RCC_APB2_DIV_2);
  LL_RCC_SetAPB4Prescaler(LL_RCC_APB4_DIV_2);

  /* Set PLL1 as System Clock Source */
  LL_RCC_SetSysClkSource(LL_RCC_SYS_CLKSOURCE_PLL1);
  while (LL_RCC_GetSysClkSource() != LL_RCC_SYS_CLKSOURCE_STATUS_PLL1) {
  }

  /* Config & activate PLL2 */
  LL_RCC_PLL2P_Enable();
  LL_RCC_PLL2Q_Enable();
  LL_RCC_PLL2R_Enable();
  LL_RCC_PLL2FRACN_Disable();
  LL_RCC_PLL2_SetVCOInputRange(LL_RCC_PLLINPUTRANGE_2_4);
  LL_RCC_PLL2_SetVCOOutputRange(LL_RCC_PLLVCORANGE_WIDE);
  LL_RCC_PLL2_SetM(1);
  LL_RCC_PLL2_SetN(120);
  LL_RCC_PLL2_SetP(12);
  LL_RCC_PLL2_SetQ(2);
  LL_RCC_PLL2_SetR(4);
  LL_RCC_PLL2_Enable();
  while (LL_RCC_PLL2_IsReady() != 1) {
  }

  /* Config & activate PLL3 */
  LL_RCC_PLL3P_Enable();
  LL_RCC_PLL3Q_Enable();
  LL_RCC_PLL3R_Enable();
  LL_RCC_PLL3FRACN_Disable();
  LL_RCC_PLL3_SetVCOInputRange(LL_RCC_PLLINPUTRANGE_2_4);
  LL_RCC_PLL3_SetVCOOutputRange(LL_RCC_PLLVCORANGE_WIDE);
  LL_RCC_PLL3_SetM(1);
  LL_RCC_PLL3_SetN(120);
  LL_RCC_PLL3_SetP(5);
  LL_RCC_PLL3_SetQ(20);
  LL_RCC_PLL3_SetR(80);
  LL_RCC_PLL3_Enable();
  while (LL_RCC_PLL3_IsReady() != 1) {
  }

  /* Enable SRAM1, SRAM2 & SRAM3 */
  LL_AHB2_GRP1_EnableClock(LL_AHB2_GRP1_PERIPH_D2SRAM1 |
                           LL_AHB2_GRP1_PERIPH_D2SRAM2 |
                           LL_AHB2_GRP1_PERIPH_D2SRAM3);

  /* Set periph clock sources */
  LL_RCC_SetFMCClockSource(LL_RCC_FMC_CLKSOURCE_HCLK);
  LL_RCC_SetSPIClockSource(LL_RCC_SPI123_CLKSOURCE_PLL3P);
  LL_RCC_SetUSBClockSource(LL_RCC_USB_CLKSOURCE_PLL3Q);
  LL_RCC_SetADCClockSource(LL_RCC_ADC_CLKSOURCE_CLKP);
}

oid I2C_Init_Radio(void)
{
  TRACE("GT911 I2C Init");

  if (i2c_init(TOUCH_I2C_BUS) < 0) {
    TRACE("GT911 ERROR: i2c_init failed");
    return;
  }
}

ool I2C_GT911_WriteRegister(uint16_t reg, uint8_t *buf, uint8_t len)
{
  uint8_t uAddrAndBuf[258];
  uAddrAndBuf[0] = (uint8_t)((reg & 0xFF00) >> 8);
  uAddrAndBuf[1] = (uint8_t)(reg & 0x00FF);

  if (len > 0) {
    for (int i = 0; i < len; i++) {
      uAddrAndBuf[i + 2] = buf[i];
    }
  }

  if (stm32_i2c_master_tx(TOUCH_I2C_BUS, GT911_I2C_ADDR, uAddrAndBuf, len + 2,
                          100) < 0) {
    TRACE("I2C B1 ERROR: WriteRegister failed");
    return false;
  }
  return true;
}

ool I2C_GT911_ReadRegister(uint16_t reg, uint8_t *buf, uint8_t len)
{
  uint8_t uRegAddr[2];
  uRegAddr[0] = (uint8_t)((reg & 0xFF00) >> 8);
  uRegAddr[1] = (uint8_t)(reg & 0x00FF);

  if (stm32_i2c_master_tx(TOUCH_I2C_BUS, GT911_I2C_ADDR, uRegAddr, 2, 10) < 0) {
    TRACE("I2C B1 ERROR: ReadRegister write reg address failed");
    return false;
  }

  if (stm32_i2c_master_rx(TOUCH_I2C_BUS, GT911_I2C_ADDR, buf, len, 100) < 0) {
    TRACE("I2C B1 ERROR: ReadRegister read reg address failed");
    return false;
  }
  return true;
}

ool I2C_GT911_SendConfig(uint8_t cfgVer)
{
  uint8_t buf[2] = { cfgVer, 1 };
  bool bResult = true;

  for (uint8_t i = 1; i < sizeof(TOUCH_GT911_Cfg); i++) {
    buf[0] += TOUCH_GT911_Cfg[i]; //check sum
  }

  buf[0] = (~buf[0]) + 1;

  if (!I2C_GT911_WriteRegister(GT911_CONFIG_REG, (uint8_t *)&cfgVer, 1)) {
    TRACE("GT911 ERROR: write config failed");
    bResult = false;
  }

  if (!I2C_GT911_WriteRegister(GT911_CONFIG_REG+1, (uint8_t *)&TOUCH_GT911_Cfg[1],
                               sizeof(TOUCH_GT911_Cfg)-1)) {
    TRACE("GT911 ERROR: write config failed");
    bResult = false;
  }

  // write checksum and config_fresh
  if (!I2C_GT911_WriteRegister(GT911_CONFIG_CHECKSUM_REG, buf, 2)) {
    TRACE("GT911 ERROR: write config checksum failed");
    bResult = false;
  }

  return bResult;
}

oid touchPanelDeInit(void)
{
  gpio_int_disable(TOUCH_INT_GPIO);
  touchGT911Flag = false;
}

ool touchPanelInit(void)
{
  uint8_t tmp[4] = {0};

  if (touchGT911Flag) {
    gpio_init_int(TOUCH_INT_GPIO, GPIO_IN_PU, GPIO_RISING, _gt911_exti_isr);
    return true;
  } else {
    TRACE("Touchpanel init start ...");

    gpio_init(TOUCH_RST_GPIO, GPIO_OUT, GPIO_PIN_SPEED_LOW);
    gpio_init(TOUCH_INT_GPIO, GPIO_OUT, GPIO_PIN_SPEED_LOW);
    I2C_Init_Radio();

    gpio_clear(TOUCH_RST_GPIO);
    gpio_set(TOUCH_INT_GPIO);
    delay_us(200);

    gpio_set(TOUCH_RST_GPIO);
    delay_ms(6);

    gpio_clear(TOUCH_INT_GPIO);
    delay_ms(55);

    gpio_init(TOUCH_INT_GPIO, GPIO_IN_PU, GPIO_PIN_SPEED_LOW);

    delay_ms(50);

    TRACE("Reading Touch registry");
    if (!I2C_GT911_ReadRegister(GT911_PRODUCT_ID_REG, tmp, 4)) {
      TRACE("GT911 ERROR: Product ID read failed");
    }

    if (strcmp((char *)tmp, TP_GT911_ID) == 0) {
      TRACE("GT911 chip detected");
      tmp[0] = 0X02;
      if (!I2C_GT911_WriteRegister(GT911_COMMAND_REG, tmp, 1)) {
        TRACE("GT911 ERROR: write to control register failed");
      }
      if (!I2C_GT911_ReadRegister(GT911_CONFIG_REG, tmp, 1)) {
        TRACE("GT911 ERROR: configuration register read failed");
      }

      TRACE("Chip config Ver:%x", tmp[0]);
      if ((tp_gt911_cfgVer == 0) || (tmp[0] < tp_gt911_cfgVer)) { // Config ver
        TRACE("Sending new config %d", GT911_CFG_NUMBER);
        if (!I2C_GT911_SendConfig(tp_gt911_cfgVer)) {
          TRACE("GT911 ERROR: sending configration failed");
        }
        if (!I2C_GT911_ReadRegister(GT911_CONFIG_REG, tmp, 1)) {
          TRACE("GT911 ERROR: configuration register read failed");
        }
        tp_gt911_cfgVer = tmp[0];
      }

      if (!I2C_GT911_ReadRegister(GT911_FIRMWARE_VERSION_REG, tmp, 2)) {
        TRACE("GT911 ERROR: reading firmware version failed");
      } else {
        touchGT911fwver = (tmp[1] << 8) + tmp[0];
        TRACE("GT911 FW version: %u", touchGT911fwver);
      }

      delay_ms(10);
      tmp[0] = 0X00;
      if (!I2C_GT911_WriteRegister(GT911_COMMAND_REG, tmp, 1)) { // end reset
        TRACE("GT911 ERROR: write to command register failed");
      }
      touchGT911Flag = true;

      gpio_init_int(TOUCH_INT_GPIO, GPIO_IN_PU, GPIO_RISING, _gt911_exti_isr);

      return true;
    }
    TRACE("GT911 chip NOT FOUND");
    return false;
  }
}

ool I2C_ReInit(void)
{
  TRACE("I2C B1 ReInit");
  touchPanelDeInit();
  if (stm32_i2c_deinit(TOUCH_I2C_BUS) < 0)
    TRACE("I2C B1 ReInit - I2C DeInit failed");

  // If DeInit fails, try to re-init anyway
  if (!touchPanelInit()) {
    TRACE("I2C B1 ReInit - touchPanelInit failed");
    return false;
  }
  return true;
}

tatic const char *event2str(uint8_t ev)
{
  switch (ev) {
    case TE_NONE:
      return "NONE";
    case TE_UP:
      return "UP";
    case TE_DOWN:
      return "DOWN";
    case TE_SLIDE_END:
      return "SLIDE_END";
    case TE_SLIDE:
      return "SLIDE";
    default:
      return "UNKNOWN";
  }
}

truct TouchState touchPanelRead()
{
  uint8_t state = 0;
  static bool gt911_needTranspose = true;      // 是否需要旋转
  if (!touchEventOccured) return internalTouchState;
#if defined(CSD203_SENSOR)
  for(int a=0;a<6;a++)
  {//IIC bus preemption
    if(IICReadStatusFlag==false){
      IICReadStatusFlag=true;
      break;
    } 
    else if(a>6){
      return internalTouchState;
    }
    delay_us(10);
  }
#endif  

  touchEventOccured = false;

  uint32_t startReadStatus = timersGetMsTick();
  do {
    if (!I2C_GT911_ReadRegister(GT911_READ_XY_REG, &state, 1)) {
      // ledRed();
      touchGT911hiccups++;
      TRACE("GT911 I2C read XY error");
      if (!I2C_ReInit()) TRACE("I2C B1 ReInit failed");
    #if defined(CSD203_SENSOR)
      IICReadStatusFlag=false;
    #endif  
      return internalTouchState;
    }

    if (state & 0x80u) {
      // ready
      break;
    }
    sleep_ms(1);
  } while (timersGetMsTick() - startReadStatus < GT911_TIMEOUT);

  internalTouchState.deltaX = 0;
  internalTouchState.deltaY = 0;
  TRACE("touch state = 0x%x", state);
  if (state & 0x80u) {
    uint8_t pointsCount = (state & 0x0Fu);
    uint32_t now = timersGetMsTick();
    internalTouchState.tapCount = 0;

    if (pointsCount > 0 && pointsCount <= GT911_MAX_TP) {
      if (!I2C_GT911_ReadRegister(GT911_READ_XY_REG + 1, touchData.data,
                                  pointsCount * sizeof(TouchPoint))) {
        // ledRed();
        touchGT911hiccups++;
        TRACE("GT911 I2C data read error");
        if (!I2C_ReInit()) TRACE("I2C B1 ReInit failed");
      #if defined(CSD203_SENSOR)
        IICReadStatusFlag=false;
      #endif  
        return internalTouchState;
      }

      // Rotate the raw touch point into screen coordinates up-front, so that
      // position, start position and slide deltas all live in the same
      // coordinate space. (Computing deltas from raw points against a
      // previously-rotated internalTouchState would otherwise yield wrong
      // slide/scroll deltas, e.g. for GT911_ROTATION_MODE == 180.)
      coord_t px = touchData.points[0].x;
      coord_t py = touchData.points[0].y;
      if (gt911_needTranspose) {
        coord_t rawX = px, rawY = py;
        switch (GT911_ROTATION_MODE) {
          case 90:
            px = LCD_H - rawY - 1;
            py = rawX;
            break;
          case 180:
            px = LCD_W - rawX - 1;
            py = LCD_H - rawY - 1;
            break;
          case 270:
            px = rawY;
            py = LCD_W - rawX - 1;
            break;
          default:
            break;
        }
      }

      if (internalTouchState.event == TE_NONE ||
          internalTouchState.event == TE_UP ||
          internalTouchState.event == TE_SLIDE_END) {
        internalTouchState.event = TE_DOWN;
        internalTouchState.startX = internalTouchState.x = px;
        internalTouchState.startY = internalTouchState.y = py;
        downTime = now;
      } else {
        internalTouchState.deltaX = px - internalTouchState.x;
        internalTouchState.deltaY = py - internalTouchState.y;
        if (internalTouchState.event == TE_SLIDE ||
            abs(internalTouchState.deltaX) >= SLIDE_RANGE ||
            abs(internalTouchState.deltaY) >= SLIDE_RANGE) {
          internalTouchState.event = TE_SLIDE;
          internalTouchState.x = px;
          internalTouchState.y = py;
        }
      }
    } else {
      if (internalTouchState.event == TE_SLIDE) {
        internalTouchState.event = TE_SLIDE_END;
      } else if (internalTouchState.event == TE_DOWN) {
        internalTouchState.event = TE_UP;
        if (now - downTime <= GT911_TAP_TIME) {
          if (now - tapTime > GT911_TAP_TIME)
            tapCount = 1;
          else
            tapCount++;
          internalTouchState.tapCount = tapCount;
          tapTime = now;
        }
      } else {
        internalTouchState.event = TE_NONE;
      }
    }
  }

  uint8_t zero = 0;
  if (!I2C_GT911_WriteRegister(GT911_READ_XY_REG, &zero, 1)) {
    TRACE("GT911 ERROR: clearing XY register failed");
  }

  TRACE("touch event = %s", event2str(internalTouchState.event));
#if defined(CSD203_SENSOR)
  IICReadStatusFlag=false;
#endif
  return internalTouchState;
}

