TEST(FunctionSwitches, holdIsNotRepeatedToggle)
{
  MODEL_RESET();
  setModelDefaults();
  switchInit();

  for (uint8_t i = 0; i < switchGetMaxSwitches(); i++) {
    if (!switchIsCustomSwitch(i)) continue;
    // Toggle type with no group, so a phantom "switch moved" event
    // flips the logical state and is observable
    g_model.cfsSetType(i, SWITCH_TOGGLE);
    g_model.cfsSetGroup(i, 0);
    simuSetSwitch(i, -1);
  }

  setFSStartupPosition();
  evalFunctionSwitches();  // sync previous state with all switches released

  for (uint8_t i = 0; i < switchGetMaxSwitches(); i++) {
    if (!switchIsCustomSwitch(i)) continue;

    bool released = g_model.cfsState(i);
    simuSetSwitch(i, 1);
    evalFunctionSwitches();
    bool pressed = g_model.cfsState(i);
    EXPECT_NE(released, pressed) << "press did not toggle switch index " << (int)i;

    // holding the switch must not generate further toggles
    evalFunctionSwitches();
    EXPECT_EQ(pressed, g_model.cfsState(i))
        << "hold re-toggled switch index " << (int)i;
    evalFunctionSwitches();
    EXPECT_EQ(pressed, g_model.cfsState(i))
        << "hold re-toggled switch index " << (int)i;

    simuSetSwitch(i, -1);
    evalFunctionSwitches();
  }
}

TEST(FrSkyDataClear, InitialisesAllSerialisedFields)
{
  FrSkyData fs;
  memset(reinterpret_cast<void*>(&fs), 0x2D, sizeof(fs));  // 0x2D == 45
  fs.clear();

  EXPECT_FALSE(fs.varioCenterSilent)
      << "varioCenterSilent left uninitialised by FrSkyData::clear()";
  EXPECT_FALSE(fs.ignoreSensorIds)
      << "ignoreSensorIds left uninitialised by FrSkyData::clear()";
}

EST(BoundedString, AssignTruncatesToCapacity)
{
  BoundedString<16> bs;
  bs = std::string(40, 'A');
  EXPECT_EQ(16u, bs.size());
  EXPECT_EQ(std::string(16, 'A'), bs.str());
}

EST(BoundedString, ShortValueIsUntouched)
{
  BoundedString<16> bs("model1.yml");
  EXPECT_EQ("model1.yml", bs.str());
  EXPECT_FALSE(bs.empty());
}

EST(BoundedString, AssignFromVariousSources)
{
  BoundedString<16> a("c-string");
  BoundedString<16> b(std::string("std-string"));
  BoundedString<16> c(QString("qstring"));
  EXPECT_EQ("c-string", a.str());
  EXPECT_EQ("std-string", b.str());
  EXPECT_EQ("qstring", c.str());
  EXPECT_EQ(QString("qstring"), c.toQString());
}

EST(BoundedString, NullCStringIsEmpty)
{
  const char* p = nullptr;
  BoundedString<16> bs(p);
  EXPECT_TRUE(bs.empty());
}

EST(BoundedString, Comparison)
{
  BoundedString<16> a("abc");
  BoundedString<16> b("abc");
  BoundedString<16> c("xyz");
  EXPECT_TRUE(a == b);
  EXPECT_TRUE(a != c);
  EXPECT_TRUE(a == std::string("abc"));
  EXPECT_TRUE(a != std::string("abcd"));
  EXPECT_TRUE(a == "abc");        // const char*
}

EST(BoundedString, YamlRoundTrip)
{
  for (const auto& in : kInputs) {
    BoundedString<16> src(in);  // truncates on construction
    YAML::Node node;
    node["v"] = src;

    BoundedString<16> dst;
    node["v"] >> dst;

    EXPECT_EQ(src.str(), dst.str()) << "round-trip mismatch for input: " << in;
  }
}

EST(BoundedString, YamlDecodeTruncatesOverlongScalar)
{
  // A malicious/oversized scalar must be clamped on decode, not overflow.
  YAML::Node node;
  node["v"] = std::string(200, 'Z');

  BoundedString<16> dst;
  node["v"] >> dst;
  EXPECT_EQ(16u, dst.size());
}

EST(BoundedString, MatchesLegacyCharArrayOnDecode)
{
  constexpr size_t CAP = 16;
  for (const auto& in : kInputs) {
    YAML::Node node;
    node["v"] = in;

    char legacy[CAP + 1] = {0};
    node["v"] >> legacy;

    BoundedString<CAP> modern;
    node["v"] >> modern;

    EXPECT_EQ(std::string(legacy), modern.str())
        << "decode diverged from legacy char[] for input: " << in;
  }
}

EST(BoundedString, MatchesLegacyCharArrayOnEncode)
{
  constexpr size_t CAP = 16;
  for (const auto& in : kInputs) {
    char legacy[CAP + 1] = {0};
    {
      // seed the legacy buffer the same way decode would
      YAML::Node seed;
      seed["v"] = in;
      seed["v"] >> legacy;
    }
    BoundedString<CAP> modern(in);

    YAML::Node a, b;
    a["v"] = legacy;
    b["v"] = modern;

    YAML::Emitter ea, eb;
    ea << a;
    eb << b;
    EXPECT_EQ(std::string(ea.c_str()), std::string(eb.c_str()))
        << "encode diverged from legacy char[] for input: " << in;
  }
}

ModelData roundTrip(const ModelData& in, QByteArray& yamlOut)
{
  writeModelToYaml(in, yamlOut);
  ModelData out;
  out.clear();
  loadModelFromYaml(out, yamlOut);
  return out;
}

void SetUp() override
  {
    Firmware::setCurrentVariant(Firmware::getFirmwareForFlavour("tx16s"));
    ASSERT_NE(getCurrentFirmware(), nullptr)
        << "tx16s firmware must be registered for this test";
  }

TEST_F(ModelYamlRoundTrip, HeaderFieldsSurviveAndAreStable)
{
  struct Case { const char* name; const char* labels; };
  const std::vector<Case> corpus = {
    {"MyModel",         "fav,race"},
    {"ABCDEFGHIJKLMNO", "alpha,bravo"},     // name exactly at the 15-char limit
    {"",                ""},                 // empty model
    {"Plane01",         "fav"},
    {"Heli3D",          "race,fav,park,3d,heli,test"},
  };

  for (const auto& c : corpus) {
    ModelData m;
    m.clear();
    m.used = true;
    m.name = c.name;
    m.labels = c.labels;

    QByteArray y1;
    ModelData m2 = roundTrip(m, y1);

    EXPECT_EQ(m.name.str(),   m2.name.str())   << "name lost for: "   << c.name;
    EXPECT_EQ(m.labels.str(), m2.labels.str()) << "labels lost for: " << c.name;

    // Fixed point at the field level: reloading the re-serialised model
    // yields the same field bytes. (We deliberately do NOT compare the whole
    // YAML document -- it round-trips unrelated non-string fields that have
    // pre-existing non-idempotencies, e.g. varioData.centerSilent.)
    QByteArray y2;
    ModelData m3 = roundTrip(m2, y2);

    EXPECT_EQ(m2.name.str(),   m3.name.str());
    EXPECT_EQ(m2.labels.str(), m3.labels.str());
  }
}

TEST_F(ModelYamlRoundTrip, OverlongNameTruncatesAndRoundTrips)
{
  ModelData m;
  m.clear();
  m.used = true;
  m.name = std::string(40, 'N');  // capacity is MODEL_NAME_LEN (15)

  ASSERT_EQ(m.name.size(), (size_t)MODEL_NAME_LEN);

  QByteArray y1;
  ModelData m2 = roundTrip(m, y1);
  EXPECT_EQ(m.name.str(), m2.name.str());

  // The truncated value is a fixed point: no further loss or growth.
  QByteArray y2;
  ModelData m3 = roundTrip(m2, y2);
  EXPECT_EQ(m2.name.str(), m3.name.str());
}

ComponentReleaseData & ComponentReleaseData::operator= (const ComponentReleaseData & rhs)
{
  for (int i = metaObject()->propertyOffset(), e = metaObject()->propertyCount(); i < e; ++i) {
    const QMetaProperty & prop = metaObject()->property(i);
    if (!prop.isValid() || !prop.isWritable()) {
      qWarning() << "Could not copy property" << QString(prop.name()) << "isValid:" << prop.isValid() << "isWritable:" << prop.isWritable();
      continue;
    }
    prop.write(this, prop.read(&rhs));
  }
  return *this;
}

ComponentReleaseData & Profile::getCompRelease(int index)
{
  if (index > -1 && index < MAX_COMPONENTS)
    return compRelease[index];

  return compRelease[0];
}

const ComponentReleaseData & Profile::getCompRelease(int index) const
{
  if (index > -1 && index < MAX_COMPONENTS)
    return compRelease[index];

  return compRelease[0];
}

ter(lua_State *L, const void *p, size_t size, void *ud) {
  (void)L; (void)ud;
  if (out_len + size > out_cap) {
    size_t new_cap = out_cap ? out_cap * 2 : 4096;
    while (new_cap < out_len + size)
      new_cap *= 2;
    unsigned char *nb = realloc(out_buf, new_cap);
    if (!nb) return 1;
    out_buf = nb;
    out_cap = new_cap;
  }
  memcpy(out_buf + out_len, p, size);
  out_len += size;
  return 0;
}

/* ---------

T(compile)(const char *source, int source_len, int strip) {
  error_msg[0] = '\0';
  error_len = 0;

  /* reset output */
  free(out_buf);
  out_buf = NULL;
  out_len = 0;
  out_cap = 0;

  lua_State *L = luaL_newstate();
  if (!L) return -1;

  int status = luaL_loadbuffer(L, source, (size_t)source_len, "input");
  if (status != LUA_OK) {
    const char *err = lua_tostring(L, -1);
    if (err) {
      size_t n = strlen(err);
      if (n >= sizeof(error_msg)) n = sizeof(error_msg) - 1;
      memcpy(error_msg, err, n);
      error_msg[n] = '\0';
      error_len = (int)n;
    }
    lua_close(L);
    return -2;
  }

  /* The compiled chunk is a function at the top of the stack.
   * lua_dump serialises it via the writer callback. */
  status = lua_dump(L, writer, NULL, strip);
  lua_close(L);

  return status == 0 ? (int)out_len : -3;
}

