void WASM_EX

id pdmStart()
{
  if (pdmRunning) return;

  // Per-session state reset. Must happen before the DMA starts producing data
  // so the audio-task path never sees a half-reset filter.
  cic_i1 = cic_i2 = cic_i3 = 0;
  cic_p1 = cic_p2 = cic_p3 = 0;
  cic_bitsSeen = 0;
  pdmRingReadPos = 0;
  lastSoundLevel = 0;

  gpio_init_af(PDM_CLOCK, PDM_CLOCK_GPIO_AF, GPIO_PIN_SPEED_VERY_HIGH);
  gpio_init(PDM_DATA, GPIO_IN, GPIO_PIN_SPEED_VERY_HIGH);

  SET_BIT(RCC->APB2ENR, RCC_APB2ENR_SAI1EN);
  (void)READ_BIT(RCC->APB2ENR, RCC_APB2ENR_SAI1EN);

  SAI_Block_TypeDef* block = PDM_SAI_BLOCK;

  CLEAR_BIT(block->CR1, SAI_xCR1_SAIEN);
  while (READ_BIT(block->CR1, SAI_xCR1_SAIEN)) {}

  block->CR1 = (0U << SAI_xCR1_MODE_Pos)       // Master TX
             | (0U << SAI_xCR1_PRTCFG_Pos)     // Free protocol
             | (4U << SAI_xCR1_DS_Pos)         // 16-bit data
             | SAI_xCR1_NODIV                  // BCLK = ker_ck / MCKDIV
             | (PDM_SAI_MCKDIV << SAI_xCR1_MCKDIV_Pos);

  block->CR2 = (1U << SAI_xCR2_FTH_Pos);       // FIFO threshold = 1/4 full

  block->FRCR = (15U << 0)                      // FRL = 15 (16-bit frame)
              | (7U  << 8);                     // FSALL = 7
  block->SLOTR = (0U << 8)                      // NBSLOT = 0 -> 1 slot
               | (1U << 16);                    // SLOTEN slot 0

  // Prime the FIFO so the block starts clocking immediately (no underrun).
  for (int i = 0; i < 4; ++i) block->DR = 0U;

  SET_BIT(block->CR1, SAI_xCR1_SAIEN);

  // TIM15 is free because FLYSKY_GIMBAL is OFF.
  SET_BIT(RCC->APB2ENR, RCC_APB2ENR_TIM15EN);
  (void)READ_BIT(RCC->APB2ENR, RCC_APB2ENR_TIM15EN);

  stm32_dma_enable_clock(PDM_CAPTURE_DMA);

  PDM_CAPTURE_TIMER->CR1 = 0;
  PDM_CAPTURE_TIMER->PSC = 0;
  PDM_CAPTURE_TIMER->ARR = (PDM_CAPTURE_TIMER_FREQ / PDM_CLOCK_FREQ) - 1U;
  PDM_CAPTURE_TIMER->CNT = 0;
  PDM_CAPTURE_TIMER->EGR = TIM_EGR_UG;   // load PSC/ARR
  PDM_CAPTURE_TIMER->SR  = 0;            // clear update flag
  PDM_CAPTURE_TIMER->DIER = TIM_DIER_UDE; // fire DMA request on every UEV

  LL_DMA_DeInit(PDM_CAPTURE_DMA, PDM_CAPTURE_DMA_STREAM);

  LL_DMA_InitTypeDef dmaInit;
  LL_DMA_StructInit(&dmaInit);
  dmaInit.PeriphRequest             = PDM_CAPTURE_DMA_REQUEST;
  dmaInit.Mode                      = LL_DMA_MODE_CIRCULAR;
  dmaInit.Direction                 = LL_DMA_DIRECTION_PERIPH_TO_MEMORY;
  dmaInit.PeriphOrM2MSrcAddress     = (uintptr_t)&PDM_DATA_GPIO_PORT->IDR;
  dmaInit.PeriphOrM2MSrcIncMode     = LL_DMA_PERIPH_NOINCREMENT;
  dmaInit.PeriphOrM2MSrcDataSize    = LL_DMA_PDATAALIGN_BYTE;
  dmaInit.MemoryOrM2MDstAddress     = (uintptr_t)pdmRingBuf;
  dmaInit.MemoryOrM2MDstIncMode     = LL_DMA_MEMORY_INCREMENT;
  dmaInit.MemoryOrM2MDstDataSize    = LL_DMA_MDATAALIGN_BYTE;
  dmaInit.NbData                    = PDM_RING_BYTES;
  dmaInit.Priority                  = LL_DMA_PRIORITY_HIGH;
  LL_DMA_Init(PDM_CAPTURE_DMA, PDM_CAPTURE_DMA_STREAM, &dmaInit);

  LL_DMA_EnableStream(PDM_CAPTURE_DMA, PDM_CAPTURE_DMA_STREAM);

  PDM_CAPTURE_TIMER->CR1 |= TIM_CR1_CEN;

  pdmRunning = true;
}

id pdmStop()
{
  if (!pdmRunning) return;

  // Stop DMA pacing first so no further requests fire.
  PDM_CAPTURE_TIMER->CR1 &= ~TIM_CR1_CEN;
  PDM_CAPTURE_TIMER->DIER = 0;

  // Disable the DMA stream and wait for it to actually stop. A subsequent
  // pdmStart() calls LL_DMA_DeInit which expects the stream idle.
  LL_DMA_DisableStream(PDM_CAPTURE_DMA, PDM_CAPTURE_DMA_STREAM);
  while (LL_DMA_IsEnabledStream(PDM_CAPTURE_DMA, PDM_CAPTURE_DMA_STREAM)) {}

  // Disable the SAI block — this stops the PDM clock to the mic, putting it
  // into low-power mode.
  SAI_Block_TypeDef* block = PDM_SAI_BLOCK;
  CLEAR_BIT(block->CR1, SAI_xCR1_SAIEN);
  while (READ_BIT(block->CR1, SAI_xCR1_SAIEN)) {}

  pdmRunning = false;
}

st

ic uint32_t pdmRingAvailable()
{
  const uint32_t ndtr =
      LL_DMA_GetDataLength(PDM_CAPTURE_DMA, PDM_CAPTURE_DMA_STREAM);
  const uint32_t writePos = PDM_RING_BYTES - ndtr;
  if (writePos >= pdmRingReadPos) return writePos - pdmRingReadPos;
  return PDM_RING_BYTES - pdmRingReadPos + writePos;
}

bo

pdmCapture()
{
  uint32_t avail = pdmRingAvailable();
  if (avail < PDM_BURST_BITS) return false;

  // Skip ahead if DMA is about to overwrite unread data.
  if (avail > PDM_RING_BYTES - PDM_BURST_BITS) {
    const uint32_t target_avail = PDM_BURST_BITS + PDM_BURST_BITS / 2;
    const uint32_t skip = avail - target_avail;
    pdmRingReadPos = (pdmRingReadPos + skip) % PDM_RING_BYTES;
  }

  static_assert(PDM_BURST_BITS % 32U == 0U,
                "PDM_BURST_BITS must be a multiple of 32");

  uint32_t src = pdmRingReadPos;
  for (uint32_t w = 0; w < PDM_BURST_WORDS; ++w) {
    uint32_t acc = 0;
    for (uint32_t b = 0; b < 32; ++b) {
      const uint8_t s = pdmRingBuf[src];
      if (++src >= PDM_RING_BYTES) src = 0;
      acc = (acc << 1) | ((s >> PDM_DATA_GPIO_PIN) & 1U);
    }
    pdmBurstBuf[w] = acc;
  }

  pdmRingReadPos = src;
  return true;
}

bo

pdmUpdateSoundLevel()
{
  if (!pdmCapture()) return false;

  // Ones-density of the PDM bitstream approximates signal amplitude.
  uint32_t ones = 0;
  for (uint32_t w = 0; w < PDM_BURST_WORDS; ++w) {
    ones += __builtin_popcount(pdmBurstBuf[w]);
  }

  const uint32_t total = PDM_BURST_WORDS * 32U;
  const int32_t  mid   = (int32_t)(total / 2U);
  int32_t dev = (int32_t)ones - mid;
  if (dev < 0) dev = -dev;

  uint32_t level = (uint32_t)dev * 200U / total;
  if (level > 100U) level = 100U;
  lastSoundLevel = (uint8_t)level;
  return true;
}

ui

8_t pdmGetSoundLevel()
{
  return lastSoundLevel;
}

//

pdmConvertToPCM(int16_t* pcm, uint32_t max)
{
  if (!pcm || max == 0) return 0;

  constexpr uint32_t R  = PDM_PCM_DECIMATION;
  constexpr int32_t  G  = (int32_t)(R * R * R);
  constexpr int32_t  DC = G / 2;

  // floor_log2(DC) - 14: ensures (c3 - DC) >> SCALE_SHIFT fits in int16.
  // Works for any R, not just powers of two.
  constexpr int SCALE_SHIFT = (31 - __builtin_clz((unsigned)(DC))) - 14;
  static_assert(SCALE_SHIFT >= 0, "Decimation too small to fit PCM range");

  uint32_t produced = 0;
  const uint32_t totalBits = PDM_BURST_WORDS * 32U;

  for (uint32_t idx = 0; idx < totalBits && produced < max; ++idx) {
    const uint32_t word = pdmBurstBuf[idx >> 5];
    const int32_t  bit  = (int32_t)((word >> (31U - (idx & 31U))) & 1U);

    cic_i1 += bit;
    cic_i2 += cic_i1;
    cic_i3 += cic_i2;

    if (++cic_bitsSeen == R) {
      cic_bitsSeen = 0;

      const int32_t c1 = cic_i3 - cic_p1; cic_p1 = cic_i3;
      const int32_t c2 = c1     - cic_p2; cic_p2 = c1;
      const int32_t c3 = c2     - cic_p3; cic_p3 = c2;

      int32_t s = (c3 - DC) >> SCALE_SHIFT;
      s <<= PDM_POST_GAIN_SHIFT;
      if (s >  32767) s =  32767;
      if (s < -32768) s = -32768;
      pcm[produced++] = (int16_t)s;
    }
  }

  return produced;
}

#endif

int cliRecord(const char ** argv)
{
  if (!argv[1] || !argv[1][0]) {
    cliSerialPrint("%s: missing filename", argv[0]);
    return 0;
  }

  int seconds = 5;
  if (argv[2] && argv[2][0]) {
    if (toInt(argv, 2, &seconds) == 0 || seconds <= 0 || seconds > 600) {
      cliSerialPrint("%s: Invalid duration \"%s\"", argv[0], argv[2]);
      return 0;
    }
  }

  char pathBuf[64];
  const char* path = argv[1];
  const size_t nameLen = strlen(argv[1]);
  const bool hasExt =
      nameLen >= 4 && strcasecmp(argv[1] + nameLen - 4, ".wav") == 0;
  if (!hasExt) {
    if (nameLen + 5 > sizeof(pathBuf)) {
      cliSerialPrint("%s: path too long", argv[0]);
      return 0;
    }
    memcpy(pathBuf, argv[1], nameLen);
    memcpy(pathBuf + nameLen, ".wav", 5);
    path = pathBuf;
  }

  const uint32_t totalSamples = PdmWavRecorder::DST_RATE * (uint32_t)seconds;
  // Capture only runs while needed — bring the hardware up for this command.
  pdmStart();
  PdmWavRecorder rec;
  FRESULT res = rec.start(path, (uint32_t)seconds);
  if (res != FR_OK) {
    pdmStop();
    cliSerialPrint("%s: cannot open \"%s\" (err %u)", argv[0], path,
                   (unsigned)res);
    return 0;
  }

  cliSerialPrint("Recording %d s (%u samples @ %u Hz) to %s",
                 seconds, (unsigned)totalSamples,
                 (unsigned)PdmWavRecorder::DST_RATE, path);

  while (rec.isRecording() && rec.getSamplesWritten() < totalSamples) {
    sleep_ms(50);
  }

  rec.stop();
  pdmStop();
  cliSerialPrint("Recorded %u samples (%u bytes)",
                 (unsigned)rec.getSamplesWritten(),
                 (unsigned)rec.getBytesWritten());
  return 0;
}
#

RadioMicRecorder::RadioMicRecorder() :
    Page(ICON_RADIO_TOOLS)
{
  // Bring the PDM hardware up only while this tool is open. Capture is off
  // outside of this scope so the mic clock and DMA stream are idle.
  pdmStart();
  buildHeader(header);
  buildBody(body);
  enterIdle();
}

RadioMicRecorder::~RadioMicRecorder()
{
  // An async call scheduled from the LabelDialog confirm path may still be
  // pending when the page is closed (e.g. user long-presses EXIT while the
  // dialog is being dismissed). Cancelling ensures the callback never fires
  // on a destroyed instance.
  lv_async_call_cancel(&RadioMicRecorder::asyncProcessPendingRename, this);
  if (recorder.isRecording()) recorder.stop();
  pdmStop();
}

void RadioMicRecorder::buildHeader(Window* window)
{
  header->setTitle(STR_MENUTOOLS);
  header->setTitle2(STR_MIC_RECORDER);
}

void RadioMicRecorder::buildBody(Window* window)
{
  window->padAll(PAD_ZERO);

  const coord_t w = window->width();
  const coord_t h = window->height();

  bigLabel = new StaticText(
      window,
      {0, h / 3 - 20, w, 40},
      "", COLOR_THEME_PRIMARY1_INDEX, FONT(XL));
  lv_obj_set_style_text_align(bigLabel->getLvObj(), LV_TEXT_ALIGN_CENTER, 0);

  infoLabel = new StaticText(
      window,
      {0, h / 3 + 30, w, 24},
      "", COLOR_THEME_SECONDARY1_INDEX, FONT(STD));
  lv_obj_set_style_text_align(infoLabel->getLvObj(), LV_TEXT_ALIGN_CENTER, 0);

  actionButton = new TextButton(
      window,
      {(w - MIC_BTN_W) / 2,
       h - MIC_BTN_H - PAD_LARGE * 2,
       MIC_BTN_W, MIC_BTN_H},
      "", [this]() {
        onActionPressed();
        return 0;
      });
  actionButton->setFont(FONT_XL_INDEX);
}

void RadioMicRecorder::onEvent(event_t event)
{
  if (event == EVT_KEY_LONG(KEY_EXIT)) {
    killEvents(event);
    if (recorder.isRecording()) recorder.stop();
    onCancel();
  }
}

void RadioMicRecorder::onActionPressed()
{
  switch (state) {
    case State::IDLE:      enterCountdown(); break;
    case State::COUNTDOWN: enterIdle();      break;   // cancel
    case State::RECORDING: stopRecording();  break;
  }
}

void RadioMicRecorder::enterIdle()
{
  if (recorder.isRecording()) recorder.stop();
  state = State::IDLE;
  stateStart = get_tmr10ms();
  refreshUI();
}

void RadioMicRecorder::enterCountdown()
{
  state = State::COUNTDOWN;
  stateStart = get_tmr10ms();
  refreshUI();
}

void RadioMicRecorder::enterRecording()
{
  pickNextFilename();
  FRESULT res = recorder.start(filename, 0);
  if (res != FR_OK) {
    char msg[40];
    snprintf(msg, sizeof(msg), "%s %u", STR_OPEN_ERROR, (unsigned)res);
    bigLabel->setText(msg);
    state = State::IDLE;
    stateStart = get_tmr10ms();
    actionButton->setText(STR_RECORD);
    return;
  }
  state = State::RECORDING;
  stateStart = get_tmr10ms();
  refreshUI();
}

void RadioMicRecorder::stopRecording()
{
  recorder.stop();
  PdmWavRecorder::trimSilence(filename);
  state = State::IDLE;
  stateStart = get_tmr10ms();
  refreshUI();

  const char* base = strrchr(filename, '/');
  base = base ? base + 1 : filename;

  char baseName[PATH_MAX_LEN] = {};
  strncpy(baseName, base, sizeof(baseName) - 1);
  char* dot = strrchr(baseName, '.');
  if (dot) *dot = '\0';

  new LabelDialog(baseName, LEN_FUNCTION_NAME, STR_SAVE_AS, [this](std::string newName) {
    if (newName.empty()) return;
    char dir[sizeof(SOUNDS_PATH) + 1];
    strcpy(dir, SOUNDS_PATH "/");
    strncpy(dir + SOUNDS_PATH_LNG_OFS, currentLanguagePack->id, 2);
    snprintf(pendingRename, sizeof(pendingRename), "%s%s.wav", dir, newName.c_str());
    if (strcmp(pendingRename, filename) == 0) { refreshUI(); return; }

    // Defer the overwrite check until LabelDialog has finished closing —
    // creating a modal now would leave us stacked on top of LabelDialog,
    // which corrupts the lv_group chain when LabelDialog deletes itself.
    // The page dtor cancels this async call if the user bails out before
    // it fires (see ~RadioMicRecorder).
    lv_async_call(&RadioMicRecorder::asyncProcessPendingRename, this);
  });
}

id RadioMicRecorder::processPendingRename()
{
  FILINFO info;
  if (f_stat(pendingRename, &info) == FR_OK) {
    new ConfirmDialog(STR_FILE_EXISTS, STR_ASK_OVERWRITE,
                      [this]() { applyRename(); });
  } else {
    applyRename();
  }
}

id RadioMicRecorder::applyRename()
{
  f_unlink(pendingRename);
  f_rename(filename, pendingRename);
  strncpy(filename, pendingRename, sizeof(filename) - 1);
  filename[sizeof(filename) - 1] = '\0';
  refreshUI();
}

id RadioMicRecorder::refreshUI()
{
  char buf[64];
  switch (state) {
    case State::IDLE:
      bigLabel->setText(STR_PUSH_TO_RECORD);
      if (recorder.getSamplesWritten() > 0) {
        snprintf(buf, sizeof(buf), "%s %s (%us)", STR_SAVED,
                 filename, (unsigned)recorder.getElapsedSeconds());
        infoLabel->setText(buf);
      } else {
        infoLabel->setText("");
      }
      actionButton->setText(STR_RECORD);
      break;

    case State::COUNTDOWN: {
      const uint32_t elapsed10 = (uint32_t)(get_tmr10ms() - stateStart);
      int remaining = (int)COUNTDOWN_SECONDS - (int)(elapsed10 / 100U);
      if (remaining < 0) remaining = 0;
      snprintf(buf, sizeof(buf), "%s %d", STR_STARTING_IN, remaining);
      bigLabel->setText(buf);
      infoLabel->setText(STR_GET_READY);
      actionButton->setText(STR_CANCEL);
      break;
    }

    case State::RECORDING: {
      const uint32_t s = recorder.getElapsedSeconds();
      snprintf(buf, sizeof(buf), "%s %02u:%02u", STR_REC,
               (unsigned)(s / 60U), (unsigned)(s % 60U));
      bigLabel->setText(buf);
      snprintf(buf, sizeof(buf), "%s  %u KB",
               filename, (unsigned)(recorder.getBytesWritten() / 1024U));
      infoLabel->setText(buf);
      actionButton->setText(STR_STOP);
      break;
    }
  }
}

id RadioMicRecorder::checkEvents()
{
  Page::checkEvents();

  if (state == State::COUNTDOWN) {
    const uint32_t elapsed10 = (uint32_t)(get_tmr10ms() - stateStart);
    if (elapsed10 >= COUNTDOWN_SECONDS * 100U) {
      enterRecording();
    } else {
      refreshUI();
    }
  } else if (state == State::RECORDING) {
    if (!recorder.isRecording()) {
      state = State::IDLE;
      stateStart = get_tmr10ms();
    }
    refreshUI();
  }
}

id RadioMicRecorder::pickNextFilename()
{
  char dir[sizeof(SOUNDS_PATH) + 1];
  strcpy(dir, SOUNDS_PATH "/");
  strncpy(dir + SOUNDS_PATH_LNG_OFS, currentLanguagePack->id, 2);

  FILINFO info;
  for (int i = 0; i < 100; i++) {
    snprintf(filename, sizeof(filename), "%srec_%02d.wav", dir, i);
    if (f_stat(filename, &info) != FR_OK) return;
  }
  snprintf(filename, sizeof(filename), "%srec.wav", dir);
}

static void ensureMutex()
{
  if (!s_mutexInited) {
    mutex_create(&s_mutex);
    s_mutexInited = true;
  }
}

static void writeLE16(uint8_t* p, uint16_t v)
{
  p[0] = v & 0xFF;
  p[1] = (v >> 8) & 0xFF;
}

static void writeLE32(uint8_t* p, uint32_t v)
{
  p[0] = v & 0xFF;
  p[1] = (v >> 8) & 0xFF;
  p[2] = (v >> 16) & 0xFF;
  p[3] = (v >> 24) & 0xFF;
}

FRESULT PdmWavRecorder::start(const char* path, uint32_t expectedSeconds)
{
  ensureMutex();
  MutexLock lock = MutexLock::MakeInstance(&s_mutex);

  if (s_active != nullptr) return FR_LOCKED;

  samplesWritten = 0;
  maxSamples = expectedSeconds * DST_RATE;
  recording = false;

  FRESULT res = f_open(&file, path, FA_CREATE_ALWAYS | FA_WRITE);
  if (res != FR_OK) return res;

  const uint32_t dataBytes = maxSamples * 2U;
  uint8_t header[44];
  memcpy(&header[0],  "RIFF", 4);
  writeLE32(&header[4],  36U + dataBytes);
  memcpy(&header[8],  "WAVE", 4);
  memcpy(&header[12], "fmt ", 4);
  writeLE32(&header[16], 16);
  writeLE16(&header[20], 1);              // PCM
  writeLE16(&header[22], 1);              // mono
  writeLE32(&header[24], DST_RATE);
  writeLE32(&header[28], DST_RATE * 2U);  // byte rate
  writeLE16(&header[32], 2);              // block align
  writeLE16(&header[34], 16);             // bits per sample
  memcpy(&header[36], "data", 4);
  writeLE32(&header[40], dataBytes);

  UINT written = 0;
  res = f_write(&file, header, sizeof(header), &written);
  if (res != FR_OK || written != sizeof(header)) {
    f_close(&file);
    return res != FR_OK ? res : FR_DISK_ERR;
  }

  recording = true;
  s_active = this;
  return FR_OK;
}

bool PdmWavRecorder::tickLocked()
{
  if (!recording) return false;
  if (!pdmCapture()) return false;

  uint32_t n = pdmConvertToPCM(pcm, PCM_MAX);
  if (n == 0) return false;

  if (maxSamples != 0) {
    const uint32_t remaining = maxSamples - samplesWritten;
    if (n > remaining) n = remaining;
  }

  UINT w = 0;
  FRESULT res = f_write(&file, pcm, n * sizeof(int16_t), &w);
  if (res != FR_OK || w != n * sizeof(int16_t)) {
    recording = false;
    return false;
  }
  samplesWritten += n;
  if (maxSamples != 0 && samplesWritten >= maxSamples) {
    recording = false;
  }
  return true;
}

void PdmWavRecorder::audioTick()
{
  if (s_active == nullptr) return;
  ensureMutex();
  MutexLock lock = MutexLock::MakeInstance(&s_mutex);
  if (s_active != nullptr) s_active->tickLocked();
}

FRESULT PdmWavRecorder::stop()
{
  ensureMutex();
  MutexLock lock = MutexLock::MakeInstance(&s_mutex);

  if (s_active != this) return FR_OK;

  s_active = nullptr;
  recording = false;

  const uint32_t dataBytes = samplesWritten * 2U;
  uint8_t buf[4];
  UINT written = 0;

  writeLE32(buf, 36U + dataBytes);
  f_lseek(&file, 4);
  f_write(&file, buf, 4, &written);

  writeLE32(buf, dataBytes);
  f_lseek(&file, 40);
  f_write(&file, buf, 4, &written);

  return f_close(&file);
}

FRESULT PdmWavRecorder::trimSilence(const char* path)
{
  // Threshold tracks the post-CIC gain so trim stays calibrated when
  // PDM_POST_GAIN_SHIFT is changed. Baseline 4000 was tuned at shift=4.
  static constexpr int32_t _silenceRaw =
      ((int32_t)4000 * (1 << PDM_POST_GAIN_SHIFT)) / 16;
  static constexpr int16_t SILENCE_THRESHOLD =
      _silenceRaw > 32767 ? (int16_t)32767 : (int16_t)_silenceRaw;
  static constexpr uint32_t PAD_SAMPLES = DST_RATE / 100;  // 10 ms
  static constexpr uint32_t CHUNK = 256;

  FIL f;
  FRESULT res = f_open(&f, path, FA_READ | FA_WRITE);
  if (res != FR_OK) return res;

  uint8_t hdr[44];
  UINT br = 0;
  res = f_read(&f, hdr, sizeof(hdr), &br);
  if (res != FR_OK || br != sizeof(hdr)) { f_close(&f); return res; }

  const uint32_t dataBytes =
      (uint32_t)hdr[40] | ((uint32_t)hdr[41] << 8) |
      ((uint32_t)hdr[42] << 16) | ((uint32_t)hdr[43] << 24);
  const uint32_t total = dataBytes / 2;
  if (total == 0) { f_close(&f); return FR_OK; }

  int16_t buf[CHUNK];
  uint32_t firstActive = UINT32_MAX;
  uint32_t lastActive = 0;

  for (uint32_t base = 0; base < total; base += CHUNK) {
    const uint32_t n = (base + CHUNK <= total) ? CHUNK : total - base;
    f_lseek(&f, 44 + base * 2);
    res = f_read(&f, buf, n * 2, &br);
    if (res != FR_OK) { f_close(&f); return res; }
    const uint32_t got = br / 2;
    for (uint32_t i = 0; i < got; i++) {
      const int16_t abs = buf[i] < 0 ? (int16_t)-buf[i] : buf[i];
      if (abs > SILENCE_THRESHOLD) {
        if (firstActive == UINT32_MAX) firstActive = base + i;
        lastActive = base + i;
      }
    }
  }

  if (firstActive == UINT32_MAX) { f_close(&f); return FR_OK; }  // all silent

  const uint32_t trimStart = firstActive > PAD_SAMPLES ? firstActive - PAD_SAMPLES : 0;
  const uint32_t trimEnd   = (lastActive + PAD_SAMPLES < total) ? lastActive + PAD_SAMPLES : total - 1;
  const uint32_t newTotal  = trimEnd - trimStart + 1;

  if (trimStart == 0 && trimEnd == total - 1) { f_close(&f); return FR_OK; }

  if (trimStart > 0) {
    uint32_t src = trimStart, dst = 0;
    while (src <= trimEnd) {
      const uint32_t n = (src + CHUNK - 1 <= trimEnd) ? CHUNK : trimEnd - src + 1;
      f_lseek(&f, 44 + src * 2);
      res = f_read(&f, buf, n * 2, &br);
      if (res != FR_OK) { f_close(&f); return res; }
      UINT bw = 0;
      f_lseek(&f, 44 + dst * 2);
      res = f_write(&f, buf, br, &bw);
      if (res != FR_OK) { f_close(&f); return res; }
      src += n;
      dst += n;
    }
  }

  f_lseek(&f, 44 + newTotal * 2);
  f_truncate(&f);

  const uint32_t newDataBytes = newTotal * 2;
  uint8_t tmp[4];
  UINT bw = 0;
  writeLE32(tmp, 36 + newDataBytes);
  f_lseek(&f, 4);
  f_write(&f, tmp, 4, &bw);
  writeLE32(tmp, newDataBytes);
  f_lseek(&f, 40);
  f_write(&f, tmp, 4, &bw);

  return f_close(&f);
}

FRESULT f_truncate(FIL* fil)
{
  if (fil && fil->obj.fs) {
    _simu_FIL* sf = reinterpret_cast<_simu_FIL*>(fil->obj.fs);
    if (sf->stream && sf->stream->is_open()) {
      sf->stream->flush();
      if (!sf->stream->good()) return FR_DISK_ERR;
      std::error_code ec;
      fs::resize_file(sf->filepath, fil->fptr, ec);
      if (ec) return FR_DISK_ERR;
    }
  }
  return FR_OK;
}

static void host_simuAuxSerialStart(wasm_exec_env_t exec_env, uint32_t port_nr,
                                    uint32_t baudrate, uint32_t encoding)
{
  auto * inst = wasm_runtime_get_module_inst(exec_env);
  auto * iface = static_cast<WasmSimulatorInterface *>(
      wasm_runtime_get_custom_data(inst));
  if (iface)
    iface->onAuxSerialStart((uint8_t)port_nr, baudrate, (uint8_t)encoding);
}

static void host_simuAuxSerialStop(wasm_exec_env_t exec_env, uint32_t port_nr)
{
  auto * inst = wasm_runtime_get_module_inst(exec_env);
  auto * iface = static_cast<WasmSimulatorInterface *>(
      wasm_runtime_get_custom_data(inst));
  if (iface)
    iface->onAuxSerialStop((uint8_t)port_nr);
}

static void host_simuAuxSerialSetBaudrate(wasm_exec_env_t exec_env,
                                          uint32_t port_nr, uint32_t baudrate)
{
  auto * inst = wasm_runtime_get_module_inst(exec_env);
  auto * iface = static_cast<WasmSimulatorInterface *>(
      wasm_runtime_get_custom_data(inst));
  if (iface)
    iface->onAuxSerialSetBaudrate((uint8_t)port_nr, baudrate);
}

static void host_simuAuxSerialSendBuffer(wasm_exec_env_t exec_env,
                                         uint32_t port_nr, uint8_t * data,
                                         uint32_t len)
{
  auto * inst = wasm_runtime_get_module_inst(exec_env);
  auto * iface = static_cast<WasmSimulatorInterface *>(
      wasm_runtime_get_custom_data(inst));
  if (iface && data && len > 0)
    iface->onAuxSerialSendBuffer((uint8_t)port_nr, data, len);
}

void WasmSimulatorInterface::onAuxSerialStart(uint8_t port_nr,
                                              uint32_t baudrate,
                                              uint8_t encoding)
{
  emit auxSerialSetEncoding(port_nr, encoding);
  if (baudrate != 0)
    emit auxSerialSetBaudrate(port_nr, baudrate);
  emit auxSerialStart(port_nr);
}

void WasmSimulatorInterface::onAuxSerialSetBaudrate(uint8_t port_nr,
                                                    uint32_t baudrate)
{
  emit auxSerialSetBaudrate(port_nr, baudrate);
}

void WasmSimulatorInterface::onAuxSerialSendBuffer(uint8_t port_nr,
                                                   const uint8_t * data,
                                                   uint32_t len)
{
  emit auxSerialSendData(port_nr,
                         QByteArray((const char *)data, (int)len));

atic void hostSerialInit()
{
  for (uint8_t i = 0; i < MAX_AUX_SERIAL; ++i)
    mutex_create(&hostSerialPorts[i].rxMutex);
}

atic void* host_drv_init(void* hw_def, const etx_serial_init* dev)
{
  if (hw_def == nullptr || dev == nullptr) return nullptr;

  auto* port = static_cast<host_serial_port_t*>(hw_def);
  mutex_lock(&port->rxMutex);
  port->rxQueue.clear();
  mutex_unlock(&port->rxMutex);
  simuAuxSerialStart(port->index, dev->baudrate, dev->encoding);
  return port;
}

atic void host_drv_deinit(void* ctx)
{
  if (ctx == nullptr) return;
  auto* port = static_cast<host_serial_port_t*>(ctx);
  simuAuxSerialStop(port->index);
}

atic void host_drv_send_byte(void* ctx, uint8_t b)
{
  if (ctx == nullptr) return;
  auto* port = static_cast<host_serial_port_t*>(ctx);
  simuAuxSerialSendBuffer(port->index, &b, 1);
}

atic void host_drv_send_buffer(void* ctx, const uint8_t* b, uint32_t l)
{
  if (ctx == nullptr || b == nullptr || l == 0) return;
  auto* port = static_cast<host_serial_port_t*>(ctx);
  simuAuxSerialSendBuffer(port->index, b, l);
}

atic int host_drv_get_byte(void* ctx, uint8_t* b)
{
  if (ctx == nullptr || b == nullptr) return 0;
  auto* port = static_cast<host_serial_port_t*>(ctx);
  mutex_lock(&port->rxMutex);
  if (port->rxQueue.empty()) {
    mutex_unlock(&port->rxMutex);
    return 0;
  }
  *b = port->rxQueue.front();
  port->rxQueue.pop_front();
  mutex_unlock(&port->rxMutex);
  return 1;
}

atic void host_drv_set_baudrate(void* ctx, uint32_t baudrate)
{
  if (ctx == nullptr) return;
  auto* port = static_cast<host_serial_port_t*>(ctx);
  simuAuxSerialSetBaudrate(port->index, baudrate);
}

