double rms(const int16_t* data, size_t n) {
  double sumsq = 0;
  for (size_t i = 0; i < n; i++) sumsq += (double)data[i] * data[i];
  return sqrt(sumsq / n);
}

double runTone(double freq, int freq_low, int freq_high, float gain_low,
               float gain_medium, float gain_high, int n = 4000) {
  NullPrint out;
  Equalizer3BandsT<T> eq(out);
  auto cfg = eq.defaultConfig();
  cfg.channels = 2;
  cfg.bits_per_sample = 16;
  cfg.sample_rate = 44100;
  cfg.freq_low = freq_low;
  cfg.freq_high = freq_high;
  cfg.gain_low = gain_low;
  cfg.gain_medium = gain_medium;
  cfg.gain_high = gain_high;
  assert(eq.begin(cfg));

  std::vector<int16_t> ch0(n);
  int16_t buf[2];
  for (int i = 0; i < n; i++) {
    int16_t s = (int16_t)(10000.0 * sin(2 * M_PI * freq * i / 44100.0));
    buf[0] = s;
    buf[1] = s;
    eq.write((uint8_t*)buf, sizeof(buf));
    ch0[i] = buf[0];
  }
  // skip the filter's startup transient (state starts at zero)
  return rms(ch0.data() + 200, n - 200);
}

void test_identity_gain_reconstructs_signal(const char* label,
                                             double tol_ratio) {
  double in_rms = 10000.0 / sqrt(2.0);  // RMS of a 10000-amplitude sine
  double out_rms = runTone<T>(440.0, 880, 5000, 1.0f, 1.0f, 1.0f);
  double diff_ratio = fabs(out_rms - in_rms) / in_rms;
  printf("[%s] identity gain: in_rms=%.1f out_rms=%.1f diff_ratio=%.4f\n",
         label, in_rms, out_rms, diff_ratio);
  assert(diff_ratio < tol_ratio);
}

void test_gain_changes_energy(const char* label) {
  // 100Hz is deep in the low band (freq_low=880)
  double unity_low = runTone<T>(100.0, 880, 5000, 1.0f, 1.0f, 1.0f);
  double cut_low = runTone<T>(100.0, 880, 5000, 0.0f, 1.0f, 1.0f);
  double boost_low = runTone<T>(100.0, 880, 5000, 2.0f, 1.0f, 1.0f);
  printf("[%s] low-band gain sweep: cut=%.1f unity=%.1f boost=%.1f\n", label,
         cut_low, unity_low, boost_low);
  assert(cut_low < unity_low);
  assert(boost_low > unity_low);

  // 8000Hz is deep in the high band (freq_high=5000)
  double unity_high = runTone<T>(8000.0, 880, 5000, 1.0f, 1.0f, 1.0f);
  double cut_high = runTone<T>(8000.0, 880, 5000, 1.0f, 1.0f, 0.0f);
  double boost_high = runTone<T>(8000.0, 880, 5000, 1.0f, 1.0f, 2.0f);
  printf("[%s] high-band gain sweep: cut=%.1f unity=%.1f boost=%.1f\n", label,
         cut_high, unity_high, boost_high);
  assert(cut_high < unity_high);
  assert(boost_high > unity_high);
}

void test_matches_float_reference(const char* label, double tol_ratio) {
  double float_rms = runTone<float>(440.0, 880, 5000, 1.5f, 0.8f, 1.2f);
  double t_rms = runTone<T>(440.0, 880, 5000, 1.5f, 0.8f, 1.2f);
  double diff_ratio = fabs(t_rms - float_rms) / float_rms;
  printf("[%s] vs float: float_rms=%.1f %s_rms=%.1f diff_ratio=%.4f\n", label,
         float_rms, label, t_rms, diff_ratio);
  assert(diff_ratio < tol_ratio);
}

void test_per_channel_independence(const char* label) {
  NullPrint out;
  Equalizer3BandsPerChannelT<T> eq(out);
  auto cfg = eq.defaultConfig();
  cfg.channels = 2;
  cfg.bits_per_sample = 16;
  cfg.sample_rate = 44100;
  assert(eq.begin(cfg));
  eq.setChannelGains(0, 2.0f, 1.0f, 1.0f);   // boost low on ch 0
  eq.setChannelGains(1, 0.0f, 1.0f, 1.0f);   // cut low on ch 1
  eq.setChannelFrequencies(0, 880, 5000);
  eq.setChannelFrequencies(1, 880, 5000);

  double sumsq0 = 0, sumsq1 = 0;
  const int n = 2000;
  for (int i = 0; i < n; i++) {
    int16_t s = (int16_t)(10000.0 * sin(2 * M_PI * 220.0 * i / 44100.0));
    int16_t buf[2] = {s, s};
    eq.write((uint8_t*)buf, sizeof(buf));
    if (i >= 200) {
      sumsq0 += (double)buf[0] * buf[0];
      sumsq1 += (double)buf[1] * buf[1];
    }
  }
  double rms0 = sqrt(sumsq0 / (n - 200));
  double rms1 = sqrt(sumsq1 / (n - 200));
  printf("[%s] per-channel: rms_boosted=%.1f rms_cut=%.1f\n", label, rms0,
         rms1);
  assert(rms0 > rms1);
}

void test_backward_compat_aliases() {
  NullPrint out;
  Equalizer3Bands eq(out);
  auto cfg = eq.defaultConfig();
  cfg.channels = 2;
  assert(eq.begin(cfg));
  int16_t buf[2] = {1000, -1000};
  eq.write((uint8_t*)buf, sizeof(buf));

  NullPrint out2;
  Equalizer3BandsPerChannel eqpc(out2);
  auto cfg2 = eqpc.defaultConfig();
  cfg2.channels = 2;
  assert(eqpc.begin(cfg2));
  eqpc.setChannelGains(0, 1.2f, 1.0f, 0.9f);
  eqpc.write((uint8_t*)buf, sizeof(buf));
  printf("[compat] Equalizer3Bands / Equalizer3BandsPerChannel aliases OK\n");
}

int main() {
  test_backward_compat_aliases();

  test_identity_gain_reconstructs_signal<float>("float", 0.02);
  test_identity_gain_reconstructs_signal<q1_14_t>("q1_14_t", 0.05);
  test_identity_gain_reconstructs_signal<soft_float_t>("soft_float_t", 0.02);

  test_gain_changes_energy<float>("float");
  test_gain_changes_energy<q1_14_t>("q1_14_t");
  test_gain_changes_energy<soft_float_t>("soft_float_t");

  test_matches_float_reference<q1_14_t>("q1_14_t", 0.02);
  test_matches_float_reference<soft_float_t>("soft_float_t", 0.02);

  test_per_channel_independence<float>("float");
  test_per_channel_independence<q1_14_t>("q1_14_t");
  test_per_channel_independence<soft_float_t>("soft_float_t");

  printf("All equalizer template tests passed.\n");
  return 0;
}

static void cb_stop_self(Button* btn, void* user_data)
{
    (void)user_data;
    stop_cb_called++;
    button_stop(btn);  /* Remove self from list during iteration */
}

static int test_stop_in_callback(void)
{
    stop_cb_called = 0;
    mock_gpio_value = 0;

    button_init(&stop_btn_a, mock_read_gpio, 1, 10);
    button_init(&stop_btn_b, mock_read_gpio, 1, 11);
    button_attach(&stop_btn_a, BTN_PRESS_DOWN, cb_stop_self, NULL);
    button_attach(&stop_btn_b, BTN_PRESS_DOWN, log_press_down, NULL);
    button_start(&stop_btn_a);
    button_start(&stop_btn_b);

    reset_event_log();

    /* Press: both buttons should fire BTN_PRESS_DOWN.
     * stop_btn_a's callback removes itself from the list.
     * The iteration must still process stop_btn_b safely. */
    mock_gpio_value = 1;
    tick_n(DEBOUNCE_TICKS + 5);

    ASSERT(stop_cb_called >= 1);
    ASSERT(has_event(BTN_PRESS_DOWN));  /* stop_btn_b should have fired */

    /* Cleanup */
    button_stop(&stop_btn_b);
    mock_gpio_value = 0;
    return 0;
}

static int test_ticks_saturation(void)
{
    setup_button();

    /* Press and hold the button */
    mock_gpio_value = 1;
    tick_n(DEBOUNCE_TICKS + 5);

    /* Manually set ticks near UINT16_MAX to test saturation */
    test_btn.ticks = UINT16_MAX - 2;

    /* Tick a few more times */
    tick_n(5);

    /* ticks should saturate at UINT16_MAX, not wrap to 0 */
    ASSERT(test_btn.ticks == UINT16_MAX);

    teardown_button();
    return 0;
}

static int test_triple_click(void)
{
    setup_button();

    /* Three rapid clicks */
    for (int i = 0; i < 3; i++) {
        mock_gpio_value = 1;
        tick_n(DEBOUNCE_TICKS + 8);
        mock_gpio_value = 0;
        tick_n(DEBOUNCE_TICKS + 5);
    }

    /* Wait for timeout */
    tick_n(SHORT_TICKS + 20);

    /* Should have 3 press downs and repeat events */
    ASSERT(count_event(BTN_PRESS_DOWN) == 3);
    ASSERT(has_event(BTN_PRESS_REPEAT));
    /* repeat count should be 3 (or check via last known state) */
    /* Note: after timeout, state goes to IDLE, but repeat count is preserved */
    ASSERT(button_get_repeat_count(&test_btn) >= 3);

    teardown_button();
    return 0;
}

static void cb_check_user_data(Button* btn, void* user_data)
{
    (void)btn;
    user_data_received = 1;
    user_data_value = user_data;
}

static int test_user_data(void)
{
    Button ud_btn;
    int my_context = 42;

    mock_gpio_value = 0;
    user_data_received = 0;
    user_data_value = NULL;

    button_init(&ud_btn, mock_read_gpio, 1, 99);
    button_attach(&ud_btn, BTN_PRESS_DOWN, cb_check_user_data, &my_context);
    button_start(&ud_btn);

    /* Trigger press down */
    mock_gpio_value = 1;
    tick_n(DEBOUNCE_TICKS + 5);

    ASSERT(user_data_received == 1);
    ASSERT(user_data_value == &my_context);
    ASSERT(*(int*)user_data_value == 42);

    button_stop(&ud_btn);
    mock_gpio_value = 0;
    return 0;
}

static int test_debounce_boundary(void)
{
    setup_button();

    /* Hold for exactly DEBOUNCE_TICKS - should register */
    mock_gpio_value = 1;
    tick_n(DEBOUNCE_TICKS);

    /* After exactly DEBOUNCE_TICKS of consistent high reading,
     * the level should have changed and press detected */
    tick_n(5);  /* a few more ticks for state machine to process */

    ASSERT(has_event(BTN_PRESS_DOWN));

    teardown_button();
    return 0;
}

static int test_rapid_press_release(void)
{
    setup_button();

    /* 50 rapid press/release cycles */
    for (int i = 0; i < 50; i++) {
        mock_gpio_value = 1;
        tick_n(DEBOUNCE_TICKS + 3);
        mock_gpio_value = 0;
        tick_n(DEBOUNCE_TICKS + 3);
    }

    /* Wait for timeout */
    tick_n(SHORT_TICKS + 20);

    /* Should not crash, and should have registered some presses */
    ASSERT(count_event(BTN_PRESS_DOWN) > 0);

    teardown_button();
    return 0;
}

cubic_w(float x)
{
    const float a = -0.5f;
    x = x < 0 ? -x : x;
    if (x < 1.0f) return ((a + 2.0f) * x - (a + 3.0f)) * x * x + 1.0f;
    if (x < 2.0f) return (((x - 5.0f) * x + 8.0f) * x - 4.0f) * a;
    return 0.0f;
}

/* One axi

ubic_axis(int in, int out, int **first, int **count, float **wts)
{
    const double scale = (double)in / (double)out;
    const double support = (scale > 1.0 ? scale : 1.0) * 2.0;
    const int span = (int)ceil(support) * 2 + 2;
    int *f = (int *)malloc((size_t)out * sizeof(int));
    int *n = (int *)malloc((size_t)out * sizeof(int));
    float *w = (float *)malloc((size_t)out * span * sizeof(float));
    if (!f || !n || !w) { free(f); free(n); free(w); return 0; }
    for (int i = 0; i < out; i++) {
        const double centre = ((double)i + 0.5) * scale;
        int lo = (int)floor(centre - support + 0.5);
        int hi = (int)floor(centre + support + 0.5);
        if (lo < 0) lo = 0;
        if (hi > in) hi = in;
        float *row = w + (size_t)i * span;
        double sum = 0;
        int k = 0;
        for (int s = lo; s < hi && k < span; s++, k++) {
            const float t = cubic_w((float)(((double)s + 0.5 - centre) /
                                            (scale > 1.0 ? scale : 1.0)));
            row[k] = t;
            sum += t;
        }
        /* A degenerate range would divide by zero; it cannot happen for
         * in,out >= 1, and saying so costs one branch. */
        if (sum == 0.0) { row[0] = 1.0f; k = k ? k : 1; sum = 1.0; }
        for (int j = 0; j < k; j++) row[j] = (float)(row[j] / sum);
        f[i] = lo;
        n[i] = k;
    }
    *first = f; *count = n; *wts = w;
    return span;
}

/* src is

ize_bicubic(const unsigned char *src, int sw, int sh,
                          float *dst, int dw, int dh)
{
    int *xf = NULL, *xn = NULL, *yf = NULL, *yn = NULL;
    float *xw = NULL, *yw = NULL, *mid = NULL;
    int rc = -1;
    const int xspan = cubic_axis(sw, dw, &xf, &xn, &xw);
    const int yspan = cubic_axis(sh, dh, &yf, &yn, &yw);
    if (!xspan || !yspan) goto out;
    mid = (float *)malloc((size_t)3 * sh * dw * sizeof(float));
    if (!mid) goto out;

    for (int c = 0; c < 3; c++)
        for (int y = 0; y < sh; y++)
            for (int x = 0; x < dw; x++) {
                const float *w = xw + (size_t)x * xspan;
                float acc = 0;
                for (int k = 0; k < xn[x]; k++)
                    acc += w[k] * (float)src[((size_t)y * sw + xf[x] + k) * 3 + c];
                mid[((size_t)c * sh + y) * dw + x] = acc;
            }
    for (int c = 0; c < 3; c++)
        for (int y = 0; y < dh; y++) {
            const float *w = yw + (size_t)y * yspan;
            for (int x = 0; x < dw; x++) {
                float acc = 0;
                for (int k = 0; k < yn[y]; k++)
                    acc += w[k] * mid[((size_t)c * sh + yf[y] + k) * dw + x];
                dst[((size_t)c * dh + y) * dw + x] = acc;
            }
        }
    rc = 0;
out:
    free(xf); free(xn); free(xw); free(yf); free(yn); free(yw); free(mid);
    return rc;
}

static int g

m_smart_resize(int sh, int sw, int patch, int merge,
                             int temporal, int min_tok, int max_tok,
                             int *out_h, int *out_w)
{
    const int factor = patch * merge;
    const long long ppt = (long long)temporal * factor * factor;
    const long long min_px = (long long)min_tok * ppt;
    const long long max_px = (long long)max_tok * ppt;
    /* round(num_frames / temporal) * temporal with num_frames = 1 is 0 for
     * every temporal above 2, and 0 for 2 as well under round-half-even;
     * the max() is what makes it one aligned frame pair either way. */
    const int frames = temporal;

    int ah = glm_align(sh, factor), aw = glm_align(sw, factor);
    long long budget = (long long)frames * ah * aw;

    if (budget < min_px) {
        const double scale = sqrt((double)min_px / ((double)sh * sw));
        ah = glm_align((int)ceil(sh * scale) < 1 ? 1 : (int)ceil(sh * scale), factor);
        aw = glm_align((int)ceil(sw * scale) < 1 ? 1 : (int)ceil(sw * scale), factor);
        budget = (long long)frames * ah * aw;
    }
    if (budget > max_px) {
        int low = 1, high = sh, bh = factor, bw = factor;
        while (low <= high) {
            const int ch = (low + high) / 2;
            int cw = (int)floor((double)sw * ch / (double)sh);
            if (cw < 1) cw = 1;
            const int cah = glm_align(ch, factor), caw = glm_align(cw, factor);
            if ((long long)frames * cah * caw <= max_px) {
                bh = cah; bw = caw; low = ch + 1;
            } else {
                high = ch - 1;
            }
        }
        ah = bh; aw = bw;
    }
    *out_h = ah;
    *out_w = aw;
}

float *waste

mage_load_glm(const char *path, const waste_vision_cfg *v,
                            int *out_h, int *out_w)
{
    int sw = 0, sh = 0, ch = 0;
    if (!stbi_info(path, &sw, &sh, &ch) || sw <= 0 || sh <= 0 ||
        (uint64_t)sw * (uint64_t)sh > WASTE_MAX_SOURCE_PIXELS) {
        fprintf(stderr, "waste: image dimensions are invalid or exceed the %u-pixel limit: %s\n",
                WASTE_MAX_SOURCE_PIXELS, path ? path : "(null)");
        return NULL;
    }
    unsigned char *img = stbi_load(path, &sw, &sh, &ch, 3);
    if (!img) {
        fprintf(stderr, "waste: cannot decode %s: %s\n", path, stbi_failure_reason());
        return NULL;
    }

    const int patch = v->patch, mg = v->merge, T = v->temporal;
    int min_tok = v->min_tokens > 0 ? v->min_tokens : 1;
    int max_tok = v->max_patches > 0 ? v->max_patches : 1024;
    if (min_tok > max_tok) min_tok = max_tok;
    int H = 0, W = 0;
    glm_smart_resize(sh, sw, patch, mg, T, min_tok, max_tok, &H, &W);
    const int gh = H / patch, gw = W / patch;
    const int npix = 3 * T * patch * patch;

    float *px = (float *)malloc((size_t)gh * gw * npix * sizeof(float));
    float *rs = (float *)malloc((size_t)3 * H * W * sizeof(float));
    if (!px || !rs || resize_bicubic(img, sw, sh, rs, W, H)) {
        stbi_image_free(img); free(px); free(rs);
        return NULL;
    }
    stbi_image_free(img);

    size_t row = 0;
    for (int by = 0; by < gh / mg; by++)
        for (int bx = 0; bx < gw / mg; bx++)
            for (int dy = 0; dy < mg; dy++)
                for (int dx = 0; dx < mg; dx++, row++) {
                    const int py = by * mg + dy, pxi = bx * mg + dx;
                    float *dst = px + row * npix;
                    for (int c = 0; c < 3; c++)
                        for (int j = 0; j < patch; j++)
                            for (int i = 0; i < patch; i++) {
                                const size_t si = ((size_t)c * H + py * patch + j)
                                                  * W + pxi * patch + i;
                                const float val =
                                    (rs[si] / 255.0f - v->mean[c]) / v->std[c];
                                /* (channel, temporal, y, x), the temporal
                                 * axis a copy of the same patch */
                                for (int t = 0; t < T; t++)
                                    dst[(((size_t)c * T + t) * patch + j) * patch + i] = val;
                            }
                }
    free(rs);
    *out_h = gh;
    *out_w = gw;
    return px;
}

static void vt_swiglu(float *gate, const float *up, size_t n, float limit)
{
    for (size_t i = 0; i < n; i++) {
        float g = gate[i], u = up[i];
        if (limit > 0.0f) {
            if (g > limit) g = limit;
            u = u > limit ? limit : (u < -limit ? -limit : u);
        }
        gate[i] = (g / (1.0f + expf(-g))) * u;
    }
}

static const float *vt_bias(waste_model *m, const char *name, float *tmp, int n)
{
    const waste_tensor *t = waste_find(m, name);
    if (!t) return NULL;
    if (t->data) return t->data;
    waste_deq_row(t, 0, n, tmp);
    return tmp;
}

static void glm_rope_row(int row, int col, int hd, float *cs, float *sn)
{
    const int dim = hd / 2, nf = dim / 2;
    for (int j = 0; j < nf; j++) {
        const float inv = powf(10000.0f, -(float)(2 * j) / (float)dim);
        const float a = (float)row * inv, b = (float)col * inv;
        cs[j] = cosf(a);           sn[j] = sinf(a);
        cs[nf + j] = cosf(b);      sn[nf + j] = sinf(b);
    }
    for (int j = 0; j < dim; j++) { cs[dim + j] = cs[j]; sn[dim + j] = sn[j]; }
}

static void glm_rope_apply(float *v, int hd, const float *cs, const float *sn)
{
    float t[256];
    const int h = hd / 2;
    for (int i = 0; i < hd; i++) t[i] = v[i];
    for (int i = 0; i < h; i++) {
        v[i]     = t[i]     * cs[i]     + (-t[h + i]) * sn[i];
        v[h + i] = t[h + i] * cs[h + i] + ( t[i]    ) * sn[h + i];
    }
}

static void rmsnorm_rows(float *dst, const float *src, const float *w,
                         int rows, int n, float eps)
{
    for (int r = 0; r < rows; r++) {
        const float *x = src + (size_t)r * n;
        float ss = 0;
        for (int i = 0; i < n; i++) ss += x[i] * x[i];
        const float inv = 1.0f / sqrtf(ss / (float)n + eps);
        float *o = dst + (size_t)r * n;
        for (int i = 0; i < n; i++) o[i] = x[i] * inv * w[i];
    }
}

int open_model(waste_model *m, const char *dir)
{
    waste_load_opts o;
    memset(&o, 0, sizeof o);
    o.cache_bytes = 0;            /* the tower is trunk; no experts needed */
    o.want_vision = 1;
    o.direct_io = 1;
    const int rc = waste_model_load(m, dir, 256, &o);
    if (rc) fprintf(stderr, "load failed rc=%d\n", rc);
    return rc;
}

stat

void stats(const char *what, const float *v, size_t n, int rows, int dim)
{
    double mean = 0, ss = 0, mx = 0;
    for (size_t i = 0; i < n; i++) {
        mean += v[i];
        ss += (double)v[i] * v[i];
        const double a = v[i] < 0 ? -v[i] : v[i];
        if (a > mx) mx = a;
    }
    mean /= (double)n;
    double var = ss / (double)n - mean * mean;
    printf("%s (%d, %d)  mean %.6f  std %.6f  absmax %.6f\n",
           what, rows, dim, mean, var > 0 ? sqrt(var) : 0.0, mx);
}

int

in(int argc, char **argv)
{
    if (argc < 3) {
        fprintf(stderr,
                "usage: %s tower  CONTAINER H W pixels.bin [out.bin]\n"
                "       %s pixels CONTAINER image [out.bin]\n",
                argv[0], argv[0]);
        return 2;
    }
    const char *mode = argv[1];
    waste_model m;
    if (open_model(&m, argv[2])) return 1;
    const waste_vision_cfg *c = &m.vcfg;
    if (c->tower != WASTE_TOWER_GLM) {
        fprintf(stderr, "this container's tower is not GLM's\n");
        waste_model_free(&m);
        return 1;
    }
    const int npix = 3 * c->temporal * c->patch * c->patch;
    int rc = 1;

    if (!strcmp(mode, "pixels")) {
        if (argc < 4) { fprintf(stderr, "pixels: need an image\n"); goto out; }
        int gh = 0, gw = 0;
        float *px = waste_image_load_glm(argv[3], c, &gh, &gw);
        if (!px) { fprintf(stderr, "image load failed\n"); goto out; }
        printf("grid %dx%d patches, %d merged tokens, row %d\n", gh, gw,
               (gh / c->merge) * (gw / c->merge), npix);
        if (argc > 4) {
            FILE *f = fopen(argv[4], "wb");
            if (f) {
                fwrite(px, sizeof(float), (size_t)gh * gw * npix, f);
                fclose(f);
            }
        }
        free(px);
        rc = 0;
        goto out;
    }

    if (strcmp(mode, "tower") || argc < 6) {
        fprintf(stderr, "tower: need H W pixels.bin\n");
        goto out;
    }
    {
        const int h = atoi(argv[3]), w = atoi(argv[4]);
        if (h <= 0 || w <= 0) { fprintf(stderr, "bad grid\n"); goto out; }
        const size_t L = (size_t)h * w;
        float *px = (float *)malloc(L * npix * sizeof(float));
        /* Wide enough for whichever stage was asked for: the merged output
         * is the smallest of them. */
        float *out = (float *)malloc(L * (size_t)(c->hidden > c->out_hidden
                                                  ? c->hidden : c->out_hidden)
                                     * sizeof(float));
        if (!px || !out) { free(px); free(out); goto out; }
        FILE *f = fopen(argv[5], "rb");
        if (!f || fread(px, sizeof(float), L * npix, f) != L * npix) {
            fprintf(stderr, "pixels file short\n");
            if (f) fclose(f);
            free(px); free(out);
            goto out;
        }
        fclose(f);
        if (waste_vision_encode_glm(&m, px, h, w, out)) {
            fprintf(stderr, "encode failed\n");
            free(px); free(out);
            goto out;
        }
        const char *st = getenv("WASTE_VIS_STAGE");
        const int merged = !st || !strcmp(st, "downsample") ||
                           !strcmp(st, "merged");
        const int rows = merged ? (int)(L / ((size_t)c->merge * c->merge)) : (int)L;
        const int dim = merged ? c->out_hidden : c->hidden;
        stats("tower ->", out, (size_t)rows * dim, rows, dim);
        if (argc > 6) {
            FILE *o = fopen(argv[6], "wb");
            if (o) { fwrite(out, sizeof(float), (size_t)rows * dim, o); fclose(o); }
        }
        free(px); free(out);
        rc = 0;
    }
out:
    waste_model_free(&m);
    return rc;
}

ic void jstr_bare(const char *js, const char *key, char *out, size_t cap)
{
    out[0] = 0;
    const char *k = strstr(js, key);
    if (!k) return;
    const char *q = strchr(k + strlen(key), '"');
    if (!q) return;
    size_t i = 0;
    for (q++; *q && *q != '"' && i + 1 < cap; q++) {
        if (*q == '\\' && q[1]) {
            q++;
            out[i++] = *q == 'n' ? '\n' : *q == 't' ? '\t' : *q;
        } else out[i++] = *q;
    }
    out[i] = 0;
}

/*

const char *asst_open(const chatfmt *f, char *buf, size_t cap)
{
    const char *role = f->open[0] ? f->open : f->asst_p;
    if (!f->think_o[0]) return role;
    snprintf(buf, cap, "%s%s", role, f->think_o);
    return buf;
}

int waste_ecache_admit(waste_ecache *c, int layer, int expert,
                       waste_fetch_fn fetch, void *user)
{
    if (!c || c->n_slots <= 0 || !c->io || !fetch) return 0;
    const int32_t key = ec_key(layer, expert);

    ec_lock(c);
    if (ec_lookup(c, key) >= 0) { ec_unlock(c); return 0; }
    /* A monotone cursor rather than a scan. Nothing is evicted while this
     * runs — it only ever runs when every record fits — so a slot the
     * cursor has passed is a slot that is taken for good, and the whole
     * sweep costs one pass over the slot array instead of one per record. */
    int si = -1;
    while (c->fill_cursor < c->n_slots) {
        const int i = c->fill_cursor++;
        if (c->slot[i].key < 0) { si = i; break; }
    }
    if (si < 0) { ec_unlock(c); return 0; }
    ec_nonvolatile(c, si);
    c->slot[si].key = key;
    c->slot[si].state = EC_INFLIGHT;
    c->slot[si].fresh = 0;          /* a demand read on it is a real hit  */
    c->slot[si].pin = 0;
    c->slot[si].hits = 1;
    c->slot[si].last = c->clock;
    ec_insert(c, key, si);
    c->bytes_read += c->rec_bytes;
    ec_unlock(c);

    const int rc = fetch(user, layer, expert, c->slot[si].data);

    ec_lock(c);
    if (rc == 0) {
        c->slot[si].state = EC_READY;
        c->filled++;
    } else {
        /* Leave no INFLIGHT slot behind for a demand read to wait on: drop
         * it and let the ordinary path re-read and report the reason. */
        ec_drop(c, si);
    }
    pthread_cond_broadcast(&c->io->done);
    ec_unlock(c);
    return rc == 0 ? 1 : -1;
}

in

waste_ecache_resident_all(waste_ecache *c, int layer, const int *ids, int n)
{
    if (!c || c->n_slots <= 0 || n <= 0) return 0;
    int all = 1;
    ec_lock(c);
    for (int i = 0; i < n && all; i++) {
        const int si = ec_lookup(c, ec_key(layer, ids[i]));
        if (si < 0 || c->slot[si].state != EC_READY) all = 0;
    }
    ec_unlock(c);
    return all;
}

start_fill(waste_model *m)
{
    m->fill_records = 0;
    for (int L = 0; L < m->cfg.n_layers; L++)
        if (m->bank[L].fd >= 0)
            m->fill_records += (uint64_t)m->bank[L].n_experts;
    if (!m->fill_records || !m->cache.io) return;
    if ((uint64_t)m->cache.n_slots < m->fill_records) return;
    { const char *e = getenv("WASTE_PRELOAD"); if (e && *e == '0') return; }
    atomic_store(&m->fill_stop, 0);
    if (pthread_create(&m->fill_th, NULL, fill_worker, m) == 0)
        m->fill_running = 1;
}

static vo

stop_fill(waste_model *m)
{
    if (!m->fill_running) return;
    atomic_store(&m->fill_stop, 1);
    pthread_join(m->fill_th, NULL);
    m->fill_running = 0;
}

