ws(float *comb, int H, float eps)
{
    for (int i = 0; i < H; i++) {
        float sum = 0;
        for (int j = 0; j < H; j++) sum += comb[i * H + j];
        const float inv = 1.0f / (sum + eps);
        for (int j = 0; j < H; j++) comb[i * H + j] *= inv;
    }
}

