            const float ck = comb[(size_t)k * H + i];
            const float *src = x + (size_t)k * hid;
            for (int d = 0; d < hid; d++) dst[d] += ck * src[d];
        }
    }
    memcpy(x, tmp, (size_t)H * hid * sizeof(float));
}

