                d1 = vmlal_s16(d1, vget_high_s16(h1), vld1_s16(xo + j + 12));
            }
            acc += waste_f16(ws[k]) * a->xs[k] * (float)(vaddvq_s32(d0) + vaddvq_s32(d1));
        }
        a->y[o] = acc;
    }
}

