int open_bypass(int writing) {
#if defined(_WIN32)
    const DWORD access = writing ? GENERIC_WRITE : GENERIC_READ;
    const DWORD disp = writing ? CREATE_ALWAYS : OPEN_EXISTING;
    const HANDLE h = CreateFileA(g_path, access,
                                 FILE_SHARE_READ | FILE_SHARE_WRITE, NULL, disp,
                                 FILE_FLAG_NO_BUFFERING | FILE_FLAG_WRITE_THROUGH,
                                 NULL);
    if (h == INVALID_HANDLE_VALUE) return -1;
    const int fd = _open_osfhandle((intptr_t)h,
                                   (writing ? _O_WRONLY : _O_RDONLY) | _O_BINARY);
    if (fd < 0) { CloseHandle(h); return -1; }
    if (dio_probe(fd, writing)) return fd;
    close(fd);
    return -1;
#elif defined(__linux__) && defined(O_DIRECT)
    const int rw = writing ? (O_WRONLY | O_CREAT | O_TRUNC) : O_RDONLY;
    const int fd = open(g_path, rw | O_DIRECT, 0644);
    if (fd < 0) return -1;
    if (dio_probe(fd, writing)) return fd;
    close(fd);
    return -1;
#elif defined(__APPLE__)
    /* F_NOCACHE has no alignment contract, so this is the whole bypass on
     * macOS and its failure is the difference between the number the row
     * claims and the number it prints. */
    const int rw = writing ? (O_WRONLY | O_CREAT | O_TRUNC) : O_RDONLY;
    const int fd = open(g_path, rw, 0644);
    if (fd < 0) return -1;
    if (fcntl(fd, F_NOCACHE, 1) < 0) { close(fd); return -1; }
    fcntl(fd, F_RDAHEAD, 0);
    return fd;
#else
    (void)writing;
    return -1;                       /* no bypass known here; say so */
#endif
}

atic void vq_pool_init(int nthreads)
{
    waste_cpumask cpus;
    const int cr = waste_cpus_resolve(NULL, &cpus);
    waste_pool_init(nthreads, cr == WASTE_CPUS_OK ? &cpus : NULL);
}

ic int one(const char *s, int want_count, const char *want_set)
{
    waste_cpumask m;
    const int n = waste_cpuset_parse(s, &m);
    if (n != want_count) {
        fprintf(stderr, "\"%s\": parsed %d, expected %d\n", s, n, want_count);
        return 1;
    }
    if (n < 0) return 0;                       /* rejected, as expected */
    /* want_set lists exactly the CPUs that must be set, "1,2,3"-style. */
    waste_cpumask expect;
    if (waste_cpuset_parse(want_set, &expect) < 0) return 1;
    if (memcmp(&m, &expect, sizeof m) != 0) {
        fprintf(stderr, "\"%s\": wrong CPUs (expected %s)\n", s, want_set);
        return 1;
    }
    return 0;
}

