        if (r != (ssize_t)g_rec) { fprintf(stderr, "short read %zd: %s\n", r, strerror(errno)); break; }
    /* A record under one page rounds to zero and divides by it two screens
     * further down, as a crash rather than as a usage error. */
    if (!g_rec || g_file < g_rec) {
        fprintf(stderr, "record must be >= 4 KiB and file must hold at least one\n");
        return 1;
    }
    int fd = open_path(1);
    if (posix_memalign(&buf, DIO_ALIGN, g_rec)) return 1;
    printf("seq write   : %6.2f GB/s  (%s)\n", written / dt / (1u << 30), bypass_note());
    fd = open_path(0);
    if (fd < 0) { perror("open read"); return 1; }
    if (r < 0) perror("read");   /* a failed read otherwise just ends the loop and shortens the row */
    printf("seq read    : %6.2f GB/s  (%s)\n", rd / dt / (1u << 30), bypass_note());
        printf("rand %2d thr : %6.2f GB/s  -> %.2f tok/s at 12.5 GB/token cold  (%s)\n",
               nt, gbs, gbs / 12.5, bypass_note());
    }

    if (!g

atic void my_parallel_for(int n, int chunk, waste_range_fn fn, void *arg)
{
    if (g_pool.nthreads <= 1 || n <= chunk) { fn(0, n, arg); return; }
    pthread_mutex_lock(&g_pool.mu);
    g_pool.fn=fn; g_pool.arg=arg; g_pool.n=n; g_pool.chunk=chunk;
    g_pool.next_chunk=0; g_pool.active=g_pool.nthreads-1; g_pool.epoch++;
    pthread_cond_broadcast(&g_pool.start);
    pthread_mutex_unlock(&g_pool.mu);
    for (;;) {
        pthread_mutex_lock(&g_pool.mu);
        const int b=g_pool.next_chunk;
        if (b>=n) { pthread_mutex_unlock(&g_pool.mu); break; }
        g_pool.next_chunk=b+chunk;
        pthread_mutex_unlock(&g_pool.mu);
        int e=b+chunk; if (e>n) e=n;
        fn(b,e,arg);
    }
    pthread_mutex_lock(&g_pool.mu);
    while (g_pool.active>0) pthread_cond_wait(&g_pool.done,&g_pool.mu);
    pthread_mutex_unlock(&g_pool.mu);
}

atic void rowsA(int b, int e, void *p)
{
    const arg_t *a = (const arg_t *)p;
    const int st=3, en=256;
    float acc[TILE];
    for (int r0=b; r0<e; r0+=TILE) {
        memset(acc,0,sizeof acc);
        for (int v=0; v<NV; v++) {
            const float *blk=a->lut+(size_t)v*st*en, *b1=blk+en, *b2=blk+2*en;
            const uint8_t *ix=a->idx+((size_t)(r0/TILE)*NV+v)*TILE*st;
            for (int r=0; r+8<=TILE; r+=8, ix+=24) {
                uint32_t w0,w1,w2,w3,w4,w5;
                memcpy(&w0,ix,4);    memcpy(&w1,ix+4,4);
                memcpy(&w2,ix+8,4);  memcpy(&w3,ix+12,4);
                memcpy(&w4,ix+16,4); memcpy(&w5,ix+20,4);
                acc[r]  +=blk[w0&0xff]       +b1[(w0>>8)&0xff] +b2[(w0>>16)&0xff];
                acc[r+1]+=blk[w0>>24]        +b1[w1&0xff]      +b2[(w1>>8)&0xff];
                acc[r+2]+=blk[(w1>>16)&0xff] +b1[w1>>24]       +b2[w2&0xff];
                acc[r+3]+=blk[(w2>>8)&0xff]  +b1[(w2>>16)&0xff]+b2[w2>>24];
                acc[r+4]+=blk[w3&0xff]       +b1[(w3>>8)&0xff] +b2[(w3>>16)&0xff];
                acc[r+5]+=blk[w3>>24]        +b1[w4&0xff]      +b2[(w4>>8)&0xff];
                acc[r+6]+=blk[(w4>>16)&0xff] +b1[w4>>24]       +b2[w5&0xff];
                acc[r+7]+=blk[(w5>>8)&0xff]  +b1[(w5>>16)&0xff]+b2[w5>>24];
            }
        }
        for (int r=0;r<TILE;r++) a->y[r0+r]=acc[r]*a->sc[r0+r];
    }
}

atic void rowsD(int b, int e, void *p)
{
    const arg_t *a = (const arg_t *)p;
    int32_t acc[TILE];
    const uint8x16_t m3f=vdupq_n_u8(0x3f), m0f=vdupq_n_u8(0x0f), m03=vdupq_n_u8(0x03);
    for (int r0=b; r0<e; r0+=TILE) {
        int32x4_t A[16];
        for (int i=0;i<16;i++) A[i]=vdupq_n_s32(0);
        for (int v0=0; v0<NV; v0+=32) {
            const int ve = v0+32>NV?NV:v0+32;
            int16x8_t s[8];
            for (int i=0;i<8;i++) s[i]=vdupq_n_s16(0);
            for (int v=v0; v<ve; v++) {
                const int8_t *blk=a->lut8+(size_t)v*4*64;
                int8x16x4_t T0,T1,T2,T3;
                for (int k=0;k<4;k++){
                    T0.val[k]=vld1q_s8(blk+   0+k*16); T1.val[k]=vld1q_s8(blk+ 64+k*16);
                    T2.val[k]=vld1q_s8(blk+128+k*16);  T3.val[k]=vld1q_s8(blk+192+k*16);
                }
                const uint8_t *ix=a->idx+((size_t)(r0/TILE)*NV+v)*TILE*3;
                for (int g=0; g<4; g++) {
                    const uint8x16x3_t I=vld3q_u8(ix+g*48);
                    const uint8x16_t j0=vandq_u8(I.val[0],m3f);
                    const uint8x16_t j1=vorrq_u8(vshrq_n_u8(I.val[0],6),vshlq_n_u8(vandq_u8(I.val[1],m0f),2));
                    const uint8x16_t j2=vorrq_u8(vshrq_n_u8(I.val[1],4),vshlq_n_u8(vandq_u8(I.val[2],m03),4));
                    const uint8x16_t j3=vshrq_n_u8(I.val[2],2);
                    int8x16_t r =vaddq_s8(vqtbl4q_s8(T0,j0),vqtbl4q_s8(T1,j1));
                    int8x16_t r2=vaddq_s8(vqtbl4q_s8(T2,j2),vqtbl4q_s8(T3,j3));
                    s[g*2]  =vaddw_s8(s[g*2],  vget_low_s8(r));
                    s[g*2+1]=vaddw_s8(s[g*2+1],vget_high_s8(r));
                    s[g*2]  =vaddw_s8(s[g*2],  vget_low_s8(r2));
                    s[g*2+1]=vaddw_s8(s[g*2+1],vget_high_s8(r2));
                }
            }
            for (int i=0;i<8;i++){
                A[i*2]  =vaddw_s16(A[i*2],  vget_low_s16(s[i]));
                A[i*2+1]=vaddw_s16(A[i*2+1],vget_high_s16(s[i]));
            }
        }
        for (int i=0;i<16;i++) vst1q_s32(acc+i*4,A[i]);
        for (int r=0;r<TILE;r++) a->y[r0+r]=(float)acc[r]*a->ls*a->sc[r0+r];
    }
}

t main(int argc, char **argv)
{
    const int nthr   = argc>1 ? atoi(argv[1]) : 1;
    const int mchunk = argc>2 ? atoi(argv[2]) : 1;   /* in TILEs */
    const int copies = argc>3 ? atoi(argv[3]) : 24;  /* index buffers */
    const size_t nidx=(size_t)(M_ROWS/TILE)*NV*TILE*3;

    uint8_t **idx = malloc(sizeof(void*)*copies);
    for (int c=0;c<copies;c++) idx[c]=aligned_alloc(64,nidx);
    float *lutf=aligned_alloc(64,(size_t)NV*3*256*sizeof(float));
    int8_t *lut8=aligned_alloc(64,(size_t)NV*4*64);
    float *sc=aligned_alloc(64,M_ROWS*sizeof(float));
    float *y=aligned_alloc(64,M_ROWS*sizeof(float));
    srandom(1234);
    for (int c=0;c<copies;c++)
        for (size_t i=0;i<nidx;i++) idx[c][i]=(uint8_t)(random()&0xff);
    for (size_t i=0;i<(size_t)NV*3*256;i++) lutf[i]=(float)((random()%2001)-1000)/1000.0f;
    for (size_t i=0;i<(size_t)NV*4*64;i++) lut8[i]=(int8_t)((random()%127)-63);
    for (int i=0;i<M_ROWS;i++) sc[i]=0.01f;

    waste_pool_init(nthr);
    static volatile double sink;
    arg_t a = { y, NULL, lutf, lut8, sc, 1.0f/127.0f };
    const int REP = 40;

    /* A */
    a.idx = idx[0]; my_parallel_for(M_ROWS, TILE*mchunk, rowsA, &a);
    double t=now();
    for (int i=0;i<REP;i++){ a.idx=idx[i%copies];
        my_parallel_for(M_ROWS, TILE*mchunk, rowsA, &a); }
    const double ta=(now()-t)/REP;
    { double s2=0; for(int i=0;i<M_ROWS;i++) s2+=y[i]; sink=s2; }

    /* D */
    a.idx = idx[0]; my_parallel_for(M_ROWS, TILE*mchunk, rowsD, &a);
    t=now();
    for (int i=0;i<REP;i++){ a.idx=idx[i%copies];
        my_parallel_for(M_ROWS, TILE*mchunk, rowsD, &a); }
    const double td=(now()-t)/REP;
    { double s2=0; for(int i=0;i<M_ROWS;i++) s2+=y[i]; sink=s2; }

    const double mb=(double)nidx/1048576.0;
    const int tasks = (M_ROWS + TILE*mchunk - 1)/(TILE*mchunk);
    printf("thr %2d  chunk %2d tiles (%2d task)  A %7.3f ms %6.1f GB/s   "
           "D %7.3f ms %6.1f GB/s   D/A %5.2fx\n",
           nthr, mchunk, tasks,
           ta*1e3, mb/1024.0/ta, td*1e3, mb/1024.0/td, ta/td);
    return 0;
}

static int ec_is_held(const waste_ecache *c, int i)
{
    for (int k = 0; k < c->n_held; k++)
        if (c->held[k] == i) return 1;
    return 0;
}

const uint8_t *waste_ecache_hold(waste_ecache *c, int layer, int expert,
                                 waste_fetch_fn fetch, void *user)
{
    if (c->n_slots <= 0 || c->n_held >= WASTE_PF_MAX) return NULL;
    const uint8_t *r = waste_ecache_get(c, layer, expert, fetch, user);
    if (!r) return NULL;
    /* get() parked it in last_used, which the *next* get would release.
     * Move it into the held set instead, so the claim outlives the loop
     * that is collecting these. */
    ec_lock(c);
    if (c->last_used >= 0) {
        if (!ec_is_held(c, c->last_used)) c->held[c->n_held++] = c->last_used;
        c->last_used = -1;
    }
    ec_unlock(c);
    return r;
}

void waste_ecache_release(waste_ecache *c)
{
    ec_lock(c);
    for (int k = 0; k < c->n_held; k++) {
        const int si = c->held[k];
        /* Same test as ec_release_last: a slot reclaimed for another
         * expert may have a reader writing into it, and a volatile object
         * under an in-flight write is how a purged page becomes a silently
         * zeroed weight. */
        if (c->slot[si].state == EC_READY) ec_volatile(c, si);
    }
    c->n_held = 0;
    ec_unlock(c);
}

d vq_quant_range(int b, int e, void *p)
{
    const lutq_arg *a = (const lutq_arg *)p;
    const int st = a->st, en = a->en;
    for (int blk = b; blk < e; blk++) {
        const int v0 = blk * WASTE_VQ_LUT_BLK;
        int v1 = v0 + WASTE_VQ_LUT_BLK;
        if (v1 > a->nv) v1 = a->nv;
        const size_t n = (size_t)(v1 - v0) * st * en;
        const float *src = a->lut + (size_t)v0 * st * en;
        int8_t *dst = a->q + (size_t)v0 * st * en;
        size_t i = 0;
        float mx = 0;
#if defined(__ARM_NEON) || defined(__aarch64__)
        {   /* Scalar this pass was ~0.4s a run on Kimi-Linear — more than
             * the kernel it feeds was saving — and almost all of it was
             * lrintf and the two clamp branches per value. */
            float32x4_t m0 = vdupq_n_f32(0), m1 = vdupq_n_f32(0);
            for (; i + 8 <= n; i += 8) {
                m0 = vmaxq_f32(m0, vabsq_f32(vld1q_f32(src + i)));
                m1 = vmaxq_f32(m1, vabsq_f32(vld1q_f32(src + i + 4)));
            }
            mx = vmaxvq_f32(vmaxq_f32(m0, m1));
        }
#endif
        for (; i < n; i++) {
            const float f = fabsf(src[i]);
            if (f > mx) mx = f;
        }
        a->scale[blk] = mx / 127.0f;
        const float inv = mx > 0 ? 127.0f / mx : 0.0f;
        i = 0;
#if defined(__ARM_NEON) || defined(__aarch64__)
        {
            const float32x4_t vinv = vdupq_n_f32(inv);
            const int32x4_t hi = vdupq_n_s32(127), lo = vdupq_n_s32(-127);
            for (; i + 16 <= n; i += 16) {
                int32x4_t c[4];
                for (int k = 0; k < 4; k++) {
                    /* vcvtnq rounds to nearest, ties to even — the same
                     * rule lrintf follows in the default mode, so the two
                     * paths agree value for value. The explicit clamp is
                     * what keeps -128 out; a saturating narrow alone would
                     * let it through and break the table's symmetry. */
                    const float32x4_t f = vmulq_f32(vld1q_f32(src + i + k * 4), vinv);
                    c[k] = vminq_s32(vmaxq_s32(vcvtnq_s32_f32(f), lo), hi);
                }
                const int16x8_t s0 = vcombine_s16(vmovn_s32(c[0]), vmovn_s32(c[1]));
                const int16x8_t s1 = vcombine_s16(vmovn_s32(c[2]), vmovn_s32(c[3]));
                vst1q_s8(dst + i, vcombine_s8(vmovn_s16(s0), vmovn_s16(s1)));
            }
        }
#endif
        for (; i < n; i++) {
            /* -127 rather than -128 keeps the table symmetric. */
            int t = (int)lrintf(src[i] * inv);
            if (t > 127) t = 127;
            else if (t < -127) t = -127;
            dst[i] = (int8_t)t;
        }
    }
}

/* Serial on p

nt_lut(const float *lut, int nv, int st, int en,
                         int8_t *q, float *scale)
{
    lutq_arg a = { lut, q, scale, nv, st, en };
    vq_quant_range(0, (nv + WASTE_VQ_LUT_BLK - 1) / WASTE_VQ_LUT_BLK, &a);
}

typedef struct {

s_p6(int b, int e, void *p)
{
    vqp_arg *a = (vqp_arg *)p;
    const int nv = a->nv;
    const int en = 64;              /* validated at load; the tbl4 width   */
    float acc[VQ_TILE];

    for (int r0 = b; r0 < e; r0 += VQ_TILE) {
        const int nr = (r0 + VQ_TILE <= e) ? VQ_TILE : e - r0;
        for (int r = 0; r < nr; r++) acc[r] = 0.0f;

        for (int v0 = 0; v0 < nv; v0 += WASTE_VQ_LUT_BLK) {
            int v1 = v0 + WASTE_VQ_LUT_BLK;
            if (v1 > nv) v1 = nv;
            /* int16 is enough: 4 stages x 32 positions x 127 = 16256. */
            int16_t sum[VQ_TILE];
            memset(sum, 0, sizeof sum);

/* -DWASTE_P6_SCALAR drops to the portable path. The two are meant to agree
 * exactly — the accumulation is integer until the per-block fold, so there
 * is no reordering for float addition to notice — and that is only worth
 * claiming if it can be checked. */
#if (defined(__ARM_NEON) || defined(__aarch64__)) && !defined(WASTE_P6_SCALAR)
            if (nr == VQ_TILE) {
                int16x8_t s[8];
                for (int i = 0; i < 8; i++) s[i] = vdupq_n_s16(0);
                for (int v = v0; v < v1; v++) {
                    const int8_t *T = a->lut8 + (size_t)v * 4 * en;
                    int8x16x4_t T0, T1, T2, T3;
                    for (int k = 0; k < 4; k++) {
                        T0.val[k] = vld1q_s8(T +   0 + k * 16);
                        T1.val[k] = vld1q_s8(T +  64 + k * 16);
                        T2.val[k] = vld1q_s8(T + 128 + k * 16);
                        T3.val[k] = vld1q_s8(T + 192 + k * 16);
                    }
                    const uint8_t *ix = a->idx +
                        ((size_t)(r0 / VQ_TILE) * nv + v) * VQ_TILE * 3;
                    for (int g = 0; g < 4; g++) {
                        const uint8x16x3_t I = vld3q_u8(ix + g * 48);
                        const uint8x16_t j0 =
                            vandq_u8(I.val[0], vdupq_n_u8(0x3f));
                        const uint8x16_t j1 = vandq_u8(
                            vorrq_u8(vshrq_n_u8(I.val[0], 6),
                                     vshlq_n_u8(I.val[1], 2)), vdupq_n_u8(0x3f));
                        const uint8x16_t j2 = vandq_u8(
                            vorrq_u8(vshrq_n_u8(I.val[1], 4),
                                     vshlq_n_u8(I.val[2], 4)), vdupq_n_u8(0x3f));
                        const uint8x16_t j3 = vshrq_n_u8(I.val[2], 2);
                        /* Each lookup is widened on its own rather than
                         * summed in int8 first: two int8 tables can add to
                         * 254 and the table is worth a bit more than the
                         * two instructions that would save. */
                        const int8x16_t r0v = vqtbl4q_s8(T0, j0);
                        const int8x16_t r1v = vqtbl4q_s8(T1, j1);
                        const int8x16_t r2v = vqtbl4q_s8(T2, j2);
                        const int8x16_t r3v = vqtbl4q_s8(T3, j3);
                        int16x8_t lo = s[g * 2], hi = s[g * 2 + 1];
                        lo = vaddw_s8(lo, vget_low_s8(r0v));
                        hi = vaddw_s8(hi, vget_high_s8(r0v));
                        lo = vaddw_s8(lo, vget_low_s8(r1v));
                        hi = vaddw_s8(hi, vget_high_s8(r1v));
                        lo = vaddw_s8(lo, vget_low_s8(r2v));
                        hi = vaddw_s8(hi, vget_high_s8(r2v));
                        lo = vaddw_s8(lo, vget_low_s8(r3v));
                        hi = vaddw_s8(hi, vget_high_s8(r3v));
                        s[g * 2] = lo; s[g * 2 + 1] = hi;
                    }
                }
                for (int i = 0; i < 8; i++) vst1q_s16(sum + i * 8, s[i]);
            } else
#endif
            {
                for (int v = v0; v < v1; v++) {
                    const int8_t *T = a->lut8 + (size_t)v * 4 * en;
                    const uint8_t *ix = a->idx +
                        ((size_t)(r0 / VQ_TILE) * nv + v) * VQ_TILE * 3;
                    for (int r = 0; r < nr; r++) {
                        const unsigned b0 = ix[r * 3], b1 = ix[r * 3 + 1],
                                       b2 = ix[r * 3 + 2];
                        sum[r] = (int16_t)(sum[r] +
                            T[P6_J0(b0, b1, b2)] +
                            T[en + P6_J1(b0, b1, b2)] +
                            T[2 * en + P6_J2(b0, b1, b2)] +
                            T[3 * en + P6_J3(b0, b1, b2)]);
                    }
                }
            }
            const float ls = a->lscale[v0 / WASTE_VQ_LUT_BLK];
            for (int r = 0; r < nr; r++) acc[r] += ls * (float)sum[r];
        }
        for (int r = 0; r < nr; r++)
            a->y[r0 + r] = acc[r] * f16_to_f32(a->scale[r0 + r]);
    }
}

/* The same two kern

l(waste_model *m, float *y, const uint8_t *idx,
                            const uint16_t *scale, int M, int N,
                            const float *lut, const int8_t *q, const float *qs)
{
    const int nv = N / m->vec_dim;
    if (m->index_bits == 6) {
        vqp_arg a = { y, idx, scale, q, qs, nv };
        vq_rows_p6(0, M, &a);
    } else {
        vq_arg a = { y, idx, scale, lut, nv, m->stages, m->cb_entries };
        vq_rows(0, M, &a);
    }
}

static void vq_matvec_se

al(waste_model *m, float *y, const uint8_t *idx,
                             const uint16_t *scale, const float *x, int M,
                             int N, int cb_base, float *lut, int8_t *q,
                             float *qs)
{
    lutb_arg a = { lut, m->codebooksT, x, cb_base, m->stages, m->cb_entries,
                   m->vec_dim };
    waste_k.lutb_range(0, N / m->vec_dim, &a);
    if (q) vq_quant_lut(lut, N / m->vec_dim, m->stages, m->cb_entries, q, qs);
    vq_apply_serial(m, y, idx, scale, M, N, lut, q, qs);
}

                     con

atic void kern_A(float *y, const uint8_t *idx, const float *lut, const float *sc)
{
    const int st=3, en=256;
    float acc[TILE];
    for (int r0=0; r0<M_ROWS; r0+=TILE) {
        memset(acc,0,sizeof acc);
        for (int v=0; v<NV; v++) {
            const float *blk = lut + (size_t)v*st*en, *b1=blk+en, *b2=blk+2*en;
            const uint8_t *ix = idx + ((size_t)(r0/TILE)*NV + v)*TILE*st;
            for (int r=0; r+8<=TILE; r+=8, ix+=24) {
                uint32_t w0,w1,w2,w3,w4,w5;
                memcpy(&w0,ix,4);      memcpy(&w1,ix+4,4);
                memcpy(&w2,ix+8,4);    memcpy(&w3,ix+12,4);
                memcpy(&w4,ix+16,4);   memcpy(&w5,ix+20,4);
                acc[r]  +=blk[w0&0xff]        +b1[(w0>>8)&0xff] +b2[(w0>>16)&0xff];
                acc[r+1]+=blk[w0>>24]         +b1[w1&0xff]      +b2[(w1>>8)&0xff];
                acc[r+2]+=blk[(w1>>16)&0xff]  +b1[w1>>24]       +b2[w2&0xff];
                acc[r+3]+=blk[(w2>>8)&0xff]   +b1[(w2>>16)&0xff]+b2[w2>>24];
                acc[r+4]+=blk[w3&0xff]        +b1[(w3>>8)&0xff] +b2[(w3>>16)&0xff];
                acc[r+5]+=blk[w3>>24]         +b1[w4&0xff]      +b2[(w4>>8)&0xff];
                acc[r+6]+=blk[(w4>>16)&0xff]  +b1[w4>>24]       +b2[w5&0xff];
                acc[r+7]+=blk[(w5>>8)&0xff]   +b1[(w5>>16)&0xff]+b2[w5>>24];
            }
        }
        for (int r=0;r<TILE;r++) y[r0+r]=acc[r]*sc[r0+r];
    }
}

ic void kern_D(float *y, const uint8_t *idx, const int8_t *lut8,
                   const float *sc, const float *ls)
{
    int32_t acc[TILE];
    const uint8x16_t m3f=vdupq_n_u8(0x3f), m0f=vdupq_n_u8(0x0f), m03=vdupq_n_u8(0x03);
    for (int r0=0; r0<M_ROWS; r0+=TILE) {
        int32x4_t A[16];
        for (int i=0;i<16;i++) A[i]=vdupq_n_s32(0);
        for (int v0=0; v0<NV; v0+=32) {
            const int ve = v0+32>NV?NV:v0+32;
            int16x8_t s[8];
            for (int i=0;i<8;i++) s[i]=vdupq_n_s16(0);
            for (int v=v0; v<ve; v++) {
                const int8_t *blk = lut8 + (size_t)v*4*64;
                int8x16x4_t T0,T1,T2,T3;
                for (int k=0;k<4;k++){
                    T0.val[k]=vld1q_s8(blk+   0+k*16); T1.val[k]=vld1q_s8(blk+ 64+k*16);
                    T2.val[k]=vld1q_s8(blk+128+k*16);  T3.val[k]=vld1q_s8(blk+192+k*16);
                }
                const uint8_t *ix = idx + ((size_t)(r0/TILE)*NV + v)*TILE*3;
                for (int g=0; g<4; g++) {
                    const uint8x16x3_t I = vld3q_u8(ix+g*48);
                    const uint8x16_t j0=vandq_u8(I.val[0],m3f);
                    const uint8x16_t j1=vorrq_u8(vshrq_n_u8(I.val[0],6),vshlq_n_u8(vandq_u8(I.val[1],m0f),2));
                    const uint8x16_t j2=vorrq_u8(vshrq_n_u8(I.val[1],4),vshlq_n_u8(vandq_u8(I.val[2],m03),4));
                    const uint8x16_t j3=vshrq_n_u8(I.val[2],2);
                    int8x16_t r =vaddq_s8(vqtbl4q_s8(T0,j0),vqtbl4q_s8(T1,j1));
                    int8x16_t r2=vaddq_s8(vqtbl4q_s8(T2,j2),vqtbl4q_s8(T3,j3));
                    s[g*2]  =vaddw_s8(s[g*2],  vget_low_s8(r));
                    s[g*2+1]=vaddw_s8(s[g*2+1],vget_high_s8(r));
                    s[g*2]  =vaddw_s8(s[g*2],  vget_low_s8(r2));
                    s[g*2+1]=vaddw_s8(s[g*2+1],vget_high_s8(r2));
                }
            }
            for (int i=0;i<8;i++){
                A[i*2]  =vaddw_s16(A[i*2],  vget_low_s16(s[i]));
                A[i*2+1]=vaddw_s16(A[i*2+1],vget_high_s16(s[i]));
            }
        }
        for (int i=0;i<16;i++) vst1q_s32(acc+i*4,A[i]);
        for (int r=0;r<TILE;r++) y[r0+r]=(float)acc[r]*ls[0]*sc[r0+r];
    }
}

in

main(void)
{
    const size_t nidx=(size_t)(M_ROWS/TILE)*NV*TILE*3;
    uint8_t *idx=aligned_alloc(64,nidx);
    float *lutf=aligned_alloc(64,(size_t)NV*3*256*sizeof(float));
    int8_t *lut8=aligned_alloc(64,(size_t)NV*4*64);
    float *sc=aligned_alloc(64,M_ROWS*sizeof(float));
    float *y=aligned_alloc(64,M_ROWS*sizeof(float));
    float ls[1]={1.0f/127.0f};
    srandom(1234);
    for (size_t i=0;i<nidx;i++) idx[i]=(uint8_t)(random()&0xff);
    for (size_t i=0;i<(size_t)NV*3*256;i++) lutf[i]=(float)((random()%2001)-1000)/1000.0f;
    for (size_t i=0;i<(size_t)NV*4*64;i++) lut8[i]=(int8_t)((random()%127)-63);
    for (int i=0;i<M_ROWS;i++) sc[i]=0.01f;

    /* one pass each, cold-ish: the index stream is the thing being sized */
    static volatile double sink;
    double t=now(); kern_A(y,idx,lutf,sc);        const double ta=now()-t;
    { double s2=0; for (int i=0;i<M_ROWS;i++) s2+=y[i]; sink=s2; }
    t=now();        kern_D(y,idx,lut8,sc,ls);     const double td=now()-t;
    { double s2=0; for (int i=0;i<M_ROWS;i++) s2+=y[i]; sink=s2; }
    const double mb=(double)nidx/1048576.0;
    printf("indici %8.1f MB   A %8.3f ms   D %8.3f ms   speedup %5.2fx   "
           "(A %5.1f GB/s, D %5.1f GB/s)\n",
           mb, ta*1e3, td*1e3, ta/td,
           mb/1024.0/ta, mb/1024.0/td);
    return 0;
}

read_limit(const char *dir, const char *leaf)
{
    char path[1600];
    const int n = snprintf(path, sizeof path, "%s/%s", dir, leaf);
    if (n < 0 || (size_t)n >= sizeof path) return 0;

    FILE *f = fopen(path, "r");
    if (!f) return 0;
    char b[64];
    const int got = fgets(b, sizeof b, f) != NULL;
    fclose(f);
    if (!got) return 0;

    char *p = b, *end = NULL;
    while (*p == ' ' || *p == '\t') p++;
    errno = 0;
    const unsigned long long v = strtoull(p, &end, 10);
    if (errno || end == p) return 0;          /* "max", or anything else */
    while (*end == ' ' || *end == '\t' || *end == '\r' || *end == '\n') end++;
    return *end ? 0 : (uint64_t)v;
}

static uint64

smaller_nonzero(uint64_t a, uint64_t b)
{
    if (!a) return b;
    if (!b) return a;
    return a < b ? a : b;
}

static uint64

limits_at(const char *dir)
{
    return smaller_nonzero(read_limit(dir, "memory.max"),
                           read_limit(dir, "memory.high"));
}

/* The unifie

ied_path(const char *path, char *out, size_t cap)
{
    FILE *f = fopen(path, "r");
    if (!f) return 0;
    char line[1024];
    int found = 0;
    while (fgets(line, sizeof line, f)) {
        if (strncmp(line, "0::", 3)) continue;
        const char *rel = line + 3;
        const size_t n = strcspn(rel, "\r\n");
        if (!n || rel[0] != '/' || n >= cap) break;
        int bad = 0;
        for (size_t i = 0; i + 1 < n; i++)
            if (rel[i] == '.' && rel[i + 1] == '.' &&
                (i == 0 || rel[i - 1] == '/') &&
                (i + 2 == n || rel[i + 2] == '/')) bad = 1;
        if (bad) break;
        memcpy(out, rel, n);
        out[n] = 0;
        found = 1;
        break;
    }
    fclose(f);
    return found;
}

uint64_t wast

cgroup_limit(const char *self_cgroup_path, const char *cgroup_root)
{
    if (!cgroup_root || !*cgroup_root) return 0;

    char root[1024];
    size_t root_n = strlen(cgroup_root);
    while (root_n > 1 && cgroup_root[root_n - 1] == '/') root_n--;
    if (root_n >= sizeof root) return 0;
    memcpy(root, cgroup_root, root_n);
    root[root_n] = 0;

    char dir[1600];
    char rel[512];
    int walked = 0;
    if (self_cgroup_path && unified_path(self_cgroup_path, rel, sizeof rel)) {
        const int n = snprintf(dir, sizeof dir, "%s%s", root,
                               strcmp(rel, "/") ? rel : "");
        walked = n > 0 && (size_t)n < sizeof dir;
    }
    if (!walked) snprintf(dir, sizeof dir, "%s", root);

    /* memory.max is hierarchical: a leaf saying "max" does not cancel a
     * finite parent, so keep the most restrictive ancestor rather than
     * trusting the leaf.
     *
     * The walk ends *on* the mounted root, and that last read is not a
     * formality — it is what covers `docker run` without a private cgroup
     * namespace, where /proc/self/cgroup reports the host path
     * (0::/system.slice/docker-<id>.scope) while /sys/fs/cgroup is mounted
     * as the container's own root. Every composed directory along the way
     * is then missing, and the limit that actually applies is sitting in
     * the root itself. Stopping one level short would read nothing and
     * report "unconfined" for the one deployment this exists for. An
     * unconfined host is still 0: a real unified root has no memory.max. */
    uint64_t cap = 0;
    for (;;) {
        cap = smaller_nonzero(cap, limits_at(dir));
        const size_t len = strlen(dir);
        if (len <= root_n) break;
        char *slash = strrchr(dir, '/');
        if (!slash || (size_t)(slash - dir) < root_n) break;
        if ((size_t)(slash - dir) == root_n) dir[root_n] = 0;
        else *slash = 0;
    }
    return cap;
}

nt64_t waste_usable_ram(void)
{
    const uint64_t phys = waste_physical_ram();
    const uint64_t cg = waste_cgroup_limit("/proc/self/cgroup", "/sys/fs/cgroup");
    if (!cg) return phys;
    return (!phys || cg < phys) ? cg : phys;
}

ic int put(const char *dir, const char *leaf, const char *text)
{
    char path[1024];
    snprintf(path, sizeof path, "%s/%s", dir, leaf);
    FILE *f = fopen(path, "w");
    if (!f) return -1;
    return fputs(text, f) < 0 || fclose(f) ? -1 : 0;
}

st

ic int rm(const char *dir, const char *leaf)
{
    char path[1024];
    snprintf(path, sizeof path, "%s/%s", dir, leaf);
    return remove(path) && errno != ENOENT ? -1 : 0;
}

st

ic int mk(const char *path)
{
    return make_dir(path) && errno != EEXIST ? -1 : 0;
}

st

ic int self_says(const char *line)
{
    FILE *f = fopen(SELF, "w");
    if (!f) return -1;
    return fputs(line, f) < 0 || fclose(f) ? -1 : 0;
}

st

ic int hierarchy_cases(const char *tmp)
{
    snprintf(R, sizeof R, "%s/cgroup", tmp);
    snprintf(SELF, sizeof SELF, "%s/self.cgroup", tmp);
    snprintf(PARENT, sizeof PARENT, "%s/parent", R);
    snprintf(CHILD, sizeof CHILD, "%s/child", PARENT);
    CHECK(!mk(R) && !mk(PARENT) && !mk(CHILD));

    /* Nothing anywhere is an unconfined host: a real unified root carries
     * no memory.max, so every read fails and nothing is claimed. */
    CHECK(!self_says("0::/parent/child\n"));
    CHECK(waste_cgroup_limit(SELF, R) == 0);

    /* The ordinary case: our own group is limited. */
    CHECK(!put(CHILD, "memory.max", "8589934592\n"));           /* 8 GiB */
    CHECK(waste_cgroup_limit(SELF, R) == 8 * GiB);

    /* "max" is not a limit, and it does not cancel a finite ancestor.
     * memory.max is hierarchical, so the parent still binds. */
    CHECK(!put(CHILD, "memory.max", "max\n"));
    CHECK(!put(PARENT, "memory.max", "17179869184\n"));         /* 16 GiB */
    CHECK(waste_cgroup_limit(SELF, R) == 16 * GiB);

    /* The most restrictive ancestor wins regardless of which one it is. */
    CHECK(!put(CHILD, "memory.max", "4294967296\n"));           /* 4 GiB */
    CHECK(waste_cgroup_limit(SELF, R) == 4 * GiB);

    /* memory.high counts too: a group the kernel reclaims from at 2 GiB
     * cannot hold a 4 GiB expert cache, whatever memory.max permits. */
    CHECK(!put(CHILD, "memory.high", "2147483648\n"));          /* 2 GiB */
    CHECK(waste_cgroup_limit(SELF, R) == 2 * GiB);
    CHECK(!rm(CHILD, "memory.high"));

    /* `docker run` without a private cgroup namespace: /proc/self/cgroup
     * reports the host path while the mount is the container's own root.
     * Nothing along the composed path exists; the limit is in the root.
     * Reading it is the whole point — this is the deployment the change
     * is for, and the version that stopped one level short reported
     * "unconfined" here. */
    CHECK(!rm(CHILD, "memory.max") && !rm(PARENT, "memory.max"));
    CHECK(!put(R, "memory.max", "34359738368\n"));              /* 32 GiB */
    CHECK(!self_says("0::/system.slice/docker-0123456789ab.scope\n"));
    CHECK(waste_cgroup_limit(SELF, R) == 32 * GiB);

    /* Same answer when /proc/self/cgroup cannot be read at all — cgroup v1,
     * or no /proc — because the mounted root is still the truth. */
    CHECK(waste_cgroup_limit("/nonexistent/self.cgroup", R) == 32 * GiB);
    CHECK(waste_cgroup_limit(NULL, R) == 32 * GiB);

    /* Malformed telemetry claims nothing rather than guessing. A limit
     * read wrong is a budget sized wrong, and 0 is the safe reading. */
    CHECK(!put(R, "memory.max", "not-a-number\n"));
    CHECK(waste_cgroup_limit(SELF, R) == 0);
    CHECK(!put(R, "memory.max", "\n"));
    CHECK(waste_cgroup_limit(SELF, R) == 0);
    CHECK(!put(R, "memory.max", "8589934592 trailing\n"));
    CHECK(waste_cgroup_limit(SELF, R) == 0);
    CHECK(!put(R, "memory.max", "34359738368\n"));

    /* The paths are parameters, so a path that walks out of the supplied
     * root is refused rather than followed. */
    CHECK(!self_says("0::/../outside\n"));
    CHECK(waste_cgroup_limit(SELF, R) == 32 * GiB);   /* fell back to root */
    CHECK(!self_says("garbage with no unified line\n"));
    CHECK(waste_cgroup_limit(SELF, R) == 32 * GiB);

    /* A trailing slash on the root is the same root. */
    char slashed[520];
    snprintf(slashed, sizeof slashed, "%s/", R);
    CHECK(!self_says("0::/parent/child\n"));
    CHECK(waste_cgroup_limit(SELF, slashed) == 32 * GiB);
    return 0;
}

int main

nt argc, char **argv)
{
    if (argc != 2) {
        fprintf(stderr, "usage: test_memory TMPDIR\n");
        return 2;
    }

    /* No root, no answer — on every platform. */
    CHECK(waste_cgroup_limit("/proc/self/cgroup", NULL) == 0);
    CHECK(waste_cgroup_limit("/proc/self/cgroup", "") == 0);

    if (hierarchy_cases(argv[1])) return 1;

    /* The production paths, whatever this host is. Either it is in a cgroup
     * with a limit, or nothing opens and the ceiling stays physical RAM;
     * both are correct and the check is that neither crashes nor invents. */
    {
        const uint64_t live = waste_cgroup_limit("/proc/self/cgroup",
                                                 "/sys/fs/cgroup");
        CHECK(live == 0 || live > (1 << 20));
    }

    puts("PASS cgroup limits");
    return 0;
}

static void start_readers(waste_model *m)
{
    int nio = 2, depth = 2;
    const char *e = getenv("WASTE_IO_THREADS");
    if (e) nio = atoi(e);
    e = getenv("WASTE_IO_DEPTH");
    if (e) depth = atoi(e);
    if (depth < nio) depth = nio;
    waste_ecache_io_start(&m->cache, bank_fetch, m, nio, depth);
}

waste_model_resize_cache(waste_model *m, size_t cache_bytes)
{
    const int policy = m->cache.policy;
    int64_t rec = 0;
    for (int L = 0; L < m->cfg.n_layers; L++)
        if (m->bank[L].rec_bytes > rec) rec = m->bank[L].rec_bytes;
    if (rec <= 0) return -1;
    waste_ecache_free(&m->cache);          /* stops the readers first */
    if (waste_ecache_init(&m->cache, cache_bytes, (size_t)rec, policy)) return -1;
    start_readers(m);
    return 0;
}

id waste_ecache_clear(waste_ecache *c)
{
    ec_lock(c);
    for (int i = 0; i < c->n_slots; i++) {
        if (c->slot[i].state == EC_READY) ec_volatile(c, i);
        c->slot[i].key = -1;
        c->slot[i].state = EC_EMPTY;
        c->slot[i].fresh = 0;
        c->slot[i].pin = 0;
        c->slot[i].hits = 0;
        c->slot[i].last = 0;
    }
    if (c->hash) memset(c->hash, 0xff, ((size_t)c->hash_mask + 1) * sizeof *c->hash);
    c->clock = c->hits = c->misses = c->bytes_read = 0;
    c->evictions = c->prefetched = c->spec_issued = 0;
    c->pf_n = c->pf_issued = 0;
    c->last_used = -1;
    ec_unlock(c);
}

void waste_model_reset(waste_model *m)
{
    const waste_config *c = &m->cfg;
    for (int L = 0; L < c->n_layers; L++) {
        if (m->S[L])
            memset(m->S[L], 0, (size_t)c->kda_heads * c->kda_dim * c->kda_dim * sizeof(float));
        if (m->conv[L])
            memset(m->conv[L], 0,
                   (size_t)3 * c->kda_heads * c->kda_dim * (c->conv_k - 1) * sizeof(float));
        m->n_kv[L] = 0;
    }
    m->n_blockres = 0;
    if (m->x) memset(m->x, 0, (size_t)c->hidden * sizeof(float));
    if (m->blockres && c->attn_res_block) {
        const int nb = c->n_layers / c->attn_res_block + 2;
        memset(m->blockres, 0, (size_t)nb * c->hidden * sizeof(float));
    }
}

c double now(void)
{
    struct timeval t;
    gettimeofday(&t, NULL);
    return t.tv_sec + t.tv_usec / 1e6;
}

#de

ain(int argc, char **argv)
{
    if (argc < 5) {
        fprintf(stderr,
                "usage: %s CONTAINER ids,.. n_gen KEY=v1,v2,.. [repeat]\n"
                "  KEY is lookahead or iodepth\n", argv[0]);
        return 2;
    }
    int ids[MAX_IDS], n = 0;
    for (char *p = strtok(argv[2], ","); p && n < MAX_IDS; p = strtok(NULL, ","))
        ids[n++] = atoi(p);
    const int n_gen = atoi(argv[3]);

    char *eq = strchr(argv[4], '=');
    if (!eq) { fprintf(stderr, "expected KEY=v1,v2,..\n"); return 2; }
    *eq = 0;
    const char *key = argv[4];
    int arm[MAX_ARMS], n_arms = 0;
    for (char *p = strtok(eq + 1, ","); p && n_arms < MAX_ARMS; p = strtok(NULL, ","))
        arm[n_arms++] = atoi(p);
    const int repeat = argc > 5 ? atoi(argv[5]) : 3;

    const int is_look = !strcmp(key, "lookahead");
    const int is_depth = !strcmp(key, "iodepth");
    if (!is_look && !is_depth) { fprintf(stderr, "unknown key %s\n", key); return 2; }

    waste_model m;
    waste_load_opts lo;
    memset(&lo, 0, sizeof lo);
    const char *cmb = getenv("WASTE_CACHE_MB");
    lo.cache_bytes = (size_t)(cmb ? atoi(cmb) : 0) << 20;
    lo.direct_io = 1;
    double t0 = now();
    if (waste_model_load(&m, argv[1], 4096, &lo)) {
        fprintf(stderr, "load failed\n");
        return 1;
    }
    printf("loaded in %.1fs — cache %d slots; %d arms x %d repeats, "
           "%d prompt + %d generated\n\n",
           now() - t0, m.cache.n_slots, n_arms, repeat, n, n_gen);

    /* Interleaved rather than grouped: if the machine drifts over the run —
     * and it does — a grouped sweep charges the drift to the last arm and
     * an interleaved one spreads it across all of them. */
    printf("%8s %6s %9s %9s %9s\n", key, "rep", "tok/s", "hit", "GB read");
    for (int r = 0; r < repeat; r++) {
        for (int a = 0; a < n_arms; a++) {
            if (is_look) waste_model_set_lookahead(arm[a]);
            else m.cache.depth = arm[a] < 1 ? 1 : arm[a];

            waste_model_reset(&m);
            waste_ecache_clear(&m.cache);

            const float *lg = NULL;
            for (int i = 0; i < n; i++) lg = waste_model_step(&m, ids[i], i, NULL);
            if (!lg) { fprintf(stderr, "prompt failed\n"); return 1; }

            int cur = 0;
            for (int v = 1; v < m.cfg.vocab; v++) if (lg[v] > lg[cur]) cur = v;
            const double s = now();
            for (int i = 0; i < n_gen; i++) {
                lg = waste_model_step(&m, cur, n + i, NULL);
                if (!lg) { fprintf(stderr, "step failed\n"); return 1; }
                cur = 0;
                for (int v = 1; v < m.cfg.vocab; v++) if (lg[v] > lg[cur]) cur = v;
            }
            const double dt = now() - s;
            const unsigned long long h = m.cache.hits, mi = m.cache.misses;
            printf("%8d %6d %8.3f %8.1f%% %8.1f\n", arm[a], r + 1,
                   n_gen / dt, 100.0 * (double)h / (double)(h + mi ? h + mi : 1),
                   (double)m.cache.bytes_read / 1073741824.0);
            fflush(stdout);
        }
    }
    waste_model_free(&m);
    return 0;
}

ic void ec_claim_spec(waste_ecache *c, int vi, int32_t key)
{
    ec_nonvolatile(c, vi);
    const int had = c->slot[vi].key >= 0;
    c->slot[vi].key = key;
    c->slot[vi].state = EC_INFLIGHT;
    c->slot[vi].fresh = 0;              /* a demand hit on it is a real hit */
    c->slot[vi].pin = 0;                /* belongs to no hint generation    */
    c->slot[vi].hits = 1;
    c->slot[vi].last = c->clock;
    if (had) { c->evictions++; ec_rehash(c); }
    else ec_insert(c, key, vi);
    c->spec_issued++;
    c->bytes_read += c->rec_bytes;
}

vo

waste_ecache_prefetch(waste_ecache *c, int layer, const int *ids, int n)
{
    if (!c->io || c->n_slots <= 0 || n <= 0) return;
    ec_lock(c);
    for (int i = 0; i < n; i++) {
        if (ids[i] < 0) continue;
        const int32_t key = ec_key(layer, ids[i]);
        if (ec_lookup(c, key) >= 0) continue;   /* already here, or coming */
        const int vi = ec_victim(c);
        if (vi < 0) break;                      /* everything pinned; skip */
        ec_claim_spec(c, vi, key);
        if (eio_push(c->io, vi, layer, ids[i]) != 0) {
            c->spec_issued--;
            c->bytes_read -= c->rec_bytes;
            ec_drop(c, vi);
            break;                              /* queue full: stop asking */
        }
    }
    ec_unlock(c);
}

c int predict_next_moe(waste_model *m, int L, const float *in, int *out, int n)
{
    const waste_config *c = &m->cfg;
    const int E = c->n_experts, hid = c->hidden;
    if (n <= 0 || E <= 0 || L + 1 >= c->n_layers) return 0;
    const waste_tensor *g = waste_find(m, tname(
        "%smodel.layers.%d.block_sparse_moe.gate.weight", c->prefix, L + 1));
    if (!g) return 0;
    if (n > E) n = E;

    float *sc = m->att + WASTE_ATT_ROUTER_OFF, *p = sc + E;
    matvec_t(m, sc, g, in, E, hid);
    const float *bias = T(m, "%smodel.layers.%d.block_sparse_moe.gate.e_score_correction_bias",
                          c->prefix, L + 1);
    /* Selection order only, so the sigmoid is monotone and could be skipped
     * — kept because the bias is added in probability space, as the real
     * router does it, and a different order here would be a different
     * prediction rather than a faster one. */
    for (int e = 0; e < E; e++)
        p[e] = 1.0f / (1.0f + expf(-sc[e])) + (bias ? bias[e] : 0.0f);
    for (int j = 0; j < n; j++) {
        int best = -1;
        float bv = -1e30f;
        for (int e = 0; e < E; e++) {
            int taken = 0;
            for (int q = 0; q < j; q++) if (out[q] == e) { taken = 1; break; }
            if (!taken && p[e] > bv) { bv = p[e]; best = e; }
        }
        out[j] = best;
    }
    return n;
}

int waste_mlock_mode(void)
{
    const char *e = getenv("WASTE_MLOCK");
    if (!e || !*e || *e == '0') return 0;
    if (!strcmp(e, "trunk")) return WASTE_WIRE_TRUNK;
    if (!strcmp(e, "cache")) return WASTE_WIRE_CACHE;
    if (!strcmp(e, "all") || !strcmp(e, "both"))
        return WASTE_WIRE_CACHE | WASTE_WIRE_TRUNK;
    /* Bare 1 means "wire what you can". It meant cache-only when §30 was
     * written, and §31 measured the trunk: wiring the cache alone is the
     * one setting that is worse than doing nothing, because it leaves the
     * hot part pageable. `cache` still names the old behaviour, for
     * reproducing that section. */
    return WASTE_WIRE_CACHE | WASTE_WIRE_TRUNK;
}

void wire_trunk(waste_model *m)
{
    size_t done = 0;
    int failed = 0;
    for (int i = 0; i < m->n_tensors; i++) {
        const waste_tensor *t = &m->t[i];
        if (t->on_disk || t->ndim < 1) continue;
        if (t->data) {
            const size_t n = t->n * sizeof(float);
            if (waste_wire(t->data, n)) done += n; else failed++;
        }
        const int N = t->shape[t->ndim - 1];
        if (!t->q || N <= 0 || t->group <= 0) continue;
        const size_t rows = t->n / (size_t)N;
        const size_t payload = rows * t->rowbytes;
        if (waste_wire(t->q, payload)) done += payload; else failed++;
        if (t->qs) {
            const size_t sb = rows * (size_t)((N + t->group - 1) / t->group) *
                              sizeof(uint16_t);
            if (waste_wire(t->qs, sb)) done += sb; else failed++;
        }
    }
    fprintf(stderr, "waste: wired %.2f GB of trunk%s\n",
            (double)done / (double)(1u << 30),
            failed ? " (some buffers were refused)" : "");
}

