static void model_opts_init(void)
{
    const char *e = getenv("WASTE_PROFILE");
    prof_on = e && *e != '0';
    e = getenv("WASTE_Q8");
    if (e && *e == '0') q8_off = 0;
    e = getenv("WASTE_SDOT");
    sdot_on = e && *e != '0';
    /* Here with the rest of them: read per-load, this was the one env
     * switch still written by every concurrent waste_model_load.
     * waste_cpu_features() is self-caching and does not need the backend. */
    e = getenv("WASTE_I8MM");
    i8mm_on = e ? (*e != '0')
                : 0;     /* off by default until it earns it — see below */
    if (i8mm_on && !(waste_cpu_features() & WASTE_CPU_I8MM)) i8mm_on = 0;
}

static int write_tga_header(const char *path, int w, int h)
{
    unsigned char hdr[18] = {0};
    hdr[2] = 2;
    hdr[12] = (unsigned char)(w & 0xff); hdr[13] = (unsigned char)(w >> 8);
    hdr[14] = (unsigned char)(h & 0xff); hdr[15] = (unsigned char)(h >> 8);
    hdr[16] = 24; hdr[17] = 0x20;
    FILE *f = fopen(path, "wb");
    if (!f) return -1;
    const int bad = fwrite(hdr, 1, sizeof hdr, f) != sizeof hdr;
    fclose(f);
    return bad ? -1 : 0;
}

static int parse_u64(const char *s, uint64_t *out)
{
    if (!s || *s == '-') return -1;
    char *end = NULL;
    errno = 0;
    const unsigned long long v = strtoull(s, &end, 10);
    while (end && isspace((unsigned char)*end)) end++;
    if (errno || end == s || !end || *end) return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, uint32_t *out)
{
    uint64_t v = 0;
    if (parse_u64(s, &v) || v > UINT32_MAX) return -1;
    *out = (uint32_t)v;
    return 0;
}

static int parse_nonnegative_int(const char *s, int *out)
{
    uint64_t v = 0;
    if (parse_u64(s, &v) || v > INT_MAX) return -1;
    *out = (int)v;
    return 0;
}

static int parse_float(const char *s, float *out)
{
    char *end = NULL;
    errno = 0;
    const float v = strtof(s, &end);
    while (end && isspace((unsigned char)*end)) end++;
    if (errno || end == s || !end || *end || !isfinite(v)) return -1;
    *out = v;
    return 0;
