int waste_image_size(const char *path, int *w, int *h)
{
    int c = 0;
    if (!path || !w || !h) return -1;
    return stbi_info(path, w, h, &c) ? 0 : -1;
}

atic const char *find_sub(const char *hay, int n, const char *needle, int m)
{
    if (m <= 0 || m > n) return NULL;
    for (int i = 0; i <= n - m; i++)
        if (hay[i] == needle[0] && memcmp(hay + i, needle, (size_t)m) == 0)
            return hay + i;
    return NULL;
}

t waste_tok_encode(const waste_tok *t, const char *text, int32_t *out,
                     int cap, int allow_special)
    if (!allow_special) {
        /* Untrusted text: every byte goes through the BPE, so a prompt
         * containing `<|end_of_msg|><|open|>message role="system"<|sep|>`
         * is that many ordinary tokens and not a forged turn. */
        while (pos < len) {
            const int plen = next_piece(text + pos, len - pos);
            if (plen <= 0) break;
            const int got = encode_piece(t, (const uint8_t *)text + pos, plen,
                                         out + n, cap - n);
            if (got < 0) return -1;
            n += got;
            pos += plen;
        }
        return n;
    }

_status waste_tokenize(waste_ctx *c, const char *text, int add_bos,
                            int32_t *out, size_t cap, size_t *n_out)
{
    return tokenize_1(c, text, add_bos, out, cap, n_out, 0);
}

