_status waste_image_dimensions(const char *path, int *w, int *h)
{
    if (!path || !w || !h) return WASTE_E_ARG;
    return waste_image_size(path, w, h) == 0 ? WASTE_OK : WASTE_E_IO;
}

static int build_prompt(waste_ctx *c, const opts *o, const char *prompt,
                        int32_t *ids, size_t cap, size_t *n)
{
    if (!o->n_image)
        return waste_tokenize(c, prompt, 0, ids, cap, n) == WASTE_OK
                   ? 0 : fail("tokenize", WASTE_E_ARG);

    char head[MEDIA_HEAD_CAP], *full;
    if (prefix_images(c, o, head, sizeof head)) return 1;
    const size_t need = strlen(head) + strlen(prompt) + 1;
    if (!(full = (char *)malloc(need))) return fail("prompt", WASTE_E_OOM);
    snprintf(full, need, "%s%s", head, prompt);

    int32_t *raw = (int32_t *)malloc(cap * sizeof *raw);
    if (!raw) { free(full); return fail("prompt", WASTE_E_OOM); }
    size_t rn = 0;
    waste_status st = waste_tokenize(c, full, 0, raw, cap, &rn);
    free(full);
    if (st == WASTE_OK) st = waste_image_expand(c, raw, rn, ids, cap, n);
    free(raw);
    if (st != WASTE_OK) return fail("prompt", st);
    return 0;
}

waste_embed_row(waste_model *m, int token, float *dst)
{
    const int hid = m->cfg.hidden;
    const waste_tensor *emb = waste_find(m, tname("%smodel.embed_tokens.weight",
                                                  m->cfg.prefix));
    if (!emb) return -1;
    if (emb->data) {
        memcpy(dst, emb->data + (size_t)clamp_token(m, token) * hid,
               (size_t)hid * sizeof(float));
        return 0;
    }
    const int g = emb->group, ng = (hid + g - 1) / g;
    const int8_t *row; const uint16_t *sc;
    trunk_row(m, emb, clamp_token(m, token), &row, &sc);
    for (int k = 0; k < ng; k++) {
        const float sv = f16_to_f32(sc[k]);
        for (int i = 0; i < g && k * g + i < hid; i++) {
            int v;
            if (emb->bits == 3) v = q3_at((const uint8_t *)row, (long)k * g + i);
            else if (emb->bits == 4) {
                const uint8_t byte = ((const uint8_t *)row)[(k * g + i) / 2];
                v = (i & 1) ? (byte >> 4) - 8 : (byte & 0x0F) - 8;
            } else v = row[k * g + i];
            dst[k * g + i] = (float)v * sv;
        }
    }
    return 0;
}

static void params_human(uint64_t n, char *out, size_t cap)
{
    if (n >= 1000000000000ULL) snprintf(out, cap, "%.2f T", (double)n / 1e12);
    else snprintf(out, cap, "%.2f B", (double)n / 1e9);
}

static int prefix_images(waste_ctx *c, const opts *o, char *buf, size_t cap)
{
    size_t k = 0;
    for (int i = 0; i < o->n_image; i++) {
        size_t rows = 0;
        const waste_status st = waste_image_add(c, o->image[i], &rows);
        if (st != WASTE_OK) return fail(o->image[i], st);
        if (!o->quiet)
            fprintf(stderr, "[%s: %zu image tokens]\n", o->image[i], rows);
        const int w = snprintf(buf + k, cap - k, "%s%s%s%s",
                               "<|media_begin|>", "<|media_content|>",
                               "<|media_pad|>", "<|media_end|>");
        if (w < 0 || (size_t)w >= cap - k) {
            fprintf(stderr, "prompt too long\n");
            return 1;
        }
        k += (size_t)w;
    }
    buf[k] = 0;
    return 0;
}

void waste_image_clear(waste_ctx *c)
{
    if (!c) return;
    free(c->img);
    c->img = NULL;
    c->img_rows = 0;
    c->img_n = 0;
}

waste_status waste_image_add(waste_ctx *c, const char *path, size_t *n_out)
{
    if (!c || !path) return WASTE_E_ARG;
    if (!c->m.want_vision || !c->m.vcfg.layers) return WASTE_E_UNSUPPORTED;
    if (c->img_n >= WASTE_MAX_IMAGES) return WASTE_E_ARG;

    int gh = 0, gw = 0;
    float *px = waste_image_load(path, c->m.vcfg.max_patches,
                                 c->m.vcfg.mean, c->m.vcfg.std, &gh, &gw);
    if (!px) return WASTE_E_IO;

    const size_t rows = (size_t)(gh / 2) * (size_t)(gw / 2);
    const size_t th = (size_t)c->m.vcfg.text_hidden;
    float *nb = (float *)realloc(c->img, (c->img_rows + rows) * th * sizeof(float));
    if (!nb) { free(px); return WASTE_E_OOM; }
    c->img = nb;

    const int rc = waste_vision_encode(&c->m, px, gh, gw,
                                       c->img + c->img_rows * th);
    free(px);
    if (rc) return WASTE_E_IO;

    c->img_each[c->img_n++] = rows;
    c->img_rows += rows;
    if (n_out) *n_out = rows;
    return WASTE_OK;
}

waste_status waste_image_expand(waste_ctx *c, const int32_t *tokens, size_t n,
                                int32_t *out, size_t cap, size_t *n_out)
{
    if (!c || !tokens || !out) return WASTE_E_ARG;
    if (!c->m.want_vision || !c->m.vcfg.layers) return WASTE_E_UNSUPPORTED;
    const int32_t pad = (int32_t)c->m.vcfg.media_token;

    size_t seen = 0;
    for (size_t i = 0; i < n; i++) if (tokens[i] == pad) seen++;
    /* A mismatch is a prompt-assembly bug, and a silent one would show up
     * much later as an image the model never saw. Refuse it here. */
    if (seen != (size_t)c->img_n) return WASTE_E_ARG;

    size_t k = 0, img = 0;
    for (size_t i = 0; i < n; i++) {
        const size_t rep = (tokens[i] == pad) ? c->img_each[img++] : 1;
        if (k + rep > cap) { if (n_out) *n_out = 0; return WASTE_E_ARG; }
        for (size_t r = 0; r < rep; r++) out[k++] = tokens[i];
    }
    if (n_out) *n_out = k;
    return WASTE_OK;
}

static void media_arm(waste_ctx *c)
{
    c->m.media = c->img;
    c->m.media_n = (int)c->img_rows;
    c->m.media_used = 0;
    c->m.cfg_media_token = c->m.vcfg.media_token;
}

static void media_release(waste_ctx *c)
{
    if (c->m.media_used > 0) waste_image_clear(c);
    c->m.media = NULL;
    c->m.media_n = c->m.media_used = 0;
}

atic void close_to(float got, float want, float tol, const char *what)
{
    if (!(fabsf(got - want) <= tol)) {
        printf("FAIL %s: %+.5f vs %+.5f\n", what, (double)got, (double)want);
        fails++;
    }
}

atic int write_tga(const char *path, int w, int h,
                     unsigned char r, unsigned char g, unsigned char b)
{
    unsigned char hdr[18];
    memset(hdr, 0, sizeof hdr);
    hdr[2] = 2;                                  /* uncompressed true-colour */
    hdr[12] = (unsigned char)(w & 0xff); hdr[13] = (unsigned char)(w >> 8);
    hdr[14] = (unsigned char)(h & 0xff); hdr[15] = (unsigned char)(h >> 8);
    hdr[16] = 24;
    hdr[17] = 0x20;                              /* origin top-left */
    FILE *f = fopen(path, "wb");
    if (!f) return -1;
    fwrite(hdr, 1, sizeof hdr, f);
    const unsigned char px[3] = { b, g, r };     /* TGA stores BGR */
    for (long i = 0; i < (long)w * h; i++) fwrite(px, 1, 3, f);
    fclose(f);
    return 0;
}

t main(int argc, char **argv)
{
    const char *dir = (argc > 1) ? argv[1] : ".";
    char path[512];
    snprintf(path, sizeof path, "%s/waste_test_img.tga", dir);

    /* --- a solid colour: every pixel is predictable ---------------------- */
    if (write_tga(path, 56, 28, 255, 0, 0)) { printf("FAIL cannot write %s\n", path); return 1; }

    int gh = 0, gw = 0;
    float *px = waste_image_load(path, 1024, MEAN, STD, &gh, &gw);
    ok(px != NULL, "decode");
    if (!px) return 1;

    /* 56x28 at 14 pixels per patch is 4 wide by 2 high, and both are already
     * even so nothing is rounded away. */
    ok(gw == 4 && gh == 2, "grid 4x2");
    ok(gw % 2 == 0 && gh % 2 == 0, "grid even on both axes");

    /* Channel-major inside a patch: R plane, then G, then B. Sampling the
     * centre avoids the edge clamp in the bilinear filter. */
    const int P = PATCH, mid = (7 * P) + 7;
    for (int p = 0; p < gw * gh; p++) {
        const float *q = px + (size_t)p * 3 * P * P;
        close_to(q[0 * P * P + mid], (1.0f - MEAN[0]) / STD[0], 1e-4f, "R");
        close_to(q[1 * P * P + mid], (0.0f - MEAN[1]) / STD[1], 1e-4f, "G");
        close_to(q[2 * P * P + mid], (0.0f - MEAN[2]) / STD[2], 1e-4f, "B");
    }
    free(px);

    /* --- the patch budget is a ceiling, not a suggestion ----------------- */
    if (write_tga(path, 700, 700, 128, 128, 128)) { printf("FAIL write\n"); return 1; }
    px = waste_image_load(path, 64, MEAN, STD, &gh, &gw);
    ok(px != NULL, "decode large");
    if (px) {
        ok(gw * gh <= 64, "patch budget respected");
        ok(gw % 2 == 0 && gh % 2 == 0, "large grid even");
        ok(gw == gh, "square image gives a square grid");
        free(px);
    }

    /* --- an image smaller than one patch still yields a legal grid ------- */
    if (write_tga(path, 3, 5, 0, 255, 0)) { printf("FAIL write\n"); return 1; }
    px = waste_image_load(path, 1024, MEAN, STD, &gh, &gw);
    ok(px != NULL, "decode tiny");
    if (px) {
        ok(gw >= 2 && gh >= 2, "tiny image padded up to the 2x2 merge");
        close_to(px[1 * P * P + mid], (1.0f - MEAN[1]) / STD[1], 1e-4f, "tiny G");
        free(px);
    }

    /* --- a file that is not an image is an error, not a crash ------------ */
    snprintf(path, sizeof path, "%s/waste_test_img.tga", dir);
    FILE *f = fopen(path, "wb");
    if (f) { fputs("this is not an image", f); fclose(f); }
    ok(waste_image_load(path, 1024, MEAN, STD, &gh, &gw) == NULL, "garbage rejected");
    ok(waste_image_load("/nonexistent/x.png", 1024, MEAN, STD, &gh, &gw) == NULL,
       "missing file rejected");
    remove(path);

    printf(fails ? "IMAGE FAILED (%d)\n" : "IMAGE OK\n", fails);
    return fails ? 1 : 0;
}

ic float sample(const unsigned char *src, int sw, int sh, int ch,
                    float fx, float fy, int c)
{
    int x0 = (int)floorf(fx), y0 = (int)floorf(fy);
    const float wx = fx - (float)x0, wy = fy - (float)y0;
    int x1 = x0 + 1, y1 = y0 + 1;
    if (x0 < 0) x0 = 0; if (y0 < 0) y0 = 0;
    if (x1 < 0) x1 = 0; if (y1 < 0) y1 = 0;
    if (x0 > sw - 1) x0 = sw - 1; if (y0 > sh - 1) y0 = sh - 1;
    if (x1 > sw - 1) x1 = sw - 1; if (y1 > sh - 1) y1 = sh - 1;
    const float a = src[((size_t)y0 * sw + x0) * ch + c];
    const float b = src[((size_t)y0 * sw + x1) * ch + c];
    const float d = src[((size_t)y1 * sw + x0) * ch + c];
    const float e = src[((size_t)y1 * sw + x1) * ch + c];
    return (1 - wy) * ((1 - wx) * a + wx * b) + wy * ((1 - wx) * d + wx * e);
}

fl

t *waste_image_load(const char *path, int max_patches,
                        const float *mean, const float *std,
                        int *out_h, int *out_w)
{
    int sw = 0, sh = 0, ch = 0;
    unsigned char *img = stbi_load(path, &sw, &sh, &ch, 3);
    if (!img) {
        fprintf(stderr, "waste: cannot decode %s: %s\n", path, stbi_failure_reason());
        return NULL;
    }

    /* Choose a patch grid that keeps the aspect ratio, stays under the
     * budget, and is even on both axes for the 2x2 merge. */
    double scale = sqrt((double)max_patches / ((double)sw * sh / (PATCH * PATCH)));
    if (scale > 1.0) scale = 1.0;
    int gw = (int)((double)sw * scale / PATCH + 0.5);
    int gh = (int)((double)sh * scale / PATCH + 0.5);
    if (gw < 2) gw = 2;
    if (gh < 2) gh = 2;
    gw &= ~1;
    gh &= ~1;
    while (gw * gh > max_patches && (gw > 2 || gh > 2)) {
        if (gw >= gh && gw > 2) gw -= 2; else if (gh > 2) gh -= 2; else break;
    }

    const int W = gw * PATCH, H = gh * PATCH;
    float *px = (float *)malloc((size_t)gw * gh * 3 * PATCH * PATCH * sizeof(float));
    if (!px) { stbi_image_free(img); return NULL; }

    const float rx = (float)sw / (float)W, ry = (float)sh / (float)H;
    for (int py = 0; py < gh; py++) {
        for (int pxi = 0; pxi < gw; pxi++) {
            float *dst = px + ((size_t)py * gw + pxi) * 3 * PATCH * PATCH;
            for (int c = 0; c < 3; c++)
                for (int j = 0; j < PATCH; j++)
                    for (int i = 0; i < PATCH; i++) {
                        const float fx = ((float)(pxi * PATCH + i) + 0.5f) * rx - 0.5f;
                        const float fy = ((float)(py * PATCH + j) + 0.5f) * ry - 0.5f;
                        const float v = sample(img, sw, sh, 3, fx, fy, c) / 255.0f;
                        dst[((size_t)c * PATCH + j) * PATCH + i] =
                            (v - mean[c]) / std[c];
                    }
        }
    }
    stbi_image_free(img);
    *out_h = gh;
    *out_w = gw;
    return px;
}

static void quant_summary(waste_ctx *c)
{
    static const struct { int fmt; const char *name; } tbl[] = {
        { 7, "Q3G" }, { 3, "Q4G" }, { 2, "Q8G" }, { 1, "F16" }, { 0, "F32" },
    };
    int n = snprintf(c->quant, sizeof c->quant, "experts VQ%dR, trunk",
                     c->m.stages);
    size_t off = (n > 0 && (size_t)n < sizeof c->quant) ? (size_t)n : 0;
    const char *sep = " ";
    for (size_t i = 0; i < sizeof tbl / sizeof *tbl; i++) {
        if (!(c->m.trunk_fmts & (1u << tbl[i].fmt))) continue;
        n = snprintf(c->quant + off, sizeof c->quant - off, "%s%s",
                     sep, tbl[i].name);
        if (n < 0 || (size_t)n >= sizeof c->quant - off) break;
        off += (size_t)n;
        sep = "/";
    }
}

