ic void softmax_row(float *a, int n)
{
    float mx = a[0];
    for (int i = 1; i < n; i++) if (a[i] > mx) mx = a[i];
    float s = 0;
    for (int i = 0; i < n; i++) { a[i] = expf(a[i] - mx); s += a[i]; }
    const float inv = 1.0f / s;
    for (int i = 0; i < n; i++) a[i] *= inv;
}

