int main(int argc, char **argv)
{
    if (argc < 6) {
        fprintf(stderr, "usage: %s MODEL pixels.bin H W out.bin\n", argv[0]);
        return 2;
    }
    const int h = atoi(argv[3]), w = atoi(argv[4]);
    waste_model m;
    if (waste_model_load(&m, argv[1], 512, 0, 1)) { fprintf(stderr, "load\n"); return 1; }
    if (!waste_vision_available(&m)) { fprintf(stderr, "no vision tower\n"); return 1; }

    const int L = h * w, PX = 3 * 14 * 14;
    float *px = (float *)malloc((size_t)L * PX * sizeof(float));
    FILE *f = fopen(argv[2], "rb");
    if (!f || fread(px, sizeof(float), (size_t)L * PX, f) != (size_t)L * PX) {
        fprintf(stderr, "pixels\n"); return 1;
    }
    fclose(f);

    /* a staged run writes L x vt_hidden instead of N x text_hidden */
    const char *st = getenv("WASTE_VIS_STAGE");
    const int N = st ? L : (h / 2) * (w / 2);
    const int TH = st ? m.vcfg.hidden : m.vcfg.text_hidden;
    float *out = (float *)malloc((size_t)N * TH * sizeof(float));
    if (waste_vision_encode(&m, px, h, w, out)) { fprintf(stderr, "encode\n"); return 1; }

    double mean = 0, sq = 0;
    for (size_t i = 0; i < (size_t)N * TH; i++) { mean += out[i]; sq += out[i] * out[i]; }
    mean /= (double)N * TH;
    printf("grid %dx%d -> (%d, %d)  mean %+.5f  std %.5f\n", h, w, N, TH,
           mean, sqrt(sq / ((double)N * TH) - mean * mean));

    f = fopen(argv[5], "wb");
    fwrite(out, sizeof(float), (size_t)N * TH, f);
    fclose(f);
    waste_model_free(&m);
    free(px); free(out);
    return 0;
}

static void show_chosen_budget(waste_ctx *c, const opts *o)
{
    if (o->budget || o->quiet) return;
    waste_memplan u;
    if (waste_memory_used(c, &u) != WASTE_OK) return;
    /* waste_memory_used reports the cache the engine really allocated, so
     * this is what is held, not what was allowed. */
    const uint64_t used = u.trunk_bytes + u.state_bytes + u.scratch_bytes +
                          u.min_expert_cache;
    const uint64_t phys = waste_physical_ram();
    char ub[32], cb[32], pb[32];
    human(used, ub, 32);
    human(u.min_expert_cache, cb, 32);
    if (phys) {
        human(phys, pb, 32);
        fprintf(stderr, "waste: no --budget, using %s of %s (expert cache %s)\n",
                ub, pb, cb);
    } else {
        fprintf(stderr, "waste: no --budget, using %s (expert cache %s)\n", ub, cb);
    }
}

nt spec_cmp(const void *a, const void *b)
{
    return ((const tok_special *)b)->len - ((const tok_special *)a)->len;
}

static

oid load_specials(waste_tok *t, const char *dir)
{
    char path[512];
    snprintf(path, sizeof path, "%s/specials.json", dir);
    FILE *f = fopen(path, "rb");
    if (!f) return;
    fseek(f, 0, SEEK_END);
    const long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)n + 1);
    if (!buf || fread(buf, 1, (size_t)n, f) != (size_t)n) { free(buf); fclose(f); return; }
    buf[n] = 0;
    fclose(f);

    int cap = 16;
    t->special = (tok_special *)malloc((size_t)cap * sizeof *t->special);
    if (!t->special) { free(buf); return; }

    const char *p = buf;
    while ((p = strstr(p, "\"id\"")) != NULL) {
        const int32_t id = (int32_t)strtol(strchr(p, ':') + 1, NULL, 10);
        const char *tk = strstr(p, "\"text\"");
        if (!tk) break;
        const char *q = strchr(tk + 6, '"');
        if (!q) break;
        q++;
        const char *e = q;
        while (*e && *e != '"') e += (*e == '\\' && e[1]) ? 2 : 1;
        const int len = (int)(e - q);
        if (len > 0) {
            if (t->n_special == cap) {
                cap *= 2;
                tok_special *g = (tok_special *)realloc(t->special, (size_t)cap * sizeof *g);
                if (!g) break;
                t->special = g;
            }
            char *txt = (char *)malloc((size_t)len + 1);
            if (!txt) break;
            memcpy(txt, q, (size_t)len);
            txt[len] = 0;
            t->special[t->n_special].text = txt;
            t->special[t->n_special].len = len;
            t->special[t->n_special].id = id;
            t->n_special++;
        }
        p = e;
    }
    free(buf);
    qsort(t->special, (size_t)t->n_special, sizeof *t->special, spec_cmp);
}

    lo

static void jstr_field(const char *js, const char *key, int idx,
                       char *out, size_t cap)
{
    out[0] = 0;
    const char *k = strstr(js, key);
    if (!k) return;
    const char *p = strchr(k + strlen(key), '[');
    if (!p) return;
    for (int i = 0; i <= idx; i++) {
        p = strchr(p, '"');
        if (!p) return;
        if (i < idx) { p = strchr(p + 1, '"'); if (!p) return; p++; }
    }
    p++;
    size_t n = 0;
    while (*p && *p != '"' && n + 1 < cap) {
        if (*p == '\\' && p[1]) {           /* \n and friends */
            p++;
            out[n++] = *p == 'n' ? '\n' : *p == 't' ? '\t' : *p;
        } else out[n++] = *p;
        p++;
    }
    out[n] = 0;
}

static int load_chatfmt(const char *model, chatfmt *f)
{
    memset(f, 0, sizeof *f);
    char path[1024];
    snprintf(path, sizeof path, "%s/chat.json", model);
    FILE *fp = fopen(path, "rb");
    if (!fp) return 0;
    char buf[8192];
    const size_t n = fread(buf, 1, sizeof buf - 1, fp);
    fclose(fp);
    buf[n] = 0;
    jstr_field(buf, "\"system\"", 0, f->sys_p, sizeof f->sys_p);
    jstr_field(buf, "\"system\"", 1, f->sys_s, sizeof f->sys_s);
    jstr_field(buf, "\"user\"", 0, f->usr_p, sizeof f->usr_p);
    jstr_field(buf, "\"user\"", 1, f->usr_s, sizeof f->usr_s);
    jstr_field(buf, "\"assistant\"", 0, f->asst_p, sizeof f->asst_p);
    jstr_field(buf, "\"assistant\"", 1, f->asst_s, sizeof f->asst_s);
    /* "open" is a bare string, not a pair; reuse the scanner on a fake array */
    const char *o = strstr(buf, "\"open\"");
    if (o) {
        const char *q = strchr(o + 6, '"');
        if (q) {
            size_t i = 0;
            for (q++; *q && *q != '"' && i + 1 < sizeof f->open; q++) {
                if (*q == '\\' && q[1]) { q++; f->open[i++] = *q == 'n' ? '\n' : *q == 't' ? '\t' : *q; }
                else f->open[i++] = *q;
            }
            f->open[i] = 0;
        }
    }
    f->have = f->usr_p[0] || f->asst_p[0] || f->open[0];
    return f->have;
}

uint64_t waste_physical_ram(void)
{
#if defined(__APPLE__)
    uint64_t v = 0;
    size_t n = sizeof v;
    if (sysctlbyname("hw.memsize", &v, &n, NULL, 0) == 0) return v;
    return 0;
#elif defined(__linux__)
    const long p = sysconf(_SC_PHYS_PAGES), z = sysconf(_SC_PAGESIZE);
    return (p > 0 && z > 0) ? (uint64_t)p * (uint64_t)z : 0;
#else
    return 0;
#endif
}

atic char *read_prompt(const opts *o)
{
    FILE *f = NULL;
    const char *arg = o->n_pos > 1 ? o->pos[1] : NULL;
    if (o->file) {
        f = strcmp(o->file, "-") ? fopen(o->file, "rb") : stdin;
        if (!f) { fprintf(stderr, "cannot read %s\n", o->file); return NULL; }
    } else if (arg && strcmp(arg, "-")) {
        char *d = (char *)malloc(strlen(arg) + 1);
        if (d) memcpy(d, arg, strlen(arg) + 1);
        return d;
    } else if (arg || !isatty(fileno(stdin))) {
        f = stdin;
    } else {
        return NULL;                               /* nothing to read */
    }

    size_t cap = 4096, n = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) { if (f != stdin) fclose(f); return NULL; }
    for (;;) {
        if (n + 1 >= cap) {
            char *g = (char *)realloc(buf, cap *= 2);
            if (!g) { free(buf); if (f != stdin) fclose(f); return NULL; }
            buf = g;
        }
        const size_t got = fread(buf + n, 1, cap - n - 1, f);
        n += got;
        if (got == 0) break;
    }
    buf[n] = 0;
    while (n && (buf[n - 1] == '\n' || buf[n - 1] == '\r')) buf[--n] = 0;
    if (f != stdin) fclose(f);
    return buf;
}

atic int cmd_tokens(int argc, char **argv, int decode)
{
    opts o; opts_init(&o);
    if (parse_opts(argc, argv, 2, &o)) return 2;
    if (o.n_pos < 1) {
        fprintf(stderr, "usage: waste %s MODEL [text|ids | - | --file F]\n",
                decode ? "detokenize" : "tokenize");
        return 2;
    }
    char *text = read_prompt(&o);
    if (!text || !*text) { free(text); fprintf(stderr, "nothing to read\n"); return 2; }
    waste_ctx *c;
    const waste_status st = open_model(o.pos[0], &o, &c);
    if (st != WASTE_OK) { free(text); return fail("open", st); }

    int rc = 0;
    if (decode) {
        int32_t ids[MAXTOK];
        size_t n = 0;
        for (char *t = strtok(text, " ,\t\n"); t && n < MAXTOK; t = strtok(NULL, " ,\t\n"))
            ids[n++] = (int32_t)atoi(t);
        char out[8192];
        size_t used = 0;
        const waste_status d = waste_detokenize(c, ids, n, out, sizeof out, &used);
        if (d != WASTE_OK) rc = fail("detokenize", d);
        else printf("%.*s\n", (int)used, out);
    } else {
        int32_t ids[MAXTOK];
        size_t n = 0;
        const waste_status t = waste_tokenize(c, text, 0, ids, MAXTOK, &n);
        if (t != WASTE_OK) rc = fail("tokenize", t);
        else if (o.json) {
            printf("{\"n\":%zu,\"ids\":[", n);
            for (size_t i = 0; i < n; i++) printf("%s%d", i ? "," : "", ids[i]);
            printf("]}\n");
        } else {
            for (size_t i = 0; i < n; i++) printf("%s%d", i ? " " : "", ids[i]);
            printf("\n");
        }
    }
    waste_close(c);
    free(text);
    return rc;
}

atic int cmd_eval(int argc, char **argv)
{
    opts o; opts_init(&o);
    if (parse_opts(argc, argv, 2, &o)) return 2;
    if (o.n_pos < 1) {
        fprintf(stderr, "usage: waste eval MODEL [\"prompt\" | - | --file F] "
                        "[--top-k N] [--json]\n");
        return 2;
    }
    char *prompt = read_prompt(&o);
    if (!prompt || !*prompt) { free(prompt); fprintf(stderr, "no prompt\n"); return 2; }
    waste_ctx *c;
    const waste_status st = open_model(o.pos[0], &o, &c);
    if (st != WASTE_OK) { free(prompt); return fail("open", st); }

    int32_t ids[MAXTOK];
    size_t n = 0;
    waste_status t = waste_tokenize(c, prompt, 0, ids, MAXTOK, &n);
    if (t != WASTE_OK) { waste_close(c); free(prompt); return fail("tokenize", t); }

    const float *lg = NULL;
    size_t vocab = 0;
    t = waste_eval(c, ids, n, &lg, &vocab);
    if (t != WASTE_OK) { waste_close(c); free(prompt); return fail("eval", t); }

    /* softmax over the whole vocabulary, then report the top few */
    int k = o.top_k > 0 ? o.top_k : 10;
    if ((size_t)k > vocab) k = (int)vocab;
    float mx = lg[0];
    for (size_t v = 1; v < vocab; v++) if (lg[v] > mx) mx = lg[v];
    double sum = 0;
    for (size_t v = 0; v < vocab; v++) sum += exp((double)(lg[v] - mx));

    /* Its own array: borrowing the tail of `ids` would collide with the
     * prompt as soon as the prompt got long. */
    int32_t *picked = (int32_t *)malloc((size_t)k * sizeof *picked);
    if (!picked) { waste_close(c); free(prompt); return fail("eval", WASTE_E_OOM); }

    if (o.json) printf("{\"prompt_tokens\":%zu,\"vocab\":%zu,\"top\":[", n, vocab);
    for (int i = 0; i < k; i++) {
        size_t best = 0;
        float bv = -3.4e38f;
        for (size_t v = 0; v < vocab; v++) {
            int seen = 0;
            for (int j = 0; j < i; j++) if (picked[j] == (int32_t)v) seen = 1;
            if (!seen && lg[v] > bv) { bv = lg[v]; best = v; }
        }
        picked[i] = (int32_t)best;
        const double pr = exp((double)(bv - mx)) / sum;
        char piece[64] = "";
        size_t used = 0;
        const int32_t one = (int32_t)best;
        waste_detokenize(c, &one, 1, piece, sizeof piece, &used);
        if (o.json)
            printf("%s{\"id\":%zu,\"logit\":%.4f,\"prob\":%.6f}", i ? "," : "", best, bv, pr);
        else
            printf("  %6zu  %8.4f  %7.4f  %.*s\n", best, bv, pr, (int)used, piece);
    }
    if (o.json) printf("]}\n");

    free(picked);
    waste_close(c);
    free(prompt);
    return 0;
}

nt cfg_sane(const waste_config *c)
{
    if (c->n_layers < 1 || c->n_layers > WASTE_MAX_LAYERS) return 0;
    if (c->hidden   < 1 || c->hidden   > (1 << 20)) return 0;
    if (c->vocab    < 1 || c->vocab    > (1 << 24)) return 0;
    if (c->n_heads  < 1 || c->n_heads  > (1 << 16)) return 0;
    if (c->eps <= 0.0f || !(c->eps < 1.0f)) return 0;      /* also catches NaN */
    /* MoE is optional, but if there are experts the routing has to make
     * sense: top_k above the pool overruns the per-token index array. */
    if (c->n_experts < 0 || c->n_experts > (1 << 20)) return 0;
    if (c->n_experts && (c->top_k < 1 || c->top_k > c->n_experts ||
                         c->top_k > 64)) return 0;
    if (c->moe_inter < 0 || c->moe_inter > (1 << 20)) return 0;
    if (c->dense_inter < 0 || c->dense_inter > (1 << 20)) return 0;
    if (c->kda_heads < 0 || c->kda_heads > (1 << 16)) return 0;
    if (c->kda_dim   < 0 || c->kda_dim   > (1 << 16)) return 0;
    if (c->conv_k    < 0 || c->conv_k    > 64) return 0;
    if (c->kv_lora   < 0 || c->q_lora    < 0) return 0;
    if (c->qk_nope   < 0 || c->qk_rope   < 0 || c->v_head < 0) return 0;
    if (c->first_dense < 0 || c->first_dense > c->n_layers) return 0;
    if (c->n_shared  < 0 || c->n_shared  > 64) return 0;
    if (c->latent_dim < 0 || c->latent_dim > (1 << 20)) return 0;
    if (c->attn_res_block < 0 || c->attn_res_block > c->n_layers) return 0;
    return 1;
}

