static int pread_all(int fd, void *dst, size_t n, long off)
{
    uint8_t *p = (uint8_t *)dst;
    while (n) {
        const ssize_t r = pread(fd, p, n, (off_t)off);
        if (r <= 0) return -1;
        p += r; n -= (size_t)r; off += r;
    }
    return 0;
}

static void trunk_row(waste_model *m, const waste_tensor *t, long row,
                      const int8_t **q, const uint16_t **qs)
{
    const int ng = (t->shape[t->ndim - 1] + t->group - 1) / t->group;
    if (!t->on_disk) {
        *q  = t->q  + (size_t)row * t->rowbytes;
        *qs = t->qs + (size_t)row * ng;
        return;
    }
    if (pread_all(m->trunk_fd, m->embrow, t->rowbytes,
                  t->file_off + row * (long)t->rowbytes) ||
        pread_all(m->trunk_fd, m->embsc, (size_t)ng * sizeof(uint16_t),
                  t->file_scale_off + row * (long)ng * 2)) {
        memset(m->embrow, 0, t->rowbytes);
        memset(m->embsc, 0, (size_t)ng * sizeof(uint16_t));
    }
    *q = m->embrow; *qs = m->embsc;
}

static int pread_all(int fd, void *dst, size_t n, long off)
{
    uint8_t *p = (uint8_t *)dst;
    while (n) {
        const ssize_t r = pread(fd, p, n, (off_t)off);
        if (r <= 0) return -1;
        p += r; n -= (size_t)r; off += r;
    }
    return 0;
}

static void deq_row(const waste_tensor *t, long r, int cols, float *dst)
{
    if (!t->q) {
        memcpy(dst, t->data + (size_t)r * cols, (size_t)cols * sizeof(float));
        return;
    }
    const int g = t->group, ng = (cols + g - 1) / g;
    const int8_t *row = t->q + (size_t)r * t->rowbytes;
    const uint16_t *ws = t->qs + (size_t)r * ng;
    for (int k = 0; k < ng; k++) {
        const float s = f16_to_f32(ws[k]);
        const int base = k * g;
        const int lim = (base + g <= cols) ? g : cols - base;
        if (t->bits == 8) {
            const int8_t *w = row + (size_t)base;
            for (int i = 0; i < lim; i++) dst[base + i] = s * (float)w[i];
        } else if (t->bits == 4) {
            const uint8_t *p4 = (const uint8_t *)row + (size_t)base / 2;
            for (int i = 0; i < lim; i++) {
                const uint8_t byte = p4[i >> 1];
                const int v = (i & 1) ? (byte >> 4) - 8 : (byte & 0x0F) - 8;
                dst[base + i] = s * (float)v;
            }
        } else {
            const uint8_t *p3 = (const uint8_t *)row;
            for (int i = 0; i < lim; i++)
                dst[base + i] = s * (float)q3_at(p3, (long)base + i);
        }
    }
}

atic void mla_head_range(int lo, int hi, void *ap)
{
    const mla_par *a = (const mla_par *)ap;
    const int kl = a->kv_lora, latd = a->latd, S = a->S;
    const int nope = a->qk_nope, rope = a->qk_rope, vh = a->vh;
    const int wrows = nope + vh;                 /* kv_b_proj rows per head */

    for (int h = lo; h < hi; h++) {
        const float *qh = a->q + (size_t)h * a->qd;
        float *qa  = a->m->qabs + (size_t)h * kl;
        float *ca  = a->m->cacc + (size_t)h * kl;
        float *rw  = a->m->mrow + (size_t)h * kl;
        float *sc  = a->m->att  + (size_t)h * S;

        /* q~ = W_kb^T q_nope */
        memset(qa, 0, (size_t)kl * sizeof(float));
        for (int i = 0; i < nope; i++) {
            const float qi = qh[i];
            if (qi == 0.0f) continue;
            deq_row(a->kvb, (long)h * wrows + i, kl, rw);
            for (int j = 0; j < kl; j++) qa[j] += qi * rw[j];
        }

        for (int s = 0; s < S; s++) {
            const float *cs = a->lat + (size_t)s * latd;
            float acc = dotf(qa, cs, kl);
            acc += dotf(qh + nope, cs + kl, rope);
            sc[s] = acc * a->scale;
        }
        softmax(sc, S);

        memset(ca, 0, (size_t)kl * sizeof(float));
        for (int s = 0; s < S; s++) {
            const float w = sc[s];
            const float *cs = a->lat + (size_t)s * latd;
            for (int j = 0; j < kl; j++) ca[j] += w * cs[j];
        }

        /* o = W_vb c~ */
        float *oh = a->o + (size_t)h * vh;
        for (int i = 0; i < vh; i++) {
            deq_row(a->kvb, (long)h * wrows + nope + i, kl, rw);
            oh[i] = dotf(rw, ca, kl);
        }
    }
}

static void kda_step_range(int lo, int hi, void *ap)
{
    const kda_par *a = (const kda_par *)ap;
    waste_k.kda_step(hi - lo, a->K, a->V,
                     a->q + (size_t)lo * a->K, a->k + (size_t)lo * a->K,
                     a->v + (size_t)lo * a->V, a->g + (size_t)lo * a->K,
                     a->beta + lo,
                     a->S + (size_t)lo * a->K * a->V,
                     a->o + (size_t)lo * a->V,
                     a->u + (size_t)lo * a->V);
}

static inline int q3_at(const uint8_t *p, long i)
{
    const long off = i * 3;
    const int v = (p[off >> 3] >> (off & 7)) | (p[(off >> 3) + 1] << (8 - (off & 7)));
    return (v & 7) - 4;
}

void waste_kda_decay_gate(float *g, const float *A_log, const float *dt_bias,
                          int H, int D, float lower_bound)
{
    waste_kda_decay_gate_ex(g, A_log, dt_bias, H, D, lower_bound, 0);
}

int waste_ecache_save_usage(const waste_ecache *c, const char *path,
                            uint64_t tokens)
{
    if (!c->slot || !path) return -1;
    FILE *f = fopen(path, "wb");
    if (!f) return -1;
    waste_usage_hdr h = { WASTE_MAGIC_USAGE, 1, tokens };
    int rc = fwrite(&h, sizeof h, 1, f) == 1 ? 0 : -1;
    for (int i = 0; i < c->n_slots && !rc; i++) {
        if (c->slot[i].key < 0) continue;
        waste_usage_ent e;
        e.layer = (uint16_t)(c->slot[i].key >> 16);
        e.expert_id = (uint16_t)(c->slot[i].key & 0xFFFF);
        e.hits = c->slot[i].hits;
        e.last_seen = (uint32_t)c->slot[i].last;
        e.next_layer_top = 0;
        if (fwrite(&e, sizeof e, 1, f) != 1) rc = -1;
    }
    fclose(f);
    if (rc) remove(path);
    return rc;
}

int waste_ecache_warm(waste_ecache *c, const char *path,
                      waste_fetch_fn fetch, void *user)
{
    if (!c->slot || !path) return -1;
    FILE *f = fopen(path, "rb");
    if (!f) return -1;
    waste_usage_hdr h;
    if (fread(&h, sizeof h, 1, f) != 1 || h.magic != WASTE_MAGIC_USAGE) {
        fclose(f);
        return -1;
    }

    long start = ftell(f);
    fseek(f, 0, SEEK_END);
    const long n = (ftell(f) - start) / (long)sizeof(waste_usage_ent);
    fseek(f, start, SEEK_SET);
    if (n <= 0) { fclose(f); return 0; }

    waste_usage_ent *ent = (waste_usage_ent *)malloc((size_t)n * sizeof *ent);
    if (!ent || fread(ent, sizeof *ent, (size_t)n, f) != (size_t)n) {
        free(ent); fclose(f); return -1;
    }
    fclose(f);

    /* hottest first; a partial selection is enough since we stop at n_slots */
    const int want = (int)n < c->n_slots ? (int)n : c->n_slots;
    for (int i = 0; i < want; i++) {
        int best = i;
        for (int j = i + 1; j < n; j++)
            if (ent[j].hits > ent[best].hits) best = j;
        const waste_usage_ent t = ent[i]; ent[i] = ent[best]; ent[best] = t;
    }

    int loaded = 0;
    for (int i = 0; i < want; i++) {
        const int32_t key = ((int32_t)ent[i].layer << 16) | ent[i].expert_id;
        if (ec_lookup(c, key) >= 0) continue;
        const int vi = ec_victim(c);
        if (vi < 0) break;
        if (fetch(user, ent[i].layer, ent[i].expert_id, c->slot[vi].data) != 0) continue;
        const int had = c->slot[vi].key >= 0;
        c->slot[vi].key = key;
        c->slot[vi].hits = ent[i].hits;
        c->slot[vi].last = ++c->clock;
        if (had) ec_rehash(c); else ec_insert(c, key, vi);
        loaded++;
    }
    free(ent);
    return loaded;
}

int waste_model_warm_cache(waste_model *m, const char *dir)
{
    if (m->cache.n_slots <= 0) return 0;
    char p[512];
    snprintf(p, sizeof p, "%s/usage.waste", dir);
    return waste_ecache_warm(&m->cache, p, bank_fetch, m);
}

int waste_model_save_usage(const waste_model *m, const char *dir)
{
    if (m->cache.n_slots <= 0) return 0;
    char p[512];
    snprintf(p, sizeof p, "%s/usage.waste", dir);
    return waste_ecache_save_usage(&m->cache, p, m->cache.clock);
}

static void state_fill(const waste_model *m, waste_state_hdr *h, int pos)
{
    const waste_config *c = &m->cfg;
    memset(h, 0, sizeof *h);
    h->magic = WASTE_MAGIC_KDASTATE;
    h->version = 1;
    h->n_layers = c->n_layers; h->hidden = c->hidden;
    h->kda_heads = c->kda_heads; h->kda_dim = c->kda_dim; h->conv_k = c->conv_k;
    h->n_heads = c->n_heads; h->qk_nope = c->qk_nope; h->qk_rope = c->qk_rope;
    h->v_head = c->v_head; h->attn_res_block = c->attn_res_block;
    h->pos = pos; h->n_blockres = m->n_blockres;
}

int waste_model_state_save(const waste_model *m, const char *path, int pos)
{
    const waste_config *c = &m->cfg;
    FILE *f = fopen(path, "wb");
    if (!f) return -1;
    waste_state_hdr h;
    state_fill(m, &h, pos);
    int rc = fwrite(&h, sizeof h, 1, f) == 1 ? 0 : -1;

    const int H = c->kda_heads, D = c->kda_dim, C = H * D;
    const int qd = c->qk_nope + c->qk_rope;
    for (int L = 0; L < c->n_layers && !rc; L++) {
        if (c->kda_layer[L]) {
            if (fwrite(m->S[L], sizeof(float), (size_t)H * D * D, f) != (size_t)H * D * D) rc = -1;
            const size_t cn = (size_t)3 * C * (c->conv_k - 1);
            if (!rc && fwrite(m->conv[L], sizeof(float), cn, f) != cn) rc = -1;
        } else {
            const int32_t nkv = m->n_kv[L];
            if (fwrite(&nkv, sizeof nkv, 1, f) != 1) { rc = -1; break; }
            const size_t kn = (size_t)nkv * c->n_heads * qd;
            const size_t vn = (size_t)nkv * c->n_heads * c->v_head;
            if (kn && fwrite(m->kcache[L], sizeof(float), kn, f) != kn) rc = -1;
            if (!rc && vn && fwrite(m->vcache[L], sizeof(float), vn, f) != vn) rc = -1;
        }
    }
    if (!rc && c->attn_res_block && m->n_blockres > 0) {
        const size_t n = (size_t)m->n_blockres * c->hidden;
        if (fwrite(m->blockres, sizeof(float), n, f) != n) rc = -1;
    }
    if (!rc && fwrite(m->x, sizeof(float), (size_t)c->hidden, f) != (size_t)c->hidden) rc = -1;
    fclose(f);
    if (rc) remove(path);
    return rc;
}

int waste_model_state_load(waste_model *m, const char *path, int *pos)
{
    const waste_config *c = &m->cfg;
    FILE *f = fopen(path, "rb");
    if (!f) return -1;
    waste_state_hdr h, want;
    state_fill(m, &want, 0);
    if (fread(&h, sizeof h, 1, f) != 1) { fclose(f); return -1; }
    /* every shape must match; pos and n_blockres are the payload */
    if (h.magic != want.magic || h.version != want.version ||
        h.n_layers != want.n_layers || h.hidden != want.hidden ||
        h.kda_heads != want.kda_heads || h.kda_dim != want.kda_dim ||
        h.conv_k != want.conv_k || h.n_heads != want.n_heads ||
        h.qk_nope != want.qk_nope || h.qk_rope != want.qk_rope ||
        h.v_head != want.v_head || h.attn_res_block != want.attn_res_block) {
        fclose(f);
        return -2;                       /* state does not belong to this model */
    }

    const int H = c->kda_heads, D = c->kda_dim, C = H * D;
    const int qd = c->qk_nope + c->qk_rope;
    int rc = 0;
    for (int L = 0; L < c->n_layers && !rc; L++) {
        if (c->kda_layer[L]) {
            if (fread(m->S[L], sizeof(float), (size_t)H * D * D, f) != (size_t)H * D * D) rc = -1;
            const size_t cn = (size_t)3 * C * (c->conv_k - 1);
            if (!rc && fread(m->conv[L], sizeof(float), cn, f) != cn) rc = -1;
        } else {
            int32_t nkv = 0;
            if (fread(&nkv, sizeof nkv, 1, f) != 1) { rc = -1; break; }
            if (nkv < 0 || nkv > m->kv_cap) { rc = -1; break; }
            const size_t kn = (size_t)nkv * c->n_heads * qd;
            const size_t vn = (size_t)nkv * c->n_heads * c->v_head;
            if (kn && fread(m->kcache[L], sizeof(float), kn, f) != kn) rc = -1;
            if (!rc && vn && fread(m->vcache[L], sizeof(float), vn, f) != vn) rc = -1;
            m->n_kv[L] = nkv;
        }
    }
    m->n_blockres = h.n_blockres;
    if (!rc && c->attn_res_block && h.n_blockres > 0) {
        const size_t n = (size_t)h.n_blockres * c->hidden;
        if (fread(m->blockres, sizeof(float), n, f) != n) rc = -1;
    }
    if (!rc && fread(m->x, sizeof(float), (size_t)c->hidden, f) != (size_t)c->hidden) rc = -1;
    fclose(f);
    if (!rc && pos) *pos = h.pos;
    return rc;
}

waste_status waste_save_usage(waste_ctx *c)
{
    if (!c) return WASTE_E_ARG;
    return waste_model_save_usage(&c->m, c->path) < 0 ? WASTE_E_IO : WASTE_OK;
}

atic int on_tok(const waste_token_info *i, const char *piece, void *user)
{
    (void)piece;
    sink *s = (sink *)user;
    if (s->n < 64) s->ids[s->n++] = i->token;
    return 0;
}

t main(int argc, char **argv)
{
    if (argc < 2) { fprintf(stderr, "usage: %s MODEL\n", argv[0]); return 2; }
    waste_cfg cfg;
    waste_cfg_init(&cfg);
    cfg.ram_budget_bytes = 6ULL << 30;
    waste_ctx *c;
    if (waste_open(argv[1], &cfg, &c) != WASTE_OK) { fprintf(stderr, "open\n"); return 1; }

    int32_t prompt[64];
    size_t n = 0;
    if (waste_tokenize(c, "The capital of France is Paris, and the capital of Italy is",
                       0, prompt, 64, &n) != WASTE_OK) { fprintf(stderr, "tok\n"); return 1; }

    waste_gen_params p;
    waste_gen_params_init(&p);
    p.max_tokens = 6;

    /* run the prompt, save, then continue */
    const char *path = "/tmp/waste_state_test.bin";
    sink a = {{0}, 0};
    const float *lg;
    if (waste_eval(c, prompt, n, &lg, NULL) != WASTE_OK) return 1;
    if (waste_state_save(c, path) != WASTE_OK) { fprintf(stderr, "save\n"); return 1; }
    int32_t nxt[1] = { 0 };
    for (int v = 1; v < 163840; v++) if (lg[v] > lg[nxt[0]]) nxt[0] = v;
    waste_generate(c, nxt, 1, &p, on_tok, &a);

    /* fresh context, load the save, continue from the same token */
    waste_close(c);
    if (waste_open(argv[1], &cfg, &c) != WASTE_OK) return 1;
    const waste_status st = waste_state_load(c, path);
    if (st != WASTE_OK) { fprintf(stderr, "load: %s\n", waste_strerror(st)); return 1; }
    sink b = {{0}, 0};
    waste_generate(c, nxt, 1, &p, on_tok, &b);
    waste_close(c);

    int same = (a.n == b.n);
    for (int i = 0; i < a.n && same; i++) same = (a.ids[i] == b.ids[i]);
    printf("fresh   :");
    for (int i = 0; i < a.n; i++) printf(" %d", a.ids[i]);
    printf("\nrestored:");
    for (int i = 0; i < b.n; i++) printf(" %d", b.ids[i]);
    printf("\n%s\n", same ? "STATE OK — restored session continues identically"
                          : "STATE MISMATCH");
    remove(path);
    return same ? 0 : 1;
}

atic void mm_rows(int b, int e, void *p)
{
    mm_arg *a = (mm_arg *)p;
    for (int o = b; o < e; o++) {
        const float *row = a->W + (size_t)o * a->in;
        for (int t = 0; t < a->T; t++)
            a->Y[(size_t)t * a->out + o] = dotf(row, a->X + (size_t)t * a->in, a->in);
    }
}

atic void matmul_f32(float *Y, const float *W, const float *X,
                       int out, int in, int T)
{
    mm_arg a = { Y, W, X, in, out, T };
    waste_parallel_for(out, 32, mm_rows, &a);
}

atic void mmq_rows(int b, int e, void *p)
{
    mmq_arg *a = (mmq_arg *)p;
    const int g = a->group, ng = a->ng;
    float *row = (float *)malloc((size_t)a->in * sizeof(float));
    if (!row) return;
    for (int o = b; o < e; o++) {
        const int8_t *q = a->W + (size_t)o * ng * g;
        const uint16_t *sc = a->ws + (size_t)o * ng;
        for (int k = 0; k < ng; k++) {
            const float s = f16_to_f32(sc[k]);
            const int lim = (k * g + g <= a->in) ? g : a->in - k * g;
            for (int i = 0; i < lim; i++) row[k * g + i] = (float)q[(size_t)k * g + i] * s;
        }
        for (int t = 0; t < a->T; t++)
            a->Y[(size_t)t * a->out + o] = dotf(row, a->X + (size_t)t * a->in, a->in);
    }
    free(row);
}

atic void matmul_t(waste_model *m, float *Y, const waste_tensor *t,
                     const float *X, int out, int in, int T)
{
    (void)m;
    if (!t || (!t->q && !t->data)) {
        memset(Y, 0, (size_t)T * out * sizeof(float));
        return;
    }
    if (!t->q) { matmul_f32(Y, t->data, X, out, in, T); return; }
    const int g = t->group, ng = (in + g - 1) / g;
    mmq_arg a = { Y, t->q, t->qs, X, in, out, T, ng, g };
    waste_parallel_for(out, 32, mmq_rows, &a);
}

atic void vq_expand(waste_model *m, float *W, const uint8_t *idx,
                      const uint16_t *scale, int M, int N, int cb_base)
{
    const int nv_row = N / m->vec_dim, st = m->stages, en = m->cb_entries,
              vd = m->vec_dim;
    for (int r0 = 0; r0 < M; r0 += VQ_TILE) {
        const int nr = (r0 + VQ_TILE <= M) ? VQ_TILE : M - r0;
        const uint8_t *base = idx + (size_t)(r0 / VQ_TILE) * nv_row * VQ_TILE * st;
        for (int v = 0; v < nv_row; v++) {
            const uint8_t *ix = base + (size_t)v * VQ_TILE * st;
            for (int r = 0; r < nr; r++, ix += st) {
                float *dst = W + (size_t)(r0 + r) * N + (size_t)v * vd;
                for (int d = 0; d < vd; d++) dst[d] = 0.0f;
                for (int s = 0; s < st; s++) {
                    const float *C = m->codebooks +
                        ((size_t)(cb_base + s) * en + ix[s]) * vd;
                    for (int d = 0; d < vd; d++) dst[d] += C[d];
                }
            }
        }
    }
    for (int r = 0; r < M; r++) {
        const float sc = f16_to_f32(scale[r]);
        float *row = W + (size_t)r * N;
        for (int i = 0; i < N; i++) row[i] *= sc;
    }
}

atic int prefill_alloc(waste_model *m, int T)
{
    if (m->chunk_cap >= T) return 0;
    const waste_config *c = &m->cfg;
    const int hid = c->hidden, lat = c->latent_dim ? c->latent_dim : hid;
    const int wide = c->kda_heads * c->kda_dim;
    const int big = hid > wide ? hid : wide;
    const int inter = c->dense_inter > c->moe_inter ? c->dense_inter : c->moe_inter;
    const int nb = c->attn_res_block ? c->n_layers / c->attn_res_block + 2 : 1;

    free(m->cx); free(m->cnorm); free(m->cresid); free(m->cq); free(m->ckv);
    free(m->clat); free(m->cff); free(m->cexp); free(m->cblockres);
    free(m->cprefix); free(m->croute); free(m->crw);

    m->cx     = (float *)calloc((size_t)T * hid, sizeof(float));
    m->cnorm  = (float *)calloc((size_t)T * hid, sizeof(float));
    m->cresid = (float *)calloc((size_t)T * hid, sizeof(float));
    {   /* cq holds 2 LUTs per token plus one for `down` */
        const size_t lut_sz = (size_t)((hid > lat ? hid : lat) / 8) * 3 * 256;
        m->cq = (float *)calloc((size_t)(2 * T + 1) * lut_sz + 64, sizeof(float));
    }
    {   /* ckv holds the shared-expert staging: gate, up, out */
        const int si = c->moe_inter * (c->n_shared ? c->n_shared : 1);
        m->ckv = (float *)calloc((size_t)T * (size_t)(2 * si + hid) + 64, sizeof(float));
    }
    m->clat   = (float *)calloc((size_t)T * (size_t)(2 * lat + 2 * hid), sizeof(float));
    {   /* cff serves two callers: the per-token MoE staging (2*moe_inter +
         * lat) and the batched dense FFN (2 * T * dense_inter). Size for
         * whichever is larger — getting this wrong overflows silently. */
        const size_t moe_need = (size_t)2 * c->moe_inter + (size_t)(hid > lat ? hid : lat);
        const size_t dense_need = (size_t)2 * T * c->dense_inter;
        m->cff = (float *)calloc((moe_need > dense_need ? moe_need : dense_need) + 64,
                                 sizeof(float));
    }
    /* one expanded expert: gate/up [inter][lat] and down [hid][inter] */
    m->cexp   = (float *)calloc((size_t)2 * c->moe_inter * lat + (size_t)lat * c->moe_inter,
                                sizeof(float));
    m->cblockres = (float *)calloc((size_t)T * nb * hid, sizeof(float));
    m->cprefix   = (float *)calloc((size_t)T * hid, sizeof(float));
    m->croute = (int *)calloc((size_t)T * 64, sizeof(int));
    m->crw    = (float *)calloc((size_t)T * 64, sizeof(float));
    m->chunk_cap = T;
    return (m->cx && m->cnorm && m->cresid && m->cq && m->ckv && m->clat &&
            m->cff && m->cexp && m->cblockres && m->cprefix && m->croute &&
            m->crw) ? 0 : -1;
}

/*

ic void moe_chunk(waste_model *m, int L, const float *in, float *out, int nT)
{
    const waste_config *c = &m->cfg;
    const int E = c->n_experts, K = c->top_k, hid = c->hidden;
    const int lat = c->latent_dim ? c->latent_dim : hid, inter = c->moe_inter;
    int *route = m->croute;
    float *rw = m->crw;

    float *sc = m->att + 4096, *score = sc + E;
    const float *bias = T(m, "%smodel.layers.%d.block_sparse_moe.gate.e_score_correction_bias",
                          c->prefix, L);
    for (int t = 0; t < nT; t++) {
        matvec_t(m, sc, waste_find(m, tname("%smodel.layers.%d.block_sparse_moe.gate.weight",
                                            c->prefix, L)), in + (size_t)t * hid, E, hid);
        for (int e = 0; e < E; e++) score[e] = 1.0f / (1.0f + expf(-sc[e]));
        int *idx = route + (size_t)t * K;
        float *w = rw + (size_t)t * K;
        for (int j = 0; j < K; j++) {
            int best = -1; float bv = -1e30f;
            for (int e = 0; e < E; e++) {
                int taken = 0;
                for (int p = 0; p < j; p++) if (idx[p] == e) { taken = 1; break; }
                if (taken) continue;
                const float v = score[e] + (bias ? bias[e] : 0.0f);
                if (v > bv) { bv = v; best = e; }
            }
            idx[j] = best; w[j] = score[best];
        }
        if (c->renorm && K > 1) {
            float s = 0;
            for (int j = 0; j < K; j++) s += w[j];
            for (int j = 0; j < K; j++) w[j] /= (s + 1e-20f);
        }
        for (int j = 0; j < K; j++) w[j] *= c->routed_scale;
    }

    const float *xin = in;
    float *lat_in = m->clat, *ysum = lat_in + (size_t)nT * lat;
    if (c->latent_dim) {
        matmul_t(m, lat_in, waste_find(m, tname(
                     "%smodel.layers.%d.block_sparse_moe.routed_expert_down_proj.weight",
                     c->prefix, L)), in, lat, hid, nT);
        xin = lat_in;
    }
    memset(ysum, 0, (size_t)nT * lat * sizeof(float));

    /* gate/up tables: one per token, shared by every expert it routes to */
    const int lut_sz = ((hid > lat ? hid : lat) / m->vec_dim) * m->stages * m->cb_entries;
    float *lut_gu = m->cq;                    /* [nT][2][lut_sz] */
    float *lut_down = lut_gu + (size_t)nT * 2 * lut_sz;
    int lut_ready = 0;

    float *ga = m->cff, *ub = ga + inter, *acc = m->cff + 2 * inter;

    for (int e = 0; e < E; e++) {
        int used = 0;
        for (int i = 0; i < nT * K; i++) if (route[i] == e) { used = 1; break; }
        if (!used) continue;

        PROF_START(P_EDEQ);
        const uint8_t *rec = read_expert(m, L, e);
        PROF_END(P_EDEQ);
        if (!rec) continue;
        const waste_expert_hdr *h = (const waste_expert_hdr *)rec;
        const uint16_t *s16 = (const uint16_t *)(rec + h->chan_corr_off);

        PROF_START(P_EMM);
        if (!lut_ready) {
            for (int t = 0; t < nT; t++) {
                vq_build_lut(lut_gu + (size_t)(2 * t) * lut_sz, m->codebooks,
                             h->codebook_id + 0 * m->stages,
                             xin + (size_t)t * lat, lat, m->stages,
                             m->cb_entries, m->vec_dim);
                vq_build_lut(lut_gu + (size_t)(2 * t + 1) * lut_sz, m->codebooks,
                             h->codebook_id + 1 * m->stages,
                             xin + (size_t)t * lat, lat, m->stages,
                             m->cb_entries, m->vec_dim);
            }
            lut_ready = 1;
        }
        for (int t = 0; t < nT; t++) {
            float wj = 0;
            for (int j = 0; j < K; j++)
                if (route[(size_t)t * K + j] == e) { wj = rw[(size_t)t * K + j]; break; }
            if (wj == 0.0f) continue;

            vq_apply(m, ga, rec + h->gate_off, s16, inter, lat,
                     lut_gu + (size_t)(2 * t) * lut_sz);
            vq_apply(m, ub, rec + h->up_off, s16 + inter, inter, lat,
                     lut_gu + (size_t)(2 * t + 1) * lut_sz);
            if (c->act_situ)
                for (int i = 0; i < inter; i++)
                    ga[i] = waste_situ_pair(ga[i], ub[i], c->situ_beta, c->situ_linear_beta);
            else
                for (int i = 0; i < inter; i++) ga[i] = silu(ga[i]) * ub[i];
            vq_matvec(m, acc, rec + h->down_off, s16 + 2 * inter, ga, lat, inter,
                      h->codebook_id + 2 * m->stages, lut_down);
            float *dst = ysum + (size_t)t * lat;
            for (int i = 0; i < lat; i++) dst[i] += wj * acc[i];
        }
        PROF_END(P_EMM);
    }

    if (c->latent_dim) {
        if (c->latent_norm) {
            const float *nw = waste_find(m, tname(
                "%smodel.layers.%d.block_sparse_moe.routed_expert_norm.weight",
                c->prefix, L))->data;
            for (int t = 0; t < nT; t++)
                rmsnorm(ysum + (size_t)t * lat, ysum + (size_t)t * lat, nw, lat, c->eps);
        }
        matmul_t(m, out, waste_find(m, tname(
                     "%smodel.layers.%d.block_sparse_moe.routed_expert_up_proj.weight",
                     c->prefix, L)), ysum, hid, lat, nT);
    } else {
        memcpy(out, ysum, (size_t)nT * hid * sizeof(float));
    }

    /* shared experts, on the full hidden state */
    const int si = inter * (c->n_shared ? c->n_shared : 1);
    float *sa = m->ckv, *sb = sa + (size_t)nT * si, *sh = sb + (size_t)nT * si;
    matmul_t(m, sa, waste_find(m, tname(
                 "%smodel.layers.%d.block_sparse_moe.shared_experts.gate_proj.weight",
                 c->prefix, L)), in, si, hid, nT);
    matmul_t(m, sb, waste_find(m, tname(
                 "%smodel.layers.%d.block_sparse_moe.shared_experts.up_proj.weight",
                 c->prefix, L)), in, si, hid, nT);
    for (int i = 0; i < nT * si; i++)
        sa[i] = c->act_situ ? waste_situ_pair(sa[i], sb[i], c->situ_beta, c->situ_linear_beta)
                            : silu(sa[i]) * sb[i];
    matmul_t(m, sh, waste_find(m, tname(
                 "%smodel.layers.%d.block_sparse_moe.shared_experts.down_proj.weight",
                 c->prefix, L)), sa, hid, si, nT);
    for (int i = 0; i < nT * hid; i++) out[i] += sh[i];
}

/*

oat *waste_model_prefill(waste_model *m, const int *tokens, int n,
                                 int pos0)
{
    const waste_config *c = &m->cfg;
    const int hid = c->hidden;
    if (n <= 0) return m->logits;
    if (n == 1) return waste_model_step(m, tokens[0], pos0, NULL);
    if (n > CHUNK_MAX) n = CHUNK_MAX;
    if (prefill_alloc(m, n)) return NULL;

    const waste_tensor *emb = waste_find(m, tname("%smodel.embed_tokens.weight", c->prefix));
    for (int t = 0; t < n; t++) {
        float *dst = m->cx + (size_t)t * hid;
        if (emb->data) memcpy(dst, emb->data + (size_t)tokens[t] * hid, (size_t)hid * 4);
        else {
            const int g = emb->group, ng = (hid + g - 1) / g;
            const int8_t *row = emb->q + (size_t)tokens[t] * ng * g;
            const uint16_t *sc = emb->qs + (size_t)tokens[t] * ng;
            for (int k = 0; k < ng; k++) {
                const float sv = f16_to_f32(sc[k]);
                for (int i = 0; i < g && k * g + i < hid; i++)
                    dst[k * g + i] = (float)row[k * g + i] * sv;
            }
        }
    }

    const int ares_on = c->attn_res_block > 0;
    int nb = 0;
    int ps_live = 0;

    for (int L = 0; L < c->n_layers; L++) {
        if (ares_on) {
            memcpy(m->cprefix, m->cx, (size_t)n * hid * sizeof(float));
            ps_live = 1;
            if (nb > 0) {
                const float *nw = waste_find(m, tname("%smodel.layers.%d.self_attention_res_norm.weight", c->prefix, L))->data;
                const float *pw = waste_find(m, tname("%smodel.layers.%d.self_attention_res_proj.weight", c->prefix, L))->data;
                const int stride = (c->n_layers / c->attn_res_block + 2) * hid;
                for (int t = 0; t < n; t++)
                    waste_apply_attn_res(m, m->cblockres + (size_t)t * stride, nb,
                                         m->cprefix + (size_t)t * hid, nw, pw,
                                         m->cx + (size_t)t * hid);
            }
            if (L % c->attn_res_block == 0) {
                const int stride = (c->n_layers / c->attn_res_block + 2) * hid;
                for (int t = 0; t < n; t++)
                    memcpy(m->cblockres + (size_t)t * stride + (size_t)nb * hid,
                           m->cprefix + (size_t)t * hid, (size_t)hid * sizeof(float));
                nb++;
                ps_live = 0;
            }
        }

        const float *iln = waste_find(m, tname("%smodel.layers.%d.input_layernorm.weight", c->prefix, L))->data;
        for (int t = 0; t < n; t++)
            rmsnorm(m->cnorm + (size_t)t * hid, m->cx + (size_t)t * hid, iln, hid, c->eps);

        /* attention: per token, but on the batched norm buffer */
        for (int t = 0; t < n; t++) {
            if (c->kda_layer[L]) kda_layer(m, L, m->cnorm + (size_t)t * hid,
                                           m->cresid + (size_t)t * hid);
            else mla_layer(m, L, m->cnorm + (size_t)t * hid,
                           m->cresid + (size_t)t * hid, pos0 + t);
        }

        if (ares_on) {
            if (ps_live) for (int i = 0; i < n * hid; i++) m->cprefix[i] += m->cresid[i];
            else { memcpy(m->cprefix, m->cresid, (size_t)n * hid * sizeof(float)); ps_live = 1; }
            const float *nw = waste_find(m, tname("%smodel.layers.%d.mlp_res_norm.weight", c->prefix, L))->data;
            const float *pw = waste_find(m, tname("%smodel.layers.%d.mlp_res_proj.weight", c->prefix, L))->data;
            const int stride = (c->n_layers / c->attn_res_block + 2) * hid;
            for (int t = 0; t < n; t++)
                waste_apply_attn_res(m, m->cblockres + (size_t)t * stride, nb,
                                     m->cprefix + (size_t)t * hid, nw, pw,
                                     m->cx + (size_t)t * hid);
        } else {
            for (int i = 0; i < n * hid; i++) m->cx[i] += m->cresid[i];
        }

        const float *pln = waste_find(m, tname("%smodel.layers.%d.post_attention_layernorm.weight", c->prefix, L))->data;
        for (int t = 0; t < n; t++)
            rmsnorm(m->cnorm + (size_t)t * hid, m->cx + (size_t)t * hid, pln, hid, c->eps);

        if (waste_find(m, tname("%smodel.layers.%d.block_sparse_moe.gate.weight", c->prefix, L))) {
            PROF_START(P_ROUTE);
            moe_chunk(m, L, m->cnorm, m->cresid, n);
            PROF_END(P_ROUTE);
        } else {
            const int inter = c->dense_inter;
            float *a = m->cff, *b = a + (size_t)n * inter;
            matmul_t(m, a, waste_find(m, tname("%smodel.layers.%d.mlp.gate_proj.weight", c->prefix, L)), m->cnorm, inter, hid, n);
            matmul_t(m, b, waste_find(m, tname("%smodel.layers.%d.mlp.up_proj.weight", c->prefix, L)), m->cnorm, inter, hid, n);
            for (int i = 0; i < n * inter; i++)
                a[i] = c->act_situ ? waste_situ_pair(a[i], b[i], c->situ_beta, c->situ_linear_beta)
                                   : silu(a[i]) * b[i];
            matmul_t(m, m->cresid, waste_find(m, tname("%smodel.layers.%d.mlp.down_proj.weight", c->prefix, L)), a, hid, inter, n);
        }

        if (ares_on) {
            for (int i = 0; i < n * hid; i++) m->cprefix[i] += m->cresid[i];
            memcpy(m->cx, m->cprefix, (size_t)n * hid * sizeof(float));
        } else {
            for (int i = 0; i < n * hid; i++) m->cx[i] += m->cresid[i];
        }
    }

    /* hand the chunk's block-residual history to the per-token path: decode
     * continues from the last token's row */
    if (ares_on) {
        const int stride = (c->n_layers / c->attn_res_block + 2) * hid;
        memcpy(m->blockres, m->cblockres + (size_t)(n - 1) * stride,
               (size_t)nb * hid * sizeof(float));
    }
    m->n_blockres = nb;
    const float *fnw = waste_find(m, tname("%smodel.norm.weight", c->prefix))->data;
    float *last = m->cnorm;
    rmsnorm(last, m->cx + (size_t)(n - 1) * hid, fnw, hid, c->eps);
    matvec_t(m, m->logits, waste_find(m, tname("%slm_head.weight", c->prefix)), last,
             c->vocab, hid);
    memcpy(m->x, m->cx + (size_t)(n - 1) * hid, (size_t)hid * sizeof(float));
    return m->logits;
}

atic inline int vq_step(const float *v, const float *C, int entries, int dim,
                          float *resid)
{
    int best = 0;
    float bestd = INFINITY;

#if defined(__ARM_NEON) || defined(__aarch64__)
    if (dim == 8) {
        const float32x4_t v0 = vld1q_f32(v), v1 = vld1q_f32(v + 4);
        for (int c = 0; c < entries; c++) {
            const float *e = C + (size_t)c * 8;
            const float32x4_t d0 = vsubq_f32(v0, vld1q_f32(e));
            const float32x4_t d1 = vsubq_f32(v1, vld1q_f32(e + 4));
            const float d = vaddvq_f32(vfmaq_f32(vmulq_f32(d0, d0), d1, d1));
            if (d < bestd) { bestd = d; best = c; }
        }
        const float *e = C + (size_t)best * 8;
        vst1q_f32(resid, vsubq_f32(v0, vld1q_f32(e)));
        vst1q_f32(resid + 4, vsubq_f32(v1, vld1q_f32(e + 4)));
        return best;
    }
#endif
    for (int c = 0; c < entries; c++) {
        const float *e = C + (size_t)c * dim;
        float d = 0;
        for (int j = 0; j < dim; j++) { const float t = v[j] - e[j]; d += t * t; }
        if (d < bestd) { bestd = d; best = c; }
    }
    for (int j = 0; j < dim; j++) resid[j] = v[j] - C[(size_t)best * dim + j];
    return best;
}

atic void vq_range(int b, int e, void *p)
{
    const vq_job *j = (const vq_job *)p;
    float cur[64], nxt[64];
    for (int i = b; i < e; i++) {
        const float *v = j->X + (size_t)i * j->dim;
        for (int d = 0; d < j->dim; d++) cur[d] = v[d];
        for (int s = 0; s < j->stages; s++) {
            const float *C = j->books + (size_t)s * j->entries * j->dim;
            j->out[(size_t)i * j->stages + s] =
                (uint8_t)vq_step(cur, C, j->entries, j->dim, nxt);
            for (int d = 0; d < j->dim; d++) cur[d] = nxt[d];
        }
    }
}

id waste_vq_encode(const float *X, int n, const float *books, int stages,
                     int entries, int dim, uint8_t *out, int nthreads)
{
    waste_pool_init(nthreads);
    vq_job j = { X, books, out, dim, entries, stages };
    waste_parallel_for(n, 4096, vq_range, &j);
}

t waste_vq_lloyd(const float *X, int n, float *C, int entries, int dim,
                   int nthreads)
{
    uint8_t *asg = (uint8_t *)malloc((size_t)n);
    if (!asg) return -1;
    waste_pool_init(nthreads);
    vq_job j = { X, C, asg, dim, entries, 1 };
    waste_parallel_for(n, 4096, vq_range, &j);

    double *sum = (double *)calloc((size_t)entries * dim, sizeof(double));
    long *cnt = (long *)calloc((size_t)entries, sizeof(long));
    if (!sum || !cnt) { free(asg); free(sum); free(cnt); return -1; }
    for (int i = 0; i < n; i++) {
        const int a = asg[i];
        cnt[a]++;
        for (int d = 0; d < dim; d++) sum[(size_t)a * dim + d] += X[(size_t)i * dim + d];
    }
    int live = 0;
    for (int c = 0; c < entries; c++) {
        if (cnt[c]) {
            live++;
            for (int d = 0; d < dim; d++)
                C[(size_t)c * dim + d] = (float)(sum[(size_t)c * dim + d] / (double)cnt[c]);
        }
    }
    free(asg); free(sum); free(cnt);
    return live;
}

float waste_situ_pair(float g, float u, float beta, float lbeta)
/* Log-space decay gate, in place over [H][D].
 *
 * Kimi-Linear:  g = -exp(A_log) * softplus(z)         unbounded below
 * K3:           g = lower_bound * sigmoid(exp(A_log) * z)
 *
 * The second is not a clamp of the first — it is a different function, and
 * it confines the decay exp(g) to (exp(lower_bound), 1).
 */
void waste_kda_decay_gate(float *g, const float *A_log, const float *dt_bias,
                          int H, int D, float lower_bound)
{
    for (int h = 0; h < H; h++) {
        const float ea = expf(A_log[h]);
        for (int j = 0; j < D; j++) {
            const int i = h * D + j;
            const float z = g[i] + (dt_bias ? dt_bias[i] : 0.0f);
            if (lower_bound < 0.0f)
                g[i] = lower_bound / (1.0f + expf(-ea * z));
            else {
                const float sp = z > 20.0f ? z : log1pf(expf(z));
                g[i] = -ea * sp;
            }
        }
    }
}

atic float frand(void)
{
    rng = rng * 6364136223846793005ULL + 1442695040888963407ULL;
    return (float)((double)((rng >> 11) & 0x1FFFFFFFFFFFFFULL) / 9007199254740992.0
                   * 2.0 - 1.0);
}

t main(int argc, char **argv)
{
    const char *out = argc > 1 ? argv[1] : "k3parts.bin";
    FILE *f = fopen(out, "wb");
    if (!f) { perror("open"); return 1; }

    /* ---- 1. SiTU ------------------------------------------------------ */
    {
        const int n = 512;
        const float beta = 4.0f, lbeta = 25.0f;    /* K3's config values */
        float *g = malloc((size_t)n * 4), *u = malloc((size_t)n * 4),
              *o = malloc((size_t)n * 4);
        for (int i = 0; i < n; i++) { g[i] = frand() * 30.0f; u[i] = frand() * 30.0f; }
        for (int i = 0; i < n; i++) o[i] = waste_situ_pair(g[i], u[i], beta, lbeta);
        wi(f, n); wf(f, beta); wf(f, lbeta);
        wr(f, g, n); wr(f, u, n); wr(f, o, n);
        free(g); free(u); free(o);
    }

    /* ---- 2. decay gate, both forms ------------------------------------ */
    {
        const int H = 8, D = 16, n = H * D;
        const float lb = -5.0f;
        float *gin = malloc((size_t)n * 4), *A = malloc((size_t)H * 4),
              *dt = malloc((size_t)n * 4), *g1 = malloc((size_t)n * 4),
              *g2 = malloc((size_t)n * 4);
        for (int i = 0; i < n; i++) { gin[i] = frand() * 4.0f; dt[i] = frand(); }
        for (int i = 0; i < H; i++) A[i] = frand();
        memcpy(g1, gin, (size_t)n * 4);
        waste_kda_decay_gate(g1, A, dt, H, D, lb);          /* K3 form */
        memcpy(g2, gin, (size_t)n * 4);
        waste_kda_decay_gate(g2, A, dt, H, D, 0.0f);        /* Kimi-Linear form */
        wi(f, H); wi(f, D); wf(f, lb);
        wr(f, gin, n); wr(f, A, H); wr(f, dt, n); wr(f, g1, n); wr(f, g2, n);
        free(gin); free(A); free(dt); free(g1); free(g2);
    }

    /* ---- 3. attention residuals --------------------------------------- */
    {
        const int nb = 5, hid = 128;
        const float eps = 1e-5f;
        waste_model m;
        memset(&m, 0, sizeof m);
        m.cfg.hidden = hid;
        m.cfg.eps = eps;
        m.n_blockres = nb;
        m.blockres = malloc((size_t)nb * hid * 4);
        m.att = malloc(4096 * 4);
        float *ps = malloc((size_t)hid * 4), *nw = malloc((size_t)hid * 4),
              *pw = malloc((size_t)hid * 4), *o = malloc((size_t)hid * 4);
        for (int i = 0; i < nb * hid; i++) m.blockres[i] = frand() * 2.0f;
        for (int i = 0; i < hid; i++) { ps[i] = frand() * 2.0f; nw[i] = frand(); pw[i] = frand(); }
        waste_apply_attn_res(&m, ps, nw, pw, o);
        wi(f, nb); wi(f, hid); wf(f, eps);
        wr(f, m.blockres, nb * hid); wr(f, ps, hid);
        wr(f, nw, hid); wr(f, pw, hid); wr(f, o, hid);
        free(m.blockres); free(m.att); free(ps); free(nw); free(pw); free(o);
    }

    fclose(f);
    printf("wrote %s\n", out);
    return 0;
}

atic inline float situ_pair(float g, float u, float beta, float lbeta)
{
    const float a = beta * tanhf(g / beta) / (1.0f + expf(-g));
    return a * (lbeta > 0.0f ? lbeta * tanhf(u / lbeta) : u);
}

atic uint64_t parse_size(const char *s)
{
    char *end;
    double v = strtod(s, &end);
    while (*end == ' ') end++;
    switch (*end) {
    case 'g': case 'G': return (uint64_t)(v * (1ULL << 30));
    case 'm': case 'M': return (uint64_t)(v * (1ULL << 20));
    case 'k': case 'K': return (uint64_t)(v * (1ULL << 10));
    default: return (uint64_t)v;
    }
}

atic void human(uint64_t b, char *out, size_t cap)
{
    const double g = (double)b / (1ULL << 30);
    if (g >= 1.0) snprintf(out, cap, "%.2f GB", g);
    else snprintf(out, cap, "%.0f MB", (double)b / (1ULL << 20));
}

atic void opts_init(opts *o)
{
    memset(o, 0, sizeof *o);
    o->ctx = 4096;
    o->max_tokens = 128;
    o->top_p = 1.0f;
}

atic int parse_opts(int argc, char **argv, int from, opts *o)
{
    for (int i = from; i < argc; i++) {
        if (!strcmp(argv[i], "--budget") && i + 1 < argc) o->budget = parse_size(argv[++i]);
        else if (!strcmp(argv[i], "--ctx") && i + 1 < argc) o->ctx = (uint32_t)atoi(argv[++i]);
        else if (!strcmp(argv[i], "-n") && i + 1 < argc) o->max_tokens = (uint32_t)atoi(argv[++i]);
        else if (!strcmp(argv[i], "--temp") && i + 1 < argc) o->temperature = (float)atof(argv[++i]);
        else if (!strcmp(argv[i], "--top-p") && i + 1 < argc) o->top_p = (float)atof(argv[++i]);
        else if (!strcmp(argv[i], "--top-k") && i + 1 < argc) o->top_k = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--seed") && i + 1 < argc) o->seed = strtoull(argv[++i], NULL, 10);
        else if (!strcmp(argv[i], "--threads") && i + 1 < argc) o->threads = atoi(argv[++i]);
        else if (!strcmp(argv[i], "-q") || !strcmp(argv[i], "--quiet")) o->quiet = 1;
        else if (argv[i][0] == '-') { fprintf(stderr, "unknown option %s\n", argv[i]); return -1; }
    }
    return 0;
}

atic waste_status open_model(const char *path, const opts *o, waste_ctx **ctx)
{
    waste_cfg cfg;
    waste_cfg_init(&cfg);
    cfg.ram_budget_bytes = o->budget;
    cfg.ctx_tokens = o->ctx;
    cfg.n_threads = o->threads;
    return waste_open(path, &cfg, ctx);
}

atic int fail(const char *what, waste_status s)
{
    fprintf(stderr, "%s: %s\n", what, waste_strerror(s));
    if (s == WASTE_E_RAM_BUDGET)
        fprintf(stderr, "  (run `waste plan MODEL` to see the floor)\n");
    return 1;
}

atic int on_token(const waste_token_info *i, const char *piece, void *user)
{
    sink *s = (sink *)user;
    if (!s->quiet) { fputs(piece, stdout); fflush(stdout); }
    s->n++;
    s->hit += i->experts_hit;
    s->miss += i->experts_missed;
    s->ms += i->ms_total;
    return 0;
}

atic int cmd_plan(int argc, char **argv)
{
    if (argc < 3) { fprintf(stderr, "usage: waste plan MODEL [--budget N] [--ctx N]\n"); return 2; }
    opts o; opts_init(&o);
    if (parse_opts(argc, argv, 3, &o)) return 2;

    waste_memplan p;
    const waste_status st = waste_plan_memory(argv[2], o.ctx, &p);
    if (st != WASTE_OK) return fail("plan", st);

    char b[5][32];
    human(p.trunk_bytes, b[0], 32); human(p.state_bytes, b[1], 32);
    human(p.scratch_bytes, b[2], 32); human(p.min_expert_cache, b[3], 32);
    human(p.floor_bytes, b[4], 32);
    printf("memory plan for %s (ctx %u)\n\n", argv[2], o.ctx);
    printf("  resident trunk        %12s\n", b[0]);
    printf("  KDA state + KV cache  %12s\n", b[1]);
    printf("  scratch               %12s\n", b[2]);
    printf("  minimum expert cache  %12s\n", b[3]);
    printf("  ---------------------------------\n");
    printf("  FLOOR                 %12s\n", b[4]);
    human(p.recommended_bytes, b[0], 32);
    printf("  recommended           %12s   (floor + 3x a token's working set;\n"
           "                                      below that the cache keeps\n"
           "                                      nothing alive between tokens)\n", b[0]);
    if (o.budget) {
        char bb[32];
        human(o.budget, bb, 32);
        if (o.budget < p.floor_bytes) printf("\n  budget %s is BELOW the floor — open would fail\n", bb);
        else {
            char cb[32];
            human(o.budget - p.floor_bytes + p.min_expert_cache, cb, 32);
            printf("\n  budget %s -> expert cache %s\n", bb, cb);
        }
    }
    return 0;
}

st

ic int cmd_info(int argc, char **argv)
{
    if (argc < 3) { fprintf(stderr, "usage: waste info MODEL\n"); return 2; }
    opts o; opts_init(&o);
    if (parse_opts(argc, argv, 3, &o)) return 2;
    waste_ctx *c;
    const waste_status st = open_model(argv[2], &o, &c);
    if (st != WASTE_OK) return fail("open", st);

    waste_model_info mi;
    waste_model_get_info(c, &mi);
    waste_memplan used;
    waste_memory_used(c, &used);
    char cb[32];
    human(used.min_expert_cache, cb, 32);
    printf("%s\n\n", waste_build_info());
    printf("  arch          %s\n", mi.arch);
    printf("  layers        %u\n", mi.n_layers);
    printf("  experts       %u (top-%u)\n", mi.n_experts, mi.top_k);
    printf("  hidden        %u\n", mi.hidden);
    printf("  routed params %.1f B total, %.1f B active/token\n",
           mi.params_total / 1e9, mi.params_active / 1e9);
    printf("  quantization  %s\n", mi.quant_summary);
    printf("  expert cache  %s\n", cb);
    waste_close(c);
    return 0;
}

st

ic int run_prompt(waste_ctx *c, const opts *o, const char *prompt, int show_stats)
{
    int32_t ids[MAXTOK];
    size_t n = 0;
    waste_status st = waste_tokenize(c, prompt, 0, ids, MAXTOK, &n);
    if (st != WASTE_OK) return fail("tokenize", st);

    waste_gen_params p;
    waste_gen_params_init(&p);
    p.max_tokens = o->max_tokens;
    p.temperature = o->temperature;
    p.top_p = o->top_p;
    p.top_k = o->top_k;
    p.seed = o->seed;

    sink s = { o->quiet, 0, 0, 0, 0.0 };
    if (!o->quiet) fputs(prompt, stdout);
    st = waste_generate(c, ids, n, &p, on_token, &s);
    printf("\n");
    if (st != WASTE_OK && st != WASTE_E_CANCELLED) return fail("generate", st);

    if (show_stats && s.n) {
        const double sec = s.ms / 1000.0;
        fprintf(stderr, "\n[%u tokens, %.2f s, %.2f tok/s | experts %llu hit / "
                        "%llu miss = %.0f%%]\n",
                s.n, sec, s.n / sec,
                (unsigned long long)s.hit, (unsigned long long)s.miss,
                100.0 * (double)s.hit / (double)(s.hit + s.miss ? s.hit + s.miss : 1));
    }
    return 0;
}

