ic int cmd_run(int argc, char **argv)
{
    if (argc < 4) { fprintf(stderr, "usage: waste run MODEL \"prompt\" [options]\n"); return 2; }
    opts o; opts_init(&o);
    if (parse_opts(argc, argv, 4, &o)) return 2;
    waste_ctx *c;
    const waste_status st = open_model(argv[2], &o, &c);
    if (st != WASTE_OK) return fail("open", st);
    const int r = run_prompt(c, &o, argv[3], !o.quiet);
    waste_close(c);
    return r;
}

st

ic int cmd_chat(int argc, char **argv)
{
    if (argc < 3) { fprintf(stderr, "usage: waste chat MODEL [options]\n"); return 2; }
    opts o; opts_init(&o);
    if (parse_opts(argc, argv, 3, &o)) return 2;
    waste_ctx *c;
    const waste_status st = open_model(argv[2], &o, &c);
    if (st != WASTE_OK) return fail("open", st);

    printf("%s — /reset clears state, /stats prints counters, Ctrl-D exits\n",
           waste_build_info());
    char line[8192];
    while (1) {
        fputs("\n> ", stdout);
        fflush(stdout);
        if (!fgets(line, sizeof line, stdin)) break;
        size_t l = strlen(line);
        while (l && (line[l - 1] == '\n' || line[l - 1] == '\r')) line[--l] = 0;
        if (!l) continue;
        if (!strcmp(line, "/reset")) { waste_state_reset(c); printf("(state cleared)\n"); continue; }
        if (!strcmp(line, "/stats")) {
            waste_stats s;
            waste_get_stats(c, &s);
            printf("%llu tokens, %.2f tok/s, experts %llu hit / %llu miss (%.0f%%), %.2f GB read\n",
                   (unsigned long long)s.tokens_generated,
                   s.sec_total > 0 ? s.tokens_generated / s.sec_total : 0.0,
                   (unsigned long long)s.experts_hit, (unsigned long long)s.experts_missed,
                   100.0 * (double)s.experts_hit /
                       (double)(s.experts_hit + s.experts_missed ? s.experts_hit + s.experts_missed : 1),
                   (double)s.bytes_read / (1ULL << 30));
            continue;
        }
        printf("\n");
        run_prompt(c, &o, line, 0);
    }
    waste_close(c);
    return 0;
}

stat

int cmd_bench(int argc, char **argv)
{
    if (argc < 3) { fprintf(stderr, "usage: waste bench MODEL [-n N] [--budget N]\n"); return 2; }
    opts o; opts_init(&o);
    o.max_tokens = 64;
    if (parse_opts(argc, argv, 3, &o)) return 2;
    waste_ctx *c;
    const waste_status st = open_model(argv[2], &o, &c);
    if (st != WASTE_OK) return fail("open", st);

    waste_memplan used;
    waste_memory_used(c, &used);
    char cb[32];
    human(used.min_expert_cache, cb, 32);
    printf("%s\n  expert cache %s, %u tokens\n\n", waste_build_info(), cb, o.max_tokens);

    opts q = o;
    q.quiet = 1;
    run_prompt(c, &q, "Write a C function that parses a JSON array of integers "
                      "and explain its edge cases.", 0);

    waste_stats s;
    waste_get_stats(c, &s);
    const double tps = s.sec_total > 0 ? s.tokens_generated / s.sec_total : 0;
    const uint64_t acc = s.experts_hit + s.experts_missed;
    printf("  %.2f tok/s (%.0f ms/token)\n", tps, 1000.0 / (tps > 0 ? tps : 1));
    printf("  experts   %llu hit / %llu miss = %.1f%% hit\n",
           (unsigned long long)s.experts_hit, (unsigned long long)s.experts_missed,
           100.0 * (double)s.experts_hit / (double)(acc ? acc : 1));
    printf("  disk      %.2f GB total, %.3f GB/token\n",
           (double)s.bytes_read / (1ULL << 30),
           (double)s.bytes_read / (1ULL << 30) /
               (s.tokens_generated ? s.tokens_generated : 1));
    waste_close(c);
    return 0;
}

int

in(int argc, char **argv)
{
    if (argc < 2 || !strcmp(argv[1], "-h") || !strcmp(argv[1], "--help")) {
        printf("waste %s — run large MoE models from a streaming container\n\n"
               "  waste run    MODEL \"prompt\"   generate\n"
               "  waste chat   MODEL            interactive, state kept\n"
               "  waste bench  MODEL            throughput and cache stats\n"
               "  waste plan   MODEL            memory floor and budget\n"
               "  waste info   MODEL            container details\n"
               "  waste version\n\n"
               "options: --budget 8G  --ctx N  -n N  --temp F  --top-p F\n"
               "         --top-k N  --seed N  --threads N  -q\n",
               waste_version());
        return argc < 2 ? 2 : 0;
    }
    if (!strcmp(argv[1], "version")) {
        printf("%s\n", waste_build_info());
        return 0;
    }
    if (!strcmp(argv[1], "run"))   return cmd_run(argc, argv);
    if (!strcmp(argv[1], "chat"))  return cmd_chat(argc, argv);
    if (!strcmp(argv[1], "bench")) return cmd_bench(argc, argv);
    if (!strcmp(argv[1], "plan"))  return cmd_plan(argc, argv);
    if (!strcmp(argv[1], "info"))  return cmd_info(argc, argv);
    fprintf(stderr, "unknown command '%s' (try --help)\n", argv[1]);
    return 2;
}

atic int b64val(int c)
{
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '+') return 62;
    if (c == '/') return 63;
    return -1;
}

atic int b64decode(const char *s, int len, uint8_t *out)
{
    int n = 0, acc = 0, bits = 0;
    for (int i = 0; i < len; i++) {
        if (s[i] == '=') break;
        const int v = b64val((unsigned char)s[i]);
        if (v < 0) continue;
        acc = (acc << 6) | v;
        bits += 6;
        if (bits >= 8) { bits -= 8; out[n++] = (uint8_t)((acc >> bits) & 0xff); }
    }
    return n;
}

atic uint32_t bhash(const uint8_t *p, int len)
{
    uint32_t h = 2166136261u;
    for (int i = 0; i < len; i++) { h ^= p[i]; h *= 16777619u; }
    return h;
}

atic void tok_index(waste_tok *t, int i)
{
    uint32_t h = bhash(t->by_rank[i].p, t->by_rank[i].len) & (uint32_t)t->hash_mask;
    while (t->hash[h] >= 0) h = (h + 1) & (uint32_t)t->hash_mask;
    t->hash[h] = i;
}

atic int tok_rank(const waste_tok *t, const uint8_t *p, int len)
{
    uint32_t h = bhash(p, len) & (uint32_t)t->hash_mask;
    for (int probe = 0; probe <= t->hash_mask; probe++) {
        const int32_t i = t->hash[h];
        if (i < 0) return -1;
        if (t->by_rank[i].len == len && memcmp(t->by_rank[i].p, p, (size_t)len) == 0)
            return t->by_rank[i].rank;
        h = (h + 1) & (uint32_t)t->hash_mask;
    }
    return -1;
}

ste_tok *waste_tok_open(const char *dir)
{
    char path[512];
    FILE *f = NULL;
    const char *names[] = { "tokenizer.model", "tiktoken.model" };
    for (int i = 0; i < 2 && !f; i++) {
        snprintf(path, sizeof path, "%s/%s", dir, names[i]);
        f = fopen(path, "rb");
    }
    if (!f) return NULL;

    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *raw = (char *)malloc((size_t)sz + 1);
    if (!raw || fread(raw, 1, (size_t)sz, f) != (size_t)sz) { free(raw); fclose(f); return NULL; }
    raw[sz] = 0;
    fclose(f);

    waste_tok *t = (waste_tok *)calloc(1, sizeof *t);
    t->blob = (uint8_t *)malloc((size_t)sz);          /* decoded is smaller */
    t->by_rank = (tok_entry *)malloc(sizeof(tok_entry) * 300000);
    if (!t->blob || !t->by_rank) { free(raw); waste_tok_free(t); return NULL; }

    size_t used = 0;
    char *line = raw, *end = raw + sz;
    while (line < end) {
        char *nl = memchr(line, '\n', (size_t)(end - line));
        if (!nl) nl = end;
        char *sp = memchr(line, ' ', (size_t)(nl - line));
        if (sp) {
            const int nb = b64decode(line, (int)(sp - line), t->blob + used);
            const int rank = atoi(sp + 1);
            t->by_rank[t->n_tokens].p = t->blob + used;
            t->by_rank[t->n_tokens].len = nb;
            t->by_rank[t->n_tokens].rank = rank;
            t->n_tokens++;
            used += (size_t)nb;
        }
        line = nl + 1;
    }
    free(raw);

    int hs = 1;
    while (hs < t->n_tokens * 2) hs <<= 1;
    t->hash_mask = hs - 1;
    t->hash = (int32_t *)malloc((size_t)hs * sizeof(int32_t));
    if (!t->hash) { waste_tok_free(t); return NULL; }
    memset(t->hash, 0xff, (size_t)hs * sizeof(int32_t));
    for (int i = 0; i < t->n_tokens; i++) tok_index(t, i);

    /* Kimi's reserved block starts right after the base vocabulary:
     * [BOS] = base, [EOS] = base+1, <|im_end|> = base+2. */
    t->bos = t->n_tokens;
    t->eos = t->n_tokens + 2;
    return t;
}

id waste_tok_free(waste_tok *t)
{
    if (!t) return;
    free(t->blob); free(t->by_rank); free(t->hash); free(t);
}

atic int utf8_next(const char *s, int len, int *cp)
{
    const unsigned char *u = (const unsigned char *)s;
    if (len <= 0) { *cp = -1; return 0; }
    if (u[0] < 0x80) { *cp = u[0]; return 1; }
    if ((u[0] & 0xe0) == 0xc0 && len >= 2) { *cp = ((u[0] & 0x1f) << 6) | (u[1] & 0x3f); return 2; }
    if ((u[0] & 0xf0) == 0xe0 && len >= 3) {
        *cp = ((u[0] & 0x0f) << 12) | ((u[1] & 0x3f) << 6) | (u[2] & 0x3f); return 3;
    }
    if ((u[0] & 0xf8) == 0xf0 && len >= 4) {
        *cp = ((u[0] & 0x07) << 18) | ((u[1] & 0x3f) << 12) | ((u[2] & 0x3f) << 6) | (u[3] & 0x3f);
        return 4;
    }
    *cp = u[0];
    return 1;
}

atic int is_han(int c)
{
    return (c >= 0x4E00 && c <= 0x9FFF) || (c >= 0x3400 && c <= 0x4DBF) ||
           (c >= 0xF900 && c <= 0xFAFF) || (c >= 0x20000 && c <= 0x2FA1F);
}

tribute__((unused)) static int is_upper(int c)
{
    if (c < 0x80) return c >= 'A' && c <= 'Z';
    return (c >= 0xC0 && c <= 0xDE) || (c >= 0x391 && c <= 0x3A9) ||
           (c >= 0x410 && c <= 0x42F);
}

st

ic int next_piece(const char *s, int len)
{
    int cp, n = utf8_next(s, len, &cp), i;
    if (n == 0) return 0;

    if (is_han(cp)) {                                   /* [\p{Han}]+ */
        i = n;
        while (i < len) { int c2, k = utf8_next(s + i, len - i, &c2);
                          if (!is_han(c2)) break; i += k; }
        return i;
    }

    /* (?i:'s|'t|'re|'ve|'m|'ll|'d) — both letter branches take it */
    #define SUFFIX_AT(i) do { \
        if ((i) < len && s[i] == '\'') { \
            static const char *sfx[] = { "s", "t", "re", "ve", "m", "ll", "d" }; \
            for (size_t q = 0; q < sizeof sfx / sizeof *sfx; q++) { \
                const int sl = (int)strlen(sfx[q]); \
                if ((i) + 1 + sl <= len && \
                    strncasecmp(s + (i) + 1, sfx[q], (size_t)sl) == 0) { \
                    (i) += 1 + sl; break; \
                } \
            } \
        } \
    } while (0)

    /* optional leading non-letter/non-digit, then a letter run */
    if (!is_letter(cp) && !is_digit(cp) && !is_nl(cp)) {
        int c2, k2, j = n;
        k2 = utf8_next(s + j, len - j, &c2);
        if (k2 && is_letter(c2)) {
            i = j;
            while (i < len) { int c3, k = utf8_next(s + i, len - i, &c3);
                              if (!is_letter(c3)) break; i += k; }
            SUFFIX_AT(i);
            return i;
        }
    }
    if (is_letter(cp)) {
        i = n;
        while (i < len) { int c3, k = utf8_next(s + i, len - i, &c3);
                          if (!is_letter(c3)) break; i += k; }
        SUFFIX_AT(i);
        return i;
    }

    if (is_digit(cp)) {                                 /* \p{N}{1,3} */
        i = n;
        int cnt = 1;
        while (i < len && cnt < 3) { int c3, k = utf8_next(s + i, len - i, &c3);
                                     if (!is_digit(c3)) break; i += k; cnt++; }
        return i;
    }

    /* " ?[^\s\p{L}\p{N}]+[\r\n]*" */
    {
        int j = 0;
        if (cp == ' ') {
            int c2, k2 = utf8_next(s + n, len - n, &c2);
            if (k2 && !is_space(c2) && !is_letter(c2) && !is_digit(c2)) j = n;
        }
        int save = j;
        i = j;
        while (i < len) { int c3, k = utf8_next(s + i, len - i, &c3);
                          if (is_space(c3) || is_letter(c3) || is_digit(c3)) break; i += k; }
        if (i > save) {
            while (i < len && is_nl(s[i])) i++;
            return i;
        }
    }

    /* "\s*[\r\n]+" then "\s+(?!\S)" then "\s+" */
    if (is_space(cp)) {
        i = 0;
        int last_nl = -1;
        while (i < len) { int c3, k = utf8_next(s + i, len - i, &c3);
                          if (!is_space(c3)) break;
                          i += k;
                          if (is_nl(c3)) last_nl = i; }
        if (last_nl > 0) return last_nl;
        /* \s+(?!\S): keep all but the last space when more text follows */
        if (i < len && i > 1) return i - 1;
        return i;
    }
    return n;
}

/* -

int encode_piece(const waste_tok *t, const uint8_t *p, int len,
                        int32_t *out, int cap)
{
    if (len == 0) return 0;
    const int r = tok_rank(t, p, len);
    if (r >= 0) { if (cap < 1) return -1; out[0] = r; return 1; }
    if (len > MAXPIECE) len = MAXPIECE;

    int start[MAXPIECE + 1], rank[MAXPIECE + 1], n = 0;
    for (int i = 0; i < len; i++) { start[n] = i; rank[n] = INT32_MAX; n++; }
    start[n] = len; rank[n] = INT32_MAX;

    for (int i = 0; i + 1 < n; i++) {
        const int rr = tok_rank(t, p + start[i], start[i + 2] - start[i]);
        rank[i] = rr < 0 ? INT32_MAX : rr;
    }

    for (;;) {
        int best = -1, bestr = INT32_MAX;
        for (int i = 0; i + 1 < n; i++)
            if (rank[i] < bestr) { bestr = rank[i]; best = i; }
        if (best < 0) break;

        /* merge best with best+1 */
        for (int i = best + 1; i < n; i++) { start[i] = start[i + 1]; rank[i] = rank[i + 1]; }
        n--;
        for (int i = (best > 0 ? best - 1 : 0); i <= best && i + 1 < n; i++) {
            const int rr = tok_rank(t, p + start[i], start[i + 2] - start[i]);
            rank[i] = rr < 0 ? INT32_MAX : rr;
        }
    }

    if (n > cap) return -1;
    for (int i = 0; i < n; i++) {
        const int rr = tok_rank(t, p + start[i], start[i + 1] - start[i]);
        out[i] = rr < 0 ? 0 : rr;
    }
    return n;
}

int

ste_tok_encode(const waste_tok *t, const char *text, int32_t *out, int cap)
{
    int n = 0, pos = 0;
    const int len = (int)strlen(text);
    while (pos < len) {
        const int plen = next_piece(text + pos, len - pos);
        if (plen <= 0) break;
        const int got = encode_piece(t, (const uint8_t *)text + pos, plen,
                                     out + n, cap - n);
        if (got < 0) return -1;
        n += got;
        pos += plen;
    }
    return n;
}

int

ste_tok_decode1(const waste_tok *t, int32_t id, char *buf, int cap)
{
    for (int i = 0; i < t->n_tokens; i++)
        if (t->by_rank[i].rank == id) {
            const int l = t->by_rank[i].len < cap ? t->by_rank[i].len : cap;
            memcpy(buf, t->by_rank[i].p, (size_t)l);
            return l;
        }
    return 0;
}

int

ste_tok_decode(const waste_tok *t, const int32_t *ids, int n,
                     char *buf, int cap)
{
    int w = 0;
    for (int i = 0; i < n && w < cap; i++)
        w += waste_tok_decode1(t, ids[i], buf + w, cap - w);
    return w;
}

nst char *waste_strerror(waste_status s)
{
    switch (s) {
    case WASTE_OK:             return "ok";
    case WASTE_E_IO:           return "I/O error";
    case WASTE_E_FORMAT:       return "malformed container";
    case WASTE_E_RAM_BUDGET:   return "RAM budget below the model's floor";
    case WASTE_E_OOM:          return "out of memory";
    case WASTE_E_ARG:          return "invalid argument";
    case WASTE_E_UNSUPPORTED:  return "unsupported";
    case WASTE_E_CANCELLED:    return "cancelled by callback";
    }
    return "unknown error";
}

id waste_cfg_init(waste_cfg *cfg)
{
    if (!cfg) return;
    memset(cfg, 0, sizeof *cfg);
    cfg->cache_policy = WASTE_CACHE_LFRU;
    cfg->use_direct_io = 1;
    cfg->ctx_tokens = 4096;
}

id waste_gen_params_init(waste_gen_params *p)
{
    if (!p) return;
    memset(p, 0, sizeof *p);
    p->temperature = 0.0f;      /* greedy */
    p->top_p = 1.0f;
    p->max_tokens = 256;
}

atic double nowf(void)
{
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec / 1e9;
}

atic char *slurp_all(const char *path)
{
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *b = (char *)malloc((size_t)n + 1);
    if (!b || fread(b, 1, (size_t)n, f) != (size_t)n) { free(b); fclose(f); return NULL; }
    b[n] = 0;
    fclose(f);
    return b;
}

ste_status waste_plan_memory(const char *model_path, uint32_t ctx_tokens,
                               waste_memplan *out)
{
    if (!model_path || !out) return WASTE_E_ARG;
    char p[512];
    snprintf(p, sizeof p, "%s/manifest.json", model_path);
    char *src = slurp_all(p);
    if (!src) return WASTE_E_IO;
    js_doc d;
    if (js_parse(&d, src) < 0) { free(src); return WASTE_E_FORMAT; }

    memset(out, 0, sizeof *out);

    /* trunk: sum the tensor payloads as they are stored */
    const int trunk = js_get(&d, 0, "trunk");
    for (int i = 0; i < d.tok[trunk].size; i++) {
        const int e = js_at(&d, trunk, i);
        out->trunk_bytes += (uint64_t)js_int(&d, js_get(&d, e, "bytes"), 0);
    }

    const int cfg = js_get(&d, 0, "config");
    const int layers = (int)js_int(&d, js_get(&d, cfg, "num_hidden_layers"), 0);
    const int hidden = (int)js_int(&d, js_get(&d, cfg, "hidden_size"), 0);
    const int nheads = (int)js_int(&d, js_get(&d, cfg, "num_attention_heads"), 0);
    const int kv_lora = (int)js_int(&d, js_get(&d, cfg, "kv_lora_rank"), 0);
    const int qk_rope = (int)js_int(&d, js_get(&d, cfg, "qk_rope_head_dim"), 0);
    const int qk_nope = (int)js_int(&d, js_get(&d, cfg, "qk_nope_head_dim"), 0);
    const int v_head = (int)js_int(&d, js_get(&d, cfg, "v_head_dim"), 0);
    const int lac = js_get(&d, cfg, "linear_attn_config");
    const int kh = (int)js_int(&d, js_get(&d, lac, "num_heads"), 0);
    const int kd = (int)js_int(&d, js_get(&d, lac, "head_dim"), 0);
    const int ck = (int)js_int(&d, js_get(&d, lac, "short_conv_kernel_size"), 4);
    const int kl = js_get(&d, lac, "kda_layers");
    const int n_kda = kl >= 0 ? d.tok[kl].size : 0;
    const int n_mla = layers - n_kda;

    out->state_bytes = (uint64_t)n_kda * kh * kd * kd * 4                /* S */
                     + (uint64_t)n_kda * 3 * (ck - 1) * kh * kd * 4      /* conv */
                     + (uint64_t)n_mla * ctx_tokens * nheads *
                       ((uint64_t)(qk_nope + qk_rope) + v_head) * 4;     /* KV */
    (void)kv_lora;
    out->scratch_bytes = (uint64_t)64 * 1024 * 1024 + (uint64_t)hidden * 64 * 4;

    /* one layer's top-k experts, double buffered */
    const int top_k = (int)js_int(&d, js_get(&d, cfg, "num_experts_per_token"), 8);
    const int lyr = js_get(&d, 0, "layers");
    uint64_t rec = 0;
    if (lyr >= 0 && d.tok[lyr].size > 0) {
        const int first = lyr + 2;   /* first member's value */
        const uint64_t bytes = (uint64_t)js_int(&d, js_get(&d, first, "bytes"), 0);
        const uint64_t n = (uint64_t)js_int(&d, js_get(&d, first, "experts"), 1);
        rec = n ? bytes / n : 0;
    }
    out->min_expert_cache = rec * (uint64_t)top_k * 2;
    out->floor_bytes = out->trunk_bytes + out->state_bytes +
                       out->scratch_bytes + out->min_expert_cache;
    /* A cache below one token's working set keeps nothing alive to the
     * next token (Gate 5), so "recommended" starts at 3x that. */
    out->recommended_bytes = out->floor_bytes +
                             rec * (uint64_t)top_k * (uint64_t)layers * 3;

    js_free(&d);
    free(src);
    return WASTE_OK;
}

ste_status waste_open(const char *model_path, const waste_cfg *cfg_in,
                        waste_ctx **out)
{
    if (!model_path || !out) return WASTE_E_ARG;
    *out = NULL;

    waste_cfg cfg;
    if (cfg_in) cfg = *cfg_in;
    else waste_cfg_init(&cfg);
    if (!cfg.ctx_tokens) cfg.ctx_tokens = 4096;

    waste_ctx *c = (waste_ctx *)calloc(1, sizeof *c);
    if (!c) return WASTE_E_OOM;
    c->cfg = cfg;
    snprintf(c->path, sizeof c->path, "%s", model_path);

    waste_status st = waste_plan_memory(model_path, cfg.ctx_tokens, &c->plan);
    if (st != WASTE_OK) { free(c); return st; }

    uint64_t budget = cfg.ram_budget_bytes;
    if (!budget) budget = c->plan.recommended_bytes;
    if (budget < c->plan.floor_bytes) { free(c); return WASTE_E_RAM_BUDGET; }

    const uint64_t cache_bytes = budget - c->plan.floor_bytes +
                                 c->plan.min_expert_cache;
    if (waste_model_load(&c->m, model_path, (int)cfg.ctx_tokens,
                         (size_t)cache_bytes)) {
        free(c);
        return WASTE_E_IO;
    }
    c->tok = waste_tok_open(model_path);      /* optional */
    *out = c;
    return WASTE_OK;
}

id waste_close(waste_ctx *c)
{
    if (!c) return;
    waste_model_free(&c->m);
    waste_tok_free(c->tok);
    free(c);
}

ste_status waste_memory_used(const waste_ctx *c, waste_memplan *out)
{
    if (!c || !out) return WASTE_E_ARG;
    *out = c->plan;
    out->min_expert_cache = (uint64_t)c->m.cache.n_slots * c->m.cache.rec_bytes;
    return WASTE_OK;
}

ste_status waste_tokenize(waste_ctx *c, const char *text, int add_bos,
                            int32_t *out, size_t cap, size_t *n_out)
{
    if (!c || !text || !out || !n_out) return WASTE_E_ARG;
    if (!c->tok) return WASTE_E_UNSUPPORTED;
    size_t n = 0;
    if (add_bos && cap > 0) out[n++] = (int32_t)waste_tok_bos(c->tok);
    const int got = waste_tok_encode(c->tok, text, out + n, (int)(cap - n));
    if (got < 0) return WASTE_E_ARG;
    *n_out = n + (size_t)got;
    return WASTE_OK;
}

ste_status waste_detokenize(waste_ctx *c, const int32_t *ids, size_t n,
                              char *out, size_t cap, size_t *n_out)
{
    if (!c || !ids || !out || !n_out) return WASTE_E_ARG;
    if (!c->tok) return WASTE_E_UNSUPPORTED;
    const int got = waste_tok_decode(c->tok, ids, (int)n, out, (int)cap - 1);
    out[got < 0 ? 0 : got] = 0;
    *n_out = (size_t)(got < 0 ? 0 : got);
    return WASTE_OK;
}

ste_status waste_eval(waste_ctx *c, const int32_t *tokens, size_t n,
                        const float **logits_out, size_t *vocab_out)
{
    if (!c || !tokens || !n) return WASTE_E_ARG;
    const float *lg = NULL;
    for (size_t i = 0; i < n; i++)
        lg = waste_model_step(&c->m, tokens[i], c->pos++, NULL);
    if (logits_out) *logits_out = lg;
    if (vocab_out) *vocab_out = (size_t)c->m.cfg.vocab;
    return WASTE_OK;
}

atic int sample(const float *logits, int vocab, const waste_gen_params *p,
                  uint64_t *rng)
{
    if (p->temperature <= 0.0f) {
        int best = 0;
        for (int i = 1; i < vocab; i++) if (logits[i] > logits[best]) best = i;
        return best;
    }
    /* top-k / top-p over a temperature-scaled softmax */
    int k = p->top_k > 0 && p->top_k < vocab ? p->top_k : vocab;
    int *idx = (int *)malloc((size_t)vocab * sizeof(int));
    float *pr = (float *)malloc((size_t)vocab * sizeof(float));
    if (!idx || !pr) { free(idx); free(pr); return 0; }
    for (int i = 0; i < vocab; i++) idx[i] = i;

    /* partial selection of the top k */
    for (int i = 0; i < k; i++) {
        int best = i;
        for (int j = i + 1; j < vocab; j++)
            if (logits[idx[j]] > logits[idx[best]]) best = j;
        const int t = idx[i]; idx[i] = idx[best]; idx[best] = t;
    }
    float mx = logits[idx[0]], sum = 0;
    for (int i = 0; i < k; i++) {
        pr[i] = expf((logits[idx[i]] - mx) / p->temperature);
        sum += pr[i];
    }
    float cum = 0;
    int last = k;
    for (int i = 0; i < k; i++) {
        cum += pr[i] / sum;
        if (cum >= p->top_p) { last = i + 1; break; }
    }
    *rng = *rng * 6364136223846793005ULL + 1442695040888963407ULL;
    const float r = (float)((*rng >> 11) * 0x1.0p-53) * cum;
    float acc = 0;
    int pick = idx[0];
    for (int i = 0; i < last; i++) {
        acc += pr[i] / sum;
        if (r <= acc) { pick = idx[i]; break; }
    }
    free(idx); free(pr);
    return pick;
}

ste_status waste_generate(waste_ctx *c, const int32_t *prompt, size_t n,
                            const waste_gen_params *params,
                            waste_token_cb cb, void *user)
{
    if (!c || !prompt || !n) return WASTE_E_ARG;
    waste_gen_params p;
    if (params) p = *params; else waste_gen_params_init(&p);
    uint64_t rng = p.seed ? p.seed : 0x853c49e6748fea9bULL;

    const uint64_t h0 = c->m.cache.hits, m0 = c->m.cache.misses;
    const float *lg = NULL;
    double t0 = nowf();
    for (size_t i = 0; i < n; i++)
        lg = waste_model_step(&c->m, prompt[i], c->pos++, NULL);
    c->stats.sec_total += nowf() - t0;

    char piece[64];
    int cur = sample(lg, c->m.cfg.vocab, &p, &rng);
    for (uint32_t t = 0; t < p.max_tokens; t++) {
        const uint64_t hb = c->m.cache.hits, mb = c->m.cache.misses;
        const uint64_t bb = c->m.cache.bytes_read;
        t0 = nowf();
        lg = waste_model_step(&c->m, cur, c->pos++, NULL);
        const double dt = nowf() - t0;
        c->stats.sec_total += dt;
        c->stats.tokens_generated++;

        int stop = 0;
        for (size_t s = 0; s < p.n_stop; s++) if (p.stop_tokens[s] == cur) stop = 1;
        if (c->tok && cur == waste_tok_eos(c->tok)) stop = 1;

        if (cb) {
            waste_token_info info;
            memset(&info, 0, sizeof info);
            info.token_index = t;
            info.token = cur;
            info.experts_hit = (uint32_t)(c->m.cache.hits - hb);
            info.experts_missed = (uint32_t)(c->m.cache.misses - mb);
            info.bytes_read = c->m.cache.bytes_read - bb;
            info.ms_total = dt * 1000.0;
            int pn = 0;
            if (c->tok) pn = waste_tok_decode1(c->tok, cur, piece, (int)sizeof piece - 1);
            piece[pn] = 0;
            if (cb(&info, piece, user) != 0) return WASTE_E_CANCELLED;
        }
        if (stop) break;
        cur = sample(lg, c->m.cfg.vocab, &p, &rng);
    }
    c->stats.experts_hit += c->m.cache.hits - h0;
    c->stats.experts_missed += c->m.cache.misses - m0;
    c->stats.bytes_read = c->m.cache.bytes_read;
    return WASTE_OK;
}

id waste_state_reset(waste_ctx *c)
{
    if (!c) return;
    c->pos = 0;
    const waste_config *cf = &c->m.cfg;
    for (int L = 0; L < cf->n_layers; L++) {
        if (c->m.S[L])
            memset(c->m.S[L], 0, (size_t)cf->kda_heads * cf->kda_dim * cf->kda_dim * sizeof(float));
        if (c->m.conv[L])
            memset(c->m.conv[L], 0,
                   (size_t)3 * cf->kda_heads * cf->kda_dim * (cf->conv_k - 1) * sizeof(float));
        c->m.n_kv[L] = 0;
    }
}

ste_status waste_state_save(waste_ctx *c, const char *path)
{
    (void)c; (void)path;
    return WASTE_E_UNSUPPORTED;      /* 0.2.0 */
}

ste_status waste_state_load(waste_ctx *c, const char *path)
{
    (void)c; (void)path;
    return WASTE_E_UNSUPPORTED;
}

ste_status waste_model_get_info(const waste_ctx *c, waste_model_info *out)
{
    if (!c || !out) return WASTE_E_ARG;
    const waste_config *cf = &c->m.cfg;
    memset(out, 0, sizeof *out);
    out->n_layers = (uint32_t)cf->n_layers;
    out->n_experts = (uint32_t)cf->n_experts;
    out->top_k = (uint32_t)cf->top_k;
    out->hidden = (uint32_t)cf->hidden;
    out->ctx_max = c->cfg.ctx_tokens;
    const uint64_t pe = 3ULL * cf->hidden * cf->moe_inter;
    out->params_total = pe * (uint64_t)cf->n_experts * (uint64_t)(cf->n_layers - cf->first_dense);
    out->params_active = pe * (uint64_t)cf->top_k * (uint64_t)(cf->n_layers - cf->first_dense);
    out->arch = "kimi-linear";
    out->quant_summary = "experts VQ3R, trunk Q8G/F32";
    return WASTE_OK;
}

ste_status waste_get_stats(const waste_ctx *c, waste_stats *out)
{
    if (!c || !out) return WASTE_E_ARG;
    *out = c->stats;
    out->experts_hit = c->m.cache.hits;
    out->experts_missed = c->m.cache.misses;
    out->bytes_read = c->m.cache.bytes_read;
    return WASTE_OK;
}

t main(int argc, char **argv)
{
    if (argc < 2) { fprintf(stderr, "usage: %s container [text...]\n", argv[0]); return 2; }
    waste_tok *t = waste_tok_open(argv[1]);
    if (!t) { fprintf(stderr, "no tokenizer in %s\n", argv[1]); return 1; }
    if (argc == 2) {
        printf("vocab %d  bos %d  eos %d\n", waste_tok_vocab(t),
               waste_tok_bos(t), waste_tok_eos(t));
        return 0;
    }
    for (int a = 2; a < argc; a++) {
        int32_t ids[4096];
        const int n = waste_tok_encode(t, argv[a], ids, 4096);
        printf("%d", n);
        for (int i = 0; i < n; i++) printf(" %d", ids[i]);
        printf("\n");
    }
    waste_tok_free(t);
    return 0;
}

atic uint32_t ec_hash(int32_t k)
{
    uint32_t x = (uint32_t)k;
    x ^= x >> 16; x *= 0x7feb352du;
    x ^= x >> 15; x *= 0x846ca68bu;
    x ^= x >> 16;
    return x;
}

t waste_ecache_init(waste_ecache *c, size_t budget_bytes, size_t rec_bytes,
                      int policy)
{
    memset(c, 0, sizeof *c);
    c->rec_bytes = rec_bytes;
    c->budget_bytes = budget_bytes;
    c->policy = policy;
    c->rng = 0x9e3779b9u;
    if (!rec_bytes || budget_bytes < rec_bytes) return 0;   /* no cache */

    c->n_slots = (int)(budget_bytes / rec_bytes);
    int hs = 1;
    while (hs < c->n_slots * 2) hs <<= 1;
    c->hash_mask = hs - 1;

    c->slot = (waste_eslot *)calloc((size_t)c->n_slots, sizeof *c->slot);
    c->hash = (int32_t *)malloc((size_t)hs * sizeof *c->hash);
    if (!c->slot || !c->hash) { waste_ecache_free(c); return -1; }
    memset(c->hash, 0xff, (size_t)hs * sizeof *c->hash);   /* all -1 */

    for (int i = 0; i < c->n_slots; i++) {
        c->slot[i].key = -1;
        c->slot[i].data = (uint8_t *)malloc(rec_bytes);
        if (!c->slot[i].data) { waste_ecache_free(c); return -1; }
    }
    return 0;
}

id waste_ecache_free(waste_ecache *c)
{
    if (c->slot) {
        for (int i = 0; i < c->n_slots; i++) free(c->slot[i].data);
        free(c->slot);
    }
    free(c->hash);
    c->slot = NULL; c->hash = NULL; c->n_slots = 0;
}

atic int ec_lookup(waste_ecache *c, int32_t key)
{
    uint32_t h = ec_hash(key) & (uint32_t)c->hash_mask;
    for (int probe = 0; probe <= c->hash_mask; probe++) {
        const int32_t si = c->hash[h];
        if (si < 0) return -1;
        if (c->slot[si].key == key) return si;
        h = (h + 1) & (uint32_t)c->hash_mask;
    }
    return -1;
}

atic void ec_insert(waste_ecache *c, int32_t key, int slot)
{
    uint32_t h = ec_hash(key) & (uint32_t)c->hash_mask;
    while (c->hash[h] >= 0) h = (h + 1) & (uint32_t)c->hash_mask;
    c->hash[h] = slot;
}

atic void ec_rehash(waste_ecache *c)
{
    memset(c->hash, 0xff, ((size_t)c->hash_mask + 1) * sizeof *c->hash);
    for (int i = 0; i < c->n_slots; i++)
        if (c->slot[i].key >= 0) ec_insert(c, c->slot[i].key, i);
}

atic int ec_victim(waste_ecache *c)
{
    /* free slot first */
    for (int i = 0; i < c->n_slots; i++)
        if (c->slot[i].key < 0) return i;

    int best = -1;
    uint32_t best_h = 0;
    uint64_t best_l = 0;
    for (int s = 0; s < EC_SAMPLE; s++) {
        c->rng = c->rng * 1664525u + 1013904223u;
        const int i = (int)(c->rng % (uint32_t)c->n_slots);
        const waste_eslot *sl = &c->slot[i];
        int better;
        if (c->policy == 1)                       /* LRU */
            better = (best < 0) || sl->last < best_l;
        else                                      /* LFRU */
            better = (best < 0) || sl->hits < best_h ||
                     (sl->hits == best_h && sl->last < best_l);
        if (better) { best = i; best_h = sl->hits; best_l = sl->last; }
    }
    return best;
}

nst uint8_t *waste_ecache_get(waste_ecache *c, int layer, int expert,
                                waste_fetch_fn fetch, void *user)
{
    const int32_t key = ec_key(layer, expert);
    c->clock++;

    if (c->n_slots > 0) {
        const int si = ec_lookup(c, key);
        if (si >= 0) {
            c->hits++;
            c->slot[si].hits++;
            c->slot[si].last = c->clock;
            return c->slot[si].data;
        }
    }

    c->misses++;
    c->bytes_read += c->rec_bytes;

    if (c->n_slots == 0) return NULL;      /* caller falls back to its own buf */

    const int vi = ec_victim(c);
    const int had = c->slot[vi].key >= 0;
    if (fetch(user, layer, expert, c->slot[vi].data) != 0) {
        c->slot[vi].key = -1;
        if (had) { c->evictions++; ec_rehash(c); }
        return NULL;
    }
    if (had) { c->evictions++; c->slot[vi].key = key; ec_rehash(c); }
    else { c->slot[vi].key = key; ec_insert(c, key, vi); }
    c->slot[vi].hits = 1;
    c->slot[vi].last = c->clock;
    return c->slot[vi].data;
}

atic const uint8_t *read_expert(waste_model *m, int L, int eid)
{
    if (m->cache.n_slots > 0)
        return waste_ecache_get(&m->cache, L, eid, bank_fetch, m);
    m->cache.misses++;
    m->cache.bytes_read += (size_t)m->bank[L].rec_bytes;
    return bank_fetch(m, L, eid, m->miss_buf) == 0 ? m->miss_buf : NULL;

nst char *waste_build_info(void)
{
    static char buf[192];
    static int done = 0;
    if (!done) {
        waste_backend_init(WASTE_BE_AUTO);
        snprintf(buf, sizeof buf,
                 "WASTE %s (container v%d, backend %s, %s)",
                 WASTE_VERSION_STRING, WASTE_FORMAT_VERSION,
                 waste_backend_name(),
#if defined(__aarch64__)
                 "arm64"
#elif defined(__x86_64__)
                 "x86_64"
#else
                 "generic"
#endif
        );
        done = 1;
    }
    return buf;
}

attribute__((format(printf, 1, 2)))
static const char *tname(const char *fmt, ...)
{
    static char buf[8][160];
    static int turn = 0;
    char *b = buf[turn++ & 7];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(b, 160, fmt, ap);
    va_end(ap);
    return b;
}

atic inline float f16_to_f32(uint16_t h)
{
    const uint32_t sign = (uint32_t)(h >> 15) << 31;
    const uint32_t e = (h >> 10) & 0x1f, mn = h & 0x3ff;
    const uint32_t bits = e ? (sign | ((e + 112u) << 23) | (mn << 13)) : sign;
    float f;
    memcpy(&f, &bits, 4);
    return f;
}

atic inline int32_t idot(const int8_t *a, const int8_t *b, int n)
{
#if defined(__ARM_FEATURE_DOTPROD)
    int32x4_t acc = vdupq_n_s32(0);
    int i = 0;
    for (; i + 16 <= n; i += 16)
        acc = vdotq_s32(acc, vld1q_s8(a + i), vld1q_s8(b + i));
    int32_t s = vaddvq_s32(acc);
    for (; i < n; i++) s += (int32_t)a[i] * b[i];
    return s;
#else
    int32_t s = 0;
    for (int i = 0; i < n; i++) s += (int32_t)a[i] * b[i];
    return s;
#endif
}

ic void mvq_rows_f32(int b, int e, void *p)
{
    mvq_arg *a = (mvq_arg *)p;
    const int ng = a->ng, g = a->group;
    const float *x = (const float *)a->xs;      /* raw activations */
    for (int o = b; o < e; o++) {
        const int8_t *row = a->W + (size_t)o * ng * g;
        const uint16_t *ws = a->ws + (size_t)o * ng;
        float acc = 0;
        for (int k = 0; k < ng; k++) {
            const int8_t *w = row + (size_t)k * g;
            const float *xx = x + (size_t)k * g;
            const int lim = (k * g + g <= a->in) ? g : a->in - k * g;
#if defined(__ARM_NEON) || defined(__aarch64__)
            float32x4_t s0 = vdupq_n_f32(0);
            int i = 0;
            for (; i + 8 <= lim; i += 8) {
                const int16x8_t w16 = vmovl_s8(vld1_s8(w + i));
                s0 = vfmaq_f32(s0, vcvtq_f32_s32(vmovl_s16(vget_low_s16(w16))),
                               vld1q_f32(xx + i));
                s0 = vfmaq_f32(s0, vcvtq_f32_s32(vmovl_s16(vget_high_s16(w16))),
                               vld1q_f32(xx + i + 4));
            }
            float part = vaddvq_f32(s0);
            for (; i < lim; i++) part += (float)w[i] * xx[i];
#else
            float part = 0;
            for (int i = 0; i < lim; i++) part += (float)w[i] * xx[i];
#endif
            acc += f16_to_f32(ws[k]) * part;
        }
        a->y[o] = acc;
    }
}

st

ic void mvq_rows(int b, int e, void *p)
{
    mvq_arg *a = (mvq_arg *)p;
    const int ng = a->ng, g = a->group;
    for (int o = b; o < e; o++) {
        const int8_t *row = a->W + (size_t)o * ng * g;
        const uint16_t *ws = a->ws + (size_t)o * ng;
        float acc = 0;
        for (int k = 0; k < ng; k++)
            acc += f16_to_f32(ws[k]) * a->xs[k] *
                   (float)idot(row + (size_t)k * g, a->xq + (size_t)k * g, g);
        a->y[o] = acc;
    }
}

