static double pnow(void)
{
    struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec / 1e9;
}

static inline float dotf(const float *a, const float *b, int n)
{
    float acc = 0;
    for (int i = 0; i < n; i++) acc += a[i] * b[i];
    return acc;
}

static void mv_rows(int b, int e, void *p)
{
    mv_arg *a = (mv_arg *)p;
    for (int o = b; o < e; o++)
        a->y[o] = dotf(a->W + (size_t)o * a->in, a->x, a->in);
}

static void matvec(float *y, const float *W, const float *x, int out, int in)
{
    mv_arg a = { y, W, x, in };
    waste_parallel_for(out, 64, mv_rows, &a);
    if (prof_on < 0) { const char *e = getenv("WASTE_PROFILE"); prof_on = e && *e != '0'; }
    {
        const char *e = getenv("WASTE_THREADS");
        waste_pool_init(e ? atoi(e) : 0);
    }
    {   /* LUT: [max_nv][stages][entries] */
        const int nmax = (c->hidden > c->moe_inter ? c->hidden : c->moe_inter);
        m->lut = (float *)malloc((size_t)3 * (nmax / 8 + 1) * m->stages
                                 * m->cb_entries * sizeof(float));
    }
    free(m->ff); free(m->e_gate); free(m->e_up); free(m->e_down); free(m->lut);
/* Read one expert record; returns the raw buffer (indices stay packed). */
static const uint8_t *read_expert(waste_model *m, int L, int eid)
    if (fread(buf, 1, (size_t)b->rec_bytes, b->f) != (size_t)b->rec_bytes) return NULL;
    return buf;
}

static inline float f16_to_f32(uint16_t h)
{
    const uint32_t sign = (uint32_t)(h >> 15) << 31;
    const uint32_t e = (h >> 10) & 0x1f, mn = h & 0x3ff;
    const uint32_t bits = e ? (sign | ((e + 112u) << 23) | (mn << 13)) : sign;
    float f;
    memcpy(&f, &bits, 4);
    return f;
}

ic void vq_rows(int b, int e, void *p)
{
    vq_arg *a = (vq_arg *)p;
    const int nv = a->nv, st = a->stages, en = a->entries;
    for (int r = b; r < e; r++) {
        const uint8_t *ix = a->idx + (size_t)r * nv * st;
        const float *lut = a->lut;
        float acc = 0;
        for (int v = 0; v < nv; v++) {
            const float *blk = lut + (size_t)v * st * en;
            for (int s = 0; s < st; s++) acc += blk[s * en + ix[v * st + s]];
        }
        a->y[r] = acc * f16_to_f32(a->scale[r]);
    }
}

st

ic void vq_apply(waste_model *m, float *y, const uint8_t *idx,
                     const uint16_t *scale, int M, int N, const float *lut)
{
    vq_arg a = { y, idx, scale, lut, N / m->vec_dim, m->stages, m->cb_entries };
    waste_parallel_for(M, 32, vq_rows, &a);
}

st

ic void vq_matvec(waste_model *m, float *y, const uint8_t *idx,
                      const uint16_t *scale, const float *x, int M, int N,
                      int cb_base, float *lut)
{
    vq_build_lut(lut, m->codebooks, cb_base, x, N, m->stages, m->cb_entries,
                 m->vec_dim);
    vq_apply(m, y, idx, scale, M, N, lut);
}

atic char *slurp(const char *path, size_t *len)
{
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *b = (char *)malloc((size_t)n + 1);
    if (!b || fread(b, 1, (size_t)n, f) != (size_t)n) { free(b); fclose(f); return NULL; }
    b[n] = 0;
    fclose(f);
    if (len) *len = (size_t)n;
    return b;
}

nst waste_tensor *waste_find(const waste_model *m, const char *name)
{
    for (int i = 0; i < m->n_tensors; i++)
        if (strcmp(m->t[i].name, name) == 0) return &m->t[i];
    return NULL;
}

attribute__((format(printf, 2, 3)))
static const float *T(const waste_model *m, const char *fmt, ...)
{
    char buf[160];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof buf, fmt, ap);
    va_end(ap);
    const waste_tensor *t = waste_find(m, buf);
    return t ? t->data : NULL;
}

atic void rmsnorm(float *o, const float *x, const float *w, int n, float eps)
{
    float s = 0;
    for (int i = 0; i < n; i++) s += x[i] * x[i];
    const float r = 1.0f / sqrtf(s / (float)n + eps);
    for (int i = 0; i < n; i++) o[i] = x[i] * r * w[i];
}

atic void matvec(float *y, const float *W, const float *x, int out, int in)
{
#pragma omp parallel for schedule(static)
    for (int o = 0; o < out; o++) {
        const float *row = W + (size_t)o * in;
        float s = 0;
        for (int i = 0; i < in; i++) s += row[i] * x[i];
        y[o] = s;
    }
}

atic void softmax(float *x, int n)
{
    float mx = x[0];
    for (int i = 1; i < n; i++) if (x[i] > mx) mx = x[i];
    float s = 0;
    for (int i = 0; i < n; i++) { x[i] = expf(x[i] - mx); s += x[i]; }
    for (int i = 0; i < n; i++) x[i] /= s;
}

atic int load_trunk(waste_model *m, const char *dir, const js_doc *d, int trunk)
{
    char path[MAXP];
    snprintf(path, sizeof path, "%s/trunk.bin", dir);
    size_t blen;
    char *blob = slurp(path, &blen);
    if (!blob) return -1;

    m->n_tensors = d->tok[trunk].size;
    m->t = (waste_tensor *)calloc((size_t)m->n_tensors, sizeof *m->t);

    for (int i = 0; i < m->n_tensors; i++) {
        int e = js_at(d, trunk, i);
        waste_tensor *t = &m->t[i];
        js_str(d, js_get(d, e, "name"), t->name, sizeof t->name);
        const int fmt = (int)js_int(d, js_get(d, e, "fmt"), 0);
        const long off = js_int(d, js_get(d, e, "off"), 0);
        int sh = js_get(d, e, "shape");
        t->ndim = d->tok[sh].size;
        t->n = 1;
        for (int k = 0; k < t->ndim && k < 4; k++) {
            t->shape[k] = (int)js_int(d, js_at(d, sh, k), 1);
            t->n *= (size_t)t->shape[k];
        }
        t->data = (float *)malloc(t->n * sizeof(float));
        if (!t->data) { free(blob); return -1; }

        if (fmt == 0) {                                   /* F32 */
            memcpy(t->data, blob + off, t->n * sizeof(float));
        } else {                                          /* Q8G */
            const int g = (int)js_int(d, js_get(d, e, "group"), 128);
            const long soff = js_int(d, js_get(d, e, "scale_off"), 0);
            const int N = t->shape[t->ndim - 1];
            const long rows = (long)(t->n / (size_t)N);
            const int ng = (N + g - 1) / g;
            const int8_t *q = (const int8_t *)(blob + off);
            const uint16_t *sc = (const uint16_t *)(blob + soff);
            for (long r = 0; r < rows; r++) {
                for (int b = 0; b < ng; b++) {
                    /* fp16 -> float without <arm_fp16.h> assumptions */
                    const uint16_t h = sc[r * ng + b];
                    const uint32_t sign = (uint32_t)(h >> 15) << 31;
                    uint32_t exp = (h >> 10) & 0x1f, man = h & 0x3ff, bits;
                    if (exp == 0) { bits = sign; }
                    else { bits = sign | ((exp + 112u) << 23) | (man << 13); }
                    float s;
                    memcpy(&s, &bits, 4);
                    for (int k = 0; k < g; k++) {
                        const int col = b * g + k;
                        if (col >= N) break;
                        t->data[r * N + col] = (float)q[(r * ng + b) * g + k] * s;
                    }
                }
            }
        }
    }
    free(blob);
    return 0;
}

atic void cfg_from_json(waste_config *c, const js_doc *d, int cfg)
{
    c->n_layers = (int)js_int(d, js_get(d, cfg, "num_hidden_layers"), 0);
    c->hidden = (int)js_int(d, js_get(d, cfg, "hidden_size"), 0);
    c->n_experts = (int)js_int(d, js_get(d, cfg, "num_experts"), 0);
    c->top_k = (int)js_int(d, js_get(d, cfg, "num_experts_per_token"), 0);
    c->moe_inter = (int)js_int(d, js_get(d, cfg, "moe_intermediate_size"), 0);
    c->dense_inter = (int)js_int(d, js_get(d, cfg, "intermediate_size"), 0);
    c->n_shared = (int)js_int(d, js_get(d, cfg, "num_shared_experts"), 0);
    c->first_dense = (int)js_int(d, js_get(d, cfg, "first_k_dense_replace"), 0);
    c->vocab = (int)js_int(d, js_get(d, cfg, "vocab_size"), 0);
    c->n_heads = (int)js_int(d, js_get(d, cfg, "num_attention_heads"), 0);
    c->kv_lora = (int)js_int(d, js_get(d, cfg, "kv_lora_rank"), 0);
    c->qk_nope = (int)js_int(d, js_get(d, cfg, "qk_nope_head_dim"), 0);
    c->qk_rope = (int)js_int(d, js_get(d, cfg, "qk_rope_head_dim"), 0);
    c->v_head = (int)js_int(d, js_get(d, cfg, "v_head_dim"), 0);
    c->eps = (float)js_num(d, js_get(d, cfg, "rms_norm_eps"), 1e-5);
    c->routed_scale = (float)js_num(d, js_get(d, cfg, "routed_scaling_factor"), 1.0);
    c->renorm = js_get(d, cfg, "moe_renormalize") >= 0;

    int lac = js_get(d, cfg, "linear_attn_config");
    c->kda_heads = (int)js_int(d, js_get(d, lac, "num_heads"), 0);
    c->kda_dim = (int)js_int(d, js_get(d, lac, "head_dim"), 0);
    c->conv_k = (int)js_int(d, js_get(d, lac, "short_conv_kernel_size"), 4);
    memset(c->kda_layer, 0, sizeof c->kda_layer);
    int kl = js_get(d, lac, "kda_layers");
    for (int i = 0; i < d->tok[kl].size; i++) {
        int v = (int)js_int(d, js_at(d, kl, i), -1) - 1;   /* list is 1-based */
        if (v >= 0 && v < 128) c->kda_layer[v] = 1;
    }
}

t waste_model_load(waste_model *m, const char *dir, int kv_cap)
{
    memset(m, 0, sizeof *m);
    m->kv_cap = kv_cap;
    waste_backend_init(WASTE_BE_AUTO);

    char path[MAXP];
    snprintf(path, sizeof path, "%s/manifest.json", dir);
    char *src = slurp(path, NULL);
    if (!src) return -1;
    js_doc d;
    if (js_parse(&d, src) < 0) { free(src); return -1; }

    cfg_from_json(&m->cfg, &d, js_get(&d, 0, "config"));
    const waste_config *c = &m->cfg;

    int eq = js_get(&d, 0, "expert_quant");
    m->stages = (int)js_int(&d, js_get(&d, eq, "stages"), 3);
    m->vec_dim = (int)js_int(&d, js_get(&d, eq, "vec_dim"), 8);
    m->cb_entries = (int)js_int(&d, js_get(&d, eq, "entries"), 256);

    if (load_trunk(m, dir, &d, js_get(&d, 0, "trunk")) < 0) { js_free(&d); free(src); return -1; }

    /* codebooks */
    snprintf(path, sizeof path, "%s/codebooks.bin", dir);
    size_t cblen;
    char *cb = slurp(path, &cblen);
    if (!cb) { js_free(&d); free(src); return -1; }
    const size_t rec = 16 + (size_t)m->cb_entries * m->vec_dim * 2;
    m->n_books = (int)(cblen / rec);
    m->codebooks = (float *)malloc((size_t)m->n_books * m->cb_entries * m->vec_dim * sizeof(float));
    for (int b = 0; b < m->n_books; b++) {
        const uint16_t *h = (const uint16_t *)(cb + b * rec + 16);
        for (int i = 0; i < m->cb_entries * m->vec_dim; i++) {
            const uint16_t v = h[i];
            const uint32_t sign = (uint32_t)(v >> 15) << 31;
            uint32_t exp = (v >> 10) & 0x1f, man = v & 0x3ff, bits;
            bits = exp ? (sign | ((exp + 112u) << 23) | (man << 13)) : sign;
            memcpy(&m->codebooks[(size_t)b * m->cb_entries * m->vec_dim + i], &bits, 4);
        }
    }
    free(cb);

    /* expert banks */
    m->expert_m[0] = m->expert_m[1] = c->moe_inter; m->expert_n[0] = m->expert_n[1] = c->hidden;
    m->expert_m[2] = c->hidden; m->expert_n[2] = c->moe_inter;
    int layers = js_get(&d, 0, "layers");
    for (int L = 0; L < c->n_layers; L++) {
        char key[16];
        snprintf(key, sizeof key, "%d", L);
        int e = js_get(&d, layers, key);
        if (e < 0) continue;
        char fn[64];
        js_str(&d, js_get(&d, e, "file"), fn, sizeof fn);
        snprintf(path, sizeof path, "%s/%s", dir, fn);
        m->bank[L].f = fopen(path, "rb");
        m->bank[L].n_experts = (int)js_int(&d, js_get(&d, e, "experts"), 0);
        m->bank[L].cb_base = (int)js_int(&d, js_get(&d, e, "codebook_base"), 0);
        const long bytes = js_int(&d, js_get(&d, e, "bytes"), 0);
        m->bank[L].rec_bytes = m->bank[L].n_experts ? bytes / m->bank[L].n_experts : 0;
    }
    js_free(&d);
    free(src);

    /* state + scratch */
    const int H = c->kda_heads, D = c->kda_dim, C = H * D;
    for (int L = 0; L < c->n_layers; L++) {
        if (c->kda_layer[L]) {
            m->S[L] = (float *)calloc((size_t)H * D * D, sizeof(float));
            m->conv[L] = (float *)calloc((size_t)3 * C * (c->conv_k - 1), sizeof(float));
        } else {
            const int kd = c->qk_nope + c->qk_rope;
            m->kcache[L] = (float *)calloc((size_t)kv_cap * c->n_heads * kd, sizeof(float));
            m->vcache[L] = (float *)calloc((size_t)kv_cap * c->n_heads * c->v_head, sizeof(float));
        }
    }
    const int big = c->hidden > C ? c->hidden : C;
    m->x = (float *)calloc((size_t)c->hidden, sizeof(float));
    m->h = (float *)calloc((size_t)c->hidden, sizeof(float));
    m->tmp = (float *)calloc((size_t)8 * big + 8 * c->moe_inter + 8 * c->dense_inter, sizeof(float));
    m->att = (float *)calloc((size_t)kv_cap * c->n_heads + 1024, sizeof(float));
    m->logits = (float *)calloc((size_t)c->vocab, sizeof(float));
    m->ff = (float *)calloc((size_t)2 * (c->dense_inter > c->moe_inter ? c->dense_inter : c->moe_inter), sizeof(float));
    m->e_gate = (float *)malloc((size_t)c->moe_inter * c->hidden * sizeof(float));
    m->e_up = (float *)malloc((size_t)c->moe_inter * c->hidden * sizeof(float));
    m->e_down = (float *)malloc((size_t)c->hidden * c->moe_inter * sizeof(float));
    return (m->x && m->logits && m->e_gate && m->e_up && m->e_down) ? 0 : -1;
}

id waste_model_free(waste_model *m)
{
    for (int i = 0; i < m->n_tensors; i++) free(m->t[i].data);
    free(m->t);
    free(m->codebooks);
    for (int L = 0; L < 128; L++) {
        free(m->S[L]); free(m->conv[L]); free(m->kcache[L]); free(m->vcache[L]);
        if (m->bank[L].f) fclose(m->bank[L].f);
    }
    free(m->x); free(m->h); free(m->tmp); free(m->att); free(m->logits);
    free(m->ff); free(m->e_gate); free(m->e_up); free(m->e_down);
}

atic void dequant_expert(waste_model *m, int L, int eid)
{
    waste_bank *b = &m->bank[L];
    static uint8_t *buf = NULL;
    static size_t bufsz = 0;
    if (bufsz < (size_t)b->rec_bytes) {
        free(buf);
        buf = (uint8_t *)malloc((size_t)b->rec_bytes);
        bufsz = (size_t)b->rec_bytes;
    }
    fseek(b->f, (long)eid * b->rec_bytes, SEEK_SET);
    if (fread(buf, 1, (size_t)b->rec_bytes, b->f) != (size_t)b->rec_bytes) return;
    m->expert_reads++;

    const waste_expert_hdr *h = (const waste_expert_hdr *)buf;
    const uint32_t off[3] = { h->gate_off, h->up_off, h->down_off };
    float *dst[3] = { m->e_gate, m->e_up, m->e_down };
    size_t sc_cur = h->chan_corr_off;

    for (int k = 0; k < 3; k++) {
        const int M = m->expert_m[k], N = m->expert_n[k];
        const long nvec = (long)M * N / m->vec_dim;
        const uint8_t *idx = buf + off[k];
        const uint16_t *sc = (const uint16_t *)(buf + sc_cur);
        sc_cur += (size_t)M * 2;
        for (long v = 0; v < nvec; v++) {
            float acc[16] = {0};
            for (int s = 0; s < m->stages; s++) {
                const int book = h->codebook_id + k * m->stages + s;
                const float *C = m->codebooks +
                    ((size_t)book * m->cb_entries + idx[v * m->stages + s]) * m->vec_dim;
                for (int j = 0; j < m->vec_dim; j++) acc[j] += C[j];
            }
            const long base = v * m->vec_dim;
            const int row = (int)(base / N);
            const uint16_t hs = sc[row];
            const uint32_t sign = (uint32_t)(hs >> 15) << 31;
            uint32_t e = (hs >> 10) & 0x1f, mn = hs & 0x3ff, bits;
            bits = e ? (sign | ((e + 112u) << 23) | (mn << 13)) : sign;
            float s;
            memcpy(&s, &bits, 4);
            for (int j = 0; j < m->vec_dim; j++) dst[k][base + j] = acc[j] * s;
        }
    }
}

atic void kda_layer(waste_model *m, int L, const float *in, float *out)
{
    const waste_config *c = &m->cfg;
    const int H = c->kda_heads, D = c->kda_dim, C = H * D, hid = c->hidden;
    float *q = m->tmp, *k = q + C, *v = k + C, *g = v + C, *o = g + C;
    float *beta = o + C, *lo = beta + H, *gate = lo + C;

    const char *nm[3] = { "q", "k", "v" };
    float *dstv[3] = { q, k, v };
    for (int i = 0; i < 3; i++) {
        char b[128];
        snprintf(b, sizeof b, "model.layers.%d.self_attn.%s_proj.weight", L, nm[i]);
        matvec(dstv[i], waste_find(m, b)->data, in, C, hid);
        snprintf(b, sizeof b, "model.layers.%d.self_attn.%s_conv1d.weight", L, nm[i]);
        waste_k.short_conv_step(C, c->conv_k, waste_find(m, b)->data, NULL,
                                m->conv[L] + (size_t)i * C * (c->conv_k - 1),
                                dstv[i], dstv[i]);
    }

    matvec(lo, T(m, "model.layers.%d.self_attn.f_a_proj.weight", L), in, D, hid);
    matvec(g, T(m, "model.layers.%d.self_attn.f_b_proj.weight", L), lo, C, D);
    const float *A_log = T(m, "model.layers.%d.self_attn.A_log", L);
    const float *dt = T(m, "model.layers.%d.self_attn.dt_bias", L);
    for (int h = 0; h < H; h++) {
        const float a = -expf(A_log[h]);
        for (int j = 0; j < D; j++) {
            const int i = h * D + j;
            const float z = g[i] + dt[i];
            /* softplus, numerically safe */
            const float sp = z > 20.0f ? z : log1pf(expf(z));
            g[i] = a * sp;
        }
    }
    matvec(beta, T(m, "model.layers.%d.self_attn.b_proj.weight", L), in, H, hid);
    for (int h = 0; h < H; h++) beta[h] = 1.0f / (1.0f + expf(-beta[h]));

    waste_k.kda_step(H, D, D, q, k, v, g, beta, m->S[L], o, m->att);

    matvec(lo, T(m, "model.layers.%d.self_attn.g_a_proj.weight", L), in, D, hid);
    matvec(gate, T(m, "model.layers.%d.self_attn.g_b_proj.weight", L), lo, C, D);
    const float *onw = T(m, "model.layers.%d.self_attn.o_norm.weight", L);
    for (int h = 0; h < H; h++)
        waste_k.rmsnorm_gated(D, o + h * D, gate + h * D, onw, c->eps, o + h * D);

    matvec(out, T(m, "model.layers.%d.self_attn.o_proj.weight", L), o, hid, C);
}

atic void mla_layer(waste_model *m, int L, const float *in, float *out, int pos)
{
    const waste_config *c = &m->cfg;
    const int nh = c->n_heads, qd = c->qk_nope + c->qk_rope, vh = c->v_head;
    const int hid = c->hidden;
    float *q = m->tmp, *ckv = q + nh * qd, *kb = ckv + c->kv_lora + c->qk_rope;
    float *o = kb + nh * (c->qk_nope + vh);

    matvec(q, T(m, "model.layers.%d.self_attn.q_proj.weight", L), in, nh * qd, hid);
    matvec(ckv, T(m, "model.layers.%d.self_attn.kv_a_proj_with_mqa.weight", L), in,
           c->kv_lora + c->qk_rope, hid);
    float *kpass = ckv, *krot = ckv + c->kv_lora;
    rmsnorm(kpass, kpass, T(m, "model.layers.%d.self_attn.kv_a_layernorm.weight", L),
            c->kv_lora, c->eps);
    matvec(kb, T(m, "model.layers.%d.self_attn.kv_b_proj.weight", L), kpass,
           nh * (c->qk_nope + vh), c->kv_lora);

    float *kc = m->kcache[L] + (size_t)pos * nh * qd;
    float *vc = m->vcache[L] + (size_t)pos * nh * vh;
    for (int h = 0; h < nh; h++) {
        const float *src = kb + h * (c->qk_nope + vh);
        memcpy(kc + h * qd, src, (size_t)c->qk_nope * sizeof(float));
        memcpy(kc + h * qd + c->qk_nope, krot, (size_t)c->qk_rope * sizeof(float));
        memcpy(vc + h * vh, src + c->qk_nope, (size_t)vh * sizeof(float));
    }
    m->n_kv[L] = pos + 1;

    const float scale = 1.0f / sqrtf((float)qd);
    const int S = m->n_kv[L];
    for (int h = 0; h < nh; h++) {
        float *a = m->att;
        for (int s = 0; s < S; s++) {
            const float *kk = m->kcache[L] + ((size_t)s * nh + h) * qd;
            float acc = 0;
            for (int i = 0; i < qd; i++) acc += q[h * qd + i] * kk[i];
            a[s] = acc * scale;
        }
        softmax(a, S);
        float *oh = o + h * vh;
        memset(oh, 0, (size_t)vh * sizeof(float));
        for (int s = 0; s < S; s++) {
            const float *vv = m->vcache[L] + ((size_t)s * nh + h) * vh;
            const float w = a[s];
            for (int i = 0; i < vh; i++) oh[i] += w * vv[i];
        }
    }
    matvec(out, T(m, "model.layers.%d.self_attn.o_proj.weight", L), o, hid, nh * vh);
}

atic void ffn(waste_model *m, const float *W1, const float *W3, const float *W2,
                const float *in, float *out, int inter, int hid, float w, int accum)
{
    float *a = m->ff, *b = a + inter;
    matvec(a, W1, in, inter, hid);
    matvec(b, W3, in, inter, hid);
    for (int i = 0; i < inter; i++) a[i] = silu(a[i]) * b[i];
    float *dst = accum ? m->h : out;
    matvec(dst, W2, a, hid, inter);
    if (accum) for (int i = 0; i < hid; i++) out[i] += w * dst[i];
}

atic void moe_layer(waste_model *m, int L, const float *in, float *out, int *routed)
{
    const waste_config *c = &m->cfg;
    const int E = c->n_experts, K = c->top_k, hid = c->hidden;
    float *sc = m->att + 4096;
    matvec(sc, T(m, "model.layers.%d.block_sparse_moe.gate.weight", L), in, E, hid);
    const float *bias = T(m, "model.layers.%d.block_sparse_moe.gate.e_score_correction_bias", L);
    float *score = sc + E;
    for (int e = 0; e < E; e++) score[e] = 1.0f / (1.0f + expf(-sc[e]));

    int idx[64];
    float w[64];
    for (int j = 0; j < K; j++) {
        int best = -1;
        float bv = -1e30f;
        for (int e = 0; e < E; e++) {
            int taken = 0;
            for (int p = 0; p < j; p++) if (idx[p] == e) { taken = 1; break; }
            if (taken) continue;
            const float v = score[e] + (bias ? bias[e] : 0.0f);
            if (v > bv) { bv = v; best = e; }
        }
        idx[j] = best;
        w[j] = score[best];
    }
    if (c->renorm && K > 1) {
        float s = 0;
        for (int j = 0; j < K; j++) s += w[j];
        for (int j = 0; j < K; j++) w[j] /= (s + 1e-20f);
    }
    for (int j = 0; j < K; j++) w[j] *= c->routed_scale;
    if (routed) for (int j = 0; j < K; j++) routed[j] = idx[j];

    memset(out, 0, (size_t)hid * sizeof(float));
    for (int j = 0; j < K; j++) {
        dequant_expert(m, L, idx[j]);
        ffn(m, m->e_gate, m->e_up, m->e_down, in, out, c->moe_inter, hid, w[j], 1);
    }
    /* shared expert */
    float *tmp = m->h;
    ffn(m, T(m, "model.layers.%d.block_sparse_moe.shared_experts.gate_proj.weight", L),
        T(m, "model.layers.%d.block_sparse_moe.shared_experts.up_proj.weight", L),
        T(m, "model.layers.%d.block_sparse_moe.shared_experts.down_proj.weight", L),
        in, tmp, c->moe_inter * (c->n_shared ? c->n_shared : 1), hid, 1.0f, 0);
    for (int i = 0; i < hid; i++) out[i] += tmp[i];
}

nst float *waste_model_step(waste_model *m, int token, int pos, int *routed)
{
    const waste_config *c = &m->cfg;
    const int hid = c->hidden;
    const float *emb = waste_find(m, "model.embed_tokens.weight")->data;
    memcpy(m->x, emb + (size_t)token * hid, (size_t)hid * sizeof(float));

    float *resid = (float *)malloc((size_t)hid * sizeof(float));
    float *norm = (float *)malloc((size_t)hid * sizeof(float));
    for (int L = 0; L < c->n_layers; L++) {
        char b[128];
        snprintf(b, sizeof b, "model.layers.%d.input_layernorm.weight", L);
        rmsnorm(norm, m->x, waste_find(m, b)->data, hid, c->eps);
        if (c->kda_layer[L]) kda_layer(m, L, norm, resid);
        else mla_layer(m, L, norm, resid, pos);
        for (int i = 0; i < hid; i++) m->x[i] += resid[i];

        snprintf(b, sizeof b, "model.layers.%d.post_attention_layernorm.weight", L);
        rmsnorm(norm, m->x, waste_find(m, b)->data, hid, c->eps);
        snprintf(b, sizeof b, "model.layers.%d.block_sparse_moe.gate.weight", L);
        if (waste_find(m, b))
            moe_layer(m, L, norm, resid, routed ? routed + (size_t)L * c->top_k : NULL);
        else
            ffn(m, T(m, "model.layers.%d.mlp.gate_proj.weight", L),
                T(m, "model.layers.%d.mlp.up_proj.weight", L),
                T(m, "model.layers.%d.mlp.down_proj.weight", L),
                norm, resid, c->dense_inter, hid, 1.0f, 0);
        for (int i = 0; i < hid; i++) m->x[i] += resid[i];
    }
    rmsnorm(norm, m->x, waste_find(m, "model.norm.weight")->data, hid, c->eps);
    matvec(m->logits, waste_find(m, "lm_head.weight")->data, norm, c->vocab, hid);
    free(resid);
    free(norm);
    return m->logits;
}

atic double now(void)
{
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec / 1e9;
}

t main(int argc, char **argv)
{
    if (argc < 3) {
        fprintf(stderr, "usage: %s container ids[,..] [out.bin] [n_gen]\n", argv[0]);
        return 2;
    }
    const char *dir = argv[1];
    int ids[512], n = 0;
    for (char *p = strtok(argv[2], ","); p && n < 512; p = strtok(NULL, ","))
        ids[n++] = atoi(p);
    const char *out = argc > 3 ? argv[3] : NULL;
    const int n_gen = argc > 4 ? atoi(argv[4]) : 0;

    waste_model m;
    double t0 = now();
    if (waste_model_load(&m, dir, 4096)) { fprintf(stderr, "load failed\n"); return 1; }
    printf("loaded in %.1fs — backend %s, %d layers, %d experts, top-%d, vocab %d\n",
           now() - t0, waste_backend_name(), m.cfg.n_layers, m.cfg.n_experts,
           m.cfg.top_k, m.cfg.vocab);

    const float *lg = NULL;
    t0 = now();
    for (int i = 0; i < n; i++) lg = waste_model_step(&m, ids[i], i, NULL);
    const double tp = now() - t0;

    int best = 0;
    for (int v = 1; v < m.cfg.vocab; v++) if (lg[v] > lg[best]) best = v;
    printf("prefill %d tok in %.2fs (%.2f tok/s); argmax %d, max %.4f\n",
           n, tp, n / tp, best, lg[best]);

    if (out) {
        FILE *f = fopen(out, "wb");
        fwrite(lg, sizeof(float), (size_t)m.cfg.vocab, f);
        fclose(f);
        printf("wrote %s\n", out);
    }

    int cur = best;
    for (int i = 0; i < n_gen; i++) {
        t0 = now();
        lg = waste_model_step(&m, cur, n + i, NULL);
        best = 0;
        for (int v = 1; v < m.cfg.vocab; v++) if (lg[v] > lg[best]) best = v;
        printf("  [%3d] %6d  (%.2fs, %llu expert reads)\n", i, best, now() - t0,
               (unsigned long long)m.expert_reads);
        cur = best;
    }

    waste_model_free(&m);
    return 0;
}

in(int argc, char **argv)
{
    if (argc < 2) { fprintf(stderr, "usage: %s experts-LN.bin [n]\n", argv[0]); return 2; }
    const int want = argc > 2 ? atoi(argv[2]) : 4;

    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) { perror("open"); return 1; }
#ifdef __APPLE__
    fcntl(fd, F_NOCACHE, 1);            /* the engine's real read path */
#endif
    struct stat st;
    if (fstat(fd, &st)) { perror("fstat"); return 1; }

    printf("file %s (%.1f MB)\n", argv[1], st.st_size / 1048576.0);
    printf("sizeof(waste_expert_hdr) = %zu\n\n", sizeof(waste_expert_hdr));

    off_t off = 0;
    int n = 0, bad = 0;
    while (off < st.st_size && n < want) {
        waste_expert_hdr h;
        if (pread(fd, &h, sizeof h, off) != (ssize_t)sizeof h) { perror("pread"); return 1; }

        if (h.magic != WASTE_MAGIC_EXPERT) {
            printf("record %d at %lld: BAD MAGIC %08x\n", n, (long long)off, h.magic);
            bad++; break;
        }
        if (off % WASTE_ALIGN) { printf("  not 4 KiB aligned!\n"); bad++; }
        if (h.lowrank_id != 0) { printf("  lowrank_id != 0 (v0 violation)\n"); bad++; }
        if (h.fmt != WQ_VQ3R && h.fmt != WQ_VQ2R) { printf("  unexpected fmt %u\n", h.fmt); bad++; }

        /* the whole expert in ONE read — the point of the layout */
        const size_t bytes = (size_t)h.rec_4k_blocks * WASTE_ALIGN;
        void *buf = NULL;
        if (posix_memalign(&buf, WASTE_ALIGN, bytes)) { fprintf(stderr, "oom\n"); return 1; }
        if (pread(fd, buf, bytes, off) != (ssize_t)bytes) { perror("pread rec"); return 1; }

        printf("record %d: layer %u expert %-3u fmt %u cb %u  %u blocks (%.2f MB)\n",
               n, h.layer, h.expert_id, h.fmt, h.codebook_id, h.rec_4k_blocks,
               bytes / 1048576.0);
        printf("          gate@%u up@%u down@%u corr@%u  crc %08x\n",
               h.gate_off, h.up_off, h.down_off, h.chan_corr_off, h.crc32);

        if (!(h.gate_off < h.up_off && h.up_off < h.down_off &&
              h.down_off < h.chan_corr_off && h.chan_corr_off < bytes)) {
            printf("          OFFSETS OUT OF ORDER/RANGE\n"); bad++;
        }
        free(buf);
        off += (off_t)bytes;
        n++;
    }
    close(fd);
    printf("\n%d records read, %d problems\n", n, bad);
    return bad ? 1 : 0;
}

atic void run_cpuid(unsigned leaf, unsigned sub, unsigned r[4])
{
  #if defined(_MSC_VER)
    int i[4]; __cpuidex(i, (int)leaf, (int)sub);
    r[0] = i[0]; r[1] = i[1]; r[2] = i[2]; r[3] = i[3];
  #else
    __cpuid_count(leaf, sub, r[0], r[1], r[2], r[3]);
  #endif
}

atic uint64_t run_xgetbv(unsigned idx)
{
  #if defined(_MSC_VER)
    return _xgetbv(idx);
  #else
    unsigned lo, hi;
    __asm__ volatile(".byte 0x0f,0x01,0xd0" : "=a"(lo), "=d"(hi) : "c"(idx));
    return ((uint64_t)hi << 32) | lo;
  #endif
}
#

atic int sysctl_flag(const char *name)
{
    int v = 0; size_t sz = sizeof(v);
    return sysctlbyname(name, &v, &sz, NULL, 0) == 0 && v != 0;
}
#

nt32_t waste_cpu_features(void)
{
    static uint32_t cached = 0;
    static int done = 0;
    if (done) return cached;

    uint32_t f = 0;

#if WASTE_X86
    unsigned r[4];
    run_cpuid(0, 0, r);
    const unsigned maxleaf = r[0];
    if (maxleaf >= 1) {
        run_cpuid(1, 0, r);
        if (r[3] & (1u << 26)) f |= WASTE_CPU_SSE2;
        const int osxsave = (r[2] & (1u << 27)) != 0;
        const int fma     = (r[2] & (1u << 12)) != 0;
        /* AVX state must be enabled by the OS, not just present in silicon */
        const uint64_t xcr0 = osxsave ? run_xgetbv(0) : 0;
        const int ymm_ok = osxsave && ((xcr0 & 0x6) == 0x6);
        const int zmm_ok = ymm_ok && ((xcr0 & 0xE0) == 0xE0);
        if (fma && ymm_ok) f |= WASTE_CPU_FMA;
        if (maxleaf >= 7) {
            run_cpuid(7, 0, r);
            if (ymm_ok && (r[1] & (1u << 5)))  f |= WASTE_CPU_AVX2;
            if (zmm_ok && (r[1] & (1u << 16))) f |= WASTE_CPU_AVX512F;
            if (zmm_ok && (r[1] & (1u << 30))) f |= WASTE_CPU_AVX512BW;
            run_cpuid(7, 1, r);
            if (ymm_ok && (r[0] & (1u << 4)))  f |= WASTE_CPU_AVX_VNNI;
        }
    }
#elif defined(__aarch64__)
    f |= WASTE_CPU_NEON;              /* mandatory on aarch64 */
  #if defined(__APPLE__)
    if (sysctl_flag("hw.optional.arm.FEAT_DotProd")) f |= WASTE_CPU_DOTPROD;
    if (sysctl_flag("hw.optional.arm.FEAT_I8MM"))    f |= WASTE_CPU_I8MM;
  #elif defined(__linux__)
    {
        unsigned long hw = getauxval(AT_HWCAP);
    #ifdef HWCAP_ASIMDDP
        if (hw & HWCAP_ASIMDDP) f |= WASTE_CPU_DOTPROD;
    #endif
    #ifdef HWCAP_SVE
        if (hw & HWCAP_SVE) f |= WASTE_CPU_SVE;
    #endif
    #ifdef AT_HWCAP2
        {
            unsigned long hw2 = getauxval(AT_HWCAP2);
        #ifdef HWCAP2_I8MM
            if (hw2 & HWCAP2_I8MM) f |= WASTE_CPU_I8MM;
        #endif
        }
    #endif
    }
  #elif defined(_WIN32)
    /* Windows on ARM64: dot product is guaranteed on supported SoCs */
    if (IsProcessorFeaturePresent(PF_ARM_V82_DP_INSTRUCTIONS_AVAILABLE))
        f |= WASTE_CPU_DOTPROD;
  #endif
#elif defined(__ARM_NEON)
    f |= WASTE_CPU_NEON;
#endif

    cached = f; done = 1;
    return f;
}

t waste_backend_load(const char *path_or_name)
{
    if (!path_or_name || !*path_or_name) return -1;

    char buf[512];
    void *h = WASTE_DLOPEN(path_or_name);
    if (!h) {   /* try the conventional plugin name */
        snprintf(buf, sizeof(buf), "libwaste_%s%s", path_or_name, WASTE_DLEXT);
        h = WASTE_DLOPEN(buf);
    }
    if (!h) return -1;

    waste_backend_register_fn reg =
        (waste_backend_register_fn)WASTE_DLSYM(h, "waste_backend_register");
    if (!reg) return -1;           /* leave the handle open: harmless, rare */

    const char *name = reg(&waste_k);
    if (!name) return -1;          /* backend declined (no device, too old) */
    g_backend_name = name;
    return 0;
}

id waste_backend_init(unsigned flags)
{
    if (g_initialized) return;

    /* 1. universal baseline — always present, always correct */
    g_backend_name = waste_kda_register_cpu(&waste_k);
    g_initialized = 1;

    const char *env = getenv("WASTE_BACKEND");
    if (env && strcmp(env, "cpu") == 0) flags |= WASTE_BE_FORCE_CPU;
    if (flags & WASTE_BE_FORCE_CPU) return;

    /* 2. best in-process SIMD backend for this machine */
    const uint32_t f = waste_cpu_features();
    (void)f;
#if defined(__ARM_NEON) || defined(__aarch64__)
    if (f & WASTE_CPU_NEON) g_backend_name = waste_kda_register_neon(&waste_k);
#endif
    /* AVX2 / AVX-512 / SVE / RVV modules register here as they land, in
     * best-first order, each overwriting only what it implements. */

    /* 3. external accelerator plugins (never required, never fatal) */
    if (flags & WASTE_BE_NO_EXTERNAL) return;
    if (env && strcmp(env, "cpu") != 0 && strcmp(env, "neon") != 0)
        waste_backend_load(env);
}

co

t char *waste_backend_name(void)
{
    if (!g_initialized) waste_backend_init(WASTE_BE_AUTO);
    return g_backend_name;
}

const char *waste_kda_register_cpu(waste_kernels *t)
{
    t->kda_step = waste_kda_step;
    t->short_conv_step = waste_short_conv_step;
    t->rmsnorm_gated = waste_rmsnorm_gated;
    return "CPU";
}

atic float l2_rnorm_neon(const float *x, int n)
{
    float32x4_t acc = vdupq_n_f32(0.0f);
    int i = 0;
    for (; i + 4 <= n; i += 4) {
        float32x4_t v = vld1q_f32(x + i);
        acc = vfmaq_f32(acc, v, v);
    }
    float s = vaddvq_f32(acc);
    for (; i < n; i++) s += x[i] * x[i];
    return 1.0f / sqrtf(s + 1e-12f);
}

atic void kda_step_neon(int H, int K, int V,
                          const float *q, const float *k, const float *v,
                          const float *g_log, const float *beta,
                          float *S, float *o, float *u)
{
    const float qscale = 1.0f / sqrtf((float)K);

    for (int h = 0; h < H; h++) {
        const float *qh = q + (size_t)h * K;
        const float *kh = k + (size_t)h * K;
        const float *vh = v + (size_t)h * V;
        const float *gh = g_log + (size_t)h * K;
        float *Sh = S + (size_t)h * K * V;
        float *oh = o + (size_t)h * V;
        const float b = beta[h];

        const float qn = l2_rnorm_neon(qh, K) * qscale;
        const float kn = l2_rnorm_neon(kh, K);

        memset(u, 0, (size_t)V * sizeof(float));

        /* pass A: decay rows, accumulate u = S'^T k */
        for (int kk = 0; kk < K; kk++) {
            float *row = Sh + (size_t)kk * V;
            const float32x4_t vd = vdupq_n_f32(expf(gh[kk]));
            const float32x4_t vk = vdupq_n_f32(kh[kk] * kn);
            int i = 0;
            for (; i + 4 <= V; i += 4) {
                float32x4_t r = vmulq_f32(vld1q_f32(row + i), vd);
                vst1q_f32(row + i, r);
                vst1q_f32(u + i, vfmaq_f32(vld1q_f32(u + i), r, vk));
            }
            const float d = expf(gh[kk]), kv = kh[kk] * kn;
            for (; i < V; i++) { row[i] *= d; u[i] += row[i] * kv; }
        }

        /* delta */
        {
            const float32x4_t vb = vdupq_n_f32(b);
            int i = 0;
            for (; i + 4 <= V; i += 4) {
                float32x4_t d = vsubq_f32(vld1q_f32(vh + i), vld1q_f32(u + i));
                vst1q_f32(u + i, vmulq_f32(vb, d));
            }
            for (; i < V; i++) u[i] = b * (vh[i] - u[i]);
        }

        /* pass B: rank-1 update, accumulate o = S^T q */
        memset(oh, 0, (size_t)V * sizeof(float));
        for (int kk = 0; kk < K; kk++) {
            float *row = Sh + (size_t)kk * V;
            const float32x4_t vk = vdupq_n_f32(kh[kk] * kn);
            const float32x4_t vq = vdupq_n_f32(qh[kk] * qn);
            int i = 0;
            for (; i + 4 <= V; i += 4) {
                float32x4_t r = vfmaq_f32(vld1q_f32(row + i), vld1q_f32(u + i), vk);
                vst1q_f32(row + i, r);
                vst1q_f32(oh + i, vfmaq_f32(vld1q_f32(oh + i), r, vq));
            }
            const float kv = kh[kk] * kn, qv = qh[kk] * qn;
            for (; i < V; i++) { row[i] += u[i] * kv; oh[i] += row[i] * qv; }
        }
    }
}

nst char *waste_kda_register_neon(waste_kernels *t)
{
    t->kda_step = kda_step_neon;
    /* short_conv_step and rmsnorm_gated stay on the CPU baseline until
     * they show up in a profile — partial override is the whole point. */
    const uint32_t f = waste_cpu_features();
    if (f & WASTE_CPU_I8MM)    return "NEON+i8mm";
    if (f & WASTE_CPU_DOTPROD) return "NEON+dotprod";
    return "NEON";
}

#e

atic float l2_rnorm(const float *x, int n)
{
    float s = 0.0f;
    for (int i = 0; i < n; i++) s += x[i] * x[i];
    return 1.0f / sqrtf(s + 1e-12f);
}

id waste_kda_step(int H, int K, int V,
                    const float *q, const float *k, const float *v,
                    const float *g_log, const float *beta,
                    float *S, float *o, float *u)
{
    const float qscale = 1.0f / sqrtf((float)K);

    for (int h = 0; h < H; h++) {
        const float *qh = q + (size_t)h * K;
        const float *kh = k + (size_t)h * K;
        const float *vh = v + (size_t)h * V;
        const float *gh = g_log + (size_t)h * K;
        float *Sh = S + (size_t)h * K * V;
        float *oh = o + (size_t)h * V;
        const float b = beta[h];

        /* q, k are L2-normalized per head; q additionally scaled by K^-0.5 */
        const float qn = l2_rnorm(qh, K) * qscale;
        const float kn = l2_rnorm(kh, K);

        memset(u, 0, (size_t)V * sizeof(float));

        /* pass A: S <- Diag(exp(g)) S, and u = S^T k (post-decay) */
        for (int kk = 0; kk < K; kk++) {
            float *row = Sh + (size_t)kk * V;
            const float d = expf(gh[kk]);
            const float kv = kh[kk] * kn;
#if WASTE_SIMD_NEON
            const float32x4_t vd = vdupq_n_f32(d), vk = vdupq_n_f32(kv);
            int i = 0;
            for (; i + 4 <= V; i += 4) {
                float32x4_t r = vmulq_f32(vld1q_f32(row + i), vd);
                vst1q_f32(row + i, r);
                vst1q_f32(u + i, vfmaq_f32(vld1q_f32(u + i), r, vk));
            }
            for (; i < V; i++) { row[i] *= d; u[i] += row[i] * kv; }
#elif WASTE_SIMD_AVX2
            const __m256 vd = _mm256_set1_ps(d), vk = _mm256_set1_ps(kv);
            int i = 0;
            for (; i + 8 <= V; i += 8) {
                __m256 r = _mm256_mul_ps(_mm256_loadu_ps(row + i), vd);
                _mm256_storeu_ps(row + i, r);
                _mm256_storeu_ps(u + i,
                    _mm256_fmadd_ps(r, vk, _mm256_loadu_ps(u + i)));
            }
            for (; i < V; i++) { row[i] *= d; u[i] += row[i] * kv; }
#else
            for (int i = 0; i < V; i++) { row[i] *= d; u[i] += row[i] * kv; }
#endif
        }

        /* delta: d = beta * (v - u), reused as the rank-1 right factor */
        for (int i = 0; i < V; i++) u[i] = b * (vh[i] - u[i]);

        /* pass B: S += k d^T, and o = S^T q (post-update) */
        memset(oh, 0, (size_t)V * sizeof(float));
        for (int kk = 0; kk < K; kk++) {
            float *row = Sh + (size_t)kk * V;
            const float kv = kh[kk] * kn;
            const float qv = qh[kk] * qn;
#if WASTE_SIMD_NEON
            const float32x4_t vk = vdupq_n_f32(kv), vq = vdupq_n_f32(qv);
            int i = 0;
            for (; i + 4 <= V; i += 4) {
                float32x4_t r = vfmaq_f32(vld1q_f32(row + i), vld1q_f32(u + i), vk);
                vst1q_f32(row + i, r);
                vst1q_f32(oh + i, vfmaq_f32(vld1q_f32(oh + i), r, vq));
            }
            for (; i < V; i++) { row[i] += u[i] * kv; oh[i] += row[i] * qv; }
#elif WASTE_SIMD_AVX2
            const __m256 vk = _mm256_set1_ps(kv), vq = _mm256_set1_ps(qv);
            int i = 0;
            for (; i + 8 <= V; i += 8) {
                __m256 r = _mm256_fmadd_ps(_mm256_loadu_ps(u + i), vk,
                                           _mm256_loadu_ps(row + i));
                _mm256_storeu_ps(row + i, r);
                _mm256_storeu_ps(oh + i,
                    _mm256_fmadd_ps(r, vq, _mm256_loadu_ps(oh + i)));
            }
            for (; i < V; i++) { row[i] += u[i] * kv; oh[i] += row[i] * qv; }
#else
            for (int i = 0; i < V; i++) { row[i] += u[i] * kv; oh[i] += row[i] * qv; }
#endif
        }
    }
}

id waste_kda_forward(int T, int H, int K, int V,
                       const float *q, const float *k, const float *v,
                       const float *g_log, const float *beta,
                       float *S, float *o, float *scratch)
{
    for (int t = 0; t < T; t++) {
        waste_kda_step(H, K, V,
                       q + (size_t)t * H * K, k + (size_t)t * H * K,
                       v + (size_t)t * H * V, g_log + (size_t)t * H * K,
                       beta + (size_t)t * H,
                       S, o + (size_t)t * H * V, scratch);
    }
}

id waste_short_conv_step(int C, int KS, const float *w, const float *bias,
                           float *ring, const float *x, float *y)
{
    /* ring holds the previous KS-1 samples per channel, oldest first */
    const int R = KS - 1;
    for (int c = 0; c < C; c++) {
        const float *wc = w + (size_t)c * KS;
        float *rc = ring + (size_t)c * R;
        float acc = bias ? bias[c] : 0.0f;
        for (int j = 0; j < R; j++) acc += rc[j] * wc[j];
        acc += x[c] * wc[R];
        for (int j = 0; j + 1 < R; j++) rc[j] = rc[j + 1];
        if (R > 0) rc[R - 1] = x[c];
        y[c] = acc / (1.0f + expf(-acc));       /* SiLU */
    }
}

id waste_rmsnorm_gated(int C, const float *x, const float *gate,
                         const float *weight, float eps, float *y)
{
    float s = 0.0f;
    for (int i = 0; i < C; i++) s += x[i] * x[i];
    const float r = 1.0f / sqrtf(s / (float)C + eps);
    for (int i = 0; i < C; i++) {
        const float g = 1.0f / (1.0f + expf(-gate[i]));
        y[i] = x[i] * r * weight[i] * g;
    }
}

atic void *xread(FILE *f, size_t n)
{
    void *p = malloc(n);
    if (!p || fread(p, 1, n, f) != n) { fprintf(stderr, "short read\n"); exit(1); }
    return p;
}

t main(int argc, char **argv)
{
    if (argc < 3) { fprintf(stderr, "usage: %s fixture.bin out.bin\n", argv[0]); return 2; }
    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fixture"); return 1; }

    int32_t d[4];
    if (fread(d, sizeof(int32_t), 4, f) != 4) { fprintf(stderr, "bad header\n"); return 1; }
    const int T = d[0], H = d[1], K = d[2], V = d[3];
    printf("T=%d H=%d K=%d V=%d\n", T, H, K, V);

    const size_t nqk = (size_t)T * H * K, nv = (size_t)T * H * V;
    float *q = xread(f, nqk * sizeof(float));
    float *k = xread(f, nqk * sizeof(float));
    float *v = xread(f, nv * sizeof(float));
    float *g = xread(f, nqk * sizeof(float));
    float *beta = xread(f, (size_t)T * H * sizeof(float));
    float *S = xread(f, (size_t)H * K * V * sizeof(float));
    fclose(f);

    float *o = calloc(nv, sizeof(float));
    float *scratch = calloc((size_t)V, sizeof(float));
    if (!o || !scratch) { fprintf(stderr, "oom\n"); return 1; }

    waste_kda_forward(T, H, K, V, q, k, v, g, beta, S, o, scratch);

    FILE *out = fopen(argv[2], "wb");
    if (!out) { perror("out"); return 1; }
    fwrite(o, sizeof(float), nv, out);
    fwrite(S, sizeof(float), (size_t)H * K * V, out);
    fclose(out);
    printf("wrote %s\n", argv[2]);
    return 0;
}

atic void nocache(int fd) {
#ifdef __APPLE__
    fcntl(fd, F_NOCACHE, 1);
    fcntl(fd, F_RDAHEAD, 0);
#endif
}

atic void *rand_reader(void *p) {
    targ *a = (targ *)p;
    int fd = open(g_path, O_RDONLY);
    if (fd < 0) { perror("open"); return NULL; }
    nocache(fd);
    void *buf = NULL;
    if (posix_memalign(&buf, 4096, g_rec)) { close(fd); return NULL; }
    size_t nrec = g_file / g_rec;
    unsigned seed = 12345u + a->id * 7919u;
    double got = 0;
    for (int i = 0; i < g_reps; i++) {
        seed = seed * 1103515245u + 12345u;
        off_t off = (off_t)(seed % nrec) * g_rec;
        ssize_t r = pread(fd, buf, g_rec, off);
        if (r != (ssize_t)g_rec) { fprintf(stderr, "short read %zd\n", r); break; }
        got += r;
    }
    a->bytes = got;
    free(buf); close(fd);
    return NULL;
}

t main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s PATH [file_gb] [rec_mb] [threads]\n", argv[0]); return 1; }
    g_path = argv[1];
    double file_gb = argc > 2 ? atof(argv[2]) : 8.0;
    double rec_mb  = argc > 3 ? atof(argv[3]) : 12.0;
    int maxthreads = argc > 4 ? atoi(argv[4]) : 8;
    g_file = (size_t)(file_gb * (1u << 30));
    g_rec  = (size_t)(rec_mb * (1u << 20)) & ~4095UL;

    printf("file %.1f GB, record %.1f MB, path %s\n", file_gb, rec_mb, g_path);

    /* 1. sequential write */
    int fd = open(g_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) { perror("open write"); return 1; }
    nocache(fd);
    void *buf;
    if (posix_memalign(&buf, 4096, g_rec)) return 1;
    memset(buf, 0xA5, g_rec);
    double t0 = now(); size_t written = 0;
    while (written < g_file) {
        ssize_t w = write(fd, buf, g_rec);
        if (w <= 0) { perror("write"); break; }
        written += w;
    }
    fsync(fd); close(fd);
    double dt = now() - t0;
    printf("seq write   : %6.2f GB/s\n", written / dt / (1u << 30));

    /* 2. sequential read, cache-bypassed */
    fd = open(g_path, O_RDONLY); nocache(fd);
    t0 = now(); size_t rd = 0; ssize_t r;
    while ((r = read(fd, buf, g_rec)) > 0) rd += r;
    dt = now() - t0; close(fd);
    printf("seq read    : %6.2f GB/s  (cache bypassed)\n", rd / dt / (1u << 30));

    /* 3+4. random record reads, 1..maxthreads */
    g_reps = 40;
    for (int nt = 1; nt <= maxthreads; nt *= 2) {
        pthread_t th[64]; targ ta[64];
        t0 = now();
        for (int i = 0; i < nt; i++) {
            ta[i].id = i; ta[i].nthreads = nt; ta[i].bytes = 0;
            pthread_create(&th[i], NULL, rand_reader, &ta[i]);
        }
        double tot = 0;
        for (int i = 0; i < nt; i++) { pthread_join(th[i], NULL); tot += ta[i].bytes; }
        dt = now() - t0;
        double gbs = tot / dt / (1u << 30);
        printf("rand %2d thr : %6.2f GB/s  -> %.2f tok/s at 12.5 GB/token cold\n",
               nt, gbs, gbs / 12.5);
    }

    free(buf);
    unlink(g_path);
    return 0;
}

void camera_start_cinematic_shot(s32 playerId, s32 cameraId) {
    f32 prevX, prevY, prevZ, dx, dy, dz;
    prevX = camera->pos[0];
    prevY = camera->pos[1];
    prevZ = camera->pos[2];


    // Flag a camera cut only when the camera teleported to a new shot;
    // small moves are continuous tracking updates that should stay smooth.
    dx = camera->pos[0] - prevX;
    dy = camera->pos[1] - prevY;
    dz = camera->pos[2] - prevZ;
    if ((dx * dx + dy * dy + dz * dz) > 100.0f * 100.0f) {
        FrameInterpolation_DontInterpolateCamera();
    }
    camera_start_cinematic_shot(0, 0);
    camera_start_cinematic_shot(0, 1);
    camera_start_cinematic_shot(playerId, cameraId);
        camera_start_cinematic_shot(playerId, arg0);
            camera_start_cinematic_shot(arg2, arg1);
        camera_start_cinematic_shot((s32) playerId, cameraIndex);

static void ApplyPendingReset() {
    if (!sResetRequested.exchange(false)) {
        return;
    }

    // The FROM_QUIT gamestates run identical inits; alternating keeps
    // gGamestateNext != gGamestate true so every press re-enters the menus.
    gGamestateNext = (gGamestate == MAIN_MENU_FROM_QUIT) ? START_MENU_FROM_QUIT : MAIN_MENU_FROM_QUIT;
    gIsGamePaused = 0;
    // Reset credits
    D_800DC5E4 = 0;
    gTourComplete = false;
    SetMarioRaceway();
    memset(&gGameModeMenuColumn, 0, sizeof(s8) * NUM_ROWS_GAME_MODE_MENU);
    memset(&gGameModeSubMenuColumn, 0, sizeof(s8) * NUM_COLUMN_GAME_MODE_SUB_MENU * NUM_ROWS_GAME_MODE_SUB_MENU);

    CM_ResetAudio();

    // Close the editor.
    if (gEditor.IsEnabled()) {
        gEditor.Disable();
    }

    // Set the debug menu track browsing index back to zero
    TrackBrowser::Instance->Reset();

    // Land on the same screen the gSkipIntro setting picks at boot.
    switch (CVarGetInteger("gSkipIntro", 0)) {
        case 0:
            gMenuSelection = HARBOUR_MASTERS_MENU;
            break;
        case 1:
            gMenuSelection = LOGO_INTRO_MENU;
            break;
        case 2:
            gMenuSelection = START_MENU;
            break;
        case 3:
            gMenuSelection = MAIN_MENU;
            break;
    }

    // Debug mode override gSkipIntro
    if (CVarGetInteger("gEnableDebugMode", 0) == true) {
        gMenuSelection = START_MENU;
    }
    // Re-enter through the intro's own transition protocol (see HM_TickIntro):
    // FADE_MODE_LOGO makes setup_menus rebuild the menu items and start a
    // fresh fade-in, replacing any in-flight transition that would otherwise
    // advance the stale screen right after the reset.
    gMenuFadeType = 0;
    gFadeModeSelection = FADE_MODE_LOGO;
}

void __asan_alloca_poison(uintptr addr, size_t size)
    {
        uintptr const left_redzone_size = 32;
        uintptr const left_redzone_addr = addr - left_redzone_size;
        uintptr const partial_rz_addr = addr + size;
        uintptr const right_rz_addr = (partial_rz_addr + 31) & ~static_cast<uintptr>(31);
        uintptr const partial_rz_aligned = partial_rz_addr & ~static_cast<uintptr>(7);

        poison_shadow(left_redzone_addr, left_redzone_size, ASAN_SHADOW_ALLOCA_LEFT_MAGIC);

        size_t const partial = partial_rz_addr & KASAN_SHADOW_MASK;
        if (partial != 0)
        {
            *reinterpret_cast<uint8_t *>(KASAN_MEM_TO_SHADOW(partial_rz_aligned)) = static_cast<uint8_t>(partial);
            size_t const right_size = right_rz_addr - partial_rz_aligned - KASAN_SHADOW_GRANULE_SIZE;
            if (right_size > 0)
            {
                poison_shadow(partial_rz_aligned + KASAN_SHADOW_GRANULE_SIZE,
                              right_size,
                              ASAN_SHADOW_ALLOCA_RIGHT_MAGIC);
            }
        }
        else
        {
            size_t const right_size = right_rz_addr - partial_rz_aligned;
            if (right_size > 0)
            {
                poison_shadow(partial_rz_aligned, right_size, ASAN_SHADOW_ALLOCA_RIGHT_MAGIC);
            }
        }

        poison_shadow(right_rz_addr, left_redzone_size, ASAN_SHADOW_ALLOCA_RIGHT_MAGIC);
    }

void __asan_allocas_unpoison(uintptr top, uintptr bottom)
    {
        if (!g_kasan_initialized || top == 0 || top >= bottom)
        {
            return;
        }

        __kasan_memset(reinterpret_cast<void *>(KASAN_MEM_TO_SHADOW(top)),
                       ASAN_SHADOW_UNPOISONED_MAGIC,
                       (bottom - top) >> KASAN_SHADOW_SHIFT);
    }

static void annotate_range_transition(uintptr old_addr, uintptr new_addr)
{
    if (new_addr > old_addr)
    {
        // Region grew: unpoison [old_addr, new_addr).
        // Align down to cover the partial shadow byte at old_addr.
        uintptr const aligned_start = old_addr & ~static_cast<uintptr>(KASAN_SHADOW_MASK);
        unpoison_shadow(aligned_start, new_addr - aligned_start);
    }
    else if (new_addr < old_addr)
    {
        // Region shrank: poison [new_addr, old_addr).
        // Handle partial shadow byte at new_addr's block.
        size_t const new_partial = new_addr & KASAN_SHADOW_MASK;
        if (new_partial != 0)
        {
            *reinterpret_cast<uint8_t *>(KASAN_MEM_TO_SHADOW(new_addr)) =
                static_cast<uint8_t>(new_partial);
        }
        // Poison all complete 8-byte blocks between the two aligned boundaries.
        uintptr const new_aligned_next =
            (new_addr + KASAN_SHADOW_MASK) & ~static_cast<uintptr>(KASAN_SHADOW_MASK);
        uintptr const old_aligned = old_addr & ~static_cast<uintptr>(KASAN_SHADOW_MASK);
        if (new_aligned_next < old_aligned)
        {
            poison_shadow(new_aligned_next, old_aligned - new_aligned_next,
                          ASAN_SHADOW_CONTAINER_OVERFLOW_MAGIC);
        }
        // If old_addr is not 8-byte aligned and falls in a block beyond new_addr's
        // block, poison that block entirely.
        if ((old_addr & KASAN_SHADOW_MASK) != 0 && old_aligned >= new_aligned_next)
        {
            *reinterpret_cast<uint8_t *>(KASAN_MEM_TO_SHADOW(old_addr)) =
                ASAN_SHADOW_CONTAINER_OVERFLOW_MAGIC;
        }
    }
}

void __sanitizer_annotate_contiguous_container(
        void const* beg, void const* /*end*/,
        void const* old_mid, void const* new_mid)
    {
        if (!g_kasan_initialized || beg == nullptr)
            return;
        annotate_range_transition(reinterpret_cast<uintptr>(old_mid),
                                  reinterpret_cast<uintptr>(new_mid));
    }

void __sanitizer_annotate_double_ended_contiguous_container(
        void const* storage_beg, void const* /*storage_end*/,
        void const* old_container_beg, void const* old_container_end,
        void const* new_container_beg, void const* new_container_end)
    {
        if (!g_kasan_initialized || storage_beg == nullptr)
            return;
        // Front boundary: swap old/new because moving right = shrinking from left.
        annotate_range_transition(reinterpret_cast<uintptr>(new_container_beg),
                                  reinterpret_cast<uintptr>(old_container_beg));
        // Back boundary: normal direction, moving right = growing.
        annotate_range_transition(reinterpret_cast<uintptr>(old_container_end),
                                  reinterpret_cast<uintptr>(new_container_end));
    }

int __sanitizer_verify_double_ended_contiguous_container(
        void const* storage_beg, void const* container_beg,
        void const* container_end, void const* /*storage_end*/)
    {
        if (!g_kasan_initialized || storage_beg == nullptr)
            return 1;

        uintptr const beg_addr = reinterpret_cast<uintptr>(container_beg);
        uintptr const end_addr = reinterpret_cast<uintptr>(container_end);

        if (beg_addr >= end_addr)
            return 1;

        // Check all complete 8-byte blocks fully within [container_beg, container_end).
        uintptr const beg_aligned =
            (beg_addr + KASAN_SHADOW_MASK) & ~static_cast<uintptr>(KASAN_SHADOW_MASK);
        uintptr const end_aligned =
            end_addr & ~static_cast<uintptr>(KASAN_SHADOW_MASK);

        for (uintptr addr = beg_aligned; addr < end_aligned;
             addr += KASAN_SHADOW_GRANULE_SIZE)
        {
            if (*reinterpret_cast<uint8_t const*>(KASAN_MEM_TO_SHADOW(addr)) != 0)
                return 0;
        }

        return 1;
    }

CNVMeDevice::CNVMeDevice(void)
: 	m_PCIeExternal (PCIE_BUS_EXTERNAL, CInterruptSystem::Get()),
	m_Allocator (CMemorySystem::GetCoherentPage (COHERENT_SLOT_NVME),
		     CMemorySystem::GetCoherentPage (COHERENT_SLOT_NVME + 1)),
	m_ulOffset(0),
	m_pPartitionManager(nullptr)
{
	memset(&m_AdminQueue, 0, sizeof m_AdminQueue);
	m_AdminQueue.pName = "Admin";
	m_AdminQueue.usID = AQID;
	m_AdminQueue.nEntries = NVME_ADMIN_QUEUE_ENTRIES;

	memset(&m_IoQueue, 0, sizeof m_IoQueue);
	m_IoQueue.pName = "I/O";
	m_IoQueue.usID = IOQID;
	m_IoQueue.nEntries = NVME_IO_QUEUE_ENTRIES;
}

CNVMeDevice::~CNVMeDevice(void)
{
	delete m_pPartitionManager;
	m_pPartitionManager = nullptr;

        // Reset controller
        MmioWrite32(NVME_REG_CC, MmioRead32(NVME_REG_CC) & ~NVME_REG_CC_EN);
        WaitReady(false);

	if (m_AdminQueue.pSqVirt)
	{
		m_Allocator.Free(m_AdminQueue.pSqVirt);
		m_AdminQueue.pSqVirt = nullptr;
	}

	if (m_AdminQueue.pCqVirt)
	{
		m_Allocator.Free(m_AdminQueue.pCqVirt);
		m_AdminQueue.pCqVirt = nullptr;
	}

	if (m_IoQueue.pSqVirt)
	{
		m_Allocator.Free(m_IoQueue.pSqVirt);
		m_IoQueue.pSqVirt = nullptr;
	}

	if (m_IoQueue.pCqVirt)
	{
		m_Allocator.Free(m_IoQueue.pCqVirt);
		m_IoQueue.pCqVirt = nullptr;
	}
}

int CNVMeDevice::Read (void *pBuffer, size_t ulCount)
{
#ifdef NVME_DEBUG
	LOGDBG("Read(%p, %lu)", pBuffer, ulCount);
#endif

	assert (pBuffer);

	if (m_ulOffset & (NVME_LBA_SIZE-1))
	{
		return NVME_STATUS_ERROR_BAD_PARAM;
	}
        unsigned nLBA = m_ulOffset / NVME_LBA_SIZE;

	if (!ulCount || (ulCount & (NVME_LBA_SIZE-1)))
	{
		return NVME_STATUS_ERROR_BAD_PARAM;
	}

	// Use temporary DMA buffer, if pBuffer is not cache aligned
	void *pTransferBuffer = pBuffer;
	u8 *pDMABuffer = nullptr;
	if (!IS_CACHE_ALIGNED(pBuffer, ulCount))
	{
		pDMABuffer = new u8[ulCount];
		if (!pDMABuffer)
		{
			return NVME_STATUS_ERROR_NO_RESOURCE;
		}

		pTransferBuffer = pDMABuffer;
	}

	InvalidateDataCacheRange (reinterpret_cast<uintptr>(pTransferBuffer), ulCount);

	int nRet = IoPassThrough(NSID, nLBA, ulCount / NVME_LBA_SIZE, pTransferBuffer, false);
        if (nRet != NVME_STATUS_OK)
	{
		delete [] pDMABuffer;

		return nRet;
        }

	InvalidateDataCacheRange (reinterpret_cast<uintptr>(pTransferBuffer), ulCount);

	if (pDMABuffer)
	{
		memcpy (pBuffer, pDMABuffer, ulCount);

		delete [] pDMABuffer;
	}

        return ulCount;
}

int CNVMeDevice::Write (const void *pBuffer, size_t ulCount)
{
#ifdef NVME_DEBUG
	LOGDBG("Write(%p, %lu)", pBuffer, ulCount);
#endif

	assert (pBuffer);

	if (m_ulOffset & (NVME_LBA_SIZE-1))
	{
		return NVME_STATUS_ERROR_BAD_PARAM;
	}
        unsigned nLBA = m_ulOffset / NVME_LBA_SIZE;

	if (!ulCount || (ulCount & (NVME_LBA_SIZE-1)))
	{
		return NVME_STATUS_ERROR_BAD_PARAM;
	}

#ifdef NVME_READ_ONLY
	return NVME_STATUS_ERROR_READ_ONLY;
#endif

	// Use temporary DMA buffer, if pBuffer is not cache aligned
	void *pTransferBuffer = const_cast<void *> (pBuffer);
	u8 *pDMABuffer = nullptr;
	if (!IS_CACHE_ALIGNED(pBuffer, ulCount))
	{
		pDMABuffer = new u8[ulCount];
		if (!pDMABuffer)
		{
			return NVME_STATUS_ERROR_NO_RESOURCE;
		}

		memcpy (pDMABuffer, pBuffer, ulCount);

		pTransferBuffer = pDMABuffer;
	}

	CleanDataCacheRange (reinterpret_cast<uintptr>(pTransferBuffer), ulCount);

	int nRet = IoPassThrough(NSID, nLBA, ulCount / NVME_LBA_SIZE, pTransferBuffer, true);

	delete [] pDMABuffer;

        if (nRet != NVME_STATUS_OK)
	{

		return nRet;
        }

	return ulCount;
}

u64 CNVMeDevice::Seek (u64 ulOffset)
{
#ifdef NVME_DEBUG
	LOGDBG("Seek(%lu)", ulOffset);
#endif

	m_ulOffset = ulOffset;

	return ulOffset;
}

int CNVMeDevice::IOCtl (unsigned long ulCmd, void *pData)
{
#ifdef NVME_DEBUG
	LOGDBG("IOCtl(0x%lX)", ulCmd);
#endif

	if (ulCmd == DEVICE_IOCTL_SYNC)
	{
		return Flush(NSID);
	}

	return NVME_STATUS_ERROR_BAD_PARAM;
}

int CNVMeDevice::CreateAdminQueues(void)
{
	// Allocate space for queues. ASQ is submission queue (array of commands)
	size_t uSqSize = sizeof(TNVMeCommand) * NVME_ADMIN_QUEUE_ENTRIES;
	size_t uCqSize = sizeof(TNVMeCompletion) * NVME_ADMIN_QUEUE_ENTRIES;

	void *pSq = m_Allocator.Allocate(uSqSize, NVME_PAGE_SIZE);
	if (!pSq) return NVME_STATUS_ERROR_NO_RESOURCE;
	void *pCq = m_Allocator.Allocate(uCqSize, NVME_PAGE_SIZE);
	if (!pCq) return NVME_STATUS_ERROR_NO_RESOURCE;

	memset(pSq, 0, uSqSize);
	memset(pCq, 0, uCqSize);

	m_AdminQueue.pSqVirt = pSq;
	m_AdminQueue.pCqVirt = pCq;
	m_AdminQueue.nSqPhys = PhysicalOf(pSq);
	m_AdminQueue.nCqPhys = PhysicalOf(pCq);

	u32 uAqa = ((NVME_ADMIN_QUEUE_ENTRIES - 1) << 16) | (NVME_ADMIN_QUEUE_ENTRIES - 1);
	MmioWrite32(NVME_REG_AQA, uAqa);
	MmioWrite64(NVME_REG_ASQ, m_AdminQueue.nSqPhys);
	MmioWrite64(NVME_REG_ACQ, m_AdminQueue.nCqPhys);

	m_AdminQueue.nSqTail = 0;
	m_AdminQueue.nCqHead = 0;
	m_AdminQueue.bCqPhase = true;

	return NVME_STATUS_OK;
}

int CNVMeDevice::CreateIoQueue(u16 uQueueId, u16 uEntries)
{
	// For I/O queues, we need to send Admin Create I/O Completion Queue and
	// Create Submission Queue commands. We allocate SQ/CQ memory and then use
	// AdminCommand() to create queues.
	size_t uSqSize = sizeof(TNVMeCommand) * uEntries;
	size_t uCqSize = sizeof(TNVMeCompletion) * uEntries;

	void *pSq = m_Allocator.Allocate(uSqSize, NVME_PAGE_SIZE);
	if (!pSq) return NVME_STATUS_ERROR_NO_RESOURCE;
	void *pCq = m_Allocator.Allocate(uCqSize, NVME_PAGE_SIZE);
	if (!pCq) return NVME_STATUS_ERROR_NO_RESOURCE;

	memset(pSq, 0, uSqSize);
	memset(pCq, 0, uCqSize);

	m_IoQueue.pSqVirt = pSq;
	m_IoQueue.pCqVirt = pCq;
	m_IoQueue.nSqPhys = PhysicalOf(pSq);
	m_IoQueue.nCqPhys = PhysicalOf(pCq);

	// Build Create CQ
	u32 uCdw10 = (uQueueId & 0xffff) | ((uEntries - 1) << 16);
	// cdw11: PC=1(phys contig) | PRIO=0 | IRQ vector=0
	u32 uCdw11 = 1;
	// Data pointer: PRP1 = CQ physical base, PRP2 = 0
	u32 nRet = AdminCommand(NVME_ADMIN_OPC_CREATE_IO_CQ, 0, uCdw10, uCdw11, m_IoQueue.nCqPhys);
	if (nRet != NVME_STATUS_OK) return nRet;

	uCdw10 = (uQueueId & 0xffff) | ((uEntries - 1) << 16);
	// cdw11: CQid << 16, PC=1
	uCdw11 = (static_cast<u32>(uQueueId) << 16) | 1;
	nRet = AdminCommand(NVME_ADMIN_OPC_CREATE_IO_SQ, 0, uCdw10, uCdw11, m_IoQueue.nSqPhys);
	if (nRet != NVME_STATUS_OK) return nRet;

	m_IoQueue.nSqTail = 0;
	m_IoQueue.nCqHead = 0;
	m_IoQueue.bCqPhase = true;

	return NVME_STATUS_OK;
}

int CNVMeDevice::Identify(u32 uCns, void *pOutBuf, u32 uNsId)
{
	// Ensure buffer is physically contiguous and acquire physical address
	u64 uPhys = PhysicalOf(pOutBuf);

	// Build Admin Identify - CNS selects controller or namespace
	u32 uCdw10 = uCns;

	return AdminCommand(NVME_ADMIN_OPC_IDENTIFY, uNsId, uCdw10, 0, uPhys);
}

int CNVMeDevice::IoPassThrough(u32 nNsId, u64 nLba, u32 nBlocks, void *pBuffer, bool bIsWrite)
{
	assert (pBuffer);
	assert (nBlocks);

	CNVMePRP PrpBuilder(&m_Allocator);
	if (!PrpBuilder.BuildForBuffer(pBuffer, static_cast<size_t>(nBlocks) * NVME_LBA_SIZE))
	{
		return NVME_STATUS_ERROR_NO_RESOURCE;
	}

	return SubmitCommand(&m_IoQueue,
			     bIsWrite ? NVME_IO_OPC_WRITE : NVME_IO_OPC_READ,
			     nNsId,
			     static_cast<u32>(nLba & 0xffffffff),
			     static_cast<u32>((nLba >> 32) & 0xffffffff),
			     nBlocks - 1,
			     PrpBuilder.Prp1(),
			     PrpBuilder.Prp2());
}

int CNVMeDevice::AdminCommand(u8 uchOpcode, u32 nNsId, u32 uCdw10, u32 uCdw11, u64 ulDataPhysAddr)
{
	assert(ulDataPhysAddr);

	return SubmitCommand(&m_AdminQueue, uchOpcode, nNsId, uCdw10, uCdw11, 0, ulDataPhysAddr, 0);
}

int CNVMeDevice::SubmitCommand(TQueue *pQueue, u8 uchOpcode, u32 nNsId,
			       u32 nCdw10, u32 nCdw11, u32 nCdw12,
			       uintptr ulPrp1, uintptr ulPrp2)
{
	assert (pQueue);

#ifdef NVME_DEBUG
	LOGDBG("%s command (opcode 0x%02X, cdw 0x%X 0x%X 0x%X)",
	       pQueue->pName, uchOpcode, nCdw10, nCdw11, nCdw12);
#endif

	TNVMeCommand *pSq = reinterpret_cast<TNVMeCommand *>(pQueue->pSqVirt);

	u16 usCid = static_cast<u16>((pQueue->nSqTail) & 0xffff);
	TNVMeCommand *pCmd = &pSq[pQueue->nSqTail];
	memset(pCmd, 0, sizeof(TNVMeCommand));
	pCmd->opc = uchOpcode;
	pCmd->cid = usCid;
	pCmd->nsid = nNsId;
	pCmd->prp1 = ulPrp1;
	pCmd->prp2 = ulPrp2;
	pCmd->cdw10 = nCdw10;
	pCmd->cdw11 = nCdw11;
	pCmd->cdw12 = nCdw12;

	// Doorbell write for submission queue
	pQueue->nSqTail = (pQueue->nSqTail + 1) % pQueue->nEntries;
	DataSyncBarrier();
	MmioWrite32(NVME_DOORBELL_SQ_OFFSET(pQueue->usID), pQueue->nSqTail);

	return PollForCompletion(pQueue, usCid, POLL_TIMEOUT_HZ);
}

int CNVMeDevice::PollForCompletion(TQueue *pQueue, u16 usCid, unsigned nTimeoutHZ)
{
	assert (pQueue);
	assert (usCid < pQueue->nEntries);

	// Poll queue for matching CID
	TNVMeCompletion *pCq = reinterpret_cast<TNVMeCompletion *>(pQueue->pCqVirt);
	unsigned nStart = CTimer::Get()->GetTicks();

#ifdef NVME_DEBUG
	unsigned nStartClockTicks = CTimer::Get()->GetClockTicks();
#endif

	while (true)
	{
		DataMemBarrier();

		TNVMeCompletion &ce = pCq[pQueue->nCqHead];
		u16 usStatus = ATOMIC_READ(&ce.status);

		if (   !!(usStatus & CQE_STATUS_PHASE_BIT) == pQueue->bCqPhase
		    && ATOMIC_READ(&ce.cid) == usCid
		    && ATOMIC_READ(&ce.sqid) == pQueue->usID)
		{
			// Advance head
			pQueue->nCqHead = (pQueue->nCqHead + 1) % pQueue->nEntries;
			if (pQueue->nCqHead == 0) pQueue->bCqPhase = !pQueue->bCqPhase;
			DataSyncBarrier ();
			MmioWrite32(NVME_DOORBELL_CQ_OFFSET(pQueue->usID), pQueue->nCqHead);

			unsigned nSCT = (usStatus & CQE_STATUS_SCT__MASK) >> CQE_STATUS_SCT__SHIFT;
			unsigned nSC = (usStatus & CQE_STATUS_SC__MASK) >> CQE_STATUS_SC__SHIFT;
			if (nSCT || nSC)
			{
				LOGDBG("%s command failed (sct %u, sc 0x%X)",
				       pQueue->pName, nSCT, nSC);

				if (!nSCT && nSC == 0x80)
				{
					return NVME_STATUS_ERROR_LBA_RANGE;
				}

				return NVME_STATUS_ERROR_CONTROLLER;
			}

			break;
		}

		if (CTimer::Get()->GetTicks() - nStart > nTimeoutHZ)
		{
#ifdef NVME_DEBUG
			LOGDBG("%s command timed out", pQueue->pName);
#endif

			return NVME_STATUS_ERROR_TIMEOUT;
		}

#ifdef NO_BUSY_WAIT
		CScheduler::Get()->usSleep(50);
#else
		CTimer::Get()->usDelay(50);
#endif
	}

#ifdef NVME_DEBUG
	LOGDBG("%s command completed after %uus",
	       pQueue->pName, CTimer::Get()->GetClockTicks() - nStartClockTicks);
#endif

	return NVME_STATUS_OK;
}

bool CNVMeDevice::WaitReady(bool bOn)
{
	unsigned nStart = CTimer::Get()->GetTicks();

	while (true)
	{
		if (!!(MmioRead32(NVME_REG_CSTS) & NVME_REG_CSTS_RDY) == bOn)
		{
			return true;
		}

		if (CTimer::Get()->GetTicks() - nStart >= m_nTimeoutHZ)
		{
			break;
		}

#ifdef NO_BUSY_WAIT
		CScheduler::Get()->MsSleep(1);
#else
		CTimer::Get()->MsDelay(1);
#endif
	}

#ifdef NVME_DEBUG
	LOGDBG("Timeout");
#endif

	return false;
}

void CNVMeDevice::DumpStatus()
{
	for (u32 nOffset = 0; nOffset <= 0x3F; nOffset += 4)
	{
		LOGDBG("%04X: %08X", nOffset, MmioRead32 (nOffset));
	}

	m_PCIeExternal.DumpStatus (PCIE_SLOT, PCIE_FUNC);

	LOGDBG("%lu bytes shared memory free", m_Allocator.GetFreeSpace ());
}

CNVMePRP::~CNVMePRP()
{
	if (m_pPrpListVirt)
	{
		m_pAllocator->Free(m_pPrpListVirt);
		m_pPrpListVirt = nullptr;
		m_nPrpListPages = 0;
		m_uPrp1 = 0;
		m_uPrp2 = 0;
	}
}

bool CNVMePRP::BuildForBuffer(void *pBuffer, size_t ulLength)
{
	if (!pBuffer || ulLength == 0) return false;

	// Buffer is physically contiguous or described by page addresses
	// We'll compute PRP1 as physical address of the first page + offset within page.
	uintptr uBuf = reinterpret_cast<uintptr>(pBuffer);
	u64 uPhysFirst = PhysicalOf(pBuffer);

	m_uPrp1 = uPhysFirst;

	size_t uRemaining = ulLength;
	size_t uOffsetInFirstPage = uBuf & (PRP_PAGE_SIZE - 1);
	size_t uFirstPageRemaining = PRP_PAGE_SIZE - uOffsetInFirstPage;

	if (uRemaining <= uFirstPageRemaining)
	{
		// Data fits in a single PRP (PRP2 == 0)
		m_uPrp2 = 0;

		return true;
	}

	// Else we need PRP2 to point to next page phys address
	// Compute physical address of second page
	uintptr uSecondPageVirt = (uBuf & ~(PRP_PAGE_SIZE - 1)) + PRP_PAGE_SIZE;
	void *pSecondPagePtr = reinterpret_cast<void *>(uSecondPageVirt);
	u64 uPhysSecond = PhysicalOf(pSecondPagePtr);
	m_uPrp2 = uPhysSecond;

	uRemaining -= uFirstPageRemaining;

	if (uRemaining <= PRP_PAGE_SIZE)
	{
		// No PRP list needed; PRP2 points to last page
		return true;
	}

	// Need PRP list pages. Each PRP list page can hold PRP_PAGE_SIZE / PRP_ENTRY_SIZE entries.
	size_t uEntriesPerPage = PRP_PAGE_SIZE / PRP_ENTRY_SIZE;
	size_t uNeededEntries = (uRemaining + PRP_PAGE_SIZE - 1) / PRP_PAGE_SIZE;

	// Allocate one or more pages for PRP list
	size_t uPages = (uNeededEntries + uEntriesPerPage - 1) / uEntriesPerPage;
	void *pList = m_pAllocator->Allocate(uPages * PRP_PAGE_SIZE, PRP_PAGE_SIZE);
	if (!pList)
	{
		return false;
	}

	memset(pList, 0, uPages * PRP_PAGE_SIZE);

	// Fill list with subsequent page physical addresses
	u64 *pEntries = reinterpret_cast<u64 *>(pList);
	uintptr uCurPageVirt = uSecondPageVirt;
	for (size_t i = 0; i < uNeededEntries; ++i)
	{
		// compute physical of current page
		void *pPagePtr = reinterpret_cast<void *>(uCurPageVirt + i * PRP_PAGE_SIZE);
		pEntries[i] = PhysicalOf(pPagePtr);
	}

	m_pPrpListVirt = pList;
	m_nPrpListPages = uPages;

	// PRP2 should point to the PRP list page physical address
	m_uPrp2 = PhysicalOf(pList);

	return true;
}

CNVMeSharedMemAllocator::CNVMeSharedMemAllocator (uintptr nMemStart, uintptr nMemEnd)
:	m_nMemStart (nMemStart),
	m_nMemEnd (nMemEnd),
	m_pFreeList (0)
{
	assert (m_nMemStart != 0);
	assert (m_nMemEnd > m_nMemStart);
}

CNVMeSharedMemAllocator::~CNVMeSharedMemAllocator (void)
{
	m_nMemStart = 0;
	m_nMemEnd = 0;

	m_pFreeList = 0;
}

void *CNVMeSharedMemAllocator::Allocate (size_t nSize, size_t nAlign, size_t nBoundary)
{
	assert (nSize > 0);
	assert (nAlign != 0);
	assert (nAlign <= nBoundary);
	assert (m_nMemStart != 0);
	assert (m_nMemEnd != 0);

	if (   nSize <= NVME_BLOCK_SIZE
	    && nAlign <= NVME_BLOCK_ALIGN
	    && nBoundary <= NVME_BLOCK_BOUNDARY)
	{
		if (m_pFreeList != 0)
		{
			TNVMeBlockHeader *pBlockHeader = m_pFreeList;
			assert (pBlockHeader->nMagic == NVME_BLOCK_MAGIC);
			assert (pBlockHeader->nSize == NVME_BLOCK_SIZE);
			assert (pBlockHeader->nAlign == NVME_BLOCK_ALIGN);
			assert (pBlockHeader->nBoundary == NVME_BLOCK_BOUNDARY);

			m_pFreeList = pBlockHeader->pNext;
			pBlockHeader->pNext = 0;

			void *pResult = pBlockHeader->Data;
			assert (((uintptr) pResult & (NVME_BLOCK_ALIGN-1)) == 0);

			return pResult;
		}

		nSize = NVME_BLOCK_SIZE;
		nAlign = NVME_BLOCK_ALIGN;
		nBoundary = NVME_BLOCK_BOUNDARY;
	}

	m_nMemStart += sizeof (TNVMeBlockHeader);

	size_t nAlignMask = nAlign - 1;
	if (m_nMemStart & nAlignMask)
	{
		m_nMemStart += nAlignMask;
		m_nMemStart &= ~nAlignMask;
	}

	size_t nBoundaryMask = nBoundary - 1;
	if (   (m_nMemStart & ~nBoundaryMask)
	    != ((m_nMemStart + nSize-1) & ~nBoundaryMask))
	{
		m_nMemStart += nBoundaryMask;
		m_nMemStart &= ~nBoundaryMask;
	}

	TNVMeBlockHeader *pBlockHeader =
		(TNVMeBlockHeader *) (m_nMemStart - sizeof (TNVMeBlockHeader));

	m_nMemStart += nSize;

	if (m_nMemStart > m_nMemEnd)
	{
		return 0;
	}

	pBlockHeader->nMagic = NVME_BLOCK_MAGIC;
	pBlockHeader->nSize = (u32) nSize;
	pBlockHeader->nAlign = (u32) nAlign;
	pBlockHeader->nBoundary = (u32) nBoundary;
	pBlockHeader->pNext = 0;

	void *pResult = pBlockHeader->Data;
	assert (((uintptr) pResult & (nAlign-1)) == 0);

	return pResult;
}

void CNVMeSharedMemAllocator::Free (void *pBlock)
{
	assert (pBlock != 0);

	TNVMeBlockHeader *pBlockHeader =
		(TNVMeBlockHeader *) ((uintptr) pBlock - sizeof (TNVMeBlockHeader));
	assert (pBlockHeader->nMagic == NVME_BLOCK_MAGIC);

	if (   pBlockHeader->nSize == NVME_BLOCK_SIZE
	    && pBlockHeader->nAlign == NVME_BLOCK_ALIGN
	    && pBlockHeader->nBoundary == NVME_BLOCK_BOUNDARY)
	{
		pBlockHeader->pNext = m_pFreeList;
		m_pFreeList = pBlockHeader;
	}
	else
	{
		LOGWARN ("Trying to free shared memory at 0x%lX (size %u, align %u)",
			 (uintptr) pBlock, pBlockHeader->nSize, pBlockHeader->nAlign);
	}
}

sample_t get_usb_audio_input(void)
{
	sample_t zero = { 0.0f, 0.0f };
	return zero;
}

static void die(const char *fmt, ...)
{
	va_list ap;
	va_start(ap, fmt);
	vfprintf(stderr, fmt, ap);
	va_end(ap);
	exit(1);
}

static bool name_hit(const char *haystack, const char *needle, bool *exact)
{
	*exact = !strcasecmp(haystack, needle);
	if (*exact)
		return true;
	for (const char *p = haystack; *p; p++) {
		if (!strncasecmp(p, needle, strlen(needle)))
			return true;
	}
	return false;
}

static const char *unpad(const char *s)
{
	while (*s == ' ')
		s++;
	return s;
}

static struct effect *find_effect(const char *name)
{
	struct effect *hit = NULL;
	int hits = 0;

	for (int i = 0; i < (int)ARRAY_SIZE(effects); i++) {
		bool exact;

		if (!name_hit(effects[i]->name, name, &exact))
			continue;
		if (exact)
			return effects[i];
		hit = effects[i];
		hits++;
	}

	if (hits == 1)
		return hit;

	fprintf(stderr, hits ? "'%s' is ambiguous.  It could be:\n"
			     : "There is no effect called '%s'.  There is:\n",
		name);
	for (int i = 0; i < (int)ARRAY_SIZE(effects); i++) {
		bool exact;

		if (!hits || name_hit(effects[i]->name, name, &exact))
			fprintf(stderr, "    %s\n", effects[i]->name);
	}
	exit(1);
}

static int find_pot(struct effect *e, const char *label)
{
	int hit = -1, hits = 0;

	for (int i = 0; i < 10; i++) {
		bool exact;

		if (!e->pots[i].label)
			continue;
		if (!name_hit(unpad(e->pots[i].label), label, &exact))
			continue;
		if (exact)
			return i;
		hit = i;
		hits++;
	}

	if (hits == 1)
		return hit;

	fprintf(stderr, hits ? "'%s' is ambiguous on %s.  Its pots are:\n"
			     : "%s has no pot called '%s'.  It has:\n",
		hits ? label : e->name, hits ? e->name : label);
	for (int i = 0; i < 10; i++) {
		if (e->pots[i].label)
			fprintf(stderr, "    %s\n", unpad(e->pots[i].label));
	}
	exit(1);
}

static unsigned char pot_value(struct effect *e, int idx, const char *text)
{
	char *end;
	long v = strtol(text, &end, 0);

	if (end == text || *end)
		die("'%s' is not a number\n", text);
	if (v < 0 || v > max_pot_val(e, idx))
		die("%s / %s takes 0..%d, not %ld\n",
		    e->name, unpad(e->pots[idx].label), max_pot_val(e, idx), v);
	return (unsigned char) v;
}

static void list_effects(void)
{
	for (int i = 0; i < (int)ARRAY_SIZE(effects); i++) {
		struct effect *e = effects[i];

		printf("%s%s [mix: %s]\n", e->name,
		       effect_always_runs(i) ? "  (always runs)" : "",
		       e->no_mix ? "none" :
		       e->mix_law == MIX_POWER ? "equal power" : "linear");
		for (int p = 0; p < 10; p++) {
			if (!e->pots[p].label)
				continue;
			printf("    %-14s 0..%-4d default %-4d %s\n",
			       unpad(e->pots[p].label), max_pot_val(e, p),
			       e->pots[p].def_val,
			       e->pots[p].unit ? e->pots[p].unit : "");
		}
	}
}

static s32 float_to_raw(float v)
{
	float scaled = v / (float)SAMPLE_TO_FLOAT_MULTIPLIER;

	if (scaled >= RAW_FULL_SCALE)
		return INT32_MAX;
	if (scaled <= -RAW_FULL_SCALE)
		return INT32_MIN;
	return (s32) scaled;
}

static int run_map(const char *name)
{
	float (*fn)(float) = NULL;
	float x;

	for (int i = 0; i < (int)ARRAY_SIZE(maps); i++) {
		if (!strcasecmp(maps[i].name, name))
			fn = maps[i].fn;
	}
	if (!fn) {
		fprintf(stderr, "no such primitive '%s'.  There is:\n", name);
		for (int i = 0; i < (int)ARRAY_SIZE(maps); i++)
			fprintf(stderr, "    %s\n", maps[i].name);
		return 1;
	}

	while (fread(&x, sizeof(x), 1, stdin) == 1) {
		float y = fn(x);

		if (fwrite(&y, sizeof(y), 1, stdout) != 1)
			die("short write\n");
	}
	fflush(stdout);
	return 0;
}

static void bench_sample(raw_sample_t in, raw_sample_t *out)
{
	unsigned slot = cpu_idx;

	i2s_dma_buf[slot] = in;

	bench_dma_regs.ch[dma_rx].write_addr = (uintptr_t)&i2s_dma_buf[(slot + 1) & 15];
	bench_dma_regs.ch[dma_tx].read_addr  = (uintptr_t)&i2s_dma_buf[(slot + 8) & 15];

	//
	// 20.83us a sample at 48kHz.  The load meter reads the difference
	// across its own spin, which is zero here, so it will report a
	// fully loaded core.  That is honest - this "core" never waits -
	// and it is not audio either way.
	//
	bench_timer_regs.timerawl += 21;

	single_sample(1.0f);

	*out = i2s_dma_buf[slot];
}

static int read_input_report(hid_device *h, unsigned char *buf, int timeout_ms)
{
	int waited = 0;
	while (waited < timeout_ms) {
		int n = hid_read_timeout(h, buf, TEST_VDEV_REPORT_SIZE, 250);
		if (n < 0)
			return -1;                /* read error */
		if (n >= TEST_VDEV_REPORT_SIZE)
			return 0;                 /* got a full report */
		waited += 250;
	}
	return -1;                                /* timed out */
}

static void step(const char *what)
{
	printf("    -> %s\n", what);
	fflush(stdout);
}

static int run_device_io(test_virtual_device *vdev, hid_device *h)
{
	unsigned char out_report[1 + TEST_VDEV_REPORT_SIZE];
	unsigned char in_report[TEST_VDEV_REPORT_SIZE];
	const unsigned char expect_a[TEST_VDEV_REPORT_SIZE] = TEST_VDEV_INPUT_A;
	const unsigned char expect_b[TEST_VDEV_REPORT_SIZE] = TEST_VDEV_INPUT_B;

	/* write: send one output report (report id 0 + payload). Output-report
	   support depends on how each virtual device is built, so this is
	   best-effort - we exercise hid_write() and log the result rather than
	   hard-failing. The strictly-checked write path below is the Feature
	   report (the scenario trigger), which every provider implements. */
	memset(out_report, 0, sizeof(out_report));
	out_report[0] = 0x00;             /* report id (unnumbered device) */
	out_report[1] = 0x10;
	out_report[2] = 0x20;
	step("hid_write(output)");
	printf("    hid_write(output) returned %d\n",
	       hid_write(h, out_report, sizeof(out_report)));

	/* exchange A: a Feature report triggers scenario A; read the replay. */
	step("trigger A (hid_send_feature_report)");
	CHECK(test_virtual_device_trigger(vdev, h, TEST_VDEV_CMD_EMIT_A) >= 0);
	step("read A (hid_read_timeout)");
	memset(in_report, 0, sizeof(in_report));
	CHECK(read_input_report(h, in_report, READ_TIMEOUT_MS) == 0);
	CHECK(memcmp(in_report, expect_a, TEST_VDEV_REPORT_SIZE) == 0);

	/* exchange B. */
	step("trigger B (hid_send_feature_report)");
	CHECK(test_virtual_device_trigger(vdev, h, TEST_VDEV_CMD_EMIT_B) >= 0);
	step("read B (hid_read_timeout)");
	memset(in_report, 0, sizeof(in_report));
	CHECK(read_input_report(h, in_report, READ_TIMEOUT_MS) == 0);
	CHECK(memcmp(in_report, expect_b, TEST_VDEV_REPORT_SIZE) == 0);

	step("done");
	return 0;
}

int main(void)
{
	test_virtual_device *vdev = NULL;
	hid_device *h;
	int rc;

	if (hid_init() != 0) {
		printf("hid_init() failed\n");
		return EXIT_FAILURE;
	}

	step("create virtual device");
	rc = test_virtual_device_create(&vdev, TEST_VID, TEST_PID, TEST_SERIAL);
	if (rc == TEST_VDEV_UNAVAILABLE) {
		printf("virtual device unavailable on this host - skipping\n");
		hid_exit();
		return EXIT_SKIP;
	}
	if (rc != TEST_VDEV_OK || !vdev) {
		printf("failed to create virtual device (rc=%d)\n", rc);
		hid_exit();
		return EXIT_FAILURE;
	}

	/* Opening doubles as the presence probe: on platforms where create()
	   cannot itself tell whether a device is installed (Windows, macOS),
	   a failure to enumerate/open means there is no device here, so the
	   test skips rather than fails. */
	step("open via HIDAPI");
	h = test_virtual_device_open_hidapi(vdev, OPEN_TIMEOUT_MS);
	if (!h) {
		printf("virtual device did not enumerate - skipping\n");
		test_virtual_device_destroy(vdev);
		hid_exit();
		return EXIT_SKIP;
	}

	printf("running device-io smoke test...\n");
	rc = run_device_io(vdev, h);
	printf("%s device_io\n", (rc == 0 && g_failures == 0) ? "PASS" : "FAIL");

	hid_close(h);
	test_virtual_device_destroy(vdev);
	hid_exit();

	return (g_failures == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

static int load_spi(struct mac_spi *spi, void **out_handle)
{
	void *h = dlopen("/System/Library/Frameworks/IOKit.framework/IOKit",
	                 RTLD_LAZY | RTLD_LOCAL);
	if (!h)
		return -1;

	/* dlsym() returns an object pointer; converting it to a function pointer
	   directly is undefined in ISO C (and -pedantic rejects it), so pun via a
	   union. */
#define LOAD_SYM(field, type, name)                                       \
	do {                                                              \
		union { void *obj; type fn; } _u;                        \
		_u.obj = dlsym(h, (name));                               \
		(field) = _u.fn;                                         \
	} while (0)

	LOAD_SYM(spi->create, fn_create, "IOHIDUserDeviceCreate");
	LOAD_SYM(spi->schedule, fn_schedule, "IOHIDUserDeviceScheduleWithRunLoop");
	LOAD_SYM(spi->unschedule, fn_unschedule, "IOHIDUserDeviceUnscheduleFromRunLoop");
	LOAD_SYM(spi->reg_get, fn_reg_cb, "IOHIDUserDeviceRegisterGetReportCallback");
	LOAD_SYM(spi->reg_set, fn_reg_cb, "IOHIDUserDeviceRegisterSetReportCallback");
	LOAD_SYM(spi->handle_report, fn_handle, "IOHIDUserDeviceHandleReport");

#undef LOAD_SYM

	if (!spi->create || !spi->schedule || !spi->reg_set || !spi->handle_report) {
		dlclose(h);
		return -1;
	}
	*out_handle = h;
	return 0;
}

static IOReturn set_report_cb(void *refcon, IOHIDReportType type,
                              uint32_t reportID, uint8_t *report,
                              CFIndex reportLength)
{
	struct test_virtual_device *dev = (struct test_virtual_device *)refcon;
	unsigned char command = TEST_VDEV_CMD_NONE;
	CFIndex scan = reportLength > 4 ? 4 : reportLength;
	CFIndex i;
	(void)reportID;

	/* Only a *Feature* SET_REPORT is a scenario trigger (per the shared
	   contract and matching the other providers). hid_write() Output reports
	   also arrive through this callback on macOS and must not replay. */
	if (type != kIOHIDReportTypeFeature)
		return kIOReturnSuccess;

	for (i = 0; i < scan; i++) {
		if (report[i] == TEST_VDEV_CMD_EMIT_A || report[i] == TEST_VDEV_CMD_EMIT_B) {
			command = report[i];
			break;
		}
	}

	if (command == TEST_VDEV_CMD_EMIT_A) {
		uint8_t buf[TEST_VDEV_REPORT_SIZE];
		memcpy(buf, k_input_a, sizeof(buf));
		dev->spi.handle_report(dev->device, buf, sizeof(buf));
	} else if (command == TEST_VDEV_CMD_EMIT_B) {
		uint8_t buf[TEST_VDEV_REPORT_SIZE];
		memcpy(buf, k_input_b, sizeof(buf));
		dev->spi.handle_report(dev->device, buf, sizeof(buf));
	}
	return kIOReturnSuccess;
}

static IOReturn get_report_cb(void *refcon, IOHIDReportType type,
                              uint32_t reportID, uint8_t *report,
                              CFIndex reportLength)
{
	(void)refcon;
	(void)type;
	(void)reportID;
	if (report && reportLength > 0)
		memset(report, 0, reportLength);
	return kIOReturnSuccess;
}

static void *runloop_thread_fn(void *arg)
{
	struct test_virtual_device *dev = (struct test_virtual_device *)arg;

	dev->runloop = CFRunLoopGetCurrent();
	dev->spi.schedule(dev->device, dev->runloop, kCFRunLoopDefaultMode);

	pthread_mutex_lock(&dev->lock);
	dev->ready = 1;
	pthread_cond_signal(&dev->cond);
	pthread_mutex_unlock(&dev->lock);

	CFRunLoopRun();

	if (dev->spi.unschedule)
		dev->spi.unschedule(dev->device, dev->runloop, kCFRunLoopDefaultMode);
	return NULL;
}

static void dict_set_number(CFMutableDictionaryRef d, CFStringRef key, int value)
{
	CFNumberRef n = CFNumberCreate(kCFAllocatorDefault, kCFNumberSInt32Type, &value);
	if (n) {
		CFDictionarySetValue(d, key, n);
		CFRelease(n);
	}
}

int test_virtual_device_create(test_virtual_device **out_dev,
                               unsigned short vendor_id,
                               unsigned short product_id,
                               const char *serial)
{
	struct test_virtual_device *dev;
	CFMutableDictionaryRef props;
	CFDataRef rd;
	CFStringRef serial_cf;
	int rc;

	if (!out_dev)
		return TEST_VDEV_ERROR;
	*out_dev = NULL;

	dev = (struct test_virtual_device *)calloc(1, sizeof(*dev));
	if (!dev)
		return TEST_VDEV_ERROR;

	dev->vendor_id = vendor_id;
	dev->product_id = product_id;
	snprintf(dev->serial, sizeof(dev->serial), "%s", serial ? serial : "");
	pthread_mutex_init(&dev->lock, NULL);
	pthread_cond_init(&dev->cond, NULL);

	if (load_spi(&dev->spi, &dev->iokit_handle) != 0) {
		pthread_cond_destroy(&dev->cond);
		pthread_mutex_destroy(&dev->lock);
		free(dev);
		return TEST_VDEV_UNAVAILABLE;     /* SPI not present -> skip */
	}

	props = CFDictionaryCreateMutable(kCFAllocatorDefault, 0,
	                                  &kCFTypeDictionaryKeyCallBacks,
	                                  &kCFTypeDictionaryValueCallBacks);
	rd = CFDataCreate(kCFAllocatorDefault, k_report_descriptor,
	                  sizeof(k_report_descriptor));
	serial_cf = CFStringCreateWithCString(kCFAllocatorDefault, dev->serial,
	                                       kCFStringEncodingUTF8);
	if (!props || !rd || !serial_cf) {
		if (props) CFRelease(props);
		if (rd) CFRelease(rd);
		if (serial_cf) CFRelease(serial_cf);
		dlclose(dev->iokit_handle);
		pthread_cond_destroy(&dev->cond);
		pthread_mutex_destroy(&dev->lock);
		free(dev);
		return TEST_VDEV_ERROR;
	}

	CFDictionarySetValue(props, CFSTR("ReportDescriptor"), rd);
	dict_set_number(props, CFSTR(kIOHIDVendorIDKey), vendor_id);
	dict_set_number(props, CFSTR(kIOHIDProductIDKey), product_id);
	CFDictionarySetValue(props, CFSTR(kIOHIDSerialNumberKey), serial_cf);
	CFDictionarySetValue(props, CFSTR(kIOHIDProductKey),
	                     CFSTR("HIDAPI Test Device"));

	dev->device = dev->spi.create(kCFAllocatorDefault, props);

	CFRelease(props);
	CFRelease(rd);
	CFRelease(serial_cf);

	if (!dev->device) {
		/* Entitlement / consent denied (the usual case on hosted CI). */
		dlclose(dev->iokit_handle);
		pthread_cond_destroy(&dev->cond);
		pthread_mutex_destroy(&dev->lock);
		free(dev);
		return TEST_VDEV_UNAVAILABLE;
	}

	dev->spi.reg_set(dev->device, set_report_cb, dev);
	if (dev->spi.reg_get)
		dev->spi.reg_get(dev->device, get_report_cb, dev);

	rc = pthread_create(&dev->runloop_thread, NULL, runloop_thread_fn, dev);
	if (rc != 0) {
		CFRelease(dev->device);
		dlclose(dev->iokit_handle);
		pthread_cond_destroy(&dev->cond);
		pthread_mutex_destroy(&dev->lock);
		free(dev);
		return TEST_VDEV_ERROR;
	}
	dev->thread_started = 1;

	/* Wait until the run loop has scheduled the device. */
	pthread_mutex_lock(&dev->lock);
	while (!dev->ready)
		pthread_cond_wait(&dev->cond, &dev->lock);
	pthread_mutex_unlock(&dev->lock);

	*out_dev = dev;
	return TEST_VDEV_OK;
}

hid_device *test_virtual_device_open_hidapi(test_virtual_device *dev, int timeout_ms)
{
	wchar_t wserial[64];
	int waited = 0;
	size_t i;

	if (!dev)
		return NULL;

	for (i = 0; i + 1 < (sizeof(wserial) / sizeof(wserial[0])) && dev->serial[i]; i++)
		wserial[i] = (wchar_t)(unsigned char)dev->serial[i];
	wserial[i] = L'\0';

	for (;;) {
		struct hid_device_info *infos = hid_enumerate(dev->vendor_id, dev->product_id);
		struct hid_device_info *cur;
		struct hid_device_info *first = NULL;
		struct hid_device_info *match = NULL;
		hid_device *h = NULL;

		for (cur = infos; cur; cur = cur->next) {
			if (!first)
				first = cur;
			if (cur->serial_number && wcscmp(cur->serial_number, wserial) == 0) {
				match = cur;
				break;
			}
		}
		if (match || first)
			h = hid_open_path((match ? match : first)->path);
		hid_free_enumeration(infos);
		if (h)
			return h;

		if (waited >= timeout_ms)
			return NULL;
		struct timespec ts = { 0, 50 * 1000000L };
		nanosleep(&ts, NULL);
		waited += 50;
	}
}

int test_virtual_device_trigger(test_virtual_device *dev, hid_device *handle,
                                unsigned char command)
{
	unsigned char feature[1 + TEST_VDEV_REPORT_SIZE];
	(void)dev;
	memset(feature, 0, sizeof(feature));
	feature[0] = 0x00;        /* Report ID (the device has no numbered reports) */
	feature[1] = command;     /* scenario command, first byte of the payload */
	return hid_send_feature_report(handle, feature, sizeof(feature));
}

void test_virtual_device_destroy(test_virtual_device *dev)
{
	if (!dev)
		return;

	if (dev->thread_started) {
		if (dev->runloop)
			CFRunLoopStop(dev->runloop);
		pthread_join(dev->runloop_thread, NULL);
		dev->thread_started = 0;
	}

	if (dev->device) {
		CFRelease(dev->device);
		dev->device = NULL;
	}
	if (dev->iokit_handle) {
		dlclose(dev->iokit_handle);
		dev->iokit_handle = NULL;
	}

	pthread_cond_destroy(&dev->cond);
	pthread_mutex_destroy(&dev->lock);
	free(dev);
}

static void sleep_ms(int ms)
{
	struct timespec ts;
	ts.tv_sec = ms / 1000;
	ts.tv_nsec = (long)(ms % 1000) * 1000000L;
	nanosleep(&ts, NULL);
}

static void rg_install_signal(void)
{
	struct sigaction sa;
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = rg_sig_noop;
	sigaction(SIGUSR1, &sa, NULL);
}

static int ep_io_write(int fd, unsigned long request, int ep,
                       const void *data, int len)
{
	struct usb_raw_ep_io *io;
	int rv;
	if (len < 0)
		len = 0;
	io = (struct usb_raw_ep_io *)calloc(1, sizeof(*io) + (size_t)len);
	if (!io)
		return -1;
	io->ep = (__u16)ep;
	io->flags = 0;
	io->length = (__u32)len;
	if (data && len)
		memcpy(io->data, data, (size_t)len);
	rv = ioctl(fd, request, io);
	free(io);
	return rv;
}

static int ep0_read(int fd, void *data, int maxlen)
{
	struct usb_raw_ep_io *io;
	int rv;
	if (maxlen < 0)
		maxlen = 0;
	io = (struct usb_raw_ep_io *)calloc(1, sizeof(*io) + (size_t)maxlen);
	if (!io)
		return -1;
	io->ep = 0;
	io->flags = 0;
	io->length = (__u32)maxlen;
	rv = ioctl(fd, USB_RAW_IOCTL_EP0_READ, io);
	if (rv > 0 && data) {
		int cp = (rv > maxlen) ? maxlen : rv;
		memcpy(data, io->data, (size_t)cp);
	}
	free(io);
	return rv;
}

static void ep0_ack(int fd, const struct usb_ctrlrequest *ctrl)
{
	if (ctrl->bRequestType & USB_DIR_IN)
		ep0_write(fd, NULL, 0);
	else
		ep0_read(fd, NULL, 0);
}

static int build_config_descriptor(unsigned char *buf, int buflen, __u8 ep_addr)
{
	struct usb_config_descriptor cfg;
	struct usb_interface_descriptor intf;
	struct hid_class_desc hid;
	struct usb_endpoint_descriptor ep;
	/* On-the-wire sizes: struct usb_endpoint_descriptor is 9 bytes (it carries
	   2 trailing audio-only fields), but a non-audio endpoint descriptor is 7
	   bytes (USB_DT_ENDPOINT_SIZE). Use the wire sizes so no stray bytes follow
	   a descriptor (which the host would parse as a bogus length-0 descriptor). */
	int total = USB_DT_CONFIG_SIZE + USB_DT_INTERFACE_SIZE +
	            (int)sizeof(hid) + USB_DT_ENDPOINT_SIZE;
	int off = 0;

	if (buflen < total)
		return -1;

	memset(&cfg, 0, sizeof(cfg));
	cfg.bLength = USB_DT_CONFIG_SIZE;
	cfg.bDescriptorType = USB_DT_CONFIG;
	cfg.wTotalLength = (__u16)total;
	cfg.bNumInterfaces = 1;
	cfg.bConfigurationValue = 1;
	cfg.iConfiguration = 0;
	cfg.bmAttributes = 0x80;       /* bus powered */
	cfg.bMaxPower = 50;            /* 100 mA */

	memset(&intf, 0, sizeof(intf));
	intf.bLength = USB_DT_INTERFACE_SIZE;
	intf.bDescriptorType = USB_DT_INTERFACE;
	intf.bInterfaceNumber = 0;
	intf.bAlternateSetting = 0;
	intf.bNumEndpoints = 1;
	intf.bInterfaceClass = USB_CLASS_HID;     /* 0x03 */
	intf.bInterfaceSubClass = 0;
	intf.bInterfaceProtocol = 0;
	intf.iInterface = 0;

	memset(&hid, 0, sizeof(hid));
	hid.bLength = (__u8)sizeof(hid);
	hid.bDescriptorType = HID_DT_HID;
	hid.bcdHID = 0x0111;
	hid.bCountryCode = 0;
	hid.bNumDescriptors = 1;
	hid.bReportType = HID_DT_REPORT;
	hid.wReportLength = (__u16)sizeof(k_report_descriptor);

	memset(&ep, 0, sizeof(ep));
	ep.bLength = USB_DT_ENDPOINT_SIZE;
	ep.bDescriptorType = USB_DT_ENDPOINT;
	ep.bEndpointAddress = ep_addr;
	ep.bmAttributes = USB_ENDPOINT_XFER_INT;  /* 0x03 */
	ep.wMaxPacketSize = TEST_VDEV_REPORT_SIZE;
	ep.bInterval = 5;

	memcpy(buf + off, &cfg, USB_DT_CONFIG_SIZE);      off += USB_DT_CONFIG_SIZE;
	memcpy(buf + off, &intf, USB_DT_INTERFACE_SIZE);  off += USB_DT_INTERFACE_SIZE;
	memcpy(buf + off, &hid, sizeof(hid));             off += (int)sizeof(hid);
	memcpy(buf + off, &ep, USB_DT_ENDPOINT_SIZE);
	return total;
}

static int build_device_descriptor(struct test_virtual_device *dev,
                                   struct usb_device_descriptor *d)
{
	memset(d, 0, sizeof(*d));
	d->bLength = USB_DT_DEVICE_SIZE;
	d->bDescriptorType = USB_DT_DEVICE;
	d->bcdUSB = 0x0200;
	d->bDeviceClass = 0;
	d->bDeviceSubClass = 0;
	d->bDeviceProtocol = 0;
	d->bMaxPacketSize0 = 64;
	d->idVendor = dev->vendor_id;
	d->idProduct = dev->product_id;
	d->bcdDevice = 0x0100;
	d->iManufacturer = 1;
	d->iProduct = 2;
	d->iSerialNumber = 3;
	d->bNumConfigurations = 1;
	return (int)sizeof(*d);
}

static int build_string_descriptor(struct test_virtual_device *dev, __u8 index,
                                   unsigned char *buf, int buflen)
{
	const char *s;
	int i, n;

	if (index == 0) {
		if (buflen < 4)
			return -1;
		buf[0] = 4;
		buf[1] = USB_DT_STRING;
		buf[2] = 0x09;        /* 0x0409 English (US) */
		buf[3] = 0x04;
		return 4;
	}

	switch (index) {
	case 1:  s = "HIDAPI"; break;
	case 2:  s = "HIDAPI Test Device"; break;
	case 3:  s = dev->serial; break;
	default: s = ""; break;
	}

	n = (int)strlen(s);
	if (2 + n * 2 > buflen)
		n = (buflen - 2) / 2;
	buf[0] = (__u8)(2 + n * 2);
	buf[1] = USB_DT_STRING;
	for (i = 0; i < n; i++) {
		buf[2 + i * 2] = (unsigned char)s[i];
		buf[2 + i * 2 + 1] = 0;
	}
	return 2 + n * 2;
}

static void queue_input(struct test_virtual_device *dev, unsigned char command)
{
	pthread_mutex_lock(&dev->lock);
	dev->pending = command;
	pthread_cond_signal(&dev->cond);
	pthread_mutex_unlock(&dev->lock);
}

static void handle_control(struct test_virtual_device *dev,
                           const struct usb_ctrlrequest *ctrl)
{
	unsigned char buf[256];
	int wlen = (int)ctrl->wLength;
	int n;

	if ((ctrl->bRequestType & USB_TYPE_MASK) == USB_TYPE_STANDARD) {
		switch (ctrl->bRequest) {
		case USB_REQ_GET_DESCRIPTOR: {
			__u8 type = (__u8)(ctrl->wValue >> 8);
			__u8 idx = (__u8)(ctrl->wValue & 0xFF);
			if (type == USB_DT_DEVICE) {
				struct usb_device_descriptor d;
				n = build_device_descriptor(dev, &d);
				if (n > wlen) n = wlen;
				ep0_write(dev->fd, &d, n);
			} else if (type == USB_DT_CONFIG) {
				n = build_config_descriptor(buf, (int)sizeof(buf), dev->int_in_addr);
				if (n < 0) { ioctl(dev->fd, USB_RAW_IOCTL_EP0_STALL, 0); break; }
				if (n > wlen) n = wlen;
				ep0_write(dev->fd, buf, n);
			} else if (type == USB_DT_STRING) {
				n = build_string_descriptor(dev, idx, buf, (int)sizeof(buf));
				if (n < 0) { ioctl(dev->fd, USB_RAW_IOCTL_EP0_STALL, 0); break; }
				if (n > wlen) n = wlen;
				ep0_write(dev->fd, buf, n);
			} else if (type == HID_DT_REPORT) {
				n = (int)sizeof(k_report_descriptor);
				if (n > wlen) n = wlen;
				ep0_write(dev->fd, k_report_descriptor, n);
			} else if (type == HID_DT_HID) {
				struct hid_class_desc hid;
				memset(&hid, 0, sizeof(hid));
				hid.bLength = (__u8)sizeof(hid);
				hid.bDescriptorType = HID_DT_HID;
				hid.bcdHID = 0x0111;
				hid.bNumDescriptors = 1;
				hid.bReportType = HID_DT_REPORT;
				hid.wReportLength = (__u16)sizeof(k_report_descriptor);
				n = (int)sizeof(hid);
				if (n > wlen) n = wlen;
				ep0_write(dev->fd, &hid, n);
			} else {
				ioctl(dev->fd, USB_RAW_IOCTL_EP0_STALL, 0);
			}
			break;
		}
		case USB_REQ_SET_CONFIGURATION: {
			struct usb_endpoint_descriptor ep;
			int handle;
			memset(&ep, 0, sizeof(ep));
			ep.bLength = USB_DT_ENDPOINT_SIZE;
			ep.bDescriptorType = USB_DT_ENDPOINT;
			ep.bEndpointAddress = dev->int_in_addr;
			ep.bmAttributes = USB_ENDPOINT_XFER_INT;
			ep.wMaxPacketSize = TEST_VDEV_REPORT_SIZE;
			ep.bInterval = 5;
			handle = ioctl(dev->fd, USB_RAW_IOCTL_EP_ENABLE, &ep);
			if (handle >= 0) {
				dev->int_in_ep = handle;
				ioctl(dev->fd, USB_RAW_IOCTL_CONFIGURE, 0);
				dev->configured = 1;
			}
			ep0_ack(dev->fd, ctrl);   /* status ACK */
			break;
		}
		case USB_REQ_SET_INTERFACE:
			ep0_ack(dev->fd, ctrl);
			break;
		case USB_REQ_GET_STATUS: {
			unsigned char st[2] = { 0, 0 };
			ep0_write(dev->fd, st, sizeof(st));
			break;
		}
		default:
			ep0_ack(dev->fd, ctrl);
			break;
		}
		return;
	}

	if ((ctrl->bRequestType & USB_TYPE_MASK) == USB_TYPE_CLASS) {
		if (ctrl->bRequestType & USB_DIR_IN) {
			/* GET_REPORT / GET_IDLE / GET_PROTOCOL: benign reply. */
			if (ctrl->bRequest == HID_REQ_GET_REPORT) {
				memset(buf, 0, TEST_VDEV_REPORT_SIZE);
				n = TEST_VDEV_REPORT_SIZE;
				if (n > wlen) n = wlen;
				ep0_write(dev->fd, buf, n);
			} else {
				unsigned char z = 0;
				ep0_write(dev->fd, &z, wlen ? 1 : 0);
			}
			return;
		}

		/* Host-to-device class requests. */
		if (ctrl->bRequest == HID_REQ_SET_REPORT) {
			unsigned char command = TEST_VDEV_CMD_NONE;
			int i, scan;
			int len = wlen;
			if (len > (int)sizeof(buf))
				len = (int)sizeof(buf);
			n = ep0_read(dev->fd, buf, len);   /* read data stage + ACK */
			scan = (n > 4) ? 4 : n;
			for (i = 0; i < scan; i++) {
				if (buf[i] == TEST_VDEV_CMD_EMIT_A ||
				    buf[i] == TEST_VDEV_CMD_EMIT_B) {
					command = buf[i];
					break;
				}
			}
			if (command != TEST_VDEV_CMD_NONE)
				queue_input(dev, command);
		} else {
			/* SET_IDLE / SET_PROTOCOL and friends: just ACK. */
			ep0_ack(dev->fd, ctrl);
		}
		return;
	}

	/* Unknown request type. */
	ep0_ack(dev->fd, ctrl);
}

static void process_eps_info(struct test_virtual_device *dev)
{
	struct usb_raw_eps_info info;
	int num, i;
	memset(&info, 0, sizeof(info));
	num = ioctl(dev->fd, USB_RAW_IOCTL_EPS_INFO, &info);
	if (num < 0)
		return;
	for (i = 0; i < num && i < USB_RAW_EPS_NUM_MAX; i++) {
		if (info.eps[i].caps.type_int && info.eps[i].caps.dir_in) {
			__u32 addr = info.eps[i].addr;
			if (addr == USB_RAW_EP_ADDR_ANY)
				addr = 1;                       /* pick ep number 1 */
			dev->int_in_addr = (__u8)(0x80 | (addr & 0x0F));
			return;
		}
	}
}

static void *ep0_thread_fn(void *arg)
{
	struct test_virtual_device *dev = (struct test_virtual_device *)arg;
	struct usb_raw_event *ev;
	size_t evsz = sizeof(*ev) + sizeof(struct usb_ctrlrequest);

	ev = (struct usb_raw_event *)calloc(1, evsz);
	if (!ev)
		return NULL;

	while (!dev->stop) {
		int rv;
		ev->type = 0;
		ev->length = sizeof(struct usb_ctrlrequest);
		rv = ioctl(dev->fd, USB_RAW_IOCTL_EVENT_FETCH, ev);
		if (rv < 0) {
			if (errno == EINTR)
				continue;
			sleep_ms(10);
			continue;
		}

		if (ev->type == USB_RAW_EVENT_CONNECT) {
			process_eps_info(dev);
		} else if (ev->type == USB_RAW_EVENT_CONTROL) {
			struct usb_ctrlrequest ctrl;
			memcpy(&ctrl, ev->data, sizeof(ctrl));
			handle_control(dev, &ctrl);
		}
	}

	free(ev);
	dev->ep0_exited = 1;
	return NULL;
}

static void *int_in_thread_fn(void *arg)
{
	struct test_virtual_device *dev = (struct test_virtual_device *)arg;

	for (;;) {
		unsigned char command;
		const unsigned char *payload;

		pthread_mutex_lock(&dev->lock);
		while (!dev->stop && dev->pending == TEST_VDEV_CMD_NONE) {
			struct timespec ts;
			clock_gettime(CLOCK_REALTIME, &ts);
			ts.tv_nsec += 100 * 1000000L;
			if (ts.tv_nsec >= 1000000000L) {
				ts.tv_sec += 1;
				ts.tv_nsec -= 1000000000L;
			}
			pthread_cond_timedwait(&dev->cond, &dev->lock, &ts);
		}
		if (dev->stop) {
			pthread_mutex_unlock(&dev->lock);
			break;
		}
		command = dev->pending;
		dev->pending = TEST_VDEV_CMD_NONE;
		pthread_mutex_unlock(&dev->lock);

		if (!dev->configured || dev->int_in_ep < 0)
			continue;

		payload = (command == TEST_VDEV_CMD_EMIT_B) ? k_input_b : k_input_a;
		/* Best effort: may fail if the host isn't reading; ignore. */
		(void)ep_io_write(dev->fd, USB_RAW_IOCTL_EP_WRITE, dev->int_in_ep,
		                  payload, TEST_VDEV_REPORT_SIZE);
	}
	return NULL;
}

int test_virtual_device_create(test_virtual_device **out_dev,
                               unsigned short vendor_id,
                               unsigned short product_id,
                               const char *serial)
{
	struct test_virtual_device *dev;
	struct usb_raw_init init;
	int rc;

	if (!out_dev)
		return TEST_VDEV_ERROR;
	*out_dev = NULL;

	dev = (struct test_virtual_device *)calloc(1, sizeof(*dev));
	if (!dev)
		return TEST_VDEV_ERROR;

	dev->fd = -1;
	dev->int_in_ep = -1;
	dev->int_in_addr = 0x81;
	dev->pending = TEST_VDEV_CMD_NONE;
	dev->vendor_id = vendor_id;
	dev->product_id = product_id;
	snprintf(dev->serial, sizeof(dev->serial), "%s", serial ? serial : "");
	pthread_mutex_init(&dev->lock, NULL);
	pthread_cond_init(&dev->cond, NULL);

	dev->fd = open("/dev/raw-gadget", O_RDWR);
	if (dev->fd < 0) {
		int e = errno;
		pthread_cond_destroy(&dev->cond);
		pthread_mutex_destroy(&dev->lock);
		free(dev);
		if (e == ENOENT || e == EACCES || e == EPERM || e == ENODEV)
			return TEST_VDEV_UNAVAILABLE;
		return TEST_VDEV_ERROR;
	}

	memset(&init, 0, sizeof(init));
	/* dummy_hcd registers a UDC named "dummy_udc.0". */
	snprintf((char *)init.driver_name, sizeof(init.driver_name), "dummy_udc");
	snprintf((char *)init.device_name, sizeof(init.device_name), "dummy_udc.0");
	init.speed = USB_SPEED_HIGH;
	if (ioctl(dev->fd, USB_RAW_IOCTL_INIT, &init) < 0 ||
	    ioctl(dev->fd, USB_RAW_IOCTL_RUN, 0) < 0) {
		/* No dummy_hcd UDC present -> nothing to emulate on; skip. */
		close(dev->fd);
		pthread_cond_destroy(&dev->cond);
		pthread_mutex_destroy(&dev->lock);
		free(dev);
		return TEST_VDEV_UNAVAILABLE;
	}

	rg_install_signal();

	rc = pthread_create(&dev->ep0_thread, NULL, ep0_thread_fn, dev);
	if (rc != 0)
		goto fail_threads;
	dev->ep0_started = 1;

	rc = pthread_create(&dev->int_in_thread, NULL, int_in_thread_fn, dev);
	if (rc != 0)
		goto fail_threads;
	dev->int_in_started = 1;

	*out_dev = dev;
	return TEST_VDEV_OK;

fail_threads:
	dev->stop = 1;
	pthread_mutex_lock(&dev->lock);
	pthread_cond_broadcast(&dev->cond);
	pthread_mutex_unlock(&dev->lock);
	if (dev->ep0_started) {
		int spins = 0;
		while (!dev->ep0_exited && spins++ < 500) {
			pthread_kill(dev->ep0_thread, SIGUSR1);
			sleep_ms(10);
		}
		pthread_join(dev->ep0_thread, NULL);
	}
	close(dev->fd);
	pthread_cond_destroy(&dev->cond);
	pthread_mutex_destroy(&dev->lock);
	free(dev);
	return TEST_VDEV_ERROR;
}

hid_device *test_virtual_device_open_hidapi(test_virtual_device *dev, int timeout_ms)
{
	wchar_t wserial[64];
	int waited = 0;
	size_t i;

	if (!dev)
		return NULL;

	for (i = 0; i + 1 < (sizeof(wserial) / sizeof(wserial[0])) && dev->serial[i]; i++)
		wserial[i] = (wchar_t)(unsigned char)dev->serial[i];
	wserial[i] = L'\0';

	for (;;) {
		struct hid_device_info *infos = hid_enumerate(dev->vendor_id, dev->product_id);
		struct hid_device_info *cur;
		struct hid_device_info *first = NULL;
		struct hid_device_info *match = NULL;
		hid_device *h = NULL;

		for (cur = infos; cur; cur = cur->next) {
			if (!first)
				first = cur;
			if (cur->serial_number && wcscmp(cur->serial_number, wserial) == 0) {
				match = cur;
				break;
			}
		}
		if (match || first)
			h = hid_open_path((match ? match : first)->path);
		hid_free_enumeration(infos);
		if (h)
			return h;

		if (waited >= timeout_ms)
			return NULL;
		sleep_ms(50);
		waited += 50;
	}
}

int test_virtual_device_trigger(test_virtual_device *dev, hid_device *handle,
                                unsigned char command)
{
	unsigned char feature[1 + TEST_VDEV_REPORT_SIZE];
	(void)dev;
	memset(feature, 0, sizeof(feature));
	feature[0] = 0x00;        /* Report ID (the device has no numbered reports) */
	feature[1] = command;     /* scenario command, first byte of the payload */
	return hid_send_feature_report(handle, feature, sizeof(feature));
}

void test_virtual_device_destroy(test_virtual_device *dev)
{
	if (!dev)
		return;

	dev->stop = 1;
	pthread_mutex_lock(&dev->lock);
	pthread_cond_broadcast(&dev->cond);
	pthread_mutex_unlock(&dev->lock);

	/* The ep0 thread is parked in the blocking EVENT_FETCH ioctl (and the
	   int_in thread may be in EP_WRITE); interrupt them with SIGUSR1 until the
	   ep0 thread reports it has left its loop, so the joins below don't hang. */
	{
		int spins = 0;
		while (dev->ep0_started && !dev->ep0_exited && spins++ < 500) {
			pthread_kill(dev->ep0_thread, SIGUSR1);
			if (dev->int_in_started)
				pthread_kill(dev->int_in_thread, SIGUSR1);
			sleep_ms(10);
		}
	}

	if (dev->int_in_started) {
		pthread_join(dev->int_in_thread, NULL);
		dev->int_in_started = 0;
	}
	if (dev->ep0_started) {
		pthread_join(dev->ep0_thread, NULL);
		dev->ep0_started = 0;
	}

	if (dev->fd >= 0) {
		close(dev->fd);
		dev->fd = -1;
	}

	pthread_cond_destroy(&dev->cond);
	pthread_mutex_destroy(&dev->lock);
	free(dev);
}

static void write_event_best_effort(int fd, const struct uhid_event *ev)
{
	ssize_t r = write(fd, ev, sizeof(*ev));
	(void)r;
}

static void sleep_ms(int ms)
{
	struct timespec ts;
	ts.tv_sec = ms / 1000;
	ts.tv_nsec = (long)(ms % 1000) * 1000000L;
	nanosleep(&ts, NULL);
}

static void emit_input(struct test_virtual_device *dev, const unsigned char *payload)
{
	struct uhid_event ev;
	memset(&ev, 0, sizeof(ev));
	ev.type = UHID_INPUT2;
	ev.u.input2.size = TEST_VDEV_REPORT_SIZE;
	memcpy(ev.u.input2.data, payload, TEST_VDEV_REPORT_SIZE);

	pthread_mutex_lock(&dev->write_lock);
	write_event_best_effort(dev->fd, &ev);
	pthread_mutex_unlock(&dev->write_lock);
}

static void handle_set_report(struct test_virtual_device *dev, const struct uhid_event *in)
{
	struct uhid_event out;
	unsigned char command = TEST_VDEV_CMD_NONE;
	uint16_t scan = in->u.set_report.size;
	uint16_t i;
	if (scan > 4)
		scan = 4;
	for (i = 0; i < scan; i++) {
		unsigned char b = in->u.set_report.data[i];
		if (b == TEST_VDEV_CMD_EMIT_A || b == TEST_VDEV_CMD_EMIT_B) {
			command = b;
			break;
		}
	}

	memset(&out, 0, sizeof(out));
	out.type = UHID_SET_REPORT_REPLY;
	out.u.set_report_reply.id = in->u.set_report.id;
	out.u.set_report_reply.err = 0;
	pthread_mutex_lock(&dev->write_lock);
	write_event_best_effort(dev->fd, &out);
	pthread_mutex_unlock(&dev->write_lock);

	switch (command) {
	case TEST_VDEV_CMD_EMIT_A:
		emit_input(dev, k_input_a);
		break;
	case TEST_VDEV_CMD_EMIT_B:
		emit_input(dev, k_input_b);
		break;
	default:
		break;
	}
}

static void handle_get_report(struct test_virtual_device *dev, const struct uhid_event *in)
{
	struct uhid_event out;
	memset(&out, 0, sizeof(out));
	out.type = UHID_GET_REPORT_REPLY;
	out.u.get_report_reply.id = in->u.get_report.id;
	out.u.get_report_reply.err = 0;
	out.u.get_report_reply.size = 0;
	pthread_mutex_lock(&dev->write_lock);
	write_event_best_effort(dev->fd, &out);
	pthread_mutex_unlock(&dev->write_lock);
}

static void *pump_thread_fn(void *arg)
{
	struct test_virtual_device *dev = (struct test_virtual_device *)arg;

	while (!dev->stop) {
		struct pollfd pfd;
		int pret;
		ssize_t rret;
		struct uhid_event ev;

		pfd.fd = dev->fd;
		pfd.events = POLLIN;
		pfd.revents = 0;

		pret = poll(&pfd, 1, 100);
		if (pret <= 0)
			continue;       /* timeout (re-check stop) or EINTR */

		if (pfd.revents & (POLLERR | POLLHUP | POLLNVAL))
			break;

		memset(&ev, 0, sizeof(ev));
		rret = read(dev->fd, &ev, sizeof(ev));
		if (rret < 0) {
			if (errno == EAGAIN || errno == EINTR)
				continue;
			break;
		}

		switch (ev.type) {
		case UHID_SET_REPORT:
			handle_set_report(dev, &ev);
			break;
		case UHID_GET_REPORT:
			handle_get_report(dev, &ev);
			break;
		default:
			/* UHID_START / UHID_OPEN / UHID_CLOSE / UHID_STOP / UHID_OUTPUT */
			break;
		}
	}

	return NULL;
}

int test_virtual_device_create(test_virtual_device **out_dev,
                               unsigned short vendor_id,
                               unsigned short product_id,
                               const char *serial)
{
	struct test_virtual_device *dev;
	struct uhid_event ev;
	int rc;

	if (!out_dev)
		return TEST_VDEV_ERROR;
	*out_dev = NULL;

	dev = (struct test_virtual_device *)calloc(1, sizeof(*dev));
	if (!dev)
		return TEST_VDEV_ERROR;

	dev->fd = -1;
	dev->vendor_id = vendor_id;
	dev->product_id = product_id;
	snprintf(dev->serial, sizeof(dev->serial), "%s", serial ? serial : "");
	pthread_mutex_init(&dev->write_lock, NULL);

	dev->fd = open("/dev/uhid", O_RDWR | O_CLOEXEC);
	if (dev->fd < 0) {
		int e = errno;
		pthread_mutex_destroy(&dev->write_lock);
		free(dev);
		if (e == ENOENT || e == EACCES || e == EPERM || e == ENODEV)
			return TEST_VDEV_UNAVAILABLE;
		return TEST_VDEV_ERROR;
	}

	memset(&ev, 0, sizeof(ev));
	ev.type = UHID_CREATE2;
	snprintf((char *)ev.u.create2.name, sizeof(ev.u.create2.name), "HIDAPI Test Device");
	snprintf((char *)ev.u.create2.uniq, sizeof(ev.u.create2.uniq), "%s", dev->serial);
	memcpy(ev.u.create2.rd_data, k_report_descriptor, sizeof(k_report_descriptor));
	ev.u.create2.rd_size = (uint16_t)sizeof(k_report_descriptor);
	ev.u.create2.bus = 0x03;          /* BUS_USB */
	ev.u.create2.vendor = vendor_id;
	ev.u.create2.product = product_id;
	ev.u.create2.version = 0;
	ev.u.create2.country = 0;

	if (write(dev->fd, &ev, sizeof(ev)) < 0) {
		int e = errno;
		close(dev->fd);
		pthread_mutex_destroy(&dev->write_lock);
		free(dev);
		if (e == EACCES || e == EPERM)
			return TEST_VDEV_UNAVAILABLE;
		return TEST_VDEV_ERROR;
	}

	rc = pthread_create(&dev->pump_thread, NULL, pump_thread_fn, dev);
	if (rc != 0) {
		memset(&ev, 0, sizeof(ev));
		ev.type = UHID_DESTROY;
		write_event_best_effort(dev->fd, &ev);
		close(dev->fd);
		pthread_mutex_destroy(&dev->write_lock);
		free(dev);
		return TEST_VDEV_ERROR;
	}
	dev->pump_started = 1;

	*out_dev = dev;
	return TEST_VDEV_OK;
}

hid_device *test_virtual_device_open_hidapi(test_virtual_device *dev, int timeout_ms)
{
	wchar_t wserial[64];
	int waited = 0;
	size_t i;

	if (!dev)
		return NULL;

	for (i = 0; i + 1 < (sizeof(wserial) / sizeof(wserial[0])) && dev->serial[i]; i++)
		wserial[i] = (wchar_t)(unsigned char)dev->serial[i];
	wserial[i] = L'\0';

	/* The hidraw node and its udev attributes appear asynchronously after
	   UHID_CREATE2; poll enumeration until the device shows up. Match by the
	   (test-unique) VID/PID, preferring the entry whose serial matches. */
	for (;;) {
		struct hid_device_info *infos = hid_enumerate(dev->vendor_id, dev->product_id);
		struct hid_device_info *cur;
		struct hid_device_info *first = NULL;
		struct hid_device_info *match = NULL;
		hid_device *h = NULL;

		for (cur = infos; cur; cur = cur->next) {
			if (!first)
				first = cur;
			if (cur->serial_number && wcscmp(cur->serial_number, wserial) == 0) {
				match = cur;
				break;
			}
		}
		if (match || first)
			h = hid_open_path((match ? match : first)->path);
		hid_free_enumeration(infos);
		if (h)
			return h;

		if (waited >= timeout_ms)
			return NULL;
		sleep_ms(50);
		waited += 50;
	}
}

int test_virtual_device_trigger(test_virtual_device *dev, hid_device *handle,
                                unsigned char command)
{
	unsigned char feature[1 + TEST_VDEV_REPORT_SIZE];
	(void)dev;
	memset(feature, 0, sizeof(feature));
	feature[0] = 0x00;        /* Report ID (the device has no numbered reports) */
	feature[1] = command;     /* scenario command, first byte of the payload */
	return hid_send_feature_report(handle, feature, sizeof(feature));
}

void test_virtual_device_destroy(test_virtual_device *dev)
{
	struct uhid_event ev;

	if (!dev)
		return;

	if (dev->pump_started) {
		dev->stop = 1;
		pthread_join(dev->pump_thread, NULL);
		dev->pump_started = 0;
	}

	if (dev->fd >= 0) {
		memset(&ev, 0, sizeof(ev));
		ev.type = UHID_DESTROY;
		write_event_best_effort(dev->fd, &ev);
		close(dev->fd);
		dev->fd = -1;
	}

	pthread_mutex_destroy(&dev->write_lock);
	free(dev);
}

int test_virtual_device_create(test_virtual_device **out_dev,
                               unsigned short vendor_id,
                               unsigned short product_id,
                               const char *serial)
{
	struct test_virtual_device *dev;

	if (!out_dev)
		return TEST_VDEV_ERROR;
	*out_dev = NULL;

	dev = (struct test_virtual_device *)calloc(1, sizeof(*dev));
	if (!dev)
		return TEST_VDEV_ERROR;

	dev->vendor_id = vendor_id;
	dev->product_id = product_id;
	if (serial)
		strncpy_s(dev->serial, sizeof(dev->serial), serial, _TRUNCATE);

	/* The device (if any) is installed by the harness; presence is verified
	   by open_hidapi(). */
	*out_dev = dev;
	return TEST_VDEV_OK;
}

static ULONG query_feature_len(const char *path)
{
	HANDLE h;
	PHIDP_PREPARSED_DATA pp = NULL;
	ULONG feat = 0;

	h = CreateFileA(path, GENERIC_READ | GENERIC_WRITE,
	                FILE_SHARE_READ | FILE_SHARE_WRITE, NULL,
	                OPEN_EXISTING, 0, NULL);
	if (h == INVALID_HANDLE_VALUE)
		return 0;

	if (HidD_GetPreparsedData(h, &pp)) {
		HIDP_CAPS caps;
		if (HidP_GetCaps(pp, &caps) == HIDP_STATUS_SUCCESS) {
			printf("    device caps: input=%u output=%u feature=%u\n",
			       (unsigned)caps.InputReportByteLength,
			       (unsigned)caps.OutputReportByteLength,
			       (unsigned)caps.FeatureReportByteLength);
			feat = caps.FeatureReportByteLength;
		}
		HidD_FreePreparsedData(pp);
	}
	CloseHandle(h);
	return feat;
}

hid_device *test_virtual_device_open_hidapi(test_virtual_device *dev, int timeout_ms)
{
	int waited = 0;

	if (!dev)
		return NULL;

	for (;;) {
		struct hid_device_info *infos = hid_enumerate(dev->vendor_id, dev->product_id);
		hid_device *h = NULL;

		if (infos) {
			if (dev->feature_len == 0)
				dev->feature_len = query_feature_len(infos->path);
			h = hid_open_path(infos->path);
		}
		hid_free_enumeration(infos);
		if (h)
			return h;

		if (waited >= timeout_ms)
			return NULL;
		Sleep(50);
		waited += 50;
	}
}

int test_virtual_device_trigger(test_virtual_device *dev, hid_device *handle,
                                unsigned char command)
{
	unsigned char feature[256];
	size_t len = (1 + TEST_VDEV_REPORT_SIZE);

	/* Windows requires the feature buffer to be exactly FeatureReportByteLength. */
	if (dev && dev->feature_len > 0 && dev->feature_len <= sizeof(feature))
		len = dev->feature_len;

	memset(feature, 0, sizeof(feature));
	feature[0] = 0x00;        /* Report ID (the device has no numbered reports) */
	feature[1] = command;     /* scenario command, first byte of the payload */
	return hid_send_feature_report(handle, feature, len);
}

void test_virtual_device_destroy(test_virtual_device *dev)
{
	/* The harness uninstalls the driver/device after the test. */
	free(dev);
}

NTSTATUS
RequestGetHidXferPacket_ToReadFromDevice(
    _In_  WDFREQUEST        Request,
    _Out_ HID_XFER_PACKET  *Packet
    )
{
    //
    // Driver need to write to the output buffer (so that App can read from it)
    //
    //   Report Buffer: Output Buffer
    //   Report Id    : Input Buffer
    //

    NTSTATUS                status;
    WDFMEMORY               inputMemory;
    WDFMEMORY               outputMemory;
    size_t                  inputBufferLength;
    size_t                  outputBufferLength;
    PVOID                   inputBuffer;
    PVOID                   outputBuffer;

    //
    // Get report Id from input buffer
    //
    status = WdfRequestRetrieveInputMemory(Request, &inputMemory);
    if( !NT_SUCCESS(status) ) {
        KdPrint(("WdfRequestRetrieveInputMemory failed 0x%x\n",status));
        return status;
    }
    inputBuffer = WdfMemoryGetBuffer(inputMemory, &inputBufferLength);

    if (inputBufferLength < sizeof(UCHAR)) {
        status = STATUS_INVALID_BUFFER_SIZE;
        KdPrint(("WdfRequestRetrieveInputMemory: invalid input buffer. size %d, expect %d\n",
                            (int)inputBufferLength, (int)sizeof(UCHAR)));
        return status;
    }

    Packet->reportId        = *(PUCHAR)inputBuffer;

    //
    // Get report buffer from output buffer
    //
    status = WdfRequestRetrieveOutputMemory(Request, &outputMemory);
    if( !NT_SUCCESS(status) ) {
        KdPrint(("WdfRequestRetrieveOutputMemory failed 0x%x\n",status));
        return status;
    }

    outputBuffer = WdfMemoryGetBuffer(outputMemory, &outputBufferLength);

    Packet->reportBuffer    = (PUCHAR) outputBuffer;
    Packet->reportBufferLen = (ULONG)  outputBufferLength;

    return status;
}

NTSTATUS
RequestGetHidXferPacket_ToWriteToDevice(
    _In_  WDFREQUEST        Request,
    _Out_ HID_XFER_PACKET  *Packet
    )
{
    //
    // Driver need to read from the input buffer (which was written by App)
    //
    //   Report Buffer: Input Buffer
    //   Report Id    : Output Buffer Length
    //
    // Note that the report id is not stored inside the output buffer, as the
    // driver has no read-access right to the output buffer, and trying to read
    // from the buffer will cause an access violation error.
    //
    // The workaround is to store the report id in the OutputBufferLength field,
    // to which the driver does have read-access right.
    //

    NTSTATUS                status;
    WDFMEMORY               inputMemory;
    WDFMEMORY               outputMemory;
    size_t                  inputBufferLength;
    size_t                  outputBufferLength;
    PVOID                   inputBuffer;

    //
    // Get report Id from output buffer length
    //
    status = WdfRequestRetrieveOutputMemory(Request, &outputMemory);
    if( !NT_SUCCESS(status) ) {
        KdPrint(("WdfRequestRetrieveOutputMemory failed 0x%x\n",status));
        return status;
    }
    WdfMemoryGetBuffer(outputMemory, &outputBufferLength);
    Packet->reportId        = (UCHAR) outputBufferLength;

    //
    // Get report buffer from input buffer
    //
    status = WdfRequestRetrieveInputMemory(Request, &inputMemory);
    if( !NT_SUCCESS(status) ) {
        KdPrint(("WdfRequestRetrieveInputMemory failed 0x%x\n",status));
        return status;
    }
    inputBuffer = WdfMemoryGetBuffer(inputMemory, &inputBufferLength);

    Packet->reportBuffer    = (PUCHAR) inputBuffer;
    Packet->reportBufferLen = (ULONG)  inputBufferLength;

    return status;
}

NTSTATUS
DriverEntry(
    _In_  PDRIVER_OBJECT    DriverObject,
    _In_  PUNICODE_STRING   RegistryPath
    )
/*++

Routine Description:
    DriverEntry initializes the driver and is the first routine called by the
    system after the driver is loaded. DriverEntry specifies the other entry
    points in the function driver, such as EvtDevice and DriverUnload.

Parameters Description:

    DriverObject - represents the instance of the function driver that is loaded
    into memory. DriverEntry must initialize members of DriverObject before it
    returns to the caller. DriverObject is allocated by the system before the
    driver is loaded, and it is released by the system after the system unloads
    the function driver from memory.

    RegistryPath - represents the driver specific path in the Registry.
    The function driver can use the path to store driver related data between
    reboots. The path does not store hardware instance specific data.

Return Value:

    STATUS_SUCCESS, or another status value for which NT_SUCCESS(status) equals
                    TRUE if successful,

    STATUS_UNSUCCESSFUL, or another status for which NT_SUCCESS(status) equals
                    FALSE otherwise.

--*/
{
    WDF_DRIVER_CONFIG       config;
    NTSTATUS                status;

    KdPrint(("DriverEntry for VHidMini\n"));

#ifdef _KERNEL_MODE
    //
    // Opt-in to using non-executable pool memory on Windows 8 and later.
    // https://msdn.microsoft.com/en-us/library/windows/hardware/hh920402(v=vs.85).aspx
    //
    ExInitializeDriverRuntime(DrvRtPoolNxOptIn);
#endif

    WDF_DRIVER_CONFIG_INIT(&config, EvtDeviceAdd);

    status = WdfDriverCreate(DriverObject,
                            RegistryPath,
                            WDF_NO_OBJECT_ATTRIBUTES,
                            &config,
                            WDF_NO_HANDLE);
    if (!NT_SUCCESS(status)) {
        KdPrint(("Error: WdfDriverCreate failed 0x%x\n", status));
        return status;
    }

    return status;
}

NTSTATUS
EvtDeviceAdd(
    _In_  WDFDRIVER         Driver,
    _Inout_ PWDFDEVICE_INIT DeviceInit
    )
/*++
Routine Description:

    EvtDeviceAdd is called by the framework in response to AddDevice
    call from the PnP manager. We create and initialize a device object to
    represent a new instance of the device.

Arguments:

    Driver - Handle to a framework driver object created in DriverEntry

    DeviceInit - Pointer to a framework-allocated WDFDEVICE_INIT structure.

Return Value:

    NTSTATUS

--*/
{
    NTSTATUS                status;
    WDF_OBJECT_ATTRIBUTES   deviceAttributes;
    WDFDEVICE               device;
    PDEVICE_CONTEXT         deviceContext;
    PHID_DEVICE_ATTRIBUTES  hidAttributes;
    UNREFERENCED_PARAMETER  (Driver);

    KdPrint(("Enter EvtDeviceAdd\n"));

    //
    // Mark ourselves as a filter, which also relinquishes power policy ownership
    //
    WdfFdoInitSetFilter(DeviceInit);

    WDF_OBJECT_ATTRIBUTES_INIT_CONTEXT_TYPE(
                            &deviceAttributes,
                            DEVICE_CONTEXT);

    status = WdfDeviceCreate(&DeviceInit,
                            &deviceAttributes,
                            &device);
    if (!NT_SUCCESS(status)) {
        KdPrint(("Error: WdfDeviceCreate failed 0x%x\n", status));
        return status;
    }

    deviceContext = GetDeviceContext(device);
    deviceContext->Device       = device;
    deviceContext->DeviceData   = 0;

    hidAttributes = &deviceContext->HidDeviceAttributes;
    RtlZeroMemory(hidAttributes, sizeof(HID_DEVICE_ATTRIBUTES));
    hidAttributes->Size         = sizeof(HID_DEVICE_ATTRIBUTES);
    hidAttributes->VendorID     = HIDMINI_VID;
    hidAttributes->ProductID    = HIDMINI_PID;
    hidAttributes->VersionNumber = HIDMINI_VERSION;

    status = QueueCreate(device,
                         &deviceContext->DefaultQueue);
    if( !NT_SUCCESS(status) ) {
        return status;
    }

    status = ManualQueueCreate(device,
                               &deviceContext->ManualQueue);
    if( !NT_SUCCESS(status) ) {
        return status;
    }

    //
    // Use default "HID Descriptor" (hardcoded). We will set the
    // wReportLength memeber of HID descriptor when we read the
    // the report descriptor either from registry or the hard-coded
    // one.
    //
    deviceContext->HidDescriptor = G_DefaultHidDescriptor;

    //
    // Check to see if we need to read the Report Descriptor from
    // registry. If the "ReadFromRegistry" flag in the registry is set
    // then we will read the descriptor from registry using routine
    // ReadDescriptorFromRegistry(). Otherwise, we will use the
    // hard-coded default report descriptor.
    //

    status = CheckRegistryForDescriptor(device);
    if (NT_SUCCESS(status)){
        //
        // We need to read read descriptor from registry
        //
        status = ReadDescriptorFromRegistry(device);
        if (!NT_SUCCESS(status)){
            KdPrint(("Failed to read descriptor from registry\n"));
        }
    }

    //
    // We will use hard-coded report descriptor if registry one is not used.
    //
    if (!NT_SUCCESS(status)){
        deviceContext->ReportDescriptor = G_DefaultReportDescriptor;
        KdPrint(("Using Hard-coded Report descriptor\n"));
        status = STATUS_SUCCESS;
    }

    return status;
}

NTSTATUS
QueueCreate(
    _In_  WDFDEVICE         Device,
    _Out_ WDFQUEUE          *Queue
    )
/*++
Routine Description:

    This function creates a default, parallel I/O queue to proces IOCTLs
    from hidclass.sys.

Arguments:

    Device - Handle to a framework device object.

    Queue - Output pointer to a framework I/O queue handle, on success.

Return Value:

    NTSTATUS

--*/
{
    NTSTATUS                status;
    WDF_IO_QUEUE_CONFIG     queueConfig;
    WDF_OBJECT_ATTRIBUTES   queueAttributes;
    WDFQUEUE                queue;
    PQUEUE_CONTEXT          queueContext;

    WDF_IO_QUEUE_CONFIG_INIT_DEFAULT_QUEUE(
                            &queueConfig,
                            WdfIoQueueDispatchParallel);

#ifdef _KERNEL_MODE
    queueConfig.EvtIoInternalDeviceControl  = EvtIoDeviceControl;
#else
    //
    // HIDclass uses INTERNAL_IOCTL which is not supported by UMDF. Therefore
    // the hidumdf.sys changes the IOCTL type to DEVICE_CONTROL for next stack
    // and sends it down
    //
    queueConfig.EvtIoDeviceControl          = EvtIoDeviceControl;
#endif

    WDF_OBJECT_ATTRIBUTES_INIT_CONTEXT_TYPE(
                            &queueAttributes,
                            QUEUE_CONTEXT);

    status = WdfIoQueueCreate(
                            Device,
                            &queueConfig,
                            &queueAttributes,
                            &queue);

    if( !NT_SUCCESS(status) ) {
        KdPrint(("WdfIoQueueCreate failed 0x%x\n",status));
        return status;
    }

    queueContext = GetQueueContext(queue);
    queueContext->Queue         = queue;
    queueContext->DeviceContext = GetDeviceContext(Device);
    queueContext->OutputReport  = 0;

    *Queue = queue;
    return status;
}

NTSTATUS
RequestCopyFromBuffer(
    _In_  WDFREQUEST        Request,
    _In_  PVOID             SourceBuffer,
    _When_(NumBytesToCopyFrom == 0, __drv_reportError(NumBytesToCopyFrom cannot be zero))
    _In_  size_t            NumBytesToCopyFrom
    )
/*++

Routine Description:

    A helper function to copy specified bytes to the request's output memory

Arguments:

    Request - A handle to a framework request object.

    SourceBuffer - The buffer to copy data from.

    NumBytesToCopyFrom - The length, in bytes, of data to be copied.

Return Value:

    NTSTATUS

--*/
{
    NTSTATUS                status;
    WDFMEMORY               memory;
    size_t                  outputBufferLength;

    status = WdfRequestRetrieveOutputMemory(Request, &memory);
    if( !NT_SUCCESS(status) ) {
        KdPrint(("WdfRequestRetrieveOutputMemory failed 0x%x\n",status));
        return status;
    }

    WdfMemoryGetBuffer(memory, &outputBufferLength);
    if (outputBufferLength < NumBytesToCopyFrom) {
        status = STATUS_INVALID_BUFFER_SIZE;
        KdPrint(("RequestCopyFromBuffer: buffer too small. Size %d, expect %d\n",
                (int)outputBufferLength, (int)NumBytesToCopyFrom));
        return status;
    }

    status = WdfMemoryCopyFromBuffer(memory,
                                    0,
                                    SourceBuffer,
                                    NumBytesToCopyFrom);
    if( !NT_SUCCESS(status) ) {
        KdPrint(("WdfMemoryCopyFromBuffer failed 0x%x\n",status));
        return status;
    }

    WdfRequestSetInformation(Request, NumBytesToCopyFrom);
    return status;
}

NTSTATUS
ReadReport(
    _In_  PQUEUE_CONTEXT    QueueContext,
    _In_  WDFREQUEST        Request,
    _Always_(_Out_)
          BOOLEAN*          CompleteRequest
    )
/*++

Routine Description:

    Handles IOCTL_HID_READ_REPORT for the HID collection. Normally the request
    will be forwarded to a manual queue for further process. In that case, the
    caller should not try to complete the request at this time, as the request
    will later be retrieved back from the manually queue and completed there.
    However, if for some reason the forwarding fails, the caller still need
    to complete the request with proper error code immediately.

Arguments:

    QueueContext - The object context associated with the queue

    Request - Pointer to  Request Packet.

    CompleteRequest - A boolean output value, indicating whether the caller
            should complete the request or not

Return Value:

    NT status code.

--*/
{
    NTSTATUS                status;

    KdPrint(("ReadReport\n"));

    //
    // forward the request to manual queue
    //
    status = WdfRequestForwardToIoQueue(
                            Request,
                            QueueContext->DeviceContext->ManualQueue);
    if( !NT_SUCCESS(status) ) {
        KdPrint(("WdfRequestForwardToIoQueue failed with 0x%x\n", status));
        *CompleteRequest = TRUE;
    }
    else {
        *CompleteRequest = FALSE;
    }

    return status;
}

NTSTATUS
WriteReport(
    _In_  PQUEUE_CONTEXT    QueueContext,
    _In_  WDFREQUEST        Request
    )
/*++

Routine Description:

    Handles IOCTL_HID_WRITE_REPORT all the collection.

Arguments:

    QueueContext - The object context associated with the queue

    Request - Pointer to  Request Packet.

Return Value:

    NT status code.

--*/

{
    NTSTATUS                status;
    HID_XFER_PACKET         packet;
    ULONG                   reportSize;
    PHIDMINI_OUTPUT_REPORT  outputReport;

    KdPrint(("WriteReport\n"));

    status = RequestGetHidXferPacket_ToWriteToDevice(
                            Request,
                            &packet);
    if( !NT_SUCCESS(status) ) {
        return status;
    }

    //
    // HIDAPI test: the device is unnumbered (no Report ID in the descriptor),
    // so hidclass passes report id 0 for every request.
    //
    if (packet.reportId != 0) {
        //
        // Return error for unknown collection
        //
        status = STATUS_INVALID_PARAMETER;
        KdPrint(("WriteReport: unkown report id %d\n", packet.reportId));
        return status;
    }

    //
    // before touching buffer make sure buffer is big enough.
    //
    reportSize = sizeof(HIDMINI_OUTPUT_REPORT);

    if (packet.reportBufferLen < reportSize) {
        status = STATUS_INVALID_BUFFER_SIZE;
        KdPrint(("WriteReport: invalid input buffer. size %d, expect %d\n",
                            packet.reportBufferLen, reportSize));
        return status;
    }

    outputReport = (PHIDMINI_OUTPUT_REPORT)packet.reportBuffer;

    //
    // Store the device data in device extension.
    //
    QueueContext->DeviceContext->DeviceData = outputReport->Data;

    //
    // set status and information
    //
    WdfRequestSetInformation(Request, reportSize);
    return status;
}

HRESULT
GetFeature(
    _In_  PQUEUE_CONTEXT    QueueContext,
    _In_  WDFREQUEST        Request
    )
/*++

Routine Description:

    Handles IOCTL_HID_GET_FEATURE for all the collection.

Arguments:

    QueueContext - The object context associated with the queue

    Request - Pointer to  Request Packet.

Return Value:

    NT status code.

--*/
{
    NTSTATUS                status;
    HID_XFER_PACKET         packet;
    ULONG                   reportSize;
    PMY_DEVICE_ATTRIBUTES   myAttributes;
    PHID_DEVICE_ATTRIBUTES  hidAttributes = &QueueContext->DeviceContext->HidDeviceAttributes;

    KdPrint(("GetFeature\n"));

    status = RequestGetHidXferPacket_ToReadFromDevice(
                            Request,
                            &packet);
    if( !NT_SUCCESS(status) ) {
        return status;
    }

    //
    // HIDAPI test: the device is unnumbered (no Report ID in the descriptor),
    // so hidclass passes report id 0 for every request.
    //
    if (packet.reportId != 0) {
        status = STATUS_INVALID_PARAMETER;
        KdPrint(("GetFeature: invalid report id %d\n", packet.reportId));
        return status;
    }

    //
    // Since output buffer is for write only (no read allowed by UMDF in output
    // buffer), any read from output buffer would be reading garbage), so don't
    // let app embed custom control code in output buffer. The minidriver can
    // support multiple features using separate report ID instead of using
    // custom control code. Since this is targeted at report ID 1, we know it
    // is a request for getting attributes.
    //
    // While KMDF does not enforce the rule (disallow read from output buffer),
    // it is good practice to not do so.
    //

    reportSize = sizeof(MY_DEVICE_ATTRIBUTES) + sizeof(packet.reportId);
    if (packet.reportBufferLen < reportSize) {
        status = STATUS_INVALID_BUFFER_SIZE;
        KdPrint(("GetFeature: output buffer too small. Size %d, expect %d\n",
                            packet.reportBufferLen, reportSize));
        return status;
    }

    //
    // Since this device has one report ID, hidclass would pass on the report
    // ID in the buffer (it wouldn't if report descriptor did not have any report
    // ID). However, since UMDF allows only writes to an output buffer, we can't
    // "read" the report ID from "output" buffer. There is no need to read the
    // report ID since we get it other way as shown above, however this is
    // something to keep in mind.
    //
    myAttributes = (PMY_DEVICE_ATTRIBUTES)(packet.reportBuffer + sizeof(packet.reportId));
    myAttributes->ProductID     = hidAttributes->ProductID;
    myAttributes->VendorID      = hidAttributes->VendorID;
    myAttributes->VersionNumber = hidAttributes->VersionNumber;

    //
    // Report how many bytes were copied
    //
    WdfRequestSetInformation(Request, reportSize);
    return status;
}

NTSTATUS
SetFeature(
    _In_  PQUEUE_CONTEXT    QueueContext,
    _In_  WDFREQUEST        Request
    )
/*++

Routine Description:

    Handles IOCTL_HID_SET_FEATURE for all the collection.
    For control collection (custom defined collection) it handles
    the user-defined control codes for sideband communication

Arguments:

    QueueContext - The object context associated with the queue

    Request - Pointer to Request Packet.

Return Value:

    NT status code.

--*/
{
    NTSTATUS                status;
    WDFMEMORY               inputMemory;
    size_t                  inputLen = 0;
    PUCHAR                  inputBuf;
    size_t                  i;
    size_t                  scan;

    KdPrint(("SetFeature\n"));

    //
    // Read the feature report data directly. We deliberately do NOT use
    // RequestGetHidXferPacket_ToWriteToDevice() here: that helper derives the
    // report id from the request's *output* buffer length, which is 0 for an
    // unnumbered device (report id 0) and makes the retrieval fail. We only
    // need the raw bytes.
    //
    status = WdfRequestRetrieveInputMemory(Request, &inputMemory);
    if (!NT_SUCCESS(status)) {
        return status;
    }
    inputBuf = (PUCHAR)WdfMemoryGetBuffer(inputMemory, &inputLen);

    //
    // HIDAPI test: a Feature report carries a scenario command. Depending on
    // whether the report is prefixed by a report-id byte, the command is in the
    // first couple of bytes; scan for a recognised TEST_VDEV_CMD_* value (the
    // report-id byte is 0 and the commands are non-zero, so this is
    // unambiguous). The matching input report is replayed by the manual-queue
    // timer (EvtTimerFunc).
    //
    scan = inputLen;
    if (scan > 4) {
        scan = 4;
    }
    for (i = 0; i < scan; i++) {
        UCHAR b = inputBuf[i];
        if (b == TEST_VDEV_CMD_EMIT_A || b == TEST_VDEV_CMD_EMIT_B) {
            InterlockedExchange(&QueueContext->DeviceContext->ScenarioCommand, (LONG)b);
            break;
        }
    }

    WdfRequestSetInformation(Request, inputLen);
    return STATUS_SUCCESS;
}

NTSTATUS
GetInputReport(
    _In_  PQUEUE_CONTEXT    QueueContext,
    _In_  WDFREQUEST        Request
    )
/*++

Routine Description:

    Handles IOCTL_HID_GET_INPUT_REPORT for all the collection.

Arguments:

    QueueContext - The object context associated with the queue

    Request - Pointer to Request Packet.

Return Value:

    NT status code.

--*/
{
    NTSTATUS                status;
    HID_XFER_PACKET         packet;
    ULONG                   reportSize;
    PHIDMINI_INPUT_REPORT   reportBuffer;

    KdPrint(("GetInputReport\n"));

    status = RequestGetHidXferPacket_ToReadFromDevice(
                            Request,
                            &packet);
    if( !NT_SUCCESS(status) ) {
        return status;
    }

    //
    // HIDAPI test: the device is unnumbered (no Report ID in the descriptor),
    // so hidclass passes report id 0 for every request.
    //
    if (packet.reportId != 0) {
        status = STATUS_INVALID_PARAMETER;
        KdPrint(("GetInputReport: invalid report id %d\n", packet.reportId));
        return status;
    }

    reportSize = sizeof(HIDMINI_INPUT_REPORT);
    if (packet.reportBufferLen < reportSize) {
        status = STATUS_INVALID_BUFFER_SIZE;
        KdPrint(("GetInputReport: output buffer too small. Size %d, expect %d\n",
                            packet.reportBufferLen, reportSize));
        return status;
    }

    reportBuffer = (PHIDMINI_INPUT_REPORT)(packet.reportBuffer);

    reportBuffer->ReportId = 0; /* unnumbered device */
    reportBuffer->Data     = QueueContext->OutputReport;

    //
    // Report how many bytes were copied
    //
    WdfRequestSetInformation(Request, reportSize);
    return status;
}

