NTSTATUS
GetStringId(
    _In_  WDFREQUEST        Request,
    _Out_ ULONG            *StringId,
    _Out_ ULONG            *LanguageId
    )
/*++

Routine Description:

    Helper routine to decode IOCTL_HID_GET_INDEXED_STRING and IOCTL_HID_GET_STRING.

Arguments:

    Request - Pointer to Request Packet.

Return Value:

    NT status code.

--*/
{
    NTSTATUS                status;
    ULONG                   inputValue;

#ifdef _KERNEL_MODE

    WDF_REQUEST_PARAMETERS  requestParameters;

    //
    // IOCTL_HID_GET_STRING:                      // METHOD_NEITHER
    // IOCTL_HID_GET_INDEXED_STRING:              // METHOD_OUT_DIRECT
    //
    // The string id (or string index) is passed in Parameters.DeviceIoControl.
    // Type3InputBuffer. However, Parameters.DeviceIoControl.InputBufferLength
    // was not initialized by hidclass.sys, therefore trying to access the
    // buffer with WdfRequestRetrieveInputMemory will fail
    //
    // Another problem with IOCTL_HID_GET_INDEXED_STRING is that METHOD_OUT_DIRECT
    // expects the input buffer to be Irp->AssociatedIrp.SystemBuffer instead of
    // Type3InputBuffer. That will also fail WdfRequestRetrieveInputMemory.
    //
    // The solution to the above two problems is to get Type3InputBuffer directly
    //
    // Also note that instead of the buffer's content, it is the buffer address
    // that was used to store the string id (or index)
    //

    WDF_REQUEST_PARAMETERS_INIT(&requestParameters);
    WdfRequestGetParameters(Request, &requestParameters);

    inputValue = PtrToUlong(
        requestParameters.Parameters.DeviceIoControl.Type3InputBuffer);

    status = STATUS_SUCCESS;

#else

    WDFMEMORY               inputMemory;
    size_t                  inputBufferLength;
    PVOID                   inputBuffer;

    //
    // mshidumdf.sys updates the IRP and passes the string id (or index) through
    // the input buffer correctly based on the IOCTL buffer type
    //

    status = WdfRequestRetrieveInputMemory(Request, &inputMemory);
    if( !NT_SUCCESS(status) ) {
        KdPrint(("WdfRequestRetrieveInputMemory failed 0x%x\n",status));
        return status;
    }
    inputBuffer = WdfMemoryGetBuffer(inputMemory, &inputBufferLength);

    //
    // make sure buffer is big enough.
    //
    if (inputBufferLength < sizeof(ULONG))
    {
        status = STATUS_INVALID_BUFFER_SIZE;
        KdPrint(("GetStringId: invalid input buffer. size %d, expect %d\n",
                            (int)inputBufferLength, (int)sizeof(ULONG)));
        return status;
    }

    inputValue = (*(PULONG)inputBuffer);

#endif

    //
    // The least significant two bytes of the INT value contain the string id.
    //
    *StringId = (inputValue & 0x0ffff);

    //
    // The most significant two bytes of the INT value contain the language
    // ID (for example, a value of 1033 indicates English).
    //
    *LanguageId = (inputValue >> 16);

    return status;
}

NTSTATUS
GetIndexedString(
    _In_  WDFREQUEST        Request
    )
/*++

Routine Description:

    Handles IOCTL_HID_GET_INDEXED_STRING

Arguments:

    Request - Pointer to Request Packet.

Return Value:

    NT status code.

--*/
{
    NTSTATUS                status;
    ULONG                   languageId, stringIndex;

    status = GetStringId(Request, &stringIndex, &languageId);

    // While we don't use the language id, some minidrivers might.
    //
    UNREFERENCED_PARAMETER(languageId);

    if (NT_SUCCESS(status)) {

        if (stringIndex != VHIDMINI_DEVICE_STRING_INDEX)
        {
            status = STATUS_INVALID_PARAMETER;
            KdPrint(("GetString: unkown string index %d\n", stringIndex));
            return status;
        }

        status = RequestCopyFromBuffer(Request, VHIDMINI_DEVICE_STRING, sizeof(VHIDMINI_DEVICE_STRING));
    }
    return status;
}

NTSTATUS
GetString(
    _In_  WDFREQUEST        Request
    )
/*++

Routine Description:

    Handles IOCTL_HID_GET_STRING.

Arguments:

    Request - Pointer to Request Packet.

Return Value:

    NT status code.

--*/
{
    NTSTATUS                status;
    ULONG                   languageId, stringId;
    size_t                  stringSizeCb;
    PWSTR                   string;

    status = GetStringId(Request, &stringId, &languageId);

    // While we don't use the language id, some minidrivers might.
    //
    UNREFERENCED_PARAMETER(languageId);

    if (!NT_SUCCESS(status)) {
        return status;
    }

    switch (stringId){
    case HID_STRING_ID_IMANUFACTURER:
        stringSizeCb = sizeof(VHIDMINI_MANUFACTURER_STRING);
        string = VHIDMINI_MANUFACTURER_STRING;
        break;
    case HID_STRING_ID_IPRODUCT:
        stringSizeCb = sizeof(VHIDMINI_PRODUCT_STRING);
        string = VHIDMINI_PRODUCT_STRING;
        break;
    case HID_STRING_ID_ISERIALNUMBER:
        stringSizeCb = sizeof(VHIDMINI_SERIAL_NUMBER_STRING);
        string = VHIDMINI_SERIAL_NUMBER_STRING;
        break;
    default:
        status = STATUS_INVALID_PARAMETER;
        KdPrint(("GetString: unkown string id %d\n", stringId));
        return status;
    }

    status = RequestCopyFromBuffer(Request, string, stringSizeCb);
    return status;
}

NTSTATUS
ManualQueueCreate(
    _In_  WDFDEVICE         Device,
    _Out_ WDFQUEUE          *Queue
    )
/*++
Routine Description:

    This function creates a manual I/O queue to receive IOCTL_HID_READ_REPORT
    forwarded from the device's default queue handler.

    It also creates a periodic timer to check the queue and complete any pending
    request with data from the device. Here timer expiring is used to simulate
    a hardware event that new data is ready.

    The workflow is like this:

    - Hidclass.sys sends an ioctl to the miniport to read input report.

    - The request reaches the driver's default queue. As data may not be avaiable
      yet, the request is forwarded to a second manual queue temporarily.

    - Later when data is ready (as simulated by timer expiring), the driver
      checks for any pending request in the manual queue, and then completes it.

    - Hidclass gets notified for the read request completion and return data to
      the caller.

    On the other hand, for IOCTL_HID_WRITE_REPORT request, the driver simply
    sends the request to the hardware (as simulated by storing the data at
    DeviceContext->DeviceData) and completes the request immediately. There is
    no need to use another queue for write operation.

Arguments:

    Device - Handle to a framework device object.

    Queue - Output pointer to a framework I/O queue handle, on success.

Return Value:

    NTSTATUS

--*/
{
    NTSTATUS                status;
    WDF_IO_QUEUE_CONFIG     queueConfig;
    WDF_OBJECT_ATTRIBUTES   queueAttributes;
    WDFQUEUE                queue;
    PMANUAL_QUEUE_CONTEXT   queueContext;
    WDF_TIMER_CONFIG        timerConfig;
    WDF_OBJECT_ATTRIBUTES   timerAttributes;
    ULONG                   timerPeriodInSeconds = 5;

    WDF_IO_QUEUE_CONFIG_INIT(
                            &queueConfig,
                            WdfIoQueueDispatchManual);

    WDF_OBJECT_ATTRIBUTES_INIT_CONTEXT_TYPE(
                            &queueAttributes,
                            MANUAL_QUEUE_CONTEXT);

    status = WdfIoQueueCreate(
                            Device,
                            &queueConfig,
                            &queueAttributes,
                            &queue);

    if( !NT_SUCCESS(status) ) {
        KdPrint(("WdfIoQueueCreate failed 0x%x\n",status));
        return status;
    }

    queueContext = GetManualQueueContext(queue);
    queueContext->Queue         = queue;
    queueContext->DeviceContext = GetDeviceContext(Device);

    /* HIDAPI test: poll the scenario state often so a triggered input report
       is replayed promptly (well within the test's read timeouts). */
    (void)timerPeriodInSeconds;
    WDF_TIMER_CONFIG_INIT_PERIODIC(
                            &timerConfig,
                            EvtTimerFunc,
                            50 /* ms */);

    WDF_OBJECT_ATTRIBUTES_INIT(&timerAttributes);
    timerAttributes.ParentObject = queue;
    status = WdfTimerCreate(&timerConfig,
                            &timerAttributes,
                            &queueContext->Timer);

    if( !NT_SUCCESS(status) ) {
        KdPrint(("WdfTimerCreate failed 0x%x\n",status));
        return status;
    }

    WdfTimerStart(queueContext->Timer, WDF_REL_TIMEOUT_IN_MS(50));

    *Queue = queue;

    return status;
}

void
EvtTimerFunc(
    _In_  WDFTIMER          Timer
    )
/*++
Routine Description:

    This periodic timer callback routine checks the device's manual queue and
    completes any pending request with data from the device.

Arguments:

    Timer - Handle to a timer object that was obtained from WdfTimerCreate.

Return Value:

    VOID

--*/
{
    NTSTATUS                status;
    WDFQUEUE                queue;
    PMANUAL_QUEUE_CONTEXT   queueContext;
    WDFREQUEST              request;
    LONG                    command;
    const UCHAR            *payload;
    static const UCHAR      inputA[TEST_VDEV_REPORT_SIZE] = { TEST_VDEV_INPUT_A_BYTES };
    static const UCHAR      inputB[TEST_VDEV_REPORT_SIZE] = { TEST_VDEV_INPUT_B_BYTES };

    queue = (WDFQUEUE)WdfTimerGetParentObject(Timer);
    queueContext = GetManualQueueContext(queue);

    //
    // HIDAPI test: only deliver an input report when a scenario has been
    // triggered via SetFeature. Otherwise leave pended reads alone, so that a
    // blocking hid_read() genuinely blocks until hid_read_interrupt() cancels
    // it (the read-interrupt tests rely on the device being silent).
    //
    command = InterlockedExchange(&queueContext->DeviceContext->ScenarioCommand, 0);
    if (command == 0) {
        return;
    }

    status = WdfIoQueueRetrieveNextRequest(queueContext->Queue, &request);
    if (!NT_SUCCESS(status)) {
        //
        // The read hasn't been pended yet; re-arm the command so a later timer
        // tick retries once hid_read() has issued the request.
        //
        InterlockedExchange(&queueContext->DeviceContext->ScenarioCommand, command);
        return;
    }

    /* Deliver the raw report bytes (no report-id prefix: the device is
       unnumbered, so the report on the wire is just the payload). hidclass
       frames it for user mode; HIDAPI returns exactly these bytes. */
    payload = (command == TEST_VDEV_CMD_EMIT_B) ? inputB : inputA;
    status = RequestCopyFromBuffer(request, (PVOID)payload, TEST_VDEV_REPORT_SIZE);
    WdfRequestComplete(request, status);
}

NTSTATUS
CheckRegistryForDescriptor(
        WDFDEVICE Device
        )
/*++

Routine Description:

    Read "ReadFromRegistry" key value from device parameters in the registry.

Arguments:

    device - pointer to a device object.

Return Value:

    NT status code.

--*/

{
    WDFKEY          hKey = NULL;
    NTSTATUS        status;
    UNICODE_STRING  valueName;
    ULONG           value;

    status = WdfDeviceOpenRegistryKey(Device,
                                  PLUGPLAY_REGKEY_DEVICE,
                                  KEY_READ,
                                  WDF_NO_OBJECT_ATTRIBUTES,
                                  &hKey);
    if (NT_SUCCESS(status)) {

        RtlInitUnicodeString(&valueName, L"ReadFromRegistry");

        status = WdfRegistryQueryULong (hKey,
                                  &valueName,
                                  &value);

        if (NT_SUCCESS (status)) {
            if (value == 0) {
                status = STATUS_UNSUCCESSFUL;
            }
        }

        WdfRegistryClose(hKey);
    }

    return status;
}

NTSTATUS
ReadDescriptorFromRegistry(
        WDFDEVICE Device
        )
/*++

Routine Description:

    Read HID report descriptor from registry

Arguments:

    device - pointer to a device object.

Return Value:

    NT status code.

--*/
{
    WDFKEY          hKey = NULL;
    NTSTATUS        status;
    UNICODE_STRING  valueName;
    WDFMEMORY       memory;
    size_t          bufferSize;
    PVOID           reportDescriptor;
    PDEVICE_CONTEXT deviceContext;
    WDF_OBJECT_ATTRIBUTES   attributes;

    deviceContext = GetDeviceContext(Device);

    status = WdfDeviceOpenRegistryKey(Device,
                                  PLUGPLAY_REGKEY_DEVICE,
                                  KEY_READ,
                                  WDF_NO_OBJECT_ATTRIBUTES,
                                  &hKey);

    if (NT_SUCCESS(status)) {

        RtlInitUnicodeString(&valueName, L"MyReportDescriptor");

        WDF_OBJECT_ATTRIBUTES_INIT(&attributes);
        attributes.ParentObject = Device;

        status = WdfRegistryQueryMemory (hKey,
                                  &valueName,
                                  NonPagedPool,
                                  &attributes,
                                  &memory,
                                  NULL);

        if (NT_SUCCESS (status)) {

            reportDescriptor = WdfMemoryGetBuffer(memory, &bufferSize);

            KdPrint(("No. of report descriptor bytes copied: %d\n", (INT) bufferSize));

            //
            // Store the registry report descriptor in the device extension
            //
            deviceContext->ReadReportDescFromRegistry = TRUE;
            deviceContext->ReportDescriptor = reportDescriptor;
            deviceContext->HidDescriptor.DescriptorList[0].wReportLength = (USHORT)bufferSize;
        }

        WdfRegistryClose(hKey);
    }

    return status;
}

char *module_source_ext(char *filename) {
    if (ends_with(filename, SOURCE_EXT_N)) {
        return SOURCE_EXT_N;
    }
    if (ends_with(filename, SOURCE_EXT_X)) {
        return SOURCE_EXT_X;
    }
    return NULL;
}

static void scan_windows_context_roots(rt_linked_fixalloc_t *worklist,
                                       const aco_t *aco) {
    for (int i = ACO_REG_IDX_GP_NONVOL_FIRST;
         i <= ACO_REG_IDX_GP_NONVOL_LAST; ++i) {
        addr_t value = (addr_t) aco->reg[i];
        if (span_of(value)) {
            insert_gc_worklist(worklist, (void *) value);
        }
    }
}

static void scan_saved_stack_conservative(rt_linked_fixalloc_t *worklist,
                                          const aco_save_stack_t *save_stack) {
    if (!save_stack->ptr || save_stack->valid_sz == 0) {
        return;
    }

    size_t size = save_stack->valid_sz;
    if (size > save_stack->sz) {
        size = save_stack->sz;
    }

    addr_t stack_top_ptr = (addr_t) save_stack->ptr;
    for (size_t offset = 0; offset + POINTER_SIZE <= size;
         offset += POINTER_SIZE) {
        addr_t value = fetch_addr_value(stack_top_ptr + offset);
        if (span_of(value)) {
            insert_gc_worklist(worklist, (void *) value);
        }
    }
}

static ssize_t windows_pwrite(int fd, const void *buf, size_t len, int64_t offset) {
    if (offset < 0) {
        return _write(fd, buf, (unsigned int) len);
    }

    __int64 original_offset = _lseeki64(fd, 0, SEEK_CUR);
    if (original_offset < 0 || _lseeki64(fd, offset, SEEK_SET) < 0) {
        return -1;
    }

    int result = _write(fd, buf, (unsigned int) len);
    int saved_errno = errno;
    (void) _lseeki64(fd, original_offset, SEEK_SET);
    errno = saved_errno;
    return result;
}

static ssize_t windows_pread(int fd, void *buf, size_t len, int64_t offset) {
    if (offset < 0) {
        return _read(fd, buf, (unsigned int) len);
    }

    __int64 original_offset = _lseeki64(fd, 0, SEEK_CUR);
    if (original_offset < 0 || _lseeki64(fd, offset, SEEK_SET) < 0) {
        return -1;
    }

    int result = _read(fd, buf, (unsigned int) len);
    int saved_errno = errno;
    (void) _lseeki64(fd, original_offset, SEEK_SET);
    errno = saved_errno;
    return result;
}

static inline void http_conn_close(http_conn_t *conn) {
    uv_handle_t *handle = (uv_handle_t *) &conn->handle;
    if (uv_is_closing(handle)) {
        return;
    }

    uv_read_stop((uv_stream_t *) &conn->handle);
    uv_close(handle, on_conn_close_cb);
}

static void rt_windows_write_crash_line(const char *line) {
    HANDLE error = GetStdHandle(STD_ERROR_HANDLE);
    if (error == NULL || error == INVALID_HANDLE_VALUE) return;
    DWORD written = 0;
    (void) WriteFile(error, line, (DWORD) strlen(line), &written, NULL);
}

static fndef_t *rt_windows_find_crash_fn(DWORD64 pc) {
    if (!rt_fndef_ptr || !rt_strtable_ptr) return NULL;
    for (uint64_t i = 0; i < rt_fndef_count; ++i) {
        fndef_t *fn = &rt_fndef_ptr[i];
        if (fn->base <= pc && pc < fn->base + fn->size) return fn;
    }
    return NULL;
}

static void rt_windows_write_crash_frame(unsigned frame_index, DWORD64 pc) {
    char line[512];
    DWORD64 image_base = (DWORD64) (uintptr_t) GetModuleHandleW(NULL);
    DWORD64 rva = pc >= image_base ? pc - image_base : pc;
    fndef_t *fn = rt_windows_find_crash_fn(pc);
    if (fn) {
        snprintf(line, sizeof(line),
                 "  #%u %s+0x%llx [0x%llx, image+0x%llx]\n",
                 frame_index, STRTABLE(fn->name_offset),
                 (unsigned long long) (pc - fn->base),
                 (unsigned long long) pc, (unsigned long long) rva);
    } else {
        snprintf(line, sizeof(line),
                 "  #%u <native> [0x%llx, image+0x%llx]\n", frame_index,
                 (unsigned long long) pc, (unsigned long long) rva);
    }
    rt_windows_write_crash_line(line);
}

static void rt_windows_report_exception(EXCEPTION_POINTERS *exception) {
    if (!exception || !exception->ExceptionRecord ||
        !exception->ContextRecord ||
        InterlockedCompareExchange(&rt_windows_reporting_exception, 1, 0) !=
                0)
        return;

    EXCEPTION_RECORD *record = exception->ExceptionRecord;
    CONTEXT context = *exception->ContextRecord;
    char line[512];
    snprintf(line, sizeof(line),
             "nature: unhandled Windows exception 0x%08lx at 0x%llx\n",
             (unsigned long) record->ExceptionCode,
             (unsigned long long) (uintptr_t) record->ExceptionAddress);
    rt_windows_write_crash_line(line);

    if (record->ExceptionCode == EXCEPTION_ACCESS_VIOLATION &&
        record->NumberParameters >= 2) {
        const char *operation = "read";
        if (record->ExceptionInformation[0] == 1) operation = "write";
        if (record->ExceptionInformation[0] == 8) operation = "execute";
        snprintf(line, sizeof(line), "nature: invalid %s at 0x%llx\n",
                 operation,
                 (unsigned long long) record->ExceptionInformation[1]);
        rt_windows_write_crash_line(line);
    }

#ifdef __x86_64__
    snprintf(line, sizeof(line),
             "nature: rip=0x%llx rsp=0x%llx rbp=0x%llx\n",
             (unsigned long long) context.Rip,
             (unsigned long long) context.Rsp,
             (unsigned long long) context.Rbp);
    rt_windows_write_crash_line(line);
    rt_windows_write_crash_line("nature: stack backtrace:\n");

    HANDLE process = GetCurrentProcess();
    for (unsigned i = 0; i < 64 && context.Rip != 0; ++i) {
        DWORD64 pc = context.Rip;
        DWORD64 rsp = context.Rsp;
        rt_windows_write_crash_frame(i, pc);

        DWORD64 image_base = 0;
        PRUNTIME_FUNCTION function =
                RtlLookupFunctionEntry(pc, &image_base, NULL);
        if (function) {
            PVOID handler_data = NULL;
            DWORD64 establisher_frame = 0;
            RtlVirtualUnwind(UNW_FLAG_NHANDLER, image_base, pc, function,
                             &context, &handler_data, &establisher_frame,
                             NULL);
        } else {
            DWORD64 return_address = 0;
            SIZE_T bytes_read = 0;
            if (!ReadProcessMemory(process, (const void *) (uintptr_t) rsp,
                                   &return_address, sizeof(return_address),
                                   &bytes_read) ||
                bytes_read != sizeof(return_address)) {
                break;
            }
            context.Rip = return_address;
            context.Rsp = rsp + sizeof(return_address);
        }
        if ((context.Rip == pc && context.Rsp == rsp) || context.Rsp < rsp)
            break;
    }
#endif
}

static LONG WINAPI
rt_windows_unhandled_exception_filter(EXCEPTION_POINTERS *exception) {
    rt_windows_report_exception(exception);
    return EXCEPTION_EXECUTE_HANDLER;
}

void rt_dump_stack_backtrace(void) {
#ifdef __WINDOWS
    enum { MAX_BACKTRACE_FRAMES = 64 };
    void *frames[MAX_BACKTRACE_FRAMES] = {0};
    unsigned short frame_count = RtlCaptureStackBackTrace(
            1, MAX_BACKTRACE_FRAMES, frames, NULL);
    if (frame_count == 0) return;

    char *line = "stack backtrace:\n";
    VOID write(STDOUT_FILENO, line, strlen(line));
    n_processor_t *processor = processor_get();
    for (unsigned short i = 0; i < frame_count; ++i) {
        addr_t pc = (addr_t) frames[i];
        fndef_t *fn = processor ? find_fn(pc, processor) : NULL;
        if (fn) {
            line = tlsprintf(
                    "%u:\t%s+0x%llx [0x%llx]\n\t\tat %s:%llu:%llu\n",
                    (unsigned) i, STRTABLE(fn->name_offset),
                    (unsigned long long) (pc - fn->base),
                    (unsigned long long) pc, STRTABLE(fn->relpath_offset),
                    (unsigned long long) fn->line,
                    (unsigned long long) fn->column);
        } else {
            line = tlsprintf("%u:\t<native> [0x%llx]\n", (unsigned) i,
                             (unsigned long long) pc);
        }
        VOID write(STDOUT_FILENO, line, strlen(line));
    }
#endif
}

static caller_t *caller_from_return_address(addr_t ret_addr) {
    caller_t *caller = sc_map_get_64v(&rt_caller_map, ret_addr);
    if (caller) return caller;
    if (!rt_caller_ptr) return NULL;

    for (uint64_t i = 0; i < rt_caller_count; ++i) {
        if (rt_caller_ptr[i].offset == ret_addr) return &rt_caller_ptr[i];
    }
    return NULL;
}

int getppid(void) {
    DWORD current_pid = GetCurrentProcessId();
    HANDLE snapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snapshot == INVALID_HANDLE_VALUE) {
        errno = ESRCH;
        return -1;
    }

    PROCESSENTRY32W entry = {0};
    entry.dwSize = sizeof(entry);
    int parent_pid = -1;
    if (Process32FirstW(snapshot, &entry)) {
        do {
            if (entry.th32ProcessID == current_pid) {
                parent_pid = (int) entry.th32ParentProcessID;
                break;
            }
        } while (Process32NextW(snapshot, &entry));
    }
    CloseHandle(snapshot);
    if (parent_pid <= 0) errno = ESRCH;
    return parent_pid;
}

static int rt_windows_validate_env_name(const char *name) {
    if (!name || name[0] == '\0' || strchr(name, '=') != NULL) {
        errno = EINVAL;
        return -1;
    }
    return 0;
}

int setenv(const char *name, const char *value, int overwrite) {
    if (rt_windows_validate_env_name(name) != 0 || !value) {
        errno = EINVAL;
        return -1;
    }
    if (!overwrite && getenv(name) != NULL) return 0;

    errno_t error = _putenv_s(name, value);
    if (error != 0) {
        errno = error;
        return -1;
    }
    return 0;
}

int unsetenv(const char *name) {
    if (rt_windows_validate_env_name(name) != 0) return -1;

    errno_t error = _putenv_s(name, "");
    if (error != 0) {
        errno = error;
        return -1;
    }
    return 0;
}

static void rt_windows_copy_tm(rt_windows_tm_t *destination,
                               const struct tm *source, int64_t gmtoff,
                               const char *zone) {
    destination->tm_sec = source->tm_sec;
    destination->tm_min = source->tm_min;
    destination->tm_hour = source->tm_hour;
    destination->tm_mday = source->tm_mday;
    destination->tm_mon = source->tm_mon;
    destination->tm_year = source->tm_year;
    destination->tm_wday = source->tm_wday;
    destination->tm_yday = source->tm_yday;
    destination->tm_isdst = source->tm_isdst;
    destination->tm_gmtoff = gmtoff;
    destination->tm_zone = zone;
}

static int64_t rt_windows_days_from_civil(int64_t year, unsigned month,
                                          unsigned day) {
    year -= month <= 2;
    int64_t era = (year >= 0 ? year : year - 399) / 400;
    unsigned year_of_era = (unsigned) (year - era * 400);
    unsigned shifted_month = month > 2 ? month - 3 : month + 9;
    unsigned day_of_year = (153 * shifted_month + 2) / 5 + day - 1;
    unsigned day_of_era = year_of_era * 365 + year_of_era / 4 -
                          year_of_era / 100 + day_of_year;
    return era * 146097 + (int64_t) day_of_era - 719468;
}

static int64_t rt_windows_tm_as_utc_seconds(const struct tm *value) {
    int64_t days = rt_windows_days_from_civil(
            (int64_t) value->tm_year + 1900, (unsigned) value->tm_mon + 1,
            (unsigned) value->tm_mday);
    return days * 86400 + (int64_t) value->tm_hour * 3600 +
           (int64_t) value->tm_min * 60 + value->tm_sec;
}

rt_windows_tm_t *rt_windows_gmtime(const int64_t *timestamp) {
    if (!timestamp) return NULL;
    time_t native_timestamp = (time_t) *timestamp;
    struct tm *value = gmtime(&native_timestamp);
    if (!value) return NULL;
    rt_windows_copy_tm(&rt_windows_gmtime_result, value, 0, "UTC");
    return &rt_windows_gmtime_result;
}

rt_windows_tm_t *rt_windows_localtime(const int64_t *timestamp) {
    if (!timestamp) return NULL;
    time_t native_timestamp = (time_t) *timestamp;
    struct tm *value = localtime(&native_timestamp);
    if (!value) return NULL;

    int64_t gmtoff = rt_windows_tm_as_utc_seconds(value) - *timestamp;
    rt_windows_copy_tm(&rt_windows_localtime_result, value, gmtoff, "LOCAL");
    return &rt_windows_localtime_result;
}

int clock_gettime(int clock_id, rt_windows_timespec_t *result) {
    if (!result || !rt_windows_clock_supported(clock_id)) {
        errno = EINVAL;
        return -1;
    }

    if (clock_id == RT_CLOCK_REALTIME) {
        rt_windows_filetime_t filetime;
        GetSystemTimePreciseAsFileTime(&filetime);
        uint64_t ticks = ((uint64_t) filetime.high << 32U) | filetime.low;
        ticks -= UINT64_C(116444736000000000);
        result->tv_sec = (int64_t) (ticks / UINT64_C(10000000));
        result->tv_nsec =
                (int64_t) ((ticks % UINT64_C(10000000)) * UINT64_C(100));
        return 0;
    }

    int64_t counter;
    int64_t frequency;
    if (!QueryPerformanceCounter(&counter) ||
        !QueryPerformanceFrequency(&frequency) || frequency <= 0) {
        errno = EINVAL;
        return -1;
    }
    result->tv_sec = counter / frequency;
    result->tv_nsec = (int64_t) (((uint64_t) (counter % frequency) *
                                  UINT64_C(1000000000)) /
                                 (uint64_t) frequency);
    return 0;
}

int clock_getres(int clock_id, rt_windows_timespec_t *result) {
    if (!result || !rt_windows_clock_supported(clock_id)) {
        errno = EINVAL;
        return -1;
    }

    result->tv_sec = 0;
    if (clock_id == RT_CLOCK_REALTIME) {
        result->tv_nsec = 100;
        return 0;
    }

    int64_t frequency;
    if (!QueryPerformanceFrequency(&frequency) || frequency <= 0) {
        errno = EINVAL;
        return -1;
    }
    result->tv_nsec = (int64_t) ((UINT64_C(1000000000) +
                                  (uint64_t) frequency - 1U) /
                                 (uint64_t) frequency);
    if (result->tv_nsec == 0) result->tv_nsec = 1;
    return 0;
}

static wchar_t *rt_windows_utf8_to_utf16(const char *input) {
    if (!input) {
        errno = EINVAL;
        SetLastError(ERROR_INVALID_PARAMETER);
        return NULL;
    }

    int length = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, input, -1,
                                     NULL, 0);
    if (length <= 0) {
        rt_windows_set_conversion_error();
        return NULL;
    }
    if ((size_t) length > SIZE_MAX / sizeof(wchar_t)) {
        errno = ENOMEM;
        SetLastError(ERROR_NOT_ENOUGH_MEMORY);
        return NULL;
    }

    wchar_t *result = malloc((size_t) length * sizeof(wchar_t));
    if (!result) {
        errno = ENOMEM;
        SetLastError(ERROR_NOT_ENOUGH_MEMORY);
        return NULL;
    }
    if (MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, input, -1, result,
                            length) != length) {
        free(result);
        rt_windows_set_conversion_error();
        return NULL;
    }
    return result;
}

static int64_t rt_windows_utf16_to_utf8(const wchar_t *input, int length,
                                        char *output, size_t capacity) {
    if (!input || !output || capacity == 0U || capacity > INT_MAX) {
        errno = EINVAL;
        SetLastError(ERROR_INVALID_PARAMETER);
        return -1;
    }

    const bool nul_terminated = length < 0;
    int required = WideCharToMultiByte(CP_UTF8, WC_ERR_INVALID_CHARS, input,
                                       length, NULL, 0, NULL, NULL);
    if (required <= 0) {
        rt_windows_set_conversion_error();
        return -1;
    }
    if ((nul_terminated && (size_t) required > capacity) ||
        (!nul_terminated && (size_t) required >= capacity)) {
        errno = ERANGE;
        SetLastError(ERROR_INSUFFICIENT_BUFFER);
        return -1;
    }
    if (WideCharToMultiByte(CP_UTF8, WC_ERR_INVALID_CHARS, input, length,
                            output, (int) capacity, NULL, NULL) != required) {
        rt_windows_set_conversion_error();
        return -1;
    }
    if (nul_terminated) return required - 1;
    output[required] = '\0';
    return required;
}

int32_t rt_windows_open_mode(int32_t mode) {
    int32_t windows_mode = 0;
    if ((mode & 0444) != 0) windows_mode |= _S_IREAD;
    if ((mode & 0222) != 0) windows_mode |= _S_IWRITE;
    return windows_mode;
}

int32_t rt_windows_open_utf8(const char *path, int32_t flags, int32_t mode) {
    wchar_t *wide = rt_windows_utf8_to_utf16(path);
    if (!wide) return -1;
    int result = _wopen(wide, flags | _O_BINARY,
                        rt_windows_open_mode(mode));
    free(wide);
    return result;
}

int32_t rt_windows_stat_utf8(const char *path, void *result) {
    if (!result) {
        errno = EINVAL;
        return -1;
    }
    wchar_t *wide = rt_windows_utf8_to_utf16(path);
    if (!wide) return -1;
    int status = _wstat64(wide, (struct _stat64 *) result);
    free(wide);
    return status;
}

int32_t rt_windows_mkdir_utf8(const char *path) {
    wchar_t *wide = rt_windows_utf8_to_utf16(path);
    if (!wide) return -1;
    int status = _wmkdir(wide);
    free(wide);
    return status;
}

int32_t rt_windows_rmdir_utf8(const char *path) {
    wchar_t *wide = rt_windows_utf8_to_utf16(path);
    if (!wide) return -1;
    int status = _wrmdir(wide);
    free(wide);
    return status;
}

int32_t rt_windows_unlink_utf8(const char *path) {
    wchar_t *wide = rt_windows_utf8_to_utf16(path);
    if (!wide) return -1;
    int status = _wunlink(wide);
    free(wide);
    return status;
}

int32_t rt_windows_rename_utf8(const char *old_path, const char *new_path) {
    wchar_t *wide_old = rt_windows_utf8_to_utf16(old_path);
    if (!wide_old) return -1;
    wchar_t *wide_new = rt_windows_utf8_to_utf16(new_path);
    if (!wide_new) {
        free(wide_old);
        return -1;
    }
    int status = _wrename(wide_old, wide_new);
    free(wide_new);
    free(wide_old);
    return status;
}

int32_t rt_windows_chmod_utf8(const char *path, int32_t mode) {
    wchar_t *wide = rt_windows_utf8_to_utf16(path);
    if (!wide) return -1;
    int status = _wchmod(wide, rt_windows_open_mode(mode));
    free(wide);
    return status;
}

int32_t rt_windows_chdir_utf8(const char *path) {
    wchar_t *wide = rt_windows_utf8_to_utf16(path);
    if (!wide) return -1;
    int status = _wchdir(wide);
    free(wide);
    return status;
}

int64_t rt_windows_getcwd_utf8(char *output, size_t capacity) {
    DWORD required = GetCurrentDirectoryW(0, NULL);
    if (required == 0U) return -1;
    if ((size_t) required > SIZE_MAX / sizeof(wchar_t)) {
        errno = ENOMEM;
        SetLastError(ERROR_NOT_ENOUGH_MEMORY);
        return -1;
    }

    wchar_t *wide = malloc((size_t) required * sizeof(wchar_t));
    if (!wide) {
        errno = ENOMEM;
        SetLastError(ERROR_NOT_ENOUGH_MEMORY);
        return -1;
    }
    DWORD length = GetCurrentDirectoryW(required, wide);
    if (length == 0U || length >= required) {
        free(wide);
        return -1;
    }
    int64_t result =
            rt_windows_utf16_to_utf8(wide, (int) length, output, capacity);
    free(wide);
    return result;
}

static int64_t rt_windows_module_filename_utf8(char *output,
                                               size_t capacity) {
    DWORD wide_capacity = 512U;
    while (wide_capacity <= 32768U) {
        wchar_t *wide = malloc((size_t) wide_capacity * sizeof(wchar_t));
        if (!wide) {
            errno = ENOMEM;
            SetLastError(ERROR_NOT_ENOUGH_MEMORY);
            return -1;
        }
        SetLastError(ERROR_SUCCESS);
        DWORD length = GetModuleFileNameW(NULL, wide, wide_capacity);
        DWORD error = GetLastError();
        if (length == 0U) {
            free(wide);
            return -1;
        }
        if (length < wide_capacity && error != ERROR_INSUFFICIENT_BUFFER) {
            int64_t result = rt_windows_utf16_to_utf8(
                    wide, (int) length, output, capacity);
            free(wide);
            return result;
        }
        free(wide);
        wide_capacity *= 2U;
    }
    errno = ERANGE;
    SetLastError(ERROR_INSUFFICIENT_BUFFER);
    return -1;
}

static int64_t rt_windows_final_path_utf8(const char *path, char *output,
                                          size_t capacity) {
    wchar_t *wide_path = rt_windows_utf8_to_utf16(path);
    if (!wide_path) return -1;

    HANDLE handle = CreateFileW(wide_path, 0,
                                FILE_SHARE_READ | FILE_SHARE_WRITE |
                                        FILE_SHARE_DELETE,
                                NULL, OPEN_EXISTING,
                                FILE_FLAG_BACKUP_SEMANTICS, NULL);
    free(wide_path);
    if (handle == INVALID_HANDLE_VALUE) return -1;

    DWORD required = GetFinalPathNameByHandleW(handle, NULL, 0, 0);
    if (required == 0U || required == UINT32_MAX ||
        (size_t) required + 1U > SIZE_MAX / sizeof(wchar_t)) {
        DWORD error = GetLastError();
        CloseHandle(handle);
        SetLastError(error);
        return -1;
    }
    wchar_t *wide = malloc(((size_t) required + 1U) * sizeof(wchar_t));
    if (!wide) {
        CloseHandle(handle);
        errno = ENOMEM;
        SetLastError(ERROR_NOT_ENOUGH_MEMORY);
        return -1;
    }
    DWORD length = GetFinalPathNameByHandleW(handle, wide, required + 1U, 0);
    DWORD error = GetLastError();
    CloseHandle(handle);
    if (length == 0U || length > required) {
        free(wide);
        SetLastError(error);
        return -1;
    }

    const wchar_t *normalized = wide;
    DWORD normalized_length = length;
    wchar_t *unc = NULL;
    if (length >= 8U && wcsncmp(wide, L"\\\\?\\UNC\\", 8U) == 0) {
        normalized_length = length - 6U;
        unc = malloc(((size_t) normalized_length + 1U) * sizeof(wchar_t));
        if (!unc) {
            free(wide);
            errno = ENOMEM;
            SetLastError(ERROR_NOT_ENOUGH_MEMORY);
            return -1;
        }
        unc[0] = L'\\';
        unc[1] = L'\\';
        memcpy(unc + 2U, wide + 8U,
               ((size_t) length - 8U) * sizeof(wchar_t));
        unc[normalized_length] = L'\0';
        normalized = unc;
    } else if (length >= 4U && wcsncmp(wide, L"\\\\?\\", 4U) == 0) {
        normalized = wide + 4U;
        normalized_length = length - 4U;
    }

    int64_t result = rt_windows_utf16_to_utf8(
            normalized, (int) normalized_length, output, capacity);
    free(unc);
    free(wide);
    return result;
}

int64_t rt_windows_readlink_utf8(const char *path, char *output,
                                 size_t capacity) {
    if (path && strcmp(path, "/proc/self/exe") == 0)
        return rt_windows_module_filename_utf8(output, capacity);
    return rt_windows_final_path_utf8(path, output, capacity);
}

int64_t rt_windows_get_env_utf8(const char *key, char *output,
                                size_t capacity) {
    if (!output || capacity == 0U) {
        errno = EINVAL;
        SetLastError(ERROR_INVALID_PARAMETER);
        return -1;
    }
    output[0] = '\0';
    wchar_t *wide_key = rt_windows_utf8_to_utf16(key);
    if (!wide_key) return -1;

    SetLastError(ERROR_SUCCESS);
    DWORD required = GetEnvironmentVariableW(wide_key, NULL, 0);
    DWORD error = GetLastError();
    if (required == 0U) {
        free(wide_key);
        if (error == ERROR_SUCCESS || error == ERROR_ENVVAR_NOT_FOUND) return 0;
        SetLastError(error);
        return -1;
    }
    if ((size_t) required > SIZE_MAX / sizeof(wchar_t)) {
        free(wide_key);
        errno = ENOMEM;
        SetLastError(ERROR_NOT_ENOUGH_MEMORY);
        return -1;
    }

    wchar_t *wide_value = malloc((size_t) required * sizeof(wchar_t));
    if (!wide_value) {
        free(wide_key);
        errno = ENOMEM;
        SetLastError(ERROR_NOT_ENOUGH_MEMORY);
        return -1;
    }
    DWORD length =
            GetEnvironmentVariableW(wide_key, wide_value, required);
    error = GetLastError();
    free(wide_key);
    if (length >= required) {
        free(wide_value);
        SetLastError(error == ERROR_SUCCESS ? ERROR_INSUFFICIENT_BUFFER : error);
        return -1;
    }
    int64_t result = rt_windows_utf16_to_utf8(
            wide_value, (int) length, output, capacity);
    free(wide_value);
    return result;
}

int32_t rt_windows_set_env_utf8(const char *key, const char *value) {
    wchar_t *wide_key = rt_windows_utf8_to_utf16(key);
    if (!wide_key) return 0;
    wchar_t *wide_value = rt_windows_utf8_to_utf16(value);
    if (!wide_value) {
        free(wide_key);
        return 0;
    }
    BOOL result = SetEnvironmentVariableW(wide_key, wide_value);
    free(wide_value);
    free(wide_key);
    return result != FALSE;
}

static int32_t rt_windows_env_entry(rt_windows_env_iterator_t *iterator,
                                    char *entry, size_t capacity) {
    return rt_windows_utf16_to_utf8(iterator->current, -1, entry, capacity) <
                           0
                   ? -1
                   : 1;
}

void *rt_windows_env_first_utf8(char *entry, size_t capacity) {
    rt_windows_env_iterator_t *iterator = calloc(1U, sizeof(*iterator));
    if (!iterator) {
        errno = ENOMEM;
        SetLastError(ERROR_NOT_ENOUGH_MEMORY);
        return NULL;
    }
    iterator->block = GetEnvironmentStringsW();
    if (!iterator->block) {
        free(iterator);
        return NULL;
    }
    iterator->current = iterator->block;
    if (*iterator->current == L'\0' ||
        rt_windows_env_entry(iterator, entry, capacity) < 0) {
        DWORD error = GetLastError();
        FreeEnvironmentStringsW(iterator->block);
        free(iterator);
        SetLastError(error);
        return NULL;
    }
    return iterator;
}

int32_t rt_windows_env_next_utf8(void *iterator_value, char *entry,
                                 size_t capacity) {
    rt_windows_env_iterator_t *iterator = iterator_value;
    if (!iterator || !iterator->current) {
        errno = EINVAL;
        SetLastError(ERROR_INVALID_PARAMETER);
        return -1;
    }
    iterator->current += wcslen(iterator->current) + 1U;
    if (*iterator->current == L'\0') return 0;
    return rt_windows_env_entry(iterator, entry, capacity);
}

int32_t rt_windows_env_close_utf8(void *iterator_value) {
    rt_windows_env_iterator_t *iterator = iterator_value;
    if (!iterator) {
        errno = EINVAL;
        SetLastError(ERROR_INVALID_PARAMETER);
        return 0;
    }
    BOOL released = FreeEnvironmentStringsW(iterator->block);
    free(iterator);
    return released != FALSE;
}

static int32_t rt_windows_find_name(rt_windows_find_iterator_t *iterator,
                                    char *name, size_t capacity) {
    int64_t length = rt_windows_utf16_to_utf8(iterator->data.cFileName, -1,
                                              name, capacity);
    if (length < 0) return -1;
    return 1;
}

void *rt_windows_find_first_utf8(const char *pattern, char *name,
                                 size_t capacity) {
    wchar_t *wide = rt_windows_utf8_to_utf16(pattern);
    if (!wide) return NULL;
    rt_windows_find_iterator_t *iterator = calloc(1U, sizeof(*iterator));
    if (!iterator) {
        free(wide);
        errno = ENOMEM;
        SetLastError(ERROR_NOT_ENOUGH_MEMORY);
        return NULL;
    }
    iterator->handle = FindFirstFileW(wide, &iterator->data);
    free(wide);
    if (iterator->handle == INVALID_HANDLE_VALUE) {
        free(iterator);
        return NULL;
    }
    if (rt_windows_find_name(iterator, name, capacity) < 0) {
        DWORD error = GetLastError();
        FindClose(iterator->handle);
        free(iterator);
        SetLastError(error);
        return NULL;
    }
    return iterator;
}

int32_t rt_windows_find_next_utf8(void *iterator_value, char *name,
                                  size_t capacity) {
    rt_windows_find_iterator_t *iterator = iterator_value;
    if (!iterator) {
        errno = EINVAL;
        SetLastError(ERROR_INVALID_PARAMETER);
        return -1;
    }
    if (!FindNextFileW(iterator->handle, &iterator->data)) {
        return GetLastError() == ERROR_NO_MORE_FILES ? 0 : -1;
    }
    return rt_windows_find_name(iterator, name, capacity);
}

int32_t rt_windows_find_close_utf8(void *iterator_value) {
    rt_windows_find_iterator_t *iterator = iterator_value;
    if (!iterator) {
        errno = EINVAL;
        SetLastError(ERROR_INVALID_PARAMETER);
        return 0;
    }
    BOOL closed = FindClose(iterator->handle);
    free(iterator);
    return closed != FALSE;
}

static void windows_free_utf8_argv(char **argv, int argc) {
    if (argv == NULL) {
        return;
    }
    for (int i = 0; i < argc; ++i) {
        free(argv[i]);
    }
    free(argv);
}

static char **windows_utf8_argv(int *argc_out) {
    int wide_argc = 0;
    wchar_t **wide_argv = CommandLineToArgvW(GetCommandLineW(), &wide_argc);
    if (wide_argv == NULL || wide_argc < 0) {
        return NULL;
    }

    char **utf8_argv = calloc((size_t) wide_argc + 1U, sizeof(char *));
    if (utf8_argv == NULL) {
        LocalFree(wide_argv);
        return NULL;
    }

    for (int i = 0; i < wide_argc; ++i) {
        int bytes = WideCharToMultiByte(CP_UTF8, 0, wide_argv[i], -1, NULL,
                                        0, NULL, NULL);
        if (bytes <= 0) {
            windows_free_utf8_argv(utf8_argv, i);
            LocalFree(wide_argv);
            return NULL;
        }
        utf8_argv[i] = malloc((size_t) bytes);
        if (utf8_argv[i] == NULL ||
            WideCharToMultiByte(CP_UTF8, 0, wide_argv[i], -1, utf8_argv[i],
                                bytes, NULL, NULL) != bytes) {
            windows_free_utf8_argv(utf8_argv, i + 1);
            LocalFree(wide_argv);
            return NULL;
        }
    }

    LocalFree(wide_argv);
    *argc_out = wide_argc;
    return utf8_argv;
}

int main(int argc, char *argv[]) {
    rt_install_windows_exception_handler();

    int utf8_argc = 0;
    char **utf8_argv = windows_utf8_argv(&utf8_argc);
    if (utf8_argv == NULL) {
        return runtime_main(argc, argv);
    }

    int status = runtime_main(utf8_argc, utf8_argv);
    windows_free_utf8_argv(utf8_argv, utf8_argc);
    return status;
}

static coff_writer_status_t coff_amd64_fail(
        coff_amd64_context_t *context, coff_writer_status_t status,
        const char *format, ...) {
    if (context && context->error && context->error_capacity != 0U) {
        va_list arguments;
        va_start(arguments, format);
        vsnprintf(context->error, context->error_capacity, format, arguments);
        va_end(arguments);
    }
    return status;
}

static coff_writer_status_t coff_amd64_writer_status(
        coff_amd64_context_t *context, coff_writer_status_t status) {
    if (status == COFF_WRITER_OK || !context || !context->error ||
        context->error_capacity == 0U)
        return status;
    const char *message = coff_object_last_error(context->object);
    if (message && *message)
        snprintf(context->error, context->error_capacity, "%s", message);
    else
        snprintf(context->error, context->error_capacity, "%s",
                 coff_writer_status_string(status));
    return status;
}

static void coff_amd64_write_u32(uint8_t *bytes, uint32_t value) {
    bytes[0] = (uint8_t) value;
    bytes[1] = (uint8_t) (value >> 8U);
    bytes[2] = (uint8_t) (value >> 16U);
    bytes[3] = (uint8_t) (value >> 24U);
}

static bool coff_amd64_is_unwind_plan_name(const char *name) {
    return name &&
           strncmp(name, COFF_AMD64_UNWIND_PLAN_PREFIX,
                   COFF_AMD64_UNWIND_PLAN_PREFIX_SIZE) == 0;
}

static char *coff_amd64_join_name(const char *prefix, const char *name) {
    if (!prefix || !name) return NULL;
    const size_t prefix_size = strlen(prefix);
    const size_t name_size = strlen(name);
    if (name_size > SIZE_MAX - prefix_size - 1U) return NULL;
    char *result = malloc(prefix_size + name_size + 1U);
    if (!result) return NULL;
    memcpy(result, prefix, prefix_size);
    memcpy(result + prefix_size, name, name_size + 1U);
    return result;
}

static void coff_amd64_unwind_plans_deinit(coff_amd64_context_t *context) {
    if (!context) return;
    for (size_t i = 0U; i < context->unwind_plan_count; i++)
        free(context->unwind_plans[i].actions);
    free(context->unwind_plans);
    context->unwind_plans = NULL;
    context->unwind_plan_count = 0U;
}

static coff_amd64_unwind_plan_t *coff_amd64_find_unwind_plan(
        coff_amd64_context_t *context, const char *function_name) {
    if (!context || !function_name) return NULL;
    for (size_t i = 0U; i < context->unwind_plan_count; i++) {
        if (strcmp(context->unwind_plans[i].function_name, function_name) ==
            0)
            return &context->unwind_plans[i];
    }
    return NULL;
}

static coff_writer_status_t coff_amd64_validate_unwind_action(
        coff_amd64_context_t *context, const char *function_name,
        coff_amd64_unwind_plan_t *plan,
        coff_amd64_unwind_action_t *action, uint16_t action_index) {
    if (action->reg > 15U) {
        return coff_amd64_fail(
                context, COFF_WRITER_INVALID_ARGUMENT,
                "unwind plan for '%s' action %u has invalid register %u",
                function_name, action_index, action->reg);
    }
    switch (action->kind) {
        case COFF_AMD64_PLAN_PUSH_NONVOL:
            if (action->flags != 0U || action->value != 0U)
                goto invalid_action;
            break;
        case COFF_AMD64_PLAN_SET_FPREG:
            if (action->flags != 0U || action->value != plan->frame_size ||
                action->reg != plan->frame_register)
                goto invalid_action;
            break;
        case COFF_AMD64_PLAN_ALLOC:
            if ((action->flags & ~UINT16_C(1)) != 0U || action->reg != 0U ||
                action->value != plan->frame_size || action->value < 8U ||
                (action->value & 7U) != 0U)
                goto invalid_action;
            break;
        case COFF_AMD64_PLAN_SAVE_NONVOL:
            if (action->flags != 0U || (action->value & 7U) != 0U ||
                action->value > plan->frame_size ||
                plan->frame_size - action->value < 8U)
                goto invalid_action;
            break;
        case COFF_AMD64_PLAN_SAVE_XMM128:
            if (action->flags != 0U || (action->value & 15U) != 0U ||
                action->value > plan->frame_size ||
                plan->frame_size - action->value < 16U)
                goto invalid_action;
            break;
        default:
            goto invalid_action;
    }
    return COFF_WRITER_OK;

invalid_action:
    return coff_amd64_fail(
            context, COFF_WRITER_INVALID_ARGUMENT,
            "unwind plan for '%s' has invalid action %u", function_name,
            action_index);
}

static coff_writer_status_t coff_amd64_parse_unwind_plan(
        coff_amd64_context_t *context, const asm_global_symbol_t *symbol,
        coff_amd64_unwind_plan_t *plan) {
    if (!symbol->value || symbol->size < COFF_AMD64_UNWIND_PLAN_HEADER_SIZE) {
        return coff_amd64_fail(context, COFF_WRITER_INVALID_ARGUMENT,
                               "unwind plan '%s' is truncated", symbol->name);
    }
    const uint8_t *bytes = symbol->value;
    const char *function_name =
            symbol->name + COFF_AMD64_UNWIND_PLAN_PREFIX_SIZE;
    const uint16_t header_size = coff_amd64_read_u16(bytes + 4U);
    const uint16_t action_count = coff_amd64_read_u16(bytes + 6U);
    const size_t actions_size =
            (size_t) action_count * COFF_AMD64_UNWIND_PLAN_ACTION_SIZE;
    if (!*function_name || memcmp(bytes, "NWU1", 4U) != 0 ||
        header_size != COFF_AMD64_UNWIND_PLAN_HEADER_SIZE ||
        actions_size > SIZE_MAX - header_size ||
        symbol->size != header_size + actions_size || action_count == 0U ||
        coff_amd64_read_u16(bytes + 18U) != 0U || bytes[16] > 15U ||
        (bytes[17] & ~UINT8_C(1)) != 0U) {
        return coff_amd64_fail(context, COFF_WRITER_INVALID_ARGUMENT,
                               "unwind plan '%s' has an invalid header",
                               symbol->name);
    }
    if (coff_amd64_find_unwind_plan(context, function_name)) {
        return coff_amd64_fail(context, COFF_WRITER_DUPLICATE,
                               "duplicate unwind plan for '%s'",
                               function_name);
    }
    memset(plan, 0, sizeof(*plan));
    plan->function_name = function_name;
    plan->action_count = action_count;
    plan->frame_size = coff_amd64_read_u32(bytes + 8U);
    plan->outgoing_size = coff_amd64_read_u32(bytes + 12U);
    plan->frame_register = bytes[16];
    plan->flags = bytes[17];
    if ((plan->frame_size & 7U) != 0U ||
        plan->outgoing_size > plan->frame_size) {
        return coff_amd64_fail(context, COFF_WRITER_INVALID_ARGUMENT,
                               "unwind plan for '%s' has invalid frame sizes",
                               function_name);
    }
    plan->actions = calloc(action_count, sizeof(*plan->actions));
    if (!plan->actions) {
        return coff_amd64_fail(context, COFF_WRITER_OUT_OF_MEMORY,
                               "out of memory parsing unwind plan for '%s'",
                               function_name);
    }
    const uint8_t *action_bytes = bytes + header_size;
    for (uint16_t i = 0U; i < action_count; i++) {
        coff_amd64_unwind_action_t *action = &plan->actions[i];
        action->kind = action_bytes[0];
        action->reg = action_bytes[1];
        action->flags = coff_amd64_read_u16(action_bytes + 2U);
        action->value = coff_amd64_read_u32(action_bytes + 4U);
        coff_writer_status_t status = coff_amd64_validate_unwind_action(
                context, function_name, plan, action, i);
        if (status != COFF_WRITER_OK) return status;
        action_bytes += COFF_AMD64_UNWIND_PLAN_ACTION_SIZE;
    }
    if (action_count < 3U ||
        plan->actions[0].kind != COFF_AMD64_PLAN_PUSH_NONVOL ||
        plan->actions[1].kind != COFF_AMD64_PLAN_ALLOC ||
        plan->actions[2].kind != COFF_AMD64_PLAN_SET_FPREG ||
        (plan->actions[1].flags & 1U) != (plan->flags & 1U)) {
        return coff_amd64_fail(
                context, COFF_WRITER_INVALID_ARGUMENT,
                "unwind plan for '%s' has an invalid prologue prefix",
                function_name);
    }
    return COFF_WRITER_OK;
}

static coff_writer_status_t coff_amd64_collect_unwind_plans(
        coff_amd64_context_t *context) {
    size_t count = 0U;
    for (int i = 0; i < context->module->asm_global_symbols->count; i++) {
        const asm_global_symbol_t *symbol =
                context->module->asm_global_symbols->take[i];
        if (symbol && coff_amd64_is_unwind_plan_name(symbol->name)) count++;
    }
    if (count == 0U) return COFF_WRITER_OK;
    context->unwind_plans = calloc(count, sizeof(*context->unwind_plans));
    if (!context->unwind_plans) {
        return coff_amd64_fail(context, COFF_WRITER_OUT_OF_MEMORY,
                               "out of memory collecting AMD64 unwind plans");
    }
    for (int i = 0; i < context->module->asm_global_symbols->count; i++) {
        const asm_global_symbol_t *symbol =
                context->module->asm_global_symbols->take[i];
        if (!symbol || !coff_amd64_is_unwind_plan_name(symbol->name))
            continue;
        coff_amd64_unwind_plan_t *plan =
                &context->unwind_plans[context->unwind_plan_count];
        coff_writer_status_t status =
                coff_amd64_parse_unwind_plan(context, symbol, plan);
        if (status != COFF_WRITER_OK) {
            free(plan->actions);
            plan->actions = NULL;
            return status;
        }
        context->unwind_plan_count++;
    }
    return COFF_WRITER_OK;
}

static void coff_amd64_record_caller(
        closure_t *closure, const amd64_asm_inst_t *operation,
        const asm_symbol_t *target, uint64_t closure_size) {
    if (!ct_caller_list || !coff_amd64_is_call(operation->name) ||
        (target && is_rtcall((char *) target->name)))
        return;

    caller_t caller = {
            .offset = closure_size,
            .line = operation->line,
            .column = operation->column,
            .data = closure,
    };
    if (target) caller.target_name_offset = strtable_put(target->name);
    ct_list_push(ct_caller_list, &caller);
}

static amd64_asm_operand_t *coff_amd64_find_symbol_operand(
        const amd64_asm_inst_t *operation) {
    if (!operation) return NULL;
    for (uint8_t i = 0U; i < operation->count; i++) {
        amd64_asm_operand_t *operand = operation->operands[i];
        if (operand && operand->type == AMD64_ASM_OPERAND_TYPE_SYMBOL)
            return operand;
    }
    return NULL;
}

static bool coff_amd64_is_immediate_operand(
        const amd64_asm_operand_t *operand) {
    if (!operand) return false;
    switch (operand->type) {
        case AMD64_ASM_OPERAND_TYPE_UINT:
        case AMD64_ASM_OPERAND_TYPE_UINT8:
        case AMD64_ASM_OPERAND_TYPE_UINT16:
        case AMD64_ASM_OPERAND_TYPE_UINT32:
        case AMD64_ASM_OPERAND_TYPE_UINT64:
        case AMD64_ASM_OPERAND_TYPE_INT8:
        case AMD64_ASM_OPERAND_TYPE_INT32:
            return true;
        default:
            return false;
    }
}

static coff_writer_status_t coff_amd64_force_rel32(
        coff_amd64_context_t *context, amd64_asm_operand_t *operand) {
    asm_uint32_t *relative = calloc(1U, sizeof(*relative));
    if (!relative)
        return coff_amd64_fail(context, COFF_WRITER_OUT_OF_MEMORY,
                               "out of memory lowering AMD64 rel32 operand");
    operand->type = AMD64_ASM_OPERAND_TYPE_UINT32;
    operand->size = 4U;
    operand->value = relative;
    return COFF_WRITER_OK;
}

static coff_writer_status_t coff_amd64_force_rip_relative(
        coff_amd64_context_t *context, amd64_asm_operand_t *operand) {
    asm_rip_relative_t *relative = calloc(1U, sizeof(*relative));
    if (!relative)
        return coff_amd64_fail(
                context, COFF_WRITER_OUT_OF_MEMORY,
                "out of memory lowering AMD64 RIP-relative operand");
    operand->type = AMD64_ASM_OPERAND_TYPE_RIP_RELATIVE;
    operand->value = relative;
    return COFF_WRITER_OK;
}

static coff_writer_status_t coff_amd64_preflight(
        coff_amd64_context_t *context) {
    if (!context || !context->module || !context->module->closures ||
        !context->module->asm_global_symbols) {
        return coff_amd64_fail(context, COFF_WRITER_INVALID_ARGUMENT,
                               "AMD64 COFF module is not initialized");
    }
    for (int i = 0; i < context->module->asm_global_symbols->count; i++) {
        const asm_global_symbol_t *symbol =
                context->module->asm_global_symbols->take[i];
        if (!symbol || !symbol->name || !*symbol->name) {
            return coff_amd64_fail(
                    context, COFF_WRITER_INVALID_ARGUMENT,
                    "AMD64 COFF module contains an invalid global symbol");
        }
        if (symbol->size > UINT32_MAX) {
            return coff_amd64_fail(
                    context, COFF_WRITER_OVERFLOW,
                    "AMD64 COFF global symbol '%s' exceeds 4 GiB",
                    symbol->name);
        }
    }
    coff_writer_status_t plan_status =
            coff_amd64_collect_unwind_plans(context);
    if (plan_status != COFF_WRITER_OK) return plan_status;
    for (int i = 0; i < context->module->closures->count; i++) {
        const closure_t *closure = context->module->closures->take[i];
        if (!closure || !closure->asm_operations) {
            return coff_amd64_fail(
                    context, COFF_WRITER_INVALID_ARGUMENT,
                    "AMD64 COFF module contains an invalid closure");
        }
        for (int j = 0; j < closure->asm_operations->count; j++) {
            const amd64_asm_inst_t *operation =
                    closure->asm_operations->take[j];
            if (!operation || !operation->name || !*operation->name) {
                return coff_amd64_fail(
                        context, COFF_WRITER_INVALID_ARGUMENT,
                        "AMD64 COFF closure contains an invalid instruction");
            }
            amd64_asm_operand_t *operand =
                    coff_amd64_find_symbol_operand(operation);
            if (!operand) {
                if (coff_amd64_is_label(operation->name)) {
                    return coff_amd64_fail(
                            context, COFF_WRITER_INVALID_ARGUMENT,
                            "AMD64 label instruction has no symbol operand");
                }
                continue;
            }
            const asm_symbol_t *symbol = operand->value;
            if (!symbol || !symbol->name || !*symbol->name) {
                return coff_amd64_fail(
                        context, COFF_WRITER_INVALID_ARGUMENT,
                        "AMD64 instruction has an invalid symbol operand");
            }
        }
    }
    return COFF_WRITER_OK;
}

static coff_writer_status_t coff_amd64_emit_globals(
        coff_amd64_context_t *context) {
    for (int i = 0; i < context->module->asm_global_symbols->count; i++) {
        const asm_global_symbol_t *symbol =
                context->module->asm_global_symbols->take[i];
        if (coff_amd64_is_unwind_plan_name(symbol->name)) continue;
        uint32_t offset = 0U;
        coff_writer_status_t status = coff_section_append(
                context->data, symbol->value, symbol->size, 1U, &offset);
        if (status != COFF_WRITER_OK)
            return coff_amd64_writer_status(context, status);
        status = coff_object_define_symbol(
                context->object, symbol->name, context->data, offset, 0U,
                LD_COFF_STORAGE_CLASS_EXTERNAL, NULL);
        if (status != COFF_WRITER_OK)
            return coff_amd64_writer_status(context, status);
    }
    return COFF_WRITER_OK;
}

static coff_writer_status_t coff_amd64_define_label(
        coff_amd64_context_t *context, amd64_asm_inst_t *operation) {
    amd64_asm_operand_t *operand =
            coff_amd64_find_symbol_operand(operation);
    asm_symbol_t *symbol = operand ? operand->value : NULL;
    if (!symbol) {
        return coff_amd64_fail(context, COFF_WRITER_INVALID_ARGUMENT,
                               "AMD64 label has no symbol");
    }
    const uint8_t storage_class = symbol->is_local
                                          ? LD_COFF_STORAGE_CLASS_STATIC
                                          : LD_COFF_STORAGE_CLASS_EXTERNAL;
    coff_writer_status_t status = coff_object_define_symbol(
            context->object, symbol->name, context->text,
            coff_section_size(context->text), COFF_SYMBOL_TYPE_FUNCTION,
            storage_class, NULL);
    return coff_amd64_writer_status(context, status);
}

static coff_writer_status_t coff_amd64_relocation_type(
        coff_amd64_context_t *context, const amd64_asm_inst_t *operation,
        uint8_t encoded_size, bool control_transfer, uint32_t *field_offset,
        uint16_t *relocation_type) {
    uint32_t trailing = 0U;
    if (!control_transfer && operation->count != 0U) {
        const amd64_asm_operand_t *last =
                operation->operands[operation->count - 1U];
        if (coff_amd64_is_immediate_operand(last)) trailing = last->size;
    }
    if (trailing > 5U || encoded_size < 4U + trailing) {
        return coff_amd64_fail(
                context, COFF_WRITER_UNSUPPORTED,
                "AMD64 RIP relocation for '%s' has %u trailing bytes; COFF "
                "supports at most five",
                operation->name, trailing);
    }
    *field_offset = (uint32_t) encoded_size - 4U - trailing;
    *relocation_type =
            (uint16_t) (LD_COFF_REL_AMD64_REL32 + trailing);
    return COFF_WRITER_OK;
}

static bool coff_amd64_register_operand(const amd64_asm_operand_t *operand,
                                        uint8_t *index) {
    if (!operand ||
        (operand->type != AMD64_ASM_OPERAND_TYPE_REG &&
         operand->type != AMD64_ASM_OPERAND_TYPE_FREG) ||
        !operand->value)
        return false;
    const reg_t *reg = operand->value;
    if (index) *index = reg->index;
    return true;
}

static bool coff_amd64_rsp_slot_operand(const amd64_asm_operand_t *operand,
                                        uint32_t *offset) {
    if (!operand || operand->type != AMD64_ASM_OPERAND_TYPE_SIB_REG ||
        !operand->value)
        return false;
    const asm_sib_reg_t *slot = operand->value;
    if (!slot->base || slot->base->index != 4U || slot->index ||
        slot->disp < 0)
        return false;
    if (offset) *offset = (uint32_t) slot->disp;
    return true;
}

static coff_writer_status_t coff_amd64_note_unwind_instruction(
        coff_amd64_context_t *context, coff_amd64_unwind_plan_t *plan,
        const amd64_asm_inst_t *operation, uint64_t instruction_end) {
    if (!plan || plan->matched_count == plan->action_count)
        return COFF_WRITER_OK;
    coff_amd64_unwind_action_t *action =
            &plan->actions[plan->matched_count];
    if (!coff_amd64_instruction_matches_action(operation, action)) {
        if (action->kind == COFF_AMD64_PLAN_ALLOC &&
            (action->flags & 1U) != 0U &&
            (strcmp(operation->name, "mov") == 0 ||
             strcmp(operation->name, "call") == 0))
            return COFF_WRITER_OK;
        return coff_amd64_fail(
                context, COFF_WRITER_INVALID_STATE,
                "instruction '%s' does not match unwind action %u for '%s'",
                operation->name, plan->matched_count, plan->function_name);
    }
    if (instruction_end > UINT8_MAX) {
        return coff_amd64_fail(
                context, COFF_WRITER_UNSUPPORTED,
                "prologue for '%s' exceeds the Windows 255-byte unwind limit",
                plan->function_name);
    }
    action->code_offset = (uint8_t) instruction_end;
    action->matched = true;
    plan->matched_count++;
    return COFF_WRITER_OK;
}

static coff_writer_status_t coff_amd64_emit_encoded_instruction(
        coff_amd64_context_t *context, closure_t *closure,
        amd64_asm_inst_t *operation, uint64_t *closure_size,
        coff_amd64_unwind_plan_t *unwind_plan,
        uint32_t *instruction_offset_out, uint8_t *encoded_size_out) {
    uint8_t encoded[COFF_AMD64_MAX_INSTRUCTION_SIZE] = {0};
    uint8_t encoded_size = 0U;
    amd64_opcode_inst_t *matched = amd64_asm_inst_encoding(
            *operation, encoded, &encoded_size, closure);
    if (!matched || encoded_size == 0U ||
        encoded_size > COFF_AMD64_MAX_INSTRUCTION_SIZE) {
        return coff_amd64_fail(
                context, COFF_WRITER_INVALID_STATE,
                "cannot encode AMD64 instruction '%s' for COFF",
                operation->name);
    }
    uint32_t instruction_offset = 0U;
    coff_writer_status_t status = coff_section_append(
            context->text, encoded, encoded_size, 1U, &instruction_offset);
    if (status != COFF_WRITER_OK)
        return coff_amd64_writer_status(context, status);
    if (*closure_size > UINT64_MAX - encoded_size) {
        return coff_amd64_fail(context, COFF_WRITER_OVERFLOW,
                               "AMD64 closure size overflows");
    }
    *closure_size += encoded_size;
    status = coff_amd64_note_unwind_instruction(
            context, unwind_plan, operation, *closure_size);
    if (status != COFF_WRITER_OK) return status;
    if (instruction_offset_out) *instruction_offset_out = instruction_offset;
    if (encoded_size_out) *encoded_size_out = encoded_size;
    return COFF_WRITER_OK;
}

static bool coff_amd64_operand_uses_gp_register(
        const amd64_asm_operand_t *operand, uint8_t index) {
    if (!operand || !operand->value) return false;
    switch (operand->type) {
        case AMD64_ASM_OPERAND_TYPE_REG:
            return ((const reg_t *) operand->value)->index == index;
        case AMD64_ASM_OPERAND_TYPE_INDIRECT_REG:
            return ((const asm_indirect_reg_t *) operand->value)->reg->index ==
                   index;
        case AMD64_ASM_OPERAND_TYPE_DISP_REG:
            return ((const asm_disp_reg_t *) operand->value)->reg->index ==
                   index;
        case AMD64_ASM_OPERAND_TYPE_SIB_REG: {
            const asm_sib_reg_t *sib = operand->value;
            return (sib->base && sib->base->index == index) ||
                   (sib->index && sib->index->index == index);
        }
        default:
            return false;
    }
}

static bool coff_amd64_operation_uses_gp_register(
        const amd64_asm_inst_t *operation, uint8_t index) {
    for (uint8_t i = 0U; i < operation->count; i++) {
        if (coff_amd64_operand_uses_gp_register(operation->operands[i],
                                                index))
            return true;
    }
    return false;
}

static bool coff_amd64_tls_scratch_offset(
        const coff_amd64_unwind_plan_t *plan, uint32_t *offset) {
    if (!plan || !offset) return false;
    uint64_t end = plan->outgoing_size;
    for (uint16_t i = 0U; i < plan->action_count; i++) {
        const coff_amd64_unwind_action_t *action = &plan->actions[i];
        uint32_t width = 0U;
        if (action->kind == COFF_AMD64_PLAN_SAVE_NONVOL)
            width = 8U;
        else if (action->kind == COFF_AMD64_PLAN_SAVE_XMM128)
            width = 16U;
        if (width != 0U && action->value + (uint64_t) width > end)
            end = action->value + (uint64_t) width;
    }
    if (end > UINT32_MAX || end + 16U > plan->frame_size) return false;
    *offset = (uint32_t) end;
    return true;
}

static amd64_asm_operand_t coff_amd64_make_register_operand(reg_t *reg) {
    return (amd64_asm_operand_t) {
            .type = AMD64_ASM_OPERAND_TYPE_REG,
            .size = reg->size,
            .value = reg,
    };
}

static amd64_asm_operand_t coff_amd64_sib_operand(
        asm_sib_reg_t *sib, uint8_t size) {
    return (amd64_asm_operand_t) {
            .type = AMD64_ASM_OPERAND_TYPE_SIB_REG,
            .size = size,
            .value = sib,
    };
}

static coff_writer_status_t coff_amd64_emit_instruction(
        coff_amd64_context_t *context, closure_t *closure,
        amd64_asm_inst_t *operation, uint64_t *closure_size,
        coff_amd64_unwind_plan_t *unwind_plan) {
    amd64_asm_operand_t *operand =
            coff_amd64_find_symbol_operand(operation);
    asm_symbol_t *symbol = operand ? operand->value : NULL;
    if (symbol && symbol->is_tls)
        return coff_amd64_emit_tls_instruction(
                context, closure, operation, operand, symbol, closure_size,
                unwind_plan);

    const bool control_transfer =
            symbol && (coff_amd64_is_call(operation->name) ||
                       coff_amd64_is_jump(operation->name));
    uint32_t symbol_index = COFF_SYMBOL_INDEX_NONE;
    coff_writer_status_t status = COFF_WRITER_OK;
    if (symbol) {
        status = coff_object_get_or_add_symbol_reference(
                context->object, symbol->name, !symbol->is_local,
                control_transfer ? COFF_SYMBOL_TYPE_FUNCTION : 0U,
                &symbol_index);
        if (status != COFF_WRITER_OK)
            return coff_amd64_writer_status(context, status);
        status = control_transfer
                         ? coff_amd64_force_rel32(context, operand)
                         : coff_amd64_force_rip_relative(context, operand);
        if (status != COFF_WRITER_OK) return status;
    }

    uint32_t instruction_offset = 0U;
    uint8_t encoded_size = 0U;
    status = coff_amd64_emit_encoded_instruction(
            context, closure, operation, closure_size, unwind_plan,
            &instruction_offset, &encoded_size);
    if (status != COFF_WRITER_OK) return status;
    coff_amd64_record_caller(closure, operation, symbol, *closure_size);
    if (!symbol) return COFF_WRITER_OK;

    uint32_t field_in_instruction = 0U;
    uint16_t relocation_type = 0U;
    status = coff_amd64_relocation_type(
            context, operation, encoded_size, control_transfer,
            &field_in_instruction, &relocation_type);
    if (status != COFF_WRITER_OK) return status;
    if (field_in_instruction > UINT32_MAX - instruction_offset) {
        return coff_amd64_fail(context, COFF_WRITER_OVERFLOW,
                               "AMD64 COFF relocation offset overflows");
    }
    status = coff_section_add_relocation_with_addend(
            context->text, instruction_offset + field_in_instruction,
            symbol_index, relocation_type, 0);
    return status == COFF_WRITER_OK
                   ? COFF_WRITER_OK
                   : coff_amd64_writer_status(context, status);
}

static bool coff_amd64_use_frame_register(
        const coff_amd64_unwind_plan_t *plan) {
    if (!plan || plan->frame_register == 0U || plan->frame_size > 240U ||
        (plan->frame_size & 15U) != 0U)
        return false;
    for (uint16_t i = 0U; i < plan->action_count; i++) {
        if (plan->actions[i].kind == COFF_AMD64_PLAN_SET_FPREG) return true;
    }
    return false;
}

static size_t coff_amd64_unwind_action_slots(
        const coff_amd64_unwind_action_t *action, bool use_frame_register) {
    switch (action->kind) {
        case COFF_AMD64_PLAN_PUSH_NONVOL:
            return 1U;
        case COFF_AMD64_PLAN_SET_FPREG:
            return use_frame_register ? 1U : 0U;
        case COFF_AMD64_PLAN_ALLOC:
            if (action->value <= 128U) return 1U;
            return action->value / 8U <= UINT16_MAX ? 2U : 3U;
        case COFF_AMD64_PLAN_SAVE_NONVOL:
            return action->value / 8U <= UINT16_MAX ? 2U : 3U;
        case COFF_AMD64_PLAN_SAVE_XMM128:
            return action->value / 16U <= UINT16_MAX ? 2U : 3U;
        default:
            return 0U;
    }
}

static coff_writer_status_t coff_amd64_encode_unwind_info(
        coff_amd64_context_t *context, coff_amd64_unwind_plan_t *plan,
        uint8_t **result, size_t *result_size) {
    *result = NULL;
    *result_size = 0U;
    if (plan->matched_count != plan->action_count) {
        return coff_amd64_fail(
                context, COFF_WRITER_INVALID_STATE,
                "unwind plan for '%s' matched %u of %u actions",
                plan->function_name, plan->matched_count, plan->action_count);
    }
    const bool use_frame_register =
            coff_amd64_use_frame_register(plan);
    size_t slot_count = 0U;
    uint8_t previous_offset = 0U;
    for (uint16_t i = 0U; i < plan->action_count; i++) {
        const coff_amd64_unwind_action_t *action = &plan->actions[i];
        if (!action->matched || action->code_offset < previous_offset) {
            return coff_amd64_fail(
                    context, COFF_WRITER_INVALID_STATE,
                    "unwind action offsets for '%s' are not monotonic",
                    plan->function_name);
        }
        previous_offset = action->code_offset;
        const size_t action_slots =
                coff_amd64_unwind_action_slots(action, use_frame_register);
        if (action_slots > UINT8_MAX - slot_count) {
            return coff_amd64_fail(
                    context, COFF_WRITER_UNSUPPORTED,
                    "unwind codes for '%s' exceed the Windows 255-slot limit",
                    plan->function_name);
        }
        slot_count += action_slots;
    }
    const size_t padded_slot_count = (slot_count + 1U) & ~(size_t) 1U;
    if (padded_slot_count > (SIZE_MAX - 4U) / 2U) {
        return coff_amd64_fail(context, COFF_WRITER_OVERFLOW,
                               "unwind info size overflows");
    }
    const size_t size = 4U + padded_slot_count * 2U;
    uint8_t *bytes = calloc(1U, size);
    if (!bytes) {
        return coff_amd64_fail(context, COFF_WRITER_OUT_OF_MEMORY,
                               "out of memory encoding unwind info for '%s'",
                               plan->function_name);
    }
    bytes[0] = 1U; /* Version 1, no exception/termination/chained flags. */
    bytes[1] = previous_offset;
    bytes[2] = (uint8_t) slot_count;
    if (use_frame_register) {
        bytes[3] = (uint8_t) (plan->frame_register |
                              ((plan->frame_size / 16U) << 4U));
    }

    uint8_t *codes = bytes + 4U;
    size_t cursor = 0U;
    for (size_t i = plan->action_count; i > 0U; i--) {
        const coff_amd64_unwind_action_t *action = &plan->actions[i - 1U];
        if (action->kind == COFF_AMD64_PLAN_SET_FPREG &&
            !use_frame_register)
            continue;
        uint8_t unwind_op = 0U;
        uint8_t op_info = 0U;
        switch (action->kind) {
            case COFF_AMD64_PLAN_PUSH_NONVOL:
                unwind_op = COFF_AMD64_UWOP_PUSH_NONVOL;
                op_info = action->reg;
                break;
            case COFF_AMD64_PLAN_SET_FPREG:
                unwind_op = COFF_AMD64_UWOP_SET_FPREG;
                break;
            case COFF_AMD64_PLAN_ALLOC:
                if (action->value <= 128U) {
                    unwind_op = COFF_AMD64_UWOP_ALLOC_SMALL;
                    op_info = (uint8_t) ((action->value - 8U) / 8U);
                } else if (action->value / 8U <= UINT16_MAX) {
                    unwind_op = COFF_AMD64_UWOP_ALLOC_LARGE;
                    op_info = 0U;
                } else {
                    unwind_op = COFF_AMD64_UWOP_ALLOC_LARGE;
                    op_info = 1U;
                }
                break;
            case COFF_AMD64_PLAN_SAVE_NONVOL:
                unwind_op = action->value / 8U <= UINT16_MAX
                                    ? COFF_AMD64_UWOP_SAVE_NONVOL
                                    : COFF_AMD64_UWOP_SAVE_NONVOL_FAR;
                op_info = action->reg;
                break;
            case COFF_AMD64_PLAN_SAVE_XMM128:
                unwind_op = action->value / 16U <= UINT16_MAX
                                    ? COFF_AMD64_UWOP_SAVE_XMM128
                                    : COFF_AMD64_UWOP_SAVE_XMM128_FAR;
                op_info = action->reg;
                break;
            default:
                free(bytes);
                return coff_amd64_fail(
                        context, COFF_WRITER_INVALID_STATE,
                        "unknown unwind action while encoding '%s'",
                        plan->function_name);
        }
        codes[cursor * 2U] = action->code_offset;
        codes[cursor * 2U + 1U] =
                (uint8_t) (unwind_op | (op_info << 4U));
        cursor++;
        if (action->kind == COFF_AMD64_PLAN_ALLOC &&
            action->value > 128U) {
            if (op_info == 0U) {
                coff_amd64_write_u16(codes + cursor * 2U,
                                     (uint16_t) (action->value / 8U));
                cursor++;
            } else {
                coff_amd64_write_u32(codes + cursor * 2U, action->value);
                cursor += 2U;
            }
        } else if (action->kind == COFF_AMD64_PLAN_SAVE_NONVOL) {
            if (unwind_op == COFF_AMD64_UWOP_SAVE_NONVOL) {
                coff_amd64_write_u16(codes + cursor * 2U,
                                     (uint16_t) (action->value / 8U));
                cursor++;
            } else {
                coff_amd64_write_u32(codes + cursor * 2U, action->value);
                cursor += 2U;
            }
        } else if (action->kind == COFF_AMD64_PLAN_SAVE_XMM128) {
            if (unwind_op == COFF_AMD64_UWOP_SAVE_XMM128) {
                coff_amd64_write_u16(codes + cursor * 2U,
                                     (uint16_t) (action->value / 16U));
                cursor++;
            } else {
                coff_amd64_write_u32(codes + cursor * 2U, action->value);
                cursor += 2U;
            }
        }
    }
    if (cursor != slot_count) {
        free(bytes);
        return coff_amd64_fail(context, COFF_WRITER_INVALID_STATE,
                               "unwind slot count mismatch for '%s'",
                               plan->function_name);
    }
    *result = bytes;
    *result_size = size;
    return COFF_WRITER_OK;
}

static coff_writer_status_t coff_amd64_emit_unwind_sections(
        coff_amd64_context_t *context, coff_amd64_unwind_plan_t *plan) {
    uint8_t *unwind_info = NULL;
    size_t unwind_info_size = 0U;
    coff_writer_status_t status = coff_amd64_encode_unwind_info(
            context, plan, &unwind_info, &unwind_info_size);
    if (status != COFF_WRITER_OK) return status;

    char *pdata_name = coff_amd64_join_name(".pdata$", plan->function_name);
    char *xdata_name = coff_amd64_join_name(".xdata$", plan->function_name);
    char *end_name =
            coff_amd64_join_name("__nature_unwind_end$", plan->function_name);
    char *xdata_symbol = coff_amd64_join_name(
            "__nature_unwind_info$", plan->function_name);
    char *pdata_leader =
            coff_amd64_join_name("__nature_pdata$", plan->function_name);
    if (!pdata_name || !xdata_name || !end_name || !xdata_symbol ||
        !pdata_leader) {
        status = coff_amd64_fail(
                context, COFF_WRITER_OUT_OF_MEMORY,
                "out of memory naming unwind sections for '%s'",
                plan->function_name);
        goto cleanup;
    }

    coff_section_t *pdata = NULL;
    coff_section_t *xdata = NULL;
    const uint32_t characteristics =
            LD_COFF_SCN_CNT_INITIALIZED_DATA | LD_COFF_SCN_MEM_READ;
    status = coff_object_add_section(context->object, pdata_name,
                                     characteristics, 4U, &pdata);
    if (status != COFF_WRITER_OK) goto writer_failure;
    status = coff_object_add_section(context->object, xdata_name,
                                     characteristics, 4U, &xdata);
    if (status != COFF_WRITER_OK) goto writer_failure;
    uint32_t xdata_offset = 0U;
    status = coff_section_append(xdata, unwind_info, unwind_info_size, 4U,
                                 &xdata_offset);
    if (status != COFF_WRITER_OK) goto writer_failure;
    uint32_t pdata_offset = 0U;
    status = coff_section_append_zeros(pdata, 12U, 4U, &pdata_offset);
    if (status != COFF_WRITER_OK) goto writer_failure;
    if (xdata_offset != 0U || pdata_offset != 0U) {
        status = coff_amd64_fail(context, COFF_WRITER_INVALID_STATE,
                                 "new unwind sections are not empty");
        goto cleanup;
    }

    uint32_t function_index = COFF_SYMBOL_INDEX_NONE;
    uint32_t end_index = COFF_SYMBOL_INDEX_NONE;
    uint32_t xdata_index = COFF_SYMBOL_INDEX_NONE;
    status = coff_object_get_or_add_symbol_reference(
            context->object, plan->function_name, true,
            COFF_SYMBOL_TYPE_FUNCTION, &function_index);
    if (status != COFF_WRITER_OK) goto writer_failure;
    status = coff_object_define_symbol(
            context->object, end_name, context->text,
            coff_section_size(context->text), COFF_SYMBOL_TYPE_FUNCTION,
            LD_COFF_STORAGE_CLASS_STATIC, &end_index);
    if (status != COFF_WRITER_OK) goto writer_failure;
    status = coff_object_add_defined_symbol(
            context->object, xdata_symbol, xdata, 0U, 0U,
            LD_COFF_STORAGE_CLASS_STATIC, &xdata_index);
    if (status != COFF_WRITER_OK) goto writer_failure;
    status = coff_section_add_relocation_with_addend(
            pdata, 0U, function_index, LD_COFF_REL_AMD64_ADDR32NB, 0);
    if (status != COFF_WRITER_OK) goto writer_failure;
    status = coff_section_add_relocation_with_addend(
            pdata, 4U, end_index, LD_COFF_REL_AMD64_ADDR32NB, 0);
    if (status != COFF_WRITER_OK) goto writer_failure;
    status = coff_section_add_relocation_with_addend(
            pdata, 8U, xdata_index, LD_COFF_REL_AMD64_ADDR32NB, 0);
    if (status != COFF_WRITER_OK) goto writer_failure;

    status = coff_object_mark_comdat(
            context->object, pdata, LD_COFF_COMDAT_ANY, NULL, pdata_leader,
            0U, NULL, NULL);
    if (status != COFF_WRITER_OK) goto writer_failure;
    status = coff_object_mark_comdat(
            context->object, xdata, LD_COFF_COMDAT_ASSOCIATIVE, pdata, NULL,
            0U, NULL, NULL);
    if (status != COFF_WRITER_OK) goto writer_failure;
    plan->emitted = true;
    goto cleanup;

writer_failure:
    status = coff_amd64_writer_status(context, status);

cleanup:
    free(unwind_info);
    free(pdata_name);
    free(xdata_name);
    free(end_name);
    free(xdata_symbol);
    free(pdata_leader);
    return status;
}

static coff_writer_status_t coff_amd64_emit_text(
        coff_amd64_context_t *context) {
    for (int i = 0; i < context->module->closures->count; i++) {
        closure_t *closure = context->module->closures->take[i];
        coff_amd64_unwind_plan_t *unwind_plan =
                coff_amd64_find_unwind_plan(context, closure->linkident);
        uint64_t closure_size = 0U;
        closure->text_count = 0U;
        for (int j = 0; j < closure->asm_operations->count; j++) {
            amd64_asm_inst_t *operation =
                    closure->asm_operations->take[j];
            coff_writer_status_t status;
            if (coff_amd64_is_label(operation->name))
                status = coff_amd64_define_label(context, operation);
            else
                status = coff_amd64_emit_instruction(
                        context, closure, operation, &closure_size,
                        unwind_plan);
            if (status != COFF_WRITER_OK) return status;
        }
        closure->text_count = closure_size;
        if (unwind_plan) {
            coff_writer_status_t status =
                    coff_amd64_emit_unwind_sections(context, unwind_plan);
            if (status != COFF_WRITER_OK) return status;
        }
    }
    return COFF_WRITER_OK;
}

coff_writer_status_t coff_encode_amd64_module_ex(
        coff_object_t *object, module_t *module, char *error,
        size_t error_capacity) {
    if (error && error_capacity != 0U) error[0] = '\0';
    coff_amd64_context_t context = {
            .object = object,
            .module = module,
            .text = coff_object_text(object),
            .data = coff_object_data(object),
            .error = error,
            .error_capacity = error_capacity,
    };
    if (!object || !module || !context.text || !context.data) {
        return coff_amd64_fail(
                &context, COFF_WRITER_INVALID_ARGUMENT,
                "AMD64 COFF adapter requires an object with .text and .data");
    }
    coff_writer_status_t status = coff_amd64_preflight(&context);
    if (status == COFF_WRITER_OK) status = coff_amd64_emit_globals(&context);
    if (status == COFF_WRITER_OK) status = coff_amd64_emit_text(&context);
    coff_amd64_unwind_plans_deinit(&context);
    return status;
}

coff_writer_status_t coff_assembler_module(module_t *module,
                                           const char *output_path,
                                           char *error,
                                           size_t error_capacity) {
    if (error && error_capacity != 0U) error[0] = '\0';
    if (!module || !output_path || !*output_path) {
        if (error && error_capacity != 0U)
            snprintf(error, error_capacity,
                     "COFF module or output path is invalid");
        return COFF_WRITER_INVALID_ARGUMENT;
    }
    coff_object_t *object = coff_object_create_amd64(module->source_path);
    if (!object) {
        if (error && error_capacity != 0U)
            snprintf(error, error_capacity,
                     "out of memory creating AMD64 COFF object");
        return COFF_WRITER_OUT_OF_MEMORY;
    }
    coff_writer_status_t status = coff_encode_amd64_module_ex(
            object, module, error, error_capacity);
    if (status == COFF_WRITER_OK) {
        status = coff_object_write_file(object, output_path);
        if (status != COFF_WRITER_OK && error && error_capacity != 0U)
            snprintf(error, error_capacity, "%s",
                     coff_object_last_error(object));
    }
    if (status == COFF_WRITER_OK) {
        const size_t length = strlen(output_path);
        char *copy = malloc(length + 1U);
        if (!copy) {
            status = COFF_WRITER_OUT_OF_MEMORY;
            if (error && error_capacity != 0U)
                snprintf(error, error_capacity,
                         "out of memory recording COFF object path");
        } else {
            memcpy(copy, output_path, length + 1U);
            module->object_file = copy;
        }
    }
    coff_object_destroy(object);
    return status;
}

static void coff_amd64_test_put_u32(uint8_t *bytes, uint32_t value) {
    bytes[0] = (uint8_t) value;
    bytes[1] = (uint8_t) (value >> 8U);
    bytes[2] = (uint8_t) (value >> 16U);
    bytes[3] = (uint8_t) (value >> 24U);
}

static bool coff_amd64_test_parse(const uint8_t *bytes, size_t size,
                                  coff_amd64_test_image_t *image) {
    if (!bytes || !image || size < LD_COFF_HEADER_SIZE) return false;
    memset(image, 0, sizeof(*image));
    image->bytes = bytes;
    image->size = size;
    image->section_count = coff_amd64_test_u16(bytes + 2U);
    image->symbol_offset = coff_amd64_test_u32(bytes + 8U);
    image->symbol_count = coff_amd64_test_u32(bytes + 12U);
    const uint64_t string_offset =
            (uint64_t) image->symbol_offset +
            (uint64_t) image->symbol_count * LD_COFF_SYMBOL_SIZE;
    if (string_offset > UINT32_MAX ||
        !coff_amd64_test_range(size, (size_t) string_offset, 4U))
        return false;
    image->string_offset = (uint32_t) string_offset;
    image->string_size = coff_amd64_test_u32(bytes + image->string_offset);
    return image->string_size >= 4U &&
           coff_amd64_test_range(size, image->string_offset,
                                 image->string_size);
}

static bool coff_amd64_test_string(const coff_amd64_test_image_t *image,
                                   uint32_t offset, const char **value) {
    if (!image || !value || offset < 4U || offset >= image->string_size)
        return false;
    const char *text = (const char *) image->bytes + image->string_offset +
                       offset;
    const size_t remaining = image->string_size - offset;
    if (!memchr(text, '\0', remaining)) return false;
    *value = text;
    return true;
}

static bool coff_amd64_test_section_name(
        const coff_amd64_test_image_t *image, const uint8_t *header,
        char short_name[LD_COFF_NAME_SIZE + 1U], const char **name) {
    memcpy(short_name, header, LD_COFF_NAME_SIZE);
    short_name[LD_COFF_NAME_SIZE] = '\0';
    if (header[0] != '/') {
        *name = short_name;
        return true;
    }
    char *end = NULL;
    unsigned long offset = strtoul(short_name + 1U, &end, 10);
    if (end == short_name + 1U || *end != '\0' || offset > UINT32_MAX)
        return false;
    return coff_amd64_test_string(image, (uint32_t) offset, name);
}

static bool coff_amd64_test_find_section(
        const coff_amd64_test_image_t *image, const char *name,
        uint16_t *index, uint32_t *header_offset) {
    for (uint16_t i = 0U; i < image->section_count; i++) {
        const uint32_t offset = LD_COFF_HEADER_SIZE +
                                (uint32_t) i * LD_COFF_SECTION_HEADER_SIZE;
        if (!coff_amd64_test_range(image->size, offset,
                                   LD_COFF_SECTION_HEADER_SIZE))
            return false;
        char short_name[LD_COFF_NAME_SIZE + 1U];
        const char *actual = NULL;
        if (!coff_amd64_test_section_name(image, image->bytes + offset,
                                          short_name, &actual))
            return false;
        if (strcmp(actual, name) == 0) {
            if (index) *index = (uint16_t) (i + 1U);
            if (header_offset) *header_offset = offset;
            return true;
        }
    }
    return false;
}

static bool coff_amd64_test_symbol_name(
        const coff_amd64_test_image_t *image, const uint8_t *record,
        char short_name[LD_COFF_NAME_SIZE + 1U], const char **name) {
    memcpy(short_name, record, LD_COFF_NAME_SIZE);
    short_name[LD_COFF_NAME_SIZE] = '\0';
    if (coff_amd64_test_u32(record) != 0U) {
        *name = short_name;
        return true;
    }
    return coff_amd64_test_string(image, coff_amd64_test_u32(record + 4U),
                                  name);
}

static bool coff_amd64_test_find_symbol(
        const coff_amd64_test_image_t *image, const char *name,
        coff_amd64_test_symbol_t *result) {
    uint32_t index = 0U;
    while (index < image->symbol_count) {
        const uint64_t offset = (uint64_t) image->symbol_offset +
                                (uint64_t) index * LD_COFF_SYMBOL_SIZE;
        if (offset > UINT32_MAX ||
            !coff_amd64_test_range(image->size, (size_t) offset,
                                   LD_COFF_SYMBOL_SIZE))
            return false;
        const uint8_t *record = image->bytes + (size_t) offset;
        char short_name[LD_COFF_NAME_SIZE + 1U];
        const char *actual = NULL;
        if (!coff_amd64_test_symbol_name(image, record, short_name, &actual))
            return false;
        const uint8_t aux_count = record[17];
        if ((uint64_t) index + 1U + aux_count > image->symbol_count)
            return false;
        if (strcmp(actual, name) == 0) {
            result->index = index;
            result->offset = (uint32_t) offset;
            result->aux_count = aux_count;
            return true;
        }
        index += 1U + aux_count;
    }
    return false;
}

amd64_opcode_inst_t *amd64_asm_inst_encoding(amd64_asm_inst_t instruction,
                                             uint8_t *data, uint8_t *count,
                                             closure_t *closure) {
    (void) closure;
    if (strcmp(instruction.name, "push") == 0) {
        data[0] = 0x55;
        *count = 1U;
    } else if (strcmp(instruction.name, "pop") == 0) {
        data[0] = 0x5d;
        *count = 1U;
    } else if (strcmp(instruction.name, "mov") == 0 &&
               instruction.operands[0]->type == AMD64_ASM_OPERAND_TYPE_REG &&
               instruction.operands[1]->type == AMD64_ASM_OPERAND_TYPE_REG) {
        const uint8_t bytes[] = {0x48, 0x89, 0xe5};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else if (strcmp(instruction.name, "lea") == 0 &&
               instruction.operands[1]->type ==
                       AMD64_ASM_OPERAND_TYPE_SIB_REG) {
        const asm_sib_reg_t *slot = instruction.operands[1]->value;
        const uint8_t bytes[] = {0x48, 0x8d, 0x6c, 0x24,
                                 (uint8_t) slot->disp};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else if (strcmp(instruction.name, "sub") == 0) {
        const uint8_t bytes[] = {0x48, 0x83, 0xec, 0x40};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else if (strcmp(instruction.name, "add") == 0 &&
               instruction.operands[0]->type ==
                       AMD64_ASM_OPERAND_TYPE_REG &&
               instruction.operands[1]->type ==
                       AMD64_ASM_OPERAND_TYPE_UINT32 &&
               ((asm_uint32_t *) instruction.operands[1]->value)->value ==
                       0U) {
        const uint8_t bytes[] = {0x49, 0x81, 0xc3, 0x00,
                                 0x00, 0x00, 0x00};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else if (strcmp(instruction.name, "add") == 0) {
        const uint8_t bytes[] = {0x48, 0x83, 0xc4, 0x40};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else if (strcmp(instruction.name, "mov") == 0 &&
               instruction.operands[0]->type ==
                       AMD64_ASM_OPERAND_TYPE_SIB_REG) {
        const uint8_t bytes[] = {0x48, 0x89, 0x5c, 0x24, 0x20};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else if (strcmp(instruction.name, "mov") == 0 &&
               instruction.operands[1]->type ==
                       AMD64_ASM_OPERAND_TYPE_SIB_REG) {
        const uint8_t bytes[] = {0x48, 0x8b, 0x5c, 0x24, 0x20};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else if (strcmp(instruction.name, "mov") == 0 &&
               instruction.operands[1]->type ==
                       AMD64_ASM_OPERAND_TYPE_RIP_RELATIVE) {
        const uint8_t bytes[] = {0x48, 0x8b, 0x05, 0x00,
                                 0x00, 0x00, 0x00};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else if (strcmp(instruction.name, "mov") == 0 &&
               instruction.operands[1]->type ==
                       AMD64_ASM_OPERAND_TYPE_SEG_OFFSET) {
        const uint8_t bytes[] = {0x65, 0x48, 0x8b, 0x1c, 0x25,
                                 0x58, 0x00, 0x00, 0x00};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else if (strcmp(instruction.name, "mov") == 0 &&
               instruction.operands[1]->type ==
                       AMD64_ASM_OPERAND_TYPE_INDIRECT_REG) {
        const uint8_t bytes[] = {0x49, 0x8b, 0x03};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else if (strcmp(instruction.name, "movxmm128") == 0 &&
               instruction.operands[0]->type ==
                       AMD64_ASM_OPERAND_TYPE_SIB_REG) {
        const uint8_t bytes[] = {0x44, 0x0f, 0x11, 0x7c, 0x24, 0x30};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else if (strcmp(instruction.name, "movxmm128") == 0 &&
               instruction.operands[1]->type ==
                       AMD64_ASM_OPERAND_TYPE_SIB_REG) {
        const uint8_t bytes[] = {0x44, 0x0f, 0x10, 0x7c, 0x24, 0x30};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else if (strcmp(instruction.name, "ret") == 0) {
        data[0] = 0xc3;
        *count = 1U;
    } else if (strcmp(instruction.name, "call") == 0) {
        const uint8_t bytes[] = {0xe8, 0x00, 0x00, 0x00, 0x00};
        memcpy(data, bytes, sizeof(bytes));
        *count = sizeof(bytes);
    } else {
        *count = 0U;
        return NULL;
    }
    return &coff_amd64_test_matched_instruction;
}

static void coff_amd64_test_plan_action(uint8_t *bytes, uint8_t kind,
                                        uint8_t reg, uint16_t flags,
                                        uint32_t value) {
    bytes[0] = kind;
    bytes[1] = reg;
    coff_amd64_test_put_u16(bytes + 2U, flags);
    coff_amd64_test_put_u32(bytes + 4U, value);
}

int coff_amd64_run_tests(void) {
    return coff_amd64_test_unwind_object() &&
                           coff_amd64_test_tls_object()
                   ? 0
                   : 1;
}

int main(void) {
    const int result = coff_amd64_run_tests();
    if (result == 0)
        fprintf(stderr, "COFF AMD64 unwind tests passed\n");
    return result;
}

static void coff_write_u32(uint8_t *bytes, uint32_t value) {
    bytes[0] = (uint8_t) value;
    bytes[1] = (uint8_t) (value >> 8U);
    bytes[2] = (uint8_t) (value >> 16U);
    bytes[3] = (uint8_t) (value >> 24U);
}

static coff_writer_status_t coff_fail(coff_object_t *object,
                                      coff_writer_status_t status,
                                      const char *format, ...) {
    if (object) {
        va_list arguments;
        va_start(arguments, format);
        vsnprintf(object->error, sizeof(object->error), format, arguments);
        va_end(arguments);
    }
    return status;
}

static coff_writer_status_t coff_fail_const(const coff_object_t *object,
                                            coff_writer_status_t status,
                                            const char *format, ...) {
    if (object) {
        coff_object_t *mutable_object = (coff_object_t *) object;
        va_list arguments;
        va_start(arguments, format);
        vsnprintf(mutable_object->error, sizeof(mutable_object->error), format,
                  arguments);
        va_end(arguments);
    }
    return status;
}

static bool coff_add_size(size_t left, size_t right, size_t *result) {
    if (!result || right > SIZE_MAX - left) return false;
    *result = left + right;
    return true;
}

static bool coff_mul_size(size_t left, size_t right, size_t *result) {
    if (!result || (left != 0U && right > SIZE_MAX / left)) return false;
    *result = left * right;
    return true;
}

static bool coff_align_size(size_t value, uint32_t alignment,
                            size_t *result) {
    if (!result || !coff_is_power_of_two(alignment)) return false;
    const size_t mask = (size_t) alignment - 1U;
    if (value > SIZE_MAX - mask) return false;
    *result = (value + mask) & ~mask;
    return true;
}

static char *coff_strdup(const char *value) {
    if (!value) return NULL;
    size_t length = strlen(value);
    if (length == SIZE_MAX) return NULL;
    char *copy = malloc(length + 1U);
    if (!copy) return NULL;
    memcpy(copy, value, length + 1U);
    return copy;
}

static bool coff_grow_array(void **array, size_t *capacity, size_t needed,
                            size_t element_size) {
    if (!array || !capacity || element_size == 0U) return false;
    if (needed <= *capacity) return true;
    size_t next = *capacity ? *capacity : 8U;
    while (next < needed) {
        if (next > SIZE_MAX / 2U) {
            next = needed;
            break;
        }
        next *= 2U;
    }
    if (next > SIZE_MAX / element_size) return false;
    void *resized = realloc(*array, next * element_size);
    if (!resized) return false;
    *array = resized;
    *capacity = next;
    return true;
}

static uint32_t coff_alignment_characteristic(uint32_t alignment) {
    if (!coff_is_power_of_two(alignment) || alignment > 8192U) return 0U;
    uint32_t exponent = 0U;
    for (uint32_t value = alignment; value > 1U; value >>= 1U) exponent++;
    return (exponent + 1U) << 20U;
}

static coff_writer_status_t coff_update_section_alignment(
        coff_section_t *section, uint32_t alignment) {
    if (!section || !coff_is_power_of_two(alignment) || alignment > 8192U) {
        return coff_fail(section ? section->object : NULL,
                         COFF_WRITER_INVALID_ARGUMENT,
                         "COFF section alignment must be a power of two "
                         "between 1 and 8192 bytes");
    }
    if (alignment <= section->alignment) return COFF_WRITER_OK;
    section->alignment = alignment;
    section->characteristics &= ~LD_COFF_SCN_ALIGN_MASK;
    section->characteristics |= coff_alignment_characteristic(alignment);
    return COFF_WRITER_OK;
}

static coff_symbol_t *coff_find_symbol_by_raw_index(
        const coff_object_t *object, uint32_t raw_index) {
    if (!object) return NULL;
    for (size_t i = 0U; i < object->symbol_count; i++) {
        if (object->symbols[i].raw_index == raw_index)
            return &object->symbols[i];
    }
    return NULL;
}

static coff_symbol_t *coff_find_symbol_by_name(const coff_object_t *object,
                                               const char *name) {
    if (!object || !name) return NULL;
    for (size_t i = 0U; i < object->symbol_count; i++) {
        if (strcmp(object->symbols[i].name, name) == 0)
            return &object->symbols[i];
    }
    return NULL;
}

static void coff_remove_last_symbol(coff_object_t *object) {
    if (!object || object->symbol_count == 0U) return;
    coff_symbol_t *symbol = &object->symbols[object->symbol_count - 1U];
    object->symbol_record_count = symbol->raw_index;
    free(symbol->name);
    free(symbol->aux_records);
    memset(symbol, 0, sizeof(*symbol));
    object->symbol_count--;
}

static coff_writer_status_t coff_add_symbol_internal(
        coff_object_t *object, const char *name, uint32_t value,
        int32_t section_number, uint16_t type, uint8_t storage_class,
        const coff_aux_record_t *aux_records, uint8_t aux_count,
        uint32_t *symbol_index) {
    if (!object || !name || !coff_symbol_section_number_valid(section_number) ||
        (aux_count != 0U && !aux_records)) {
        return coff_fail(object, COFF_WRITER_INVALID_ARGUMENT,
                         "invalid COFF symbol description");
    }
    const uint64_t new_record_count =
            (uint64_t) object->symbol_record_count + 1U + aux_count;
    if (new_record_count > UINT32_MAX) {
        return coff_fail(object, COFF_WRITER_OVERFLOW,
                         "COFF symbol table exceeds 32-bit record count");
    }
    if (!coff_grow_array((void **) &object->symbols,
                         &object->symbol_capacity, object->symbol_count + 1U,
                         sizeof(*object->symbols))) {
        return coff_fail(object, COFF_WRITER_OUT_OF_MEMORY,
                         "out of memory adding COFF symbol '%s'", name);
    }
    char *name_copy = coff_strdup(name);
    if (!name_copy) {
        return coff_fail(object, COFF_WRITER_OUT_OF_MEMORY,
                         "out of memory copying COFF symbol '%s'", name);
    }
    coff_aux_record_t *aux_copy = NULL;
    if (aux_count != 0U) {
        aux_copy = malloc((size_t) aux_count * sizeof(*aux_copy));
        if (!aux_copy) {
            free(name_copy);
            return coff_fail(object, COFF_WRITER_OUT_OF_MEMORY,
                             "out of memory adding auxiliary records for '%s'",
                             name);
        }
        memcpy(aux_copy, aux_records,
               (size_t) aux_count * sizeof(*aux_copy));
    }
    coff_symbol_t *symbol = &object->symbols[object->symbol_count++];
    memset(symbol, 0, sizeof(*symbol));
    symbol->name = name_copy;
    symbol->value = value;
    symbol->section_number = section_number;
    symbol->type = type;
    symbol->storage_class = storage_class;
    symbol->aux_count = aux_count;
    symbol->aux_records = aux_copy;
    symbol->raw_index = object->symbol_record_count;
    object->symbol_record_count = (uint32_t) new_record_count;
    if (symbol_index) *symbol_index = symbol->raw_index;
    return COFF_WRITER_OK;
}

coff_object_t *coff_object_create(const char *source_name) {
    coff_object_t *object = calloc(1U, sizeof(*object));
    if (!object) return NULL;
    if (source_name) {
        object->source_name = coff_strdup(source_name);
        if (!object->source_name) {
            free(object);
            return NULL;
        }
    }
    return object;
}

coff_object_t *coff_object_create_amd64(const char *source_name) {
    coff_object_t *object = coff_object_create(source_name);
    if (!object) return NULL;
    if (coff_object_add_standard_sections(object) != COFF_WRITER_OK ||
        (source_name && *source_name &&
         coff_object_add_file_symbol(object, source_name, NULL) !=
                 COFF_WRITER_OK)) {
        coff_object_destroy(object);
        return NULL;
    }
    return object;
}

void coff_object_destroy(coff_object_t *object) {
    if (!object) return;
    for (size_t i = 0U; i < object->section_count; i++) {
        coff_section_t *section = object->sections[i];
        if (!section) continue;
        free(section->name);
        free(section->data);
        free(section->relocations);
        free(section);
    }
    for (size_t i = 0U; i < object->symbol_count; i++) {
        free(object->symbols[i].name);
        free(object->symbols[i].aux_records);
    }
    free(object->sections);
    free(object->symbols);
    free(object->source_name);
    free(object);
}

const char *coff_writer_status_string(coff_writer_status_t status) {
    switch (status) {
        case COFF_WRITER_OK:
            return "success";
        case COFF_WRITER_INVALID_ARGUMENT:
            return "invalid argument";
        case COFF_WRITER_OUT_OF_MEMORY:
            return "out of memory";
        case COFF_WRITER_OVERFLOW:
            return "integer or file-format overflow";
        case COFF_WRITER_DUPLICATE:
            return "duplicate definition";
        case COFF_WRITER_INVALID_STATE:
            return "invalid builder state";
        case COFF_WRITER_UNSUPPORTED:
            return "unsupported COFF feature";
        case COFF_WRITER_IO_ERROR:
            return "I/O error";
    }
    return "unknown COFF writer error";
}

coff_writer_status_t coff_object_add_section(
        coff_object_t *object, const char *name, uint32_t characteristics,
        uint32_t alignment, coff_section_t **result) {
    if (!object || !name || !*name || !coff_is_power_of_two(alignment) ||
        alignment > 8192U) {
        return coff_fail(object, COFF_WRITER_INVALID_ARGUMENT,
                         "invalid COFF section name or alignment");
    }
    if (object->section_count >= COFF_MAX_STANDARD_SECTIONS) {
        return coff_fail(object, COFF_WRITER_OVERFLOW,
                         "standard COFF object has too many sections");
    }
    if (coff_object_find_section(object, name)) {
        return coff_fail(object, COFF_WRITER_DUPLICATE,
                         "duplicate COFF section '%s'", name);
    }
    const uint32_t content_kinds =
            characteristics & (LD_COFF_SCN_CNT_CODE |
                               LD_COFF_SCN_CNT_INITIALIZED_DATA |
                               LD_COFF_SCN_CNT_UNINITIALIZED_DATA);
    if (content_kinds != 0U && (content_kinds & (content_kinds - 1U)) != 0U) {
        return coff_fail(object, COFF_WRITER_INVALID_ARGUMENT,
                         "COFF section '%s' has conflicting content kinds",
                         name);
    }
    if (!coff_grow_array((void **) &object->sections,
                         &object->section_capacity, object->section_count + 1U,
                         sizeof(*object->sections))) {
        return coff_fail(object, COFF_WRITER_OUT_OF_MEMORY,
                         "out of memory adding COFF section '%s'", name);
    }
    coff_section_t *section = calloc(1U, sizeof(*section));
    if (!section) {
        return coff_fail(object, COFF_WRITER_OUT_OF_MEMORY,
                         "out of memory adding COFF section '%s'", name);
    }
    section->name = coff_strdup(name);
    if (!section->name) {
        free(section);
        return coff_fail(object, COFF_WRITER_OUT_OF_MEMORY,
                         "out of memory copying COFF section '%s'", name);
    }
    section->object = object;
    section->index = (uint32_t) object->section_count + 1U;
    section->alignment = alignment;
    section->characteristics =
            (characteristics & ~LD_COFF_SCN_ALIGN_MASK) |
            coff_alignment_characteristic(alignment);
    section->uninitialized =
            (characteristics & LD_COFF_SCN_CNT_UNINITIALIZED_DATA) != 0U;
    object->sections[object->section_count++] = section;
    if (result) *result = section;
    return COFF_WRITER_OK;
}

coff_writer_status_t coff_object_add_standard_sections(
        coff_object_t *object) {
    if (!object) return COFF_WRITER_INVALID_ARGUMENT;
    if (object->section_count != 0U) {
        return coff_fail(object, COFF_WRITER_INVALID_STATE,
                         "standard COFF sections must be added to an empty "
                         "object");
    }
    coff_writer_status_t status = coff_object_add_section(
            object, ".text",
            LD_COFF_SCN_CNT_CODE | LD_COFF_SCN_MEM_EXECUTE |
                    LD_COFF_SCN_MEM_READ,
            16U, &object->text);
    if (status == COFF_WRITER_OK)
        status = coff_object_add_section(
                object, ".rdata",
                LD_COFF_SCN_CNT_INITIALIZED_DATA | LD_COFF_SCN_MEM_READ, 8U,
                &object->rdata);
    if (status == COFF_WRITER_OK)
        status = coff_object_add_section(
                object, ".data",
                LD_COFF_SCN_CNT_INITIALIZED_DATA | LD_COFF_SCN_MEM_READ |
                        LD_COFF_SCN_MEM_WRITE,
                8U, &object->data);
    if (status == COFF_WRITER_OK)
        status = coff_object_add_section(
                object, ".bss",
                LD_COFF_SCN_CNT_UNINITIALIZED_DATA | LD_COFF_SCN_MEM_READ |
                        LD_COFF_SCN_MEM_WRITE,
                8U, &object->bss);
    return status;
}

coff_section_t *coff_object_find_section(const coff_object_t *object,
                                         const char *name) {
    if (!object || !name) return NULL;
    for (size_t i = 0U; i < object->section_count; i++) {
        if (strcmp(object->sections[i]->name, name) == 0)
            return object->sections[i];
    }
    return NULL;
}

coff_writer_status_t coff_section_append(
        coff_section_t *section, const void *data, size_t size,
        uint32_t alignment, uint32_t *offset) {
    if (!section || (section->uninitialized && data) ||
        !coff_is_power_of_two(alignment) || alignment > 8192U) {
        return coff_fail(section ? section->object : NULL,
                         COFF_WRITER_INVALID_ARGUMENT,
                         "invalid append to COFF section");
    }
    size_t aligned;
    if (!coff_align_size(section->logical_size, alignment, &aligned) ||
        size > UINT32_MAX || aligned > UINT32_MAX - size) {
        return coff_fail(section->object, COFF_WRITER_OVERFLOW,
                         "COFF section '%s' exceeds 4 GiB", section->name);
    }
    const size_t end = aligned + size;
    coff_writer_status_t status =
            coff_update_section_alignment(section, alignment);
    if (status != COFF_WRITER_OK) return status;
    if (!section->uninitialized && end != 0U) {
        if (!coff_grow_array((void **) &section->data,
                             &section->data_capacity, end, sizeof(uint8_t))) {
            return coff_fail(section->object, COFF_WRITER_OUT_OF_MEMORY,
                             "out of memory growing COFF section '%s'",
                             section->name);
        }
        if (aligned > section->logical_size) {
            memset(section->data + section->logical_size, 0,
                   aligned - section->logical_size);
        }
        if (size != 0U) {
            if (data)
                memcpy(section->data + aligned, data, size);
            else
                memset(section->data + aligned, 0, size);
        }
    }
    section->logical_size = (uint32_t) end;
    if (offset) *offset = (uint32_t) aligned;
    return COFF_WRITER_OK;
}

coff_writer_status_t coff_section_append_zeros(
        coff_section_t *section, size_t size, uint32_t alignment,
        uint32_t *offset) {
    return coff_section_append(section, NULL, size, alignment, offset);
}

coff_writer_status_t coff_section_write(
        coff_section_t *section, uint32_t offset, const void *data,
        size_t size) {
    if (!section || (!data && size != 0U) || section->uninitialized ||
        offset > section->logical_size ||
        size > (size_t) section->logical_size - offset) {
        return coff_fail(section ? section->object : NULL,
                         COFF_WRITER_INVALID_ARGUMENT,
                         "invalid write to COFF section");
    }
    if (size != 0U) memcpy(section->data + offset, data, size);
    return COFF_WRITER_OK;
}

coff_writer_status_t coff_object_add_symbol(
        coff_object_t *object, const coff_symbol_desc_t *symbol,
        uint32_t *symbol_index) {
    if (!object || !symbol || !symbol->name ||
        (symbol->aux_count != 0U && !symbol->aux_records)) {
        return coff_fail(object, COFF_WRITER_INVALID_ARGUMENT,
                         "invalid raw COFF symbol");
    }
    coff_aux_record_t *aux = NULL;
    if (symbol->aux_count != 0U) {
        aux = calloc(symbol->aux_count, sizeof(*aux));
        if (!aux) {
            return coff_fail(object, COFF_WRITER_OUT_OF_MEMORY,
                             "out of memory decoding auxiliary records");
        }
        for (uint8_t i = 0U; i < symbol->aux_count; i++) {
            aux[i].kind = COFF_AUX_RAW;
            memcpy(aux[i].value.raw,
                   symbol->aux_records + (size_t) i * LD_COFF_SYMBOL_SIZE,
                   LD_COFF_SYMBOL_SIZE);
        }
    }
    coff_writer_status_t status = coff_add_symbol_internal(
            object, symbol->name, symbol->value, symbol->section_number,
            symbol->type, symbol->storage_class, aux, symbol->aux_count,
            symbol_index);
    free(aux);
    return status;
}

coff_writer_status_t coff_object_add_defined_symbol(
        coff_object_t *object, const char *name, coff_section_t *section,
        uint32_t value, uint16_t type, uint8_t storage_class,
        uint32_t *symbol_index) {
    if (!object || !name || !section || section->object != object ||
        value > section->logical_size) {
        return coff_fail(object, COFF_WRITER_INVALID_ARGUMENT,
                         "invalid defined COFF symbol '%s'",
                         name ? name : "");
    }
    return coff_add_symbol_internal(object, name, value,
                                    (int32_t) section->index, type,
                                    storage_class, NULL, 0U, symbol_index);
}

coff_writer_status_t coff_object_define_symbol(
        coff_object_t *object, const char *name, coff_section_t *section,
        uint32_t value, uint16_t type, uint8_t storage_class,
        uint32_t *symbol_index) {
    if (!object || !name || !section || section->object != object ||
        value > section->logical_size) {
        return coff_fail(object, COFF_WRITER_INVALID_ARGUMENT,
                         "invalid COFF symbol definition '%s'",
                         name ? name : "");
    }
    coff_symbol_t *symbol = coff_find_symbol_by_name(object, name);
    if (!symbol) {
        return coff_object_add_defined_symbol(object, name, section, value,
                                              type, storage_class,
                                              symbol_index);
    }
    if (symbol->section_number != LD_COFF_SYM_UNDEFINED ||
        symbol->aux_count != 0U) {
        if (symbol->section_number == (int32_t) section->index &&
            symbol->value == value && symbol->type == type &&
            symbol->storage_class == storage_class) {
            if (symbol_index) *symbol_index = symbol->raw_index;
            return COFF_WRITER_OK;
        }
        return coff_fail(object, COFF_WRITER_DUPLICATE,
                         "duplicate COFF symbol definition '%s'", name);
    }
    if (symbol->storage_class != storage_class &&
        symbol->storage_class != LD_COFF_STORAGE_CLASS_EXTERNAL) {
        return coff_fail(object, COFF_WRITER_DUPLICATE,
                         "COFF symbol '%s' changes storage class", name);
    }
    symbol->section_number = (int32_t) section->index;
    symbol->value = value;
    symbol->type = type;
    symbol->storage_class = storage_class;
    if (symbol_index) *symbol_index = symbol->raw_index;
    return COFF_WRITER_OK;
}

coff_writer_status_t coff_object_get_or_add_symbol_reference(
        coff_object_t *object, const char *name, bool external, uint16_t type,
        uint32_t *symbol_index) {
    if (!object || !name || !*name) {
        return coff_fail(object, COFF_WRITER_INVALID_ARGUMENT,
                         "invalid COFF symbol reference");
    }
    coff_symbol_t *symbol = coff_find_symbol_by_name(object, name);
    if (symbol) {
        if (symbol_index) *symbol_index = symbol->raw_index;
        return COFF_WRITER_OK;
    }
    return coff_add_symbol_internal(
            object, name, 0U, LD_COFF_SYM_UNDEFINED, type,
            external ? LD_COFF_STORAGE_CLASS_EXTERNAL
                     : LD_COFF_STORAGE_CLASS_STATIC,
            NULL, 0U, symbol_index);
}

bool coff_object_find_symbol(const coff_object_t *object, const char *name,
                             uint32_t *symbol_index) {
    coff_symbol_t *symbol = coff_find_symbol_by_name(object, name);
    if (!symbol) return false;
    if (symbol_index) *symbol_index = symbol->raw_index;
    return true;
}

coff_writer_status_t coff_object_add_file_symbol(coff_object_t *object,
                                                 const char *file_name,
                                                 uint32_t *symbol_index) {
    if (!object || !file_name || !*file_name) {
        return coff_fail(object, COFF_WRITER_INVALID_ARGUMENT,
                         "COFF file symbol has an empty filename");
    }
    const size_t length = strlen(file_name);
    size_t count = (length + LD_COFF_SYMBOL_SIZE - 1U) /
                   LD_COFF_SYMBOL_SIZE;
    if (count == 0U) count = 1U;
    if (count > UINT8_MAX) {
        return coff_fail(object, COFF_WRITER_OVERFLOW,
                         "COFF file symbol filename is too long");
    }
    size_t raw_size;
    if (!coff_mul_size(count, LD_COFF_SYMBOL_SIZE, &raw_size)) {
        return coff_fail(object, COFF_WRITER_OVERFLOW,
                         "COFF file symbol auxiliary size overflows");
    }
    uint8_t *raw = calloc(1U, raw_size);
    coff_aux_record_t *aux = calloc(count, sizeof(*aux));
    if (!raw || !aux) {
        free(raw);
        free(aux);
        return coff_fail(object, COFF_WRITER_OUT_OF_MEMORY,
                         "out of memory creating COFF file symbol");
    }
    memcpy(raw, file_name, length);
    for (size_t i = 0U; i < count; i++) {
        aux[i].kind = COFF_AUX_RAW;
        memcpy(aux[i].value.raw, raw + i * LD_COFF_SYMBOL_SIZE,
               LD_COFF_SYMBOL_SIZE);
    }
    coff_writer_status_t status = coff_add_symbol_internal(
            object, ".file", 0U, LD_COFF_SYM_DEBUG, 0U,
            LD_COFF_STORAGE_CLASS_FILE, aux, (uint8_t) count, symbol_index);
    free(raw);
    free(aux);
    return status;
}

coff_writer_status_t coff_object_add_weak_external(
        coff_object_t *object, const char *name,
        uint32_t fallback_symbol_index, uint32_t search_characteristics,
        uint32_t *symbol_index) {
    if (!object || !name || !*name ||
        !coff_find_symbol_by_raw_index(object, fallback_symbol_index) ||
        search_characteristics < LD_COFF_WEAK_SEARCH_NOLIBRARY ||
        search_characteristics > LD_COFF_WEAK_ANTI_DEPENDENCY) {
        return coff_fail(object, COFF_WRITER_INVALID_ARGUMENT,
                         "invalid weak external COFF symbol");
    }
    if (coff_find_symbol_by_name(object, name)) {
        return coff_fail(object, COFF_WRITER_DUPLICATE,
                         "duplicate weak external COFF symbol '%s'", name);
    }
    coff_aux_record_t aux;
    memset(&aux, 0, sizeof(aux));
    aux.kind = COFF_AUX_WEAK_EXTERNAL;
    aux.value.weak_external.fallback_symbol_index = fallback_symbol_index;
    aux.value.weak_external.characteristics = search_characteristics;
    return coff_add_symbol_internal(
            object, name, 0U, LD_COFF_SYM_UNDEFINED, 0U,
            LD_COFF_STORAGE_CLASS_WEAK_EXTERNAL, &aux, 1U, symbol_index);
}

coff_writer_status_t coff_object_mark_comdat(
        coff_object_t *object, coff_section_t *section, uint8_t selection,
        coff_section_t *associative_parent, const char *leader_name,
        uint32_t checksum, uint32_t *section_symbol_index,
        uint32_t *leader_symbol_index) {
    if (section_symbol_index)
        *section_symbol_index = COFF_SYMBOL_INDEX_NONE;
    if (leader_symbol_index) *leader_symbol_index = COFF_SYMBOL_INDEX_NONE;
    if (!object || !section || section->object != object || section->comdat ||
        selection < LD_COFF_COMDAT_NODUPLICATES ||
        selection > LD_COFF_COMDAT_LARGEST) {
        return coff_fail(object, COFF_WRITER_INVALID_ARGUMENT,
                         "invalid COFF COMDAT description");
    }
    if (selection == LD_COFF_COMDAT_ASSOCIATIVE) {
        if (!associative_parent || associative_parent->object != object ||
            associative_parent == section) {
            return coff_fail(object, COFF_WRITER_INVALID_ARGUMENT,
                             "associative COFF COMDAT has invalid parent");
        }
    } else if (associative_parent || !leader_name || !*leader_name) {
        return coff_fail(object, COFF_WRITER_INVALID_ARGUMENT,
                         "non-associative COFF COMDAT requires a leader");
    }
    if (selection != LD_COFF_COMDAT_ASSOCIATIVE &&
        coff_find_symbol_by_name(object, leader_name)) {
        return coff_fail(object, COFF_WRITER_DUPLICATE,
                         "duplicate COFF COMDAT leader '%s'", leader_name);
    }

    coff_aux_record_t aux;
    memset(&aux, 0, sizeof(aux));
    aux.kind = COFF_AUX_SECTION_DEFINITION;
    aux.value.section_definition.section = section;
    aux.value.section_definition.associative_parent = associative_parent;
    aux.value.section_definition.checksum = checksum;
    aux.value.section_definition.selection = selection;

    coff_writer_status_t status = coff_add_symbol_internal(
            object, section->name, 0U, (int32_t) section->index, 0U,
            LD_COFF_STORAGE_CLASS_STATIC, &aux, 1U,
            section_symbol_index);
    if (status != COFF_WRITER_OK) return status;

    section->comdat = true;
    section->characteristics |= LD_COFF_SCN_LNK_COMDAT;
    if (selection != LD_COFF_COMDAT_ASSOCIATIVE) {
        status = coff_object_add_defined_symbol(
                object, leader_name, section, 0U, 0U,
                LD_COFF_STORAGE_CLASS_EXTERNAL, leader_symbol_index);
        if (status != COFF_WRITER_OK) {
            coff_remove_last_symbol(object);
            section->comdat = false;
            section->characteristics &= ~LD_COFF_SCN_LNK_COMDAT;
            if (section_symbol_index)
                *section_symbol_index = COFF_SYMBOL_INDEX_NONE;
        }
    }
    return status;
}

static size_t coff_relocation_width(uint16_t type) {
    switch (type) {
        case LD_COFF_REL_AMD64_ABSOLUTE:
            return 0U;
        case LD_COFF_REL_AMD64_ADDR64:
            return 8U;
        case LD_COFF_REL_AMD64_SECTION:
            return 2U;
        case LD_COFF_REL_AMD64_ADDR32:
        case LD_COFF_REL_AMD64_ADDR32NB:
        case LD_COFF_REL_AMD64_REL32:
        case LD_COFF_REL_AMD64_REL32_1:
        case LD_COFF_REL_AMD64_REL32_2:
        case LD_COFF_REL_AMD64_REL32_3:
        case LD_COFF_REL_AMD64_REL32_4:
        case LD_COFF_REL_AMD64_REL32_5:
        case LD_COFF_REL_AMD64_SECREL:
            return 4U;
        default:
            return SIZE_MAX;
    }
}

static coff_writer_status_t coff_validate_relocation(
        coff_section_t *section, uint32_t offset, uint32_t symbol_index,
        uint16_t type) {
    if (!section || section->uninitialized) {
        return coff_fail(section ? section->object : NULL,
                         COFF_WRITER_INVALID_ARGUMENT,
                         "COFF relocation cannot target uninitialized data");
    }
    const size_t width = coff_relocation_width(type);
    if (width == SIZE_MAX) {
        return coff_fail(section->object, COFF_WRITER_UNSUPPORTED,
                         "unsupported AMD64 COFF relocation 0x%x", type);
    }
    if (!coff_find_symbol_by_raw_index(section->object, symbol_index)) {
        return coff_fail(section->object, COFF_WRITER_INVALID_ARGUMENT,
                         "COFF relocation references auxiliary or missing "
                         "symbol index %u",
                         symbol_index);
    }
    if (offset > section->logical_size ||
        width > (size_t) section->logical_size - offset) {
        return coff_fail(section->object, COFF_WRITER_INVALID_ARGUMENT,
                         "COFF relocation field extends past section '%s'",
                         section->name);
    }
    if (section->relocation_count >= UINT32_MAX - 1U) {
        return coff_fail(section->object, COFF_WRITER_OVERFLOW,
                         "COFF relocation count exceeds overflow format");
    }
    return COFF_WRITER_OK;
}

coff_writer_status_t coff_section_add_relocation(
        coff_section_t *section, uint32_t offset, uint32_t symbol_index,
        uint16_t type) {
    coff_writer_status_t status =
            coff_validate_relocation(section, offset, symbol_index, type);
    if (status != COFF_WRITER_OK) return status;
    if (!coff_grow_array((void **) &section->relocations,
                         &section->relocation_capacity,
                         section->relocation_count + 1U,
                         sizeof(*section->relocations))) {
        return coff_fail(section->object, COFF_WRITER_OUT_OF_MEMORY,
                         "out of memory adding relocation to '%s'",
                         section->name);
    }
    coff_relocation_t *relocation =
            &section->relocations[section->relocation_count++];
    relocation->offset = offset;
    relocation->symbol_index = symbol_index;
    relocation->type = type;
    return COFF_WRITER_OK;
}

coff_writer_status_t coff_section_add_relocation_with_addend(
        coff_section_t *section, uint32_t offset, uint32_t symbol_index,
        uint16_t type, int64_t implicit_addend) {
    coff_writer_status_t status =
            coff_validate_relocation(section, offset, symbol_index, type);
    if (status != COFF_WRITER_OK) return status;
    const size_t width = coff_relocation_width(type);
    uint8_t encoded[8] = {0};
    if (width == 0U) {
        if (implicit_addend != 0) {
            return coff_fail(section->object, COFF_WRITER_INVALID_ARGUMENT,
                             "ABSOLUTE relocation cannot carry an addend");
        }
    } else if (width == 2U) {
        if (implicit_addend < INT16_MIN || implicit_addend > UINT16_MAX) {
            return coff_fail(section->object, COFF_WRITER_OVERFLOW,
                             "16-bit COFF relocation addend overflows");
        }
        coff_write_u16(encoded, (uint16_t) implicit_addend);
    } else if (width == 4U) {
        if (implicit_addend < INT32_MIN || implicit_addend > UINT32_MAX) {
            return coff_fail(section->object, COFF_WRITER_OVERFLOW,
                             "32-bit COFF relocation addend overflows");
        }
        coff_write_u32(encoded, (uint32_t) implicit_addend);
    } else {
        coff_write_u64(encoded, (uint64_t) implicit_addend);
    }
    if (width != 0U) memcpy(section->data + offset, encoded, width);
    return coff_section_add_relocation(section, offset, symbol_index, type);
}

static void coff_string_table_deinit(coff_string_table_t *table) {
    if (!table) return;
    free(table->names);
    free(table->offsets);
    free(table->bytes);
    memset(table, 0, sizeof(*table));
}

static coff_writer_status_t coff_string_table_init(
        coff_string_table_t *table, const coff_object_t *object) {
    memset(table, 0, sizeof(*table));
    table->bytes = calloc(1U, 4U);
    if (!table->bytes) {
        return coff_fail_const(object, COFF_WRITER_OUT_OF_MEMORY,
                               "out of memory creating COFF string table");
    }
    table->size = 4U;
    table->capacity_bytes = 4U;
    return COFF_WRITER_OK;
}

static coff_writer_status_t coff_string_table_add(
        coff_string_table_t *table, const coff_object_t *object,
        const char *name, uint32_t *offset) {
    if (!table || !object || !name || !offset) {
        return coff_fail_const(object, COFF_WRITER_INVALID_ARGUMENT,
                               "invalid COFF string-table entry");
    }
    for (size_t i = 0U; i < table->count; i++) {
        if (strcmp(table->names[i], name) == 0) {
            *offset = table->offsets[i];
            return COFF_WRITER_OK;
        }
    }
    const size_t length = strlen(name) + 1U;
    size_t next_size;
    if (!coff_add_size(table->size, length, &next_size) ||
        next_size > UINT32_MAX) {
        return coff_fail_const(object, COFF_WRITER_OVERFLOW,
                               "COFF string table exceeds 4 GiB");
    }
    if (!coff_grow_array((void **) &table->bytes,
                         &table->capacity_bytes, next_size, sizeof(uint8_t))) {
        return coff_fail_const(object, COFF_WRITER_OUT_OF_MEMORY,
                               "out of memory growing COFF string table");
    }
    const size_t needed = table->count + 1U;
    if (needed > table->capacity) {
        size_t next = table->capacity ? table->capacity * 2U : 8U;
        if (next < needed) next = needed;
        if (next > SIZE_MAX / sizeof(*table->names) ||
            next > SIZE_MAX / sizeof(*table->offsets)) {
            return coff_fail_const(object, COFF_WRITER_OVERFLOW,
                                   "COFF string-table index overflows");
        }
        const char **new_names = malloc(next * sizeof(*table->names));
        uint32_t *new_offsets = malloc(next * sizeof(*table->offsets));
        if (!new_names || !new_offsets) {
            free(new_names);
            free(new_offsets);
            return coff_fail_const(object, COFF_WRITER_OUT_OF_MEMORY,
                                   "out of memory indexing COFF strings");
        }
        if (table->count != 0U) {
            memcpy(new_names, table->names,
                   table->count * sizeof(*table->names));
            memcpy(new_offsets, table->offsets,
                   table->count * sizeof(*table->offsets));
        }
        free(table->names);
        free(table->offsets);
        table->names = new_names;
        table->offsets = new_offsets;
        table->capacity = next;
    }
    const uint32_t new_offset = (uint32_t) table->size;
    memcpy(table->bytes + table->size, name, length);
    table->names[table->count] = name;
    table->offsets[table->count] = new_offset;
    table->count++;
    table->size = next_size;
    *offset = new_offset;
    return COFF_WRITER_OK;
}

static coff_writer_status_t coff_build_string_table(
        const coff_object_t *object, coff_string_table_t *table) {
    coff_writer_status_t status = coff_string_table_init(table, object);
    if (status != COFF_WRITER_OK) return status;
    uint32_t ignored;
    for (size_t i = 0U; i < object->section_count; i++) {
        if (strlen(object->sections[i]->name) > LD_COFF_NAME_SIZE) {
            status = coff_string_table_add(table, object,
                                           object->sections[i]->name,
                                           &ignored);
            if (status != COFF_WRITER_OK) return status;
        }
    }
    for (size_t i = 0U; i < object->symbol_count; i++) {
        if (strlen(object->symbols[i].name) > LD_COFF_NAME_SIZE) {
            status = coff_string_table_add(table, object,
                                           object->symbols[i].name,
                                           &ignored);
            if (status != COFF_WRITER_OK) return status;
        }
    }
    coff_write_u32(table->bytes, (uint32_t) table->size);
    return COFF_WRITER_OK;
}

static bool coff_string_table_find(const coff_string_table_t *table,
                                   const char *name, uint32_t *offset) {
    for (size_t i = 0U; table && i < table->count; i++) {
        if (strcmp(table->names[i], name) == 0) {
            if (offset) *offset = table->offsets[i];
            return true;
        }
    }
    return false;
}

static coff_writer_status_t coff_encode_section_name(
        const coff_object_t *object, const coff_string_table_t *strings,
        const char *name, uint8_t destination[LD_COFF_NAME_SIZE]) {
    memset(destination, 0, LD_COFF_NAME_SIZE);
    const size_t length = strlen(name);
    if (length <= LD_COFF_NAME_SIZE) {
        memcpy(destination, name, length);
        return COFF_WRITER_OK;
    }
    uint32_t offset;
    if (!coff_string_table_find(strings, name, &offset)) {
        return coff_fail_const(object, COFF_WRITER_INVALID_STATE,
                               "missing long COFF section name '%s'", name);
    }
    char encoded[LD_COFF_NAME_SIZE + 1U];
    const int count = snprintf(encoded, sizeof(encoded), "/%u", offset);
    if (count <= 0 || count > LD_COFF_NAME_SIZE) {
        return coff_fail_const(
                object, COFF_WRITER_OVERFLOW,
                "long COFF section-name offset cannot fit in 8 bytes");
    }
    memcpy(destination, encoded, (size_t) count);
    return COFF_WRITER_OK;
}

static coff_writer_status_t coff_encode_symbol_name(
        const coff_object_t *object, const coff_string_table_t *strings,
        const char *name, uint8_t destination[LD_COFF_NAME_SIZE]) {
    memset(destination, 0, LD_COFF_NAME_SIZE);
    const size_t length = strlen(name);
    if (length <= LD_COFF_NAME_SIZE) {
        memcpy(destination, name, length);
        return COFF_WRITER_OK;
    }
    uint32_t offset;
    if (!coff_string_table_find(strings, name, &offset)) {
        return coff_fail_const(object, COFF_WRITER_INVALID_STATE,
                               "missing long COFF symbol name '%s'", name);
    }
    coff_write_u32(destination, 0U);
    coff_write_u32(destination + 4U, offset);
    return COFF_WRITER_OK;
}

static coff_writer_status_t coff_validate_for_serialization(
        const coff_object_t *object) {
    if (!object) return COFF_WRITER_INVALID_ARGUMENT;
    if (object->section_count > COFF_MAX_STANDARD_SECTIONS ||
        object->section_count > UINT16_MAX) {
        return coff_fail_const(object, COFF_WRITER_OVERFLOW,
                               "standard COFF section count overflows");
    }
    for (size_t i = 0U; i < object->symbol_count; i++) {
        const coff_symbol_t *symbol = &object->symbols[i];
        if (symbol->section_number > 0 &&
            (uint32_t) symbol->section_number > object->section_count) {
            return coff_fail_const(object, COFF_WRITER_INVALID_STATE,
                                   "COFF symbol '%s' names a missing section",
                                   symbol->name);
        }
        if (symbol->section_number == LD_COFF_SYM_UNDEFINED &&
            symbol->storage_class == LD_COFF_STORAGE_CLASS_STATIC) {
            return coff_fail_const(
                    object, COFF_WRITER_INVALID_STATE,
                    "local COFF symbol '%s' was referenced but never defined",
                    symbol->name);
        }
    }
    return COFF_WRITER_OK;
}

static coff_writer_status_t coff_assign_layout(
        const coff_object_t *object, coff_section_layout_t *layouts,
        size_t *symbol_table_offset, size_t string_table_size,
        size_t *file_size) {
    size_t section_headers_size;
    if (!coff_mul_size(object->section_count, LD_COFF_SECTION_HEADER_SIZE,
                       &section_headers_size)) {
        return coff_fail_const(object, COFF_WRITER_OVERFLOW,
                               "COFF section-header table size overflows");
    }
    size_t cursor;
    if (!coff_add_size(LD_COFF_HEADER_SIZE, section_headers_size, &cursor)) {
        return coff_fail_const(object, COFF_WRITER_OVERFLOW,
                               "COFF object header size overflows");
    }
    for (size_t i = 0U; i < object->section_count; i++) {
        const coff_section_t *section = object->sections[i];
        coff_section_layout_t *layout = &layouts[i];
        memset(layout, 0, sizeof(*layout));
        layout->characteristics = section->characteristics;
        if (!section->uninitialized && section->logical_size != 0U) {
            if (cursor > UINT32_MAX) {
                return coff_fail_const(object, COFF_WRITER_OVERFLOW,
                                       "COFF raw-data pointer overflows");
            }
            layout->raw_pointer = (uint32_t) cursor;
            if (!coff_add_size(cursor, section->logical_size, &cursor)) {
                return coff_fail_const(object, COFF_WRITER_OVERFLOW,
                                       "COFF raw-data size overflows");
            }
        }
        if (section->relocation_count != 0U) {
            if (cursor > UINT32_MAX) {
                return coff_fail_const(object, COFF_WRITER_OVERFLOW,
                                       "COFF relocation pointer overflows");
            }
            layout->relocation_pointer = (uint32_t) cursor;
            const bool overflow = section->relocation_count >= UINT16_MAX;
            layout->relocation_count =
                    overflow ? UINT16_MAX
                             : (uint16_t) section->relocation_count;
            if (overflow)
                layout->characteristics |= LD_COFF_SCN_LNK_NRELOC_OVFL;
            const size_t record_count =
                    section->relocation_count + (overflow ? 1U : 0U);
            size_t relocation_size;
            if (!coff_mul_size(record_count, LD_COFF_RELOCATION_SIZE,
                               &relocation_size) ||
                !coff_add_size(cursor, relocation_size, &cursor)) {
                return coff_fail_const(object, COFF_WRITER_OVERFLOW,
                                       "COFF relocation table size overflows");
            }
        }
    }
    if (cursor > UINT32_MAX) {
        return coff_fail_const(object, COFF_WRITER_OVERFLOW,
                               "COFF symbol-table pointer overflows");
    }
    *symbol_table_offset = cursor;
    size_t symbol_bytes;
    if (!coff_mul_size(object->symbol_record_count, LD_COFF_SYMBOL_SIZE,
                       &symbol_bytes) ||
        !coff_add_size(cursor, symbol_bytes, &cursor) ||
        !coff_add_size(cursor, string_table_size, &cursor)) {
        return coff_fail_const(object, COFF_WRITER_OVERFLOW,
                               "COFF symbol or string table size overflows");
    }
    if (cursor > UINT32_MAX) {
        return coff_fail_const(object, COFF_WRITER_OVERFLOW,
                               "standard COFF object exceeds 4 GiB");
    }
    *file_size = cursor;
    return COFF_WRITER_OK;
}

static void coff_encode_aux_record(const coff_aux_record_t *aux,
                                   uint8_t bytes[LD_COFF_SYMBOL_SIZE]) {
    memset(bytes, 0, LD_COFF_SYMBOL_SIZE);
    switch (aux->kind) {
        case COFF_AUX_RAW:
            memcpy(bytes, aux->value.raw, LD_COFF_SYMBOL_SIZE);
            break;
        case COFF_AUX_SECTION_DEFINITION: {
            const coff_section_t *section =
                    aux->value.section_definition.section;
            coff_write_u32(bytes, section->logical_size);
            const uint16_t relocation_count =
                    section->relocation_count >= UINT16_MAX
                            ? UINT16_MAX
                            : (uint16_t) section->relocation_count;
            coff_write_u16(bytes + 4U, relocation_count);
            coff_write_u16(bytes + 6U, 0U);
            coff_write_u32(bytes + 8U,
                           aux->value.section_definition.checksum);
            uint32_t number = 0U;
            if (aux->value.section_definition.associative_parent)
                number = aux->value.section_definition.associative_parent
                                 ->index;
            coff_write_u16(bytes + 12U, (uint16_t) number);
            bytes[14] = aux->value.section_definition.selection;
            bytes[15] = 0U;
            coff_write_u16(bytes + 16U, 0U);
            break;
        }
        case COFF_AUX_WEAK_EXTERNAL:
            coff_write_u32(
                    bytes,
                    aux->value.weak_external.fallback_symbol_index);
            coff_write_u32(bytes + 4U,
                           aux->value.weak_external.characteristics);
            break;
    }
}

coff_writer_status_t coff_object_serialize(const coff_object_t *object,
                                           uint8_t **image,
                                           size_t *image_size) {
    if (!object || !image || !image_size) {
        return coff_fail_const(object, COFF_WRITER_INVALID_ARGUMENT,
                               "invalid COFF serialization output");
    }
    *image = NULL;
    *image_size = 0U;
    coff_writer_status_t status = coff_validate_for_serialization(object);
    if (status != COFF_WRITER_OK) return status;

    coff_string_table_t strings;
    status = coff_build_string_table(object, &strings);
    if (status != COFF_WRITER_OK) {
        coff_string_table_deinit(&strings);
        return status;
    }
    coff_section_layout_t *layouts = NULL;
    if (object->section_count != 0U) {
        layouts = calloc(object->section_count, sizeof(*layouts));
        if (!layouts) {
            coff_string_table_deinit(&strings);
            return coff_fail_const(object, COFF_WRITER_OUT_OF_MEMORY,
                                   "out of memory laying out COFF sections");
        }
    }
    size_t symbol_table_offset = 0U;
    size_t total_size = 0U;
    status = coff_assign_layout(object, layouts, &symbol_table_offset,
                                strings.size, &total_size);
    if (status != COFF_WRITER_OK) {
        free(layouts);
        coff_string_table_deinit(&strings);
        return status;
    }
    uint8_t *bytes = calloc(1U, total_size ? total_size : 1U);
    if (!bytes) {
        free(layouts);
        coff_string_table_deinit(&strings);
        return coff_fail_const(object, COFF_WRITER_OUT_OF_MEMORY,
                               "out of memory creating COFF image");
    }

    coff_write_u16(bytes, LD_COFF_MACHINE_AMD64);
    coff_write_u16(bytes + 2U, (uint16_t) object->section_count);
    coff_write_u32(bytes + 4U, 0U);
    coff_write_u32(bytes + 8U, (uint32_t) symbol_table_offset);
    coff_write_u32(bytes + 12U, object->symbol_record_count);
    coff_write_u16(bytes + 16U, 0U);
    coff_write_u16(bytes + 18U, 0U);

    for (size_t i = 0U; i < object->section_count; i++) {
        const coff_section_t *section = object->sections[i];
        const coff_section_layout_t *layout = &layouts[i];
        uint8_t *header = bytes + LD_COFF_HEADER_SIZE +
                          i * LD_COFF_SECTION_HEADER_SIZE;
        status = coff_encode_section_name(object, &strings, section->name,
                                          header);
        if (status != COFF_WRITER_OK) goto fail;
        coff_write_u32(header + 8U, 0U);
        coff_write_u32(header + 12U, 0U);
        coff_write_u32(header + 16U, section->logical_size);
        coff_write_u32(header + 20U, layout->raw_pointer);
        coff_write_u32(header + 24U, layout->relocation_pointer);
        coff_write_u32(header + 28U, 0U);
        coff_write_u16(header + 32U, layout->relocation_count);
        coff_write_u16(header + 34U, 0U);
        coff_write_u32(header + 36U, layout->characteristics);

        if (layout->raw_pointer != 0U && section->logical_size != 0U)
            memcpy(bytes + layout->raw_pointer, section->data,
                   section->logical_size);
        if (layout->relocation_pointer != 0U) {
            uint8_t *relocation_bytes = bytes + layout->relocation_pointer;
            if (section->relocation_count >= UINT16_MAX) {
                coff_write_u32(relocation_bytes,
                               (uint32_t) section->relocation_count + 1U);
                coff_write_u32(relocation_bytes + 4U, 0U);
                coff_write_u16(relocation_bytes + 8U, 0U);
                relocation_bytes += LD_COFF_RELOCATION_SIZE;
            }
            for (size_t j = 0U; j < section->relocation_count; j++) {
                const coff_relocation_t *relocation =
                        &section->relocations[j];
                coff_write_u32(relocation_bytes, relocation->offset);
                coff_write_u32(relocation_bytes + 4U,
                               relocation->symbol_index);
                coff_write_u16(relocation_bytes + 8U, relocation->type);
                relocation_bytes += LD_COFF_RELOCATION_SIZE;
            }
        }
    }

    uint8_t *symbol_bytes = bytes + symbol_table_offset;
    for (size_t i = 0U; i < object->symbol_count; i++) {
        const coff_symbol_t *symbol = &object->symbols[i];
        status = coff_encode_symbol_name(object, &strings, symbol->name,
                                         symbol_bytes);
        if (status != COFF_WRITER_OK) goto fail;
        coff_write_u32(symbol_bytes + 8U, symbol->value);
        coff_write_u16(symbol_bytes + 12U,
                       (uint16_t) symbol->section_number);
        coff_write_u16(symbol_bytes + 14U, symbol->type);
        symbol_bytes[16] = symbol->storage_class;
        symbol_bytes[17] = symbol->aux_count;
        symbol_bytes += LD_COFF_SYMBOL_SIZE;
        for (uint8_t j = 0U; j < symbol->aux_count; j++) {
            coff_encode_aux_record(&symbol->aux_records[j], symbol_bytes);
            symbol_bytes += LD_COFF_SYMBOL_SIZE;
        }
    }
    memcpy(symbol_bytes, strings.bytes, strings.size);

    free(layouts);
    coff_string_table_deinit(&strings);
    *image = bytes;
    *image_size = total_size;
    return COFF_WRITER_OK;

fail:
    free(bytes);
    free(layouts);
    coff_string_table_deinit(&strings);
    return status;
}

coff_writer_status_t coff_object_write_file(const coff_object_t *object,
                                            const char *path) {
    if (!object || !path || !*path) {
        return coff_fail_const(object, COFF_WRITER_INVALID_ARGUMENT,
                               "COFF output path is empty");
    }
    uint8_t *image = NULL;
    size_t image_size = 0U;
    coff_writer_status_t status =
            coff_object_serialize(object, &image, &image_size);
    if (status != COFF_WRITER_OK) return status;
    FILE *file = fopen(path, "wb");
    if (!file) {
        free(image);
        return coff_fail_const(object, COFF_WRITER_IO_ERROR,
                               "cannot open COFF output '%s': %s", path,
                               strerror(errno));
    }
    size_t written = 0U;
    while (written < image_size) {
        size_t count = fwrite(image + written, 1U, image_size - written, file);
        if (count == 0U) {
            status = coff_fail_const(object, COFF_WRITER_IO_ERROR,
                                     "cannot write COFF output '%s'", path);
            break;
        }
        written += count;
    }
    if (fclose(file) != 0 && status == COFF_WRITER_OK) {
        status = coff_fail_const(object, COFF_WRITER_IO_ERROR,
                                 "cannot close COFF output '%s': %s", path,
                                 strerror(errno));
    }
    free(image);
    return status;
}

void *ld_coff_grow(void *items, size_t old_count, size_t new_count,
                   size_t item_size) {
    if (item_size == 0U || new_count > SIZE_MAX / item_size) return NULL;
    void *result = realloc(items, new_count * item_size);
    if (result && new_count > old_count) {
        memset((uint8_t *) result + old_count * item_size, 0,
               (new_count - old_count) * item_size);
    }
    return result;
}

char *ld_coff_strndup(const char *text, size_t length) {
    if (!text || length == SIZE_MAX) return NULL;
    char *result = malloc(length + 1U);
    if (!result) return NULL;
    memcpy(result, text, length);
    result[length] = '\0';
    return result;
}

int ld_coff_fail(ld_coff_context_t *ctx, int code, const char *format, ...) {
    if (!ctx) return code;
    ctx->error = code;
    if (ctx->options && ctx->options->diagnostic) {
        char message[4096];
        va_list arguments;
        va_start(arguments, format);
        vsnprintf(message, sizeof(message), format, arguments);
        va_end(arguments);
        ctx->options->diagnostic(ctx->options->diagnostic_context,
                                 LD_DIAG_ERROR, message);
    }
    return code;
}

const char *ld_coff_relocation_name(uint16_t type) {
    switch (type) {
        case LD_COFF_REL_AMD64_ABSOLUTE:
            return "ABSOLUTE";
        case LD_COFF_REL_AMD64_ADDR64:
            return "ADDR64";
        case LD_COFF_REL_AMD64_ADDR32:
            return "ADDR32";
        case LD_COFF_REL_AMD64_ADDR32NB:
            return "ADDR32NB";
        case LD_COFF_REL_AMD64_REL32:
            return "REL32";
        case LD_COFF_REL_AMD64_REL32_1:
            return "REL32_1";
        case LD_COFF_REL_AMD64_REL32_2:
            return "REL32_2";
        case LD_COFF_REL_AMD64_REL32_3:
            return "REL32_3";
        case LD_COFF_REL_AMD64_REL32_4:
            return "REL32_4";
        case LD_COFF_REL_AMD64_REL32_5:
            return "REL32_5";
        case LD_COFF_REL_AMD64_SECTION:
            return "SECTION";
        case LD_COFF_REL_AMD64_SECREL:
            return "SECREL";
        default:
            return "UNKNOWN";
    }
}

int ld_coff_relocation_fail(ld_coff_context_t *ctx, int code,
                            const ld_coff_object_t *object,
                            const ld_coff_section_t *section,
                            const ld_coff_relocation_t *relocation,
                            const char *symbol_name, const char *format, ...) {
    char detail[2048];
    va_list arguments;
    va_start(arguments, format);
    vsnprintf(detail, sizeof(detail), format, arguments);
    va_end(arguments);

    const char *object_name =
            object && object->file && object->file->path
                    ? object->file->path
                    : (object && object->display_name ? object->display_name
                                                      : "<synthetic>");
    const char *member_name =
            object && object->member_name ? object->member_name : "<direct>";
    const char *section_name =
            section && section->name ? section->name : "<unknown>";
    uint32_t offset = relocation ? relocation->offset : 0U;
    uint16_t type = relocation ? relocation->type : UINT16_MAX;
    return ld_coff_fail(
            ctx, code,
            "relocation error: object='%s', member='%s', section='%s', "
            "offset=0x%08x, symbol='%s', type=%s(0x%04x): %s",
            object_name, member_name, section_name, offset,
            symbol_name ? symbol_name : "<unknown>",
            ld_coff_relocation_name(type), type, detail);
}

void ld_coff_context_init(ld_coff_context_t *ctx,
                          const ld_options_t *options) {
    if (!ctx) return;
    memset(ctx, 0, sizeof(*ctx));
    ctx->options = options;
    ctx->image_base = LD_PE_IMAGE_BASE64;
    ctx->section_alignment = LD_PE_SECTION_ALIGNMENT;
    ctx->file_alignment = LD_PE_FILE_ALIGNMENT;
}

static void ld_coff_object_destroy(ld_coff_object_t *object) {
    if (!object) return;
    for (size_t i = 0; i < object->section_count; i++) {
        free(object->sections[i].name);
        free(object->sections[i].owned_data);
        free(object->sections[i].relocations);
    }
    for (size_t i = 0; i < object->symbol_count; i++)
        free(object->symbols[i].name);
    if (object->import) {
        free(object->import->public_name);
        free(object->import->import_name);
        free(object->import->dll_name);
        free(object->import);
    }
    free(object->sections);
    free(object->symbols);
    free(object->display_name);
    free(object->member_name);
    free(object);
}

void ld_coff_context_deinit(ld_coff_context_t *ctx) {
    if (!ctx) return;
    for (size_t i = 0; i < ctx->object_count; i++)
        ld_coff_object_destroy(ctx->objects[i]);
    for (size_t i = 0; i < ctx->synthetic_count; i++) {
        ld_coff_section_t *section = ctx->synthetic_sections[i];
        free(section->name);
        free(section->owned_data);
        free(section->relocations);
        free(section);
    }
    for (size_t i = 0; i < ctx->file_count; i++) {
        free(ctx->files[i]->bytes);
        free(ctx->files[i]->path);
        free(ctx->files[i]);
    }
    for (size_t i = 0; i < ctx->output_count; i++) {
        free(ctx->outputs[i]->name);
        free(ctx->outputs[i]->inputs);
        free(ctx->outputs[i]->data);
        free(ctx->outputs[i]);
    }
    ld_coff_global_t *global, *temporary;
    HASH_ITER(hh, ctx->globals, global, temporary) {
        HASH_DEL(ctx->globals, global);
        free(global->name);
        free(global->fallback_name);
        free(global->lazy_objects);
        free(global);
    }
    for (size_t i = 0; i < ctx->alias_count; i++) {
        free(ctx->aliases[i].source);
        free(ctx->aliases[i].target);
    }
    for (size_t i = 0; i < ctx->mismatch_count; i++) {
        free(ctx->mismatches[i].key);
        free(ctx->mismatches[i].value);
        free(ctx->mismatches[i].source);
    }
    for (size_t i = 0; i < ctx->default_library_count; i++)
        free(ctx->default_libraries[i]);
    for (size_t i = 0; i < ctx->nodefault_library_count; i++)
        free(ctx->nodefault_libraries[i]);
    for (size_t i = 0; i < ctx->loaded_path_count; i++)
        free(ctx->loaded_paths[i]);
    free(ctx->files);
    free(ctx->objects);
    free(ctx->synthetic_sections);
    free(ctx->global_order);
    free(ctx->imports);
    free(ctx->outputs);
    free(ctx->aliases);
    free(ctx->mismatches);
    free(ctx->default_libraries);
    free(ctx->nodefault_libraries);
    free(ctx->loaded_paths);
    free(ctx->base_relocations);
    memset(ctx, 0, sizeof(*ctx));
}

static int ld_coff_push_global_order(ld_coff_context_t *ctx,
                                     ld_coff_global_t *global) {
    if (ctx->global_count == ctx->global_capacity) {
        size_t next = ctx->global_capacity ? ctx->global_capacity * 2U : 128U;
        ld_coff_global_t **items = ld_coff_grow(
                ctx->global_order, ctx->global_capacity, next, sizeof(*items));
        if (!items) return LD_IO_ERROR;
        ctx->global_order = items;
        ctx->global_capacity = next;
    }
    global->insertion_order = (uint32_t) ctx->global_count;
    ctx->global_order[ctx->global_count++] = global;
    return LD_OK;
}

ld_coff_global_t *ld_coff_get_global(ld_coff_context_t *ctx,
                                     const char *name, bool create) {
    if (!ctx || !name || !*name) return NULL;
    ld_coff_global_t *global = NULL;
    HASH_FIND_STR(ctx->globals, name, global);
    if (global || !create) return global;
    global = calloc(1, sizeof(*global));
    if (!global) return NULL;
    global->name = ld_coff_strndup(name, strlen(name));
    if (!global->name || ld_coff_push_global_order(ctx, global) != LD_OK) {
        free(global->name);
        free(global);
        return NULL;
    }
    global->kind = LD_COFF_GLOBAL_UNDEFINED;
    HASH_ADD_KEYPTR(hh, ctx->globals, global->name, strlen(global->name),
                    global);
    return global;
}

int ld_coff_register_lazy(ld_coff_context_t *ctx, const char *name,
                          ld_coff_object_t *object) {
    ld_coff_global_t *global = ld_coff_get_global(ctx, name, true);
    if (!global) return ld_coff_fail(ctx, LD_IO_ERROR, "out of memory");
    for (size_t i = 0; i < global->lazy_count; i++)
        if (global->lazy_objects[i] == object) return LD_OK;
    if (global->lazy_count == global->lazy_capacity) {
        size_t next = global->lazy_capacity ? global->lazy_capacity * 2U : 2U;
        ld_coff_object_t **items = ld_coff_grow(
                global->lazy_objects, global->lazy_capacity, next,
                sizeof(*items));
        if (!items)
            return ld_coff_fail(ctx, LD_IO_ERROR,
                                "out of memory indexing archive symbols");
        global->lazy_objects = items;
        global->lazy_capacity = next;
    }
    global->lazy_objects[global->lazy_count++] = object;
    return LD_OK;
}

static int ld_coff_choose_comdat(ld_coff_context_t *ctx,
                                 ld_coff_global_t *existing,
                                 ld_coff_section_t *candidate,
                                 bool *candidate_wins) {
    ld_coff_section_t *current = existing->section;
    *candidate_wins = false;
    if (!ld_coff_section_is_comdat(current) ||
        !ld_coff_section_is_comdat(candidate)) {
        return ld_coff_fail(ctx, LD_SYMBOL_ERROR,
                            "duplicate symbol '%s' in %s and %s",
                            existing->name,
                            current && current->object
                                    ? current->object->display_name
                                    : "<synthetic>",
                            candidate->object
                                    ? candidate->object->display_name
                                    : "<synthetic>");
    }
    if (!current->comdat_key || !candidate->comdat_key ||
        strcmp(current->comdat_key, candidate->comdat_key) != 0) {
        return ld_coff_fail(
                ctx, LD_SYMBOL_ERROR,
                "duplicate symbol '%s' in COMDATs with different leaders",
                existing->name);
    }
    uint8_t selection = current->comdat_selection
                                ? current->comdat_selection
                                : candidate->comdat_selection;
    if (candidate->comdat_selection && current->comdat_selection &&
        candidate->comdat_selection != current->comdat_selection) {
        return ld_coff_fail(ctx, LD_SYMBOL_ERROR,
                            "conflicting COMDAT selections for '%s'",
                            existing->name);
    }
    switch (selection) {
        case LD_COFF_COMDAT_NODUPLICATES:
            return ld_coff_fail(ctx, LD_SYMBOL_ERROR,
                                "duplicate NODUPLICATES COMDAT '%s'",
                                existing->name);
        case LD_COFF_COMDAT_ANY:
            return LD_OK;
        case LD_COFF_COMDAT_SAME_SIZE:
            if (current->virtual_size != candidate->virtual_size)
                return ld_coff_fail(ctx, LD_SYMBOL_ERROR,
                                    "SAME_SIZE COMDAT '%s' has different sizes",
                                    existing->name);
            return LD_OK;
        case LD_COFF_COMDAT_EXACT_MATCH:
            /* Match link.exe/lld-link: EXACT_MATCH compares section contents,
               not the auxiliary section-definition checksum or alignment. */
            if (current->data_size != candidate->data_size ||
                (current->data_size &&
                 memcmp(current->data, candidate->data,
                        current->data_size) != 0))
                return ld_coff_fail(ctx, LD_SYMBOL_ERROR,
                                    "EXACT_MATCH COMDAT '%s' differs",
                                    existing->name);
            return LD_OK;
        case LD_COFF_COMDAT_LARGEST:
            *candidate_wins = candidate->virtual_size > current->virtual_size;
            return LD_OK;
        case LD_COFF_COMDAT_ASSOCIATIVE:
            return LD_OK;
        case LD_COFF_COMDAT_NEWEST:
            return ld_coff_fail(ctx, LD_UNSUPPORTED,
                                "unsupported NEWEST COMDAT '%s'",
                                existing->name);
        default:
            return ld_coff_fail(ctx, LD_UNSUPPORTED,
                                "unsupported COMDAT selection %u for '%s'",
                                selection, existing->name);
    }
}

static void ld_coff_clear_section_definitions(ld_coff_context_t *ctx,
                                              ld_coff_section_t *section) {
    for (size_t i = 0; i < ctx->global_count; i++) {
        ld_coff_global_t *global = ctx->global_order[i];
        if (global->section != section) continue;
        global->kind = LD_COFF_GLOBAL_UNDEFINED;
        global->object = NULL;
        global->symbol = NULL;
        global->section = NULL;
        global->import = NULL;
        global->value = 0U;
    }
}

static int ld_coff_select_object_comdats(ld_coff_context_t *ctx,
                                         ld_coff_object_t *object) {
    for (size_t i = 0; i < object->section_count; i++) {
        ld_coff_section_t *section = &object->sections[i];
        if (!ld_coff_section_is_comdat(section)) continue;

        uint8_t selection = section->comdat_selection;
        if (selection == LD_COFF_COMDAT_NEWEST)
            return ld_coff_fail(
                    ctx, LD_UNSUPPORTED,
                    "%s(%s): NEWEST COMDAT selection is unsupported",
                    object->display_name, section->name);
        if (selection < LD_COFF_COMDAT_NODUPLICATES ||
            selection > LD_COFF_COMDAT_LARGEST)
            return ld_coff_fail(
                    ctx, LD_UNSUPPORTED,
                    "%s(%s): unsupported or missing COMDAT selection %u",
                    object->display_name, section->name, selection);
        if (selection == LD_COFF_COMDAT_ASSOCIATIVE) continue;
        /* LLD treats a COMDAT whose leader is not external as locally
           prevailing.  Such unwind/debug contributions have no global key
           and therefore do not participate in cross-object selection. */
        if (!section->comdat_key || !*section->comdat_key) continue;

        ld_coff_global_t *leader =
                ld_coff_get_global(ctx, section->comdat_key, false);
        if (!leader || leader->kind == LD_COFF_GLOBAL_UNDEFINED) continue;

        bool candidate_wins = false;
        int status =
                ld_coff_choose_comdat(ctx, leader, section, &candidate_wins);
        if (status != LD_OK) return status;
        if (!candidate_wins) {
            section->discarded = true;
            continue;
        }

        ld_coff_section_t *previous = leader->section;
        if (previous) {
            previous->discarded = true;
            ld_coff_clear_section_definitions(ctx, previous);
        }
    }
    return LD_OK;
}

static int ld_coff_define_regular(ld_coff_context_t *ctx,
                                  ld_coff_symbol_t *symbol) {
    ld_coff_global_t *global = ld_coff_get_global(ctx, symbol->name, true);
    if (!global) return ld_coff_fail(ctx, LD_IO_ERROR, "out of memory");
    symbol->global = global;
    if (symbol->section && symbol->section->discarded) return LD_OK;
    if (global->kind == LD_COFF_GLOBAL_DEFINED) {
        bool candidate_wins = false;
        int status = ld_coff_choose_comdat(ctx, global, symbol->section,
                                           &candidate_wins);
        if (status != LD_OK) return status;
        if (!candidate_wins) {
            if (symbol->section) {
                symbol->section->discarded = true;
                ld_coff_clear_section_definitions(ctx, symbol->section);
            }
            return LD_OK;
        }
        if (global->section) {
            ld_coff_section_t *previous = global->section;
            previous->discarded = true;
            ld_coff_clear_section_definitions(ctx, previous);
        }
    }
    global->kind = LD_COFF_GLOBAL_DEFINED;
    global->object = symbol->section ? symbol->section->object : NULL;
    global->symbol = symbol;
    global->section = symbol->section;
    global->import = NULL;
    global->value = symbol->value;
    return LD_OK;
}

static int ld_coff_define_common(ld_coff_context_t *ctx,
                                 ld_coff_object_t *object,
                                 ld_coff_symbol_t *symbol) {
    ld_coff_global_t *global = ld_coff_get_global(ctx, symbol->name, true);
    if (!global) return ld_coff_fail(ctx, LD_IO_ERROR, "out of memory");
    symbol->global = global;
    if (global->kind == LD_COFF_GLOBAL_DEFINED) return LD_OK;
    /* LLD's addCommon replaces every non-DefinedCOFF symbol (including an
       import or absolute symbol), but among common definitions it retains
       the first unless a later input requests strictly more storage. */
    if (global->kind == LD_COFF_GLOBAL_COMMON &&
        symbol->value <= global->common_size) {
        return LD_OK;
    }
    global->kind = LD_COFF_GLOBAL_COMMON;
    global->common_size = symbol->value;
    uint64_t alignment = 1U;
    while (alignment < global->common_size && alignment < 32U)
        alignment <<= 1U;
    global->common_alignment = (uint32_t) alignment;
    global->object = object;
    global->symbol = symbol;
    global->section = NULL;
    global->import = NULL;
    return LD_OK;
}

static int ld_coff_define_absolute(ld_coff_context_t *ctx,
                                   ld_coff_symbol_t *symbol) {
    ld_coff_global_t *global = ld_coff_get_global(ctx, symbol->name, true);
    if (!global) return ld_coff_fail(ctx, LD_IO_ERROR, "out of memory");
    symbol->global = global;
    if (global->kind != LD_COFF_GLOBAL_UNDEFINED &&
        (global->kind != LD_COFF_GLOBAL_ABSOLUTE ||
         global->value != symbol->value))
        return ld_coff_fail(ctx, LD_SYMBOL_ERROR,
                            "duplicate absolute symbol '%s'", symbol->name);
    global->kind = LD_COFF_GLOBAL_ABSOLUTE;
    global->value = symbol->value;
    global->symbol = symbol;
    return LD_OK;
}

static int ld_coff_push_import(ld_coff_context_t *ctx,
                               ld_coff_import_t *import,
                               ld_coff_import_t **canonical) {
    for (size_t i = 0; i < ctx->import_count; i++) {
        ld_coff_import_t *old = ctx->imports[i];
        if (strcmp(old->public_name, import->public_name) == 0) {
            if (old->type != import->type)
                return ld_coff_fail(
                        ctx, LD_SYMBOL_ERROR,
                        "conflicting import symbol '%s': type %u from %s and type %u from %s",
                        import->public_name, old->type, old->dll_name,
                        import->type, import->dll_name);
            // UCRT umbrella and API-set import libraries intentionally expose
            // many of the same public symbols. Match normal COFF link-order
            // semantics by retaining the first selected import definition.
            *canonical = old;
            return LD_OK;
        }
    }
    if (ctx->import_count == ctx->import_capacity) {
        size_t next = ctx->import_capacity ? ctx->import_capacity * 2U : 32U;
        ld_coff_import_t **items = ld_coff_grow(
                ctx->imports, ctx->import_capacity, next, sizeof(*items));
        if (!items) return ld_coff_fail(ctx, LD_IO_ERROR, "out of memory");
        ctx->imports = items;
        ctx->import_capacity = next;
    }
    ctx->imports[ctx->import_count++] = import;
    import->selected = true;
    *canonical = import;
    return LD_OK;
}

static int ld_coff_define_import_symbol(ld_coff_context_t *ctx,
                                        const char *name,
                                        ld_coff_import_t *import,
                                        ld_coff_global_kind_t kind) {
    ld_coff_global_t *global = ld_coff_get_global(ctx, name, true);
    if (!global) return ld_coff_fail(ctx, LD_IO_ERROR, "out of memory");
    if (global->kind != LD_COFF_GLOBAL_UNDEFINED && global->import != import)
        return ld_coff_fail(ctx, LD_SYMBOL_ERROR,
                            "duplicate import symbol '%s'", name);
    global->kind = kind;
    global->import = import;
    global->object = import->object;
    return LD_OK;
}

static int ld_coff_select_import(ld_coff_context_t *ctx,
                                 ld_coff_object_t *object) {
    ld_coff_import_t *import = object->import;
    ld_coff_import_t *canonical = NULL;
    int status = ld_coff_push_import(ctx, import, &canonical);
    if (status != LD_OK) return status;
    import = canonical;
    size_t length = strlen(import->public_name);
    char *iat = malloc(length + 7U);
    if (!iat) return ld_coff_fail(ctx, LD_IO_ERROR, "out of memory");
    memcpy(iat, "__imp_", 6U);
    memcpy(iat + 6U, import->public_name, length + 1U);
    status = ld_coff_define_import_symbol(ctx, iat, import,
                                          LD_COFF_GLOBAL_IMPORT_IAT);
    free(iat);
    if (status != LD_OK) return status;
    return ld_coff_define_import_symbol(
            ctx, import->public_name, import,
            import->type == LD_COFF_IMPORT_CODE
                    ? LD_COFF_GLOBAL_IMPORT_THUNK
                    : LD_COFF_GLOBAL_IMPORT_IAT);
}

int ld_coff_select_object(ld_coff_context_t *ctx, ld_coff_object_t *object) {
    if (!ctx || !object) return LD_INVALID_ARGUMENT;
    if (object->selected) return LD_OK;
    object->selected = true;
    if (object->import_object) return ld_coff_select_import(ctx, object);

    for (size_t i = 0; i < object->section_count; i++) {
        ld_coff_section_t *section = &object->sections[i];
        if (strcmp(section->name, ".drectve") == 0) {
            int status = ld_coff_parse_directives(ctx, section);
            if (status != LD_OK) return status;
            section->discarded = true;
        }
    }

    int status = ld_coff_select_object_comdats(ctx, object);
    if (status != LD_OK) return status;

    for (size_t i = 0; i < object->symbol_count; i++) {
        ld_coff_symbol_t *symbol = &object->symbols[i];
        if (symbol->auxiliary || !symbol->name || !*symbol->name) continue;
        bool external = symbol->storage_class == LD_COFF_STORAGE_CLASS_EXTERNAL ||
                        symbol->storage_class ==
                                LD_COFF_STORAGE_CLASS_WEAK_EXTERNAL;
        if (!external) continue;
        status = LD_OK;
        if (symbol->section_number > 0) {
            status = ld_coff_define_regular(ctx, symbol);
        } else if (symbol->section_number == LD_COFF_SYM_ABSOLUTE) {
            status = ld_coff_define_absolute(ctx, symbol);
        } else if (symbol->section_number == LD_COFF_SYM_UNDEFINED &&
                   symbol->value != 0U) {
            status = ld_coff_define_common(ctx, object, symbol);
        } else if (symbol->section_number == LD_COFF_SYM_UNDEFINED) {
            ld_coff_global_t *global =
                    ld_coff_get_global(ctx, symbol->name, true);
            if (!global)
                return ld_coff_fail(ctx, LD_IO_ERROR, "out of memory");
            symbol->global = global;
            global->referenced = true;
            if (symbol->storage_class == LD_COFF_STORAGE_CLASS_WEAK_EXTERNAL &&
                symbol->weak_target_index < object->symbol_count) {
                ld_coff_symbol_t *target =
                        &object->symbols[symbol->weak_target_index];
                if (target->name && *target->name && !global->fallback_name) {
                    global->fallback_name = ld_coff_strndup(
                            target->name, strlen(target->name));
                    if (!global->fallback_name)
                        return ld_coff_fail(ctx, LD_IO_ERROR,
                                            "out of memory");
                    global->fallback_characteristics =
                            symbol->weak_characteristics;
                    global->fallback_object = object;
                }
            }
        }
        if (status != LD_OK) return status;
    }
    return LD_OK;
}

static int ld_coff_apply_aliases(ld_coff_context_t *ctx, bool *changed) {
    for (size_t i = 0; i < ctx->alias_count; i++) {
        ld_coff_alias_t *alias = &ctx->aliases[i];
        ld_coff_global_t *source =
                ld_coff_get_global(ctx, alias->source, true);
        ld_coff_global_t *target =
                ld_coff_get_global(ctx, alias->target, true);
        if (!source || !target)
            return ld_coff_fail(ctx, LD_IO_ERROR, "out of memory");
        if (source->referenced && !ld_coff_global_resolved(source) &&
            !target->referenced) {
            target->referenced = true;
            *changed = true;
        }
        if (!source->fallback_name) {
            source->fallback_name =
                    ld_coff_strndup(alias->target, strlen(alias->target));
            if (!source->fallback_name)
                return ld_coff_fail(ctx, LD_IO_ERROR, "out of memory");
            source->fallback_characteristics = LD_COFF_WEAK_SEARCH_ALIAS;
        }
    }
    return LD_OK;
}

int ld_coff_resolve_archives(ld_coff_context_t *ctx) {
    if (!ctx) return LD_INVALID_ARGUMENT;
    bool loaded_defaults;
    do {
        /* Finish the current archive fixed point before admitting queued
           /DEFAULTLIB inputs. A selected member may introduce another
           undefined symbol whose provider carries /NODEFAULTLIB; loading
           defaults between those two selections makes the result depend on
           member discovery order. This corresponds to lld-link's ordinary
           input queue reaching all currently available providers first. */
        bool changed;
        do {
            changed = false;
            int status = ld_coff_apply_aliases(ctx, &changed);
            if (status != LD_OK) return status;
            size_t count = ctx->global_count;
            for (size_t i = 0; i < count; i++) {
                ld_coff_global_t *global = ctx->global_order[i];
                if (!global->referenced || ld_coff_global_resolved(global))
                    continue;
                ld_coff_object_t *provider = NULL;
                for (size_t j = 0; j < global->lazy_count; j++) {
                    ld_coff_object_t *candidate = global->lazy_objects[j];
                    if (candidate->selected) continue;
                    /* COFF weak externals are added with overrideLazy=false.
                       An earlier lazy symbol is therefore forced, while a
                       lazy archive registered after the weak alias is
                       ignored.  Nature parses archives up front, so recover
                       LLD's incremental input semantics using stable object
                       input order at extraction time. */
                    if (global->fallback_object &&
                        candidate->input_order >
                                global->fallback_object->input_order) {
                        continue;
                    }
                    provider = candidate;
                    break;
                }
                if (provider) {
                    status = ld_coff_select_object(ctx, provider);
                    if (status != LD_OK) return status;
                    changed = true;
                    continue;
                }
                if (global->fallback_name &&
                    global->fallback_characteristics !=
                            LD_COFF_WEAK_SEARCH_NOLIBRARY) {
                    ld_coff_global_t *target = ld_coff_get_global(
                            ctx, global->fallback_name, true);
                    if (!target)
                        return ld_coff_fail(ctx, LD_IO_ERROR,
                                            "out of memory");
                    if (!target->referenced) {
                        target->referenced = true;
                        changed = true;
                    }
                }
            }
        } while (changed);

        size_t objects_before = ctx->object_count;
        int status = ld_coff_load_default_libraries(ctx);
        if (status != LD_OK) return status;
        loaded_defaults = ctx->object_count != objects_before;
    } while (loaded_defaults);
    return LD_OK;
}

static int ld_coff_finalize_weak_aliases(ld_coff_context_t *ctx) {
    for (size_t i = 0; i < ctx->global_count; i++) {
        ld_coff_global_t *global = ctx->global_order[i];
        if (ld_coff_global_resolved(global) || !global->fallback_name) continue;
        ld_coff_global_t *target =
                ld_coff_get_global(ctx, global->fallback_name, false);
        size_t depth = 0U;
        while (target && !ld_coff_global_resolved(target) &&
               target->fallback_name && depth++ < ctx->global_count) {
            target = ld_coff_get_global(ctx, target->fallback_name, false);
        }
        if (depth >= ctx->global_count)
            return ld_coff_fail(ctx, LD_SYMBOL_ERROR,
                                "weak alias cycle involving '%s'",
                                global->name);
        if (target && ld_coff_global_resolved(target)) {
            global->kind = target->kind;
            global->object = target->object;
            global->symbol = target->symbol;
            global->section = target->section;
            global->import = target->import;
            global->value = target->value;
        }
    }
    return LD_OK;
}

static int ld_coff_check_undefined(ld_coff_context_t *ctx) {
    for (size_t i = 0; i < ctx->global_count; i++) {
        ld_coff_global_t *global = ctx->global_order[i];
        if (global->referenced && !ld_coff_global_resolved(global))
            return ld_coff_fail(ctx, LD_SYMBOL_ERROR,
                                "undefined symbol: %s", global->name);
    }
    return LD_OK;
}

static int ld_coff_mark_entry(ld_coff_context_t *ctx) {
    const char *entry = ctx->options->entry_symbol;
    if (!entry || !*entry) entry = "mainCRTStartup";
    ld_coff_global_t *global = ld_coff_get_global(ctx, entry, true);
    if (!global) return ld_coff_fail(ctx, LD_IO_ERROR, "out of memory");
    global->referenced = true;
    const char *image_names[] = {"__ImageBase", "__image_base__"};
    for (size_t i = 0; i < sizeof(image_names) / sizeof(*image_names); i++) {
        ld_coff_global_t *image =
                ld_coff_get_global(ctx, image_names[i], true);
        if (!image) return ld_coff_fail(ctx, LD_IO_ERROR, "out of memory");
        if (image->kind == LD_COFF_GLOBAL_UNDEFINED) {
            /* A section-less defined value of zero denotes image RVA zero.
               ADDR64 then adds the configured image base. */
            image->kind = LD_COFF_GLOBAL_DEFINED;
            image->value = 0U;
        }
    }
    return LD_OK;
}

static int ld_coff_define_mingw_synthetics(ld_coff_context_t *ctx) {
    /* MinGW startup objects refer to linker-created boundary symbols.  They
       can first appear while resolving libmingw32, so install placeholders
       after the archive fixed point and attach them to concrete synthetic
       chunks during PE construction. */
    static const char *names[] = {
            "__CTOR_LIST__",
            "__DTOR_LIST__",
            "__RUNTIME_PSEUDO_RELOC_LIST__",
            "__RUNTIME_PSEUDO_RELOC_LIST_END__",
            "__data_start__",
            "__data_end__",
            "__bss_start__",
            "__bss_end__",
    };
    for (size_t i = 0; i < sizeof(names) / sizeof(*names); i++) {
        ld_coff_global_t *global = ld_coff_get_global(ctx, names[i], false);
        if (!global || global->kind != LD_COFF_GLOBAL_UNDEFINED) continue;
        global->kind = LD_COFF_GLOBAL_DEFINED;
        global->value = 0U;
    }
    return LD_OK;
}

int ld_link_coff(const ld_options_t *options) {
    if (!options || !options->output_path || !*options->output_path ||
        options->os != LD_OS_WINDOWS)
        return LD_INVALID_ARGUMENT;
    if (options->arch != LD_ARCH_AMD64) {
        if (options->diagnostic)
            options->diagnostic(options->diagnostic_context, LD_DIAG_ERROR,
                                "the COFF linker supports windows/amd64 only");
        return LD_UNSUPPORTED;
    }
    if (options->inputs.count == 0U) {
        if (options->diagnostic)
            options->diagnostic(options->diagnostic_context, LD_DIAG_ERROR,
                                "no COFF linker input files were provided");
        return LD_INVALID_ARGUMENT;
    }

    ld_coff_context_t ctx;
    ld_coff_context_init(&ctx, options);
    int status = ld_coff_load_options(&ctx);
    if (status == LD_OK) status = ld_coff_mark_entry(&ctx);
    if (status == LD_OK) status = ld_coff_resolve_archives(&ctx);
    if (status == LD_OK) status = ld_coff_define_mingw_synthetics(&ctx);
    if (status == LD_OK) status = ld_coff_finalize_weak_aliases(&ctx);
    if (status == LD_OK) status = ld_coff_check_undefined(&ctx);
    uint8_t *image = NULL;
    size_t image_size = 0U;
    if (status == LD_OK) status = ld_coff_build_image(&ctx, &image, &image_size);
    if (status == LD_OK)
        status = ld_write_output_atomic(options, image, image_size);
    if (status == LD_OK) status = ld_coff_write_map(&ctx);
    free(image);
    ld_coff_context_deinit(&ctx);
    return status;
}

static void *ld_coff_capability_grow(void *items, size_t old_capacity,
                                     size_t new_capacity,
                                     size_t item_size) {
    if (item_size == 0U || new_capacity > SIZE_MAX / item_size) return NULL;
    void *grown = realloc(items, new_capacity * item_size);
    if (grown && new_capacity > old_capacity) {
        memset((uint8_t *) grown + old_capacity * item_size, 0,
               (new_capacity - old_capacity) * item_size);
    }
    return grown;
}

static char *ld_coff_capability_strdup(const char *value) {
    if (!value) return NULL;
    size_t length = strlen(value);
    if (length == SIZE_MAX) return NULL;
    char *copy = malloc(length + 1U);
    if (!copy) return NULL;
    memcpy(copy, value, length + 1U);
    return copy;
}

static unsigned char ld_coff_capability_ascii_lower(unsigned char value) {
    return value >= 'A' && value <= 'Z'
                   ? (unsigned char) (value + ('a' - 'A'))
                   : value;
}

static bool ld_coff_capability_ascii_equal(const char *left,
                                           const char *right,
                                           size_t length) {
    for (size_t i = 0U; i < length; i++) {
        if (ld_coff_capability_ascii_lower((unsigned char) left[i]) !=
            ld_coff_capability_ascii_lower((unsigned char) right[i]))
            return false;
    }
    return true;
}

static int ld_coff_capability_ascii_compare(const char *left,
                                            const char *right) {
    while (*left && *right) {
        unsigned char a =
                ld_coff_capability_ascii_lower((unsigned char) *left++);
        unsigned char b =
                ld_coff_capability_ascii_lower((unsigned char) *right++);
        if (a != b) return a < b ? -1 : 1;
    }
    unsigned char a = (unsigned char) *left;
    unsigned char b = (unsigned char) *right;
    return a < b ? -1 : a > b;
}

static int ld_coff_capability_fail(ld_coff_capability_state_t *state,
                                   int status, const char *format, ...) {
    if (state && state->error && state->error_capacity != 0U) {
        va_list arguments;
        va_start(arguments, format);
        vsnprintf(state->error, state->error_capacity, format, arguments);
        va_end(arguments);
    }
    return status;
}

static void ld_coff_capability_diagnostic(void *context,
                                          ld_diag_level_t level,
                                          const char *message) {
    ld_coff_capability_state_t *state = context;
    if (!state || level != LD_DIAG_ERROR || !state->error ||
        state->error_capacity == 0U || state->error[0] != '\0')
        return;
    snprintf(state->error, state->error_capacity, "%s", message);
}

static bool ld_coff_capability_push_string(
        ld_coff_capability_strings_t *strings, const char *value) {
    for (size_t i = 0U; i < strings->count; i++) {
        if (strcmp(strings->items[i], value) == 0) return true;
    }
    if (strings->count == strings->capacity) {
        size_t next = strings->capacity ? strings->capacity * 2U : 16U;
        if (next < strings->capacity) return false;
        char **grown = ld_coff_capability_grow(
                strings->items, strings->capacity, next, sizeof(*grown));
        if (!grown) return false;
        strings->items = grown;
        strings->capacity = next;
    }
    char *copy = ld_coff_capability_strdup(value);
    if (!copy) return false;
    strings->items[strings->count++] = copy;
    return true;
}

static bool ld_coff_capability_push_string_n(
        ld_coff_capability_strings_t *strings, const char *value,
        size_t length) {
    if (length == SIZE_MAX) return false;
    char *copy = malloc(length + 1U);
    if (!copy) return false;
    memcpy(copy, value, length);
    copy[length] = '\0';
    bool pushed = ld_coff_capability_push_string(strings, copy);
    free(copy);
    return pushed;
}

static bool ld_coff_capability_append_string(
        ld_coff_capability_strings_t *strings, const char *value) {
    if (strings->count == strings->capacity) {
        size_t next = strings->capacity ? strings->capacity * 2U : 8U;
        if (next < strings->capacity) return false;
        char **grown = ld_coff_capability_grow(
                strings->items, strings->capacity, next, sizeof(*grown));
        if (!grown) return false;
        strings->items = grown;
        strings->capacity = next;
    }
    char *copy = ld_coff_capability_strdup(value);
    if (!copy) return false;
    strings->items[strings->count++] = copy;
    return true;
}

static bool ld_coff_capability_push_lower_string(
        ld_coff_capability_strings_t *strings, const char *value) {
    size_t length = strlen(value);
    if (length == SIZE_MAX) return false;
    char *lower = malloc(length + 1U);
    if (!lower) return false;
    for (size_t i = 0U; i < length; i++)
        lower[i] = (char) ld_coff_capability_ascii_lower(
                (unsigned char) value[i]);
    lower[length] = '\0';
    bool result = ld_coff_capability_push_string(strings, lower);
    free(lower);
    return result;
}

static bool ld_coff_capability_has_string(
        const ld_coff_capability_strings_t *strings, const char *value) {
    for (size_t i = 0U; i < strings->count; i++)
        if (strcmp(strings->items[i], value) == 0) return true;
    return false;
}

static bool ld_coff_capability_ascii_string_equal(const char *left,
                                                   const char *right) {
    size_t left_length = strlen(left);
    return left_length == strlen(right) &&
           ld_coff_capability_ascii_equal(left, right, left_length);
}

static bool ld_coff_capability_allowed_system_dll(const char *name) {
    static const char *allowed[] = {
            "advapi32.dll", "bcrypt.dll",  "crypt32.dll", "dbghelp.dll",
            "iphlpapi.dll", "kernel32.dll", "ntdll.dll",   "ole32.dll",
            "psapi.dll",    "secur32.dll",  "shell32.dll", "ucrtbase.dll",
            "user32.dll",   "userenv.dll",  "version.dll", "winmm.dll",
            "ws2_32.dll",
    };
    for (size_t i = 0U; i < sizeof(allowed) / sizeof(*allowed); i++)
        if (ld_coff_capability_ascii_string_equal(name, allowed[i]))
            return true;
    static const char api_set_prefix[] = "api-ms-win-crt-";
    size_t length = strlen(name);
    return length > sizeof(api_set_prefix) - 1U + 4U &&
           ld_coff_capability_ascii_equal(
                   name, api_set_prefix, sizeof(api_set_prefix) - 1U) &&
           ld_coff_capability_ascii_equal(name + length - 4U, ".dll", 4U);
}

static bool ld_coff_capability_linker_synthetic(const char *name) {
    static const char *synthetics[] = {
            "__ImageBase",
            "__image_base__",
            "__CTOR_LIST__",
            "__DTOR_LIST__",
            "__RUNTIME_PSEUDO_RELOC_LIST__",
            "__RUNTIME_PSEUDO_RELOC_LIST_END__",
            "__data_start__",
            "__data_end__",
            "__bss_start__",
            "__bss_end__",
    };
    for (size_t i = 0U; i < sizeof(synthetics) / sizeof(*synthetics); i++)
        if (strcmp(name, synthetics[i]) == 0) return true;
    return false;
}

static bool ld_coff_capability_external_contract(const char *name) {
    static const char *external[] = {
            "main",           "main.main",      "WinMain",
            "wWinMain",       "rt_data",
            "rt_rtype_data",  "rt_rtype_count", "rt_fndef_data",
            "rt_fndef_count", "rt_caller_data", "rt_caller_count",
            "rt_symdef_data", "rt_symdef_count", "rt_strtable_data",
    };
    for (size_t i = 0U; i < sizeof(external) / sizeof(*external); i++)
        if (strcmp(name, external[i]) == 0) return true;
    return false;
}

static bool ld_coff_capability_object_provides(
        const ld_coff_capability_object_t *object, const char *name) {
    return ld_coff_capability_object_defines(object, name) ||
           ld_coff_capability_has_string(&object->weak_alias_sources, name);
}

static bool ld_coff_capability_symbol_resolved(
        const ld_coff_capability_state_t *state, const char *name,
        size_t depth) {
    if (depth > state->weak_undefined_symbols.count) return false;
    if (ld_coff_capability_linker_synthetic(name) ||
        ld_coff_capability_external_contract(name))
        return true;
    for (size_t i = 0U; i < state->object_count; i++) {
        const ld_coff_capability_object_t *object = &state->objects[i];
        if (object->selected &&
            ld_coff_capability_object_defines(object, name))
            return true;
    }
    for (size_t i = 0U; i < state->object_count; i++) {
        const ld_coff_capability_object_t *object = &state->objects[i];
        if (!object->selected) continue;
        for (size_t j = 0U; j < object->weak_alias_sources.count; j++) {
            if (strcmp(object->weak_alias_sources.items[j], name) != 0)
                continue;
            if (ld_coff_capability_symbol_resolved(
                        state, object->weak_alias_targets.items[j], depth + 1U))
                return true;
        }
    }
    return false;
}

static int ld_coff_capability_validate_symbol_closure(
        ld_coff_capability_state_t *state) {
    bool changed;
    do {
        changed = false;
        for (size_t i = 0U; i < state->object_count; i++) {
            ld_coff_capability_object_t *object = &state->objects[i];
            if (!object->selected) continue;
            for (size_t j = 0U; j < object->undefined_symbols.count; j++) {
                const char *name = object->undefined_symbols.items[j];
                if (ld_coff_capability_linker_synthetic(name)) {
                    if (!ld_coff_capability_push_string(
                                &state->allowed_synthetic_symbols, name))
                        return ld_coff_capability_fail(
                                state, LD_IO_ERROR, "out of memory");
                    continue;
                }
                if (ld_coff_capability_external_contract(name)) {
                    if (!ld_coff_capability_push_string(
                                &state->external_contract_symbols, name))
                        return ld_coff_capability_fail(
                                state, LD_IO_ERROR, "out of memory");
                    continue;
                }
                bool defined = false;
                for (size_t k = 0U; k < state->object_count; k++) {
                    ld_coff_capability_object_t *provider =
                            &state->objects[k];
                    if (provider->selected &&
                        ld_coff_capability_object_defines(provider, name)) {
                        defined = true;
                        break;
                    }
                }
                if (defined) continue;
                for (size_t k = 0U; k < state->object_count; k++) {
                    ld_coff_capability_object_t *provider =
                            &state->objects[k];
                    if (provider->selected ||
                        !ld_coff_capability_object_provides(provider, name))
                        continue;
                    provider->selected = true;
                    changed = true;
                    break;
                }
            }
        }
    } while (changed);

    const char *hard_source = NULL;
    for (size_t i = 0U; i < state->object_count; i++) {
        ld_coff_capability_object_t *object = &state->objects[i];
        if (!object->selected) continue;
        for (size_t j = 0U; j < object->undefined_symbols.count; j++) {
            const char *name = object->undefined_symbols.items[j];
            if (ld_coff_capability_linker_synthetic(name)) {
                if (!ld_coff_capability_push_string(
                            &state->allowed_synthetic_symbols, name))
                    return ld_coff_capability_fail(state, LD_IO_ERROR,
                                                   "out of memory");
                continue;
            }
            if (ld_coff_capability_external_contract(name)) {
                if (!ld_coff_capability_push_string(
                            &state->external_contract_symbols, name))
                    return ld_coff_capability_fail(state, LD_IO_ERROR,
                                                   "out of memory");
                continue;
            }
            if (ld_coff_capability_symbol_resolved(state, name, 0U)) continue;
            if (ld_coff_capability_has_string(
                        &object->weak_undefined_symbols, name)) {
                if (!ld_coff_capability_push_string(
                            &state->weak_unresolved_symbols, name))
                    return ld_coff_capability_fail(state, LD_IO_ERROR,
                                                   "out of memory");
                continue;
            }
            if (!ld_coff_capability_push_string(
                        &state->hard_unresolved_symbols, name))
                return ld_coff_capability_fail(state, LD_IO_ERROR,
                                               "out of memory");
            if (!hard_source) hard_source = object->name;
        }
    }
    if (state->hard_unresolved_symbols.count != 0U)
        return ld_coff_capability_fail(
                state, LD_SYMBOL_ERROR,
                "windows_amd64 sysroot has unresolved symbol '%s' referenced by '%s' in the default archive closure",
                state->hard_unresolved_symbols.items[0],
                hard_source ? hard_source : "<unknown>");
    return LD_OK;
}

static bool ld_coff_capability_push_u16(ld_coff_capability_u16s_t *values,
                                        uint16_t value) {
    for (size_t i = 0U; i < values->count; i++)
        if (values->items[i] == value) return true;
    if (values->count == values->capacity) {
        size_t next = values->capacity ? values->capacity * 2U : 16U;
        if (next < values->capacity) return false;
        uint16_t *grown = ld_coff_capability_grow(
                values->items, values->capacity, next, sizeof(*grown));
        if (!grown) return false;
        values->items = grown;
        values->capacity = next;
    }
    values->items[values->count++] = value;
    return true;
}

static bool ld_coff_capability_push_u8(ld_coff_capability_u8s_t *values,
                                       uint8_t value) {
    for (size_t i = 0U; i < values->count; i++)
        if (values->items[i] == value) return true;
    if (values->count == values->capacity) {
        size_t next = values->capacity ? values->capacity * 2U : 8U;
        if (next < values->capacity) return false;
        uint8_t *grown = ld_coff_capability_grow(
                values->items, values->capacity, next, sizeof(*grown));
        if (!grown) return false;
        values->items = grown;
        values->capacity = next;
    }
    values->items[values->count++] = value;
    return true;
}

static bool ld_coff_capability_push_input(
        ld_coff_capability_state_t *state, const char *path,
        const char *type) {
    if (state->input_count == state->input_capacity) {
        size_t next = state->input_capacity ? state->input_capacity * 2U : 8U;
        if (next < state->input_capacity) return false;
        ld_coff_capability_input_t *grown = ld_coff_capability_grow(
                state->inputs, state->input_capacity, next, sizeof(*grown));
        if (!grown) return false;
        state->inputs = grown;
        state->input_capacity = next;
    }
    char *copy = ld_coff_capability_strdup(path);
    if (!copy) return false;
    state->inputs[state->input_count++] =
            (ld_coff_capability_input_t) {.path = copy, .type = type};
    return true;
}

static ld_coff_capability_object_t *ld_coff_capability_push_object(
        ld_coff_capability_state_t *state, const char *name,
        const char *container, const char *type) {
    if (state->object_count == state->object_capacity) {
        size_t next =
                state->object_capacity ? state->object_capacity * 2U : 32U;
        if (next < state->object_capacity) return NULL;
        ld_coff_capability_object_t *grown = ld_coff_capability_grow(
                state->objects, state->object_capacity, next,
                sizeof(*grown));
        if (!grown) return NULL;
        state->objects = grown;
        state->object_capacity = next;
    }
    char *copy = ld_coff_capability_strdup(name);
    if (!copy) return NULL;
    ld_coff_capability_object_t *object =
            &state->objects[state->object_count++];
    *object =
            (ld_coff_capability_object_t) {.name = copy,
                                           .container = container,
                                           .type = type};
    return object;
}

static const char *ld_coff_capability_basename(const char *path) {
    const char *base = path ? path : "";
    for (const char *cursor = base; *cursor; cursor++)
        if (*cursor == '/' || *cursor == '\\') base = cursor + 1U;
    return base;
}

static char *ld_coff_capability_normalized_object_name(
        const ld_coff_object_t *object) {
    const char *container = object && object->file
                                    ? ld_coff_capability_basename(
                                              object->file->path)
                                    : "<input>";
    if (!object || !object->archive_member)
        return ld_coff_capability_strdup(container);
    const char *member = ld_coff_capability_basename(
            object->member_name ? object->member_name : "<member>");
    size_t container_length = strlen(container);
    size_t member_length = strlen(member);
    if (container_length > SIZE_MAX - member_length - 3U) return NULL;
    char *name = malloc(container_length + member_length + 3U);
    if (!name) return NULL;
    memcpy(name, container, container_length);
    name[container_length] = '(';
    memcpy(name + container_length + 1U, member, member_length);
    name[container_length + 1U + member_length] = ')';
    name[container_length + 2U + member_length] = '\0';
    return name;
}

static bool ld_coff_capability_push_import(
        ld_coff_capability_state_t *state, const ld_coff_object_t *object,
        uint16_t version) {
    if (state->import_count == state->import_capacity) {
        size_t next =
                state->import_capacity ? state->import_capacity * 2U : 32U;
        if (next < state->import_capacity) return false;
        ld_coff_capability_import_t *grown = ld_coff_capability_grow(
                state->imports, state->import_capacity, next,
                sizeof(*grown));
        if (!grown) return false;
        state->imports = grown;
        state->import_capacity = next;
    }
    const ld_coff_import_t *source = object->import;
    ld_coff_capability_import_t value = {
            .object_name = ld_coff_capability_normalized_object_name(object),
            .dll = ld_coff_capability_strdup(source->dll_name),
            .symbol = ld_coff_capability_strdup(source->public_name),
            .import_name = ld_coff_capability_strdup(source->import_name),
            .version = version,
            .hint = source->ordinal_hint,
            .type = source->type,
            .name_type = source->name_type,
    };
    if (!value.object_name || !value.dll || !value.symbol ||
        !value.import_name) {
        free(value.object_name);
        free(value.dll);
        free(value.symbol);
        free(value.import_name);
        return false;
    }
    state->imports[state->import_count++] = value;
    return true;
}

