static uint16_t read16(ld_coff_view_t view, uint64_t offset) {
    uint16_t value;
    assert(ld_coff_read_u16(view, offset, &value));
    return value;
}

static uint32_t read32(ld_coff_view_t view, uint64_t offset) {
    uint32_t value;
    assert(ld_coff_read_u32(view, offset, &value));
    return value;
}

static uint64_t read64(ld_coff_view_t view, uint64_t offset) {
    uint64_t value;
    assert(ld_coff_read_u64(view, offset, &value));
    return value;
}

static void write_all(const char *path, const uint8_t *bytes, size_t size) {
    FILE *file = fopen(path, "wb");
    assert(file);
    assert(fwrite(bytes, 1U, size, file) == size);
    assert(fclose(file) == 0);
}

static uint8_t *read_all(const char *path, size_t *size) {
    FILE *file = fopen(path, "rb");
    assert(file);
    assert(fseek(file, 0, SEEK_END) == 0);
    long length = ftell(file);
    assert(length > 0 && fseek(file, 0, SEEK_SET) == 0);
    uint8_t *bytes = malloc((size_t) length);
    assert(bytes);
    assert(fread(bytes, 1U, (size_t) length, file) == (size_t) length);
    assert(fclose(file) == 0);
    *size = (size_t) length;
    return bytes;
}

static uint64_t pe_optional_offset(ld_coff_view_t view) {
    uint32_t pe = read32(view, 0x3cU);
    assert(pe == LD_PE_OFFSET);
    assert(ld_coff_range_ok(view, pe, 4U));
    assert(memcmp(view.bytes + pe, "PE\0\0", 4U) == 0);
    return (uint64_t) pe + 4U + LD_PE_COFF_HEADER_SIZE;
}

static bool pe_find_section(ld_coff_view_t view, const char *name,
                            pe_section_t *result) {
    uint32_t pe = read32(view, 0x3cU);
    uint16_t count = read16(view, pe + 6U);
    uint64_t headers = pe + 4U + LD_PE_COFF_HEADER_SIZE +
                       LD_PE_OPTIONAL_HEADER64_SIZE;
    for (uint16_t i = 0; i < count; i++) {
        uint64_t offset = headers + i * LD_PE_SECTION_HEADER_SIZE;
        assert(ld_coff_range_ok(view, offset, LD_PE_SECTION_HEADER_SIZE));
        char actual[9] = {0};
        memcpy(actual, view.bytes + offset, 8U);
        if (strcmp(actual, name) != 0) continue;
        result->virtual_size = read32(view, offset + 8U);
        result->rva = read32(view, offset + 12U);
        result->raw_offset = read32(view, offset + 20U);
        return true;
    }
    return false;
}

static uint64_t pe_rva_to_file(const pe_section_t *section, uint32_t rva) {
    assert(rva >= section->rva);
    uint32_t offset = rva - section->rva;
    assert(offset < section->virtual_size);
    return (uint64_t) section->raw_offset + offset;
}

static void add_bytes(coff_object_t *object, const char *name,
                      const void *bytes, size_t size, uint32_t alignment) {
    coff_section_t *section = NULL;
    uint32_t characteristics = LD_COFF_SCN_CNT_INITIALIZED_DATA |
                               LD_COFF_SCN_MEM_READ |
                               LD_COFF_SCN_MEM_WRITE;
    assert(coff_object_add_section(object, name, characteristics, alignment,
                                   &section) == COFF_WRITER_OK);
    assert(coff_section_append(section, bytes, size, alignment, NULL) ==
           COFF_WRITER_OK);
}

static void make_entry_object(const char *path, bool with_gnu_idata) {
    coff_object_t *object = coff_object_create("import-directories.c");
    assert(object);
    coff_section_t *text = NULL;
    assert(coff_object_add_section(
                   object, ".text",
                   LD_COFF_SCN_CNT_CODE | LD_COFF_SCN_MEM_EXECUTE |
                           LD_COFF_SCN_MEM_READ,
                   16U, &text) == COFF_WRITER_OK);
    static const uint8_t ret[] = {0xc3};
    assert(coff_section_append(text, ret, sizeof(ret), 1U, NULL) ==
           COFF_WRITER_OK);
    assert(coff_object_define_symbol(
                   object, "entry", text, 0U, COFF_SYMBOL_TYPE_FUNCTION,
                   LD_COFF_STORAGE_CLASS_EXTERNAL, NULL) == COFF_WRITER_OK);

    if (with_gnu_idata) {
        uint8_t prefix[12];
        uint8_t descriptor[20];
        uint8_t terminator[20] = {0};
        uint8_t lookup[8];
        uint8_t address[16];
        memset(prefix, 0xa1, sizeof(prefix));
        memset(descriptor, 0xd2, sizeof(descriptor));
        memset(lookup, 0xa4, sizeof(lookup));
        memset(address, 0xa5, sizeof(address));
        add_bytes(object, ".idata$1", prefix, sizeof(prefix), 1U);
        add_bytes(object, ".idata$2", descriptor, sizeof(descriptor), 4U);
        add_bytes(object, ".idata$3", terminator, sizeof(terminator), 4U);
        add_bytes(object, ".idata$4", lookup, sizeof(lookup), 8U);
        add_bytes(object, ".idata$5", address, sizeof(address), 8U);
    }

    assert(coff_object_write_file(object, path) == COFF_WRITER_OK);
    coff_object_destroy(object);
}

static void make_named_short_import(const char *path, const char *symbol,
                                    const char *dll) {
    size_t symbol_size = strlen(symbol) + 1U;
    size_t dll_size = strlen(dll) + 1U;
    size_t size = LD_COFF_IMPORT_HEADER_SIZE + symbol_size + dll_size;
    uint8_t *bytes = calloc(1, size);
    assert(bytes);
    put16(bytes, size, 2U, 0xffffU);
    put16(bytes, size, 6U, LD_COFF_MACHINE_AMD64);
    put32(bytes, size, 12U, (uint32_t) (symbol_size + dll_size));
    put16(bytes, size, 18U,
          LD_COFF_IMPORT_CODE | (LD_COFF_IMPORT_NAME << 2U));
    memcpy(bytes + LD_COFF_IMPORT_HEADER_SIZE, symbol, symbol_size);
    memcpy(bytes + LD_COFF_IMPORT_HEADER_SIZE + symbol_size, dll, dll_size);
    write_all(path, bytes, size);
    free(bytes);
}

static void make_ordinal_short_import(const char *path, const char *symbol,
                                      const char *dll, uint16_t ordinal) {
    size_t symbol_size = strlen(symbol) + 1U;
    size_t dll_size = strlen(dll) + 1U;
    size_t size = LD_COFF_IMPORT_HEADER_SIZE + symbol_size + dll_size;
    uint8_t *bytes = calloc(1, size);
    assert(bytes);
    put16(bytes, size, 2U, 0xffffU);
    put16(bytes, size, 6U, LD_COFF_MACHINE_AMD64);
    put32(bytes, size, 12U, (uint32_t) (symbol_size + dll_size));
    put16(bytes, size, 16U, ordinal);
    put16(bytes, size, 18U,
          LD_COFF_IMPORT_CODE | (LD_COFF_IMPORT_ORDINAL << 2U));
    memcpy(bytes + LD_COFF_IMPORT_HEADER_SIZE, symbol, symbol_size);
    memcpy(bytes + LD_COFF_IMPORT_HEADER_SIZE + symbol_size, dll, dll_size);
    write_all(path, bytes, size);
    free(bytes);
}

static ld_coff_view_t link_fixture(const char *object, const char *import,
                                   const char *output, uint8_t **image) {
    char *inputs[2] = {(char *) object, (char *) import};
    diagnostic_capture_t capture = {{0}};
    ld_options_t options = {0};
    options.os = LD_OS_WINDOWS;
    options.arch = LD_ARCH_AMD64;
    options.output_path = output;
    options.entry_symbol = "entry";
    options.inputs.items = inputs;
    options.inputs.count = import ? 2U : 1U;
    options.inputs.capacity = options.inputs.count;
    options.diagnostic = diagnostic;
    options.diagnostic_context = &capture;
    int status = ld_link(&options);
    if (status != LD_OK) fprintf(stderr, "%s\n", capture.message);
    assert(status == LD_OK);
    size_t image_size;
    *image = read_all(output, &image_size);
    return (ld_coff_view_t) {*image, image_size};
}

static void assert_gnu_prefix(ld_coff_view_t view, const pe_section_t *idata,
                              uint32_t directory_rva) {
    assert(directory_rva == idata->rva + 12U);
    uint64_t offset = pe_rva_to_file(idata, directory_rva);
    for (size_t i = 0; i < 20U; i++) assert(view.bytes[offset + i] == 0xd2U);
}

static void test_pure_short(const char *directory) {
    char object[512], import[512], output[512];
    snprintf(object, sizeof(object), "%s/short-entry.obj", directory);
    snprintf(import, sizeof(import), "%s/short.obj", directory);
    snprintf(output, sizeof(output), "%s/short.exe", directory);
    make_entry_object(object, false);
    make_short_import(import);

    uint8_t *image;
    ld_coff_view_t view = link_fixture(object, import, output, &image);
    pe_section_t idata;
    assert(pe_find_section(view, ".idata", &idata));
    assert(pe_directory_rva(view, LD_PE_DIRECTORY_IMPORT) == idata.rva);
    assert(pe_directory_size(view, LD_PE_DIRECTORY_IMPORT) == 40U);
    assert(pe_directory_size(view, LD_PE_DIRECTORY_IAT) == 16U);
    uint64_t descriptor = pe_rva_to_file(
            &idata, pe_directory_rva(view, LD_PE_DIRECTORY_IMPORT));
    assert(read32(view, descriptor) != 0U);
    assert(read32(view, descriptor + 12U) != 0U);
    assert(read32(view, descriptor + 16U) != 0U);
    for (size_t i = 20U; i < 40U; i++)
        assert(view.bytes[descriptor + i] == 0U);
    free(image);
}

static void test_ordinal_short_import(const char *directory) {
    char object[512], import[512], output[512];
    snprintf(object, sizeof(object), "%s/ordinal-entry.obj", directory);
    snprintf(import, sizeof(import), "%s/ordinal.obj", directory);
    snprintf(output, sizeof(output), "%s/ordinal.exe", directory);
    make_entry_object(object, false);
    make_ordinal_short_import(import, "OrdinalOnly", "KERNEL32.dll", 77U);

    uint8_t *image;
    ld_coff_view_t view = link_fixture(object, import, output, &image);
    pe_section_t idata;
    assert(pe_find_section(view, ".idata", &idata));
    uint64_t descriptor = pe_rva_to_file(
            &idata, pe_directory_rva(view, LD_PE_DIRECTORY_IMPORT));
    uint32_t ilt_rva = read32(view, descriptor);
    uint32_t iat_rva = read32(view, descriptor + 16U);
    uint64_t expected = UINT64_C(0x8000000000000000) | 77U;
    assert(read64(view, pe_rva_to_file(&idata, ilt_rva)) == expected);
    assert(read64(view, pe_rva_to_file(&idata, iat_rva)) == expected);
    free(image);
}

static void test_pure_gnu(const char *directory) {
    char object[512], output[512];
    snprintf(object, sizeof(object), "%s/gnu-entry.obj", directory);
    snprintf(output, sizeof(output), "%s/gnu.exe", directory);
    make_entry_object(object, true);

    uint8_t *image;
    ld_coff_view_t view = link_fixture(object, NULL, output, &image);
    pe_section_t idata;
    assert(pe_find_section(view, ".idata", &idata));
    uint32_t import_rva = pe_directory_rva(view, LD_PE_DIRECTORY_IMPORT);
    assert_gnu_prefix(view, &idata, import_rva);
    assert(pe_directory_size(view, LD_PE_DIRECTORY_IMPORT) == 20U);
    assert(pe_directory_size(view, LD_PE_DIRECTORY_IAT) == 16U);
    uint64_t iat = pe_rva_to_file(
            &idata, pe_directory_rva(view, LD_PE_DIRECTORY_IAT));
    for (size_t i = 0; i < 16U; i++) assert(view.bytes[iat + i] == 0xa5U);
    free(image);
}

static void test_mixed(const char *directory) {
    char object[512], import[512], output[512];
    snprintf(object, sizeof(object), "%s/mixed-entry.obj", directory);
    snprintf(import, sizeof(import), "%s/mixed-short.obj", directory);
    snprintf(output, sizeof(output), "%s/mixed.exe", directory);
    make_entry_object(object, true);
    make_short_import(import);

    uint8_t *image;
    ld_coff_view_t view = link_fixture(object, import, output, &image);
    pe_section_t idata;
    assert(pe_find_section(view, ".idata", &idata));
    uint32_t import_rva = pe_directory_rva(view, LD_PE_DIRECTORY_IMPORT);
    assert_gnu_prefix(view, &idata, import_rva);
    assert(pe_directory_size(view, LD_PE_DIRECTORY_IMPORT) == 60U);
    uint64_t descriptors = pe_rva_to_file(&idata, import_rva);
    assert(read32(view, descriptors + 20U) != 0U);
    assert(read32(view, descriptors + 32U) != 0U);
    assert(read32(view, descriptors + 36U) != 0U);
    for (size_t i = 40U; i < 60U; i++)
        assert(view.bytes[descriptors + i] == 0U);

    assert(pe_directory_size(view, LD_PE_DIRECTORY_IAT) == 32U);
    uint64_t iat = pe_rva_to_file(
            &idata, pe_directory_rva(view, LD_PE_DIRECTORY_IAT));
    for (size_t i = 0; i < 16U; i++) assert(view.bytes[iat + i] == 0xa5U);
    assert(read64(view, iat + 16U) != 0U);
    assert(read64(view, iat + 24U) == 0U);
    free(image);
}

static void test_duplicate_short_import(const char *directory) {
    char object[512], first[512], second[512], output[512];
    snprintf(object, sizeof(object), "%s/duplicate-entry.obj", directory);
    snprintf(first, sizeof(first), "%s/duplicate-first.obj", directory);
    snprintf(second, sizeof(second), "%s/duplicate-second.obj", directory);
    snprintf(output, sizeof(output), "%s/duplicate.exe", directory);
    make_entry_object(object, false);
    make_short_import(first);
    make_short_import(second);

    char *inputs[] = {object, first, second};
    diagnostic_capture_t capture = {{0}};
    ld_options_t options = {0};
    options.os = LD_OS_WINDOWS;
    options.arch = LD_ARCH_AMD64;
    options.output_path = output;
    options.entry_symbol = "entry";
    options.inputs.items = inputs;
    options.inputs.count = sizeof(inputs) / sizeof(*inputs);
    options.inputs.capacity = options.inputs.count;
    options.diagnostic = diagnostic;
    options.diagnostic_context = &capture;
    int status = ld_link(&options);
    if (status != LD_OK) fprintf(stderr, "%s\n", capture.message);
    assert(status == LD_OK);

    size_t image_size = 0U;
    uint8_t *image = read_all(output, &image_size);
    ld_coff_view_t view = {image, image_size};
    assert(pe_directory_size(view, LD_PE_DIRECTORY_IMPORT) == 40U);
    assert(pe_directory_size(view, LD_PE_DIRECTORY_IAT) == 16U);
    free(image);
}

static void test_duplicate_short_import_across_dlls(const char *directory) {
    char object[512], first[512], second[512], output[512];
    snprintf(object, sizeof(object), "%s/duplicate-dll-entry.obj", directory);
    snprintf(first, sizeof(first), "%s/duplicate-ucrt.obj", directory);
    snprintf(second, sizeof(second), "%s/duplicate-apiset.obj", directory);
    snprintf(output, sizeof(output), "%s/duplicate-dll.exe", directory);
    make_entry_object(object, false);
    make_named_short_import(first, "ShortOnly", "ucrtbase.dll");
    make_named_short_import(second, "ShortOnly",
                            "api-ms-win-crt-time-l1-1-0.dll");

    char *inputs[] = {object, first, second};
    diagnostic_capture_t capture = {{0}};
    ld_options_t options = {0};
    options.os = LD_OS_WINDOWS;
    options.arch = LD_ARCH_AMD64;
    options.output_path = output;
    options.entry_symbol = "entry";
    options.inputs.items = inputs;
    options.inputs.count = sizeof(inputs) / sizeof(*inputs);
    options.inputs.capacity = options.inputs.count;
    options.diagnostic = diagnostic;
    options.diagnostic_context = &capture;
    int status = ld_link(&options);
    if (status != LD_OK) fprintf(stderr, "%s\n", capture.message);
    assert(status == LD_OK);

    size_t image_size = 0U;
    uint8_t *image = read_all(output, &image_size);
    ld_coff_view_t view = {image, image_size};
    assert(pe_directory_size(view, LD_PE_DIRECTORY_IMPORT) == 40U);
    assert(pe_directory_size(view, LD_PE_DIRECTORY_IAT) == 16U);
    free(image);
}

int main(void) {
    char directory[] = "/tmp/nature-ld-coff-import-directories-XXXXXX";
    assert(mkdtemp(directory));
    test_pure_short(directory);
    test_ordinal_short_import(directory);
    test_pure_gnu(directory);
    test_mixed(directory);
    test_duplicate_short_import(directory);
    test_duplicate_short_import_across_dlls(directory);
    return 0;
}

static void diagnostic(void *context, ld_diag_level_t level,
                       const char *message) {
    (void) level;
    diagnostic_capture_t *capture = context;
    snprintf(capture->message, sizeof(capture->message), "%s", message);
}

static void write_all(int descriptor, const uint8_t *bytes, size_t size) {
    size_t offset = 0U;
    while (offset < size) {
        ssize_t count = write(descriptor, bytes + offset, size - offset);
        assert(count > 0);
        offset += (size_t) count;
    }
}

static int load_bytes(const uint8_t *bytes, size_t size,
                      diagnostic_capture_t *capture) {
    char path[] = "/tmp/nature-coff-input-XXXXXX";
    int descriptor = mkstemp(path);
    assert(descriptor >= 0);
    write_all(descriptor, bytes, size);
    assert(close(descriptor) == 0);

    ld_options_t options = {0};
    options.os = LD_OS_WINDOWS;
    options.arch = LD_ARCH_AMD64;
    options.diagnostic = diagnostic;
    options.diagnostic_context = capture;
    ld_coff_context_t context;
    ld_coff_context_init(&context, &options);
    int status = ld_coff_load_input(&context, path);
    ld_coff_context_deinit(&context);
    assert(unlink(path) == 0);
    return status;
}

static void expect_status(const uint8_t *bytes, size_t size, int expected,
                          const char *message) {
    diagnostic_capture_t capture = {{0}};
    assert(load_bytes(bytes, size, &capture) == expected);
    if (message)
        assert(strstr(capture.message, message) != NULL);
    else
        assert(capture.message[0] == '\0');
}

static void build_bigobj(uint8_t bytes[LD_COFF_BIGOBJ_HEADER_SIZE],
                         uint16_t version) {
    memset(bytes, 0, LD_COFF_BIGOBJ_HEADER_SIZE);
    put16(bytes, LD_COFF_BIGOBJ_HEADER_SIZE, 2U, 0xffffU);
    put16(bytes, LD_COFF_BIGOBJ_HEADER_SIZE, 4U, version);
    put16(bytes, LD_COFF_BIGOBJ_HEADER_SIZE, 6U, LD_COFF_MACHINE_AMD64);
    memcpy(bytes + 12U, LD_COFF_BIGOBJ_MAGIC, 16U);
}

static size_t build_short_import(uint8_t *bytes, size_t capacity,
                                 uint16_t version, uint16_t type_info) {
    static const char symbol[] = "ExitProcess";
    static const char dll[] = "KERNEL32.dll";
    size_t data_size = sizeof(symbol) + sizeof(dll);
    size_t size = LD_COFF_IMPORT_HEADER_SIZE + data_size;
    assert(size <= capacity);
    memset(bytes, 0, size);
    put16(bytes, size, 2U, 0xffffU);
    put16(bytes, size, 4U, version);
    put16(bytes, size, 6U, LD_COFF_MACHINE_AMD64);
    put32(bytes, size, 12U, (uint32_t) data_size);
    put16(bytes, size, 18U, type_info);
    memcpy(bytes + LD_COFF_IMPORT_HEADER_SIZE, symbol, sizeof(symbol));
    memcpy(bytes + LD_COFF_IMPORT_HEADER_SIZE + sizeof(symbol), dll,
           sizeof(dll));
    return size;
}

static size_t build_llvm_lto_object(uint8_t *bytes, size_t capacity) {
    static const char name[] = ".llvm.lto";
    const size_t string_table = LD_COFF_HEADER_SIZE +
                                LD_COFF_SECTION_HEADER_SIZE;
    const size_t string_size = 4U + sizeof(name);
    const size_t size = string_table + string_size;
    assert(size <= capacity);
    memset(bytes, 0, size);
    put16(bytes, size, 0U, LD_COFF_MACHINE_AMD64);
    put16(bytes, size, 2U, 1U);
    put32(bytes, size, 8U, (uint32_t) string_table);
    memcpy(bytes + LD_COFF_HEADER_SIZE, "/4", 2U);
    put32(bytes, size, LD_COFF_HEADER_SIZE + 36U,
          LD_COFF_SCN_CNT_INITIALIZED_DATA | LD_COFF_SCN_MEM_READ);
    put32(bytes, size, string_table, (uint32_t) string_size);
    memcpy(bytes + string_table + 4U, name, sizeof(name));
    return size;
}

static void test_bigobj_version(void) {
    uint8_t bytes[LD_COFF_BIGOBJ_HEADER_SIZE];
    build_bigobj(bytes, 2U);
    expect_status(bytes, sizeof(bytes), LD_OK, NULL);
    build_bigobj(bytes, 3U);
    expect_status(bytes, sizeof(bytes), LD_INVALID_INPUT,
                  "BigObj header version 3; expected version 2");
}

static void test_bigobj_sections_symbols_aux_and_relocation(void) {
    const size_t section_table = LD_COFF_BIGOBJ_HEADER_SIZE;
    const size_t raw_data = section_table + LD_COFF_SECTION_HEADER_SIZE;
    const size_t relocations = raw_data + 4U;
    const size_t symbols = relocations + LD_COFF_RELOCATION_SIZE;
    const size_t string_table =
            symbols + 3U * LD_COFF_BIGOBJ_SYMBOL_SIZE;
    const size_t size = string_table + 16U;
    uint8_t *bytes = calloc(1, size);
    assert(bytes);
    build_bigobj(bytes, 2U);
    put32(bytes, size, 44U, 1U);
    put32(bytes, size, 48U, (uint32_t) symbols);
    put32(bytes, size, 52U, 3U);

    memcpy(bytes + section_table, ".text", 5U);
    put32(bytes, size, section_table + 8U, 4U);
    put32(bytes, size, section_table + 16U, 4U);
    put32(bytes, size, section_table + 20U, (uint32_t) raw_data);
    put32(bytes, size, section_table + 24U, (uint32_t) relocations);
    put16(bytes, size, section_table + 32U, 1U);
    put32(bytes, size, section_table + 36U,
          LD_COFF_SCN_CNT_CODE | LD_COFF_SCN_MEM_EXECUTE |
                  LD_COFF_SCN_MEM_READ);
    bytes[raw_data] = 0xc3U;
    put32(bytes, size, relocations, 0U);
    put32(bytes, size, relocations + 4U, 2U);
    put16(bytes, size, relocations + 8U, LD_COFF_REL_AMD64_REL32);

    memcpy(bytes + symbols, "entry", 5U);
    put32(bytes, size, symbols + 12U, 1U);
    put16(bytes, size, symbols + 16U, 0x20U);
    bytes[symbols + 18U] = LD_COFF_STORAGE_CLASS_EXTERNAL;
    bytes[symbols + 19U] = 1U;
    size_t target = symbols + 2U * LD_COFF_BIGOBJ_SYMBOL_SIZE;
    put32(bytes, size, target + 4U, 4U);
    bytes[target + 18U] = LD_COFF_STORAGE_CLASS_EXTERNAL;
    put32(bytes, size, string_table, 16U);
    memcpy(bytes + string_table + 4U, "ExitProcess", 12U);

    char path[] = "/tmp/nature-coff-bigobj-XXXXXX";
    int descriptor = mkstemp(path);
    assert(descriptor >= 0);
    write_all(descriptor, bytes, size);
    assert(close(descriptor) == 0);
    free(bytes);

    diagnostic_capture_t capture = {{0}};
    ld_options_t options = {0};
    options.os = LD_OS_WINDOWS;
    options.arch = LD_ARCH_AMD64;
    options.diagnostic = diagnostic;
    options.diagnostic_context = &capture;
    ld_coff_context_t context;
    ld_coff_context_init(&context, &options);
    assert(ld_coff_load_input(&context, path) == LD_OK);
    assert(context.object_count == 1U && context.objects[0]->bigobj);
    assert(context.objects[0]->section_count == 1U);
    assert(context.objects[0]->sections[0].relocation_count == 1U);
    assert(context.objects[0]->sections[0].relocations[0].symbol_index == 2U);
    assert(context.objects[0]->symbols[0].aux_count == 1U);
    assert(context.objects[0]->symbols[1].auxiliary);
    assert(strcmp(context.objects[0]->symbols[2].name, "ExitProcess") == 0);
    ld_coff_context_deinit(&context);
    assert(unlink(path) == 0);
}

static void test_short_import_header(void) {
    uint8_t bytes[128];
    size_t size = build_short_import(
            bytes, sizeof(bytes), 0U,
            LD_COFF_IMPORT_CODE | (LD_COFF_IMPORT_NAME << 2U));
    expect_status(bytes, size, LD_OK, NULL);

    size = build_short_import(
            bytes, sizeof(bytes), 1U,
            LD_COFF_IMPORT_CODE | (LD_COFF_IMPORT_NAME << 2U));
    expect_status(bytes, size, LD_INVALID_INPUT,
                  "short import version 1; expected version 0");

    size = build_short_import(
            bytes, sizeof(bytes), 0U,
            LD_COFF_IMPORT_CODE | (LD_COFF_IMPORT_NAME << 2U) | 0x20U);
    expect_status(bytes, size, LD_INVALID_INPUT,
                  "short import TypeInfo bits");
}

static void test_anonymous_object_is_not_import(void) {
    uint8_t bytes[LD_COFF_BIGOBJ_HEADER_SIZE] = {0};
    put16(bytes, sizeof(bytes), 2U, 0xffffU);
    put16(bytes, sizeof(bytes), 4U, 1U);
    put16(bytes, sizeof(bytes), 6U, LD_COFF_MACHINE_AMD64);
    memset(bytes + 12U, 0xa5, 16U);
    diagnostic_capture_t capture = {{0}};
    assert(load_bytes(bytes, sizeof(bytes), &capture) == LD_UNSUPPORTED);
    assert(strstr(capture.message, "unsupported anonymous COFF object"));
    assert(strstr(capture.message, "short import object") == NULL);
}

static void test_lto_rejection(void) {
    uint8_t bytes[128];
    size_t size = build_llvm_lto_object(bytes, sizeof(bytes));
    expect_status(bytes, size, LD_UNSUPPORTED, ".llvm.lto");
    diagnostic_capture_t capture = {{0}};
    assert(load_bytes(bytes, size, &capture) == LD_UNSUPPORTED);
    assert(strstr(capture.message, "-fno-lto"));

    memset(bytes, 0, LD_COFF_BIGOBJ_HEADER_SIZE);
    put16(bytes, sizeof(bytes), 2U, 0xffffU);
    put16(bytes, sizeof(bytes), 4U, 2U);
    put16(bytes, sizeof(bytes), 6U, LD_COFF_MACHINE_AMD64);
    memcpy(bytes + 12U, LD_COFF_CL_GL_MAGIC, 16U);
    capture.message[0] = '\0';
    assert(load_bytes(bytes, LD_COFF_BIGOBJ_HEADER_SIZE, &capture) ==
           LD_UNSUPPORTED);
    assert(strstr(capture.message, "MSVC LTCG"));
    assert(strstr(capture.message, "/GL-"));
}

int main(void) {
    test_bigobj_version();
    test_bigobj_sections_symbols_aux_and_relocation();
    test_short_import_header();
    test_anonymous_object_is_not_import();
    test_lto_rejection();
    return 0;
}

static void diagnostic(void *context, ld_diag_level_t level,
                       const char *message) {
    (void) level;
    diagnostic_capture_t *capture = context;
    snprintf(capture->message, sizeof(capture->message), "%s", message);
}

static uint8_t *build_object(const char *definition,
                             const char *undefined_symbol,
                             const char *directives, size_t *size) {
    coff_object_t *object = coff_object_create("nodefaultlib.c");
    assert(object);
    coff_section_t *text = NULL;
    assert(coff_object_add_section(
                   object, ".text",
                   LD_COFF_SCN_CNT_CODE | LD_COFF_SCN_MEM_EXECUTE |
                           LD_COFF_SCN_MEM_READ,
                   16U, &text) == COFF_WRITER_OK);
    static const uint8_t ret[] = {0xc3};
    assert(coff_section_append(text, ret, sizeof(ret), 1U, NULL) ==
           COFF_WRITER_OK);
    assert(coff_object_define_symbol(
                   object, definition, text, 0U, COFF_SYMBOL_TYPE_FUNCTION,
                   LD_COFF_STORAGE_CLASS_EXTERNAL, NULL) == COFF_WRITER_OK);
    if (undefined_symbol) {
        assert(coff_object_get_or_add_symbol_reference(
                       object, undefined_symbol, true, 0U, NULL) ==
               COFF_WRITER_OK);
    }
    if (directives) {
        coff_section_t *section = NULL;
        assert(coff_object_add_section(
                       object, ".drectve",
                       LD_COFF_SCN_CNT_INITIALIZED_DATA |
                               LD_COFF_SCN_LNK_INFO |
                               LD_COFF_SCN_LNK_REMOVE,
                       1U, &section) == COFF_WRITER_OK);
        assert(coff_section_append(section, directives, strlen(directives),
                                   1U, NULL) == COFF_WRITER_OK);
    }
    uint8_t *bytes = NULL;
    assert(coff_object_serialize(object, &bytes, size) == COFF_WRITER_OK);
    coff_object_destroy(object);
    return bytes;
}

static void write_all(const char *path, const uint8_t *bytes, size_t size) {
    FILE *file = fopen(path, "wb");
    assert(file);
    assert(fwrite(bytes, 1U, size, file) == size);
    assert(fclose(file) == 0);
}

static void write_object(const char *path, const char *definition,
                         const char *undefined_symbol,
                         const char *directives) {
    size_t size;
    uint8_t *bytes =
            build_object(definition, undefined_symbol, directives, &size);
    write_all(path, bytes, size);
    free(bytes);
}

static void archive_header(uint8_t header[LD_COFF_ARCHIVE_HEADER_SIZE],
                           const char *name, size_t size) {
    memset(header, ' ', LD_COFF_ARCHIVE_HEADER_SIZE);
    size_t name_length = strlen(name);
    assert(name_length + 1U <= 16U);
    memcpy(header, name, name_length);
    header[name_length] = '/';
    memcpy(header + 16U, "0", 1U);
    memcpy(header + 28U, "0", 1U);
    memcpy(header + 34U, "0", 1U);
    memcpy(header + 40U, "644", 3U);
    char encoded[32];
    int length = snprintf(encoded, sizeof(encoded), "%zu", size);
    assert(length > 0 && length <= 10);
    memcpy(header + 48U, encoded, (size_t) length);
    header[58U] = '`';
    header[59U] = '\n';
}

static void write_archive(const char *path, const uint8_t *first,
                          size_t first_size, const uint8_t *second,
                          size_t second_size) {
    FILE *file = fopen(path, "wb");
    assert(file);
    assert(fwrite(LD_COFF_ARCHIVE_MAGIC, 1U, LD_COFF_ARCHIVE_MAGIC_SIZE,
                  file) == LD_COFF_ARCHIVE_MAGIC_SIZE);
    uint8_t header[LD_COFF_ARCHIVE_HEADER_SIZE];
    archive_header(header, "trigger.obj", first_size);
    assert(fwrite(header, 1U, sizeof(header), file) == sizeof(header));
    assert(fwrite(first, 1U, first_size, file) == first_size);
    if (first_size & 1U) assert(fputc('\n', file) != EOF);
    archive_header(header, "suppress.obj", second_size);
    assert(fwrite(header, 1U, sizeof(header), file) == sizeof(header));
    assert(fwrite(second, 1U, second_size, file) == second_size);
    if (second_size & 1U) assert(fputc('\n', file) != EOF);
    assert(fclose(file) == 0);
}

static void link_success(const char *output, char **inputs, size_t input_count,
                         const char *library_directory) {
    char *library_paths[] = {(char *) library_directory};
    diagnostic_capture_t capture = {{0}};
    ld_options_t options = {0};
    options.os = LD_OS_WINDOWS;
    options.arch = LD_ARCH_AMD64;
    options.output_path = output;
    options.entry_symbol = "entry";
    options.inputs.items = inputs;
    options.inputs.count = input_count;
    options.inputs.capacity = input_count;
    options.library_paths.items = library_paths;
    options.library_paths.count = 1U;
    options.library_paths.capacity = 1U;
    options.diagnostic = diagnostic;
    options.diagnostic_context = &capture;
    int status = ld_link(&options);
    if (status != LD_OK) fprintf(stderr, "%s\n", capture.message);
    assert(status == LD_OK);
}

static void test_direct_object_order(const char *directory) {
    char entry[512], suppress[512], first_output[512], second_output[512];
    snprintf(entry, sizeof(entry), "%s/direct-entry.obj", directory);
    snprintf(suppress, sizeof(suppress), "%s/direct-suppress.obj", directory);
    snprintf(first_output, sizeof(first_output), "%s/direct-first.exe",
             directory);
    snprintf(second_output, sizeof(second_output), "%s/direct-second.exe",
             directory);
    write_object(entry, "entry", NULL, "/DEFAULTLIB:never_load_me");
    write_object(suppress, "suppress_marker", NULL,
                 "/NODEFAULTLIB:NEVER_LOAD_ME.LIB");
    char *first_inputs[] = {entry, suppress};
    char *second_inputs[] = {suppress, entry};
    link_success(first_output, first_inputs, 2U, directory);
    link_success(second_output, second_inputs, 2U, directory);
}

static void test_directive_order(const char *directory) {
    char first[512], second[512], first_output[512], second_output[512];
    snprintf(first, sizeof(first), "%s/directives-first.obj", directory);
    snprintf(second, sizeof(second), "%s/directives-second.obj", directory);
    snprintf(first_output, sizeof(first_output), "%s/directives-first.exe",
             directory);
    snprintf(second_output, sizeof(second_output), "%s/directives-second.exe",
             directory);
    write_object(first, "entry", NULL,
                 "/DEFAULTLIB:never_load_me "
                 "/NODEFAULTLIB:NEVER_LOAD_ME.LIB");
    write_object(second, "entry", NULL,
                 "/NODEFAULTLIB:never_load_me.lib "
                 "/DEFAULTLIB:NEVER_LOAD_ME");
    char *first_inputs[] = {first};
    char *second_inputs[] = {second};
    link_success(first_output, first_inputs, 1U, directory);
    link_success(second_output, second_inputs, 1U, directory);
}

static void test_wildcard(const char *directory) {
    char object[512], output[512];
    snprintf(object, sizeof(object), "%s/wildcard.obj", directory);
    snprintf(output, sizeof(output), "%s/wildcard.exe", directory);
    write_object(object, "entry", NULL,
                 "/DEFAULTLIB:never_load_me /NODEFAULTLIB");
    char *inputs[] = {object};
    link_success(output, inputs, 1U, directory);
}

static void test_name_normalization(const char *directory) {
    char archive_style[512], path_style[512];
    char archive_output[512], path_output[512];
    snprintf(archive_style, sizeof(archive_style), "%s/archive-style.obj",
             directory);
    snprintf(path_style, sizeof(path_style), "%s/path-style.obj", directory);
    snprintf(archive_output, sizeof(archive_output), "%s/archive-style.exe",
             directory);
    snprintf(path_output, sizeof(path_output), "%s/path-style.exe", directory);
    write_object(archive_style, "entry", NULL,
                 "/DEFAULTLIB:never_load_me.a "
                 "/NODEFAULTLIB:NEVER_LOAD_ME");
    write_object(path_style, "entry", NULL,
                 "/DEFAULTLIB:never_load_me "
                 "/NODEFAULTLIB:C:\\SDK\\NEVER_LOAD_ME.LIB");
    char *archive_inputs[] = {archive_style};
    char *path_inputs[] = {path_style};
    link_success(archive_output, archive_inputs, 1U, directory);
    link_success(path_output, path_inputs, 1U, directory);
}

static void test_archive_member_discovery(const char *directory) {
    char entry[512], archive[512], reverse_archive[512];
    char output[512], reverse_output[512];
    snprintf(entry, sizeof(entry), "%s/archive-entry.obj", directory);
    snprintf(archive, sizeof(archive), "%s/directives.lib", directory);
    snprintf(reverse_archive, sizeof(reverse_archive),
             "%s/directives-reverse.lib", directory);
    snprintf(output, sizeof(output), "%s/archive.exe", directory);
    snprintf(reverse_output, sizeof(reverse_output), "%s/archive-reverse.exe",
             directory);
    write_object(entry, "entry", "trigger", NULL);

    size_t trigger_size, suppress_size;
    uint8_t *trigger = build_object(
            "trigger", "next",
            "/DEFAULTLIB:never_load_me", &trigger_size);
    uint8_t *suppress = build_object(
            "next", NULL, "/NODEFAULTLIB:NEVER_LOAD_ME.LIB",
            &suppress_size);
    write_archive(archive, trigger, trigger_size, suppress, suppress_size);
    write_archive(reverse_archive, suppress, suppress_size, trigger,
                  trigger_size);
    free(trigger);
    free(suppress);

    char *inputs[] = {entry, archive};
    char *reverse_inputs[] = {entry, reverse_archive};
    link_success(output, inputs, 2U, directory);
    link_success(reverse_output, reverse_inputs, 2U, directory);
}

int main(void) {
    char directory[] = "/tmp/nature-ld-coff-nodefaultlib-XXXXXX";
    assert(mkdtemp(directory));
    test_direct_object_order(directory);
    test_directive_order(directory);
    test_wildcard(directory);
    test_name_normalization(directory);
    test_archive_member_discovery(directory);
    return 0;
}

static void diagnostic(void *context, ld_diag_level_t level,
                       const char *message) {
    (void) level;
    diagnostic_capture_t *capture = context;
    snprintf(capture->message, sizeof(capture->message), "%s", message);
}

static bool relocation_supported(uint16_t type) {
    switch (type) {
        case LD_COFF_REL_AMD64_ABSOLUTE:
        case LD_COFF_REL_AMD64_ADDR64:
        case LD_COFF_REL_AMD64_ADDR32:
        case LD_COFF_REL_AMD64_ADDR32NB:
        case LD_COFF_REL_AMD64_REL32:
        case LD_COFF_REL_AMD64_REL32_1:
        case LD_COFF_REL_AMD64_REL32_2:
        case LD_COFF_REL_AMD64_REL32_3:
        case LD_COFF_REL_AMD64_REL32_4:
        case LD_COFF_REL_AMD64_REL32_5:
        case LD_COFF_REL_AMD64_SECTION:
        case LD_COFF_REL_AMD64_SECREL:
            return true;
        default:
            return false;
    }
}

static void check_object_capabilities(ld_coff_context_t *context,
                                      const char *input_name) {
    for (size_t i = 0; i < context->object_count; i++) {
        ld_coff_object_t *object = context->objects[i];
        if (object->import_object) continue;
        for (size_t j = 0; j < object->section_count; j++) {
            ld_coff_section_t *section = &object->sections[j];
            if ((section->characteristics & LD_COFF_SCN_LNK_COMDAT) != 0U) {
                if (section->comdat_selection <
                            LD_COFF_COMDAT_NODUPLICATES ||
                    section->comdat_selection > LD_COFF_COMDAT_LARGEST) {
                    fprintf(stderr,
                            "%s: %s(%s) uses unsupported COMDAT selection "
                            "%u\n",
                            input_name, object->display_name, section->name,
                            section->comdat_selection);
                    assert(false);
                }
                if (section->comdat_selection ==
                            LD_COFF_COMDAT_ASSOCIATIVE &&
                    (section->associative_section == 0U ||
                     section->associative_section > object->section_count)) {
                    fprintf(stderr,
                            "%s: %s(%s) has invalid associative parent %u\n",
                            input_name, object->display_name, section->name,
                            section->associative_section);
                    assert(false);
                }
            }
            for (size_t k = 0; k < section->relocation_count; k++) {
                if (!relocation_supported(section->relocations[k].type)) {
                    fprintf(stderr,
                            "%s: %s(%s) uses unsupported AMD64 relocation "
                            "0x%04x\n",
                            input_name, object->display_name, section->name,
                            section->relocations[k].type);
                    assert(false);
                }
            }
            if (strcmp(section->name, ".drectve") == 0) {
                int status = ld_coff_parse_directives(context, section);
                if (status != LD_OK)
                    fprintf(stderr, "%s: %s directive scan failed\n",
                            input_name, object->display_name);
                assert(status == LD_OK);
            }
        }
    }
}

static bool object_has_section(const ld_coff_object_t *object,
                               const char *name) {
    for (size_t i = 0; i < object->section_count; i++)
        if (strcmp(object->sections[i].name, name) == 0) return true;
    return false;
}

static void check_runtime_aco_unwind(const ld_coff_context_t *context) {
    bool found = false;
    for (size_t i = 0; i < context->object_count; i++) {
        const ld_coff_object_t *object = context->objects[i];
        if (!object->display_name ||
            !strstr(object->display_name, "acosw.S.obj"))
            continue;
        found = true;
        assert(object_has_section(object, ".pdata"));
        assert(object_has_section(object, ".xdata"));
    }
    assert(found);
}

static void check_input(const char *name) {
    char path[4096];
    int length = snprintf(path, sizeof(path), "%s/lib/windows_amd64/%s",
                          NATURE_SOURCE_DIR, name);
    assert(length > 0 && (size_t) length < sizeof(path));

    diagnostic_capture_t capture = {{0}};
    ld_options_t options = {0};
    options.os = LD_OS_WINDOWS;
    options.arch = LD_ARCH_AMD64;
    options.diagnostic = diagnostic;
    options.diagnostic_context = &capture;

    ld_coff_context_t context;
    ld_coff_context_init(&context, &options);
    int status = ld_coff_load_input(&context, path);
    if (status != LD_OK)
        fprintf(stderr, "sysroot input %s failed: %s\n", name,
                capture.message);
    assert(status == LD_OK);
    assert(context.object_count != 0U);
    check_object_capabilities(&context, name);
    if (strcmp(name, "libruntime.a") == 0)
        check_runtime_aco_unwind(&context);
    ld_coff_context_deinit(&context);
}

