static void test_elf_set_binary_mode(int fd) {
#ifdef _WIN32
    assert(_setmode(fd, _O_BINARY) != -1);
#else
    (void) fd;
#endif
}

uint64_t test_elf_add_signed_u32(uint64_t base, uint32_t encoded) {
    if (encoded <= INT32_MAX) return base + encoded;
    uint64_t magnitude = (uint64_t) UINT32_MAX - encoded + 1U;
    assert(magnitude <= base);
    return base - magnitude;
}

void capture_diagnostic(void *context, ld_diag_level_t level, const char *message) {
    (void) level;
    diagnostic_capture_t *capture = context;
    capture->count++;
    snprintf(capture->message, sizeof(capture->message), "%s", message);
}

void write_fixture(char path[], const void *bytes, size_t size) {
    int fd = mkstemp(path);
    assert(fd >= 0);
    test_elf_set_binary_mode(fd);
    assert(write(fd, bytes, size) == (ssize_t) size);
    assert(close(fd) == 0);
}

void test_elf_write_u32(uint8_t *bytes, uint32_t value) {
    bytes[0] = (uint8_t) value;
    bytes[1] = (uint8_t) (value >> 8U);
    bytes[2] = (uint8_t) (value >> 16U);
    bytes[3] = (uint8_t) (value >> 24U);
}

uint32_t test_elf_read_u32(const uint8_t *bytes) {
    return (uint32_t) bytes[0] | ((uint32_t) bytes[1] << 8U) |
           ((uint32_t) bytes[2] << 16U) |
           ((uint32_t) bytes[3] << 24U);
}

const uint8_t *test_elf_find_output_section(const uint8_t *image,
                                            size_t image_size,
                                            const char *name) {
    if (!image || !name || image_size < LD_ELF64_EHDR_SIZE) return NULL;
    uint64_t table_offset = test_elf_read_u64(image + 40U);
    uint16_t entry_size = test_elf_read_u16(image + 58U);
    uint16_t section_count = test_elf_read_u16(image + 60U);
    uint16_t names_index = test_elf_read_u16(image + 62U);
    if (entry_size != LD_ELF64_SHDR_SIZE || names_index >= section_count ||
        table_offset > image_size ||
        (uint64_t) section_count * entry_size > image_size - table_offset) {
        return NULL;
    }
    const uint8_t *table = image + (size_t) table_offset;
    const uint8_t *names_header =
            table + (size_t) names_index * entry_size;
    uint64_t names_offset = test_elf_read_u64(names_header + 24U);
    uint64_t names_size = test_elf_read_u64(names_header + 32U);
    if (names_offset > image_size || names_size > image_size - names_offset)
        return NULL;
    const char *names = (const char *) image + (size_t) names_offset;
    for (uint16_t i = 1U; i < section_count; i++) {
        const uint8_t *section = table + (size_t) i * entry_size;
        uint32_t name_offset = test_elf_read_u32(section);
        if (name_offset >= names_size ||
            !memchr(names + name_offset, '\0',
                    (size_t) names_size - name_offset)) {
            return NULL;
        }
        if (strcmp(names + name_offset, name) == 0) return section;
    }
    return NULL;
}

const uint8_t *test_elf_find_program_header(const uint8_t *image,
                                            size_t image_size,
                                            uint32_t type,
                                            size_t *match_count) {
    if (match_count) *match_count = 0U;
    if (!image || image_size < LD_ELF64_EHDR_SIZE) return NULL;
    uint64_t table_offset = test_elf_read_u64(image + 32U);
    uint16_t entry_size = test_elf_read_u16(image + 54U);
    uint16_t count = test_elf_read_u16(image + 56U);
    if (entry_size != LD_ELF64_PHDR_SIZE || table_offset > image_size ||
        (uint64_t) count * entry_size > image_size - table_offset) {
        return NULL;
    }
    const uint8_t *first = NULL;
    size_t matches = 0U;
    for (uint16_t i = 0U; i < count; i++) {
        const uint8_t *program =
                image + (size_t) table_offset + (size_t) i * entry_size;
        if (test_elf_read_u32(program) != type) continue;
        if (!first) first = program;
        matches++;
    }
    if (match_count) *match_count = matches;
    return first;
}

size_t test_elf_align(size_t value, size_t alignment) {
    assert(alignment != 0U && (alignment & (alignment - 1U)) == 0U);
    assert(value <= SIZE_MAX - (alignment - 1U));
    return (value + alignment - 1U) & ~(alignment - 1U);
}

uint32_t test_elf_append_name(char *table, size_t capacity,
                              size_t *cursor, const char *name) {
    assert(table != NULL && cursor != NULL && name != NULL);
    size_t length = strlen(name) + 1U;
    assert(*cursor <= capacity && length <= capacity - *cursor);
    assert(*cursor <= UINT32_MAX);
    uint32_t result = (uint32_t) *cursor;
    memcpy(table + *cursor, name, length);
    *cursor += length;
    return result;
}

void test_elf_write_section(uint8_t *bytes, uint32_t name,
                            uint32_t type, uint64_t flags,
                            uint64_t offset, uint64_t size,
                            uint32_t link, uint32_t info,
                            uint64_t alignment, uint64_t entry_size) {
    memset(bytes, 0, LD_ELF64_SHDR_SIZE);
    test_elf_write_u32(bytes, name);
    test_elf_write_u32(bytes + 4U, type);
    test_elf_write_u64(bytes + 8U, flags);
    test_elf_write_u64(bytes + 24U, offset);
    test_elf_write_u64(bytes + 32U, size);
    test_elf_write_u32(bytes + 40U, link);
    test_elf_write_u32(bytes + 44U, info);
    test_elf_write_u64(bytes + 48U, alignment);
    test_elf_write_u64(bytes + 56U, entry_size);
}

uint8_t *read_test_fixture(const char *path, size_t *result_size,
                           mode_t *result_mode) {
    int fd = open(path, O_RDONLY | O_BINARY);
    assert(fd >= 0);
    struct stat status;
    assert(fstat(fd, &status) == 0 && status.st_size >= 0);
    size_t size = (size_t) status.st_size;
    uint8_t *bytes = malloc(size ? size : 1U);
    assert(bytes != NULL);
    size_t offset = 0U;
    while (offset < size) {
        ssize_t count = read(fd, bytes + offset, size - offset);
        assert(count > 0);
        offset += (size_t) count;
    }
    assert(close(fd) == 0);
    *result_size = size;
    if (result_mode) *result_mode = status.st_mode;
    return bytes;
}

void test_elf_assert_executable_mode(mode_t mode) {
#ifdef __WINDOWS
    (void) mode;
#else
    assert((mode & 0777U) == 0755U);
#endif
}

uint32_t read_test_elf_entry_word(const char *path) {
    size_t image_size;
    uint8_t *image = read_test_fixture(path, &image_size, NULL);
    assert(image_size >= LD_ELF64_EHDR_SIZE);
    uint64_t entry = test_elf_read_u64(image + 24U);
    uint64_t program_offset = test_elf_read_u64(image + 32U);
    uint16_t program_count = test_elf_read_u16(image + 56U);
    assert(program_offset <= image_size);

    bool found = false;
    uint32_t result = 0U;
    for (uint16_t i = 0; i < program_count; i++) {
        uint64_t header_offset =
                program_offset + (uint64_t) i * LD_ELF64_PHDR_SIZE;
        assert(header_offset <= image_size &&
               LD_ELF64_PHDR_SIZE <= image_size - header_offset);
        const uint8_t *program = image + (size_t) header_offset;
        if (test_elf_read_u32(program) != LD_ELF_PT_LOAD) continue;
        uint64_t file_offset = test_elf_read_u64(program + 8U);
        uint64_t address = test_elf_read_u64(program + 16U);
        uint64_t file_size = test_elf_read_u64(program + 32U);
        if (entry < address || entry - address >= file_size) continue;
        uint64_t entry_offset = file_offset + entry - address;
        assert(entry_offset <= image_size && 4U <= image_size - entry_offset);
        result = test_elf_read_u32(image + (size_t) entry_offset);
        found = true;
        break;
    }
    free(image);
    assert(found);
    return result;
}

bool test_elf_file_contains_u32(const char *path, uint32_t value) {
    size_t size;
    uint8_t *bytes = read_test_fixture(path, &size, NULL);
    bool found = false;
    for (size_t i = 0; i + sizeof(uint32_t) <= size; i++) {
        if (test_elf_read_u32(bytes + i) == value) {
            found = true;
            break;
        }
    }
    free(bytes);
    return found;
}

int link_test_elf_inputs(const char *output_path,
                         const char *const *input_paths,
                         size_t input_count,
                         diagnostic_capture_t *capture) {
    return link_test_elf_inputs_configured(
            output_path, input_paths, input_count, LD_ARCH_ARM64, false,
            LD_DEBUG_NONE, true, capture);
}

int link_test_elf_inputs_configured(
        const char *output_path, const char *const *input_paths,
        size_t input_count, ld_arch_t arch, bool pie,
        ld_debug_mode_t debug_mode, bool remove_existing_output,
        diagnostic_capture_t *capture) {
    if (remove_existing_output) unlink(output_path);
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = arch;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = pie;
    options.debug_mode = debug_mode;
    options.adhoc_codesign = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = capture;
    for (size_t i = 0; i < input_count; i++)
        assert(ld_add_input(&options, input_paths[i]) == LD_OK);
    int status = ld_link(&options);
    ld_options_deinit(&options);
    return status;
}

void test_archive_append(uint8_t *archive, size_t capacity,
                         size_t *cursor, const char *name,
                         const uint8_t *payload, size_t payload_size) {
    size_t padded_size = payload_size + (payload_size & 1U);
    assert(strlen(name) <= LD_ELF_AR_NAME_SIZE);
    assert(*cursor <= capacity &&
           LD_ELF_AR_HEADER_SIZE + padded_size <= capacity - *cursor);
    uint8_t *header = archive + *cursor;
    memset(header, ' ', LD_ELF_AR_HEADER_SIZE);
    memcpy(header, name, strlen(name));
    char decimal[32];
    int decimal_length =
            snprintf(decimal, sizeof(decimal), "%zu", payload_size);
    assert(decimal_length > 0 && decimal_length <= 10);
    memcpy(header + 48U, decimal, (size_t) decimal_length);
    memcpy(header + 58U, "`\n", 2U);
    memcpy(header + LD_ELF_AR_HEADER_SIZE, payload, payload_size);
    if (payload_size & 1U) {
        header[LD_ELF_AR_HEADER_SIZE + payload_size] = '\n';
    }
    *cursor += LD_ELF_AR_HEADER_SIZE + padded_size;
}

uint8_t *make_test_elf_object(uint16_t machine, bool with_sht_rel,
                              bool executable_stack, size_t *result_size) {
    static const char symbol_names[] = "\0_start";
    static const char section_names[] =
            "\0.text\0.symtab\0.strtab\0.shstrtab\0.rel.text"
            "\0.note.GNU-stack";
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t symbol_names_offset = text_offset + sizeof(uint32_t);
    const size_t section_names_offset =
            symbol_names_offset + sizeof(symbol_names);
    const size_t symbols_offset = test_elf_align(
            section_names_offset + sizeof(section_names), 8U);
    const size_t symbol_count = 2U;
    const size_t section_table_offset =
            symbols_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const uint16_t section_count =
            (uint16_t) (5U + (with_sht_rel ? 1U : 0U) +
                        (executable_stack ? 1U : 0U));
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, machine);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, 4U);

    test_elf_write_u32(bytes + text_offset, 0xd65f03c0U);
    memcpy(bytes + symbol_names_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + section_names_offset, section_names,
           sizeof(section_names));

    uint8_t *start_symbol = bytes + symbols_offset + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(start_symbol, 1U);
    start_symbol[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(start_symbol + 6U, 1U);
    test_elf_write_u64(start_symbol + 16U, sizeof(uint32_t));

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(sections + LD_ELF64_SHDR_SIZE, 1U,
                           LD_ELF_SHT_PROGBITS,
                           LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR,
                           text_offset, sizeof(uint32_t), 0U, 0U, 4U, 0U);
    test_elf_write_section(sections + 2U * LD_ELF64_SHDR_SIZE, 7U,
                           LD_ELF_SHT_SYMTAB, 0U, symbols_offset,
                           symbol_count * LD_ELF64_SYM_SIZE, 3U, 1U, 8U,
                           LD_ELF64_SYM_SIZE);
    test_elf_write_section(sections + 3U * LD_ELF64_SHDR_SIZE, 15U,
                           LD_ELF_SHT_STRTAB, 0U, symbol_names_offset,
                           sizeof(symbol_names), 0U, 0U, 1U, 0U);
    test_elf_write_section(sections + 4U * LD_ELF64_SHDR_SIZE, 23U,
                           LD_ELF_SHT_STRTAB, 0U, section_names_offset,
                           sizeof(section_names), 0U, 0U, 1U, 0U);
    if (with_sht_rel) {
        test_elf_write_section(sections + 5U * LD_ELF64_SHDR_SIZE, 33U,
                               LD_ELF_SHT_REL, 0U, section_table_offset, 0U,
                               2U, 1U, 8U, 16U);
    }
    if (executable_stack) {
        size_t note_index = 5U + (with_sht_rel ? 1U : 0U);
        uint32_t note_name =
                (uint32_t) (sizeof(section_names) -
                            sizeof(".note.GNU-stack"));
        test_elf_write_section(
                sections + note_index * LD_ELF64_SHDR_SIZE, note_name,
                LD_ELF_SHT_PROGBITS, LD_ELF_SHF_EXECINSTR, 0U, 0U, 0U, 0U,
                1U, 0U);
    }

    *result_size = size;
    return bytes;
}

uint8_t *make_test_elf_weak_dynamic_object(size_t *result_size) {
    static const char symbol_names[] = "\0_start\0_DYNAMIC";
    static const char section_names[] =
            "\0.text\0.symtab\0.strtab\0.shstrtab\0.rela.text";
    const uint32_t text_name = 1U;
    const uint32_t symtab_name = 7U;
    const uint32_t strtab_name = 15U;
    const uint32_t shstrtab_name = 23U;
    const uint32_t rela_name = 33U;
    const uint32_t start_name = 1U;
    const uint32_t dynamic_name = 8U;
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t symtab_offset = test_elf_align(text_offset + 4U, 8U);
    const size_t strtab_offset =
            symtab_offset + 3U * LD_ELF64_SYM_SIZE;
    const size_t shstrtab_offset = strtab_offset + sizeof(symbol_names);
    const size_t rela_offset =
            test_elf_align(shstrtab_offset + sizeof(section_names), 8U);
    const size_t section_table_offset = rela_offset + LD_ELF64_RELA_SIZE;
    const uint16_t section_count = 6U;
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, LD_ELF_EM_X86_64);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, 4U);

    memcpy(bytes + text_offset, "\0\0\0\0", 4U);
    memcpy(bytes + strtab_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + shstrtab_offset, section_names, sizeof(section_names));

    uint8_t *symbols = bytes + symtab_offset;
    uint8_t *start_symbol = symbols + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(start_symbol, start_name);
    start_symbol[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(start_symbol + 6U, 1U);
    test_elf_write_u64(start_symbol + 16U, 4U);
    uint8_t *dynamic_symbol = start_symbol + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(dynamic_symbol, dynamic_name);
    dynamic_symbol[4] = LD_ELF_SYM_INFO(LD_ELF_STB_WEAK, LD_ELF_STT_OBJECT);
    test_elf_write_u16(dynamic_symbol + 6U, LD_ELF_SHN_UNDEF);

    uint8_t *rela = bytes + rela_offset;
    test_elf_write_u64(rela, 0U);
    test_elf_write_u64(
            rela + 8U,
            LD_ELF_RELA_INFO(2U, LD_ELF_R_X86_64_PC32));
    test_elf_write_u64(rela + 16U, UINT64_MAX - 3U); /* signed addend -4 */

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(sections + LD_ELF64_SHDR_SIZE, text_name,
                           LD_ELF_SHT_PROGBITS,
                           LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR,
                           text_offset, 4U, 0U, 0U, 4U, 0U);
    test_elf_write_section(sections + 2U * LD_ELF64_SHDR_SIZE, symtab_name,
                           LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
                           3U * LD_ELF64_SYM_SIZE, 3U, 1U, 8U,
                           LD_ELF64_SYM_SIZE);
    test_elf_write_section(sections + 3U * LD_ELF64_SHDR_SIZE, strtab_name,
                           LD_ELF_SHT_STRTAB, 0U, strtab_offset,
                           sizeof(symbol_names), 0U, 0U, 1U, 0U);
    test_elf_write_section(sections + 4U * LD_ELF64_SHDR_SIZE, shstrtab_name,
                           LD_ELF_SHT_STRTAB, 0U, shstrtab_offset,
                           sizeof(section_names), 0U, 0U, 1U, 0U);
    test_elf_write_section(sections + 5U * LD_ELF64_SHDR_SIZE, rela_name,
                           LD_ELF_SHT_RELA, 0U, rela_offset,
                           LD_ELF64_RELA_SIZE, 2U, 1U, 8U,
                           LD_ELF64_RELA_SIZE);

    *result_size = size;
    return bytes;
}

static void test_elf_empty_alloc_section_symbols(void) {
    size_t object_size;
    uint8_t *object = make_test_elf_empty_alloc_object(&object_size);
    char object_path[] = "/tmp/nature-ld-empty-alloc-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path = "/tmp/nature-ld-empty-alloc-output";
    diagnostic_capture_t capture = {0};
    const char *inputs[] = {object_path};
    assert(link_test_elf_inputs(output_path, inputs, 1U, &capture) == LD_OK);
    assert(capture.count == 0U);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *text =
            test_elf_find_output_section(image, image_size, ".text");
    const uint8_t *data =
            test_elf_find_output_section(image, image_size, ".data");
    const uint8_t *empty = test_elf_find_output_section(
            image, image_size, ".tm_clone_table");
    assert(text != NULL && data != NULL && empty != NULL);

    uint64_t text_offset = test_elf_read_u64(text + 24U);
    uint64_t empty_address = test_elf_read_u64(empty + 16U);
    assert(test_elf_read_u64(empty + 32U) == 0U);
    assert(test_elf_read_u64(empty + 48U) == 8U);
    assert(test_elf_read_u64(empty + 8U) ==
           (LD_ELF_SHF_ALLOC | LD_ELF_SHF_WRITE));
    assert(text_offset <= image_size &&
           3U * sizeof(uint64_t) <= image_size - text_offset);
    for (size_t i = 0U; i < 3U; i++) {
        assert(test_elf_read_u64(image + (size_t) text_offset +
                                 i * sizeof(uint64_t)) == empty_address);
    }

    uint64_t data_end = test_elf_read_u64(data + 16U) +
                        test_elf_read_u64(data + 32U);
    uint64_t expected_empty_address = (data_end + 7U) & ~7ULL;
    assert(empty_address == expected_empty_address);

    free(image);
    unlink(object_path);
    unlink(output_path);
}

static uint64_t test_ld_elf_debug_read(const uint8_t *bytes, size_t width) {
    uint64_t value = 0U;
    for (size_t i = 0; i < width; i++)
        value |= (uint64_t) bytes[i] << (i * 8U);
    return value;
}

static void test_ld_elf_debug_write(uint8_t *bytes, size_t width,
                                    uint64_t value) {
    for (size_t i = 0; i < width; i++) {
        bytes[i] = (uint8_t) value;
        value >>= 8U;
    }
}

static void test_ld_elf_debug_expect_scalar(
        uint16_t machine, uint32_t type, int64_t addend,
        const ld_elf_debug_reloc_values_t *values, size_t width,
        uint64_t initial, uint64_t expected) {
    uint8_t place[16];
    memset(place, 0xa5, sizeof(place));
    test_ld_elf_debug_write(place, width, initial);
    uint8_t before[16];
    memcpy(before, place, sizeof(before));
    size_t written = SIZE_MAX;
    const ld_elf_debug_relocation_t relocation = {type, addend};
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   machine, &relocation, values, place, sizeof(place),
                   &written) == LD_ELF_DEBUG_RELOC_OK);
    assert(written == width);
    assert(test_ld_elf_debug_read(place, width) == expected);
    assert(memcmp(place + width, before + width, sizeof(place) - width) == 0);
}

static void test_ld_elf_debug_section_classification(void) {
    assert(ld_elf_debug_classify_nonalloc_section(
                   ".debug_info", LD_ELF_SHT_PROGBITS, 0U, true) ==
           LD_ELF_DEBUG_SECTION_DWARF);
    assert(ld_elf_debug_classify_nonalloc_section(
                   ".debug_info", LD_ELF_SHT_PROGBITS, 0U, false) ==
           LD_ELF_DEBUG_SECTION_SKIP);
    assert(ld_elf_debug_classify_nonalloc_section(
                   ".debug_line", LD_ELF_SHT_PROGBITS,
                   LD_ELF_SHF_COMPRESSED, true) ==
           LD_ELF_DEBUG_SECTION_DWARF);
    assert(ld_elf_debug_classify_nonalloc_section(
                   ".comment", LD_ELF_SHT_PROGBITS,
                   LD_ELF_SHF_MERGE | LD_ELF_SHF_STRINGS, false) ==
           LD_ELF_DEBUG_SECTION_COMMENT);
    assert(ld_elf_debug_classify_nonalloc_section(
                   ".gcc_except_table.tooling", LD_ELF_SHT_PROGBITS, 0U,
                   false) == LD_ELF_DEBUG_SECTION_OTHER);

    assert(ld_elf_debug_classify_nonalloc_section(
                   ".debug_info", LD_ELF_SHT_PROGBITS, LD_ELF_SHF_ALLOC,
                   true) == LD_ELF_DEBUG_SECTION_SKIP);
    assert(ld_elf_debug_classify_nonalloc_section(
                   ".debug_info", LD_ELF_SHT_PROGBITS, LD_ELF_SHF_EXCLUDE,
                   true) == LD_ELF_DEBUG_SECTION_SKIP);
    assert(ld_elf_debug_classify_nonalloc_section(
                   ".note.GNU-stack", LD_ELF_SHT_PROGBITS, 0U, true) ==
           LD_ELF_DEBUG_SECTION_SKIP);
    assert(ld_elf_debug_classify_nonalloc_section(
                   ".llvm_addrsig", LD_ELF_SHT_PROGBITS, 0U, true) ==
           LD_ELF_DEBUG_SECTION_SKIP);
    assert(ld_elf_debug_classify_nonalloc_section(
                   ".riscv.attributes", LD_ELF_SHT_PROGBITS, 0U, true) ==
           LD_ELF_DEBUG_SECTION_SKIP);
    assert(ld_elf_debug_classify_nonalloc_section(
                   ".debug_info", LD_ELF_SHT_RELA, 0U, true) ==
           LD_ELF_DEBUG_SECTION_SKIP);
    assert(ld_elf_debug_classify_nonalloc_section(
                   ".debug_info", LD_ELF_SHT_NOBITS, 0U, true) ==
           LD_ELF_DEBUG_SECTION_SKIP);
    assert(ld_elf_debug_classify_nonalloc_section(
                   NULL, LD_ELF_SHT_PROGBITS, 0U, true) ==
           LD_ELF_DEBUG_SECTION_SKIP);
}

static void test_ld_elf_debug_tombstones(void) {
    assert(ld_elf_debug_tombstone(".debug_loc", true) ==
           LD_ELF_DEBUG_TOMBSTONE_ONE);
    assert(ld_elf_debug_tombstone(".debug_ranges", true) ==
           LD_ELF_DEBUG_TOMBSTONE_ONE);
    assert(ld_elf_debug_tombstone(".debug_info", true) ==
           LD_ELF_DEBUG_TOMBSTONE_ZERO);
    assert(ld_elf_debug_tombstone(".debug_loclists", true) ==
           LD_ELF_DEBUG_TOMBSTONE_ZERO);
    assert(ld_elf_debug_tombstone(".debug_loc", false) ==
           LD_ELF_DEBUG_TOMBSTONE_NONE);
    assert(ld_elf_debug_tombstone(".eh_frame", true) ==
           LD_ELF_DEBUG_TOMBSTONE_NONE);
    assert(ld_elf_debug_tombstone(NULL, true) ==
           LD_ELF_DEBUG_TOMBSTONE_NONE);
}

static void test_ld_elf_debug_x86_64_relocations(void) {
    const ld_elf_debug_reloc_values_t values = {
            .symbol_value = 0x60U,
            .symbol_size = 0x50U,
            .got_address = 0x20U,
            .dynamic_thread_pointer = 0x10U,
    };
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_X86_64,
                                    LD_ELF_R_X86_64_8, -0x20, &values, 1U,
                                    0U, 0x40U);
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_X86_64,
                                    LD_ELF_R_X86_64_16, -0x20, &values, 2U,
                                    0U, 0x40U);
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_X86_64,
                                    LD_ELF_R_X86_64_32, -0x20, &values, 4U,
                                    0U, 0x40U);
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_X86_64,
                                    LD_ELF_R_X86_64_32S, -0x20, &values, 4U,
                                    0U, 0x40U);
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_X86_64,
                                    LD_ELF_R_X86_64_64, -0x20, &values, 8U,
                                    0U, 0x40U);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_X86_64, LD_ELF_R_X86_64_DTPOFF32, -0x20, &values, 4U,
            0U, 0x30U);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_X86_64, LD_ELF_R_X86_64_DTPOFF64, -0x20, &values, 8U,
            0U, 0x30U);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_X86_64, LD_ELF_R_X86_64_GOTOFF64, -0x20, &values, 8U,
            0U, 0x20U);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_X86_64, LD_ELF_R_X86_64_GOTPC64, -0x20, &values, 8U,
            0U, 0U);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_X86_64, LD_ELF_R_X86_64_SIZE32, -0x20, &values, 4U,
            0U, 0x30U);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_X86_64, LD_ELF_R_X86_64_SIZE64, -0x20, &values, 8U,
            0U, 0x30U);

    ld_elf_debug_reloc_values_t negative = values;
    negative.symbol_value = 0U;
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_X86_64,
                                    LD_ELF_R_X86_64_16, -1, &negative, 2U,
                                    0U, UINT16_MAX);

    ld_elf_debug_reloc_values_t tombstone = values;
    tombstone.has_tombstone = true;
    tombstone.tombstone_value = 1U;
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_X86_64,
                                    LD_ELF_R_X86_64_64, INT64_MAX,
                                    &tombstone, 8U, 0U, 1U);
    /* This unusual eight-byte DTPOFF32 tombstone matches Zig 738d2be9. */
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_X86_64, LD_ELF_R_X86_64_DTPOFF32, INT64_MAX,
            &tombstone, 8U, 0U, 1U);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_X86_64, LD_ELF_R_X86_64_DTPOFF64, INT64_MAX,
            &tombstone, 8U, 0U, 1U);
}

static void test_ld_elf_debug_aarch64_relocations(void) {
    const ld_elf_debug_reloc_values_t values = {
            .symbol_value = 0x1020U,
    };
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_AARCH64,
                                    LD_ELF_R_AARCH64_ABS32, -0x20, &values,
                                    4U, 0U, 0x1000U);
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_AARCH64,
                                    LD_ELF_R_AARCH64_ABS64, -0x20, &values,
                                    8U, 0U, 0x1000U);

    ld_elf_debug_reloc_values_t tombstone = values;
    tombstone.has_tombstone = true;
    tombstone.tombstone_value = 1U;
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_AARCH64,
                                    LD_ELF_R_AARCH64_ABS64, INT64_MAX,
                                    &tombstone, 8U, 0U, 1U);
}

static void test_ld_elf_debug_riscv_integer_relocations(void) {
    const ld_elf_debug_reloc_values_t values = {
            .symbol_value = 5U,
    };
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_RISCV, LD_ELF_R_RISCV_32, 1,
                                    &values, 4U, 0U, 6U);
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_RISCV, LD_ELF_R_RISCV_64, 1,
                                    &values, 8U, 0U, 6U);

    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_RISCV, LD_ELF_R_RISCV_ADD8, 1, &values, 1U, 125U,
            INT8_MAX);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_RISCV, LD_ELF_R_RISCV_ADD16, 1, &values, 2U,
            INT16_MAX - 2, INT16_MAX);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_RISCV, LD_ELF_R_RISCV_ADD32, 1, &values, 4U,
            INT32_MAX - 2, INT32_MAX);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_RISCV, LD_ELF_R_RISCV_ADD64, 1, &values, 8U,
            (uint64_t) INT64_MAX - 2U, (uint64_t) INT64_MAX);

    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_RISCV, LD_ELF_R_RISCV_SUB8, 1, &values, 1U,
            (uint8_t) (INT8_MIN + 2), (uint8_t) INT8_MIN);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_RISCV, LD_ELF_R_RISCV_SUB16, 1, &values, 2U,
            (uint16_t) (INT16_MIN + 2), (uint16_t) INT16_MIN);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_RISCV, LD_ELF_R_RISCV_SUB32, 1, &values, 4U,
            (uint32_t) (INT32_MIN + 2), (uint32_t) INT32_MIN);
    test_ld_elf_debug_expect_scalar(
            LD_ELF_EM_RISCV, LD_ELF_R_RISCV_SUB64, 1, &values, 8U,
            (uint64_t) INT64_MIN + 2U, (uint64_t) INT64_MIN);

    test_ld_elf_debug_expect_scalar(LD_ELF_EM_RISCV,
                                    LD_ELF_R_RISCV_SET6, 1, &values, 1U,
                                    0xc0U, 0xc6U);
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_RISCV,
                                    LD_ELF_R_RISCV_SUB6, 1, &values, 1U,
                                    0xc8U, 0xc2U);
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_RISCV,
                                    LD_ELF_R_RISCV_SET8, 1, &values, 1U,
                                    0U, 6U);
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_RISCV,
                                    LD_ELF_R_RISCV_SET16, 1, &values, 2U,
                                    0U, 6U);
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_RISCV,
                                    LD_ELF_R_RISCV_SET32, 1, &values, 4U,
                                    0U, 6U);

    ld_elf_debug_reloc_values_t tombstone = values;
    tombstone.has_tombstone = true;
    tombstone.tombstone_value = 1U;
    test_ld_elf_debug_expect_scalar(LD_ELF_EM_RISCV, LD_ELF_R_RISCV_64,
                                    INT64_MAX, &tombstone, 8U, 0U, 1U);
}

static void test_ld_elf_debug_riscv_uleb_pair(void) {
    const ld_elf_debug_relocation_t set = {
            LD_ELF_R_RISCV_SET_ULEB128,
            -0x20,
    };
    const ld_elf_debug_relocation_t sub = {
            LD_ELF_R_RISCV_SUB_ULEB128,
            -0x10,
    };
    const ld_elf_debug_reloc_values_t set_values = {
            .symbol_value = 0x120U,
    };
    const ld_elf_debug_reloc_values_t sub_values = {
            .symbol_value = 0x90U,
    };
    uint8_t field[3] = {0x80U, 0x00U, 0xa5U};
    size_t written = SIZE_MAX;
    assert(ld_elf_debug_apply_riscv_uleb_pair(
                   &set, &set_values, &sub, &sub_values, field,
                   sizeof(field), &written) == LD_ELF_DEBUG_RELOC_OK);
    /* (0x120 - 0x20) - (0x90 - -0x10) == 0x60. */
    assert(written == 2U && field[0] == 0xe0U && field[1] == 0U &&
           field[2] == 0xa5U);

    const ld_elf_debug_relocation_t wrong = {LD_ELF_R_RISCV_64, 0};
    uint8_t unchanged[2] = {0x80U, 0x00U};
    uint8_t before[2];
    memcpy(before, unchanged, sizeof(before));
    written = 12U;
    assert(ld_elf_debug_apply_riscv_uleb_pair(
                   &wrong, &set_values, &sub, &sub_values, unchanged,
                   sizeof(unchanged), &written) ==
           LD_ELF_DEBUG_RELOC_INVALID_PAIR);
    assert(written == 0U && memcmp(unchanged, before, sizeof(before)) == 0);

    uint8_t truncated = 0x80U;
    assert(ld_elf_debug_apply_riscv_uleb_pair(
                   &set, &set_values, &sub, &sub_values, &truncated, 1U,
                   NULL) == LD_ELF_DEBUG_RELOC_TRUNCATED);
    assert(truncated == 0x80U);

    uint8_t malformed[10];
    memset(malformed, 0x80, sizeof(malformed));
    malformed[9] = 0x02U;
    uint8_t malformed_before[10];
    memcpy(malformed_before, malformed, sizeof(malformed));
    assert(ld_elf_debug_apply_riscv_uleb_pair(
                   &set, &set_values, &sub, &sub_values, malformed,
                   sizeof(malformed), NULL) ==
           LD_ELF_DEBUG_RELOC_MALFORMED_ULEB128);
    assert(memcmp(malformed, malformed_before, sizeof(malformed)) == 0);

    const ld_elf_debug_relocation_t large_set = {
            LD_ELF_R_RISCV_SET_ULEB128,
            0,
    };
    const ld_elf_debug_relocation_t zero_sub = {
            LD_ELF_R_RISCV_SUB_ULEB128,
            0,
    };
    const ld_elf_debug_reloc_values_t large_values = {
            .symbol_value = 128U,
    };
    const ld_elf_debug_reloc_values_t zero_values = {0};
    uint8_t narrow = 0x55U;
    assert(ld_elf_debug_apply_riscv_uleb_pair(
                   &large_set, &large_values, &zero_sub, &zero_values,
                   &narrow, 1U, NULL) == LD_ELF_DEBUG_RELOC_OK);
    assert(narrow == 0U);

    const ld_elf_debug_reloc_values_t one_value = {.symbol_value = 1U};
    const ld_elf_debug_reloc_values_t two_value = {.symbol_value = 2U};
    narrow = 0x33U;
    assert(ld_elf_debug_apply_riscv_uleb_pair(
                   &large_set, &one_value, &zero_sub, &two_value, &narrow,
                   1U, NULL) == LD_ELF_DEBUG_RELOC_OK);
    assert(narrow == 0x7fU);
}

static void test_ld_elf_debug_relocation_failures(void) {
    ld_elf_debug_reloc_values_t values = {.symbol_value = 128U};
    const ld_elf_debug_relocation_t overflow = {
            LD_ELF_R_X86_64_8,
            0,
    };
    uint8_t place[8];
    memset(place, 0xa5, sizeof(place));
    uint8_t before[8];
    memcpy(before, place, sizeof(before));
    size_t written = SIZE_MAX;
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   LD_ELF_EM_X86_64, &overflow, &values, place,
                   sizeof(place), &written) == LD_ELF_DEBUG_RELOC_OVERFLOW);
    assert(written == 0U && memcmp(place, before, sizeof(place)) == 0);

    values.symbol_value = (uint64_t) INT16_MAX + 1U;
    const ld_elf_debug_relocation_t x86_16 = {LD_ELF_R_X86_64_16, 0};
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   LD_ELF_EM_X86_64, &x86_16, &values, place,
                   sizeof(place), NULL) == LD_ELF_DEBUG_RELOC_OVERFLOW);
    assert(memcmp(place, before, sizeof(place)) == 0);

    values.symbol_value = (uint64_t) INT32_MAX + 1U;
    const ld_elf_debug_relocation_t aarch64_32 = {
            LD_ELF_R_AARCH64_ABS32,
            0,
    };
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   LD_ELF_EM_AARCH64, &aarch64_32, &values, place,
                   sizeof(place), NULL) == LD_ELF_DEBUG_RELOC_OVERFLOW);
    assert(memcmp(place, before, sizeof(place)) == 0);

    const ld_elf_debug_relocation_t riscv_32 = {LD_ELF_R_RISCV_32, 0};
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   LD_ELF_EM_RISCV, &riscv_32, &values, place,
                   sizeof(place), NULL) == LD_ELF_DEBUG_RELOC_OVERFLOW);
    assert(memcmp(place, before, sizeof(place)) == 0);

    values.symbol_value = 0U;
    values.got_address = 1U;
    const ld_elf_debug_relocation_t gotoff_overflow = {
            LD_ELF_R_X86_64_GOTOFF64,
            INT64_MIN,
    };
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   LD_ELF_EM_X86_64, &gotoff_overflow, &values, place,
                   sizeof(place), NULL) == LD_ELF_DEBUG_RELOC_OVERFLOW);
    assert(memcmp(place, before, sizeof(place)) == 0);

    values.symbol_value = (uint64_t) INT64_MAX + 1U;
    const ld_elf_debug_relocation_t riscv_add = {LD_ELF_R_RISCV_ADD8, 0};
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   LD_ELF_EM_RISCV, &riscv_add, &values, place,
                   sizeof(place), NULL) == LD_ELF_DEBUG_RELOC_OVERFLOW);
    assert(memcmp(place, before, sizeof(place)) == 0);

    const ld_elf_debug_relocation_t wide = {LD_ELF_R_X86_64_64, 0};
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   LD_ELF_EM_X86_64, &wide, &values, place, 7U,
                   &written) == LD_ELF_DEBUG_RELOC_TRUNCATED);
    assert(written == 0U && memcmp(place, before, sizeof(place)) == 0);

    const ld_elf_debug_relocation_t unsupported = {
            LD_ELF_R_X86_64_PC32,
            0,
    };
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   LD_ELF_EM_X86_64, &unsupported, &values, place,
                   sizeof(place), NULL) ==
           LD_ELF_DEBUG_RELOC_UNSUPPORTED_RELOCATION);
    assert(memcmp(place, before, sizeof(place)) == 0);

    const ld_elf_debug_relocation_t standalone = {
            LD_ELF_R_RISCV_SET_ULEB128,
            0,
    };
    uint8_t uleb = 0U;
    written = 0U;
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   LD_ELF_EM_RISCV, &standalone, &values, &uleb,
                   sizeof(uleb), &written) == LD_ELF_DEBUG_RELOC_OK);
    assert(uleb == 0U && written == 1U);

    assert(ld_elf_debug_apply_nonalloc_relocation(
                   0xffffU, &wide, &values, place, sizeof(place), NULL) ==
           LD_ELF_DEBUG_RELOC_UNSUPPORTED_MACHINE);
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   LD_ELF_EM_X86_64, NULL, &values, place, sizeof(place),
                   NULL) == LD_ELF_DEBUG_RELOC_INVALID_ARGUMENT);
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   LD_ELF_EM_X86_64, &wide, NULL, place, sizeof(place),
                   NULL) == LD_ELF_DEBUG_RELOC_INVALID_ARGUMENT);

    const ld_elf_debug_relocation_t none = {LD_ELF_R_X86_64_NONE, 0};
    written = SIZE_MAX;
    assert(ld_elf_debug_apply_nonalloc_relocation(
                   LD_ELF_EM_X86_64, &none, NULL, NULL, 0U, &written) ==
           LD_ELF_DEBUG_RELOC_OK);
    assert(written == 0U);

    for (int result = LD_ELF_DEBUG_RELOC_OK;
         result <= LD_ELF_DEBUG_RELOC_MALFORMED_ULEB128; result++) {
        const char *message = ld_elf_debug_reloc_result_string(
                (ld_elf_debug_reloc_result_t) result);
        assert(message && message[0]);
    }
    assert(strstr(ld_elf_debug_reloc_result_string(
                          (ld_elf_debug_reloc_result_t) 999),
                  "unknown"));
}

void test_ld_elf_debug(void) {
    test_ld_elf_debug_section_classification();
    test_ld_elf_debug_tombstones();
    test_ld_elf_debug_x86_64_relocations();
    test_ld_elf_debug_aarch64_relocations();
    test_ld_elf_debug_riscv_integer_relocations();
    test_ld_elf_debug_riscv_uleb_pair();
    test_ld_elf_debug_relocation_failures();
}

static void test_debug_link_write_header(uint8_t *bytes, uint16_t section_count,
                                         uint16_t section_names_index,
                                         size_t section_table_offset) {
    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, LD_ELF_EM_AARCH64);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, section_names_index);
}

static void test_debug_link_write_start_symbol(uint8_t *symbol,
                                               uint16_t section_index) {
    test_elf_write_u32(symbol, 1U);
    symbol[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(symbol + 6U, section_index);
    test_elf_write_u64(symbol + 16U, sizeof(uint32_t));
}

static void test_debug_link_write_compressed_zeros(uint8_t *bytes) {
    test_elf_write_u32(bytes, LD_ELF_COMPRESS_ZLIB);
    test_elf_write_u32(bytes + 4U, 0U);
    test_elf_write_u64(bytes + 8U, 256U);
    test_elf_write_u64(bytes + 16U, 1U);
    memcpy(bytes + LD_ELF64_CHDR_SIZE,
           test_debug_link_compressed_zeros,
           sizeof(test_debug_link_compressed_zeros));
}

static uint8_t *test_debug_link_make_stripped_relocation_object(
        size_t *result_size) {
    enum {
        text_index = 1,
        debug_index = 2,
        rela_index = 3,
        symtab_index = 4,
        strtab_index = 5,
        shstrtab_index = 6,
        section_count = 7,
        symbol_count = 2,
    };
    static const char symbol_names[] = "\0_start";
    char section_names[128] = {0};
    size_t section_names_size = 1U;
    uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text");
    uint32_t debug_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".debug_info");
    uint32_t rela_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".rela.debug_info");
    uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");

    const size_t compressed_size =
            LD_ELF64_CHDR_SIZE + sizeof(test_debug_link_compressed_zeros);
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t debug_offset = test_elf_align(text_offset + 4U, 8U);
    const size_t rela_offset =
            test_elf_align(debug_offset + compressed_size, 8U);
    const size_t symtab_offset =
            test_elf_align(rela_offset + LD_ELF64_RELA_SIZE, 8U);
    const size_t strtab_offset =
            symtab_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t shstrtab_offset = strtab_offset + sizeof(symbol_names);
    const size_t section_table_offset = test_elf_align(
            shstrtab_offset + section_names_size, 8U);
    const size_t size = section_table_offset +
                        section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    test_debug_link_write_header(bytes, section_count, shstrtab_index,
                                 section_table_offset);
    test_elf_write_u32(bytes + text_offset, UINT32_C(0xd65f03c0));
    test_debug_link_write_compressed_zeros(bytes + debug_offset);
    test_elf_write_u64(bytes + rela_offset, 128U);
    test_elf_write_u64(bytes + rela_offset + 8U,
                       ((uint64_t) 1U << 32U) |
                               LD_ELF_R_AARCH64_ABS64);
    test_elf_write_u64(bytes + rela_offset + 16U, 0U);
    test_debug_link_write_start_symbol(
            bytes + symtab_offset + LD_ELF64_SYM_SIZE, text_index);
    memcpy(bytes + strtab_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + shstrtab_offset, section_names, section_names_size);

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(
            sections + text_index * LD_ELF64_SHDR_SIZE, text_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR, text_offset, 4U, 0U,
            0U, 4U, 0U);
    test_elf_write_section(
            sections + debug_index * LD_ELF64_SHDR_SIZE, debug_name,
            LD_ELF_SHT_PROGBITS, LD_ELF_SHF_COMPRESSED, debug_offset,
            compressed_size, 0U, 0U, 8U, 0U);
    test_elf_write_section(
            sections + rela_index * LD_ELF64_SHDR_SIZE, rela_name,
            LD_ELF_SHT_RELA, 0U, rela_offset, LD_ELF64_RELA_SIZE,
            symtab_index, debug_index, 8U, LD_ELF64_RELA_SIZE);
    test_elf_write_section(
            sections + symtab_index * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
            symbol_count * LD_ELF64_SYM_SIZE, strtab_index, 1U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + strtab_index * LD_ELF64_SHDR_SIZE, strtab_name,
            LD_ELF_SHT_STRTAB, 0U, strtab_offset, sizeof(symbol_names), 0U,
            0U, 1U, 0U);
    test_elf_write_section(
            sections + shstrtab_index * LD_ELF64_SHDR_SIZE, shstrtab_name,
            LD_ELF_SHT_STRTAB, 0U, shstrtab_offset, section_names_size, 0U,
            0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static uint8_t *test_debug_link_make_unnamed_compressed_object(
        size_t *result_size) {
    enum {
        text_index = 1,
        compressed_index = 2,
        symtab_index = 3,
        strtab_index = 4,
        section_count = 5,
        symbol_count = 2,
    };
    static const char symbol_names[] = "\0_start";
    const size_t compressed_size =
            LD_ELF64_CHDR_SIZE + sizeof(test_debug_link_compressed_zeros);
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t compressed_offset = test_elf_align(text_offset + 4U, 8U);
    const size_t symtab_offset =
            test_elf_align(compressed_offset + compressed_size, 8U);
    const size_t strtab_offset =
            symtab_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t section_table_offset =
            test_elf_align(strtab_offset + sizeof(symbol_names), 8U);
    const size_t size = section_table_offset +
                        section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    test_debug_link_write_header(bytes, section_count, LD_ELF_SHN_UNDEF,
                                 section_table_offset);
    test_elf_write_u32(bytes + text_offset, UINT32_C(0xd65f03c0));
    test_debug_link_write_compressed_zeros(bytes + compressed_offset);
    test_debug_link_write_start_symbol(
            bytes + symtab_offset + LD_ELF64_SYM_SIZE, text_index);
    memcpy(bytes + strtab_offset, symbol_names, sizeof(symbol_names));

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(
            sections + text_index * LD_ELF64_SHDR_SIZE, 0U,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR, text_offset, 4U, 0U,
            0U, 4U, 0U);
    test_elf_write_section(
            sections + compressed_index * LD_ELF64_SHDR_SIZE, 0U,
            LD_ELF_SHT_PROGBITS, LD_ELF_SHF_COMPRESSED, compressed_offset,
            compressed_size, 0U, 0U, 8U, 0U);
    test_elf_write_section(
            sections + symtab_index * LD_ELF64_SHDR_SIZE, 0U,
            LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
            symbol_count * LD_ELF64_SYM_SIZE, strtab_index, 1U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + strtab_index * LD_ELF64_SHDR_SIZE, 0U,
            LD_ELF_SHT_STRTAB, 0U, strtab_offset, sizeof(symbol_names), 0U,
            0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static uint8_t *test_debug_link_make_named_section_object(
        const char *section_name, uint32_t section_type,
        uint64_t section_flags, size_t section_alignment, uint32_t fill,
        bool define_start, size_t *result_size) {
    enum {
        text_index = 1,
        named_index = 2,
        symtab_index = 3,
        strtab_index = 4,
        shstrtab_index = 5,
        section_count = 6,
    };
    static const char symbol_names[] = "\0_start";
    char section_names[128] = {0};
    size_t section_names_size = 1U;
    uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text");
    uint32_t named_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            section_name);
    uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");

    const size_t text_size = define_start ? sizeof(uint32_t) : 0U;
    const size_t named_file_size =
            section_type == LD_ELF_SHT_NOBITS ? 0U : sizeof(uint32_t);
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t named_offset = test_elf_align(
            text_offset + text_size, section_alignment);
    const size_t symbol_count = define_start ? 2U : 1U;
    const size_t symtab_offset =
            test_elf_align(named_offset + named_file_size, 8U);
    const size_t strtab_offset =
            symtab_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t shstrtab_offset = strtab_offset + sizeof(symbol_names);
    const size_t section_table_offset = test_elf_align(
            shstrtab_offset + section_names_size, 8U);
    const size_t size = section_table_offset +
                        section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    test_debug_link_write_header(bytes, section_count, shstrtab_index,
                                 section_table_offset);
    if (define_start) {
        test_elf_write_u32(bytes + text_offset, UINT32_C(0xd65f03c0));
        test_debug_link_write_start_symbol(
                bytes + symtab_offset + LD_ELF64_SYM_SIZE, text_index);
    }
    if (named_file_size != 0U)
        test_elf_write_u32(bytes + named_offset, fill);
    memcpy(bytes + strtab_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + shstrtab_offset, section_names, section_names_size);

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(
            sections + text_index * LD_ELF64_SHDR_SIZE, text_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR, text_offset, text_size,
            0U, 0U, 4U, 0U);
    test_elf_write_section(
            sections + named_index * LD_ELF64_SHDR_SIZE, named_name,
            section_type, section_flags, named_offset, sizeof(uint32_t), 0U,
            0U, section_alignment, 0U);
    test_elf_write_section(
            sections + symtab_index * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
            symbol_count * LD_ELF64_SYM_SIZE, strtab_index, 1U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + strtab_index * LD_ELF64_SHDR_SIZE, strtab_name,
            LD_ELF_SHT_STRTAB, 0U, strtab_offset, sizeof(symbol_names), 0U,
            0U, 1U, 0U);
    test_elf_write_section(
            sections + shstrtab_index * LD_ELF64_SHDR_SIZE, shstrtab_name,
            LD_ELF_SHT_STRTAB, 0U, shstrtab_offset, section_names_size, 0U,
            0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static uint8_t *test_debug_link_make_empty_none_relocation_object(
        uint16_t machine, uint32_t none_type, size_t *result_size) {
    enum {
        text_index = 1,
        debug_index = 2,
        rela_index = 3,
        symtab_index = 4,
        strtab_index = 5,
        shstrtab_index = 6,
        section_count = 7,
        symbol_count = 2,
    };
    static const char symbol_names[] = "\0_start";
    char section_names[128] = {0};
    size_t section_names_size = 1U;
    uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text");
    uint32_t debug_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".debug_info");
    uint32_t rela_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".rela.debug_info");
    uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");

    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t debug_offset = text_offset + sizeof(uint32_t);
    const size_t rela_offset = test_elf_align(debug_offset, 8U);
    const size_t symtab_offset = rela_offset + LD_ELF64_RELA_SIZE;
    const size_t strtab_offset =
            symtab_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t shstrtab_offset = strtab_offset + sizeof(symbol_names);
    const size_t section_table_offset = test_elf_align(
            shstrtab_offset + section_names_size, 8U);
    const size_t size = section_table_offset +
                        section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    test_debug_link_write_header(bytes, section_count, shstrtab_index,
                                 section_table_offset);
    test_elf_write_u16(bytes + 18U, machine);
    test_debug_link_write_start_symbol(
            bytes + symtab_offset + LD_ELF64_SYM_SIZE, text_index);
    test_elf_write_u64(bytes + rela_offset, 0U);
    test_elf_write_u64(bytes + rela_offset + 8U, none_type);
    test_elf_write_u64(bytes + rela_offset + 16U, UINT64_MAX);
    memcpy(bytes + strtab_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + shstrtab_offset, section_names, section_names_size);

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(
            sections + text_index * LD_ELF64_SHDR_SIZE, text_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR, text_offset,
            sizeof(uint32_t), 0U, 0U, 4U, 0U);
    test_elf_write_section(
            sections + debug_index * LD_ELF64_SHDR_SIZE, debug_name,
            LD_ELF_SHT_PROGBITS, 0U, debug_offset, 0U, 0U, 0U, 1U, 0U);
    test_elf_write_section(
            sections + rela_index * LD_ELF64_SHDR_SIZE, rela_name,
            LD_ELF_SHT_RELA, 0U, rela_offset, LD_ELF64_RELA_SIZE,
            symtab_index, debug_index, 8U, LD_ELF64_RELA_SIZE);
    test_elf_write_section(
            sections + symtab_index * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
            symbol_count * LD_ELF64_SYM_SIZE, strtab_index, 1U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + strtab_index * LD_ELF64_SHDR_SIZE, strtab_name,
            LD_ELF_SHT_STRTAB, 0U, strtab_offset, sizeof(symbol_names), 0U,
            0U, 1U, 0U);
    test_elf_write_section(
            sections + shstrtab_index * LD_ELF64_SHDR_SIZE, shstrtab_name,
            LD_ELF_SHT_STRTAB, 0U, shstrtab_offset, section_names_size, 0U,
            0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static size_t test_debug_link_find_output_sections(
        const uint8_t *image, size_t image_size, const char *name,
        test_debug_link_output_section_t *results, size_t capacity) {
    assert(image_size >= LD_ELF64_EHDR_SIZE);
    uint64_t table_offset = test_elf_read_u64(image + 40U);
    uint16_t entry_size = test_elf_read_u16(image + 58U);
    uint16_t section_count = test_elf_read_u16(image + 60U);
    uint16_t names_index = test_elf_read_u16(image + 62U);
    assert(entry_size == LD_ELF64_SHDR_SIZE);
    assert(names_index < section_count);
    assert(table_offset <= image_size);
    assert((uint64_t) section_count * entry_size <=
           image_size - table_offset);
    const uint8_t *table = image + (size_t) table_offset;
    const uint8_t *names_header =
            table + (size_t) names_index * entry_size;
    uint64_t names_offset = test_elf_read_u64(names_header + 24U);
    uint64_t names_size = test_elf_read_u64(names_header + 32U);
    assert(names_offset <= image_size &&
           names_size <= image_size - names_offset);
    const char *names = (const char *) image + (size_t) names_offset;

    size_t count = 0U;
    for (uint16_t i = 1U; i < section_count; i++) {
        const uint8_t *section = table + (size_t) i * entry_size;
        uint32_t name_offset = test_elf_read_u32(section);
        assert(name_offset < names_size);
        assert(memchr(names + name_offset, '\0',
                      (size_t) names_size - name_offset) != NULL);
        if (strcmp(names + name_offset, name) != 0) continue;
        assert(count < capacity);
        results[count].header = section;
        results[count].type = test_elf_read_u32(section + 4U);
        results[count].flags = test_elf_read_u64(section + 8U);
        results[count].address = test_elf_read_u64(section + 16U);
        results[count].offset = test_elf_read_u64(section + 24U);
        results[count].size = test_elf_read_u64(section + 32U);
        results[count].alignment = test_elf_read_u64(section + 48U);
        count++;
    }
    return count;
}

static uint64_t test_debug_link_loaded_file_end(
        const uint8_t *image, size_t image_size) {
    uint64_t program_offset = test_elf_read_u64(image + 32U);
    uint16_t entry_size = test_elf_read_u16(image + 54U);
    uint16_t program_count = test_elf_read_u16(image + 56U);
    assert(entry_size == LD_ELF64_PHDR_SIZE);
    assert(program_offset <= image_size);
    assert((uint64_t) program_count * entry_size <=
           image_size - program_offset);
    uint64_t result = 0U;
    for (uint16_t i = 0U; i < program_count; i++) {
        const uint8_t *program = image + (size_t) program_offset +
                                 (size_t) i * entry_size;
        if (test_elf_read_u32(program) != LD_ELF_PT_LOAD) continue;
        uint64_t offset = test_elf_read_u64(program + 8U);
        uint64_t size = test_elf_read_u64(program + 32U);
        assert(offset <= UINT64_MAX - size);
        uint64_t end = offset + size;
        if (end > result) result = end;
    }
    return result;
}

static bool test_debug_link_intersects_load_segment(
        const uint8_t *image, size_t image_size,
        const test_debug_link_output_section_t *section) {
    uint64_t program_offset = test_elf_read_u64(image + 32U);
    uint16_t entry_size = test_elf_read_u16(image + 54U);
    uint16_t program_count = test_elf_read_u16(image + 56U);
    assert(entry_size == LD_ELF64_PHDR_SIZE);
    assert(program_offset <= image_size);
    assert((uint64_t) program_count * entry_size <=
           image_size - program_offset);
    uint64_t section_end = section->offset + section->size;
    assert(section_end >= section->offset);
    for (uint16_t i = 0U; i < program_count; i++) {
        const uint8_t *program = image + (size_t) program_offset +
                                 (size_t) i * entry_size;
        if (test_elf_read_u32(program) != LD_ELF_PT_LOAD) continue;
        uint64_t load_offset = test_elf_read_u64(program + 8U);
        uint64_t load_size = test_elf_read_u64(program + 32U);
        uint64_t load_end = load_offset + load_size;
        assert(load_end >= load_offset);
        if (section->offset < load_end && load_offset < section_end)
            return true;
    }
    return false;
}

static void test_debug_link_default_strip_skips_relocations(void) {
    size_t object_size;
    uint8_t *object =
            test_debug_link_make_stripped_relocation_object(&object_size);
    char object_path[] = "/tmp/nature-ld-debug-strip-reloc-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path =
            "/tmp/nature-ld-debug-strip-reloc-output";
    const char *inputs[] = {object_path};
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_inputs(output_path, inputs, 1U, &capture) == LD_OK);
    assert(capture.count == 0U);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    assert(test_elf_find_output_section(image, image_size, ".debug_info") ==
           NULL);
    free(image);
    unlink(object_path);
    unlink(output_path);
}

static void test_debug_link_dwarf_decompresses_and_lays_out(void) {
    size_t object_size;
    uint8_t *object =
            test_debug_link_make_stripped_relocation_object(&object_size);
    char object_path[] = "/tmp/nature-ld-debug-dwarf-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path =
            "/tmp/nature-ld-debug-dwarf-output";
    const char *inputs[] = {object_path};
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_inputs_configured(
                   output_path, inputs, 1U, LD_ARCH_ARM64, false,
                   LD_DEBUG_DWARF, true, &capture) == LD_OK);
    assert(capture.count == 0U);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    test_debug_link_output_section_t debug;
    test_debug_link_output_section_t symtab;
    assert(test_debug_link_find_output_sections(
                   image, image_size, ".debug_info", &debug, 1U) == 1U);
    assert(test_debug_link_find_output_sections(
                   image, image_size, ".symtab", &symtab, 1U) == 1U);
    assert(debug.type == LD_ELF_SHT_PROGBITS);
    assert((debug.flags &
            (LD_ELF_SHF_ALLOC | LD_ELF_SHF_COMPRESSED)) == 0U);
    assert(debug.address == 0U && debug.size == 256U &&
           debug.alignment == 1U);
    assert(debug.offset >= test_debug_link_loaded_file_end(image,
                                                           image_size));
    assert(debug.offset <= UINT64_MAX - debug.size);
    assert(debug.offset + debug.size <= symtab.offset);
    assert(!test_debug_link_intersects_load_segment(image, image_size,
                                                    &debug));
    assert(debug.offset <= image_size &&
           debug.size <= image_size - debug.offset);
    assert(test_elf_read_u64(image + (size_t) debug.offset + 128U) ==
           test_elf_read_u64(image + 24U));

    free(image);
    unlink(object_path);
    unlink(output_path);
}

static void test_debug_link_merges_same_name_with_max_alignment(void) {
    size_t first_size, second_size;
    uint8_t *first = test_debug_link_make_named_section_object(
            ".debug_info", LD_ELF_SHT_PROGBITS, 0U, 1U,
            UINT32_C(0x44332211), true, &first_size);
    uint8_t *second = test_debug_link_make_named_section_object(
            ".debug_info", LD_ELF_SHT_PROGBITS, 0U, 16U,
            UINT32_C(0x88776655), false, &second_size);
    char first_path[] = "/tmp/nature-ld-debug-align-first-XXXXXX";
    char second_path[] = "/tmp/nature-ld-debug-align-second-XXXXXX";
    write_fixture(first_path, first, first_size);
    write_fixture(second_path, second, second_size);
    free(first);
    free(second);

    static const char *output_path = "/tmp/nature-ld-debug-align-output";
    const char *inputs[] = {first_path, second_path};
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_inputs_configured(
                   output_path, inputs, 2U, LD_ARCH_ARM64, false,
                   LD_DEBUG_DWARF, true, &capture) == LD_OK);
    assert(capture.count == 0U);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    test_debug_link_output_section_t debug[2];
    assert(test_debug_link_find_output_sections(
                   image, image_size, ".debug_info", debug, 2U) == 1U);
    assert(debug[0].type == LD_ELF_SHT_PROGBITS);
    assert((debug[0].flags & LD_ELF_SHF_ALLOC) == 0U);
    assert(debug[0].address == 0U);
    assert(debug[0].alignment == 16U);
    assert(debug[0].size == 20U);
    assert(debug[0].offset >= test_debug_link_loaded_file_end(
                                      image, image_size));
    assert(!test_debug_link_intersects_load_segment(
            image, image_size, &debug[0]));
    assert(debug[0].offset <= image_size &&
           debug[0].size <= image_size - debug[0].offset);

    const uint8_t *contents = image + (size_t) debug[0].offset;
    assert(test_elf_read_u32(contents) == UINT32_C(0x44332211));
    for (size_t i = sizeof(uint32_t); i < 16U; i++)
        assert(contents[i] == 0U);
    assert(test_elf_read_u32(contents + 16U) == UINT32_C(0x88776655));

    free(image);
    unlink(first_path);
    unlink(second_path);
    unlink(output_path);
}

static void test_debug_link_none_relocation_on_empty_section(void) {
    static const uint8_t sentinel[] = {
            0x4eU,
            0x4fU,
            0x4eU,
            0x45U,
    };
    static const struct {
        ld_arch_t arch;
        uint16_t machine;
        uint32_t none_type;
    } cases[] = {
            {LD_ARCH_AMD64, LD_ELF_EM_X86_64,
             LD_ELF_R_X86_64_NONE},
            {LD_ARCH_ARM64, LD_ELF_EM_AARCH64,
             LD_ELF_R_AARCH64_NONE},
            {LD_ARCH_RISCV64, LD_ELF_EM_RISCV,
             LD_ELF_R_RISCV_NONE},
    };

    for (size_t i = 0U; i < sizeof(cases) / sizeof(cases[0]); i++) {
        size_t object_size;
        uint8_t *object =
                test_debug_link_make_empty_none_relocation_object(
                        cases[i].machine, cases[i].none_type,
                        &object_size);
        char object_path[] = "/tmp/nature-ld-debug-none-XXXXXX";
        char output_path[] = "/tmp/nature-ld-debug-none-out-XXXXXX";
        write_fixture(object_path, object, object_size);
        write_fixture(output_path, sentinel, sizeof(sentinel));
        free(object);

        const char *inputs[] = {object_path};
        diagnostic_capture_t capture = {0};
        assert(link_test_elf_inputs_configured(
                       output_path, inputs, 1U, cases[i].arch, false,
                       LD_DEBUG_DWARF, false, &capture) == LD_OK);
        assert(capture.count == 0U);

        size_t image_size;
        mode_t image_mode;
        uint8_t *image = read_test_fixture(
                output_path, &image_size, &image_mode);
        assert(image_size >= LD_ELF64_EHDR_SIZE);
        assert(image[0] == LD_ELF_MAGIC_0 &&
               image[1] == LD_ELF_MAGIC_1 &&
               image[2] == LD_ELF_MAGIC_2 &&
               image[3] == LD_ELF_MAGIC_3);
        assert(test_elf_read_u16(image + 16U) == LD_ELF_ET_EXEC);
        assert(test_elf_read_u16(image + 18U) == cases[i].machine);
        test_elf_assert_executable_mode(image_mode);
        assert(image_size != sizeof(sentinel) ||
               memcmp(image, sentinel, sizeof(sentinel)) != 0);

        test_debug_link_output_section_t debug;
        assert(test_debug_link_find_output_sections(
                       image, image_size, ".debug_info", &debug, 1U) ==
               1U);
        assert(debug.type == LD_ELF_SHT_PROGBITS);
        assert((debug.flags & LD_ELF_SHF_ALLOC) == 0U);
        assert(debug.address == 0U && debug.size == 0U);
        assert(debug.offset <= image_size);

        free(image);
        unlink(object_path);
        unlink(output_path);
    }
}

static void test_debug_link_invalid_chdr_is_atomic(void) {
    static const uint8_t sentinel[] = {
            0x44U,
            0x57U,
            0x41U,
            0x52U,
            0x46U,
            0xa5U,
    };
    static const struct {
        int expected;
        const char *message;
    } cases[] = {
            {LD_UNSUPPORTED, "compression type 2"},
            {LD_INVALID_INPUT, "invalid ch_addralign 3"},
            {LD_INVALID_INPUT, "invalid ch_addralign 0"},
            {LD_INVALID_INPUT, "truncated Elf64_Chdr"},
            {LD_INVALID_INPUT, "non-zero ch_reserved"},
    };
    for (unsigned case_index = 0U;
         case_index < sizeof(cases) / sizeof(cases[0]); case_index++) {
        size_t object_size;
        uint8_t *object = test_debug_link_make_stripped_relocation_object(
                &object_size);
        uint64_t section_table_offset = test_elf_read_u64(object + 40U);
        uint8_t *debug_header =
                object + (size_t) section_table_offset +
                2U * LD_ELF64_SHDR_SIZE;
        uint64_t debug_offset = test_elf_read_u64(debug_header + 24U);
        assert(debug_offset <= object_size &&
               LD_ELF64_CHDR_SIZE <= object_size - debug_offset);
        if (case_index == 0U)
            test_elf_write_u32(object + (size_t) debug_offset, 2U);
        else if (case_index == 1U)
            test_elf_write_u64(object + (size_t) debug_offset + 16U, 3U);
        else if (case_index == 2U)
            test_elf_write_u64(object + (size_t) debug_offset + 16U, 0U);
        else if (case_index == 3U)
            test_elf_write_u64(debug_header + 32U,
                               LD_ELF64_CHDR_SIZE - 1U);
        else
            test_elf_write_u32(object + (size_t) debug_offset + 4U, 1U);

        char object_path[] = "/tmp/nature-ld-debug-chdr-XXXXXX";
        char output_path[] = "/tmp/nature-ld-debug-chdr-out-XXXXXX";
        write_fixture(object_path, object, object_size);
        write_fixture(output_path, sentinel, sizeof(sentinel));
        free(object);

        const char *inputs[] = {object_path};
        diagnostic_capture_t capture = {0};
        assert(link_test_elf_inputs_configured(
                       output_path, inputs, 1U, LD_ARCH_ARM64, false,
                       LD_DEBUG_DWARF, false, &capture) ==
               cases[case_index].expected);
        assert(capture.count > 0U);
        assert(strstr(capture.message, cases[case_index].message) != NULL);
        size_t output_size;
        uint8_t *output =
                read_test_fixture(output_path, &output_size, NULL);
        assert(output_size == sizeof(sentinel));
        assert(memcmp(output, sentinel, sizeof(sentinel)) == 0);
        free(output);
        unlink(object_path);
        unlink(output_path);
    }
}

static void test_debug_link_skips_filtered_compressed_sections(void) {
    static const uint8_t sentinel[] = {
            0x53U,
            0x4bU,
            0x49U,
            0x50U,
    };
    for (unsigned case_index = 0U; case_index < 2U; case_index++) {
        size_t object_size;
        uint8_t *object = test_debug_link_make_stripped_relocation_object(
                &object_size);
        uint64_t section_table_offset = test_elf_read_u64(object + 40U);
        uint16_t section_names_index = test_elf_read_u16(object + 62U);
        assert(section_table_offset <= object_size);

        uint8_t *debug_header =
                object + (size_t) section_table_offset +
                2U * LD_ELF64_SHDR_SIZE;
        uint64_t debug_offset = test_elf_read_u64(debug_header + 24U);
        assert(debug_offset <= object_size &&
               LD_ELF64_CHDR_SIZE <= object_size - debug_offset);
        test_elf_write_u32(object + (size_t) debug_offset, 2U);

        if (case_index == 0U) {
            uint64_t flags = test_elf_read_u64(debug_header + 8U);
            test_elf_write_u64(debug_header + 8U,
                               flags | LD_ELF_SHF_EXCLUDE);
        } else {
            const uint8_t *section_names_header =
                    object + (size_t) section_table_offset +
                    (size_t) section_names_index * LD_ELF64_SHDR_SIZE;
            uint64_t section_names_offset =
                    test_elf_read_u64(section_names_header + 24U);
            uint32_t debug_name_offset = test_elf_read_u32(debug_header);
            assert(section_names_offset <= object_size &&
                   debug_name_offset <=
                           object_size - (size_t) section_names_offset);
            char *debug_name =
                    (char *) object + (size_t) section_names_offset +
                    debug_name_offset;
            assert(strcmp(debug_name, ".debug_info") == 0);
            memcpy(debug_name, ".note.skip", sizeof(".note.skip"));
        }

        char object_path[] = "/tmp/nature-ld-debug-skip-XXXXXX";
        char output_path[] = "/tmp/nature-ld-debug-skip-out-XXXXXX";
        write_fixture(object_path, object, object_size);
        write_fixture(output_path, sentinel, sizeof(sentinel));
        free(object);

        const char *inputs[] = {object_path};
        diagnostic_capture_t capture = {0};
        assert(link_test_elf_inputs_configured(
                       output_path, inputs, 1U, LD_ARCH_ARM64, false,
                       LD_DEBUG_DWARF, false, &capture) == LD_OK);
        assert(capture.count == 0U);

        size_t output_size;
        uint8_t *output =
                read_test_fixture(output_path, &output_size, NULL);
        assert(output_size >= LD_ELF64_EHDR_SIZE);
        assert(output[0] == LD_ELF_MAGIC_0 &&
               output[1] == LD_ELF_MAGIC_1 &&
               output[2] == LD_ELF_MAGIC_2 &&
               output[3] == LD_ELF_MAGIC_3);
        assert(test_elf_find_output_section(
                       output, output_size,
                       case_index == 0U ? ".debug_info" : ".note.skip") ==
               NULL);
        free(output);
        unlink(object_path);
        unlink(output_path);
    }
}

static void test_debug_link_unnamed_compressed_section_is_rejected(void) {
    size_t object_size;
    uint8_t *object =
            test_debug_link_make_unnamed_compressed_object(&object_size);
    char object_path[] = "/tmp/nature-ld-debug-unnamed-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path =
            "/tmp/nature-ld-debug-unnamed-output";
    unlink(output_path);
    const char *inputs[] = {object_path};
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_inputs(output_path, inputs, 1U, &capture) ==
           LD_UNSUPPORTED);
    assert(capture.count != 0U);
    assert(strstr(capture.message, "unsupported compressed ELF section") !=
           NULL);
    errno = 0;
    assert(access(output_path, F_OK) != 0 && errno == ENOENT);

    unlink(object_path);
}

static void test_debug_link_output_section_keys_do_not_collide(void) {
    size_t alloc_size, nonalloc_size, progbits_size, nobits_size;
    uint8_t *alloc = test_debug_link_make_named_section_object(
            ".collision", LD_ELF_SHT_PROGBITS, LD_ELF_SHF_ALLOC, 4U,
            UINT32_C(0x11111111), true, &alloc_size);
    uint8_t *nonalloc = test_debug_link_make_named_section_object(
            ".collision", LD_ELF_SHT_PROGBITS, 0U, 4U,
            UINT32_C(0x22222222), false, &nonalloc_size);
    uint8_t *progbits = test_debug_link_make_named_section_object(
            ".typed", LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_WRITE, 4U,
            UINT32_C(0x33333333), false, &progbits_size);
    uint8_t *nobits = test_debug_link_make_named_section_object(
            ".typed", LD_ELF_SHT_NOBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_WRITE, 4U, 0U, false,
            &nobits_size);

    char alloc_path[] = "/tmp/nature-ld-debug-key-alloc-XXXXXX";
    char nonalloc_path[] = "/tmp/nature-ld-debug-key-nonalloc-XXXXXX";
    char progbits_path[] = "/tmp/nature-ld-debug-key-progbits-XXXXXX";
    char nobits_path[] = "/tmp/nature-ld-debug-key-nobits-XXXXXX";
    write_fixture(alloc_path, alloc, alloc_size);
    write_fixture(nonalloc_path, nonalloc, nonalloc_size);
    write_fixture(progbits_path, progbits, progbits_size);
    write_fixture(nobits_path, nobits, nobits_size);
    free(alloc);
    free(nonalloc);
    free(progbits);
    free(nobits);

    static const char *output_path = "/tmp/nature-ld-debug-key-output";
    const char *inputs[] = {
            alloc_path,
            nonalloc_path,
            progbits_path,
            nobits_path,
    };
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_inputs(output_path, inputs, 4U, &capture) == LD_OK);
    assert(capture.count == 0U);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    test_debug_link_output_section_t collision[2];
    assert(test_debug_link_find_output_sections(
                   image, image_size, ".collision", collision, 2U) == 2U);
    const test_debug_link_output_section_t *allocated = NULL;
    const test_debug_link_output_section_t *nonallocated = NULL;
    for (size_t i = 0U; i < 2U; i++) {
        assert(collision[i].type == LD_ELF_SHT_PROGBITS);
        if ((collision[i].flags & LD_ELF_SHF_ALLOC) != 0U)
            allocated = &collision[i];
        else
            nonallocated = &collision[i];
    }
    assert(allocated != NULL && nonallocated != NULL);
    assert(allocated->address != 0U);
    assert(nonallocated->address == 0U);
    assert(!test_debug_link_intersects_load_segment(
            image, image_size, nonallocated));

    test_debug_link_output_section_t typed[2];
    assert(test_debug_link_find_output_sections(
                   image, image_size, ".typed", typed, 2U) == 2U);
    bool found_progbits = false;
    bool found_nobits = false;
    for (size_t i = 0U; i < 2U; i++) {
        assert((typed[i].flags &
                (LD_ELF_SHF_ALLOC | LD_ELF_SHF_WRITE)) ==
               (LD_ELF_SHF_ALLOC | LD_ELF_SHF_WRITE));
        found_progbits |= typed[i].type == LD_ELF_SHT_PROGBITS;
        found_nobits |= typed[i].type == LD_ELF_SHT_NOBITS;
    }
    assert(found_progbits && found_nobits);

    free(image);
    unlink(alloc_path);
    unlink(nonalloc_path);
    unlink(progbits_path);
    unlink(nobits_path);
    unlink(output_path);
}

void test_ld_elf_debug_link(void) {
    test_debug_link_default_strip_skips_relocations();
    test_debug_link_dwarf_decompresses_and_lays_out();
    test_debug_link_merges_same_name_with_max_alignment();
    test_debug_link_none_relocation_on_empty_section();
    test_debug_link_invalid_chdr_is_atomic();
    test_debug_link_skips_filtered_compressed_sections();
    test_debug_link_unnamed_compressed_section_is_rejected();
    test_debug_link_output_section_keys_do_not_collide();
}

static void debug_merge_write_header(uint8_t *bytes, uint16_t machine,
                                     uint16_t section_count,
                                     uint16_t names_index,
                                     size_t section_table_offset) {
    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, machine);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, names_index);
}

static void debug_merge_write_symbol(uint8_t *symbol, uint32_t name,
                                     uint8_t binding, uint8_t type,
                                     uint16_t section, uint64_t value,
                                     uint64_t size) {
    test_elf_write_u32(symbol, name);
    symbol[4] = LD_ELF_SYM_INFO(binding, type);
    test_elf_write_u16(symbol + 6U, section);
    test_elf_write_u64(symbol + 8U, value);
    test_elf_write_u64(symbol + 16U, size);
}

static uint8_t *debug_merge_make_x86_object(size_t *result_size) {
    enum {
        text_index = 1,
        debug_index = 2,
        merge_index = 3,
        rela_index = 4,
        symtab_index = 5,
        strtab_index = 6,
        shstrtab_index = 7,
        section_count = 8,
        symbol_count = 4,
        relocation_count = 4,
    };
    char symbol_names[64] = {0};
    size_t symbol_names_size = 1U;
    uint32_t start_name = test_elf_append_name(
            symbol_names, sizeof(symbol_names), &symbol_names_size,
            "_start");
    uint32_t resolver_name = test_elf_append_name(
            symbol_names, sizeof(symbol_names), &symbol_names_size,
            "resolver");

    char section_names[160] = {0};
    size_t section_names_size = 1U;
    uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text");
    uint32_t debug_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".debug_info");
    uint32_t merge_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".debug_str");
    uint32_t rela_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".rela.debug_info");
    uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");

    static const uint8_t text[] = {0xc3U, 0xc3U};
    static const char merge[] = "abcdefghijklmnopqrstuvwxyz";
    const size_t debug_size = 32U;
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t debug_offset = test_elf_align(
            text_offset + sizeof(text), 8U);
    const size_t merge_offset = debug_offset + debug_size;
    const size_t rela_offset = test_elf_align(
            merge_offset + sizeof(merge), 8U);
    const size_t symtab_offset = test_elf_align(
            rela_offset + relocation_count * LD_ELF64_RELA_SIZE, 8U);
    const size_t strtab_offset =
            symtab_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t shstrtab_offset = strtab_offset + symbol_names_size;
    const size_t section_table_offset = test_elf_align(
            shstrtab_offset + section_names_size, 8U);
    const size_t size = section_table_offset +
                        section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1U, size);
    assert(bytes != NULL);

    debug_merge_write_header(bytes, LD_ELF_EM_X86_64, section_count,
                             shstrtab_index, section_table_offset);
    memcpy(bytes + text_offset, text, sizeof(text));
    memcpy(bytes + merge_offset, merge, sizeof(merge));
    memcpy(bytes + strtab_offset, symbol_names, symbol_names_size);
    memcpy(bytes + shstrtab_offset, section_names, section_names_size);

    uint8_t *symbols = bytes + symtab_offset;
    debug_merge_write_symbol(symbols + LD_ELF64_SYM_SIZE, 0U,
                             LD_ELF_STB_LOCAL, LD_ELF_STT_SECTION,
                             merge_index, 0U, 0U);
    debug_merge_write_symbol(symbols + 2U * LD_ELF64_SYM_SIZE,
                             start_name, LD_ELF_STB_GLOBAL,
                             LD_ELF_STT_FUNC, text_index, 0U, 1U);
    debug_merge_write_symbol(symbols + 3U * LD_ELF64_SYM_SIZE,
                             resolver_name, LD_ELF_STB_GLOBAL,
                             LD_ELF_STT_GNU_IFUNC, text_index, 1U, 1U);

    static const uint64_t offsets[relocation_count] = {0U, 8U, 12U, 24U};
    static const uint32_t symbols_index[relocation_count] = {1U, 1U, 1U,
                                                             3U};
    static const uint32_t types[relocation_count] = {
            LD_ELF_R_X86_64_GOTPC64,
            LD_ELF_R_X86_64_SIZE32,
            LD_ELF_R_X86_64_SIZE64,
            LD_ELF_R_X86_64_64,
    };
    static const int64_t addends[relocation_count] = {7, 11, 13, 0};
    for (size_t i = 0U; i < relocation_count; i++) {
        uint8_t *relocation = bytes + rela_offset +
                              i * LD_ELF64_RELA_SIZE;
        test_elf_write_u64(relocation, offsets[i]);
        test_elf_write_u64(
                relocation + 8U,
                LD_ELF_RELA_INFO(symbols_index[i], types[i]));
        test_elf_write_u64(relocation + 16U, (uint64_t) addends[i]);
    }

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(
            sections + text_index * LD_ELF64_SHDR_SIZE, text_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR, text_offset,
            sizeof(text), 0U, 0U, 1U, 0U);
    test_elf_write_section(
            sections + debug_index * LD_ELF64_SHDR_SIZE, debug_name,
            LD_ELF_SHT_PROGBITS, 0U, debug_offset, debug_size, 0U, 0U, 8U,
            0U);
    test_elf_write_section(
            sections + merge_index * LD_ELF64_SHDR_SIZE, merge_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_MERGE | LD_ELF_SHF_STRINGS, merge_offset,
            sizeof(merge), 0U, 0U, 1U, 1U);
    test_elf_write_section(
            sections + rela_index * LD_ELF64_SHDR_SIZE, rela_name,
            LD_ELF_SHT_RELA, 0U, rela_offset,
            relocation_count * LD_ELF64_RELA_SIZE, symtab_index,
            debug_index, 8U, LD_ELF64_RELA_SIZE);
    test_elf_write_section(
            sections + symtab_index * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
            symbol_count * LD_ELF64_SYM_SIZE, strtab_index, 2U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + strtab_index * LD_ELF64_SHDR_SIZE, strtab_name,
            LD_ELF_SHT_STRTAB, 0U, strtab_offset, symbol_names_size, 0U, 0U,
            1U, 0U);
    test_elf_write_section(
            sections + shstrtab_index * LD_ELF64_SHDR_SIZE, shstrtab_name,
            LD_ELF_SHT_STRTAB, 0U, shstrtab_offset, section_names_size, 0U,
            0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static uint64_t debug_merge_output_symbol_value(
        const uint8_t *image, size_t image_size, const char *name) {
    const uint8_t *symtab = test_elf_find_output_section(
            image, image_size, ".symtab");
    assert(symtab != NULL);
    uint64_t table_offset = test_elf_read_u64(image + 40U);
    uint16_t section_size = test_elf_read_u16(image + 58U);
    uint16_t section_count = test_elf_read_u16(image + 60U);
    uint32_t strings_index = test_elf_read_u32(symtab + 40U);
    assert(strings_index < section_count);
    const uint8_t *strings = image + (size_t) table_offset +
                             (size_t) strings_index * section_size;
    uint64_t strings_offset = test_elf_read_u64(strings + 24U);
    uint64_t strings_size = test_elf_read_u64(strings + 32U);
    uint64_t symbols_offset = test_elf_read_u64(symtab + 24U);
    uint64_t symbols_size = test_elf_read_u64(symtab + 32U);
    assert(strings_offset <= image_size &&
           strings_size <= image_size - strings_offset);
    assert(symbols_offset <= image_size &&
           symbols_size <= image_size - symbols_offset &&
           symbols_size % LD_ELF64_SYM_SIZE == 0U);
    for (uint64_t offset = 0U; offset < symbols_size;
         offset += LD_ELF64_SYM_SIZE) {
        const uint8_t *symbol = image + (size_t) symbols_offset +
                                (size_t) offset;
        uint32_t name_offset = test_elf_read_u32(symbol);
        assert(name_offset < strings_size);
        const char *symbol_name =
                (const char *) image + (size_t) strings_offset + name_offset;
        assert(memchr(symbol_name, '\0',
                      (size_t) strings_size - name_offset) != NULL);
        if (strcmp(symbol_name, name) == 0)
            return test_elf_read_u64(symbol + 8U);
    }
    assert(false && "missing output symbol");
    return 0U;
}

static void debug_merge_test_x86_formulae_and_ifunc(void) {
    size_t object_size;
    uint8_t *object = debug_merge_make_x86_object(&object_size);
    char object_path[] = "/tmp/nature-ld-debug-merge-x86-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path =
            "/tmp/nature-ld-debug-merge-x86-output";
    const char *inputs[] = {object_path};
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_inputs_configured(
                   output_path, inputs, 1U, LD_ARCH_AMD64, false,
                   LD_DEBUG_DWARF, true, &capture) == LD_OK);
    assert(capture.count == 0U);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *debug = test_elf_find_output_section(
            image, image_size, ".debug_info");
    assert(debug != NULL);
    uint64_t debug_offset = test_elf_read_u64(debug + 24U);
    uint64_t debug_size = test_elf_read_u64(debug + 32U);
    assert(debug_offset <= image_size && debug_size == 32U &&
           debug_size <= image_size - debug_offset);
    const uint8_t *contents = image + (size_t) debug_offset;
    assert(test_elf_read_u64(contents) == 7U);
    assert(test_elf_read_u32(contents + 8U) == 11U);
    assert(test_elf_read_u64(contents + 12U) == 13U);
    assert(test_elf_read_u64(contents + 24U) ==
           debug_merge_output_symbol_value(image, image_size, "resolver"));
    assert(test_elf_find_output_section(image, image_size, ".plt.got") ==
           NULL);

    free(image);
    unlink(object_path);
    unlink(output_path);
}

static uint8_t *debug_merge_make_aarch64_comdat_winner(
        size_t *result_size) {
    enum {
        group_index = 1,
        text_index = 2,
        symtab_index = 3,
        strtab_index = 4,
        shstrtab_index = 5,
        section_count = 6,
        symbol_count = 3,
    };
    char symbol_names[64] = {0};
    size_t symbol_names_size = 1U;
    uint32_t signature_name = test_elf_append_name(
            symbol_names, sizeof(symbol_names), &symbol_names_size,
            "debug.comdat.signature");
    uint32_t start_name = test_elf_append_name(
            symbol_names, sizeof(symbol_names), &symbol_names_size,
            "_start");

    char section_names[128] = {0};
    size_t section_names_size = 1U;
    uint32_t group_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".group");
    uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text.debug.comdat.winner");
    uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");

    const size_t group_offset = LD_ELF64_EHDR_SIZE;
    const size_t group_size = 2U * sizeof(uint32_t);
    const size_t text_offset = test_elf_align(group_offset + group_size, 4U);
    const size_t text_size = sizeof(uint32_t);
    const size_t symtab_offset =
            test_elf_align(text_offset + text_size, 8U);
    const size_t strtab_offset =
            symtab_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t shstrtab_offset = strtab_offset + symbol_names_size;
    const size_t section_table_offset = test_elf_align(
            shstrtab_offset + section_names_size, 8U);
    const size_t size = section_table_offset +
                        section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1U, size);
    assert(bytes != NULL);

    debug_merge_write_header(bytes, LD_ELF_EM_AARCH64, section_count,
                             shstrtab_index, section_table_offset);
    test_elf_write_u32(bytes + group_offset, LD_ELF_GRP_COMDAT);
    test_elf_write_u32(bytes + group_offset + sizeof(uint32_t), text_index);
    test_elf_write_u32(bytes + text_offset, UINT32_C(0xd65f03c0));
    memcpy(bytes + strtab_offset, symbol_names, symbol_names_size);
    memcpy(bytes + shstrtab_offset, section_names, section_names_size);

    uint8_t *symbols = bytes + symtab_offset;
    debug_merge_write_symbol(symbols + LD_ELF64_SYM_SIZE, signature_name,
                             LD_ELF_STB_LOCAL, LD_ELF_STT_NOTYPE,
                             text_index, 0U, 0U);
    debug_merge_write_symbol(symbols + 2U * LD_ELF64_SYM_SIZE, start_name,
                             LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC,
                             text_index, 0U, text_size);

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(
            sections + group_index * LD_ELF64_SHDR_SIZE, group_name,
            LD_ELF_SHT_GROUP, 0U, group_offset, group_size, symtab_index, 1U,
            sizeof(uint32_t), sizeof(uint32_t));
    test_elf_write_section(
            sections + text_index * LD_ELF64_SHDR_SIZE, text_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR | LD_ELF_SHF_GROUP,
            text_offset, text_size, 0U, 0U, 4U, 0U);
    test_elf_write_section(
            sections + symtab_index * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
            symbol_count * LD_ELF64_SYM_SIZE, strtab_index, 2U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + strtab_index * LD_ELF64_SHDR_SIZE, strtab_name,
            LD_ELF_SHT_STRTAB, 0U, strtab_offset, symbol_names_size, 0U, 0U,
            1U, 0U);
    test_elf_write_section(
            sections + shstrtab_index * LD_ELF64_SHDR_SIZE, shstrtab_name,
            LD_ELF_SHT_STRTAB, 0U, shstrtab_offset, section_names_size, 0U,
            0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static uint8_t *debug_merge_make_aarch64_comdat_loser(
        size_t *result_size) {
    enum {
        group_index = 1,
        text_index = 2,
        debug_info_index = 3,
        debug_loc_index = 4,
        rela_info_index = 5,
        rela_loc_index = 6,
        symtab_index = 7,
        strtab_index = 8,
        shstrtab_index = 9,
        section_count = 10,
        symbol_count = 3,
    };
    char symbol_names[64] = {0};
    size_t symbol_names_size = 1U;
    uint32_t signature_name = test_elf_append_name(
            symbol_names, sizeof(symbol_names), &symbol_names_size,
            "debug.comdat.signature");

    char section_names[256] = {0};
    size_t section_names_size = 1U;
    uint32_t group_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".group");
    uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text.debug.comdat.loser");
    uint32_t debug_info_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".debug_info");
    uint32_t debug_loc_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".debug_loc");
    uint32_t rela_info_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".rela.debug_info");
    uint32_t rela_loc_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".rela.debug_loc");
    uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");

    const size_t group_offset = LD_ELF64_EHDR_SIZE;
    const size_t group_size = 2U * sizeof(uint32_t);
    const size_t text_offset = test_elf_align(group_offset + group_size, 4U);
    const size_t text_size = sizeof(uint32_t);
    const size_t debug_info_offset =
            test_elf_align(text_offset + text_size, 8U);
    const size_t debug_size = sizeof(uint64_t);
    const size_t debug_loc_offset = debug_info_offset + debug_size;
    const size_t rela_info_offset =
            test_elf_align(debug_loc_offset + debug_size, 8U);
    const size_t rela_loc_offset = rela_info_offset + LD_ELF64_RELA_SIZE;
    const size_t symtab_offset =
            test_elf_align(rela_loc_offset + LD_ELF64_RELA_SIZE, 8U);
    const size_t strtab_offset =
            symtab_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t shstrtab_offset = strtab_offset + symbol_names_size;
    const size_t section_table_offset = test_elf_align(
            shstrtab_offset + section_names_size, 8U);
    const size_t size = section_table_offset +
                        section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1U, size);
    assert(bytes != NULL);

    debug_merge_write_header(bytes, LD_ELF_EM_AARCH64, section_count,
                             shstrtab_index, section_table_offset);
    test_elf_write_u32(bytes + group_offset, LD_ELF_GRP_COMDAT);
    test_elf_write_u32(bytes + group_offset + sizeof(uint32_t), text_index);
    test_elf_write_u32(bytes + text_offset, UINT32_C(0xdeadc0de));
    memset(bytes + debug_info_offset, 0xa5, debug_size);
    memset(bytes + debug_loc_offset, 0x5a, debug_size);
    memcpy(bytes + strtab_offset, symbol_names, symbol_names_size);
    memcpy(bytes + shstrtab_offset, section_names, section_names_size);

    uint8_t *symbols = bytes + symtab_offset;
    debug_merge_write_symbol(symbols + LD_ELF64_SYM_SIZE, signature_name,
                             LD_ELF_STB_LOCAL, LD_ELF_STT_NOTYPE,
                             text_index, 0U, 0U);
    debug_merge_write_symbol(symbols + 2U * LD_ELF64_SYM_SIZE, 0U,
                             LD_ELF_STB_LOCAL, LD_ELF_STT_SECTION,
                             text_index, 0U, text_size);

    uint8_t *rela_info = bytes + rela_info_offset;
    test_elf_write_u64(rela_info, 0U);
    test_elf_write_u64(
            rela_info + 8U,
            LD_ELF_RELA_INFO(2U, LD_ELF_R_AARCH64_ABS64));
    test_elf_write_u64(rela_info + 16U, 0U);
    uint8_t *rela_loc = bytes + rela_loc_offset;
    test_elf_write_u64(rela_loc, 0U);
    test_elf_write_u64(
            rela_loc + 8U,
            LD_ELF_RELA_INFO(2U, LD_ELF_R_AARCH64_ABS64));
    test_elf_write_u64(rela_loc + 16U, 0U);

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(
            sections + group_index * LD_ELF64_SHDR_SIZE, group_name,
            LD_ELF_SHT_GROUP, 0U, group_offset, group_size, symtab_index, 1U,
            sizeof(uint32_t), sizeof(uint32_t));
    test_elf_write_section(
            sections + text_index * LD_ELF64_SHDR_SIZE, text_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR | LD_ELF_SHF_GROUP,
            text_offset, text_size, 0U, 0U, 4U, 0U);
    test_elf_write_section(
            sections + debug_info_index * LD_ELF64_SHDR_SIZE,
            debug_info_name, LD_ELF_SHT_PROGBITS, 0U, debug_info_offset,
            debug_size, 0U, 0U, 8U, 0U);
    test_elf_write_section(
            sections + debug_loc_index * LD_ELF64_SHDR_SIZE, debug_loc_name,
            LD_ELF_SHT_PROGBITS, 0U, debug_loc_offset, debug_size, 0U, 0U,
            8U, 0U);
    test_elf_write_section(
            sections + rela_info_index * LD_ELF64_SHDR_SIZE,
            rela_info_name, LD_ELF_SHT_RELA, 0U, rela_info_offset,
            LD_ELF64_RELA_SIZE, symtab_index, debug_info_index, 8U,
            LD_ELF64_RELA_SIZE);
    test_elf_write_section(
            sections + rela_loc_index * LD_ELF64_SHDR_SIZE, rela_loc_name,
            LD_ELF_SHT_RELA, 0U, rela_loc_offset, LD_ELF64_RELA_SIZE,
            symtab_index, debug_loc_index, 8U, LD_ELF64_RELA_SIZE);
    test_elf_write_section(
            sections + symtab_index * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
            symbol_count * LD_ELF64_SYM_SIZE, strtab_index, symbol_count, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + strtab_index * LD_ELF64_SHDR_SIZE, strtab_name,
            LD_ELF_SHT_STRTAB, 0U, strtab_offset, symbol_names_size, 0U, 0U,
            1U, 0U);
    test_elf_write_section(
            sections + shstrtab_index * LD_ELF64_SHDR_SIZE, shstrtab_name,
            LD_ELF_SHT_STRTAB, 0U, shstrtab_offset, section_names_size, 0U,
            0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static void debug_merge_test_comdat_tombstones(void) {
    size_t winner_size;
    size_t loser_size;
    uint8_t *winner =
            debug_merge_make_aarch64_comdat_winner(&winner_size);
    uint8_t *loser = debug_merge_make_aarch64_comdat_loser(&loser_size);
    char winner_path[] =
            "/tmp/nature-ld-debug-comdat-winner-XXXXXX";
    char loser_path[] = "/tmp/nature-ld-debug-comdat-loser-XXXXXX";
    write_fixture(winner_path, winner, winner_size);
    write_fixture(loser_path, loser, loser_size);
    free(winner);
    free(loser);

    static const char *output_path =
            "/tmp/nature-ld-debug-comdat-output";
    const char *inputs[] = {winner_path, loser_path};
    diagnostic_capture_t capture = {0};
    int status = link_test_elf_inputs_configured(
            output_path, inputs, 2U, LD_ARCH_ARM64, false,
            LD_DEBUG_DWARF, true, &capture);
    assert(status == LD_OK);
    assert(capture.count == 0U);
    assert(!test_elf_file_contains_u32(output_path, UINT32_C(0xdeadc0de)));

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *debug_info = test_elf_find_output_section(
            image, image_size, ".debug_info");
    const uint8_t *debug_loc = test_elf_find_output_section(
            image, image_size, ".debug_loc");
    assert(debug_info != NULL && debug_loc != NULL);
    assert(test_elf_read_u64(debug_info + 16U) == 0U);
    assert(test_elf_read_u64(debug_loc + 16U) == 0U);
    uint64_t debug_info_offset = test_elf_read_u64(debug_info + 24U);
    uint64_t debug_info_size = test_elf_read_u64(debug_info + 32U);
    uint64_t debug_loc_offset = test_elf_read_u64(debug_loc + 24U);
    uint64_t debug_loc_size = test_elf_read_u64(debug_loc + 32U);
    assert(debug_info_offset <= image_size && debug_info_size == 8U &&
           debug_info_size <= image_size - debug_info_offset);
    assert(debug_loc_offset <= image_size && debug_loc_size == 8U &&
           debug_loc_size <= image_size - debug_loc_offset);
    assert(test_elf_read_u64(image + (size_t) debug_info_offset) == 0U);
    assert(test_elf_read_u64(image + (size_t) debug_loc_offset) == 1U);

    free(image);
    unlink(winner_path);
    unlink(loser_path);
    unlink(output_path);
}

static uint8_t *debug_merge_make_riscv_owner(size_t *result_size) {
    enum {
        text_index = 1,
        merge_index = 2,
        symtab_index = 3,
        strtab_index = 4,
        shstrtab_index = 5,
        section_count = 6,
        symbol_count = 3,
    };
    static const char prefix[] = "aaaaaaaaaaaaaaaaaaa";
    char merge[sizeof(prefix) + sizeof(debug_merge_riscv_target)];
    memcpy(merge, prefix, sizeof(prefix));
    memcpy(merge + sizeof(prefix), debug_merge_riscv_target,
           sizeof(debug_merge_riscv_target));
    static const char symbols[] = "\0_start";
    char names[128] = {0};
    size_t names_size = 1U;
    uint32_t text_name = test_elf_append_name(
            names, sizeof(names), &names_size, ".text");
    uint32_t merge_name = test_elf_append_name(
            names, sizeof(names), &names_size, ".debug_str");
    uint32_t symtab_name = test_elf_append_name(
            names, sizeof(names), &names_size, ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            names, sizeof(names), &names_size, ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            names, sizeof(names), &names_size, ".shstrtab");

    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t merge_offset = text_offset + 4U;
    const size_t symtab_offset = test_elf_align(
            merge_offset + sizeof(merge), 8U);
    const size_t strtab_offset =
            symtab_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t names_offset = strtab_offset + sizeof(symbols);
    const size_t section_table_offset = test_elf_align(
            names_offset + names_size, 8U);
    const size_t size = section_table_offset +
                        section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1U, size);
    assert(bytes != NULL);
    debug_merge_write_header(bytes, LD_ELF_EM_RISCV, section_count,
                             shstrtab_index, section_table_offset);
    test_elf_write_u32(bytes + text_offset, UINT32_C(0x00000073));
    memcpy(bytes + merge_offset, merge, sizeof(merge));
    memcpy(bytes + strtab_offset, symbols, sizeof(symbols));
    memcpy(bytes + names_offset, names, names_size);
    debug_merge_write_symbol(bytes + symtab_offset + LD_ELF64_SYM_SIZE,
                             0U, LD_ELF_STB_LOCAL, LD_ELF_STT_SECTION,
                             merge_index, 0U, 0U);
    debug_merge_write_symbol(bytes + symtab_offset +
                                     2U * LD_ELF64_SYM_SIZE,
                             1U, LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC,
                             text_index, 0U, 4U);
    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(
            sections + text_index * LD_ELF64_SHDR_SIZE, text_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR, text_offset, 4U, 0U,
            0U, 4U, 0U);
    test_elf_write_section(
            sections + merge_index * LD_ELF64_SHDR_SIZE, merge_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_MERGE | LD_ELF_SHF_STRINGS, merge_offset,
            sizeof(merge), 0U, 0U, 1U, 1U);
    test_elf_write_section(
            sections + symtab_index * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
            symbol_count * LD_ELF64_SYM_SIZE, strtab_index, 2U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + strtab_index * LD_ELF64_SHDR_SIZE, strtab_name,
            LD_ELF_SHT_STRTAB, 0U, strtab_offset, sizeof(symbols), 0U, 0U,
            1U, 0U);
    test_elf_write_section(
            sections + shstrtab_index * LD_ELF64_SHDR_SIZE,
            shstrtab_name, LD_ELF_SHT_STRTAB, 0U, names_offset, names_size,
            0U, 0U, 1U, 0U);
    *result_size = size;
    return bytes;
}

static uint8_t *debug_merge_make_riscv_relocator(size_t *result_size) {
    enum {
        debug_index = 1,
        merge_index = 2,
        rela_index = 3,
        symtab_index = 4,
        strtab_index = 5,
        shstrtab_index = 6,
        section_count = 7,
        symbol_count = 3,
        relocation_count = 2,
    };
    static const char prefix[] = "bbbbbbbbb";
    char merge[sizeof(prefix) + sizeof(debug_merge_riscv_target)];
    memcpy(merge, prefix, sizeof(prefix));
    memcpy(merge + sizeof(prefix), debug_merge_riscv_target,
           sizeof(debug_merge_riscv_target));
    static const char symbols[] = "\0";
    char names[160] = {0};
    size_t names_size = 1U;
    uint32_t debug_name = test_elf_append_name(
            names, sizeof(names), &names_size, ".debug_info");
    uint32_t merge_name = test_elf_append_name(
            names, sizeof(names), &names_size, ".debug_str");
    uint32_t rela_name = test_elf_append_name(
            names, sizeof(names), &names_size, ".rela.debug_info");
    uint32_t symtab_name = test_elf_append_name(
            names, sizeof(names), &names_size, ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            names, sizeof(names), &names_size, ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            names, sizeof(names), &names_size, ".shstrtab");
    const size_t debug_offset = LD_ELF64_EHDR_SIZE;
    const size_t merge_offset = debug_offset + 2U;
    const size_t rela_offset = test_elf_align(
            merge_offset + sizeof(merge), 8U);
    const size_t symtab_offset = test_elf_align(
            rela_offset + relocation_count * LD_ELF64_RELA_SIZE, 8U);
    const size_t strtab_offset =
            symtab_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t names_offset = strtab_offset + sizeof(symbols);
    const size_t section_table_offset = test_elf_align(
            names_offset + names_size, 8U);
    const size_t size = section_table_offset +
                        section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1U, size);
    assert(bytes != NULL);
    debug_merge_write_header(bytes, LD_ELF_EM_RISCV, section_count,
                             shstrtab_index, section_table_offset);
    bytes[debug_offset] = 0x80U;
    bytes[debug_offset + 1U] = 0U;
    memcpy(bytes + merge_offset, merge, sizeof(merge));
    memcpy(bytes + strtab_offset, symbols, sizeof(symbols));
    memcpy(bytes + names_offset, names, names_size);
    debug_merge_write_symbol(bytes + symtab_offset + LD_ELF64_SYM_SIZE,
                             0U, LD_ELF_STB_LOCAL, LD_ELF_STT_SECTION,
                             merge_index, 0U, 0U);
    debug_merge_write_symbol(bytes + symtab_offset +
                                     2U * LD_ELF64_SYM_SIZE,
                             0U, LD_ELF_STB_LOCAL, LD_ELF_STT_NOTYPE,
                             LD_ELF_SHN_ABS, 100U, 0U);
    uint8_t *set = bytes + rela_offset;
    test_elf_write_u64(set, 0U);
    test_elf_write_u64(
            set + 8U,
            LD_ELF_RELA_INFO(2U, LD_ELF_R_RISCV_SET_ULEB128));
    uint8_t *sub = set + LD_ELF64_RELA_SIZE;
    test_elf_write_u64(sub, 0U);
    test_elf_write_u64(
            sub + 8U,
            LD_ELF_RELA_INFO(1U, LD_ELF_R_RISCV_SUB_ULEB128));
    test_elf_write_u64(sub + 16U, sizeof(prefix));
    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(
            sections + debug_index * LD_ELF64_SHDR_SIZE, debug_name,
            LD_ELF_SHT_PROGBITS, 0U, debug_offset, 2U, 0U, 0U, 1U, 0U);
    test_elf_write_section(
            sections + merge_index * LD_ELF64_SHDR_SIZE, merge_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_MERGE | LD_ELF_SHF_STRINGS, merge_offset,
            sizeof(merge), 0U, 0U, 1U, 1U);
    test_elf_write_section(
            sections + rela_index * LD_ELF64_SHDR_SIZE, rela_name,
            LD_ELF_SHT_RELA, 0U, rela_offset,
            relocation_count * LD_ELF64_RELA_SIZE, symtab_index,
            debug_index, 8U, LD_ELF64_RELA_SIZE);
    test_elf_write_section(
            sections + symtab_index * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
            symbol_count * LD_ELF64_SYM_SIZE, strtab_index, symbol_count,
            8U, LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + strtab_index * LD_ELF64_SHDR_SIZE, strtab_name,
            LD_ELF_SHT_STRTAB, 0U, strtab_offset, sizeof(symbols), 0U, 0U,
            1U, 0U);
    test_elf_write_section(
            sections + shstrtab_index * LD_ELF64_SHDR_SIZE,
            shstrtab_name, LD_ELF_SHT_STRTAB, 0U, names_offset, names_size,
            0U, 0U, 1U, 0U);
    *result_size = size;
    return bytes;
}

static size_t debug_merge_find_bytes(const uint8_t *bytes, size_t size,
                                     const uint8_t *needle,
                                     size_t needle_size) {
    assert(needle_size != 0U && needle_size <= size);
    for (size_t i = 0U; i <= size - needle_size; i++) {
        if (memcmp(bytes + i, needle, needle_size) == 0) return i;
    }
    assert(false && "missing merged string");
    return 0U;
}

static void debug_merge_test_riscv_sub_uleb(void) {
    size_t owner_size;
    size_t relocator_size;
    uint8_t *owner = debug_merge_make_riscv_owner(&owner_size);
    uint8_t *relocator = debug_merge_make_riscv_relocator(&relocator_size);
    char owner_path[] = "/tmp/nature-ld-debug-merge-rv-owner-XXXXXX";
    char relocator_path[] = "/tmp/nature-ld-debug-merge-rv-rel-XXXXXX";
    write_fixture(owner_path, owner, owner_size);
    write_fixture(relocator_path, relocator, relocator_size);
    free(owner);
    free(relocator);
    static const char *output_path =
            "/tmp/nature-ld-debug-merge-rv-output";
    const char *inputs[] = {owner_path, relocator_path};
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_inputs_configured(
                   output_path, inputs, 2U, LD_ARCH_RISCV64, false,
                   LD_DEBUG_DWARF, true, &capture) == LD_OK);
    assert(capture.count == 0U);
    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *debug = test_elf_find_output_section(
            image, image_size, ".debug_info");
    const uint8_t *strings = test_elf_find_output_section(
            image, image_size, ".debug_str");
    assert(debug != NULL && strings != NULL);
    uint64_t debug_offset = test_elf_read_u64(debug + 24U);
    uint64_t debug_size = test_elf_read_u64(debug + 32U);
    uint64_t strings_offset = test_elf_read_u64(strings + 24U);
    uint64_t strings_size = test_elf_read_u64(strings + 32U);
    assert(debug_offset <= image_size && debug_size == 2U &&
           debug_size <= image_size - debug_offset);
    assert(strings_offset <= image_size &&
           strings_size <= image_size - strings_offset);
    size_t mapped = debug_merge_find_bytes(
            image + (size_t) strings_offset, (size_t) strings_size,
            (const uint8_t *) debug_merge_riscv_target,
            sizeof(debug_merge_riscv_target));
    const uint64_t addend = sizeof("bbbbbbbbb");
    assert(mapped >= 2U * addend && mapped <= 100U + 2U * addend);
    uint64_t expected = 100U - ((uint64_t) mapped - 2U * addend);
    const uint8_t *encoded = image + (size_t) debug_offset;
    uint64_t actual = (uint64_t) (encoded[0] & 0x7fU) |
                      ((uint64_t) (encoded[1] & 0x7fU) << 7U);
    assert((encoded[0] & 0x80U) != 0U &&
           (encoded[1] & 0x80U) == 0U);
    assert(actual == expected);
    free(image);
    unlink(owner_path);
    unlink(relocator_path);
    unlink(output_path);
}

