}

static uint64_t test_ld_elf_dynamic_read_u64(const uint8_t *bytes) {
    uint64_t value = 0U;
    for (size_t i = 0U; i < 8U; i++)
        value |= (uint64_t) bytes[i] << (i * 8U);
    return value;
}

static void test_ld_elf_dynamic_expect_entries(
        const uint8_t *encoded, size_t encoded_size,
        const test_ld_elf_dynamic_entry_t *expected,
        size_t expected_count) {
    assert(encoded != NULL);
    assert(expected != NULL || expected_count == 0U);
    assert(expected_count <= SIZE_MAX / LD_ELF64_DYN_SIZE);
    assert(encoded_size == expected_count * LD_ELF64_DYN_SIZE);
    for (size_t i = 0U; i < expected_count; i++) {
        const uint8_t *entry = encoded + i * LD_ELF64_DYN_SIZE;
        assert(test_ld_elf_dynamic_read_u64(entry) == expected[i].tag);
        assert(test_ld_elf_dynamic_read_u64(entry + 8U) ==
               expected[i].value);
    }
}

static void test_ld_elf_dynamic_architecture_types(void) {
    assert(ld_elf_dynamic_relative_type(LD_ARCH_AMD64) ==
           LD_ELF_R_X86_64_RELATIVE);
    assert(ld_elf_dynamic_irelative_type(LD_ARCH_AMD64) ==
           LD_ELF_R_X86_64_IRELATIVE);

    assert(ld_elf_dynamic_relative_type(LD_ARCH_ARM64) ==
           LD_ELF_R_AARCH64_RELATIVE);
    assert(ld_elf_dynamic_irelative_type(LD_ARCH_ARM64) ==
           LD_ELF_R_AARCH64_IRELATIVE);

    assert(ld_elf_dynamic_relative_type(LD_ARCH_RISCV64) ==
           LD_ELF_R_RISCV_RELATIVE);
    assert(ld_elf_dynamic_irelative_type(LD_ARCH_RISCV64) ==
           LD_ELF_R_RISCV_IRELATIVE);

    assert(ld_elf_dynamic_relative_type((ld_arch_t) 0) == 0U);
    assert(ld_elf_dynamic_irelative_type((ld_arch_t) 0) == 0U);
    assert(ld_elf_dynamic_relative_type((ld_arch_t) UINT16_MAX) == 0U);
    assert(ld_elf_dynamic_irelative_type((ld_arch_t) UINT16_MAX) == 0U);
}

static void test_ld_elf_dynamic_relocation_order(void) {
    ld_elf_dynamic_relocation_t relocations[] = {
            {
                    .offset = 0x90U,
                    .symbol = 0U,
                    .type = LD_ELF_R_RISCV_IRELATIVE,
                    .addend = 9,
                    .kind = LD_ELF_DYNAMIC_RELOC_IRELATIVE,
            },
            {
                    .offset = 0x40U,
                    .symbol = 2U,
                    .type = 5U,
                    .addend = 4,
                    .kind = LD_ELF_DYNAMIC_RELOC_ORDINARY,
            },
            {
                    .offset = 0x30U,
                    .symbol = 0U,
                    .type = LD_ELF_R_X86_64_RELATIVE,
                    .addend = 3,
                    .kind = LD_ELF_DYNAMIC_RELOC_RELATIVE,
            },
            {
                    .offset = 0x50U,
                    .symbol = 1U,
                    .type = 7U,
                    .addend = 5,
                    .kind = LD_ELF_DYNAMIC_RELOC_ORDINARY,
            },
            {
                    .offset = 0x10U,
                    .symbol = 0U,
                    .type = LD_ELF_R_AARCH64_RELATIVE,
                    .addend = 1,
                    .kind = LD_ELF_DYNAMIC_RELOC_RELATIVE,
            },
            {
                    .offset = 0x80U,
                    .symbol = 0U,
                    .type = LD_ELF_R_X86_64_IRELATIVE,
                    .addend = 8,
                    .kind = LD_ELF_DYNAMIC_RELOC_IRELATIVE,
            },
            {
                    .offset = 0x20U,
                    .symbol = 1U,
                    .type = 7U,
                    .addend = 2,
                    .kind = LD_ELF_DYNAMIC_RELOC_ORDINARY,
            },
    };

    ld_elf_dynamic_sort_relocations(
            relocations, sizeof(relocations) / sizeof(relocations[0]));

    static const ld_elf_dynamic_reloc_kind_t expected_kinds[] = {
            LD_ELF_DYNAMIC_RELOC_RELATIVE,
            LD_ELF_DYNAMIC_RELOC_RELATIVE,
            LD_ELF_DYNAMIC_RELOC_ORDINARY,
            LD_ELF_DYNAMIC_RELOC_ORDINARY,
            LD_ELF_DYNAMIC_RELOC_ORDINARY,
            LD_ELF_DYNAMIC_RELOC_IRELATIVE,
            LD_ELF_DYNAMIC_RELOC_IRELATIVE,
    };
    static const uint64_t expected_offsets[] = {
            0x10U,
            0x30U,
            0x20U,
            0x50U,
            0x40U,
            0x80U,
            0x90U,
    };
    for (size_t i = 0U; i < sizeof(relocations) / sizeof(relocations[0]);
         i++) {
        assert(relocations[i].kind == expected_kinds[i]);
        assert(relocations[i].offset == expected_offsets[i]);
    }

    /* Sorting an already sorted sequence is deterministic. */
    ld_elf_dynamic_relocation_t sorted_copy[sizeof(relocations) /
                                            sizeof(relocations[0])];
    memcpy(sorted_copy, relocations, sizeof(relocations));
    ld_elf_dynamic_sort_relocations(
            relocations, sizeof(relocations) / sizeof(relocations[0]));
    assert(memcmp(sorted_copy, relocations, sizeof(relocations)) == 0);

    ld_elf_dynamic_sort_relocations(NULL, 2U);
    ld_elf_dynamic_sort_relocations(relocations, 0U);
    ld_elf_dynamic_sort_relocations(relocations, 1U);
}

static void test_ld_elf_dynamic_minimal_tables(void) {
    uint8_t dynsym[LD_ELF_DYNAMIC_MIN_DYNSYM_SIZE];
    uint8_t dynstr[LD_ELF_DYNAMIC_MIN_DYNSTR_SIZE];
    uint8_t hash[LD_ELF_DYNAMIC_MIN_HASH_SIZE];
    uint8_t gnu_hash[LD_ELF_DYNAMIC_MIN_GNU_HASH_SIZE];
    memset(dynsym, 0xa5, sizeof(dynsym));
    memset(dynstr, 0xa5, sizeof(dynstr));
    memset(hash, 0xa5, sizeof(hash));
    memset(gnu_hash, 0xa5, sizeof(gnu_hash));

    assert(ld_elf_dynamic_encode_minimal_tables(
                   dynsym, sizeof(dynsym), dynstr, sizeof(dynstr), hash,
                   sizeof(hash), gnu_hash, sizeof(gnu_hash)) ==
           LD_ELF_DYNAMIC_OK);

    static const uint8_t expected_dynsym[LD_ELF_DYNAMIC_MIN_DYNSYM_SIZE] = {
            0U,
    };
    static const uint8_t expected_dynstr[LD_ELF_DYNAMIC_MIN_DYNSTR_SIZE] = {
            0U,
    };
    static const uint8_t expected_hash[LD_ELF_DYNAMIC_MIN_HASH_SIZE] = {
            1U,
            0U,
            0U,
            0U,
            1U,
            0U,
            0U,
            0U,
            0U,
            0U,
            0U,
            0U,
            0U,
            0U,
            0U,
            0U,
    };
    static const uint8_t expected_gnu_hash
            [LD_ELF_DYNAMIC_MIN_GNU_HASH_SIZE] = {
                    1U,
                    0U,
                    0U,
                    0U,
                    1U,
                    0U,
                    0U,
                    0U,
                    1U,
                    0U,
                    0U,
                    0U,
                    26U,
                    0U,
                    0U,
                    0U,
                    0U,
                    0U,
                    0U,
                    0U,
                    0U,
                    0U,
                    0U,
                    0U,
                    0U,
                    0U,
                    0U,
                    0U,
            };
    assert(memcmp(dynsym, expected_dynsym, sizeof(dynsym)) == 0);
    assert(memcmp(dynstr, expected_dynstr, sizeof(dynstr)) == 0);
    assert(memcmp(hash, expected_hash, sizeof(hash)) == 0);
    assert(memcmp(gnu_hash, expected_gnu_hash, sizeof(gnu_hash)) == 0);

    assert(ld_elf_dynamic_encode_minimal_tables(
                   NULL, sizeof(dynsym), dynstr, sizeof(dynstr), hash,
                   sizeof(hash), gnu_hash, sizeof(gnu_hash)) ==
           LD_ELF_DYNAMIC_INVALID_ARGUMENT);
    assert(ld_elf_dynamic_encode_minimal_tables(
                   dynsym, sizeof(dynsym), NULL, sizeof(dynstr), hash,
                   sizeof(hash), gnu_hash, sizeof(gnu_hash)) ==
           LD_ELF_DYNAMIC_INVALID_ARGUMENT);
    assert(ld_elf_dynamic_encode_minimal_tables(
                   dynsym, sizeof(dynsym), dynstr, sizeof(dynstr), NULL,
                   sizeof(hash), gnu_hash, sizeof(gnu_hash)) ==
           LD_ELF_DYNAMIC_INVALID_ARGUMENT);
    assert(ld_elf_dynamic_encode_minimal_tables(
                   dynsym, sizeof(dynsym), dynstr, sizeof(dynstr), hash,
                   sizeof(hash), NULL, sizeof(gnu_hash)) ==
           LD_ELF_DYNAMIC_INVALID_ARGUMENT);

    uint8_t dynsym_before[sizeof(dynsym)];
    uint8_t dynstr_before[sizeof(dynstr)];
    uint8_t hash_before[sizeof(hash)];
    uint8_t gnu_hash_before[sizeof(gnu_hash)];
    memset(dynsym, 0x3c, sizeof(dynsym));
    memset(dynstr, 0x3c, sizeof(dynstr));
    memset(hash, 0x3c, sizeof(hash));
    memset(gnu_hash, 0x3c, sizeof(gnu_hash));
    memcpy(dynsym_before, dynsym, sizeof(dynsym));
    memcpy(dynstr_before, dynstr, sizeof(dynstr));
    memcpy(hash_before, hash, sizeof(hash));
    memcpy(gnu_hash_before, gnu_hash, sizeof(gnu_hash));

#define TEST_LD_ELF_DYNAMIC_WRONG_TABLE_SIZE(dynsym_length, dynstr_length,  \
                                             hash_length, gnu_hash_length)  \
    do {                                                                    \
        assert(ld_elf_dynamic_encode_minimal_tables(                        \
                       dynsym, (dynsym_length), dynstr, (dynstr_length),    \
                       hash, (hash_length), gnu_hash, (gnu_hash_length)) == \
               LD_ELF_DYNAMIC_BUFFER_TOO_SMALL);                            \
        assert(memcmp(dynsym, dynsym_before, sizeof(dynsym)) == 0);         \
        assert(memcmp(dynstr, dynstr_before, sizeof(dynstr)) == 0);         \
        assert(memcmp(hash, hash_before, sizeof(hash)) == 0);               \
        assert(memcmp(gnu_hash, gnu_hash_before, sizeof(gnu_hash)) == 0);   \
    } while (0)

    TEST_LD_ELF_DYNAMIC_WRONG_TABLE_SIZE(sizeof(dynsym) - 1U,
                                         sizeof(dynstr), sizeof(hash),
                                         sizeof(gnu_hash));
    TEST_LD_ELF_DYNAMIC_WRONG_TABLE_SIZE(sizeof(dynsym),
                                         sizeof(dynstr) + 1U, sizeof(hash),
                                         sizeof(gnu_hash));
    TEST_LD_ELF_DYNAMIC_WRONG_TABLE_SIZE(sizeof(dynsym), sizeof(dynstr),
                                         sizeof(hash) - 1U,
                                         sizeof(gnu_hash));
    TEST_LD_ELF_DYNAMIC_WRONG_TABLE_SIZE(sizeof(dynsym), sizeof(dynstr),
                                         sizeof(hash),
                                         sizeof(gnu_hash) + 1U);
#undef TEST_LD_ELF_DYNAMIC_WRONG_TABLE_SIZE
}

static ld_elf_dynamic_metadata_t test_ld_elf_dynamic_base_metadata(void) {
    const ld_elf_dynamic_metadata_t metadata = {
            /* Non-zero optional values must be ignored while flags are off. */
            .init_address = UINT64_C(0xaaaaaaaaaaaaaaaa),
            .fini_address = UINT64_C(0xbbbbbbbbbbbbbbbb),
            .init_array_address = UINT64_C(0xcccccccccccccccc),
            .init_array_size = UINT64_C(0xdddddddddddddddd),
            .fini_array_address = UINT64_C(0xeeeeeeeeeeeeeeee),
            .fini_array_size = UINT64_C(0xffffffffffffffff),
            .rela_address = UINT64_C(0x1111111111111111),
            .rela_size = UINT64_C(0x2222222222222222),
            .hash_address = UINT64_C(0x1020304050607080),
            .gnu_hash_address = UINT64_C(0x1121314151617181),
            .dynsym_address = UINT64_C(0x1222324252627282),
            .dynstr_address = UINT64_C(0x1323334353637383),
            .dynstr_size = UINT64_C(0x1424344454647484),
    };
    return metadata;
}

static void test_ld_elf_dynamic_minimal_metadata(void) {
    const ld_elf_dynamic_metadata_t metadata =
            test_ld_elf_dynamic_base_metadata();
    size_t encoded_size = SIZE_MAX;
    assert(ld_elf_dynamic_metadata_size(&metadata, &encoded_size) ==
           LD_ELF_DYNAMIC_OK);
    assert(encoded_size == 9U * LD_ELF64_DYN_SIZE);

    uint8_t encoded[9U * LD_ELF64_DYN_SIZE];
    memset(encoded, 0xa5, sizeof(encoded));
    assert(ld_elf_dynamic_encode_metadata(&metadata, encoded,
                                          sizeof(encoded)) ==
           LD_ELF_DYNAMIC_OK);
    static const test_ld_elf_dynamic_entry_t expected[] = {
            {LD_ELF_DT_HASH, UINT64_C(0x1020304050607080)},
            {LD_ELF_DT_GNU_HASH, UINT64_C(0x1121314151617181)},
            {LD_ELF_DT_SYMTAB, UINT64_C(0x1222324252627282)},
            {LD_ELF_DT_SYMENT, LD_ELF64_SYM_SIZE},
            {LD_ELF_DT_STRTAB, UINT64_C(0x1323334353637383)},
            {LD_ELF_DT_STRSZ, UINT64_C(0x1424344454647484)},
            {LD_ELF_DT_FLAGS_1, LD_ELF_DF_1_PIE},
            {LD_ELF_DT_DEBUG, 0U},
            {LD_ELF_DT_NULL, 0U},
    };
    test_ld_elf_dynamic_expect_entries(
            encoded, sizeof(encoded), expected,
            sizeof(expected) / sizeof(expected[0]));
}

static void test_ld_elf_dynamic_full_metadata(void) {
    ld_elf_dynamic_metadata_t metadata =
            test_ld_elf_dynamic_base_metadata();
    metadata.has_init = true;
    metadata.has_fini = true;
    metadata.has_init_array = true;
    metadata.has_fini_array = true;
    metadata.has_rela = true;
    metadata.has_static_tls = true;
    metadata.init_address = UINT64_C(0x1000);
    metadata.fini_address = UINT64_C(0x2000);
    metadata.init_array_address = UINT64_C(0x3000);
    metadata.init_array_size = UINT64_C(0x18);
    metadata.fini_array_address = UINT64_C(0x4000);
    metadata.fini_array_size = UINT64_C(0x20);
    metadata.rela_address = UINT64_C(0x5000);
    metadata.rela_size = UINT64_C(0x78);

    size_t encoded_size = 0U;
    assert(ld_elf_dynamic_metadata_size(&metadata, &encoded_size) ==
           LD_ELF_DYNAMIC_OK);
    assert(encoded_size == 19U * LD_ELF64_DYN_SIZE);

    uint8_t encoded[19U * LD_ELF64_DYN_SIZE];
    memset(encoded, 0xa5, sizeof(encoded));
    assert(ld_elf_dynamic_encode_metadata(&metadata, encoded,
                                          sizeof(encoded)) ==
           LD_ELF_DYNAMIC_OK);
    static const test_ld_elf_dynamic_entry_t expected[] = {
            {LD_ELF_DT_INIT, UINT64_C(0x1000)},
            {LD_ELF_DT_FINI, UINT64_C(0x2000)},
            {LD_ELF_DT_INIT_ARRAY, UINT64_C(0x3000)},
            {LD_ELF_DT_INIT_ARRAYSZ, UINT64_C(0x18)},
            {LD_ELF_DT_FINI_ARRAY, UINT64_C(0x4000)},
            {LD_ELF_DT_FINI_ARRAYSZ, UINT64_C(0x20)},
            {LD_ELF_DT_RELA, UINT64_C(0x5000)},
            {LD_ELF_DT_RELASZ, UINT64_C(0x78)},
            {LD_ELF_DT_RELAENT, LD_ELF64_RELA_SIZE},
            {LD_ELF_DT_HASH, UINT64_C(0x1020304050607080)},
            {LD_ELF_DT_GNU_HASH, UINT64_C(0x1121314151617181)},
            {LD_ELF_DT_SYMTAB, UINT64_C(0x1222324252627282)},
            {LD_ELF_DT_SYMENT, LD_ELF64_SYM_SIZE},
            {LD_ELF_DT_STRTAB, UINT64_C(0x1323334353637383)},
            {LD_ELF_DT_STRSZ, UINT64_C(0x1424344454647484)},
            {LD_ELF_DT_FLAGS, LD_ELF_DF_STATIC_TLS},
            {LD_ELF_DT_FLAGS_1, LD_ELF_DF_1_PIE},
            {LD_ELF_DT_DEBUG, 0U},
            {LD_ELF_DT_NULL, 0U},
    };
    test_ld_elf_dynamic_expect_entries(
            encoded, sizeof(encoded), expected,
            sizeof(expected) / sizeof(expected[0]));
}

static void test_ld_elf_dynamic_metadata_errors(void) {
    ld_elf_dynamic_metadata_t metadata =
            test_ld_elf_dynamic_base_metadata();
    size_t encoded_size = 0x1234U;
    assert(ld_elf_dynamic_metadata_size(NULL, &encoded_size) ==
           LD_ELF_DYNAMIC_INVALID_ARGUMENT);
    assert(encoded_size == 0x1234U);
    assert(ld_elf_dynamic_metadata_size(&metadata, NULL) ==
           LD_ELF_DYNAMIC_INVALID_ARGUMENT);

    assert(ld_elf_dynamic_metadata_size(&metadata, &encoded_size) ==
           LD_ELF_DYNAMIC_OK);
    assert(encoded_size == 9U * LD_ELF64_DYN_SIZE);

    uint8_t encoded[10U * LD_ELF64_DYN_SIZE];
    uint8_t before[sizeof(encoded)];
    memset(encoded, 0x6d, sizeof(encoded));
    memcpy(before, encoded, sizeof(encoded));
    assert(ld_elf_dynamic_encode_metadata(NULL, encoded, encoded_size) ==
           LD_ELF_DYNAMIC_INVALID_ARGUMENT);
    assert(memcmp(encoded, before, sizeof(encoded)) == 0);
    assert(ld_elf_dynamic_encode_metadata(&metadata, NULL, encoded_size) ==
           LD_ELF_DYNAMIC_INVALID_ARGUMENT);
    assert(ld_elf_dynamic_encode_metadata(&metadata, encoded,
                                          encoded_size - 1U) ==
           LD_ELF_DYNAMIC_BUFFER_TOO_SMALL);
    assert(memcmp(encoded, before, sizeof(encoded)) == 0);
    assert(ld_elf_dynamic_encode_metadata(&metadata, encoded,
                                          encoded_size + 1U) ==
           LD_ELF_DYNAMIC_BUFFER_TOO_SMALL);
    assert(memcmp(encoded, before, sizeof(encoded)) == 0);
}

static void test_ld_elf_dynamic_result_strings(void) {
    assert(strcmp(ld_elf_dynamic_result_string(LD_ELF_DYNAMIC_OK),
                  "success") == 0);
    assert(strcmp(ld_elf_dynamic_result_string(
                          LD_ELF_DYNAMIC_INVALID_ARGUMENT),
                  "invalid argument") == 0);
    assert(strcmp(ld_elf_dynamic_result_string(LD_ELF_DYNAMIC_OVERFLOW),
                  "integer overflow") == 0);
    assert(strcmp(ld_elf_dynamic_result_string(
                          LD_ELF_DYNAMIC_BUFFER_TOO_SMALL),
                  "output buffer has the wrong size") == 0);
    assert(strcmp(ld_elf_dynamic_result_string(
                          LD_ELF_DYNAMIC_UNSUPPORTED_ARCH),
                  "unsupported architecture") == 0);
    assert(strstr(ld_elf_dynamic_result_string(
                          (ld_elf_dynamic_result_t) 999),
                  "unknown") != NULL);
}

void test_ld_elf_dynamic(void) {
    test_ld_elf_dynamic_architecture_types();
    test_ld_elf_dynamic_relocation_order();
    test_ld_elf_dynamic_relocation_encoding();
    test_ld_elf_dynamic_minimal_tables();
    test_ld_elf_dynamic_minimal_metadata();
    test_ld_elf_dynamic_full_metadata();
    test_ld_elf_dynamic_metadata_errors();
    test_ld_elf_dynamic_result_strings();
}

static uint32_t read_u32(const uint8_t *bytes) {
    return (uint32_t) bytes[0] | ((uint32_t) bytes[1] << 8U) |
           ((uint32_t) bytes[2] << 16U) |
           ((uint32_t) bytes[3] << 24U);
}

static void test_x86_64_pltgot(void) {
    uint8_t entry[LD_ELF_IFUNC_PLTGOT_ENTRY_SIZE];
    memset(entry, 0xa5, sizeof(entry));
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_AMD64, entry, UINT64_C(0x400100),
                   UINT64_C(0x401000)) == LD_ELF_IFUNC_OK);
    static const uint8_t prefix[] = {
            0xf3U,
            0x0fU,
            0x1eU,
            0xfaU,
            0xffU,
            0x25U,
    };
    assert(memcmp(entry, prefix, sizeof(prefix)) == 0);
    assert(read_u32(entry + 6U) == UINT32_C(0x00000ef6));
    for (size_t i = 10U; i < sizeof(entry); i++) assert(entry[i] == 0xccU);

    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_AMD64, entry, UINT64_C(0x401000),
                   UINT64_C(0x400000)) == LD_ELF_IFUNC_OK);
    assert(read_u32(entry + 6U) == UINT32_C(0xffffeff6));

    memset(entry, 0x5a, sizeof(entry));
    uint8_t expected[sizeof(entry)];
    memcpy(expected, entry, sizeof(expected));
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_AMD64, entry, 0U,
                   (uint64_t) INT32_MAX + 11U) == LD_ELF_IFUNC_RANGE);
    assert(memcmp(entry, expected, sizeof(entry)) == 0);
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_AMD64, entry, UINT64_MAX - 9U,
                   0U) == LD_ELF_IFUNC_RANGE);
    assert(memcmp(entry, expected, sizeof(entry)) == 0);
}

static void test_aarch64_pltgot(void) {
    uint8_t entry[LD_ELF_IFUNC_PLTGOT_ENTRY_SIZE];
    memset(entry, 0xa5, sizeof(entry));
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_ARM64, entry, UINT64_C(0x401000),
                   UINT64_C(0x402018)) == LD_ELF_IFUNC_OK);
    assert(read_u32(entry) == UINT32_C(0xb0000010));
    assert(read_u32(entry + 4U) == UINT32_C(0xf9400e11));
    assert(read_u32(entry + 8U) == UINT32_C(0xd61f0220));
    assert(read_u32(entry + 12U) == UINT32_C(0xd503201f));

    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_ARM64, entry, UINT64_C(0x402000),
                   UINT64_C(0x401008)) == LD_ELF_IFUNC_OK);
    assert(read_u32(entry) == UINT32_C(0xf0fffff0));
    assert(read_u32(entry + 4U) == UINT32_C(0xf9400611));

    memset(entry, 0x5a, sizeof(entry));
    uint8_t expected[sizeof(entry)];
    memcpy(expected, entry, sizeof(expected));
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_ARM64, entry, UINT64_C(0x401002),
                   UINT64_C(0x402018)) == LD_ELF_IFUNC_UNALIGNED);
    assert(memcmp(entry, expected, sizeof(entry)) == 0);
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_ARM64, entry, UINT64_C(0x401000),
                   UINT64_C(0x402014)) == LD_ELF_IFUNC_UNALIGNED);
    assert(memcmp(entry, expected, sizeof(entry)) == 0);
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_ARM64, entry, 0U,
                   UINT64_C(0x100000000)) == LD_ELF_IFUNC_RANGE);
    assert(memcmp(entry, expected, sizeof(entry)) == 0);
}

static void test_riscv64_pltgot(void) {
    uint8_t entry[LD_ELF_IFUNC_PLTGOT_ENTRY_SIZE];
    memset(entry, 0xa5, sizeof(entry));

    /* Exact sequence emitted by GNU ld 2.42 for a static RISC-V IFUNC. */
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_RISCV64, entry, UINT64_C(0x10270),
                   UINT64_C(0x82000)) == LD_ELF_IFUNC_OK);
    assert(read_u32(entry) == UINT32_C(0x00072e17));
    assert(read_u32(entry + 4U) == UINT32_C(0xd90e3e03));
    assert(read_u32(entry + 8U) == UINT32_C(0x000e0367));
    assert(read_u32(entry + 12U) == UINT32_C(0x00000013));

    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_RISCV64, entry, UINT64_C(0x401000),
                   UINT64_C(0x402018)) == LD_ELF_IFUNC_OK);
    assert(read_u32(entry) == UINT32_C(0x00001e17));
    assert(read_u32(entry + 4U) == UINT32_C(0x018e3e03));

    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_RISCV64, entry, UINT64_C(0x402000),
                   UINT64_C(0x401008)) == LD_ELF_IFUNC_OK);
    assert(read_u32(entry) == UINT32_C(0xfffffe17));
    assert(read_u32(entry + 4U) == UINT32_C(0x008e3e03));

    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_RISCV64, entry, 0U,
                   UINT64_C(0x7ffff7f8)) == LD_ELF_IFUNC_OK);
    assert(read_u32(entry) == UINT32_C(0x7ffffe17));
    assert(read_u32(entry + 4U) == UINT32_C(0x7f8e3e03));
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_RISCV64, entry, UINT64_C(0x80000000),
                   0U) == LD_ELF_IFUNC_OK);
    assert(read_u32(entry) == UINT32_C(0x80000e17));
    assert(read_u32(entry + 4U) == UINT32_C(0x000e3e03));

    memset(entry, 0x5a, sizeof(entry));
    uint8_t expected[sizeof(entry)];
    memcpy(expected, entry, sizeof(expected));
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_RISCV64, entry, UINT64_C(0x401002),
                   UINT64_C(0x402018)) == LD_ELF_IFUNC_UNALIGNED);
    assert(memcmp(entry, expected, sizeof(entry)) == 0);
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_RISCV64, entry, UINT64_C(0x401000),
                   UINT64_C(0x402014)) == LD_ELF_IFUNC_UNALIGNED);
    assert(memcmp(entry, expected, sizeof(entry)) == 0);
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_RISCV64, entry, 0U,
                   UINT64_C(0x7ffff800)) == LD_ELF_IFUNC_RANGE);
    assert(memcmp(entry, expected, sizeof(entry)) == 0);
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_RISCV64, entry, UINT64_C(0x80000004),
                   0U) == LD_ELF_IFUNC_RANGE);
    assert(memcmp(entry, expected, sizeof(entry)) == 0);
}

static void test_irelative(void) {
    const struct {
        ld_arch_t arch;
        uint32_t type;
    } cases[] = {
            {LD_ARCH_AMD64, LD_ELF_R_X86_64_IRELATIVE},
            {LD_ARCH_ARM64, LD_ELF_R_AARCH64_IRELATIVE},
            {LD_ARCH_RISCV64, LD_ELF_R_RISCV_IRELATIVE},
    };
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
        uint8_t rela[LD_ELF_IFUNC_RELA_SIZE];
        memset(rela, 0xa5, sizeof(rela));
        assert(ld_elf_ifunc_encode_irelative(
                       cases[i].arch, rela, UINT64_C(0x401020),
                       UINT64_C(0x400880)) == LD_ELF_IFUNC_OK);
        assert(read_u64(rela) == UINT64_C(0x401020));
        assert(read_u64(rela + 8U) == cases[i].type);
        assert(read_u64(rela + 16U) == UINT64_C(0x400880));

        assert(ld_elf_ifunc_encode_irelative(
                       cases[i].arch, rela, UINT64_C(0x401020),
                       -INT64_C(7)) == LD_ELF_IFUNC_OK);
        assert(read_u64(rela + 16U) == UINT64_MAX - 6U);
    }

    uint8_t unchanged[LD_ELF_IFUNC_RELA_SIZE];
    memset(unchanged, 0x5a, sizeof(unchanged));
    uint8_t expected[sizeof(unchanged)];
    memcpy(expected, unchanged, sizeof(expected));
    assert(ld_elf_ifunc_encode_irelative(
                   (ld_arch_t) 99, unchanged, 1U, 2U) ==
           LD_ELF_IFUNC_UNSUPPORTED_ARCH);
    assert(memcmp(unchanged, expected, sizeof(unchanged)) == 0);
    assert(ld_elf_ifunc_encode_irelative(
                   LD_ARCH_ARM64, NULL, 1U, 2U) ==
           LD_ELF_IFUNC_INVALID_ARGUMENT);
    assert(ld_elf_ifunc_encode_pltgot(
                   LD_ARCH_ARM64, NULL, 1U, 2U) ==
           LD_ELF_IFUNC_INVALID_ARGUMENT);
}

static const uint8_t *find_output_symbol(const uint8_t *image,
                                         size_t image_size,
                                         const char *name) {
    const uint8_t *symtab =
            test_elf_find_output_section(image, image_size, ".symtab");
    assert(symtab != NULL);
    uint64_t section_table_offset = test_elf_read_u64(image + 40U);
    uint32_t string_index = test_elf_read_u32(symtab + 40U);
    uint16_t section_count = test_elf_read_u16(image + 60U);
    assert(string_index < section_count);
    const uint8_t *strings_header =
            image + section_table_offset +
            (size_t) string_index * LD_ELF64_SHDR_SIZE;
    uint64_t symbols_offset = test_elf_read_u64(symtab + 24U);
    uint64_t symbols_size = test_elf_read_u64(symtab + 32U);
    uint64_t strings_offset = test_elf_read_u64(strings_header + 24U);
    uint64_t strings_size = test_elf_read_u64(strings_header + 32U);
    assert(symbols_offset <= image_size &&
           symbols_size <= image_size - symbols_offset);
    assert(strings_offset <= image_size &&
           strings_size <= image_size - strings_offset);
    const char *strings = (const char *) image + strings_offset;
    for (uint64_t offset = 0U; offset < symbols_size;
         offset += LD_ELF64_SYM_SIZE) {
        const uint8_t *symbol = image + symbols_offset + offset;
        uint32_t name_offset = test_elf_read_u32(symbol);
        assert(name_offset < strings_size);
        assert(memchr(strings + name_offset, '\0',
                      (size_t) strings_size - name_offset) != NULL);
        if (strcmp(strings + name_offset, name) == 0) return symbol;
    }
    return NULL;
}

static void test_ifunc_negative_signed_addend(ld_arch_t arch) {
    const int64_t input_addend = -INT64_C(0x100000);
    size_t object_size;
    uint8_t *object = make_ifunc_link_object(
            arch, input_addend, &object_size);
    char object_path[] = "/tmp/nature-ld-ifunc-negative-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    const char *suffix = arch == LD_ARCH_AMD64
                                 ? "x86"
                                 : (arch == LD_ARCH_ARM64 ? "arm"
                                                          : "riscv");
    char output_path[sizeof(object_path) + 16U];
    assert(snprintf(output_path, sizeof(output_path), "%s.%s",
                    object_path, suffix) > 0);
    unlink(output_path);

    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = arch;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = true;
    options.adhoc_codesign = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    assert(ld_add_input(&options, object_path) == LD_OK);
    assert(ld_link(&options) == LD_OK);
    assert(capture.count == 0U);
    ld_options_deinit(&options);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *data = test_elf_find_output_section(
            image, image_size, ".data");
    const uint8_t *rela = test_elf_find_output_section(
            image, image_size, ".rela.dyn");
    const uint8_t *ifunc = find_output_symbol(
            image, image_size, "ifunc_target");
    assert(data != NULL && rela != NULL && ifunc != NULL);

    uint64_t resolver_address = test_elf_read_u64(ifunc + 8U);
    assert(resolver_address < UINT64_C(0x100000));
    int64_t expected = (int64_t) resolver_address + input_addend;
    assert(expected < 0);
    uint64_t data_address = test_elf_read_u64(data + 16U);
    uint64_t data_offset = test_elf_read_u64(data + 24U);
    uint64_t rela_offset = test_elf_read_u64(rela + 24U);
    uint64_t rela_size = test_elf_read_u64(rela + 32U);
    assert(data_offset <= image_size && 8U <= image_size - data_offset);
    assert(rela_offset <= image_size && rela_size <= image_size - rela_offset);
    assert(test_elf_read_u64(image + data_offset) == (uint64_t) expected);

    const uint32_t irelative_type =
            arch == LD_ARCH_AMD64
                    ? LD_ELF_R_X86_64_IRELATIVE
                    : (arch == LD_ARCH_ARM64
                               ? LD_ELF_R_AARCH64_IRELATIVE
                               : LD_ELF_R_RISCV_IRELATIVE);
    bool found = false;
    for (uint64_t offset = 0U; offset < rela_size;
         offset += LD_ELF_IFUNC_RELA_SIZE) {
        assert(LD_ELF_IFUNC_RELA_SIZE <= rela_size - offset);
        const uint8_t *entry = image + rela_offset + offset;
        if (test_elf_read_u64(entry) != data_address) continue;
        assert(test_elf_read_u64(entry + 8U) == irelative_type);
        assert(test_elf_read_u64(entry + 16U) == (uint64_t) expected);
        found = true;
    }
    assert(found);

    free(image);
    unlink(object_path);
    unlink(output_path);
}

void test_ld_elf_ifunc(void) {
    test_x86_64_pltgot();
    test_aarch64_pltgot();
    test_riscv64_pltgot();
    test_irelative();
    test_ifunc_link(LD_ARCH_AMD64, false);
    test_ifunc_link(LD_ARCH_ARM64, false);
    test_ifunc_link(LD_ARCH_RISCV64, false);
    test_ifunc_link(LD_ARCH_AMD64, true);
    test_ifunc_link(LD_ARCH_ARM64, true);
    test_ifunc_link(LD_ARCH_RISCV64, true);
    test_ifunc_negative_signed_addend(LD_ARCH_AMD64);
    test_ifunc_negative_signed_addend(LD_ARCH_ARM64);
    test_ifunc_negative_signed_addend(LD_ARCH_RISCV64);
}

static uint8_t *make_test_elf_symtab_shndx_object(
        test_elf_shndx_variant_t variant, size_t *result_size) {
    enum {
        compact_text_index = 1,
        symtab_index = 2,
        strtab_index = 3,
        shndx_index = 4,
        compact_shstrtab_index = 5,
        compact_section_count = 6,
        symbol_count = 2,
    };
    const uint32_t text_index =
            variant == TEST_ELF_SHNDX_VALID ? LD_ELF_SHN_LORESERVE
                                            : compact_text_index;
    const uint32_t shstrtab_index =
            variant == TEST_ELF_SHNDX_VALID ? text_index + 1U
                                            : compact_shstrtab_index;
    const uint32_t section_count =
            variant == TEST_ELF_SHNDX_VALID ? shstrtab_index + 1U
                                            : compact_section_count;
    static const char symbol_names[] = "\0_start";
    char section_names[128] = {0};
    size_t section_names_size = 1U;
    const uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text");
    const uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    const uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    const uint32_t shndx_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab_shndx");
    const uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");

    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t symtab_offset = test_elf_align(text_offset + 4U, 8U);
    const size_t strtab_offset =
            symtab_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t shndx_offset =
            test_elf_align(strtab_offset + sizeof(symbol_names), 4U);
    const size_t shstrtab_offset =
            shndx_offset + symbol_count * sizeof(uint32_t);
    const size_t section_table_offset = test_elf_align(
            shstrtab_offset + section_names_size, 8U);
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, LD_ELF_EM_AARCH64);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    /* Section zero carries the real count and section-name table index. */
    test_elf_write_u16(bytes + 60U, 0U);
    test_elf_write_u16(bytes + 62U, LD_ELF_SHN_XINDEX);

    test_elf_write_u32(bytes + text_offset, UINT32_C(0xd65f03c0));
    uint8_t *start = bytes + symtab_offset + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(start, 1U);
    start[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(start + 6U, LD_ELF_SHN_XINDEX);
    test_elf_write_u64(start + 16U, 4U);
    memcpy(bytes + strtab_offset, symbol_names, sizeof(symbol_names));
    test_elf_write_u32(bytes + shndx_offset, 0U);
    test_elf_write_u32(
            bytes + shndx_offset + sizeof(uint32_t),
            variant == TEST_ELF_SHNDX_BAD_INDEX ? section_count : text_index);
    memcpy(bytes + shstrtab_offset, section_names, section_names_size);

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(sections, 0U, LD_ELF_SHT_NULL, 0U, 0U,
                           section_count, shstrtab_index, 0U, 0U, 0U);
    test_elf_write_section(
            sections + text_index * LD_ELF64_SHDR_SIZE, text_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR, text_offset, 4U, 0U,
            0U, 4U, 0U);
    test_elf_write_section(
            sections + symtab_index * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
            symbol_count * LD_ELF64_SYM_SIZE, strtab_index, 1U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + strtab_index * LD_ELF64_SHDR_SIZE, strtab_name,
            LD_ELF_SHT_STRTAB, 0U, strtab_offset, sizeof(symbol_names), 0U,
            0U, 1U, 0U);

    const uint32_t shndx_type = variant == TEST_ELF_SHNDX_MISSING
                                        ? LD_ELF_SHT_PROGBITS
                                        : LD_ELF_SHT_SYMTAB_SHNDX;
    const uint32_t shndx_link = variant == TEST_ELF_SHNDX_BAD_LINK
                                        ? strtab_index
                                        : symtab_index;
    const uint64_t shndx_size = variant == TEST_ELF_SHNDX_BAD_SIZE
                                        ? sizeof(uint32_t)
                                        : symbol_count * sizeof(uint32_t);
    const uint64_t shndx_entsize = variant == TEST_ELF_SHNDX_BAD_ENTSIZE
                                           ? 8U
                                           : sizeof(uint32_t);
    test_elf_write_section(
            sections + shndx_index * LD_ELF64_SHDR_SIZE, shndx_name,
            shndx_type, 0U, shndx_offset, shndx_size, shndx_link, 0U, 4U,
            shndx_entsize);
    test_elf_write_section(
            sections + shstrtab_index * LD_ELF64_SHDR_SIZE, shstrtab_name,
            LD_ELF_SHT_STRTAB, 0U, shstrtab_offset, section_names_size, 0U,
            0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static void expect_invalid_symtab_shndx(test_elf_shndx_variant_t variant,
                                        const char *message_fragment) {
    size_t object_size;
    uint8_t *object =
            make_test_elf_symtab_shndx_object(variant, &object_size);
    char object_path[] = "/tmp/nature-ld-elf-shndx-invalid-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_ARM64;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    ld_elf_context_t ctx;
    ld_elf_context_init(&ctx, &options);
    assert(ld_elf_load_input(&ctx, object_path) == LD_INVALID_INPUT);
    assert(capture.count != 0U);
    assert(strstr(capture.message, message_fragment) != NULL);
    ld_elf_context_deinit(&ctx);
    ld_options_deinit(&options);
    unlink(object_path);
}

static void test_elf_extended_symbol_section_indexes(void) {
    size_t object_size;
    uint8_t *object = make_test_elf_symtab_shndx_object(
            TEST_ELF_SHNDX_VALID, &object_size);
    char object_path[] = "/tmp/nature-ld-elf-shndx-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_ARM64;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    ld_elf_context_t ctx;
    ld_elf_context_init(&ctx, &options);
    assert(ld_elf_load_input(&ctx, object_path) == LD_OK);
    assert(capture.count == 0U);
    assert(ctx.objects.count == 1U);
    ld_elf_object_t *parsed = ctx.objects.items[0];
    assert(parsed->header.e_shnum == 0U);
    assert(parsed->header.e_shstrndx == LD_ELF_SHN_XINDEX);
    assert(parsed->section_count == (size_t) LD_ELF_SHN_LORESERVE + 2U);
    assert(parsed->symbol_count == 2U);
    assert(parsed->symbols[1].entry.st_shndx == LD_ELF_SHN_XINDEX);
    assert(parsed->symbols[1].section ==
           &parsed->sections[LD_ELF_SHN_LORESERVE]);
    assert(strcmp(parsed->symbols[1].section->name, ".text") == 0);
    ld_elf_context_deinit(&ctx);
    ld_options_deinit(&options);

    static const char *output_path = "/tmp/nature-ld-elf-shndx-output";
    unlink(output_path);
    memset(&capture, 0, sizeof(capture));
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_ARM64;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = false;
    options.adhoc_codesign = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    assert(ld_add_input(&options, object_path) == LD_OK);
    assert(ld_link(&options) == LD_OK);
    assert(capture.count == 0U);
    assert(read_test_elf_entry_word(output_path) == UINT32_C(0xd65f03c0));
    ld_options_deinit(&options);

    unlink(object_path);
    unlink(output_path);
}

void test_ld_elf_input(void) {
    test_elf_extended_symbol_section_indexes();
    expect_invalid_symtab_shndx(TEST_ELF_SHNDX_MISSING, "without a linked");
    expect_invalid_symtab_shndx(TEST_ELF_SHNDX_BAD_LINK,
                                "does not link to a symbol table");
    expect_invalid_symtab_shndx(TEST_ELF_SHNDX_BAD_ENTSIZE,
                                "invalid entry size or count");
    expect_invalid_symtab_shndx(TEST_ELF_SHNDX_BAD_SIZE,
                                "invalid entry size or count");
    expect_invalid_symtab_shndx(TEST_ELF_SHNDX_BAD_INDEX,
                                "out-of-range extended section index");
}

static uint8_t *make_init_fini_object(uint32_t init_word,
                                      uint32_t text_word,
                                      uint32_t fini_word, bool define_start,
                                      size_t *result_size) {
    static const char symbol_names[] = "\0_start";
    static const char section_names[] =
            "\0.init\0.text\0.fini\0.symtab\0.strtab\0.shstrtab";
    const size_t init_size = init_word == 0U ? 0U : sizeof(uint32_t);
    const size_t text_size = text_word == 0U ? 0U : sizeof(uint32_t);
    const size_t fini_size = fini_word == 0U ? 0U : sizeof(uint32_t);
    const size_t init_offset = LD_ELF64_EHDR_SIZE;
    const size_t text_offset = test_elf_align(init_offset + init_size, 4U);
    const size_t fini_offset = test_elf_align(text_offset + text_size, 4U);
    const size_t symbol_count = define_start ? 2U : 1U;
    const size_t symbols_offset =
            test_elf_align(fini_offset + fini_size, 8U);
    const size_t strings_offset =
            symbols_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t section_names_offset =
            strings_offset + sizeof(symbol_names);
    const size_t section_table_offset = test_elf_align(
            section_names_offset + sizeof(section_names), 8U);
    const uint16_t section_count = 7U;
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, LD_ELF_EM_AARCH64);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, 6U);

    if (init_size != 0U) test_elf_write_u32(bytes + init_offset, init_word);
    if (text_size != 0U) test_elf_write_u32(bytes + text_offset, text_word);
    if (fini_size != 0U) test_elf_write_u32(bytes + fini_offset, fini_word);
    memcpy(bytes + strings_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + section_names_offset, section_names,
           sizeof(section_names));

    if (define_start) {
        uint8_t *start = bytes + symbols_offset + LD_ELF64_SYM_SIZE;
        test_elf_write_u32(start, 1U);
        start[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
        test_elf_write_u16(start + 6U, 2U);
        test_elf_write_u64(start + 16U, text_size);
    }

    uint8_t *sections = bytes + section_table_offset;
    const uint64_t executable_flags =
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR;
    test_elf_write_section(sections + LD_ELF64_SHDR_SIZE, 1U,
                           LD_ELF_SHT_PROGBITS, executable_flags,
                           init_offset, init_size, 0U, 0U, 4U, 0U);
    test_elf_write_section(sections + 2U * LD_ELF64_SHDR_SIZE, 7U,
                           LD_ELF_SHT_PROGBITS, executable_flags,
                           text_offset, text_size, 0U, 0U, 4U, 0U);
    test_elf_write_section(sections + 3U * LD_ELF64_SHDR_SIZE, 13U,
                           LD_ELF_SHT_PROGBITS, executable_flags,
                           fini_offset, fini_size, 0U, 0U, 4U, 0U);
    test_elf_write_section(sections + 4U * LD_ELF64_SHDR_SIZE, 19U,
                           LD_ELF_SHT_SYMTAB, 0U, symbols_offset,
                           symbol_count * LD_ELF64_SYM_SIZE, 5U, 1U, 8U,
                           LD_ELF64_SYM_SIZE);
    test_elf_write_section(sections + 5U * LD_ELF64_SHDR_SIZE, 27U,
                           LD_ELF_SHT_STRTAB, 0U, strings_offset,
                           sizeof(symbol_names), 0U, 0U, 1U, 0U);
    test_elf_write_section(sections + 6U * LD_ELF64_SHDR_SIZE, 35U,
                           LD_ELF_SHT_STRTAB, 0U, section_names_offset,
                           sizeof(section_names), 0U, 0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static const uint8_t *section_contents(const uint8_t *image,
                                       size_t image_size,
                                       const uint8_t *section,
                                       uint64_t expected_size) {
    assert(section != NULL);
    uint64_t offset = test_elf_read_u64(section + 24U);
    uint64_t size = test_elf_read_u64(section + 32U);
    assert(size == expected_size);
    assert(offset <= image_size && size <= image_size - offset);
    return image + (size_t) offset;
}

static void test_init_fini_sections_are_collected_separately(void) {
    const uint32_t init_head = 0xa1a2a3a4U;
    const uint32_t init_tail = 0xc1c2c3c4U;
    const uint32_t text_word = 0xd65f03c0U;
    const uint32_t fini_head = 0xb1b2b3b4U;
    const uint32_t fini_tail = 0xe1e2e3e4U;
    size_t first_size, main_size, last_size;
    uint8_t *first = make_init_fini_object(
            init_head, 0U, fini_head, false, &first_size);
    uint8_t *main = make_init_fini_object(
            0U, text_word, 0U, true, &main_size);
    uint8_t *last = make_init_fini_object(
            init_tail, 0U, fini_tail, false, &last_size);

    char first_path[] = "/tmp/nature-ld-init-head-XXXXXX";
    char main_path[] = "/tmp/nature-ld-init-main-XXXXXX";
    char last_path[] = "/tmp/nature-ld-init-tail-XXXXXX";
    write_fixture(first_path, first, first_size);
    write_fixture(main_path, main, main_size);
    write_fixture(last_path, last, last_size);
    free(first);
    free(main);
    free(last);

    static const char *output_path = "/tmp/nature-ld-init-fini-output";
    const char *inputs[] = {first_path, main_path, last_path};
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_inputs(output_path, inputs, 3U, &capture) == LD_OK);
    assert(capture.count == 0U);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *init =
            test_elf_find_output_section(image, image_size, ".init");
    const uint8_t *text =
            test_elf_find_output_section(image, image_size, ".text");
    const uint8_t *fini =
            test_elf_find_output_section(image, image_size, ".fini");
    const uint8_t *init_bytes =
            section_contents(image, image_size, init, 2U * sizeof(uint32_t));
    const uint8_t *text_bytes =
            section_contents(image, image_size, text, sizeof(uint32_t));
    const uint8_t *fini_bytes =
            section_contents(image, image_size, fini, 2U * sizeof(uint32_t));

    assert(test_elf_read_u64(init + 16U) <
           test_elf_read_u64(text + 16U));
    assert(test_elf_read_u64(text + 16U) <
           test_elf_read_u64(fini + 16U));
    assert(test_elf_read_u32(init_bytes) == init_head);
    assert(test_elf_read_u32(init_bytes + sizeof(uint32_t)) == init_tail);
    assert(test_elf_read_u32(text_bytes) == text_word);
    assert(test_elf_read_u32(fini_bytes) == fini_head);
    assert(test_elf_read_u32(fini_bytes + sizeof(uint32_t)) == fini_tail);

    free(image);
    unlink(first_path);
    unlink(main_path);
    unlink(last_path);
    unlink(output_path);
}

static uint8_t *make_rodata_alignment_object(uint64_t rodata_alignment,
                                             uint8_t fill,
                                             bool define_start,
                                             size_t *result_size) {
    static const char symbol_names[] = "\0_start";
    static const char section_names[] =
            "\0.text\0.rodata\0.symtab\0.strtab\0.shstrtab";
    const size_t text_size = define_start ? sizeof(uint32_t) : 0U;
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t rodata_offset =
            test_elf_align(text_offset + text_size, rodata_alignment);
    const size_t rodata_size = (size_t) rodata_alignment;
    const size_t symbol_count = define_start ? 2U : 1U;
    const size_t symbols_offset =
            test_elf_align(rodata_offset + rodata_size, 8U);
    const size_t strings_offset =
            symbols_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t section_names_offset =
            strings_offset + sizeof(symbol_names);
    const size_t section_table_offset = test_elf_align(
            section_names_offset + sizeof(section_names), 8U);
    const uint16_t section_count = 6U;
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, LD_ELF_EM_AARCH64);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, 5U);

    if (define_start)
        test_elf_write_u32(bytes + text_offset, 0xd65f03c0U);
    memset(bytes + rodata_offset, fill, rodata_size);
    memcpy(bytes + strings_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + section_names_offset, section_names,
           sizeof(section_names));

    if (define_start) {
        uint8_t *start = bytes + symbols_offset + LD_ELF64_SYM_SIZE;
        test_elf_write_u32(start, 1U);
        start[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
        test_elf_write_u16(start + 6U, 1U);
        test_elf_write_u64(start + 16U, text_size);
    }

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(
            sections + LD_ELF64_SHDR_SIZE, 1U, LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR, text_offset,
            text_size, 0U, 0U, 4U, 0U);
    test_elf_write_section(
            sections + 2U * LD_ELF64_SHDR_SIZE, 7U,
            LD_ELF_SHT_PROGBITS, LD_ELF_SHF_ALLOC, rodata_offset,
            rodata_size, 0U, 0U, rodata_alignment, 0U);
    test_elf_write_section(
            sections + 3U * LD_ELF64_SHDR_SIZE, 15U,
            LD_ELF_SHT_SYMTAB, 0U, symbols_offset,
            symbol_count * LD_ELF64_SYM_SIZE, 4U, 1U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + 4U * LD_ELF64_SHDR_SIZE, 23U,
            LD_ELF_SHT_STRTAB, 0U, strings_offset, sizeof(symbol_names),
            0U, 0U, 1U, 0U);
    test_elf_write_section(
            sections + 5U * LD_ELF64_SHDR_SIZE, 31U,
            LD_ELF_SHT_STRTAB, 0U, section_names_offset,
            sizeof(section_names), 0U, 0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static void test_output_alignment_uses_maximum_input_alignment(void) {
    size_t low_size, high_size;
    uint8_t *low = make_rodata_alignment_object(8U, 0x18U, true,
                                                &low_size);
    uint8_t *high = make_rodata_alignment_object(16U, 0x30U, false,
                                                 &high_size);
    char low_path[] = "/tmp/nature-ld-align-low-XXXXXX";
    char high_path[] = "/tmp/nature-ld-align-high-XXXXXX";
    write_fixture(low_path, low, low_size);
    write_fixture(high_path, high, high_size);
    free(low);
    free(high);

    static const char *output_path = "/tmp/nature-ld-align-output";
    const char *inputs[] = {low_path, high_path};
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_inputs(output_path, inputs, 2U, &capture) == LD_OK);
    assert(capture.count == 0U);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *rodata =
            test_elf_find_output_section(image, image_size, ".rodata");
    assert(rodata != NULL);
    assert(test_elf_read_u64(rodata + 48U) == 16U);
    assert((test_elf_read_u64(rodata + 16U) & 15U) == 0U);
    const uint8_t *contents =
            section_contents(image, image_size, rodata, 32U);
    for (size_t i = 0U; i < 8U; i++) assert(contents[i] == 0x18U);
    for (size_t i = 8U; i < 16U; i++) assert(contents[i] == 0U);
    for (size_t i = 16U; i < 32U; i++) assert(contents[i] == 0x30U);

    free(image);
    unlink(low_path);
    unlink(high_path);
    unlink(output_path);
}

static uint8_t *make_merge_string_object(const char *unique,
                                         bool define_start,
                                         size_t *result_size) {
    static const char symbol_names[] = "\0shared\0_start";
    const size_t shared_size = sizeof("shared");
    const size_t unique_size = strlen(unique) + 1U;
    const size_t merge_size = shared_size + unique_size;
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t data_offset = test_elf_align(text_offset + 4U, 8U);
    const size_t merge_offset = data_offset + 16U;
    const size_t rela_offset = test_elf_align(merge_offset + merge_size, 8U);
    const size_t symbol_count = define_start ? 4U : 3U;
    const size_t symbols_offset =
            rela_offset + 2U * LD_ELF64_RELA_SIZE;
    const size_t strings_offset =
            symbols_offset + symbol_count * LD_ELF64_SYM_SIZE;

    char section_names[128] = {0};
    size_t section_names_size = 1U;
    uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text");
    uint32_t data_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".data");
    uint32_t merge_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".rodata.str1.1");
    uint32_t rela_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".rela.data");
    uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");

    const size_t section_names_offset =
            strings_offset + sizeof(symbol_names);
    const size_t section_table_offset = test_elf_align(
            section_names_offset + section_names_size, 8U);
    const uint16_t section_count = 8U;
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, LD_ELF_EM_AARCH64);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, 7U);

    test_elf_write_u32(bytes + text_offset, 0xd65f03c0U);
    memcpy(bytes + merge_offset, "shared", shared_size);
    memcpy(bytes + merge_offset + shared_size, unique, unique_size);
    memcpy(bytes + strings_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + section_names_offset, section_names,
           section_names_size);

    uint8_t *symbols = bytes + symbols_offset;
    uint8_t *section_symbol = symbols + LD_ELF64_SYM_SIZE;
    section_symbol[4] =
            LD_ELF_SYM_INFO(LD_ELF_STB_LOCAL, LD_ELF_STT_SECTION);
    test_elf_write_u16(section_symbol + 6U, 3U);
    uint8_t *shared_symbol = section_symbol + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(shared_symbol, 1U);
    shared_symbol[4] =
            LD_ELF_SYM_INFO(LD_ELF_STB_LOCAL, LD_ELF_STT_OBJECT);
    test_elf_write_u16(shared_symbol + 6U, 3U);
    test_elf_write_u64(shared_symbol + 16U, shared_size);
    if (define_start) {
        uint8_t *start_symbol = shared_symbol + LD_ELF64_SYM_SIZE;
        test_elf_write_u32(start_symbol, 8U);
        start_symbol[4] =
                LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
        test_elf_write_u16(start_symbol + 6U, 1U);
        test_elf_write_u64(start_symbol + 16U, 4U);
    }

    uint8_t *relocations = bytes + rela_offset;
    test_elf_write_u64(relocations, 0U);
    test_elf_write_u64(
            relocations + 8U,
            LD_ELF_RELA_INFO(2U, LD_ELF_R_AARCH64_ABS64));
    test_elf_write_u64(relocations + LD_ELF64_RELA_SIZE, 8U);
    test_elf_write_u64(
            relocations + LD_ELF64_RELA_SIZE + 8U,
            LD_ELF_RELA_INFO(1U, LD_ELF_R_AARCH64_ABS64));
    test_elf_write_u64(relocations + LD_ELF64_RELA_SIZE + 16U,
                       shared_size);

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(sections + LD_ELF64_SHDR_SIZE, text_name,
                           LD_ELF_SHT_PROGBITS,
                           LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR,
                           text_offset, 4U, 0U, 0U, 4U, 0U);
    test_elf_write_section(sections + 2U * LD_ELF64_SHDR_SIZE, data_name,
                           LD_ELF_SHT_PROGBITS,
                           LD_ELF_SHF_ALLOC | LD_ELF_SHF_WRITE, data_offset,
                           16U, 0U, 0U, 8U, 0U);
    test_elf_write_section(
            sections + 3U * LD_ELF64_SHDR_SIZE, merge_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_MERGE | LD_ELF_SHF_STRINGS,
            merge_offset, merge_size, 0U, 0U, 1U, 1U);
    test_elf_write_section(
            sections + 4U * LD_ELF64_SHDR_SIZE, rela_name, LD_ELF_SHT_RELA,
            0U, rela_offset, 2U * LD_ELF64_RELA_SIZE, 5U, 2U, 8U,
            LD_ELF64_RELA_SIZE);
    test_elf_write_section(
            sections + 5U * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symbols_offset,
            symbol_count * LD_ELF64_SYM_SIZE, 6U, 3U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(sections + 6U * LD_ELF64_SHDR_SIZE, strtab_name,
                           LD_ELF_SHT_STRTAB, 0U, strings_offset,
                           sizeof(symbol_names), 0U, 0U, 1U, 0U);
    test_elf_write_section(
            sections + 7U * LD_ELF64_SHDR_SIZE, shstrtab_name,
            LD_ELF_SHT_STRTAB, 0U, section_names_offset,
            section_names_size, 0U, 0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static const char *output_string_at(const uint8_t *image,
                                    size_t image_size,
                                    const uint8_t *section,
                                    uint64_t address) {
    uint64_t section_address = test_elf_read_u64(section + 16U);
    uint64_t section_offset = test_elf_read_u64(section + 24U);
    uint64_t section_size = test_elf_read_u64(section + 32U);
    assert(address >= section_address &&
           address - section_address < section_size);
    uint64_t offset = section_offset + address - section_address;
    assert(offset < image_size &&
           memchr(image + (size_t) offset, '\0', image_size - offset));
    return (const char *) image + (size_t) offset;
}

static void test_merge_strings_are_deduplicated(void) {
    size_t first_size, second_size;
    uint8_t *first =
            make_merge_string_object("first", true, &first_size);
    uint8_t *second =
            make_merge_string_object("second", false, &second_size);
    char first_path[] = "/tmp/nature-ld-merge-first-XXXXXX";
    char second_path[] = "/tmp/nature-ld-merge-second-XXXXXX";
    write_fixture(first_path, first, first_size);
    write_fixture(second_path, second, second_size);
    free(first);
    free(second);

    static const char *output_path = "/tmp/nature-ld-merge-output";
    const char *inputs[] = {first_path, second_path};
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_inputs(output_path, inputs, 2U, &capture) == LD_OK);
    assert(capture.count == 0U);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *merge = test_elf_find_output_section(
            image, image_size, ".rodata.str1.1");
    const uint8_t *data =
            test_elf_find_output_section(image, image_size, ".data");
    assert(merge != NULL && data != NULL);
    assert(test_elf_read_u64(merge + 32U) ==
           sizeof("shared") + sizeof("first") + sizeof("second"));
    assert(test_elf_read_u64(merge + 56U) == 1U);
    uint64_t flags = test_elf_read_u64(merge + 8U);
    assert((flags & (LD_ELF_SHF_ALLOC | LD_ELF_SHF_MERGE |
                     LD_ELF_SHF_STRINGS)) ==
           (LD_ELF_SHF_ALLOC | LD_ELF_SHF_MERGE | LD_ELF_SHF_STRINGS));

    const uint8_t *data_bytes =
            section_contents(image, image_size, data, 4U * sizeof(uint64_t));
    uint64_t first_shared = test_elf_read_u64(data_bytes);
    uint64_t first_unique = test_elf_read_u64(data_bytes + 8U);
    uint64_t second_shared = test_elf_read_u64(data_bytes + 16U);
    uint64_t second_unique = test_elf_read_u64(data_bytes + 24U);
    assert(first_shared == second_shared);
    assert(first_unique != first_shared && second_unique != first_shared &&
           first_unique != second_unique);
    assert(strcmp(output_string_at(image, image_size, merge, first_shared),
                  "shared") == 0);
    assert(strcmp(output_string_at(image, image_size, merge, first_unique),
                  "first") == 0);
    assert(strcmp(output_string_at(image, image_size, merge, second_unique),
                  "second") == 0);

    free(image);
    unlink(first_path);
    unlink(second_path);
    unlink(output_path);
}

void test_ld_elf_layout(void) {
    test_init_fini_sections_are_collected_separately();
    test_output_alignment_uses_maximum_input_alignment();
    test_merge_strings_are_deduplicated();
}

static const uint8_t *test_link_order_section_contents(
        const uint8_t *image, size_t image_size, const uint8_t *section,
        uint64_t expected_size) {
    assert(section != NULL);
    uint64_t offset = test_elf_read_u64(section + 24U);
    uint64_t size = test_elf_read_u64(section + 32U);
    assert(size == expected_size);
    assert(offset <= image_size && size <= image_size - offset);
    return image + (size_t) offset;
}

static uint32_t test_link_order_section_index(const uint8_t *image,
                                              size_t image_size,
                                              const uint8_t *section) {
    uint64_t table_offset = test_elf_read_u64(image + 40U);
    uint16_t entry_size = test_elf_read_u16(image + 58U);
    uint16_t section_count = test_elf_read_u16(image + 60U);
    assert(entry_size == LD_ELF64_SHDR_SIZE);
    assert(table_offset <= image_size);
    assert((uint64_t) section_count * entry_size <=
           image_size - table_offset);
    const uint8_t *table = image + (size_t) table_offset;
    assert(section >= table && section < table + section_count * entry_size);
    size_t distance = (size_t) (section - table);
    assert(distance % entry_size == 0U);
    return (uint32_t) (distance / entry_size);
}

static void test_elf_link_order_layout(void) {
    size_t object_size;
    uint8_t *object = make_test_elf_link_order_object(
            TEST_ELF_LINK_ORDER_VALID, &object_size);
    char object_path[] = "/tmp/nature-ld-link-order-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path = "/tmp/nature-ld-link-order-output";
    const char *inputs[] = {object_path};
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_inputs(output_path, inputs, 1U, &capture) == LD_OK);
    assert(capture.count == 0U);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *text =
            test_elf_find_output_section(image, image_size, ".text");
    const uint8_t *meta =
            test_elf_find_output_section(image, image_size, ".meta");
    const uint8_t *chain =
            test_elf_find_output_section(image, image_size, ".meta.chain");
    const uint8_t *zero =
            test_elf_find_output_section(image, image_size, ".meta.zero");
    assert(text != NULL && meta != NULL && chain != NULL && zero != NULL);
    assert(test_elf_find_output_section(image, image_size, ".discarded") ==
           NULL);
    assert(test_elf_find_output_section(image, image_size,
                                        ".meta.discarded") == NULL);
    assert(test_elf_find_output_section(image, image_size,
                                        ".meta.discarded.chain") == NULL);

    const uint8_t *text_bytes = test_link_order_section_contents(
            image, image_size, text, 2U * sizeof(uint32_t));
    const uint8_t *meta_bytes = test_link_order_section_contents(
            image, image_size, meta, 3U);
    const uint8_t *chain_bytes = test_link_order_section_contents(
            image, image_size, chain, 3U);
    const uint8_t *zero_bytes = test_link_order_section_contents(
            image, image_size, zero, 1U);
    assert(test_elf_read_u32(text_bytes) == UINT32_C(0xd65f03c0));
    assert(test_elf_read_u32(text_bytes + sizeof(uint32_t)) ==
           UINT32_C(0xd503201f));
    assert(meta_bytes[0] == 0xa1U && meta_bytes[1] == 0xa2U &&
           meta_bytes[2] == 0xb2U);
    assert(chain_bytes[0] == 0xd1U && chain_bytes[1] == 0xd3U &&
           chain_bytes[2] == 0xd2U);
    assert(zero_bytes[0] == 0xf0U);

    assert((test_elf_read_u64(meta + 8U) & LD_ELF_SHF_LINK_ORDER) != 0U);
    assert((test_elf_read_u64(chain + 8U) & LD_ELF_SHF_LINK_ORDER) != 0U);
    assert((test_elf_read_u64(zero + 8U) & LD_ELF_SHF_LINK_ORDER) != 0U);
    assert(test_elf_read_u32(meta + 40U) ==
           test_link_order_section_index(image, image_size, text));
    assert(test_elf_read_u32(chain + 40U) ==
           test_link_order_section_index(image, image_size, meta));
    assert(test_elf_read_u32(zero + 40U) == 0U);

    free(image);
    unlink(object_path);
    unlink(output_path);
}

static void expect_invalid_link_order(test_elf_link_order_variant_t variant,
                                      const char *message_fragment) {
    size_t object_size;
    uint8_t *object = make_test_elf_link_order_object(variant, &object_size);
    char object_path[] = "/tmp/nature-ld-link-order-invalid-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path =
            "/tmp/nature-ld-link-order-invalid-output";
    const char *inputs[] = {object_path};
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_inputs(output_path, inputs, 1U, &capture) ==
           LD_INVALID_INPUT);
    assert(capture.count != 0U);
    assert(strstr(capture.message, message_fragment) != NULL);

    unlink(object_path);
    unlink(output_path);
}

void test_ld_elf_link_order(void) {
    test_elf_link_order_layout();
    expect_invalid_link_order(TEST_ELF_LINK_ORDER_BAD_LINK,
                              "out-of-range section link");
    expect_invalid_link_order(TEST_ELF_LINK_ORDER_SELF_LINK,
                              "links to itself");
    expect_invalid_link_order(TEST_ELF_LINK_ORDER_CYCLE,
                              "dependency cycle");
}

static uint16_t test_elf_output_section_index(const uint8_t *image,
                                              size_t image_size,
                                              const uint8_t *section) {
    uint64_t table_offset = test_elf_read_u64(image + 40U);
    uint16_t entry_size = test_elf_read_u16(image + 58U);
    uint16_t section_count = test_elf_read_u16(image + 60U);
    assert(entry_size == LD_ELF64_SHDR_SIZE && table_offset <= image_size);
    const uint8_t *table = image + (size_t) table_offset;
    assert(section >= table && section < table +
                                                 (size_t) section_count * entry_size);
    size_t delta = (size_t) (section - table);
    assert(delta % entry_size == 0U && delta / entry_size <= UINT16_MAX);
    return (uint16_t) (delta / entry_size);
}

static test_elf_output_symbol_t test_elf_find_output_symbol(
        const uint8_t *image, size_t image_size, const char *name) {
    test_elf_output_symbol_t result = {0};
    const uint8_t *symtab =
            test_elf_find_output_section(image, image_size, ".symtab");
    const uint8_t *strtab =
            test_elf_find_output_section(image, image_size, ".strtab");
    assert(symtab != NULL && strtab != NULL);
    uint64_t symbols_offset = test_elf_read_u64(symtab + 24U);
    uint64_t symbols_size = test_elf_read_u64(symtab + 32U);
    uint64_t entry_size = test_elf_read_u64(symtab + 56U);
    uint64_t strings_offset = test_elf_read_u64(strtab + 24U);
    uint64_t strings_size = test_elf_read_u64(strtab + 32U);
    assert(entry_size == LD_ELF64_SYM_SIZE &&
           symbols_offset <= image_size &&
           symbols_size <= image_size - symbols_offset &&
           symbols_size % entry_size == 0U &&
           strings_offset <= image_size &&
           strings_size <= image_size - strings_offset);
    const char *strings = (const char *) image + strings_offset;
    for (uint64_t offset = 0U; offset < symbols_size;
         offset += entry_size) {
        const uint8_t *symbol = image + symbols_offset + offset;
        uint32_t name_offset = test_elf_read_u32(symbol);
        assert(name_offset < strings_size &&
               memchr(strings + name_offset, '\0',
                      (size_t) strings_size - name_offset));
        if (strcmp(strings + name_offset, name) != 0) continue;
        result.found = true;
        result.info = symbol[4];
        result.other = symbol[5];
        result.section_index = test_elf_read_u16(symbol + 6U);
        result.value = test_elf_read_u64(symbol + 8U);
        result.size = test_elf_read_u64(symbol + 16U);
        break;
    }
    return result;
}

static const uint8_t *test_elf_output_section_contents(
        const uint8_t *image, size_t image_size, const uint8_t *section) {
    assert(section != NULL);
    uint64_t offset = test_elf_read_u64(section + 24U);
    uint64_t size = test_elf_read_u64(section + 32U);
    assert(offset <= image_size && size <= image_size - offset);
    return image + (size_t) offset;
}

static void test_elf_start_stop_link(bool define_start_override) {
    size_t object_size;
    uint8_t *object = make_test_elf_start_stop_object(
            "nature_registry", "__start_nature_registry",
            "__stop_nature_registry", define_start_override, &object_size);
    char object_path[] = "/tmp/nature-ld-start-stop-object-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path = "/tmp/nature-ld-start-stop-output";
    diagnostic_capture_t capture = {0};
    const char *inputs[] = {object_path};
    assert(link_test_elf_inputs(output_path, inputs, 1U, &capture) == LD_OK);
    assert(capture.count == 0U);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *registry = test_elf_find_output_section(
            image, image_size, "nature_registry");
    const uint8_t *write_registry = test_elf_find_output_section(
            image, image_size, "write_registry");
    const uint8_t *exec_registry = test_elf_find_output_section(
            image, image_size, "exec_registry");
    const uint8_t *data =
            test_elf_find_output_section(image, image_size, ".data");
    assert(registry && write_registry && exec_registry && data);
    assert(test_elf_read_u64(registry + 32U) == 12U);
    assert(test_elf_read_u64(write_registry + 32U) == 5U);
    assert(test_elf_read_u64(exec_registry + 32U) == 4U);
    assert((test_elf_read_u64(registry + 8U) & LD_ELF_SHF_WRITE) == 0U);
    assert((test_elf_read_u64(write_registry + 8U) & LD_ELF_SHF_WRITE) !=
           0U);
    assert((test_elf_read_u64(exec_registry + 8U) &
            LD_ELF_SHF_EXECINSTR) != 0U);

    uint64_t registry_start = test_elf_read_u64(registry + 16U);
    uint64_t registry_stop =
            registry_start + test_elf_read_u64(registry + 32U);
    const uint8_t *references =
            test_elf_output_section_contents(image, image_size, data);
    assert(test_elf_read_u64(data + 32U) == 2U * sizeof(uint64_t));
    assert(test_elf_read_u64(references) == registry_start);
    assert(test_elf_read_u64(references + sizeof(uint64_t)) ==
           registry_stop);

    test_elf_output_symbol_t start = test_elf_find_output_symbol(
            image, image_size, "__start_nature_registry");
    test_elf_output_symbol_t stop = test_elf_find_output_symbol(
            image, image_size, "__stop_nature_registry");
    assert(start.found && stop.found);
    assert(start.value == registry_start && stop.value == registry_stop);
    uint16_t registry_index =
            test_elf_output_section_index(image, image_size, registry);
    assert(start.section_index == registry_index &&
           stop.section_index == registry_index);
    assert((start.info >> 4U) == LD_ELF_STB_LOCAL &&
           (stop.info >> 4U) == LD_ELF_STB_LOCAL);
    assert((start.other & 3U) == LD_ELF_STV_HIDDEN &&
           (stop.other & 3U) == LD_ELF_STV_HIDDEN);
    assert(start.size == 0U && stop.size == 0U);

    test_elf_output_symbol_t write_start = test_elf_find_output_symbol(
            image, image_size, "__start_write_registry");
    test_elf_output_symbol_t write_stop = test_elf_find_output_symbol(
            image, image_size, "__stop_write_registry");
    test_elf_output_symbol_t exec_start = test_elf_find_output_symbol(
            image, image_size, "__start_exec_registry");
    test_elf_output_symbol_t exec_stop = test_elf_find_output_symbol(
            image, image_size, "__stop_exec_registry");
    assert(write_start.found && write_stop.found && exec_start.found &&
           exec_stop.found);
    assert(write_start.value == test_elf_read_u64(write_registry + 16U));
    assert(write_stop.value == write_start.value + 5U);
    assert(exec_start.value == test_elf_read_u64(exec_registry + 16U));
    assert(exec_stop.value == exec_start.value + 4U);

    free(image);
    unlink(object_path);
    unlink(output_path);
}

static void test_elf_start_stop_failure(const char *section_name,
                                        const char *start_name,
                                        const char *stop_name) {
    size_t object_size;
    uint8_t *object = make_test_elf_start_stop_object(
            section_name, start_name, stop_name, false, &object_size);
    char object_path[] = "/tmp/nature-ld-start-stop-invalid-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path =
            "/tmp/nature-ld-start-stop-invalid-output";
    diagnostic_capture_t capture = {0};
    const char *inputs[] = {object_path};
    assert(link_test_elf_inputs(output_path, inputs, 1U, &capture) ==
           LD_SYMBOL_ERROR);
    assert(capture.count > 0U);
    assert(strstr(capture.message, "undefined ELF symbol") != NULL);
    assert(access(output_path, F_OK) != 0);
    unlink(object_path);
}

void test_ld_elf_linker_defined(void) {
    test_elf_start_stop_link(false);
    test_elf_start_stop_link(true);
    test_elf_start_stop_failure(
            "nature-bad", "__start_nature-bad", "__stop_nature-bad");
    test_elf_start_stop_failure(
            "nature_registry", "__start_missing", "__stop_missing");
}

static void test_pie_expect_policy(ld_arch_t arch,
                                   const uint32_t *accepted,
                                   size_t accepted_count,
                                   const uint32_t *rejected,
                                   size_t rejected_count) {
    for (size_t i = 0U; i < accepted_count; i++) {
        assert(ld_elf_relocation_supported(arch, accepted[i]));
        assert(ld_elf_relocation_supported_in_static_pie(arch,
                                                         accepted[i]));
    }
    for (size_t i = 0U; i < rejected_count; i++) {
        assert(ld_elf_relocation_supported(arch, rejected[i]));
        assert(!ld_elf_relocation_supported_in_static_pie(arch,
                                                          rejected[i]));
    }
}

static void test_pie_mutate_target_and_addend(
        uint8_t *object, size_t object_size, uint8_t binding,
        uint16_t section_index, uint64_t value, int64_t addend) {
    assert(object != NULL && object_size >= LD_ELF64_EHDR_SIZE);
    uint64_t section_table_offset = test_elf_read_u64(object + 40U);
    uint16_t section_count = test_elf_read_u16(object + 60U);
    assert(section_count == TEST_PIE_SECTION_COUNT);
    assert(section_table_offset <= object_size &&
           (uint64_t) section_count * LD_ELF64_SHDR_SIZE <=
                   object_size - section_table_offset);

    uint8_t *sections = object + (size_t) section_table_offset;
    uint8_t *symtab = sections + TEST_PIE_SYMTAB * LD_ELF64_SHDR_SIZE;
    uint64_t symtab_offset = test_elf_read_u64(symtab + 24U);
    uint64_t symtab_size = test_elf_read_u64(symtab + 32U);
    assert(symtab_offset <= object_size &&
           symtab_size <= object_size - symtab_offset);
    assert((uint64_t) (TEST_PIE_TARGET_SYMBOL + 1U) * LD_ELF64_SYM_SIZE <=
           symtab_size);
    uint8_t *target = object + (size_t) symtab_offset +
                      TEST_PIE_TARGET_SYMBOL * LD_ELF64_SYM_SIZE;
    target[4] = LD_ELF_SYM_INFO(binding, LD_ELF_STT_OBJECT);
    test_elf_write_u16(target + 6U, section_index);
    test_elf_write_u64(target + 8U, value);

    uint8_t *rela = sections + TEST_PIE_RELA_DATA * LD_ELF64_SHDR_SIZE;
    uint64_t rela_offset = test_elf_read_u64(rela + 24U);
    uint64_t rela_size = test_elf_read_u64(rela + 32U);
    assert(rela_offset <= object_size &&
           rela_size <= object_size - rela_offset &&
           rela_size >= LD_ELF64_RELA_SIZE);
    test_elf_write_u64(object + (size_t) rela_offset + 16U,
                       (uint64_t) addend);
}

static int test_pie_link_arch(const char *input_path,
                              const char *output_path, bool pie,
                              ld_arch_t arch,
                              diagnostic_capture_t *capture) {
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = arch;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = pie;
    options.adhoc_codesign = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = capture;
    assert(ld_add_input(&options, input_path) == LD_OK);
    int status = ld_link(&options);
    ld_options_deinit(&options);
    return status;
}

static int test_pie_link(const char *input_path, const char *output_path,
                         bool pie, diagnostic_capture_t *capture) {
    return test_pie_link_arch(input_path, output_path, pie, LD_ARCH_AMD64,
                              capture);
}

static const uint8_t *test_pie_find_program_header(const uint8_t *image,
                                                   size_t image_size,
                                                   uint32_t type,
                                                   size_t *match_count) {
    assert(image != NULL && image_size >= LD_ELF64_EHDR_SIZE);
    uint64_t table_offset = test_elf_read_u64(image + 32U);
    uint16_t entry_size = test_elf_read_u16(image + 54U);
    uint16_t entry_count = test_elf_read_u16(image + 56U);
    assert(entry_size == LD_ELF64_PHDR_SIZE && table_offset <= image_size);
    assert((uint64_t) entry_count * entry_size <= image_size - table_offset);
    const uint8_t *result = NULL;
    size_t count = 0U;
    for (uint16_t i = 0U; i < entry_count; i++) {
        const uint8_t *program = image + (size_t) table_offset +
                                 (size_t) i * entry_size;
        if (test_elf_read_u32(program) != type) continue;
        if (!result) result = program;
        count++;
    }
    if (match_count) *match_count = count;
    return result;
}

static uint16_t test_pie_section_index(const uint8_t *image,
                                       size_t image_size,
                                       const uint8_t *section) {
    assert(image != NULL && section != NULL &&
           image_size >= LD_ELF64_EHDR_SIZE);
    uint64_t table_offset = test_elf_read_u64(image + 40U);
    uint16_t entry_size = test_elf_read_u16(image + 58U);
    uint16_t entry_count = test_elf_read_u16(image + 60U);
    assert(entry_size == LD_ELF64_SHDR_SIZE && table_offset <= image_size);
    assert((uint64_t) entry_count * entry_size <= image_size - table_offset);
    const uint8_t *table = image + (size_t) table_offset;
    assert(section >= table &&
           section < table + (size_t) entry_count * entry_size);
    size_t offset = (size_t) (section - table);
    assert(offset % entry_size == 0U);
    return (uint16_t) (offset / entry_size);
}

static const uint8_t *test_pie_section_contents(const uint8_t *image,
                                                size_t image_size,
                                                const uint8_t *section) {
    assert(image != NULL && section != NULL);
    uint64_t offset = test_elf_read_u64(section + 24U);
    uint64_t size = test_elf_read_u64(section + 32U);
    assert(offset <= image_size && size <= image_size - offset);
    return image + (size_t) offset;
}

static test_pie_output_symbol_t test_pie_find_output_symbol(
        const uint8_t *image, size_t image_size, const char *name) {
    test_pie_output_symbol_t result = {0};
    const uint8_t *symtab =
            test_elf_find_output_section(image, image_size, ".symtab");
    const uint8_t *strtab =
            test_elf_find_output_section(image, image_size, ".strtab");
    assert(symtab != NULL && strtab != NULL);

    uint64_t symbols_offset = test_elf_read_u64(symtab + 24U);
    uint64_t symbols_size = test_elf_read_u64(symtab + 32U);
    uint64_t symbol_size = test_elf_read_u64(symtab + 56U);
    uint64_t strings_offset = test_elf_read_u64(strtab + 24U);
    uint64_t strings_size = test_elf_read_u64(strtab + 32U);
    assert(symbol_size == LD_ELF64_SYM_SIZE &&
           symbols_offset <= image_size &&
           symbols_size <= image_size - symbols_offset &&
           symbols_size % symbol_size == 0U &&
           strings_offset <= image_size &&
           strings_size <= image_size - strings_offset);

    const char *strings = (const char *) image + (size_t) strings_offset;
    for (uint64_t offset = 0U; offset < symbols_size;
         offset += symbol_size) {
        const uint8_t *symbol =
                image + (size_t) symbols_offset + (size_t) offset;
        uint32_t name_offset = test_elf_read_u32(symbol);
        assert(name_offset < strings_size);
        assert(memchr(strings + name_offset, '\0',
                      (size_t) strings_size - name_offset) != NULL);
        if (strcmp(strings + name_offset, name) != 0) continue;
        result.found = true;
        result.info = symbol[4];
        result.other = symbol[5];
        result.section_index = test_elf_read_u16(symbol + 6U);
        result.value = test_elf_read_u64(symbol + 8U);
        result.size = test_elf_read_u64(symbol + 16U);
        break;
    }
    return result;
}

static void test_pie_expect_section_header_links(
        const uint8_t *image, size_t image_size, const uint8_t *dynstr,
        const uint8_t *dynsym, const uint8_t *hash,
        const uint8_t *gnu_hash, const uint8_t *rela,
        const uint8_t *dynamic) {
    const uint16_t dynstr_index =
            test_pie_section_index(image, image_size, dynstr);
    const uint16_t dynsym_index =
            test_pie_section_index(image, image_size, dynsym);

    assert(test_elf_read_u32(dynstr + 4U) == LD_ELF_SHT_STRTAB);
    assert(test_elf_read_u32(dynstr + 40U) == 0U);
    assert(test_elf_read_u32(dynstr + 44U) == 0U);

    assert(test_elf_read_u32(dynsym + 4U) == LD_ELF_SHT_DYNSYM);
    assert(test_elf_read_u32(dynsym + 40U) == dynstr_index);
    assert(test_elf_read_u32(dynsym + 44U) == 1U);
    assert(test_elf_read_u64(dynsym + 56U) == LD_ELF64_SYM_SIZE);

    assert(test_elf_read_u32(hash + 4U) == LD_ELF_SHT_HASH);
    assert(test_elf_read_u32(hash + 40U) == dynsym_index);
    assert(test_elf_read_u32(hash + 44U) == 0U);
    assert(test_elf_read_u64(hash + 56U) == 4U);

    assert(test_elf_read_u32(gnu_hash + 4U) == LD_ELF_SHT_GNU_HASH);
    assert(test_elf_read_u32(gnu_hash + 40U) == dynsym_index);
    assert(test_elf_read_u32(gnu_hash + 44U) == 0U);

    assert(test_elf_read_u32(rela + 4U) == LD_ELF_SHT_RELA);
    assert(test_elf_read_u32(rela + 40U) == dynsym_index);
    assert(test_elf_read_u32(rela + 44U) == 0U);
    assert(test_elf_read_u64(rela + 56U) == LD_ELF64_RELA_SIZE);

    assert(test_elf_read_u32(dynamic + 4U) == LD_ELF_SHT_DYNAMIC);
    assert(test_elf_read_u32(dynamic + 40U) == dynstr_index);
    assert(test_elf_read_u32(dynamic + 44U) == 0U);
    assert(test_elf_read_u64(dynamic + 56U) == LD_ELF64_DYN_SIZE);
}

static void test_pie_expect_dynamic_tags(const uint8_t *image,
                                         size_t image_size,
                                         const uint8_t *dynamic) {
    const uint8_t *contents =
            test_pie_section_contents(image, image_size, dynamic);
    uint64_t size = test_elf_read_u64(dynamic + 32U);
    assert(size >= LD_ELF64_DYN_SIZE && size % LD_ELF64_DYN_SIZE == 0U);
    bool terminated = false;
    bool saw_flags_1 = false;
    for (uint64_t offset = 0U; offset < size;
         offset += LD_ELF64_DYN_SIZE) {
        uint64_t tag = test_elf_read_u64(contents + (size_t) offset);
        uint64_t value =
                test_elf_read_u64(contents + (size_t) offset + 8U);
        assert(tag != 1U); /* DT_NEEDED */
        assert(tag != LD_ELF_DT_FLAGS); /* no static TLS in this fixture */
        if (tag == LD_ELF_DT_FLAGS_1) {
            assert(value == LD_ELF_DF_1_PIE);
            saw_flags_1 = true;
        }
        if (tag != LD_ELF_DT_NULL) continue;
        assert(offset + LD_ELF64_DYN_SIZE == size);
        terminated = true;
        break;
    }
    assert(terminated && saw_flags_1);
}

static bool test_pie_find_dynamic_tag(const uint8_t *image,
                                      size_t image_size,
                                      const uint8_t *dynamic, uint64_t tag,
                                      uint64_t *value) {
    const uint8_t *contents =
            test_pie_section_contents(image, image_size, dynamic);
    uint64_t size = test_elf_read_u64(dynamic + 32U);
    assert(size % LD_ELF64_DYN_SIZE == 0U);
    for (uint64_t offset = 0U; offset < size;
         offset += LD_ELF64_DYN_SIZE) {
        uint64_t current = test_elf_read_u64(contents + (size_t) offset);
        if (current == tag) {
            if (value) {
                *value = test_elf_read_u64(contents + (size_t) offset + 8U);
            }
            return true;
        }
        if (current == LD_ELF_DT_NULL) break;
    }
    return false;
}

static void test_pie_arch_relative_final_outputs(void) {
    static const struct {
        ld_arch_t arch;
        uint16_t machine;
        uint32_t input_type;
        uint32_t relative_type;
        const char *suffix;
    } cases[] = {
            {LD_ARCH_ARM64, LD_ELF_EM_AARCH64, LD_ELF_R_AARCH64_ABS64,
             LD_ELF_R_AARCH64_RELATIVE, "arm64"},
            {LD_ARCH_RISCV64, LD_ELF_EM_RISCV, LD_ELF_R_RISCV_64,
             LD_ELF_R_RISCV_RELATIVE, "riscv64"},
    };
    for (size_t i = 0U; i < sizeof(cases) / sizeof(cases[0]); i++) {
        size_t object_size;
        uint8_t *object = test_pie_make_relocation_object(
                cases[i].machine, cases[i].input_type, false, 0U,
                &object_size);
        char object_path[] = "/tmp/nature-ld-pie-arch-object-XXXXXX";
        write_fixture(object_path, object, object_size);
        free(object);

        char output_path[sizeof(object_path) + 16U];
        assert(snprintf(output_path, sizeof(output_path), "%s.%s",
                        object_path, cases[i].suffix) > 0);
        unlink(output_path);
        diagnostic_capture_t capture = {0};
        assert(test_pie_link_arch(object_path, output_path, true,
                                  cases[i].arch, &capture) == LD_OK);
        assert(capture.count == 0U);

        size_t image_size;
        uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
        assert(test_elf_read_u16(image + 16U) == LD_ELF_ET_DYN);
        assert(test_elf_read_u16(image + 18U) == cases[i].machine);
        size_t match_count = 0U;
        assert(test_pie_find_program_header(
                       image, image_size, LD_ELF_PT_INTERP,
                       &match_count) == NULL);
        assert(match_count == 0U);
        assert(test_pie_find_program_header(
                       image, image_size, LD_ELF_PT_DYNAMIC,
                       &match_count) != NULL &&
               match_count == 1U);

        const uint8_t *data =
                test_elf_find_output_section(image, image_size, ".data");
        const uint8_t *rela = test_elf_find_output_section(
                image, image_size, ".rela.dyn");
        const uint8_t *dynamic = test_elf_find_output_section(
                image, image_size, ".dynamic");
        assert(data != NULL && rela != NULL && dynamic != NULL);
        assert(test_elf_read_u64(rela + 32U) == LD_ELF64_RELA_SIZE);
        assert(test_elf_read_u64(rela + 56U) == LD_ELF64_RELA_SIZE);
        const uint8_t *rela_contents =
                test_pie_section_contents(image, image_size, rela);
        test_pie_output_symbol_t target =
                test_pie_find_output_symbol(image, image_size, "target");
        assert(target.found);
        const uint64_t expected = target.value + 7U;
        assert(test_elf_read_u64(rela_contents) ==
               test_elf_read_u64(data + 16U));
        assert(test_elf_read_u64(rela_contents + 8U) ==
               cases[i].relative_type);
        assert(test_elf_read_u64(rela_contents + 16U) == expected);
        assert(test_elf_read_u64(
                       test_pie_section_contents(image, image_size, data)) ==
               expected);

        uint64_t value = 0U;
        assert(test_pie_find_dynamic_tag(image, image_size, dynamic,
                                         LD_ELF_DT_RELA, &value));
        assert(value == test_elf_read_u64(rela + 16U));
        assert(test_pie_find_dynamic_tag(image, image_size, dynamic,
                                         LD_ELF_DT_RELASZ, &value));
        assert(value == LD_ELF64_RELA_SIZE);
        assert(test_pie_find_dynamic_tag(image, image_size, dynamic,
                                         LD_ELF_DT_RELAENT, &value));
        assert(value == LD_ELF64_RELA_SIZE);

        free(image);
        unlink(object_path);
        unlink(output_path);
    }
}

