        ld_arch_t arch;
        uint16_t machine;
        uint32_t type;
        const char *name;
    } cases[] = {
            {LD_ARCH_AMD64, LD_ELF_EM_X86_64, LD_ELF_R_X86_64_8,
             "R_X86_64_8"},
            {LD_ARCH_AMD64, LD_ELF_EM_X86_64, LD_ELF_R_X86_64_16,
             "R_X86_64_16"},
            {LD_ARCH_ARM64, LD_ELF_EM_AARCH64,
             LD_ELF_R_AARCH64_ABS16, "R_AARCH64_ABS16"},
            {LD_ARCH_ARM64, LD_ELF_EM_AARCH64,
             LD_ELF_R_AARCH64_ABS32, "R_AARCH64_ABS32"},
    };
    for (size_t i = 0U; i < sizeof(cases) / sizeof(cases[0]); i++) {
        test_pie_expect_zig_unhandled_failure(
                cases[i].arch, cases[i].machine, cases[i].type, true, 0U,
                cases[i].name);
    }
}

static void test_pie_rejects_zig_unhandled_riscv_extensions(void) {
    static const struct {
        uint32_t type;
        const char *name;
    } cases[] = {
            {LD_ELF_R_RISCV_BRANCH, "R_RISCV_BRANCH"},
            {LD_ELF_R_RISCV_JAL, "R_RISCV_JAL"},
            {LD_ELF_R_RISCV_CALL, "R_RISCV_CALL"},
            {LD_ELF_R_RISCV_ADD16, "R_RISCV_ADD16"},
            {LD_ELF_R_RISCV_SUB64, "R_RISCV_SUB64"},
            {LD_ELF_R_RISCV_RELAX, "R_RISCV_RELAX"},
            {LD_ELF_R_RISCV_32_PCREL, "R_RISCV_32_PCREL"},
    };
    for (size_t i = 0U; i < sizeof(cases) / sizeof(cases[0]); i++) {
        test_pie_expect_zig_unhandled_failure(
                LD_ARCH_RISCV64, LD_ELF_EM_RISCV, cases[i].type, true,
                0U, cases[i].name);
    }
}

static void test_pie_accepts_riscv_lo12(void) {
    static const struct {
        uint32_t type;
        uint32_t instruction;
        bool is_i_type;
    } cases[] = {
            {LD_ELF_R_RISCV_LO12_I, UINT32_C(0x00000013), true},
            {LD_ELF_R_RISCV_LO12_S, UINT32_C(0x00002023), false},
    };
    for (size_t i = 0U; i < sizeof(cases) / sizeof(cases[0]); i++) {
        size_t object_size;
        uint8_t *object = test_pie_make_relocation_object(
                LD_ELF_EM_RISCV, cases[i].type, false,
                cases[i].instruction, &object_size);
        char object_path[] = "/tmp/nature-ld-pie-riscv-lo12-XXXXXX";
        write_fixture(object_path, object, object_size);
        free(object);

        char output_path[sizeof(object_path) + 8U];
        assert(snprintf(output_path, sizeof(output_path), "%s.pie",
                        object_path) > 0);
        unlink(output_path);
        diagnostic_capture_t capture = {0};
        assert(test_pie_link_arch(object_path, output_path, true,
                                  LD_ARCH_RISCV64, &capture) == LD_OK);
        assert(capture.count == 0U);

        size_t image_size;
        uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
        assert(test_elf_read_u16(image + 16U) == LD_ELF_ET_DYN);
        assert(test_elf_read_u16(image + 18U) == LD_ELF_EM_RISCV);
        const uint8_t *data =
                test_elf_find_output_section(image, image_size, ".data");
        const uint8_t *rela = test_elf_find_output_section(
                image, image_size, ".rela.dyn");
        const uint8_t *dynamic = test_elf_find_output_section(
                image, image_size, ".dynamic");
        assert(data != NULL && rela != NULL && dynamic != NULL);
        assert(test_elf_read_u64(rela + 32U) == 0U);
        uint64_t dynamic_value = 0U;
        assert(!test_pie_find_dynamic_tag(
                image, image_size, dynamic, LD_ELF_DT_RELA,
                &dynamic_value));
        assert(!test_pie_find_dynamic_tag(
                image, image_size, dynamic, LD_ELF_DT_RELASZ,
                &dynamic_value));
        assert(!test_pie_find_dynamic_tag(
                image, image_size, dynamic, LD_ELF_DT_RELAENT,
                &dynamic_value));

        test_pie_output_symbol_t target =
                test_pie_find_output_symbol(image, image_size, "target");
        assert(target.found);
        uint32_t instruction = test_elf_read_u32(
                test_pie_section_contents(image, image_size, data));
        uint32_t immediate = cases[i].is_i_type
                                     ? test_pie_riscv_i_immediate(instruction)
                                     : test_pie_riscv_s_immediate(instruction);
        assert(immediate == ((target.value + 7U) & 0xfffU));

        free(image);
        unlink(object_path);
        unlink(output_path);
    }
}

void test_ld_elf_pie(void) {
    test_pie_zig_relocation_policy();
    test_pie_mode_and_backend_metadata();
    test_pie_arch_relative_final_outputs();
    test_pie_narrow_absolute_failure_is_atomic();
    test_pie_gottpoff_sets_static_tls_flag();
    test_pie_pc32_absolute_failure_is_atomic();
    test_pie_pc_relative_weak_undefined_is_absolute_zero();
    test_pie_relative_accepts_negative_signed_addend();
    test_pie_relative_signed_addend_overflow_is_atomic();
    test_pie_rejects_zig_unhandled_aarch64_movw();
    test_pie_rejects_zig_unhandled_x86_pc_absolute();
    test_pie_rejects_zig_unhandled_absolute_widths();
    test_pie_rejects_zig_unhandled_riscv_extensions();
    test_pie_accepts_riscv_lo12();
}

static size_t make_test_property_note(
        uint8_t *bytes, size_t capacity,
        const test_elf_property_entry_t *entries, size_t entry_count) {
    size_t descriptor_size = 0U;
    for (size_t i = 0; i < entry_count; i++) {
        descriptor_size +=
                test_elf_align(8U + entries[i].data_size, 8U);
    }
    size_t note_size = 16U + descriptor_size;
    assert(note_size <= capacity && descriptor_size <= UINT32_MAX);
    memset(bytes, 0, note_size);
    test_elf_write_u32(bytes, 4U);
    test_elf_write_u32(bytes + 4U, (uint32_t) descriptor_size);
    test_elf_write_u32(bytes + 8U,
                       LD_ELF_NT_GNU_PROPERTY_TYPE_0);
    memcpy(bytes + 12U, "GNU\0", 4U);
    size_t cursor = 16U;
    for (size_t i = 0; i < entry_count; i++) {
        test_elf_write_u32(bytes + cursor, entries[i].type);
        test_elf_write_u32(bytes + cursor + 4U,
                           entries[i].data_size);
        if (entries[i].data_size == 4U) {
            test_elf_write_u32(bytes + cursor + 8U,
                               (uint32_t) entries[i].value);
        } else if (entries[i].data_size == 8U) {
            test_elf_write_u64(bytes + cursor + 8U,
                               entries[i].value);
        }
        cursor = test_elf_align(cursor + 8U + entries[i].data_size, 8U);
    }
    assert(cursor == note_size);
    return note_size;
}

static ld_elf_property_result_t add_test_property_object(
        ld_elf_property_plan_t *plan, ld_arch_t arch,
        const uint8_t *note, size_t note_size) {
    ld_elf_property_input_t input = {
            .data = note,
            .size = note_size,
            .section_index = 3U,
    };
    return ld_elf_property_add_object(plan, arch, &input, 1U);
}

static void expect_property_parse_result(
        ld_arch_t arch, const uint8_t *note, size_t note_size,
        ld_elf_property_result_t expected) {
    ld_elf_property_plan_t plan;
    ld_elf_property_plan_init(&plan);
    assert(add_test_property_object(&plan, arch, note, note_size) ==
           expected);
    ld_elf_property_plan_deinit(&plan);
}

static void test_property_parse_failures(void) {
    uint8_t note[96];
    test_elf_property_entry_t entry = {
            .type = LD_ELF_GNU_PROPERTY_AARCH64_FEATURE_1_AND,
            .data_size = 4U,
            .value = 3U,
    };
    size_t size = make_test_property_note(
            note, sizeof(note), &entry, 1U);
    expect_property_parse_result(LD_ARCH_ARM64, note, 11U,
                                 LD_ELF_PROPERTY_TRUNCATED_NOTE);

    uint8_t malformed[96];
    memcpy(malformed, note, size);
    test_elf_write_u32(malformed, 3U);
    expect_property_parse_result(LD_ARCH_ARM64, malformed, size,
                                 LD_ELF_PROPERTY_INVALID_NOTE);
    memcpy(malformed, note, size);
    malformed[12U] = 'X';
    expect_property_parse_result(LD_ARCH_ARM64, malformed, size,
                                 LD_ELF_PROPERTY_INVALID_OWNER);
    memcpy(malformed, note, size);
    test_elf_write_u32(malformed + 8U, 4U);
    expect_property_parse_result(LD_ARCH_ARM64, malformed, size,
                                 LD_ELF_PROPERTY_INVALID_NOTE);
    memcpy(malformed, note, size);
    test_elf_write_u32(malformed + 4U, 15U);
    expect_property_parse_result(LD_ARCH_ARM64, malformed, size,
                                 LD_ELF_PROPERTY_INVALID_PROPERTY);
    memcpy(malformed, note, size);
    test_elf_write_u32(malformed + 20U, 8U);
    expect_property_parse_result(LD_ARCH_ARM64, malformed, size,
                                 LD_ELF_PROPERTY_INVALID_PROPERTY);
    memcpy(malformed, note, size);
    malformed[28U] = 1U;
    expect_property_parse_result(LD_ARCH_ARM64, malformed, size,
                                 LD_ELF_PROPERTY_INVALID_PROPERTY);
    expect_property_parse_result(LD_ARCH_AMD64, note, size,
                                 LD_ELF_PROPERTY_UNSUPPORTED_PROPERTY);

    test_elf_property_entry_t unsorted[2] = {
            {
                    .type = LD_ELF_GNU_PROPERTY_X86_ISA_1_NEEDED,
                    .data_size = 4U,
                    .value = 1U,
            },
            {
                    .type = LD_ELF_GNU_PROPERTY_X86_FEATURE_1_AND,
                    .data_size = 4U,
                    .value = 1U,
            },
    };
    size = make_test_property_note(
            malformed, sizeof(malformed), unsorted, 2U);
    ld_elf_property_plan_t unsorted_plan;
    ld_elf_property_plan_init(&unsorted_plan);
    assert(add_test_property_object(&unsorted_plan, LD_ARCH_AMD64,
                                    malformed, size) ==
           LD_ELF_PROPERTY_OK);
    assert(ld_elf_property_finalize(&unsorted_plan) ==
           LD_ELF_PROPERTY_OK);
    assert(unsorted_plan.output_size == 48U);
    assert(test_elf_read_u32(unsorted_plan.output + 16U) ==
           LD_ELF_GNU_PROPERTY_X86_FEATURE_1_AND);
    assert(test_elf_read_u32(unsorted_plan.output + 32U) ==
           LD_ELF_GNU_PROPERTY_X86_ISA_1_NEEDED);
    ld_elf_property_plan_deinit(&unsorted_plan);

    test_elf_property_entry_t duplicate[3] = {
            unsorted[0],
            unsorted[1],
            unsorted[0],
    };
    size = make_test_property_note(
            malformed, sizeof(malformed), duplicate, 3U);
    expect_property_parse_result(LD_ARCH_AMD64, malformed, size,
                                 LD_ELF_PROPERTY_DUPLICATE_PROPERTY);

    test_elf_property_entry_t gcc13_used[2] = {
            {
                    .type = LD_ELF_GNU_PROPERTY_X86_ISA_1_USED,
                    .data_size = 4U,
                    .value = 1U,
            },
            {
                    .type = LD_ELF_GNU_PROPERTY_X86_FEATURE_2_USED,
                    .data_size = 4U,
                    .value = 9U,
            },
    };
    size = make_test_property_note(
            malformed, sizeof(malformed), gcc13_used, 2U);
    expect_property_parse_result(LD_ARCH_AMD64, malformed, size,
                                 LD_ELF_PROPERTY_OK);

    unsorted[0].type = 0xc0001234U;
    size = make_test_property_note(
            malformed, sizeof(malformed), unsorted, 1U);
    expect_property_parse_result(LD_ARCH_AMD64, malformed, size,
                                 LD_ELF_PROPERTY_UNSUPPORTED_PROPERTY);

    ld_elf_property_plan_t plan;
    ld_elf_property_plan_init(NULL);
    ld_elf_property_plan_deinit(NULL);
    ld_elf_property_plan_init(&plan);
    assert(ld_elf_property_add_object(NULL, LD_ARCH_ARM64, NULL, 0U) ==
           LD_ELF_PROPERTY_INVALID_ARGUMENT);
    assert(ld_elf_property_add_object(&plan, LD_ARCH_ARM64, NULL, 1U) ==
           LD_ELF_PROPERTY_INVALID_ARGUMENT);
    assert(ld_elf_property_finalize(NULL) ==
           LD_ELF_PROPERTY_INVALID_ARGUMENT);
    ld_elf_property_plan_deinit(&plan);
    assert(strcmp(ld_elf_property_result_string(
                          LD_ELF_PROPERTY_DUPLICATE_PROPERTY),
                  "duplicate GNU property type") == 0);
}

static uint8_t *make_test_property_object(
        const char *symbol_name, const uint8_t *note, size_t note_size,
        size_t *result_size) {
    const bool has_note = note != NULL;
    static const char section_names[] =
            "\0.text\0.note.gnu.property\0.symtab\0.strtab\0.shstrtab";
    const size_t symbol_name_size = strlen(symbol_name) + 2U;
    char *symbol_names = calloc(1, symbol_name_size);
    assert(symbol_names != NULL);
    memcpy(symbol_names + 1U, symbol_name, symbol_name_size - 1U);

    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t note_offset = test_elf_align(text_offset + 4U, 8U);
    const size_t symbol_names_offset =
            has_note ? note_offset + note_size : text_offset + 4U;
    const size_t section_names_offset =
            symbol_names_offset + symbol_name_size;
    const size_t symbols_offset = test_elf_align(
            section_names_offset + sizeof(section_names), 8U);
    const uint16_t section_count = has_note ? 6U : 5U;
    const uint16_t symtab_index = has_note ? 3U : 2U;
    const uint16_t strtab_index = has_note ? 4U : 3U;
    const uint16_t shstrtab_index = has_note ? 5U : 4U;
    const size_t section_table_offset =
            symbols_offset + 2U * LD_ELF64_SYM_SIZE;
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, LD_ELF_EM_AARCH64);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, shstrtab_index);

    test_elf_write_u32(bytes + text_offset, 0xd65f03c0U);
    if (has_note) memcpy(bytes + note_offset, note, note_size);
    memcpy(bytes + symbol_names_offset, symbol_names, symbol_name_size);
    memcpy(bytes + section_names_offset, section_names,
           sizeof(section_names));
    free(symbol_names);

    uint8_t *symbol = bytes + symbols_offset + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(symbol, 1U);
    symbol[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(symbol + 6U, 1U);
    test_elf_write_u64(symbol + 16U, 4U);

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(sections + LD_ELF64_SHDR_SIZE, 1U,
                           LD_ELF_SHT_PROGBITS,
                           LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR,
                           text_offset, 4U, 0U, 0U, 4U, 0U);
    if (has_note) {
        test_elf_write_section(sections + 2U * LD_ELF64_SHDR_SIZE, 7U,
                               LD_ELF_SHT_NOTE, LD_ELF_SHF_ALLOC,
                               note_offset, note_size, 0U, 0U, 8U, 0U);
    }
    test_elf_write_section(
            sections + (size_t) symtab_index * LD_ELF64_SHDR_SIZE, 26U,
            LD_ELF_SHT_SYMTAB, 0U, symbols_offset,
            2U * LD_ELF64_SYM_SIZE, strtab_index, 1U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + (size_t) strtab_index * LD_ELF64_SHDR_SIZE, 34U,
            LD_ELF_SHT_STRTAB, 0U, symbol_names_offset,
            symbol_name_size, 0U, 0U, 1U, 0U);
    test_elf_write_section(
            sections + (size_t) shstrtab_index * LD_ELF64_SHDR_SIZE, 42U,
            LD_ELF_SHT_STRTAB, 0U, section_names_offset,
            sizeof(section_names), 0U, 0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static size_t count_test_program_header(const uint8_t *image,
                                        size_t image_size, uint32_t type,
                                        const uint8_t **result) {
    uint64_t offset = test_elf_read_u64(image + 32U);
    uint16_t entry_size = test_elf_read_u16(image + 54U);
    uint16_t count = test_elf_read_u16(image + 56U);
    assert(entry_size == LD_ELF64_PHDR_SIZE && offset <= image_size &&
           (uint64_t) count * entry_size <= image_size - offset);
    size_t matches = 0U;
    for (uint16_t i = 0; i < count; i++) {
        const uint8_t *program =
                image + (size_t) offset + (size_t) i * entry_size;
        if (test_elf_read_u32(program) != type) continue;
        if (result) *result = program;
        matches++;
    }
    return matches;
}

void test_ld_elf_property(void) {
    test_property_merge_unit();
    test_property_parse_failures();
    test_property_link_integration();
}

static size_t append_property_note(
        uint8_t *bytes, size_t capacity, size_t offset,
        const test_property_note_entry_t *entries, size_t entry_count) {
    size_t descriptor_size = 0U;
    for (size_t i = 0; i < entry_count; i++) {
        size_t entry_size = test_elf_align(
                8U + (size_t) entries[i].data_size, 8U);
        assert(descriptor_size <= SIZE_MAX - entry_size);
        descriptor_size += entry_size;
    }
    assert(descriptor_size <= UINT32_MAX &&
           descriptor_size <= SIZE_MAX - 16U);
    size_t note_size = 16U + descriptor_size;
    assert(offset <= capacity && note_size <= capacity - offset);

    uint8_t *note = bytes + offset;
    memset(note, 0, note_size);
    test_elf_write_u32(note, 4U);
    test_elf_write_u32(note + 4U, (uint32_t) descriptor_size);
    test_elf_write_u32(note + 8U, LD_ELF_NT_GNU_PROPERTY_TYPE_0);
    memcpy(note + 12U, "GNU\0", 4U);

    size_t cursor = 16U;
    for (size_t i = 0; i < entry_count; i++) {
        const test_property_note_entry_t *entry = &entries[i];
        test_elf_write_u32(note + cursor, entry->type);
        test_elf_write_u32(note + cursor + 4U, entry->data_size);
        if (entry->data_size == 4U) {
            test_elf_write_u32(note + cursor + 8U,
                               (uint32_t) entry->value);
        } else if (entry->data_size == 8U) {
            test_elf_write_u64(note + cursor + 8U, entry->value);
        }
        cursor = test_elf_align(
                cursor + 8U + (size_t) entry->data_size, 8U);
    }
    assert(cursor == note_size);
    return note_size;
}

static uint64_t property_output_value(
        const ld_elf_property_plan_t *plan, uint32_t expected_type) {
    assert(plan->finalized && plan->output && plan->output_size >= 16U);
    assert(test_elf_read_u32(plan->output) == 4U);
    assert(test_elf_read_u32(plan->output + 8U) ==
           LD_ELF_NT_GNU_PROPERTY_TYPE_0);
    assert(memcmp(plan->output + 12U, "GNU\0", 4U) == 0);
    size_t descriptor_size = test_elf_read_u32(plan->output + 4U);
    assert(descriptor_size == plan->output_size - 16U);

    size_t cursor = 16U;
    while (cursor < plan->output_size) {
        assert(plan->output_size - cursor >= 8U);
        uint32_t type = test_elf_read_u32(plan->output + cursor);
        uint32_t data_size = test_elf_read_u32(
                plan->output + cursor + 4U);
        assert((size_t) data_size <= plan->output_size - cursor - 8U);
        if (type == expected_type) {
            assert(data_size == 4U || data_size == 8U);
            return data_size == 4U
                           ? test_elf_read_u32(plan->output + cursor + 8U)
                           : test_elf_read_u64(plan->output + cursor + 8U);
        }
        cursor = test_elf_align(
                cursor + 8U + (size_t) data_size, 8U);
    }
    assert(false);
    return 0U;
}

static void test_property_first_note_wins_within_object(void) {
    uint8_t first_note[96], second_note[96];
    test_property_note_entry_t first = {
            .type = LD_ELF_GNU_PROPERTY_X86_FEATURE_1_AND,
            .data_size = 4U,
            .value = LD_ELF_GNU_PROPERTY_X86_FEATURE_1_IBT |
                     LD_ELF_GNU_PROPERTY_X86_FEATURE_1_SHSTK,
    };
    test_property_note_entry_t second[2] = {
            {
                    .type = LD_ELF_GNU_PROPERTY_X86_FEATURE_1_AND,
                    .data_size = 4U,
                    .value = LD_ELF_GNU_PROPERTY_X86_FEATURE_1_IBT,
            },
            {
                    .type = LD_ELF_GNU_PROPERTY_X86_ISA_1_NEEDED,
                    .data_size = 4U,
                    .value = 2U,
            },
    };
    size_t first_size = append_property_note(
            first_note, sizeof(first_note), 0U, &first, 1U);
    size_t second_size = append_property_note(
            second_note, sizeof(second_note), 0U, second, 2U);
    ld_elf_property_input_t inputs[2] = {
            {
                    .data = first_note,
                    .size = first_size,
                    .section_index = 4U,
            },
            {
                    .data = second_note,
                    .size = second_size,
                    .section_index = 7U,
            },
    };

    ld_elf_property_plan_t plan;
    ld_elf_property_plan_init(&plan);
    assert(ld_elf_property_add_object(
                   &plan, LD_ARCH_AMD64, inputs, 2U) ==
           LD_ELF_PROPERTY_OK);

    first.value = LD_ELF_GNU_PROPERTY_X86_FEATURE_1_SHSTK;
    second[0].value = first.value;
    second[0].type = LD_ELF_GNU_PROPERTY_X86_FEATURE_1_AND;
    second[1].value = 1U;
    size_t other_size = append_property_note(
            second_note, sizeof(second_note), 0U, second, 2U);
    ld_elf_property_input_t other = {
            .data = second_note,
            .size = other_size,
            .section_index = 4U,
    };
    assert(ld_elf_property_add_object(
                   &plan, LD_ARCH_AMD64, &other, 1U) ==
           LD_ELF_PROPERTY_OK);
    assert(ld_elf_property_finalize(&plan) == LD_ELF_PROPERTY_OK);

    assert(property_output_value(
                   &plan, LD_ELF_GNU_PROPERTY_X86_FEATURE_1_AND) ==
           LD_ELF_GNU_PROPERTY_X86_FEATURE_1_SHSTK);
    assert(property_output_value(
                   &plan, LD_ELF_GNU_PROPERTY_X86_ISA_1_NEEDED) == 3U);
    ld_elf_property_plan_deinit(&plan);
}

static void test_property_descriptor_duplicate_is_rejected(void) {
    uint8_t note[96];
    test_property_note_entry_t entries[2] = {
            {
                    .type = LD_ELF_GNU_PROPERTY_X86_FEATURE_1_AND,
                    .data_size = 4U,
                    .value = 3U,
            },
            {
                    .type = LD_ELF_GNU_PROPERTY_X86_FEATURE_1_AND,
                    .data_size = 4U,
                    .value = 1U,
            },
    };
    size_t size = append_property_note(
            note, sizeof(note), 0U, entries, 2U);
    ld_elf_property_input_t input = {
            .data = note,
            .size = size,
            .section_index = 4U,
    };
    ld_elf_property_plan_t plan;
    ld_elf_property_plan_init(&plan);
    assert(ld_elf_property_add_object(
                   &plan, LD_ARCH_AMD64, &input, 1U) ==
           LD_ELF_PROPERTY_DUPLICATE_PROPERTY);
    assert(plan.error_input_index == 0U);
    assert(plan.error_offset == 32U);
    assert(plan.error_property_type ==
           LD_ELF_GNU_PROPERTY_X86_FEATURE_1_AND);
    ld_elf_property_plan_deinit(&plan);
}

static void test_later_property_note_is_still_validated(void) {
    uint8_t notes[96];
    test_property_note_entry_t entry = {
            .type = LD_ELF_GNU_PROPERTY_X86_FEATURE_1_AND,
            .data_size = 4U,
            .value = 3U,
    };
    size_t first_size = append_property_note(
            notes, sizeof(notes), 0U, &entry, 1U);
    entry.data_size = 8U;
    size_t second_size = append_property_note(
            notes, sizeof(notes), first_size, &entry, 1U);
    ld_elf_property_input_t input = {
            .data = notes,
            .size = first_size + second_size,
            .section_index = 4U,
    };
    ld_elf_property_plan_t plan;
    ld_elf_property_plan_init(&plan);
    assert(ld_elf_property_add_object(
                   &plan, LD_ARCH_AMD64, &input, 1U) ==
           LD_ELF_PROPERTY_INVALID_PROPERTY);
    assert(plan.error_input_index == 0U);
    assert(plan.error_offset == first_size + 16U);
    assert(plan.error_property_type ==
           LD_ELF_GNU_PROPERTY_X86_FEATURE_1_AND);
    ld_elf_property_plan_deinit(&plan);
}

void test_ld_elf_property_notes(void) {
    test_glibc_concatenated_property_notes();
    test_property_first_note_wins_within_object();
    test_property_descriptor_duplicate_is_rejected();
    test_later_property_note_is_still_validated();
}

static ld_arch_t test_elf_rel_arch(uint16_t machine) {
    if (machine == LD_ELF_EM_X86_64) return LD_ARCH_AMD64;
    if (machine == LD_ELF_EM_AARCH64) return LD_ARCH_ARM64;
    assert(machine == LD_ELF_EM_RISCV);
    return LD_ARCH_RISCV64;
}

static uint32_t test_elf_rel_riscv_jal(int32_t displacement) {
    uint32_t immediate = (uint32_t) displacement & 0x1fffffU;
    uint32_t instruction = 0x0000006fU;
    instruction |= (immediate & 0x100000U) << 11U;
    instruction |= (immediate & 0x0007feU) << 20U;
    instruction |= (immediate & 0x000800U) << 9U;
    instruction |= immediate & 0x0ff000U;
    return instruction;
}

static uint32_t test_elf_rel_aarch64_adr(uint32_t opcode,
                                         int64_t immediate, bool page) {
    uint64_t encoded = (uint64_t) (page ? immediate / 4096 : immediate) &
                       0x1fffffU;
    return opcode | (uint32_t) ((encoded & 3U) << 29U) |
           (uint32_t) (((encoded >> 2U) & 0x7ffffU) << 5U);
}

static int test_elf_rel_decode_direct(uint16_t machine, uint32_t type,
                                      const uint8_t *data, size_t size,
                                      int64_t *addend,
                                      diagnostic_capture_t *capture) {
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = test_elf_rel_arch(machine);
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = capture;
    ld_elf_context_t ctx;
    ld_elf_context_init(&ctx, &options);
    ld_elf_object_t object = {0};
    object.header.e_machine = machine;
    object.display_name = (char *) "direct-rel-test.o";
    ld_elf_section_t section = {0};
    section.header.sh_type = LD_ELF_SHT_PROGBITS;
    section.name = ".text";
    section.data = data;
    section.data_size = size;
    ld_elf_relocation_t relocation = {
            .type = type,
    };
    int result = ld_elf_rel_decode_addend(
            &ctx, &object, &section, &relocation, addend);
    ld_elf_context_deinit(&ctx);
    ld_options_deinit(&options);
    return result;
}

static void test_elf_rel_direct_decoders(void) {
    uint8_t data[16] = {0};
    diagnostic_capture_t capture = {0};
    int64_t addend;

    test_elf_write_u64(data, UINT64_MAX - 7U);
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_X86_64, LD_ELF_R_X86_64_64, data,
                   sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == -8 && capture.count == 0U);
    test_elf_write_u32(data, UINT32_MAX);
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_X86_64, LD_ELF_R_X86_64_32, data,
                   sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == (int64_t) UINT32_MAX);
    test_elf_write_u16(data, UINT16_MAX - 1U);
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_X86_64, LD_ELF_R_X86_64_PC16, data,
                   sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == -2);

    test_elf_write_u32(
            data, test_elf_rel_aarch64_adr(0x90000000U, -4096, true));
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_AARCH64,
                   LD_ELF_R_AARCH64_ADR_PREL_PG_HI21, data,
                   sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == -4096);
    test_elf_write_u32(
            data, test_elf_rel_aarch64_adr(0x10000000U, -4, false));
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_AARCH64, LD_ELF_R_AARCH64_ADR_PREL_LO21,
                   data, sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == -4);
    test_elf_write_u32(data, 0x91000000U | (0xabcU << 10U));
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_AARCH64,
                   LD_ELF_R_AARCH64_ADD_ABS_LO12_NC, data,
                   sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == 0xabc);
    test_elf_write_u32(data, 0x91400000U | (0x123U << 10U));
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_AARCH64,
                   LD_ELF_R_AARCH64_TLSLE_ADD_TPREL_HI12, data,
                   sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == 0x123000);
    test_elf_write_u32(data, 0xf9400000U | (0x12U << 10U));
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_AARCH64,
                   LD_ELF_R_AARCH64_LD64_GOT_LO12_NC, data,
                   sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == 0x90);
    test_elf_write_u32(data,
                       0xd2800000U | (2U << 21U) | (0x1234U << 5U));
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_AARCH64, LD_ELF_R_AARCH64_MOVW_UABS_G2,
                   data, sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == INT64_C(0x123400000000));

    test_elf_write_u64(data, UINT64_MAX - 7U);
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_RISCV, LD_ELF_R_RISCV_64, data,
                   sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == -8);
    test_elf_write_u32(data, 0x00001097U);
    test_elf_write_u32(data + 4U, 0x234080e7U);
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_RISCV, LD_ELF_R_RISCV_CALL, data,
                   sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == 0x1234);
    test_elf_write_u32(data, 0xfffff037U);
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_RISCV, LD_ELF_R_RISCV_HI20, data,
                   sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == -4096);
    test_elf_write_u32(data, 0xffc00013U);
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_RISCV, LD_ELF_R_RISCV_LO12_I, data,
                   sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == -4);
    data[0] = 0xacU;
    data[1] = 0x02U;
    assert(test_elf_rel_decode_direct(
                   LD_ELF_EM_RISCV, LD_ELF_R_RISCV_SET_ULEB128, data,
                   sizeof(data), &addend, &capture) == LD_OK);
    assert(addend == 300);
}

static test_elf_rel_fixture_t test_elf_make_rel_fixture(
        uint16_t machine, uint32_t relocation_type,
        uint32_t initial_instruction) {
    static const char symbol_names[] = "\0_start\0target";
    static const char section_names[] =
            "\0.text\0.symtab\0.strtab\0.shstrtab\0.rel.text";
    const uint32_t text_name = 1U;
    const uint32_t symtab_name = 7U;
    const uint32_t strtab_name = 15U;
    const uint32_t shstrtab_name = 23U;
    const uint32_t rel_name = 33U;
    const uint32_t start_name = 1U;
    const uint32_t target_name = 8U;
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t text_size = 8U;
    const size_t symtab_offset =
            test_elf_align(text_offset + text_size, 8U);
    const size_t symbol_count = 3U;
    const size_t strtab_offset =
            symtab_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t shstrtab_offset = strtab_offset + sizeof(symbol_names);
    const size_t rel_offset =
            test_elf_align(shstrtab_offset + sizeof(section_names), 8U);
    const size_t section_table_offset = rel_offset + LD_ELF64_REL_SIZE;
    const uint16_t section_count = 6U;
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, machine);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, 4U);

    test_elf_write_u32(bytes + text_offset, initial_instruction);
    if (machine == LD_ELF_EM_AARCH64) {
        test_elf_write_u32(bytes + text_offset + 4U, 0xd65f03c0U);
    } else if (machine == LD_ELF_EM_RISCV) {
        test_elf_write_u32(bytes + text_offset + 4U, 0x00008067U);
    } else {
        bytes[text_offset + 4U] = 0xc3U;
    }
    memcpy(bytes + strtab_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + shstrtab_offset, section_names, sizeof(section_names));

    uint8_t *symbols = bytes + symtab_offset;
    uint8_t *start = symbols + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(start, start_name);
    start[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(start + 6U, 1U);
    test_elf_write_u64(start + 8U, 0U);
    test_elf_write_u64(start + 16U, text_size);
    uint8_t *target = start + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(target, target_name);
    target[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(target + 6U, 1U);
    test_elf_write_u64(target + 8U, 4U);
    test_elf_write_u64(target + 16U, 4U);

    test_elf_write_u64(bytes + rel_offset, 0U);
    test_elf_write_u64(
            bytes + rel_offset + 8U,
            LD_ELF_RELA_INFO(2U, relocation_type));

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(sections + LD_ELF64_SHDR_SIZE, text_name,
                           LD_ELF_SHT_PROGBITS,
                           LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR,
                           text_offset, text_size, 0U, 0U, 4U, 0U);
    test_elf_write_section(sections + 2U * LD_ELF64_SHDR_SIZE, symtab_name,
                           LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
                           symbol_count * LD_ELF64_SYM_SIZE, 3U, 1U, 8U,
                           LD_ELF64_SYM_SIZE);
    test_elf_write_section(sections + 3U * LD_ELF64_SHDR_SIZE, strtab_name,
                           LD_ELF_SHT_STRTAB, 0U, strtab_offset,
                           sizeof(symbol_names), 0U, 0U, 1U, 0U);
    test_elf_write_section(sections + 4U * LD_ELF64_SHDR_SIZE,
                           shstrtab_name, LD_ELF_SHT_STRTAB, 0U,
                           shstrtab_offset, sizeof(section_names), 0U, 0U,
                           1U, 0U);
    test_elf_write_section(sections + 5U * LD_ELF64_SHDR_SIZE, rel_name,
                           LD_ELF_SHT_REL, LD_ELF_SHF_INFO_LINK, rel_offset,
                           LD_ELF64_REL_SIZE, 2U, 1U, 8U,
                           LD_ELF64_REL_SIZE);

    test_elf_rel_fixture_t fixture = {
            .bytes = bytes,
            .size = size,
            .text_offset = text_offset,
            .rel_offset = rel_offset,
            .section_table_offset = section_table_offset,
    };
    return fixture;
}

static void test_elf_rel_parse_fixture(test_elf_rel_fixture_t *fixture,
                                       uint16_t machine,
                                       int64_t expected_addend) {
    char input_path[] = "/tmp/nature-ld-rel-parse-XXXXXX";
    write_fixture(input_path, fixture->bytes, fixture->size);

    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = test_elf_rel_arch(machine);
    diagnostic_capture_t capture = {0};
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    ld_elf_context_t ctx;
    ld_elf_context_init(&ctx, &options);
    assert(ld_elf_load_input(&ctx, input_path) == LD_OK);
    assert(capture.count == 0U);
    assert(ctx.objects.count == 1U);
    assert(ctx.objects.items[0]->section_count == 6U);
    const ld_elf_section_t *text = &ctx.objects.items[0]->sections[1];
    assert(text->relocation_count == 1U);
    assert(text->relocations[0].addend == expected_addend);
    assert(text->relocations[0].relocation_section_index == 5U);
    ld_elf_context_deinit(&ctx);
    ld_options_deinit(&options);
    unlink(input_path);
}

static void test_elf_rel_link_fixture(test_elf_rel_fixture_t *fixture,
                                      uint16_t machine,
                                      uint32_t expected_entry_word) {
    char input_path[] = "/tmp/nature-ld-rel-link-XXXXXX";
    char output_path[] = "/tmp/nature-ld-rel-output-XXXXXX";
    write_fixture(input_path, fixture->bytes, fixture->size);
    int output_fd = mkstemp(output_path);
    assert(output_fd >= 0);
    assert(close(output_fd) == 0);
    unlink(output_path);

    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = test_elf_rel_arch(machine);
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = false;
    options.adhoc_codesign = false;
    diagnostic_capture_t capture = {0};
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    assert(ld_add_input(&options, input_path) == LD_OK);
    assert(ld_link(&options) == LD_OK);
    assert(capture.count == 0U);
    assert(read_test_elf_entry_word(output_path) == expected_entry_word);
    ld_options_deinit(&options);
    unlink(input_path);
    unlink(output_path);
}

static void test_elf_expect_rel_failure(test_elf_rel_fixture_t *fixture,
                                        uint16_t machine, int expected,
                                        const char *fragment) {
    char input_path[] = "/tmp/nature-ld-rel-invalid-XXXXXX";
    char output_path[] = "/tmp/nature-ld-rel-invalid-output-XXXXXX";
    write_fixture(input_path, fixture->bytes, fixture->size);
    int output_fd = mkstemp(output_path);
    assert(output_fd >= 0);
    assert(close(output_fd) == 0);
    unlink(output_path);

    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = test_elf_rel_arch(machine);
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = false;
    options.adhoc_codesign = false;
    diagnostic_capture_t capture = {0};
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    assert(ld_add_input(&options, input_path) == LD_OK);
    assert(ld_link(&options) == expected);
    assert(capture.count > 0U);
    assert(strstr(capture.message, fragment) != NULL);
    assert(access(output_path, F_OK) != 0);
    ld_options_deinit(&options);
    unlink(input_path);
}

static void test_elf_rel_three_architectures(void) {
    test_elf_rel_fixture_t amd64 = test_elf_make_rel_fixture(
            LD_ELF_EM_X86_64, LD_ELF_R_X86_64_PC32, UINT32_MAX - 3U);
    test_elf_rel_parse_fixture(&amd64, LD_ELF_EM_X86_64, -4);
    test_elf_rel_link_fixture(&amd64, LD_ELF_EM_X86_64, 0U);
    free(amd64.bytes);

    test_elf_rel_fixture_t arm64 = test_elf_make_rel_fixture(
            LD_ELF_EM_AARCH64, LD_ELF_R_AARCH64_CALL26, 0x97ffffffU);
    test_elf_rel_parse_fixture(&arm64, LD_ELF_EM_AARCH64, -4);
    test_elf_rel_link_fixture(&arm64, LD_ELF_EM_AARCH64, 0x94000000U);
    free(arm64.bytes);

    test_elf_rel_fixture_t riscv = test_elf_make_rel_fixture(
            LD_ELF_EM_RISCV, LD_ELF_R_RISCV_JAL,
            test_elf_rel_riscv_jal(-4));
    test_elf_rel_parse_fixture(&riscv, LD_ELF_EM_RISCV, -4);
    test_elf_rel_link_fixture(&riscv, LD_ELF_EM_RISCV, 0x0000006fU);
    free(riscv.bytes);
}

static void test_elf_rel_malformed_inputs(void) {
    test_elf_rel_fixture_t fixture = test_elf_make_rel_fixture(
            LD_ELF_EM_AARCH64, LD_ELF_R_AARCH64_CALL26, 0x97ffffffU);
    uint8_t *rel_header = fixture.bytes + fixture.section_table_offset +
                          5U * LD_ELF64_SHDR_SIZE;

    test_elf_write_u64(rel_header + 56U, LD_ELF64_RELA_SIZE);
    test_elf_expect_rel_failure(&fixture, LD_ELF_EM_AARCH64,
                                LD_INVALID_INPUT, "expected 16-byte entries");
    test_elf_write_u64(rel_header + 56U, LD_ELF64_REL_SIZE);

    test_elf_write_u64(rel_header + 32U, LD_ELF64_REL_SIZE - 1U);
    test_elf_expect_rel_failure(&fixture, LD_ELF_EM_AARCH64,
                                LD_INVALID_INPUT, "expected 16-byte entries");
    test_elf_write_u64(rel_header + 32U, LD_ELF64_REL_SIZE);

    test_elf_write_u64(fixture.bytes + fixture.rel_offset, 6U);
    test_elf_expect_rel_failure(&fixture, LD_ELF_EM_AARCH64,
                                LD_INVALID_INPUT,
                                "4-byte relocation field extends");
    test_elf_write_u64(fixture.bytes + fixture.rel_offset, 0U);

    test_elf_write_u64(
            fixture.bytes + fixture.rel_offset + 8U,
            LD_ELF_RELA_INFO(3U, LD_ELF_R_AARCH64_CALL26));
    test_elf_expect_rel_failure(&fixture, LD_ELF_EM_AARCH64,
                                LD_INVALID_INPUT,
                                "out-of-range symbol index 3");
    test_elf_write_u64(
            fixture.bytes + fixture.rel_offset + 8U,
            LD_ELF_RELA_INFO(2U, LD_ELF_R_AARCH64_CALL26));

    uint8_t *text_header = fixture.bytes + fixture.section_table_offset +
                           LD_ELF64_SHDR_SIZE;
    test_elf_write_u32(text_header + 4U, LD_ELF_SHT_NOBITS);
    test_elf_expect_rel_failure(&fixture, LD_ELF_EM_AARCH64,
                                LD_INVALID_INPUT, "SHT_NOBITS");
    test_elf_write_u32(text_header + 4U, LD_ELF_SHT_PROGBITS);

    test_elf_write_u32(fixture.bytes + fixture.text_offset, 0xd503201fU);
    test_elf_expect_rel_failure(&fixture, LD_ELF_EM_AARCH64,
                                LD_INVALID_INPUT, "expected BL instruction");
    free(fixture.bytes);

    fixture = test_elf_make_rel_fixture(
            LD_ELF_EM_RISCV, LD_ELF_R_RISCV_ALIGN, 0x00000013U);
    test_elf_expect_rel_failure(&fixture, LD_ELF_EM_RISCV,
                                LD_UNSUPPORTED,
                                "does not contain a reversible implicit addend");
    free(fixture.bytes);
}

void test_ld_elf_rel_input(void) {
    test_elf_rel_direct_decoders();
    test_elf_rel_three_architectures();
    test_elf_rel_malformed_inputs();
}

static uint8_t *make_amd64_rex_gotpcrelx_object(bool far_nobits_target,
                                                size_t *result_size) {
    static const char symbol_names[] = "\0target\0_start";
    static const uint8_t text_bytes[] = {
            0x48U,
            0x8bU,
            0x05U,
            0x00U,
            0x00U,
            0x00U,
            0x00U,
            0xc3U,
    };
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t data_offset = text_offset + sizeof(text_bytes);
    const size_t data_file_size = far_nobits_target ? 0U : 8U;
    const uint64_t target_offset =
            far_nobits_target ? UINT64_C(0x80000000) : 0U;
    const uint64_t data_size = target_offset + 8U;
    const size_t rela_offset =
            test_elf_align(data_offset + data_file_size, 8U);
    const size_t symbols_offset = rela_offset + LD_ELF64_RELA_SIZE;
    const size_t strings_offset = symbols_offset + 3U * LD_ELF64_SYM_SIZE;

    char section_names[96] = {0};
    size_t section_names_size = 1U;
    uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text");
    uint32_t data_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            far_nobits_target ? ".bss" : ".data");
    uint32_t rela_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".rela.text");
    uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");

    const size_t section_names_offset =
            strings_offset + sizeof(symbol_names);
    const size_t section_table_offset = test_elf_align(
            section_names_offset + section_names_size, 8U);
    const uint16_t section_count = 7U;
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, LD_ELF_EM_X86_64);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, 6U);

    memcpy(bytes + text_offset, text_bytes, sizeof(text_bytes));
    if (!far_nobits_target) {
        test_elf_write_u64(bytes + data_offset,
                           UINT64_C(0x1122334455667788));
    }
    memcpy(bytes + strings_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + section_names_offset, section_names,
           section_names_size);

    uint8_t *relocation = bytes + rela_offset;
    test_elf_write_u64(relocation, 3U);
    test_elf_write_u64(
            relocation + 8U,
            LD_ELF_RELA_INFO(1U, LD_ELF_R_X86_64_REX_GOTPCRELX));
    test_elf_write_u64(relocation + 16U, UINT64_MAX - 3U);

    uint8_t *symbols = bytes + symbols_offset;
    uint8_t *target = symbols + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(target, 1U);
    target[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_OBJECT);
    test_elf_write_u16(target + 6U, 2U);
    test_elf_write_u64(target + 8U, target_offset);
    test_elf_write_u64(target + 16U, 8U);
    uint8_t *start = target + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(start, 8U);
    start[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(start + 6U, 1U);
    test_elf_write_u64(start + 16U, sizeof(text_bytes));

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(sections + LD_ELF64_SHDR_SIZE, text_name,
                           LD_ELF_SHT_PROGBITS,
                           LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR,
                           text_offset, sizeof(text_bytes), 0U, 0U, 1U, 0U);
    test_elf_write_section(sections + 2U * LD_ELF64_SHDR_SIZE, data_name,
                           far_nobits_target ? LD_ELF_SHT_NOBITS
                                             : LD_ELF_SHT_PROGBITS,
                           LD_ELF_SHF_ALLOC | LD_ELF_SHF_WRITE, data_offset,
                           data_size, 0U, 0U, 8U, 0U);
    test_elf_write_section(
            sections + 3U * LD_ELF64_SHDR_SIZE, rela_name, LD_ELF_SHT_RELA,
            0U, rela_offset, LD_ELF64_RELA_SIZE, 4U, 1U, 8U,
            LD_ELF64_RELA_SIZE);
    test_elf_write_section(
            sections + 4U * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symbols_offset,
            3U * LD_ELF64_SYM_SIZE, 5U, 1U, 8U, LD_ELF64_SYM_SIZE);
    test_elf_write_section(sections + 5U * LD_ELF64_SHDR_SIZE, strtab_name,
                           LD_ELF_SHT_STRTAB, 0U, strings_offset,
                           sizeof(symbol_names), 0U, 0U, 1U, 0U);
    test_elf_write_section(
            sections + 6U * LD_ELF64_SHDR_SIZE, shstrtab_name,
            LD_ELF_SHT_STRTAB, 0U, section_names_offset,
            section_names_size, 0U, 0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static const uint8_t *output_section_contents(const uint8_t *image,
                                              size_t image_size,
                                              const uint8_t *section,
                                              size_t minimum_size) {
    assert(section != NULL);
    uint64_t offset = test_elf_read_u64(section + 24U);
    uint64_t size = test_elf_read_u64(section + 32U);
    assert(size >= minimum_size && offset <= image_size &&
           size <= image_size - offset);
    return image + (size_t) offset;
}

static uint8_t *make_riscv_align_object(bool corrupt_padding,
                                        size_t *result_size) {
    static const char symbol_names[] = "\0_start\0target";
    static const uint8_t text_bytes[] = {
            0x01U,
            0x00U,
            0x00U,
            0x00U,
            0x00U,
            0x00U,
    };
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t rela_offset = test_elf_align(
            text_offset + sizeof(text_bytes), 8U);
    const size_t relocation_count = 2U;
    const size_t symbols_offset =
            rela_offset + relocation_count * LD_ELF64_RELA_SIZE;
    const size_t symbol_count = 4U;
    const size_t strings_offset =
            symbols_offset + symbol_count * LD_ELF64_SYM_SIZE;

    char section_names[96] = {0};
    size_t section_names_size = 1U;
    uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text");
    uint32_t rela_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".rela.text");
    uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");
    const size_t section_names_offset =
            strings_offset + sizeof(symbol_names);
    const size_t section_table_offset = test_elf_align(
            section_names_offset + section_names_size, 8U);
    const uint16_t section_count = 6U;
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, LD_ELF_EM_RISCV);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u32(bytes + 48U, 1U); /* EF_RISCV_RVC */
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, 5U);

    memcpy(bytes + text_offset, text_bytes, sizeof(text_bytes));
    if (corrupt_padding) bytes[text_offset] = 0xffU;
    memcpy(bytes + strings_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + section_names_offset, section_names,
           section_names_size);

    uint8_t *relocation = bytes + rela_offset;
    test_elf_write_u64(relocation, 0U);
    test_elf_write_u64(
            relocation + 8U,
            LD_ELF_RELA_INFO(0U, LD_ELF_R_RISCV_ALIGN));
    test_elf_write_u64(relocation + 16U, 2U);
    relocation += LD_ELF64_RELA_SIZE;
    test_elf_write_u64(relocation, 2U);
    test_elf_write_u64(
            relocation + 8U,
            LD_ELF_RELA_INFO(1U, LD_ELF_R_RISCV_32));
    test_elf_write_u64(relocation + 16U, 6U);

    uint8_t *symbols = bytes + symbols_offset;
    uint8_t *section_symbol = symbols + LD_ELF64_SYM_SIZE;
    section_symbol[4] =
            LD_ELF_SYM_INFO(LD_ELF_STB_LOCAL, LD_ELF_STT_SECTION);
    test_elf_write_u16(section_symbol + 6U, 1U);
    uint8_t *start = section_symbol + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(start, 1U);
    start[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(start + 6U, 1U);
    test_elf_write_u64(start + 8U, 2U);
    test_elf_write_u64(start + 16U, 4U);
    uint8_t *target = start + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(target, 8U);
    target[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_NOTYPE);
    test_elf_write_u16(target + 6U, 1U);
    test_elf_write_u64(target + 8U, 6U);

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(
            sections + LD_ELF64_SHDR_SIZE, text_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR, text_offset,
            sizeof(text_bytes), 0U, 0U, 4U, 0U);
    test_elf_write_section(
            sections + 2U * LD_ELF64_SHDR_SIZE, rela_name,
            LD_ELF_SHT_RELA, 0U, rela_offset,
            relocation_count * LD_ELF64_RELA_SIZE, 3U, 1U, 8U,
            LD_ELF64_RELA_SIZE);
    test_elf_write_section(
            sections + 3U * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symbols_offset,
            symbol_count * LD_ELF64_SYM_SIZE, 4U, 2U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + 4U * LD_ELF64_SHDR_SIZE, strtab_name,
            LD_ELF_SHT_STRTAB, 0U, strings_offset, sizeof(symbol_names),
            0U, 0U, 1U, 0U);
    test_elf_write_section(
            sections + 5U * LD_ELF64_SHDR_SIZE, shstrtab_name,
            LD_ELF_SHT_STRTAB, 0U, section_names_offset,
            section_names_size, 0U, 0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static void test_riscv_align_link_relaxes_and_maps_offsets(void) {
    size_t object_size;
    uint8_t *object = make_riscv_align_object(false, &object_size);
    char object_path[] = "/tmp/nature-ld-riscv-align-object-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path = "/tmp/nature-ld-riscv-align-output";
    unlink(output_path);
    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_RISCV64;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = false;
    options.adhoc_codesign = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    assert(ld_add_input(&options, object_path) == LD_OK);
    assert(ld_link(&options) == LD_OK);
    assert(capture.count == 0U);
    ld_options_deinit(&options);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *text =
            test_elf_find_output_section(image, image_size, ".text");
    assert(text != NULL);
    assert(test_elf_read_u64(text + 32U) == 4U);
    uint64_t text_address = test_elf_read_u64(text + 16U);
    assert(test_elf_read_u64(image + 24U) == text_address);
    const uint8_t *contents =
            output_section_contents(image, image_size, text, 4U);
    assert(test_elf_read_u32(contents) == (uint32_t) (text_address + 4U));
    free(image);
    unlink(object_path);
    unlink(output_path);

    object = make_riscv_align_object(true, &object_size);
    char bad_path[] = "/tmp/nature-ld-riscv-align-bad-XXXXXX";
    write_fixture(bad_path, object, object_size);
    free(object);
    memset(&capture, 0, sizeof(capture));
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_RISCV64;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = false;
    options.adhoc_codesign = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    assert(ld_add_input(&options, bad_path) == LD_OK);
    assert(ld_link(&options) == LD_INVALID_INPUT);
    assert(capture.count > 0U);
    assert(strstr(capture.message, "non-NOP") != NULL);
    assert(access(output_path, F_OK) != 0);
    ld_options_deinit(&options);
    unlink(bad_path);
    unlink(output_path);
}

static void test_amd64_gotpcrelx_instruction_forms(void) {
    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_AMD64;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    ld_elf_context_t context;
    ld_elf_context_init(&context, &options);
    ld_elf_object_t object = {0};
    object.header.e_machine = LD_ELF_EM_X86_64;
    object.display_name = (char *) "gotpcrelx-forms.o";
    ld_elf_section_t section = {0};
    section.name = ".text";
    ld_elf_reloc_values_t values = {
            .place_address = 0x400003U,
            .symbol_address = 0x401000U,
            .symbol_name = "target",
    };

    uint8_t rex_mov[] = {0x48U, 0x8bU, 0x05U, 0U, 0U, 0U, 0U};
    ld_elf_relocation_t relocation = {
            .offset = 3U,
            .type = LD_ELF_R_X86_64_REX_GOTPCRELX,
            .addend = -4,
    };
    section.data = rex_mov;
    section.data_size = sizeof(rex_mov);
    section.header.sh_size = sizeof(rex_mov);
    assert(ld_elf_relocation_can_relax_x86_gotpcrelx(&section,
                                                     &relocation));
    assert(ld_elf_relocation_apply_x86_gotpcrelx(
                   &context, &object, &section, &relocation, rex_mov,
                   sizeof(rex_mov), relocation.offset, &values) == LD_OK);
    assert(rex_mov[1] == 0x8dU);
    assert(test_elf_read_u32(rex_mov + 3U) == 0x00000ff9U);

    uint8_t call[] = {0xffU, 0x15U, 0U, 0U, 0U, 0U};
    relocation.offset = 2U;
    relocation.type = LD_ELF_R_X86_64_GOTPCRELX;
    values.place_address = 0x400002U;
    section.data = call;
    section.data_size = sizeof(call);
    section.header.sh_size = sizeof(call);
    assert(ld_elf_relocation_can_relax_x86_gotpcrelx(&section,
                                                     &relocation));
    assert(ld_elf_relocation_apply_x86_gotpcrelx(
                   &context, &object, &section, &relocation, call,
                   sizeof(call), relocation.offset, &values) == LD_OK);
    assert(call[0] == 0x90U && call[1] == 0xe8U);
    assert(test_elf_read_u32(call + 2U) == 0x00000ffaU);

    uint8_t jump[] = {0xffU, 0x25U, 0U, 0U, 0U, 0U};
    section.data = jump;
    section.data_size = sizeof(jump);
    section.header.sh_size = sizeof(jump);
    assert(ld_elf_relocation_can_relax_x86_gotpcrelx(&section,
                                                     &relocation));
    assert(ld_elf_relocation_apply_x86_gotpcrelx(
                   &context, &object, &section, &relocation, jump,
                   sizeof(jump), relocation.offset, &values) == LD_OK);
    assert(jump[0] == 0x90U && jump[1] == 0xe9U);

    uint8_t unsupported[] = {0x48U, 0x03U, 0x05U, 0U, 0U, 0U, 0U};
    relocation.offset = 3U;
    relocation.type = LD_ELF_R_X86_64_REX_GOTPCRELX;
    section.data = unsupported;
    section.data_size = sizeof(unsupported);
    section.header.sh_size = sizeof(unsupported);
    assert(!ld_elf_relocation_can_relax_x86_gotpcrelx(&section,
                                                      &relocation));

    ld_elf_context_deinit(&context);
    ld_options_deinit(&options);
    assert(capture.count == 0U);
}

static void test_amd64_rex_gotpcrelx_link_relaxes_without_got(void) {
    size_t object_size;
    uint8_t *object =
            make_amd64_rex_gotpcrelx_object(false, &object_size);
    char object_path[] = "/tmp/nature-ld-gotpcrelx-object-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path = "/tmp/nature-ld-gotpcrelx-output";
    unlink(output_path);
    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_AMD64;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = false;
    options.adhoc_codesign = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    assert(ld_add_input(&options, object_path) == LD_OK);
    assert(ld_link(&options) == LD_OK);
    assert(capture.count == 0U);
    ld_options_deinit(&options);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *text =
            test_elf_find_output_section(image, image_size, ".text");
    const uint8_t *data =
            test_elf_find_output_section(image, image_size, ".data");
    assert(text != NULL && data != NULL);
    assert(test_elf_find_output_section(image, image_size, ".got") == NULL);
    const uint8_t *text_bytes =
            output_section_contents(image, image_size, text, 8U);
    assert(text_bytes[0] == 0x48U && text_bytes[1] == 0x8dU &&
           text_bytes[2] == 0x05U && text_bytes[7] == 0xc3U);
    uint64_t place = test_elf_read_u64(text + 16U) + 3U;
    uint64_t target = test_elf_read_u64(data + 16U);
    assert(test_elf_add_signed_u32(
                   place, test_elf_read_u32(text_bytes + 3U)) +
                   4U ==
           target);

    free(image);
    unlink(object_path);
    unlink(output_path);
}

static void test_amd64_rex_gotpcrelx_far_target_falls_back_to_got(void) {
    size_t object_size;
    uint8_t *object =
            make_amd64_rex_gotpcrelx_object(true, &object_size);
    char object_path[] = "/tmp/nature-ld-gotpcrelx-far-object-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path = "/tmp/nature-ld-gotpcrelx-far-output";
    unlink(output_path);
    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_AMD64;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = false;
    options.adhoc_codesign = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    assert(ld_add_input(&options, object_path) == LD_OK);
    assert(ld_link(&options) == LD_OK);
    assert(capture.count == 0U);
    ld_options_deinit(&options);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    assert(image_size < 1024U * 1024U);
    const uint8_t *text =
            test_elf_find_output_section(image, image_size, ".text");
    const uint8_t *got =
            test_elf_find_output_section(image, image_size, ".got");
    const uint8_t *bss =
            test_elf_find_output_section(image, image_size, ".bss");
    assert(text != NULL && got != NULL && bss != NULL);
    assert(test_elf_read_u64(got + 32U) == 8U);
    assert(test_elf_read_u64(bss + 32U) == UINT64_C(0x80000008));

    const uint8_t *text_bytes =
            output_section_contents(image, image_size, text, 8U);
    const uint8_t *got_bytes =
            output_section_contents(image, image_size, got, 8U);
    assert(text_bytes[0] == 0x48U && text_bytes[1] == 0x8bU &&
           text_bytes[2] == 0x05U && text_bytes[7] == 0xc3U);
    uint64_t place = test_elf_read_u64(text + 16U) + 3U;
    uint64_t got_address = test_elf_read_u64(got + 16U);
    uint64_t target_address = test_elf_read_u64(bss + 16U) +
                              UINT64_C(0x80000000);
    assert(test_elf_add_signed_u32(
                   place, test_elf_read_u32(text_bytes + 3U)) +
                   4U ==
           got_address);
    assert(test_elf_read_u64(got_bytes) == target_address);

    free(image);
    unlink(object_path);
    unlink(output_path);
}

