static void test_elf_amd64_weak_dynamic_link(void) {
    size_t object_size;
    uint8_t *object = make_test_elf_weak_dynamic_object(&object_size);
    char object_path[] = "/tmp/nature-ld-weak-dynamic-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path = "/tmp/nature-ld-weak-dynamic-output";
    unlink(output_path);
    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_AMD64;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = false;
    options.adhoc_codesign = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    assert(ld_add_input(&options, object_path) == LD_OK);
    assert(ld_link(&options) == LD_OK);
    assert(capture.count == 0U);
    ld_options_deinit(&options);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    assert(image_size >= LD_ELF64_EHDR_SIZE + LD_ELF64_PHDR_SIZE);
    uint64_t entry = test_elf_read_u64(image + 24U);
    assert(entry >= 0x400000U && entry - 0x400000U <= image_size - 4U);
    size_t entry_offset = (size_t) (entry - 0x400000U);
    /* S + A - P = 0 - 4 - entry for the weak undefined _DYNAMIC. */
    uint32_t expected = (uint32_t) (0U - 4U - entry);
    assert(test_elf_read_u32(image + entry_offset) == expected);
    free(image);
    unlink(object_path);
    unlink(output_path);
}

static void test_elf_amd64_relocations(void) {
    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_AMD64;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;

    ld_elf_context_t ctx;
    ld_elf_context_init(&ctx, &options);
    ld_elf_object_t object = {0};
    object.header.e_machine = LD_ELF_EM_X86_64;
    object.display_name = (char *) "amd64-relocation-test.o";
    ld_elf_section_t section = {0};
    section.name = ".text";
    ld_elf_relocation_t relocation = {0};
    ld_elf_reloc_scan_result_t scan = {0};
    ld_elf_reloc_values_t values = {0};
    uint8_t place[16] = {0};

    /* A weak undefined _DYNAMIC resolves to the linker-defined zero symbol.
     * The -4 addend is emitted by crt objects and must remain a valid signed
     * PC32 expression instead of tripping an unsigned-underflow check. */
    relocation.type = LD_ELF_R_X86_64_PC32;
    relocation.addend = -4;
    values.place_address = 0x400009U;
    values.symbol_address = 0U;
    values.symbol_name = "_DYNAMIC";
    assert(ld_elf_relocation_scan(&ctx, &object, &section, &relocation,
                                  false, &scan) == LD_OK);
    assert(scan.pc_relative && !scan.needs_got && !scan.needs_plt);
    assert(scan.write_width == 4U);
    memset(place, 0, sizeof(place));
    assert(ld_elf_relocation_apply(&ctx, &object, &section, &relocation,
                                   place, sizeof(place), &values) == LD_OK);
    assert(test_elf_read_u32(place) == 0xffbffff3U);
    assert(capture.count == 0U);

    /*
     * The context-free formula scan conservatively reports a GOT need. The
     * backend's instruction/target-aware allocation pass can now suppress it
     * and is covered by test_ld_elf_relax.c.
     */
    relocation.type = LD_ELF_R_X86_64_REX_GOTPCRELX;
    relocation.addend = -4;
    values.place_address = 0x400008U;
    values.got_entry_address = 0x403000U;
    values.symbol_name = "got_target";
    assert(ld_elf_relocation_scan(&ctx, &object, &section, &relocation,
                                  false, &scan) == LD_OK);
    assert(scan.needs_got && scan.pc_relative && !scan.needs_plt);
    assert(scan.write_width == 4U);
    memset(place, 0, sizeof(place));
    assert(ld_elf_relocation_apply(&ctx, &object, &section, &relocation,
                                   place, sizeof(place), &values) == LD_OK);
    assert(test_elf_read_u32(place) == 0x2ff4U);

    /* Local-exec TLS relocations use S + A - TP. */
    relocation.type = LD_ELF_R_X86_64_TPOFF32;
    relocation.addend = 0;
    values.symbol_address = 0x403000U;
    values.thread_pointer_address = 0x404000U;
    values.symbol_name = "tls_local";
    assert(ld_elf_relocation_scan(&ctx, &object, &section, &relocation,
                                  false, &scan) == LD_OK);
    assert(!scan.needs_got && !scan.pc_relative && scan.write_width == 4U);
    memset(place, 0, sizeof(place));
    assert(ld_elf_relocation_apply(&ctx, &object, &section, &relocation,
                                   place, sizeof(place), &values) == LD_OK);
    assert(test_elf_read_u32(place) == 0xfffff000U);

    relocation.type = LD_ELF_R_X86_64_TPOFF64;
    assert(ld_elf_relocation_scan(&ctx, &object, &section, &relocation,
                                  false, &scan) == LD_OK);
    assert(!scan.needs_got && !scan.pc_relative && scan.write_width == 8U);
    memset(place, 0, sizeof(place));
    assert(ld_elf_relocation_apply(&ctx, &object, &section, &relocation,
                                   place, sizeof(place), &values) == LD_OK);
    assert(test_elf_read_u64(place) == 0xfffffffffffff000ULL);

    /* Initial-exec style DTP offsets use S + A - the TLS block address. */
    relocation.type = LD_ELF_R_X86_64_DTPOFF32;
    relocation.addend = -0x20;
    values.symbol_address = 0x403120U;
    values.tls_block_address = 0x403000U;
    values.symbol_name = "tls_dtp";
    assert(ld_elf_relocation_scan(&ctx, &object, &section, &relocation,
                                  false, &scan) == LD_OK);
    assert(!scan.needs_got && !scan.pc_relative && scan.write_width == 4U);
    memset(place, 0, sizeof(place));
    assert(ld_elf_relocation_apply(&ctx, &object, &section, &relocation,
                                   place, sizeof(place), &values) == LD_OK);
    assert(test_elf_read_u32(place) == 0x100U);

    relocation.type = LD_ELF_R_X86_64_DTPOFF64;
    assert(ld_elf_relocation_scan(&ctx, &object, &section, &relocation,
                                  false, &scan) == LD_OK);
    assert(!scan.needs_got && !scan.pc_relative && scan.write_width == 8U);
    memset(place, 0, sizeof(place));
    assert(ld_elf_relocation_apply(&ctx, &object, &section, &relocation,
                                   place, sizeof(place), &values) == LD_OK);
    assert(test_elf_read_u64(place) == 0x100U);

    assert(capture.count == 0U);
    ld_elf_context_deinit(&ctx);
    ld_options_deinit(&options);
}

void test_ld_elf_reloc_x86_64(void) {
    test_elf_amd64_weak_dynamic_link();
    test_elf_amd64_relocations();
    test_elf_amd64_code_model_relocations();
}

static uint32_t test_elf_relro_entry_word(uint16_t machine) {
    switch (machine) {
        case LD_ELF_EM_X86_64:
            return 0x000000c3U;
        case LD_ELF_EM_AARCH64:
            return 0xd65f03c0U;
        case LD_ELF_EM_RISCV:
            return 0x00008067U;
    }
    assert(false);
    return 0U;
}

static uint32_t test_elf_relro_absolute_relocation(uint16_t machine) {
    switch (machine) {
        case LD_ELF_EM_X86_64:
            return LD_ELF_R_X86_64_64;
        case LD_ELF_EM_AARCH64:
            return LD_ELF_R_AARCH64_ABS64;
        case LD_ELF_EM_RISCV:
            return LD_ELF_R_RISCV_64;
    }
    assert(false);
    return 0U;
}

static const uint8_t *find_test_elf_program(const uint8_t *image,
                                            size_t image_size,
                                            uint32_t type,
                                            size_t *match_count) {
    assert(image_size >= LD_ELF64_EHDR_SIZE);
    uint64_t offset = test_elf_read_u64(image + 32U);
    uint16_t count = test_elf_read_u16(image + 56U);
    assert(offset <= image_size &&
           (uint64_t) count * LD_ELF64_PHDR_SIZE <= image_size - offset);
    const uint8_t *found = NULL;
    size_t matches = 0U;
    for (uint16_t i = 0; i < count; i++) {
        const uint8_t *program = image + (size_t) offset +
                                 (size_t) i * LD_ELF64_PHDR_SIZE;
        if (test_elf_read_u32(program) != type) continue;
        if (!found) found = program;
        matches++;
    }
    if (match_count) *match_count = matches;
    return found;
}

static int link_test_elf_relro_object(ld_arch_t arch, const char *input_path,
                                      const char *output_path,
                                      diagnostic_capture_t *capture) {
    unlink(output_path);
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = arch;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = capture;
    assert(ld_add_input(&options, input_path) == LD_OK);
    int result = ld_link(&options);
    ld_options_deinit(&options);
    return result;
}

static void test_relro_classification_and_plan(void) {
    const uint64_t write = LD_ELF_SHF_ALLOC | LD_ELF_SHF_WRITE;
    const uint64_t tls = write | LD_ELF_SHF_TLS;
    assert(ld_elf_relro_section_is_protected(
            ".tdata", LD_ELF_SHT_PROGBITS, tls, 8U));
    assert(!ld_elf_relro_section_is_protected(
            ".tbss", LD_ELF_SHT_NOBITS, tls, 8U));
    assert(ld_elf_relro_section_is_transparent(
            ".tbss", LD_ELF_SHT_NOBITS, tls, 8U));
    assert(ld_elf_relro_section_is_protected(
            ".init_array", LD_ELF_SHT_INIT_ARRAY, write, 8U));
    assert(ld_elf_relro_section_is_protected(
            ".data.rel.ro.local", LD_ELF_SHT_PROGBITS, write, 8U));
    assert(ld_elf_relro_section_is_protected(
            ".bss.rel.ro.foo", LD_ELF_SHT_PROGBITS, write, 8U));
    assert(ld_elf_relro_section_is_protected(
            ".got", LD_ELF_SHT_PROGBITS, write, 8U));
    assert(!ld_elf_relro_section_is_protected(
            ".got.plt", LD_ELF_SHT_PROGBITS, write, 8U));
    assert(!ld_elf_relro_section_is_protected(
            ".data", LD_ELF_SHT_PROGBITS, write, 8U));

    ld_elf_relro_plan_t plan;
    ld_elf_relro_plan_init(&plan);
    assert(ld_elf_relro_add_section(
                   &plan, ".tdata", LD_ELF_SHT_PROGBITS, tls,
                   0x4000U, 0x404000U, 8U, 8U) == LD_ELF_RELRO_OK);
    assert(ld_elf_relro_add_section(
                   &plan, ".init_array", LD_ELF_SHT_INIT_ARRAY, write,
                   0x4008U, 0x404008U, 8U, 8U) == LD_ELF_RELRO_OK);
    assert(ld_elf_relro_add_section(
                   &plan, ".got", LD_ELF_SHT_PROGBITS, write,
                   0x4020U, 0x404020U, 8U, 8U) == LD_ELF_RELRO_OK);
    uint64_t next_file = 0U;
    uint64_t next_address = 0U;
    assert(ld_elf_relro_finalize(
                   &plan, 0x1000U, 0x4028U, 0x404028U,
                   &next_file, &next_address) == LD_ELF_RELRO_OK);
    assert(plan.present && plan.finalized);
    assert(plan.file_offset == 0x4000U && plan.address == 0x404000U);
    assert(plan.file_size == 0x28U && plan.memory_size == 0x1000U);
    assert(plan.protection_end == 0x405000U);
    assert(next_file == 0x5000U && next_address == 0x405000U);
    assert(ld_elf_relro_finalize(
                   &plan, 0x1000U, next_file, next_address,
                   &next_file, &next_address) == LD_ELF_RELRO_FINALIZED);
    assert(ld_elf_relro_add_section(
                   &plan, ".got", LD_ELF_SHT_PROGBITS, write,
                   0x5000U, 0x405000U, 8U, 8U) ==
           LD_ELF_RELRO_FINALIZED);
}

static void test_relro_plan_failures(void) {
    const uint64_t write = LD_ELF_SHF_ALLOC | LD_ELF_SHF_WRITE;
    ld_elf_relro_plan_t plan;
    uint64_t next_file;
    uint64_t next_address;

    ld_elf_relro_plan_init(&plan);
    assert(ld_elf_relro_finalize(
                   &plan, 3U, 0U, 0U, &next_file, &next_address) ==
           LD_ELF_RELRO_INVALID_ALIGNMENT);

    ld_elf_relro_plan_init(&plan);
    assert(ld_elf_relro_add_section(
                   &plan, ".data", LD_ELF_SHT_PROGBITS, write,
                   0U, 0U, 8U, 8U) ==
           LD_ELF_RELRO_SECTION_NOT_PROTECTED);
    assert(ld_elf_relro_add_section(
                   &plan, ".got", LD_ELF_SHT_PROGBITS, write,
                   UINT64_MAX - 3U, 0x400000U, 8U, 8U) ==
           LD_ELF_RELRO_LAYOUT_OVERFLOW);

    ld_elf_relro_plan_init(&plan);
    assert(ld_elf_relro_add_section(
                   &plan, ".got", LD_ELF_SHT_PROGBITS, write,
                   0x4008U, 0x404000U, 8U, 8U) == LD_ELF_RELRO_OK);
    assert(ld_elf_relro_finalize(
                   &plan, 0x1000U, 0x4010U, 0x404008U,
                   &next_file, &next_address) ==
           LD_ELF_RELRO_INCONGRUENT_LAYOUT);

    ld_elf_relro_plan_init(&plan);
    assert(ld_elf_relro_add_section(
                   &plan, ".got", LD_ELF_SHT_PROGBITS, write,
                   0x4000U, 0x404000U, 16U, 16U) == LD_ELF_RELRO_OK);
    assert(ld_elf_relro_add_section(
                   &plan, ".data.rel.ro", LD_ELF_SHT_PROGBITS, write,
                   0x4008U, 0x404008U, 8U, 8U) ==
           LD_ELF_RELRO_NON_MONOTONIC_LAYOUT);

    ld_elf_relro_plan_init(&plan);
    assert(ld_elf_relro_finalize(
                   &plan, 0x1000U, 0x123U, 0x456U,
                   &next_file, &next_address) == LD_ELF_RELRO_OK);
    assert(!plan.present && plan.finalized);
    assert(next_file == 0x123U && next_address == 0x456U);
}

static void test_output_without_relro_has_no_header(void) {
    size_t object_size;
    uint8_t *object = make_test_elf_relro_object(
            LD_ELF_EM_AARCH64, false, &object_size);
    char object_path[] = "/tmp/nature-ld-no-relro-object-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);
    static const char output_path[] = "/tmp/nature-ld-no-relro-output";
    diagnostic_capture_t capture = {0};
    assert(link_test_elf_relro_object(
                   LD_ARCH_ARM64, object_path, output_path, &capture) ==
           LD_OK);
    assert(capture.count == 0U);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    size_t count;
    assert(find_test_elf_program(
                   image, image_size, LD_ELF_PT_GNU_RELRO, &count) == NULL);
    assert(count == 0U);
    assert(test_elf_read_u16(image + 56U) == 4U);
    free(image);
    unlink(object_path);
    unlink(output_path);
}

void test_ld_elf_relro(void) {
    test_relro_classification_and_plan();
    test_relro_plan_failures();
    test_relro_output_for_arch(LD_ARCH_ARM64, LD_ELF_EM_AARCH64,
                               "aarch64");
    test_relro_output_for_arch(LD_ARCH_AMD64, LD_ELF_EM_X86_64,
                               "x86-64");
    test_relro_output_for_arch(LD_ARCH_RISCV64, LD_ELF_EM_RISCV,
                               "riscv64");
    test_output_without_relro_has_no_header();
}

static void test_elf_riscv_uleb_encoder(void) {
    size_t width = SIZE_MAX;
    uint8_t one_byte[] = {0x19U};
    assert(ld_elf_riscv_uleb_apply_pair(
                   one_byte, sizeof(one_byte), 0x1001cU, 0,
                   0x10003U, 0, &width) == LD_ELF_RISCV_ULEB_OK);
    assert(width == 1U && one_byte[0] == 0x19U);

    uint8_t two_bytes[] = {0x9eU, 0x02U};
    assert(ld_elf_riscv_uleb_apply_pair(
                   two_bytes, sizeof(two_bytes), 0x1011eU, 0,
                   0x10000U, 0, &width) == LD_ELF_RISCV_ULEB_OK);
    assert(width == 2U && two_bytes[0] == 0x9eU &&
           two_bytes[1] == 0x02U);

    uint8_t with_addends[] = {0x80U, 0x00U};
    assert(ld_elf_riscv_uleb_apply_pair(
                   with_addends, sizeof(with_addends), 0x100U, 5,
                   0x80U, 1, &width) == LD_ELF_RISCV_ULEB_OK);
    assert(width == 2U && with_addends[0] == 0x86U &&
           with_addends[1] == 0x01U);

    uint8_t standalone = 0x00U;
    assert(ld_elf_riscv_uleb_apply(
                   &standalone, 1U, false, 0x105U, 0,
                   &width) == LD_ELF_RISCV_ULEB_OK);
    assert(width == 1U && standalone == 0x05U);
    assert(ld_elf_riscv_uleb_apply(
                   &standalone, 1U, true, 2U, 0,
                   &width) == LD_ELF_RISCV_ULEB_OK);
    assert(width == 1U && standalone == 0x03U);

    uint8_t maximum[10];
    memset(maximum, 0x80, sizeof(maximum));
    maximum[9] = 0U;
    assert(ld_elf_riscv_uleb_apply_pair(
                   maximum, sizeof(maximum), UINT64_MAX, 0, 0U, 0,
                   &width) == LD_ELF_RISCV_ULEB_OK);
    assert(width == 10U);
    for (size_t i = 0; i < 9U; i++) assert(maximum[i] == 0xffU);
    assert(maximum[9] == 0x01U);
}

static void test_elf_riscv_uleb_encoder_failures(void) {
    size_t width = SIZE_MAX;
    uint8_t truncated[] = {0x80U};
    uint8_t truncated_copy[sizeof(truncated)];
    memcpy(truncated_copy, truncated, sizeof(truncated));
    assert(ld_elf_riscv_uleb_apply_pair(
                   truncated, sizeof(truncated), 1U, 0, 0U, 0,
                   &width) == LD_ELF_RISCV_ULEB_TRUNCATED);
    assert(width == 0U &&
           memcmp(truncated, truncated_copy, sizeof(truncated)) == 0);

    uint8_t field_overflow[10];
    memset(field_overflow, 0x80, sizeof(field_overflow));
    field_overflow[9] = 0x02U;
    uint8_t field_overflow_copy[sizeof(field_overflow)];
    memcpy(field_overflow_copy, field_overflow, sizeof(field_overflow));
    assert(ld_elf_riscv_uleb_apply_pair(
                   field_overflow, sizeof(field_overflow), 1U, 0, 0U, 0,
                   &width) == LD_ELF_RISCV_ULEB_FIELD_OVERFLOW);
    assert(width == 0U &&
           memcmp(field_overflow, field_overflow_copy,
                  sizeof(field_overflow)) == 0);

    uint8_t byte = 0x55U;
    assert(ld_elf_riscv_uleb_apply_pair(
                   &byte, 1U, UINT64_MAX, 1, 0U, 0,
                   &width) == LD_ELF_RISCV_ULEB_SET_OVERFLOW);
    assert(width == 1U && byte == 0x55U);
    assert(ld_elf_riscv_uleb_apply_pair(
                   &byte, 1U, 0U, -1, 0U, 0,
                   &width) == LD_ELF_RISCV_ULEB_SET_OVERFLOW);
    assert(byte == 0x55U);
    assert(ld_elf_riscv_uleb_apply_pair(
                   &byte, 1U, 1U, 0, 0U, 1,
                   &width) == LD_ELF_RISCV_ULEB_SUB_OVERFLOW);
    assert(byte == 0x55U);
    assert(ld_elf_riscv_uleb_apply_pair(
                   &byte, 1U, 1U, 0, 2U, 0,
                   &width) == LD_ELF_RISCV_ULEB_OK);
    assert(byte == 0x7fU);
    byte = 0x55U;
    assert(ld_elf_riscv_uleb_apply_pair(
                   &byte, 1U, 128U, 0, 0U, 0,
                   &width) == LD_ELF_RISCV_ULEB_OK);
    assert(width == 1U && byte == 0U);
    assert(ld_elf_riscv_uleb_apply_pair(
                   NULL, 0U, 0U, 0, 0U, 0,
                   &width) == LD_ELF_RISCV_ULEB_INVALID_ARGUMENT);
}

static ld_elf_relocation_t test_elf_riscv_uleb_relocation(
        uint32_t type, uint64_t offset, uint32_t symbol_index,
        uint32_t relocation_section_index) {
    ld_elf_relocation_t relocation = {
            .offset = offset,
            .symbol_index = symbol_index,
            .type = type,
            .relocation_section_index = relocation_section_index,
            .x86_tls_pair_index = SIZE_MAX,
    };
    return relocation;
}

static void test_elf_riscv_uleb_pair_diagnostics(void) {
    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_RISCV64;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    ld_elf_context_t ctx;
    ld_elf_context_init(&ctx, &options);
    ld_elf_object_t object = {0};
    object.header.e_machine = LD_ELF_EM_RISCV;
    object.display_name = (char *) "uleb-apply.o";
    ld_elf_section_t section = {0};
    section.name = ".gcc_except_table";
    ld_elf_relocation_t set = test_elf_riscv_uleb_relocation(
            LD_ELF_R_RISCV_SET_ULEB128, 2U, 1U, 7U);
    ld_elf_relocation_t sub = test_elf_riscv_uleb_relocation(
            LD_ELF_R_RISCV_SUB_ULEB128, 2U, 2U, 7U);
    ld_elf_reloc_values_t set_values = {
            .symbol_address = 0x1001cU,
            .symbol_name = "set_target",
    };
    ld_elf_reloc_values_t sub_values = {
            .symbol_address = 0x10003U,
            .symbol_name = "sub_target",
    };
    uint8_t field = 0U;
    assert(ld_elf_relocation_apply_riscv_uleb_pair(
                   &ctx, &object, &section, &set, &sub, &field, 1U,
                   &set_values, &sub_values) == LD_OK);
    assert(field == 0x19U && capture.count == 0U);

    field = 0x55U;
    set_values.symbol_address = 1U;
    sub_values.symbol_address = 2U;
    assert(ld_elf_relocation_apply_riscv_uleb_pair(
                   &ctx, &object, &section, &set, &sub, &field, 1U,
                   &set_values, &sub_values) == LD_OK);
    assert(field == 0x7fU && capture.count == 0U);

    capture = (diagnostic_capture_t) {0};
    field = 0x55U;
    sub.offset = 3U;
    assert(ld_elf_relocation_apply_riscv_uleb_pair(
                   &ctx, &object, &section, &set, &sub, &field, 1U,
                   &set_values, &sub_values) == LD_RELOCATION_ERROR);
    assert(field == 0x55U && strstr(capture.message, "invalid"));

    ld_elf_context_deinit(&ctx);
    ld_options_deinit(&options);
}

static uint8_t *test_elf_make_riscv_uleb_fixture(
        test_elf_riscv_uleb_fixture_mode_t mode, size_t *result_size) {
    char symbol_names[64] = {0};
    size_t symbol_name_cursor = 1U;
    uint32_t set_symbol_name = test_elf_append_name(
            symbol_names, sizeof(symbol_names), &symbol_name_cursor,
            ".Lset");
    uint32_t sub_symbol_name = test_elf_append_name(
            symbol_names, sizeof(symbol_names), &symbol_name_cursor,
            ".Lsub");
    uint32_t start_symbol_name = test_elf_append_name(
            symbol_names, sizeof(symbol_names), &symbol_name_cursor,
            "_start");

    char section_names[128] = {0};
    size_t section_name_cursor = 1U;
    uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_name_cursor,
            ".text");
    uint32_t except_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_name_cursor,
            ".gcc_except_table");
    uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_name_cursor,
            ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_name_cursor,
            ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_name_cursor,
            ".shstrtab");
    uint32_t rela_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_name_cursor,
            ".rela.gcc_except_table");

    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t text_size = 256U;
    const size_t except_offset = text_offset + text_size;
    const size_t symtab_offset = test_elf_align(except_offset + 1U, 8U);
    const size_t symbol_count = 4U;
    const size_t strtab_offset =
            symtab_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t shstrtab_offset = strtab_offset + sizeof(symbol_names);
    const size_t rela_offset =
            test_elf_align(shstrtab_offset + sizeof(section_names), 8U);
    size_t relocation_count =
            mode == TEST_ELF_RISCV_ULEB_MISSING_SUB ? 1U : 2U;
    const size_t section_table_offset =
            rela_offset + relocation_count * LD_ELF64_RELA_SIZE;
    const uint16_t section_count = 7U;
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, LD_ELF_EM_RISCV);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, 5U);

    test_elf_write_u32(bytes + text_offset, 0x00000513U);
    test_elf_write_u32(bytes + text_offset + 4U, 0x00008067U);
    bytes[except_offset] =
            mode == TEST_ELF_RISCV_ULEB_TRUNCATED ? 0x80U : 0x19U;
    memcpy(bytes + strtab_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + shstrtab_offset, section_names, sizeof(section_names));

    uint64_t set_value = 0x1cU;
    uint64_t sub_value = 0x03U;
    uint8_t *symbols = bytes + symtab_offset;
    uint8_t *set_symbol = symbols + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(set_symbol, set_symbol_name);
    set_symbol[4] = LD_ELF_SYM_INFO(LD_ELF_STB_LOCAL, LD_ELF_STT_NOTYPE);
    test_elf_write_u16(set_symbol + 6U, 1U);
    test_elf_write_u64(set_symbol + 8U, set_value);
    uint8_t *sub_symbol = set_symbol + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(sub_symbol, sub_symbol_name);
    sub_symbol[4] = LD_ELF_SYM_INFO(LD_ELF_STB_LOCAL, LD_ELF_STT_NOTYPE);
    test_elf_write_u16(sub_symbol + 6U, 1U);
    test_elf_write_u64(sub_symbol + 8U, sub_value);
    uint8_t *start_symbol = sub_symbol + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(start_symbol, start_symbol_name);
    start_symbol[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(start_symbol + 6U, 1U);
    test_elf_write_u64(start_symbol + 16U, 8U);

    uint8_t *rela = bytes + rela_offset;
    uint32_t first_type = mode == TEST_ELF_RISCV_ULEB_REVERSE
                                  ? LD_ELF_R_RISCV_SUB_ULEB128
                                  : LD_ELF_R_RISCV_SET_ULEB128;
    uint32_t first_symbol = mode == TEST_ELF_RISCV_ULEB_REVERSE ? 2U : 1U;
    test_elf_write_u64(rela, 0U);
    test_elf_write_u64(rela + 8U,
                       LD_ELF_RELA_INFO(first_symbol, first_type));
    if (relocation_count == 2U) {
        uint32_t second_type = mode == TEST_ELF_RISCV_ULEB_REVERSE
                                       ? LD_ELF_R_RISCV_SET_ULEB128
                                       : LD_ELF_R_RISCV_SUB_ULEB128;
        uint32_t second_symbol =
                mode == TEST_ELF_RISCV_ULEB_REVERSE ? 1U : 2U;
        test_elf_write_u64(rela + LD_ELF64_RELA_SIZE, 0U);
        test_elf_write_u64(rela + LD_ELF64_RELA_SIZE + 8U,
                           LD_ELF_RELA_INFO(second_symbol, second_type));
    }

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(sections + LD_ELF64_SHDR_SIZE, text_name,
                           LD_ELF_SHT_PROGBITS,
                           LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR,
                           text_offset, text_size, 0U, 0U, 4U, 0U);
    test_elf_write_section(sections + 2U * LD_ELF64_SHDR_SIZE, except_name,
                           LD_ELF_SHT_PROGBITS, LD_ELF_SHF_ALLOC,
                           except_offset, 1U, 0U, 0U, 1U, 0U);
    test_elf_write_section(sections + 3U * LD_ELF64_SHDR_SIZE, symtab_name,
                           LD_ELF_SHT_SYMTAB, 0U, symtab_offset,
                           symbol_count * LD_ELF64_SYM_SIZE, 4U, 3U, 8U,
                           LD_ELF64_SYM_SIZE);
    test_elf_write_section(sections + 4U * LD_ELF64_SHDR_SIZE, strtab_name,
                           LD_ELF_SHT_STRTAB, 0U, strtab_offset,
                           sizeof(symbol_names), 0U, 0U, 1U, 0U);
    test_elf_write_section(sections + 5U * LD_ELF64_SHDR_SIZE,
                           shstrtab_name, LD_ELF_SHT_STRTAB, 0U,
                           shstrtab_offset, sizeof(section_names), 0U, 0U,
                           1U, 0U);
    test_elf_write_section(sections + 6U * LD_ELF64_SHDR_SIZE, rela_name,
                           LD_ELF_SHT_RELA, LD_ELF_SHF_INFO_LINK,
                           rela_offset,
                           relocation_count * LD_ELF64_RELA_SIZE, 3U, 2U,
                           8U, LD_ELF64_RELA_SIZE);

    *result_size = size;
    return bytes;
}

static int test_elf_link_riscv_uleb_fixture(
        test_elf_riscv_uleb_fixture_mode_t mode, const char *output_path,
        diagnostic_capture_t *capture) {
    size_t fixture_size;
    uint8_t *fixture = test_elf_make_riscv_uleb_fixture(
            mode, &fixture_size);
    char input_path[] = "/tmp/nature-ld-riscv-uleb-input-XXXXXX";
    write_fixture(input_path, fixture, fixture_size);
    free(fixture);
    unlink(output_path);

    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_RISCV64;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = false;
    options.adhoc_codesign = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = capture;
    assert(ld_add_input(&options, input_path) == LD_OK);
    int status = ld_link(&options);
    ld_options_deinit(&options);
    unlink(input_path);
    return status;
}

static void test_elf_riscv_uleb_full_link(void) {
    char output_path[] = "/tmp/nature-ld-riscv-uleb-output-XXXXXX";
    int output_fd = mkstemp(output_path);
    assert(output_fd >= 0 && close(output_fd) == 0);
    unlink(output_path);

    diagnostic_capture_t capture = {0};
    assert(test_elf_link_riscv_uleb_fixture(
                   TEST_ELF_RISCV_ULEB_VALID, output_path, &capture) == LD_OK);
    assert(capture.count == 0U);
    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    const uint8_t *header = test_elf_find_output_section(
            image, image_size, ".gcc_except_table");
    assert(header != NULL);
    uint64_t file_offset = test_elf_read_u64(header + 24U);
    uint64_t section_size = test_elf_read_u64(header + 32U);
    assert(section_size == 1U && file_offset < image_size);
    assert(image[file_offset] == 0x19U);
    free(image);
    unlink(output_path);

    capture = (diagnostic_capture_t) {0};
    assert(test_elf_link_riscv_uleb_fixture(
                   TEST_ELF_RISCV_ULEB_MISSING_SUB, output_path,
                   &capture) == LD_OK);
    image = read_test_fixture(output_path, &image_size, NULL);
    header = test_elf_find_output_section(
            image, image_size, ".gcc_except_table");
    assert(header != NULL);
    file_offset = test_elf_read_u64(header + 24U);
    assert(file_offset < image_size && image[file_offset] == 0x3cU);
    free(image);
    unlink(output_path);

    capture = (diagnostic_capture_t) {0};
    assert(test_elf_link_riscv_uleb_fixture(
                   TEST_ELF_RISCV_ULEB_REVERSE, output_path,
                   &capture) == LD_OK);
    image = read_test_fixture(output_path, &image_size, NULL);
    header = test_elf_find_output_section(
            image, image_size, ".gcc_except_table");
    assert(header != NULL);
    file_offset = test_elf_read_u64(header + 24U);
    assert(file_offset < image_size && image[file_offset] == 0x3cU);
    free(image);
    unlink(output_path);

    capture = (diagnostic_capture_t) {0};
    assert(test_elf_link_riscv_uleb_fixture(
                   TEST_ELF_RISCV_ULEB_TRUNCATED, output_path,
                   &capture) == LD_RELOCATION_ERROR);
    assert(strstr(capture.message, "truncated") &&
           access(output_path, F_OK) != 0);
}

void test_ld_elf_riscv_uleb(void) {
    test_elf_riscv_uleb_encoder();
    test_elf_riscv_uleb_encoder_failures();
    test_elf_riscv_uleb_pair_diagnostics();
    test_elf_riscv_uleb_full_link();
}

static void test_script_parser(void) {
    static const char source[] =
            "/* GNU ld script */\n"
            "OUTPUT_FORMAT(elf64-littleaarch64)\n"
            "OUTPUT_ARCH(aarch64);\n"
            "SEARCH_DIR(\"=/usr/lib\")\n"
            "GROUP ( first.a, AS_NEEDED ( -lm 'second path.a' ) )\n"
            "INPUT(../third\\ path.o)\n";
    ld_elf_script_t script;
    ld_elf_script_error_t error;
    assert(ld_elf_script_parse((const uint8_t *) source,
                               sizeof(source) - 1U, LD_ARCH_ARM64,
                               &script, &error) == LD_ELF_SCRIPT_OK);
    assert(error.message == NULL);
    assert(script.search_dir_count == 1U);
    assert(strcmp(script.search_dirs[0], "=/usr/lib") == 0);
    assert(script.input_count == 4U);
    assert(strcmp(script.inputs[0].path, "first.a") == 0);
    assert(!script.inputs[0].as_needed);
    assert(strcmp(script.inputs[1].path, "-lm") == 0);
    assert(script.inputs[1].as_needed);
    assert(strcmp(script.inputs[2].path, "second path.a") == 0);
    assert(script.inputs[2].as_needed);
    assert(strcmp(script.inputs[3].path, "../third path.o") == 0);
    assert(!script.inputs[3].as_needed);
    ld_elf_script_deinit(&script);

    static const char riscv_source[] =
            "OUTPUT_FORMAT(elf64-littleriscv) GROUP(libc.a)";
    assert(ld_elf_script_parse((const uint8_t *) riscv_source,
                               sizeof(riscv_source) - 1U,
                               LD_ARCH_RISCV64, &script,
                               &error) == LD_ELF_SCRIPT_OK);
    assert(script.input_count == 1U);
    ld_elf_script_deinit(&script);
}

static void expect_script_error(const uint8_t *source, size_t size,
                                ld_arch_t arch,
                                ld_elf_script_result_t expected,
                                const char *message) {
    ld_elf_script_t script;
    ld_elf_script_error_t error;
    assert(ld_elf_script_parse(source, size, arch, &script, &error) ==
           expected);
    assert(error.message != NULL);
    assert(strstr(error.message, message) != NULL);
    assert(script.inputs == NULL && script.input_count == 0U);
    assert(script.search_dirs == NULL && script.search_dir_count == 0U);
}

static void test_script_parser_failures(void) {
    static const char empty[] = " /* only a comment */ ";
    expect_script_error((const uint8_t *) empty, sizeof(empty) - 1U,
                        LD_ARCH_ARM64, LD_ELF_SCRIPT_INVALID,
                        "empty linker script");

    static const char bad_comment[] = "/* unterminated";
    expect_script_error((const uint8_t *) bad_comment,
                        sizeof(bad_comment) - 1U, LD_ARCH_ARM64,
                        LD_ELF_SCRIPT_INVALID, "unterminated block comment");

    static const char bad_command[] = "SECTIONS { }";
    expect_script_error((const uint8_t *) bad_command,
                        sizeof(bad_command) - 1U, LD_ARCH_ARM64,
                        LD_ELF_SCRIPT_INVALID, "unsupported");

    static const char missing_close[] = "GROUP(one.a";
    expect_script_error((const uint8_t *) missing_close,
                        sizeof(missing_close) - 1U, LD_ARCH_ARM64,
                        LD_ELF_SCRIPT_INVALID, "unterminated");

    static const char wrong_arch[] =
            "OUTPUT_FORMAT(elf64-x86-64) GROUP(one.a)";
    expect_script_error((const uint8_t *) wrong_arch,
                        sizeof(wrong_arch) - 1U, LD_ARCH_ARM64,
                        LD_ELF_SCRIPT_UNSUPPORTED_ARCH, "does not match");

    static const uint8_t embedded_nul[] = {
            'G', 'R', 'O', 'U', 'P', '(', 'a', '\0', 'b', ')'};
    expect_script_error(embedded_nul, sizeof(embedded_nul), LD_ARCH_ARM64,
                        LD_ELF_SCRIPT_INVALID, "NUL byte");
}

static void write_named_fixture(const char *path, const void *bytes,
                                size_t size) {
    int fd = open(path, O_CREAT | O_TRUNC | O_WRONLY, 0600);
    assert(fd >= 0);
    size_t offset = 0U;
    while (offset < size) {
        ssize_t count = write(fd, (const uint8_t *) bytes + offset,
                              size - offset);
        assert(count > 0);
        offset += (size_t) count;
    }
    assert(close(fd) == 0);
}

static void test_script_relative_and_library_inputs(void) {
    char directory[] = "/tmp/nature-ld-elf-script-XXXXXX";
    assert(mkdtemp(directory) != NULL);
    char object_path[PATH_MAX];
    char script_path[PATH_MAX];
    char output_path[PATH_MAX];
    int length = snprintf(object_path, sizeof(object_path), "%s/libentry.a",
                          directory);
    assert(length > 0 && (size_t) length < sizeof(object_path));
    length = snprintf(script_path, sizeof(script_path), "%s/libwrapper.a",
                      directory);
    assert(length > 0 && (size_t) length < sizeof(script_path));
    length = snprintf(output_path, sizeof(output_path), "%s/output",
                      directory);
    assert(length > 0 && (size_t) length < sizeof(output_path));

    size_t object_size;
    uint8_t *object = make_test_elf_object(
            LD_ELF_EM_AARCH64, false, false, &object_size);
    write_named_fixture(object_path, object, object_size);
    free(object);

    static const char source[] =
            "OUTPUT_FORMAT(elf64-littleaarch64)\n"
            "SEARCH_DIR(.)\n"
            "GROUP(-lentry)\n";
    write_named_fixture(script_path, source, sizeof(source) - 1U);

    diagnostic_capture_t capture = {0};
    const char *inputs[] = {script_path};
    assert(link_test_elf_inputs(output_path, inputs, 1U, &capture) == LD_OK);
    assert(capture.count == 0U);
    assert(read_test_elf_entry_word(output_path) == UINT32_C(0xd65f03c0));

    unlink(output_path);
    unlink(script_path);
    unlink(object_path);
    assert(rmdir(directory) == 0);
}

static void test_script_cycle_and_missing_input(void) {
    char cycle_path[] = "/tmp/nature-ld-elf-script-cycle-XXXXXX";
    int fd = mkstemp(cycle_path);
    assert(fd >= 0);
    assert(close(fd) == 0);
    char source[PATH_MAX + 32U];
    int length = snprintf(source, sizeof(source), "GROUP(%s)\n", cycle_path);
    assert(length > 0 && (size_t) length < sizeof(source));
    write_named_fixture(cycle_path, source, (size_t) length);

    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_ARM64;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    ld_elf_context_t context;
    ld_elf_context_init(&context, &options);
    assert(ld_elf_load_input(&context, cycle_path) == LD_INVALID_INPUT);
    assert(capture.count == 1U);
    assert(strstr(capture.message, "script cycle") != NULL);
    ld_elf_context_deinit(&context);
    ld_options_deinit(&options);
    unlink(cycle_path);

    char missing_path[] = "/tmp/nature-ld-elf-script-missing-XXXXXX";
    fd = mkstemp(missing_path);
    assert(fd >= 0);
    static const char missing[] = "INPUT(no-such-input.o)\n";
    assert(write(fd, missing, sizeof(missing) - 1U) ==
           (ssize_t) (sizeof(missing) - 1U));
    assert(close(fd) == 0);

    memset(&capture, 0, sizeof(capture));
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_ARM64;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    ld_elf_context_init(&context, &options);
    assert(ld_elf_load_input(&context, missing_path) == LD_IO_ERROR);
    assert(capture.count == 1U);
    assert(strstr(capture.message, "no-such-input.o") != NULL);
    assert(strstr(capture.message, missing_path) != NULL);
    ld_elf_context_deinit(&context);
    ld_options_deinit(&options);
    unlink(missing_path);
}

void test_ld_elf_script(void) {
    test_script_parser();
    test_script_parser_failures();
    test_script_relative_and_library_inputs();
    test_script_cycle_and_missing_input();
}

static void test_elf_cie_deduplication(void) {
    static const uint8_t bytes_a[] = {1U, 2U, 3U, 4U};
    static const uint8_t bytes_a_copy[] = {1U, 2U, 3U, 4U};
    static const uint8_t bytes_b[] = {1U, 2U, 3U, 5U};
    static const int target_a = 1;
    static const int target_b = 2;
    const ld_elf_cie_relocation_t base_relocation = {
            .offset = 8U,
            .type = 2U,
            .addend = -4,
            .target_namespace = &target_a,
            .target_index = 7U,
    };
    ld_elf_cie_relocation_t relocation_offset = base_relocation;
    relocation_offset.offset++;
    ld_elf_cie_relocation_t relocation_type = base_relocation;
    relocation_type.type++;
    ld_elf_cie_relocation_t relocation_addend = base_relocation;
    relocation_addend.addend++;
    ld_elf_cie_relocation_t relocation_namespace = base_relocation;
    relocation_namespace.target_namespace = &target_b;
    ld_elf_cie_relocation_t relocation_index = base_relocation;
    relocation_index.target_index++;
    const ld_elf_cie_entry_t entries[] = {
            {bytes_a, sizeof(bytes_a), &base_relocation, 1U},
            {bytes_a_copy, sizeof(bytes_a_copy), &base_relocation, 1U},
            {bytes_b, sizeof(bytes_b), &base_relocation, 1U},
            {bytes_a, sizeof(bytes_a), &relocation_offset, 1U},
            {bytes_a, sizeof(bytes_a), &relocation_type, 1U},
            {bytes_a, sizeof(bytes_a), &relocation_addend, 1U},
            {bytes_a, sizeof(bytes_a), &relocation_namespace, 1U},
            {bytes_a, sizeof(bytes_a), &relocation_index, 1U},
            {bytes_a, sizeof(bytes_a), NULL, 0U},
            {bytes_a_copy, sizeof(bytes_a_copy), NULL, 0U},
    };
    const size_t expected[] = {0U, 0U, 2U, 3U, 4U,
                               5U, 6U, 7U, 8U, 8U};
    size_t canonical[sizeof(entries) / sizeof(entries[0])];
    memset(canonical, 0xa5, sizeof(canonical));
    size_t error_index = 0U;
    assert(ld_elf_cie_deduplicate(
                   entries, sizeof(entries) / sizeof(entries[0]), canonical,
                   &error_index) == LD_ELF_CIE_OK);
    assert(error_index == SIZE_MAX);
    assert(memcmp(canonical, expected, sizeof(expected)) == 0);

    size_t unchanged[] = {11U, 22U};
    const size_t unchanged_expected[] = {11U, 22U};
    const ld_elf_cie_entry_t invalid_bytes = {
            .bytes = NULL,
            .bytes_size = 1U,
    };
    assert(ld_elf_cie_deduplicate(&invalid_bytes, 1U, unchanged,
                                  &error_index) ==
           LD_ELF_CIE_INVALID_ENTRY);
    assert(error_index == 0U);
    assert(memcmp(unchanged, unchanged_expected, sizeof(unchanged)) == 0);

    const ld_elf_cie_entry_t invalid_relocations = {
            .bytes = bytes_a,
            .bytes_size = sizeof(bytes_a),
            .relocations = NULL,
            .relocation_count = 1U,
    };
    assert(ld_elf_cie_deduplicate(&invalid_relocations, 1U, unchanged,
                                  &error_index) ==
           LD_ELF_CIE_INVALID_ENTRY);
    assert(error_index == 0U);
    assert(memcmp(unchanged, unchanged_expected, sizeof(unchanged)) == 0);

    assert(ld_elf_cie_deduplicate(NULL, 1U, unchanged, &error_index) ==
           LD_ELF_CIE_INVALID_ARGUMENT);
    assert(error_index == SIZE_MAX);
    assert(memcmp(unchanged, unchanged_expected, sizeof(unchanged)) == 0);
    assert(ld_elf_cie_deduplicate(entries, 1U, NULL, &error_index) ==
           LD_ELF_CIE_INVALID_ARGUMENT);
    assert(ld_elf_cie_deduplicate(NULL, 0U, NULL, &error_index) ==
           LD_ELF_CIE_OK);
    assert(error_index == SIZE_MAX);
}

static void test_elf_symtab_encoder(void) {
    const ld_elf_symtab_entry_t locals[] = {
            {
                    .name = "",
                    .binding = LD_ELF_STB_LOCAL,
                    .type = LD_ELF_STT_SECTION,
                    .other = LD_ELF_STV_DEFAULT,
                    .section_index = 1U,
                    .value = UINT64_C(0x401000),
            },
            {
                    .name = "local",
                    .binding = LD_ELF_STB_LOCAL,
                    .type = LD_ELF_STT_OBJECT,
                    .other = LD_ELF_STV_HIDDEN,
                    .section_index = 2U,
                    .value = UINT64_C(0x402000),
                    .size = 4U,
            },
    };
    const ld_elf_symtab_entry_t globals[] = {
            {
                    .name = "global",
                    .binding = LD_ELF_STB_GLOBAL,
                    .type = LD_ELF_STT_FUNC,
                    .other = LD_ELF_STV_DEFAULT,
                    .section_index = 1U,
                    .value = UINT64_C(0x401004),
                    .size = 8U,
            },
            {
                    .name = "weak",
                    .binding = LD_ELF_STB_WEAK,
                    .type = LD_ELF_STT_NOTYPE,
                    .other = LD_ELF_STV_PROTECTED,
                    .section_index = LD_ELF_SHN_UNDEF,
            },
    };

    ld_elf_symtab_t table;
    ld_elf_symtab_init(&table);
    size_t error_index = 123U;
    assert(ld_elf_symtab_build(
                   locals, sizeof(locals) / sizeof(locals[0]), globals,
                   sizeof(globals) / sizeof(globals[0]), &table,
                   &error_index) == LD_ELF_SYMTAB_OK);
    assert(error_index == SIZE_MAX);
    assert(table.symbol_count == 5U);
    assert(table.symbols_size == 5U * LD_ELF64_SYM_SIZE);
    assert(table.first_global == 3U);
    static const char expected_strings[] = "\0local\0global\0weak";
    assert(table.strings_size == sizeof(expected_strings));
    assert(memcmp(table.strings, expected_strings,
                  sizeof(expected_strings)) == 0);

    for (size_t i = 0; i < LD_ELF64_SYM_SIZE; i++)
        assert(table.symbols[i] == 0U);
    const uint8_t *section = table.symbols + LD_ELF64_SYM_SIZE;
    assert(test_elf_read_u32(section) == 0U);
    assert(section[4] == LD_ELF_SYM_INFO(LD_ELF_STB_LOCAL,
                                         LD_ELF_STT_SECTION));
    assert(test_elf_read_u16(section + 6U) == 1U);
    assert(test_elf_read_u64(section + 8U) == UINT64_C(0x401000));

    const uint8_t *local = section + LD_ELF64_SYM_SIZE;
    assert(test_elf_read_u32(local) == 1U);
    assert(local[4] ==
           LD_ELF_SYM_INFO(LD_ELF_STB_LOCAL, LD_ELF_STT_OBJECT));
    assert(local[5] == LD_ELF_STV_HIDDEN);
    assert(test_elf_read_u16(local + 6U) == 2U);
    assert(test_elf_read_u64(local + 8U) == UINT64_C(0x402000));
    assert(test_elf_read_u64(local + 16U) == 4U);

    const uint8_t *global = local + LD_ELF64_SYM_SIZE;
    assert(test_elf_read_u32(global) == 7U);
    assert(global[4] ==
           LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC));
    assert(test_elf_read_u16(global + 6U) == 1U);
    assert(test_elf_read_u64(global + 8U) == UINT64_C(0x401004));
    assert(test_elf_read_u64(global + 16U) == 8U);

    const uint8_t *weak = global + LD_ELF64_SYM_SIZE;
    assert(test_elf_read_u32(weak) == 14U);
    assert(weak[4] ==
           LD_ELF_SYM_INFO(LD_ELF_STB_WEAK, LD_ELF_STT_NOTYPE));
    assert(weak[5] == LD_ELF_STV_PROTECTED);
    assert(test_elf_read_u16(weak + 6U) == LD_ELF_SHN_UNDEF);

    ld_elf_symtab_deinit(&table);
    ld_elf_symtab_deinit(&table);
    assert(table.symbols == NULL && table.symbols_size == 0U);
    assert(table.strings == NULL && table.strings_size == 0U);
    assert(table.symbol_count == 0U && table.first_global == 0U);

    ld_elf_symtab_entry_t invalid = locals[0];
    invalid.name = NULL;
    error_index = SIZE_MAX;
    assert(ld_elf_symtab_build(&invalid, 1U, NULL, 0U, &table,
                               &error_index) ==
           LD_ELF_SYMTAB_INVALID_ARGUMENT);
    assert(error_index == 0U && table.symbols == NULL &&
           table.strings == NULL);

    ld_elf_symtab_init(&table);
    assert(ld_elf_symtab_build(NULL, 1U, NULL, 0U, &table,
                               &error_index) ==
           LD_ELF_SYMTAB_INVALID_ARGUMENT);
    assert(table.symbols == NULL && table.strings == NULL);
    assert(ld_elf_symtab_build(NULL, 0U, NULL, 0U, NULL,
                               &error_index) ==
           LD_ELF_SYMTAB_INVALID_ARGUMENT);

    invalid = globals[0];
    invalid.binding = 16U;
    error_index = SIZE_MAX;
    assert(ld_elf_symtab_build(NULL, 0U, &invalid, 1U, &table,
                               &error_index) == LD_ELF_SYMTAB_INVALID_INFO);
    assert(error_index == 0U && table.symbols == NULL &&
           table.strings == NULL);

#if SIZE_MAX > UINT32_MAX
    invalid = locals[0];
    assert(ld_elf_symtab_build(
                   &invalid, (size_t) UINT32_MAX + 1U, NULL, 0U, &table,
                   &error_index) == LD_ELF_SYMTAB_SYMBOL_COUNT_OVERFLOW);
    assert(table.symbols == NULL && table.strings == NULL);
#endif
    invalid = globals[0];
    assert(ld_elf_symtab_build(
                   NULL, 0U, &invalid, SIZE_MAX / LD_ELF64_SYM_SIZE + 1U,
                   &table, &error_index) ==
           LD_ELF_SYMTAB_SYMBOL_SIZE_OVERFLOW);
    assert(table.symbols == NULL && table.strings == NULL);

    ld_elf_symtab_init(&table);
    assert(ld_elf_symtab_build(NULL, 0U, NULL, 0U, &table,
                               &error_index) == LD_ELF_SYMTAB_OK);
    assert(table.symbol_count == 1U && table.first_global == 1U);
    assert(table.symbols_size == LD_ELF64_SYM_SIZE);
    assert(table.strings_size == 1U && table.strings[0] == '\0');
    ld_elf_symtab_deinit(&table);
}

static void test_elf_eh_frame_hdr_encoder(void) {
    size_t encoded_size = 999U;
    assert(ld_elf_eh_frame_hdr_size(3U, &encoded_size) ==
           LD_ELF_EH_FRAME_HDR_OK);
    assert(encoded_size == 36U);
    assert(ld_elf_eh_frame_hdr_size(0U, NULL) ==
           LD_ELF_EH_FRAME_HDR_INVALID_ARGUMENT);
#if SIZE_MAX > UINT32_MAX
    encoded_size = 999U;
    assert(ld_elf_eh_frame_hdr_size((size_t) UINT32_MAX + 1U,
                                    &encoded_size) ==
           LD_ELF_EH_FRAME_HDR_ENTRY_COUNT_OVERFLOW);
    assert(encoded_size == 999U);
#endif

    const uint64_t header_address = 0x100000U;
    const uint64_t eh_frame_address = 0x100080U;
    const ld_elf_eh_frame_hdr_entry_t entries[] = {
            {.first_pc = 0x100300U, .fde_address = 0x100900U},
            {.first_pc = 0x0fff00U, .fde_address = 0x100800U},
            {.first_pc = 0x100300U, .fde_address = 0x100700U},
    };
    uint8_t output[36];
    memset(output, 0xa5, sizeof(output));
    size_t error_index = 0U;
    assert(ld_elf_eh_frame_hdr_encode(
                   output, sizeof(output), header_address, eh_frame_address,
                   entries, sizeof(entries) / sizeof(entries[0]),
                   &error_index) == LD_ELF_EH_FRAME_HDR_OK);
    assert(error_index == SIZE_MAX);
    assert(output[0] == 1U);
    assert(output[1] == 0x1bU);
    assert(output[2] == 0x03U);
    assert(output[3] == 0x3bU);
    assert(test_elf_read_u32(output + 4U) == 0x7cU);
    assert(test_elf_read_u32(output + 8U) == 3U);
    /* Sorted by first PC, then by FDE address. */
    assert(test_elf_read_u32(output + 12U) == 0xffffff00U);
    assert(test_elf_read_u32(output + 16U) == 0x800U);
    assert(test_elf_read_u32(output + 20U) == 0x300U);
    assert(test_elf_read_u32(output + 24U) == 0x700U);
    assert(test_elf_read_u32(output + 28U) == 0x300U);
    assert(test_elf_read_u32(output + 32U) == 0x900U);

    uint8_t empty_header[12];
    memset(empty_header, 0xa5, sizeof(empty_header));
    assert(ld_elf_eh_frame_hdr_encode(
                   empty_header, sizeof(empty_header), header_address,
                   eh_frame_address, NULL, 0U, &error_index) ==
           LD_ELF_EH_FRAME_HDR_OK);
    assert(error_index == SIZE_MAX);
    assert(empty_header[0] == 1U && empty_header[1] == 0x1bU &&
           empty_header[2] == 0x03U && empty_header[3] == 0x3bU);
    assert(test_elf_read_u32(empty_header + 4U) == 0x7cU);
    assert(test_elf_read_u32(empty_header + 8U) == 0U);

    uint8_t unchanged[36];
    memset(unchanged, 0x5a, sizeof(unchanged));
    uint8_t expected[36];
    memcpy(expected, unchanged, sizeof(expected));
    assert(ld_elf_eh_frame_hdr_encode(
                   unchanged, sizeof(unchanged) - 1U, header_address,
                   eh_frame_address, entries,
                   sizeof(entries) / sizeof(entries[0]), &error_index) ==
           LD_ELF_EH_FRAME_HDR_OUTPUT_TOO_SMALL);
    assert(memcmp(unchanged, expected, sizeof(unchanged)) == 0);

    const ld_elf_eh_frame_hdr_entry_t first_pc_overflow = {
            .first_pc = header_address + (uint64_t) INT32_MAX + 1U,
            .fde_address = header_address,
    };
    assert(ld_elf_eh_frame_hdr_encode(
                   unchanged, sizeof(unchanged), header_address,
                   eh_frame_address, &first_pc_overflow, 1U, &error_index) ==
           LD_ELF_EH_FRAME_HDR_FIRST_PC_RANGE);
    assert(error_index == 0U);
    assert(memcmp(unchanged, expected, sizeof(unchanged)) == 0);

    const ld_elf_eh_frame_hdr_entry_t fde_overflow = {
            .first_pc = header_address,
            .fde_address = header_address + (uint64_t) INT32_MAX + 1U,
    };
    assert(ld_elf_eh_frame_hdr_encode(
                   unchanged, sizeof(unchanged), header_address,
                   eh_frame_address, &fde_overflow, 1U, &error_index) ==
           LD_ELF_EH_FRAME_HDR_FDE_ADDRESS_RANGE);
    assert(error_index == 0U);
    assert(memcmp(unchanged, expected, sizeof(unchanged)) == 0);

    assert(ld_elf_eh_frame_hdr_encode(
                   unchanged, sizeof(unchanged), header_address,
                   header_address + 4U + (uint64_t) INT32_MAX + 1U,
                   entries, 1U, &error_index) ==
           LD_ELF_EH_FRAME_HDR_EH_FRAME_POINTER_RANGE);
    assert(error_index == SIZE_MAX);
    assert(memcmp(unchanged, expected, sizeof(unchanged)) == 0);

    const uint64_t pointer_boundary_field = UINT64_C(0x90000000);
    assert(ld_elf_eh_frame_hdr_encode(
                   empty_header, sizeof(empty_header),
                   pointer_boundary_field - 4U, UINT64_C(0x10000000), NULL,
                   0U, &error_index) == LD_ELF_EH_FRAME_HDR_OK);
    assert(test_elf_read_u32(empty_header + 4U) == 0x80000000U);
    assert(ld_elf_eh_frame_hdr_encode(
                   empty_header, sizeof(empty_header),
                   pointer_boundary_field - 4U,
                   pointer_boundary_field + (uint64_t) INT32_MAX, NULL, 0U,
                   &error_index) == LD_ELF_EH_FRAME_HDR_OK);
    assert(test_elf_read_u32(empty_header + 4U) == 0x7fffffffU);

    assert(ld_elf_eh_frame_hdr_encode(
                   unchanged, sizeof(unchanged), UINT64_MAX - 3U,
                   eh_frame_address, entries, 1U, &error_index) ==
           LD_ELF_EH_FRAME_HDR_EH_FRAME_POINTER_RANGE);
    assert(error_index == SIZE_MAX);
    assert(memcmp(unchanged, expected, sizeof(unchanged)) == 0);

    const uint64_t boundary_header = UINT64_C(0x90000000);
    const ld_elf_eh_frame_hdr_entry_t boundary_entries[] = {
            {.first_pc = UINT64_C(0x10000000),
             .fde_address = boundary_header + (uint64_t) INT32_MAX},
            {.first_pc = boundary_header + (uint64_t) INT32_MAX,
             .fde_address = UINT64_C(0x10000000)},
    };
    assert(ld_elf_eh_frame_hdr_encode(
                   output, sizeof(output), boundary_header,
                   boundary_header + 4U, boundary_entries, 2U,
                   &error_index) == LD_ELF_EH_FRAME_HDR_OK);
    assert(test_elf_read_u32(output + 12U) == 0x80000000U);
    assert(test_elf_read_u32(output + 16U) == 0x7fffffffU);
    assert(test_elf_read_u32(output + 20U) == 0x7fffffffU);
    assert(test_elf_read_u32(output + 24U) == 0x80000000U);

    const ld_elf_eh_frame_hdr_entry_t sorted_range_error[] = {
            {.first_pc = boundary_header,
             .fde_address = boundary_header},
            {.first_pc = UINT64_C(0x0fffffff),
             .fde_address = boundary_header},
    };
    assert(ld_elf_eh_frame_hdr_encode(
                   unchanged, sizeof(unchanged), boundary_header,
                   boundary_header + 4U, sorted_range_error, 2U,
                   &error_index) == LD_ELF_EH_FRAME_HDR_FIRST_PC_RANGE);
    assert(error_index == 1U);
    assert(memcmp(unchanged, expected, sizeof(unchanged)) == 0);
}

static void test_elf_fixed_merge_entities(void) {
    static const uint8_t first_data[] = {
            0x10,
            0x11,
            0x12,
            0x13,
            0x14,
            0x15,
            0x16,
            0x17,
            0x20,
            0x21,
            0x22,
            0x23,
            0x24,
            0x25,
            0x26,
            0x27,
    };
    static const uint8_t second_data[] = {
            0x10,
            0x11,
            0x12,
            0x13,
            0x14,
            0x15,
            0x16,
            0x17,
            0x30,
            0x31,
            0x32,
            0x33,
            0x34,
            0x35,
            0x36,
            0x37,
    };
    ld_elf_section_t first = {
            .header =
                    {
                            .sh_type = LD_ELF_SHT_PROGBITS,
                            .sh_flags = LD_ELF_SHF_ALLOC | LD_ELF_SHF_MERGE,
                            .sh_size = sizeof(first_data),
                            .sh_addralign = 8U,
                            .sh_entsize = 8U,
                    },
            .name = ".rodata.cst8",
            .data = first_data,
            .data_size = sizeof(first_data),
    };
    ld_elf_section_t second = {
            .header =
                    {
                            .sh_type = LD_ELF_SHT_PROGBITS,
                            .sh_flags = LD_ELF_SHF_ALLOC | LD_ELF_SHF_MERGE,
                            .sh_size = sizeof(second_data),
                            .sh_addralign = 8U,
                            .sh_entsize = 8U,
                    },
            .name = ".rodata.cst8",
            .data = second_data,
            .data_size = sizeof(second_data),
    };
    ld_elf_output_section_t output = {
            .name = ".rodata.cst8",
            .type = LD_ELF_SHT_PROGBITS,
            .flags = LD_ELF_SHF_ALLOC | LD_ELF_SHF_MERGE,
            .align = 8U,
    };
    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    ld_elf_context_t context;
    ld_elf_context_init(&context, &options);
    ld_elf_merge_plan_t plan;
    ld_elf_merge_plan_init(&plan, &context);

    assert(ld_elf_merge_section_eligible(&first));
    assert(ld_elf_merge_add_section(&plan, &first, &output) == LD_OK);
    assert(ld_elf_merge_add_section(&plan, &second, &output) == LD_OK);
    assert(ld_elf_merge_finalize(&plan) == LD_OK);
    assert(output.size == 3U * 8U);
    assert(output.file_size == output.size);
    assert(output.entry_size == 8U);
    assert(output.align == 8U);
    output.data = calloc(1, (size_t) output.file_size);
    assert(output.data != NULL);
    assert(ld_elf_merge_emit(&plan) == LD_OK);

    uint64_t first_shared, first_unique, second_shared, second_unique;
    bool alive;
    assert(ld_elf_merge_map_input(&first, 0U, 8U, &first_shared, &alive,
                                  NULL) &&
           alive);
    assert(ld_elf_merge_map_input(&first, 8U, 8U, &first_unique, &alive,
                                  NULL) &&
           alive);
    assert(ld_elf_merge_map_input(&second, 0U, 8U, &second_shared, &alive,
                                  NULL) &&
           alive);
    assert(ld_elf_merge_map_input(&second, 8U, 8U, &second_unique, &alive,
                                  NULL) &&
           alive);
    assert(first_shared == second_shared);
    assert(first_unique != second_unique && first_unique != first_shared &&
           second_unique != first_shared);
    assert(memcmp(output.data + first_shared, first_data, 8U) == 0);
    assert(memcmp(output.data + first_unique, first_data + 8U, 8U) == 0);
    assert(memcmp(output.data + second_unique, second_data + 8U, 8U) == 0);
    assert(!ld_elf_merge_map_input(&first, 4U, 8U, NULL, NULL, NULL));

    free(output.data);
    ld_elf_merge_plan_deinit(&plan);
    ld_elf_context_deinit(&context);
    ld_options_deinit(&options);
    assert(capture.count == 0U);
}

static void test_elf_malformed_merge_entities(void) {
    static const uint8_t unterminated[] = {'b', 'a', 'd'};
    ld_elf_section_t section = {
            .header =
                    {
                            .sh_type = LD_ELF_SHT_PROGBITS,
                            .sh_flags = LD_ELF_SHF_ALLOC | LD_ELF_SHF_MERGE |
                                        LD_ELF_SHF_STRINGS,
                            .sh_size = sizeof(unterminated),
                            .sh_addralign = 1U,
                            .sh_entsize = 1U,
                    },
            .name = ".rodata.str1.1",
            .data = unterminated,
            .data_size = sizeof(unterminated),
    };
    ld_elf_output_section_t output = {
            .name = ".rodata.str1.1",
            .type = LD_ELF_SHT_PROGBITS,
            .flags = LD_ELF_SHF_ALLOC | LD_ELF_SHF_MERGE |
                     LD_ELF_SHF_STRINGS,
            .align = 1U,
    };
    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    ld_elf_context_t context;
    ld_elf_context_init(&context, &options);
    ld_elf_merge_plan_t plan;
    ld_elf_merge_plan_init(&plan, &context);
    assert(ld_elf_merge_add_section(&plan, &section, &output) ==
           LD_INVALID_INPUT);
    assert(capture.count == 1U);
    assert(strstr(capture.message, "not NUL terminated") != NULL);
    ld_elf_merge_plan_deinit(&plan);

    memset(&capture, 0, sizeof(capture));
    context.error = LD_OK;
    section.header.sh_flags = LD_ELF_SHF_ALLOC | LD_ELF_SHF_MERGE;
    section.header.sh_entsize = 2U;
    ld_elf_merge_plan_init(&plan, &context);
    assert(ld_elf_merge_add_section(&plan, &section, &output) ==
           LD_INVALID_INPUT);
    assert(capture.count == 1U);
    assert(strstr(capture.message, "not a multiple") != NULL);
    ld_elf_merge_plan_deinit(&plan);
    ld_elf_context_deinit(&context);
    ld_options_deinit(&options);
}

static void test_elf_rejects_invalid_debug_mode(void) {
    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.debug_mode = (ld_debug_mode_t) 99;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    assert(ld_link(&options) == LD_INVALID_ARGUMENT);
    assert(capture.count == 1U);
    assert(strstr(capture.message, "invalid linker debug mode value 99") !=
           NULL);
    ld_options_deinit(&options);
}

void test_ld_elf_unit(void) {
    test_elf_cie_deduplication();
    test_elf_symtab_encoder();
    test_elf_eh_frame_hdr_encoder();
    test_elf_fixed_merge_entities();
    test_elf_malformed_merge_entities();
    test_elf_rejects_invalid_debug_mode();
}

static void test_elf_init_rel_header(uint8_t *bytes, uint16_t machine,
                                     size_t section_table_offset,
                                     uint16_t section_count,
                                     uint16_t section_names_index) {
    memset(bytes, 0, LD_ELF64_EHDR_SIZE);
    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, machine);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, section_names_index);
}

static uint8_t *make_test_elf_eh_comdat_winner(size_t *result_size) {
    enum {
        group_index = 1,
        text_index = 2,
        symtab_index = 3,
        strtab_index = 4,
        shstrtab_index = 5,
        section_count = 6,
    };
    const uint32_t winner_marker = 0xc0dec0deU;
    const size_t group_offset = LD_ELF64_EHDR_SIZE;
    const size_t group_size = 2U * sizeof(uint32_t);
    const size_t text_offset = test_elf_align(group_offset + group_size, 4U);
    const size_t text_size = 8U;

    char symbol_names[64] = {0};
    size_t symbol_names_size = 1U;
    const uint32_t signature_name = test_elf_append_name(
            symbol_names, sizeof(symbol_names), &symbol_names_size,
            "comdat.eh");
    const uint32_t start_name = test_elf_append_name(
            symbol_names, sizeof(symbol_names), &symbol_names_size, "_start");

    char section_names[160] = {0};
    size_t section_names_size = 1U;
    const uint32_t group_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".group");
    const uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text.comdat.eh");
    const uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    const uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    const uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");

    const size_t symbol_names_offset = text_offset + text_size;
    const size_t section_names_offset = symbol_names_offset + symbol_names_size;
    const size_t symbols_offset = test_elf_align(
            section_names_offset + section_names_size, 8U);
    const size_t symbol_count = 3U;
    const size_t section_table_offset =
            symbols_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);
    test_elf_init_rel_header(bytes, LD_ELF_EM_X86_64, section_table_offset,
                             section_count, shstrtab_index);

    uint8_t *group = bytes + group_offset;
    test_elf_write_u32(group, LD_ELF_GRP_COMDAT);
    test_elf_write_u32(group + 4U, text_index);

    test_elf_write_u32(bytes + text_offset, winner_marker);
    test_elf_write_u32(bytes + text_offset + 4U, 0xc3U); /* ret */
    memcpy(bytes + symbol_names_offset, symbol_names, symbol_names_size);
    memcpy(bytes + section_names_offset, section_names, section_names_size);

    uint8_t *symbols = bytes + symbols_offset;
    uint8_t *signature = symbols + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(signature, signature_name);
    signature[4] = LD_ELF_SYM_INFO(LD_ELF_STB_LOCAL, LD_ELF_STT_NOTYPE);
    test_elf_write_u16(signature + 6U, text_index);
    uint8_t *start = signature + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(start, start_name);
    start[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(start + 6U, text_index);
    test_elf_write_u64(start + 8U, 0U);
    test_elf_write_u64(start + 16U, text_size);

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(sections + (size_t) group_index * LD_ELF64_SHDR_SIZE,
                           group_name, LD_ELF_SHT_GROUP, 0U, group_offset,
                           group_size, symtab_index, 1U, 4U, 4U);
    test_elf_write_section(sections + (size_t) text_index * LD_ELF64_SHDR_SIZE,
                           text_name, LD_ELF_SHT_PROGBITS,
                           LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR |
                                   LD_ELF_SHF_GROUP,
                           text_offset, text_size, 0U, 0U, 4U, 0U);
    test_elf_write_section(
            sections + (size_t) symtab_index * LD_ELF64_SHDR_SIZE,
            symtab_name, LD_ELF_SHT_SYMTAB, 0U, symbols_offset,
            symbol_count * LD_ELF64_SYM_SIZE, strtab_index, 2U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + (size_t) strtab_index * LD_ELF64_SHDR_SIZE,
            strtab_name, LD_ELF_SHT_STRTAB, 0U, symbol_names_offset,
            symbol_names_size, 0U, 0U, 1U, 0U);
    test_elf_write_section(
            sections + (size_t) shstrtab_index * LD_ELF64_SHDR_SIZE,
            shstrtab_name, LD_ELF_SHT_STRTAB, 0U, section_names_offset,
            section_names_size, 0U, 0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static uint8_t *make_test_elf_eh_archive_provider(size_t *result_size) {
    static const uint32_t provider_marker = 0xbadc0ffeU;
    char symbol_names[64] = {0};
    size_t symbol_names_size = 1U;
    const uint32_t provider_name = test_elf_append_name(
            symbol_names, sizeof(symbol_names), &symbol_names_size,
            "dead_provider");
    char section_names[128] = {0};
    size_t section_names_size = 1U;
    const uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text.provider");
    const uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    const uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    const uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t text_size = 8U;
    const size_t symbol_names_offset = text_offset + text_size;
    const size_t section_names_offset = symbol_names_offset + symbol_names_size;
    const size_t symbols_offset = test_elf_align(
            section_names_offset + section_names_size, 8U);
    const size_t symbol_count = 2U;
    const size_t section_table_offset =
            symbols_offset + symbol_count * LD_ELF64_SYM_SIZE;
    const size_t section_count = 5U;
    const size_t size = section_table_offset +
                        section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);
    test_elf_init_rel_header(bytes, LD_ELF_EM_X86_64, section_table_offset,
                             (uint16_t) section_count, 4U);
    test_elf_write_u32(bytes + text_offset, provider_marker);
    test_elf_write_u32(bytes + text_offset + 4U, 0xc3U);
    memcpy(bytes + symbol_names_offset, symbol_names, symbol_names_size);
    memcpy(bytes + section_names_offset, section_names, section_names_size);
    uint8_t *provider = bytes + symbols_offset + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(provider, provider_name);
    provider[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(provider + 6U, 1U);
    test_elf_write_u64(provider + 16U, text_size);

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(sections + LD_ELF64_SHDR_SIZE, text_name,
                           LD_ELF_SHT_PROGBITS,
                           LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR,
                           text_offset, text_size, 0U, 0U, 4U, 0U);
    test_elf_write_section(sections + 2U * LD_ELF64_SHDR_SIZE, symtab_name,
                           LD_ELF_SHT_SYMTAB, 0U, symbols_offset,
                           symbol_count * LD_ELF64_SYM_SIZE, 3U, 1U, 8U,
                           LD_ELF64_SYM_SIZE);
    test_elf_write_section(sections + 3U * LD_ELF64_SHDR_SIZE, strtab_name,
                           LD_ELF_SHT_STRTAB, 0U, symbol_names_offset,
                           symbol_names_size, 0U, 0U, 1U, 0U);
    test_elf_write_section(sections + 4U * LD_ELF64_SHDR_SIZE, shstrtab_name,
                           LD_ELF_SHT_STRTAB, 0U, section_names_offset,
                           section_names_size, 0U, 0U, 1U, 0U);
    *result_size = size;
    return bytes;
}

static int link_test_elf_amd64_inputs(const char *output_path,
                                      const char *const *input_paths,
                                      size_t input_count,
                                      diagnostic_capture_t *capture) {
    unlink(output_path);
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_AMD64;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = false;
    options.adhoc_codesign = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = capture;
    for (size_t i = 0; i < input_count; i++)
        assert(ld_add_input(&options, input_paths[i]) == LD_OK);
    int status = ld_link(&options);
    ld_options_deinit(&options);
    return status;
}

static void test_elf_assert_eh_record_layout(
        const uint8_t *image, size_t image_size, size_t expected_cies,
        size_t expected_fdes, uint64_t expected_size,
        bool every_fde_uses_first_cie) {
    const uint8_t *section =
            test_elf_find_output_section(image, image_size, ".eh_frame");
    assert(section != NULL);
    uint64_t section_offset = test_elf_read_u64(section + 24U);
    uint64_t section_size = test_elf_read_u64(section + 32U);
    assert(section_size == expected_size);
    assert(section_offset <= image_size &&
           section_size <= image_size - section_offset);
    const uint8_t *bytes = image + (size_t) section_offset;
    uint64_t cie_offsets[8];
    size_t cie_count = 0U;
    size_t fde_count = 0U;
    uint64_t cursor = 0U;
    while (cursor + sizeof(uint32_t) <= section_size) {
        uint32_t length = test_elf_read_u32(bytes + (size_t) cursor);
        if (length == 0U) {
            cursor += sizeof(uint32_t);
            break;
        }
        assert(length != UINT32_MAX);
        uint64_t record_size = sizeof(uint32_t) + (uint64_t) length;
        assert(record_size >= 8U && record_size <= section_size - cursor);
        uint32_t cie_pointer =
                test_elf_read_u32(bytes + (size_t) cursor + 4U);
        if (cie_pointer == 0U) {
            assert(cie_count < sizeof(cie_offsets) / sizeof(cie_offsets[0]));
            cie_offsets[cie_count++] = cursor;
        } else {
            assert(cie_pointer <= cursor + 4U);
            uint64_t target = cursor + 4U - cie_pointer;
            bool found = false;
            for (size_t i = 0; i < cie_count; i++) {
                if (cie_offsets[i] == target) found = true;
            }
            assert(found);
            if (every_fde_uses_first_cie) {
                assert(cie_count != 0U && target == cie_offsets[0]);
            }
            fde_count++;
        }
        cursor += record_size;
    }
    assert(cursor == section_size);
    assert(cie_count == expected_cies);
    assert(fde_count == expected_fdes);

    const uint8_t *header =
            test_elf_find_output_section(image, image_size, ".eh_frame_hdr");
    assert(header != NULL);
    uint64_t header_offset = test_elf_read_u64(header + 24U);
    uint64_t header_size = test_elf_read_u64(header + 32U);
    assert(header_offset <= image_size &&
           header_size <= image_size - header_offset && header_size >= 12U);
    assert(test_elf_read_u32(image + (size_t) header_offset + 8U) ==
           expected_fdes);
}

static void test_elf_cross_object_cie_deduplication(void) {
    test_elf_eh_frame_options_t first_options = {
            .owner_relocation = true,
    };
    test_elf_eh_frame_options_t same_options = {
            .owner_relocation = true,
            .section_anchor_relocation = true,
            .symbol_name = "second_fn",
    };
    test_elf_eh_frame_options_t different_options = {
            .owner_relocation = true,
            .symbol_name = "second_fn",
            .cie_return_register = 17U,
    };
    size_t first_size, same_size, different_size;
    uint8_t *first =
            make_test_elf_eh_frame_object(&first_options, &first_size);
    uint8_t *same =
            make_test_elf_eh_frame_object(&same_options, &same_size);
    uint8_t *different = make_test_elf_eh_frame_object(
            &different_options, &different_size);
    char first_path[] = "/tmp/nature-ld-cie-first-XXXXXX";
    char same_path[] = "/tmp/nature-ld-cie-same-XXXXXX";
    char different_path[] = "/tmp/nature-ld-cie-different-XXXXXX";
    write_fixture(first_path, first, first_size);
    write_fixture(same_path, same, same_size);
    write_fixture(different_path, different, different_size);
    free(first);
    free(same);
    free(different);

    static const char *output_path = "/tmp/nature-ld-cie-dedup-output";
    diagnostic_capture_t capture = {0};
    const char *same_inputs[] = {first_path, same_path};
    assert(link_test_elf_amd64_inputs(output_path, same_inputs, 2U,
                                      &capture) == LD_OK);
    assert(capture.count == 0U);
    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    test_elf_assert_eh_record_layout(image, image_size, 1U, 2U, 68U, true);
    const uint8_t *eh_frame =
            test_elf_find_output_section(image, image_size, ".eh_frame");
    assert(eh_frame != NULL);
    uint64_t eh_frame_address = test_elf_read_u64(eh_frame + 16U);
    uint64_t eh_frame_offset = test_elf_read_u64(eh_frame + 24U);
    /* CIE (16) + first FDE (24) + 16-byte offset of the range field in
       the second FDE.  The relocated value must be the combined section
       start even though the second object's input CIE was deduplicated. */
    assert(eh_frame_offset <= image_size &&
           64U <= image_size - eh_frame_offset);
    assert(test_elf_read_u64(image + (size_t) eh_frame_offset + 56U) ==
           eh_frame_address);
    free(image);

    memset(&capture, 0, sizeof(capture));
    const char *different_inputs[] = {first_path, different_path};
    assert(link_test_elf_amd64_inputs(output_path, different_inputs, 2U,
                                      &capture) == LD_OK);
    assert(capture.count == 0U);
    image = read_test_fixture(output_path, &image_size, NULL);
    test_elf_assert_eh_record_layout(image, image_size, 2U, 2U, 84U, false);
    free(image);

    unlink(first_path);
    unlink(same_path);
    unlink(different_path);
    unlink(output_path);
}

static bool test_elf_find_eh_cie(const uint8_t *image, size_t image_size,
                                 size_t *offset_result) {
    for (size_t offset = 0; offset + 16U <= image_size; offset++) {
        if (test_elf_read_u32(image + offset) != 12U ||
            test_elf_read_u32(image + offset + 4U) != 0U ||
            image[offset + 8U] != 1U || image[offset + 9U] != 0U ||
            image[offset + 10U] != 1U || image[offset + 11U] != 0x7cU ||
            image[offset + 12U] != 16U) {
            continue;
        }
        if (offset_result) *offset_result = offset;
        return true;
    }
    return false;
}

static bool test_elf_find_dwarf64_eh_cie(const uint8_t *image,
                                         size_t image_size,
                                         size_t *offset_result) {
    for (size_t offset = 0; offset + 24U <= image_size; offset++) {
        if (test_elf_read_u32(image + offset) != UINT32_MAX ||
            test_elf_read_u64(image + offset + 4U) != 12U ||
            test_elf_read_u32(image + offset + 12U) != 0U ||
            image[offset + 16U] != 1U || image[offset + 17U] != 0U ||
            image[offset + 18U] != 1U || image[offset + 19U] != 0x7cU ||
            image[offset + 20U] != 16U) {
            continue;
        }
        if (offset_result) *offset_result = offset;
        return true;
    }
    return false;
}

static void test_elf_expect_eh_frame_failure(
        const test_elf_eh_frame_options_t *fixture_options,
        int expected_status, const char *message_fragment) {
    size_t object_size;
    uint8_t *object =
            make_test_elf_eh_frame_object(fixture_options, &object_size);
    char object_path[] = "/tmp/nature-ld-eh-invalid-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);

    static const char *output_path = "/tmp/nature-ld-eh-invalid-output";
    diagnostic_capture_t capture = {0};
    const char *inputs[] = {object_path};
    int status =
            link_test_elf_amd64_inputs(output_path, inputs, 1U, &capture);
    if (status != expected_status || capture.count == 0U ||
        strstr(capture.message, message_fragment) == NULL) {
        fprintf(stderr,
                ".eh_frame failure mismatch: status=%d expected=%d, "
                "diagnostic='%s', expected fragment='%s'\n",
                status, expected_status, capture.message, message_fragment);
    }
    assert(status == expected_status);
    assert(capture.count > 0U);
    assert(strstr(capture.message, message_fragment) != NULL);
    assert(access(output_path, F_OK) != 0);
    unlink(object_path);
    unlink(output_path);
}

static void test_elf_eh_frame_boundaries(void) {
    static const char *output_path = "/tmp/nature-ld-eh-boundary-output";

    /* An ET_REL FDE without an initial-location relocation has no input atom
       owner.  Match Zig by dropping both the FDE and its now-unused CIE. */
    test_elf_eh_frame_options_t fixture_options = {0};
    size_t object_size;
    uint8_t *object =
            make_test_elf_eh_frame_object(&fixture_options, &object_size);
    char object_path[] = "/tmp/nature-ld-eh-no-owner-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);
    diagnostic_capture_t capture = {0};
    const char *inputs[] = {object_path};
    assert(link_test_elf_amd64_inputs(output_path, inputs, 1U, &capture) ==
           LD_OK);
    assert(capture.count == 0U);
    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    assert(!test_elf_find_eh_cie(image, image_size, NULL));
    free(image);
    unlink(object_path);
    unlink(output_path);

    /* In the DWARF64 initial-length form the CIE pointer is still a u32.  A
       live FDE proves that both owner discovery and output pointer rewriting
       advance only four bytes after that pointer. */
    fixture_options = (test_elf_eh_frame_options_t) {
            .dwarf64 = true,
            .owner_relocation = true,
    };
    object = make_test_elf_eh_frame_object(&fixture_options, &object_size);
    char dwarf64_path[] = "/tmp/nature-ld-eh-dwarf64-XXXXXX";
    write_fixture(dwarf64_path, object, object_size);
    free(object);
    memset(&capture, 0, sizeof(capture));
    inputs[0] = dwarf64_path;
    assert(link_test_elf_amd64_inputs(output_path, inputs, 1U, &capture) ==
           LD_OK);
    assert(capture.count == 0U);
    image = read_test_fixture(output_path, &image_size, NULL);
    size_t cie_offset;
    assert(test_elf_find_dwarf64_eh_cie(image, image_size, &cie_offset));
    assert(cie_offset + 60U <= image_size);
    assert(test_elf_read_u32(image + cie_offset + 24U) == UINT32_MAX);
    assert(test_elf_read_u64(image + cie_offset + 28U) == 20U);
    assert(test_elf_read_u32(image + cie_offset + 36U) == 36U);
    assert(test_elf_read_u32(image + cie_offset + 56U) == 0U);

    const uint8_t *eh_frame_header =
            test_elf_find_output_section(image, image_size, ".eh_frame");
    const uint8_t *eh_frame_hdr_header =
            test_elf_find_output_section(image, image_size,
                                         ".eh_frame_hdr");
    assert(eh_frame_header != NULL && eh_frame_hdr_header != NULL);
    assert(test_elf_read_u32(eh_frame_header + 4U) ==
           LD_ELF_SHT_X86_64_UNWIND);
    assert(test_elf_read_u64(eh_frame_header + 8U) == LD_ELF_SHF_ALLOC);
    assert(test_elf_read_u32(eh_frame_hdr_header + 4U) ==
           LD_ELF_SHT_PROGBITS);
    assert(test_elf_read_u64(eh_frame_hdr_header + 8U) == LD_ELF_SHF_ALLOC);
    assert(test_elf_read_u64(eh_frame_hdr_header + 48U) == 4U);
    uint64_t eh_frame_address =
            test_elf_read_u64(eh_frame_header + 16U);
    uint64_t eh_frame_file_offset =
            test_elf_read_u64(eh_frame_header + 24U);
    uint64_t header_address =
            test_elf_read_u64(eh_frame_hdr_header + 16U);
    uint64_t header_file_offset =
            test_elf_read_u64(eh_frame_hdr_header + 24U);
    uint64_t header_size = test_elf_read_u64(eh_frame_hdr_header + 32U);
    assert(eh_frame_file_offset == cie_offset);
    assert(header_size == 20U);
    assert(header_file_offset <= image_size &&
           header_size <= image_size - header_file_offset);
    const uint8_t *header = image + (size_t) header_file_offset;
    assert(header[0] == 1U && header[1] == 0x1bU &&
           header[2] == 0x03U && header[3] == 0x3bU);
    assert(test_elf_add_signed_u32(
                   header_address + 4U,
                   test_elf_read_u32(header + 4U)) == eh_frame_address);
    assert(test_elf_read_u32(header + 8U) == 1U);
    assert(test_elf_add_signed_u32(
                   header_address,
                   test_elf_read_u32(header + 12U)) ==
           test_elf_read_u64(image + 24U));
    assert(test_elf_add_signed_u32(
                   header_address,
                   test_elf_read_u32(header + 16U)) ==
           eh_frame_address + 24U);

    uint64_t program_offset = test_elf_read_u64(image + 32U);
    uint16_t program_count = test_elf_read_u16(image + 56U);
    assert(program_count == 5U);
    assert(program_offset <= image_size &&
           (uint64_t) program_count * LD_ELF64_PHDR_SIZE <=
                   image_size - program_offset);
    size_t gnu_eh_frame_count = 0U;
    for (uint16_t i = 0; i < program_count; i++) {
        const uint8_t *program =
                image + (size_t) program_offset +
                (size_t) i * LD_ELF64_PHDR_SIZE;
        if (test_elf_read_u32(program) != LD_ELF_PT_GNU_EH_FRAME) continue;
        gnu_eh_frame_count++;
        assert(test_elf_read_u32(program + 4U) == LD_ELF_PF_R);
        assert(test_elf_read_u64(program + 8U) == header_file_offset);
        assert(test_elf_read_u64(program + 16U) == header_address);
        assert(test_elf_read_u64(program + 32U) == header_size);
        assert(test_elf_read_u64(program + 40U) == header_size);
        assert(test_elf_read_u64(program + 48U) == 4U);
    }
    assert(gnu_eh_frame_count == 1U);
    free(image);
    unlink(dwarf64_path);
    unlink(output_path);

    fixture_options = (test_elf_eh_frame_options_t) {
            .cie_pointer_into_record = true,
    };
    test_elf_expect_eh_frame_failure(&fixture_options, LD_INVALID_INPUT,
                                     "has no matching CIE");

    fixture_options = (test_elf_eh_frame_options_t) {
            .nonzero_after_terminator = true,
    };
    test_elf_expect_eh_frame_failure(
            &fixture_options, LD_INVALID_INPUT,
            "non-zero bytes follow the .eh_frame terminator");

    fixture_options = (test_elf_eh_frame_options_t) {
            .terminator_relocation = true,
    };
    test_elf_expect_eh_frame_failure(
            &fixture_options, LD_INVALID_INPUT,
            "terminator, padding, or outside a record");

    fixture_options = (test_elf_eh_frame_options_t) {
            .owner_relocation = true,
            .cross_record_relocation = true,
    };
    test_elf_expect_eh_frame_failure(&fixture_options, LD_RELOCATION_ERROR,
                                     "cross-record");
}

static void test_elf_comdat_eh_frame_compaction(void) {
    size_t winner_size, loser_size, provider_size;
    uint8_t *winner = make_test_elf_eh_comdat_winner(&winner_size);
    uint8_t *loser = make_test_elf_eh_comdat_loser(&loser_size);
    uint8_t *provider = make_test_elf_eh_archive_provider(&provider_size);

    char winner_path[] = "/tmp/nature-ld-eh-comdat-winner-XXXXXX";
    char loser_path[] = "/tmp/nature-ld-eh-comdat-loser-XXXXXX";
    write_fixture(winner_path, winner, winner_size);
    write_fixture(loser_path, loser, loser_size);
    free(winner);
    free(loser);

    size_t archive_capacity = LD_ELF_AR_MAGIC_SIZE +
                              LD_ELF_AR_HEADER_SIZE + provider_size + 1U;
    uint8_t *archive = calloc(1, archive_capacity);
    assert(archive != NULL);
    memcpy(archive, LD_ELF_AR_MAGIC, LD_ELF_AR_MAGIC_SIZE);
    size_t archive_size = LD_ELF_AR_MAGIC_SIZE;
    test_archive_append(archive, archive_capacity, &archive_size,
                        "dead-provider.o/", provider, provider_size);
    free(provider);
    char archive_path[] = "/tmp/nature-ld-eh-comdat-provider-XXXXXX";
    write_fixture(archive_path, archive, archive_size);
    free(archive);

    static const char *output_path = "/tmp/nature-ld-eh-comdat-output";
    diagnostic_capture_t capture = {0};
    const char *inputs[] = {winner_path, loser_path, archive_path};
    int link_status =
            link_test_elf_amd64_inputs(output_path, inputs, 3U, &capture);
    if (link_status != LD_OK)
        fprintf(stderr, "COMDAT .eh_frame link failed (%d): %s\n", link_status,
                capture.message);
    assert(link_status == LD_OK);
    assert(capture.count == 0U);

    /* The duplicate COMDAT's dead text and its archive-only provider must not
       survive the link, while the loser's non-COMDAT live text must remain. */
    assert(!test_elf_file_contains_u32(output_path, 0xd3ad0badU));
    assert(test_elf_file_contains_u32(output_path, 0x11a7e5edU));
    assert(!test_elf_file_contains_u32(output_path, 0xbadc0ffeU));

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    size_t cie_offset;
    assert(test_elf_find_eh_cie(image, image_size, &cie_offset));
    assert(cie_offset + 36U <= image_size);
    /* CIE + live FDE only; the original dead FDE was removed. */
    assert(test_elf_read_u32(image + cie_offset + 16U) == 12U);
    assert(test_elf_read_u32(image + cie_offset + 20U) == 20U);
    assert(test_elf_read_u32(image + cie_offset + 36U) == 0U);
    free(image);

    unlink(winner_path);
    unlink(loser_path);
    unlink(archive_path);
    unlink(output_path);
}

void test_ld_elf_unwind(void) {
    test_elf_cross_object_cie_deduplication();
    test_elf_eh_frame_boundaries();
    test_elf_comdat_eh_frame_compaction();
}

static uint32_t test_zlib_adler32(const uint8_t *data, size_t size) {
    uint32_t first = 1U;
    uint32_t second = 0U;
    while (size != 0U) {
        size_t chunk = size < 5552U ? size : 5552U;
        size -= chunk;
        for (size_t i = 0; i < chunk; i++) {
            first += *data++;
            second += first;
        }
        first %= 65521U;
        second %= 65521U;
    }
    return second << 16U | first;
}

static void test_zlib_writer_init(test_zlib_bit_writer_t *writer) {
    memset(writer, 0, sizeof(*writer));
    writer->bytes[0] = 0x78U;
    writer->bytes[1] = 0x9cU;
    writer->bit_position = 16U;
}

static void test_zlib_write_bits(test_zlib_bit_writer_t *writer,
                                 uint32_t value, unsigned count) {
    assert(writer && count <= 16U);
    for (unsigned i = 0; i < count; i++) {
        size_t byte_index = writer->bit_position / 8U;
        unsigned bit_index = (unsigned) (writer->bit_position % 8U);
        assert(byte_index < sizeof(writer->bytes));
        writer->bytes[byte_index] |=
                (uint8_t) (((value >> i) & 1U) << bit_index);
        writer->bit_position++;
    }
}

static uint32_t test_zlib_reverse_bits(uint32_t value, unsigned count) {
    uint32_t reversed = 0U;
    for (unsigned i = 0; i < count; i++) {
        reversed = reversed << 1U | (value & 1U);
        value >>= 1U;
    }
    return reversed;
}

static void test_zlib_write_fixed_symbol(test_zlib_bit_writer_t *writer,
                                         uint16_t symbol) {
    uint32_t code;
    unsigned bits;
    if (symbol <= 143U) {
        code = 0x30U + symbol;
        bits = 8U;
    } else if (symbol <= 255U) {
        code = 0x190U + symbol - 144U;
        bits = 9U;
    } else if (symbol <= 279U) {
        code = symbol - 256U;
        bits = 7U;
    } else {
        assert(symbol <= 287U);
        code = 0xc0U + symbol - 280U;
        bits = 8U;
    }
    test_zlib_write_bits(writer, test_zlib_reverse_bits(code, bits), bits);
}

static void test_zlib_write_fixed_distance(test_zlib_bit_writer_t *writer,
                                           uint16_t symbol) {
    assert(symbol <= 31U);
    test_zlib_write_bits(writer, test_zlib_reverse_bits(symbol, 5U), 5U);
}

static size_t test_zlib_finish_stream(test_zlib_bit_writer_t *writer,
                                      const uint8_t *output,
                                      size_t output_size) {
    writer->bit_position = (writer->bit_position + 7U) & ~(size_t) 7U;
    size_t byte_position = writer->bit_position / 8U;
    assert(byte_position <= sizeof(writer->bytes) - 4U);
    uint32_t checksum = test_zlib_adler32(output, output_size);
    writer->bytes[byte_position++] = (uint8_t) (checksum >> 24U);
    writer->bytes[byte_position++] = (uint8_t) (checksum >> 16U);
    writer->bytes[byte_position++] = (uint8_t) (checksum >> 8U);
    writer->bytes[byte_position++] = (uint8_t) checksum;
    return byte_position;
}

static void test_zlib_expect_success(const uint8_t *stream,
                                     size_t stream_size,
                                     const uint8_t *expected,
                                     size_t expected_size) {
    uint8_t *output = (uint8_t *) (uintptr_t) 1U;
    size_t output_size = SIZE_MAX;
    assert(ld_elf_zlib_decompress(stream, stream_size, expected_size,
                                  &output, &output_size) ==
           LD_ELF_ZLIB_OK);
    assert(output_size == expected_size);
    if (expected_size == 0U) {
        assert(output == NULL);
    } else {
        assert(output != NULL);
        assert(memcmp(output, expected, expected_size) == 0);
    }
    free(output);
}

static void test_zlib_expect_failure(const uint8_t *stream,
                                     size_t stream_size,
                                     uint64_t expected_size,
                                     ld_elf_zlib_result_t expected_result) {
    uint8_t *output = (uint8_t *) (uintptr_t) 1U;
    size_t output_size = SIZE_MAX;
    assert(ld_elf_zlib_decompress(stream, stream_size, expected_size,
                                  &output, &output_size) ==
           expected_result);
    assert(output == NULL && output_size == 0U);
}

static void test_zlib_empty_stream(void) {
    static const uint8_t empty[] = {
            0x78U,
            0x9cU,
            0x03U,
            0x00U,
            0x00U,
            0x00U,
            0x00U,
            0x01U,
    };
    test_zlib_expect_success(empty, sizeof(empty), NULL, 0U);
}

static void test_zlib_32k_window(void) {
    enum {
        PREFIX_A_COUNT = 32767,
        EXPECTED_SIZE = 32771,
    };
    uint8_t expected[EXPECTED_SIZE];
    memset(expected, 'A', PREFIX_A_COUNT);
    expected[PREFIX_A_COUNT] = 'B';
    memset(expected + PREFIX_A_COUNT + 1U, 'A', 3U);

    test_zlib_bit_writer_t writer;
    test_zlib_writer_init(&writer);
    test_zlib_write_bits(&writer, 3U, 3U); /* final fixed block */
    test_zlib_write_fixed_symbol(&writer, 'A');
    for (size_t i = 0; i < 127U; i++) {
        test_zlib_write_fixed_symbol(&writer, 285U); /* length 258 */
        test_zlib_write_fixed_distance(&writer, 0U); /* distance 1 */
    }
    test_zlib_write_fixed_symbol(&writer, 'B');
    test_zlib_write_fixed_symbol(&writer, 257U); /* length 3 */
    test_zlib_write_fixed_distance(&writer, 29U);
    test_zlib_write_bits(&writer, 8191U, 13U); /* distance 32768 */
    test_zlib_write_fixed_symbol(&writer, 256U);
    size_t stream_size =
            test_zlib_finish_stream(&writer, expected, sizeof(expected));

    test_zlib_expect_success(writer.bytes, stream_size, expected,
                             sizeof(expected));
}

static void test_zlib_header_and_container_failures(void) {
    static const uint8_t invalid_check[] = {0x78U, 0x9dU};
    static const uint8_t dictionary[] = {0x78U, 0x20U};
    static const uint8_t invalid_block[] = {
            0x78U,
            0x9cU,
            0x07U,
            0x00U,
            0x00U,
            0x00U,
            0x01U,
    };
    static const uint8_t truncated[] = {0x78U};
    test_zlib_expect_failure(invalid_check, sizeof(invalid_check), 0U,
                             LD_ELF_ZLIB_BAD_HEADER);
    test_zlib_expect_failure(dictionary, sizeof(dictionary), 0U,
                             LD_ELF_ZLIB_PRESET_DICTIONARY);
    test_zlib_expect_failure(invalid_block, sizeof(invalid_block), 0U,
                             LD_ELF_ZLIB_INVALID_BLOCK_TYPE);
    test_zlib_expect_failure(truncated, sizeof(truncated), 0U,
                             LD_ELF_ZLIB_TRUNCATED);

    uint8_t *output = (uint8_t *) (uintptr_t) 1U;
    size_t output_size = SIZE_MAX;
    assert(ld_elf_zlib_decompress(NULL, 0U, 0U, &output, &output_size) ==
           LD_ELF_ZLIB_INVALID_ARGUMENT);
    assert(output == NULL && output_size == 0U);
    assert(ld_elf_zlib_decompress(invalid_check, sizeof(invalid_check), 0U,
                                  NULL, &output_size) ==
           LD_ELF_ZLIB_INVALID_ARGUMENT);
}

static void test_zlib_huffman_failures(void) {
    test_zlib_bit_writer_t writer;
    test_zlib_writer_init(&writer);
    test_zlib_write_bits(&writer, 5U, 3U); /* final dynamic block */
    test_zlib_write_bits(&writer, 0U, 5U); /* 257 literals */
    test_zlib_write_bits(&writer, 0U, 5U); /* one distance */
    test_zlib_write_bits(&writer, 0U, 4U); /* four code lengths */
    for (size_t i = 0; i < 4U; i++) {
        test_zlib_write_bits(&writer, 1U, 3U);
    }
    size_t size = test_zlib_finish_stream(&writer, NULL, 0U);
    test_zlib_expect_failure(writer.bytes, size, 0U,
                             LD_ELF_ZLIB_OVERSUBSCRIBED_HUFFMAN);

    test_zlib_writer_init(&writer);
    test_zlib_write_bits(&writer, 5U, 3U);
    test_zlib_write_bits(&writer, 0U, 5U);
    test_zlib_write_bits(&writer, 0U, 5U);
    test_zlib_write_bits(&writer, 0U, 4U);
    test_zlib_write_bits(&writer, 2U, 3U);
    test_zlib_write_bits(&writer, 0U, 3U);
    test_zlib_write_bits(&writer, 0U, 3U);
    test_zlib_write_bits(&writer, 0U, 3U);
    size = test_zlib_finish_stream(&writer, NULL, 0U);
    test_zlib_expect_failure(writer.bytes, size, 0U,
                             LD_ELF_ZLIB_INCOMPLETE_HUFFMAN);
}

static void test_zlib_invalid_distance(void) {
    test_zlib_bit_writer_t writer;
    test_zlib_writer_init(&writer);
    test_zlib_write_bits(&writer, 3U, 3U);
    test_zlib_write_fixed_symbol(&writer, 257U); /* length 3 */
    test_zlib_write_fixed_distance(&writer, 0U); /* no history */
    test_zlib_write_fixed_symbol(&writer, 256U);
    size_t size = test_zlib_finish_stream(&writer, NULL, 0U);
    test_zlib_expect_failure(writer.bytes, size, 3U,
                             LD_ELF_ZLIB_INVALID_DISTANCE);
}

static void test_zlib_checksum_and_trailing_data(void) {
    static const uint8_t fixed[] = {
            0x78U,
            0x9cU,
            0xf3U,
            0x48U,
            0xcdU,
            0xc9U,
            0xc9U,
            0x57U,
            0x28U,
            0xcfU,
            0x2fU,
            0xcaU,
            0x49U,
            0xe1U,
            0x02U,
            0x00U,
            0x1cU,
            0xf2U,
            0x04U,
            0x46U,
    };
    uint8_t trailing[sizeof(fixed) + 1U];
    memcpy(trailing, fixed, sizeof(fixed));
    trailing[sizeof(fixed) - 1U] = 0x47U;
    trailing[sizeof(fixed)] = 0U;

    test_zlib_expect_failure(fixed, sizeof(fixed), 12U,
                             LD_ELF_ZLIB_CHECKSUM_MISMATCH);
    test_zlib_expect_failure(trailing, sizeof(trailing), 12U,
                             LD_ELF_ZLIB_TRAILING_DATA);
}

static void *test_zlib_allocate(void *context, size_t size) {
    test_zlib_allocator_state_t *state = context;
    state->allocations++;
    if (state->fail_allocation) return NULL;
    return malloc(size);
}

static void test_zlib_deallocate(void *context, void *allocation) {
    test_zlib_allocator_state_t *state = context;
    state->deallocations++;
    free(allocation);
}

static void test_zlib_allocator_failures_are_atomic(void) {
    static const uint8_t fixed[] = {
            0x78U,
            0x9cU,
            0xf3U,
            0x48U,
            0xcdU,
            0xc9U,
            0xc9U,
            0x57U,
            0x28U,
            0xcfU,
            0x2fU,
            0xcaU,
            0x49U,
            0xe1U,
            0x02U,
            0x00U,
            0x1cU,
            0xf2U,
            0x04U,
            0x46U,
    };
    test_zlib_allocator_state_t state = {.fail_allocation = 1};
    ld_elf_zlib_allocator_t allocator = {
            .allocate = test_zlib_allocate,
            .deallocate = test_zlib_deallocate,
            .context = &state,
    };
    uint8_t *output = (uint8_t *) (uintptr_t) 1U;
    size_t output_size = SIZE_MAX;
    assert(ld_elf_zlib_decompress_with_allocator(
                   fixed, sizeof(fixed), 12U, &allocator, &output,
                   &output_size) == LD_ELF_ZLIB_ALLOCATION_FAILED);
    assert(output == NULL && output_size == 0U);
    assert(state.allocations == 1U && state.deallocations == 0U);

    state = (test_zlib_allocator_state_t) {0};
    allocator.context = &state;
    output = (uint8_t *) (uintptr_t) 1U;
    output_size = SIZE_MAX;
    assert(ld_elf_zlib_decompress_with_allocator(
                   fixed, sizeof(fixed), 12U, &allocator, &output,
                   &output_size) == LD_ELF_ZLIB_CHECKSUM_MISMATCH);
    assert(output == NULL && output_size == 0U);
    assert(state.allocations == 1U && state.deallocations == 1U);
}

static void test_zlib_damaged_stream_smoke(void) {
    uint32_t random = UINT32_C(0x6d2b79f5);
    for (size_t iteration = 0; iteration < 2000U; iteration++) {
        uint8_t stream[80];
        stream[0] = 0x78U;
        stream[1] = 0x9cU;
        for (size_t i = 2U; i < sizeof(stream); i++) {
            random ^= random << 13U;
            random ^= random >> 17U;
            random ^= random << 5U;
            stream[i] = (uint8_t) random;
        }

        uint8_t *output = (uint8_t *) (uintptr_t) 1U;
        size_t output_size = SIZE_MAX;
        ld_elf_zlib_result_t result = ld_elf_zlib_decompress(
                stream, sizeof(stream), random & 127U, &output, &output_size);
        assert(result >= LD_ELF_ZLIB_OK &&
               result <= LD_ELF_ZLIB_TRAILING_DATA);
        if (result == LD_ELF_ZLIB_OK) {
            assert(output_size == (random & 127U));
            free(output);
        } else {
            assert(output == NULL && output_size == 0U);
        }
    }
}

void test_ld_elf_zlib(void) {
    test_zlib_block_types();
    test_zlib_empty_stream();
    test_zlib_32k_window();
    test_zlib_header_and_container_failures();
    test_zlib_stored_and_size_failures();
    test_zlib_huffman_failures();
    test_zlib_invalid_distance();
    test_zlib_checksum_and_trailing_data();
    test_zlib_allocator_failures_are_atomic();
    test_zlib_damaged_stream_smoke();
    assert(strcmp(ld_elf_zlib_result_string(
                          LD_ELF_ZLIB_CHECKSUM_MISMATCH),
                  "zlib Adler-32 checksum mismatch") == 0);
}

