    assert(ld_parse_input_file(&ctx, path) == LD_OK);
    assert(ctx.dylibs.count == 1U);
    const ld_dylib_input_t *dylib = &ctx.dylibs.items[0];
    assert(test_ld_dylib_has_symbol(dylib->exports, dylib->export_count,
                                    "_renamed"));
    assert(!test_ld_dylib_has_symbol(dylib->exports, dylib->export_count,
