void dump_global_errorf(char *rel_path, int line, int column, char *format, ...) {
    char msg[1024];

    va_list args;
    va_start(args, format);
    vsnprintf(msg, sizeof(msg), format, args);
    va_end(args);

#ifdef TEST_MODE
    COMPILER_THROW("%s:%d:%d: %s\n", rel_path, line, column, msg);
#endif

#ifdef ASSERT_ERROR
    assertf(false, "%s:%d:%d: %s\n", rel_path, line, column, msg);
#else
    fprintf(stderr, "%s:%d:%d: %s\n", rel_path, line, column, msg);
    exit(EXIT_FAILURE);
#endif
}

void module_set_current_source(module_t *m, source_file_t *sf) {
    m->current_source = sf;
    m->source = sf->source;
    m->source_path = sf->path;
    m->source_dir = sf->dir;
    m->rel_path = sf->rel_path;
    m->token_list = sf->token_list;
    m->stmt_list = sf->stmt_list;
    m->imports = sf->imports;
    m->import_table = sf->import_table;
    m->selective_import_table = sf->selective_import_table;
}

