    source_file_t *sf = NEW(source_file_t);
    sf->path = source_path;
    sf->dir = path_dir(source_path);
    sf->rel_path = module_source_rel(m, source_path);
    sf->source = file_read(source_path);
    sf->mod_ident = NULL;
