void ElectronWebAuthenticationDelegate::SetPlatformPasskeysEnabled(
    bool enabled) {
  DCHECK_CURRENTLY_ON(content::BrowserThread::UI);
  platform_passkeys_enabled() = enabled;
}

void ElectronWebAuthenticationDelegate::
    IsUserVerifyingPlatformAuthenticatorAvailableOverride(
        content::RenderFrameHost* render_frame_host,
        base::OnceCallback<void(std::optional<bool>)> callback) {
  // When platform passkeys are enabled and available, report `true` so that
  // isUserVerifyingPlatformAuthenticatorAvailable() reflects the passkey
  // authenticator, not just Touch ID. Otherwise defer to the default (nullopt).
  if (IsPlatformPasskeysEnabled() &&
      ElectronPlatformPasskeysAuthenticator::IsAvailable()) {
    std::move(callback).Run(true);
    return;
  }
  std::move(callback).Run(std::nullopt);
}

v8::Local<v8::Promise> WebFrameMain::PrintToPDF(const base::Value& settings) {
  if (!HasRenderFrame()) {
    v8::Isolate* isolate = JavascriptEnvironment::GetIsolate();
    gin_helper::Promise<v8::Local<v8::Value>> promise(isolate);
    v8::Local<v8::Promise> handle = promise.GetHandle();
    promise.RejectWithErrorMessage(
        "Render frame was disposed before WebFrameMain could be accessed");
    return handle;
  }
  return PrintFrameToPDF(render_frame_host(), settings);
}

void OnPDFCreated(gin_helper::Promise<v8::Local<v8::Value>> promise,
                  print_to_pdf::PdfPrintResult print_result,
                  scoped_refptr<base::RefCountedMemory> data) {
  if (print_result != print_to_pdf::PdfPrintResult::kPrintSuccess) {
    promise.RejectWithErrorMessage(
        "Failed to generate PDF: " +
        print_to_pdf::PdfPrintResultToString(print_result));
    return;
  }

  v8::Isolate* isolate = promise.isolate();
  gin_helper::Locker locker(isolate);
  v8::HandleScope handle_scope(isolate);
  v8::Context::Scope context_scope(
      v8::Local<v8::Context>::New(isolate, promise.GetContext()));

  v8::Local<v8::Value> buffer =
      electron::Buffer::Copy(isolate, *data).ToLocalChecked();

  promise.Resolve(buffer);
}

v8::Local<v8::Promise> PrintFrameToPDF(content::RenderFrameHost* rfh,
                                       const base::Value& settings) {
  v8::Isolate* isolate = JavascriptEnvironment::GetIsolate();
  gin_helper::Promise<v8::Local<v8::Value>> promise(isolate);
  v8::Local<v8::Promise> handle = promise.GetHandle();

  const base::DictValue& dict = settings.GetDict();

  // This allows us to track headless printing calls.
  auto unique_id = dict.FindInt(printing::kPreviewRequestID);
  auto landscape = dict.FindBool(kLandscape);
  auto display_header_footer = dict.FindBool(kDisplayHeaderFooter);
  auto print_background = dict.FindBool(kPrintBackground);
  auto scale = dict.FindDouble(kScale);
  auto paper_width = dict.FindDouble(kPaperWidth);
  auto paper_height = dict.FindDouble(kPaperHeight);
  auto margin_top = dict.FindDouble(kMarginTop);
  auto margin_bottom = dict.FindDouble(kMarginBottom);
  auto margin_left = dict.FindDouble(kMarginLeft);
  auto margin_right = dict.FindDouble(kMarginRight);
  auto page_ranges = FindStringOrEmpty(dict, kPageRanges);
  auto header_template = FindStringOrEmpty(dict, kHeaderTemplate);
  auto footer_template = FindStringOrEmpty(dict, kFooterTemplate);
  auto prefer_css_page_size = dict.FindBool(kPreferCSSPageSize);
  auto generate_tagged_pdf = dict.FindBool(kGenerateTaggedPDF);
  auto generate_document_outline = dict.FindBool(kGenerateDocumentOutline);

  absl::variant<printing::mojom::PrintPagesParamsPtr, std::string>
      print_pages_params = print_to_pdf::GetPrintPagesParams(
          rfh->GetLastCommittedURL(), landscape, display_header_footer,
          print_background, scale, paper_width, paper_height, margin_top,
          margin_bottom, margin_left, margin_right,
          std::make_optional(header_template),
          std::make_optional(footer_template), prefer_css_page_size,
          generate_tagged_pdf, generate_document_outline);

  if (absl::holds_alternative<std::string>(print_pages_params)) {
    auto error = absl::get<std::string>(print_pages_params);
    promise.RejectWithErrorMessage("Invalid print parameters: " + error);
    return handle;
  }

  auto* manager = PrintViewManagerElectron::FromWebContents(
      content::WebContents::FromRenderFrameHost(rfh));
  if (!manager) {
    promise.RejectWithErrorMessage("Failed to find print manager");
    return handle;
  }

  auto params = std::move(
      absl::get<printing::mojom::PrintPagesParamsPtr>(print_pages_params));
  params->params->document_cookie = unique_id.value_or(0);

  manager->PrintToPdf(rfh, page_ranges, std::move(params),
                      base::BindOnce(&OnPDFCreated, std::move(promise)));

  return handle;
}

void ElectronComponentExtensionResourceManager::Data::
    AddComponentResourceEntries(base::span<const webui::ResourcePath> entries) {
  for (const auto& entry : entries) {
    base::FilePath resource_path = base::FilePath().AppendASCII(entry.path);
    resource_path = resource_path.NormalizePathSeparators();

    DCHECK(!path_to_resource_id_.contains(resource_path));
    path_to_resource_id_[resource_path] = entry.id;
  }
}

bool ElectronComponentExtensionResourceManager::
    IsDynamicComponentExtensionResource(
        const ExtensionId& extension_id,
        const std::string& path,
        const content::BrowserContext* context) const {
  DCHECK_CURRENTLY_ON(content::BrowserThread::UI);
  if (path != kDynamicStringsJsPath) {
    return false;
  }
  auto it = template_data_providers_.find(
      ExtensionIdAndContext(extension_id, context));
  return it != template_data_providers_.end() && !it->second.is_null();
}

std::string
ElectronComponentExtensionResourceManager::GetDynamicResourceContent(
    const ExtensionId& extension_id,
    const std::string& path,
    const content::BrowserContext* context) const {
  DCHECK_CURRENTLY_ON(content::BrowserThread::UI);
  CHECK_EQ(path, kDynamicStringsJsPath);

  auto it = template_data_providers_.find(
      ExtensionIdAndContext(extension_id, context));
  CHECK(it != template_data_providers_.end() && !it->second.is_null());

  base::DictValue dict = it->second.Run();
  return base::StringPrintf(kDynamicStringsModuleTemplate,
                            base::WriteJson(dict).value_or("{}").c_str());
}

base::ScopedClosureRunner
ElectronComponentExtensionResourceManager::RegisterTemplateDataProvider(
    const ExtensionId& extension_id,
    const content::BrowserContext* context,
    TemplateDataProvider provider) const {
  DCHECK_CURRENTLY_ON(content::BrowserThread::UI);
  auto key = ExtensionIdAndContext(extension_id, context);
  template_data_providers_[key] = std::move(provider);
  return base::ScopedClosureRunner(base::BindOnce(
      &ElectronComponentExtensionResourceManager::OnTemplateDataProviderRemoved,
      weak_factory_.GetWeakPtr(), key));
}

void ElectronComponentExtensionResourceManager::OnTemplateDataProviderRemoved(
    const ExtensionIdAndContext& key) const {
  DCHECK_CURRENTLY_ON(content::BrowserThread::UI);
  template_data_providers_.erase(key);
  template_replacements_.erase(key);
}

base::span<const char* const>
ElectronMainDelegate::GetNonWildcardDomainNonPortSchemes() {
  static const char* const kNonWildcardDomainNonPortSchemes[] = {
      extensions::kExtensionScheme};
  return kNonWildcardDomainNonPortSchemes;
}

ProxyingAIManager::ProxyingAIManager(content::BrowserContext* browser_context,
                                     content::RenderFrameHost* rfh)
    : browser_context_(browser_context),
      rfh_(rfh ? rfh->GetWeakDocumentPtr() : content::WeakDocumentPtr()) {
  gin::WeakCell<api::Session>* session =
      api::Session::FromBrowserContext(browser_context_);
  if (session && session->Get()) {
    ai_handler_changed_subscription_ =
        session->Get()->AddAIHandlerChangedCallback(
            base::BindRepeating(&ProxyingAIManager::OnAIHandlerChanged,
                                weak_ptr_factory_.GetWeakPtr()));
  }
}

const mojo::Remote<blink::mojom::AIManager>&
ProxyingAIManager::GetAIManagerRemote() {
  if (!ai_manager_remote_.is_bound()) {
    gin::WeakCell<api::Session>* session =
        api::Session::FromBrowserContext(browser_context_);

    if (session && session->Get() && session->Get()->LocalAIHandler()) {
      auto* rfh = rfh_.AsRenderFrameHostIfValid();
      DCHECK(rfh);

      auto* web_contents = electron::api::WebContents::From(
          content::WebContents::FromRenderFrameHost(rfh));
      std::optional<int32_t> web_contents_id;

      if (web_contents) {
        web_contents_id = web_contents->ID();
      }

      session->Get()->LocalAIHandler()->BindAIManager(
          web_contents_id, rfh->GetLastCommittedOrigin(), rfh->GetFrameToken(),
          rfh->GetProcess()->GetID().GetUnsafeValue(),
          ai_manager_remote_.BindNewPipeAndPassReceiver());
    }
  }

  return ai_manager_remote_;
}

void ProxyingAIManager::CanCreateLanguageModel(
    blink::mojom::AILanguageModelCreateOptionsPtr options,
    CanCreateLanguageModelCallback callback) {
  // Default to unavailable. This ensures the callback is always invoked
  // even if there is no registered utility process handler, or the
  // process crashes.
  auto cb = mojo::WrapCallbackWithDefaultInvokeIfNotRun(
      std::move(callback),
      blink::mojom::ModelAvailabilityCheckResult::kUnavailableUnknown);

  // Proxy the call through to the utility process
  auto& ai_manager = GetAIManagerRemote();

  if (ai_manager.is_bound()) {
    ai_manager->CanCreateLanguageModel(std::move(options), std::move(cb));
  }
}

void ProxyingAIManager::CreateLanguageModel(
    mojo::PendingRemote<blink::mojom::AIManagerCreateLanguageModelClient>
        client,
    blink::mojom::AILanguageModelCreateOptionsPtr options,
    mojo::PendingRemote<on_device_model::mojom::DownloadObserver> monitor) {
  // Proxy the call through to the utility process
  auto& ai_manager = GetAIManagerRemote();

  if (!ai_manager.is_bound()) {
    mojo::Remote<blink::mojom::AIManagerCreateLanguageModelClient>
        client_remote(std::move(client));
    client_remote->OnError(
        blink::mojom::AIManagerCreateClientError::kUnableToCreateSession,
        /*quota_error_info=*/nullptr);
    return;
  }

  ai_manager->CreateLanguageModel(std::move(client), std::move(options),
                                  std::move(monitor));
}

