void ProfileTests::SettingInheritanceFallback()
    {
        // Verify that when no layer defines a setting, the default value is used.
        // Also verify that when only user defaults defines it, profiles inherit from there.
        static constexpr std::string_view userSettings{ R"({
            "profiles": {
                "defaults": {
                    "historySize": 5000
                },
                "list": [
                    {
                        "name": "profile0",
                        "guid": "{6239a42c-0000-49a3-80bd-e8fdd045185c}"
                    },
                    {
                        "name": "profile1",
                        "guid": "{6239a42c-1111-49a3-80bd-e8fdd045185c}",
                        "snapOnInput": false
                    }
                ]
            }
        })" };

        const auto settings = winrt::make_self<implementation::CascadiaSettings>(userSettings);
        const auto allProfiles = settings->AllProfiles();

        VERIFY_ARE_EQUAL(2u, allProfiles.Size());

        // profile0: historySize inherited from defaults
        VERIFY_ARE_EQUAL(5000, allProfiles.GetAt(0).HistorySize());
        // profile0: snapOnInput not set anywhere, falls back to default (true)
        VERIFY_ARE_EQUAL(true, allProfiles.GetAt(0).SnapOnInput());

        // profile1: historySize inherited from defaults
        VERIFY_ARE_EQUAL(5000, allProfiles.GetAt(1).HistorySize());
        // profile1: snapOnInput explicitly set to false
        VERIFY_ARE_EQUAL(false, allProfiles.GetAt(1).SnapOnInput());
    }

void ProfileTests::ClearSettingRestoresInheritance()
    {
        // Verify that clearing a setting at the profile layer causes it to
        // fall back to the parent's value.
        static constexpr std::string_view parentString{ R"({
            "name": "parent",
            "guid": "{6239a42c-0000-49a3-80bd-e8fdd045185c}",
            "historySize": 1000,
            "tabTitle": "ParentTitle"
        })" };
        static constexpr std::string_view childString{ R"({
            "name": "child",
            "guid": "{6239a42c-0000-49a3-80bd-e8fdd045185c}",
            "historySize": 2000,
            "tabTitle": "ChildTitle"
        })" };

        const auto parentJson = VerifyParseSucceeded(parentString);
        const auto childJson = VerifyParseSucceeded(childString);

        auto parent = implementation::Profile::FromJson(parentJson);
        auto child = parent->CreateChild();
        child->LayerJson(childJson);

        // Verify child has its own values
        VERIFY_ARE_EQUAL(2000, child->HistorySize());
        VERIFY_ARE_EQUAL(L"ChildTitle", child->TabTitle());
        VERIFY_IS_TRUE(child->HasHistorySize());
        VERIFY_IS_TRUE(child->HasTabTitle());

        // Clear historySize on child: should fall back to parent
        child->ClearHistorySize();
        VERIFY_IS_FALSE(child->HasHistorySize());
        VERIFY_ARE_EQUAL(1000, child->HistorySize());

        // Clear tabTitle on child: should fall back to parent
        child->ClearTabTitle();
        VERIFY_IS_FALSE(child->HasTabTitle());
        VERIFY_ARE_EQUAL(L"ParentTitle", child->TabTitle());
    }

void ProfileTests::HasSettingAtSpecificLayer()
    {
        // Verify that HasXxx() correctly reports whether a setting is defined
        // at the current layer vs inherited from a parent.
        static constexpr std::string_view userSettings{ R"({
            "profiles": {
                "defaults": {
                    "historySize": 5000,
                    "tabTitle": "DefaultTitle"
                },
                "list": [
                    {
                        "name": "profile0",
                        "guid": "{6239a42c-0000-49a3-80bd-e8fdd045185c}",
                        "historySize": 9001
                    },
                    {
                        "name": "profile1",
                        "guid": "{6239a42c-1111-49a3-80bd-e8fdd045185c}"
                    }
                ]
            }
        })" };

        const auto settings = winrt::make_self<implementation::CascadiaSettings>(userSettings);
        const auto allProfiles = settings->AllProfiles();

        VERIFY_ARE_EQUAL(2u, allProfiles.Size());

        // profile0: historySize is explicitly set
        VERIFY_IS_TRUE(allProfiles.GetAt(0).HasHistorySize());
        VERIFY_ARE_EQUAL(9001, allProfiles.GetAt(0).HistorySize());

        // profile0: tabTitle is NOT set at this layer (inherited from defaults)
        VERIFY_IS_FALSE(allProfiles.GetAt(0).HasTabTitle());
        VERIFY_ARE_EQUAL(L"DefaultTitle", allProfiles.GetAt(0).TabTitle());

        // profile1: historySize is NOT set at this layer (inherited from defaults)
        VERIFY_IS_FALSE(allProfiles.GetAt(1).HasHistorySize());
        VERIFY_ARE_EQUAL(5000, allProfiles.GetAt(1).HistorySize());

        // ProfileDefaults: historySize is set
        VERIFY_IS_TRUE(settings->ProfileDefaults().HasHistorySize());
        VERIFY_ARE_EQUAL(5000, settings->ProfileDefaults().HistorySize());
    }

void SerializationTests::ModifyProfileSettingAndRoundtrip()
    {
        // Load settings, modify a profile setting via setter, serialize,
        // and verify the JSON output reflects the change.
        static constexpr std::string_view settingsJson{ R"(
        {
            "defaultProfile": "{6239a42c-0000-49a3-80bd-e8fdd045185c}",
            "profiles": [
                {
                    "name": "profile0",
                    "guid": "{6239a42c-0000-49a3-80bd-e8fdd045185c}",
                    "historySize": 1000,
                    "commandline": "cmd.exe"
                }
            ]
        })" };

        const auto settings{ winrt::make_self<implementation::CascadiaSettings>(settingsJson) };

        // Verify initial value
        VERIFY_ARE_EQUAL(1000, settings->AllProfiles().GetAt(0).HistorySize());

        // Modify the setting
        settings->AllProfiles().GetAt(0).HistorySize(5000);
        VERIFY_ARE_EQUAL(5000, settings->AllProfiles().GetAt(0).HistorySize());

        // Serialize and verify the change is reflected in JSON
        const auto result{ settings->ToJson() };
        VERIFY_ARE_EQUAL(5000, result["profiles"]["list"][0]["historySize"].asInt());

        // Verify other settings are preserved
        VERIFY_ARE_EQUAL("cmd.exe", result["profiles"]["list"][0]["commandline"].asString());

        // Also verify: modify a setting that wasn't previously set
        settings->AllProfiles().GetAt(0).TabTitle(L"NewTitle");
        const auto result2{ settings->ToJson() };
        VERIFY_ARE_EQUAL("NewTitle", result2["profiles"]["list"][0]["tabTitle"].asString());
    }

void SerializationTests::ModifyGlobalSettingAndRoundtrip()
    {
        // Load settings, modify a global setting, serialize, verify JSON.
        static constexpr std::string_view settingsJson{ R"(
        {
            "defaultProfile": "{6239a42c-0000-49a3-80bd-e8fdd045185c}",
            "initialRows": 30,
            "alwaysOnTop": false,
            "profiles": [
                {
                    "name": "profile0",
                    "guid": "{6239a42c-0000-49a3-80bd-e8fdd045185c}"
                }
            ]
        })" };

        const auto settings{ winrt::make_self<implementation::CascadiaSettings>(settingsJson) };

        // Verify initial values
        VERIFY_ARE_EQUAL(30, settings->GlobalSettings().InitialRows());
        VERIFY_ARE_EQUAL(false, settings->GlobalSettings().AlwaysOnTop());

        // Modify global settings
        settings->GlobalSettings().InitialRows(50);
        settings->GlobalSettings().AlwaysOnTop(true);

        // Verify in-memory changes
        VERIFY_ARE_EQUAL(50, settings->GlobalSettings().InitialRows());
        VERIFY_ARE_EQUAL(true, settings->GlobalSettings().AlwaysOnTop());

        // Serialize and verify
        const auto result{ settings->ToJson() };
        VERIFY_ARE_EQUAL(50, result["initialRows"].asInt());
        VERIFY_ARE_EQUAL(true, result["alwaysOnTop"].asBool());
    }

void SerializationTests::ModifyColorSchemeAndRoundtrip()
    {
        // Load settings with a user color scheme, modify it, serialize, verify.
        static constexpr std::string_view settingsJson{ R"(
        {
            "defaultProfile": "{6239a42c-0000-49a3-80bd-e8fdd045185c}",
            "profiles": [
                {
                    "name": "profile0",
                    "guid": "{6239a42c-0000-49a3-80bd-e8fdd045185c}"
                }
            ],
            "schemes": [
                {
                    "name": "MyScheme",
                    "foreground": "#CCCCCC",
                    "background": "#0C0C0C",
                    "cursorColor": "#FFFFFF",
                    "black": "#0C0C0C",
                    "red": "#C50F1F",
                    "green": "#13A10E",
                    "yellow": "#C19C00",
                    "blue": "#0037DA",
                    "purple": "#881798",
                    "cyan": "#3A96DD",
                    "white": "#CCCCCC",
                    "brightBlack": "#767676",
                    "brightRed": "#E74856",
                    "brightGreen": "#16C60C",
                    "brightYellow": "#F9F1A5",
                    "brightBlue": "#3B78FF",
                    "brightPurple": "#B4009E",
                    "brightCyan": "#61D6D6",
                    "brightWhite": "#F2F2F2"
                }
            ]
        })" };

        const auto settings{ winrt::make_self<implementation::CascadiaSettings>(settingsJson) };

        // Find and modify the color scheme
        const auto schemes = settings->GlobalSettings().ColorSchemes();
        VERIFY_IS_TRUE(schemes.HasKey(L"MyScheme"));
        auto myScheme = schemes.Lookup(L"MyScheme");

        const auto origForeground = myScheme.Foreground();
        myScheme.Foreground(til::color{ 0xAA, 0xBB, 0xCC });

        // Serialize and verify the change persists
        const auto result{ settings->ToJson() };
        const auto& schemesJson = result["schemes"];
        bool found = false;
        for (const auto& scheme : schemesJson)
        {
            if (scheme["name"].asString() == "MyScheme")
            {
                VERIFY_ARE_EQUAL("#AABBCC", scheme["foreground"].asString());
                found = true;
                break;
            }
        }
        VERIFY_IS_TRUE(found, L"MyScheme should be present in serialized output");
    }

void SerializationTests::FixupUserSettingsDetectsChanges()
    {
        // Verify that FixupUserSettings returns true when settings need
        // to be written back (e.g., migration), and false when clean.
        static constexpr std::string_view cleanSettingsJson{ R"(
        {
            "defaultProfile": "{6239a42c-0000-49a3-80bd-e8fdd045185c}",
            "profiles": [
                {
                    "name": "profile0",
                    "guid": "{6239a42c-0000-49a3-80bd-e8fdd045185c}",
                    "commandline": "cmd.exe"
                }
            ]
        })" };

        // Load, fixup, serialize. Reload and verify fixup returns false.
        implementation::SettingsLoader loader1{ cleanSettingsJson, implementation::LoadStringResource(IDR_DEFAULTS) };
        loader1.MergeInboxIntoUserSettings();
        loader1.FinalizeLayering();
        loader1.FixupUserSettings();
        const auto settings1 = winrt::make_self<implementation::CascadiaSettings>(std::move(loader1));
        const auto result1{ settings1->ToJson() };

        // Reload from the serialized output (should be stable)
        implementation::SettingsLoader loader2{ toString(result1), implementation::LoadStringResource(IDR_DEFAULTS) };
        loader2.MergeInboxIntoUserSettings();
        loader2.FinalizeLayering();
        const auto fixupNeeded = loader2.FixupUserSettings();

        // After a clean roundtrip, no further fixups should be needed
        VERIFY_IS_FALSE(fixupNeeded, L"A clean roundtrip should not require further fixups");
    }

void SerializationTests::FixupCommandlinePatching()
    {
        // Verify that FixupUserSettings patches "cmd.exe" to the full path
        // for the Command Prompt profile, and "powershell.exe" for the
        // Windows PowerShell profile, and returns true to indicate changes.

        // Case 1: CMD profile with short commandline should be patched
        static constexpr std::string_view cmdSettingsJson{ R"(
        {
            "defaultProfile": "{0caa0dad-35be-5f56-a8ff-afceeeaa6101}",
            "profiles": [
                {
                    "name": "Command Prompt",
                    "guid": "{0caa0dad-35be-5f56-a8ff-afceeeaa6101}",
                    "commandline": "cmd.exe"
                }
            ]
        })" };

        {
            implementation::SettingsLoader loader{ cmdSettingsJson, implementation::LoadStringResource(IDR_DEFAULTS) };
            loader.MergeInboxIntoUserSettings();
            loader.FinalizeLayering();
            const auto fixupNeeded = loader.FixupUserSettings();
            VERIFY_IS_TRUE(fixupNeeded, L"FixupUserSettings should return true when cmd.exe is patched");

            const auto settings = winrt::make_self<implementation::CascadiaSettings>(std::move(loader));
            const auto cmdProfile = settings->FindProfile(Utils::GuidFromString(L"{0caa0dad-35be-5f56-a8ff-afceeeaa6101}"));
            VERIFY_IS_NOT_NULL(cmdProfile);
            VERIFY_ARE_EQUAL(L"%SystemRoot%\\System32\\cmd.exe", cmdProfile.Commandline());
        }

        // Case 2: PowerShell profile with short commandline should be patched
        static constexpr std::string_view psSettingsJson{ R"(
        {
            "defaultProfile": "{61c54bbd-c2c6-5271-96e7-009a87ff44bf}",
            "profiles": [
                {
                    "name": "Windows PowerShell",
                    "guid": "{61c54bbd-c2c6-5271-96e7-009a87ff44bf}",
                    "commandline": "powershell.exe"
                }
            ]
        })" };

        {
            implementation::SettingsLoader loader{ psSettingsJson, implementation::LoadStringResource(IDR_DEFAULTS) };
            loader.MergeInboxIntoUserSettings();
            loader.FinalizeLayering();
            const auto fixupNeeded = loader.FixupUserSettings();
            VERIFY_IS_TRUE(fixupNeeded, L"FixupUserSettings should return true when powershell.exe is patched");

            const auto settings = winrt::make_self<implementation::CascadiaSettings>(std::move(loader));
            const auto psProfile = settings->FindProfile(Utils::GuidFromString(L"{61c54bbd-c2c6-5271-96e7-009a87ff44bf}"));
            VERIFY_IS_NOT_NULL(psProfile);
            VERIFY_ARE_EQUAL(L"%SystemRoot%\\System32\\WindowsPowerShell\\v1.0\\powershell.exe", psProfile.Commandline());
        }

        // Case 3: CMD profile with the full path should NOT trigger fixup
        static constexpr std::string_view cleanCmdSettingsJson{ R"(
        {
            "defaultProfile": "{0caa0dad-35be-5f56-a8ff-afceeeaa6101}",
            "profiles": [
                {
                    "name": "Command Prompt",
                    "guid": "{0caa0dad-35be-5f56-a8ff-afceeeaa6101}"
                }
            ]
        })" };

        {
            implementation::SettingsLoader loader{ cleanCmdSettingsJson, implementation::LoadStringResource(IDR_DEFAULTS) };
            loader.MergeInboxIntoUserSettings();
            loader.FinalizeLayering();
            const auto fixupNeeded = loader.FixupUserSettings();
            VERIFY_IS_FALSE(fixupNeeded, L"FixupUserSettings should return false when no patching is needed");

            const auto settings = winrt::make_self<implementation::CascadiaSettings>(std::move(loader));
            const auto cmdProfile = settings->FindProfile(Utils::GuidFromString(L"{0caa0dad-35be-5f56-a8ff-afceeeaa6101}"));
            VERIFY_IS_NOT_NULL(cmdProfile);
            // Should still resolve to the full path via inbox defaults
            VERIFY_ARE_EQUAL(L"%SystemRoot%\\System32\\cmd.exe", cmdProfile.Commandline());
        }

        // Case 4: A non-builtin profile with "cmd.exe" should NOT be patched
        static constexpr std::string_view customCmdSettingsJson{ R"(
        {
            "defaultProfile": "{6239a42c-0000-49a3-80bd-e8fdd045185c}",
            "profiles": [
                {
                    "name": "My Custom CMD",
                    "guid": "{6239a42c-0000-49a3-80bd-e8fdd045185c}",
                    "commandline": "cmd.exe"
                }
            ]
        })" };

        {
            implementation::SettingsLoader loader{ customCmdSettingsJson, implementation::LoadStringResource(IDR_DEFAULTS) };
            loader.MergeInboxIntoUserSettings();
            loader.FinalizeLayering();
            loader.FixupUserSettings();

            const auto settings = winrt::make_self<implementation::CascadiaSettings>(std::move(loader));
            const auto customProfile = settings->FindProfile(Utils::GuidFromString(L"{6239a42c-0000-49a3-80bd-e8fdd045185c}"));
            VERIFY_IS_NOT_NULL(customProfile);
            // Custom profile should keep "cmd.exe" unchanged
            VERIFY_ARE_EQUAL(L"cmd.exe", customProfile.Commandline());
        }
    }

bool TerminalPage::_IsUriConsideredSomewhatSafe(const winrt::Windows::Foundation::Uri& parsedUri)
    {
        if (parsedUri.SchemeName() == L"http" || parsedUri.SchemeName() == L"https")
        {
            return true;
        }
        if (parsedUri.SchemeName() == L"file")
        {
            static const auto pathext{ wil::TryGetEnvironmentVariableW<std::wstring>(L"PATHEXT") };
            const auto filename = parsedUri.Path();
            for (const auto& e : til::split_iterator{ std::wstring_view{ pathext }, L';' })
            {
                if (til::ends_with_insensitive_ascii(filename, e))
                {
                    return false;
                }
            }

            return true;
        }

        return false;
    }

void ControlCore::HardResetWithoutErase()
    {
        const auto lock = _terminal->LockForWriting();
        _terminal->HardResetWithoutErase();
    }

void Terminal::HardResetWithoutErase()
{
    _assertLocked();
    _stateMachine->ResetState();
    auto& engine = reinterpret_cast<OutputStateMachineEngine&>(_stateMachine->Engine());
    engine.Dispatch().HardReset(false);
}

void AdaptDispatch::HardReset(bool erase)
    if (erase)
    {
        // Clears the screen - Needs to be done in two operations.
        EraseInDisplay(DispatchTypes::EraseType::All);
        EraseInDisplay(DispatchTypes::EraseType::Scrollback);
    }

TEST(Core_Mat, extractChannel_inplace_29568)
{
    // https://github.com/opencv/opencv/issues/29568
    // extractChannel() must support in-place operation (dst aliasing src).
    Mat mat(3, 3, CV_8UC3, Scalar(1, 2, 3));
    ASSERT_NO_THROW(cv::extractChannel(mat, mat, 1));
    EXPECT_EQ(1, mat.channels());
    EXPECT_EQ(Size(3, 3), mat.size());
    EXPECT_EQ(0, cv::norm(mat, Mat(3, 3, CV_8UC1, Scalar(2)), NORM_INF));
}

static std::vector<MatType> filterFP16InputTypes(const std::vector<MatType>& types)
{
    std::vector<MatType> result = types;
    for (MatType& t : result)
    {
        if (t == CV_16F)
            t = CV_32F;
    }
    return result;
}

inline void broadcastOp(const Mat* const* arrays, int narrays,
                        const std::function<void(const BroadcastOp::Tile&)>& body,
                        bool expandChannels = false,
                        double nstripes = 0.)
{
    BroadcastOp::run(arrays, narrays, body, expandChannels, nstripes);
}

inline void
AutoBuffer<_Tp, fixed_size>::reserve(size_t _cap)
{
    if( _cap <= cap )       // never shrink; _cap > cap implies _cap > fixed_size, so always heap
        return;
    _Tp* prevptr = ptr;
    ptr = new _Tp[_cap];
    // only the LIVE elements [0, sz) are copied - for trivial types the inline buf tail beyond sz
    // is intentionally raw (AutoBuffer is a scratch buffer), which gcc's -Wmaybe-uninitialized
    // cannot prove when it inlines a grow-from-inline-storage call chain; the annotation below
    // documents exactly that, it does not change behavior
#if defined(__GNUC__) && !defined(__clang__)
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wmaybe-uninitialized"
#endif
    for( size_t i = 0; i < sz; i++ )    // preserve the live elements
        ptr[i] = prevptr[i];
#if defined(__GNUC__) && !defined(__clang__)
#pragma GCC diagnostic pop
#endif
    if( prevptr != buf )
        delete[] prevptr;
    cap = _cap;
    if(_size <= sz)         // shrink: keep the capacity and the surviving content
    if(_size > cap)         // grow with geometric slack (like push_back) so incremental
        reserve(cap + cap/2 > _size ? cap + cap/2 : _size);   // resize(size()+delta) loops don't realloc every step
    // !!! DO NOT ADD ANY INITIALIZATION OF THE NEW TAIL HERE (e.g. `for(i=sz..) ptr[i]=_Tp();`) !!!
    // AutoBuffer IS A RAW SCRATCH BUFFER. Value-initializing the tail zero-fills it on EVERY grow, which
    // silently dominates the cost of small allocations (measured: ~1.2us per few-KB resize) and there is
    // NOTHING to init anyway - callers write before they read. Class-type elements are already
    // constructed by `new _Tp[]` / the inline array. If you truly need filled slots, call the two-arg
    // overload resize(size, value) EXPLICITLY.
}

inline void
AutoBuffer<_Tp, fixed_size>::resize(size_t _size, const _Tp& value)
{
    const size_t old = sz;
    resize(_size);
    for( size_t i = old; i < _size; i++ )   // fill every newly exposed slot
        ptr[i] = value;
template<typename _Tp, size_t fixed_size> inline size_t
AutoBuffer<_Tp, fixed_size>::capacity() const
{ return cap; }

static Mat randMat(const std::vector<int>& shape, int cn, int depth, double lo, double hi)
{
    Mat m64((int)shape.size(), shape.data(), CV_MAKETYPE(CV_64F, cn));
    cvtest::randUni(theRNG(), m64, Scalar::all(lo), Scalar::all(hi));
    Mat m; m64.convertTo(m, CV_MAKETYPE(depth, cn));
    return m;
}

static Mat randMask(const std::vector<int>& shape)
{
    Mat m((int)shape.size(), shape.data(), CV_8U);
    cvtest::randUni(theRNG(), m, Scalar::all(0), Scalar::all(2));
    return m;
}

static double minUs(F&& f, int iters, int ninner)
{
    f();  // warmup (allocates reused output, warms caches)
    double best = DBL_MAX;
    for (int i = 0; i < iters; i++)
    {
        int64 t0 = getTickCount();
        for (int j = 0; j < ninner; j++) f();
        double us = (getTickCount() - t0) * 1e6 / getTickFrequency() / ninner;
        best = std::min(best, us);
    }
    return best;
}

static void perfBinOp(TOp op, const char* title, bool masked)
{
    const std::string opname = opName(op);
    const Combo combos[] = {
        { CV_8U,  CV_8U,  CV_8U,  opname + "(u8,  u8)->u8   " },
        { CV_16F, CV_16F, CV_16F, opname + "(f16, f16)->f16 " },
        { CV_32F, CV_32F, CV_32F, opname + "(f32, f32)->f32 " },
        { CV_8U,  CV_16F, CV_16F, opname + "(u8,  f16)->f16 " },
    };
    const Sz sizes[] = {
        { {10,10,10},   1, 5000, "10x10x10    " },
        { {165,121},    1, 2000, "165x121     " },
        { {1024,1024},  3,    4, "1024x1024x3 " },
    };

    std::cout << "\n[ew-perf] " << title << "  (min us per call over 30 trials)\n";
    std::cout << "  combo                size           engine     cv::op     speedup\n";
    std::cout << "  -----------------------------------------------------------------\n";

    for (const Combo& c : combos)
        for (const Sz& s : sizes)
        {
            Mat a = randMat(s.shape, s.cn, c.da, 0, 100);
            Mat b = randMat(s.shape, s.cn, c.db, 0, 100);
            // div: make the divisor nonzero (the 0..100 data includes 0 for integer b); float-div by
            // zero is UB, integer-div by zero is a separate (accuracy-tested) corner not timed here.
            if (op == OP_DIV) { Mat b64; b.convertTo(b64, CV_64F); b64.setTo(1.0, b64 == 0.0); b64.convertTo(b, c.db); }
            Mat mask = masked ? randMask(s.shape) : Mat();
            Mat init = masked ? randMat(s.shape, s.cn, c.Tr, 0, 50) : Mat();   // pre-existing dst
            Mat in2[] = {a, b}, in3[] = {a, b, mask}, out = masked ? init.clone() : Mat();
            Mat* inps = masked ? in3 : in2;
            const int mdepth = masked ? CV_8U : EW_DEPTH_NONE;
            // u8*u8 mul: exercise a realistic non-unit scale (1/255, the normalized-blend case) -
            // checks the specialized u8 mul branch still holds up when scale != 1.
            const double scale = (op == OP_MUL && c.da == CV_8U && c.db == CV_8U) ? 1.0/255 : 1.0;

            // Full per-call path (matches a future cv:: op): build the program every call.
            // (masked preserves the pre-filled `out` where mask==0, so repeated calls are idempotent.)
            double te = minUs([&]{ TExpr p; makeBinaryArithProgram(p, op, c.da, c.db, c.Tr, mdepth, scale);
                                   p.exec(inps, &out); }, 30, s.ninner);

            // engine correctness sanity: add/sub vs cv:: directly; mul/div vs a double reference (the
            // extensive test owns exactness, so a generous tolerance here just guards against garbage).
            const bool fp = (op == OP_MUL || op == OP_DIV);
            Mat ref;
            if (op == OP_ADD)      cv::add     (a, b, ref, noArray(), c.Tr);
            else if (op == OP_SUB) cv::subtract(a, b, ref, noArray(), c.Tr);
            else if (op == OP_MIN || op == OP_MAX || op == OP_ABSDIFF) {
                   Mat aT, bT; a.convertTo(aT, c.Tr); b.convertTo(bT, c.Tr);
                   if (op == OP_MIN) cv::min(aT, bT, ref);
                   else if (op == OP_MAX) cv::max(aT, bT, ref);
                   else cv::absdiff(aT, bT, ref); }
            else { Mat aD, bD, q; a.convertTo(aD, CV_64F); b.convertTo(bD, CV_64F);
                   if (op == OP_MUL) cv::multiply(aD, bD, q, scale); else cv::divide(aD, bD, q);
                   q.convertTo(ref, c.Tr); }
            if (masked) { Mat full = ref; ref = init.clone(); full.copyTo(ref, mask); }
            double n = cvtest::norm(out, ref, NORM_INF);
            double sc = std::max(1.0, cvtest::norm(ref, NORM_INF));
            double tol = (c.Tr==CV_16F||c.Tr==CV_16BF) ? (fp ? 1e-2*sc : 1.0)
                       : c.Tr==CV_32F                  ? (fp ? 1e-3*sc : 1e-3)
                       : (fp ? 1.0 : 0.0);
            EXPECT_LE(n, tol) << title << " " << c.name << " " << s.name;

            // cv:: timing reference (skip for mixed-type masked / mul / div, where the cv:: array op
            // needs same-type inputs). min/max/absdiff have no dtype arg and require identical input
            // types, so they are only timed against cv:: when da == db.
            const bool mm = (op == OP_MIN || op == OP_MAX || op == OP_ABSDIFF);
            double tc = -1;
            if (c.da == c.db || (!masked && !fp && !mm))
            {
                Mat tmp;
                InputArray m = masked ? InputArray(mask) : noArray();
                if      (op == OP_ADD) tc = minUs([&]{ cv::add     (a, b, tmp, m, c.Tr); }, 30, s.ninner);
                else if (op == OP_SUB) tc = minUs([&]{ cv::subtract(a, b, tmp, m, c.Tr); }, 30, s.ninner);
                else if (op == OP_MUL) tc = minUs([&]{ cv::multiply(a, b, tmp, scale, c.Tr); }, 30, s.ninner);
                else if (op == OP_MIN) tc = minUs([&]{ cv::min     (a, b, tmp); }, 30, s.ninner);
                else if (op == OP_MAX) tc = minUs([&]{ cv::max     (a, b, tmp); }, 30, s.ninner);
                else if (op == OP_ABSDIFF) tc = minUs([&]{ cv::absdiff(a, b, tmp); }, 30, s.ninner);
                else                   tc = minUs([&]{ cv::divide  (a, b, tmp, 1.0, c.Tr); }, 30, s.ninner);
            }

            std::cout << "  " << c.name << "  " << s.name << "  "
                      << std::fixed << std::setprecision(3) << std::setw(8) << te << "   ";
            if (tc >= 0)
                std::cout << std::setw(8) << tc << "   " << std::setprecision(2) << std::setw(6) << (tc/te) << "x";
            else
                std::cout << "      -          -  ";
            std::cout << "\n";
        }
}

static void perfCompare(TOp op, const char* title)
{
    const std::string opname = opName(op);
    const int cmpop = (op == OP_CMP_EQ) ? cv::CMP_EQ : cv::CMP_GT;
    const Combo combos[] = {
        { CV_8U,  CV_8U,  CV_8U, opname + "(u8,  u8) ->u8 " },
        { CV_16F, CV_16F, CV_8U, opname + "(f16, f16)->u8 " },
        { CV_32F, CV_32F, CV_8U, opname + "(f32, f32)->u8 " },
        { CV_8U,  CV_16F, CV_8U, opname + "(u8,  f16)->u8 " },
    };
    const Sz sizes[] = {
        { {10,10,10},   1, 5000, "10x10x10    " },
        { {165,121},    1, 2000, "165x121     " },
        { {1024,1024},  3,    4, "1024x1024x3 " },
    };

    std::cout << "\n[ew-perf] " << title << "  (min us per call over 30 trials)\n";
    std::cout << "  combo                size           engine     cv::cmp    speedup\n";
    std::cout << "  -----------------------------------------------------------------\n";

    for (const Combo& c : combos)
        for (const Sz& s : sizes)
        {
            Mat a = randMat(s.shape, s.cn, c.da, 0, 16);   // small range so EQ fires often
            Mat b = randMat(s.shape, s.cn, c.db, 0, 16);
            Mat in2[] = {a, b}, out;

            double te = minUs([&]{ TExpr p; makeBinaryArithProgram(p, op, c.da, c.db, -1);
                                   p.exec(in2, &out); }, 30, s.ninner);

            // correctness: per-channel compare in f64 -> 0/255 (engine's default mask value)
            std::vector<Mat> ach, bch; cv::split(a, ach); cv::split(b, bch);
            std::vector<Mat> refch(s.cn);
            for (int ch = 0; ch < s.cn; ch++) {
                Mat af, bf; ach[ch].convertTo(af, CV_64F); bch[ch].convertTo(bf, CV_64F);
                cv::compare(af, bf, refch[ch], cmpop);
            }
            Mat ref; cv::merge(refch, ref);
            ASSERT_EQ(out.type(), CV_8UC(s.cn)) << title << " " << c.name;
            EXPECT_EQ(0, cvtest::norm(out, ref, NORM_INF)) << title << " " << c.name << " " << s.name;

            double tc = -1;
            if (c.da == c.db)   // cv::compare needs identical input types (it handles multi-channel)
            {
                Mat tmp;
                tc = minUs([&]{ cv::compare(a, b, tmp, cmpop); }, 30, s.ninner);
            }

            std::cout << "  " << c.name << "  " << s.name << "  "
                      << std::fixed << std::setprecision(3) << std::setw(8) << te << "   ";
            if (tc >= 0)
                std::cout << std::setw(8) << tc << "   " << std::setprecision(2) << std::setw(6) << (tc/te) << "x";
            else
                std::cout << "      -          -  ";
            std::cout << "\n";
        }
}

TEST(Core_EW_Perf, cmpEQ)
{
    perfCompare(OP_CMP_EQ, "cmpEQ");
    std::cout << std::endl;
}

