TEST(Core_EW_Perf, addWeighted)
{
    // fused: addWeighted(a,alpha,b,beta,gamma) = a*alpha + b*beta + gamma. Two convert_scale MACs +
    // an add => 2 temp buffers => exercises the body's L1 column-fragmentation.
    std::cout << "\n[ew-perf] addWeighted  (min us per call over 30 trials)\n";
    std::cout << "  combo         size           engine    cv::aW     speedup\n";

    const double alpha = 1.5, beta = -0.75, gamma = 12.0;
    struct Sz2 { std::vector<int> shape; int cn; int ninner; const char* name; };
    const Sz2 sizes2[] = {
        { {10,10,10},  1, 2000, "10x10x10    " },
        { {165,121},   1, 1000, "165x121     " },
        { {1024,1024}, 1,    8, "1024x1024   " },
    };
    for (const Sz2& s : sizes2)
    {
        Mat a = randMat(s.shape, s.cn, CV_32F, -100, 100);
        Mat b = randMat(s.shape, s.cn, CV_32F, -100, 100);
        Mat inps[] = {a, b}, out;
        double te = minUs([&]{ TExpr p; makeAddWeightedProgram(p, CV_32F, CV_32F, CV_32F, alpha, beta, gamma);
                               p.exec(inps, &out); }, 30, s.ninner);
        Mat ref;
        double tc = minUs([&]{ cv::addWeighted(a, alpha, b, beta, gamma, ref); }, 30, s.ninner);
        EXPECT_LE(cvtest::norm(out, ref, NORM_INF), 1e-2) << "addWeighted " << s.name;

        std::cout << "  f32 aW->f32   " << s.name << "  " << std::fixed << std::setprecision(3)
                  << std::setw(8) << te << "   " << std::setw(8) << tc << "   "
                  << std::setprecision(2) << std::setw(6) << (tc/te) << "x\n";
    }
    std::cout << std::endl;
}

TKernel getElemwiseFunc(TOp op, int depth0, int depth1, int depth2, int rdepth)
{
    (void)depth2;

    if (op == OP_CAST)          return getCastFunc(depth0, rdepth, false);
    if (op == OP_CONVERT_SCALE) return getCastFunc(depth0, rdepth, true);

    if (op == OP_ADD || op == OP_SUB)
    {
        if (depth0 != depth1) return {};   // operands must be the same type
        return op == OP_ADD ? getAddFunc(depth0, rdepth) : getSubFunc(depth0, rdepth);
    }

    // OP_ADDW (addWeighted): a*alpha+b*beta+gamma; operands same type T, result R (T/f32 for small ints
    // + f16/bf16/f32, f64 otherwise). alpha/beta/gamma travel in the instruction's params.
    if (op == OP_ADDW)
    {
        if (depth0 != depth1) return {};
        return getAddWeightedFunc(depth0, rdepth);
    }

    // OP_MUL / OP_DIV / OP_POW: operands same type T; compute in the float work type (rdepth).
    if (op == OP_MUL || op == OP_DIV || op == OP_POW)
    {
        if (depth0 != depth1) return {};
        if (op == OP_MUL) return getMulFunc(depth0, rdepth);
        if (op == OP_POW) return getPowFunc(depth0, rdepth);
        // integer inputs guard divide-by-zero (-> 0); floats do not (a/0 -> inf, matching cv::divide).
        const bool isflt = depth0==CV_16F || depth0==CV_16BF || depth0==CV_32F || depth0==CV_64F;
        return getDivFunc(depth0, rdepth, !isflt);
    }

    // OP_MIN / OP_MAX: T x T -> T.
    if (op == OP_MIN || op == OP_MAX)
    {
        if (depth0 != depth1 || rdepth != depth0) return {};
        return op == OP_MIN ? getMinFunc(depth0, rdepth) : getMaxFunc(depth0, rdepth);
    }

    // OP_ABSDIFF: result is absdiffResultDepth(T) (unsigned same width for signed).
    if (op == OP_ABSDIFF)
    {
        if (depth0 != depth1) return {};
        return getAbsdiffFunc(depth0, rdepth);
    }

    // OP_CMP_*: T x T -> u8 mask (0 / 1 / 255, value via TKernel::flags).
    if (opCategory(op) == CAT_COMPARE)
    {
        if (depth0 != depth1 || rdepth != CV_8U) return {};
        return getCmpFunc(op, depth0);
    }

    // OP_AND / OP_OR / OP_XOR: bit-pattern op, T x T -> T (same depth), dispatched by element size.
    if (op == OP_AND || op == OP_OR || op == OP_XOR)
    {
        if (depth0 != depth1 || rdepth != depth0) return {};
        return getBitwiseFunc(op, CV_ELEM_SIZE1(depth0));
    }

    // OP_NOT: ~x, one input, T -> T (same depth), dispatched by element size.
    if (op == OP_NOT)
    {
        if (rdepth != depth0) return {};
        return getNotFunc(CV_ELEM_SIZE1(depth0));
    }

    // OP_HYPOT / OP_ATAN2: T x T -> T over the float depths (integer inputs are the compiler's job).
    if (op == OP_HYPOT || op == OP_ATAN2)
    {
        if (depth0 != depth1) return {};
        return op == OP_HYPOT ? getHypotFunc(depth0, rdepth) : getAtan2Func(depth0, rdepth);
    }

    // unary math: T -> T over the float depths (math.simd.hpp). Anything else - integer input,
    // widening/narrowing result - is the compiler's job (cast to a float working type first).
    if (op == OP_SQRT || op == OP_EXP || op == OP_LOG || op == OP_SIN || op == OP_COS ||
        op == OP_TANH || op == OP_ERF || op == OP_RELU)
    {
        if (rdepth != depth0) return {};
        return getMathFunc(op, depth0);
    }

    // OP_SELECT: depth0 is the (1-byte, never cast) mask; both branches and dst share one depth.
    if (op == OP_SELECT)
    {
        if (depth1 != depth2 || rdepth != depth1) return {};
        return getSelectFunc(depth0, rdepth);
    }

    // OP_CLAMP: x, lo, hi and dst all share one depth (emitTernary unifies them).
    if (op == OP_CLAMP)
    {
        if (depth1 != depth0 || depth2 != depth0 || rdepth != depth0) return {};
        return getClampFunc(rdepth);
    }

    return {};
}

void mul8u(const uchar* src1, size_t step1, const uchar* src2, size_t step2,
           uchar* dst, size_t step, int width, int height, void* scale)
{
    const double params[] = { scale ? *(const double*)scale : 1.0 };
    ew::TKernel k = ew::getMulFunc(CV_8U, CV_8U);
    k.fptr(src1, step1, 1, src2, step2, 1, nullptr, 0, 0, dst, step, width, height,
           params, k.flags, k.userdata);
}

static void bitwise8u(ew::TOp op, const uchar* src1, size_t step1, const uchar* src2, size_t step2,
                      uchar* dst, size_t step, int width, int height)
{
    const double noparams[4] = {};
    ew::TKernel k = ew::getBitwiseFunc(op, 1);
    CV_Assert(k.fptr != nullptr);
    k.fptr(src1, step1, 1, src2, step2, 1, nullptr, 0, 0, dst, step, width, height,
           noparams, k.flags, k.userdata);
}

void not8u(const uchar* src1, size_t step1, const uchar* /*src2*/, size_t /*step2*/,
           uchar* dst, size_t step, int width, int height, void*)
{
    const double noparams[4] = {};
    ew::TKernel k = ew::getNotFunc(1);
    CV_Assert(k.fptr != nullptr);
    k.fptr(src1, step1, 1, nullptr, 0, 0, nullptr, 0, 0, dst, step, width, height,
           noparams, k.flags, k.userdata);
}

const char* opName(TOp op)
{
    switch (op)
    {
    case OP_NOP:           return "nop";
    case OP_NEG:           return "neg";
    case OP_ABS:           return "abs";
    case OP_NOT:           return "not";
    case OP_SQRT:          return "sqrt";
    case OP_EXP:           return "exp";
    case OP_LOG:           return "log";
    case OP_SIN:           return "sin";
    case OP_COS:           return "cos";
    case OP_TANH:          return "tanh";
    case OP_ERF:           return "erf";
    case OP_RELU:          return "relu";
    case OP_CAST:          return "cast";
    case OP_ADD:           return "add";
    case OP_SUB:           return "sub";
    case OP_MUL:           return "mul";
    case OP_DIV:           return "div";
    case OP_POW:           return "pow";
    case OP_MIN:           return "min";
    case OP_MAX:           return "max";
    case OP_ABSDIFF:       return "absdiff";
    case OP_HYPOT:         return "hypot";
    case OP_ATAN2:         return "atan2";
    case OP_AND:           return "and";
    case OP_OR:            return "or";
    case OP_XOR:           return "xor";
    case OP_CMP_EQ:        return "cmp_eq";
    case OP_CMP_NE:        return "cmp_ne";
    case OP_CMP_LT:        return "cmp_lt";
    case OP_CMP_LE:        return "cmp_le";
    case OP_CMP_GT:        return "cmp_gt";
    case OP_CMP_GE:        return "cmp_ge";
    case OP_CLAMP:         return "clamp";
    case OP_SELECT:        return "select";
    case OP_CONVERT_SCALE: return "convert_scale";
    default:               return "?";
    }
}

ElemwiseCategory opCategory(TOp op)
{
    switch (op)
    {
    case OP_AND: case OP_OR: case OP_XOR: case OP_NOT:
        return CAT_BITWISE;
    case OP_CMP_EQ: case OP_CMP_NE: case OP_CMP_LT:
    case OP_CMP_LE: case OP_CMP_GT: case OP_CMP_GE:
        return CAT_COMPARE;
    case OP_SQRT: case OP_EXP: case OP_LOG:
    case OP_SIN: case OP_COS: case OP_TANH: case OP_ERF: case OP_ATAN2: case OP_RELU:
        return CAT_MATH;
    case OP_CAST: case OP_CONVERT_SCALE:
        return CAT_CAST;
    case OP_SELECT:
        return CAT_SELECT;
    default:
        return CAT_ARITH;   // add/sub/mul/div/pow/min/max/absdiff/neg/abs/clamp
    }
}

static bool depthRepresents(double v, int depth)
{
    if (isFloatDepth(depth)) return true;
    if (v != std::floor(v)) return false;
    switch (depth)
    {
    case CV_8U:  return v >= 0            && v <= 255;
    case CV_8S:  return v >= -128         && v <= 127;
    case CV_16U: return v >= 0            && v <= 65535;
    case CV_16S: return v >= -32768       && v <= 32767;
    case CV_32U: return v >= 0            && v <= 4294967295.0;
    case CV_32S: return v >= -2147483648.0 && v <= 2147483647.0;
    case CV_64U: return v >= 0            && v <= 18446744073709551615.0;
    case CV_64S: return v >= -9223372036854775808.0 && v <= 9223372036854775807.0;
    default:     return false;
    }
}

static void intRange(int depth, double& lo, double& hi)
{
    switch (depth)
    {
    case CV_8U:  lo = 0;                     hi = 255; break;
    case CV_8S:  lo = -128;                  hi = 127; break;
    case CV_16U: lo = 0;                     hi = 65535; break;
    case CV_16S: lo = -32768;                hi = 32767; break;
    case CV_32U: lo = 0;                     hi = 4294967295.0; break;
    case CV_32S: lo = -2147483648.0;         hi = 2147483647.0; break;
    case CV_64U: lo = 0;                     hi = 18446744073709551615.0; break;
    case CV_64S: lo = -9223372036854775808.0; hi = 9223372036854775807.0; break;
    default:     lo = 0;                     hi = 0; break;
    }
}

int promoteArith(int a, int b)
{
    constexpr uint64_t leszlut = 034412243322110ULL;
    constexpr unsigned signlut = 0b1001111110100u;
    constexpr unsigned fltlut  = 0b1111000000u;

    if (a == b) return a;

    int wa = int((leszlut >> (a+1)*3) & 7u), wb = int((leszlut >> (b+1)*3) & 7u);
    int fa = int((fltlut >> (a+1)) & 1u),    fb = int((fltlut >> (b+1)) & 1u);

    if (fa + fb == 0)                          // both integer
    {
        int sa = int((signlut >> (a+1)) & 1u), sb = int((signlut >> (b+1)) & 1u);
        if (sa == sb)                          // same signedness -> the wider one (keeps the sign)
            return wa >= wb ? a : b;
        // mixed sign -> a SIGNED result holding the unsigned operand: the signed width if it is already
        // wider, else one step past the unsigned width; past 64 bits there is no int -> f64.
        int rw = std::max(wa + (1 - sa), wb + (1 - sb));
        constexpr int ilut = (CV_64F << 5*5) | (CV_64S << 4*5) | (CV_32S << 3*5) |
                             (CV_16S << 2*5) | (CV_8S << 1*5) | (CV_8S << 0*5);
        return (ilut >> rw*5) & CV_MAT_DEPTH_MASK;
    }

    // at least one float -> the smallest float covering both operands. Lift each integer operand to the
    // float size class that holds it (8-bit -> 16-float, 16-bit -> 32F, 32/64-bit -> 64F); a float
    // operand keeps its own. Size 2 with exactly one float -> that float (a 8-bit int + 16-float pair);
    // otherwise 32F, or 64F once the size class reaches 4.
    wa += 1 - fa;
    wb += 1 - fb;
    int maxw = std::max(wa, wb);
    if (maxw == 2 && fa + fb == 1)
        return fa*a + (1 - fa)*b;
    return CV_32F + (maxw >= 4);
}

int absdiffResultDepth(int depth)
{
    switch (depth)
    {
    case CV_8S:  return CV_8U;
    case CV_16S: return CV_16U;
    case CV_32S: return CV_32U;
    case CV_64S: return CV_64U;
    default:     return depth;
    }
}

static int promote2(int a, int b)
{
    if (a == b) return a;

    constexpr unsigned lbits = 3, lmask = (1u << lbits) - 1u;
    const uint64_t typelut = (uint64_t)((0ULL << CV_8U*lbits) | (0ULL << CV_8S*lbits) |
                                        (1ULL << CV_16U*lbits) | (1ULL << CV_16S*lbits) |
                                        (2ULL << CV_32U*lbits) | (2ULL << CV_32S*lbits) |
                                        (3ULL << CV_16F*lbits) | (3ULL << CV_16BF*lbits) |
                                        (3ULL << CV_32F*lbits) | (4ULL << CV_64F*lbits) |
                                        (4ULL << CV_64S*lbits) | (4ULL << CV_64U*lbits));
    unsigned pr_a = unsigned((typelut >> (a*lbits)) & lmask);
    unsigned pr_b = unsigned((typelut >> (b*lbits)) & lmask);
    unsigned max_pr = std::max(pr_a, pr_b);
    constexpr unsigned dbits = CV_CN_SHIFT, dmask = (1u << dbits) - 1u;
    const unsigned ctypelut = ((CV_16S << 0*dbits) | (CV_32S << 1*dbits) | (CV_64S << 2*dbits) |
                            (CV_32F << 3*dbits) | (CV_64F << 4*dbits));
    return int((ctypelut >> (max_pr*dbits)) & dmask);
}

static int promoteBitwise(int a, int b)
{
    if (a == EW_DEPTH_NONE) return b;
    if (b == EW_DEPTH_NONE) return a;
    if (a == b) return a;
    return CV_ELEM_SIZE1(a) >= CV_ELEM_SIZE1(b) ? a : b;
}

static int safeWide(int depth)
{
    constexpr unsigned lbits = 3, lmask = (1u << lbits) - 1u;
    const uint64_t typelut = (uint64_t)((0ULL << CV_8U*lbits) | (0ULL << CV_8S*lbits) |
                                        (1ULL << CV_16U*lbits) | (1ULL << CV_16S*lbits) |
                                        (2ULL << CV_32U*lbits) | (2ULL << CV_32S*lbits) |
                                        (3ULL << CV_16F*lbits) | (3ULL << CV_16BF*lbits) |
                                        (3ULL << CV_32F*lbits) | (4ULL << CV_64F*lbits) |
                                        (4ULL << CV_64S*lbits) | (4ULL << CV_64U*lbits));
    unsigned pr_depth = unsigned((typelut >> (depth*lbits)) & lmask);
    constexpr unsigned dbits = CV_CN_SHIFT, dmask = (1u << dbits) - 1u;
    const unsigned ctypelut = ((CV_16S << 0*dbits) | (CV_32S << 1*dbits) | (CV_64S << 2*dbits) |
                              (CV_32F << 3*dbits) | (CV_64F << 4*dbits));
    return int((ctypelut >> (pr_depth*dbits)) & dmask);
}

static size_t appendConstBuf(AutoBuffer<uint64_t, 16>& constbuf, int srcdepth, const void* data, int channels)
{
    const int cn = std::max(1, channels);
    const size_t nbytes = (size_t)cn * CV_ELEM_SIZE1(srcdepth);
    const size_t nu64 = (nbytes + sizeof(uint64_t) - 1) / sizeof(uint64_t);
    const size_t ofs = constbuf.size();
    constbuf.resize(ofs + nu64);
    uchar* dst = (uchar*)(constbuf.data() + ofs);
    if (data) memcpy(dst, data, nbytes); else memset(dst, 0, nbytes);
    return ofs;
}

static int constDoubles(const TExpr& e, int s, AutoBuffer<double, MAX_LOCAL_CN>& buf)
{
    const TExpr::Arg& a = e.arginfo[s];
    const int cn = std::max(1, a.channels);
    buf.resize(cn);
    const uchar* src = (const uchar*)(e.constbuf.data() + a.constofs);
    if (a.srcdepth == CV_64F)
        memcpy(buf.data(), src, (size_t)cn * sizeof(double));   // common (Scalar / parsed literal)
    else
        getConvertFunc(a.srcdepth, CV_64F)(src, 0, nullptr, 0, (uchar*)buf.data(), 0, Size(cn, 1), nullptr);
    return cn;
}

static bool constFits(const TExpr& e, int s, int d)
{
    if (!isFlexConst(e, s)) return true;
    AutoBuffer<double, MAX_LOCAL_CN> v;
    int cn = constDoubles(e, s, v);
    for (int ch = 0; ch < cn; ch++)
        if (!depthRepresents(v[ch], d)) return false;
    return true;
}

int TExpr::emitUnary(TOp op, int a, int rdepth, const Scalar& params)
{
    const int nd = isFlexConst(*this, a) ? EW_DEPTH_NONE : arginfo[a].depth;
    const ElemwiseCategory cat = opCategory(op);

    // NEG and ABS have no kernels of their own - they are compositions over the binary family
    // with a zero constant (flexible, so emitBinary types it as the operand's own type).
    if (op == OP_NEG)
        return emitBinary(OP_SUB, addConst(EW_DEPTH_NONE, Scalar(0.), 1), a, rdepth, params);
    if (op == OP_ABS)
    {
        // peephole: abs(x - y) -> absdiff(x, y), ALWAYS. Strictly speaking the two differ on
        // integers - the literal subtract saturates first (u8: max(x-y, 0); signed: clipped
        // difference), absdiff computes the true |x - y| - but whoever writes abs(a - b) MEANS
        // absdiff; the saturation artifacts are never the desired result. So we deliberately
        // "don't notice" the difference and hand out the useful semantics. The sub is necessarily
        // the last instruction and its result the last temp (abs is emitted right after its
        // argument) - retire both, the moveToOutput manoeuvre.
        if (!prog.empty() && arginfo[a].kind == TEMP &&
            prog.back().op == OP_SUB && prog.back().result == a &&
            arginfo[a].index == ntemps - 1)
        {
            const int x = prog.back().arg0, y = prog.back().arg1;
            prog.pop_back();
            arginfo[a].kind = NONE;
            ntemps--;
            return emitBinary(OP_ABSDIFF, x, y, rdepth, params);
        }
        // abs IS absdiff(a, 0), including the auto result type: a signed |a| lands in the
        // UNSIGNED type of the same width (|-128| = 128 fits u8 exactly; pinning the result to
        // the signed operand type would saturate it to 127). Fully uniform with the peephole.
        return emitBinary(OP_ABSDIFF, a, addConst(EW_DEPTH_NONE, Scalar(0.), 1), rdepth, params);
    }

    int result = rdepth;
    if (result == EW_DEPTH_NONE)
    {
        switch (cat)
        {
        // math is T -> T over the float depths (f16/bf16/f32/f64 kernels exist natively);
        // an integer input computes - and lands - in the float domain
        case CAT_MATH:    result = isFloatDepth(nd) ? nd : CV_32F; break;
        case CAT_BITWISE: result = (nd == EW_DEPTH_NONE) ? CV_32S : nd; break;  // NOT
        default:          result = (nd == EW_DEPTH_NONE) ? CV_32F : nd; break;  // NEG, ABS
        }
    }

    int depth, wide;
    switch (cat)
    {
    case CAT_MATH:
        // T == result over a float depth => the native kernel (incl. the f16/bf16 in-kernel f32
        // hub - no materialized f32 temps). Everything else computes in f32/f64 and casts.
        depth = (isFloatDepth(nd) && nd == result) ? nd
              : (nd == CV_64F || result == CV_64F) ? CV_64F : CV_32F;
        wide = depth;
        break;
    case CAT_BITWISE: depth = result; wide = result; break;
    default:          depth = (nd == EW_DEPTH_NONE) ? result : nd; wide = result; break;  // NEG/ABS
    }

    if (!constFits(*this, a, depth)) depth = (cat == CAT_MATH) ? depth : CV_32F;
    int s0 = isFlexConst(*this, a) ? typedConstFrom(a, depth) : a;
    int c0 = maybeAddCast(s0, depth);

    TKernel k = getElemwiseFunc(op, depth, EW_DEPTH_NONE, EW_DEPTH_NONE, result);
    if (k.fptr)
    {
        int res = addTemp(result);
        addInsn(op, c0, 0, 0, res, k, params);
        return res;
    }
    k = getElemwiseFunc(op, depth, EW_DEPTH_NONE, EW_DEPTH_NONE, wide);
    CV_Assert(k.fptr && "ew: no kernel for this op/type combination");
    int w = addTemp(wide);
    addInsn(op, c0, 0, 0, w, k, params);
    return maybeAddCast(w, result);
}

int TExpr::emitTernary(TOp op, int a, int b, int c, int rdepth)
{
    auto dep = [&](int s) { return isFlexConst(*this, s) ? EW_DEPTH_NONE : arginfo[s].depth; };

    if (op == OP_SELECT)                         // select(mask=a, x=b, y=c)
    {
        // the kernel consumes a 1-byte mask as-is (u8/s8/bool, mask != 0 semantics). Any other
        // mask type - a wider array or a literal - is normalized by an explicit `mask != 0`
        // compare (u8 result), NOT by a value cast (which would saturate/round the values).
        if (isFlexConst(*this, a) || CV_ELEM_SIZE1(arginfo[a].depth) != 1)
            a = emitBinary(OP_CMP_NE, a, addConst(EW_DEPTH_NONE, Scalar(0.), 1), CV_8U, Scalar());
        int result = rdepth != EW_DEPTH_NONE ? rdepth : promoteArith(dep(b), dep(c));
        if (result == EW_DEPTH_NONE) result = CV_32F;
        // a literal branch (select(m, x, 0)) is a flexible const: type it at `result` directly
        // (a value conversion in constbuf), never through an OP_CAST of a depth-less slot
        int sb = isFlexConst(*this, b) ? typedConstFrom(b, result) : maybeAddCast(b, result);
        int sc = isFlexConst(*this, c) ? typedConstFrom(c, result) : maybeAddCast(c, result);
        int res = addTemp(result);
        addInsn(OP_SELECT, a, sb, sc, res);
        return res;
    }

    // clamp(x,lo,hi): unify all three operands at `result` (compute == result, no wide fallback).
    // The x operand dominates the auto type: clamp(u8_img, 10, 200) must stay u8, and literal
    // bounds are flexible consts typed at `result` directly (never OP_CAST of a depth-less slot).
    int result = rdepth != EW_DEPTH_NONE ? rdepth
                                         : promoteArith(promoteArith(dep(a), dep(b)), dep(c));
    if (result == EW_DEPTH_NONE) result = CV_32F;
    auto typed = [&](int s) {
        return isFlexConst(*this, s) ? typedConstFrom(s, result) : maybeAddCast(s, result);
    };
    int c0 = typed(a), c1 = typed(b), c2 = typed(c);
    TKernel k = getElemwiseFunc(op, result, result, result, result);
    CV_Assert(k.fptr && "ew: no kernel for this op/type combination");
    int res = addTemp(result);
    addInsn(op, c0, c1, c2, res, k);
    return res;
}

int TExpr::moveToOutput(int temp, int out)
{
    const int ninsn = (int)prog.size();
    int producer = -1;
    bool usedAsArg = false;
    for (int i = 0; i < ninsn; i++)
    {
        const TExpr::Insn& ins = prog[i];
        if (ins.result == temp) producer = i;
        if (ins.arg0 == temp || ins.arg1 == temp || ins.arg2 == temp) usedAsArg = true;
    }
    if (arginfo[temp].kind == TEMP && producer >= 0 && !usedAsArg &&
        arginfo[temp].depth == arginfo[out].depth)
    {
        // MOVE semantics: redirect `temp`'s single producer to write `out` directly, then leave the
        // source slot EMPTY - reclassify it to NONE. A NONE slot gets no physical buffer (compile's
        // liveness only walks TEMP slots) and is skipped everywhere in exec, so no stale dead-TEMP slot
        // remains (which, buffer or not, would still cost per-tile setup in the general path) - and no
        // slot removal / index renumbering is needed. This keeps single-op programs at zero temps =>
        // compile()'s no-temp early-out (zero heap traffic) still fires. Every caller moves the result
        // it JUST emitted, so `temp` is always the last-created temp - decrement ntemps to retire its
        // index and keep the temp indices dense (0..ntemps-1) for compile()'s liveness arrays.
        CV_Assert(arginfo[temp].index == ntemps - 1);
        prog[producer].result = out;
        arginfo[temp].kind = NONE;
        ntemps--;
        return out;
    }
    addInsn(OP_CAST, temp, 0, 0, out);                     // same/different depth copy into `out`
    return out;
}

void TExpr::compile()
{
    const int ninsn = (int)prog.size();

    // Kernels are bound eagerly by addInsn at build time, so there is no binding pass here - compile()
    // only counts consts and packs temp buffers.

    // Materialize consts: convert each live CONST's source values (still in `srcdepth` at constofs)
    // to its resolved `depth`, appending the result to constbuf; constofs then points at the converted
    // values and srcdepth becomes the resolved depth. Flexible literals (depth==NONE) are dead - the
    // emit* layers replaced them with typed copies - and are skipped. nconsts sizes exec's per-const
    // header buffer and gates the fast path. (getConvertFunc may reallocate constbuf, so snapshot the
    // source bytes first.)
    const int nslots = (int)arginfo.size();
    nconsts = 0;
    for (int s = 1; s < nslots; s++)
    {
        Arg& a = arginfo[s];
        if (a.kind != CONST || a.depth == EW_DEPTH_NONE) continue;
        const int cn = std::max(1, a.channels), sd = a.srcdepth, dd = a.depth;
        const size_t sesz = CV_ELEM_SIZE1(sd), desz = CV_ELEM_SIZE1(dd);
        AutoBuffer<uchar, 64> srcbytes((size_t)cn * sesz);
        memcpy(srcbytes.data(), (const uchar*)(constbuf.data() + a.constofs), (size_t)cn * sesz);
        const size_t ofs = appendConstBuf(constbuf, dd, nullptr, cn);   // reserve converted region
        uchar* dst = (uchar*)(constbuf.data() + ofs);
        if (sd == dd) memcpy(dst, srcbytes.data(), (size_t)cn * desz);
        else getConvertFunc(sd, dd)(srcbytes.data(), 0, nullptr, 0, dst, 0, Size(cn, 1), nullptr);
        a.constofs = ofs; a.srcdepth = dd;
        nconsts++;
    }

    // ---- liveness: pack temps into a minimal set of reusable physical buffers. A program with no
    //      temps (single-op add/sub/mul/...) needs none of this - early out with ZERO heap traffic,
    //      so building such a program (the dominant cv::add-style call) allocates nothing. The temp
    //      case uses stack-backed AutoBuffers (inline for typical small expressions). ----
    nbuffers = 0;
    bufEszPrefix.resize(1); bufEszPrefix[0] = 0;
    capElems = INT_MAX;                       // no temps => exec runs each tile in one block, no scratch
    if (ntemps == 0) return;

    AutoBuffer<int, 32> tempOfSlot(nslots);
    for (int s = 0; s < nslots; s++) tempOfSlot[s] = -1;
    for (int s = 1; s < nslots; s++)
        if (arginfo[s].kind == TEMP) tempOfSlot[s] = arginfo[s].index;

    AutoBuffer<int, 16> lastUse(ntemps);
    for (int t = 0; t < ntemps; t++) lastUse[t] = -1;
    for (int i = 0; i < ninsn; i++)
    {
        const TExpr::Insn& ins = prog[i];
        int as[3] = { ins.arg0, ins.arg1, ins.arg2 };
        for (int k = 0; k < 3; k++)
            if (tempOfSlot[as[k]] >= 0) lastUse[tempOfSlot[as[k]]] = i;
    }

    bufferOfTemp.resize(ntemps);
    for (int t = 0; t < ntemps; t++) bufferOfTemp[t] = -1;
    AutoBuffer<int, 16> freeBufs(ntemps);
    int nfree = 0, nbuf = 0;
    for (int i = 0; i < ninsn; i++)
    {
        const TExpr::Insn& ins = prog[i];
        int rt = tempOfSlot[ins.result];
        if (rt >= 0 && bufferOfTemp[rt] < 0)
            bufferOfTemp[rt] = nfree > 0 ? freeBufs[--nfree] : nbuf++;
        int as[3] = { ins.arg0, ins.arg1, ins.arg2 };
        for (int k = 0; k < 3; k++)
        {
            int t = tempOfSlot[as[k]];
            if (t >= 0 && lastUse[t] == i)
            {
                freeBufs[nfree++] = bufferOfTemp[t];
                lastUse[t] = -1;   // the same temp may be several args of this insn ("d*d") -
                                   // release its buffer once, or freeBufs overflows/double-frees
            }
        }
    }

    nbuffers = nbuf;

    // Byte layout of the physical temp buffers, per output element: prefix sums of each buffer's
    // max element size. bufEszPrefix[b]*region = buffer b's byte offset in the scratch; [nbuffers] =
    // total temp bytes/element. Precomputed here (depths are build-time) so exec()/its fast path
    // never recompute it per call, and the fast path can size its scratch in O(1).
    bufEszPrefix.resize(nbuffers + 1);
    for (int b = 0; b <= nbuffers; b++) bufEszPrefix[b] = 0;
    for (int s = 1; s < nslots; s++)
        if (arginfo[s].kind == TEMP)
        {
            int b = bufferOfTemp[arginfo[s].index], e = (int)CV_ELEM_SIZE1(arginfo[s].depth);
            if (e > bufEszPrefix[b + 1]) bufEszPrefix[b + 1] = e;     // max elem size in buffer b
        }
    for (int b = 0; b < nbuffers; b++) bufEszPrefix[b + 1] += bufEszPrefix[b];   // -> prefix sums

    // L1 fragment cap: # elements one ~16KB scratch fragment holds (exec fragments the strip so the
    // intermediates stay hot). Pure function of the temp byte layout, hence computed here once.
    const int totalEsz = bufEszPrefix[nbuffers];
    capElems = totalEsz > 0 ? std::max(64, (16 * 1024) / totalEsz) : INT_MAX;
}

static void matLogical(const Mat& m, MatShape& shp, EwSteps& step, int& esz1)
{
    esz1 = (int)m.elemSize1();
    int nd = m.dims, cn = m.channels();
    shp.resize(nd + 1);
    for (int i = 0; i < nd; i++)
    {
        shp[i] = m.size[i];
        step[i] = m.step[i] / esz1;
    }
    shp[nd] = cn;
    step[nd] = 1;
}

static bool broadcastShape(const MatShape* shps, int K, MatShape& out)
{
    int nd = 0;
    for (int k = 0; k < K; k++) nd = std::max(nd, shps[k].dims);
    out.assign(nd, 1);
    for (int k = 0; k < K; k++)
    {
        const MatShape& s = shps[k];
        int off = nd - s.dims;
        for (int i = 0; i < s.dims; i++)
        {
            int d = s[i], &o = out[off + i];
            if (o == 1) o = d;
            else if (d != 1 && d != o) return false;
        }
    }
    return true;
}

static int opCost(TOp op)
{
    switch (op)
    {
    case OP_ADD: case OP_SUB: case OP_MUL: case OP_MIN: case OP_MAX:
    case OP_ABSDIFF: case OP_AND: case OP_OR: case OP_XOR: case OP_NOT:
    case OP_NEG: case OP_ABS: case OP_CAST: case OP_RELU: case OP_SELECT:
    case OP_CMP_EQ: case OP_CMP_NE: case OP_CMP_LT:
    case OP_CMP_LE: case OP_CMP_GT: case OP_CMP_GE: return 1;
    case OP_DIV: case OP_SQRT: case OP_HYPOT: case OP_CONVERT_SCALE: return 3;
    case OP_SIN: case OP_COS: case OP_TANH: case OP_ERF: case OP_ATAN2:
    case OP_EXP: case OP_LOG: case OP_POW:           return 6;
    default:                                         return 3;
    }
}

void TExpr::clear()
{
    prog.allocate(0);
    arginfo.allocate(0);
    bufferOfTemp.allocate(0);
    constbuf.allocate(0);
    ninputs = noutputs = ntemps = nbuffers = 0;
    Arg none;                       // slot 0: the reserved empty operand (kind == NONE)
    arginfo.push_back(none);
}

void TExpr::dump(std::ostream& os) const
{
    auto dn = [](int d) -> const char* {
        switch (d) {
        case EW_DEPTH_NONE: return "flex";
        case CV_8U:  return "u8";  case CV_8S:  return "s8";
        case CV_16U: return "u16"; case CV_16S: return "s16";
        case CV_32U: return "u32"; case CV_32S: return "s32";
        case CV_64U: return "u64"; case CV_64S: return "s64";
        case CV_16F: return "f16"; case CV_16BF:return "bf16";
        case CV_32F: return "f32"; case CV_64F: return "f64";
        case CV_Bool:return "bool";
        default:     return "?"; }
    };
    auto kn = [](ArgKind k) -> const char* {
        switch (k) { case NONE: return "none"; case INPUT: return "in"; case CONST: return "const";
                     case TEMP: return "temp"; case OUTPUT: return "out"; } return "?";
    };
    os << "TExpr: inputs=" << ninputs << " outputs=" << noutputs << " temps=" << ntemps
       << " buffers=" << nbuffers << " consts=" << nconsts << " insns=" << (int)prog.size() << "\n";
    os << "  slots:\n";
    for (int s = 0; s < (int)arginfo.size(); s++) {
        const Arg& a = arginfo[s];
        os << "    [" << s << "] " << kn(a.kind);
        if (a.kind != NONE) os << " " << dn(a.depth);
        if (a.kind == INPUT || a.kind == OUTPUT || a.kind == TEMP) os << " idx=" << a.index;
        if (a.kind == CONST) {
            const int cn = std::max(1, a.channels);
            AutoBuffer<double, MAX_LOCAL_CN> v(cn);
            const uchar* src = (const uchar*)(constbuf.data() + a.constofs);
            if (a.srcdepth == CV_64F) memcpy(v.data(), src, (size_t)cn * sizeof(double));
            else getConvertFunc(a.srcdepth, CV_64F)(src, 0, nullptr, 0, (uchar*)v.data(), 0, Size(cn, 1), nullptr);
            os << " cn=" << cn << " src=" << dn(a.srcdepth) << " {";
            for (int c = 0; c < cn; c++) os << (c ? "," : "") << v[c];
            os << "}";
        }
        os << "\n";
    }
    os << "  prog:\n";
    for (int i = 0; i < (int)prog.size(); i++) {
        const Insn& ins = prog[i];
        os << "    " << i << ": " << opName(ins.op) << "(" << ins.arg0;
        if (ins.arg1) os << ", " << ins.arg1;
        if (ins.arg2) os << ", " << ins.arg2;
        os << ") -> " << ins.result;
        if (ins.kernel.flags) os << " kflags=" << ins.kernel.flags;
        if (ins.params[0] != 1.0 || ins.params[1] != 0.0)
            os << " params=[" << ins.params[0] << "," << ins.params[1] << "," << ins.params[2] << "]";
        if (!ins.kernel.fptr) os << " [UNBOUND]";
        os << "\n";
    }
}

int TExpr::addInput(int depth)
{
    Arg a; a.kind = INPUT; a.depth = depth; a.index = ninputs++;
    arginfo.push_back(a); return (int)arginfo.size() - 1;
}

int TExpr::addOutput(int depth)
{
    Arg a; a.kind = OUTPUT; a.depth = depth; a.index = noutputs++;
    arginfo.push_back(a); return (int)arginfo.size() - 1;
}

int TExpr::addTemp(int depth)
{
    Arg a; a.kind = TEMP; a.depth = depth; a.index = ntemps++;
    arginfo.push_back(a); return (int)arginfo.size() - 1;
}

int TExpr::addConst(int depth, const Scalar& v, int channels)
{
    CV_Assert(channels <= 4);
    Arg a; a.kind = CONST; a.depth = depth; a.channels = channels; a.srcdepth = CV_64F;
    a.constofs = appendConstBuf(constbuf, CV_64F, v.val, channels);
    arginfo.push_back(a); return (int)arginfo.size() - 1;
}

int TExpr::addConst(int depth, int srcdepth, const void* data, int channels)
{
    // A CONST is a broadcast scalar - capped at 4 channels (a Scalar). Need more? Pass a 0-D Mat with
    // the desired channel count as an INPUT: broadcasting handles it, and it isn't limited to 4.
    CV_Assert(channels <= 4);
    Arg a; a.kind = CONST; a.depth = depth; a.channels = channels; a.srcdepth = srcdepth;
    a.constofs = appendConstBuf(constbuf, srcdepth, data, channels);
    arginfo.push_back(a); return (int)arginfo.size() - 1;
}

int TExpr::typedConstFrom(int srcSlot, int depth)
{
    const Arg& src = arginfo[srcSlot];
    Arg a; a.kind = CONST; a.depth = depth; a.channels = src.channels;
    a.srcdepth = src.srcdepth; a.constofs = src.constofs;    // shares the source region
    arginfo.push_back(a); return (int)arginfo.size() - 1;
}

int TExpr::addInsn(TOp op, int a0, int a1, int a2, int result, const TKernel& kernel, const Scalar& params)
{
    TExpr::Insn ins; ins.op = op; ins.arg0 = a0; ins.arg1 = a1; ins.arg2 = a2; ins.result = result;
    ins.params = params; ins.kernel = kernel;
    prog.push_back(ins);
    return (int)prog.size() - 1;
}

int TExpr::addInsn(TOp op, int a0, int a1, int a2, int result, const Scalar& params)
{
    int d0 = a0 ? arginfo[a0].depth : EW_DEPTH_NONE;
    int d1 = a1 ? arginfo[a1].depth : EW_DEPTH_NONE;
    int d2 = a2 ? arginfo[a2].depth : EW_DEPTH_NONE;
    TKernel k = getElemwiseFunc(op, d0, d1, d2, arginfo[result].depth);
    CV_Assert(k.fptr && "ew: no kernel for this op/type combination");
    return addInsn(op, a0, a1, a2, result, k, params);
}

int TExpr::maybeAddCast(int arg, int depth)
{
    if (arginfo[arg].depth == depth) return arg;
    int t = addTemp(depth);
    addInsn(OP_CAST, arg, 0, 0, t);
    return t;
}

static inline void runInsn(const TExpr::Insn& ins,
                           const void* p0, size_t y0, size_t x0,
                           const void* p1, size_t y1, size_t x1,
                           const void* p2, size_t y2, size_t x2,
                           void* pr, size_t yr, int w, int h)
{
    int code = ins.kernel.fptr(p0, y0, x0, p1, y1, x1, p2, y2, x2, pr, yr, w, h,
                                ins.params.val, ins.kernel.flags, ins.kernel.userdata);
    CV_Assert(code >= 0);
}

void TExpr::outputShape(const Mat* const* inputs, MatShape& spatial, int& channels) const
{
    // Fast path: every real input shares one shape + channel count => the result IS inputs[0]'s
    // (consts add no dims/channels). Otherwise re-broadcast the logical (spatial + channel) shapes.
    const int rcn0 = ninputs >= 1 ? inputs[0]->channels() : 1;
    bool sameShape = ninputs >= 1;
    for (int i = 1; sameShape && i < ninputs; i++)
    {
        const Mat& a = *inputs[i];
        if (a.dims != inputs[0]->dims || a.channels() != rcn0) sameShape = false;
        else for (int d = 0; d < a.dims; d++) if (a.size[d] != inputs[0]->size[d]) { sameShape = false; break; }
    }
    if (sameShape) { spatial = inputs[0]->size; channels = rcn0; return; }

    AutoBuffer<MatShape, 16> bshapes(std::max(ninputs, 1));
    MatShape shp; EwSteps step; int esz1;
    for (int i = 0; i < ninputs; i++) { matLogical(*inputs[i], shp, step, esz1); bshapes[i] = shp; }
    MatShape full;
    CV_Assert(broadcastShape(bshapes.data(), ninputs, full) && "ew: inputs not broadcast-compatible");
    const int ndFull = (int)full.size();
    channels = full[ndFull - 1];
    spatial = full; spatial.resize(ndFull - 1);
}

void TExpr::outputShape(const Mat* inputs, MatShape& spatial, int& channels) const
{
    AutoBuffer<const Mat*, 16> ptrs(std::max(ninputs, 1));
    for (int i = 0; i < ninputs; i++) ptrs[i] = &inputs[i];
    outputShape(ptrs.data(), spatial, channels);
}

void TExpr::exec(const Mat* inputs, Mat* outputs)
{
    AutoBuffer<const Mat*, 16> ptrs(std::max(ninputs, 1));
    for (int i = 0; i < ninputs; i++) ptrs[i] = &inputs[i];
    exec(ptrs.data(), outputs);
}

void makeBinaryArithProgram(TExpr& p, TOp op, int depth0, int depth1, int rdepth,
                            int maskDepth, double scale)
{
    p.clear();
    if (rdepth < 0)                                          // rdepth == -1 => auto (like cv::'s dtype=-1)
    {
        if (opCategory(op) == CAT_COMPARE)
            rdepth = CV_8U;                                  // compare -> u8 mask
        else
        {
            rdepth = promoteArith(depth0, depth1);
            if (op == OP_ABSDIFF) rdepth = absdiffResultDepth(rdepth);   // signed |a-b| -> unsigned same width
        }
    }
    const bool masked = maskDepth != EW_DEPTH_NONE;
    int sIn0  = p.addInput(depth0);
    int sIn1  = p.addInput(depth1);
    int sMask = masked ? p.addInput(maskDepth) : 0;
    int sOut  = p.addOutput(rdepth);

    int r = p.emitBinary(op, sIn0, sIn1, rdepth, Scalar(scale));
    if (masked)
        p.addInsn(OP_SELECT, sMask, r, sOut, sOut);          // dst = mask ? r : dst
    else
        p.moveToOutput(r, sOut);                             // straight into the output, no dead temp

    p.compile();    // pack temp buffers + count consts (kernels already bound by addInsn)
}

void makeAddWeightedProgram(TExpr& p, int depth0, int depth1, int rdepth,
                            double alpha, double beta, double gamma)
{
    p.clear();
    int sA   = p.addInput(depth0);
    int sB   = p.addInput(depth1);
    int sOut = p.addOutput(rdepth);
    int r = p.emitBinary(OP_ADDW, sA, sB, rdepth, Scalar(alpha, beta, gamma));
    p.moveToOutput(r, sOut);
    p.compile();    // pack temp buffers + count consts (kernels already bound by addInsn)
}

Token next()
    {
        while (pos < s.size() && std::isspace((unsigned char)s[pos])) pos++;
        Token t;
        if (pos >= s.size()) { t.type = T_END; return t; }

        char c = s[pos];

        if (c == '{')                       // input placeholder {N}
        {
            pos++;
            size_t start = pos;
            while (pos < s.size() && s[pos] != '}') pos++;
            CV_Assert(pos < s.size() && "ew::expression: unterminated '{'");
            t.type = T_INPUT;
            t.input = std::atoi(std::string(s.substr(start, pos - start)).c_str());
            pos++;                          // consume '}'
            return t;
        }
        if (std::isdigit((unsigned char)c) || (c == '.' && pos + 1 < s.size() &&
                                               std::isdigit((unsigned char)s[pos + 1])))
        {
            char* end = nullptr;
            std::string num(s.substr(pos));
            t.type = T_NUM;
            t.num = std::strtod(num.c_str(), &end);
            pos += (size_t)(end - num.c_str());
            return t;
        }
        if (isIdentStart(c))
        {
            size_t start = pos;
            while (pos < s.size() && isIdentChar(s[pos])) pos++;
            t.type = T_IDENT;
            t.text.assign(s.substr(start, pos - start));
            return t;
        }
        switch (c)
        {
        case '(': pos++; t.type = T_LPAREN; return t;
        case ')': pos++; t.type = T_RPAREN; return t;
        case ',': pos++; t.type = T_COMMA;  return t;
        case ';': pos++; t.type = T_SEMI;   return t;
        }
        // multi/!single-char operators
        auto two = [&](const char* op) {
            return pos + 1 < s.size() && s[pos] == op[0] && s[pos + 1] == op[1];
        };
        t.type = T_OP;
        if (two("<=") || two(">=") || two("==") || two("!=") || two("**"))
        { t.text.assign(s.substr(pos, 2)); pos += 2; return t; }
        if (c == '=') { pos++; t.type = T_ASSIGN; return t; }
        CV_Assert(std::strchr("+-*/<>&|^!?:", c) && "ew::expression: unexpected character");
        t.text.assign(1, c); pos++;
        return t;
    }

static int binPrec(const std::string& op)
{
    if (op == "**") return 8;              // power binds tighter than '*'; RIGHT-associative
    if (op == "*" || op == "/") return 7;
    if (op == "+" || op == "-") return 6;
    if (op == "<" || op == "<=" || op == ">" || op == ">=") return 5;
    if (op == "==" || op == "!=") return 4;
    if (op == "&") return 3;
    if (op == "^") return 2;
    if (op == "|") return 1;
    return -1;
}

static TOp binOp(const std::string& op)
{
    if (op == "**") return OP_POW;
    if (op == "+")  return OP_ADD;
    if (op == "-")  return OP_SUB;
    if (op == "*")  return OP_MUL;
    if (op == "/")  return OP_DIV;
    if (op == "<")  return OP_CMP_LT;
    if (op == "<=") return OP_CMP_LE;
    if (op == ">")  return OP_CMP_GT;
    if (op == ">=") return OP_CMP_GE;
    if (op == "==") return OP_CMP_EQ;
    if (op == "!=") return OP_CMP_NE;
    if (op == "&")  return OP_AND;
    if (op == "|")  return OP_OR;
    if (op == "^")  return OP_XOR;
    CV_Error(Error::StsParseError, "ew::expression: bad binary operator");
}

static int typeDepth(const std::string& name)
{
    if (name == "float")    return CV_32F;
    if (name == "double")   return CV_64F;
    if (name == "half" || name == "float16") return CV_16F;
    if (name == "bfloat16") return CV_16BF;
    if (name == "uint8")    return CV_8U;
    if (name == "int8")     return CV_8S;
    if (name == "uint16")   return CV_16U;
    if (name == "int16")    return CV_16S;
    if (name == "uint32")   return CV_32U;
    if (name == "int32")    return CV_32S;
    if (name == "uint64")   return CV_64U;
    if (name == "int64")    return CV_64S;
    return -1;
}

static TOp fnOp(const std::string& name, int& arity)
{
    struct E { const char* n; TOp op; };
    static const E unary[]  = { {"abs",OP_ABS},{"sqrt",OP_SQRT},{"exp",OP_EXP},{"log",OP_LOG},
                                {"sin",OP_SIN},{"cos",OP_COS},{"tanh",OP_TANH},{"erf",OP_ERF},
                                {"relu",OP_RELU} };
    static const E binary[] = { {"max",OP_MAX},{"min",OP_MIN},{"pow",OP_POW},{"absdiff",OP_ABSDIFF},
                                {"hypot",OP_HYPOT},{"mag",OP_HYPOT},     // mag = the cv::magnitude-flavored alias
                                {"atan2",OP_ATAN2} };
    static const E tern[]   = { {"clamp",OP_CLAMP},{"select",OP_SELECT} };
    for (const E& e : unary)  if (name == e.n) { arity = 1; return e.op; }
    for (const E& e : binary) if (name == e.n) { arity = 2; return e.op; }
    for (const E& e : tern)   if (name == e.n) { arity = 3; return e.op; }
    arity = 0; return OP_NOP;
}

void expect(TokType t, const char* what)
    {
        CV_Assert(cur.type == t && what);
        advance();
    }

int parsePrimary()
    {
        if (cur.type == T_NUM)   { int s = e.addConst(EW_DEPTH_NONE, Scalar(cur.num), 1); advance(); return s; }
        if (cur.type == T_INPUT) { int idx = cur.input; advance();
                                   CV_Assert(idx >= 0 && idx < ninputs && "ew::expression: input index out of range");
                                   return inputSlot[idx]; }
        if (cur.type == T_LPAREN){ advance(); int x = parseTernary(); expect(T_RPAREN, "expected ')'"); return x; }
        if (cur.type == T_IDENT)
        {
            std::string name = cur.text; advance();
            if (cur.type != T_LPAREN)             // variable reference
            {
                auto it = env.find(name);
                CV_Assert(it != env.end() && "ew::expression: undefined name");
                return it->second;
            }
            advance();                            // consume '('
            // every function takes <= 3 args (clamp/select); a stack buffer avoids a std::vector
            // heap alloc. The {} is for gcc's -Wmaybe-uninitialized only.
            std::array<int, 8> args = {}; int nargs = 0;
            if (cur.type != T_RPAREN)
            {
                args[nargs++] = parseTernary();
                while (cur.type == T_COMMA) { advance();
                    CV_Assert(nargs < (int)args.size() && "ew::expression: too many arguments");
                    args[nargs++] = parseTernary(); }
            }
            expect(T_RPAREN, "expected ')'");

            int td = typeDepth(name);
            if (td >= 0)
            {
                CV_Assert(nargs == 1);                       // type cast: just convert the operand
                int s = args[0];
                return isFlexConst(s) ? e.typedConstFrom(s, td)
                                      : e.maybeAddCast(s, td);
            }

            int arity = 0; TOp op = fnOp(name, arity);
            CV_Assert(arity != 0 && "ew::expression: unknown function");
            CV_Assert(nargs == arity && "ew::expression: wrong number of arguments");
            if (arity == 1) return e.emitUnary(op, args[0]);
            if (arity == 2) return e.emitBinary(op, args[0], args[1]);
            return e.emitTernary(op, args[0], args[1], args[2]);
        }
        CV_Error(Error::StsParseError, "ew::expression: expected a primary expression");
    }

int parseUnary()
    {
        if (isOp("-") || isOp("!"))
        {
            std::string op = cur.text; advance();
            int operand = parseUnary();
            // constant-fold a leading sign so that "-1.5" does not need an OP_NEG kernel
            if (op == "-" && isFlexConst(operand))
            {
                AutoBuffer<double, MAX_LOCAL_CN> v; int cn = constDoubles(e, operand, v);
                Scalar neg; for (int i = 0; i < cn && i < 4; i++) neg[i] = -v[i];
                return e.addConst(EW_DEPTH_NONE, neg, std::min(cn, 4));
            }
            return e.emitUnary(op == "-" ? OP_NEG : OP_NOT, operand);
        }
        return parsePrimary();
    }

int parseExpr(int minPrec)
    {
        int left = parseUnary();
        while (cur.type == T_OP)
        {
            int p = binPrec(cur.text);
            if (p < minPrec) break;
            std::string op = cur.text; advance();
            // '**' is right-associative (a ** b ** c == a ** (b ** c)): recurse at the SAME
            // precedence so the right side swallows further '**'s; everything else at p+1.
            int right = parseExpr(op == "**" ? p : p + 1);
            left = e.emitBinary(binOp(op), left, right);
        }
        return left;
    }

int parseTernary()
    {
        int cond = parseExpr(0);
        if (!isOp("?")) return cond;
        advance();
        int thenv = parseTernary();
        CV_Assert(isOp(":") && "ew::expression: expected ':' in a ?: conditional");
        advance();
        int elsev = parseTernary();               // right-associative chain
        return e.emitTernary(OP_SELECT, cond, thenv, elsev);
    }

void parseResult()
    {
        if (cur.type == T_LPAREN)
        {
            // backtrack point: save the lexer AND the program length, since the trial parse below
            // emits instructions/slots that must be rolled back if this turns out NOT to be a tuple.
            Lexer save = lex; Token savedCur = cur;
            size_t nInsn = e.prog.size(), nArg = e.arginfo.size(); int nTemp = e.ntemps;
            advance();
            int e0 = parseTernary();
            if (cur.type == T_COMMA)
            {
                e.output(e0);
                while (cur.type == T_COMMA) { advance(); e.output(parseTernary()); }
                expect(T_RPAREN, "expected ')'");
                return;
            }
            lex = save; cur = savedCur;                   // not a tuple -> undo the trial parse
            e.prog.resize(nInsn); e.arginfo.resize(nArg); e.ntemps = nTemp;
        }
        e.output(parseTernary());
    }

void parse()
    {
        while (true)
        {
            if (cur.type == T_IDENT)
            {
                Lexer save = lex; Token savedCur = cur;   // lexer-only backtrack (nothing emitted yet)
                std::string name = cur.text; advance();
                if (cur.type == T_ASSIGN)
                {
                    advance();
                    env[name] = parseTernary();
                    expect(T_SEMI, "expected ';' after assignment");
                    continue;
                }
                lex = save; cur = savedCur;               // not an assignment
            }
            parseResult();
            if (cur.type == T_SEMI) advance();
            break;
        }
        CV_Assert(cur.type == T_END && "ew::expression: trailing tokens");
        CV_Assert(e.noutputs > 0 && "ew::expression: no result");
    }

void texpr(const std::string& expr, InputArrayOfArrays _inputs, OutputArrayOfArrays _outputs)
{
    using namespace cv::ew;
    CV_INSTRUMENT_REGION();
    CV_Assert(_inputs.kind() == _InputArray::STD_VECTOR_MAT);
    const std::vector<Mat>& inps = *(const std::vector<Mat>*)_inputs.getObj();
    const int ninputs = (int)inps.size();

    // Input depths are known now, so build a fully-typed program straight away: one INPUT slot per
    // input (slot index i carries input i's depth), then parse the expression into instructions.
    TExpr e;
    AutoBuffer<int> islot(std::max(ninputs, 1));
    for (int i = 0; i < ninputs; i++) islot[i] = e.addInput(inps[i].depth());
    Parser(expr, e, islot.data(), ninputs).parse();
    e.compile();

    auto kind = _outputs.kind();
    if (kind == _InputArray::STD_VECTOR_MAT) {
        std::vector<Mat>& outs = _outputs.getMatVecRef();
        outs.resize(e.noutputs);
        e.exec(inps.data(), outs.data());
    } else {
        CV_Error(Error::StsNotImplemented, "vector<Mat> is expected as output of texpr");
    }
}

ruct CV_EXPORTS TExpr
{
    // Static (shape-independent) classification of an arg slot.
    enum ArgKind
    {
        NONE = 0,   // the reserved empty operand (slot 0)
        INPUT,
        CONST,
        TEMP,
        OUTPUT
    };

    struct Arg
    {
        ArgKind kind = NONE;
        int depth = EW_DEPTH_NONE;  // EW_DEPTH_NONE on a CONST = "flexible" (the emit* layers type it per use)
        int channels = 0;           // for CONST: # of per-channel values (0/1 => single broadcast value)
        int index = -1;             // input#/output#/temp-id depending on kind
        // CONST only: the constant's values live in TExpr::constbuf (in `srcdepth` until compile(),
        // which converts them to the resolved `depth`). constofs = offset into constbuf, in uint64_t
        // units. A per-channel scalar of any width is carried this way (no 4-channel Scalar limit).
        int srcdepth = EW_DEPTH_NONE;
        size_t constofs = 0;
    };

    // One compiled instruction: the op + arg-table indices + a resolved kernel (TKernel: fptr +
    // userdata + flags). Every kernel uses the SAME calling convention (the universal KernelFunc);
    // OP_CAST / OP_CONVERT_SCALE bind castKernel, which carries the core convert BinaryFunc in
    // kernel.userdata. `params` is the per-instruction scalar block (mul/div scale in params[0];
    // convert_scale {scale, offset} in params[0..1]). The kernel is bound by addInsn at build time.
    struct Insn
    {
        TKernel kernel;
        TOp op = OP_NOP;
        int arg0 = 0, arg1 = 0, arg2 = 0, result = 0;
        Scalar params = Scalar(1);          // op scalars; params[0]=scale defaults to 1 (identity)
    };

    AutoBuffer<Insn, 16>   prog;             // instructions, in execution order (kernels bound by addInsn)
    AutoBuffer<Arg, 16>    arginfo;          // slot 0 is always NONE
    AutoBuffer<uint64_t, 16> constbuf;       // CONST value store (uint64-aligned slots); Arg::constofs
                                             // indexes it. Source values on build, resolved-type after compile()
    int ninputs = 0;
    int noutputs = 0;
    int ntemps = 0;
    int nbuffers = 0;                        // distinct physical temp buffers after liveness
    int nconsts = 0;                         // # materialized CONST slots (set by compile()) - sizes
                                             // the const store; nconsts==0 enables exec()'s fast path
    int capElems = 0;                        // # elements one ~16KB L1 scratch fragment holds (set by
                                             // compile()); INT_MAX when there are no temps.
    AutoBuffer<int, 16>    bufferOfTemp;     // temp-id -> physical buffer id
    AutoBuffer<int, 8>     bufEszPrefix;     // [nbuffers+1] prefix sums of each physical temp buffer's
                                             // elem size (set by compile()); [nbuffers] = temp bytes
                                             // per output element.

    TExpr();
    void clear();                            // reset to an empty program (slot 0 = NONE)
    void dump(std::ostream& os) const;       // human-readable slot table + instruction list (debug)

    // ---- operand / instruction builders (return the new slot / instruction index) ----
    int  addInput(int depth);
    int  addConst(int depth, const Scalar& v, int channels = 1);   // source = Scalar (f64); depth NONE => flexible
    int  addConst(int depth, int srcdepth, const void* data, int channels);   // source = native bytes
    // A typed copy of a flexible CONST `srcSlot` at the resolved `depth` (shares its source values;
    // compile() converts them). Used by the emit* layers / parser cast where addConst(depth, cval) was.
    int  typedConstFrom(int srcSlot, int depth);
    int  addTemp(int depth);
    int  addOutput(int depth);
    // addInsn resolves the instruction's kernel NOW from the operand/result depths (final at build
    // time). The 2nd form takes a pre-resolved kernel, for callers that already probed getElemwiseFunc.
    int  addInsn(TOp op, int a0, int a1, int a2, int result, const Scalar& params = Scalar(1));
    int  addInsn(TOp op, int a0, int a1, int a2, int result, const TKernel& kernel,
                 const Scalar& params = Scalar(1));

    // Return `arg` unchanged if it is already of depth `depth`; otherwise append an OP_CAST into a
    // fresh temp of that depth and return the temp's slot. The one place casts are inserted.
    int  maybeAddCast(int arg, int depth);

    // ---- type-inference + cast-insertion policy layers (parser + hand builders) ----
    // Each derives the result depth (promotion, or a forced `rdepth`), picks the compute depth and a
    // wide fallback per op family, materializes flexible CONST operands, casts every operand to the
    // compute depth, then emits `op` (direct when a kernel exists, else compute wide and cast down).
    // Returns the slot holding the result. `rdepth` EW_DEPTH_NONE = auto.
    int  emitUnary(TOp op, int a, int rdepth = EW_DEPTH_NONE, const Scalar& params = Scalar(1));
    int  emitBinary(TOp op, int a, int b, int rdepth = EW_DEPTH_NONE, const Scalar& params = Scalar(1));
    int  emitTernary(TOp op, int a, int b, int c, int rdepth = EW_DEPTH_NONE);

    // Land `temp` in the existing slot `out`: redirect temp's single producer to write `out` directly
    // (dropping a dead last temp so compile() keeps its no-temp fast exit); otherwise copy via OP_CAST.
    int  moveToOutput(int temp, int out);

    // Declare a result tensor fed by `rootSlot` (a fresh OUTPUT of its depth) and moveToOutput into it.
    int  output(int rootSlot);

    // Finalize: pack temps into physical buffers (liveness), count consts, size the L1 fragment cap.
    void compile();

    // The broadcast output geometry for the given inputs (spatial dims + channel count, channels
    // innermost). All outputs share it; their depth comes from arginfo. Lets a caller pre-create the
    // destination (dst.create(spatial, CV_MAKETYPE(depth, channels))) before exec writes into it.
    // Inputs are passed as an array of pointers (no Mat-header copies in the hot path).
    void outputShape(const Mat* const* inputs, MatShape& spatial, int& channels) const;

    // Execute the compiled program over a set of input Mats, producing the broadcast result(s). If an
    // output Mat already has the right shape/type it is reused (not reallocated). Inputs are passed as
    // an array of pointers.
    void exec(const Mat* const* inputs, Mat* outputs);

    // Convenience overloads: inputs as a contiguous array of Mats (builds the pointer array + forwards).
    // Handy for callers holding a Mat[]/vector<Mat>; the hot path should pass pointers directly.
    void outputShape(const Mat* inputs, MatShape& spatial, int& channels) const;
    void exec(const Mat* inputs, Mat* outputs);
};

static void matLayout(const Mat& m, ChMode mode, MatShape& shp, MatStep& step, int& esz1)
{
    const int nd = m.dims, cn = m.channels();
    if (mode == CH_ELEM)
    {
        esz1 = (int)m.elemSize();                       // one full (cn-channel) pixel
        shp.resize(nd);
        for (int i = 0; i < nd; i++) { shp[i] = m.size[i]; step[i] = m.step[i] / esz1; }
        return;
    }
    esz1 = (int)m.elemSize1();                           // one scalar (channel value)
    if (mode == CH_DIM)
    {
        shp.resize(nd + 1);
        for (int i = 0; i < nd; i++) { shp[i] = m.size[i]; step[i] = m.step[i] / esz1; }
        shp[nd] = cn; step[nd] = 1;                      // channels = explicit innermost dim
    }
    else // CH_FOLD
    {
        if (nd == 0)                                     // 0-dim scalar: channels are the only dim
        {
            shp.assign(1, cn);
            step[0] = 1;
        }
        else
        {
            shp.resize(nd);
            for (int i = 0; i < nd; i++) { shp[i] = m.size[i]; step[i] = m.step[i] / esz1; }
            shp[nd - 1] *= cn;                           // fold channels into the innermost dim
            step[nd - 1] = 1;                            // scalars are contiguous there
        }
    }
}

static ChMode decideChannelMode(const Mat* const* arrays, int K)
{
    int N = 1;                                           // the single multichannel count, if any
    for (int k = 0; k < K; k++)
    {
        if (isSingleChannelScalar(*arrays[k])) continue;
        int c = arrays[k]->channels();
        if (c > 1) { if (N == 1) N = c; else CV_Assert(N == c && "ew: (n,m) channel mix unsupported"); }
    }
    if (N == 1) return CH_FOLD;                          // all single-channel -> fold (a no-op)

    bool allMulti = true, sameBack = true;
    int back = -1;
    for (int k = 0; k < K; k++)
    {
        const Mat& a = *arrays[k];
        if (isSingleChannelScalar(a)) continue;
        if (a.channels() != N) allMulti = false;
        int b = a.dims > 0 ? a.size[a.dims - 1] : 1;   // 0-dim scalar has no spatial back (=1)
        if (back < 0) back = b; else if (b != back) sameBack = false;
    }
    return (allMulti && sameBack) ? CH_FOLD : CH_DIM;    // fold only if no channel broadcast
}

static bool broadcastShape(const MatShape* shps, int K, MatShape& out)
{
    size_t nd = 0;
    for (int k = 0; k < K; k++) nd = std::max(nd, shps[k].size());
    out.assign(nd, 1);
    for (int k = 0; k < K; k++)
    {
        const MatShape& s = shps[k];
        size_t off = nd - s.size();
        for (size_t i = 0; i < s.size(); i++)
        {
            int d = s[i], &o = out[off + i];
            if (o == 1) o = d;
            else if (d != 1 && d != o) return false;
        }
    }
    return true;
}

static void alignArg(const MatShape& shp, const MatStep& step, int nd,
                     MatStep& as, MatShape& ash)
{
    as.clear();
    ash.assign(nd, 1);
    int off = nd - (int)shp.size();
    for (int i = 0; i < (int)shp.size(); i++)
    {
        int d = shp[i];
        ash[off + i] = d;
        as[off + i] = (d == 1) ? 0 : step[i];
    }
}

static int collapseDims(MatStep* S, MatShape* H, int K, MatShape& D)
{
    int nd = (int)D.size();
    if (nd <= 1) return nd;

    int j = nd - 1;
    for (int i = j - 1; i >= 0; i--)
    {
        bool contig = true, scalar = true, consist = true;
        for (int k = 0; k < K; k++)
        {
            size_t st = S[k][j] * (size_t)H[k][j];
            bool prevScalar = H[k][j] == 1;
            bool curScalar = H[k][i] == 1;
            contig  = contig  && (st == S[k][i]);
            scalar  = scalar  && curScalar;
            consist = consist && (curScalar == prevScalar);
        }
        if (contig && (consist || scalar))
        {
            for (int k = 0; k < K; k++) H[k][j] *= H[k][i];
            D[j] *= D[i];
        }
        else
        {
            j--;
            if (i < j)
            {
                for (int k = 0; k < K; k++) { H[k][j] = H[k][i]; S[k][j] = S[k][i]; }
                D[j] = D[i];
            }
        }
    }

    int m = nd - j;
    for (int d = 0; d < m; d++)
    {
        D[d] = D[j + d];
        for (int k = 0; k < K; k++) { S[k][d] = S[k][j + d]; H[k][d] = H[k][j + d]; }
    }
    D.resize(m);
    for (int k = 0; k < K; k++) H[k].resize(m);

    // Zero out steps of broadcast (size-1) dims (numpy step==0 trick).
    for (int d = 0; d < m; d++)
        for (int k = 0; k < K; k++)
            if (H[k][d] == 1) S[k][d] = 0;

    return m;
}

static bool fastSameShape(const Mat* const* arrays, int K, bool expandChannels,
                          uchar** base, int* esz1, MatStep* S, MatShape& D, int& m)
{
    if (!expandChannels) return false;
    int ref = -1;
    for (int k = 0; k < K; k++)
        if (!isSingleChannelScalar(*arrays[k])) { ref = k; break; }
    if (ref < 0) return false;                       // all single-channel scalars: let general handle
    const Mat& R = *arrays[ref];
    const int rdims = R.dims, rcn = R.channels();
    for (int k = 0; k < K; k++)
    {
        const Mat& a = *arrays[k];
        if (isSingleChannelScalar(a)) continue;
        if (a.channels() != rcn || a.dims != rdims || !a.isContinuous()) return false;
        for (int i = 0; i < rdims; i++) if (a.size[i] != R.size[i]) return false;
    }
    const long long total = (long long)R.total() * rcn;   // channels folded into the 1D run
    CV_Assert(total <= (long long)INT_MAX);
    for (int k = 0; k < K; k++)
    {
        const Mat& a = *arrays[k];
        base[k] = (uchar*)a.data;
        esz1[k] = (int)a.elemSize1();
        S[k][0] = isSingleChannelScalar(a) ? 0 : 1;
    }
    D.assign(1, (int)total);
    m = 1;
    return true;
}

static int halUnaryKernel(const void* src0_, size_t s0y, size_t s0x,
                          const void*, size_t, size_t, const void*, size_t, size_t,
                          void* dst_, size_t dsty, int width, int height,
                          const double*, int, void* userdata)
{
    typedef int (*HalFunc)(const T*, T*, int);
    const HalFunc fn = (HalFunc)userdata;
    s0y /= sizeof(T);
    dsty /= sizeof(T);
    CV_Assert(s0x <= 1u);
    const T* src0 = (const T*)src0_;
    T* dst = (T*)dst_;
    if (height > 1 && dsty == (size_t)width && s0y == s0x*(size_t)width) { width *= height; height = 1; }
    const int urows = (s0y == 0 && height > 1) ? 1 : height;   // vertical broadcast: 1 row + copies
    for (int y = 0; y < urows; y++, src0 += s0y, dst += dsty)
    {
        int code;
        if (s0x == 0)                     // broadcast-scalar source: one value covers the row
        {
            T v;
            code = fn(src0, &v, 1);
            for (int x = 0; x < width; x++) dst[x] = v;
        }
        else
            code = fn(src0, dst, width);
        if (code != CV_HAL_ERROR_OK)
            return code;                  // shouldn't happen (probed at get time) - let exec assert
    }
    dst = (T*)dst_;
    for (int y = urows; y < height; y++)
        memcpy(dst + (size_t)y*dsty, dst, (size_t)width*sizeof(T));
    return 0;
}

static TKernel probeHalUnary(HalFunc fn)
{
    T one = (T)1, r = (T)0;
    if (fn(&one, &r, 1) == CV_HAL_ERROR_OK)
        return {halUnaryKernel<T>, (void*)fn, 0};
    return {};
}

void mathSpanEngine(TOp op, int depth, const void* src, void* dst, int n)
{
    TKernel k = getEngineMathFunc(op, depth);
    CV_Assert(k.fptr);
    const double noparams[4] = {};
    k.fptr(src, 0, 1, nullptr, 0, 0, nullptr, 0, 0, dst, 0, n, 1, noparams, k.flags, k.userdata);
}

TKernel getMathFunc(TOp op, int T)
{
    if ((op == OP_EXP || op == OP_LOG) && (T == CV_32F || T == CV_64F))
    {
        // IPP now rides the cv_hal_* hooks too (hal/ipp), so the single probe below picks it up
        // together with any external vendor HAL - no separate IPP tier needed here.
        // probe results are process-lifetime stable; cache them (thread-safe magic statics)
        static const TKernel exp32 = probeHalUnary<float >(cv_hal_exp32f);
        static const TKernel exp64 = probeHalUnary<double>(cv_hal_exp64f);
        static const TKernel log32 = probeHalUnary<float >(cv_hal_log32f);
        static const TKernel log64 = probeHalUnary<double>(cv_hal_log64f);
        const TKernel* k = op == OP_EXP ? (T == CV_32F ? &exp32 : &exp64)
                                        : (T == CV_32F ? &log32 : &log64);
        if (k->fptr)
            return *k;
    }
    return getEngineMathFunc(op, T);
}

static inline void v_store_pair_as(hfloat* p, const v_float32& a, const v_float32& b)
{
    v_pack_store(p, a);
    v_pack_store(p + VTraits<v_float32>::vlanes(), b);
}

static inline void v_store_pair_as(bfloat* p, const v_float32& a, const v_float32& b)
{
    v_pack_store(p, a);
    v_pack_store(p + VTraits<v_float32>::vlanes(), b);
}

static v_float32 vec(const v_float32& x)
    {
        const v_float32 one = vx_setall_f32(1.f), lim = vx_setall_f32(10.f);
        v_float32 cx = v_min(v_max(x, v_sub(vx_setzero_f32(), lim)), lim);
        v_float32 e = v_exp(v_add(cx, cx));
        return v_div(v_sub(e, one), v_add(e, one));
    }

static v_float64 vec(const v_float64& x)
    {
        const v_float64 one = vx_setall_f64(1.), lim = vx_setall_f64(20.);
        v_float64 cx = v_min(v_max(x, v_sub(vx_setzero_f64(), lim)), lim);
        v_float64 e = v_exp(v_add(cx, cx));
        return v_div(v_sub(e, one), v_add(e, one));
    }

static v_float64 vec(const v_float64& x)
    {
        double buf[VTraits<v_float64>::max_nlanes];
        v_store(buf, x);
        for (int i = 0; i < VTraits<v_float64>::vlanes(); i++) buf[i] = std::erf(buf[i]);
        return vx_load(buf);
    }

static int vecUnaryKernel(const void* src0_, size_t s0y, size_t s0x,
                          const void*, size_t, size_t, const void*, size_t, size_t,
                          void* dst_, size_t dsty, int width, int height,
                          const double*, int, void*)
{
    s0y /= sizeof(T);
    dsty /= sizeof(T);
    CV_Assert(s0x <= 1u);

    const T* src0 = (const T*)src0_;
    T* dst = (T*)dst_;
    using WT = typename VTraits<Wvec>::lane_type;

    if (height > 1 && dsty == (size_t)width && s0y == s0x*(size_t)width) { width *= height; height = 1; }

    // vertical broadcast (a row expanded into a matrix, s0y == 0): every output row is identical -
    // compute the first one, memcpy the rest (transcendentals cost far more than a row copy)
    const int urows = (s0y == 0 && height > 1) ? 1 : height;

    for (int y = 0; y < urows; y++, src0 += s0y, dst += dsty)
    {
        if (s0x == 0)                     // broadcast-scalar source: one value covers the row
        {
            T v = saturate_cast<T>(Op::scl((WT)src0[0]));
            for (int x = 0; x < width; x++) dst[x] = v;
            continue;
        }
        int x = 0;
#if (CV_SIMD || CV_SIMD_SCALABLE)
        const int VECSZ = VTraits<Wvec>::vlanes();
        // in-place (dst == src) forbids the right-edge backoff: it would re-read already-written
        // values and apply Op twice. Those rows finish in the scalar tail instead.
        const bool use_tail_trick = width >= VECSZ*4 && src0_ != dst_;
        for (; x < width; x += VECSZ*2)
        {
            if (x + VECSZ*2 > width) { if (!use_tail_trick || x == 0) break; x = width - VECSZ*2; }
            Wvec a0, a1;
            vx_load_pair_as(src0 + x, a0, a1);
            a0 = Op::vec(a0); a1 = Op::vec(a1);
            v_store_pair_as(dst + x, a0, a1);
        }
#endif
        for (; x < width; x++)
            dst[x] = saturate_cast<T>(Op::scl((WT)src0[x]));
    }
    dst = (T*)dst_;
    for (int y = urows; y < height; y++)
        memcpy(dst + (size_t)y*dsty, dst, (size_t)width*sizeof(T));
    return 0;
}

static int scalarUnaryKernel(const void* src0_, size_t s0y, size_t s0x,
                             const void*, size_t, size_t, const void*, size_t, size_t,
                             void* dst_, size_t dsty, int width, int height,
                             const double*, int, void*)
{
    s0y /= sizeof(T);
    dsty /= sizeof(T);
    CV_Assert(s0x <= 1u);
    const T* src0 = (const T*)src0_;
    T* dst = (T*)dst_;
    if (height > 1 && dsty == (size_t)width && s0y == s0x*(size_t)width) { width *= height; height = 1; }
    const int urows = (s0y == 0 && height > 1) ? 1 : height;   // vertical broadcast: 1 row + copies
    for (int y = 0; y < urows; y++, src0 += s0y, dst += dsty)
    {
        if (s0x == 0)
        {
            T v = saturate_cast<T>(Op::scl((WT)src0[0]));
            for (int x = 0; x < width; x++) dst[x] = v;
            continue;
        }
        for (int x = 0; x < width; x++)
            dst[x] = saturate_cast<T>(Op::scl((WT)src0[x]));
    }
    dst = (T*)dst_;
    for (int y = urows; y < height; y++)
        memcpy(dst + (size_t)y*dsty, dst, (size_t)width*sizeof(T));
    return 0;
}

static int scalarPowKernel(const void* src0_, size_t s0y, size_t s0x,
                           const void* src1_, size_t s1y, size_t s1x,
                           const void*, size_t, size_t,
                           void* dst_, size_t dsty, int width, int height,
                           const double*, int, void*)
{
    s0y /= sizeof(T); s1y /= sizeof(T); dsty /= sizeof(T);
    CV_Assert(s0x <= 1u && s1x <= 1u);
    const T* src0 = (const T*)src0_;
    const T* src1 = (const T*)src1_;
    T* dst = (T*)dst_;
    if (height > 1 && dsty == (size_t)width && s0y == s0x*(size_t)width && s1y == s1x*(size_t)width)
    { width *= height; height = 1; }
    for (int y = 0; y < height; y++, src0 += s0y, src1 += s1y, dst += dsty)
        for (int x = 0; x < width; x++)
            dst[x] = saturate_cast<T>(std::pow((WT)src0[x*s0x], (WT)src1[x*s1x]));
    return 0;
}

TKernel getPowFunc_(int T, int R)
{
    if (R != T)
        return {};
    KernelFunc fptr = nullptr;
    switch (T)
    {
    case CV_16F:  fptr = powKernel<hfloat, v_float32>; break;
    case CV_16BF: fptr = powKernel<bfloat, v_float32>; break;
    case CV_32F:  fptr = powKernel<float,  v_float32>; break;
#if CV_SIMD_64F || CV_SIMD_SCALABLE_64F
    case CV_64F:  fptr = powKernel<double, v_float64>; break;
#else
    case CV_64F:  fptr = scalarPowKernel<double, double>; break;
#endif
    default: ;
    }
    return {fptr, nullptr, 0};
}

static KernelFunc mathByDepth(int T)
{
    switch (T)
    {
    case CV_16F:  return vecUnaryKernel<hfloat, v_float32, Op>;
    case CV_16BF: return vecUnaryKernel<bfloat, v_float32, Op>;
    case CV_32F:  return vecUnaryKernel<float,  v_float32, Op>;
#if CV_SIMD_64F || CV_SIMD_SCALABLE_64F
    case CV_64F:  return vecUnaryKernel<double, v_float64, Op>;
#else
    case CV_64F:  return scalarUnaryKernel<double, double, Op>;
#endif
    default:      return nullptr;
    }
}

TKernel getMathFunc_(TOp op, int T)
{
    KernelFunc f = nullptr;
    switch (op)
    {
    case OP_SQRT: f = mathByDepth<MSqrt>(T); break;
    case OP_EXP:  f = mathByDepth<MExp >(T); break;
    case OP_LOG:  f = mathByDepth<MLog >(T); break;
    case OP_SIN:  f = mathByDepth<MSin >(T); break;
    case OP_COS:  f = mathByDepth<MCos >(T); break;
    case OP_TANH: f = mathByDepth<MTanh>(T); break;
    case OP_RELU: f = mathByDepth<MRelu>(T); break;
    case OP_ERF:  f = mathByDepth<MErf >(T); break;
    default: ;
    }
    return {f, nullptr, 0};
}

inline bool isScalarArg(const _InputArray& sc, int cn)
{
    const _InputArray::KindFlag kind = sc.kind();
    if (kind == _InputArray::MATX)
    {
        Size sz = sc.getSz();
        int scn0 = sz.width * sz.height;
        // A genuine scalar is a 1D MATX (a Vec/Scalar/number: one of width/height is 1). A 2D MATX
        // (e.g. a Matx33) is a real matrix operand and rides broadcasting - never a scalar.
        if (scn0 != sz.width + sz.height - 1)
            return false;
        // Per-channel match (incl. Vec<_,N> for an N-channel array), a 4-elem Scalar on a <4-channel
        // array, or a single broadcast value. No 4-channel cap: a multichannel scalar rides as a 0-dim
        // per-channel CONST over the caller's data (not squeezed into a 4-slot Scalar).
        return scn0 == cn || (cn < 4 && scn0 == 4) || scn0 == 1;
    }
    // the bindings-style Scalar column. dims must be exactly 2: a 1-D [4] CV_64F array is an honest
    // broadcast operand. Direct field reads (no _InputArray getter dispatch) - this runs on EVERY
    // engine call with Mat operands, and `rows == 4` alone rejects almost every real array.
    if (kind == _InputArray::MAT)
    {
        const Mat& m = *(const Mat*)sc.getObj();
        return m.rows == 4 && m.cols == 1 && cn <= 4 && m.dims == 2 &&
               m.type() == CV_64F && m.isContinuous();
    }
    if (kind == _InputArray::UMAT)
    {
        const UMat& m = *(const UMat*)sc.getObj();
        return m.rows == 4 && m.cols == 1 && cn <= 4 && m.dims == 2 &&
               m.type() == CV_64F && m.isContinuous();
    }
    return false;
}

inline bool isScalarLikeMat(const _InputArray& sc, int cn)
{
    // direct field reads, like isScalarArg: this probe also runs per engine call (see arithm_op's
    // compat fallback). `rows != 1 && cols != 1` exits in two inline compares for ordinary arrays.
    int rows, cols, nval;
    bool continuous;
    const _InputArray::KindFlag kind = sc.kind();
    if (kind == _InputArray::MAT)
    {
        const Mat& m = *(const Mat*)sc.getObj();
        if ((m.rows != 1 && m.cols != 1) || m.dims > 2) return false;
        rows = m.rows; cols = m.cols; nval = rows * cols * m.channels(); continuous = m.isContinuous();
    }
    else if (kind == _InputArray::UMAT)
    {
        const UMat& m = *(const UMat*)sc.getObj();
        if ((m.rows != 1 && m.cols != 1) || m.dims > 2) return false;
        rows = m.rows; cols = m.cols; nval = rows * cols * m.channels(); continuous = m.isContinuous();
    }
    else
        return false;
    if (!continuous || nval > 4)
        return false;
    return (rows == 1 && cols == 1) || (rows == cn && cols == 1) || (rows == 1 && cols == cn);
}

inline int scalarArgElems(const _InputArray& sc, const uchar*& p, int& d, uchar* scbuf)
{
    const _InputArray::KindFlag kind = sc.kind();
    if (kind == _InputArray::MAT)
    {
        const Mat& m = *(const Mat*)sc.getObj();
        p = m.data;
        d = m.depth();
        return (int)m.total() * m.channels();
    }
    if (kind == _InputArray::UMAT)
    {
        const UMat& u = *(const UMat*)sc.getObj();
        d = u.depth();
        int n = (int)u.total() * u.channels();
        CV_Assert(n * (int)CV_ELEM_SIZE1(d) <= (int)EW_SCALAR_BUF_SIZE);
        Mat header(u.dims, u.size.p, u.type(), scbuf);   // header over the caller's stack buffer
        u.copyTo(header);                                // create() is a no-op (exact match) -> the
        p = scbuf;                                       // copy lands straight in scbuf
        return n;
    }
    p = (const uchar*)sc.getObj();
    d = sc.depth();
    Size sz = sc.getSz();
    return sz.width * sz.height;
}

inline double elemToDouble(int d, const uchar* p)
{
    switch (d)
    {
    case CV_8U:   return *(const uchar*)p;
    case CV_8S:   return *(const schar*)p;
    case CV_16U:  return *(const ushort*)p;
    case CV_16S:  return *(const short*)p;
    case CV_32U:  return *(const unsigned*)p;
    case CV_32S:  return *(const int*)p;
    case CV_64U:  return (double)*(const uint64_t*)p;
    case CV_64S:  return (double)*(const int64_t*)p;
    case CV_16F:  return (float)*(const hfloat*)p;
    case CV_16BF: return (float)*(const bfloat*)p;
    case CV_32F:  return *(const float*)p;
    case CV_64F:  return *(const double*)p;
    default:      CV_Error(Error::StsUnsupportedFormat, "unsupported scalar depth");
    }
}

inline int readScalarArg(const _InputArray& sc, Scalar& out)
{
    out = Scalar();                      // unused channels stay 0 (independent of the caller's Scalar)
    const uchar* p; int d; uchar scbuf[EW_SCALAR_BUF_SIZE];
    int n = scalarArgElems(sc, p, d, scbuf);
    CV_Assert(n <= 4);                   // Scalar holds 4 slots; isScalarArg admits more only for MATX
    size_t esz = CV_ELEM_SIZE1(d);
    for (int i = 0; i < n; i++)
        out[i] = elemToDouble(d, p + (size_t)i * esz);
    return n;
}

static Mat expr1(const String& e, const std::vector<Mat>& in)
{
    std::vector<Mat> out;
    cv::texpr(e, in, out);
    return out[0];
}

TEST(Core_TExpr, add)
{
    Mat a(12, 15, CV_32F), b(12, 15, CV_32F);
    theRNG().fill(a, RNG::UNIFORM, 1.f, 10.f);
    theRNG().fill(b, RNG::UNIFORM, 1.f, 10.f);

    Mat got = expr1("{0} + {1}", { a, b });
    Mat exp; cv::add(a, b, exp);
    EXPECT_LE(cvtest::norm(got, exp, NORM_INF), 1e-3);
}

TEST(Core_TExpr, minmax_absdiff)
{
    Mat a(18, 21, CV_8U), b(18, 21, CV_8U);
    theRNG().fill(a, RNG::UNIFORM, 0, 255);
    theRNG().fill(b, RNG::UNIFORM, 0, 255);

    Mat gmin = expr1("min({0}, {1})", { a, b });
    Mat gmax = expr1("max({0}, {1})", { a, b });
    Mat gabs = expr1("absdiff({0}, {1})", { a, b });

    Mat emin, emax, eabs;
    cv::min(a, b, emin); cv::max(a, b, emax); cv::absdiff(a, b, eabs);
    EXPECT_EQ(0, cvtest::norm(gmin, emin, NORM_INF));
    EXPECT_EQ(0, cvtest::norm(gmax, emax, NORM_INF));
    EXPECT_EQ(0, cvtest::norm(gabs, eabs, NORM_INF));
}

TEST(Core_TExpr, addweighted_precedence)
{
    Mat a(20, 16, CV_32F), b(20, 16, CV_32F);
    theRNG().fill(a, RNG::UNIFORM, 1.f, 10.f);
    theRNG().fill(b, RNG::UNIFORM, 1.f, 10.f);

    Mat got = expr1("{0} * 2.5 + {1} * -1.5 + 7", { a, b });
    Mat exp; cv::addWeighted(a, 2.5, b, -1.5, 7.0, exp);
    EXPECT_LE(cvtest::norm(got, exp, NORM_INF), 1e-3);
}

TEST(Core_TExpr, assignment)
{
    Mat a(18, 22, CV_32F), b(18, 22, CV_32F);
    theRNG().fill(a, RNG::UNIFORM, 1.f, 10.f);
    theRNG().fill(b, RNG::UNIFORM, 1.f, 10.f);

    Mat got = expr1("t = {0} * 2.5; t + {1}", { a, b });
    Mat exp; cv::addWeighted(a, 2.5, b, 1.0, 0.0, exp);
    EXPECT_LE(cvtest::norm(got, exp, NORM_INF), 1e-3);
}

TEST(Core_TExpr, tuple_outputs)
{
    Mat a(14, 19, CV_32F), b(14, 19, CV_32F);
    theRNG().fill(a, RNG::UNIFORM, 1.f, 10.f);
    theRNG().fill(b, RNG::UNIFORM, 1.f, 10.f);

    std::vector<Mat> out;
    cv::texpr("({0} + {1}, {0} - {1})", std::vector<Mat>{ a, b }, out);
    ASSERT_EQ(out.size(), 2u);
    Mat eadd, esub; cv::add(a, b, eadd); cv::subtract(a, b, esub);
    EXPECT_LE(cvtest::norm(out[0], eadd, NORM_INF), 1e-3) << "sum";
    EXPECT_LE(cvtest::norm(out[1], esub, NORM_INF), 1e-3) << "diff";
}

TEST(Core_TExpr, grouping_parens)
{
    Mat a(11, 13, CV_32F), b(11, 13, CV_32F);
    theRNG().fill(a, RNG::UNIFORM, 1.f, 10.f);
    theRNG().fill(b, RNG::UNIFORM, 1.f, 10.f);

    Mat got = expr1("({0} + {1}) * 2", { a, b });
    Mat exp; cv::add(a, b, exp); exp *= 2.0;
    EXPECT_LE(cvtest::norm(got, exp, NORM_INF), 1e-3);
}

TEST(Core_TExpr, cast_uint8)
{
    Mat a(23, 17, CV_32F);
    theRNG().fill(a, RNG::UNIFORM, -50.f, 300.f);

    Mat got = expr1("uint8({0})", { a });
    Mat exp; a.convertTo(exp, CV_8U);
    ASSERT_EQ(got.type(), exp.type());
    EXPECT_EQ(0, cvtest::norm(got, exp, NORM_INF));
}

TEST(Core_TExpr, pow_call)
{
    Mat a(16, 16, CV_32F);
    theRNG().fill(a, RNG::UNIFORM, 1.f, 5.f);

    Mat got = expr1("pow({0}, 2)", { a });
    Mat exp; cv::pow(a, 2.0, exp);
    EXPECT_LE(cvtest::norm(got, exp, NORM_INF), 1e-3);
}

TEST(Core_TExpr, pow_exponents)
{
    for (int depth : { CV_32F, CV_64F })
    {
        const double eps = depth == CV_32F ? 1e-6 : 1e-9;
        Mat a0(37, 41, CV_64F), a;
        theRNG().fill(a0, RNG::UNIFORM, 0.05, 9.);
        a0.convertTo(a, depth);
        for (double p : { 2., 3., 0.5, 1., 0., 2.5, -1.5, -0.5, 5., -2., 11. })
        {
            Mat got = expr1(cv::format("pow({0}, %.10g)", p), { a });
            ASSERT_EQ(got.depth(), depth) << "p=" << p;
            Mat ad, gd;
            a.convertTo(ad, CV_64F); got.convertTo(gd, CV_64F);
            double maxerr = 0;
            for (int y = 0; y < a.rows; y++)
                for (int x = 0; x < a.cols; x++)
                {
                    double r = std::pow(ad.at<double>(y, x), p);
                    maxerr = std::max(maxerr, std::abs(gd.at<double>(y, x) - r) / std::max(1.0, std::abs(r)));
                }
            EXPECT_LE(maxerr, eps) << "depth=" << depth << " p=" << p;
        }
    }
}

TEST(Core_TExpr, pow_negative_base)
{
    Mat a(9, 13, CV_32F);
    theRNG().fill(a, RNG::UNIFORM, -5.f, -1.f);

    Mat got3 = expr1("pow({0}, 3)", { a });
    for (int y = 0; y < a.rows; y++)
        for (int x = 0; x < a.cols; x++)
            ASSERT_NEAR(got3.at<float>(y, x), std::pow((double)a.at<float>(y, x), 3.), 1e-2);

    Mat gotf = expr1("pow({0}, 2.5)", { a });
    for (int y = 0; y < a.rows; y++)
        for (int x = 0; x < a.cols; x++)
            ASSERT_TRUE(cvIsNaN(gotf.at<float>(y, x))) << "pow(neg, frac) must be NaN";
}

TEST(Core_TExpr, neg_abs)
{
    for (int depth : { CV_32F, CV_16S })
    {
        Mat a(15, 19, depth);
        theRNG().fill(a, RNG::UNIFORM, -100, 100);

        Mat gneg = expr1("-{0}", { a });
        Mat eneg; cv::subtract(Scalar(0), a, eneg);
        ASSERT_EQ(gneg.depth(), depth);
        EXPECT_EQ(0, cvtest::norm(gneg, eneg, NORM_INF)) << "neg depth=" << depth;

        // abs == absdiff(a, 0) INCLUDING the texpr auto result type rule: signed input -> the
        // UNSIGNED type of the same width (|SHRT_MIN| fits u16 exactly, no saturation). NB this
        // deliberately differs from the public cv::absdiff, whose auto depth keeps the source
        // type for 4.x compatibility - the VALUES agree, the depth rule is the engine's own.
        Mat gabs = expr1("abs({0})", { a });
        ASSERT_EQ(gabs.depth(), cv::ew::absdiffResultDepth(depth)) << "texpr absdiff type rule";
        Mat eabs; cv::absdiff(a, Scalar(0), eabs);
        eabs.convertTo(eabs, gabs.depth());
        EXPECT_EQ(0, cvtest::norm(gabs, eabs, NORM_INF)) << "abs depth=" << depth;
    }
}

TEST(Core_TExpr, abs_sub_peephole)
{
    for (int depth : { CV_8U, CV_16S, CV_32F })
    {
        Mat a(23, 17, depth), b(23, 17, depth);
        theRNG().fill(a, RNG::UNIFORM, 0, 100);
        theRNG().fill(b, RNG::UNIFORM, 0, 100);

        Mat got = expr1("abs({0} - {1})", { a, b });
        ASSERT_EQ(got.depth(), cv::ew::absdiffResultDepth(depth)) << "depth=" << depth;
        Mat exp; cv::absdiff(a, b, exp);
        exp.convertTo(exp, got.depth());          // cv::absdiff auto KEEPS the source depth (4.x)
        EXPECT_EQ(0, cvtest::norm(got, exp, NORM_INF)) << "depth=" << depth;
    }
}

TEST(Core_TExpr, clamp)
{
    for (int depth : { CV_8U, CV_16S, CV_32F, CV_64F })
    {
        Mat a(25, 31, depth);
        theRNG().fill(a, RNG::UNIFORM, -100, 355);

        Mat got = expr1("clamp({0}, 10, 200)", { a });
        Mat emax, exp;
        cv::max(a, 10.0, emax); cv::min(emax, 200.0, exp);
        ASSERT_EQ(got.depth(), depth) << "clamp must keep the operand type";
        EXPECT_EQ(0, cvtest::norm(got, exp, NORM_INF)) << "depth=" << depth;
    }
    // array bounds
    Mat x(14, 22, CV_32F), lo(14, 22, CV_32F), hi(14, 22, CV_32F);
    theRNG().fill(x, RNG::UNIFORM, -10.f, 10.f);
    theRNG().fill(lo, RNG::UNIFORM, -5.f, 0.f);
    theRNG().fill(hi, RNG::UNIFORM, 0.f, 5.f);
    Mat got = expr1("clamp({0}, {1}, {2})", { x, lo, hi });
    Mat emax, exp;
    cv::max(x, lo, emax); cv::min(emax, hi, exp);
    EXPECT_EQ(0, cvtest::norm(got, exp, NORM_INF));
}

TEST(Core_TExpr, pow_operator)
{
    Mat a(13, 18, CV_32F);
    theRNG().fill(a, RNG::UNIFORM, 0.5f, 2.f);

    Mat got = expr1("{0} ** 2", { a });
    Mat exp; cv::pow(a, 2.0, exp);
    EXPECT_EQ(0, cvtest::norm(got, exp, NORM_INF));

    // precedence: 3 * a ** 2 == 3 * (a ** 2)
    Mat got2 = expr1("3 * {0} ** 2", { a });
    Mat exp2 = 3.0 * exp;
    EXPECT_LE(cvtest::norm(got2, exp2, NORM_INF), 1e-4);

    // right associativity: a ** 2 ** 3 == a ** (2 ** 3) == a ** 8
    Mat got3 = expr1("{0} ** 2 ** 3", { a });
    Mat exp3; cv::pow(a, 8.0, exp3);
    EXPECT_LE(cvtest::norm(got3, exp3, NORM_INF), 1e-4);
}

TEST(Core_TExpr, ternary_operator)
{
    Mat a(19, 23, CV_32F), b(19, 23, CV_32F);
    theRNG().fill(a, RNG::UNIFORM, 0.f, 100.f);
    theRNG().fill(b, RNG::UNIFORM, 0.f, 100.f);

    // max via ?: - the condition is a full comparison (lower precedence than '>')
    Mat got = expr1("{0} > {1} ? {0} : {1}", { a, b });
    Mat exp; cv::max(a, b, exp);
    EXPECT_EQ(0, cvtest::norm(got, exp, NORM_INF));

    // arithmetic in every position without parentheses
    Mat got2 = expr1("{0} - {1} > 10 ? {0} + 1 : {1} * 2", { a, b });
    Mat mask = (a - b > 10), e1 = a + 1, e2 = b * 2, exp2 = e2.clone();
    e1.copyTo(exp2, mask);
    EXPECT_LE(cvtest::norm(got2, exp2, NORM_INF), 1e-4);

    // right-associative chain: c1 ? x : c2 ? y : z
    Mat got3 = expr1("{0} > 66 ? 1 : {0} > 33 ? 2 : 3", { a });
    Mat exp3(a.size(), CV_32F);
    for (int y = 0; y < a.rows; y++)
        for (int x = 0; x < a.cols; x++)
        {
            float v = a.at<float>(y, x);
            exp3.at<float>(y, x) = v > 66 ? 1.f : v > 33 ? 2.f : 3.f;
        }
    EXPECT_EQ(0, cvtest::norm(got3, exp3, NORM_INF));
}

TEST(Core_TExpr, hypot_mag)
{
    for (int depth : { CV_32F, CV_64F })
    {
        Mat x(23, 31, depth), y(23, 31, depth);
        theRNG().fill(x, RNG::UNIFORM, -100, 100);
        theRNG().fill(y, RNG::UNIFORM, -100, 100);

        Mat got = expr1("hypot({0}, {1})", { x, y });
        ASSERT_EQ(got.depth(), depth);
        Mat exp; cv::magnitude(x, y, exp);
        EXPECT_LE(cvtest::norm(got, exp, NORM_INF), depth == CV_32F ? 1e-4 : 1e-9);

        Mat got2 = expr1("mag({0}, {1})", { x, y });   // alias
        EXPECT_EQ(0, cvtest::norm(got2, got, NORM_INF));
    }
    // broadcast branch: hypot(array, scalar)
    Mat x(11, 17, CV_32F);
    theRNG().fill(x, RNG::UNIFORM, -10.f, 10.f);
    Mat got = expr1("hypot({0}, 3)", { x });
    for (int r = 0; r < x.rows; r++)
        for (int c = 0; c < x.cols; c++)
        {
            float v = x.at<float>(r, c);
            ASSERT_NEAR(got.at<float>(r, c), std::sqrt(v*v + 9.f), 1e-4) << r << "," << c;
        }
    // f16: T -> T through the native kernel (f32 hub inside)
    Mat xh, yh, y16(11, 17, CV_32F);
    x.convertTo(xh, CV_16F);
    theRNG().fill(y16, RNG::UNIFORM, -10.f, 10.f);
    y16.convertTo(yh, CV_16F);
    Mat goth = expr1("hypot({0}, {1})", { xh, yh });
    ASSERT_EQ(goth.depth(), CV_16F);
}

TEST(Core_TExpr, atan2)
{
    Mat y(23, 31, CV_32F), x(23, 31, CV_32F);
    theRNG().fill(y, RNG::UNIFORM, -10.f, 10.f);   // both signs -> all quadrants
    theRNG().fill(x, RNG::UNIFORM, -10.f, 10.f);

    Mat got = expr1("atan2({0}, {1})", { y, x });
    ASSERT_EQ(got.depth(), CV_32F);
    double maxerr = 0;
    for (int r = 0; r < y.rows; r++)
        for (int c = 0; c < y.cols; c++)
        {
            double ref = std::atan2((double)y.at<float>(r, c), (double)x.at<float>(r, c));
            maxerr = std::max(maxerr, std::abs((double)got.at<float>(r, c) - ref));
        }
    EXPECT_LE(maxerr, 2e-4) << "fastAtan2-class polynomial accuracy (measured ~1.6e-4 rad)";

    // f64: exact std::atan2 per element
    Mat y64, x64;
    y.convertTo(y64, CV_64F); x.convertTo(x64, CV_64F);
    Mat got64 = expr1("atan2({0}, {1})", { y64, x64 });
    ASSERT_EQ(got64.depth(), CV_64F);
    for (int r = 0; r < y.rows; r++)
        for (int c = 0; c < y.cols; c++)
            ASSERT_EQ(got64.at<double>(r, c),
                      std::atan2(y64.at<double>(r, c), x64.at<double>(r, c)));

    // axis cases: atan2(0, 1) = 0, atan2(1, 0) = pi/2, atan2(0, -1) = pi, atan2(-1, 0) = -pi/2
    Mat ya = (Mat_<float>(1, 4) << 0.f, 1.f, 0.f, -1.f);
    Mat xa = (Mat_<float>(1, 4) << 1.f, 0.f, -1.f, 0.f);
    Mat ga = expr1("atan2({0}, {1})", { ya, xa });
    const float expctd[] = { 0.f, (float)(CV_PI/2), (float)CV_PI, (float)(-CV_PI/2) };
    for (int i = 0; i < 4; i++)
        ASSERT_NEAR(ga.at<float>(0, i), expctd[i], 1e-4) << "axis case " << i;
}

TEST(Core_TExpr, pow_array_exponent)
{
    Mat a(21, 27, CV_32F), b(21, 27, CV_32F);
    theRNG().fill(a, RNG::UNIFORM, 0.1f, 5.f);
    theRNG().fill(b, RNG::UNIFORM, -2.f, 3.f);

    Mat got = expr1("pow({0}, {1})", { a, b });
    double maxerr = 0;
    for (int y = 0; y < a.rows; y++)
        for (int x = 0; x < a.cols; x++)
        {
            double r = std::pow((double)a.at<float>(y, x), (double)b.at<float>(y, x));
            maxerr = std::max(maxerr, std::abs(got.at<float>(y, x) - r) / std::max(1.0, std::abs(r)));
        }
    EXPECT_LE(maxerr, 1e-6);
}

static double relErr(const Mat& got, const Mat& in, mathRef ref)
{
    Mat gotd, ind;
    got.convertTo(gotd, CV_64F);
    in.convertTo(ind, CV_64F);
    double maxerr = 0;
    for (int y = 0; y < ind.rows; y++)
        for (int x = 0; x < ind.cols; x++)
        {
            double r = ref(ind.at<double>(y, x));
            double e = std::abs(gotd.at<double>(y, x) - r) / std::max(1.0, std::abs(r));
            maxerr = std::max(maxerr, e);
        }
    return maxerr;
}

TEST_P(Core_TExpr_Math, unary_accuracy)
{
    const int depth = GetParam();
    // eps: half-precision types are exact to ~2^-8/2^-11 per element; the f32 kernels are
    // polynomial approximations (a few ulp); f64 sqrt/exp/log are also vectorized polynomials
    const double eps = depth == CV_16F ? 2e-3 : depth == CV_16BF ? 1.6e-2
                     : depth == CV_32F ? 1e-6 : 1e-9;
    Mat a0(37, 41, CV_32F);
    theRNG().fill(a0, RNG::UNIFORM, 0.05f, 9.f);   // positive: one range serves log/sqrt too
    Mat a;
    a0.convertTo(a, depth);

    for (const MathOpRef& m : mathOps)
    {
        Mat got = expr1(cv::format("%s({0})", m.name), { a });
        ASSERT_EQ(got.depth(), depth) << m.name << ": math must be T -> T on float inputs";
        EXPECT_LE(relErr(got, a, m.ref), eps) << m.name << " depth=" << depth;
    }

    // negative inputs for the ops defined there (skip log/sqrt)
    Mat b0(37, 41, CV_32F), b;
    theRNG().fill(b0, RNG::UNIFORM, -8.f, 8.f);
    b0.convertTo(b, depth);
    for (const char* name : { "exp", "sin", "cos", "tanh", "erf", "relu" })
    {
        const MathOpRef* m = nullptr;
        for (const MathOpRef& c : mathOps) if (!strcmp(c.name, name)) m = &c;
        Mat got = expr1(cv::format("%s({0})", name), { b });
        EXPECT_LE(relErr(got, b, m->ref), eps) << name << "(neg) depth=" << depth;
    }
}

