                        (iq3 % mask->ne[3]) * mask->nb[3];

    if (mask->type == GGML_TYPE_F32) {
        return *(const float *) (base + ik1 * mask->nb[0]);
    }
    return fp16_to_fp32(*(const uint16_t *) (base + ik1 * mask->nb[0]));
}

