DECLARE_DEFAULT_CODE(using BaselineMD5Ops = AVX2MD5Ops;)
#elif USE_MD5_AARCH64_ASIMD
DECLARE_DEFAULT_CODE(using BaselineMD5Ops = ASIMDMD5Ops;)
#else
DECLARE_DEFAULT_CODE(using BaselineMD5Ops = ScalarMD5Ops;)
#endif

