SphericalPointInRadians toRadianPoint(const SphericalPoint & degree_point)
{
    Float64 lon = get<0>(degree_point) * M_PI / 180.0;
    Float64 lat = get<1>(degree_point) * M_PI / 180.0;
    return SphericalPointInRadians(lon, lat);
}

void validateCoordinates(const SphericalPoint & degree_point, std::string_view function_name)
{
    const Float64 lon = get<0>(degree_point);
    const Float64 lat = get<1>(degree_point);

    if (!std::isfinite(lon) || !std::isfinite(lat) || std::abs(lon) > 180.0 || std::abs(lat) > 90.0)
        throw Exception(
            ErrorCodes::ARGUMENT_OUT_OF_BOUND,
            "The vertex ({}, {}) of the geometry passed to function {} is out of bounds "
            "(longitude must be -180..180 and latitude -90..90 degrees)",
            toString(lon),
            toString(lat),
            function_name);
}

void checkH3Error(H3Error error, std::string_view function_name)
{
    if (error != E_SUCCESS)
        throw Exception(ErrorCodes::INCORRECT_DATA,
            "Failed to compute H3 polygon to cells in function {}: {}",
            function_name, describeH3Error(error));
}

H3Index nextCellInSequence(H3Index cell)
{
    int res = H3_GET_RESOLUTION(cell);
    while (true)
    {
        /// A base cell has no parent, so continue with the next one.
        if (res == 0)
            return baseCellNumToCell(H3_GET_BASE_CELL(cell) + 1);

        H3Index parent = cell;
        H3_SET_RESOLUTION(parent, res - 1);
        H3_SET_INDEX_DIGIT(parent, res, H3_DIGIT_MASK);

        /// Not the last sibling: continue with the next one, skipping the missing child of a pentagon.
        const int digit = static_cast<int>(H3_GET_INDEX_DIGIT(cell, res));
        if (digit < INVALID_DIGIT - 1)
        {
            H3_SET_INDEX_DIGIT(cell, res, digit + ((isPentagon(parent) && digit == CENTER_DIGIT) ? 2 : 1));
            return cell;
        }

        --res;
        cell = parent;
    }
}

H3Index next()
    {
        if (cell == H3_NULL)
            return H3_NULL;

        /// The first candidate is the cell the walk starts at; after that, the one after the last output.
        if (started)
            cell = nextCellInSequence(cell);
        else
            started = true;

        /// Nothing covers a polygon without vertices.
        if (polygon->geoloop.numVerts == 0)
            cell = H3_NULL;

        while (cell)
        {
            budget.chargeUnits(units_per_candidate);

            const int cell_res = H3_GET_RESOLUTION(cell);

            /// Target resolution: a fine-grained check.
            if (cell_res == res && matchesContainmentMode(cell, cell_res))
                return cell;

            /// Coarser cell: check the bounding box of all of its children.
            if (cell_res < res)
            {
                BBox bbox;
                checkH3Error(cellToBBox(cell, &bbox, true), function_name);

                if (bboxOverlapsBBox(&bboxes[0], &bbox))
                {
                    /// Quick check for possible containment, then the expensive one on the polygon.
                    if (bboxContainsBBox(&bboxes[0], &bbox))
                    {
                        CellBoundary bbox_boundary = bboxToCellBoundary(&bbox);
                        if (cellBoundaryInsidePolygon(polygon, bboxes, &bbox_boundary, &bbox))
                            return cell;
                    }

                    /// An intersecting bounding box means every child has to be tested.
                    H3Index child = H3_NULL;
                    checkH3Error(cellToCenterChild(cell, cell_res + 1, &child), function_name);
                    cell = child;
                    continue;
                }
            }

            cell = nextCellInSequence(cell);
        }

        return H3_NULL;
    }

bool matchesContainmentMode(H3Index candidate, int candidate_res)
    {
        if (mode == CONTAINMENT_CENTER || mode == CONTAINMENT_OVERLAPPING || mode == CONTAINMENT_OVERLAPPING_BBOX)
        {
            LatLng center;
            checkH3Error(cellToLatLng(candidate, &center), function_name);
            if (pointInsidePolygon(polygon, bboxes, &center))
                return true;
        }

        if (mode == CONTAINMENT_OVERLAPPING || mode == CONTAINMENT_OVERLAPPING_BBOX)
        {
            /// The polygon may be wholly contained by the cell, which its first vertex tells us. That
            /// vertex exists because the caller rejects a polygon without vertices.
            const LatLng first_vertex = polygon->geoloop.verts[0];
            /// Out-of-range coordinates yield false positives with `latLngToCell`.
            if (bboxContains(&VALID_RANGE_BBOX, &first_vertex))
            {
                H3Index polygon_cell = H3_NULL;
                checkH3Error(latLngToCell(&first_vertex, candidate_res, &polygon_cell), function_name);
                if (polygon_cell == candidate)
                    return true;
            }
        }

        if (mode == CONTAINMENT_FULL || mode == CONTAINMENT_OVERLAPPING || mode == CONTAINMENT_OVERLAPPING_BBOX)
        {
            CellBoundary boundary;
            checkH3Error(cellToBoundary(candidate, &boundary), function_name);
            BBox bbox;
            checkH3Error(cellToBBox(candidate, &bbox, false), function_name);

            if ((mode == CONTAINMENT_FULL || mode == CONTAINMENT_OVERLAPPING_BBOX)
                && cellBoundaryInsidePolygon(polygon, bboxes, &boundary, &bbox))
                return true;

            /// Center point inclusion was checked above, so overlap only needs line intersection.
            if ((mode == CONTAINMENT_OVERLAPPING || mode == CONTAINMENT_OVERLAPPING_BBOX)
                && cellBoundaryCrossesPolygon(polygon, bboxes, &boundary, &bbox))
                return true;
        }

        if (mode == CONTAINMENT_OVERLAPPING_BBOX)
        {
            /// A bounding box containing all the cell's children, so that this works for the size estimate.
            BBox bbox;
            checkH3Error(cellToBBox(candidate, &bbox, true), function_name);

            if (bboxOverlapsBBox(&bboxes[0], &bbox))
            {
                CellBoundary bbox_boundary = bboxToCellBoundary(&bbox);
                if (bboxContainsBBox(&bbox, &bboxes[0])
                    || pointInsidePolygon(polygon, bboxes, &bbox_boundary.verts[0])
                    || cellBoundaryCrossesPolygon(polygon, bboxes, &bbox_boundary, &bbox))
                    return true;
            }
        }

        return false;
    }

Int64 estimateCellCount(
    const GeoPolygon * polygon,
    const BBox * bboxes,
    int res,
    std::string_view function_name,
    CancellationBudget & budget,
    size_t units_per_candidate)
{
    if (polygon->geoloop.numVerts == 0)
        return 0;

    /// A (very) rough area of the polygon's bounding box.
    const BBox & polygon_bbox = bboxes[0];
    const double polygon_bbox_area_km2 = bboxHeightRads(&polygon_bbox) * bboxWidthRads(&polygon_bbox)
        / cos(fmin(fabs(polygon_bbox.north), fabs(polygon_bbox.south))) * EARTH_RADIUS_KM * EARTH_RADIUS_KM;

    /// All this needs is a general order of magnitude of the number of cells that would fit.
    int estimate_res = res;
    while (estimate_res > 0)
    {
        double average_cell_area_km2 = 0;
        checkH3Error(getHexagonAreaAvgKm2(estimate_res - 1, &average_cell_area_km2), function_name);
        if (polygon_bbox_area_km2 / average_cell_area_km2 <= MAX_SIZE_CELL_THRESHOLD)
            break;
        --estimate_res;
    }

    /// Ignore the requested containment mode and use the faster overlapping-bbox one.
    CompactCellScan scan(
        polygon, bboxes, estimate_res, CONTAINMENT_OVERLAPPING_BBOX, function_name, budget, units_per_candidate);

    Int64 estimate = 0;
    while (H3Index cell = scan.next())
    {
        Int64 children_size = 0;
        checkH3Error(cellToChildrenSize(cell, res, &children_size), function_name);
        estimate += children_size;
    }

    return estimate;
}

LatLng toH3LatLng(const SphericalPointInRadians & point)
{
    LatLng result;
    result.lat = point.get<1>();
    result.lng = point.get<0>();
    return result;
}

const GeoPolygon * unwrap() const
    {
        mutableMainLoop = {static_cast<int>(mainLoopVerts.size()),
                           const_cast<LatLng*>(mainLoopVerts.data())};

        mutableHoles.clear();
        mutableHoles.reserve(holeVerts.size());
        for (const auto & hole : holeVerts)
            mutableHoles.push_back({static_cast<int>(hole.size()),
                                    const_cast<LatLng*>(hole.data())});

        mutablePolygon = {mutableMainLoop,
                          static_cast<int>(mutableHoles.size()),
                          mutableHoles.data()};
        return &mutablePolygon;
    }

void appendH3Cells(
    const SphericalMultiPolygon & multi_polygon,
    UInt8 resolution,
    UInt32 flags,
    std::string_view function_name,
    CancellationBudget & budget,
    ColumnUInt64 & dst_data)
{
    const size_t row_start_offset = dst_data.size();
    for (const auto & polygon : multi_polygon)
    {
        VectorWithMemoryTracking<LatLng> exterior;
        exterior.reserve(polygon.outer().size());
        for (const auto & point : polygon.outer())
        {
            validateCoordinates(point, function_name);
            exterior.push_back(toH3LatLng(toRadianPoint(point)));
        }

        size_t vertex_count = exterior.size();

        VectorWithMemoryTracking<VectorWithMemoryTracking<LatLng>> holes;
        holes.reserve(polygon.inners().size());
        for (const auto & inner : polygon.inners())
        {
            VectorWithMemoryTracking<LatLng> hole;
            hole.reserve(inner.size());
            for (const auto & point : inner)
            {
                validateCoordinates(point, function_name);
                hole.push_back(toH3LatLng(toRadianPoint(point)));
            }
            vertex_count += hole.size();
            holes.emplace_back(std::move(hole));
        }

        GeoPolygonContainer polygon_wrapper(std::move(exterior), std::move(holes));
        const GeoPolygon * geo_polygon = polygon_wrapper.unwrap();

        checkH3Error(validatePolygonFlags(flags), function_name);

        /// Bounding boxes of the polygon and of each of its holes, which every candidate check needs.
        VectorWithMemoryTracking<BBox> bboxes(geo_polygon->numHoles + 1);
        bboxesFromGeoPolygon(geo_polygon, bboxes.data());

        /// A candidate at the target resolution is tested against every vertex of the polygon.
        const size_t units_per_candidate = 1 + vertex_count;

        /// Cheap bbox-based estimate: rejects a polygon that cannot fit before enumerating it. Rough in
        /// both directions, hence the exact check per cell below.
        const size_t row_size_so_far = dst_data.size() - row_start_offset;
        const size_t estimate = static_cast<size_t>(
            estimateCellCount(geo_polygon, bboxes.data(), resolution, function_name, budget, units_per_candidate));
        if (estimate > MAX_ARRAY_SIZE || row_size_so_far + estimate > MAX_ARRAY_SIZE)
            throw Exception(ErrorCodes::TOO_LARGE_ARRAY_SIZE,
                "The result of function {} (array of {} elements) will be too large with resolution = {}",
                function_name, row_size_so_far + estimate, toString(resolution));

        CompactCellScan scan(
            geo_polygon, bboxes.data(), resolution, flags, function_name, budget, units_per_candidate);

        while (H3Index compact_cell = scan.next())
        {
            /// A cell coarser than the requested resolution stands for all of its children.
            IterCellsChildren children = iterInitParent(compact_cell, resolution);
            for (; children.h; iterStepChild(&children))
            {
                /// The candidates rejected on the way here are charged by the walk; a child of a covered
                /// cell only costs the index arithmetic that produced it.
                budget.charge(sizeof(H3Index));

                if (dst_data.size() - row_start_offset >= MAX_ARRAY_SIZE)
                    throw Exception(ErrorCodes::TOO_LARGE_ARRAY_SIZE,
                        "The result of function {} (array of {} elements) will be too large with resolution = {}",
                        function_name, dst_data.size() - row_start_offset + 1, toString(resolution));

                /// `PODArray::push_back` grows geometrically; `IColumn::reserve` would size it exactly.
                dst_data.getData().push_back(children.h);
            }
        }
    }
}

void dispatchLowCardinalityIndexes(const IColumn & indexes, F && func)
    {
        if (const auto * indexes_uint8 = typeid_cast<const ColumnUInt8 *>(&indexes))
            func(indexes_uint8->getData().data());
        else if (const auto * indexes_uint16 = typeid_cast<const ColumnUInt16 *>(&indexes))
            func(indexes_uint16->getData().data());
        else if (const auto * indexes_uint32 = typeid_cast<const ColumnUInt32 *>(&indexes))
            func(indexes_uint32->getData().data());
        else if (const auto * indexes_uint64 = typeid_cast<const ColumnUInt64 *>(&indexes))
            func(indexes_uint64->getData().data());
        else
            throw Exception(ErrorCodes::ILLEGAL_COLUMN, "Unexpected index column {} of a LowCardinality column", indexes.getName());
    }

ColumnPtr tryMaterializeUnhandledLowCardinalityID(const IColumn & id_data)
    {
        ColumnPtr materialized = recursiveRemoveLowCardinality(id_data.getPtr());
        if (materialized.get() == &id_data)
            return nullptr;
        return materialized;
    }

std::optional<JoinKind> isValidJoinOrder(
    const QueryGraph & query_graph,
    const BitSet & left_mask,
    const BitSet & right_mask)
{
    auto check = [&](const auto & lhs, const auto & rhs) -> std::optional<JoinKind>
    {
        auto rel_id = lhs.getSingleBit();
        if (rel_id.has_value())
        {
            auto it = query_graph.join_kinds.find(rel_id.value());
            if (it != query_graph.join_kinds.end())
            {
                if (isSubsetOf(it->second.first, rhs))
                    return it->second.second;
                return {};
            }
        }
        return JoinKind::Inner;
    };

    JoinKind left_join_type = JoinKind::Inner;
    JoinKind right_join_type = JoinKind::Inner;

    if (auto res = check(left_mask, right_mask))
    {
        /// When original join stored a Left/Full kind for the left relation,
        /// and it now appears on the left side of reordered join, reverse the kind
        left_join_type = isLeftOrFull(res.value()) ? reverseJoinKind(res.value()) : res.value();
    }
    else
        return {};

    if (auto res = check(right_mask, left_mask))
        right_join_type = isRightOrFull(res.value()) ? reverseJoinKind(res.value()) : res.value();
    else
        return {};

    if (left_join_type == JoinKind::Inner)
        return right_join_type;
    if (right_join_type == JoinKind::Inner)
        return left_join_type;
    /// Allow FULL join as it's restricted to table swapping and no reordering
    if (left_join_type == JoinKind::Full && right_join_type == JoinKind::Full)
        return JoinKind::Full;

    /// Conflict, join is not possible:
    /// FROM t1 LEFT JOIN t2 LEFT JOIN t3
    /// t1 -> Inner, t2 -> Left, t3 -> Left
    /// Cannot do (t2 x t3)
    return {};
}

std::vector<JoinActionRef *> getApplicableExpressions(
    QueryGraph & query_graph,
    const BitSet & left,
    const BitSet & right)
{
    std::vector<JoinActionRef *> applicable;

    BitSet joined_rels = left | right;
    for (auto & edge : query_graph.edges)
    {
        if (!edge)
            continue;
        const auto & edge_sources = edge.getSourceRelations();
        if (!isSubsetOf(edge_sources, joined_rels))
            continue;

        auto pin_it = query_graph.outer_join_conditions.find(edge);
        if (pin_it != query_graph.outer_join_conditions.end())
        {
            /// ON-clause predicates of an outer join can be applied only when the
            /// null-supplying relation is joined. That relation appears as a singleton
            /// on one side of the join step (enforced by isValidJoinOrder), so the
            /// predicate becomes applicable exactly at that step.
            if (!joined_rels.test(pin_it->second))
                continue;
        }

        applicable.push_back(&edge);
    }
    return applicable;
}

double computeSelectivity(
    const QueryGraph & query_graph,
    const PlanMemo & dp_table,
    SelectivityCache & expression_selectivity,
    const std::vector<JoinActionRef *> & edges,
    const BitSet & left,
    const BitSet & right)
{
    double selectivity = DB::computeSelectivity(query_graph, dp_table, expression_selectivity, edges);

    /// Also account for transitively-equivalent columns spanning both sides.
    using ConstClassPtr = EquivalenceClasses<JoinActionRef>::ConstClassPtr;
    std::unordered_set<ConstClassPtr> visited;

    for (const auto & [member, _] : query_graph.column_equivalences.getMemberToClassMap())
    {
        auto member_rel = member.getSourceRelations().getSingleBit();
        if (!member_rel || !left.test(*member_rel))
            continue;

        auto equiv_class = query_graph.column_equivalences.getClass(member);
        if (!equiv_class || !visited.insert(equiv_class).second)
            continue;

        /// Find the maximum NDV across all members of this class that belong
        /// to either side of the join. This is equivalent to evaluating all
        /// (left_member, right_member) pairs and taking the minimum selectivity,
        /// since min(1/max(l,r)) = 1/max(all l's and r's).
        size_t max_ndv = 0;
        bool has_left = false;
        bool has_right = false;
        for (const auto & equiv_member : *equiv_class)
        {
            auto relation = equiv_member.getSourceRelations().getSingleBit();
            if (!relation)
                continue;
            if (left.test(*relation))
            {
                has_left = true;
                max_ndv = std::max(max_ndv, getColumnStats(query_graph, dp_table, equiv_member.getSourceRelations(), equiv_member.getColumnName()));
            }
            else if (right.test(*relation))
            {
                has_right = true;
                max_ndv = std::max(max_ndv, getColumnStats(query_graph, dp_table, equiv_member.getSourceRelations(), equiv_member.getColumnName()));
            }
        }
        if (has_left && has_right && max_ndv > 0)
            selectivity = std::min(selectivity, 1.0 / static_cast<double>(max_ndv));
    }

    return selectivity;
}

bool connects(const JoinActionRef * predicate, const BitSet & left, const BitSet & right)
{
    const auto & participating = predicate->getSourceRelations();
    return areIntersecting(participating, left) && areIntersecting(participating, right);
}

DPJoinEntryPtr evaluateJoin(
    const QueryGraph & query_graph,
    PlanMemo & dp_table,
    SelectivityCache & expression_selectivity,
    const DPJoinEntryPtr & left,
    const DPJoinEntryPtr & right,
    JoinKind join_kind,
    std::vector<JoinActionRef *> & predicates,
    LoggerPtr log)
{
    auto selectivity = computeSelectivity(query_graph, dp_table, expression_selectivity, predicates, left->relations, right->relations);
    auto new_cost = computeJoinCost(left, right, selectivity);

    const BitSet combined_rels = left->relations | right->relations;
    auto current_best = dp_table.find(combined_rels);
    if (current_best != dp_table.end() && new_cost >= current_best->second->cost)
        return nullptr;

    /// Transitively connected pairs are inner joins; their predicate is synthesized later.
    bool connected = !predicates.empty()
        || query_graph.areTransitivelyConnected(left->relations, right->relations);
    auto effective_kind = (connected && join_kind == JoinKind::Cross) ? JoinKind::Inner : join_kind;
    auto cardinality = estimateJoinCardinality(left, right, selectivity, effective_kind);
    JoinOperator join_operator(
        effective_kind, JoinStrictness::All, JoinLocality::Unspecified,
        std::ranges::to<std::vector>(predicates | std::views::transform([](const auto * p) { return *p; })));
    auto new_entry = std::make_shared<DPJoinEntry>(left, right, new_cost, cardinality, std::move(join_operator));

    LOG_TEST(log, "New best plan for '{}' as '{} JOIN {}', cost: {}, cardinality: {}, operator: {}",
        new_entry->dump(), left->dump(), right->dump(),
        new_entry->cost, new_entry->estimated_rows ? toString(*new_entry->estimated_rows) : "unknown",
        new_entry->join_operator.dump());

    dp_table[combined_rels] = new_entry;
    return new_entry;
}

void DPHypJoinOrderOptimizer::checkLimits()
{
    if (query_status)
        query_status->checkTimeLimit();
    if (interactive_cancel_callback)
        interactive_cancel_callback();
}

bool DPHypJoinOrderOptimizer::continueEnumeration()
{
    if (dphyp_unsupported_predicate || search_budget_exceeded)
        return false;
    ++searched_plans;
    if (max_searched_plans && searched_plans > max_searched_plans)
    {
        search_budget_exceeded = true;
        LOG_TRACE(log, "Exceeded the limit of {} searched plans, falling back", max_searched_plans);
        return false;
    }
    /// `checkLimits` invokes the interactive cancel callback, which can send progress over the
    /// network and snapshot profile events. Poll it once every few thousand enumerated subsets
    /// instead of on every one, which would otherwise dominate the optimization time.
    if ((searched_plans & 0xFFF) == 0)
        checkLimits();
    return true;
}

void DPHypJoinOrderOptimizer::tryJoin(const BitSet & left_rels, const BitSet & right_rels)
{
    auto left_entry = dp_table.find(left_rels);
    if (left_entry == dp_table.end())
        return;

    auto right_entry = dp_table.find(right_rels);
    if (right_entry == dp_table.end())
        return;

    auto join_kind = isValidJoinOrder(query_graph, left_rels, right_rels);
    if (!join_kind)
        return;

    /// Restrict to inner joins for now (same as DPsize FIXME)
    if (*join_kind != JoinKind::Inner)
        return;

    auto applicable_predicates = getApplicableExpressions(query_graph, left_rels, right_rels);
    std::vector<JoinActionRef *> connecting_predicates;
    for (auto * predicate : applicable_predicates)
    {
        if (connects(predicate, left_rels, right_rels))
        {
            connecting_predicates.push_back(predicate);
            continue;
        }

        /// Predicates spanning 2+ relations were already applied in a sub-join.
        /// Single-table or constant predicates (e.g. moved into `ON` by
        /// `query_plan_merge_filter_into_join_condition`) are not handled by `dphyp` here;
        /// `dpsize` attaches them at the smallest containing join, but `dphyp` would need
        /// extra bookkeeping to avoid double-application. For now, mark the query as
        /// unsupported and let `solve` return `nullptr` so the fallback chain runs.
        if (predicate->getSourceRelations().count() < 2)
        {
            LOG_TRACE(log, "DPhyp cannot attach non-connecting predicate {} (sources: {{ {} }}), falling back",
                predicate->dump(), fmt::join(predicate->getSourceRelations(), ","));
            dphyp_unsupported_predicate = true;
            return;
        }
    }

    /// When no explicit predicate connects the two sides, check transitive connectivity
    /// via column equivalence classes (e.g. A.key=B.key AND B.key=C.key implies A.key=C.key).
    /// `cleanupJoinPredicates` will synthesize the missing predicate after optimization.
    if (connecting_predicates.empty()
        && !query_graph.areTransitivelyConnected(left_rels, right_rels))
        return;

    evaluateJoin(query_graph, dp_table, expression_selectivity, left_entry->second, right_entry->second, *join_kind, connecting_predicates, log);
}

void DPHypJoinOrderOptimizer::buildHyperedges()
{
    const size_t num_relations = query_graph.relation_stats.size();
    node_to_edge_ids.assign(num_relations, {});
    hyperedges.clear();

    auto add_hyperedge = [&](const BitSet & left_rels, const BitSet & right_rels)
    {
        size_t hyperedge_id = hyperedges.size();
        hyperedges.push_back({left_rels, right_rels});

        for (auto rel : left_rels)
            if (rel < num_relations)
                node_to_edge_ids[rel].push_back(hyperedge_id);
        for (auto rel : right_rels)
            if (rel < num_relations && !left_rels.test(rel))
                node_to_edge_ids[rel].push_back(hyperedge_id);
    };

    /// Phase 1: create hyperedges from explicit join predicates.
    /// Duplicate edges for the same relation pair (e.g. A.x=B.x AND A.y=B.y) are harmless:
    /// `getNeighborhood` ORs results into a BitSet, and `tryJoin` collects predicates
    /// from `query_graph.edges`, not from hyperedges.
    for (const auto & predicate : query_graph.edges)
    {
        if (!predicate)
            continue;

        BitSet left_rels;
        BitSet right_rels;

        auto [op, lhs, rhs] = predicate.asBinaryPredicate();
        if (op != JoinConditionOperator::Unknown && lhs && rhs)
        {
            left_rels  = lhs.getSourceRelations();
            right_rels = rhs.getSourceRelations();
        }
        else
        {
            /// Non-binary predicate: treat the full source set as both endpoints.
            left_rels  = predicate.getSourceRelations();
            right_rels = predicate.getSourceRelations();
        }

        if (!left_rels.any() || !right_rels.any())
            continue;

        add_hyperedge(left_rels, right_rels);
    }

    /// Phase 2: add synthetic hyperedges for transitively-connected relation pairs.
    /// Column equivalence classes (e.g. A.key=B.key AND B.key=C.key implies A.key=C.key)
    /// connect relations that have no direct predicate. Without these edges DPhyp's
    /// neighborhood traversal would never discover the pair.

    /// Build a connectivity matrix from explicit edges to avoid duplicating them.
    std::vector<BitSet> connected_rels(num_relations);
    for (const auto & hyperedge : hyperedges)
    {
        auto left_rel = hyperedge.left.getSingleBit();
        auto right_rel = hyperedge.right.getSingleBit();
        if (left_rel && right_rel)
        {
            connected_rels[*left_rel].set(*right_rel);
            connected_rels[*right_rel].set(*left_rel);
        }
    }

    using ConstClassPtr = EquivalenceClasses<JoinActionRef>::ConstClassPtr;
    std::unordered_set<ConstClassPtr> processed_classes;

    for (const auto & [member, equiv_class] : query_graph.column_equivalences.getMemberToClassMap())
    {
        if (!equiv_class || !processed_classes.insert(equiv_class).second)
            continue;

        /// Collect all distinct relations in this equivalence class.
        BitSet seen_rels;
        std::vector<size_t> class_rels;
        for (const auto & column : *equiv_class)
        {
            auto relation = column.getSourceRelations().getSingleBit();
            if (relation && *relation < num_relations && !seen_rels.test(*relation))
            {
                seen_rels.set(*relation);
                class_rels.push_back(*relation);
            }
        }

        for (size_t i = 0; i < class_rels.size(); ++i)
        {
            for (size_t j = i + 1; j < class_rels.size(); ++j)
            {
                if (connected_rels[class_rels[i]].test(class_rels[j]))
                    continue;

                connected_rels[class_rels[i]].set(class_rels[j]);
                connected_rels[class_rels[j]].set(class_rels[i]);

                BitSet left_singleton;
                BitSet right_singleton;
                left_singleton.set(class_rels[i]);
                right_singleton.set(class_rels[j]);
                add_hyperedge(left_singleton, right_singleton);
            }
        }
    }
}

BitSet DPHypJoinOrderOptimizer::getNeighborhood(const BitSet & node_set) const
{
    BitSet neighbors;
    BitSet visited_edges;
    for (auto node : node_set)
    {
        if (node >= node_to_edge_ids.size())
            continue;
        for (auto hyperedge_id : node_to_edge_ids[node])
        {
            if (visited_edges.test(hyperedge_id))
                continue;
            visited_edges.set(hyperedge_id);
            const auto & edge = hyperedges[hyperedge_id];
            if (edge.left == edge.right)
            {
                /// In case of non-binary predicate (`f(A,B,C) = const`) the hyperedge is
                /// represented as L={A,B,C}, R={A,B,C}
                neighbors |= edge.left;
            }
            else
            {
                if (isSubsetOf(edge.left, node_set))
                    neighbors |= edge.right;
                if (isSubsetOf(edge.right, node_set))
                    neighbors |= edge.left;
            }
        }
    }
    auto result = neighbors.andNot(node_set);
    LOG_TEST(log, "DPhyp: getNeighborhood({}) = {}",
        fmt::join(node_set, ","), fmt::join(result, ","));
    return result;
}

void forEachNonEmptySubset(const BitSet & mask, F && func)
{
    std::vector<size_t> bit_positions;
    for (auto bit : mask)
        bit_positions.push_back(bit);

    const size_t num_bits = bit_positions.size();
    if (num_bits == 0)
        return;
    chassert(num_bits < 64);

    const UInt64 num_subsets = 1ULL << num_bits;
    for (UInt64 subset_mask = 1; subset_mask < num_subsets; ++subset_mask)
    {
        BitSet subset;
        for (size_t i = 0; i < num_bits; ++i)
            if (subset_mask & (1ULL << i))
                subset.set(bit_positions[i]);
        /// The callback returns false to stop enumeration early.
        if (!func(subset))
            return;
    }
}

void DPHypJoinOrderOptimizer::emitCsgCmp(const BitSet & left_csg, const BitSet & right_csg)
{
    if (dphyp_unsupported_predicate)
        return;
    LOG_TEST(log, "DPhyp: emitCsgCmp({{ {} }}, {{ {} }})",
        fmt::join(left_csg, ","), fmt::join(right_csg, ","));
    tryJoin(left_csg, right_csg);
}

void DPHypJoinOrderOptimizer::enumerateCmpRec(const BitSet & csg, const BitSet & complement, const BitSet & exclusion)
{
    if (dphyp_unsupported_predicate)
        return;

    LOG_TEST(log, "DPhyp: enumerateCmpRec(csg={{ {} }}, cmp={{ {} }}, excl={{ {} }})",
        fmt::join(csg, ","), fmt::join(complement, ","), fmt::join(exclusion, ","));

    BitSet complement_neighborhood = getNeighborhood(complement).andNot(exclusion);
    if (!complement_neighborhood)
        return;

    LOG_TEST(log, "DPhyp: enumerateCmpRec neighborhood={{ {} }}",
        fmt::join(complement_neighborhood, ","));

    /// First pass: emit pairs for every connected extension of the complement.
    forEachNonEmptySubset(complement_neighborhood, [&](const BitSet & extension)
    {
        if (!continueEnumeration())
            return false;
        BitSet extended_complement = complement | extension;
        if (dp_table.contains(extended_complement))
            emitCsgCmp(csg, extended_complement);
        return true;
    });

    /// Second pass: recurse with extended exclusion (paper: X = X | N(S2, X)).
    BitSet incremental_exclusion = exclusion | complement_neighborhood;
    forEachNonEmptySubset(complement_neighborhood, [&](const BitSet & extension)
    {
        if (!continueEnumeration())
            return false;
        enumerateCmpRec(csg, complement | extension, incremental_exclusion);
        return true;
    });
}

void DPHypJoinOrderOptimizer::emitCsg(const BitSet & csg)
{
    if (dphyp_unsupported_predicate)
        return;
    LOG_TEST(log, "DPhyp: emitCsg({{ {} }})", fmt::join(csg, ","));

    BitSet exclusion = csg | BitSet::allSet(*csg.begin());

    BitSet csg_neighborhood = getNeighborhood(csg).andNot(exclusion);
    if (!csg_neighborhood)
        return;

    LOG_TEST(log, "DPhyp: emitCsg neighborhood={{ {} }}, exclusion={{ {} }}",
        fmt::join(csg_neighborhood, ","), fmt::join(exclusion, ","));

    std::vector<size_t> neighbor_nodes;
    for (size_t n : csg_neighborhood)
        neighbor_nodes.push_back(n);

    /// Process seeds in descending index order, excluding each already-processed seed from the
    /// complements grown by later seeds. Without this, the same complement (e.g. {1,2}) would be
    /// reached from both the {2} seed and the {1} seed, enumerating the (S1, S2) pair twice.
    BitSet seed_exclusion = exclusion;
    for (auto it = neighbor_nodes.rbegin(); it != neighbor_nodes.rend(); ++it)
    {
        if (!continueEnumeration())
            return;
        BitSet single_node;
        single_node.set(*it);
        emitCsgCmp(csg, single_node);
        enumerateCmpRec(csg, single_node, seed_exclusion);
        seed_exclusion.set(*it);
    }
}

void DPHypJoinOrderOptimizer::enumerateCsgRec(const BitSet & csg, const BitSet & exclusion)
{
    if (dphyp_unsupported_predicate)
        return;

    LOG_TEST(log, "DPhyp: enumerateCsgRec(csg={{ {} }}, excl={{ {} }})",
        fmt::join(csg, ","), fmt::join(exclusion, ","));

    BitSet neighborhood = getNeighborhood(csg).andNot(exclusion);
    if (!neighborhood)
        return;

    LOG_TEST(log, "DPhyp: enumerateCsgRec neighborhood={{ {} }}",
        fmt::join(neighborhood, ","));

    /// First pass: emit complements for every connected extension of S1.
    forEachNonEmptySubset(neighborhood, [&](const BitSet & extension)
    {
        if (!continueEnumeration())
            return false;
        BitSet extended_csg = csg | extension;
        if (dp_table.contains(extended_csg))
            emitCsg(extended_csg);
        return true;
    });

    /// Second pass: recurse with extended exclusion (paper: X = X | N(S1, X)).
    BitSet extended_exclusion = exclusion | neighborhood;
    forEachNonEmptySubset(neighborhood, [&](const BitSet & extension)
    {
        if (!continueEnumeration())
            return false;
        enumerateCsgRec(csg | extension, extended_exclusion);
        return true;
    });
}

std::shared_ptr<DPJoinEntry> DPHypJoinOrderOptimizer::solve()
{
    const size_t num_relations = query_graph.relation_stats.size();

    /// DPhyp's subset enumeration uses a 64-bit bitmask, so it cannot handle neighborhoods
    /// larger than 63 relations. Bail out gracefully so the fallback algorithm chain can continue.
    if (num_relations >= 64)
    {
        LOG_TRACE(log, "Too many relations ({}) for DPhyp, falling back", num_relations);
        return nullptr;
    }

    dphyp_unsupported_predicate = false;
    search_budget_exceeded = false;
    searched_plans = 0;

    /// Initialize dp_table with a leaf entry for each base relation.
    /// Also reset the per-edge selectivity cache so this run is independent of any
    /// earlier algorithm in the fallback chain.
    dp_table.clear();
    expression_selectivity.clear();
    for (size_t i = 0; i < num_relations; ++i)
    {
        const auto & rel = query_graph.relation_stats[i];
        auto entry = std::make_shared<DPJoinEntry>(i, rel.estimated_rows, rel.column_stats);
        dp_table[entry->relations] = entry;
    }

    buildHyperedges();

    LOG_TEST(log, "DPhyp: {} relations, {} hyperedges", num_relations, hyperedges.size());
    for (size_t e = 0; e < hyperedges.size(); ++e)
        LOG_TEST(log, "DPhyp: hyperedge {}: ({{ {} }}, {{ {} }})", e,
            fmt::join(hyperedges[e].left, ","), fmt::join(hyperedges[e].right, ","));

    /// Main DPhyp loop (paper: Solve, Sec 3.1).
    /// Seed with each single-relation CSG in descending index order.
    /// For each seed {v}, `emitCsg` finds complements (the other side of the join),
    /// and `enumerateCsgRec` grows {v} into larger connected subgraphs.
    /// The exclusion set B_v = {w : w < v} | {v} ensures each unordered (S1, S2) pair
    /// is considered exactly once (the side with the smaller min-index is always S1).
    BitSet exclusion = BitSet::allSet(num_relations);
    for (int i = static_cast<int>(num_relations) - 1; i >= 0; --i)
    {
        /// Once enumeration is aborted, the result is discarded below, so stop seeding.
        if (dphyp_unsupported_predicate || search_budget_exceeded)
            break;

        BitSet seed;
        seed.set(static_cast<size_t>(i));

        LOG_TEST(log, "DPhyp: === seed {} ===", i);
        emitCsg(seed);
        exclusion.set(i, false);
        enumerateCsgRec(seed, exclusion);
    }

    if (dphyp_unsupported_predicate || search_budget_exceeded)
    {
        LOG_TRACE(log, "DPhyp could not produce a plan ({}), falling back",
            dphyp_unsupported_predicate ? "unsupported predicate" : "search budget exceeded");
        return nullptr;
    }

    auto best = dp_table.find(BitSet::allSet(num_relations));
    if (best != dp_table.end())
        return best->second;

    /// DPhyp cannot produce a plan for disconnected graphs (no cross products).
    /// The caller's fallback chain (e.g. dphyp,greedy) handles this.
    LOG_TRACE(log, "Failed to find best plan using DPhyp algorithm");
    return nullptr;
}

DPJoinEntryPtr solveDPHypJoinOrder(
    QueryGraph & query_graph,
    UInt64 max_searched_plans,
    QueryStatusPtr query_status,
    std::function<bool()> interactive_cancel_callback)
{
    return DPHypJoinOrderOptimizer(
        query_graph,
        max_searched_plans,
        std::move(query_status),
        std::move(interactive_cancel_callback)).solve();
}

void DPSizeJoinOrderOptimizer::checkLimits()
{
    if (query_status)
        query_status->checkTimeLimit();
    if (interactive_cancel_callback)
        interactive_cancel_callback();
}

DPJoinEntryPtr DPSizeJoinOrderOptimizer::solve()
{
    const size_t total_relations_count = query_graph.relation_stats.size();

    /// Components by size (index 0 is not used that why the size is N+1)
    std::vector<std::unordered_map<BitSet, DPJoinEntryPtr>> components(total_relations_count + 1);

    /// Populate DP table for components of size=1.
    /// Also reset the per-edge selectivity cache so an earlier algorithm in the
    /// fallback chain cannot leak cached `1.0` defaults from a partial `dp_table`.
    dp_table.clear();
    expression_selectivity.clear();
    searched_plans = 0;
    for (size_t i = 0; i < total_relations_count; ++i)
    {
        const auto & rel = query_graph.relation_stats[i];
        auto entry = std::make_shared<DPJoinEntry>(i, rel.estimated_rows, rel.column_stats);
        components[1][entry->relations] = entry;
        dp_table[entry->relations] = entry;
    }

    /// Iteratively build components of size from 2 to N
    for (size_t component_size = 2; component_size <= total_relations_count; ++component_size)
    {
        for (size_t smaller_component_size = 1; smaller_component_size <= component_size / 2; ++smaller_component_size)
        {
            const size_t bigger_component_size = component_size - smaller_component_size;

            for (const auto & [_, right] : components[smaller_component_size])
            {
                for (const auto & [_, left] : components[bigger_component_size])
                {
                    /// Do components overlap?
                    if (left->relations & right->relations)
                        continue;

                    /// If both components are of the same size then check each pair just once, not twice
                    if (smaller_component_size == bigger_component_size && *left->relations.begin() > *right->relations.begin())
                        continue;

                    ++searched_plans;
                    if (max_searched_plans && searched_plans > max_searched_plans)
                    {
                        LOG_TRACE(log, "Exceeded the limit of {} searched plans, falling back", max_searched_plans);
                        return nullptr;
                    }
                    /// `checkLimits` invokes the interactive cancel callback, which can send progress over
                    /// the network. Poll it once every few thousand pairs instead of on every one.
                    if ((searched_plans & 0xFFF) == 0)
                        checkLimits();

                    auto join_kind = isValidJoinOrder(query_graph, left->relations, right->relations);
                    if (!join_kind)
                        continue;

                    /// FIXME: Restrict to Inner joins for now because isValidJoinOrder seems to not handle non-Inner joins with swapped inputs correctly
                    if (*join_kind != JoinKind::Inner)
                        continue;

                    auto applicable_edge = getApplicableExpressions(query_graph, left->relations, right->relations);
                    /// Only leave the edges that connect left and right.
                    /// DPsize also includes non-connecting predicates (single-table filters) at the earliest
                    /// stage (component_size == 2), unlike DPhyp which handles them separately via the hyperedge graph.
                    std::vector<JoinActionRef *> edge;
                    for (auto & edge_it : applicable_edge)
                    {
                        if (connects(edge_it, left->relations, right->relations))
                        {
                            LOG_TEST(log, "Adding predicate connecting {} and {} : {}", left->dump(), right->dump(), edge_it->dump());
                            edge.push_back(edge_it);
                        }
                        else if ((edge_it->fromLeft() || edge_it->fromRight() || edge_it->fromNone()) && component_size == 2)
                        {
                            LOG_TEST(log, "Adding early non-connecting predicate for {} and {} : {}", left->dump(), right->dump(), edge_it->dump());
                            edge.push_back(edge_it);
                        }
                        else
                        {
                            LOG_TEST(log, "Skipping non-connecting predicate for {} and {} : {}", left->dump(), right->dump(), edge_it->dump());
                        }
                    }

                    bool connected = !edge.empty()
                        || query_graph.areTransitivelyConnected(left->relations, right->relations);

                    LOG_TEST(log, "Considering join between {} and {}, predicates count: {}, connected: {}",
                        left->dump(), right->dump(), edge.size(), connected);

                    if (!connected)
                        continue;

                    auto new_entry = evaluateJoin(query_graph, dp_table, expression_selectivity, left, right, *join_kind, edge, log);
                    if (new_entry)
                        components[component_size][new_entry->relations] = new_entry;
                }
            }
        }
    }

    auto best_full_plan = dp_table.find(BitSet::allSet(total_relations_count));
    if (best_full_plan != dp_table.end())
        return best_full_plan->second;

    LOG_TRACE(log, "Failed to find best plan using DPsize algorithm");
    return nullptr;
}

DPJoinEntryPtr solveDPSizeJoinOrder(
    QueryGraph & query_graph,
    UInt64 max_searched_plans,
    QueryStatusPtr query_status,
    std::function<bool()> interactive_cancel_callback)
{
    return DPSizeJoinOrderOptimizer(
        query_graph,
        max_searched_plans,
        std::move(query_status),
        std::move(interactive_cancel_callback)).solve();
}

UInt32 toMask(const BitSet & bits)
{
    UInt32 mask = 0;
    for (auto bit : bits)
    {
        chassert(bit < std::numeric_limits<UInt32>::digits);
        mask |= (static_cast<UInt32>(1) << bit);
    }
    return mask;
}

std::optional<UInt64> DPSubJoinOrderOptimizer::estimateCardinality(
    std::optional<UInt64> left_rows, std::optional<UInt64> right_rows, double selectivity, JoinKind join_kind) const
{
    return estimateJoinCardinality(left_rows, right_rows, selectivity, join_kind);
}

void DPSubJoinOrderOptimizer::initDPsubScratch()
{
    using EquivClass = EquivalenceClasses<JoinActionRef>::Class;

    const size_t num_relations = query_graph.relation_stats.size();
    const auto & edges = query_graph.edges;

    /// Edges: precompute the source-relation mask and any pin mask once per edge
    auto n = edges.size();
    dpsub_data.edge_source_mask.assign(n, 0);
    dpsub_data.edge_pin_mask.assign(n, 0);
    dpsub_data.edge_pinned.assign(n, 0);
    for (size_t i = 0; i < n; ++i)
    {
        const auto & edge = edges[i];
        if (!edge)
            continue;
        dpsub_data.edge_source_mask[i] = toMask(edge.getSourceRelations());
        /// ON-clause predicates of an outer join are pinned to the single null-supplying
        /// relation; the pin becomes applicable exactly when that relation is joined.
        if (auto pin_it = query_graph.outer_join_conditions.find(edge); pin_it != query_graph.outer_join_conditions.end())
        {
            dpsub_data.edge_pinned[i] = 1;
            dpsub_data.edge_pin_mask[i] = static_cast<UInt32>(1) << pin_it->second;
        }
    }

    /// Outer-join restrictions: index by the null-supplying relation
    dpsub_data.restriction_by_rel.assign(num_relations, {});
    for (const auto & [rel, restriction] : query_graph.join_kinds)
    {
        if (rel >= num_relations)
            continue;
        auto & native = dpsub_data.restriction_by_rel[rel];
        native.required = toMask(restriction.first);
        native.kind = restriction.second;
        native.present = true;
    }

    /// Column-equivalence classes: build a per-relation incidence list so selectivity only
    /// visits the classes touching the left side instead of rescanning the whole member map
    dpsub_data.equiv_classes.clear();
    dpsub_data.rel_to_classes.assign(num_relations, {});
    std::unordered_map<const EquivClass *, UInt32> class_index;
    for (const auto & [member, class_ptr] : query_graph.column_equivalences.getMemberToClassMap())
    {
        if (!class_ptr)
            continue;
        auto rel = member.getSourceRelations().getSingleBit();
        if (!rel || *rel >= num_relations)
            continue;

        auto [it, inserted] = class_index.try_emplace(class_ptr.get(), static_cast<UInt32>(dpsub_data.equiv_classes.size()));
        if (inserted)
            dpsub_data.equiv_classes.push_back(class_ptr);
        dpsub_data.rel_to_classes[*rel].push_back(it->second);
    }
    dpsub_data.class_visited.assign(dpsub_data.equiv_classes.size(), 0);
    dpsub_data.equiv_generation = 0;
}

std::optional<JoinKind> DPSubJoinOrderOptimizer::isValidJoinOrderMask(UInt32 left_mask, UInt32 right_mask) const
{
    auto check = [&](UInt32 lhs, UInt32 rhs) -> std::optional<JoinKind>
    {
        if (std::popcount(lhs) == 1)
        {
            const auto & restriction = dpsub_data.restriction_by_rel[std::countr_zero(lhs)];
            if (restriction.present)
            {
                /// If there are any bits set in `restriction.required`
                /// that are not set in `rhs`, the bitwise AND (&) results in a non-zero value
                if (restriction.required & ~rhs)
                    return {};
                return restriction.kind;
            }
        }
        return JoinKind::Inner;
    };

    JoinKind left_join_type = JoinKind::Inner;
    JoinKind right_join_type = JoinKind::Inner;

    if (auto res = check(left_mask, right_mask))
        left_join_type = isLeftOrFull(res.value()) ? reverseJoinKind(res.value()) : res.value();
    else
        return {};

    if (auto res = check(right_mask, left_mask))
        right_join_type = isRightOrFull(res.value()) ? reverseJoinKind(res.value()) : res.value();
    else
        return {};

    if (left_join_type == JoinKind::Inner)
        return right_join_type;
    if (right_join_type == JoinKind::Inner)
        return left_join_type;
    if (left_join_type == JoinKind::Full && right_join_type == JoinKind::Full)
        return JoinKind::Full;

    /// Conflicting outer-join constraints, the order is not possible
    return {};
}

const std::vector<JoinActionRef *> & DPSubJoinOrderOptimizer::collectJoinEdgesMask(UInt32 left_mask, UInt32 right_mask)
{
    auto & out = dpsub_data.applicable_scratch;
    out.clear();

    const UInt32 joined = left_mask | right_mask;
    const bool two_relations = std::popcount(joined) == 2;
    auto & edges = query_graph.edges;

    for (size_t i = 0; i < edges.size(); ++i)
    {
        auto & edge = edges[i];
        if (!edge)
            continue;

        const UInt32 sources = dpsub_data.edge_source_mask[i];
        if (sources & ~joined) /// edge sources not proper subset of joined relations
            continue;
        if (dpsub_data.edge_pinned[i] && (dpsub_data.edge_pin_mask[i] & ~joined))
            continue;

        /// Works much like Extended Eligibility List (EEL) in case of outerjoins:
        /// encoding relations that must be present for the predicate to be applicable (in `pin` mask)
        /// For innerjoins its just the sources of the predicate, i.e., NEL, here pin is empty.
        /// For a single-table conjunct of an outer join's ON
        /// clause (e.g. `t2.value = 'x'` in `... LEFT JOIN t3 ON t2.id = t3.id AND t2.value = 'x'`),
        /// `sources` is only `{t2}` but the pin is `{t3}`: the predicate belongs to the ON condition of
        /// the join that brings in `t3`, not to `t2` as a base-table filter. Placing it by `sources`
        /// alone would push it below (or drop it from) that join, silently changing outer-join
        /// semantics, since `t2` may already have been NULL-extended (or default-filled) by an
        /// earlier join.
        const UInt32 pin = dpsub_data.edge_pinned[i] ? dpsub_data.edge_pin_mask[i] : 0;
        const UInt32 applicable = sources | pin;

        if (std::popcount(applicable) <= 1)
        {
            /// Base-relation filter or constant predicate (the edge references at most one relation).
            const bool relation_introduced = applicable != 0 && (left_mask == applicable || right_mask == applicable);
            const bool constant_at_earliest_join = applicable == 0 && two_relations;
            if (relation_introduced || constant_at_earliest_join)
                out.push_back(&edge);
        }
        else if ((applicable & ~left_mask) && (applicable & ~right_mask))
        {
            /// The predicate spans the split (a connecting equi-predicate, or a single-table ON-clause
            /// conjunct pinned to the opposite side): neither side alone contains all the relations it
            /// needs. This join is the lowest one that makes it applicable, so attach it here — into the
            /// correct join's ON condition.
            out.push_back(&edge);
        }
    }
    return out;
}

uble DPSubJoinOrderOptimizer::computeSelectivityMask(
    const std::vector<JoinActionRef *> & edges, UInt32 left_mask, UInt32 right_mask)
{
    double selectivity = DB::computeSelectivity(query_graph, dp_table, expression_selectivity, edges);

    /// Account for transitively-equivalent columns spanning both sides, visiting only the classes
    /// incident to the left relations. A generation stamp deduplicates classes without allocating
    const UInt64 generation = ++dpsub_data.equiv_generation;

    for (UInt32 remaining = left_mask; remaining;)
    {
        const UInt32 rel = std::countr_zero(remaining);
        remaining &= remaining - 1;

        for (UInt32 class_idx : dpsub_data.rel_to_classes[rel])
        {
            if (dpsub_data.class_visited[class_idx] == generation)
                continue;
            dpsub_data.class_visited[class_idx] = generation;

            size_t max_ndv = 0;
            bool has_left = false;
            bool has_right = false;
            for (const auto & equiv_member : *dpsub_data.equiv_classes[class_idx])
            {
                auto relation = equiv_member.getSourceRelations().getSingleBit();
                if (!relation)
                    continue;
                const UInt32 relation_bit = static_cast<UInt32>(1) << *relation;
                if (left_mask & relation_bit)
                {
                    has_left = true;
                    max_ndv = std::max(max_ndv, getColumnStats(query_graph, dp_table, equiv_member.getSourceRelations(), equiv_member.getColumnName()));
                }
                else if (right_mask & relation_bit)
                {
                    has_right = true;
                    max_ndv = std::max(max_ndv, getColumnStats(query_graph, dp_table, equiv_member.getSourceRelations(), equiv_member.getColumnName()));
                }
            }
            if (has_left && has_right && max_ndv > 0)
                selectivity = std::min(selectivity, 1.0 / static_cast<double>(max_ndv));
        }
    }

    return selectivity;
}

d::shared_ptr<DPJoinEntry> DPSubJoinOrderOptimizer::buildPhysicalPlan(const DPTable & dptable, const TUInt & S) const
{
    auto& entry = dptable[S];
    if (!entry.left && !entry.right)
        return std::make_shared<DPJoinEntry>(std::countr_zero(S), entry.estimated_rows, entry.column_stats);

    JoinOperator join_operator(entry.kind, JoinStrictness::All, JoinLocality::Unspecified);
    /// A filter predicate applied at an outer join step must not go to the ON clause, where it
    /// would affect matching instead of filtering and let non-matching rows of the preserved side
    /// survive NULL-extended. Apply it after the join instead (see `solveGreedy`).
    bool is_inner_step = isInner(entry.kind) || isCrossOrComma(entry.kind);
    for (const auto * e : entry.edges)
    {
        if (is_inner_step || query_graph.outer_join_conditions.contains(*e))
            join_operator.expression.push_back(*e);
        else
            join_operator.residual_filter.push_back(*e);
    }

    auto left = buildPhysicalPlan(dptable, entry.left);
    auto right = buildPhysicalPlan(dptable, entry.right);
    return std::make_shared<DPJoinEntry>(left, right, entry.cost, entry.estimated_rows, std::move(join_operator));
}

:shared_ptr<DPJoinEntry> DPSubJoinOrderOptimizer::solve()
{
    /// DPsub uses the generic memo only for composite-expression statistics. Clear any
    /// partial state left by an earlier algorithm in the fallback chain so this attempt
    /// has the same cost model as a standalone DPsub run.
    dp_table.clear();
    expression_selectivity.clear();

    const size_t n = query_graph.relation_stats.size();
    using Bitvector = UInt32; // choose UInt64 or even UInt128 for larger sets
    // A budget cap on nr. of connected components considered by DPsub to avoid excessive optimization time on large join graphs.
    // This budget cap is obtained from empirical testing using different queries and join graphs.
    static constexpr UInt32 max_nr_ccps = 50'000;

    if (n >= std::numeric_limits<Bitvector>::digits)
    {
        LOG_TRACE(log,
            "Number of relations {} exceeds the DP threshold {}, skipping DP optimization invoking greedy algorithm",
            n, std::numeric_limits<Bitvector>::digits);
        return nullptr;
    }

    struct DPEntry
    {
        Bitvector neighbor{0};
        Bitvector left{0};
        Bitvector right{0};
        std::optional<UInt64> estimated_rows = {};
        std::unordered_map<String, ColumnStats> column_stats = {};
        double cost{.0};
        double sel{.0};
        JoinKind kind{JoinKind::Inner};
        std::vector<JoinActionRef*> edges; // needed for physical plan generation
    };
    using DPTable = DPTable<DPEntry, Bitvector>;
    using Checker = EnumeratorCheckerWithCosts<DPTable, DPSubJoinOrderOptimizer>;
    using Enumerator = EnumCcpSub<Checker, DPTable, QueryGraph>;

    /// Precompute the native-mask view of the query graph so the acceptor's per-CCP work
    /// (validity, edge collection, selectivity) runs without allocating a `BitSet` each time
    /// That is, we don't have to convert Bitvector -> BitSet -> Bitvector for every subset S
    /// and its subcomponents S1, S2
    initDPsubScratch();

    Checker checker(n, *this);
    Enumerator enumerator(n, max_nr_ccps, log);
    enumerator.enumerate(checker, query_graph);

    const Bitvector full_set = (static_cast<Bitvector>(1) << n) - 1;
    const auto & dptable = checker.getDPTable();

    /// a. If the join graph is too complex we break early
    /// b. The full set is assembled only if the join graph is connected. When it is not e.g.
    /// cross products, or predicates that reference a single relation or a constant and thus
    /// create no binary edge (`... LEFT JOIN t ON t.x = 5`): DPsub cannot stitch the
    /// disconnected components, so the full-set entry is missing (or was never given a join)
    const bool full_built = dptable.isConnected(full_set)
                            && (dptable[full_set].left != 0 || dptable[full_set].right != 0);
    if (!full_built)
    {
        LOG_TRACE(log, "DPsub: join graph is either too complex or disconnected!");
        return nullptr;
    }

    return buildPhysicalPlan(dptable, full_set);
}

}

inEntryPtr solveDPSubJoinOrder(QueryGraph & query_graph)
{
    return DPSubJoinOrderOptimizer(query_graph).solve();
}

}

DPJoinEntryPtr GreedyJoinOrderOptimizer::solve()
{
    /// Discard any partial state left by an earlier algorithm in the fallback chain
    /// (e.g. `dphyp,greedy`) so cost-model lookups via `getColumnStats` only see
    /// entries built by this run. `expression_selectivity` is cleared along with
    /// `dp_table` because multi-relation predicates resolve NDV through it.
    dp_table.clear();
    expression_selectivity.clear();

    std::deque<std::shared_ptr<DPJoinEntry>> components;
    for (size_t i = 0; i < query_graph.relation_stats.size(); ++i)
    {
        const auto & rel = query_graph.relation_stats[i];
        components.push_back(std::make_shared<DPJoinEntry>(i, rel.estimated_rows, rel.column_stats));
    }

    std::vector<JoinActionRef *> applied_edges;
    /// Iteratively join components until we have a single plan
    while (components.size() > 1)
    {
        std::shared_ptr<DPJoinEntry> best_plan = nullptr;
        size_t best_i = 0;
        size_t best_j = 0;

        /// Try all pairs of components
        for (size_t i = 0; i < components.size(); i++)
        {
            for (size_t j = i + 1; j < components.size(); j++)
            {
                auto left = components[i];
                auto right = components[j];

                auto join_kind = isValidJoinOrder(query_graph, left->relations, right->relations);
                if (!join_kind)
                    continue;

                auto edges = getApplicableExpressions(query_graph, left->relations, right->relations);
                bool connected = !edges.empty()
                    || query_graph.areTransitivelyConnected(left->relations, right->relations);
                if (!connected && best_plan)
                    continue;

                auto selectivity = computeSelectivity(query_graph, dp_table, expression_selectivity, edges, left->relations, right->relations);
                auto current_cost = computeJoinCost(left, right, selectivity);
                if (!best_plan || current_cost < best_plan->cost)
                {
                    if (join_kind == JoinKind::Inner && !connected)
                        join_kind = JoinKind::Cross;
                    auto cardinality = estimateJoinCardinality(left, right, selectivity, join_kind.value());
                    JoinOperator join_operator(join_kind.value(), JoinStrictness::All, JoinLocality::Unspecified);
                    bool is_inner_step = isInner(join_kind.value()) || isCrossOrComma(join_kind.value());
                    for (const auto * e : edges)
                    {
                        /// A filter predicate applied at an outer join step must not go to the
                        /// ON clause, where it would affect matching instead of filtering and
                        /// let non-matching rows of the preserved side survive NULL-extended.
                        /// Apply it after the join instead.
                        if (is_inner_step || query_graph.outer_join_conditions.contains(*e))
                            join_operator.expression.push_back(*e);
                        else
                            join_operator.residual_filter.push_back(*e);
                    }
                    applied_edges = std::move(edges);
                    best_plan = std::make_shared<DPJoinEntry>(left, right, current_cost, cardinality, std::move(join_operator));
                    best_i = i;
                    best_j = j;
                }
            }
        }

        /// The loop above accepts any pair passing isValidJoinOrder, even an unconnected
        /// one (which becomes a cross product), as long as no best plan exists yet. So
        /// reaching this point means no pair of components can be joined at all: the
        /// outer join restrictions are stuck. This cannot happen for a query graph built
        /// from a well-formed join tree: required partner sets follow the original tree's
        /// scoping, so the original join order always remains valid.
        if (!best_plan)
            throw Exception(ErrorCodes::LOGICAL_ERROR,
                "No valid join pair found among components [{}], the outer join restrictions cannot be satisfied",
                fmt::join(components | std::views::transform([](const auto & c) { return c->dump(); }), ", "));

        LOG_TEST(log, "Best plan for '{}' as '{} JOIN {}', cost: {}, cardinality: {}, join operator: {}",
            best_plan->dump(), best_plan->left->dump(), best_plan->right->dump(),
            best_plan->cost, best_plan->estimated_rows ? toString(*best_plan->estimated_rows) : "unknown",
            best_plan->join_operator.dump());

        /// replace the two components with the best plan
        components.erase(components.begin() + std::max(best_i, best_j));
        components.erase(components.begin() + std::min(best_i, best_j));
        components.push_front(best_plan);
        dp_table[best_plan->relations] = best_plan;

        for (auto * edge : applied_edges)
            *edge = nullptr;
    }

    for (auto * edge : applied_edges)
        *edge = nullptr;

    auto non_applied_edges = std::views::filter(query_graph.edges, [](auto & edge) { return bool(edge); });
    if (!non_applied_edges.empty())
        throw Exception(ErrorCodes::LOGICAL_ERROR, "Some expressions was not applied: [{}]",
            fmt::join(non_applied_edges | std::views::take(5) | std::views::transform(&JoinActionRef::dump), ", "));

    return components.at(0);
}

bool isSameSetting(const String & left, const String & right)
{
    auto resolve = [](const String & name)
    { return MergeTreeSettings::hasBuiltin(name) ? MergeTreeSettings::resolveName(name) : std::string_view(name); };
    return resolve(left) == resolve(right);
}

bool setHasEmptyArray(const DataTypePtr & index_type, const ColumnPtr & set_column, size_t row_size)
{
    if (!WhichDataType(index_type).isArray())
        return false;

    const auto * array_column = checkAndGetColumn<ColumnArray>(set_column.get());
    if (!array_column)
        return true;

    for (size_t row = 0; row < row_size; ++row)
        if (array_column->getSize(row) == 0)
            return true;

    return false;
}

SettingsChanges MergeTreeSettings::changesFrom(const MergeTreeSettings & base) const
{
    SettingsChanges res;
    for (const auto & setting : impl->all())
    {
        auto value = setting.getValue();
        if (value != base.impl->get(setting.getName()))
            res.emplace_back(String{setting.getName()}, value);
    }
    return res;
}

void IcebergMetadata::checkTableRootIsQueriedPath(std::string_view operation) const
{
    if (!persistent_components.table_root_was_derived)
        return;

    throw Exception(
        ErrorCodes::NOT_IMPLEMENTED,
        "{} is not supported for an Iceberg table whose directory '{}' is below the queried path '{}'. "
        "Query the table directory itself instead of naming a deeper metadata file with the "
        "iceberg_metadata_file_path setting.",
        operation,
        persistent_components.path_resolver.getTableRoot(),
        persistent_components.table_path);
}

std::string_view trimTrailingSlashes(std::string_view str)
{
    while (!str.empty() && str.back() == '/')
        str.remove_suffix(1);
    return str;
}

IcebergPathResolver::TableRootDerivation IcebergPathResolver::deriveTableRoot(
    const String & table_location, const String & queried_path, const String & metadata_file_key)
{
    static constexpr std::string_view metadata_dir = "/metadata/";

    auto queried = trimTrailingSlashes(queried_path);
    auto key = trimTrailingSlashes(metadata_file_key);

    /// Only a document directly inside the table's own `metadata` directory names the table root.
    auto metadata_dir_pos = key.rfind(metadata_dir);
    if (metadata_dir_pos == std::string_view::npos
        || key.find('/', metadata_dir_pos + metadata_dir.size()) != std::string_view::npos)
        return {queried_path, RootRelation::Unknown};
    auto candidate = key.substr(0, metadata_dir_pos);

    if (candidate == queried)
        return {queried_path, RootRelation::Same};

    /// A component-aligned proper descendant; an empty queried path is the storage root.
    const bool is_descendant = queried.empty()
        ? !candidate.empty()
        : candidate.size() > queried.size() && candidate.starts_with(queried) && candidate[queried.size()] == '/';
    if (!is_descendant)
        return {queried_path, RootRelation::Unknown};

    auto strip_leading_slash = [](std::string_view str) { return str.starts_with('/') ? str.substr(1) : str; };

    /// Adopt only when the declared location denotes that same directory. It may differ from the
    /// storage path by a leading slash and by a `<scheme>://<authority>/` prefix, both of which
    /// still name that directory; a prefix carrying a path component names a different one.
    auto location = strip_leading_slash(trimTrailingSlashes(table_location));
    auto tail = strip_leading_slash(candidate);
    if (tail.empty())
        return {queried_path, RootRelation::Unknown};
    bool location_agrees = location == tail;
    if (!location_agrees && location.size() > tail.size() && location.ends_with(tail)
        && location[location.size() - tail.size() - 1] == '/')
    {
        auto prefix = location.substr(0, location.size() - tail.size());
        auto scheme_end = prefix.find("://");
        location_agrees = scheme_end != std::string_view::npos && prefix.find('/', scheme_end + 3) == prefix.size() - 1;
    }
    if (!location_agrees)
        return {queried_path, RootRelation::Unknown};

    return {String(candidate), RootRelation::AdoptedDescendant};
}

void check(const DeriveTableRootCase & test_case)
{
    auto derivation = IcebergPathResolver::deriveTableRoot(
        test_case.table_location, test_case.queried_path, test_case.metadata_file_key);
    EXPECT_EQ(derivation.table_root, test_case.expected_table_root) << test_case.name;
    EXPECT_EQ(static_cast<int>(derivation.relation), static_cast<int>(test_case.expected_relation)) << test_case.name;
}

TEST(IcebergDeriveTableRoot, AbsoluteStoragePath)
{
    check({"authority location", "hdfs://hdfs1:9000/warehouse/tbl", "/warehouse",
        "/warehouse/tbl/metadata/v2.metadata.json",
        "/warehouse/tbl", IcebergPathResolver::RootRelation::AdoptedDescendant});

    /// The tail matches only mid-component, so the two paths name different directories.
    check({"tail is not component-aligned", "hdfs://h:9000/xwarehouse/tbl", "/warehouse",
        "/warehouse/tbl/metadata/v2.metadata.json",
        "/warehouse", IcebergPathResolver::RootRelation::Unknown});
}

TEST(IcebergDeriveTableRoot, LocationDiffersOnlyByAuthority)
{
    check({"hdfs", "hdfs://host:9000/tbl/UUIDDIR", "/tbl", "/tbl/UUIDDIR/metadata/v2.metadata.json",
        "/tbl/UUIDDIR", IcebergPathResolver::RootRelation::AdoptedDescendant});

    check({"abfss", "abfss://container@account.dfs.core.windows.net/tbl/UUIDDIR", "tbl",
        "tbl/UUIDDIR/metadata/v2.metadata.json",
        "tbl/UUIDDIR", IcebergPathResolver::RootRelation::AdoptedDescendant});

    check({"virtual-hosted s3", "https://mybucket.s3.amazonaws.com/tbl/UUIDDIR", "tbl",
        "tbl/UUIDDIR/metadata/v2.metadata.json",
        "tbl/UUIDDIR", IcebergPathResolver::RootRelation::AdoptedDescendant});

    check({"no scheme", "/tbl/UUIDDIR", "tbl", "tbl/UUIDDIR/metadata/v2.metadata.json",
        "tbl/UUIDDIR", IcebergPathResolver::RootRelation::AdoptedDescendant});

    check({"s3", "s3://warehouse/tbl/UUIDDIR", "tbl", "tbl/UUIDDIR/metadata/v2.metadata.json",
        "tbl/UUIDDIR", IcebergPathResolver::RootRelation::AdoptedDescendant});

    /// A Spark warehouse of many tables, queried at the warehouse instead of at one table.
    check({"spark warehouse", "s3a://spark-bucket/warehouse/db/spark_table", "warehouse",
        "warehouse/db/spark_table/metadata/v2.metadata.json",
        "warehouse/db/spark_table", IcebergPathResolver::RootRelation::AdoptedDescendant});
}

TEST(IcebergDeriveTableRoot, LocationHasUnmatchedPathComponent)
{
    check({"stale copied location", "s3://old/backup/warehouse/db/t", "warehouse",
        "warehouse/db/t/metadata/v2.metadata.json",
        "warehouse", IcebergPathResolver::RootRelation::Unknown});

    check({"no scheme", "/backup/warehouse/db/t", "warehouse",
        "warehouse/db/t/metadata/v2.metadata.json",
        "warehouse", IcebergPathResolver::RootRelation::Unknown});

    check({"absolute storage path", "hdfs://h:9000/other/warehouse/tbl", "/warehouse",
        "/warehouse/tbl/metadata/v2.metadata.json",
        "/warehouse", IcebergPathResolver::RootRelation::Unknown});
}

TEST(IcebergDeriveTableRoot, RelativeStoragePath)
{
    check({"uri location", "s3://test/dir/t1/sub", "dir/t1", "dir/t1/sub/metadata/v2.metadata.json",
        "dir/t1/sub", IcebergPathResolver::RootRelation::AdoptedDescendant});

    check({"absolute location", "/dir/t1/sub", "dir/t1", "dir/t1/sub/metadata/v2.metadata.json",
        "dir/t1/sub", IcebergPathResolver::RootRelation::AdoptedDescendant});

    /// `location` names the queried path itself, so it contradicts the document's position and
    /// neither source can be trusted over the other.
    check({"location shallower than the document", "/dir/t4", "dir/t4",
        "dir/t4/archive/metadata/v2.metadata.json",
        "dir/t4", IcebergPathResolver::RootRelation::Unknown});

    check({"document at the queried path", "/dir/t3/sub", "dir/t3", "dir/t3/metadata/v2.metadata.json",
        "dir/t3", IcebergPathResolver::RootRelation::Same});

    check({"no location", "", "dir/t1", "dir/t1/sub/metadata/v2.metadata.json",
        "dir/t1", IcebergPathResolver::RootRelation::Unknown});
}

TEST(IcebergDeriveTableRoot, EmptyTailIsNotARoot)
{
    check({"storage root", "", "", "//metadata/v2.metadata.json",
        "", IcebergPathResolver::RootRelation::Unknown});
}

Field castValueOfSetting(const String & name, const Field & value)
{
    if constexpr (std::is_same_v<SettingsT, Settings>)
        return settingCastValueUtil(name, value);
    else
        return SettingsT::castValueUtil(name, value);
}

bool SettingsConstraints::isAnyTierRestricted() const
{
    return access_control
        && (!access_control->getAllowExperimentalTierSettings() || !access_control->getAllowPrivatePreviewTierSettings()
            || !access_control->getAllowBetaTierSettings());
}

std::optional<SettingsConstraints::Checker> SettingsConstraints::getTierChecker(std::string_view setting_name, SettingsTierType tier) const
{
    if (!access_control)
        return {};

    auto refuse = [&](std::string_view tier_name)
    {
        return Checker(
            PreformattedMessage::create(
                "Cannot modify setting '{}'. Changes to {} settings are disabled in the server config ('allow_feature_tier')",
                setting_name,
                tier_name),
            ErrorCodes::READONLY);
    };

    if (tier == SettingsTierType::EXPERIMENTAL && !access_control->getAllowExperimentalTierSettings())
        return refuse("EXPERIMENTAL");
    if (tier == SettingsTierType::PRIVATE_PREVIEW && !access_control->getAllowPrivatePreviewTierSettings())
        return refuse("PRIVATE PREVIEW");
    if (tier == SettingsTierType::BETA && !access_control->getAllowBetaTierSettings())
        return refuse("BETA");
    return {};
}

std::optional<String> getEffectiveKeyValueArgStringValue(const ASTPtr & ast, const ContextPtr & context)
    {
        if (auto value = getKeyValueArgStringValue(ast))
            return value;

        const auto * func = ast->as<const ASTFunction>();
        if (!func || func->name != "equals")
            return std::nullopt;

        const auto * list = func->arguments ? func->arguments->as<const ASTExpressionList>() : nullptr;
        if (!list || list->children.size() != 2)
            return std::nullopt;

        if (!context)
            throw Exception(
                ErrorCodes::BAD_ARGUMENTS, "Cannot remove credentials from the base backup locator with a non-literal argument value");

        ASTPtr evaluated = evaluateConstantExpressionOrIdentifierAsLiteral(list->children[1], context);
        const auto * evaluated_literal = evaluated->as<const ASTLiteral>();
        if (!evaluated_literal || evaluated_literal->value.getType() != Field::Types::Which::String)
            throw Exception(ErrorCodes::BAD_ARGUMENTS, "The base backup locator argument value must be a constant string expression");
        return evaluated_literal->value.safeGet<String>();
    }

ASTPtr withoutSecretExtraCredentials(const ASTPtr & function_arg, const ContextPtr & context)
    {
        const auto * func = function_arg->as<const ASTFunction>();
        /// Only `extra_credentials` is consumed by `registerBackupEngineS3`; don't guess at anything else.
        if (!func || func->name != "extra_credentials" || !func->arguments)
            return nullptr;

        ASTs kept;
        for (const auto & child : func->arguments->children)
        {
            auto key = getEffectiveKeyValueArgName(child, context);
            if (!key || !FunctionSecretArgumentsFinder::isNonSecretExtraCredentialsKey(*key))
                continue;
            /// The value is only classified, not rewritten: an expression the open path resolves stays as
            /// it was written, so a locator that loses nothing serializes byte for byte.
            if (!getEffectiveKeyValueArgStringValue(child, context))
                continue;
            kept.push_back(child);
        }

        if (kept.empty())
            return nullptr;

        /// Keep the original node when nothing is dropped, so the locator serializes byte for byte.
        if (kept.size() == func->arguments->children.size())
            return function_arg;

        /// The AST may be shared with the query, so it must not be modified in place.
        auto res = make_intrusive<ASTFunction>();
        res->name = func->name;
        res->arguments = make_intrusive<ASTExpressionList>();
        res->arguments->children = std::move(kept);
        res->children.push_back(res->arguments);
        return res;
    }

bool hasRoleToAssume(const ASTPtr & function_arg, const ContextPtr & context)
    {
        const auto * func = function_arg ? function_arg->as<const ASTFunction>() : nullptr;
        if (!func || func->name != "extra_credentials" || !func->arguments)
            return false;

        for (const auto & child : func->arguments->children)
        {
            auto key = context ? getEffectiveKeyValueArgName(child, context) : getKeyValueArgName(child);
            if (!key || *key != "role_arn")
                continue;
            auto value = context ? getEffectiveKeyValueArgStringValue(child, context) : getKeyValueArgStringValue(child);
            return value && !value->empty();
        }

        return false;
    }

[[noreturn]] void checkExpressionRoleArnValueWithContext()
    {
        tryRegisterFunctions();
        const auto & context = getContext().context;
        /// `collectCredentials` resolves the value when opening the locator, so one written as an
        /// expression names a role just as well and has to survive into the metadata.
        auto info = BackupInfo::fromString(
            "S3('https://s3.example.com/bucket/backup', extra_credentials(role_arn = concat('arn::', 'role')))");

        String str = info.withoutS3Credentials(context).toString();
        requireContains(str, "extra_credentials");
        requireContains(str, "concat('arn::', 'role')");
        std::_Exit(0);
    }

[[noreturn]] void checkCopyS3CredentialsResolvesExtraCredentialsWithContext()
    {
        tryRegisterFunctions();
        const auto & context = getContext().context;

        /// `collectCredentials` resolves both sides of each assignment when the locator is opened, so what
        /// a clause authenticates as is decided by what it loads, not by how it is written. A resolved
        /// `role_arn` is lent whatever its spelling; a clause that resolves to no role is not.
        const auto dest = BackupInfo::fromString("S3('https://s3.example.com/base')");

        for (const auto * lendable :
             {"S3('https://s3.example.com/backup', extra_credentials(concat('role_', 'arn') = 'arn::role'))",
              "S3('https://s3.example.com/backup', extra_credentials(role_arn = concat('arn::', 'role')))"})
        {
            auto source = BackupInfo::fromString(lendable);
            if (!source.canCopyS3CredentialsTo(dest, context))
            {
                std::cerr << "Expected to be able to lend the credentials of " << lendable << '\n';
                std::_Exit(1);
            }
        }

        for (const auto * barren :
             {"S3('https://s3.example.com/backup', extra_credentials(concat('external_', 'id') = 'EXTERNALID'))",
              "S3('https://s3.example.com/backup', extra_credentials(role_arn = concat('', '')))"})
        {
            auto source = BackupInfo::fromString(barren);
            if (source.canCopyS3CredentialsTo(dest, context))
            {
                std::cerr << "Expected " << barren << " to name no role to assume\n";
                std::_Exit(1);
            }
        }

        std::_Exit(0);
    }

TEST(BackupInfoDeathTest, WithoutS3CredentialsKeepsExpressionRoleArnValue)
{
    ::testing::FLAGS_gtest_death_test_style = "threadsafe";
    EXPECT_EXIT(checkExpressionRoleArnValueWithContext(), ::testing::ExitedWithCode(0), ".*");
}

TEST(BackupInfoDeathTest, CopyS3CredentialsToResolvesExtraCredentials)
{
    ::testing::FLAGS_gtest_death_test_style = "threadsafe";
    EXPECT_EXIT(checkCopyS3CredentialsResolvesExtraCredentialsWithContext(), ::testing::ExitedWithCode(0), ".*");
}

TEST(BackupInfo, WithoutS3CredentialsStripsExternalIdFromExtraCredentials)
{
    auto info = BackupInfo::fromString(
        "S3('https://s3.example.com/bucket/backup', extra_credentials(role_arn = 'ROLEARN', external_id = 'EXTERNALID'))");

    String str = info.withoutS3Credentials().toString();
    EXPECT_NE(str.find("ROLEARN"), String::npos) << str;
    EXPECT_EQ(str.find("EXTERNALID"), String::npos) << str;
}

TEST(BackupInfo, WithoutS3CredentialsStripsExtraCredentialsWithOnlySecrets)
{
    auto info
        = BackupInfo::fromString("S3('https://s3.example.com/bucket/backup', extra_credentials(external_id = 'EXTERNALID'))");

    EXPECT_EQ(info.withoutS3Credentials().toString(), "S3('https://s3.example.com/bucket/backup')");
}

TEST(BackupInfo, WithoutS3CredentialsRejectsNonLiteralExtraCredentialsValueWithoutContext)
{
    /// A value that is no literal has to be resolved to be classified, and a nested secret must not be
    /// persisted on the guess that it is one of the identifiers. Without a context it fails closed, the
    /// same way a key that is no literal does.
    auto info = BackupInfo::fromString(
        "S3('https://s3.example.com/bucket/backup', extra_credentials(role_arn = headers('Authorization' = 'SECRET')))");

    EXPECT_THROW(info.withoutS3Credentials(), Exception);
}

TEST(BackupInfo, WithoutS3CredentialsStripsUnrecognizedTrailingFunction)
{
    /// Only `extra_credentials` is consumed by the `S3` backup engine; anything else is dropped.
    auto info
        = BackupInfo::fromString("S3('https://s3.example.com/bucket/backup', headers('Authorization' = 'SECRET'))");

    checkCanCopyS3CredentialsInvariant(
        "S3('https://s3.example.com/backup', extra_credentials(role_arn = 'ROLEARN'))", "S3('https://s3.example.com/base')");
    checkCanCopyS3CredentialsInvariant(
        "S3('https://s3.example.com/backup', extra_credentials(role_arn = 'ROLEARN'))", "S3(collection)");
    checkCanCopyS3CredentialsInvariant(
        "S3('https://s3.example.com/backup', headers('Authorization' = 'SECRET'))", "S3('https://s3.example.com/base')");
    checkCanCopyS3CredentialsInvariant(
        "S3('https://s3.example.com/backup', extra_credentials(role_session_name = 'SESSION'))",
        "S3('https://s3.example.com/base')");
}

TEST(BackupInfo, CopyS3CredentialsToRejectsClauseNamingNoRole)
{
    /// Only a non-empty `role_arn` makes `getCredentialsProvider` assume a role, so a clause carrying
    /// just the session name or the external id lends no identity. Copying it would leave the base
    /// backup unauthenticated instead of failing where the credentials are asked for.
    for (const auto * source_str :
         {"S3('https://s3.example.com/backup', extra_credentials(role_session_name = 'SESSION'))",
          "S3('https://s3.example.com/backup', extra_credentials(external_id = 'EXTERNALID'))",
          "S3('https://s3.example.com/backup', extra_credentials(role_arn = ''))"})
    {
        auto source = BackupInfo::fromString(source_str);
        auto dest = BackupInfo::fromString("S3('https://s3.example.com/base')");

        EXPECT_FALSE(source.canCopyS3CredentialsTo(dest)) << source_str;
        expectExceptionCode([&] { source.copyS3CredentialsTo(dest); }, ErrorCodes::BAD_ARGUMENTS);
    }
}

TEST(BackupInfo, CopyS3CredentialsToKeepsDestinationCredentialsWhenSourceNamesNoRole)
{
    /// The rejection has to come before the destination is cleared: a source that cannot lend anything
    /// must not cost the destination the credentials it was given.
    auto source = BackupInfo::fromString("S3('https://s3.example.com/backup', extra_credentials(role_session_name = 'SESSION'))");
    auto dest = BackupInfo::fromString("S3('https://s3.example.com/base', 'OTHERKEYID', 'OTHERKEYSECRET')");
    const String dest_before = dest.toString();

    expectExceptionCode([&] { source.copyS3CredentialsTo(dest); }, ErrorCodes::BAD_ARGUMENTS);

    EXPECT_EQ(dest.toString(), dest_before);
}

TEST(BackupInfo, CopyS3CredentialsToCarriesExtraCredentials)
{
    auto source = BackupInfo::fromString(
        "S3('https://s3.example.com/backup', extra_credentials(role_arn = 'ROLEARN', external_id = 'EXTERNALID'))");
    auto dest = BackupInfo::fromString("S3('https://s3.example.com/base')");

    source.copyS3CredentialsTo(dest);

    EXPECT_EQ(
        dest.toString(),
        "S3('https://s3.example.com/base', extra_credentials(equals(role_arn, 'ROLEARN'), equals(external_id, 'EXTERNALID')))");
}

TEST(BackupInfo, CopyS3CredentialsToKeepsDestinationRoleBesideTheCopiedKeyPair)
{
    /// The setting repairs a base backup locator that cannot authenticate on its own, so a role the
    /// destination names has to survive: it is opened as the copied key pair assuming that role, the
    /// composition `getCredentialsProvider` builds, and what a key pair copied onto it always did.
    auto source = BackupInfo::fromString("S3('https://s3.example.com/backup', 'KEYID', 'KEYSECRET')");
    auto dest = BackupInfo::fromString("S3('https://s3.example.com/base', extra_credentials(role_arn = 'OTHERROLE'))");

    source.copyS3CredentialsTo(dest);

    EXPECT_EQ(
        dest.toString(),
        "S3('https://s3.example.com/base', 'KEYID', 'KEYSECRET', extra_credentials(equals(role_arn, 'OTHERROLE')))");
}

TEST(BackupInfo, CopyS3CredentialsToOverwritesTheDestinationRoleWithTheCopiedOne)
{
    /// Same kind, so the source wins: the destination cannot assume two roles.
    auto source = BackupInfo::fromString("S3('https://s3.example.com/backup', extra_credentials(role_arn = 'ROLEARN'))");
    auto dest = BackupInfo::fromString("S3('https://s3.example.com/base', extra_credentials(role_arn = 'OTHERROLE'))");

    source.copyS3CredentialsTo(dest);

    EXPECT_EQ(dest.toString(), "S3('https://s3.example.com/base', extra_credentials(equals(role_arn, 'ROLEARN')))");
}

TEST(BackupInfo, CopyS3CredentialsToDropsADestinationKeyPairItCannotReplay)
{
    /// A key pair the source has none of to lend cannot come back: `withoutS3Credentials` strips it from
    /// the metadata and re-copying restores only the role. Keeping it would open the base backup here and
    /// leave it unopenable on restore, so it goes and the locator stays reconstructable.
    auto source = BackupInfo::fromString("S3('https://s3.example.com/backup', extra_credentials(role_arn = 'ROLEARN'))");
    auto dest = BackupInfo::fromString("S3('https://s3.example.com/base', 'OTHERKEYID', 'OTHERKEYSECRET')");

    source.copyS3CredentialsTo(dest);

    EXPECT_EQ(dest.toString(), "S3('https://s3.example.com/base', extra_credentials(equals(role_arn, 'ROLEARN')))");
}

TEST(BackupInfo, CopyS3CredentialsToRoundTripsTheMergedLocatorThroughRedaction)
{
    /// What `BackupImpl::writeBackupMetadata` compares before it may replace the credentials with the
    /// `<base_backup_copy_s3_credentials_from_backup>` marker: strip the copied locator, copy onto the
    /// stripped form again, and the two must agree. A destination role survives redaction, so the merge
    /// this performs has to survive the round trip too.
    auto source = BackupInfo::fromString("S3('https://s3.example.com/backup', 'KEYID', 'KEYSECRET')");
    auto dest = BackupInfo::fromString("S3('https://s3.example.com/base', extra_credentials(role_arn = 'OTHERROLE'))");

    source.copyS3CredentialsTo(dest);

    auto stripped = dest.withoutS3Credentials();
    EXPECT_NE(stripped.toString(), dest.toString());

    auto replayed = stripped;
    source.copyS3CredentialsTo(replayed);
    EXPECT_EQ(replayed.toString(), dest.toString());
}

TEST(BackupInfo, CopyS3CredentialsToDropsADestinationClauseNamingNoRole)
{
    /// `external_id` without a `role_arn` assumes nothing, so it is not authentication to preserve.
    /// Keeping it would also leave the locator unreconstructable from the stripped form, costing the
    /// `<base_backup_copy_s3_credentials_from_backup>` marker for no gain.
    auto source = BackupInfo::fromString("S3('https://s3.example.com/backup', 'KEYID', 'KEYSECRET')");
    auto dest = BackupInfo::fromString("S3('https://s3.example.com/base', extra_credentials(external_id = 'EXTERNALID'))");

    source.copyS3CredentialsTo(dest);

    EXPECT_EQ(dest.toString(), "S3('https://s3.example.com/base', 'KEYID', 'KEYSECRET')");
}

TEST(BackupInfo, CopyS3CredentialsToLeavesAnEmptyDestinationCarryingOnlyTheCopiedCredentials)
{
    /// The shape every locator written with the `<base_backup_copy_s3_credentials_from_backup>` marker
    /// has, since stripping is what produced it. Nothing is there to keep, so copying reconstructs it
    /// exactly -- which is what `BackupImpl::writeBackupMetadata` compares before emitting the marker.
    auto source = BackupInfo::fromString("S3('https://s3.example.com/backup', 'KEYID', 'KEYSECRET')");
    auto dest = BackupInfo::fromString("S3('https://s3.example.com/base')");

    source.copyS3CredentialsTo(dest);

    EXPECT_EQ(dest.toString(), "S3('https://s3.example.com/base', 'KEYID', 'KEYSECRET')");
}

TEST(BackupInfo, CopyS3CredentialsToRejectsSourceWithoutCredentials)
{
    auto source = BackupInfo::fromString("S3('https://s3.example.com/backup')");
    auto dest = BackupInfo::fromString("S3('https://s3.example.com/base')");

    expectExceptionCode([&] { source.copyS3CredentialsTo(dest); }, ErrorCodes::BAD_ARGUMENTS);

UInt64 clampTemporaryFilesBufferSize(UInt64 buffer_size)
{
    if (buffer_size <= MAX_TEMPORARY_FILES_BUFFER_SIZE)
        return buffer_size;

    LOG_WARNING(
        getLogger("SettingsSanity"),
        "Sanity check: 'temporary_files_buffer_size' value is too high ({}). Reduced to {}",
        buffer_size,
        MAX_TEMPORARY_FILES_BUFFER_SIZE);
    return MAX_TEMPORARY_FILES_BUFFER_SIZE;
}

DECLARE_DEFAULT_CODE(

struct ASIMDMD5Ops
{
    using Vec = uint32x4_t;
    static constexpr size_t lanes = 4;

    static inline Vec add(Vec a, Vec b)
    {
        return vaddq_u32(a, b);
    }
    static inline Vec set1(uint32_t v)
    {
        return vdupq_n_u32(v);
    }
    static inline Vec loadu(const void * p)
    {
        return vreinterpretq_u32_u8(vld1q_u8(reinterpret_cast<const uint8_t *>(p)));
    }
    static inline void storeu(void * p, Vec v)
    {
        vst1q_u8(reinterpret_cast<uint8_t *>(p), vreinterpretq_u8_u32(v));
    }

    template <int N>
    static inline Vec rotl(Vec x)
    {
        return vorrq_u32(vshlq_n_u32(x, N), vshrq_n_u32(x, 32 - N));
    }

    static inline Vec F(Vec b, Vec c, Vec d)
    {
        return veorq_u32(d, vandq_u32(b, veorq_u32(c, d)));
    }
    static inline Vec G(Vec b, Vec c, Vec d)
    {
        return veorq_u32(c, vandq_u32(d, veorq_u32(b, c)));
    }
    static inline Vec H(Vec b, Vec c, Vec d)
    {
        return veorq_u32(b, veorq_u32(c, d));
    }
    static inline Vec I(Vec b, Vec c, Vec d)
    {
        return veorq_u32(c, vorrq_u32(b, vmvnq_u32(d)));
    }

    static inline void gatherAllMessageWords(const uint8_t * const block_ptrs[], Vec msg[16])
    {
        for (size_t word = 0; word < 16; ++word)
        {
            const size_t offset = word * sizeof(uint32_t);
            const uint32_t values[lanes] = {
                unalignedLoadLittleEndian<uint32_t>(block_ptrs[0] + offset),
                unalignedLoadLittleEndian<uint32_t>(block_ptrs[1] + offset),
                unalignedLoadLittleEndian<uint32_t>(block_ptrs[2] + offset),
                unalignedLoadLittleEndian<uint32_t>(block_ptrs[3] + offset),
            };
            msg[word] = loadu(values);
        }
    }
};

) // DECLARE_DEFAULT_CODE

#endif


