  // 7 }
  llvm::SmallVector<MismatchedBracketToken> tokens = {
      MakeToken(0, BracketTokenKind::StatementIntroducer, 1, 1),
      MakeToken(1, BracketTokenKind::OpenCurlyBrace, 1, 1,
                /*is_at_end_of_line=*/true),
      MakeToken(2, BracketTokenKind::StatementIntroducer, 2, 3),
      MakeToken(3, BracketTokenKind::OpenParen, 2, 3),
      MakeToken(4, BracketTokenKind::CloseParen, 2, 3),
      MakeToken(5, BracketTokenKind::OpenCurlyBrace, 2, 3,
                /*is_at_end_of_line=*/true),
      MakeToken(6, BracketTokenKind::StatementIntroducer, 3, 5),
      MakeToken(7, BracketTokenKind::Semi, 3, 5, /*is_at_end_of_line=*/true),
      MakeToken(8, BracketTokenKind::StatementIntroducer, 4, 3),
      MakeToken(9, BracketTokenKind::OpenParen, 4, 3),
      MakeToken(10, BracketTokenKind::CloseParen, 4, 3),
      MakeToken(11, BracketTokenKind::OpenCurlyBrace, 4, 3,
                /*is_at_end_of_line=*/true),
      MakeToken(12, BracketTokenKind::StatementIntroducer, 5, 5),
      MakeToken(13, BracketTokenKind::Semi, 5, 5, /*is_at_end_of_line=*/true),
      MakeToken(14, BracketTokenKind::CloseCurlyBrace, 6, 3,
                /*is_at_end_of_line=*/true),
      MakeToken(15, BracketTokenKind::CloseCurlyBrace, 7, 1,
                /*is_at_end_of_line=*/true),
  };

  auto corrections = FixMismatchedBrackets(tokens);
  ASSERT_FALSE(corrections.empty());
  EXPECT_EQ(corrections[0].fix_action, BracketFixAction::InsertBefore);
  EXPECT_EQ(corrections[0].fix_token_index.index,
            8);  // Should insert before token 8 (fn Check3).
}

TEST_F(MismatchedBracketsTest, PathologicalInputRecoversSafely) {
  // Alternating `(` and `}`, so no bracket can ever match. The small case runs
  // through the search; the large one exceeds the region size limit and takes
  // the naive fallback. Either way recovery has to account for every bracket
  // exactly once, and must not invent an out-of-range fix.
  for (int32_t num_tokens : {200, 2000}) {
    llvm::SmallVector<MismatchedBracketToken> tokens;
    for (int32_t i = 0; i < num_tokens; ++i) {
      tokens.push_back(MakeToken(i,
                                 (i % 2 == 0)
                                     ? BracketTokenKind::OpenParen
                                     : BracketTokenKind::CloseCurlyBrace,
                                 i + 1, (i % 4) * 2));
    }

    auto corrections = FixMismatchedBrackets(tokens);
    EXPECT_THAT(corrections, SizeIs(num_tokens));
    llvm::SmallVector<bool> diagnosed(num_tokens, false);
    for (const auto& correction : corrections) {
      ASSERT_GE(correction.diagnostic_token_index.index, 0);
      ASSERT_LT(correction.diagnostic_token_index.index, num_tokens);
      ASSERT_GE(correction.fix_token_index.index, 0);
      ASSERT_LT(correction.fix_token_index.index, num_tokens);
      EXPECT_FALSE(diagnosed[correction.diagnostic_token_index.index]);
      diagnosed[correction.diagnostic_token_index.index] = true;
    }
  }
}

TEST_F(MismatchedBracketsTest, FixesMissingOpenParenAfterIf) {
  // 1  if x) {
  // 2    y;
  // 3  }
  llvm::SmallVector<MismatchedBracketToken> tokens = {
      MakeToken(0, BracketTokenKind::StatementIntroducer, 1, 1),
      MakeToken(1, BracketTokenKind::Leaf, 1, 1),
      MakeToken(2, BracketTokenKind::CloseParen, 1, 1),
      MakeToken(3, BracketTokenKind::OpenCurlyBrace, 1, 1,
                /*is_at_end_of_line=*/true),
      MakeToken(4, BracketTokenKind::Leaf, 2, 3),
      MakeToken(5, BracketTokenKind::Semi, 2, 3, /*is_at_end_of_line=*/true),
      MakeToken(6, BracketTokenKind::CloseCurlyBrace, 3, 1,
                /*is_at_end_of_line=*/true),
  };
  // `if` must be directly followed by `(`.
  tokens[0].is_paren_keyword = true;
  tokens[1].has_leading_space = true;

  auto corrections = FixMismatchedBrackets(tokens);
  ASSERT_THAT(corrections, SizeIs(1));
  EXPECT_EQ(corrections[0].fix_action, BracketFixAction::InsertBefore);
  EXPECT_EQ(corrections[0].fix_token_kind, TokenKind::OpenParen);
  EXPECT_EQ(corrections[0].fix_token_index.index, 1);
  EXPECT_FALSE(corrections[0].is_tied);
}

TEST_F(MismatchedBracketsTest, FixesMissingCloseParenBeforeSemi) {
  // 1  fn F() {
  // 2    G(x;
  // 3  }
  llvm::SmallVector<MismatchedBracketToken> tokens = {
      MakeToken(0, BracketTokenKind::StatementIntroducer, 1, 1),
      MakeToken(1, BracketTokenKind::OpenParen, 1, 1),
      MakeToken(2, BracketTokenKind::CloseParen, 1, 1),
      MakeToken(3, BracketTokenKind::OpenCurlyBrace, 1, 1,
                /*is_at_end_of_line=*/true),
      MakeToken(4, BracketTokenKind::Leaf, 2, 3),
      MakeToken(5, BracketTokenKind::OpenParen, 2, 3),
      MakeToken(6, BracketTokenKind::Leaf, 2, 3),
      MakeToken(7, BracketTokenKind::Semi, 2, 3, /*is_at_end_of_line=*/true),
      MakeToken(8, BracketTokenKind::CloseCurlyBrace, 3, 1,
                /*is_at_end_of_line=*/true),
  };
  // A `;` can't appear inside parens, so the `)` belongs directly before it.
  auto corrections = FixMismatchedBrackets(tokens);
  ASSERT_THAT(corrections, SizeIs(1));
  EXPECT_EQ(corrections[0].fix_action, BracketFixAction::InsertBefore);
  EXPECT_EQ(corrections[0].fix_token_kind, TokenKind::CloseParen);
  EXPECT_EQ(corrections[0].fix_token_index.index, 7);
  EXPECT_FALSE(corrections[0].is_tied);
}

auto Context::File::sem_ir_index() const -> const SemIRIndex* {
  if (!sem_ir_index_) {
    const auto* sem_ir = this->sem_ir();
    if (!sem_ir) {
      return nullptr;
    }
    sem_ir_index_.emplace(*sem_ir, tree_and_subtrees());
  }
  return &*sem_ir_index_;
}

static auto StringifyTypeOfInst(const SemIR::File& sem_ir,
                                SemIR::InstId inst_id) -> std::string {
  auto type_id = sem_ir.insts().Get(inst_id).type_id();
  if (!type_id.has_value()) {
    return "";
  }
  return SemIR::StringifyConstantInst(sem_ir,
                                      sem_ir.types().GetTypeInstId(type_id));
}

static auto FindInstAtPositionOrFail(
    Context& context, const clang::clangd::TextDocumentPositionParams& params,
    llvm::function_ref<auto(llvm::Expected<ResponseType>)->void> on_done)
    -> PositionInfo {
  auto* file = context.LookupFile(params.textDocument.uri.file());
  if (!file) {
    on_done(llvm::make_error<clang::clangd::LSPError>(
        llvm::formatv("Unknown textDocument `{0}`",
                      params.textDocument.uri.file()),
        clang::clangd::ErrorCode::InvalidParams));
    return {};
  }

  auto info = FindPositionInfo(*file, params.position);
  if (!info.has_inst()) {
    on_done(ResponseType());
  }

  return info;
}

auto HandleHover(
    Context& context, const clang::clangd::TextDocumentPositionParams& params,
    llvm::function_ref<auto(llvm::Expected<clang::clangd::Hover>)->void>
        on_done) -> void {
  auto info = FindInstAtPositionOrFail(context, params, on_done);
  if (!info.has_inst()) {
    return;
  }

  const auto& sem_ir = *info.file->sem_ir();
  RawStringOstream text;
  text << "```carbon\n" << info.file->tokens().GetTokenText(info.token);
  if (auto type = StringifyTypeOfInst(sem_ir, info.inst_id); !type.empty()) {
    text << ": " << type;
  }
  text << "\n```";

  on_done(clang::clangd::Hover{
      .contents = {.kind = clang::clangd::MarkupKind::Markdown,
                   .value = text.TakeStr()},
      .range = GetTokenRange(info.file->tokens(), info.token)});
}

static auto HandleGoto(
    Context& context, const clang::clangd::TextDocumentPositionParams& params,
    bool use_type,
    llvm::function_ref<
        auto(llvm::Expected<std::vector<clang::clangd::Location>>)->void>
        on_done) -> void {
  auto info = FindInstAtPositionOrFail(context, params, on_done);
  if (!info.has_inst()) {
    return;
  }

  const auto& sem_ir = *info.file->sem_ir();
  auto target_id = GetReferencedInst(sem_ir, info.inst_id);
  if (use_type) {
    auto type_id = sem_ir.insts().Get(target_id).type_id();
    if (!type_id.has_value()) {
      on_done(std::vector<clang::clangd::Location>());
      return;
    }
    target_id = sem_ir.types().GetTypeInstId(type_id);
  }

  std::vector<clang::clangd::Location> locations;
  if (auto location = GetInstLocation(*info.file, target_id)) {
    locations.push_back(*location);
  }
  on_done(std::move(locations));
}

auto HandleDefinition(
    Context& context, const clang::clangd::TextDocumentPositionParams& params,
    llvm::function_ref<
        auto(llvm::Expected<std::vector<clang::clangd::Location>>)->void>
        on_done) -> void {
  HandleGoto(context, params, /*use_type=*/false, on_done);
}

auto HandleTypeDefinition(
    Context& context, const clang::clangd::TextDocumentPositionParams& params,
    llvm::function_ref<
        auto(llvm::Expected<std::vector<clang::clangd::Location>>)->void>
        on_done) -> void {
  HandleGoto(context, params, /*use_type=*/true, on_done);
}

auto HandleReferences(
    Context& context, const clang::clangd::ReferenceParams& params,
    llvm::function_ref<
        auto(llvm::Expected<std::vector<clang::clangd::Location>>)->void>
        on_done) -> void {
  auto info = FindInstAtPositionOrFail(context, params, on_done);
  if (!info.has_inst()) {
    return;
  }

  const auto& sem_ir = *info.file->sem_ir();
  auto target_token =
      GetInstNameToken(*info.file, GetReferencedInst(sem_ir, info.inst_id));
  if (!target_token.has_value()) {
    on_done(std::vector<clang::clangd::Location>());
    return;
  }

  // This is the one request the token index can't serve: it needs every
  // instruction referring to an entity, which is the opposite direction from
  // the index. A scan is inherent, and cheap next to the compile that produced
  // the IR.
  std::vector<clang::clangd::Location> locations;
  if (params.context.includeDeclaration) {
    locations.push_back(
        {.uri = info.file->uri(),
         .range = GetTokenRange(info.file->tokens(), target_token)});
  }
  for (auto [inst_id, inst] : sem_ir.insts().enumerate()) {
    auto name_ref = inst.TryAs<SemIR::NameRef>();
    if (!name_ref ||
        GetInstNameToken(*info.file, name_ref->value_id) != target_token) {
      continue;
    }
    if (auto location = GetInstLocation(*info.file, inst_id)) {
      locations.push_back(*location);
    }
  }
  on_done(std::move(locations));
}

auto GetTokenRange(const Lex::TokenizedBuffer& tokens, Lex::TokenIndex start,
                   Lex::TokenIndex end) -> clang::clangd::Range {
  auto start_line = tokens.GetLine(start);
  auto start_col = tokens.GetColumnNumber(start);
  auto [end_line, end_col] = tokens.GetEndLoc(end);
  return clang::clangd::Range{
      .start = {.line = start_line.index, .character = start_col - 1},
      .end = {.line = end_line.index, .character = end_col - 1},
  };
}

auto FindToken(const Lex::TokenizedBuffer& tokens,
               const clang::clangd::Position& position) -> Lex::TokenIndex {
  std::pair<int, int> target = {position.line, position.character};

  // Tokens are in source order, so find the first one starting after
  // `position`; only the token before that can contain it. Searching on
  // (line, column) avoids converting the position to a byte offset, which would
  // mean rescanning the text for line boundaries.
  //
  // `tokens()` excludes the recovery tokens added after lexing finished, which
  // matters here: those are appended rather than inserted in source order, so
  // including them would break the ordering this search relies on.
  auto range = tokens.tokens();
  auto after = llvm::partition_point(range, [&](Lex::TokenIndex token) {
    return GetTokenStart(tokens, token) <= target;
  });
  if (after == range.begin()) {
    return Lex::TokenIndex::None;
  }

  // The position is in that token only if it's also before the token's end;
  // otherwise it falls in whitespace or a comment.
  auto token = *std::prev(after);
  auto [end_line, end_col] = tokens.GetEndLoc(token);
  if (target < std::pair<int, int>(end_line.index, end_col - 1)) {
    return token;
  }
  return Lex::TokenIndex::None;
}

auto FindPositionInfo(const Context::File& file,
                      const clang::clangd::Position& position) -> PositionInfo {
  const auto* sem_ir = file.sem_ir();
  const auto* index = file.sem_ir_index();
  if (!sem_ir || !index) {
    return {};
  }

  auto token = FindToken(file.tokens(), position);
  if (!token.has_value()) {
    return {};
  }

  PositionInfo info = {.file = &file, .token = token};
  auto insts = index->InstsForToken(token);
  for (auto inst_id : insts) {
    // Prefer a name reference: a token such as the name in `fn F()` also has
    // instructions for the declaration itself, but a request at a name is about
    // the name.
    if (sem_ir->insts().Is<SemIR::NameRef>(inst_id)) {
      info.inst_id = inst_id;
      return info;
    }
  }
  if (!insts.empty()) {
    info.inst_id = insts.front();
  }
  return info;
}

auto GetReferencedInst(const SemIR::File& sem_ir, SemIR::InstId inst_id)
    -> SemIR::InstId {
  if (auto name_ref = sem_ir.insts().TryGetAs<SemIR::NameRef>(inst_id)) {
    return name_ref->value_id;
  }
  return inst_id;
}

auto GetInstNameToken(const Context::File& file, SemIR::InstId inst_id)
    -> Lex::TokenIndex {
  const auto* sem_ir = file.sem_ir();
  if (!sem_ir || !inst_id.has_value()) {
    return Lex::TokenIndex::None;
  }
  auto loc_id = sem_ir->insts().GetCanonicalLocId(inst_id);
  if (loc_id.kind() != SemIR::LocId::Kind::NodeId) {
    // Imported from another file, which we can't yet name a location in.
    return Lex::TokenIndex::None;
  }
  auto node_id = loc_id.node_id();
  if (!node_id.has_value()) {
    return Lex::TokenIndex::None;
  }
  return GetNameToken(file.tree_and_subtrees(), node_id);
}

auto GetInstLocation(const Context::File& file, SemIR::InstId inst_id)
    -> std::optional<clang::clangd::Location> {
  auto token = GetInstNameToken(file, inst_id);
  if (!token.has_value()) {
    return std::nullopt;
  }
  return clang::clangd::Location{.uri = file.uri(),
                                 .range = GetTokenRange(file.tokens(), token)};
}

auto GetNameToken(const Parse::TreeAndSubtrees& tree_and_subtrees,
                  Parse::NodeId node_id) -> Lex::TokenIndex {
  const auto& tree = tree_and_subtrees.tree();
  const auto& tokens = tree.tokens();
  for (auto child : tree_and_subtrees.children(node_id)) {
    switch (tree.node_kind(child)) {
      case Parse::NodeKind::IdentifierNameMaybeBeforeSignature:
      case Parse::NodeKind::IdentifierNameNotBeforeSignature: {
        auto token = tree.node_token(child);
        if (tokens.GetKind(token) == Lex::TokenKind::Identifier) {
          return token;
        }
        break;
      }
      default:
        break;
    }
  }
  return tree.node_token(node_id);
}

static auto GetTokenForInst(const SemIR::File& sem_ir,
                            const Parse::TreeAndSubtrees& tree_and_subtrees,
                            SemIR::InstId inst_id) -> Lex::TokenIndex {
  auto loc_id = sem_ir.insts().GetCanonicalLocId(inst_id);
  if (loc_id.kind() != SemIR::LocId::Kind::NodeId) {
    return Lex::TokenIndex::None;
  }
  auto node_id = loc_id.node_id();
  if (!node_id.has_value()) {
    return Lex::TokenIndex::None;
  }
  return GetNameToken(tree_and_subtrees, node_id);
}

SemIRIndex::SemIRIndex(const SemIR::File& sem_ir,
                       const Parse::TreeAndSubtrees& tree_and_subtrees) {
  const auto& tokens = tree_and_subtrees.tree().tokens();
  // Count the instructions per token, leaving a leading zero so that the counts
  // can be turned into start offsets in place.
  token_starts_.assign(tokens.size() + 1, 0);
  int32_t total = 0;
  for (auto [inst_id, inst] : sem_ir.insts().enumerate()) {
    auto token = GetTokenForInst(sem_ir, tree_and_subtrees, inst_id);
    if (!token.has_value()) {
      continue;
    }
    ++token_starts_[token.index + 1];
    ++total;
  }

  // Turn the counts into start offsets.
  for (size_t i = 1; i < token_starts_.size(); ++i) {
    token_starts_[i] += token_starts_[i - 1];
  }
  CARBON_CHECK(token_starts_.back() == total);

  // Fill each token's group. `next` tracks the next free slot per token, and
  // ends up equal to the following token's start, so the offsets stay valid.
  insts_.resize(total, SemIR::InstId::None);
  llvm::SmallVector<int32_t> next(token_starts_.begin(), token_starts_.end());
  for (auto [inst_id, inst] : sem_ir.insts().enumerate()) {
    auto token = GetTokenForInst(sem_ir, tree_and_subtrees, inst_id);
    if (!token.has_value()) {
      continue;
    }
    insts_[next[token.index]++] = inst_id;
  }
}

auto SemIRIndex::InstsForToken(Lex::TokenIndex token) const
    -> llvm::ArrayRef<SemIR::InstId> {
  if (!token.has_value()) {
    return {};
  }
  CARBON_CHECK(static_cast<size_t>(token.index) + 1 < token_starts_.size(),
               "Token {0} is not from the indexed file", token.index);
  int32_t start = token_starts_[token.index];
  int32_t end = token_starts_[token.index + 1];
  return llvm::ArrayRef(insts_).slice(start, end - start);
}

TEST(PrintableTest, Printing) {
  RawStringOstream raw_out;
  raw_out << Point(1, 2) << " " << Label("label");
  EXPECT_EQ(raw_out.TakeStr(), "(1, 2) label");

  std::ostringstream standard_out;
  standard_out << Point(1, 2) << " " << Label("label");
  EXPECT_EQ(standard_out.str(), "(1, 2) label");

  EXPECT_EQ(PrintToString(Point(1, 2)), "(1, 2)");
}

TEST(PrintableTest, DefaultedEquality) {
  EXPECT_EQ(Point(1, 2), Point(1, 2));
  EXPECT_NE(Point(1, 2), Point(1, 3));
  EXPECT_NE(Point(1, 2), Point(2, 2));

  static_assert(Point(1, 2) == Point(1, 2));
  static_assert(Point(1, 2) != Point(1, 3));

  // The base class comparisons don't make defaulted comparisons throwing.
  Point point(1, 2);
  static_assert(noexcept(point == point));
}

TEST(PrintableTest, DefaultedOrdering) {
  // Ordering is lexicographic in declaration order, with the empty base class
  // contributing nothing.
  EXPECT_LT(Point(1, 2), Point(1, 3));
  EXPECT_LT(Point(1, 9), Point(2, 0));
  EXPECT_LE(Point(1, 2), Point(1, 2));
  EXPECT_GT(Point(2, 0), Point(1, 9));
  EXPECT_GE(Point(1, 2), Point(1, 2));

  EXPECT_EQ(Point(1, 2) <=> Point(1, 3), std::strong_ordering::less);
  EXPECT_EQ(Point(1, 2) <=> Point(1, 2), std::strong_ordering::equal);
  EXPECT_EQ(Point(1, 3) <=> Point(1, 2), std::strong_ordering::greater);

  static_assert(std::totally_ordered<Point>);
  static_assert(std::same_as<std::compare_three_way_result_t<Point>,
                             std::strong_ordering>);
  static_assert(Point(1, 2) < Point(1, 3));

  Point point(1, 2);
  static_assert(noexcept(point <=> point));
}

TEST(PrintableTest, DefaultedFriendComparison) {
  EXPECT_EQ(Label("a"), Label("a"));
  EXPECT_NE(Label("a"), Label("b"));
  EXPECT_LT(Label("a"), Label("b"));
  EXPECT_EQ(Label("a") <=> Label("b"), std::strong_ordering::less);

  static_assert(std::totally_ordered<Label>);
}

TEST(PrintableTest, DefaultedEqualityWithoutOrdering) {
  EXPECT_EQ(Id(1), Id(1));
  EXPECT_NE(Id(1), Id(2));

  static_assert(std::equality_comparable<Id>);
  static_assert(!std::totally_ordered<Id>);
  static_assert(!std::three_way_comparable<Id>);
}

TEST(PrintableTest, DefaultedComparisonCategories) {
  static_assert(std::same_as<std::compare_three_way_result_t<Measure>,
                             std::partial_ordering>);
  static_assert(std::same_as<std::compare_three_way_result_t<Version>,
                             std::weak_ordering>);

  EXPECT_LT(Measure(1.0), Measure(2.0));
  EXPECT_EQ(Measure(1.0) <=> Measure(2.0), std::partial_ordering::less);

  // The base class comparing equal must not make unordered values ordered.
  Measure nan(std::numeric_limits<double>::quiet_NaN());
  EXPECT_EQ(nan <=> Measure(1.0), std::partial_ordering::unordered);
  EXPECT_NE(nan, nan);

  EXPECT_LT(Version(1, 0), Version(1, 1));
  EXPECT_EQ(Version(1, 0) <=> Version(1, 1), std::weak_ordering::less);
}

TEST(PrintableTest, NoComparisonWithoutDefaulting) {
  // Inheriting from `Printable` must not by itself make a type comparable, and
  // in particular must not make distinct values compare equal.
  static_assert(!std::equality_comparable<Opaque>);
  static_assert(!std::totally_ordered<Opaque>);
  static_assert(!std::three_way_comparable<Opaque>);

  EXPECT_EQ(PrintToString(Opaque(1)), "1");
}

TEST(PrintableTest, NoComparisonBetweenBaseAndChild) {
  // The base class comparisons are viable only between two base class
  // subobjects, and so don't apply to comparing a child with one, whether or
  // not the child provides comparisons of its own.
  static_assert(Comparable<Printable<Opaque>, Printable<Opaque>>);
  static_assert(!Comparable<Printable<Opaque>, Opaque>);
  static_assert(!Comparable<Opaque, Printable<Opaque>>);
  static_assert(!Comparable<Printable<Label>, Label>);
  static_assert(!Comparable<Label, Printable<Label>>);
}

TEST(PrintableTest, ComparisonThroughConversion) {
  // The base class comparisons must not displace comparisons that a child
  // provides through a conversion.
  EXPECT_TRUE(Level(Level::Low) == Level(Level::Low));
  EXPECT_FALSE(Level(Level::Low) == Level(Level::High));
  EXPECT_TRUE(Level(Level::Low) < Level(Level::High));
  EXPECT_TRUE(Level(Level::High) == Level::High);
}

TEST(PrintableTest, ComparisonsUsableGenerically) {
  llvm::SmallVector<Point> points = {Point(2, 1), Point(1, 2), Point(1, 1)};
  llvm::sort(points);
  EXPECT_THAT(points, ElementsAre(Point(1, 1), Point(1, 2), Point(2, 1)));

  EXPECT_EQ(llvm::find(points, Point(1, 2)), points.begin() + 1);
}

TEST(PrintableTest, EmptyBaseClass) {
  // The comparison support must not add any state to children.
  static_assert(sizeof(Point) == 2 * sizeof(int));
  static_assert(sizeof(Id) == sizeof(int));
  static_assert(std::is_empty_v<Printable<Point>>);
}

static auto NegotiatePositionEncoding(
    const clang::clangd::ClientCapabilities& capabilities)
    -> clang::clangd::OffsetEncoding {
  if (capabilities.PositionEncodings &&
      llvm::is_contained(*capabilities.PositionEncodings,
                         clang::clangd::OffsetEncoding::UTF8)) {
    return clang::clangd::OffsetEncoding::UTF8;
  }
  return clang::clangd::OffsetEncoding::UTF16;
}

auto HandleInitialized(Context& /*context*/,
                       const clang::clangd::NoParams& /*params*/) -> void {
  // Nothing to do, but every client sends this, so we handle it rather than
  // warning about an unsupported notification.
  // TODO: This is when we would use `client/registerCapability` for any
  // capabilities we want to register dynamically.
}

auto HandleDidSaveTextDocument(
    Context& /*context*/,
    const clang::clangd::DidSaveTextDocumentParams& /*params*/) -> void {
  // Saving doesn't change the content we're tracking: we always use the text
  // provided by the client, which is already up-to-date from `didChange`. We
  // handle this rather than warning about an unsupported notification.
  // TODO: Other open files that import this one may now be stale, because they
  // read it from disk rather than from the client. Re-check them here, or
  // handle `workspace/didChangeWatchedFiles` instead.
}

static auto GetCommentCategory(llvm::StringRef source, int32_t comment_start)
    -> CommentCategory {
  if (comment_start + 2 >= static_cast<int32_t>(source.size()) ||
      IsSpace(source[comment_start + 2])) {
    return CommentCategory::Ordinary;
  }
  if (source[comment_start + 2] == '@') {
    return CommentCategory::Directive;
  }
  return CommentCategory::Invalid;
}

TEST_F(LexerTest, DirectiveComments) {
  // A `//@...` directive line is consumed for its tooling side effects and is
  // also recorded as a comment: the tokens and comments together reconstruct
  // the source, so tooling such as the formatter preserves the directive.
  auto& buffer = compile_helper_.GetTokenizedBuffer(
      "//@include-in-dumps\n"
      "\n"
      "//@dump-sem-ir-begin\n"
      "var x: i32 = 0;\n"
      "//@dump-sem-ir-end\n");
  EXPECT_FALSE(buffer.has_errors());
  EXPECT_TRUE(buffer.has_include_in_dumps());
  EXPECT_TRUE(buffer.has_dump_sem_ir_ranges());
  ASSERT_THAT(buffer.comments_size(), Eq(3));
  EXPECT_THAT(buffer.GetCommentText(CommentIndex(0)),
              Eq("//@include-in-dumps\n"));
  EXPECT_THAT(buffer.GetCommentText(CommentIndex(1)),
              Eq("//@dump-sem-ir-begin\n"));
  EXPECT_THAT(buffer.GetCommentText(CommentIndex(2)),
              Eq("//@dump-sem-ir-end\n"));
  EXPECT_FALSE(buffer.IsTrailingComment(CommentIndex(0)));

  // Adjacent full-line comments coalesce only within a category: a directive
  // next to an ordinary comment is its own record, while adjacent directives
  // share one.
  auto& adjacent = compile_helper_.GetTokenizedBuffer(
      "// Dump this file.\n"
      "//@include-in-dumps\n"
      "//@dump-sem-ir-begin\n"
      "var x: i32 = 0;\n"
      "//@dump-sem-ir-end\n");
  EXPECT_FALSE(adjacent.has_errors());
  EXPECT_TRUE(adjacent.has_include_in_dumps());
  ASSERT_THAT(adjacent.comments_size(), Eq(3));
  EXPECT_THAT(adjacent.GetCommentText(CommentIndex(0)),
              Eq("// Dump this file.\n"));
  EXPECT_THAT(adjacent.GetCommentText(CommentIndex(1)),
              Eq("//@include-in-dumps\n//@dump-sem-ir-begin\n"));
  EXPECT_THAT(adjacent.GetCommentText(CommentIndex(2)),
              Eq("//@dump-sem-ir-end\n"));
}

TEST_F(LexerTest, DirectiveAfterInvalidComment) {
  // An invalid comment line does not absorb a following directive: the
  // directive ends the invalid run, so its side effects are still recognized
  // and it is recorded separately.
  auto& buffer = compile_helper_.GetTokenizedBuffer(
      "//!bad\n"
      "//@dump-sem-ir-begin\n"
      "var x: i32 = 0;\n"
      "//@dump-sem-ir-end\n");
  EXPECT_TRUE(buffer.has_errors());
  EXPECT_TRUE(buffer.has_dump_sem_ir_ranges());
  ASSERT_THAT(buffer.comments_size(), Eq(3));
  EXPECT_THAT(buffer.GetCommentText(CommentIndex(0)), Eq("//!bad\n"));
  EXPECT_THAT(buffer.GetCommentText(CommentIndex(1)),
              Eq("//@dump-sem-ir-begin\n"));
}

TEST_F(LexerTest, InvalidCommentRunsLumpTogether) {
  // A run of invalid comment lines lumps into one comment and one diagnostic,
  // no matter which invalid byte follows each `//`; a valid comment ends the
  // run and starts its own record.
  Testing::MockDiagnosticConsumer consumer;
  EXPECT_CALL(consumer,
              HandleDiagnostic(IsSingleDiagnostic(
                  Diagnostics::Kind::NoWhitespaceAfterCommentIntroducer,
                  Diagnostics::Level::Error, 1, 3, _)));
  auto& buffer = compile_helper_.GetTokenizedBuffer(
      "//!one\n"
      "//?two\n"
      "// valid\n",
      &consumer);
  ASSERT_THAT(buffer.comments_size(), Eq(2));
  EXPECT_THAT(buffer.GetCommentText(CommentIndex(0)), Eq("//!one\n//?two\n"));
  EXPECT_THAT(buffer.GetCommentText(CommentIndex(1)), Eq("// valid\n"));
}

TEST_F(LexerTest, InvalidCommentRunAtEof) {
  // An invalid run's line-by-line skip reads the byte after each line's `//`;
  // these cases end the source at that read's boundary, with no trailing
  // newline, to pin its bounds.

  // The final line's introducer byte is the last byte of the source.
  auto& tight = compile_helper_.GetTokenizedBuffer(
      "//!a\n"
      "//!");
  EXPECT_TRUE(tight.has_errors());
  ASSERT_THAT(tight.comments_size(), Eq(1));
  EXPECT_THAT(tight.GetCommentText(CommentIndex(0)), Eq("//!a\n//!"));

  // A bare `//` ending the source has no byte after the introducer at all:
  // the run must stop before it rather than read past the end, and it lexes
  // as its own valid, empty comment.
  auto& bare = compile_helper_.GetTokenizedBuffer(
      "//!a\n"
      "//");
  EXPECT_TRUE(bare.has_errors());
  ASSERT_THAT(bare.comments_size(), Eq(2));
  EXPECT_THAT(bare.GetCommentText(CommentIndex(0)), Eq("//!a\n"));
  EXPECT_THAT(bare.GetCommentText(CommentIndex(1)), Eq("//"));
}

TEST(ArrayStack, MergeTopArrayIntoGrandparent) {
  ArrayStack<int> stack;

  // Basic case with 3 arrays.
  stack.PushArray();
  stack.AppendToTop(1);
  stack.AppendToTop(2);

  stack.PushArray();
  stack.AppendToTop(3);
  stack.AppendToTop(4);
  stack.AppendToTop(5);

  stack.PushArray();
  stack.AppendToTop(6);
  stack.AppendToTop(7);

  stack.MergeTopArrayIntoGrandparent();

  EXPECT_THAT(stack.PeekArrayAt(0), ElementsAre(1, 2, 6, 7));
  EXPECT_THAT(stack.PeekArrayAt(1), ElementsAre(3, 4, 5));
  EXPECT_THAT(stack.PeekArrayAt(2), IsEmpty());
  EXPECT_THAT(stack.PeekArray(), IsEmpty());
  EXPECT_THAT(stack.PeekAllValues(), ElementsAre(1, 2, 6, 7, 3, 4, 5));

  // Appending to the now-empty top array and popping works as expected.
  stack.AppendToTop(8);
  EXPECT_THAT(stack.PeekArray(), ElementsAre(8));
  EXPECT_THAT(stack.PeekAllValues(), ElementsAre(1, 2, 6, 7, 3, 4, 5, 8));

  stack.PopArray();
  EXPECT_THAT(stack.PeekArray(), ElementsAre(3, 4, 5));
  EXPECT_THAT(stack.PeekAllValues(), ElementsAre(1, 2, 6, 7, 3, 4, 5));

  stack.PopArray();
  EXPECT_THAT(stack.PeekArray(), ElementsAre(1, 2, 6, 7));
  EXPECT_THAT(stack.PeekAllValues(), ElementsAre(1, 2, 6, 7));
}

TEST(ArrayStack, MergeTopArrayIntoGrandparentDeeperStack) {
  ArrayStack<int> stack;

  // Verify behavior when there are more than 3 arrays on the stack.
  stack.PushArray();
  stack.AppendToTop(10);

  stack.PushArray();
  stack.AppendToTop(20);

  stack.PushArray();
  stack.AppendToTop(30);

  stack.PushArray();
  stack.AppendToTop(40);
  stack.AppendToTop(50);

  stack.MergeTopArrayIntoGrandparent();

  EXPECT_THAT(stack.PeekArrayAt(0), ElementsAre(10));
  EXPECT_THAT(stack.PeekArrayAt(1), ElementsAre(20, 40, 50));
  EXPECT_THAT(stack.PeekArrayAt(2), ElementsAre(30));
  EXPECT_THAT(stack.PeekArrayAt(3), IsEmpty());
  EXPECT_THAT(stack.PeekAllValues(), ElementsAre(10, 20, 40, 50, 30));
}

TEST(ArrayStack, MergeTopArrayIntoGrandparentEmptyArrays) {
  // Test when the parent array is initially empty.
  {
    ArrayStack<int> stack;
    stack.PushArray();
    stack.AppendToTop(1);
    stack.PushArray();
    stack.PushArray();
    stack.AppendToTop(2);
    stack.AppendToTop(3);

    stack.MergeTopArrayIntoGrandparent();
    EXPECT_THAT(stack.PeekArrayAt(0), ElementsAre(1, 2, 3));
    EXPECT_THAT(stack.PeekArrayAt(1), IsEmpty());
    EXPECT_THAT(stack.PeekArrayAt(2), IsEmpty());
    EXPECT_THAT(stack.PeekAllValues(), ElementsAre(1, 2, 3));
  }

  // Test when the top array is initially empty.
  {
    ArrayStack<int> stack;
    stack.PushArray();
    stack.AppendToTop(1);
    stack.PushArray();
    stack.AppendToTop(2);
    stack.PushArray();

    stack.MergeTopArrayIntoGrandparent();
    EXPECT_THAT(stack.PeekArrayAt(0), ElementsAre(1));
    EXPECT_THAT(stack.PeekArrayAt(1), ElementsAre(2));
    EXPECT_THAT(stack.PeekArrayAt(2), IsEmpty());
    EXPECT_THAT(stack.PeekAllValues(), ElementsAre(1, 2));
  }

  // Test when the grandparent array is initially empty.
  {
    ArrayStack<int> stack;
    stack.PushArray();
    stack.PushArray();
    stack.AppendToTop(1);
    stack.AppendToTop(2);
    stack.PushArray();
    stack.AppendToTop(3);
    stack.AppendToTop(4);

    stack.MergeTopArrayIntoGrandparent();
    EXPECT_THAT(stack.PeekArrayAt(0), ElementsAre(3, 4));
    EXPECT_THAT(stack.PeekArrayAt(1), ElementsAre(1, 2));
    EXPECT_THAT(stack.PeekArrayAt(2), IsEmpty());
    EXPECT_THAT(stack.PeekAllValues(), ElementsAre(3, 4, 1, 2));
  }
}

auto AddAndDiscardCleanups(Context& context) -> void {
  auto depth = context.scope_stack().enclosing_cleanup_scope_depth();
  AddCleanups(context, depth);
  context.scope_stack().DiscardCleanupsSince(depth);
}

auto AddBranchWithCleanups(Context& context, SemIR::LocId loc_id,
                           SemIR::InstBlockId target_id,
                           ScopeStack::CleanupScopeDepth depth) -> void {
  AddCleanups(context, depth);
  AddInst<SemIR::Branch>(context, loc_id, {.target_id = target_id});
}

