       CleanupScopeKind::Owned, /*lexical_lookup_has_load_error=*/false);
  return_scope_stack_.push_back(
      {.decl_id = scope_inst_id, .cleanup_scope_depth = cleanup_scope_depth()});
  if (scope.cleanup_scope_kind == CleanupScopeKind::Owned) {
    CARBON_CHECK(destroy_id_stack_.PeekArray().empty(),
                 "Popping scope with cleanups");
    destroy_id_stack_.PopArray();
  }

    }

auto HandleParseNode(Context& context, Parse::RuntimeBindingNameId node_id)
    -> bool {
  context.node_stack().Push(node_id);
  return true;
}

static auto ResolveBindingPhase(Context& context, Context::State& state,
                                bool is_form,
                                std::optional<Lex::TokenIndex> template_token,
                                std::optional<Lex::TokenIndex> generic_token,
                                std::optional<Lex::TokenIndex> runtime_token,
                                bool& redundant_modifier) -> bool {
  // `template`/`generic` force a generic binding, `runtime` forces a runtime
  // binding, and otherwise the context's default applies.
  bool resolved_generic;
  if (template_token || generic_token) {
    resolved_generic = true;
  } else if (runtime_token) {
    resolved_generic = false;
  } else {
    resolved_generic = state.binding_context != BindingContext::ExplicitParam;
  }

  // A form binding's phase is fixed, so phase keywords don't apply to it, and
  // there is no point diagnosing a redundant keyword once the binding is
  // already in error.
  // TODO: `:?` form bindings are temporary; see the TODO in
  // `HandleBindingPattern`.
  if (is_form || state.has_error) {
    return resolved_generic;
  }

  // Diagnose a phase keyword that is redundant with the contextual default. A
  // keyword that is invalid (rather than redundant) is left for `check`.
  if (generic_token && state.binding_context != BindingContext::ExplicitParam) {
    CARBON_DIAGNOSTIC(
        RedundantGenericModifier, Error,
        "`generic` is redundant here; this binding is a checked generic by "
        "default");
    context.emitter().Emit(*generic_token, RedundantGenericModifier);
    redundant_modifier = true;
  } else if (runtime_token &&
             state.binding_context == BindingContext::ExplicitParam) {
    CARBON_DIAGNOSTIC(
        RedundantRuntimeModifier, Error,
        "`runtime` is redundant here; this binding is runtime by default");
    context.emitter().Emit(*runtime_token, RedundantRuntimeModifier);
    redundant_modifier = true;
  }

  return resolved_generic;
}

static auto ExplicitParamListContext(Context& context,
                                     BindingContext decl_context)
    -> BindingContext {
  // A compile-time entity's parameters are compile-time whether or not this
  // list is a name qualifier, so there is no need to look ahead for the `.`.
  if (decl_context == BindingContext::CompileTimeEntityParam) {
    return decl_context;
  }
  auto open_paren = *context.position();
  auto close_paren = context.tokens().GetMatchedClosingToken(open_paren);
  auto after_close = Lex::TokenIndex(close_paren.index + 1);
  if (context.tokens().GetKind(after_close) == Lex::TokenKind::Period) {
    return BindingContext::CompileTimeEntityParam;
  }
  return decl_context;
}

static auto PhaseFlag(Phase phase) -> llvm::StringRef {
  switch (phase) {
    case Phase::Lex:
      return "--phase=lex";
    case Phase::Parse:
      return "--phase=parse";
    case Phase::Check:
      return "--phase=check";
  }
}

static auto SourceFileName(size_t index) -> std::string {
  return llvm::formatv("file_{0}.{1}", index,
                       L == Lang::Carbon ? "carbon" : "cpp")
      .str();
}

SubprocessCompiler()
      : installation_(InstallPaths::MakeForBazelRunfiles(GetExePath())),
        gen_(L) {
    carbon_path_ = (installation_.root() / "carbon-busybox").string();
    clang_path_ = installation_.clang_path().string();

    // Leave stdin connected to the parent, but discard the compiler's stdout
    // and stderr so benchmark output isn't cluttered.
    redirects_[0] = std::nullopt;
    redirects_[1] = llvm::StringRef("/dev/null");
    redirects_[2] = llvm::StringRef("/dev/null");
  }

auto SetUpFiles(llvm::ArrayRef<std::string> sources)
      -> llvm::SmallVector<std::string> {
    auto tmp_dir_result = Filesystem::MakeTmpDir();
    CARBON_CHECK(tmp_dir_result.ok(), "Failed to create temp dir: {0}",
                 tmp_dir_result.error());
    tmp_dir_ = std::move(*tmp_dir_result);

    llvm::SmallVector<std::string> file_names;
    file_names.reserve(sources.size());
    for (auto [i, source] : llvm::enumerate(sources)) {
      std::string file_name = SourceFileName<L>(i);
      auto write_result = tmp_dir_->WriteFileFromString(file_name, source);
      CARBON_CHECK(write_result.ok(), "Failed to write file: {0}",
                   write_result.error());
      file_names.push_back((tmp_dir_->path() / file_name).string());
    }
    return file_names;
  }

auto RunCompile(llvm::StringRef file_name, Phase phase) -> bool {
    llvm::StringRef program;
    llvm::SmallVector<llvm::StringRef> args;

    if constexpr (L == Lang::Carbon) {
      program = carbon_path_;
      args = {"carbon", "compile", PhaseFlag(phase), file_name};
    } else {
      program = clang_path_;
      args = {"clang++", "--driver-mode=g++"};

      // We only support check and lex phases for C++ as it doesn't have a
      // meaningful parse phase in Clang.
      switch (phase) {
        case Phase::Check:
          args.push_back("-fsyntax-only");
          break;
        case Phase::Lex:
          args.push_back("-E");
          args.push_back("-o");
          args.push_back("/dev/null");
          break;
        case Phase::Parse:
          CARBON_FATAL("No parse phase to benchmark in Clang");
      }
      args.push_back(file_name);
    }

    std::string err_msg;
    bool execution_failed = false;
    int exit_code = llvm::sys::ExecuteAndWait(
        program, args, /*Env=*/std::nullopt, redirects_,
        /*SecondsToWait=*/0, /*MemoryLimit=*/0, &err_msg, &execution_failed);
    return exit_code == 0 && !execution_failed;
  }

static auto ComputeFileCount(int target_lines, int min_files,
                             [[maybe_unused]] int max_files) -> int {
  int file_count = (1024 * 1024) / target_lines;
  // Use a smaller number of files in debug builds where compiles are slower,
  // capping at the release-mode minimum.
  return std::max(1, std::min(min_files, file_count));
  return std::max(min_files, std::min(max_files, file_count));
template <Lang L, Phase P, Mode M = Mode::InProcess>
  using Compiler = CompilerFor<L, M>;
  Compiler bench;
  int num_files =
      ComputeFileCount(target_lines, Compiler::MinFiles, Compiler::MaxFiles);
  }

TEST(SourceGenTest, IdentifierByteSumStableAcrossSeeds) {
  struct Config {
    int number;
    int min_length;
    int max_length;
    bool uniform;
    bool unique;
  };
  // A spread of parameters including: the default range, narrow ranges, the
  // single-length extreme, uniform distributions, and a uniform range with a
  // `max_length` well beyond the 64 limit that only the uniform path allows.
  Config configs[] = {
      {.number = 1000, .min_length = 1, .max_length = 64, .uniform = false},
      {.number = 1000, .min_length = 4, .max_length = 64, .uniform = false},
      {.number = 999, .min_length = 1, .max_length = 64, .uniform = false},
      {.number = 1000, .min_length = 10, .max_length = 20, .uniform = false},
      {.number = 1000, .min_length = 8, .max_length = 8, .uniform = false},
      {.number = 100, .min_length = 10, .max_length = 19, .uniform = true},
      {.number = 97, .min_length = 10, .max_length = 19, .uniform = true},
      {.number = 500, .min_length = 50, .max_length = 200, .uniform = true},
      {.number = 1000,
       .min_length = 4,
       .max_length = 64,
       .uniform = false,
       .unique = true},
      {.number = 1000,
       .min_length = 4,
       .max_length = 4,
       .uniform = false,
       .unique = true},
      {.number = 200,
       .min_length = 30,
       .max_length = 120,
       .uniform = true,
       .unique = true},
  };

  for (const Config& c : configs) {
    SCOPED_TRACE(llvm::formatv(
        "Config: number={0} min_length={1} max_length={2} uniform={3} "
        "unique={4}",
        c.number, c.min_length, c.max_length, c.uniform, c.unique));
    std::optional<ssize_t> expected_sum;
    bool any_different = false;
    std::optional<llvm::SmallVector<llvm::StringRef>> first;
    constexpr int NumSeeds = 8;
    for (int seed : llvm::seq(NumSeeds)) {
      // Each iteration constructs a fresh generator with an independent random
      // seed; the traced index identifies which iteration failed.
      SCOPED_TRACE(llvm::formatv("Seed iteration: {0}", seed));
      SourceGen gen;
      auto idents = c.unique
                        ? gen.GetShuffledUniqueIdentifiers(
                              c.number, c.min_length, c.max_length, c.uniform)
                        : gen.GetShuffledIdentifiers(c.number, c.min_length,
                                                     c.max_length, c.uniform);
      EXPECT_THAT(idents, SizeIs(c.number));
      EXPECT_THAT(idents,
                  Each(SizeIs(AllOf(Ge(c.min_length), Le(c.max_length)))));

      ssize_t sum = SumSizes(idents);
      if (!expected_sum) {
        expected_sum = sum;
        first = idents;
        continue;
      }
      // The byte sum must be identical regardless of the seed.
      EXPECT_THAT(sum, Eq(*expected_sum));
      if (idents != *first) {
        any_different = true;
      }
    }
    // Sanity check that the generators really are producing different content,
    // so that the invariance check above is meaningful rather than trivially
    // passing on identical output.
    EXPECT_TRUE(any_different);
  }
}

auto Formatter::EmitComment() -> void {
  auto comment = *next_comment_;
  ++next_comment_;

  if (tokens_->IsTrailingComment(comment) && line_state_ != LineState::Empty) {
    // Keep the trailing comment on the current line, separated by a space. The
    // line still has content because its newline was deferred (`EndOfLine`) or
    // not yet required.
    *out_ << " " << tokens_->GetCommentText(comment);
  } else {
    // A full-line comment (or a trailing comment with nothing left to attach
    // to) is emitted on its own line.
    RequireEmptyLine();
    PrepareForSpacedContent();
    // TODO: We do need to adjust the indent of multi-line comments.
    *out_ << tokens_->GetCommentText(comment);
  }
  // Comment text includes a terminating newline, so just update the state.
  line_state_ = LineState::Empty;
}

TEST_F(LexerTest, TrailingComment) {
  // A comment that follows other content on a line is a valid trailing comment.
  auto& buffer = compile_helper_.GetTokenizedBuffer(
      "// leading\nvar x: i32 = 0; // trailing\n// trailing's neighbor\n");
  EXPECT_FALSE(buffer.has_errors());
  // The trailing comment is recorded but never coalesced with an adjacent
  // full-line comment, so the leading comment, the trailing comment, and the
  // following full-line comment remain three separate comments.
  EXPECT_THAT(buffer.comments_size(), Eq(3));
}

TEST_F(LexerTest, TrailingCommentAfterMultiLineString) {
  // A multi-line string literal records the real indentation of each line it
  // spans. Here the trailing `//` is deliberately aligned to the column where
  // the literal opened (both at column 17); if the literal instead recorded
  // that opening column as the final line's indent (as it once did), the
  // trailing-comment check in `Lexer::LexComment` would misclassify this as a
  // full-line comment.
  auto& buffer = compile_helper_.GetTokenizedBuffer(
      "var x: String = '''\n"
      "           text\n"
      "           '''; // trailing\n");
  EXPECT_FALSE(buffer.has_errors());
  ASSERT_THAT(buffer.comments_size(), Eq(1));
  EXPECT_TRUE(buffer.IsTrailingComment(CommentIndex(0)));

TEST_F(TreeTest, IncompleteLambdaRecovers) {
  // An incomplete lambda -- a `fn` introducer with no body, here `(fn)` -- must
  // still parse to a structurally valid tree (a `Lambda` node with a
  // placeholder body) rather than leaving an orphaned introducer where an
  // expression is required, which would fail the parser's own tree
  // verification.
  Lex::TokenizedBuffer& tokens =
      compile_helper_.GetTokenizedBuffer("var x: auto = (fn);");
  ASSERT_FALSE(tokens.has_errors());
  ::testing::NiceMock<Testing::MockDiagnosticConsumer> consumer;
  Parse::ParseOptions options;
  options.consumer = &consumer;
  Tree tree = Parse(tokens, options);
  EXPECT_TRUE(tree.has_errors());
}

TEST_F(LexerTest, RawIdentifierIntroducerAtEndOfFile) {
  // `r#` at the very end of the source is not a raw identifier -- there is no
  // identifier after the `#` -- but the leading `r` is still an identifier
  // whose text begins with `r#`. Computing that text checks for the raw form
  // and must not read past the end of the buffer.
  auto& buffer = compile_helper_.GetTokenizedBuffer("r#");
  for (TokenIndex token : buffer.tokens()) {
    if (buffer.GetKind(token) == TokenKind::Identifier) {
      EXPECT_EQ(buffer.GetTokenText(token), "r");
    }
  }
}

static auto ImportSource(Import import) -> llvm::StringRef {
  switch (import) {
    case Import::Nothing:
      return "fn F() {}\n";
    case Import::SingleType:
      return "fn F(n: i32) -> i32 { return n; }\n";
    case Import::ManyTypesManyImpls:
      return "fn F(a: i32, b: i64, c: u32, d: f64) -> bool {\n"
             "  return ((a + a - a) == a) and ((b * b) > b) and\n"
             "         ((c / c) <= c) and (d < d);\n"
             "}\n";
    case Import::NonTrivialAmount:
      return "fn F(a: array(i32, 3), s: str) -> i32 {\n"
             "  var n: i32 = s.Size() as i32;\n"
             "  for (x: i32 in a) { n = (n + x) * x; }\n"
             "  return n;\n"
             "}\n";
  }
}

explicit PreludeCompileBenchmark(llvm::StringRef source)
      : fs_(new llvm::vfs::InMemoryFileSystem),
        installation_(InstallPaths::MakeForBazelRunfiles(GetExePath())) {
    AddPreludeFilesToVfs(installation_, fs_);
    fs_->addFile(InputFileName, /*ModificationTime=*/0,
                 llvm::MemoryBuffer::getMemBuffer(source));
  }

auto RunCompile(MemUsage* mem_usage = nullptr) -> bool {
    llvm::raw_null_ostream output;
    Driver driver(fs_, &installation_, /*input_stream=*/nullptr, &output,
                  &llvm::errs());
    if (mem_usage) {
      driver.set_mem_usage(mem_usage);
    }
    return driver.RunCommand({"compile", "--phase=check", InputFileName})
        .success;
  }

auto RecordMemoryCounters(benchmark::State& state) -> void {
    // The driver collects each compiled file's usage into this one `MemUsage`:
    // the prelude files and the input each contribute entries with the same
    // labels, which `SumMemUsage` accumulates.
    MemUsage mem_usage;
    bool success = RunCompile(&mem_usage);
    CARBON_CHECK(success);
    MemSizes sizes = SumMemUsage(mem_usage);
    // Guard against a `MemUsage` label being renamed out from under us, which
    // would otherwise silently report zero sizes.
    CARBON_CHECK(sizes.insts > 0, "no SemIR instruction memory was recorded");

    // The `Mem` prefix marks these as memory-cost metrics (smaller is better)
    // for `scripts/bench_runner.py`.
    auto set = [&](const char* name, int64_t bytes) {
      state.counters[name] = benchmark::Counter(static_cast<double>(bytes));
    };
    set("MemTotal", sizes.total);
    set("MemSemIR", sizes.sem_ir);
    set("MemSemIRInsts", sizes.insts);
    set("MemSemIRInstLocs", sizes.inst_locs);
    set("MemSemIRConstantValues", sizes.constant_values);
    set("MemSemIRInstBlocks", sizes.inst_blocks);
    set("MemSemIRAllocator", sizes.allocator);
  }

static auto SumMemUsage(const MemUsage& mem_usage) -> MemSizes {
    MemSizes sizes;
    for (const MemUsage::Entry& entry : mem_usage.entries()) {
      llvm::StringRef label = entry.label;
      sizes.total += entry.used_bytes;
      if (label.starts_with("sem_ir_")) {
        sizes.sem_ir += entry.used_bytes;
      }
      if (label == "sem_ir_.insts_.values_") {
        sizes.insts += entry.used_bytes;
      } else if (label == "sem_ir_.insts_.loc_ids_") {
        sizes.inst_locs += entry.used_bytes;
      } else if (label == "sem_ir_.constant_values_.values_") {
        sizes.constant_values += entry.used_bytes;
      } else if (label == "sem_ir_.inst_blocks_.values_") {
        sizes.inst_blocks += entry.used_bytes;
      } else if (label == "sem_ir_.allocator_") {
        sizes.allocator += entry.used_bytes;
      }
    }
    return sizes;
  }

static auto BM_PreludeCompile(benchmark::State& state) -> void {
  PreludeCompileBenchmark bench(ImportSource(V));
  bench.RecordMemoryCounters(state);

  for (auto _ : state) {
    bool success = bench.RunCompile();
    CARBON_CHECK(success);
    benchmark::DoNotOptimize(success);
  }
}

auto HandleParseNode(Context& context, Parse::SelfBindingPatternId node_id)
    -> bool {
  // A `self` binding with an omitted type behaves like `self: Self`. There is
  // no type expression in the parse tree, so synthesize a reference to `Self`
  // into the current subpattern region and feed it in as the binding's type.
  auto self_type =
      LookupUnqualifiedName(context, node_id, SemIR::NameId::SelfType);
  auto self_type_inst_id = BuildNameRef(
      context, node_id, SemIR::NameId::SelfType,
      self_type.scope_result.target_inst_id(), self_type.specific_id);
  return HandleAnyBindingPattern(context, node_id,
                                 Parse::NodeKind::LetBindingPattern,
                                 /*is_unused=*/false, self_type_inst_id);
}

TEST_METHOD(InspectCommands_FormatArgumentHasDockerAlias)
    {
        const auto VerifyFormatAlias = [](const Command& command) {
            const auto args = command.GetArguments();
            const auto found = std::ranges::find_if(args, [](const auto& arg) { return arg.Type() == ArgType::InspectFormat; });

            VERIFY_IS_TRUE(found != args.end(), std::format(L"Command '{}' does not register --format", command.FullName()).c_str());
            VERIFY_ARE_EQUAL(std::wstring(L"format"), found->Name());
            VERIFY_ARE_EQUAL(std::wstring(L"f"), found->Alias());
        };

        VerifyFormatAlias(InspectCommand(L""));
        VerifyFormatAlias(ContainerInspectCommand(L"container"));
        VerifyFormatAlias(ImageInspectCommand(L"image"));
        VerifyFormatAlias(NetworkInspectCommand(L"network"));
        VerifyFormatAlias(VolumeInspectCommand(L"volume"));
    }

TEST_METHOD(Value_AliasCarriesValue)
    {
        std::vector<Argument> defs = {Argument::Create(ArgType::InspectFormat), Argument::Create(ArgType::ObjectId, false, Limit::Unlimited)};

        VERIFY_ARE_EQUAL(wsl::shared::c_jsonCompactIndent, ParseFlags(L"wslc -f json cont1", defs).GetValue<ArgType::InspectFormat>());
        VERIFY_ARE_EQUAL(wsl::shared::c_jsonCompactIndent, ParseFlags(L"wslc -f=json cont1", defs).GetValue<ArgType::InspectFormat>());

        // The positional still lands where it belongs once the alias has taken its value.
        auto args = ParseFlags(L"wslc -f json cont1", defs);
        VERIFY_ARE_EQUAL(1u, args.Count(ArgType::ObjectId));
        VERIFY_ARE_EQUAL(std::wstring(L"cont1"), args.GetValue<ArgType::ObjectId>());
    }

static size_t CharacterWidth(UChar32 CodePoint)
{
    const auto width = u_getIntPropertyValue(CodePoint, UCHAR_EAST_ASIAN_WIDTH);
    return (width == U_EA_WIDE || width == U_EA_FULLWIDTH) ? 2 : 1;
}

std::wstring wsl::windows::common::string::Ellipsis(_In_ std::wstring_view Value, _In_ size_t MaxDisplayWidth)
{
    if (MaxDisplayWidth == 0 || Value.empty())
    {
        return {};
    }

    const auto length = gsl::narrow_cast<int32_t>(Value.size());
    if (MaxDisplayWidth == 1)
    {
        // There is no room for both content and an ellipsis, so the leading code point is kept as-is even
        // if it is wider than the limit.
        int32_t index = 0;
        UChar32 codePoint{};
        U16_NEXT(Value.data(), index, length, codePoint);
        return std::wstring{Value.substr(0, index)};
    }

    // The ellipsis occupies one column, so the retained content has one column less to work with.
    const auto budget = MaxDisplayWidth - 1;
    size_t totalWidth = 0;
    size_t cutoff = 0;
    for (int32_t index = 0; index < length;)
    {
        UChar32 codePoint{};
        U16_NEXT(Value.data(), index, length, codePoint);
        totalWidth += CharacterWidth(codePoint);
        if (totalWidth <= budget)
        {
            cutoff = index;
        }
    }

    // A cutoff of zero means the first code point alone leaves no room for the ellipsis, in which case docker
    // returns the value untouched.
    if (totalWidth <= MaxDisplayWidth || cutoff == 0)
    {
        return std::wstring{Value};
    }

    return std::wstring{Value.substr(0, cutoff)} + L'\u2026';
}

std::wstring wsl::windows::common::timestamp::FormatElapsedSeconds(LONGLONG elapsedSeconds)
{
    using wsl::shared::Localization;

    const auto [unit, count] = ClassifyElapsedSeconds(elapsedSeconds);
    switch (unit)
    {
    case ElapsedUnit::LessThanASecond:
        return Localization::WSLCCLI_RelativeTimeLessThanASecond();
    case ElapsedUnit::OneSecond:
        return Localization::WSLCCLI_RelativeTimeOneSecond();
    case ElapsedUnit::Seconds:
        return Localization::WSLCCLI_RelativeTimeSeconds(count);
    case ElapsedUnit::AboutAMinute:
        return Localization::WSLCCLI_RelativeTimeAboutAMinute();
    case ElapsedUnit::Minutes:
        return Localization::WSLCCLI_RelativeTimeMinutes(count);
    case ElapsedUnit::AboutAnHour:
        return Localization::WSLCCLI_RelativeTimeAboutAnHour();
    case ElapsedUnit::Hours:
        return Localization::WSLCCLI_RelativeTimeHours(count);
    case ElapsedUnit::Days:
        return Localization::WSLCCLI_RelativeTimeDays(count);
    case ElapsedUnit::Weeks:
        return Localization::WSLCCLI_RelativeTimeWeeks(count);
    case ElapsedUnit::Months:
        return Localization::WSLCCLI_RelativeTimeMonths(count);
    case ElapsedUnit::Years:
        return Localization::WSLCCLI_RelativeTimeYears(count);
    default:
        THROW_HR(E_UNEXPECTED);
    }
}

std::wstring wsl::windows::common::timestamp::FormatInvariantElapsedSeconds(LONGLONG elapsedSeconds)
{
    const auto [unit, count] = ClassifyElapsedSeconds(elapsedSeconds);
    switch (unit)
    {
    case ElapsedUnit::LessThanASecond:
        return L"Less than a second ago";
    case ElapsedUnit::OneSecond:
        return L"1 second ago";
    case ElapsedUnit::Seconds:
        return std::format(L"{} seconds ago", count);
    case ElapsedUnit::AboutAMinute:
        return L"About a minute ago";
    case ElapsedUnit::Minutes:
        return std::format(L"{} minutes ago", count);
    case ElapsedUnit::AboutAnHour:
        return L"About an hour ago";
    case ElapsedUnit::Hours:
        return std::format(L"{} hours ago", count);
    case ElapsedUnit::Days:
        return std::format(L"{} days ago", count);
    case ElapsedUnit::Weeks:
        return std::format(L"{} weeks ago", count);
    case ElapsedUnit::Months:
        return std::format(L"{} months ago", count);
    case ElapsedUnit::Years:
        return std::format(L"{} years ago", count);
    default:
        THROW_HR(E_UNEXPECTED);
    }

std::wstring wsl::windows::common::timestamp::FormatInvariantRelativeTime(LONGLONG timestamp)
{
    if (timestamp == 0)
    {
        return {};
    }

    return FormatInvariantElapsedSeconds(static_cast<LONGLONG>(std::time(nullptr)) - timestamp);
}

std::wstring wsl::windows::common::timestamp::FormatInvariantRelativeTime(LONGLONG timestamp)
{
    if (timestamp == 0)
    {
        return {};
    }

    return FormatInvariantElapsedSeconds(static_cast<LONGLONG>(std::time(nullptr)) - timestamp);
}

std::wstring ContainerService::LocalizedContainerStateName(WSLCContainerState state)
{
    switch (state)
    {
    case WSLCContainerState::WslcContainerStateCreated:
        return Localization::WSLCCLI_ContainerStateCreated();
    case WSLCContainerState::WslcContainerStateRunning:
        return Localization::WSLCCLI_ContainerStateRunning();
    case WSLCContainerState::WslcContainerStateDeleted:
        return Localization::WSLCCLI_ContainerStateStopped();
    case WSLCContainerState::WslcContainerStateExited:
        return Localization::WSLCCLI_ContainerStateExited();
    case WSLCContainerState::WslcContainerStateInvalid:
        return Localization::WSLCCLI_ContainerStateInvalid();
    default:
        THROW_HR(E_UNEXPECTED);
    }
}

std::wstring ContainerService::ContainerStateToString(WSLCContainerState state, LONGLONG stateChangedAt, FormatType format)
{
    const auto invariant = format == FormatType::Json;
    auto stateString = invariant ? ContainerStateName(state) : LocalizedContainerStateName(state);
    if (stateChangedAt == 0 || state == WSLCContainerState::WslcContainerStateInvalid)
    const auto relative = invariant ? wsl::windows::common::timestamp::FormatInvariantRelativeTime(stateChangedAt)
                                    : wsl::windows::common::timestamp::FormatRelativeTime(stateChangedAt);

    return std::format(L"{} {}", stateString, relative);
}

static bool IsPrintable(UChar32 codePoint)
{
    constexpr auto printableMask = U_GC_L_MASK | U_GC_M_MASK | U_GC_N_MASK | U_GC_P_MASK | U_GC_S_MASK;
    return codePoint == U' ' || (U_GET_GC_MASK(codePoint) & printableMask) != 0;
}

static void AppendEscape(std::wstring& quoted, UChar32 codePoint)
{
    switch (codePoint)
    {
    case L'\a':
        quoted += L"\\a";
        return;
    case L'\b':
        quoted += L"\\b";
        return;
    case L'\f':
        quoted += L"\\f";
        return;
    case L'\n':
        quoted += L"\\n";
        return;
    case L'\r':
        quoted += L"\\r";
        return;
    case L'\t':
        quoted += L"\\t";
        return;
    case L'\v':
        quoted += L"\\v";
        return;
    default:
        break;
    }

    if (codePoint < L' ' || codePoint == 0x7F)
    {
        quoted += std::format(L"\\x{:02x}", static_cast<unsigned int>(codePoint));
    }
    else if (U_IS_SURROGATE(codePoint))
    {
        // An unpaired surrogate is not a valid code point, and Go substitutes the replacement character.
        quoted += L"\\ufffd";
    }
    else if (codePoint < 0x10000)
    {
        quoted += std::format(L"\\u{:04x}", static_cast<unsigned int>(codePoint));
    }
    else
    {
        quoted += std::format(L"\\U{:08x}", static_cast<unsigned int>(codePoint));
    }
}

std::wstring ContainerService::FormatCommand(const std::string& command, bool truncate)
{
    constexpr size_t c_maxDisplayWidth = 20;

    auto wide = wsl::shared::string::MultiByteToWide(command);
    if (truncate)
    {
        wide = wsl::windows::common::string::Ellipsis(wide, c_maxDisplayWidth);
    }

    // Quoting happens after truncation, so the result can exceed c_maxDisplayWidth. This matches docker, which truncates
    // the command first and quotes the truncated value.
    const auto length = static_cast<int32_t>(wide.size());
    std::wstring quoted{L'"'};
    for (int32_t index = 0; index < length;)
    {
        const auto start = index;
        UChar32 codePoint{};
        U16_NEXT(wide.data(), index, length, codePoint);

        if (codePoint == L'"' || codePoint == L'\\')
        {
            quoted += L'\\';
            quoted += static_cast<wchar_t>(codePoint);
        }
        else if (IsPrintable(codePoint))
        {
            quoted.append(wide, start, static_cast<size_t>(index - start));
        }
        else
        {
            AppendEscape(quoted, codePoint);
        }
    }

    quoted += L'"';
    return quoted;
}

std::wstring ContainerService::FormatMounts(const std::string& mounts, bool truncate)
{
    constexpr size_t c_maxDisplayWidth = 15;

    auto wide = wsl::shared::string::MultiByteToWide(mounts);
    if (!truncate || wide.empty())
    {
        return wide;
    }

    std::vector<std::wstring> shortened;
    for (const auto& mount : wsl::shared::string::SplitPreserveEmpty(std::wstring_view{wide}, L','))
    {
        shortened.emplace_back(wsl::windows::common::string::Ellipsis(mount, c_maxDisplayWidth));
    }

    return wsl::shared::string::Join(shortened, L',');
}

std::wstring ContainerService::FormatStatus(const std::string& status, WSLCContainerState state, LONGLONG stateChangedAt, FormatType format)
{
    if (!status.empty())
    {
        return wsl::shared::string::MultiByteToWide(status);
    }

    return ContainerStateToString(state, stateChangedAt, format);
}

std::string ContainerService::FormatHealthStatus(const std::string& status)
{
    const auto open = status.find('(');
    if (open == std::string::npos || status.back() != ')')
    {
        return {};
    }

    constexpr std::string_view c_healthPrefix = "health: ";
    auto health = std::string_view{status}.substr(open + 1, status.size() - open - 2);
    if (health.starts_with(c_healthPrefix))
    {
        health.remove_prefix(c_healthPrefix.size());
    }

    if (health == "healthy" || health == "unhealthy" || health == "starting")
    {
        return std::string{health};
    }

    return {};
    wsl::windows::common::wslc::unique_container_entry_array containers;
        entry.Command = current.Command == nullptr ? "" : current.Command;
        entry.Status = current.Status == nullptr ? "" : current.Status;
        entry.Labels = current.Labels == nullptr ? "" : current.Labels;
        entry.Networks = current.Networks == nullptr ? "" : current.Networks;
        entry.Mounts = current.Mounts == nullptr ? "" : current.Mounts;
        entry.LocalVolumes = current.LocalVolumes;

ContainerOutputInformation ToContainerOutput(const ContainerInformation& container, bool truncate, FormatType format)
{
    ContainerOutputInformation entry;
    entry.Command = WideToMultiByte(ContainerService::FormatCommand(container.Command, truncate));
    entry.CreatedAt = EpochToLocalDisplayTime(container.CreatedAt);
    // The runtime reports health as a suffix on the status description, which is the only place it is
    // exposed by the listing API.
    entry.HealthStatus = ContainerService::FormatHealthStatus(container.Status);
    entry.ID = truncate ? TruncateId(container.Id) : container.Id;
    entry.Image = container.Image;
    entry.Labels = container.Labels;
    entry.LocalVolumes = std::to_string(container.LocalVolumes);
    entry.Mounts = WideToMultiByte(ContainerService::FormatMounts(container.Mounts, truncate));
    entry.Names = container.Name;
    entry.Networks = container.Networks;
    entry.Platform.architecture = wsl::shared::Arm64 ? "arm64" : "amd64";
    entry.Platform.os = "linux";
    entry.Ports = WideToMultiByte(ContainerService::FormatPorts(container.State, container.Ports));
    entry.RunningFor = WideToMultiByte(
        format == FormatType::Json ? FormatInvariantRelativeTime(container.CreatedAt) : FormatRelativeTime(container.CreatedAt));
    // Container sizes are only computed when docker is passed --size, which wslc does not support.
    entry.Size = WideToMultiByte(FormatHumanReadableSize(0));
    entry.State = WideToMultiByte(ContainerService::ContainerStateName(container.State));
    entry.Status = WideToMultiByte(ContainerService::FormatStatus(container.Status, container.State, container.StateChangedAt, format));

    return entry;
}

TEST_METHOD(Ellipsis_NarrowCharacters_AreCountedAsOneColumn)
    {
        VERIFY_ARE_EQUAL(std::wstring{L""}, Ellipsis(L"", 20));
        VERIFY_ARE_EQUAL(std::wstring{L"sleep 3600"}, Ellipsis(L"sleep 3600", 20));
        VERIFY_ARE_EQUAL(std::wstring{L"12345678901234567890"}, Ellipsis(L"12345678901234567890", 20));
        VERIFY_ARE_EQUAL(std::wstring{L"1234567890123456789\u2026"}, Ellipsis(L"123456789012345678901", 20));
        VERIFY_ARE_EQUAL(std::wstring(19, L'\u00E0') + L"\u2026", Ellipsis(std::wstring(21, L'\u00E0'), 20));
    }

TEST_METHOD(Ellipsis_WideCharacters_AreCountedAsTwoColumns)
    {
        // Ten wide characters fill the twenty columns exactly, so an eleventh forces the value to be shortened
        // to the nine characters that leave room for the ellipsis.
        VERIFY_ARE_EQUAL(std::wstring(10, L'\u65E5'), Ellipsis(std::wstring(10, L'\u65E5'), 20));
        VERIFY_ARE_EQUAL(std::wstring(9, L'\u65E5') + L"\u2026", Ellipsis(std::wstring(11, L'\u65E5'), 20));
        VERIFY_ARE_EQUAL(std::wstring(9, L'\uFF21') + L"\u2026", Ellipsis(std::wstring(11, L'\uFF21'), 20));
        VERIFY_ARE_EQUAL(std::wstring{L"ab"} + std::wstring(8, L'\u65E5') + L"\u2026", Ellipsis(L"ab" + std::wstring(10, L'\u65E5'), 20));
    }

TEST_METHOD(Ellipsis_SurrogatePairs_AreNotSplit)
    {
        // Emoji are wide and encoded as surrogate pairs, so both the column count and the code unit boundary
        // have to be honored.
        const std::wstring emoji{L"\U0001F600"};
        std::wstring ten;
        for (size_t index = 0; index < 10; ++index)
        {
            ten += emoji;
        }

        VERIFY_ARE_EQUAL(ten, Ellipsis(ten, 20));
        VERIFY_ARE_EQUAL(ten.substr(0, 18) + L"\u2026", Ellipsis(ten + emoji, 20));
    }

TEST_METHOD(Ellipsis_SmallWidths_MatchDocker)
    {
        VERIFY_ARE_EQUAL(std::wstring{L""}, Ellipsis(L"abc", 0));

        // A width of one has no room for both content and an ellipsis, so the leading code point is kept even
        // when it is wider than the limit.
        VERIFY_ARE_EQUAL(std::wstring{L"a"}, Ellipsis(L"abc", 1));
        VERIFY_ARE_EQUAL(std::wstring{L"\u65E5"}, Ellipsis(L"\u65E5\u65E5", 1));
        VERIFY_ARE_EQUAL(std::wstring{L"\U0001F600"}, Ellipsis(L"\U0001F600\U0001F600", 1));

        // A leading wide character leaves no room for the ellipsis at a width of two, and docker returns the
        // value untouched in that case.
        VERIFY_ARE_EQUAL(std::wstring{L"\u65E5\u65E5"}, Ellipsis(L"\u65E5\u65E5", 2));
        VERIFY_ARE_EQUAL(std::wstring{L"a\u2026"}, Ellipsis(L"abc", 2));
        VERIFY_ARE_EQUAL(std::wstring{L"\u65E5\u2026"}, Ellipsis(L"\u65E5\u65E5", 3));
    }

TEST_METHOD(FormatCommand_NoTruncate_KeepsFullCommand)
    {
        const std::string command = "sh -c 'echo this is a very long command that should be truncated by docker'";
        VERIFY_ARE_EQUAL(
            std::wstring{L"\"" + wsl::shared::string::MultiByteToWide(command) + L"\""}, ContainerService::FormatCommand(command, false));
    }

TEST_METHOD(FormatCommand_EmbeddedQuotesAndBackslashes_AreEscaped)
    {
        // Raw string literals are avoided here: the compiler mangles them when the verify macro
        // stringizes its arguments.
        VERIFY_ARE_EQUAL(std::wstring{L"\"say \\\"hi\\\"\""}, Truncated("say \"hi\""));
        VERIFY_ARE_EQUAL(std::wstring{L"\"c:\\\\temp\""}, Truncated("c:\\temp"));
    }

TEST_METHOD(FormatCommand_NarrowMultiByteCharacters_CountedAsOneColumn)
    {
        const std::string accented = "\xC3\xA0";
        std::string twenty;
        for (int i = 0; i < 20; ++i)
        {
            twenty += accented;
        }

        VERIFY_ARE_EQUAL(std::wstring(20, L'\u00E0').insert(0, L"\"") + L"\"", Truncated(twenty));
        VERIFY_ARE_EQUAL(std::wstring(19, L'\u00E0').insert(0, L"\"") + L"\u2026\"", Truncated(twenty + accented));
    }

TEST_METHOD(FormatCommand_WideCharacters_CountedAsTwoColumns)
    {
        // Docker measures display columns, so an East Asian wide character consumes two of the twenty
        // available columns and only ten of them fit.
        const std::string wide = "\xE6\x97\xA5";
        std::string ten;
        for (int i = 0; i < 10; ++i)
        {
            ten += wide;
        }

        VERIFY_ARE_EQUAL(std::wstring(10, L'\u65E5').insert(0, L"\"") + L"\"", Truncated(ten));
        VERIFY_ARE_EQUAL(std::wstring(9, L'\u65E5').insert(0, L"\"") + L"\u2026\"", Truncated(ten + wide));
    }

TEST_METHOD(FormatCommand_MixedWidthCharacters_AreShortenedByColumn)
    {
        // Two narrow characters leave eighteen columns, so eight wide characters fit before the ellipsis.
        const std::string wide = "\xE6\x97\xA5";
        std::string command = "ab";
        for (int i = 0; i < 10; ++i)
        {
            command += wide;
        }

        VERIFY_ARE_EQUAL(std::wstring{L"\"ab"} + std::wstring(8, L'\u65E5') + L"\u2026\"", Truncated(command));
    }

TEST_METHOD(FormatCommand_SurrogatePairs_AreNotSplit)
    {
        // Emoji are wide and encoded as surrogate pairs, so a shortened value has to stop on a code point
        // boundary as well as a column boundary.
        const std::string emoji = "\xF0\x9F\x98\x80";
        std::string ten;
        std::wstring expected;
        for (int i = 0; i < 10; ++i)
        {
            ten += emoji;
            expected += L"\U0001F600";
        }

        VERIFY_ARE_EQUAL(L"\"" + expected + L"\"", Truncated(ten));
        VERIFY_ARE_EQUAL(L"\"" + expected.substr(0, 18) + L"\u2026\"", Truncated(ten + emoji));
    }

TEST_METHOD(FormatCommand_ControlCharacters_AreEscaped)
    {
        // Docker quotes this field with Go's strconv.Quote, which renders control characters as escape sequences
        // rather than emitting them raw and breaking the table row.
        VERIFY_ARE_EQUAL(std::wstring{L"\"line1\\nline2\""}, Truncated("line1\nline2"));
        VERIFY_ARE_EQUAL(std::wstring{L"\"col1\\tcol2\""}, Truncated("col1\tcol2"));
        VERIFY_ARE_EQUAL(std::wstring{L"\"a\\rb\""}, Truncated("a\rb"));
        VERIFY_ARE_EQUAL(std::wstring{L"\"a\\vb\""}, Truncated("a\vb"));
        VERIFY_ARE_EQUAL(std::wstring{L"\"a\\fb\""}, Truncated("a\fb"));
        VERIFY_ARE_EQUAL(std::wstring{L"\"a\\bb\""}, Truncated("a\bb"));
        VERIFY_ARE_EQUAL(std::wstring{L"\"a\\ab\""}, Truncated("a\ab"));
    }

TEST_METHOD(FormatCommand_NonPrintableCharacters_AreEscapedAsHex)
    {
        // Control characters without a dedicated escape use \x, matching strconv.Quote.
        VERIFY_ARE_EQUAL(
            std::wstring{L"\"a\\x1bb\""},
            Truncated("a\x1b"
                      "b"));
        VERIFY_ARE_EQUAL(
            std::wstring{L"\"a\\x7fb\""},
            Truncated("a\x7f"
                      "b"));
    }

TEST_METHOD(FormatCommand_PrintableUnicode_IsNotEscaped)
    {
        // Letters and symbols stay verbatim, so only genuinely unprintable values are expanded.
        VERIFY_ARE_EQUAL(std::wstring{L"\"caf\u00E9\""}, Truncated("caf\xC3\xA9"));
    }

TEST_METHOD(FormatCommand_EscapesAreCountedAfterTruncation)
    {
        // Docker truncates before quoting, so escape expansion does not consume the display budget and the
        // quoted result is wider than the limit.
        VERIFY_ARE_EQUAL(std::wstring{L"\"\\n\\n\\n\\n\\n\""}, Truncated("\n\n\n\n\n"));
    }

TEST_METHOD(FormatMounts_LongNames_AreShortenedIndependently)
    {
        // Docker shortens every mount name to fifteen columns rather than the list as a whole
        // (ContainerContext.Mounts in cli/command/formatter/container.go).
        const auto mounts = "/var/lib/docker/volumes/data,logs,/mnt/c/users/test/source";
        VERIFY_ARE_EQUAL(std::wstring{L"/var/lib/docke\u2026,logs,/mnt/c/users/t\u2026"}, ContainerService::FormatMounts(mounts, true));
        VERIFY_ARE_EQUAL(wsl::shared::string::MultiByteToWide(mounts), ContainerService::FormatMounts(mounts, false));
    }

TEST_METHOD(FormatMounts_ShortNames_AreUnchanged)
    {
        VERIFY_ARE_EQUAL(std::wstring{L""}, ContainerService::FormatMounts("", true));
        VERIFY_ARE_EQUAL(std::wstring{L"data-volume"}, ContainerService::FormatMounts("data-volume", true));
        VERIFY_ARE_EQUAL(std::wstring{L"123456789012345"}, ContainerService::FormatMounts("123456789012345", true));
        VERIFY_ARE_EQUAL(std::wstring{L"12345678901234\u2026"}, ContainerService::FormatMounts("1234567890123456", true));
    }

TEST_METHOD(FormatMounts_WideCharacters_CountedAsTwoColumns)
    {
        // Seven wide characters occupy fourteen columns, so an eighth exceeds the fifteen column budget.
        std::string wide;
        for (int i = 0; i < 8; ++i)
        {
            wide += "\xE6\x97\xA5";
        }

        VERIFY_ARE_EQUAL(std::wstring(7, L'\u65E5') + L"\u2026", ContainerService::FormatMounts(wide, true));
    }

TEST_METHOD(FormatStatus_EmptyRuntimeStatus_JsonFallbackIsInvariant)
