void wsl::core::filesystem::CompactVhd(_In_ LPCWSTR Path)
{
    auto diskHandle = OpenVhd(Path, VIRTUAL_DISK_ACCESS_GET_INFO | VIRTUAL_DISK_ACCESS_METAOPS);

    COMPACT_VIRTUAL_DISK_PARAMETERS compact{};
    compact.Version = COMPACT_VIRTUAL_DISK_VERSION_1;

    THROW_IF_WIN32_ERROR(CompactVirtualDisk(diskHandle.get(), COMPACT_VIRTUAL_DISK_FLAG_NONE, &compact, nullptr));
}

HRESULT
wsl::windows::common::SvcComm::CompactDistribution(_In_ LPCGUID DistroGuid) const
{
    ClientExecutionContext context;
    RETURN_HR(m_userSession->CompactDistribution(DistroGuid, context.OutError()));
}

void WslCoreVm::TrimDistribution(_In_ ULONG Lun)
{
    auto lock = m_lock.lock_exclusive();

    LX_MINI_INIT_TRIM_DISTRIBUTION_MESSAGE message;
    message.Header.MessageSize = sizeof(message);
    message.Header.MessageType = LxMiniInitMessageTrimDistribution;
    message.ScsiLun = Lun;

    auto transaction = m_miniInitChannel.StartTransaction();
    transaction.Send(message);

    wsl::shared::SocketChannel channel{AcceptConnection(m_vmConfig.KernelBootTimeout), "TrimDistribution", {m_terminatingEvent.get()}};

    const auto& resultMessage = channel.ReceiveMessage<LX_MINI_INIT_TRIM_DISTRIBUTION_RESPONSE>();
    THROW_HR_IF(E_FAIL, resultMessage.ResponseCode != 0);
}

static std::wstring ExpectedUsageMessage()
    {
        std::wstring expectedUsageMessage;
        for (auto e : wsl::shared::Localization::MessageWslUsage())
        {
            if (e == L'\n')
            {
                expectedUsageMessage += L'\r';
            }

            expectedUsageMessage += e;
        }

        return expectedUsageMessage + L"\r\n";
    }

static void VerifyInvalidUsage(const std::wstring& Cmd)
    {
        auto [output, error] = LxsstuLaunchWslAndCaptureOutput(Cmd.c_str(), -1);
        VERIFY_ARE_EQUAL(ExpectedUsageMessage(), output);
        VERIFY_ARE_EQUAL(error, L"");
    }

models::ProgressMode GetProgressModeFromString(const std::wstring& input, const std::wstring& argName)
{
    static constexpr std::pair<std::wstring_view, models::ProgressMode> c_progressModes[] = {
        {L"auto", models::ProgressMode::Auto},
        {L"tty", models::ProgressMode::Tty},
        {L"plain", models::ProgressMode::Plain},
        {L"quiet", models::ProgressMode::Quiet},
    };

    for (const auto& [name, mode] : c_progressModes)
    {
        if (IsEqual(input, name))
        {
            return mode;
        }
    }

    std::wstring supportedValues;
    for (const auto& progressMode : c_progressModes)
    {
        if (!supportedValues.empty())
        {
            supportedValues += L", ";
        }

        supportedValues += progressMode.first;
    }

    throw ArgumentException(Localization::WSLCCLI_InvalidProgressTypeError(argName, input, supportedValues));
}

const wsl::windows::common::vt::Sequence& BuildImageCallback::Color(const wsl::windows::common::vt::Sequence& sequence) const
{
    static const wsl::windows::common::vt::Sequence empty{};
    return m_color ? sequence : empty;
}

void BuildImageCallback::CaptureForReplay(std::string_view text)
{
    m_allLines.emplace_back(text);
    m_allLinesBytes += m_allLines.back().size();
    while (m_allLinesBytes > c_maxAllLinesBytes && !m_allLines.empty())
    {
        m_allLinesBytes -= m_allLines.front().size();
        m_allLines.pop_front();
    }
}

std::wstring RunBuild(ProgressMode mode, bool vtEnabled, bool verbose = false)
    {
        CaptureTerminal capture(vtEnabled);
        wil::unique_event cancelEvent;
        cancelEvent.create(wil::EventOptions::ManualReset);

        {
            BuildImageCallback callback(capture.terminal, cancelEvent.get(), verbose, mode);

            VERIFY_SUCCEEDED(callback.OnProgress("#1 [1/2] FROM debian:latest\n", "", 0, 0));
            VERIFY_SUCCEEDED(callback.OnProgress("first log line\nsecond log line\n", "log", 0, 0));
            VERIFY_SUCCEEDED(callback.OnProgress("downloading 10%\rdownloading 80%\r", "log", 0, 0));
            VERIFY_SUCCEEDED(callback.OnProgress("sha256:abc downloading", "sha256:abc", 50, 100));
            VERIFY_SUCCEEDED(callback.OnProgress("#2 [2/2] RUN echo hi\n", "", 0, 0));
        }

        return capture.captured();
    }

std::wstring RunFailingBuild(ProgressMode mode, bool vtEnabled)
    {
        CaptureTerminal capture(vtEnabled);
        wil::unique_event cancelEvent;
        cancelEvent.create(wil::EventOptions::ManualReset);

        try
        {
            BuildImageCallback callback(capture.terminal, cancelEvent.get(), false, mode);

            VERIFY_SUCCEEDED(callback.OnProgress("#1 [1/2] FROM debian:latest\n", "", 0, 0));
            VERIFY_SUCCEEDED(callback.OnProgress("sha256:abc downloading", "sha256:abc", 50, 100));
            VERIFY_SUCCEEDED(callback.OnProgress("#2 [2/2] RUN exit 7\n", "", 0, 0));
            VERIFY_SUCCEEDED(callback.OnProgress("  | about-to-fail\n", "log", 0, 0));
            VERIFY_SUCCEEDED(callback.OnProgress("process \"/bin/sh -c exit 7\" did not complete successfully: exit code: 7\n", "", 0, 0));

            THROW_HR(E_FAIL);
        }
        catch (...)
        {
        }

        return capture.captured();
    }

