WSLC_TEST_METHOD(WSLCE2E_Image_Build_IidFile_NotWritable_Fails)
    {
        auto imageCleanup = DeleteImageOnExit(BuiltImageIidFileNotWritable);
        auto testRoot = std::filesystem::current_path() / L"wslc-e2e-build-iidfile-readonly";
        auto cleanup = SetupTestDirectory(testRoot);

        auto contextDir = SharedOutputBuildContext();

        auto dockerfilePath = testRoot / L"Dockerfile";
        WriteTestFileContent(dockerfilePath, "FROM debian:latest\n");

        // Pre-create the destination and deny write access so buildx cannot write the image ID to it.
        const auto iidFilePath = testRoot / L"image.id";
        WriteTestFileContent(iidFilePath, "original-content");
        SetPathAccess(iidFilePath, GENERIC_WRITE, DENY_ACCESS);

        // The deny ACE also blocks this test from reading the file back, so it must be revoked before
        // any assertion on the contents, and before cleanup can delete the file.
        auto restore = wil::scope_exit_log(WI_DIAGNOSTICS_INFO, [iidFilePath]() {
            SetPathAccess(iidFilePath, 0, REVOKE_ACCESS);
            DeleteFileW(iidFilePath.c_str());
        });

        auto buildResult = RunWslc(std::format(
            L"build \"{}\" -f \"{}\" -t {} --iidfile \"{}\"",
            contextDir.wstring(),
            dockerfilePath.wstring(),
            BuiltImageIidFileNotWritable.NameAndTag(),
            iidFilePath.wstring()));
        VERIFY_ARE_EQUAL(1u, buildResult.ExitCode.value_or(0u));
        VERIFY_IS_TRUE(buildResult.Stderr.has_value());
        VERIFY_IS_FALSE(buildResult.Stderr->empty());

        // buildx truncates the destination when it opens it, so the previous contents are not preserved.
        // What matters is that a failed write never leaves an image ID behind.
        SetPathAccess(iidFilePath, 0, REVOKE_ACCESS);
        const auto contents = ReadFileContent(iidFilePath.wstring());
        VERIFY_IS_FALSE(contents.starts_with(L"sha256:"), L"a failed iidfile write must not leave an image ID behind");
    }

static bool IsCliSessionName(std::wstring_view Name)
    {
        constexpr std::wstring_view prefix{wsl::windows::wslc::DefaultSessionName};

        return Name.size() >= prefix.size() && wsl::shared::string::IsEqual(Name.substr(0, prefix.size()), prefix, true) &&
               (Name.size() == prefix.size() || Name[prefix.size()] == L'-');
    }

static std::set<std::wstring> ListTestSessionNames(IWSLCSessionManager* SessionManager)
    {
        wil::unique_cotaskmem_array_ptr<WSLCSessionListEntry> sessions;
        VERIFY_SUCCEEDED(SessionManager->ListSessions(&sessions, sessions.size_address<ULONG>()));

        std::set<std::wstring> names;
        for (const auto& e : sessions)
        {
            if (IsCliSessionName(e.DisplayName))
            {
                continue;
            }

            auto [it, inserted] = names.emplace(e.DisplayName);
            VERIFY_IS_TRUE(inserted);
        }

        return names;
    }

bool AreEqual(const std::vector<IpAddress>& left, const std::vector<IpAddress>& right)
{
    return std::ranges::equal(
        left, right, [](const auto& leftAddress, const auto& rightAddress) { return AreEqual(leftAddress, rightAddress); });
}

bool AreEqual(const WslVirtioNetConfig& left, const WslVirtioNetConfig& right)
{
    return left.clientIp.value == right.clientIp.value && left.hasClientIpv6 == right.hasClientIpv6 &&
           std::equal(std::begin(left.clientIpv6.bytes), std::end(left.clientIpv6.bytes), std::begin(right.clientIpv6.bytes)) &&
           std::equal(std::begin(left.clientMac.bytes), std::end(left.clientMac.bytes), std::begin(right.clientMac.bytes)) &&
           left.gatewayIp.value == right.gatewayIp.value &&
           std::equal(std::begin(left.gatewayMac.bytes), std::end(left.gatewayMac.bytes), std::begin(right.gatewayMac.bytes)) &&
           std::equal(std::begin(left.gatewayMacIpv6.bytes), std::end(left.gatewayMacIpv6.bytes), std::begin(right.gatewayMacIpv6.bytes)) &&
           left.netmask.value == right.netmask.value;
}

void PluginManager::OnWslcVmStarted(const WSLCSessionInformation* Session) const
{
    WslcPluginNotificationContext context;

    for (const auto& e : m_plugins)
    {
        if (e.hooks.WslcVmStarted != nullptr)
        {
            const auto result = e.hooks.WslcVmStarted(Session);
            WSL_LOG(
                "PluginOnWslcVmStartedCall",
                TraceLoggingValue(e.name.c_str(), "Plugin"),
                TraceLoggingValue(Session->SessionId, "SessionId"),
                TraceLoggingValue(result, "Result"));
            LOG_IF_FAILED_MSG(result, "Error thrown from plugin: '%ls'", e.name.c_str());
        }
    }
}

void PluginManager::OnWslcVmStopping(const WSLCSessionInformation* Session) const
{
    WslcPluginNotificationContext context;

    for (const auto& e : m_plugins)
    {
        if (e.hooks.WslcVmStopping != nullptr)
        {
            const auto result = e.hooks.WslcVmStopping(Session);
            WSL_LOG(
                "PluginOnWslcVmStoppingCall",
                TraceLoggingValue(e.name.c_str(), "Plugin"),
                TraceLoggingValue(Session->SessionId, "SessionId"),
                TraceLoggingValue(result, "Result"));
            LOG_IF_FAILED_MSG(result, "Error thrown from plugin: '%ls'", e.name.c_str());
        }
    }
}

void WSLCContainerImpl::RecoverPorts(const common::docker_schema::ContainerInfo& dockerContainer)
{
    auto lock = m_lock.lock_exclusive();

    // Re-register VM-scoped port reservations against the restarted VM using the numbers recorded at
    // create time, restoring bridge-mode forwarding when the stopped container starts again.
    const bool allocateVmPorts = NetworkModeAllocatesVmPorts(m_networkMode);
    if (!allocateVmPorts)
    {
        return;
    }

    auto metadataIt = dockerContainer.Labels.find(WSLCContainerMetadataLabel);
    if (metadataIt == dockerContainer.Labels.end())
    {
        return;
    }

    auto metadata = ParseContainerMetadata(metadataIt->second.c_str());

    std::vector<ContainerPortMapping> ports;
    ports.reserve(metadata.Ports.size());
    for (const auto& e : metadata.Ports)
    {
        auto& inserted = ports.emplace_back(ContainerPortMapping{VMPortMapping::FromContainerMetaData(e), e.ContainerPort});

        auto allocation = m_runtime.Vm().TryAllocatePort(e.VmPort, e.Family, e.Protocol);

        THROW_HR_IF_MSG(
            HRESULT_FROM_WIN32(ERROR_ALREADY_EXISTS), !allocation, "Port %hu is in use, cannot recover container %hs", e.VmPort, m_id.c_str());

        inserted.VmMapping.AssignVmPort(allocation);
    }

    m_mappedPorts = std::move(ports);
}

void WSLCContainerImpl::UpdateActivityHoldLockHeld() noexcept
{
    const bool active = (m_state == WslcContainerStateRunning);
    if (active && !m_activityHold)
    {
        m_activityHold = ActivityRef(m_wslcSession.Runtime().IdleStateShared());
    }
    else if (!active && m_activityHold)
    {
        m_activityHold.reset();
    }
try
    auto vmLease = m_session.Runtime().AcquireVmLease();
CATCH_RETURN();
try

    auto vmLease = m_session.Runtime().AcquireVmLease();
CATCH_RETURN();
try
    // Hold a VM lease for the whole operation: --rm containers self-delete during Stop, which
    // disconnects the wrapper and drops activity. Without the lease, the idle worker can fire
    // during the post-stop destroy wait (up to 60s) and tear the VM down mid-call.
    auto vmLease = m_session.Runtime().AcquireVmLease();
CATCH_RETURN();
try
    // Hold a VM lease for the same reason as Stop(): --rm can self-delete and drop activity.
    auto vmLease = m_session.Runtime().AcquireVmLease();
CATCH_RETURN();
    auto vmLease = m_session.Runtime().AcquireVmLease();
try
    auto vmLease = m_session.Runtime().AcquireVmLease();
CATCH_RETURN();

    auto vmLease = m_session.Runtime().AcquireVmLease();
    // Hold a VM lease across the whole operation: deleting a container makes it inactive and
    // can trigger an idle teardown. Without the lease the idle worker could take the session
    // lock exclusively and clear m_containers (destroying this container) concurrently, racing
    // the delete and inverting the container->session lock order.
    auto vmLease = m_session.Runtime().AcquireVmLease();
try
    auto vmLease = m_session.Runtime().AcquireVmLease();
CATCH_RETURN();
try

    auto vmLease = m_session.Runtime().AcquireVmLease();
CATCH_RETURN();
try

    auto vmLease = m_session.Runtime().AcquireVmLease();
CATCH_RETURN();
    auto vmLease = m_session.Runtime().AcquireVmLease();
        m_runtime.Docker().ConnectContainerToNetwork(Options->NetworkName, request);
        m_runtime.Docker().DisconnectContainerFromNetwork(NetworkName, request);

    auto vmLease = m_session.Runtime().AcquireVmLease();

    auto vmLease = m_session.Runtime().AcquireVmLease();

void ValidateNewSessionStorageDirectory(const std::filesystem::path& StoragePath)
{
    // status's error_code distinguishes "doesn't exist yet" (OK, we'll create it) from other I/O errors.
    std::error_code ec;
    const auto status = std::filesystem::status(StoragePath, ec);
    if (ec && ec.value() != ERROR_FILE_NOT_FOUND && ec.value() != ERROR_PATH_NOT_FOUND)
    {
        THROW_IF_WIN32_ERROR_MSG(ec.value(), "status failed for %ls", StoragePath.c_str());
    }

    if (!std::filesystem::exists(status))
    {
        return;
    }

    THROW_HR_WITH_USER_ERROR_IF(
        E_INVALIDARG, Localization::MessageWslcSessionStorageMustBeDirectory(StoragePath.c_str()), !std::filesystem::is_directory(status));

    const bool empty = std::filesystem::is_empty(StoragePath, ec);
    THROW_IF_WIN32_ERROR_MSG(ec.value(), "is_empty failed for %ls", StoragePath.c_str());
    THROW_HR_WITH_USER_ERROR_IF(E_INVALIDARG, Localization::MessageWslcSessionStorageMustBeEmpty(StoragePath.c_str()), !empty);
}

void WSLCSession::PersistSettings(const WSLCSessionInitSettings& Settings, PSID UserSid)
{
    m_settings = Settings;

    // Repoint the string fields at storage owned by the session so they outlive the caller's buffers.
    m_settings.DisplayName = m_displayName.c_str();

    if (Settings.CreatorProcessName != nullptr)
    {
        m_settingsCreatorProcessName = Settings.CreatorProcessName;
        m_settings.CreatorProcessName = m_settingsCreatorProcessName->c_str();
    }
    else
    {
        m_settings.CreatorProcessName = nullptr;
    }

    if (Settings.StoragePath != nullptr)
    {
        m_settingsStoragePath = Settings.StoragePath;
        m_settings.StoragePath = m_settingsStoragePath->c_str();
    }
    else
    {
        m_settings.StoragePath = nullptr;
    }

    if (Settings.RootVhdTypeOverride != nullptr)
    {
        m_settingsRootVhdTypeOverride = Settings.RootVhdTypeOverride;
        m_settings.RootVhdTypeOverride = m_settingsRootVhdTypeOverride->c_str();
    }
    else
    {
        m_settings.RootVhdTypeOverride = nullptr;
    }

    THROW_HR_IF(E_UNEXPECTED, UserSid == nullptr);

    const auto length = GetLengthSid(UserSid);
    const auto* bytes = reinterpret_cast<const BYTE*>(UserSid);
    m_userSid.assign(bytes, bytes + length);
}

~ContainerOperation() override
        {
            if (m_onRelease)
            {
                m_onRelease();
            }
        }

Microsoft::WRL::ComPtr<IUnknown> WSLCSession::CreateActivityToken()
{
    // Record the in-flight activity up front so the VM cannot idle-terminate before the caller
    // takes ownership of the returned token.
    m_runtime.Idle().AddActivity();
    auto countCleanup = wil::scope_exit([this]() { m_runtime.Idle().ReleaseActivity(); });

    auto operation = Microsoft::WRL::Make<ContainerOperation>();
    THROW_IF_NULL_ALLOC(operation.Get());

    // Capture shared idle state so token can outlive session and release activity without keeping session alive.
    std::shared_ptr<IdleState> idleState = m_runtime.IdleStateShared();
    operation->Initialize([idleState = std::move(idleState)]() { idleState->ReleaseActivity(); });

    // The token now owns the activity-count reference and will release it on destruction.
    countCleanup.release();

    Microsoft::WRL::ComPtr<IUnknown> token;
    THROW_IF_FAILED(operation.As(&token));
    return token;
}

void WSLCSessionRuntime::Initialize(
    DWORD vmFactoryGitCookie,
    wil::com_ptr<IGlobalInterfaceTable> git,
    const WSLCSessionInitSettings* settings,
    std::chrono::milliseconds idleGrace,
    SessionContext sessionContext,
    RuntimeHooks hooks)
{
    m_vmFactoryGitCookie = vmFactoryGitCookie;
    m_git = std::move(git);
    m_settings = settings;
    m_id = sessionContext.Id;
    m_displayName = std::move(sessionContext.DisplayName);
    m_terminating = sessionContext.Terminating;
    m_sessionTerminatingEvent = sessionContext.SessionTerminatingEvent;
    m_sessionTerminatedEvent = sessionContext.SessionTerminatedEvent;
    m_hooks = std::move(hooks);

    m_idleState->Initialize(idleGrace, [this]() { OnIdleTimer(); });

    // Session-scoped: subscriptions must survive VM restarts. Rebound per-VM in InitializeDockerRuntime.
    m_eventTracker.emplace(*m_session);

    m_initialized = true;
}

