bool WSLCSessionRuntime::IdleTerminationEnabled() const noexcept
{
    // Only tear the VM down when there is persistent storage to recover from. A tmpfs-backed
    // session would lose all image/container state on teardown, so its VM is kept alive once started.
    return m_settings->StoragePath != nullptr;
}

int WSLCSessionRuntime::StopProcess(ServiceRunningProcess& Process, DWORD TerminateTimeoutMs, DWORD KillTimeoutMs)
{
    auto signalResult = Process.Get().Signal(WSLCSignalSIGTERM);
    if (FAILED(signalResult))
    {
        LOG_HR_MSG(signalResult, "Failed to terminate process %i", Process.Get().GetPid());
        return -1;
    }

    try
    {
        return Process.Wait(TerminateTimeoutMs);
    }
    catch (...)
    {
        LOG_CAUGHT_EXCEPTION();
        try
        {
            LOG_IF_FAILED(Process.Get().Signal(WSLCSignalSIGKILL));
            return Process.Wait(KillTimeoutMs);
        }
        CATCH_LOG();
    }

    return -1;
}

void WSLCSessionRuntime::EnsureVmRunning()
{
    // Reject leases once the session is terminating/terminated, including on the running fast path:
    // Shutdown() drops the lock to fire OnVmStopping, and a reentrant lease that finds the VM still
    // Running must fail here rather than run work against a VM being permanently torn down.
    THROW_HR_IF(HRESULT_FROM_WIN32(ERROR_INVALID_STATE), m_terminating->load() || m_sessionTerminatedEvent.is_signaled());

    if (m_vmState.load() == VmState::Running)
    {
        return;
    }

    bool started = false;
    uint64_t generation = 0;
    {
        auto lock = m_lock.lock_exclusive();

        // Re-check under the lock: terminating may have been set since the check above. This also
        // bounds VmLease's retry loop: a lease that races with Terminate() fails here instead of
        // restarting a VM that is being permanently torn down.
        THROW_HR_IF(HRESULT_FROM_WIN32(ERROR_INVALID_STATE), m_terminating->load() || m_sessionTerminatedEvent.is_signaled());

        if (m_vmState.load() != VmState::Running)
        {
            StartVmLockHeld();
            started = true;
        }

        generation = m_vmGeneration.load();
    }

    // Notify plugins that a VM has started, outside the exclusive lock: the handler forwards to the
    // plugin, which may call back into the session (e.g. WSLCCreateProcess acquires a VM lease and
    // the exclusive lock), so firing under the lock would deadlock. EnsureVmRunning's only caller
    // (VmLease) holds an activity reference across this call, so idle teardown cannot race the VM
    // down in the gap between releasing the lock and notifying.
    if (started)
    {
        NotifyVmStarted(generation);
    }
}

void WSLCSessionRuntime::NotifyVmStarted(uint64_t Generation)
{
    // Hold m_notifyLock across both the pairing-state flip and the hook invocation, so a concurrent
    // NotifyVmStopping on another thread cannot deliver its OnVmStopping in between and observe this
    // OnVmStarted arrive late (which would otherwise leave the plugin with a trailing "started" for a
    // VM that already stopped). m_notifyLock is recursive: the handler may reentrantly restart the VM
    // (e.g. WSLCCreateProcess -> NotifyVmStarted/Stopping) on this same thread, which would self-deadlock
    // under a plain mutex. Suppressed once terminating, else a racing Shutdown leaves OnVmStarted unpaired.
    // m_notifiedGeneration tracks the VM lifecycle, not whether OnVmStarted is installed, so a hooks
    // user that sets only OnVmStopping still gets paired stop notifications.
    auto lock = std::lock_guard(m_notifyLock);

    // Drop the notification if this instance is already gone: between releasing the runtime lock and
    // getting here it may have been torn down and replaced, and announcing it now would misattribute
    // the start to whichever instance is running.
    if (m_terminating->load() || m_vmGeneration.load() != Generation)
    {
        return;
    }

    m_notifiedGeneration.store(Generation);
    if (m_hooks.OnVmStarted)
    {
        m_hooks.OnVmStarted();
    }
}

void WSLCSessionRuntime::NotifyVmStopping(uint64_t Generation)
{
    // See NotifyVmStarted: hold m_notifyLock across both the pairing check and the hook invocation, so
    // the two notifications cannot interleave across threads. Recursive because the handler may
    // reentrantly restart the VM and call NotifyVmStarted on this same thread.
    //
    // N.B. The CAS below retires the generation as the stop is announced, so a second stop for the
    // same VM (e.g. Terminate() racing an idle teardown that has dropped the lock across its
    // notification) cannot deliver OnVmStopping twice. This is safe because the stop is committed
    // before it is announced: the VM cannot come back, so nothing needs the generation afterwards.
    //
    // Generation 0 is the sentinel for "no VM has been announced": both counters start there, so a
    // session that is torn down without ever starting a VM must not match, or Shutdown would deliver
    // an OnVmStopping that no OnVmStarted ever paired with.
    auto lock = std::lock_guard(m_notifyLock);

    auto expected = Generation;
    if (Generation != 0 && m_notifiedGeneration.compare_exchange_strong(expected, 0) && m_hooks.OnVmStopping)
    {
        m_hooks.OnVmStopping();
    }
}

void WSLCSessionRuntime::BeginVmStopLockHeld() noexcept
{
    // Reset before publishing the flag, so a lease cannot observe the pending stop while the event is
    // still signaled from the previous teardown.
    m_vmStopCompleteEvent.ResetEvent();
    m_vmStopPending.store(true);
}

void WSLCSessionRuntime::EndVmStop() noexcept
{
    m_vmStopPending.store(false);
    m_vmStopCompleteEvent.SetEvent();
}

bool WSLCSessionRuntime::TryClaimExpectedStop() noexcept
{
    auto expected = VmExitDisposition::Active;
    return m_vmExitDisposition.compare_exchange_strong(expected, VmExitDisposition::StopRequested);
}

bool WSLCSessionRuntime::TryClaimSpontaneousExit() noexcept
{
    auto expected = VmExitDisposition::Active;
    return m_vmExitDisposition.compare_exchange_strong(expected, VmExitDisposition::ExitClaimed);
}

void WSLCSessionRuntime::StartVmLockHeld()
{
    WI_ASSERT(m_vmState.load() != VmState::Running);

    WSL_LOG("WslcVmStarting", TraceLoggingValue(m_id, "SessionId"));

    m_vmState.store(VmState::Starting);
    m_vmExitDisposition.store(VmExitDisposition::Active);

    // Identify this instance. Bumped under the runtime lock so a notification that had to drop the
    // lock to fire can tell whether it still describes the VM it was raised for. The first VM is
    // generation 1, so the 0 stored by TearDownVmLockHeld never collides with a live instance.
    m_vmGeneration.fetch_add(1);

    // Tear back down if bring-up fails partway. The VM may have exited on its own during bring-up,
    // so claim the stop first and only tear down if we win it (TryClaimExpectedStop()); otherwise
    // OnVmExited() owns the teardown and we just release the lock to let its Terminate() finish.
    auto startCleanup = wil::scope_exit_log(WI_DIAGNOSTICS_INFO, [&]() {
        if (TryClaimExpectedStop())
        {
            TearDownVmLockHeld();
            m_vmState.store(VmState::None);
        }
        else
        {
            WSL_LOG("WslcVmExitedDuringStart", TraceLoggingValue(m_id, "SessionId"));
        }
    });

    // Create a fresh IO relay for this VM instance. The previous one (if any) was stopped
    // during teardown and cannot be restarted.
    m_ioRelay.emplace();

    // Create the VM via the factory. Re-fetch the factory from the GIT so we call it through a
    // proxy marshalled into this thread's apartment (see m_git). The VM produces crash events;
    // the session multiplexes them out to any registered ICrashDumpCallback subscribers via
    // OnCrashDumpWritten.
    wil::com_ptr<IWSLCVirtualMachineFactory> vmFactory;
    THROW_IF_FAILED(m_git->GetInterfaceFromGlobal(m_vmFactoryGitCookie, __uuidof(IWSLCVirtualMachineFactory), vmFactory.put_void()));

    wil::com_ptr<IWSLCVirtualMachine> vm;
    THROW_IF_FAILED(vmFactory->CreateVirtualMachine(&vm));

    m_virtualMachine.emplace(vm.get(), m_settings, m_sessionTerminatingEvent.get(), WSLCVirtualMachine::TOnCrashDump(m_hooks.OnCrashDump));

    // Publish only once the object is constructed. If Initialize() below throws, startCleanup tears
    // the VM down and clears this again.
    m_hasVm.store(true);

    m_virtualMachine->Initialize();

    // Get an event from the service that is signaled when the VM exits.
    m_vmExitedEvent.reset();
    THROW_IF_FAILED(vm->GetTerminationEvent(&m_vmExitedEvent));
    m_vmExited.store(false);

    if (m_hooks.BringUp)
    {
        m_hooks.BringUp();
    }

    // Monitor for unexpected VM exit.
    m_ioRelay->AddHandle(
        std::make_unique<windows::common::io::EventHandle>(m_vmExitedEvent.get(), std::bind(&WSLCSessionRuntime::OnVmExited, this)));

    if (m_hooks.RecoverState)
    {
        m_hooks.RecoverState();
    }

    m_vmState.store(VmState::Running);
    startCleanup.release();

    WSL_LOG("WslcVmStarted", TraceLoggingValue(m_id, "SessionId"));
}

void WSLCSessionRuntime::InitializeDockerRuntime(const std::filesystem::path& storagePath)
{
    // Wait for dockerd to be ready before starting the event tracker.
    THROW_WIN32_IF_MSG(
        ERROR_TIMEOUT, !m_dockerdReadyEvent.wait(m_settings->BootTimeoutMs), "Timed out waiting for dockerd to start");

    [[maybe_unused]] auto [pid, ptyMaster, channel] = m_virtualMachine->Fork(WSLC_FORK::Thread);

    m_dockerClient.emplace(std::move(channel), m_virtualMachine->TerminatingEvent(), m_virtualMachine->VmId(), 10 * 1000);

    // (Re)bind the session-scoped event tracker to this VM's docker client and relay. Existing
    // container subscriptions are preserved across restarts.
    m_eventTracker->Connect(m_dockerClient.value(), *m_ioRelay);

    m_volumes.emplace(m_dockerClient.value(), m_virtualMachine.value(), m_eventTracker.value(), storagePath);
}

void WSLCSessionRuntime::StopVmLockHeld()
{
    if (m_vmState.load() != VmState::Running)
    {
        return;
    }

    WSL_LOG("WslcVmIdleStop", TraceLoggingValue(m_id, "SessionId"));

    // N.B. The caller has claimed StopRequested (via TryClaimExpectedStop), so VM/dockerd/containerd
    // exit callbacks firing from the relay thread during teardown are treated as expected, not as a
    // crash.
    m_vmState.store(VmState::Stopping);

    TearDownVmLockHeld();

    m_vmState.store(VmState::None);
}

void WSLCSessionRuntime::TearDownVmLockHeld(bool CaptureTerminationReason)
{
    // The VM is committed to going away from here on, so the plugin's view of it ends here. Retiring
    // the notified instance up front, before any step below can throw, also covers the case where the
    // VM is torn down without an OnVmStopping ever being announced (e.g. bring-up failed). Written
    // under the runtime lock; NotifyVmStarted/NotifyVmStopping read it under m_notifyLock without the
    // runtime lock, so this store can land while one of them is inside a plugin handler. That is
    // benign: both compare against a generation they captured earlier, so a store of 0 can only make
    // them decline to notify, and by this point either the stop has already been announced (its CAS
    // ran first) or the instance is gone and must not be announced at all.
    m_notifiedGeneration.store(0);

    // Latch whether the guest is already dead before running session-state cleanup so container
    // teardown (ReleaseRuntimeResources) can skip VM-dependent calls, e.g. volume unmounts, on a VM
    // that has exited. A graceful stop reaches here with the VM still alive (is_signaled() false), so
    // its mounts are unmounted through the live VM; StartVmLockHeld clears this for the next instance.
    if (m_vmExitedEvent && m_vmExitedEvent.is_signaled())
    {
        m_vmExited.store(true);
    }

    if (m_hooks.TearDownSessionState)
    {
        m_hooks.TearDownSessionState(CaptureTerminationReason);
    }

    m_volumes.reset();

    // Stop the IO relay.
    // This stops:
    // - container state monitoring.
    // - container init process relays
    // - execs relays
    // - container logs relays
    if (m_ioRelay)
    {
        m_ioRelay->Stop();
    }

    {
        std::lock_guard allocatedPortsLock(m_allocatedPortsLock);
        m_allocatedPorts.clear();
    }

    // The session-scoped event tracker is intentionally not reset. Its stream handle dies with the IO
    // relay above, and InitializeDockerRuntime re-binds it on the next start.
    m_dockerClient.reset();

    if (CaptureTerminationReason)
    {
        // Default: an explicit/graceful teardown is a shutdown (the VM is still alive and we are
        // bringing it down). Overridden below if the VM exited on its own and recorded a cause.
        m_lastTerminationReason = WSLCVirtualMachineTerminationReasonShutdown;
        m_lastTerminationDetails.clear();
    }

    // Check if the VM has already exited (e.g., killed externally).
    // If so, skip operations that require a live VM to avoid unnecessary waits.
    // N.B. m_vmExitedEvent may be uninitialized if teardown runs before GetTerminationEvent() succeeds.
    if (m_vmExitedEvent && m_vmExitedEvent.is_signaled())
    {
        WSL_LOG("SkippingGracefulShutdown_VmDead", TraceLoggingValue(m_id, "SessionId"));

        // The VM exited on its own, so it recorded the cause.
        if (CaptureTerminationReason && m_virtualMachine)
        {
            wil::unique_cotaskmem_string details;
            LOG_IF_FAILED(m_virtualMachine->GetTerminationReason(&m_lastTerminationReason, &details));
            m_lastTerminationDetails = details ? details.get() : L"";
        }
    }
    else if (m_virtualMachine)
    {
        m_virtualMachine->OnSessionTerminated();

        // Stop dockerd first, then containerd (dockerd is a client of containerd).
        // N.B. dockerd waits a couple seconds if there are any outstanding HTTP request sockets opened.
        if (m_dockerdProcess.has_value())
        {
            auto dockerdExitCode = StopProcess(m_dockerdProcess.value(), c_processTerminateTimeoutMs, c_processKillTimeoutMs);
            WSL_LOG("DockerdExit", TraceLoggingValue(dockerdExitCode, "code"));
        }

        if (m_containerdProcess.has_value())
        {
            auto containerdExitCode = StopProcess(m_containerdProcess.value(), c_processTerminateTimeoutMs, c_processKillTimeoutMs);
            WSL_LOG("ContainerdExit", TraceLoggingValue(containerdExitCode, "code"));
        }

        // N.B. dockerd has exited by this point, so unmounting the VHD is safe since no container can be running.
        if (m_storageMounted)
        {
            try
            {
                m_virtualMachine->Unmount(c_containerdStorage);
            }
            CATCH_LOG();
        }
    }

    m_dockerdProcess.reset();
    m_containerdProcess.reset();

    // Retire the lock-free mirror before destroying the object so an unlocked reader never sees
    // "a VM is present" while it is being torn down.
    m_hasVm.store(false);
    m_virtualMachine.reset();
    m_storageMounted = false;

    // Destroy the relay unless we're on its own thread (~IORelay joins the thread, which would
    // deadlock). On unexpected-VM-exit path (runs on relay thread), leave it for ~WSLCSession.
    if (!m_ioRelay || !m_ioRelay->IsRelayThread())
    {
        m_ioRelay.reset();
        m_vmExitedEvent.reset();
    }

    // Delete the ephemeral swap VHD now that the VM is gone.
    if (!m_swapVhdPath.empty())
    {
        LOG_IF_WIN32_BOOL_FALSE(DeleteFileW(m_swapVhdPath.c_str()));
        m_swapVhdPath.clear();
    }
}

bool WSLCSessionRuntime::TriggerIdleTerminationForTest()
{
    // Mirror OnIdleTimer's MTA context on a dedicated thread: the incoming RPC thread is an STA, so
    // both re-initializing MTA on it and running teardown inline would fail (RPC_E_CHANGED_MODE /
    // RPC_E_WRONG_THREAD when releasing the VM's cross-process COM proxies).
    bool wasAlreadyIdle = false;
    std::exception_ptr error;

    std::thread worker([&]() {
        try
        {
            const auto coInit = wil::CoInitializeEx(COINIT_MULTITHREADED);

            auto lock = m_lock.lock_exclusive();

            if (m_terminating->load() || m_vmState.load() != VmState::Running)
            {
                wasAlreadyIdle = true;
                return;
            }

            // tmpfs sessions have no persistent storage to recover from, so tearing a running VM down
            // loses all state. Check this after the VM state so a never-started session still reports
            // that it was already idle.
            if (!IdleTerminationEnabled())
            {
                return;
            }

            // Match the production idle timer: an active container or operation keeps the VM alive.
            if (m_idleState->ActivityCount() != 0)
            {
                return;
            }

            if (!TryClaimExpectedStop())
            {
                wasAlreadyIdle = true;
                return;
            }

            auto dispositionCleanup = wil::scope_exit([this]() {
                auto stopRequested = VmExitDisposition::StopRequested;
                m_vmExitDisposition.compare_exchange_strong(stopRequested, VmExitDisposition::Active);
            });

            // Mirror OnIdleTimer's final re-check under the lock: a lease taken while the stop claim
            // was being made is now blocked on the lock we hold, and must back the teardown out here
            // rather than announce a stop production code would have suppressed.
            if (m_idleState->ActivityCount() != 0)
            {
                return;
            }

            // Commit to the stop before announcing it, then fire OnVmStopping without holding m_lock
            // and tear down unconditionally. See OnIdleTimer for the full rationale.
            BeginVmStopLockHeld();
            auto endStop = wil::scope_exit([this]() { EndVmStop(); });

            const auto generation = m_vmGeneration.load();

            lock.reset();
            try
            {
                NotifyVmStopping(generation);
            }
            CATCH_LOG();
            lock = m_lock.lock_exclusive();

            StopVmLockHeld();
        }
        catch (...)
        {
            error = std::current_exception();
        }
    });

    worker.join();

    if (error)
    {
        std::rethrow_exception(error);
    }

    return wasAlreadyIdle;
}

WSLCSessionRuntime::VmLease::VmLease(WSLCSessionRuntime& Runtime, VmLeasePolicy Policy) : m_runtime(&Runtime)
{
    // Record an in-flight operation before bringing the VM up so idle teardown cannot tear it down
    // between EnsureVmRunning() and acquiring the shared lock. AddActivity cancels any pending idle
    // timer.
    m_runtime->m_idleState->AddActivity();

    auto countCleanup = wil::scope_exit([this]() {
        m_runtime->m_idleState->ReleaseActivity();
        m_runtime = nullptr;
    });

    // Activity increment may race with idle teardown. Retry until we hold the lock with VM running.
    for (;;)
    {
        if (Policy == VmLeasePolicy::Acquire)
        {
            m_runtime->EnsureVmRunning();
        }

        m_lock = m_runtime->m_lock.lock_shared();

        if (m_runtime->m_vmState.load() == VmState::Running)
        {
            // An announced stop always happens, so a VM with one pending is unusable even though it is
            // still Running: wait for the teardown, then retry, which brings up a fresh VM. ExistingOnly
            // callers are exempt and are served by the stopping VM -- see VmLeasePolicy.
            if (Policy == VmLeasePolicy::ExistingOnly || !m_runtime->m_vmStopPending.load())
            {
                break;
            }

            // Release the shared lock before waiting. The teardown must be able to take the exclusive
            // lock, and it is the only thing that will ever signal us.
            m_lock.reset();

            // The wait is bounded only so that a handler wedging the teardown is visible in traces;
            // there is no correct way to proceed without a VM, so the retry is unconditional.
            while (!m_runtime->m_vmStopCompleteEvent.wait(c_vmStopWaitLogIntervalMs))
            {
                WSL_LOG(
                    "WslcVmLeaseWaitingForStop",
                    TraceLoggingLevel(WINEVENT_LEVEL_WARNING),
                    TraceLoggingValue(m_runtime->m_id, "SessionId"));
            }

            continue;
        }

        // ExistingOnly never starts a VM, so retrying could only spin. Reject the caller instead.
        THROW_HR_IF(WSLC_E_VM_NOT_RUNNING, Policy == VmLeasePolicy::ExistingOnly);

        WSL_LOG(
            "WslcVmLeaseRetry",
            TraceLoggingValue(m_runtime->m_id, "SessionId"),
            TraceLoggingValue(static_cast<uint32_t>(m_runtime->m_vmState.load()), "VmState"));
        m_lock.reset();
    }

    countCleanup.release();
}

WSLCSessionRuntime::VmLease& WSLCSessionRuntime::VmLease::operator=(VmLease&& Other) noexcept
{
    if (this != &Other)
    {
        if (m_runtime != nullptr)
        {
            // Release the shared lock before the activity reference so that, if this was the last
            // activity, idle teardown can immediately take the exclusive lock.
            m_lock.reset();
            m_runtime->m_idleState->ReleaseActivity();
        }

        m_runtime = std::exchange(Other.m_runtime, nullptr);
        m_lock = std::move(Other.m_lock);
    }

    return *this;
}

WSLCSessionRuntime::VmLease::~VmLease()
{
    if (m_runtime != nullptr)
    {
        // Release the shared lock before the activity reference so that, if this was the last
        // activity, idle teardown can immediately take the exclusive lock. ReleaseActivity arms the
        // idle timer on the 1->0 transition.
        m_lock.reset();
        m_runtime->m_idleState->ReleaseActivity();
    }
}

void WSLCSessionRuntime::OnVmExited()
{
    // A spontaneous exit we must permanently terminate, unless an expected stop already claimed it,
    // in which case the exit was wanted and we decline.
    if (!TryClaimSpontaneousExit())
    {
        WSL_LOG("WslcVmExitedDuringStop", TraceLoggingValue(m_id, "SessionId"));
        return;
    }

    WSL_LOG(
        "VmExited",
        TraceLoggingLevel(WINEVENT_LEVEL_WARNING),
        TraceLoggingValue(m_id, "SessionId"),
        TraceLoggingValue(m_displayName.c_str(), "Name"),
        TraceLoggingValue(!m_sessionTerminatingEvent.is_signaled(), "Unexpected"));

    if (m_hooks.OnSpontaneousExit)
    {
        m_hooks.OnSpontaneousExit();
    }
}

void WSLCSessionRuntime::Shutdown(
    wil::rwlock_release_exclusive_scope_exit& runtimeLock, WSLCVirtualMachineTerminationReason& terminationReason, std::wstring& terminationDetails)
{
    if (!m_initialized)
    {
        return;
    }

    // runtimeLock is an exclusive hold on m_lock, guaranteeing no operation is running.
    WI_VERIFY(runtimeLock);

    // Permanently disable idle teardown and drain any in-flight timer callback on every exit path,
    // including an exception escaping the teardown below. The timer callback captures this runtime,
    // but IdleState outlives it (activity tokens hold shared_ptr copies), so skipping the disarm
    // would leave a late 1->0 transition able to re-arm a timer that references freed memory.
    //
    // The exclusive lock is released first: a timer callback already blocked acquiring it must be
    // able to obtain it, observe m_terminating, and return, otherwise the drain below deadlocks.
    auto disarmIdleState = wil::scope_exit([&]() {
        runtimeLock.reset();
        m_idleState->Disarm();
    });

    // Notify with m_lock dropped, then re-lock for the teardown. The handler may call back into the
    // session (e.g. WSLCCreateProcess) which takes a VM lease and this lock; firing under it would
    // deadlock. m_terminating is set, so any such reentrant lease fails at EnsureVmRunning's gate
    // rather than restarting the VM, and the reacquire can't block on it. A throwing handler must not
    // skip the teardown below -- the session is terminating either way.
    runtimeLock.reset();
    try
    {
        NotifyVmStopping(m_vmGeneration.load());
    }
    CATCH_LOG();
    runtimeLock = m_lock.lock_exclusive();

    // Tear down the VM (if running) and all VM-scoped state, capturing the termination reason; the
    // reacquired exclusive hold on m_lock satisfies TearDownVmLockHeld's precondition.
    TearDownVmLockHeld(/* CaptureTerminationReason */ true);

    m_vmState.store(VmState::None);

    terminationReason = m_lastTerminationReason;
    terminationDetails = m_lastTerminationDetails;

    // Signal completion last so any observer of the terminated event sees a fully torn-down
    // session and a populated termination reason.
    m_sessionTerminatedEvent.SetEvent();
}

WSL2_TEST_METHOD(WslcVmRestart)
    {
        ConfigurePlugin(PluginTestType::WslcVmRestart);

        // Idle termination only tears down storage-backed sessions (tmpfs state is unrecoverable), so
        // this restart lifecycle test needs a dedicated persistent storage directory.
        const auto storageDir = std::filesystem::current_path() / "test-storage-wslc-vm-restart";
        std::error_code storageError;
        std::filesystem::remove_all(storageDir, storageError);
        std::filesystem::create_directories(storageDir);
        auto storageCleanup = wil::scope_exit([&]() {
            std::error_code ec;
            std::filesystem::remove_all(storageDir, ec);
        });

        {
            auto session = CreateWslcSession(L"plugin-wslc-vm-restart", WSLCNetworkingModeNone, storageDir.c_str());

            // First operation brings the VM up -> OnWslcVmStarted (which reentrantly runs a process).
            {
                wsl::windows::common::WSLCProcessLauncher launcher("/bin/sleep", {"/bin/sleep", "60"});
                auto process = launcher.Launch(*session);
            }

            // Force idle teardown of the running VM -> OnWslcVmStopping.
            BOOL wasAlreadyIdle = TRUE;
            VERIFY_SUCCEEDED(session->TriggerIdleTermination(&wasAlreadyIdle));
            VERIFY_IS_FALSE(wasAlreadyIdle);

            // Next operation lazily restarts the VM -> OnWslcVmStarted fires again.
            {
                wsl::windows::common::WSLCProcessLauncher launcher("/bin/sleep", {"/bin/sleep", "60"});
                auto process = launcher.Launch(*session);
            }

            // Session teardown tears the second VM down -> OnWslcVmStopping, then OnWslcSessionStopping.
        }

        constexpr auto ExpectedOutput =
            LR"(Plugin loaded. TestMode=22
            WSLC Session created, name=plugin-wslc-vm-restart, id=*, pid=*, token=set, sid=set
            WSLC VM started, session=*
            WSLC VM started reentrant WSLCCreateProcess: ok
            WSLC VM started mount+unmount: ok
            WSLC VM stopping, session=*
            WSLC VM stopping reentrant WSLCCreateProcess: ok
            WSLC VM stopping mount+unmount: ok
            WSLC VM started, session=*
            WSLC VM started reentrant WSLCCreateProcess: ok
            WSLC VM started mount+unmount: ok
            WSLC VM stopping, session=*
            WSLC VM stopping reentrant WSLCCreateProcess: failed
            WSLC VM stopping mount+unmount: skipped
            WSLC Session stopping, name=plugin-wslc-vm-restart, id=*)";

        ValidateLogFile(ExpectedOutput);
    }

WSL2_TEST_METHOD(WslcVmStopCommitted)
    {
        ConfigurePlugin(PluginTestType::WslcVmStopCommitted);

        // Idle termination only tears down storage-backed sessions (see WslcVmRestart).
        const auto storageDir = std::filesystem::current_path() / "test-storage-wslc-vm-stop-committed";
        std::error_code storageError;
        std::filesystem::remove_all(storageDir, storageError);
        std::filesystem::create_directories(storageDir);
        auto storageCleanup = wil::scope_exit([&]() {
            std::error_code ec;
            std::filesystem::remove_all(storageDir, ec);
        });

        {
            auto session = CreateWslcSession(L"plugin-wslc-vm-stop-committed", WSLCNetworkingModeNone, storageDir.c_str());

            // Bring the VM up -> OnWslcVmStarted.
            {
                wsl::windows::common::WSLCProcessLauncher launcher("/bin/sleep", {"/bin/sleep", "60"});
                auto process = launcher.Launch(*session);
            }

            // The teardown is announced and then carried out, even though the plugin's callback left a
            // process running. The session is genuinely idle afterwards.
            BOOL wasAlreadyIdle = TRUE;
            VERIFY_SUCCEEDED(session->TriggerIdleTermination(&wasAlreadyIdle));
            VERIFY_IS_FALSE(wasAlreadyIdle);

            // The VM is gone, so this starts a fresh one -> a second OnWslcVmStarted.
            {
                wsl::windows::common::WSLCProcessLauncher launcher("/bin/sleep", {"/bin/sleep", "60"});
                auto process = launcher.Launch(*session);
            }
        }

        // "leaked process died: yes" is the assertion that the announced stop actually happened: the
        // process the callback left running was killed by the teardown rather than keeping the VM
        // alive. "stop-window caller: ok" shows a plugin call from another thread was served by the
        // stopping VM instead of deadlocking against the teardown that callback was holding up. Both
        // are reported when that thread is joined, at session teardown.
        constexpr auto ExpectedOutput =
            LR"(Plugin loaded. TestMode=23
            WSLC Session created, name=plugin-wslc-vm-stop-committed, id=*, pid=*, token=set, sid=set
            WSLC VM started, session=*
            WSLC VM stopping, session=*
            WSLC VM stopping leaked process: ok
            WSLC VM started, session=*
            WSLC stop-window caller: ok
            WSLC leaked process died: yes
            WSLC Session stopping, name=plugin-wslc-vm-stop-committed, id=*)";

        ValidateLogFile(ExpectedOutput);
    }

WSL2_TEST_METHOD(WslcVmNeverStarted)
    {
        ConfigurePlugin(PluginTestType::WslcVmNeverStarted);

        // A session whose VM is never needed. VM bring-up is lazy, so creating and destroying the
        // session must not produce either VM notification: OnWslcVmStopping is documented to fire
        // exactly once per OnWslcVmStarted, and a stop for a VM that never existed would break the
        // pairing every plugin relies on to track VM lifetime. The plugin also issues a call from
        // OnWslcSessionCreated, which must be rejected rather than bring a VM up.
        {
            auto session = CreateWslcSession(L"plugin-wslc-vm-never-started");
            VERIFY_IS_NOT_NULL(session.get());
        }

        constexpr auto ExpectedOutput =
            LR"(Plugin loaded. TestMode=24
            WSLC Session created, name=plugin-wslc-vm-never-started, id=*, pid=*, token=set, sid=set
            WSLC no-vm caller: rejected
            WSLC Session stopping, name=plugin-wslc-vm-never-started, id=*)";

        ValidateLogFile(ExpectedOutput);
    }

WSLC_TEST_METHOD(TriggerIdleTerminationRestartsVm)
    {
        constexpr auto c_sessionName = L"wslc-idle-trigger-test";

        // Idle termination is only permitted for storage-backed sessions (tmpfs state is
        // unrecoverable), so this lifecycle test uses a dedicated storage directory.
        const auto storageDir = std::filesystem::current_path() / "test-storage-idle-restart";
        std::error_code storageError;
        std::filesystem::remove_all(storageDir, storageError);
        std::filesystem::create_directories(storageDir);
        auto storageCleanup = wil::scope_exit([&]() {
            std::error_code ec;
            std::filesystem::remove_all(storageDir, ec);
        });

        auto settings = GetDefaultSessionSettings(c_sessionName);
        settings.StoragePath = storageDir.c_str();
        auto session = CreateSession(settings);

        // The VM starts lazily, so a freshly created session is already idle.
        BOOL wasAlreadyIdle = FALSE;
        VERIFY_SUCCEEDED(session->TriggerIdleTermination(&wasAlreadyIdle));
        VERIFY_IS_TRUE(wasAlreadyIdle);
        VERIFY_IS_FALSE(IsVmRunning(c_sessionName));

        // Starting a process brings the VM up.
        {
            WSLCProcessLauncher launcher("/bin/sleep", {"/bin/sleep", "60"});
            auto process = launcher.Launch(*session);
            VERIFY_IS_TRUE(IsVmRunning(c_sessionName));
        }

        // Releasing the process wrapper removes its activity hold, allowing idle termination.
        wasAlreadyIdle = TRUE;
        VERIFY_SUCCEEDED(session->TriggerIdleTermination(&wasAlreadyIdle));
        VERIFY_IS_FALSE(wasAlreadyIdle);
        VERIFY_IS_FALSE(IsVmRunning(c_sessionName));

        // A second trigger is now a no-op.
        wasAlreadyIdle = FALSE;
        VERIFY_SUCCEEDED(session->TriggerIdleTermination(&wasAlreadyIdle));
        VERIFY_IS_TRUE(wasAlreadyIdle);

        // The session survives and lazily restarts the VM on the next operation.
        WSLCProcessLauncher launcher2("/bin/sleep", {"/bin/sleep", "60"});
        auto process2 = launcher2.Launch(*session);
        VERIFY_IS_TRUE(IsVmRunning(c_sessionName));
    }

WSLC_TEST_METHOD(TriggerIdleTerminationRefusedWithoutStorage)
    {
        constexpr auto c_sessionName = L"wslc-idle-tmpfs-test";
        auto session = CreateSession(GetDefaultSessionSettings(c_sessionName));

        // A never-started session is already idle even though idle termination is disabled.
        BOOL wasAlreadyIdle = FALSE;
        VERIFY_SUCCEEDED(session->TriggerIdleTermination(&wasAlreadyIdle));
        VERIFY_IS_TRUE(wasAlreadyIdle);
        VERIFY_IS_FALSE(IsVmRunning(c_sessionName));

        WSLCProcessLauncher launcher("/bin/sleep", {"/bin/sleep", "60"});
        auto process = launcher.Launch(*session);
        VERIFY_IS_TRUE(IsVmRunning(c_sessionName));

        wasAlreadyIdle = TRUE;
        VERIFY_SUCCEEDED(session->TriggerIdleTermination(&wasAlreadyIdle));
        VERIFY_IS_FALSE(wasAlreadyIdle);

        // The VM must still be running: the tmpfs session was not torn down.
        VERIFY_IS_TRUE(IsVmRunning(c_sessionName));
    }

WSLC_TEST_METHOD(TriggerIdleTerminationDefersForRunningContainer)
    {
        WSLCContainerLauncher launcher("debian:latest", "wslc-idle-active", {"/bin/sleep", "600"});
        auto container = launcher.Launch(*m_defaultSession, WSLCContainerStartFlagsNone);

        VERIFY_ARE_EQUAL(container.State(), WslcContainerStateRunning);
        VERIFY_IS_TRUE(IsVmRunning(c_testSessionName));

        // The test hook honors the same activity guard as automatic idle teardown.
        BOOL wasAlreadyIdle = TRUE;
        VERIFY_SUCCEEDED(m_defaultSession->TriggerIdleTermination(&wasAlreadyIdle));
        VERIFY_IS_FALSE(wasAlreadyIdle);
        VERIFY_IS_TRUE(IsVmRunning(c_testSessionName));
        VERIFY_ARE_EQUAL(container.State(), WslcContainerStateRunning);
    }

WSLC_TEST_METHOD(TriggerIdleTerminationRecoversStoppedContainerResources)
    {
        const auto hostFolder = std::filesystem::current_path() / "test-idle-container-volume";
        std::filesystem::create_directories(hostFolder);
        VERIFY_IS_TRUE((std::ofstream(hostFolder / "marker.txt") << "idle-recovery").good());
        auto folderCleanup = wil::scope_exit_log(WI_DIAGNOSTICS_INFO, [&]() {
            std::error_code ec;
            std::filesystem::remove_all(hostFolder, ec);
        });

        WSLCContainerLauncher launcher(
            "python:3.12-alpine",
            "wslc-idle-resource-recovery",
            {"python3", "-m", "http.server", "8000", "--bind", "0.0.0.0", "--directory", "/data"},
            {"PYTHONUNBUFFERED=1"},
            "bridge");
        launcher.AddPort(1270, 8000, AF_INET);
        launcher.AddVolume(hostFolder.wstring(), "/data", true);
        auto container = launcher.Create(*m_defaultSession);

        VERIFY_ARE_EQUAL(container.State(), WslcContainerStateCreated);

        // Tear down before the first start, then validate both recovered resources.
        BOOL wasAlreadyIdle = TRUE;
        VERIFY_SUCCEEDED(m_defaultSession->TriggerIdleTermination(&wasAlreadyIdle));
        VERIFY_IS_FALSE(wasAlreadyIdle);
        VERIFY_IS_FALSE(IsVmRunning(c_testSessionName));

        for (int iteration = 0; iteration < 2; ++iteration)
        {
            {
                VERIFY_SUCCEEDED(container.Get().Start(WSLCContainerStartFlagsAttach, nullptr, nullptr));
                VERIFY_ARE_EQUAL(container.State(), WslcContainerStateRunning);
                VERIFY_IS_TRUE(IsVmRunning(c_testSessionName));

                auto initProcess = container.GetInitProcess();
                WaitForOutput(initProcess.GetStdHandle(1), "Serving HTTP on");

                const auto ports = container.Inspect().Ports;
                VERIFY_IS_TRUE(ports.contains("8000/tcp"));
                VERIFY_ARE_EQUAL(ports.at("8000/tcp").size(), 1u);
                VERIFY_ARE_EQUAL(ports.at("8000/tcp")[0].HostPort, std::string{"1270"});
                ExpectHttpResponse(L"http://127.0.0.1:1270/marker.txt", 200);

                VERIFY_SUCCEEDED(container.Get().Stop(WSLCSignalSIGKILL, 0));
                VERIFY_ARE_EQUAL(container.State(), WslcContainerStateExited);
            }

            wasAlreadyIdle = TRUE;
            VERIFY_SUCCEEDED(m_defaultSession->TriggerIdleTermination(&wasAlreadyIdle));
            VERIFY_IS_FALSE(wasAlreadyIdle);
            VERIFY_IS_FALSE(IsVmRunning(c_testSessionName));
        }
    }

WSLC_TEST_METHOD(SessionTerminationAfterIdleTerminationWithContainer)
    {
        const auto hostFolder = std::filesystem::current_path() / "test-idle-terminate-volume";
        std::filesystem::create_directories(hostFolder);
        auto folderCleanup = wil::scope_exit_log(WI_DIAGNOSTICS_INFO, [&]() {
            std::error_code ec;
            std::filesystem::remove_all(hostFolder, ec);
        });

        WSLCContainerLauncher launcher("debian:latest", "wslc-idle-terminate-session", {"/bin/sleep", "600"});
        launcher.AddVolume(hostFolder.wstring(), "/data", true);

        {
            auto container = launcher.Launch(*m_defaultSession, WSLCContainerStartFlagsNone);

            VERIFY_ARE_EQUAL(container.State(), WslcContainerStateRunning);
            VERIFY_IS_TRUE(IsVmRunning(c_testSessionName));

            // Stop the container so it releases its activity hold on the VM.
            VERIFY_SUCCEEDED(container.Get().Stop(WSLCSignalSIGKILL, 0));
            VERIFY_ARE_EQUAL(container.State(), WslcContainerStateExited);

            // Drop the client reference without deleting: the session keeps the only remaining
            // reference in m_containers, so the impl is destroyed by the session teardown below
            // rather than here (where the VM is still alive and the release path is trivially safe).
            container.SetDeleteOnClose(false);
        }

        // Tear the VM down. The container metadata (including its mounted-volume state) deliberately
        // survives, while the VM object is released without the exit event ever being signaled.
        BOOL wasAlreadyIdle = TRUE;
        VERIFY_SUCCEEDED(m_defaultSession->TriggerIdleTermination(&wasAlreadyIdle));
        VERIFY_IS_FALSE(wasAlreadyIdle);
        VERIFY_IS_FALSE(IsVmRunning(c_testSessionName));

        // Terminating clears m_containers, running ~WSLCContainerImpl with no VM to unmount from.
        VERIFY_SUCCEEDED(m_defaultSession->Terminate());
        WaitForSessionTermination(m_defaultSession.get());

        {
            auto restore = ResetTestSession();
        }

        // The session host must still be alive and usable: if the destructor threw, the per-user
        // host process died and this fails.
        WSLCProcessLauncher processLauncher("/bin/echo", {"/bin/echo", "OK"});
        auto process = processLauncher.Launch(*m_defaultSession);
        VERIFY_ARE_EQUAL(process.Wait(), 0);
        PruneResult pruneResult;
        LOG_IF_FAILED(m_defaultSession->PruneContainers(nullptr, 0, &pruneResult.result));
    }

WSLC_TEST_METHOD(TriggerIdleTerminationConcurrentWithOperations)
    {
        constexpr auto c_sessionName = L"wslc-idle-hammer-test";

        // Idle termination only tears down storage-backed sessions, so a dedicated storage directory
        // is required for the teardown path to actually run under the concurrent hammering.
        const auto storageDir = std::filesystem::current_path() / "test-storage-idle-hammer";
        std::error_code storageError;
        std::filesystem::remove_all(storageDir, storageError);
        std::filesystem::create_directories(storageDir);
        auto storageCleanup = wil::scope_exit([&]() {
            std::error_code ec;
            std::filesystem::remove_all(storageDir, ec);
        });

        auto settings = GetDefaultSessionSettings(c_sessionName);
        settings.StoragePath = storageDir.c_str();
        auto session = CreateSession(settings);

        std::atomic<bool> stop = false;
        std::atomic<unsigned int> opFailures = 0;

        // Run the hammering worker via a future so the join is bounded: a real teardown/operation
        // deadlock would otherwise hang the test host indefinitely instead of failing. If the worker
        // does not drain within the timeout after we signal stop, treat it as a deadlock and fail.
        auto worker = std::async(std::launch::async, [&]() {
            while (!stop.load())
            {
                try
                {
                    WSLCProcessLauncher launcher("/bin/true", {"/bin/true"});
                    auto process = launcher.Launch(*session);
                    process.GetExitEvent().wait(5000);
                }
                catch (...)
                {
                    opFailures.fetch_add(1);
                }
            }
        });

        for (int i = 0; i < 25; ++i)
        {
            BOOL wasAlreadyIdle = FALSE;
            VERIFY_SUCCEEDED(session->TriggerIdleTermination(&wasAlreadyIdle));
        }

        stop.store(true);

        // A real teardown/operation deadlock would leave the worker wedged forever. The std::future
        // destructor blocks until the task completes, so letting a failed VERIFY unwind here would hang
        // the test host -- exactly what this test guards against. Fail fast with a dump on timeout so we
        // never unwind with an unfinished async task.
        FAIL_FAST_IF_MSG(
            worker.wait_for(std::chrono::seconds(60)) != std::future_status::ready,
            "hammering worker did not drain after stop; likely teardown/operation deadlock");

        worker.get();

        LogInfo("TriggerIdleTerminationConcurrentWithOperations tolerated %u operation failures", opFailures.load());

        // The session must still be usable after the hammering.
        WSLCProcessLauncher launcher("/bin/true", {"/bin/true"});
        auto process = launcher.Launch(*session);
        VERIFY_IS_TRUE(process.GetExitEvent().wait(30000));
    }

services::BuildOutput ParseOutputSpec(const std::wstring& spec)
{
    // Mirrors `docker buildx build --output`. A bare token is shorthand for a destination; otherwise
    // the spec is a single CSV record of key=value pairs where 'type'/'dest' are structural and every
    // other key is forwarded verbatim to buildx as an exporter attribute.
    if (spec.empty())
    {
        throw ArgumentException(Localization::MessageWslcOutputInvalidSpec(spec, L"the value may not be empty"));
    }

    // buildx parses the spec as one CSV record (go-csvvalue / encoding/csv): fields are comma
    // separated, a field may be double-quoted, "" inside a quoted field is a literal quote, and a
    // comma inside quotes is part of the value. This lets a value such as an annotation contain commas.
    const auto fields = SplitCsvFields(spec);
    if (!fields.has_value())
    {
        throw ArgumentException(Localization::MessageWslcOutputInvalidSpec(spec, L"malformed quoting"));
    }

    // Keys are ASCII and matched case-insensitively, and buildx TrimSpace's each key so " dest=x" after
    // a comma is accepted; values are left untouched. AsciiToLower/TrimAscii live in stringshared.h.

    // Shorthand: a single field that is exactly the input and does not start with "type=" names the
    // destination. Matching Docker, '-' streams a tarball to stdout ('type=tar,dest=-'); anything else
    // is the local (directory) exporter ('type=local,dest=<path>'), which is not supported.
    if (fields->size() == 1 && fields->front() == spec && spec.compare(0, 5, L"type=") != 0)
    {
        if (fields->front() == L"-")
        {
            return services::BuildOutput{.Type = L"tar", .Dest = L"-"};
        }

        throw ArgumentException(Localization::MessageWslcOutputInvalidSpec(
            spec,
            L"directory exporters are not supported; write a single file with 'dest=<file>' (type=tar/oci/docker) "
            L"or stream a tarball to stdout with 'type=tar,dest=-'"));
    }

    services::BuildOutput output;
    std::wstring rawType;
    bool hasType = false;

    for (const auto& field : *fields)
    {
        // buildx splits each field on the FIRST '=' and requires two parts; the value is not trimmed.
        const auto pos = field.find(L'=');
        if (pos == std::wstring::npos)
        {
            throw ArgumentException(
                Localization::MessageWslcOutputInvalidSpec(spec, L"expected key=value pairs separated by ','"));
        }

        const auto key = AsciiToLower(TrimAscii(std::wstring_view(field).substr(0, pos)));
        auto value = field.substr(pos + 1);
        if (key.empty())
        {
            throw ArgumentException(
                Localization::MessageWslcOutputInvalidSpec(spec, L"expected key=value pairs separated by ','"));
        }

        if (key == L"type")
        {
            rawType = value;
            output.Type = AsciiToLower(std::wstring_view(value));
            hasType = true;
        }
        else if (key == L"dest")
        {
            output.Dest = std::move(value);
        }
        else
        {
            // Remaining attributes (name, push, compression, tar, annotations, ...) are matched
            // case-insensitively by buildx, so their keys are already lowercased above.
            output.Attributes[key] = std::move(value);
        }
    }

    if (!hasType || output.Type.empty())
    {
        throw ArgumentException(Localization::MessageWslcOutputInvalidSpec(spec, L"type is required"));
    }

    // buildx forwards the type to buildkit and only rejects it there; we route the exporter ourselves,
    // so an unroutable type has to be rejected up front. Every real exporter is in this list.
    const bool supportedType = output.Type == L"local" || output.Type == L"tar" || output.Type == L"oci" ||
                               output.Type == L"docker" || output.Type == L"image" || output.Type == L"registry" ||
                               output.Type == L"cacheonly";
    if (!supportedType)
    {
        throw ArgumentException(Localization::MessageWslcOutputInvalidSpec(spec, std::format(L"unsupported output type '{}'", rawType)));
    }

    // The 'tar' attribute selects a single tarball vs. an OCI layout directory for oci/docker, and it
    // drives file-vs-directory routing here. buildx parses it with Go's ParseBool and errors on
    // anything else, so reject an invalid value up front rather than failing confusingly in the VM.
    if (output.Type == L"oci" || output.Type == L"docker")
    {
        const auto tarIt = output.Attributes.find(L"tar");
        if (tarIt != output.Attributes.end() && !ParseBool(tarIt->second.c_str(), true).has_value())
        {
            throw ArgumentException(
                Localization::MessageWslcOutputInvalidSpec(spec, std::format(L"invalid boolean value '{}' for 'tar'", tarIt->second)));
        }
    }

    // Destination resolution, mirroring `docker buildx build --output`:
    if (OutputIsDirectory(output))
    {
        // Directory exporters (local, or oci/docker with tar=false) write a Linux directory tree, which
        // cannot be materialized faithfully on a Windows destination, so they are not supported. Point
        // users at the single-file exporters instead.
        throw ArgumentException(Localization::MessageWslcOutputInvalidSpec(
            spec,
            L"directory exporters are not supported; write a single file with 'dest=<file>' (type=tar/oci/docker) "
            L"or stream a tarball to stdout with 'type=tar,dest=-'"));
    }

    if (output.Type == L"tar" || output.Type == L"oci")
    {
        // Single-tarball exporters stream to stdout when no destination is given (buildx default).
        if (output.Dest.empty())
        {
            output.Dest = L"-";
        }
    }
    // docker: no dest -> load into the VM image store (leave empty); dest='-' streams a tarball to
    //         stdout; a path writes a file. image/registry/cacheonly run in the VM and ignore 'dest'.

    return output;
}

bool OutputStreamsToClient(const services::BuildOutput& output)
{
    if (output.Type == L"local" || output.Type == L"tar" || output.Type == L"oci")
    {
        return true;
    }

    if (output.Type == L"docker")
    {
        // An omitted destination loads the image into the store in the VM; any destination (a file or
        // stdout '-') is produced in the VM and streamed back to the client.
        return !output.Dest.empty();
    }

    // image / registry / cacheonly run entirely in the build VM.
    return false;
}

bool OutputIsDirectory(const services::BuildOutput& output)
{
    if (output.Type == L"local")
    {
        return true;
    }

    if (output.Type == L"oci" || output.Type == L"docker")
    {
        // oci/docker default to a single tarball but export an OCI layout directory when tar is false.
        const auto it = output.Attributes.find(L"tar");
        if (it != output.Attributes.end())
        {
            const auto tar = ParseBool(it->second.c_str(), true);
            return tar.has_value() && !tar.value();
        }
    }

    return false;
}

std::wstring FormatOutputSpec(const services::BuildOutput& output)
{
    // buildx consumes the same CSV key=value form we parsed, so we round-trip the parsed struct back
    // into a canonical spec. This is what actually reaches `docker build --output <spec>`. Each token
    // is CSV-escaped so a value containing a comma or quote survives the trip.
    std::vector<std::wstring> fields;
    fields.push_back(std::format(L"type={}", output.Type));
    if (!output.Dest.empty())
    {
        fields.push_back(std::format(L"dest={}", output.Dest));
    }

    for (const auto& [key, value] : output.Attributes)
    {
        fields.push_back(std::format(L"{}={}", key, value));
    }

    return JoinCsvFields(fields);
}

static void VerifyValid(const std::wstring& spec, const std::wstring& expectedType, const std::wstring& expectedDest, const AttrMap& expectedAttrs = {})
    {
        auto output = validation::ParseOutputSpec(spec);
        VERIFY_ARE_EQUAL(expectedType, output.Type);
        VERIFY_ARE_EQUAL(expectedDest, output.Dest);
        VERIFY_ARE_EQUAL(expectedAttrs.size(), output.Attributes.size());
        for (const auto& [key, value] : expectedAttrs)
        {
            const auto it = output.Attributes.find(key);
            VERIFY_IS_TRUE(it != output.Attributes.end());
            if (it != output.Attributes.end())
            {
                VERIFY_ARE_EQUAL(value, it->second);
            }
        }
    }

static void VerifyInvalid(const std::wstring& spec, const std::wstring& expectedReasonSubstr)
    {
        Log::Comment(String().Format(L"Rejecting: %ls", spec.c_str()));
        try
        {
            (void)validation::ParseOutputSpec(spec);
            VERIFY_FAIL(L"Expected ArgumentException for invalid output spec");
        }
        catch (const ArgumentException& ex)
        {
            const std::wstring& message = ex.Message();
            VERIFY_IS_TRUE(message.find(L"Invalid --output value") != std::wstring::npos);
            VERIFY_IS_TRUE(message.find(expectedReasonSubstr) != std::wstring::npos);
        }
    }

TEST_METHOD(Output_Shorthand_DashIsTarToStdout)
    {
        // '-' is docker's shorthand for streaming a tarball to stdout ('type=tar,dest=-').
        VerifyValid(L"-", L"tar", L"-");
    }

TEST_METHOD(Output_LocalExporter_Rejected)
    {
        // The local exporter - a bare-path shorthand or an explicit type=local - writes a Linux
        // directory tree, which is not supported, so every form is rejected regardless of destination.
        // 'dest=./out' is buildx's single-field shorthand quirk: a lone field containing '=' that does
        // not start with 'type=' still names a local path.
        for (const auto* spec :
             {L"./out", L"C:\\build\\artifacts", L"dest=./out", L"type=local", L"type=local,dest=./out", L"type=local,dest=-"})
        {
            VerifyInvalid(spec, L"directory exporters are not supported");
        }
    }

TEST_METHOD(Output_OciDockerTarFalse_Rejected)
    {
        // oci/docker export an OCI layout directory when 'tar' is false; buildx parses 'tar' with Go's
        // ParseBool, so every false spelling (false/False/0/f) is a directory exporter and is rejected
        // the same way, with or without a destination.
        for (const auto* spec :
             {L"type=oci,dest=./layout,tar=false",
              L"type=oci,tar=false",
              L"type=oci,dest=./layout,tar=False",
              L"type=oci,dest=./layout,tar=0",
              L"type=oci,dest=./layout,tar=f",
              L"type=docker,dest=./layout,tar=false",
              L"type=docker,dest=./layout,tar=0"})
        {
            VerifyInvalid(spec, L"directory exporters are not supported");
        }
    }

