        std::error_code ec;
        std::filesystem::create_directories(contextDir, ec);
        THROW_HR_IF(E_FAIL, ec.value() != 0 || !std::filesystem::exists(contextDir));

        auto dockerfilePath = testRoot / L"Dockerfile";
        WriteTestFileContent(dockerfilePath, "FROM debian:latest\n");

        auto buildResult =
            RunWslc(std::format(L"build \"{}\" -f \"{}\" --secret id=x,type=bogus", contextDir.wstring(), dockerfilePath.wstring()));
        VERIFY_ARE_EQUAL(1u, buildResult.ExitCode.value_or(0u));
        VERIFY_IS_TRUE(buildResult.Stderr.has_value());
        VERIFY_IS_TRUE(buildResult.Stderr->find(L"Invalid --secret value 'id=x,type=bogus': unsupported secret type 'bogus'") != std::wstring::npos);
    }

bool wsl::shared::Localization::IsCurrentLanguageEnglish(Options options)
{
    try
    {
        const auto languages = GetUserLanguages(options != Options::DontImpersonate && g_runningInService);
        if (!languages.empty())
        {
            return languages[0] == L"en" || languages[0].starts_with(L"en-");
        }
    }
    catch (...)
    {
        LOG_CAUGHT_EXCEPTION();
    }

    return true;
}

std::string wsl::windows::service::wslc::FormatDockerEngineError(const std::string& EngineMessage)
{
    if (EngineMessage.empty() || wsl::shared::Localization::IsCurrentLanguageEnglish())
    {
        return EngineMessage;
    }

    return wsl::shared::string::WideToMultiByte(wsl::shared::Localization::MessageWslcDockerEngineErrorPrefix()) + " " + EngineMessage;
}

WSL2_TEST_METHOD(ManageRejectedWhileLocked)
    {
        constexpr auto name = L"manage-locked-test-distro";

        VERIFY_ARE_EQUAL(LxsstuLaunchWsl(std::format(L"--import {} . \"{}\" --version 2", name, g_testDistroPath)), 0L);
        auto cleanupName =
            wil::scope_exit_log(WI_DIAGNOSTICS_INFO, [name]() { LxsstuLaunchWsl(std::format(L"--unregister {}", name)); });
        WslShutdown();

        // Start an export to a pipe we deliberately don't drain. Use a tiny buffer so the export blocks
        // as soon as it writes any data, regardless of the test distro's size, deterministically holding
        // the distribution in the "Exporting" locked state.
        auto [readPipe, writePipe] = CreateSubprocessPipe(false, true, 1);

        std::thread exportThread([&]() { LxsstuLaunchWsl(std::format(L"--export {} -", name), nullptr, writePipe.get()); });

        auto joinExport = wil::scope_exit_log(WI_DIAGNOSTICS_INFO, [&]() {
            // Close the read end so the blocked export fails with a broken pipe and returns, then join.
            readPipe.reset();
            if (exportThread.joinable())
            {
                exportThread.join();
            }
        });

        // Wait until the service reports the distribution as Exporting (i.e. the lock is held).
        bool locked = false;
        for (int i = 0; i < 100 && !locked; ++i)
        {
            auto [out, _] = LxsstuLaunchWslAndCaptureOutput(L"--list --verbose");
            locked = (out.find(name) != std::wstring::npos) && (out.find(L"Exporting") != std::wstring::npos);
            if (!locked)
            {
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        }

        VERIFY_IS_TRUE(locked);

        // Each VHD-mutating manage operation must be rejected with E_ILLEGAL_STATE_CHANGE while the lock is held.
        auto verifyRejected = [&](const std::wstring& command) {
            auto [out, _] = LxsstuLaunchWslAndCaptureOutput(command, -1);
            VERIFY_IS_TRUE(out.find(L"E_ILLEGAL_STATE_CHANGE") != std::wstring::npos);
        };

        verifyRejected(std::format(L"--manage {} --resize 2GB", name));
        verifyRejected(std::format(L"--manage {} --set-sparse false", name));

        const auto moveTarget = std::filesystem::absolute(L"manage-locked-move-target").wstring();
        verifyRejected(std::format(L"--manage {} --move \"{}\"", name, moveTarget));
    }

State AddSample(unsigned long long Busy, unsigned long long Total)
    {
        m_windowBusy -= m_busyWindow[m_windowIndex];
        m_windowTotal -= m_totalWindow[m_windowIndex];
        m_busyWindow[m_windowIndex] = Busy;
        m_totalWindow[m_windowIndex] = Total;
        m_windowBusy += Busy;
        m_windowTotal += Total;
        m_windowIndex = (m_windowIndex + 1) % c_windowIntervals;
        if (m_windowSamples < c_windowIntervals)
        {
            m_windowSamples += 1;
        }

        return {
            .IntervalIdle = IsIdle(Busy, Total),
            .WindowIdle = m_windowSamples == c_windowIntervals && IsIdle(m_windowBusy, m_windowTotal),
        };
    }

void Reset()
    {
        m_busyWindow.fill(0);
        m_totalWindow.fill(0);
        m_windowBusy = 0;
        m_windowTotal = 0;
        m_windowIndex = 0;
        m_windowSamples = 0;
    }

static std::tuple<unique_kill_process, uint16_t> BindGuestPortViaListenOnly()
    {
        auto [stdOutRead, stdOutWrite] = CreateSubprocessPipe(false, true);

        // Perl one-liner: socket() + listen() with no bind(), print the kernel-assigned
        // port via getsockname(), then accept() (blocking) to keep the socket alive.
        const std::wstring wslCmd =
            L"perl -MSocket -e '"
            L"$|=1;"
            L"socket(S,AF_INET,SOCK_STREAM,0) or die;"
            L"listen(S,5) or die;"
            L"my $port=(sockaddr_in(getsockname(S)))[0];"
            L"print \"PORT=$port\\n\";"
            L"accept(C,S);"
            L"'";
        auto cmd = LxssGenerateWslCommandLine(wslCmd.data());

        auto process = LxsstuStartProcess(cmd.data(), nullptr, stdOutWrite.get(), nullptr);
        stdOutWrite.reset();

        std::string output(256, '\0');
        DWORD writeOffset = 0;
        uint16_t assignedPort = 0;
        bool found = false;

        while (!found)
        {
            if (writeOffset == output.size())
            {
                output.resize(output.size() * 2);
            }

            DWORD bytesRead = 0;
            if (!ReadFile(stdOutRead.get(), output.data() + writeOffset, static_cast<DWORD>(output.size() - writeOffset), &bytesRead, nullptr) ||
                bytesRead == 0)
            {
                break;
            }

            writeOffset += bytesRead;
            LogInfo("output %hs", output.c_str());
            std::string_view outputView(output.data(), writeOffset);
            auto pos = outputView.find("PORT=");
            if (pos != std::string_view::npos)
            {
                auto portStr = outputView.substr(pos + 5);

                // Only parse once the line is fully read (terminated by '\n'); otherwise a
                // partial read could truncate the port digits (e.g. "123" read as "12").
                auto newlinePos = portStr.find('\n');
                if (newlinePos != std::string_view::npos)
                {
                    portStr = portStr.substr(0, newlinePos);
                    if (!portStr.empty())
                    {
                        assignedPort = static_cast<uint16_t>(std::stoi(std::string(portStr)));
                        found = true;
                    }
                }
            }
        }

        VERIFY_IS_TRUE(found);
        VERIFY_IS_TRUE(assignedPort > 0);
        LogInfo("listen()-only autobind resolved to port %u", assignedPort);

        return {std::move(process), assignedPort};
    }

static void VerifyListenWithoutBindIsTracked(bool verifyRelease = true)
    {
        WslKeepAlive keepAlive;

        auto [guestProcess, assignedPort] = BindGuestPortViaListenOnly();

        // Port resolution is asynchronous (deferred to a background thread) for the case where
        // the socket wasn't already bound. Retry until the host port tracker registers the port,
        // blocking the host bind.
        VERIFY_NO_THROW(wsl::shared::retry::RetryWithTimeout<void>(
            [&assignedPort]() {
                wil::unique_socket sock(socket(AF_INET, SOCK_STREAM, IPPROTO_TCP));
                THROW_LAST_ERROR_IF(!sock);

                SOCKADDR_IN addr{};
                addr.sin_family = AF_INET;
                addr.sin_port = htons(assignedPort);
                THROW_HR_IF(E_FAIL, bind(sock.get(), reinterpret_cast<SOCKADDR*>(&addr), sizeof(addr)) != SOCKET_ERROR);
            },
            std::chrono::seconds(1),
            std::chrono::seconds(30)));

        if (!verifyRelease)
        {
            return;
        }

        // Kill the guest process so the port tracker releases the port.
        guestProcess.reset();

        // Retry until the host can bind the port again, confirming it was released.
        VERIFY_NO_THROW(wsl::shared::retry::RetryWithTimeout<void>(
            [&assignedPort]() {
                wil::unique_socket sock(socket(AF_INET, SOCK_STREAM, IPPROTO_TCP));
                THROW_LAST_ERROR_IF(!sock);

                SOCKADDR_IN addr{};
                addr.sin_family = AF_INET;
                addr.sin_port = htons(assignedPort);
                THROW_HR_IF(E_FAIL, bind(sock.get(), reinterpret_cast<SOCKADDR*>(&addr), sizeof(addr)) == SOCKET_ERROR);
            },
            std::chrono::seconds(1),
            std::chrono::minutes(2)));
    }

WSL2_TEST_METHOD(ListenWithoutBindIsTracked)
    {
        MIRRORED_NETWORKING_TEST_ONLY();

        m_config->Update(LxssGenerateTestConfig({.networkingMode = wsl::core::NetworkingMode::Mirrored}));
        WaitForMirroredStateInLinux();

        // See PortZeroBindIsTracked above for why release verification is skipped in mirrored mode.
        NetworkTests::VerifyListenWithoutBindIsTracked(false);
    }

WSL2_TEST_METHOD(ListenWithoutBindIsTracked)
    {
        CONSOMME_TEST_ONLY();

        m_config->Update(LxssGenerateTestConfig({.networkingMode = wsl::core::NetworkingMode::Consomme}));

        NetworkTests::VerifyListenWithoutBindIsTracked();
    }

void DeleteImagesWithRepositoryPrefix(const std::wstring& repositoryPrefix)
{
    auto result = RunWslc(L"image list --format json");
    result.Verify({.Stderr = L"", .ExitCode = 0});

    const auto images = wsl::shared::FromJson<std::vector<wsl::windows::wslc::models::ImageInformation>>(result.Stdout.value().c_str());
    const auto prefix = wsl::shared::string::WideToMultiByte(repositoryPrefix);
    for (const auto& image : images)
    {
        if (image.Repository && image.Tag && image.Repository->starts_with(prefix))
        {
            // No container cleanup here: the images this prunes are only ever built and inspected, never used to
            // create containers, so image delete --force is sufficient. If a future test containerizes a built
            // image, remove its container in that test's cleanup rather than broadening this prefix-based safety net.
            const auto nameAndTag = wsl::shared::string::MultiByteToWide(std::format("{}:{}", *image.Repository, *image.Tag));
            RunWslc(std::format(L"image delete --force {}", nameAndTag)).Verify({.Stderr = L"", .ExitCode = 0});
        }
    }
}

__declspec(dllexport) UINT __stdcall WslTestForceInstallFailure(MSIHANDLE install)
{
    try
    {
        WSL_INSTALL_LOG("WslTestForceInstallFailure", TraceLoggingValue("Forcing install failure for rollback testing", "Reason"));
    }
    CATCH_LOG();

    return ERROR_INSTALL_FAILURE;
}

static void CallMsiExec(const std::wstring& Args)
    {
        VERIFY_ARE_EQUAL(0L, RunMsiExec(Args));
    // Queries the MSI database for the sequence number of the given action in InstallExecuteSequence.
    // Returns -1 if the action is not found.
    int GetMsiSequenceNumber(MSIHANDLE database, LPCWSTR action)
    {
        unique_msi_handle view;
        THROW_IF_WIN32_ERROR(MsiDatabaseOpenViewW(database, L"SELECT `Sequence` FROM `InstallExecuteSequence` WHERE `Action` = ?", &view));
        unique_msi_handle rec{MsiCreateRecord(1)};
        THROW_IF_WIN32_ERROR(MsiRecordSetStringW(rec.get(), 1, action));
        THROW_IF_WIN32_ERROR(MsiViewExecute(view.get(), rec.get()));

        MSIHANDLE hResult = 0;
        auto fetchResult = MsiViewFetch(view.get(), &hResult);
        if (fetchResult == ERROR_NO_MORE_ITEMS)
        {
            return -1;
        }

        THROW_IF_WIN32_ERROR(fetchResult);
        unique_msi_handle result{hResult};
        return MsiRecordGetInteger(result.get(), 1);
    }

    TEST_METHOD(MsiRemoveExistingProductsScheduledInsideTransaction)
    {
        // Verify that RemoveExistingProducts is scheduled between InstallInitialize
        // and InstallFinalize in the MSI sequence table. This is the effect of
        // Schedule="afterInstallInitialize" on <MajorUpgrade> in package.wix.in.

        unique_msi_handle database;
        THROW_IF_WIN32_ERROR(MsiOpenDatabaseW(m_msiPath.c_str(), MSIDBOPEN_READONLY, &database));

        auto installInitialize = GetMsiSequenceNumber(database.get(), L"InstallInitialize");
        auto removeExistingProducts = GetMsiSequenceNumber(database.get(), L"RemoveExistingProducts");
        auto installFinalize = GetMsiSequenceNumber(database.get(), L"InstallFinalize");

        LogInfo("MSI sequence: InstallInitialize=%d, RemoveExistingProducts=%d, InstallFinalize=%d", installInitialize, removeExistingProducts, installFinalize);

        VERIFY_ARE_NOT_EQUAL(-1, installInitialize);
        VERIFY_ARE_NOT_EQUAL(-1, removeExistingProducts);
        VERIFY_ARE_NOT_EQUAL(-1, installFinalize);

        VERIFY_IS_GREATER_THAN(
            removeExistingProducts, installInitialize, L"RemoveExistingProducts must be after InstallInitialize");

        VERIFY_IS_LESS_THAN(removeExistingProducts, installFinalize, L"RemoveExistingProducts must precede InstallFinalize");
    }

    TEST_METHOD(MsiUpgradeFailureRestoresFiles)
    {
#ifdef WSL_OFFICIAL_BUILD
        Log::Comment(L"TestSkipped: This test case requires the test-only WslTestForceInstallFailure CA");
        return;
#else
        // End-to-end rollback test: install an older version, then attempt a major
        // upgrade that fails inside the transaction. Verify the old version's files
        // are restored by MSI rollback.

        UninstallMsi();
        InstallGitHubRelease(L"2.0.2");

        auto restore = wil::scope_exit([this]() { InstallMsi(); });

        VERIFY_IS_TRUE(IsMsiPackageInstalled());

        const auto wslExe = m_installedPath / L"wsl.exe";
        const auto wslService = m_installedPath / L"wslservice.exe";
        const auto systemVhd = m_installedPath / L"system.vhd";

        VERIFY_IS_TRUE(std::filesystem::exists(wslExe), L"wsl.exe must exist before upgrade");
        VERIFY_IS_TRUE(std::filesystem::exists(wslService), L"wslservice.exe must exist before upgrade");
        VERIFY_IS_TRUE(std::filesystem::exists(systemVhd), L"system.vhd must exist before upgrade");

        // Attempt a major upgrade forced to fail after RemoveExistingProducts.
        PrepareForMsiOperation();
        auto msiArgs = std::format(
            L"/qn /norestart /i \"{}\" WSL_TEST_FORCE_INSTALL_FAILURE=1 SKIPVALIDATION=1 "
            L"/L*V \"{}\"",
            m_msiPath,
            GenerateMsiLogPath());
        auto exitCode = RunMsiExec(msiArgs);

        VERIFY_ARE_NOT_EQUAL(0L, exitCode, L"Upgrade should have failed due to forced failure CA");

        // Verify rollback restored the previous installation
        VERIFY_IS_TRUE(IsMsiPackageInstalled(), L"MSI package must still be installed after rollback");
        VERIFY_IS_TRUE(std::filesystem::exists(wslExe), L"wsl.exe must be restored after rollback");
        VERIFY_IS_TRUE(std::filesystem::exists(wslService), L"wslservice.exe must be restored after rollback");
        VERIFY_IS_TRUE(std::filesystem::exists(systemVhd), L"system.vhd must be restored after rollback");
        ValidateInstalledVersion(L"2.0.2");
#endif
    }

