WSL2_TEST_METHOD(MountVhdThroughSymlinkSucceeds)
    {
        SKIP_UNSUPPORTED_ARM64_MOUNT_TEST();

        const auto symlink = std::filesystem::absolute(L"TestVhdSymlink.vhd");
        DeleteFileW(symlink.c_str());

        const auto absoluteTarget = std::filesystem::absolute(TEST_MOUNT_VHD);

        // Create a file symbolic link pointing at the real VHD.
        VERIFY_IS_TRUE(CreateSymbolicLinkW(symlink.c_str(), absoluteTarget.c_str(), SYMBOLIC_LINK_FLAG_ALLOW_UNPRIVILEGED_CREATE));

        auto cleanup = wil::scope_exit([&]() { DeleteFileW(symlink.c_str()); });

        VERIFY_ARE_EQUAL(LxsstuLaunchWsl(L"--mount " + symlink.wstring() + L" --vhd --bare"), (DWORD)0);

        const auto disk = GetBlockDeviceInWsl();
        VERIFY_IS_TRUE(IsBlockDevicePresent(disk));

        VERIFY_ARE_EQUAL(LxsstuLaunchWsl(L"--unmount " + symlink.wstring()), (DWORD)0);
    }

WSL2_TEST_METHOD(MountVhdThroughSymlinkSurvivesVmTimeout)
    {
        SKIP_UNSUPPORTED_ARM64_MOUNT_TEST();

        const auto symlink = std::filesystem::absolute(L"TestVhdSymlinkRestore.vhd");
        DeleteFileW(symlink.c_str());

        const auto absoluteTarget = std::filesystem::absolute(TEST_MOUNT_VHD);

        VERIFY_IS_TRUE(CreateSymbolicLinkW(symlink.c_str(), absoluteTarget.c_str(), SYMBOLIC_LINK_FLAG_ALLOW_UNPRIVILEGED_CREATE));

        auto cleanup = wil::scope_exit([&]() { DeleteFileW(symlink.c_str()); });

        WslKeepAlive keepAlive;

        VERIFY_ARE_EQUAL(LxsstuLaunchWsl(L"--mount " + symlink.wstring() + L" --vhd --bare"), (DWORD)0);

        auto disk = GetBlockDeviceInWsl();
        VERIFY_IS_TRUE(IsBlockDevicePresent(disk));

        WaitForVmTimeout(keepAlive);

        // Recreating the VM restores the persisted disk mount; the symlinked VHD must re-attach. The
        // block device name is not guaranteed to be stable across the VM teardown, so re-query it.
        disk = GetBlockDeviceInWsl();
        VERIFY_IS_TRUE(IsBlockDevicePresent(disk));

        VERIFY_ARE_EQUAL(LxsstuLaunchWsl(L"--unmount " + symlink.wstring()), (DWORD)0);
    }

void Container::EnsureNotClosed() const
{
    if (!m_container)
    {
        throw winrt::hresult_error(RO_E_CLOSED, L"Container has been closed");
    }
}

void Container::Close()
{
    m_initProcess = nullptr;

    // Methods called after Close() will fail due to EnsureNotClosed().
    m_container.reset();
}

void Container::final_release(std::unique_ptr<Container> self)
{
    // Ensure cleanup when refcount drops to zero even if Close() was not called explicitly.
    self->Close();
}

void ContainerSettings::EnableGpu(bool value)
{
    if (m_containerSettings)
    {
        throw winrt::hresult_illegal_state_change(L"Cannot change container settings after container has been initialized");
    }

    WI_UpdateFlag(m_containerFlags, WSLC_CONTAINER_FLAG_ENABLE_GPU, value);
}

void ContainerSettings::Privileged(bool value)
{
    if (m_containerSettings)
    {
        throw winrt::hresult_illegal_state_change(L"Cannot change container settings after container has been initialized");
    }

    WI_UpdateFlag(m_containerFlags, WSLC_CONTAINER_FLAG_PRIVILEGED, value);
        winrt::check_hresult(WslcSetContainerSettingsFlags(m_containerSettings.get(), m_containerFlags));

void Process::Close()
{
    if (m_waitForExitAction)
    {
        m_waitForExitAction.Cancel();
        m_waitForExitAction = nullptr;
    }

    // Methods called after Close() will fail due to EnsureStarted().
    m_process.reset();
}

void Process::final_release(std::unique_ptr<Process> self)
{
    // Ensure cleanup when refcount drops to zero even if Close() was not called explicitly.
    self->Close();
}

void Session::PullImage(winrt::Microsoft::WSL::Containers::PullImageOptions const& options)
{
    if (!options)
    {
        throw winrt::hresult_error(E_POINTER, L"Options for pull cannot be null");
    }

    EnsureStarted();

    auto pullOptions = GetStruct(options);

    wil::unique_cotaskmem_string errorMessage;
    auto hr = WslcPullSessionImage(ToHandle(), &pullOptions, errorMessage.put());
    THROW_MSG_IF_FAILED(hr, errorMessage);
}

void Session::ImportImage(hstring const& path, hstring const& imageName)
{
    if (path.empty())
    {
        throw winrt::hresult_invalid_argument(L"Path cannot be empty");
    }

    if (imageName.empty())
    {
        throw winrt::hresult_invalid_argument(L"Image name cannot be empty");
    }

    EnsureStarted();

    auto name = winrt::to_string(imageName);

    WslcImportImageOptions importOptions{};

    wil::unique_cotaskmem_string errorMessage;
    auto hr = WslcImportSessionImageFromFile(ToHandle(), name.c_str(), path.c_str(), &importOptions, errorMessage.put());
    THROW_MSG_IF_FAILED(hr, errorMessage);
}

void Session::LoadImage(hstring const& path)
{
    if (path.empty())
    {
        throw winrt::hresult_invalid_argument(L"Path cannot be empty");
    }

    EnsureStarted();

    WslcLoadImageOptions loadOptions{};

    wil::unique_cotaskmem_string errorMessage;
    auto hr = WslcLoadSessionImageFromFile(ToHandle(), path.c_str(), &loadOptions, errorMessage.put());
    THROW_MSG_IF_FAILED(hr, errorMessage);
}

void Session::PushImage(winrt::Microsoft::WSL::Containers::PushImageOptions const& options)
{
    if (!options)
    {
        throw winrt::hresult_error(E_POINTER, L"Options for push cannot be null");
    }

    EnsureStarted();

    auto pushOptions = GetStruct(options);

    wil::unique_cotaskmem_string errorMessage;
    auto hr = WslcPushSessionImage(ToHandle(), &pushOptions, errorMessage.put());
    THROW_MSG_IF_FAILED(hr, errorMessage);
}

void Session::Close()
{
    m_terminationWait.reset();
    m_terminationEvent.reset();
    m_crashDumpSubscription.reset();

    // Methods called after Close() will fail due to EnsureStarted().
    m_settings = nullptr;
    m_session.reset();
}

void Session::final_release(std::unique_ptr<Session> self)
{
    // Ensure cleanup when refcount drops to zero even if Close() was not called explicitly.
    self->Close();
}

