}

[[nodiscard]] Qt::InputMethodHints HintsForType(FieldType type) {
	switch (type) {
	case FieldType::Text:
	case FieldType::Country:
		return {};
	case FieldType::Email:
		return Qt::ImhEmailCharactersOnly
			| Qt::ImhNoAutoUppercase
			| Qt::ImhNoPredictiveText;
	case FieldType::CardNumber:
	case FieldType::CardCVC:
		return Qt::ImhDigitsOnly
			| Qt::ImhNoPredictiveText
			| Qt::ImhSensitiveData;
	case FieldType::CardExpireDate:
		return Qt::ImhDigitsOnly | Qt::ImhNoPredictiveText;
	case FieldType::Phone:
		return Qt::ImhDialableCharactersOnly | Qt::ImhNoPredictiveText;
	case FieldType::Money:
		return Qt::ImhFormattedNumbersOnly | Qt::ImhNoPredictiveText;
	}
	Unexpected("FieldType in Payments::Ui::HintsForType.");
}

uint64_t hllCount(struct hllhdr *hdr, int *invalid) {
    double m = HLL_REGISTERS;
    double E;
    int j;
    /* Note that reghisto size could be just HLL_Q+2, because HLL_Q+1 is
     * the maximum frequency of the "000...1" sequence the hash function is
     * able to return. However it is slow to check for sanity of the
     * input: instead we history array at a safe size: overflows will
     * just write data to wrong, but correctly allocated, places. */
    int reghisto[64] = {0};

    /* Compute register histogram */
    if (hdr->encoding == HLL_DENSE) {
        hllDenseRegHisto(hdr->registers, reghisto);
    } else if (hdr->encoding == HLL_SPARSE) {
        hllSparseRegHisto(hdr->registers, sdslen((sds)hdr) - HLL_HDR_SIZE, invalid, reghisto);
    } else if (hdr->encoding == HLL_RAW) {
        hllRawRegHisto(hdr->registers, reghisto);
    } else {
        serverPanic("Unknown HyperLogLog encoding in hllCount()");
    }
    /* Estimate cardinality from register histogram. See:
     * "New cardinality estimation algorithms for HyperLogLog sketches"
     * Otmar Ertl, arXiv:1702.01284 */
    double z = m * hllTau((m - reghisto[HLL_Q + 1]) / (double)m);
    for (j = HLL_Q; j >= 1; --j) {
        z += reghisto[j];
        z *= 0.5;
    }
    z += m * hllSigma(reghisto[0] / (double)m);
    E = llroundl(HLL_ALPHA_INF * m * m / z);
    return (uint64_t)E;
}

static int hllAdd(robj *o, unsigned char *ele, size_t elesize) {
    struct hllhdr *hdr = objectGetVal(o);
    switch (hdr->encoding) {
    case HLL_DENSE: return hllDenseAdd(hdr->registers, ele, elesize);
    case HLL_SPARSE: return hllSparseAdd(o, ele, elesize);
    default: return -1; /* Invalid representation. */
    }
}

ATTRIBUTE_TARGET_AVX2
void hllMergeDenseAVX2(uint8_t *reg_raw, const uint8_t *reg_dense) {
    /* Shuffle indices for unpacking bytes of dense registers
     * From: {XXXX|AAAB|BBCC|CDDD|EEEF|FFGG|GHHH|XXXX}
     * To:   {AAA0|BBB0|CCC0|DDD0|EEE0|FFF0|GGG0|HHH0}
     */
    const __m256i shuffle = _mm256_setr_epi8( //
        4, 5, 6, -1,                          //
        7, 8, 9, -1,                          //
        10, 11, 12, -1,                       //
        13, 14, 15, -1,                       //
        0, 1, 2, -1,                          //
        3, 4, 5, -1,                          //
        6, 7, 8, -1,                          //
        9, 10, 11, -1                         //
    );

    /* Merge the first 8 registers (6 bytes) normally
     * as the AVX2 algorithm needs 4 padding bytes at the start */
    uint8_t val;
    for (int i = 0; i < 8; i++) {
        HLL_DENSE_GET_REGISTER(val, reg_dense, i);
        if (val > reg_raw[i]) {
            reg_raw[i] = val;
        }
    }

    /* Dense to Raw:
     *
     * 4 registers in 3 bytes:
     * {bbaaaaaa|ccccbbbb|ddddddcc}
     *
     * LOAD 32 bytes (32 registers) per iteration:
     * 4(padding) + 12(16 registers) + 12(16 registers) + 4(padding)
     * {XXXX|AAAB|BBCC|CDDD|EEEF|FFGG|GHHH|XXXX}
     *
     * SHUFFLE to:
     * {AAA0|BBB0|CCC0|DDD0|EEE0|FFF0|GGG0|HHH0}
     * {bbaaaaaa|ccccbbbb|ddddddcc|00000000} x8
     *
     * AVX2 is little endian, each of the 8 groups is a little-endian int32.
     * A group (int32) contains 3 valid bytes (4 registers) and a zero byte.
     *
     * extract registers in each group with AND and SHIFT:
     * {00aaaaaa|00000000|00000000|00000000} x8 (<<0)
     * {00000000|00bbbbbb|00000000|00000000} x8 (<<2)
     * {00000000|00000000|00cccccc|00000000} x8 (<<4)
     * {00000000|00000000|00000000|00dddddd} x8 (<<6)
     *
     * merge the extracted registers with OR:
     * {00aaaaaa|00bbbbbb|00cccccc|00dddddd} x8
     *
     * Finally, compute MAX(reg_raw, merged) and STORE it back to reg_raw
     */

    /* Skip 8 registers (6 bytes) */
    const uint8_t *r = reg_dense + 6 - 4;
    uint8_t *t = reg_raw + 8;

    for (int i = 0; i < HLL_REGISTERS / 32 - 1; ++i) {
        __m256i x0, x;
        x0 = _mm256_loadu_si256((__m256i *)r);
        x = _mm256_shuffle_epi8(x0, shuffle);

        __m256i a1, a2, a3, a4;
        a1 = _mm256_and_si256(x, _mm256_set1_epi32(0x0000003f));
        a2 = _mm256_and_si256(x, _mm256_set1_epi32(0x00000fc0));
        a3 = _mm256_and_si256(x, _mm256_set1_epi32(0x0003f000));
        a4 = _mm256_and_si256(x, _mm256_set1_epi32(0x00fc0000));

        a2 = _mm256_slli_epi32(a2, 2);
        a3 = _mm256_slli_epi32(a3, 4);
        a4 = _mm256_slli_epi32(a4, 6);

        __m256i y1, y2, y;
        y1 = _mm256_or_si256(a1, a2);
        y2 = _mm256_or_si256(a3, a4);
        y = _mm256_or_si256(y1, y2);

        __m256i z = _mm256_loadu_si256((__m256i *)t);

        z = _mm256_max_epu8(z, y);

        _mm256_storeu_si256((__m256i *)t, z);

        r += 24;
        t += 32;
    }

    /* Merge the last 24 registers normally
     * as the AVX2 algorithm needs 4 padding bytes at the end */
    for (int i = HLL_REGISTERS - 24; i < HLL_REGISTERS; i++) {
        HLL_DENSE_GET_REGISTER(val, reg_dense, i);
        if (val > reg_raw[i]) {
            reg_raw[i] = val;
        }
    }
}

void hllMergeDenseNEON(uint8_t *reg_raw, const uint8_t *reg_dense) {
    uint8_t *dense_ptr = (uint8_t *)reg_dense;
    uint8_t *raw_ptr = (uint8_t *)reg_raw;

    uint8x16_t idx = {0, 1, 2, 0xFF,
                      3, 4, 5, 0xFF,
                      6, 7, 8, 0xFF,
                      9, 10, 11, 0xFF};

    // Bit masks for extracting specific bit ranges
    uint8x16_t mask1 = vreinterpretq_u8_u32(vdupq_n_u32(0x0000003f)); // Bits 0-5
    uint8x16_t mask2 = vreinterpretq_u8_u32(vdupq_n_u32(0x00000fc0)); // Bits 6-11
    uint8x16_t mask3 = vreinterpretq_u8_u32(vdupq_n_u32(0x0003f000)); // Bits 12-17
    uint8x16_t mask4 = vreinterpretq_u8_u32(vdupq_n_u32(0x00fc0000)); // Bits 18-23

    for (int i = 0; i < HLL_REGISTERS / 16 - 1; ++i) {
        /* Load 16 bytes from dense registers but only the first 12 bytes are processed because they contain
         * 16 registers, which is copied into 16 bytes raw registers.
         * The last 4 bytes are ignored because (1) they do not form a complete number of registers, and do not fit
         * in the 16 bytes. The unprocessed 4 bytes are processed in the next iteration.
         */
        uint8x16_t r = vld1q_u8(dense_ptr);

        /* Reorder bytes based on index mapping
         * Lookup indices
         *From: {AAAB|BBCC|CDDD}
         *To:   {AAA0|BBB0|CCC0|DDD0}
         */
        uint8x16_t x = vqtbl1q_u8(r, idx);

        // Extract and isolate registers
        uint8x16_t a1 = vandq_u8(x, mask1);
        uint8x16_t a2 = vandq_u8(x, mask2);
        uint8x16_t a3 = vandq_u8(x, mask3);
        uint8x16_t a4 = vandq_u8(x, mask4);

        // Align extracted values by shifting left
        uint32x4_t a2_32 = vreinterpretq_u32_u8(a2);
        a2_32 = vshlq_n_u32(a2_32, 2);
        a2 = vreinterpretq_u8_u32(a2_32);

        uint32x4_t a3_32 = vreinterpretq_u32_u8(a3);
        a3_32 = vshlq_n_u32(a3_32, 4);
        a3 = vreinterpretq_u8_u32(a3_32);

        uint32x4_t a4_32 = vreinterpretq_u32_u8(a4);
        a4_32 = vshlq_n_u32(a4_32, 6);
        a4 = vreinterpretq_u8_u32(a4_32);

        // Combine extracted values
        uint8x16_t y1 = vorrq_u8(a1, a2);
        uint8x16_t y2 = vorrq_u8(a3, a4);
        uint8x16_t y = vorrq_u8(y1, y2);

        // Load current raw register values
        uint8x16_t z = vld1q_u8(raw_ptr);

        // Update raw registers with max values
        z = vmaxq_u8(z, y);

        // Store updated values
        vst1q_u8(raw_ptr, z);

        raw_ptr += 16;
        dense_ptr += 12;
    }

    /* Process remaining registers, we do this manually because we don't want to over-read 4 bytes */
    uint8_t val;
    for (int i = HLL_REGISTERS - 16; i < HLL_REGISTERS; i++) {
        HLL_DENSE_GET_REGISTER(val, reg_dense, i);
        if (val > reg_raw[i]) {
            reg_raw[i] = val; // Update raw register if new value is greater
        }
    }
}

int hllMerge(uint8_t *max, robj *hll) {
    struct hllhdr *hdr = objectGetVal(hll);
    int i;
    if (hdr->encoding == HLL_DENSE) {
        hllMergeDense(max, hdr->registers);
    } else {
        uint8_t *p = objectGetVal(hll), *end = p + sdslen(objectGetVal(hll));
        long runlen, regval;
        int valid = 1;

        p += HLL_HDR_SIZE;
        i = 0;
        while (p < end) {
            if (HLL_SPARSE_IS_ZERO(p)) {
                runlen = HLL_SPARSE_ZERO_LEN(p);
                if ((runlen + i) > HLL_REGISTERS) { /* Overflow. */
                    valid = 0;
                    break;
                }
                i += runlen;
                p++;
            } else if (HLL_SPARSE_IS_XZERO(p)) {
                runlen = HLL_SPARSE_XZERO_LEN(p);
                if ((runlen + i) > HLL_REGISTERS) { /* Overflow. */
                    valid = 0;
                    break;
                }
                i += runlen;
                p += 2;
            } else {
                runlen = HLL_SPARSE_VAL_LEN(p);
                regval = HLL_SPARSE_VAL_VALUE(p);
                if ((runlen + i) > HLL_REGISTERS) { /* Overflow. */
                    valid = 0;
                    break;
                }
                while (runlen--) {
                    if (regval > max[i]) max[i] = regval;
                    i++;
                }
                p++;
            }
        }
        if (!valid || i != HLL_REGISTERS) return C_ERR;
    }
    return C_OK;
}

void hllDenseCompressNEON(uint8_t *reg_dense, const uint8_t *reg_raw) {
    /* Shuffle indices for packing bytes of dense registers
     * From: {AAA0|BBB0|CCC0|DDD0}
     * To:   {AAAB|BBCC|CDDD|0000}
     */
    uint8x16_t idx = {
        0, 1, 2,               // Extract bytes from lane 0
        4, 5, 6,               // Extract bytes from lane 1
        8, 9, 10,              // Extract bytes from lane 2
        12, 13, 14,            // Extract bytes from lane 3
        0xFF, 0xFF, 0xFF, 0xFF // Zero out last 4 elements (padding)
    };

    // Bit masks for extracting first 6 bits from every byte within 32-bit lanes
    uint32x4_t mask1 = vdupq_n_u32(0x0000003F); // Extract bits 0-5
    uint32x4_t mask2 = vdupq_n_u32(0x00003F00); // Extract bits 8-13
    uint32x4_t mask3 = vdupq_n_u32(0x003F0000); // Extract bits 16-21
    uint32x4_t mask4 = vdupq_n_u32(0x3F000000); // Extract bits 24-29

    uint8_t *r = (uint8_t *)reg_raw;   // Input pointer
    uint8_t *t = (uint8_t *)reg_dense; // Output pointer

    // Process registers in blocks of 16 using NEON instructions
    // The last 16 registers are processed separately to avoid overwriting, as the final write is 12 bytes.
    for (int i = 0; i < HLL_REGISTERS / 16 - 1; i++) {
        // Load 16 bytes as 4x 32-bit values
        uint32x4_t x = vld1q_u32((uint32_t *)r);

        // Apply masks to extract a single register from every 4 registers, for every lane
        uint32x4_t a1 = vandq_u32(x, mask1);
        uint32x4_t a2 = vandq_u32(x, mask2);
        uint32x4_t a3 = vandq_u32(x, mask3);
        uint32x4_t a4 = vandq_u32(x, mask4);

        // Shift extracted bits to align them properly
        a2 = vshrq_n_u32(a2, 2);
        a3 = vshrq_n_u32(a3, 4);
        a4 = vshrq_n_u32(a4, 6);

        uint32x4_t y1 = vorrq_u32(a1, a2);
        uint32x4_t y2 = vorrq_u32(a3, a4);
        uint32x4_t y = vorrq_u32(y1, y2);

        // Perform a table lookup to shuffle extracted values and align them in 12 bytes
        vst1q_u8(t, vqtbl1q_u8(vreinterpretq_u8_u32(y), idx));

        t += 12;
        r += 16;
    }
    // Handle the remaining registers individually (12 bytes)
    for (int i = HLL_REGISTERS - 16; i < HLL_REGISTERS; i++) {
        HLL_DENSE_SET_REGISTER(reg_dense, i, reg_raw[i]);
    }
}

void hllDenseCompress(uint8_t *reg_dense, const uint8_t *reg_raw) {
#if HAVE_X86_SIMD && HLL_REGISTERS == 16384 && HLL_BITS == 6
    if (HLL_USE_AVX2) {
        hllDenseCompressAVX2(reg_dense, reg_raw);
        return;
    }
#endif

#if HAVE_ARM_NEON && HLL_REGISTERS == 16384 && HLL_BITS == 6
    if (HLL_USE_NEON) {
        hllDenseCompressNEON(reg_dense, reg_raw);
        return;
    }
#endif

    for (int i = 0; i < HLL_REGISTERS; i++) {
        HLL_DENSE_SET_REGISTER(reg_dense, i, reg_raw[i]);
    }
}

int hllEnableSimd(int enable) {
#if SIMD_SUPPORTED
  simd_enabled = enable;
#else
  (void)enable;
#endif
  return (HLL_USE_AVX2 || HLL_USE_NEON) ? 1 : 0;
}

std::string MakeOverflowingSparseHll() {
  // 155486 * 16384 wraps `idx` to a value whose *6 (bits per register) is still
  // negative, so the resulting byte offset is a huge unsigned number.
  constexpr int kXZeroOps = 155486;

  std::string hll;
  hll.reserve(16 + kXZeroOps * 2 + 1);
  hll.append("HYLL");   // magic
  hll.push_back(1);     // encoding = HLL_SPARSE
  hll.append(3, '\0');  // notused
  hll.append(8, '\0');  // cached cardinality
  for (int i = 0; i < kXZeroOps; ++i) {
    hll.push_back('\x7f');  // XZERO, 14-bit length-1 == 16383
    hll.push_back('\xff');
  }
  hll.push_back('\x80');  // VAL: value 1, run length 1
  return hll;
}

std::string MakeDenseHll(absl::FunctionRef<unsigned(int)> value_at) {
  constexpr int kRegisters = 16384;
  constexpr int kBits = 6;

  // One byte of slack: setting the last register touches the byte just past the
  // register array, which is the implicit terminator hyperloglog.c relies on.
  std::vector<uint8_t> buf(getDenseHllSize() + 1, 0);
  CHECK_EQ(createDenseHll({buf.data(), getDenseHllSize()}), 0);

  uint8_t* regs = buf.data() + (getDenseHllSize() - kRegisters * kBits / 8);
  for (int i = 0; i < kRegisters; ++i) {
    const unsigned v = value_at(i) & 63;
    const unsigned byte = i * kBits / 8;
    const unsigned fb = (i * kBits) & 7;
    regs[byte] &= ~(63u << fb);
    regs[byte] |= v << fb;
    regs[byte + 1] &= ~(63u >> (8 - fb));
    regs[byte + 1] |= v >> (8 - fb);
  }
  return std::string(reinterpret_cast<char*>(buf.data()), getDenseHllSize());
}

TEST_F(HllFamilyTest, CorruptedSparseRunLengthOverflow) {
  const string payload = MakeOverflowingSparseHll();
  ASSERT_EQ(Run({"set", "overflow", payload}), "OK");

  // PFCOUNT and PFMERGE decode through convertSparseToDenseHll().
  EXPECT_THAT(Run({"pfcount", "overflow"}), ErrArg(kCorruptedHllError));

  EXPECT_EQ(CheckedInt({"pfadd", "src", "hi"}), 1);
  EXPECT_THAT(Run({"pfmerge", "dest", "overflow", "src"}), ErrArg(kCorruptedHllError));

  // PFADD decodes through hllSparseSet()'s promote path: the value is far above
  // HLL_SPARSE_MAX_BYTES, so the very first insert tries to convert to dense.
  EXPECT_THAT(Run({"pfadd", "overflow", "foo"}), ErrArg(kInvalidHllError));
}

TEST_F(HllFamilyTest, CorruptedSparseTruncatedRun) {
  // XZERO covering 16384 registers followed by another one: the second overruns
  // the register space, and nothing else in the value can make up for it.
  string hll("HYLL", 4);
  hll.push_back(1);
  hll.append(3, '\0');
  hll.append(8, '\0');
  for (int i = 0; i < 2; ++i) {
    hll.push_back('\x7f');
    hll.push_back('\xff');
  }
  ASSERT_EQ(Run({"set", "truncated", hll}), "OK");
  EXPECT_THAT(Run({"pfcount", "truncated"}), ErrArg(kCorruptedHllError));
}

TEST_F(HllFamilyTest, CountMultipleAgreesWithMerge) {
  constexpr int kValuesPerKey = 20000;
  for (int i = 0; i < kValuesPerKey; ++i) {
    Run({"pfadd", "k1", GenerateUniqueValue(i)});
    Run({"pfadd", "k2", GenerateUniqueValue(kValuesPerKey + i)});
  }

  ASSERT_EQ(Run({"pfmerge", "merged", "k1", "k2"}), "OK");
  const int64_t merged = CheckedInt({"pfcount", "merged"});
  EXPECT_EQ(CheckedInt({"pfcount", "k1", "k2"}), merged);

  // Sanity check that the shared estimate is in the right ballpark.
  EXPECT_LT(std::abs(merged - 2.0 * kValuesPerKey) / (2.0 * kValuesPerKey), 0.05);
}

TEST_F(HllFamilyTest, SimdMatchesScalar) {
  if (!hllEnableSimd(1)) {
    GTEST_SKIP() << "no SIMD fast path on this CPU";
  }

  // Three patterns that between them put every value in 0..63 into every
  // position within the 4-registers-per-3-bytes packing group, and that differ
  // per input so the max() in the merge is exercised too.
  ASSERT_EQ(Run({"set", "s1", MakeDenseHll([](int i) -> unsigned { return i % 64; })}), "OK");
  ASSERT_EQ(Run({"set", "s2", MakeDenseHll([](int i) -> unsigned { return (i * 7 + 3) % 64; })}),
            "OK");
  ASSERT_EQ(Run({"set", "s3", MakeDenseHll([](int i) -> unsigned { return (i / 64) % 64; })}),
            "OK");

  ASSERT_EQ(Run({"pfmerge", "simd", "s1", "s2", "s3"}), "OK");
  const int64_t simd_count = CheckedInt({"pfcount", "s1", "s2", "s3"});
  const string simd_merged = Run({"get", "simd"}).GetString();

  ASSERT_EQ(hllEnableSimd(0), 0);
  ASSERT_EQ(Run({"pfmerge", "scalar", "s1", "s2", "s3"}), "OK");
  const int64_t scalar_count = CheckedInt({"pfcount", "s1", "s2", "s3"});
  const string scalar_merged = Run({"get", "scalar"}).GetString();
  hllEnableSimd(1);

  EXPECT_EQ(simd_count, scalar_count);
  EXPECT_EQ(simd_merged, scalar_merged);
}

TEST_F(HllFamilyTest, SparseSetPromotesOnLargeCount) {
  constexpr string_view kPromotingValue = ".K{bTLLX";

  EXPECT_EQ(CheckedInt({"pfadd", "key", kPromotingValue}), 1);
  EXPECT_EQ(CheckedInt({"strlen", "key"}), getDenseHllSize());
  EXPECT_EQ(CheckedInt({"pfcount", "key"}), 1);
}

explicit SimdSelector(benchmark::State& state) {
    const bool want_simd = state.range(0) != 0;
    if (want_simd && hllEnableSimd(1) == 0) {
      state.SkipWithMessage("no AVX2/NEON implementation on this CPU");
      skipped_ = true;
    } else if (!want_simd) {
      hllEnableSimd(0);
    }
  }

explicit MergeInputs(int64_t count) {
    hlls.reserve(count);
    ptrs.reserve(count);
    for (int64_t i = 0; i < count; ++i)
      hlls.push_back(MakeDenseHll([i](int reg) { return BenchRegister(i + 1, reg); }));
    for (string& hll : hlls)
      ptrs.push_back({reinterpret_cast<unsigned char*>(hll.data()), hll.size()});
  }

static void BM_HllMergeDense(benchmark::State& state) {
  SimdSelector simd(state);
  if (simd.skipped())
    return;

  const string dense = MakeDenseHll([](int i) { return BenchRegister(1, i); });
  const uint8_t* regs = DenseRegisters(dense);
  vector<uint8_t> raw(kRegisters, 0);

  while (state.KeepRunning()) {
    hllMergeDense(raw.data(), regs);
  }
  state.SetItemsProcessed(state.iterations() * kRegisters);
}

static void BM_HllDenseCompress(benchmark::State& state) {
  SimdSelector simd(state);
  if (simd.skipped())
    return;

  vector<uint8_t> raw(kRegisters);
  for (int i = 0; i < kRegisters; ++i)
    raw[i] = BenchRegister(1, i);

  // One byte of slack: writing the last register touches the byte just past the
  // register array, the same terminator MakeDenseHll() accounts for.
  vector<uint8_t> dense(kDenseRegBytes + 1, 0);

  while (state.KeepRunning()) {
    hllDenseCompress(dense.data(), raw.data());
  }
  state.SetItemsProcessed(state.iterations() * kRegisters);
}

static void BM_HllDenseCompressUnchained(benchmark::State& state) {
  vector<uint8_t> raw(kRegisters);
  for (int i = 0; i < kRegisters; ++i)
    raw[i] = BenchRegister(1, i);

  vector<uint8_t> dense(kDenseRegBytes + 1, 0);
  auto compress = [&] {
    // 4 registers pack into 3 bytes: {bbaaaaaa|ccccbbbb|ddddddcc}.
    for (int i = 0; i < kRegisters; i += 4) {
      const uint32_t a = raw[i], b = raw[i + 1], c = raw[i + 2], d = raw[i + 3];
      uint8_t* out = dense.data() + i * 6 / 8;
      out[0] = a | (b << 6);
      out[1] = (b >> 2) | (c << 4);
      out[2] = (c >> 4) | (d << 2);
    }
  };

  // Guard against the reference drifting from the real thing.
  vector<uint8_t> expected(kDenseRegBytes + 1, 0);
  hllDenseCompress(expected.data(), raw.data());
  compress();
  CHECK(memcmp(dense.data(), expected.data(), kDenseRegBytes) == 0);

  while (state.KeepRunning()) {
    compress();
  }
  state.SetItemsProcessed(state.iterations() * kRegisters);
}

static void BM_PfMerge(benchmark::State& state) {
  SimdSelector simd(state);
  if (simd.skipped())
    return;

  MergeInputs inputs(state.range(1));
  string out = MakeDenseHll([](int) -> unsigned { return 0; });
  const HllBufferPtr out_ptr{reinterpret_cast<unsigned char*>(out.data()), out.size()};

  while (state.KeepRunning()) {
    CHECK_EQ(pfmerge(inputs.ptrs.data(), inputs.ptrs.size(), out_ptr), 0);
  }
  state.SetItemsProcessed(state.iterations() * state.range(1) * kRegisters);
}

static void BM_PfCountMulti(benchmark::State& state) {
  SimdSelector simd(state);
  if (simd.skipped())
    return;

  MergeInputs inputs(state.range(1));

  while (state.KeepRunning()) {
    benchmark::DoNotOptimize(pfcountMulti(inputs.ptrs.data(), inputs.ptrs.size()));
  }
  state.SetItemsProcessed(state.iterations() * state.range(1) * kRegisters);
}

TEST_F(StreamFamilyTest, XReadBlockIgnoresEntriesBelowRequestedId) {
  Run({"xadd", "foo", "1-0", "k", "v"});

  RespExpr resp;
  auto reader = pp_->at(0)->LaunchFiber(Launch::dispatch, [&] {
    resp = Run({"xread", "block", "0", "streams", "foo", "5-0"});
  });
  ASSERT_TRUE(WaitUntilCondition([&] { return IsConnBlocked("IO0"); }, 500ms));

  // The wake is processed on the shard thread, so give it a window to land before concluding
  // that the reader stayed blocked.
  pp_->at(1)->Await([&] { return Run({"xadd", "foo", "2-0", "k", "v"}); });
  EXPECT_FALSE(WaitUntilCondition([&] { return !IsConnBlocked("IO0"); }, 100ms))
      << "the reader woke on an entry below the requested id";

  pp_->at(1)->Await([&] { return Run({"xadd", "foo", "6-0", "k", "v"}); });
  reader.Join();
  const auto& stream_resp = resp.GetVec()[0].GetVec();
  EXPECT_THAT(stream_resp, ElementsAre("foo", ArrLen(1)));
  EXPECT_THAT(stream_resp[1].GetVec()[0].GetVec(), ElementsAre("6-0", ArrLen(2)));
}

TEST_F(StreamFamilyTest, XReadGroupBlockIgnoresWakeFromRemovedEntry) {
  Run({"xgroup", "create", "foo", "group", "$", "MKSTREAM"});

  RespExpr resp;
  auto reader = pp_->at(0)->LaunchFiber(Launch::dispatch, [&] {
    resp = Run({"xreadgroup", "group", "group", "alice", "block", "0", "streams", "foo", ">"});
  });
  ASSERT_TRUE(WaitUntilCondition([&] { return IsConnBlocked("IO0"); }, 500ms));

  pp_->at(1)->Await([&] {
    Run({"multi"});
    Run({"xadd", "foo", "1-0", "k", "v"});
    Run({"xdel", "foo", "1-0"});
    return Run({"exec"});
  });
  EXPECT_FALSE(WaitUntilCondition([&] { return !IsConnBlocked("IO0"); }, 100ms))
      << "the reader woke on an entry that the same transaction removed";

  pp_->at(1)->Await([&] { return Run({"xadd", "foo", "2-0", "k", "v"}); });
  reader.Join();
  const auto& stream_resp = resp.GetVec()[0].GetVec();
  EXPECT_THAT(stream_resp, ElementsAre("foo", ArrLen(1)));
  EXPECT_THAT(stream_resp[1].GetVec()[0].GetVec(), ElementsAre("2-0", ArrLen(2)));
}

TEST_F(StreamFamilyTest, XReadBlockOnMaxMsId) {
  Run({"xadd", "foo", "1-0", "k", "v"});

  RespExpr resp;
  auto reader = pp_->at(0)->LaunchFiber(Launch::dispatch, [&] {
    resp = Run({"xread", "block", "0", "streams", "foo", "18446744073709551615-0"});
  });
  ASSERT_TRUE(WaitUntilCondition([&] { return IsConnBlocked("IO0"); }, 500ms));

  pp_->at(1)->Await([&] { return Run({"xadd", "foo", "18446744073709551615-2", "k", "v"}); });
  reader.Join();
  const auto& stream_resp = resp.GetVec()[0].GetVec();
  EXPECT_THAT(stream_resp, ElementsAre("foo", ArrLen(1)));
  EXPECT_THAT(stream_resp[1].GetVec()[0].GetVec(),
              ElementsAre("18446744073709551615-2", ArrLen(2)));
}

void RedisReplyBuilder::SendBulkStringBorrowed(const cmn::BorrowedString& bs) {
  ReplyScope scope(this);
  tl_facade_stats->reply_stats.borrowed_string_sent_cnt++;

  auto* ops = cmn::BorrowedStringOps::Get();
  size_t total = ops->DecodedSize(bs);

  DVLOG(1) << "SendBulkBorrowed " << total << " enc=" << unsigned(bs.encoding());
  WritePieces(kLengthPrefix, total, kCRLF);
  if (bs.IsEncoded()) {
    WriteDecodedAscii(bs);
  } else {
    WriteRef(bs.view());
  }
  WritePieces(kCRLF);
}

TEST_F(DflyEngineTest, EvalGetLargeBorrowedStrings) {
  std::string raw(32 * 1024, '\x81');
  std::string ascii(32 * 1024, 'a');

  EXPECT_THAT(Run({"set", "ascii", ascii}), "OK");
  EXPECT_THAT(Run({"set", "raw", raw}), "OK");
  optional<int64_t> ascii_usage = Run({"memory", "usage", "ascii"}).GetInt();
  optional<int64_t> raw_usage = Run({"memory", "usage", "raw"}).GetInt();
  ASSERT_TRUE(ascii_usage);
  ASSERT_TRUE(raw_usage);
  EXPECT_GT(*raw_usage, *ascii_usage);

  EXPECT_THAT(Run({"eval", "return {redis.call('get', KEYS[1]), redis.call('get', KEYS[2])}", "2",
                   "ascii", "raw"}),
              RespElementsAre(ascii, raw));
}

void operator()(const cmn::BorrowedString& bs) {
    // HTTP visitor wants a single contiguous string to JSON-escape. Raw bytes
    // are already user-visible (avoid a copy); packed encodings are decoded
    // once via the shared helper (chunked decoding only matters for iovec
    // sinks).
    absl::StrAppend(&str, JsonEscape(cmn::DecodeToString(bs)));

void InterpreterReplier::SendBulkStringBorrowed(cmn::BorrowedString&& bs) {
  // No streaming sink here: decode into a contiguous string and route through
  // SendBulkString (-> explr_->OnString), rather than RedisReplyBuilder's
  // iovec-based chunked path.
  if (!bs.IsEncoded())
    return SendBulkString(bs.view());

  string decoded = cmn::DecodeToString(bs);
  SendBulkString(string_view{decoded});
}

TEST_F(SearchParserTest, QuotedTagEscapes) {
  auto tag_affix = [this](const string& query) -> string {
    EXPECT_EQ(0, Parse(query));
    AstExpr e = query_driver_.Take();
    EXPECT_TRUE(std::holds_alternative<AstFieldNode>(e));
    const AstNode& tags = *std::get<AstFieldNode>(e).node;
    EXPECT_TRUE(std::holds_alternative<AstTagsNode>(tags));
    const auto& tn = std::get<AstTagsNode>(tags);
    EXPECT_EQ(tn.tags.size(), 1u);
    EXPECT_TRUE(std::holds_alternative<AstTermNode>(tn.tags[0]));
    return std::get<AstTermNode>(tn.tags[0]).affix;
  };

  // Recognized escapes \\ and \" resolve to their single-character values.
  EXPECT_EQ(tag_affix(R"(@t:{"tnt\\backslash"})"), R"(tnt\backslash)");
  EXPECT_EQ(tag_affix(R"(@t:{"tnt\"quote"})"), "tnt\"quote");

  // Characterization: one layer of \X is stripped for any X, mirroring the unquoted make_Tag
  // path, so an unrecognized escape drops its backslash rather than passing through verbatim.
  // This is an intentional policy change from v1.39's verbatim behavior; pinning it keeps a
  // future reader from "restoring" the old semantics.
  EXPECT_EQ(tag_affix(R"(@t:{"ACME\jdoe"})"), "ACMEjdoe");

  // A trailing lone backslash (e.g. a Windows path) must not abort — it previously tripped the
  // DCHECK in UnescapeTerm — and drops the dangling backslash; the doubled form is a literal `\`.
  EXPECT_EQ(tag_affix(R"(@t:{"C:\"})"), "C:");
  EXPECT_EQ(tag_affix(R"(@t:{"C:\\"})"), R"(C:\)");
}

TEST_F(SearchFamilyTest, QuotedTagEscapes) {
  Run({"FT.CREATE", "demo_idx", "ON", "HASH", "PREFIX", "1", "doc:", "SCHEMA", "tags", "TAG"});
  Run({"HSET", "doc:1", "tags", R"(tnt\backslash)"});
  Run({"HSET", "doc:2", "tags", "tnt\"quote"});
  Run({"HSET", "doc:3", "tags", "plain-value"});
  Run({"HSET", "doc:4", "tags", "foo bar"});
  Run({"HSET", "doc:5", "tags", R"(a\b)"});
  Run({"HSET", "doc:6", "tags", "c"});
  Run({"HSET", "doc:7", "tags", R"(C:\)"});
  EXPECT_THAT(Run({"FT.SEARCH", "demo_idx", R"(@tags:{"tnt\\backslash"})", "DIALECT", "2"}),
              AreDocIds("doc:1"));
  EXPECT_THAT(Run({"FT.SEARCH", "demo_idx", R"(@tags:{"tnt\"quote"})", "DIALECT", "2"}),
              AreDocIds("doc:2"));
  EXPECT_THAT(Run({"FT.SEARCH", "demo_idx", R"(@tags:{"plain-value"})", "DIALECT", "2"}),
              AreDocIds("doc:3"));

  // A quoted value may contain spaces, which the bare {foo bar} form cannot express.
  EXPECT_THAT(Run({"FT.SEARCH", "demo_idx", R"(@tags:{"foo bar"})", "DIALECT", "2"}),
              AreDocIds("doc:4"));

  // OR-list of quoted members, each unescaped independently.
  EXPECT_THAT(Run({"FT.SEARCH", "demo_idx", R"(@tags:{"a\\b"|"c"})", "DIALECT", "2"}),
              AreDocIds("doc:5", "doc:6"));

  // Value ending in a backslash: the doubled query matches the stored `C:\`, and the lone-backslash
  // query must not abort the server (it unescapes to `C:`, which matches nothing here).
  EXPECT_THAT(Run({"FT.SEARCH", "demo_idx", R"(@tags:{"C:\\"})", "DIALECT", "2"}),
              AreDocIds("doc:7"));
  EXPECT_THAT(Run({"FT.SEARCH", "demo_idx", R"(@tags:{"C:\"})", "DIALECT", "2"}), kNoResults);
  EXPECT_EQ(Run({"PING"}), "PONG");
}

TEST_F(SearchFamilyTest, QuotedTagEscapesJson) {
  Run({"FT.CREATE", "json_idx", "ON", "JSON", "PREFIX", "1", "jdoc:", "SCHEMA", "$.tag", "AS",
       "tag", "TAG"});
  // JSON unescapes "a\\b" to the stored tag value a\b.
  Run({"JSON.SET", "jdoc:1", "$", R"({"tag":"a\\b"})"});
  EXPECT_THAT(Run({"FT.SEARCH", "json_idx", R"(@tag:{"a\\b"})", "DIALECT", "2"}),
              AreDocIds("jdoc:1"));
}

TEST_F(SearchFamilyTest, QuotedTagEscapesCaseSensitive) {
  Run({"FT.CREATE", "cs_idx", "ON", "HASH", "PREFIX", "1", "cs:", "SCHEMA", "tags", "TAG",
       "CASESENSITIVE"});
  Run({"HSET", "cs:1", "tags", R"(ACME\Admin)"});
  // Exact case matches; wrong case does not.
  EXPECT_THAT(Run({"FT.SEARCH", "cs_idx", R"(@tags:{"ACME\\Admin"})", "DIALECT", "2"}),
              AreDocIds("cs:1"));
  EXPECT_THAT(Run({"FT.SEARCH", "cs_idx", R"(@tags:{"acme\\admin"})", "DIALECT", "2"}), kNoResults);
}

void SendSaveHelp(RedisReplyBuilder* rb, bool is_bgsave) {
  static constexpr string_view kSaveHelp[] = {
      "DF",
      "    Save in dragonfly-specific snapshotting format (default).",
      "RDB",
      "    Save in standard redis rdb format.",
      "CLOUD_URI",
      "    Specifies a cloud storage URI (s3://, gs://, azure://) to save the snapshot.",
      "BASENAME",
      "    The base filename for the snapshot files. <dbfilename> if omitted",
  };

  string format_line = is_bgsave ? "BGSAVE [SCHEDULE]" : "SAVE";
  format_line.append(" [DF|RDB [CLOUD_URI [BASENAME]]]. Sub-options are:");
  vector<string_view> help_arr{format_line};

  if (is_bgsave) {
    help_arr.emplace_back("SCHEDULE");
    help_arr.emplace_back("    Optional. Parsed for client compatibility (no-op).");
  }
  help_arr.insert(help_arr.end(), begin(kSaveHelp), end(kSaveHelp));
  rb->SendSimpleStrArr(help_arr);
}

TEST_F(MultiTest, SquashShardLocalMultiKey) {
  absl::FlagSaver fs;
  SetTestFlag("cluster_mode", "emulated");
  SetTestFlag("experimental_cluster_shard_by_slot", "true");
  ResetService();

  // disable-atomicity => NON_ATOMIC multi => squasher creates SHARD_LOCAL local txs.
  // redis.acall queues the calls for non-atomic squashing. All keys share the {t} hashtag, so the
  // multi-key MSET lands on a single shard and is squashable into one local_tx.
  const char* kScript = R"(--!df flags=disable-atomicity,allow-undeclared-keys
redis.acall('mset', '{t}a', '1', '{t}b', '2', '{t}c', '3')
redis.acall('set', '{t}d', '4')
)";
  auto resp = Run({"eval", kScript, "0"});
  EXPECT_THAT(resp, ArgType(RespExpr::NIL));

  // Guard that the calls really went through non-atomic squashing. Without a flush the shard-local
  // multi-key branch in Transaction::InitByKeys is never reached and the test would pass vacuously.
  EXPECT_GT(GetMetrics().coordinator_stats.eval_squashed_flushes, 0u);

  EXPECT_EQ(Run({"get", "{t}a"}), "1");
  EXPECT_EQ(Run({"get", "{t}c"}), "3");
  EXPECT_EQ(Run({"get", "{t}d"}), "4");
}

static ToolDef make_ma_cmd_tool(const char* name, const char* desc, const QString& context,
                                MaCmdMethod method, const QString& command, QJsonObject props, QStringList required) {
    ToolDef t;
    t.name = name;
    t.description = desc;
    t.category = "ma-analytics";
    t.input_schema.properties = std::move(props);
    t.input_schema.required = std::move(required);
    t.handler = [method, context, command](const QJsonObject& args) -> ToolResult {
        return run_ma_sync(context, [&, method, command]() {
            (fincept::services::ma::MAAnalyticsService::instance().*method)(command, args);
        });
    };
    return t;
}

atic ToolDef make_ma_tool(const char* name, const char* desc, const QString& context,
                            MaMethod method, QJsonObject props, QStringList required) {
    ToolDef t;
    t.name = name;
    t.description = desc;
    t.category = "ma-analytics";
    t.input_schema.properties = std::move(props);
    t.input_schema.required = std::move(required);
    t.handler = [method, context](const QJsonObject& args) -> ToolResult {
        return run_ma_sync(context, [&, method]() {
            (fincept::services::ma::MAAnalyticsService::instance().*method)(args);
        });
    };
    return t;
}

