tRunner::restore_state_from_db() {
    auto db = Database::instance().connection();
    QSqlQuery q(db);
    q.prepare(QStringLiteral(
        "SELECT total_pnl, total_trades, win_rate, max_drawdown, current_position_qty, "
        "current_position_side, current_position_entry FROM algo_metrics WHERE deployment_id = ?"));
    q.addBindValue(deployment_.id);
    if (!q.exec() || !q.next())
        return; // fresh deploy — no prior state

    const QString side_s = q.value("current_position_side").toString();
    const PositionSide side = (side_s == "LONG")    ? PositionSide::Long
                              : (side_s == "SHORT") ? PositionSide::Short
                                                    : PositionSide::None;
    const double qty = q.value("current_position_qty").toDouble();
    const double entry = q.value("current_position_entry").toDouble();

    position_mgr_->restore_state(side, qty, entry, q.value("total_pnl").toDouble(),
                                 q.value("total_trades").toInt(), q.value("win_rate").toDouble(),
                                 q.value("max_drawdown").toDouble());

    if (side != PositionSide::None)
        LOG_INFO("AlgoEngine", QString("Deployment %1: restored open %2 %3 @ %4 across restart")
                                   .arg(deployment_.id, side_s)
                                   .arg(qty, 0, 'f', 0)
                                   .arg(entry, 0, 'f', 2));
}

void PositionManager::restore_state(PositionSide side, double qty, double entry_price,
                                    double total_pnl, int total_trades, double win_rate,
                                    double max_drawdown) {
    QMutexLocker lock(&mutex_);
    position_.side = side;
    position_.quantity = qty;
    position_.entry_price = entry_price;
    position_.highest_since_entry = entry_price; // trailing-stop baseline resets on resume
    position_.lowest_since_entry = entry_price;

    metrics_.total_pnl = total_pnl;
    metrics_.total_trades = total_trades;
    metrics_.win_rate = win_rate;
    metrics_.winning_trades = static_cast<int>(std::lround(win_rate * total_trades / 100.0));
    metrics_.losing_trades = total_trades - metrics_.winning_trades;
    if (metrics_.losing_trades < 0)
        metrics_.losing_trades = 0;
    metrics_.max_drawdown = max_drawdown;
    metrics_.current_position_qty = qty;
    metrics_.current_position_side = position_side_to_string(side);
    metrics_.current_position_entry = entry_price;

    risk_.max_drawdown = max_drawdown;
    risk_.peak_equity = total_pnl > 0 ? total_pnl : 0;
}

double fetch_quote_ltp(const QString& broker_id, const QString& account_id, const QString& symbol,
                       int timeout_ms) {
    if (broker_id.isEmpty() || account_id.isEmpty() || symbol.isEmpty())
        return 0.0;
    auto fut = QtConcurrent::run([broker_id, account_id, symbol]() -> double {
        auto* broker = trading::BrokerRegistry::instance().get(broker_id);
        if (!broker)
            return 0.0;
        auto creds = trading::AccountManager::instance().load_credentials(account_id);
        auto resp = broker->get_quotes(creds, {symbol});
        if (resp.success && resp.data.has_value() && !resp.data->isEmpty())
            return resp.data->first().ltp;
        return 0.0;
    });
    QFutureWatcher<double> watcher;
    QEventLoop loop;
    QObject::connect(&watcher, &QFutureWatcher<double>::finished, &loop, &QEventLoop::quit);
    watcher.setFuture(fut);
    QTimer::singleShot(timeout_ms, &loop, &QEventLoop::quit);
    loop.exec();
    return watcher.isFinished() ? watcher.result() : 0.0;
}

id scan_unreachable(const QJsonArray& conds, const QString& section, double price, QStringList& out) {
    static const QSet<QString> price_inds = {"CLOSE", "OPEN", "HIGH", "LOW", "VWAP"};
    for (const auto& v : conds) {
        const QJsonObject o = v.toObject();
        if (o.contains("children")) {
            scan_unreachable(o.value("children").toArray(), section, price, out);
            continue;
        }
        if (o.value("compare_mode").toString("value") != "value")
            continue;
        const QString ind = o.value("indicator").toString();
        if (!price_inds.contains(ind))
            continue;
        const QString op = o.value("operator").toString();
        const double val = o.value("value").toDouble();
        if (val <= 0)
            continue;
        if (op == "crosses_above" && price > val)
            out << QString("• %1 '%2 crosses above %3' — price %4 is already above; it can never cross up.")
                       .arg(section, ind).arg(val, 0, 'f', 2).arg(price, 0, 'f', 2);
        else if (op == "crosses_below" && price < val)
            out << QString("• %1 '%2 crosses below %3' — price %4 is already below; it can never cross down.")
                       .arg(section, ind).arg(val, 0, 'f', 2).arg(price, 0, 'f', 2);
        else if (std::abs(price - val) / price > 0.25)
            out << QString("• %1 '%2 %3 %4' — threshold is %5% away from price %6.")
                       .arg(section, ind, op).arg(val, 0, 'f', 2)
                       .arg(std::abs(price - val) / price * 100.0, 0, 'f', 0).arg(price, 0, 'f', 2);
    }
}

