void setActivationPolicy(long policy)
{
    auto sharedApp = reinterpret_cast<id (*)(id, SEL)>(objc_msgSend);
    auto setPolicy = reinterpret_cast<void (*)(id, SEL, long)>(objc_msgSend);
    id nsApp = sharedApp(reinterpret_cast<id>(objc_getClass("NSApplication")),
                         sel_registerName("sharedApplication"));
    setPolicy(nsApp, sel_registerName("setActivationPolicy:"), policy);
}

void Flameshot::onWindowVisibilityChanged(QWindow::Visibility newVisibility)
{
    auto* qw = qobject_cast<QWindow*>(sender());
    if (!qw) {
        return;
    }

    if (newVisibility == QWindow::Hidden) {
        qw->setProperty(visibleInDockProperty, false);
        --m_dockIconVisibleCount;
        if (m_dockIconVisibleCount == 0) {
            setActivationPolicyAccessory();
        }
    } else {
        bool windowTrackedInDock = qw->property(visibleInDockProperty).toBool();
        if (!windowTrackedInDock) {
            qw->setProperty(visibleInDockProperty, true);
            ++m_dockIconVisibleCount;
            setActivationPolicyRegular();
        }
    }
}

std::tm make_tm(int year, int month, int day, int hour, int minute) {
    std::tm t;
    std::memset(&t, 0, sizeof(t));
    t.tm_year = year - 1900;
    t.tm_mon = month - 1;
    t.tm_mday = day;
    t.tm_hour = hour;
    t.tm_min = minute;
    t.tm_sec = 0;
    t.tm_isdst = -1;
    std::mktime(&t);
    return t;
}

explicit ScopedTZ(const std::string& tz_name) {
        // save current TZ
#ifdef _WIN32
        char* buf = nullptr;
        size_t len = 0;
        if (_dupenv_s(&buf, &len, "TZ") == 0 && buf != nullptr) {
            original_tz_ = std::string(buf);
            has_original_ = true;
            free(buf);
        }
#else
        const char* tz = std::getenv("TZ");
        if (tz) {
            original_tz_ = tz;
            has_original_ = true;
        }
#endif

        // set new TZ
#ifdef _WIN32
        _putenv_s("TZ", tz_name.c_str());
        _tzset();
#else
        setenv("TZ", tz_name.c_str(), 1);
        tzset();
#endif
    }

~ScopedTZ() {
        // restore original TZ
#ifdef _WIN32
        if (has_original_) {
            _putenv_s("TZ", original_tz_.c_str());
        } else {
            _putenv_s("TZ", "");
        }
        _tzset();
#else
        if (has_original_) {
            setenv("TZ", original_tz_.c_str(), 1);
        } else {
            unsetenv("TZ");
        }
        tzset();
#endif
    }

void InitializeDimTimer() {
        esp_timer_create_args_t args = {
            .callback = [](void* arg) {
                auto self = static_cast<WaveshareEsp32s3TouchAMOLED1inch8*>(arg);
                self->DimTick();
            },
            .arg = this,
            .dispatch_method = ESP_TIMER_TASK,
            .name = "dim_tick",
            .skip_unhandled_events = true,
        };
        ESP_ERROR_CHECK(esp_timer_create(&args, &dim_timer_));
    }

void ApplyDim(bool on) {
        Application::GetInstance().Schedule([this, on]() {
            if (on) {
                ESP_LOGI(TAG, "Dim mode (always-on)");
                GetDisplay()->SetPowerSaveMode(true);
                GetBacklight()->SetBrightness(20);
            } else {
                GetDisplay()->SetPowerSaveMode(false);
                GetBacklight()->RestoreBrightness();
            }
        });
    }

void DimTick() {
        if (!Application::GetInstance().CanEnterSleepMode()) {
            // Activity (conversation, button) — restore display and reset.
            dim_ticks_ = 0;
            if (dimmed_) {
                dimmed_ = false;
                ApplyDim(false);
            }
            return;
        }
        dim_ticks_++;
        if (dim_ticks_ >= kDimSeconds && !dimmed_) {
            dimmed_ = true;
            ApplyDim(true);
        }
    }

id StartDimTimer() {
        if (dim_timer_running_) return;
        dim_ticks_ = 0;
        esp_timer_start_periodic(dim_timer_, 1000000);
        dim_timer_running_ = true;
    }

id StopDimTimer() {
        if (!dim_timer_running_) return;
        esp_timer_stop(dim_timer_);
        dim_timer_running_ = false;
        if (dimmed_) {
            dimmed_ = false;
            ApplyDim(false);
        }
    }

