virtual srs_error_t write(void *buf, size_t size, ssize_t *nwrite) {
        data_.append((const char *)buf, size);
        if (nwrite) {
            *nwrite = (ssize_t)size;
        }
        return srs_success;
    }

static std::vector<uint8_t> ts_collect_pmt_versions(const std::string &data)
{
    std::vector<uint8_t> versions;
    const size_t plen = SRS_TS_PACKET_SIZE;
    // Mirrors TS_PMT_PID in srs_kernel_ts.cpp (a .cpp-local define).
    const int pmt_pid = 0x1001;

    for (size_t off = 0; off + plen <= data.size(); off += plen) {
        const unsigned char *p = (const unsigned char *)data.data() + off;
        if (p[0] != 0x47) {
            continue;
        }
        // PID is the low 13 bits of bytes 1-2.
        int pid = ((p[1] & 0x1F) << 8) | p[2];
        if (pid != pmt_pid) {
            continue;
        }
        int payload_off = 4;
        int afc = (p[3] >> 4) & 0x03;
        if (afc == 0x02) { // adaptation field only
            continue;
        }
        if (afc == 0x03) { // adaptation field + payload
            payload_off += 1 + p[4];
        }
        // Need pointer_field(1) + table_id(1) ... up to the version byte at pos+5,
        // i.e. payload_off + 7 bytes must fit in the packet.
        if ((size_t)(payload_off + 7) > plen) {
            continue;
        }
        // pointer_field then table_id.
        int pos = payload_off;
        pos++; // skip pointer_field
        if (p[pos] != SrsTsPsiIdPms) {
            continue;
        }
        // version/current_next byte: after table_id(1) + section_length(2) + program_number(2)
        int vbyte = p[pos + 5];
        versions.push_back((vbyte >> 1) & 0x1F);
    }
    return versions;
}

VOID TEST(KernelTSTest, PmtVersionIncrementsOnCodecChange)
{
    srs_error_t err;

    MockTsBufferWriter writer;
    SrsTsContext context;

    // Start in "guess has a/v" mode: neither codec is known yet, exactly like a
    // fresh HTTP-TS connection.
    SrsTsContextWriter tscw(&writer, &context, SrsAudioCodecIdForbidden, SrsVideoCodecIdForbidden);

    // 1. First frame is video: announce a video-only PMT (version 0).
    SrsTsMessage *vmsg = new SrsTsMessage();
    vmsg->sid_ = SrsTsPESStreamIdVideoCommon;
    vmsg->dts_ = 0;
    vmsg->pts_ = 0;
    vmsg->PES_packet_length_ = 0;
    const char vdata[] = {0x00, 0x00, 0x00, 0x01, 0x67, 0x42, 0x00, 0x1e};
    vmsg->payload_->append((char *)vdata, sizeof(vdata));

    tscw.set_vcodec(SrsVideoCodecIdAVC);
    HELPER_EXPECT_SUCCESS(tscw.write_video(vmsg));
    srs_freep(vmsg);

    // 2. Then AAC audio arrives: the PMT must be re-announced with a new version.
    SrsTsMessage *amsg = new SrsTsMessage();
    amsg->sid_ = SrsTsPESStreamIdAudioCommon;
    amsg->dts_ = 0;
    amsg->pts_ = 0;
    amsg->PES_packet_length_ = 0;
    // Payload content is irrelevant; only the codec switch drives the PMT refresh.
    const std::string adata = std::string("\xff\xf1\x00\x00\x00\x00\x00", 7);
    amsg->payload_->append((char *)adata.data(), adata.size());

    tscw.set_acodec(SrsAudioCodecIdAAC);
    HELPER_EXPECT_SUCCESS(tscw.write_audio(amsg));
    srs_freep(amsg);

    std::vector<uint8_t> versions = ts_collect_pmt_versions(writer.data_);
    ASSERT_GE((int)versions.size(), 2);
    EXPECT_EQ(0, versions[0]); // first PMT: video only
    EXPECT_EQ(1, versions[1]); // second PMT: gains AAC audio, version bumped

    // 3. Reset (new segment/connection) should restart versioning at 0.
    context.reset();
    MockTsBufferWriter reset_writer;
    SrsTsContextWriter reset_tscw(&reset_writer, &context, SrsAudioCodecIdAAC, SrsVideoCodecIdAVC);

    SrsTsMessage *reset_audio = new SrsTsMessage();
    reset_audio->sid_ = SrsTsPESStreamIdAudioCommon;
    reset_audio->dts_ = 0;
    reset_audio->pts_ = 0;
    reset_audio->PES_packet_length_ = 0;
    reset_audio->payload_->append((char *)adata.data(), adata.size());
    HELPER_EXPECT_SUCCESS(reset_tscw.write_audio(reset_audio));
    srs_freep(reset_audio);

    std::vector<uint8_t> reset_versions = ts_collect_pmt_versions(reset_writer.data_);
    ASSERT_GE((int)reset_versions.size(), 1);
    EXPECT_EQ(0, reset_versions[0]);
}

static const char* get_key_wrap_algo(size_t kek_len)
{
    switch (kek_len)
    {
    case 16:
        return "AES-128";
    case 24:
        return "AES-192";
    case 32:
        return "AES-256";
    }

    return NULL;
}

int crysprBotan_Prng(unsigned char *rn, int len)
{
    if (botan_system_rng_get(rn, len) != BOTAN_FFI_SUCCESS) {
        return -1;
    }

    return 0;
}

int crysprBotan_AES_SetKey(
        int cipher_type,            /* One of HCRYPT_CTX_MODE_[CLRTXT|AESECB|AESCTR] */
        bool bEncrypt,              /* true:encrypt key, false:decrypt key*/
        const unsigned char *kstr,  /* key string */
        size_t kstr_len,            /* kstr length in  bytes (16, 24, or 32 bytes, for AES128, AES192, or AES256) */
        CRYSPR_AESCTX *aes_key)     /* Cryptolib Specific AES key context */
{
    if (!(cipher_type == HCRYPT_CTX_MODE_AESCTR || cipher_type == HCRYPT_CTX_MODE_AESGCM)) {
        return -1;
    }
    if (!(kstr_len == 16 || kstr_len == 24 || kstr_len == 32)) {
        return -1;
    }

    const char* algo = NULL;
    if (cipher_type == HCRYPT_CTX_MODE_AESCTR) {
        if (kstr_len == 16) {
            algo = "CTR(AES-128)";
        }
        else if (kstr_len == 24) {
            algo = "CTR(AES-192)";
        }
        else/* if (kstr_len == 32)*/ {
            algo = "CTR(AES-256)";
        }
    } else if (cipher_type == HCRYPT_CTX_MODE_AESGCM) {
        if (kstr_len == 16) {
            algo = "AES-128/GCM";
        }
        else if (kstr_len == 24) {
            algo = "AES-192/GCM";
        }
        else/* if (kstr_len == 32)*/ {
            algo = "AES-256/GCM";
        }
    }

    if (botan_cipher_init(
        &aes_key->cipher,
        algo,
        bEncrypt ? BOTAN_CIPHER_INIT_FLAG_ENCRYPT : BOTAN_CIPHER_INIT_FLAG_DECRYPT) != BOTAN_FFI_SUCCESS) {
        return -1;
    }

    if (botan_cipher_set_key(
        aes_key->cipher,
        kstr,
        kstr_len) != BOTAN_FFI_SUCCESS) {
        return -1;
    }

    memcpy(aes_key->kstr, kstr, kstr_len);
    aes_key->kstr_len = kstr_len;

    return 0;
}

int crysprBotan_AES_CtrCipher(
    bool bEncrypt,                  /* true:encrypt, false:decrypt */
    CRYSPR_AESCTX *aes_key,         /* CryptoLib AES context */
    unsigned char *iv,              /* iv */
    const unsigned char *indata,    /* src */
    size_t inlen,                   /* src length */
    unsigned char *out_txt)         /* dest buffer[inlen] */
{
    (void)bEncrypt;

    if (botan_cipher_start(
        aes_key->cipher,
        iv,
        16) != BOTAN_FFI_SUCCESS) {
        return -1;
    }

    size_t out_written = 0;
    size_t in_consumed = 0;
    if (botan_cipher_update(
        aes_key->cipher,
        BOTAN_CIPHER_UPDATE_FLAG_FINAL,
        out_txt,
        inlen,
        &out_written,
        indata,
        inlen,
        &in_consumed) != BOTAN_FFI_SUCCESS) {
        return -1;
    }
    if (in_consumed != inlen || out_written != inlen) {
        return -1;
    }

    return 0;
}

int crysprBotan_AES_GCMCipher(
    bool bEncrypt,                  /* true:encrypt, false:decrypt */
    CRYSPR_AESCTX* aes_key,         /* CryptoLib AES context */
    unsigned char* iv,              /* iv */
    const unsigned char* aad,       /* associated data */
    size_t aadlen,                  /* associated data length */
    const unsigned char* indata,    /* src */
    size_t inlen,                   /* src length */
    unsigned char* out_txt,         /* dest buffer[inlen] */
    unsigned char* out_tag)         /* dest auth tag */
{
    if (botan_cipher_set_associated_data(
        aes_key->cipher,
        aad,
        aadlen) != BOTAN_FFI_SUCCESS) {
        return -1;
    }

    if (botan_cipher_start(
        aes_key->cipher,
        iv,
        16) != BOTAN_FFI_SUCCESS) {
        return -1;
    }

    size_t out_written = 0;
    size_t in_consumed = 0;
    if (!bEncrypt) {
        if (botan_cipher_update(
            aes_key->cipher,
            BOTAN_CIPHER_UPDATE_FLAG_FINAL,
            out_txt,
            inlen,
            &out_written,
            indata,
            inlen + HAICRYPT_AUTHTAG_MAX,
            &in_consumed) != BOTAN_FFI_SUCCESS) {
            return -1;
        }
        if (out_written != inlen) {
            return -1;
        }
    } else {
        if (botan_cipher_update(
            aes_key->cipher,
            BOTAN_CIPHER_UPDATE_FLAG_FINAL,
            out_txt,
            inlen + HAICRYPT_AUTHTAG_MAX,
            &out_written,
            indata,
            inlen,
            &in_consumed) != BOTAN_FFI_SUCCESS) {
            return -1;
        }
        if (in_consumed != inlen) {
            return -1;
        }
        memcpy(out_tag, out_txt + inlen, HAICRYPT_AUTHTAG_MAX);
    }

    return 0;
}

static CRYSPR_cb *crysprBotan_Open(CRYSPR_methods *cryspr, size_t max_len)
{
    crysprBotan_cb *aes_data;

    aes_data = (crysprBotan_cb *)crysprHelper_Open(cryspr, sizeof(crysprBotan_cb), max_len);
    if (!aes_data) {
        return NULL;
    }

    CRYSPR_cb *cryspr_cb = &aes_data->ccb;

#ifdef CRYSPR2
    cryspr_cb->aes_kek = &aes_data->aes_kek_buf;        // key encrypting key
    cryspr_cb->aes_sek[0] = &aes_data->aes_sek_buf[0];  // stream encrypting key
    cryspr_cb->aes_sek[1] = &aes_data->aes_sek_buf[1];  // stream encrypting key
#endif
    cryspr_cb->aes_kek->cipher = NULL;
    cryspr_cb->aes_sek[0]->cipher = NULL;
    cryspr_cb->aes_sek[1]->cipher = NULL;

    return cryspr_cb;
}

static int crysprBotan_Close(CRYSPR_cb *cryspr_cb)
{
    if (cryspr_cb->aes_kek->cipher) {
        botan_cipher_destroy(cryspr_cb->aes_kek->cipher);
        cryspr_cb->aes_kek->cipher = NULL;
    }
    if (cryspr_cb->aes_sek[0]->cipher) {
        botan_cipher_destroy(cryspr_cb->aes_sek[0]->cipher);
        cryspr_cb->aes_sek[0]->cipher = NULL;
    }
    if (cryspr_cb->aes_sek[1]->cipher) {
        botan_cipher_destroy(cryspr_cb->aes_sek[1]->cipher);
        cryspr_cb->aes_sek[1]->cipher = NULL;
    }

    return crysprHelper_Close(cryspr_cb);
}

int crysprBotan_KmPbkdf2(
    CRYSPR_cb *cryspr_cb,
    char *passwd,           /* passphrase */
    size_t passwd_len,      /* passphrase len */
    unsigned char *salt,    /* salt */
    size_t salt_len,        /* salt_len */
    int itr,                /* iterations */
    size_t key_len,         /* key_len */
    unsigned char *out)     /* derived key buffer[key_len]*/
{
    (void)cryspr_cb;

    if (botan_pwdhash(
        "PBKDF2(SHA-1)",
        itr,
        0,
        0,
        out,
        key_len,
        passwd,
        passwd_len,
        salt,
        salt_len) != BOTAN_FFI_SUCCESS) {
        return -1;
    }

    return 0;
}

int crysprBotan_KmSetKey(CRYSPR_cb *cryspr_cb, bool bWrap, const unsigned char *kek, size_t kek_len)
{
    return crysprBotan_AES_SetKey(
        HCRYPT_CTX_MODE_AESCTR,
        bWrap,
        kek,
        kek_len,
        CRYSPR_GETKEK(cryspr_cb));
}

int crysprBotan_KmWrap(CRYSPR_cb *cryspr_cb,
		unsigned char *wrap,
		const unsigned char *sek,
        unsigned int seklen)
{
    CRYSPR_AESCTX *aes_key = CRYSPR_GETKEK(cryspr_cb); // key encrypting key

    size_t wraplen = seklen + HAICRYPT_WRAPKEY_SIGN_SZ;
    int ret;
    if ((ret = botan_nist_kw_enc(
        get_key_wrap_algo(aes_key->kstr_len),
        0,
        sek,
        seklen,
        aes_key->kstr,
        aes_key->kstr_len,
        wrap,
        &wraplen)) != BOTAN_FFI_SUCCESS) {
        return -1;
    }

    if (seklen + HAICRYPT_WRAPKEY_SIGN_SZ != wraplen) {
        return -1;
    }

    return 0;
}

int crysprBotan_KmUnwrap(
        CRYSPR_cb *cryspr_cb,
		unsigned char *sek,
		const unsigned char *wrap,
        unsigned int wraplen)
{
    CRYSPR_AESCTX *aes_key = CRYSPR_GETKEK(cryspr_cb); // key encrypting key

    size_t seklen = wraplen - HAICRYPT_WRAPKEY_SIGN_SZ;
    if (botan_nist_kw_dec(
        get_key_wrap_algo(aes_key->kstr_len),
        0,
        wrap,
        wraplen,
        aes_key->kstr,
        aes_key->kstr_len,
        sek,
        &seklen) != BOTAN_FFI_SUCCESS) {
        return -1;
    }

    if (wraplen - HAICRYPT_WRAPKEY_SIGN_SZ != seklen) {
        return -1;
    }

    return 0;
}

CRYSPR_methods *crysprBotan(void)
{
    if (crysprBotan_methods.open) {
        return &crysprBotan_methods;
    }

    crysprInit(&crysprBotan_methods);

    /* CryptoLib Primitive API */
    crysprBotan_methods.prng            = crysprBotan_Prng;
    crysprBotan_methods.aes_set_key     = crysprBotan_AES_SetKey;
    crysprBotan_methods.aes_ctr_cipher  = crysprBotan_AES_CtrCipher;
    crysprBotan_methods.aes_gcm_cipher  = crysprBotan_AES_GCMCipher;

    //--Crypto Session (Top API)
    crysprBotan_methods.open            = crysprBotan_Open;
    crysprBotan_methods.close           = crysprBotan_Close;

    //--Keying material (km) encryption
    crysprBotan_methods.km_pbkdf2       = crysprBotan_KmPbkdf2;
    crysprBotan_methods.km_setkey       = crysprBotan_KmSetKey;
    crysprBotan_methods.km_wrap         = crysprBotan_KmWrap;
    crysprBotan_methods.km_unwrap       = crysprBotan_KmUnwrap;

    return &crysprBotan_methods;
}

int HaiCrypt_UpdateGcm153(HaiCrypt_Handle hhc, unsigned use_gcm_153)
{
    ASSERT(hhc != NULL);
    hcrypt_Session* crypto = hhc;
    if (!crypto)
        return (-1);

    crypto->ctx_pair[0].use_gcm_153 = use_gcm_153;
    crypto->ctx_pair[1].use_gcm_153 = use_gcm_153;
    return (0);
}

int HaiCrypt_GetKeyIndex(HaiCrypt_Handle hhc, unsigned char* in_msg)
{
	hcrypt_Session *crypto = (hcrypt_Session *)hhc;
	int msg_type;

	if ((NULL == crypto)
	||  (NULL == in_msg)) {

		HCRYPT_LOG(LOG_ERR, "%s", "invalid parameters\n");
		return(-1);
	}

	/* Validate HaiCrypt message */
	if (0 > (msg_type = hcryptMsg_SRT_ParseMsg(crypto->msg_info, in_msg))) {
		return(-1);
	}

    if (msg_type != HCRYPT_MSG_PT_KM)
        return -1;

    return hcryptMsg_GetKeyIndex(crypto->msg_info, in_msg);
}

void srt::CUDTSocket::resetAtFork()
{
    m_UDT.resetAtFork();
    resetCond(m_AcceptCond);
}

void srt::CUDTUnited::stopGarbageCollector()
{
    ScopedLock guard(m_GCStartLock);
    if (m_bGCStatus)
    {
        m_bGCStatus = false;
        {
            CUniqueSync gclock (m_GCStopLock, m_GCStopCond);
            m_bClosing = true;
            gclock.notify_all();
        }
        m_GCThread.join();
    }
}

void srt::CUDTUnited::cleanupAllSockets()
{
    for (sockets_t::iterator i = m_Sockets.begin(); i != m_Sockets.end(); ++i)
    {
        CUDTSocket* s = i->second;

#if ENABLE_BONDING
        if (s->m_GroupOf)
        {
            s->removeFromGroup(false);
        }
        // remove from listener's queue
        sockets_t::iterator ls = m_Sockets.find(s->m_ListenSocket);
        if (ls == m_Sockets.end())
        {
            ls = m_ClosedSockets.find(s->m_ListenSocket);
        }
        if (ls != m_ClosedSockets.end())
        {
            ls->second->m_QueuedSockets.erase(s->m_SocketID);
        }
        s->core().closeAtFork();
        s->resetAtFork();
        delete(s);
    }
    m_Sockets.clear();

#if ENABLE_BONDING
    for (groups_t::iterator j = m_Groups.begin(); j != m_Groups.end(); ++j)
    {
        delete j->second;
    }
    m_Groups.clear();
#endif
    for (map<int, CMultiplexer>::iterator i = m_mMultiplexer.begin(); i != m_mMultiplexer.end(); ++i)
    {
        CMultiplexer &multiplexer = i->second;
        multiplexer.resetAtFork();
    }
    m_mMultiplexer.clear();
}

void srt::CUDTUnited::closeAllSockets()
{
    // remove all sockets and multiplexers
    HLOGC(inlog.Debug, log << "GC: GLOBAL EXIT - releasing all pending sockets. Acquiring control lock...");
    {
        // Pre-closing: run over all open sockets and close them.
        SharedLock glock(m_GlobControlLock);
        for (sockets_t::iterator i = m_Sockets.begin(); i != m_Sockets.end(); ++i)
        {
            CUDTSocket* s = i->second;
            s->breakSocket_LOCKED();

#if ENABLE_BONDING
            if (s->m_GroupOf)
            {
                HLOGC(smlog.Debug,
                      log << "@" << s->m_SocketID << " IS MEMBER OF $" << s->m_GroupOf->id()
                          << " (IPE?) - REMOVING FROM GROUP");
                s->removeFromGroup(false);
            }
#endif
        }
    }
    {
        ExclusiveLock glock(m_GlobControlLock);
        for (sockets_t::iterator i = m_Sockets.begin(); i != m_Sockets.end(); ++i)
        {
            CUDTSocket* s = i->second;

            m_ClosedSockets[i->first] = s;

            // remove from listener's queue
            sockets_t::iterator ls = m_Sockets.find(s->m_ListenSocket);
            if (ls == m_Sockets.end())
            {
                ls = m_ClosedSockets.find(s->m_ListenSocket);
                if (ls == m_ClosedSockets.end())
                    continue;
            }

            enterCS(ls->second->m_AcceptLock);
            ls->second->m_QueuedSockets.erase(s->m_SocketID);
            leaveCS(ls->second->m_AcceptLock);
        }
        m_Sockets.clear();

        for (sockets_t::iterator j = m_ClosedSockets.begin(); j != m_ClosedSockets.end(); ++j)
        {
            j->second->m_tsClosureTimeStamp = steady_clock::time_point();
        }

#if ENABLE_BONDING
        for (groups_t::iterator j = m_Groups.begin(); j != m_Groups.end(); ++j)
        {
            SRTSOCKET id = j->second->m_GroupID;
            m_ClosedGroups[id] = j->second;
        }
        m_Groups.clear();
#endif
    }

    HLOGC(inlog.Debug, log << "GC: GLOBAL EXIT - releasing all CLOSED sockets.");
    while (true)
    {
        checkBrokenSockets();

        enterCS(m_GlobControlLock);
        bool empty = m_ClosedSockets.empty();
        leaveCS(m_GlobControlLock);

        if (empty)
            break;

        HLOGC(inlog.Debug, log << "GC: checkBrokenSockets didn't wipe all sockets, repeating after 1s sleep");
        srt::sync::this_thread::sleep_for(milliseconds_from(1));
    }


}

int srt::CUDTUnited::startup()
{
    ScopedLock gcinit(m_InitLock);
    m_iInstanceCount++;
    if (m_bGCStatus)
        return (m_iInstanceCount == 1) ? 1 : 0;
    else
        return startGarbageCollector() ? 0 : -1; 
}

