string FormatLossArray(const vector< pair<int32_t, int32_t> >& lra)
{
    ostringstream os;

    os << "[ ";
    for (vector< pair<int32_t, int32_t> >::const_iterator i = lra.begin(); i != lra.end(); ++i)
    {
        int len = CSeqNo::seqoff(i->first, i->second);
        os << "%" << i->first;
        if (len > 1)
            os << "+" << len;
        os << " ";
    }

    os << "]";
    return os.str();
}

string FormatValue(int value, int factor, const char* unit)
{
    ostringstream out;
    double showval = value;
    showval /= factor;
    out << std::fixed << showval << unit;
    return out.str();
}

ostream& PrintEpollEvent(ostream& os, int events, int et_events)
{
    static pair<int, const char*> const namemap [] = {
        make_pair(SRT_EPOLL_IN, "R"),
        make_pair(SRT_EPOLL_OUT, "W"),
        make_pair(SRT_EPOLL_ERR, "E"),
        make_pair(SRT_EPOLL_UPDATE, "U")
    };
    bool any = false;

    const int N = (int)Size(namemap);

    for (int i = 0; i < N; ++i)
    {
        if (events & namemap[i].first)
        {
            os << "[";
            if (et_events & namemap[i].first)
                os << "^";
            os << namemap[i].second << "]";
            any = true;
        }
    }

    if (!any)
        os << "[]";

    return os;
}

int srt::CCryptoControl::processSrtMsg_KMREQ(
        const uint32_t*, size_t, int, unsigned, // ignore input
        uint32_t pw_srtdata_out[], size_t& w_srtlen)
{
    // It's ok that this is reported as error because this happens in a scenario,
    // when non-encryption-enabled SRT application is contacted by encryption-enabled SRT
    // application which tries to make a security association.
    LOGC(cnlog.Warn, log << "processSrtMsg_KMREQ: Encryption not enabled at compile time - must reject...");
    m_RcvKmState = SRT_KM_S_NOSECRET;
    pw_srtdata_out[SRT_KMR_KMSTATE] = m_RcvKmState;
    w_srtlen = 1;

    return SRT_CMD_KMRSP;
}

int srt::CCryptoControl::processSrtMsg_KMRSP(const uint32_t*, size_t, unsigned)
{
    LOGP(cnlog.Error, "processSrtMsg_KMRSP: Encryption not enabled at compile time; not expected to receive SRT_CMD_KMRSP");
    return SRT_CMD_NONE;
}

