int RcvBufferSizeOptionToValue(int val, int flightflag, int mss)
{
    // Minimum recv buffer size is 32 packets
    const int mssin_size = mss - CPacket::UDP_HDR_SIZE;

    int bufsize;
    if (val > mssin_size * CSrtConfig::DEF_MIN_FLIGHT_PKT)
        bufsize = val / mssin_size;
    else
        bufsize = CSrtConfig::DEF_MIN_FLIGHT_PKT;

    // recv buffer MUST not be greater than FC size
    if (bufsize > flightflag)
        bufsize = flightflag;

    return bufsize;
}

srt::sync::SharedMutex::SharedMutex()
    : m_LockWriteCond()
    , m_LockReadCond()
    , m_Mutex()
    , m_iCountRead(0)
    , m_bWriterLocked(false)
{
    setupCond(m_LockReadCond, "SharedMutex::m_pLockReadCond");
    setupCond(m_LockWriteCond, "SharedMutex::m_pLockWriteCond");
    setupMutex(m_Mutex, "SharedMutex::m_pMutex");
}

srt::sync::SharedMutex::~SharedMutex()
{
    releaseMutex(m_Mutex);
    releaseCond(m_LockWriteCond);
    releaseCond(m_LockReadCond);
}

void srt::sync::SharedMutex::lock()
{
    UniqueLock l1(m_Mutex);
    while (m_bWriterLocked)
        m_LockWriteCond.wait(l1);

    m_bWriterLocked = true;

    while (m_iCountRead)
        m_LockReadCond.wait(l1);
}

bool srt::sync::SharedMutex::try_lock()
{
    UniqueLock l1(m_Mutex);
    if (m_bWriterLocked || m_iCountRead > 0)
        return false;

    m_bWriterLocked = true;
    return true;
}

void srt::sync::SharedMutex::unlock()
{
    ScopedLock lk(m_Mutex);
    m_bWriterLocked = false;

    m_LockWriteCond.notify_all();
}

void srt::sync::SharedMutex::lock_shared()
{
    UniqueLock lk(m_Mutex);
    while (m_bWriterLocked)
        m_LockWriteCond.wait(lk);

    m_iCountRead++;
}

bool srt::sync::SharedMutex::try_lock_shared()
{
    UniqueLock lk(m_Mutex);
    if (m_bWriterLocked)
        return false;

    m_iCountRead++;
    return true;
}

void srt::sync::SharedMutex::unlock_shared()
{
    ScopedLock lk(m_Mutex);

    m_iCountRead--;

    SRT_ASSERT(m_iCountRead >= 0);
    if (m_iCountRead < 0)
        m_iCountRead = 0;

    if (m_bWriterLocked && m_iCountRead == 0)
        m_LockReadCond.notify_one();

}

int srt::sync::SharedMutex::getReaderCount() const
{
    ScopedLock lk(m_Mutex);
    return m_iCountRead;
}

void srt::sync::Condition::reset()
{
    // SRT attempts to safely handle `fork()` in multithreaded environments,
    // even though using `fork()` in such contexts is strongly discouraged.
    // This is because `fork()` only duplicates the calling thread, leaving
    // synchronization primitives (like condition variables) in an
    // undefined or inconsistent state in the child process.
    //
    // To mitigate this, SRT forcefully reinitializes these synchronization
    // primitives post-fork. In POSIX, this is done by overwriting the object
    // with its default-initialized state. In C++11, we achieve the same effect
    // using *placement new* to reconstruct the object in place. This ensures
    // the condition variable is returned to a fresh, "neutral" state,
    // as if it was just created.

    new (&m_cv) std::condition_variable;
}

void Condition::reset()
{

    pthread_cond_t  temp = PTHREAD_COND_INITIALIZER;
    memcpy(&m_cv, (void *) &temp, sizeof(m_cv));
    init();
}

