    raw_a->conn_manager_ = NULL;
    raw_b->conn_manager_ = NULL;
    raw_a->wrapper_ = NULL;
    raw_b->wrapper_ = NULL;
    tcp_network->sendonly_skt_ = NULL;
    mock_session->tcp_network_ = NULL;
    mock_conn_manager->session_to_return_ = NULL;
}

bool SrsStreamPublishTokenManager::is_acquired(const std::string &stream_url)
{
    SrsLocker(&mutex_);

    std::map<std::string, SrsStreamPublishToken *>::iterator it = tokens_.find(stream_url);
    if (it == tokens_.end()) {
        return false;
    }

    SrsStreamPublishToken *token = it->second;
    return token->is_acquired();
}

VOID TEST(ReproduceIssue4656, PublishTokenKeepsPendingLiveSource)
{
    srs_error_t err;

    SrsUniquePtr<SrsLiveSourceManager> manager(new SrsLiveSourceManager());
    HELPER_EXPECT_SUCCESS(manager->initialize());

    SrsUniquePtr<SrsRequest> req(new SrsRequest());
    req->host_ = "localhost";
    req->vhost_ = "test.vhost";
    req->app_ = "live";
    req->stream_ = "pending-publisher";

    SrsSharedPtr<SrsLiveSource> source;
    HELPER_EXPECT_SUCCESS(manager->fetch_or_create(req.get(), source));

    // Make the inactive source eligible for immediate cleanup.
    source->stream_die_at_ = srs_time_now_cached() - 10 * SRS_UTIME_MINUTES;
    EXPECT_TRUE(source->stream_is_dead());

    SrsStreamPublishTokenManager tokens;
    SrsStreamPublishTokenManager *previous_tokens = _srs_stream_publish_tokens;
    _srs_stream_publish_tokens = &tokens;

    SrsStreamPublishToken *token = NULL;
    HELPER_EXPECT_SUCCESS(tokens.acquire_token(req.get(), token));

    // The pending publisher token pins the source in the manager.
    HELPER_EXPECT_SUCCESS(manager->notify(0, 0, 0));
    EXPECT_EQ(1, (int)manager->pool_.size());
    EXPECT_EQ(source.get(), manager->fetch(req.get()).get());

    // Once the pending publisher leaves, normal cleanup resumes.
    srs_freep(token);
    HELPER_EXPECT_SUCCESS(manager->notify(0, 0, 0));
    EXPECT_EQ(0, (int)manager->pool_.size());

    _srs_stream_publish_tokens = previous_tokens;
}

VOID TEST(StreamTokenTest, QueryTokenAcquisition)
{
    srs_error_t err;

    SrsStreamPublishTokenManager manager;
    MockStreamTokenRequest req("/live/stream1");

    EXPECT_FALSE(manager.is_acquired("/live/stream1"));

    SrsStreamPublishToken *token = NULL;
    HELPER_EXPECT_SUCCESS(manager.acquire_token(&req, token));
    EXPECT_TRUE(manager.is_acquired("/live/stream1"));
    EXPECT_FALSE(manager.is_acquired("/live/stream2"));

    srs_freep(token);
    EXPECT_FALSE(manager.is_acquired("/live/stream1"));
}

static void* coroutine_stack_addr(void* arg)
{
    int local_var = 42;
    // Write our stack variable address back to the caller.
    *(uintptr_t*)arg = (uintptr_t)&local_var;
    return NULL;
}

VOID TEST(LearnKB, CoroutineRunsOnSeparateStack)
{
    uintptr_t primordial_stack_addr = 0;
    uintptr_t coroutine_stack = 0;

    // Capture primordial thread's stack address.
    int local = 0;
    primordial_stack_addr = (uintptr_t)&local;

    st_thread_t trd = st_thread_create(coroutine_stack_addr, &coroutine_stack, 1, 0);
    ASSERT_TRUE(trd != NULL);
    st_thread_join(trd, NULL);

    ASSERT_NE((uintptr_t)0, coroutine_stack);

    // The coroutine's stack should be far from the primordial stack.
    // Default stack is 128KB, so the difference should be at least that much.
    uintptr_t diff = (primordial_stack_addr > coroutine_stack)
        ? (primordial_stack_addr - coroutine_stack)
        : (coroutine_stack - primordial_stack_addr);
    EXPECT_GT(diff, (uintptr_t)4096) << "Coroutine stack should be on a separate heap-allocated stack";
}

static void* coroutine_preserve_local(void* arg)
{
    int id = *(int*)arg;
    int local_state = id * 1000;

    // Yield to let other coroutines run.
    st_usleep(0);

    // After resume, local_state should be intact — it lives on our own stack.
    local_state += 1;

    // Write result back.
    *(int*)arg = local_state;
    return NULL;
}

ID TEST(LearnKB, LocalStatePreservedAcrossYield)
{
    int a = 1, b = 2, c = 3;
    st_thread_t t1 = st_thread_create(coroutine_preserve_local, &a, 1, 0);
    st_thread_t t2 = st_thread_create(coroutine_preserve_local, &b, 1, 0);
    st_thread_t t3 = st_thread_create(coroutine_preserve_local, &c, 1, 0);
    ASSERT_TRUE(t1 && t2 && t3);

    st_thread_join(t1, NULL);
    st_thread_join(t2, NULL);
    st_thread_join(t3, NULL);

    // Each coroutine computed: id * 1000 + 1
    EXPECT_EQ(1001, a);
    EXPECT_EQ(2001, b);
    EXPECT_EQ(3001, c);
}

atic void* coroutine_yield_order(void* arg)
{
    int my_order = *(int*)arg;

    // Wait until it's our turn.
    while (g_counter < my_order) {
        st_usleep(0);
    }

    // It's our turn — increment.
    g_counter++;
    return NULL;
}

VO

TEST(LearnKB, YieldOrderPreserved)
{
    g_counter = 0;

    int order0 = 0, order1 = 1, order2 = 2;
    st_thread_t t0 = st_thread_create(coroutine_yield_order, &order0, 1, 0);
    st_thread_t t1 = st_thread_create(coroutine_yield_order, &order1, 1, 0);
    st_thread_t t2 = st_thread_create(coroutine_yield_order, &order2, 1, 0);
    ASSERT_TRUE(t0 && t1 && t2);

    st_thread_join(t0, NULL);
    st_thread_join(t1, NULL);
    st_thread_join(t2, NULL);

    EXPECT_EQ(3, g_counter);
}

//

coroutine_retval(void* arg)
{
    int input = *(int*)arg;
    st_usleep(0);
    // Return a computed value as void*.
    return (void*)(intptr_t)(input * input);
}

VOID TEST(

arnKB, ReturnValueThroughJoin)
