    ASSERT_TRUE(tt1 != NULL);

    ST_COROUTINE_JOIN(tt1, tt1_err);
    ST_EXPECT_SUCCESS(tt1_err);

    int r0 = st_cond_destroy(cond);
    EXPECT_EQ(0, r0);
}

