  McpParserConfig config;

  EXPECT_EQ(config.getNameAttributePath("tools/call"), "params.name");
  EXPECT_EQ(config.getNameAttributePath("prompts/get"), "params.name");
  EXPECT_EQ(config.getNameAttributePath("resources/read"), "params.uri");
  EXPECT_EQ(config.getNameAttributePath("tasks/get"), "params.taskId");
  EXPECT_EQ(config.getNameAttributePath("tasks/update"), "params.taskId");
  EXPECT_EQ(config.getNameAttributePath("tasks/cancel"), "params.taskId");
  EXPECT_EQ(config.getNameAttributePath("logging/setLevel"), "");
}

absl::Status validatePathSyntax(absl::string_view path) {
  if (path.empty()) {
    return absl::InvalidArgumentError("extract_field_spec: path must not be empty");
  }
  if (path.front() == '.') {
    return absl::InvalidArgumentError("extract_field_spec: path must not start with '.'");
  }
  if (path.back() == '.') {
    return absl::InvalidArgumentError("extract_field_spec: path must not end with '.'");
  }
  // '\' is reserved for a future escape syntax for document keys containing
  // '.', '[', ']' Rejecting it now keeps that extension non-breaking.
  if (path.find('\\') != absl::string_view::npos) {
    return absl::InvalidArgumentError(
        "extract_field_spec: '\\' is reserved for future escape syntax");
  }
  return absl::OkStatus();
}

absl::Status appendSegment(std::vector<Segment>& segments, Segment segment, int max_depth) {
  if (max_depth > 0 && segments.size() >= static_cast<size_t>(max_depth)) {
    return absl::InvalidArgumentError(absl::StrCat("extract_field_spec: path depth ",
                                                   segments.size() + 1,
                                                   " exceeds maximum supported depth ", max_depth));
  }
  segments.push_back(std::move(segment));
  return absl::OkStatus();
}

sl::StatusOr<std::vector<Segment>> parse(absl::string_view path) {
    path_ = path;
    std::vector<Segment> segments;
    for (size_t i = 0; i < path_.size(); ++i) {
      if (auto status = consume(i, segments); !status.ok()) {
        return status;
      }
    }
    if (in_array_) {
      return absl::InvalidArgumentError("extract_field_spec: unterminated '[' in path");
    }
    if (auto status = flushKey(path_.size(), segments); !status.ok()) {
      return status;
    }
    if (segments.empty()) {
      return absl::InvalidArgumentError("extract_field_spec: path contains no segments");
    }
    return segments;
  }

sl::Status consume(size_t i, std::vector<Segment>& segments) {
    switch (path_[i]) {
    case '[':
      return openArray(i, segments);
    case ']':
      return closeArray(segments);
    case '.':
      return separator(i, segments);
    default:
      return keyCharacter(i);
    }
  }

sl::Status openArray(size_t i, std::vector<Segment>& segments) {
    if (in_array_) {
      return absl::InvalidArgumentError("extract_field_spec: nested '[' in path");
    }
    // '.' immediately before '[' is invalid: the canonical pattern-path
    // syntax never contains '.[]' — '[]' always directly follows the parent dict key.
    if (i > 0 && path_[i - 1] == '.') {
      return absl::InvalidArgumentError(
          "extract_field_spec: '.' before '[' is not valid; use 'key[]' not 'key.[]'");
    }
    if (auto status = flushKey(i, segments); !status.ok()) {
      return status;
    }
    in_array_ = true;
    return absl::OkStatus();
  }

::Status closeArray(std::vector<Segment>& segments) {
    if (!in_array_) {
      return absl::InvalidArgumentError("extract_field_spec: unexpected ']' in path");
    }
    if (auto status = appendSegment(segments, Segment{"", /*is_array_element=*/true}, max_depth_);
        !status.ok()) {
      return status;
    }
    in_array_ = false;
    return absl::OkStatus();
  }

::Status separator(size_t i, std::vector<Segment>& segments) {
    if (in_array_) {
      return absl::InvalidArgumentError("extract_field_spec: '.' inside '[]' in path");
    }
    if (!has_key_ && i > 0 && path_[i - 1] == '.') {
      return absl::InvalidArgumentError(
          absl::StrCat("extract_field_spec: consecutive '.' at position ", i, " in path"));
    }
    return flushKey(i, segments);
  }

::Status keyCharacter(size_t i) {
    if (in_array_) {
      // Index-based addressing (e.g. "[42]") is intentionally unsupported.
      // Path specs are structural patterns: '[]' means "every element" because
      // LLM/MCP arrays (messages[], choices[], result.content[]) are homogeneous
      // lists where every element is processed.
      // We can implement index-based addressing if needed in the future.
      return absl::InvalidArgumentError(
          "extract_field_spec: only '[]' wildcard is supported, not '[...]'");
    }
    // A key may not start directly after ']': the canonical pattern-path
    // syntax always has a '.' separator between an array wildcard and a
    // following dict key ("a[].b", never "a[]b").
    if (i > 0 && path_[i - 1] == ']') {
      return absl::InvalidArgumentError("extract_field_spec: missing '.' between ']' and key");
    }
    if (!has_key_) {
      segment_start_ = i;
      has_key_ = true;
    }
    return absl::OkStatus();
  }

::Status flushKey(size_t end, std::vector<Segment>& segments) {
    if (!has_key_) {
      return absl::OkStatus();
    }
    has_key_ = false;
    return appendSegment(segments,
                         Segment{std::string(path_.substr(segment_start_, end - segment_start_)),
                                 /*is_array_element=*/false},
                         max_depth_);
  }

::StatusOr<ExtractFieldSpec> parseExtractFieldSpec(absl::string_view path, int max_depth) {
  if (absl::Status status = validatePathSyntax(path); !status.ok()) {
    return status;
  }
  absl::StatusOr<std::vector<Segment>> segments = ExtractFieldSpecParser(max_depth).parse(path);
  if (!segments.ok()) {
    return segments.status();
  }
  ExtractFieldSpec out;
  out.segments = *std::move(segments);
  return out;
}

ab

::Status ParserConfig::validate() const {
  if (capture_all_scalars && !extract_fields.empty()) {
    return absl::InvalidArgumentError("parser_config: capture_all_scalars and extract_fields are "
                                      "mutually exclusive; set at most one extraction mode");
  }
  return absl::OkStatus();
}

}

ol onStringChunk(absl::string_view, int, absl::string_view chunk) override {
    const size_t projected = pending_.size() + chunk.size();
    if ((max_per_scalar_bytes_ > 0 && projected > max_per_scalar_bytes_) ||
        (max_total_scalar_bytes_ > 0 && total_captured_ + projected > max_total_scalar_bytes_)) {
      over_budget_ = true;
      pending_.clear();
      return false; // reject this value — no further chunks, no record
    }
    pending_.append(chunk.data(), chunk.size());
    return true;
  }
  v

closeStringCapture(absl::string_view key, int, size_t) override {
    if (over_budget_) {
      over_budget_ = false;
      return;
    }
    record(key, pending_);
    pending_.clear();
  }
  a

::Status onNumber(absl::string_view key, absl::string_view raw, int, size_t,
                        size_t) override {
    record(key, raw);
    return absl::OkStatus();
  }
  a

::Status onBoolean(absl::string_view key, bool value, int, size_t, size_t) override {
    record(key, value ? "true" : "false");
    return absl::OkStatus();
  }
  v

record(absl::string_view key, absl::string_view value) {
    if (max_total_scalar_bytes_ > 0 && total_captured_ + value.size() > max_total_scalar_bytes_) {
      return; // reject: recording would exceed the body-wide budget
    }
    total_captured_ += value.size();
    fields_.push_back({std::string(key), std::string(value)});
  }

(CaptureAllScalarsTest, CapturesEveryScalarWithoutPathTracking) {
  CaptureAllScalarsHandler h;
  WuffsJsonCursor cursor(h);
  constexpr absl::string_view json = R"({"model":"m","max_tokens":5,"stream":false,)"
                                     R"("id":null,"params":{"name":"n"}})";
  ASSERT_TRUE(cursor.feed(json, /*closed=*/true).ok());
  using F = CaptureAllScalarsHandler::Fields;
  EXPECT_EQ(
      h.fields(),
      (F{{"model", "m"}, {"max_tokens", "5"}, {"stream", "false"}, {"id", "null"}, {"name", "n"}}));
}

//

(CaptureAllScalarsTest, CapturesAtAllDepthsThroughBound) {
  constexpr int bound = WuffsJsonCursor::kMaxTrackedDepth - 1; // 16

  // {"d1":"v1","nest":{"d2":"v2","nest":{...{"d16":"v16"}...}}}
  std::string json = "{";
  for (int d = 1; d <= bound; ++d) {
    json += "\"d" + std::to_string(d) + "\":\"v" + std::to_string(d) + "\"";
    if (d < bound) {
      json += ",\"nest\":{";
    }
  }
  json += std::string(bound - 1, '}') + "}";

  CaptureAllScalarsHandler::Fields expected;
  for (int d = 1; d <= bound; ++d) {
    expected.push_back({"d" + std::to_string(d), "v" + std::to_string(d)});
  }

  CaptureAllScalarsHandler h;
  WuffsJsonCursor cursor(h);
  ASSERT_TRUE(cursor.feed(json, /*closed=*/true).ok());
  EXPECT_EQ(h.fields(), expected);
}

