void onContainerOpen(absl::string_view key, bool is_dict, int depth, size_t) override {
    if (depth <= kMaxDepth) {
      is_array_[depth] = !is_dict;
      array_index_[depth] = 0;
      push_key_[depth] = std::string(key);
    }
  }

void onContainerClose(int depth, size_t) override {
    // Advance the parent array's element counter when a child container closes.
    if (depth > 1 && depth - 1 <= kMaxDepth && is_array_[depth - 1]) {
      ++array_index_[depth - 1];
    }
  }

void record(absl::string_view key, int depth) {
    std::string path;
    for (int d = 1; d <= depth; ++d) {
      if (!is_array_[d]) {
        continue;
      }
      if (!push_key_[d].empty()) {
        if (!path.empty()) {
          path += '.';
        }
        path += push_key_[d];
      }
      path += arraySegment(d);
    }
    if (!key.empty()) {
      if (!path.empty()) {
        path += '.';
      }
      path += std::string(key);
    }
    paths.push_back(std::move(path));
    // Advance this depth's array index after recording a scalar element.
    if (depth <= kMaxDepth && is_array_[depth]) {
      ++array_index_[depth];
    }
  }

absl::Status RouteConfigUpdateReceiverImpl::onRdsUpdate(const Protobuf::Message& rc,
                                                        const std::string& version_info) {
    // The route configuration is unchanged, so there is nothing to build, warm up or publish. An
    // update that is still warming up is deliberately left alone.
    return absl::OkStatus();
  return absl::OkStatus();
  // Mark that we have received at least one valid route configuration update.
  initialized_ = true;

absl::Status RouteConfigUpdateReceiverImpl::onRdsUpdate(const Protobuf::Message& rc,
                                                        const std::string& version_info) {
    // The route configuration is unchanged, so there is nothing to build, warm up or publish. An
    // update that is still warming up is deliberately left alone.
    return absl::OkStatus();
  std::unique_ptr<VirtualHostMap> rds_virtual_hosts;
    rds_virtual_hosts = std::make_unique<VirtualHostMap>();
      rds_virtual_hosts->emplace(vhost.name(), vhost);
      rebuildRouteConfigVirtualHosts(*rds_virtual_hosts, *vhds_virtual_hosts_, *new_route_config);

  std::string update_id = fmt::format("rds {}:{}", new_route_config->name(), version_info);
  // The init manager is kept local until the new route configuration is known to be built without
  // throwing, so that a rejected update leaves a previous update that is still warming up alone.
  auto update_init_manager = base_.warmer_.createInitManager(update_id);
  auto config =
      config_traits_.createConfig(*new_route_config, factory_context_, *update_init_manager,
                                  false /* not validate unknown cluster */);

  // No exception, the route configuration is valid, now we can try to create VHDS if necessary.
  const bool vhds_configuration_changed = new_vhds_config_hash != last_vhds_config_hash_;

  // Captured here because the proto is moved into the state below, before it is used to decide
  // what happens to the VHDS subscription.
  const bool has_vhds = new_route_config->has_vhds();

  std::unique_ptr<Init::Manager> vhds_noop_init_manager;
  std::unique_ptr<Init::Watcher> vhds_noop_init_watcher;
  VhdsSubscriptionPtr new_vhds_subscription;
  if (has_vhds) {
    if (!base_.initialized_) {
      // We are still waiting for the first valid route configuration update but received a
      // different RDS update again. Then always create a new subscription because the previous init
      // manager will be dropped and we need add the VHDS subscription to the new init manager.
      auto subscription_or_error = createVhdsSubscription(*new_route_config, *update_init_manager);
      RETURN_IF_NOT_OK_REF(subscription_or_error.status());
      new_vhds_subscription = std::move(subscription_or_error.value());
    } else if (vhds_configuration_changed || vhds_subscription_ == nullptr) {
      // We have received the first valid route configuration update and the VHDS configuration has
      // changed. Then create a new subscription but use a noop init manager for this subscription
      // to avoid blocking the main init manager.
      // This is for backward compatibility: the previous implementation didn't block the new RDS
      // update if the updated VHDS subscription was not ready.
      vhds_noop_init_manager = std::make_unique<Init::ManagerImpl>(
          fmt::format("VHDS noop init manager for {}", new_route_config->name()));
      vhds_noop_init_watcher = std::make_unique<Init::WatcherImpl>(
          fmt::format("VHDS noop init watcher for {}", new_route_config->name()), []() {});
      auto subscription_or_error =
          createVhdsSubscription(*new_route_config, *vhds_noop_init_manager);
      RETURN_IF_NOT_OK_REF(subscription_or_error.status());
      new_vhds_subscription = std::move(subscription_or_error.value());
    }
    // Otherwise the VHDS configuration is unchanged and its subscription is still around, so that
    // subscription is kept: it is the one that is delivering the virtual hosts of the route
    // configuration that is being updated here.
  }

  // The new route configuration and VHDS subscription have been built without error, now we can
  // update the state and start warming up.
  base_.updateState(std::move(new_route_config), new_hash, version_info, std::move(config),
                    std::move(update_init_manager), std::move(update_id));

  // Now, the state is updated and previous warming update is aborted (if any), we can update the
  // VHDS subscription here. So the destruction of the previous subscription will not bring any
  // side effect.
  if (new_vhds_subscription != nullptr) {
    vhds_subscription_ = std::move(new_vhds_subscription);
  } else if (!has_vhds) {
    // This route configuration doesn't use VHDS, so the subscription of a previous one goes away.
    vhds_subscription_.reset();
  }
  rds_virtual_hosts_ = std::move(rds_virtual_hosts);


  if (vhds_noop_init_manager != nullptr) {
    vhds_noop_init_manager->initialize(*vhds_noop_init_watcher);
  }

  return absl::OkStatus();
absl::StatusOr<VhdsSubscriptionPtr> RouteConfigUpdateReceiverImpl::createVhdsSubscription(
    const envoy::config::route::v3::RouteConfiguration& route_config, Init::Manager& init_manager) {
  return VhdsSubscription::createVhdsSubscription(route_config, factory_context_, stat_prefix_,
                                                  *this, init_manager);
}

absl::StatusOr<VhdsSubscriptionPtr> RouteConfigUpdateReceiverImpl::createVhdsSubscription(
    const envoy::config::route::v3::RouteConfiguration& route_config, Init::Manager& init_manager) {
  return VhdsSubscription::createVhdsSubscription(route_config, factory_context_, stat_prefix_,
                                                  *this, init_manager);
}

TEST_F(RdsWarmingTest, DestructionWhileWarmingDoesNotPublishTheWarmingUpdate) {
  config_traits_.ready_on_destruction_ = true;
  createProvider();

  init_watcher_.expectReady().Times(0);
  EXPECT_TRUE(pushUpdate(routeConfig("1", "foo")).ok());
  ASSERT_EQ(1, config_traits_.configs_.size());
  EXPECT_TRUE(receiver().configWarming());
  EXPECT_EQ(0, configReloads());
  ::testing::Mock::VerifyAndClearExpectations(&init_watcher_);

  // Hand the only remaining reference to the route configuration over to the receiver, so that the
  // resource that is warming up is destroyed together with it.
  config_traits_.configs_.clear();

  // The subscription signals readiness as it is destroyed, so that nothing keeps warming with it.
  init_watcher_.expectReady();
  provider_.reset();
  EXPECT_EQ(0, configReloads());
}

static Protobuf::RepeatedPtrField<envoy::service::discovery::v3::Resource>
  vhdsResources(const std::string& name, const std::string& domain) {
    Protobuf::RepeatedPtrField<envoy::service::discovery::v3::Resource> resources;
    auto* added = resources.Add();
    added->set_name(name);
    added->set_version("1");
    std::ignore = added->mutable_resource()->PackFrom(
        TestUtility::parseYaml<envoy::config::route::v3::VirtualHost>(fmt::format(R"EOF(
name: {}
domains: ["{}"]
routes:
- match: {{ prefix: "/" }}
  route: {{ cluster: "foo" }}
)EOF",
                                                                                  name, domain)));
    return resources;
  }

static std::string vhdsRdsConfigJson(absl::string_view version,
                                       absl::string_view vhost_name = "foo") {
  "version_info": "{0}",
          "name": "{1}",
          "domains": ["{1}"],
          "routes": [{{"match": {{"prefix": "/{1}"}}, "route": {{"cluster": "foo"}}}}]
                       version, vhost_name);
  // The route configuration configures VHDS, so it isn't published until the initial VHDS fetch
  // has landed, and this subscription stays unready until then.
  EXPECT_CALL(init_watcher_, ready()).Times(0);
  EXPECT_FALSE(rds_->configCast()->usesVhds());
  ::testing::Mock::VerifyAndClearExpectations(&init_watcher_);
  Envoy::Config::SubscriptionCallbacks* vhds_callbacks =
      server_factory_context_.cluster_manager_.subscription_factory_.callbacks_;
  ASSERT_NE(rds_callbacks_, vhds_callbacks);

  // Landing the initial VHDS fetch publishes the route configuration.
  const auto vhds_resources = vhdsResources("bar", "bar");
  const auto decoded_vhds_resources =
      TestUtility::decodeResources<envoy::config::route::v3::VirtualHost>(vhds_resources);
  EXPECT_CALL(init_watcher_, ready());
  EXPECT_OK(vhds_callbacks->onConfigUpdate(decoded_vhds_resources.refvec_, {}, "1"));

  EXPECT_TRUE(rds_->configCast()->usesVhds());

  // The VHDS subscription was created, so it is now the most recently created subscription. This
  // subscription has already published a route configuration, so the update goes live right away
  // and the VHDS subscription warms up with a throwaway init manager rather than holding the live
  // route configuration back until its initial fetch lands.
  Envoy::Config::SubscriptionCallbacks* vhds_callbacks =
      server_factory_context_.cluster_manager_.subscription_factory_.callbacks_;
  EXPECT_NE(rds_callbacks_, vhds_callbacks);
  const auto vhds_resources = vhdsResources("bar", "bar");
  const auto decoded_vhds_resources =
      TestUtility::decodeResources<envoy::config::route::v3::VirtualHost>(vhds_resources);
  EXPECT_OK(vhds_callbacks->onConfigUpdate(decoded_vhds_resources.refvec_, {}, "2"));
  EXPECT_TRUE(rds_->configCast()->usesVhds());
  // Not published yet: the route configuration waits for the initial VHDS fetch.
  EXPECT_EQ(0UL, scope_.counter("foo.rds.foo_route_config.config_reload").value());
  // The initial VHDS fetch publishes the route configuration that was waiting for it.
  const auto first_vhds_resources = vhdsResources("bar", "bar");
  const auto first_decoded_vhds_resources =
      TestUtility::decodeResources<envoy::config::route::v3::VirtualHost>(first_vhds_resources);
  EXPECT_OK(vhds_callbacks->onConfigUpdate(first_decoded_vhds_resources.refvec_, {}, "2"));
  EXPECT_EQ(1UL, scope_.counter("foo.rds.foo_route_config.config_reload").value());
  // Deliver a second VHDS update through the same subscription.
  const auto second_vhds_resources = vhdsResources("baz", "baz");
  const auto second_decoded_vhds_resources =
      TestUtility::decodeResources<envoy::config::route::v3::VirtualHost>(second_vhds_resources);
  EXPECT_OK(vhds_callbacks->onConfigUpdate(second_decoded_vhds_resources.refvec_, {}, "3"));

  // The VhdsSubscription survived delivering its own updates, i.e. it wasn't re-created and
  // destroyed while its onConfigUpdate() was on the stack.
  EXPECT_EQ(2UL, scope_.counter("foo.rds.vhds.foo_route_config.config_reload").value());
  // The RDS publishing path ran for each VHDS update, which is what propagates the rebuilt route
// An RDS update that leaves the VHDS configuration unchanged keeps the VHDS subscription that is
// already running: that subscription is the one delivering the virtual hosts of the route
// configuration that is being updated.
TEST_F(RdsImplTest, RdsUpdateWithUnchangedVhdsKeepsTheVhdsSubscription) {
  setup();

  // Exactly one VHDS subscription is created for all of the RDS updates below, i.e. the first one
  // creates it and the later ones neither re-create nor drop it.
  EXPECT_CALL(server_factory_context_.cluster_manager_.subscription_factory_,
              subscriptionFromConfigSource(_, _, _, _, _, _));

  auto first_rds_response =
      TestUtility::parseYaml<envoy::service::discovery::v3::DiscoveryResponse>(
          vhdsRdsConfigJson("1"));
  const auto first_decoded_rds_resources =
      TestUtility::decodeResources<envoy::config::route::v3::RouteConfiguration>(
          first_rds_response);
  EXPECT_CALL(init_watcher_, ready());
  EXPECT_OK(rds_callbacks_->onConfigUpdate(first_decoded_rds_resources.refvec_,
                                           first_rds_response.version_info()));

  Envoy::Config::SubscriptionCallbacks* vhds_callbacks =
      server_factory_context_.cluster_manager_.subscription_factory_.callbacks_;
  ASSERT_NE(nullptr, vhds_callbacks);
  ASSERT_NE(rds_callbacks_, vhds_callbacks);

  // The initial VHDS fetch publishes the route configuration that was waiting for it.
  const auto vhds_resources = vhdsResources("bar", "bar");
  const auto decoded_vhds_resources =
      TestUtility::decodeResources<envoy::config::route::v3::VirtualHost>(vhds_resources);
  EXPECT_OK(vhds_callbacks->onConfigUpdate(decoded_vhds_resources.refvec_, {}, "1"));
  EXPECT_EQ(1UL, scope_.counter("foo.rds.foo_route_config.config_reload").value());

  // A second RDS update changes the virtual hosts of the route configuration but not its VHDS
  // configuration, so the VHDS subscription of the first update is kept.
  auto second_rds_response =
      TestUtility::parseYaml<envoy::service::discovery::v3::DiscoveryResponse>(
          vhdsRdsConfigJson("2", "baz"));
  const auto second_decoded_rds_resources =
      TestUtility::decodeResources<envoy::config::route::v3::RouteConfiguration>(
          second_rds_response);
  EXPECT_OK(rds_callbacks_->onConfigUpdate(second_decoded_rds_resources.refvec_,
                                           second_rds_response.version_info()));
  EXPECT_EQ(2UL, scope_.counter("foo.rds.foo_route_config.config_reload").value());
  EXPECT_EQ(vhds_callbacks,
            server_factory_context_.cluster_manager_.subscription_factory_.callbacks_);

  // A third one behaves the same way. If the second update had dropped the subscription, this one
  // would have had to create a new one, because a route configuration that configures VHDS without
  // a subscription to deliver its virtual hosts is never updated again.
  auto third_rds_response =
      TestUtility::parseYaml<envoy::service::discovery::v3::DiscoveryResponse>(
          vhdsRdsConfigJson("3", "qux"));
  const auto third_decoded_rds_resources =
      TestUtility::decodeResources<envoy::config::route::v3::RouteConfiguration>(
          third_rds_response);
  EXPECT_OK(rds_callbacks_->onConfigUpdate(third_decoded_rds_resources.refvec_,
                                           third_rds_response.version_info()));
  EXPECT_EQ(3UL, scope_.counter("foo.rds.foo_route_config.config_reload").value());
  EXPECT_EQ(vhds_callbacks,
            server_factory_context_.cluster_manager_.subscription_factory_.callbacks_);

  // The virtual host that VHDS delivered is still merged into the route configuration of the last
  // RDS update.
  EXPECT_TRUE(rds_->configCast()->usesVhds());
  EXPECT_EQ("foo", route(Http::TestRequestHeaderMapImpl{{":authority", "qux"}, {":path", "/qux"}})
                       ->routeEntry()
                       ->clusterName());
  EXPECT_EQ("foo", route(Http::TestRequestHeaderMapImpl{{":authority", "bar"}, {":path", "/"}})
                       ->routeEntry()
                       ->clusterName());
}

TEST_F(RdsImplTest, RdsUpdateWithUnchangedVhdsKeepsTheVhdsSubscription) {
  setup();

  // Exactly one VHDS subscription is created for all of the RDS updates below, i.e. the first one
  // creates it and the later ones neither re-create nor drop it.
  EXPECT_CALL(server_factory_context_.cluster_manager_.subscription_factory_,
              subscriptionFromConfigSource(_, _, _, _, _, _));

  auto first_rds_response =
      TestUtility::parseYaml<envoy::service::discovery::v3::DiscoveryResponse>(
          vhdsRdsConfigJson("1"));
  const auto first_decoded_rds_resources =
      TestUtility::decodeResources<envoy::config::route::v3::RouteConfiguration>(
          first_rds_response);
  EXPECT_CALL(init_watcher_, ready());
  EXPECT_OK(rds_callbacks_->onConfigUpdate(first_decoded_rds_resources.refvec_,
                                           first_rds_response.version_info()));

  Envoy::Config::SubscriptionCallbacks* vhds_callbacks =
      server_factory_context_.cluster_manager_.subscription_factory_.callbacks_;
  ASSERT_NE(nullptr, vhds_callbacks);
  ASSERT_NE(rds_callbacks_, vhds_callbacks);

  // The initial VHDS fetch publishes the route configuration that was waiting for it.
  const auto vhds_resources = vhdsResources("bar", "bar");
  const auto decoded_vhds_resources =
      TestUtility::decodeResources<envoy::config::route::v3::VirtualHost>(vhds_resources);
  EXPECT_OK(vhds_callbacks->onConfigUpdate(decoded_vhds_resources.refvec_, {}, "1"));
  EXPECT_EQ(1UL, scope_.counter("foo.rds.foo_route_config.config_reload").value());

  // A second RDS update changes the virtual hosts of the route configuration but not its VHDS
  // configuration, so the VHDS subscription of the first update is kept.
  auto second_rds_response =
      TestUtility::parseYaml<envoy::service::discovery::v3::DiscoveryResponse>(
          vhdsRdsConfigJson("2", "baz"));
  const auto second_decoded_rds_resources =
      TestUtility::decodeResources<envoy::config::route::v3::RouteConfiguration>(
          second_rds_response);
  EXPECT_OK(rds_callbacks_->onConfigUpdate(second_decoded_rds_resources.refvec_,
                                           second_rds_response.version_info()));
  EXPECT_EQ(2UL, scope_.counter("foo.rds.foo_route_config.config_reload").value());
  EXPECT_EQ(vhds_callbacks,
            server_factory_context_.cluster_manager_.subscription_factory_.callbacks_);

  // A third one behaves the same way. If the second update had dropped the subscription, this one
  // would have had to create a new one, because a route configuration that configures VHDS without
  // a subscription to deliver its virtual hosts is never updated again.
  auto third_rds_response =
      TestUtility::parseYaml<envoy::service::discovery::v3::DiscoveryResponse>(
          vhdsRdsConfigJson("3", "qux"));
  const auto third_decoded_rds_resources =
      TestUtility::decodeResources<envoy::config::route::v3::RouteConfiguration>(
          third_rds_response);
  EXPECT_OK(rds_callbacks_->onConfigUpdate(third_decoded_rds_resources.refvec_,
                                           third_rds_response.version_info()));
  EXPECT_EQ(3UL, scope_.counter("foo.rds.foo_route_config.config_reload").value());
  EXPECT_EQ(vhds_callbacks,
            server_factory_context_.cluster_manager_.subscription_factory_.callbacks_);

  // The virtual host that VHDS delivered is still merged into the route configuration of the last
  // RDS update.
  EXPECT_TRUE(rds_->configCast()->usesVhds());
  EXPECT_EQ("foo", route(Http::TestRequestHeaderMapImpl{{":authority", "qux"}, {":path", "/qux"}})
                       ->routeEntry()
                       ->clusterName());
  EXPECT_EQ("foo", route(Http::TestRequestHeaderMapImpl{{":authority", "bar"}, {":path", "/"}})
                       ->routeEntry()
                       ->clusterName());
}

TEST_F(StaticRouteConfigProviderImplTest, StaticConfigWithVhdsWarmsUp) {
  const std::string config_yaml = R"EOF(
name: foo
virtual_hosts:
  - name: bar
    domains: ["*"]
    routes:
      - match: { prefix: "/" }
        route: { cluster: baz }
vhds:
  config_source:
    api_config_source:
      api_type: DELTA_GRPC
      transport_api_version: V3
      grpc_services:
        envoy_grpc:
          cluster_name: xds_cluster
)EOF";
  server_factory_context_.cluster_manager_.initializeClusters({"baz"}, {});

  envoy::config::route::v3::RouteConfiguration route_config;
  TestUtility::loadFromYaml(config_yaml, route_config);

  NiceMock<Envoy::Config::MockSubscriptionFactory> subscription_factory;
  ON_CALL(server_factory_context_.cluster_manager_, subscriptionFactory())
      .WillByDefault(ReturnRef(subscription_factory));

  Envoy::Config::SubscriptionCallbacks* vhds_callbacks = nullptr;
  auto subscription = std::make_unique<NiceMock<Envoy::Config::MockSubscription>>();
  EXPECT_CALL(subscription_factory, subscriptionFromConfigSource(_, _, _, _, _, _))
      .WillOnce(Invoke([&vhds_callbacks, &subscription](
                           const envoy::config::core::v3::ConfigSource&, absl::string_view,
                           Stats::Scope&, Envoy::Config::SubscriptionCallbacks& callbacks,
                           Envoy::Config::OpaqueResourceDecoderSharedPtr,
                           const Envoy::Config::SubscriptionOptions&) {
        vhds_callbacks = &callbacks;
        return absl::StatusOr<Envoy::Config::SubscriptionPtr>(std::move(subscription));
      }));

  StaticRouteConfigProviderImpl provider(route_config, config_traits_, server_factory_context_,
                                         init_manager_, rds_manager_);
  ASSERT_NE(nullptr, vhds_callbacks);

  // The provider registered an init target, and it isn't ready while the initial VHDS fetch is
  // still outstanding.
  Init::ExpectableWatcherImpl init_watcher;
  init_watcher.expectReady().Times(0);
  init_manager_.initialize(init_watcher);
  ::testing::Mock::VerifyAndClearExpectations(&init_watcher);

  // Landing the initial fetch publishes the route configuration and releases whatever warms up
  // with this provider.
  envoy::config::route::v3::VirtualHost vhost;
  vhost.set_name("from_vhds");
  vhost.add_domains("vhds.com");
  auto* route = vhost.add_routes();
  route->mutable_match()->set_prefix("/");
  route->mutable_route()->set_cluster("baz");
  Protobuf::RepeatedPtrField<envoy::service::discovery::v3::Resource> resources;
  auto* resource = resources.Add();
  resource->set_name("foo/vhds.com");
  std::ignore = resource->mutable_resource()->PackFrom(vhost);
  const auto decoded_resources =
      TestUtility::decodeResources<envoy::config::route::v3::VirtualHost>(resources, "name");

  init_watcher.expectReady();
  EXPECT_OK(vhds_callbacks->onConfigUpdate(decoded_resources.refvec_, {}, "1"));

  const auto config_impl = std::static_pointer_cast<const ConfigImpl>(provider.configCast());
  EXPECT_TRUE(
      config_impl->virtualHostExists(Http::TestRequestHeaderMapImpl{{":authority", "vhds.com"}}));
}

TEST_F(VhdsTest, DestroyingTheReceiverWhileWarmingDoesNotNotifyTheObserver) {
  const auto route_config =
      TestUtility::parseYaml<envoy::config::route::v3::RouteConfiguration>(default_vhds_config_);

  NiceMock<MockRouteConfigUpdateObserver> observer;
  RouteConfigUpdatePtr config_update_info = makeReceiver();
  config_update_info->setObserver(observer);
  // The route configuration configures VHDS, so it isn't published until the initial VHDS fetch has
  // landed, i.e. it is still warming up here.
  EXPECT_OK(config_update_info->onRdsUpdate(route_config, "1"));
  EXPECT_TRUE(config_update_info->configWarming());

  // Ensure that when the receiver and VHDS subscription are destroyed, the observer is not
  // notified.
  EXPECT_CALL(observer, onConfigWarmed()).Times(0);
  config_update_info.reset();
  RouteConfigUpdatePtr config_update_info = makeReceiver();
  EXPECT_THAT(config_update_info->onRdsUpdate(route_config, "1"), Not(IsOk()));
  RouteConfigUpdatePtr config_update_info = makeReceiver();
  EXPECT_THAT(config_update_info->onRdsUpdate(route_config, "1"), Not(IsOk()));
  // Creating the receiver's VHDS subscription is part of applying the RDS update.
  makeRouteConfigUpdate(route_config);
  RouteConfigUpdatePtr config_update_info = makeReceiver();
  auto result = config_update_info->onRdsUpdate(route_config, "1");
  RouteConfigUpdatePtr config_update_info = makeReceiver();
  auto result = config_update_info->onRdsUpdate(route_config, "1");
  // The route configuration configures VHDS, so it isn't published until the initial VHDS fetch
  // has landed.
  EXPECT_EQ(0UL, config_update_info->protobufConfigurationCast().virtual_hosts_size());
  EXPECT_OK(config_update_info->onRdsUpdate(updated_route_config, "2"));
  // Land the initial VHDS fetch, which is what publishes the route configuration.
  const auto first_added_resources =
      buildAddedResources({buildVirtualHost("vhost1", "vhost1.com")});
  const auto first_decoded_resources =
      TestUtility::decodeResources<envoy::config::route::v3::VirtualHost>(first_added_resources);
  EXPECT_OK(factory_context_.cluster_manager_.subscription_factory_.callbacks_->onConfigUpdate(
      first_decoded_resources.refvec_, {}, "2"));
  ASSERT_NE(nullptr, config_before_update);

TEST_P(VhdsIntegrationTest, InitialVhdsBlocksListenerWarmingWithInlineRouteConfig) {
  if (routeConfigType() != RouteConfigType::Static) {
    GTEST_SKIP() << "This test covers the inline route configuration";
  }

  // Returns once Envoy has asked for the virtual hosts, i.e. once everything the inline route
  // configuration needs in order to go live has happened except the response itself.
  initializeUpToInitialVhdsRequest();

  // The listener is still warming: the inline route configuration hasn't gone live, so Envoy
  // hasn't started its workers.
  EXPECT_FALSE(workersStarted());

  // The virtual hosts arrive, so the route configuration goes live and the listener finishes
  // warming.
  sendInitialVhdsResponse();
  waitForListenerToServe();

  // The virtual host that only VHDS knows about is reachable, i.e. the listener didn't come up
  // serving a route configuration that was missing it.
  testRouterHeaderOnlyRequestAndResponse(nullptr, 1, "/", "sni.lyft.com");
  cleanupUpstreamAndDownstream();
  ASSERT_TRUE(codec_client_->waitForDisconnect());
}

TEST_P(VhdsIntegrationTest, InitialVhdsBlocksListenerWarmingWithRdsRouteConfig) {
  if (routeConfigType() != RouteConfigType::Rds) {
    GTEST_SKIP() << "This test covers the dynamic route configuration";
  }

  // Returns once the RDS response has been delivered and Envoy has asked for the virtual hosts.
  initializeUpToInitialVhdsRequest();

  // The RouteConfiguration has already arrived over RDS and Envoy has started the VHDS
  // subscription that it configures, so RDS is no longer what the listener is waiting on. It is
  // still warming, which is what makes this a test of VHDS gating warming rather than of RDS.
  auto config_reload = test_server_->counter("http.config_test.rds.my_route.config_reload");
  ASSERT_NE(nullptr, config_reload);
  EXPECT_EQ(0, config_reload->value());
  EXPECT_FALSE(workersStarted());

  sendInitialVhdsResponse();
  // The route configuration is published exactly once, by the initial VHDS response.
  test_server_->waitForCounter("http.config_test.rds.my_route.config_reload", testing::Eq(1));
  waitForListenerToServe();

  testRouterHeaderOnlyRequestAndResponse(nullptr, 1, "/", "sni.lyft.com");
  cleanupUpstreamAndDownstream();
  ASSERT_TRUE(codec_client_->waitForDisconnect());
}

VhdsInlineOnLdsListenerTest()
      : HttpIntegrationTest(Http::CodecType::HTTP2, ipVersion(), config()) {
    use_lds_ = false;
    config_helper_.addRuntimeOverride("envoy.reloadable_features.unified_mux",
                                      isUnified() ? "true" : "false");
  }

void initialize() override {
    // Drop the bootstrap listener and serve listeners over LDS from the same xDS cluster instead.
    config_helper_.addConfigModifier([](envoy::config::bootstrap::v3::Bootstrap& bootstrap) {
      bootstrap.mutable_static_resources()->mutable_listeners()->Clear();
      auto* lds_config = bootstrap.mutable_dynamic_resources()->mutable_lds_config();
      lds_config->set_resource_api_version(envoy::config::core::v3::ApiVersion::V3);
      auto* api_config_source = lds_config->mutable_api_config_source();
      api_config_source->set_api_type(envoy::config::core::v3::ApiConfigSource::GRPC);
      api_config_source->set_transport_api_version(envoy::config::core::v3::V3);
      api_config_source->add_grpc_services()->mutable_envoy_grpc()->set_cluster_name("xds_cluster");
    });

    setUpstreamCount(2);
    setUpstreamProtocol(Http::CodecType::HTTP2);
    defer_listener_finalization_ = true;
    HttpIntegrationTest::initialize();

    AssertionResult result =
        fake_upstreams_[0]->waitForHttpConnection(*dispatcher_, xds_connection_);
    RELEASE_ASSERT(result, result.message());
    result = xds_connection_->waitForNewStream(*dispatcher_, xds_stream_);
    RELEASE_ASSERT(result, result.message());
    xds_stream_->startGrpcStream();

    // Complete LDS with no listeners at all, so the server finishes initializing and starts its
    // workers. Everything the test does after this happens against a live server whose init
    // manager is Initialized, which is the whole point of the fixture.
    EXPECT_TRUE(compareSotwDiscoveryRequest(Config::TestTypeUrl::get().Listener, "", {}, true));
    sendSotwDiscoveryResponse<envoy::config::listener::v3::Listener>(
        Config::TestTypeUrl::get().Listener, {}, "1");
    test_server_->waitForGauge("listener_manager.workers_started", testing::Eq(1));
  }

TEST_P(VhdsInlineOnLdsListenerTest, InlineVhdsOnListenerAddedAfterServerIsLive) {
  initialize();

  // Deliver the listener now that the server is live.
  sendSotwDiscoveryResponse<envoy::config::listener::v3::Listener>(
      Config::TestTypeUrl::get().Listener, {listenerWithInlineVhds()}, "2");

  // Because the workers are already running, a newly added listener goes into warming_listeners_
  // rather than straight into active_listeners_, so unlike the bootstrap case this gauge is a
  // direct read of "the listener is warming".
  test_server_->waitForGauge("listener_manager.total_listeners_warming", testing::Eq(1));

  // The inline route configuration started its VHDS subscription. This is the assertion the old
  // implementation failed: it registered the VHDS init target with the server's init manager,
  // which is Initialized by now, so the target was dropped and start() never ran - meaning this
  // stream would never be created and the wait below would time out.
  AssertionResult result = xds_connection_->waitForNewStream(*dispatcher_, vhds_stream_);
  RELEASE_ASSERT(result, result.message());
  vhds_stream_->startGrpcStream();
  EXPECT_TRUE(compareDeltaDiscoveryRequest(Config::TestTypeUrl::get().VirtualHost, {}, {},
                                           vhds_stream_.get()));

  // The virtual hosts haven't arrived, so the listener is still warming and not yet serving.
  EXPECT_EQ(1, test_server_->gauge("listener_manager.total_listeners_warming")->value());
  EXPECT_EQ(0, test_server_->gauge("listener_manager.total_listeners_active")->value());

  sendDeltaDiscoveryResponse<envoy::config::route::v3::VirtualHost>(
      Config::TestTypeUrl::get().VirtualHost,
      {TestUtility::parseYaml<envoy::config::route::v3::VirtualHost>(
          fmt::format(VhostTemplate, "my_route/vhost_0", "sni.lyft.com"))},
      {}, "1", vhds_stream_.get());

  // The virtual hosts arrived, so the route configuration goes live and the listener finishes
  // warming.
  test_server_->waitForGauge("listener_manager.total_listeners_warming", testing::Eq(0));
  test_server_->waitForGauge("listener_manager.total_listeners_active", testing::Eq(1));
  test_server_->waitUntilListenersReady();
  registerTestServerPorts({"http"});

  // The virtual host that only VHDS knows about is reachable, i.e. the listener didn't come up
  // serving a route configuration that was missing it.
  testRouterHeaderOnlyRequestAndResponse(nullptr, 1, "/", "sni.lyft.com");
  cleanupUpstreamAndDownstream();
  ASSERT_TRUE(codec_client_->waitForDisconnect());
}

TEST_F(CustomResponseFilterTest, ExistingLocalReplyBodyWithFormatter) {
  createConfig(R"EOF(
  custom_response_matcher:
    on_no_match:
      action:
        name: action
        typed_config:
          "@type": type.googleapis.com/envoy.extensions.http.custom_response.local_response_policy.v3.LocalResponsePolicy
          body_format:
            text_format_source:
              inline_string: "%LOCAL_REPLY_BODY%"
)EOF");
  setupFilterAndCallback();

  const ::Envoy::Http::StreamFilterBase::LocalReplyData local_reply_data{
      ::Envoy::Http::Code::Unauthorized, std::nullopt, "details", false, "original body"};
  EXPECT_EQ(filter_->onLocalReply(local_reply_data), ::Envoy::Http::LocalErrorStatus::Continue);

  ::Envoy::Http::TestRequestHeaderMapImpl request_headers{};
  ::Envoy::Http::TestResponseHeaderMapImpl response_headers{{":status", "401"}};
  ON_CALL(encoder_callbacks_.stream_info_, getRequestHeaders())
      .WillByDefault(Return(&request_headers));
  EXPECT_CALL(encoder_callbacks_,
              sendLocalReply(::Envoy::Http::Code::Unauthorized, "original body", _, _, _));
  EXPECT_EQ(filter_->encodeHeaders(response_headers, true),
            ::Envoy::Http::FilterHeadersStatus::StopIteration);
}

