TEST_P(CustomResponseIntegrationTest, ExistingLocalReplyBodyWithFormatter) {
  custom_response_filter_config_ = TestUtility::parseYaml<CustomResponse>(R"EOF(
custom_response_matcher:
  matcher_list:
    matchers:
    - predicate:
        single_predicate:
          input:
            name: local_reply
            typed_config:
              "@type": type.googleapis.com/envoy.type.matcher.v3.HttpResponseLocalReplyMatchInput
          value_match:
            exact: "true"
      on_match:
        action:
          name: action
          typed_config:
            "@type": type.googleapis.com/envoy.extensions.http.custom_response.local_response_policy.v3.LocalResponsePolicy
            body_format:
              text_format_source:
                inline_string: "formatted: %LOCAL_REPLY_BODY%"
)EOF");
  initialize();

  codec_client_ = makeHttpConnection(lookupPort("http"));
  default_request_headers_.setHost("default.host");
  default_request_headers_.setPath("/default");
  auto response = codec_client_->makeHeaderOnlyRequest(default_request_headers_);
  ASSERT_TRUE(response->waitForEndStream());
  ASSERT_TRUE(response->complete());
  EXPECT_EQ("201", response->headers().getStatusValue());
  EXPECT_EQ("formatted: Response body", response->body());
}

void extractUsageInto(const nlohmann::json& json, ExtractionResult& result) const override {
    bool& malformed = result.malformed;
    TokenUsage& usage = result.usage;
    const nlohmann::json* response = readObject(json, JsonKeys::get().Response, malformed);
    const nlohmann::json& node = response != nullptr ? *response : json;

    if (auto model = readString(node, JsonKeys::get().Model); model.has_value()) {
      usage.model = std::move(model).value();
    }

    const nlohmann::json* usage_node =
        readObject(node, JsonKeys::get().Usage, malformed, NullPolicy::AllowNullAsAbsent);
    if (usage_node == nullptr) {
      return;
    }

    usage.input_tokens = readCount(*usage_node, JsonKeys::get().PromptTokens, malformed);
    if (!usage.input_tokens.has_value()) {
      usage.input_tokens = readCount(*usage_node, JsonKeys::get().InputTokens, malformed);
    }
    usage.output_tokens = readCount(*usage_node, JsonKeys::get().CompletionTokens, malformed);
    if (!usage.output_tokens.has_value()) {
      usage.output_tokens = readCount(*usage_node, JsonKeys::get().OutputTokens, malformed);
    }
    usage.total_tokens = readCount(*usage_node, JsonKeys::get().TotalTokens, malformed);

    const nlohmann::json* input_details = readObject(
        *usage_node, JsonKeys::get().PromptTokensDetails, malformed, NullPolicy::AllowNullAsAbsent);
    if (input_details == nullptr) {
      input_details = readObject(*usage_node, JsonKeys::get().InputTokensDetails, malformed,
                                 NullPolicy::AllowNullAsAbsent);
    }
    if (input_details != nullptr) {
      usage.cached_input_tokens =
          readCount(*input_details, JsonKeys::get().CachedTokens, malformed);
      usage.cache_creation_input_tokens =
          readCount(*input_details, JsonKeys::get().CacheWriteTokens, malformed);
    }

    const nlohmann::json* output_details =
        readObject(*usage_node, JsonKeys::get().CompletionTokensDetails, malformed,
                   NullPolicy::AllowNullAsAbsent);
    if (output_details == nullptr) {
      output_details = readObject(*usage_node, JsonKeys::get().OutputTokensDetails, malformed,
                                  NullPolicy::AllowNullAsAbsent);
    }
    if (output_details != nullptr) {
      usage.reasoning_tokens =
          readCount(*output_details, JsonKeys::get().ReasoningTokens, malformed);
    }
  }

const PayloadSchema* schema() const override {
    // Construct-on-first-use: schemas are non-trivially destructible, so a
    // plain function-local static would register an exit-time destructor.
    static const PayloadSchema* openai_schema = new PayloadSchema(OpenAI::createPayloadSchema());
    return openai_schema;
  }

bool isTerminalEvent(const nlohmann::json& json) const override {
    // Terminal lifecycle events; also the usage carriers, so callers
    // extractUsage() first.
    const auto type = readString(json, JsonKeys::get().Type);
    return type.has_value() && isOpenAiResponsesTerminalEventType(type.value());
  }

void canonicalizeUsage(TokenUsage& usage, bool& overflow) const override {
    // Native input excludes the two disjoint cache buckets.
    if (usage.input_tokens.has_value()) {
      usage.input_tokens =
          addCounts(addCounts(usage.input_tokens, usage.cached_input_tokens, overflow),
                    usage.cache_creation_input_tokens, overflow);
    }
  }

void extractUsageInto(const nlohmann::json& json, ExtractionResult& result) const override {
    bool& malformed = result.malformed;
    TokenUsage& usage = result.usage;
    // Anthropic documents `event: error` after a 200 has streamed: the
    // terminal usage update never arrives, so the accumulation so far must
    // not publish as complete.
    if (const auto type = readString(json, JsonKeys::get().Type);
        type.has_value() && type.value() == "error") {
      result.stream_error = true;
      return;
    }
    const nlohmann::json* message = readObject(json, JsonKeys::get().Message, malformed);
    const nlohmann::json& node = message != nullptr ? *message : json;

    if (auto model = readString(node, JsonKeys::get().Model); model.has_value()) {
      usage.model = std::move(model).value();
    }

    const nlohmann::json* usage_node = readObject(node, JsonKeys::get().Usage, malformed);
    if (usage_node == nullptr) {
      return;
    }

    // Native counts only: the disjoint input/cache buckets are summed once,
    // in canonicalizeUsage() -- summing per event would let a partial update
    // regress the accumulated value via last-wins merge.
    usage.input_tokens = readCount(*usage_node, JsonKeys::get().InputTokens, malformed);
    // `output_tokens` already includes thinking tokens (inclusive).
    usage.output_tokens = readCount(*usage_node, JsonKeys::get().OutputTokens, malformed);
    // No total_tokens in this dialect; computed at finalize.
    usage.cached_input_tokens =
        readCount(*usage_node, JsonKeys::get().CacheReadInputTokens, malformed);
    usage.cache_creation_input_tokens =
        readCount(*usage_node, JsonKeys::get().CacheCreationInputTokens, malformed);

    if (const nlohmann::json* details = readObject(*usage_node, JsonKeys::get().OutputTokensDetails,
                                                   malformed, NullPolicy::AllowNullAsAbsent);
        details != nullptr) {
      usage.reasoning_tokens = readCount(*details, JsonKeys::get().ThinkingTokens, malformed);
    }
  }

void canonicalizeUsage(TokenUsage& usage, bool& overflow) const override {
    // Native prompt/candidates counts exclude tool-use and thoughts.
    if (usage.input_tokens.has_value()) {
      usage.input_tokens = addCounts(usage.input_tokens, usage.tool_use_input_tokens, overflow);
    }
    if (usage.output_tokens.has_value()) {
      usage.output_tokens = addCounts(usage.output_tokens, usage.reasoning_tokens, overflow);
    }
  }

void extractUsageInto(const nlohmann::json& json, ExtractionResult& result) const override {
    bool& malformed = result.malformed;
    TokenUsage& usage = result.usage;
    if (auto model = readString(json, JsonKeys::get().ModelVersion); model.has_value()) {
      usage.model = std::move(model).value();
    }

    const nlohmann::json* usage_node = readObject(json, JsonKeys::get().UsageMetadata, malformed);
    if (usage_node == nullptr) {
      return;
    }

    // Native counts only; the tool-use and thoughts adjuncts are summed in at
    // canonicalizeUsage(), after the last cumulative snapshot merged.
    usage.input_tokens = readCount(*usage_node, JsonKeys::get().PromptTokenCount, malformed);
    usage.output_tokens = readCount(*usage_node, JsonKeys::get().CandidatesTokenCount, malformed);
    usage.total_tokens = readCount(*usage_node, JsonKeys::get().TotalTokenCount, malformed);
    usage.cached_input_tokens =
        readCount(*usage_node, JsonKeys::get().CachedContentTokenCount, malformed);
    usage.tool_use_input_tokens =
        readCount(*usage_node, JsonKeys::get().ToolUsePromptTokenCount, malformed);
    usage.reasoning_tokens = readCount(*usage_node, JsonKeys::get().ThoughtsTokenCount, malformed);
  }

const ApiProtocolAdapter& AdapterRegistry::get(ApiProtocol protocol) {
  // Construct-on-first-use: adapters have virtual destructors, so plain
  // function-local statics would register exit-time destructors.
  switch (protocol) {
  case ApiProtocol::OpenAiChatCompletions:
    CONSTRUCT_ON_FIRST_USE(OpenAiChatCompletionsAdapter);
  case ApiProtocol::OpenAiResponses:
    CONSTRUCT_ON_FIRST_USE(OpenAiResponsesAdapter);
  case ApiProtocol::AnthropicMessages:
    CONSTRUCT_ON_FIRST_USE(AnthropicMessagesAdapter);
  case ApiProtocol::GeminiGenerateContent:
    CONSTRUCT_ON_FIRST_USE(GeminiGenerateContentAdapter);
  case ApiProtocol::Unspecified:
    break;
  }
  CONSTRUCT_ON_FIRST_USE(NullAdapter);
}

ApiProtocol AdapterRegistry::detect(const nlohmann::json& json) {
  // Gemini markers, validated by value shape: a foreign document with e.g. a
  // `candidates` *string* must not lock the stream. Real candidates lists are
  // non-empty arrays of objects.
  if (const auto it = json.find(JsonKeys::get().Candidates);
      it != json.end() && it->is_array() && !it->empty() && it->front().is_object()) {
    return ApiProtocol::GeminiGenerateContent;
  }
  if (const auto it = json.find(JsonKeys::get().UsageMetadata);
      it != json.end() && it->is_object()) {
    return ApiProtocol::GeminiGenerateContent;
  }
  if (readString(json, JsonKeys::get().ModelVersion).has_value()) {
    return ApiProtocol::GeminiGenerateContent;
  }

  // OpenAI Chat Completions and non-streaming Responses discriminate on
  // `object`; Responses streaming events discriminate on `type` ("response.*").
  if (const auto object = readString(json, JsonKeys::get().ObjectKey); object.has_value()) {
    if (absl::StartsWith(object.value(), "chat.completion")) {
      return ApiProtocol::OpenAiChatCompletions;
    }
    if (object.value() == "response") {
      return ApiProtocol::OpenAiResponses;
    }
  }

  if (const auto type = readString(json, JsonKeys::get().Type); type.has_value()) {
    const absl::string_view type_view = type.value();
    if (absl::StartsWith(type_view, "response.")) {
      return ApiProtocol::OpenAiResponses;
    }
    // Anthropic markers need their documented companion structure: bare
    // `type` strings are generic, and a genuine stream always presents
    // message_start (nested Message) or a non-streaming Message (role/usage)
    // before any usage, so skipping the bare event types loses nothing.
    bool discard = false;
    if (type_view == "message") {
      if (readString(json, JsonKeys::get().Role).has_value() ||
          readObject(json, JsonKeys::get().Usage, discard) != nullptr) {
        return ApiProtocol::AnthropicMessages;
      }
    } else if (type_view == "message_start") {
      if (readObject(json, JsonKeys::get().Message, discard) != nullptr) {
        return ApiProtocol::AnthropicMessages;
      }
    } else if (type_view == "message_delta") {
      if (readObject(json, JsonKeys::get().Usage, discard) != nullptr ||
          readObject(json, JsonKeys::get().Delta, discard) != nullptr) {
        return ApiProtocol::AnthropicMessages;
      }
    }
    // `message_stop`/`content_block_*` carry no structure and no usage.
  }

  return ApiProtocol::Unspecified;
}

bool isJsonContentType(absl::string_view content_type) {
  const absl::string_view normalized = StringUtil::trim(StringUtil::cropRight(content_type, ";"));
  return absl::EqualsIgnoreCase(normalized, "application/json") ||
         absl::EndsWithIgnoreCase(normalized, "+json");
}

bool contentEncodingIsIdentity(const Http::ResponseHeaderMap& headers) {
  const auto entries = headers.get(Http::CustomHeaders::get().ContentEncoding);
  for (size_t i = 0; i < entries.size(); ++i) {
    // keep_empty_string=true rejects malformed values like `identity,,`.
    for (const absl::string_view coding : StringUtil::splitToken(
             entries[i]->value().getStringView(), ",", /*keep_empty_string=*/true)) {
      if (!absl::EqualsIgnoreCase(StringUtil::trim(coding), "identity")) {
        return false;
      }
    }
  }
  return true;
}

envoy::data::ai::v3::TokenUsage typedUsage(const TokenUsage& usage, bool degraded) {
  envoy::data::ai::v3::TokenUsage typed;
  typed.set_api_protocol(protocolToProto(usage.api_protocol));
  if (!usage.model.empty()) {
    typed.set_model(usage.model);
  }
  const auto set = [](const std::optional<uint64_t>& value, auto setter) {
    if (value.has_value()) {
      setter(value.value());
    }
  };
  set(usage.input_tokens, [&typed](uint64_t v) { typed.mutable_input_tokens()->set_value(v); });
  set(usage.output_tokens, [&typed](uint64_t v) { typed.mutable_output_tokens()->set_value(v); });
  set(usage.total_tokens, [&typed](uint64_t v) { typed.mutable_total_tokens()->set_value(v); });
  set(usage.cached_input_tokens, [&typed](uint64_t v) {
    typed.mutable_input_token_details()->mutable_cached_tokens()->set_value(v);
  });
  set(usage.cache_creation_input_tokens, [&typed](uint64_t v) {
    typed.mutable_input_token_details()->mutable_cache_creation_tokens()->set_value(v);
  });
  set(usage.tool_use_input_tokens, [&typed](uint64_t v) {
    typed.mutable_input_token_details()->mutable_tool_use_tokens()->set_value(v);
  });
  set(usage.reasoning_tokens, [&typed](uint64_t v) {
    typed.mutable_output_token_details()->mutable_reasoning_tokens()->set_value(v);
  });
  set(usage.provider_total_tokens,
      [&typed](uint64_t v) { typed.mutable_provider_total_tokens()->set_value(v); });
  if (!usage.hasAny()) {
    typed.set_extraction_status(envoy::data::ai::v3::TokenUsage::FAILED);
  } else {
    typed.set_extraction_status(degraded ? envoy::data::ai::v3::TokenUsage::PARTIAL
                                         : envoy::data::ai::v3::TokenUsage::COMPLETE);
  }
  return typed;
}

AiProtocolManagerFilter::encodeData(Buffer::Instance& data,
                                                           bool end_stream) {
  if (response_handler_ != nullptr && !response_finalized_) {
    response_handler_->onData(data);
    if (end_stream) {
      response_handler_->onEndStream();
      finalizeResponseHandling();
    }
  }
  return Http::FilterDataStatus::Continue;
}

Http::FilterTrailersStatus AiProtocolManagerFilter::encodeTrailers(Http::ResponseTrailerMap&) {
  if (response_handler_ != nullptr && !response_finalized_) {
    // Trailers end the body: the handler must observe end-of-stream (parsing a
    // buffered JSON body, resolving a pending SSE terminator) before the
    // result is finalized.
    response_handler_->onEndStream();
    finalizeResponseHandling();
  }
  return Http::FilterTrailersStatus::Continue;
}

void AiProtocolManagerFilter::finalizeResponseHandling() {
  response_finalized_ = true;

  TokenUsage usage = response_handler_->usage();
  finalizeUsage(usage);
  const bool degraded = response_handler_->degraded() || usage.canonicalizationOverflow();
  if (!usage.hasAny() && !degraded) {
    // Legitimately absent usage: e.g. an OpenAI stream without
    // `stream_options.include_usage`, or an unrecognized response shape.
    config_->stats().token_usage_missing_.inc();
    return;
  }

  // Two publications for one stream (both-placement installs) would leave
  // consumers with an ambiguous record. First writer wins: the upstream
  // instance publishes first, later instances skip.
  const auto& existing_metadata =
      encoder_callbacks_->streamInfo().dynamicMetadata().typed_filter_metadata();
  if (existing_metadata.contains(config_->metadataNamespace())) {
    ENVOY_LOG(debug,
              "ai_protocol_manager: namespace {} already published for this stream "
              "(both-placement installation); skipping duplicate publication",
              config_->metadataNamespace());
    config_->stats().token_usage_duplicate_.inc();
    return;
  }

  // Convert the finalized accumulator once into the authoritative typed
  // record (envoy.data.ai.v3.TokenUsage). When extraction failed outright the
  // record is status-only (api_protocol/model/extraction_status, no counts),
  // letting consumers distinguish "failed to extract" from "no usage
  // supplied". Only typed metadata is published: consumers with full-fidelity
  // needs (ext_proc typed forwarding, filters reading typed metadata) share
  // the proto definition; no untyped Struct mirror is emitted.
  // TODO(botengyao): move this dynamic-metadata publication into a built-in
  // AI payload filter once the payload filter manager (the in-filter chain
  // over the parsed payload) lands. The filter core then only orchestrates
  // transport, and publication becomes an ordered, configurable chain entry
  // like any other payload feature.
  const envoy::data::ai::v3::TokenUsage typed = typedUsage(usage, degraded);
  // In both roles streamInfo() resolves to the downstream request's
  // StreamInfo. Under retries/hedging only the router-selected attempt
  // streams to a clean end of stream, so only the winner reaches this write.
  Protobuf::Any typed_any;
  MessageUtil::packFrom(typed_any, typed);
  encoder_callbacks_->streamInfo().setDynamicTypedMetadata(config_->metadataNamespace(), typed_any);

  if (!usage.hasAny()) {
    config_->stats().token_usage_failed_.inc();
    ENVOY_LOG(trace, "ai_protocol_manager: status-only (failed) record published to namespace {}",
              config_->metadataNamespace());
    return;
  }
  if (degraded) {
    config_->stats().token_usage_partial_.inc();
  }
  if (usage.provider_total_tokens.has_value() && usage.total_tokens.has_value() &&
      usage.provider_total_tokens.value() != usage.total_tokens.value()) {
    config_->stats().token_usage_total_mismatch_.inc();
  }
  config_->stats().token_usage_found_.inc();
  ENVOY_LOG(trace, "ai_protocol_manager: token usage published to namespace {}",
            config_->metadataNamespace());
}

std::optional<uint64_t> readCount(const nlohmann::json& json, const std::string& key,
                                  bool& malformed) {
  const auto it = json.find(key);
  if (it == json.end()) {
    return std::nullopt;
  }
  const nlohmann::json& value = *it;
  // JsonWithExtBufParser stores any literal that fits int64 as a *signed*
  // integer (is_number_unsigned() is true only above INT64_MAX), so probe the
  // signed representation first.
  if (value.is_number_integer()) {
    if (value.is_number_unsigned()) {
      const uint64_t count = value.get<uint64_t>();
      if (count > MaxSafeCount) {
        malformed = true;
        return std::nullopt;
      }
      return count;
    }
    const int64_t count = value.get<int64_t>();
    if (count < 0 || static_cast<uint64_t>(count) > MaxSafeCount) {
      malformed = true;
      return std::nullopt;
    }
    return static_cast<uint64_t>(count);
  }
  if (value.is_number_float()) {
    const double as_double = value.get<double>();
    // Range-check before the float-to-integer cast: converting an
    // out-of-range double to uint64_t is undefined behavior.
    if (!std::isfinite(as_double) || as_double < 0 ||
        as_double > static_cast<double>(MaxSafeCount) || std::trunc(as_double) != as_double) {
      malformed = true;
      return std::nullopt;
    }
    return static_cast<uint64_t>(as_double);
  }
  malformed = true; // Present with a non-numeric value (string, bool, null, container).
  return std::nullopt;
}

std::optional<std::string> readString(const nlohmann::json& json, const std::string& key) {
  const auto it = json.find(key);
  if (it == json.end() || !it->is_string()) {
    return std::nullopt;
  }
  const auto& value = it->get_ref<const std::string&>();
  if (value.empty() || value.size() > MaxStringValueSize) {
    return std::nullopt;
  }
  return value;
}

const nlohmann::json* readObject(const nlohmann::json& json, const std::string& key,
                                 bool& malformed, NullPolicy null_policy) {
  const auto it = json.find(key);
  if (it == json.end()) {
    return nullptr;
  }
  if (it->is_object()) {
    return &*it;
  }
  if (!it->is_null() || null_policy == NullPolicy::NullIsMalformed) {
    malformed = true;
  }
  return nullptr;
}

std::optional<uint64_t> addCounts(std::optional<uint64_t> base,
                                  const std::optional<uint64_t>& extra, bool& overflow) {
  if (!base.has_value() || !extra.has_value()) {
    return base;
  }
  const uint64_t sum = base.value() + extra.value();
  if (sum > MaxSafeCount) {
    overflow = true;
    return std::nullopt;
  }
  return sum;
}

std::optional<absl::string_view> sseEventTypeView(absl::string_view region) {
  std::optional<absl::string_view> event_type;
  size_t pos = 0;
  while (pos < region.size()) {
    size_t eol = region.find_first_of("\r\n", pos);
    if (eol == absl::string_view::npos) {
      eol = region.size();
    }
    absl::string_view line = region.substr(pos, eol - pos);
    if (absl::ConsumePrefix(&line, "event:")) {
      absl::ConsumePrefix(&line, " ");
      event_type = line;
    }
    pos = eol;
    if (pos < region.size() && region[pos] == '\r') {
      ++pos;
    }
    if (pos < region.size() && region[pos] == '\n') {
      ++pos;
    }
  }
  return event_type;
}

bool skippableEventType(absl::string_view event_type) {
  // Anthropic keepalives and content deltas.
  if (event_type == "ping" || absl::StartsWith(event_type, "content_block")) {
    return true;
  }
  // OpenAI Responses lifecycle events: usage rides only the terminal ones
  // (one shared name list; see isOpenAiResponsesTerminalEventType).
  if (absl::StartsWith(event_type, "response.")) {
    return !isOpenAiResponsesTerminalEventType(event_type);
  }
  return false;
}

bool ResponseHandler::processDocument(const nlohmann::json& json) {
  if (!json.is_object()) {
    // Non-object JSON (scalar, array, null) is an unsupported shape, not an
    // error: skip it.
    return false;
  }
  if (format_ == ApiProtocol::Unspecified) {
    format_ = AdapterRegistry::detect(json);
    if (format_ == ApiProtocol::Unspecified) {
      return false; // Not discriminating; a later document may be.
    }
  }
  const ApiProtocolAdapter& adapter = AdapterRegistry::get(format_);
  const ExtractionResult result = adapter.extractUsage(json);
  usage_.merge(result.usage);
  if (result.malformed) {
    // A corrupt document must not leave an earlier accumulated snapshot
    // published as complete.
    stats_.malformed_usage_field_.inc();
    degraded_ = true;
  }
  if (result.stream_error) {
    // An in-band stream error: the dialect's terminal usage update will
    // never arrive, so the counts so far are not authoritative.
    degraded_ = true;
  }
  return adapter.isTerminalEvent(json);
}

std::optional<uint64_t> SseResponseHandler::scanView(absl::string_view data) {
  for (size_t i = 0; i < data.size(); ++i) {
    const char c = data[i];
    switch (scan_state_) {
    case ScanState::LineStart:
      if (c == '\n') {
        return i + 1; // LF-terminated blank line: event boundary.
      }
      if (c == '\r') {
        scan_state_ = ScanState::BlankTermCr;
      } else {
        scan_state_ = ScanState::LineContent;
      }
      break;
    case ScanState::LineContent:
      if (c == '\n') {
        scan_state_ = ScanState::LineStart;
      } else if (c == '\r') {
        scan_state_ = ScanState::TermCr;
      }
      break;
    case ScanState::TermCr:
      // The CR already ended the content line.
      if (c == '\n') {
        scan_state_ = ScanState::LineStart; // CRLF pair.
      } else if (c == '\r') {
        scan_state_ = ScanState::BlankTermCr; // A new, empty line ended by CR.
      } else {
        scan_state_ = ScanState::LineContent; // A new line starting with content.
      }
      break;
    case ScanState::BlankTermCr:
      // A blank line ended with CR: the boundary is complete, but an
      // immediately following LF belongs to the same CRLF terminator.
      scan_state_ = ScanState::LineStart;
      if (c == '\n') {
        return i + 1;
      }
      return i; // Boundary before this byte; it is re-scanned as next-event input.
    }
  }
  return std::nullopt;
}

void SseResponseHandler::onData(const Buffer::Instance& data) {
  if (parsing_complete_ || budget_exhausted_ || data.length() == 0) {
    return;
  }
  // Incoming frames are scanned directly, before any retention; previously
  // buffered slices are never re-enumerated.
  for (const Buffer::RawSlice& slice : data.getRawSlices()) {
    if (parsing_complete_) {
      break;
    }
    processSlice(absl::string_view(static_cast<const char*>(slice.mem_), slice.len_));
  }
  if (parsing_complete_) {
    // Terminal event seen: release everything; later frames drop at entry.
    buffer_.drain(buffer_.length());
  }
}

void SseResponseHandler::processSlice(absl::string_view view) {
  while (!view.empty() && !parsing_complete_ && !budget_exhausted_) {
    const auto boundary = scanView(view);
    if (discarding_) {
      // Nothing is retained while discarding; the scanner's line state (not
      // raw tail bytes) carries the mid-event position across frames, so a
      // split terminator cannot fabricate a boundary.
      if (!boundary.has_value()) {
        return; // The rest of the slice belongs to the discarded event.
      }
      discarding_ = false;
      view.remove_prefix(boundary.value());
      continue;
    }
    // buffer_.length() <= max_event_size_ is a class invariant, so the
    // subtraction cannot underflow.
    const uint64_t allowance = static_cast<uint64_t>(max_event_size_) - buffer_.length();
    if (!boundary.has_value()) {
      // The whole (already scanned) view is interior of the pending event.
      // The cap is enforced *before* copying: one oversized frame must not
      // become an over-cap side allocation.
      if (view.size() > allowance) {
        enterDiscardMode(pendingEventSkippable(view));
      } else {
        retainBytes(view);
      }
      return;
    }
    if (boundary.value() > allowance) {
      // A complete over-cap event is skipped without ever being buffered,
      // linearized, or parsed. A skippable named event (keepalive, content
      // delta) could never have carried usage, so its loss does not degrade
      // the record.
      ENVOY_LOG(debug, "ai_protocol_manager: SSE event exceeds max_event_size ({} > {}), skipped",
                buffer_.length() + boundary.value(), max_event_size_);
      stats_.sse_event_too_large_.inc();
      if (!pendingEventSkippable(view.substr(0, boundary.value()))) {
        degraded_ = true;
      }
      buffer_.drain(buffer_.length());
      // scanView() already left the line state at LineStart.
    } else if (buffer_.length() == 0) {
      // Fast path: process the complete event in place -- nothing retained.
      handleCompleteEvent(view.substr(0, boundary.value()));
    } else {
      retainBytes(view.substr(0, boundary.value()));
      consumeEvent();
    }
    view.remove_prefix(boundary.value());
  }
}

void SseResponseHandler::consumeEvent() {
  const uint64_t length = buffer_.length();
  ASSERT(length <= max_event_size_);
  // Only split events reach here; linearize() can transiently hold a second,
  // account-charged copy (bounded by max_event_size) while consolidating.
  const absl::string_view region(static_cast<const char*>(buffer_.linearize(length)), length);
  handleCompleteEvent(region);
  buffer_.drain(buffer_.length());
  scan_state_ = ScanState::LineStart;
}

void SseResponseHandler::handleCompleteEvent(absl::string_view region) {
  // Classify before materializing: named non-usage events are dropped before
  // their data payload is assembled or parsed.
  if (!eventMayCarryUsage(region)) {
    return;
  }
  // The region ends exactly at a blank-line boundary, so end_stream=true
  // resolves a trailing bare-CR terminator safely.
  const auto result = Http::Sse::SseParser::findEventEnd(region, /*end_stream=*/true);
  if (result.event_start != absl::string_view::npos) {
    processSseEvent(region.substr(result.event_start, result.event_end - result.event_start));
  }
}

void SseResponseHandler::enterDiscardMode(bool skippable) {
  // The pending event exceeded the cap before terminating: drop its bytes,
  // keep only the scanner's line state. Counted once per oversized event; a
  // skippable named event could never have carried usage, so its loss does
  // not degrade the record.
  ENVOY_LOG(debug,
            "ai_protocol_manager: pending SSE data exceeds max_event_size ({}), "
            "discarding this event",
            max_event_size_);
  stats_.sse_event_too_large_.inc();
  if (!skippable) {
    degraded_ = true;
  }
  discarding_ = true;
  buffer_.drain(buffer_.length());
}

bool SseResponseHandler::pendingEventSkippable(absl::string_view tail) {
  // The event's opening lines are within the retained prefix, or within
  // `tail` when nothing is retained yet. linearize() runs only on this rare
  // oversize transition and is bounded by max_event_size_; the caller drains
  // the buffer right after.
  absl::string_view region = tail;
  if (buffer_.length() > 0) {
    region = absl::string_view(static_cast<const char*>(buffer_.linearize(buffer_.length())),
                               buffer_.length());
  }
  const std::optional<absl::string_view> event_type = sseEventTypeView(region);
  return event_type.has_value() && skippableEventType(event_type.value());
}

void SseResponseHandler::onEndStream() {
  if (!parsing_complete_ && !budget_exhausted_ && !discarding_ && buffer_.length() > 0) {
    // Final pass with EOS semantics: a pending event whose terminator only
    // resolves at EOS (e.g. a trailing bare CR) completes here; genuinely
    // incomplete events are discarded per the SSE spec.
    const uint64_t length = buffer_.length();
    absl::string_view view(static_cast<const char*>(buffer_.linearize(length)), length);
    while (!view.empty() && !parsing_complete_ && !budget_exhausted_) {
      const auto result = Http::Sse::SseParser::findEventEnd(view, /*end_stream=*/true);
      if (result.event_start == absl::string_view::npos) {
        break;
      }
      const absl::string_view event =
          view.substr(result.event_start, result.event_end - result.event_start);
      if (eventMayCarryUsage(event)) {
        processSseEvent(event);
      }
      view = view.substr(result.next_start);
    }
    if (!parsing_complete_ && !budget_exhausted_ && !view.empty()) {
      // Discarded incomplete input may have been the usage-bearing final
      // event; an earlier snapshot must not publish as complete.
      ENVOY_LOG(debug,
                "ai_protocol_manager: {} bytes of incomplete SSE input discarded at end of stream",
                view.size());
      stats_.sse_incomplete_event_.inc();
      degraded_ = true;
    }
  }
  // All extraction state is released at EOS regardless of outcome.
  buffer_.drain(buffer_.length());
}

void SseResponseHandler::processSseEvent(absl::string_view event) {
  const auto parsed_event = Http::Sse::SseParser::parseEvent(event);
  if (!parsed_event.data.has_value() || parsed_event.data.value().empty()) {
    // Comment-only keepalives and events without data are normal; skip.
    return;
  }
  const std::string& data = parsed_event.data.value();
  if (data == OpenAiDoneSentinel) {
    parsing_complete_ = true;
    return;
  }

  // Stream-wide parse budget: bounds how many payloads a long-lived stream
  // can make the worker JSON-parse. Exhaustion makes the handler inert.
  if (parse_budget_ == 0) {
    ENVOY_LOG(debug, "ai_protocol_manager: SSE parse budget exhausted, extraction goes inert");
    stats_.sse_event_budget_exhausted_.inc();
    budget_exhausted_ = true;
    degraded_ = true;
    return;
  }
  --parse_budget_;

  JsonWithExtBufParser parser({});
  if (const absl::Status status = parser.feed(data, /*end_stream=*/true); !status.ok()) {
    // Never log payload bytes: they can carry model output or user data.
    ENVOY_LOG(debug, "ai_protocol_manager: {}-byte SSE event data is not valid JSON, skipped",
              data.size());
    stats_.response_parse_error_.inc();
    degraded_ = true;
    return;
  }
  if (processDocument(parser.takeDocument().json())) {
    parsing_complete_ = true;
  }
}

void JsonResponseHandler::abandonOverLimit() {
  ENVOY_LOG(debug,
            "ai_protocol_manager: response body exceeds max_inspected_body_size ({}), "
            "skipping token extraction",
            max_inspected_body_size_);
  stats_.response_body_too_large_.inc();
  degraded_ = true;
  over_limit_ = true;
  parser_.reset();
}

void JsonResponseHandler::onData(const Buffer::Instance& data) {
  if (over_limit_ || parse_failed_ || parsing_complete_) {
    return;
  }
  // The body streams straight into the parser -- no side copy is retained;
  // oversized string values become 16-byte external references rather than
  // materialized bytes.
  if (data.length() > max_inspected_body_size_ - bytes_fed_) {
    abandonOverLimit();
    return;
  }
  for (const Buffer::RawSlice& slice : data.getRawSlices()) {
    bytes_fed_ += slice.len_;
    const absl::Status status = parser_->feed(
        absl::string_view(static_cast<const char*>(slice.mem_), slice.len_), /*end_stream=*/false);
    if (!status.ok()) {
      // Never log payload bytes; the status carries no body content.
      ENVOY_LOG(debug, "ai_protocol_manager: response body is not valid JSON");
      stats_.response_parse_error_.inc();
      degraded_ = true;
      parse_failed_ = true;
      parser_.reset();
      return;
    }
  }
}

void JsonResponseHandler::onEndStream() {
  if (over_limit_ || parse_failed_ || parsing_complete_ || parser_ == nullptr) {
    return;
  }
  parsing_complete_ = true;
  if (bytes_fed_ == 0) {
    // An empty body carries no usage; the outcome matches an eligible
    // headers-only response (missing), independent of HTTP framing.
    parser_.reset();
    return;
  }
  if (const absl::Status status = parser_->feed("", /*end_stream=*/true); !status.ok()) {
    ENVOY_LOG(debug, "ai_protocol_manager: response body is not valid JSON");
    stats_.response_parse_error_.inc();
    degraded_ = true;
    parser_.reset();
    return;
  }
  const nlohmann::json document = std::move(parser_->takeDocument().json());
  parser_.reset();

  // A root-level array is Gemini's default (non-SSE) streaming. Elements are
  // processed in order, stopping at a terminal event so a later element
  // cannot override an authoritative terminal result.
  if (document.is_array()) {
    for (const nlohmann::json& element : document) {
      if (processDocument(element)) {
        break;
      }
    }
    return;
  }

  processDocument(document);
}

absl::string_view apiProtocolName(ApiProtocol protocol) {
  switch (protocol) {
  case ApiProtocol::OpenAiChatCompletions:
    return "OPENAI_CHAT_COMPLETIONS";
  case ApiProtocol::OpenAiResponses:
    return "OPENAI_RESPONSES";
  case ApiProtocol::AnthropicMessages:
    return "ANTHROPIC_MESSAGES";
  case ApiProtocol::GeminiGenerateContent:
    return "GEMINI_GENERATE_CONTENT";
  case ApiProtocol::Unspecified:
    break;
  }
  return "API_PROTOCOL_UNSPECIFIED";
}

void TokenUsage::merge(const TokenUsage& update) {
  // Native updates must not land on a canonicalized accumulator.
  ASSERT(!finalized_);
  const auto take = [](std::optional<uint64_t>& current, const std::optional<uint64_t>& next) {
    if (next.has_value()) {
      current = next;
    }
  };
  take(input_tokens, update.input_tokens);
  take(output_tokens, update.output_tokens);
  take(total_tokens, update.total_tokens);
  take(cached_input_tokens, update.cached_input_tokens);
  take(cache_creation_input_tokens, update.cache_creation_input_tokens);
  take(tool_use_input_tokens, update.tool_use_input_tokens);
  take(reasoning_tokens, update.reasoning_tokens);
  if (!update.model.empty()) {
    model = update.model;
  }
  if (update.api_protocol != ApiProtocol::Unspecified) {
    api_protocol = update.api_protocol;
  }
}

void TokenUsage::finalize(const ApiProtocolAdapter& adapter) {
  // Canonicalization rules are per dialect: the adapter must be the
  // accumulator's own (finalizeUsage() in api_protocol_adapter.h wires this).
  ASSERT(adapter.protocol() == api_protocol);
  // The summations below must not run twice.
  ASSERT(!finalized_);
  if (finalized_) {
    return;
  }
  finalized_ = true;
  // Canonicalize the accumulated native counts per dialect (see the header
  // for why this must not run per event).
  adapter.canonicalizeUsage(*this, canonicalization_overflow_);

  // The provider-reported total (riding total_tokens during accumulation)
  // moves to its own field, always preserved. total_tokens is exclusively the
  // canonical sum, present only when both components are known and the sum
  // round-trips exactly through the double-backed metadata field -- so its
  // meaning never depends on what else was reported.
  provider_total_tokens = total_tokens;
  total_tokens.reset();
  if (input_tokens.has_value() && output_tokens.has_value()) {
    const uint64_t sum = input_tokens.value() + output_tokens.value();
    if (sum <= MaxSafeCount) {
      total_tokens = sum;
    } else {
      // Not exactly representable in the double-backed Struct projection:
      // publish no canonical total and flag the record.
      canonicalization_overflow_ = true;
    }
  }
}

void initializeWithResponseHandling(bool upstream_filter) {
    config_helper_.prependFilter(R"EOF(
name: envoy.filters.http.ai_protocol_manager
typed_config:
  "@type": type.googleapis.com/envoy.extensions.filters.http.ai_protocol_manager.v3.AiProtocolManager
  response_handling:
    token_usage:
      include_unconfigured_routes: true
)EOF",
                                 /*downstream=*/!upstream_filter);
    initialize();
  }

Http::TestRequestHeaderMapImpl requestHeaders() {
    return Http::TestRequestHeaderMapImpl{{":method", "POST"},
                                          {":path", "/v1/chat/completions"},
                                          {":scheme", "http"},
                                          {":authority", "sni.lyft.com"}};
  }

uint64_t sumCounters(absl::string_view suffix) {
    uint64_t total = 0;
    for (const auto& counter : test_server_->counters()) {
      if (absl::EndsWith(counter->name(), suffix)) {
        total += counter->value();
      }
    }
    return total;
  }

TEST_P(AiProtocolManagerResponseIntegrationTest, SseTokenUsagePublished) {
  initializeWithResponseHandling(/*upstream_filter=*/false);

  codec_client_ = makeHttpConnection(lookupPort("http"));
  auto response = codec_client_->makeRequestWithBody(requestHeaders(), "{\"stream\":true}");
  waitForNextUpstreamRequest();

  const std::string chunk1 = "data: {\"object\":\"chat.completion.chunk\",\"model\":\"gpt-4o\","
                             "\"choices\":[{\"delta\":{\"content\":\"hi\"}}],\"usage\":null}\n\n";
  const std::string chunk2 =
      "data: {\"object\":\"chat.completion.chunk\",\"model\":\"gpt-4o\",\"choices\":[],"
      "\"usage\":{\"prompt_tokens\":19,\"completion_tokens\":10,\"total_tokens\":29}}\n\n"
      "data: [DONE]\n\n";
  upstream_request_->encodeHeaders(responseHeaders("text/event-stream"), false);
  upstream_request_->encodeData(chunk1, false);
  upstream_request_->encodeData(chunk2, true);

  ASSERT_TRUE(response->waitForEndStream());
  ASSERT_TRUE(response->complete());
  // Observe-only: the response body reaches the client byte-for-byte.
  EXPECT_EQ(chunk1 + chunk2, response->body());

  EXPECT_EQ(sumCounters("ai_protocol_manager.token_usage_found"), 1);
  EXPECT_EQ(sumCounters("ai_protocol_manager.token_usage_missing"), 0);
}

TEST_P(AiProtocolManagerResponseIntegrationTest, UpstreamFilterJsonTokenUsage) {
  initializeWithResponseHandling(/*upstream_filter=*/true);

  codec_client_ = makeHttpConnection(lookupPort("http"));
  auto response = codec_client_->makeRequestWithBody(requestHeaders(), "{\"model\":\"claude\"}");
  waitForNextUpstreamRequest();
  EXPECT_EQ("{\"model\":\"claude\"}", upstream_request_->body().toString());

  const std::string body = "{\"id\":\"msg_1\",\"type\":\"message\",\"model\":\"claude-opus-5\","
                           "\"usage\":{\"input_tokens\":2095,\"output_tokens\":503}}";
  upstream_request_->encodeHeaders(responseHeaders("application/json"), false);
  upstream_request_->encodeData(body, true);

  ASSERT_TRUE(response->waitForEndStream());
  ASSERT_TRUE(response->complete());
  EXPECT_EQ(body, response->body());

  EXPECT_EQ(sumCounters("ai_protocol_manager.token_usage_found"), 1);
}

TEST_P(AiProtocolManagerResponseIntegrationTest, RetryPublishesWinningAttemptOnly) {
  config_helper_.addConfigModifier(
      [](envoy::extensions::filters::network::http_connection_manager::v3::HttpConnectionManager&
             hcm) {
        auto* retry_policy = hcm.mutable_route_config()
                                 ->mutable_virtual_hosts(0)
                                 ->mutable_routes(0)
                                 ->mutable_route()
                                 ->mutable_retry_policy();
        retry_policy->set_retry_on("5xx");
        retry_policy->mutable_num_retries()->set_value(1);
      });
  initializeWithResponseHandling(/*upstream_filter=*/true);

  codec_client_ = makeHttpConnection(lookupPort("http"));
  auto response = codec_client_->makeRequestWithBody(requestHeaders(), "{}");

  // First attempt fails with a completed 5xx; the router retries on a new
  // stream. The 5xx never engages extraction (non-2xx).
  waitForNextUpstreamRequest();
  upstream_request_->encodeHeaders(Http::TestResponseHeaderMapImpl{{":status", "503"}}, true);

  // Winning attempt returns usage.
  ASSERT_TRUE(fake_upstream_connection_->waitForNewStream(*dispatcher_, upstream_request_));
  ASSERT_TRUE(upstream_request_->waitForEndStream(*dispatcher_));
  const std::string body = "{\"type\":\"message\",\"model\":\"claude-opus-5\","
                           "\"usage\":{\"input_tokens\":7,\"output_tokens\":8}}";
  upstream_request_->encodeHeaders(responseHeaders("application/json"), false);
  upstream_request_->encodeData(body, true);

  ASSERT_TRUE(response->waitForEndStream());
  ASSERT_TRUE(response->complete());
  EXPECT_EQ("200", response->headers().getStatusValue());

  // Only the winning attempt's filter instance publishes.
  EXPECT_EQ(sumCounters("ai_protocol_manager.token_usage_found"), 1);
  EXPECT_EQ(sumCounters("ai_protocol_manager.token_usage_duplicate"), 0);
}

TEST_P(AiProtocolManagerResponseIntegrationTest, ResponseOnlyModeDoesNotHoldRequestHeaders) {
  config_helper_.prependFilter(R"EOF(
name: envoy.filters.http.ai_protocol_manager
typed_config:
  "@type": type.googleapis.com/envoy.extensions.filters.http.ai_protocol_manager.v3.AiProtocolManager
  response_handling:
    token_usage:
      include_unconfigured_routes: true
)EOF",
                               /*downstream=*/false);
  initialize();

  codec_client_ = makeHttpConnection(lookupPort("http"));
  auto encoder_decoder = codec_client_->startRequest(requestHeaders());
  request_encoder_ = &encoder_decoder.first;
  auto response = std::move(encoder_decoder.second);

  // Headers arrive upstream while the request body has not been sent: no hold.
  ASSERT_TRUE(fake_upstreams_[0]->waitForHttpConnection(*dispatcher_, fake_upstream_connection_));
  ASSERT_TRUE(fake_upstream_connection_->waitForNewStream(*dispatcher_, upstream_request_));
  ASSERT_TRUE(upstream_request_->waitForHeadersComplete());

  codec_client_->sendData(*request_encoder_, "{}", true);
  ASSERT_TRUE(upstream_request_->waitForEndStream(*dispatcher_));

  upstream_request_->encodeHeaders(responseHeaders("application/json"), false);
  upstream_request_->encodeData("{\"type\":\"message\",\"model\":\"claude-haiku-4-5\","
                                "\"usage\":{\"input_tokens\":5,\"output_tokens\":7}}",
                                true);
  ASSERT_TRUE(response->waitForEndStream());
  ASSERT_TRUE(response->complete());

  EXPECT_EQ(sumCounters("ai_protocol_manager.token_usage_found"), 1);
  EXPECT_EQ(sumCounters("ai_protocol_manager.token_usage_partial"), 0);
}

TEST_P(AiProtocolManagerResponseIntegrationTest, BothPlacementsSinglePublication) {
  config_helper_.prependFilter(R"EOF(
name: envoy.filters.http.ai_protocol_manager
typed_config:
  "@type": type.googleapis.com/envoy.extensions.filters.http.ai_protocol_manager.v3.AiProtocolManager
  response_handling:
    token_usage:
      include_unconfigured_routes: true
)EOF",
                               /*downstream=*/false);
  config_helper_.prependFilter(R"EOF(
name: envoy.filters.http.ai_protocol_manager
typed_config:
  "@type": type.googleapis.com/envoy.extensions.filters.http.ai_protocol_manager.v3.AiProtocolManager
  response_handling:
    token_usage:
      include_unconfigured_routes: true
      limits:
        max_sse_event_size: 64
)EOF",
                               /*downstream=*/true);
  initialize();

  codec_client_ = makeHttpConnection(lookupPort("http"));
  auto response = codec_client_->makeRequestWithBody(requestHeaders(), "{}");
  waitForNextUpstreamRequest();

  // Over the downstream instance's 64-byte cap; well under the upstream
  // instance's default cap.
  upstream_request_->encodeHeaders(responseHeaders("text/event-stream"), false);
  upstream_request_->encodeData(
      "data: {\"object\":\"chat.completion.chunk\",\"model\":\"gpt-4o\",\"choices\":[],"
      "\"usage\":{\"prompt_tokens\":19,\"completion_tokens\":10,\"total_tokens\":29}}\n\n"
      "data: [DONE]\n\n",
      true);

  ASSERT_TRUE(response->waitForEndStream());
  ASSERT_TRUE(response->complete());

  // The upstream instance publishes once; the downstream instance sees the
  // occupied namespace and skips instead of writing a second record.
  EXPECT_EQ(sumCounters("ai_protocol_manager.token_usage_found"), 1);
  EXPECT_EQ(sumCounters("ai_protocol_manager.token_usage_duplicate"), 1);
}

TEST_P(AiProtocolManagerHedgeIntegrationTest, HedgedRequestPublishesWinnerOnly) {
  config_helper_.prependFilter(R"EOF(
name: envoy.filters.http.ai_protocol_manager
typed_config:
  "@type": type.googleapis.com/envoy.extensions.filters.http.ai_protocol_manager.v3.AiProtocolManager
  response_handling:
    token_usage:
      include_unconfigured_routes: true
)EOF",
                               /*downstream=*/false);
  initialize();

  codec_client_ = makeHttpConnection(makeClientConnection(lookupPort("http")));
  // The complete request is sent up front: the upstream-chain filter offloads
  // the payload before releasing headers toward the upstream, so a request
  // whose body trails until the upstream responds would never be issued.
  auto response = codec_client_->makeRequestWithBody(
      Http::TestRequestHeaderMapImpl{{":method", "POST"},
                                     {":path", "/test/long/url"},
                                     {":scheme", "http"},
                                     {":authority", "sni.lyft.com"},
                                     // Marks the request internal so the x-envoy-*
                                     // timeout/hedge headers below are honored.
                                     {"x-forwarded-for", "10.0.0.1"},
                                     {"x-envoy-retry-on", "5xx"},
                                     {"x-envoy-hedge-on-per-try-timeout", "true"},
                                     {"x-envoy-upstream-rq-timeout-ms", "5000"},
                                     {"x-envoy-upstream-rq-per-try-timeout-ms", "400"}},
      "{}");

  ASSERT_TRUE(fake_upstreams_[0]->waitForHttpConnection(*dispatcher_, fake_upstream_connection_));
  ASSERT_TRUE(fake_upstream_connection_->waitForNewStream(*dispatcher_, upstream_request_));
  ASSERT_TRUE(upstream_request_->waitForEndStream(*dispatcher_));

  // Trigger the per-try timeout (not the global timeout): the original
  // attempt stays alive and a hedged second attempt is issued after the 25ms
  // retry backoff.
  timeSystem().advanceTimeWait(std::chrono::milliseconds(400));
  timeSystem().advanceTimeWait(std::chrono::milliseconds(26));

  FakeStreamPtr upstream_request2;
  ASSERT_TRUE(fake_upstream_connection_->waitForNewStream(*dispatcher_, upstream_request2));
  ASSERT_TRUE(upstream_request2->waitForHeadersComplete());
  ASSERT_TRUE(upstream_request2->waitForEndStream(*dispatcher_));

  // The second attempt wins with a streamed usage-carrying response.
  upstream_request2->encodeHeaders(
      Http::TestResponseHeaderMapImpl{{":status", "200"}, {"content-type", "application/json"}},
      false);
  upstream_request2->encodeData("{\"type\":\"message\",\"model\":\"claude-opus-5\","
                                "\"usage\":{\"input_tokens\":7,\"output_tokens\":8}}",
                                true);
  ASSERT_TRUE(response->waitForEndStream());

  // The losing first attempt is reset by the router once the winner is
  // selected: its filter instance is destroyed before a clean end of stream
  // and never publishes.
  ASSERT_TRUE(upstream_request_->waitForReset(std::chrono::seconds(15)));
  codec_client_->close();

  EXPECT_TRUE(response->complete());
  EXPECT_EQ("200", response->headers().getStatusValue());
  // Only the router-selected attempt's filter instance publishes.
  uint64_t found = 0;
  for (const auto& counter : test_server_->counters()) {
    if (absl::EndsWith(counter->name(), "ai_protocol_manager.token_usage_found")) {
      found += counter->value();
    }
  }
  EXPECT_EQ(found, 1);
}

void SetUp() override {
    setDownstreamProtocol(Http::CodecType::HTTP2);
    // Populates the cluster's HttpProtocolOptions.upstream_protocol_options,
    // required once upstream http_filters are configured on the cluster.
    setUpstreamProtocol(Http::CodecType::HTTP2);
  }

void initializeWithExtProc(bool upstream_filter, bool trailer_mode = false) {
    // The processor captures the metadata_context of the stream-terminating
    // message -- the end-of-stream response_body message, or the
    // response_trailers message when the response ends in trailers;
    // observability mode means no responses are needed.
    test_processor_.start(
        GetParam(),
        [this](grpc::ServerReaderWriter<envoy::service::ext_proc::v3::ProcessingResponse,
                                        envoy::service::ext_proc::v3::ProcessingRequest>* stream) {
          envoy::service::ext_proc::v3::ProcessingRequest request;
          while (stream->Read(&request)) {
            const bool terminal =
                (request.has_response_body() && request.response_body().end_of_stream()) ||
                request.has_response_trailers();
            if (!terminal || metadata_seen_.HasBeenNotified()) {
              continue;
            }
            const auto& typed_metadata = request.metadata_context().typed_filter_metadata();
            const auto typed_entry = typed_metadata.find("envoy.ai.token_usage");
            if (typed_entry != typed_metadata.end()) {
              ASSERT_TRUE(typed_entry->second.UnpackTo(&captured_typed_usage_));
              metadata_seen_.Notify();
            }
          }
        });

    // AI Protocol Manager first...
    config_helper_.prependFilter(R"EOF(
name: envoy.filters.http.ai_protocol_manager
typed_config:
  "@type": type.googleapis.com/envoy.extensions.filters.http.ai_protocol_manager.v3.AiProtocolManager
  response_handling:
    token_usage:
      include_unconfigured_routes: true
)EOF",
                                 /*downstream=*/!upstream_filter);

    // ...then ext_proc prepended to the head of the downstream chain: encoder
    // filters run in reverse list order, so in the downstream installation the
    // AI Protocol Manager executes before ext_proc on the encode path.
    config_helper_.addConfigModifier([this, trailer_mode](
                                         envoy::config::bootstrap::v3::Bootstrap& bootstrap) {
      auto* processor_cluster = bootstrap.mutable_static_resources()->add_clusters();
      processor_cluster->set_name("ext_proc_server");
      processor_cluster->mutable_load_assignment()->set_cluster_name("ext_proc_server");
      auto* address = processor_cluster->mutable_load_assignment()
                          ->add_endpoints()
                          ->add_lb_endpoints()
                          ->mutable_endpoint()
                          ->mutable_address()
                          ->mutable_socket_address();
      address->set_address(Network::Test::getLoopbackAddressString(GetParam()));
      address->set_port_value(test_processor_.port());
      ConfigHelper::setHttp2(*processor_cluster);

      envoy::extensions::filters::http::ext_proc::v3::ExternalProcessor ext_proc;
      ext_proc.mutable_grpc_service()->mutable_envoy_grpc()->set_cluster_name("ext_proc_server");
      ext_proc.set_observability_mode(true);
      ext_proc.mutable_processing_mode()->set_request_header_mode(
          envoy::extensions::filters::http::ext_proc::v3::ProcessingMode::SKIP);
      ext_proc.mutable_processing_mode()->set_response_header_mode(
          envoy::extensions::filters::http::ext_proc::v3::ProcessingMode::SEND);
      if (trailer_mode) {
        // The sharper variant of the documented consumer requirement: with
        // body mode NONE (the ext_proc default) the *only* message that can
        // carry the usage metadata for a trailer-ended response is the
        // response_trailers message, which requires SEND (default is SKIP).
        ext_proc.mutable_processing_mode()->set_response_trailer_mode(
            envoy::extensions::filters::http::ext_proc::v3::ProcessingMode::SEND);
      } else {
        ext_proc.mutable_processing_mode()->set_response_body_mode(
            envoy::extensions::filters::http::ext_proc::v3::ProcessingMode::STREAMED);
      }
      ext_proc.mutable_metadata_options()->mutable_forwarding_namespaces()->add_typed(
          "envoy.ai.token_usage");

      envoy::config::listener::v3::Filter ext_proc_filter;
      ext_proc_filter.set_name("envoy.filters.http.ext_proc");
      std::ignore = ext_proc_filter.mutable_typed_config()->PackFrom(ext_proc);
      config_helper_.prependFilter(MessageUtil::getJsonStringFromMessageOrError(ext_proc_filter));
    });

    initialize();
  }

void runJsonUsageRequest(bool end_with_trailers = false) {
    codec_client_ = makeHttpConnection(lookupPort("http"));
    auto response = codec_client_->makeRequestWithBody(
        Http::TestRequestHeaderMapImpl{{":method", "POST"},
                                       {":path", "/v1/messages"},
                                       {":scheme", "http"},
                                       {":authority", "sni.lyft.com"}},
        "{}");
    waitForNextUpstreamRequest();
    upstream_request_->encodeHeaders(
        Http::TestResponseHeaderMapImpl{{":status", "200"}, {"content-type", "application/json"}},
        false);
    upstream_request_->encodeData("{\"type\":\"message\",\"model\":\"claude-opus-5\","
                                  "\"usage\":{\"input_tokens\":5,\"output_tokens\":7}}",
                                  /*end_stream=*/!end_with_trailers);
    if (end_with_trailers) {
      // The body ends via trailers: the filter finalizes and publishes on the
      // encodeTrailers callback, before ext_proc snapshots its
      // response_trailers message.
      Http::TestResponseTrailerMapImpl trailers{{"x-resp-trailer", "yes"}};
      upstream_request_->encodeTrailers(trailers);
    }
    ASSERT_TRUE(response->waitForEndStream());
    ASSERT_TRUE(response->complete());
    EXPECT_EQ("200", response->headers().getStatusValue());
  }

void expectUsageMetadataAtProcessor() {
    ASSERT_TRUE(metadata_seen_.WaitForNotificationWithTimeout(absl::Seconds(5)));
    // The authoritative typed record arrives through the typed forwarding
    // namespace with full integer fidelity.
    EXPECT_EQ(captured_typed_usage_.input_tokens().value(), 5);
    EXPECT_EQ(captured_typed_usage_.output_tokens().value(), 7);
    EXPECT_EQ(captured_typed_usage_.total_tokens().value(), 12);
    EXPECT_EQ(captured_typed_usage_.api_protocol(), envoy::type::ai::v3::ANTHROPIC_MESSAGES);
    EXPECT_EQ(captured_typed_usage_.extraction_status(), envoy::data::ai::v3::TokenUsage::COMPLETE);
  }

