    } else {
      for (size_t offset = 0; offset < stream.size(); offset += frame_size) {
        Buffer::OwnedImpl frame(absl::string_view(stream).substr(offset, frame_size));
        handler.onData(frame);
      }
    }
    handler.onEndStream();
    benchmark::DoNotOptimize(handler.usage().total_tokens);
