  feed(handler,
       ": ping\rdata: {\"usageMetadata\":{\"promptTokenCount\":1,\"candidatesTokenCount\":2,"
       "\"totalTokenCount\":3}}\r\r"
       "data: {\"usageMetadata\":{\"promptTokenCount\":6,\"candidatesTokenCount\":16,"
