TEST_F(ResponseHandlerTest, SseTerminalSentinelStopsMultiSliceScan) {
  SseResponseHandler handler(ApiProtocol::OpenAiChatCompletions, TestMaxEventSize,
                             TestMaxParsedEvents, stats_);
  Buffer::OwnedImpl buffer;
