            std::string(MethodGroups::TASK));
}

absl::Status setupWithStatus(const std::string& lib_id, const std::string& lib_path,
                               const std::string& plugin_name) {
    RETURN_IF_NOT_OK(setupConfig(proto_config, per_route_proto_config, plugin_name));
    return absl::OkStatus();
  }

void setup(const std::string& lib_id, const std::string& lib_path,
             const std::string& plugin_name) {
    ASSERT_TRUE(setupWithStatus(lib_id, lib_path, plugin_name).ok());
  absl::Status setupConfig(
    RETURN_IF_NOT_OK(config_->newGoPluginConfig());
    return absl::OkStatus();
  auto status = setupWithStatus(ROUTECONFIG, genSoPath(), ROUTECONFIG);
  EXPECT_THAT(status, HasStatus(absl::StatusCode::kInvalidArgument,
                                testing::HasSubstr("golang filter failed to parse plugin config")));
  ASSERT_TRUE(config->newGoPluginConfig().ok());
  ASSERT_TRUE(config->newGoPluginConfig().ok());

TEST_F(RandomShardRequestTest, ClusterShards) {
  InSequence s;

  setup({"cluster", "shards"});
  EXPECT_NE(nullptr, handle_);

  time_system_.setMonotonicTime(std::chrono::milliseconds(10));
  EXPECT_CALL(store_, deliverHistogramToSinks(
                          Property(&Stats::Metric::name, "redis.foo.command.cluster.latency"), 10));
  EXPECT_CALL(callbacks_, onResponse_(_));
  pool_callbacks_[0]->onResponse(response());

  EXPECT_EQ(1UL, store_.counter("redis.foo.command.cluster.total").value());
  EXPECT_EQ(1UL, store_.counter("redis.foo.command.cluster.success").value());
}

void ForEachGradientSample(Context const* ctx, bst_idx_t n_samples,
                           common::Span<float const> reg_abs_grad, float threshold,
                           std::uint64_t initial_seed, Fn&& fn) {
  ParallelSampling(ctx, n_samples, initial_seed,
                   [&](std::size_t ibegin, std::size_t iend, auto& eng) {
                     std::uniform_real_distribution<float> dist{0.0f, 1.0f};
                     for (std::size_t i = ibegin; i < iend; ++i) {
                       auto p = SamplingProbability(threshold, reg_abs_grad[i]);
                       // Consume exactly one random value per row for thread-count
                       // independence and replay.
                       auto rnd = dist(eng);
                       fn(i, p, IsSampled(p, rnd));
                     }
                   });
}

TEST(CpuSampler, ZeroSampleRows) {
  Context ctx;
  constexpr std::size_t kRows = 2;
  std::size_t shape[2] = {kRows, 1};
  linalg::Matrix<GradientPair> split_gpair{shape, ctx.Device()};
  auto h_split = split_gpair.HostView();
  std::fill(linalg::begin(h_split), linalg::end(h_split), GradientPair{1.0e20f, 1.0f});
  linalg::Matrix<GradientPair> original_split{shape, ctx.Device()};
  original_split.Data()->Copy(*split_gpair.Data());

  linalg::Matrix<GradientPair> value_gpair{shape, ctx.Device()};
  auto h_value = value_gpair.HostView();
  std::fill(linalg::begin(h_value), linalg::end(h_value), GradientPair{1.0f, 1.0f});

  TrainParam param;
  param.UpdateAllowUnknown(Args{{"subsample", "0"}, {"sampling_method", "gradient_based"}});
  Sampler sampler{param};
  sampler.Sample(&ctx, split_gpair.HostView());
  sampler.ApplySampling(&ctx, original_split.HostView(), &value_gpair);

  for (std::size_t i = 0; i < kRows; ++i) {
    EXPECT_EQ(h_split(i, 0), GradientPair{});
    EXPECT_EQ(h_value(i, 0), GradientPair{});
  }
}

void UnlockPrompt::collectionRetired(Collection* coll)
    {
        // the collection is going away (already removed from DBus, backend reset);
        // stop referencing it so no doUnlock/doneUnlockCollection is attempted on it
        for (auto& p : m_collections) {
            if (p == coll) {
                p = nullptr;
            }
        }
        m_items.remove(coll);

        if (!m_pendingCollections.remove(coll)) {
            // nothing was issued for it yet (promptSync not run) or it already resolved;
            // promptSync accounts for cleared entries itself
            return;
        }

        // treat as if the collection rejected the unlock
        m_numRejected += 1;
        if (m_pendingCollections.isEmpty()) {
            unlockItems();
        }
    }

void TestGuiFdoSecrets::testServiceUnlockConcurrentDelete()
{
    lockDatabaseInBackend();

    auto service = enableService();
    VERIFY(service);
    auto coll = getDefaultCollection(service);
    VERIFY(coll);

    DBUS_GET2(unlocked, promptPath, service->Unlock({QDBusObjectPath(coll->path())}));
    COMPARE(unlocked, {});

    auto prompt = getProxy<PromptProxy>(promptPath);
    VERIFY(prompt);
    QSignalSpy spyPromptCompleted(prompt.data(), SIGNAL(Completed(bool, QDBusVariant)));
    VERIFY(spyPromptCompleted.isValid());

    // show the unlock dialog, but do not interact with it
    DBUS_VERIFY(prompt->Prompt(""));
    VERIFY(waitForSignal(spyPromptCompleted, 0));

    // while the unlock prompt is waiting for the user, the collection gets deleted
    DBUS_GET(deletePromptPath, coll->Delete());
    auto deletePrompt = getProxy<PromptProxy>(deletePromptPath);
    VERIFY(deletePrompt);
    QSignalSpy spyDeletePromptCompleted(deletePrompt.data(), SIGNAL(Completed(bool, QDBusVariant)));
    VERIFY(spyDeletePromptCompleted.isValid());
    DBUS_VERIFY(deletePrompt->Prompt(""));

    // the deletion completes
    VERIFY(waitForSignal(spyDeletePromptCompleted, 1));
    {
        auto args = spyDeletePromptCompleted.takeFirst();
        COMPARE(args.count(), 2);
        COMPARE(args.at(0).toBool(), false);
    }

    // the unlock prompt completes as dismissed with nothing unlocked, instead of
    // waiting forever for a collection that no longer exists
    VERIFY(waitForSignal(spyPromptCompleted, 1));
    {
        auto args = spyPromptCompleted.takeFirst();
        COMPARE(args.count(), 2);
        COMPARE(args.at(0).toBool(), true);
        auto unlockedResult = getSignalVariantArgument<QList<QDBusObjectPath>>(args.at(1));
        VERIFY(unlockedResult.isEmpty());
    }

    // dismiss the leftover unlock dialog so it does not interfere with other tests
    auto dbOpenDlg = m_tabWidget->findChild<DatabaseOpenDialog*>();
    if (dbOpenDlg && dbOpenDlg->isVisible()) {
        dbOpenDlg->reject();
        processEvents();
    }

    // reopen the database; the service must still be able to show unlock dialogs.
    // A stale Service::m_unlockingDb entry keyed by the destroyed widget used to
    // block the unlock-any-database dialog forever.
    m_tabWidget->addDatabaseTab(m_dbFile->fileName(), false, "a");
    m_dbWidget = m_tabWidget->currentDatabaseWidget();
    m_db = m_dbWidget->database();
    processEvents();

    auto entries = m_db->rootGroup()->entriesRecursive();
    VERIFY(!entries.isEmpty());
    auto title = entries.first()->title();

    lockDatabaseInBackend();

    FdoSecrets::settings()->setUnlockBeforeSearch(true);
    bool unlockDialogWorks = false;
    QTimer::singleShot(50, [&]() { unlockDialogWorks = driveUnlockDialog(); });
    DBUS_GET2(unlockedItems, lockedItems, service->SearchItems({{"Title", title}}));
    VERIFY(unlockDialogWorks);
    COMPARE(lockedItems, {});
    COMPARE(unlockedItems.size(), 1);
}

void TestEntry::testHistoryItemCustomData()
{
    QScopedPointer<Entry> entry(new Entry());
    entry->setUuid(QUuid::createUuid());
    entry->setTitle("Original Title");
    entry->customData()->set("CustomKey", "CustomValue");

    entry->beginUpdate();
    entry->setTitle("New Title");
    entry->endUpdate();

    // The history item must carry the custom data present before the update
    QCOMPARE(entry->historyItems().size(), 1);
    const Entry* historyItem = entry->historyItems().constFirst();
    QCOMPARE(historyItem->customData()->value("CustomKey"), QString("CustomValue"));

    // Restoring from the history item restores the custom data
    entry->customData()->remove("CustomKey");
    QVERIFY(entry->customData()->isEmpty());

    entry->copyDataFrom(historyItem);
    QCOMPARE(entry->customData()->value("CustomKey"), QString("CustomValue"));
}

void TestConfig::testURLDoubleClickMigration()
{
    // Test migration from OpenURLOnDoubleClick to URLDoubleClickAction
    TemporaryFile tempFile;
    tempFile.open();

    // Create a config with old setting = true (open browser)
    QSettings oldConfig(tempFile.fileName(), QSettings::IniFormat);
    oldConfig.setValue("OpenURLOnDoubleClick", true);
    oldConfig.sync();
    tempFile.close();

    Config::createConfigFromFile(tempFile.fileName());

    // Should migrate to URLDoubleClickAction = 0 (open browser)
    QCOMPARE(config()->get(Config::URLDoubleClickAction).toInt(), 0);

    tempFile.remove();

    // Test migration from OpenURLOnDoubleClick = false (edit entry)
    TemporaryFile tempFile2;
    tempFile2.open();

    QSettings oldConfig2(tempFile2.fileName(), QSettings::IniFormat);
    oldConfig2.setValue("OpenURLOnDoubleClick", false);
    oldConfig2.sync();
    tempFile2.close();

    Config::createConfigFromFile(tempFile2.fileName());

    // Should migrate to URLDoubleClickAction = 2 (edit entry)
    QCOMPARE(config()->get(Config::URLDoubleClickAction).toInt(), 2);

    tempFile2.remove();
}

void TestEntry::testResolveUuidPlaceholder()
{
    Database db;
    auto* root = db.rootGroup();

    auto* entry = new Entry();
    entry->setGroup(root);
    entry->setUuid(QUuid::createUuid());
    entry->setTitle("Test Entry");
    entry->setUsername("TestUser");
    entry->setPassword("TestPass");
    entry->setNotes("Test with UUID: {UUID}");

    // Test that {UUID} placeholder resolves to the entry's UUID
    QString expectedUuid = entry->uuidToHex();
    QString resolvedNotes = entry->resolveMultiplePlaceholders(entry->notes());
    QCOMPARE(resolvedNotes, QString("Test with UUID: %1").arg(expectedUuid));

    // Test {UUID} placeholder directly
    QCOMPARE(entry->resolveMultiplePlaceholders("{UUID}"), expectedUuid);

    // Test case insensitivity
    QCOMPARE(entry->resolveMultiplePlaceholders("{uuid}"), expectedUuid);
    QCOMPARE(entry->resolveMultiplePlaceholders("{Uuid}"), expectedUuid);

    // Test mixed case in text
    QCOMPARE(entry->resolveMultiplePlaceholders("UUID is {UUID} here"), QString("UUID is %1 here").arg(expectedUuid));

    // Test advanced attribute with {REF:U@I:{UUID}} - should resolve to the entry's own username
    entry->attributes()->set("SelfReference", "{REF:U@I:{UUID}}");
    QString attributeValue = entry->attributes()->value("SelfReference");
    QString resolvedSelfRef = entry->resolveMultiplePlaceholders(attributeValue);

    // Test the manual reference to confirm it works as before
    QString manualReference = QString("{REF:U@I:%1}").arg(entry->uuidToHex());
    entry->attributes()->set("ManualReference", manualReference);
    QString resolvedManualRef = entry->resolveMultiplePlaceholders(entry->attributes()->value("ManualReference"));

    // Test that both approaches work
    QCOMPARE(resolvedManualRef, entry->username());
    QCOMPARE(resolvedSelfRef, entry->username());
}

bool DatabaseWidget::hasRecycledSelectedEntries() const
{
    if (!m_entryView) {
        return false;
    }

    // Check if any of the selected entries are actually recycled
    for (auto* entry : m_entryView->selectedEntries()) {
        if (entry && entry->isRecycled()) {
            return true;
        }
    }

    return false;
}

void TextAttachmentsPreviewWidget::matchScroll(double percent)
{
    // Match the scroll position of the text browser to the given percentage
    int maxScroll = m_ui->previewTextBrowser->verticalScrollBar()->maximum();
    int newScrollPos = static_cast<int>(maxScroll * percent);
    m_ui->previewTextBrowser->verticalScrollBar()->setValue(newScrollPos);

void TextAttachmentsWidget::updatePreviewWidget()
{
    m_previewVisible = isPreviewVisible();
    if (m_previewVisible) {
        m_attachment = m_editWidget->getAttachment();
        m_previewWidget->openAttachment(m_attachment, attachments::OpenMode::ReadOnly);
    }
    connect(m_previewUpdateTimer, &QTimer::timeout, this, &TextAttachmentsWidget::updatePreviewWidget);
    connect(m_editWidget,
            &TextAttachmentsEditWidget::scrollChanged,
            m_previewWidget,
            &TextAttachmentsPreviewWidget::matchScroll);
        // Split the display in half if showing the preview widget
        const auto previewSize = isPreviewVisible() ? 0 : m_splitter->width() / 2;
        const auto editSize = m_splitter->width() - previewSize;
        m_splitter->setSizes({editSize, previewSize});
        updatePreviewWidget();
    }

void SearchWidget::performRequestedSearch(const QString& text)
{
    // This method handles saved searches - it should set the text and immediately trigger search
    // without any delay, regardless of the "Press Enter to search" setting
    m_ui->searchEdit->setText(text);
    m_ui->saveIcon->setVisible(!text.isEmpty());
    emit search(text);
}

void SearchWidget::updateSaveButtonVisibility()
{
    // Show save button whenever there's non-empty text in the search field
    m_ui->saveIcon->setVisible(!m_ui->searchEdit->text().isEmpty());
}

void EntryView::jumpToGroupShortcut()
{
    // Only allow jump to group in search mode
    if (!inSearchMode()) {
        return;
    }

    auto entry = currentEntry();
    if (entry) {
        // Emit the entryActivated signal with ParentGroup column to trigger jump to group
        emit entryActivated(entry, EntryModel::ParentGroup);
    }
}

void TestEntrySearcher::testTotpSearch()
{
    auto entry1 = new Entry();
    entry1->setGroup(m_rootGroup);
    entry1->setTitle("Regular Entry");

    auto entry2 = new Entry();
    entry2->setGroup(m_rootGroup);
    entry2->setTitle("TOTP Entry");
    // Set up TOTP on entry2
    auto totpSettings = Totp::createSettings("GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ", 6, 30);
    entry2->setTotp(totpSettings);

    auto entry3 = new Entry();
    entry3->setGroup(m_rootGroup);
    entry3->setTitle("Another TOTP Entry");
    // Set up TOTP on entry3
    auto totpSettings2 = Totp::createSettings("MFRGG43UEBUXGIDBKRWXAZLSMUQGG6LQ", 6, 30);
    entry3->setTotp(totpSettings2);

    // Test searching for TOTP entries
    m_searchResult = m_entrySearcher.search("has:totp", m_rootGroup);
    QCOMPARE(m_searchResult.count(), 2);
    QVERIFY(m_searchResult.contains(entry2));
    QVERIFY(m_searchResult.contains(entry3));
    QVERIFY(!m_searchResult.contains(entry1));

    // Test case insensitive search
    m_searchResult = m_entrySearcher.search("has:TOTP", m_rootGroup);
    QCOMPARE(m_searchResult.count(), 2);

    // Test excluding TOTP entries
    m_searchResult = m_entrySearcher.search("!has:totp", m_rootGroup);
    QCOMPARE(m_searchResult.count(), 1);
    QVERIFY(m_searchResult.contains(entry1));
    QVERIFY(!m_searchResult.contains(entry2));
    QVERIFY(!m_searchResult.contains(entry3));
}

EiClipboard::EiClipboard(ClipboardID id) : m_id(id)
{
  open(0);
  empty();
  close();
}

bool EiClipboard::empty()
{
  if (!m_open) {
    LOG_WARN("cannot empty clipboard, not open");
    return false;
  }

  // Clear all data
  for (int32_t index = 0; index < static_cast<int>(Format::TotalFormats); ++index) {
    m_data[index] = "";
    m_added[index] = false;
  }

  // Save time
  m_timeOwned = m_time;

  // We're the owner now
  m_owner = true;

  return true;
}

void EiClipboard::add(Format format, const std::string &data)
{
  if (!m_open) {
    LOG_WARN("cannot add to clipboard, not open");
    return;
  }

  if (!m_owner) {
    LOG_WARN("cannot add to clipboard, no owner");
    return;
  }

  const auto formatID = static_cast<int>(format);
  m_data[formatID] = data;
  m_added[formatID] = true;
}

bool EiClipboard::open(Time time) const
{
  if (m_open) {
    LOG_DEBUG("skipping clipboard open, already open");
    return true;
  }

  m_open = true;
  m_time = time;

  return true;
}

void EiClipboard::close() const
{
  if (!m_open) {
    LOG_WARN("clipboard is not open");
  }
  m_open = false;
}

bool EiClipboard::has(Format format) const
{
  if (!m_open) {
    LOG_WARN("cannot check for clipboard format, not open");
    return false;
  }
  return m_added[static_cast<int>(format)];
}

std::string EiClipboard::get(Format format) const
{
  if (!m_open) {
    LOG_WARN("cannot get clipboard format, not open");
    return "";
  }
  return m_data[static_cast<int>(format)];
}

QByteArray PortalInputCapture::formatMimeTypes(const char *const *mimeTypes)
{
  if (!mimeTypes || !mimeTypes[0])
    return QByteArrayLiteral("(none)");

  QByteArrayList parts;
  for (int i = 0; mimeTypes[i]; i++)
    parts.append(mimeTypes[i]);

  return parts.join(", ");
}

void PortalInputCapture::claimClipboardOwnership(XdpSession *session)
{
#ifdef HAVE_LIBPORTAL_CLIPBOARD
  constexpr size_t count = std::size(kSupportedMimes);
  const char *mimeTypes[count + 1];
  for (size_t i = 0; i < count; ++i)
    mimeTypes[i] = kSupportedMimes[i].mime;
  mimeTypes[count] = nullptr;

  LOG_DEBUG("claiming clipboard: %s", formatMimeTypes(mimeTypes).constData());
  xdp_session_set_selection(session, mimeTypes);
#endif
}

void PortalInputCapture::readClipboardSelection(XdpSession *session)
{
#ifdef HAVE_LIBPORTAL_CLIPBOARD
  const qint64 kClipboardReadCap = static_cast<qint64>(m_screen->maximumClipboardSize()) * 1024;
  LOG_DEBUG("clipboard read cap: %lld bytes", static_cast<long long>(kClipboardReadCap));

  const char **mimeTypes = xdp_session_get_selection_mime_types(session);
  if (!mimeTypes) {
    LOG_DEBUG("clipboard has no mime types available to read");
    return;
  }

  if (!pickSupportedMime(mimeTypes)) {
    LOG_DEBUG(
        "clipboard no supported mime type in selection, available types: %s", formatMimeTypes(mimeTypes).constData()
    );
    return;
  }

  std::vector<std::pair<IClipboard::Format, std::string>> reads;
  std::set<IClipboard::Format> seen;
  for (const auto &entry : kSupportedMimes) {
    if (seen.count(entry.format))
      continue;
    if (!g_strv_contains(mimeTypes, entry.mime))
      continue;

    LOG_DEBUG("clipboard reading selection for mime type: %s", entry.mime);
    QByteArray bytes = readSelectionBytes(session, entry.mime, kClipboardReadCap);
    if (bytes.isEmpty()) {
      LOG_WARN("clipboard read returned no data for mime type: %s", entry.mime);
      continue;
    }

    if (entry.format != IClipboard::Format::Bitmap) {
      while (bytes.endsWith('\0'))
        bytes.chop(1);
      bytes.replace("\r\n", "\n");
    }

    std::string data = decodeFormat(entry.format, bytes);
    if (data.empty())
      continue;

    reads.emplace_back(entry.format, std::move(data));
    seen.insert(entry.format);
  }

  if (reads.empty()) {
    LOG_DEBUG("clipboard read produced no data, leaving existing clipboard intact");
    return;
  }

  m_clipboard->open(0);
  m_clipboard->empty();
  for (const auto &[format, data] : reads)
    m_clipboard->add(format, data);
  m_clipboard->close();

  m_screen->sendClipboardEvent(EventTypes::ClipboardGrabbed, kClipboardClipboard);
#else
  (void)session;
#endif
}

void PortalInputCapture::handleSelectionOwnerChanged(XdpSession *session, GStrv mimeTypes, gboolean isOwner)
{
#ifdef HAVE_LIBPORTAL_CLIPBOARD
  LOG_DEBUG(
      "selection owner changed, session owns: %s, mime types: %s", isOwner ? "yes" : "no",
      mimeTypes ? formatMimeTypes(const_cast<const char **>(mimeTypes)).constData() : "(none)"
  );

  if (isOwner) {
    LOG_DEBUG("ignoring selection owner change, session already owns the selection");
    return;
  }
  if (!mimeTypes) {
    LOG_DEBUG("ignoring selection owner change, selection cleared");
    return;
  }

  if (!pickSupportedMime(mimeTypes)) {
    LOG_DEBUG("ignoring selection owner change, no supported mime types: %s", formatMimeTypes(mimeTypes).constData());
    return;
  }

  m_screen->sendClipboardEvent(EventTypes::ClipboardGrabbed, kClipboardClipboard);

  if (!m_isActive) {
    LOG_DEBUG("deferring clipboard read until input capture activates");
    m_pendingClipboardRead = true;
    return;
  }

  readClipboardSelection(session);
#endif
}

void PortalInputCapture::handleSelectionTransfer(XdpSession *session, const char *mimeType, uint32_t serial)
{
#ifdef HAVE_LIBPORTAL_CLIPBOARD
  constexpr int kClipboardWriteTimeoutMs = 200;

  LOG_DEBUG("clipboard selection transfer requested, mime type: %s, serial: %u", mimeType, serial);

  const auto *requested = findSupportedMime(mimeType);
  if (!requested) {
    LOG_DEBUG("rejecting clipboard selection transfer, unsupported mime type: %s", mimeType);
    xdp_session_selection_write_done(session, serial, false);
    return;
  }

  int fd = xdp_session_selection_write(session, serial);
  if (fd < 0) {
    LOG_WARN("failed to write clipboard content: invalid fd");
    xdp_session_selection_write_done(session, serial, false);
    return;
  }

  m_clipboard->open(0);
  std::string raw;
  const bool hasFormat = m_clipboard->has(requested->format);
  if (hasFormat)
    raw = m_clipboard->get(requested->format);
  m_clipboard->close();

  LOG_DEBUG(
      "clipboard format requested: %d, has: %d, raw bytes: %zu", static_cast<int>(requested->format), hasFormat,
      raw.size()
  );

  QByteArray data = encodeFormat(requested->format, raw);

  LOG_DEBUG("writing clipboard content, mime type: %s, bytes: %lld", mimeType, static_cast<long long>(data.size()));

  QFile pipe;
  if (!pipe.open(fd, QIODevice::WriteOnly, QFileDevice::AutoCloseHandle)) {
    LOG_WARN("failed to wrap clipboard pipe");
    ::close(fd);
    xdp_session_selection_write_done(session, serial, false);
    return;
  }

  const char *buf = data.constData();
  qint64 total = data.size();
  qint64 written = 0;

  while (written < total) {
    pollfd pfd{fd, POLLOUT, 0};
    if (poll(&pfd, 1, kClipboardWriteTimeoutMs) <= 0) {
      LOG_ERR("timed out writing clipboard selection");
      xdp_session_selection_write_done(session, serial, false);
      return;
    }
    qint64 n = pipe.write(buf + written, total - written);
    if (n < 0) {
      LOG_ERR("failed to write clipboard selection");
      xdp_session_selection_write_done(session, serial, false);
      return;
    }
    if (n == 0) {
      LOG_ERR("clipboard pipe accepted no bytes");
      xdp_session_selection_write_done(session, serial, false);
      return;
    }
    written += n;
  }

  xdp_session_selection_write_done(session, serial, true);
  LOG_DEBUG("clipboard write complete");

#endif
}

const PortalInputCapture::SupportedMime *PortalInputCapture::findSupportedMime(const char *mime)
{
  if (!mime)
    return nullptr;

  for (const auto &entry : kSupportedMimes) {
    if (g_strcmp0(mime, entry.mime) == 0)
      return &entry;
  }

  return nullptr;
}

const PortalInputCapture::SupportedMime *PortalInputCapture::pickSupportedMime(const char *const *available)
{
  if (!available) {
    LOG_WARN("cannot pick mime type, no mime types provided");
    return nullptr;
  }

  for (const auto &entry : kSupportedMimes) {
    if (g_strv_contains(available, entry.mime))
      return &entry;
  }

  return nullptr;
}

QByteArray PortalInputCapture::dibToBmp(const std::string &dib)
{
  if (dib.size() < sizeof(quint32))
    return {};
  quint32 headerSize;
  std::memcpy(&headerSize, dib.data(), sizeof(headerSize));
  headerSize = qFromLittleEndian(headerSize);
  if (headerSize < 12 || headerSize > dib.size())
    return {};

  const quint32 fileSize = static_cast<quint32>(14 + dib.size());
  const quint32 pixelOffset = 14 + headerSize;

  QByteArray bmp;
  QDataStream ds(&bmp, QIODevice::WriteOnly);
  ds.setByteOrder(QDataStream::LittleEndian);
  ds.writeRawData("BM", 2);
  ds << fileSize;
  ds << quint32(0);
  ds << pixelOffset;
  ds.writeRawData(dib.data(), static_cast<int>(dib.size()));
  return bmp;
}

std::string PortalInputCapture::bmpToDib(const QByteArray &bmp)
{
  if (bmp.size() < 14)
    return {};
  return std::string(bmp.constData() + 14, bmp.size() - 14);
}

QByteArray PortalInputCapture::encodeFormat(IClipboard::Format format, const std::string &data)
{
  if (data.empty())
    return {};
  if (format == IClipboard::Format::Bitmap) {
    QByteArray bmpFile = dibToBmp(data);
    if (bmpFile.isEmpty()) {
      LOG_WARN("clipboard bitmap data is malformed");
      return {};
    }
    QImage image;
    if (!image.loadFromData(bmpFile, "BMP")) {
      LOG_WARN("failed to decode clipboard bitmap");
      return {};
    }
    QByteArray png;
    QBuffer buf(&png);
    buf.open(QIODevice::WriteOnly);
    if (!image.save(&buf, "PNG")) {
      LOG_WARN("failed to encode clipboard image as png");
      return {};
    }
    return png;
  }
  return QByteArray::fromStdString(data);
}

std::string PortalInputCapture::decodeFormat(IClipboard::Format format, const QByteArray &bytes)
{
  if (bytes.isEmpty())
    return {};
  if (format == IClipboard::Format::Bitmap) {
    QImage image;
    if (!image.loadFromData(bytes, "PNG")) {
      LOG_WARN("failed to decode clipboard png");
      return {};
    }
    QByteArray bmp;
    QBuffer buf(&bmp);
    buf.open(QIODevice::WriteOnly);
    if (!image.save(&buf, "BMP")) {
      LOG_WARN("failed to encode clipboard image as bmp");
      return {};
    }
    return bmpToDib(bmp);
  }
  return bytes.toStdString();
}

QByteArray PortalInputCapture::readSelectionBytes(XdpSession *session, const char *mime, qint64 maxBytes)
{
  constexpr int kClipboardReadTimeoutMs = 200;
  constexpr qint64 kInitialReserveBytes = 64 * 1024;

  int fd = xdp_session_selection_read(session, mime);
  if (fd < 0) {
    LOG_ERR("failed to read clipboard selection: invalid fd");
    return {};
  }

  QFile pipe;
  if (!pipe.open(fd, QIODevice::ReadOnly, QFileDevice::AutoCloseHandle)) {
    LOG_WARN("failed to wrap clipboard pipe");
    ::close(fd);
    return {};
  }

  QByteArray contents;
  contents.reserve(std::min(maxBytes, kInitialReserveBytes));
  while (contents.size() < maxBytes) {
    pollfd pfd{fd, POLLIN, 0};
    if (poll(&pfd, 1, kClipboardReadTimeoutMs) <= 0)
      break;
    QByteArray chunk = pipe.read(maxBytes - contents.size());
    if (chunk.isEmpty())
      break;
    contents.append(chunk);
  }

  return contents;
}

void updateReplicaSetWriteBlockCriticalSection(OperationContext* opCtx, bool allowDeletions) {
        const auto nss = NamespaceString::kReplicaSetWritesCriticalSectionsNamespace;
        AutoGetCollection autoColl(opCtx, nss, MODE_IX);
        ASSERT(autoColl) << "Collection " << nss.toStringForErrorMsg() << " doesn't exist";

        ReplicaSetWriteBlockingCriticalSectionDocument doc(
            UserWritesRecoverableCriticalSectionService::kBlockReplicaSetWritesNamespace);
        doc.setEnabled(true);
        doc.setAllowDeletions(allowDeletions);
        doc.setReplicaSetWritesBlockReason(ReplicaSetWritesBlockReasonEnum::kInsufficientDiskSpace);
        const auto updatedDoc = doc.toBSON();
        const auto criteria = updatedDoc["_id"].wrap();
        CollectionUpdateArgs updateArgs{criteria};
        updateArgs.criteria = criteria;
        updateArgs.update = BSON("$set" << BSON("allowDeletions" << allowDeletions));
        updateArgs.updatedDoc = updatedDoc;

        WriteUnitOfWork wuow(opCtx);
        ReplicaSetWriteBlockOpObserver opObserver;
        OplogUpdateEntryArgs oplogUpdateArgs(&updateArgs, *autoColl);
        opObserver.onUpdate(opCtx, oplogUpdateArgs);
        wuow.commit();
    }

TEST_F(ReplicaSetWriteBlockOpObserverTest,
       UpdatingAllowDeletionsChangesOnlyDeletionBlockingAndDoesNotReenableWrites) {
    auto opCtx = cc().makeOperationContext();
    auto* rsBlock = ReplicaSetWriteBlockState::get(opCtx.get());
    {
        Lock::GlobalLock lock(opCtx.get(), MODE_IX);
        rsBlock->disableReplicaSetWriteBlocking();
        rsBlock->disableReplicaSetDeletionsBlocking();
    }

    // An update that disallows deletions leaves writes blocking active while enabling deletion
    // blocking.
    updateReplicaSetWriteBlockCriticalSection(opCtx.get(), false /* allowDeletions */);
    {
        Lock::GlobalLock lock(opCtx.get(), MODE_IX);
        ASSERT_TRUE(rsBlock->isReplicaSetWriteBlockingEnabled());
        ASSERT_TRUE(rsBlock->isReplicaSetDeletionsBlockingEnabled());
    }

    BSONObjBuilder beforeBuilder;
    rsBlock->appendReplicaSetWritesBlockCounters(beforeBuilder);
    const auto before =
        beforeBuilder.obj()
            .getObjectField("replicaSetWritesBlockCounters")["InsufficientDiskSpace"]
            .safeNumberLong();

    // An allowDeletions-only update must leave write blocking active while allowing deletions.
    updateReplicaSetWriteBlockCriticalSection(opCtx.get(), true /* allowDeletions */);
    {
        Lock::GlobalLock lock(opCtx.get(), MODE_IX);
        ASSERT_TRUE(rsBlock->isReplicaSetWriteBlockingEnabled());
        ASSERT_FALSE(rsBlock->isReplicaSetDeletionsBlockingEnabled());
    }

    BSONObjBuilder afterBuilder;
    rsBlock->appendReplicaSetWritesBlockCounters(afterBuilder);
    const auto after = afterBuilder.obj()
                           .getObjectField("replicaSetWritesBlockCounters")["InsufficientDiskSpace"]
                           .safeNumberLong();
    ASSERT_EQ(after, before + 1);
}

TEST_F(ReplicaSetWriteBlockStateTest,
       BlockReplicaSetWritesCommandCountersDoNotIncrementWhenAlreadyEnabled) {
    auto opCtx = cc().makeOperationContext();
    Lock::GlobalLock lock(opCtx.get(), MODE_IX);

    auto* state = ReplicaSetWriteBlockState::get(opCtx.get());
    state->disableReplicaSetWriteBlocking();

    state->enableReplicaSetWriteBlocking(ReplicaSetWritesBlockReasonEnum::kInsufficientDiskSpace);
    state->enableReplicaSetWriteBlocking(ReplicaSetWritesBlockReasonEnum::kInsufficientDiskSpace);

    BSONObjBuilder bob;
    state->appendReplicaSetWritesBlockCounters(bob);
    BSONObj doc = bob.obj();
    const auto sub = doc.getObjectField("replicaSetWritesBlockCounters");
    ASSERT_EQ(sub["InsufficientDiskSpace"].safeNumberLong(), 1);
}

