ExecState getNext(BSONObj* out, RecordId* dlOut) override {
        if (_idx >= _data.size()) {
            return ExecState::IS_EOF;
        }
        invariant(out == nullptr);
        *_calledGetNextWithoutOutput = true;
        ++_idx;
        return ExecState::ADVANCED;
    }

TEST_F(DSCursorTest, EmptyDocumentsUsesCountOnlyPlanExecutorInterface) {
    std::vector<BSONObj> bsons = {BSON("foo" << 1), BSON("foo" << 2), BSON("foo" << 3)};
    auto calledGetNextWithoutOutput = std::make_shared<bool>(false);
    auto exec =
        std::make_unique<MockPlanExecutorForCount>(getOpCtx(), bsons, calledGetNextWithoutOutput);
    std::unique_ptr<PlanExecutor, PlanExecutor::Deleter> execWithDeleter(
        std::move(exec).release(), PlanExecutor::Deleter{getOpCtx()});

    MultipleCollectionAccessor collections;
    auto stasher = make_intrusive<ShardRoleTransactionResourcesStasherForPipeline>();
    auto cursor = DocumentSourceCursor::create(
        std::move(execWithDeleter), getExpCtx(), DocumentSourceCursor::CursorType::kEmptyDocuments);
    cursor->bindCatalogInfo(collections, stasher);
    cursor->setCatalogResourceHandle_forTest(
        make_intrusive<MockDSCursorCatalogResourceHandle>(std::make_shared<bool>(false)));

    auto cursorStage = exec::agg::buildStage(cursor);
    for (size_t i = 0; i < bsons.size(); ++i) {
        auto next = cursorStage->getNext();
        ASSERT(next.isAdvanced());
        ASSERT(next.getDocument().toBson().isEmpty());
    }
    ASSERT(cursorStage->getNext().isEOF());
    ASSERT(*calledGetNextWithoutOutput);
    cursorStage->dispose();
}

TEST(WriteConflictBackoff, GeometricRampFromAttemptFour) {
    ASSERT_EQ(defaultSchedule(4), 8);
    ASSERT_EQ(defaultSchedule(5), 32);
    ASSERT_EQ(defaultSchedule(6), 128);
}

TEST(WriteConflictBackoff, CapsAtCapMs) {
    ASSERT_EQ(defaultSchedule(7), 256);
    ASSERT_EQ(defaultSchedule(8), 256);
    ASSERT_EQ(defaultSchedule(1000), 256);
    ASSERT_EQ(defaultSchedule(std::numeric_limits<size_t>::max()), 256);
}

TEST(WriteConflictBackoff, HonorsCustomRampParameters) {
    // Slow ramp: 1ms start, 1s cap (growth fixed at x4).
    ASSERT_EQ(backoffBaseMillis(4, 1, 1000), 1);
    ASSERT_EQ(backoffBaseMillis(7, 1, 1000), 64);
    ASSERT_EQ(backoffBaseMillis(9, 1, 1000), 1000);
    // Cap below the fast attempts clamps them too.
    ASSERT_EQ(backoffBaseMillis(2, 8, 1), 1);
    ASSERT_EQ(backoffBaseMillis(3, 8, 1), 1);
    ASSERT_EQ(backoffBaseMillis(4, 8, 1), 1);
}

TEST_F(WriteConflictBackoffKillSwitchTest, NewPathSleepIsInterruptible) {
    KnobGuard guard;
    internalQueryWriteConflictBackoffRampStartMs.store(8);
    auto opCtx = makeOperationContext();
    opCtx->markKilled(ErrorCodes::Interrupted);
    const auto nss = NamespaceString::createNamespaceString_forTest("test.backoff");
    // Attempt 2 sleeps (1ms base), so the killed opCtx interrupts the sleep.
    ASSERT_THROWS_CODE(write_conflict_backoff::logAndBackoff(
                           opCtx.get(), 2, "test op", "", NamespaceStringOrUUID(nss)),
                       DBException,
                       ErrorCodes::Interrupted);
}

TEST_F(WriteConflictBackoffKillSwitchTest, RampStartZeroFallsBackToLegacyUninterruptibleBackoff) {
    KnobGuard guard;
    internalQueryWriteConflictBackoffRampStartMs.store(0);
    auto opCtx = makeOperationContext();
    opCtx->markKilled(ErrorCodes::Interrupted);
    const auto nss = NamespaceString::createNamespaceString_forTest("test.backoff");
    // The legacy stepped backoff (0ms below 4 attempts) ignores the killed opCtx and returns.
    write_conflict_backoff::logAndBackoff(
        opCtx.get(), 2, "test op", "", NamespaceStringOrUUID(nss));
}

TEST(HostMemoryPool, AllocateMemory) {
  auto oldAllocatorSize = HostMemoryPoolTestHelper::getDefaultAllocatorSize();
  HostMemoryPoolTestHelper::setDefaultAllocatorSize(102400);  // 100KB

  HostMemoryPool pool;

  void *ptr1 = pool.allocate(1024, 16);
  void *ptr2 = pool.allocate(1024, 16);
  void *ptr3 = pool.allocate(1024, 16);

  EXPECT_NE(ptr1, ptr2);
  EXPECT_NE(ptr1, ptr3);
  EXPECT_NE(ptr2, ptr3);

  EXPECT_EQ((std::size_t)ptr2, (std::size_t)ptr1 + 1024);
  EXPECT_EQ((std::size_t)ptr3, (std::size_t)ptr2 + 1024);

  HostMemoryPoolTestHelper::setDefaultAllocatorSize(oldAllocatorSize);
}

