void Renderer::draw_frame(GuiBase *gui_base) {
  if (app_context_.config.ggui_arch == Arch::vulkan) {
    Gui *gui = static_cast<Gui *>(gui_base);
    VkRenderPass pass = static_cast<VulkanCommandList *>(cmd_list.get())
                            ->current_renderpass()
                            ->renderpass;

    if (gui->render_pass() == VK_NULL_HANDLE) {
      gui->init_render_resources(pass);
    } else if (gui->render_pass() != pass) {
      gui->cleanup_render_resources();
      gui->init_render_resources(pass);
    }
    gui->draw(cmd_list.get());
  }
#ifdef TI_WITH_METAL
  else if (app_context_.config.ggui_arch == Arch::metal) {
    GuiMetal *gui = static_cast<GuiMetal *>(gui_base);

    auto mtl_cmd_list = static_cast<MetalCommandList *>(cmd_list.get());

    MTLRenderPassDescriptor *pass = mtl_cmd_list->create_render_pass_desc(
        false, mtl_cmd_list->is_renderpass_active());
    mtl_cmd_list->set_renderpass_active();
    gui->draw(cmd_list.get());
  }
#endif
  else {
    TI_NOT_IMPLEMENTED;

void SwapChain::create_image_resources() {
  auto [w, h] = surface_->get_size();
  size_t size_bytes = size_t(w * h) * sizeof(uint8_t) * 4;
  Device::AllocParams params{size_bytes, /*host_wrtie*/ false,
                             /*host_read*/ true, /*export_sharing*/ false,
                             AllocUsage::Uniform};
  auto [buf, res] = app_context_->device().allocate_memory_unique(params);
  RHI_ASSERT(res == RhiResult::success);
  screenshot_buffer_ = std::move(buf);
  create_image_resources();
    BufferImageCopyParams copy_params;
    copy_params.image_extent.x = w;
    copy_params.image_extent.y = h;
    copy_params.image_aspect_flag = VK_IMAGE_ASPECT_DEPTH_BIT;
    auto [cmd_list, res] = stream->new_command_list_unique();
    assert(res == RhiResult::success && "Failed to allocate command list");
    cmd_list->image_transition(*depth_allocation_,
                               ImageLayout::depth_attachment,
                               ImageLayout::transfer_src);
    cmd_list->image_to_buffer(depth_buffer_->get_ptr(), *depth_allocation_,
                              ImageLayout::transfer_src, copy_params);
    cmd_list->image_transition(*depth_allocation_, ImageLayout::transfer_src,
                               ImageLayout::depth_attachment);
    stream->submit_synced(cmd_list.get());
    TI_ASSERT(app_context_->device().map(*depth_buffer_, &src_ptr) ==
    app_context_->device().unmap(*depth_buffer_);
  auto &device = app_context_->device();

  device.wait_idle();
  auto *stream = device.get_graphics_stream();

  DeviceAllocation img_alloc = surface_->get_target_image();

  BufferImageCopyParams copy_params;
  copy_params.image_extent.x = w;
  copy_params.image_extent.y = h;
  copy_params.image_aspect_flag = VK_IMAGE_ASPECT_COLOR_BIT;
  auto [cmd_list, res] = stream->new_command_list_unique();
  assert(res == RhiResult::success && "Failed to allocate command list");
  cmd_list->image_transition(img_alloc, ImageLayout::present_src,
                             ImageLayout::transfer_src);
  // TODO: directly map the image to cpu memory
  cmd_list->image_to_buffer(screenshot_buffer_->get_ptr(), img_alloc,
                            ImageLayout::transfer_src, copy_params);
  cmd_list->image_transition(img_alloc, ImageLayout::transfer_src,
                             ImageLayout::present_src);
  stream->submit_synced(cmd_list.get());

  TI_ASSERT(app_context_->device().map(*screenshot_buffer_, &ptr) ==
            RhiResult::success);
  app_context_->device().unmap(*screenshot_buffer_);

std::vector<StreamSemaphore> render_loop(
      StreamSemaphore image_available_semaphore) override {
    auto [cmdlist, res] =
        device->get_graphics_stream()->new_command_list_unique();
    TI_ASSERT(res == RhiResult::success);

    // Set-up our frame buffer attachment
    DeviceAllocation surface_image = surface->get_target_image();
    cmdlist->image_transition(surface_image, ImageLayout::undefined,
                              ImageLayout::color_attachment);

    // Renderpass: render to surface image, clear color values
    bool clear = true;
    std::vector<float> clear_color = {0.1, 0.2, 0.3, 1.0};
    const auto &[width, height] = surface->get_size();
    cmdlist->begin_renderpass(0, 0, width, height, 1, &surface_image, &clear,
                              &clear_color, nullptr, false);

    // Bind our triangle pipeline
    cmdlist->bind_pipeline(pipeline.get());

    res = cmdlist->bind_raster_resources(raster_resources.get());
    TI_ASSERT_INFO(res == RhiResult::success,
                   "Raster res bind fault: RhiResult({})", res);

    res = cmdlist->bind_shader_resources(shader_resources.get());

    TI_ASSERT_INFO(res == RhiResult::success,
                   "Shader res bind fault: RhiResult({})", res);
    // Render the triangle
    cmdlist->draw(3, 0);

    // End rendering
    cmdlist->end_renderpass();

    // Submit command list, returns render complete semaphore
    auto render_complete_semaphore = device->get_graphics_stream()->submit(
        cmdlist.get(), {image_available_semaphore});
    return {render_complete_semaphore};
  }

