void check_cond_type(const Expr &cond, const std::string &stmt_name) {
    DataType cond_type = cond.get_rvalue_type();
    if (!cond_type->is<PrimitiveType>() || !is_integral(cond_type)) {
      ErrorEmitter(
          TaichiTypeError(), cond,
          fmt::format("`{0}` conditions must be an integer; found {1}. "
                      "Consider using "
                      "`{0} x != 0` instead of `{0} x` for float values.",
                      stmt_name, cond_type->to_string()));
    }
    if (!stmt->ret_type.ptr_removed().get_element_type()->is_primitive(
            PrimitiveTypeID::unknown)) {
      // pass
    } else if (stmt->snode) {
      stmt->ret_type =
          TypeFactory::get_instance().get_pointer_type(stmt->snode->dt);
    } else
      ErrorEmitter(TaichiTypeWarning(), stmt,
                   "Type inference failed: snode is nullptr.");
    auto check_indices = [&](SNode *snode) {
      if (snode->num_active_indices != stmt->indices.size()) {
        ErrorEmitter(
            TaichiRuntimeError(), stmt,
            fmt::format("{} has {} indices. Indexed with {}.",
                        snode->node_type_name, snode->num_active_indices,
                        stmt->indices.size()));
      }
    };
    auto is_cell_access = SNodeOpStmt::activation_related(stmt->op_type) &&
                          stmt->snode->type != SNodeType::dynamic;
    check_indices(is_cell_access ? stmt->snode : stmt->snode->parent);
    for (int i = 0; i < stmt->indices.size(); i++) {
      if (!stmt->indices[i]->ret_type->is_primitive(PrimitiveTypeID::i32)) {
        ErrorEmitter(
            TaichiCastWarning(), stmt,
            fmt::format(
                "Field index {} not int32, casting into int32 implicitly", i));
      }
    }
    auto const &lhs_type = stmt->lhs->ret_type.ptr_removed();
    auto const &rhs_type = stmt->rhs->ret_type.ptr_removed();
      ErrorEmitter(TaichiTypeError(), stmt,
                   fmt::format("cannot assign '{}' to '{}'",
                               rhs_type->to_string(), lhs_type->to_string()));
    }

std::pair<const ArgPackType *, size_t>
Program::get_argpack_type_with_data_layout(const ArgPackType *old_ty,
                                           const std::string &layout) {
  // Convert to StructType
  auto *struct_type_old =
      TypeFactory::get_instance()
          .get_struct_type(old_ty->elements(), old_ty->get_layout())
          ->as<StructType>();
  // Call get_struct_type_with_data_layout
  auto [struct_type, size] = program_impl_->get_struct_type_with_data_layout(
      const_cast<StructType *>(struct_type_old), layout);
  // Convert back to ArgPackType
  auto *new_ty =
      TypeFactory::get_instance()
          .get_argpack_type(struct_type->elements(), struct_type->get_layout())
          ->as<ArgPackType>();
  return {new_ty, size};
}

std::pair<const StructType *, size_t> Program::get_struct_type_with_data_layout(
    const StructType *old_ty,
    const std::string &layout) {
  return program_impl_->get_struct_type_with_data_layout(old_ty, layout);
}

void visit(BinaryOpStmt *stmt) override {
    auto lhs = stmt->lhs;
    auto rhs = stmt->rhs;

    if (lhs->is<ConstStmt>() && rhs->is<ConstStmt>()) {
      auto typed_constant = get_scalar_value_to_replace(
          stmt, lhs->as<ConstStmt>(), rhs->as<ConstStmt>(), stmt->ret_type);
      if (!typed_constant)
        return;

      TypedConstant new_constant = *typed_constant;
      insert_and_erase(stmt, new_constant);
    } else if (lhs->is<MatrixInitStmt>() && rhs->is<MatrixInitStmt>()) {
      int num_values = rhs->as<MatrixInitStmt>()->values.size();

      std::vector<TypedConstant> typed_constants;
      for (int i = 0; i < num_values; i++) {
        auto scalar_lhs =
            lhs->as<MatrixInitStmt>()->values[i]->cast<ConstStmt>();
        auto scalar_rhs =
            rhs->as<MatrixInitStmt>()->values[i]->cast<ConstStmt>();
        if (!scalar_lhs || !scalar_rhs)
          return;

        auto typed_constant = get_scalar_value_to_replace(
            stmt, scalar_lhs, scalar_rhs, stmt->ret_type.get_element_type());
        if (!typed_constant)
          return;

        TypedConstant new_constant = *typed_constant;
        typed_constants.push_back(new_constant);
      }
      insert_and_erase(stmt, typed_constants);
  }

  std::optional<TypedConstant> get_scalar_value_to_replace(UnaryOpStmt *stmt,
                                                           ConstStmt *operand,
                                                           DataType dst_type) {
      TypedConstant new_constant(dst_type);
      return new_constant;
      return std::nullopt;

    std::optional<TypedConstant> res = std::nullopt;
#define HANDLE_REAL_AND_INTEGRAL_UNARY(OP_TYPE, OP_CPP)                \
  case UnaryOpType::OP_TYPE: {                                         \
    if (dt->is_primitive(PrimitiveTypeID::f32) ||                      \
        dt->is_primitive(PrimitiveTypeID::f64)) {                      \
      res = TypedConstant(dst_type, OP_CPP(operand->val.val_float())); \
    } else if (dt->is_primitive(PrimitiveTypeID::i32) ||               \
               dt->is_primitive(PrimitiveTypeID::i64)) {               \
      res = TypedConstant(dst_type, OP_CPP(operand->val.val_int()));   \
    } else if (dt->is_primitive(PrimitiveTypeID::u32) ||               \
               dt->is_primitive(PrimitiveTypeID::u64)) {               \
      res = TypedConstant(dst_type, OP_CPP(operand->val.val_uint()));  \
    }                                                                  \
    break;                                                             \
#define HANDLE_INTEGRAL_UNARY(OP_TYPE, OP_CPP)                        \
  case UnaryOpType::OP_TYPE: {                                        \
    if (dt->is_primitive(PrimitiveTypeID::i32) ||                     \
        dt->is_primitive(PrimitiveTypeID::i64)) {                     \
      res = TypedConstant(dst_type, OP_CPP(operand->val.val_int()));  \
    } else if (dt->is_primitive(PrimitiveTypeID::u32) ||              \
               dt->is_primitive(PrimitiveTypeID::u64)) {              \
      res = TypedConstant(dst_type, OP_CPP(operand->val.val_uint())); \
    } else if (dt->is_primitive(PrimitiveTypeID::u1)) {               \
      res = TypedConstant(dst_type, !operand->val.val_uint1());       \
    }                                                                 \
    break;                                                            \
          res = TypedConstant(dst_type, operand->val.val_float());
          res = TypedConstant(dst_type, operand->val.val_int());
          res = TypedConstant(dst_type, operand->val.val_uint());
          res = TypedConstant(dst_type, operand->val.val_uint1());
        return std::nullopt;
    }
    return res;
  }

std::optional<TypedConstant> get_scalar_value_to_replace(UnaryOpStmt *stmt,
                                                           ConstStmt *operand,
                                                           DataType dst_type) {
      TypedConstant new_constant(dst_type);
      return new_constant;
      return std::nullopt;

    std::optional<TypedConstant> res = std::nullopt;
#define HANDLE_REAL_AND_INTEGRAL_UNARY(OP_TYPE, OP_CPP)                \
  case UnaryOpType::OP_TYPE: {                                         \
    if (dt->is_primitive(PrimitiveTypeID::f32) ||                      \
        dt->is_primitive(PrimitiveTypeID::f64)) {                      \
      res = TypedConstant(dst_type, OP_CPP(operand->val.val_float())); \
    } else if (dt->is_primitive(PrimitiveTypeID::i32) ||               \
               dt->is_primitive(PrimitiveTypeID::i64)) {               \
      res = TypedConstant(dst_type, OP_CPP(operand->val.val_int()));   \
    } else if (dt->is_primitive(PrimitiveTypeID::u32) ||               \
               dt->is_primitive(PrimitiveTypeID::u64)) {               \
      res = TypedConstant(dst_type, OP_CPP(operand->val.val_uint()));  \
    }                                                                  \
    break;                                                             \
#define HANDLE_INTEGRAL_UNARY(OP_TYPE, OP_CPP)                        \
  case UnaryOpType::OP_TYPE: {                                        \
    if (dt->is_primitive(PrimitiveTypeID::i32) ||                     \
        dt->is_primitive(PrimitiveTypeID::i64)) {                     \
      res = TypedConstant(dst_type, OP_CPP(operand->val.val_int()));  \
    } else if (dt->is_primitive(PrimitiveTypeID::u32) ||              \
               dt->is_primitive(PrimitiveTypeID::u64)) {              \
      res = TypedConstant(dst_type, OP_CPP(operand->val.val_uint())); \
    } else if (dt->is_primitive(PrimitiveTypeID::u1)) {               \
      res = TypedConstant(dst_type, !operand->val.val_uint1());       \
    }                                                                 \
    break;                                                            \
          res = TypedConstant(dst_type, operand->val.val_float());
          res = TypedConstant(dst_type, operand->val.val_int());
          res = TypedConstant(dst_type, operand->val.val_uint());
          res = TypedConstant(dst_type, operand->val.val_uint1());
        return std::nullopt;
    }

void insert_and_erase(Stmt *stmt,
                        const std::vector<TypedConstant> &new_constants) {
    std::vector<Stmt *> values;
    for (auto &new_constant : new_constants) {
      auto const_stmt = Stmt::make<ConstStmt>(new_constant);
      values.push_back(const_stmt.get());
      modifier.insert_before(stmt, std::move(const_stmt));
    }

    auto evaluated = Stmt::make<MatrixInitStmt>(values);
    evaluated->ret_type = stmt->ret_type;

    stmt->replace_usages_with(evaluated.get());
    modifier.insert_before(stmt, std::move(evaluated));
    modifier.erase(stmt);
  }

std::vector<float64> get_exponent_values(BinaryOpStmt *stmt) {
    std::vector<float64> rets;
    if (stmt->rhs->is<ConstStmt>()) {
      rets.push_back(stmt->rhs->as<ConstStmt>()->val.val_cast_to_float64());
      return rets;
    } else if (stmt->rhs->is<MatrixInitStmt>()) {
      auto matrix_init = stmt->rhs->as<MatrixInitStmt>();
      for (auto &value : matrix_init->values) {
        if (value->is<ConstStmt>()) {
          rets.push_back(value->as<ConstStmt>()->val.val_cast_to_float64());
        } else {
          return {};
        }
      }
      return rets;
    }
    return {};
  }

Stmt *get_inverse(BinaryOpStmt *stmt) {
    auto rhs = stmt->rhs;
    if (rhs->is<ConstStmt>()) {
      auto reciprocal =
          Stmt::make_typed<ConstStmt>(TypedConstant(rhs->ret_type));
      if (rhs->ret_type->is_primitive(PrimitiveTypeID::f64)) {
        reciprocal->val.val_float64() =
            (float64)1.0 / rhs->as<ConstStmt>()->val.val_float64();
      } else if (rhs->ret_type->is_primitive(PrimitiveTypeID::f32)) {
        reciprocal->val.val_float32() =
            (float32)1.0 / rhs->as<ConstStmt>()->val.val_float32();
      } else {
        TI_NOT_IMPLEMENTED
      }
      Stmt *reciprocal_ptr = reciprocal.get();
      modifier.insert_before(stmt, std::move(reciprocal));
      return reciprocal_ptr;
    } else {
      auto matrix_rhs = rhs->cast<MatrixInitStmt>();
      TI_ASSERT(matrix_rhs != nullptr);
      std::vector<Stmt *> values;
      for (auto scalar_stmt : matrix_rhs->values) {
        auto const_stmt = scalar_stmt->cast<ConstStmt>();
        TI_ASSERT(const_stmt != nullptr);
        auto reciprocal =
            Stmt::make_typed<ConstStmt>(TypedConstant(scalar_stmt->ret_type));
        if (scalar_stmt->ret_type->is_primitive(PrimitiveTypeID::f64)) {
          reciprocal->val.val_float64() =
              (float64)1.0 / const_stmt->val.val_float64();
        } else if (scalar_stmt->ret_type->is_primitive(PrimitiveTypeID::f32)) {
          reciprocal->val.val_float32() =
              (float32)1.0 / const_stmt->val.val_float32();
        } else {
          TI_NOT_IMPLEMENTED
        }
        values.push_back(reciprocal.get());
        modifier.insert_before(stmt, std::move(reciprocal));
      }
      auto new_rhs = Stmt::make<MatrixInitStmt>(values);
      new_rhs->ret_type = rhs->ret_type;

      Stmt *new_rhs_ptr = new_rhs.get();
      modifier.insert_before(stmt, std::move(new_rhs));
      return new_rhs_ptr;
    }
  }

Stmt *get_log2rhs(BinaryOpStmt *stmt) {
    auto rhs = stmt->rhs;
    if (auto const_rhs = stmt->rhs->cast<ConstStmt>()) {
      int log2rhs =
          bit::log2int((uint64)rhs->as<ConstStmt>()->val.val_as_int64());
      auto new_rhs =
          Stmt::make<ConstStmt>(TypedConstant(stmt->lhs->ret_type, log2rhs));
      Stmt *new_rhs_ptr = new_rhs.get();
      modifier.insert_before(stmt, std::move(new_rhs));
      return new_rhs_ptr;
    } else {
      auto matrix_rhs = rhs->cast<MatrixInitStmt>();
      TI_ASSERT(matrix_rhs != nullptr);

      std::vector<Stmt *> values;
      for (auto scalar_stmt : matrix_rhs->values) {
        auto const_stmt = scalar_stmt->cast<ConstStmt>();
        TI_ASSERT(const_stmt != nullptr);
        int log2int = bit::log2int((uint64)const_stmt->val.val_as_int64());
        auto log2int_stmt = Stmt::make<ConstStmt>(
            TypedConstant(scalar_stmt->ret_type, log2int));

        values.push_back(log2int_stmt.get());
        modifier.insert_before(stmt, std::move(log2int_stmt));
      }

      auto new_rhs = Stmt::make<MatrixInitStmt>(values);
      new_rhs->ret_type = rhs->ret_type;

      Stmt *new_rhs_ptr = new_rhs.get();
      modifier.insert_before(stmt, std::move(new_rhs));
      return new_rhs_ptr;
    }
  }

bool exponent_one_optimize(BinaryOpStmt *stmt) {
    auto exponents = get_exponent_values(stmt);
    if (exponents.empty()) {
      return false;
    }

    for (auto exponent : exponents) {
      if (exponent != 1) {
        return false;
      }
    }

    stmt->replace_usages_with(stmt->lhs);
    modifier.erase(stmt);
    return true;
  }

bool exponent_zero_optimize(BinaryOpStmt *stmt) {
    auto exponents = get_exponent_values(stmt);
    if (exponents.empty()) {
      return false;
    }

    for (auto exponent : exponents) {
      if (exponent != 0) {
        return false;
      }
    }

    replace_with_one(stmt);
    return true;
  }

bool exponent_half_optimize(BinaryOpStmt *stmt) {
    auto exponents = get_exponent_values(stmt);
    if (exponents.empty()) {
      return false;
    }

    for (auto exponent : exponents) {
      if (exponent != 0.5) {
        return false;
      }
    }
    auto a = stmt->lhs;
    cast_to_result_type(a, stmt);
    auto result = Stmt::make<UnaryOpStmt>(UnaryOpType::sqrt, a);
    result->ret_type = a->ret_type;
    stmt->replace_usages_with(result.get());
    modifier.insert_before(stmt, std::move(result));
    modifier.erase(stmt);
    return true;
  }

bool exponent_n_optimize(BinaryOpStmt *stmt) {
    auto exponents = get_exponent_values(stmt);
    if (exponents.empty()) {
      return false;
    }

    // Equal exponents
    for (auto exponent : exponents) {
      if (exponent != exponents[0]) {
        return false;
      }
    }

    float64 exponent = exponents[0];
    if (!(exponent == std::round(exponent) && exponent > 0 &&
          exponent <= max_weaken_exponent)) {
      return false;
    }

    // a ** n -> Exponentiation by squaring
    auto a = stmt->lhs;
    cast_to_result_type(a, stmt);
    const int exp = exponent;
    Stmt *result = nullptr;
    auto a_power_of_2 = a;
    int current_exponent = 1;
    while (true) {
      if (exp & current_exponent) {
        if (!result)
          result = a_power_of_2;
        else {
          auto new_result =
              Stmt::make<BinaryOpStmt>(BinaryOpType::mul, result, a_power_of_2);
          new_result->ret_type = a->ret_type;
          result = new_result.get();
          modifier.insert_before(stmt, std::move(new_result));
        }
      }
      current_exponent <<= 1;
      if (current_exponent > exp)
        break;
      auto new_a_power = Stmt::make<BinaryOpStmt>(BinaryOpType::mul,
                                                  a_power_of_2, a_power_of_2);
      new_a_power->ret_type = a->ret_type;
      a_power_of_2 = new_a_power.get();
      modifier.insert_before(stmt, std::move(new_a_power));
    }
    stmt->replace_usages_with(result);
    modifier.erase(stmt);
    return true;
  }

bool exponent_negative_optimize(BinaryOpStmt *stmt) {
    auto exponents = get_exponent_values(stmt);
    if (exponents.empty()) {
      return false;
    }

    // All negative exponent
    for (auto exponent : exponents) {
      if (!(exponent == std::round(exponent) && exponent < 0 &&
            exponent >= -max_weaken_exponent)) {
        return false;
      }
    }

    if (is_integral(stmt->lhs->ret_type.get_element_type())) {
      TI_ERROR("Negative exponent in pow(int, int) is not allowed.");
    }

    auto stmts = get_const_stmt_with_value(stmt->ret_type, 1);
    auto one = stmts.back().get();

    for (auto &s : stmts) {
      modifier.insert_before(stmt, std::move(s));
    }

    cast_to_result_type(one, stmt);
    auto new_exponent = Stmt::make<UnaryOpStmt>(UnaryOpType::neg, stmt->rhs);
    auto a_to_n = Stmt::make<BinaryOpStmt>(BinaryOpType::pow, stmt->lhs,
                                           new_exponent.get());
    a_to_n->ret_type = stmt->ret_type;
    auto result =
        Stmt::make<BinaryOpStmt>(BinaryOpType::div, one, a_to_n.get());
    stmt->replace_usages_with(result.get());
    modifier.insert_before(stmt, std::move(new_exponent));
    modifier.insert_before(stmt, std::move(a_to_n));
    modifier.insert_before(stmt, std::move(result));
    modifier.erase(stmt);
    return true;
  }

static bool alg_is_minus_one(Stmt *stmt) {
    if (auto const_stmt = stmt->cast<ConstStmt>()) {
      return const_stmt->val.equal_value(-1);
    } else if (auto matrix_stmt = stmt->cast<MatrixInitStmt>()) {
      for (auto &val : matrix_stmt->values) {
        if (!alg_is_minus_one(val)) {
          return false;
        }
      }
      return true;
    }
    return false;
  }

void lines(FieldInfo vbo,
             FieldInfo indices,
             bool has_per_vertex_color,
             py::tuple color_,
             float width,
             float draw_index_count,
             float draw_first_index,
             float draw_vertex_count,
             float draw_first_vertex) {
    RenderableInfo renderable_info;
    renderable_info.vbo = vbo;
    renderable_info.indices = indices;
    renderable_info.has_per_vertex_color = has_per_vertex_color;
    renderable_info.has_user_customized_draw = true;
    renderable_info.draw_index_count = (int)draw_index_count;
    renderable_info.draw_first_index = (int)draw_first_index;
    renderable_info.draw_vertex_count = (int)draw_vertex_count;
    renderable_info.draw_first_vertex = (int)draw_first_vertex;

    SceneLinesInfo info;
    info.renderable_info = renderable_info;
    info.color = tuple_to_vec3(color_);
    info.width = width;

    return scene->lines(info);
  }

