void mesh_instance(FieldInfo vbo,
                     bool has_per_vertex_color,
                     FieldInfo indices,
                     py::tuple color,
                     bool two_sided,
                     FieldInfo transforms,
                     float draw_instance_count,
                     float draw_first_instance,
                     float draw_index_count,
                     float draw_first_index,
                     float draw_vertex_count,
                     float draw_first_vertex,
                     bool show_wireframe) {
    RenderableInfo renderable_info;
    renderable_info.vbo = vbo;
    renderable_info.has_per_vertex_color = has_per_vertex_color;
    renderable_info.indices = indices;
    renderable_info.has_user_customized_draw = true;
    renderable_info.draw_index_count = (int)draw_index_count;
    renderable_info.draw_first_index = (int)draw_first_index;
    renderable_info.draw_vertex_count = (int)draw_vertex_count;
    renderable_info.draw_first_vertex = (int)draw_first_vertex;
    renderable_info.display_mode = show_wireframe
                                       ? taichi::lang::PolygonMode::Line
                                       : taichi::lang::PolygonMode::Fill;

    MeshInfo info;
    info.renderable_info = renderable_info;
    info.color = tuple_to_vec3(color);
    info.two_sided = two_sided;
    if (transforms.valid) {
      info.start_instance = (int)draw_first_instance;
      info.num_instances =
          (draw_instance_count + info.start_instance) > transforms.shape[0]
              ? (transforms.shape[0] - info.start_instance)
              : (int)draw_instance_count;
    }
    info.mesh_attribute_info.mesh_attribute = transforms;
    info.mesh_attribute_info.has_attribute = transforms.valid;

    scene->mesh(info);
  }

void point_light(py::tuple pos_, py::tuple color_) {
    glm::vec3 pos = tuple_to_vec3(pos_);
    glm::vec3 color = tuple_to_vec3(color_);
    scene->point_light(pos, color);
  }

void Renderer::scene_v2(SceneBase *scene) {
  if (scene->point_lights_.size() == 0) {
    TI_WARN("warning, there are no light sources in the scene.\n");
  }
  float aspect_ratio = swap_chain_.width() / (float)swap_chain_.height();
  scene->update_ubo(aspect_ratio);
  update_scene_data(scene);

  for (auto renderable_ : render_queue_) {
    if (renderable_->is_3d_renderable) {
      renderable_->update_scene_data(lights_ssbo_->get_ptr(0),
                                     scene_ubo_->get_ptr(0));
    }
  }

  scene->point_lights_.clear();
}

bool is_aos_matrix_of_global_ptr(MatrixOfGlobalPtrStmt *stmt) {
  auto ret_type = stmt->ret_type;
  auto indices = stmt->indices;
  auto snodes = stmt->snodes;

  bool is_continuous_addr = true;
  SNode *parent_snode = snodes[0]->parent;
  for (auto snode : snodes) {
    TI_ASSERT(snode->type == SNodeType::place);
    if (snode->parent != parent_snode ||
        parent_snode->type != SNodeType::dense) {
      is_continuous_addr = false;
      break;
    }
  }

  return is_continuous_addr;
}

explicit GatherValidAOSGlobalPtrStmt(IRNode *node) {
    node->accept(this);

    modifier_.modify_ir();
  }

void visit(MatrixPtrStmt *stmt) override {
    if (stmt->origin->is<MatrixOfGlobalPtrStmt>()) {
      auto origin = stmt->origin->as<MatrixOfGlobalPtrStmt>();

      if (is_quant(origin->snodes[0]->dt)) {
        invalid_aos_global_ptr_stmts_.insert(stmt->origin);
      }

      if (origin->snodes[0]->dt->is<PointerType>() &&
          origin->snodes[0]->dt->as<PointerType>()->is_bit_pointer()) {
        invalid_aos_global_ptr_stmts_.insert(stmt->origin);
      }

      if (!stmt->offset->is<ConstStmt>()) {
        invalid_aos_global_ptr_stmts_.insert(stmt->origin);
      }
    }
  }

explicit LowerAOSGlobalPtrStmt(
      IRNode *node,
      std::unordered_set<Stmt *> &invalid_aos_global_ptr_stmts)
      : immediate_modifier_(node),
        invalid_aos_global_ptr_stmts_(invalid_aos_global_ptr_stmts) {
    node->accept(this);

    delayed_modifier_.modify_ir();
  }

void visit(MatrixOfGlobalPtrStmt *stmt) override {
    bool is_aos = is_aos_matrix_of_global_ptr(stmt);
    auto ret_type = stmt->ret_type;
    auto indices = stmt->indices;
    auto snodes = stmt->snodes;

    if (is_aos && invalid_aos_global_ptr_stmts_.find(stmt) ==
                      invalid_aos_global_ptr_stmts_.end()) {
      auto new_stmt = std::make_unique<GlobalPtrStmt>(snodes[0], indices);
      new_stmt->ret_type = ret_type;
      new_stmt->ret_type.set_is_pointer(true);

      stmt->replace_usages_with(new_stmt.get());
      delayed_modifier_.insert_before(stmt, std::move(new_stmt));
      delayed_modifier_.erase(stmt);
    }
  }

if (stmt->origin->is<GetChStmt>() &&
        stmt->origin->ret_type.ptr_removed()->is<TensorType>()) {
      auto origin = stmt->origin->as<GetChStmt>();

      if (!stmt->offset->is<ConstStmt>()) {
        return;
      }

      int offset = stmt->offset->as<ConstStmt>()->val.val_int32();

      auto input_ptr = origin->input_ptr;
      auto input_snode = origin->input_snode;
      bool is_bit_vectorized = origin->is_bit_vectorized;

      auto new_get_ch_stmt = std::make_unique<GetChStmt>(
          input_ptr, input_snode, origin->chid + offset, is_bit_vectorized);
      new_get_ch_stmt->ret_type = stmt->ret_type;

      stmt->replace_usages_with(new_get_ch_stmt.get());
      modifier_.insert_before(stmt, std::move(new_get_ch_stmt));
      modifier_.erase(stmt);
      return;
    }

TiRuntime ti_import_opengl_runtime(TiOpenglRuntimeInteropInfo *interop_info,
                                   bool use_gles) {
  TI_CAPI_TRY_CATCH_BEGIN();
  TI_CAPI_ARGUMENT_NULL_RV(interop_info);
  taichi::lang::opengl::imported_process_address = interop_info->get_proc_addr;
  taichi::lang::opengl::set_gles_override(use_gles);
  TI_CAPI_TRY_CATCH_END();
  return ti_create_runtime(TI_ARCH_OPENGL, 0);
}

bool is_matrix_ptr_indices_loop_unique(MatrixPtrStmt *stmt) const {
    bool ret = true;
    if (stmt->origin->is<GlobalPtrStmt>()) {
      ret &= is_ptr_indices_loop_unique(stmt->origin->as<GlobalPtrStmt>());
    } else if (stmt->origin->is<ExternalPtrStmt>()) {
      ret &= is_ptr_indices_loop_unique(stmt->origin->as<ExternalPtrStmt>());
    } else {
      return true;
    }

    if (loop_unique_.find(stmt->offset) != loop_unique_.end()) {
      ret &= (loop_unique_.find(stmt->offset)->second == -1);
    } else {
      return false;
    }

    return ret;
  }

void visit(MatrixPtrStmt *stmt) override {
    bool accessed = true;
    if (stmt->origin->is<GlobalPtrStmt>()) {
      auto snode = stmt->origin->as<GlobalPtrStmt>()->snode;
      accessed &= (accessed_pointer_.find(snode) != accessed_pointer_.end());
    } else if (stmt->origin->is<ExternalPtrStmt>()) {
      auto arg_id = stmt->origin->as<ExternalPtrStmt>()
                        ->base_ptr->as<ArgLoadStmt>()
                        ->arg_id;
      accessed &=
          (accessed_arr_pointer_.find(arg_id) != accessed_arr_pointer_.end());
    } else {
      return;
    }

    accessed &=
        loop_unique_stmt_searcher_.is_matrix_ptr_indices_loop_unique(stmt);

    if (accessed) {
      accessed_matrix_pointer_.insert(stmt);
    }
  }

