void Renderer::resize_lights_ssbo(int new_ssbo_size) {
  if (lights_ssbo_ != nullptr && new_ssbo_size == lights_ssbo_size) {
    return;
  }
  lights_ssbo_.reset();
  lights_ssbo_size = new_ssbo_size;
  if (lights_ssbo_size) {
    auto [buf, res] = app_context_.device().allocate_memory_unique(
        {lights_ssbo_size, /*host_write=*/true, /*host_read=*/false,
         /*export_sharing=*/false, AllocUsage::Storage});
    TI_ASSERT(res == RhiResult::success);
    lights_ssbo_ = std::move(buf);
  }
}

void Renderer::init_scene_ubo() {
  scene_ubo_.reset();
  auto [buf, res] = app_context_.device().allocate_memory_unique(
      {sizeof(SceneBase::UBOScene), /*host_write=*/true, /*host_read=*/false,
       /*export_sharing=*/false, AllocUsage::Uniform});
  TI_ASSERT(res == RhiResult::success);
  scene_ubo_ = std::move(buf);
}

void Renderer::update_scene_data(SceneBase *scene) {
  // Update SSBO
  {
    size_t new_ssbo_size = scene->point_lights_.size() * sizeof(PointLight);
    resize_lights_ssbo(new_ssbo_size);

    void *mapped{nullptr};
    RHI_VERIFY(app_context_.device().map(lights_ssbo_->get_ptr(), &mapped));
    memcpy(mapped, scene->point_lights_.data(), new_ssbo_size);
    app_context_.device().unmap(*lights_ssbo_);
  }

  // Update UBO
  {
    init_scene_ubo();

    SceneBase::UBOScene ubo;
    ubo.scene = scene->current_scene_data_;
    ubo.window_width = app_context_.config.width;
    ubo.window_height = app_context_.config.height;
    ubo.tan_half_fov = tanf(glm::radians(scene->camera_.fov) / 2);
    ubo.aspect_ratio =
        float(app_context_.config.width) / float(app_context_.config.height);

    void *mapped{nullptr};
    RHI_VERIFY(app_context_.device().map(scene_ubo_->get_ptr(0), &mapped));
    memcpy(mapped, &ubo, sizeof(ubo));
    app_context_.device().unmap(*scene_ubo_);
  }
}

static std::unordered_set<Stmt *> run(Function *func,
                                        TarjanData &tarjan_data) {
    TI_ASSERT(tarjan_data.func_dfn.count(func) == 0);
    tarjan_data.func_dfn[func] = tarjan_data.func_low[func] =
        tarjan_data.func_dfn.size();
    tarjan_data.func_in_stack.insert(func);
    tarjan_data.func_stack.push(func);
    GatherFuncStoreDests searcher(func, tarjan_data);
    func->ir->accept(&searcher);
    if (tarjan_data.func_low[func] == tarjan_data.func_dfn[func]) {
      while (true) {
        auto top = tarjan_data.func_stack.top();
        tarjan_data.func_stack.pop();
        tarjan_data.func_in_stack.erase(top);
        top->store_dests.insert(searcher.results_.begin(),
                                searcher.results_.end());
        if (top == func) {
          break;
        }
      }
    }
    return searcher.results_;
  }

GatherFuncStoreDests(Function *func, TarjanData &tarjan_data)
      : current_func_(func), tarjan_data_(tarjan_data) {
    allow_undefined_visitor = true;
    invoke_default_visitor = true;
  }

void visit(Stmt *stmt) override {
    if (!current_func_) {
      return;
    }
    auto result = irpass::analysis::get_store_destination(stmt);
    results_.insert(result.begin(), result.end());
  }

void visit(FuncCallStmt *stmt) override {
    auto func = stmt->func;
    if (!current_func_) {
      if (!tarjan_data_.func_dfn.count(func)) {
        run(func, tarjan_data_);
      }
      return;
    }
    if (!tarjan_data_.func_dfn.count(func)) {
      auto result = run(func, tarjan_data_);
      results_.merge(result);
      tarjan_data_.func_low[current_func_] = std::min(
          tarjan_data_.func_low[current_func_], tarjan_data_.func_low[func]);
    } else if (tarjan_data_.func_in_stack.count(func)) {
      tarjan_data_.func_low[current_func_] = std::min(
          tarjan_data_.func_low[current_func_], tarjan_data_.func_dfn[func]);
    } else {
      const auto &dests = func->store_dests;
      results_.insert(dests.begin(), dests.end());
    }
  }

stmt_refs FuncCallStmt::get_store_destination() const {
  std::vector<Stmt *> ret;
  for (auto &arg : args) {
    if (auto ref = arg->cast<ReferenceStmt>()) {
      ret.push_back(ref->var);
    } else if (arg->ret_type.is_pointer()) {
      ret.push_back(arg);
    }
  }
  ret.insert(ret.end(), func->store_dests.begin(), func->store_dests.end());
  return ret;
}

std::function<void(const std::string &)>
make_pass_printer(bool verbose, const std::string &kernel_name, IRNode *ir) {
  if (!verbose) {
    return [](const std::string &) {};
  }
  return [ir, kernel_name](const std::string &pass) {
    TI_INFO("[{}] {}:", kernel_name, pass);
    std::cout << std::flush;
    irpass::re_id(ir);
    irpass::print(ir);
    std::cout << std::flush;
  };
}

