std::unique_ptr<Stmt> clone(Stmt *root) {
  auto ret = IRCloner::run(root);
  Stmt *stmt_ptr = dynamic_cast<Stmt *>(ret.release());
  TI_ASSERT(stmt_ptr != nullptr);

  return std::unique_ptr<Stmt>(stmt_ptr);
}

Stmt *transform_pow_op_impl(IRBuilder &builder, Stmt *lhs, Stmt *rhs) {
    auto lhs_type = lhs->ret_type.get_element_type();
    auto rhs_type = rhs->ret_type.get_element_type();

    auto one_lhs = builder.get_constant(lhs_type, 1);
    auto one_rhs = builder.get_constant(rhs_type, 1);
    auto zero_rhs = builder.get_constant(rhs_type, 0);
    auto a = builder.create_local_var(lhs_type);
    builder.create_local_store(a, lhs);
    auto b = builder.create_local_var(rhs_type);
    builder.create_local_store(b, builder.create_abs(rhs));
    auto result = builder.create_local_var(lhs_type);
    builder.create_local_store(result, one_lhs);
    auto loop = builder.create_while_true();
    {
      auto loop_guard = builder.get_loop_guard(loop);
      auto current_a = builder.create_local_load(a);
      auto current_b = builder.create_local_load(b);
      auto if_stmt =
          builder.create_if(builder.create_cmp_le(current_b, zero_rhs));
      {
        auto _ = builder.get_if_guard(if_stmt, true);
        builder.create_break();
      }
      auto bit_and = builder.create_and(current_b, one_rhs);
      if_stmt = builder.create_if(builder.create_cmp_ne(bit_and, zero_rhs));
      {
        auto _ = builder.get_if_guard(if_stmt, true);
        auto current_result = builder.create_local_load(result);
        auto new_result = builder.create_mul(current_result, current_a);
        builder.create_local_store(result, new_result);
      }
      auto new_a = builder.create_mul(current_a, current_a);
      builder.create_local_store(a, new_a);
      auto new_b = builder.create_sar(current_b, one_rhs);
      builder.create_local_store(b, new_b);
    }
    if (is_real(lhs_type)) {
      auto if_stmt = builder.create_if(builder.create_cmp_le(rhs, zero_rhs));
      {
        auto _ = builder.get_if_guard(if_stmt, true);
        auto current_result = builder.create_local_load(result);
        auto new_result = builder.create_div(one_lhs, current_result);
        builder.create_local_store(result, new_result);
      }
    }
    auto final_result = builder.create_local_load(result);
    return final_result;
  }

void transform_pow_op_scalar(BinaryOpStmt *stmt, Stmt *lhs, Stmt *rhs) {
    IRBuilder builder;

    auto final_result = transform_pow_op_impl(builder, lhs, rhs);

    stmt->replace_usages_with(final_result);
    modifier.insert_before(
        stmt, VecStatement(std::move(builder.extract_ir()->statements)));
    modifier.erase(stmt);
  }

void transform_pow_op_tensor(BinaryOpStmt *stmt, Stmt *lhs, Stmt *rhs) {
    std::vector<Stmt *> ret_stmts;
    auto lhs_tensor_ty = lhs->ret_type->cast<TensorType>();
    auto rhs_tensor_ty = rhs->ret_type->cast<TensorType>();

    auto lhs_prim_type = lhs_tensor_ty->get_element_type();
    auto rhs_prim_type = rhs_tensor_ty->get_element_type();

    auto lhs_alloca = Stmt::make<AllocaStmt>(lhs_tensor_ty);
    auto rhs_alloca = Stmt::make<AllocaStmt>(rhs_tensor_ty);
    auto lhs_store = Stmt::make<LocalStoreStmt>(lhs_alloca.get(), stmt->lhs);
    auto rhs_store = Stmt::make<LocalStoreStmt>(rhs_alloca.get(), stmt->rhs);
    auto lhs_ptr = lhs_alloca.get();
    auto rhs_ptr = rhs_alloca.get();
    modifier.insert_before(stmt, std::move(lhs_alloca));
    modifier.insert_before(stmt, std::move(rhs_alloca));
    modifier.insert_before(stmt, std::move(lhs_store));
    modifier.insert_before(stmt, std::move(rhs_store));
    for (int i = 0; i < lhs_tensor_ty->get_num_elements(); i++) {
      auto idx = Stmt::make<ConstStmt>(TypedConstant(i));
      auto lhs_i = Stmt::make<MatrixPtrStmt>(lhs_ptr, idx.get());
      auto rhs_i = Stmt::make<MatrixPtrStmt>(rhs_ptr, idx.get());
      auto lhs_load = Stmt::make<LocalLoadStmt>(lhs_i.get());
      lhs_load->ret_type = lhs_prim_type;

      auto rhs_load = Stmt::make<LocalLoadStmt>(rhs_i.get());
      rhs_load->ret_type = rhs_prim_type;

      auto cur_lhs = lhs_load.get();
      auto cur_rhs = rhs_load.get();
      modifier.insert_before(stmt, std::move(idx));
      modifier.insert_before(stmt, std::move(lhs_i));
      modifier.insert_before(stmt, std::move(rhs_i));
      modifier.insert_before(stmt, std::move(lhs_load));
      modifier.insert_before(stmt, std::move(rhs_load));

      IRBuilder builder;
      auto cur_result = transform_pow_op_impl(builder, cur_lhs, cur_rhs);

      modifier.insert_before(
          stmt, VecStatement(std::move(builder.extract_ir()->statements)));
      ret_stmts.push_back(cur_result);
    }
    auto new_matrix = Stmt::make<MatrixInitStmt>(ret_stmts);
    new_matrix->ret_type = stmt->ret_type;
    stmt->replace_usages_with(new_matrix.get());
    modifier.insert_before(stmt, std::move(new_matrix));
    modifier.erase(stmt);
  }

static bool run(IRNode *node) {
    Scalarize pass(node);
    node->accept(&pass);
    return pass.delayed_modifier_.modify_ir();
  }

static bool run(IRNode *node,
                  const std::unordered_set<Stmt *> &scalarizable_allocas) {
    ScalarizePointers pass(node, scalarizable_allocas);
    node->accept(&pass);
    return pass.delayed_modifier_.modify_ir();
  }

static bool run(IRNode *node) {
    ExtractLocalPointers pass(node);
    node->accept(&pass);
    return pass.delayed_modifier_.modify_ir();
  }

stmt_refs include_aliased_stmts(stmt_refs dest) {
      auto aliased_stmts = include_aliased_stmts(load_src);
      return aliased_stmts;
      auto aliased_stmts = include_aliased_stmts(store_dest);
      return aliased_stmts;

bool CFGNode::contain_variable(
    const std::unordered_map<Stmt *, CFGNode::UseDefineStatus> &var_set,
    Stmt *var) {
  if (var->is<AllocaStmt>() || var->is<AdStackAllocaStmt>()) {
    if (var_set.find(var) != var_set.end()) {
      return var_set.at(var) != CFGNode::UseDefineStatus::PARTIAL;
    }
    return false;
  } else {
    // TODO: How to optimize this?
    if (var_set.find(var) != var_set.end()) {
      return var_set.at(var) != CFGNode::UseDefineStatus::PARTIAL;
    }
    return std::any_of(
        var_set.begin(), var_set.end(), [&](const auto &set_var) {
          if (irpass::analysis::definitely_same_address(var, set_var.first)) {
            return set_var.second != CFGNode::UseDefineStatus::PARTIAL;
          }
          return false;
        });
  }
}

bool CFGNode::may_contain_variable(
    const std::unordered_map<Stmt *, CFGNode::UseDefineStatus> &var_set,
    Stmt *var) {
  if (var->is<AllocaStmt>() || var->is<AdStackAllocaStmt>()) {
    return var_set.find(var) != var_set.end();
  } else {
    // TODO: How to optimize this?
    if (var_set.find(var) != var_set.end())
      return true;
    return std::any_of(
        var_set.begin(), var_set.end(), [&](const auto &set_var) {
          return irpass::analysis::maybe_same_address(var, set_var.first);
        });
  }
}

static void update_aliased_stmts(
    const std::unordered_map<Stmt *, std::vector<Stmt *>>
        &tensor_to_matrix_ptrs_map,
    const std::unordered_map<Stmt *, Stmt *> &matrix_ptr_to_tensor_map,
    std::unordered_map<Stmt *, CFGNode::UseDefineStatus> &container,
    Stmt *key,
    bool to_erase) {
  if (tensor_to_matrix_ptrs_map.find(key) != tensor_to_matrix_ptrs_map.end()) {
    auto scalars_address = tensor_to_matrix_ptrs_map.at(key);
    // Update aliased MatrixPtrStmt for TensorType<>*
    for (auto scalar_address : scalars_address) {
      if (to_erase) {
        if (container.find(scalar_address) != container.end()) {
          TI_ASSERT(container[scalar_address] ==
                    CFGNode::UseDefineStatus::NONE);
          container.erase(scalar_address);
        }
      } else {
        container[scalar_address] = CFGNode::UseDefineStatus::NONE;
      }
    }
  }

  // Update aliased TensorType<>* for MatrixPtrStmt
  if (matrix_ptr_to_tensor_map.find(key) != matrix_ptr_to_tensor_map.end()) {
    auto tensor_address = matrix_ptr_to_tensor_map.at(key);
    // no matter to_erase or not, the tensor_address is only partially defined
    // or used
    if (to_erase) {
      if (container.find(tensor_address) != container.end()) {
        container[tensor_address] = CFGNode::UseDefineStatus::PARTIAL;
      }
    } else {
      container[tensor_address] = CFGNode::UseDefineStatus::PARTIAL;
    }
  }
}

static void update_container_with_alias(
    const std::unordered_map<Stmt *, std::vector<Stmt *>>
        &tensor_to_matrix_ptrs_map,
    const std::unordered_map<Stmt *, Stmt *> &matrix_ptr_to_tensor_map,
    std::unordered_map<Stmt *, CFGNode::UseDefineStatus> &container,
    Stmt *key,
    bool to_erase) {
  if (to_erase) {
    container.erase(key);
  } else if (key->ret_type.ptr_removed()->is<TensorType>()) {
    container[key] = CFGNode::UseDefineStatus::FULL;
  } else {
    container[key] = CFGNode::UseDefineStatus::NONE;
  }
  update_aliased_stmts(tensor_to_matrix_ptrs_map, matrix_ptr_to_tensor_map,
                       container, key, to_erase);
}

else if (auto stmt = statements[i]->cast<BitStructStoreStmt>()) {
        // Phase 2: Find bit store after a marked load
        if (loaded_after_store.find(stmt->ptr) != loaded_after_store.end()) {
          // Disable store fusion for this bit struct
          ptr_to_bit_struct_stores.erase(stmt->ptr);
          loaded_after_store.erase(stmt->ptr);
        } else {
          ptr_to_bit_struct_stores[stmt->ptr].push_back(stmt);
        }
      }

bool MatrixPtrStmt::common_statement_eliminable() const {
  Kernel *k = get_kernel();
  TI_ASSERT(k != nullptr);
  return (k->autodiff_mode == AutodiffMode::kNone);
}

void runtime_get_memory_requirements(Ptr result_buffer,
                                     i32 num_rand_states,
                                     i32 use_preallocated_buffer) {
  i64 size = 0;

  if (use_preallocated_buffer) {
    size += taichi::iroundup(i64(sizeof(LLVMRuntime)), taichi_page_size);
  }

  size +=
      taichi::iroundup(i64(taichi_global_tmp_buffer_size), taichi_page_size);
  size += taichi::iroundup(i64(sizeof(RandState)) * num_rand_states,
                           taichi_page_size);

  reinterpret_cast<i64 *>(result_buffer)[0] = size;
}

Option<nlohmann::json> NaturalLanguageSearchModel::google_generate_search_params(
    const std::string& query,
    const std::string& system_prompt,
    const nlohmann::json& model_config) {

    const std::string& model_name = model_config["model_name"].get<std::string>();
    const std::string& model_name_without_namespace = model_name.substr(model_name.find('/') + 1);
    float temperature = model_config.value("temperature", 0.0f);
    size_t max_bytes = model_config["max_bytes"].get<size_t>();

    nlohmann::json request_body;

    // Add system instruction if present
    if(!system_prompt.empty()) {
        request_body["systemInstruction"] = {
            {"parts", {{{"text", system_prompt}}}}
        };
    }

    // Add user content
    request_body["contents"] = {{
        {"parts", {{{"text", query}}}}
    }};

    // Add generation config
    nlohmann::json generation_config;
    generation_config["temperature"] = temperature;
    generation_config["maxOutputTokens"] = max_bytes;

    if(model_config.count("top_p") != 0) {
        generation_config["topP"] = model_config["top_p"].get<float>();
    }

    if(model_config.count("top_k") != 0) {
        generation_config["topK"] = model_config["top_k"].get<int>();
    }

    if(model_config.count("stop_sequences") != 0) {
        generation_config["stopSequences"] = model_config["stop_sequences"];
    }

    request_body["generationConfig"] = generation_config;

    auto result = call_google_api(request_body, model_config, DEFAULT_TIMEOUT_MS);
    if(!result.ok()) {
        return Option<nlohmann::json>(500, "Failed to get response from Google Gemini: " + result.error());
    }

    auto response_json = result.get();
    // Extract text from Gemini response format
    if(!response_json.contains("candidates") || !response_json["candidates"].is_array() || 
       response_json["candidates"].empty()) {
        return Option<nlohmann::json>(500, "No valid candidates in Google Gemini response");
    }

    auto& candidate = response_json["candidates"][0];
    if(!candidate.contains("content") || !candidate["content"].contains("parts") || 
       !candidate["content"]["parts"].is_array() || candidate["content"]["parts"].empty()) {
        return Option<nlohmann::json>(500, "No valid content in Google Gemini response");
    }

    auto& part = candidate["content"]["parts"][0];
    if(!part.contains("text") || !part["text"].is_string()) {
        return Option<nlohmann::json>(500, "No valid text in Google Gemini response");
    }

    std::string content = part["text"].get<std::string>();
    return extract_search_params_from_content(content, model_name_without_namespace);
}

Option<bool> NaturalLanguageSearchModel::validate_gcp_model(const nlohmann::json& model_config) {
    // Required fields
    if(model_config.count("project_id") == 0 || !model_config["project_id"].is_string() || 
       model_config["project_id"].get<std::string>().empty()) {
        return Option<bool>(400, "Property `project_id` is missing or is not a non-empty string.");
    }

    if(model_config.count("access_token") == 0 || !model_config["access_token"].is_string() || 
       model_config["access_token"].get<std::string>().empty()) {
        return Option<bool>(400, "Property `access_token` is missing or is not a non-empty string.");
    }

    if(model_config.count("refresh_token") == 0 || !model_config["refresh_token"].is_string() || 
       model_config["refresh_token"].get<std::string>().empty()) {
        return Option<bool>(400, "Property `refresh_token` is missing or is not a non-empty string.");
    }

    if(model_config.count("client_id") == 0 || !model_config["client_id"].is_string() || 
       model_config["client_id"].get<std::string>().empty()) {
        return Option<bool>(400, "Property `client_id` is missing or is not a non-empty string.");
    }

    if(model_config.count("client_secret") == 0 || !model_config["client_secret"].is_string() || 
       model_config["client_secret"].get<std::string>().empty()) {
        return Option<bool>(400, "Property `client_secret` is missing or is not a non-empty string.");
    }

    // Optional fields
    if(model_config.count("region") != 0 && !model_config["region"].is_string()) {
        return Option<bool>(400, "Property `region` must be a string.");
    }

    if(model_config.count("temperature") != 0 && 
       (!model_config["temperature"].is_number() || 
        model_config["temperature"].get<float>() < 0 || 
        model_config["temperature"].get<float>() > 2)) {
        return Option<bool>(400, "Property `temperature` must be a number between 0 and 2.");
    }

    if(model_config.count("top_p") != 0 && 
       (!model_config["top_p"].is_number() || 
        model_config["top_p"].get<float>() < 0 || 
        model_config["top_p"].get<float>() > 1)) {
        return Option<bool>(400, "Property `top_p` must be a number between 0 and 1.");
    }

    if(model_config.count("top_k") != 0 && 
       (!model_config["top_k"].is_number_integer() || 
        model_config["top_k"].get<int>() < 0)) {
        return Option<bool>(400, "Property `top_k` must be a non-negative integer.");
    }

    if(model_config.count("max_output_tokens") != 0 && 
       (!model_config["max_output_tokens"].is_number_integer() || 
        model_config["max_output_tokens"].get<int>() <= 0)) {
        return Option<bool>(400, "Property `max_output_tokens` must be a positive integer.");
    }

    // Validate credentials by making a test API call
    nlohmann::json test_request;
    test_request["contents"] = {{
        {"role", "user"},
        {"parts", {{{"text", "hello"}}}}
    }};
    test_request["generationConfig"] = {
        {"temperature", 0},
        {"maxOutputTokens", 10}
    };

    auto result = call_gcp_api(test_request, model_config, VALIDATION_TIMEOUT_MS);
    if(!result.ok()) {
        return Option<bool>(400, result.error());
    }

    return Option<bool>(true);
}

Option<nlohmann::json> NaturalLanguageSearchModel::gcp_generate_search_params(
    const std::string& query,
    const std::string& system_prompt,
    const nlohmann::json& model_config) {

    const std::string& model_name = model_config["model_name"].get<std::string>();
    const std::string& model_name_without_namespace = model_name.substr(model_name.find('/') + 1);
    float temperature = model_config.value("temperature", 0.0f);
    size_t max_bytes = model_config["max_bytes"].get<size_t>();

    // Build request body
    nlohmann::json request_body;

    // Combine system prompt and query
    std::string full_prompt = system_prompt;
    if (!full_prompt.empty()) {
        full_prompt += "\n\n";
    }
    full_prompt += query;

    // Add contents
    request_body["contents"] = {{
        {"role", "user"},
        {"parts", {{{"text", full_prompt}}}}
    }};

    // Add generation config
    nlohmann::json generation_config;
    generation_config["temperature"] = temperature;
    generation_config["maxOutputTokens"] = max_bytes;

    if(model_config.count("top_p") != 0) {
        generation_config["topP"] = model_config["top_p"].get<float>();
    }

    if(model_config.count("top_k") != 0) {
        generation_config["topK"] = model_config["top_k"].get<int>();
    }

    if(model_config.count("max_output_tokens") != 0) {
        generation_config["maxOutputTokens"] = model_config["max_output_tokens"].get<int>();
    }

    request_body["generationConfig"] = generation_config;

    auto result = call_gcp_api(request_body, model_config, DEFAULT_TIMEOUT_MS);
    if(!result.ok()) {
        return Option<nlohmann::json>(500, "Failed to get response from GCP Vertex AI: " + result.error());
    }

    auto response_json = result.get();
    // Extract text from Vertex AI response format
    if(!response_json.contains("candidates") || !response_json["candidates"].is_array() || 
       response_json["candidates"].empty()) {
        return Option<nlohmann::json>(500, "No valid candidates in GCP Vertex AI response");
    }

    auto& candidate = response_json["candidates"][0];
    if(!candidate.contains("content") || !candidate["content"].contains("parts") || 
       !candidate["content"]["parts"].is_array() || candidate["content"]["parts"].empty()) {
        return Option<nlohmann::json>(500, "No valid content in GCP Vertex AI response");
    }

    auto& part = candidate["content"]["parts"][0];
    if(!part.contains("text") || !part["text"].is_string()) {
        return Option<nlohmann::json>(500, "No valid text in GCP Vertex AI response");
    }

    std::string content = part["text"].get<std::string>();
    return extract_search_params_from_content(content, model_name_without_namespace);
}

Option<std::string> NaturalLanguageSearchModel::generate_gcp_access_token(
    const std::string& refresh_token, 
    const std::string& client_id, 
    const std::string& client_secret) {

    const std::string GCP_AUTH_TOKEN_URL = "https://oauth2.googleapis.com/token";

    std::unordered_map<std::string, std::string> headers;
    headers["Content-Type"] = "application/x-www-form-urlencoded";

    std::map<std::string, std::string> res_headers;
    std::string res;
    std::string req_body = "grant_type=refresh_token&client_id=" + client_id + 
                          "&client_secret=" + client_secret + "&refresh_token=" + refresh_token;

    auto res_code = post_response(GCP_AUTH_TOKEN_URL, req_body, res, res_headers, headers, DEFAULT_TIMEOUT_MS);

    if(res_code != 200) {
        nlohmann::json json_res;
        try {
            json_res = nlohmann::json::parse(res);
        } catch (const std::exception& e) {
            return Option<std::string>(400, "Got malformed response from GCP OAuth API.");
        }

        // Handle OAuth2 error response format
        if(json_res.count("error") != 0) {
            std::string error_msg = "GCP OAuth API error: ";

            // OAuth2 errors have "error" as a string and "error_description" as additional info
            if(json_res["error"].is_string()) {
                error_msg += json_res["error"].get<std::string>();
                if(json_res.count("error_description") != 0 && json_res["error_description"].is_string()) {
                    error_msg += " - " + json_res["error_description"].get<std::string>();
                }
            }
            // Some GCP errors have "error" as an object with "message" field
            else if(json_res["error"].is_object() && json_res["error"].count("message") != 0) {
                error_msg += json_res["error"]["message"].get<std::string>();
            }
            else {
                error_msg += "Unknown error format";
            }

            return Option<std::string>(400, error_msg);
        }

        return Option<std::string>(400, "GCP OAuth API error: HTTP " + std::to_string(res_code));
    }

    nlohmann::json res_json;
    try {
        res_json = nlohmann::json::parse(res);
    } catch (const std::exception& e) {
        return Option<std::string>(400, "Got malformed response from GCP OAuth API.");
    }

    if(!res_json.contains("access_token") || !res_json["access_token"].is_string()) {
        return Option<std::string>(400, "No access token in GCP OAuth response");
    }

    std::string access_token = res_json["access_token"].get<std::string>();
    return Option<std::string>(access_token);
}

void NaturalLanguageSearchModel::clear_mock_responses() {
    mock_responses.clear();
    mock_response_index = 0;
    captured_requests.clear();
}

Option<nlohmann::json> NaturalLanguageSearchModel::call_openai_api(
    const nlohmann::json& request_body,
    const nlohmann::json& model_config,
    long timeout_ms) {

    const std::string& api_key = model_config.contains("api_key") ? model_config["api_key"].get<std::string>() : "";
    std::string api_url = model_config.value("api_url", std::string("https://api.openai.com/v1/chat/completions"));

    std::unordered_map<std::string, std::string> headers = {
        {"Content-Type", "application/json"}
    };

    if(!api_key.empty()) {
        headers["Authorization"] = "Bearer " + api_key;
    }

    std::string response;
    std::map<std::string, std::string> response_headers;
    long status_code = post_response(api_url, request_body.dump(), response, response_headers, headers, timeout_ms);

    if(status_code == 408) {
        return Option<nlohmann::json>(408, "OpenAI API timeout.");
    }

    if(status_code != 200) {
        std::string error_msg = "OpenAI API error: ";
        try {
            nlohmann::json response_json = nlohmann::json::parse(response);
            if(response_json.contains("error") && response_json["error"].contains("message")) {
                error_msg += response_json["error"]["message"].get<std::string>();
            } else {
                error_msg += "HTTP " + std::to_string(status_code);
            }
        } catch(...) {
            error_msg += "HTTP " + std::to_string(status_code);
        }
        return Option<nlohmann::json>(status_code, error_msg);
    }

    try {
        return Option<nlohmann::json>(nlohmann::json::parse(response));
    } catch(const std::exception& e) {
        return Option<nlohmann::json>(500, "Failed to parse OpenAI response: Invalid JSON");
    }
}

Option<nlohmann::json> NaturalLanguageSearchModel::call_cloudflare_api(
    const nlohmann::json& request_body,
    const nlohmann::json& model_config,
    long timeout_ms) {

    const std::string& model_name = model_config["model_name"].get<std::string>();
    const std::string& model_name_without_namespace = model_name.substr(model_name.find("/") + 1);
    const std::string& api_key = model_config["api_key"].get<std::string>();
    const std::string& account_id = model_config["account_id"].get<std::string>();

    std::string api_url = "https://api.cloudflare.com/client/v4/accounts/" + account_id + "/ai/run/" + model_name_without_namespace;

    std::unordered_map<std::string, std::string> headers = {
        {"Content-Type", "application/json"},
        {"Authorization", "Bearer " + api_key}
    };

    std::string response;
    std::map<std::string, std::string> response_headers;
    long status_code = post_response(api_url, request_body.dump(), response, response_headers, headers, timeout_ms);

    if(status_code == 408) {
        return Option<nlohmann::json>(408, "Cloudflare API timeout.");
    }

    if(status_code != 200) {
        std::string error_msg = "Cloudflare API error: ";
        try {
            nlohmann::json response_json = nlohmann::json::parse(response);
            if(response_json.contains("errors") && response_json["errors"].is_array() && !response_json["errors"].empty()) {
                error_msg += response_json["errors"][0]["message"].get<std::string>();
            } else {
                error_msg += "HTTP " + std::to_string(status_code);
            }
        } catch(...) {
            error_msg += "HTTP " + std::to_string(status_code);
        }
        return Option<nlohmann::json>(status_code, error_msg);
    }

    try {
        return Option<nlohmann::json>(nlohmann::json::parse(response));
    } catch(const std::exception& e) {
        return Option<nlohmann::json>(500, "Cloudflare API response JSON parse error: Invalid JSON");
    }
}

Option<nlohmann::json> NaturalLanguageSearchModel::call_google_api(
    const nlohmann::json& request_body,
    const nlohmann::json& model_config,
    long timeout_ms) {

    const std::string& model_name = model_config["model_name"].get<std::string>();
