void BuildVectorCreationHelper(const StructDef& struct_def,
                                 const FieldDef& field, std::string* code_ptr,
                                 ImportMap& imports) const {
    auto& code = *code_ptr;
    const auto vector_type = field.value.type.VectorType();
    const bool is_struct_vector = IsStruct(vector_type);
    const bool is_scalar_vector =
        IsScalar(vector_type.base_type) || vector_type.enum_def != nullptr;
    const std::string struct_type = namer_.Type(struct_def);
    const std::string field_method = namer_.Method(field);
    const std::string helper_name =
        parser_.opts.python_no_type_prefix_suffix
            ? "Create" + field_method + "Vector"
            : struct_type + "Create" + field_method + "Vector";

    if (parser_.opts.python_typing) {
      imports.insert(ImportMapEntry{"typing", "Iterable"});
      code += "def " + helper_name +
              "(builder: flatbuffers.Builder, data: Iterable[Any]) -> int:\n";
    } else {
      code += "def " + helper_name + "(builder, data):\n";
    }

    if (is_scalar_vector || is_struct_vector) {
      auto alignment = InlineAlignment(vector_type);
      auto elem_size = InlineSize(vector_type);
      code += Indent + "data = list(data)\n";
      code += Indent + "builder.StartVector(" + NumToString(elem_size) +
              ", len(data), " + NumToString(alignment) + ")\n";
      code += Indent + "for item in reversed(data):\n";
      if (is_struct_vector) {
        code += Indent + Indent + "item.Pack(builder)\n";
      } else {
        code += Indent + Indent + "builder.Prepend" +
                namer_.Method(GenTypeBasic(vector_type)) + "(item)\n";
      }
      code += Indent + "return builder.EndVector()\n\n";
    } else {
      code += Indent + "return builder.CreateVectorOfTables(data)\n\n";
    }

    if (!parser_.opts.one_file && !parser_.opts.python_no_type_prefix_suffix) {
      if (parser_.opts.python_typing) {
        code += "def Create" + field_method +
                "Vector(builder: flatbuffers.Builder, data: Iterable[Any]) "
                "-> int:\n";
      } else {
        code += "def Create" + field_method + "Vector(builder, data):\n";
      }
      code += Indent + helper_name + "(builder, data)\n\n";
    }
  }

void TelemetryTraceLogger::LogStoreInstall(std::string_view packageId) const noexcept
    {
        // Don't use IsTelemetryEnabled as that also checks the WinGet provider.
        if (g_IsStoreTelemetryProviderEnabled && m_isInitialized && m_isSettingEnabled && m_isRuntimeEnabled)
        {
            TraceLoggingWrite(g_hWindowsStoreProvider,
                "StoreExperienceTelemetry-WinGetInstall",
                TelemetryPrivacyDataTag(PDT_ProductAndServicePerformance),
                TraceLoggingKeyword(MICROSOFT_KEYWORD_CRITICAL_DATA),
                AICLI_TraceLoggingStringView(packageId, "pid"),
                TraceLoggingString(m_caller.c_str(), "src"),
                TraceLoggingWideString(L"msstore", "cn")
            );
        }
    }

SortablePackageEntry::SortablePackageEntry(
        size_t originalIndex,
        std::string_view name,
        std::string_view id,
        std::string_view installedVersion,
        std::string_view availableVersion,
        std::string_view source,
        SortField fieldMask)
        : OriginalIndex(originalIndex)
    {
        if (WI_IsFlagSet(fieldMask, SortField::Name))
        {
            FoldedName = Utility::FoldCase(name);
        }
        if (WI_IsFlagSet(fieldMask, SortField::Id))
        {
            FoldedId = Utility::FoldCase(id);
        }
        if (WI_IsFlagSet(fieldMask, SortField::Source))
        {
            FoldedSource = Utility::FoldCase(source);
        }
        if (WI_IsFlagSet(fieldMask, SortField::Version))
        {
            ParsedInstalledVersion = Utility::Version{ std::string{ installedVersion } };
        }
        if (WI_IsFlagSet(fieldMask, SortField::Available))
        {
            if (!availableVersion.empty())
            {
                ParsedAvailableVersion = Utility::Version{ std::string{ availableVersion } };
            }
        }
    }

SortField ComputeSortFieldMask(const std::vector<SortField>& sortFields)
    {
        SortField mask = SortField::None;
        for (const auto& f : sortFields)
        {
            mask |= f;
        }
        return mask;
    }

SortParameters::SortParameters(const Execution::Context& context)
    {
        if (context.Args.Contains(Execution::Args::Type::Sort))
        {
            for (const auto& arg : *context.Args.GetArgs(Execution::Args::Type::Sort))
            {
                auto field = ConvertToSortField(arg);
                WI_ASSERT(field.has_value());
                if (field.has_value())
                {
                    Fields.emplace_back(field.value());
                }
            }
        }
        else
        {
            Fields = User().Get<Setting::OutputSortOrder>();

            if (Fields.empty())
            {
                bool hasQuery = context.Args.Contains(Execution::Args::Type::Query) ||
                    context.Args.Contains(Execution::Args::Type::MultiQuery);

                if (hasQuery)
                {
                    // Preserve relevance ordering when a free-text query is present
                    // and no explicit sort preference is configured.
                    return; // ShouldSort remains false
                }

                // No settings, no query — default to name sort.
                Fields.emplace_back(SortField::Name);
            }
        }

        // Relevance-only means preserve source ordering.
        if (Fields.size() == 1 && Fields[0] == SortField::Relevance)
        {
            return; // ShouldSort remains false
        }

        // Resolve direction: CLI flags override settings
        Direction = context.Args.Contains(Execution::Args::Type::SortDescending) ? SortDirection::Descending :
            context.Args.Contains(Execution::Args::Type::SortAscending) ? SortDirection::Ascending :
            User().Get<Setting::OutputSortDirection>();

        ShouldSort = true;
    }

t CompareByField(const SortablePackageEntry& a, const SortablePackageEntry& b, SortField field)
    {
        switch (field)
        {
        case SortField::Name:
            return a.FoldedName.compare(b.FoldedName);
        case SortField::Id:
            return a.FoldedId.compare(b.FoldedId);
        case SortField::Version:
        {
            if (a.ParsedInstalledVersion < b.ParsedInstalledVersion) return -1;
            if (b.ParsedInstalledVersion < a.ParsedInstalledVersion) return 1;
            return 0;
        }
        case SortField::Source:
            return a.FoldedSource.compare(b.FoldedSource);
        case SortField::Available:
        {
            bool aHas = a.ParsedAvailableVersion.has_value();
            bool bHas = b.ParsedAvailableVersion.has_value();

            // Has-version sorts before no-version in ascending order.
            if (aHas != bHas)
            {
                return aHas ? -1 : 1;
            }

            // Both have versions — compare normally.
            if (aHas && bHas)
            {
                if (a.ParsedAvailableVersion.value() < b.ParsedAvailableVersion.value()) return -1;
                if (b.ParsedAvailableVersion.value() < a.ParsedAvailableVersion.value()) return 1;
            }
            return 0;
        }
        case SortField::Relevance:
            // Relevance has no precomputed sort key — preserve original ordering.
            return 0;
        default:
            WI_ASSERT(false);
            return 0;
        }
    }

ortEntries(
        std::vector<SortablePackageEntry>& entries,
        const SortParameters& sortParams)
    {
        if (entries.size() <= 1 || !sortParams.ShouldSort)
        {
            return;
        }

        std::stable_sort(entries.begin(), entries.end(),
            [&sortParams](const SortablePackageEntry& a, const SortablePackageEntry& b)
            {
                for (const auto& field : sortParams.Fields)
                {
                    int cmp = CompareByField(a, b, field);
                    if (cmp != 0)
                    {
                        return sortParams.Direction == SortDirection::Ascending ? (cmp < 0) : (cmp > 0);
                    }
                }
                return false;
            });
    }
}

void SortInstalledPackagesTableLines(Execution::Context& context, std::vector<InstalledPackagesTableLine>& lines)
        {
            if (lines.size() <= 1)
            {
                return;
            }

            const SortParameters params(context);

            // Not strictly required — SortBy handles this internally — but avoids
            // constructing the SortablePackageEntry vector when no sorting is needed.
            if (!params.ShouldSort)
            {
                return;
            }

            const SortField mask = ComputeSortFieldMask(params.Fields);
            SortBy(lines,
                [mask](const InstalledPackagesTableLine& line, size_t index) {
                    return SortablePackageEntry(
                        index,
                        line.Name.get(),
                        line.Id.get(),
                        line.InstalledVersion.get(),
                        line.AvailableVersion.get(),
                        line.Source.get(),
                        mask);
                },
                params);
        }

void ValidateSortResult(
        const std::vector<SortablePackageEntry>& actual,
        const std::vector<SortablePackageEntry>& expected)
    {
        REQUIRE(actual.size() == expected.size());
        for (size_t i = 0; i < actual.size(); ++i)
        {
            INFO("Entry index: " << i);
            REQUIRE(actual[i].FoldedName == expected[i].FoldedName);
            REQUIRE(actual[i].FoldedId == expected[i].FoldedId);
            REQUIRE(actual[i].FoldedSource == expected[i].FoldedSource);
            REQUIRE(actual[i].ParsedInstalledVersion == expected[i].ParsedInstalledVersion);
            REQUIRE(actual[i].ParsedAvailableVersion == expected[i].ParsedAvailableVersion);
        }
    }

SortParameters MakeSortParams(std::vector<SortField> fields, SortDirection direction = SortDirection::Ascending)
    {
        SortParameters params;
        params.Fields = std::move(fields);
        params.Direction = direction;
        params.ShouldSort = !params.Fields.empty() &&
            !(params.Fields.size() == 1 && params.Fields[0] == SortField::Relevance);
        return params;
    }

std::optional<SortField> ConvertToSortField(std::string_view value)
    {
        static constexpr std::string_view s_sortField_relevance = "relevance";
        static constexpr std::string_view s_sortField_name = "name";
        static constexpr std::string_view s_sortField_id = "id";
        static constexpr std::string_view s_sortField_version = "version";
        static constexpr std::string_view s_sortField_source = "source";
        static constexpr std::string_view s_sortField_available = "available";

        std::string lowered = Utility::ToLower(value);

        if (lowered == s_sortField_relevance) return SortField::Relevance;
        if (lowered == s_sortField_name) return SortField::Name;
        if (lowered == s_sortField_id) return SortField::Id;
        if (lowered == s_sortField_version) return SortField::Version;
        if (lowered == s_sortField_source) return SortField::Source;
        if (lowered == s_sortField_available) return SortField::Available;
        return std::nullopt;
    }

WINGET_VALIDATE_SIGNATURE(OutputSortOrder)
        {
            std::vector<SortField> fields;
            for (auto const& entry : value)
            {
                auto field = ConvertToSortField(entry);
                if (!field)
                {
                    return {};
                }
                fields.emplace_back(field.value());
            }
            return fields;
        }

WINGET_VALIDATE_SIGNATURE(OutputSortDirection)
        {
            static constexpr std::string_view s_sortDirection_ascending = "ascending";
            static constexpr std::string_view s_sortDirection_descending = "descending";

            if (Utility::CaseInsensitiveEquals(value, s_sortDirection_ascending))
            {
                return SortDirection::Ascending;
            }
            else if (Utility::CaseInsensitiveEquals(value, s_sortDirection_descending))
            {
                return SortDirection::Descending;
            }

            return {};
        }

bool llamafile_consume_flag(int *argc, char **argv, const char *flag) {
    bool found = false;
    int w = 1;
    for (int r = 1; r < *argc; ++r) {
        if (!strcmp(argv[r], flag)) {
            found = true;
        } else {
            argv[w++] = argv[r];
        }
    }
    argv[w] = 0;
    *argc = w;
    return found;
}

bool llamafile_sandbox_supported(void) {
#ifdef COSMOCC
    return !pledge(0, 0);
#else
    return false;
#endif
}

static int sandbox_skip_status(void) {
    if (FLAG_unsecure)
        return LLAMAFILE_SANDBOX_UNSECURE;
    if (llamafile_has_gpu())
        return LLAMAFILE_SANDBOX_GPU;
    if (!llamafile_sandbox_supported())
        return LLAMAFILE_SANDBOX_UNSUPPORTED;
    return LLAMAFILE_SANDBOX_ACTIVE;
}

static int sandbox_install_pledge(const char *promises) {
#ifdef COSMOCC
    __pledge_mode = PLEDGE_PENALTY_RETURN_EPERM;
    return pledge(promises, 0) ? LLAMAFILE_SANDBOX_FAILED
                               : LLAMAFILE_SANDBOX_ACTIVE;
#else
    (void)promises;
    return LLAMAFILE_SANDBOX_UNSUPPORTED;
#endif
}

int llamafile_sandbox_apply(const char *promises) {
    if (!llamafile_sandbox_supported())
        return LLAMAFILE_SANDBOX_UNSUPPORTED;
    return sandbox_install_pledge(promises);
}

int llamafile_sandbox(const char *promises) {
    int skip = sandbox_skip_status();
    if (skip != LLAMAFILE_SANDBOX_ACTIVE)
        return skip;
    return sandbox_install_pledge(promises);
}

int llamafile_sandbox_enter(const char *promises, bool verbose) {
    int status = llamafile_sandbox(promises);
    if (status == LLAMAFILE_SANDBOX_FAILED) {
        perror("pledge");
    } else if (verbose) {
        fprintf(stderr, "sandbox: %s\n", llamafile_sandbox_describe(status));
    }
    return status;
}

void llamafile_sandbox_server_promises(char *out, size_t len, bool is_openbsd,
                                       bool has_rw, bool needs_outbound) {
    // "anet" is accept()-only networking (no connect) -- the default, so a
    // compromised server can't dial out. When the server itself must make
    // outbound connections (--rpc, server-side tools, the MCP proxy) we relax
    // to "inet", which still blocks writes and exec. OpenBSD has no "anet", so
    // it always uses "inet".
    const char *net = (is_openbsd || needs_outbound) ? "inet" : "anet";
    if (has_rw)  // slot save/restore and the prompt cache read+write on disk
        snprintf(out, len, "stdio %s rpath wpath cpath", net);
    else
        snprintf(out, len, "stdio %s rpath", net);
}

static bool container_of(const char *path, char *dir, size_t len) {
    if (!path_on_disk(path))
        return false;
    if (isdirectory(path)) {
        strlcpy(dir, path, len);
        return true;
    }
    strlcpy(dir, path, len);
    char *slash = strrchr(dir, '/');
    if (!slash)
        strlcpy(dir, ".", len);        // bare "file" -> cwd
    else if (slash == dir)
        strlcpy(dir, path, len);       // "/file" -> the file, never "/"
    else
        *slash = '\0';                 // "dir/file" -> "dir"
    return true;
}

static void unveil_container(const char *path, const char *perms) {
    char dir[PATH_MAX];
    if (container_of(path, dir, sizeof(dir)))
        unveil(dir, perms);
}

static void unveil_apply(const char *const *read_paths, int n_read,
                         const char *const *rw_paths, int n_rw) {
    unveil(GetProgramExecutableName(), "r");
    if (path_on_disk("/etc/hosts"))
        unveil("/etc/hosts", "r");
    if (path_on_disk("/etc/resolv.conf"))
        unveil("/etc/resolv.conf", "r");
    for (int i = 0; i < n_read; ++i)
        unveil_container(read_paths[i], "r");
    for (int i = 0; i < n_rw; ++i)
        unveil_container(rw_paths[i], "rwc");
}

static bool can_read(const char *path) {
    int fd = open(path, O_RDONLY);
    if (fd < 0)
        return false;
    close(fd);
    return true;
}

static bool is_denied(const char *path) {
    errno = 0;
    int fd = open(path, O_RDONLY);
    if (fd >= 0) {
        close(fd);
        return false;
    }
    return errno == EACCES || errno == EPERM;
}

static bool unveil_is_governable(const char *const *read_paths, int n_read,
                                 const char *const *rw_paths, int n_rw) {
    pid_t pid = fork();
    if (pid < 0)
        return false;
    if (!pid) {
        // Snapshot the paths the locked ruleset must still let us read,
        // computed while access() is unrestricted.
        char verify[SANDBOX_PROBE_MAX][PATH_MAX];
        int nv = 0;
        strlcpy(verify[nv++], GetProgramExecutableName(), PATH_MAX);
        for (int i = 0; i < n_read && nv < SANDBOX_PROBE_MAX; ++i)
            if (path_on_disk(read_paths[i]))
                strlcpy(verify[nv++], read_paths[i], PATH_MAX);
        for (int i = 0; i < n_rw && nv < SANDBOX_PROBE_MAX; ++i)
            if (container_of(rw_paths[i], verify[nv], PATH_MAX))
                ++nv;

        // Pick a canary that exists now, before the ruleset can hide it.
        const char *canary = 0;
        for (size_t i = 0; i < sizeof(kSandboxCanaries) / sizeof(*kSandboxCanaries); ++i)
            if (!access(kSandboxCanaries[i], F_OK)) {
                canary = kSandboxCanaries[i];
                break;
            }

        unveil_apply(read_paths, n_read, rw_paths, n_rw);
        unveil(0, 0);  // lock

        int ok = 1;
        for (int i = 0; ok && i < nv; ++i)
            ok = can_read(verify[i]);
        // Confinement must demonstrably bite: the canary, outside every
        // rule, must now be *denied* (EACCES/EPERM). No canary, or one that
        // fails for another reason, is inconclusive -- treat as "not
        // confined" rather than claiming a guarantee unveil() didn't install.
        if (ok && (!canary || !is_denied(canary)))
            ok = 0;
        _exit(ok ? 0 : 1);
    }
    int ws;
    while (waitpid(pid, &ws, 0) < 0 && errno == EINTR) {
    }
    return WIFEXITED(ws) && WEXITSTATUS(ws) == 0;
}

int llamafile_sandbox_server(const struct llamafile_sandbox_spec *spec,
                             char *promises_out, size_t promises_len) {
    if (promises_out && promises_len)
        promises_out[0] = '\0';
    int skip = sandbox_skip_status();
    if (skip != LLAMAFILE_SANDBOX_ACTIVE)
        return skip;
#ifdef COSMOCC
    // wpath/cpath only when a write target is actually configured; callers
    // pass fixed-position entries that are often empty strings.
    bool has_rw = false;
    for (int i = 0; i < spec->n_rw; ++i)
        if (spec->rw_paths[i] && *spec->rw_paths[i])
            has_rw = true;
    char promises[64];
    llamafile_sandbox_server_promises(promises, sizeof(promises), IsOpenbsd(),
                                      has_rw, spec->needs_outbound);
    if (promises_out)
        strlcpy(promises_out, promises, promises_len);

    // Opt-in unveil() path confinement, run before pledge() (it needs
    // Landlock syscalls the pledge filter denies). Skip it when the
    // filesystem can't enforce it, rather than locking down a server that can
    // no longer read its weights. 0 = not requested, 1 = confined, 2 = asked
    // for but unavailable.
    int confine_state = 0;
    if (spec->confine) {
        if (unveil_is_governable(spec->read_paths, spec->n_read,
                                 spec->rw_paths, spec->n_rw)) {
            unveil_apply(spec->read_paths, spec->n_read,
                         spec->rw_paths, spec->n_rw);
            unveil(0, 0);  // lock the ruleset
            confine_state = 1;
        } else {
            confine_state = 2;
        }
    }

    if (sandbox_install_pledge(promises) == LLAMAFILE_SANDBOX_FAILED)
        return LLAMAFILE_SANDBOX_FAILED;
    return confine_state == 1 ? LLAMAFILE_SANDBOX_ACTIVE_CONFINED
         : confine_state == 2 ? LLAMAFILE_SANDBOX_ACTIVE_UNCONFINED
                              : LLAMAFILE_SANDBOX_ACTIVE;
#else
    (void)spec;
    return LLAMAFILE_SANDBOX_UNSUPPORTED;
#endif
}

bool llamafile_sandbox_is_active(int status) {
    return status == LLAMAFILE_SANDBOX_ACTIVE ||
           status == LLAMAFILE_SANDBOX_ACTIVE_CONFINED ||
           status == LLAMAFILE_SANDBOX_ACTIVE_UNCONFINED;
}

const char *llamafile_sandbox_describe(int status) {
    switch (status) {
    case LLAMAFILE_SANDBOX_ACTIVE:
        return "active";
    case LLAMAFILE_SANDBOX_ACTIVE_CONFINED:
        return "active, reads confined to weights dirs";
    case LLAMAFILE_SANDBOX_ACTIVE_UNCONFINED:
        return "active (path confinement requested but unavailable on this filesystem)";
    case LLAMAFILE_SANDBOX_UNSECURE:
        return "disabled by --unsecure";
    case LLAMAFILE_SANDBOX_GPU:
        return "disabled in GPU mode";
    case LLAMAFILE_SANDBOX_UNSUPPORTED:
        return "not supported on this OS";
    case LLAMAFILE_SANDBOX_FAILED:
        return "failed";
    default:
        return "unknown";
    }
}

static void child_rpath_promises(void) {
    CHECK(llamafile_sandbox_apply("stdio rpath") == LLAMAFILE_SANDBOX_ACTIVE,
          "apply stdio rpath");

    // reads must keep working: model weights are opened after pledge
    int fd = open("/dev/null", O_RDONLY);
    CHECK(fd != -1, "open O_RDONLY allowed under rpath");
    close(fd);

    // threads must keep working: ggml spawns its compute pool after pledge
    pthread_t th;
    CHECK(!pthread_create(&th, 0, thread_fn, 0), "pthread_create under stdio");
    pthread_join(th, 0);

    // no filesystem writes
    errno = 0;
    CHECK(open("sandbox_test.tmp", O_WRONLY | O_CREAT | O_TRUNC, 0644) == -1,
          "open O_WRONLY|O_CREAT blocked");
    CHECK(errno == EPERM, "write open fails with EPERM, not a kill");

    // no network at all
    errno = 0;
    CHECK(socket(AF_INET, SOCK_STREAM, 0) == -1, "socket() blocked");
    CHECK(errno == EPERM, "socket() fails with EPERM");

    _exit(0);
}

static void child_stdio_only(void) {
    CHECK(llamafile_sandbox_apply("stdio") == LLAMAFILE_SANDBOX_ACTIVE,
          "apply stdio");
    errno = 0;
    CHECK(open("/dev/null", O_RDONLY) == -1, "open O_RDONLY blocked");
    CHECK(errno == EPERM, "read open fails with EPERM");
    _exit(0);
}

static void child_anet_promises(void) {
    // pre-pledge: a second socket to attempt the outbound connect() with
    int censored = socket(AF_INET, SOCK_STREAM, 0);
    CHECK(censored != -1, "pre-pledge socket");

    CHECK(llamafile_sandbox_apply("stdio anet rpath") == LLAMAFILE_SANDBOX_ACTIVE,
          "apply stdio anet rpath");

    // the listening side of the HTTP server must keep working
    int server = socket(AF_INET, SOCK_STREAM, 0);
    CHECK(server != -1, "socket() allowed under anet");

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = 0; // ephemeral
    CHECK(!bind(server, (struct sockaddr *)&addr, sizeof(addr)),
          "bind() allowed under anet");
    CHECK(!listen(server, 1), "listen() allowed under anet");

    socklen_t addrlen = sizeof(addr);
    CHECK(!getsockname(server, (struct sockaddr *)&addr, &addrlen),
          "getsockname()");

    // accept() is permitted: with no pending client it must report
    // EAGAIN (not EPERM, which would mean the filter rejected it)
    int flags = fcntl(server, F_GETFL);
    CHECK(flags != -1 && fcntl(server, F_SETFL, flags | O_NONBLOCK) != -1,
          "set O_NONBLOCK");
    errno = 0;
    CHECK(accept(server, 0, 0) == -1, "accept with no client");
    CHECK(errno == EAGAIN || errno == EWOULDBLOCK,
          "accept() allowed by filter (EAGAIN, not EPERM)");

    // outbound connections must be denied, even to ourselves
    errno = 0;
    CHECK(connect(censored, (struct sockaddr *)&addr, sizeof(addr)) == -1,
          "connect() blocked under anet");
    CHECK(errno == EPERM, "connect() fails with EPERM");

    _exit(0);
}

static void child_unveil(void) {
    // Two files we own: one inside a directory we will unveil (must stay
    // readable), one outside it (a self-made canary that must become denied
    // -- a sibling under /tmp, never a system file).
    char dir[] = "/tmp/lf_uv_XXXXXX";
    CHECK(mkdtemp(dir), "mkdtemp");
    char inside[PATH_MAX];
    snprintf(inside, sizeof(inside), "%s/weights.bin", dir);
    int fd = open(inside, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    CHECK(fd != -1, "create file inside temp dir");
    close(fd);

    char canary[] = "/tmp/lf_canary_XXXXXX";
    fd = mkstemp(canary);  // outside `dir`, so confinement must hide it
    CHECK(fd != -1, "mkstemp canary");
    close(fd);

    unveil(dir, "r");
    unveil(0, 0);  // lock

    int in = open(inside, O_RDONLY);
    if (in == -1) {
        // filesystem accepts unveil() but denies everything: over-denies
        fprintf(stderr, "sandbox_test: unveil: SKIP (filesystem not "
                        "Landlock-governable)\n");
        _exit(0);
    }
    close(in);

    // If the canary outside the unveiled dir is still readable, unveil()
    // installed nothing (kernel without Landlock, or cosmo's silent no-op):
    // there is no confinement to assert. Same check the production probe
    // makes, on a file we created rather than a system file.
    errno = 0;
    int c = open(canary, O_RDONLY);
    if (c != -1) {
        close(c);
        fprintf(stderr, "sandbox_test: unveil: SKIP (Landlock unavailable; "
                        "confinement not installed)\n");
        _exit(0);
    }
    CHECK(errno == EACCES || errno == EPERM,
          "unveil denial is EACCES/EPERM, not a kill");
    _exit(0);
}

static int run_case(const char *name, void (*fn)(void)) {
    pid_t pid = fork();
    if (!pid)
        fn(); // never returns
    int ws;
    if (waitpid(pid, &ws, 0) != pid || !WIFEXITED(ws) || WEXITSTATUS(ws)) {
        fprintf(stderr, "sandbox_test: %s: FAILED%s\n", name,
                WIFSIGNALED(ws) ? " (killed by signal)" : "");
        return 1;
    }
    printf("sandbox_test: %s: OK\n", name);
    return 0;
}

static int test_promises(void) {
    struct {
        bool openbsd, has_rw, outbound;
        const char *want;
    } cases[] = {
        {false, false, false, "stdio anet rpath"},
        {false, true, false, "stdio anet rpath wpath cpath"},
        {false, false, true, "stdio inet rpath"},              // --rpc etc.
        {false, true, true, "stdio inet rpath wpath cpath"},
        {true, false, false, "stdio inet rpath"},              // OpenBSD: no anet
        {true, true, false, "stdio inet rpath wpath cpath"},
    };
    int rc = 0;
    for (size_t i = 0; i < sizeof(cases) / sizeof(*cases); ++i) {
        char got[64];
        llamafile_sandbox_server_promises(got, sizeof(got), cases[i].openbsd,
                                          cases[i].has_rw, cases[i].outbound);
        if (strcmp(got, cases[i].want)) {
            fprintf(stderr, "sandbox_test: promises: FAILED want=\"%s\" got=\"%s\"\n",
                    cases[i].want, got);
            rc = 1;
        }
    }
    if (!rc)
        printf("sandbox_test: server promise derivation: OK\n");
    return rc;
}

int main(void) {
    int rc = 0;

    // Pure logic, runs on every platform.
    rc |= test_promises();

    // The enforcement cases assert Linux SECCOMP semantics: the "anet"
    // promise is a cosmo Linux extension OpenBSD's pledge(2) rejects, and
    // the EPERM assertions assume PLEDGE_PENALTY_RETURN_EPERM (Linux only;
    // OpenBSD kills violators). So gate them to Linux.
    if (!IsLinux() || !llamafile_sandbox_supported()) {
        printf("sandbox_test: SKIP enforcement: needs Linux with SECCOMP "
               "(anet/EPERM semantics are Linux-specific)\n");
        return rc;
    }
    rc |= run_case("stdio+rpath (cli promises)", child_rpath_promises);
    rc |= run_case("stdio only (embedded weights)", child_stdio_only);
    rc |= run_case("stdio+anet+rpath (server promises)", child_anet_promises);
    rc |= run_case("unveil confinement", child_unveil);
    return rc;
}

int main(int argc, char **argv) {
    FLAG_verbose = 1;  // show the probe path so DSO-resolution issues are visible

    struct {
        const char *name;
        bool (*probe)(void);
    } backends[] = {
        {"metal", llamafile_has_metal},
        {"cuda", llamafile_has_cuda},
        {"rocm", llamafile_has_amd_gpu},
        {"vulkan", llamafile_has_vulkan},
    };

    int loaded = 0;
    for (const auto &b : backends) {
        if (b.probe()) {
            fprintf(stderr, "backend_ops_harness: %s backend loaded\n", b.name);
            loaded++;
        } else {
            fprintf(stderr, "backend_ops_harness: %s backend not available\n", b.name);
        }
    }
    if (!loaded)
        fprintf(stderr,
                "backend_ops_harness: WARNING: no GPU backend loaded; "
                "only CPU will be tested\n");

    return backend_ops_main(argc, argv);
}

ggml_backend_reg_t gpu_call_reg(void *fp) {
    if (!fp)
        return NULL;
    if (IsWindows())
        return ((ggml_backend_reg_t(__attribute__((__ms_abi__)) *)(void))fp)();
    return ((ggml_backend_reg_t(*)(void))fp)();
}

int gpu_call_device_count(void *fp) {
    if (!fp)
        return 0;
    if (IsWindows())
        return ((int(__attribute__((__ms_abi__)) *)(void))fp)();
    return ((int(*)(void))fp)();
}

void gpu_call_get_description(void *fp, int device, char *buf, size_t n) {
    if (!fp)
        return;
    if (IsWindows())
        ((void(__attribute__((__ms_abi__)) *)(int, char *, size_t))fp)(device, buf, n);
    else
        ((void(*)(int, char *, size_t))fp)(device, buf, n);
}

void gpu_call_log_set(void *fp, llamafile_log_callback cb, void *user_data) {
    if (!fp)
        return;
    if (IsWindows())
        ((void(__attribute__((__ms_abi__)) *)(llamafile_log_callback, void *))fp)(cb, user_data);
    else
        ((void(*)(llamafile_log_callback, void *))fp)(cb, user_data);
}

void gpu_backend_unlink(GpuBackend *b) {
    if (b->lib_handle) {
        cosmo_dlclose(b->lib_handle);
        b->lib_handle = NULL;
    }
    b->backend_init = NULL;
    b->backend_reg = NULL;
    b->get_device_count = NULL;
    b->get_device_description = NULL;
    b->log_set = NULL;
}

bool gpu_backend_link(GpuBackend *b, const char *dso, const GpuBackendDesc *desc) {
    b->desc = desc;

    void *lib = cosmo_dlopen(dso, RTLD_LAZY);
    if (!lib) {
        char *err = cosmo_dlerror();
        llamafile_info(desc->tag, "failed to load library %s: %s", dso,
                       err ? err : "unknown error");
        return false;
    }

    // Required symbols: the backend is unusable without them. get_device_count
    // is required because gpu_backend_probe() relies on it to reject 0-device
    // DSOs (which is what lets AUTO mode fall through to the next backend).
    bool ok = true;
    b->backend_init = cosmo_dlsym(lib, desc->init);
    ok &= (b->backend_init != NULL);
    b->backend_reg = cosmo_dlsym(lib, desc->reg);
    ok &= (b->backend_reg != NULL);
    b->get_device_count = cosmo_dlsym(lib, desc->get_device_count);
    ok &= (b->get_device_count != NULL);

    // Optional symbols: degrade gracefully if absent.
    b->get_device_description =
        desc->get_device_description ? cosmo_dlsym(lib, desc->get_device_description) : NULL;
    b->log_set = cosmo_dlsym(lib, "ggml_log_set");

    if (!ok) {
        char *err = cosmo_dlerror();
        llamafile_info(desc->tag, "could not import all symbols from %s: %s", dso,
                       err ? err : "unknown error");
        cosmo_dlclose(lib);
        b->lib_handle = NULL;
        b->backend_init = NULL;
        b->backend_reg = NULL;
        b->get_device_count = NULL;
        b->get_device_description = NULL;
        b->log_set = NULL;
        return false;
    }

    b->lib_handle = lib;
    return true;
}

static void gpu_guard_handler(int sig) {
    if (g_gpu_guard_active) {
        g_gpu_guard_active = 0;
        siglongjmp(g_gpu_guard_jmp, sig);
    }
    // Fault outside a guarded call: restore default disposition and re-raise so
    // a genuine crash is not silently swallowed.
    signal(sig, SIG_DFL);
    raise(sig);
}

static bool gpu_run_guarded(void (*fn)(void *), void *arg) {
    static const int kSignals[] = {SIGSEGV, SIGABRT, SIGILL, SIGBUS, SIGFPE};
    struct sigaction sa, old[sizeof(kSignals) / sizeof(kSignals[0])];
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = gpu_guard_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_NODEFER;
    for (int i = 0; i < (int)(sizeof(kSignals) / sizeof(kSignals[0])); ++i)
        sigaction(kSignals[i], &sa, &old[i]);

    bool ok;
    // SA_NODEFER (set above) leaves the trapped signal unblocked while the
    // handler runs, so a re-fault in the tiny window before siglongjmp is not
    // dropped. savesigs=1 makes siglongjmp restore the signal mask captured
    // here, keeping the mask correct after we jump out of the fault.
    if (sigsetjmp(g_gpu_guard_jmp, 1) == 0) {
        g_gpu_guard_active = 1;
        fn(arg);
        g_gpu_guard_active = 0;
        ok = true;
    } else {
        g_gpu_guard_active = 0;
        ok = false;
    }

    for (int i = 0; i < (int)(sizeof(kSignals) / sizeof(kSignals[0])); ++i)
        sigaction(kSignals[i], &old[i], NULL);
    return ok;
}

bool gpu_backend_probe(GpuBackend *b) {
    // Suppress the DSO's ggml logging before touching any function that
    // triggers device enumeration inside the DSO. Without this, a failed
    // probe on the wrong backend prints confusing errors even without
    // --verbose.
    if (!FLAG_verbose)
        gpu_call_log_set(b->log_set, llamafile_log_callback_null, NULL);

    // The DSO loads fine even when no compatible hardware is present, so probe
    // the device count before committing. The call goes through the crash guard
    // because for some backends it triggers driver init that can fault across
    // the DSO boundary (see the Crash guard section / issue #988). A fault is
    // treated exactly like "no usable device": unlink and let AUTO mode fall
    // through to the next backend and ultimately to CPU.
    struct gpu_device_count_call call = {b->get_device_count, 0};
    if (!gpu_run_guarded(gpu_device_count_thunk, &call)) {
        llamafile_info(b->desc->tag, "%s crashed during device probe; trying next backend",
                       b->desc->name);
        gpu_backend_unlink(b);
        return false;
    }

    if (call.count <= 0) {
        llamafile_info(b->desc->tag,
                       "%s library loaded but no devices detected; trying next backend",
                       b->desc->name);
        gpu_backend_unlink(b);
        return false;
    }
    return true;
}

void gpu_backend_register(GpuBackend *b) {
    // No crash guard here: register() runs only after gpu_backend_probe()
    // succeeded, so the DSO's driver/instance init already completed without
    // faulting and reg() just returns the (cached) registry.
    ggml_backend_reg_t reg = gpu_call_reg(b->backend_reg);
    if (reg) {
        ggml_backend_register(reg);
        llamafile_info(b->desc->tag, "%s backend registered with GGML", b->desc->name);
    }
}

static void init_linked_backend(GpuBackend *b, void *get_device_count, void *log_set) {
    memset(b, 0, sizeof(*b));
    b->desc = &TEST_DESC;
    b->lib_handle = NULL; // pretend "loaded" without a real dlopen handle
    b->backend_init = SENTINEL;
    b->backend_reg = SENTINEL;
    b->get_device_count = get_device_count;
    b->get_device_description = SENTINEL;
    b->log_set = log_set;
}

static bool is_unlinked(const GpuBackend *b) {
    return b->lib_handle == NULL && b->backend_init == NULL && b->backend_reg == NULL &&
           b->get_device_count == NULL && b->get_device_description == NULL &&
           b->log_set == NULL;
}

static void test_probe_accepts_when_devices_present(void) {
    FLAG_verbose = 1; // skip suppression branch
    GpuBackend b;
    init_linked_backend(&b, (void *)dc_two, (void *)log_set_spy);
    CHECK(gpu_backend_probe(&b) == true);
    CHECK(b.backend_init == SENTINEL);       // still linked
    CHECK(b.get_device_count == (void *)dc_two);
}

static void test_probe_rejects_and_unlinks_when_zero_devices(void) {
    FLAG_verbose = 1;
    GpuBackend b;
    init_linked_backend(&b, (void *)dc_zero, (void *)log_set_spy);
    CHECK(gpu_backend_probe(&b) == false);
    CHECK(is_unlinked(&b));
    CHECK(b.desc == &TEST_DESC); // identity is preserved across unlink
}

static void test_probe_rejects_on_negative_count(void) {
    FLAG_verbose = 1;
    GpuBackend b;
    init_linked_backend(&b, (void *)dc_negative, (void *)log_set_spy);
    CHECK(gpu_backend_probe(&b) == false);
    CHECK(is_unlinked(&b));
}

static void test_probe_rejects_when_device_count_symbol_absent(void) {
    FLAG_verbose = 1;
    GpuBackend b;
    init_linked_backend(&b, /*get_device_count=*/NULL, (void *)log_set_spy);
    CHECK(gpu_backend_probe(&b) == false);
    CHECK(is_unlinked(&b));
}

static void test_probe_log_suppression_respects_verbose(void) {
    g_log_set_calls = 0;
    FLAG_verbose = 0;
    GpuBackend quiet;
    init_linked_backend(&quiet, (void *)dc_two, (void *)log_set_spy);
    gpu_backend_probe(&quiet);
    CHECK(g_log_set_calls == 1); // suppression installed

    g_log_set_calls = 0;
    FLAG_verbose = 1;
    GpuBackend loud;
    init_linked_backend(&loud, (void *)dc_two, (void *)log_set_spy);
    gpu_backend_probe(&loud);
    CHECK(g_log_set_calls == 0); // left alone
}

static void test_probe_survives_segv_in_device_count(void) {
    FLAG_verbose = 1;
    GpuBackend b;
    init_linked_backend(&b, (void *)dc_segv, (void *)log_set_spy);
    CHECK(gpu_backend_probe(&b) == false);
    CHECK(is_unlinked(&b));
}

static void test_probe_survives_abort_in_device_count(void) {
    FLAG_verbose = 1;
    GpuBackend b;
    init_linked_backend(&b, (void *)dc_abort, (void *)log_set_spy);
    CHECK(gpu_backend_probe(&b) == false);
    CHECK(is_unlinked(&b));
}

static void test_probe_works_after_guarded_fault(void) {
    FLAG_verbose = 1;
    GpuBackend crashed;
    init_linked_backend(&crashed, (void *)dc_segv, (void *)log_set_spy);
    gpu_backend_probe(&crashed); // faults, handled

    GpuBackend good;
    init_linked_backend(&good, (void *)dc_two, (void *)log_set_spy);
    CHECK(gpu_backend_probe(&good) == true);
}

static void test_register_forwards_non_null_reg(void) {
    g_last_registered = (ggml_backend_reg_t)-1;
    GpuBackend b;
    init_linked_backend(&b, (void *)dc_two, (void *)log_set_spy);
    b.backend_reg = (void *)reg_ok;
    gpu_backend_register(&b);
    CHECK(g_last_registered == g_fake_reg);
}

static void test_register_skips_null_reg(void) {
    g_last_registered = (ggml_backend_reg_t)-1;
    GpuBackend b;
    init_linked_backend(&b, (void *)dc_two, (void *)log_set_spy);
    b.backend_reg = (void *)reg_null;
    gpu_backend_register(&b);
    CHECK(g_last_registered == (ggml_backend_reg_t)-1); // never called
}

static void test_call_helpers_tolerate_null(void) {
    char buf[32] = "untouched";
    CHECK(gpu_call_reg(NULL) == NULL);
    CHECK(gpu_call_device_count(NULL) == 0);
    gpu_call_get_description(NULL, 0, buf, sizeof(buf)); // must not crash/modify
    CHECK(strcmp(buf, "untouched") == 0);
    gpu_call_log_set(NULL, llamafile_log_callback_null, NULL); // must not crash
    CHECK(gpu_call_device_count((void *)dc_two) == 2);         // and dispatches when set
}

int main(void) {
    test_probe_accepts_when_devices_present();
    test_probe_rejects_and_unlinks_when_zero_devices();
    test_probe_rejects_on_negative_count();
    test_probe_rejects_when_device_count_symbol_absent();
    test_probe_log_suppression_respects_verbose();
    test_probe_survives_segv_in_device_count();
    test_probe_survives_abort_in_device_count();
    test_probe_works_after_guarded_fault();
    test_register_forwards_non_null_reg();
    test_register_skips_null_reg();
    test_call_helpers_tolerate_null();

    if (g_failures) {
        fprintf(stderr, "gpu_backend_test: %d/%d checks FAILED\n", g_failures, g_checks);
        return 1;
    }
    printf("gpu_backend_test: all %d checks PASSED\n", g_checks);
    return 0;
}

bool llamafile_fa_vec_dot_f16_amd_avx512f(int n, float *s,
                                           const void *vx, const void *vy) {
    const ggml_fp16_t *x = (const ggml_fp16_t *)vx;
    const ggml_fp16_t *y = (const ggml_fp16_t *)vy;
    __m512 acc0 = _mm512_setzero_ps();
    __m512 acc1 = _mm512_setzero_ps();
    int i = 0;
    // Unrolled by 2: 32 f16 elements per iteration.
    for (; i + 32 <= n; i += 32) {
        __m512 xv0 = _mm512_cvtph_ps(_mm256_loadu_si256((const __m256i *)(x + i)));
        __m512 yv0 = _mm512_cvtph_ps(_mm256_loadu_si256((const __m256i *)(y + i)));
        __m512 xv1 = _mm512_cvtph_ps(_mm256_loadu_si256((const __m256i *)(x + i + 16)));
        __m512 yv1 = _mm512_cvtph_ps(_mm256_loadu_si256((const __m256i *)(y + i + 16)));
        acc0 = _mm512_fmadd_ps(xv0, yv0, acc0);
        acc1 = _mm512_fmadd_ps(xv1, yv1, acc1);
    }
    acc0 = _mm512_add_ps(acc0, acc1);
    for (; i + 16 <= n; i += 16) {
        __m512 xv = _mm512_cvtph_ps(_mm256_loadu_si256((const __m256i *)(x + i)));
        __m512 yv = _mm512_cvtph_ps(_mm256_loadu_si256((const __m256i *)(y + i)));
        acc0 = _mm512_fmadd_ps(xv, yv, acc0);
    }
    float sum = _mm512_reduce_add_ps(acc0);
    for (; i < n; ++i) {
        sum += GGML_COMPUTE_FP16_TO_FP32(x[i]) * GGML_COMPUTE_FP16_TO_FP32(y[i]);
    }
    *s = sum;
    return true;
}

bool llamafile_fa_fp16_to_fp32_row_amd_avx512f(const void *vx, float *y,
                                                int64_t n) {
    const ggml_fp16_t *x = (const ggml_fp16_t *)vx;
    int64_t i = 0;
    for (; i + 16 <= n; i += 16) {
        __m512 v = _mm512_cvtph_ps(_mm256_loadu_si256((const __m256i *)(x + i)));
        _mm512_storeu_ps(y + i, v);
    }
    for (; i < n; ++i) {
        y[i] = GGML_COMPUTE_FP16_TO_FP32(x[i]);
    }
    return true;
}

ol llamafile_fa_simd_gemm_amd_avx512f(float *C, const float *A,
                                                    const float *B,
                                                    int M, int K, int N) {
    // Computes C[M x N] += A[M x K] * B[K x N]. simd_gemm in
    // simd-gemm.h is a header-static template; compiling this TU with
    // -Xx86_64-mavx512f gives the included simd_gemm the AVX-512
    // codegen we want.
    simd_gemm(C, A, B, M, K, N);
    return true;
}

atic void fill_random_f16(std::vector<ggml_fp16_t> &out, uint64_t seed) {
    std::mt19937_64 rng(seed);
    std::normal_distribution<float> dist(0.0f, 0.1f);
    for (auto &v : out) {
        v = ggml_fp32_to_fp16(dist(rng));
    }
}

atic float vec_dot_tol(int n, const std::vector<ggml_fp16_t> &x,
                          const std::vector<ggml_fp16_t> &y) {
    float max_abs = 0.0f;
    for (int i = 0; i < n; ++i) {
        float xv = ggml_fp16_to_fp32(x[i]);
        float yv = ggml_fp16_to_fp32(y[i]);
        max_abs = std::max(max_abs, std::fabs(xv) * std::fabs(yv));
    }
    return std::max(1e-5f, 8.0f * (float)n * FLT_EPSILON * max_abs);
}

ST(fp16_to_fp32_row_normal_inputs) {
    for (int n : kTestSizes) {
        std::vector<ggml_fp16_t> input(n);
        std::vector<float> ref_out(n), our_out(n);
        fill_random_f16(input, /*seed=*/0xDEADBEEFCAFEull ^ (uint64_t)n);

        ggml_fp16_to_fp32_row(input.data(), ref_out.data(), n);
        bool handled = llamafile_fa_fp16_to_fp32_row(input.data(), our_out.data(), n);

        if (!handled) {
            skip_count++;
            continue;
        }

        char msg[128];
        for (int i = 0; i < n; ++i) {
            snprintf(msg, sizeof(msg),
                     "fp16_to_fp32_row n=%d i=%d (normal inputs)", n, i);
            ASSERT_BITEQ_F32(ref_out[i], our_out[i], msg);
        }
    }
}

ST(fp16_to_fp32_row_edge_values) {
    // Include ±0, ±INF, denormals, NaN, and the f16 min/max.
    std::vector<ggml_fp16_t> input = {
        ggml_fp32_to_fp16( 0.0f),
        ggml_fp32_to_fp16(-0.0f),
        ggml_fp32_to_fp16( INFINITY),
        ggml_fp32_to_fp16(-INFINITY),
        ggml_fp32_to_fp16(NAN),
        ggml_fp32_to_fp16( 65504.0f),   // f16 max finite
        ggml_fp32_to_fp16(-65504.0f),   // f16 min finite
        ggml_fp32_to_fp16( 6.10e-5f),   // f16 smallest normal
        ggml_fp32_to_fp16( 5.96e-8f),   // f16 smallest denormal
        ggml_fp32_to_fp16( 1.0f),
        ggml_fp32_to_fp16(-1.0f),
        ggml_fp32_to_fp16( 0.5f),
        ggml_fp32_to_fp16( 0.125f),
        ggml_fp32_to_fp16( 0.0625f),
        ggml_fp32_to_fp16( 0.00390625f),
        ggml_fp32_to_fp16( 65000.0f),
    };
    int n = (int)input.size();
    std::vector<float> ref_out(n), our_out(n);

    ggml_fp16_to_fp32_row(input.data(), ref_out.data(), n);
    bool handled = llamafile_fa_fp16_to_fp32_row(input.data(), our_out.data(), n);

    if (!handled) {
        skip_count++;
        return;
    }

    char msg[128];
    for (int i = 0; i < n; ++i) {
        // For NaN, only assert both are NaN (any NaN representation is OK).
        if (std::isnan(ref_out[i]) || std::isnan(our_out[i])) {
            test_count++;
            if (!(std::isnan(ref_out[i]) && std::isnan(our_out[i]))) {
                fprintf(stderr,
                        "FAIL: fp16_to_fp32_row edge values i=%d: "
                        "NaN mismatch (ref nan=%d, our nan=%d)\n",
                        i, std::isnan(ref_out[i]), std::isnan(our_out[i]));
                fail_count++;
            }
            continue;
        }
        snprintf(msg, sizeof(msg),
                 "fp16_to_fp32_row edge values i=%d", i);
        ASSERT_BITEQ_F32(ref_out[i], our_out[i], msg);
    }
}

