(vec_dot_f16_normal_inputs) {
    for (int n : kTestSizes) {
        std::vector<ggml_fp16_t> x(n), y(n);
        fill_random_f16(x, /*seed=*/0xA5A5A5A5A5A5A5A5ull ^ (uint64_t)n);
        fill_random_f16(y, /*seed=*/0x5A5A5A5A5A5A5A5Aull ^ (uint64_t)n);

        float ref = 0.0f, our = 0.0f;
        ggml_vec_dot_f16(n, &ref, /*bs=*/0, x.data(), /*bx=*/0,
                          y.data(), /*by=*/0, /*nrc=*/1);
        bool handled = llamafile_fa_vec_dot_f16(n, &our, x.data(), y.data());

        if (!handled) {
            skip_count++;
            continue;
        }

        char msg[128];
        snprintf(msg, sizeof(msg),
                 "vec_dot_f16 n=%d (normal inputs)", n);
        ASSERT_NEAR_F32(ref, our, vec_dot_tol(n, x, y), msg);
    }
}

TE

(vec_dot_f16_adversarial_reduction_order) {
    // To actually stress reduction-order sensitivity, the per-element
    // products x[i]*y[i] must alternate sign — otherwise SIMD width
    // doesn't change the result. Use a scale of 10 so |product| = 100
    // (well within f16 range): partial sums oscillate by ±100 across
    // steps, and AVX2 (8-wide) vs AVX-512 (16-wide) reduction trees
    // pair the cancelling terms in different orders, amplifying any
    // floating-point drift.
    //   x[i] = (i & 1) ? -10 : +10                 → [+, -, +, -, ...]
    //   y[i] = ((i / 2) & 1) ? -10 : +10           → [+, +, -, -, ...]
    //   products = x[i]*y[i] alternate as          [+, -, -, +, +, -, -, +, ...]
    for (int n : kTestSizes) {
        if (n < 2) continue;
        std::vector<ggml_fp16_t> x(n), y(n);
        const float scale = 10.0f;
        for (int i = 0; i < n; ++i) {
            x[i] = ggml_fp32_to_fp16((i & 1)        ? -scale : scale);
            y[i] = ggml_fp32_to_fp16(((i / 2) & 1) ? -scale : scale);
        }

        float ref = 0.0f, our = 0.0f;
        ggml_vec_dot_f16(n, &ref, 0, x.data(), 0, y.data(), 0, 1);
        bool handled = llamafile_fa_vec_dot_f16(n, &our, x.data(), y.data());

        if (!handled) {
            skip_count++;
            continue;
        }

        // Worst-case drift bound: ~n * eps * max_partial_sum_scale.
        // max |x[i]*y[i]| = scale^2 = 100. Use 4 * n * eps * 100 with
        // a small absolute floor for tiny n.
        float tol = std::max(1e-4f, 4.0f * (float)n * FLT_EPSILON * scale * scale);
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "vec_dot_f16 n=%d (adversarial alternating-sign products)", n);
        ASSERT_NEAR_F32(ref, our, tol, msg);
    }
}

TEST(vec_

t_f16_zeros) {
    // All-zero inputs: result must be exactly 0.0f, bit-identical.
    for (int n : kTestSizes) {
        std::vector<ggml_fp16_t> x(n, ggml_fp32_to_fp16(0.0f));
        std::vector<ggml_fp16_t> y(n, ggml_fp32_to_fp16(0.0f));

        float ref = 999.0f, our = 999.0f;
        ggml_vec_dot_f16(n, &ref, 0, x.data(), 0, y.data(), 0, 1);
        bool handled = llamafile_fa_vec_dot_f16(n, &our, x.data(), y.data());

        if (!handled) {
            skip_count++;
            continue;
        }

        float zero = 0.0f;
        char msg[128];
        snprintf(msg, sizeof(msg), "vec_dot_f16 n=%d (zeros) ref", n);
        ASSERT_BITEQ_F32(zero, ref, msg);
        snprintf(msg, sizeof(msg), "vec_dot_f16 n=%d (zeros) ours", n);
        ASSERT_BITEQ_F32(zero, our, msg);
    }
}

TEST(disp

ch_wiring) {
    // Sanity check: regardless of whether the AVX-512F variant is
    // available, the wrapper must return without crashing for trivial
    // input. If our dispatch table got mis-wired (e.g., function pointer
    // to wrong arch), this would catch it.
    std::vector<ggml_fp16_t> tiny = {
        ggml_fp32_to_fp16(0.5f), ggml_fp32_to_fp16(-0.25f),
        ggml_fp32_to_fp16(1.0f), ggml_fp32_to_fp16( 0.125f),
    };
    float dot = -1.0f;
    bool dot_handled = llamafile_fa_vec_dot_f16((int)tiny.size(), &dot,
                                                  tiny.data(), tiny.data());
    ASSERT_TRUE(dot_handled || dot == -1.0f,
                "vec_dot_f16: if not handled, output must be untouched");

    std::vector<float> out(tiny.size(), -999.0f);
    bool conv_handled = llamafile_fa_fp16_to_fp32_row(tiny.data(), out.data(),
                                                       (int64_t)tiny.size());
    ASSERT_TRUE(conv_handled || out[0] == -999.0f,
                "fp16_to_fp32_row: if not handled, output must be untouched");
}

// ======

scalar_gemm_reference(float *C, const float *A, const float *B,
                                   int M, int K, int N) {
    for (int i = 0; i < M; ++i) {
        for (int j = 0; j < N; ++j) {
            float acc = C[i * N + j];
            for (int k = 0; k < K; ++k) {
                acc += A[i * K + k] * B[k * N + j];
            }
            C[i * N + j] = acc;
        }
    }
}

static fl

t gemm_tol(int K, float scale) {
    return std::max(1e-4f, 8.0f * (float)K * FLT_EPSILON * scale * scale);
}

static vo

fill_random_f32(std::vector<float> &v, uint64_t seed,
                             float stddev = 0.1f) {
    std::mt19937_64 rng(seed);
    std::normal_distribution<float> dist(0.0f, stddev);
    for (auto &x : v) x = dist(rng);
}

TEST(simd

emm_typical_fa_tile_shapes) {
    // Shapes that match the FA tile dispatch in ops.cpp's tiled function
    // (Q_TILE_SZ x KV_TILE_SZ for the KQ matmul, Q_TILE_SZ x DV for the
    // VKQ accumulation). Common head dims: 64, 80, 96, 128. Common tile
    // sizes from ggml_fa_tile_config: 4-16 Q rows, 32-128 KV columns.
    struct Shape { int M, K, N; const char *label; };
    Shape shapes[] = {
        {  4, 128,  64, "KQ: Q4 x DK128 x KV64" },
        {  8, 128,  64, "KQ: Q8 x DK128 x KV64" },
        { 16, 128, 128, "KQ: Q16 x DK128 x KV128" },
        {  4,  64, 128, "VKQ: Q4 x KV64 x DV128" },
        {  8,  64, 128, "VKQ: Q8 x KV64 x DV128" },
        { 16, 128, 128, "VKQ: Q16 x KV128 x DV128" },
        {  4,  96,  80, "odd: Q4 x 96 x 80" },
        { 16,  64,  32, "narrow: Q16 x 64 x 32" },
    };
    for (auto &s : shapes) {
        std::vector<float> A(s.M * s.K), B(s.K * s.N);
        std::vector<float> C_ref(s.M * s.N), C_our(s.M * s.N);
        uint64_t seed = 0xC0FFEEull ^ (uint64_t)(s.M * 31 + s.K * 17 + s.N);
        fill_random_f32(A, seed);
        fill_random_f32(B, seed ^ 0xDEADBEEFull);
        // Pre-fill C with random values to test the += accumulation.
        fill_random_f32(C_ref, seed ^ 0xFACEFEEDull);
        C_our = C_ref;

        scalar_gemm_reference(C_ref.data(), A.data(), B.data(),
                              s.M, s.K, s.N);
        bool handled = llamafile_fa_simd_gemm(C_our.data(), A.data(),
                                               B.data(), s.M, s.K, s.N);

        if (!handled) {
            skip_count++;
            continue;
        }

        char msg[160];
        float tol = gemm_tol(s.K, 0.5f);  // stddev 0.1 → max |a|*|b| ~ 0.5
        for (int i = 0; i < s.M; ++i) {
            for (int j = 0; j < s.N; ++j) {
                snprintf(msg, sizeof(msg),
                         "simd_gemm %s i=%d j=%d", s.label, i, j);
                ASSERT_NEAR_F32(C_ref[i * s.N + j], C_our[i * s.N + j], tol, msg);
            }
        }
    }
}

TEST(simd_g

m_zero_accumulator) {
    // Start from C=0 so the result is purely A*B (no += round-off).
    // Verifies the kernel handles a zero starting accumulator correctly.
    int M = 8, K = 128, N = 128;
    std::vector<float> A(M * K), B(K * N);
    std::vector<float> C_ref(M * N, 0.0f), C_our(M * N, 0.0f);
    fill_random_f32(A, 0x1234);
    fill_random_f32(B, 0x5678);

    scalar_gemm_reference(C_ref.data(), A.data(), B.data(), M, K, N);
    bool handled = llamafile_fa_simd_gemm(C_our.data(), A.data(), B.data(),
                                           M, K, N);
    if (!handled) {
        skip_count++;
        return;
    }
    char msg[160];
    float tol = gemm_tol(K, 0.5f);
    for (int i = 0; i < M; ++i) {
        for (int j = 0; j < N; ++j) {
            snprintf(msg, sizeof(msg),
                     "simd_gemm zero-acc i=%d j=%d", i, j);
            ASSERT_NEAR_F32(C_ref[i * N + j], C_our[i * N + j], tol, msg);
        }
    }
}

TEST(simd_g

m_dispatch_wiring) {
    int M = 4, K = 16, N = 32;
    std::vector<float> A(M * K, 1.0f), B(K * N, 1.0f);
    std::vector<float> C(M * N, -777.0f);
    bool handled = llamafile_fa_simd_gemm(C.data(), A.data(), B.data(),
                                           M, K, N);
    ASSERT_TRUE(handled || C[0] == -777.0f,
                "simd_gemm: if not handled, output must be untouched");
    if (handled) {
        // Each C[i,j] = -777 + sum_k(1 * 1) = -777 + K = -761
        for (int i = 0; i < M; ++i) {
            for (int j = 0; j < N; ++j) {
                test_count++;
                float expected = -777.0f + (float)K;
                if (fabsf(C[i * N + j] - expected) > 1e-5f) {
                    fprintf(stderr, "FAIL: simd_gemm dispatch i=%d j=%d "
                            "expected %.3f got %.3f\n",
                            i, j, expected, C[i * N + j]);
                    fail_count++;
                }
            }
        }
    }
}

// ggml's f

t_ggml_tables() {
    for (int i = 0; i < (1 << 16); ++i) {
        ggml_fp16_t f16 = (ggml_fp16_t)(uint16_t)i;
        ggml_table_f32_f16[i] = ggml_fp16_to_fp32(f16);
    }
}

int main(int

gc, char *argv[]) {
    (void)argc;
    (void)argv;

    // Must happen before any test runs ggml_vec_dot_f16.
    init_ggml_tables();

    fprintf(stderr, "Running fa_helpers tests (issue #975) — %d tests registered\n",
            g_test_count_registered);

    for (int i = 0; i < g_test_count_registered; ++i) {
        fprintf(stderr, "  [%d/%d] %s\n", i + 1, g_test_count_registered,
                g_tests[i].name);
        g_tests[i].fn();
    }

    if (fail_count > 0) {
        fprintf(stderr, "\n%d/%d assertions FAILED (%d skipped — CPU "
                "doesn't have the optimized variant)\n",
                fail_count, test_count, skip_count);
        return 1;
    }

    fprintf(stderr, "All %d assertions PASSED (%d skipped — CPU doesn't "
            "have the optimized variant)\n",
            test_count, skip_count);
    return 0;
}

const char *llamafile_get_dso_extension(void) {
    if (IsWindows())
        return "dll";
    else if (IsXnu())
        return "dylib";
    else
        return "so";
}

int llamafile_makedirs(const char *path, int mode) {
    char tmp[PATH_MAX];
    char *p = NULL;
    size_t len;

    snprintf(tmp, sizeof(tmp), "%s", path);
    len = strlen(tmp);

    if (tmp[len - 1] == '/')
        tmp[len - 1] = '\0';

    if (mkdir(tmp, mode) == 0)
        return 0;

    if (errno == EEXIST) {
        struct stat st;
        if (stat(tmp, &st) == 0 && S_ISDIR(st.st_mode))
            return 0;
        return -1;
    }

    if (errno != ENOENT)
        return -1;

    for (p = tmp + 1; *p; p++) {
        if (*p == '/') {
            *p = '\0';
            if (mkdir(tmp, mode) != 0 && errno != EEXIST)
                return -1;
            *p = '/';
        }
    }

    return mkdir(tmp, mode);
}

bool llamafile_try_load_prebuilt_dso(const char *name, const char *backend_name,
                                     llamafile_link_dso_fn link_fn) {
    char dso[PATH_MAX];
    char app_dir[PATH_MAX];

    // Try loading from /zip/ (bundled in executable)
    snprintf(dso, PATH_MAX, "/zip/%s", name);
    if (llamafile_file_exists(dso)) {
        // Extract to app dir first (cosmo_dlopen can't load from /zip/)
        llamafile_get_app_dir(app_dir, PATH_MAX);
        if (llamafile_makedirs(app_dir, 0755) != 0) {
            perror(app_dir);
            return false;
        }
        char extracted[PATH_MAX];
        if (snprintf(extracted, PATH_MAX, "%s%s", app_dir, name) >= PATH_MAX) {
            fprintf(stderr, "%s: path too long: %s%s\n", backend_name, app_dir, name);
            return false;
        }
        // Check if extraction needed
        switch (llamafile_is_file_newer_than(dso, extracted)) {
        case -1:
            return false;
        case 0:
            // Already extracted and up to date
            break;
        case 1:
            if (!llamafile_extract(dso, extracted)) {
                return false;
            }
            break;
        }

        if (link_fn(extracted)) {
            if (FLAG_verbose)
                fprintf(stderr, "%s: loaded bundled %s\n", backend_name, name);
            return true;
        }
    }

    // Try loading from app directory
    llamafile_get_app_dir(app_dir, PATH_MAX);
    snprintf(dso, PATH_MAX, "%s%s", app_dir, name);
    if (llamafile_file_exists(dso)) {
        if (link_fn(dso)) {
            if (FLAG_verbose)
                fprintf(stderr, "%s: loaded %s from app directory\n", backend_name, name);
            return true;
        }
    }

    // Try loading from home directory (common build location)
    const char *home = getenv("HOME");
    if (home && *home) {
        snprintf(dso, PATH_MAX, "%s/%s", home, name);
        if (llamafile_file_exists(dso)) {
            if (link_fn(dso)) {
                if (FLAG_verbose)
                    fprintf(stderr, "%s: loaded %s from home directory\n", backend_name, name);
                return true;
            }
        }
    }

    return false;
}

static bool LinkVulkan(const char *dso) {
    // Load dynamic shared object using Cosmopolitan's dlopen
    void *lib = cosmo_dlopen(dso, RTLD_LAZY);
    if (!lib) {
        char *err = cosmo_dlerror();
        fprintf(stderr, "vulkan: %s: failed to load library\n", err ? err : "unknown error");
        return false;
    }

    // Import functions
    bool ok = true;

    *(void **)(&g_vulkan.backend_init) = cosmo_dlsym(lib, "ggml_backend_vk_init");
    ok &= (g_vulkan.backend_init != NULL);

    *(void **)(&g_vulkan.backend_reg) = cosmo_dlsym(lib, "ggml_backend_vk_reg");
    ok &= (g_vulkan.backend_reg != NULL);

    *(void **)(&g_vulkan.get_device_count) = cosmo_dlsym(lib, "ggml_backend_vk_get_device_count");
    // Optional - don't fail if not found

    *(void **)(&g_vulkan.get_device_description) = cosmo_dlsym(lib, "ggml_backend_vk_get_device_description");
    // Optional - don't fail if not found

    // Import logging control (optional)
    *(void **)(&g_vulkan.log_set) = cosmo_dlsym(lib, "ggml_log_set");

    if (!ok) {
        char *err = cosmo_dlerror();
        fprintf(stderr, "vulkan: %s: not all symbols could be imported\n", err ? err : "unknown error");
        g_vulkan.backend_init = NULL;
        g_vulkan.backend_reg = NULL;
        g_vulkan.get_device_count = NULL;
        g_vulkan.get_device_description = NULL;
        g_vulkan.log_set = NULL;
        cosmo_dlclose(lib);
        return false;
    }

    g_vulkan.lib_handle = lib;
    return true;
}

static bool ImportVulkanImpl(void) {
    // Note: Unlike CUDA, we don't skip Apple Silicon here because
    // Vulkan works on macOS via MoltenVK (Vulkan-to-Metal translation)

    // Check if we're allowed to even try
    switch (FLAG_gpu) {
    case LLAMAFILE_GPU_AUTO:
    case LLAMAFILE_GPU_VULKAN:
        break;
    default:
        return false;
    }

    // Determine DSO name
    const char *ext = llamafile_get_dso_extension();
    char vulkan_dso[64];
    snprintf(vulkan_dso, sizeof(vulkan_dso), "ggml-vulkan.%s", ext);

    // Try to load pre-built DSO
    if (!llamafile_try_load_prebuilt_dso(vulkan_dso, "vulkan", LinkVulkan)) {
        // No pre-built DSO found
        if (FLAG_verbose) {
            fprintf(stderr, "vulkan: no pre-built GPU library found\n");
            fprintf(stderr, "vulkan: to enable Vulkan support, build with:\n");
            fprintf(stderr, "vulkan:   llamafile/vulkan.sh\n");
        }
        return false;
    }

    // Register the Vulkan backend with GGML
    if (g_vulkan.backend_reg) {
        ggml_backend_reg_t reg = g_vulkan.backend_reg();
        if (reg) {
            ggml_backend_register(reg);
            if (FLAG_verbose)
                fprintf(stderr, "vulkan: Vulkan backend registered with GGML\n");
        }
    }

    return true;
}

static void ImportVulkan(void) {
    if (ImportVulkanImpl()) {
        g_vulkan.supported = true;
        if (FLAG_verbose) {
            fprintf(stderr, "vulkan: Vulkan GPU support successfully loaded\n");
            if (g_vulkan.get_device_count) {
                int count = g_vulkan.get_device_count();
                fprintf(stderr, "vulkan: found %d GPU device(s)\n", count);
            }
        }
    } else if (FLAG_gpu == LLAMAFILE_GPU_VULKAN) {
        fprintf(stderr, "fatal error: support for --gpu vulkan was explicitly requested, "
                "but it wasn't available\n");
        exit(1);
    }
}

ggml_backend_t ggml_backend_vk_init(size_t device) {
    if (!llamafile_has_vulkan())
        return NULL;
    if (!g_vulkan.backend_init)
        return NULL;
    return g_vulkan.backend_init(device);
}

int ggml_backend_vk_get_device_count(void) {
    if (!llamafile_has_vulkan())
        return 0;
    if (!g_vulkan.get_device_count)
        return 0;
    return g_vulkan.get_device_count();
}

void ggml_backend_vk_get_device_description(int device, char *description, size_t description_size) {
    if (!llamafile_has_vulkan()) {
        if (description_size > 0)
            description[0] = '\0';
        return;
    }
    if (!g_vulkan.get_device_description) {
        if (description_size > 0)
            snprintf(description, description_size, "Vulkan GPU %d", device);
        return;
    }
    g_vulkan.get_device_description(device, description, description_size);
}

void llamafile_vulkan_log_set(llamafile_log_callback log_callback, void *user_data) {
    if (!llamafile_has_vulkan())
        return;
    if (g_vulkan.log_set)
        g_vulkan.log_set(log_callback, user_data);
}

static bool is_llamafile_flag(const char* arg) {
    return strcmp(arg, "--server") == 0 ||
           strcmp(arg, "--chat") == 0 ||
           strcmp(arg, "--cli") == 0 ||
           strcmp(arg, "--gpu") == 0 ||
           strcmp(arg, "--ascii") == 0 ||
           strcmp(arg, "--nologo") == 0 ||
           strcmp(arg, "--nothink") == 0 ||
           strcmp(arg, "--version") == 0;
}

LlamafileArgs parse_llamafile_args(int argc, char** argv) {
    LlamafileArgs args;

    // Early GPU init must happen before we filter args
    // This reads --gpu and -ngl flags to set FLAG_gpu
    llamafile_early_gpu_init(argv);

    // Capture -p/--prompt value before filtering (needed for combined mode
    // where SERVER parsing excludes -p)
    // Note: Loop does not break early; if multiple -p flags are given,
    // the last occurrence wins (intentional for override flexibility)
    for (int i = 0; i < argc; ++i) {
        if ((strcmp(argv[i], "-p") == 0 || strcmp(argv[i], "--prompt") == 0) && i + 1 < argc) {
            args.system_prompt = argv[i + 1];
        }
        if ((strcmp(argv[i], "-m") == 0 || strcmp(argv[i], "--model") == 0) && i + 1 < argc) {
            args.model_path = argv[i + 1];
        }
    }

    // Determine execution mode from flags
    // Priority: explicit flags override defaults
    if (llamafile_has(argv, "--server")) {
        args.mode = ProgramMode::SERVER;
    } else if (llamafile_has(argv, "--chat")) {
        args.mode = ProgramMode::CHAT;
    } else if (llamafile_has(argv, "--cli")) {
        args.mode = ProgramMode::CLI;
    } else {
        // AUTO mode: will run combined chat + server
        args.mode = ProgramMode::AUTO;
    }

    // Check verbose flag
    FLAG_verbose = llamafile_has(argv, "--verbose") ? 1 : 0;

    // Check --nothink flag (filters thinking/reasoning content in CLI mode)
    FLAG_nothink = llamafile_has(argv, "--nothink");

    // Check logo flags
    FLAG_nologo = llamafile_has(argv, "--nologo");
    FLAG_ascii = llamafile_has(argv, "--ascii");

    // Filter out llamafile-specific arguments
    // These are not recognized by llama.cpp and would cause errors
    g_filtered_argv.clear();

    for (int i = 0; i < argc; ++i) {
        const char* arg = argv[i];

        // Skip llamafile-specific flags
        if (is_llamafile_flag(arg)) {
            // --gpu takes a value argument, skip it too
            if (strcmp(arg, "--gpu") == 0 && i + 1 < argc) {
                ++i;
            }
            continue;
        }

        // Keep this argument
        g_filtered_argv.push_back(argv[i]);
    }

    // Null-terminate argv array (required by convention)
    g_filtered_argv.push_back(nullptr);

    args.llama_argc = static_cast<int>(g_filtered_argv.size()) - 1;
    args.llama_argv = g_filtered_argv.data();

    return args;
}

explicit ApiBackend(const std::string &server_url)
        : server_url_(server_url) {
        // Parse host and port from URL
        // Expected format: http://host:port
        std::string url = server_url;
        if (url.substr(0, 7) == "http://")
            url = url.substr(7);
        auto colon = url.find(':');
        if (colon != std::string::npos) {
            host_ = url.substr(0, colon);
            port_ = std::stoi(url.substr(colon + 1));
        } else {
            host_ = url;
            port_ = 8080;
        }
    }

static json build_content(const std::string &text) {
        // Look for data:image/ URIs
        static const std::string prefix = "data:image/";
        auto pos = text.find(prefix);
        if (pos == std::string::npos) {
            return text;  // plain string, no images
        }

        // Split text into text parts and image_url parts
        json parts = json::array();
        size_t last = 0;

        while (pos != std::string::npos) {
            // Add preceding text
            if (pos > last) {
                std::string before = text.substr(last, pos - last);
                if (!before.empty())
                    parts.push_back({{"type", "text"}, {"text", before}});
            }

            // Find end of data URI (terminated by whitespace, quote, or end of string)
            size_t end = pos;
            while (end < text.size() && text[end] != ' ' && text[end] != '\n' &&
                   text[end] != '\r' && text[end] != '\t' && text[end] != '"')
                end++;

            std::string uri = text.substr(pos, end - pos);
            parts.push_back({
                {"type", "image_url"},
                {"image_url", {{"url", uri}}}
            });

            last = end;
            pos = text.find(prefix, last);
        }

        // Add trailing text
        if (last < text.size()) {
            std::string after = text.substr(last);
            if (!after.empty())
                parts.push_back({{"type", "text"}, {"text", after}});
        }

        return parts;
    }

std::string complete(
        const std::vector<common_chat_msg> &messages,
        TokenCallback on_token) override
    {
        // Build request JSON
        json req_json;
        json msgs_json = json::array();
        for (const auto &msg : messages) {
            msgs_json.push_back({
                {"role", msg.role},
                {"content", build_content(msg.content)}
            });
        }
        req_json["messages"] = msgs_json;
        req_json["stream"] = true;
        req_json["stream_options"] = {{"include_usage", true}};

        std::string body = req_json.dump();
        std::string assistant_content;
        std::string sse_buffer;
        bool stopped = false;

        httplib::Client cli(host_, port_);
        cli.set_read_timeout(300);  // 5 minutes for long generations

        auto result = cli.Post(
            "/v1/chat/completions",
            httplib::Headers{},
            body,
            "application/json",
            [&](const char *data, size_t len) -> bool {
                if (stopped)
                    return false;

                sse_buffer.append(data, len);

                // Process complete SSE lines
                size_t pos;
                while ((pos = sse_buffer.find("\n")) != std::string::npos) {
                    std::string line = sse_buffer.substr(0, pos);
                    sse_buffer.erase(0, pos + 1);

                    // Skip empty lines
                    if (line.empty() || line == "\r")
                        continue;

                    // Strip trailing \r
                    if (!line.empty() && line.back() == '\r')
                        line.pop_back();

                    // Only process "data: " lines
                    if (line.substr(0, 6) != "data: ")
                        continue;

                    std::string payload = line.substr(6);

                    // Check for stream end
                    if (payload == "[DONE]")
                        return true;

                    // Parse JSON
                    try {
                        json chunk = json::parse(payload);

                        // Extract usage stats from final chunk
                        if (chunk.contains("usage")) {
                            auto &usage = chunk["usage"];
                            if (usage.contains("prompt_tokens"))
                                last_prompt_tokens_ = usage["prompt_tokens"].get<int>();
                            if (usage.contains("completion_tokens"))
                                last_completion_tokens_ = usage["completion_tokens"].get<int>();
                            if (usage.contains("total_tokens"))
                                total_tokens_ = usage["total_tokens"].get<int>();
                        }

                        if (!chunk.contains("choices") || chunk["choices"].empty())
                            continue;

                        auto &choice = chunk["choices"][0];
                        if (!choice.contains("delta"))
                            continue;

                        auto &delta = choice["delta"];

                        std::string content_delta;
                        std::string reasoning_delta;

                        if (delta.contains("content") && !delta["content"].is_null())
                            content_delta = delta["content"].get<std::string>();

                        if (delta.contains("reasoning_content") && !delta["reasoning_content"].is_null())
                            reasoning_delta = delta["reasoning_content"].get<std::string>();

                        if (!content_delta.empty())
                            assistant_content += content_delta;

                        if (!content_delta.empty() || !reasoning_delta.empty()) {
                            if (!on_token(content_delta, reasoning_delta)) {
                                stopped = true;
                                return false;  // close connection to cancel
                            }
                        }
                    } catch (const json::exception &) {
                        // Skip malformed JSON chunks
                        continue;
                    }
                }
                return true;
            });

        if (!result) {
            err("error: HTTP request failed: %s", httplib::to_string(result.error()).c_str());
        } else if (result->status != 200) {
            err("error: server returned HTTP %d", result->status);
        }

        return assistant_content;
    }

int context_max() override {
        if (context_max_ <= 0)
            fetch_context_max();
        return context_max_;
    }

void print_stats() override {
        printf("prompt tokens: %d\n"
               "completion tokens: %d\n"
               "total tokens: %d\n",
               last_prompt_tokens_, last_completion_tokens_, total_tokens_);
    }

void on_clear() override {
        // Message list is managed by the REPL (g_messages)
        // Just reset our token counters
        last_prompt_tokens_ = 0;
        last_completion_tokens_ = 0;
        total_tokens_ = 0;
    }

void on_push() override {
        message_stack_.push_back(g_messages);
        printf(FAINT "conversation state pushed (depth: %zu)" RESET "\n",
               message_stack_.size());
    }

void on_pop() override {
        if (message_stack_.empty()) {
            err("error: conversation stack is empty");
            return;
        }
        g_messages = message_stack_.back();
        message_stack_.pop_back();
        printf(FAINT "conversation state restored (depth: %zu)" RESET "\n",
               message_stack_.size());
    }

void on_undo() override {
        // Remove last assistant + user message pair
        while (!g_messages.empty() && g_messages.back().role == "assistant")
            g_messages.pop_back();
        if (!g_messages.empty() && g_messages.back().role == "user")
            g_messages.pop_back();
        printf(FAINT "last exchange undone (%zu messages remaining)" RESET "\n",
               g_messages.size());
    }

void on_forget(int n) override {
        // Remove the oldest non-system message pair to free context
        auto it = g_messages.begin();
        while (it != g_messages.end() && it->role == "system")
            ++it;
        if (it == g_messages.end()) {
            err("error: nothing left to forget");
            return;
        }
        // Remove one user+assistant exchange
        auto start = it;
        ++it;  // skip user
        if (it != g_messages.end() && it->role == "assistant")
            ++it;  // skip assistant
        g_messages.erase(start, it);
        printf(FAINT "oldest exchange forgotten (%zu messages remaining)" RESET "\n",
               g_messages.size());
    }

void fetch_context_max() {
        httplib::Client cli(host_, port_);
        cli.set_read_timeout(5);
        auto result = cli.Get("/props");
        if (result && result->status == 200) {
            try {
                json props = json::parse(result->body);
                if (props.contains("default_generation_settings")) {
                    auto &settings = props["default_generation_settings"];
                    if (settings.contains("n_ctx"))
                        context_max_ = settings["n_ctx"].get<int>();
                }
            } catch (const json::exception &) {
            }
        }
    }

atic cli_chat_template_result cli_apply_chat_template_full(llama_model *model,
                                                              common_chat_templates *templates,
                                                              const common_params &params,
                                                              const std::vector<common_chat_msg> &messages,
                                                              bool add_assistant,
                                                              bool enable_thinking) {
    cli_chat_template_result result;

    if (templates) {
        common_chat_templates_inputs inputs;
        inputs.messages = messages;
        inputs.use_jinja = true;
        inputs.add_generation_prompt = add_assistant;
        inputs.enable_thinking = enable_thinking;
        // Set reasoning_format so the PEG parser includes reasoning extraction
        inputs.reasoning_format = COMMON_REASONING_FORMAT_DEEPSEEK;

        auto chat_params = common_chat_templates_apply(templates, inputs);
        result.prompt = chat_params.prompt;

        // Initialize parser params from chat_params
        result.parser_params.format = chat_params.format;
        result.parser_params.thinking_forced_open = chat_params.thinking_forced_open;
        if (!chat_params.parser.empty()) {
            result.parser_params.parser.load(chat_params.parser);
        }
        // Enable reasoning parsing for thinking models
        result.parser_params.reasoning_format = COMMON_REASONING_FORMAT_DEEPSEEK;
        result.parser_params.reasoning_in_content = false;
        return result;
    }

    // Fallback to heuristic-based template (doesn't support enable_thinking)
    const char *tmpl = params.chat_template.empty()
                       ? llama_model_chat_template(model, nullptr)
                       : params.chat_template.c_str();

    // Build llama_chat_message array from messages
    // Note: c_str() pointers remain valid because messages vector is not modified
    // until after llama_chat_apply_template() completes
    std::vector<llama_chat_message> chat;
    for (const auto &msg : messages) {
        chat.push_back({msg.role.c_str(), msg.content.c_str()});
    }

    int len = llama_chat_apply_template(tmpl, chat.data(), chat.size(), add_assistant, nullptr, 0);
    if (len < 0) {
        return result;
    }

    result.prompt.resize(len);
    llama_chat_apply_template(tmpl, chat.data(), chat.size(), add_assistant, &result.prompt[0], result.prompt.size());
    // For fallback, parser_params will be default (COMMON_CHAT_FORMAT_CONTENT_ONLY)
    return result;
}

atic void cleanup(mtmd_context *mtmd_ctx, common_sampler *sampler,
                    llama_context *ctx, llama_model *model) {
    if (mtmd_ctx) mtmd_free(mtmd_ctx);
    if (sampler) common_sampler_free(sampler);
    if (ctx) llama_free(ctx);
    if (model) llama_model_free(model);
}

std::string complete(
        const std::vector<common_chat_msg> &messages,
        TokenCallback on_token) override
    {
        std::string assistant_content;
        const llama_vocab *vocab = llama_model_get_vocab(g_model);

        // Check if we should use chat parsing (for think mode models)
        const bool use_chat_parser =
            g_chat_syntax.format != COMMON_CHAT_FORMAT_CONTENT_ONLY;
        std::string raw_output;
        common_chat_msg prev_msg;

        for (;;) {
            if (g_got_sigint) {
                eval_token(llamafile_token_eot(g_model));
                break;
            }
            llama_token id = common_sampler_sample(g_sampler, g_ctx, -1);
            common_sampler_accept(g_sampler, id, true);
            if (!eval_token(id))
                break;
            if (llama_vocab_is_eog(vocab, id))
                break;

            if (use_chat_parser) {
                std::string token_str = token_to_piece(g_ctx, id, true);
                raw_output += token_str;
                auto msg = common_chat_parse(raw_output, true, g_chat_syntax);
                auto diffs = common_chat_msg_diff::compute_diffs(prev_msg, msg);

                for (const auto &diff : diffs) {
                    std::string content_delta = diff.content_delta;
                    std::string reasoning_delta = diff.reasoning_content_delta;
                    if (!content_delta.empty())
                        assistant_content += content_delta;
                    if (!content_delta.empty() || !reasoning_delta.empty()) {
                        if (!on_token(content_delta, reasoning_delta))
                            goto done;
                    }
                }
                prev_msg = msg;
            } else {
                std::string token_str = token_to_piece(g_ctx, id, g_params->special);
                assistant_content += token_str;
                if (!on_token(token_str, ""))
                    goto done;
            }
        }
    done:
        return assistant_content;
    }

void print_stats() override {
        FLAG_log_disable = false;
        common_perf_print(g_ctx, g_sampler);
        FLAG_log_disable = true;
    }

static std::string maintain_faint_styling(const std::string &s) {
    std::string result;
    result.reserve(s.size() + 32);
    size_t pos = 0;
    while (pos < s.size()) {
        // Look for \e[0m (RESET)
        if (pos + 3 < s.size() && s[pos] == '\e' && s[pos+1] == '[' && s[pos+2] == '0' && s[pos+3] == 'm') {
            // Replace with \e[0m\e[2m (RESET + FAINT)
            result += "\e[0m\e[2m";
            pos += 4;
        } else {
            result += s[pos++];
        }
    }
    return result;
}

std::string apply_chat_template_with_thinking(
    const std::vector<common_chat_msg> &past_msgs,
    const common_chat_msg &new_msg,
    bool add_generation_prompt) {

    if (!g_chat_templates)
        return "";

    // Check if template supports thinking mode
    bool supports_thinking = common_chat_templates_support_enable_thinking(g_chat_templates.get());

    common_chat_templates_inputs inputs;
    inputs.messages = past_msgs;
    inputs.messages.push_back(new_msg);
    inputs.use_jinja = true;
    inputs.add_generation_prompt = add_generation_prompt;
    inputs.enable_thinking = supports_thinking;
    inputs.reasoning_format = COMMON_REASONING_FORMAT_DEEPSEEK;

    auto chat_params = common_chat_templates_apply(g_chat_templates.get(), inputs);
    return chat_params.prompt;
}

DataUriExtraction extract_data_uris(std::string_view s, const char *marker) {
    DataUriExtraction result;
    result.marker = marker;
    size_t i = 0;
    size_t last_pos = 0;

    while (i < s.size()) {
        // look for the offset where a data URI might start
        size_t pos = s.find("data:", i);
        if (pos == std::string_view::npos)
            break;

        // if "data:" is present, try to parse the following as a URI
        i = pos + 5;
        DataUri uri;
        size_t end = uri.parse(s.substr(pos + 5));
        if (end == std::string_view::npos)
            // not a valid URI
            continue;
        if (!lf::startscasewith(uri.mime, "image/"))
            // not an image mime type
            continue;

        std::string image;
        try {
            image = uri.decode();
        } catch (const base64_error &e) {
            // could not decode the base64 data
            continue;
        }
        if (!is_image(image))
            // not a valid image
            continue;

        // Append text before this data URI
        result.modified_text += s.substr(last_pos, pos - last_pos);

        // Store decoded image data
        result.images.push_back(std::move(image));

        // Add marker where image should go
        result.modified_text += marker;

        // Move past this data URI
        last_pos = i + end;
        i = last_pos;
    }

    // Append any remaining text after the last processed position
    // (handles case where loop exits normally due to invalid trailing data: URIs)
    if (last_pos < s.size())
        result.modified_text += s.substr(last_pos);

    return result;
}

bool llamafile_has(char **a, const char *x) {
    for (int i = 0; a[i]; ++i)
        if (!strcmp(a[i], x))
            return true;
    return false;
}

static const char *llamafile_get_home_dir(void) {
    const char *homedir;
    if (!(homedir = getenv("HOME")) || !*homedir)
        homedir = ".";
    return homedir;
}

void llamafile_get_app_dir(char *path, size_t size) {
    snprintf(path, size, "%s/.llamafile/v/%d.%d.%d/",
             llamafile_get_home_dir(),
             LLAMAFILE_MAJOR,
             LLAMAFILE_MINOR,
             LLAMAFILE_PATCH);
}

static int copy_file_contents(int fdin, int fdout) {
    char buf[8192];
    ssize_t nread;
    while ((nread = read(fdin, buf, sizeof(buf))) > 0) {
        char *ptr = buf;
        while (nread > 0) {
            ssize_t nwritten = write(fdout, ptr, nread);
            if (nwritten < 0) return -1;
            nread -= nwritten;
            ptr += nwritten;
        }
    }
    return nread < 0 ? -1 : 0;
}

bool llamafile_extract(const char *zip, const char *to) {
    int fdin, fdout;
    char stage[PATH_MAX];
    if (FLAG_verbose)
        fprintf(stderr, "extracting %s to %s\n", zip, to);
    strlcpy(stage, to, sizeof(stage));
    if (strlcat(stage, ".XXXXXX", sizeof(stage)) >= sizeof(stage)) {
        errno = ENAMETOOLONG;
        perror(to);
        return false;
    }
    if ((fdout = mkstemp(stage)) == -1) {
        perror(stage);
        return false;
    }
    if ((fdin = open(zip, O_RDONLY | O_CLOEXEC)) == -1) {
        perror(zip);
        close(fdout);
        unlink(stage);
        return false;
    }
    if (copy_file_contents(fdin, fdout) == -1) {
        perror(zip);
        close(fdin);
        close(fdout);
        unlink(stage);
        return false;
    }
    if (close(fdout)) {
        perror(to);
        close(fdin);
        unlink(stage);
        return false;
    }
    if (close(fdin)) {
        perror(zip);
        unlink(stage);
        return false;
    }
    if (rename(stage, to)) {
        perror(to);
        unlink(stage);
        return false;
    }
    return true;
}

static int is_file_newer_than_time(const char *path, const char *other) {
    struct stat st1, st2;
    if (stat(path, &st1)) {
        perror(path);
        return -1;
    }
    if (stat(other, &st2)) {
        if (errno == ENOENT) {
            return true;
        } else {
            perror(other);
            return -1;
        }
    }
    return timespec_cmp(st1.st_mtim, st2.st_mtim) > 0;
}

static int is_file_newer_than_bytes(const char *path, const char *other) {
    int other_fd;
    if ((other_fd = open(other, O_RDONLY | O_CLOEXEC)) == -1) {
        if (errno == ENOENT) {
            return true;
        } else {
            perror(other);
            return -1;
        }
    }
    int path_fd;
    if ((path_fd = open(path, O_RDONLY | O_CLOEXEC)) == -1) {
        perror(path);
        close(other_fd);
        return -1;
    }
    int res;
    off_t i = 0;
    for (;;) {
        char path_buf[512];
        ssize_t path_rc = pread(path_fd, path_buf, sizeof(path_buf), i);
        if (path_rc == -1) {
            perror(path);
            res = -1;
            break;
        }
        char other_buf[512];
        ssize_t other_rc = pread(other_fd, other_buf, sizeof(other_buf), i);
        if (other_rc == -1) {
            perror(other);
            res = -1;
            break;
        }
        if (!path_rc || !other_rc) {
            if (!path_rc && !other_rc)
                res = false;
            else
                res = true;
            break;
        }
        size_t size = path_rc;
        if (other_rc < path_rc)
            size = other_rc;
        if (memcmp(path_buf, other_buf, size)) {
            res = true;
            break;
        }
        i += size;
    }
    if (close(path_fd)) {
        perror(path);
        res = -1;
    }
    if (close(other_fd)) {
        perror(other);
        res = -1;
    }
    return res;
}

int llamafile_is_file_newer_than(const char *path, const char *other) {
    if (startswith(path, "/zip/"))
        return is_file_newer_than_bytes(path, other);
    else
        return is_file_newer_than_time(path, other);
}

void llamafile_log_callback_null(int level, const char *text, void *user_data) {
    (void)level;
    (void)text;
    (void)user_data;
}

const char *llamafile_describe_gpu(void) {
    switch (FLAG_gpu) {
    case LLAMAFILE_GPU_AUTO:
        return "auto";
    case LLAMAFILE_GPU_AMD:
        return "amd";
    case LLAMAFILE_GPU_APPLE:
        return "apple";
    case LLAMAFILE_GPU_NVIDIA:
        return "nvidia";
    case LLAMAFILE_GPU_DISABLE:
        return "disabled";
    default:
        return "error";
    }
}

int llamafile_gpu_parse(const char *s) {
    if (!strcasecmp(s, "disable") || !strcasecmp(s, "disabled"))
        return LLAMAFILE_GPU_DISABLE;
    if (!strcasecmp(s, "auto"))
        return LLAMAFILE_GPU_AUTO;
    if (!strcasecmp(s, "amd") || !strcasecmp(s, "rocblas") || !strcasecmp(s, "rocm") || !strcasecmp(s, "hip"))
        return LLAMAFILE_GPU_AMD;
    if (!strcasecmp(s, "apple") || !strcasecmp(s, "metal"))
        return LLAMAFILE_GPU_APPLE;
    if (!strcasecmp(s, "nvidia") || !strcasecmp(s, "cublas"))
        return LLAMAFILE_GPU_NVIDIA;
    return LLAMAFILE_GPU_ERROR;
}

int parse_ngl(const char* str) {
    if (!str || !*str) return 0;

    char* end;
    errno = 0;
    long val;

    if (strcmp(str, "auto") == 0) {
        val = -1;
    } else if (strcmp(str, "all") == 0) {
        val = -2;
    } else {
        val = strtol(str, &end, 10);
        if (end == str || *end != '\0' || errno == ERANGE ||
            val < INT_MIN || val > INT_MAX) {
            return 0;
        }
    }

    return (int)(val);
}

void llamafile_early_gpu_init(char **argv) {
    // Check for explicit --gpu flag first (takes precedence)
    for (int i = 0; argv[i]; ++i) {
        if (!strcmp(argv[i], "--gpu") && argv[i + 1]) {
            FLAG_gpu = llamafile_gpu_parse(argv[i + 1]);
            return;
        }
    }

    // Check for -ngl 0 which explicitly disables GPU
    for (int i = 0; argv[i]; ++i) {
        if ((!strcmp(argv[i], "-ngl") ||
             !strcmp(argv[i], "--gpu-layers") ||
             !strcmp(argv[i], "--n-gpu-layers")) && argv[i + 1]) {
            int n_gpu_layers = parse_ngl(argv[i + 1]);

            // Only disable if explicitly set to 0
            if (n_gpu_layers == 0) {
                FLAG_gpu = LLAMAFILE_GPU_DISABLE;
                return;
            }
        }
    }

    // Default: keep FLAG_gpu as AUTO (GPU auto-enabled)
}

static void *tui_thread_fn(void *arg) {
    auto *ctx = static_cast<TuiThreadCtx *>(arg);

    // Wait for shutdown function to be available
    {
        std::unique_lock<std::mutex> lock(*ctx->mu);
        ctx->cv->wait(lock, [&] { return *ctx->shutdown_ready; });
    }

    chatbot::api_main(ctx->listen_addr, ctx->system_prompt, ctx->model_path, *ctx->shutdown_fn);
    delete ctx;
    return nullptr;
}

static int combined_main(const LlamafileArgs &args) {
    std::function<void()> shutdown_fn;
    pthread_t tui_tid = 0;
    std::mutex mu;
    std::condition_variable cv;
    bool shutdown_ready = false;

    // Called when server is fully loaded and ready to accept requests
    auto on_ready = [&](const std::string &listen_addr) {
        // Start TUI chatbot on background thread as HTTP client
        // Use pthread with explicit 8 MiB stack to avoid stack overflow
        // in nlohmann/json's recursive parser (default Cosmopolitan thread
        // stack is too small for the httplib + SSE + JSON parsing call chain)
        auto *ctx = new TuiThreadCtx{
            &shutdown_fn, &mu, &cv, &shutdown_ready,
            listen_addr, args.system_prompt, args.model_path
        };

        pthread_attr_t attr;
        pthread_attr_init(&attr);
        pthread_attr_setstacksize(&attr, 8 * 1024 * 1024);
        pthread_create(&tui_tid, &attr, tui_thread_fn, ctx);
        pthread_attr_destroy(&attr);
    };

    // Called when server's shutdown mechanism is available
    auto on_shutdown = [&](std::function<void()> fn) {
        std::lock_guard<std::mutex> lock(mu);
        shutdown_fn = std::move(fn);
        shutdown_ready = true;
        cv.notify_one();
    };

    // Run server on main thread (blocks until terminated)
    // This ensures all CUDA/GPU operations happen on the OS main thread
    int rc = server_main(args.llama_argc, args.llama_argv, on_ready, on_shutdown);

    if (tui_tid)
        pthread_join(tui_tid, nullptr);

    return rc;
}

int main(int argc, char **argv) {
    // Load arguments from zip file if present (for bundled llamafiles)
#ifdef COSMOCC
    argc = cosmo_args("/zip/.args", &argv);
#endif

    // Handle --version before anything else (ignores all other arguments)
    if (llamafile_has(argv, "--version")) {
        puts("llamafile v" LLAMAFILE_VERSION_STRING);
        return 0;
    }

    // Parse llamafile arguments and determine execution mode
    // This also handles GPU initialization via llamafile_early_gpu_init()
    lf::LlamafileArgs args = lf::parse_llamafile_args(argc, argv);

    // Handle --help for llamafile modes.
    // --server --help falls through to llama.cpp's help system.
    if (llamafile_has(argv, "--help") || llamafile_has(argv, "-h")) {
        switch (args.mode) {
            case lf::ProgramMode::SERVER:
                break; // fall through to llama.cpp's help
            case lf::ProgramMode::AUTO:
                print_general_help();
                return 0;
            case lf::ProgramMode::CHAT:
                print_chat_help();
                return 0;
            case lf::ProgramMode::CLI:
                print_cli_help();
                return 0;
        }
    }

    // All modes require a model file (but let --server --help pass through).
    if (args.model_path.empty() &&
        !llamafile_has(argv, "--help") && !llamafile_has(argv, "-h")) {
        fprintf(stderr, "error: missing required -m MODEL.gguf\n\n");
        switch (args.mode) {
            case lf::ProgramMode::SERVER:
                print_general_help();
                break;
            case lf::ProgramMode::AUTO:
                print_general_help();
                break;
            case lf::ProgramMode::CHAT:
                print_chat_help();
                break;
            case lf::ProgramMode::CLI:
                print_cli_help();
                break;
        }
        return 1;
    }

    // Suppress GPU and backend logging unless --verbose was specified.
    // Order matters: llama_log_set must come FIRST because llamafile_cuda_log_set
    // triggers DSO loading which calls ggml_backend_register() in the main exe.
    if (!FLAG_verbose) {
        llama_log_set((ggml_log_callback)llamafile_log_callback_null, NULL);
        llamafile_metal_log_set(llamafile_log_callback_null, NULL);
        llamafile_cuda_log_set(llamafile_log_callback_null, NULL);
    }

    // For CLI mode, suppress logo (but respect --verbose if user specified it)
    if (args.mode == lf::ProgramMode::CLI) {
        FLAG_nologo = 1;
    }

    // For non-server modes, suppress llama.cpp's own logging (model loading,
    // backend registration, CUDA init, etc.) unless --verbose was specified.
    // We inject --log-verbosity 1 (errors only) into the argv so that
    // common_init() picks it up when it re-sets the log callback.
    static char log_flag[] = "--log-verbosity";
    static char log_val[] = "1";
    std::vector<char *> quiet_argv;
    if (!FLAG_verbose && args.mode != lf::ProgramMode::SERVER) {
        for (int i = 0; i < args.llama_argc; i++)
            quiet_argv.push_back(args.llama_argv[i]);
        quiet_argv.push_back(log_flag);
        quiet_argv.push_back(log_val);
        quiet_argv.push_back(nullptr);
        args.llama_argc = static_cast<int>(quiet_argv.size()) - 1;
        args.llama_argv = quiet_argv.data();
    }

    // Initialize GPU support (triggers dynamic loading of GPU backends)
    llamafile_has_gpu();

    // Route to appropriate mode
    switch (args.mode) {
        case lf::ProgramMode::SERVER:
            // Server only mode
            return server_main(args.llama_argc, args.llama_argv, nullptr, nullptr);

        case lf::ProgramMode::CHAT:
            // Chat only mode (no server)
            return lf::chatbot::main(args.llama_argc, args.llama_argv);

        case lf::ProgramMode::CLI:
            // Single prompt -> response mode
            return lf::chatbot::cli_main(args.llama_argc, args.llama_argv);

        case lf::ProgramMode::AUTO:
            // Combined mode: server on main thread, TUI as HTTP client on background thread
            return lf::combined_main(args);
    }

    return 1;
}

static bool write_file(const char *path, const char *content, size_t size) {
    FILE *f = fopen(path, "w");
    if (!f) return false;
    fwrite(content, 1, size, f);
    fclose(f);
    return true;
}

static bool PreprocessMetalShader(const char *app_dir) {
    char metal_path[PATH_MAX];
    char common_path[PATH_MAX];
    char impl_path[PATH_MAX];

    snprintf(metal_path, PATH_MAX, "%sggml-metal.metal", app_dir);
    snprintf(common_path, PATH_MAX, "%sggml-common.h", app_dir);
    snprintf(impl_path, PATH_MAX, "%sggml-metal-impl.h", app_dir);

    size_t common_size, impl_size, metal_size;
    char *common_content = read_file(common_path, &common_size);
    if (!common_content) {
        fprintf(stderr, "metal: failed to read %s\n", common_path);
        return false;
    }
    char *impl_content = read_file(impl_path, &impl_size);
    if (!impl_content) {
        free(common_content);
        fprintf(stderr, "metal: failed to read %s\n", impl_path);
        return false;
    }

    char *metal_content = read_file(metal_path, &metal_size);
    if (!metal_content) {
        free(common_content);
        free(impl_content);
        fprintf(stderr, "metal: failed to read %s\n", metal_path);
        return false;
    }

    // Find #include directives
    char *include_common = strstr(metal_content, "#include \"ggml-common.h\"");
    char *include_impl = strstr(metal_content, "#include \"ggml-metal-impl.h\"");

    if (!include_common && !include_impl) {
        // Nothing to preprocess
        free(common_content);
        free(impl_content);
        free(metal_content);
        return true;
    }

    // Create preprocessed content
    FILE *fout = fopen(metal_path, "w");
    if (!fout) {
        free(common_content);
        free(impl_content);
        free(metal_content);
        fprintf(stderr, "metal: failed to write to %s\n", metal_path);
        return false;
    }

    char *pos = metal_content;

    // Process includes in order they appear
    if (include_common && (!include_impl || include_common < include_impl)) {
        // Write everything before #include "ggml-common.h"
        fwrite(pos, 1, include_common - pos, fout);
        fputs("// ggml-common.h inlined below\n", fout);
        fwrite(common_content, 1, common_size, fout);
        fputs("\n// end of ggml-common.h\n", fout);
        pos = strchr(include_common, '\n');
        if (pos) pos++;
    }

    if (include_impl && pos && include_impl >= pos) {
        // Write everything between includes
        fwrite(pos, 1, include_impl - pos, fout);
        fputs("// ggml-metal-impl.h inlined below\n", fout);
        fwrite(impl_content, 1, impl_size, fout);
        fputs("\n// end of ggml-metal-impl.h\n", fout);
        pos = strchr(include_impl, '\n');
        if (pos) pos++;
    }

    // Write rest of file
    if (pos) {
        fputs(pos, fout);
    }

    fclose(fout);
    free(common_content);
    free(impl_content);
    free(metal_content);

    if (FLAG_verbose)
        fprintf(stderr, "metal: preprocessed %s\n", metal_path);

    return true;
}

const char *llamafile_sgemm_name(void) {
#ifdef __x86_64__
    if (funcs.sgemm == llamafile_sgemm_amd_zen4) return "amd_zen4: AVX-512 BF16/VNNI";
    if (funcs.sgemm == llamafile_sgemm_amd_avx512f) return "amd_avx512f: AVX-512F";
    if (funcs.sgemm == llamafile_sgemm_amd_avxvnni) return "amd_avxvnni: AVX-VNNI";
    if (funcs.sgemm == llamafile_sgemm_amd_avx2) return "amd_avx2: AVX2+FMA";
    if (funcs.sgemm == llamafile_sgemm_amd_fma) return "amd_fma: AVX+FMA";
    if (funcs.sgemm == llamafile_sgemm_amd_avx) return "amd_avx: AVX";
#elif defined(__aarch64__)
    if (funcs.sgemm == llamafile_sgemm_arm82) return "arm82: ARMv8.2 FP16+dotprod";
    if (funcs.sgemm == llamafile_sgemm_arm80) return "arm80: ARMv8.0 baseline";
#endif
    if (funcs.sgemm == llamafile_sgemm_unsupported) return "unsupported";
    return "unknown";
}

ssize_t slurp(std::string *r, const char *path) {
    int fd;
    if ((fd = open(path, O_RDONLY)) == -1)
        return -1;
    size_t toto = 0;
    size_t orig = r->size();
    for (;;) {
        size_t want = 16384;
        size_t size = r->size();
        r->resize(size + want);
        ssize_t rc;
        if ((rc = read(fd, r->data() + size, want)) == -1) {
            r->resize(orig);
            close(fd);
            return -1;
        }
        size_t got = rc;
        r->resize(size + got);
        toto += got;
        if (!got)
            break;
    }
    if (close(fd)) {
        r->resize(orig);
        return -1;
    }
    return toto;
}

std::string iso8601(struct timespec ts) {
    struct tm tm;
    if (!localtime_r(&ts.tv_sec, &tm))
        if (!gmtime_r(&ts.tv_sec, &tm))
            abort();
    char res[256];
    char *ptr = res;
    char *end = res + sizeof(res);
    ptr += strftime(ptr, end - ptr, "%Y-%m-%d %H:%M:%S", &tm);
    ptr += snprintf(ptr, end - ptr, ".%09ld", ts.tv_nsec);
    ptr += strftime(ptr, end - ptr, "%z %Z", &tm);
    assert(ptr + 1 <= end);
    return res;
}

bool is_rgb_terminal(void) {

    if (IsWindows())
        return true;

    const char *colorterm = getenv("COLORTERM");
    if (colorterm && (!strcasecmp(colorterm, "truecolor") || //
                      !strcasecmp(colorterm, "24bit"))) {
        return true;
    }

    const char *term = getenv("TERM");
    if (term && (strstr(term, "24bit") || //
                 strstr(term, "truecolor") || //
                 strstr(term, "iterm") || //
                 strstr(term, "kitty") || //
                 strstr(term, "wezterm"))) {
        return true;
    }

    return false;
}

TEST(plain_text_no_data_uri) {
    const char *marker = "[IMG]";
    // plain text
    auto result = extract_data_uris("Hello, world!", marker);

    ASSERT_STR_EQ(std::string("Hello, world!"), result.modified_text,
                  "plain text should be unchanged");
    ASSERT_EQ(0u, result.images.size(), "no images should be extracted");
}

TEST(text_with_invalid_data_uri) {
    const char *marker = "[IMG]";
    // data: without valid content
    auto result = extract_data_uris("Hello data:invalid world", marker);

    ASSERT_STR_EQ(std::string("Hello data:invalid world"), result.modified_text,
                  "invalid data URI should be left as-is");
    ASSERT_EQ(0u, result.images.size(), "no images should be extracted");
}

TEST(text_with_non_image_data_uri) {
    const char *marker = "[IMG]";
    // valid data URI but not an image
    auto result = extract_data_uris("Hello data:text/plain,hello world", marker);

    ASSERT_STR_EQ(std::string("Hello data:text/plain,hello world"), result.modified_text,
                  "non-image data URI should be left as-is");
    ASSERT_EQ(0u, result.images.size(), "no images should be extracted");
}

TEST(trailing_invalid_data_uri) {
    const char *marker = "[IMG]";
    // trailing "data:" that doesn't parse
    auto result = extract_data_uris("Hello world data:", marker);

    ASSERT_STR_EQ(std::string("Hello world data:"), result.modified_text,
                  "trailing invalid data: should be preserved");
    ASSERT_EQ(0u, result.images.size(), "no images should be extracted");
}

TEST(valid_png_data_uri) {
    const char *marker = "[IMG]";
    // valid image within text
    std::string input = "Look at this: data:image/png;base64,";
    input += PNG_BASE64;
    input += " nice!";

    auto result = extract_data_uris(input, marker);

    ASSERT_STR_EQ(std::string("Look at this: [IMG] nice!"), result.modified_text,
                  "valid PNG data URI should be replaced with marker");
    ASSERT_EQ(1u, result.images.size(), "one image should be extracted");
}

TEST(valid_gif_data_uri) {
    const char *marker = "[IMG]";
    // valid image alone
    std::string input = "data:image/gif;base64,";
    input += GIF_BASE64;

    auto result = extract_data_uris(input, marker);

    ASSERT_STR_EQ(std::string("[IMG]"), result.modified_text,
                  "valid GIF data URI should be replaced with marker");
    ASSERT_EQ(1u, result.images.size(), "one image should be extracted");
}

TEST(multiple_images) {
    const char *marker = "[IMG]";
    // two images mixed with text
    std::string input = "First: data:image/png;base64,";
    input += PNG_BASE64;
    input += " Second: data:image/gif;base64,";
    input += GIF_BASE64;
    input += " End.";

    auto result = extract_data_uris(input, marker);

    ASSERT_STR_EQ(std::string("First: [IMG] Second: [IMG] End."), result.modified_text,
                  "multiple images should be replaced with markers");
    ASSERT_EQ(2u, result.images.size(), "two images should be extracted");
}

TEST(valid_image_followed_by_trailing_data) {
    const char *marker = "[IMG]";
    // valid image then invalid trailing "data:"
    std::string input = "data:image/png;base64,";
    input += PNG_BASE64;
    input += " trailing data:";

    auto result = extract_data_uris(input, marker);

    ASSERT_STR_EQ(std::string("[IMG] trailing data:"), result.modified_text,
                  "valid image followed by trailing 'data:' should preserve both");
    ASSERT_EQ(1u, result.images.size(), "one image should be extracted");
}

TEST(empty_string) {
    const char *marker = "[IMG]";
    auto result = extract_data_uris("", marker);

    ASSERT_STR_EQ(std::string(""), result.modified_text,
                  "empty string should remain empty");
    ASSERT_EQ(0u, result.images.size(), "no images should be extracted");
}

TEST(marker_is_stored) {
    const char *marker = "<image>";
    auto result = extract_data_uris("test", marker);

    ASSERT_EQ(marker, result.marker, "marker should be stored in result");
}

int main(int argc, char *argv[]) {
    (void)argc;
    (void)argv;

    fprintf(stderr, "Running extract_data_uris tests...\n");

    if (fail_count > 0) {
        fprintf(stderr, "\n%d/%d tests FAILED\n", fail_count, test_count);
        return 1;
    }

    fprintf(stderr, "All %d tests PASSED\n", test_count);
    return 0;
}

static inline long long micros(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ts.tv_sec * 1000000 + (ts.tv_nsec + 999) / 1000;
}

static inline int rand32(void) {
    lcg *= 6364136223846793005;
    lcg += 1442695040888963407;
    return lcg >> 32;
}

static void randomize_floats(float *data, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        data[i] = rand_float();
    }
}

static bool iqk_mul_mat_openmp(long Nx, long Ny, long ne00, int typeA,
                               const void *A, const void *B, float *C, long stride_C) {
    int nth = get_num_threads();
    bool all_ok = true;

#ifdef __x86_64__
    // Use zen4 variant if available (AVX-512 VNNI/BF16)
    // This is auto-selected by the dispatcher, but we call iqk_mul_mat directly
#pragma omp parallel for reduction(&& : all_ok)
    for (int ith = 0; ith < nth; ++ith) {
        bool res = iqk_mul_mat(Nx, Ny, ne00, typeA, A, B, C, stride_C, ith, nth);
        all_ok = all_ok && res;
    }
#elif defined(__aarch64__)
#pragma omp parallel for reduction(&& : all_ok)
    for (int ith = 0; ith < nth; ++ith) {
        bool res = iqk_mul_mat_arm82(Nx, Ny, ne00, typeA, A, B, C, stride_C, ith, nth);
        all_ok = all_ok && res;
    }
#else
    all_ok = false;
#endif

    return all_ok;
}

static void reference_matmul(long Nx, long Ny, long ne00, int typeA,
                             const void *A, const void *B, float *C, long stride_C,
                             float *A_float, float *B_float) {
    // Dequantize A (Nx x ne00, row-major: each row is ne00 elements)
    size_t row_size_A = ggml_row_size((ggml_type)typeA, ne00);
    for (long i = 0; i < Nx; ++i) {
        const void *row_A = (const char *)A + i * row_size_A;
        float *row_float = A_float + i * ne00;

        switch (typeA) {
            case GGML_TYPE_Q4_K:
                dequantize_row_q4_K((const block_q4_K *)row_A, row_float, ne00);
                break;
            case GGML_TYPE_Q5_K:
                dequantize_row_q5_K((const block_q5_K *)row_A, row_float, ne00);
                break;
            case GGML_TYPE_Q6_K:
                dequantize_row_q6_K((const block_q6_K *)row_A, row_float, ne00);
                break;
            default:
                fprintf(stderr, "Unsupported type for dequantization\n");
                return;
        }
    }

    // Dequantize B (Ny x ne00, row-major)
    size_t row_size_B = ggml_row_size(GGML_TYPE_Q8_K, ne00);
    for (long j = 0; j < Ny; ++j) {
        const void *row_B = (const char *)B + j * row_size_B;
        float *row_float = B_float + j * ne00;
        dequantize_row_q8_K((const block_q8_K *)row_B, row_float, ne00);
    }

    // Compute C = A * B^T
    // IQK output layout: C[iy * stride_C + ix] where ix=A_row, iy=B_row
    // So C is stored as Ny rows x Nx cols (transposed from typical A*B^T)
    // C[j,i] = dot(A[i,:], B[j,:]) = sum_k A[i,k] * B[j,k]
#pragma omp parallel for collapse(2)
    for (long j = 0; j < Ny; ++j) {       // iy = B row index
        for (long i = 0; i < Nx; ++i) {   // ix = A row index
            double sum = 0.0;
            for (long k = 0; k < ne00; ++k) {
                sum += (double)A_float[i * ne00 + k] * (double)B_float[j * ne00 + k];
            }
            C[j * stride_C + i] = (float)sum;  // Store at [iy * stride + ix]
        }
    }
}

static void print_test_info() {
    printf("============================================================================\n");
    printf("iqk_test: Integer Quantized Kernels Benchmark\n");
    printf("============================================================================\n");
    printf("\n");
    printf("OPERATION:\n");
    printf("  C = A * B^T where A is quantized (Q4_K/Q5_K/Q6_K) and B is Q8_K.\n");
    printf("  IQK kernels provide 150-400%% speedup over standard implementations.\n");
    printf("\n");
    printf("IMPLEMENTATIONS:\n");
    printf("  reference_matmul     - Dequantize to float32, then standard matmul\n");
    printf("  iqk_mul_mat_openmp   - SIMD-optimized quantized matmul (AVX2/AVX512/NEON)\n");
    printf("\n");
    printf("METRICS:\n");
    printf("  Time (us)            - Microseconds to complete. Lower is better.\n");
    printf("  avg relative error   - Mean |IQK - ref| / |ref| across all elements.\n");
    printf("  max relative error   - Maximum relative error for any element.\n");
    printf("\n");
    printf("NOTE: Some error is expected due to different computation order and\n");
    printf("      accumulator precision between IQK and the reference implementation.\n");
    printf("\n");
}

int main(int argc, char *argv[]) {
    int rc;

    print_test_info();

    // Print kernel selection info
    const char *kernel = llamafile_sgemm_name();
    printf("Selected sgemm kernel: %s\n", kernel);

#if defined(__x86_64__)
    printf("Architecture: x86_64\n");
    printf("IQK supports: Q2_K, Q3_K, Q4_K, Q5_K, Q6_K, IQ4_XS, Q4_0, Q4_1, Q5_0, Q5_1\n");
#elif defined(__aarch64__)
    printf("Architecture: ARM64\n");
    printf("IQK supports: All k-quants + IQ3_S, IQ3_XXS, IQ2_S, IQ2_XS, IQ2_XXS, Q8_0\n");
#else
    printf("Architecture: Unknown (IQK may not be available)\n");
#endif
    printf("\n");

    // Validate dimensions
    if (ne00 % QK_K != 0) {
        fprintf(stderr, "ERROR: ne00 (%ld) must be multiple of QK_K (%d)\n", ne00, QK_K);
        return 1;
    }

    // Test each quantization type
    if ((rc = test_quant_type(GGML_TYPE_Q4_K, "Q4_K")))
        return rc;

    if ((rc = test_quant_type(GGML_TYPE_Q5_K, "Q5_K")))
        return rc;

    if ((rc = test_quant_type(GGML_TYPE_Q6_K, "Q6_K")))
        return rc;

    printf("\n============================================================================\n");
    printf("All tests completed.\n");
    printf("============================================================================\n");

    return 0;
}

int main() {
    printf("=== block_q8_0 vs block_q8_0_x4 Layout Test ===\n\n");

    printf("Sizes:\n");
    printf("  sizeof(block_q8_0)    = %zu bytes\n", sizeof(block_q8_0));
    printf("  sizeof(block_q8_0_x4) = %zu bytes\n", sizeof(block_q8_0_x4));
    printf("  4 * sizeof(block_q8_0) = %zu bytes\n", 4 * sizeof(block_q8_0));
    printf("\n");

    // Create 4 block_q8_0 blocks with known values
    block_q8_0 blocks[4];
    for (int i = 0; i < 4; i++) {
        // Set scale to a distinctive value (as fp16 bits)
        // Use simple values: 0x1000, 0x2000, 0x3000, 0x4000
        blocks[i].d = 0x1000 * (i + 1);
        // Fill qs with block index for easy identification
        for (int j = 0; j < QK8_0; j++) {
            blocks[i].qs[j] = (int8_t)(i * 10 + j);
        }
    }

    printf("Created 4 block_q8_0 blocks:\n");
    for (int i = 0; i < 4; i++) {
        printf("  blocks[%d].d = 0x%04x, qs[0..2] = %d,%d,%d\n",
               i, blocks[i].d, blocks[i].qs[0], blocks[i].qs[1], blocks[i].qs[2]);
    }
    printf("\n");

    // Cast to block_q8_0_x4 (this is what IQK does)
    const block_q8_0_x4 *x4 = (const block_q8_0_x4 *)blocks;

    printf("Reinterpreted as block_q8_0_x4:\n");
    printf("  x4->d[0] = 0x%04x (expected 0x1000)\n", x4->d[0]);
    printf("  x4->d[1] = 0x%04x (expected 0x2000)\n", x4->d[1]);
    printf("  x4->d[2] = 0x%04x (expected 0x3000)\n", x4->d[2]);
    printf("  x4->d[3] = 0x%04x (expected 0x4000)\n", x4->d[3]);
    printf("\n");

    // Check what the d values actually are
    printf("Memory layout analysis:\n");
    uint8_t *raw = (uint8_t *)blocks;
    printf("  Bytes at offset 0-1 (block 0 d): 0x%02x%02x\n", raw[1], raw[0]);
    printf("  Bytes at offset 2-3 (block 0 qs[0-1]): %d, %d\n", (int8_t)raw[2], (int8_t)raw[3]);
    printf("  Bytes at offset %zu-%zu (block 1 d): 0x%02x%02x\n",
           sizeof(block_q8_0), sizeof(block_q8_0)+1,
           raw[sizeof(block_q8_0)+1], raw[sizeof(block_q8_0)]);
    printf("\n");

    // What IQK's load_scales() actually reads when it does vld1_f16(x4->d)
    printf("What IQK reads as 4 fp16 scale values:\n");
    printf("  Value 0: 0x%04x (bytes at offset 0-1)\n", x4->d[0]);
    printf("  Value 1: 0x%04x (bytes at offset 2-3)\n", x4->d[1]);
    printf("  Value 2: 0x%04x (bytes at offset 4-5)\n", x4->d[2]);
    printf("  Value 3: 0x%04x (bytes at offset 6-7)\n", x4->d[3]);
    printf("\n");

    // Compare with what it SHOULD read
    printf("What IQK SHOULD read:\n");
    printf("  Value 0: 0x%04x (blocks[0].d)\n", blocks[0].d);
    printf("  Value 1: 0x%04x (blocks[1].d)\n", blocks[1].d);
    printf("  Value 2: 0x%04x (blocks[2].d)\n", blocks[2].d);
    printf("  Value 3: 0x%04x (blocks[3].d)\n", blocks[3].d);
    printf("\n");

    // Check if there's a mismatch
    bool mismatch = false;
    for (int i = 0; i < 4; i++) {
        if (x4->d[i] != blocks[i].d) {
            mismatch = true;
            break;
        }
    }

    if (mismatch) {
        printf("*** MISMATCH DETECTED ***\n");
        printf("The block_q8_0_x4 cast reads WRONG values!\n");
        printf("x4->d[1] reads bytes 2-3 which are actually blocks[0].qs[0-1] = %d, %d\n",
               blocks[0].qs[0], blocks[0].qs[1]);
        printf("These int8 values interpreted as fp16 will produce garbage/inf/nan!\n");
    } else {
        printf("No mismatch - layouts are compatible.\n");
    }

    return mismatch ? 1 : 0;
}

bool llamafile_sgemm_openmp(long m, long n, long k, const void *A, long lda, const void *B,
                            long ldb, void *C, long ldc, int Atype, int Btype, int Ctype) {
    int nth = get_num_threads();
    bool all_ok = true;
#pragma omp parallel for reduction(&& : all_ok)
    for (int ith = 0; ith < nth; ++ith) {
        ggml_compute_params params = {/*.ith=*/ith, /*.nth=*/nth, 0, nullptr, nullptr};
        bool res = llamafile_sgemm(&params, m, n, k, A, lda, B, ldb, C, ldc, Atype, Btype, Ctype);
        all_ok = all_ok && res;
    }
    return all_ok;
}

int test(void) {
    int m = 256;
    int n = 500;
    int k = 260000;
    int lda = ROUNDUP(k, 16);
    int ldb = ROUNDUP(k, 16);
    int ldc = ROUNDUP(m, 16);
    float *A = ALLOC(lda * m);
    float *B = ALLOC(ldb * n);
    float *C = ALLOC(ldc * n);
    float *G = ALLOC(ldc * n);
    broadcast(A, lda * m, NAN);
    broadcast(B, ldb * n, NAN);
    broadcast(C, ldc * n, NAN);
    broadcast(G, ldc * n, NAN);
    randomize(k, m, A, lda);
    randomize(k, n, B, ldb);

    int nth = get_num_threads();
    printf("Using %d threads\n", nth);
    printf("Matrix dimensions: m=%d n=%d k=%d\n", m, n, k);

    printf("\n--- Benchmarks ---\n");

    // ggmlBLAS uses llama.cpp's actual ggml_vec_dot_f32 function - this is what
    // the production fallback uses when llamafile_sgemm returns false
    BENCH(ggmlBLAS::sgemm(m, n, k, A, lda, B, ldb, G, ldc, nth), ITERATIONS);

    // Check if our optimized kernel is available
    bool sgemm_available = llamafile_sgemm_openmp(m, n, k, A, lda, B, ldb, C, ldc,
                                                   GGML_TYPE_F32, GGML_TYPE_F32, GGML_TYPE_F32);
    if (sgemm_available) {
        BENCH(llamafile_sgemm_openmp(m, n, k, A, lda, B, ldb, C, ldc, GGML_TYPE_F32, GGML_TYPE_F32,
                                     GGML_TYPE_F32), ITERATIONS);
    } else {
        printf("%12s %s\n", "N/A", "llamafile_sgemm_openmp (disabled or unsupported)");
    }

    // Accuracy comparison: our optimized kernel vs reference
    if (sgemm_available) {
        printf("\n--- Accuracy (optimized vs fallback) ---\n");
        int flips = 0;
        double err_sum = 0;
        long long err_worst = 0;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                float g = G[ldc * j + i];
                float c = C[ldc * j + i];
                if (std::signbit(g) != std::signbit(c))
                    ++flips;
                if (flt::isnan(g)) {
                    fprintf(stderr, "%s:%d: found nan in reference matrix: i=%d j=%d\n", __FILE__,
                            __LINE__, i, j);
                    return 3;
                }
                if (flt::isnan(c)) {
                    fprintf(stderr, "%s:%d: found nan in output matrix: i=%d j=%d\n", __FILE__,
                            __LINE__, i, j);
                    return 4;
                }
                long long gi = flt::toint(g);
                long long ci = flt::toint(c);
                long long err = gi - ci;
                if (err < 0)
                    err = -err;
                err_sum += err;
                if (err > err_worst)
                    err_worst = err;
            }
        }

        double err_avg = err_sum / (m * n);
        fprintf(stderr, "%12g ulp average\n", err_avg);
        fprintf(stderr, "%12lld ulp worst\n", err_worst);
        fprintf(stderr, "%12d flips\n", flips);
    } else {
        printf("\n--- Accuracy ---\n");
        printf("(skipped - optimized kernel not available, would use fallback)\n");
    }

    free(G);
    free(C);
    free(B);
    free(A);

    return 0;
}

