bool IsOneInstrConstant(const InstructionSequence* code,
                        const InstructionOperand& op) {
  if (!op.IsConstant()) return false;
  Constant constant =
      code->GetConstant(ConstantOperand::cast(op).virtual_register());
  uint64_t imm;
  unsigned size;
  switch (constant.type()) {
    case Constant::kInt32:
      imm = static_cast<uint32_t>(constant.ToInt32());
      size = kWRegSizeInBits;
      break;
    case Constant::kInt64:
      imm = static_cast<uint64_t>(constant.ToInt64());
      size = kXRegSizeInBits;
      break;
    default:
      return false;
  }
  unsigned n, imm_s, imm_r;
  return MacroAssembler::IsImmMovz(imm, size) ||
         MacroAssembler::IsImmMovn(imm, size) ||
         Assembler::IsImmLogical(imm, size, &n, &imm_s, &imm_r);
}

TestOperand ConstWithValue(int32_t value) {
    int virtual_register = sequence()->NextVirtualRegister();
    sequence()->AddConstant(virtual_register, Constant(value));
    return Const(virtual_register);
  }

TEST_F(MoveOptimizerTest, KeepsCheapConstantsIndependent) {
  StartBlock();
  EndBlock(Last());

  auto gap = LastInstruction();
  TestOperand cheap = ConstWithValue(1);
  AddMove(gap, cheap, Reg(0));
  AddMove(gap, cheap, Reg(1));

  Optimize();

  auto move = gap->parallel_moves()[0];
#if V8_TARGET_ARCH_ARM64
  // A one-instruction constant rematerializes into each register; grouping
  // would only make the second move depend on the first.
  CHECK_EQ(2, NonRedundantSize(move));
  CHECK(Contains(move, cheap, Reg(0)));
  CHECK(Contains(move, cheap, Reg(1)));
  auto follow = gap->parallel_moves()[1];
  CHECK(follow == nullptr || NonRedundantSize(follow) == 0);
#else
  CHECK_EQ(1, NonRedundantSize(move));
  CHECK(Contains(move, cheap, Reg(0)));
  auto follow = gap->parallel_moves()[1];
  CHECK_EQ(1, NonRedundantSize(follow));
  CHECK(Contains(follow, Reg(0), Reg(1)));
#endif
}

TEST_F(MoveOptimizerTest, GroupsExpensiveConstants) {
  StartBlock();
  EndBlock(Last());

  auto gap = LastInstruction();
  // 0x12345678 is no single MOVZ/MOVN/ORR-immediate on arm64, so grouping
  // still pays off: materialize once, then copy.
  TestOperand expensive = ConstWithValue(0x12345678);
  AddMove(gap, expensive, Reg(0));
  AddMove(gap, expensive, Reg(1));

  Optimize();

  auto move = gap->parallel_moves()[0];
  CHECK_EQ(1, NonRedundantSize(move));
  CHECK(Contains(move, expensive, Reg(0)));
  auto follow = gap->parallel_moves()[1];
  CHECK_EQ(1, NonRedundantSize(follow));
  CHECK(Contains(follow, Reg(0), Reg(1)));
}

TEST(enum_test, format_scattered_enum) {
  static_assert(fmt::detail::identifier_table_size<scattered>() == 0);
  static_assert(fmt::detail::identifier_map_size<scattered>() == 32);
  EXPECT_EQ(fmt::format("{}", scattered::a), "a");
  EXPECT_EQ(fmt::format("{}", scattered::b), "b");
  EXPECT_EQ(fmt::format("{}", scattered::c), "c");
  EXPECT_EQ(fmt::format("{}", scattered::d), "d");
  EXPECT_EQ(fmt::format("{}", scattered::e), "e");
  EXPECT_EQ(fmt::format("{}", scattered::f), "f");
  EXPECT_EQ(fmt::format("{}", scattered::g), "g");
  EXPECT_EQ(fmt::format("{}", scattered::h), "h");
  EXPECT_EQ(fmt::format("{}", scattered::i), "i");
  EXPECT_EQ(fmt::format("{}", scattered::j), "j");
  EXPECT_EQ(fmt::format("{}", scattered::k), "k");
  EXPECT_EQ(fmt::format("{}", scattered::l), "l");
  EXPECT_EQ(fmt::format("{}", static_cast<scattered>(0)), "0");
  EXPECT_EQ(fmt::format("{}", static_cast<scattered>(-1)), "-1");
  EXPECT_EQ(fmt::format("{}", static_cast<scattered>(999)), "999");
}

TEST(enum_test, format_enum_with_hash_collision) {
  static_assert(fmt::detail::identifier_table_size<collision>() == 0);
  static_assert(fmt::detail::identifier_map_size<collision>() == 8);
  // Three of the four values want the same slot and the fourth takes the slot
  // next to it, filling the table to its maximum load factor of 0.5.
  static_assert(fmt::detail::identifier_slot(collision::c0) ==
                fmt::detail::identifier_slot(collision::c7));
  static_assert(fmt::detail::identifier_slot(collision::c0) ==
                fmt::detail::identifier_slot(collision::c15));
  static_assert(fmt::detail::identifier_slot(collision::c6) !=
                fmt::detail::identifier_slot(collision::c0));
  EXPECT_EQ(fmt::format("{}", collision::c0), "c0");
  EXPECT_EQ(fmt::format("{}", collision::c6), "c6");
  EXPECT_EQ(fmt::format("{}", collision::c7), "c7");
  EXPECT_EQ(fmt::format("{}", collision::c15), "c15");
  // A value that collides with the enumerators but doesn't match any of them
  // is rejected after probing the whole chain.
  static_assert(fmt::detail::identifier_slot(static_cast<collision>(23)) ==
                fmt::detail::identifier_slot(collision::c0));
  EXPECT_EQ(fmt::format("{}", static_cast<collision>(23)), "23");
}

TEST(enum_test, format_enum_with_wrapping_hash_collision) {
  static_assert(fmt::detail::identifier_table_size<wrapping_collision>() == 0);
  static_assert(fmt::detail::identifier_map_size<wrapping_collision>() == 8);
  // All the values want the last slot, so the probe sequence wraps around.
  static_assert(fmt::detail::identifier_slot(wrapping_collision::w8) == 7);
  static_assert(fmt::detail::identifier_slot(wrapping_collision::w16) == 7);
  static_assert(fmt::detail::identifier_slot(wrapping_collision::w24) == 7);
  EXPECT_EQ(fmt::format("{}", wrapping_collision::w8), "w8");
  EXPECT_EQ(fmt::format("{}", wrapping_collision::w16), "w16");
  EXPECT_EQ(fmt::format("{}", wrapping_collision::w24), "w24");
  EXPECT_EQ(fmt::format("{}", static_cast<wrapping_collision>(33)), "33");
}

TEST(enum_test, format_sparse_enum_alias) {
  // The first enumerator with a matching value is used in the hash table too.
  static_assert(fmt::detail::identifier_table_size<sparse_alias>() == 0);
  EXPECT_EQ(fmt::format("{}", sparse_alias::dup), "one");
  EXPECT_EQ(fmt::format("{}", sparse_alias::far), "far");
}

TEST(enum_test, format_enum) {
  EXPECT_EQ(fmt::format("{}", color::red), "red");
  EXPECT_EQ(fmt::format("{}", color::green), "green");
  EXPECT_EQ(fmt::format("{}", color::blue), "blue");
}

TEST(enum_test, format_enum_with_underlying_type) {
  EXPECT_EQ(fmt::format("{}", level::high), "high");
  EXPECT_EQ(fmt::format("{}", byte_enum::one), "one");
  EXPECT_EQ(fmt::format("{}", signed_byte_enum::minus_one), "minus_one");
  EXPECT_EQ(fmt::format("{}", bool_enum::off), "off");
}

TEST(enum_test, format_dense_enum) {
  // A dense enum is formatted using a lookup table.
  static_assert(fmt::detail::identifier_table_size<dense>() == 5);
  EXPECT_EQ(fmt::format("{}", dense::d0), "d0");
  EXPECT_EQ(fmt::format("{}", dense::d4), "d4");
  EXPECT_EQ(fmt::format("{}", static_cast<dense>(5)), "5");
}

TEST(enum_test, format_holey_enum) {
  // Up to 30% of holes are still formatted using a lookup table.
  static_assert(fmt::detail::identifier_table_size<holey>() == 10);
  EXPECT_EQ(fmt::format("{}", holey::h0), "h0");
  EXPECT_EQ(fmt::format("{}", holey::h5), "h5");
  EXPECT_EQ(fmt::format("{}", holey::h6), "h6");
  // Values in the holes and outside of the table fall back to the number.
  EXPECT_EQ(fmt::format("{}", static_cast<holey>(6)), "6");
  EXPECT_EQ(fmt::format("{}", static_cast<holey>(8)), "8");
  EXPECT_EQ(fmt::format("{}", static_cast<holey>(10)), "10");
  EXPECT_EQ(fmt::format("{}", static_cast<holey>(-1)), "-1");
}

TEST(enum_test, format_sparse_enum) {
  // One more hole than holey, which is too many for a lookup table.
  static_assert(fmt::detail::identifier_table_size<sparse>() == 0);
  EXPECT_EQ(fmt::format("{}", sparse::s0), "s0");
  EXPECT_EQ(fmt::format("{}", sparse::s5), "s5");
  EXPECT_EQ(fmt::format("{}", sparse::s6), "s6");
  EXPECT_EQ(fmt::format("{}", static_cast<sparse>(6)), "6");
  EXPECT_EQ(fmt::format("{}", static_cast<sparse>(11)), "11");
}

TEST(enum_test, format_enum_with_negative_values) {
  static_assert(fmt::detail::identifier_table_size<signed_enum>() == 4);
  EXPECT_EQ(fmt::format("{}", signed_enum::minus_two), "minus_two");
  EXPECT_EQ(fmt::format("{}", signed_enum::minus_one), "minus_one");
  EXPECT_EQ(fmt::format("{}", signed_enum::one), "one");
  // A hole and values below and above the range of the table.
  EXPECT_EQ(fmt::format("{}", static_cast<signed_enum>(0)), "0");
  EXPECT_EQ(fmt::format("{}", static_cast<signed_enum>(-3)), "-3");
  EXPECT_EQ(fmt::format("{}", static_cast<signed_enum>(2)), "2");
}

TEST(enum_test, format_enum_with_extreme_values) {
  // The span of the values overflows the underlying type, so no table is used.
  static_assert(fmt::detail::identifier_table_size<extremes>() == 0);
  EXPECT_EQ(fmt::format("{}", extremes::lowest), "lowest");
  EXPECT_EQ(fmt::format("{}", extremes::highest), "highest");
  EXPECT_EQ(fmt::format("{}", static_cast<extremes>(0)), "0");

  static_assert(fmt::detail::identifier_table_size<big>() == 1);
  EXPECT_EQ(fmt::format("{}", big::huge), "huge");
  EXPECT_EQ(fmt::format("{}", static_cast<big>(0)), "0");
}

TEST(enum_test, format_unknown_value) {
  EXPECT_EQ(fmt::format("{}", static_cast<color>(42)), "42");
  EXPECT_EQ(fmt::format("{}", static_cast<level>(42)), "42");
  EXPECT_EQ(fmt::format("{}", static_cast<empty_enum>(0)), "0");
}

TEST(enum_test, format_unknown_char_value) {
  // A char underlying type is written in decimal, not as a character.
  EXPECT_EQ(fmt::format("{}", static_cast<byte_enum>(65)), "65");
  EXPECT_EQ(fmt::format("{}", static_cast<signed_byte_enum>(-65)), "-65");
  EXPECT_EQ(fmt::format("{}", static_cast<level>(65)), "65");
  // A bool underlying type is written as 0 or 1, not as "true"/"false".
  EXPECT_EQ(fmt::format("{}", static_cast<bool_enum>(true)), "1");
}

TEST(enum_test, format_enum_specs) {
  EXPECT_EQ(fmt::format("{:>7}", color::red), "    red");
  EXPECT_EQ(fmt::format("{:*^7}", color::red), "**red**");
  EXPECT_EQ(fmt::format("{:.2}", color::green), "gr");
  EXPECT_EQ(fmt::format("{:>4}", static_cast<color>(42)), "  42");
}

bool rejects_trailing_garbage() {
    TEST_START();
    dom::parser parser;
    parser.number_as_string(true);
    // A big integer whose digit run is followed by a non-structural, non-whitespace character is
    // a malformed token and must be rejected, just as it is for numbers that fit in 64 bits.
    ASSERT_ERROR(parser.parse(R"({"val":123456789012345678901x})"_padded), NUMBER_ERROR);
    ASSERT_ERROR(parser.parse(R"({"val":-123456789012345678901x})"_padded), NUMBER_ERROR);
    // Same at the top level of a document.
    ASSERT_ERROR(parser.parse("123456789012345678901x"_padded), NUMBER_ERROR);
    // A well-formed big integer terminated by a structural character is still accepted.
    ASSERT_SUCCESS(parser.parse(R"({"val":123456789012345678901})"_padded));
    TEST_SUCCEED();
  }

void simpleinputpad_dom1() {
  std::string_view json = "[1,2,3]";
  simdjson::padded_input input(json);
  dom::parser parser;
  dom::element doc;
  auto error = parser.parse(input).get(doc);
  if(error) { exit(-1); }
}

void simpleinputpad_dom2() {
  const char *jsonpointer = R"(
        {
            "key": "value"
        }
    )";
  size_t len = strlen(jsonpointer);
  simdjson::padded_input input(jsonpointer, len);
  dom::parser parser;
  dom::element doc;
  auto error = parser.parse(input).get(doc);
  if(error) { exit(-1); }
  std::string_view val;
  error = doc["key"].get(val);
  if(error) { exit(-1); }
  if(val != "value") { exit(-1); }
}

bool test_padded_input_from_string_view() {
  std::string_view json = "[1,2,3]";
  simdjson::padded_input input(json);
  simdjson::ondemand::parser parser;
  simdjson::ondemand::document doc;
  auto error = parser.iterate(input).get(doc);
  if (error) {
    printf("FAILED: test_padded_input_from_string_view (iterate error: %s)\n",
           simdjson::error_message(error));
    return false;
  }
  size_t count = 0;
  for (auto val : doc) {
    int64_t v;
    error = val.get_int64().get(v);
    if (error) {
      printf("FAILED: test_padded_input_from_string_view (get_int64 error)\n");
      return false;
    }
    count++;
  }
  if (count != 3) {
    printf("FAILED: test_padded_input_from_string_view (expected 3 elements, got %zu)\n", count);
    return false;
  }
  printf("OK: test_padded_input_from_string_view\n");
  return true;
}

bool test_padded_input_from_cstring() {
  const char *json = R"({"key": "value"})";
  size_t len = std::strlen(json);
  simdjson::padded_input input(json, len);
  simdjson::ondemand::parser parser;
  simdjson::ondemand::document doc;
  auto error = parser.iterate(input).get(doc);
  if (error) {
    printf("FAILED: test_padded_input_from_cstring (iterate error: %s)\n",
           simdjson::error_message(error));
    return false;
  }
  std::string_view val;
  error = doc["key"].get_string().get(val);
  if (error) {
    printf("FAILED: test_padded_input_from_cstring (get_string error)\n");
    return false;
  }
  if (val != "value") {
    printf("FAILED: test_padded_input_from_cstring (expected 'value', got '%.*s')\n",
           (int)val.size(), val.data());
    return false;
  }
  printf("OK: test_padded_input_from_cstring\n");
  return true;
}

bool test_padded_input_is_view() {
  // A short string at a "safe" position should typically be a view (no copy).
  // We can't guarantee this in all environments, but we can at least test
  // that is_view() returns a valid boolean and parsing works either way.
  std::string_view json = "[1]";
  simdjson::padded_input input(json);
  bool view = input.is_view();
  printf("  is_view() = %s\n", view ? "true" : "false");
  simdjson::ondemand::parser parser;
  simdjson::ondemand::document doc;
  auto error = parser.iterate(input).get(doc);
  if (error) {
    printf("FAILED: test_padded_input_is_view (iterate error: %s)\n",
           simdjson::error_message(error));
    return false;
  }
  printf("OK: test_padded_input_is_view\n");
  return true;
}

bool test_padded_input_nested_json() {
  std::string_view json = R"({"a":{"b":[1,2,{"c":true}]}})";
  simdjson::padded_input input(json);
  simdjson::ondemand::parser parser;
  simdjson::ondemand::document doc;
  auto error = parser.iterate(input).get(doc);
  if (error) {
    printf("FAILED: test_padded_input_nested_json (iterate error: %s)\n",
           simdjson::error_message(error));
    return false;
  }
  bool c_val;
  error = doc["a"]["b"].at(2)["c"].get_bool().get(c_val);
  if (error) {
    printf("FAILED: test_padded_input_nested_json (get_bool error)\n");
    return false;
  }
  if (!c_val) {
    printf("FAILED: test_padded_input_nested_json (expected true)\n");
    return false;
  }
  printf("OK: test_padded_input_nested_json\n");
  return true;
}

bool test_padded_input_dom() {
  std::string_view json = "[1,2,3]";
  simdjson::padded_input input(json);
  simdjson::dom::parser parser;
  simdjson::dom::element doc;
  auto error = parser.parse(input).get(doc);
  if (error) {
    printf("FAILED: test_padded_input_dom (parse error: %s)\n",
           simdjson::error_message(error));
    return false;
  }
  printf("OK: test_padded_input_dom\n");
  return true;
}

bool test_padded_input_dom_object() {
  const char *json = R"({"name":"simdjson","version":42})";
  size_t len = std::strlen(json);
  simdjson::padded_input input(json, len);
  simdjson::dom::parser parser;
  simdjson::dom::element doc;
  auto error = parser.parse(input).get(doc);
  if (error) {
    printf("FAILED: test_padded_input_dom_object (parse error: %s)\n",
           simdjson::error_message(error));
    return false;
  }
  std::string_view name;
  error = doc["name"].get(name);
  if (error || name != "simdjson") {
    printf("FAILED: test_padded_input_dom_object (name mismatch)\n");
    return false;
  }
  printf("OK: test_padded_input_dom_object\n");
  return true;
}

bool test_padded_input_from_std_string() {
  std::string json = R"({"key": "value"})";
  // Reserve extra space to test capacity handling
  json.reserve(json.size() + 100);
  simdjson::padded_input input(json);
  simdjson::ondemand::parser parser;
  simdjson::ondemand::document doc;
  auto error = parser.iterate(input).get(doc);
  if (error) {
    printf("FAILED: test_padded_input_from_std_string (iterate error: %s)\n",
           simdjson::error_message(error));
    return false;
  }
  std::string_view key;
  error = doc["key"].get(key);
  if (error || key != "value") {
    printf("FAILED: test_padded_input_from_std_string (key/value mismatch)\n");
    return false;
  }
  printf("OK: test_padded_input_from_std_string\n");
  return true;
}

int main() {
  bool ok = true;
  ok = test_padded_input_from_string_view() && ok;
  ok = test_padded_input_from_cstring() && ok;
  ok = test_padded_input_from_std_string() && ok;
  ok = test_padded_input_is_view() && ok;
  ok = test_padded_input_nested_json() && ok;
  ok = test_padded_input_dom() && ok;
  ok = test_padded_input_dom_object() && ok;
  if (ok) {
    printf("\nAll padded_input tests passed.\n");
    return EXIT_SUCCESS;
  } else {
    printf("\nSome padded_input tests FAILED.\n");
    return EXIT_FAILURE;
  }
}

