TEST(ATenFactoryDefaultDtypeTest, ScalarTensorCreatesZeroDimTensor) {
  at::Tensor tensor = at::scalar_tensor(
      42, at::TensorOptions().dtype(at::kLong).device(at::kCPU));

  ASSERT_EQ(tensor.dim(), 0);
  ASSERT_EQ(tensor.scalar_type(), at::kLong);
  ASSERT_EQ(tensor.device().type(), at::kCPU);
  ASSERT_EQ(tensor.item<int64_t>(), 42);
}

TEST(ATenFactoryDefaultDtypeTest,
     ScalarTensorOptionalArgumentsUseCurrentDefaultDtype) {
  DefaultDtypeGuard guard(at::kDouble);

  at::Tensor tensor =
      at::scalar_tensor(1.25, std::nullopt, std::nullopt, at::kCPU, false);
  at::Tensor strided_tensor =
      at::scalar_tensor(2.5, std::nullopt, at::kStrided, at::kCPU, false);

  ASSERT_EQ(tensor.dim(), 0);
  ASSERT_EQ(tensor.scalar_type(), at::kDouble);
  ASSERT_DOUBLE_EQ(tensor.item<double>(), 1.25);
  ASSERT_EQ(strided_tensor.dim(), 0);
  ASSERT_EQ(strided_tensor.scalar_type(), at::kDouble);
  ASSERT_EQ(strided_tensor.layout(), at::kStrided);
  ASSERT_DOUBLE_EQ(strided_tensor.item<double>(), 2.5);
}

void BlockingStreamCallback(hipStream_t /*stream*/,
                            hipError_t /*status*/,
                            void* user_data) {
  auto* gate = static_cast<StreamCallbackGate*>(user_data);
  while (!gate->load(std::memory_order_acquire)) {
    std::this_thread::sleep_for(std::chrono::milliseconds(1));
  }
}

void CUDART_CB BlockingStreamCallback(void* user_data) {
  auto* gate = static_cast<StreamCallbackGate*>(user_data);
  while (!gate->load(std::memory_order_acquire)) {
    std::this_thread::sleep_for(std::chrono::milliseconds(1));
  }
}

TEST_F(RecordStreamTest, StorageHolderViewKeepsNonDefaultStreamAlive) {
  if (!at::cuda::is_available()) {
    return;
  }
  auto& facade = paddle::memory::allocation::AllocatorFacade::Instance();
  if (!facade.IsStreamSafeCUDAAllocatorUsed() &&
      !facade.IsCUDAMallocAsyncAllocatorUsed()) {
    return;
  }

  auto current_stream = at::cuda::getCurrentCUDAStream();
  auto other_stream = at::cuda::getStreamFromPool(
      /*isHighPriority=*/false, current_stream.device_index());
  for (int i = 0; i < 32 && other_stream == current_stream; ++i) {
    other_stream = at::cuda::getStreamFromPool(
        /*isHighPriority=*/false, current_stream.device_index());
  }
  ASSERT_NE(other_stream, current_stream);

  StreamCallbackGate gate{false};
  CallbackGateRelease release_gate(&gate);
  void* original_ptr = nullptr;
  constexpr int64_t kElements = 1 << 20;
  constexpr size_t kBytes = kElements * sizeof(float);
  {
    at::Tensor tensor = at::empty(
        {kElements}, at::TensorOptions().dtype(at::kFloat).device(at::kCUDA));
    (void)tensor.storage();
    auto dense = std::dynamic_pointer_cast<phi::DenseTensor>(
        tensor._PD_GetInner().impl());
    ASSERT_NE(dense, nullptr);
    ASSERT_NE(
        std::dynamic_pointer_cast<c10::StorageHolderView>(dense->Holder()),
        nullptr);
    original_ptr = tensor.data_ptr();

#ifdef PADDLE_WITH_HIP
    C10_CUDA_CHECK(hipStreamAddCallback(
        other_stream.stream(), BlockingStreamCallback, &gate, 0));
    C10_CUDA_CHECK(
        hipMemsetAsync(original_ptr, 0, kBytes, other_stream.stream()));
#else
    C10_CUDA_CHECK(cudaLaunchHostFunc(
        other_stream.stream(), BlockingStreamCallback, &gate));
    C10_CUDA_CHECK(
        cudaMemsetAsync(original_ptr, 0, kBytes, other_stream.stream()));
#endif
    EXPECT_NO_THROW(tensor.record_stream(other_stream.unwrap()));
  }

  at::Tensor replacement = at::empty(
      {kElements}, at::TensorOptions().dtype(at::kFloat).device(at::kCUDA));
  EXPECT_NE(replacement.data_ptr(), original_ptr)
      << "record_stream must defer reuse while non-default stream work is "
         "pending";

  gate.store(true, std::memory_order_release);
  EXPECT_NO_THROW(other_stream.synchronize());
}

TEST_F(RecordStreamTest, StorageHolderViewWithoutAllocationFailsLoudly) {
  if (!at::cuda::is_available()) {
    return;
  }
  auto stream = at::cuda::getCurrentCUDAStream();
  at::Tensor tensor =
      at::empty({4}, at::TensorOptions().dtype(at::kFloat).device(at::kCUDA));
  c10::Storage storage = tensor.storage();
  auto dense =
      std::dynamic_pointer_cast<phi::DenseTensor>(tensor._PD_GetInner().impl());
  ASSERT_NE(dense, nullptr);
  ASSERT_NE(std::dynamic_pointer_cast<c10::StorageHolderView>(dense->Holder()),
            nullptr);

  storage.set_data_ptr_noswap(
      c10::DataPtr(reinterpret_cast<void*>(static_cast<uintptr_t>(1)),
                   c10::Device(c10::DeviceType::CUDA, stream.device_index())));
  EXPECT_THROW(tensor.record_stream(stream.unwrap()), std::exception);
}

TEST_F(RecordStreamTest, RejectsStreamFromAnotherDevice) {
  if (c10::cuda::device_count() < 2) {
    return;
  }
  c10::cuda::CUDAGuard guard(0);
  at::Tensor tensor = at::empty(
      {4},
      at::TensorOptions().dtype(at::kFloat).device(c10::Device(at::kCUDA, 0)));
  auto other_device_stream = at::cuda::getStreamFromPool(
      /*isHighPriority=*/false, /*device_index=*/1);

  EXPECT_THROW(tensor.record_stream(other_device_stream.unwrap()),
               std::exception);
}

void EighPreProcess(Tensor* x, std::string* UPLO) {
  auto x_shape = x->dims();
  int64_t rank = x_shape.size();
  PADDLE_ENFORCE_GE(rank,
                    2,
                    phi::errors::InvalidArgument(
                        "Input(input) only support >=2 tensor, but received "
                        "length of Input(input) is %ld.",
                        rank));
  PADDLE_ENFORCE_EQ(x_shape[rank - 1],
                    x_shape[rank - 2],
                    phi::errors::InvalidArgument(
                        "The input matrix must be batches of square matrices. "
                        "But received x's dimension: [%s]",
                        x_shape));
  PADDLE_ENFORCE_EQ(
      *UPLO == "L" || *UPLO == "U",
      true,
      phi::errors::InvalidArgument(
          "UPLO must be L or U. But received UPLO is: %s", UPLO->c_str()));
}

void EighPreProcess(Value* x, std::string* UPLO) {
  auto x_shape = pir::GetShapeFromValue(*x);
  int64_t rank = x_shape.size();
  PADDLE_ENFORCE_GE(rank,
                    2,
                    phi::errors::InvalidArgument(
                        "Input(input) only support >=2 tensor, but received "
                        "length of Input(input) is %ld.",
                        rank));
  if (x_shape[rank - 1] > 0 && x_shape[rank - 2] > 0) {
    PADDLE_ENFORCE_EQ(
        x_shape[rank - 1],
        x_shape[rank - 2],
        phi::errors::InvalidArgument(
            "The input matrix must be batches of square matrices. "
            "But received x's dimension."));
  }
  PADDLE_ENFORCE_EQ(
      *UPLO == "L" || *UPLO == "U",
      true,
      phi::errors::InvalidArgument(
          "UPLO must be L or U. But received UPLO is: %s", UPLO->c_str()));
}

void CholeskyPreProcess(Tensor* x, bool* upper) {
  auto x_shape = x->dims();
  int64_t rank = x_shape.size();
  PADDLE_ENFORCE_GE(
      rank,
      2,
      phi::errors::InvalidArgument("Shape must have at least 2 dimensions. "
                                   "But received x's dimension: %ld.",
                                   rank));
  PADDLE_ENFORCE_EQ(
      x_shape[rank - 1],
      x_shape[rank - 2],
      phi::errors::InvalidArgument("The last two dimensions must be equal. "
                                   "But received x's dimension: [%s]",
                                   x_shape));
}

void CholeskyPreProcess(Value* x, bool* upper) {
  auto x_shape = pir::GetShapeFromValue(*x);
  int64_t rank = x_shape.size();
  PADDLE_ENFORCE_GE(
      rank,
      2,
      phi::errors::InvalidArgument("Shape must have at least 2 dimensions. "
                                   "But received x's dimension: %ld.",
                                   rank));
  if (x_shape[rank - 1] > 0 && x_shape[rank - 2] > 0) {
    PADDLE_ENFORCE_EQ(
        x_shape[rank - 1],
        x_shape[rank - 2],
        phi::errors::InvalidArgument("The last two dimensions must be equal. "
                                     "But received x's dimension."));
  }
}

void MmOutDtypeInferMeta(const MetaTensor& x,
                         const MetaTensor& y,
                         DataType out_dtype,
                         MetaTensor* out,
                         MetaConfig config) {
  PADDLE_ENFORCE_EQ(
      out_dtype,
      DataType::FLOAT32,
      common::errors::InvalidArgument(
          "The out_dtype of paddle.mm currently only supports float32."));
  PADDLE_ENFORCE_EQ(
      x.dtype(),
      DataType::BFLOAT16,
      common::errors::InvalidArgument(
          "The out_dtype of paddle.mm currently only supports bfloat16 "
          "Input(X)."));
  PADDLE_ENFORCE_EQ(
      y.dtype(),
      DataType::BFLOAT16,
      common::errors::InvalidArgument(
          "The out_dtype of paddle.mm currently only supports bfloat16 "
          "Input(Y)."));

  auto dims_x = vectorize(x.dims());
  auto dims_y = vectorize(y.dims());
  PADDLE_ENFORCE_EQ(
      dims_x.size(),
      2UL,
      common::errors::InvalidArgument(
          "The out_dtype of paddle.mm currently only supports 2-D Input(X)."));
  PADDLE_ENFORCE_EQ(
      dims_y.size(),
      2UL,
      common::errors::InvalidArgument(
          "The out_dtype of paddle.mm currently only supports 2-D Input(Y)."));
  const int64_t K_lhs = dims_x[1];
  const int64_t K_rhs = dims_y[0];
  if (config.is_runtime || (K_lhs >= 0 && K_rhs >= 0)) {
    PADDLE_ENFORCE_EQ(
        K_lhs,
        K_rhs,
        common::errors::InvalidArgument(
            "Input(X)'s width must equal Input(Y)'s height, but received %d "
            "and %d.",
            K_lhs,
            K_rhs));
  }

  out->set_dims(make_ddim({dims_x[0], dims_y[1]}));
  out->set_dtype(DataType::FLOAT32);
  out->set_layout(x.layout());
  out->share_lod(x);
}

int AbsVal_loongarch::forward_inplace_bf16s_fp16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    // fp16/bf16 abs: sign bit is bit 15 for both formats.
    // Reinterpret pairs of 16-bit values as 32-bit and apply AND with
    // 0x7fff7fff to clear both sign bits in one 32-bit operation.
    // No fp32 round-trip required.

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __loongarch_sx
#if __loongarch_asx
        __m256i _sign_mask256 = (__m256i)__lasx_xvreplgr2vr_w(0x7fff7fff);
        for (; i + 15 < size; i += 16)
        {
            __m256i _p = __lasx_xvld(ptr, 0);
            __m256i _outp = __lasx_xvand_v(_p, _sign_mask256);
            __lasx_xvst(_outp, ptr, 0);

            ptr += 16;
        }
#endif // __loongarch_asx
        __m128i _sign_mask = (__m128i)__lsx_vreplgr2vr_w(0x7fff7fff);
        for (; i + 7 < size; i += 8)
        {
            __m128i _p = __lsx_vld(ptr, 0);
            __m128i _outp = __lsx_vand_v(_p, _sign_mask);
            __lsx_vst(_outp, ptr, 0);

            ptr += 8;
        }
#endif // __loongarch_sx
        for (; i < size; i++)
        {
            *ptr = *ptr & 0x7fffu;
            ptr++;
        }
    }

    return 0;
}

static void batchnorm_bf16s_lsx(unsigned short* ptr, const float* a, const float* b, int size, int elempack)
{
#if __loongarch_sx
    __m128 _a128 = (elempack == 4) ? (__m128)__lsx_vld(a, 0) : (__m128)__lsx_vreplfr2vr_s(a[0]);
    __m128 _b128 = (elempack == 4) ? (__m128)__lsx_vld(b, 0) : (__m128)__lsx_vreplfr2vr_s(b[0]);
#if !__loongarch_asx
    __m128 _a0 = _a128;
    __m128 _a1 = _a128;
    __m128 _b0 = _b128;
    __m128 _b1 = _b128;
    if (elempack == 8)
    {
        _a0 = (__m128)__lsx_vld(a, 0);
        _a1 = (__m128)__lsx_vld(a + 4, 0);
        _b0 = (__m128)__lsx_vld(b, 0);
        _b1 = (__m128)__lsx_vld(b + 4, 0);
    }
#endif // !__loongarch_asx
#if __loongarch_asx
    __m256 _a256 = (elempack == 8) ? (__m256)__lasx_xvld(a, 0) : __lasx_concat_128_s(_a128, _a128);
    __m256 _b256 = (elempack == 8) ? (__m256)__lasx_xvld(b, 0) : __lasx_concat_128_s(_b128, _b128);
#endif
#endif
    float sa = a[0];
    float sb = b[0];

    int i = 0;
#if __loongarch_sx
#if __loongarch_asx
    for (; i + 7 < size; i += 8)
    {
        __m256 _p = bfloat2float_lasx((__m128i)__lsx_vld(ptr, 0));
        _p = __lasx_xvfmadd_s(_p, _b256, _a256);
        __lsx_vst(float2bfloat_lasx(_p), ptr, 0);
        ptr += 8;
    }
#else  // __loongarch_asx
    {
        __m128i _zero = __lsx_vreplgr2vr_w(0);
        for (; i + 7 < size; i += 8)
        {
            __m128i _p01 = __lsx_vld(ptr, 0);
            __m128 _p0 = (__m128)__lsx_vilvl_h(_p01, _zero);
            __m128 _p1 = (__m128)__lsx_vilvh_h(_p01, _zero);
            _p0 = __lsx_vfmadd_s(_p0, _b0, _a0);
            _p1 = __lsx_vfmadd_s(_p1, _b1, _a1);
            __lsx_vst(float2bfloat_lsx(_p0, _p1), ptr, 0);
            ptr += 8;
        }
    }
#endif // __loongarch_asx
    for (; i + 3 < size; i += 4)
    {
        __m128 _p = bfloat2float_lsx(__lsx_vldrepl_d(ptr, 0));
        _p = __lsx_vfmadd_s(_p, _b128, _a128);
        __lsx_vstelm_d(float2bfloat_lsx(_p), ptr, 0, 0);
        ptr += 4;
    }
#endif // __loongarch_sx
    for (; i < size; i++)
    {
        *ptr = float32_to_bfloat16(sb * bfloat16_to_float32(*ptr) + sa);
        ptr++;
    }
}

static void batchnorm_bf16s_per_element_lsx(unsigned short* ptr, const float* a, const float* b, int size, int num_threads)
{
    int nn_size = 0;
    int remain_size_start = 0;
#if __loongarch_sx
#if __loongarch_asx
    nn_size = (size - remain_size_start) / 8;
    #pragma omp parallel for num_threads(num_threads)
    for (int ii = 0; ii < nn_size; ii++)
    {
        int i = remain_size_start + ii * 8;
        __m256 _p = bfloat2float_lasx((__m128i)__lsx_vld(ptr + i, 0));
        __m256 _a0 = (__m256)__lasx_xvld(a + i, 0);
        __m256 _b0 = (__m256)__lasx_xvld(b + i, 0);
        _p = __lasx_xvfmadd_s(_p, _b0, _a0);
        __lsx_vst(float2bfloat_lasx(_p), ptr + i, 0);
    }
    remain_size_start += nn_size * 8;
#else // __loongarch_asx
    nn_size = (size - remain_size_start) / 8;
    #pragma omp parallel for num_threads(num_threads)
    for (int ii = 0; ii < nn_size; ii++)
    {
        int i = remain_size_start + ii * 8;
        __m128i _zero = __lsx_vreplgr2vr_w(0);
        __m128i _p01 = __lsx_vld(ptr + i, 0);
        __m128 _p0 = (__m128)__lsx_vilvl_h(_p01, _zero);
        __m128 _p1 = (__m128)__lsx_vilvh_h(_p01, _zero);
        __m128 _a0 = (__m128)__lsx_vld(a + i, 0);
        __m128 _a1 = (__m128)__lsx_vld(a + i + 4, 0);
        __m128 _b0 = (__m128)__lsx_vld(b + i, 0);
        __m128 _b1 = (__m128)__lsx_vld(b + i + 4, 0);
        _p0 = __lsx_vfmadd_s(_p0, _b0, _a0);
        _p1 = __lsx_vfmadd_s(_p1, _b1, _a1);
        __lsx_vst(float2bfloat_lsx(_p0, _p1), ptr + i, 0);
    }
    remain_size_start += nn_size * 8;
#endif // __loongarch_asx
    nn_size = (size - remain_size_start) / 4;
    #pragma omp parallel for num_threads(num_threads)
    for (int ii = 0; ii < nn_size; ii++)
    {
        int i = remain_size_start + ii * 4;
        __m128 _p = bfloat2float_lsx(ptr + i);
        __m128 _a0 = (__m128)__lsx_vld(a + i, 0);
        __m128 _b0 = (__m128)__lsx_vld(b + i, 0);
        _p = __lsx_vfmadd_s(_p, _b0, _a0);
        __lsx_vstelm_d(float2bfloat_lsx(_p), ptr + i, 0, 0);
    }
    remain_size_start += nn_size * 4;
#endif // __loongarch_sx
    #pragma omp parallel for num_threads(num_threads)
    for (int i = remain_size_start; i < size; i++)
    {
        ptr[i] = float32_to_bfloat16(b[i] * bfloat16_to_float32(ptr[i]) + a[i]);
    }
}

int BatchNorm_loongarch::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int dims = bottom_top_blob.dims;
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int c = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;

    if (dims == 1)
    {
        unsigned short* ptr = bottom_top_blob;
        const float* aptr = a_data;
        const float* bptr = b_data;

        const int size = w * elempack;

        batchnorm_bf16s_per_element_lsx(ptr, aptr, bptr, size, opt.num_threads);
    }

    if (dims == 2)
    {
        const int size = w * elempack;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int i = 0; i < h; i++)
        {
            unsigned short* ptr = bottom_top_blob.row<unsigned short>(i);
            const float* aptr = (const float*)a_data + i * elempack;
            const float* bptr = (const float*)b_data + i * elempack;

            batchnorm_bf16s_lsx(ptr, aptr, bptr, size, elempack);
        }
    }

    if (dims == 3 || dims == 4)
    {
        const int size = w * h * d * elempack;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int q = 0; q < c; q++)
        {
            unsigned short* ptr = bottom_top_blob.channel(q);
            const float* aptr = (const float*)a_data + q * elempack;
            const float* bptr = (const float*)b_data + q * elempack;

            batchnorm_bf16s_lsx(ptr, aptr, bptr, size, elempack);
        }
    }

    return 0;
}

Bias_loongarch::Bias_loongarch()
{
#if __loongarch_sx
    support_packing = true;
    support_any_packing = true;
#endif
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

static void binary_op_vector_no_broadcast_bf16s(const unsigned short* ptr, const unsigned short* ptr1, unsigned short* outptr, int size)
{
    const Op op;

    int i = 0;
#if __loongarch_sx
