static void binary_op_vector_broadcast_pb_bf16s(const unsigned short* ptr, const unsigned short* ptr1, unsigned short* outptr, int w, int elempack)
{
    const Op op;

#if __loongarch_sx
#if __loongarch_asx
    if (elempack == 8)
    {
        for (int i = 0; i < w; i++)
        {
            __m256 _p = bfloat2float_lasx((__m128i)__lsx_vld(ptr, 0));
            __m256 _b = __lasx_xvreplfr2vr_s(bfloat16_to_float32(*ptr1));
            __m256 _outp = op(_p, _b);
            __lsx_vst(float2bfloat_lasx(_outp), outptr, 0);
            ptr += 8;
            ptr1 += 1;
            outptr += 8;
        }
    }
#else  // __loongarch_asx
    if (elempack == 8)
    {
        __m128i _zero = __lsx_vreplgr2vr_w(0);
        for (int i = 0; i < w; i++)
        {
            __m128i _p01 = __lsx_vld(ptr, 0);
            __m128 _p0 = (__m128)__lsx_vilvl_h(_p01, _zero);
            __m128 _p1 = (__m128)__lsx_vilvh_h(_p01, _zero);
            __m128 _b = (__m128)__lsx_vreplfr2vr_s(bfloat16_to_float32(*ptr1));
            __m128 _outp0 = op(_p0, _b);
            __m128 _outp1 = op(_p1, _b);
            __lsx_vst(float2bfloat_lsx(_outp0, _outp1), outptr, 0);
            ptr += 8;
            ptr1 += 1;
            outptr += 8;
        }
    }
#endif // __loongarch_asx

    if (elempack == 4)
    {
        int i = 0;
        __m128i _zero = __lsx_vreplgr2vr_w(0);
        for (; i + 1 < w; i += 2)
        {
            __m128i _p01 = __lsx_vld(ptr, 0);
            __m128 _p0 = (__m128)__lsx_vilvl_h(_p01, _zero);
            __m128 _p1 = (__m128)__lsx_vilvh_h(_p01, _zero);
            __m128 _b0 = (__m128)__lsx_vreplfr2vr_s(bfloat16_to_float32(ptr1[0]));
            __m128 _b1 = (__m128)__lsx_vreplfr2vr_s(bfloat16_to_float32(ptr1[1]));
            __m128 _outp0 = op(_p0, _b0);
            __m128 _outp1 = op(_p1, _b1);
            __lsx_vst(float2bfloat_lsx(_outp0, _outp1), outptr, 0);
            ptr += 8;
            ptr1 += 2;
            outptr += 8;
        }
        for (; i < w; i++)
        {
            __m128 _p = bfloat2float_lsx(__lsx_vldrepl_d(ptr, 0));
            __m128 _b = (__m128)__lsx_vreplfr2vr_s(bfloat16_to_float32(*ptr1));
            __m128 _outp = op(_p, _b);
            __lsx_vstelm_d(float2bfloat_lsx(_outp), outptr, 0, 0);
            ptr += 4;
            ptr1 += 1;
            outptr += 4;
        }
    }
#endif // __loongarch_sx
}

