static void binary_op_vector_bf16s(const unsigned short* ptr, const unsigned short* ptr1, unsigned short* outptr, int aw, int bw, int ap, int bp)
{
    const int w = std::max(aw, bw);
    const int elempack = std::max(ap, bp);
    const int size = w * elempack;

    if (ap == bp)
    {
        if (aw == bw)
            return binary_op_vector_no_broadcast_bf16s<Op>(ptr, ptr1, outptr, size);
        if (bw == 1)
            return binary_op_vector_broadcast_b_bf16s<Op>(ptr, ptr1, outptr, size, elempack);
        if (aw == 1)
            return binary_op_vector_broadcast_a_bf16s<Op>(ptr, ptr1, outptr, size, elempack);
    }

    if (bp == 1)
    {
        if (aw == bw)
            return binary_op_vector_broadcast_pb_bf16s<Op>(ptr, ptr1, outptr, w, elempack);
        if (bw == 1)
            return binary_op_vector_broadcast_pb_b_bf16s<Op>(ptr, ptr1, outptr, w, elempack);
        if (aw == 1)
            return binary_op_vector_broadcast_pb_a_bf16s<Op>(ptr, ptr1, outptr, w, elempack);
    }
}

static void binary_op_vector_bf16s(const unsigned short* ptr, const unsigned short* ptr1, unsigned short* outptr, int aw, int bw, int ap, int bp, int op_type)
{
    using namespace BinaryOp_loongarch_functor;

    if (op_type == BinaryOp::Operation_ADD) return binary_op_vector_bf16s<binary_op_add>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_SUB) return binary_op_vector_bf16s<binary_op_sub>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_MUL) return binary_op_vector_bf16s<binary_op_mul>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_DIV) return binary_op_vector_bf16s<binary_op_div>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_MAX) return binary_op_vector_bf16s<binary_op_max>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_MIN) return binary_op_vector_bf16s<binary_op_min>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_POW) return binary_op_vector_bf16s<binary_op_pow>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RSUB) return binary_op_vector_bf16s<binary_op_rsub>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RDIV) return binary_op_vector_bf16s<binary_op_rdiv>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RPOW) return binary_op_vector_bf16s<binary_op_rpow>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_ATAN2) return binary_op_vector_bf16s<binary_op_atan2>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RATAN2) return binary_op_vector_bf16s<binary_op_ratan2>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_FMOD) return binary_op_vector_bf16s<binary_op_fmod>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RFMOD) return binary_op_vector_bf16s<binary_op_rfmod>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_LOGADDEXP) return binary_op_vector_bf16s<binary_op_logaddexp>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_FLOOR_DIVIDE) return binary_op_vector_bf16s<binary_op_floor_divide>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RFLOOR_DIVIDE) return binary_op_vector_bf16s<binary_op_rfloor_divide>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_REMAINDER) return binary_op_vector_bf16s<binary_op_remainder>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RREMAINDER) return binary_op_vector_bf16s<binary_op_rremainder>(ptr, ptr1, outptr, aw, bw, ap, bp);

    // should never reach here
}

static void binary_op_scalar_bf16s(const Mat& a, unsigned short b, Mat& c, int op_type, const Option& opt)
{
    const int channels = a.c;
    const int size = a.w * a.h * a.d * a.elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        const unsigned short* ptr = a.channel(q);
        unsigned short* outptr = c.channel(q);

        binary_op_vector_bf16s(ptr, &b, outptr, size, 1, 1, 1, op_type);
    }
}

static void binary_op_no_broadcast_bf16s(const Mat& a, const Mat& b, Mat& c, int op_type, const Option& opt)
{
    const int channels = a.c;
    const int size = a.w * a.h * a.d * a.elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        const unsigned short* ptr = a.channel(q);
        const unsigned short* ptr1 = b.channel(q);
        unsigned short* outptr = c.channel(q);

        binary_op_vector_bf16s(ptr, ptr1, outptr, size, size, 1, 1, op_type);
    }
}

static void binary_op_broadcast_bf16s(const Mat& a, const Mat& b, Mat& c, int op_type, const Option& opt)
{
    if (b.w * b.h * b.d * b.c * b.elempack == 1)
    {
        return binary_op_scalar_bf16s(a, ((const unsigned short*)b)[0], c, op_type, opt);
    }

    if (a.dims == b.dims && a.w == b.w && a.h == b.h && a.d == b.d && a.c == b.c && a.elempack == b.elempack)
    {
        return binary_op_no_broadcast_bf16s(a, b, c, op_type, opt);
    }

    const int dims = c.dims;

    if (dims == 2)
    {
        const int h = c.h;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int y = 0; y < h; y++)
        {
            const int y0 = std::min(y, a.h - 1);
            const int y1 = std::min(y, b.h - 1);

            const unsigned short* ptr = a.row<const unsigned short>(y0);
            const unsigned short* ptr1 = b.row<const unsigned short>(y1);
            unsigned short* outptr = c.row<unsigned short>(y);

            binary_op_vector_bf16s(ptr, ptr1, outptr, a.w, b.w, a.elempack, b.elempack, op_type);
        }
    }

    if (dims == 3 || dims == 4)
    {
        const int channels = c.c;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int q = 0; q < channels; q++)
        {
            const int q0 = std::min(q, a.c - 1);
            const int q1 = std::min(q, b.c - 1);

            if (b.d * b.h * b.w == 1)
            {
                const unsigned short* ptr = a.channel(q0);
                const unsigned short* ptr1 = b.channel(q1);
                unsigned short* outptr = c.channel(q);

                binary_op_vector_bf16s(ptr, ptr1, outptr, a.w * a.h * a.d, 1, a.elempack, b.elempack, op_type);
                continue;
            }

            if (b.h * b.w == 1)
            {
                for (int z = 0; z < c.d; z++)
                {
                    const int z0 = std::min(z, a.d - 1);
                    const int z1 = std::min(z, b.d - 1);

                    const unsigned short* ptr = a.channel(q0).depth(z0);
                    const unsigned short* ptr1 = b.channel(q1).depth(z1);
                    unsigned short* outptr = c.channel(q).depth(z);

                    binary_op_vector_bf16s(ptr, ptr1, outptr, a.w * a.h, 1, a.elempack, b.elempack, op_type);
                }
                continue;
            }

            for (int z = 0; z < c.d; z++)
            {
                const int z0 = std::min(z, a.d - 1);
                const int z1 = std::min(z, b.d - 1);

                for (int y = 0; y < c.h; y++)
                {
                    const int y0 = std::min(y, a.h - 1);
                    const int y1 = std::min(y, b.h - 1);

                    const unsigned short* ptr = a.channel(q0).depth(z0).row<const unsigned short>(y0);
                    const unsigned short* ptr1 = b.channel(q1).depth(z1).row<const unsigned short>(y1);
                    unsigned short* outptr = c.channel(q).depth(z).row<unsigned short>(y);

                    binary_op_vector_bf16s(ptr, ptr1, outptr, a.w, b.w, a.elempack, b.elempack, op_type);
                }
            }
        }
    }
}

static void binary_op_scalar_inplace_bf16s(Mat& a, unsigned short b, int op_type, const Option& opt)
{
    const int channels = a.c;
    const int size = a.w * a.h * a.d * a.elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = a.channel(q);

        binary_op_vector_bf16s(ptr, &b, ptr, size, 1, 1, 1, op_type);
    }
}

int BinaryOp_loongarch::forward_bf16s(const std::vector<Mat>& bottom_blobs, std::vector<Mat>& top_blobs, const Option& opt) const
{
    const Mat& A = bottom_blobs[0];
    const Mat& B = bottom_blobs[1];
    const int outdims = std::max(A.dims, B.dims);

    Mat A2 = A;
    Mat B2 = B;
    if (A.dims < outdims)
    {
        // expand inner axes
        if (outdims == 2)
        {
            if (A.w * A.elempack == B.h * B.elempack)
                A2 = A.reshape(1, A.w, opt.workspace_allocator);
            else // if (A.w == B.w)
            {
                A2.dims = 2;
                A2.w = A.w * A.elempack;
                A2.elempack = 1;
                A2.elemsize = A.elemsize / A.elempack;
                A2.cstep = A.cstep * A.elempack;
            }
        }
        if (outdims == 3 && A.dims == 1)
        {
            if (A.w * A.elempack == B.c * B.elempack)
                A2 = A.reshape(1, 1, A.w, opt.workspace_allocator);
            else // if (A.w == B.w)
            {
                A2.dims = 3;
                A2.w = A.w * A.elempack;
                A2.elempack = 1;
                A2.elemsize = A.elemsize / A.elempack;
                A2.cstep = A.cstep * A.elempack;
            }
        }
        if (outdims == 3 && A.dims == 2)
            A2 = A.reshape(1, A.w, A.h, opt.workspace_allocator);
        if (outdims == 4 && A.dims == 1)
        {
            if (A.w * A.elempack == B.c * B.elempack)
                A2 = A.reshape(1, 1, 1, A.w, opt.workspace_allocator);
            else // if (A.w == B.w)
            {
                A2.dims = 4;
                A2.w = A.w * A.elempack;
                A2.elempack = 1;
                A2.elemsize = A.elemsize / A.elempack;
                A2.cstep = A.cstep * A.elempack;
            }
        }
        if (outdims == 4 && A.dims == 2)
            A2 = A.reshape(1, 1, A.w, A.h, opt.workspace_allocator);
        if (outdims == 4 && A.dims == 3)
            A2 = A.reshape(1, A.w, A.h, A.c, opt.workspace_allocator);
    }
    if (B.dims < outdims)
    {
        // expand inner axes
        if (outdims == 2)
        {
            if (B.w * B.elempack == A.h * A.elempack)
                B2 = B.reshape(1, B.w, opt.workspace_allocator);
            else // if (B.w == A.w)
            {
                B2.dims = 2;
                B2.w = B.w * B.elempack;
                B2.elempack = 1;
                B2.elemsize = B.elemsize / B.elempack;
                B2.cstep = B.cstep * B.elempack;
            }
        }
        if (outdims == 3 && B.dims == 1)
        {
            if (B.w * B.elempack == A.c * A.elempack)
                B2 = B.reshape(1, 1, B.w, opt.workspace_allocator);
            else // if (B.w == A.w)
            {
                B2.dims = 3;
                B2.w = B.w * B.elempack;
                B2.elempack = 1;
                B2.elemsize = B.elemsize / B.elempack;
                B2.cstep = B.cstep * B.elempack;
            }
        }
        if (outdims == 3 && B.dims == 2)
            B2 = B.reshape(1, B.w, B.h, opt.workspace_allocator);
        if (outdims == 4 && B.dims == 1)
        {
            if (B.w * B.elempack == A.c * A.elempack)
                B2 = B.reshape(1, 1, 1, B.w, opt.workspace_allocator);
            else // if (B.w == A.w)
            {
                B2.dims = 4;
                B2.w = B.w * B.elempack;
                B2.elempack = 1;
                B2.elemsize = B.elemsize / B.elempack;
                B2.cstep = B.cstep * B.elempack;
            }
        }
        if (outdims == 4 && B.dims == 2)
            B2 = B.reshape(1, 1, B.w, B.h, opt.workspace_allocator);
        if (outdims == 4 && B.dims == 3)
            B2 = B.reshape(1, B.w, B.h, B.c, opt.workspace_allocator);
    }

    const int outw = std::max(A2.w, B2.w);
    const int outh = std::max(A2.h, B2.h);
    const int outd = std::max(A2.d, B2.d);
    const int outc = std::max(A2.c, B2.c);
    const size_t out_elemsize = std::max(A2.elemsize, B2.elemsize);
    const int out_elempack = std::max(A2.elempack, B2.elempack);

    Mat& top_blob = top_blobs[0];
    if (outdims == 1)
    {
        top_blob.create(outw, out_elemsize, out_elempack, opt.blob_allocator);
    }
    if (outdims == 2)
    {
        top_blob.create(outw, outh, out_elemsize, out_elempack, opt.blob_allocator);
    }
    if (outdims == 3)
    {
        top_blob.create(outw, outh, outc, out_elemsize, out_elempack, opt.blob_allocator);
    }
    if (outdims == 4)
    {
        top_blob.create(outw, outh, outd, outc, out_elemsize, out_elempack, opt.blob_allocator);
    }
    if (top_blob.empty())
        return -100;

    const bool a_pack_is_lower = A2.elempack < B2.elempack;
    const bool a_pack_is_equal = A2.elempack == B2.elempack;
    const bool a_size_is_lower = A2.w * A2.h * A2.d * A2.c * A2.elempack < B2.w * B2.h * B2.d * B2.c * B2.elempack;
    if (a_pack_is_lower || (a_pack_is_equal && a_size_is_lower))
    {
        binary_op_broadcast_bf16s(B2, A2, top_blob, get_reverse_op_type(op_type), opt);
    }
    else
    {
        binary_op_broadcast_bf16s(A2, B2, top_blob, op_type, opt);
    }

    return 0;
}

int BinaryOp_loongarch::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    binary_op_scalar_inplace_bf16s(bottom_top_blob, float32_to_bfloat16(b), op_type, opt);

    return 0;
}

BNLL_loongarch::BNLL_loongarch()
{
#if __loongarch_sx
    support_packing = true;
    support_any_packing = true;
#endif
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int BNLL_loongarch::forward_inplace(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

#if NCNN_BF16
    if (opt.use_bf16_storage && bottom_top_blob.elembits() == 16)
        return forward_inplace_bf16s(bottom_top_blob, opt);
#endif

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        float* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __loongarch_sx
#if __loongarch_asx
        __m256 _zero8 = (__m256)__lasx_xvreplgr2vr_w(0);
        __m256 _one8 = (__m256)__lasx_xvreplfr2vr_s(1.f);
        __m256i _abs_mask8 = __lasx_xvreplgr2vr_w(0x7fffffff);
        for (; i + 7 < size; i += 8)
        {
            __builtin_prefetch(ptr + 32);

            __m256 _p = (__m256)__lasx_xvld(ptr, 0);
            __m256 _abs_p = (__m256)__lasx_xvand_v((__m256i)_p, _abs_mask8);
            __m256 _tmp = log256_ps(__lasx_xvfadd_s(_one8, exp256_ps((__m256)__lasx_xvbitrevi_w((__m256i)_abs_p, 31))));
            __m256 _outp = __lasx_xvfadd_s(__lasx_xvfmax_s(_p, _zero8), _tmp);
            __lasx_xvst(_outp, ptr, 0);

            ptr += 8;
        }
#endif
        __m128 _zero4 = (__m128)__lsx_vreplgr2vr_w(0);
        __m128 _one4 = (__m128)__lsx_vreplfr2vr_s(1.f);
        __m128i _abs_mask4 = __lsx_vreplgr2vr_w(0x7fffffff);
        for (; i + 3 < size; i += 4)
        {
            __builtin_prefetch(ptr + 16);

            __m128 _p = (__m128)__lsx_vld(ptr, 0);
            __m128 _abs_p = (__m128)__lsx_vand_v((__m128i)_p, _abs_mask4);
            __m128 _tmp = log_ps(__lsx_vfadd_s(_one4, exp_ps((__m128)__lsx_vbitrevi_w((__m128i)_abs_p, 31))));
            __m128 _outp = __lsx_vfadd_s(__lsx_vfmax_s(_p, _zero4), _tmp);
            __lsx_vst(_outp, ptr, 0);

            ptr += 4;
        }
#endif
        for (; i < size; i++)
        {
            if (*ptr > 0.f)
                *ptr = *ptr + logf(1.f + expf(-*ptr));
            else
                *ptr = logf(1.f + expf(*ptr));

            ptr++;
        }
    }

    return 0;
}

int BNLL_loongarch::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __loongarch_sx
#if __loongarch_asx
        for (; i + 7 < size; i += 8)
        {
            __m256 _p = bfloat2float_lasx((__m128i*)ptr);
            __m256 _zero = (__m256)__lasx_xvreplgr2vr_w(0);
            __m256 _one = (__m256)__lasx_xvreplfr2vr_s(1.f);
            __m256 _abs_p = (__m256)__lasx_xvand_v((__m256i)_p, __lasx_xvreplgr2vr_w(0x7fffffff));
            __m256 _tmp = log256_ps(__lasx_xvfadd_s(_one, exp256_ps((__m256)__lasx_xvbitrevi_w((__m256i)_abs_p, 31))));
            __m256 _outp = __lasx_xvfadd_s(__lasx_xvfmax_s(_p, _zero), _tmp);
            __lsx_vst(float2bfloat_lasx(_outp), ptr, 0);
            ptr += 8;
        }
#else // __loongarch_asx
        {
            __m128i _zero_raw = __lsx_vreplgr2vr_w(0);
            __m128 _zero = (__m128)_zero_raw;
            __m128 _one = (__m128)__lsx_vreplfr2vr_s(1.f);
            for (; i + 7 < size; i += 8)
            {
                __m128i _p01 = __lsx_vld(ptr, 0);
                __m128 _p0 = (__m128)__lsx_vilvl_h(_p01, _zero_raw);
                __m128 _p1 = (__m128)__lsx_vilvh_h(_p01, _zero_raw);
                __m128 _abs_p0 = (__m128)__lsx_vand_v((__m128i)_p0, __lsx_vreplgr2vr_w(0x7fffffff));
                __m128 _abs_p1 = (__m128)__lsx_vand_v((__m128i)_p1, __lsx_vreplgr2vr_w(0x7fffffff));
                __m128 _tmp0 = log_ps(__lsx_vfadd_s(_one, exp_ps((__m128)__lsx_vbitrevi_w((__m128i)_abs_p0, 31))));
                __m128 _tmp1 = log_ps(__lsx_vfadd_s(_one, exp_ps((__m128)__lsx_vbitrevi_w((__m128i)_abs_p1, 31))));
                __m128 _outp0 = __lsx_vfadd_s(__lsx_vfmax_s(_p0, _zero), _tmp0);
                __m128 _outp1 = __lsx_vfadd_s(__lsx_vfmax_s(_p1, _zero), _tmp1);
                __lsx_vst(float2bfloat_lsx(_outp0, _outp1), ptr, 0);
                ptr += 8;
            }
        }
#endif
        for (; i + 3 < size; i += 4)
        {
            __m128 _p = bfloat2float_lsx(__lsx_vldrepl_d(ptr, 0));
            __m128 _zero = (__m128)__lsx_vreplgr2vr_w(0);
            __m128 _one = (__m128)__lsx_vreplfr2vr_s(1.f);
            __m128 _abs_p = (__m128)__lsx_vand_v((__m128i)_p, __lsx_vreplgr2vr_w(0x7fffffff));
            __m128 _tmp = log_ps(__lsx_vfadd_s(_one, exp_ps((__m128)__lsx_vbitrevi_w((__m128i)_abs_p, 31))));
            __m128 _outp = __lsx_vfadd_s(__lsx_vfmax_s(_p, _zero), _tmp);
            __lsx_vstelm_d(float2bfloat_lsx(_outp), ptr, 0, 0);
            ptr += 4;
        }
#endif
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            if (v > 0)
                v = v + logf(1.f + expf(-v));
            else
                v = logf(1.f + expf(v));
            *ptr = float32_to_bfloat16(v);
            ptr++;
        }
    }

    return 0;
}

int Clip_loongarch::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __loongarch_sx
#if __loongarch_asx
        __m256 _min_lasx = (__m256)__lasx_xvreplfr2vr_s(min);
        __m256 _max_lasx = (__m256)__lasx_xvreplfr2vr_s(max);
        for (; i + 7 < size; i += 8)
        {
            __m256 _p = bfloat2float_lasx((__m128i)__lsx_vld(ptr, 0));
            _p = __lasx_xvfmax_s(_p, _min_lasx);
            _p = __lasx_xvfmin_s(_p, _max_lasx);
            __lsx_vst(float2bfloat_lasx(_p), ptr, 0);
            ptr += 8;
        }
#else  // __loongarch_asx
        {
            __m128i _zero = __lsx_vreplgr2vr_w(0);
            __m128 _min = (__m128)__lsx_vreplfr2vr_s(min);
            __m128 _max = (__m128)__lsx_vreplfr2vr_s(max);
            for (; i + 7 < size; i += 8)
            {
                __m128i _p01 = __lsx_vld(ptr, 0);
                __m128 _p0 = (__m128)__lsx_vilvl_h(_p01, _zero);
                __m128 _p1 = (__m128)__lsx_vilvh_h(_p01, _zero);
                _p0 = __lsx_vfmax_s(_p0, _min);
                _p1 = __lsx_vfmax_s(_p1, _min);
                _p0 = __lsx_vfmin_s(_p0, _max);
                _p1 = __lsx_vfmin_s(_p1, _max);
                __lsx_vst(float2bfloat_lsx(_p0, _p1), ptr, 0);
                ptr += 8;
            }
        }
#endif // __loongarch_asx
        __m128 _min = (__m128)__lsx_vreplfr2vr_s(min);
        __m128 _max = (__m128)__lsx_vreplfr2vr_s(max);
        for (; i + 3 < size; i += 4)
        {
            __m128 _p = bfloat2float_lsx(__lsx_vldrepl_d(ptr, 0));
            _p = __lsx_vfmax_s(_p, _min);
            _p = __lsx_vfmin_s(_p, _max);
            __lsx_vstelm_d(float2bfloat_lsx(_p), ptr, 0, 0);
            ptr += 4;
        }
#endif // __loongarch_sx
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            if (v < min) v = min;
            if (v > max) v = max;
            *ptr = float32_to_bfloat16(v);
            ptr++;
        }
    }

    return 0;
}

int Convolution1D_loongarch::create_pipeline_bf16s(const Option& opt)
{
    int num_input = weight_data_size / kernel_w / num_output;

    convolution1d_transform_kernel_packed_bf16s(weight_data, weight_data_tm, num_input, num_output, kernel_w);

    if (opt.lightmode)
        weight_data.release();

    return 0;
}

int Convolution1D_loongarch::forward_bf16s(const Mat& bottom_blob, Mat& top_blob, const Option& opt) const
{
    int w = bottom_blob.w;
    size_t elemsize = bottom_blob.elemsize;
    int elempack = bottom_blob.elempack;

    const int kernel_extent_w = dilation_w * (kernel_w - 1) + 1;

    Mat bottom_blob_bordered;
    make_padding(bottom_blob, bottom_blob_bordered, opt);
    if (bottom_blob_bordered.empty())
        return -100;

    w = bottom_blob_bordered.w;

    int out_elempack = 1;
#if __loongarch_sx
    if (opt.use_packing_layout)
    {
#if __loongarch_asx
        out_elempack = num_output % 8 == 0 ? 8 : num_output % 4 == 0 ? 4 : 1;
#else
        out_elempack = num_output % 8 == 0 ? 8 : num_output % 4 == 0 ? 4 : 1;
#endif
    }
#endif
    size_t out_elemsize = elemsize / elempack * out_elempack;

    const int outw = (w - kernel_extent_w) / stride_w + 1;
    const int outh = num_output / out_elempack;

    top_blob.create(outw, outh, out_elemsize, out_elempack, opt.blob_allocator);
    if (top_blob.empty())
        return -100;

    convolution1d_packed_bf16s(bottom_blob_bordered, top_blob, weight_data_tm, bias_data, kernel_w, dilation_w, stride_w, activation_type, activation_params, opt);

    return 0;
}

static bool test_prefer_winograd63(int num_input, int num_output, int w, int h)
{
    // winograd selection strategy (profiled on i7-7700 single thread)

    const int minwh = std::min(w, h);

    if (num_input >= 64)
    {
        return false;
    }
    if (num_input >= 32)
    {
        if (num_output >= 64) return false;
        if (num_output >= 32) return (minwh >= 11 && minwh <= 14)
                                         || (minwh >= 19 && minwh <= 20)
                                         || (minwh >= 23 && minwh <= 44)
                                         || (minwh >= 47 && minwh <= 56)
                                         || (minwh >= 63 && minwh <= 130);
        if (num_output >= 16) return (minwh >= 13 && minwh <= 14)
                                         || (minwh >= 19 && minwh <= 20)
                                         || (minwh >= 23 && minwh <= 38)
                                         || (minwh >= 43 && minwh <= 44)
                                         || (minwh >= 47 && minwh <= 140);
        if (num_output >= 8) return (minwh >= 11 && minwh <= 14)
                                        || (minwh >= 19 && minwh <= 20)
                                        || (minwh >= 31 && minwh <= 38)
                                        || (minwh >= 43 && minwh <= 44)
                                        || (minwh >= 55 && minwh <= 162);
        return false;
    }
    if (num_input >= 16)
    {
        if (num_output >= 64) return false;
        if (num_output >= 32) return (minwh >= 11 && minwh <= 14)
                                         || (minwh >= 19 && minwh <= 20)
                                         || (minwh >= 23 && minwh <= 44)
                                         || (minwh >= 47 && minwh <= 92)
                                         || (minwh >= 95 && minwh <= 188);
        if (num_output >= 16) return (minwh >= 11 && minwh <= 14)
                                         || (minwh >= 27 && minwh <= 38)
                                         || (minwh >= 43 && minwh <= 44)
                                         || (minwh >= 47 && minwh <= 74)
                                         || (minwh >= 81 && minwh <= 110)
                                         || (minwh >= 117 && minwh <= 170)
                                         || (minwh >= 177 && minwh <= 182);
        if (num_output >= 8) return (minwh >= 19 && minwh <= 20)
                                        || (minwh >= 33 && minwh <= 38)
                                        || (minwh >= 43 && minwh <= 44)
                                        || (minwh >= 47 && minwh <= 128)
                                        || (minwh >= 155 && minwh <= 210);
        return false;
    }
    if (num_input >= 8)
    {
        if (num_output >= 64) return false;
        if (num_output >= 32) return (minwh >= 7 && minwh <= 14)
                                         || (minwh >= 17 && minwh <= 20)
                                         || (minwh >= 23 && minwh <= 26)
                                         || (minwh >= 31 && minwh <= 38)
                                         || (minwh >= 43 && minwh <= 162);
        if (num_output >= 16) return minwh == 31 || minwh == 32
                                         || (minwh >= 39 && minwh <= 44)
                                         || (minwh >= 47 && minwh <= 212);
        if (num_output >= 8) return false;
        return false;
    }

    return false;
}

static bool test_prefer_winograd23(int num_input, int num_output, int w, int h)
{
    // winograd selection strategy (profiled on i7-7700 single thread)

    const int minwh = std::min(w, h);

    if (num_input >= 64)
    {
        return false;
    }
    if (num_input >= 32)
    {
        if (num_output >= 64) return false;
        if (num_output >= 32) return minwh >= 36;
        if (num_output >= 16) return minwh >= 28;
        if (num_output >= 8) return minwh >= 20;
        return false;
    }
    if (num_input >= 16)
    {
        if (num_output >= 64) return false;
        if (num_output >= 32) return minwh >= 24;
        if (num_output >= 16) return minwh >= 16;
        if (num_output >= 8) return minwh >= 12;
        return false;
    }
    if (num_input >= 8)
    {
        if (num_output >= 64) return false;
        if (num_output >= 32) return minwh >= 16;
        if (num_output >= 16) return minwh >= 8;
        if (num_output >= 8) return false;
        return false;
    }

    return false;
}

static bool get_winograd_input_shape(const Convolution* convolution, int& w, int& h)
{
    const bool bottom_shape_known = !convolution->bottom_shapes.empty() && convolution->bottom_shapes[0].w > 0 && convolution->bottom_shapes[0].h > 0;
    const bool top_shape_known = !convolution->top_shapes.empty() && convolution->top_shapes[0].w > 0 && convolution->top_shapes[0].h > 0;

    if (!bottom_shape_known && !top_shape_known)
        return false;

    if (top_shape_known)
    {
        w = convolution->top_shapes[0].w + 2;
        h = convolution->top_shapes[0].h + 2;
    }
    else
    {
        w = convolution->bottom_shapes[0].w;
        h = convolution->bottom_shapes[0].h;
    }

    return true;
}

static int select_winograd_mode(int num_input, int num_output, int w, int h, bool use_winograd23, bool use_winograd43, bool use_winograd63)
{
    bool prefer_winograd63 = test_prefer_winograd63(num_input, num_output, w, h);
    bool prefer_winograd23 = test_prefer_winograd23(num_input, num_output, w, h);
    bool prefer_winograd43 = !prefer_winograd63 && !prefer_winograd23;

    if (prefer_winograd23 && !use_winograd23)
    {
        prefer_winograd23 = false;
        prefer_winograd43 = true;
    }
    if (prefer_winograd63 && !use_winograd63)
    {
        prefer_winograd63 = false;
        prefer_winograd43 = true;
    }
    if (prefer_winograd43 && !use_winograd43)
    {
        prefer_winograd43 = false;
        if (use_winograd63)
            prefer_winograd63 = true;
        else if (use_winograd23)
            prefer_winograd23 = true;
    }

    if (prefer_winograd23)
        return 23;
    if (prefer_winograd43)
        return 43;
    if (prefer_winograd63)
        return 63;

    return 0;
}

int Convolution_loongarch::forward(const std::vector<Mat>& bottom_blobs, std::vector<Mat>& top_blobs, const Option& opt) const
{
    const Mat& bottom_blob = bottom_blobs[0];
    const Mat& _weight_data = bottom_blobs[1];
    Mat& top_blob = top_blobs[0];
#if NCNN_BF16
    if (opt.use_bf16_storage && weight_data_flattened.elembits() == 16)
    {
        Mat weight_data_flattened_fp32;
        cast_bfloat16_to_float32(weight_data_flattened, weight_data_flattened_fp32, opt);
        weight_data_flattened = weight_data_flattened_fp32;
        if (weight_data_flattened.empty())
            return -100;
    }
#endif

#if NCNN_BF16
        if (opt.use_bf16_storage && bias_data_flattened.elembits() == 16)
        {
            Mat bias_data_flattened_fp32;
            cast_bfloat16_to_float32(bias_data_flattened, bias_data_flattened_fp32, opt);
            bias_data_flattened = bias_data_flattened_fp32;
            if (bias_data_flattened.empty())
                return -100;
        }
#endif

    nT = opt.num_threads;
    bool prefer_winograd = (opt.use_winograd23_convolution || opt.use_winograd43_convolution) && (num_input > 8 || num_output > 8);
    if (opt.use_winograd_convolution && prefer_winograd && kernel_w == 3 && kernel_h == 3 && dilation_w == 1 && dilation_h == 1 && stride_w == 1 && stride_h == 1)
        if (opt.use_winograd43_convolution)
            conv3x3s1_winograd43_transform_kernel_int8(weight_data, weight_winograd43_data, num_input, num_output, opt);
            conv3x3s1_winograd23_transform_kernel_int8(weight_data, weight_winograd23_data, num_input, num_output, opt);
    else if (opt.use_sgemm_convolution)
        convolution_im2col_gemm_transform_kernel_int8(weight_data, weight_sgemm_data, num_input, num_output, kernel_w, kernel_h, opt);
    else
        convolution_transform_kernel_packed_int8(weight_data, weight_data_tm, num_input, num_output, kernel_w, kernel_h);
#if NCNN_BF16
    if (opt.use_bf16_storage)
        out_elemsize = use_int8_requantize ? 1u * out_elempack : 2u * out_elempack;
#endif
    bool prefer_winograd = (opt.use_winograd23_convolution || opt.use_winograd43_convolution) && (num_input > 8 || num_output > 8);

    if (opt.use_winograd_convolution && prefer_winograd && kernel_w == 3 && kernel_h == 3 && dilation_w == 1 && dilation_h == 1 && stride_w == 1 && stride_h == 1)
        int _nT = nT ? nT : opt.num_threads;
        if (nT != 0 && opt.num_threads != nT)
            // force num_threads the same as in create_pipeline
            // so we could use pre-packed A/B from the same tile config
            NCNN_LOGE("opt.num_threads %d changed, convolution gemm will use load-time value %d", opt.num_threads, nT);

        int ret = 0;
        if (!weight_winograd43_data.empty())
            ret = conv3x3s1_winograd43_int8(bottom_blob_bordered, top_blob_int32, weight_winograd43_data, _nT, opt);
            ret = conv3x3s1_winograd23_int8(bottom_blob_bordered, top_blob_int32, weight_winograd23_data, _nT, opt);
        if (ret != 0)
            return ret;
    }

int Convolution_loongarch::create_pipeline_bf16s(const Option& opt)
{
    const int maxk = kernel_w * kernel_h;
    const int num_input = weight_data_size / maxk / num_output;

    nT = opt.num_threads;

    bool prefer_winograd = (opt.use_winograd23_convolution || opt.use_winograd43_convolution || opt.use_winograd63_convolution) && (num_input > 8 || num_output > 8);

    if (opt.use_winograd_convolution && prefer_winograd && kernel_w == 3 && kernel_h == 3 && dilation_w == 1 && dilation_h == 1 && stride_w == 1 && stride_h == 1)
    {
        if ((bottom_shapes.empty() || bottom_shapes[0].w == 0 || bottom_shapes[0].h == 0) && (top_shapes.empty() || top_shapes[0].w == 0 || top_shapes[0].h == 0))
            if ((opt.use_winograd63_convolution) && (num_input <= 32 && num_output <= 32))
                conv3x3s1_winograd63_transform_kernel(weight_data, weight_winograd63_data, num_input, num_output, opt);
            else if (opt.use_winograd43_convolution)
                conv3x3s1_winograd43_transform_kernel(weight_data, weight_winograd43_data, num_input, num_output, opt);
            else
                conv3x3s1_winograd23_transform_kernel(weight_data, weight_winograd23_data, num_input, num_output, opt);
            int w;
            int h;
            if (top_shapes.empty() || top_shapes[0].w == 0 || top_shapes[0].h == 0)
            {
                w = bottom_shapes[0].w;
                h = bottom_shapes[0].h;

                if (pad_left > 0 || pad_right > 0 || pad_top > 0 || pad_bottom > 0)
                {
                    w += pad_left + pad_right;
                    h += pad_top + pad_bottom;
                }
                else if ((pad_left == -233 && pad_right == -233 && pad_top == -233 && pad_bottom == -233)
                         || (pad_left == -234 && pad_right == -234 && pad_top == -234 && pad_bottom == -234))
                {
                    w += 2;
                    h += 2;
                }
            }
            else
            {
                w = top_shapes[0].w + 2;
                h = top_shapes[0].h + 2;
            }

            bool prefer_winograd63 = test_prefer_winograd63(num_input, num_output, w, h);
            bool prefer_winograd23 = test_prefer_winograd23(num_input, num_output, w, h);
            bool prefer_winograd43 = !prefer_winograd63 && !prefer_winograd23;

            if (prefer_winograd23 && !opt.use_winograd23_convolution)
            {
                prefer_winograd23 = false;
                prefer_winograd43 = true;
            }
            if (prefer_winograd63 && !opt.use_winograd63_convolution)
            {
                prefer_winograd63 = false;
                prefer_winograd43 = true;
            }
            if (prefer_winograd43 && !opt.use_winograd43_convolution)
            {
                prefer_winograd43 = false;
                if (opt.use_winograd63_convolution)
                    prefer_winograd63 = true;
                else
                    prefer_winograd23 = true;
            }

            if (prefer_winograd23)
                conv3x3s1_winograd23_transform_kernel(weight_data, weight_winograd23_data, num_input, num_output, opt);
            else if (prefer_winograd43)
                conv3x3s1_winograd43_transform_kernel(weight_data, weight_winograd43_data, num_input, num_output, opt);
            else if (prefer_winograd63)
                conv3x3s1_winograd63_transform_kernel(weight_data, weight_winograd63_data, num_input, num_output, opt);

        if (opt.lightmode)
            weight_data.release();

        return 0;
    int l2_cache_size = get_cpu_level2_cache_size();
    bool prefer_sgemm = num_input * num_output * kernel_w * kernel_h * dilation_w * dilation_h * stride_w * stride_h * (int)sizeof(unsigned short) * 2 > l2_cache_size || (num_input > 16 || num_output > 16);

    if ((opt.use_sgemm_convolution && prefer_sgemm) || (kernel_w == 1 && kernel_h == 1))
        convolution_im2col_gemm_transform_kernel_bf16s(weight_data, weight_sgemm_data, num_input, num_output, kernel_w, kernel_h, opt);

        if (opt.lightmode)
            weight_data.release();

        return 0;
    }

    convolution_transform_kernel_packed_bf16s(weight_data, weight_data_tm, num_input, num_output, kernel_w, kernel_h);

    if (opt.lightmode)
        weight_data.release();

    return 0;
}

GridSample_loongarch::GridSample_loongarch()
{
#if __loongarch_sx
    support_packing = true;
#endif // __loongarch_sx
}

GroupNorm_loongarch::GroupNorm_loongarch()
{
#if __loongarch_sx
    support_packing = true;
    support_any_packing = true;
#endif // __loongarch_sx
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int GroupNorm_loongarch::forward_inplace(Mat& bottom_top_blob, const Option& opt) const
{
#if NCNN_BF16
    if (opt.use_bf16_storage && bottom_top_blob.elembits() == 16)
        return forward_inplace_bf16s(bottom_top_blob, opt);
#endif

    const int dims = bottom_top_blob.dims;
    const int elempack = bottom_top_blob.elempack;
    const int channels_g = channels / group;

    int g_elempack = elempack;
#if __loongarch_sx
#if __loongarch_asx
    if (opt.use_packing_layout && elempack == 8 && channels_g % 8 != 0)
        g_elempack = channels_g % 4 == 0 ? 4 : 1;
#endif // __loongarch_asx
    if (opt.use_packing_layout && g_elempack == 4 && channels_g % 4 != 0)
        g_elempack = 1;
#endif // __loongarch_sx

    Mat bottom_top_blob_packed = bottom_top_blob;
    if (elempack != g_elempack)
    {
        Option opt_pack = opt;
        opt_pack.blob_allocator = opt.workspace_allocator;

        convert_packing(bottom_top_blob, bottom_top_blob_packed, g_elempack, opt_pack);
        if (bottom_top_blob_packed.empty())
            return -100;
    }

    if (dims == 1)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int g = 0; g < group; g++)
        {
            Mat bottom_top_blob_g = bottom_top_blob_packed.range(g * channels_g / g_elempack, channels_g / g_elempack);
            const float* gamma_ptr = affine ? (const float*)gamma_data + g * channels_g : 0;
            const float* beta_ptr = affine ? (const float*)beta_data + g * channels_g : 0;
            groupnorm_loongarch(bottom_top_blob_g, gamma_ptr, beta_ptr, eps, channels_g / g_elempack, g_elempack, g_elempack, 1);
        }
    }

    if (dims == 2)
    {
        const int w = bottom_top_blob_packed.w;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int g = 0; g < group; g++)
        {
            Mat bottom_top_blob_g = bottom_top_blob_packed.row_range(g * channels_g / g_elempack, channels_g / g_elempack);
            const float* gamma_ptr = affine ? (const float*)gamma_data + g * channels_g : 0;
            const float* beta_ptr = affine ? (const float*)beta_data + g * channels_g : 0;
            groupnorm_loongarch(bottom_top_blob_g, gamma_ptr, beta_ptr, eps, channels_g / g_elempack, w * g_elempack, g_elempack, w);
        }
    }

    if (dims == 3 || dims == 4)
    {
        const int size = bottom_top_blob_packed.w * bottom_top_blob_packed.h * bottom_top_blob_packed.d;
        const size_t cstep = bottom_top_blob_packed.cstep;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int g = 0; g < group; g++)
        {
            Mat bottom_top_blob_g = bottom_top_blob_packed.channel_range(g * channels_g / g_elempack, channels_g / g_elempack);
            const float* gamma_ptr = affine ? (const float*)gamma_data + g * channels_g : 0;
            const float* beta_ptr = affine ? (const float*)beta_data + g * channels_g : 0;
            groupnorm_loongarch(bottom_top_blob_g, gamma_ptr, beta_ptr, eps, channels_g / g_elempack, size * g_elempack, g_elempack, cstep);
        }
    }

    if (g_elempack != elempack)
    {
        convert_packing(bottom_top_blob_packed, bottom_top_blob, elempack, opt);
        if (bottom_top_blob.empty())
            return -100;
    }

    return 0;
}

int GroupNorm_loongarch::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    const int dims = bottom_top_blob.dims;
    const int elempack = bottom_top_blob.elempack;
    const int channels_g = channels / group;

    int g_elempack = elempack;
#if __loongarch_sx
    if (opt.use_packing_layout && elempack == 8 && channels_g % 8 != 0)
        g_elempack = channels_g % 4 == 0 ? 4 : 1;
    if (opt.use_packing_layout && g_elempack == 4 && channels_g % 4 != 0)
        g_elempack = 1;
#endif // __loongarch_sx

    Mat bottom_top_blob_packed = bottom_top_blob;
    if (elempack != g_elempack)
    {
        Option opt_pack = opt;
        opt_pack.blob_allocator = opt.workspace_allocator;

        convert_packing(bottom_top_blob, bottom_top_blob_packed, g_elempack, opt_pack);
        if (bottom_top_blob_packed.empty())
            return -100;
    }

    if (dims == 1)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int g = 0; g < group; g++)
        {
            Mat bottom_top_blob_g = bottom_top_blob_packed.range(g * channels_g / g_elempack, channels_g / g_elempack);
            const float* gamma_ptr = affine ? (const float*)gamma_data + g * channels_g : 0;
            const float* beta_ptr = affine ? (const float*)beta_data + g * channels_g : 0;
            groupnorm_loongarch_bf16(bottom_top_blob_g, gamma_ptr, beta_ptr, eps, channels_g / g_elempack, g_elempack, g_elempack, 1);
        }
    }

    if (dims == 2)
    {
        const int w = bottom_top_blob_packed.w;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int g = 0; g < group; g++)
        {
            unsigned short* ptr_g = (unsigned short*)bottom_top_blob_packed.row(g * channels_g / g_elempack);
            const float* gamma_ptr = affine ? (const float*)gamma_data + g * channels_g : 0;
            const float* beta_ptr = affine ? (const float*)beta_data + g * channels_g : 0;
            groupnorm_loongarch_bf16(ptr_g, gamma_ptr, beta_ptr, eps, channels_g / g_elempack, w * g_elempack, g_elempack, w);
        }
    }

    if (dims == 3 || dims == 4)
    {
        const int size = bottom_top_blob_packed.w * bottom_top_blob_packed.h * bottom_top_blob_packed.d;
        const size_t cstep = bottom_top_blob_packed.cstep;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int g = 0; g < group; g++)
        {
            unsigned short* ptr_g = (unsigned short*)bottom_top_blob_packed.channel(g * channels_g / g_elempack);
            const float* gamma_ptr = affine ? (const float*)gamma_data + g * channels_g : 0;
            const float* beta_ptr = affine ? (const float*)beta_data + g * channels_g : 0;
            groupnorm_loongarch_bf16(ptr_g, gamma_ptr, beta_ptr, eps, channels_g / g_elempack, size * g_elempack, g_elempack, cstep);
        }
    }

    if (g_elempack != elempack)
    {
        Option opt_pack = opt;
        opt_pack.blob_allocator = opt.workspace_allocator;

        Mat bottom_top_blob_unpacked;
        convert_packing(bottom_top_blob_packed, bottom_top_blob_unpacked, elempack, opt_pack);
        if (bottom_top_blob_unpacked.empty())
            return -100;
        bottom_top_blob = bottom_top_blob_unpacked;
    }

    return 0;
}

int HardSigmoid_loongarch::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __loongarch_sx
#if __loongarch_asx
        __m256 _zero8 = (__m256)__lasx_xvreplgr2vr_w(0);
        __m256 _one8 = (__m256)__lasx_xvreplfr2vr_s(1.f);
        __m256 _alpha8 = (__m256)__lasx_xvreplfr2vr_s(alpha);
        __m256 _beta8 = (__m256)__lasx_xvreplfr2vr_s(beta);
        for (; i + 7 < size; i += 8)
        {
            __m256 _p = bfloat2float_lasx((__m128i*)ptr);
            _p = __lasx_xvfmadd_s(_alpha8, _p, _beta8);
            _p = __lasx_xvfmax_s(_p, _zero8);
            _p = __lasx_xvfmin_s(_p, _one8);
            __lsx_vst(float2bfloat_lasx(_p), ptr, 0);
            ptr += 8;
        }
#else  // __loongarch_asx
        {
            __m128i _zero_raw = __lsx_vreplgr2vr_w(0);
            __m128 _zero4 = (__m128)_zero_raw;
            __m128 _one4 = (__m128)__lsx_vreplfr2vr_s(1.f);
            __m128 _alpha4 = (__m128)__lsx_vreplfr2vr_s(alpha);
            __m128 _beta4 = (__m128)__lsx_vreplfr2vr_s(beta);
            for (; i + 7 < size; i += 8)
            {
                __m128i _p01 = __lsx_vld(ptr, 0);
                __m128 _p0 = (__m128)__lsx_vilvl_h(_p01, _zero_raw);
                __m128 _p1 = (__m128)__lsx_vilvh_h(_p01, _zero_raw);
                _p0 = __lsx_vfmadd_s(_alpha4, _p0, _beta4);
                _p1 = __lsx_vfmadd_s(_alpha4, _p1, _beta4);
                _p0 = __lsx_vfmax_s(_p0, _zero4);
                _p1 = __lsx_vfmax_s(_p1, _zero4);
                _p0 = __lsx_vfmin_s(_p0, _one4);
                _p1 = __lsx_vfmin_s(_p1, _one4);
                __lsx_vst(float2bfloat_lsx(_p0, _p1), ptr, 0);
                ptr += 8;
            }
        }
#endif // __loongarch_asx
        __m128 _zero4 = (__m128)__lsx_vreplgr2vr_w(0);
        __m128 _one4 = (__m128)__lsx_vreplfr2vr_s(1.f);
        __m128 _alpha4 = (__m128)__lsx_vreplfr2vr_s(alpha);
        __m128 _beta4 = (__m128)__lsx_vreplfr2vr_s(beta);
        for (; i + 3 < size; i += 4)
        {
            __m128 _p = bfloat2float_lsx(__lsx_vldrepl_d(ptr, 0));
            _p = __lsx_vfmadd_s(_alpha4, _p, _beta4);
            _p = __lsx_vfmax_s(_p, _zero4);
            _p = __lsx_vfmin_s(_p, _one4);
            __lsx_vstelm_d(float2bfloat_lsx(_p), ptr, 0, 0);
            ptr += 4;
        }
#endif // __loongarch_sx
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            if (v < lower)
                v = 0.f;
            else if (v > upper)
                v = 1.f;
            else
                v = v * alpha + beta;
            *ptr = float32_to_bfloat16(v);
            ++ptr;
        }
    }

    return 0;
}

int HardSwish_loongarch::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __loongarch_sx
#if __loongarch_asx
        __m256 _zero8 = (__m256)__lasx_xvreplgr2vr_w(0);
        __m256 _one8 = (__m256)__lasx_xvreplfr2vr_s(1.f);
        __m256 _alpha8 = (__m256)__lasx_xvreplfr2vr_s(alpha);
        __m256 _beta8 = (__m256)__lasx_xvreplfr2vr_s(beta);
        for (; i + 7 < size; i += 8)
        {
            __m256 _p = bfloat2float_lasx((__m128i*)ptr);
            __m256 _outp = __lasx_xvfmadd_s(_alpha8, _p, _beta8);
            _outp = __lasx_xvfmax_s(_outp, _zero8);
            _outp = __lasx_xvfmin_s(_outp, _one8);
            _outp = __lasx_xvfmul_s(_outp, _p);
            __lsx_vst(float2bfloat_lasx(_outp), ptr, 0);
            ptr += 8;
        }
#else  // __loongarch_asx
        {
            __m128i _zero_raw = __lsx_vreplgr2vr_w(0);
            __m128 _zero4 = (__m128)_zero_raw;
            __m128 _one4 = (__m128)__lsx_vreplfr2vr_s(1.f);
            __m128 _alpha4 = (__m128)__lsx_vreplfr2vr_s(alpha);
            __m128 _beta4 = (__m128)__lsx_vreplfr2vr_s(beta);
            for (; i + 7 < size; i += 8)
            {
                __m128i _p01 = __lsx_vld(ptr, 0);
                __m128 _p0 = (__m128)__lsx_vilvl_h(_p01, _zero_raw);
                __m128 _p1 = (__m128)__lsx_vilvh_h(_p01, _zero_raw);
                __m128 _outp0 = __lsx_vfmadd_s(_alpha4, _p0, _beta4);
                __m128 _outp1 = __lsx_vfmadd_s(_alpha4, _p1, _beta4);
                _outp0 = __lsx_vfmax_s(_outp0, _zero4);
                _outp1 = __lsx_vfmax_s(_outp1, _zero4);
                _outp0 = __lsx_vfmin_s(_outp0, _one4);
                _outp1 = __lsx_vfmin_s(_outp1, _one4);
                _outp0 = __lsx_vfmul_s(_outp0, _p0);
                _outp1 = __lsx_vfmul_s(_outp1, _p1);
                __lsx_vst(float2bfloat_lsx(_outp0, _outp1), ptr, 0);
                ptr += 8;
            }
        }
#endif // __loongarch_asx
        __m128 _zero4 = (__m128)__lsx_vreplgr2vr_w(0);
        __m128 _one4 = (__m128)__lsx_vreplfr2vr_s(1.f);
        __m128 _alpha4 = (__m128)__lsx_vreplfr2vr_s(alpha);
        __m128 _beta4 = (__m128)__lsx_vreplfr2vr_s(beta);
        for (; i + 3 < size; i += 4)
        {
            __m128 _p = bfloat2float_lsx(__lsx_vldrepl_d(ptr, 0));
            __m128 _outp = __lsx_vfmadd_s(_alpha4, _p, _beta4);
            _outp = __lsx_vfmax_s(_outp, _zero4);
            _outp = __lsx_vfmin_s(_outp, _one4);
            _outp = __lsx_vfmul_s(_outp, _p);
            __lsx_vstelm_d(float2bfloat_lsx(_outp), ptr, 0, 0);
            ptr += 4;
        }
#endif // __loongarch_sx
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            if (v < lower)
                v = 0.f;
            else if (v > upper)
                ;
            else
                v = v * (v * alpha + beta);
            *ptr = float32_to_bfloat16(v);
            ++ptr;
        }
    }

    return 0;
}

int InnerProduct_loongarch::create_pipeline_bf16s(const Option& opt)
{
    const int num_input = weight_data_size / num_output;

    innerproduct_transform_kernel_bf16s_lsx(weight_data, weight_data_tm, num_input, num_output, opt);

    if (opt.lightmode)
        weight_data.release();

    return 0;
}

int InnerProduct_loongarch::forward_bf16s(const Mat& bottom_blob, Mat& top_blob, const Option& opt) const
{
    const int num_input = weight_data_size / num_output;

    if (bottom_blob.dims == 2 && bottom_blob.w == num_input)
    {
        // gemm
        int h = bottom_blob.h;
        size_t elemsize = bottom_blob.elemsize;
        int elempack = bottom_blob.elempack;

        top_blob.create(num_output, h, elemsize, elempack, opt.blob_allocator);
        if (top_blob.empty())
            return -100;

        innerproduct_gemm_bf16s_lsx(bottom_blob, top_blob, weight_data_tm, bias_data, activation_type, activation_params, opt);

        return 0;
    }

    // flatten
    Mat bottom_blob_flattened = bottom_blob;
    if (bottom_blob.dims != 1)
    {
        Option opt_flatten = opt;
        opt_flatten.blob_allocator = opt.workspace_allocator;

        flatten->forward(bottom_blob, bottom_blob_flattened, opt_flatten);
        if (bottom_blob_flattened.empty())
            return -100;
    }

    size_t elemsize = bottom_blob_flattened.elemsize;
    int elempack = bottom_blob_flattened.elempack;

    int out_elempack = 1;
#if __loongarch_sx
    if (opt.use_packing_layout)
    {
#if __loongarch_asx
        out_elempack = num_output % 8 == 0 ? 8 : num_output % 4 == 0 ? 4 : 1;
#else
        out_elempack = num_output % 8 == 0 ? 8 : num_output % 4 == 0 ? 4 : 1;
#endif
    }
#endif
    size_t out_elemsize = elemsize / elempack * out_elempack;

    top_blob.create(num_output / out_elempack, out_elemsize, out_elempack, opt.blob_allocator);
    if (top_blob.empty())
        return -100;

    innerproduct_bf16s_lsx(bottom_blob_flattened, top_blob, weight_data_tm, bias_data, activation_type, activation_params, opt);

    return 0;
}

InstanceNorm_loongarch::InstanceNorm_loongarch()
{
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int InstanceNorm_loongarch::forward_inplace(Mat& bottom_top_blob, const Option& opt) const
{
#if NCNN_BF16
    if (opt.use_bf16_storage && bottom_top_blob.elembits() == 16)
        return forward_inplace_bf16s(bottom_top_blob, opt);
#endif

    // x = (x - mean) / (sqrt(var + eps)) * gamma + beta

    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int c = bottom_top_blob.c;
    int size = w * h;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < c; q++)
    {
        float* ptr = bottom_top_blob.channel(q);
        const float* ptr0 = ptr;

        // mean and var
        float sum = 0.f;
        float sqsum = 0.f;

        int i = 0;
#if __loongarch_sx
#if __loongarch_asx
        __m256 _sum_lasx = (__m256)__lasx_xvreplfr2vr_s(0.f);
        for (; i + 7 < size; i += 8)
        {
            __m256 _p = (__m256)__lasx_xvld(ptr0, 0);
            _sum_lasx = __lasx_xvfadd_s(_sum_lasx, _p);
            ptr0 += 8;
        }
        sum += __lasx_reduce_fadd_s(_sum_lasx);
#endif // __loongarch_asx
        __m128 _sum = (__m128)__lsx_vreplfr2vr_s(0.f);
        for (; i + 3 < size; i += 4)
        {
            __m128 _p = (__m128)__lsx_vld(ptr0, 0);
            _sum = __lsx_vfadd_s(_sum, _p);
            ptr0 += 4;
        }
        sum += __lsx_reduce_fadd_s(_sum);
#endif // __loongarch_sx
        for (; i < size; i++)
        {
            sum += ptr0[0];
            ptr0++;
        }

        float mean = sum / size;
        float tmp = 0.f;

        ptr0 = ptr;
        i = 0;
#if __loongarch_sx
#if __loongarch_asx
        __m256 _sqsum_lasx = (__m256)__lasx_xvreplfr2vr_s(0.f);
        __m256 _mean_lasx = (__m256)__lasx_xvreplfr2vr_s(mean);
        for (; i + 7 < size; i += 8)
        {
            __m256 _p = (__m256)__lasx_xvld(ptr0, 0);
            _p = __lasx_xvfsub_s(_p, _mean_lasx);
            _sqsum_lasx = __lasx_xvfmadd_s(_p, _p, _sqsum_lasx);
            ptr0 += 8;
        }
        sqsum += __lasx_reduce_fadd_s(_sqsum_lasx);
#endif // __loongarch_asx
        __m128 _sqsum = (__m128)__lsx_vreplfr2vr_s(0.f);
        __m128 _mean = (__m128)__lsx_vreplfr2vr_s(mean);
        for (; i + 3 < size; i += 4)
        {
            __m128 _p = (__m128)__lsx_vld(ptr0, 0);
            _p = __lsx_vfsub_s(_p, _mean);
            _sqsum = __lsx_vfmadd_s(_p, _p, _sqsum);
            ptr0 += 4;
        }
        sqsum += __lsx_reduce_fadd_s(_sqsum);
#endif // __loongarch_sx
        for (; i < size; i++)
        {
            tmp = ptr0[0] - mean;
            sqsum += tmp * tmp;
            ptr0++;
        }

        float var = sqsum / size;
        // the var maybe minus due to accuracy

        float a;
        float b;
        if (affine)
        {
            float gamma = gamma_data[q];
            float beta = beta_data[q];

            a = gamma / (sqrtf(var + eps));
            b = -mean * a + beta;
        }
        else
        {
            a = 1.f / (sqrtf(var + eps));
            b = -mean * a;
        }

        i = 0;
#if __loongarch_sx
#if __loongarch_asx
        __m256 _a_lasx = (__m256)__lasx_xvreplfr2vr_s(a);
        __m256 _b_lasx = (__m256)__lasx_xvreplfr2vr_s(b);
        for (; i + 7 < size; i += 8)
        {
            __m256 _p = (__m256)__lasx_xvld(ptr, 0);
            _p = __lasx_xvfmadd_s(_p, _a_lasx, _b_lasx);
            __lasx_xvst(_p, ptr, 0);
            ptr += 8;
        }
#endif // __loongarch_asx
        __m128 _a = (__m128)__lsx_vreplfr2vr_s(a);
        __m128 _b = (__m128)__lsx_vreplfr2vr_s(b);
        for (; i + 3 < size; i += 4)
        {
            __m128 _p = (__m128)__lsx_vld(ptr, 0);
            _p = __lsx_vfmadd_s(_p, _a, _b);
            __lsx_vst(_p, ptr, 0);
            ptr += 4;
        }
#endif // __loongarch_sx
        for (; i < size; i++)
        {
            ptr[0] = ptr[0] * a + b;
            ptr++;
        }
    }

    return 0;
}

static void interp_copy_bf16s(const unsigned short* ptr, unsigned short* outptr, int elempack)
{
#if __loongarch_sx
    if (elempack == 8)
    {
        __m128i _p = __lsx_vld(ptr, 0);
        __lsx_vst(_p, outptr, 0);
        return;
    }
#endif // __loongarch_sx

    for (int i = 0; i < elempack; i++)
    {
        outptr[i] = ptr[i];
    }
}

static void resize_bilinear_image_bf16s(const Mat& src, Mat& dst, float* alpha, int* xofs, float* beta, int* yofs)
{
    int w = dst.w;
    int h = dst.h;

    Mat rowsbuf0(w);
    Mat rowsbuf1(w);
    float* rows0 = rowsbuf0;
    float* rows1 = rowsbuf1;

    int prev_sy1 = -2;

    for (int dy = 0; dy < h; dy++)
    {
        int sy = yofs[dy];

        if (sy == prev_sy1)
        {
            // reuse all rows
        }
        else if (sy == prev_sy1 + 1)
        {
            // hresize one row
            float* rows0_old = rows0;
            rows0 = rows1;
            rows1 = rows0_old;
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx];
                const unsigned short* S1p = S1 + sx;

                float a0 = alphap[0];
                float a1 = alphap[1];
                rows1p[dx] = bfloat16_to_float32(S1p[0]) * a0 + bfloat16_to_float32(S1p[1]) * a1;

                alphap += 2;
            }
        }
        else
        {
            // hresize two rows
            const unsigned short* S0 = src.row<const unsigned short>(sy);
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows0p = rows0;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx];
                const unsigned short* S0p = S0 + sx;
                const unsigned short* S1p = S1 + sx;

                float a0 = alphap[0];
                float a1 = alphap[1];
                rows0p[dx] = bfloat16_to_float32(S0p[0]) * a0 + bfloat16_to_float32(S0p[1]) * a1;
                rows1p[dx] = bfloat16_to_float32(S1p[0]) * a0 + bfloat16_to_float32(S1p[1]) * a1;

                alphap += 2;
            }
        }

        prev_sy1 = sy;

        unsigned short* Dp = dst.row<unsigned short>(dy);

        int dx = 0;
#if __loongarch_sx
#if __loongarch_asx
        __m256 _b0_lasx = __lasx_xvreplfr2vr_s(beta[0]);
        __m256 _b1_lasx = __lasx_xvreplfr2vr_s(beta[1]);
        for (; dx + 7 < w; dx += 8)
        {
            __m256 _rows0 = (__m256)__lasx_xvld(rows0 + dx, 0);
            __m256 _rows1 = (__m256)__lasx_xvld(rows1 + dx, 0);
            __m256 _Dp = __lasx_xvfmul_s(_rows0, _b0_lasx);
            _Dp = __lasx_xvfmadd_s(_b1_lasx, _rows1, _Dp);
            __lsx_vst(float2bfloat_lasx(_Dp), Dp + dx, 0);
        }
#endif // __loongarch_asx
        __m128 _b0_lsx = (__m128)__lsx_vreplfr2vr_s(beta[0]);
        __m128 _b1_lsx = (__m128)__lsx_vreplfr2vr_s(beta[1]);
        for (; dx + 3 < w; dx += 4)
        {
            __m128 _rows0 = (__m128)__lsx_vld(rows0 + dx, 0);
            __m128 _rows1 = (__m128)__lsx_vld(rows1 + dx, 0);
            __m128 _Dp = __lsx_vfmul_s(_rows0, _b0_lsx);
            _Dp = __lsx_vfmadd_s(_b1_lsx, _rows1, _Dp);
            __lsx_vstelm_d(float2bfloat_lsx(_Dp), Dp + dx, 0, 0);
        }
#endif // __loongarch_sx
        for (; dx < w; dx++)
        {
            Dp[dx] = float32_to_bfloat16(rows0[dx] * beta[0] + rows1[dx] * beta[1]);
        }

        beta += 2;
    }
}

static void resize_bilinear_image_pack4_bf16s_lsx(const Mat& src, Mat& dst, float* alpha, int* xofs, float* beta, int* yofs)
{
    int w = dst.w;
    int h = dst.h;

    Mat rowsbuf0(w, (size_t)4 * 4u, 4);
    Mat rowsbuf1(w, (size_t)4 * 4u, 4);
    float* rows0 = rowsbuf0;
    float* rows1 = rowsbuf1;

    int prev_sy1 = -2;

    for (int dy = 0; dy < h; dy++)
    {
        int sy = yofs[dy];

        if (sy == prev_sy1)
        {
            // reuse all rows
        }
        else if (sy == prev_sy1 + 1)
        {
            // hresize one row
            float* rows0_old = rows0;
            rows0 = rows1;
            rows1 = rows0_old;
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx] * 4;
                const unsigned short* S1p = S1 + sx;

                __m128 _a0 = (__m128)__lsx_vreplfr2vr_s(alphap[0]);
                __m128 _a1 = (__m128)__lsx_vreplfr2vr_s(alphap[1]);

                __m128i _zero_bf16 = __lsx_vreplgr2vr_w(0);
                __m128i _S1 = __lsx_vld(S1p, 0);
                __m128 _S10 = (__m128)__lsx_vilvl_h(_S1, _zero_bf16);
                __m128 _S11 = (__m128)__lsx_vilvh_h(_S1, _zero_bf16);
                __m128 _rows1 = __lsx_vfmul_s(_S10, _a0);
                _rows1 = __lsx_vfmadd_s(_a1, _S11, _rows1);
                __lsx_vst(_rows1, rows1p + dx * 4, 0);

                alphap += 2;
            }
        }
        else
        {
            // hresize two rows
            const unsigned short* S0 = src.row<const unsigned short>(sy);
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows0p = rows0;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx] * 4;
                const unsigned short* S0p = S0 + sx;
                const unsigned short* S1p = S1 + sx;

                __m128 _a0 = (__m128)__lsx_vreplfr2vr_s(alphap[0]);
                __m128 _a1 = (__m128)__lsx_vreplfr2vr_s(alphap[1]);

                __m128i _zero_bf16 = __lsx_vreplgr2vr_w(0);
                __m128i _S0 = __lsx_vld(S0p, 0);
                __m128i _S1 = __lsx_vld(S1p, 0);
                __m128 _S00 = (__m128)__lsx_vilvl_h(_S0, _zero_bf16);
                __m128 _S01 = (__m128)__lsx_vilvh_h(_S0, _zero_bf16);
                __m128 _S10 = (__m128)__lsx_vilvl_h(_S1, _zero_bf16);
                __m128 _S11 = (__m128)__lsx_vilvh_h(_S1, _zero_bf16);
                __m128 _rows0 = __lsx_vfmul_s(_S00, _a0);
                __m128 _rows1 = __lsx_vfmul_s(_S10, _a0);
                _rows0 = __lsx_vfmadd_s(_a1, _S01, _rows0);
                _rows1 = __lsx_vfmadd_s(_a1, _S11, _rows1);
                __lsx_vst(_rows0, rows0p + dx * 4, 0);
                __lsx_vst(_rows1, rows1p + dx * 4, 0);

                alphap += 2;
            }
        }

        prev_sy1 = sy;

        __m128 _b0 = (__m128)__lsx_vreplfr2vr_s(beta[0]);
        __m128 _b1 = (__m128)__lsx_vreplfr2vr_s(beta[1]);

        float* rows0p = rows0;
        float* rows1p = rows1;
        unsigned short* Dp = dst.row<unsigned short>(dy);

        for (int dx = 0; dx < w; dx++)
        {
            __m128 _rows0 = (__m128)__lsx_vld(rows0p, 0);
            __m128 _rows1 = (__m128)__lsx_vld(rows1p, 0);
            __m128 _Dp = __lsx_vfmul_s(_rows0, _b0);
            _Dp = __lsx_vfmadd_s(_b1, _rows1, _Dp);
            __lsx_vstelm_d(float2bfloat_lsx(_Dp), Dp, 0, 0);

            Dp += 4;
            rows0p += 4;
            rows1p += 4;
        }

        beta += 2;
    }
}

static void resize_bilinear_image_pack8_bf16s_lsx(const Mat& src, Mat& dst, float* alpha, int* xofs, float* beta, int* yofs)
{
    int w = dst.w;
    int h = dst.h;

    Mat rowsbuf0(w, (size_t)8 * 4u, 8);
    Mat rowsbuf1(w, (size_t)8 * 4u, 8);
    float* rows0 = rowsbuf0;
    float* rows1 = rowsbuf1;

    int prev_sy1 = -2;

    for (int dy = 0; dy < h; dy++)
    {
        int sy = yofs[dy];

        if (sy == prev_sy1)
        {
            // reuse all rows
        }
        else if (sy == prev_sy1 + 1)
        {
            // hresize one row
            float* rows0_old = rows0;
            rows0 = rows1;
            rows1 = rows0_old;
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx] * 8;
                const unsigned short* S1p = S1 + sx;

                __m128 _a0 = (__m128)__lsx_vreplfr2vr_s(alphap[0]);
                __m128 _a1 = (__m128)__lsx_vreplfr2vr_s(alphap[1]);

                __m128i _zero_bf16 = __lsx_vreplgr2vr_w(0);
                __m128i _S10 = __lsx_vld(S1p, 0);
                __m128i _S11 = __lsx_vld(S1p + 8, 0);
                __m128 _rows10 = __lsx_vfmul_s((__m128)__lsx_vilvl_h(_S10, _zero_bf16), _a0);
                __m128 _rows11 = __lsx_vfmul_s((__m128)__lsx_vilvh_h(_S10, _zero_bf16), _a0);
                _rows10 = __lsx_vfmadd_s(_a1, (__m128)__lsx_vilvl_h(_S11, _zero_bf16), _rows10);
                _rows11 = __lsx_vfmadd_s(_a1, (__m128)__lsx_vilvh_h(_S11, _zero_bf16), _rows11);
                __lsx_vst(_rows10, rows1p + dx * 8, 0);
                __lsx_vst(_rows11, rows1p + dx * 8 + 4, 0);

                alphap += 2;
            }
        }
        else
        {
            // hresize two rows
            const unsigned short* S0 = src.row<const unsigned short>(sy);
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows0p = rows0;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx] * 8;
                const unsigned short* S0p = S0 + sx;
                const unsigned short* S1p = S1 + sx;

                __m128 _a0 = (__m128)__lsx_vreplfr2vr_s(alphap[0]);
                __m128 _a1 = (__m128)__lsx_vreplfr2vr_s(alphap[1]);

                __m128i _zero_bf16 = __lsx_vreplgr2vr_w(0);
                __m128i _S00 = __lsx_vld(S0p, 0);
                __m128i _S01 = __lsx_vld(S0p + 8, 0);
                __m128i _S10 = __lsx_vld(S1p, 0);
                __m128i _S11 = __lsx_vld(S1p + 8, 0);
                __m128 _rows00 = __lsx_vfmul_s((__m128)__lsx_vilvl_h(_S00, _zero_bf16), _a0);
                __m128 _rows01 = __lsx_vfmul_s((__m128)__lsx_vilvh_h(_S00, _zero_bf16), _a0);
                __m128 _rows10 = __lsx_vfmul_s((__m128)__lsx_vilvl_h(_S10, _zero_bf16), _a0);
                __m128 _rows11 = __lsx_vfmul_s((__m128)__lsx_vilvh_h(_S10, _zero_bf16), _a0);
                _rows00 = __lsx_vfmadd_s(_a1, (__m128)__lsx_vilvl_h(_S01, _zero_bf16), _rows00);
                _rows01 = __lsx_vfmadd_s(_a1, (__m128)__lsx_vilvh_h(_S01, _zero_bf16), _rows01);
                _rows10 = __lsx_vfmadd_s(_a1, (__m128)__lsx_vilvl_h(_S11, _zero_bf16), _rows10);
                _rows11 = __lsx_vfmadd_s(_a1, (__m128)__lsx_vilvh_h(_S11, _zero_bf16), _rows11);
                __lsx_vst(_rows00, rows0p + dx * 8, 0);
                __lsx_vst(_rows01, rows0p + dx * 8 + 4, 0);
                __lsx_vst(_rows10, rows1p + dx * 8, 0);
                __lsx_vst(_rows11, rows1p + dx * 8 + 4, 0);

                alphap += 2;
            }
        }

        prev_sy1 = sy;

        __m128 _b0 = (__m128)__lsx_vreplfr2vr_s(beta[0]);
        __m128 _b1 = (__m128)__lsx_vreplfr2vr_s(beta[1]);

        float* rows0p = rows0;
        float* rows1p = rows1;
        unsigned short* Dp = dst.row<unsigned short>(dy);

        for (int dx = 0; dx < w; dx++)
        {
            __m128 _rows00 = (__m128)__lsx_vld(rows0p, 0);
            __m128 _rows01 = (__m128)__lsx_vld(rows0p + 4, 0);
            __m128 _rows10 = (__m128)__lsx_vld(rows1p, 0);
            __m128 _rows11 = (__m128)__lsx_vld(rows1p + 4, 0);
            __m128 _Dp0 = __lsx_vfmul_s(_rows00, _b0);
            __m128 _Dp1 = __lsx_vfmul_s(_rows01, _b0);
            _Dp0 = __lsx_vfmadd_s(_b1, _rows10, _Dp0);
            _Dp1 = __lsx_vfmadd_s(_b1, _rows11, _Dp1);
            __lsx_vst(float2bfloat_lsx(_Dp0, _Dp1), Dp, 0);

            Dp += 8;
            rows0p += 8;
            rows1p += 8;
        }

        beta += 2;
    }
}

static void resize_bilinear_image_pack8_bf16s_lasx(const Mat& src, Mat& dst, float* alpha, int* xofs, float* beta, int* yofs)
{
    int w = dst.w;
    int h = dst.h;

    Mat rowsbuf0(w, (size_t)8 * 4u, 8);
    Mat rowsbuf1(w, (size_t)8 * 4u, 8);
    float* rows0 = rowsbuf0;
    float* rows1 = rowsbuf1;

    int prev_sy1 = -2;

    for (int dy = 0; dy < h; dy++)
    {
        int sy = yofs[dy];

        if (sy == prev_sy1)
        {
            // reuse all rows
        }
        else if (sy == prev_sy1 + 1)
        {
            // hresize one row
            float* rows0_old = rows0;
            rows0 = rows1;
            rows1 = rows0_old;
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx] * 8;
                const unsigned short* S1p = S1 + sx;

                __m256 _a0 = __lasx_xvreplfr2vr_s(alphap[0]);
                __m256 _a1 = __lasx_xvreplfr2vr_s(alphap[1]);

                __m256 _S10 = bfloat2float_lasx((__m128i*)S1p);
                __m256 _S11 = bfloat2float_lasx((__m128i*)(S1p + 8));
                __m256 _rows1 = __lasx_xvfmul_s(_S10, _a0);
                _rows1 = __lasx_xvfmadd_s(_a1, _S11, _rows1);
                __lasx_xvst(_rows1, rows1p + dx * 8, 0);

                alphap += 2;
            }
        }
        else
        {
            // hresize two rows
            const unsigned short* S0 = src.row<const unsigned short>(sy);
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows0p = rows0;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx] * 8;
                const unsigned short* S0p = S0 + sx;
                const unsigned short* S1p = S1 + sx;

                __m256 _a0 = __lasx_xvreplfr2vr_s(alphap[0]);
                __m256 _a1 = __lasx_xvreplfr2vr_s(alphap[1]);

                __m256 _S00 = bfloat2float_lasx((__m128i*)S0p);
                __m256 _S01 = bfloat2float_lasx((__m128i*)(S0p + 8));
                __m256 _S10 = bfloat2float_lasx((__m128i*)S1p);
                __m256 _S11 = bfloat2float_lasx((__m128i*)(S1p + 8));
                __m256 _rows0 = __lasx_xvfmul_s(_S00, _a0);
                __m256 _rows1 = __lasx_xvfmul_s(_S10, _a0);
                _rows0 = __lasx_xvfmadd_s(_a1, _S01, _rows0);
                _rows1 = __lasx_xvfmadd_s(_a1, _S11, _rows1);
                __lasx_xvst(_rows0, rows0p + dx * 8, 0);
                __lasx_xvst(_rows1, rows1p + dx * 8, 0);

                alphap += 2;
            }
        }

        prev_sy1 = sy;

        __m256 _b0 = __lasx_xvreplfr2vr_s(beta[0]);
        __m256 _b1 = __lasx_xvreplfr2vr_s(beta[1]);

        float* rows0p = rows0;
        float* rows1p = rows1;
        unsigned short* Dp = dst.row<unsigned short>(dy);

        for (int dx = 0; dx < w; dx++)
        {
            __m256 _rows0 = (__m256)__lasx_xvld(rows0p, 0);
            __m256 _rows1 = (__m256)__lasx_xvld(rows1p, 0);
            __m256 _Dp = __lasx_xvfmul_s(_rows0, _b0);
            _Dp = __lasx_xvfmadd_s(_b1, _rows1, _Dp);
            __lsx_vst(float2bfloat_lasx(_Dp), Dp, 0);

            Dp += 8;
            rows0p += 8;
            rows1p += 8;
        }

        beta += 2;
    }
}

LayerNorm_loongarch::LayerNorm_loongarch()
{
#if __loongarch_sx
    support_packing = true;
    support_any_packing = true;
#endif // __loongarch_sx
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int LayerNorm_loongarch::forward_inplace(Mat& bottom_top_blob, const Option& opt) const
{
#if NCNN_BF16
    if (opt.use_bf16_storage && bottom_top_blob.elembits() == 16)
        return forward_inplace_bf16s(bottom_top_blob, opt);
#endif

    const int dims = bottom_top_blob.dims;
    const int elempack = bottom_top_blob.elempack;
    const int w = bottom_top_blob.w;
    const int h = bottom_top_blob.h;
    const int channels = bottom_top_blob.c;

    if (dims == 1)
    {
        float* ptr = bottom_top_blob;
        layernorm_loongarch(ptr, gamma_data, beta_data, eps, w * elempack, 1);
    }

    if (dims == 2)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int i = 0; i < h; i++)
        {
            float* ptr = bottom_top_blob.row(i);
            layernorm_loongarch(ptr, gamma_data, beta_data, eps, w, elempack);
        }
    }

    if (dims == 3)
    {
        if (affine_size == w)
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int q = 0; q < channels; q++)
            {
                for (int i = 0; i < h; i++)
                {
                    float* ptr = bottom_top_blob.channel(q).row(i);
                    layernorm_loongarch(ptr, gamma_data, beta_data, eps, w, elempack);
                }
            }
        }
        else
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int q = 0; q < channels; q++)
            {
                float* ptr = bottom_top_blob.channel(q);
                layernorm_loongarch(ptr, gamma_data, beta_data, eps, w * h, elempack);
            }
        }
    }

    return 0;
}

int LayerNorm_loongarch::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    const int dims = bottom_top_blob.dims;
    const int elempack = bottom_top_blob.elempack;
    const int w = bottom_top_blob.w;
    const int h = bottom_top_blob.h;
    const int channels = bottom_top_blob.c;

    if (dims == 1)
    {
        unsigned short* ptr = (unsigned short*)bottom_top_blob;
        layernorm_loongarch_bf16(ptr, gamma_data, beta_data, eps, w * elempack, 1);
    }

    if (dims == 2)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int i = 0; i < h; i++)
        {
            unsigned short* ptr = (unsigned short*)bottom_top_blob.row(i);
            layernorm_loongarch_bf16(ptr, gamma_data, beta_data, eps, w, elempack);
        }
    }

    if (dims == 3)
    {
        if (affine_size == w)
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int q = 0; q < channels; q++)
            {
                for (int i = 0; i < h; i++)
                {
                    unsigned short* ptr = (unsigned short*)bottom_top_blob.channel(q).row(i);
                    layernorm_loongarch_bf16(ptr, gamma_data, beta_data, eps, w, elempack);
                }
            }
        }
        else
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int q = 0; q < channels; q++)
            {
                unsigned short* ptr = (unsigned short*)bottom_top_blob.channel(q);
                layernorm_loongarch_bf16(ptr, gamma_data, beta_data, eps, w * h, elempack);
            }
        }
    }

    return 0;
}

LRN_loongarch::LRN_loongarch()
{
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int LRN_loongarch::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    Option opt_cast = opt;
    opt_cast.blob_allocator = opt.workspace_allocator;

    Mat bottom_top_blob_fp32;
    cast_bfloat16_to_float32(bottom_top_blob, bottom_top_blob_fp32, opt_cast);
    if (bottom_top_blob_fp32.empty())
        return -100;

    int ret = forward_inplace(bottom_top_blob_fp32, opt);
    if (ret != 0)
        return ret;

    cast_float32_to_bfloat16(bottom_top_blob_fp32, bottom_top_blob, opt);
    if (bottom_top_blob.empty())
        return -100;

    return 0;
}

LSTM_loongarch::LSTM_loongarch()
{
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

static int cast_to_float32_if_needed(const Mat& src, Mat& dst, const Option& opt)
{
    if (src.elembits() != 16)
    {
        dst = src;
        return 0;
    }

#if NCNN_BF16
    Option opt_cast = opt;
    opt_cast.blob_allocator = opt.workspace_allocator;

    cast_bfloat16_to_float32(src, dst, opt_cast);
    if (dst.empty())
        return -100;

    return 0;
#else
    return -100;
#endif
}

int MatMul_loongarch::create_pipeline(const Option& opt)
{
    gemm = ncnn::create_layer_cpu(ncnn::LayerType::Gemm);

    ncnn::ParamDict pd;
    pd.set(2, 0);      // transA
    pd.set(3, transB); // transB
    pd.set(4, 0);      // constantA
    pd.set(5, 0);      // constantB
    pd.set(6, 1);      // constantC
    pd.set(7, 0);      // M = outch
    pd.set(8, 0);      // N = size
    pd.set(9, 0);      // K = maxk*inch
    pd.set(10, -1);    // constant_broadcast_type_C = null
    pd.set(11, 0);     // output_N1M
    pd.set(12, 1);     // output_elempack

    gemm->load_param(pd);

    gemm->load_model(ModelBinFromMatArray(0));

    gemm->create_pipeline(opt);

    return 0;
}

int MatMul_loongarch::destroy_pipeline(const Option& opt)
{
    if (gemm)
    {
        gemm->destroy_pipeline(opt);
        delete gemm;
        gemm = 0;
    }

    return 0;
}

int Mish_loongarch::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __loongarch_sx
#if __loongarch_asx
        for (; i + 7 < size; i += 8)
        {
            __m256 _p = bfloat2float_lasx((__m128i*)ptr);
            _p = __lasx_xvfmul_s(_p, tanh256_ps(log256_ps(__lasx_xvfadd_s(exp256_ps(_p), (__m256)__lasx_xvreplfr2vr_s(1.f)))));
            __lsx_vst(float2bfloat_lasx(_p), ptr, 0);
            ptr += 8;
        }
#else  // __loongarch_asx
        {
            __m128i _zero = __lsx_vreplgr2vr_w(0);
            __m128 _one = (__m128)__lsx_vreplfr2vr_s(1.f);
            for (; i + 7 < size; i += 8)
            {
                __m128i _p01 = __lsx_vld(ptr, 0);
                __m128 _p0 = (__m128)__lsx_vilvl_h(_p01, _zero);
                __m128 _p1 = (__m128)__lsx_vilvh_h(_p01, _zero);
                _p0 = __lsx_vfmul_s(_p0, tanh_ps(log_ps(__lsx_vfadd_s(exp_ps(_p0), _one))));
                _p1 = __lsx_vfmul_s(_p1, tanh_ps(log_ps(__lsx_vfadd_s(exp_ps(_p1), _one))));
                __lsx_vst(float2bfloat_lsx(_p0, _p1), ptr, 0);
                ptr += 8;
            }
        }
#endif // __loongarch_asx
        for (; i + 3 < size; i += 4)
        {
            __m128 _p = bfloat2float_lsx(__lsx_vldrepl_d(ptr, 0));
            _p = __lsx_vfmul_s(_p, tanh_ps(log_ps(__lsx_vfadd_s(exp_ps(_p), (__m128)__lsx_vreplfr2vr_s(1.f)))));
            __lsx_vstelm_d(float2bfloat_lsx(_p), ptr, 0, 0);
            ptr += 4;
        }
#endif // __loongarch_sx
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            v = v * tanhf(logf(expf(v) + 1.f));
            *ptr = float32_to_bfloat16(v);
            ptr++;
        }
    }

    return 0;
}

