int Padding_loongarch::create_pipeline(const Option& opt)
{
#if NCNN_BF16
    if (opt.use_bf16_storage)
    {
        value_bf16 = float32_to_bfloat16(value);

        ncnn::cast_float32_to_bfloat16(per_channel_pad_data, per_channel_pad_data_bf16, opt);
    }
#endif

    return 0;
}

int Padding_loongarch::destroy_pipeline(const Option& /*opt*/)
{
#if NCNN_BF16
    per_channel_pad_data_bf16 = Mat();
#endif

    return 0;
#if NCNN_BF16
    if (elembits == 16)
        return forward_bf16s(bottom_blob, top_blob, opt);
#endif

#if __loongarch_asx
    if (elempack == 8)
    {
        if (dims == 1)
        {
            int outw = w * elempack + left + right;

            int out_elempack = outw % 8 == 0 ? 8 : outw % 4 == 0 ? 4 : 1;
            size_t out_elemsize = elemsize / elempack * out_elempack;

            if (left % 8 == 0 && out_elempack == 8 && type == 0)
            {
                top_blob.create(outw / out_elempack, out_elemsize, out_elempack, opt.blob_allocator);
                if (top_blob.empty())
                    return -100;

                __m256 pad_value = (__m256)__lasx_xvreplfr2vr_s(value);
                padding_constant_pack8_lasx(bottom_blob, top_blob, 0, 0, left / 8, right / 8, pad_value);

                return 0;
            }
        }

        if (dims == 2)
        {
            int outw = w + left + right;
            int outh = h * elempack + top + bottom;

            int out_elempack = outh % 8 == 0 ? 8 : outh % 4 == 0 ? 4 : 1;
            size_t out_elemsize = elemsize / elempack * out_elempack;

            if (top % 8 == 0 && out_elempack == 8 && type == 0)
            {
                top_blob.create(outw, outh / out_elempack, out_elemsize, out_elempack, opt.blob_allocator);
                if (top_blob.empty())
                    return -100;

                __m256 pad_value = (__m256)__lasx_xvreplfr2vr_s(value);
                padding_constant_pack8_lasx(bottom_blob, top_blob, top / 8, bottom / 8, left, right, pad_value);

                return 0;
            }
        }

        if (dims == 3)
        {
            int outw = w + left + right;
            int outh = h + top + bottom;
            int outc = channels * elempack + front + behind;

            int out_elempack = outc % 8 == 0 ? 8 : outc % 4 == 0 ? 4 : 1;
            size_t out_elemsize = elemsize / elempack * out_elempack;

            if (front % 8 == 0 && out_elempack == 8 && !(outc != channels * elempack && type != 0))
            {
                top_blob.create(outw, outh, outc / out_elempack, out_elemsize, out_elempack, opt.blob_allocator);
                if (top_blob.empty())
                    return -100;

                int front_ = front / elempack;
                #pragma omp parallel for num_threads(opt.num_threads)
                for (int q = 0; q < outc / out_elempack; q++)
                {
                    Mat borderm = top_blob.channel(q);

                    __m256 pad_value = per_channel_pad_data_size ? (__m256)__lasx_xvld((const float*)per_channel_pad_data + q * 8, 0) : (__m256)__lasx_xvreplfr2vr_s(value);
                    //Channel padding
                    if ((q - front_) < 0 || (q - front_) >= channels)
                    {
                        borderm.fill(pad_value);
                    }
                    else
                    {
                        const Mat m = bottom_blob.channel(q - front_);
                        if (type == 0)
                            padding_constant_pack8_lasx(m, borderm, top, bottom, left, right, pad_value);
                        if (type == 1)
                            padding_replicate_pack8_lasx(m, borderm, top, bottom, left, right);
                        if (type == 2)
                            padding_reflect_pack8_lasx(m, borderm, top, bottom, left, right);
                    }
                }

                return 0;
            }
        }

        if (dims == 4)
        {
            int outw = w + left + right;
            int outh = h + top + bottom;
            int outd = d + front + behind;

            if (type == 0)
            {
                top_blob.create(outw, outh, outd, channels, elemsize, elempack, opt.blob_allocator);
                if (top_blob.empty())
                    return -100;

                #pragma omp parallel for num_threads(opt.num_threads)
                for (int q = 0; q < channels; q++)
                {
                    __m256 pad_value = per_channel_pad_data_size ? (__m256)__lasx_xvld((const float*)per_channel_pad_data + q * 8, 0) : (__m256)__lasx_xvreplfr2vr_s(value);

                    for (int z = 0; z < outd; z++)
                    {
                        Mat borderm = top_blob.channel(q).depth(z);

                        // depth padding
                        if ((z - front) < 0 || (z - front) >= d)
                        {
                            borderm.fill(pad_value);
                        }
                        else
                        {
                            const Mat m = bottom_blob.channel(q).depth(z - front);
                            padding_constant_pack8_lasx(m, borderm, top, bottom, left, right, pad_value);
                        }
                    }
                }

                return 0;
            }
        }
    }
#endif // __loongarch_asx

#if __loongarch_asx
        if (elempack == 8)
            out_elempack = top_blob_unpacked.c % 8 == 0 ? 8 : top_blob_unpacked.c % 4 == 0 ? 4 : 1;
        else
            out_elempack = top_blob_unpacked.c % 4 == 0 ? 4 : 1;
#else
#endif
    }

int Pooling_loongarch::forward_bf16s(const Mat& bottom_blob, Mat& top_blob, const Option& opt) const
{
    if (adaptive_pooling)
    {
        return Pooling::forward(bottom_blob, top_blob, opt);
    }

    int w = bottom_blob.w;
    int h = bottom_blob.h;
    int channels = bottom_blob.c;
    size_t elemsize = bottom_blob.elemsize;
    int elempack = bottom_blob.elempack;

    //     NCNN_LOGE("Pooling bf16s input %d x %d  pad = %d %d %d %d  ksize=%d %d  stride=%d %d", w, h, pad_left, pad_right, pad_top, pad_bottom, kernel_w, kernel_h, stride_w, stride_h);

    if (global_pooling)
    {
        top_blob.create(channels, elemsize, elempack, opt.blob_allocator);
        if (top_blob.empty())
            return -100;

        if (pooling_type == PoolMethod_MAX)
        {
            pooling_global_max_bf16s_lsx(bottom_blob, top_blob, opt);
        }
        else if (pooling_type == PoolMethod_AVE)
        {
            pooling_global_avg_bf16s_lsx(bottom_blob, top_blob, opt);
        }

        return 0;
    }

    Mat bottom_blob_bordered;
    make_padding(bottom_blob, bottom_blob_bordered, opt);
    if (bottom_blob_bordered.empty())
        return -100;

    w = bottom_blob_bordered.w;
    h = bottom_blob_bordered.h;

    int outw = (w - kernel_w) / stride_w + 1;
    int outh = (h - kernel_h) / stride_h + 1;

    top_blob.create(outw, outh, channels, elemsize, elempack, opt.blob_allocator);
    if (top_blob.empty())
        return -100;

    if (pooling_type == PoolMethod_MAX)
    {
        pooling_max_bf16s_lsx(bottom_blob_bordered, top_blob, kernel_w, kernel_h, stride_w, stride_h, opt);
    }
    else if (pooling_type == PoolMethod_AVE)
    {
        pooling_avg_bf16s_lsx(bottom_blob_bordered, bottom_blob, top_blob, kernel_w, kernel_h, stride_w, stride_h, pad_left, pad_right, pad_top, pad_bottom, pad_mode, avgpool_count_include_pad, opt);
    }

    return 0;
}

Bias_mips::Bias_mips()
{
#if __mips_msa
    support_packing = true;
    support_any_packing = true;
#endif
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

static void binary_op_vector_no_broadcast_bf16s(const unsigned short* ptr, const unsigned short* ptr1, unsigned short* outptr, int size)
{
    const Op op;

    int i = 0;
#if __mips_msa
    v8i16 _zero = __msa_fill_h(0);
    for (; i + 7 < size; i += 8)
    {
        v8i16 _p01 = __msa_ld_h(ptr, 0);
        v8i16 _b01 = __msa_ld_h(ptr1, 0);
        v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
        v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
        v4f32 _b0 = (v4f32)__msa_ilvr_h(_b01, _zero);
        v4f32 _b1 = (v4f32)__msa_ilvl_h(_b01, _zero);
        v4f32 _outp0 = op(_p0, _b0);
        v4f32 _outp1 = op(_p1, _b1);
        __msa_st_w(float2bfloat_msa(_outp0, _outp1), outptr, 0);
        ptr += 8;
        ptr1 += 8;
        outptr += 8;
    }
    for (; i + 3 < size; i += 4)
    {
        v4f32 _p = bfloat2float_msa(ptr);
        v4f32 _b = bfloat2float_msa(ptr1);
        v4f32 _outp = op(_p, _b);
        *(int64_t*)outptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_outp), 0);
        ptr += 4;
        ptr1 += 4;
        outptr += 4;
    }
#endif // __mips_msa
    for (; i < size; i++)
    {
        *outptr++ = float32_to_bfloat16(op(bfloat16_to_float32(*ptr++), bfloat16_to_float32(*ptr1++)));
    }
}

static void binary_op_vector_broadcast_b_bf16s(const unsigned short* ptr, const unsigned short* ptr1, unsigned short* outptr, int size, int elempack)
{
    const Op op;

    const float b = bfloat16_to_float32(*ptr1);

    int i = 0;
#if __mips_msa
    v4f32 _b0 = (elempack == 4) ? bfloat2float_msa(ptr1) : __msa_fill_w_f32(b);
    v4f32 _b1 = _b0;
    if (elempack == 8)
    {
        v8i16 _zero = __msa_fill_h(0);
        v8i16 _b01 = __msa_ld_h(ptr1, 0);
        _b0 = (v4f32)__msa_ilvr_h(_b01, _zero);
        _b1 = (v4f32)__msa_ilvl_h(_b01, _zero);
    }
    v8i16 _zero = __msa_fill_h(0);
    for (; i + 7 < size; i += 8)
    {
        v8i16 _p01 = __msa_ld_h(ptr, 0);
        v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
        v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
        v4f32 _outp0 = op(_p0, _b0);
        v4f32 _outp1 = op(_p1, _b1);
        __msa_st_w(float2bfloat_msa(_outp0, _outp1), outptr, 0);
        ptr += 8;
        outptr += 8;
    }
    for (; i + 3 < size; i += 4)
    {
        v4f32 _p = bfloat2float_msa(ptr);
        v4f32 _outp = op(_p, _b0);
        *(int64_t*)outptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_outp), 0);
        ptr += 4;
        outptr += 4;
    }
#endif // __mips_msa
    for (; i < size; i++)
    {
        *outptr++ = float32_to_bfloat16(op(bfloat16_to_float32(*ptr++), b));
    }
}

static void binary_op_vector_broadcast_a_bf16s(const unsigned short* ptr, const unsigned short* ptr1, unsigned short* outptr, int size, int elempack)
{
    const Op op;

    const float a = bfloat16_to_float32(*ptr);

    int i = 0;
#if __mips_msa
    v4f32 _a0 = (elempack == 4) ? bfloat2float_msa(ptr) : __msa_fill_w_f32(a);
    v4f32 _a1 = _a0;
    if (elempack == 8)
    {
        v8i16 _zero = __msa_fill_h(0);
        v8i16 _a01 = __msa_ld_h(ptr, 0);
        _a0 = (v4f32)__msa_ilvr_h(_a01, _zero);
        _a1 = (v4f32)__msa_ilvl_h(_a01, _zero);
    }
    v8i16 _zero = __msa_fill_h(0);
    for (; i + 7 < size; i += 8)
    {
        v8i16 _b01 = __msa_ld_h(ptr1, 0);
        v4f32 _b0 = (v4f32)__msa_ilvr_h(_b01, _zero);
        v4f32 _b1 = (v4f32)__msa_ilvl_h(_b01, _zero);
        v4f32 _outp0 = op(_a0, _b0);
        v4f32 _outp1 = op(_a1, _b1);
        __msa_st_w(float2bfloat_msa(_outp0, _outp1), outptr, 0);
        ptr1 += 8;
        outptr += 8;
    }
    for (; i + 3 < size; i += 4)
    {
        v4f32 _b = bfloat2float_msa(ptr1);
        v4f32 _outp = op(_a0, _b);
        *(int64_t*)outptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_outp), 0);
        ptr1 += 4;
        outptr += 4;
    }
#endif // __mips_msa
    for (; i < size; i++)
    {
        *outptr++ = float32_to_bfloat16(op(a, bfloat16_to_float32(*ptr1++)));
    }
}

static void binary_op_vector_broadcast_pb_bf16s(const unsigned short* ptr, const unsigned short* ptr1, unsigned short* outptr, int w, int elempack)
{
    const Op op;

#if __mips_msa
    if (elempack == 8)
    {
        v8i16 _zero = __msa_fill_h(0);
        for (int i = 0; i < w; i++)
        {
            v8i16 _p01 = __msa_ld_h(ptr, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
            v4f32 _b = __msa_fill_w_f32(bfloat16_to_float32(*ptr1));
            v4f32 _outp0 = op(_p0, _b);
            v4f32 _outp1 = op(_p1, _b);
            __msa_st_w(float2bfloat_msa(_outp0, _outp1), outptr, 0);
            ptr += 8;
            ptr1 += 1;
            outptr += 8;
        }
    }

    if (elempack == 4)
    {
        int i = 0;
        v8i16 _zero = __msa_fill_h(0);
        for (; i + 1 < w; i += 2)
        {
            v8i16 _p01 = __msa_ld_h(ptr, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
            v4f32 _b0 = __msa_fill_w_f32(bfloat16_to_float32(ptr1[0]));
            v4f32 _b1 = __msa_fill_w_f32(bfloat16_to_float32(ptr1[1]));
            v4f32 _outp0 = op(_p0, _b0);
            v4f32 _outp1 = op(_p1, _b1);
            __msa_st_w(float2bfloat_msa(_outp0, _outp1), outptr, 0);
            ptr += 8;
            ptr1 += 2;
            outptr += 8;
        }
        for (; i < w; i++)
        {
            v4f32 _p = bfloat2float_msa(ptr);
            v4f32 _b = __msa_fill_w_f32(bfloat16_to_float32(*ptr1));
            v4f32 _outp = op(_p, _b);
            *(int64_t*)outptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_outp), 0);
            ptr += 4;
            ptr1 += 1;
            outptr += 4;
        }
    }
#endif // __mips_msa
}

static void binary_op_vector_broadcast_pb_b_bf16s(const unsigned short* ptr, const unsigned short* ptr1, unsigned short* outptr, int w, int elempack)
{
    const Op op;

    const int size = w * elempack;
    const float b = bfloat16_to_float32(*ptr1);

    int i = 0;
#if __mips_msa
    v4f32 _b_128 = __msa_fill_w_f32(b);
    v8i16 _zero = __msa_fill_h(0);
    for (; i + 7 < size; i += 8)
    {
        v8i16 _p01 = __msa_ld_h(ptr, 0);
        v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
        v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
        v4f32 _outp0 = op(_p0, _b_128);
        v4f32 _outp1 = op(_p1, _b_128);
        __msa_st_w(float2bfloat_msa(_outp0, _outp1), outptr, 0);
        ptr += 8;
        outptr += 8;
    }
    for (; i + 3 < size; i += 4)
    {
        v4f32 _p = bfloat2float_msa(ptr);
        v4f32 _outp = op(_p, _b_128);
        *(int64_t*)outptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_outp), 0);
        ptr += 4;
        outptr += 4;
    }
#endif // __mips_msa
}

static void binary_op_vector_broadcast_pb_a_bf16s(const unsigned short* ptr, const unsigned short* ptr1, unsigned short* outptr, int w, int elempack)
{
    const Op op;

#if __mips_msa
    if (elempack == 8)
    {
        v8i16 _zero = __msa_fill_h(0);
        v8i16 _p01 = __msa_ld_h(ptr, 0);
        v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
        v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
        for (int i = 0; i < w; i++)
        {
            v4f32 _b = __msa_fill_w_f32(bfloat16_to_float32(*ptr1));
            v4f32 _outp0 = op(_p0, _b);
            v4f32 _outp1 = op(_p1, _b);
            __msa_st_w(float2bfloat_msa(_outp0, _outp1), outptr, 0);
            ptr1 += 1;
            outptr += 8;
        }
    }

    if (elempack == 4)
    {
        v4f32 _p = bfloat2float_msa(ptr);
        int i = 0;
        for (; i + 1 < w; i += 2)
        {
            v4f32 _b0 = __msa_fill_w_f32(bfloat16_to_float32(ptr1[0]));
            v4f32 _b1 = __msa_fill_w_f32(bfloat16_to_float32(ptr1[1]));
            v4f32 _outp0 = op(_p, _b0);
            v4f32 _outp1 = op(_p, _b1);
            __msa_st_w(float2bfloat_msa(_outp0, _outp1), outptr, 0);
            ptr1 += 2;
            outptr += 8;
        }
        for (; i < w; i++)
        {
            v4f32 _b = __msa_fill_w_f32(bfloat16_to_float32(*ptr1));
            v4f32 _outp = op(_p, _b);
            *(int64_t*)outptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_outp), 0);
            ptr1 += 1;
            outptr += 4;
        }
    }
#endif // __mips_msa
}

static void binary_op_vector_bf16s(const unsigned short* ptr, const unsigned short* ptr1, unsigned short* outptr, int aw, int bw, int ap, int bp)
{
    const int w = std::max(aw, bw);
    const int elempack = std::max(ap, bp);
    const int size = w * elempack;

    if (ap == bp)
    {
        if (aw == bw)
            return binary_op_vector_no_broadcast_bf16s<Op>(ptr, ptr1, outptr, size);
        if (bw == 1)
            return binary_op_vector_broadcast_b_bf16s<Op>(ptr, ptr1, outptr, size, elempack);
        if (aw == 1)
            return binary_op_vector_broadcast_a_bf16s<Op>(ptr, ptr1, outptr, size, elempack);
    }

    if (bp == 1)
    {
        if (aw == bw)
            return binary_op_vector_broadcast_pb_bf16s<Op>(ptr, ptr1, outptr, w, elempack);
        if (bw == 1)
            return binary_op_vector_broadcast_pb_b_bf16s<Op>(ptr, ptr1, outptr, w, elempack);
        if (aw == 1)
            return binary_op_vector_broadcast_pb_a_bf16s<Op>(ptr, ptr1, outptr, w, elempack);
    }
}

static void binary_op_vector_bf16s(const unsigned short* ptr, const unsigned short* ptr1, unsigned short* outptr, int aw, int bw, int ap, int bp, int op_type)
{
    using namespace BinaryOp_mips_functor;

    if (op_type == BinaryOp::Operation_ADD) return binary_op_vector_bf16s<binary_op_add>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_SUB) return binary_op_vector_bf16s<binary_op_sub>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_MUL) return binary_op_vector_bf16s<binary_op_mul>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_DIV) return binary_op_vector_bf16s<binary_op_div>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_MAX) return binary_op_vector_bf16s<binary_op_max>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_MIN) return binary_op_vector_bf16s<binary_op_min>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_POW) return binary_op_vector_bf16s<binary_op_pow>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RSUB) return binary_op_vector_bf16s<binary_op_rsub>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RDIV) return binary_op_vector_bf16s<binary_op_rdiv>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RPOW) return binary_op_vector_bf16s<binary_op_rpow>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_ATAN2) return binary_op_vector_bf16s<binary_op_atan2>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RATAN2) return binary_op_vector_bf16s<binary_op_ratan2>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_FMOD) return binary_op_vector_bf16s<binary_op_fmod>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RFMOD) return binary_op_vector_bf16s<binary_op_rfmod>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_LOGADDEXP) return binary_op_vector_bf16s<binary_op_logaddexp>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_FLOOR_DIVIDE) return binary_op_vector_bf16s<binary_op_floor_divide>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RFLOOR_DIVIDE) return binary_op_vector_bf16s<binary_op_rfloor_divide>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_REMAINDER) return binary_op_vector_bf16s<binary_op_remainder>(ptr, ptr1, outptr, aw, bw, ap, bp);
    if (op_type == BinaryOp::Operation_RREMAINDER) return binary_op_vector_bf16s<binary_op_rremainder>(ptr, ptr1, outptr, aw, bw, ap, bp);

    // should never reach here
}

static void binary_op_scalar_bf16s(const Mat& a, unsigned short b, Mat& c, int op_type, const Option& opt)
{
    const int channels = a.c;
    const int size = a.w * a.h * a.d * a.elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        const unsigned short* ptr = a.channel(q);
        unsigned short* outptr = c.channel(q);

        binary_op_vector_bf16s(ptr, &b, outptr, size, 1, 1, 1, op_type);
    }
}

static void binary_op_no_broadcast_bf16s(const Mat& a, const Mat& b, Mat& c, int op_type, const Option& opt)
{
    const int channels = a.c;
    const int size = a.w * a.h * a.d * a.elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        const unsigned short* ptr = a.channel(q);
        const unsigned short* ptr1 = b.channel(q);
        unsigned short* outptr = c.channel(q);

        binary_op_vector_bf16s(ptr, ptr1, outptr, size, size, 1, 1, op_type);
    }
}

static void binary_op_broadcast_bf16s(const Mat& a, const Mat& b, Mat& c, int op_type, const Option& opt)
{
    if (b.w * b.h * b.d * b.c * b.elempack == 1)
    {
        return binary_op_scalar_bf16s(a, ((const unsigned short*)b)[0], c, op_type, opt);
    }

    if (a.dims == b.dims && a.w == b.w && a.h == b.h && a.d == b.d && a.c == b.c && a.elempack == b.elempack)
    {
        return binary_op_no_broadcast_bf16s(a, b, c, op_type, opt);
    }

    const int dims = c.dims;

    if (dims == 2)
    {
        const int h = c.h;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int y = 0; y < h; y++)
        {
            const int y0 = std::min(y, a.h - 1);
            const int y1 = std::min(y, b.h - 1);

            const unsigned short* ptr = a.row<const unsigned short>(y0);
            const unsigned short* ptr1 = b.row<const unsigned short>(y1);
            unsigned short* outptr = c.row<unsigned short>(y);

            binary_op_vector_bf16s(ptr, ptr1, outptr, a.w, b.w, a.elempack, b.elempack, op_type);
        }
    }

    if (dims == 3 || dims == 4)
    {
        const int channels = c.c;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int q = 0; q < channels; q++)
        {
            const int q0 = std::min(q, a.c - 1);
            const int q1 = std::min(q, b.c - 1);

            if (b.d * b.h * b.w == 1)
            {
                const unsigned short* ptr = a.channel(q0);
                const unsigned short* ptr1 = b.channel(q1);
                unsigned short* outptr = c.channel(q);

                binary_op_vector_bf16s(ptr, ptr1, outptr, a.w * a.h * a.d, 1, a.elempack, b.elempack, op_type);
                continue;
            }

            if (b.h * b.w == 1)
            {
                for (int z = 0; z < c.d; z++)
                {
                    const int z0 = std::min(z, a.d - 1);
                    const int z1 = std::min(z, b.d - 1);

                    const unsigned short* ptr = a.channel(q0).depth(z0);
                    const unsigned short* ptr1 = b.channel(q1).depth(z1);
                    unsigned short* outptr = c.channel(q).depth(z);

                    binary_op_vector_bf16s(ptr, ptr1, outptr, a.w * a.h, 1, a.elempack, b.elempack, op_type);
                }
                continue;
            }

            for (int z = 0; z < c.d; z++)
            {
                const int z0 = std::min(z, a.d - 1);
                const int z1 = std::min(z, b.d - 1);

                for (int y = 0; y < c.h; y++)
                {
                    const int y0 = std::min(y, a.h - 1);
                    const int y1 = std::min(y, b.h - 1);

                    const unsigned short* ptr = a.channel(q0).depth(z0).row<const unsigned short>(y0);
                    const unsigned short* ptr1 = b.channel(q1).depth(z1).row<const unsigned short>(y1);
                    unsigned short* outptr = c.channel(q).depth(z).row<unsigned short>(y);

                    binary_op_vector_bf16s(ptr, ptr1, outptr, a.w, b.w, a.elempack, b.elempack, op_type);
                }
            }
        }
    }
}

static void binary_op_scalar_inplace_bf16s(Mat& a, unsigned short b, int op_type, const Option& opt)
{
    const int channels = a.c;
    const int size = a.w * a.h * a.d * a.elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = a.channel(q);

        binary_op_vector_bf16s(ptr, &b, ptr, size, 1, 1, 1, op_type);
    }
}

int BinaryOp_mips::forward_bf16s(const std::vector<Mat>& bottom_blobs, std::vector<Mat>& top_blobs, const Option& opt) const
{
    const Mat& A = bottom_blobs[0];
    const Mat& B = bottom_blobs[1];
    const int outdims = std::max(A.dims, B.dims);

    Mat A2 = A;
    Mat B2 = B;
    if (A.dims < outdims)
    {
        // expand inner axes
        if (outdims == 2)
        {
            if (A.w * A.elempack == B.h * B.elempack)
                A2 = A.reshape(1, A.w, opt.workspace_allocator);
            else // if (A.w == B.w)
            {
                A2.dims = 2;
                A2.w = A.w * A.elempack;
                A2.elempack = 1;
                A2.elemsize = A.elemsize / A.elempack;
                A2.cstep = A.cstep * A.elempack;
            }
        }
        if (outdims == 3 && A.dims == 1)
        {
            if (A.w * A.elempack == B.c * B.elempack)
                A2 = A.reshape(1, 1, A.w, opt.workspace_allocator);
            else // if (A.w == B.w)
            {
                A2.dims = 3;
                A2.w = A.w * A.elempack;
                A2.elempack = 1;
                A2.elemsize = A.elemsize / A.elempack;
                A2.cstep = A.cstep * A.elempack;
            }
        }
        if (outdims == 3 && A.dims == 2)
            A2 = A.reshape(1, A.w, A.h, opt.workspace_allocator);
        if (outdims == 4 && A.dims == 1)
        {
            if (A.w * A.elempack == B.c * B.elempack)
                A2 = A.reshape(1, 1, 1, A.w, opt.workspace_allocator);
            else // if (A.w == B.w)
            {
                A2.dims = 4;
                A2.w = A.w * A.elempack;
                A2.elempack = 1;
                A2.elemsize = A.elemsize / A.elempack;
                A2.cstep = A.cstep * A.elempack;
            }
        }
        if (outdims == 4 && A.dims == 2)
            A2 = A.reshape(1, 1, A.w, A.h, opt.workspace_allocator);
        if (outdims == 4 && A.dims == 3)
            A2 = A.reshape(1, A.w, A.h, A.c, opt.workspace_allocator);
    }
    if (B.dims < outdims)
    {
        // expand inner axes
        if (outdims == 2)
        {
            if (B.w * B.elempack == A.h * A.elempack)
                B2 = B.reshape(1, B.w, opt.workspace_allocator);
            else // if (B.w == A.w)
            {
                B2.dims = 2;
                B2.w = B.w * B.elempack;
                B2.elempack = 1;
                B2.elemsize = B.elemsize / B.elempack;
                B2.cstep = B.cstep * B.elempack;
            }
        }
        if (outdims == 3 && B.dims == 1)
        {
            if (B.w * B.elempack == A.c * A.elempack)
                B2 = B.reshape(1, 1, B.w, opt.workspace_allocator);
            else // if (B.w == A.w)
            {
                B2.dims = 3;
                B2.w = B.w * B.elempack;
                B2.elempack = 1;
                B2.elemsize = B.elemsize / B.elempack;
                B2.cstep = B.cstep * B.elempack;
            }
        }
        if (outdims == 3 && B.dims == 2)
            B2 = B.reshape(1, B.w, B.h, opt.workspace_allocator);
        if (outdims == 4 && B.dims == 1)
        {
            if (B.w * B.elempack == A.c * A.elempack)
                B2 = B.reshape(1, 1, 1, B.w, opt.workspace_allocator);
            else // if (B.w == A.w)
            {
                B2.dims = 4;
                B2.w = B.w * B.elempack;
                B2.elempack = 1;
                B2.elemsize = B.elemsize / B.elempack;
                B2.cstep = B.cstep * B.elempack;
            }
        }
        if (outdims == 4 && B.dims == 2)
            B2 = B.reshape(1, 1, B.w, B.h, opt.workspace_allocator);
        if (outdims == 4 && B.dims == 3)
            B2 = B.reshape(1, B.w, B.h, B.c, opt.workspace_allocator);
    }

    const int outw = std::max(A2.w, B2.w);
    const int outh = std::max(A2.h, B2.h);
    const int outd = std::max(A2.d, B2.d);
    const int outc = std::max(A2.c, B2.c);
    const size_t out_elemsize = std::max(A2.elemsize, B2.elemsize);
    const int out_elempack = std::max(A2.elempack, B2.elempack);

    Mat& top_blob = top_blobs[0];
    if (outdims == 1)
    {
        top_blob.create(outw, out_elemsize, out_elempack, opt.blob_allocator);
    }
    if (outdims == 2)
    {
        top_blob.create(outw, outh, out_elemsize, out_elempack, opt.blob_allocator);
    }
    if (outdims == 3)
    {
        top_blob.create(outw, outh, outc, out_elemsize, out_elempack, opt.blob_allocator);
    }
    if (outdims == 4)
    {
        top_blob.create(outw, outh, outd, outc, out_elemsize, out_elempack, opt.blob_allocator);
    }
    if (top_blob.empty())
        return -100;

    const bool a_pack_is_lower = A2.elempack < B2.elempack;
    const bool a_pack_is_equal = A2.elempack == B2.elempack;
    const bool a_size_is_lower = A2.w * A2.h * A2.d * A2.c * A2.elempack < B2.w * B2.h * B2.d * B2.c * B2.elempack;
    if (a_pack_is_lower || (a_pack_is_equal && a_size_is_lower))
    {
        binary_op_broadcast_bf16s(B2, A2, top_blob, get_reverse_op_type(op_type), opt);
    }
    else
    {
        binary_op_broadcast_bf16s(A2, B2, top_blob, op_type, opt);
    }

    return 0;
}

int BinaryOp_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    binary_op_scalar_inplace_bf16s(bottom_top_blob, float32_to_bfloat16(b), op_type, opt);

    return 0;
}

BNLL_mips::BNLL_mips()
{
#if __mips_msa
    support_packing = true;
    support_any_packing = true;
#endif
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int BNLL_mips::forward_inplace(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

#if NCNN_BF16
    if (opt.use_bf16_storage && bottom_top_blob.elembits() == 16)
        return forward_inplace_bf16s(bottom_top_blob, opt);
#endif

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        float* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __mips_msa
        v4f32 _zero = (v4f32)__msa_fill_w(0);
        v4f32 _one = (v4f32)__msa_fill_w_f32(1.f);
        for (; i + 3 < size; i += 4)
        {
            __builtin_prefetch(ptr + 16);

            v4f32 _p = (v4f32)__msa_ld_w(ptr, 0);
            v4f32 _abs_p = (v4f32)__msa_bclri_w((v4u32)_p, 31);
            v4f32 _tmp = log_ps(__msa_fadd_w(_one, exp_ps((v4f32)__msa_bnegi_w((v4u32)_abs_p, 31))));
            v4f32 _outp = __msa_fadd_w(__msa_fmax_w(_p, _zero), _tmp);
            __msa_st_w((v4i32)_outp, ptr, 0);

            ptr += 4;
        }
#endif
        for (; i < size; i++)
        {
            if (*ptr > 0.f)
                *ptr = *ptr + logf(1.f + expf(-*ptr));
            else
                *ptr = logf(1.f + expf(*ptr));

            ptr++;
        }
    }

    return 0;
}

int BNLL_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __mips_msa
        v4f32 _zero = (v4f32)__msa_fill_w(0);
        v4f32 _one = (v4f32)__msa_fill_w_f32(1.f);
        v8i16 _zero_bf16 = __msa_fill_h(0);
        for (; i + 7 < size; i += 8)
        {
            v8i16 _p01 = __msa_ld_h(ptr, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero_bf16);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero_bf16);
            v4f32 _abs_p0 = (v4f32)__msa_bclri_w((v4u32)_p0, 31);
            v4f32 _abs_p1 = (v4f32)__msa_bclri_w((v4u32)_p1, 31);
            v4f32 _tmp0 = log_ps(__msa_fadd_w(_one, exp_ps((v4f32)__msa_bnegi_w((v4u32)_abs_p0, 31))));
            v4f32 _tmp1 = log_ps(__msa_fadd_w(_one, exp_ps((v4f32)__msa_bnegi_w((v4u32)_abs_p1, 31))));
            v4f32 _outp0 = __msa_fadd_w(__msa_fmax_w(_p0, _zero), _tmp0);
            v4f32 _outp1 = __msa_fadd_w(__msa_fmax_w(_p1, _zero), _tmp1);
            __msa_st_w(float2bfloat_msa(_outp0, _outp1), ptr, 0);

            ptr += 8;
        }
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = bfloat2float_msa(ptr);
            v4f32 _abs_p = (v4f32)__msa_bclri_w((v4u32)_p, 31);
            v4f32 _tmp = log_ps(__msa_fadd_w(_one, exp_ps((v4f32)__msa_bnegi_w((v4u32)_abs_p, 31))));
            v4f32 _outp = __msa_fadd_w(__msa_fmax_w(_p, _zero), _tmp);
            *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_outp), 0);

            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            if (v > 0.f)
                v = v + logf(1.f + expf(-v));
            else
                v = logf(1.f + expf(v));
            *ptr = float32_to_bfloat16(v);
            ptr++;
        }
    }

    return 0;
}

int Clip_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __mips_msa
        v4f32 _min = (v4f32)__msa_fill_w_f32(min);
        v4f32 _max = (v4f32)__msa_fill_w_f32(max);
        v8i16 _zero = __msa_fill_h(0);
        for (; i + 7 < size; i += 8)
        {
            v8i16 _p01 = __msa_ld_h(ptr, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
            _p0 = __msa_fmax_w(_p0, _min);
            _p1 = __msa_fmax_w(_p1, _min);
            _p0 = __msa_fmin_w(_p0, _max);
            _p1 = __msa_fmin_w(_p1, _max);
            __msa_st_w(float2bfloat_msa(_p0, _p1), ptr, 0);
            ptr += 8;
        }
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = bfloat2float_msa(ptr);
            _p = __msa_fmax_w(_p, _min);
            _p = __msa_fmin_w(_p, _max);
            *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            if (v < min) v = min;
            if (v > max) v = max;
            *ptr = float32_to_bfloat16(v);
            ptr++;
        }
    }

    return 0;
}

int Convolution1D_mips::create_pipeline_bf16s(const Option& opt)
{
    int num_input = weight_data_size / kernel_w / num_output;

    convolution1d_transform_kernel_packed_bf16s(weight_data, weight_data_tm, num_input, num_output, kernel_w);

    if (opt.lightmode)
        weight_data.release();

    return 0;
}

int Convolution1D_mips::forward_bf16s(const Mat& bottom_blob, Mat& top_blob, const Option& opt) const
{
    int w = bottom_blob.w;
    size_t elemsize = bottom_blob.elemsize;
    int elempack = bottom_blob.elempack;

    const int kernel_extent_w = dilation_w * (kernel_w - 1) + 1;

    Mat bottom_blob_bordered;
    make_padding(bottom_blob, bottom_blob_bordered, opt);
    if (bottom_blob_bordered.empty())
        return -100;

    w = bottom_blob_bordered.w;

    int out_elempack = 1;
#if __mips_msa
    if (opt.use_packing_layout)
    {
        out_elempack = num_output % 8 == 0 ? 8 : num_output % 4 == 0 ? 4 : 1;
    }
#endif
    size_t out_elemsize = elemsize / elempack * out_elempack;

    const int outw = (w - kernel_extent_w) / stride_w + 1;
    const int outh = num_output / out_elempack;

    top_blob.create(outw, outh, out_elemsize, out_elempack, opt.blob_allocator);
    if (top_blob.empty())
        return -100;

    convolution1d_packed_bf16s(bottom_blob_bordered, top_blob, weight_data_tm, bias_data, kernel_w, dilation_w, stride_w, activation_type, activation_params, opt);

    return 0;
}

static bool test_prefer_winograd63(int num_input, int num_output, int w, int h)
{
    // winograd selection strategy (profiled on i7-7700 single thread)

    const int minwh = std::min(w, h);

    if (num_input >= 64)
    {
        return false;
    }
    if (num_input >= 32)
    {
        if (num_output >= 64) return false;
        if (num_output >= 32) return (minwh >= 11 && minwh <= 14)
                                         || (minwh >= 19 && minwh <= 20)
                                         || (minwh >= 23 && minwh <= 44)
                                         || (minwh >= 47 && minwh <= 56)
                                         || (minwh >= 63 && minwh <= 130);
        if (num_output >= 16) return (minwh >= 13 && minwh <= 14)
                                         || (minwh >= 19 && minwh <= 20)
                                         || (minwh >= 23 && minwh <= 38)
                                         || (minwh >= 43 && minwh <= 44)
                                         || (minwh >= 47 && minwh <= 140);
        if (num_output >= 8) return (minwh >= 11 && minwh <= 14)
                                        || (minwh >= 19 && minwh <= 20)
                                        || (minwh >= 31 && minwh <= 38)
                                        || (minwh >= 43 && minwh <= 44)
                                        || (minwh >= 55 && minwh <= 162);
        return false;
    }
    if (num_input >= 16)
    {
        if (num_output >= 64) return false;
        if (num_output >= 32) return (minwh >= 11 && minwh <= 14)
                                         || (minwh >= 19 && minwh <= 20)
                                         || (minwh >= 23 && minwh <= 44)
                                         || (minwh >= 47 && minwh <= 92)
                                         || (minwh >= 95 && minwh <= 188);
        if (num_output >= 16) return (minwh >= 11 && minwh <= 14)
                                         || (minwh >= 27 && minwh <= 38)
                                         || (minwh >= 43 && minwh <= 44)
                                         || (minwh >= 47 && minwh <= 74)
                                         || (minwh >= 81 && minwh <= 110)
                                         || (minwh >= 117 && minwh <= 170)
                                         || (minwh >= 177 && minwh <= 182);
        if (num_output >= 8) return (minwh >= 19 && minwh <= 20)
                                        || (minwh >= 33 && minwh <= 38)
                                        || (minwh >= 43 && minwh <= 44)
                                        || (minwh >= 47 && minwh <= 128)
                                        || (minwh >= 155 && minwh <= 210);
        return false;
    }
    if (num_input >= 8)
    {
        if (num_output >= 64) return false;
        if (num_output >= 32) return (minwh >= 7 && minwh <= 14)
                                         || (minwh >= 17 && minwh <= 20)
                                         || (minwh >= 23 && minwh <= 26)
                                         || (minwh >= 31 && minwh <= 38)
                                         || (minwh >= 43 && minwh <= 162);
        if (num_output >= 16) return minwh == 31 || minwh == 32
                                         || (minwh >= 39 && minwh <= 44)
                                         || (minwh >= 47 && minwh <= 212);
        if (num_output >= 8) return false;
        return false;
    }

    return false;
}

static bool test_prefer_winograd23(int num_input, int num_output, int w, int h)
{
    // winograd selection strategy (profiled on i7-7700 single thread)

    const int minwh = std::min(w, h);

    if (num_input >= 64)
    {
        return false;
    }
    if (num_input >= 32)
    {
        if (num_output >= 64) return false;
        if (num_output >= 32) return minwh >= 36;
        if (num_output >= 16) return minwh >= 28;
        if (num_output >= 8) return minwh >= 20;
        return false;
    }
    if (num_input >= 16)
    {
        if (num_output >= 64) return false;
        if (num_output >= 32) return minwh >= 24;
        if (num_output >= 16) return minwh >= 16;
        if (num_output >= 8) return minwh >= 12;
        return false;
    }
    if (num_input >= 8)
    {
        if (num_output >= 64) return false;
        if (num_output >= 32) return minwh >= 16;
        if (num_output >= 16) return minwh >= 8;
        if (num_output >= 8) return false;
        return false;
    }

    return false;
}

int Convolution_mips::create_pipeline_bf16s(const Option& opt)
{
    const int maxk = kernel_w * kernel_h;
    const int num_input = weight_data_size / maxk / num_output;

    nT = opt.num_threads;

    bool prefer_winograd = (opt.use_winograd23_convolution || opt.use_winograd43_convolution || opt.use_winograd63_convolution) && (num_input > 8 || num_output > 8);

    if (opt.use_winograd_convolution && prefer_winograd && kernel_w == 3 && kernel_h == 3 && dilation_w == 1 && dilation_h == 1 && stride_w == 1 && stride_h == 1)
    {
        if ((bottom_shapes.empty() || bottom_shapes[0].w == 0 || bottom_shapes[0].h == 0) && (top_shapes.empty() || top_shapes[0].w == 0 || top_shapes[0].h == 0))
            if ((opt.use_winograd63_convolution) && (num_input <= 32 && num_output <= 32))
                conv3x3s1_winograd63_transform_kernel(weight_data, weight_winograd63_data, num_input, num_output, opt);
            else if (opt.use_winograd43_convolution)
                conv3x3s1_winograd43_transform_kernel(weight_data, weight_winograd43_data, num_input, num_output, opt);
            else
                conv3x3s1_winograd23_transform_kernel(weight_data, weight_winograd23_data, num_input, num_output, opt);
            int w;
            int h;
            if (top_shapes.empty() || top_shapes[0].w == 0 || top_shapes[0].h == 0)
            {
                w = bottom_shapes[0].w;
                h = bottom_shapes[0].h;

                if (pad_left > 0 || pad_right > 0 || pad_top > 0 || pad_bottom > 0)
                {
                    w += pad_left + pad_right;
                    h += pad_top + pad_bottom;
                }
                else if ((pad_left == -233 && pad_right == -233 && pad_top == -233 && pad_bottom == -233)
                         || (pad_left == -234 && pad_right == -234 && pad_top == -234 && pad_bottom == -234))
                {
                    w += 2;
                    h += 2;
                }
            }
            else
            {
                w = top_shapes[0].w + 2;
                h = top_shapes[0].h + 2;
            }

            bool prefer_winograd63 = test_prefer_winograd63(num_input, num_output, w, h);
            bool prefer_winograd23 = test_prefer_winograd23(num_input, num_output, w, h);
            bool prefer_winograd43 = !prefer_winograd63 && !prefer_winograd23;

            if (prefer_winograd23 && !opt.use_winograd23_convolution)
            {
                prefer_winograd23 = false;
                prefer_winograd43 = true;
            }
            if (prefer_winograd63 && !opt.use_winograd63_convolution)
            {
                prefer_winograd63 = false;
                prefer_winograd43 = true;
            }
            if (prefer_winograd43 && !opt.use_winograd43_convolution)
            {
                prefer_winograd43 = false;
                if (opt.use_winograd63_convolution)
                    prefer_winograd63 = true;
                else
                    prefer_winograd23 = true;
            }

            if (prefer_winograd23)
                conv3x3s1_winograd23_transform_kernel(weight_data, weight_winograd23_data, num_input, num_output, opt);
            else if (prefer_winograd43)
                conv3x3s1_winograd43_transform_kernel(weight_data, weight_winograd43_data, num_input, num_output, opt);
            else if (prefer_winograd63)
                conv3x3s1_winograd63_transform_kernel(weight_data, weight_winograd63_data, num_input, num_output, opt);

        if (opt.lightmode)
            weight_data.release();

        return 0;
    int l2_cache_size = get_cpu_level2_cache_size();
    bool prefer_sgemm = num_input * num_output * kernel_w * kernel_h * dilation_w * dilation_h * stride_w * stride_h * (int)sizeof(unsigned short) * 2 > l2_cache_size || (num_input > 16 || num_output > 16);

    if ((opt.use_sgemm_convolution && prefer_sgemm) || (kernel_w == 1 && kernel_h == 1))
        convolution_im2col_gemm_transform_kernel_bf16s(weight_data, weight_sgemm_data, num_input, num_output, kernel_w, kernel_h, opt);

        if (opt.lightmode)
            weight_data.release();

        return 0;
    }

    convolution_transform_kernel_packed_bf16s(weight_data, weight_data_tm, num_input, num_output, kernel_w, kernel_h);

    if (opt.lightmode)
        weight_data.release();

    return 0;
}

GridSample_mips::GridSample_mips()
{
#if __mips_msa
    support_packing = true;
#endif // __mips_msa
}

GroupNorm_mips::GroupNorm_mips()
{
#if __mips_msa
    support_packing = true;
    support_any_packing = true;
#endif // __mips_msa
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int GroupNorm_mips::forward_inplace(Mat& bottom_top_blob, const Option& opt) const
{
#if NCNN_BF16
    if (opt.use_bf16_storage && bottom_top_blob.elembits() == 16)
        return forward_inplace_bf16s(bottom_top_blob, opt);
#endif

    const int dims = bottom_top_blob.dims;
    const int elempack = bottom_top_blob.elempack;
    const int channels_g = channels / group;

    int g_elempack = elempack;
#if __mips_msa
    if (opt.use_packing_layout && elempack == 4 && channels_g % 4 != 0)
        g_elempack = 1;
#endif // __mips_msa

    Mat bottom_top_blob_packed = bottom_top_blob;
    if (elempack != g_elempack)
    {
        Option opt_pack = opt;
        opt_pack.blob_allocator = opt.workspace_allocator;

        convert_packing(bottom_top_blob, bottom_top_blob_packed, g_elempack, opt_pack);
        if (bottom_top_blob_packed.empty())
            return -100;
    }

    if (dims == 1)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int g = 0; g < group; g++)
        {
            Mat bottom_top_blob_g = bottom_top_blob_packed.range(g * channels_g / g_elempack, channels_g / g_elempack);
            const float* gamma_ptr = affine ? (const float*)gamma_data + g * channels_g : 0;
            const float* beta_ptr = affine ? (const float*)beta_data + g * channels_g : 0;
            groupnorm_mips(bottom_top_blob_g, gamma_ptr, beta_ptr, eps, channels_g / g_elempack, g_elempack, g_elempack, 1);
        }
    }

    if (dims == 2)
    {
        const int w = bottom_top_blob_packed.w;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int g = 0; g < group; g++)
        {
            Mat bottom_top_blob_g = bottom_top_blob_packed.row_range(g * channels_g / g_elempack, channels_g / g_elempack);
            const float* gamma_ptr = affine ? (const float*)gamma_data + g * channels_g : 0;
            const float* beta_ptr = affine ? (const float*)beta_data + g * channels_g : 0;
            groupnorm_mips(bottom_top_blob_g, gamma_ptr, beta_ptr, eps, channels_g / g_elempack, w * g_elempack, g_elempack, w);
        }
    }

    if (dims == 3 || dims == 4)
    {
        const int size = bottom_top_blob_packed.w * bottom_top_blob_packed.h * bottom_top_blob_packed.d;
        const size_t cstep = bottom_top_blob_packed.cstep;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int g = 0; g < group; g++)
        {
            Mat bottom_top_blob_g = bottom_top_blob_packed.channel_range(g * channels_g / g_elempack, channels_g / g_elempack);
            const float* gamma_ptr = affine ? (const float*)gamma_data + g * channels_g : 0;
            const float* beta_ptr = affine ? (const float*)beta_data + g * channels_g : 0;
            groupnorm_mips(bottom_top_blob_g, gamma_ptr, beta_ptr, eps, channels_g / g_elempack, size * g_elempack, g_elempack, cstep);
        }
    }

    if (g_elempack != elempack)
    {
        convert_packing(bottom_top_blob_packed, bottom_top_blob, elempack, opt);
        if (bottom_top_blob.empty())
            return -100;
    }

    return 0;
}

int GroupNorm_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    const int dims = bottom_top_blob.dims;
    const int elempack = bottom_top_blob.elempack;
    const int channels_g = channels / group;

    int g_elempack = elempack;
#if __mips_msa
    if (opt.use_packing_layout && elempack == 8 && channels_g % 8 != 0)
        g_elempack = channels_g % 4 == 0 ? 4 : 1;
    if (opt.use_packing_layout && elempack == 4 && channels_g % 4 != 0)
        g_elempack = 1;
#endif // __mips_msa

    Mat bottom_top_blob_packed = bottom_top_blob;
    if (elempack != g_elempack)
    {
        Option opt_pack = opt;
        opt_pack.blob_allocator = opt.workspace_allocator;

        convert_packing(bottom_top_blob, bottom_top_blob_packed, g_elempack, opt_pack);
        if (bottom_top_blob_packed.empty())
            return -100;
    }

    if (dims == 1)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int g = 0; g < group; g++)
        {
            Mat bottom_top_blob_g = bottom_top_blob_packed.range(g * channels_g / g_elempack, channels_g / g_elempack);
            const float* gamma_ptr = affine ? (const float*)gamma_data + g * channels_g : 0;
            const float* beta_ptr = affine ? (const float*)beta_data + g * channels_g : 0;
            groupnorm_mips_bf16(bottom_top_blob_g, gamma_ptr, beta_ptr, eps, channels_g / g_elempack, g_elempack, g_elempack, 1);
        }
    }

    if (dims == 2)
    {
        const int w = bottom_top_blob_packed.w;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int g = 0; g < group; g++)
        {
            Mat bottom_top_blob_g = bottom_top_blob_packed.row_range(g * channels_g / g_elempack, channels_g / g_elempack);
            const float* gamma_ptr = affine ? (const float*)gamma_data + g * channels_g : 0;
            const float* beta_ptr = affine ? (const float*)beta_data + g * channels_g : 0;
            groupnorm_mips_bf16(bottom_top_blob_g, gamma_ptr, beta_ptr, eps, channels_g / g_elempack, w * g_elempack, g_elempack, w);
        }
    }

    if (dims == 3 || dims == 4)
    {
        const int size = bottom_top_blob_packed.w * bottom_top_blob_packed.h * bottom_top_blob_packed.d;
        const size_t cstep = bottom_top_blob_packed.cstep;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int g = 0; g < group; g++)
        {
            Mat bottom_top_blob_g = bottom_top_blob_packed.channel_range(g * channels_g / g_elempack, channels_g / g_elempack);
            const float* gamma_ptr = affine ? (const float*)gamma_data + g * channels_g : 0;
            const float* beta_ptr = affine ? (const float*)beta_data + g * channels_g : 0;
            groupnorm_mips_bf16(bottom_top_blob_g, gamma_ptr, beta_ptr, eps, channels_g / g_elempack, size * g_elempack, g_elempack, cstep);
        }
    }

    if (g_elempack != elempack)
    {
        convert_packing(bottom_top_blob_packed, bottom_top_blob, elempack, opt);
        if (bottom_top_blob.empty())
            return -100;
    }

    return 0;
}

int HardSigmoid_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __mips_msa
        v4f32 _zero = (v4f32)__msa_fill_w(0);
        v4f32 _one = (v4f32)__msa_fill_w_f32(1.f);
        v4f32 _alpha = (v4f32)__msa_fill_w_f32(alpha);
        v4f32 _beta = (v4f32)__msa_fill_w_f32(beta);
        v8i16 _zero_bf16 = __msa_fill_h(0);
        for (; i + 7 < size; i += 8)
        {
            v8i16 _p01 = __msa_ld_h(ptr, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero_bf16);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero_bf16);
            _p0 = __ncnn_msa_fmadd_w(_beta, _p0, _alpha);
            _p1 = __ncnn_msa_fmadd_w(_beta, _p1, _alpha);
            _p0 = __msa_fmax_w(_p0, _zero);
            _p1 = __msa_fmax_w(_p1, _zero);
            _p0 = __msa_fmin_w(_p0, _one);
            _p1 = __msa_fmin_w(_p1, _one);
            __msa_st_w(float2bfloat_msa(_p0, _p1), ptr, 0);
            ptr += 8;
        }
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = bfloat2float_msa(ptr);
            _p = __ncnn_msa_fmadd_w(_beta, _p, _alpha);
            _p = __msa_fmax_w(_p, _zero);
            _p = __msa_fmin_w(_p, _one);
            *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            if (v < lower)
                v = 0.f;
            else if (v > upper)
                v = 1.f;
            else
                v = v * alpha + beta;
            *ptr = float32_to_bfloat16(v);
            ++ptr;
        }
    }

    return 0;
}

int HardSwish_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __mips_msa
        v4f32 _alpha = (v4f32)__msa_fill_w_f32(alpha);
        v4f32 _beta = (v4f32)__msa_fill_w_f32(beta);
        v8i16 _zero = __msa_fill_h(0);
        for (; i + 7 < size; i += 8)
        {
            v8i16 _p01 = __msa_ld_h(ptr, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
            _p0 = hardswish_msa(_p0, _alpha, _beta);
            _p1 = hardswish_msa(_p1, _alpha, _beta);
            __msa_st_w(float2bfloat_msa(_p0, _p1), ptr, 0);
            ptr += 8;
        }
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = bfloat2float_msa(ptr);
            _p = hardswish_msa(_p, _alpha, _beta);
            *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            if (v < lower)
                v = 0.f;
            else if (v > upper)
                ;
            else
                v = v * (v * alpha + beta);
            *ptr = float32_to_bfloat16(v);
            ++ptr;
        }
    }

    return 0;
}

int InnerProduct_mips::create_pipeline_bf16s(const Option& opt)
{
    const int num_input = weight_data_size / num_output;

    innerproduct_transform_kernel_bf16s_msa(weight_data, weight_data_tm, num_input, num_output, opt);

    if (opt.lightmode)
        weight_data.release();

    return 0;
}

int InnerProduct_mips::forward_bf16s(const Mat& bottom_blob, Mat& top_blob, const Option& opt) const
{
    const int num_input = weight_data_size / num_output;

    if (bottom_blob.dims == 2 && bottom_blob.w == num_input)
    {
        // gemm
        int h = bottom_blob.h;
        size_t elemsize = bottom_blob.elemsize;
        int elempack = bottom_blob.elempack;

        top_blob.create(num_output, h, elemsize, elempack, opt.blob_allocator);
        if (top_blob.empty())
            return -100;

        innerproduct_gemm_bf16s_msa(bottom_blob, top_blob, weight_data_tm, bias_data, activation_type, activation_params, opt);

        return 0;
    }

    // flatten
    Mat bottom_blob_flattened = bottom_blob;
    if (bottom_blob.dims != 1)
    {
        Option opt_flatten = opt;
        opt_flatten.blob_allocator = opt.workspace_allocator;

        flatten->forward(bottom_blob, bottom_blob_flattened, opt_flatten);
        if (bottom_blob_flattened.empty())
            return -100;
    }

    size_t elemsize = bottom_blob_flattened.elemsize;
    int elempack = bottom_blob_flattened.elempack;

    int out_elempack = 1;
#if __mips_msa
    if (opt.use_packing_layout)
    {
        out_elempack = num_output % 8 == 0 ? 8 : num_output % 4 == 0 ? 4 : 1;
    }
#endif
    size_t out_elemsize = elemsize / elempack * out_elempack;

    top_blob.create(num_output / out_elempack, out_elemsize, out_elempack, opt.blob_allocator);
    if (top_blob.empty())
        return -100;

    innerproduct_bf16s_msa(bottom_blob_flattened, top_blob, weight_data_tm, bias_data, activation_type, activation_params, opt);

    return 0;
}

InstanceNorm_mips::InstanceNorm_mips()
{
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int InstanceNorm_mips::forward_inplace(Mat& bottom_top_blob, const Option& opt) const
{
#if NCNN_BF16
    if (opt.use_bf16_storage && bottom_top_blob.elembits() == 16)
        return forward_inplace_bf16s(bottom_top_blob, opt);
#endif

    // x = (x - mean) / (sqrt(var + eps)) * gamma + beta

    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int c = bottom_top_blob.c;
    int size = w * h;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < c; q++)
    {
        float* ptr = bottom_top_blob.channel(q);
        const float* ptr0 = ptr;

        // mean and var
        float sum = 0.f;
        float sqsum = 0.f;

        int i = 0;
#if __mips_msa
        v4f32 _sum = (v4f32)__msa_fill_w(0);
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = (v4f32)__msa_ld_w(ptr0, 0);
            _sum = __msa_fadd_w(_sum, _p);
            ptr0 += 4;
        }
        sum += __msa_reduce_fadd_w(_sum);
#endif // __mips_msa
        for (; i < size; i++)
        {
            sum += ptr0[0];
            ptr0++;
        }

        float mean = sum / size;
        float tmp = 0.f;

        ptr0 = ptr;
        i = 0;
#if __mips_msa
        v4f32 _sqsum = (v4f32)__msa_fill_w(0);
        v4f32 _mean = __msa_fill_w_f32(mean);
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = (v4f32)__msa_ld_w(ptr0, 0);
            _p = __msa_fsub_w(_p, _mean);
            _sqsum = __ncnn_msa_fmadd_w(_sqsum, _p, _p);
            ptr0 += 4;
        }
        sqsum += __msa_reduce_fadd_w(_sqsum);
#endif // __mips_msa
        for (; i < size; i++)
        {
            tmp = ptr0[0] - mean;
            sqsum += tmp * tmp;
            ptr0++;
        }

        float var = sqsum / size;
        // the var maybe minus due to accuracy

        float a;
        float b;
        if (affine)
        {
            float gamma = gamma_data[q];
            float beta = beta_data[q];

            a = gamma / (sqrtf(var + eps));
            b = -mean * a + beta;
        }
        else
        {
            a = 1.f / (sqrtf(var + eps));
            b = -mean * a;
        }

        i = 0;
#if __mips_msa
        v4f32 _a = __msa_fill_w_f32(a);
        v4f32 _b = __msa_fill_w_f32(b);
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = (v4f32)__msa_ld_w(ptr, 0);
            _p = __ncnn_msa_fmadd_w(_b, _p, _a);
            __msa_st_w((v4i32)_p, ptr, 0);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            ptr[0] = ptr[0] * a + b;
            ptr++;
        }
    }

    return 0;
}

int InstanceNorm_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    // x = (x - mean) / (sqrt(var + eps)) * gamma + beta

    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int c = bottom_top_blob.c;
    int size = w * h;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < c; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);
        const unsigned short* ptr0 = ptr;

        // mean and var
        float sum = 0.f;
        float sqsum = 0.f;

        int i = 0;
#if __mips_msa
        v4f32 _sum = (v4f32)__msa_fill_w(0);
        v8i16 _zero_bf16 = __msa_fill_h(0);
        for (; i + 7 < size; i += 8)
        {
            v8i16 _p01 = __msa_ld_h(ptr0, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero_bf16);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero_bf16);
            _sum = __msa_fadd_w(_sum, _p0);
            _sum = __msa_fadd_w(_sum, _p1);
            ptr0 += 8;
        }
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = bfloat2float_msa(ptr0);
            _sum = __msa_fadd_w(_sum, _p);
            ptr0 += 4;
        }
        sum += __msa_reduce_fadd_w(_sum);
#endif // __mips_msa
        for (; i < size; i++)
        {
            sum += bfloat16_to_float32(ptr0[0]);
            ptr0++;
        }

        float mean = sum / size;
        float tmp = 0.f;

        ptr0 = ptr;
        i = 0;
#if __mips_msa
        v4f32 _sqsum = (v4f32)__msa_fill_w(0);
        v4f32 _mean = __msa_fill_w_f32(mean);
        for (; i + 7 < size; i += 8)
        {
            v8i16 _p01 = __msa_ld_h(ptr0, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero_bf16);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero_bf16);
            _p0 = __msa_fsub_w(_p0, _mean);
            _p1 = __msa_fsub_w(_p1, _mean);
            _sqsum = __ncnn_msa_fmadd_w(_sqsum, _p0, _p0);
            _sqsum = __ncnn_msa_fmadd_w(_sqsum, _p1, _p1);
            ptr0 += 8;
        }
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = bfloat2float_msa(ptr0);
            _p = __msa_fsub_w(_p, _mean);
            _sqsum = __ncnn_msa_fmadd_w(_sqsum, _p, _p);
            ptr0 += 4;
        }
        sqsum += __msa_reduce_fadd_w(_sqsum);
#endif // __mips_msa
        for (; i < size; i++)
        {
            tmp = bfloat16_to_float32(ptr0[0]) - mean;
            sqsum += tmp * tmp;
            ptr0++;
        }

        float var = sqsum / size;
        // the var maybe minus due to accuracy

        float a;
        float b;
        if (affine)
        {
            float gamma = gamma_data[q];
            float beta = beta_data[q];

            a = gamma / (sqrtf(var + eps));
            b = -mean * a + beta;
        }
        else
        {
            a = 1.f / (sqrtf(var + eps));
            b = -mean * a;
        }

        i = 0;
#if __mips_msa
        v4f32 _a = __msa_fill_w_f32(a);
        v4f32 _b = __msa_fill_w_f32(b);
        for (; i + 7 < size; i += 8)
        {
            v8i16 _p01 = __msa_ld_h(ptr, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero_bf16);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero_bf16);
            _p0 = __ncnn_msa_fmadd_w(_b, _p0, _a);
            _p1 = __ncnn_msa_fmadd_w(_b, _p1, _a);
            __msa_st_w(float2bfloat_msa(_p0, _p1), ptr, 0);
            ptr += 8;
        }
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = bfloat2float_msa(ptr);
            _p = __ncnn_msa_fmadd_w(_b, _p, _a);
            *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            ptr[0] = float32_to_bfloat16(bfloat16_to_float32(ptr[0]) * a + b);
            ptr++;
        }
    }

    return 0;
}

static void interp_copy_bf16s(const unsigned short* ptr, unsigned short* outptr, int elempack)
{
#if __mips_msa
    if (elempack == 8)
    {
        v8i16 _p = (v8i16)__msa_ld_h(ptr, 0);
        __msa_st_h(_p, outptr, 0);
        return;
    }

    if (elempack == 4)
    {
        __msa_storel_d(__msa_loadl_d(ptr), outptr);
        return;
    }
#endif // __mips_msa

    for (int i = 0; i < elempack; i++)
    {
        outptr[i] = ptr[i];
    }
}

static void resize_bilinear_image_bf16s(const Mat& src, Mat& dst, float* alpha, int* xofs, float* beta, int* yofs)
{
    int w = dst.w;
    int h = dst.h;

    Mat rowsbuf0(w);
    Mat rowsbuf1(w);
    float* rows0 = rowsbuf0;
    float* rows1 = rowsbuf1;

    int prev_sy1 = -2;

    for (int dy = 0; dy < h; dy++)
    {
        int sy = yofs[dy];

        if (sy == prev_sy1)
        {
            // reuse all rows
        }
        else if (sy == prev_sy1 + 1)
        {
            // hresize one row
            float* rows0_old = rows0;
            rows0 = rows1;
            rows1 = rows0_old;
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx];
                const unsigned short* S1p = S1 + sx;

                float a0 = alphap[0];
                float a1 = alphap[1];
                rows1p[dx] = bfloat16_to_float32(S1p[0]) * a0 + bfloat16_to_float32(S1p[1]) * a1;

                alphap += 2;
            }
        }
        else
        {
            // hresize two rows
            const unsigned short* S0 = src.row<const unsigned short>(sy);
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows0p = rows0;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx];
                const unsigned short* S0p = S0 + sx;
                const unsigned short* S1p = S1 + sx;

                float a0 = alphap[0];
                float a1 = alphap[1];
                rows0p[dx] = bfloat16_to_float32(S0p[0]) * a0 + bfloat16_to_float32(S0p[1]) * a1;
                rows1p[dx] = bfloat16_to_float32(S1p[0]) * a0 + bfloat16_to_float32(S1p[1]) * a1;

                alphap += 2;
            }
        }

        prev_sy1 = sy;

        unsigned short* Dp = dst.row<unsigned short>(dy);

        int dx = 0;
#if __mips_msa
        v4f32 _b0 = __msa_fill_w_f32(beta[0]);
        v4f32 _b1 = __msa_fill_w_f32(beta[1]);
        for (; dx + 3 < w; dx += 4)
        {
            v4f32 _rows0 = (v4f32)__msa_ld_w(rows0 + dx, 0);
            v4f32 _rows1 = (v4f32)__msa_ld_w(rows1 + dx, 0);
            v4f32 _Dp = __msa_fmul_w(_rows0, _b0);
            _Dp = __ncnn_msa_fmadd_w(_Dp, _rows1, _b1);
            __msa_storel_d(float2bfloat_msa(_Dp), Dp + dx);
        }
#endif // __mips_msa
        for (; dx < w; dx++)
        {
            Dp[dx] = float32_to_bfloat16(rows0[dx] * beta[0] + rows1[dx] * beta[1]);
        }

        beta += 2;
    }
}

static void resize_bilinear_image_pack8_bf16s_msa(const Mat& src, Mat& dst, float* alpha, int* xofs, float* beta, int* yofs)
{
    int w = dst.w;
    int h = dst.h;

    Mat rowsbuf0(w, (size_t)8 * 4u, 8);
    Mat rowsbuf1(w, (size_t)8 * 4u, 8);
    float* rows0 = rowsbuf0;
    float* rows1 = rowsbuf1;

    int prev_sy1 = -2;

    for (int dy = 0; dy < h; dy++)
    {
        int sy = yofs[dy];

        if (sy == prev_sy1)
        {
            // reuse all rows
        }
        else if (sy == prev_sy1 + 1)
        {
            // hresize one row
            float* rows0_old = rows0;
            rows0 = rows1;
            rows1 = rows0_old;
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx] * 8;
                const unsigned short* S1p = S1 + sx;

                v4f32 _a0 = __msa_fill_w_f32(alphap[0]);
                v4f32 _a1 = __msa_fill_w_f32(alphap[1]);

                v8i16 _zero_bf16 = __msa_fill_h(0);
                v8i16 _S10 = (v8i16)__msa_ld_h(S1p, 0);
                v8i16 _S11 = (v8i16)__msa_ld_h(S1p + 8, 0);
                v4f32 _rows10 = __msa_fmul_w((v4f32)__msa_ilvr_h(_S10, _zero_bf16), _a0);
                v4f32 _rows11 = __msa_fmul_w((v4f32)__msa_ilvl_h(_S10, _zero_bf16), _a0);
                _rows10 = __ncnn_msa_fmadd_w(_rows10, (v4f32)__msa_ilvr_h(_S11, _zero_bf16), _a1);
                _rows11 = __ncnn_msa_fmadd_w(_rows11, (v4f32)__msa_ilvl_h(_S11, _zero_bf16), _a1);
                __msa_st_w((v4i32)_rows10, rows1p + dx * 8, 0);
                __msa_st_w((v4i32)_rows11, rows1p + dx * 8 + 4, 0);

                alphap += 2;
            }
        }
        else
        {
            // hresize two rows
            const unsigned short* S0 = src.row<const unsigned short>(sy);
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows0p = rows0;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx] * 8;
                const unsigned short* S0p = S0 + sx;
                const unsigned short* S1p = S1 + sx;

                v4f32 _a0 = __msa_fill_w_f32(alphap[0]);
                v4f32 _a1 = __msa_fill_w_f32(alphap[1]);

                v8i16 _zero_bf16 = __msa_fill_h(0);
                v8i16 _S00 = (v8i16)__msa_ld_h(S0p, 0);
                v8i16 _S01 = (v8i16)__msa_ld_h(S0p + 8, 0);
                v8i16 _S10 = (v8i16)__msa_ld_h(S1p, 0);
                v8i16 _S11 = (v8i16)__msa_ld_h(S1p + 8, 0);
                v4f32 _rows00 = __msa_fmul_w((v4f32)__msa_ilvr_h(_S00, _zero_bf16), _a0);
                v4f32 _rows01 = __msa_fmul_w((v4f32)__msa_ilvl_h(_S00, _zero_bf16), _a0);
                v4f32 _rows10 = __msa_fmul_w((v4f32)__msa_ilvr_h(_S10, _zero_bf16), _a0);
                v4f32 _rows11 = __msa_fmul_w((v4f32)__msa_ilvl_h(_S10, _zero_bf16), _a0);
                _rows00 = __ncnn_msa_fmadd_w(_rows00, (v4f32)__msa_ilvr_h(_S01, _zero_bf16), _a1);
                _rows01 = __ncnn_msa_fmadd_w(_rows01, (v4f32)__msa_ilvl_h(_S01, _zero_bf16), _a1);
                _rows10 = __ncnn_msa_fmadd_w(_rows10, (v4f32)__msa_ilvr_h(_S11, _zero_bf16), _a1);
                _rows11 = __ncnn_msa_fmadd_w(_rows11, (v4f32)__msa_ilvl_h(_S11, _zero_bf16), _a1);
                __msa_st_w((v4i32)_rows00, rows0p + dx * 8, 0);
                __msa_st_w((v4i32)_rows01, rows0p + dx * 8 + 4, 0);
                __msa_st_w((v4i32)_rows10, rows1p + dx * 8, 0);
                __msa_st_w((v4i32)_rows11, rows1p + dx * 8 + 4, 0);

                alphap += 2;
            }
        }

        prev_sy1 = sy;

        v4f32 _b0 = __msa_fill_w_f32(beta[0]);
        v4f32 _b1 = __msa_fill_w_f32(beta[1]);

        float* rows0p = rows0;
        float* rows1p = rows1;
        unsigned short* Dp = dst.row<unsigned short>(dy);

        for (int dx = 0; dx < w; dx++)
        {
            v4f32 _rows00 = (v4f32)__msa_ld_w(rows0p, 0);
            v4f32 _rows01 = (v4f32)__msa_ld_w(rows0p + 4, 0);
            v4f32 _rows10 = (v4f32)__msa_ld_w(rows1p, 0);
            v4f32 _rows11 = (v4f32)__msa_ld_w(rows1p + 4, 0);
            v4f32 _Dp0 = __msa_fmul_w(_rows00, _b0);
            v4f32 _Dp1 = __msa_fmul_w(_rows01, _b0);
            _Dp0 = __ncnn_msa_fmadd_w(_Dp0, _rows10, _b1);
            _Dp1 = __ncnn_msa_fmadd_w(_Dp1, _rows11, _b1);
            __msa_st_w(float2bfloat_msa(_Dp0, _Dp1), Dp, 0);

            Dp += 8;
            rows0p += 8;
            rows1p += 8;
        }

        beta += 2;
    }
}

static void resize_bilinear_image_pack4_bf16s_msa(const Mat& src, Mat& dst, float* alpha, int* xofs, float* beta, int* yofs)
{
    int w = dst.w;
    int h = dst.h;

    Mat rowsbuf0(w, (size_t)4 * 4u, 4);
    Mat rowsbuf1(w, (size_t)4 * 4u, 4);
    float* rows0 = rowsbuf0;
    float* rows1 = rowsbuf1;

    int prev_sy1 = -2;

    for (int dy = 0; dy < h; dy++)
    {
        int sy = yofs[dy];

        if (sy == prev_sy1)
        {
            // reuse all rows
        }
        else if (sy == prev_sy1 + 1)
        {
            // hresize one row
            float* rows0_old = rows0;
            rows0 = rows1;
            rows1 = rows0_old;
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx] * 4;
                const unsigned short* S1p = S1 + sx;

                v4f32 _a0 = __msa_fill_w_f32(alphap[0]);
                v4f32 _a1 = __msa_fill_w_f32(alphap[1]);

                v8i16 _zero_bf16 = __msa_fill_h(0);
                v8i16 _S1 = (v8i16)__msa_ld_h(S1p, 0);
                v4f32 _S10 = (v4f32)__msa_ilvr_h(_S1, _zero_bf16);
                v4f32 _S11 = (v4f32)__msa_ilvl_h(_S1, _zero_bf16);
                v4f32 _rows1 = __msa_fmul_w(_S10, _a0);
                _rows1 = __ncnn_msa_fmadd_w(_rows1, _S11, _a1);
                __msa_st_w((v4i32)_rows1, rows1p + dx * 4, 0);

                alphap += 2;
            }
        }
        else
        {
            // hresize two rows
            const unsigned short* S0 = src.row<const unsigned short>(sy);
            const unsigned short* S1 = src.row<const unsigned short>(sy + 1);

            const float* alphap = alpha;
            float* rows0p = rows0;
            float* rows1p = rows1;

            for (int dx = 0; dx < w; dx++)
            {
                int sx = xofs[dx] * 4;
                const unsigned short* S0p = S0 + sx;
                const unsigned short* S1p = S1 + sx;

                v4f32 _a0 = __msa_fill_w_f32(alphap[0]);
                v4f32 _a1 = __msa_fill_w_f32(alphap[1]);

                v8i16 _zero_bf16 = __msa_fill_h(0);
                v8i16 _S0 = (v8i16)__msa_ld_h(S0p, 0);
                v8i16 _S1 = (v8i16)__msa_ld_h(S1p, 0);
                v4f32 _S00 = (v4f32)__msa_ilvr_h(_S0, _zero_bf16);
                v4f32 _S01 = (v4f32)__msa_ilvl_h(_S0, _zero_bf16);
                v4f32 _S10 = (v4f32)__msa_ilvr_h(_S1, _zero_bf16);
                v4f32 _S11 = (v4f32)__msa_ilvl_h(_S1, _zero_bf16);
                v4f32 _rows0 = __msa_fmul_w(_S00, _a0);
                v4f32 _rows1 = __msa_fmul_w(_S10, _a0);
                _rows0 = __ncnn_msa_fmadd_w(_rows0, _S01, _a1);
                _rows1 = __ncnn_msa_fmadd_w(_rows1, _S11, _a1);
                __msa_st_w((v4i32)_rows0, rows0p + dx * 4, 0);
                __msa_st_w((v4i32)_rows1, rows1p + dx * 4, 0);

                alphap += 2;
            }
        }

        prev_sy1 = sy;

        v4f32 _b0 = __msa_fill_w_f32(beta[0]);
        v4f32 _b1 = __msa_fill_w_f32(beta[1]);

        float* rows0p = rows0;
        float* rows1p = rows1;
        unsigned short* Dp = dst.row<unsigned short>(dy);

        for (int dx = 0; dx < w; dx++)
        {
            v4f32 _rows0 = (v4f32)__msa_ld_w(rows0p, 0);
            v4f32 _rows1 = (v4f32)__msa_ld_w(rows1p, 0);
            v4f32 _Dp = __msa_fmul_w(_rows0, _b0);
            _Dp = __ncnn_msa_fmadd_w(_Dp, _rows1, _b1);
            __msa_storel_d(float2bfloat_msa(_Dp), Dp);

            Dp += 4;
            rows0p += 4;
            rows1p += 4;
        }

        beta += 2;
    }
}

LayerNorm_mips::LayerNorm_mips()
{
#if __mips_msa
    support_packing = true;
    support_any_packing = true;
#endif // __mips_msa
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int LayerNorm_mips::forward_inplace(Mat& bottom_top_blob, const Option& opt) const
{
#if NCNN_BF16
    if (opt.use_bf16_storage && bottom_top_blob.elembits() == 16)
        return forward_inplace_bf16s(bottom_top_blob, opt);
#endif

    const int dims = bottom_top_blob.dims;
    const int elempack = bottom_top_blob.elempack;
    const int w = bottom_top_blob.w;
    const int h = bottom_top_blob.h;
    const int channels = bottom_top_blob.c;

    if (dims == 1)
    {
        float* ptr = bottom_top_blob;
        layernorm_mips(ptr, gamma_data, beta_data, eps, w * elempack, 1);
    }

    if (dims == 2)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int i = 0; i < h; i++)
        {
            float* ptr = bottom_top_blob.row(i);
            layernorm_mips(ptr, gamma_data, beta_data, eps, w, elempack);
        }
    }

    if (dims == 3)
    {
        if (affine_size == w)
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int q = 0; q < channels; q++)
            {
                for (int i = 0; i < h; i++)
                {
                    float* ptr = bottom_top_blob.channel(q).row(i);
                    layernorm_mips(ptr, gamma_data, beta_data, eps, w, elempack);
                }
            }
        }
        else
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int q = 0; q < channels; q++)
            {
                float* ptr = bottom_top_blob.channel(q);
                layernorm_mips(ptr, gamma_data, beta_data, eps, w * h, elempack);
            }
        }
    }

    return 0;
}

int LayerNorm_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    const int dims = bottom_top_blob.dims;
    const int elempack = bottom_top_blob.elempack;
    const int w = bottom_top_blob.w;
    const int h = bottom_top_blob.h;
    const int channels = bottom_top_blob.c;

    if (dims == 1)
    {
        unsigned short* ptr = (unsigned short*)bottom_top_blob;
        layernorm_mips_bf16(ptr, gamma_data, beta_data, eps, w * elempack, 1);
    }

    if (dims == 2)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int i = 0; i < h; i++)
        {
            unsigned short* ptr = bottom_top_blob.row<unsigned short>(i);
            layernorm_mips_bf16(ptr, gamma_data, beta_data, eps, w, elempack);
        }
    }

    if (dims == 3)
    {
        if (affine_size == w)
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int q = 0; q < channels; q++)
            {
                for (int i = 0; i < h; i++)
                {
                    unsigned short* ptr = bottom_top_blob.channel(q).row<unsigned short>(i);
                    layernorm_mips_bf16(ptr, gamma_data, beta_data, eps, w, elempack);
                }
            }
        }
        else
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int q = 0; q < channels; q++)
            {
                unsigned short* ptr = bottom_top_blob.channel(q);
                layernorm_mips_bf16(ptr, gamma_data, beta_data, eps, w * h, elempack);
            }
        }
    }

    return 0;
}

LRN_mips::LRN_mips()
{
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int LRN_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    Option opt_cast = opt;
    opt_cast.blob_allocator = opt.workspace_allocator;

    Mat bottom_top_blob_fp32;
    cast_bfloat16_to_float32(bottom_top_blob, bottom_top_blob_fp32, opt_cast);
    if (bottom_top_blob_fp32.empty())
        return -100;

    int ret = forward_inplace(bottom_top_blob_fp32, opt);
    if (ret != 0)
        return ret;

    cast_float32_to_bfloat16(bottom_top_blob_fp32, bottom_top_blob, opt);
    if (bottom_top_blob.empty())
        return -100;

    return 0;
}

LSTM_mips::LSTM_mips()
{
    one_blob_only = false;
    support_inplace = false;

#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int LSTM_mips::create_pipeline(const Option& opt)
{
#if NCNN_INT8
    if (int8_scale_term)
    {
        return LSTM::create_pipeline(opt);
    }
#endif

    // pack IFOG
    int num_directions = direction == 2 ? 2 : 1;
    int size = weight_data_size / num_directions / hidden_size / 4;

    weight_xc_data_packed.create(size, hidden_size, num_directions, 16u, 4);
    bias_c_data_packed.create(hidden_size, 1, num_directions, 16u, 4);
    weight_hc_data_packed.create(num_output, hidden_size, num_directions, 16u, 4);

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int dr = 0; dr < num_directions; dr++)
    {
        const Mat weight_xc = weight_xc_data.channel(dr);
        const Mat bias_c = bias_c_data.channel(dr);
        const Mat weight_hc = weight_hc_data.channel(dr);

        Mat weight_xc_data_packed_dr = weight_xc_data_packed.channel(dr);
        Mat bias_c_data_packed_dr = bias_c_data_packed.channel(dr);
        Mat weight_hc_data_packed_dr = weight_hc_data_packed.channel(dr);

        const float* bias_c_I = bias_c.row(0);
        const float* bias_c_F = bias_c.row(1);
        const float* bias_c_O = bias_c.row(2);
        const float* bias_c_G = bias_c.row(3);

        float* bias_c_IFOG = bias_c_data_packed_dr.row(0);

        for (int q = 0; q < hidden_size; q++)
        {
            bias_c_IFOG[0] = bias_c_I[q];
            bias_c_IFOG[1] = bias_c_F[q];
            bias_c_IFOG[2] = bias_c_O[q];
            bias_c_IFOG[3] = bias_c_G[q];

            bias_c_IFOG += 4;

            const float* weight_xc_I = weight_xc.row(hidden_size * 0 + q);
            const float* weight_xc_F = weight_xc.row(hidden_size * 1 + q);
            const float* weight_xc_O = weight_xc.row(hidden_size * 2 + q);
            const float* weight_xc_G = weight_xc.row(hidden_size * 3 + q);

            const float* weight_hc_I = weight_hc.row(hidden_size * 0 + q);
            const float* weight_hc_F = weight_hc.row(hidden_size * 1 + q);
            const float* weight_hc_O = weight_hc.row(hidden_size * 2 + q);
            const float* weight_hc_G = weight_hc.row(hidden_size * 3 + q);

            float* weight_xc_IFOG = weight_xc_data_packed_dr.row(q);
            float* weight_hc_IFOG = weight_hc_data_packed_dr.row(q);

            for (int i = 0; i < size; i++)
            {
                weight_xc_IFOG[0] = weight_xc_I[i];
                weight_xc_IFOG[1] = weight_xc_F[i];
                weight_xc_IFOG[2] = weight_xc_O[i];
                weight_xc_IFOG[3] = weight_xc_G[i];

                weight_xc_IFOG += 4;
            }

            for (int i = 0; i < num_output; i++)
            {
                weight_hc_IFOG[0] = weight_hc_I[i];
                weight_hc_IFOG[1] = weight_hc_F[i];
                weight_hc_IFOG[2] = weight_hc_O[i];
                weight_hc_IFOG[3] = weight_hc_G[i];

                weight_hc_IFOG += 4;
            }
        }
    }

    if (opt.lightmode)
    {
        weight_xc_data.release();
        bias_c_data.release();
        weight_hc_data.release();
    }

    return 0;
}

static int cast_to_float32_if_needed(const Mat& src, Mat& dst, const Option& opt)
{
    if (src.elembits() != 16)
    {
        dst = src;
        return 0;
    }

#if NCNN_BF16
    Option opt_cast = opt;
    opt_cast.blob_allocator = opt.workspace_allocator;

    cast_bfloat16_to_float32(src, dst, opt_cast);
    if (dst.empty())
        return -100;

    return 0;
#else
    return -100;
#endif
}

int LSTM_mips::forward(const Mat& bottom_blob, Mat& top_blob, const Option& opt) const
{
#if NCNN_INT8
    if (int8_scale_term)
    {
        if (opt.use_bf16_storage && bottom_blob.elembits() == 16)
        {
            Mat bottom_blob_fp32;
            if (cast_to_float32_if_needed(bottom_blob, bottom_blob_fp32, opt) != 0)
                return -100;

            Option opt_fp32 = opt;
            opt_fp32.use_bf16_packed = false;
            opt_fp32.use_bf16_storage = false;

            Mat top_blob_fp32;
            int ret = LSTM::forward(bottom_blob_fp32, top_blob_fp32, opt_fp32);
            if (ret != 0)
                return ret;

#if NCNN_BF16
            cast_float32_to_bfloat16(top_blob_fp32, top_blob, opt);
            if (top_blob.empty())
                return -100;
#endif
            return 0;
        }

        return LSTM::forward(bottom_blob, top_blob, opt);
    }
#endif

    int T = bottom_blob.h;
    Mat bottom_blob_fp32 = bottom_blob;

    if (opt.use_bf16_storage && bottom_blob.elembits() == 16)
    {
        if (cast_to_float32_if_needed(bottom_blob, bottom_blob_fp32, opt) != 0)
            return -100;
    }

    int num_directions = direction == 2 ? 2 : 1;

    // initial hidden state
    Mat hidden(num_output, 4u, opt.workspace_allocator);
    if (hidden.empty())
        return -100;
    hidden.fill(0.f);

    Mat cell(hidden_size, 4u, opt.workspace_allocator);
    if (cell.empty())
        return -100;
    cell.fill(0.f);

    top_blob.create(num_output * num_directions, T, 4u, opt.blob_allocator);
    if (top_blob.empty())
        return -100;

    // Uni directional
    if (direction == 0 || direction == 1)
    {
        int ret = lstm(bottom_blob_fp32, top_blob, direction, weight_xc_data_packed.channel(0), bias_c_data_packed.channel(0), weight_hc_data_packed.channel(0), num_output == hidden_size ? Mat() : weight_hr_data.channel(0), hidden, cell, opt);
        if (ret != 0)
            return ret;
    }

    if (direction == 2)
    {
        Mat top_blob_forward(num_output, T, 4u, opt.workspace_allocator);
        if (top_blob_forward.empty())
            return -100;

        Mat top_blob_reverse(num_output, T, 4u, opt.workspace_allocator);
        if (top_blob_reverse.empty())
            return -100;

        {
            int ret = lstm(bottom_blob_fp32, top_blob_forward, 0, weight_xc_data_packed.channel(0), bias_c_data_packed.channel(0), weight_hc_data_packed.channel(0), num_output == hidden_size ? Mat() : weight_hr_data.channel(0), hidden, cell, opt);
            if (ret != 0)
                return ret;
        }

        hidden.fill(0.0f);
        cell.fill(0.0f);

        {
            int ret = lstm(bottom_blob_fp32, top_blob_reverse, 1, weight_xc_data_packed.channel(1), bias_c_data_packed.channel(1), weight_hc_data_packed.channel(1), num_output == hidden_size ? Mat() : weight_hr_data.channel(1), hidden, cell, opt);
            if (ret != 0)
                return ret;
        }

        // concat w
        for (int i = 0; i < T; i++)
        {
            const float* pf = top_blob_forward.row(i);
            const float* pr = top_blob_reverse.row(i);
            float* ptr = top_blob.row(i);

            memcpy(ptr, pf, num_output * sizeof(float));
            memcpy(ptr + num_output, pr, num_output * sizeof(float));
        }
    }

    if (opt.use_bf16_storage && bottom_blob.elembits() == 16)
    {
#if NCNN_BF16
        Mat top_blob_fp32 = top_blob;
        cast_float32_to_bfloat16(top_blob_fp32, top_blob, opt);
        if (top_blob.empty())
            return -100;
#endif
    }

    return 0;
}

int MatMul_mips::create_pipeline(const Option& opt)
{
    gemm = ncnn::create_layer_cpu(ncnn::LayerType::Gemm);

    ncnn::ParamDict pd;
    pd.set(2, 0);      // transA
    pd.set(3, transB); // transB
    pd.set(4, 0);      // constantA
    pd.set(5, 0);      // constantB
    pd.set(6, 1);      // constantC
    pd.set(7, 0);      // M = outch
    pd.set(8, 0);      // N = size
    pd.set(9, 0);      // K = maxk*inch
    pd.set(10, -1);    // constant_broadcast_type_C = null
    pd.set(11, 0);     // output_N1M
    pd.set(12, 1);     // output_elempack

    gemm->load_param(pd);

    gemm->load_model(ModelBinFromMatArray(0));

    gemm->create_pipeline(opt);

    return 0;
}

int MatMul_mips::destroy_pipeline(const Option& opt)
{
    if (gemm)
    {
        gemm->destroy_pipeline(opt);
        delete gemm;
        gemm = 0;
    }

    return 0;
}

int Mish_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __mips_msa
        v8i16 _zero = __msa_fill_h(0);
        for (; i + 7 < size; i += 8)
        {
            v8i16 _p01 = __msa_ld_h(ptr, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
            _p0 = mish_msa(_p0);
            _p1 = mish_msa(_p1);
            __msa_st_w(float2bfloat_msa(_p0, _p1), ptr, 0);
            ptr += 8;
        }
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = bfloat2float_msa(ptr);
            _p = mish_msa(_p);
            *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            v = v * tanhf(logf(expf(v) + 1.f));
            *ptr = float32_to_bfloat16(v);
            ptr++;
        }
    }

    return 0;
}

MultiHeadAttention_mips::MultiHeadAttention_mips()
{
#if __mips_msa
    support_packing = true;
#endif // __mips_msa
#if NCNN_BF16
    support_bf16_storage = true;
#endif

    q_gemm = 0;
    k_gemm = 0;
    v_gemm = 0;

    qk_gemm = 0;
    qkv_gemm = 0;

    qk_softmax = 0;

    o_gemm = 0;
}

int MultiHeadAttention_mips::destroy_pipeline(const Option& _opt)
{
    Option opt = _opt;
    if (int8_scale_term)
    {
        opt.use_packing_layout = false; // TODO enable packing
    }

    if (qk_softmax)
    {
        qk_softmax->destroy_pipeline(opt);
        delete qk_softmax;
        qk_softmax = 0;
    }

    if (q_gemm)
    {
        q_gemm->destroy_pipeline(opt);
        delete q_gemm;
        q_gemm = 0;
    }

    if (k_gemm)
    {
        k_gemm->destroy_pipeline(opt);
        delete k_gemm;
        k_gemm = 0;
    }

    if (v_gemm)
    {
        v_gemm->destroy_pipeline(opt);
        delete v_gemm;
        v_gemm = 0;
    }

    if (o_gemm)
    {
        o_gemm->destroy_pipeline(opt);
        delete o_gemm;
        o_gemm = 0;
    }

    if (qk_gemm)
    {
        qk_gemm->destroy_pipeline(opt);
        delete qk_gemm;
        qk_gemm = 0;
    }
    if (qkv_gemm)
    {
        qkv_gemm->destroy_pipeline(opt);
        delete qkv_gemm;
        qkv_gemm = 0;
    }

    return 0;
}

int Padding_mips::create_pipeline(const Option& opt)
{
#if NCNN_BF16
    if (opt.use_bf16_storage)
    {
        value_bf16 = float32_to_bfloat16(value);

        ncnn::cast_float32_to_bfloat16(per_channel_pad_data, per_channel_pad_data_bf16, opt);
    }
#endif

    return 0;
}

int Pooling_mips::forward_bf16s(const Mat& bottom_blob, Mat& top_blob, const Option& opt) const
{
    if (adaptive_pooling)
    {
        return Pooling::forward(bottom_blob, top_blob, opt);
    }

    int w = bottom_blob.w;
    int h = bottom_blob.h;
    int channels = bottom_blob.c;
    size_t elemsize = bottom_blob.elemsize;
    int elempack = bottom_blob.elempack;

    //     NCNN_LOGE("Pooling bf16s input %d x %d  pad = %d %d %d %d  ksize=%d %d  stride=%d %d", w, h, pad_left, pad_right, pad_top, pad_bottom, kernel_w, kernel_h, stride_w, stride_h);

    if (global_pooling)
    {
        top_blob.create(channels, elemsize, elempack, opt.blob_allocator);
        if (top_blob.empty())
            return -100;

        if (pooling_type == PoolMethod_MAX)
        {
            pooling_global_max_bf16s_msa(bottom_blob, top_blob, opt);
        }
        else if (pooling_type == PoolMethod_AVE)
        {
            pooling_global_avg_bf16s_msa(bottom_blob, top_blob, opt);
        }

        return 0;
    }

    Mat bottom_blob_bordered;
    make_padding(bottom_blob, bottom_blob_bordered, opt);
    if (bottom_blob_bordered.empty())
        return -100;

    w = bottom_blob_bordered.w;
    h = bottom_blob_bordered.h;

    int outw = (w - kernel_w) / stride_w + 1;
    int outh = (h - kernel_h) / stride_h + 1;

    top_blob.create(outw, outh, channels, elemsize, elempack, opt.blob_allocator);
    if (top_blob.empty())
        return -100;

    if (pooling_type == PoolMethod_MAX)
    {
        pooling_max_bf16s_msa(bottom_blob_bordered, top_blob, kernel_w, kernel_h, stride_w, stride_h, opt);
    }
    else if (pooling_type == PoolMethod_AVE)
    {
        pooling_avg_bf16s_msa(bottom_blob_bordered, bottom_blob, top_blob, kernel_w, kernel_h, stride_w, stride_h, pad_left, pad_right, pad_top, pad_bottom, pad_mode, avgpool_count_include_pad, opt);
    }

    return 0;
}

static void quantize_bf16(const unsigned short* ptr, signed char* s8ptr, const Mat& scale_data, int elemcount, int elempack)
{
    const int scale_data_size = scale_data.w;
    const int size = elemcount * elempack;

#if __mips_msa
    if (elempack == 8)
    {
        float scale = scale_data[0];
        v4f32 _scale0 = (v4f32)__msa_fill_w_f32(scale);
        v4f32 _scale1 = _scale0;
        if (scale_data_size > 1)
        {
            _scale0 = (v4f32)__msa_ld_w((const float*)scale_data, 0);
            _scale1 = (v4f32)__msa_ld_w((const float*)scale_data + 4, 0);
        }

        v8i16 _zero = __msa_fill_h(0);
        for (int i = 0; i < size; i += 8)
        {
            v8i16 _v01_bf16 = __msa_ld_h(ptr, 0);
            v4f32 _v0 = (v4f32)__msa_ilvr_h(_v01_bf16, _zero);
            v4f32 _v1 = (v4f32)__msa_ilvl_h(_v01_bf16, _zero);
            _v0 = __msa_fmul_w(_v0, _scale0);
            _v1 = __msa_fmul_w(_v1, _scale1);
            int64_t v = float2int8(_v0, _v1);
            *(int64_t*)s8ptr = v;
            ptr += 8;
            s8ptr += 8;
        }

        return;
    }
#endif // __mips_msa

    float scale = scale_data[0];
#if __mips_msa
    v4f32 _scale = (v4f32)__msa_fill_w_f32(scale);
    if (scale_data_size > 1)
    {
        if (elempack == 4)
        {
            _scale = (v4f32)__msa_ld_w((const float*)scale_data, 0);
        }
    }
#endif // __mips_msa

    int i = 0;
#if __mips_msa
    for (; i + 7 < size; i += 8)
    {
        v8i16 _zero = __msa_fill_h(0);
        v8i16 _v01_bf16 = __msa_ld_h(ptr, 0);
        v4f32 _v0 = (v4f32)__msa_ilvr_h(_v01_bf16, _zero);
        v4f32 _v1 = (v4f32)__msa_ilvl_h(_v01_bf16, _zero);
        _v0 = __msa_fmul_w(_v0, _scale);
        _v1 = __msa_fmul_w(_v1, _scale);
        *(int64_t*)s8ptr = float2int8(_v0, _v1);
        ptr += 8;
        s8ptr += 8;
    }
    for (; i + 3 < size; i += 4)
    {
        v4f32 _v = bfloat2float_msa(ptr);
        _v = __msa_fmul_w(_v, _scale);
        v16i8 v = float2int8(_v);
        int32_t vi = __msa_copy_s_w((v4i32)v, 0);
        s8ptr[0] = (vi >> 0) & 0xff;
        s8ptr[1] = (vi >> 8) & 0xff;
        s8ptr[2] = (vi >> 16) & 0xff;
        s8ptr[3] = (vi >> 24) & 0xff;
        ptr += 4;
        s8ptr += 4;
    }
#endif // __mips_msa
    for (; i < size; i++)
    {
        float v = bfloat16_to_float32(*ptr) * scale;
        *s8ptr = float2int8(v);
        ptr++;
        s8ptr++;
    }
}

static void quantize_bf16_pack4to8(const unsigned short* ptr0, const unsigned short* ptr1, signed char* s8ptr, const Mat& scale_data, int elemcount)
{
    const int scale_data_size = scale_data.w;

    float scale = scale_data[0];
    v4f32 _scale0 = (v4f32)__msa_fill_w_f32(scale);
    v4f32 _scale1 = _scale0;
    if (scale_data_size > 1)
    {
        _scale0 = (v4f32)__msa_ld_w((const float*)scale_data, 0);
        _scale1 = (v4f32)__msa_ld_w((const float*)scale_data + 4, 0);
    }

    int i = 0;
    v8i16 _zero = __msa_fill_h(0);
    for (; i + 1 < elemcount; i += 2)
    {
        v8i16 _v02_bf16 = __msa_ld_h(ptr0, 0);
        v8i16 _v13_bf16 = __msa_ld_h(ptr1, 0);
        v4f32 _v0 = (v4f32)__msa_ilvr_h(_v02_bf16, _zero);
        v4f32 _v2 = (v4f32)__msa_ilvl_h(_v02_bf16, _zero);
        v4f32 _v1 = (v4f32)__msa_ilvr_h(_v13_bf16, _zero);
        v4f32 _v3 = (v4f32)__msa_ilvl_h(_v13_bf16, _zero);
        _v0 = __msa_fmul_w(_v0, _scale0);
        _v1 = __msa_fmul_w(_v1, _scale1);
        _v2 = __msa_fmul_w(_v2, _scale0);
        _v3 = __msa_fmul_w(_v3, _scale1);
        int64_t v01 = float2int8(_v0, _v1);
        int64_t v23 = float2int8(_v2, _v3);
        const int* v01ptr = (const int*)&v01;
        const int* v23ptr = (const int*)&v23;
        v4i32 _result = __msa_set_w(v01ptr[0], v01ptr[1], v23ptr[0], v23ptr[1]);
        __msa_st_w(_result, s8ptr, 0);
        ptr0 += 8;
        ptr1 += 8;
        s8ptr += 16;
    }
    for (; i < elemcount; i++)
    {
        v4f32 _v0 = bfloat2float_msa(ptr0);
        v4f32 _v1 = bfloat2float_msa(ptr1);
        _v0 = __msa_fmul_w(_v0, _scale0);
        _v1 = __msa_fmul_w(_v1, _scale1);
        *(int64_t*)s8ptr = float2int8(_v0, _v1);
        ptr0 += 4;
        ptr1 += 4;
        s8ptr += 8;
    }
}

static void quantize_bf16_pack4to1(const unsigned short* ptr, signed char* s8ptr0, signed char* s8ptr1, signed char* s8ptr2, signed char* s8ptr3, const Mat& scale_data, int elemcount)
{
    const int scale_data_size = scale_data.w;

    float scale = scale_data[0];
    v4f32 _scale = (v4f32)__msa_fill_w_f32(scale);
    if (scale_data_size > 1)
    {
        _scale = (v4f32)__msa_ld_w((const float*)scale_data, 0);
    }

    int i = 0;
    v8i16 _zero = __msa_fill_h(0);
    for (; i + 7 < elemcount; i += 8)
    {
        v8i16 _v01_bf16 = __msa_ld_h(ptr, 0);
        v8i16 _v23_bf16 = __msa_ld_h(ptr + 8, 0);
        v8i16 _v45_bf16 = __msa_ld_h(ptr + 16, 0);
        v8i16 _v67_bf16 = __msa_ld_h(ptr + 24, 0);
        v4f32 _v0 = (v4f32)__msa_ilvr_h(_v01_bf16, _zero);
        v4f32 _v1 = (v4f32)__msa_ilvl_h(_v01_bf16, _zero);
        v4f32 _v2 = (v4f32)__msa_ilvr_h(_v23_bf16, _zero);
        v4f32 _v3 = (v4f32)__msa_ilvl_h(_v23_bf16, _zero);
        v4f32 _v4 = (v4f32)__msa_ilvr_h(_v45_bf16, _zero);
        v4f32 _v5 = (v4f32)__msa_ilvl_h(_v45_bf16, _zero);
        v4f32 _v6 = (v4f32)__msa_ilvr_h(_v67_bf16, _zero);
        v4f32 _v7 = (v4f32)__msa_ilvl_h(_v67_bf16, _zero);
        _v0 = __msa_fmul_w(_v0, _scale);
        _v1 = __msa_fmul_w(_v1, _scale);
        _v2 = __msa_fmul_w(_v2, _scale);
        _v3 = __msa_fmul_w(_v3, _scale);
        _v4 = __msa_fmul_w(_v4, _scale);
        _v5 = __msa_fmul_w(_v5, _scale);
        _v6 = __msa_fmul_w(_v6, _scale);
        _v7 = __msa_fmul_w(_v7, _scale);

        int64_t lo0426 = float2int8(_v0, _v4);
        int64_t hi0426 = float2int8(_v2, _v6);
        const int* lo0426ptr = (const int*)&lo0426;
        const int* hi0426ptr = (const int*)&hi0426;
        v16i8 v0426 = (v16i8)__msa_set_w(lo0426ptr[0], lo0426ptr[1], hi0426ptr[0], hi0426ptr[1]);

        int64_t lo1537 = float2int8(_v1, _v5);
        int64_t hi1537 = float2int8(_v3, _v7);
        const int* lo1537ptr = (const int*)&lo1537;
        const int* hi1537ptr = (const int*)&hi1537;
        v16i8 v1537 = (v16i8)__msa_set_w(lo1537ptr[0], lo1537ptr[1], hi1537ptr[0], hi1537ptr[1]);

        v16i8 v0145 = __msa_ilvr_b(v1537, v0426);
        v16i8 v2367 = __msa_ilvl_b(v1537, v0426);
        v16i8 v0123 = (v16i8)__msa_ilvr_h((v8i16)v2367, (v8i16)v0145);
        v16i8 v4567 = (v16i8)__msa_ilvl_h((v8i16)v2367, (v8i16)v0145);
        v16i8 v01 = (v16i8)__msa_ilvr_w((v4i32)v4567, (v4i32)v0123);
        v16i8 v23 = (v16i8)__msa_ilvl_w((v4i32)v4567, (v4i32)v0123);

        *(int64_t*)s8ptr0 = __msa_copy_s_d((v2i64)v01, 0);
        *(int64_t*)s8ptr1 = __msa_copy_s_d((v2i64)v01, 1);
        *(int64_t*)s8ptr2 = __msa_copy_s_d((v2i64)v23, 0);
        *(int64_t*)s8ptr3 = __msa_copy_s_d((v2i64)v23, 1);
        ptr += 32;
        s8ptr0 += 8;
        s8ptr1 += 8;
        s8ptr2 += 8;
        s8ptr3 += 8;
    }
    for (; i < elemcount; i++)
    {
        v4f32 _v = bfloat2float_msa(ptr);
        _v = __msa_fmul_w(_v, _scale);
        int64_t v = float2int8(_v, _v);
        s8ptr0[0] = (v >> 32) & 0xff;
        s8ptr1[0] = (v >> 40) & 0xff;
        s8ptr2[0] = (v >> 48) & 0xff;
        s8ptr3[0] = (v >> 56) & 0xff;
        ptr += 4;
        s8ptr0 += 1;
        s8ptr1 += 1;
        s8ptr2 += 1;
        s8ptr3 += 1;
    }
}

int ReLU_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    if (slope == 0.f)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int q = 0; q < channels; q++)
        {
            unsigned short* ptr = bottom_top_blob.channel(q);

            int i = 0;
#if __mips_msa
            v4f32 _zero = (v4f32)__msa_fill_w(0);
            v8i16 _zero_bf16 = __msa_fill_h(0);
            for (; i + 7 < size; i += 8)
            {
                v8i16 _p01 = __msa_ld_h(ptr, 0);
                v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero_bf16);
                v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero_bf16);
                _p0 = __msa_fmax_w(_p0, _zero);
                _p1 = __msa_fmax_w(_p1, _zero);
                __msa_st_w(float2bfloat_msa(_p0, _p1), ptr, 0);
                ptr += 8;
            }
            for (; i + 3 < size; i += 4)
            {
                v4f32 _p = bfloat2float_msa(ptr);
                _p = __msa_fmax_w(_p, _zero);
                *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
                ptr += 4;
            }
#endif // __mips_msa
            for (; i < size; i++)
            {
                float v = bfloat16_to_float32(*ptr);
                if (v < 0.f) v = 0.f;
                *ptr = float32_to_bfloat16(v);
                ptr++;
            }
        }
    }
    else
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int q = 0; q < channels; q++)
        {
            unsigned short* ptr = bottom_top_blob.channel(q);

            int i = 0;
#if __mips_msa
            v4f32 _zero = (v4f32)__msa_fill_w(0);
            v4f32 _slope = (v4f32)__msa_fill_w_f32(slope);
            v8i16 _zero_bf16 = __msa_fill_h(0);
            for (; i + 7 < size; i += 8)
            {
                v8i16 _p01 = __msa_ld_h(ptr, 0);
                v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero_bf16);
                v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero_bf16);
                v4f32 _pos0 = __msa_fmax_w(_p0, _zero);
                v4f32 _pos1 = __msa_fmax_w(_p1, _zero);
                v4f32 _neg0 = __msa_fmin_w(_p0, _zero);
                v4f32 _neg1 = __msa_fmin_w(_p1, _zero);
                _p0 = __msa_fadd_w(_pos0, __msa_fmul_w(_slope, _neg0));
                _p1 = __msa_fadd_w(_pos1, __msa_fmul_w(_slope, _neg1));
                __msa_st_w(float2bfloat_msa(_p0, _p1), ptr, 0);
                ptr += 8;
            }
            for (; i + 3 < size; i += 4)
            {
                v4f32 _p = bfloat2float_msa(ptr);
                v4f32 _pos = __msa_fmax_w(_p, _zero);
                v4f32 _neg = __msa_fmin_w(_p, _zero);
                _p = __msa_fadd_w(_pos, __msa_fmul_w(_slope, _neg));
                *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
                ptr += 4;
            }
#endif // __mips_msa
            for (; i < size; i++)
            {
                float v = bfloat16_to_float32(*ptr);
                if (v < 0.f) v *= slope;
                *ptr = float32_to_bfloat16(v);
                ptr++;
            }
        }
    }

    return 0;
}

Reshape_mips::Reshape_mips()
{
#if __mips_msa
    support_packing = true;
#endif // __mips_msa
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

RMSNorm_mips::RMSNorm_mips()
{
#if __mips_msa
    support_packing = true;
    support_any_packing = true;
#endif // __mips_msa
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

static void rmsnorm_mips(float* ptr, const float* gamma_ptr, float eps, int elemcount, int elempack)
{
    const int size = elemcount * elempack;

    // compute rms
#if __mips_msa
    v4f32 _rms = (v4f32)__msa_fill_w(0);
#endif // __mips_msa
    float rms = 0.f;
    {
        const float* ptr0 = ptr;
        int i = 0;
#if __mips_msa
        for (; i + 3 < size; i += 4)
        {
            __builtin_prefetch(ptr0 + 16);

            v4f32 _p = (v4f32)__msa_ld_w(ptr0, 0);
            _rms = __ncnn_msa_fmadd_w(_rms, _p, _p);
            ptr0 += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            rms += ptr0[0] * ptr0[0];
            ptr0++;
        }
    }

#if __mips_msa
    if (elempack == 4)
    {
        v4f32 _elemcount = __msa_fill_w_f32((float)elemcount);
        v4f32 _eps = __msa_fill_w_f32(eps);
        _rms = __msa_fdiv_w(_rms, _elemcount);
        _rms = __msa_fadd_w(_rms, _eps);
        _rms = __msa_frsqrt_w(_rms);
    }
#endif // __mips_msa
    if (elempack == 1)
    {
#if __mips_msa
        rms += __msa_reduce_fadd_w(_rms);
#endif // __mips_msa

        rms = 1.f / sqrtf(rms / elemcount + eps);
#if __mips_msa
        _rms = __msa_fill_w_f32(rms);
#endif // __mips_msa
    }
    if (gamma_ptr)
    {
        int i = 0;
#if __mips_msa
        if (elempack == 4)
        {
            for (; i + 3 < size; i += 4)
            {
                __builtin_prefetch(ptr + 16);

                v4f32 _p = (v4f32)__msa_ld_w(ptr, 0);
                v4f32 _gamma = __msa_fill_w_f32(gamma_ptr[0]);
                _p = __msa_fmul_w(_p, _rms);
                _p = __msa_fmul_w(_p, _gamma);
                __msa_st_w((v4i32)_p, ptr, 0);
                ptr += 4;
                gamma_ptr += 1;
            }
        }
        if (elempack == 1)
        {
            for (; i + 3 < size; i += 4)
            {
                __builtin_prefetch(ptr + 16);
                __builtin_prefetch(gamma_ptr + 16);

                v4f32 _p = (v4f32)__msa_ld_w(ptr, 0);
                v4f32 _gamma = (v4f32)__msa_ld_w(gamma_ptr, 0);
                _p = __msa_fmul_w(_p, _rms);
                _p = __msa_fmul_w(_p, _gamma);
                __msa_st_w((v4i32)_p, ptr, 0);
                ptr += 4;
                gamma_ptr += 4;
            }
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            ptr[0] = (ptr[0] * rms) * gamma_ptr[0];
            ptr++;
            gamma_ptr++;
        }
    }
    else
    {
        int i = 0;
#if __mips_msa
        for (; i + 3 < size; i += 4)
        {
            __builtin_prefetch(ptr + 16);

            v4f32 _p = (v4f32)__msa_ld_w(ptr, 0);
            _p = __msa_fmul_w(_p, _rms);
            __msa_st_w((v4i32)_p, ptr, 0);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            ptr[0] = ptr[0] * rms;
            ptr++;
        }
    }
}

int RMSNorm_mips::forward_inplace(Mat& bottom_top_blob, const Option& opt) const
{
#if NCNN_BF16
    if (opt.use_bf16_storage && bottom_top_blob.elembits() == 16)
        return forward_inplace_bf16s(bottom_top_blob, opt);
#endif

    const int dims = bottom_top_blob.dims;
    const int w = bottom_top_blob.w;
    const int h = bottom_top_blob.h;
    const int channels = bottom_top_blob.c;
    const int elempack = bottom_top_blob.elempack;

    if (dims == 1)
    {
        float* ptr = bottom_top_blob;
        rmsnorm_mips(ptr, gamma_data, eps, w * elempack, 1);
    }

    if (dims == 2)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int i = 0; i < h; i++)
        {
            float* ptr = bottom_top_blob.row(i);
            rmsnorm_mips(ptr, gamma_data, eps, w, elempack);
        }
    }

    if (dims == 3)
    {
        if (affine_size == w)
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int q = 0; q < channels; q++)
            {
                for (int i = 0; i < h; i++)
                {
                    float* ptr = bottom_top_blob.channel(q).row(i);
                    rmsnorm_mips(ptr, gamma_data, eps, w, elempack);
                }
            }
        }
        else
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int q = 0; q < channels; q++)
            {
                float* ptr = bottom_top_blob.channel(q);
                rmsnorm_mips(ptr, gamma_data, eps, w * h, elempack);
            }
        }
    }

    return 0;
}

int RMSNorm_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    const int dims = bottom_top_blob.dims;
    const int w = bottom_top_blob.w;
    const int h = bottom_top_blob.h;
    const int channels = bottom_top_blob.c;
    const int elempack = bottom_top_blob.elempack;

    if (dims == 1)
    {
        unsigned short* ptr = (unsigned short*)bottom_top_blob;
        rmsnorm_mips_bf16(ptr, gamma_data, eps, w * elempack, 1);
    }

    if (dims == 2)
    {
        #pragma omp parallel for num_threads(opt.num_threads)
        for (int i = 0; i < h; i++)
        {
            unsigned short* ptr = bottom_top_blob.row<unsigned short>(i);
            rmsnorm_mips_bf16(ptr, gamma_data, eps, w, elempack);
        }
    }

    if (dims == 3)
    {
        if (affine_size == w)
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int q = 0; q < channels; q++)
            {
                for (int i = 0; i < h; i++)
                {
                    unsigned short* ptr = bottom_top_blob.channel(q).row<unsigned short>(i);
                    rmsnorm_mips_bf16(ptr, gamma_data, eps, w, elempack);
                }
            }
        }
        else
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int q = 0; q < channels; q++)
            {
                unsigned short* ptr = bottom_top_blob.channel(q);
                rmsnorm_mips_bf16(ptr, gamma_data, eps, w * h, elempack);
            }
        }
    }

    return 0;
}

RotaryEmbed_mips::RotaryEmbed_mips()
{
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int RotaryEmbed_mips::forward(const std::vector<Mat>& bottom_blobs, std::vector<Mat>& top_blobs, const Option& opt) const
{
#if NCNN_BF16
    if (opt.use_bf16_storage && bottom_blobs[0].elembits() == 16)
        return forward_bf16s(bottom_blobs, top_blobs, opt);
#endif

    const Mat& bottom_blob = bottom_blobs[0];
    const Mat& cos_cache = bottom_blobs[1];
    const Mat& sin_cache = bottom_blobs[2];

    const int embed_dim = bottom_blob.w;
    const int seqlen = bottom_blob.h;
    const int num_heads = bottom_blob.c;

    Mat& top_blob = top_blobs[0];
    top_blob.create_like(bottom_blob, opt.blob_allocator);
    if (top_blob.empty())
        return -100;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < num_heads; q++)
    {
        const Mat head = bottom_blob.channel(q);
        Mat out_head = top_blob.channel(q);

        for (int i = 0; i < seqlen; i++)
        {
            if (interleaved)
            {
                const float* ptr = head.row(i);
                const float* cos_ptr = cos_cache.row(i);
                const float* sin_ptr = sin_cache.row(i);
                float* outptr = out_head.row(i);

                int j = 0;
#if __mips_msa
                v4i32 _signmask = __msa_fill_w(0);
                _signmask = __msa_insert_w(_signmask, 1, -1);
                _signmask = __msa_insert_w(_signmask, 3, -1);

                for (; j + 3 < embed_dim / 2; j += 4)
                {
                    v4f32 _a0 = (v4f32)__msa_ld_w(ptr, 0);
                    v4f32 _a1 = (v4f32)__msa_ld_w(ptr + 4, 0);

                    v4f32 _c4 = (v4f32)__msa_ld_w(cos_ptr, 0);
                    v4f32 _s4 = (v4f32)__msa_ld_w(sin_ptr, 0);

                    v4f32 _clo = (v4f32)__msa_ilvr_w((v4i32)_c4, (v4i32)_c4);
                    v4f32 _chi = (v4f32)__msa_ilvl_w((v4i32)_c4, (v4i32)_c4);
                    v4f32 _slo = (v4f32)__msa_ilvr_w((v4i32)_s4, (v4i32)_s4);
                    v4f32 _shi = (v4f32)__msa_ilvl_w((v4i32)_s4, (v4i32)_s4);

                    v4f32 _swap0 = (v4f32)__msa_shf_w((v4i32)_a0, _MSA_SHUFFLE(2, 3, 0, 1));
                    v4f32 _swap1 = (v4f32)__msa_shf_w((v4i32)_a1, _MSA_SHUFFLE(2, 3, 0, 1));

                    v4f32 _ac0 = __msa_fmul_w(_a0, _clo);
                    v4f32 _ac1 = __msa_fmul_w(_a1, _chi);
                    v4f32 _y0sub = __ncnn_msa_fmsub_w(_ac0, _swap0, _slo);
                    v4f32 _y0add = __ncnn_msa_fmadd_w(_ac0, _swap0, _slo);
                    v4f32 _y1sub = __ncnn_msa_fmsub_w(_ac1, _swap1, _shi);
                    v4f32 _y1add = __ncnn_msa_fmadd_w(_ac1, _swap1, _shi);

                    v4f32 _y0 = (v4f32)__msa_bsel_v((v16u8)_signmask, (v16u8)_y0sub, (v16u8)_y0add);
                    v4f32 _y1 = (v4f32)__msa_bsel_v((v16u8)_signmask, (v16u8)_y1sub, (v16u8)_y1add);

                    __msa_st_w((v4i32)_y0, outptr, 0);
                    __msa_st_w((v4i32)_y1, outptr + 4, 0);

                    ptr += 8;
                    outptr += 8;
                    cos_ptr += 4;
                    sin_ptr += 4;
                }
#endif // __mips_msa
                for (; j < embed_dim / 2; j++)
                {
                    const float x0 = ptr[0];
                    const float x1 = ptr[1];
                    const float cos_val = *cos_ptr++;
                    const float sin_val = *sin_ptr++;

                    outptr[0] = x0 * cos_val - x1 * sin_val;
                    outptr[1] = x0 * sin_val + x1 * cos_val;

                    ptr += 2;
                    outptr += 2;
                }
            }
            else
            {
                const float* ptr0 = head.row(i);
                const float* ptr1 = ptr0 + embed_dim / 2;
                const float* cos_ptr = cos_cache.row(i);
                const float* sin_ptr = sin_cache.row(i);
                float* outptr0 = out_head.row(i);
                float* outptr1 = outptr0 + embed_dim / 2;

                int j = 0;
#if __mips_msa
                for (; j + 3 < embed_dim / 2; j += 4)
                {
                    v4f32 _x0 = (v4f32)__msa_ld_w(ptr0, 0);
                    v4f32 _x1 = (v4f32)__msa_ld_w(ptr1, 0);
                    v4f32 _c = (v4f32)__msa_ld_w(cos_ptr, 0);
                    v4f32 _s = (v4f32)__msa_ld_w(sin_ptr, 0);

                    v4f32 _y0 = __ncnn_msa_fmsub_w(__msa_fmul_w(_x0, _c), _x1, _s);
                    v4f32 _y1 = __ncnn_msa_fmadd_w(__msa_fmul_w(_x1, _c), _x0, _s);

                    __msa_st_w((v4i32)_y0, outptr0, 0);
                    __msa_st_w((v4i32)_y1, outptr1, 0);

                    ptr0 += 4;
                    ptr1 += 4;
                    cos_ptr += 4;
                    sin_ptr += 4;
                    outptr0 += 4;
                    outptr1 += 4;
                }
#endif // __mips_msa
                for (; j < embed_dim / 2; j++)
                {
                    const float x0 = *ptr0++;
                    const float x1 = *ptr1++;
                    const float cos_val = *cos_ptr++;
                    const float sin_val = *sin_ptr++;

                    *outptr0++ = x0 * cos_val - x1 * sin_val;
                    *outptr1++ = x0 * sin_val + x1 * cos_val;
                }
            }
        }
    }

    return 0;
}

int RotaryEmbed_mips::forward_bf16s(const std::vector<Mat>& bottom_blobs, std::vector<Mat>& top_blobs, const Option& opt) const
{
    const Mat& bottom_blob = bottom_blobs[0];
    const Mat& cos_cache = bottom_blobs[1];
    const Mat& sin_cache = bottom_blobs[2];

    const int embed_dim = bottom_blob.w;
    const int seqlen = bottom_blob.h;
    const int num_heads = bottom_blob.c;

    Mat& top_blob = top_blobs[0];
    top_blob.create_like(bottom_blob, opt.blob_allocator);
    if (top_blob.empty())
        return -100;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < num_heads; q++)
    {
        const Mat head = bottom_blob.channel(q);
        Mat out_head = top_blob.channel(q);

        for (int i = 0; i < seqlen; i++)
        {
            if (interleaved)
            {
                const unsigned short* ptr = head.row<const unsigned short>(i);
                const unsigned short* cos_ptr = cos_cache.row<const unsigned short>(i);
                const unsigned short* sin_ptr = sin_cache.row<const unsigned short>(i);
                unsigned short* outptr = out_head.row<unsigned short>(i);

                int j = 0;
#if __mips_msa
                v4i32 _signmask = __msa_fill_w(0);
                _signmask = __msa_insert_w(_signmask, 1, -1);
                _signmask = __msa_insert_w(_signmask, 3, -1);
                v8i16 _zero_bf16 = __msa_fill_h(0);

                for (; j + 3 < embed_dim / 2; j += 4)
                {
                    v8i16 _a01 = (v8i16)__msa_ld_h(ptr, 0);
                    v4f32 _a0 = (v4f32)__msa_ilvr_h(_a01, _zero_bf16);
                    v4f32 _a1 = (v4f32)__msa_ilvl_h(_a01, _zero_bf16);

                    v4f32 _c4 = bfloat2float_msa(cos_ptr);
                    v4f32 _s4 = bfloat2float_msa(sin_ptr);

                    v4f32 _clo = (v4f32)__msa_ilvr_w((v4i32)_c4, (v4i32)_c4);
                    v4f32 _chi = (v4f32)__msa_ilvl_w((v4i32)_c4, (v4i32)_c4);
                    v4f32 _slo = (v4f32)__msa_ilvr_w((v4i32)_s4, (v4i32)_s4);
                    v4f32 _shi = (v4f32)__msa_ilvl_w((v4i32)_s4, (v4i32)_s4);

                    v4f32 _swap0 = (v4f32)__msa_shf_w((v4i32)_a0, _MSA_SHUFFLE(2, 3, 0, 1));
                    v4f32 _swap1 = (v4f32)__msa_shf_w((v4i32)_a1, _MSA_SHUFFLE(2, 3, 0, 1));

                    v4f32 _ac0 = __msa_fmul_w(_a0, _clo);
                    v4f32 _ac1 = __msa_fmul_w(_a1, _chi);
                    v4f32 _y0sub = __ncnn_msa_fmsub_w(_ac0, _swap0, _slo);
                    v4f32 _y0add = __ncnn_msa_fmadd_w(_ac0, _swap0, _slo);
                    v4f32 _y1sub = __ncnn_msa_fmsub_w(_ac1, _swap1, _shi);
                    v4f32 _y1add = __ncnn_msa_fmadd_w(_ac1, _swap1, _shi);

                    v4f32 _y0 = (v4f32)__msa_bsel_v((v16u8)_signmask, (v16u8)_y0sub, (v16u8)_y0add);
                    v4f32 _y1 = (v4f32)__msa_bsel_v((v16u8)_signmask, (v16u8)_y1sub, (v16u8)_y1add);

                    v4i32 _y01_bf16 = float2bfloat_msa(_y0, _y1);
                    __msa_st_h((v8i16)_y01_bf16, outptr, 0);

                    ptr += 8;
                    outptr += 8;
                    cos_ptr += 4;
                    sin_ptr += 4;
                }
#endif // __mips_msa
                for (; j < embed_dim / 2; j++)
                {
                    const float x0 = bfloat16_to_float32(ptr[0]);
                    const float x1 = bfloat16_to_float32(ptr[1]);
                    const float cos_val = bfloat16_to_float32(*cos_ptr++);
                    const float sin_val = bfloat16_to_float32(*sin_ptr++);

                    outptr[0] = float32_to_bfloat16(x0 * cos_val - x1 * sin_val);
                    outptr[1] = float32_to_bfloat16(x0 * sin_val + x1 * cos_val);

                    ptr += 2;
                    outptr += 2;
                }
            }
            else
            {
                const unsigned short* ptr0 = head.row<const unsigned short>(i);
                const unsigned short* ptr1 = ptr0 + embed_dim / 2;
                const unsigned short* cos_ptr = cos_cache.row<const unsigned short>(i);
                const unsigned short* sin_ptr = sin_cache.row<const unsigned short>(i);
                unsigned short* outptr0 = out_head.row<unsigned short>(i);
                unsigned short* outptr1 = outptr0 + embed_dim / 2;

                int j = 0;
#if __mips_msa
                for (; j + 3 < embed_dim / 2; j += 4)
                {
                    v4f32 _x0 = bfloat2float_msa(ptr0);
                    v4f32 _x1 = bfloat2float_msa(ptr1);
                    v4f32 _c = bfloat2float_msa(cos_ptr);
                    v4f32 _s = bfloat2float_msa(sin_ptr);

                    v4f32 _y0 = __ncnn_msa_fmsub_w(__msa_fmul_w(_x0, _c), _x1, _s);
                    v4f32 _y1 = __ncnn_msa_fmadd_w(__msa_fmul_w(_x1, _c), _x0, _s);

                    __msa_storel_d(float2bfloat_msa(_y0), outptr0);
                    __msa_storel_d(float2bfloat_msa(_y1), outptr1);

                    ptr0 += 4;
                    ptr1 += 4;
                    cos_ptr += 4;
                    sin_ptr += 4;
                    outptr0 += 4;
                    outptr1 += 4;
                }
#endif // __mips_msa
                for (; j < embed_dim / 2; j++)
                {
                    const float x0 = bfloat16_to_float32(*ptr0++);
                    const float x1 = bfloat16_to_float32(*ptr1++);
                    const float cos_val = bfloat16_to_float32(*cos_ptr++);
                    const float sin_val = bfloat16_to_float32(*sin_ptr++);

                    *outptr0++ = float32_to_bfloat16(x0 * cos_val - x1 * sin_val);
                    *outptr1++ = float32_to_bfloat16(x0 * sin_val + x1 * cos_val);
                }
            }
        }
    }

    return 0;
}

Scale_mips::Scale_mips()
{
#if __mips_msa
    support_packing = true;
#endif // __mips_msa
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

static void scale_bf16s_msa(unsigned short* ptr, const float* scale, const float* bias, int size, int elempack)
{
#if __mips_msa
    v4f32 _s0 = (elempack == 4) ? (v4f32)__msa_ld_w(scale, 0) : (v4f32)__msa_fill_w_f32(scale[0]);
    v4f32 _s1 = _s0;
    v4f32 _b0 = (elempack == 4) ? (v4f32)__msa_ld_w(bias, 0) : (v4f32)__msa_fill_w_f32(bias[0]);
    v4f32 _b1 = _b0;
    if (elempack == 8)
    {
        _s0 = (v4f32)__msa_ld_w(scale, 0);
        _s1 = (v4f32)__msa_ld_w(scale + 4, 0);
        _b0 = (v4f32)__msa_ld_w(bias, 0);
        _b1 = (v4f32)__msa_ld_w(bias + 4, 0);
    }
#endif
    float s = scale[0];
    float b = bias[0];

    int i = 0;
#if __mips_msa
    v8i16 _zero = __msa_fill_h(0);
    for (; i + 7 < size; i += 8)
    {
        v8i16 _p01 = __msa_ld_h(ptr, 0);
        v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
        v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
        _p0 = __ncnn_msa_fmadd_w(_b0, _p0, _s0);
        _p1 = __ncnn_msa_fmadd_w(_b1, _p1, _s1);
        __msa_st_w(float2bfloat_msa(_p0, _p1), ptr, 0);
        ptr += 8;
    }
    for (; i + 3 < size; i += 4)
    {
        v4f32 _p = bfloat2float_msa(ptr);
        _p = __ncnn_msa_fmadd_w(_b0, _p, _s0);
        *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
        ptr += 4;
    }
#endif // __mips_msa
    for (; i < size; i++)
    {
        *ptr = float32_to_bfloat16(bfloat16_to_float32(*ptr) * s + b);
        ptr++;
    }
}

static void scale_bf16s_no_bias_msa(unsigned short* ptr, const float* scale, int size, int elempack)
{
#if __mips_msa
    v4f32 _s0 = (elempack == 4) ? (v4f32)__msa_ld_w(scale, 0) : (v4f32)__msa_fill_w_f32(scale[0]);
    v4f32 _s1 = _s0;
    if (elempack == 8)
    {
        _s0 = (v4f32)__msa_ld_w(scale, 0);
        _s1 = (v4f32)__msa_ld_w(scale + 4, 0);
    }
#endif
    float s = scale[0];

    int i = 0;
#if __mips_msa
    v8i16 _zero = __msa_fill_h(0);
    for (; i + 7 < size; i += 8)
    {
        v8i16 _p01 = __msa_ld_h(ptr, 0);
        v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
        v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
        _p0 = __msa_fmul_w(_p0, _s0);
        _p1 = __msa_fmul_w(_p1, _s1);
        __msa_st_w(float2bfloat_msa(_p0, _p1), ptr, 0);
        ptr += 8;
    }
    for (; i + 3 < size; i += 4)
    {
        v4f32 _p = bfloat2float_msa(ptr);
        _p = __msa_fmul_w(_p, _s0);
        *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
        ptr += 4;
    }
#endif // __mips_msa
    for (; i < size; i++)
    {
        *ptr = float32_to_bfloat16(bfloat16_to_float32(*ptr) * s);
        ptr++;
    }
}

static void scale_bf16s_per_element_msa(unsigned short* ptr, const float* scale, const float* bias, int size, int num_threads)
{
    int nn_size = 0;
    int remain_size_start = 0;
#if __mips_msa
    nn_size = (size - remain_size_start) / 8;
    #pragma omp parallel for num_threads(num_threads)
    for (int ii = 0; ii < nn_size; ii++)
    {
        int i = remain_size_start + ii * 8;
        v8i16 _zero = __msa_fill_h(0);
        v8i16 _p01 = __msa_ld_h(ptr + i, 0);
        v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
        v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
        v4f32 _s0 = (v4f32)__msa_ld_w(scale + i, 0);
        v4f32 _s1 = (v4f32)__msa_ld_w(scale + i + 4, 0);
        v4f32 _b0 = (v4f32)__msa_ld_w(bias + i, 0);
        v4f32 _b1 = (v4f32)__msa_ld_w(bias + i + 4, 0);
        _p0 = __ncnn_msa_fmadd_w(_b0, _p0, _s0);
        _p1 = __ncnn_msa_fmadd_w(_b1, _p1, _s1);
        __msa_st_w(float2bfloat_msa(_p0, _p1), ptr + i, 0);
    }
    remain_size_start += nn_size * 8;

    nn_size = (size - remain_size_start) / 4;
    #pragma omp parallel for num_threads(num_threads)
    for (int ii = 0; ii < nn_size; ii++)
    {
        int i = remain_size_start + ii * 4;
        v4f32 _p = bfloat2float_msa(ptr + i);
        v4f32 _s = (v4f32)__msa_ld_w(scale + i, 0);
        v4f32 _b = (v4f32)__msa_ld_w(bias + i, 0);
        _p = __ncnn_msa_fmadd_w(_b, _p, _s);
        *(int64_t*)(ptr + i) = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
    }
    remain_size_start += nn_size * 4;
#endif // __mips_msa
    #pragma omp parallel for num_threads(num_threads)
    for (int i = remain_size_start; i < size; i++)
    {
        ptr[i] = float32_to_bfloat16(bfloat16_to_float32(ptr[i]) * scale[i] + bias[i]);
    }
}

static void scale_bf16s_no_bias_per_element_msa(unsigned short* ptr, const float* scale, int size, int num_threads)
{
    int nn_size = 0;
    int remain_size_start = 0;
#if __mips_msa
    nn_size = (size - remain_size_start) / 8;
    #pragma omp parallel for num_threads(num_threads)
    for (int ii = 0; ii < nn_size; ii++)
    {
        int i = remain_size_start + ii * 8;
        v8i16 _zero = __msa_fill_h(0);
        v8i16 _p01 = __msa_ld_h(ptr + i, 0);
        v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
        v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
        v4f32 _s0 = (v4f32)__msa_ld_w(scale + i, 0);
        v4f32 _s1 = (v4f32)__msa_ld_w(scale + i + 4, 0);
        _p0 = __msa_fmul_w(_p0, _s0);
        _p1 = __msa_fmul_w(_p1, _s1);
        __msa_st_w(float2bfloat_msa(_p0, _p1), ptr + i, 0);
    }
    remain_size_start += nn_size * 8;

    nn_size = (size - remain_size_start) / 4;
    #pragma omp parallel for num_threads(num_threads)
    for (int ii = 0; ii < nn_size; ii++)
    {
        int i = remain_size_start + ii * 4;
        v4f32 _p = bfloat2float_msa(ptr + i);
        v4f32 _s = (v4f32)__msa_ld_w(scale + i, 0);
        _p = __msa_fmul_w(_p, _s);
        *(int64_t*)(ptr + i) = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
    }
    remain_size_start += nn_size * 4;
#endif // __mips_msa
    #pragma omp parallel for num_threads(num_threads)
    for (int i = remain_size_start; i < size; i++)
    {
        ptr[i] = float32_to_bfloat16(bfloat16_to_float32(ptr[i]) * scale[i]);
    }
}

int Scale_mips::forward_inplace_bf16s(std::vector<Mat>& bottom_top_blobs, const Option& opt) const
{
    Mat& bottom_top_blob = bottom_top_blobs[0];
    const Mat& scale_blob = bottom_top_blobs[1];

    const int w = bottom_top_blob.w;
    const int h = bottom_top_blob.h;
    const int channels = bottom_top_blob.c;
    const int dims = bottom_top_blob.dims;
    const int elempack = bottom_top_blob.elempack;

    const float* scale = 0;
    Mat scale_fp32;
    if (scale_blob.elembits() == 16)
    {
        const int scale_data_size = scale_blob.w * scale_blob.elempack;
        scale_fp32.create(scale_data_size, 4u, 1, opt.workspace_allocator);
        if (scale_fp32.empty())
            return -100;

        const unsigned short* src = scale_blob;
        float* dst = scale_fp32;
        for (int i = 0; i < scale_data_size; i++)
        {
            dst[i] = bfloat16_to_float32(src[i]);
        }
        scale = scale_fp32;
    }
    else
    {
        scale = scale_blob;
    }
    const float* bias = bias_data;

    if (dims == 1)
    {
        unsigned short* ptr = bottom_top_blob;
        const int size = w * elempack;

        if (bias_term)
        {
            scale_bf16s_per_element_msa(ptr, scale, bias, size, opt.num_threads);
        }
        else
        {
            scale_bf16s_no_bias_per_element_msa(ptr, scale, size, opt.num_threads);
        }

        return 0;
    }

    if (dims == 2)
    {
        const int size = w * elempack;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int i = 0; i < h; i++)
        {
            unsigned short* ptr = bottom_top_blob.row<unsigned short>(i);
            const float* sptr = scale + i * elempack;

            if (bias_term)
            {
                const float* bptr = bias + i * elempack;
                scale_bf16s_msa(ptr, sptr, bptr, size, elempack);
            }
            else
            {
                scale_bf16s_no_bias_msa(ptr, sptr, size, elempack);
            }
        }

        return 0;
    }

    if (dims == 3)
    {
        const int size = w * h * elempack;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int q = 0; q < channels; q++)
        {
            unsigned short* ptr = bottom_top_blob.channel(q);
            const float* sptr = scale + q * elempack;

            if (bias_term)
            {
                const float* bptr = bias + q * elempack;
                scale_bf16s_msa(ptr, sptr, bptr, size, elempack);
            }
            else
            {
                scale_bf16s_no_bias_msa(ptr, sptr, size, elempack);
            }
        }

        return 0;
    }

    return 0;
}

SDPA_mips::SDPA_mips()
{
#if NCNN_BF16
    support_bf16_storage = true;
#endif

    qk_gemm = 0;
    qkv_gemm = 0;
    qk_softmax = 0;
}

int SDPA_mips::create_pipeline(const Option& _opt)
{
    Option opt = _opt;
    if (int8_scale_term)
    {
        opt.use_packing_layout = false; // TODO enable packing
        support_bf16_storage = false;
    }

    {
        qk_softmax = ncnn::create_layer_cpu(ncnn::LayerType::Softmax);
        ncnn::ParamDict pd;
        pd.set(0, -1); // axis
        pd.set(1, 1);
        qk_softmax->load_param(pd);
        qk_softmax->load_model(ModelBinFromMatArray(0));
        qk_softmax->create_pipeline(opt);
    }

    // Q * K^T
    if (scale != 0.f)
    {
        qk_gemm = ncnn::create_layer_cpu(ncnn::LayerType::Gemm);
        ncnn::ParamDict pd;

        pd.set(0, scale);               // alpha
        pd.set(1, 1.f / scale);         // beta
        pd.set(2, 0);                   // transA (Q: Seq x Embed)
        pd.set(3, 1);                   // transB (K: Seq x Embed -> K^T: Embed x Seq) => Q * K^T
        pd.set(4, 0);                   // constantA
        pd.set(5, 0);                   // constantB
        pd.set(6, attn_mask ? 0 : 1);   // constantC (if mask exists, use it)
        pd.set(7, 0);                   // M
        pd.set(8, 0);                   // N
        pd.set(9, 0);                   // K
        pd.set(10, attn_mask ? 3 : -1); // constant_broadcast_type_C (MxN)
        pd.set(11, 0);                  // output_N1M
        pd.set(12, 1);                  // output_elempack
        pd.set(13, 1);                  // output_elemtype = fp32
#if NCNN_INT8
        pd.set(18, int8_scale_term);
#endif
        qk_gemm->load_param(pd);
        qk_gemm->load_model(ModelBinFromMatArray(0));
        Option opt1 = opt;
        opt1.num_threads = 1;
        qk_gemm->create_pipeline(opt1);
    }

    // Attn * V
    {
        qkv_gemm = ncnn::create_layer_cpu(ncnn::LayerType::Gemm);
        ncnn::ParamDict pd;
        pd.set(0, 1.f); // alpha
        pd.set(1, 1.f); // beta
        pd.set(2, 0);   // transA (Attn: Seq x Seq)
        pd.set(3, 0);   // transB (V: Seq x Embed) => Attn * V
        pd.set(4, 0);   // constantA
        pd.set(5, 0);   // constantB
        pd.set(6, 1);   // constantC (None)
        pd.set(7, 0);   // M
        pd.set(8, 0);   // N
        pd.set(9, 0);   // K
        pd.set(10, -1); // constant_broadcast_type_C
        pd.set(11, 0);  // output_N1M
        pd.set(12, 1);  // output_elempack
        pd.set(13, 1);  // output_elemtype = fp32
        pd.set(14, 0);  // output_transpose
#if NCNN_INT8
        pd.set(18, int8_scale_term);
#endif
        qkv_gemm->load_param(pd);
        qkv_gemm->load_model(ModelBinFromMatArray(0));
        Option opt1 = opt;
        opt1.num_threads = 1;
        qkv_gemm->create_pipeline(opt1);
    }

    return 0;
}

int SDPA_mips::destroy_pipeline(const Option& _opt)
{
    Option opt = _opt;
    if (int8_scale_term)
    {
        opt.use_packing_layout = false; // TODO enable packing
    }

    if (qk_softmax)
    {
        qk_softmax->destroy_pipeline(opt);
        delete qk_softmax;
        qk_softmax = 0;
    }

    if (qk_gemm)
    {
        qk_gemm->destroy_pipeline(opt);
        delete qk_gemm;
        qk_gemm = 0;
    }

    if (qkv_gemm)
    {
        qkv_gemm->destroy_pipeline(opt);
        delete qkv_gemm;
        qkv_gemm = 0;
    }

    return 0;
}

int SELU_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __mips_msa
        v4f32 _zero = (v4f32)__msa_fill_w_f32(0.f);
        v4f32 _alpha = (v4f32)__msa_fill_w_f32(alpha);
        v4f32 _lambda = (v4f32)__msa_fill_w_f32(lambda);
        v4f32 _alpha_lambda = (v4f32)__msa_fill_w_f32(alpha * lambda);
        v8i16 _zero_bf16 = __msa_fill_h(0);
        for (; i + 7 < size; i += 8)
        {
            v8i16 _p01 = __msa_ld_h(ptr, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero_bf16);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero_bf16);
            v4f32 _pos0 = __msa_fmul_w(_lambda, _p0);
            v4f32 _pos1 = __msa_fmul_w(_lambda, _p1);
            v4f32 _neg0 = __msa_fmul_w(__msa_fsub_w(__msa_fmul_w(exp_ps(_p0), _alpha), _alpha), _lambda);
            v4f32 _neg1 = __msa_fmul_w(__msa_fsub_w(__msa_fmul_w(exp_ps(_p1), _alpha), _alpha), _lambda);
            v4i32 _mask0 = __msa_fclt_w(_p0, _zero);
            v4i32 _mask1 = __msa_fclt_w(_p1, _zero);
            _p0 = (v4f32)__msa_bsel_v((v16u8)_mask0, (v16u8)_pos0, (v16u8)_neg0);
            _p1 = (v4f32)__msa_bsel_v((v16u8)_mask1, (v16u8)_pos1, (v16u8)_neg1);
            __msa_st_w(float2bfloat_msa(_p0, _p1), ptr, 0);
            ptr += 8;
        }
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = bfloat2float_msa(ptr);
            v4f32 _pos = __msa_fmul_w(_lambda, _p);
            v4f32 _neg = __msa_fmul_w(__msa_fsub_w(__msa_fmul_w(exp_ps(_p), _alpha), _alpha), _lambda);
            v4i32 _mask = __msa_fclt_w(_p, _zero);
            _p = (v4f32)__msa_bsel_v((v16u8)_mask, (v16u8)_pos, (v16u8)_neg);
            *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            if (v < 0.f)
                v = (expf(v) * alpha - alpha) * lambda;
            else
                v = v * lambda;
            *ptr = float32_to_bfloat16(v);
            ptr++;
        }
    }

    return 0;
}

ShuffleChannel_mips::ShuffleChannel_mips()
{
#if __mips_msa
    support_packing = true;
    support_any_packing = true;
#endif // __mips_msa
#if NCNN_BF16
    support_bf16_storage = true;
#endif
}

int Sigmoid_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __mips_msa
        v4f32 _one = (v4f32)__msa_fill_w_f32(1.f);
        v8i16 _zero = __msa_fill_h(0);
        for (; i + 7 < size; i += 8)
        {
            v8i16 _p01 = __msa_ld_h(ptr, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
            _p0 = (v4f32)__msa_bnegi_w((v4u32)_p0, 31);
            _p1 = (v4f32)__msa_bnegi_w((v4u32)_p1, 31);
            _p0 = exp_ps(_p0);
            _p1 = exp_ps(_p1);
            _p0 = __msa_fadd_w(_p0, _one);
            _p1 = __msa_fadd_w(_p1, _one);
            v4f32 _outp0 = __msa_fdiv_w(_one, _p0);
            v4f32 _outp1 = __msa_fdiv_w(_one, _p1);
            __msa_st_w(float2bfloat_msa(_outp0, _outp1), ptr, 0);
            ptr += 8;
        }
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = bfloat2float_msa(ptr);
            _p = (v4f32)__msa_bnegi_w((v4u32)_p, 31);
            _p = exp_ps(_p);
            _p = __msa_fadd_w(_p, _one);
            v4f32 _outp = __msa_fdiv_w(_one, _p);
            *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_outp), 0);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            v = 1.f / (1.f + expf(-v));
            *ptr = float32_to_bfloat16(v);
            ptr++;
        }
    }

    return 0;
}

static void softmax(float* _ptr, int elemcount, int elempack)
{
    const int size = elemcount * elempack;
    // reduce max
#if __mips_msa
    v4f32 _max = (v4f32)__msa_fill_w_f32(-FLT_MAX);
#endif // __mips_msa
    float max = -FLT_MAX;
    {
        const float* ptr = _ptr;

        int i = 0;
#if __mips_msa
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = (v4f32)__msa_ld_w(ptr, 0);
            _max = __msa_fmax_w(_max, _p);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            max = std::max(max, *ptr++);
        }
    }
#if __mips_msa
    if (elempack == 1)
    {
        max = std::max(max, __msa_reduce_fmax_w(_max));
        _max = (v4f32)__msa_fill_w_f32(max);
    }
#endif // __mips_msa
    // reduce exp(x - max)
#if __mips_msa
    v4f32 _sum = (v4f32)__msa_fill_w_f32(0.f);
#endif // __mips_msa
    float sum = 0.f;
        float* ptr = _ptr;
        int i = 0;
#if __mips_msa
        for (; i + 3 < size; i += 4)
            v4f32 _p = (v4f32)__msa_ld_w(ptr, 0);
            _p = __msa_fsub_w(_p, _max);
            _p = exp_ps(_p);
            __msa_st_w((v4i32)_p, ptr, 0);
            _sum = __msa_fadd_w(_sum, _p);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            float v = expf(*ptr - max);
            *ptr = v;
            sum += v;
            ptr++;
#if __mips_msa
    if (elempack == 4)
        v4f32 _one = (v4f32)__msa_fill_w_f32(1.f);
        _sum = __msa_fdiv_w(_one, _sum);
    }
#endif // __mips_msa
    if (elempack == 1)
    {
#if __mips_msa
        sum += __msa_reduce_fadd_w(_sum);
#endif // __mips_msa

        sum = 1.f / sum;
        _sum = (v4f32)__msa_fill_w_f32(sum);
    }
    // div sum
    {
        float* ptr = _ptr;

        int i = 0;
        for (; i + 3 < size; i += 4)
            _p = __msa_fmul_w(_p, _sum);
            __msa_st_w((v4i32)_p, ptr, 0);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            *ptr++ *= sum;
        }
    }
}

static void softmax_pack4(float* _ptr, int elemcount, size_t stride, int size1, float* _maxptr, float* _sumptr)
{
    // reduce max
    for (int i = 0; i < elemcount; i++)
    {
        const float* ptr = _ptr + i * stride;
        float* maxptr = _maxptr;

        int j = 0;
        for (; j + 3 < size1; j += 4)
        {
            v4f32 _p0 = (v4f32)__msa_ld_w(ptr, 0);
            v4f32 _p1 = (v4f32)__msa_ld_w(ptr + 4, 0);
            v4f32 _p2 = (v4f32)__msa_ld_w(ptr + 8, 0);
            v4f32 _p3 = (v4f32)__msa_ld_w(ptr + 12, 0);
            transpose4x4_ps(_p0, _p1, _p2, _p3);
            v4f32 _max01 = __msa_fmax_w(_p0, _p1);
            v4f32 _max23 = __msa_fmax_w(_p2, _p3);
            v4f32 _max0123 = __msa_fmax_w(_max01, _max23);
            _max = __msa_fmax_w(_max, _max0123);
            __msa_st_w((v4i32)_max, maxptr, 0);
            ptr += 16;
            maxptr += 4;
        }
        for (; j < size1; j++)
        {
            v4f32 _p = (v4f32)__msa_ld_w(ptr, 0);
            *maxptr = std::max(*maxptr, __msa_reduce_fmax_w(_p));
            ptr += 4;
            maxptr++;
        }
    }

    // reduce exp(x - max)
    for (int i = 0; i < elemcount; i++)
    {
        float* ptr = _ptr + i * stride;
        const float* maxptr = _maxptr;
        float* sumptr = _sumptr;
        int j = 0;
        for (; j + 3 < size1; j += 4)
        {
            v4f32 _p0 = (v4f32)__msa_ld_w(ptr, 0);
            v4f32 _p1 = (v4f32)__msa_ld_w(ptr + 4, 0);
            v4f32 _p2 = (v4f32)__msa_ld_w(ptr + 8, 0);
            v4f32 _p3 = (v4f32)__msa_ld_w(ptr + 12, 0);
            _p0 = exp_ps(__msa_fsub_w(_p0, (v4f32)__msa_fill_w_f32(maxptr[0])));
            _p1 = exp_ps(__msa_fsub_w(_p1, (v4f32)__msa_fill_w_f32(maxptr[1])));
            _p2 = exp_ps(__msa_fsub_w(_p2, (v4f32)__msa_fill_w_f32(maxptr[2])));
            _p3 = exp_ps(__msa_fsub_w(_p3, (v4f32)__msa_fill_w_f32(maxptr[3])));
            __msa_st_w((v4i32)_p0, ptr, 0);
            __msa_st_w((v4i32)_p1, ptr + 4, 0);
            __msa_st_w((v4i32)_p2, ptr + 8, 0);
            __msa_st_w((v4i32)_p3, ptr + 12, 0);
            transpose4x4_ps(_p0, _p1, _p2, _p3);
            v4f32 _sum01 = __msa_fadd_w(_p0, _p1);
            v4f32 _sum23 = __msa_fadd_w(_p2, _p3);
            v4f32 _sum0123 = __msa_fadd_w(_sum01, _sum23);
            v4f32 _sum = (v4f32)__msa_ld_w(sumptr, 0);
            _sum = __msa_fadd_w(_sum, _sum0123);
            __msa_st_w((v4i32)_sum, sumptr, 0);
            ptr += 16;
            maxptr += 4;
            sumptr += 4;
        }
        for (; j < size1; j++)
        {
            v4f32 _p = (v4f32)__msa_ld_w(ptr, 0);
            v4f32 _max = (v4f32)__msa_fill_w_f32(*maxptr);
            __msa_st_w((v4i32)_p, ptr, 0);
            *sumptr += __msa_reduce_fadd_w(_p);
            ptr += 4;
            maxptr++;
            sumptr++;
        }
    }

    {
        float* sumptr = _sumptr;
        int j = 0;
        for (; j + 3 < size1; j += 4)
        {
            v4f32 _sum = (v4f32)__msa_ld_w(sumptr, 0);
            v4f32 _one = (v4f32)__msa_fill_w_f32(1.f);
            _sum = __msa_fdiv_w(_one, _sum);
            __msa_st_w((v4i32)_sum, sumptr, 0);
            sumptr += 4;
        }
        for (; j < size1; j++)
        {
            *sumptr = 1.f / *sumptr;
            sumptr++;
        }
    }
    // div sum
    for (int i = 0; i < elemcount; i++)
    {
        float* ptr = _ptr + i * stride;
        const float* sumptr = _sumptr;

        int j = 0;
        for (; j + 3 < size1; j += 4)
        {
            v4f32 _p0 = (v4f32)__msa_ld_w(ptr, 0);
            v4f32 _p1 = (v4f32)__msa_ld_w(ptr + 4, 0);
            v4f32 _p2 = (v4f32)__msa_ld_w(ptr + 8, 0);
            v4f32 _p3 = (v4f32)__msa_ld_w(ptr + 12, 0);
            _p0 = __msa_fmul_w(_p0, (v4f32)__msa_fill_w_f32(sumptr[0]));
            _p1 = __msa_fmul_w(_p1, (v4f32)__msa_fill_w_f32(sumptr[1]));
            _p2 = __msa_fmul_w(_p2, (v4f32)__msa_fill_w_f32(sumptr[2]));
            _p3 = __msa_fmul_w(_p3, (v4f32)__msa_fill_w_f32(sumptr[3]));
            __msa_st_w((v4i32)_p0, ptr, 0);
            __msa_st_w((v4i32)_p1, ptr + 4, 0);
            __msa_st_w((v4i32)_p2, ptr + 8, 0);
            __msa_st_w((v4i32)_p3, ptr + 12, 0);
            ptr += 16;
            sumptr += 4;
        }
        for (; j < size1; j++)
        {
            v4f32 _p = (v4f32)__msa_ld_w(ptr, 0);
            v4f32 _sum = (v4f32)__msa_fill_w_f32(*sumptr);
            _p = __msa_fmul_w(_p, _sum);
            ptr += 4;
            sumptr++;
        }
    }
}

static void softmax(float* _ptr, int elemcount, int elempack, size_t stride, int size1, float* _maxptr, float* _sumptr)
{
    // init max
    {
        float* maxptr = _maxptr;

        int j = 0;
#if __mips_msa
        v4f32 _negmax = (v4f32)__msa_fill_w_f32(-FLT_MAX);
        for (; j + 3 < size1; j += 4)
        {
            __msa_st_w((v4i32)_negmax, maxptr, 0);
            maxptr += 4;
        }
#endif // __mips_msa
        for (; j < size1; j++)
        {
            *maxptr++ = -FLT_MAX;
        }
    }

    // init sum
    {
        float* sumptr = _sumptr;

        int j = 0;
#if __mips_msa
        v4f32 _zero = (v4f32)__msa_fill_w_f32(0.f);
        for (; j + 3 < size1; j += 4)
        {
            __msa_st_w((v4i32)_zero, sumptr, 0);
            sumptr += 4;
        }
#endif // __mips_msa
        for (; j < size1; j++)
        {
            *sumptr++ = 0.f;
        }
    }

#if __mips_msa
    if (elempack == 4)
    {
        softmax_pack4(_ptr, elemcount, stride, size1, _maxptr, _sumptr);
    }
#endif // __mips_msa
    if (elempack == 1)
    {
        softmax_pack1(_ptr, elemcount, stride, size1, _maxptr, _sumptr);
    }
}

int Swish_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __mips_msa
        v4f32 _one = (v4f32)__msa_fill_w_f32(1.f);
        v8i16 _zero = __msa_fill_h(0);
        for (; i + 7 < size; i += 8)
        {
            v8i16 _p01 = __msa_ld_h(ptr, 0);
            v4f32 _p0 = (v4f32)__msa_ilvr_h(_p01, _zero);
            v4f32 _p1 = (v4f32)__msa_ilvl_h(_p01, _zero);
            _p0 = __msa_fdiv_w(_p0, __msa_fadd_w(_one, exp_ps((v4f32)__msa_bnegi_w((v4u32)_p0, 31))));
            _p1 = __msa_fdiv_w(_p1, __msa_fadd_w(_one, exp_ps((v4f32)__msa_bnegi_w((v4u32)_p1, 31))));
            __msa_st_w(float2bfloat_msa(_p0, _p1), ptr, 0);
            ptr += 8;
        }
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = bfloat2float_msa(ptr);
            _p = __msa_fdiv_w(_p, __msa_fadd_w(_one, exp_ps((v4f32)__msa_bnegi_w((v4u32)_p, 31))));
            *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            v = v / (1.f + expf(-v));
            *ptr = float32_to_bfloat16(v);
            ptr++;
        }
    }

    return 0;
}

int TanH_mips::forward_inplace_bf16s(Mat& bottom_top_blob, const Option& opt) const
{
    int w = bottom_top_blob.w;
    int h = bottom_top_blob.h;
    int d = bottom_top_blob.d;
    int channels = bottom_top_blob.c;
    int elempack = bottom_top_blob.elempack;
    int size = w * h * d * elempack;

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int q = 0; q < channels; q++)
    {
        unsigned short* ptr = bottom_top_blob.channel(q);

        int i = 0;
#if __mips_msa
        for (; i + 3 < size; i += 4)
        {
            v4f32 _p = bfloat2float_msa(ptr);
            _p = tanh_ps(_p);
            *(int64_t*)ptr = __msa_copy_s_d((v2i64)float2bfloat_msa(_p), 0);
            ptr += 4;
        }
#endif // __mips_msa
        for (; i < size; i++)
        {
            float v = bfloat16_to_float32(*ptr);
            v = tanhf(v);
            *ptr = float32_to_bfloat16(v);
            ptr++;
        }
    }

    return 0;
}

Status platformCreatePrivateDir(const fs::path& path) {
  // Create the directory with no group/other permissions to avoid a window
  // where it is accessible by other users.
  if (::mkdir(path.c_str(), S_IRWXU) != 0) {
    return Status::failure("Failed to create private directory: " +
                           path.string());
  }

  // mkdir is affected by umask; ensure the owner retains full rwx. This does
  // not widen access for group/other because those bits are not set.
  if (::chmod(path.c_str(), S_IRWXU) != 0) {
    ::rmdir(path.c_str());
    return Status::failure("Failed to set private directory permissions: " +
                           path.string());
  }

  return Status::success();
}

TEST_F(FileOpsTests, test_create_private_dir) {
  const auto dir_path = fs::temp_directory_path() /
                        fs::unique_path("osquery.private-dir-test.%%%%.%%%%");
  auto const cleanup =
      scope_guard::create([&dir_path]() { fs::remove_all(dir_path); });

  // Should create successfully and produce a real directory
  auto s = platformCreatePrivateDir(dir_path);
  ASSERT_TRUE(s.ok()) << s.getMessage();
  EXPECT_TRUE(fs::is_directory(dir_path));

  // On POSIX, verify the mode is exactly 0700 (owner rwx, no group/other bits)
#ifdef OSQUERY_POSIX
  {
    struct stat sb;
    ASSERT_EQ(0, ::stat(dir_path.c_str(), &sb));
    EXPECT_EQ(static_cast<mode_t>(S_IRWXU), sb.st_mode & 0777);
  }
#endif

#ifdef WIN32
  {
    // Retrieve the directory's DACL
    auto wpath = dir_path.wstring();
    PACL dacl = nullptr;
    PSECURITY_DESCRIPTOR sd = nullptr;
    ASSERT_EQ(static_cast<DWORD>(ERROR_SUCCESS),
              ::GetNamedSecurityInfoW(wpath.c_str(),
                                      SE_FILE_OBJECT,
                                      DACL_SECURITY_INFORMATION,
                                      nullptr,
                                      nullptr,
                                      &dacl,
                                      nullptr,
                                      &sd));
    auto sd_guard = scope_guard::create([&sd] { ::LocalFree(sd); });

    // Verify we got valid security descriptor and DACL
    ASSERT_TRUE(sd != nullptr);
    ASSERT_TRUE(dacl != nullptr);

    // The DACL must be protected so no ACEs are inherited from the parent
    // temp directory and accidentally widen access.
    SECURITY_DESCRIPTOR_CONTROL ctrl{};
    DWORD revision = 0;
    ASSERT_TRUE(::GetSecurityDescriptorControl(sd, &ctrl, &revision));
    EXPECT_TRUE(ctrl & SE_DACL_PROTECTED);

    // The Everyone (World) SID must have zero effective rights.
    {
      unsigned long sid_size = SECURITY_MAX_SID_SIZE;
      std::vector<char> sid_buf(sid_size);
      PSID sid = reinterpret_cast<PSID>(sid_buf.data());
      ASSERT_TRUE(::CreateWellKnownSid(WinWorldSid, nullptr, sid, &sid_size));
      TRUSTEE_W trustee{};
      ::BuildTrusteeWithSidW(&trustee, sid);
      ACCESS_MASK access = 0;
      ASSERT_EQ(static_cast<DWORD>(ERROR_SUCCESS),
                ::GetEffectiveRightsFromAclW(dacl, &trustee, &access));
      EXPECT_EQ(0u, access);
    }

    // The Authenticated Users group must also have zero effective rights.
    {
      unsigned long sid_size = SECURITY_MAX_SID_SIZE;
      std::vector<char> sid_buf(sid_size);
      PSID sid = reinterpret_cast<PSID>(sid_buf.data());
      ASSERT_TRUE(::CreateWellKnownSid(
          WinAuthenticatedUserSid, nullptr, sid, &sid_size));
      TRUSTEE_W trustee{};
      ::BuildTrusteeWithSidW(&trustee, sid);
      ACCESS_MASK access = 0;
      ASSERT_EQ(static_cast<DWORD>(ERROR_SUCCESS),
                ::GetEffectiveRightsFromAclW(dacl, &trustee, &access));
      EXPECT_EQ(0u, access);
    }
  }
#endif

  // Should fail when the directory already exists
  s = platformCreatePrivateDir(dir_path);
  EXPECT_FALSE(s.ok());
}

Status platformCreatePrivateDir(const fs::path& path) {
  // Build a security descriptor that grants full access only to the creating
  // user (Creator Owner) and protects the DACL from inheriting ACEs from the
  // parent directory.
  // "D:P(A;OICI;FA;;;CO)" = protected DACL; allow file-all-access to Creator
  // Owner, with Object Inherit + Container Inherit so that files and
  // subdirectories created inside also receive owner-only permissions.
  PSECURITY_DESCRIPTOR sd = nullptr;
  if (!::ConvertStringSecurityDescriptorToSecurityDescriptorW(
          L"D:P(A;OICI;FA;;;CO)", SDDL_REVISION_1, &sd, nullptr)) {
    return Status::failure("Failed to create security descriptor");
  }
  auto sd_guard = scope_guard::create([&sd] { ::LocalFree(sd); });

  SECURITY_ATTRIBUTES sa;
  sa.nLength = sizeof(sa);
  sa.lpSecurityDescriptor = sd;
  sa.bInheritHandle = FALSE;

  auto wpath = path.wstring();
  if (!::CreateDirectoryW(wpath.c_str(), &sa)) {
    return Status::failure("Failed to create private directory: " +
                           path.string());
  }

  // Retrieve the DACL we just created and mark it as protected (this seems to
  // be necessary to allow deleting the directory when we are finished)
  PACL dacl = nullptr;
  PSECURITY_DESCRIPTOR current_sd = nullptr;
  if (::GetNamedSecurityInfoW(const_cast<LPWSTR>(wpath.c_str()),
                              SE_FILE_OBJECT,
                              DACL_SECURITY_INFORMATION,
                              nullptr,
                              nullptr,
                              &dacl,
                              nullptr,
                              &current_sd) != ERROR_SUCCESS) {
    ::RemoveDirectoryW(wpath.c_str());
    return Status::failure("Failed to get directory DACL");
  }
  auto current_sd_guard =
      scope_guard::create([&current_sd] { ::LocalFree(current_sd); });

  // Reapply the DACL with the protected flag
  if (::SetNamedSecurityInfoW(
          const_cast<LPWSTR>(wpath.c_str()),
          SE_FILE_OBJECT,
          DACL_SECURITY_INFORMATION | PROTECTED_DACL_SECURITY_INFORMATION,
          nullptr,
          nullptr,
          dacl,
          nullptr) != ERROR_SUCCESS) {
    ::RemoveDirectoryW(wpath.c_str());
    return Status::failure("Failed to protect directory DACL");
  }

  return Status::success();
}

TEST_F(ClampPebReadLengthTest, buffer_larger_than_ushort_max_unchanged) {
  // dest_size > USHORT max — peb_length always fits, no clamping needed.
  EXPECT_EQ(static_cast<SIZE_T>(65535),
            clampPebReadLength(65535, static_cast<SIZE_T>(100000)));
}

SIZE_T clampPebReadLength(USHORT peb_length, SIZE_T dest_size) {
  return (static_cast<SIZE_T>(peb_length) > dest_size)
             ? dest_size
             : static_cast<SIZE_T>(peb_length);
}

TEST_F(SQLTests, select_from_multiple_constraints) {
  auto tables = RegistryFactory::get().registry("table");
  tables->add("test", std::make_shared<TestTablePlugin>());

  // No constraints should return all rows
  {
    ConstraintMap constraints;
    EXPECT_EQ(constraints.size(), 0U);

    auto results = SQL::selectFrom({}, "test", std::move(constraints));
    EXPECT_EQ(results.size(), 3U);
  }

  // Single constraint on test_int should return only matching rows
  {
    ConstraintMap constraints;
    constraints["test_int"].add(Constraint(EQUALS, "1"));
    EXPECT_EQ(constraints.size(), 1U);

    auto results = SQL::selectFrom({}, "test", std::move(constraints));
    EXPECT_EQ(results.size(), 2U);
    EXPECT_EQ(results[0]["test_int"], "1");
    EXPECT_EQ(results[0]["test_text"], "0");
    EXPECT_EQ(results[1]["test_int"], "1");
    EXPECT_EQ(results[1]["test_text"], "2");
  }

  // Multiple constraints should return only matching rows
  {
    ConstraintMap constraints;
    constraints["test_int"].add(Constraint(EQUALS, "1"));
    constraints["test_text"].add(Constraint(EQUALS, "2"));
    EXPECT_EQ(constraints.size(), 2U);

    auto results = SQL::selectFrom({}, "test", std::move(constraints));
    EXPECT_EQ(results.size(), 1U);
    EXPECT_EQ(results[0]["test_int"], "1");
    EXPECT_EQ(results[0]["test_text"], "2");
  }

  // Non-matching constraints should return no rows
  {
    ConstraintMap constraints;
    constraints["test_int"].add(Constraint(EQUALS, "2"));
    constraints["test_text"].add(Constraint(EQUALS, "3"));
    EXPECT_EQ(constraints.size(), 2U);

    auto results = SQL::selectFrom({}, "test", std::move(constraints));
    EXPECT_EQ(results.size(), 0U);
  }

  // Conflicting constraints should return no rows (check AND)
  {
    ConstraintMap constraints;
    constraints["test_int"].add(Constraint(EQUALS, "1"));
    constraints["test_int"].add(Constraint(EQUALS, "0"));
    EXPECT_EQ(constraints.size(), 1U);
    auto results = SQL::selectFrom({}, "test", std::move(constraints));
    EXPECT_EQ(results.size(), 0U);
  }
}

void SetUp() override {
    temp_dir_ = fs::temp_directory_path() /
                fs::unique_path("osquery_npm_test_%%%%-%%%%-%%%%-%%%%");
    fs::create_directories(temp_dir_);
  }

void TearDown() override {
    if (fs::exists(temp_dir_)) {
      fs::remove_all(temp_dir_);
    }
  }

void createScopedPackage(const std::string& scope,
                           const std::string& package_name,
                           const std::string& version) {
    auto package_path =
        temp_dir_ / "node_modules" / scope / package_name / "package.json";
    std::string package_json = R"({
  "name": ")" + scope + "/" + package_name +
                               R"(",
  "version": ")" + version + R"(",
  "description": "Test scoped package",
  "author": "Test Author",
  "license": "MIT"
})";
    createPackageJson(package_path, package_json);
  }

void createRegularPackage(const std::string& package_name,
                            const std::string& version) {
    auto package_path =
        temp_dir_ / "node_modules" / package_name / "package.json";
    std::string package_json = R"({
  "name": ")" + package_name + R"(",
  "version": ")" + version + R"(",
  "description": "Test regular package",
  "author": "Test Author",
  "license": "MIT"
})";
    createPackageJson(package_path, package_json);
  }

TEST_F(NpmPackagesUnitTest, test_scoped_package_detection) {
  GLOGLogger logger;

  // Create mock scoped packages
  createScopedPackage("@types", "node", "18.0.0");
  createScopedPackage("@angular", "core", "15.0.0");

  // Create mock regular packages
  createRegularPackage("express", "4.18.0");
  createRegularPackage("lodash", "4.17.21");

  // Create mock nested regular package that should NOT be found
  // because nested pattern only matches scoped packages with @ prefix
  createScopedPackage("nested", "package", "3.2.1");

  QueryData results;
  tables::genNodeSiteDirectories(temp_dir_.string(), results, logger);

  // We should find only 4 packages (2 scoped + 2 regular)
  // The nested/package should NOT be found
  EXPECT_EQ(results.size(), 4);

  // Check that we found both scoped and regular packages
  bool found_scoped_types_node = false;
  bool found_scoped_angular_core = false;
  bool found_regular_express = false;
  bool found_regular_lodash = false;

  for (const auto& row : results) {
    auto name = row.at("name");
    auto version = row.at("version");
    auto path = row.at("path");

    // Verify scoped packages
    if (name == "@types/node") {
      found_scoped_types_node = true;
      EXPECT_EQ(version, "18.0.0");
      // Check for platform-agnostic path containing package structure
      fs::path expected_path =
          fs::path("node_modules") / "@types" / "node" / "package.json";
      EXPECT_TRUE(path.find(expected_path.string()) != std::string::npos);
    } else if (name == "@angular/core") {
      found_scoped_angular_core = true;
      EXPECT_EQ(version, "15.0.0");
      fs::path expected_path =
          fs::path("node_modules") / "@angular" / "core" / "package.json";
      EXPECT_TRUE(path.find(expected_path.string()) != std::string::npos);
    }
    // Verify regular packages
    else if (name == "express") {
      found_regular_express = true;
      EXPECT_EQ(version, "4.18.0");
      fs::path expected_path =
          fs::path("node_modules") / "express" / "package.json";
      EXPECT_TRUE(path.find(expected_path.string()) != std::string::npos);
    } else if (name == "lodash") {
      found_regular_lodash = true;
      EXPECT_EQ(version, "4.17.21");
      fs::path expected_path =
          fs::path("node_modules") / "lodash" / "package.json";
      EXPECT_TRUE(path.find(expected_path.string()) != std::string::npos);
    } else {
      FAIL() << "Unexpected package found: " << name;
    }

    // Verify common fields based on package type
    if (name.find('@') == 0) {
      EXPECT_EQ(row.at("description"), "Test scoped package");
    } else {
      EXPECT_EQ(row.at("description"), "Test regular package");
    }

    // Ensure nested/package is NOT found (it should not match the patterns)
    EXPECT_NE(name, "nested/package")
        << "nested/package should not be found by the search patterns";
    EXPECT_EQ(row.at("author"), "Test Author");
    EXPECT_EQ(row.at("license"), "MIT");
    EXPECT_EQ(row.at("directory"), temp_dir_.string());
  }

  // Ensure we found all expected packages
  EXPECT_TRUE(found_scoped_types_node)
      << "Did not find @types/node scoped package";
  EXPECT_TRUE(found_scoped_angular_core)
      << "Did not find @angular/core scoped package";
  EXPECT_TRUE(found_regular_express) << "Did not find express regular package";
  EXPECT_TRUE(found_regular_lodash) << "Did not find lodash regular package";
}

FileData extractSpecificFileFromArchive(const std::string& archive_file_path,
                                        const std::string& target_file_path) {
  struct archive* archive;
  struct archive_entry* entry;
  int result;
  FileData file_data;

  archive = archive_read_new();
  archive_read_support_format_all(archive);
  archive_read_support_filter_all(archive);

  auto archive_guard = osquery::scope_guard::create([&archive]() {
    if (archive != nullptr) {
      int free_result = archive_read_free(archive);
      if (free_result != ARCHIVE_OK) {
        VLOG(1) << "Failed to close zip file: " << archive_error_string(archive)
                << std::endl;
      }
    }
  });

  result = archive_read_open_filename(
      archive, archive_file_path.c_str(), 10240); // 10KB buffer
  if (result != ARCHIVE_OK) {
    VLOG(1) << "Failed to open zip file: " << archive_error_string(archive)
            << std::endl;

    return file_data;
  }

  while (archive_read_next_header(archive, &entry) == ARCHIVE_OK) {
    // Get the current file from the archive entry
    const char* currentFile = archive_entry_pathname(entry);
    boost::filesystem::path currentPath(currentFile);
    boost::filesystem::path targetPath(target_file_path);

    if (currentPath == targetPath) {
      // Found the target file in the archive
      file_data.path = currentFile;

      const void* buffer;
      size_t size;
      int64_t offset;

      while (archive_read_data_block(archive, &buffer, &size, &offset) ==
             ARCHIVE_OK) {
        file_data.content.insert(file_data.content.end(),
                                 (const char*)buffer,
                                 (const char*)buffer + size);
      }

      if (archive_errno(archive) != 0) {
        VLOG(1) << "Error reading data block: " << archive_error_string(archive)
                << std::endl;
      }

      break;
    }
    // Move to the next entry
    archive_read_data_skip(archive);
  }

  return file_data;
}

std::string getContentFromTag(const std::string& xml,
                              const std::string& tag_name) {
  std::regex tagRegex("<" + tag_name + "[\\s\\S]*?>([\\s\\S]*?)<\\/" +
                      tag_name + ">");
  std::smatch match;

  if (std::regex_search(xml, match, tagRegex)) {
    // match[0] is the entire tag with contents <TagName>contents</TagName>
    // match[1] is the contents of the tag
    return match[1];
  }
  return "";
}

PluginAttributes parsePluginXml(const std::string& xml_content) {
  PluginAttributes attributes;

  // Example
  // <name>Osquery Plugin</name>
  // Uses Title Case
  auto name_pos = xml_content.find("<name>");
  if (name_pos != std::string::npos) {
    attributes.name = getContentFromTag(xml_content, "name");
  }

  // Example
  // <vendor>Osquery</vendor>
  // <vendor
  //     url="https://www.osquery.io"
  //     email="help@osquery.io">
  //   Osquery
  // </vendor>
  // url (optional)
  // email (optional)
  auto vendor_pos = xml_content.find("<vendor");
  if (vendor_pos != std::string::npos) {
    attributes.vendor = getContentFromTag(xml_content, "vendor");
  }

  // Example
  // <version>1.3.18</version>
  // Uses JetBrains Marketplace Semantic Versioning
  // https://plugins.jetbrains.com/docs/marketplace/semver.html
  auto version_pos = xml_content.find("<version>");
  if (version_pos != std::string::npos) {
    attributes.version = getContentFromTag(xml_content, "version");
  }

  return attributes;
}

FileData getPluginXMLFile(const std::string& jar_file_path) {
  // The plugin.xml configuration file contains all the information about the
  // plugin, which is displayed in the plugins' settings dialog
  // https://plugins.jetbrains.com/docs/intellij/plugin-configuration-file.html
  std::string target_file_path;
  if (isPlatform(PlatformType::TYPE_WINDOWS)) {
    target_file_path = "META-INF\\plugin.xml";
  } else {
    target_file_path = "META-INF/plugin.xml";
  }
  FileData file_data =
      extractSpecificFileFromArchive(jar_file_path, target_file_path);

  return file_data;
}

std::unique_ptr<PluginAttributes> attributesFromJar(
    const std::string& jar_file_path) {
  auto file_data = getPluginXMLFile(jar_file_path);

  if (file_data.content.empty()) {
    return nullptr;
  }
  std::string xml_content(file_data.content.begin(), file_data.content.end());

  return std::make_unique<PluginAttributes>(parsePluginXml(xml_content));
}

bool fileNameIsLikeVersionedLibraryName(const std::string& name) {
  size_t i = name.rfind('-');
  if (i == std::string::npos) {
    return false;
  }
  if (i + 1 < name.length()) {
    char c = name[i + 1];
    if (std::isdigit(c))
      return true;
    if ((c == 'm' || c == 'M') && i + 2 < name.length() &&
        std::isdigit(name[i + 2]))
      return true;
  }
  return false;
}

void putMoreLikelyPluginJarsFirst(
    const std::string& plugin_dir_name,
    std::vector<std::string>& files_in_lib_under_plugin_dir) {
  std::sort(
      files_in_lib_under_plugin_dir.begin(),
      files_in_lib_under_plugin_dir.end(),
      [&plugin_dir_name](const std::string& o1, const std::string& o2) {
        std::string o1_name = boost::filesystem::path(o1).filename().string();
        std::string o2_name = boost::filesystem::path(o2).filename().string();
        bool o1_starts_with_resources = o1_name.rfind("resources", 0) == 0;
        bool o2_starts_with_resources = o2_name.rfind("resources", 0) == 0;
        if (o2_starts_with_resources != o1_starts_with_resources) {
          // Files with "resources" in name go last
          return !o1_starts_with_resources && o2_starts_with_resources;
        }

        bool o1_is_versioned = fileNameIsLikeVersionedLibraryName(o1_name);
        bool o2_is_versioned = fileNameIsLikeVersionedLibraryName(o2_name);
        if (o2_is_versioned != o1_is_versioned) {
          // Files with digits in suffix go last
          return !o1_is_versioned && o2_is_versioned;
        }

        bool o1_starts_with_needed_name =
            boost::algorithm::istarts_with(o1_name, plugin_dir_name);
        bool o2_starts_with_needed_name =
            boost::algorithm::istarts_with(o2_name, plugin_dir_name);
        if (o2_starts_with_needed_name != o1_starts_with_needed_name) {
          // Files starting with plugin_dir_name go first
          return o1_starts_with_needed_name && !o2_starts_with_needed_name;
        }

        bool o2_ends_with_idea =
            boost::algorithm::iends_with(o2_name, "-idea.jar");
        bool o1_ends_with_idea =
            boost::algorithm::iends_with(o1_name, "-idea.jar");
        if (o2_ends_with_idea != o1_ends_with_idea) {
          // Files ending with -idea.jar go last
          return !o1_ends_with_idea && o2_ends_with_idea;
        }

        bool o1_is_db_plugin = o1_name == "database-plugin.jar";
        bool o2_is_db_plugin = o2_name == "database-plugin.jar";
        if (o2_is_db_plugin != o1_is_db_plugin) {
          // Files named database-plugin.jar come last
          return !o1_is_db_plugin && o2_is_db_plugin;
        }

        return static_cast<int>(o1_name.length()) <
               static_cast<int>(o2_name.length());
      });
}

void genPlugins(QueryData& results,
                const ProductPathMap paths_to_traverse,
                const std::string& user_path_prefix,
                const std::int64_t& uid) {
  for (const auto& [product_type, path] : paths_to_traverse) {
    std::string full_path;
    if (isPlatform(PlatformType::TYPE_WINDOWS)) {
      full_path = user_path_prefix + "\\" + path;
    } else {
      full_path = user_path_prefix + "/" + path;
    }

    std::vector<std::string> plugin_paths;
    resolveFilePattern(full_path, plugin_paths);
    for (const auto& plugin_path : plugin_paths) {
      // "Plugin Without Dependencies"
      // The plugin is a .jar file
      std::vector<std::string> plugin_files;
      listFilesInDirectory(plugin_path, plugin_files, false);
      for (const auto& plugin_jar_file : plugin_files) {
        std::unique_ptr<PluginAttributes> attributes =
            attributesFromJar(plugin_jar_file);
        if (!attributes) {
          // Skip this plugin, as we cannot find the plugin.xml file.
          // This should not happen. Even in the case of Kotlin-based plugins
          // that use build.gradle.kts, they will still contain a plugin.xml
          // file.
          VLOG(1) << "Failed to find plugin.xml from: " << plugin_jar_file;
          continue;
        }

        Row row;
        row["product_type"] = SQL_TEXT(getProductName(product_type));
        row["uid"] = BIGINT(uid);
        row["path"] = SQL_TEXT(plugin_jar_file);
        row["name"] = SQL_TEXT(attributes->name);
        row["vendor"] = SQL_TEXT(attributes->vendor);
        row["version"] = SQL_TEXT(attributes->version);
        results.push_back(row);
      }

      // "Plugin With Dependencies"
      // The plugin is a folder
      // The plugin .jar file is placed in the /lib within this folder, together
      // with all required bundled libraries.
      std::vector<std::string> plugins_directories;
      listDirectoriesInDirectory(plugin_path, plugins_directories, false);
      for (const auto& plugin_directory : plugins_directories) {
        // plugin_directory Example:
        // /<absolute
        // path>/JetBrains/IntelliJIdea2024.3/plugins/aws-toolkit-jetbrains-standalone

        std::string plugin_lib_directory;
        if (isPlatform(PlatformType::TYPE_WINDOWS)) {
          plugin_lib_directory = plugin_directory + "\\lib";
        } else {
          plugin_lib_directory = plugin_directory + "/lib";
        }
        std::vector<std::string> plugin_lib_files;
        listFilesInDirectory(plugin_lib_directory, plugin_lib_files, false);
        // plugin_lib_files
        // An array of full string paths to files
        // Example:
        // [
        //    /<absolute
        //    path>/JetBrains/IntelliJIdea2024.3/plugins/aws-toolkit-jetbrains-standalone/lib/jetbrains-ultimate.jar
        //    ...
        // ]
        std::string plugin_dir_name;
        if (isPlatform(PlatformType::TYPE_WINDOWS)) {
          plugin_dir_name =
              plugin_directory.substr(plugin_directory.find_last_of("\\") + 1);
        } else {
          plugin_dir_name =
              plugin_directory.substr(plugin_directory.find_last_of("/\\") + 1);
        }
        // plugin_dir_name
        // The name of the plugin directory under lib
        // Example:
        // aws-toolkit-jetbrains-standalone
        putMoreLikelyPluginJarsFirst(plugin_dir_name, plugin_lib_files);

        std::unique_ptr<PluginAttributes> attributes;
        for (const auto& jar_file : plugin_lib_files) {
          // Iterate through the jar files in the plugin lib directory
          // and try to find the plugin.xml file
          attributes = attributesFromJar(jar_file);
          if (attributes) {
            break;
          }
        }
        if (!attributes) {
          // Skip this plugin, as we cannot find the plugin.xml file in any of
          // the jar files. This should not happen. Even in the case of
          // Kotlin-based plugins that use build.gradle.kts, they will still
          // contain a plugin.xml file.
          VLOG(1) << "Failed to find plugin.xml from: " << plugin_directory;
          continue;
        }

        Row row;
        row["product_type"] = SQL_TEXT(getProductName(product_type));
        row["uid"] = BIGINT(uid);
        row["path"] = SQL_TEXT(plugin_directory);
        row["name"] = SQL_TEXT(attributes->name);
        row["vendor"] = SQL_TEXT(attributes->vendor);
        row["version"] = SQL_TEXT(attributes->version);
        results.push_back(row);
      }
    }
  }
}

QueryData genJetBrainsPlugins(QueryContext& context) {
  QueryData results;

  auto users = usersFromContext(context);
  for (const auto& user : users) {
    if (user.count("uid") == 0 || user.count("directory") == 0) {
      continue;
    }

    const auto& uid_as_string = user.at("uid");
    auto uid_as_big_int = tryTo<int64_t>(uid_as_string, 10);
    if (uid_as_big_int.isError()) {
      LOG(ERROR) << "Invalid uid field returned: " << uid_as_string;
      continue;
    }
    const auto& user_path_prefix = user.at("directory");

    ProductPathMap paths_to_traverse;
    if (isPlatform(PlatformType::TYPE_WINDOWS)) {
      paths_to_traverse = kWindowsPathList;
    } else if (isPlatform(PlatformType::TYPE_OSX)) {
      paths_to_traverse = kMacOsPathList;
    } else {
      paths_to_traverse = kLinuxPathList;
    }

    genPlugins(
        results, paths_to_traverse, user_path_prefix, uid_as_big_int.get());
  }

  return results;
}

TEST_F(JetbrainsPluginsTest, test_fileNameIsLikeVersionedLibraryName) {
  // Versioned filenames
  ASSERT_TRUE(fileNameIsLikeVersionedLibraryName("kotlin-stdlib-1.5.0.jar"));
  ASSERT_TRUE(fileNameIsLikeVersionedLibraryName("kotlin-stdlib-m5.jar"));
  ASSERT_TRUE(fileNameIsLikeVersionedLibraryName("kotlin-stdlib-M5.jar"));
  ASSERT_TRUE(fileNameIsLikeVersionedLibraryName("jsr305-3.0.2.jar"));

  // non-versioned filenames
  ASSERT_FALSE(
      fileNameIsLikeVersionedLibraryName("kotlin-stdlib-1.5.0-sources.jar"));
  ASSERT_FALSE(fileNameIsLikeVersionedLibraryName("kotlin-stdlib.jar"));
  ASSERT_FALSE(fileNameIsLikeVersionedLibraryName("kotlin-stdlib-sources.jar"));
  ASSERT_FALSE(fileNameIsLikeVersionedLibraryName("banana-plugin.jar"));
  ASSERT_FALSE(fileNameIsLikeVersionedLibraryName("resources.jar"));
}

TEST_F(JetbrainsPluginsTest, test_putMoreLikelyPluginJarsFirst) {
  std::vector<std::string> files;

  // Resources are last
  files = {"/test-plugin/lib/resources.jar",
           "/test-plugin/lib/kotlin-stdlib.jar"};
  putMoreLikelyPluginJarsFirst("banana", files);
  ASSERT_EQ(files[0], "/test-plugin/lib/kotlin-stdlib.jar");
  ASSERT_EQ(files[1], "/test-plugin/lib/resources.jar");

  // Suffix is a digit is last
  files = {"/test-plugin/lib/json-2.8.0.jar",
           "/test-plugin/lib/completion-ranking.jar",
           "/test-plugin/lib/junit-m5.jar"};
  putMoreLikelyPluginJarsFirst("banana", files);
  ASSERT_EQ(files[0], "/test-plugin/lib/completion-ranking.jar");
  ASSERT_EQ(files[1], "/test-plugin/lib/junit-m5.jar");
  ASSERT_EQ(files[2], "/test-plugin/lib/json-2.8.0.jar");

  // Plugin name match is first
  files = {"/test-plugin/lib/plugin.jar", "/test-plugin/lib/banana-stdlib.jar"};
  putMoreLikelyPluginJarsFirst("banana", files);
  ASSERT_EQ(files[0], "/test-plugin/lib/banana-stdlib.jar");
  ASSERT_EQ(files[1], "/test-plugin/lib/plugin.jar");

  // Plugins ending with -idea.jar are last
  files = {"/test-plugin/lib/banana-idea.jar",
           "/test-plugin/lib/banana-stdlib.jar"};
  putMoreLikelyPluginJarsFirst("banana", files);
  ASSERT_EQ(files[0], "/test-plugin/lib/banana-stdlib.jar");
  ASSERT_EQ(files[1], "/test-plugin/lib/banana-idea.jar");

  // Plugins named database-plugin.jar are last
  files = {"/test-plugin/lib/database-plugin.jar",
           "/test-plugin/lib/banana-stdlib-common.jar"};
  putMoreLikelyPluginJarsFirst("banana", files);
  ASSERT_EQ(files[0], "/test-plugin/lib/banana-stdlib-common.jar");
  ASSERT_EQ(files[1], "/test-plugin/lib/database-plugin.jar");

  // Shorter names first
  files = {"/test-plugin/lib/android-base-common.jar",
           "/test-plugin/lib/android.jar"};
  putMoreLikelyPluginJarsFirst("banana", files);
  ASSERT_EQ(files[0], "/test-plugin/lib/android.jar");
  ASSERT_EQ(files[1], "/test-plugin/lib/android-base-common.jar");
}

