struct AsstMapLevelKey ASSTAPI AsstGetMapLevelKey(const char* key)
    {
        if (!key) {
            return { nullptr, nullptr, nullptr, nullptr };
        }
        const auto& level_metadata = asst::Tile.find(key);
        if (!level_metadata) {
            return { nullptr, nullptr, nullptr, nullptr };
        }
        thread_local Map::LevelKey level_key;
        level_key = level_metadata->first;
        return { level_key.stageId.c_str(), level_key.code.c_str(), level_key.levelId.c_str(), level_key.name.c_str() };
    }

inline void GatherStrided(float* dst, const float* src, int64_t stride, int64_t count) {
  if (stride == 1) {
    std::memcpy(dst, src, static_cast<size_t>(count) * sizeof(float));
    return;
  }
  for (int64_t i = 0; i < count; ++i) {
    dst[i] = src[i * stride];
  }
}

inline void ScatterStrided(float* dst, int64_t stride, const float* src, int64_t count) {
  if (stride == 1) {
    std::memcpy(dst, src, static_cast<size_t>(count) * sizeof(float));
    return;
  }
  for (int64_t i = 0; i < count; ++i) {
    dst[i * stride] = src[i];
  }
}

Status EngramGate<T>::Compute(OpKernelContext* context) const {
  const Tensor* key = context->Input<Tensor>(0);
  const Tensor* query = context->Input<Tensor>(1);
  const Tensor* value = context->Input<Tensor>(2);
  const Tensor* key_norm_scale = context->Input<Tensor>(3);
  const Tensor* query_norm_scale = context->Input<Tensor>(4);

  const TensorShape& key_shape = key->Shape();
  ORT_RETURN_IF_NOT(key_shape.NumDimensions() == 4,
                    "key must have shape (batch_size, sequence_length, hc_mult, hidden_size)");
  const int64_t batch_size = key_shape[0];
  const int64_t sequence_length = key_shape[1];
  const int64_t hc_mult = key_shape[2];
  const int64_t hidden_size = key_shape[3];

  ORT_RETURN_IF_NOT(query->Shape() == key_shape, "query must have the same shape as key");
  ORT_RETURN_IF_NOT(value->Shape() == TensorShape({batch_size, sequence_length, hidden_size}),
                    "value must have shape (batch_size, sequence_length, hidden_size)");
  ORT_RETURN_IF_NOT(key_norm_scale->Shape() == TensorShape({hc_mult, hidden_size}),
                    "key_norm_scale must have shape (hc_mult, hidden_size)");
  ORT_RETURN_IF_NOT(query_norm_scale->Shape() == TensorShape({hc_mult, hidden_size}),
                    "query_norm_scale must have shape (hc_mult, hidden_size)");

  Tensor* output = context->Output(0, key_shape);
  if (key_shape.Size() == 0) {
    return Status::OK();
  }

  const T* key_data = key->Data<T>();
  const T* query_data = query->Data<T>();
  const T* value_data = value->Data<T>();
  const T* key_scale_data = key_norm_scale->Data<T>();
  const T* query_scale_data = query_norm_scale->Data<T>();
  T* output_data = output->MutableData<T>();

  const int64_t rows = batch_size * sequence_length * hc_mult;
  ThreadPool::TryParallelFor(
      // Each row makes one fused reduction pass and one output pass over hidden_size, plus a
      // handful of scalar transcendentals. Costing it as a single pass would over-partition.
      context->GetOperatorThreadPool(), narrow<ptrdiff_t>(rows),
      static_cast<double>(2 * hidden_size + 32),
      [&](ptrdiff_t begin, ptrdiff_t end) {
        for (int64_t row = begin; row < end; ++row) {
          const int64_t g = row % hc_mult;
          const int64_t token = row / hc_mult;
          const T* key_row = key_data + row * hidden_size;
          const T* query_row = query_data + row * hidden_size;
          const T* value_row = value_data + token * hidden_size;

          // Both inverse RMS factors are scalars, so they can be pulled out of the dot product and
          // applied afterwards. That folds the two reductions into one pass over key_row and
          // query_row, which is what the CUDA and WGSL kernels already do.
          const T* key_scale_row = key_scale_data + g * hidden_size;
          const T* query_scale_row = query_scale_data + g * hidden_size;
          float key_sum_sq = 0.0f;
          float query_sum_sq = 0.0f;
          float dot_numerator = 0.0f;
          for (int64_t c = 0; c < hidden_size; ++c) {
            const float key_value = static_cast<float>(key_row[c]);
            const float query_value = static_cast<float>(query_row[c]);
            key_sum_sq += key_value * key_value;
            query_sum_sq += query_value * query_value;
            dot_numerator += key_value * static_cast<float>(key_scale_row[c]) *
                             query_value * static_cast<float>(query_scale_row[c]);
          }

          const float key_inv_rms = 1.0f / std::sqrt(key_sum_sq / static_cast<float>(hidden_size) + epsilon_);
          const float query_inv_rms = 1.0f / std::sqrt(query_sum_sq / static_cast<float>(hidden_size) + epsilon_);
          const float dot =
              dot_numerator * key_inv_rms * query_inv_rms / std::sqrt(static_cast<float>(hidden_size));
          const float gate = engram_helper::SigmoidFloat(engram_helper::EngramGateArg(dot));

          T* output_row = output_data + row * hidden_size;
          for (int64_t c = 0; c < hidden_size; ++c) {
            output_row[c] = static_cast<T>(gate * static_cast<float>(value_row[c]));
          }
        }
      });

  return Status::OK();
}

NGramHashMapping<T>::NGramHashMapping(const OpKernelInfo& info) : OpKernel(info) {
  ORT_ENFORCE(info.GetAttr<int64_t>("max_ngram_size", &max_ngram_size_).IsOK(),
              "max_ngram_size attribute is required");
  ORT_ENFORCE(info.GetAttr<int64_t>("n_head_per_ngram", &n_head_per_ngram_).IsOK(),
              "n_head_per_ngram attribute is required");
  int64_t pad_id = 0;
  ORT_ENFORCE(info.GetAttr<int64_t>("pad_id", &pad_id).IsOK(), "pad_id attribute is required");
  ORT_ENFORCE(max_ngram_size_ >= 2, "max_ngram_size must be at least 2");
  ORT_ENFORCE(n_head_per_ngram_ >= 1, "n_head_per_ngram must be positive");
  ORT_ENFORCE(pad_id >= static_cast<int64_t>(std::numeric_limits<T>::min()) &&
                  pad_id <= static_cast<int64_t>(std::numeric_limits<T>::max()),
              "pad_id is out of range for the input id type");
  pad_id_ = static_cast<T>(pad_id);
}

T NGramHashMapping<T>::HistoryId(const T* past_data, int64_t b, int64_t slot, int64_t state_length) const {
  if (past_data == nullptr || slot < 0 || slot >= state_length) {
    return pad_id_;
  }
  return past_data[b * state_length + slot];
}

Status NGramHashMapping<T>::Compute(OpKernelContext* context) const {
  const Tensor* input_ids = context->Input<Tensor>(0);
  const Tensor* multipliers = context->Input<Tensor>(1);
  const Tensor* vocab_sizes = context->Input<Tensor>(2);
  const Tensor* past_ids = context->Input<Tensor>(3);

  const TensorShape& input_shape = input_ids->Shape();
  ORT_RETURN_IF_NOT(input_shape.NumDimensions() == 2, "input_ids must have rank 2");
  ORT_RETURN_IF_NOT(multipliers->Shape().NumDimensions() == 1 &&
                        multipliers->Shape()[0] == max_ngram_size_,
                    "multipliers must have shape (max_ngram_size)");
  const int64_t num_heads = (max_ngram_size_ - 1) * n_head_per_ngram_;
  ORT_RETURN_IF_NOT(vocab_sizes->Shape().NumDimensions() == 1 && vocab_sizes->Shape()[0] == num_heads,
                    "vocab_sizes must have shape ((max_ngram_size - 1) * n_head_per_ngram)");

  const int64_t batch_size = input_shape[0];
  const int64_t sequence_length = input_shape[1];
  // An n-gram window reaches this many positions before the current token.
  const int64_t state_length = max_ngram_size_ - 1;
  if (past_ids != nullptr) {
    ORT_RETURN_IF_NOT(past_ids->Shape() == TensorShape({batch_size, state_length}),
                      "past_ids must have shape (batch_size, max_ngram_size - 1)");
  }

  Tensor* output = context->Output(0, TensorShape({batch_size, sequence_length, num_heads}));
  Tensor* present_ids = context->Output(1, TensorShape({batch_size, state_length}));

  const T* input_data = input_ids->Data<T>();
  const T* multiplier_data = multipliers->Data<T>();
  const T* vocab_data = vocab_sizes->Data<T>();
  const T* past_data = past_ids == nullptr ? nullptr : past_ids->Data<T>();

  // A non-positive head vocabulary size has no meaningful modulo. Every EP guards the division to
  // avoid a device-side divide-by-zero, which turns the mistake into a constant hash id of 0 for that
  // head rather than a crash. That is a silent wrong answer, so validate it here where vocab_sizes is
  // already resident on the host and the check costs one pass over a tiny tensor.
  for (int64_t h = 0; h < num_heads; ++h) {
    ORT_RETURN_IF_NOT(vocab_data[h] > 0,
                      "vocab_sizes must be positive; entry ", h, " is ", static_cast<int64_t>(vocab_data[h]));
  }

  if (input_shape.Size() != 0) {
    T* output_data = output->MutableData<T>();
    const int64_t total = batch_size * sequence_length;
    ThreadPool::TryParallelFor(
        context->GetOperatorThreadPool(), narrow<ptrdiff_t>(total), static_cast<double>(max_ngram_size_ * n_head_per_ngram_),
        [&](ptrdiff_t begin, ptrdiff_t end) {
          for (int64_t linear = begin; linear < end; ++linear) {
            const int64_t t = linear % sequence_length;
            const int64_t b = linear / sequence_length;
            const int64_t input_base = b * sequence_length;
            const int64_t output_base = linear * num_heads;

            for (int64_t n = 2; n <= max_ngram_size_; ++n) {
              T mix = 0;
              for (int64_t k = 0; k < n; ++k) {
                const int64_t source_t = t - k;
                const T token = source_t >= 0 ? input_data[input_base + source_t]
                                              : HistoryId(past_data, b, state_length + source_t, state_length);
                const T product = engram_helper::WrappedMultiply(token, multiplier_data[k]);
                mix = k == 0 ? product : static_cast<T>(mix ^ product);
              }

              const int64_t ngram_offset = (n - 2) * n_head_per_ngram_;
              for (int64_t h = 0; h < n_head_per_ngram_; ++h) {
                const int64_t out_h = ngram_offset + h;
                // vocab_sizes was validated to be positive above, so the modulo is always well defined.
                output_data[output_base + out_h] = engram_helper::PositiveMod(mix, vocab_data[out_h]);
              }
            }
          }
        });
  }

  // present_ids is the right-aligned trailing window of (past_ids ++ input_ids), so it is well defined
  // even when this call is shorter than the window. It is written last because past_ids may share
  // its allocation, and the hash loop above still needs the original history. Within this loop the
  // aliased case is safe too: slot j writes index j and reads index j + sequence_length, so the walk
  // is strictly ahead of itself.
  if (present_ids != nullptr) {
    T* present_data = present_ids->MutableData<T>();
    for (int64_t b = 0; b < batch_size; ++b) {
      for (int64_t j = 0; j < state_length; ++j) {
        // Virtual position of slot j relative to the end of input_ids.
        const int64_t source_t = sequence_length - state_length + j;
        present_data[b * state_length + j] =
            source_t >= 0 ? input_data[b * sequence_length + source_t]
                          : HistoryId(past_data, b, state_length + source_t, state_length);
      }
    }
  }

  return Status::OK();
}

Status EngramGate<T>::ComputeInternal(OpKernelContext* context) const {
  using CudaT = typename OrtToCudaType<T>::type;
  const Tensor* key = context->Input<Tensor>(0);
  const Tensor* query = context->Input<Tensor>(1);
  const Tensor* value = context->Input<Tensor>(2);
  const Tensor* key_norm_scale = context->Input<Tensor>(3);
  const Tensor* query_norm_scale = context->Input<Tensor>(4);

  const TensorShape& key_shape = key->Shape();
  ORT_RETURN_IF_NOT(key_shape.NumDimensions() == 4,
                    "key must have shape (batch_size, sequence_length, hc_mult, hidden_size)");
  const int64_t batch_size = key_shape[0];
  const int64_t sequence_length = key_shape[1];
  const int64_t hc_mult = key_shape[2];
  const int64_t hidden_size = key_shape[3];

  ORT_RETURN_IF_NOT(query->Shape() == key_shape, "query must have the same shape as key");
  ORT_RETURN_IF_NOT(value->Shape() == TensorShape({batch_size, sequence_length, hidden_size}),
                    "value must have shape (batch_size, sequence_length, hidden_size)");
  ORT_RETURN_IF_NOT(key_norm_scale->Shape() == TensorShape({hc_mult, hidden_size}),
                    "key_norm_scale must have shape (hc_mult, hidden_size)");
  ORT_RETURN_IF_NOT(query_norm_scale->Shape() == TensorShape({hc_mult, hidden_size}),
                    "query_norm_scale must have shape (hc_mult, hidden_size)");

  Tensor* output = context->Output(0, key_shape);
  if (key_shape.Size() == 0) {
    return Status::OK();
  }

  return LaunchEngramGateKernel<CudaT>(
      Stream(context),
      reinterpret_cast<const CudaT*>(key->Data<T>()),
      reinterpret_cast<const CudaT*>(query->Data<T>()),
      reinterpret_cast<const CudaT*>(value->Data<T>()),
      reinterpret_cast<const CudaT*>(key_norm_scale->Data<T>()),
      reinterpret_cast<const CudaT*>(query_norm_scale->Data<T>()),
      reinterpret_cast<CudaT*>(output->MutableData<T>()),
      batch_size,
      sequence_length,
      hc_mult,
      hidden_size,
      epsilon_);
}

NGramHashMapping<T>::NGramHashMapping(const OpKernelInfo& info) : CudaKernel(info) {
  ORT_ENFORCE(info.GetAttr<int64_t>("max_ngram_size", &max_ngram_size_).IsOK(),
              "max_ngram_size attribute is required");
  ORT_ENFORCE(info.GetAttr<int64_t>("n_head_per_ngram", &n_head_per_ngram_).IsOK(),
              "n_head_per_ngram attribute is required");
  int64_t pad_id = 0;
  ORT_ENFORCE(info.GetAttr<int64_t>("pad_id", &pad_id).IsOK(), "pad_id attribute is required");
  ORT_ENFORCE(max_ngram_size_ >= 2, "max_ngram_size must be at least 2");
  ORT_ENFORCE(n_head_per_ngram_ >= 1, "n_head_per_ngram must be positive");
  ORT_ENFORCE(pad_id >= static_cast<int64_t>(std::numeric_limits<T>::min()) &&
                  pad_id <= static_cast<int64_t>(std::numeric_limits<T>::max()),
              "pad_id is out of range for the input id type");
  pad_id_ = static_cast<T>(pad_id);
}

Status NGramHashMapping<T>::ComputeInternal(OpKernelContext* context) const {
  const Tensor* input_ids = context->Input<Tensor>(0);
  const Tensor* multipliers = context->Input<Tensor>(1);
  const Tensor* vocab_sizes = context->Input<Tensor>(2);
  const Tensor* past_ids = context->Input<Tensor>(3);
  const TensorShape& input_shape = input_ids->Shape();
  ORT_RETURN_IF_NOT(input_shape.NumDimensions() == 2, "input_ids must have rank 2");
  ORT_RETURN_IF_NOT(multipliers->Shape().NumDimensions() == 1 &&
                        multipliers->Shape()[0] == max_ngram_size_,
                    "multipliers must have shape (max_ngram_size)");
  const int64_t num_heads = (max_ngram_size_ - 1) * n_head_per_ngram_;
  ORT_RETURN_IF_NOT(vocab_sizes->Shape().NumDimensions() == 1 && vocab_sizes->Shape()[0] == num_heads,
                    "vocab_sizes must have shape ((max_ngram_size - 1) * n_head_per_ngram)");

  const int64_t batch_size = input_shape[0];
  const int64_t sequence_length = input_shape[1];
  // An n-gram window reaches this many positions before the current token.
  const int64_t state_length = max_ngram_size_ - 1;
  if (past_ids != nullptr) {
    ORT_RETURN_IF_NOT(past_ids->Shape() == TensorShape({batch_size, state_length}),
                      "past_ids must have shape (batch_size, max_ngram_size - 1)");
  }

  Tensor* output = context->Output(0, TensorShape({batch_size, sequence_length, num_heads}));
  Tensor* present_ids = context->Output(1, TensorShape({batch_size, state_length}));
  return LaunchNGramHashMappingKernel<T>(
      Stream(context),
      input_ids->Data<T>(),
      multipliers->Data<T>(),
      vocab_sizes->Data<T>(),
      past_ids == nullptr ? nullptr : past_ids->Data<T>(),
      output->MutableData<T>(),
      present_ids == nullptr ? nullptr : present_ids->MutableData<T>(),
      batch_size,
      sequence_length,
      max_ngram_size_,
      n_head_per_ngram_,
      pad_id_);
}

Status EngramGateProgram::GenerateShaderCode(ShaderHelper& shader) const {
  const auto& value = shader.AddInput("value", ShaderUsage::UseUniform | ShaderUsage::UseElementTypeAlias);
  const auto& gate = shader.AddInput("gate", ShaderUsage::UseUniform);
  const auto& output = shader.AddOutput("output", ShaderUsage::UseUniform | ShaderUsage::UseValueTypeAlias);

  // value and output are both contiguous over the hidden dimension, and the gate is constant across
  // it, so one invocation can broadcast the gate over a whole vecN of channels.
  const int components = value.NumComponents();

  shader.AdditionalImplementation() << "alias gate_f32_t = " << MakeScalarOrVectorType(components, "f32") << ";\n";

  shader.MainFunctionBody()
      << shader.GuardAgainstOutOfBoundsWorkgroupSizes("uniforms.total")
      << "  let c = global_idx % uniforms.hidden_vec_size;\n"
      << "  let row = global_idx / uniforms.hidden_vec_size;\n"
      << "  let token = row / uniforms.hc_mult;\n"
      << "  let value_element = gate_f32_t(" << value.GetByOffset("token * uniforms.hidden_vec_size + c") << ");\n"
      << "  " << output.SetByOffset("global_idx", "output_value_t(" + gate.GetByOffset("row") + " * value_element)")
      << "\n";
  return Status::OK();
}

Status EngramGate::ComputeInternal(ComputeContext& context) const {
  const auto* key = context.Input(0);
  const auto* query = context.Input(1);
  const auto* value = context.Input(2);
  const auto* key_norm_scale = context.Input(3);
  const auto* query_norm_scale = context.Input(4);

  const auto& key_shape = key->Shape();
  ORT_RETURN_IF_NOT(key_shape.NumDimensions() == 4,
                    "key must have shape (batch_size, sequence_length, hc_mult, hidden_size)");
  const int64_t batch_size = key_shape[0];
  const int64_t sequence_length = key_shape[1];
  const int64_t hc_mult = key_shape[2];
  const int64_t hidden_size = key_shape[3];

  ORT_RETURN_IF_NOT(query->Shape() == key_shape, "query must have the same shape as key");
  ORT_RETURN_IF_NOT(value->Shape() == TensorShape({batch_size, sequence_length, hidden_size}),
                    "value must have shape (batch_size, sequence_length, hidden_size)");
  ORT_RETURN_IF_NOT(key_norm_scale->Shape() == TensorShape({hc_mult, hidden_size}),
                    "key_norm_scale must have shape (hc_mult, hidden_size)");
  ORT_RETURN_IF_NOT(query_norm_scale->Shape() == TensorShape({hc_mult, hidden_size}),
                    "query_norm_scale must have shape (hc_mult, hidden_size)");

  auto* output = context.Output(0, key_shape);
  const int64_t total = key_shape.Size();
  if (total == 0) {
    return Status::OK();
  }

  // First pass: one scalar gate per (token, g) row.
  const int64_t rows = batch_size * sequence_length * hc_mult;
  const int components = onnxruntime::webgpu::GetMaxComponents(hidden_size);
  const int64_t hidden_vec_size = hidden_size / components;
  Tensor gate = context.CreateGPUTensor(DataTypeImpl::GetType<float>(), TensorShape({rows}));
  EngramGateScalarProgram gate_program;
  gate_program
      .CacheHint(components)
      .AddInputs({{key, ProgramTensorMetadataDependency::Type, ProgramInput::Flatten, components},
                  {query, ProgramTensorMetadataDependency::Type, ProgramInput::Flatten, components},
                  {key_norm_scale, ProgramTensorMetadataDependency::Type, ProgramInput::Flatten, components},
                  {query_norm_scale, ProgramTensorMetadataDependency::Type, ProgramInput::Flatten, components}})
      .AddOutput({&gate, ProgramTensorMetadataDependency::None})
      .SetWorkgroupSize(kGateWorkgroupSize)
      .SetDispatchGroupSize(onnxruntime::narrow<uint32_t>(rows))
      .AddUniformVariables({{onnxruntime::narrow<uint32_t>(rows)},
                            {onnxruntime::narrow<uint32_t>(hc_mult)},
                            {onnxruntime::narrow<uint32_t>(hidden_size)},
                            {onnxruntime::narrow<uint32_t>(hidden_vec_size)},
                            {epsilon_}});
  ORT_RETURN_IF_ERROR(context.RunProgram(gate_program));

  // Second pass: broadcast the shared gate over the value channels.
  const int64_t total_vec = total / components;
  EngramGateProgram program;
  program
      .CacheHint(components)
      .AddInputs({{value, ProgramTensorMetadataDependency::Type, ProgramInput::Flatten, components},
                  {&gate, ProgramTensorMetadataDependency::Type}})
      .AddOutput({output, ProgramTensorMetadataDependency::None, ProgramOutput::Flatten, components})
      .SetDispatchGroupSize((onnxruntime::narrow<uint32_t>(total_vec) + WORKGROUP_SIZE - 1) / WORKGROUP_SIZE)
      .AddUniformVariables({{onnxruntime::narrow<uint32_t>(total_vec)},
                            {onnxruntime::narrow<uint32_t>(hc_mult)},
                            {onnxruntime::narrow<uint32_t>(hidden_vec_size)}});
  return context.RunProgram(program);
}

Status NGramHashMappingProgram::GenerateShaderCode(ShaderHelper& shader) const {
  const auto& input_ids = shader.AddInput("input_ids", ShaderUsage::UseUniform);
  const auto& multipliers = shader.AddInput("multipliers", ShaderUsage::UseUniform);
  const auto& vocab_sizes = shader.AddInput("vocab_sizes", ShaderUsage::UseUniform);
  const ShaderVariableHelper* past_ids = nullptr;
  if (has_past_ids_) {
    past_ids = &shader.AddInput("past_ids", ShaderUsage::UseUniform);
  }
  const auto& output = shader.AddOutput("output", ShaderUsage::UseUniform);

  shader.AdditionalImplementation() << engram_helper::kPositiveModWgsl;

  shader.MainFunctionBody()
      << shader.GuardAgainstOutOfBoundsWorkgroupSizes("uniforms.total")
      << "  let num_heads = (uniforms.max_ngram_size - 1u) * uniforms.n_head_per_ngram;\n"
      << "  let t = global_idx % uniforms.sequence_length;\n"
      << "  let b = global_idx / uniforms.sequence_length;\n"
      << "  let input_base = b * uniforms.sequence_length;\n"
      << "  let output_base = global_idx * num_heads;\n"
      << "  let state_length = uniforms.max_ngram_size - 1u;\n"
      << "  let past_base = b * state_length;\n"
      << "  for (var n = 2u; n <= uniforms.max_ngram_size; n++) {\n"
      << "    var mix = 0i;\n"
      << "    for (var k = 0u; k < n; k++) {\n"
      << "      var token = uniforms.pad_id;\n"
      << "      if (t >= k) {\n"
      << "        token = " << input_ids.GetByOffset("input_base + t - k") << ";\n"
      << "      }\n";
  if (has_past_ids_) {
    // past_ids is right-aligned, so position -1 is its last slot. k <= max_ngram_size - 1 keeps the
    // slot inside the window, so no additional bounds check is needed here.
    shader.MainFunctionBody()
        << "      if (t < k) {\n"
        << "        token = " << past_ids->GetByOffset("past_base + state_length + t - k") << ";\n"
        << "      }\n";
  }
  shader.MainFunctionBody()
      << "      let product = token * " << multipliers.GetByOffset("k") << ";\n"
      << "      if (k == 0u) { mix = product; } else { mix = mix ^ product; }\n"
      << "    }\n"
      << "    let ngram_offset = (n - 2u) * uniforms.n_head_per_ngram;\n"
      << "    for (var h = 0u; h < uniforms.n_head_per_ngram; h++) {\n"
      << "      let out_h = ngram_offset + h;\n"
      << "      let mod_value = " << vocab_sizes.GetByOffset("out_h") << ";\n"
      << "      var result = 0i;\n"
      << "      if (mod_value > 0i) {\n"
      << "        result = positive_mod(mix, mod_value);\n"
      << "      }\n"
      << "      " << output.SetByOffset("output_base + out_h", "result") << "\n"
      << "    }\n"
      << "  }\n";
  return Status::OK();
}

Status NGramPresentIdsProgram::GenerateShaderCode(ShaderHelper& shader) const {
  const ShaderVariableHelper* input_ids = nullptr;
  if (has_input_ids_) {
    input_ids = &shader.AddInput("input_ids", ShaderUsage::UseUniform);
  }
  const ShaderVariableHelper* past_ids = nullptr;
  if (has_past_ids_ && !past_aliases_present_) {
    past_ids = &shader.AddInput("past_ids", ShaderUsage::UseUniform);
  }
  const auto& present_ids = shader.AddOutput("present_ids", ShaderUsage::UseUniform);
  // When past_ids aliases present_ids the history lives in the output buffer itself, and reading it
  // through the read_write binding is the only spec-legal way to reach it.
  const ShaderVariableHelper* history = past_aliases_present_ ? &present_ids : past_ids;

  // past_ids and present_ids may be the same buffer, which is what threading present_ids straight
  // back into past_ids produces; `history` above then points at the output binding. Slot `slot`
  // writes index `slot` and reads index `slot + sequence_length`, so the read and write ranges
  // overlap and must be separated. One workgroup owns one batch row and walks it in ascending
  // workgroup-sized chunks: a barrier separates the chunk's reads from its writes, and a chunk only
  // writes indices strictly below the read indices of every later chunk.
  shader.MainFunctionBody()
      << "  let b = workgroup_idx;\n"
      // NormalizeDispatchGroupSize reshapes an oversized 1-D dispatch to a 2-D grid that rounds up,
      // so a large batch_size can produce workgroups past the last row.
      << "  if (b >= uniforms.batch_size) { return; }\n"
      << "  let row_base = b * uniforms.state_length;\n"
      << "  for (var chunk = 0u; chunk < uniforms.state_length; chunk += workgroup_size_x) {\n"
      << "    let slot = chunk + local_idx;\n"
      << "    var token = uniforms.pad_id;\n"
      << "    if (slot < uniforms.state_length) {\n";
  if (has_input_ids_) {
    shader.MainFunctionBody()
        << "      if (slot + uniforms.sequence_length >= uniforms.state_length) {\n"
        << "        let source_t = slot + uniforms.sequence_length - uniforms.state_length;\n"
        << "        token = " << input_ids->GetByOffset("b * uniforms.sequence_length + source_t") << ";\n"
        << "      }\n";
  }
  if (has_past_ids_) {
    shader.MainFunctionBody()
        << "      if (slot + uniforms.sequence_length < uniforms.state_length) {\n"
        << "        token = " << history->GetByOffset("b * uniforms.state_length + slot + uniforms.sequence_length")
        << ";\n"
        << "      }\n";
  }
  shader.MainFunctionBody()
      << "    }\n"
      << "    workgroupBarrier();\n"
      << "    if (slot < uniforms.state_length) {\n"
      << "      " << present_ids.SetByOffset("row_base + slot", "token") << "\n"
      << "    }\n"
      << "    workgroupBarrier();\n"
      << "  }\n";
  return Status::OK();
}

NGramHashMapping::NGramHashMapping(const OpKernelInfo& info) : WebGpuKernel(info) {
  ORT_ENFORCE(info.GetAttr<int64_t>("max_ngram_size", &max_ngram_size_).IsOK(),
              "max_ngram_size attribute is required");
  ORT_ENFORCE(info.GetAttr<int64_t>("n_head_per_ngram", &n_head_per_ngram_).IsOK(),
              "n_head_per_ngram attribute is required");
  ORT_ENFORCE(info.GetAttr<int64_t>("pad_id", &pad_id_).IsOK(), "pad_id attribute is required");
  ORT_ENFORCE(max_ngram_size_ >= 2, "max_ngram_size must be at least 2");
  ORT_ENFORCE(n_head_per_ngram_ >= 1, "n_head_per_ngram must be positive");
  ORT_ENFORCE(pad_id_ >= std::numeric_limits<int32_t>::min() && pad_id_ <= std::numeric_limits<int32_t>::max(),
              "WebGPU NGramHashMapping only supports int32 ids");
}

Status NGramHashMapping::ComputeInternal(ComputeContext& context) const {
  const auto* input_ids = context.Input(0);
  const auto* multipliers = context.Input(1);
  const auto* vocab_sizes = context.Input(2);
  const auto* past_ids = context.Input(3);
  const auto& input_shape = input_ids->Shape();
  ORT_RETURN_IF_NOT(input_shape.NumDimensions() == 2, "input_ids must have rank 2");
  ORT_RETURN_IF_NOT(multipliers->Shape().NumDimensions() == 1 && multipliers->Shape()[0] == max_ngram_size_,
                    "multipliers must have shape (max_ngram_size)");
  const int64_t num_heads = (max_ngram_size_ - 1) * n_head_per_ngram_;
  ORT_RETURN_IF_NOT(vocab_sizes->Shape() == TensorShape({num_heads}),
                    "vocab_sizes must have shape ((max_ngram_size - 1) * n_head_per_ngram)");
  const int64_t batch_size = input_shape[0];
  const int64_t sequence_length = input_shape[1];
  // An n-gram window reaches this many positions before the current token.
  const int64_t state_length = max_ngram_size_ - 1;
  if (past_ids != nullptr) {
    ORT_RETURN_IF_NOT(past_ids->Shape() == TensorShape({batch_size, state_length}),
                      "past_ids must have shape (batch_size, max_ngram_size - 1)");
  }
  const bool has_past_ids = past_ids != nullptr;

  auto* output = context.Output(0, TensorShape({batch_size, sequence_length, num_heads}));
  auto* present_ids = context.Output(1, TensorShape({batch_size, state_length}));

  // The hash program reads past_ids and the present program writes present_ids, so when the caller
  // aliases the two the hash program must be queued first.
  const int64_t total = input_shape.Size();
  if (total > 0) {
    NGramHashMappingProgram program{has_past_ids};
    program.CacheHint(has_past_ids)
        .AddInputs({{input_ids, ProgramTensorMetadataDependency::None},
                    {multipliers, ProgramTensorMetadataDependency::None},
                    {vocab_sizes, ProgramTensorMetadataDependency::None}});
    if (has_past_ids) {
      program.AddInput({past_ids, ProgramTensorMetadataDependency::None});
    }
    program.AddOutput({output, ProgramTensorMetadataDependency::None})
        .SetDispatchGroupSize((onnxruntime::narrow<uint32_t>(total) + WORKGROUP_SIZE - 1) / WORKGROUP_SIZE)
        .AddUniformVariables({{onnxruntime::narrow<uint32_t>(total)},
                              {onnxruntime::narrow<uint32_t>(sequence_length)},
                              {onnxruntime::narrow<uint32_t>(max_ngram_size_)},
                              {onnxruntime::narrow<uint32_t>(n_head_per_ngram_)},
                              {onnxruntime::narrow<int32_t>(pad_id_)}});
    ORT_RETURN_IF_ERROR(context.RunProgram(program));
  }

  if (present_ids != nullptr && batch_size * state_length > 0) {
    // WebGPU rejects zero-sized storage buffer bindings, so an empty input_ids tensor must not be
    // bound. When sequence_length == 0 every present slot comes from history (or pad_id), so the
    // input_ids branch of the shader is dead anyway.
    const bool has_input_ids = sequence_length > 0;
    // WebGPU rejects a bind group that exposes one buffer as both read-only and read-write storage
    // in the same compute pass, so an aliased past_ids must not be bound a second time.
    const bool past_aliases_present = has_past_ids && past_ids->DataRaw() == present_ids->DataRaw();
    NGramPresentIdsProgram present_program{has_input_ids, has_past_ids, past_aliases_present};
    present_program.CacheHint(has_input_ids, has_past_ids, past_aliases_present);
    if (has_input_ids) {
      present_program.AddInput({input_ids, ProgramTensorMetadataDependency::None});
    }
    if (has_past_ids && !past_aliases_present) {
      present_program.AddInput({past_ids, ProgramTensorMetadataDependency::None});
    }
    // One workgroup per batch row, so the shader can use a workgroup barrier to order its reads
    // against its writes.
    present_program.AddOutput({present_ids, ProgramTensorMetadataDependency::None})
        .SetDispatchGroupSize(onnxruntime::narrow<uint32_t>(batch_size))
        .AddUniformVariables({{onnxruntime::narrow<uint32_t>(batch_size)},
                              {onnxruntime::narrow<uint32_t>(sequence_length)},
                              {onnxruntime::narrow<uint32_t>(state_length)},
                              {onnxruntime::narrow<int32_t>(pad_id_)}});
    ORT_RETURN_IF_ERROR(context.RunProgram(present_program));
  }

  return Status::OK();
}

float Sigmoid(float x) {
  if (x > 0.0f) {
    return 1.0f / (1.0f + std::exp(-x));
  }
  const float exp_x = std::exp(x);
  return exp_x / (1.0f + exp_x);
}

std::vector<T> ToTensorType(const std::vector<float>& data) {
  if constexpr (std::is_same_v<T, MLFloat16>) {
    return ToFloat16(data);
  } else if constexpr (std::is_same_v<T, BFloat16>) {
    return ToBFloat16(data);
  } else {
    return data;
  }
}

bool IsTypeSupported() {
  if constexpr (std::is_same_v<T, BFloat16>) {
    return DefaultCudaExecutionProvider() != nullptr;
  } else {
    return true;
  }
}

void RunOnSupportedProviders(OpTester& test) {
  if constexpr (std::is_same_v<T, BFloat16>) {
    std::vector<std::unique_ptr<IExecutionProvider>> providers;
    providers.push_back(DefaultCudaExecutionProvider());
    test.Run(OpTester::ExpectResult::kExpectSuccess, "", {}, nullptr, &providers);
  } else {
    test.Run();
  }
}

std::vector<float> MakeWave(size_t count, float phase, float step) {
  std::vector<float> values(count);
  for (size_t i = 0; i < count; ++i) {
    values[i] = std::sin(phase + step * static_cast<float>(i));
  }
  return values;
}

float GateArg(float dot) {
  if (dot == 0.0f) {
    return 0.0f;
  }
  const float magnitude = std::sqrt(std::max(std::abs(dot), 1.0e-6f));
  return dot < 0.0f ? -magnitude : magnitude;
}

float EngramGateReference(const std::vector<float>& key, const std::vector<float>& query) {
  const auto hidden_size = static_cast<float>(key.size());
  float key_sum_sq = 0.0f;
  float query_sum_sq = 0.0f;
  for (size_t c = 0; c < key.size(); ++c) {
    key_sum_sq += key[c] * key[c];
    query_sum_sq += query[c] * query[c];
  }
  const float key_inv = 1.0f / std::sqrt(key_sum_sq / hidden_size + kEpsilon);
  const float query_inv = 1.0f / std::sqrt(query_sum_sq / hidden_size + kEpsilon);
  float dot = 0.0f;
  for (size_t c = 0; c < key.size(); ++c) {
    dot += key[c] * key_inv * query[c] * query_inv;
  }
  dot /= std::sqrt(hidden_size);
  return Sigmoid(GateArg(dot));
}

void RunEngramGateTest(float tolerance) {
  if (!IsTypeSupported<T>()) {
    GTEST_SKIP() << "No execution provider available for this type";
  }
  const std::vector<float> key{0.0f, 2.5f};
  const std::vector<float> query{3.0f, 4.0f};
  const std::vector<float> value{2.0f, -1.5f};
  const std::vector<float> unit_scale{1.0f, 1.0f};

  const float gate = EngramGateReference(key, query);
  const std::vector<float> expected{gate * value[0], gate * value[1]};

  OpTester test("EngramGate", 1, kMSDomain);
  test.AddAttribute<float>("epsilon", kEpsilon);
  test.AddInput<T>("key", {1, 1, 1, 2}, ToTensorType<T>(key));
  test.AddInput<T>("query", {1, 1, 1, 2}, ToTensorType<T>(query));
  test.AddInput<T>("value", {1, 1, 2}, ToTensorType<T>(value));
  test.AddInput<T>("key_norm_scale", {1, 2}, ToTensorType<T>(unit_scale));
  test.AddInput<T>("query_norm_scale", {1, 2}, ToTensorType<T>(unit_scale));
  test.AddOutput<T>("output", {1, 1, 1, 2}, ToTensorType<T>(expected), false, tolerance, tolerance);
  RunOnSupportedProviders<T>(test);
}

void RunEngramGateVectorizedTest(float tolerance, int64_t hidden) {
  if (!IsTypeSupported<T>()) {
    GTEST_SKIP() << "No execution provider available for this type";
  }
  constexpr int64_t kBatch = 1;
  constexpr int64_t kSequence = 2;
  constexpr int64_t kHcMult = 2;
  const int64_t rows = kBatch * kSequence * kHcMult;

  const std::vector<float> key = MakeWave(static_cast<size_t>(rows * hidden), -0.9f, 0.3f);
  const std::vector<float> query = MakeWave(static_cast<size_t>(rows * hidden), 1.2f, -0.25f);
  const std::vector<float> value = MakeWave(static_cast<size_t>(kBatch * kSequence * hidden), 0.4f, 0.35f);
  const std::vector<float> key_scale = MakeWave(static_cast<size_t>(kHcMult * hidden), 0.6f, 0.1f);
  const std::vector<float> query_scale = MakeWave(static_cast<size_t>(kHcMult * hidden), 1.4f, -0.15f);

  std::vector<float> expected(static_cast<size_t>(rows * hidden));
  for (int64_t row = 0; row < rows; ++row) {
    const int64_t g = row % kHcMult;
    const int64_t token = row / kHcMult;
    float key_sum_sq = 0.0f;
    float query_sum_sq = 0.0f;
    for (int64_t c = 0; c < hidden; ++c) {
      const float k = key[static_cast<size_t>(row * hidden + c)];
      const float q = query[static_cast<size_t>(row * hidden + c)];
      key_sum_sq += k * k;
      query_sum_sq += q * q;
    }
    const float key_inv = 1.0f / std::sqrt(key_sum_sq / static_cast<float>(hidden) + kEpsilon);
    const float query_inv = 1.0f / std::sqrt(query_sum_sq / static_cast<float>(hidden) + kEpsilon);
    float dot = 0.0f;
    for (int64_t c = 0; c < hidden; ++c) {
      const auto scale_index = static_cast<size_t>(g * hidden + c);
      const float normed_key = key[static_cast<size_t>(row * hidden + c)] * key_inv * key_scale[scale_index];
      const float normed_query =
          query[static_cast<size_t>(row * hidden + c)] * query_inv * query_scale[scale_index];
      dot += normed_key * normed_query;
    }
    dot /= std::sqrt(static_cast<float>(hidden));
    const float gate = Sigmoid(GateArg(dot));
    for (int64_t c = 0; c < hidden; ++c) {
      expected[static_cast<size_t>(row * hidden + c)] = gate * value[static_cast<size_t>(token * hidden + c)];
    }
  }

  OpTester test("EngramGate", 1, kMSDomain);
  test.AddAttribute<float>("epsilon", kEpsilon);
  test.AddInput<T>("key", {kBatch, kSequence, kHcMult, hidden}, ToTensorType<T>(key));
  test.AddInput<T>("query", {kBatch, kSequence, kHcMult, hidden}, ToTensorType<T>(query));
  test.AddInput<T>("value", {kBatch, kSequence, hidden}, ToTensorType<T>(value));
  test.AddInput<T>("key_norm_scale", {kHcMult, hidden}, ToTensorType<T>(key_scale));
  test.AddInput<T>("query_norm_scale", {kHcMult, hidden}, ToTensorType<T>(query_scale));
  test.AddOutput<T>("output", {kBatch, kSequence, kHcMult, hidden}, ToTensorType<T>(expected), false, tolerance,
                    tolerance);
  RunOnSupportedProviders<T>(test);
}

std::vector<T> NGramHashMappingReference(const std::vector<T>& ids,
                                         const std::vector<T>& history,
                                         const std::vector<T>& multipliers,
                                         const std::vector<T>& vocab_sizes,
                                         int64_t pad_id = kPadId) {
  const int64_t sequence_length = static_cast<int64_t>(ids.size());
  const int64_t state_length = kMaxNGramSize - 1;
  const int64_t num_heads = state_length * kHeadsPerNGram;
  std::vector<T> output(static_cast<size_t>(sequence_length * num_heads));

  auto id_at = [&](int64_t t) -> T {
    if (t >= 0) {
      return ids[static_cast<size_t>(t)];
    }
    const int64_t slot = state_length + t;
    if (history.empty() || slot < 0) {
      return static_cast<T>(pad_id);
    }
    return history[static_cast<size_t>(slot)];
  };

  for (int64_t t = 0; t < sequence_length; ++t) {
    for (int64_t n = 2; n <= kMaxNGramSize; ++n) {
      T mix = 0;
      for (int64_t k = 0; k < n; ++k) {
        // Multiplication wraps on overflow, matching the kernel's unsigned arithmetic.
        using U = std::make_unsigned_t<T>;
        const T product = static_cast<T>(static_cast<U>(id_at(t - k)) *
                                         static_cast<U>(multipliers[static_cast<size_t>(k)]));
        mix = k == 0 ? product : static_cast<T>(mix ^ product);
      }
      for (int64_t h = 0; h < kHeadsPerNGram; ++h) {
        const int64_t out_h = (n - 2) * kHeadsPerNGram + h;
        const T mod = vocab_sizes[static_cast<size_t>(out_h)];
        T value = static_cast<T>(mix % mod);
        if (value < 0) {
          value = static_cast<T>(value + mod);
        }
        output[static_cast<size_t>(t * num_heads + out_h)] = value;
      }
    }
  }
  return output;
}

void RunNGramHashMappingNegativeIdsTest() {
  constexpr int64_t kNegativePadId = -4;
  const std::vector<T> ids{-5, 7, -3, 2};
  const std::vector<T> multipliers{11, 13, 17};
  const std::vector<T> vocab_sizes{101, 103, 107, 109};
  const std::vector<T> expected =
      NGramHashMappingReference<T>(ids, {}, multipliers, vocab_sizes, kNegativePadId);
  // Pins the reference, and the values themselves: every entry is a positive residue even though
  // most of the underlying mixes are negative, which is exactly the PositiveMod correction.
  ASSERT_EQ(expected, (std::vector<T>{5, 5, 36, 38,
                                      87, 89, 78, 78,
                                      78, 82, 47, 47,
                                      52, 54, 35, 37}));
  for (const T value : expected) {
    ASSERT_GE(value, 0);
  }

  OpTester test("NGramHashMapping", 1, kMSDomain);
  test.AddAttribute<int64_t>("max_ngram_size", kMaxNGramSize);
  test.AddAttribute<int64_t>("n_head_per_ngram", kHeadsPerNGram);
  test.AddAttribute<int64_t>("pad_id", kNegativePadId);
  test.AddInput<T>("input_ids", {1, 4}, ids);
  test.AddInput<T>("multipliers", {3}, multipliers);
  test.AddInput<T>("vocab_sizes", {4}, vocab_sizes);
  test.AddOptionalInputEdge<T>();
  test.AddOutput<T>("hash_ids", {1, 4, 4}, expected);
  test.AddOutput<T>("present_ids", {1, 2}, {ids[2], ids[3]});
  test.Run();
}

