TEST(Scan9, NumScanInputsExceedsVariadicInputs) {
  RunOptions options{};
  options.is_v8 = false;

  Model model("NumScanInputsExceedsVariadicInputs_v9", false, ModelMetaData(), PathString(),
              IOnnxRuntimeOpSchemaRegistryList(), {{"", 9}}, {}, DefaultLoggingManager().DefaultLogger());
  auto& graph = model.MainGraph();
  ASSERT_STATUS_OK(CreateSubgraph(graph, options));
  auto& proto = graph.ToGraphProto();

  ScanOpTester test{9};
  test.AddAttribute("body", proto);
  // The subgraph has 1 loop state variable and 2 scan inputs -> 3 variadic inputs (no 'sequence_lens'
  // in opset 9+). Requesting 10 scan inputs is invalid regardless of the Scan node's actual inputs.
  test.AddAttribute<int64_t>("num_scan_inputs", 10);

  test.AddInput<float>("scan_loop_state_in_0", {1}, {0.f});
  test.AddInput<float>("scan_input_0", {2, 2}, {1.f, 2.f, 3.f, 4.f});
  test.AddInput<float>("scan_input_1", {2, 2}, {-1.f, -2.f, -3.f, -4.f});

  test.AddOutput<float>("scan_loop_state_out_0", {1}, {1.f});
  test.AddOutput<float>("scan_output_0", {2, 1}, {0.f, 0.f});
  test.AddOutput<float>("scan_output_1", {2, 1}, {0.f, 0.f});
  test.AddOutput<float>("scan_output_2", {2, 1}, {0.f, 0.f});
  test.AddOutput<float>("scan_output_3", {2, 1}, {0.f, 0.f});

  // Unlike opset 8, opset 9+ Scan is type/shape-inferred via the standard ONNX inferencing path. With
  // 'num_scan_inputs' wrongly set to 10, the loop-state-variable/scan-input split used to propagate
  // input types into the body subgraph is wrong too, so the subgraph's own output shape inference ends
  // up disagreeing with its declared output shape and graph resolution fails before the node's kernel
  // (and its own attribute validation) is ever constructed. The failure surfaces as a graph attribute
  // inferencing error wrapping a shape-inference error, rather than the kernel-level message produced
  // by the opset 8 test above.
  test.Run(OpTester::ExpectResult::kExpectFailure,
           "[ShapeInferenceError] Mismatch between number of inferred and declared dimensions",
           options.excluded_provider_types);
}

bool MLASCALL
MlasHalfGemmAccelerationSupported(
    const MLAS_BACKEND_KERNEL_SELECTOR_CONFIG* BackendKernelSelectorConfig
    )
{
    if ((!BackendKernelSelectorConfig || BackendKernelSelectorConfig->use_kleidiai) &&
        GetMlasPlatform().MlasHalfGemmBatchOverride != nullptr) {
        return true;
    }

#if (defined(MLAS_F16VEC_INTRINSICS_SUPPORTED) && defined(MLAS_TARGET_ARM64)) || \
    (defined(MLAS_TARGET_RISCV64) && defined(MLAS_USE_RVV_ZVFH))
    return MlasFp16AccelerationSupported();
#else
    return false;
#endif
}

Status RegisterFp16GemmMatMulKernels(KernelRegistry& kernel_registry) {
  static const BuildKernelCreateInfoFn function_table[] = {
      BuildKernelCreateInfo<void>,  // default entry to avoid the list become empty after ops-reducing
      BuildKernelCreateInfo<ONNX_OPERATOR_VERSIONED_TYPED_KERNEL_CLASS_NAME(kCpuExecutionProvider, kOnnxDomain, 7, 8,
                                                                            MLFloat16, Gemm)>,
      BuildKernelCreateInfo<ONNX_OPERATOR_VERSIONED_TYPED_KERNEL_CLASS_NAME(kCpuExecutionProvider, kOnnxDomain, 9, 10,
                                                                            MLFloat16, Gemm)>,
      BuildKernelCreateInfo<ONNX_OPERATOR_VERSIONED_TYPED_KERNEL_CLASS_NAME(kCpuExecutionProvider, kOnnxDomain, 11, 12,
                                                                            MLFloat16, Gemm)>,
      BuildKernelCreateInfo<ONNX_OPERATOR_TYPED_KERNEL_CLASS_NAME(kCpuExecutionProvider, kOnnxDomain, 13, MLFloat16, Gemm)>,
      BuildKernelCreateInfo<ONNX_OPERATOR_VERSIONED_TYPED_KERNEL_CLASS_NAME(kCpuExecutionProvider, kOnnxDomain, 1, 8,
                                                                            MLFloat16, MatMul)>,
      BuildKernelCreateInfo<ONNX_OPERATOR_VERSIONED_TYPED_KERNEL_CLASS_NAME(kCpuExecutionProvider, kOnnxDomain, 9, 12,
                                                                            MLFloat16, MatMul)>,
      BuildKernelCreateInfo<ONNX_OPERATOR_TYPED_KERNEL_CLASS_NAME(kCpuExecutionProvider, kOnnxDomain, 13, MLFloat16,
                                                                  MatMul)>,
  };

  if constexpr (std::size(function_table) > 1) {
    // Kernel registration is process-wide and based on the default backend
    // selector config (nullptr => use_kleidiai=true). A session can still
    // disable KleidiAI via kOrtSessionOptionsMlasDisableKleidiAi, in which case
    // MatMul/Gemm may run their non-accelerated fp16 fallback for these kernels.
    if (MlasHalfGemmAccelerationSupported(nullptr)) {
      for (auto& function_table_entry : function_table) {
        KernelCreateInfo info = function_table_entry();
        if (info.kernel_def != nullptr) {
          ORT_RETURN_IF_ERROR(kernel_registry.Register(std::move(info)));
        }
      }
    }
  }

  return Status::OK();
}

TEST(CPUExecutionProviderTest, Float16GemmAndMatMulRegistration) {
  auto kernel_registry = CPUExecutionProvider(CPUExecutionProviderInfo()).GetKernelRegistry();
  ASSERT_NE(kernel_registry, nullptr);

  const auto has_kernel = [&](std::string_view op_type, int opset_version, const DataTypeImpl* tensor_type) {
    KernelRegistry::TypeConstraintMap type_constraints{{"T", tensor_type}};
    const KernelCreateInfo* kernel_create_info{};
    const auto status = kernel_registry->TryFindKernel(
        kCpuExecutionProvider, op_type, kOnnxDomain, opset_version, type_constraints,
        DefaultLoggingManager().DefaultLogger(), &kernel_create_info);
    return status.IsOK() && kernel_create_info != nullptr;
  };

  const auto* fp32_tensor_type = DataTypeImpl::GetTensorType<float>();
  EXPECT_TRUE(has_kernel("Gemm", 10, fp32_tensor_type));
  EXPECT_TRUE(has_kernel("Gemm", 12, fp32_tensor_type));
  EXPECT_TRUE(has_kernel("MatMul", 10, fp32_tensor_type));
  EXPECT_TRUE(has_kernel("MatMul", 12, fp32_tensor_type));

  const auto* fp16_tensor_type = DataTypeImpl::GetTensorType<MLFloat16>();
  const bool expected_kernel = MlasHalfGemmAccelerationSupported(nullptr);
  EXPECT_EQ(has_kernel("Gemm", 8, fp16_tensor_type), expected_kernel);
  EXPECT_EQ(has_kernel("Gemm", 10, fp16_tensor_type), expected_kernel);
  EXPECT_EQ(has_kernel("Gemm", 12, fp16_tensor_type), expected_kernel);
  EXPECT_EQ(has_kernel("Gemm", 13, fp16_tensor_type), expected_kernel);
  EXPECT_EQ(has_kernel("MatMul", 8, fp16_tensor_type), expected_kernel);
  EXPECT_EQ(has_kernel("MatMul", 10, fp16_tensor_type), expected_kernel);
  EXPECT_EQ(has_kernel("MatMul", 12, fp16_tensor_type), expected_kernel);
  EXPECT_EQ(has_kernel("MatMul", 13, fp16_tensor_type), expected_kernel);
}

