TEST(ActivationCacheKeyTest, QuickGeluUnitAlphaIsKeyedSeparately) {
  const auto unit_alpha = MakeActivation(webgpu::ActivationKind::QuickGelu, 1.0f);
  const auto other_alpha = MakeActivation(webgpu::ActivationKind::QuickGelu, 1.702f);

  EXPECT_NE(unit_alpha.CacheKey(), other_alpha.CacheKey())
      << "QuickGelu drops the multiply at alpha == 1, which is different shader text";

  const auto another_alpha = MakeActivation(webgpu::ActivationKind::QuickGelu, 0.5f);
  EXPECT_EQ(other_alpha.CacheKey(), another_alpha.CacheKey());
}

std::vector<std::string> ExtractNumericLiterals(const std::string& wgsl) {
  std::vector<std::string> literals;
  for (size_t i = 0; i < wgsl.size();) {
    const bool starts_number =
        (std::isdigit(static_cast<unsigned char>(wgsl[i])) != 0) ||
        (wgsl[i] == '-' && i + 1 < wgsl.size() && std::isdigit(static_cast<unsigned char>(wgsl[i + 1])) != 0);
    const bool part_of_identifier =
        i > 0 && (std::isalnum(static_cast<unsigned char>(wgsl[i - 1])) != 0 || wgsl[i - 1] == '_');
    if (!starts_number || part_of_identifier) {
      i++;
      continue;
    }
    size_t end = i + 1;
    while (end < wgsl.size() && (std::isdigit(static_cast<unsigned char>(wgsl[end])) != 0 || wgsl[end] == '.' ||
                                 wgsl[end] == 'e' || wgsl[end] == 'E' ||
                                 ((wgsl[end] == '+' || wgsl[end] == '-') &&
                                  (wgsl[end - 1] == 'e' || wgsl[end - 1] == 'E')))) {
      end++;
    }
    literals.push_back(wgsl.substr(i, end - i));
    i = end;
  }
  return literals;
}

std::string RenderShortestRoundTrip(float value) {
  std::array<char, 32> buffer;
  const auto result = std::to_chars(buffer.data(), buffer.data() + buffer.size(), value);
  return std::string(buffer.data(), result.ptr);
}

Activation MakeActivation(ActivationKind kind, float param_0 = 0.0f, float param_1 = 0.0f) {
  Activation activation;
  activation.activation_kind_ = kind;
  activation.activation_params_.values_[0] = param_0;
  activation.activation_params_.values_[1] = param_1;
  return activation;
}

const std::vector<ActivationKind>& AllActivationKinds() {
  static const std::vector<ActivationKind> kinds{
      ActivationKind::Relu, ActivationKind::Sigmoid, ActivationKind::Clip,
      ActivationKind::HardSigmoid, ActivationKind::LeakyRelu, ActivationKind::Tanh,
      ActivationKind::QuickGelu, ActivationKind::HardSwish, ActivationKind::Elu,
      ActivationKind::Gelu, ActivationKind::GeluTanh, ActivationKind::Softplus,
      ActivationKind::ThresholdedRelu, ActivationKind::Erf};
  return kinds;
}

TEST(WebGpuActivationSnippetTest, ConstantsUseShortestRoundTripForm) {
  for (ActivationKind kind : AllActivationKinds()) {
    const Activation activation = MakeActivation(kind, 0.125f, 0.375f);
    for (const std::string& wgsl : {GetActivationSnippet(activation, "vec4<f32>", "f32"),
                                    GetActivationDeclaration(activation, "vec4<f32>", "f32")}) {
      for (const std::string& literal : ExtractNumericLiterals(wgsl)) {
        // Each literal must be the canonical shortest form of the f32 it parses to.
        const float parsed = std::strtof(literal.c_str(), nullptr);
        EXPECT_EQ(RenderShortestRoundTrip(parsed), literal)
            << "literal '" << literal << "' is not the shortest round-trippable form of the f32 it"
            << " parses to, for activation kind " << static_cast<int>(kind);
      }
    }
  }
}

TEST(WebGpuActivationSnippetTest, ConstantsAreLocaleIndependent) {
  std::vector<std::pair<std::string, std::string>> classic;
  for (ActivationKind kind : AllActivationKinds()) {
    const Activation activation = MakeActivation(kind, 0.125f, 0.375f);
    classic.emplace_back(GetActivationSnippet(activation, "vec4<f32>", "f32"),
                         GetActivationDeclaration(activation, "vec4<f32>", "f32"));
  }

  const ScopedGlobalLocale comma_locale{std::locale(std::locale::classic(), new CommaDecimalPoint)};
  ASSERT_EQ(std::use_facet<std::numpunct<char>>(std::locale()).decimal_point(), ',')
      << "the comma-decimal locale did not take effect, so this test proves nothing";

  size_t index = 0;
  for (ActivationKind kind : AllActivationKinds()) {
    const Activation activation = MakeActivation(kind, 0.125f, 0.375f);
    EXPECT_EQ(GetActivationSnippet(activation, "vec4<f32>", "f32"), classic[index].first)
        << "activation kind " << static_cast<int>(kind) << " emits locale-dependent snippet text";
    EXPECT_EQ(GetActivationDeclaration(activation, "vec4<f32>", "f32"), classic[index].second)
        << "activation kind " << static_cast<int>(kind) << " emits locale-dependent helper text";
    ++index;
  }
}

TEST(WebGpuActivationSnippetTest, KnownConstantsAreNotTruncated) {
  struct Expectation {
    ActivationKind kind;
    bool declaration;
    float value;
    const char* description;
  };
  const std::vector<Expectation> expectations{
      {ActivationKind::Gelu, false, 0.70710678118654752f, "Gelu 1/sqrt(2)"},
      {ActivationKind::Gelu, true, 0.3275911f, "erf r0"},
      {ActivationKind::Gelu, true, 1.061405429f, "erf r5"},
      {ActivationKind::Gelu, true, -1.453152027f, "erf r4"},
      {ActivationKind::Gelu, true, 1.421413741f, "erf r3"},
      {ActivationKind::Gelu, true, -0.284496736f, "erf r2"},
      {ActivationKind::Gelu, true, 0.254829592f, "erf r1"},
      {ActivationKind::GeluTanh, false, 0.035677408136300125f, "Gelu-tanh cubic coefficient"},
      {ActivationKind::GeluTanh, false, 0.79788456080286535f, "Gelu-tanh sqrt(2/pi)"},
      {ActivationKind::HardSwish, false, 1.0f / 6.0f, "HardSwish 1/6"},
  };

  for (const Expectation& expectation : expectations) {
    const Activation activation = MakeActivation(expectation.kind);
    const std::string wgsl = expectation.declaration
                                 ? GetActivationDeclaration(activation, "vec4<f32>", "f32")
                                 : GetActivationSnippet(activation, "vec4<f32>", "f32");

    bool found = false;
    for (const std::string& literal : ExtractNumericLiterals(wgsl)) {
      if (std::strtof(literal.c_str(), nullptr) == expectation.value) {
        found = true;
        break;
      }
    }
    EXPECT_TRUE(found) << expectation.description << " was not emitted at full precision. WGSL was:\n"
                       << wgsl;
  }
}

TEST(WebGpuActivationSnippetTest, ParametersAreReadFromUniformsNotBaked) {
  const std::vector<ActivationKind> parameterized{
      ActivationKind::Clip, ActivationKind::HardSigmoid, ActivationKind::LeakyRelu,
      ActivationKind::Elu, ActivationKind::ThresholdedRelu};

  for (ActivationKind kind : parameterized) {
    const Activation activation = MakeActivation(kind, 0.13579f, 0.24680f);
    const std::string wgsl = GetActivationSnippet(activation, "vec4<f32>", "f32");

    EXPECT_NE(wgsl.find("uniforms.activation_param_0"), std::string::npos)
        << "kind " << static_cast<int>(kind) << " does not read its parameter from a uniform: " << wgsl;
    EXPECT_EQ(wgsl.find("0.13579"), std::string::npos) << "parameter value baked into shader: " << wgsl;
    EXPECT_EQ(wgsl.find("0.2468"), std::string::npos) << "parameter value baked into shader: " << wgsl;
  }
}

TEST(WebGpuActivationSnippetTest, QuickGeluUnitAlphaIsASeparateShaderAndCacheKey) {
  const Activation silu = MakeActivation(ActivationKind::QuickGelu, 1.0f);
  const Activation general = MakeActivation(ActivationKind::QuickGelu, 1.702f);

  EXPECT_TRUE(silu.HasUnitQuickGeluAlpha());
  EXPECT_FALSE(general.HasUnitQuickGeluAlpha());

  const std::string silu_wgsl = GetActivationSnippet(silu, "vec4<f32>", "f32");
  const std::string general_wgsl = GetActivationSnippet(general, "vec4<f32>", "f32");

  EXPECT_EQ(silu_wgsl.find("activation_param_0"), std::string::npos)
      << "SiLU must not read an alpha uniform: " << silu_wgsl;
  EXPECT_NE(general_wgsl.find("activation_param_0"), std::string::npos)
      << "non-unit alpha must read its alpha from a uniform: " << general_wgsl;
  EXPECT_NE(silu_wgsl, general_wgsl);

  EXPECT_NE(silu.CacheKey(), general.CacheKey());
}

TEST(WebGpuActivationSnippetTest, ParameterValuesDoNotAffectTheCacheKey) {
  const Activation leaky_a = MakeActivation(ActivationKind::LeakyRelu, 0.01f);
  const Activation leaky_b = MakeActivation(ActivationKind::LeakyRelu, 0.25f);
  EXPECT_EQ(leaky_a.CacheKey(), leaky_b.CacheKey());
  EXPECT_EQ(GetActivationSnippet(leaky_a, "vec4<f32>", "f32"),
            GetActivationSnippet(leaky_b, "vec4<f32>", "f32"));

  const Activation clip_a = MakeActivation(ActivationKind::Clip, 0.0f, 6.0f);
  const Activation clip_b = MakeActivation(ActivationKind::Clip, -1.0f, 1.0f);
  EXPECT_EQ(clip_a.CacheKey(), clip_b.CacheKey());
  EXPECT_EQ(GetActivationSnippet(clip_a, "vec4<f32>", "f32"),
            GetActivationSnippet(clip_b, "vec4<f32>", "f32"));

  EXPECT_NE(MakeActivation(ActivationKind::Relu).CacheKey(),
            MakeActivation(ActivationKind::Sigmoid).CacheKey());
}

TEST(WebGpuActivationSnippetTest, ParameterlessActivationsReadNoUniforms) {
  const std::vector<ActivationKind> parameterless{
      ActivationKind::None, ActivationKind::Relu, ActivationKind::Sigmoid, ActivationKind::Tanh,
      ActivationKind::HardSwish, ActivationKind::Gelu, ActivationKind::GeluTanh,
      ActivationKind::Softplus, ActivationKind::Erf};

  for (ActivationKind kind : parameterless) {
    const Activation activation = MakeActivation(kind, 7.25f, 9.5f);
    const std::string snippet = GetActivationSnippet(activation, "vec4<f32>", "f32");
    const std::string declaration = GetActivationDeclaration(activation, "vec4<f32>", "f32");
    EXPECT_EQ(snippet.find("uniforms.activation_param"), std::string::npos)
        << "kind " << static_cast<int>(kind) << " unexpectedly reads a parameter uniform: " << snippet;
    EXPECT_EQ(declaration.find("uniforms.activation_param"), std::string::npos)
        << "kind " << static_cast<int>(kind) << " helper unexpectedly reads a parameter uniform: " << declaration;
  }
}

TEST(WebGpuActivationSnippetTest, HelperIsEmittedWheneverItIsCalled) {
  for (ActivationKind kind : AllActivationKinds()) {
    const Activation activation = MakeActivation(kind, 0.5f, 1.5f);
    const std::string snippet = GetActivationSnippet(activation, "vec4<f32>", "f32");
    const std::string declaration = GetActivationDeclaration(activation, "vec4<f32>", "f32");

    if (snippet.find("fused_act_erf") != std::string::npos) {
      EXPECT_NE(declaration.find("fn fused_act_erf"), std::string::npos)
          << "kind " << static_cast<int>(kind) << " calls fused_act_erf but declares no helper";
    }
    if (snippet.find("fused_act_tanh") != std::string::npos) {
      EXPECT_NE(declaration.find("fn fused_act_tanh"), std::string::npos)
          << "kind " << static_cast<int>(kind) << " calls fused_act_tanh but declares no helper";
    }
    if (!declaration.empty()) {
      const bool referenced = snippet.find("fused_act_erf") != std::string::npos ||
                              snippet.find("fused_act_tanh") != std::string::npos;
      EXPECT_TRUE(referenced) << "kind " << static_cast<int>(kind) << " emits an unused helper";
    }
  }
}

TEST(WebGpuActivationSnippetTest, EveryKindProducesASnippet) {
  for (ActivationKind kind : AllActivationKinds()) {
    const Activation activation = MakeActivation(kind, 0.5f, 1.5f);
    EXPECT_FALSE(GetActivationSnippet(activation, "vec4<f32>", "f32").empty())
        << "activation kind " << static_cast<int>(kind) << " produced no snippet";
  }
  EXPECT_TRUE(GetActivationSnippet(MakeActivation(ActivationKind::None), "vec4<f32>", "f32").empty());
}

static bool IsFp16NodeOnCpuWithoutKernel(const onnxruntime::Node& node,
                                         const KernelRegistryList& cpu_kernel_registries,
                                         const logging::Logger& logger) {
  if (node.GetExecutionProviderType() != kCpuExecutionProvider ||
      node.ContainsSubgraph() ||
      node.Op() == nullptr) {  // no schema, so the type constraints cannot be resolved
    return false;
  }

  const auto& input_defs = node.InputDefs();
  const auto& output_defs = node.OutputDefs();
  const auto is_fp16 = [](const NodeArg* def) { return IsMLFloat16Tensor(*def); };
  if (std::none_of(input_defs.cbegin(), input_defs.cend(), is_fp16) &&
      std::none_of(output_defs.cbegin(), output_defs.cend(), is_fp16)) {
    return false;
  }

  // Check every registry, not just the CPU EP's own one: a kernel registered through a custom registry
  // takes priority at kernel lookup time, so a node it covers is not kernel-less and must be left alone.
  const OpSchemaKernelTypeStrResolver kernel_type_str_resolver{};
  const KernelCreateInfo* kernel_create_info{};
  return std::none_of(cpu_kernel_registries.cbegin(), cpu_kernel_registries.cend(),
                      [&](const gsl::not_null<const KernelRegistry*>& registry) {
                        const auto lookup_status = registry->TryFindKernel(
                            node, kCpuExecutionProvider, kernel_type_str_resolver, logger, &kernel_create_info);
                        return lookup_status.IsOK();
                      });
}

TEST(TransformerTest, Fp16FusedNodeWithNoCpuKernelForcedToFp32) {
#if defined(DISABLE_CONTRIB_OPS)
  GTEST_SKIP() << "BiasGelu is unavailable when contrib ops are disabled.";
#endif
  auto model = std::make_shared<onnxruntime::Model>("test", false, DefaultLoggingManager().DefaultLogger());
  onnxruntime::Graph& graph = model->MainGraph();

  TypeProto tensor_float_16;
  tensor_float_16.mutable_tensor_type()->set_elem_type(TensorProto_DataType_FLOAT16);

  onnxruntime::NodeArg a_def("A", &tensor_float_16),
      b_def("B", &tensor_float_16),
      c_def("C", &tensor_float_16);

  auto& bias_gelu = graph.AddNode("bias_gelu", "BiasGelu", "fp16 fusion output with no CPU fp16 kernel",
                                  ArgMap{&a_def, &b_def}, ArgMap{&c_def}, nullptr, kMSDomain);
  // Simulate the fusion transformer assigning the fused node the CPU EP without checking for a kernel.
  bias_gelu.SetExecutionProviderType(onnxruntime::kCpuExecutionProvider);
  graph.SetOutputs({bias_gelu.OutputDefs()[0]});

  auto status = graph.Resolve();
  ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();

  InsertCastTransformer transformer("Test", DefaultCpuExecutionProvider()->GetKernelRegistry().get());

  bool modified = false;
  status = transformer.Apply(graph, modified, DefaultLoggingManager().DefaultLogger());
  ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();
  EXPECT_TRUE(modified) << "The kernel-less fp16 node should have been wrapped with fp32 casts";
  status = graph.Resolve();
  ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();

  auto is_type = [](const NodeArg& node_arg, const MLDataType type) {
    return node_arg.Type() != nullptr &&
           DataTypeImpl::TypeFromProto(*node_arg.TypeAsProto()) == type;
  };

  EXPECT_TRUE(is_type(*bias_gelu.InputDefs()[0], DataTypeImpl::GetTensorType<float>()));
  EXPECT_TRUE(is_type(*bias_gelu.InputDefs()[1], DataTypeImpl::GetTensorType<float>()));
  EXPECT_TRUE(is_type(*bias_gelu.OutputDefs()[0], DataTypeImpl::GetTensorType<float>()));
  EXPECT_EQ(bias_gelu.GetExecutionProviderType(), onnxruntime::kCpuExecutionProvider);

  // Cast A and B to fp32 on the way in, and cast the output back to fp16 for the graph output.
  auto ops = CountOpsInGraph(graph);
  EXPECT_EQ(ops["Cast"], 3);
}

TEST(TransformerTest, Fp16NodeWithCpuKernelAtGraphBoundaryNotForced) {
  auto model = std::make_shared<onnxruntime::Model>("test", false, DefaultLoggingManager().DefaultLogger());
  onnxruntime::Graph& graph = model->MainGraph();

  TypeProto tensor_float_16;
  tensor_float_16.mutable_tensor_type()->set_elem_type(TensorProto_DataType_FLOAT16);

  onnxruntime::NodeArg i1_def("I1", &tensor_float_16),
      o1_def("O1", &tensor_float_16);

  auto& round = graph.AddNode("round", "Round", "fp16 with real CPU kernel", {&i1_def}, {&o1_def});
  round.SetExecutionProviderType(onnxruntime::kCpuExecutionProvider);
  graph.SetOutputs({round.OutputDefs()[0]});

  auto status = graph.Resolve();
  ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();

  InsertCastTransformer transformer("Test", DefaultCpuExecutionProvider()->GetKernelRegistry().get());

  bool modified = false;
  status = transformer.Apply(graph, modified, DefaultLoggingManager().DefaultLogger());
  ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();
  EXPECT_FALSE(modified) << "A node with a real fp16 kernel should not be forced to fp32";
  status = graph.Resolve();
  ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();

  ASSERT_TRUE(round.InputDefs()[0]->Type() != nullptr);
  EXPECT_EQ(DataTypeImpl::TypeFromProto(*round.InputDefs()[0]->TypeAsProto()),
            DataTypeImpl::GetTensorType<MLFloat16>());
  EXPECT_EQ(round.GetExecutionProviderType(), onnxruntime::kCpuExecutionProvider);

  auto ops = CountOpsInGraph(graph);
  EXPECT_EQ(ops.find("Cast"), ops.end());
}

TEST(TransformerTest, Fp16OutputOnlyNodeWithNoCpuKernelForcedToFp32) {
  // Pin the ai.onnx opset to one where RandomNormal's schema (and therefore Node::SinceVersion())
  // resolves to version 1, matching the only CPU kernel registered for it. RandomNormal's schema was
  // later revised for a newer opset, and the CPU kernel for that revision isn't the point of this test.
  auto model = std::make_shared<onnxruntime::Model>(
      "test", false, ModelMetaData(), PathString(), IOnnxRuntimeOpSchemaRegistryList(),
      std::unordered_map<std::string, int>{{onnxruntime::kOnnxDomain, 12}},
      std::vector<ONNX_NAMESPACE::FunctionProto>(), DefaultLoggingManager().DefaultLogger());
  onnxruntime::Graph& graph = model->MainGraph();

  TypeProto tensor_float_16;
  tensor_float_16.mutable_tensor_type()->set_elem_type(TensorProto_DataType_FLOAT16);

  onnxruntime::NodeArg o1_def("O1", &tensor_float_16);

  NodeAttributes attrs = {
      {"dtype", utils::MakeAttribute("dtype", static_cast<int64_t>(TensorProto_DataType_FLOAT16))},
      {"shape", utils::MakeAttribute("shape", std::vector<int64_t>{1})}};

  auto& random_normal = graph.AddNode("random_normal", "RandomNormal", "fp16 output with no CPU fp16 kernel",
                                      ArgMap{}, ArgMap{&o1_def}, &attrs);
  // Simulate the node somehow ending up assigned to the CPU EP without a kernel check.
  random_normal.SetExecutionProviderType(onnxruntime::kCpuExecutionProvider);
  graph.SetOutputs({random_normal.OutputDefs()[0]});

  auto status = graph.Resolve();
  ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();

  InsertCastTransformer transformer("Test", DefaultCpuExecutionProvider()->GetKernelRegistry().get());

  bool modified = false;
  status = transformer.Apply(graph, modified, DefaultLoggingManager().DefaultLogger());
  ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();
  EXPECT_TRUE(modified) << "The kernel-less output-only fp16 node should have been forced to fp32";
  status = graph.Resolve();
  ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();

  auto is_type = [](const NodeArg& node_arg, const MLDataType type) {
    return node_arg.Type() != nullptr &&
           DataTypeImpl::TypeFromProto(*node_arg.TypeAsProto()) == type;
  };

  EXPECT_TRUE(is_type(*random_normal.OutputDefs()[0], DataTypeImpl::GetTensorType<float>()));
  EXPECT_EQ(random_normal.GetExecutionProviderType(), onnxruntime::kCpuExecutionProvider);

  const auto& post_attrs = random_normal.GetAttributes();
  auto dtype_attr = post_attrs.find("dtype");
  ASSERT_NE(dtype_attr, post_attrs.end());
  EXPECT_EQ(dtype_attr->second.i(), static_cast<int64_t>(TensorProto_DataType_FLOAT));

  // Cast the output back to fp16 for the graph output.
  auto ops = CountOpsInGraph(graph);
  EXPECT_EQ(ops["Cast"], 1);
}

static std::shared_ptr<KernelRegistry> MakeCustomCpuRegistry(const char* op_type, const char* domain,
                                                             MLDataType constrained_type) {
  auto kernel_def = KernelDefBuilder()
                        .SetName(op_type)
                        .SetDomain(domain)
                        .SinceVersion(1)
                        .Provider(onnxruntime::kCpuExecutionProvider)
                        .TypeConstraint("T", constrained_type)
                        .Build();

  auto registry = std::make_shared<KernelRegistry>();
  ORT_THROW_IF_ERROR(registry->Register(KernelCreateInfo(
      std::move(kernel_def),
      [](FuncManager&, const OpKernelInfo&, std::unique_ptr<OpKernel>&) -> Status {
        return ORT_MAKE_STATUS(ONNXRUNTIME, NOT_IMPLEMENTED, "kernel is only ever looked up, never created");
      })));
  return registry;
}

TEST(TransformerTest, Fp16NodeWithCustomRegistryFp16KernelNotForced) {
#if defined(DISABLE_CONTRIB_OPS)
  GTEST_SKIP() << "BiasGelu is unavailable when contrib ops are disabled.";
#endif
  // Pin both opsets the graph uses. com.microsoft must be listed explicitly: Model uses a non-empty
  // domain_to_version map verbatim, so omitting it would leave the contrib node without a schema and
  // fail Resolve. Its version is 1 and stays there, but ai.onnx is pinned for the same reason as in
  // Fp16OutputOnlyNodeWithNoCpuKernelForcedToFp32 -- so nothing here moves when main's default opset
  // does.
  auto model = std::make_shared<onnxruntime::Model>(
      "test", false, ModelMetaData(), PathString(), IOnnxRuntimeOpSchemaRegistryList(),
      std::unordered_map<std::string, int>{{onnxruntime::kOnnxDomain, 12}, {onnxruntime::kMSDomain, 1}},
      std::vector<ONNX_NAMESPACE::FunctionProto>(), DefaultLoggingManager().DefaultLogger());
  onnxruntime::Graph& graph = model->MainGraph();

  TypeProto tensor_float_16;
  tensor_float_16.mutable_tensor_type()->set_elem_type(TensorProto_DataType_FLOAT16);

  onnxruntime::NodeArg a_def("A", &tensor_float_16),
      b_def("B", &tensor_float_16),
      c_def("C", &tensor_float_16);

  auto& bias_gelu = graph.AddNode("bias_gelu", "BiasGelu", "fp16, kernel comes from a custom registry",
                                  ArgMap{&a_def, &b_def}, ArgMap{&c_def}, nullptr, kMSDomain);
  bias_gelu.SetExecutionProviderType(onnxruntime::kCpuExecutionProvider);
  graph.SetOutputs({bias_gelu.OutputDefs()[0]});

  auto status = graph.Resolve();
  ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();

  auto custom_registry = MakeCustomCpuRegistry("BiasGelu", kMSDomain, DataTypeImpl::GetTensorType<MLFloat16>());
  auto cpu_registry = DefaultCpuExecutionProvider()->GetKernelRegistry();
  // Custom registries first, matching the order GetKernelRegistriesByProviderType returns and the
  // priority SearchKernelRegistry applies when the kernel is looked up for real.
  InsertCastTransformer transformer("Test",
                                    InsertCastTransformer::KernelRegistryList{custom_registry.get(),
                                                                              cpu_registry.get()});

  bool modified = false;
  status = transformer.Apply(graph, modified, DefaultLoggingManager().DefaultLogger());
  ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();
  EXPECT_FALSE(modified) << "A node whose fp16 kernel comes from a custom registry must be left in fp16";
  status = graph.Resolve();
  ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();

  auto is_type = [](const NodeArg& node_arg, const MLDataType type) {
    return node_arg.Type() != nullptr &&
           DataTypeImpl::TypeFromProto(*node_arg.TypeAsProto()) == type;
  };

  EXPECT_TRUE(is_type(*bias_gelu.InputDefs()[0], DataTypeImpl::GetTensorType<MLFloat16>()));
  EXPECT_TRUE(is_type(*bias_gelu.InputDefs()[1], DataTypeImpl::GetTensorType<MLFloat16>()));
  EXPECT_TRUE(is_type(*bias_gelu.OutputDefs()[0], DataTypeImpl::GetTensorType<MLFloat16>()));
  EXPECT_EQ(bias_gelu.GetExecutionProviderType(), onnxruntime::kCpuExecutionProvider);

  auto ops = CountOpsInGraph(graph);
  EXPECT_EQ(ops.find("Cast"), ops.end());
}

static onnxruntime::Node& BuildFp16BiasAddGraph(onnxruntime::Graph& graph, TypeProto& tensor_float_16,
                                                std::vector<std::unique_ptr<onnxruntime::NodeArg>>& arg_storage) {
  tensor_float_16.mutable_tensor_type()->set_elem_type(TensorProto_DataType_FLOAT16);

  ArgMap inputs;
  for (const char* name : {"X", "bias", "skip"}) {
    arg_storage.push_back(std::make_unique<onnxruntime::NodeArg>(name, &tensor_float_16));
    inputs.push_back(arg_storage.back().get());
  }
  arg_storage.push_back(std::make_unique<onnxruntime::NodeArg>("Y", &tensor_float_16));

  auto& bias_add = graph.AddNode("bias_add", "BiasAdd", "fp16 with no CPU kernel at all",
                                 inputs, ArgMap{arg_storage.back().get()}, nullptr, kMSDomain);
  bias_add.SetExecutionProviderType(onnxruntime::kCpuExecutionProvider);
  graph.SetOutputs({bias_add.OutputDefs()[0]});
  return bias_add;
}

TEST(TransformerTest, Fp16NodeWithCustomRegistryFp32KernelForcedToFp32) {
#if defined(DISABLE_CONTRIB_OPS)
  GTEST_SKIP() << "BiasGelu is unavailable when contrib ops are disabled.";
#endif
  auto& logger = DefaultLoggingManager().DefaultLogger();
  auto cpu_registry = DefaultCpuExecutionProvider()->GetKernelRegistry();
  auto is_type = [](const NodeArg& node_arg, const MLDataType type) {
    return node_arg.Type() != nullptr &&
           DataTypeImpl::TypeFromProto(*node_arg.TypeAsProto()) == type;
  };

  // Both blocks below pin the two opsets the graph uses. com.microsoft must be listed explicitly:
  // Model uses a non-empty domain_to_version map verbatim, so omitting it would leave the contrib
  // node without a schema and fail Resolve. Its version is 1 and stays there, but ai.onnx is pinned
  // for the same reason as in Fp16OutputOnlyNodeWithNoCpuKernelForcedToFp32 -- so nothing here moves
  // when main's default opset does.

  // Baseline: the CPU EP registry alone has neither an fp16 nor an fp32 BiasAdd kernel, so there is
  // nothing to fall back to and the node stays as it is.
  {
    auto model = std::make_shared<onnxruntime::Model>(
        "test", false, ModelMetaData(), PathString(), IOnnxRuntimeOpSchemaRegistryList(),
        std::unordered_map<std::string, int>{{onnxruntime::kOnnxDomain, 12}, {onnxruntime::kMSDomain, 1}},
        std::vector<ONNX_NAMESPACE::FunctionProto>(), logger);
    TypeProto tensor_float_16;
    std::vector<std::unique_ptr<onnxruntime::NodeArg>> arg_storage;
    auto& bias_add = BuildFp16BiasAddGraph(model->MainGraph(), tensor_float_16, arg_storage);

    auto status = model->MainGraph().Resolve();
    ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();

    InsertCastTransformer transformer("Test", cpu_registry.get());
    bool modified = false;
    status = transformer.Apply(model->MainGraph(), modified, logger);
    ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();
    EXPECT_FALSE(modified) << "With no fp32 kernel to fall back to the node must be left untouched";
    EXPECT_TRUE(is_type(*bias_add.OutputDefs()[0], DataTypeImpl::GetTensorType<MLFloat16>()));
  }

  // With the fp32 kernel supplied by a custom registry the fallback is available and is applied.
  {
    auto model = std::make_shared<onnxruntime::Model>(
        "test", false, ModelMetaData(), PathString(), IOnnxRuntimeOpSchemaRegistryList(),
        std::unordered_map<std::string, int>{{onnxruntime::kOnnxDomain, 12}, {onnxruntime::kMSDomain, 1}},
        std::vector<ONNX_NAMESPACE::FunctionProto>(), logger);
    TypeProto tensor_float_16;
    std::vector<std::unique_ptr<onnxruntime::NodeArg>> arg_storage;
    auto& bias_add = BuildFp16BiasAddGraph(model->MainGraph(), tensor_float_16, arg_storage);

    auto status = model->MainGraph().Resolve();
    ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();

    auto custom_registry = MakeCustomCpuRegistry("BiasAdd", kMSDomain, DataTypeImpl::GetTensorType<float>());
    InsertCastTransformer transformer("Test",
                                      InsertCastTransformer::KernelRegistryList{custom_registry.get(),
                                                                                cpu_registry.get()});
    bool modified = false;
    status = transformer.Apply(model->MainGraph(), modified, logger);
    ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();
    EXPECT_TRUE(modified) << "The fp32 kernel in the custom registry makes the fp32 fallback possible";
    status = model->MainGraph().Resolve();
    ASSERT_TRUE(status.IsOK()) << status.ErrorMessage();

    for (const auto* input_def : bias_add.InputDefs()) {
      EXPECT_TRUE(is_type(*input_def, DataTypeImpl::GetTensorType<float>()));
    }
    EXPECT_TRUE(is_type(*bias_add.OutputDefs()[0], DataTypeImpl::GetTensorType<float>()));
    EXPECT_EQ(bias_add.GetExecutionProviderType(), onnxruntime::kCpuExecutionProvider);

    // Three inputs cast to fp32 on the way in, and the output cast back to fp16 for the graph output.
    auto ops = CountOpsInGraph(model->MainGraph());
    EXPECT_EQ(ops["Cast"], 4);
  }
}

PackedAttentionShape MakePackedAttentionShape(const TensorShape& shape) noexcept {
  PackedAttentionShape result;
  const auto& dimensions = shape.GetDims();
  result.rank = dimensions.size();
  const size_t dimensions_to_copy =
      dimensions.size() < result.dimensions.size() ? dimensions.size() : result.dimensions.size();
  for (size_t i = 0; i < dimensions_to_copy; ++i) {
    result.dimensions[i] = dimensions[i];
  }

  return result;
}

Status PackedAttentionWorkspaceStatusToStatus(PackedAttentionWorkspaceStatus status) {
  if (status.IsOK()) {
    return Status::OK();
  }

  return ORT_MAKE_STATUS(ONNXRUNTIME, INVALID_ARGUMENT, status.message);
}

PackedAttentionWorkspaceStatus ValidateDimension(int64_t value) noexcept {
  if (value < 0) {
    return Invalid("Packed attention dimensions must be non-negative.");
  }

  if (value > std::numeric_limits<int32_t>::max()) {
    return Invalid("Packed attention dimensions and attributes must fit the int32 CUDA ABI.");
  }

  return Ok();
}

PackedAttentionWorkspaceStatus CheckedProductFitsInt32(size_t left, size_t right) noexcept {
  size_t product = 0;
  auto status = CheckedPackedAttentionMultiply(left, right, product);
  if (!status.IsOK()) {
    return status;
  }

  if (product > static_cast<size_t>(std::numeric_limits<int32_t>::max())) {
    return Invalid("A packed attention derived product does not fit the int32 CUDA ABI.");
  }

  return Ok();
}

PackedAttentionWorkspaceStatus CheckedProductFitsInt32(size_t first, size_t second, size_t third) noexcept {
  size_t product = 0;
  auto status = CheckedPackedAttentionMultiply(first, second, product);
  if (!status.IsOK()) {
    return status;
  }

  return CheckedProductFitsInt32(product, third);
}

PackedAttentionWorkspaceStatus CheckedProductFitsInt32(size_t first, size_t second, size_t third,
                                                       size_t fourth) noexcept {
  size_t product = 0;
  auto status = CheckedPackedAttentionMultiply(first, second, product);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedPackedAttentionMultiply(product, third, product);
  if (!status.IsOK()) {
    return status;
  }

  return CheckedProductFitsInt32(product, fourth);
}

PackedAttentionWorkspaceStatus ValidateElementSize(size_t element_size) noexcept {
  if (element_size != 2 && element_size != 4) {
    return Invalid("Packed attention element size must be 2 or 4 bytes.");
  }

  return Ok();
}

PackedAttentionWorkspaceStatus ValidateShape(const PackedAttentionShape& shape, size_t expected_rank) noexcept {
  if (shape.rank != expected_rank || shape.rank > shape.dimensions.size()) {
    return Invalid("A packed attention input has an invalid rank.");
  }

  for (size_t i = 0; i < shape.rank; ++i) {
    auto status = ValidateDimension(shape.dimensions[i]);
    if (!status.IsOK()) {
      return status;
    }
  }

  return Ok();
}

PackedAttentionWorkspaceStatus ValidateAttentionBias(const PackedAttentionShape& shape,
                                                     int64_t batch_size,
                                                     int64_t num_heads,
                                                     int64_t sequence_length) noexcept {
  if (shape.rank != 4 || shape.rank > shape.dimensions.size()) {
    return Invalid("Attention bias must have rank 4.");
  }

  for (size_t i = 0; i < shape.rank; ++i) {
    auto status = ValidateDimension(shape.dimensions[i]);
    if (!status.IsOK()) {
      return status;
    }
  }

  if ((shape.dimensions[0] != 1 && shape.dimensions[0] != batch_size) ||
      (shape.dimensions[1] != 1 && shape.dimensions[1] != num_heads) ||
      shape.dimensions[2] != sequence_length ||
      shape.dimensions[3] != sequence_length) {
    return Invalid("Attention bias must have shape [B or 1, N or 1, S, S].");
  }

  return Ok();
}

PackedAttentionWorkspaceStatus ValidateCoreGeometry(int32_t token_count,
                                                    int32_t batch_size,
                                                    int32_t sequence_length,
                                                    int32_t num_heads,
                                                    int32_t hidden_size,
                                                    int32_t v_hidden_size,
                                                    int32_t qk_head_size,
                                                    int32_t v_head_size) noexcept {
  if (token_count < 0 || batch_size < 0 || sequence_length < 0 ||
      num_heads <= 0 || hidden_size < 0 || v_hidden_size < 0 ||
      qk_head_size < 0 || v_head_size < 0) {
    return Invalid("Packed attention problem dimensions are invalid.");
  }

  const size_t t = static_cast<size_t>(token_count);
  const size_t b = static_cast<size_t>(batch_size);
  const size_t s = static_cast<size_t>(sequence_length);
  const size_t n = static_cast<size_t>(num_heads);
  const size_t h = static_cast<size_t>(qk_head_size);
  const size_t hv = static_cast<size_t>(v_head_size);

  size_t q_hidden = 0;
  auto status = CheckedPackedAttentionMultiply(n, h, q_hidden);
  if (!status.IsOK()) {
    return status;
  }

  size_t v_hidden = 0;
  status = CheckedPackedAttentionMultiply(n, hv, v_hidden);
  if (!status.IsOK()) {
    return status;
  }

  if (q_hidden != static_cast<size_t>(hidden_size) ||
      v_hidden != static_cast<size_t>(v_hidden_size)) {
    return Invalid("Packed attention hidden sizes do not match the head geometry.");
  }

  size_t padded_tokens = 0;
  status = CheckedPackedAttentionMultiply(b, s, padded_tokens);
  if (!status.IsOK()) {
    return status;
  }

  if (t > padded_tokens) {
    return Invalid("Packed attention token count T must not exceed B * S.");
  }

  return Ok();
}

PackedAttentionWorkspaceStatus ValidateQkvMaterializationGeometry(int32_t token_count,
                                                                  int32_t num_heads,
                                                                  int32_t qk_head_size,
                                                                  int32_t v_head_size,
                                                                  PackedAttentionQkvMaterializationIndexWidth
                                                                      index_width) noexcept {
  const size_t t = static_cast<size_t>(token_count);
  const size_t n = static_cast<size_t>(num_heads);
  const int32_t width = static_cast<int32_t>(index_width);
  if (width != 1 && width != 2 && width != 4) {
    return Invalid("Packed attention QKV materialization index width is invalid.");
  }

  if (qk_head_size % width != 0 || v_head_size % width != 0) {
    return Invalid("Packed attention head geometry is not divisible by the QKV materialization index width.");
  }

  const size_t h = static_cast<size_t>(qk_head_size / width);
  const size_t hv = static_cast<size_t>(v_head_size / width);

  size_t qkv_head_size = 0;
  auto status = CheckedPackedAttentionAdd(h, h, qkv_head_size);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedPackedAttentionAdd(qkv_head_size, hv, qkv_head_size);
  if (!status.IsOK()) {
    return status;
  }

  // The packed transpose producers use int32 offsets in scalar, T2, or T4
  // elements according to the producer selected by the graph adapter.
  status = CheckedProductFitsInt32(n, qkv_head_size);
  if (!status.IsOK()) {
    return status;
  }

  return CheckedProductFitsInt32(t, n, qkv_head_size);
}

PackedAttentionWorkspaceStatus ValidateUnfusedGeometry(int32_t token_count,
                                                       int32_t batch_size,
                                                       int32_t sequence_length,
                                                       int32_t num_heads,
                                                       int32_t qk_head_size,
                                                       int32_t v_head_size,
                                                       PackedAttentionQkvMaterializationIndexWidth
                                                           index_width) noexcept {
  constexpr int32_t kMaxGridDimY = 65535;
  if (batch_size > kMaxGridDimY) {
    return Invalid("Packed unfused attention batch size exceeds CUDA gridDim.y.");
  }

  const size_t t = static_cast<size_t>(token_count);
  const size_t b = static_cast<size_t>(batch_size);
  const size_t s = static_cast<size_t>(sequence_length);
  const size_t n = static_cast<size_t>(num_heads);
  const size_t h = static_cast<size_t>(qk_head_size);
  const size_t hv = static_cast<size_t>(v_head_size);
  const int32_t width = static_cast<int32_t>(index_width);
  if ((width != 1 && width != 2 && width != 4) ||
      qk_head_size % width != 0 || v_head_size % width != 0) {
    return Invalid("Packed attention QKV materialization index width is invalid.");
  }

  const size_t producer_h = static_cast<size_t>(qk_head_size / width);
  const size_t producer_hv = static_cast<size_t>(v_head_size / width);

  auto status = CheckedProductFitsInt32(b, s);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedProductFitsInt32(s, s);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedProductFitsInt32(b, n);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedProductFitsInt32(b, n, s);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedProductFitsInt32(s, h);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedProductFitsInt32(s, hv);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedProductFitsInt32(b, n, s, producer_h);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedProductFitsInt32(b, n, s, producer_hv);
  if (!status.IsOK()) {
    return status;
  }

  size_t qkv_head_size = 0;
  status = CheckedPackedAttentionAdd(producer_h, producer_h, qkv_head_size);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedPackedAttentionAdd(qkv_head_size, producer_hv, qkv_head_size);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedProductFitsInt32(t, n, qkv_head_size);
  if (!status.IsOK()) {
    return status;
  }

  return CheckedProductFitsInt32(b, s, n, qkv_head_size);
}

PackedAttentionWorkspaceStatus CheckedProductFitsInt64(size_t first, size_t second,
                                                       size_t third) noexcept {
  size_t product = 0;
  auto status = CheckedPackedAttentionMultiply(first, second, product);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedPackedAttentionMultiply(product, third, product);
  if (!status.IsOK()) {
    return status;
  }

  if (product > static_cast<size_t>(std::numeric_limits<int64_t>::max())) {
    return Invalid("A packed attention stride or extent does not fit int64.");
  }

  return Ok();
}

PackedAttentionWorkspaceStatus ValidateFusedGrid(int32_t batch_size, int32_t num_heads,
                                                 const char* backend_name) noexcept {
  constexpr int32_t kMaxGridDimYZ = 65535;
  if (batch_size > kMaxGridDimYZ || num_heads > kMaxGridDimYZ) {
    return Invalid(backend_name);
  }

  return Ok();
}

PackedAttentionWorkspaceStatus ValidateRoundedInt32Dimension(int32_t value,
                                                             int32_t alignment,
                                                             const char* message) noexcept {
  if (value > std::numeric_limits<int32_t>::max() - (alignment - 1)) {
    return Invalid(message);
  }

  return Ok();
}

PackedAttentionWorkspaceStatus ValidateMemoryEfficientGeometry(
    size_t element_size,
    int32_t batch_size,
    int32_t sequence_length,
    int32_t num_heads,
    int32_t qk_head_size,
    int32_t v_head_size,
    bool has_attention_bias,
    bool broadcast_attn_bias_dim_0,
    bool broadcast_attn_bias_dim_1) noexcept {
  auto status = ValidateFusedGrid(
      batch_size, num_heads,
      "Packed memory-efficient attention exceeds CUDA gridDim.y or gridDim.z.");
  if (!status.IsOK()) {
    return status;
  }

  // DispatchBlockSize in fmha_launch_template.h selects at most 64
  // AttentionKernel::kQueriesPerBlock, and AttentionKernel::kAlignLSE is 32.
  // Validate both ceil_div round-ups before either CUDA int32 expression is formed.
  constexpr int32_t kMaxQueriesPerBlock = 64;
  constexpr int32_t kAlignLse = 32;
  status = ValidateRoundedInt32Dimension(
      sequence_length, kMaxQueriesPerBlock,
      "Packed memory-efficient attention query-block rounding exceeds int32.");
  if (!status.IsOK()) {
    return status;
  }

  status = ValidateRoundedInt32Dimension(
      sequence_length, kAlignLse,
      "Packed memory-efficient attention LSE rounding exceeds int32.");
  if (!status.IsOK()) {
    return status;
  }

  const size_t b = static_cast<size_t>(batch_size);
  const size_t s = static_cast<size_t>(sequence_length);
  const size_t n = static_cast<size_t>(num_heads);
  const size_t h = static_cast<size_t>(qk_head_size);
  const size_t hv = static_cast<size_t>(v_head_size);

  // CUTLASS stores BSNH batch strides in int64_t.
  status = CheckedProductFitsInt64(n, h, s);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedProductFitsInt64(n, hv, s);
  if (!status.IsOK()) {
    return status;
  }

  if (!has_attention_bias) {
    return Ok();
  }

  size_t bias_matrix_elements = 0;
  status = CheckedPackedAttentionMultiply(s, s, bias_matrix_elements);
  if (!status.IsOK() ||
      bias_matrix_elements > static_cast<size_t>(std::numeric_limits<int64_t>::max())) {
    return status.IsOK() ? Invalid("The MEA attention-bias head stride does not fit int64.") : status;
  }

  const size_t bias_heads = broadcast_attn_bias_dim_1 ? 1 : n;
  size_t bias_batch_stride = 0;
  status = CheckedPackedAttentionMultiply(bias_heads, bias_matrix_elements, bias_batch_stride);
  if (!status.IsOK() ||
      bias_batch_stride > static_cast<size_t>(std::numeric_limits<int64_t>::max())) {
    return status.IsOK() ? Invalid("The MEA attention-bias batch stride does not fit int64.") : status;
  }

  const size_t bias_batches = broadcast_attn_bias_dim_0 ? 1 : b;
  size_t bias_extent = 0;
  status = CheckedPackedAttentionMultiply(bias_batches, bias_batch_stride, bias_extent);
  if (!status.IsOK() ||
      bias_extent > static_cast<size_t>(std::numeric_limits<int64_t>::max())) {
    return status.IsOK() ? Invalid("The MEA attention-bias extent does not fit int64.") : status;
  }

  size_t bias_bytes = 0;
  return CheckedPackedAttentionMultiply(bias_extent, element_size, bias_bytes);
}

PackedAttentionWorkspaceStatus CheckedMultiplyMany(size_t first, size_t second, size_t third,
                                                   size_t fourth, size_t fifth,
                                                   size_t& result) noexcept {
  auto status = CheckedPackedAttentionMultiply(first, second, result);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedPackedAttentionMultiply(result, third, result);
  if (!status.IsOK()) {
    return status;
  }

  status = CheckedPackedAttentionMultiply(result, fourth, result);
  if (!status.IsOK()) {
    return status;
  }

  return CheckedPackedAttentionMultiply(result, fifth, result);
}

PackedAttentionWorkspaceStatus CheckedPackedAttentionAdd(size_t left, size_t right, size_t& result) noexcept {
  // Keep these helpers non-throwing for the provider/plugin boundary. SafeInt<T>
  // construction is intentionally avoided because it reports overflow by throwing.
  size_t checked_result = 0;
  if (!SafeAdd(left, right, checked_result)) {
    return Overflow("Packed attention size addition overflowed size_t.");
  }

  result = checked_result;
  return Ok();
}

PackedAttentionWorkspaceStatus CheckedPackedAttentionMultiply(size_t left, size_t right,
                                                              size_t& result) noexcept {
  size_t checked_result = 0;
  if (!SafeMultiply(left, right, checked_result)) {
    return Overflow("Packed attention size multiplication overflowed size_t.");
  }

  result = checked_result;
  return Ok();
}

PackedAttentionWorkspaceStatus CheckedPackedAttentionAlign(size_t value, size_t alignment,
                                                           size_t& result) noexcept {
  if (alignment == 0) {
    return Invalid("Packed attention alignment must be non-zero.");
  }

  size_t numerator = 0;
  auto status = CheckedPackedAttentionAdd(value, alignment - 1, numerator);
  if (!status.IsOK()) {
    return status;
  }

  const size_t quotient = numerator / alignment;
  return CheckedPackedAttentionMultiply(quotient, alignment, result);
}

PackedAttentionWorkspaceStatus ValidatePackedAttentionWorkspaceRecipe(
    const PackedAttentionWorkspaceRecipe& recipe) noexcept {
  const auto validate_range = [&recipe](size_t offset, size_t bytes) {
    size_t end = 0;
    auto status = CheckedPackedAttentionAdd(offset, bytes, end);
    if (!status.IsOK()) {
      return status;
    }

    return end <= recipe.attention_workspace_bytes
               ? Ok()
               : Invalid("A packed attention workspace view exceeds its allocation.");
  };

  if (recipe.qkv_capacity_bytes > recipe.attention_workspace_bytes) {
    return Invalid("Packed attention QKV capacity exceeds its allocation.");
  }

  PackedAttentionWorkspaceStatus status;
  switch (recipe.qkv_layout) {
    case PackedAttentionQkvWorkspaceLayout::None:
      if (!recipe.no_qkv_workspace ||
          recipe.q_offset_bytes != 0 || recipe.q_bytes != 0 ||
          recipe.k_offset_bytes != 0 || recipe.k_bytes != 0 ||
          recipe.v_offset_bytes != 0 || recipe.v_bytes != 0 ||
          recipe.interleaved_qkv_offset_bytes != 0 || recipe.interleaved_qkv_bytes != 0) {
        return Invalid("A no-QKV-workspace recipe exposes QKV workspace views.");
      }
      break;
    case PackedAttentionQkvWorkspaceLayout::Planar:
      if (recipe.no_qkv_workspace ||
          recipe.interleaved_qkv_offset_bytes != 0 || recipe.interleaved_qkv_bytes != 0) {
        return Invalid("A planar QKV recipe has inconsistent layout fields.");
      }
      status = validate_range(recipe.q_offset_bytes, recipe.q_bytes);
      if (!status.IsOK()) {
        return status;
      }
      status = validate_range(recipe.k_offset_bytes, recipe.k_bytes);
      if (!status.IsOK()) {
        return status;
      }
      status = validate_range(recipe.v_offset_bytes, recipe.v_bytes);
      if (!status.IsOK()) {
        return status;
      }
      break;
    case PackedAttentionQkvWorkspaceLayout::InterleavedTn3h:
      if (recipe.no_qkv_workspace ||
          recipe.q_offset_bytes != 0 || recipe.q_bytes != 0 ||
          recipe.k_offset_bytes != 0 || recipe.k_bytes != 0 ||
          recipe.v_offset_bytes != 0 || recipe.v_bytes != 0) {
        return Invalid("An interleaved QKV recipe exposes planar Q/K/V views.");
      }
      status = validate_range(recipe.interleaved_qkv_offset_bytes, recipe.interleaved_qkv_bytes);
      if (!status.IsOK()) {
        return status;
      }
      break;
    default:
      return Invalid("Packed attention QKV workspace layout is invalid.");
  }

  status = validate_range(recipe.backend_workspace_offset_bytes, recipe.backend_workspace_bytes);
  if (!status.IsOK()) {
    return status;
  }

  if (recipe.has_second_scratch) {
    status = validate_range(recipe.second_scratch_offset_bytes, recipe.backend_workspace_bytes);
    if (!status.IsOK()) {
      return status;
    }
  } else if (recipe.second_scratch_offset_bytes != 0) {
    return Invalid("A packed attention recipe without a second scratch region has a second-scratch offset.");
  }

  return Ok();
}

PackedAttentionWorkspaceResult GetPackedAttentionWorkspaceRecipe(
    const PackedAttentionProblem& problem) noexcept {
  PackedAttentionWorkspaceResult result;

  auto status = ValidateElementSize(problem.element_size);
  if (!status.IsOK()) {
    result.status = status;
    return result;
  }

  status = ValidateCoreGeometry(problem.token_count, problem.batch_size, problem.sequence_length,
                                problem.num_heads, problem.hidden_size, problem.v_hidden_size,
                                problem.qk_head_size, problem.v_head_size);
  if (!status.IsOK()) {
    result.status = status;
    return result;
  }

  if (problem.input_hidden_size < 0) {
    result.status = Invalid("PackedAttention input hidden size must be non-negative.");
    return result;
  }

  if (problem.backend == PackedAttentionBackend::Flash) {
    result.status = Invalid("PackedAttention does not have a Flash Attention route.");
    return result;
  }

  if (problem.backend == PackedAttentionBackend::Trt) {
    if (!problem.trt_runner_available) {
      result.status = Invalid("TRT workspace sizing requires an existing validated runner.");
      return result;
    }

    if (problem.qk_head_size != problem.v_head_size) {
      result.status = Invalid("The packed TRT route requires equal Q/K and V head sizes.");
      return result;
    }
  }

  PackedAttentionWorkspaceRecipe recipe;
  status = ComputeWorkspaceRecipe(problem.element_size, problem.token_count, problem.batch_size,
                                  problem.sequence_length, problem.num_heads, problem.qk_head_size,
                                  problem.v_head_size, problem.has_attention_bias,
                                  problem.broadcast_attn_bias_dim_0, problem.broadcast_attn_bias_dim_1,
                                  problem.backend, false, problem.qkv_materialization_index_width, recipe);
  if (!status.IsOK()) {
    result.status = status;
    return result;
  }

  size_t projection_n = 0;
  status = CheckedPackedAttentionAdd(static_cast<size_t>(problem.hidden_size),
                                     static_cast<size_t>(problem.hidden_size), projection_n);
  if (!status.IsOK()) {
    result.status = status;
    return result;
  }

  status = CheckedPackedAttentionAdd(projection_n, static_cast<size_t>(problem.v_hidden_size),
                                     projection_n);
  if (!status.IsOK() ||
      projection_n > static_cast<size_t>(std::numeric_limits<int32_t>::max())) {
    result.status = Invalid("PackedAttention projection n does not fit the int32 GEMM ABI.");
    return result;
  }

  size_t projection_elements = 0;
  status = CheckedPackedAttentionMultiply(static_cast<size_t>(problem.token_count), projection_n,
                                          projection_elements);
  if (!status.IsOK()) {
    result.status = status;
    return result;
  }

  status = CheckedPackedAttentionMultiply(projection_elements, problem.element_size,
                                          recipe.projection_bytes);
  if (!status.IsOK()) {
    result.status = status;
    return result;
  }

  recipe.projection_m = problem.token_count;
  recipe.projection_n = static_cast<int32_t>(projection_n);
  recipe.projection_k = problem.input_hidden_size;

  result.recipe = recipe;
  result.status = Ok();
  return result;
}

PackedAttentionWorkspaceResult GetPackedMultiHeadAttentionWorkspaceRecipe(
    const PackedMultiHeadAttentionProblem& problem) noexcept {
  PackedAttentionWorkspaceResult result;

  auto status = ValidateElementSize(problem.element_size);
  if (!status.IsOK()) {
    result.status = status;
    return result;
  }

  if (problem.qkv_format != PackedMultiHeadAttentionQkvFormat::Packed &&
      problem.qkv_format != PackedMultiHeadAttentionQkvFormat::Separate) {
    result.status = Invalid("PackedMultiHeadAttention QKV format is invalid.");
    return result;
  }

  status = ValidateCoreGeometry(problem.token_count, problem.batch_size, problem.sequence_length,
                                problem.num_heads, problem.hidden_size, problem.v_hidden_size,
                                problem.qk_head_size, problem.v_head_size);
  if (!status.IsOK()) {
    result.status = status;
    return result;
  }

  if (problem.backend == PackedAttentionBackend::Trt) {
    if (!problem.trt_runner_available) {
      result.status = Invalid("TRT workspace sizing requires an existing validated runner.");
      return result;
    }

    if (problem.qk_head_size != problem.v_head_size) {
      result.status = Invalid("The packed TRT route requires equal Q/K and V head sizes.");
      return result;
    }
  }

  if (problem.backend == PackedAttentionBackend::Flash) {
    if (problem.qk_head_size != problem.v_head_size || problem.has_attention_bias) {
      result.status = Invalid("The packed Flash route requires equal head sizes and no attention bias.");
      return result;
    }
  }

  const bool no_qkv_workspace =
      (problem.backend == PackedAttentionBackend::Trt &&
       problem.qkv_format == PackedMultiHeadAttentionQkvFormat::Packed &&
       !problem.has_bias) ||
      ((problem.backend == PackedAttentionBackend::Flash ||
        problem.backend == PackedAttentionBackend::MemoryEfficient) &&
       problem.qkv_format == PackedMultiHeadAttentionQkvFormat::Separate &&
       !problem.has_bias);

  PackedAttentionWorkspaceRecipe recipe;
  status = ComputeWorkspaceRecipe(problem.element_size, problem.token_count, problem.batch_size,
                                  problem.sequence_length, problem.num_heads, problem.qk_head_size,
                                  problem.v_head_size, problem.has_attention_bias,
                                  problem.broadcast_attn_bias_dim_0, problem.broadcast_attn_bias_dim_1,
                                  problem.backend, no_qkv_workspace,
                                  problem.qkv_materialization_index_width, recipe);
  if (!status.IsOK()) {
    result.status = status;
    return result;
  }

  result.recipe = recipe;
  result.status = Ok();
  return result;
}

