REGISTER_KERNEL_TYPED

namespace {

// output = x + round_to_T(y * gate). For MLFloat16 the product is rounded to half before the
// add, matching separate ONNX Mul and Add operators.
template <typename T>
inline T GatedAddValue(T x, T y, T gate) {
  if constexpr (std::is_same_v<T, MLFloat16>) {
    const T product(y.ToFloat() * gate.ToFloat());
    return T(x.ToFloat() + product.ToFloat());
  } else {
    return x + y * gate;
  }
}

}

inline T GatedAddValue(T x, T y, T gate) {
  if constexpr (std::is_same_v<T, MLFloat16>) {
    const T product(y.ToFloat() * gate.ToFloat());
    return T(x.ToFloat() + product.ToFloat());
  } else {
    return x + y * gate;
  }
}

Status GatedAdd<T>::Compute(OpKernelContext* context) const {
  const Tensor* x = context->Input<Tensor>(0);
  const Tensor* y = context->Input<Tensor>(1);
  const Tensor* gate = context->Input<Tensor>(2);
  const TensorShape& shape = x->Shape();

  ORT_RETURN_IF_NOT(shape.NumDimensions() >= 1, "X must have rank >= 1");
  ORT_RETURN_IF_NOT(y->Shape() == shape, "Y must have the same shape as X");
  ORT_RETURN_IF_NOT(gate->Shape().NumDimensions() == shape.NumDimensions(),
                    "gate must have the same rank as X");

  const size_t last_axis = shape.NumDimensions() - 1;
  const int64_t hidden_size = shape[last_axis];
  ORT_RETURN_IF_NOT(hidden_size > 0, "X last dimension must be positive");
  ORT_RETURN_IF_NOT(gate->Shape()[last_axis] == 1, "gate last dimension must be 1");
  for (size_t axis = 0; axis < last_axis; ++axis) {
    ORT_RETURN_IF_NOT(gate->Shape()[axis] == shape[axis],
                      "gate dimension ", axis, " must match X");
  }

  Tensor* output = context->Output(0, shape);
  const int64_t count = shape.Size();
  if (count == 0) {
    return Status::OK();
  }

  const T* x_data = x->Data<T>();
  const T* y_data = y->Data<T>();
  const T* gate_data = gate->Data<T>();
  T* output_data = output->MutableData<T>();
  const int64_t num_rows = count / hidden_size;

  concurrency::ThreadPool::TryBatchParallelFor(
      context->GetOperatorThreadPool(), onnxruntime::narrow<ptrdiff_t>(num_rows),
      [&](ptrdiff_t row) {
        const int64_t offset = row * hidden_size;
        const T gate_value = gate_data[row];
        for (int64_t i = 0; i < hidden_size; ++i) {
          output_data[offset + i] = GatedAddValue<T>(x_data[offset + i], y_data[offset + i], gate_value);
        }
      },
      0);

  return Status::OK();
}

REGISTER_KERNEL_TYPED

namespace {

inline float SigmoidFloat(float value) {
  float output;
  MlasComputeLogistic(&value, &output, 1);
  return output;
}

inline float SoftplusFloat(float value) {
  return value > 0.0f ? value + std::log(std::exp(-value) + 1.0f) : std::log(std::exp(value) + 1.0f);
}

}

inline float SigmoidFloat(float value) {
  float output;
  MlasComputeLogistic(&value, &output, 1);
  return output;
}

Status LinearAttentionGate<T>::Compute(OpKernelContext* context) const {
  const Tensor* a = context->Input<Tensor>(0);
  const Tensor* dt_bias = context->Input<Tensor>(1);
  const Tensor* decay_scale = context->Input<Tensor>(2);
  const Tensor* b = context->Input<Tensor>(3);  // optional

  const auto& a_shape = a->Shape();
  ORT_RETURN_IF_NOT(a_shape.NumDimensions() >= 1, "a must have rank >= 1");
  const int64_t num_heads = a_shape[a_shape.NumDimensions() - 1];
  ORT_RETURN_IF_NOT(num_heads > 0, "a last dimension must be positive");

  ORT_RETURN_IF_NOT(dt_bias->Shape().Size() == num_heads,
                    "dt_bias must have ", num_heads, " elements, got ", dt_bias->Shape().Size());
  ORT_RETURN_IF_NOT(decay_scale->Shape().Size() == num_heads,
                    "decay_scale must have ", num_heads, " elements, got ", decay_scale->Shape().Size());

  Tensor* decay = context->Output(0, a_shape);
  Tensor* beta = context->Output(1, a_shape);

  if (beta != nullptr) {
    ORT_RETURN_IF_NOT(b != nullptr, "The b input is required when the beta output is requested");
    ORT_RETURN_IF_NOT(b->Shape() == a_shape, "b must have the same shape as a");
  }

  const int64_t count = a_shape.Size();
  if (count == 0) {
    return Status::OK();
  }

  const T* a_data = a->Data<T>();
  const T* b_data = b == nullptr ? nullptr : b->Data<T>();
  const float* dt_bias_data = dt_bias->Data<float>();
  const float* decay_scale_data = decay_scale->Data<float>();
  T* decay_data = decay->MutableData<T>();
  T* beta_data = beta == nullptr ? nullptr : beta->MutableData<T>();

  const int64_t num_tokens = count / num_heads;

  concurrency::ThreadPool::TryBatchParallelFor(
      context->GetOperatorThreadPool(), onnxruntime::narrow<ptrdiff_t>(num_tokens),
      [&](ptrdiff_t token) {
        const int64_t offset = token * num_heads;
        for (int64_t h = 0; h < num_heads; ++h) {
          const int64_t idx = offset + h;
          const float biased = static_cast<float>(a_data[idx]) + dt_bias_data[h];
          decay_data[idx] = static_cast<T>(decay_scale_data[h] * SoftplusFloat(biased));
          if (beta_data != nullptr) {
            beta_data[idx] = static_cast<T>(SigmoidFloat(static_cast<float>(b_data[idx])));
          }
        }
      },
      0);

  return Status::OK();
}

Status GatedRMSNorm<T>::Compute(OpKernelContext* context) const {
  const Tensor* input = context->Input<Tensor>(0);
  const Tensor* scale = context->Input<Tensor>(1);
  const Tensor* gate = context->Input<Tensor>(2);

  const auto& shape = input->Shape();
  ORT_RETURN_IF_NOT(shape.NumDimensions() >= 1, "X must have rank >= 1");
  ORT_RETURN_IF_NOT(gate->Shape() == shape, "gate must have the same shape as X");

  const int64_t norm_size = scale->Shape().Size();
  ORT_RETURN_IF_NOT(norm_size > 0, "scale must not be empty");
  const int64_t last_dim = shape[shape.NumDimensions() - 1];
  ORT_RETURN_IF_NOT(last_dim % norm_size == 0,
                    "X last dimension (", last_dim, ") must be a multiple of the scale length (",
                    norm_size, ")");

  Tensor* output = context->Output(0, shape);
  const int64_t count = shape.Size();
  if (count == 0) {
    return Status::OK();
  }
  const int64_t num_rows = count / norm_size;

  const T* input_data = input->Data<T>();
  const T* scale_data = scale->Data<T>();
  const T* gate_data = gate->Data<T>();
  T* output_data = output->MutableData<T>();

  concurrency::ThreadPool::TryBatchParallelFor(
      context->GetOperatorThreadPool(), onnxruntime::narrow<ptrdiff_t>(num_rows),
      [&](ptrdiff_t row) {
        const int64_t offset = row * norm_size;
        float sum_sq = 0.0f;
        for (int64_t i = 0; i < norm_size; ++i) {
          const float v = static_cast<float>(input_data[offset + i]);
          sum_sq += v * v;
        }
        const float inv_rms = 1.0f / std::sqrt(sum_sq / static_cast<float>(norm_size) + epsilon_);
        for (int64_t i = 0; i < norm_size; ++i) {
          const float z = static_cast<float>(gate_data[offset + i]);
          const float normalized = static_cast<float>(input_data[offset + i]) * inv_rms *
                                   static_cast<float>(scale_data[i]);
          output_data[offset + i] = static_cast<T>(normalized * (z * SigmoidFloat(z)));
        }
      },
      0);

  return Status::OK();
}

Status GatedAddProgram::GenerateShaderCode(ShaderHelper& shader) const {
  const auto& x = shader.AddInput("x", ShaderUsage::UseUniform);
  const auto& y = shader.AddInput("y", ShaderUsage::UseUniform);
  const auto& gate = shader.AddInput("gate", ShaderUsage::UseUniform);
  const auto& output = shader.AddOutput("output", ShaderUsage::UseUniform);

  shader.MainFunctionBody() << shader.GuardAgainstOutOfBoundsWorkgroupSizes("uniforms.output_size")
                            << "  let gate_idx = global_idx / uniforms.hidden_size;\n"
                            << "  let gate_value = " << gate.GetByOffset("gate_idx") << ";\n"
                            << "  let value = " << x.GetByOffset("global_idx")
                            << " + (" << y.GetByOffset("global_idx") << " * gate_value);\n"
                            << "  " << output.SetByOffset("global_idx", "value");

  return Status::OK();
}

Status GatedAdd::ComputeInternal(ComputeContext& context) const {
  const auto* x = context.Input(0);
  const auto* y = context.Input(1);
  const auto* gate = context.Input(2);
  const TensorShape& shape = x->Shape();

  ORT_RETURN_IF_NOT(shape.NumDimensions() >= 1, "X must have rank >= 1");
  ORT_RETURN_IF_NOT(y->Shape() == shape, "Y must have the same shape as X");
  ORT_RETURN_IF_NOT(gate->Shape().NumDimensions() == shape.NumDimensions(),
                    "gate must have the same rank as X");

  const size_t last_axis = shape.NumDimensions() - 1;
  const int64_t hidden_size = shape[last_axis];
  ORT_RETURN_IF_NOT(hidden_size > 0, "X last dimension must be positive");
  ORT_RETURN_IF_NOT(gate->Shape()[last_axis] == 1, "gate last dimension must be 1");
  for (size_t axis = 0; axis < last_axis; ++axis) {
    ORT_RETURN_IF_NOT(gate->Shape()[axis] == shape[axis],
                      "gate dimension ", axis, " must match X");
  }

  auto* output = context.Output(0, shape);
  const int64_t output_size = shape.Size();
  if (output_size == 0) {
    return Status::OK();
  }

  GatedAddProgram program{};
  program.AddInputs({{x, ProgramTensorMetadataDependency::Type},
                     {y, ProgramTensorMetadataDependency::Type},
                     {gate, ProgramTensorMetadataDependency::Type}})
      .AddOutput({output, ProgramTensorMetadataDependency::None})
      .SetDispatchGroupSize((onnxruntime::narrow<uint32_t>(output_size) + WORKGROUP_SIZE - 1) / WORKGROUP_SIZE)
      .AddUniformVariables({{onnxruntime::narrow<uint32_t>(output_size)},
                            {onnxruntime::narrow<uint32_t>(hidden_size)}});
  return context.RunProgram(program);
}

Status LinearAttentionGateProgram::GenerateShaderCode(ShaderHelper& shader) const {
  const auto& a = shader.AddInput("a", ShaderUsage::UseUniform | ShaderUsage::UseElementTypeAlias);
  const auto& dt_bias = shader.AddInput("dt_bias", ShaderUsage::UseUniform);
  const auto& decay_scale = shader.AddInput("decay_scale", ShaderUsage::UseUniform);
  const ShaderVariableHelper* b = nullptr;
  if (has_b_) {
    b = &shader.AddInput("b", ShaderUsage::UseUniform | ShaderUsage::UseElementTypeAlias);
  }
  const auto& decay = shader.AddOutput("decay", ShaderUsage::UseUniform | ShaderUsage::UseElementTypeAlias);
  const ShaderVariableHelper* beta = nullptr;
  if (has_beta_) {
    beta = &shader.AddOutput("beta", ShaderUsage::UseUniform | ShaderUsage::UseElementTypeAlias);
  }

  shader.AdditionalImplementation()
      << "fn la_softplus(x: f32) -> f32 {\n"
      << "  if (x > 0.0) {\n"
      << "    return x + log(exp(-x) + 1.0);\n"
      << "  }\n"
      << "  return log(exp(x) + 1.0);\n"
      << "}\n"
      << "fn la_sigmoid(x: f32) -> f32 {\n"
      << "  if (x > 0.0) {\n"
      << "    return 1.0 / (1.0 + exp(-x));\n"
      << "  }\n"
      << "  let e = exp(x);\n"
      << "  return e / (1.0 + e);\n"
      << "}\n";

  shader.MainFunctionBody() << shader.GuardAgainstOutOfBoundsWorkgroupSizes("uniforms.output_size")
                            << "  let h = global_idx % uniforms.num_heads;\n"
                            << "  let biased = f32(" << a.GetByOffset("global_idx") << ") + f32("
                            << dt_bias.GetByOffset("h") << ");\n"
                            << "  " << decay.SetByOffset("global_idx", "decay_element_t(f32(" + decay_scale.GetByOffset("h") + ") * la_softplus(biased))")
                            << "\n";
  if (has_beta_) {
    shader.MainFunctionBody() << "  "
                              << beta->SetByOffset("global_idx",
                                                   "beta_element_t(la_sigmoid(f32(" + b->GetByOffset("global_idx") + ")))")
                              << "\n";
  }

  return Status::OK();
}

Status LinearAttentionGate::ComputeInternal(ComputeContext& context) const {
  const auto* a = context.Input(0);
  const auto* dt_bias = context.Input(1);
  const auto* decay_scale = context.Input(2);
  const auto* b = context.Input(3);  // optional

  const auto& a_shape = a->Shape();
  ORT_RETURN_IF_NOT(a_shape.NumDimensions() >= 1, "a must have rank >= 1");
  const int64_t num_heads = a_shape[a_shape.NumDimensions() - 1];
  ORT_RETURN_IF_NOT(num_heads > 0, "a last dimension must be positive");

  ORT_RETURN_IF_NOT(dt_bias->Shape().Size() == num_heads,
                    "dt_bias must have ", num_heads, " elements, got ", dt_bias->Shape().Size());
  ORT_RETURN_IF_NOT(decay_scale->Shape().Size() == num_heads,
                    "decay_scale must have ", num_heads, " elements, got ", decay_scale->Shape().Size());

  auto* decay = context.Output(0, a_shape);
  auto* beta = context.Output(1, a_shape);

  if (beta != nullptr) {
    ORT_RETURN_IF_NOT(b != nullptr, "The b input is required when the beta output is requested");
    ORT_RETURN_IF_NOT(b->Shape() == a_shape, "b must have the same shape as a");
  }

  const int64_t output_size = a_shape.Size();
  if (output_size == 0) {
    return Status::OK();
  }

  LinearAttentionGateProgram program{b != nullptr, beta != nullptr};
  program.CacheHint(b != nullptr, beta != nullptr)
      .AddInputs({{a, ProgramTensorMetadataDependency::Type},
                  {dt_bias, ProgramTensorMetadataDependency::None},
                  {decay_scale, ProgramTensorMetadataDependency::None}});
  if (b != nullptr) {
    program.AddInput({b, ProgramTensorMetadataDependency::Type});
  }
  program.AddOutput({decay, ProgramTensorMetadataDependency::None});
  if (beta != nullptr) {
    program.AddOutput({beta, ProgramTensorMetadataDependency::None});
  }
  program.SetDispatchGroupSize((onnxruntime::narrow<uint32_t>(output_size) + WORKGROUP_SIZE - 1) / WORKGROUP_SIZE)
      .AddUniformVariables({{onnxruntime::narrow<uint32_t>(output_size)},
                            {onnxruntime::narrow<uint32_t>(num_heads)}});

  return context.RunProgram(program);
}

Status GatedRMSNorm::ComputeInternal(ComputeContext& context) const {
  const auto* input = context.Input(0);
  const auto* scale = context.Input(1);
  const auto* gate = context.Input(2);

  const auto& shape = input->Shape();
  ORT_RETURN_IF_NOT(shape.NumDimensions() >= 1, "X must have rank >= 1");
  ORT_RETURN_IF_NOT(gate->Shape() == shape, "gate must have the same shape as X");

  const int64_t norm_size = scale->Shape().Size();
  ORT_RETURN_IF_NOT(norm_size > 0, "scale must not be empty");
  const int64_t last_dim = shape[shape.NumDimensions() - 1];
  ORT_RETURN_IF_NOT(last_dim % norm_size == 0,
                    "X last dimension (", last_dim, ") must be a multiple of the scale length (",
                    norm_size, ")");

  auto* output = context.Output(0, shape);
  const int64_t total_size = shape.Size();
  if (total_size == 0) {
    return Status::OK();
  }
  const int64_t num_rows = total_size / norm_size;

  const uint32_t workgroup_size = norm_size <= 64    ? 64
                                  : norm_size <= 128 ? 128
                                                     : 256;

  GatedRMSNormProgram program{};
  program.AddInputs({{input, ProgramTensorMetadataDependency::Type},
                     {scale, ProgramTensorMetadataDependency::Type},
                     {gate, ProgramTensorMetadataDependency::Type}})
      .AddOutput({output, ProgramTensorMetadataDependency::None})
      .SetDispatchGroupSize(onnxruntime::narrow<uint32_t>(num_rows))
      .SetWorkgroupSize(workgroup_size)
      .AddUniformVariables({{onnxruntime::narrow<uint32_t>(norm_size)},
                            {epsilon_}});
  return context.RunProgram(program);
}

TEST(CausalConvWithStateTest, BFloat16_Cuda) {
  auto ep = DefaultCudaExecutionProvider();
  if (!ep) {
    GTEST_SKIP() << "CUDA execution provider not available";
    return;
  }
  if (!CudaHasBF16Support()) {
    GTEST_SKIP() << "CUDA device does not support BFloat16.";
    return;
  }

  const int batch_size = 2;
  const int channels = 4;
  const int input_length = 6;
  const int kernel_size = 3;
  const int state_length = kernel_size - 1;
  const std::string activation = "silu";

  std::vector<float> input_data(static_cast<size_t>(batch_size) * channels * input_length);
  for (size_t i = 0; i < input_data.size(); ++i) {
    input_data[i] = 0.3f * std::sin(static_cast<float>(i) * 0.41f);
  }
  std::vector<float> weight_data(static_cast<size_t>(channels) * kernel_size);
  for (size_t i = 0; i < weight_data.size(); ++i) {
    weight_data[i] = 0.2f * std::cos(static_cast<float>(i) * 0.17f);
  }
  std::vector<float> bias_data(channels);
  for (int i = 0; i < channels; ++i) {
    bias_data[i] = 0.01f * static_cast<float>(i);
  }
  std::vector<float> conv_state_data(static_cast<size_t>(batch_size) * channels * state_length);
  for (size_t i = 0; i < conv_state_data.size(); ++i) {
    conv_state_data[i] = 0.25f * std::sin(static_cast<float>(i) * 0.29f);
  }

  std::vector<float> expected_output, expected_state;
  CausalConvWithStateReference(
      input_data, weight_data, &bias_data, &conv_state_data,
      expected_output, expected_state,
      batch_size, channels, input_length, kernel_size, activation);

  std::vector<int64_t> input_shape = {batch_size, channels, input_length};
  std::vector<int64_t> weight_shape = {channels, 1, kernel_size};
  std::vector<int64_t> bias_shape = {channels};
  std::vector<int64_t> state_shape = {batch_size, channels, state_length};
  std::vector<int64_t> output_shape = {batch_size, channels, input_length};

  OpTester test("CausalConvWithState", 1, onnxruntime::kMSDomain);
  test.AddAttribute<std::string>("activation", activation);
  test.AddInput<BFloat16>("input", input_shape, ToBFloat16(input_data));
  test.AddInput<BFloat16>("weight", weight_shape, ToBFloat16(weight_data));
  test.AddInput<BFloat16>("bias", bias_shape, ToBFloat16(bias_data));
  test.AddInput<BFloat16>("past_state", state_shape, ToBFloat16(conv_state_data));
  test.AddOutput<BFloat16>("output", output_shape, ToBFloat16(expected_output), false, 0.02f, 0.0f);
  test.AddOutput<BFloat16>("present_state", state_shape, ToBFloat16(expected_state), false, 0.02f, 0.0f);

  std::vector<std::unique_ptr<IExecutionProvider>> execution_providers;
  execution_providers.push_back(std::move(ep));
  test.Run(OpTester::ExpectResult::kExpectSuccess, "", {}, nullptr, &execution_providers);
}

