TEST(ContribOpLinearAttentionTest, BFloat16_Cuda) {
  auto ep = DefaultCudaExecutionProvider();
  if (!ep) {
    GTEST_SKIP() << "CUDA execution provider not available";
    return;
  }
  if (!CudaHasBF16Support()) {
    GTEST_SKIP() << "CUDA device does not support BFloat16.";
    return;
  }

  const std::string update_rule = "gated_delta";
  const int batch_size = 2;
  const int num_heads = 2;
  const int seq_length = 4;
  const int head_dim_k = 8;
  const int head_dim_v = 8;
  const float scale = 1.0f / std::sqrt(static_cast<float>(head_dim_k));

  auto make_data = [](size_t count, float lo, float hi, uint32_t seed) {
    std::vector<float> out(count);
    std::mt19937 gen(seed);
    std::uniform_real_distribution<float> dist(lo, hi);
    for (auto& v : out) v = dist(gen);
    return out;
  };

  const size_t qk_count = static_cast<size_t>(batch_size) * num_heads * seq_length * head_dim_k;
  const size_t v_count = static_cast<size_t>(batch_size) * num_heads * seq_length * head_dim_v;
  const size_t state_count = static_cast<size_t>(batch_size) * num_heads * head_dim_k * head_dim_v;
  const size_t decay_count = static_cast<size_t>(batch_size) * num_heads * seq_length;
  const size_t beta_count = decay_count;

  auto query = make_data(qk_count, -0.5f, 0.5f, 1);
  auto key = make_data(qk_count, -0.5f, 0.5f, 2);
  auto value = make_data(v_count, -0.5f, 0.5f, 3);
  auto initial_state = make_data(state_count, -0.1f, 0.1f, 4);
  auto decay = make_data(decay_count, -1.0f, 0.0f, 5);
  auto beta = make_data(beta_count, 0.1f, 0.9f, 6);

  std::vector<float> expected_output_4d, expected_state;
  LinearAttentionReference(update_rule, batch_size, num_heads, seq_length, head_dim_k, head_dim_v,
                           scale, query, key, value, &initial_state, &decay, &beta,
                           expected_output_4d, expected_state);

  auto query_3d = PackBHTD_to_BTHD(query, batch_size, num_heads, seq_length, head_dim_k);
  auto key_3d = PackBHTD_to_BTHD(key, batch_size, num_heads, seq_length, head_dim_k);
  auto value_3d = PackBHTD_to_BTHD(value, batch_size, num_heads, seq_length, head_dim_v);
  auto output_3d = PackBHTD_to_BTHD(expected_output_4d, batch_size, num_heads, seq_length, head_dim_v);
  auto decay_3d = TransposeBHT_to_BTH(decay, batch_size, num_heads, seq_length);
  auto beta_3d = TransposeBHT_to_BTH(beta, batch_size, num_heads, seq_length);

  OpTester tester("LinearAttention", 1, onnxruntime::kMSDomain);
  tester.AddAttribute<std::string>("update_rule", update_rule);
  tester.AddAttribute<float>("scale", scale);
  tester.AddAttribute<int64_t>("q_num_heads", static_cast<int64_t>(num_heads));
  tester.AddAttribute<int64_t>("kv_num_heads", static_cast<int64_t>(num_heads));

  std::vector<int64_t> qk_dims = {batch_size, seq_length, num_heads * head_dim_k};
  std::vector<int64_t> v_dims = {batch_size, seq_length, num_heads * head_dim_v};
  std::vector<int64_t> state_dims = {batch_size, num_heads, head_dim_k, head_dim_v};
  std::vector<int64_t> decay_dims = {batch_size, seq_length, num_heads};
  std::vector<int64_t> beta_dims = {batch_size, seq_length, num_heads};
  std::vector<int64_t> out_dims = {batch_size, seq_length, num_heads * head_dim_v};

  tester.AddInput<BFloat16>("query", qk_dims, ToBFloat16(query_3d));
  tester.AddInput<BFloat16>("key", qk_dims, ToBFloat16(key_3d));
  tester.AddInput<BFloat16>("value", v_dims, ToBFloat16(value_3d));
  tester.AddInput<BFloat16>("past_state", state_dims, ToBFloat16(initial_state));
  tester.AddInput<BFloat16>("decay", decay_dims, ToBFloat16(decay_3d));
  tester.AddInput<BFloat16>("beta", beta_dims, ToBFloat16(beta_3d));
  tester.AddOutput<BFloat16>("output", out_dims, ToBFloat16(output_3d), false, 0.02f, 0.0f);
  tester.AddOutput<BFloat16>("present_state", state_dims, ToBFloat16(expected_state), false, 0.02f, 0.0f);

  std::vector<std::unique_ptr<IExecutionProvider>> execution_providers;
  execution_providers.push_back(std::move(ep));
  tester.Run(OpTester::ExpectResult::kExpectSuccess, "", {}, nullptr, &execution_providers);
}

TEST(LpNormalizationTest, L2Normalization_BFloat16_Opset22) {
#ifndef USE_CUDA
  GTEST_SKIP() << "BFloat16 tests are only enabled on CUDA builds";
#else
  if (!CudaHasBF16Support()) {
    GTEST_SKIP() << "CUDA device does not support BFloat16.";
  }

  OpTester test("LpNormalization", 22);
  test.AddAttribute("axis", static_cast<int64_t>(-1));
  test.AddAttribute("p", static_cast<int64_t>(2));

  constexpr int64_t kRows = 2;
  constexpr int64_t kCols = 8;
  std::vector<float> input_f = {
      1.0f, 2.0f, 3.0f, 4.0f, 2.0f, 1.0f, 0.5f, 0.25f,
      4.0f, 3.0f, 2.0f, 1.0f, 1.0f, 2.0f, 4.0f, 8.0f};

  std::vector<float> expected_f(kRows * kCols);
  for (int64_t r = 0; r < kRows; ++r) {
    float sum_sq = 0.0f;
    for (int64_t c = 0; c < kCols; ++c) {
      const float v = input_f[r * kCols + c];
      sum_sq += v * v;
    }
    const float norm = std::sqrt(sum_sq);
    for (int64_t c = 0; c < kCols; ++c) {
      expected_f[r * kCols + c] = input_f[r * kCols + c] / norm;
    }
  }

  const std::vector<int64_t> dims = {kRows, kCols};
  test.AddInput<BFloat16>("input", dims, FloatsToBFloat16s(input_f));
  test.AddOutput<BFloat16>("Y", dims, FloatsToBFloat16s(expected_f), false, 0.01f, 0.0f);

  SessionOptions so;
  ASSERT_TRUE(so.config_options.AddConfigEntry(kOrtSessionOptionsDisableCPUEPFallback, "1").IsOK());
  std::vector<std::unique_ptr<IExecutionProvider>> execution_providers;
  execution_providers.push_back(DefaultCudaExecutionProvider());
  test.Run(so, OpTester::ExpectResult::kExpectSuccess, "", {}, nullptr, &execution_providers);
#endif
}

void PrepareWork(ptrdiff_t Index)
    {
        const size_t TotalWork = BatchCount * GroupCount * FilterSetCount * OutputHeight;

        size_t WorkIndex;

        MlasPartitionWork(Index, WorkBlock->tids, TotalWork, &WorkIndex, &WorkRemaining);

        if (WorkRemaining > 0) {
            SeekToWork(WorkIndex);
        }
    }

size_t CostToWorkIndex(size_t Cost, size_t TotalBlockedFilters, size_t LastSetFilterCount) const
    {
        return MlasNchwcCostToWorkIndex(Cost, OutputHeight, FilterSetCount, FilterSetSize,
                                        TotalBlockedFilters, LastSetFilterCount);
    }

void PrepareWorkWeighted(ptrdiff_t Index)
    {
        const size_t TotalBlockedFilters = OutputChannels / BlockSize;
        const size_t LastSetFilterCount =
            TotalBlockedFilters - (FilterSetCount - 1) * FilterSetSize;

        const size_t TotalCost = BatchCount * GroupCount * TotalBlockedFilters * OutputHeight;

        size_t CostStart;
        size_t CostCount;

        MlasPartitionWork(Index, WorkBlock->tids, TotalCost, &CostStart, &CostCount);

        const size_t WorkIndexBegin =
            CostToWorkIndex(CostStart, TotalBlockedFilters, LastSetFilterCount);
        const size_t WorkIndexEnd =
            CostToWorkIndex(CostStart + CostCount, TotalBlockedFilters, LastSetFilterCount);

        WorkRemaining = WorkIndexEnd - WorkIndexBegin;

        //
        // Skip the seek when this thread received no work. TotalCost below tids
        // leaves surplus threads with an empty cost interval starting at
        // TotalCost, which maps to WorkIndexBegin == TotalWork; seeking there
        // would advance the buffer pointers past the end of their tensors.
        //

        if (WorkRemaining > 0) {
            SeekToWork(WorkIndexBegin);
        }
    }

size_t RangeCost(size_t Begin, size_t End) const {
    size_t Cost = 0;
    for (size_t i = Begin; i < End; i++) {
      Cost += WorkItemCost(i);
    }
    return Cost;
  }

std::string Describe() const {
    return "OutputChannels=" + std::to_string(OutputChannels) +
           " OutputHeight=" + std::to_string(OutputHeight) +
           " BatchGroupCount=" + std::to_string(BatchGroupCount) +
           " FilterSetCount=" + std::to_string(FilterSetCount()) +
           " LastSetFilterCount=" + std::to_string(LastSetFilterCount());
  }

std::vector<PartitionShape> AllShapes() {
  const size_t OutputChannelValues[] = {16, 32, 48, 64, 96, 144, 208, 256};
  const size_t OutputHeightValues[] = {1, 2, 7, 13, 52};
  const size_t BatchGroupValues[] = {1, 2, 8};

  std::vector<PartitionShape> Shapes;

  for (size_t OutputChannels : OutputChannelValues) {
    for (size_t OutputHeight : OutputHeightValues) {
      for (size_t BatchGroupCount : BatchGroupValues) {
        Shapes.push_back(PartitionShape{16, 4, OutputChannels, OutputHeight, BatchGroupCount});
      }
    }
  }

  return Shapes;
}

TEST(SnchwcPartition, RangesTileWorkSpace) {
  for (const PartitionShape& Shape : AllShapes()) {
    for (ptrdiff_t tids : ThreadCounts) {
      size_t Expected = 0;

      for (ptrdiff_t Index = 0; Index < tids; Index++) {
        size_t CostStart;
        size_t CostCount;
        MlasPartitionWork(Index, tids, Shape.TotalCost(), &CostStart, &CostCount);

        const size_t Begin = Shape.CostToWorkIndex(CostStart);
        const size_t End = Shape.CostToWorkIndex(CostStart + CostCount);

        ASSERT_LE(Begin, End) << Shape.Describe() << " tids=" << tids << " Index=" << Index;
        ASSERT_EQ(Begin, Expected) << "gap or overlap; " << Shape.Describe()
                                   << " tids=" << tids << " Index=" << Index;
        Expected = End;
      }

      ASSERT_EQ(Expected, Shape.TotalWork())
          << "work space not fully covered; " << Shape.Describe() << " tids=" << tids;
    }
  }
}

TEST(SnchwcPartition, MonotoneAndBounded) {
  for (const PartitionShape& Shape : AllShapes()) {
    size_t Previous = 0;

    for (size_t Cost = 0; Cost <= Shape.TotalCost(); Cost++) {
      const size_t WorkIndex = Shape.CostToWorkIndex(Cost);

      ASSERT_GE(WorkIndex, Previous) << "not monotone at Cost=" << Cost << "; " << Shape.Describe();
      ASSERT_LE(WorkIndex, Shape.TotalWork())
          << "out of bounds at Cost=" << Cost << "; " << Shape.Describe();

      Previous = WorkIndex;
    }

    ASSERT_EQ(Shape.CostToWorkIndex(0), size_t{0}) << Shape.Describe();
    ASSERT_EQ(Shape.CostToWorkIndex(Shape.TotalCost()), Shape.TotalWork()) << Shape.Describe();
  }
}

TEST(SnchwcPartition, CostIsBalancedAcrossThreads) {
  for (const PartitionShape& Shape : AllShapes()) {
    for (ptrdiff_t tids : ThreadCounts) {
      if (Shape.TotalCost() < static_cast<size_t>(tids)) {
        continue;  // covered by EmptyPartitionsAreWellFormed
      }

      const size_t Ideal = Shape.TotalCost() / static_cast<size_t>(tids);

      //
      // A thread's range boundary can only fall on a work item, so its cost can
      // deviate from ideal by at most the cost of one item at each end.
      //

      const size_t Tolerance = 2 * Shape.FilterSetSize;

      for (ptrdiff_t Index = 0; Index < tids; Index++) {
        size_t CostStart;
        size_t CostCount;
        MlasPartitionWork(Index, tids, Shape.TotalCost(), &CostStart, &CostCount);

        const size_t Begin = Shape.CostToWorkIndex(CostStart);
        const size_t End = Shape.CostToWorkIndex(CostStart + CostCount);
        const size_t ActualCost = Shape.RangeCost(Begin, End);

        const size_t Deviation = (ActualCost > Ideal) ? (ActualCost - Ideal) : (Ideal - ActualCost);

        ASSERT_LE(Deviation, Tolerance)
            << "thread " << Index << " of " << tids << " got " << ActualCost
            << " block-rows, ideal " << Ideal << "; " << Shape.Describe();
      }
    }
  }
}

TEST(SnchwcPartition, EmptyPartitionsAreWellFormed) {
  for (const PartitionShape& Shape : AllShapes()) {
    for (ptrdiff_t tids : ThreadCounts) {
      if (Shape.TotalCost() >= static_cast<size_t>(tids)) {
        continue;
      }

      bool SawEmpty = false;

      for (ptrdiff_t Index = 0; Index < tids; Index++) {
        size_t CostStart;
        size_t CostCount;
        MlasPartitionWork(Index, tids, Shape.TotalCost(), &CostStart, &CostCount);

        const size_t Begin = Shape.CostToWorkIndex(CostStart);
        const size_t End = Shape.CostToWorkIndex(CostStart + CostCount);

        if (CostCount == 0) {
          SawEmpty = true;
          ASSERT_EQ(Begin, End) << "empty cost interval produced work; " << Shape.Describe()
                                << " tids=" << tids << " Index=" << Index;
          ASSERT_LE(Begin, Shape.TotalWork())
              << "empty partition seeks out of bounds; " << Shape.Describe()
              << " tids=" << tids << " Index=" << Index;
        }
      }

      ASSERT_TRUE(SawEmpty) << "expected surplus threads; " << Shape.Describe()
                            << " tids=" << tids;
    }
  }
}

TEST(SnchwcPartition, WorkedExampleFromDocumentation) {
  const PartitionShape Shape{16, 4, 96, 52, 1};

  ASSERT_EQ(Shape.TotalBlockedFilters(), size_t{6});
  ASSERT_EQ(Shape.FilterSetCount(), size_t{2});
  ASSERT_EQ(Shape.LastSetFilterCount(), size_t{2});
  ASSERT_EQ(Shape.TotalCost(), size_t{6 * 52});
  ASSERT_EQ(Shape.TotalWork(), size_t{2 * 52});

  const ptrdiff_t tids = 4;
  const size_t Ideal = Shape.TotalCost() / tids;  // 78 block-rows

  size_t Worst = 0;

  for (ptrdiff_t Index = 0; Index < tids; Index++) {
    size_t CostStart;
    size_t CostCount;
    MlasPartitionWork(Index, tids, Shape.TotalCost(), &CostStart, &CostCount);

    const size_t ActualCost = Shape.RangeCost(Shape.CostToWorkIndex(CostStart),
                                              Shape.CostToWorkIndex(CostStart + CostCount));
    Worst = std::max(Worst, ActualCost);
  }

  //
  // Scheduling efficiency is Ideal/Worst. The uniform split gives 4*52/(2*52*... )
  // -- concretely, its worst thread takes 104 block-rows against an ideal of 78,
  // i.e. 75%. The weighted split must stay within one work item of ideal.
  //

  ASSERT_LE(Worst, Ideal + Shape.FilterSetSize)
      << "worst thread took " << Worst << " block-rows against ideal " << Ideal;
}

static std::vector<float> MakeWideArgReductionInput(int64_t num_rows, int64_t num_cols,
                                                    const std::vector<int64_t>& max_indices,
                                                    const std::vector<int64_t>& min_indices) {
  std::vector<float> data(static_cast<size_t>(num_rows * num_cols));
  for (int64_t row = 0; row < num_rows; ++row) {
    for (int64_t col = 0; col < num_cols; ++col) {
      // Repeating ramp: plenty of duplicated values, no accidental extremes.
      data[static_cast<size_t>(row * num_cols + col)] = static_cast<float>((col + row) % 97) * 0.5f;
    }
    // Duplicated extremes: the first occurrence has to win.
    data[static_cast<size_t>(row * num_cols + max_indices[static_cast<size_t>(row)])] = 1000.0f;
    data[static_cast<size_t>(row * num_cols + num_cols - 1)] = 1000.0f;
    data[static_cast<size_t>(row * num_cols + min_indices[static_cast<size_t>(row)])] = -1000.0f;
    data[static_cast<size_t>(row * num_cols + num_cols - 2)] = -1000.0f;
  }
  return data;
}

