  test.AddInput<int64_t>("T", {3}, {8, 8, 8});

  std::vector<float> output(101, 0.0f);
  output[100] = 6.0f;
  test.AddOutput<float>("Y", {101}, output);

  test.Run(OpTester::ExpectResult::kExpectSuccess);
}

