            "E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855");
  EXPECT_EQ(telemetry_internal::Sha256::HashStringHex("abc"),
            "BA7816BF8F01CFEA414140DE5DAE2223B00361A396177A9CB410FF61F20015AD");
  EXPECT_EQ(telemetry_internal::Sha256::HashStringHex(
                "01234567-89ab-4def-8123-456789abcdef"),
            "6225BD190D6CCF87766A49C9986D174DEF3391FE175A61525E49A1D2334D6A43");
}

static void VerifyTensorProtoFitsInBuffer(const onnx::TensorProto& tensorProto, size_t bufferByteSize)
    {
        // Strings are not laid out as a flat buffer of fixed-width elements, and the DML EP has no
        // consumer that reads them through this wrapper.
        if (tensorProto.data_type() == onnx::TensorProto_DataType_STRING)
        {
            return;
        }

        // A failure here means the declared shape is not representable, the byte count overflows, or the
        // element type has no fixed width. The only types ToMLTensorDataType accepts that this helper
        // cannot size are COMPLEX64/COMPLEX128, and no DML operator registers those (they exist in
        // OperatorRegistration.cpp's SupportedTensorDataTypes only as unused enum values, and DmlCommon
        // maps both to DML_TENSOR_DATA_TYPE_UNKNOWN). Rejecting the proto is therefore the correct
        // outcome for every type that can actually reach this point.
        size_t requiredByteSize = 0;
        THROW_IF_NOT_OK(onnxruntime::utils::GetSizeInBytesFromTensorProto<0>(tensorProto, &requiredByteSize));

        if (bufferByteSize < requiredByteSize)
        {
            ORT_THROW_HR_MSG(
                E_INVALIDARG,
                "Tensor '%hs' carries fewer bytes of data than its shape requires. "
                "Shape requires %llu bytes, but only %llu bytes are present.",
                tensorProto.name().c_str(),
                static_cast<uint64_t>(requiredByteSize),
                static_cast<uint64_t>(bufferByteSize));
        }
    }

std::string MakeInt64RawData(const std::vector<int64_t>& values, size_t truncateToByteCount = SIZE_MAX) {
  std::string raw;
  raw.reserve(values.size() * sizeof(int64_t));
  for (int64_t value : values) {
    for (size_t byteIndex = 0; byteIndex < sizeof(int64_t); ++byteIndex) {
      raw.push_back(static_cast<char>(static_cast<uint64_t>(value) >> (8 * byteIndex)));
    }
  }

  if (truncateToByteCount < raw.size()) {
    raw.resize(truncateToByteCount);
  }

  return raw;
}

std::string BuildConstantOfShapeModel(ValueAttributePayload payload) {
  ONNX_NAMESPACE::ModelProto model;
  model.set_ir_version(ONNX_NAMESPACE::Version::IR_VERSION);
  ONNX_NAMESPACE::OperatorSetIdProto& opset = *model.add_opset_import();
  opset.set_domain("");
  opset.set_version(13);

  ONNX_NAMESPACE::GraphProto& graph = *model.mutable_graph();
  graph.set_name("dml_onnx_tensor_wrapper_test");

  ONNX_NAMESPACE::ValueInfoProto& output = *graph.add_output();
  output.set_name("Y");
  output.mutable_type()->mutable_tensor_type()->set_elem_type(ONNX_NAMESPACE::TensorProto_DataType_INT64);

  ONNX_NAMESPACE::TensorProto& shape = *graph.add_initializer();
  shape.set_name("shape");
  shape.set_data_type(ONNX_NAMESPACE::TensorProto_DataType_INT64);
  shape.add_dims(1);
  shape.set_raw_data(MakeInt64RawData({4}));

  ONNX_NAMESPACE::NodeProto& node = *graph.add_node();
  node.set_name("constant_of_shape0");
  node.set_op_type("ConstantOfShape");
  node.add_input("shape");
  node.add_output("Y");

  ONNX_NAMESPACE::AttributeProto& valueAttribute = *node.add_attribute();
  valueAttribute.set_name("value");
  valueAttribute.set_type(ONNX_NAMESPACE::AttributeProto_AttributeType_TENSOR);

  // Every variant declares a single INT64 element, i.e. a shape that implies 8 bytes of payload.
  ONNX_NAMESPACE::TensorProto& valueTensor = *valueAttribute.mutable_t();
  valueTensor.set_name("value");
  valueTensor.set_data_type(ONNX_NAMESPACE::TensorProto_DataType_INT64);
  valueTensor.add_dims(1);

  switch (payload) {
    case ValueAttributePayload::FullRawData:
      valueTensor.set_raw_data(MakeInt64RawData({42}));
      break;
    case ValueAttributePayload::TruncatedRawData:
      valueTensor.set_raw_data(MakeInt64RawData({42}, /*truncateToByteCount*/ 1));
      break;
  }

  std::string serialized;
  EXPECT_TRUE(model.SerializeToString(&serialized));
  return serialized;
}

Status InitializeWithDmlEp(const std::string& serializedModel,
                           bool& skipped,
                           std::unique_ptr<InferenceSession>* outSession = nullptr) {
  skipped = false;

  std::unique_ptr<IExecutionProvider> dmlEp = DefaultDmlExecutionProvider();
  if (dmlEp == nullptr) {
    skipped = true;
    return Status::OK();
  }

  SessionOptions sessionOptions;
  sessionOptions.session_logid = "DmlOnnxTensorWrapperTest";
  ORT_RETURN_IF_ERROR(sessionOptions.config_options.AddConfigEntry(
      kOrtSessionOptionsDisableSpecifiedOptimizers, "ConstantFolding"));

  auto session = std::make_unique<InferenceSession>(sessionOptions, GetEnvironment());
  ORT_RETURN_IF_ERROR(session->RegisterExecutionProvider(std::move(dmlEp)));
  ORT_RETURN_IF_ERROR(session->Load(serializedModel.data(), static_cast<int>(serializedModel.size())));

  Status status = session->Initialize();
  if (outSession != nullptr) {
    *outSession = std::move(session);
  }

  return status;
}

TEST(DmlOnnxTensorWrapperTest, TruncatedRawDataAttributeTensorIsRejected) {
  const std::string model = BuildConstantOfShapeModel(ValueAttributePayload::TruncatedRawData);

  bool skipped = false;
  const Status status = InitializeWithDmlEp(model, skipped);
  if (skipped) {
    GTEST_SKIP() << "DirectML execution provider is not available on this machine.";
  }

  ASSERT_FALSE(status.IsOK()) << "Session initialization should reject a tensor whose declared shape "
                                 "exceeds the data it carries.";

  // The detailed message raised inside the constructor does not survive: OnnxTensorWrapper is
  // constructed behind the IMLOperatorAttributes1 COM boundary, whose ORT_CATCH_RETURN reduces the
  // exception to a bare HRESULT before it is rethrown. 0x80070057 is E_INVALIDARG, so this asserts the
  // model was rejected as malformed rather than failing for an unrelated reason.
  EXPECT_NE(status.ErrorMessage().find("80070057"), std::string::npos)
      << "Unexpected failure reason: " << status.ErrorMessage();
}

TEST(DmlOnnxTensorWrapperTest, WellFormedAttributeTensorIsAccepted) {
  const std::string model = BuildConstantOfShapeModel(ValueAttributePayload::FullRawData);

  bool skipped = false;
  std::unique_ptr<InferenceSession> session;
  const Status status = InitializeWithDmlEp(model, skipped, &session);
  if (skipped) {
    GTEST_SKIP() << "DirectML execution provider is not available on this machine.";
  }

  ASSERT_STATUS_OK(status);

  RunOptions runOptions;
  std::vector<OrtValue> fetches;
  ASSERT_STATUS_OK(session->Run(runOptions, NameMLValMap{}, std::vector<std::string>{"Y"}, &fetches));

  ASSERT_EQ(fetches.size(), 1u);
  const Tensor& result = fetches[0].Get<Tensor>();
  ASSERT_EQ(result.Shape(), TensorShape({4}));

  for (int64_t element : result.DataAsSpan<int64_t>()) {
    EXPECT_EQ(element, 42);
  }
}

Status LinearAttentionGate<T>::ComputeInternal(OpKernelContext* context) const {
  typedef typename OrtToCudaType<T>::type CudaT;

  const Tensor* a = context->Input<Tensor>(0);
  const Tensor* dt_bias = context->Input<Tensor>(1);
  const Tensor* decay_scale = context->Input<Tensor>(2);
  const Tensor* b = context->Input<Tensor>(3);  // optional

  const auto& a_shape = a->Shape();
  ORT_RETURN_IF_NOT(a_shape.NumDimensions() >= 1, "a must have rank >= 1");
  const int64_t num_heads = a_shape[a_shape.NumDimensions() - 1];
  ORT_RETURN_IF_NOT(num_heads > 0, "a last dimension must be positive");
  ORT_RETURN_IF_NOT(num_heads <= std::numeric_limits<int>::max(),
                    "a last dimension is too large for the CUDA kernel");

  ORT_RETURN_IF_NOT(dt_bias->Shape().Size() == num_heads,
                    "dt_bias must have ", num_heads, " elements, got ", dt_bias->Shape().Size());
  ORT_RETURN_IF_NOT(decay_scale->Shape().Size() == num_heads,
                    "decay_scale must have ", num_heads, " elements, got ", decay_scale->Shape().Size());

  Tensor* decay = context->Output(0, a_shape);
  Tensor* beta = context->Output(1, a_shape);

  if (beta != nullptr) {
    ORT_RETURN_IF_NOT(b != nullptr, "the b input is required when the beta output is requested");
    ORT_RETURN_IF_NOT(b->Shape() == a_shape, "b must have the same shape as a");
  }

  const int64_t num_tokens = a_shape.Size() / num_heads;
  return LaunchLinearAttentionGateKernel<CudaT>(
      Stream(context),
      reinterpret_cast<CudaT*>(decay->MutableData<T>()),
      beta == nullptr ? nullptr : reinterpret_cast<CudaT*>(beta->MutableData<T>()),
      reinterpret_cast<const CudaT*>(a->Data<T>()),
      b == nullptr ? nullptr : reinterpret_cast<const CudaT*>(b->Data<T>()),
      dt_bias->Data<float>(),
      decay_scale->Data<float>(),
      num_tokens,
      static_cast<int>(num_heads));
}

Status GatedRMSNorm<T>::ComputeInternal(OpKernelContext* context) const {
  typedef typename OrtToCudaType<T>::type CudaT;

  const Tensor* input = context->Input<Tensor>(0);
  const Tensor* scale = context->Input<Tensor>(1);
  const Tensor* gate = context->Input<Tensor>(2);

  const auto& shape = input->Shape();
  ORT_RETURN_IF_NOT(shape.NumDimensions() >= 1, "X must have rank >= 1");
  ORT_RETURN_IF_NOT(gate->Shape() == shape, "gate must have the same shape as X");

  const int64_t norm_size = scale->Shape().Size();
  ORT_RETURN_IF_NOT(norm_size > 0, "scale must not be empty");
  ORT_RETURN_IF_NOT(norm_size <= std::numeric_limits<int>::max(),
                    "scale is too large for the CUDA kernel");
  const int64_t last_dim = shape[shape.NumDimensions() - 1];
  ORT_RETURN_IF_NOT(last_dim % norm_size == 0,
                    "X last dimension (", last_dim, ") must be a multiple of the scale length (",
                    norm_size, ")");

  Tensor* output = context->Output(0, shape);
  const int64_t num_rows = shape.Size() / norm_size;

  return LaunchGatedRMSNormKernel<CudaT>(
      Stream(context),
      reinterpret_cast<CudaT*>(output->MutableData<T>()),
      reinterpret_cast<const CudaT*>(input->Data<T>()),
      reinterpret_cast<const CudaT*>(scale->Data<T>()),
      reinterpret_cast<const CudaT*>(gate->Data<T>()),
      num_rows,
      static_cast<int>(norm_size),
      epsilon_);
}

static void RunCausalConvStateWindowTest(int batch_size, int channels, int input_length,
                                         int kernel_size, int window, bool with_past_state) {
  auto ep = DefaultCudaExecutionProvider();
  if (!ep) {
    GTEST_SKIP() << "CUDA execution provider not available";
    return;
  }

  const int state_length = kernel_size - 1;
  const std::string activation = "silu";

  std::vector<float> input_data(static_cast<size_t>(batch_size) * channels * input_length);
  for (int i = 0; i < static_cast<int>(input_data.size()); ++i) {
    input_data[i] = 0.5f * std::sin(static_cast<float>(i) * 0.37f);
  }
  std::vector<float> weight_data(static_cast<size_t>(channels) * kernel_size);
  for (int i = 0; i < static_cast<int>(weight_data.size()); ++i) {
    weight_data[i] = 0.25f * std::cos(static_cast<float>(i) * 0.21f);
  }
  std::vector<float> bias_data(channels);
  for (int i = 0; i < channels; ++i) {
    bias_data[i] = 0.01f * static_cast<float>(i);
  }
  std::vector<float> conv_state_data(static_cast<size_t>(batch_size) * channels * state_length);
  for (int i = 0; i < static_cast<int>(conv_state_data.size()); ++i) {
    conv_state_data[i] = with_past_state ? 0.5f * std::sin(static_cast<float>(i) * 0.3f) : 0.0f;
  }
  const std::vector<float>* past = with_past_state ? &conv_state_data : nullptr;

  // Keep only the first `prefix` positions of a (B, C, L) tensor.
  auto slice_prefix = [&](const std::vector<float>& src, int prefix) {
    std::vector<float> dst(static_cast<size_t>(batch_size) * channels * prefix);
    for (int bc = 0; bc < batch_size * channels; ++bc) {
      for (int l = 0; l < prefix; ++l) {
        dst[static_cast<size_t>(bc) * prefix + l] = src[static_cast<size_t>(bc) * input_length + l];
      }
    }
    return dst;
  };

  std::vector<float> expected_output, expected_state;
  CausalConvWithStateReference(
      input_data, weight_data, &bias_data, past,
      expected_output, expected_state,
      batch_size, channels, input_length, kernel_size, activation);

  // Slot j holds the state after the first (input_length - window + j + 1) positions; slots for
  // non-positive prefixes are never computed by the kernel and stay zero. The window axis leads
  // the batch axis, so a slot is exactly one contiguous (B, C, K-1) reference block.
  const size_t slot_elems = static_cast<size_t>(channels) * state_length;
  const size_t batch_slot_elems = static_cast<size_t>(batch_size) * slot_elems;
  std::vector<float> expected_state_window(static_cast<size_t>(window) * batch_slot_elems, 0.0f);
  for (int j = 0; j < window; ++j) {
    const int prefix = input_length - window + j + 1;
    if (prefix <= 0) continue;
    std::vector<float> prefix_state;
    if (prefix == input_length) {
      prefix_state = expected_state;
    } else {
      std::vector<float> prefix_output;
      CausalConvWithStateReference(
          slice_prefix(input_data, prefix), weight_data, &bias_data, past,
          prefix_output, prefix_state,
          batch_size, channels, prefix, kernel_size, activation);
    }
    std::copy_n(prefix_state.begin(), batch_slot_elems,
                expected_state_window.begin() + static_cast<size_t>(j) * batch_slot_elems);
  }

  OpTester test("CausalConvWithState", 1, onnxruntime::kMSDomain);
  test.AddAttribute<std::string>("activation", activation);
  test.AddAttribute<int64_t>("state_window", static_cast<int64_t>(window));

  test.AddInput<float>("input", {batch_size, channels, input_length}, input_data);
  test.AddInput<float>("weight", {channels, 1, kernel_size}, weight_data);
  test.AddInput<float>("bias", {channels}, bias_data);
  if (with_past_state) {
    // past_state is windowed too, and only slot W-1 is read. Poison the earlier slots to prove it.
    std::vector<float> past_state_window(static_cast<size_t>(window) * batch_slot_elems, -1e4f);
    std::copy_n(conv_state_data.begin(), batch_slot_elems,
                past_state_window.begin() + static_cast<size_t>(window - 1) * batch_slot_elems);
    test.AddInput<float>("past_state", {window, batch_size, channels, state_length}, past_state_window);
  } else {
    test.AddOptionalInputEdge<float>();
  }

  test.AddOutput<float>("output", {batch_size, channels, input_length}, expected_output);
  test.AddOutput<float>("present_state", {window, batch_size, channels, state_length},
                        expected_state_window);
  test.SetOutputAbsErr("output", 0.01f);
  test.SetOutputAbsErr("present_state", 0.01f);

  std::vector<std::unique_ptr<IExecutionProvider>> execution_providers;
  execution_providers.push_back(std::move(ep));
  test.Run(OpTester::ExpectResult::kExpectSuccess, "", {}, nullptr, &execution_providers);
}

std::vector<float> RandomFloats(size_t count, float lo, float hi, uint32_t seed) {
  std::mt19937 gen(seed);
  std::uniform_real_distribution<float> dist(lo, hi);
  std::vector<float> out(count);
  for (auto& v : out) {
    v = dist(gen);
  }
  return out;
}

std::vector<T> ToTensorType(const std::vector<float>& data) {
  if constexpr (std::is_same_v<T, MLFloat16>) {
    return ToFloat16(data);
  } else if constexpr (std::is_same_v<T, BFloat16>) {
    return ToBFloat16(data);
  } else {
    return data;
  }
}

void RunLinearAttentionGateTest(int batch_size, int seq_length, int num_heads, bool with_beta,
                                float tolerance) {
  auto cuda_ep = DefaultCudaExecutionProvider();
  if (!cuda_ep) {
    GTEST_SKIP() << "CUDA EP not available";
  }

  const size_t count = static_cast<size_t>(batch_size) * seq_length * num_heads;
  const auto a = RandomFloats(count, -6.0f, 6.0f, 11);
  const auto b = RandomFloats(count, -6.0f, 6.0f, 12);
  const auto dt_bias = RandomFloats(static_cast<size_t>(num_heads), -2.0f, 2.0f, 13);
  const auto decay_scale = RandomFloats(static_cast<size_t>(num_heads), -4.0f, -0.1f, 14);

  std::vector<float> expected_decay(count);
  std::vector<float> expected_beta(count);
  for (size_t i = 0; i < count; ++i) {
    const int h = static_cast<int>(i % num_heads);
    expected_decay[i] = decay_scale[h] * SoftplusRef(a[i] + dt_bias[h]);
    expected_beta[i] = SigmoidRef(b[i]);
  }

  const std::vector<int64_t> dims = {batch_size, seq_length, num_heads};
  const std::vector<int64_t> param_dims = {num_heads};

  OpTester tester("LinearAttentionGate", 1, onnxruntime::kMSDomain);
  tester.AddInput<T>("a", dims, ToTensorType<T>(a));
  tester.AddInput<float>("dt_bias", param_dims, dt_bias);
  tester.AddInput<float>("decay_scale", param_dims, decay_scale);
  if (with_beta) {
    tester.AddInput<T>("b", dims, ToTensorType<T>(b));
  } else {
    tester.AddOptionalInputEdge<T>();
  }
  tester.AddOutput<T>("decay", dims, ToTensorType<T>(expected_decay), false, tolerance, tolerance);
  if (with_beta) {
    tester.AddOutput<T>("beta", dims, ToTensorType<T>(expected_beta), false, tolerance, tolerance);
  }

  std::vector<std::unique_ptr<IExecutionProvider>> execution_providers;
  execution_providers.push_back(std::move(cuda_ep));
  tester.Run(OpTester::ExpectResult::kExpectSuccess, "", {}, nullptr, &execution_providers);
}

void RunGatedRMSNormTest(int batch_size, int seq_length, int num_heads, int head_dim,
                         float epsilon, float tolerance) {
  auto cuda_ep = DefaultCudaExecutionProvider();
  if (!cuda_ep) {
    GTEST_SKIP() << "CUDA EP not available";
  }

  const int hidden = num_heads * head_dim;
  const size_t count = static_cast<size_t>(batch_size) * seq_length * hidden;
  const auto x = RandomFloats(count, -3.0f, 3.0f, 21);
  const auto gate = RandomFloats(count, -5.0f, 5.0f, 22);
  const auto scale = RandomFloats(static_cast<size_t>(head_dim), 0.2f, 1.8f, 23);

  std::vector<float> expected(count);
  const size_t num_rows = count / head_dim;
  for (size_t r = 0; r < num_rows; ++r) {
    const size_t base = r * head_dim;
    float sum_sq = 0.0f;
    for (int i = 0; i < head_dim; ++i) {
      sum_sq += x[base + i] * x[base + i];
    }
    const float inv_rms = 1.0f / std::sqrt(sum_sq / static_cast<float>(head_dim) + epsilon);
    for (int i = 0; i < head_dim; ++i) {
      const float z = gate[base + i];
      expected[base + i] = x[base + i] * inv_rms * scale[i] * (z * SigmoidRef(z));
    }
  }

  const std::vector<int64_t> dims = {batch_size, seq_length, hidden};
  const std::vector<int64_t> scale_dims = {head_dim};

  OpTester tester("GatedRMSNorm", 1, onnxruntime::kMSDomain);
  tester.AddAttribute<float>("epsilon", epsilon);
  tester.AddInput<T>("X", dims, ToTensorType<T>(x));
  tester.AddInput<T>("scale", scale_dims, ToTensorType<T>(scale));
  tester.AddInput<T>("gate", dims, ToTensorType<T>(gate));
  tester.AddOutput<T>("Y", dims, ToTensorType<T>(expected), false, tolerance, tolerance);

  std::vector<std::unique_ptr<IExecutionProvider>> execution_providers;
  execution_providers.push_back(std::move(cuda_ep));
  tester.Run(OpTester::ExpectResult::kExpectSuccess, "", {}, nullptr, &execution_providers);
}

