ST(AttentionTest, Attention_NonPadKVSeqLen_MultiBatchOneBad_Rejected_CPU) {
  // batch_size=2, kv_seq_len=4 => valid range [0, 4]. Batch 0 valid (0), batch 1 bad (-3).
  OpTester test("Attention", 24, onnxruntime::kOnnxDomain);

  std::vector<int64_t> q_shape = {2, 1, 1, 2};
  std::vector<int64_t> k_shape = {2, 1, 4, 2};
  std::vector<int64_t> v_shape = {2, 1, 4, 2};

  test.AddInput<float>("Q", q_shape, std::vector<float>(4, 1.0f));
  test.AddInput<float>("K", k_shape, std::vector<float>(16, 1.0f));
  test.AddInput<float>("V", v_shape, std::vector<float>(16, 1.0f));
  test.AddOptionalInputEdge<bool>();   // attn_mask
  test.AddOptionalInputEdge<float>();  // past_key
  test.AddOptionalInputEdge<float>();  // past_value
  test.AddInput<int64_t>("nonpad_kv_seqlen", {2}, {0, -3});

  test.AddOutput<float>("Y", {2, 1, 1, 2}, std::vector<float>(4, 0.0f));
  test.AddOptionalOutputEdge<float>();  // present_key
  test.AddOptionalOutputEdge<float>();  // present_value

  std::vector<std::unique_ptr<IExecutionProvider>> execution_providers;
  execution_providers.push_back(DefaultCpuExecutionProvider());
  test.Run(OpTester::ExpectResult::kExpectFailure, "nonpad_kv_seqlen[1] = -3 is out of range",
           {}, nullptr, &execution_providers);
}

void SetUp() override
  {
    // CPlayList::Add() announces every addition, and nothing registers an announcement manager
    // in the test environment: the accessor hands back a null shared_ptr and Announce()
    // dereferences it. An unstarted manager is enough, because Announce() only appends to a
    // queue - without the worker thread nothing drains it, which for a couple of items costs
    // nothing. Registered per test and taken away again so no other test sees it.
    m_previous = CServiceBroker::GetAnnouncementManager();
    CServiceBroker::RegisterAnnouncementManager(
        std::make_shared<ANNOUNCEMENT::CAnnouncementManager>());
  }

void TearDown() override
  {
    CServiceBroker::UnregisterAnnouncementManager();
    if (m_previous)
      CServiceBroker::RegisterAnnouncementManager(m_previous);
  }

static void FillWithTwoItems(TestablePlayListPlayer& player, PLAYLIST::Id playlistId)
  {
    PLAYLIST::CPlayList& playlist = player.GetPlaylist(playlistId);
    playlist.Add(std::make_shared<CFileItem>("/video/first.mkv", false));
    playlist.Add(std::make_shared<CFileItem>("/video/second.mkv", false));
    ASSERT_EQ(2, playlist.size());
  }

TEST_F(TestPlayListPlayer, GetNextItemIdxFromNoCurrentItemGivesTheFirstItem)
{
  TestablePlayListPlayer player;
  player.SetCurrentPlaylist(PLAYLIST::Id::TYPE_VIDEO);
  FillWithTwoItems(player, PLAYLIST::Id::TYPE_VIDEO);

  player.SetCurrentItemIdx(-1);
  ASSERT_EQ(-1, player.GetCurrentItemIdx()) << "the no-current-item state under test was not set";

  EXPECT_EQ(0, player.GetNextItemIdx(1));
}

TEST_F(TestPlayListPlayer, GetNextItemIdxFromNoCurrentItemGivesTheFirstItemWithRepeatOne)
{
  TestablePlayListPlayer player;
  player.SetCurrentPlaylist(PLAYLIST::Id::TYPE_VIDEO);
  FillWithTwoItems(player, PLAYLIST::Id::TYPE_VIDEO);

  player.SetCurrentItemIdx(-1);
  ASSERT_EQ(-1, player.GetCurrentItemIdx()) << "the no-current-item state under test was not set";

  player.SetRepeatDirectly(PLAYLIST::Id::TYPE_VIDEO, PLAYLIST::RepeatState::ONE);
  ASSERT_TRUE(player.IsRepeatedOne(PLAYLIST::Id::TYPE_VIDEO)) << "repeat one was not set";

  // Without the fix this answers -1: the repeat-one branch returns the current index unchanged,
  // and PlayNext() treats a negative index as nothing to play.
  EXPECT_EQ(0, player.GetNextItemIdx(1));
}

TEST_F(TestPlayListPlayer, GetNextItemIdxWithRepeatOneRepeatsTheCurrentItem)
{
  TestablePlayListPlayer player;
  player.SetCurrentPlaylist(PLAYLIST::Id::TYPE_VIDEO);
  FillWithTwoItems(player, PLAYLIST::Id::TYPE_VIDEO);

  player.SetCurrentItemIdx(1);
  ASSERT_EQ(1, player.GetCurrentItemIdx()) << "the current item under test was not set";

  player.SetRepeatDirectly(PLAYLIST::Id::TYPE_VIDEO, PLAYLIST::RepeatState::ONE);
  ASSERT_TRUE(player.IsRepeatedOne(PLAYLIST::Id::TYPE_VIDEO)) << "repeat one was not set";

  EXPECT_EQ(1, player.GetNextItemIdx(1));
}

TEST_F(TestPlayListPlayer, ClearingTheCurrentPlaylistKeepsThePlaybackStartedState)
{
  TestablePlayListPlayer player;
  player.SetCurrentPlaylist(PLAYLIST::Id::TYPE_VIDEO);
  FillWithTwoItems(player, PLAYLIST::Id::TYPE_VIDEO);
  player.SetCurrentItemIdx(0);

  CGUIMessage started(GUI_MSG_PLAYBACK_STARTED, 0, 0);
  player.OnMessage(started);
  ASSERT_TRUE(player.PlaybackStarted()) << "the playing state under test was not set";

  player.ClearPlaylist(PLAYLIST::Id::TYPE_VIDEO);

  EXPECT_EQ(-1, player.GetCurrentItemIdx());
  EXPECT_TRUE(player.PlaybackStarted());
  EXPECT_EQ(PLAYLIST::Id::TYPE_VIDEO, player.GetCurrentPlaylist());
}

TEST(TestExecuteAddonParams, ACommaInAnObjectValueStaysInOneArgument)
{
  const std::vector<std::string> argv = ArgumentsSeenByTheAddon(
      ParseExecuteAddonParams(MakeRequest(ObjectParams("title", "Peaches, Herb"))).command);

  ASSERT_EQ(2U, argv.size());
  EXPECT_EQ(ADDON_ID, argv[0]);
  EXPECT_EQ("title=Peaches, Herb", argv[1]);
}

TEST(TestExecuteAddonParams, AQuoteInAnObjectValueStaysInOneArgument)
{
  const std::vector<std::string> argv = ArgumentsSeenByTheAddon(
      ParseExecuteAddonParams(MakeRequest(ObjectParams("quote", "say \"hi\", then go"))).command);

  ASSERT_EQ(2U, argv.size());
  EXPECT_EQ("quote=say \"hi\", then go", argv[1]);
}

TEST(TestExecuteAddonParams, ACommaInAnArrayValueStaysInOneArgument)
{
  CVariant params(CVariant::VariantTypeArray);
  params.push_back("Peaches, Herb");

  const std::vector<std::string> argv =
      ArgumentsSeenByTheAddon(ParseExecuteAddonParams(MakeRequest(params)).command);

  ASSERT_EQ(2U, argv.size());
  EXPECT_EQ("Peaches, Herb", argv[1]);
}

std::string BuildArguments(const CVariant& params)
{
  std::string argv;

  if (params.isObject())
  {
    for (CVariant::const_iterator_map it = params.begin_map(); it != params.end_map(); ++it)
    {
      if (it != params.begin_map())
      {
        argv += ",";
      }
      argv += it->first + "=" + it->second.asString();
    }
  }
  else if (params.isArray())
  {
    for (CVariant::const_iterator_array it = params.begin_array(); it != params.end_array(); ++it)
    {
      if (it != params.begin_array())
      {
        argv += ",";
      }
      argv += StringUtils::Paramify(it->asString());
    }
  }
  else if (params.isString())
  {
    if (!params.empty())
    {
      argv = StringUtils::Paramify(params.asString());
    }
  }

  return argv;
}

ParsedExecuteAddon ParseExecuteAddonParams(const CVariant& parameterObject)
{
  const std::string id = parameterObject["addonid"].asString();
  const CVariant& params = parameterObject["params"];

  ParsedExecuteAddon parsed;
  parsed.wait = parameterObject["wait"].asBoolean();

  const std::string argv = BuildArguments(params);
  if (params.empty())
  {
    parsed.command = StringUtils::Format("RunAddon({})", id);
  }
  else
  {
    parsed.command = StringUtils::Format("RunAddon({}, {})", id, argv);
  }

  return parsed;
}

CVariant MakeRequest(const CVariant& params)
{
  CVariant request(CVariant::VariantTypeObject);
  request["addonid"] = ADDON_ID;
  request["params"] = params;
  request["wait"] = false;

  return request;
}

CVariant ObjectParams(const std::string& key, const std::string& value)
{
  CVariant params(CVariant::VariantTypeObject);
  params[key] = value;

  return params;
}

std::vector<std::string> ArgumentsSeenByTheAddon(const std::string& command)
{
  const CExecString exec(command);
  EXPECT_TRUE(exec.IsValid()) << command;

  return exec.GetParams();
}

TEST(TestExecuteAddonParams, NoParamsGivesTheBareBuiltin)
{
  CVariant request(CVariant::VariantTypeObject);
  request["addonid"] = ADDON_ID;
  request["params"] = "";
  request["wait"] = false;

  EXPECT_EQ("RunAddon(script.toolbox)", ParseExecuteAddonParams(request).command);
}

TEST(TestExecuteAddonParams, ObjectParamsBecomeKeyValueArguments)
{
  CVariant params(CVariant::VariantTypeObject);
  params["info"] = "builtin";
  params["id"] = "ReloadSkin()";

  const std::vector<std::string> argv =
      ArgumentsSeenByTheAddon(ParseExecuteAddonParams(MakeRequest(params)).command);

  ASSERT_EQ(3U, argv.size());
  EXPECT_EQ(ADDON_ID, argv[0]);
  // CVariant orders an object's members by key, so "id" precedes "info".
  EXPECT_EQ("id=ReloadSkin()", argv[1]);
  EXPECT_EQ("info=builtin", argv[2]);
}

TEST(TestExecuteAddonParams, WaitIsReadFromTheDeclaredTopLevelParameter)
{
  CVariant request = MakeRequest(ObjectParams("info", "builtin"));
  request["wait"] = true;

  EXPECT_TRUE(ParseExecuteAddonParams(request).wait);
}

TEST(TestExecuteAddonParams, AWaitKeyInsideParamsIsJustAnAddonArgument)
{
  const ParsedExecuteAddon parsed =
      ParseExecuteAddonParams(MakeRequest(ObjectParams("wait", "true")));

  EXPECT_FALSE(parsed.wait);

  const std::vector<std::string> argv = ArgumentsSeenByTheAddon(parsed.command);
  ASSERT_EQ(2U, argv.size());
  EXPECT_EQ("wait=true", argv[1]);
}

TEST(TestUPnPPlaybackState, NothingIsWatchedBeforeAFileStarts)
{
  CPlaybackState state;

  EXPECT_FALSE(state.IsStarted());
  EXPECT_FALSE(state.HasEnded("STOPPED"));
  EXPECT_FALSE(state.Finish());
}

TEST(TestUPnPPlaybackState, AStoppedRendererEndsTheFileItWasPlaying)
{
  CPlaybackState state;

  state.Opening();
  state.Started();

  EXPECT_FALSE(state.HasEnded("PLAYING"));
  EXPECT_FALSE(state.HasEnded("TRANSITIONING"));
  EXPECT_TRUE(state.HasEnded("STOPPED"));
}

TEST(TestUPnPPlaybackState, PlaybackEndsOnlyOnce)
{
  CPlaybackState state;

  state.Opening();
  state.Started();

  ASSERT_TRUE(state.HasEnded("STOPPED"));
  EXPECT_TRUE(state.Finish());

  EXPECT_FALSE(state.HasEnded("STOPPED"));
  EXPECT_FALSE(state.Finish());
}

TEST(TestUPnPPlaybackState, TheStopThatStartsTheNextFileDoesNotEndPlayback)
{
  CPlaybackState state;

  state.Opening();
  state.Started();
  ASSERT_FALSE(state.HasEnded("PLAYING"));

  // the user picks another file while that one is playing
  state.Opening();

  EXPECT_FALSE(state.HasEnded("STOPPED"));

  state.Started();

  EXPECT_FALSE(state.HasEnded("PLAYING"));
  EXPECT_TRUE(state.HasEnded("STOPPED"));
}

TEST(TestUPnPPlaybackState, AnOpenThatFailsLeavesNothingWatched)
{
  CPlaybackState state;

  state.Opening();
  state.Started();
  ASSERT_TRUE(state.IsStarted());

  state.Opening();

  EXPECT_FALSE(state.IsStarted());
  EXPECT_FALSE(state.HasEnded("STOPPED"));
  EXPECT_FALSE(state.Finish());
}

void OnGetProtocolInfoResult(NPT_Result res,
                               PLT_DeviceDataReference& device,
                               PLT_StringList* sources,
                               PLT_StringList* sinks,
                               void* userdata) override
  {
    if (NPT_FAILED(res))
      return;

    if (sinks)
      StoreProtocolInfo(device, "SinkProtocolInfo", *sinks);
    if (sources)
      StoreProtocolInfo(device, "SourceProtocolInfo", *sources);
  }

static void StoreProtocolInfo(PLT_DeviceDataReference& device,
                                const char* variable,
                                const PLT_StringList& values)
  {
    PLT_Service* service = nullptr;
    if (NPT_FAILED(
            device->FindServiceByType("urn:schemas-upnp-org:service:ConnectionManager:*", service)))
      return;

    NPT_String joined;
    for (NPT_List<NPT_String>::Iterator value = values.GetFirstItem(); value; ++value)
    {
      if (!joined.IsEmpty())
        joined += ",";
      joined += *value;
    }

    if (!joined.IsEmpty())
      service->SetStateVariable(variable, joined);
  }

void AddAlternateMimeResources(PLT_MediaObject& object)
{
  // Content types that are in common use under more than one name. A renderer selects a
  // resource by matching its protocolInfo against the sink list it advertises, so a resource
  // offered under one spelling is invisible to a renderer that names the other.
  static constexpr std::pair<const char*, const char*> alternates[] = {
      {"audio/x-flac", "audio/flac"},
      {"audio/x-ms-wma", "audio/wma"},
  };

  // The loop appends to the list it reads, so the original count is taken first.
  const NPT_Cardinal count = object.m_Resources.GetItemCount();

  for (const auto& [name, alternate] : alternates)
  {
    for (NPT_Cardinal i = 0; i < count; i++)
    {
      const NPT_String contentType = object.m_Resources[i].m_ProtocolInfo.GetContentType();

      NPT_String from;
      NPT_String to;
      if (contentType.Compare(name, true) == 0)
      {
        from = name;
        to = alternate;
      }
      else if (contentType.Compare(alternate, true) == 0)
      {
        from = alternate;
        to = name;
      }
      else
      {
        continue;
      }

      // Per resource, not per object: each carries its own uri, and only the one on the
      // renderer's network is any use to it.
      bool present = false;
      for (NPT_Cardinal j = 0; j < object.m_Resources.GetItemCount(); j++)
      {
        if (object.m_Resources[j].m_Uri == object.m_Resources[i].m_Uri &&
            object.m_Resources[j].m_ProtocolInfo.GetContentType().Compare(to, true) == 0)
        {
          present = true;
          break;
        }
      }
      if (present)
        continue;

      PLT_MediaItemResource resource = object.m_Resources[i];
      NPT_String protocolInfo = resource.m_ProtocolInfo.ToString();
      protocolInfo.Replace(":" + from + ":", ":" + to + ":");
      resource.m_ProtocolInfo = PLT_ProtocolInfo(protocolInfo);
      object.m_Resources.Add(resource);
    }
  }
}

void PreferResourceAddresses(PLT_MediaObject& object, const std::vector<NPT_UInt32>& preferred)
{
  if (preferred.empty())
    return;

  NPT_Array<PLT_MediaItemResource> front;
  NPT_Array<PLT_MediaItemResource> back;

  for (NPT_Cardinal i = 0; i < object.m_Resources.GetItemCount(); i++)
  {
    const PLT_MediaItemResource& resource = object.m_Resources[i];
    NPT_IpAddress host;
    const bool wanted =
        NPT_SUCCEEDED(host.Parse(NPT_HttpUrl(resource.m_Uri).GetHost())) &&
        std::find(preferred.begin(), preferred.end(), host.AsLong()) != preferred.end();
    if (wanted)
      front.Add(resource);
    else
      back.Add(resource);
  }

  if (front.GetItemCount() == 0)
    return;

  for (NPT_Cardinal i = 0; i < back.GetItemCount(); i++)
    front.Add(back[i]);

  object.m_Resources = front;
}

void SortResourcesForRenderer(PLT_MediaObject& object, const NPT_IpAddress& renderer)
{
  NPT_List<NPT_NetworkInterface*> interfaces;
  if (NPT_FAILED(NPT_NetworkInterface::GetNetworkInterfaces(interfaces)))
    return;

  std::vector<NPT_UInt32> reachable;
  for (NPT_List<NPT_NetworkInterface*>::Iterator it = interfaces.GetFirstItem(); it; ++it)
  {
    const NPT_List<NPT_NetworkInterfaceAddress>& addresses = (*it)->GetAddresses();
    for (NPT_List<NPT_NetworkInterfaceAddress>::Iterator addr = addresses.GetFirstItem(); addr;
         ++addr)
    {
      NPT_NetworkInterfaceAddress candidate = *addr;
      if (candidate.IsAddressInNetwork(renderer))
        reachable.push_back(candidate.GetPrimaryAddress().AsLong());
    }
  }
  interfaces.Apply(NPT_ObjectDeleter<NPT_NetworkInterface>());

  PreferResourceAddresses(object, reachable);
}

PLT_MediaItem MakeObjectWithResource(const char* protocolInfo)
{
  PLT_MediaItem object;
  PLT_MediaItemResource resource;
  resource.m_Uri = "http://192.0.2.1:8080/song";
  resource.m_ProtocolInfo = PLT_ProtocolInfo(protocolInfo);
  object.m_Resources.Add(resource);
  return object;
}

void AddResource(PLT_MediaObject& object, const char* uri, const char* protocolInfo)
{
  PLT_MediaItemResource resource;
  resource.m_Uri = uri;
  resource.m_ProtocolInfo = PLT_ProtocolInfo(protocolInfo);
  object.m_Resources.Add(resource);
}

NPT_UInt32 AddressOf(const char* literal)
{
  NPT_IpAddress address;
  address.Parse(literal);
  return address.AsLong();
}

bool HasContentType(const PLT_MediaObject& object, const char* contentType)
{
  for (NPT_Cardinal i = 0; i < object.m_Resources.GetItemCount(); i++)
  {
    if (object.m_Resources[i].m_ProtocolInfo.GetContentType().Compare(contentType, true) == 0)
      return true;
  }
  return false;
}

TEST(TestUPnPInternal, AddAlternateMimeResourcesOffersRegisteredFlacSpelling)
{
  PLT_MediaItem object = MakeObjectWithResource("http-get:*:audio/x-flac:*");

  AddAlternateMimeResources(object);

  EXPECT_EQ(2u, object.m_Resources.GetItemCount());
  EXPECT_TRUE(HasContentType(object, "audio/x-flac"));
  EXPECT_TRUE(HasContentType(object, "audio/flac"));
}

TEST(TestUPnPInternal, AddAlternateMimeResourcesOffersLegacyFlacSpelling)
{
  PLT_MediaItem object = MakeObjectWithResource("http-get:*:audio/flac:*");

  AddAlternateMimeResources(object);

  EXPECT_EQ(2u, object.m_Resources.GetItemCount());
  EXPECT_TRUE(HasContentType(object, "audio/flac"));
  EXPECT_TRUE(HasContentType(object, "audio/x-flac"));
}

TEST(TestUPnPInternal, AddAlternateMimeResourcesKeepsUriAndProtocol)
{
  PLT_MediaItem object = MakeObjectWithResource("http-get:*:audio/x-flac:DLNA.ORG_PN=FLAC");

  AddAlternateMimeResources(object);

  ASSERT_EQ(2u, object.m_Resources.GetItemCount());
  EXPECT_STREQ("http://192.0.2.1:8080/song", object.m_Resources[1].m_Uri.GetChars());
  EXPECT_STREQ("http-get", object.m_Resources[1].m_ProtocolInfo.GetProtocol().GetChars());
  EXPECT_STREQ("audio/flac", object.m_Resources[1].m_ProtocolInfo.GetContentType().GetChars());
}

TEST(TestUPnPInternal, AddAlternateMimeResourcesDoesNotDuplicate)
{
  PLT_MediaItem object = MakeObjectWithResource("http-get:*:audio/x-flac:*");
  PLT_MediaItemResource other;
  other.m_Uri = "http://192.0.2.1:8080/song";
  other.m_ProtocolInfo = PLT_ProtocolInfo("http-get:*:audio/flac:*");
  object.m_Resources.Add(other);

  AddAlternateMimeResources(object);

  EXPECT_EQ(2u, object.m_Resources.GetItemCount());
}

TEST(TestUPnPInternal, AddAlternateMimeResourcesLeavesUnrelatedTypes)
{
  PLT_MediaItem object = MakeObjectWithResource("http-get:*:audio/mpeg:*");

  AddAlternateMimeResources(object);

  EXPECT_EQ(1u, object.m_Resources.GetItemCount());
  EXPECT_TRUE(HasContentType(object, "audio/mpeg"));
}

TEST(TestUPnPInternal, PreferResourceAddressesPutsAReachableAddressFirst)
{
  PLT_MediaItem object;
  AddResource(object, "http://10.20.100.8:1298/song", "http-get:*:audio/x-flac:*");
  AddResource(object, "http://192.0.2.1:1298/song", "http-get:*:audio/x-flac:*");
  AddResource(object, "http://169.254.96.137:1298/song", "http-get:*:audio/x-flac:*");

  PreferResourceAddresses(object, {AddressOf("192.0.2.1")});

  ASSERT_EQ(3u, object.m_Resources.GetItemCount());
  EXPECT_STREQ("http://192.0.2.1:1298/song", object.m_Resources[0].m_Uri.GetChars());
}

TEST(TestUPnPInternal, PreferResourceAddressesKeepsTheRestInOrder)
{
  PLT_MediaItem object;
  AddResource(object, "http://10.20.100.8:1298/song", "http-get:*:audio/x-flac:*");
  AddResource(object, "http://192.0.2.1:1298/song", "http-get:*:audio/x-flac:*");
  AddResource(object, "http://169.254.96.137:1298/song", "http-get:*:audio/x-flac:*");

  PreferResourceAddresses(object, {AddressOf("192.0.2.1")});

  EXPECT_STREQ("http://10.20.100.8:1298/song", object.m_Resources[1].m_Uri.GetChars());
  EXPECT_STREQ("http://169.254.96.137:1298/song", object.m_Resources[2].m_Uri.GetChars());
}

TEST(TestUPnPInternal, PreferResourceAddressesLeavesTheOrderAloneWhenNoneMatch)
{
  PLT_MediaItem object;
  AddResource(object, "http://10.20.100.8:1298/song", "http-get:*:audio/x-flac:*");
  AddResource(object, "http://192.0.2.1:1298/song", "http-get:*:audio/x-flac:*");

  PreferResourceAddresses(object, {AddressOf("203.0.113.9")});

  EXPECT_STREQ("http://10.20.100.8:1298/song", object.m_Resources[0].m_Uri.GetChars());
}

TEST(TestUPnPInternal, AddAlternateMimeResourcesOffersEveryAddress)
{
  PLT_MediaItem object;
  AddResource(object, "http://192.0.2.1:1298/song", "http-get:*:audio/x-flac:*");
  AddResource(object, "http://192.0.2.2:1298/song", "http-get:*:audio/x-flac:*");

  AddAlternateMimeResources(object);

  ASSERT_EQ(4u, object.m_Resources.GetItemCount());
  int alternates = 0;
  for (NPT_Cardinal i = 0; i < object.m_Resources.GetItemCount(); i++)
  {
    if (object.m_Resources[i].m_ProtocolInfo.GetContentType().Compare("audio/flac", true) == 0)
      alternates++;
  }
  EXPECT_EQ(2, alternates);
}

