TEST(TestMusicInfoTagLoaderMatroska, DoesNotGiveTheOnlyChapterATagNamingAnotherOne)
{
  const CURL url(XBMC_REF_FILE_PATH("xbmc/filesystem/test/data/audiobook/straychapteruid.mka"));

  const MatroskaAlbum album = ReadMatroskaTags(url, nullptr);

  ASSERT_EQ(1u, album.chapters.size());

  // The chapter keeps the only name it was given, its ChapterDisplay - not the stray tag's.
  const auto chapterTitle = album.chapters[0].tags.find("TITLE");
  ASSERT_NE(album.chapters[0].tags.end(), chapterTitle);
  EXPECT_EQ("DISPLAY Only Track", chapterTitle->second);

  /*!
   * And the stray tag reached the file, where it outranks the Segment title: a tag the file
   * states outright says more about it than the container's own name for itself.
   */
  const auto fileTitle = album.fileTags.find("TITLE");
  ASSERT_NE(album.fileTags.end(), fileTitle);
  EXPECT_EQ("TAG Stray Title", fileTitle->second);
}

void CollectTags(const AVDictionary* metadata, std::map<std::string, std::string>& tags)
{
  const AVDictionaryEntry* entry = nullptr;
  while ((entry = av_dict_get(metadata, "", entry, AV_DICT_IGNORE_SUFFIX)))
    tags[StringUtils::ToUpper(entry->key)] = entry->value;
}

void CollectFileTags(const AVDictionary* metadata, MatroskaAlbum& album)
{
  //! TargetTypeValue 50 and 60: what the file as a whole is part of.
  static constexpr std::array<std::string_view, 11> albumLevel = {
      "ALBUM", "OPERA",  "CONCERT", "MOVIE",  "EPISODE", "EDITION",
      "ISSUE", "VOLUME", "OPUS",    "SEASON", "SEQUEL"};
  //! TargetTypeValue 30. In the file's own metadata it names no chapter, so it describes the file.
  static constexpr std::array<std::string_view, 3> trackLevel = {"TRACK", "SONG", "CHAPTER"};

  const AVDictionaryEntry* entry = nullptr;
  while ((entry = av_dict_get(metadata, "", entry, AV_DICT_IGNORE_SUFFIX)))
  {
    const std::string key = StringUtils::ToUpper(entry->key);

    /*!
    * Not tags at all: FFmpeg reports MuxingApp as an encoder and DateUTC as a creation time, both
    * mandatory or near enough that every Matroska would look like it carries tags. Neither is
    * mapped to a music field, so dropping them costs nothing and lets what remains answer whether
    * the file was tagged.
    */
    if (key == "ENCODER" || key == "CREATION_TIME")
      continue;

    const size_t slash = key.find('/');
    if (slash == std::string::npos)
    {
      album.fileTags[key] = entry->value;
      continue;
    }

    const std::string_view prefix{key.data(), slash};
    const std::string name = key.substr(slash + 1);
    if (std::find(albumLevel.begin(), albumLevel.end(), prefix) != albumLevel.end())
      album.albumTags[name] = entry->value;
    else if (std::find(trackLevel.begin(), trackLevel.end(), prefix) != trackLevel.end())
      album.fileTags[name] = entry->value;
  }
}

MatroskaAlbum ReadWithFFmpegImpl(const AVFormatContext* fctx)
{
  MatroskaAlbum album;

  if (!fctx)
    return album;

  CollectFileTags(fctx->metadata, album);

  for (unsigned int i = 0; fctx->chapters && i < fctx->nb_chapters; ++i)
  {
    const AVChapter* chapter = fctx->chapters[i];
    if (!chapter || chapter->start < 0)
      continue;

    ChapterTags& entry = album.chapters.emplace_back();
    CollectTags(chapter->metadata, entry.tags);
    entry.start = chapter->start * av_q2d(chapter->time_base);

    /*!
     * A chapter that declared no ChapterTimeEnd never reaches here open: compute_chapters_end()
     * runs inside avformat_find_stream_info() and closes it with the next chapter's start, bounded
     * by the file's duration. That is the right answer whenever the duration is, so the end is
     * taken as given.
     *
     * Where the demuxer had to estimate a duration and estimated one below the chapter timeline,
     * what it writes instead is the bound itself, or the chapter's own start where even that
     * precedes it - an end equal to the start, a chapter of no length, which IsTrack() drops. A
     * file declaring neither its Duration nor any ChapterTimeEnd is therefore not expanded on this
     * reader, where TagLib expands it - see
     * TestMatroskaTagReaderFFmpeg.ClampsEveryEndOfAFileThatDeclaresNoLength.
     *
     * Zero is how a chapter with no end reaches IsTrack() and CAudioBookFileDirectory, which serve
     * either reader. An end that still precedes its start is written as that same zero, so it is
     * closed against the file's duration rather than dropped - the two states share a spelling,
     * and telling them apart would take a flag on ChapterTags. Only a file whose chapter
     * timestamps are already malformed reaches the second.
     */
    const double end = chapter->end * av_q2d(chapter->time_base);
    entry.end = end >= entry.start ? end : 0.0;
  }

  return album;
}

bool AppendIfNotDuplicate(std::string& currentValue,
                          const std::string& newValue,
                          const std::string& tagname)
{
  const std::vector<std::string>& separators = (tagname.find("ARTIST") != std::string::npos)
                                                   ? SupportedArtistMultiValueSeparators
                                                   : SupportedMultiValueSeparators;

  try
  {
    std::vector<std::string> existingValues = StringUtils::Split(currentValue, separators);

    for (auto& existing : existingValues)
    {
      StringUtils::Trim(existing);
      if (existing.empty())
        continue; // mirrors RemoveEmptyEntries
      if (StringUtils::EqualsNoCase(existing, newValue))
        return false;
    }
  }
  catch (const std::exception& ex)
  {
    CLog::Log(LOGERROR, "AppendIfNotDuplicate: {}", ex.what());
    return false;
  }

  if (currentValue.empty())
    currentValue = newValue;
  else
    currentValue += MatroskaTagMapping::MultiValueSeparator + newValue;

  return true;
}

void AddTagValue(std::map<std::string, std::string>& tags,
                 const std::string& name,
                 const std::string& value)
{
  const auto it = tags.find(name);
  if (it == tags.end())
  {
    tags.emplace(name, value);
    return;
  }

  if (MatroskaTagMapping::HoldsSeveralValues(name))
    AppendIfNotDuplicate(it->second, value, name);
}

FileProperties ReadFileProperties(TagLib::Matroska::File& file)
{
  const TagLib::Matroska::Properties* audioProps = file.audioProperties();
  if (!audioProps)
    return {};

  // Milliseconds: lengthInSeconds() truncates, and this is what gives a last chapter with no
  // ChapterTimeEnd its end.
  return {audioProps->lengthInMilliseconds() / 1000.0, audioProps->title().to8Bit(true)};
}

SelectedEdition CollectChapters(TagLib::Matroska::File& file, MatroskaAlbum& album)
{
  SelectedEdition selected;

  const TagLib::Matroska::Chapters* chapters = file.chapters();
  if (!chapters)
    return selected;

  const TagLib::Matroska::Chapters::ChapterEditionList& editions = chapters->chapterEditionList();
  const TagLib::Matroska::ChapterEdition* selectedEdition = nullptr;
  for (const auto& edition : editions)
  {
    if (!selectedEdition || edition.isDefault())
      selectedEdition = &edition;
    if (edition.isDefault())
      break;
  }

  for (const auto& edition : editions)
  {
    if (&edition == selectedEdition)
      continue;
    // Zero names no chapter: it is what a chapter declaring no ChapterUID reports, and equally
    // what a tag carrying none reports. Filing it would drop every such tag as belonging to an
    // edition this file does not play.
    for (const auto& chapter : edition.chapterList())
      if (chapter.uid() > 0)
        selected.unselectedChapterUids.insert(chapter.uid());
  }

  if (!selectedEdition)
    return selected;

  selected.uid = selectedEdition->uid();
  for (const auto& chapter : selectedEdition->chapterList())
  {
    const unsigned long long chapUid = chapter.uid();

    std::string chapterName;
    if (chapUid > 0 && !chapter.displayList().isEmpty())
    {
      // Match VB behavior: keep the last display name
      for (const auto& display : chapter.displayList())
        chapterName = display.string().toCString(true);
    }

    // Only a chapter that named itself can be found by name; nameless ones would take turns
    // owning the key zero.
    if (chapUid > 0)
      selected.chapterIndex[chapUid] = album.chapters.size();
    ChapterTags& entry = album.chapters.emplace_back();
    entry.tags.emplace("CHAPTERNAME", chapterName);
    entry.start = static_cast<double>(chapter.timeStart()) / 1000000000.0;
    entry.end = static_cast<double>(chapter.timeEnd()) / 1000000000.0;
  }

  /*!
  * A UID the selected edition carries as well names a chapter this file does play. Editions
  * sharing chapter UIDs is legal - an ordered cut reusing the transfer's chapters is the usual
  * reason - so what is left behind is only what the selected edition does not have, and a tag
  * naming one of those is dropped in CollectSimpleTags() rather than applied to a chapter it
  * does not describe.
  */
  for (const auto& entry : selected.chapterIndex)
    selected.unselectedChapterUids.erase(entry.first);

  return selected;
}

void FillMissingEndTimes(MatroskaAlbum& album, double fileDuration)
{
  for (size_t i = 0; i < album.chapters.size(); ++i)
  {
    if (album.chapters[i].end > 0.0)
      continue;
    const double end = (i + 1 < album.chapters.size()) ? album.chapters[i + 1].start : fileDuration;
    if (end > album.chapters[i].start)
      album.chapters[i].end = end;
  }
}

void CollectSimpleTags(const TagLib::Matroska::SimpleTagsList& list,
                       MatroskaAlbum& album,
                       const SelectedEdition& edition)
{
  auto& fileTags = album.fileTags;

  auto namesAnotherEdition = [&edition](const TagLib::Matroska::SimpleTag& tag)
  { return tag.editionUid() != 0 && tag.editionUid() != edition.uid; };
  // An edition, volume or opus tag describes a grouping above the album, which for one file is
  // still the whole file - so it lands on the album rather than nowhere.
  auto isAlbumLevel = [](TagLib::Matroska::SimpleTag::TargetTypeValue level)
  {
    return level == TagLib::Matroska::SimpleTag::Album ||
           level == TagLib::Matroska::SimpleTag::Edition;
  };

  for (const TagLib::Matroska::SimpleTag& tag : list)
  {
    if (!isAlbumLevel(tag.targetTypeValue()) || namesAnotherEdition(tag))
      continue;

    const std::string name = StringUtils::ToUpper(tag.name().to8Bit(true));
    AddTagValue(album.albumTags, name, tag.toString().to8Bit(true));
  }

  for (const TagLib::Matroska::SimpleTag& tag : list)
  {
    const TagLib::Matroska::SimpleTag::TargetTypeValue level = tag.targetTypeValue();
    if (isAlbumLevel(level) || namesAnotherEdition(tag))
      continue;

    const std::string name = StringUtils::ToUpper(tag.name().to8Bit(true));
    const std::string value = tag.toString().to8Bit(true);

    /*!
    * A tag with no TargetTypeValue describes the file: taggers that ignore the spec write album
    * metadata that way, and dropping it would lose the lot.
    */
    if (level == TagLib::Matroska::SimpleTag::None)
    {
      AddTagValue(fileTags, name, value);
      continue;
    }

    if (level != TagLib::Matroska::SimpleTag::Track)
      continue;

    /*!
    * A tag naming a chapter of an edition that was not selected describes a track this file will
    * not produce. Neither merging it into a chapter it does not describe nor promoting it to the
    * album is right, so it goes no further.
    */
    const unsigned long long chapterUid = tag.chapterUid();
    if (chapterUid > 0 && edition.unselectedChapterUids.count(chapterUid) != 0)
      continue;

    /*!
    * A tag with no ChapterUID describes the only track there is - MP3tag writes song tags that
    * way - so a single chapter file takes it. One naming a chapter goes to that chapter, and one
    * naming a chapter this file does not have falls back to the album. Zero is what TagLib
    * reports for a tag carrying no ChapterUID at all; every other value names a chapter.
    *
    * Which is why a named chapter is looked up whatever the file's chapter count. Taking the only
    * chapter first would give it every track level tag, including one naming a chapter that is
    * not it - a stale UID left by a tagger, or one belonging to a file this was cut from - and
    * the fallback above is the whole reason a name is read at all.
    */
    ChapterTags* target = nullptr;
    if (chapterUid > 0)
    {
      if (const auto it = edition.chapterIndex.find(chapterUid); it != edition.chapterIndex.end())
        target = &album.chapters[it->second];
    }
    else if (album.chapters.size() == 1)
      target = &album.chapters.front();

    // Either the file has no chapters at all, or names one it does not contain. Either way the tag
    // describes the file rather than a track of it.
    AddTagValue(target ? target->tags : fileTags, name, value);
  }
}

void FillTitlesFromDisplayNames(MatroskaAlbum& album)
{
  for (auto& chapter : album.chapters)
  {
    const auto chapterName = chapter.tags.find("CHAPTERNAME");
    if (chapterName == chapter.tags.end() || chapterName->second.empty())
      continue;
    chapter.tags.emplace("TITLE", chapterName->second);
  }
}

MatroskaAlbum ReadWithTagLib(const CURL& url)
{
  MatroskaAlbum album;

  MatroskaTagLibStream matroskaStream(url.Get());
  if (!matroskaStream.open())
    return album;

  std::unique_ptr<TagLib::Matroska::File> matroskaFile;
  Matroska::Tag* matroskatag = nullptr;
  try
  {
    // MatroskaTagLibStream provides a 512 KiB read-ahead buffer and deferred seeks
    matroskaFile = std::make_unique<TagLib::Matroska::File>(&matroskaStream, true,
                                                            TagLib::AudioProperties::Fast);
    if (matroskaFile->isValid())
      matroskatag = matroskaFile->tag(true);
    if (!matroskatag)
      return album;

    const FileProperties properties = ReadFileProperties(*matroskaFile);

    const SelectedEdition edition = CollectChapters(*matroskaFile, album);
    FillMissingEndTimes(album, properties.duration);

    CollectSimpleTags(matroskatag->simpleTagsList(), album, edition);

    /*!
    * The Segment title names the file rather than its album, and FFmpeg's demuxer reports it as an
    * unprefixed title. Say the same, so that a file holding one song is titled the same way
    * whichever reader read it.
    *
    * After the tags rather than before: a TITLE SimpleTag carrying no level is filed here too, and
    * a tag the file states outright says more about it than the container's own title. Seeding
    * first would leave AddTagValue() to drop the explicit one, TITLE being a name that holds a
    * single value.
    */
    if (!properties.segmentTitle.empty())
      album.fileTags.emplace("TITLE", properties.segmentTitle);
    FillTitlesFromDisplayNames(album);

    // bufferedStream and matroskaFile are destroyed when scope exits.
  }
  catch (const std::exception& e)
  {
    CLog::Log(LOGERROR, "ReadWithTagLib: Exception while reading Matroska tags: {} {}",
              url.GetRedacted(), e.what());
  }

  return album;
}

void MUSIC_INFO::CloseOpenEndedChapters(MatroskaAlbum& album, double fileDuration)
{
  for (auto& chapter : album.chapters)
    if (chapter.end <= 0.0 && fileDuration > chapter.start)
      chapter.end = fileDuration;
}

bool MUSIC_INFO::IsTrack(double start, double end)
{
  // Still open after CloseOpenEndedChapters() means nothing could measure it. Nothing says it is
  // an artefact either, so it is kept.
  if (end <= 0.0)
    return true;

  // Rounded to milliseconds, as fine as a chapter is ever written. Seconds are scaled from
  // nanosecond ticks, and the difference of two such doubles lands just under the whole second
  // often enough to drop chapters that are exactly one second long.
  return std::llround((end - start) * 1000.0) >= MinimumTrackMilliseconds;
}

MatroskaAlbum MUSIC_INFO::ReadMatroskaTagsWithFFmpeg(const CURL& /*url*/,
                                                     const AVFormatContext* fctx)
{
  return ReadWithFFmpegImpl(fctx);
}

MatroskaAlbum MUSIC_INFO::ReadMatroskaTagsWithTagLib(const CURL& url,
                                                     const AVFormatContext* /*fctx*/)
{
  return ReadWithTagLib(url);
}

MatroskaAlbum MUSIC_INFO::ReadMatroskaTags(const CURL& url, const AVFormatContext* fctx)
{
  // TagLib wherever the version floor allows it, FFmpeg below that: fewer tags rather than none.
#ifdef HAS_TAGLIB_MATROSKA
  return ReadMatroskaTagsWithTagLib(url, fctx);
#else
  return ReadMatroskaTagsWithFFmpeg(url, fctx);
#endif
}

CGameUtils::GetDefaultGameClient(const std::string& path,
                                             const GameClientVector& candidates)
{
  if (path.empty())
    return "";

  CGameDatabase db;
  if (!db.Open())
    return "";

  const std::string gameClient = db.GameClients().GetGameClientForGame(path);
  if (gameClient.empty())
    return "";

  // A remembered emulator is a preference, not an instruction. It is only used
  // if it can still open this game: one set on a folder has no idea what else
  // was put in that folder later, and one set before the emulator was
  // uninstalled would otherwise stop the game loading at all. Where it does not
  // fit, say so and let the user be asked, which is what would have happened
  // had nothing been remembered.
  const bool bCanOpen = std::any_of(candidates.begin(), candidates.end(),
                                    [&gameClient](const GameClientPtr& candidate)
                                    { return candidate->ID() == gameClient; });
  if (!bCanOpen)
  {
    CLog::Log(LOGDEBUG, "GAME: Ignoring remembered emulator {} for {}: it can't open this game",
              gameClient, CURL::GetRedacted(path));
    return "";
  }

  CLog::Log(LOGDEBUG, "GAME: Opening {} with remembered emulator {}", CURL::GetRedacted(path),
            gameClient);

  return gameClient;
}

bool CGameUtils::ChooseAndSetDefaultGameClient(const CFileItem& item)
{
  using namespace ADDON;

  const std::string path = item.GetPath();
  if (path.empty())
    return false;

  // A folder can be given anything later, so it offers every emulator that is
  // installed. A game only offers the ones that can open it.
  GameClientVector emulators;
  if (item.IsFolder())
  {
    VECADDONS addons;
    CServiceBroker::GetBinaryAddonCache().GetAddons(addons, AddonType::GAMEDLL);
    for (const auto& addon : addons)
      emulators.emplace_back(std::static_pointer_cast<CGameClient>(addon));
  }
  else
  {
    GameClientVector installable;
    bool bHasVfsGameClient = false;
    GetGameClients(item, emulators, installable, bHasVfsGameClient);
  }

  CGUIDialogSelect* dialog =
      CServiceBroker::GetGUI()->GetWindowManager().GetWindow<CGUIDialogSelect>(
          WINDOW_DIALOG_SELECT);
  if (dialog == nullptr)
    return false;

  CGameDatabase db;
  if (!db.Open())
    return false;

  const std::string currentGameClient = db.GameClients().GetGameClient(path);

  dialog->Reset();
  dialog->SetHeading(CVariant{35510}); // "Default emulator"
  dialog->SetUseDetails(true);

  CFileItemList items;

  // First, so that clearing is as easy to reach as setting
  {
    CFileItemPtr noneItem = std::make_shared<CFileItem>(
        CServiceBroker::GetResourcesComponent().GetLocalizeStrings().Get(231)); // "None"
    noneItem->SetPath("");
    items.Add(std::move(noneItem));
  }

  for (const auto& emulator : emulators)
  {
    CFileItemPtr emulatorItem(XFILE::CAddonsDirectory::FileItemFromAddon(emulator, emulator->ID()));
    if (emulator->ID() == currentGameClient)
    {
      emulatorItem->SetLabel2(
          CServiceBroker::GetResourcesComponent().GetLocalizeStrings().Get(35511)); // "Current"
      emulatorItem->Select(true);
    }
    items.Add(std::move(emulatorItem));
  }

  dialog->SetItems(items);
  dialog->Open();

  if (!dialog->IsConfirmed())
    return false;

  const int selectedIndex = dialog->GetSelectedItem();
  if (selectedIndex < 0 || selectedIndex >= items.Size())
    return false;

  // An empty path is the "None" entry, which forgets rather than stores
  const std::string gameClient = items[selectedIndex]->GetPath();

  if (!db.GameClients().SetGameClient(path, gameClient))
    return false;

  if (gameClient.empty())
    CLog::Log(LOGDEBUG, "GAME: Forgot the emulator for {}", CURL::GetRedacted(path));
  else
    CLog::Log(LOGDEBUG, "GAME: Remembered emulator {} for {}", gameClient, CURL::GetRedacted(path));

  return true;
}

void CGameClientTable::Create()
{
  CLog::Log(LOGINFO, "GAME: Creating gameclient table");

  m_database.ExecuteQuery("CREATE TABLE gameclient ("
                          "idPath integer primary key,"
                          "path text,"
                          "gameClient text)");
}

void CGameClientTable::CreateAnalytics()
{
  CLog::Log(LOGINFO, "GAME: Creating gameclient index");

  // Unique: a path has one emulator, so storing a second replaces the first
  m_database.ExecuteQuery("CREATE UNIQUE INDEX idxGameClientPath ON gameclient(path)");
}

void CGameClientTable::UpdateTables(int version)
{
  // No schema changes yet
  (void)version;
}

bool CGameClientTable::SetGameClient(const std::string& path, const std::string& gameClient)
{
  if (path.empty())
    return false;

  // No emulator means the path is no longer remembered, rather than remembered
  // as nothing
  if (gameClient.empty())
    return ClearGameClient(path);

  const std::string sql =
      m_database.PrepareSQL("REPLACE INTO gameclient (path, gameClient) VALUES ('%s', '%s')",
                            path.c_str(), gameClient.c_str());

  if (!m_database.ExecuteQuery(sql))
  {
    CLog::Log(LOGERROR, "GAME: Failed to remember emulator {} for {}", gameClient, path);
    return false;
  }

  return true;
}

std::string CGameClientTable::GetGameClient(const std::string& path)
{
  if (path.empty())
    return "";

  const std::string sql =
      m_database.PrepareSQL("SELECT gameClient FROM gameclient WHERE path='%s'", path.c_str());

  return m_database.GetSingleValue(sql);
}

std::string CGameClientTable::GetGameClientForGame(const std::string& path)
{
  if (path.empty())
    return "";

  // The game's own emulator wins, which is what makes a per-game choice an
  // override of the folder it sits in
  std::string gameClient = GetGameClient(path);
  if (!gameClient.empty())
    return gameClient;

  // Otherwise the nearest folder above it that has one
  std::string currentPath = path;
  for (unsigned int i = 0; i < MAX_FOLDER_DEPTH; ++i)
  {
    std::string parentPath;
    if (!URIUtils::GetParentPath(currentPath, parentPath) || parentPath.empty() ||
        parentPath == currentPath)
      break;

    gameClient = GetGameClient(parentPath);
    if (!gameClient.empty())
      return gameClient;

    currentPath = std::move(parentPath);
  }

  return "";
}

bool CGameClientTable::ClearGameClient(const std::string& path)
{
  if (path.empty())
    return false;

  const std::string sql =
      m_database.PrepareSQL("DELETE FROM gameclient WHERE path='%s'", path.c_str());

  if (!m_database.ExecuteQuery(sql))
  {
    CLog::Log(LOGERROR, "GAME: Failed to forget the emulator for {}", path);
    return false;
  }

  return true;
}

std::vector<std::string> SplitValues(const std::string& value,
                                     const std::vector<std::string>& separators)
{
  std::vector<std::string> parts = StringUtils::Split(value, separators);
  for (auto& part : parts)
    StringUtils::Trim(part);
  std::erase_if(parts, [](const std::string& part) { return part.empty(); });
  return parts;
}

std::vector<std::string> NameSeparators(const std::vector<std::string>& separators)
{
  std::vector<std::string> names = separators;
  std::erase_if(
      names, [](const std::string& sep)
      { return sep.size() == 1 && SeparatorsInsideNames.find(sep[0]) != std::string_view::npos; });
  if (std::find(names.begin(), names.end(), MUSIC_INFO::MatroskaTagMapping::MultiValueSeparator) ==
      names.end())
    names.emplace_back(MUSIC_INFO::MatroskaTagMapping::MultiValueSeparator);
  return names;
}

std::vector<std::string> SplitNames(const std::string& value,
                                    const std::vector<std::string>& separators)
{
  return SplitValues(value, NameSeparators(separators));
}

std::string JoinNames(const std::string& value,
                      const std::vector<std::string>& separators,
                      const std::string& musicsep)
{
  return StringUtils::Join(SplitNames(value, separators), musicsep);
}

void MUSIC_INFO::MatroskaTagMapping::MapTag(const std::string& key,
                                            const std::string& value,
                                            TagLevel level,
                                            const std::vector<std::string>& separators,
                                            const std::string& musicsep,
                                            CMusicInfoTag& tag)
{
  /*!
  * The names whose field the level decides. Everything else means the same thing wherever it
  * sits, and a caller applies album level tags before track level ones so that a song naming
  * itself wins over the album that named it.
  */
  if (level == TagLevel::Album)
  {
    if (key == "TITLE")
    {
      tag.SetAlbum(value);
      // Nothing else may have named the song yet; a track level TITLE still overrides this.
      tag.SetTitle(value);
      return;
    }
    if (key == "ARTIST")
    {
      // One ARTIST names both fields, so it is read once and read the way the track level branch
      // reads it.
      const std::string artists = JoinNames(value, separators, musicsep);

      /*!
      * It names the album's artist, but only for an album that did not name one itself. A caller
      * walks a std::map, so ARTIST is always applied after ALBUM ARTIST, ALBUMARTIST and
      * ALBUM_ARTIST - taking it unconditionally would replace what the file stated, and a
      * compilation carrying ALBUM ARTIST=Various Artists beside ARTIST=Miles Davis would be filed
      * under Miles Davis. Deferring here decides it by what the file said rather than by the order
      * the names happen to arrive in.
      */
      if (tag.GetAlbumArtist().empty())
        tag.SetAlbumArtist(artists);

      // The album's artist is the song's until the song says otherwise.
      tag.SetArtist(artists);
      return;
    }
  }
  else if (level == TagLevel::File && key == "TITLE")
  {
    /*!
    * The Segment title names the file. That is the song when the file holds one, and the album
    * when nothing better named it - a file with no album level tags at all still belongs
    * somewhere.
    */
    tag.SetTitle(value);
    if (tag.GetAlbum().empty())
      tag.SetAlbum(value);
    return;
  }

  Map(key, value, separators, musicsep, tag);
}

bool Map(const std::string& key,
         const std::string& value,
         const std::vector<std::string>& separators,
         const std::string& musicsep,
         CMusicInfoTag& tag)
{
  /*!
  * Matroska Tag spec does not allow storing multi values in a single tag, but some tools
  * do it anyway using a delimiter. So we need to split the value using the separator and
  * then join it back using the music item separator from as.xml if needed.
  *
  * The spaced spellings (ALBUM ARTIST, ARTIST SORT, ...) are what mp3tag writes; the
  * underscored and run-together ones are what the spec and most other taggers use.
  */
  if (key == "ALBUM")
    tag.SetAlbum(value);
  else if (key == "ARTIST")
    // SetArtist() splits on musicsep, so several artists have to arrive joined with it.
    tag.SetArtist(JoinNames(value, separators, musicsep));
  else if (key == "ARTISTS")
    tag.SetMusicBrainzArtistHints(SplitNames(value, separators));
  else if (key == "ALBUMARTISTS" || key == "ALBUM_ARTISTS" || key == "ALBUM ARTISTS")
    // Split and rejoined like ALBUMARTIST below: a file carrying both spellings would otherwise
    // keep whichever the caller happened to apply last, one of them unnormalised.
    tag.SetAlbumArtist(JoinNames(value, separators, musicsep));
  else if (key == "ALBUMARTIST" || key == "ALBUM_ARTIST" || key == "ALBUM ARTIST")
    tag.SetAlbumArtist(JoinNames(value, separators, musicsep));
  else if (key == "TITLE")
    tag.SetTitle(value);
  else if (key == "PART_NUMBER" || key == "TRACK")
  {
    try
    {
      tag.SetTrackNumber(std::stoi(value));
    }
    catch (const std::exception&)
    {
    }
  }
  else if (key == "DISC" || key == "DISCNUMBER")
  {
    try
    {
      tag.SetDiscNumber(std::stoi(value));
    }
    catch (const std::exception&)
    {
    }
  }
  else if (key == "GENRE")
    // Both delimiters: the user's, which is what a single tag packing several genres is written
    // with, and the one a reader joined repeated GENRE tags with.
    tag.SetGenre(SplitValues(value, {musicsep, MatroskaTagMapping::MultiValueSeparator}), true);
  else if (key == "COMPILATION")
    tag.SetCompilation(true);
  else if (key == "DATE" || key == "DATE_RELEASED" || key == "YEAR")
    tag.SetReleaseDate(value);
  else if (key == "DATE_RECORDED" || key == "ORIGINALDATE" || key == "ORIGINALYEAR" ||
           key == "ORIGYEAR")
    tag.SetOriginalDate(value);
  else if (key == "MOOD")
    tag.SetMood(StringUtils::Join(SplitValues(value, separators), musicsep));
  // genre could be comma delimited or not. Temporarily add the comma just in case.
  // true trims any whitespace around the genre(s)
  else if (key == "COMMENT")
    tag.SetComment(value);
  else if (key == "ARTIST-SORT" || key == "ARTISTSORT" || key == "ARTIST SORT")
    tag.SetArtistSort(JoinNames(value, separators, musicsep));
  else if (key == "ALBUMARTISTSORT" || key == "SORT_ALBUM_ARTIST" || key == "ALBUM ARTIST SORT")
    tag.SetAlbumArtistSort(JoinNames(value, separators, musicsep));
  else if (key == "COMPOSERSORT")
    tag.SetComposerSort(JoinNames(value, separators, musicsep));
  else if (key == "DISCSUBTITLE" || key == "SUBTITLE" || key == "SETSUBTITLE")
    tag.SetDiscSubtitle(value);
  else if (key == "MUSICBRAINZ_ARTISTID")
    tag.SetMusicBrainzArtistID(SplitValues(value, separators));
  else if (key == "MUSICBRAINZ_ALBUMID")
    tag.SetMusicBrainzAlbumID(value);
  else if (key == "MUSICBRAINZ_RELEASEGROUPID")
    tag.SetMusicBrainzReleaseGroupID(value);
  else if (key == "MUSICBRAINZ_ALBUMARTISTID")
    tag.SetMusicBrainzAlbumArtistID(SplitValues(value, separators));
  else if (key == "MUSICBRAINZ_TRACKID")
    tag.SetMusicBrainzTrackID(value);
  else if (key == "MUSICBRAINZ_ALBUMARTIST")
  {
    // tag.SetAlbumArtist(value);
  }
  else if (key == "MUSICBRAINZ_ALBUMTYPE")
    tag.SetMusicBrainzReleaseType(value);
  else if (key == "MUSICBRAINZ_ALBUMSTATUS")
    tag.SetAlbumReleaseStatus(value);
  else if (key == "ENCODED_BY" || key == "LANGUAGE")
  {
  }
  else if (key == "LABEL" || key == "PUBLISHER")
    tag.SetRecordLabel(value);
  else if (key == "CATALOGNUMBER")
  {
  } // No database field yet
  else if (key == "COPYRIGHT")
  {
  } // Copyright message
  else if (key == "WRITER")
    tag.AddArtistRole("Writer", SplitNames(value, separators));
  else if (key == "PERFORMER")
  {
    std::vector<std::string> tagdata = SplitValues(value, separators);
    AddRole(tagdata, separators, tag);
  }
  else if (key == "ARRANGER")
  {
    std::vector<std::string> tagdata = SplitValues(value, separators);
    AddRole(tagdata, separators, tag);
  }
  else if (key == "REMIXED_BY" || key == "REMIXEDBY")
    tag.AddArtistRole("Remixer", SplitNames(value, separators));
  else if (key == "MIXED_BY" || key == "MIXER")
    tag.AddArtistRole("Mixer", SplitNames(value, separators));
  else if (key == "LYRICIST")
    tag.AddArtistRole("Lyricist", SplitNames(value, separators));
  else if (key == "COMPOSER")
    tag.AddArtistRole("Composer", SplitNames(value, separators));
  else if (key == "CONDUCTOR")
    tag.AddArtistRole("Conductor", SplitNames(value, separators));
  else if (key == "ENGINEER")
    tag.AddArtistRole("Engineer", SplitNames(value, separators));
  else if (key == "PRODUCER")
    tag.AddArtistRole("Producer", SplitNames(value, separators));
  else if (key == "BAND")
    tag.AddArtistRole("Band", SplitNames(value, separators));
  // comma separated list of role, person
  else if (key == "INVOLVEDPEOPLE" || key == "ACTOR")
  {
    std::vector<std::string> tagdata = StringUtils::Split(value, ",");

    AddCommaDelimitedString(tagdata, separators, tag);
  }
  else if (key == "INSTRUMENTS")
  {
    std::vector<std::string> tagdata = StringUtils::Split(value, ",");

    AddCommaDelimitedString(tagdata, separators, tag);
  }
  else
    return false;

  return true;
}

void AddRole(const std::vector<std::string>& data,
             const std::vector<std::string>& separators,
             CMusicInfoTag& musictag)
{
  if (!data.empty())
  {
    for (size_t i = 0; i + 1 < data.size(); i += 2)
    {
      std::vector<std::string> roles = SplitValues(data[i], separators);
      for (auto& role : roles)
      {
        StringUtils::Trim(role);
        StringUtils::ToCapitalize(role);
        musictag.AddArtistRole(role, SplitValues(data[i + 1], separators));
      }
    }
  }
}

void AddCommaDelimitedString(const std::vector<std::string>& data,
                             const std::vector<std::string>& separators,
                             CMusicInfoTag& musictag)
{
  if (!data.empty())
  {
    for (size_t i = 0; i + 1 < data.size(); i += 2)
    {
      std::vector<std::string> roles = SplitValues(data[i], separators);
      for (auto& role : roles)
      {
        StringUtils::Trim(role);
        StringUtils::ToCapitalize(role);
        musictag.AddArtistRole(role, SplitValues(data[i + 1], {","}));
      }
    }
  }
}

int64_t VfsSeek(void* h, int64_t pos, int whence)
{
  auto* file = static_cast<CFile*>(h);
  return whence == AVSEEK_SIZE ? file->GetLength() : file->Seek(pos, whence & ~AVSEEK_FORCE);
}

void CFFmpegVfsContext::Close()
{
  // AVFMT_FLAG_CUSTOM_IO is what keeps this from closing the IO context too; it is ours to free.
  if (m_fctx)
    avformat_close_input(&m_fctx);
  if (m_ioctx)
  {
    av_free(m_ioctx->buffer);
    av_free(m_ioctx);
    m_ioctx = nullptr;
  }
  m_file.reset();
  m_haveStreamInfo = false;
}

double CFFmpegVfsContext::Duration() const
{
  if (!m_fctx || m_fctx->duration == AV_NOPTS_VALUE || m_fctx->duration <= 0)
    return 0.0;
  return static_cast<double>(m_fctx->duration) / AV_TIME_BASE;
}

bool CFFmpegVfsContext::Open(const std::string& path)
{
  Close();

  m_file = std::make_unique<CFile>();
  if (!m_file->Open(path))
  {
    Close();
    return false;
  }

  // A buffer under what one read returns only costs more reads, which over SMB or NFS is the cost
  // that matters.
  const int bufferSize = std::max(FFMPEG_BUFFER_SIZE, m_file->GetChunkSize());
  auto* buffer = static_cast<uint8_t*>(av_malloc(bufferSize));
  if (!buffer)
  {
    Close();
    return false;
  }

  m_ioctx = avio_alloc_context(buffer, bufferSize, 0, m_file.get(), VfsRead, nullptr, VfsSeek);
  if (!m_ioctx)
  {
    av_free(buffer);
    Close();
    return false;
  }
  m_ioctx->max_packet_size = bufferSize;

  // Say so rather than let FFmpeg find out by seeking on something that cannot, such as a pipe.
  if (m_file->IoControl(IOControl::SEEK_POSSIBLE, nullptr) != 1)
    m_ioctx->seekable = 0;

  m_fctx = avformat_alloc_context();
  if (!m_fctx)
  {
    Close();
    return false;
  }
  m_fctx->pb = m_ioctx;
  m_fctx->flags |= AVFMT_FLAG_CUSTOM_IO;

  const AVInputFormat* iformat = nullptr;
  av_probe_input_buffer(m_ioctx, &iformat, path.c_str(), nullptr, 0, 0);

  if (avformat_open_input(&m_fctx, path.c_str(), iformat, nullptr) < 0)
  {
    // avformat_open_input() has freed and cleared m_fctx already; the IO context is still ours.
    Close();
    return false;
  }

  // Nothing here decodes: the headers, the chapters and the attachments are all that is wanted.
  m_fctx->flags |= AVFMT_FLAG_NOPARSE;
  /*!
   * A failure here does not fail the open: the tags, the chapters and the attachments come from
   * the header and are there either way, and a caller after those is entitled to them. It is only
   * what is read off the streams that has none of it, so the outcome is recorded for
   * HasStreamInfo() to hand to whoever asks for that.
   */
  m_haveStreamInfo = avformat_find_stream_info(m_fctx, nullptr) >= 0;
  if (!m_haveStreamInfo)
    CLog::Log(LOGERROR, "CFFmpegVfsContext: can't detect codec info in file {}",
              CURL::GetRedacted(path));

  return true;
}

void ColorPassDescriptorSet::prepareExtraDirectionalLights(FEngine& engine,
        float const exposure, size_t const count,
        float3 const* sceneSpaceDirections,
        LightManagerInstance const* instances) noexcept {
    assert_invariant(count <= CONFIG_MAX_EXTRA_DIRECTIONAL_LIGHTS);
    FLightManager const& lcm = engine.getLightManager();
    auto& s = mUniforms.edit();
    for (size_t i = 0; i < count; i++) {
        LightManagerInstance const li = instances[i];
        // the channel mask fits in 8 bits, so the float conversion is exact
        s.extraLightDirection[i] = float4{
                -sceneSpaceDirections[i], float(lcm.getLightChannels(li)) };
        s.extraLightColorIntensity[i] = float4{
                lcm.getColor(li), lcm.getIntensity(li) * exposure };
    }
    s.extraLightCount = int32_t(count);
}

TEST(FilamentTest, MultipleDirectionalLights) {
    Engine::Config config{};
    config.enableMultipleDirectionalLights = true;
    FEngine* engine = downcast(Engine::Builder()
            .backend(backend::Backend::NOOP)
            .config(&config)
            .build());
    FScene* scene = downcast(engine->createScene());
    auto& em = engine->getEntityManager();
    FLightManager& lcm = engine->getLightManager();

    // create more directional lights than can be supported, with decreasing intensity,
    // in a random-ish direction each
    constexpr size_t EXTRA_COUNT = CONFIG_MAX_EXTRA_DIRECTIONAL_LIGHTS;
    constexpr size_t LIGHT_COUNT = FScene::DIRECTIONAL_LIGHTS_COUNT + EXTRA_COUNT + 2;
    Entity entities[LIGHT_COUNT];
    float3 directions[LIGHT_COUNT];
    for (size_t i = 0; i < LIGHT_COUNT; i++) {
        entities[i] = em.create();
        directions[i] = normalize(float3{ float(i + 1), 1.0f, -0.5f });
        LightManager::Builder(LightManager::Type::DIRECTIONAL)
                .intensity(1000.0f * float(LIGHT_COUNT - i))
                .direction(directions[i])
                .build(*engine, entities[i]);
        static_cast<Scene*>(scene)->addEntity(entities[i]);
    }

    LinearAllocatorArena arena("MultipleDirectionalLights test arena", 3 * 1024 * 1024);
    RootArenaScope rootArenaScope(arena);
    FScene::SceneCacheData cache;
    scene->prepare(engine->getJobSystem(), rootArenaScope, mat4{}, false, cache);

    // the most intense directional light is the dominant one, at index 0 of the LightSoa
    auto const& lightData = cache.lightData;
    EXPECT_TRUE(lightData.elementAt<FScene::LIGHT_ENTITY>(0) == entities[0]);

    // the next EXTRA_COUNT lights, by decreasing intensity, are the extra directional
    // lights; the remaining ones are ignored
    ASSERT_EQ(EXTRA_COUNT, cache.extraDirectionalLightCount);
    for (size_t i = 0; i < EXTRA_COUNT; i++) {
        size_t const entity = FScene::DIRECTIONAL_LIGHTS_COUNT + i;
        EXPECT_TRUE(cache.extraDirectionalLightInstances[i] ==
                lcm.getInstance(entities[entity]));
        float3 const d = cache.extraDirectionalLightDirections[i];
        EXPECT_NEAR(directions[entity].x, d.x, 1e-6f);
        EXPECT_NEAR(directions[entity].y, d.y, 1e-6f);
        EXPECT_NEAR(directions[entity].z, d.z, 1e-6f);
    }

    // with a single directional light there are no extras
    for (size_t i = 1; i < LIGHT_COUNT; i++) {
        static_cast<Scene*>(scene)->remove(entities[i]);
    }
    scene->prepare(engine->getJobSystem(), rootArenaScope, mat4{}, false, cache);
    EXPECT_TRUE(lightData.elementAt<FScene::LIGHT_ENTITY>(0) == entities[0]);
    EXPECT_EQ(0u, cache.extraDirectionalLightCount);

    engine->destroy(scene);
    for (auto& e : entities) {
        engine->destroy(e);
        em.destroy(e);
    }
    Engine::destroy((Engine**)&engine);
}

float2 ShadowMap::texelSizeWorldSpaceAtOneMeter(
        mat4f const& Mp,
        uint16_t const shadowDimension) noexcept {
    constexpr float3 oneMeterLs{0, 0, -1};
    return texelSizeWorldSpaceAt(Mp, oneMeterLs, shadowDimension);
}

static float computeDynamicMaxSearchRadius(float const maxMipLevel, float const wsTexelSizeAtOneMeter) noexcept {
    // Calculate the maximum texel radius before clamping kicks in
    // Since the shader does: searchLod = log2(radiusInTexels)
    // The maximum radius in texels we can support is 2^MAX_MIP_LEVEL
    float const maxRadiusInTexels = std::exp2(maxMipLevel);
    // Convert that max texel limit back into physical world meters
    float const maxPhysicalRadius = wsTexelSizeAtOneMeter * maxRadiusInTexels;
    return maxPhysicalRadius;
}

bool ShadowMapManager::isDepthClampEnabled(FEngine const& engine,
        FView const& view, ShadowMap const& shadowMap) const noexcept {
    return (shadowMap.getShadowLightType() == ShadowLightType::DIRECTIONAL) &&
            !view.hasVSM() &&
            !view.hasPCSS() &&
            mIsDepthClampSupported &&
            engine.debug.shadowmap.depth_clamp;
}

void ShadowMapManager::updateShadowUbo(FEngine const& engine, FView const& view,
        ShadowMap& shadowMap, ShadowMap::ShaderParameters const& shaderParameters) const noexcept {
    VsmShadowOptions const& vsmShadowOptions = view.getVsmShadowOptions();
    FLightManager::ShadowOptions const& options = shadowMap.getShadowOptions();

    auto const& lcm = engine.getLightManager();
    auto const li = lcm.getInstance(shadowMap.getLightEntity());

    float const effectiveBulbRadius = lcm.getEffectiveBulbRadius(li);
    float2 const normalBias = options.normalBias * shaderParameters.texelSizeAtOneMeterWs;
    float const bulbRadius = (mSoftShadowOptions.penumbraScale * options.penumbraScale) * effectiveBulbRadius;

    const float cw = computeDynamicVsmExponent(
            !vsmShadowOptions.highPrecision,
            view.hasPCSS(),
            view.hasPCSS() ? (PCSS_MIP_LEVELS - 1) : (mTextureAtlasRequirements.levels - 1),
            options.vsm.blurWidth);

    shadowMap.setWrapExponent(cw);

    auto packHalf2x16 = [](half2 v) -> uint32_t {
        short2 s;
        memcpy(&s[0], &v[0], sizeof(s));
        return s.y << 16 | s.x;
    };

    // The camera's near / far are distance from the camera to the near / far plane (not coordinates on the z axis)
    const float n = float(shadowMap.getCamera().getNear());
    const float f = float(shadowMap.getCamera().getCullingFar());

    // no limits by default
    float maxSearchRadius = std::numeric_limits<half>::max();
    if (shadowMap.getShadowLightType() == ShadowLightType::DIRECTIONAL) {
        // The maximum search radius the shader will ever need for a directional light is given by
        // bulbRadius * (f - n)
        // But we're limited by the number of mip levels we have relative to the shadowmap resolution.
        // We must always use the first cascade parameters for this calculation.
        float2 const wsTexelSizeAtOneMeter0 = getCascadeShaderParameters(0).texelSizeAtOneMeterWs;
        maxSearchRadius = computeDynamicMaxSearchRadius(PCSS_MIP_LEVELS - 1,
                std::max(wsTexelSizeAtOneMeter0.x, wsTexelSizeAtOneMeter0.y));
    }

    // further limit the search radius to a user-defined value
    const float resolvedMaxSearchRadius = options.maxSearchRadius > 0 ?
            options.maxSearchRadius : mSoftShadowOptions.maxSearchRadius;
    maxSearchRadius = std::min(maxSearchRadius, resolvedMaxSearchRadius);

    const uint32_t layer = shadowMap.getLayer();
    const uint32_t evsm4 = (view.hasPCSS() || options.vsm.elvsm) ? 1 : 0;

    // this is not needed in the shader for directional lights, and for spot-lights, both .x and .y
    // should be equal
    const float wsOneOverTexelSizeAtOneMeter = 1.0f / shaderParameters.texelSizeAtOneMeterWs.x;

    const size_t shadowIndex = shadowMap.getShadowIndex();
    auto& s = mShadowUb.edit();
    s.shadows[shadowIndex].lightFromWorldMatrix = shaderParameters.lightSpace;
    s.shadows[shadowIndex].lightFromWorldZ = shaderParameters.lightFromWorldZ;
    s.shadows[shadowIndex].scissorNormalized = shaderParameters.scissorNormalized;
    s.shadows[shadowIndex].wsOneOverTexelSizeAtOneMeter = wsOneOverTexelSizeAtOneMeter;
    s.shadows[shadowIndex].maxMipLevel_maxSearchRadius = packHalf2x16({PCSS_MIP_LEVELS - 1, maxSearchRadius});
    s.shadows[shadowIndex].bulbRadius_vsmExponent = packHalf2x16({ bulbRadius, cw });
    s.shadows[shadowIndex].evsm4_layer = (evsm4 << 8) | layer;

    switch (shadowMap.getShadowLightType()) {
        case ShadowLightType::DIRECTIONAL:
            s.shadows[shadowIndex].projectionParam = f - n;
            break;
        case ShadowLightType::SPOT:
            UTILS_FALLTHROUGH;
        case ShadowLightType::POINT:
            s.shadows[shadowIndex].projectionParam = n / (f - n);
            break;
    }

    if (view.hasVSM() || view.hasPCSS()) {
        const float resolvedMaxPenumbraRatio = options.maxPenumbraRatio > 0 ?
                options.maxPenumbraRatio : mSoftShadowOptions.maxPenumbraRatio;
        const float penumbraRatioScale =
                options.penumbraRatioScale * mSoftShadowOptions.penumbraRatioScale;
        s.shadows[shadowIndex].normalBias = float2{0.0f};
        s.shadows[shadowIndex].maxPenumbraRatio_penumbraRatioScale = packHalf2x16(
                { resolvedMaxPenumbraRatio, penumbraRatioScale });
    } else {
        s.shadows[shadowIndex].normalBias = normalBias;
    }
}

float ShadowMapManager::computeDynamicVsmExponent(
        bool const isFp16Target,
        bool const isPcss,
        int const maxMipLevel,
        float const standardBlurRadius) noexcept {

    // The absolute mathematical ceiling for a 1-texel footprint before FP32 breakdown
    constexpr float MAX_FP32_EXPONENT = 42.0f;

    // The physical ceiling to prevent GL_HALF_FLOAT from overflowing (exp(2*c) <= 65504)
    constexpr float MAX_FP16_EXPONENT = 5.54f;

    // The absolute minimum exponent before EVSM loses its non-linear properties
    constexpr float MIN_EXPONENT = 5.5f;

    // We must determine the absolute maximum filter radius this shadow map will ever experience.
    float maxEffectiveRadius;
    if (isPcss) {
        return MIN_EXPONENT;
    } else {
        // Even with no pre-blur, a single texel represents a footprint of 1.0.
        float const baseRadius = std::max(1.0f, standardBlurRadius);
        if (maxMipLevel > 0) {
            float const mipChainMultiplier = std::pow(2.0f, static_cast<float>(maxMipLevel));
            // Mipmapping IS a box blur. It exponentially scales the footprint.
            maxEffectiveRadius = baseRadius * mipChainMultiplier;
        } else {
            maxEffectiveRadius = baseRadius;
        }
    }

    // The exponent must scale inversely with the maximum filter footprint.
    float const filterCeiling = MAX_FP32_EXPONENT / maxEffectiveRadius;
    float const hardwareCeiling = isFp16Target ? MAX_FP16_EXPONENT : MAX_FP32_EXPONENT;

    // Return the most restrictive of the two ceilings to guarantee stability.
    float const targetExponent = std::min(filterCeiling, hardwareCeiling);

    // Apply the floor to prevent Curve Collapse
    float const finalExponent = std::max(targetExponent, MIN_EXPONENT);

    return finalExponent;
}

float FLightManager::getEffectiveBulbRadius(Instance const li) const noexcept {
    auto const& options = getShadowOptions(li);
    if (options.shadowBulbRadius < 0.0f) {
        switch (getType(li)) {
            case Type::SUN: {
                float const sunAngularRadius = getSunAngularRadiusRad(li);
                float const sunHaloRatio = getSunHaloSize(li);
                return clamp(sunAngularRadius * sunHaloRatio, 0.0f, f::PI_2);
            }
            case Type::DIRECTIONAL:
                return 1.0f;
            case Type::POINT:
            case Type::FOCUSED_SPOT:
            case Type::SPOT:
                return 0.06f;
        }
    }
    return options.shadowBulbRadius;
}

void set_http2_max_headers(uint32_t value) {
    if (value > 0) {
        max_headers = value;
    }
}

bool element_type_equals(const ArrayTypeInfo *element_array_type_info) const {
        return element_array_type_info->get_type_of_key() == element.type_of_key &&
               element_array_type_info->get_type_of_value() == element.type_of_value &&
               element_array_type_info->len_of_type_str == get_len_of_value_type_str() &&
               memcmp(element_array_type_info->type_str, get_value_type_str(), get_len_of_value_type_str()) == 0;
    }

ArrayTypeInfo *dup() const {
        const auto copy = static_cast<ArrayTypeInfo *>(emalloc(sizeof(ArrayTypeInfo) + get_len_of_type_str() + 1));
        memcpy(copy, this, sizeof(ArrayTypeInfo) + get_len_of_type_str() + 1);
        return copy;
    }

static void move_first_element(const zval src[], zval dst[], int size, int position) {
    zval first = src[0];
    for (int i = 0; i < position; i++) {
        dst[i] = src[i + 1];
    }
    dst[position] = first;
    for (int i = position + 1; i < size; i++) {
        dst[i] = src[i];
    }
}

static void call_func_move_first_arg(zend_function *fn, zend_execute_data *execute_data, zval *retval, int position) {
    const zval *arg_ptr = ZEND_CALL_ARG(execute_data, 1);
    const int arg_count = ZEND_CALL_NUM_ARGS(execute_data);
    const auto argv = static_cast<zval *>(ecalloc(arg_count, sizeof(zval)));
    move_first_element(arg_ptr, argv, arg_count, position);
    zend_call_known_function(fn, nullptr, nullptr, retval, arg_count, argv, nullptr);
    efree(argv);
}

static void call_method(const std::unordered_map<std::string, std::string> &method_map,
                        zend_execute_data *execute_data,
                        zval *retval) {
    const auto call_info = reinterpret_cast<CallInfo *>(execute_data->run_time_cache);
    const auto name = std::string(Z_STRVAL(call_info->func), Z_STRLEN(call_info->func));
    const auto iter = method_map.find(name);

    ON_SCOPE_EXIT {
        efree(call_info);
        execute_data->run_time_cache = nullptr;
    }

static int opcode_handler_method_call(zend_execute_data *execute_data) {
    const zend_op *opline = EX(opline);
    zval *object;
    if (opline->op1_type == IS_CONST) {
        object = RT_CONSTANT(opline, opline->op1);
    } else if (UNEXPECTED(opline->op1_type == IS_UNUSED)) {
        return ZEND_USER_OPCODE_DISPATCH;
    } else {
        object = EX_VAR(opline->op1.var);
    }

    auto type = Z_TYPE_P(object);
    if (type == IS_REFERENCE) {
        type = Z_TYPE_P(Z_REFVAL_P(object));
    }

    if (type == IS_ARRAY || type == IS_STRING || type == IS_RESOURCE) {
        auto call_info = static_cast<CallInfo *>(emalloc(sizeof(CallInfo)));
        call_info->func = *RT_CONSTANT(opline, opline->op2);
        call_info->this_ = *object;
        call_info->op1_type = opline->op1_type;

        zend_function *fbc = nullptr;
        switch (type) {
        case IS_ARRAY:
            fbc = fn_swoole_call_array_method;
            break;
        case IS_STRING:
            fbc = fn_swoole_call_string_method;
            break;
        default:
            fbc = fn_swoole_call_stream_method;
        }

        zend_execute_data *call =
            zend_vm_stack_push_call_frame(ZEND_CALL_NESTED_FUNCTION, fbc, opline->extended_value, object);

        call->run_time_cache = reinterpret_cast<void **>(call_info);
        call->prev_execute_data = EX(call);
        EX(call) = call;
        EX(opline)++;

        return ZEND_USER_OPCODE_CONTINUE;
    }

    return ZEND_USER_OPCODE_DISPATCH;
}

void php_swoole_stdext_minit(int module_number) {
    zend_set_user_opcode_handler(ZEND_INIT_METHOD_CALL, opcode_handler_method_call);
    zend_set_user_opcode_handler(ZEND_ASSIGN_DIM, opcode_handler_array_assign);
    zend_set_user_opcode_handler(ZEND_ASSIGN_DIM_OP, opcode_handler_array_assign_op);
    zend_set_user_opcode_handler(ZEND_UNSET_DIM, opcode_handler_array_unset);
    zend_set_user_opcode_handler(ZEND_FE_RESET_RW, opcode_handler_foreach_begin);

    fn_swoole_call_array_method = get_function(CG(function_table), ZEND_STRL("swoole_call_array_method"));
    fn_swoole_call_string_method = get_function(CG(function_table), ZEND_STRL("swoole_call_string_method"));
    fn_swoole_call_stream_method = get_function(CG(function_table), ZEND_STRL("swoole_call_stream_method"));

    fn_array_push = get_function(CG(function_table), ZEND_STRL("array_push"));
    fn_array_unshift = get_function(CG(function_table), ZEND_STRL("array_unshift"));
    fn_array_splice = get_function(CG(function_table), ZEND_STRL("array_splice"));

    ori_handler_array_push = fn_array_push->internal_function.handler;
    fn_array_push->internal_function.handler = ZEND_FN(swoole_array_push);
    ori_handler_array_unshift = fn_array_unshift->internal_function.handler;
    fn_array_unshift->internal_function.handler = ZEND_FN(swoole_array_unshift);
    ori_handler_array_splice = fn_array_splice->internal_function.handler;
    fn_array_splice->internal_function.handler = ZEND_FN(swoole_array_splice);
}

PHP_FUNCTION(swoole_parse_str) {
    char *arg;
    size_t arglen;

    ZEND_PARSE_PARAMETERS_START(1, 1)
    Z_PARAM_STRING(arg, arglen)
    ZEND_PARSE_PARAMETERS_END();

    array_init(return_value);
    auto res = estrndup(arg, arglen);
    sapi_module.treat_data(PARSE_STRING, res, return_value);
}

PHP_FUNCTION(swoole_str_is_empty) {
    zend_string *str;
    ZEND_PARSE_PARAMETERS_START(1, 1)
    Z_PARAM_STR(str)
    ZEND_PARSE_PARAMETERS_END();
    RETURN_BOOL(str->len == 0);
}

PHP_FUNCTION(swoole_array_is_empty) {
    zval *array;
    ZEND_PARSE_PARAMETERS_START(1, 1)
    Z_PARAM_ARRAY(array)
    ZEND_PARSE_PARAMETERS_END();
    RETURN_BOOL(zend_array_count(Z_ARRVAL_P(array)) == 0);
}

static HashTable *make_typed_array(const uint32_t nSize, const uint32_t nTypeStr) {
    const auto ht = static_cast<zend_array *>(emalloc(sizeof(HashTable) + sizeof(ArrayTypeInfo) + nTypeStr + 1));
    _zend_hash_init(ht, nSize, ZVAL_PTR_DTOR, false);
    HT_FLAGS(ht) |= HASH_FLAG_TYPED_ARRAY;
    return ht;
}

void copy_array_type_info(zval *container, zend_array *src) {
    auto src_type_info = get_type_info(src);
    zend_array *ht = Z_ARRVAL_P(container);
    auto extra_size = sizeof(ArrayTypeInfo) + src_type_info->get_len_of_type_str() + 1;
    const auto tmp = static_cast<zend_array *>(emalloc(sizeof(HashTable) + extra_size));
    memcpy(tmp, ht, sizeof(HashTable));
    memcpy(reinterpret_cast<char *>(tmp) + sizeof(HashTable), src_type_info, extra_size);
    HT_FLAGS(tmp) |= HASH_FLAG_TYPED_ARRAY;
    Z_ARRVAL_P(container) = tmp;
    efree(ht);
}

static zend_string *get_array_type_def(const ArrayTypeInfo *info) {
    zend_string *result = zend_string_alloc(info->get_len_of_value_type_str() + 16, false);
    char *p = result->val;
    *p = '<';
    if (info->get_type_of_key() == IS_STRING) {
        p++;
        strcpy(p, "string,");
        p += 7;
    } else if (info->get_type_of_key() == IS_LONG) {
        p++;
        strcpy(p, "int,");
        p += 4;
    }

    memcpy(p, info->get_value_type_str(), info->get_len_of_value_type_str());
    p += info->get_len_of_value_type_str();
    *p = '>';
    p++;
    *p = '\0';
    result->len = p - result->val;

    return result;
}

bool ArrayTypeInfo::check(const zend_array *ht, const zval *key, const zval *value) const {
    if (get_type_of_key() > 0) {
        if (Z_TYPE_P(key) != get_type_of_key()) {
            zend_type_error("Array key type mismatch, expected `%s`, got `%s`",
                            zend_get_type_by_const(get_type_of_key()),
                            zend_get_type_by_const(Z_TYPE_P(key)));
            return false;
        }
    } else {
        if (Z_TYPE_P(key) == IS_LONG) {
            if (Z_LVAL_P(key) > zend_hash_num_elements(ht)) {
                zend_throw_error(
                    nullptr, "Incorrect array key `%ld`, out of the permitted range", (long) Z_LVAL_P(key));
                return false;
            }
        } else if (!(Z_TYPE_P(key) == IS_UNDEF || Z_TYPE_P(key) == IS_NULL)) {
            zend_throw_error(nullptr, "Incorrect array key, must be undef or int");
            return false;
        }
    }
    ZVAL_DEREF(value);
    if (value_is_bool() && ZVAL_IS_BOOL(value)) {
        return true;
    }
    if (Z_TYPE_P(value) != get_type_of_value()) {
        zend_type_error("Array value type mismatch, expected `%s`, got `%s`",
                        zend_get_type_by_const(get_type_of_value()),
                        zend_get_type_by_const(Z_TYPE_P(value)));
        return false;
    }
    if (value_is_object() && !instance_of(value)) {
        zend_type_error(
            "Array value type mismatch, expected `%s`, got `%s`", value_ce->name->val, Z_OBJCE_P(value)->name->val);
        return false;
    }
    if (value_is_array()) {
        const auto element_array_type_info = get_type_info(Z_ARRVAL_P(value));
        const auto element_ht = Z_ARRVAL_P(value);
        if (!(HT_FLAGS(element_ht) & HASH_FLAG_TYPED_ARRAY)) {
            zend_type_error("Array value type mismatch, expected `%.*s`, got `array`",
                            get_len_of_value_type_str(),
                            get_value_type_str());
            return false;
        }
        if (!element_type_equals(element_array_type_info)) {
            const auto element_type_str = get_array_type_def(element_array_type_info);
            zend_type_error("Array value type mismatch, expected `%.*s`, got `%.*s`",
                            get_len_of_value_type_str(),
                            get_value_type_str(),
                            (int) ZSTR_LEN(element_type_str),
                            ZSTR_VAL(element_type_str));
            zend_string_release(element_type_str);
            return false;
        }
    }
    return true;
}

static zval *get_array_on_opline(const zend_op *opline EXECUTE_DATA_DC) {
    auto array = _get_zval_ptr_ptr_var(opline->op1.var EXECUTE_DATA_CC);
    if (ZVAL_IS_REF(array)) {
        array = Z_REFVAL_P(array);
    }
    if (!ZVAL_IS_ARRAY(array)) {
        return nullptr;
    }
    return array;
}

static void debug_val(const char *tag, int op_type, zval *value) {
    printf("[%s] refcount=%d, op1_type=%d, type=%s, refcounted=%d\n",
           tag,
           Z_REFCOUNTED_P(value) ? Z_REFCOUNT_P(value) : 0,
           op_type,
           zend_get_type_by_const(Z_TYPE_P(value)),
           Z_REFCOUNTED_P(value));
}

static void array_add_or_update(const zend_op *opline, zval *container, const zval *key, zval *value EXECUTE_DATA_DC) {
    zval *var_ptr;
    HashTable *source = Z_ARRVAL_P(container);
    SEPARATE_ARRAY(container);
    if (source != Z_ARRVAL_P(container)) {
        copy_array_type_info(container, source);
    }
    HashTable *ht = Z_ARRVAL_P(container);
    const zend_op *op_data = opline + 1;

    if (ZVAL_IS_NULL(key)) {
        var_ptr = zend_hash_next_index_insert(ht, value);
        if (UNEXPECTED(!var_ptr)) {
            zend_cannot_add_element();
            goto assign_dim_op_ret_null;
        }
    } else {
        zval *variable_ptr;
        if (opline->op2_type == IS_CONST) {
            variable_ptr = zend_fetch_dimension_address_inner_W_CONST(Z_ARRVAL_P(container), key EXECUTE_DATA_CC);
        } else {
            variable_ptr = zend_fetch_dimension_address_inner_W(Z_ARRVAL_P(container), key EXECUTE_DATA_CC);
        }
        if (UNEXPECTED(variable_ptr == nullptr)) {
            goto assign_dim_op_ret_null;
        }
        debug_val("1", op_data->op1_type, value);
        var_ptr = zend_assign_to_variable(variable_ptr, value, op_data->op1_type, EX_USES_STRICT_TYPES());
        debug_val("2", op_data->op1_type, value);
        if (UNEXPECTED(!var_ptr)) {
        assign_dim_op_ret_null:
            FREE_OP(op_data->op1_type, op_data->op1.var);
            if (UNEXPECTED(RETURN_VALUE_USED(opline))) {
                ZVAL_NULL(EX_VAR(opline->result.var));
            }
            return;
        }
    }
    debug_val("3", op_data->op1_type, value);
    if (UNEXPECTED(RETURN_VALUE_USED(opline))) {
        ZVAL_COPY(EX_VAR(opline->result.var), var_ptr);
    }
    if (op_data->op1_type == IS_VAR) {
        Z_TRY_ADDREF_P(value);
    }
    FREE_OP(op_data->op1_type, op_data->op1.var);
    debug_val("4", op_data->op1_type, value);
}

static void array_op(const zend_op *opline, zval *container, const zval *key, zval *value EXECUTE_DATA_DC) {
    HashTable *source = Z_ARRVAL_P(container);
    SEPARATE_ARRAY(container);
    if (source != Z_ARRVAL_P(container)) {
        copy_array_type_info(container, source);
    }
    const auto type_info = get_type_info(Z_ARRVAL_P(container));

    zval *variable_ptr;
    if ((opline + 1)->op1_type == IS_CONST) {
        variable_ptr = zend_fetch_dimension_address_inner_RW_CONST(Z_ARRVAL_P(container), key EXECUTE_DATA_CC);
    } else {
        variable_ptr = zend_fetch_dimension_address_inner_RW(Z_ARRVAL_P(container), key EXECUTE_DATA_CC);
    }
    if (UNEXPECTED(variable_ptr == nullptr)) {
    assign_dim_op_ret_null:
        FREE_OP((opline + 1)->op1_type, (opline + 1)->op1.var);
        if (UNEXPECTED(RETURN_VALUE_USED(opline))) {
            ZVAL_NULL(EX_VAR(opline->result.var));
        }
        return;
    }
    do {
        if (UNEXPECTED(Z_ISREF_P(variable_ptr))) {
            zend_reference *ref = Z_REF_P(variable_ptr);
            variable_ptr = Z_REFVAL_P(variable_ptr);
            if (UNEXPECTED(ZEND_REF_HAS_TYPE_SOURCES(ref))) {
                zend_binary_assign_op_typed_ref(ref, value OPLINE_CC EXECUTE_DATA_CC);
                break;
            }
        }
        const auto opcode = opline->extended_value;
        if (opcode == ZEND_CONCAT) {
            if (!type_info->value_is_string()) {
                zend_type_error("Only string support concat operation");
                goto assign_dim_op_ret_null;
            }
        } else {
            if (!type_info->value_is_numeric()) {
                zend_type_error("Only int or float support arithmetic operation");
                goto assign_dim_op_ret_null;
            }
        }
        zend_binary_op(variable_ptr, variable_ptr, value OPLINE_CC);
    } while (false);

    if (UNEXPECTED(RETURN_VALUE_USED(opline))) {
        ZVAL_COPY(EX_VAR(opline->result.var), variable_ptr);
    }
    FREE_OP((opline + 1)->op1_type, (opline + 1)->op1.var);
}

static int opcode_handler_array(zend_execute_data *execute_data, const ArrayFn &fn) {
    const zend_op *opline = EX(opline);
    const zend_op *op_data = opline + 1;
    zval *array = get_array_on_opline(opline EXECUTE_DATA_CC);
    if (UNEXPECTED(!array)) {
        return ZEND_USER_OPCODE_DISPATCH;
    }
    zend_array *ht = Z_ARRVAL_P(array);
    if (!(HT_FLAGS(ht) & HASH_FLAG_TYPED_ARRAY)) {
        return ZEND_USER_OPCODE_DISPATCH;
    }
    const auto value = get_op_data_zval_ptr_r(op_data->op1_type, op_data->op1);
    zval *key;
    if (opline->op2_type == IS_CONST) {
        key = RT_CONSTANT(opline, opline->op2);
    } else if (UNEXPECTED(opline->op2_type == IS_UNUSED)) {
        key = &EG(uninitialized_zval);
    } else {
        key = EX_VAR(opline->op2.var);
    }
    const auto type_info = get_type_info(ht);
    if (!type_info->check(ht, key, value)) {
        FREE_OP(op_data->op1_type, op_data->op1.var);
        return ZEND_USER_OPCODE_CONTINUE;
    }
    fn(opline, array, key, value EXECUTE_DATA_CC);
    EX(opline) += 2;
    return ZEND_USER_OPCODE_CONTINUE;
}

static int opcode_handler_foreach_begin(zend_execute_data *execute_data) {
    const zend_op *opline = EX(opline);
    zval *array;
    if (opline->op1_type == IS_VAR || opline->op1_type == IS_CV) {
        array = _get_zval_ptr_ptr_var(opline->op1.var EXECUTE_DATA_CC);
    } else if (opline->op1_type == IS_CONST) {
        array = RT_CONSTANT(opline, opline->op1);
    } else {
        array = _get_zval_ptr_tmp(opline->op1.var EXECUTE_DATA_CC);
    }
    ZVAL_DEREF(array);
    if (UNEXPECTED(!array || !ZVAL_IS_ARRAY(array))) {
        return ZEND_USER_OPCODE_DISPATCH;
    }
    const zend_array *ht = Z_ARRVAL_P(array);
    if (HT_FLAGS(ht) & HASH_FLAG_TYPED_ARRAY) {
        zend_throw_error(nullptr, "The type array do not support using references for element value during iteration");
        ZVAL_UNDEF(EX_VAR(opline->result.var));
        Z_FE_ITER_P(EX_VAR(opline->result.var)) = static_cast<uint32_t>(-1);

        return ZEND_USER_OPCODE_CONTINUE;
    }
    return ZEND_USER_OPCODE_DISPATCH;
}

static int opcode_handler_array_unset(zend_execute_data *execute_data) {
    const zend_op *opline = EX(opline);
    const zval *array = get_array_on_opline(opline EXECUTE_DATA_CC);
    if (!array) {
        return ZEND_USER_OPCODE_DISPATCH;
    }
    zend_array *ht = Z_ARRVAL_P(array);
    if (!(HT_FLAGS(ht) & HASH_FLAG_TYPED_ARRAY)) {
        return ZEND_USER_OPCODE_DISPATCH;
    }
    const auto type_info = get_type_info(ht);
    if (type_info->is_list()) {
        zend_throw_error(nullptr, "The typed array list do not support random deletion of elements");
        return ZEND_USER_OPCODE_CONTINUE;
    }
    return ZEND_USER_OPCODE_DISPATCH;
}

static void remove_all_spaces(char **val, uint16_t *len) {
    if (!*val || *len == 0) {
        return;
    }

    const char *src = *val;
    char *dst = *val;
    size_t new_len = 0;

    for (size_t i = 0; i < *len; i++) {
        if (!isspace((uchar) *src)) {
            *dst = *src;
            dst++;
            new_len++;
        }
        src++;
    }

    *len = new_len;
}

static int8_t get_type(const char *val, size_t len) {
    if (SW_STRCASEEQ(val, len, "int")) {
        return IS_LONG;
    } else if (SW_STRCASEEQ(val, len, "float")) {
        return IS_DOUBLE;
    } else if (SW_STRCASEEQ(val, len, "string")) {
        return IS_STRING;
    } else if (SW_STRCASEEQ(val, len, "bool")) {
        return IS_TRUE;  // IS_TRUE or IS_FALSE
    } else if (val[0] == '<' && val[len - 1] == '>') {
        return IS_ARRAY;
    } else if (SW_STRCASEEQ(val, len, "resource")) {
        return IS_RESOURCE;
    } else if (SW_STRCASEEQ(val, len, "null")) {
        return IS_NULL;
    } else {
        return IS_OBJECT;
    }
}

bool ArrayTypeValue::parse(const char *type_str, const size_t len_of_type_str) {
    auto pos = strchr(type_str, ',');
    if (pos == nullptr) {
        type_of_key = 0;
        offset_of_value_type_str = 1;
    } else {
        type_of_key = get_type(type_str + 1, pos - type_str - 1);
        if (type_of_key != IS_STRING && type_of_key != IS_LONG) {
            zend_throw_error(nullptr, "The key type of array must be string or int, but got %s", pos + 1);
            return false;
        }
        offset_of_value_type_str = pos - type_str + 1;
    }
    len_of_value_type_str = len_of_type_str - offset_of_value_type_str - 1;
    type_of_value = get_type(type_str + offset_of_value_type_str, len_of_value_type_str);
    return true;
}

bool ArrayTypeInfo::parse(zend_string *type_def) {
    if (type_def->len >= 65535) {
        zend_throw_error(nullptr, "The type definition string is too long (must be less than 65535 characters)");
        return false;
    }
    zend_string *lc_type_def = zend_string_tolower(type_def);
    memcpy(type_str, lc_type_def->val, lc_type_def->len + 1);
    len_of_type_str = lc_type_def->len;
    zend_string_release(lc_type_def);

    char *tmp_type_str = type_str;
    remove_all_spaces(&tmp_type_str, &len_of_type_str);
    tmp_type_str[len_of_type_str] = '\0';
    if (tmp_type_str != type_str) {
        memmove(type_str, tmp_type_str, len_of_type_str + 1);
    }

    if (type_str[0] != '<' || type_str[len_of_type_str - 1] != '>') {
        zend_throw_error(nullptr, "The type definition of typed array must start with '<' and end with '>'");
        return false;
    }
    if (!self.parse(type_str, len_of_type_str)) {
        return false;
    }

    if (self.type_of_value == IS_OBJECT) {
        zend::String type_str_of_value(type_str + self.offset_of_value_type_str, self.len_of_value_type_str);
        value_ce = zend_lookup_class(type_str_of_value.get());
        if (!value_ce) {
            zend_throw_error(nullptr, "Class '%s' not found", type_str_of_value.val());
            return false;
        }
    }

    return true;
}

PHP_FUNCTION(swoole_typed_array) {
    zend_string *type_def;
    zval *init_values = nullptr;

    ZEND_PARSE_PARAMETERS_START(1, 2)
    Z_PARAM_STR(type_def)
    Z_PARAM_OPTIONAL
    Z_PARAM_ARRAY(init_values)
    ZEND_PARSE_PARAMETERS_END();

    auto tmp_info = static_cast<ArrayTypeInfo *>(emalloc(sizeof(ArrayTypeInfo) + ZSTR_LEN(type_def) + 1));
    if (!tmp_info->parse(type_def)) {
        efree(tmp_info);
        RETURN_NULL();
    }

    if (init_values && is_typed_array(init_values)) {
        auto type_info = get_type_info(Z_ARRVAL_P(init_values));
        if (tmp_info->equals(type_info)) {
            ZVAL_COPY(return_value, init_values);
        } else {
            zend_throw_error(nullptr, "The type definition of the typed array does not match the initial values");
        }
        efree(tmp_info);
        return;
    }

    auto n = init_values ? zend_array_count(Z_ARRVAL_P(init_values)) : 0;
    auto array = make_typed_array(n, tmp_info->len_of_type_str);
    ZVAL_ARR(return_value, array);
    auto info = get_type_info(array);
    memcpy(info, tmp_info, sizeof(ArrayTypeInfo) + tmp_info->len_of_type_str + 1);
    efree(tmp_info);

    if (info->self.type_of_value == IS_ARRAY) {
        if (!info->element.parse(info->get_value_type_str(), info->get_len_of_value_type_str())) {
            zval_ptr_dtor(return_value);
            RETURN_NULL();
        }
    }

    if (init_values) {
        zend_string *str_key;
        zend_ulong num_key;
        zval *zv;
        zval zk;
        HashTable *ht = Z_ARRVAL_P(init_values);

        ZEND_HASH_FOREACH_KEY_VAL(ht, num_key, str_key, zv) {
            if (str_key) {
                ZVAL_STR(&zk, str_key);
            } else {
                ZVAL_LONG(&zk, num_key);
            }
            if (!info->check(array, &zk, zv)) {
                zval_ptr_dtor(return_value);
                RETURN_NULL();
            }
            Z_TRY_ADDREF_P(zv);
            if (str_key) {
                zend_hash_add(array, str_key, zv);
            } else {
                zend_hash_index_add(array, num_key, zv);
            }
        }
        ZEND_HASH_FOREACH_END();
    }
}

ZEND_HASH_FOREACH_KEY_VAL(ht, num_key, str_key, zv) {
            if (str_key) {
                ZVAL_STR(&zk, str_key);
            } else {
                ZVAL_LONG(&zk, num_key);
            }
            if (!info->check(array, &zk, zv)) {
                zval_ptr_dtor(return_value);
                RETURN_NULL();
            }
            Z_TRY_ADDREF_P(zv);
            if (str_key) {
                zend_hash_add(array, str_key, zv);
            } else {
                zend_hash_index_add(array, num_key, zv);
            }
        }

PHP_FUNCTION(swoole_array_is_typed) {
    zend_string *type_def = nullptr;
    zval *array;

    ZEND_PARSE_PARAMETERS_START(1, 2)
    Z_PARAM_ARRAY(array)
    Z_PARAM_OPTIONAL
    Z_PARAM_STR(type_def)
    ZEND_PARSE_PARAMETERS_END();

    HashTable *ht = Z_ARRVAL_P(array);
    if (!(HT_FLAGS(ht) & HASH_FLAG_TYPED_ARRAY)) {
        RETURN_FALSE;
    }
    if (!type_def) {
        RETURN_TRUE;
    }

    const auto tmp_info = static_cast<ArrayTypeInfo *>(emalloc(sizeof(ArrayTypeInfo) + ZSTR_LEN(type_def) + 1));
    if (!tmp_info->parse(type_def)) {
        efree(tmp_info);
        RETURN_FALSE;
    }

    const auto info = get_type_info(ht);
    RETVAL_BOOL(info->equals(tmp_info));
    efree(tmp_info);
}

static PHP_FUNCTION(swoole_array_push) {
    zval *arg_ptr = ZEND_CALL_ARG(execute_data, 1);
    const int arg_count = ZEND_CALL_NUM_ARGS(execute_data);
    zval *array = &arg_ptr[0];
    ZVAL_DEREF(array);

    if (Z_TYPE_P(array) == IS_ARRAY && is_typed_array(array)) {
        auto source = Z_ARRVAL_P(array);
        auto type_info = get_type_info(source);
        for (int i = 1; i < arg_count; i++) {
            if (!type_info->check(source, &EG(uninitialized_zval), &arg_ptr[i])) {
                return;
            }
        }
    }
    ori_handler_array_push(INTERNAL_FUNCTION_PARAM_PASSTHRU);
}

static PHP_FUNCTION(swoole_array_unshift) {
    zval *arg_ptr = ZEND_CALL_ARG(execute_data, 1);
    const int arg_count = ZEND_CALL_NUM_ARGS(execute_data);
    zval *array = &arg_ptr[0];
    ZVAL_DEREF(array);

    if (Z_TYPE_P(array) == IS_ARRAY && is_typed_array(array)) {
        auto source = Z_ARRVAL_P(array);
        auto type_info = get_type_info(source);
        for (int i = 1; i < arg_count; i++) {
            if (!type_info->check(source, &EG(uninitialized_zval), &arg_ptr[i])) {
                return;
            }
        }
        ori_handler_array_unshift(INTERNAL_FUNCTION_PARAM_PASSTHRU);
        HT_FLAGS(source) |= HASH_FLAG_TYPED_ARRAY;
    } else {
        ori_handler_array_unshift(INTERNAL_FUNCTION_PARAM_PASSTHRU);
    }
}

static PHP_FUNCTION(swoole_array_splice) {
    const zval *arg_ptr = ZEND_CALL_ARG(execute_data, 1);
    const int arg_count = ZEND_CALL_NUM_ARGS(execute_data);
    const zval *array = &arg_ptr[0];
    ZVAL_DEREF(array);
    if (Z_TYPE_P(array) == IS_ARRAY && is_typed_array(array)) {
        if (arg_count > 3) {
            auto type_info = get_type_info(Z_ARRVAL_P(array));
            auto values = &arg_ptr[3];
            ZVAL_DEREF(values);
            if (Z_TYPE_P(values) == IS_ARRAY) {
                zval *zv;
                HashTable *ht = Z_ARRVAL_P(values);
                ZEND_HASH_FOREACH_VAL(ht, zv) {
                    if (!type_info->check(Z_ARRVAL_P(array), &EG(uninitialized_zval), zv)) {
                        return;
                    }
                }
                ZEND_HASH_FOREACH_END();
            } else {
                if (!type_info->check(Z_ARRVAL_P(array), &EG(uninitialized_zval), values)) {
                    return;
                }
            }
        }
        const auto source = Z_ARRVAL_P(array);
        ori_handler_array_splice(execute_data, return_value);
        HT_FLAGS(source) |= HASH_FLAG_TYPED_ARRAY;
    } else {
        ori_handler_array_splice(execute_data, return_value);
    }
}

