static zend_always_inline zval *_get_zval_ptr_undef(int op_type, znode_op node, int type EXECUTE_DATA_DC OPLINE_DC) {
    if (op_type & (IS_TMP_VAR | IS_VAR)) {
        if (!ZEND_DEBUG || op_type == IS_VAR) {
