void add_gc_checkers_with_weakrefs(const py::object &obj) {
    py::handle global_capsule = py::detail::get_internals_capsule();
    if (!global_capsule) {
        throw std::runtime_error("No global internals capsule found");
    }
    (void) py::weakref(obj, py::cpp_function([global_capsule](py::handle weakref) -> void {
                           py::handle current_global_capsule = py::detail::get_internals_capsule();
                           if (!current_global_capsule.is(global_capsule)) {
                               throw std::runtime_error(
                                   "Global internals capsule was destroyed prematurely");
                           }
                           weakref.dec_ref();
                       }))
        .release();

    py::handle local_capsule = py::detail::get_local_internals_capsule();
    if (!local_capsule) {
        throw std::runtime_error("No local internals capsule found");
    }
    (void) py::weakref(
        obj, py::cpp_function([local_capsule](py::handle weakref) -> void {
            py::handle current_local_capsule = py::detail::get_local_internals_capsule();
            if (!current_local_capsule.is(local_capsule)) {
                throw std::runtime_error("Local internals capsule was destroyed prematurely");
            }
            weakref.dec_ref();
        }))
        .release();
}

DiamondAddrs diamond_addrs() {
    auto sp = std::make_shared<Diamond>();
    return DiamondAddrs{reinterpret_cast<uintptr_t>(sp.get()),
                        reinterpret_cast<uintptr_t>(static_cast<VBase *>(sp.get())),
                        reinterpret_cast<uintptr_t>(static_cast<Left *>(sp.get())),
                        reinterpret_cast<uintptr_t>(static_cast<Right *>(sp.get()))};
}

void unsafe_reset_internals_for_single_interpreter() {
    // unsafe normally, but for subsequent tests, put this back.. we know there are no threads
    // running and only 1 interpreter
    py::detail::get_num_interpreters_seen() = 1;
    py::detail::get_internals_pp<py::detail::internals>() = nullptr;
    py::detail::get_internals();
    py::detail::get_internals_pp<py::detail::local_internals>() = nullptr;
    py::detail::get_local_internals();
}

const char *determine_trampoline_state(const std::shared_ptr<VB> &sp) {
    if (!sp) {
        return "sp nullptr";
    }
    auto *tias = dynamic_cast<trampoline_is_alive_simple *>(sp.get());
    if (!tias) {
        return "dynamic_cast failed";
    }
    if (tias->magic_token == 197001010000u) {
        return "trampoline alive";
    }
    if (tias->magic_token == 20380118191407u) {
        return "trampoline DEAD";
    }
    return "UNDEFINED BEHAVIOR";
}

int get_code() const {
        if (!sp) {
            return -888;
        }
        return sp->get_code();
    }

int get_code() const {
        auto sp = wp.lock();
        if (!sp) {
            return -999;
        }
        return sp->get_code();
    }

void wrap(py::module_ &m,
          const char *roc_pyname,
          const char *rps_pyname,
          const char *spo_pyname,
          const char *wpo_pyname) {
    m.def(roc_pyname, rtrn_obj_cast_shared_ptr<VB>);
    m.def(rps_pyname, rtrn_potentially_slicing_shared_ptr<VB>);

    py::classh<SpOwner<VB>>(m, spo_pyname)
        .def(py::init<>())
        .def("set_sp", &SpOwner<VB>::set_sp)
        .def("get_code", &SpOwner<VB>::get_code)
        .def("get_trampoline_state", &SpOwner<VB>::get_trampoline_state);

    py::classh<WpOwner<VB>>(m, wpo_pyname)
        .def(py::init<>())
        .def("set_wp",
             [](WpOwner<VB> &self, py::handle obj) {
                 self.set_wp(obj.cast<std::shared_ptr<VB>>());
             })
        .def("set_wp_potentially_slicing",
             [](WpOwner<VB> &self, py::handle obj) {
                 self.set_wp(py::potentially_slicing_weak_ptr<VB>(obj));
             })
        .def("get_code", &WpOwner<VB>::get_code)
        .def("get_trampoline_state", &WpOwner<VB>::get_trampoline_state);
}

TEST_SUBMODULE(potentially_slicing_weak_ptr, m) {
    py::classh<VirtBaseSH, PyVirtBaseSH>(m, "VirtBaseSH")
        .def(py::init<>())
        .def("get_code", &VirtBaseSH::get_code);

    py::class_<VirtBaseSP, std::shared_ptr<VirtBaseSP>, PyVirtBaseSP>(m, "VirtBaseSP")
        .def(py::init<>())
        .def("get_code", &VirtBaseSP::get_code);

    wrap<VirtBaseSH>(m,
                     "SH_rtrn_obj_cast_shared_ptr",
                     "SH_rtrn_potentially_slicing_shared_ptr",
                     "SH_SpOwner",
                     "SH_WpOwner");

    wrap<VirtBaseSP>(m,
                     "SP_rtrn_obj_cast_shared_ptr",
                     "SP_rtrn_potentially_slicing_shared_ptr",
                     "SP_SpOwner",
                     "SP_WpOwner");
}

void AppMenuModel::updateRenameItemsState()
{
    const UiActionState actionState = uiActionsRegister()->actionState(RENAME_ITEM_CODE);

    MenuItem& renameClipItem = findItem(RENAME_CLIP_ITEM_ID);
    if (renameClipItem.isValid()) {
        UiActionState state = actionState;
        state.enabled = state.enabled && selectionController()->selectedClips().size() == 1;
        renameClipItem.setState(state);
    }

    MenuItem& renameLabelItem = findItem(RENAME_LABEL_ITEM_ID);
    if (renameLabelItem.isValid()) {
        UiActionState state = actionState;
        state.enabled = state.enabled && selectionController()->selectedLabels().size() == 1;
        renameLabelItem.setState(state);
    }
}

