uint32_t WeightOfTag(const std::string& tag) {
    if (tag.empty()) {
        return 1;
    }
    uint32_t weight = 0;
    if (!butil::StringToUint(tag, &weight) || weight == 0) {
        LOG(WARNING) << "Invalid weight tag=`" << tag << "', use weight=1";
        return 1;
    }
    return weight;
}

bool P2CEwmaLoadBalancer::Add(Servers& bg, const Servers& fg,
                              const ServerId& id) {
    if (bg.server_list.capacity() < 128) {
        bg.server_list.reserve(128);
    }
    if (bg.server_map.seek(id.id) != NULL) {
        return false;
    }
    ServerInfo info = { id.id, WeightOfTag(id.tag), NULL };
    const size_t* pindex = fg.server_map.seek(id.id);
    if (pindex == NULL) {
        // Both buffers do not have the server. Create the stat structure
        // which will be shared by both buffers.
        info.stat = std::make_shared<NodeStat>();
    } else {
        // Already added to the other buffer, share its stat.
        info.stat = fg.server_list[*pindex].stat;
    }
    bg.server_map[id.id] = bg.server_list.size();
    bg.server_list.push_back(info);
    return true;
}

bool P2CEwmaLoadBalancer::Remove(Servers& bg, const ServerId& id) {
    size_t* pindex = bg.server_map.seek(id.id);
    if (pindex == NULL) {
        return false;
    }
    const size_t index = *pindex;
    bg.server_list[index] = bg.server_list.back();
    bg.server_map[bg.server_list[index].id] = index;
    bg.server_list.pop_back();
    bg.server_map.erase(id.id);
    return true;
}

size_t P2CEwmaLoadBalancer::BatchAdd(
    Servers& bg, const Servers& fg, const std::vector<ServerId>& servers) {
    size_t count = 0;
    for (size_t i = 0; i < servers.size(); ++i) {
        count += !!Add(bg, fg, servers[i]);
    }
    return count;
}

size_t P2CEwmaLoadBalancer::BatchRemove(
    Servers& bg, const std::vector<ServerId>& servers) {
    size_t count = 0;
    for (size_t i = 0; i < servers.size(); ++i) {
        count += !!Remove(bg, servers[i]);
    }
    return count;
}

size_t P2CEwmaLoadBalancer::AddServersInBatch(
    const std::vector<ServerId>& servers) {
    const size_t n = _db_servers.ModifyWithForeground(BatchAdd, servers);
    LOG_IF(ERROR, n != servers.size())
        << "Fail to AddServersInBatch, expected " << servers.size()
        << " actually " << n;
    return n;
}

double P2CEwmaLoadBalancer::Score(
    const ServerInfo& info, int64_t now_us) const {
    const int64_t ewma_us =
        info.stat->ewma_us.load(butil::memory_order_relaxed);
    const int32_t inflight =
        info.stat->inflight.load(butil::memory_order_relaxed);
    double latency_term = MIN_LATENCY_TERM_US;
    if (ewma_us > 0) {
        // Decay the (possibly stale) EWMA at read time so that a server
        // penalized long ago regains traffic and gets re-observed.
        const int64_t stamp_us =
            info.stat->stamp_us.load(butil::memory_order_relaxed);
        const int64_t elapsed_us = now_us - stamp_us;
        double decayed = (double)ewma_us;
        if (elapsed_us > 0) {
            decayed *= std::exp(-(double)elapsed_us / (double)_tau_us);
        }
        latency_term = std::max(decayed, MIN_LATENCY_TERM_US);
    }
    // Clamp so that a transiently negative counter can not invert routing.
    const int32_t load = std::max(inflight + 1, 1);
    return latency_term * (double)load / (double)info.weight;
}

int P2CEwmaLoadBalancer::SelectServer(const SelectIn& in, SelectOut* out) {
    butil::DoublyBufferedData<Servers>::ScopedPtr s;
    if (_db_servers.Read(&s) != 0) {
        return ENOMEM;
    }
    const size_t n = s->server_list.size();
    if (n == 0) {
        return ENODATA;
    }
    // Reuse the caller-provided timestamp to avoid an extra clock read per
    // selection; only Channel::CheckHealth passes 0.
    const int64_t now_us = in.begin_time_us > 0
        ? in.begin_time_us : butil::gettimeofday_us();

    const ServerInfo* best = NULL;
    double best_score = 0;
    SocketUniquePtr best_ptr;
    // Score the server at `index' and keep it if it beats the current best.
    // Excluded and unavailable servers are skipped.
    auto consider = [&](size_t index) {
        const ServerInfo& info = s->server_list[index];
        if (ExcludedServers::IsExcluded(in.excluded, info.id)) {
            return;
        }
        SocketUniquePtr ptr;
        if (!IsServerAvailable(info.id, &ptr)) {
            return;
        }
        const double score = Score(info, now_us);
        if (best == NULL || score < best_score) {
            best = &info;
            best_score = score;
            best_ptr.swap(ptr);
        }
    };

    const size_t choices = std::min((size_t)_choices, n);
    if (choices >= n) {
        // Scan from a random offset so that equal scores do not herd all
        // clients onto the lowest-indexed server.
        const size_t start = butil::fast_rand_less_than(n);
        for (size_t i = 0; i < n; ++i) {
            consider((start + i) % n);
        }
    } else {
        // Sample `choices' distinct random servers. Attempts are bounded so
        // that duplicated draws never loop for long.
        size_t chosen[MAX_CHOICES];
        size_t nchosen = 0;
        const size_t max_attempts = 4 * choices + 8;
        for (size_t attempt = 0;
             attempt < max_attempts && nchosen < choices; ++attempt) {
            const size_t index = butil::fast_rand_less_than(n);
            bool duplicated = false;
            for (size_t i = 0; i < nchosen; ++i) {
                if (chosen[i] == index) {
                    duplicated = true;
                    break;
                }
            }
            if (duplicated) {
                continue;
            }
            chosen[nchosen++] = index;
            consider(index);
        }
        if (best == NULL) {
            // All sampled servers were excluded or unavailable, fall back
            // to scoring the whole list before violating exclusion below.
            for (size_t i = 0; i < n; ++i) {
                consider(i);
            }
        }
    }

    if (best == NULL) {
        // Always take last chance: all servers are excluded, send to any
        // available one as rr/random do.
        for (size_t i = 0; i < n; ++i) {
            if (IsServerAvailable(s->server_list[i].id, &best_ptr)) {
                best = &s->server_list[i];
                break;
            }
        }
        if (best == NULL) {
            return EHOSTDOWN;
        }
    }
    if (in.changable_weights) {
        best->stat->inflight.fetch_add(1, butil::memory_order_relaxed);
        out->need_feedback = true;
    }
    out->ptr->swap(best_ptr);
    return 0;
}

void P2CEwmaLoadBalancer::Feedback(const CallInfo& info) {
    butil::DoublyBufferedData<Servers>::ScopedPtr s;
    if (_db_servers.Read(&s) != 0) {
        return;
    }
    const size_t* pindex = s->server_map.seek(info.server_id);
    if (pindex == NULL) {
        // The server was removed after selection, its stat is gone with it.
        return;
    }
    NodeStat* stat = s->server_list[*pindex].stat.get();
    stat->inflight.fetch_sub(1, butil::memory_order_relaxed);

    const int64_t now_us = butil::gettimeofday_us();
    int64_t latency_us = now_us - info.begin_time_us;
    if (latency_us <= 0) {
        // time skews, ignore the sample.
        return;
    }
    if (info.error_code != 0) {
        // Punish failures with at least the timeout(if any) and twice the
        // current average, so that a failing server keeps losing comparisons
        // even when it fails fast.
        const int64_t timeout_us = info.controller->timeout_ms() * 1000L;
        latency_us = std::max(latency_us, timeout_us);
        latency_us = std::max(
            latency_us, 2 * stat->ewma_us.load(butil::memory_order_relaxed));
        // Cap the punishment: consecutive failures double the EWMA each
        // time, which otherwise grows without bound and delays recovery
        // after the server turns healthy.
        const int64_t max_punish_us = FLAGS_p2c_max_punish_ms * 1000L;
        if (max_punish_us > 0 && latency_us > max_punish_us) {
            latency_us = max_punish_us;
        }
    }

    BAIDU_SCOPED_LOCK(stat->update_mutex);
    const int64_t ewma_us = stat->ewma_us.load(butil::memory_order_relaxed);
    int64_t new_ewma_us = latency_us;
    if (ewma_us > 0 && latency_us < ewma_us) {
        // Downward samples decay the average while upward spikes(handled by
        // the branch above) replace it immediately.
        const int64_t elapsed_us =
            now_us - stat->stamp_us.load(butil::memory_order_relaxed);
        const double w = elapsed_us > 0
            ? std::exp(-(double)elapsed_us / (double)_tau_us) : 1.0;
        new_ewma_us = (int64_t)(ewma_us * w + latency_us * (1.0 - w));
    }
    stat->ewma_us.store(new_ewma_us, butil::memory_order_relaxed);
    stat->stamp_us.store(now_us, butil::memory_order_relaxed);
}

P2CEwmaLoadBalancer* P2CEwmaLoadBalancer::New(
    const butil::StringPiece& params) const {
    P2CEwmaLoadBalancer* lb = new (std::nothrow) P2CEwmaLoadBalancer;
    if (lb != NULL && !lb->SetParameters(params)) {
        delete lb;
        lb = NULL;
    }
    return lb;
}

bool P2CEwmaLoadBalancer::SetParameters(const butil::StringPiece& params) {
    for (butil::KeyValuePairsSplitter sp(params.begin(), params.end(), ' ', '=');
         sp; ++sp) {
        if (sp.value().empty()) {
            LOG(ERROR) << "Empty value for " << sp.key() << " in lb parameter";
            return false;
        }
        if (sp.key() == "choices") {
            unsigned choices = 0;
            if (!butil::StringToUint(sp.value().as_string(), &choices) ||
                choices < 2 || choices > MAX_CHOICES) {
                LOG(ERROR) << "Invalid choices=`" << sp.value() << "'";
                return false;
            }
            _choices = choices;
        } else if (sp.key() == "tau_ms") {
            int64_t tau_ms = 0;
            if (!butil::StringToInt64(sp.value(), &tau_ms) || tau_ms <= 0) {
                LOG(ERROR) << "Invalid tau_ms=`" << sp.value() << "'";
                return false;
            }
            _tau_us = tau_ms * 1000L;
        } else {
            LOG(ERROR) << "Unknown parameter " << sp.key_and_value();
            return false;
        }
    }
    return true;
}

void P2CEwmaLoadBalancer::Describe(
    std::ostream& os, const DescribeOptions& options) {
    if (!options.verbose) {
        os << "p2c";
        return;
    }
    os << "P2CEwma{choices=" << _choices << " tau_ms=" << _tau_us / 1000;
    butil::DoublyBufferedData<Servers>::ScopedPtr s;
    if (_db_servers.Read(&s) != 0) {
        os << " fail to read _db_servers";
    } else {
        const int64_t now_us = butil::gettimeofday_us();
        os << " n=" << s->server_list.size() << ':';
        for (size_t i = 0; i < s->server_list.size(); ++i) {
            const ServerInfo& info = s->server_list[i];
            os << ' ' << info.id << '(' << "w=" << info.weight
               << " ewma_us="
               << info.stat->ewma_us.load(butil::memory_order_relaxed)
               << " inflight="
               << info.stat->inflight.load(butil::memory_order_relaxed)
               << " score=" << Score(info, now_us) << ')';
        }
    }
    os << '}';
}

brpc::ServerId CreateServer(const char* addr, const char* tag = "") {
    butil::EndPoint point;
    EXPECT_EQ(0, str2endpoint(addr, &point));
    brpc::ServerId id(8888);
    brpc::SocketOptions options;
    options.remote_side = point;
    options.user = new SaveRecycle;
    EXPECT_EQ(0, brpc::Socket::Create(options, &id.id));
    id.tag = tag;
    return id;
}

void FeedbackLatency(brpc::LoadBalancer* lb, brpc::SocketId server_id,
                     int64_t latency_us, int error_code = 0,
                     const brpc::Controller* cntl = NULL) {
    brpc::LoadBalancer::CallInfo info;
    info.begin_time_us = butil::gettimeofday_us() - latency_us;
    info.server_id = server_id;
    info.error_code = error_code;
    info.controller = cntl;
    lb->Feedback(info);
}

int Select(brpc::SocketUniquePtr* ptr, bool* need_feedback = NULL,
               const brpc::ExcludedServers* excluded = NULL) {
        brpc::LoadBalancer::SelectIn in = {
            butil::gettimeofday_us(), true, false, 0u, excluded };
        brpc::LoadBalancer::SelectOut out(ptr);
        const int rc = _lb->SelectServer(in, &out);
        if (need_feedback != NULL) {
            *need_feedback = out.need_feedback;
        }
        return rc;
    }

TEST_F(P2CEwmaLoadBalancerTest, add_remove_servers) {
    brpc::SocketUniquePtr ptr;
    ASSERT_EQ(ENODATA, Select(&ptr));

    std::vector<brpc::ServerId> ids;
    ids.push_back(CreateServer("127.0.0.1:7777"));
    ids.push_back(CreateServer("127.0.0.1:7778"));
    ids.push_back(CreateServer("127.0.0.1:7779"));

    ASSERT_TRUE(_lb->AddServer(ids[0]));
    // Duplicated server is rejected.
    ASSERT_FALSE(_lb->AddServer(ids[0]));
    ASSERT_EQ(2u, _lb->AddServersInBatch(
        std::vector<brpc::ServerId>(ids.begin() + 1, ids.end())));

    ASSERT_EQ(0, Select(&ptr));

    ASSERT_TRUE(_lb->RemoveServer(ids[0]));
    ASSERT_FALSE(_lb->RemoveServer(ids[0]));
    ASSERT_EQ(2u, _lb->RemoveServersInBatch(
        std::vector<brpc::ServerId>(ids.begin() + 1, ids.end())));
    ASSERT_EQ(ENODATA, Select(&ptr));
}

TEST_F(P2CEwmaLoadBalancerTest, single_server) {
    const brpc::ServerId id = CreateServer("127.0.0.1:7780");
    ASSERT_TRUE(_lb->AddServer(id));
    for (int i = 0; i < 10; ++i) {
        brpc::SocketUniquePtr ptr;
        bool need_feedback = false;
        ASSERT_EQ(0, Select(&ptr, &need_feedback));
        ASSERT_EQ(id.id, ptr->id());
        ASSERT_TRUE(need_feedback);
        FeedbackLatency(_lb, id.id, 1000);
    }
}

TEST_F(P2CEwmaLoadBalancerTest, prefers_lower_latency) {
    const brpc::ServerId fast = CreateServer("127.0.0.1:7781");
    const brpc::ServerId slow = CreateServer("127.0.0.1:7782");
    ASSERT_TRUE(_lb->AddServer(fast));
    ASSERT_TRUE(_lb->AddServer(slow));

    // Servers respond with their characteristic latency; both get observed
    // within the first rounds because unobserved servers score best.
    std::map<brpc::SocketId, size_t> counts;
    const int kRounds = 1000;
    for (int i = 0; i < kRounds; ++i) {
        brpc::SocketUniquePtr ptr;
        ASSERT_EQ(0, Select(&ptr));
        ++counts[ptr->id()];
        // Selected server responds with its own characteristic latency.
        FeedbackLatency(_lb, ptr->id(), ptr->id() == fast.id ? 1000 : 50000);
    }
    LOG(INFO) << "fast=" << counts[fast.id] << " slow=" << counts[slow.id];
    // The fast server should receive almost all traffic.
    ASSERT_GE(counts[fast.id], (size_t)(0.9 * kRounds));
}

TEST_F(P2CEwmaLoadBalancerTest, sheds_degraded_server) {
    const brpc::ServerId a = CreateServer("127.0.0.1:7783");
    const brpc::ServerId b = CreateServer("127.0.0.1:7784");
    ASSERT_TRUE(_lb->AddServer(a));
    ASSERT_TRUE(_lb->AddServer(b));
    // Warm up with `b' slightly faster so it is the preferred server.
    for (int i = 0; i < 20; ++i) {
        brpc::SocketUniquePtr ptr;
        ASSERT_EQ(0, Select(&ptr));
        FeedbackLatency(_lb, ptr->id(), ptr->id() == a.id ? 1000 : 500);
    }

    // `b' degrades: its first slow response must shift traffic to `a'
    // immediately(peak-sensitivity), long before an averaging window would.
    std::map<brpc::SocketId, size_t> counts;
    for (int i = 0; i < 100; ++i) {
        brpc::SocketUniquePtr ptr;
        ASSERT_EQ(0, Select(&ptr));
        ++counts[ptr->id()];
        FeedbackLatency(_lb, ptr->id(), ptr->id() == a.id ? 1000 : 100000);
    }
    ASSERT_GE(counts[a.id], 90u);
}

TEST_F(P2CEwmaLoadBalancerTest, inflight_breaks_ties) {
    const brpc::ServerId a = CreateServer("127.0.0.1:7785");
    const brpc::ServerId b = CreateServer("127.0.0.1:7786");
    ASSERT_TRUE(_lb->AddServer(a));
    ASSERT_TRUE(_lb->AddServer(b));

    // With no latency observations, scores only differ by in-flight count,
    // so two selections without feedback must go to different servers.
    brpc::SocketUniquePtr ptr1;
    brpc::SocketUniquePtr ptr2;
    ASSERT_EQ(0, Select(&ptr1));
    ASSERT_EQ(0, Select(&ptr2));
    ASSERT_NE(ptr1->id(), ptr2->id());

    // After feedback(decrementing in-flight), both are tied again and the
    // third selection must not crash or fail.
    FeedbackLatency(_lb, ptr1->id(), 1000);
    FeedbackLatency(_lb, ptr2->id(), 1000);
    brpc::SocketUniquePtr ptr3;
    ASSERT_EQ(0, Select(&ptr3));
}

TEST_F(P2CEwmaLoadBalancerTest, weighted_split_by_inflight) {
    // With equal latency, steady-state in-flight counts converge to the
    // 1:2:4 weight ratio because the score is (inflight+1)/weight.
    const brpc::ServerId w1 = CreateServer("127.0.0.1:7787", "1");
    const brpc::ServerId w2 = CreateServer("127.0.0.1:7788", "2");
    const brpc::ServerId w4 = CreateServer("127.0.0.1:7789", "4");
    brpc::policy::P2CEwmaLoadBalancer* lb =
        _lb->New(butil::StringPiece("choices=3"));
    ASSERT_TRUE(lb != NULL);
    ASSERT_TRUE(lb->AddServer(w1));
    ASSERT_TRUE(lb->AddServer(w2));
    ASSERT_TRUE(lb->AddServer(w4));

    std::map<brpc::SocketId, size_t> counts;
    const int kRounds = 700;
    for (int i = 0; i < kRounds; ++i) {
        brpc::SocketUniquePtr ptr;
        brpc::LoadBalancer::SelectIn in = {
            butil::gettimeofday_us(), true, false, 0u, NULL };
        brpc::LoadBalancer::SelectOut out(&ptr);
        ASSERT_EQ(0, lb->SelectServer(in, &out));
        ++counts[ptr->id()];
        // No feedback: requests stay in flight.
    }
    LOG(INFO) << "w1=" << counts[w1.id] << " w2=" << counts[w2.id]
              << " w4=" << counts[w4.id];
    const double share1 = counts[w1.id] / (double)kRounds;
    const double share2 = counts[w2.id] / (double)kRounds;
    const double share4 = counts[w4.id] / (double)kRounds;
    ASSERT_NEAR(share1, 1.0 / 7, 0.05);
    ASSERT_NEAR(share2, 2.0 / 7, 0.05);
    ASSERT_NEAR(share4, 4.0 / 7, 0.05);
    lb->Destroy();
}

TEST_F(P2CEwmaLoadBalancerTest, error_feedback_punishes_server) {
    const brpc::ServerId good = CreateServer("127.0.0.1:7790");
    const brpc::ServerId bad = CreateServer("127.0.0.1:7791");
    ASSERT_TRUE(_lb->AddServer(good));
    ASSERT_TRUE(_lb->AddServer(bad));
    // Warm up with `bad' slightly faster so it is the preferred server.
    for (int i = 0; i < 20; ++i) {
        brpc::SocketUniquePtr ptr;
        ASSERT_EQ(0, Select(&ptr));
        FeedbackLatency(_lb, ptr->id(), ptr->id() == good.id ? 1000 : 500);
    }

    // `bad' starts failing fast(1ms), but failures are punished with at
    // least the RPC timeout so it keeps losing selections.
    brpc::Controller cntl;
    cntl.set_timeout_ms(100);
    std::map<brpc::SocketId, size_t> counts;
    for (int i = 0; i < 100; ++i) {
        brpc::SocketUniquePtr ptr;
        ASSERT_EQ(0, Select(&ptr));
        ++counts[ptr->id()];
        if (ptr->id() == good.id) {
            FeedbackLatency(_lb, good.id, 1000);
        } else {
            FeedbackLatency(_lb, bad.id, 1000, ETIMEDOUT, &cntl);
        }
    }
    ASSERT_GE(counts[good.id], 90u);
}

TEST_F(P2CEwmaLoadBalancerTest, excluded_servers) {
    const brpc::ServerId a = CreateServer("127.0.0.1:7792");
    const brpc::ServerId b = CreateServer("127.0.0.1:7793");
    ASSERT_TRUE(_lb->AddServer(a));
    ASSERT_TRUE(_lb->AddServer(b));

    brpc::ExcludedServers* excluded = brpc::ExcludedServers::Create(2);
    excluded->Add(a.id);
    for (int i = 0; i < 20; ++i) {
        brpc::SocketUniquePtr ptr;
        ASSERT_EQ(0, Select(&ptr, NULL, excluded));
        ASSERT_EQ(b.id, ptr->id());
        FeedbackLatency(_lb, b.id, 1000);
    }
    // All servers excluded: still take the last chance instead of failing.
    excluded->Add(b.id);
    brpc::SocketUniquePtr ptr;
    ASSERT_EQ(0, Select(&ptr, NULL, excluded));
    brpc::ExcludedServers::Destroy(excluded);
}

TEST_F(P2CEwmaLoadBalancerTest, invalid_parameters) {
    brpc::LoadBalancer* lb = _lb->New(butil::StringPiece(""));
    ASSERT_TRUE(lb != NULL);
    lb->Destroy();
    lb = _lb->New(butil::StringPiece("choices=4 tau_ms=5000"));
    ASSERT_TRUE(lb != NULL);
    lb->Destroy();
    ASSERT_TRUE(_lb->New(butil::StringPiece("choices=1")) == NULL);
    ASSERT_TRUE(_lb->New(butil::StringPiece("choices=abc")) == NULL);
    ASSERT_TRUE(_lb->New(butil::StringPiece("tau_ms=0")) == NULL);
    ASSERT_TRUE(_lb->New(butil::StringPiece("unknown=1")) == NULL);
}

void* SelectAndFeedback(void* void_arg) {
    ChurnArg* arg = static_cast<ChurnArg*>(void_arg);
    while (!arg->stop.load(butil::memory_order_relaxed)) {
        brpc::SocketUniquePtr ptr;
        brpc::LoadBalancer::SelectIn in = {
            butil::gettimeofday_us(), true, false, 0u, NULL };
        brpc::LoadBalancer::SelectOut out(&ptr);
        if (arg->lb->SelectServer(in, &out) == 0) {
            arg->nselected.fetch_add(1, butil::memory_order_relaxed);
            if (out.need_feedback) {
                FeedbackLatency(arg->lb, ptr->id(), 1000);
            }
        }
    }
    return NULL;
}

TEST_F(P2CEwmaLoadBalancerTest, concurrent_select_with_churn) {
    std::vector<brpc::ServerId> ids;
    for (int i = 0; i < 8; ++i) {
        char addr[32];
        snprintf(addr, sizeof(addr), "127.0.0.1:%d", 7800 + i);
        ids.push_back(CreateServer(addr));
        ASSERT_TRUE(_lb->AddServer(ids.back()));
    }

    ChurnArg arg;
    arg.lb = _lb;
    arg.stop.store(false);
    arg.nselected.store(0);
    pthread_t threads[4];
    for (size_t i = 0; i < ARRAY_SIZE(threads); ++i) {
        ASSERT_EQ(0, pthread_create(
            &threads[i], NULL, SelectAndFeedback, &arg));
    }
    // Churn membership while selections are running.
    const int64_t stop_at_us = butil::gettimeofday_us() + 1000000L;
    while (butil::gettimeofday_us() < stop_at_us) {
        ASSERT_TRUE(_lb->RemoveServer(ids[0]));
        ASSERT_TRUE(_lb->AddServer(ids[0]));
    }
    arg.stop.store(true);
    for (size_t i = 0; i < ARRAY_SIZE(threads); ++i) {
        ASSERT_EQ(0, pthread_join(threads[i], NULL));
    }
    LOG(INFO) << "selected " << arg.nselected.load() << " times";
    ASSERT_GT(arg.nselected.load(), 0u);
}

TEST_F(P2CEwmaLoadBalancerTest, error_punish_is_capped) {
    const brpc::ServerId id = CreateServer("127.0.0.1:7900");
    ASSERT_TRUE(_lb->AddServer(id));
    brpc::Controller cntl;
    cntl.set_timeout_ms(100);
    // Persistent failures double the punished EWMA per sample; without the
    // cap 64 rounds would push it past 2^64.
    for (int i = 0; i < 64; ++i) {
        brpc::SocketUniquePtr ptr;
        ASSERT_EQ(0, Select(&ptr));
        FeedbackLatency(_lb, id.id, 1000, ETIMEDOUT, &cntl);
    }
    std::ostringstream os;
    brpc::DescribeOptions options;
    options.verbose = true;
    _lb->Describe(os, options);
    const std::string desc = os.str();
    const size_t pos = desc.find("ewma_us=");
    ASSERT_NE(std::string::npos, pos) << desc;
    const int64_t ewma_us = strtoll(desc.c_str() + pos + 8, NULL, 10);
    ASSERT_LE(ewma_us, brpc::policy::FLAGS_p2c_max_punish_ms * 1000L) << desc;
}

void* FeedbackHammer(void* void_arg) {
    FeedbackBenchArg* arg = static_cast<FeedbackBenchArg*>(void_arg);
    size_t n = 0;
    while (!arg->stop.load(butil::memory_order_relaxed)) {
        FeedbackLatency(arg->lb, arg->server_id, 1000);
        ++n;
    }
    arg->nfeedback.fetch_add(n, butil::memory_order_relaxed);
    return NULL;
}

TEST_F(P2CEwmaLoadBalancerTest, feedback_lock_overhead) {
    // All threads feed back to a single server so update_mutex sees
    // worst-case contention.
    const brpc::ServerId id = CreateServer("127.0.0.1:7901");
    ASSERT_TRUE(_lb->AddServer(id));
    for (size_t nthread = 1; nthread <= 4; nthread *= 2) {
        FeedbackBenchArg arg;
        arg.lb = _lb;
        arg.server_id = id.id;
        arg.stop.store(false);
        arg.nfeedback.store(0);
        pthread_t threads[4];
        const int64_t begin_us = butil::gettimeofday_us();
        for (size_t i = 0; i < nthread; ++i) {
            ASSERT_EQ(0, pthread_create(
                &threads[i], NULL, FeedbackHammer, &arg));
        }
        usleep(500 * 1000);
        arg.stop.store(true);
        for (size_t i = 0; i < nthread; ++i) {
            ASSERT_EQ(0, pthread_join(threads[i], NULL));
        }
        const int64_t elapsed_us = butil::gettimeofday_us() - begin_us;
        const size_t n = arg.nfeedback.load();
        ASSERT_GT(n, 0u);
        LOG(INFO) << "Feedback on 1 shared server, " << nthread
                  << " thread(s): " << (elapsed_us * 1000L * nthread) / n
                  << "ns/op (" << n << " ops in " << elapsed_us / 1000 << "ms)";
    }
}

static bool access_mysql(brpc::Channel& channel, const char* command) {
    brpc::MysqlRequest request;
    if (!request.Query(command)) {
        LOG(ERROR) << "Fail to add command";
        return false;
    }
    brpc::MysqlResponse response;
    brpc::Controller cntl;
    channel.CallMethod(NULL, &cntl, &request, &response, NULL);
    if (!cntl.Failed()) {
        std::cout << response << std::endl;
    } else {
        LOG(ERROR) << "Fail to access mysql, " << cntl.ErrorText();
        return false;
    }
    return true;
}

static int cli_getc(FILE* stream) {
    int c = getc(stream);
    if (c == EOF && errno == EINTR) {
        g_canceled = true;
        return '\n';
    }
    return c;
}

int main(int argc, char* argv[]) {
    // Parse gflags. We recommend you to use gflags as well.
    GFLAGS_NS::ParseCommandLineFlags(&argc, &argv, true);

    // A Channel represents a communication line to a Server. Notice that
    // Channel is thread-safe and can be shared by all threads in your program.
    brpc::Channel channel;

    // Initialize the channel, NULL means using default options.
    brpc::ChannelOptions options;
    options.protocol = brpc::PROTOCOL_MYSQL;
    options.connection_type = FLAGS_connection_type;
    options.timeout_ms = FLAGS_timeout_ms /*milliseconds*/;
    options.connect_timeout_ms = FLAGS_connect_timeout_ms;
    options.max_retry = FLAGS_max_retry;
    options.auth = new brpc::policy::MysqlAuthenticator(
        FLAGS_user, FLAGS_password, FLAGS_schema, FLAGS_params, FLAGS_collation);
    if (channel.Init(FLAGS_server.c_str(), FLAGS_port, &options) != 0) {
        LOG(ERROR) << "Fail to initialize channel";
        return -1;
    }

    if (argc <= 1) {  // interactive mode
        // We need this dummy signal hander to interrupt getc (and returning
        // EINTR), SIG_IGN did not work.
        signal(SIGINT, dummy_handler);

        // Hook getc of readline.
        rl_getc_function = cli_getc;

        // Print welcome information.
        printf("%s\n", brpc::logo());
        printf(
            "This command-line tool mimics the look-n-feel of official "
            "mysql-cli, as a demostration of brpc's capability of"
            " talking to mysql-server. The output and behavior is "
            "not exactly same with the official one.\n\n");

        for (;;) {
            char prompt[128];
            snprintf(prompt, sizeof(prompt), "mysql %s> ", FLAGS_server.c_str());
            std::unique_ptr<char, Freer> command(readline(prompt));
            if (command == NULL || *command == '\0') {
                if (g_canceled) {
                    // No input after the prompt and user pressed Ctrl-C,
                    // quit the CLI.
                    return 0;
                }
                // User entered an empty command by just pressing Enter.
                continue;
            }
            if (g_canceled) {
                // User entered sth. and pressed Ctrl-C, start a new prompt.
                g_canceled = false;
                continue;
            }
            // Add user's command to history so that it's browse-able by
            // UP-key and search-able by Ctrl-R.
            add_history(command.get());

            if (!strcmp(command.get(), "help")) {
                printf("This is a mysql CLI written in brpc.\n");
                continue;
            }
            if (!strcmp(command.get(), "quit")) {
                // Although quit is a valid mysql command, it does not make
                // too much sense to run it in this CLI, just quit.
                return 0;
            }
            access_mysql(channel, command.get());
        }
    } else {
        std::string command;
        command.reserve(argc * 16);
        for (int i = 1; i < argc; ++i) {
            if (i != 1) {
                command.push_back(';');
            }
            command.append(argv[i]);
        }
        if (!access_mysql(channel, command.c_str())) {
            return -1;
        }
    }
    return 0;
}

static void* sender(void* void_args) {
    SenderArgs* args = (SenderArgs*)void_args;
    std::stringstream command;
    if (FLAGS_op_type == 0) {
        command << insert;
    } else if (FLAGS_op_type == 1) {
        command << "select * from brpc_press where id = " << args->base_index + 1;
    } else if (FLAGS_op_type == 2) {
        command << "update brpc_press set col2 = '" + FLAGS_data + "' where id = "
                << args->base_index + 1;
    } else {
        LOG(ERROR) << "wrong op type " << FLAGS_op_type;
    }

    brpc::MysqlRequest request;
    if (!request.Query(command.str())) {
        LOG(ERROR) << "Fail to execute command";
        return NULL;
    }

    while (!brpc::IsAskedToQuit()) {
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        args->mysql_channel->CallMethod(NULL, &cntl, &request, &response, NULL);
        const int64_t elp = cntl.latency_us();
        if (!cntl.Failed()) {
            g_latency_recorder << elp;
            if (FLAGS_op_type == 0) {
                CHECK_EQ(response.reply(0).is_ok(), true);
            } else if (FLAGS_op_type == 1) {
                CHECK_EQ(response.reply(0).row_count(), 1);
            } else if (FLAGS_op_type == 2) {
                CHECK_EQ(response.reply(0).is_ok(), true);
            }
        } else {
            g_error_count << 1;
            CHECK(brpc::IsAskedToQuit() || !FLAGS_dont_fail)
                << "error=" << cntl.ErrorText() << " latency=" << elp;
            // We can't connect to the server, sleep a while. Notice that this
            // is a specific sleeping to prevent this thread from spinning too
            // fast. You should continue the business logic in a production
            // server rather than sleeping.
            bthread_usleep(50000);
        }
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    // Parse gflags. We recommend you to use gflags as well.
    GFLAGS_NS::ParseCommandLineFlags(&argc, &argv, true);

    // A Channel represents a communication line to a Server. Notice that
    // Channel is thread-safe and can be shared by all threads in your program.
    brpc::Channel channel;

    // Initialize the channel, NULL means using default options.
    brpc::ChannelOptions options;
    options.protocol = brpc::PROTOCOL_MYSQL;
    options.connection_type = FLAGS_connection_type;
    options.timeout_ms = FLAGS_timeout_ms /*milliseconds*/;
    options.connect_timeout_ms = FLAGS_connect_timeout_ms;
    options.max_retry = FLAGS_max_retry;
    options.auth = new brpc::policy::MysqlAuthenticator(
        FLAGS_user, FLAGS_password, FLAGS_schema, FLAGS_params, FLAGS_collation);
    if (channel.Init(FLAGS_server.c_str(), FLAGS_port, &options) != 0) {
        LOG(ERROR) << "Fail to initialize channel";
        return -1;
    }

    // create table brpc_press
    {
        brpc::MysqlRequest request;
        if (!request.Query(
                "CREATE TABLE IF NOT EXISTS `brpc_press`(`id` INT UNSIGNED AUTO_INCREMENT, `col1` "
                "VARCHAR(100) NOT NULL, `col2` VARCHAR(1024) NOT NULL, `col3` decimal(10,0) NOT "
                "NULL, `col4` DATE, PRIMARY KEY ( `id` )) ENGINE=InnoDB DEFAULT CHARSET=utf8;")) {
            LOG(ERROR) << "Fail to create table";
            return -1;
        }
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel.CallMethod(NULL, &cntl, &request, &response, NULL);
        if (!cntl.Failed()) {
            std::cout << response << std::endl;
        } else {
            LOG(ERROR) << "Fail to access mysql, " << cntl.ErrorText();
            return -1;
        }
    }

    // truncate table
    {
        brpc::MysqlRequest request;
        if (!request.Query("truncate table brpc_press")) {
            LOG(ERROR) << "Fail to truncate table";
            return -1;
        }
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel.CallMethod(NULL, &cntl, &request, &response, NULL);
        if (!cntl.Failed()) {
            std::cout << response << std::endl;
        } else {
            LOG(ERROR) << "Fail to access mysql, " << cntl.ErrorText();
            return -1;
        }
    }

    // prepare data for select, update
    if (FLAGS_op_type != 0) {
        for (int i = 0; i < FLAGS_thread_num; ++i) {
            brpc::MysqlRequest request;
            if (!request.Query(insert)) {
                LOG(ERROR) << "Fail to execute command";
                return -1;
            }
            brpc::MysqlResponse response;
            brpc::Controller cntl;
            channel.CallMethod(NULL, &cntl, &request, &response, NULL);
            if (cntl.Failed()) {
                LOG(ERROR) << cntl.ErrorText();
                return -1;
            }
            if (!response.reply(0).is_ok()) {
                LOG(ERROR) << "prepare data failed";
                return -1;
            }
        }
    }

    if (FLAGS_dummy_port >= 0) {
        brpc::StartDummyServerAt(FLAGS_dummy_port);
    }

    // test CRUD operations
    std::vector<bthread_t> bids;
    std::vector<pthread_t> pids;
    bids.resize(FLAGS_thread_num);
    pids.resize(FLAGS_thread_num);
    std::vector<SenderArgs> args;
    args.resize(FLAGS_thread_num);
    for (int i = 0; i < FLAGS_thread_num; ++i) {
        args[i].base_index = i;
        args[i].mysql_channel = &channel;
        if (!FLAGS_use_bthread) {
            if (pthread_create(&pids[i], NULL, sender, &args[i]) != 0) {
                LOG(ERROR) << "Fail to create pthread";
                return -1;
            }
        } else {
            if (bthread_start_background(&bids[i], NULL, sender, &args[i]) != 0) {
                LOG(ERROR) << "Fail to create bthread";
                return -1;
            }
        }
    }

    while (!brpc::IsAskedToQuit()) {
        sleep(1);

        LOG(INFO) << "Accessing mysql-server at qps=" << g_latency_recorder.qps(1)
                  << " latency=" << g_latency_recorder.latency(1);
    }

    LOG(INFO) << "mysql_client is going to quit";
    for (int i = 0; i < FLAGS_thread_num; ++i) {
        if (!FLAGS_use_bthread) {
            pthread_join(pids[i], NULL);
        } else {
            bthread_join(bids[i], NULL);
        }
    }

    return 0;
}

static void* access_mysql(void* void_args) {
    SenderArgs* args = (SenderArgs*)void_args;
    brpc::Channel* channel = args->mysql_channel;
    brpc::MysqlStatement* stmt = args->mysql_stmt;
    const std::vector<std::string>& commands = args->commands;

    for (int i = 0; i < FLAGS_count; ++i) {
        brpc::MysqlRequest request(stmt);
        for (size_t i = 1; i < commands.size(); i += 2) {
            if (commands[i] == "int8") {
                int8_t val = strtol(commands[i + 1].c_str(), NULL, 10);
                if (!request.AddParam(val)) {
                    LOG(ERROR) << "Fail to add int8 param";
                    return NULL;
                }
            } else if (commands[i] == "uint8") {
                uint8_t val = strtoul(commands[i + 1].c_str(), NULL, 10);
                if (!request.AddParam(val)) {
                    LOG(ERROR) << "Fail to add uint8 param";
                    return NULL;
                }
            } else if (commands[i] == "int16") {
                int16_t val = strtol(commands[i + 1].c_str(), NULL, 10);
                if (!request.AddParam(val)) {
                    LOG(ERROR) << "Fail to add uint16 param";
                    return NULL;
                }
            } else if (commands[i] == "uint16") {
                uint16_t val = strtoul(commands[i + 1].c_str(), NULL, 10);
                if (!request.AddParam(val)) {
                    LOG(ERROR) << "Fail to add uint16 param";
                    return NULL;
                }
            } else if (commands[i] == "int32") {
                int32_t val = strtol(commands[i + 1].c_str(), NULL, 10);
                if (!request.AddParam(val)) {
                    LOG(ERROR) << "Fail to add int32 param";
                    return NULL;
                }
            } else if (commands[i] == "uint32") {
                uint32_t val = strtoul(commands[i + 1].c_str(), NULL, 10);
                if (!request.AddParam(val)) {
                    LOG(ERROR) << "Fail to add uint32 param";
                    return NULL;
                }
            } else if (commands[i] == "int64") {
                int64_t val = strtol(commands[i + 1].c_str(), NULL, 10);
                if (!request.AddParam(val)) {
                    LOG(ERROR) << "Fail to add int64 param";
                    return NULL;
                }
            } else if (commands[i] == "uint64") {
                uint64_t val = strtoul(commands[i + 1].c_str(), NULL, 10);
                if (!request.AddParam(val)) {
                    LOG(ERROR) << "Fail to add uint64 param";
                    return NULL;
                }
            } else if (commands[i] == "float") {
                float val = strtof(commands[i + 1].c_str(), NULL);
                if (!request.AddParam(val)) {
                    LOG(ERROR) << "Fail to add float param";
                    return NULL;
                }
            } else if (commands[i] == "double") {
                double val = strtod(commands[i + 1].c_str(), NULL);
                if (!request.AddParam(val)) {
                    LOG(ERROR) << "Fail to add double param";
                    return NULL;
                }
            } else if (commands[i] == "string") {
                if (!request.AddParam(commands[i + 1])) {
                    LOG(ERROR) << "Fail to add string param";
                    return NULL;
                }
            } else {
                LOG(ERROR) << "Wrong param type " << commands[i];
            }
        }

        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel->CallMethod(NULL, &cntl, &request, &response, NULL);
        if (cntl.Failed()) {
            LOG(ERROR) << "Fail to access mysql, " << cntl.ErrorText();
            return NULL;
        }

        std::cout << response << std::endl;
    }

    return NULL;
}

int main(int argc, char* argv[]) {
    // Parse gflags. We recommend you to use gflags as well.
    GFLAGS_NS::ParseCommandLineFlags(&argc, &argv, true);

    // A Channel represents a communication line to a Server. Notice that
    // Channel is thread-safe and can be shared by all threads in your program.
    brpc::Channel channel;

    // Initialize the channel, NULL means using default options.
    brpc::ChannelOptions options;
    options.protocol = brpc::PROTOCOL_MYSQL;
    options.connection_type = FLAGS_connection_type;
    options.timeout_ms = FLAGS_timeout_ms /*milliseconds*/;
    options.connect_timeout_ms = FLAGS_connect_timeout_ms;
    options.max_retry = FLAGS_max_retry;
    options.auth = new brpc::policy::MysqlAuthenticator(
        FLAGS_user, FLAGS_password, FLAGS_schema, FLAGS_params, FLAGS_collation);
    if (channel.Init(FLAGS_server.c_str(), FLAGS_port, &options) != 0) {
        LOG(ERROR) << "Fail to initialize channel";
        return -1;
    }

    if (argc <= 1) {
        LOG(ERROR) << "No sql statement args";
    } else {
        std::vector<std::string> commands;
        commands.reserve(argc * 16);
        for (int i = 1; i < argc; ++i) {
            commands.push_back(argv[i]);
        }
        auto stmt(brpc::NewMysqlStatement(channel, commands[0]));
        if (stmt == NULL) {
            LOG(ERROR) << "Fail to create mysql statement";
            return -1;
        }

        std::vector<SenderArgs> args;
        std::vector<bthread_t> bids;
        args.resize(FLAGS_thread_num);
        bids.resize(FLAGS_thread_num);

        for (int i = 0; i < FLAGS_thread_num; ++i) {
            args[i].mysql_channel = &channel;
            args[i].mysql_stmt = stmt.get();
            args[i].commands = commands;
            if (bthread_start_background(&bids[i], NULL, access_mysql, &args[i]) != 0) {
                LOG(ERROR) << "Fail to create bthread";
                return -1;
            }
        }

        for (int i = 0; i < FLAGS_thread_num; ++i) {
            bthread_join(bids[i], NULL);
        }
    }

    return 0;
}

static bool access_mysql(brpc::Channel& channel, const std::vector<std::string>& commands) {
    brpc::MysqlTransactionOptions options;
    options.readonly = FLAGS_readonly;
    options.isolation_level = brpc::MysqlIsolationLevel(FLAGS_isolation_level);
    auto tx(brpc::NewMysqlTransaction(channel, options));
    if (tx == NULL) {
        LOG(ERROR) << "Fail to create transaction";
        return false;
    }

    for (auto it = commands.begin(); it != commands.end(); ++it) {
        brpc::MysqlRequest request(tx.get());
        if (!request.Query(*it)) {
            LOG(ERROR) << "Fail to add command";
            tx->rollback();
            return false;
        }
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel.CallMethod(NULL, &cntl, &request, &response, NULL);
        if (cntl.Failed()) {
            LOG(ERROR) << "Fail to access mysql, " << cntl.ErrorText();
            tx->rollback();
            return false;
        }
        // check response
        std::cout << response << std::endl;
        for (size_t i = 0; i < response.reply_size(); ++i) {
            if (response.reply(i).is_error()) {
                tx->rollback();
                return false;
            }
        }
    }
    tx->commit();
    return true;
}

int main(int argc, char* argv[]) {
    // Parse gflags. We recommend you to use gflags as well.
    GFLAGS_NS::ParseCommandLineFlags(&argc, &argv, true);

    // A Channel represents a communication line to a Server. Notice that
    // Channel is thread-safe and can be shared by all threads in your program.
    brpc::Channel channel;

    // Initialize the channel, NULL means using default options.
    brpc::ChannelOptions options;
    options.protocol = brpc::PROTOCOL_MYSQL;
    options.connection_type = FLAGS_connection_type;
    options.timeout_ms = FLAGS_timeout_ms /*milliseconds*/;
    options.connect_timeout_ms = FLAGS_connect_timeout_ms;
    options.max_retry = FLAGS_max_retry;
    options.auth = new brpc::policy::MysqlAuthenticator(
        FLAGS_user, FLAGS_password, FLAGS_schema, FLAGS_params, FLAGS_collation);
    if (channel.Init(FLAGS_server.c_str(), FLAGS_port, &options) != 0) {
        LOG(ERROR) << "Fail to initialize channel";
        return -1;
    }

    if (argc <= 1) {
        LOG(ERROR) << "No sql statement args";
    } else {
        std::vector<std::string> commands;
        commands.reserve(argc * 16);
        for (int i = 1; i < argc; ++i) {
            commands.push_back(argv[i]);
        }
        if (!access_mysql(channel, commands)) {
            return -1;
        }
    }
    return 0;
}

static void* sender(void* void_args) {
    SenderArgs* args = (SenderArgs*)void_args;
    std::stringstream command;
    if (FLAGS_op_type == 0) {
        command << insert;
    } else if (FLAGS_op_type == 1) {
        command << "select * from mysqlclient_press where id = " << args->base_index + 1;
    } else if (FLAGS_op_type == 2) {
        command << "update brpc_press set col2 = '" + FLAGS_data + "' where id = "
                << args->base_index + 1;
    } else {
        LOG(ERROR) << "wrong op type " << FLAGS_op_type;
    }

    std::string command_str = command.str();

    while (!brpc::IsAskedToQuit()) {
        const int64_t begin_time_us = butil::cpuwide_time_us();
        const int rc = mysql_real_query(args->mysql_conn, command_str.c_str(), command_str.size());
        if (rc != 0) {
            goto ERROR;
        }

        if (mysql_errno(args->mysql_conn) == 0) {
            if (FLAGS_op_type == 0) {
                CHECK_EQ(mysql_affected_rows(args->mysql_conn), 1);
            } else if (FLAGS_op_type == 1) {
                MYSQL_RES* res = mysql_store_result(args->mysql_conn);
                if (res == NULL) {
                    LOG(INFO) << "not found";
                } else {
                    CHECK_EQ(mysql_num_rows(res), 1);
                    mysql_free_result(res);
                }
            } else if (FLAGS_op_type == 2) {
            }
            const int64_t elp = butil::cpuwide_time_us() - begin_time_us;
            g_latency_recorder << elp;
        } else {
            goto ERROR;
        }

        if (false) {
        ERROR:
            const int64_t elp = butil::cpuwide_time_us() - begin_time_us;
            g_error_count << 1;
            CHECK(brpc::IsAskedToQuit() || !FLAGS_dont_fail)
                << "error=" << mysql_error(args->mysql_conn) << " latency=" << elp;
            // We can't connect to the server, sleep a while. Notice that this
            // is a specific sleeping to prevent this thread from spinning too
            // fast. You should continue the business logic in a production
            // server rather than sleeping.
            bthread_usleep(50000);
        }
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    // Parse gflags. We recommend you to use gflags as well.
    GFLAGS_NS::ParseCommandLineFlags(&argc, &argv, true);

    if (FLAGS_dummy_port >= 0) {
        brpc::StartDummyServerAt(FLAGS_dummy_port);
    }

    MYSQL* conn = mysql_init(NULL);
    if (!mysql_real_connect(conn,
                            FLAGS_server.c_str(),
                            FLAGS_user.c_str(),
                            FLAGS_password.c_str(),
                            FLAGS_schema.c_str(),
                            FLAGS_port,
                            NULL,
                            0)) {
        LOG(ERROR) << mysql_error(conn);
        return -1;
    }

    // create table mysqlclient_press
    {
        const char* sql =
            "CREATE TABLE IF NOT EXISTS `mysqlclient_press`(`id` INT UNSIGNED AUTO_INCREMENT, "
            "`col1` "
            "VARCHAR(100) NOT NULL, `col2` VARCHAR(1024) NOT NULL, `col3` decimal(10,0) NOT "
            "NULL, `col4` DATE, PRIMARY KEY ( `id` )) ENGINE=InnoDB DEFAULT CHARSET=utf8;";
        const int rc = mysql_real_query(conn, sql, strlen(sql));
        if (rc != 0) {
            LOG(ERROR) << "Fail to execute sql, " << mysql_error(conn);
            return -1;
        }

        if (mysql_errno(conn) != 0) {
            LOG(ERROR) << "Fail to store result, " << mysql_error(conn);
            return -1;
        }
    }

    // truncate table
    {
        const char* sql = "truncate table mysqlclient_press";
        const int rc = mysql_real_query(conn, sql, strlen(sql));
        if (rc != 0) {
            LOG(ERROR) << "Fail to execute sql, " << mysql_error(conn);
            return -1;
        }

        if (mysql_errno(conn) != 0) {
            LOG(ERROR) << "Fail to store result, " << mysql_error(conn);
            return -1;
        }
    }

    // prepare data for select, update
    if (FLAGS_op_type != 0) {
        for (int i = 0; i < FLAGS_thread_num; ++i) {
            const int rc = mysql_real_query(conn, insert.c_str(), insert.size());
            if (rc != 0) {
                LOG(ERROR) << "Fail to execute sql, " << mysql_error(conn);
                return -1;
            }

            if (mysql_errno(conn) != 0) {
                LOG(ERROR) << "Fail to store result, " << mysql_error(conn);
                return -1;
            }
        }
    }

    // test CRUD operations
    std::vector<bthread_t> bids;
    std::vector<pthread_t> pids;
    bids.resize(FLAGS_thread_num);
    pids.resize(FLAGS_thread_num);
    std::vector<SenderArgs> args;
    args.resize(FLAGS_thread_num);
    for (int i = 0; i < FLAGS_thread_num; ++i) {
        MYSQL* conn = mysql_init(NULL);
        if (!mysql_real_connect(conn,
                                FLAGS_server.c_str(),
                                FLAGS_user.c_str(),
                                FLAGS_password.c_str(),
                                FLAGS_schema.c_str(),
                                FLAGS_port,
                                NULL,
                                0)) {
            LOG(ERROR) << mysql_error(conn);
            return -1;
        }
        args[i].base_index = i;
        args[i].mysql_conn = conn;
        if (!FLAGS_use_bthread) {
            if (pthread_create(&pids[i], NULL, sender, &args[i]) != 0) {
                LOG(ERROR) << "Fail to create pthread";
                return -1;
            }
        } else {
            if (bthread_start_background(&bids[i], NULL, sender, &args[i]) != 0) {
                LOG(ERROR) << "Fail to create bthread";
                return -1;
            }
        }
    }

    while (!brpc::IsAskedToQuit()) {
        sleep(1);

        LOG(INFO) << "Accessing mysql-server at qps=" << g_latency_recorder.qps(1)
                  << " latency=" << g_latency_recorder.latency(1);
    }

    LOG(INFO) << "mysql_client is going to quit";
    for (int i = 0; i < FLAGS_thread_num; ++i) {
        if (!FLAGS_use_bthread) {
            pthread_join(pids[i], NULL);
        } else {
            bthread_join(bids[i], NULL);
        }
    }

    return 0;
}

butil::Status MysqlStatementStub::PackExecuteCommand(butil::IOBuf* outbuf, uint32_t stmt_id) {
    butil::Status st;
    // long data
    for (const auto& i : _long_data) {
        st = MysqlMakeLongDataPacket(outbuf, stmt_id, i.param_id, i.long_data);
        if (!st.ok()) {
            LOG(ERROR) << "make long data header error " << st;
            return st;
        }
    }
    _long_data.clear();
    // execute data
    st = MysqlMakeExecutePacket(outbuf, stmt_id, _execute_data);
    if (!st.ok()) {
        LOG(ERROR) << "make execute header error " << st;
        return st;
    }
    _execute_data.clear();
    _null_mask.mask.clear();
    _null_mask.area = butil::IOBuf::INVALID_AREA;
    _param_types.types.clear();
    _param_types.area = butil::IOBuf::INVALID_AREA;

    return st;
}

MysqlRequest::MysqlRequest(const MysqlTransaction* tx)
    : NonreflectableMessage<MysqlRequest>() {
    SharedCtor();
    _tx = tx;
}

MysqlRequest::MysqlRequest(MysqlStatement* stmt)
    : NonreflectableMessage<MysqlRequest>() {
    SharedCtor();
    _stmt = new MysqlStatementStub(stmt);
}

MysqlRequest::MysqlRequest(const MysqlTransaction* tx, MysqlStatement* stmt)
    : NonreflectableMessage<MysqlRequest>() {
    SharedCtor();
    _tx = tx;
    _stmt = new MysqlStatementStub(stmt);
}

MysqlRequest::MysqlRequest(const MysqlRequest& from)
    : NonreflectableMessage<MysqlRequest>(from) {
    SharedCtor();
    MergeFrom(from);
}

void MysqlRequest::SharedCtor() {
    _has_error = false;
    _cached_size_ = 0;
    _has_command = false;
    _tx = NULL;
    _stmt = NULL;
    _param_index = 0;
}

MysqlRequest::~MysqlRequest() {
    SharedDtor();
    if (_stmt != NULL) {
        delete _stmt;
    }
    _stmt = NULL;
}

void MysqlRequest::Clear() {
    _has_error = false;
    _buf.clear();
    _has_command = false;
    _tx = NULL;
    if (_stmt) {
        delete _stmt;
        _stmt = NULL;
    }
    _param_index = 0;
}

size_t MysqlRequest::ByteSizeLong() const {
    int total_size = _buf.size();
    _cached_size_ = total_size;
    return total_size;
}

void MysqlRequest::MergeFrom(const MysqlRequest& from) {
    if (&from == this) {
        return;
    }
    _has_command = from._has_command;
    _has_error = from._has_error;
    _buf = from._buf;
    _cached_size_ = from._cached_size_;
    _param_index = from._param_index;
    // _tx is a non-owning pointer (never deleted by MysqlRequest): shallow copy.
    _tx = from._tx;
    // _stmt is owned (deleted in the dtor): deep-copy to avoid double free.
    if (_stmt != NULL) {
        delete _stmt;
        _stmt = NULL;
    }
    if (from._stmt != NULL) {
        _stmt = new MysqlStatementStub(*from._stmt);
    }
}

void MysqlRequest::Swap(MysqlRequest* other) {
    if (other != this) {
        _buf.swap(other->_buf);
        std::swap(_has_error, other->_has_error);
        std::swap(_cached_size_, other->_cached_size_);
        std::swap(_has_command, other->_has_command);
        std::swap(_tx, other->_tx);
        std::swap(_stmt, other->_stmt);
        std::swap(_param_index, other->_param_index);
    }
}

bool MysqlRequest::SerializeTo(butil::IOBuf* buf) const {
    if (_has_error) {
        LOG(ERROR) << "Reject serialization due to error in CommandXXX[V]";
        return false;
    }
    *buf = _buf;
    return true;
}

bool MysqlRequest::Query(const butil::StringPiece& command) {
    if (_has_error) {
        return false;
    }

    if (_has_command) {
        LOG(WARNING) << "MysqlRequest::Query: a command was already set on this request";
        return false;
    }

    const butil::Status st = MysqlMakeCommand(&_buf, MYSQL_COM_QUERY, command);
    if (st.ok()) {
        _has_command = true;
        return true;
    } else {
        CHECK(st.ok()) << st;
        _has_error = true;
        return false;
    }
}

bool MysqlRequest::AddParam(int8_t p) {
    if (_has_error) {
        return false;
    }
    if (_stmt == NULL || _stmt->stmt() == NULL) {
        LOG(WARNING) << "MysqlRequest::AddParam(int8_t): no prepared statement bound to request";
        _has_error = true;
        return false;
    }
    const butil::Status st = MysqlMakeExecuteData(_stmt, _param_index, &p, MYSQL_FIELD_TYPE_TINY);
    if (st.ok()) {
        ++_param_index;
        return true;
    } else {
        CHECK(st.ok()) << st;
        _has_error = true;
        return false;
    }
}

bool MysqlRequest::AddParam(uint8_t p) {
    if (_stmt == NULL || _stmt->stmt() == NULL) {
        LOG(WARNING) << "MysqlRequest::AddParam(uint8_t): no prepared statement bound to request";
        _has_error = true;
        return false;
    }
    const butil::Status st =
        MysqlMakeExecuteData(_stmt, _param_index, &p, MYSQL_FIELD_TYPE_TINY, true);
    if (st.ok()) {
        ++_param_index;
        return true;
    } else {
        CHECK(st.ok()) << st;
        _has_error = true;
        return false;
    }
}

