void MysqlRequest::Print(std::ostream& os) const {
    butil::IOBuf cp = _buf;
    {
        uint8_t buf[3];
        cp.cutn(buf, 3);
        os << "size:" << mysql_uint3korr(buf) << ",";
    }
    {
        uint8_t buf;
        cp.cut1((char*)&buf);
        os << "sequence:" << (unsigned)buf << ",";
    }
    os << "payload(hex):";
    while (!cp.empty()) {
        uint8_t buf;
        cp.cut1((char*)&buf);
        os << std::hex << (unsigned)buf;
    }
}

void MysqlResponse::Clear() {
    MysqlReply empty_reply;
    _first_reply.Swap(empty_reply);
    _other_replies.clear();
    _arena.clear();
    _nreply = 0;
    _cached_size_ = 0;
}

void MysqlResponse::Swap(MysqlResponse* other) {
    if (other != this) {
        _first_reply.Swap(other->_first_reply);
        std::swap(_other_replies, other->_other_replies);
        _arena.swap(other->_arena);
        std::swap(_nreply, other->_nreply);
        std::swap(_cached_size_, other->_cached_size_);
    }
}

ParseError MysqlResponse::ConsumePartialIOBuf(butil::IOBuf& buf,
                                              bool is_auth,
                                              MysqlStmtType stmt_type) {
    bool more_results = true;
    size_t oldsize = 0;
    while (more_results) {
        oldsize = buf.size();
        if (reply_size() == 0) {
            ParseError err =
                _first_reply.ConsumePartialIOBuf(buf, &_arena, is_auth, stmt_type, &more_results);
            if (err != PARSE_OK) {
                return err;
            }
        } else {
            const int32_t replies_size =
                FLAGS_mysql_multi_replies_size > 1 ? FLAGS_mysql_multi_replies_size : 10;
            if (_other_replies.size() < reply_size()) {
                MysqlReply* replies =
                    (MysqlReply*)_arena.allocate(sizeof(MysqlReply) * (replies_size - 1));
                if (replies == NULL) {
                    LOG(ERROR) << "Fail to allocate MysqlReply[" << replies_size - 1 << "]";
                    return PARSE_ERROR_ABSOLUTELY_WRONG;
                }
                _other_replies.reserve(replies_size - 1);
                for (int i = 0; i < replies_size - 1; ++i) {
                    new (&replies[i]) MysqlReply;
                    _other_replies.push_back(&replies[i]);
                }
            }
            ParseError err = _other_replies[_nreply - 1]->ConsumePartialIOBuf(
                buf, &_arena, is_auth, stmt_type, &more_results);
            if (err != PARSE_OK) {
                return err;
            }
        }

        const size_t newsize = buf.size();
        _cached_size_ += oldsize - newsize;
        oldsize = newsize;
        ++_nreply;
    }

    if (oldsize == 0) {
        return PARSE_OK;
    } else {
        LOG(ERROR) << "Parse protocol finished, but IOBuf has more data";
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
}

std::ostream& operator<<(std::ostream& os, const MysqlResponse& response) {
    os << "\n-----MYSQL REPLY BEGIN-----\n";
    if (response.reply_size() == 0) {
        os << "<empty response>";
    } else if (response.reply_size() == 1) {
        os << response.reply(0);
    } else {
        for (size_t i = 0; i < response.reply_size(); ++i) {
            os << "\nreply(" << i << ")----------";
            os << response.reply(i);
        }
    }
    os << "\n-----MYSQL REPLY END-----\n";

    return os;
}

bool MysqlHandleParams(const butil::StringPiece& params, std::string* param_cmd) {
    if (params.empty()) {
        return true;
    }
    const char* delim1 = "&";
    std::vector<size_t> idx;
    for (size_t p = params.find(delim1); p != butil::StringPiece::npos;
         p = params.find(delim1, p + 1)) {
        idx.push_back(p);
    }

    const char* delim2 = "=";
    std::stringstream ss;
    for (size_t i = 0; i < idx.size() + 1; ++i) {
        size_t pos = (i > 0) ? idx[i - 1] + 1 : 0;
        size_t len = (i < idx.size()) ? idx[i] - pos : params.size() - pos;
        butil::StringPiece raw(params.data() + pos, len);
        const size_t p = raw.find(delim2);
        if (p != butil::StringPiece::npos) {
            butil::StringPiece k(raw.data(), p);
            butil::StringPiece v(raw.data() + p + 1, raw.size() - p - 1);
            if (k == "charset") {
                ss << "SET NAMES " << v << ";";
            } else {
                ss << "SET " << k << "=" << v << ";";
            }
        }
    }
    *param_cmd = ss.str();
    return true;
}

bool MysqlAuthenticator::SerializeToString(std::string* str) const {
    std::stringstream ss;
    ss << _user << auth_param_delim;
    ss << _passwd << auth_param_delim;
    ss << _schema << auth_param_delim;
    ss << _collation << auth_param_delim;
    std::string param_cmd;
    if (MysqlHandleParams(_params, &param_cmd)) {
        ss << param_cmd;
    } else {
        LOG(ERROR) << "handle mysql authentication params failed, ignore it";
        return false;
    }
    *str = ss.str();
    return true;
}

void MysqlParseAuthenticator(const butil::StringPiece& raw,
                             std::string* user,
                             std::string* password,
                             std::string* schema,
                             std::string* collation) {
    std::vector<size_t> idx;
    idx.reserve(4);
    for (size_t p = raw.find(auth_param_delim); p != butil::StringPiece::npos;
         p = raw.find(auth_param_delim, p + 1)) {
        idx.push_back(p);
    }
    if (idx.size() < 4) {
        LOG(ERROR) << "malformed mysql authentication string, expected at least 4 '\\t' "
                      "delimiters but found " << idx.size();
        user->clear();
        password->clear();
        schema->clear();
        collation->clear();
        return;
    }
    user->assign(raw.data(), 0, idx[0]);
    password->assign(raw.data(), idx[0] + 1, idx[1] - idx[0] - 1);
    schema->assign(raw.data(), idx[1] + 1, idx[2] - idx[1] - 1);
    collation->assign(raw.data(), idx[2] + 1, idx[3] - idx[2] - 1);
}

int MysqlPackAuthenticator(const MysqlReply::Auth& auth,
                           const butil::StringPiece& user,
                           const butil::StringPiece& password,
                           const butil::StringPiece& schema,
                           const butil::StringPiece& collation,
                           std::string* auth_cmd) {
    const uint16_t capability =
        butil::ByteSwapToLE16((schema == "" ? 0x8285 : 0x828d) & auth.capability());
    const uint16_t extended_capability = butil::ByteSwapToLE16(0x000b & auth.extended_capability());
    butil::IOBuf salt;
    salt.append(auth.salt().data(), auth.salt().size());
    salt.append(auth.salt2().data(), auth.salt2().size());
    if (auth.auth_plugin() == mysql_native_password) {
        // Clean-room mysql_native_password scramble:
        //   SHA1(p) XOR SHA1( salt || SHA1(SHA1(p)) )
        // Produces the same 20 wire bytes as the original GPL helper, but is
        // derived from MySQL's public protocol docs.  Returns empty for a
        // blank password (the wire convention) and empty on a bad salt length.
        const std::string scramble =
            mysql::NativePasswordScramble(salt.to_string(), password);
        if (!password.empty() && scramble.empty()) {
            LOG(ERROR) << "failed to build mysql_native_password scramble, salt size="
                       << salt.size() << " (expected " << mysql::kSaltLen << ")";
            return 1;
        }
        salt.clear();
        salt.append(scramble);
    } else if (auth.auth_plugin() == caching_sha2_password) {
        // Clean-room caching_sha2_password fast-path scramble (32 bytes):
        //   SHA256(p) XOR SHA256( SHA256( SHA256(p) ) || salt )
        // The server replies with an AuthMoreData status byte after this;
        // mysql_protocol.cpp's HandleAuthentication drives the follow-up
        // (fast-auth-success / full-auth RSA exchange).  Returns empty for a
        // blank password (the wire convention) and empty on a bad salt length.
        const std::string scramble =
            mysql::CachingSha2PasswordScramble(salt.to_string(), password);
        if (!password.empty() && scramble.empty()) {
            LOG(ERROR) << "failed to build caching_sha2_password scramble, salt size="
                       << salt.size() << " (expected " << mysql::kSaltLen << ")";
            return 1;
        }
        salt.clear();
        salt.append(scramble);
    } else {
        LOG(ERROR) << "no support auth plugin [" << auth.auth_plugin() << "]";
        return 1;
    }

    butil::IOBuf payload;
    payload.append(&capability, 2);
    payload.append(&extended_capability, 2);
    payload.push_back(0x00);
    payload.push_back(0x00);
    payload.push_back(0x00);
    payload.push_back(0x00);
    auto iter = MysqlCollations.find(std::string(collation.data(), collation.size()));
    if (iter == MysqlCollations.end()) {
        LOG(ERROR) << "wrong collation [" << collation << "]";
        return 1;
    }
    payload.append(&iter->second, 1);
    const std::string stuff(23, '\0');
    payload.append(stuff);
    payload.append(user.data(), user.size());
    payload.push_back('\0');
    payload.append(pack_encode_length(salt.size()));
    payload.append(salt);
    if (schema != "") {
        payload.append(schema.data(), schema.size());
        payload.push_back('\0');
    }
    if (auth.auth_plugin() == mysql_native_password) {
        payload.append(mysql_native_password.data(), mysql_native_password.size());
        payload.push_back('\0');
    } else if (auth.auth_plugin() == caching_sha2_password) {
        payload.append(caching_sha2_password.data(), caching_sha2_password.size());
        payload.push_back('\0');
    }
    butil::IOBuf message;
    const uint32_t payload_size = butil::ByteSwapToLE32(payload.size());
    // header
    message.append(&payload_size, 3);
    message.push_back(0x01);
    // payload
    message.append(payload);
    *auth_cmd = message.to_string();
    return 0;
}

int MysqlPackParams(const butil::StringPiece& params, std::string* param_cmd) {
    if (!params.empty()) {
        butil::IOBuf buf;
        MysqlMakeCommand(&buf, MYSQL_COM_QUERY, params);
        buf.copy_to(param_cmd);
        return 0;
    }
    LOG(ERROR) << "empty connection params";
    return 1;
}

butil::Status MakePacket(butil::IOBuf* outbuf, const H& head, const F& func, const D& data) {
    int64_t pkg_len = (int64_t)head.size() + (int64_t)data.size();
    if (pkg_len > max_allowed_packet) {
        return butil::Status(
            EINVAL,
            "[MakePacket] statement size is too big, maxAllowedPacket = %d, pkg_len = %lld",
            max_allowed_packet,
            (long long)pkg_len);
    }
    uint32_t size, header;
    uint8_t seq = 0;
    size_t offset = 0;
    // When the payload length is an exact multiple of max_packet_size, the
    // MySQL multi-packet protocol requires a trailing 0-length packet to mark
    // the end. Loop while pkg_len > 0, plus one extra pass emitting an empty
    // packet when the previous chunk exactly filled max_packet_size.
    bool need_trailing = false;
    for (; pkg_len > 0 || need_trailing; pkg_len -= max_packet_size, ++seq) {
        if (pkg_len > max_packet_size) {
            size = max_packet_size;
        } else {
            size = pkg_len;
        }
        need_trailing = (size == max_packet_size);
        header = butil::ByteSwapToLE32(size);
        ((uint8_t*)&header)[3] = seq;
        outbuf->append(&header, 4);
        if (seq == 0) {
            const uint32_t old_size = outbuf->size();
            outbuf->append(head);
            size -= outbuf->size() - old_size;
        }
        func(outbuf, data, size, offset);
        offset += size;
    }

    return butil::Status::OK();
}

butil::Status MysqlMakeCommand(butil::IOBuf* outbuf,
                               const MysqlCommandType type,
                               const butil::StringPiece& command) {
    if (outbuf == NULL || command.size() == 0) {
        return butil::Status(EINVAL, "[MysqlMakeCommand] Param[outbuf] or [stmt] is NULL");
    }
    auto func =
        [](butil::IOBuf* outbuf, const butil::StringPiece& command, size_t size, size_t offset) {
            outbuf->append(command.data() + offset, size);
        };
    butil::IOBuf head;
    head.push_back(type);
    return MakePacket(outbuf, head, func, command);
}

butil::Status MysqlMakeExecutePacket(butil::IOBuf* outbuf,
                                     uint32_t stmt_id,
                                     const butil::IOBuf& edata) {
    butil::IOBuf head;  // cmd_type + stmt_id + flag + reserved + body_size
    head.push_back(MYSQL_COM_STMT_EXECUTE);
    const uint32_t si = butil::ByteSwapToLE32(stmt_id);
    head.append(&si, 4);
    head.push_back('\0');
    head.push_back((char)0x01);
    head.push_back('\0');
    head.push_back('\0');
    head.push_back('\0');
    auto func = [](butil::IOBuf* outbuf, const butil::IOBuf& data, size_t size, size_t offset) {
        data.append_to(outbuf, size, offset);
    };
    return MakePacket(outbuf, head, func, edata);
}

butil::Status MysqlMakeExecuteData(MysqlStatementStub* stmt,
                                   uint16_t index,
                                   const void* value,
                                   MysqlFieldType type,
                                   bool is_unsigned) {
    const uint16_t n = stmt->stmt()->param_count();
    uint32_t long_data_size = max_allowed_packet / (n + 1);
    if (long_data_size < 64) {
        long_data_size = 64;
    }
    // if param count is zero finished.
    if (n == 0) {
        return butil::Status::OK();
    }
    butil::IOBuf& buf = stmt->execute_data();
    MysqlStatementStub::NullMask& null_mask = stmt->null_mask();
    MysqlStatementStub::ParamTypes& param_types = stmt->param_types();
    // else param number larger than zero.
    if (index >= n) {
        LOG(ERROR) << "too many params";
        return butil::Status(EINVAL, "[MysqlMakeExecuteData] too many params");
    }
    // reserve null mask and param types packing at first param
    if (index == 0) {
        const size_t mask_len = (n + 7) / 8;
        const size_t types_len = 2 * n;
        null_mask.mask.resize(mask_len, 0);
        null_mask.area = buf.reserve(mask_len);
        buf.push_back((char)0x01);
        param_types.types.resize(types_len, 0);
        param_types.area = buf.reserve(types_len);
    }
    // pack param value
    switch (type) {
        case MYSQL_FIELD_TYPE_TINY:
            if (is_unsigned) {
                param_types.types[index + index] = MYSQL_FIELD_TYPE_TINY;
                param_types.types[index + index + 1] = 0x80;
            } else {
                param_types.types[index + index] = MYSQL_FIELD_TYPE_TINY;
                param_types.types[index + index + 1] = 0x00;
            }
            buf.append(value, 1);
            break;
        case MYSQL_FIELD_TYPE_SHORT:
            if (is_unsigned) {
                param_types.types[index + index] = MYSQL_FIELD_TYPE_SHORT;
                param_types.types[index + index + 1] = 0x80;
            } else {
                param_types.types[index + index] = MYSQL_FIELD_TYPE_SHORT;
                param_types.types[index + index + 1] = 0x00;
            }
            {
                uint16_t v = butil::ByteSwapToLE16(*(uint16_t*)value);
                buf.append(&v, 2);
            }
            break;
        case MYSQL_FIELD_TYPE_LONG:
            if (is_unsigned) {
                param_types.types[index + index] = MYSQL_FIELD_TYPE_LONG;
                param_types.types[index + index + 1] = 0x80;

            } else {
                param_types.types[index + index] = MYSQL_FIELD_TYPE_LONG;
                param_types.types[index + index + 1] = 0x00;
            }
            {
                uint32_t v = butil::ByteSwapToLE32(*(uint32_t*)value);
                buf.append(&v, 4);
            }
            break;
        case MYSQL_FIELD_TYPE_LONGLONG:
            if (is_unsigned) {
                param_types.types[index + index] = MYSQL_FIELD_TYPE_LONGLONG;
                param_types.types[index + index + 1] = 0x80;
            } else {
                param_types.types[index + index] = MYSQL_FIELD_TYPE_LONGLONG;
                param_types.types[index + index + 1] = 0x00;
            }
            {
                uint64_t v = butil::ByteSwapToLE64(*(uint64_t*)value);
                buf.append(&v, 8);
            }
            break;
        case MYSQL_FIELD_TYPE_FLOAT:
            param_types.types[index + index] = MYSQL_FIELD_TYPE_FLOAT;
            param_types.types[index + index + 1] = 0x00;
            buf.append(value, 4);
            break;
        case MYSQL_FIELD_TYPE_DOUBLE:
            param_types.types[index + index] = MYSQL_FIELD_TYPE_DOUBLE;
            param_types.types[index + index + 1] = 0x00;
            buf.append(value, 8);
            break;
        case MYSQL_FIELD_TYPE_STRING: {
            const butil::StringPiece* p = (butil::StringPiece*)value;
            if (p == NULL || p->data() == NULL) {
                param_types.types[index + index] = MYSQL_FIELD_TYPE_NULL;
                param_types.types[index + index + 1] = 0x00;
                null_mask.mask[index / 8] |= 1 << (index & 7);
            } else {
                param_types.types[index + index] = MYSQL_FIELD_TYPE_STRING;
                param_types.types[index + index + 1] = 0x00;
                if (p->size() < long_data_size) {
                    std::string len = pack_encode_length(p->size());
                    buf.append(len);
                    buf.append(p->data(), p->size());
                } else {
                    stmt->save_long_data(index, *p);
                }
            }
        } break;
        case MYSQL_FIELD_TYPE_NULL: {
            param_types.types[index + index] = MYSQL_FIELD_TYPE_NULL;
            param_types.types[index + index + 1] = 0x00;
            null_mask.mask[index / 8] |= 1 << (index & 7);
        } break;
        default:
            LOG(ERROR) << "wrong param type";
            return butil::Status(EINVAL, "[MysqlMakeExecuteData] wrong param type");
    }

    // all args have been building
    if (index + 1 == n) {
        buf.unsafe_assign(null_mask.area, null_mask.mask.data());
        buf.unsafe_assign(param_types.area, param_types.types.data());
    }

    return butil::Status::OK();
}

butil::Status MysqlMakeLongDataPacket(butil::IOBuf* outbuf,
                                      uint32_t stmt_id,
                                      uint16_t param_id,
                                      const butil::IOBuf& ldata) {
    butil::IOBuf head;
    head.push_back(MYSQL_COM_STMT_SEND_LONG_DATA);
    const uint32_t si = butil::ByteSwapToLE32(stmt_id);
    head.append(&si, 4);
    const uint16_t pi = butil::ByteSwapToLE16(param_id);
    head.append(&pi, 2);
    // Cap each chunk so that head.size() + len never exceeds max_allowed_packet,
    // otherwise MakePacket rejects (EINVAL) an exact-limit-multiple payload.
    const size_t max_chunk = max_allowed_packet - head.size();
    size_t len, pos = 0;
    for (size_t pkg_len = ldata.size(); pkg_len > 0; pkg_len -= len) {
        if (pkg_len < max_chunk) {
            len = pkg_len;
        } else {
            len = max_chunk;
        }
        butil::IOBuf data;
        ldata.append_to(&data, len, pos);
        pos += len;
        auto func = [](butil::IOBuf* outbuf, const butil::IOBuf& data, size_t size, size_t offset) {
            data.append_to(outbuf, size, offset);
        };
        auto rc = MakePacket(outbuf, head, func, data);
        if (!rc.ok()) {
            return rc;
        }
    }
    return butil::Status::OK();
}

