static void WriteMysqlAuthPacket(int fd, const std::string& payload, uint8_t seq) {
    butil::IOBuf buf;
    const uint32_t len = butil::ByteSwapToLE32((uint32_t)payload.size());
    buf.append(&len, 3);
    buf.push_back((char)seq);
    buf.append(payload);
    buf.cut_into_file_descriptor(fd);
}

bool PackRequest(butil::IOBuf* buf,
                 ControllerPrivateAccessor& accessor,
                 const butil::IOBuf& request) {
    if (accessor.pipelined_count() == MYSQL_PREPARED_STATEMENT) {
        Socket* sock = accessor.get_sending_socket();
        if (sock == NULL) {
            LOG(ERROR) << "[MYSQL PACK] get sending socket with NULL";
            return false;
        }
        auto stub = static_cast<MysqlStatementStub*>(accessor.session_data());
        if (stub == NULL) {
            LOG(ERROR) << "[MYSQL PACK] get prepare statement with NULL";
            return false;
        }
        uint32_t stmt_id;
        // if can't found stmt_id in this socket, create prepared statement on it, store user
        // request.
        if ((stmt_id = stub->stmt()->StatementId(sock->id())) == 0) {
            butil::IOBuf b;
            butil::Status st = MysqlMakeCommand(&b, MYSQL_COM_STMT_PREPARE, stub->stmt()->str());
            if (!st.ok()) {
                LOG(ERROR) << "[MYSQL PACK] make prepare statement error " << st;
                return false;
            }
            accessor.set_mysql_statement_type(MYSQL_NEED_PREPARE);
            buf->append(b);
            return true;
        }
        // else pack execute header with stmt_id
        butil::Status st = stub->PackExecuteCommand(buf, stmt_id);
        if (!st.ok()) {
            LOG(ERROR) << "write execute data error " << st;
            return false;
        }
        return true;
    }
    buf->append(request);
    return true;
}

ParseError HandleAuthentication(const InputResponse* msg, const Socket* socket, PipelinedInfo* pi) {
    const bthread_id_t cid = pi->id_wait;
    Controller* cntl = NULL;
    if (bthread_id_lock(cid, (void**)&cntl) != 0) {
        LOG(ERROR) << "[MYSQL PARSE] fail to lock controller";
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }

    ParseError parseCode = PARSE_OK;
    const AuthContext* ctx = socket->auth_context();
    if (ctx == NULL) {
        parseCode = PARSE_ERROR_ABSOLUTELY_WRONG;
        LOG(ERROR) << "[MYSQL PARSE] auth context is null";
        goto END_OF_AUTH;
    }
    if (msg->response.reply(0).is_auth()) {
        std::string user, password, schema, collation, auth_cmd;
        const MysqlReply& reply = msg->response.reply(0);
        MysqlParseAuthenticator(ctx->user(), &user, &password, &schema, &collation);
        if (MysqlPackAuthenticator(reply.auth(), user, password, schema, collation, &auth_cmd) ==
            0) {
            butil::IOBuf buf;
            buf.append(auth_cmd);
            const ssize_t nw = buf.cut_into_file_descriptor(socket->fd());
            if (nw < 0 || !buf.empty()) {
                LOG(WARNING) << "[MYSQL PARSE] failed to write auth command to fd="
                             << socket->fd() << ", nw=" << nw
                             << ", remaining=" << buf.size();
            }
            const bool is_caching_sha2 = (reply.auth().auth_plugin() == "caching_sha2_password");
            if (is_caching_sha2) {
                // caching_sha2_password is a multi-round-trip exchange: stash
                // the 20-byte salt (greeting salt + salt2) for a later RSA
                // full-auth round, and mark that the fast scramble was sent.
                // _roles is otherwise unused on the mysql path.
                std::string salt;
                salt.append(reply.auth().salt().data(), reply.auth().salt().size());
                salt.append(reply.auth().salt2().data(), reply.auth().salt2().size());
                const_cast<AuthContext*>(ctx)->set_roles(salt);
                const_cast<AuthContext*>(ctx)->set_group(kCacheSha2Sent);
            } else {
                const_cast<AuthContext*>(ctx)->set_group(auth_step[0]);
            }
        } else {
            parseCode = PARSE_ERROR_ABSOLUTELY_WRONG;
            LOG(ERROR) << "[MYSQL PARSE] wrong pack authentication data";
        }
    } else if (msg->response.reply(0).is_auth_more_data()) {
        // caching_sha2_password follow-up packet (server -> client).  The
        // first data byte after the 0x01 tag is a status marker, except when
        // we are awaiting the RSA public key (CACHE_SHA2_PUBKEY), in which
        // case the whole payload is the PEM public key.
        std::string user, password, schema, collation;
        MysqlParseAuthenticator(ctx->user(), &user, &password, &schema, &collation);
        const MysqlReply::AuthMoreData& amd = msg->response.reply(0).auth_more_data();
        const butil::StringPiece data = amd.data();
        const uint8_t next_seq = (uint8_t)(amd.seq() + 1);
        if (ctx->group() == kCacheSha2Pubkey) {
            // The payload is the server's PEM RSA public key.  Encrypt the
            // password with it (plain-TCP full-auth) and send the ciphertext.
            const std::string rsa = mysql::CachingSha2PasswordRsaEncrypt(
                data, ctx->roles(), password);
            if (rsa.empty()) {
                parseCode = PARSE_ERROR_ABSOLUTELY_WRONG;
                LOG(ERROR) << "[MYSQL PARSE] failed to RSA-encrypt caching_sha2 password";
                goto END_OF_AUTH;
            }
            WriteMysqlAuthPacket(socket->fd(), rsa, next_seq);
            // Stay in CACHE_SHA2_SENT-equivalent: the server replies OK next.
            const_cast<AuthContext*>(ctx)->set_group(kCacheSha2Sent);
        } else if (!data.empty() && (uint8_t)data[0] == 0x03) {
            // fast_auth_success: server will send OK next; send nothing.
            const_cast<AuthContext*>(ctx)->set_group(kCacheSha2Sent);
        } else if (!data.empty() && (uint8_t)data[0] == 0x04) {
            // perform_full_authentication.
            if (socket->is_ssl()) {
                // Secure channel: send the cleartext password (one round trip).
                const std::string clear = mysql::CachingSha2PasswordCleartext(password);
                WriteMysqlAuthPacket(socket->fd(), clear, next_seq);
                const_cast<AuthContext*>(ctx)->set_group(kCacheSha2Sent);
            } else {
                // Plain TCP: request the server's RSA public key (0x02), then
                // wait for the AuthMoreData carrying the PEM.
                WriteMysqlAuthPacket(socket->fd(), std::string(1, (char)0x02), next_seq);
                const_cast<AuthContext*>(ctx)->set_group(kCacheSha2Pubkey);
            }
        } else {
            parseCode = PARSE_ERROR_ABSOLUTELY_WRONG;
            LOG(ERROR) << "[MYSQL PARSE] unexpected caching_sha2 AuthMoreData marker";
        }
    } else if (msg->response.reply_size() > 0) {
        for (size_t i = 0; i < msg->response.reply_size(); ++i) {
            if (!msg->response.reply(i).is_ok()) {
                LOG(ERROR) << "[MYSQL PARSE] auth failed " << msg->response;
                parseCode = PARSE_ERROR_NO_RESOURCE;
                goto END_OF_AUTH;
            }
        }
        std::string params, params_cmd;
        MysqlParseParams(ctx->user(), &params);
        // Auth just completed (either native's single round trip, group
        // AUTH_OK, or caching_sha2's multi round-trip, group CACHE_SHA2_SENT)
        // and connection params have not been sent yet: send them now.
        const bool auth_just_done =
            (ctx->group() == auth_step[0] || ctx->group() == kCacheSha2Sent);
        if (auth_just_done && !params.empty()) {
            if (MysqlPackParams(params, &params_cmd) == 0) {
                butil::IOBuf buf;
                buf.append(params_cmd);
                buf.cut_into_file_descriptor(socket->fd());
                const_cast<AuthContext*>(ctx)->set_group(auth_step[1]);
            } else {
                parseCode = PARSE_ERROR_ABSOLUTELY_WRONG;
                LOG(ERROR) << "[MYSQL PARSE] wrong pack params data";
            }
        } else {
            butil::IOBuf raw_req;
            raw_req.append(ctx->starter());
            raw_req.cut_into_file_descriptor(socket->fd());
            pi->auth_flags = 0;
        }
    } else {
        parseCode = PARSE_ERROR_ABSOLUTELY_WRONG;
        LOG(ERROR) << "[MYSQL PARSE] wrong authentication step";
    }

END_OF_AUTH:
    if (bthread_id_unlock(cid) != 0) {
        parseCode = PARSE_ERROR_ABSOLUTELY_WRONG;
        LOG(ERROR) << "[MYSQL PARSE] fail to unlock controller";
    }
    return parseCode;
}

ParseError HandlePrepareStatement(const InputResponse* msg,
                                  const Socket* socket,
                                  PipelinedInfo* pi) {
    if (!msg->response.reply(0).is_prepare_ok()) {
        LOG(ERROR) << "[MYSQL PARSE] response is not prepare ok, " << msg->response;
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    const MysqlReply::PrepareOk& ok = msg->response.reply(0).prepare_ok();
    const bthread_id_t cid = pi->id_wait;
    Controller* cntl = NULL;
    if (bthread_id_lock(cid, (void**)&cntl) != 0) {
        LOG(ERROR) << "[MYSQL PARSE] fail to lock controller";
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    ParseError parseCode = PARSE_OK;
    butil::IOBuf buf;
    butil::Status st;
    MysqlStatementStub* stub = NULL;
    MysqlStatement* stmt = NULL;
    stub = static_cast<MysqlStatementStub*>(ControllerPrivateAccessor(cntl).session_data());
    if (stub == NULL) {
        LOG(ERROR) << "[MYSQL PACK] get prepare statement with NULL";
        parseCode = PARSE_ERROR_ABSOLUTELY_WRONG;
        goto END_OF_PREPARE;
    }
    stmt = stub->stmt();
    if (stmt == NULL || stmt->param_count() != ok.param_count()) {
        LOG(ERROR) << "[MYSQL PACK] stmt can't be NULL";
        parseCode = PARSE_ERROR_ABSOLUTELY_WRONG;
        goto END_OF_PREPARE;
    }
    if (stmt->param_count() != ok.param_count()) {
        LOG(ERROR) << "[MYSQL PACK] stmt param number " << stmt->param_count()
                   << " not equal to prepareOk.param_number " << ok.param_count();
        parseCode = PARSE_ERROR_ABSOLUTELY_WRONG;
        goto END_OF_PREPARE;
    }
    stmt->SetStatementId(socket->id(), ok.stmt_id());
    st = stub->PackExecuteCommand(&buf, ok.stmt_id());
    if (!st.ok()) {
        LOG(ERROR) << "[MYSQL PACK] make execute header error " << st;
        parseCode = PARSE_ERROR_ABSOLUTELY_WRONG;
        goto END_OF_PREPARE;
    }
    {
        const ssize_t nw = buf.cut_into_file_descriptor(socket->fd());
        if (nw < 0 || !buf.empty()) {
            LOG(WARNING) << "[MYSQL PARSE] failed to write execute command to fd="
                         << socket->fd() << ", nw=" << nw
                         << ", remaining=" << buf.size();
        }
    }
    pi->count = MYSQL_PREPARED_STATEMENT;
END_OF_PREPARE:
    if (bthread_id_unlock(cid) != 0) {
        parseCode = PARSE_ERROR_ABSOLUTELY_WRONG;
        LOG(ERROR) << "[MYSQL PARSE] fail to unlock controller";
    }
    return parseCode;
}

ParseResult ParseMysqlMessage(butil::IOBuf* source,
                              Socket* socket,
                              bool /*read_eof*/,
                              const void* /*arg*/) {
    if (source->empty()) {
        return MakeParseError(PARSE_ERROR_NOT_ENOUGH_DATA);
    }

    PipelinedInfo pi;
    if (!socket->PopPipelinedInfo(&pi)) {
        LOG(WARNING) << "No corresponding PipelinedInfo in socket";
        return MakeParseError(PARSE_ERROR_TRY_OTHERS);
    }

    InputResponse* msg = static_cast<InputResponse*>(socket->parsing_context());
    if (msg == NULL) {
        msg = new InputResponse;
        socket->reset_parsing_context(msg);
    }

    MysqlStmtType stmt_type = static_cast<MysqlStmtType>(pi.count);
    ParseError err = msg->response.ConsumePartialIOBuf(*source, pi.auth_flags != 0, stmt_type);
    if (FLAGS_mysql_verbose) {
        LOG(INFO) << "[MYSQL PARSE] " << msg->response;
    }
    if (err != PARSE_OK) {
        if (err == PARSE_ERROR_NOT_ENOUGH_DATA) {
            socket->GivebackPipelinedInfo(pi);
        }
        return MakeParseError(err);
    }
    if (pi.auth_flags) {
        ParseError err = HandleAuthentication(msg, socket, &pi);
        if (err != PARSE_OK) {
            return MakeParseError(err, "Fail to authenticate with Mysql");
        }
        DestroyingPtr<InputResponse> auth_msg =
            static_cast<InputResponse*>(socket->release_parsing_context());
        socket->GivebackPipelinedInfo(pi);
        return MakeParseError(PARSE_ERROR_NOT_ENOUGH_DATA);
    }
    if (stmt_type == MYSQL_NEED_PREPARE) {
        // A failed PREPARE (e.g. ER_PARSE_ERROR 1064) comes back as a normal
        // ERR packet. Deliver it to the caller like any other error response
        // and keep the connection open -- matching the command path and other
        // protocols (redis, baidu_std). Only a successful prepare proceeds to
        // pack and send the COM_STMT_EXECUTE.
        if (!msg->response.reply(0).is_prepare_ok()) {
            msg->id_wait = pi.id_wait;
            socket->release_parsing_context();
            return MakeMessage(msg);
        }
        // store stmt_id, make execute header.
        ParseError err = HandlePrepareStatement(msg, socket, &pi);
        if (err != PARSE_OK) {
            return MakeParseError(err, "Fail to make parepared statement with Mysql");
        }
        DestroyingPtr<InputResponse> prepare_msg =
            static_cast<InputResponse*>(socket->release_parsing_context());
        socket->GivebackPipelinedInfo(pi);
        return MakeParseError(PARSE_ERROR_NOT_ENOUGH_DATA);
    }
    msg->id_wait = pi.id_wait;
    socket->release_parsing_context();
    return MakeMessage(msg);
}

void ProcessMysqlResponse(InputMessageBase* msg_base) {
    const int64_t start_parse_us = butil::cpuwide_time_us();
    DestroyingPtr<InputResponse> msg(static_cast<InputResponse*>(msg_base));

    const bthread_id_t cid = msg->id_wait;
    Controller* cntl = NULL;
    const int rc = bthread_id_lock(cid, (void**)&cntl);
    if (rc != 0) {
        LOG_IF(ERROR, rc != EINVAL && rc != EPERM)
            << "Fail to lock correlation_id=" << cid << ": " << berror(rc);
        return;
    }

    ControllerPrivateAccessor accessor(cntl);
    // Controller::span() returns a std::shared_ptr<Span> in current master
    // (was a raw Span* when #2093 was written).
    if (auto span = accessor.span()) {
        span->set_base_real_us(msg->base_real_us());
        span->set_received_us(msg->received_us());
        span->set_response_size(msg->response.ByteSize());
        span->set_start_parse_us(start_parse_us);
    }
    const int saved_error = cntl->ErrorCode();
    if (cntl->response() != NULL) {
        if (cntl->response()->GetDescriptor() != MysqlResponse::descriptor()) {
            LOG(ERROR) << "[MYSQL PROCESS] response message is not a MysqlResponse";
            cntl->SetFailed(ERESPONSE, "Must be MysqlResponse");
        } else {
            // We work around ParseFrom of pb which is just a placeholder.
            ((MysqlResponse*)cntl->response())->Swap(&msg->response);
        }
    }  // silently ignore the response.

    // Unlocks correlation_id inside. Revert controller's
    // error code if it version check of `cid' fails
    msg.reset();  // optional, just release resourse ASAP
    accessor.OnResponse(cid, saved_error);
}

void SerializeMysqlRequest(butil::IOBuf* buf,
                           Controller* cntl,
                           const google::protobuf::Message* request) {
    if (request == NULL) {
        LOG(ERROR) << "[MYSQL SERIALIZE] request is NULL";
        return cntl->SetFailed(EREQUEST, "request is NULL");
    }
    if (request->GetDescriptor() != MysqlRequest::descriptor()) {
        LOG(ERROR) << "[MYSQL SERIALIZE] request message is not a MysqlRequest";
        return cntl->SetFailed(EREQUEST, "The request is not a MysqlRequest");
    }
    const MysqlRequest* rr = (const MysqlRequest*)request;
    // We work around SerializeTo of pb which is just a placeholder.
    if (!rr->SerializeTo(buf)) {
        LOG(ERROR) << "[MYSQL SERIALIZE] failed to serialize MysqlRequest to IOBuf";
        return cntl->SetFailed(EREQUEST, "Fail to serialize MysqlRequest");
    }
    // mysql doesn't use pipelined_count to verify the end of a response; instead we
    // reuse it as a MysqlStmtType tag so the parse function knows which reply shape
    // to expect (OK and PrepareOk are otherwise indistinguishable). Default to
    // MYSQL_NORMAL_STATEMENT (1); it is upgraded to MYSQL_PREPARED_STATEMENT (2)
    // below when the request carries a prepared statement.
    ControllerPrivateAccessor accessor(cntl);
    accessor.set_mysql_statement_type(MYSQL_NORMAL_STATEMENT);

    auto tx = rr->tx();
    if (tx != NULL) {
        accessor.use_bind_sock(tx->GetSocketId());
    }
    auto st = rr->stmt();
    if (st != NULL) {
        accessor.set_session_data(rr->stmt());
        accessor.set_mysql_statement_type(MYSQL_PREPARED_STATEMENT);
    }
    if (FLAGS_mysql_verbose) {
        LOG(INFO) << "\n[MYSQL REQUEST] " << *rr;
    }
}

void PackMysqlRequest(butil::IOBuf* buf,
                      SocketMessage**,
                      uint64_t /*correlation_id*/,
                      const google::protobuf::MethodDescriptor*,
                      Controller* cntl,
                      const butil::IOBuf& request,
                      const Authenticator* auth) {
    ControllerPrivateAccessor accessor(cntl);
    if (auth) {
        const MysqlAuthenticator* my_auth(dynamic_cast<const MysqlAuthenticator*>(auth));
        if (my_auth == NULL) {
            LOG(ERROR) << "[MYSQL PACK] there is not MysqlAuthenticator";
            return;
        }
        Socket* sock = accessor.get_sending_socket();
        if (sock == NULL) {
            LOG(ERROR) << "[MYSQL PACK] get sending socket with NULL";
            return;
        }
        AuthContext* ctx = sock->mutable_auth_context();
        std::string str;
        if (!my_auth->SerializeToString(&str)) {
            LOG(ERROR) << "[MYSQL PACK] auth param serialize to string failed";
            return;
        }
        ctx->set_user(str);
        butil::IOBuf b;
        if (!PackRequest(&b, accessor, request)) {
            LOG(ERROR) << "[MYSQL PACK] pack request error";
            return;
        }
        ctx->set_starter(b.to_string());
        // Mark this as an auth write so the connection-phase handshake is run
        // and the (empty) data buffer is allowed through Socket::Write.  Mirrors
        // redis's set_auth_flags(); 1 == "this pipelined slot is the auth reply".
        accessor.set_auth_flags(1);
    } else {
        if (!PackRequest(buf, accessor, request)) {
            LOG(ERROR) << "[MYSQL PACK] pack request error";
            return;
        }
    }
}

const std::string& GetMysqlMethodName(const google::protobuf::MethodDescriptor*,
                                      const Controller*) {
    const static std::string MYSQL_SERVER_STR = "mysql-server";
    return MYSQL_SERVER_STR;
}

inline bool my_alloc_check(butil::Arena* arena, const size_t n, Type*& pointer) {
    if (pointer == NULL) {
        pointer = (Type*)arena->allocate(sizeof(Type) * n);
        if (pointer == NULL) {
            LOG(ERROR) << "my_alloc_check: arena failed to allocate " << (sizeof(Type) * n)
                       << " bytes (n=" << n << ")";
            return false;
        }
        for (size_t i = 0; i < n; ++i) {
            new (pointer + i) Type;
        }
    }
    return true;
}

inline bool my_alloc_check(butil::Arena* arena, const size_t n, char*& pointer) {
    if (pointer == NULL) {
        pointer = (char*)arena->allocate(sizeof(char) * n);
        if (pointer == NULL) {
            LOG(ERROR) << "my_alloc_check: arena failed to allocate " << n << " char bytes";
            return false;
        }
    }
    return true;
}

inline void write_zero_microsecs(uint8_t decimal, char* d) {
    if (decimal == 0 || decimal == 0x1f) {
        return;
    }
    uint8_t n = decimal > 6 ? 6 : decimal;
    size_t i = 0;
    d[i++] = '.';
    for (uint8_t k = 0; k < n; ++k) {
        d[i++] = '0';
    }
}

const char* MysqlRspTypeToString(MysqlRspType type) {
    switch (type) {
        case MYSQL_RSP_OK:
            return "ok";
        case MYSQL_RSP_ERROR:
            return "error";
        case MYSQL_RSP_RESULTSET:
            return "resultset";
        case MYSQL_RSP_EOF:
            return "eof";
        case MYSQL_RSP_AUTH:
            return "auth";
        case MYSQL_RSP_AUTH_MORE_DATA:
            return "auth_more_data";
        case MYSQL_RSP_PREPARE_OK:
            return "prepare_ok";
        default:
            return "Unknown Response Type";
    }
}

inline bool is_full_package(const butil::IOBuf& buf) {
    uint8_t header[4];
    const uint8_t* p = (const uint8_t*)buf.fetch(header, sizeof(header));
    if (p == NULL) {
        return false;
    }
    uint32_t payload_size = mysql_uint3korr(p);
    if (buf.size() < payload_size + 4) {
        return false;
    }
    return true;
}

inline bool is_an_eof(const butil::IOBuf& buf) {
    uint8_t tmp[5];
    const uint8_t* p = (const uint8_t*)buf.fetch(tmp, sizeof(tmp));
    if (p == NULL) {
        return false;
    }
    uint8_t type = p[4];
    if (type == MYSQL_RSP_EOF) {
        return true;
    } else {
        return false;
    }
}

inline bool parse_header(butil::IOBuf& buf, MysqlHeader* value) {
    if (!is_full_package(buf)) {
        return false;
    }
    {
        uint8_t tmp[3];
        buf.cutn(tmp, sizeof(tmp));
        value->payload_size = mysql_uint3korr(tmp);
    }
    {
        uint8_t tmp;
        buf.cut1((char*)&tmp);
        value->seq = tmp;
    }
    return true;
}

inline uint64_t parse_encode_length(butil::IOBuf& buf) {
    if (buf.size() == 0) {
        return 0;
    }

    uint64_t value = 0;
    uint8_t f = 0;
    buf.cut1((char*)&f);
    if (f <= 250) {
        value = f;
    } else if (f == 251) {
        value = 0;
    } else if (f == 252) {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        value = mysql_uint2korr(tmp);
    } else if (f == 253) {
        uint8_t tmp[3];
        buf.cutn(tmp, sizeof(tmp));
        value = mysql_uint3korr(tmp);
    } else if (f == 254) {
        uint8_t tmp[8];
        buf.cutn(tmp, sizeof(tmp));
        value = mysql_uint8korr(tmp);
    }
    return value;
}

ParseError MysqlReply::ConsumePartialIOBuf(butil::IOBuf& buf,
                                           butil::Arena* arena,
                                           bool is_auth,
                                           MysqlStmtType stmt_type,
                                           bool* more_results) {
    *more_results = false;
    if (!is_full_package(buf)) {
        return PARSE_ERROR_NOT_ENOUGH_DATA;
    }
    uint8_t header[4 + 1];  // use the extra byte to judge message type
    const uint8_t* p = (const uint8_t*)buf.fetch(header, sizeof(header));
    uint8_t type = (_type == MYSQL_RSP_UNKNOWN) ? p[4] : (uint8_t)_type;
    // During the connection (auth) phase the server may send an AuthMoreData
    // packet (first byte 0x01) as part of the caching_sha2_password exchange
    // -- a fast-auth/full-auth status byte or the RSA public key.  It must be
    // recognized here BEFORE the greeting branch, because the greeting
    // (HandshakeV10, first byte 0x0a) and AuthMoreData (0x01) are otherwise
    // both non-OK/non-error auth packets.  Outside the auth phase, a first
    // byte of 0x01 is a normal resultset column-count, handled below.
    if (is_auth && type == 0x01) {
        // Peek the status byte after the 4-byte header + 0x01 tag.  A
        // fast-auth-success marker (0x03) is immediately followed by a
        // terminal OK packet, and the server typically ships both in one TCP
        // segment.  The response wrapper parses exactly one reply per pass
        // and rejects trailing bytes, so when the OK is already buffered we
        // skip the 0x03 packet here and let the OK become this reply (the
        // auth state machine then proceeds to send the first real query).
        // When the OK has not arrived yet, we expose the AuthMoreData so the
        // state machine can wait for it.  A full-auth marker (0x04) and the
        // RSA-pubkey payload always require a client response, so they are
        // never coalesced.
        uint8_t status[4 + 2];
        const uint8_t* sp = (const uint8_t*)buf.fetch(status, sizeof(status));
        const bool fast_auth_success = (sp != NULL && sp[5] == 0x03);
        if (fast_auth_success) {
            // Determine, WITHOUT consuming anything, whether the OK packet
            // that follows the fast-auth marker is also fully buffered.
            const uint32_t amd_total = 4 + mysql_uint3korr(sp);
            butil::IOBuf rest;
            // Non-destructively copy the bytes that follow the 0x01 packet.
            buf.append_to(&rest, buf.size(), amd_total);
            if (!is_full_package(rest)) {
                // OK not arrived yet: expose the fast-auth marker untouched
                // and let the state machine wait for the next packet.
                _type = MYSQL_RSP_AUTH_MORE_DATA;
                MY_ALLOC_CHECK(my_alloc_check(arena, 1, _data.auth_more_data));
                MY_PARSE_CHECK(_data.auth_more_data->Parse(buf, arena));
                return PARSE_OK;
            }
            // Both packets buffered: drop the 0x01 packet from |buf| and
            // parse the following OK/ERR as this reply.
            butil::IOBuf discard;
            buf.cutn(&discard, amd_total);
            const uint8_t* p2 = (const uint8_t*)buf.fetch(header, sizeof(header));
            type = p2[4];
        } else {
            _type = MYSQL_RSP_AUTH_MORE_DATA;
            MY_ALLOC_CHECK(my_alloc_check(arena, 1, _data.auth_more_data));
            MY_PARSE_CHECK(_data.auth_more_data->Parse(buf, arena));
            return PARSE_OK;
        }
    }
    if (is_auth && type != 0x00 && type != 0xFF) {
        _type = MYSQL_RSP_AUTH;
        MY_ALLOC_CHECK(my_alloc_check(arena, 1, _data.auth));
        MY_PARSE_CHECK(_data.auth->Parse(buf, arena));
        return PARSE_OK;
    }
    if (type == 0x00 && (is_auth || stmt_type != MYSQL_NEED_PREPARE)) {
        _type = MYSQL_RSP_OK;
        MY_ALLOC_CHECK(my_alloc_check(arena, 1, _data.ok));
        MY_PARSE_CHECK(_data.ok->Parse(buf, arena));
        *more_results = _data.ok->status() & MYSQL_SERVER_MORE_RESULTS_EXISTS;
    } else if ((type == 0x00 && stmt_type == MYSQL_NEED_PREPARE) || type == MYSQL_RSP_PREPARE_OK) {
        _type = MYSQL_RSP_PREPARE_OK;
        MY_ALLOC_CHECK(my_alloc_check(arena, 1, _data.prepare_ok));
        MY_PARSE_CHECK(_data.prepare_ok->Parse(buf, arena));
    } else if (type == 0xFF) {
        _type = MYSQL_RSP_ERROR;
        MY_ALLOC_CHECK(my_alloc_check(arena, 1, _data.error));
        MY_PARSE_CHECK(_data.error->Parse(buf, arena));
    } else if (type == 0xFE) {
        _type = MYSQL_RSP_EOF;
        MY_ALLOC_CHECK(my_alloc_check(arena, 1, _data.eof));
        MY_PARSE_CHECK(_data.eof->Parse(buf));
        *more_results = _data.eof->status() & MYSQL_SERVER_MORE_RESULTS_EXISTS;
    } else if (type >= 0x01 && type <= 0xFA) {
        _type = MYSQL_RSP_RESULTSET;
        MY_ALLOC_CHECK(my_alloc_check(arena, 1, _data.result_set));
        MY_PARSE_CHECK(_data.result_set->Parse(buf, arena, !(stmt_type == MYSQL_NORMAL_STATEMENT)));
        *more_results = _data.result_set->_eof2.status() & MYSQL_SERVER_MORE_RESULTS_EXISTS;
    } else {
        LOG(ERROR) << "Unknown Response Type "
                   << "type=" << unsigned(type) << " buf_size=" << buf.size();
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    return PARSE_OK;
}

ParseError MysqlReply::Auth::Parse(butil::IOBuf& buf, butil::Arena* arena) {
    if (is_parsed()) {
        return PARSE_OK;
    }
    const std::string delim(1, 0x00);
    MysqlHeader header;
    if (!parse_header(buf, &header)) {
        return PARSE_ERROR_NOT_ENOUGH_DATA;
    }
    buf.cut1((char*)&_protocol);
    {
        butil::IOBuf version;
        buf.cut_until(&version, delim);
        char* d = NULL;
        MY_ALLOC_CHECK(my_alloc_check(arena, version.size(), d));
        version.copy_to(d);
        _version.set(d, version.size());
    }
    {
        uint8_t tmp[4];
        buf.cutn(tmp, sizeof(tmp));
        _thread_id = mysql_uint4korr(tmp);
    }
    {
        butil::IOBuf salt;
        buf.cut_until(&salt, delim);
        char* d = NULL;
        MY_ALLOC_CHECK(my_alloc_check(arena, salt.size(), d));
        salt.copy_to(d);
        _salt.set(d, salt.size());
    }
    {
        uint8_t tmp[2];
        buf.cutn(&tmp, sizeof(tmp));
        _capability = mysql_uint2korr(tmp);
    }
    buf.cut1((char*)&_collation);
    {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        _status = mysql_uint2korr(tmp);
    }
    {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        _extended_capability = mysql_uint2korr(tmp);
    }
    buf.cut1((char*)&_auth_plugin_length);
    buf.pop_front(10);
    {
        butil::IOBuf salt2;
        buf.cut_until(&salt2, delim);
        char* d = NULL;
        MY_ALLOC_CHECK(my_alloc_check(arena, salt2.size(), d));
        salt2.copy_to(d);
        _salt2.set(d, salt2.size());
    }
    {
        if (_auth_plugin_length > buf.size()) {
            LOG(ERROR) << "MysqlReply::Auth::Parse: auth_plugin length " << _auth_plugin_length
                       << " exceeds remaining buffer size " << buf.size();
            return PARSE_ERROR_ABSOLUTELY_WRONG;
        }
        char* d = NULL;
        MY_ALLOC_CHECK(my_alloc_check(arena, _auth_plugin_length, d));
        buf.cutn(d, _auth_plugin_length);
        _auth_plugin.set(d, _auth_plugin_length);
    }
    buf.clear();  // consume all buf
    set_parsed();
    return PARSE_OK;
}

ParseError MysqlReply::AuthMoreData::Parse(butil::IOBuf& buf, butil::Arena* arena) {
    if (is_parsed()) {
        return PARSE_OK;
    }
    MysqlHeader header;
    if (!parse_header(buf, &header)) {
        return PARSE_ERROR_NOT_ENOUGH_DATA;
    }
    _seq = (uint8_t)header.seq;
    // Drop the 0x01 AuthMoreData tag; expose only the bytes after it (a
    // single status byte 0x03/0x04, or the PEM-encoded RSA public key).
    buf.pop_front(1);
    const int64_t len = (int64_t)header.payload_size - 1;
    if (len > 0) {
        char* d = NULL;
        MY_ALLOC_CHECK(my_alloc_check(arena, len, d));
        buf.cutn(d, len);
        _data.set(d, len);
    } else {
        _data.set(NULL, 0);
    }
    set_parsed();
    return PARSE_OK;
}

ParseError MysqlReply::ResultSetHeader::Parse(butil::IOBuf& buf) {
    if (is_parsed()) {
        return PARSE_OK;
    }
    MysqlHeader header;
    if (!parse_header(buf, &header)) {
        return PARSE_ERROR_NOT_ENOUGH_DATA;
    }
    uint64_t old_size, new_size;
    old_size = buf.size();
    _column_count = parse_encode_length(buf);
    // Guard against an absurd/malicious column count driving unbounded
    // allocations downstream (per-column arrays and the row NULL-bitmap).
    // MySQL's hard limit is 4096 columns per table; 65535 is a generous cap
    // that no legitimate result set exceeds.
    if (_column_count > 65535) {
        LOG(ERROR) << "illegal column count " << _column_count;
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    new_size = buf.size();
    if (old_size - new_size < header.payload_size) {
        _extra_msg = parse_encode_length(buf);
    } else {
        _extra_msg = 0;
    }
    set_parsed();
    return PARSE_OK;
}

ParseError MysqlReply::Column::Parse(butil::IOBuf& buf, butil::Arena* arena) {
    if (is_parsed()) {
        return PARSE_OK;
    }
    MysqlHeader header;
    if (!parse_header(buf, &header)) {
        return PARSE_ERROR_NOT_ENOUGH_DATA;
    }

    // Each length-encoded string must fit within the remaining buffer; an
    // oversized length would otherwise drive my_alloc_check/cutn/.set past the
    // packet (mirrors the hardened auth_plugin path above).
    uint64_t len = parse_encode_length(buf);
    if (len > buf.size()) {
        LOG(WARNING) << "MysqlReply::Column::Parse: catalog length " << len
                   << " exceeds remaining buffer size " << buf.size();
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    char* catalog = NULL;
    MY_ALLOC_CHECK(my_alloc_check(arena, len, catalog));
    buf.cutn(catalog, len);
    _catalog.set(catalog, len);

    len = parse_encode_length(buf);
    if (len > buf.size()) {
        LOG(WARNING) << "MysqlReply::Column::Parse: database length " << len
                   << " exceeds remaining buffer size " << buf.size();
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    char* database = NULL;
    MY_ALLOC_CHECK(my_alloc_check(arena, len, database));
    buf.cutn(database, len);
    _database.set(database, len);

    len = parse_encode_length(buf);
    if (len > buf.size()) {
        LOG(WARNING) << "MysqlReply::Column::Parse: table length " << len
                   << " exceeds remaining buffer size " << buf.size();
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    char* table = NULL;
    MY_ALLOC_CHECK(my_alloc_check(arena, len, table));
    buf.cutn(table, len);
    _table.set(table, len);

    len = parse_encode_length(buf);
    if (len > buf.size()) {
        LOG(WARNING) << "MysqlReply::Column::Parse: origin_table length " << len
                   << " exceeds remaining buffer size " << buf.size();
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    char* origin_table = NULL;
    MY_ALLOC_CHECK(my_alloc_check(arena, len, origin_table));
    buf.cutn(origin_table, len);
    _origin_table.set(origin_table, len);

    len = parse_encode_length(buf);
    if (len > buf.size()) {
        LOG(WARNING) << "MysqlReply::Column::Parse: name length " << len
                   << " exceeds remaining buffer size " << buf.size();
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    char* name = NULL;
    MY_ALLOC_CHECK(my_alloc_check(arena, len, name));
    buf.cutn(name, len);
    _name.set(name, len);

    len = parse_encode_length(buf);
    if (len > buf.size()) {
        LOG(WARNING) << "MysqlReply::Column::Parse: origin_name length " << len
                   << " exceeds remaining buffer size " << buf.size();
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    char* origin_name = NULL;
    MY_ALLOC_CHECK(my_alloc_check(arena, len, origin_name));
    buf.cutn(origin_name, len);
    _origin_name.set(origin_name, len);
    buf.pop_front(1);
    {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        _charset = mysql_uint2korr(tmp);
    }
    {
        uint8_t tmp[4];
        buf.cutn(tmp, sizeof(tmp));
        _length = mysql_uint4korr(tmp);
    }
    buf.cut1((char*)&_type);
    {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        _flag = (MysqlFieldFlag)mysql_uint2korr(tmp);
    }
    buf.cut1((char*)&_decimal);
    buf.pop_front(2);
    set_parsed();
    return PARSE_OK;
}

ParseError MysqlReply::Ok::Parse(butil::IOBuf& buf, butil::Arena* arena) {
    if (is_parsed()) {
        return PARSE_OK;
    }
    MysqlHeader header;
    if (!parse_header(buf, &header)) {
        return PARSE_ERROR_NOT_ENOUGH_DATA;
    }

    uint64_t old_size, new_size;
    old_size = buf.size();
    buf.pop_front(1);

    _affect_row = parse_encode_length(buf);
    _index = parse_encode_length(buf);
    {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        _status = mysql_uint2korr(tmp);
    }
    {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        _warning = mysql_uint2korr(tmp);
    }

    new_size = buf.size();
    if (old_size - new_size < header.payload_size) {
        const int64_t len = header.payload_size - (old_size - new_size);
        char* msg = NULL;
        MY_ALLOC_CHECK(my_alloc_check(arena, len, msg));
        buf.cutn(msg, len);
        _msg.set(msg, len);
    }
    set_parsed();
    return PARSE_OK;
}

ParseError MysqlReply::Eof::Parse(butil::IOBuf& buf) {
    if (is_parsed()) {
        return PARSE_OK;
    }
    MysqlHeader header;
    if (!parse_header(buf, &header)) {
        return PARSE_ERROR_NOT_ENOUGH_DATA;
    }
    buf.pop_front(1);
    {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        _warning = mysql_uint2korr(tmp);
    }
    {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        _status = mysql_uint2korr(tmp);
    }
    set_parsed();
    return PARSE_OK;
}

ParseError MysqlReply::Error::Parse(butil::IOBuf& buf, butil::Arena* arena) {
    if (is_parsed()) {
        return PARSE_OK;
    }
    MysqlHeader header;
    if (!parse_header(buf, &header)) {
        return PARSE_ERROR_NOT_ENOUGH_DATA;
    }
    buf.pop_front(1);  // 0xFF
    {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        _errcode = mysql_uint2korr(tmp);
    }
    buf.pop_front(1);  // '#'
    // 5 byte server status
    char* status = NULL;
    MY_ALLOC_CHECK(my_alloc_check(arena, 5, status));
    buf.cutn(status, 5);
    _status.set(status, 5);
    // error message, Null-Terminated string.
    // payload layout consumed so far: 0xFF(1) + errcode(2) + '#'(1) +
    // sql_state(5) = 9 bytes; guard against a malformed short packet to avoid
    // an unsigned underflow producing a huge length.
    if (header.payload_size < 9) {
        LOG(WARNING) << "MysqlReply::Error::Parse: truncated ERR packet, payload_size "
                   << header.payload_size << " < 9 (0xFF+errcode+'#'+sql_state)";
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    uint64_t len = header.payload_size - 9;
    char* msg = NULL;
    MY_ALLOC_CHECK(my_alloc_check(arena, len, msg));
    buf.cutn(msg, len);
    _msg.set(msg, len);
    set_parsed();
    return PARSE_OK;
}

ParseError MysqlReply::Row::Parse(butil::IOBuf& buf,
                                  const MysqlReply::Column* columns,
                                  uint64_t column_count,
                                  MysqlReply::Field* fields,
                                  bool binary,
                                  butil::Arena* arena) {
    if (is_parsed()) {
        return PARSE_OK;
    }
    MysqlHeader header;
    if (!parse_header(buf, &header)) {
        return PARSE_ERROR_NOT_ENOUGH_DATA;
    }
    if (!binary) {  // mysql text protocol
        for (uint64_t i = 0; i < column_count; ++i) {
            MY_PARSE_CHECK(fields[i].Parse(buf, columns + i, arena));
        }
    } else {  // mysql binary protocol
        uint8_t hdr = 0;
        buf.cut1((char*)&hdr);
        if (hdr != 0x00) {
            LOG(WARNING) << "MysqlReply::Row::Parse: binary row packet header byte is "
                       << unsigned(hdr) << ", expected 0x00";
            return PARSE_ERROR_ABSOLUTELY_WRONG;
        }
        // NULL-bitmap, [(column-count + 7 + 2) / 8 bytes]. Allocate from the
        // arena instead of a stack VLA: column_count is attacker-controlled
        // (length-encoded in the result-set header), so a large value would
        // otherwise be an unbounded stack allocation / stack overflow.
        const uint64_t size = ((column_count + 7 + 2) >> 3);
        uint8_t* null_mask = NULL;
        MY_ALLOC_CHECK(my_alloc_check(arena, (size_t)size, null_mask));
        for (uint64_t i = 0; i < size; ++i) {
            null_mask[i] = 0;
        }
        buf.cutn(null_mask, size);
        for (uint64_t i = 0; i < column_count; ++i) {
            MY_PARSE_CHECK(fields[i].Parse(buf, columns + i, i, column_count, null_mask, arena));
        }
    }
    set_parsed();
    return PARSE_OK;
}

ParseError MysqlReply::Field::Parse(butil::IOBuf& buf,
                                    const MysqlReply::Column* column,
                                    butil::Arena* arena) {
    if (is_parsed()) {
        return PARSE_OK;
    }
    // field type
    _type = column->_type;
    // is unsigned flag set
    _unsigned = column->_flag & MYSQL_UNSIGNED_FLAG;
    // parse encode length
    const uint64_t len = parse_encode_length(buf);
    // is it null?
    if (len == 0 && !(column->_flag & MYSQL_NOT_NULL_FLAG)) {
        _is_nil = true;
        set_parsed();
        return PARSE_OK;
    }
    // field is not null
    butil::IOBuf str;
    buf.cutn(&str, len);
    switch (_type) {
        case MYSQL_FIELD_TYPE_NULL:
            _is_nil = true;
            break;
        case MYSQL_FIELD_TYPE_TINY:
            if (column->_flag & MYSQL_UNSIGNED_FLAG) {
                _data.tiny = strtoul(str.to_string().c_str(), NULL, 10);
            } else {
                _data.stiny = strtol(str.to_string().c_str(), NULL, 10);
            }
            break;
        case MYSQL_FIELD_TYPE_SHORT:
        case MYSQL_FIELD_TYPE_YEAR:
            if (column->_flag & MYSQL_UNSIGNED_FLAG) {
                _data.small = strtoul(str.to_string().c_str(), NULL, 10);
            } else {
                _data.ssmall = strtol(str.to_string().c_str(), NULL, 10);
            }
            break;
        case MYSQL_FIELD_TYPE_INT24:
        case MYSQL_FIELD_TYPE_LONG:
            if (column->_flag & MYSQL_UNSIGNED_FLAG) {
                _data.integer = strtoul(str.to_string().c_str(), NULL, 10);
            } else {
                _data.sinteger = strtol(str.to_string().c_str(), NULL, 10);
            }
            break;
        case MYSQL_FIELD_TYPE_LONGLONG:
            if (column->_flag & MYSQL_UNSIGNED_FLAG) {
                _data.bigint = strtoul(str.to_string().c_str(), NULL, 10);
            } else {
                _data.sbigint = strtol(str.to_string().c_str(), NULL, 10);
            }
            break;
        case MYSQL_FIELD_TYPE_FLOAT:
            _data.float32 = strtof(str.to_string().c_str(), NULL);
            break;
        case MYSQL_FIELD_TYPE_DOUBLE:
            _data.float64 = strtod(str.to_string().c_str(), NULL);
            break;
        case MYSQL_FIELD_TYPE_DECIMAL:
        case MYSQL_FIELD_TYPE_NEWDECIMAL:
        case MYSQL_FIELD_TYPE_VARCHAR:
        case MYSQL_FIELD_TYPE_BIT:
        case MYSQL_FIELD_TYPE_ENUM:
        case MYSQL_FIELD_TYPE_SET:
        case MYSQL_FIELD_TYPE_TINY_BLOB:
        case MYSQL_FIELD_TYPE_MEDIUM_BLOB:
        case MYSQL_FIELD_TYPE_LONG_BLOB:
        case MYSQL_FIELD_TYPE_BLOB:
        case MYSQL_FIELD_TYPE_VAR_STRING:
        case MYSQL_FIELD_TYPE_STRING:
        case MYSQL_FIELD_TYPE_GEOMETRY:
        case MYSQL_FIELD_TYPE_JSON:
        case MYSQL_FIELD_TYPE_TIME:
        case MYSQL_FIELD_TYPE_DATE:
        case MYSQL_FIELD_TYPE_NEWDATE:
        case MYSQL_FIELD_TYPE_TIMESTAMP:
        case MYSQL_FIELD_TYPE_DATETIME: {
            char* d = NULL;
            MY_ALLOC_CHECK(my_alloc_check(arena, len, d));
            str.copy_to(d);
            _data.str.set(d, len);
        } break;
        default:
            LOG(ERROR) << "Unknown field type";
            set_parsed();
            return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    set_parsed();
    return PARSE_OK;
}

ParseError MysqlReply::Field::Parse(butil::IOBuf& buf,
                                    const MysqlReply::Column* column,
                                    uint64_t column_index,
                                    uint64_t column_count,
                                    const uint8_t* null_mask,
                                    butil::Arena* arena) {
    if (is_parsed()) {
        return PARSE_OK;
    }
    // field type
    _type = column->_type;
    // is unsigned flag set
    _unsigned = column->_flag & MYSQL_UNSIGNED_FLAG;
    // (byte >> bit-pos) % 2 == 1
    if (((null_mask[(column_index + 2) >> 3] >> ((column_index + 2) & 7)) & 1) == 1) {
        _is_nil = true;
        set_parsed();
        return PARSE_OK;
    }

    switch (_type) {
        case MYSQL_FIELD_TYPE_NULL:
            _is_nil = true;
            break;
        case MYSQL_FIELD_TYPE_TINY:
            if (column->_flag & MYSQL_UNSIGNED_FLAG) {
                buf.cut1((char*)&_data.tiny);
            } else {
                buf.cut1((char*)&_data.stiny);
            }
            break;
        case MYSQL_FIELD_TYPE_SHORT:
        case MYSQL_FIELD_TYPE_YEAR:
            if (column->_flag & MYSQL_UNSIGNED_FLAG) {
                uint8_t* p = (uint8_t*)&_data.small;
                buf.cutn(p, 2);
                _data.small = mysql_uint2korr(p);
            } else {
                uint8_t* p = (uint8_t*)&_data.ssmall;
                buf.cutn(p, 2);
                _data.ssmall = (int16_t)mysql_uint2korr(p);
            }
            break;
        case MYSQL_FIELD_TYPE_INT24:
        case MYSQL_FIELD_TYPE_LONG:
            if (column->_flag & MYSQL_UNSIGNED_FLAG) {
                uint8_t* p = (uint8_t*)&_data.integer;
                buf.cutn(p, 4);
                _data.integer = mysql_uint4korr(p);
            } else {
                uint8_t* p = (uint8_t*)&_data.sinteger;
                buf.cutn(p, 4);
                _data.sinteger = (int32_t)mysql_uint4korr(p);
            }
            break;
        case MYSQL_FIELD_TYPE_LONGLONG:
            if (column->_flag & MYSQL_UNSIGNED_FLAG) {
                uint8_t* p = (uint8_t*)&_data.bigint;
                buf.cutn(p, 8);
                _data.bigint = mysql_uint8korr(p);
            } else {
                uint8_t* p = (uint8_t*)&_data.sbigint;
                buf.cutn(p, 8);
                _data.sbigint = (int64_t)mysql_uint8korr(p);
            }
            break;
        case MYSQL_FIELD_TYPE_FLOAT: {
            uint8_t* p = (uint8_t*)&_data.float32;
            buf.cutn(p, 4);
        } break;
        case MYSQL_FIELD_TYPE_DOUBLE: {
            uint8_t* p = (uint8_t*)&_data.float64;
            buf.cutn(p, 8);
        } break;
        case MYSQL_FIELD_TYPE_DECIMAL:
        case MYSQL_FIELD_TYPE_NEWDECIMAL:
        case MYSQL_FIELD_TYPE_VARCHAR:
        case MYSQL_FIELD_TYPE_BIT:
        case MYSQL_FIELD_TYPE_ENUM:
        case MYSQL_FIELD_TYPE_SET:
        case MYSQL_FIELD_TYPE_TINY_BLOB:
        case MYSQL_FIELD_TYPE_MEDIUM_BLOB:
        case MYSQL_FIELD_TYPE_LONG_BLOB:
        case MYSQL_FIELD_TYPE_BLOB:
        case MYSQL_FIELD_TYPE_VAR_STRING:
        case MYSQL_FIELD_TYPE_STRING:
        case MYSQL_FIELD_TYPE_GEOMETRY:
        case MYSQL_FIELD_TYPE_JSON: {
            const uint64_t len = parse_encode_length(buf);
            // is it null?
            if (len == 0 && !(column->_flag & MYSQL_NOT_NULL_FLAG)) {
                _is_nil = true;
                set_parsed();
                return PARSE_OK;
            }
            // field is not null
            if (len > buf.size()) {
                LOG(WARNING) << "MysqlReply::Field::Parse (binary): string field length " << len
                           << " exceeds remaining buffer size " << buf.size();
                return PARSE_ERROR_ABSOLUTELY_WRONG;
            }
            char* d = NULL;
            MY_ALLOC_CHECK(my_alloc_check(arena, len, d));
            buf.cutn(d, len);
            _data.str.set(d, len);
        } break;
        case MYSQL_FIELD_TYPE_NEWDATE:      // Date YYYY-MM-DD
        case MYSQL_FIELD_TYPE_DATE:         // Date YYYY-MM-DD
        case MYSQL_FIELD_TYPE_DATETIME:     // Timestamp YYYY-MM-DD HH:MM:SS[.fractal]
        case MYSQL_FIELD_TYPE_TIMESTAMP: {  // Timestamp YYYY-MM-DD HH:MM:SS[.fractal]
            ParseError rc = ParseBinaryDataTime(buf, column, _data.str, arena);
            if (rc != PARSE_OK) {
                return rc;
            }
        } break;
        case MYSQL_FIELD_TYPE_TIME: {  // Time [-][H]HH:MM:SS[.fractal]
            ParseError rc = ParseBinaryTime(buf, column, _data.str, arena);
            if (rc != PARSE_OK) {
                return rc;
            }
        } break;
        default:
            LOG(ERROR) << "Unknown field type";
            return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    set_parsed();
    return PARSE_OK;
}

ParseError MysqlReply::Field::ParseBinaryTime(butil::IOBuf& buf,
                                              const MysqlReply::Column* column,
                                              butil::StringPiece& str,
                                              butil::Arena* arena) {

    const uint64_t len = parse_encode_length(buf);
    // A length of 0, 8 or 12 are the only legal binary TIME encodings. Anything
    // else is a malformed packet -- reject it rather than reading past the value.
    // NOTE: len == 0 is NOT a NULL value (NULL is signalled by the row
    // NULL-bitmap, handled by the caller before we are reached); it is the zero
    // TIME value "00:00:00" with no field bytes on the wire.
    if (len != 0 && len != 8 && len != 12) {
        LOG(ERROR) << "invalid TIME packet length " << len;
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    // Never read more value bytes than the packet actually carries.
    if (len > buf.size()) {
        LOG(ERROR) << "TIME value length " << len << " exceeds buffer size " << buf.size();
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }

    // Base "HH:MM:SS" is 8 bytes, but MySQL binary TIME spans up to 838 hours
    // and may be negative, so reserve 2 extra bytes for a leading sign and a
    // possible 3rd hour digit ("-838:59:59[.ffffff]").
    uint8_t dstlen;
    switch (column->_decimal) {
        case 0x00:
        case 0x1f:
            dstlen = 8 + 2;
            break;
        case 1:
        case 2:
        case 3:
        case 4:
        case 5:
        case 6:
            dstlen = 8 + 2 + 1 + column->_decimal;
            break;
        default:
            LOG(ERROR) << "protocol error, illegal decimals value " << column->_decimal;
            return PARSE_ERROR_ABSOLUTELY_WRONG;
    }

    size_t i = 0;
    char* d = NULL;
    MY_ALLOC_CHECK(my_alloc_check(arena, dstlen + 2, d));
    d[dstlen] = '\0';
    d[dstlen + 1] = '\0';
    // Read only the fields that are present for this `len`; absent fields are 0.
    // len == 0  -> no bytes: "00:00:00".
    // len == 8  -> is_negative(1) days(4 LE) hour(1) min(1) sec(1), no micros.
    // len == 12 -> + micros(4 LE).
    uint32_t day = 0;
    uint8_t neg = 0, hour = 0, min = 0, sec = 0;

    if (len >= 8) {
        buf.cut1((char*)&neg);
        buf.cutn(&day, 4);
        day = mysql_uint4korr((uint8_t*)&day);
        buf.cut1((char*)&hour);
        buf.cut1((char*)&min);
        buf.cut1((char*)&sec);
    }

    // Validate field ranges so the formatted output cannot overflow the buffer
    // and so we never index past digits01/digits10. MySQL caps TIME at 838
    // hours and 59 min/sec; total_hour is at most 3 digits, which dstlen sizes
    // for. A larger total_hour would emit >3 hour digits and overrun `d`.
    if (neg > 1 || min > 59 || sec > 59) {
        LOG(ERROR) << "invalid TIME field value";
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    // MySQL binary TIME spans up to 838 hours, so the total can exceed 255 and
    // must be accumulated in a wider type than the 1-byte wire field.
    uint32_t total_hour = (uint32_t)hour + day * 24;
    if (total_hour > 838) {
        LOG(ERROR) << "TIME total hours " << total_hour << " exceeds MySQL max 838";
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }

    if (neg == 1) {
        d[i++] = '-';
    }
    if (total_hour >= 100) {
        // total_hour is in [100, 838]: exactly 3 digits, which dstlen reserves
        // space for. Emit hundreds/tens/units directly; the digits01/digits10
        // lookup tables only cover 0..99 so they cannot be indexed by the full
        // value here.
        d[i++] = (char)('0' + total_hour / 100);
        const uint32_t rem = total_hour % 100;
        d[i++] = digits10[rem];
        d[i++] = digits01[rem];
    } else {
        d[i++] = digits10[total_hour];
        d[i++] = digits01[total_hour];
    }

    d[i++] = ':';
    d[i++] = digits10[min];
    d[i++] = digits01[min];
    d[i++] = ':';
    d[i++] = digits10[sec];
    d[i++] = digits01[sec];

    // Microseconds are only present on the wire when len == 12; for len == 0 or
    // len == 8 there are no microsecond bytes even if the column declares
    // decimals.
    ParseError rc;
    if (len == 12) {
        rc = ParseMicrosecs(buf, column->_decimal, d + i);
    } else {
        write_zero_microsecs(column->_decimal, d + i);
        rc = PARSE_OK;
    }
    if (rc == PARSE_OK) {
        // TIME is variable-width (optional sign, 2- or 3+-digit hour), so report
        // the EXACT bytes actually written: i (through ":SS") plus the
        // fractional part -- '.' + decimal digits when decimal is 1..6, else
        // nothing (decimal 0 or 0x1f writes no fractional bytes).
        const size_t micros_len =
            (column->_decimal >= 1 && column->_decimal <= 6) ? (size_t)column->_decimal + 1 : 0;
        str.set(d, i + micros_len);
    }
    return rc;
}

ParseError MysqlReply::Field::ParseBinaryDataTime(butil::IOBuf& buf,
                                                  const MysqlReply::Column* column,
                                                  butil::StringPiece& str,
                                                  butil::Arena* arena) {
    const uint64_t len = parse_encode_length(buf);
    // A length of 0, 4, 7 or 11 are the only legal binary DATE/DATETIME/
    // TIMESTAMP encodings. Reject anything else rather than over-reading.
    // NOTE: len == 0 is NOT a NULL value (NULL is signalled by the row
    // NULL-bitmap, handled by the caller before we are reached); it is the zero
    // value "0000-00-00 00:00:00" (or "0000-00-00" for DATE) with no field
    // bytes on the wire.
    if (len != 0 && len != 4 && len != 7 && len != 11) {
        LOG(ERROR) << "illegal date time length " << len;
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    // Never read more value bytes than the packet actually carries.
    if (len > buf.size()) {
        LOG(ERROR) << "DATETIME value length " << len << " exceeds buffer size " << buf.size();
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }
    // A DATE column carries only the date part; a time-of-day part on the wire
    // would not fit its 10-byte output buffer, so reject those packets.
    const bool is_date = (column->_type == MYSQL_FIELD_TYPE_DATE ||
                          column->_type == MYSQL_FIELD_TYPE_NEWDATE);
    if (is_date && len != 0 && len != 4) {
        LOG(ERROR) << "illegal DATE length " << len;
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }

    uint8_t dstlen;
    if (is_date) {
        dstlen = 10;
    } else {
        switch (column->_decimal) {
            case 0x00:
            case 0x1f:
                dstlen = 19;
                break;
            case 1:
            case 2:
            case 3:
            case 4:
            case 5:
            case 6:
                dstlen = 19 + 1 + column->_decimal;
                break;
            default:
                LOG(ERROR) << "protocol error, illegal decimal value " << column->_decimal;
                return PARSE_ERROR_ABSOLUTELY_WRONG;
        }
    }

    size_t i = 0;
    char* d = NULL;
    MY_ALLOC_CHECK(my_alloc_check(arena, dstlen, d));
    // Read only the fields present for this `len`; absent fields are 0.
    // len == 0  -> no bytes (all-zero value).
    // len == 4  -> year(2 LE) month(1) day(1) only -> "YYYY-MM-DD".
    // len == 7  -> + hour(1) min(1) sec(1) -> "YYYY-MM-DD HH:MM:SS".
    // len == 11 -> + micros(4 LE).
    uint16_t year = 0;
    uint8_t month = 0, day = 0, hour = 0, min = 0, sec = 0;
    if (len >= 4) {
        buf.cutn(&year, 2);
        year = mysql_uint2korr((uint8_t*)&year);
        buf.cut1((char*)&month);
        buf.cut1((char*)&day);
    }
    if (len >= 7) {
        buf.cut1((char*)&hour);
        buf.cut1((char*)&min);
        buf.cut1((char*)&sec);
    }

    // Validate field ranges: year < 10000 keeps the 4-digit year within bounds
    // and keeps every two-digit component inside the digits01/digits10 tables
    // (which only cover 0..99), preventing both buffer overrun and OOB reads.
    if (year > 9999 || month > 99 || day > 99 || hour > 99 || min > 59 || sec > 59) {
        LOG(ERROR) << "invalid DATE/DATETIME field value";
        return PARSE_ERROR_ABSOLUTELY_WRONG;
    }

    const uint8_t pt = year / 100;
    const uint8_t p1 = year - (100 * pt);
    d[i++] = digits10[pt];
    d[i++] = digits01[pt];
    d[i++] = digits10[p1];
    d[i++] = digits01[p1];
    d[i++] = '-';
    d[i++] = digits10[month];
    d[i++] = digits01[month];
    d[i++] = '-';
    d[i++] = digits10[day];
    d[i++] = digits01[day];

    if (is_date) {
        // DATE column: only "YYYY-MM-DD" (10 bytes) is meaningful.
        str.set(d, i);
        return PARSE_OK;
    }

    // DATETIME/TIMESTAMP column: always emit the full "YYYY-MM-DD HH:MM:SS"
    // form. When len == 4 the time-of-day fields were absent on the wire and
    // default to zero ("00:00:00"); we still write those bytes here so the
    // reported length matches what was actually written.
    d[i++] = ' ';
    d[i++] = digits10[hour];
    d[i++] = digits01[hour];
    d[i++] = ':';
    d[i++] = digits10[min];
    d[i++] = digits01[min];
    d[i++] = ':';
    d[i++] = digits10[sec];
    d[i++] = digits01[sec];

    // Microseconds are only present on the wire when len == 11; for len == 7
    // there are no microsecond bytes even if the column declares decimals.
    ParseError rc;
    if (len == 11) {
        rc = ParseMicrosecs(buf, column->_decimal, d + i);
    } else {
        write_zero_microsecs(column->_decimal, d + i);
        rc = PARSE_OK;
    }
    if (rc == PARSE_OK) {
        // Report the EXACT bytes written: "YYYY-MM-DD HH:MM:SS" (i == 19) plus
        // the fractional part -- '.' + decimal digits when decimal is 1..6, else
        // nothing.
        const size_t micros_len =
            (column->_decimal >= 1 && column->_decimal <= 6) ? (size_t)column->_decimal + 1 : 0;
        str.set(d, i + micros_len);
    }
    return rc;
}

ParseError MysqlReply::Field::ParseMicrosecs(butil::IOBuf& buf, uint8_t decimal, char* d) {
    size_t i = 0;
    uint32_t microsecs;
    uint8_t p1, p2, p3;
    // Always consume the 4 microsecond bytes present on the wire (the caller
    // only invokes this when the value length includes them); format them only
    // when the column declares 1..6 fractional digits (0 / 0x1f == no fraction).
    buf.cutn((char*)&microsecs, 4);
    if (decimal == 0 || decimal > 6) {
        return PARSE_OK;
    }
    microsecs = mysql_uint4korr((uint8_t*)&microsecs);
    p1 = microsecs / 10000;
    microsecs -= 10000 * p1;
    p2 = microsecs / 100;
    microsecs -= 100 * p2;
    p3 = microsecs;

    switch (decimal) {
        case 1:
            d[i++] = '.';
            d[i++] = digits10[p1];
            break;
        case 2:
            d[i++] = '.';
            d[i++] = digits10[p1];
            d[i++] = digits01[p1];
            break;
        case 3:
            d[i++] = '.';
            d[i++] = digits10[p1];
            d[i++] = digits01[p1];
            d[i++] = digits10[p2];
            break;
        case 4:
            d[i++] = '.';
            d[i++] = digits10[p1];
            d[i++] = digits01[p1];
            d[i++] = digits10[p2];
            d[i++] = digits01[p2];
            break;
        case 5:
            d[i++] = '.';
            d[i++] = digits10[p1];
            d[i++] = digits01[p1];
            d[i++] = digits10[p2];
            d[i++] = digits01[p2];
            d[i++] = digits10[p3];
            break;
        default:
            d[i++] = '.';
            d[i++] = digits10[p1];
            d[i++] = digits01[p1];
            d[i++] = digits10[p2];
            d[i++] = digits01[p2];
            d[i++] = digits10[p3];
            d[i++] = digits01[p3];
    }
    return PARSE_OK;
}

ParseError MysqlReply::ResultSet::Parse(butil::IOBuf& buf, butil::Arena* arena, bool binary) {
    if (is_parsed()) {
        return PARSE_OK;
    }
    // parse header
    MY_PARSE_CHECK(_header.Parse(buf));
    // parse colunms
    MY_ALLOC_CHECK(my_alloc_check(arena, _header._column_count, _columns));
    for (uint64_t i = 0; i < _header._column_count; ++i) {
        MY_PARSE_CHECK(_columns[i].Parse(buf, arena));
    }
    // parse eof1
    MY_PARSE_CHECK(_eof1.Parse(buf));
    // parse row
    std::vector<Row*> rows;
    for (;;) {
        // if not full package reread
        if (!is_full_package(buf)) {
            return PARSE_ERROR_NOT_ENOUGH_DATA;
        }
        // if eof break loops for row
        if (is_an_eof(buf)) {
            break;
        }
        // allocate memory for row and fields
        Row* row = NULL;
        Field* fields = NULL;
        MY_ALLOC_CHECK(my_alloc_check(arena, 1, row));
        MY_ALLOC_CHECK(my_alloc_check(arena, _header._column_count, fields));
        row->_fields = fields;
        row->_field_count = _header._column_count;
        _last->_next = row;
        _last = row;
        // parse row and fields
        MY_PARSE_CHECK(row->Parse(buf, _columns, _header._column_count, fields, binary, arena));
        // add row count
        ++_row_count;
    }
    // parse eof2
    MY_PARSE_CHECK(_eof2.Parse(buf));
    set_parsed();
    return PARSE_OK;
}

ParseError MysqlReply::PrepareOk::Parse(butil::IOBuf& buf, butil::Arena* arena) {
    if (is_parsed()) {
        return PARSE_OK;
    }

    MY_PARSE_CHECK(_header.Parse(buf));

    if (_header._param_count > 0) {
        MY_ALLOC_CHECK(my_alloc_check(arena, _header._param_count, _params));
        for (uint16_t i = 0; i < _header._param_count; ++i) {
            MY_PARSE_CHECK(_params[i].Parse(buf, arena));
        }
        MY_PARSE_CHECK(_eof1.Parse(buf));
    }

    if (_header._column_count > 0) {
        MY_ALLOC_CHECK(my_alloc_check(arena, _header._column_count, _columns));
        for (uint16_t i = 0; i < _header._column_count; ++i) {
            MY_PARSE_CHECK(_columns[i].Parse(buf, arena));
        }
        MY_PARSE_CHECK(_eof2.Parse(buf));
    }
    set_parsed();
    return PARSE_OK;
}

ParseError MysqlReply::PrepareOk::Header::Parse(butil::IOBuf& buf) {
    if (is_parsed()) {
        return PARSE_OK;
    }

    MysqlHeader header;
    if (!parse_header(buf, &header)) {
        return PARSE_ERROR_NOT_ENOUGH_DATA;
    }

    buf.pop_front(1);
    {
        uint8_t tmp[4];
        buf.cutn(tmp, sizeof(tmp));
        _stmt_id = mysql_uint4korr(tmp);
    }
    {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        _column_count = mysql_uint2korr(tmp);
    }
    {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        _param_count = mysql_uint2korr(tmp);
    }
    buf.pop_front(1);
    {
        uint8_t tmp[2];
        buf.cutn(tmp, sizeof(tmp));
        _warning = mysql_uint2korr(tmp);
    }

    set_parsed();
    return PARSE_OK;
}

uint32_t MysqlStatement::StatementId(SocketId socket_id) const {
    if (_connection_type == CONNECTION_TYPE_SHORT) {
        return 0;
    }
    {
        MysqlStatementDBD::ScopedPtr ptr;
        if (_id_map.Read(&ptr) != 0) {
            LOG(WARNING) << "MysqlStatement::StatementId: failed to read the "
                          "statement-id map (DoublyBufferedData::Read failed) "
                          "for socket_id=" << socket_id << ", returning stmt_id=0";
            return 0;
        }
        const MysqlStatementId* p = ptr->seek(socket_id);
        if (p == NULL) {
            LOG(WARNING) << "MysqlStatement::StatementId: no prepared statement id "
                          "cached for socket_id=" << socket_id
                       << " (statement not found / not prepared on this "
                          "connection), returning stmt_id=0";
            return 0;
        }
        SocketUniquePtr socket;
        if (Socket::Address(socket_id, &socket) == 0) {
            uint64_t fd_version = socket->fd_version();
            if (fd_version == p->version) {
                return p->stmt_id;
            }
        }
    }
    // The socket was closed/recycled (version mismatch or address failed):
    // the cached stmt_id is stale and the server has dropped the prepared
    // statement. Erase the entry so it doesn't accumulate for the process
    // lifetime; a fresh prepare will re-insert via SetStatementId.
    //
    // NOTE: the read ScopedPtr above is released (closing scope) BEFORE this
    // Modify(), since DoublyBufferedData::Modify() blocks until all live
    // Read() references are gone -- holding `ptr` here would deadlock.
    _id_map.Modify(my_delete_k, socket_id);
    LOG(WARNING) << "MysqlStatement::StatementId: cached statement id for "
                  "socket_id=" << socket_id << " is stale (socket closed/recycled "
                  "-- fd_version mismatch or Socket::Address failed); erased the "
                  "entry and returning stmt_id=0 to force a re-prepare";
    return 0;
}

void MysqlStatement::SetStatementId(SocketId socket_id, uint32_t stmt_id) {
    if (_connection_type == CONNECTION_TYPE_SHORT) {
        return;
    }
    SocketUniquePtr socket;
    if (Socket::Address(socket_id, &socket) == 0) {
        uint64_t fd_version = socket->fd_version();
        MysqlStatementId value{stmt_id, fd_version};
        _id_map.Modify(my_update_kv, socket_id, value);
    }
}

uint16_t CountPlaceholders(const std::string& s) {
    uint16_t count = 0;
    const size_t n = s.size();
    for (size_t i = 0; i < n; ++i) {
        const char c = s[i];
        if (c == '\'' || c == '"' || c == '`') {
            // Skip the quoted span. Handles backslash escapes and the SQL
            // doubled-quote escape ('' inside '...').
            const char quote = c;
            ++i;
            while (i < n) {
                const char d = s[i];
                if (d == '\\' && quote != '`') {
                    ++i;  // skip escaped char
                } else if (d == quote) {
                    if (i + 1 < n && s[i + 1] == quote) {
                        ++i;  // doubled quote -> literal quote, stay in string
                    } else {
                        break;  // closing quote
                    }
                }
                ++i;
            }
        } else if (c == '-' && i + 1 < n && s[i + 1] == '-') {
            // line comment until end of line
            i += 2;
            while (i < n && s[i] != '\n') {
                ++i;
            }
        } else if (c == '#') {
            // line comment until end of line
            ++i;
            while (i < n && s[i] != '\n') {
                ++i;
            }
        } else if (c == '/' && i + 1 < n && s[i + 1] == '*') {
            // block comment until */
            i += 2;
            while (i + 1 < n && !(s[i] == '*' && s[i + 1] == '/')) {
                ++i;
            }
            ++i;  // land on '/' (loop ++i moves past it)
        } else if (c == '?') {
            ++count;
        }
    }
    return count;
}

void MysqlStatement::Init(const Channel& channel) {
    _param_count = CountPlaceholders(_str);
    ChannelOptions opts = channel.options();
    _connection_type = ConnectionType(opts.connection_type);
    if (_connection_type != CONNECTION_TYPE_SHORT) {
        _id_map.Modify(my_init_kv);
    } else {
        LOG_EVERY_SECOND(WARNING)
            << "Prepared statement on a 'short' connection re-prepares on every "
               "execute (a new TCP connection per request cannot cache the "
               "server stmt_id); use connection_type='pooled' for prepared "
               "statements.";
    }
}

bool MysqlTransaction::DoneTransaction(const char* command) {
    bool rc = false;
    MysqlRequest request(this);
    if (_socket == NULL) {  // must already commit or rollback, return true.
        return true;
    } else if (!request.Query(command)) {
        LOG(ERROR) << "Fail to query command" << command;
    } else {
        MysqlResponse response;
        Controller cntl;
        _channel.CallMethod(NULL, &cntl, &request, &response, NULL);
        if (!cntl.Failed()) {
            if (response.reply(0).is_ok()) {
                rc = true;
            } else {
                LOG(ERROR) << "Fail " << command << " transaction, " << response;
            }
        } else {
            LOG(ERROR) << "Fail " << command << " transaction, " << cntl.ErrorText();
        }
    }
    if (rc && _connection_type == CONNECTION_TYPE_POOLED) {
        _socket->ReturnToPool();
    }
    _socket.reset();
    return rc;
}

MysqlTransactionUniquePtr NewMysqlTransaction(Channel& channel,
                                              const MysqlTransactionOptions& opts) {
    const char* command[2] = {"START TRANSACTION READ ONLY", "START TRANSACTION"};

    if (channel.options().connection_type == CONNECTION_TYPE_SINGLE) {
        LOG(ERROR) << "mysql transaction can't use connection type 'single'";
        return NULL;
    }
    std::stringstream ss;
    // repeatable read is mysql default isolation level, so ignore it.
    if (opts.isolation_level != MysqlIsoRepeatableRead) {
        ss << "SET TRANSACTION ISOLATION LEVEL " << mysql_isolation_level[opts.isolation_level]
           << ";";
    }

    if (opts.readonly) {
        ss << command[0];
    } else {
        ss << command[1];
    }

    MysqlRequest request;
    if (!request.Query(ss.str())) {
        LOG(ERROR) << "Fail to query command" << ss.str();
        return NULL;
    }

    MysqlTransactionUniquePtr tx;
    MysqlResponse response;
    Controller cntl;
    ControllerPrivateAccessor(&cntl).set_bind_sock_action(BIND_SOCK_RESERVE);
    channel.CallMethod(NULL, &cntl, &request, &response, NULL);
    if (!cntl.Failed()) {
        // repeatable read isolation send one reply, other isolation has two reply
        if ((opts.isolation_level == MysqlIsoRepeatableRead && response.reply(0).is_ok()) ||
            (response.reply(0).is_ok() && response.reply(1).is_ok())) {
            SocketUniquePtr socket;
            ControllerPrivateAccessor(&cntl).get_bind_sock(&socket);
            if (socket == NULL) {
                LOG(ERROR) << "Fail create mysql transaction, get bind socket failed";
            } else {
                tx.reset(new MysqlTransaction(channel, socket, cntl.connection_type()));
            }
        } else {
            // The RPC itself succeeded so a socket was reserved on the
            // controller; the transaction did not start though, so return the
            // reserved pooled socket instead of letting ~Controller drop its
            // ref (which would leak the pooled connection).
            SocketUniquePtr socket;
            ControllerPrivateAccessor(&cntl).get_bind_sock(&socket);
            if (socket != NULL && cntl.connection_type() == CONNECTION_TYPE_POOLED) {
                socket->ReturnToPool();
            }
            LOG(ERROR) << "Fail create mysql transaction, " << response;
        }
    } else {
        LOG(ERROR) << "Fail create mysql transaction, " << cntl.ErrorText();
    }
    return tx;
}

static std::string TestDataDir() {
    char cwd[1024];
    if (getcwd(cwd, sizeof(cwd)) == NULL) {
        return std::string("/tmp/mysql_conn_type_data_for_test");
    }
    return std::string(cwd) + "/mysql_conn_type_data_for_test";
}

static void RemoveMysqlServer() {
    if (g_mysqld_pid > 0) {
        puts("[Stopping mysqld]");
        char cmd[1280];
        snprintf(cmd, sizeof(cmd), "kill %d", g_mysqld_pid);
        CHECK(0 == system(cmd));
        usleep(500000);
        snprintf(cmd, sizeof(cmd), "rm -rf '%s'", TestDataDir().c_str());
        CHECK(0 == system(cmd));
    }
}

static int ProbeConnect() {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(static_cast<uint16_t>(g_port));
    addr.sin_addr.s_addr = inet_addr(g_host.c_str());
    if (connect(fd, (struct sockaddr*)&addr, sizeof(addr)) != 0) {
        close(fd);
        return -1;
    }
    return fd;
}

static void StartServerOnce() {
    if (FLAGS_mysql_use_running_server) {
        g_host = FLAGS_mysql_host;
        g_port = FLAGS_mysql_port;
        g_user = FLAGS_mysql_user;
        g_password = FLAGS_mysql_password;
        printf("[Using running mysqld at %s:%d as user '%s']\n",
               g_host.c_str(), g_port, g_user.c_str());
        int fd = ProbeConnect();
        if (fd >= 0) {
            close(fd);
            g_mysqld_pid = -2;
        } else {
            printf("Cannot reach running mysqld at %s:%d, tests will skip\n",
                   g_host.c_str(), g_port);
        }
        return;
    }

    if (system("which " MYSQLD_BIN) != 0) {
        puts("Fail to find " MYSQLD_BIN ", connection-type tests will be skipped");
        return;
    }
    g_host = "127.0.0.1";
    g_port = FLAGS_mysql_port;
    g_user = "root";
    g_password.clear();
    const std::string datadir = TestDataDir();
    char cmd[2048];
    snprintf(cmd, sizeof(cmd), "rm -rf '%s' && mkdir -p '%s'",
             datadir.c_str(), datadir.c_str());
    if (system(cmd) != 0) {
        puts("Fail to create datadir, connection-type tests will be skipped");
        return;
    }
    snprintf(cmd, sizeof(cmd),
             MYSQLD_BIN " --initialize-insecure --datadir='%s'"
             " --log-error='%s/init.err'",
             datadir.c_str(), datadir.c_str());
    if (system(cmd) != 0) {
        puts("Fail to initialize mysqld datadir, tests will be skipped");
        snprintf(cmd, sizeof(cmd), "rm -rf '%s'", datadir.c_str());
        CHECK(0 == system(cmd));
        return;
    }
    atexit(RemoveMysqlServer);

    g_mysqld_pid = fork();
    if (g_mysqld_pid < 0) {
        puts("Fail to fork");
        exit(1);
    } else if (g_mysqld_pid == 0) {
        puts("[Starting mysqld]");
        char port_arg[32];
        snprintf(port_arg, sizeof(port_arg), "--port=%d", FLAGS_mysql_port);
        const std::string datadir_arg = "--datadir=" + datadir;
        const std::string socket_arg = "--socket=" + datadir + "/mysqld.sock";
        const std::string pidfile_arg = "--pid-file=" + datadir + "/mysqld.pid";
        const std::string logerr_arg = "--log-error=" + datadir + "/mysqld.err";
        char* const argv[] = {
            (char*)MYSQLD_BIN,
            (char*)datadir_arg.c_str(),
            (char*)port_arg,
            (char*)socket_arg.c_str(),
            (char*)pidfile_arg.c_str(),
            (char*)logerr_arg.c_str(),
            (char*)"--mysqlx=OFF",
            (char*)"--bind-address=127.0.0.1",
            NULL};
        if (execvp(MYSQLD_BIN, argv) < 0) {
            puts("Fail to run " MYSQLD_BIN);
            exit(1);
        }
    }
    for (int i = 0; i < 300; ++i) {
        int fd = ProbeConnect();
        if (fd >= 0) {
            close(fd);
            return;
        }
        usleep(100000);
    }
    puts("mysqld did not become ready, connection-type tests will be skipped");
    g_mysqld_pid = -1;
}

static int InitShortChannel(brpc::Channel* channel,
                            brpc::policy::MysqlAuthenticator** out_auth) {
    brpc::policy::MysqlAuthenticator* auth =
        new brpc::policy::MysqlAuthenticator(g_user, g_password, "", "",
                                             kCollation);
    *out_auth = auth;
    brpc::ChannelOptions options;
    options.protocol = brpc::PROTOCOL_MYSQL;
    options.connection_type = "short";  // CONNECTION_TYPE_SHORT: new conn/request
    options.auth = auth;
    options.timeout_ms = 10000;
    options.connect_timeout_ms = 5000;
    options.max_retry = 0;
    return channel->Init(g_host.c_str(), g_port, &options);
}

void SetUp() override {
        pthread_once(&g_start_once, StartServerOnce);
        if (NoServer()) {
            GTEST_SKIP() << "no mysqld available; skipping connection-type "
                            "integration test (set -mysql_use_running_server "
                            "or install mysqld)";
        }
        brpc::policy::MysqlAuthenticator* auth = NULL;
        ASSERT_EQ(0, InitShortChannel(&_channel, &auth));
        _auth.reset(auth);
    }

TEST_F(MysqlConnectionTypeTest, PreparedStatementUnderShortRePreparesAndSucceeds) {
    for (int iter = 0; iter < 5; ++iter) {
        brpc::MysqlStatementUniquePtr stmt =
            brpc::NewMysqlStatement(_channel, "SELECT ? AS v");
        ASSERT_TRUE(stmt != NULL) << "iter " << iter;
        ASSERT_EQ(1u, stmt->param_count()) << "iter " << iter;

        const int32_t bound = (int32_t)(40 + iter);
        brpc::MysqlRequest req(stmt.get());
        ASSERT_TRUE(req.AddParam(bound)) << "iter " << iter;

        brpc::MysqlResponse resp;
        brpc::Controller cntl;
        _channel.CallMethod(NULL, &cntl, &req, &resp, NULL);

        ASSERT_FALSE(cntl.Failed()) << "iter " << iter << ": " << cntl.ErrorText();
        ASSERT_GE(resp.reply_size(), 1) << "iter " << iter;
        ASSERT_FALSE(resp.reply(0).is_error())
            << "iter " << iter
            << ": mysql error: " << resp.reply(0).error().msg().as_string();
        ASSERT_TRUE(resp.reply(0).is_resultset()) << "iter " << iter;
        ASSERT_EQ(1u, resp.reply(0).row_count()) << "iter " << iter;

        const brpc::MysqlReply::Field& f = resp.reply(0).next().field(0);
        long long got = 0;
        if (f.is_sbigint())       got = f.sbigint();
        else if (f.is_bigint())   got = (long long)f.bigint();
        else if (f.is_sinteger()) got = f.sinteger();
        else if (f.is_integer())  got = (long long)f.integer();
        else if (f.is_string())   got = atoll(f.string().as_string().c_str());
        else FAIL() << "iter " << iter << ": prepared bind returned a non-integer-ish field";
        EXPECT_EQ((long long)bound, got) << "iter " << iter;
    }
}

TEST_F(MysqlConnectionTypeTest, PlainQueryUnderShortMustSucceed) {
    brpc::MysqlRequest req;
    ASSERT_TRUE(req.Query("SELECT 7 AS v"));

    brpc::MysqlResponse resp;
    brpc::Controller cntl;
    _channel.CallMethod(NULL, &cntl, &req, &resp, NULL);

    ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
    ASSERT_GE(resp.reply_size(), 1);
    ASSERT_FALSE(resp.reply(0).is_error())
        << "mysql error: " << resp.reply(0).error().msg().as_string();
    ASSERT_TRUE(resp.reply(0).is_resultset());
    ASSERT_EQ(1u, resp.reply(0).row_count());

    const brpc::MysqlReply::Field& f = resp.reply(0).next().field(0);
    long long got = 0;
    if (f.is_sbigint())       got = f.sbigint();
    else if (f.is_bigint())   got = (long long)f.bigint();
    else if (f.is_sinteger()) got = f.sinteger();
    else if (f.is_integer())  got = (long long)f.integer();
    else if (f.is_string())   got = atoll(f.string().as_string().c_str());
    else FAIL() << "SELECT 7 returned a non-integer-ish field";
    EXPECT_EQ(7, got);
}

