static bool RunPlain(brpc::Channel& channel, const std::string& sql,
                     brpc::MysqlResponse* resp, std::string* err) {
    brpc::MysqlRequest req;
    if (!req.Query(sql)) {
        if (err) *err = "build query failed: " + sql;
        return false;
    }
    brpc::Controller cntl;
    channel.CallMethod(NULL, &cntl, &req, resp, NULL);
    if (cntl.Failed()) {
        if (err) *err = "rpc failed: " + cntl.ErrorText();
        return false;
    }
    if (resp->reply_size() < 1) {
        if (err) *err = "no reply for: " + sql;
        return false;
    }
    if (resp->reply(0).is_error()) {
        const brpc::MysqlReply& r = resp->reply(0);
        if (err) {
            *err = butil::string_printf("mysql error %u: %.*s (sql=%s)",
                r.error().errcode(), (int)r.error().msg().size(),
                r.error().msg().data(), sql.c_str());
        }
        return false;
    }
    return true;
}

static bool RunInTx(brpc::Channel& channel, const brpc::MysqlTransaction* tx,
                    const std::string& sql, brpc::MysqlResponse* resp,
                    std::string* err) {
    brpc::MysqlRequest req(tx);
    if (!req.Query(sql)) {
        if (err) *err = "build query failed: " + sql;
        return false;
    }
    brpc::Controller cntl;
    channel.CallMethod(NULL, &cntl, &req, resp, NULL);
    if (cntl.Failed()) {
        if (err) *err = "rpc failed: " + cntl.ErrorText();
        return false;
    }
    if (resp->reply_size() < 1) {
        if (err) *err = "no reply for: " + sql;
        return false;
    }
    return true;
}

static int64_t ResultRowCount(const brpc::MysqlResponse& resp) {
    if (resp.reply_size() < 1) {
        return -1;
    }
    const brpc::MysqlReply& r = resp.reply(0);
    if (!r.is_resultset()) {
        return -1;
    }
    return static_cast<int64_t>(r.row_count());
}

static bool FieldToLongLong(const brpc::MysqlReply::Field& f, long long* out) {
    if (f.is_sbigint())       *out = f.sbigint();
    else if (f.is_bigint())   *out = (long long)f.bigint();
    else if (f.is_sinteger()) *out = f.sinteger();
    else if (f.is_integer())  *out = (long long)f.integer();
    else if (f.is_string())   *out = atoll(f.string().as_string().c_str());
    else return false;
    return true;
}

static int InitPooledChannel(brpc::Channel* channel,
                             brpc::policy::MysqlAuthenticator** out_auth,
                             const std::string& schema) {
    brpc::policy::MysqlAuthenticator* auth =
        new brpc::policy::MysqlAuthenticator(g_user, g_password, schema, "",
                                             kCollation);
    *out_auth = auth;
    brpc::ChannelOptions options;
    options.protocol = brpc::PROTOCOL_MYSQL;
    options.connection_type = "pooled";  // CONNECTION_TYPE_POOLED
    options.auth = auth;
    options.timeout_ms = 10000;
    options.connect_timeout_ms = 5000;
    options.max_retry = 0;
    return channel->Init(g_host.c_str(), g_port, &options);
}

void SetUp() override {
        pthread_once(&g_start_once, StartServerOnce);
        if (NoServer()) {
            GTEST_SKIP() << "no mysqld available; skipping pool-concurrency "
                            "integration test (set -mysql_use_running_server "
                            "or install mysqld)";
        }
        // Cap the pool at FIVE for the whole test.  Verified flag name:
        // src/brpc/socket.cpp:99 DEFINE_int32(max_connection_pool_size, ...).
        ASSERT_FALSE(GFLAGS_NS::SetCommandLineOption(
                         "max_connection_pool_size",
                         std::to_string(kPoolCap).c_str()).empty())
            << "failed to set gflag max_connection_pool_size";

        // Create the schema over a schema-less channel, then bind to it.
        brpc::policy::MysqlAuthenticator* setup_auth = NULL;
        ASSERT_EQ(0, InitPooledChannel(&_setup_channel, &setup_auth, ""));
        _setup_auth.reset(setup_auth);
        brpc::MysqlResponse resp;
        std::string err;
        ASSERT_TRUE(RunPlain(_setup_channel,
                             "CREATE DATABASE IF NOT EXISTS " + g_schema,
                             &resp, &err)) << err;

        brpc::policy::MysqlAuthenticator* auth = NULL;
        ASSERT_EQ(0, InitPooledChannel(&_channel, &auth, g_schema));
        _auth.reset(auth);
    }

static bool WU_TxnCommitVisible(brpc::Channel& ch, const std::string& table,
                                int iter, std::string* err) {
    const int id = 71000 + iter;
    const char* name = "aria";
    brpc::MysqlResponse resp;
    brpc::MysqlTransactionUniquePtr tx =
        brpc::NewMysqlTransaction(ch, brpc::MysqlTransactionOptions());
    if (tx == NULL) { *err = "WU1: NewMysqlTransaction NULL"; return false; }
    if (!RunInTx(ch, tx.get(),
                 butil::string_printf("INSERT INTO %s VALUES (%d, '%s')",
                                      table.c_str(), id, name),
                 &resp, err)) return false;
    if (resp.reply(0).is_error()) {
        *err = "WU1 INSERT err: " + resp.reply(0).error().msg().as_string();
        return false;
    }
    if (!tx->commit()) { *err = "WU1: commit failed"; return false; }

    // A fresh pooled connection must now see exactly our committed row.
    if (!RunPlain(ch, butil::string_printf(
                          "SELECT id, name FROM %s WHERE id=%d",
                          table.c_str(), id), &resp, err)) return false;
    if (ResultRowCount(resp) != 1) {
        *err = butil::string_printf("WU1: expected 1 visible row, got %lld",
                                    (long long)ResultRowCount(resp));
        return false;
    }
    const brpc::MysqlReply::Row& row = resp.reply(0).next();
    long long got_id = 0;
    if (!FieldToLongLong(row.field(0), &got_id) || got_id != id) {
        *err = "WU1: wrong id read back"; return false;
    }
    if (row.field(1).string().as_string() != name) {
        *err = "WU1: wrong name read back"; return false;
    }
    return true;
}

static bool WU_TxnRollbackDiscards(brpc::Channel& ch, const std::string& table,
                                   int iter, std::string* err) {
    const int id = 82000 + iter;
    brpc::MysqlResponse resp;
    brpc::MysqlTransactionUniquePtr tx =
        brpc::NewMysqlTransaction(ch, brpc::MysqlTransactionOptions());
    if (tx == NULL) { *err = "WU2: NewMysqlTransaction NULL"; return false; }
    if (!RunInTx(ch, tx.get(),
                 butil::string_printf("INSERT INTO %s VALUES (%d, 'cory')",
                                      table.c_str(), id),
                 &resp, err)) return false;
    if (resp.reply(0).is_error()) {
        *err = "WU2 INSERT err: " + resp.reply(0).error().msg().as_string();
        return false;
    }
    if (!tx->rollback()) { *err = "WU2: rollback failed"; return false; }

    // The rolled-back row must be gone on a fresh connection.
    if (!RunPlain(ch, butil::string_printf("SELECT id FROM %s WHERE id=%d",
                                           table.c_str(), id),
                  &resp, err)) return false;
    if (ResultRowCount(resp) != 0) {
        *err = butil::string_printf(
            "WU2: rolled-back insert still visible (%lld rows)",
            (long long)ResultRowCount(resp));
        return false;
    }
    return true;
}

static bool WU_TxnReadsOwnWrite(brpc::Channel& ch, const std::string& table,
                                int iter, std::string* err) {
    const int id = 93000 + iter;
    const char* name = "echo";
    brpc::MysqlResponse resp;
    brpc::MysqlTransactionUniquePtr tx =
        brpc::NewMysqlTransaction(ch, brpc::MysqlTransactionOptions());
    if (tx == NULL) { *err = "WU3: NewMysqlTransaction NULL"; return false; }
    if (!RunInTx(ch, tx.get(),
                 butil::string_printf("INSERT INTO %s VALUES (%d, '%s')",
                                      table.c_str(), id, name),
                 &resp, err)) return false;
    if (resp.reply(0).is_error()) {
        *err = "WU3 INSERT err: " + resp.reply(0).error().msg().as_string();
        return false;
    }
    // Same pinned connection: must see its own uncommitted row.
    if (!RunInTx(ch, tx.get(),
                 butil::string_printf("SELECT name FROM %s WHERE id=%d",
                                      table.c_str(), id),
                 &resp, err)) return false;
    bool ok = (ResultRowCount(resp) == 1) &&
              resp.reply(0).next().field(0).string().as_string() == name;
    // Discard the row so the per-worker table stays empty for the next pick.
    tx->rollback();
    if (!ok) { *err = "WU3: txn did not read its own uncommitted write"; }
    return ok;
}

static bool WU_PreparedBindInt(brpc::Channel& ch, const std::string& table,
                               int iter, std::string* err) {
    const int id = 64000 + iter;
    const char* name = "lyra";
    brpc::MysqlResponse resp;
    // Seed our own row (autocommit) then read it back via a prepared SELECT.
    if (!RunPlain(ch, butil::string_printf("INSERT INTO %s VALUES (%d, '%s')",
                                           table.c_str(), id, name),
                  &resp, err)) return false;

    brpc::MysqlStatementUniquePtr stmt = brpc::NewMysqlStatement(
        ch, butil::string_printf("SELECT name FROM %s WHERE id=?",
                                 table.c_str()));
    if (stmt == NULL) { *err = "WU4: NewMysqlStatement NULL"; return false; }
    if (stmt->param_count() != 1u) { *err = "WU4: param_count != 1"; return false; }

    brpc::MysqlRequest req(stmt.get());
    if (!req.AddParam((int32_t)id)) { *err = "WU4: AddParam failed"; return false; }
    brpc::Controller cntl;
    ch.CallMethod(NULL, &cntl, &req, &resp, NULL);
    if (cntl.Failed()) { *err = "WU4 rpc: " + cntl.ErrorText(); return false; }
    if (resp.reply_size() < 1 || !resp.reply(0).is_resultset()) {
        *err = "WU4: not a resultset"; return false;
    }
    if (resp.reply(0).row_count() != 1u) {
        *err = "WU4: expected exactly 1 row"; return false;
    }
    bool ok = resp.reply(0).next().field(0).string().as_string() == name;
    // Clean our seeded row so subsequent picks on this table stay exact.
    RunPlain(ch, butil::string_printf("DELETE FROM %s WHERE id=%d",
                                      table.c_str(), id), &resp, err);
    if (!ok) { *err = "WU4: prepared bind returned wrong/cross-talked name"; }
    return ok;
}

static bool WU_PreparedArithmetic(brpc::Channel& ch, int worker, int iter,
                                  std::string* err) {
    const int32_t a = 1000 + worker;
    const int32_t b = 7 + iter;
    const long long expect = (long long)a + b;
    brpc::MysqlStatementUniquePtr stmt =
        brpc::NewMysqlStatement(ch, "SELECT CAST(? AS SIGNED) + CAST(? AS SIGNED)");
    if (stmt == NULL) { *err = "WU5: NewMysqlStatement NULL"; return false; }
    if (stmt->param_count() != 2u) { *err = "WU5: param_count != 2"; return false; }

    brpc::MysqlRequest req(stmt.get());
    if (!req.AddParam(a) || !req.AddParam(b)) {
        *err = "WU5: AddParam failed"; return false;
    }
    brpc::MysqlResponse resp;
    brpc::Controller cntl;
    ch.CallMethod(NULL, &cntl, &req, &resp, NULL);
    if (cntl.Failed()) { *err = "WU5 rpc: " + cntl.ErrorText(); return false; }
    if (resp.reply_size() < 1 || !resp.reply(0).is_resultset() ||
        resp.reply(0).row_count() != 1u) {
        *err = "WU5: bad resultset"; return false;
    }
    long long got = 0;
    if (!FieldToLongLong(resp.reply(0).next().field(0), &got) || got != expect) {
        *err = butil::string_printf("WU5: ?+? wrong (got %lld want %lld)",
                                    got, expect);
        return false;
    }
    return true;
}

void* MixWorker(void* p) {
    MixWorkerArgs* a = static_cast<MixWorkerArgs*>(p);
    a->error.clear();
    a->completed = 0;
    for (int iter = 0; iter < kIterationsPerWorker; ++iter) {
        // Rotate through the five work units; offset by worker so different
        // workers run different units at the same instant.
        const int pick = (a->worker_id + iter) % 5;
        std::string err;
        bool ok = false;
        switch (pick) {
            case 0: ok = WU_TxnCommitVisible(*a->channel, a->table, iter, &err); break;
            case 1: ok = WU_TxnRollbackDiscards(*a->channel, a->table, iter, &err); break;
            case 2: ok = WU_TxnReadsOwnWrite(*a->channel, a->table, iter, &err); break;
            case 3: ok = WU_PreparedBindInt(*a->channel, a->table, iter, &err); break;
            default: ok = WU_PreparedArithmetic(*a->channel, a->worker_id, iter, &err); break;
        }
        if (!ok) {
            a->error = butil::string_printf("worker %d iter %d pick %d: %s",
                                            a->worker_id, iter, pick, err.c_str());
            return NULL;
        }
        ++a->completed;
    }
    return NULL;
}

TEST_F(MysqlPoolConcurrencyTest, ManyWorkersMixedScenarios) {
    std::string err;
    std::vector<MixWorkerArgs> args(kWorkers);
    // One scratch table per worker so concurrent workers never share rows.
    for (int w = 0; w < kWorkers; ++w) {
        args[w].channel = &_channel;
        args[w].worker_id = w;
        args[w].table = butil::string_printf("pool_conc_w%d", w);
        brpc::MysqlResponse resp;
        ASSERT_TRUE(RunPlain(_channel, "DROP TABLE IF EXISTS " + args[w].table,
                             &resp, &err)) << err;
        ASSERT_TRUE(RunPlain(_channel,
                             "CREATE TABLE " + args[w].table +
                                 " (id INT PRIMARY KEY, name VARCHAR(32)) "
                                 "ENGINE=InnoDB",
                             &resp, &err)) << err;
    }

    std::vector<bthread_t> threads(kWorkers);
    for (int w = 0; w < kWorkers; ++w) {
        ASSERT_EQ(0, bthread_start_background(&threads[w], NULL, MixWorker,
                                              &args[w]));
    }
    for (int w = 0; w < kWorkers; ++w) {
        bthread_join(threads[w], NULL);
    }

    for (int w = 0; w < kWorkers; ++w) {
        EXPECT_TRUE(args[w].error.empty()) << args[w].error;
        EXPECT_EQ(kIterationsPerWorker, args[w].completed)
            << "worker " << w << " did not finish all iterations";
    }

    // Cleanup.
    for (int w = 0; w < kWorkers; ++w) {
        brpc::MysqlResponse resp;
        RunPlain(_channel, "DROP TABLE IF EXISTS " + args[w].table, &resp, &err);
    }
}

void* AffinityWorker(void* p) {
    AffinityWorkerArgs* a = static_cast<AffinityWorkerArgs*>(p);
    a->error.clear();
    a->socket_id = 0;
    a->row_count = -1;
    a->read_value = -1;
    a->committed = false;

    brpc::MysqlTransactionUniquePtr tx =
        brpc::NewMysqlTransaction(*a->channel, brpc::MysqlTransactionOptions());
    if (tx == NULL) { a->error = "NewMysqlTransaction NULL"; return NULL; }
    a->socket_id = tx->GetSocketId();

    brpc::MysqlResponse resp;
    if (!RunInTx(*a->channel, tx.get(),
                 butil::string_printf("INSERT INTO %s VALUES (%d)",
                                      a->table.c_str(), a->id),
                 &resp, &a->error)) return NULL;
    if (resp.reply(0).is_error()) {
        a->error = "INSERT err: " + resp.reply(0).error().msg().as_string();
        return NULL;
    }
    // Read inside the txn: must see exactly our own row (per-worker table).
    if (!RunInTx(*a->channel, tx.get(),
                 butil::string_printf("SELECT v FROM %s", a->table.c_str()),
                 &resp, &a->error)) return NULL;
    a->row_count = ResultRowCount(resp);
    if (a->row_count == 1) {
        long long v = 0;
        if (FieldToLongLong(resp.reply(0).next().field(0), &v)) {
            a->read_value = (int)v;
        }
    }
    a->committed = tx->commit();
    if (!a->committed) a->error = "commit failed";
    return NULL;
}

TEST_F(MysqlPoolConcurrencyTest, TwoTransactionsHoldDifferentPinnedSockets) {
    const std::string t0 = "pool_conc_affinity_a";
    const std::string t1 = "pool_conc_affinity_b";
    std::string err;
    brpc::MysqlResponse resp;
    for (const std::string& t : {t0, t1}) {
        ASSERT_TRUE(RunPlain(_channel, "DROP TABLE IF EXISTS " + t, &resp, &err)) << err;
        ASSERT_TRUE(RunPlain(_channel,
                             "CREATE TABLE " + t + " (v INT) ENGINE=InnoDB",
                             &resp, &err)) << err;
    }

    for (int iter = 0; iter < kIterationsPerWorker; ++iter) {
        ASSERT_TRUE(RunPlain(_channel, "TRUNCATE TABLE " + t0, &resp, &err)) << err;
        ASSERT_TRUE(RunPlain(_channel, "TRUNCATE TABLE " + t1, &resp, &err)) << err;

        AffinityWorkerArgs a0{&_channel, t0, 30100 + iter, 0, -1, -1, false, ""};
        AffinityWorkerArgs a1{&_channel, t1, 30900 + iter, 0, -1, -1, false, ""};

        bthread_t b0, b1;
        ASSERT_EQ(0, bthread_start_background(&b0, NULL, AffinityWorker, &a0));
        ASSERT_EQ(0, bthread_start_background(&b1, NULL, AffinityWorker, &a1));
        bthread_join(b0, NULL);
        bthread_join(b1, NULL);

        ASSERT_TRUE(a0.error.empty()) << "iter " << iter << " txn0: " << a0.error;
        ASSERT_TRUE(a1.error.empty()) << "iter " << iter << " txn1: " << a1.error;

        // Each saw exactly its own single row -- no cross-talk.
        EXPECT_EQ(1, a0.row_count) << "iter " << iter;
        EXPECT_EQ(1, a1.row_count) << "iter " << iter;
        EXPECT_EQ(a0.id, a0.read_value) << "iter " << iter;
        EXPECT_EQ(a1.id, a1.read_value) << "iter " << iter;
        EXPECT_TRUE(a0.committed) << "iter " << iter;
        EXPECT_TRUE(a1.committed) << "iter " << iter;

        // Connection affinity: two concurrent txns hold DIFFERENT pinned sockets.
        EXPECT_NE(0u, a0.socket_id) << "iter " << iter;
        EXPECT_NE(0u, a1.socket_id) << "iter " << iter;
        EXPECT_NE(a0.socket_id, a1.socket_id)
            << "iter " << iter
            << ": two concurrent transactions shared a pooled socket! sid0="
            << a0.socket_id << " sid1=" << a1.socket_id;
    }

    for (const std::string& t : {t0, t1}) {
        RunPlain(_channel, "DROP TABLE IF EXISTS " + t, &resp, &err);
    }
}

void* PreparedWorker(void* p) {
    PreparedWorkerArgs* a = static_cast<PreparedWorkerArgs*>(p);
    a->ok = true;
    a->error.clear();
    for (int k = 0; k < 4; ++k) {
        std::string err;
        if (!WU_PreparedArithmetic(*a->channel, a->base, k, &err)) {
            a->ok = false;
            a->error = err;
            return NULL;
        }
    }
    return NULL;
}

TEST_F(MysqlPoolConcurrencyTest, TransactionPlusPreparedInParallel) {
    const std::string t = "pool_conc_txn_stmt";
    std::string err;
    brpc::MysqlResponse resp;
    ASSERT_TRUE(RunPlain(_channel, "DROP TABLE IF EXISTS " + t, &resp, &err)) << err;
    ASSERT_TRUE(RunPlain(_channel, "CREATE TABLE " + t + " (v INT) ENGINE=InnoDB",
                         &resp, &err)) << err;

    for (int iter = 0; iter < kIterationsPerWorker; ++iter) {
        ASSERT_TRUE(RunPlain(_channel, "TRUNCATE TABLE " + t, &resp, &err)) << err;

        AffinityWorkerArgs ta{&_channel, t, 50500 + iter, 0, -1, -1, false, ""};
        PreparedWorkerArgs pa{&_channel, 200 + iter, true, ""};

        bthread_t bt, bp;
        ASSERT_EQ(0, bthread_start_background(&bt, NULL, AffinityWorker, &ta));
        ASSERT_EQ(0, bthread_start_background(&bp, NULL, PreparedWorker, &pa));
        bthread_join(bt, NULL);
        bthread_join(bp, NULL);

        ASSERT_TRUE(ta.error.empty()) << "iter " << iter << " txn: " << ta.error;
        ASSERT_TRUE(pa.ok) << "iter " << iter << " prepared: " << pa.error;

        // Transaction result intact and isolated.
        EXPECT_EQ(1, ta.row_count) << "iter " << iter;
        EXPECT_EQ(ta.id, ta.read_value) << "iter " << iter;
        EXPECT_TRUE(ta.committed) << "iter " << iter;
        EXPECT_NE(0u, ta.socket_id) << "iter " << iter;
    }

    RunPlain(_channel, "DROP TABLE IF EXISTS " + t, &resp, &err);
}

void* PinnedTxnWorker(void* p) {
    PinnedTxnWorkerArgs* a = static_cast<PinnedTxnWorkerArgs*>(p);
    a->error.clear();
    a->socket_ids.clear();

    brpc::MysqlTransactionUniquePtr tx =
        brpc::NewMysqlTransaction(*a->channel, brpc::MysqlTransactionOptions());
    if (tx == NULL) { a->error = "NewMysqlTransaction NULL"; return NULL; }

    brpc::MysqlResponse resp;

    // Statement 1: INSERT our own row.
    a->socket_ids.push_back(tx->GetSocketId());
    if (!RunInTx(*a->channel, tx.get(),
                 butil::string_printf("INSERT INTO %s VALUES (%d, 'nova')",
                                      a->table.c_str(), a->id),
                 &resp, &a->error)) return NULL;
    if (resp.reply(0).is_error()) {
        a->error = "INSERT err: " + resp.reply(0).error().msg().as_string();
        return NULL;
    }

    // Statement 2: SELECT our own (uncommitted) row back.
    a->socket_ids.push_back(tx->GetSocketId());
    if (!RunInTx(*a->channel, tx.get(),
                 butil::string_printf("SELECT name FROM %s WHERE id=%d",
                                      a->table.c_str(), a->id),
                 &resp, &a->error)) return NULL;
    if (ResultRowCount(resp) != 1 ||
        resp.reply(0).next().field(0).string().as_string() != "nova") {
        a->error = "SELECT-own-row did not read back its own write";
        return NULL;
    }

    // Statement 3: UPDATE our own row.
    a->socket_ids.push_back(tx->GetSocketId());
    if (!RunInTx(*a->channel, tx.get(),
                 butil::string_printf("UPDATE %s SET name='zephyr' WHERE id=%d",
                                      a->table.c_str(), a->id),
                 &resp, &a->error)) return NULL;
    if (resp.reply(0).is_error()) {
        a->error = "UPDATE err: " + resp.reply(0).error().msg().as_string();
        return NULL;
    }

    // Statement 4: SELECT the updated value back.
    a->socket_ids.push_back(tx->GetSocketId());
    if (!RunInTx(*a->channel, tx.get(),
                 butil::string_printf("SELECT name FROM %s WHERE id=%d",
                                      a->table.c_str(), a->id),
                 &resp, &a->error)) return NULL;
    if (ResultRowCount(resp) != 1 ||
        resp.reply(0).next().field(0).string().as_string() != "zephyr") {
        a->error = "SELECT after UPDATE saw wrong value";
        return NULL;
    }

    // Discard so the per-worker table is empty for the next outer-loop pass.
    if (!tx->rollback()) { a->error = "rollback failed"; return NULL; }
    return NULL;
}

TEST_F(MysqlPoolConcurrencyTest, ConcurrentTxnsStayPinned) {
    const int kTxns = 8;
    SetPoolCap(4);  // SMALL vs kTxns=8: contend + force new connections.

    std::string err;
    brpc::MysqlResponse resp;
    std::vector<std::string> tables(kTxns);
    for (int w = 0; w < kTxns; ++w) {
        tables[w] = butil::string_printf("pool_conc_pin_w%d", w);
        ASSERT_TRUE(RunPlain(_channel, "DROP TABLE IF EXISTS " + tables[w],
                             &resp, &err)) << err;
        ASSERT_TRUE(RunPlain(_channel,
                             "CREATE TABLE " + tables[w] +
                                 " (id INT PRIMARY KEY, name VARCHAR(32)) "
                                 "ENGINE=InnoDB",
                             &resp, &err)) << err;
    }

    for (int loop = 0; loop < 10; ++loop) {
        std::vector<PinnedTxnWorkerArgs> args(kTxns);
        for (int w = 0; w < kTxns; ++w) {
            args[w].channel = &_channel;
            args[w].table = tables[w];
            // Unique per worker AND per loop so rows never collide.
            args[w].id = 120000 + loop * 100 + w;
        }

        std::vector<bthread_t> threads(kTxns);
        for (int w = 0; w < kTxns; ++w) {
            ASSERT_EQ(0, bthread_start_background(&threads[w], NULL,
                                                  PinnedTxnWorker, &args[w]));
        }
        for (int w = 0; w < kTxns; ++w) {
            bthread_join(threads[w], NULL);
        }

        // No worker errored.
        for (int w = 0; w < kTxns; ++w) {
            ASSERT_TRUE(args[w].error.empty())
                << "loop " << loop << " txn " << w << ": " << args[w].error;
            ASSERT_EQ(4u, args[w].socket_ids.size()) << "loop " << loop;
        }

        // INTRA-txn pinning: one constant non-zero SocketId per transaction.
        std::vector<brpc::SocketId> live(kTxns);
        for (int w = 0; w < kTxns; ++w) {
            const brpc::SocketId sid = args[w].socket_ids[0];
            EXPECT_NE(0u, sid) << "loop " << loop << " txn " << w;
            for (size_t s = 1; s < args[w].socket_ids.size(); ++s) {
                EXPECT_EQ(sid, args[w].socket_ids[s])
                    << "loop " << loop << " txn " << w << " stmt " << s
                    << ": transaction was NOT pinned to one connection";
            }
            live[w] = sid;
        }

        // INTER-txn isolation: all live (simultaneously-open) SocketIds distinct.
        for (int i = 0; i < kTxns; ++i) {
            for (int j = i + 1; j < kTxns; ++j) {
                EXPECT_NE(live[i], live[j])
                    << "loop " << loop << ": txns " << i << " and " << j
                    << " shared a pooled connection (sid=" << live[i] << ")";
            }
        }
    }

    for (int w = 0; w < kTxns; ++w) {
        RunPlain(_channel, "DROP TABLE IF EXISTS " + tables[w], &resp, &err);
    }
}

void* AbortWorker(void* p) {
    AbortWorkerArgs* a = static_cast<AbortWorkerArgs*>(p);
    a->error.clear();
    {
        brpc::MysqlTransactionUniquePtr tx = brpc::NewMysqlTransaction(
            *a->channel, brpc::MysqlTransactionOptions());
        if (tx == NULL) { a->error = "NewMysqlTransaction NULL"; return NULL; }

        brpc::MysqlResponse resp;
        if (!RunInTx(*a->channel, tx.get(),
                     butil::string_printf("INSERT INTO %s VALUES (%d, 'quill')",
                                          a->table.c_str(), a->id),
                     &resp, &a->error)) return NULL;
        if (resp.reply(0).is_error()) {
            a->error = "INSERT err: " + resp.reply(0).error().msg().as_string();
            return NULL;
        }
        if (a->mode == 0) {
            if (!tx->rollback()) { a->error = "explicit rollback failed"; return NULL; }
        }
        // mode 1: fall off the end of this scope -> tx dtor auto-rollbacks.
    }
    return NULL;
}

TEST_F(MysqlPoolConcurrencyTest, ConcurrentTxnAbortAndAutoRollback) {
    const int kWorkersB = 8;
    SetPoolCap(4);  // SMALL vs 8 workers: contend + force new connections.

    const std::string t = "pool_conc_abort";
    std::string err;
    brpc::MysqlResponse resp;
    ASSERT_TRUE(RunPlain(_channel, "DROP TABLE IF EXISTS " + t, &resp, &err)) << err;
    ASSERT_TRUE(RunPlain(_channel,
                         "CREATE TABLE " + t +
                             " (id INT PRIMARY KEY, name VARCHAR(32)) "
                             "ENGINE=InnoDB",
                         &resp, &err)) << err;

    for (int loop = 0; loop < 6; ++loop) {
        std::vector<AbortWorkerArgs> args(kWorkersB);
        for (int w = 0; w < kWorkersB; ++w) {
            args[w].channel = &_channel;
            args[w].table = t;
            args[w].id = 130000 + loop * 100 + w;  // unique per loop+worker
            args[w].mode = w % 2;  // half explicit rollback, half dtor rollback
        }

        std::vector<bthread_t> threads(kWorkersB);
        for (int w = 0; w < kWorkersB; ++w) {
            ASSERT_EQ(0, bthread_start_background(&threads[w], NULL,
                                                  AbortWorker, &args[w]));
        }
        for (int w = 0; w < kWorkersB; ++w) {
            bthread_join(threads[w], NULL);
        }

        for (int w = 0; w < kWorkersB; ++w) {
            EXPECT_TRUE(args[w].error.empty())
                << "loop " << loop << " worker " << w << " (mode "
                << args[w].mode << "): " << args[w].error;
        }

        // Effects discarded: not a single aborted insert is visible from a
        // fresh (non-tx) pooled connection.
        ASSERT_TRUE(RunPlain(_channel,
                             "SELECT COUNT(*) FROM " + t, &resp, &err)) << err;
        long long visible = -1;
        ASSERT_EQ(1, ResultRowCount(resp)) << "loop " << loop;
        ASSERT_TRUE(FieldToLongLong(resp.reply(0).next().field(0), &visible));
        EXPECT_EQ(0, visible)
            << "loop " << loop << ": " << visible
            << " aborted/dropped insert(s) leaked into the table";
    }

    // Channel still healthy: a final simple SELECT on a fresh pooled request
    // succeeds -> the reserved connections were returned to the pool cleanly.
    ASSERT_TRUE(RunPlain(_channel, "SELECT 1", &resp, &err)) << err;
    EXPECT_EQ(1, ResultRowCount(resp));

    RunPlain(_channel, "DROP TABLE IF EXISTS " + t, &resp, &err);
}

void* ReserveWorker(void* p) {
    ReserveWorkerArgs* a = static_cast<ReserveWorkerArgs*>(p);
    a->error.clear();
    // Open a few short transactions in series; each pulls a pooled connection
    // out (reserve) and returns it (rollback), churning which sockets are in
    // the pool while S is being executed concurrently.
    for (int k = 0; k < 8; ++k) {
        brpc::MysqlTransactionUniquePtr tx = brpc::NewMysqlTransaction(
            *a->channel, brpc::MysqlTransactionOptions());
        if (tx == NULL) { a->error = "reserve: NewMysqlTransaction NULL"; return NULL; }
        brpc::MysqlResponse resp;
        if (!RunInTx(*a->channel, tx.get(), "SELECT 1", &resp, &a->error)) return NULL;
        if (!tx->rollback()) { a->error = "reserve: rollback failed"; return NULL; }
    }
    return NULL;
}

void* StmtExecWorker(void* p) {
    StmtExecWorkerArgs* a = static_cast<StmtExecWorkerArgs*>(p);
    a->error.clear();
    for (int k = 0; k < 12; ++k) {
        const int32_t v = a->base + k;
        brpc::MysqlRequest req(a->stmt);
        if (!req.AddParam(v)) { a->error = "AddParam failed"; return NULL; }
        brpc::MysqlResponse resp;
        brpc::Controller cntl;
        a->channel->CallMethod(NULL, &cntl, &req, &resp, NULL);
        if (cntl.Failed()) { a->error = "rpc: " + cntl.ErrorText(); return NULL; }
        if (resp.reply_size() < 1 || !resp.reply(0).is_resultset() ||
            resp.reply(0).row_count() != 1u) {
            a->error = "bad resultset for S"; return NULL;
        }
        long long got = 0;
        if (!FieldToLongLong(resp.reply(0).next().field(0), &got) || got != v) {
            a->error = butil::string_printf(
                "S returned wrong value (got %lld want %d)", got, v);
            return NULL;
        }
    }
    return NULL;
}

TEST_F(MysqlPoolConcurrencyTest, PreparedRePreparesWhenConnectionStolen) {
    SetPoolCap(2);  // tiny pool: 2 sockets, easy to "steal" via reserving txns.

    std::string err;
    brpc::MysqlResponse resp;

    brpc::MysqlStatementUniquePtr S =
        brpc::NewMysqlStatement(_channel, "SELECT CAST(? AS SIGNED) AS v");
    ASSERT_TRUE(S != NULL);
    ASSERT_EQ(1u, S->param_count());

    // Execute S once to cache its stmt_id on whatever connection it lands on.
    {
        brpc::MysqlRequest req(S.get());
        ASSERT_TRUE(req.AddParam((int32_t)140000));
        brpc::Controller cntl;
        _channel.CallMethod(NULL, &cntl, &req, &resp, NULL);
        ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
        ASSERT_TRUE(resp.reply_size() >= 1 && resp.reply(0).is_resultset());
        long long got = 0;
        ASSERT_TRUE(FieldToLongLong(resp.reply(0).next().field(0), &got));
        ASSERT_EQ(140000, got);
    }

    const int kExecutors = 4;
    const int kReservers = 3;
    for (int loop = 0; loop < 30; ++loop) {
        std::vector<StmtExecWorkerArgs> exec_args(kExecutors);
        std::vector<ReserveWorkerArgs> res_args(kReservers);
        std::vector<bthread_t> exec_threads(kExecutors);
        std::vector<bthread_t> res_threads(kReservers);

        for (int w = 0; w < kReservers; ++w) {
            res_args[w].channel = &_channel;
            ASSERT_EQ(0, bthread_start_background(&res_threads[w], NULL,
                                                  ReserveWorker, &res_args[w]));
        }
        for (int w = 0; w < kExecutors; ++w) {
            exec_args[w].channel = &_channel;
            exec_args[w].stmt = S.get();
            // Unique param ranges per worker+loop so a wrong value is unambiguous.
            exec_args[w].base = 141000 + loop * 1000 + w * 100;
            ASSERT_EQ(0, bthread_start_background(&exec_threads[w], NULL,
                                                  StmtExecWorker, &exec_args[w]));
        }
        for (int w = 0; w < kReservers; ++w) {
            bthread_join(res_threads[w], NULL);
        }
        for (int w = 0; w < kExecutors; ++w) {
            bthread_join(exec_threads[w], NULL);
        }

        for (int w = 0; w < kReservers; ++w) {
            EXPECT_TRUE(res_args[w].error.empty())
                << "loop " << loop << " reserver " << w << ": " << res_args[w].error;
        }
        for (int w = 0; w < kExecutors; ++w) {
            EXPECT_TRUE(exec_args[w].error.empty())
                << "loop " << loop << " executor " << w << ": " << exec_args[w].error;
        }
    }
}

static std::string TestDataDir() {
    char cwd[1024];
    if (getcwd(cwd, sizeof(cwd)) == NULL) {
        return std::string("/tmp/mysql_ps_data_for_test");
    }
    return std::string(cwd) + "/mysql_ps_data_for_test";
}

static void RemoveMysqlServer() {
    if (g_mysqld_pid > 0) {
        puts("[Stopping mysqld]");
        char cmd[1280];
        snprintf(cmd, sizeof(cmd), "kill %d", g_mysqld_pid);
        CHECK(0 == system(cmd));
        usleep(500000);
        snprintf(cmd, sizeof(cmd), "rm -rf '%s'", TestDataDir().c_str());
        CHECK(0 == system(cmd));
    }
}

static int ProbeConnect() {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(static_cast<uint16_t>(g_port));
    addr.sin_addr.s_addr = inet_addr(g_host.c_str());
    if (connect(fd, (struct sockaddr*)&addr, sizeof(addr)) != 0) {
        close(fd);
        return -1;
    }
    return fd;
}

static void StartServerOnce() {
    if (FLAGS_mysql_use_running_server) {
        g_host = FLAGS_mysql_host;
        g_port = FLAGS_mysql_port;
        g_user = FLAGS_mysql_user;
        g_password = FLAGS_mysql_password;
        g_schema = FLAGS_mysql_schema;
        printf("[Using running mysqld at %s:%d as user '%s', schema '%s']\n",
               g_host.c_str(), g_port, g_user.c_str(), g_schema.c_str());
        int fd = ProbeConnect();
        if (fd >= 0) {
            close(fd);
            g_mysqld_pid = -2;
            // We create the seed schema/table lazily through the channel in
            // the fixture (SetUp) so it works even without the mysql CLI.
        } else {
            printf("Cannot reach running mysqld at %s:%d, tests will skip\n",
                   g_host.c_str(), g_port);
        }
        return;
    }

    if (system("which " MYSQLD_BIN) != 0) {
        puts("Fail to find " MYSQLD_BIN ", tests will be skipped");
        return;
    }
    g_host = "127.0.0.1";
    g_port = FLAGS_mysql_port;
    g_user = "root";
    g_password.clear();
    g_schema = FLAGS_mysql_schema;
    const std::string datadir = TestDataDir();
    char cmd[2048];
    snprintf(cmd, sizeof(cmd), "rm -rf '%s' && mkdir -p '%s'",
             datadir.c_str(), datadir.c_str());
    if (system(cmd) != 0) {
        puts("Fail to create datadir, tests will be skipped");
        return;
    }
    snprintf(cmd, sizeof(cmd),
             MYSQLD_BIN " --initialize-insecure --datadir='%s'"
             " --log-error='%s/init.err'",
             datadir.c_str(), datadir.c_str());
    if (system(cmd) != 0) {
        puts("Fail to initialize mysqld datadir, tests will be skipped");
        snprintf(cmd, sizeof(cmd), "rm -rf '%s'", datadir.c_str());
        CHECK(0 == system(cmd));
        return;
    }
    atexit(RemoveMysqlServer);

    g_mysqld_pid = fork();
    if (g_mysqld_pid < 0) {
        puts("Fail to fork");
        exit(1);
    } else if (g_mysqld_pid == 0) {
        puts("[Starting mysqld]");
        char port_arg[32];
        snprintf(port_arg, sizeof(port_arg), "--port=%d", FLAGS_mysql_port);
        const std::string datadir_arg = "--datadir=" + datadir;
        const std::string socket_arg = "--socket=" + datadir + "/mysqld.sock";
        const std::string pidfile_arg = "--pid-file=" + datadir + "/mysqld.pid";
        const std::string logerr_arg = "--log-error=" + datadir + "/mysqld.err";
        char* const argv[] = {(char*)MYSQLD_BIN,
                              (char*)datadir_arg.c_str(),
                              (char*)port_arg,
                              (char*)socket_arg.c_str(),
                              (char*)pidfile_arg.c_str(),
                              (char*)logerr_arg.c_str(),
                              (char*)"--mysqlx=OFF",
                              (char*)"--bind-address=127.0.0.1",
                              NULL};
        if (execvp(MYSQLD_BIN, argv) < 0) {
            puts("Fail to run " MYSQLD_BIN);
            exit(1);
        }
    }
    for (int i = 0; i < 300; ++i) {
        int fd = ProbeConnect();
        if (fd >= 0) {
            close(fd);
            // Create the seed schema + table over the unix socket (root has
            // an empty password there).  Best-effort: if the mysql CLI is
            // missing we fall back to creating it through the channel in
            // SetUp (DDL also works over the prepared-statement channel via
            // a plain Query reply, but the CLI keeps the fixture simple).
            char create[2048];
            snprintf(create, sizeof(create),
                     "mysql --socket='%s/mysqld.sock' -u root -e \""
                     "CREATE DATABASE IF NOT EXISTS %s; \" 2>/dev/null",
                     datadir.c_str(), g_schema.c_str());
            (void)system(create);  // schema creation is also retried lazily
            return;
        }
        usleep(100000);
    }
    puts("mysqld did not become ready, tests will be skipped");
    g_mysqld_pid = -1;
}

static int InitChannel(brpc::Channel* channel) {
    brpc::ChannelOptions options;
    options.protocol = brpc::PROTOCOL_MYSQL;
    options.connection_type = "pooled";
    options.timeout_ms = 5000;
    options.connect_timeout_ms = 5000;
    options.max_retry = 0;
    options.auth = new brpc::policy::MysqlAuthenticator(
        g_user, g_password, g_schema, "", kCollation);
    return channel->Init(g_host.c_str(), g_port, &options);
}

static bool RunPlainQuery(brpc::Channel* channel, const std::string& sql) {
    brpc::MysqlRequest request;
    if (!request.Query(sql)) {
        return false;
    }
    brpc::MysqlResponse response;
    brpc::Controller cntl;
    channel->CallMethod(NULL, &cntl, &request, &response, NULL);
    if (cntl.Failed()) {
        return false;
    }
    if (response.reply_size() < 1) {
        return false;
    }
    return !response.reply(0).is_error();
}

void SetUp() override {
        pthread_once(&g_start_once, StartServerOnce);
        if (NoServer()) {
            return;
        }
        // Ensure the schema + the shared seed table exist exactly once.
        // (Idempotent CREATE IF NOT EXISTS, so re-running is harmless.)
        if (!g_schema_ready) {
            brpc::Channel setup;
            // Connect with an empty schema first so CREATE DATABASE works
            // even if g_schema does not yet exist on a running server.
            brpc::ChannelOptions options;
            options.protocol = brpc::PROTOCOL_MYSQL;
            options.connection_type = "pooled";
            options.timeout_ms = 5000;
            options.connect_timeout_ms = 5000;
            options.auth = new brpc::policy::MysqlAuthenticator(
                g_user, g_password, "", "", kCollation);
            if (setup.Init(g_host.c_str(), g_port, &options) == 0) {
                RunPlainQuery(&setup, "CREATE DATABASE IF NOT EXISTS " + g_schema);
            }
            // Now (re)connect bound to the schema and create the seed table.
            brpc::Channel ch;
            if (InitChannel(&ch) == 0) {
                RunPlainQuery(&ch, "DROP TABLE IF EXISTS ps_people");
                RunPlainQuery(&ch,
                    "CREATE TABLE ps_people("
                    "id INT, name VARCHAR(50), score BIGINT)");
                RunPlainQuery(&ch,
                    "INSERT INTO ps_people VALUES"
                    "(417,'maple',9100),(528,'cobalt',9200),(639,NULL,9300)");
                g_schema_ready = true;
            }
        }
        ASSERT_EQ(0, InitChannel(&channel_)) << "channel init failed";
    }

TEST_F(MysqlPreparedTest, ParamCountsAndNoParamSelect) {
    SKIP_IF_NO_SERVER();

    // param_count must reflect the placeholders in each shape.
    {
        PREPARE_OR_FAIL(s, "INSERT INTO ps_people VALUES(?, ?, ?)");
        EXPECT_EQ(3u, s->param_count());
    }
    {
        PREPARE_OR_FAIL(s, "SELECT * FROM ps_people WHERE id=? AND name=?");
        EXPECT_EQ(2u, s->param_count());
    }
    {
        PREPARE_OR_FAIL(s, "DELETE FROM ps_people WHERE id=417");
        EXPECT_EQ(0u, s->param_count());
    }
    {
        PREPARE_OR_FAIL(s, "DELETE FROM ps_people WHERE id=?");
        EXPECT_EQ(1u, s->param_count());
    }

    // A no-parameter SELECT returns a result set covering all three seed rows.
    PREPARE_OR_FAIL(s, "SELECT id, name, score FROM ps_people ORDER BY id");
    EXPECT_EQ(0u, s->param_count());
    brpc::MysqlRequest request(s.get());
    brpc::MysqlResponse response;
    brpc::Controller cntl;
    channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
    ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
    ASSERT_GE(response.reply_size(), 1u);
    const brpc::MysqlReply& r = response.reply(0);
    ASSERT_TRUE(r.is_resultset()) << "expected a result set, got: " << r;
    EXPECT_EQ(3u, r.column_count());
    EXPECT_EQ(3u, r.row_count());
}

TEST_F(MysqlPreparedTest, BindAndExecuteIntStringAndArithmetic) {
    SKIP_IF_NO_SERVER();

    // (a) bind one INT param -> matching row's name.
    {
        PREPARE_OR_FAIL(s, "SELECT name FROM ps_people WHERE id=?");
        ASSERT_EQ(1u, s->param_count());
        brpc::MysqlRequest request(s.get());
        ASSERT_TRUE(request.AddParam((int32_t)417));
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
        ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
        ASSERT_GE(response.reply_size(), 1u);
        const brpc::MysqlReply& r = response.reply(0);
        ASSERT_TRUE(r.is_resultset()) << r;
        ASSERT_EQ(1u, r.row_count());
        const brpc::MysqlReply::Field& f = r.next().field(0);
        ASSERT_TRUE(f.is_string());
        EXPECT_EQ("maple", f.string().as_string());
    }

    // (b) bind one STRING param -> matching row's id.
    {
        PREPARE_OR_FAIL(s, "SELECT id FROM ps_people WHERE name=?");
        ASSERT_EQ(1u, s->param_count());
        brpc::MysqlRequest request(s.get());
        ASSERT_TRUE(request.AddParam(butil::StringPiece("cobalt")));
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
        ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
        ASSERT_GE(response.reply_size(), 1u);
        const brpc::MysqlReply& r = response.reply(0);
        ASSERT_TRUE(r.is_resultset()) << r;
        ASSERT_EQ(1u, r.row_count());
        const brpc::MysqlReply::Field& f = r.next().field(0);
        // id is INT; brpc surfaces a signed INT column as sinteger.
        ASSERT_TRUE(f.is_sinteger() || f.is_integer())
            << "expected an integer id field";
        if (f.is_sinteger()) {
            EXPECT_EQ(528, f.sinteger());
        } else {
            EXPECT_EQ(528u, f.integer());
        }
    }

    // (c) two INT params in an arithmetic expression -> their sum.
    {
        PREPARE_OR_FAIL(s, "SELECT CAST(? AS SIGNED) + CAST(? AS SIGNED)");
        ASSERT_EQ(2u, s->param_count());
        brpc::MysqlRequest request(s.get());
        ASSERT_TRUE(request.AddParam((int32_t)315));
        ASSERT_TRUE(request.AddParam((int32_t)28));
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
        ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
        ASSERT_GE(response.reply_size(), 1u);
        const brpc::MysqlReply& r = response.reply(0);
        ASSERT_TRUE(r.is_resultset()) << r;
        ASSERT_EQ(1u, r.row_count());
        const brpc::MysqlReply::Field& f = r.next().field(0);
        // The sum comes back as a (possibly wide) integer; accept any width.
        ASSERT_FALSE(f.is_nil());
        long long got = 0;
        if (f.is_sbigint()) got = f.sbigint();
        else if (f.is_bigint()) got = (long long)f.bigint();
        else if (f.is_sinteger()) got = f.sinteger();
        else if (f.is_integer()) got = f.integer();
        else if (f.is_string()) got = atoll(f.string().as_string().c_str());
        else FAIL() << "unexpected field type for ?+?";
        EXPECT_EQ(343, got);
    }
}

TEST_F(MysqlPreparedTest, ReExecuteAndTypedColumnFetch) {
    SKIP_IF_NO_SERVER();

    // Re-execute the SAME statement twice with different bound ids.
    {
        PREPARE_OR_FAIL(s, "SELECT name FROM ps_people WHERE id=?");
        struct Case { int32_t id; const char* name; };
        const Case cases[] = {{417, "maple"}, {528, "cobalt"}};
        for (const Case& c : cases) {
            SCOPED_TRACE(c.id);
            brpc::MysqlRequest request(s.get());
            ASSERT_TRUE(request.AddParam(c.id));
            brpc::MysqlResponse response;
            brpc::Controller cntl;
            channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
            ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
            ASSERT_GE(response.reply_size(), 1u);
            const brpc::MysqlReply& r = response.reply(0);
            ASSERT_TRUE(r.is_resultset()) << r;
            ASSERT_EQ(1u, r.row_count());
            const brpc::MysqlReply::Field& f = r.next().field(0);
            ASSERT_TRUE(f.is_string());
            EXPECT_EQ(c.name, f.string().as_string());
        }
    }

    // Typed fetch: read INT id, VARCHAR name and BIGINT score off one row.
    {
        PREPARE_OR_FAIL(s, "SELECT id, name, score FROM ps_people WHERE id=?");
        brpc::MysqlRequest request(s.get());
        ASSERT_TRUE(request.AddParam((int32_t)528));
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
        ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
        ASSERT_GE(response.reply_size(), 1u);
        const brpc::MysqlReply& r = response.reply(0);
        ASSERT_TRUE(r.is_resultset()) << r;
        ASSERT_EQ(3u, r.column_count());
        ASSERT_EQ(1u, r.row_count());
        const brpc::MysqlReply::Row& row = r.next();

        // Column 0: INT id == 528.
        const brpc::MysqlReply::Field& id = row.field(0);
        ASSERT_TRUE(id.is_sinteger() || id.is_integer());
        EXPECT_EQ(528, id.is_sinteger() ? id.sinteger() : (int)id.integer());

        // Column 1: VARCHAR name == "cobalt".
        const brpc::MysqlReply::Field& name = row.field(1);
        ASSERT_TRUE(name.is_string());
        EXPECT_EQ("cobalt", name.string().as_string());

        // Column 2: BIGINT score == 9200.
        const brpc::MysqlReply::Field& score = row.field(2);
        ASSERT_TRUE(score.is_sbigint() || score.is_bigint() ||
                    score.is_sinteger() || score.is_integer())
            << "expected an integer score field";
        long long sc = 0;
        if (score.is_sbigint()) sc = score.sbigint();
        else if (score.is_bigint()) sc = (long long)score.bigint();
        else if (score.is_sinteger()) sc = score.sinteger();
        else sc = score.integer();
        EXPECT_EQ(9200, sc);
    }
}

TEST_F(MysqlPreparedTest, NullColumnAndLiteralNullAreNil) {
    SKIP_IF_NO_SERVER();

    // A row with a NULL name column surfaces field(0) as nil.
    {
        PREPARE_OR_FAIL(s, "SELECT name FROM ps_people WHERE id=?");
        brpc::MysqlRequest request(s.get());
        ASSERT_TRUE(request.AddParam((int32_t)639));
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
        ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
        ASSERT_GE(response.reply_size(), 1u);
        const brpc::MysqlReply& r = response.reply(0);
        ASSERT_TRUE(r.is_resultset()) << r;
        ASSERT_EQ(1u, r.row_count());
        EXPECT_TRUE(r.next().field(0).is_nil());
    }

    // A literal NULL in the SELECT list also comes back nil.
    {
        PREPARE_OR_FAIL(s, "SELECT NULL");
        EXPECT_EQ(0u, s->param_count());
        brpc::MysqlRequest request(s.get());
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
        ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
        ASSERT_GE(response.reply_size(), 1u);
        const brpc::MysqlReply& r = response.reply(0);
        ASSERT_TRUE(r.is_resultset()) << r;
        ASSERT_EQ(1u, r.row_count());
        EXPECT_TRUE(r.next().field(0).is_nil());
    }
}

TEST_F(MysqlPreparedTest, MalformedAndParamMismatchSurfaceErrors) {
    SKIP_IF_NO_SERVER();

    // Malformed SQL: dangling WHERE with no predicate.
    {
        auto s = brpc::NewMysqlStatement(
            channel_, "SELECT id FROM ps_people WHERE id=? AND WHERE");
        // Acceptable: prepare returns null, OR the first execute reports an
        // error reply.  A crash or a silent success is not.
        if (s == nullptr) {
            SUCCEED() << "prepare of malformed SQL returned null as expected";
        } else {
            brpc::MysqlRequest request(s.get());
            brpc::MysqlResponse response;
            brpc::Controller cntl;
            channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
            if (cntl.Failed()) {
                SUCCEED() << "execute of malformed statement failed as expected: "
                          << cntl.ErrorText();
            } else {
                ASSERT_GE(response.reply_size(), 1u);
                EXPECT_TRUE(response.reply(0).is_error())
                    << "malformed prepared statement unexpectedly succeeded";
            }
        }
    }

    // Bind too few params: one-? statement executed with zero params.
    {
        PREPARE_OR_FAIL(s, "SELECT name FROM ps_people WHERE id=?");
        ASSERT_EQ(1u, s->param_count());
        brpc::MysqlRequest request(s.get());
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
        if (cntl.Failed()) {
            SUCCEED() << "mismatched param count failed the RPC as expected: "
                      << cntl.ErrorText();
        } else {
            ASSERT_GE(response.reply_size(), 1u);
            EXPECT_TRUE(response.reply(0).is_error())
                << "execute with too few params unexpectedly produced a "
                   "non-error reply";
        }
    }
}

TEST_F(MysqlPreparedTest, StatementReuseAndIndependentStatement) {
    SKIP_IF_NO_SERVER();
    PREPARE_OR_FAIL(s1, "SELECT COUNT(*) FROM ps_people");

    // Execute s1 twice; both must agree.
    long long first_count = -1;
    for (int iter = 0; iter < 2; ++iter) {
        SCOPED_TRACE(iter);
        brpc::MysqlRequest request(s1.get());
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
        ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
        ASSERT_GE(response.reply_size(), 1u);
        const brpc::MysqlReply& r = response.reply(0);
        ASSERT_TRUE(r.is_resultset()) << r;
        ASSERT_EQ(1u, r.row_count());
        const brpc::MysqlReply::Field& f = r.next().field(0);
        long long c = 0;
        if (f.is_sbigint()) c = f.sbigint();
        else if (f.is_bigint()) c = (long long)f.bigint();
        else if (f.is_sinteger()) c = f.sinteger();
        else if (f.is_integer()) c = f.integer();
        else if (f.is_string()) c = atoll(f.string().as_string().c_str());
        else FAIL() << "unexpected COUNT(*) field type";
        if (first_count < 0) first_count = c;
        EXPECT_EQ(first_count, c);
    }
    EXPECT_EQ(3, first_count) << "seed table should hold 3 rows";

    // A second, independent statement on the same channel still works after
    // s1 has been used -- exercises concurrent statement objects / reuse.
    PREPARE_OR_FAIL(s2, "SELECT id FROM ps_people WHERE id=?");
    brpc::MysqlRequest request(s2.get());
    ASSERT_TRUE(request.AddParam((int32_t)417));
    brpc::MysqlResponse response;
    brpc::Controller cntl;
    channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
    ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
    ASSERT_GE(response.reply_size(), 1u);
    ASSERT_TRUE(response.reply(0).is_resultset());
    EXPECT_EQ(1u, response.reply(0).row_count());
}

TEST_F(MysqlPreparedTest, BinaryTimeAndDateTimeParsing) {
    SKIP_IF_NO_SERVER();

    struct Case {
        const char* sql;       // prepared SELECT producing one TIME/DATETIME field
        const char* expected;  // exact string the field must equal
    };
    const Case cases[] = {
        // TIME, ordinary 2-digit hour.
        {"SELECT CAST('12:34:56' AS TIME)", "12:34:56"},
        // TIME, 3-digit hour: the variable-width hour path (total_hour >= 100).
        {"SELECT CAST('300:00:00' AS TIME)", "300:00:00"},
        // TIME, the documented maximum magnitude.
        {"SELECT CAST('838:59:59' AS TIME)", "838:59:59"},
        // TIME, negative: leading '-' sign byte on the wire.
        {"SELECT CAST('-12:30:45' AS TIME)", "-12:30:45"},
        // TIME with fractional seconds (decimal=3 -> 12-byte wire packet).
        {"SELECT CAST('01:02:03.456' AS TIME(3))", "01:02:03.456"},
        // DATETIME with no sub-second part (7-byte wire packet).
        {"SELECT CAST('2021-03-04 05:06:07' AS DATETIME)", "2021-03-04 05:06:07"},
        // DATETIME with microseconds (decimal=6 -> 11-byte wire packet).
        {"SELECT CAST('2021-03-04 05:06:07.123456' AS DATETIME(6))",
         "2021-03-04 05:06:07.123456"},
        // DATETIME at exact midnight: MySQL omits the time-of-day part, so this
        // arrives as a 4-byte (len==4) wire packet. The parser must emit the
        // full "YYYY-MM-DD 00:00:00" form and report exactly 19 bytes.
        {"SELECT CAST('2021-03-04 00:00:00' AS DATETIME)",
         "2021-03-04 00:00:00"},
        // DATE column: only the date part on the wire (len==4) -> "YYYY-MM-DD".
        {"SELECT CAST('2021-03-04' AS DATE)", "2021-03-04"},
        // TIME zero value: encoded with len==0 (no field bytes on the wire).
        // This must surface as the zero string "00:00:00", NOT as NULL.
        {"SELECT CAST('00:00:00' AS TIME)", "00:00:00"},
    };

    for (const Case& c : cases) {
        SCOPED_TRACE(c.sql);
        PREPARE_OR_FAIL(s, c.sql);
        EXPECT_EQ(0u, s->param_count());
        brpc::MysqlRequest request(s.get());
        brpc::MysqlResponse response;
        brpc::Controller cntl;
        channel_.CallMethod(NULL, &cntl, &request, &response, NULL);
        ASSERT_FALSE(cntl.Failed()) << cntl.ErrorText();
        ASSERT_GE(response.reply_size(), 1u);
        const brpc::MysqlReply& r = response.reply(0);
        ASSERT_TRUE(r.is_resultset()) << "expected a result set, got: " << r;
        ASSERT_EQ(1u, r.column_count());
        ASSERT_EQ(1u, r.row_count());
        const brpc::MysqlReply::Field& f = r.next().field(0);
        // The binary TIME/DATETIME value must be surfaced as a string (this is
        // the ParseBinaryTime / ParseBinaryDataTime output).
        ASSERT_TRUE(f.is_string())
            << "TIME/DATETIME field should be exposed as a string";
        // Compare the FULL string, including its length: a trailing-garbage or
        // off-by-one length bug in the parser would make this exact compare
        // fail even if the visible prefix looks right.
        const std::string got = f.string().as_string();
        EXPECT_EQ(c.expected, got)
            << "binary-parsed value mismatch (got length " << got.size()
            << ", expected length " << strlen(c.expected) << ")";
        EXPECT_EQ(strlen(c.expected), got.size())
            << "binary-parsed value has wrong length";
    }
}

static std::string TestDataDir() {
    char cwd[1024];
    if (getcwd(cwd, sizeof(cwd)) == NULL) {
        return std::string("/tmp/mysql_txn_data_for_test");
    }
    return std::string(cwd) + "/mysql_txn_data_for_test";
}

static void RemoveMysqlServer() {
    if (s_mysqld_pid > 0) {
        puts("[Stopping mysqld]");
        char cmd[1280];
        snprintf(cmd, sizeof(cmd), "kill %d", s_mysqld_pid);
        CHECK(0 == system(cmd));
        usleep(500000);
        snprintf(cmd, sizeof(cmd), "rm -rf '%s'", TestDataDir().c_str());
        CHECK(0 == system(cmd));
    }
}

static int ProbeMysql() {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(static_cast<uint16_t>(s_port));
    addr.sin_addr.s_addr = inet_addr(s_host.c_str());
    if (connect(fd, (struct sockaddr*)&addr, sizeof(addr)) != 0) {
        close(fd);
        return -1;
    }
    return fd;
}

static void RunMysqlServer() {
    if (FLAGS_mysql_use_running_server) {
        s_host = FLAGS_mysql_host;
        s_port = FLAGS_mysql_port;
        s_user = FLAGS_mysql_user;
        s_password = FLAGS_mysql_password;
        printf("[Using running mysqld at %s:%d as user '%s']\n",
               s_host.c_str(), s_port, s_user.c_str());
        int fd = ProbeMysql();
        if (fd >= 0) {
            close(fd);
            s_mysqld_pid = -2;
        } else {
            printf("Cannot reach running mysqld at %s:%d, tests will skip\n",
                   s_host.c_str(), s_port);
        }
        return;
    }

    if (system("which " MYSQLD_BIN) != 0) {
        puts("Fail to find " MYSQLD_BIN ", transaction tests will be skipped");
        return;
    }
    s_host = "127.0.0.1";
    s_port = FLAGS_mysql_port;
    s_user = "root";
    s_password.clear();
    const std::string datadir = TestDataDir();
    char cmd[2048];
    snprintf(cmd, sizeof(cmd), "rm -rf '%s' && mkdir -p '%s'",
             datadir.c_str(), datadir.c_str());
    if (system(cmd) != 0) {
        puts("Fail to create datadir, transaction tests will be skipped");
        return;
    }
    snprintf(cmd, sizeof(cmd),
             MYSQLD_BIN " --initialize-insecure --datadir='%s'"
             " --log-error='%s/init.err'",
             datadir.c_str(), datadir.c_str());
    if (system(cmd) != 0) {
        puts("Fail to initialize mysqld datadir, tests will be skipped");
        snprintf(cmd, sizeof(cmd), "rm -rf '%s'", datadir.c_str());
        CHECK(0 == system(cmd));
        return;
    }
    atexit(RemoveMysqlServer);

    s_mysqld_pid = fork();
    if (s_mysqld_pid < 0) {
        puts("Fail to fork");
        exit(1);
    } else if (s_mysqld_pid == 0) {
        puts("[Starting mysqld]");
        char port_arg[32];
        snprintf(port_arg, sizeof(port_arg), "--port=%d", FLAGS_mysql_port);
        const std::string datadir_arg = "--datadir=" + datadir;
        const std::string socket_arg = "--socket=" + datadir + "/mysqld.sock";
        const std::string pidfile_arg = "--pid-file=" + datadir + "/mysqld.pid";
        const std::string logerr_arg = "--log-error=" + datadir + "/mysqld.err";
        char* const argv[] = {
            (char*)MYSQLD_BIN,
            (char*)datadir_arg.c_str(),
            (char*)port_arg,
            (char*)socket_arg.c_str(),
            (char*)pidfile_arg.c_str(),
            (char*)logerr_arg.c_str(),
            (char*)"--mysqlx=OFF",
            (char*)"--bind-address=127.0.0.1",
            NULL};
        if (execvp(MYSQLD_BIN, argv) < 0) {
            puts("Fail to run " MYSQLD_BIN);
            exit(1);
        }
    }
    // Wait for TCP readiness (fresh tablespace recovery), then create a
    // password account so the caching_sha2 client can authenticate over TCP
    // exactly like the running-server mode.  root keeps its empty password on
    // the unix socket; we exercise the spawned server as empty-password root.
    for (int i = 0; i < 300; ++i) {
        int fd = ProbeMysql();
        if (fd >= 0) {
            close(fd);
            return;
        }
        usleep(100000);
    }
    puts("mysqld did not become ready, transaction tests will be skipped");
    s_mysqld_pid = -1;
}

static bool RunPlain(brpc::Channel& channel, const std::string& sql,
                     brpc::MysqlResponse* resp) {
    brpc::MysqlRequest req;
    if (!req.Query(sql)) {
        return false;
    }
    brpc::Controller cntl;
    channel.CallMethod(NULL, &cntl, &req, resp, NULL);
    return !cntl.Failed();
}

static bool RunInTx(brpc::Channel& channel, const brpc::MysqlTransaction* tx,
                    const std::string& sql, brpc::MysqlResponse* resp) {
    brpc::MysqlRequest req(tx);
    if (!req.Query(sql)) {
        return false;
    }
    brpc::Controller cntl;
    channel.CallMethod(NULL, &cntl, &req, resp, NULL);
    return !cntl.Failed();
}

static ::testing::AssertionResult ExpectOk(const brpc::MysqlResponse& resp) {
    if (resp.reply_size() < 1) {
        return ::testing::AssertionFailure() << "no reply";
    }
    const brpc::MysqlReply& r = resp.reply(0);
    if (r.is_error()) {
        return ::testing::AssertionFailure()
               << "ERR " << r.error().errcode() << ": "
               << r.error().msg().as_string();
    }
    if (!r.is_ok()) {
        return ::testing::AssertionFailure() << "reply is not OK, type=" << r.type();
    }
    return ::testing::AssertionSuccess();
}

static int64_t ResultRowCount(const brpc::MysqlResponse& resp) {
    if (resp.reply_size() < 1) {
        return -1;
    }
    const brpc::MysqlReply& r = resp.reply(0);
    if (!r.is_resultset()) {
        return -1;
    }
    return static_cast<int64_t>(r.row_count());
}

void SetUp() override {
        pthread_once(&s_start_once, RunMysqlServer);
        if (NoServer()) {
            GTEST_SKIP() << "no mysqld available; skipping transaction tests";
        }
        // Authenticator carries user/password and the working schema.  An
        // empty schema is created first over a schema-less channel.
        ASSERT_TRUE(InitChannel(&_setup_channel, /*schema=*/""));
        brpc::MysqlResponse resp;
        ASSERT_TRUE(RunPlain(_setup_channel, "CREATE DATABASE IF NOT EXISTS " +
                                                 FLAGS_mysql_schema, &resp));

        ASSERT_TRUE(InitChannel(&_channel, FLAGS_mysql_schema));
        ASSERT_TRUE(RunPlain(_channel, "DROP TABLE IF EXISTS " + Table(), &resp));
        ASSERT_TRUE(ExpectOk(resp)) << "drop pre-existing scratch table";
        ASSERT_TRUE(RunPlain(_channel,
                             "CREATE TABLE " + Table() +
                                 " (id INT PRIMARY KEY, name VARCHAR(32)) "
                                 "ENGINE=InnoDB",
                             &resp));
        ASSERT_TRUE(ExpectOk(resp)) << "create scratch table";
    }

void TearDown() override {
        if (NoServer()) {
            return;
        }
        brpc::MysqlResponse resp;
        RunPlain(_channel, "DROP TABLE IF EXISTS " + Table(), &resp);
    }

bool InitChannel(brpc::Channel* channel, const std::string& schema) {
        _auth.reset(new brpc::policy::MysqlAuthenticator(s_user, s_password,
                                                         schema));
        brpc::ChannelOptions options;
        options.protocol = "mysql";
        options.connection_type = "pooled";
        options.auth = _auth.get();
        options.timeout_ms = 5000;
        options.max_retry = 0;
        char addr[128];
        snprintf(addr, sizeof(addr), "%s:%d", s_host.c_str(), s_port);
        return channel->Init(addr, &options) == 0;
    }

TEST_F(MysqlTxnIntegrationTest, CommitPublishesRollbackRestores) {
    brpc::MysqlResponse resp;

    // 1) committed INSERT must be visible on a fresh connection afterwards.
    {
        brpc::MysqlTransactionUniquePtr tx =
            brpc::NewMysqlTransaction(_channel, brpc::MysqlTransactionOptions());
        ASSERT_TRUE(tx != NULL) << "failed to start transaction";
        ASSERT_TRUE(RunInTx(_channel, tx.get(),
                            "INSERT INTO " + Table() + " VALUES (3107, 'quill')",
                            &resp));
        EXPECT_TRUE(ExpectOk(resp));
        EXPECT_EQ(resp.reply(0).ok().affect_row(), 1u);
        ASSERT_TRUE(tx->commit());
    }
    ASSERT_TRUE(RunPlain(_channel, "SELECT id, name FROM " + Table(), &resp));
    EXPECT_EQ(ResultRowCount(resp), 1);
    {
        const brpc::MysqlReply& r = resp.reply(0);
        ASSERT_TRUE(r.is_resultset());
        ASSERT_EQ(r.row_count(), 1u);
        const brpc::MysqlReply::Row& row = r.next();
        ASSERT_EQ(row.field_count(), 2u);
        EXPECT_EQ(row.field(0).sinteger(), 3107);
        EXPECT_EQ(row.field(1).string().as_string(), "quill");
    }

    // 2) a rolled-back INSERT must leave no trace (still exactly one row).
    {
        brpc::MysqlTransactionUniquePtr tx =
            brpc::NewMysqlTransaction(_channel, brpc::MysqlTransactionOptions());
        ASSERT_TRUE(tx != NULL);
        ASSERT_TRUE(RunInTx(_channel, tx.get(),
                            "INSERT INTO " + Table() + " VALUES (5288, 'brindle')",
                            &resp));
        EXPECT_TRUE(ExpectOk(resp));
        ASSERT_TRUE(tx->rollback());
    }
    ASSERT_TRUE(RunPlain(_channel, "SELECT id FROM " + Table(), &resp));
    EXPECT_EQ(ResultRowCount(resp), 1) << "rolled-back insert must vanish";

    // 3) a rolled-back DELETE of the committed row must restore it.
    {
        brpc::MysqlTransactionUniquePtr tx =
            brpc::NewMysqlTransaction(_channel, brpc::MysqlTransactionOptions());
        ASSERT_TRUE(tx != NULL);
        ASSERT_TRUE(RunInTx(_channel, tx.get(),
                            "DELETE FROM " + Table() + " WHERE id = 3107", &resp));
        EXPECT_TRUE(ExpectOk(resp));
        EXPECT_EQ(resp.reply(0).ok().affect_row(), 1u);
        ASSERT_TRUE(tx->rollback());
    }
    ASSERT_TRUE(RunPlain(_channel, "SELECT id FROM " + Table(), &resp));
    EXPECT_EQ(ResultRowCount(resp), 1) << "rolled-back delete must restore row";
    {
        const brpc::MysqlReply& r = resp.reply(0);
        ASSERT_TRUE(r.is_resultset());
        ASSERT_EQ(r.row_count(), 1u);
        EXPECT_EQ(r.next().field(0).sinteger(), 3107);
    }
}

TEST_F(MysqlTxnIntegrationTest, OwnWriteVisibleOthersIsolated) {
    brpc::MysqlTransactionUniquePtr tx =
        brpc::NewMysqlTransaction(_channel, brpc::MysqlTransactionOptions());
    ASSERT_TRUE(tx != NULL);

    brpc::MysqlResponse resp;
    ASSERT_TRUE(RunInTx(_channel, tx.get(),
                        "INSERT INTO " + Table() + " VALUES (6741, 'tangle')",
                        &resp));
    EXPECT_TRUE(ExpectOk(resp));

    // Same pinned connection: must read its own uncommitted row.
    ASSERT_TRUE(RunInTx(_channel, tx.get(),
                        "SELECT name FROM " + Table() + " WHERE id = 6741", &resp));
    EXPECT_EQ(ResultRowCount(resp), 1);
    {
        const brpc::MysqlReply& r = resp.reply(0);
        ASSERT_TRUE(r.is_resultset());
        ASSERT_EQ(r.row_count(), 1u);
        EXPECT_EQ(r.next().field(0).string().as_string(), "tangle");
    }

    // A different pooled connection must NOT see the uncommitted write.
    ASSERT_TRUE(RunPlain(_channel, "SELECT id FROM " + Table(), &resp));
    EXPECT_EQ(ResultRowCount(resp), 0)
        << "uncommitted write leaked to another connection";

    ASSERT_TRUE(tx->rollback());

    // After rollback nothing remains anywhere.
    ASSERT_TRUE(RunPlain(_channel, "SELECT id FROM " + Table(), &resp));
    EXPECT_EQ(ResultRowCount(resp), 0);
}

TEST_F(MysqlTxnIntegrationTest, AutocommitOnDurableOffRollbackable) {
    brpc::MysqlResponse resp;

    // autocommit ON: immediate durability.
    ASSERT_TRUE(RunPlain(_channel,
                         "INSERT INTO " + Table() + " VALUES (4419, 'amber')",
                         &resp));
    EXPECT_TRUE(ExpectOk(resp));
    ASSERT_TRUE(RunPlain(_channel, "SELECT id FROM " + Table(), &resp));
    EXPECT_EQ(ResultRowCount(resp), 1);

    // autocommit OFF on a pinned connection: a new INSERT is pending and a
    // ROLLBACK drops only it, leaving the earlier durable row in place.
    {
        brpc::MysqlTransactionUniquePtr tx =
            brpc::NewMysqlTransaction(_channel, brpc::MysqlTransactionOptions());
        ASSERT_TRUE(tx != NULL);
        ASSERT_TRUE(RunInTx(_channel, tx.get(), "SET autocommit = 0", &resp));
        EXPECT_TRUE(ExpectOk(resp));
        ASSERT_TRUE(RunInTx(_channel, tx.get(),
                            "INSERT INTO " + Table() + " VALUES (8053, 'frost')",
                            &resp));
        EXPECT_TRUE(ExpectOk(resp));
        ASSERT_TRUE(tx->rollback());
    }
    ASSERT_TRUE(RunPlain(_channel, "SELECT id FROM " + Table(), &resp));
    EXPECT_EQ(ResultRowCount(resp), 1)
        << "autocommit=0 + rollback should drop only the pending insert";
    EXPECT_EQ(resp.reply(0).next().field(0).sinteger(), 4419);
}

TEST_F(MysqlTxnIntegrationTest, GroupedInsertsThenSavepointPartialUndo) {
    brpc::MysqlResponse resp;

    // Two inserts under one transaction: invisible until commit, then both show.
    {
        brpc::MysqlTransactionUniquePtr tx =
            brpc::NewMysqlTransaction(_channel, brpc::MysqlTransactionOptions());
        ASSERT_TRUE(tx != NULL);
        ASSERT_TRUE(RunInTx(_channel, tx.get(),
                            "INSERT INTO " + Table() + " VALUES (211, 'one')",
                            &resp));
        EXPECT_TRUE(ExpectOk(resp));
        ASSERT_TRUE(RunInTx(_channel, tx.get(),
                            "INSERT INTO " + Table() + " VALUES (733, 'two')",
                            &resp));
        EXPECT_TRUE(ExpectOk(resp));

        // Not yet visible to a separate connection.
        ASSERT_TRUE(RunPlain(_channel, "SELECT id FROM " + Table(), &resp));
        EXPECT_EQ(ResultRowCount(resp), 0);

        ASSERT_TRUE(tx->commit());
    }
    ASSERT_TRUE(RunPlain(_channel, "SELECT id FROM " + Table(), &resp));
    EXPECT_EQ(ResultRowCount(resp), 2) << "both grouped inserts visible";

    // Start fresh for the savepoint half.
    ASSERT_TRUE(RunPlain(_channel, "DELETE FROM " + Table(), &resp));
    ASSERT_TRUE(ExpectOk(resp));

    // SAVEPOINT then ROLLBACK TO it: pre-savepoint row kept, post dropped.
    {
        brpc::MysqlTransactionUniquePtr tx =
            brpc::NewMysqlTransaction(_channel, brpc::MysqlTransactionOptions());
        ASSERT_TRUE(tx != NULL);
        ASSERT_TRUE(RunInTx(_channel, tx.get(),
                            "INSERT INTO " + Table() + " VALUES (901, 'kept')",
                            &resp));
        EXPECT_TRUE(ExpectOk(resp));
        ASSERT_TRUE(RunInTx(_channel, tx.get(), "SAVEPOINT mark1", &resp));
        EXPECT_TRUE(ExpectOk(resp));
        ASSERT_TRUE(RunInTx(_channel, tx.get(),
                            "INSERT INTO " + Table() + " VALUES (902, 'gone')",
                            &resp));
        EXPECT_TRUE(ExpectOk(resp));
        ASSERT_TRUE(RunInTx(_channel, tx.get(), "ROLLBACK TO SAVEPOINT mark1",
                            &resp));
        EXPECT_TRUE(ExpectOk(resp));

        // Inside the txn only the pre-savepoint row remains.
        ASSERT_TRUE(RunInTx(_channel, tx.get(), "SELECT id FROM " + Table(),
                            &resp));
        EXPECT_EQ(ResultRowCount(resp), 1);

        ASSERT_TRUE(tx->commit());
    }
    ASSERT_TRUE(RunPlain(_channel, "SELECT id FROM " + Table(), &resp));
    EXPECT_EQ(ResultRowCount(resp), 1) << "only the kept row should persist";
    {
        const brpc::MysqlReply& r = resp.reply(0);
        ASSERT_TRUE(r.is_resultset());
        ASSERT_EQ(r.row_count(), 1u);
        EXPECT_EQ(r.next().field(0).sinteger(), 901);
    }
}

TEST_F(MysqlTxnIntegrationTest, DuplicateKeyAndReadOnlyWriteReportErr) {
    brpc::MysqlResponse resp;

    // Seed a committed row so the in-txn insert collides on the primary key.
    ASSERT_TRUE(RunPlain(_channel,
                         "INSERT INTO " + Table() + " VALUES (1505, 'seed')",
                         &resp));
    ASSERT_TRUE(ExpectOk(resp));

    {
        brpc::MysqlTransactionUniquePtr tx =
            brpc::NewMysqlTransaction(_channel, brpc::MysqlTransactionOptions());
        ASSERT_TRUE(tx != NULL);
        // Duplicate-key insert -> ERR packet (errno 1062, ER_DUP_ENTRY).
        ASSERT_TRUE(RunInTx(_channel, tx.get(),
                            "INSERT INTO " + Table() + " VALUES (1505, 'clash')",
                            &resp));
        ASSERT_GE(resp.reply_size(), 1u);
        const brpc::MysqlReply& r = resp.reply(0);
        EXPECT_TRUE(r.is_error()) << "duplicate key should yield an ERR reply";
        if (r.is_error()) {
            EXPECT_EQ(r.error().errcode(), 1062) << "expected ER_DUP_ENTRY (1062)";
        }
        ASSERT_TRUE(tx->rollback());
    }

    // A read-only transaction must reject a write.
    {
        brpc::MysqlTransactionOptions opts;
        opts.readonly = true;
        brpc::MysqlTransactionUniquePtr tx =
            brpc::NewMysqlTransaction(_channel, opts);
        ASSERT_TRUE(tx != NULL) << "failed to start read-only transaction";
        ASSERT_TRUE(RunInTx(_channel, tx.get(),
                            "INSERT INTO " + Table() + " VALUES (1777, 'nope')",
                            &resp));
        ASSERT_GE(resp.reply_size(), 1u);
        const brpc::MysqlReply& r = resp.reply(0);
        EXPECT_TRUE(r.is_error())
            << "write in a read-only transaction should be rejected with ERR";
        if (r.is_error()) {
            // ER_CANT_EXECUTE_IN_READ_ONLY_TRANSACTION == 1792.
            EXPECT_EQ(r.error().errcode(), 1792)
                << "expected read-only-transaction error (1792)";
        }
        ASSERT_TRUE(tx->rollback());
    }
}

TEST_F(RedisTest, inline_does_not_eat_h2_preface) {
    brpc::RedisCommandParser parser;
    butil::IOBuf buf;
    std::vector<butil::StringPiece> command_out;
    butil::Arena arena;
    {
        // Full HTTP/2 client connection preface: must defer to other protocols.
        buf.append("PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n");
        ASSERT_EQ(brpc::PARSE_ERROR_TRY_OTHERS,
                  parser.Consume(buf, &command_out, &arena));
        buf.clear();
        parser.Reset();
    }
    {
        // A not-yet-complete prefix of the preface must also defer, leaving the
        // bytes intact for the HTTP/2 parser instead of being misparsed.
        buf.append("PRI * HT");
        ASSERT_EQ(brpc::PARSE_ERROR_TRY_OTHERS,
                  parser.Consume(buf, &command_out, &arena));
        buf.clear();
        parser.Reset();
    }
    {
        // A genuine inline command sharing the leading 'P' must still parse.
        buf.append("PING\r\n");
        ASSERT_EQ(brpc::PARSE_OK, parser.Consume(buf, &command_out, &arena));
        ASSERT_EQ("ping", GetCompleteCommand(command_out));
        buf.clear();
        parser.Reset();
    }
}

bool ReadLE(const butil::StringPiece& buf, size_t off, size_t n, T* out) {
    if (off + n > buf.size()) return false;
    T v = 0;
    for (size_t i = 0; i < n; ++i) {
        v |= static_cast<T>(static_cast<unsigned char>(buf[off + i])) << (8 * i);
    }
    *out = v;
    return true;
}

void WriteLE(T value, size_t n, std::string* out) {
    for (size_t i = 0; i < n; ++i) {
        out->push_back(static_cast<char>((value >> (8 * i)) & 0xff));
    }
}

ol BuildHandshakeResponse41(const HandshakeResponse41& req, std::string* out) {
    // The CLIENT_SECURE_CONNECTION encoding prefixes auth_response with a
    // single length byte, so it cannot represent a payload larger than 255
    // bytes.  Validate this FIRST and fail hard rather than silently
    // truncating: a truncated auth_response is invalid and would
    // desynchronize the packet stream.  Larger payloads (e.g. RSA
    // ciphertext) require the caller to negotiate
    // CLIENT_PLUGIN_AUTH_LENENC_CLIENT_DATA, which has no such limit.
    const bool lenenc_client_data =
        req.capability_flags & CLIENT_PLUGIN_AUTH_LENENC_CLIENT_DATA;
    if (!lenenc_client_data &&
        (req.capability_flags & CLIENT_SECURE_CONNECTION) &&
        req.auth_response.size() > 0xff) {
        LOG(ERROR) << "Cannot build HandshakeResponse41: auth_response is "
                   << req.auth_response.size() << " bytes, exceeding the "
                      "255-byte CLIENT_SECURE_CONNECTION length prefix; "
                      "negotiate CLIENT_PLUGIN_AUTH_LENENC_CLIENT_DATA for "
                      "larger payloads";
        return false;
    }

    WriteLE<uint32_t>(req.capability_flags, 4, out);
    WriteLE<uint32_t>(req.max_packet_size, 4, out);
    out->push_back(static_cast<char>(req.character_set));
    out->append(kReservedInResponseLen, '\0');
    out->append(req.username);
    out->push_back('\0');

    if (lenenc_client_data) {
        EncodeLengthEncodedString(req.auth_response, out);
    } else if (req.capability_flags & CLIENT_SECURE_CONNECTION) {
        // Length validated above to fit in a single byte.
        const uint8_t len = static_cast<uint8_t>(req.auth_response.size());
        out->push_back(static_cast<char>(len));
        out->append(req.auth_response.data(), req.auth_response.size());
    } else {
        out->append(req.auth_response);
        out->push_back('\0');
    }

    if (req.capability_flags & CLIENT_CONNECT_WITH_DB) {
        out->append(req.database);
        out->push_back('\0');
    }

    if (req.capability_flags & CLIENT_PLUGIN_AUTH) {
        out->append(req.auth_plugin_name);
        out->push_back('\0');
    }
    return true;
}

ol ParseAuthSwitchRequest(const butil::StringPiece& payload,
                            AuthSwitchRequest* out) {
    if (payload.empty() ||
        static_cast<uint8_t>(payload[0]) != kAuthSwitchRequestTag) {
        LOG(ERROR) << "ParseAuthSwitchRequest: empty payload or missing "
                      "AuthSwitchRequest tag";
        return false;
    }
    size_t off = 1;
    std::string name;
    const butil::StringPiece rest(payload.data() + off, payload.size() - off);
    const size_t consumed = DecodeNullTerminatedString(rest, &name);
    if (consumed == 0) {
        LOG(ERROR) << "ParseAuthSwitchRequest: unterminated auth_plugin_name "
                      "string";
        return false;
    }
    off += consumed;
    out->auth_plugin_name = std::move(name);

    // Remainder is auth-plugin-data; trim a single trailing NUL filler.
    out->auth_plugin_data.assign(payload.data() + off, payload.size() - off);
    if (!out->auth_plugin_data.empty() && out->auth_plugin_data.back() == '\0') {
        out->auth_plugin_data.pop_back();
    }
    return true;
}

ol ParseAuthMoreData(const butil::StringPiece& payload, AuthMoreData* out) {
    if (payload.empty() ||
        static_cast<uint8_t>(payload[0]) != kAuthMoreDataTag) {
        LOG(ERROR) << "ParseAuthMoreData: empty payload or missing "
                      "AuthMoreData tag";
        return false;
    }
    out->data.assign(payload.data() + 1, payload.size() - 1);
    return true;
}

size_t DecodeLengthEncodedInt(const butil::StringPiece& buf, uint64_t* out,
                              bool* is_null) {
    // Define *out and *is_null on every path so a caller that forgets to
    // check the return value can never read an uninitialized result.
    *out = 0;
    if (is_null != nullptr) {
        *is_null = false;
    }
    if (buf.empty()) {
        LOG(WARNING) << "DecodeLengthEncodedInt: empty buffer";
        return 0;
    }
    const unsigned char first = static_cast<unsigned char>(buf[0]);
    if (first < 0xfb) {
        *out = first;
        return 1;
    }
    if (first == 0xfb) {
        // 0xFB is the lenenc NULL marker, not a length prefix.  Report NULL
        // (one byte consumed) instead of folding it into the failure path.
        if (is_null != nullptr) {
            *is_null = true;
        }
        return 1;
    }
    if (first == 0xfc) {
        if (buf.size() < 3) {
            LOG(WARNING) << "DecodeLengthEncodedInt: truncated 0xFC value, need 3 bytes";
            return 0;
        }
        *out = static_cast<unsigned char>(buf[1])
             | (static_cast<uint64_t>(static_cast<unsigned char>(buf[2])) << 8);
        return 3;
    }
    if (first == 0xfd) {
        if (buf.size() < 4) {
            LOG(WARNING) << "DecodeLengthEncodedInt: truncated 0xFD value, need 4 bytes";
            return 0;
        }
        *out = static_cast<unsigned char>(buf[1])
             | (static_cast<uint64_t>(static_cast<unsigned char>(buf[2])) << 8)
             | (static_cast<uint64_t>(static_cast<unsigned char>(buf[3])) << 16);
        return 4;
    }
    if (first == 0xfe) {
        if (buf.size() < 9) {
            LOG(WARNING) << "DecodeLengthEncodedInt: truncated 0xFE value, need 9 bytes";
            return 0;
        }
        uint64_t v = 0;
        for (int i = 0; i < 8; ++i) {
            v |= static_cast<uint64_t>(static_cast<unsigned char>(buf[1 + i]))
                 << (8 * i);
        }
        *out = v;
        return 9;
    }
    // 0xff is reserved for error packet marker; not a valid lenenc-int.
    LOG(WARNING) << "DecodeLengthEncodedInt: reserved 0xFF marker";
    return 0;
}

void EncodeLengthEncodedInt(uint64_t value, std::string* out) {
    if (value < 0xfb) {
        out->push_back(static_cast<char>(value));
        return;
    }
    if (value < 0x10000ULL) {
        out->push_back(static_cast<char>(0xfc));
        out->push_back(static_cast<char>(value & 0xff));
        out->push_back(static_cast<char>((value >> 8) & 0xff));
        return;
    }
    if (value < 0x1000000ULL) {
        out->push_back(static_cast<char>(0xfd));
        out->push_back(static_cast<char>(value & 0xff));
        out->push_back(static_cast<char>((value >> 8) & 0xff));
        out->push_back(static_cast<char>((value >> 16) & 0xff));
        return;
    }
    out->push_back(static_cast<char>(0xfe));
    for (int i = 0; i < 8; ++i) {
        out->push_back(static_cast<char>((value >> (8 * i)) & 0xff));
    }
}

size_t DecodeLengthEncodedString(const butil::StringPiece& buf,
                                 std::string* out_value,
                                 bool* is_null) {
    out_value->clear();
    if (is_null != nullptr) {
        *is_null = false;
    }
    uint64_t len = 0;
    bool len_is_null = false;
    const size_t prefix = DecodeLengthEncodedInt(buf, &len, &len_is_null);
    if (prefix == 0) {
        LOG(WARNING) << "DecodeLengthEncodedString: failed to decode length prefix";
        return 0;
    }
    if (len_is_null) {
        // Leading 0xFB: the string itself is NULL.  Only the marker byte is
        // consumed; there is no payload to read.
        if (is_null != nullptr) {
            *is_null = true;
        }
        return prefix;
    }
    if (prefix > buf.size() || len > buf.size() - prefix) {
        LOG(WARNING) << "DecodeLengthEncodedString: declared length " << len
                   << " exceeds buffer";
        return 0;
    }
    out_value->assign(buf.data() + prefix, len);
    return prefix + len;
}

void EncodeLengthEncodedString(const butil::StringPiece& value,
                               std::string* out) {
    EncodeLengthEncodedInt(value.size(), out);
    out->append(value.data(), value.size());
}

bool DecodePacketHeader(const butil::StringPiece& buf, PacketHeader* out) {
    if (buf.size() < kPacketHeaderLen) {
        LOG(WARNING) << "DecodePacketHeader: buffer smaller than packet header";
        return false;
    }
    out->payload_len =
          static_cast<unsigned char>(buf[0])
        | (static_cast<uint32_t>(static_cast<unsigned char>(buf[1])) << 8)
        | (static_cast<uint32_t>(static_cast<unsigned char>(buf[2])) << 16);
    out->seq = static_cast<unsigned char>(buf[3]);
    return true;
}

void EncodePacketHeader(const PacketHeader& header, std::string* out) {
    out->push_back(static_cast<char>(header.payload_len & 0xff));
    out->push_back(static_cast<char>((header.payload_len >> 8) & 0xff));
    out->push_back(static_cast<char>((header.payload_len >> 16) & 0xff));
    out->push_back(static_cast<char>(header.seq));
}

size_t DecodeNullTerminatedString(const butil::StringPiece& buf,
                                  std::string* out_value) {
    const char* nul = static_cast<const char*>(
        memchr(buf.data(), '\0', buf.size()));
    if (nul == nullptr) {
        LOG(WARNING) << "DecodeNullTerminatedString: no NUL terminator found";
        return 0;
    }
    const size_t len = static_cast<size_t>(nul - buf.data());
    out_value->assign(buf.data(), len);
    return len + 1;
}

bool Sha256Bytes(const unsigned char* data, size_t len, unsigned char out[32]) {
    unsigned int digest_len = 0;
    return EVP_Digest(data, len, out, &digest_len, EVP_sha256(), nullptr) == 1
        && digest_len == 32;
}

std::string NativePasswordScramble(const butil::StringPiece& salt,
                                   const butil::StringPiece& password) {
    if (password.empty()) {
        return std::string();
    }
    if (salt.size() != kSaltLen) {
        return std::string();
    }

    const size_t kHashLen = butil::kSHA1Length;

    unsigned char sha_pw[kHashLen];
    butil::SHA1HashBytes(
        reinterpret_cast<const unsigned char*>(password.data()),
        password.size(), sha_pw);

    unsigned char sha_sha_pw[kHashLen];
    butil::SHA1HashBytes(sha_pw, kHashLen, sha_sha_pw);

    unsigned char joined[kHashLen * 2];
    memcpy(joined, salt.data(), kHashLen);
    memcpy(joined + kHashLen, sha_sha_pw, kHashLen);

    unsigned char salted_hash[kHashLen];
    butil::SHA1HashBytes(joined, sizeof(joined), salted_hash);

    std::string out(kHashLen, '\0');
    for (size_t i = 0; i < kHashLen; ++i) {
        out[i] = static_cast<char>(sha_pw[i] ^ salted_hash[i]);
    }
    return out;
}

std::string CachingSha2PasswordScramble(const butil::StringPiece& salt,
                                        const butil::StringPiece& password) {
    if (password.empty()) {
        return std::string();
    }
    if (salt.size() != kSaltLen) {
        return std::string();
    }

    const size_t kHashLen = 32;

    unsigned char sha_pw[kHashLen];
    if (!Sha256Bytes(reinterpret_cast<const unsigned char*>(password.data()),
                     password.size(), sha_pw)) {
        return std::string();
    }

    unsigned char sha_sha_pw[kHashLen];
    if (!Sha256Bytes(sha_pw, kHashLen, sha_sha_pw)) {
        return std::string();
    }

    unsigned char joined[kHashLen + kSaltLen];
    memcpy(joined, sha_sha_pw, kHashLen);
    memcpy(joined + kHashLen, salt.data(), kSaltLen);

    unsigned char salted_hash[kHashLen];
    if (!Sha256Bytes(joined, sizeof(joined), salted_hash)) {
        return std::string();
    }

    std::string out(kHashLen, '\0');
    for (size_t i = 0; i < kHashLen; ++i) {
        out[i] = static_cast<char>(sha_pw[i] ^ salted_hash[i]);
    }
    return out;
}

std::string CachingSha2PasswordRsaEncrypt(
        const butil::StringPiece& server_pubkey_pem,
        const butil::StringPiece& salt,
        const butil::StringPiece& password) {
    if (salt.size() != kSaltLen) {
        return std::string();
    }
    if (server_pubkey_pem.empty()) {
        return std::string();
    }

    std::string plaintext;
    plaintext.resize(password.size() + 1);
    for (size_t i = 0; i < password.size(); ++i) {
        plaintext[i] = static_cast<char>(
            password.data()[i] ^ salt.data()[i % kSaltLen]);
    }
    plaintext[password.size()] = static_cast<char>(
        '\0' ^ salt.data()[password.size() % kSaltLen]);

    BIO* bio = BIO_new_mem_buf(server_pubkey_pem.data(),
                               static_cast<int>(server_pubkey_pem.size()));
    if (bio == nullptr) {
        return std::string();
    }
    EVP_PKEY* pkey = PEM_read_bio_PUBKEY(bio, nullptr, nullptr, nullptr);
    BIO_free(bio);
    if (pkey == nullptr) {
        return std::string();
    }

    EVP_PKEY_CTX* ctx = EVP_PKEY_CTX_new(pkey, nullptr);
    if (ctx == nullptr) {
        EVP_PKEY_free(pkey);
        return std::string();
    }

    std::string out;
    do {
        if (EVP_PKEY_encrypt_init(ctx) <= 0) break;
        if (EVP_PKEY_CTX_set_rsa_padding(ctx, RSA_PKCS1_OAEP_PADDING) <= 0) break;

        size_t out_len = 0;
        if (EVP_PKEY_encrypt(
                ctx, nullptr, &out_len,
                reinterpret_cast<const unsigned char*>(plaintext.data()),
                plaintext.size()) <= 0) {
            break;
        }
        out.resize(out_len);
        if (EVP_PKEY_encrypt(
                ctx,
                reinterpret_cast<unsigned char*>(&out[0]), &out_len,
                reinterpret_cast<const unsigned char*>(plaintext.data()),
                plaintext.size()) <= 0) {
            out.clear();
            break;
        }
        out.resize(out_len);
    } while (false);

    EVP_PKEY_CTX_free(ctx);
    EVP_PKEY_free(pkey);
    return out;
}

std::string CachingSha2PasswordCleartext(const butil::StringPiece& password) {
    if (password.empty()) {
        return std::string();
    }
    std::string out;
    out.reserve(password.size() + 1);
    out.append(password.data(), password.size());
    out.push_back('\0');
    return out;
}

std::string CachingSha2PasswordSlowPath(
        const butil::StringPiece& password,
        const butil::StringPiece& salt,
        const butil::StringPiece& server_pubkey_pem,
        bool is_ssl) {
    if (is_ssl) {
        return CachingSha2PasswordCleartext(password);
    }
    return CachingSha2PasswordRsaEncrypt(server_pubkey_pem, salt, password);
}

std::string MakeHandshakeV10Payload(
        const std::string& server_version,
        uint32_t connection_id,
        const std::string& salt,
        uint32_t capability_flags,
        uint8_t character_set,
        uint16_t status_flags,
        const std::string& auth_plugin_name) {
    std::string out;
    out.push_back(static_cast<char>(kHandshakeV10Tag));
    out.append(server_version);
    out.push_back('\0');
    for (int i = 0; i < 4; ++i) {
        out.push_back(static_cast<char>((connection_id >> (8 * i)) & 0xff));
    }
    // Salt part 1 (first 8 bytes).
    out.append(salt.data(), 8);
    // Filler.
    out.push_back('\0');
    // Capability flags low 16 bits.
    out.push_back(static_cast<char>(capability_flags & 0xff));
    out.push_back(static_cast<char>((capability_flags >> 8) & 0xff));
    // Character set.
    out.push_back(static_cast<char>(character_set));
    // Status flags.
    out.push_back(static_cast<char>(status_flags & 0xff));
    out.push_back(static_cast<char>((status_flags >> 8) & 0xff));
    // Capability flags high 16 bits.
    out.push_back(static_cast<char>((capability_flags >> 16) & 0xff));
    out.push_back(static_cast<char>((capability_flags >> 24) & 0xff));
    // Length of auth-plugin-data: 21 (8 + 12 + 1 NUL filler) when
    // CLIENT_PLUGIN_AUTH set, 0 otherwise.
    const uint8_t apd_total = (capability_flags & CLIENT_PLUGIN_AUTH) ? 21 : 0;
    out.push_back(static_cast<char>(apd_total));
    // 10 reserved zeros.
    out.append(10, '\0');
    if (capability_flags & CLIENT_SECURE_CONNECTION) {
        // Salt part 2: 12 bytes plus 1 NUL filler.
        out.append(salt.data() + 8, salt.size() - 8);
        out.push_back('\0');
    }
    if (capability_flags & CLIENT_PLUGIN_AUTH) {
        out.append(auth_plugin_name);
        out.push_back('\0');
    }
    return out;
}

TEST(HandshakeV10Test, HappyPath_Mysql8Style) {
    std::string salt;
    for (int i = 1; i <= 20; ++i) salt.push_back(static_cast<char>(i));
    const uint32_t caps =
        CLIENT_PROTOCOL_41 | CLIENT_SECURE_CONNECTION | CLIENT_PLUGIN_AUTH;

    const std::string payload = MakeHandshakeV10Payload(
        "8.0.32", 42, salt, caps,
        /*character_set=*/0xff, /*status_flags=*/0x0002,
        "mysql_native_password");

    HandshakeV10 hs;
    ASSERT_TRUE(ParseHandshakeV10(payload, &hs));
    EXPECT_EQ(hs.protocol_version, kHandshakeV10Tag);
    EXPECT_EQ(hs.server_version, "8.0.32");
    EXPECT_EQ(hs.connection_id, 42u);
    EXPECT_EQ(hs.auth_plugin_data, salt);
    EXPECT_EQ(hs.auth_plugin_data.size(), kSaltLen);
    EXPECT_TRUE(hs.capability_flags & CLIENT_PLUGIN_AUTH);
    EXPECT_TRUE(hs.capability_flags & CLIENT_SECURE_CONNECTION);
    EXPECT_EQ(hs.character_set, 0xff);
    EXPECT_EQ(hs.status_flags, 0x0002);
    EXPECT_EQ(hs.auth_plugin_name, "mysql_native_password");
}

TEST(HandshakeV10Test, HappyPath_CachingSha2Server) {
    std::string salt;
    for (int i = 0; i < 20; ++i) salt.push_back(static_cast<char>('A' + i));
    const uint32_t caps =
        CLIENT_PROTOCOL_41 | CLIENT_SECURE_CONNECTION | CLIENT_PLUGIN_AUTH;

    const std::string payload = MakeHandshakeV10Payload(
        "8.0.32", 7, salt, caps, 0xff, 0x0002, "caching_sha2_password");

    HandshakeV10 hs;
    ASSERT_TRUE(ParseHandshakeV10(payload, &hs));
    EXPECT_EQ(hs.auth_plugin_name, "caching_sha2_password");
    EXPECT_EQ(hs.auth_plugin_data, salt);
}

TEST(HandshakeV10Test, RejectsBadProtocolVersion) {
    std::string payload(1, static_cast<char>(0x09));  // not 10
    payload.append("ignored");
    HandshakeV10 hs;
    EXPECT_FALSE(ParseHandshakeV10(payload, &hs));
}

TEST(HandshakeV10Test, RejectsTruncatedAtServerVersion) {
    // Tag, but no NUL anywhere -> server_version unterminated.
    std::string payload(1, static_cast<char>(kHandshakeV10Tag));
    payload.append(20, 'x');  // no NUL
    HandshakeV10 hs;
    EXPECT_FALSE(ParseHandshakeV10(payload, &hs));
}

TEST(HandshakeV10Test, RejectsTruncatedBeforeSalt) {
    // Build a payload then chop after capability_flags_lo.
    std::string salt(20, '\x01');
    const std::string full = MakeHandshakeV10Payload(
        "8.0.32", 1, salt, CLIENT_PROTOCOL_41 | CLIENT_SECURE_CONNECTION,
        0xff, 0, "");
    // Chop early — keep only protocol+server_version+conn_id+part1+filler+caps_lo.
    const std::string truncated(full.data(), 6 + 1 + 4 + 8 + 1 + 2);
    HandshakeV10 hs;
    EXPECT_FALSE(ParseHandshakeV10(truncated, &hs));
}

ST(HandshakeV10Test, ExtractsFull20ByteSalt) {
    std::string salt(20, 0);
    for (int i = 0; i < 20; ++i) salt[i] = static_cast<char>(0xA0 + i);
    const std::string payload = MakeHandshakeV10Payload(
        "8.0.32", 1, salt,
        CLIENT_PROTOCOL_41 | CLIENT_SECURE_CONNECTION | CLIENT_PLUGIN_AUTH,
        0xff, 0, "mysql_native_password");
    HandshakeV10 hs;
    ASSERT_TRUE(ParseHandshakeV10(payload, &hs));
    EXPECT_EQ(hs.auth_plugin_data.size(), kSaltLen);
    EXPECT_EQ(hs.auth_plugin_data, salt);
}

ST(HandshakeResponse41Test, BuildsExpectedLayout) {
    HandshakeResponse41 req;
    req.capability_flags = CLIENT_PROTOCOL_41 | CLIENT_SECURE_CONNECTION
                         | CLIENT_PLUGIN_AUTH
                         | CLIENT_PLUGIN_AUTH_LENENC_CLIENT_DATA;
    req.max_packet_size = 1u << 24;
    req.character_set = 0x21;
    req.username = "root";
    req.auth_response = std::string(20, '\x42');  // canned scramble
    req.auth_plugin_name = "mysql_native_password";

    std::string payload;
    ASSERT_TRUE(BuildHandshakeResponse41(req, &payload));

    // 4 caps + 4 max_pkt + 1 charset + 23 reserved = 32 bytes fixed prefix
    ASSERT_GE(payload.size(), 32u);
    // Caps roundtrip
    uint32_t caps = static_cast<unsigned char>(payload[0])
        | (static_cast<uint32_t>(static_cast<unsigned char>(payload[1])) << 8)
        | (static_cast<uint32_t>(static_cast<unsigned char>(payload[2])) << 16)
        | (static_cast<uint32_t>(static_cast<unsigned char>(payload[3])) << 24);
    EXPECT_EQ(caps, req.capability_flags);
    // Username + NUL + lenenc(20) + 20 bytes + plugin + NUL
    const char* p = payload.data() + 32;
    EXPECT_EQ(std::string(p, 5), std::string("root\0", 5));
    p += 5;
    EXPECT_EQ(static_cast<unsigned char>(*p), 20u);  // lenenc(20) = 0x14
    ++p;
    EXPECT_EQ(std::string(p, 20), std::string(20, '\x42'));
    p += 20;
    const std::string plugin_nul("mysql_native_password\0", 22);
    EXPECT_EQ(std::string(p, plugin_nul.size()), plugin_nul);
}

ST(HandshakeResponse41Test, OmitsDatabaseWhenFlagAbsent) {
    HandshakeResponse41 req;
    req.capability_flags = CLIENT_PROTOCOL_41 | CLIENT_SECURE_CONNECTION
                         | CLIENT_PLUGIN_AUTH
                         | CLIENT_PLUGIN_AUTH_LENENC_CLIENT_DATA;
    req.max_packet_size = 1u << 24;
    req.character_set = 0x21;
    req.username = "u";
    req.auth_response = std::string(20, '\x01');
    req.database = "mydb";  // should be ignored
    req.auth_plugin_name = "mysql_native_password";

    std::string payload;
    ASSERT_TRUE(BuildHandshakeResponse41(req, &payload));
    EXPECT_EQ(payload.find("mydb"), std::string::npos);
}

ST(HandshakeResponse41Test, IncludesDatabaseWhenFlagSet) {
    HandshakeResponse41 req;
    req.capability_flags = CLIENT_PROTOCOL_41 | CLIENT_SECURE_CONNECTION
                         | CLIENT_PLUGIN_AUTH | CLIENT_CONNECT_WITH_DB
                         | CLIENT_PLUGIN_AUTH_LENENC_CLIENT_DATA;
    req.max_packet_size = 1u << 24;
    req.character_set = 0x21;
    req.username = "u";
    req.auth_response = std::string(20, '\x01');
    req.database = "mydb";
    req.auth_plugin_name = "mysql_native_password";

    std::string payload;
    ASSERT_TRUE(BuildHandshakeResponse41(req, &payload));
    EXPECT_NE(payload.find("mydb"), std::string::npos);
}

ST(HandshakeResponse41Test, HandlesLargeAuthResponseViaLenEncoding) {
    // 256-byte RSA ciphertext — exercises lenenc 0xfc 2-byte branch.
    HandshakeResponse41 req;
    req.capability_flags = CLIENT_PROTOCOL_41 | CLIENT_SECURE_CONNECTION
                         | CLIENT_PLUGIN_AUTH
                         | CLIENT_PLUGIN_AUTH_LENENC_CLIENT_DATA;
    req.max_packet_size = 1u << 24;
    req.character_set = 0x21;
    req.username = "u";
    req.auth_response = std::string(256, '\xAA');
    req.auth_plugin_name = "caching_sha2_password";

    std::string payload;
    ASSERT_TRUE(BuildHandshakeResponse41(req, &payload));
    // lenenc 256 -> 0xfc 0x00 0x01
    const std::string lenenc("\xfc\x00\x01", 3);
    EXPECT_NE(payload.find(lenenc), std::string::npos);
}

