    EXPECT_EQ(DecodeLengthEncodedString(buf, &out, &is_null), 3u);
    EXPECT_FALSE(is_null);
    EXPECT_EQ(out, "hi");
}

TEST(LenencStringTest, EmptyIsNotNull) {
    // Empty string (lenenc 0x00) must NOT be reported as NULL.
