static inline uint64_t rv_clmul(uint64_t a, uint64_t b) {
  uint64_t result;
  __asm__ volatile ("clmul %0, %1, %2" : "=r"(result) : "r"(a), "r"(b));
  return result;
}

static inline uint64_t rv_clmulh(uint64_t a, uint64_t b) {
  uint64_t result;
  __asm__ volatile ("clmulh %0, %1, %2" : "=r"(result) : "r"(a), "r"(b));
  return result;
}

static inline uint32_t rv_crc32c_bitwise(uint32_t crc, const uint8_t* buf,
                                         size_t len) {
  uint32_t c = crc;
  for (size_t i = 0; i < len; ++i) {
    c ^= buf[i];
    for (int k = 0; k < 8; ++k) {
      c = (c >> 1) ^ ((c & 1) ? 0x82F63B78U : 0);
    }
  }
  return c;
}

static inline void rv_fold_pair_xor_data(uint64_t* lo, uint64_t* hi,
                                         uint64_t k0, uint64_t k1,
                                         uint64_t d0, uint64_t d1) {
  uint64_t l = rv_clmul(*lo, k0) ^ rv_clmul(*hi, k1);
  uint64_t h = rv_clmulh(*lo, k0) ^ rv_clmulh(*hi, k1);
  *lo = l ^ d0;
  *hi = h ^ d1;
}

static inline void rv_fold_pair_xor_state(uint64_t* lo, uint64_t* hi,
                                          uint64_t k0, uint64_t k1,
                                          uint64_t s0, uint64_t s1) {
  uint64_t l = rv_clmul(*lo, k0) ^ rv_clmul(*hi, k1);
  uint64_t h = rv_clmulh(*lo, k0) ^ rv_clmulh(*hi, k1);
  *lo = l ^ s0;
  *hi = h ^ s1;
}

static uint32_t rv_crc32c_clmul(uint32_t crc, const char* buf, size_t len) {
  // Convert external CRC to internal register state
  crc ^= 0xFFFFFFFF;

  const uint8_t* p = reinterpret_cast<const uint8_t*>(buf);
  size_t n = len;

  // Small data: use bitwise fallback
  if (n < 64) {
    return rv_crc32c_bitwise(crc, p, n) ^ 0xFFFFFFFF;
  }

  // Align to 16-byte boundary
  uintptr_t mis = (uintptr_t)p & 0xF;
  if (mis) {
    size_t pre = 16 - mis;
    if (pre > n) pre = n;
    crc = rv_crc32c_bitwise(crc, p, pre);
    p += pre;
    n -= pre;
    if (n < 64) {
      return rv_crc32c_bitwise(crc, p, n) ^ 0xFFFFFFFF;
    }
  }

  // Load first 64 bytes and XOR CRC into the first 8 bytes
  uint64_t x0, x1, y0, y1, z0, z1, w0, w1;
  memcpy(&x0, p + 0, 8);
  memcpy(&x1, p + 8, 8);
  memcpy(&y0, p + 16, 8);
  memcpy(&y1, p + 24, 8);
  memcpy(&z0, p + 32, 8);
  memcpy(&z1, p + 40, 8);
  memcpy(&w0, p + 48, 8);
  memcpy(&w1, p + 56, 8);

  x0 ^= (uint64_t)crc;
  p += 64;
  n -= 64;

  const uint64_t k1 = crc32c_fold_const[0];
  const uint64_t k2 = crc32c_fold_const[1];
  const uint64_t k3 = crc32c_fold_const[2];
  const uint64_t k4 = crc32c_fold_const[3];

  // Main loop: fold 64 bytes per iteration using 128-bit folding
  while (n >= 64) {
    uint64_t d0, d1;
    memcpy(&d0, p + 0, 8);
    memcpy(&d1, p + 8, 8);
    rv_fold_pair_xor_data(&x0, &x1, k1, k2, d0, d1);
    memcpy(&d0, p + 16, 8);
    memcpy(&d1, p + 24, 8);
    rv_fold_pair_xor_data(&y0, &y1, k1, k2, d0, d1);
    memcpy(&d0, p + 32, 8);
    memcpy(&d1, p + 40, 8);
    rv_fold_pair_xor_data(&z0, &z1, k1, k2, d0, d1);
    memcpy(&d0, p + 48, 8);
    memcpy(&d1, p + 56, 8);
    rv_fold_pair_xor_data(&w0, &w1, k1, k2, d0, d1);
    p += 64;
    n -= 64;
  }

  // Reduce 4x128-bit to 1x128-bit
  rv_fold_pair_xor_state(&x0, &x1, k3, k4, y0, y1);
  rv_fold_pair_xor_state(&x0, &x1, k3, k4, z0, z1);
  rv_fold_pair_xor_state(&x0, &x1, k3, k4, w0, w1);

  // Barrett reduction: 128-bit -> 32-bit CRC
  uint64_t t4 = rv_clmul(x0, RV_CRC32C_CONST_1);
  uint64_t t3 = rv_clmulh(x0, RV_CRC32C_CONST_1);
  uint64_t t1 = x1 ^ t4;
  t4 = t1 & RV_CRC32_MASK32;
  t1 >>= 32;
  uint64_t t0 = rv_clmul(t4, RV_CRC32C_CONST_0);
  t3 = (t3 << 32) ^ t1 ^ t0;

  t4 = t3 & RV_CRC32_MASK32;
  t4 = rv_clmul(t4, RV_CRC32C_CONST_QUO);
  t4 &= RV_CRC32_MASK32;
  t4 = rv_clmul(t4, RV_CRC32C_CONST_POLY);
  t4 ^= t3;

  uint32_t c = (uint32_t)((t4 >> 32) & RV_CRC32_MASK32);
  // Handle remaining bytes
  if (n) {
    c = rv_crc32c_bitwise(c, p, n);
  }
  // Convert internal register state to external CRC
  return c ^ 0xFFFFFFFF;
}

static bool isZbc() {
  static const bool zbc_supported = []() {
    FILE* f = fopen("/proc/cpuinfo", "r");
    if (!f) return false;
    bool supported = false;
    char line[1024];
    while (fgets(line, sizeof(line), f)) {
      if (strstr(line, "isa") || strstr(line, "hart isa")) {
        char* colon = strchr(line, ':');
        if (colon) {
          if (strstr(colon, "_zbc") || strstr(colon, "zbc")) {
            supported = true;
            break;
          }
        }
      }
    }
    fclose(f);
    return supported;
  }();
  return zbc_supported;
}

bool ShouldAllow() const {
        const int64_t now_us = butil::cpuwide_time_us();
        int64_t last_us = _last_update_us.load(butil::memory_order_relaxed);
        double ratio = _cached_ratio.load(butil::memory_order_relaxed);

        if (now_us - last_us >= _update_interval_us) {
            if (_last_update_us.compare_exchange_strong(
                    last_us, now_us, butil::memory_order_relaxed)) {
                int64_t total = _total_window.get_value();
                int64_t backup = _backup_window.get_value();
                // Fall back to cumulative counts when the window has no
                // sampled data yet (cold-start within the first few seconds).
                if (total <= 0) {
                    total = _total_count.get_value();
                    backup = _backup_count.get_value();
                }
                if (total > 0) {
                    ratio = static_cast<double>(backup) / total;
                } else if (backup > 0) {
                    // Backups issued but no completions in window yet (latency spike).
                    // Be conservative to prevent backup storms.
                    ratio = 1.0;
                } else {
                    // True cold-start: no traffic yet. Allow freely.
                    ratio = 0.0;
                }
                _cached_ratio.store(ratio, butil::memory_order_relaxed);
            }
        }

        bool allow = ratio < _max_backup_ratio;
        if (allow) {
            // Count backup decisions immediately for faster feedback
            // during latency spikes (before RPCs complete).
            _backup_count << 1;
        }
        return allow;
    }

void OnRPCEnd(const Controller* /*controller*/) {
        // Count each completed user-level RPC (called once per RPC, not per leg).
        // Backup decisions are counted in ShouldAllow() at decision time for
        // faster feedback. As a result, the effective suppression threshold is
        // (backup_count / total_count), where total_count is the number of
        // user RPCs that have completed.
        _total_count << 1;
    }

BackupRequestPolicy* CreateRateLimitedBackupPolicy(
    const RateLimitedBackupPolicyOptions& options) {
    if (options.backup_request_ms < -1) {
        LOG(ERROR) << "Invalid backup_request_ms=" << options.backup_request_ms
                   << ", must be >= -1 (-1 means inherit from ChannelOptions)";
        return NULL;
    }
    if (options.max_backup_ratio <= 0 || options.max_backup_ratio > 1.0) {
        LOG(ERROR) << "Invalid max_backup_ratio=" << options.max_backup_ratio
                   << ", must be in (0, 1]";
        return NULL;
    }
    if (options.window_size_seconds < 1 || options.window_size_seconds > 3600) {
        LOG(ERROR) << "Invalid window_size_seconds=" << options.window_size_seconds
                   << ", must be in [1, 3600]";
        return NULL;
    }
    if (options.update_interval_seconds < 1) {
        LOG(ERROR) << "Invalid update_interval_seconds="
                   << options.update_interval_seconds << ", must be >= 1";
        return NULL;
    }
    if (options.update_interval_seconds > options.window_size_seconds) {
        LOG(WARNING) << "update_interval_seconds=" << options.update_interval_seconds
                     << " exceeds window_size_seconds=" << options.window_size_seconds
                     << "; the ratio window will rarely refresh within its own period";
    }
    // Plain new (without std::nothrow): brpc follows the project-wide convention
    // of letting OOM throw/abort rather than returning NULL. NULL return from
    // this factory already signals invalid parameters, not allocation failure.
    return new RateLimitedBackupPolicy(
        options.backup_request_ms, options.max_backup_ratio,
        options.window_size_seconds, options.update_interval_seconds);
}

