TEST_F(RateLimitedBackupPolicyTest, ValidMaxRatioAtBoundary) {
    brpc::RateLimitedBackupPolicyOptions opts;
    opts.backup_request_ms = 50;
    opts.max_backup_ratio = 1.0;
    std::unique_ptr<brpc::BackupRequestPolicy> p(
        brpc::CreateRateLimitedBackupPolicy(opts));
    ASSERT_TRUE(p != NULL);
    // With max_backup_ratio=1.0 and true cold start (total==0, backup==0),
    // ShouldAllow() sets ratio=0.0 (free pass). The conservative ratio=1.0
    // path only applies when backup>0 but total==0 (latency spike with no
    // completions yet). At absolute cold start DoBackup() must return true.
    ASSERT_TRUE(p->DoBackup(NULL));   // cold start: ratio=0.0 < 1.0, allow
}

TEST_F(RateLimitedBackupPolicyTest, ColdStartAllowsBackup) {
    brpc::RateLimitedBackupPolicyOptions opts;
    opts.backup_request_ms = 10;
    opts.max_backup_ratio = 0.1;
    opts.update_interval_seconds = 1;
    std::unique_ptr<brpc::BackupRequestPolicy> p(
        brpc::CreateRateLimitedBackupPolicy(opts));
    ASSERT_TRUE(p != NULL);
    ASSERT_TRUE(p->DoBackup(NULL));
}

ST_F(RateLimitedBackupPolicyTest, AfterColdStartBackupSuppressedUntilRpcCompletes) {
    brpc::RateLimitedBackupPolicyOptions opts;
    opts.backup_request_ms = 10;
    opts.max_backup_ratio = 0.1;
    opts.window_size_seconds = 1;
    opts.update_interval_seconds = 1;
    std::unique_ptr<brpc::BackupRequestPolicy> p(
        brpc::CreateRateLimitedBackupPolicy(opts));
    ASSERT_TRUE(p != NULL);
    // First call fires (cold start: total=0, backup=0 → ratio=0.0 → allow).
    ASSERT_TRUE(p->DoBackup(NULL));
    // Wait for the update interval to elapse so the ratio refreshes.
    // After refresh: total=0 but backup=1 → conservative path sets ratio=1.0,
    // which is >= max_backup_ratio (0.1), so DoBackup() must return false.
    bthread_usleep(1200000); // 1.2s > update_interval_seconds=1
    ASSERT_FALSE(p->DoBackup(NULL));
}

// Aft

ateLimitedBackupPolicyTest, OnRPCEndDrivesRatioDownAndReAllows) {
    brpc::RateLimitedBackupPolicyOptions opts;
    opts.backup_request_ms = 10;
    opts.max_backup_ratio = 0.5;
    opts.window_size_seconds = 1;
    opts.update_interval_seconds = 1;
    std::unique_ptr<brpc::BackupRequestPolicy> p(
        brpc::CreateRateLimitedBackupPolicy(opts));
    ASSERT_TRUE(p != NULL);
    // Fire many backup decisions so backup_count >> total_count,
    // pushing the ratio above max_backup_ratio.
    for (int i = 0; i < 20; ++i) {
        p->DoBackup(NULL);
    }
    // Wait for update interval so the ratio is refreshed above threshold.
    bthread_usleep(1200000); // 1.2s
    ASSERT_FALSE(p->DoBackup(NULL));
    // Now complete many more RPCs than backups fired to bring ratio below 0.5.
    // 20 backup decisions already counted; need total_count > 20/0.5 = 40.
    for (int i = 0; i < 50; ++i) {
        p->OnRPCEnd(NULL);
    }
    // Wait for the ratio cache to refresh.
    bthread_usleep(1200000); // 1.2s
    // Ratio is now ~20/50 = 0.4 < max_backup_ratio (0.5), so backup is re-allowed.
    ASSERT_TRUE(p->DoBackup(NULL));
}

void SetUp() override {
        // Save original values
        orig_sample_window_size_ms_ = brpc::policy::FLAGS_auto_cl_sample_window_size_ms;
        orig_min_sample_count_ = brpc::policy::FLAGS_auto_cl_min_sample_count;
        orig_max_sample_count_ = brpc::policy::FLAGS_auto_cl_max_sample_count;
        orig_enable_error_punish_ = brpc::policy::FLAGS_auto_cl_enable_error_punish;
        orig_fail_punish_ratio_ = brpc::policy::FLAGS_auto_cl_fail_punish_ratio;
        orig_error_rate_threshold_ = brpc::policy::FLAGS_auto_cl_error_rate_punish_threshold;

        // Set test-friendly values
        brpc::policy::FLAGS_auto_cl_sample_window_size_ms = 1000;
        brpc::policy::FLAGS_auto_cl_min_sample_count = 5;
        brpc::policy::FLAGS_auto_cl_max_sample_count = 200;
        brpc::policy::FLAGS_auto_cl_enable_error_punish = true;
        brpc::policy::FLAGS_auto_cl_fail_punish_ratio = 1.0;
    }

void TearDown() override {
        // Restore original values
        brpc::policy::FLAGS_auto_cl_sample_window_size_ms = orig_sample_window_size_ms_;
        brpc::policy::FLAGS_auto_cl_min_sample_count = orig_min_sample_count_;
        brpc::policy::FLAGS_auto_cl_max_sample_count = orig_max_sample_count_;
        brpc::policy::FLAGS_auto_cl_enable_error_punish = orig_enable_error_punish_;
        brpc::policy::FLAGS_auto_cl_fail_punish_ratio = orig_fail_punish_ratio_;
        brpc::policy::FLAGS_auto_cl_error_rate_punish_threshold = orig_error_rate_threshold_;
    }

void AddSamplesAndTriggerWindow(brpc::policy::AutoConcurrencyLimiter& limiter,
                                 int succ_count, int64_t succ_latency,
                                 int fail_count, int64_t fail_latency) {
    ASSERT_GT(succ_count, 0) << "Need at least 1 success to trigger window";
    int64_t now = butil::gettimeofday_us();

    // Add successful samples (reserve one for the trigger)
    for (int i = 0; i < succ_count - 1; ++i) {
        limiter.AddSample(0, succ_latency, now);
    }
    // Add failed samples
    for (int i = 0; i < fail_count; ++i) {
        limiter.AddSample(1, fail_latency, now);
    }

    // Advance timestamp past window expiry instead of sleeping
    int64_t after_window = now + brpc::policy::FLAGS_auto_cl_sample_window_size_ms * 1000 + 1000;

    // Use the final success sample to trigger window submission
    limiter.AddSample(0, succ_latency, after_window);
}

TEST_F(AutoConcurrencyLimiterTest, ThresholdZeroPreservesOriginalBehavior) {
    brpc::policy::FLAGS_auto_cl_error_rate_punish_threshold = 0;
    brpc::policy::FLAGS_auto_cl_sample_window_size_ms = 10;

    brpc::policy::AutoConcurrencyLimiter limiter;
    AddSamplesAndTriggerWindow(limiter, 90, 100, 10, 1000);

    // 10% error rate, threshold=0 means full punishment applied
    // avg_latency = ceil((10*1000 + 90*100) / 90) = ceil(211.1) = 212us
    ASSERT_GT(limiter._min_latency_us, 180);
    ASSERT_LT(limiter._min_latency_us, 250);
}

TEST_F(AutoConcurrencyLimiterTest, BelowThresholdZeroPunishment) {
    brpc::policy::FLAGS_auto_cl_error_rate_punish_threshold = 0.2;  // 20% threshold
    brpc::policy::FLAGS_auto_cl_sample_window_size_ms = 10;

    brpc::policy::AutoConcurrencyLimiter limiter;
    AddSamplesAndTriggerWindow(limiter, 90, 100, 10, 1000);

    // 10% error rate < 20% threshold, punishment should be zero
    // avg_latency = 90*100 / 90 = 100us (no inflation)
    ASSERT_GT(limiter._min_latency_us, 80);
    ASSERT_LT(limiter._min_latency_us, 130);
}

TEST_F(AutoConcurrencyLimiterTest, ExactlyAtThresholdZeroPunishment) {
    brpc::policy::FLAGS_auto_cl_error_rate_punish_threshold = 0.1;  // 10% threshold
    brpc::policy::FLAGS_auto_cl_sample_window_size_ms = 10;

    brpc::policy::AutoConcurrencyLimiter limiter;
    AddSamplesAndTriggerWindow(limiter, 90, 100, 10, 1000);

    // 10% error rate == 10% threshold, punishment should be zero
    // avg_latency = 90*100 / 90 = 100us
    ASSERT_GT(limiter._min_latency_us, 80);
    ASSERT_LT(limiter._min_latency_us, 130);
}

TEST_F(AutoConcurrencyLimiterTest, AboveThresholdLinearScaling) {
    brpc::policy::FLAGS_auto_cl_error_rate_punish_threshold = 0.1;  // 10% threshold
    brpc::policy::FLAGS_auto_cl_sample_window_size_ms = 10;

    // Case A: 50% error rate
    // punish_factor = (0.5 - 0.1) / (1.0 - 0.1) = 4/9 ≈ 0.444
    // failed_punish = 50 * 1000 * (4/9) = 22222.2us
    // avg_latency = ceil((22222.2 + 50*100) / 50) = ceil(544.4) = 545us
    {
        brpc::policy::AutoConcurrencyLimiter limiter;
        AddSamplesAndTriggerWindow(limiter, 50, 100, 50, 1000);
        ASSERT_GT(limiter._min_latency_us, 450);
        ASSERT_LT(limiter._min_latency_us, 650);
    }

    // Case B: 90% error rate (near full punishment)
    // punish_factor = (0.9 - 0.1) / (1.0 - 0.1) = 8/9 ≈ 0.889
    // failed_punish = 90 * 1000 * (8/9) = 80000us
    // avg_latency = ceil((80000 + 10*100) / 10) = ceil(8100) = 8100us
    {
        brpc::policy::AutoConcurrencyLimiter limiter;
        AddSamplesAndTriggerWindow(limiter, 10, 100, 90, 1000);
        ASSERT_GT(limiter._min_latency_us, 7000);
        ASSERT_LT(limiter._min_latency_us, 9000);
    }
}

id require(bool condition, const std::string &message) {
    if (!condition) {
        std::cerr << message << std::endl;
        std::exit(1);
    }
}

id runCase(const ParseCase &test) {
    VP9RtpDecoder decoder;
    std::vector<std::string> frames;
    decoder.addDelegate([&](const Frame::Ptr &frame) {
        frames.emplace_back(frame->data(), frame->size());
        return true;
    });

    auto packet = test.packet;
    packet[0] |= 0x0C; // B/E: make a successful descriptor dispatch one complete frame.
    RtpInfo rtp_info(0x12345678, 1400, 90000, 98, 0, 0);
    auto rtp = rtp_info.makeRtp(TrackVideo, packet.data(), packet.size(), true, 100);
    require(rtp != nullptr, std::string(test.name) + ": failed to create RTP packet");
    decoder.inputRtp(rtp, false);

    const bool should_output = test.expected_offset >= 0;
    require(frames.size() == (should_output ? 1U : 0U),
            std::string(test.name) + ": unexpected decoded frame count " + std::to_string(frames.size()));
    if (should_output) {
        require(frames[0].size() == packet.size() - static_cast<size_t>(test.expected_offset),
                std::string(test.name) + ": decoded frame has an unexpected size");
        require(frames[0] == std::string(reinterpret_cast<const char *>(packet.data() + test.expected_offset),
                                        packet.size() - static_cast<size_t>(test.expected_offset)),
                std::string(test.name) + ": decoded frame payload does not match RTP frame payload");
    }
}

id testParseFailureDropsCurrentFrame(const char *name, const std::vector<unsigned char> &invalid_payload) {
    VP9RtpDecoder decoder;
    std::vector<std::string> frames;
    decoder.addDelegate([&](const Frame::Ptr &frame) {
        frames.emplace_back(frame->data(), frame->size());
        return true;
    });

    RtpInfo rtp_info(0x12345678, 1400, 90000, 98, 0, 0);
    auto input = [&](const std::vector<unsigned char> &payload, bool mark) {
        auto rtp = rtp_info.makeRtp(TrackVideo, payload.data(), payload.size(), mark, 100);
        require(rtp != nullptr, std::string(name) + ": failed to create RTP packet");
        decoder.inputRtp(rtp, false);
    };

    input({ 0x08, 0x80, 0x11 }, false); // B: begin assembling a frame.
    input(invalid_payload, false);
    input({ 0x04, 0x22 }, true);        // E: must not emit the incomplete frame.
    require(frames.empty(), std::string(name) + ": parse failure emitted a partial VP9 frame");

    input({ 0x0C, 0x80, 0x33 }, true); // A new complete frame must recover normally.
    require(frames.size() == 1, std::string(name) + ": decoder did not recover after a parse failure");
    require(frames[0] == std::string("\x80\x33", 2),
            std::string(name) + ": recovered VP9 frame payload does not match");
}

id testParseFailureDropsGop() {
    VP9RtpDecoder decoder;
    std::vector<std::string> frames;
    decoder.addDelegate([&](const Frame::Ptr &frame) {
        frames.emplace_back(frame->data(), frame->size());
        return true;
    });

    RtpInfo rtp_info(0x12345678, 1400, 90000, 98, 0, 0);
    auto input = [&](const std::vector<unsigned char> &payload) {
        auto rtp = rtp_info.makeRtp(TrackVideo, payload.data(), payload.size(), true, 100);
        require(rtp != nullptr, "failed to create RTP packet for GOP recovery test");
        decoder.inputRtp(rtp, false);
    };

    input({ 0x50, 0x03 });             // Reject a truncated P_DIFF chain.
    input({ 0x4C, 0x00, 0x44 });       // Suppress a dependent P-frame.
    require(frames.empty(), "parse failure did not suppress the damaged GOP");

    input({ 0x0C, 0x80, 0x55 });       // A keyframe starts a new GOP.
    input({ 0x4C, 0x00, 0x66 });       // Its dependent P-frame is valid again.
    require(frames.size() == 2, "decoder did not recover at the next VP9 keyframe");
    require(frames[0] == std::string("\x80\x55", 2), "recovery keyframe payload does not match");
    require(frames[1] == std::string("\x00\x66", 2), "recovered P-frame payload does not match");
}

t main() {
    // The last byte in every successful case is frame payload. These cases cover
    // all L/F/P combinations and make incorrect descriptor consumption visible.
    const std::vector<ParseCase> combinations = {
        { "L0 F0 P0", { 0x00, 0xAA }, 1 },
        { "L0 F0 P1", { 0x40, 0xAA }, 1 },
        { "L0 F1 P0", { 0x10, 0xAA }, 1 },
        { "L0 F1 P1", { 0x50, 0x02, 0xAA }, 2 },
        { "L1 F0 P0", { 0x20, 0x00, 0x33, 0xAA }, 3 },
        { "L1 F0 P1", { 0x60, 0x00, 0x33, 0xAA }, 3 },
        { "L1 F1 P0 does not consume P_DIFF", { 0x30, 0x00, 0xAA }, 2 },
        { "L1 F1 P1 consumes P_DIFF once", { 0x70, 0x00, 0x02, 0xAA }, 3 },
    };
    for (const auto &test : combinations) {
        runCase(test);
    }

    runCase({ "three references", { 0x50, 0x03, 0x05, 0x06, 0xAA }, 4 });
    runCase({ "truncated reference chain", { 0x50, 0x03 }, -1 });
    runCase({ "more than three references", { 0x50, 0x03, 0x05, 0x07, 0x08, 0xAA }, -1 });
    runCase({ "short picture ID", { 0x80, 0x12, 0xAA }, 2 });
    runCase({ "large picture ID", { 0x80, 0x81, 0x23, 0xAA }, 3 });
    runCase({ "truncated large picture ID", { 0x80, 0x81 }, -1 });
    runCase({ "resolution", { 0x02, 0x10, 0x07, 0x80, 0x04, 0x38, 0xAA }, 6 });
    runCase({ "truncated resolution", { 0x02, 0x10, 0x07, 0x80, 0x04 }, -1 });

    // V=1, G=1, N_G=2. Each GOF frame byte is followed immediately by
    // exactly the number of reference indices it declares.
    runCase({ "GOF exact boundary", { 0x02, 0x08, 0x02, 0x04, 0x11, 0x08, 0x22, 0x33, 0xAA }, 8 });
    runCase({ "GOF truncated references", { 0x02, 0x08, 0x01, 0x08, 0x22 }, -1 });

    runCase({ "reject descriptor-only payload", { 0x00 }, -1 });
    runCase({ "reject layer-descriptor-only payload", { 0x30, 0x00 }, -1 });
    testParseFailureDropsCurrentFrame("truncated P_DIFF", { 0x50, 0x03 });
    testParseFailureDropsCurrentFrame("descriptor-only middle packet", { 0x00 });
    testParseFailureDropsGop();
    return 0;
}

AMFDecoder::DepthGuard::DepthGuard(AMFDecoder &decoder) : _decoder(decoder) {
    if (_decoder.depth >= AMFDecoder::kMaxDepth) {
        throw std::runtime_error("Maximum AMF nesting depth exceeded");
    }
    ++_decoder.depth;
}

atic const char *container_name(ContainerType type) {
    switch (type) {
    case ContainerType::Object:
        return "object";
    case ContainerType::EcmaArray:
        return "ECMA array";
    case ContainerType::StrictArray:
        return "strict array";
    }
    return "unknown";
}

atic AMFType container_amf_type(ContainerType type) {
    switch (type) {
    case ContainerType::Object:
        return AMF_OBJECT;
    case ContainerType::EcmaArray:
        return AMF_ECMA_ARRAY;
    case ContainerType::StrictArray:
        return AMF_STRICT_ARRAY;
    }
    return AMF_UNDEFINED;
}

atic string make_nested_container(ContainerType type, size_t depth) {
    string result;
    for (size_t i = 0; i < depth; ++i) {
        switch (type) {
        case ContainerType::Object:
            result.append("\x03\x00\x01x", 4);
            break;
        case ContainerType::EcmaArray:
            result.append("\x08\x00\x00\x00\x01\x00\x01x", 8);
            break;
        case ContainerType::StrictArray:
            result.append("\x0A\x00\x00\x00\x01", 5);
            break;
        }
    }
    result.append("\x05", 1);
    if (type != ContainerType::StrictArray) {
        for (size_t i = 0; i < depth; ++i) {
            result.append("\x00\x00\x09", 3);
        }
    }
    return result;
}

atic bool accepts_nesting_limit(ContainerType type) {
    BufferLikeString input(make_nested_container(type, 64));
    AMFDecoder decoder(input, 0);
    try {
        return decoder.load<AMFValue>().type() == container_amf_type(type);
    } catch (const runtime_error &) {
        return false;
    }
}

atic bool rejects_excessive_nesting(ContainerType type) {
    BufferLikeString input(make_nested_container(type, 65));
    AMFDecoder decoder(input, 0);
    try {
        decoder.load<AMFValue>();
    } catch (const runtime_error &ex) {
        return string(ex.what()) == "Maximum AMF nesting depth exceeded";
    }
    return false;
}

t main() {
    const ContainerType types[] = {
        ContainerType::Object,
        ContainerType::EcmaArray,
        ContainerType::StrictArray,
    };

    for (auto type : types) {
        if (!accepts_nesting_limit(type)) {
            cerr << "AMF " << container_name(type) << " at the nesting limit was not decoded" << endl;
            return 1;
        }
        if (!rejects_excessive_nesting(type)) {
            cerr << "AMF " << container_name(type) << " beyond the nesting limit was not rejected" << endl;
            return 2;
        }
    }

    return 0;
}

static bool connectionContainsClose(const string &connection) {
    for (auto token : split(connection, ",")) {
        if (strToLower(trim(std::move(token))) == "close") {
            return true;
        }
    }
    return false;
}

std::shared_ptr<TurboModule> DefaultTurboModules::getTurboModule(
    const std::string &name,
    const std::shared_ptr<CallInvoker> &jsInvoker) {
  if (name == NativeReactNativeFeatureFlags::kModuleName) {
    return std::make_shared<NativeReactNativeFeatureFlags>(jsInvoker);
  }

  if (name == NativeMicrotasks::kModuleName) {
    return std::make_shared<NativeMicrotasks>(jsInvoker);
  }

  if (name == NativeIdleCallbacks::kModuleName) {
    return std::make_shared<NativeIdleCallbacks>(jsInvoker);
  }

  if (name == NativeDOM::kModuleName) {
    return std::make_shared<NativeDOM>(jsInvoker);
  }

  if (name == NativePerformance::kModuleName) {
    return std::make_shared<NativePerformance>(jsInvoker);
  }

  if (ReactNativeFeatureFlags::enableIntersectionObserverByDefault()) {
    if (name == NativeIntersectionObserver::kModuleName) {
      return std::make_shared<NativeIntersectionObserver>(jsInvoker);
    }
  }

  if (ReactNativeFeatureFlags::enableMutationObserverByDefault()) {
    if (name == NativeMutationObserver::kModuleName) {
      return std::make_shared<NativeMutationObserver>(jsInvoker);
    }
  }

#ifdef REACT_NATIVE_DEBUGGER_ENABLED_DEVONLY
  if (name == DevToolsRuntimeSettingsModule::kModuleName) {
    return std::make_shared<DevToolsRuntimeSettingsModule>(jsInvoker);
  }
#endif

  return nullptr;
}

static HighResTimeStamp getTimestampFromTouchEvent(const TouchEvent& event) {
  if (!event.changedTouches.empty()) {
    const auto& firstChangedTouch = *event.changedTouches.begin();
    return firstChangedTouch.timeStamp;
  }
  return HighResTimeStamp::now();
}

void UIManager::setViewTransitionDelegate(
    UIManagerViewTransitionDelegate* delegate) {
  if (ReactNativeFeatureFlags::viewTransitionEnabled()) {
    viewTransitionDelegate_ = delegate;
  }
}

void FabricUIManager::schedulerShouldMergeReactRevision(facebook::react::SurfaceId surfaceId) {
  m_context.UIDispatcher().Post([surfaceId, self = shared_from_this()]() {
    std::lock_guard lock(self->m_schedulerMutex);
    if (self->m_scheduler) {
      self->m_scheduler->getUIManager()->getShadowTreeRegistry().visit(
          surfaceId, [](const facebook::react::ShadowTree &shadowTree) { shadowTree.mergeReactRevision(); });
    }
  });
}

void UIManager::shadowTreeDidFinishReactCommit(
    const ShadowTree& shadowTree) const {
  if (delegate_ != nullptr) {
    delegate_->uiManagerDidFinishReactCommit(shadowTree);
  }
}

void UIManager::shadowTreeDidPromoteReactRevision(
    const ShadowTree& shadowTree) const {
  if (delegate_ != nullptr) {
    delegate_->uiManagerDidPromoteReactRevision(shadowTree);
  }
}

