void packAnimatedProp(
    folly::dynamic& dyn,
    const std::unique_ptr<AnimatedPropBase>& animatedProp) {
  switch (animatedProp->propName) {
    case OPACITY:
      packOpacity(dyn, *animatedProp);
      break;

    case TRANSFORM:
      packTransform(dyn, *animatedProp);
      break;

    case TRANSFORM_ORIGIN:
      packTransformOrigin(dyn, *animatedProp);
      break;

    case BACKGROUND_COLOR:
      packBackgroundColor(dyn, *animatedProp);
      break;

    case BORDER_RADII:
      packBorderRadii(dyn, *animatedProp);
      break;

    case SHADOW_COLOR:
      packShadowColor(dyn, *animatedProp);
      break;

    case SHADOW_OFFSET:
      packShadowOffset(dyn, *animatedProp);
      break;

    case SHADOW_OPACITY:
      packShadowOpacity(dyn, *animatedProp);
      break;

    case SHADOW_RADIUS:
      packShadowRadius(dyn, *animatedProp);
      break;

    case BORDER_COLOR:
      packBorderColor(dyn, *animatedProp);
      break;

    case FILTER:
      packFilter(dyn, *animatedProp);
      break;

    case OUTLINE_COLOR:
      packOutlineColor(dyn, *animatedProp);
      break;

    case OUTLINE_OFFSET:
      packOutlineOffset(dyn, *animatedProp);
      break;

    case OUTLINE_STYLE:
      packOutlineStyle(dyn, *animatedProp);
      break;

    case OUTLINE_WIDTH:
      packOutlineWidth(dyn, *animatedProp);
      break;

    case BORDER_CURVES:
      packBorderCurves(dyn, *animatedProp);
      break;

    case BORDER_STYLES:
      packBorderStyles(dyn, *animatedProp);
      break;

    case POINTER_EVENTS:
      packPointerEvents(dyn, *animatedProp);
      break;

    case ISOLATION:
      packIsolation(dyn, *animatedProp);
      break;

    case CURSOR:
      packCursor(dyn, *animatedProp);
      break;

    case BOX_SHADOW:
      packBoxShadow(dyn, *animatedProp);
      break;

    case MIX_BLEND_MODE:
      packMixBlendMode(dyn, *animatedProp);
      break;

    case BACKFACE_VISIBILITY:
      packBackfaceVisibility(dyn, *animatedProp);
      break;

    case WIDTH:
    case HEIGHT:
    case FLEX:
    case PADDING:
    case MARGIN:
    case POSITION:
    case BORDER_WIDTH:
    case ALIGN_CONTENT:
    case ALIGN_ITEMS:
    case ALIGN_SELF:
    case ASPECT_RATIO:
    case BOX_SIZING:
    case DISPLAY:
    case FLEX_BASIS:
    case FLEX_DIRECTION:
    case ROW_GAP:
    case COLUMN_GAP:
    case FLEX_GROW:
    case FLEX_SHRINK:
    case FLEX_WRAP:
    case JUSTIFY_CONTENT:
    case MAX_HEIGHT:
    case MAX_WIDTH:
    case MIN_HEIGHT:
    case MIN_WIDTH:
    case STYLE_OVERFLOW:
    case POSITION_TYPE:
    case Z_INDEX:
    case DIRECTION:
      throw std::runtime_error("Tried to synchronously update layout props");
    default:
      throw std::runtime_error("Unknown animated prop");
  }
}

folly::dynamic packAnimatedProps(const AnimatedProps& animatedProps) {
  auto dyn = animatedProps.rawProps ? animatedProps.rawProps->toDynamic()
                                    : folly::dynamic::object();

  for (auto& animatedProp : animatedProps.props) {
    packAnimatedProp(dyn, animatedProp);
  }

  return dyn;
}

MapBuffer::MapBuffer(std::vector<uint8_t> data) : bytes_(std::move(data)) {
  auto header = reinterpret_cast<const Header*>(bytes_.data());
  count_ = header->count;

  if (static_cast<size_t>(header->bufferSize) != bytes_.size()) { // [Windows #16261]
    LOG(ERROR) << "Error: Data size does not match, expected "
               << header->bufferSize << " found: " << bytes_.size();
    abort();
  }
}

int32_t MapBuffer::getKeyBucket(Key key) const {
  int32_t lo = 0;
  int32_t hi = count_ - 1;
  while (lo <= hi) {
    int32_t mid = (lo + hi) >> 1;

    Key midVal =
        *reinterpret_cast<const Key*>(bytes_.data() + bucketOffset(mid));

    if (midVal < key) {
      lo = mid + 1;
    } else if (midVal > key) {
      hi = mid - 1;
    } else {
      return mid;
    }
  }

  return -1;
}

int32_t MapBuffer::getInt(Key key) const {
  auto bucketIndex = getKeyBucket(key);
  react_native_assert(bucketIndex != -1 && "Key not found in MapBuffer");
  if (bucketIndex == -1) {
    return 0;
  }

  return getIntAtBucket(bucketIndex);
}

int64_t MapBuffer::getLong(Key key) const {
  auto bucketIndex = getKeyBucket(key);
  react_native_assert(bucketIndex != -1 && "Key not found in MapBuffer");
  if (bucketIndex == -1) {
    return 0;
  }

  return *reinterpret_cast<const int64_t*>(
      bytes_.data() + valueOffset(bucketIndex));
}

double MapBuffer::getDouble(Key key) const {
  auto bucketIndex = getKeyBucket(key);
  react_native_assert(bucketIndex != -1 && "Key not found in MapBuffer");
  if (bucketIndex == -1) {
    return 0;
  }

  return *reinterpret_cast<const double*>(
      bytes_.data() + valueOffset(bucketIndex));
}

int32_t MapBuffer::getDynamicDataOffset() const {
  // The start of dynamic data can be calculated as the offset of the next
  // key in the map
  return bucketOffset(count_);
}

std::string MapBuffer::getString(Key key) const {
  auto bucketIndex = getKeyBucket(key);
  react_native_assert(bucketIndex != -1 && "Key not found in MapBuffer");
  if (bucketIndex == -1) {
    return "";
  }

  int32_t offset = getDynamicDataOffset() + getIntAtBucket(bucketIndex);
  int32_t stringLength =
      *reinterpret_cast<const int32_t*>(bytes_.data() + offset);
  const uint8_t* stringPtr = bytes_.data() + offset + sizeof(int);

  return {stringPtr, stringPtr + stringLength};
}

MapBuffer MapBuffer::getMapBuffer(Key key) const {
  auto bucketIndex = getKeyBucket(key);
  react_native_assert(bucketIndex != -1 && "Key not found in MapBuffer");
  if (bucketIndex == -1) {
    return MapBufferBuilder::EMPTY();
  }

  int32_t offset = getDynamicDataOffset() + getIntAtBucket(bucketIndex);
  int32_t mapBufferLength =
      *reinterpret_cast<const int32_t*>(bytes_.data() + offset);
  int32_t maxLength = static_cast<int32_t>(bytes_.size() - offset - sizeof(int32_t)); // [Windows #16261]
  if (mapBufferLength > maxLength) {
    mapBufferLength = maxLength;
  }

  std::vector<uint8_t> value(mapBufferLength);

  memcpy(
      value.data(), bytes_.data() + offset + sizeof(int32_t), mapBufferLength);

  return MapBuffer(std::move(value));
}

std::vector<MapBuffer> MapBuffer::getMapBufferList(MapBuffer::Key key) const {
  auto bucketIndex = getKeyBucket(key);
  react_native_assert(bucketIndex != -1 && "Key not found in MapBuffer");
  if (bucketIndex == -1) {
    return {};
  }

  std::vector<MapBuffer> mapBufferList;
  int32_t offset = getDynamicDataOffset() + getIntAtBucket(bucketIndex);
  int32_t mapBufferListLength =
      *reinterpret_cast<const int32_t*>(bytes_.data() + offset);
  offset = offset + sizeof(uint32_t);

  int32_t curLen = 0;
  while (curLen < mapBufferListLength) {
    int32_t mapBufferLength =
        *reinterpret_cast<const int32_t*>(bytes_.data() + offset + curLen);
    curLen = curLen + sizeof(uint32_t);
    std::vector<uint8_t> value(mapBufferLength);
    memcpy(value.data(), bytes_.data() + offset + curLen, mapBufferLength);
    mapBufferList.emplace_back(std::move(value));
    curLen = curLen + mapBufferLength;
  }
  return mapBufferList;
}

std::string BufferToString(const winrt::Windows::Storage::Streams::IBuffer &buffer) {
  std::string result(buffer.Length(), '\0');
  if (!result.empty()) {
    auto reader = winrt::Windows::Storage::Streams::DataReader::FromBuffer(buffer);
    reader.ReadBytes(winrt::array_view<uint8_t>{
        reinterpret_cast<uint8_t *>(&result[0]), reinterpret_cast<uint8_t *>(&result[result.length()])});
  }
  return result;
}

winrt::Windows::Storage::Streams::IBuffer BytesToBuffer(const void *data, uint32_t size) {
  winrt::Windows::Storage::Streams::DataWriter writer;
  auto bytes = static_cast<const uint8_t *>(data);
  writer.WriteBytes(winrt::array_view<const uint8_t>(bytes, bytes + size));
  return writer.DetachBuffer();
}

winrt::Windows::Foundation::IAsyncOperation<winrt::Windows::Web::Http::HttpStatusCode> PollForLiveReload(
    const std::string &url) {
    auto buffer = GetJavaScriptFromServerAsync(bundleUrl).get();
    std::string result(buffer.Length(), '\0');
    if (!result.empty()) {
      auto reader = winrt::Windows::Storage::Streams::DataReader::FromBuffer(buffer);
      reader.ReadBytes(winrt::array_view<uint8_t>{
          reinterpret_cast<uint8_t *>(&result[0]), reinterpret_cast<uint8_t *>(&result[result.length()])});
    }
    return std::make_pair(std::move(result), true);
  }

bool MatterEndPoint::enableTagList() {
  if (tagListEnabled) {
    return true;
  }
  if (endpoint_id == 0) {
    log_e("Endpoint ID is not set. Call the endpoint begin() first.");
    return false;
  }
  endpoint_t *ep = endpoint::get(node::get(), endpoint_id);
  if (ep == nullptr) {
    log_e("Endpoint %u not found", endpoint_id);
    return false;
  }
  cluster_t *descriptorCluster = cluster::get(ep, Descriptor::Id);
  if (descriptorCluster == nullptr) {
    log_e("Descriptor cluster not found on endpoint %u", endpoint_id);
    return false;
  }
  if (cluster::descriptor::feature::tag_list::add(descriptorCluster) != ESP_OK) {
    log_e("Failed to enable TagList feature on endpoint %u", endpoint_id);
    return false;
  }
  tagListEnabled = true;
  return true;
}

bool MatterEndPoint::setTagList(const MatterTag *tagList, uint8_t count) {
  if (endpoint_id == 0) {
    log_e("setTagList() requires the endpoint begin() to be called first.");
    return false;
  }
  if (tagList == nullptr || count == 0) {
    log_e("setTagList() requires a non-empty tag list.");
    return false;
  }
  if (count > MAX_TAG_LIST_SIZE) {
    log_e("setTagList() accepts at most %u tags", MAX_TAG_LIST_SIZE);
    return false;
  }

  for (uint8_t i = 0; i < count; i++) {
    const bool emptyLabel = (tagList[i].label == nullptr || tagList[i].label[0] == '\0');
    if (tagList[i].namespaceId == MatterTags::Switches::NS && tagList[i].tag == MatterTags::Switches::Custom && emptyLabel) {
      log_e("Switches Custom tag requires a non-empty label. Use MatterTags::Switches::createCustomTag().");
      return false;
    }
    if (tagList[i].namespaceId == MatterTags::Position::NS && tagList[i].tag == MatterTags::Position::Row && emptyLabel) {
      log_e("Position Row tag requires a non-empty label. Use MatterTags::Position::createRowTag().");
      return false;
    }
    if (tagList[i].namespaceId == MatterTags::Position::NS && tagList[i].tag == MatterTags::Position::Column && emptyLabel) {
      log_e("Position Column tag requires a non-empty label. Use MatterTags::Position::createColumnTag().");
      return false;
    }
  }

  if (!enableTagList()) {
    return false;
  }

  endpoint_t *ep = endpoint::get(node::get(), endpoint_id);
  if (ep == nullptr) {
    log_e("Endpoint %u not found", endpoint_id);
    return false;
  }

  Globals::Structs::SemanticTagStruct::Type tags[MAX_TAG_LIST_SIZE] = {};
  for (uint8_t i = 0; i < count; i++) {
    tags[i].mfgCode.SetNull();
    tags[i].namespaceID = tagList[i].namespaceId;
    tags[i].tag = tagList[i].tag;
    if (tagList[i].label != nullptr) {
      tags[i].label.Emplace(chip::CharSpan(tagList[i].label, strlen(tagList[i].label)));
    }
  }

  esp_err_t err = endpoint::set_semantic_tags(ep, tags, count);
  if (err != ESP_OK) {
    log_e("Failed to set TagList attribute: %s", esp_err_to_name(err));
    return false;
  }
  return true;
}

bool MatterEndPoint::setTagList(std::initializer_list<MatterTag> tagList) {
  if (tagList.size() > MAX_TAG_LIST_SIZE) {
    log_e("setTagList() accepts at most %u tags", MAX_TAG_LIST_SIZE);
    return false;
  }
  return setTagList(tagList.begin(), static_cast<uint8_t>(tagList.size()));
}

~OtLock() {
    if (held) {
      esp_openthread_lock_release();
    }
  }

String formatHexLower(const uint8_t *data, size_t len) {
  String s;
  s.reserve(len * 2);
  char buf[3];
  buf[2] = '\0';
  for (size_t i = 0; i < len; ++i) {
    snprintf(buf, sizeof(buf), "%02x", data[i]);
    s += buf;
  }
  return s;
}

bool discoverResultIsJoinable(const otActiveScanResult &in) {
  if (in.mSteeringData.mLength == 0 || in.mSteeringData.mLength > OT_STEERING_DATA_MAX_LENGTH) {
    return false;
  }
  for (uint8_t i = 0; i < in.mSteeringData.mLength; ++i) {
    if (in.mSteeringData.m8[i] != 0) {
      return true;
    }
  }
  return false;
}

OThreadScanClass::~OThreadScanClass() {
  if (_doneSem) {
    vSemaphoreDelete(_doneSem);
    _doneSem = nullptr;
  }
}

bool OThreadScanClass::ensureDoneSem() {
  if (_doneSem) {
    return true;
  }
  _doneSem = xSemaphoreCreateBinary();
  if (_doneSem == nullptr) {
    log_e("OThreadScan: failed to create done semaphore");
    return false;
  }
  return true;
}

void OThreadScanClass::prepareResultStorage() {
  if (_results.capacity() < OT_DISCOVER_MAX_RESULTS) {
    _results.reserve(OT_DISCOVER_MAX_RESULTS);
  }
  if (_rawResults.capacity() < OT_DISCOVER_MAX_RESULTS) {
    _rawResults.reserve(OT_DISCOVER_MAX_RESULTS);
  }
}

int OThreadScanClass::findResultByExtendedPanId(const OThreadNetworkInfo &info) const {
  for (size_t i = 0; i < _results.size(); ++i) {
    if (memcmp(_results[i].extendedPanId, info.extendedPanId, OT_EXT_PAN_ID_SIZE) == 0) {
      return static_cast<int>(i);
    }
  }
  return -1;
}

bool OThreadScanClass::discoverChannelMask(uint32_t &mask) const {
  if (_channel == 0) {
    mask = 0;
    return true;
  }
  if (_channel < 11 || _channel > 26) {
    return false;
  }
  mask = (1U << _channel);
  return true;
}

int16_t OThreadScanClass::discoverNetworks(bool async) {
  otError error = OT_ERROR_NONE;
  uint32_t channelMask = 0;

  // Create outside OtLock: heap alloc must not run while holding the OT API lock.
  if (!ensureDoneSem()) {
    return OT_DISCOVER_FAILED;
  }
  prepareResultStorage();

  {
    OtLock lock;
    if (!lock) {
      return OT_DISCOVER_FAILED;
    }

    otInstance *inst = OThread.getInstance();
    if (!inst) {
      return OT_DISCOVER_FAILED;
    }

    if (_inProgress || otThreadIsDiscoverInProgress(inst)) {
      return OT_DISCOVER_RUNNING;
    }

    if (!discoverChannelMask(channelMask)) {
      return OT_DISCOVER_FAILED;
    }

    _results.clear();
    _rawResults.clear();
    _triggered = true;
    _done = false;
    _inProgress = false;
    _startError = OT_ERROR_NONE;
    _startedMs = millis();

    if (_doneSem) {
      while (xSemaphoreTake(_doneSem, 0) == pdTRUE) {}
    }

    error = otThreadDiscover(inst, channelMask, _filters.panIdFilter, _filters.joinerOnly, _filters.eui64Filter, handleDiscoverResult, this);
    _startError = error;
    if (error != OT_ERROR_NONE) {
      _triggered = false;
      return OT_DISCOVER_FAILED;
    }

    _inProgress = true;
  }

  if (async) {
    return OT_DISCOVER_RUNNING;
  }

  if (!_doneSem || xSemaphoreTake(_doneSem, pdMS_TO_TICKS(_timeoutMs)) != pdTRUE) {
    _inProgress = false;
    return OT_DISCOVER_FAILED;
  }

  if (_startError != OT_ERROR_NONE) {
    return OT_DISCOVER_FAILED;
  }

  return (int16_t)_results.size();
}

int16_t OThreadScanClass::scanComplete() {
  if (!_triggered) {
    return OT_DISCOVER_FAILED;
  }

  if (_done) {
    if (_startError != OT_ERROR_NONE) {
      return OT_DISCOVER_FAILED;
    }
    return (int16_t)_results.size();
  }

  // _done is set only in onDiscoverResult(nullptr). Do not infer completion from
  // otThreadIsDiscoverInProgress(): OT may be idle before the final callback runs.
  // Completion is signaled by the final discover callback (aResult == nullptr),
  // which sets _done and releases _doneSem.
  if (_inProgress && (millis() - _startedMs) > _timeoutMs) {
    _inProgress = false;
    return OT_DISCOVER_FAILED;
  }

  if (_inProgress) {
    return OT_DISCOVER_RUNNING;
  }

  return OT_DISCOVER_FAILED;
}

void OThreadScanClass::scanDelete() {
  // A scan is only complete once the final discover callback (aResult == nullptr)
  // sets _done. Do not use otThreadIsDiscoverInProgress() here: OpenThread can go
  // idle before that final callback is delivered (see scanComplete()), so clearing
  // then could zero the count reported to onComplete().
  if (_triggered && !_done) {
    log_d("OThreadScan: scanDelete() deferred (waiting for discover complete)");
    return;
  }

  std::vector<OThreadNetworkInfo>().swap(_results);
  std::vector<otActiveScanResult>().swap(_rawResults);
  _triggered = false;
  _done = false;
  _inProgress = false;
  _startError = OT_ERROR_NONE;
  if (_doneSem) {
    while (xSemaphoreTake(_doneSem, 0) == pdTRUE) {}
  }
}

bool OThreadScanClass::isDiscoverInProgress() const {
  if (_inProgress) {
    return true;
  }

  OtLock lock;
  if (!lock) {
    return _inProgress;
  }

  otInstance *inst = OThread.getInstance();
  if (!inst) {
    return false;
  }

  return otThreadIsDiscoverInProgress(inst);
}

uint16_t OThreadScanClass::getResultCount() const {
  if (!resultsAvailable()) {
    return 0;
  }
  const size_t n = _results.size();
  return (n > UINT16_MAX) ? UINT16_MAX : static_cast<uint16_t>(n);
}

const OThreadNetworkInfo &OThreadScanClass::getResult(uint16_t index) const {
  static const OThreadNetworkInfo kEmpty{};
  if (!resultsAvailable() || index >= _results.size()) {
    return kEmpty;
  }
  return _results[index];
}

bool OThreadScanClass::getResult(uint16_t index, OThreadNetworkInfo &info) const {
  if (!resultsAvailable() || index >= _results.size()) {
    return false;
  }
  info = _results[index];
  return true;
}

bool OThreadScanClass::extAddress(uint16_t index, uint8_t address[OT_EXT_ADDRESS_SIZE]) {
  if (!resultsAvailable() || index >= _results.size()) {
    return false;
  }
  memcpy(address, _results[index].extAddress, OT_EXT_ADDRESS_SIZE);
  return true;
}

bool OThreadScanClass::extendedPanId(uint16_t index, uint8_t extPanId[OT_EXT_PAN_ID_SIZE]) {
  if (!resultsAvailable() || index >= _results.size()) {
    return false;
  }
  memcpy(extPanId, _results[index].extendedPanId, OT_EXT_PAN_ID_SIZE);
  return true;
}

bool OThreadScanClass::isJoinable(uint16_t index) {
  if (!resultsAvailable() || index >= _results.size()) {
    return false;
  }
  return _results[index].joinable;
}

bool OThreadScanClass::isNativeCommissioner(uint16_t index) {
  if (!resultsAvailable() || index >= _results.size()) {
    return false;
  }
  return _results[index].nativeCommissioner;
}

const otActiveScanResult *OThreadScanClass::getActiveScanResult(uint16_t index) const {
  if (!resultsAvailable() || index >= _rawResults.size()) {
    return nullptr;
  }
  return &_rawResults[index];
}

void OThreadScanClass::onDiscoverResult(otActiveScanResult *aResult) {
  if (aResult != nullptr) {
    const OThreadNetworkInfo info = fromActiveScanResult(*aResult);

    const int existing = findResultByExtendedPanId(info);
    if (existing >= 0) {
      // Same Thread network from another router/beacon; keep the strongest RSSI.
      if (info.rssi > _results[static_cast<size_t>(existing)].rssi) {
        _results[static_cast<size_t>(existing)] = info;
        _rawResults[static_cast<size_t>(existing)] = *aResult;
      }
      // Still stream every Discovery Response (Matter / OpenThread model).
      if (_resultCb) {
        _resultCb(info, _resultCtx);
      }
      return;
    }

    if (_results.size() >= OT_DISCOVER_MAX_RESULTS) {
      log_w("OThreadScan: result storage full (%u); streaming only", (unsigned)OT_DISCOVER_MAX_RESULTS);
      if (_resultCb) {
        _resultCb(info, _resultCtx);
      }
      return;
    }
    // Vectors were pre-reserved in discoverNetworks(); push_back must not realloc here.
    _results.push_back(info);
    _rawResults.push_back(*aResult);
    if (_resultCb) {
      _resultCb(info, _resultCtx);
    }
    return;
  }

  _inProgress = false;
  _done = true;
  if (_doneSem) {
    xSemaphoreGive(_doneSem);
  }
  if (_completeCb) {
    const int16_t count = (_startError == OT_ERROR_NONE) ? (int16_t)_results.size() : OT_DISCOVER_FAILED;
    _completeCb(count, _startError, _completeCtx);
  }
}

OThreadNetworkInfo OThreadScanClass::fromActiveScanResult(const otActiveScanResult &in) {
  OThreadNetworkInfo out{};
  strncpy(out.networkName, in.mNetworkName.m8, OT_NETWORK_NAME_MAX_SIZE);
  out.networkName[OT_NETWORK_NAME_MAX_SIZE] = '\0';
  memcpy(out.extendedPanId, in.mExtendedPanId.m8, OT_EXT_PAN_ID_SIZE);
  out.panId = in.mPanId;
  memcpy(out.extAddress, in.mExtAddress.m8, OT_EXT_ADDRESS_SIZE);
  out.channel = in.mChannel;
  out.rssi = in.mRssi;
  out.lqi = in.mLqi;
  out.threadVersion = (uint8_t)in.mVersion;
  // MLE Discovery (otThreadDiscover) reports joinability via Steering Data;
  // mIsJoinable is only set for IEEE 802.15.4 beacon Active Scan results.
  out.joinable = in.mDiscover ? discoverResultIsJoinable(in) : in.mIsJoinable;
  out.nativeCommissioner = in.mIsNative;
  return out;
}

static bool hostedClearPinBuses(void) {
  if (!perimanClearPinBus((uint8_t)sdio_pin_config.pin_clk)) {
    return false;
  }
  if (!perimanClearPinBus((uint8_t)sdio_pin_config.pin_cmd)) {
    return false;
  }
  if (!perimanClearPinBus((uint8_t)sdio_pin_config.pin_d0)) {
    return false;
  }
  if (!perimanClearPinBus((uint8_t)sdio_pin_config.pin_d1)) {
    return false;
  }
  if (!perimanClearPinBus((uint8_t)sdio_pin_config.pin_d2)) {
    return false;
  }
  if (!perimanClearPinBus((uint8_t)sdio_pin_config.pin_d3)) {
    return false;
  }
  if (!perimanClearPinBus((uint8_t)sdio_pin_config.pin_reset)) {
    return false;
  }
  return true;
}

static bool hostedAssignPinBuses(void) {
  void *const bus = (void *)&sdio_pin_config;

  if (!perimanSetPinBus((uint8_t)sdio_pin_config.pin_clk, ESP32_BUS_TYPE_ESP_HOSTED_SDIO_CLK, bus, 0, -1)) {
    return false;
  }
  if (!perimanSetPinBus((uint8_t)sdio_pin_config.pin_cmd, ESP32_BUS_TYPE_ESP_HOSTED_SDIO_CMD, bus, 0, -1)) {
    return false;
  }
  if (!perimanSetPinBus((uint8_t)sdio_pin_config.pin_d0, ESP32_BUS_TYPE_ESP_HOSTED_SDIO_D0, bus, 0, -1)) {
    return false;
  }
  if (!perimanSetPinBus((uint8_t)sdio_pin_config.pin_d1, ESP32_BUS_TYPE_ESP_HOSTED_SDIO_D1, bus, 0, -1)) {
    return false;
  }
  if (!perimanSetPinBus((uint8_t)sdio_pin_config.pin_d2, ESP32_BUS_TYPE_ESP_HOSTED_SDIO_D2, bus, 0, -1)) {
    return false;
  }
  if (!perimanSetPinBus((uint8_t)sdio_pin_config.pin_d3, ESP32_BUS_TYPE_ESP_HOSTED_SDIO_D3, bus, 0, -1)) {
    return false;
  }
  if (!perimanSetPinBus((uint8_t)sdio_pin_config.pin_reset, ESP32_BUS_TYPE_ESP_HOSTED_SDIO_RST, bus, 0, -1)) {
    return false;
  }
  return true;
}

static bool hostedDetachBus(void *bus_pointer) {
  if (bus_pointer != (void *)&sdio_pin_config) {
    return false;
  }
  if (hosted_initialized) {
    log_e("ESP-Hosted: stop WiFi/BLE before removing SDIO pins from periman");
    return false;
  }
  return true;
}

~OtLock() {
    if (mLocked) {
      esp_openthread_lock_release();
    }
  }

bool OpenThread::hasActiveDataset() const {
  if (!mInstance) {
    log_w("Error: OpenThread instance not initialized");
    return false;
  }

  OtLock lock;
  if (!lock) {
    log_e("Error: Failed to acquire OpenThread lock");
    return false;
  }

  otOperationalDatasetTlvs datasetTlvs;
  return otDatasetGetActiveTlvs(mInstance, &datasetTlvs) == OT_ERROR_NONE;
}

atic esp_err_t i2s_channel_read_stereo_to_mono(
  i2s_chan_handle_t handle, char *read_buff, void *dst, size_t len, size_t *bytes_read, uint32_t timeout_ms, size_t slot_offset, bool unpack_8bit
) {
  size_t out_len = 0;
  size_t read_buff_len = len * (unpack_8bit ? 4 : 2);
  if (read_buff == NULL) {
    log_e("Temp buffer is NULL!");
    return ESP_FAIL;
  }
  esp_err_t err = i2s_channel_read(handle, read_buff, read_buff_len, &out_len, timeout_ms);
  if (err != ESP_OK) {
    *bytes_read = 0;
    return err;
  }
  size_t stereo_samples = out_len / 2;
  int16_t *src = (int16_t *)read_buff;
  size_t written = 0;

  if (unpack_8bit) {
    uint8_t *ds = (uint8_t *)dst;
    if (slot_offset < 2) {
      for (size_t i = slot_offset; i < stereo_samples; i += 2) {
        ds[written++] = (uint8_t)((uint16_t)src[i] >> 8);
      }
    } else {
      for (size_t i = 0; i < stereo_samples; i += 2) {
        int16_t l = (int8_t)((uint16_t)src[i] >> 8);
        int16_t r = (int8_t)((uint16_t)src[i + 1] >> 8);
        ds[written++] = (int8_t)((l + r) / 2);
      }
    }
    *bytes_read = written;
  } else {
    int16_t *ds = (int16_t *)dst;
    if (slot_offset < 2) {
      for (size_t i = slot_offset; i < stereo_samples; i += 2) {
        ds[written++] = src[i];
      }
    } else {
      for (size_t i = 0; i < stereo_samples; i += 2) {
        ds[written++] = (int16_t)(((int32_t)src[i] + (int32_t)src[i + 1]) / 2);
      }
    }
    *bytes_read = written * 2;
  }
  return ESP_OK;
}

