esp_err_t ldoAcquireChannel(uint8_t chan_id, int voltage_mv, bool adjustable, ldo_channel_handle_t *out_handle) {
  if (out_handle == NULL) {
    return ESP_ERR_INVALID_ARG;
  }
  *out_handle = NULL;
  esp_ldo_channel_config_t cfg = {
    .chan_id = (int)chan_id,
    .voltage_mv = voltage_mv,
    .flags =
      {
        .adjustable = adjustable ? 1u : 0u,
        .owned_by_hw = 0u,
      },
  };
  esp_err_t err = esp_ldo_acquire_channel(&cfg, out_handle);
  if (err != ESP_OK) {
    log_e("ldoAcquireChannel: chan=%u %dmV adj=%d failed: %s", (unsigned)chan_id, voltage_mv, adjustable, esp_err_to_name(err));
  }
  return err;
}

esp_err_t ldoReleaseChannel(ldo_channel_handle_t handle) {
  if (handle == NULL) {
    return ESP_ERR_INVALID_ARG;
  }
  esp_err_t err = esp_ldo_release_channel(handle);
  if (err != ESP_OK) {
    log_e("ldoReleaseChannel: %s", esp_err_to_name(err));
  }
  return err;
}

static void io_ldo_release_handle(void) {
  if (s_io_ldo_slot.handle == NULL) {
    return;
  }
  if (ldoReleaseChannel(s_io_ldo_slot.handle) == ESP_OK) {
    log_i("periman IO LDO auto: released channel %d", s_io_ldo.chan_id);
  }
  s_io_ldo_slot.handle = NULL;
}

static void io_ldo_try_acquire(void) {
  if (s_io_ldo_slot.refcount <= 0 || s_io_ldo_slot.handle != NULL) {
    return;
  }
  if (s_sdmmc_ldo_chan >= 0 && s_sdmmc_ldo_chan == s_io_ldo.chan_id) {
    log_d("periman IO LDO auto: channel %d held by SDMMC; skip acquire", s_io_ldo.chan_id);
    return;
  }
  if (ldoAcquireChannel((uint8_t)s_io_ldo.chan_id, s_io_ldo.voltage_mv, false, &s_io_ldo_slot.handle) == ESP_OK) {
    log_i("periman IO LDO auto: enabled channel %d @ %d mV", s_io_ldo.chan_id, s_io_ldo.voltage_mv);
  } else {
    s_io_ldo_slot.handle = NULL;
  }
}

static void io_ldo_try_release(void) {
  if (s_io_ldo_slot.refcount != 0 || s_io_ldo_slot.handle == NULL) {
    return;
  }
  io_ldo_release_handle();
}

void ldoPerimanPinBusSet(uint8_t pin, peripheral_bus_type_t old_type, peripheral_bus_type_t new_type) {
#if BOARD_PERIMAN_IO_LDO_AUTO
  if (!io_ldo_pin_in_range(pin)) {
    return;
  }
  const bool old_active = (old_type != ESP32_BUS_TYPE_INIT);
  const bool new_active = (new_type != ESP32_BUS_TYPE_INIT);

  if (!old_active && new_active) {
    s_io_ldo_slot.refcount++;
    io_ldo_try_acquire();
  } else if (old_active && !new_active) {
    if (s_io_ldo_slot.refcount > 0) {
      s_io_ldo_slot.refcount--;
    }
    io_ldo_try_release();
  }
#else
  (void)pin;
  (void)old_type;
  (void)new_type;
#endif
}

void ldoSdmmcPrepareAcquire(uint8_t chan_id) {
#if BOARD_PERIMAN_IO_LDO_AUTO
  if (io_ldo_channel_matches(chan_id)) {
    io_ldo_release_handle();
  }
#else
  (void)chan_id;
#endif
}

void ldoSdmmcDriverDetached(uint8_t chan_id) {
  if (s_sdmmc_ldo_chan == (int8_t)chan_id) {
    s_sdmmc_ldo_chan = -1;
  }
#if BOARD_PERIMAN_IO_LDO_AUTO
  if (io_ldo_channel_matches(chan_id)) {
    io_ldo_try_acquire();
  }
#endif
}

void ldoSdmmcDriverCreateFailed(uint8_t chan_id) {
#if BOARD_PERIMAN_IO_LDO_AUTO
  if (io_ldo_channel_matches(chan_id)) {
    io_ldo_try_acquire();
  }
#else
  (void)chan_id;
#endif
}

const char *hostedGetSlaveTargetName() {
#if ESP_HOSTED_VERSION_VAL(ESP_HOSTED_VERSION_MAJOR_1, ESP_HOSTED_VERSION_MINOR_1, ESP_HOSTED_VERSION_PATCH_1) < ESP_HOSTED_VERSION_VAL(2, 12, 2)
  return CONFIG_IDF_SLAVE_TARGET;
#else
  uint32_t chip_id = 0;
  static char target_name[20] = {0};
  size_t target_name_len = sizeof(target_name);
  esp_err_t ret = esp_hosted_get_cp_info(&chip_id, target_name, target_name_len);
  if (ret != ESP_OK) {
    log_e("Could not get slave target name: %s", esp_err_to_name(ret));
    return CONFIG_IDF_SLAVE_TARGET;
  }
  return target_name;
#endif
}

bool uartSetIrdaDirection(uart_t *uart, esp32_uart_irda_direction_t irdaDirection) {
  if (uart == NULL || uart->num >= SOC_UART_NUM || (irdaDirection != ESP32_UART_IRDA_RX && irdaDirection != ESP32_UART_IRDA_TX)) {
    return false;
  }

  UART_MUTEX_LOCK();
  uart_dev_t *hw = UART_LL_GET_HW(uart->num);

#if CONFIG_IDF_TARGET_ESP32 || CONFIG_IDF_TARGET_ESP32S2 || CONFIG_IDF_TARGET_ESP32S3 || CONFIG_IDF_TARGET_ESP32C2 || CONFIG_IDF_TARGET_ESP32C3
  bool isIrdaModeEnabled = hw->conf0.irda_en == 1;
#else
  bool isIrdaModeEnabled = hw->conf0_sync.irda_en == 1;
#endif
  if (!isIrdaModeEnabled) {
    uint8_t uart_num = uart->num;
    UART_MUTEX_UNLOCK();
    log_e("UART%u is not in IrDA mode; set UART_MODE_IRDA before setting IrDA TX/RX direction.", uart_num);
    return false;
  }

#if CONFIG_IDF_TARGET_ESP32 || CONFIG_IDF_TARGET_ESP32S2 || CONFIG_IDF_TARGET_ESP32S3 || CONFIG_IDF_TARGET_ESP32C2 || CONFIG_IDF_TARGET_ESP32C3
  // enables IRDA TX
  hw->conf0.irda_tx_en = irdaDirection;
#else
  // enables IRDA TX
  hw->conf0_sync.irda_tx_en = irdaDirection;
  // it needs UART Update
  uart_ll_update(hw);
#endif
  UART_MUTEX_UNLOCK();
  return true;
}

static uint32_t zb_utctime_from_unix(time_t unix_ts) {
  if (unix_ts == (time_t)-1) {
    return ZIGBEE_UTCTIME_INVALID;
  }
  int64_t sec = (int64_t)unix_ts - ZIGBEE_UTCTIME_UNIX_OFFSET_SEC;
  if (sec < 0) {
    return ZIGBEE_UTCTIME_INVALID;
  }
  if (sec > (int64_t)UINT32_MAX) {
    return ZIGBEE_UTCTIME_INVALID;
  }
  return (uint32_t)sec;
}

static time_t unix_time_from_zb_utctime(uint32_t zb_sec) {
  if (zb_sec == ZIGBEE_UTCTIME_INVALID) {
    return (time_t)-1;
  }
  return (time_t)(ZIGBEE_UTCTIME_UNIX_OFFSET_SEC + (int64_t)zb_sec);
}

static void _uartDetectPin(int8_t pin, const char *funcName, peripheral_bus_type_t expectedType, uint8_t target_uart, bool *needsAttach, int8_t *prevUARTOut) {
  *needsAttach = false;
  if (prevUARTOut != NULL) {
    *prevUARTOut = -1;
  }

  if (pin < 0) {
    return;  // Pin not being changed
  }

  peripheral_bus_type_t t = perimanGetPinBusType(pin);
  bool isUART = (t >= ESP32_BUS_TYPE_UART_RX && t <= ESP32_BUS_TYPE_UART_RTS);
  int8_t prevU = isUART ? perimanGetPinBusNum(pin) : -1;

  *needsAttach = (t != expectedType || target_uart != prevU);
  if (prevUARTOut != NULL) {
    *prevUARTOut = prevU;  // Set to actual UART if owned, -1 otherwise
  }

  if (isUART) {
    log_v("%s: pin %d -> UART%d: currently [UART%d], attach=%s", funcName, pin, target_uart, prevU, *needsAttach ? "YES" : "NO");
  } else {
    log_v("%s: pin %d -> UART%d: currently [GPIO], attach=%s", funcName, pin, target_uart, *needsAttach ? "YES" : "NO");
  }
}

static bool _uartDetachConflictingPin(int8_t pin, uint8_t target_uart_num, const char *target_func_name, bool needsAttach, int8_t *prevOtherUARTOut) {
  if (prevOtherUARTOut != NULL) {
    *prevOtherUARTOut = -1;
  }
  if (pin < 0 || !needsAttach) {
    return true;
  }

  peripheral_bus_type_t currentType = perimanGetPinBusType(pin);
  bool isPeriTypeUART = (currentType >= ESP32_BUS_TYPE_UART_RX && currentType <= ESP32_BUS_TYPE_UART_RTS);
  if (!isPeriTypeUART) {
    return true;  // Pin not assigned to any UART; nothing to detach
  }

  int8_t prevUART = perimanGetPinBusNum(pin);

  // Build _uartDetachPins arguments from the pin's current function
  int8_t d_rx = UART_PIN_NO_CHANGE, d_tx = UART_PIN_NO_CHANGE;
  int8_t d_cts = UART_PIN_NO_CHANGE, d_rts = UART_PIN_NO_CHANGE;
  const char *currentFuncName;

  if (currentType == ESP32_BUS_TYPE_UART_RX) {
    d_rx = pin;
    currentFuncName = "RX";
  } else if (currentType == ESP32_BUS_TYPE_UART_TX) {
    d_tx = pin;
    currentFuncName = "TX";
  } else if (currentType == ESP32_BUS_TYPE_UART_CTS) {
    d_cts = pin;
    currentFuncName = "CTS";
  } else {  // ESP32_BUS_TYPE_UART_RTS
    d_rts = pin;
    currentFuncName = "RTS";
  }

  if (prevUART != target_uart_num) {
    log_d("Detaching pin %d (%s function) from UART%d", pin, currentFuncName, prevUART);
    if (prevOtherUARTOut != NULL) {
      *prevOtherUARTOut = prevUART;
    }
  } else {
    log_d("Detaching pin %d (%s function) from UART%d before using as %s", pin, currentFuncName, prevUART, target_func_name);
  }

  (void)currentFuncName;  // Suppress unused variable warning when log_d is compiled out
  return _uartDetachPins(prevUART, d_rx, d_tx, d_cts, d_rts);
}

void ZigbeeEP::addPrivilegeCommand(uint16_t cluster_id, uint16_t command_id) {
  esp_zb_lock_acquire(portMAX_DELAY);
  esp_err_t ret = esp_zb_zcl_add_privilege_command(_endpoint, cluster_id, command_id);
  esp_zb_lock_release();
  if (ret != ESP_OK) {
    log_e(
      "Failed to add privilege command for endpoint %u, cluster 0x%04x, command 0x%04x: 0x%x: %s", _endpoint, cluster_id, command_id, ret, esp_err_to_name(ret)
    );
  }
}

void ZigbeeEP::zbPrivilegeCommand(const esp_zb_zcl_privilege_command_message_t *message) {
  if (_on_privilege_command) {
    _on_privilege_command(message);
  }
}

void ZigbeeEP::zbCustomClusterCommand(const esp_zb_zcl_custom_cluster_command_message_t *message) {
  if (_on_custom_cluster_command) {
    _on_custom_cluster_command(message);
  }
}

uint16_t tusb_audio_load_descriptor(uint8_t *dst, uint8_t *itf) {
  _itf_num = *itf;
#if TUD_OPT_HIGH_SPEED
  uint8_t str_index = tinyusb_add_string_descriptor("TinyUSB UAC2");
  if (_spk_channels == 2 && _mic_channels > 0) {
    // Stereo Headset
    uint8_t ep_num = tinyusb_get_free_duplex_endpoint();
    TU_VERIFY(ep_num != 0);
    uint8_t int_ep_num = tinyusb_get_free_in_endpoint();
    TU_VERIFY(int_ep_num != 0);
    uint8_t descriptor[TUD_AUDIO20_HEADSET_STEREO_DESC_LEN] = {
      // Interface number, string index, EP Out & EP In & EP Interrupt address, max sample rate, speaker channels, mic channels, bytes per sample RX/TX, bits used per sample RX/TX
      TUD_AUDIO20_HEADSET_STEREO_DESCRIPTOR(
        _itf_num, str_index, ep_num, (uint8_t)(ep_num | 0x80), (uint8_t)(int_ep_num | 0x80), CFG_TUD_AUDIO_MAX_SAMPLE_RATE, _spk_channels, _mic_channels,
        _bytes_per_sample, _bits_per_sample
      )
    };
    *itf += 3;
    memcpy(dst, descriptor, TUD_AUDIO20_HEADSET_STEREO_DESC_LEN);
    return TUD_AUDIO20_HEADSET_STEREO_DESC_LEN;
  } else if (_spk_channels == 1 && _mic_channels > 0) {
    // Mono Headset
    uint8_t ep_num = tinyusb_get_free_duplex_endpoint();
    TU_VERIFY(ep_num != 0);
    uint8_t int_ep_num = tinyusb_get_free_in_endpoint();
    TU_VERIFY(int_ep_num != 0);
    uint8_t descriptor[TUD_AUDIO20_HEADSET_MONO_DESC_LEN] = {
      // Interface number, string index, EP Out & EP In & EP Interrupt address, max sample rate, speaker channels, mic channels, bytes per sample RX/TX, bits used per sample RX/TX
      TUD_AUDIO20_HEADSET_MONO_DESCRIPTOR(
        _itf_num, str_index, ep_num, (uint8_t)(ep_num | 0x80), (uint8_t)(int_ep_num | 0x80), CFG_TUD_AUDIO_MAX_SAMPLE_RATE, _spk_channels, _mic_channels,
        _bytes_per_sample, _bits_per_sample
      )
    };
    *itf += 3;
    memcpy(dst, descriptor, TUD_AUDIO20_HEADSET_MONO_DESC_LEN);
    return TUD_AUDIO20_HEADSET_MONO_DESC_LEN;
  } else if (_spk_channels == 2 && _mic_channels == 0) {
    // Stereo Speaker
    uint8_t ep_num = tinyusb_get_free_out_endpoint();
    TU_VERIFY(ep_num != 0);
    uint8_t int_ep_num = tinyusb_get_free_in_endpoint();
    TU_VERIFY(int_ep_num != 0);
