Status Parse(std::string_view json) {
    // Copy into padded buffer
    padded_json_ = simdjson::padded_string(json);

    // Store parsed document
    if (auto error = parser_.iterate(padded_json_).get(document_)) {
      return Status::Invalid("JSON parse error: ", simdjson::error_message(error));
    }

    // Validate root is an object
    auto object = document_.get_object();
    if (object.error()) {
      if (object.error() == simdjson::INCORRECT_TYPE) {
        return Status::TypeError("Not a JSON object");
      }
      return Status::Invalid("JSON parse error: ",
                             simdjson::error_message(object.error()));
    }

    return Status::OK();
  }

Result<std::string> GetString(const char* key) {
    document_.rewind();

    auto object = document_.get_object();

    auto field = object.find_field(key);

    if (field.error() == simdjson::NO_SUCH_FIELD) {
      return Status::KeyError("Key '", key, "' does not exist");
    }
    if (field.error()) {
      return Status::Invalid("Error accessing key '", key,
                             "': ", simdjson::error_message(field.error()));
    }

    auto str_result = field.get_string();
    if (str_result.error() == simdjson::INCORRECT_TYPE) {
      return Status::TypeError("Key '", key, "' is not a string");
    }
    if (str_result.error()) {
      return Status::Invalid("Error getting string for key '", key,
                             "': ", simdjson::error_message(str_result.error()));
    }

    std::string_view str;
    if (auto error = std::move(str_result).get(str)) {
      return Status::Invalid("Error getting string for key '", key,
                             "': ", simdjson::error_message(error));
    }
    return std::string(str);
  }

Result<std::unordered_map<std::string, std::string>> GetStringMap() {
    std::unordered_map<std::string, std::string> map;

    document_.rewind();

    auto object = document_.get_object();

    for (auto field : object) {
      std::string_view key;
      if (auto error = field.unescaped_key().get(key)) {
        return Status::Invalid("Error getting object key: ",
                               simdjson::error_message(error));
      }

      auto value = field.value();

      auto str_result = value.get_string();

      if (str_result.error() == simdjson::INCORRECT_TYPE) {
        return Status::TypeError("Key '", std::string(key),
                                 "' does not have a string value");
      }
      if (str_result.error()) {
        return Status::Invalid("Error getting value for key '", std::string(key),
                               "': (code=", static_cast<int>(str_result.error()), ")");
      }

      std::string_view str;
      if (auto error = std::move(str_result).get(str)) {
        return Status::Invalid("Error getting value for key '", std::string(key),
                               "': ", simdjson::error_message(error));
      }

      map.emplace(std::string(key), std::string(str));
    }

    return map;
  }

Result<bool> GetBool(const char* key) {
    document_.rewind();

    auto object = document_.get_object();

    auto field = object.find_field(key);

    if (field.error() == simdjson::NO_SUCH_FIELD) {
      return Status::KeyError("Key '", key, "' does not exist");
    }
    if (field.error()) {
      return Status::Invalid("Error accessing key '", key,
                             "': ", simdjson::error_message(field.error()));
    }

    auto bool_result = field.get_bool();
    if (bool_result.error() == simdjson::INCORRECT_TYPE) {
      return Status::TypeError("Key '", key, "' is not a boolean");
    }
    if (bool_result.error()) {
      return Status::Invalid("Error getting bool for key '", key,
                             "': ", simdjson::error_message(bool_result.error()));
    }

    bool value;
    if (auto error = std::move(bool_result).get(value)) {
      return Status::Invalid("Error getting bool for key '", key,
                             "': ", simdjson::error_message(error));
    }

    return value;
  }

void JsonWriter::StartObject() {
  MaybeComma();
  builder_.start_object();
  needs_comma_ = false;
}

void JsonWriter::StartArray() {
  MaybeComma();
  builder_.start_array();
  needs_comma_ = false;
}

void JsonWriter::Key(std::string_view key) {
  MaybeComma();
  builder_.escape_and_append_with_quotes(key);
  builder_.append_colon();
  needs_comma_ = false;
}

void JsonWriter::String(std::string_view value) {
  MaybeComma();
  builder_.escape_and_append_with_quotes(value);
  needs_comma_ = true;
}

void JsonWriter::RawValue(std::string_view value) {
  MaybeComma();
  builder_.append_raw(value);
  needs_comma_ = true;
}

void JsonWriter::Bool(bool value) {
  MaybeComma();
  builder_.append(value);
  needs_comma_ = true;
}

void JsonWriter::Int(int32_t value) {
  MaybeComma();
  builder_.append(value);
  needs_comma_ = true;
}

void JsonWriter::Int64(int64_t value) {
  MaybeComma();
  builder_.append(value);
  needs_comma_ = true;
}

void JsonWriter::Uint(uint32_t value) {
  MaybeComma();
  builder_.append(value);
  needs_comma_ = true;
}

void JsonWriter::Uint64(uint64_t value) {
  MaybeComma();
  builder_.append(value);
  needs_comma_ = true;
}

void JsonWriter::Double(double value) {
  MaybeComma();
  builder_.append(value);
  needs_comma_ = true;
}

Status JsonWriter::WriteValue(sj::value value) {
  return VisitJsonValue(
      value,

      [&](sj::object object) -> Status {
        StartObject();

        for (auto field : object) {
          ARROW_ASSIGN_OR_RAISE(
              auto key,
              ResolveSimdjsonResult(field.unescaped_key(), "Failed to get object key"));

          Key(key);

          ARROW_ASSIGN_OR_RAISE(
              auto field_value,
              ResolveSimdjsonResult(field.value(), "Failed to get object value"));

          RETURN_NOT_OK(WriteValue(field_value));
        }

        EndObject();
        return Status::OK();
      },

      [&](sj::array array) -> Status {
        StartArray();

        for (auto element : array) {
          ARROW_ASSIGN_OR_RAISE(
              auto element_value,
              ResolveSimdjsonResult(element, "Failed to iterate JSON array"));

          RETURN_NOT_OK(WriteValue(element_value));
        }

        EndArray();
        return Status::OK();
      },

      [&](std::string_view string_value) -> Status {
        String(string_value);
        return Status::OK();
      },

      [&](bool bool_value) -> Status {
        Bool(bool_value);
        return Status::OK();
      },

      [&]() -> Status {
        Null();
        return Status::OK();
      },

      [&](int64_t value) -> Status {
        Int64(value);
        return Status::OK();
      },

      [&](uint64_t value) -> Status {
        Uint64(value);
        return Status::OK();
      },

      [&](double value) -> Status {
        Double(value);
        return Status::OK();
      },

      [&](sj::value value) -> Status {
        ARROW_ASSIGN_OR_RAISE(auto raw_json,
                              ResolveSimdjsonResult(simdjson::to_json_string(value),
                                                    "Failed to get raw JSON"));
        RawValue(raw_json);
        return Status::OK();
      });
}

void JsonWriter::Null() {
  MaybeComma();
  builder_.append_null();
  needs_comma_ = true;
}

Result<std::string_view> JsonWriter::GetString() const {
  std::string_view view;
  if (auto error = builder_.view().get(view); error != simdjson::SUCCESS) {
    if (error == simdjson::OUT_OF_CAPACITY) {
      return Status::OutOfMemory(
          "OutOfMemory when allocating buffer to serialize json to string");
    }
    return Status::Invalid("Failed to retrieve json from string builder: ",
                           simdjson::error_message(error));
  }
  return view;
}

Result<std::string> JsonWriter::GetPrettyString(
    const simdjson::fractured_json_options& options) const {
  ARROW_ASSIGN_OR_RAISE(std::string_view json, GetString());
  return simdjson::fractured_json_string(json, options);
}

void JsonWriter::MaybeComma() {
  if (needs_comma_) {
    builder_.append_comma();
  }
}

const char* JsonTypeName(simdjson::dom::element_type type) {
  switch (type) {
    case simdjson::dom::element_type::ARRAY:
      return "array";
    case simdjson::dom::element_type::OBJECT:
      return "object";
    case simdjson::dom::element_type::INT64:
    case simdjson::dom::element_type::UINT64:
    case simdjson::dom::element_type::DOUBLE:
      return "number";
    case simdjson::dom::element_type::STRING:
      return "string";
    case simdjson::dom::element_type::BOOL:
      return "boolean";
    case simdjson::dom::element_type::NULL_VALUE:
      return "null";
    default:
      return "unknown";
  }
}

Result<simdjson::dom::array> GetJsonArray(simdjson::dom::element value,
                                          std::string_view name) {
  if (!value.is_array()) {
    return Status::Invalid(name, " must be an array, got ", JsonTypeName(value.type()));
  }
  return ResolveSimdjsonResult(value.get_array(), "Failed to get JSON array");
}

Result<int64_t> GetJsonInt(simdjson::dom::element value, std::string_view name,
                           std::string_view expected) {
  if (!value.is_int64()) {
    return Status::Invalid(name, " must contain ", expected, ", got ",
                           JsonTypeName(value.type()));
  }
  return ResolveSimdjsonResult(value.get_int64(), "Failed to get JSON integer");
}

Result<simdjson::dom::object> ParseJsonObject(simdjson::dom::parser& parser,
                                              const std::string& json) {
  return ResolveSimdjsonResult(parser.parse(json).get_object(),
                               "Invalid serialized JSON data");
}

Result<std::optional<simdjson::dom::element>> GetOptionalJsonField(
    const simdjson::dom::object& object, std::string_view key) {
  auto field = object.at_key(key);
  if (field.error() == simdjson::NO_SUCH_FIELD) {
    return std::nullopt;
  }

  ARROW_ASSIGN_OR_RAISE(
      auto value,
      ResolveSimdjsonResult(std::move(field), "Failed to get JSON object field"));

  return std::optional<simdjson::dom::element>(std::move(value));
}

Result<std::vector<int64_t>> GetJsonIntArray(simdjson::dom::element value,
                                             std::string_view name) {
  ARROW_ASSIGN_OR_RAISE(auto array, GetJsonArray(value, name));

  std::vector<int64_t> result;
  result.reserve(array.size());

  for (auto element : array) {
    ARROW_ASSIGN_OR_RAISE(auto number, GetJsonInt(element, name, "integers"));
    result.push_back(number);
  }

  return result;
}

Result<std::vector<std::optional<int64_t>>> GetJsonNullableIntArray(
    simdjson::dom::element value, std::string_view name) {
  ARROW_ASSIGN_OR_RAISE(auto array, GetJsonArray(value, name));

  std::vector<std::optional<int64_t>> result;
  result.reserve(array.size());

  for (auto element : array) {
    if (element.is_null()) {
      result.emplace_back(std::nullopt);
    } else {
      ARROW_ASSIGN_OR_RAISE(auto number, GetJsonInt(element, name, "integers or nulls"));
      result.emplace_back(number);
    }
  }

  return result;
}

Result<std::vector<std::string>> GetJsonStringArray(simdjson::dom::element value,
                                                    std::string_view name) {
  ARROW_ASSIGN_OR_RAISE(auto array, GetJsonArray(value, name));

  std::vector<std::string> result;
  result.reserve(array.size());

  for (auto element : array) {
    if (!element.is_string()) {
      return Status::Invalid(name, " must contain strings, got ",
                             JsonTypeName(element.type()));
    }

    ARROW_ASSIGN_OR_RAISE(
        auto string,
        ResolveSimdjsonResult(element.get_string(), "Failed to get JSON string"));
    result.emplace_back(string);
  }

  return result;
}

const char* JsonTypeName(simdjson::ondemand::json_type type) {
  switch (type) {
    case simdjson::ondemand::json_type::array:
      return "array";
    case simdjson::ondemand::json_type::object:
      return "object";
    case simdjson::ondemand::json_type::number:
      return "number";
    case simdjson::ondemand::json_type::string:
      return "string";
    case simdjson::ondemand::json_type::boolean:
      return "boolean";
    case simdjson::ondemand::json_type::null:
      return "null";
    default:
      return "unknown";
  }
}

Result<bool> IsJsonNull(simdjson::ondemand::value& value) {
  bool is_null;
  auto error_code = value.is_null().get(is_null);
  if (error_code != simdjson::SUCCESS) {
    return Status::Invalid("Error checking for JSON null: ",
                           simdjson::error_message(error_code));
  }
  return is_null;
}

Result<std::string> MinifyJson(std::string_view json) {
  std::string minified(json.size(), '\0');
  size_t minified_len = 0;

  if (auto error =
          simdjson::minify(json.data(), json.size(), minified.data(), minified_len);
      error != simdjson::SUCCESS) {
    return Status::Invalid("Failed to minify JSON: ", simdjson::error_message(error));
  }

  minified.resize(minified_len);
  return minified;
}

Status ConsumeJsonValue(simdjson::ondemand::value value) {
  return VisitJsonValue(
      value, ValidateJsonObject, ValidateJsonArray,
      [](std::string_view) { return Status::OK(); }, [](bool) { return Status::OK(); },
      []() { return Status::OK(); }, [](int64_t) { return Status::OK(); },
      [](uint64_t) { return Status::OK(); }, [](double) { return Status::OK(); },
      [](simdjson::ondemand::value) { return Status::OK(); });
}

Status ValidateJsonObject(simdjson::ondemand::object object) {
  for (auto field_result : object) {
    ARROW_ASSIGN_OR_RAISE(
        auto field, ResolveSimdjsonResult(field_result, "Failed to iterate JSON object"));

    RETURN_NOT_OK(ConsumeJsonValue(field.value()));
  }

  return Status::OK();
}

Status ValidateJsonArray(simdjson::ondemand::array array) {
  for (auto element_result : array) {
    ARROW_ASSIGN_OR_RAISE(
        auto value,
        ResolveSimdjsonResult(element_result, "Failed to iterate JSON array"));

    RETURN_NOT_OK(ConsumeJsonValue(value));
  }

  return Status::OK();
}

Status ValidateJsonDocument(simdjson::ondemand::parser& parser,
                            simdjson::padded_string& json) {
  ARROW_ASSIGN_OR_RAISE(
      auto document, ResolveSimdjsonResult(parser.iterate(json), "Failed to parse JSON"));

  ARROW_ASSIGN_OR_RAISE(auto value, ResolveSimdjsonResult(document.get_value(),
                                                          "Failed to get JSON value"));

  return ConsumeJsonValue(value);
}

}

TEST(JsonObjectParser, GetString) {
  JsonObjectParser parser;

  ASSERT_OK(parser.Parse(R"({"name":"arrow"})"));

  ASSERT_OK_AND_ASSIGN(auto value, parser.GetString("name"));
  EXPECT_EQ(value, "arrow");
}

TEST(JsonObjectParser, GetBool) {
  JsonObjectParser parser;

  ASSERT_OK(parser.Parse(R"({"enabled":true})"));

  ASSERT_OK_AND_ASSIGN(auto value, parser.GetBool("enabled"));
  EXPECT_TRUE(value);
}

TEST(JsonObjectParser, InvalidJson) {
  JsonObjectParser parser;

  EXPECT_RAISES_WITH_MESSAGE_THAT(Invalid, ::testing::HasSubstr("JSON parse error"),
                                  parser.Parse(R"({"name":)"));
}

TEST(JsonObjectParser, GetStringMap) {
  JsonObjectParser parser;

  ASSERT_OK(parser.Parse(R"({
    "k1": "v1",
    "k2": "v2"
  })"));

  ASSERT_OK_AND_ASSIGN(auto map, parser.GetStringMap());

  ASSERT_EQ(map.size(), 2U);
  EXPECT_EQ(map["k1"], "v1");
  EXPECT_EQ(map["k2"], "v2");
}

TEST(JsonObjectParser, MissingKey) {
  JsonObjectParser parser;

  ASSERT_OK(parser.Parse(R"({
    "name": "arrow"
  })"));

  ASSERT_RAISES(KeyError, parser.GetString("missing"));
  ASSERT_RAISES(KeyError, parser.GetBool("missing"));
}

TEST(JsonObjectParser, WrongType) {
  JsonObjectParser parser;

  ASSERT_OK(parser.Parse(R"({
    "flag": true,
    "name": "arrow"
  })"));

  ASSERT_RAISES(TypeError, parser.GetString("flag"));
  ASSERT_RAISES(TypeError, parser.GetBool("name"));
}

TEST(JsonObjectParser, NonObjectRoot) {
  JsonObjectParser parser;

  ASSERT_RAISES(TypeError, parser.Parse(R"(["a", "b"])"));
}

TEST(JsonObjectParser, EmptyObject) {
  JsonObjectParser parser;

  ASSERT_OK(parser.Parse(R"({})"));

  ASSERT_OK_AND_ASSIGN(auto map, parser.GetStringMap());

  EXPECT_TRUE(map.empty());
}

Result<std::string> JsonWriter::GetPrettyString(
    const simdjson::fractured_json_options& options) const {
  ARROW_ASSIGN_OR_RAISE(std::string_view json, GetString());
  return simdjson::fractured_json_string(json, options);
}

TEST(JsonWriter, IntField) {
  JsonWriter writer;

  writer.StartObject();
  writer.IntField("a", 42);
  writer.EndObject();

  ASSERT_OK_AND_ASSIGN(std::string_view json, writer.GetString());

  EXPECT_EQ(json, R"({"a":42})");
}

TEST(JsonWriter, GetPrettyString) {
  JsonWriter writer;

  writer.StartObject();
  writer.Key("a");
  writer.Int(42);
  writer.Key("b");
  writer.String("hello");
  writer.EndObject();

  ASSERT_OK_AND_ASSIGN(std::string pretty, writer.GetPrettyString());

  // Pretty output should differ from the compact form (padded spacing, at minimum),
  // even though a small object like this may still be rendered on one line.
  EXPECT_NE(pretty, R"({"a":42,"b":"hello"})");

  // But it should still parse back to the same values.
  sj::parser parser;
  simdjson::padded_string padded(pretty);
  sj::document doc;
  ASSERT_EQ(parser.iterate(padded).get(doc), simdjson::SUCCESS);

  int64_t a_value;
  ASSERT_EQ(doc["a"].get(a_value), simdjson::SUCCESS);
  EXPECT_EQ(a_value, 42);

  std::string_view b_value;
  ASSERT_EQ(doc["b"].get(b_value), simdjson::SUCCESS);
  EXPECT_EQ(b_value, "hello");
}

Status MakeUnionExtension(const std::shared_ptr<DataType>& type,
                          std::shared_ptr<RecordBatch>* out) {
  auto storage_type = checked_cast<const ExtensionType&>(*type).storage_type();

  auto f0 = field("f0", type);
  auto f1 = field("f1", type, /*nullable=*/false);
  auto schema = ::arrow::schema({f0, f1});

  auto a0 = ExtensionType::WrapArray(
      type, ArrayFromJSON(storage_type, R"([[0, 1.5], [1, null]])"));
  auto a1 = ExtensionType::WrapArray(
      type, ArrayFromJSON(storage_type, R"([[0, 1.5], [1, "abc"]])"));

  *out = RecordBatch::Make(schema, a1->length(), {a0, a1});
  return Status::OK();
}

std::shared_ptr<Array> UnionExtensionType::MakeArray(
    std::shared_ptr<ArrayData> data) const {
  DCHECK_EQ(data->type->id(), Type::EXTENSION);
  DCHECK(ExtensionEquals(checked_cast<const ExtensionType&>(*data->type)));
  return std::make_shared<UnionExtensionArray>(data);
}

Result<std::shared_ptr<DataType>> UnionExtensionType::Deserialize(
    std::shared_ptr<DataType> storage_type, const std::string& serialized) const {
  if (serialized != extension_name_) {
    return Status::Invalid("Type identifier did not match: '", serialized, "'");
  }
  if (!storage_type->Equals(*storage_type_)) {
    return Status::Invalid("Invalid storage type for ", extension_name_, ": ",
                           storage_type->ToString());
  }
  return std::make_shared<UnionExtensionType>(std::move(storage_type), extension_name_);
}

std::shared_ptr<DataType> dense_union_extension_type() {
  return std::make_shared<UnionExtensionType>(
      dense_union({field("floats", float64()), field("strings", large_utf8())}, {0, 1}),
      "dense-union-extension");
}

std::shared_ptr<DataType> sparse_union_extension_type() {
  return std::make_shared<UnionExtensionType>(
      sparse_union({field("floats", float64()), field("strings", large_utf8())}, {0, 1}),
      "sparse-union-extension");
}

TEST_F(TestTakeKernel, LARGE_MEMORY_TEST(TakeBinaryOffsetOverflow)) {
  // 2048 * 1 MiB = 2 GiB of output, one value past the int32 offset limit.
  constexpr int64_t kValueSize = 1 << 20;
  constexpr int64_t kNumIndices = 2048;

  StringBuilder values_builder;
  ASSERT_OK(values_builder.Append(std::string(kValueSize, 'x')));
  ASSERT_OK_AND_ASSIGN(auto values, values_builder.Finish());

  Int32Builder indices_builder;
  ASSERT_OK(indices_builder.Reserve(kNumIndices));
  for (int64_t i = 0; i < kNumIndices; ++i) {
    indices_builder.UnsafeAppend(0);
  }
  ASSERT_OK_AND_ASSIGN(auto indices, indices_builder.Finish());

  EXPECT_RAISES_WITH_MESSAGE_THAT(
      Invalid, ::testing::HasSubstr("Take operation overflowed binary array capacity"),
      TakeAAA(*values, *indices));
}

TEST_F(ScalarTemporalTest, TestCeilFloorRoundTemporalDuration) {
  auto check_unit = [&](TimeUnit::type time_unit, CalendarUnit calendar_unit) {
    RoundTemporalOptions round_to_2_units(2, calendar_unit);
    auto values = ArrayFromJSON(duration(time_unit), "[0, 1, 2, 3, -1, -2, -3, null]");

    CheckScalarUnary("ceil_temporal", values,
                     ArrayFromJSON(duration(time_unit), "[0, 2, 2, 4, 0, -2, -2, null]"),
                     &round_to_2_units);
    CheckScalarUnary("floor_temporal", values,
                     ArrayFromJSON(duration(time_unit), "[0, 0, 2, 2, -2, -2, -4, null]"),
                     &round_to_2_units);
    CheckScalarUnary("round_temporal", values,
                     ArrayFromJSON(duration(time_unit), "[0, 2, 2, 4, 0, -2, -2, null]"),
                     &round_to_2_units);
  };

  check_unit(TimeUnit::SECOND, CalendarUnit::SECOND);
  check_unit(TimeUnit::MILLI, CalendarUnit::MILLISECOND);
  check_unit(TimeUnit::MICRO, CalendarUnit::MICROSECOND);
  check_unit(TimeUnit::NANO, CalendarUnit::NANOSECOND);

  auto check_second_based_unit = [&](CalendarUnit calendar_unit, const char* values_json,
                                     const char* ceil_round_json,
                                     const char* floor_json) {
    RoundTemporalOptions round_to_2_units(2, calendar_unit);
    auto values = ArrayFromJSON(duration(TimeUnit::SECOND), values_json);

    CheckScalarUnary("ceil_temporal", values,
                     ArrayFromJSON(duration(TimeUnit::SECOND), ceil_round_json),
                     &round_to_2_units);
    CheckScalarUnary("floor_temporal", values,
                     ArrayFromJSON(duration(TimeUnit::SECOND), floor_json),
                     &round_to_2_units);
    CheckScalarUnary("round_temporal", values,
                     ArrayFromJSON(duration(TimeUnit::SECOND), ceil_round_json),
                     &round_to_2_units);
  };

  check_second_based_unit(CalendarUnit::MINUTE,
                          "[0, 60, 120, 180, -60, -120, -180, null]",
                          "[0, 120, 120, 240, 0, -120, -120, null]",
                          "[0, 0, 120, 120, -120, -120, -240, null]");

  check_second_based_unit(CalendarUnit::HOUR,
                          "[0, 3600, 7200, 10800, -3600, -7200, -10800, null]",
                          "[0, 7200, 7200, 14400, 0, -7200, -7200, null]",
                          "[0, 0, 7200, 7200, -7200, -7200, -14400, null]");

  // A day is treated as a physical 24-hour unit for duration values.
  RoundTemporalOptions round_to_day(1, CalendarUnit::DAY);
  auto day_values = ArrayFromJSON(duration(TimeUnit::SECOND),
                                  "[0, 43200, 86399, 86400, -1, -43200, null]");

  CheckScalarUnary(
      "ceil_temporal", day_values,
      ArrayFromJSON(duration(TimeUnit::SECOND), "[0, 86400, 86400, 86400, 0, 0, null]"),
      &round_to_day);
  CheckScalarUnary(
      "floor_temporal", day_values,
      ArrayFromJSON(duration(TimeUnit::SECOND), "[0, 0, 0, 86400, -86400, -86400, null]"),
      &round_to_day);
  CheckScalarUnary(
      "round_temporal", day_values,
      ArrayFromJSON(duration(TimeUnit::SECOND), "[0, 86400, 86400, 86400, 0, 0, null]"),
      &round_to_day);

  // A week is treated as exactly seven physical days for duration values.
  RoundTemporalOptions round_to_week(1, CalendarUnit::WEEK);
  auto week_values =
      ArrayFromJSON(duration(TimeUnit::SECOND),
                    "[0, 302400, 604799, 604800, -1, -302400, -604800, null]");

  CheckScalarUnary("ceil_temporal", week_values,
                   ArrayFromJSON(duration(TimeUnit::SECOND),
                                 "[0, 604800, 604800, 604800, 0, 0, -604800, null]"),
                   &round_to_week);
  CheckScalarUnary("floor_temporal", week_values,
                   ArrayFromJSON(duration(TimeUnit::SECOND),
                                 "[0, 0, 0, 604800, -604800, -604800, -604800, null]"),
                   &round_to_week);
  CheckScalarUnary("round_temporal", week_values,
                   ArrayFromJSON(duration(TimeUnit::SECOND),
                                 "[0, 604800, 604800, 604800, 0, 0, -604800, null]"),
                   &round_to_week);

  auto values = ArrayFromJSON(duration(TimeUnit::SECOND), "[0, 1, -1, null]");

  RoundTemporalOptions round_to_month(1, CalendarUnit::MONTH);
  for (const auto* function_name :
       {"ceil_temporal", "floor_temporal", "round_temporal"}) {
    EXPECT_RAISES_WITH_MESSAGE_THAT(
        Invalid, ::testing::HasSubstr("Duration values can only be rounded using units"),
        CallFunction(function_name, {values}, &round_to_month));
  }

  RoundTemporalOptions calendar_origin(2, CalendarUnit::SECOND);
  calendar_origin.calendar_based_origin = true;
  for (const auto* function_name :
       {"ceil_temporal", "floor_temporal", "round_temporal"}) {
    EXPECT_RAISES_WITH_MESSAGE_THAT(
        Invalid,
        ::testing::HasSubstr(
            "calendar_based_origin is not supported for duration inputs"),
        CallFunction(function_name, {values}, &calendar_origin));
  }
}

TEST_F(ScalarTemporalTest, TestDurationTemporalWeekMultipleOverflow) {
  auto values = ArrayFromJSON(duration(TimeUnit::SECOND), "[0]");
  RoundTemporalOptions options(std::numeric_limits<int>::max(), CalendarUnit::WEEK);

  for (const auto* function_name :
       {"ceil_temporal", "floor_temporal", "round_temporal"}) {
    EXPECT_RAISES_WITH_MESSAGE_THAT(
        Invalid,
        ::testing::HasSubstr("Duration week multiple would not fit in 32-bit integer"),
        CallFunction(function_name, {values}, &options));
  }
}

TEST_P(BaseChunkerTest, EmbeddedNulBytesDisableBulkFilter) {
  // Regression test for GH-50481 in Lexer's own bulk filter (used for
  // chunking, separately from BlockParser's).
  //
  // Lead-in with no structural bytes so ShouldUseBulkFilter's probe of the
  // first 256 bytes decides to use the bulk filter here.
  std::string lead_in(300, 'x');
  // NUL right before the closing quote: the misaligned-SIMD-scan trigger.
  std::string trigger_field = "abc";
  trigger_field += '\0';
  trigger_field += "def";
  std::string first_row = lead_in + ",\"" + trigger_field + "\",tail\n";
  // No trailing newline on the second row, so Process() must split it out
  // as the partial remainder -- proving the first row's boundary was found.
  std::string csv = first_row + "next";

  MakeChunker();
  AssertChunkSize(*chunker_, csv, static_cast<uint32_t>(first_row.size()));
}

TEST(BlockParser, EmbeddedNulBytesDisableBulkFilter) {
  // Regression test for GH-50481: disables the bulk filter for any block
  // with an embedded NUL, so every cell here carries one.
  constexpr int32_t num_cols = 64;
  // 4x the ~512-row ParseChunk cap for num_cols == 64, so the filler block
  // spans multiple calls even if that internal constant changes.
  constexpr int32_t num_filler_rows = 4 * 512;

  // 12 bytes/value, above the bulk filter's activation threshold.
  std::string filler_cell = "xxxxxxxxxxx";
  filler_cell += '\0';

  std::string csv;
  for (int32_t r = 0; r < num_filler_rows; ++r) {
    for (int32_t c = 0; c < num_cols; ++c) {
      if (c) csv += ',';
      csv += filler_cell;
    }
    csv += '\n';
  }
  // NUL right before the closing quote: the misaligned-SIMD-scan trigger.
  csv += "\"abc";
  csv += '\0';
  csv += "def\"";
  for (int32_t c = 1; c < num_cols; ++c) {
    csv += ',';
    csv += filler_cell;
  }
  csv += '\n';

  BlockParser parser(ParseOptions::Defaults(), num_cols, /*first_row=*/0);
  AssertParseFinal(parser, csv);
  ASSERT_EQ(parser.num_rows(), num_filler_rows + 1);

  std::vector<std::string> last_row;
  GetLastRow(parser, &last_row);
  ASSERT_EQ(last_row.size(), static_cast<size_t>(num_cols));
  ASSERT_EQ(last_row[0], std::string("abc\0def", 7));
  // Other NUL-bearing fields in the row must come through unmangled too.
  for (size_t c = 1; c < last_row.size(); ++c) {
    ASSERT_EQ(last_row[c], filler_cell) << "column " << c;
  }
}

TEST_P(TestCsvFileFormat, WriteRecordBatchReaderDelimiterPropagation) {
  // Verify that CsvFileFormat::DefaultWriteOptions() propagates the parse
