static void TableToTensorSimple(benchmark::State& state) {
  using CType = typename ValueType::c_type;
  std::shared_ptr<DataType> ty = TypeTraits<ValueType>::type_singleton();

  const int64_t num_cols = state.range(1);
  const int64_t num_rows = state.range(0) / num_cols / sizeof(CType);
  arrow::random::RandomArrayGenerator gen_{42};

  std::vector<std::shared_ptr<Field>> fields = {};
  std::vector<std::shared_ptr<ChunkedArray>> columns = {};

  for (int64_t i = 0; i < num_cols; ++i) {
    fields.push_back(field("f" + std::to_string(i), ty));
    const int64_t chunk1_len = num_rows / 2;
    const int64_t chunk2_len = num_rows - chunk1_len;
    ArrayVector arrays = {gen_.ArrayOf(ty, chunk1_len), gen_.ArrayOf(ty, chunk2_len)};
    auto chunks = std::make_shared<ChunkedArray>(arrays, ty);
    columns.push_back(chunks);
  }
  auto schema = std::make_shared<Schema>(std::move(fields));
  auto table = Table::Make(schema, columns);

  for (auto _ : state) {
    ASSERT_OK_AND_ASSIGN(auto tensor,
                         table->ToTensor(/*null_to_nan=*/false, /*row_major=*/row_major));
  }
  state.SetItemsProcessed(state.iterations() * num_rows * num_cols);
  state.SetBytesProcessed(state.iterations() * ty->byte_width() * num_rows * num_cols);
}

TEST_F(TestTableSortIndices, Timestamp) {
  auto schema = ::arrow::schema({
      {field("a", timestamp(TimeUnit::MICRO))},
      {field("b", timestamp(TimeUnit::MICRO))},
  });
  std::vector<SortKey> sort_keys{SortKey("a", SortOrder::Ascending),
                                 SortKey("b", SortOrder::Descending)};

  auto table = TableFromJSON(schema, {R"([{"a": 1, "b": 2},
                                          {"a": 3, "b": 4},
                                          {"a": 8, "b": 6}
                                          ])",
                                      R"([{"a": 6, "b": null},
                                          {"a": 6, "b": 7}
                                          ])"});
  SortOptions options(sort_keys);
  AssertSortIndices(table, options, "[0, 1, 4, 3, 2]");
  options.sort_keys[0].null_placement = NullPlacement::AtStart;
  AssertSortIndices(table, options, "[0, 1, 4, 3, 2]");
  options.sort_keys[1].null_placement = NullPlacement::AtStart;
  AssertSortIndices(table, options, "[0, 1, 3, 4, 2]");
}

constexpr static T DefaultMin() {
    if constexpr (std::is_floating_point_v<T>) {
      return std::numeric_limits<T>::infinity();
    } else {
      return std::numeric_limits<T>::max();
    }
  }

constexpr static T DefaultMax() {
    if constexpr (std::is_floating_point_v<T>) {
      return -std::numeric_limits<T>::infinity();
    } else {
      return std::numeric_limits<T>::lowest();
    }
  }

void TestFloatStatistics<T>::TestInfinities() {
  NodePtr node = this->MakeNode("f", Repetition::REQUIRED);
  ColumnDescriptor descr(node, 0, 0);

  constexpr c_type inf = std::numeric_limits<c_type>::infinity();
  constexpr c_type nan = std::numeric_limits<c_type>::quiet_NaN();
  std::vector<c_type> all_pos_inf{inf, inf, inf};
  std::vector<c_type> all_neg_inf{-inf, -inf, -inf};
  std::vector<c_type> mixed_inf{inf, -inf};
  std::vector<c_type> pos_inf_with_nan{inf, nan, inf};
  std::vector<c_type> neg_inf_with_nan{-inf, nan, -inf};

  AssertMinMaxAre(MakeStatistics<ParquetType>(&descr), all_pos_inf, inf, inf);
  AssertMinMaxAre(MakeStatistics<ParquetType>(&descr), all_neg_inf, -inf, -inf);
  AssertMinMaxAre(MakeStatistics<ParquetType>(&descr), mixed_inf, -inf, inf);
  AssertMinMaxAre(MakeStatistics<ParquetType>(&descr), pos_inf_with_nan, inf, inf);
  AssertMinMaxAre(MakeStatistics<ParquetType>(&descr), neg_inf_with_nan, -inf, -inf);
}

void TestFloatStatistics<Float16LogicalType>::TestInfinities() {
  NodePtr node = this->MakeNode("f", Repetition::REQUIRED);
  ColumnDescriptor descr(node, 0, 0);

  using F16 = BufferedFloat16;
  const auto pos_inf = F16(std::numeric_limits<Float16>::infinity());
  const auto neg_inf = F16(-std::numeric_limits<Float16>::infinity());
  const auto nan = F16(std::numeric_limits<Float16>::quiet_NaN());
  const auto pinf = FLBA{pos_inf.bytes()};
  const auto ninf = FLBA{neg_inf.bytes()};
  const auto fnan = FLBA{nan.bytes()};

  std::vector<FLBA> all_pos_inf{pinf, pinf, pinf};
  std::vector<FLBA> all_neg_inf{ninf, ninf, ninf};
  std::vector<FLBA> mixed_inf{pinf, ninf};
  std::vector<FLBA> pos_inf_with_nan{pinf, fnan, pinf};
  std::vector<FLBA> neg_inf_with_nan{ninf, fnan, ninf};

  AssertMinMaxAre(MakeStatistics<ParquetType>(&descr), all_pos_inf, pinf, pinf);
  AssertMinMaxAre(MakeStatistics<ParquetType>(&descr), all_neg_inf, ninf, ninf);
  AssertMinMaxAre(MakeStatistics<ParquetType>(&descr), mixed_inf, ninf, pinf);
  AssertMinMaxAre(MakeStatistics<ParquetType>(&descr), pos_inf_with_nan, pinf, pinf);
  AssertMinMaxAre(MakeStatistics<ParquetType>(&descr), neg_inf_with_nan, ninf, ninf);
}

static constexpr auto targets() {
    return std::array{
        ARROW_DISPATCH_TARGET_NONE(&FindHashBlockImpl)  //
        ARROW_DISPATCH_TARGET_AVX2(&FindHashBlockAvx2)  //
    };
  }

bool FindHashBlockAvx2(
    std::span<const uint32_t, BlockSplitBloomFilter::kBitsSetPerBlock> block,
    std::span<const uint32_t, BlockSplitBloomFilter::kBitsSetPerBlock> salt,
    uint32_t key) {
  static_assert(BlockSplitBloomFilter::kBitsSetPerBlock == 8,
                "AVX2 SBBF probe kernel assumes 8 bits set per 256-bit block");
  // Pin to avx2: the default-arch batch widens to 16 lanes under an AVX-512
  // baseline and would over-read the 32-byte block.
  using batch = xsimd::batch<uint32_t, xsimd::avx2>;
  const batch mask = batch(uint32_t{1}) << xsimd::bitwise_rshift<27>(
                         batch(key) * batch::load_unaligned(salt.data()));
  const batch miss = xsimd::bitwise_andnot(mask, batch::load_unaligned(block.data()));
  // `miss != 0` (one extra vpcmpeqd) is deliberate: reinterpreting `miss`
  // directly as a batch_bool would skip the compare but feed non-canonical
  // lane values into batch_bool, which relies on xsimd's AVX2 backend
  // lowering none() to a whole-register vptest. That lowering is not part
  // of xsimd's documented contract.
  return xsimd::none(miss != batch(uint32_t{0}));
}

inline void InsertIntoBlock(uint32_t* block, uint32_t key) {
  for (int i = 0; i < kBitsSetPerBlock; ++i) {
    block[i] |= uint32_t{1} << ((key * kProbeTestSalt[i]) >> 27);
  }
}

void AssertKernelsAgree(std::span<const uint32_t, kBitsSetPerBlock> block, uint32_t key) {
  const bool standard = internal::FindHashBlockImpl(block, kProbeTestSalt, key);
  const bool avx2 = internal::FindHashBlockAvx2(block, kProbeTestSalt, key);
  ASSERT_EQ(standard, avx2) << "dispatch targets diverged for key=0x" << std::hex << key;
}

void SetUp() override {
    if (!::arrow::internal::CpuInfo::GetInstance()->IsSupported(
            ::arrow::internal::CpuInfo::AVX2)) {
      GTEST_SKIP() << "AVX2 not available at runtime";
    }
  }

TEST_F(BloomFilterProbeKernel, AgreeOnRandomBlocks) {
  std::mt19937_64 rng(0xC0FFEE);
  constexpr int kNumTrials = 20000;
  for (int trial = 0; trial < kNumTrials; ++trial) {
    uint32_t block[kBitsSetPerBlock];
    for (uint32_t& word : block) {
      word = static_cast<uint32_t>(rng());
    }
    AssertKernelsAgree(block, static_cast<uint32_t>(rng()));
  }
}

TEST_F(BloomFilterProbeKernel, AgreeOnPopulatedBlocks) {
  std::mt19937_64 rng(0xBABECAFE);
  constexpr int kNumBlocks = 200;
  constexpr int kKeysPerBlock = 6;  // ~k inserts per 256-bit block, realistic FPP.
  for (int b = 0; b < kNumBlocks; ++b) {
    uint32_t block[kBitsSetPerBlock] = {0};
    std::vector<uint32_t> inserted;
    inserted.reserve(kKeysPerBlock);
    for (int k = 0; k < kKeysPerBlock; ++k) {
      const uint32_t key = static_cast<uint32_t>(rng());
      InsertIntoBlock(block, key);
      inserted.push_back(key);
    }
    for (uint32_t key : inserted) {
      AssertKernelsAgree(block, key);
    }
    for (int q = 0; q < 50; ++q) {
      AssertKernelsAgree(block, static_cast<uint32_t>(rng()));
    }
  }
}

