void EhFrameSection<E>::check_range(Context<E> &ctx, InputSection<E> &isec,
                                    const ElfRel<E> &rel, i64 val, i64 lo,
                                    i64 hi) {
  if (val < lo || hi <= val)
    Error(ctx) << isec << ": relocation " << rel << " against "
               << *isec.file->symbols[rel.r_sym] << " out of range: " << val
               << " is not in [" << lo << ", " << hi << ")";
}

std::string_view Script<E>::unquote_pattern(std::string_view tok) {
  if (!tok.starts_with('"'))
    return tok;

  std::string_view str = unquote(tok);
  if (str.find_first_of("*?[\\") == str.npos)
    return str;

  std::string out;
  for (char c : str) {
    if (c == '*' || c == '?' || c == '[' || c == '\\')
      out += '\\';
    out += c;
  }
  return save_string(ctx, out);
}

i64 ObjectFile<E>::count_frag_syms(std::span<const ElfRel<E>> rels) {
  i64 n = 0;
  for (const ElfRel<E> &r : rels)
    if (const ElfSym<E> &esym = this->elf_syms[r.r_sym];
        esym.st_type == STT_SECTION &&
        (this->elf_sections[get_shndx(esym)].sh_flags & SHF_MERGE))
      n++;
  return n;
}

