                                    tbb::feeder<InputFile<E> *> &feeder) {
    file->mark_live_objects(ctx, [&](InputFile<E> *obj) { feeder.add(obj); });
  });
}

static void clear_symbol(Symbol<E> &sym) {
  sym.file = nullptr;
  sym.origin = nullptr;
  sym.value = -1;
  sym.sym_idx = -1;
  sym.ver_idx = VER_NDX_UNSPECIFIED;
  sym.is_weak = false;
  sym.is_imported = false;
  sym.is_exported = false;
}

