static std::pair<InputSection<E> *, i64>
get_pubnames_target(Context<E> &ctx, InputSection<E> &isec,
                    const PubnamesHdr &hdr, ObjectFile<E> &file) {
  i64 off = (u8 *)&hdr + offsetof(PubnamesHdr, debug_info_offset) - isec.contents;
  std::span<ElfRel<E>> rels = isec.get_rels(ctx);

  auto it = ranges::lower_bound(rels, off, std::less(), &ElfRel<E>::r_offset);
  if (it == rels.end() || it->r_offset != off)
    return {nullptr, 0};

  const ElfSym<E> &esym = file.elf_syms[it->r_sym];
  return {file.get_section(esym), esym.st_value + get_addend(isec, *it)};
}

static std::vector<NameRecord> *find_unit_names(auto &units, i32 shndx,
                                                i64 offset) {
  auto key = std::pair(shndx, offset);
  auto it = ranges::lower_bound(units, key, {}, [](const auto &unit) {
    return std::pair(unit.shndx, unit.offset);
  });

  if (it == units.end() || std::pair(it->shndx, it->offset) != key)
    return nullptr;
  return &it->names;
}

static void read_debug_info_section(Context<E> &ctx, DebugUnits &units,
                                    InputSection<E> &isec, i32 file_idx) {
  isec.uncompress(ctx);
  std::string_view contents = isec.get_contents();
  u8 *begin = (u8 *)contents.data();
  u8 *end = begin + contents.size();

  for (u8 *p = begin; p < end;) {
    ParsedDwarfUnit unit = parse_unit_header(ctx, p);

    switch (unit.unit_type) {
    case DW_UT_compile:
    case DW_UT_partial:
    case DW_UT_skeleton:
    case DW_UT_split_compile:
      units.cus.push_back(
          Compunit{unit.kind, p - begin, unit.size, file_idx, isec.shndx});
      break;
    case DW_UT_type:
    case DW_UT_split_type:
      units.tus.push_back(Typeunit{p - begin, unit.type_die_offset,
                                   unit.signature, file_idx, isec.shndx});
      break;
    default:
      Fatal(ctx) << "--gdb-index: unknown unit type: 0x" << std::hex
                 << (u32)unit.unit_type;
    }

    p += unit.size;
  }
}

static void record_comdat_owner(Symbol<E> &sig, ObjectFile<E> &file) {
  // A group claimed by an IR file belongs to the LTO result, so only an
  // LTO-generated file may own it. LLVM keeps claimed groups in its output;
  // GCC emits their contents without a group, so no file owns them.
  if (sig.comdat_claimed_by_ir && !file.is_lto_output)
    return;

  i32 priority = file.priority;
  std::atomic_ref<i32> owner(sig.sym_idx);
      record_comdat_owner(*ref.signature(ctx), *file);
  //
  // An IR file's claim is permanent: the LTO result provides the claimed
  // definitions, so a regular object extracted after LTO must not win the
  // group and resurrect a copy of them
  // (https://github.com/rui314/mold/issues/1637).
          if (sig->sym_idx == -1) {
            sig->comdat_claimed_by_ir = true;
          }

void check_symbol_version_conflicts(Context<E> &ctx) {
  if (!ctx.dynsym || ctx.arg.allow_multiple_definition)
    return;

  Timer t(ctx, "check_symbol_version_conflicts");

  for (i64 i = 1; i < ctx.dynsym->symbols.size(); i++) {
    Symbol<E> *sym = ctx.dynsym->symbols[i];
    if (sym->file->is_dso || sym->is_weak ||
        sym->ver_idx == VER_NDX_UNSPECIFIED ||
        !(sym->ver_idx & VERSYM_HIDDEN))
      continue;

    Symbol<E> *sym2 = get_symbol(ctx, sym->name());
    if (sym2 != sym && sym2->file && !sym2->file->is_dso && !sym2->is_weak &&
        sym2->ver_idx == (sym->ver_idx & ~VERSYM_HIDDEN)) {
      ObjectFile<E> *file = (ObjectFile<E> *)sym->file;
      Error(ctx) << "duplicate symbol: " << *file << ": " << *sym2->file
                 << ": " << file->symbol_names[sym->sym_idx];
    }
  }

  ctx.checkpoint();
}

void gather_symbols(Context<E> &ctx) {
  Timer t(ctx, "gather_symbols");

  ctx.symbol_map.gather(
    [&](Symbol<E> &sym, std::string_view key) {
      sym.set_name(key.substr(0, key.find('@')));
      sym.demangle = ctx.arg.demangle;
    },
    [](std::pair<InputFile<E> *, i32> &ref, Symbol<E> *sym) {
      ref.first->symbols[ref.second] = sym;
    });
}

std::vector<ReaderJob> parse_nonpositional_args(Context<E> &ctx) {
  // Input file arguments are turned into ReaderJobs for
  // read_input_files(). rctx tracks the reader state options, such as
  // --as-needed, that apply to the files after them; each job gets a
  // snapshot of the state at its position.
  std::vector<ReaderJob> jobs;
  ReaderContext rctx;
  std::vector<ReaderContext> rctx_stack;
  std::unordered_set<std::string_view> visited_libs;
      ReaderJob job = {rctx, std::string(args[0])};
      job.rctx.pos = {(u32)jobs.size()};
      jobs.push_back(std::move(job));
      rctx.in_lib = false;
      rctx.static_ = true;
      rctx.static_ = false;
      rctx.in_lib = true;
      rctx.static_ = true;
      rctx.as_needed = true;
      rctx.as_needed = false;
      rctx.whole_archive = true;
      rctx.whole_archive = false;
      if (visited_libs.insert(arg).second) {
        ReaderJob job = {rctx, std::string(arg)};
        job.is_lib = true;
        job.rctx.pos = {(u32)jobs.size()};
        jobs.push_back(std::move(job));
      }
      ReaderJob job = {rctx, std::string(arg)};
      job.rctx.pos = {(u32)jobs.size()};
      jobs.push_back(std::move(job));
      rctx_stack.push_back(rctx);
      if (rctx_stack.empty())
        Fatal(ctx) << "no state pushed before popping";
      rctx = rctx_stack.back();
      rctx_stack.pop_back();
  if (version_shown && jobs.empty())

  if (rctx.static_ || ctx.arg.relocatable) {
    ctx.arg.static_ = true;
    ctx.arg.dynamic_linker = "";
  }
  return jobs;
template std::vector<ReaderJob> parse_nonpositional_args(Context<E> &ctx);

static void new_shared_file(Context<E> &ctx, ReaderContext &rctx,
                            MappedFile *mf) {
  file->parse(ctx);
  ctx.unsorted_input_files.push_back({rctx.pos, file});
}

u8 *LockingOutputFile<E>::extend(Context<E> &ctx, i64 size) {
  i64 mapsize = this->filesize;

  if (ftruncate(this->fd, mapsize + size) == -1)
    Fatal(ctx) << "ftruncate failed: " << errno_string();

  u8 *buf =
    (u8 *)mremap(this->buf, mapsize, mapsize + size, MREMAP_MAYMOVE);
  if (buf == MAP_FAILED)
    Fatal(ctx) << this->path << ": mremap failed: " << errno_string();

  this->filesize += size;
  this->buf = buf;
  ctx.buf = buf;
  mold::output_buffer_start = buf;
  mold::output_buffer_end = buf + mapsize + size;
  return buf + mapsize;
}

u8 *extend(Context<E> &ctx, i64 size) override {
    HANDLE map = CreateFileMapping(handle, nullptr, PAGE_READWRITE, 0,
                                   this->filesize + size, nullptr);
    if (!map)
      Fatal(ctx) << this->path << ": CreateFileMapping failed: "
                 << GetLastError();

    this->buf = (u8 *)MapViewOfFile(map, FILE_MAP_WRITE, 0, 0,
                                    this->filesize + size);
    if (!this->buf)
      Fatal(ctx) << this->path << ": MapViewOfFile failed: " << GetLastError();
    CloseHandle(map);

    u8 *space = this->buf + this->filesize;
    memset(space, 0, size);
    this->filesize += size;
    ctx.buf = this->buf;
    mold::output_buffer_start = this->buf;
    mold::output_buffer_end = this->buf + this->filesize;
    return space;
  }

void close(Context<E> &ctx) override {
    Timer t(ctx, "close_file");

    UnmapViewOfFile(this->buf);
template <typename E>
u8 *LockingOutputFile<E>::extend(Context<E> &ctx, i64 size) {
  return nullptr;
}

std::span<u8> write_gdb_index(Context<E> &ctx) {
    return {};
  u8 *buf = ctx.output_file->extend(ctx, bufsize);

  return {buf, (size_t)bufsize};
template std::span<u8> write_gdb_index(Context<E> &);

u8 *extend(Context<E> &ctx, i64 size) override {
    i64 offset = align_down(this->filesize, sysconf(_SC_PAGESIZE));

    if (ftruncate(this->fd, this->filesize + size) == -1)
      Fatal(ctx) << "ftruncate failed: " << errno_string();

#if HAVE_FALLOCATE
    if (struct statfs fs;
        fstatfs(this->fd, &fs) || fs.f_type != TMPFS_MAGIC)
      fallocate(this->fd, 0, this->filesize, size);
#endif

    extension_size = this->filesize + size - offset;
    extension = (u8 *)mmap(nullptr, extension_size, PROT_READ | PROT_WRITE,
                           MAP_SHARED, this->fd, offset);
    if (extension == MAP_FAILED)
      Fatal(ctx) << this->path << ": mmap failed: " << errno_string();

#ifdef MADV_HUGEPAGE
    madvise(extension, extension_size, MADV_HUGEPAGE);
#endif
    return extension + (this->filesize - offset);
  }

static void propagate(std::span<Digest> cur, std::span<Digest> next,
                      tbb::affinity_partitioner &ap) {
  i64 num_digests = cur.size();
    hasher.update(&cur[i], sizeof(Digest));
      hasher.update(&cur[j], sizeof(Digest));
    hasher.finish(&next[i]);
  // `digests` holds the current digest of each vertex; `scratch` is
  // where a propagation round writes the next digests before the two
  // vectors swap roles.
  std::vector<Digest> digests = compute_digests<E>(ctx, sections);
  std::vector<Digest> scratch(digests.size());
  DigestMap<E> map(digests.size());
      propagate<E>(digests, scratch, edges, edge_indices, ap);
      std::swap(digests, scratch);
      i64 m = count_num_classes<E>(digests, sections, map, ap);
      sections[i]->leader = map.find(digests[i]);

void next_round() {
    if (++round == 1 << 15) {
      // The round number wrapped around, making stale slot stamps
      // ambiguous, so reset the table. In practice, ICF converges long
      // before this point.
      for (Slot &slot : slots)
        slot.hi = 0;
      round = 1;
    }
  }

bool insert(const Digest &digest, InputSection<E> *isec) {
    u64 hi;
    u64 lo;
    memcpy(&hi, digest.data(), 8);
    memcpy(&lo, digest.data() + 8, 8);

    constexpr u64 busy_bit = 1LL << 48;
    u64 tag = hi >> 16;
    u64 value = (round << 49) | tag;

    for (i64 i = hi & mask;; i = (i + 1) & mask) {
      Slot &slot = slots[i];
      u64 x = slot.hi.load(std::memory_order_acquire);

      // If the slot was last written in an earlier round, it's vacant;
      // try to claim it.
      while ((x >> 49) != round) {
        if (slot.hi.compare_exchange_weak(x, value | busy_bit,
                                          std::memory_order_acquire)) {
          slot.lo = lo;
          slot.leader = isec;
          slot.hi.store(value, std::memory_order_release);
          return true;
        }
      }

      // The slot is occupied. If it holds a different digest, try the
      // next slot.
      if ((x & 0xffff'ffff'ffff) != tag)
        continue;

      // The tags match; compare the digest bits in the second word,
      // waiting for the writer to publish them if the slot is still
      // being claimed.
      while (x & busy_bit)
        x = slot.hi.load(std::memory_order_acquire);
      if (slot.lo != lo)
        continue;

      // The digest is already in the table; keep the slot pointing to
      // the lowest-priority section.
      InputSection<E> *cur = slot.leader;
      while (isec->get_priority() < cur->get_priority() &&
             !slot.leader.compare_exchange_strong(cur, isec));
      return false;
    }
  }

InputSection<E> *find(const Digest &digest) {
    u64 hi;
    u64 lo;
    memcpy(&hi, digest.data(), 8);
    memcpy(&lo, digest.data() + 8, 8);
    u64 done = (round << 49) | (hi >> 16);

    for (i64 i = hi & mask;; i = (i + 1) & mask)
      if (slots[i].hi == done && slots[i].lo == lo)
        return slots[i].leader;
  }

static void merge_leaf_nodes(Context<E> &ctx) {
  Timer t(ctx, "merge_leaf_nodes");

  static Counter eligible("icf_eligibles");
  static Counter non_eligible("icf_non_eligibles");
  static Counter leaf("icf_leaf_nodes");

  tbb::enumerable_thread_specific<i64> num_leaves;

  tbb::parallel_for((i64)0, (i64)ctx.objs.size(), [&](i64 i) {
    for (std::unique_ptr<InputSection<E>> &isec : ctx.objs[i]->sections) {
      if (!isec || !isec->is_alive)
        continue;

      if (!is_eligible(ctx, *isec)) {
        non_eligible++;
        continue;
      }

      if (is_leaf(ctx, *isec)) {
        leaf++;
        isec->icf_leaf = true;
        num_leaves.local()++;
      } else {
        eligible++;
        isec->icf_eligible = true;
      }
    }
  });

  DigestMap<E> map(num_leaves.combine(std::plus()));

  tbb::parallel_for((i64)0, (i64)ctx.objs.size(), [&](i64 i) {
    for (std::unique_ptr<InputSection<E>> &isec : ctx.objs[i]->sections)
      if (isec && isec->is_alive && isec->icf_leaf)
        map.insert(compute_digest(ctx, *isec), isec.get());
  });

  tbb::parallel_for((i64)0, (i64)ctx.objs.size(), [&](i64 i) {
    for (std::unique_ptr<InputSection<E>> &isec : ctx.objs[i]->sections)
      if (isec && isec->is_alive && isec->icf_leaf)
        isec->leader = map.find(compute_digest(ctx, *isec));
  });
}

InputSection<E> *find(const Digest &digest) {
    u64 hi;
    u64 lo;
    memcpy(&hi, digest.data(), 8);
    memcpy(&lo, digest.data() + 8, 8);
    u64 done = (round << 49) | (hi >> 16);

    for (i64 idx = hi & mask;; idx = (idx + 1) & mask)
      if (slots[idx].head == done && slots[idx].rest == lo)
        return slots[idx].leader;
  }

static void propagate(std::span<std::vector<Digest>> digests,
                      std::span<u32> edges, std::span<u32> edge_indices,
                      bool slot, std::span<u8> converged,
                      tbb::affinity_partitioner &ap) {
    // If this node has converged, skip further iterations as it will
    // yield the same hash.
    if (digests[slot][i] == digests[!slot][i])
  static Counter counter("icf_round");
  counter++;
  // The number of distinct digests can only monotonically increase as
  // the rounds hash ever-deeper trees, so once two consecutive rounds
  // yield the same count, the partition of sections into equivalence
  // classes has stopped changing and will remain unchanged for further
  // iterations (proof omitted for brevity). Note that individual
  // digests may well still be changing at that point; sections that
  // have a cycle in downstream (i.e. recursive functions and functions
  // that call them) never settle on a digest. That doesn't matter
  // because sections in the same class change their digests in
  // lockstep, keeping the partition intact.
      propagate<E>(digests, edges, edge_indices, slot, converged, ap);
      slot = !slot;

void next_round() {
    if (++round == 1 << 15) {
      // The round number wrapped around, making stale slot stamps
      // ambiguous, so reset the table. In practice, ICF converges long
      // before this point.
      std::fill(words.begin(), words.end(), 0);
      round = 1;
    }
  }

bool insert(const Digest &digest) {
    u64 hi, lo;
    memcpy(&hi, digest.data(), 8);
    memcpy(&lo, digest.data() + 8, 8);

    constexpr u64 busy_bit = 1LL << 48;
    u64 tag = hi >> 16;
    u64 busy = (round << 49) | busy_bit | tag;
    u64 done = (round << 49) | tag;

    for (i64 idx = hi & mask;; idx = (idx + 1) & mask) {
      Atomic<u64> &w1 = words[idx * 2];
      Atomic<u64> &w2 = words[idx * 2 + 1];
      u64 x = w1.load(std::memory_order_acquire);

      // If the slot was last written in an earlier round, it's vacant;
      // try to claim it.
      while ((x >> 49) != round) {
        if (w1.compare_exchange_weak(x, busy, std::memory_order_acquire)) {
          w2.store(lo, std::memory_order_relaxed);
          w1.store(done, std::memory_order_release);
          return true;
        }
      }

      // The slot is occupied. If it holds a different digest, try the
      // next slot.
      if ((x & (busy_bit - 1)) != tag)
        continue;

      // The tags match; compare the digest bits in the second word,
      // waiting for the writer to publish them if the slot is still
      // being claimed.
      while (x & busy_bit)
        x = w1.load(std::memory_order_acquire);
      if (w2.load() == lo)
        return false;
    }
  }

static i64 sframe_fre_block_size(std::string_view data, i64 offset) {
  const u8 *attr = (const u8 *)data.data() + offset;
  i64 num_fres = *(U16<E> *)attr;
  i64 addr_size = 1 << bits(attr[2], 3, 0);

  i64 p = offset + 5;
  for (i64 i = 0; i < num_fres; i++) {
    u8 info = data[p + addr_size];
    i64 num_words = bits(info, 4, 1);
    i64 word_size = 1 << bits(info, 6, 5);
    p += addr_size + 1 + num_words * word_size;
  }
  return p - offset;
}

void ObjectFile<E>::parse_sframe(Context<E> &ctx) requires supports_sframe<E> {
  for (InputSection<E> *isec : sframe_sections) {
    // The input section is consumed by the linker; it's not copied to the
    // output as-is but reconstructed into ctx.sframe.
    isec->is_alive = false;

    std::string_view data = this->get_string(ctx, isec->shdr());
    const SFrameHeader<E> &hdr = *(const SFrameHeader<E> *)data.data();

    if (hdr.magic != SFRAME_MAGIC)
      Fatal(ctx) << *isec << ": corrupted .sframe section";
    if (hdr.abi_arch != E::sframe_abi)
      Fatal(ctx) << *isec << ": .sframe is incompatible with " << E::name;

    // We support only SFrame Version 3. A section written in an older
    // version (e.g. by an old assembler) isn't an error; we just ignore
    // it, so the functions it covers won't have SFrame info in the output.
    if (hdr.version != 3)
      continue;

    i64 hdr_len = sizeof(SFrameHeader<E>) + hdr.auxhdr_len;
    i64 num_fdes = hdr.num_fdes;
    i64 fde_off = hdr_len + hdr.fdeoff;
    i64 fre_off = hdr_len + hdr.freoff;

    std::span<ElfRel<E>> rels = isec->get_rels(ctx);
    i64 rel_idx = 0;

    for (i64 i = 0; i < num_fdes; i++) {
      i64 idx_off = fde_off + i * sizeof(SFrameFdeIdx<E>);
      const SFrameFdeIdx<E> &ent =
        *(const SFrameFdeIdx<E> *)(data.data() + idx_off);

      // Find the relocation for this FDE's func_start field. An FDE without
      // one isn't tied to any function (`ld -r` can emit such dead FDEs),
      // so we drop it.
      while (rel_idx < rels.size() && rels[rel_idx].r_offset < idx_off)
        rel_idx++;
      if (rel_idx == rels.size() || rels[rel_idx].r_offset != idx_off)
        continue;

      const ElfRel<E> &rel = rels[rel_idx];
      i64 off = fre_off + ent.func_start_fre_off;

      SFrameFde<E> fde;
      fde.isec = get_section(this->elf_syms[rel.r_sym]);
      fde.sym = this->symbols[rel.r_sym];
      fde.addend = rel.r_addend;
      fde.fre = data.substr(off, sframe_fre_block_size<E>(data, off));
      fde.func_size = ent.func_size;
      fde.num_fres = *(U16<E> *)(data.data() + off);
      sframe_fdes.push_back(fde);
    }
  }
}

void SFrameSection<E>::construct(Context<E> &ctx) requires supports_sframe<E> {
  Timer t(ctx, "sframe");

  // Gather the FDEs that describe live functions and total the size of the
  // FRE subsection. FREs carry no relocations, so their contents are
  // position-independent and are simply concatenated by copy_buf.
  for (ObjectFile<E> *file : ctx.objs)
    for (SFrameFde<E> &fde : file->sframe_fdes)
      if (fde.isec->is_alive)
        fdes.push_back(&fde);

  // If no live function has unwind info, leave the section empty so that
  // it is removed from the output.
  if (fdes.empty())
    return;

  // We always emit PC-relative function pointers; we can additionally
  // mark the index as sorted unless this is a relocatable output,
  // where the final addresses (and hence the order) aren't known.
  hdr.magic = SFRAME_MAGIC;
  hdr.version = 3;
  hdr.flags = SFRAME_F_FDE_FUNC_START_PCREL |
              (ctx.arg.relocatable ? 0 : SFRAME_F_FDE_SORTED);
  hdr.abi_arch = E::sframe_abi;
  hdr.cfa_fixed_ra_offset = is_x86_64<E> ? -8 : 0;
  hdr.num_fdes = fdes.size();
  hdr.freoff = fdes.size() * sizeof(SFrameFdeIdx<E>);

  for (SFrameFde<E> *fde : fdes) {
    hdr.fre_len += fde->fre.size();
    hdr.num_fres += fde->num_fres;
  }

  this->shdr.sh_size =
    sizeof(hdr) + fdes.size() * sizeof(SFrameFdeIdx<E>) + hdr.fre_len;
}

void SFrameSection<E>::copy_buf(Context<E> &ctx) {
  // Write the header.
  u8 *base = ctx.buf + this->shdr.sh_offset;
  memcpy(base, &hdr, sizeof(hdr));

  SFrameFdeIdx<E> *fde_base = (SFrameFdeIdx<E> *)(base + sizeof(hdr));
  u8 *fre_base = base + sizeof(hdr) + hdr.freoff;

  // The FDE index must be sorted by function address so that the runtime
  // can locate an entry by binary search. A relocatable output is the
  // exception: the addresses aren't known yet, so the index is left in its
  // current order and SFrameRelocSection emits a func_start relocation for
  // each entry in that same order.
  if (!ctx.arg.relocatable) {
    ranges::sort(fdes, {}, [&](SFrameFde<E> *fde) {
      return fde->sym->get_addr(ctx) + fde->addend;
    });
  }

  // Write the FDE index and concatenate the FRE blocks. Because
  // SFRAME_F_FDE_FUNC_START_PCREL is set, func_start_offset is the distance
  // from the field itself to the function the FDE describes.
  i64 fre_off = 0;
  for (i64 i = 0; i < fdes.size(); i++) {
    SFrameFde<E> &fde = *fdes[i];
    memcpy(fre_base + fre_off, fde.fre.data(), fde.fre.size());

    SFrameFdeIdx<E> &ent = fde_base[i];
    if (ctx.arg.relocatable) {
      ent.func_start_offset = 0;
    } else {
      u64 func_addr = fde.sym->get_addr(ctx) + fde.addend;
      u64 field_addr = this->shdr.sh_addr + sizeof(hdr) +
                       i * sizeof(SFrameFdeIdx<E>);
      ent.func_start_offset = func_addr - field_addr;
    }
    ent.func_size = fde.func_size;
    ent.func_start_fre_off = fre_off;
    fre_off += fde.fre.size();
  }
}

void SFrameRelocSection<E>::update_shdr(Context<E> &ctx) {
  this->shdr.sh_size = ctx.sframe->fdes.size() * sizeof(ElfRel<E>);
  this->shdr.sh_link = ctx.symtab->shndx;
  this->shdr.sh_info = ctx.sframe->shndx;
}

void SFrameRelocSection<E>::copy_buf(Context<E> &ctx) {
  if constexpr (supports_sframe<E>) {
    ElfRel<E> *buf = (ElfRel<E> *)(ctx.buf + this->shdr.sh_offset);
    std::span<SFrameFde<E> *> fdes = ctx.sframe->fdes;

    for (i64 i = 0; i < fdes.size(); i++) {
      SFrameFde<E> &fde = *fdes[i];
      Symbol<E> &sym = *fde.sym;

      ElfRel<E> &r = buf[i];
      memset(&r, 0, sizeof(r));
      r.r_offset = ctx.sframe->shdr.sh_addr + sizeof(SFrameHeader<E>) +
                   i * sizeof(SFrameFdeIdx<E>);
      r.r_type = E::R_SFRAME;

      if (sym.esym().st_type == STT_SECTION) {
        // We discard input section symbols and create a fresh one per output
        // section, so a reference to a section symbol needs its addend
        // adjusted by the input section's offset in its output section.
        InputSection<E> *target = sym.get_input_section();
        r.r_sym = target->output_section->shndx;
        r.r_addend = fde.addend + target->offset;
      } else {
        r.r_sym = sym.get_output_sym_idx(ctx);
        r.r_addend = fde.addend;
      }
    }
  }
}

void parse_sframe_sections(Context<E> &ctx) {
  if constexpr (supports_sframe<E>) {
    Timer t(ctx, "parse_sframe_sections");
    tbb::parallel_for_each(ctx.objs, [&](ObjectFile<E> *file) {
      file->parse_sframe(ctx);
    });
  }
}

i64 sparc_plt_ptr_offset(Context<E> &ctx, i64 pltidx) {
  i64 i = pltidx - sparc_num_small_plt;
  i64 block = i / 160;
  i64 nlarge = (i64)ctx.plt->symbols.size() - sparc_num_small_plt;
  i64 nstub = std::min<i64>(160, nlarge - block * 160);
  return 0x100000 + block * 5120 + nstub * 24 + (i % 160) * 8;
}

void rewrite_reloc_types(Context<E> &ctx, InputSection<E> &isec, ElfRel<E> *buf) {
  std::span<const ElfRel<E>> rels = isec.get_rels(ctx);
  std::span<RelocDelta> deltas = isec.extra.r_deltas;
  i64 k = 0;

  for (i64 i = 0; i < rels.size(); i++) {
    const ElfRel<E> &rel = rels[i];
    Symbol<E> &sym = *isec.file.symbols[rel.r_sym];

    i64 removed_bytes = 0;
    if (!deltas.empty()) {
      while (k < deltas.size() && deltas[k].offset < rel.r_offset)
        k++;
      if (k < deltas.size() && deltas[k].offset == rel.r_offset)
        removed_bytes = get_removed_bytes(deltas, k);
    }

    switch (rel.r_type) {
    case R_LARCH_TLS_LE_HI20_R:
    case R_LARCH_TLS_LE_ADD_R:
      // lu12i.w + add.d + addi.d => addi.d
      if (removed_bytes)
        buf[i].r_type = R_LARCH_NONE;
      break;
    case R_LARCH_PCALA_HI20:
    case R_LARCH_GOT_PC_HI20:
      // pcalau12i + addi.d/ld.d => pcaddi. The high part vanishes and the low
      // part becomes the pcaddi's PC-relative relocation.
      if (removed_bytes) {
        buf[i].r_type = R_LARCH_NONE;
        buf[i + 2].r_type = R_LARCH_PCREL20_S2;
        i += 3;
      }
      break;
    case R_LARCH_CALL36:
      // pcaddu18i + jirl => b or bl
      if (removed_bytes)
        buf[i].r_type = R_LARCH_B26;
      break;
    case R_LARCH_TLS_DESC_PC_HI20:
      // pcalau12i + addi.d => pcaddi when TLSDESC is kept; both deleted when it
      // is relaxed to IE/LE.
      if (!sym.has_tlsdesc(ctx)) {
        buf[i].r_type = R_LARCH_NONE;
      } else if (removed_bytes) {
        buf[i].r_type = R_LARCH_NONE;
        buf[i + 2].r_type = R_LARCH_TLS_DESC_PCREL20_S2;
      }
      break;
    case R_LARCH_TLS_DESC_PC_LO12:
      if (!sym.has_tlsdesc(ctx))
        buf[i].r_type = R_LARCH_NONE;
      break;
    case R_LARCH_TLS_DESC_LD:
      // TLSDESC is relaxed to IE or LE. The ld.d slot holds the first
      // instruction of the resulting sequence.
      if (sym.has_tlsdesc(ctx))
        break;
      if (sym.has_gottp(ctx))
        buf[i].r_type = R_LARCH_TLS_IE_PC_HI20;   // pcalau12i
      else if (removed_bytes)
        buf[i].r_type = R_LARCH_NONE;             // small TP offset (deleted)
      else
        buf[i].r_type = R_LARCH_TLS_LE_HI20;      // large TP offset (lu12i.w)
      break;
    case R_LARCH_TLS_DESC_CALL:
      // The jirl slot holds the second instruction of the IE or LE sequence.
      if (sym.has_tlsdesc(ctx))
        break;
      if (sym.has_gottp(ctx))
        buf[i].r_type = R_LARCH_TLS_IE_PC_LO12;   // ld.d
      else
        buf[i].r_type = R_LARCH_TLS_LE_LO12;      // ori or addi.w
      break;
    }
  }
}

void rewrite_reloc_types(Context<E> &ctx, InputSection<E> &isec, ElfRel<E> *buf) {
  std::span<const ElfRel<E>> rels = isec.get_rels(ctx);
  std::span<RelocDelta> deltas = isec.extra.r_deltas;
  i64 k = 0;

  for (i64 i = 0; i < rels.size(); i++) {
    const ElfRel<E> &rel = rels[i];
    Symbol<E> &sym = *isec.file.symbols[rel.r_sym];

    i64 removed_bytes = 0;
    if (!deltas.empty()) {
      while (k < deltas.size() && deltas[k].offset < rel.r_offset)
        k++;
      if (k < deltas.size() && deltas[k].offset == rel.r_offset)
        removed_bytes = get_removed_bytes(deltas, k);
    }

    switch (rel.r_type) {
    case R_RISCV_CALL:
    case R_RISCV_CALL_PLT:
      // auipc + jalr => jal, or c.j/c.jal
      if (removed_bytes == 4)
        buf[i].r_type = R_RISCV_JAL;
      else if (removed_bytes == 6)
        buf[i].r_type = R_RISCV_RVC_JUMP;
      break;
    case R_RISCV_GOT_HI20:
      // auipc + l[dw] GOT load => the value is materialized directly, so both
      // this and the paired PCREL_LO12 (the load) no longer need a relocation.
      if (removed_bytes) {
        buf[i].r_type = R_RISCV_NONE;
        buf[i + 2].r_type = R_RISCV_NONE;
        i += 3;
      }
      break;
    case R_RISCV_HI20:
      // lui (+ addi) => an instruction holding a link-time constant.
      if (removed_bytes)
        buf[i].r_type = R_RISCV_NONE;
      break;
    case R_RISCV_TPREL_HI20:
    case R_RISCV_TPREL_ADD:
      // lui + add => deleted; the variable is accessed relative to tp directly.
      if (removed_bytes)
        buf[i].r_type = R_RISCV_NONE;
      break;
    case R_RISCV_TLSDESC_HI20:
      if (!sym.has_tlsdesc(ctx))
        buf[i].r_type = R_RISCV_NONE;
      break;
    case R_RISCV_TLSDESC_LOAD_LO12:
    case R_RISCV_TLSDESC_ADD_LO12:
    case R_RISCV_TLSDESC_CALL: {
      Symbol<E> &sym2 =
        *isec.file.symbols[find_paired_reloc(ctx, isec, rels, sym, i).r_sym];
      if (!sym2.has_tlsdesc(ctx))
        buf[i].r_type = R_RISCV_NONE;
      break;
    }
    }
  }
}

std::vector<std::string_view> SharedFile<E>::read_verneed(Context<E> &ctx) {
  ElfShdr<E> *verneed_sec = this->find_section(SHT_GNU_VERNEED);
  if (!verneed_sec)
    return {};

  std::vector<std::string_view> vec;
  std::string_view verneed = this->get_string(ctx, *verneed_sec);
  std::string_view strtab = this->get_string(ctx, verneed_sec->sh_link);

  u8 *ptr = (u8 *)verneed.data();
  for (;;) {
    ElfVerneed<E> *vn = (ElfVerneed<E> *)ptr;
    u8 *aux_ptr = ptr + vn->vn_aux;
    for (i64 i = 0; i < vn->vn_cnt; i++) {
      ElfVernaux<E> *aux = (ElfVernaux<E> *)aux_ptr;
      u16 idx = aux->vna_other & ~VERSYM_HIDDEN;
      if (vec.size() <= idx)
        vec.resize(idx + 1);
      vec[idx] = strtab.data() + aux->vna_name;
      if (!aux->vna_next)
        break;
      aux_ptr += aux->vna_next;
    }
    if (!vn->vn_next)
      break;
    ptr += vn->vn_next;
  }
  return vec;
}

static void visit_section(Context<E> &ctx, InputSection<E> *isec,
                          tbb::feeder<InputSection<E> *> &feeder, i64 depth,
                          const StartStopMap<E> &start_stop_map) {
        visit_section(ctx, sec, feeder, depth + 1, start_stop_map);
    visit_section(ctx, isec, feeder, 0, start_stop_map);

static StartStopMap<E> build_start_stop_map(Context<E> &ctx) {
  StartStopMap<E> map;
  tbb::parallel_for_each(ctx.objs, [&](ObjectFile<E> *file) {
    for (std::unique_ptr<InputSection<E>> &isec : file->sections)
      if (isec && isec->is_alive && (isec->shdr().sh_flags & SHF_ALLOC) &&
          is_c_identifier(isec->name()))
        map.insert({isec->name(), isec.get()});
  });
  return map;
static std::string_view start_stop_name(std::string_view sym) {
  if (sym.starts_with("__start_"))
    return sym.substr(8);
  if (sym.starts_with("__stop_"))
    return sym.substr(7);
  return "";
}

                  tbb::feeder<InputSection<E> *> &feeder, i64 depth,
                  const StartStopMap<E> &start_stop_map) {
        visit(ctx, sec, feeder, depth + 1, start_stop_map);
    if (SectionFragment<E> *frag = sym.get_frag()) {
      continue;
    }

    mark(sym.get_input_section());

    // A reference to __start_<name> or __stop_<name> keeps every section
    // named <name> alive, mirroring how those symbols are defined.
    if (std::string_view sec = start_stop_name(sym.name());
        !sec.empty()) {
      auto [i, end] = start_stop_map.equal_range(sec);
      for (; i != end; ++i)
        mark(i->second);
    }
                 tbb::concurrent_vector<InputSection<E> *> &rootset,
                 const StartStopMap<E> &start_stop_map) {
    visit(ctx, isec, feeder, 0, start_stop_map);
  StartStopMap<E> start_stop_map = build_start_stop_map(ctx);
  mark(ctx, rootset, start_stop_map);

static std::string_view start_stop_name(std::string_view sym) {
  if (sym.starts_with("__start_"))
    return sym.substr(8);
  if (sym.starts_with("__stop_"))
    return sym.substr(7);
  return "";
}

static void write_sleb128(std::vector<u8> &buf, i64 val) {
  for (;;) {
    buf.push_back((val & 0x7f) | 0x80);
    if ((val >> 6) == 0 || (val >> 6) == -1)
      break;
    val >>= 7;
  }
  buf.back() &= 0x7f;
}

static std::vector<u8> encode_android(std::span<ElfRel<E>> rels) {
  constexpr i64 GROUPED_BY_INFO = 1;
  constexpr i64 GROUPED_BY_OFFSET_DELTA = 2;
  constexpr i64 GROUP_HAS_ADDEND = 8;

  auto r_info = [](const ElfRel<E> &r) -> Word<E> {
    return ((Word<E> *)&r)[1];
  };

  std::vector<u8> buf = {'A', 'P', 'S', '2'};
  write_sleb128(buf, rels.size());
  write_sleb128(buf, 0);  // initial offset state

  if (rels.empty())
    return buf;

  // APS2 offset deltas are signed, so the format doesn't require
  // relocations to be in increasing-offset order. Sort by (r_type,
  // r_sym, r_offset) so all relocs of the dominant type (typically
  // R_RELATIVE, ~90% of dynrels in a real Android binary) land in one
  // contiguous block. That collapses dozens of type-broken groups into
  // a few large info-grouped runs.
  ranges::sort(rels, {}, [&](const ElfRel<E> &r) {
    return std::tuple{r.r_type, r.r_sym, r.r_offset};
  });

  i64 prev_offset = 0;
  i64 prev_addend = 0;
  i64 i = 0;

  while (i < (i64)rels.size()) {
    i64 offset_delta = (i64)rels[i].r_offset - prev_offset;
    i64 cur_info = r_info(rels[i]);

    // Greedily extend the group while consecutive relocations share the
    // same offset_delta and r_info.
    i64 j = i + 1;
    while (j < (i64)rels.size() &&
           r_info(rels[j]) == cur_info &&
           (i64)rels[j].r_offset - (i64)rels[j - 1].r_offset == offset_delta)
      j++;

    i64 size = j - i;
    i64 flags = 0;
    if (size > 1)
      flags = GROUPED_BY_INFO | GROUPED_BY_OFFSET_DELTA;
    if constexpr (E::is_rela)
      flags |= GROUP_HAS_ADDEND;

    write_sleb128(buf, size);
    write_sleb128(buf, flags);
    write_sleb128(buf, offset_delta);
    write_sleb128(buf, cur_info);

    if constexpr (E::is_rela) {
      for (i64 k = i; k < j; k++) {
        i64 cur = rels[k].r_addend;
        write_sleb128(buf, cur - prev_addend);
        prev_addend = cur;
      }
    }

    prev_offset = rels[j - 1].r_offset;
    i = j;
  }
  return buf;
}

std::vector<ElfRel<E>> PPC64OpdSection::collect_dynrels(Context<E> &ctx) const {
  if (!ctx.arg.pic)
    return {};

  std::vector<ElfRel<E>> rels;

  for (Symbol<E> *sym : symbols) {
    u64 loc = sym->get_opd_addr(ctx);
    rels.emplace_back(loc, E::R_RELATIVE, 0, sym->get_addr(ctx, NO_PLT | NO_OPD));
    rels.emplace_back(loc + 8, E::R_RELATIVE, 0, ctx.extra.TOC->value);
  }
  return rels;

std::vector<ElfRel<E>>
OutputSection<E>::collect_dynrels(Context<E> &ctx) const {
  std::vector<ElfRel<E>> rels;

  for (const AbsRel<E> &r : abs_rels) {
    Symbol<E> &sym = *r.sym;
    u64 S = sym.get_addr(ctx);
    u64 A = r.addend;
    u64 P = this->shdr.sh_addr + r.isec->offset + r.offset;

    if constexpr (is_riscv<E> || is_loongarch<E>) {
      i64 delta = get_r_delta(*r.isec, r.offset);
      P -= delta;
    }

    switch (r.kind) {
    case ABS_REL_NONE:
      break;
    case ABS_REL_BASEREL:
      rels.emplace_back(P, E::R_RELATIVE, 0, S + A);
      break;
    case ABS_REL_IFUNC:
      if constexpr (supports_ifunc<E>)
        rels.emplace_back(P, E::R_IRELATIVE, 0, sym.get_addr(ctx, NO_PLT) + A);
      break;
    case ABS_REL_DYNREL:
      rels.emplace_back(P, E::R_ABS, sym.get_dynsym_idx(ctx), A);
      break;
    }
  }

  return rels;
}

TEST(MmapTest, OpenWhileFileHeldForWriting) {
  const char *path = "mmap_concurrent_writer_test.txt";
  const char *content = "hello";

  {
    std::ofstream f(path, std::ios::binary);
    f.write(content, static_cast<std::streamsize>(strlen(content)));
  }
  auto file_cleanup = detail::scope_exit([&] { std::remove(path); });

  HANDLE writer = ::CreateFileA(path, GENERIC_WRITE, FILE_SHARE_READ, NULL,
                                OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
  ASSERT_NE(INVALID_HANDLE_VALUE, writer);
  auto handle_cleanup = detail::scope_exit([&] { ::CloseHandle(writer); });

  detail::mmap m(path);
  ASSERT_TRUE(m.is_open());
  EXPECT_EQ(strlen(content), m.size());
  EXPECT_EQ(0, std::memcmp(content, m.data(), strlen(content)));
}

std::string unique_unresolvable_host(int n) {
  // .invalid is reserved (RFC 6761) and is never served by real DNS, but
  // glibc still asks the configured nameserver — which is exactly the path
  // we want to exercise. A unique label per call avoids the resolver cache.
  auto t = std::chrono::steady_clock::now().time_since_epoch().count();
  return "h-" + std::to_string(::getpid()) + "-" + std::to_string(t) + "-" +
         std::to_string(n) + ".invalid";
}
}

ST(GetAddrInfoAsyncCancelTest, DirectCallSingleThread) {
  if (!should_run_issue_2431_tests()) {
    GTEST_SKIP()
        << "Set CPPHTTPLIB_TEST_ISSUE_2431=1 (and sinkhole DNS) to run";
  }

  for (int i = 0; i < 8; ++i) {
    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    auto host = unique_unresolvable_host(i);
    struct addrinfo *result = nullptr;
    int rc = detail::getaddrinfo_with_timeout(host.c_str(), "80", &hints,
                                              &result, /*timeout_sec=*/1);
    if (rc == 0 && result) { freeaddrinfo(result); }
  }

  // Give orphaned getaddrinfo_a worker threads a chance to write into the
  // stack region they still believe holds their gaicb.
  std::this_thread::sleep_for(std::chrono::seconds(3));
}

ST(GetAddrInfoAsyncCancelTest, DirectCallMultiThread) {
  if (!should_run_issue_2431_tests()) {
    GTEST_SKIP()
        << "Set CPPHTTPLIB_TEST_ISSUE_2431=1 (and sinkhole DNS) to run";
  }

  std::atomic<bool> stop{false};
  std::vector<std::thread> threads;
  for (int t = 0; t < 8; ++t) {
    threads.emplace_back([t, &stop] {
      int i = 0;
      while (!stop.load(std::memory_order_relaxed)) {
        struct addrinfo hints;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_UNSPEC;
        hints.ai_socktype = SOCK_STREAM;

        auto host = unique_unresolvable_host(t * 100000 + i++);
        struct addrinfo *result = nullptr;
        int rc = detail::getaddrinfo_with_timeout(host.c_str(), "80", &hints,
                                                  &result, /*timeout_sec=*/1);
        if (rc == 0 && result) { freeaddrinfo(result); }
      }
    });
  }

  std::this_thread::sleep_for(std::chrono::seconds(8));
  stop.store(true, std::memory_order_relaxed);
  for (auto &th : threads) {
    th.join();
  }
  std::this_thread::sleep_for(std::chrono::seconds(3));
}

ST(GetAddrInfoAsyncCancelTest, ClientGetMultiThread) {
  if (!should_run_issue_2431_tests()) {
    GTEST_SKIP()
        << "Set CPPHTTPLIB_TEST_ISSUE_2431=1 (and sinkhole DNS) to run";
  }

  std::atomic<bool> stop{false};
  std::vector<std::thread> threads;
  for (int t = 0; t < 8; ++t) {
    threads.emplace_back([t, &stop] {
      int i = 0;
      while (!stop.load(std::memory_order_relaxed)) {
        auto host = unique_unresolvable_host(t * 100000 + i++);
        Client cli(host, 80);
        cli.set_connection_timeout(1, 0);
        cli.set_read_timeout(1, 0);
        cli.set_write_timeout(1, 0);
        (void)cli.Get("/");
      }
    });
  }

  std::this_thread::sleep_for(std::chrono::seconds(8));
  stop.store(true, std::memory_order_relaxed);
  for (auto &th : threads) {
    th.join();
  }
  std::this_thread::sleep_for(std::chrono::seconds(3));
}

