inline Execution* checkExeValid(Execution* exe) {
    if (exe != nullptr && !exe->valid()) {
        delete exe;
        return nullptr;
    }
    return exe;
}

e float _readElement(const int8_t* ptr, int index, int bytes) {
#ifdef __aarch64__
    if (bytes == 2) return (float)((const __fp16*)ptr)[index];
#endif
    return ((const float*)ptr)[index];
}

static inl

e void _writeElement(int8_t* ptr, int index, float val, int bytes) {
#ifdef __aarch64__
    if (bytes == 2) { ((__fp16*)ptr)[index] = (__fp16)val; return; }
#endif
    ((float*)ptr)[index] = val;
}

        co

static void MNNRankOneUpdateDefault(float* S, const float* k, const float* delta, size_t dk, size_t dv) {
    for (size_t i = 0; i < dk; ++i) {
        float k_val = k[i];
        float* row = S + i * dv;
        for (size_t j = 0; j < dv; ++j) {
            row[j] += k_val * delta[j];
        }
    }
}

static void MNNDualMatVecDefault(const float* S, const float* k, const float* q, float* out_k, float* out_q, size_t dk, size_t dv) {
    ::memset(out_k, 0, dv * sizeof(float));
    ::memset(out_q, 0, dv * sizeof(float));
    for (size_t i = 0; i < dk; ++i) {
        float k_val = k[i];
        float q_val = q[i];
        const float* row = S + i * dv;
        for (size_t j = 0; j < dv; ++j) {
            out_k[j] += row[j] * k_val;
            out_q[j] += row[j] * q_val;
        }
    }
}

static void MNNDecayRankOneUpdateDefault(float* S, const float* k, const float* delta, float decay, size_t dk, size_t dv) {
    for (size_t i = 0; i < dk; ++i) {
        float k_val = k[i];
        float* row = S + i * dv;
        for (size_t j = 0; j < dv; ++j) {
            row[j] = decay * row[j] + k_val * delta[j];
        }
    }
}

virtual float onComputeFlops(const MNN::Op* op, const std::vector<Tensor*>& inputs, const std::vector<Tensor*>& outputs) const override {
        auto param = op->main_as_LinearAttentionParam();
        auto input = inputs[0];
        float L = static_cast<float>(input->length(2));
        float D = static_cast<float>(input->length(1));
        int H = param->num_v_heads();
        int dk = param->head_k_dim();
        int dv = param->head_v_dim();
        int K = inputs[3]->length(2);
        float flops = 0.f;
        // Conv1D + SiLU: D * L * (2*K + 4)
        flops += D * L * (2.f * K + 4.f);
        // Per timestep per head: DualMatVec (4*dk*dv) + DecayRankOneUpdate (3*dk*dv) + delta (3*dv)
        flops += L * H * (7.f * dk * dv + 3.f * dv);
        return flops / FLOPS_M;
    }

tatic void fillRandom(float* data, int size, float scale = 0.1f) {
    for (int i = 0; i < size; ++i) {
        data[i] = ((i % 17) - 8) * scale;
    }
}

tatic void fillGate(float* data, int size) {
    for (int i = 0; i < size; ++i) {
        data[i] = -0.1f * ((i % 5) + 1);
    }
}

tatic void fillBeta(float* data, int size) {
    for (int i = 0; i < size; ++i) {
        data[i] = 0.1f * ((i % 9) + 1);
    }
}

tatic std::shared_ptr<Module> _makeModule(
    int numKHeads, int numVHeads, int headKDim, int headVDim, bool useL2Norm, int numThread = 1)
{
    auto qkv   = _Input();
    auto gate   = _Input();
    auto beta   = _Input();
    auto convW  = _Input();

    std::shared_ptr<MNN::OpT> op(new MNN::OpT);
    op->type = MNN::OpType_LinearAttention;
    op->main.type = MNN::OpParameter_LinearAttentionParam;
    op->main.value = new MNN::LinearAttentionParamT;
    auto* param = op->main.AsLinearAttentionParam();
    param->attn_type     = "gated_delta_rule";
    param->num_k_heads   = numKHeads;
    param->num_v_heads   = numVHeads;
    param->head_k_dim    = headKDim;
    param->head_v_dim    = headVDim;
    param->use_qk_l2norm = useL2Norm;

    auto o = Variable::create(Expr::create(op.get(), {qkv, gate, beta, convW}));
    auto buffer = Variable::save({o});

    MNN::ScheduleConfig config;
    auto status = MNNTestSuite::get()->pStaus;
    config.type = (MNNForwardType)status.forwardType;
    MNN::BackendConfig bnConfig;
    bnConfig.memory    = (MNN::BackendConfig::MemoryMode)status.memory;
    bnConfig.precision = (MNN::BackendConfig::PrecisionMode)status.precision;
    bnConfig.power     = (MNN::BackendConfig::PowerMode)status.power;
    config.backendConfig = &bnConfig;
    config.numThread = numThread;

    std::shared_ptr<Executor::RuntimeManager> rtmgr(Executor::RuntimeManager::createRuntimeManager(config));
    std::shared_ptr<Module> m(Module::load({}, {}, (uint8_t*)buffer.data(), buffer.size(), rtmgr));
    return m;
}

irtual bool run(int precision) {
        struct TestCase {
            int numKHeads, numVHeads, headKDim, headVDim, seqLen, K_conv;
            const char* name;
        };

        std::vector<TestCase> cases = {
            // Decode scenarios (L=1) - most common in LLM inference
            {4, 4, 64, 64, 1, 4, "decode_H4_d64"},
            {16, 16, 64, 64, 1, 4, "decode_H16_d64"},
            {4, 4, 128, 128, 1, 4, "decode_H4_d128"},
            {16, 16, 128, 128, 1, 4, "decode_H16_d128"},
            // Prefill scenarios
            {4, 4, 64, 64, 16, 4, "prefill16_H4_d64"},
            {16, 16, 64, 64, 16, 4, "prefill16_H16_d64"},
            {4, 4, 64, 64, 64, 4, "prefill64_H4_d64"},
            {16, 16, 64, 64, 64, 4, "prefill64_H16_d64"},
            {4, 4, 64, 64, 128, 4, "prefill128_H4_d64"},
            {16, 16, 64, 64, 128, 4, "prefill128_H16_d64"},
            {4, 4, 64, 64, 2048, 4, "prefill2048_H4_d64"},
            {16, 16, 64, 64, 2048, 4, "prefill2048_H16_d64"},
        };

        const int B = 1;
        const bool useL2Norm = true;
        const int numThread = 4;
        const int warmup = 5;
        const int repeat = 20;

        for (auto& tc : cases) {
            int key_dim = tc.numKHeads * tc.headKDim;
            int val_dim = tc.numVHeads * tc.headVDim;
            int D = 2 * key_dim + val_dim;

            auto module = _makeModule(tc.numKHeads, tc.numVHeads, tc.headKDim, tc.headVDim, useL2Norm, numThread);
            if (!module) {
                MNN_PRINT("Error: failed to create module for %s\n", tc.name);
                return false;
            }

            auto qkvVar  = _Input({B, D, tc.seqLen}, NCHW, halide_type_of<float>());
            auto gateVar = _Input({B, tc.seqLen, tc.numVHeads}, NCHW, halide_type_of<float>());
            auto betaVar = _Input({B, tc.seqLen, tc.numVHeads}, NCHW, halide_type_of<float>());
            auto convWVar = _Input({D, 1, tc.K_conv}, NCHW, halide_type_of<float>());

            fillRandom(qkvVar->writeMap<float>(), B * D * tc.seqLen);
            fillGate(gateVar->writeMap<float>(), B * tc.seqLen * tc.numVHeads);
            fillBeta(betaVar->writeMap<float>(), B * tc.seqLen * tc.numVHeads);
            fillRandom(convWVar->writeMap<float>(), D * 1 * tc.K_conv, 0.05f);

            // Warmup
            for (int t = 0; t < warmup; ++t) {
                auto outputs = module->onForward({qkvVar, gateVar, betaVar, convWVar});
                if (outputs.empty()) {
                    MNN_PRINT("Error: empty output for %s\n", tc.name);
                    return false;
                }
            }

            // Benchmark
            MNN::Timer _t;
            for (int t = 0; t < repeat; ++t) {
                module->onForward({qkvVar, gateVar, betaVar, convWVar});
            }
            float avgMs = _t.durationInUs() / 1000.0f / (float)repeat;

            MNN_PRINT("[%s] B=%d H=%d dk=%d dv=%d L=%d, Avg: %.3f ms\n",
                      tc.name, B, tc.numVHeads, tc.headKDim, tc.headVDim, tc.seqLen, avgMs);
        }

        return true;
    }

TEST(ColumnNullableTest, ApplyNullMapAfterMutateLeavesSharedSourceUnchanged) {
    auto nested_mut = ColumnString::create();
    nested_mut->insert_data("-", 1);
    nested_mut->insert_data("-", 1);
    nested_mut->insert_data("2628", 4);
    ColumnPtr nested = std::move(nested_mut);

    auto null_map_mut = ColumnUInt8::create();
    null_map_mut->insert_value(0);
    null_map_mut->insert_value(0);
    null_map_mut->insert_value(0);
    ColumnPtr null_map = std::move(null_map_mut);

    ColumnPtr src = ColumnNullable::create(nested, null_map);
    ColumnPtr held = src; // second owner, as if() holds arg_else.column alongside the block's copy

    auto cond = ColumnUInt8::create();
    cond->insert_value(1);
    cond->insert_value(1);
    cond->insert_value(0);

    // mirrors if(cond, NULL, nullable_col): mutate() the shared column, then OR in the null map
    auto mutated = (*std::move(held)).mutate();
    assert_cast<ColumnNullable&>(*mutated).apply_null_map(*cond);

    EXPECT_FALSE(assert_cast<const ColumnNullable&>(*src).has_null());
    EXPECT_TRUE(assert_cast<const ColumnNullable&>(*mutated).has_null());
}

TEST(DataTypeDecimalSerDeFromStringStrictModeBatchTest, SkipsNullRowsWithoutDesyncingOffsets) {
    auto str_col = ColumnHelper::create_column<DataTypeString>({"-", "2628"});
    const auto& col_str = assert_cast<const ColumnString&>(*str_col);
    constexpr std::array<NullMap::value_type, 2> null_map {1, 0};

    auto column_to = ColumnDecimal32::create(0, 0);
    DataTypeDecimalSerDe<TYPE_DECIMAL32> serde(9, 0);
    DataTypeSerDe::FormatOptions options;

    Status st = serde.from_string_strict_mode_batch(col_str, *column_to, options, null_map.data());
    ASSERT_TRUE(st.ok()) << st;
    ASSERT_EQ(column_to->size(), 2);
    EXPECT_EQ(column_to->get_data()[1].value, 2628);
}

