            c->set_unique_id(uid);
            c->set_name(name);
            c->set_type(type);
            c->set_is_key(is_key);
            int len = 4;
            if (type == "TINYINT") {
                len = 1;
            } else if (type == "BIGINT") {
                len = 8;
            } else if (type == "LARGEINT") {
                len = 16;
            }
