void RowsetId::init(std::string_view rowset_id_str) {
    // for new rowsetid its a 48 hex string
    // if the len < 48, then it is an old format rowset id
    if (rowset_id_str.length() < 48) [[unlikely]] {
        int64_t high;
        auto [_, ec] = std::from_chars(rowset_id_str.data(),
                                       rowset_id_str.data() + rowset_id_str.length(), high);
        if (ec != std::errc {}) [[unlikely]] {
            if (config::force_regenerate_rowsetid_on_start_error) {
                LOG(WARNING) << "failed to init rowset id: " << rowset_id_str;
                high = MAX_ROWSET_ID - 1;
            } else {
                throw Exception(Status::FatalError("failed to init rowset id: {}", rowset_id_str));
            }
        }
        init(1, high, 0, 0);
    } else {
        int64_t high = 0;
        int64_t middle = 0;
        int64_t low = 0;
        from_hex(&high, rowset_id_str.substr(0, 16));
        from_hex(&middle, rowset_id_str.substr(16, 16));
        from_hex(&low, rowset_id_str.substr(32, 16));
        init(high >> 56, high & LOW_56_BITS, middle, low);
    }
}

void RowsetId::init(int64_t id_version, int64_t high, int64_t middle, int64_t low) {
    version = cast_set<int8_t>(id_version);
    if (UNLIKELY(high >= MAX_ROWSET_ID)) {
        throw Exception(Status::FatalError("inc rowsetid is too large:{}", high));
    }
    hi = (id_version << 56) + (high & LOW_56_BITS);
    mi = middle;
    lo = low;
}

std::string RowsetId::to_string() const {
    if (version < 2) {
        return std::to_string(hi & LOW_56_BITS);
    } else {
        char buf[48];
        to_hex(hi, buf);
        to_hex(mi, buf + 16);
        to_hex(lo, buf + 32);
        return {buf, 48};
    }
}

size_t std::hash<doris::RowsetId>::operator()(const doris::RowsetId& rowset_id) const {
    size_t seed = 0;
    seed = doris::HashUtil::xxHash64WithSeed((const char*)&rowset_id.hi, sizeof(rowset_id.hi),
                                             seed);
    seed = doris::HashUtil::xxHash64WithSeed((const char*)&rowset_id.mi, sizeof(rowset_id.mi),
                                             seed);
    seed = doris::HashUtil::xxHash64WithSeed((const char*)&rowset_id.lo, sizeof(rowset_id.lo),
                                             seed);
    return seed;
}

BlockAggregator::BlockAggregator(TabletSchema& tablet_schema, BaseTabletSPtr tablet,
                                 std::shared_ptr<MowContext> mow_context,
                                 const PartialUpdateInfo& partial_update_info,
                                 const RowKeyEncoder& key_encoder,
                                 const segment_v2::MowKeyProbe& probe,
                                 HistoricalRowFetcher& fetcher)
        : _tablet_schema(tablet_schema),
          _tablet(std::move(tablet)),
          _mow_context(std::move(mow_context)),
          _partial_update_info(partial_update_info),
          _key_encoder(key_encoder),
          _convertor(std::make_unique<OlapBlockDataConvertor>()),
          _probe(probe),
          _fetcher(fetcher) {
    _convertor->resize(tablet_schema.num_columns());
    for (uint32_t cid = 0; cid < tablet_schema.num_key_columns(); ++cid) {
        _convertor->add_column_data_convertor_at(tablet_schema.column(cid), cid);
    }
    if (tablet_schema.has_sequence_col()) {
        auto cid = cast_set<uint32_t>(tablet_schema.sequence_col_idx());
        _convertor->add_column_data_convertor_at(tablet_schema.column(cid), cid);
    }
}

Status BlockAggregator::_generate_encoded_default_seq_value(std::string* encoded_value) {
    const auto& seq_column = _tablet_schema.column(_tablet_schema.sequence_col_idx());
    auto block = _tablet_schema.create_block_by_cids(
            {cast_set<uint32_t>(_tablet_schema.sequence_col_idx())});
    if (seq_column.has_default_value()) {
        auto idx = _tablet_schema.sequence_col_idx() - _tablet_schema.num_key_columns();
        const auto& default_value = _partial_update_info.default_values[idx];
        StringRef str {default_value};
        RETURN_IF_ERROR(block.get_by_position(0).type->get_serde()->default_from_string(
                str, *block.get_by_position(0).column->assert_mutable().get()));

    } else {
        block.get_by_position(0).column->assert_mutable()->insert_default();
    }
    DCHECK_EQ(block.rows(), 1);
    auto olap_data_convertor = std::make_unique<OlapBlockDataConvertor>();
    olap_data_convertor->add_column_data_convertor(seq_column);
    olap_data_convertor->set_source_content(&block, 0, 1);
    auto [status, column] = olap_data_convertor->convert_column_data(0);
    if (!status.ok()) {
        return status;
    }
    // include marker
    _key_encoder.append_seq_suffix(encoded_value, column, 0);
    return Status::OK();
}

Status probe_and_plan_flexible(TransformExecContext& ctx, RowKeyEncoder& key_encoder,
                               MowKeyProbe& probe, HistoricalRowFetcher& fetcher,
                               const std::vector<RowsetSharedPtr>& specified_rowsets,
                               std::vector<std::unique_ptr<SegmentCacheHandle>>& segment_caches,
                               const std::vector<IOlapColumnDataAccessor*>& key_columns,
                               IOlapColumnDataAccessor* seq_column, const signed char* delete_signs,
                               size_t num_rows, Block* block,
                               std::vector<BitmapValue>& skip_bitmaps,
                               std::vector<bool>& use_default_or_null_flag,
                               bool& has_default_or_nullable) {
    const TabletSchema& schema = *ctx.tablet_schema;
    PartialUpdateInfo& info = *ctx.partial_update_info;
    const bool schema_has_seq = schema.has_sequence_col();
    const int32_t seq_col_unique_id =
            schema_has_seq ? schema.column(schema.sequence_col_idx()).unique_id() : -1;
    const int32_t delete_sign_col_unique_id = schema.column(schema.delete_sign_idx()).unique_id();

    use_default_or_null_flag.reserve(num_rows);
    for (size_t pos = 0; pos < num_rows; ++pos) {
        // Encode without touching the row cache: the writer's key index build
        // invalidates every row's cache entry under the same conditions, so the
        // erase runs once there, not twice.
        // one block == one fresh segment: segment_pos == block row index
        const bool row_has_seq = schema_has_seq && !skip_bitmaps[pos].contains(seq_col_unique_id);
        std::string key = key_encoder.full_encode_primary_keys(key_columns, pos);
        if (row_has_seq) {
            key_encoder.append_seq_suffix(&key, seq_column, pos);
        }
        const bool have_delete_sign =
                !skip_bitmaps[pos].contains(delete_sign_col_unique_id) && delete_signs[pos] != 0;
        ProbeOutcome out =
                DORIS_TRY(probe.probe(key, /*segment_pos=*/pos, row_has_seq, have_delete_sign,
                                      specified_rowsets, segment_caches, ctx.partial_update_stats));
        if (out.result == KeyProbeResult::NOT_FOUND && !have_delete_sign) {
            RETURN_IF_ERROR(info.handle_new_key(
                    schema,
                    [&]() -> std::string {
                        return block->dump_one_line(pos, cast_set<int>(schema.num_key_columns()));
                    },
                    &skip_bitmaps[pos]));
        }
        has_default_or_nullable |= out.use_default_or_null;
        use_default_or_null_flag.emplace_back(out.use_default_or_null);
        if (!out.use_default_or_null) {
            fetcher.pin_rowset(out.rowset);
            fetcher.plan_flexible_read(out.loc, pos, skip_bitmaps[pos]);
        }
    }
    CHECK_EQ(use_default_or_null_flag.size(), num_rows);
    return Status::OK();
}

Status FlexiblePartialUpdateFillStage::apply(TransformExecContext& ctx, Block* block) const {
    DBUG_EXECUTE_IF("VerticalSegmentWriter._append_block_with_flexible_partial_content.sleep",
                    { sleep(60); })

    const TabletSchemaSPtr& tablet_schema = ctx.tablet_schema;
    TabletSchema& schema = *tablet_schema;
    auto& info = *ctx.partial_update_info;

    DCHECK(block->columns() == schema.num_columns());
    DCHECK(schema.has_skip_bitmap_col());
    const auto skip_bitmap_col_idx = schema.skip_bitmap_col_idx();

    Block full_block = schema.create_block();

    const std::vector<RowsetSharedPtr>& specified_rowsets = ctx.mow_context->rowset_ptrs;
    std::vector<std::unique_ptr<SegmentCacheHandle>> segment_caches(specified_rowsets.size());

    // encoder shared with the aggregator, which owns the conversion code
    RowKeyEncoder key_encoder(schema, /*mow=*/true);
    // FE forbids partial update on mow tables with cluster keys; everything
    // below assumes sort keys == schema keys
    DCHECK_EQ(key_encoder.num_sort_key_columns(), schema.num_key_columns());

    MowKeyProbe probe = MowKeyProbe::for_partial_update(
            ctx.tablet.get(), tablet_schema.get(), schema.has_sequence_col(), ctx.mow_context,
            ctx.rowset_id, cast_set<uint32_t>(ctx.segment_id), /*flexible=*/true);
    HistoricalRowFetcher fetcher(ctx.rowset_ctx->make_historical_row_retriever_context());
    BlockAggregator aggregator(schema, ctx.tablet, ctx.mow_context, info, key_encoder, probe,
                               fetcher);

    // 1. aggregate duplicate keys inside the block; the row set may shrink
    size_t num_rows = block->rows();
    RETURN_IF_ERROR(aggregator.aggregate_for_flexible_partial_update(
            block, num_rows, specified_rowsets, segment_caches));
    num_rows = block->rows();

    // 2. encode primary key columns + sequence column
    std::vector<IOlapColumnDataAccessor*> key_columns;
    RETURN_IF_ERROR(aggregator.convert_pk_columns(block, 0, num_rows, key_columns));
    IOlapColumnDataAccessor* seq_column = nullptr;
    RETURN_IF_ERROR(aggregator.convert_seq_column(block, 0, num_rows, seq_column));

    std::vector<BitmapValue>* skip_bitmaps =
            &get_mutable_skip_bitmap_column(block, skip_bitmap_col_idx)->get_data();
    const auto* delete_signs = BaseTablet::get_delete_sign_column_data(*block, num_rows);
    DCHECK(delete_signs != nullptr);

    for (size_t cid = 0; cid < schema.num_key_columns(); ++cid) {
        // Carry the input's type along with its column: a variant V2 input column
        // is typed differently from the slot the schema-created block holds.
        const auto& input_column = block->get_by_position(cid);
        auto& full_column = full_block.get_by_position(cid);
        full_column.column = input_column.column;
        full_column.type = input_column.type;
    }

    // 3. probe every key against the load's rowset snapshot
    bool has_default_or_nullable = false;
    std::vector<bool> use_default_or_null_flag;
    RETURN_IF_ERROR(probe_and_plan_flexible(ctx, key_encoder, probe, fetcher, specified_rowsets,
                                            segment_caches, key_columns, seq_column, delete_signs,
                                            num_rows, block, *skip_bitmaps,
                                            use_default_or_null_flag, has_default_or_nullable));

    maybe_add_sentinel_mark(ctx);

    // 4. fill the non-primary-key columns one cell at a time, as marked by the
    //    skip bitmap
    RETURN_IF_ERROR(fetcher.fill_non_primary_key_columns(
            schema, full_block, use_default_or_null_flag, has_default_or_nullable,
            /*segment_start_pos=*/0, /*block_start_pos=*/0, block, skip_bitmaps));
    // TODO(bobhan1): should we replace the skip bitmap column with empty bitmaps to reduce
    // storage occupation? this column is not needed in read path for merge-on-write table

    // 5. swap in the filled block; downstream it looks like a plain upsert
    block->swap(full_block);
    return Status::OK();
}

void fill_rowset_ctx(RowsetWriterContext* rwc, const TabletSchemaSPtr& schema,
                         const TabletSharedPtr& tablet, std::shared_ptr<PartialUpdateInfo> pui,
                         const RowsetId& new_rsid) {
        rwc->tablet_id = kTabletId;
        rwc->tablet = tablet;
        rwc->tablet_schema = schema;
        rwc->partial_update_info = std::move(pui);
        rwc->is_transient_rowset_writer = false;
        rwc->write_type = DataWriteType::TYPE_DIRECT;
        rwc->rowset_id = new_rsid;
    }

TransformExecContext make_exec_ctx(const TabletSchemaSPtr& schema,
                                       const TabletSharedPtr& tablet,
                                       const std::shared_ptr<MowContext>& mow,
                                       const std::shared_ptr<PartialUpdateInfo>& pui,
                                       RowsetWriterContext* rwc, const RowsetId& new_rsid) {
        TransformExecContext ctx;
        ctx.tablet_schema = schema;
        ctx.write_type = DataWriteType::TYPE_DIRECT;
        ctx.tablet = tablet;
        ctx.mow_context = mow;
        ctx.partial_update_info = pui;
        ctx.rowset_ctx = rwc;
        ctx.rowset_id = new_rsid;
        ctx.segment_id = 0;
        return ctx;
    }

std::shared_ptr<PartialUpdateInfo> make_flexible_pui(
            const TabletSchemaSPtr& schema,
            PartialUpdateNewRowPolicyPB policy = PartialUpdateNewRowPolicyPB::APPEND) {
        auto pui = std::make_shared<PartialUpdateInfo>();
        EXPECT_TRUE(pui->init(kTabletId, 1, *schema, UniqueKeyUpdateModePB::UPDATE_FLEXIBLE_COLUMNS,
                              policy, {}, false, 0, 0, "UTC", "")
                            .ok());
        return pui;
    }

TabletSchemaSPtr create_flexible_required_value_schema() {
        TabletSchemaPB pb;
        pb.set_keys_type(UNIQUE_KEYS);
        pb.set_num_short_key_columns(1);
        pb.set_num_rows_per_row_block(1024);
        pb.set_compress_kind(COMPRESS_LZ4);
        pb.set_next_column_unique_id(10);

        auto add_col = [&](int uid, const std::string& name, const std::string& type, bool is_key,
                           bool nullable, const std::string& def = "") {
            ColumnPB* c = pb.add_column();
            c->set_unique_id(uid);
            c->set_name(name);
            c->set_type(type);
            c->set_is_key(is_key);
            int len = 4;
            if (type == "TINYINT") {
                len = 1;
            } else if (type == "BITMAP") {
                len = 16;
            }
            c->set_length(len);
            c->set_index_length(len);
            c->set_is_nullable(nullable);
            c->set_aggregation("NONE");
            if (!def.empty()) {
                c->set_default_value(def);
            }
        };
        add_col(0, "k", "INT", true, false);
        add_col(1, "v", "INT", false, /*nullable=*/false); // NOT NULL, no default
        add_col(2, DELETE_SIGN, "TINYINT", false, false, std::to_string(0));
        add_col(3, SKIP_BITMAP_COL, "BITMAP", false, false);
        pb.set_delete_sign_idx(2);
        pb.set_skip_bitmap_col_idx(3);

        auto schema = std::make_shared<TabletSchema>();
        schema->init_from_pb(pb);
        return schema;
    }

Status run_flexible_fill(TransformExecContext& ctx, Block* block) {
        auto saved = config::enable_merge_on_write_correctness_check;
        config::enable_merge_on_write_correctness_check = false;
        FlexiblePartialUpdateFillStage stage;
        auto st = stage.apply(ctx, block);
        config::enable_merge_on_write_correctness_check = saved;
        return st;
    }

TabletSchemaSPtr create_flexible_seq2_schema() {
        TabletSchemaPB pb;
        pb.set_keys_type(UNIQUE_KEYS);
        pb.set_num_short_key_columns(1);
        pb.set_num_rows_per_row_block(1024);
        pb.set_compress_kind(COMPRESS_LZ4);
        pb.set_next_column_unique_id(10);

        auto add_col = [&](int uid, const std::string& name, const std::string& type, bool is_key,
                           bool nullable, const std::string& def = "") {
            ColumnPB* c = pb.add_column();
            c->set_unique_id(uid);
            c->set_name(name);
            c->set_type(type);
            c->set_is_key(is_key);
            int len = 4;
            if (type == "TINYINT") {
                len = 1;
            } else if (type == "BITMAP") {
                len = 16;
            }
            c->set_length(len);
            c->set_index_length(len);
            c->set_is_nullable(nullable);
            c->set_aggregation("NONE");
            if (!def.empty()) {
                c->set_default_value(def);
            }
        };
        add_col(0, "k", "INT", true, false);
        add_col(1, "v1", "INT", false, true, std::to_string(0));
        add_col(2, "v2", "INT", false, true, std::to_string(0));
        add_col(3, SEQUENCE_COL, "INT", false, false, std::to_string(0));
        add_col(4, DELETE_SIGN, "TINYINT", false, false, std::to_string(0));
        add_col(5, SKIP_BITMAP_COL, "BITMAP", false, false);
        pb.set_sequence_col_idx(3);
        pb.set_delete_sign_idx(4);
        pb.set_skip_bitmap_col_idx(5);

        auto schema = std::make_shared<TabletSchema>();
        schema->init_from_pb(pb);
        return schema;
    }

RowsetSharedPtr write_seq2_history(const TabletSchemaSPtr& schema, int64_t rsid_num, int32_t k,
                                       int32_t v1, int32_t v2, int32_t seq,
                                       TabletSharedPtr* out_tablet) {
        return write_rowset_block(
                schema, rsid_num, /*version=*/2,
                [&](Block& b) {
                    auto guard = b.mutate_columns_scoped();
                    auto& cols = guard.mutable_columns();
                    int8_t ds0 = 0;
                    cols[0]->insert_data(reinterpret_cast<const char*>(&k), sizeof(int32_t));
                    cols[1]->insert_data(reinterpret_cast<const char*>(&v1), sizeof(int32_t));
                    cols[2]->insert_data(reinterpret_cast<const char*>(&v2), sizeof(int32_t));
                    cols[3]->insert_data(reinterpret_cast<const char*>(&seq), sizeof(int32_t));
                    cols[4]->insert_data(reinterpret_cast<const char*>(&ds0), sizeof(int8_t));
                    cols[5]->insert_default(); // empty skip bitmap
                },
                out_tablet);
    }

void append_seq2_row(const TabletSchemaSPtr& schema, MutableColumns& cols, const Seq2Row& r) {
        cols[0]->insert_data(reinterpret_cast<const char*>(&r.k), sizeof(int32_t));
        cols[1]->insert_data(reinterpret_cast<const char*>(&r.v1), sizeof(int32_t));
        cols[2]->insert_data(reinterpret_cast<const char*>(&r.v2), sizeof(int32_t));
        cols[3]->insert_data(reinterpret_cast<const char*>(&r.seq), sizeof(int32_t));
        cols[4]->insert_data(reinterpret_cast<const char*>(&r.delete_sign), sizeof(int8_t));
        BitmapValue skip;
        if (!r.give_v1) {
            skip.add(static_cast<uint64_t>(schema->column(1).unique_id()));
        }
        if (!r.give_v2) {
            skip.add(static_cast<uint64_t>(schema->column(2).unique_id()));
        }
        if (!r.give_seq) {
            skip.add(static_cast<uint64_t>(schema->column(3).unique_id()));
        }
        if (!r.give_ds) {
            skip.add(static_cast<uint64_t>(schema->column(4).unique_id()));
        }
        assert_cast<ColumnBitmap*>(cols[5].get())->insert_value(std::move(skip));
    }

TabletSchemaSPtr create_flexible_row_store_schema() {
        TabletSchemaPB pb;
        pb.set_keys_type(UNIQUE_KEYS);
        pb.set_num_short_key_columns(1);
        pb.set_num_rows_per_row_block(1024);
        pb.set_compress_kind(COMPRESS_LZ4);
        pb.set_next_column_unique_id(10);
        pb.set_store_row_column(true);

        auto add = [&](int uid, const std::string& name, const std::string& type, bool is_key,
                       int len, bool nullable, const std::string& def = "") {
            ColumnPB* c = pb.add_column();
            c->set_unique_id(uid);
            c->set_name(name);
            c->set_type(type);
            c->set_is_key(is_key);
            c->set_length(len);
            c->set_index_length(type == "STRING" ? 4 : len);
            c->set_is_nullable(nullable);
            c->set_is_bf_column(false);
            c->set_aggregation("NONE");
            if (!def.empty()) {
                c->set_default_value(def);
            }
        };
        // The hidden row-store / skip-bitmap / delete-sign columns are non-nullable,
        // matching create_row_store_schema and create_flexible_mow_schema.
        add(0, "k", "INT", true, 4, false);
        add(1, "v", "INT", false, 4, true, std::to_string(0));
        add(2, DELETE_SIGN, "TINYINT", false, 1, false, std::to_string(0));
        add(3, SKIP_BITMAP_COL, "BITMAP", false, 16, false);
        add(4, BeConsts::ROW_STORE_COL, "STRING", false, 2147483643, false);
        pb.set_delete_sign_idx(2);
        pb.set_skip_bitmap_col_idx(3);

        auto schema = std::make_shared<TabletSchema>();
        schema->init_from_pb(pb);
        return schema;
    }

std::map<int32_t, Seq2Out> index_seq2(const Block& block) {
        std::map<int32_t, Seq2Out> by_key;
        for (size_t r = 0; r < block.rows(); ++r) {
            by_key[read_int(block, 0, r)] = Seq2Out {.v1 = read_int(block, 1, r),
                                                     .v2 = read_int(block, 2, r),
                                                     .seq = read_int(block, 3, r),
                                                     .ds = read_tinyint(block, 4, r)};
        }
        return by_key;
    }

TEST_F(FlexiblePartialUpdateTest, FlexibleFillFromHistoryAndDefault) {
    auto schema = create_flexible_mow_schema(); // k(0) v(1) delete_sign(2) skip_bitmap(3)
    TabletSharedPtr tablet;
    auto rowset = write_rowset(schema, 3101, 2, {{1, 11}, {2, 22}}, &tablet);
    auto mow = make_mow_context(100, {rowset});

    auto pui = make_flexible_pui(schema);
    RowsetId new_rsid;
    new_rsid.init(3102);
    RowsetWriterContext rwc;
    fill_rowset_ctx(&rwc, schema, tablet, pui, new_rsid);
    TransformExecContext ctx = make_exec_ctx(schema, tablet, mow, pui, &rwc, new_rsid);

    const int32_t v_uid = schema->column(1).unique_id();
    Block block = schema->create_block();
    {
        auto guard = block.mutate_columns_scoped();
        auto& cols = guard.mutable_columns();
        int32_t ks[] = {1, 99};
        int32_t v_dummy = 999;
        int8_t zero8 = 0;
        for (int32_t k : ks) {
            cols[0]->insert_data(reinterpret_cast<const char*>(&k), sizeof(int32_t));
            cols[1]->insert_data(reinterpret_cast<const char*>(&v_dummy), sizeof(int32_t));
            cols[2]->insert_data(reinterpret_cast<const char*>(&zero8), sizeof(int8_t));
            BitmapValue skip;
            skip.add(static_cast<uint64_t>(v_uid));
            assert_cast<ColumnBitmap*>(cols[3].get())->insert_value(std::move(skip));
        }
    }

    ASSERT_TRUE(run_flexible_fill(ctx, &block).ok());
    ASSERT_EQ(block.columns(), schema->num_columns());
    ASSERT_EQ(block.rows(), 2);
    std::map<int32_t, int32_t> kv;
    for (size_t r = 0; r < block.rows(); ++r) {
        kv[read_int(block, 0, r)] = read_int(block, 1, r);
    }
    EXPECT_EQ(kv[1], 11); // existing key: old v from history
    EXPECT_EQ(kv[99], 0); // brand-new key: column default
    EXPECT_EQ(ctx.partial_update_stats.num_rows_updated, 1);
    EXPECT_EQ(ctx.partial_update_stats.num_rows_new_added, 1);
    EXPECT_EQ(ctx.partial_update_stats.num_rows_deleted, 0);
}

TEST_F(FlexiblePartialUpdateTest, FlexibleProvidedCellKeptSkippedFilled) {
    auto schema = create_flexible_mow_schema();
    TabletSharedPtr tablet;
    auto rowset = write_rowset(schema, 3311, 2, {{1, 11}, {2, 22}}, &tablet);
    auto mow = make_mow_context(100, {rowset});

    auto pui = make_flexible_pui(schema);
    RowsetId new_rsid;
    new_rsid.init(3312);
    RowsetWriterContext rwc;
    fill_rowset_ctx(&rwc, schema, tablet, pui, new_rsid);
    TransformExecContext ctx = make_exec_ctx(schema, tablet, mow, pui, &rwc, new_rsid);

    const auto v_uid = static_cast<uint64_t>(schema->column(1).unique_id());
    const auto ds_uid = static_cast<uint64_t>(schema->column(2).unique_id());
    Block block = schema->create_block();
    {
        auto guard = block.mutate_columns_scoped();
        auto& cols = guard.mutable_columns();
        int32_t ks[] = {1, 2};
        int32_t vs[] = {88, 999};
        int8_t ds0 = 0;
        for (int i = 0; i < 2; ++i) {
            cols[0]->insert_data(reinterpret_cast<const char*>(&ks[i]), sizeof(int32_t));
            cols[1]->insert_data(reinterpret_cast<const char*>(&vs[i]), sizeof(int32_t));
            cols[2]->insert_data(reinterpret_cast<const char*>(&ds0), sizeof(int8_t));
            BitmapValue skip;
            skip.add(ds_uid);
            if (i == 1) {
                skip.add(v_uid);
            }
            assert_cast<ColumnBitmap*>(cols[3].get())->insert_value(std::move(skip));
        }
    }

    ASSERT_TRUE(run_flexible_fill(ctx, &block).ok());
    ASSERT_EQ(block.rows(), 2);
    std::map<int32_t, int32_t> kv;
    for (size_t r = 0; r < block.rows(); ++r) {
        kv[read_int(block, 0, r)] = read_int(block, 1, r);
    }
    EXPECT_EQ(kv[1], 88); // provided cell kept
    EXPECT_EQ(kv[2], 22); // skipped cell filled from history
}

TEST_F(FlexiblePartialUpdateTest, FlexibleDeleteSign) {
    auto schema = create_flexible_mow_schema();
    TabletSharedPtr tablet;
    auto rowset = write_rowset(schema, 3321, 2, {{1, 11}}, &tablet);
    auto mow = make_mow_context(100, {rowset});

    auto pui = make_flexible_pui(schema);
    RowsetId new_rsid;
    new_rsid.init(3322);
    RowsetWriterContext rwc;
    fill_rowset_ctx(&rwc, schema, tablet, pui, new_rsid);
    TransformExecContext ctx = make_exec_ctx(schema, tablet, mow, pui, &rwc, new_rsid);

    const auto v_uid = static_cast<uint64_t>(schema->column(1).unique_id());
    Block block = schema->create_block();
    {
        auto guard = block.mutate_columns_scoped();
        auto& cols = guard.mutable_columns();
        int32_t k = 1;
        int32_t v_dummy = 999;
        int8_t ds1 = 1;
        cols[0]->insert_data(reinterpret_cast<const char*>(&k), sizeof(int32_t));
        cols[1]->insert_data(reinterpret_cast<const char*>(&v_dummy), sizeof(int32_t));
        cols[2]->insert_data(reinterpret_cast<const char*>(&ds1), sizeof(int8_t));
        BitmapValue skip;
        skip.add(v_uid);
        assert_cast<ColumnBitmap*>(cols[3].get())->insert_value(std::move(skip));
    }

    ASSERT_TRUE(run_flexible_fill(ctx, &block).ok());
    ASSERT_EQ(block.rows(), 1);
    EXPECT_EQ(read_int(block, 1, 0), 0);     // v default (old row not read)
    EXPECT_EQ(read_tinyint(block, 2, 0), 1); // delete sign kept
    // exactly the one old row (history rowset seg0 row0) marked
    EXPECT_TRUE(mow->delete_bitmap->contains(
            {rowset->rowset_id(), 0, DeleteBitmap::TEMP_VERSION_COMMON}, 0));
    EXPECT_EQ(mow->delete_bitmap->cardinality(), 1U);
    // a delete on an existing key counts as an update, like the fixed path
    EXPECT_EQ(ctx.partial_update_stats.num_rows_updated, 1);
    EXPECT_EQ(ctx.partial_update_stats.num_rows_deleted, 0);
    EXPECT_EQ(ctx.partial_update_stats.num_rows_new_added, 0);
}

TEST_F(FlexiblePartialUpdateTest, FlexibleDeleteSignNewKey) {
    auto schema = create_flexible_mow_schema();
    TabletSharedPtr tablet;
    auto rowset = write_rowset(schema, 3671, 2, {{7, 70}}, &tablet); // key 99 is absent
    auto mow = make_mow_context(100, {rowset});
    auto pui = make_flexible_pui(schema, PartialUpdateNewRowPolicyPB::ERROR);
    RowsetId new_rsid;
    new_rsid.init(3672);
    RowsetWriterContext rwc;
    fill_rowset_ctx(&rwc, schema, tablet, pui, new_rsid);
    TransformExecContext ctx = make_exec_ctx(schema, tablet, mow, pui, &rwc, new_rsid);

    const auto v_uid = static_cast<uint64_t>(schema->column(1).unique_id());
    Block block = schema->create_block();
    {
        auto guard = block.mutate_columns_scoped();
        auto& cols = guard.mutable_columns();
        int32_t k = 99, v_dummy = 999;
        int8_t ds1 = 1;
        cols[0]->insert_data(reinterpret_cast<const char*>(&k), sizeof(int32_t));
        cols[1]->insert_data(reinterpret_cast<const char*>(&v_dummy), sizeof(int32_t));
        cols[2]->insert_data(reinterpret_cast<const char*>(&ds1), sizeof(int8_t));
        BitmapValue skip;
        skip.add(v_uid);
        assert_cast<ColumnBitmap*>(cols[3].get())->insert_value(std::move(skip));
    }

    ASSERT_TRUE(run_flexible_fill(ctx, &block).ok());
    ASSERT_EQ(block.rows(), 1);
    EXPECT_EQ(read_int(block, 0, 0), 99);
    EXPECT_EQ(read_int(block, 1, 0), 0);     // v default (no old row)
    EXPECT_EQ(read_tinyint(block, 2, 0), 1); // delete sign kept
    EXPECT_EQ(mow->delete_bitmap->cardinality(), 0U);
    EXPECT_EQ(ctx.partial_update_stats.num_rows_new_added, 1);
    EXPECT_EQ(ctx.partial_update_stats.num_rows_updated, 0);
    EXPECT_EQ(ctx.partial_update_stats.num_rows_deleted, 0);
}

