                                  type, std::move(const_col), type, type);
    for (auto _ : state) {
        runner.run_once(kBinaryArithmeticRows);
    }
    state.SetItemsProcessed(state.iterations() * kBinaryArithmeticRows);
}

void BM_add_d64_d64_const_const(benchmark::State& state) {
    auto type = std::make_shared<DataTypeDecimal64>(18, 4);
    auto const_a = ColumnConst::create(
            make_decimal_bench_column<TYPE_DECIMAL64>(1, 4, 54'321, 54'322, 0xc001), 1);
    auto const_b = ColumnConst::create(
            make_decimal_bench_column<TYPE_DECIMAL64>(1, 4, 12'345, 12'346, 0xc002), 1);
    BinaryArithmeticRunner runner("add", std::move(const_a), type, std::move(const_b), type, type);
    for (auto _ : state) {
        runner.run_once(1);
    }
    state.SetItemsProcessed(state.iterations());
}

void BM_subtract_d64_d64_const_const(benchmark::State& state) {
    auto type = std::make_shared<DataTypeDecimal64>(18, 4);
    auto const_a = ColumnConst::create(
            make_decimal_bench_column<TYPE_DECIMAL64>(1, 4, 54'321, 54'322, 0xd001), 1);
    auto const_b = ColumnConst::create(
            make_decimal_bench_column<TYPE_DECIMAL64>(1, 4, 12'345, 12'346, 0xd002), 1);
    BinaryArithmeticRunner runner("subtract", std::move(const_a), type, std::move(const_b), type,
                                  type);
    for (auto _ : state) {
        runner.run_once(1);
    }
    state.SetItemsProcessed(state.iterations());
}

static FunctionBasePtr lookup(const std::string& name, const DataTypePtr& left,
                                  const DataTypePtr& right, const DataTypePtr& return_type) {
        ColumnsWithTypeAndName arguments {{nullptr, left, ""}, {nullptr, right, ""}};
        return SimpleFunctionFactory::instance().get_function(name, arguments, return_type);
    }

static std::vector<DataTypePtr> v3_widths() {
        return {std::make_shared<DataTypeDecimal<TYPE_DECIMAL32>>(),
                std::make_shared<DataTypeDecimal<TYPE_DECIMAL64>>(),
                std::make_shared<DataTypeDecimal<TYPE_DECIMAL128I>>(),
                std::make_shared<DataTypeDecimal<TYPE_DECIMAL256>>()};
    }

TEST_F(BinaryArithmeticRegistrationTest, same_width_add_subtract_resolvable) {
    for (const auto& name : {std::string("add"), std::string("subtract")}) {
        for (const auto& type : v3_widths()) {
            auto function = lookup(name, type, type, type);
            ASSERT_NE(function, nullptr) << name << " " << type->get_name();
            EXPECT_EQ(function->get_name(), name) << type->get_name();
        }
    }
}

TEST_F(BinaryArithmeticRegistrationTest, same_width_mod_resolvable) {
    for (const auto& type : v3_widths()) {
        // FunctionMod always infers a nullable return type (mod by zero -> NULL).
        auto function = lookup("mod", type, type, make_nullable(type));
        ASSERT_NE(function, nullptr) << type->get_name();
        EXPECT_EQ(function->get_name(), "mod") << type->get_name();
    }
}

TEST_F(BinaryArithmeticRegistrationTest, mixed_width_add_subtract_mod_unresolvable) {
    auto widths = v3_widths();
    for (const auto& left : widths) {
        for (const auto& right : widths) {
            if (left->get_primitive_type() == right->get_primitive_type()) {
                continue;
            }
            for (const auto& name : {std::string("add"), std::string("subtract")}) {
                EXPECT_EQ(lookup(name, left, right, left), nullptr)
                        << name << " " << left->get_name() << " x " << right->get_name();
            }
            EXPECT_EQ(lookup("mod", left, right, make_nullable(left)), nullptr)
                    << "mod " << left->get_name() << " x " << right->get_name();
        }
    }
}

TEST_F(BinaryArithmeticRegistrationTest, multiply_full_cross_product_retained) {
    auto widths = v3_widths();
    for (const auto& left : widths) {
        for (const auto& right : widths) {
            auto function = lookup("multiply", left, right, left);
            ASSERT_NE(function, nullptr)
                    << "multiply " << left->get_name() << " x " << right->get_name();
            EXPECT_EQ(function->get_name(), "multiply");
        }
    }
}

TEST_F(BinaryArithmeticRegistrationTest, decimalv2_still_resolvable) {
    auto type = std::make_shared<DataTypeDecimalV2>();
    for (const auto& name :
         {std::string("add"), std::string("subtract"), std::string("multiply")}) {
        auto function = lookup(name, type, type, type);
        ASSERT_NE(function, nullptr) << name;
        EXPECT_EQ(function->get_name(), name);
    }
    auto mod_function = lookup("mod", type, type, make_nullable(type));
    ASSERT_NE(mod_function, nullptr);
    EXPECT_EQ(mod_function->get_name(), "mod");
}

void SITL_State::handle_periph_ack(const struct sitl_mcast_ack &ack, ssize_t len, const struct sockaddr_in &src)
{
    if (len != sizeof(ack)) {
        // unknown packet format.  The most likely cause is a
        // peripheral built from a different source tree, sending the
        // old servo-only reply; its servo output will be ignored and
        // it can take no part in lockstep, so say so rather than
        // discarding its packets in silence
        if (!_warned_ack_size) {
            _warned_ack_size = true;
            ::fprintf(stderr, "SITL: ignoring %d-byte peripheral reply from %s:%u, expected %u bytes; build the peripheral from this source tree\n",
                      int(len), inet_ntoa(src.sin_addr), (unsigned)ntohs(src.sin_port),
                      (unsigned)sizeof(ack));
        }
        return;
    }
    for (uint8_t i=0; i<SITL_NUM_CHANNELS; i++) {
        // nan means that node is not outputting this channel
        if (!isnan(ack.servos[i])) {
            mc_servo[i] = uint16_t(ack.servos[i]);
        }
    }
    if (!_periph_lockstep) {
        return;
    }
    // register the peripheral, or update its ack state
    struct mcast_periph *periph = nullptr;
    for (uint8_t i=0; i<num_mcast_periphs; i++) {
        if (mcast_periphs[i].addr.sin_addr.s_addr == src.sin_addr.s_addr &&
            mcast_periphs[i].addr.sin_port == src.sin_port) {
            periph = &mcast_periphs[i];
            break;
        }
    }
    if (periph == nullptr) {
        // do not let a recently-evicted peer's stale queued acks
        // re-register it; a live peer re-registers with fresh acks
        // once the cooldown expires
        const uint64_t now_ms = wall_millis();
        for (uint8_t i=0; i<num_evicted_periphs; ) {
            if (now_ms - evicted_periphs[i].evicted_ms > PERIPH_REJOIN_COOLDOWN_MS) {
                evicted_periphs[i] = evicted_periphs[--num_evicted_periphs];
                continue;
            }
            if (evicted_periphs[i].addr.sin_addr.s_addr == src.sin_addr.s_addr &&
                evicted_periphs[i].addr.sin_port == src.sin_port) {
                return;
            }
            i++;
        }
        if (num_mcast_periphs >= MAX_MCAST_PERIPHS) {
            return;
        }
        periph = &mcast_periphs[num_mcast_periphs++];
        periph->addr = src;
        ::printf("SITL: peripheral %s:%u joined lockstep\n",
                 inet_ntoa(src.sin_addr), (unsigned)ntohs(src.sin_port));
    }
    periph->last_ack_us = ack.timestamp_us;
    periph->last_heard_ms = wall_millis();
}

uint64_t SITL_State::wall_millis(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return uint64_t(ts.tv_sec) * 1000ULL + ts.tv_nsec / 1000000ULL;
}

float ModeQRTL::calc_alt_delta_m() const
{
    float alt_delta_m = 0;
#if AP_TERRAIN_AVAILABLE
    float current_terrain_height_m;
    if (plane.next_WP_loc.terrain_alt &&
        plane.terrain.height_above_terrain(current_terrain_height_m, true)) {
        // QRTL is terrain following: compute the delta in the same
        // terrain-relative frame the ramp is applied in via
        // change_target_altitude(), so the two stay consistent over
        // sloping ground. next_WP_loc.alt is already the destination's
        // own terrain-relative target height, in cm
        alt_delta_m = current_terrain_height_m - (plane.next_WP_loc.alt * 0.01);
    } else
#endif
    {
        int32_t current_alt_cm;
        int32_t dest_alt_cm;
        if (plane.current_loc.get_alt_cm(Location::AltFrame::ABSOLUTE, current_alt_cm) &&
            plane.next_WP_loc.get_alt_cm(Location::AltFrame::ABSOLUTE, dest_alt_cm)) {
            alt_delta_m = (current_alt_cm - dest_alt_cm) * 0.01;
        }
        // else no usable altitudes, fall back to going straight to RTL_ALTITUDE
    }
    return alt_delta_m;
}

static uint32_t next_test_day()
{
    static uint32_t days = 20000;  // ~2024; the RTC rejects times before 2022
    days++;
    return days;
}

static uint64_t day_time_to_utc_usec(uint32_t days, uint8_t hour, uint8_t min, uint8_t sec, uint16_t ms)
{
    const uint64_t tod_ms = ((hour*60UL + min)*60UL + sec)*1000ULL + ms;
    return (days*86400000ULL + tod_ms)*1000ULL;
}

static uint64_t set_clock(uint8_t hour, uint8_t min, uint8_t sec, uint16_t ms)
{
    const uint64_t utc_usec = day_time_to_utc_usec(next_test_day(), hour, min, sec, ms);
    AP::rtc().set_utc_usec(utc_usec, AP_RTC::SOURCE_GPS);
    return utc_usec;
}

TEST(AP_RTC, unset_clock)
{
    uint64_t utc_usec;
    EXPECT_FALSE(AP::rtc().get_utc_usec(utc_usec));

    uint8_t hour, min, sec;
    uint16_t ms;
    EXPECT_FALSE(AP::rtc().get_system_clock_utc(hour, min, sec, ms));
    EXPECT_FALSE(AP::rtc().get_local_time(hour, min, sec, ms));

    uint16_t year;
    uint8_t month, day;
    EXPECT_FALSE(AP::rtc().get_date_and_time_utc(year, month, day, hour, min, sec, ms));

    EXPECT_EQ(0U, AP::rtc().get_time_utc(13, 0, 0, 0));

    EXPECT_EQ(AP_RTC::SOURCE_NONE, AP::rtc().get_source_type());

    // a source not in the allowed-types mask (GPS-only by default)
    // must be rejected:
    const uint64_t t_2024 = day_time_to_utc_usec(19800, 12, 0, 0, 0);
    AP::rtc().set_utc_usec(t_2024, AP_RTC::SOURCE_MAVLINK_SYSTEM_TIME);
    EXPECT_FALSE(AP::rtc().get_utc_usec(utc_usec));
    EXPECT_EQ(AP_RTC::SOURCE_NONE, AP::rtc().get_source_type());

    // times before the oldest acceptable date (2022-01-01) must be
    // rejected:
    const uint64_t t_2020 = day_time_to_utc_usec(18300, 12, 0, 0, 0);
    AP::rtc().set_utc_usec(t_2020, AP_RTC::SOURCE_GPS);
    EXPECT_FALSE(AP::rtc().get_utc_usec(utc_usec));
    EXPECT_EQ(AP_RTC::SOURCE_NONE, AP::rtc().get_source_type());
}

TEST(AP_RTC, date_field_conversions)
{
    static const struct {
        uint32_t utc_sec;
        uint16_t year;
        uint8_t month;  // 0-11
        uint8_t day;    // 1-31
        uint8_t hour;
        uint8_t min;
        uint8_t sec;
        uint8_t wday;   // 0-6, Sunday=0
    } cases[] {
        { 0U,          1970, 0,  1,  0,  0,  0,  4 },  // epoch (a Thursday)
        { 951825600U,  2000, 1, 29, 12,  0,  0,  2 },  // div-400 leap year
        { 1709251199U, 2024, 1, 29, 23, 59, 59,  4 },  // leap day, last second
        { 1783514096U, 2026, 6,  8, 12, 34, 56,  3 },  // an ordinary Wednesday
        { 2147483648U, 2038, 0, 19,  3, 14,  8,  2 },  // beyond the int32 epoch limit
        { 4102444800U, 2100, 0,  1,  0,  0,  0,  5 },  // div-100 non-leap century
        { 4294967295U, 2106, 1,  7,  6, 28, 15,  0 },  // uint32 epoch limit
    };

    for (const auto &tc : cases) {
        SCOPED_TRACE(tc.utc_sec);

        uint16_t year;
        uint8_t month, day, hour, min, sec, wday;
        ASSERT_TRUE(AP::rtc().clock_s_to_date_fields(tc.utc_sec, year, month, day, hour, min, sec, wday));
        EXPECT_EQ(tc.year, year);
        EXPECT_EQ(int(tc.month), int(month));
        EXPECT_EQ(int(tc.day), int(day));
        EXPECT_EQ(int(tc.hour), int(hour));
        EXPECT_EQ(int(tc.min), int(min));
        EXPECT_EQ(int(tc.sec), int(sec));
        EXPECT_EQ(int(tc.wday), int(wday));

        EXPECT_EQ(tc.utc_sec, AP::rtc().date_fields_to_clock_s(tc.year, tc.month, tc.day, tc.hour, tc.min, tc.sec));
    }

    // an invalid month must not convert:
    EXPECT_EQ(0U, AP::rtc().date_fields_to_clock_s(2024, 13, 1, 0, 0, 0));
}

TEST(AP_RTC, get_time_utc)
{
    static const struct {
        const char *desc;
        // time-of-day to install as "now":
        uint8_t curr_hour;
        uint8_t curr_min;
        uint8_t curr_sec;
        uint16_t curr_ms;
        // arguments to get_time_utc(), -1 meaning ignore:
        int32_t hour;
        int32_t min;
        int32_t sec;
        int32_t ms;
        uint32_t expected_ms;
    } cases[] {
        // fully-specified targets:
        { "fully-specified future time",
          12, 0, 0, 250,    13, 15, 10, 0,    4509750 },
        { "fully-specified time just past rolls over a full day",
          13, 0, 10, 250,   13, 0, 5, 0,      86394750 },
        { "fully-specified time crossing midnight",
          23, 30, 0, 250,   0, 10, 0, 0,      2399750 },

        // leading ignored fields:
        { "seconds-only target later this minute",
          12, 0, 10, 250,   -1, -1, 40, 0,    29750 },
        { "seconds-only target just past rolls over to next minute",
          12, 0, 40, 250,   -1, -1, 10, 0,    29750 },
        { "minutes-only target just past rolls over to next hour",
          12, 30, 0, 250,   -1, 10, 0, 0,     2399750 },
        { "ms-only target later this second",
          12, 0, 10, 250,   -1, -1, -1, 750,  500 },
        { "ms-only target just past rolls over to next second",
          12, 0, 10, 250,   -1, -1, -1, 100,  850 },
        { "ignored hour with min:sec just past rolls over one hour",
          12, 30, 45, 250,  -1, 30, 40, 0,    3594750 },
        { "ignored ms with target next second",
          12, 0, 10, 250,   -1, -1, 11, -1,   750 },

#if 0   // these cases document the intended handling of ignored
        // values below the largest specified element and fail before
        // the get_time_utc() ignored-values fix
        // (https://github.com/ArduPilot/ardupilot/pull/33667); remove
        // this #if 0 when that PR lands
        { "ignored minutes just before target hour must not delay a day",
          12, 59, 30, 250,  13, -1, 0, 0,     29750 },
        { "ignored minutes within target hour waits for next minute",
          13, 30, 15, 250,  13, -1, 0, 0,     44750 },
        { "ignored minutes with target hour in the past waits until tomorrow",
          14, 30, 0, 250,   13, -1, 0, 0,     80999750 },
        { "ignored minutes in target hour's final minute must wait until tomorrow",
          13, 59, 30, 250,  13, -1, 0, 0,     82829750 },
        { "carry from ignored seconds must not escape the specified minute",
          23, 30, 59, 500,  -1, 30, -1, 0,    3540500 },
        { "carry through ignored minutes must not escape the specified hour",
          13, 59, 59, 250,  13, -1, -1, 0,    82800750 },
        { "ignored minutes and seconds with future target hour",
          12, 30, 45, 250,  14, -1, -1, -1,   5354750 },
        { "ignored seconds within target minute leaves only a ms delta",
          12, 30, 15, 250,  -1, 30, -1, 900,  650 },
        { "ignored seconds with target minute in the past",
          12, 30, 45, 250,  -1, 10, -1, 0,    2354750 },
        { "ignored ms with current second as target returns zero",
          12, 0, 10, 250,   -1, -1, 10, -1,   0 },
        { "ignored ms and seconds with future target minute",
          12, 30, 45, 250,  -1, 45, -1, -1,   854750 },
        { "ignored seconds with target hour in the past rolls over a day",
          14, 30, 0, 250,   13, 0, -1, 0,     80999750 },
#endif

        // everything ignored:
        { "all fields ignored returns zero",
          12, 0, 10, 250,   -1, -1, -1, -1,   0 },
    };

    // the first accepted set_utc_usec() triggers one-time expensive
    // work (lazily initialising storage to save the MAVLink signing
    // timestamp, updating the hardware RTC); do a throwaway install
    // so that cost is not measured against clock_slack_ms below
    set_clock(0, 0, 0, 0);

    for (const auto &tc : cases) {
        SCOPED_TRACE(tc.desc);

        set_clock(tc.curr_hour, tc.curr_min, tc.curr_sec, tc.curr_ms);

        // ensure the time was actually installed:
        uint8_t hour, min, sec;
        uint16_t ms;
        ASSERT_TRUE(AP::rtc().get_system_clock_utc(hour, min, sec, ms));
        ASSERT_EQ(int(tc.curr_hour), int(hour));
        ASSERT_EQ(int(tc.curr_min), int(min));
        ASSERT_EQ(int(tc.curr_sec), int(sec));

        const uint32_t delay_ms = AP::rtc().get_time_utc(tc.hour, tc.min, tc.sec, tc.ms);
        EXPECT_NEAR(tc.expected_ms, delay_ms, clock_slack_ms);
    }
}

TEST(AP_RTC, get_utc_usec)
{
    const uint64_t installed = set_clock(12, 34, 56, 250);

    uint64_t first, second;
    ASSERT_TRUE(AP::rtc().get_utc_usec(first));
    ASSERT_TRUE(AP::rtc().get_utc_usec(second));

    // the clock must be close to the installed time, and running
    // forwards:
    EXPECT_GE(first, installed);
    EXPECT_NEAR(0, double(first - installed)/1000, clock_slack_ms);
    EXPECT_GE(second, first);

    uint8_t hour, min, sec;
    uint16_t ms;
    ASSERT_TRUE(AP::rtc().get_system_clock_utc(hour, min, sec, ms));
    EXPECT_EQ(12, hour);
    EXPECT_EQ(34, min);
    EXPECT_EQ(56, sec);
    EXPECT_NEAR(250, ms, clock_slack_ms);
}

TEST(AP_RTC, get_local_time)
{
    static const struct {
        const char *desc;
        uint8_t curr_hour;
        uint8_t curr_min;
        int16_t tz_min;
        uint8_t local_hour;
        uint8_t local_min;
    } cases[] {
        { "UTC",                     12, 0,     0,   12, 0 },
        { "positive whole hours",    12, 0,   600,   22, 0 },
        { "negative part hour",      12, 0,   -90,   10, 30 },
        { "offset crossing midnight", 23, 30,  120,   1, 30 },
    };

    for (const auto &tc : cases) {
        SCOPED_TRACE(tc.desc);

        set_clock(tc.curr_hour, tc.curr_min, 0, 250);
        rtc.tz_min.set(tc.tz_min);

        uint8_t hour, min, sec;
        uint16_t ms;
        ASSERT_TRUE(AP::rtc().get_local_time(hour, min, sec, ms));
        EXPECT_EQ(int(tc.local_hour), int(hour));
        EXPECT_EQ(int(tc.local_min), int(min));
        EXPECT_EQ(0, sec);
    }

    rtc.tz_min.set(0);
}

TEST(AP_RTC, set_utc_usec_priority)
{
    // allow all source types so the priority rules are tested rather
    // than the allowed-types mask:
    rtc.allowed_types.set((1U << AP_RTC::SOURCE_GPS) |
                          (1U << AP_RTC::SOURCE_MAVLINK_SYSTEM_TIME) |
                          (1U << AP_RTC::SOURCE_HW));

    const uint64_t t1 = set_clock(12, 0, 0, 0);
    ASSERT_EQ(AP_RTC::SOURCE_GPS, AP::rtc().get_source_type());

    uint64_t now;

    // while disarmed, a worse source than the current one must be
    // rejected:
    const uint64_t t2 = day_time_to_utc_usec(next_test_day(), 12, 0, 0, 0);
    AP::rtc().set_utc_usec(t2, AP_RTC::SOURCE_MAVLINK_SYSTEM_TIME);
    EXPECT_EQ(AP_RTC::SOURCE_GPS, AP::rtc().get_source_type());
    ASSERT_TRUE(AP::rtc().get_utc_usec(now));
    EXPECT_LT(now, t2);

    // moving time backwards must be rejected, even from the same
    // source:
    AP::rtc().set_utc_usec(t1 - 3600*1000000ULL, AP_RTC::SOURCE_GPS);
    ASSERT_TRUE(AP::rtc().get_utc_usec(now));
    EXPECT_GE(now, t1);

    // while armed, even same-source updates must be rejected...
    const uint64_t t3 = day_time_to_utc_usec(next_test_day(), 12, 0, 0, 0);
    hal.util->set_soft_armed(true);
    AP::rtc().set_utc_usec(t3, AP_RTC::SOURCE_GPS);
    ASSERT_TRUE(AP::rtc().get_utc_usec(now));
    EXPECT_LT(now, t3);

    // ... and accepted once disarmed again:
    hal.util->set_soft_armed(false);
    AP::rtc().set_utc_usec(t3, AP_RTC::SOURCE_GPS);
    ASSERT_TRUE(AP::rtc().get_utc_usec(now));
    EXPECT_GE(now, t3);
    EXPECT_NEAR(0, double(now - t3)/1000, clock_slack_ms);

    rtc.allowed_types.set(1U << AP_RTC::SOURCE_GPS);
}

TEST(AP_RTC, get_date_and_time_utc)
{
    const uint64_t installed = set_clock(12, 34, 56, 250);

    // derive the expected calendar date using clock_s_to_date_fields,
    // which date_field_conversions verified against known dates:
    uint16_t exp_year;
    uint8_t exp_month, exp_day, exp_hour, exp_min, exp_sec, exp_wday;
    ASSERT_TRUE(AP::rtc().clock_s_to_date_fields(installed / 1000000ULL, exp_year, exp_month, exp_day, exp_hour, exp_min, exp_sec, exp_wday));

    uint16_t year;
    uint8_t month, day, hour, min, sec;
    uint16_t ms;
    ASSERT_TRUE(AP::rtc().get_date_and_time_utc(year, month, day, hour, min, sec, ms));
    EXPECT_EQ(exp_year, year);
    EXPECT_EQ(int(exp_month), int(month));
    EXPECT_EQ(int(exp_day), int(day));
    EXPECT_EQ(12, hour);
    EXPECT_EQ(34, min);
    EXPECT_EQ(56, sec);
    EXPECT_NEAR(250, ms, clock_slack_ms);
}

SEASTAR_THREAD_TEST_CASE(test_compactor_partition_stats_of_partition_spanning_many_pages) {
    simple_schema ss;
    auto pk = ss.make_pkey();
    auto s = ss.schema();

    tests::reader_concurrency_semaphore_wrapper semaphore;

    auto permit = semaphore.make_permit();

    const auto marker_ts = ss.new_timestamp();
    const auto row_ts = ss.new_timestamp();

    const uint32_t rows = 10;

    auto make_frags = [&] {
        std::deque<mutation_fragment_v2> frags;

        frags.emplace_back(*s, permit, partition_start(pk, {}));

        const auto& v_def = *s->get_column_definition(to_bytes("v"));

        for (uint32_t ck = 0; ck < rows; ++ck) {
            auto row = clustering_row(ss.make_ckey(ck));
            row.cells().apply(v_def, atomic_cell::make_live(*v_def.type, row_ts, serialized("v")));
            row.marker() = row_marker(marker_ts);
            frags.emplace_back(mutation_fragment_v2(*s, permit, std::move(row)));
        }

        frags.emplace_back(*s, permit, partition_end{});

        return frags;
    };

    const auto query_time = gc_clock::now();
    const auto max_rows = std::numeric_limits<uint64_t>::max();
    const auto max_partitions = std::numeric_limits<uint32_t>::max();
    const uint64_t rows_per_page = 2;

    auto compaction_state = make_lw_shared<compact_mutation_state<compact_for_sstables::no>>(*s, query_time, s->full_slice(),
            max_rows, max_partitions, tombstone_gc_state::no_gc());
    auto reader = make_mutation_reader_from_fragments(s, permit, make_frags());
    auto close_reader = deferred_close(reader);

    unsigned pages = 0;
    unsigned pages_with_rows = 0;
    while (!reader.is_buffer_empty() || !reader.is_end_of_stream()) {
        noop_compacted_fragments_consumer c;
        compaction_state->start_new_page(rows_per_page, max_partitions, query_time, reader.peek().get()->position().region(), c);
        reader.consume(compact_for_query<noop_compacted_fragments_consumer>(compaction_state, c)).get();

        const auto& stats = compaction_state->stats();
        testlog.info("page {}: {} partition(s) ({} live, {} dead), {} clustering row(s) ({} live, {} dead)", pages,
                stats.total_partitions, stats.live_partitions, stats.dead_partitions(),
                stats.clustering_rows.total(), stats.clustering_rows.live, stats.clustering_rows.dead);

        // The partition is live on every page it has rows on, be it the page
        // it was started on or a page continuing it.
        if (stats.clustering_rows.total()) {
            BOOST_REQUIRE_EQUAL(stats.live_partitions, 1);
            BOOST_REQUIRE_EQUAL(stats.total_partitions, 1);
            ++pages_with_rows;
        }
        // A partition can never be live without being counted in the total.
        BOOST_REQUIRE_LE(stats.live_partitions, stats.total_partitions);
        BOOST_REQUIRE_EQUAL(stats.dead_partitions(), 0);

        ++pages;
    }

    BOOST_REQUIRE_EQUAL(pages_with_rows, rows / rows_per_page);
}

static sstring join_path(std::string_view prefix, std::string_view relative_path) {
    if (prefix.empty()) {
        return sstring(relative_path);
    }
    return fmt::format("{}/{}", prefix, relative_path);
}

std::optional<std::pair<dht::token_range, dht::token_range>>
split_token_range(const dht::token_range& range) {
    if (!range.start() || !range.end()) {
        return std::nullopt;
    }
    auto split_point = dht::token::midpoint(range.start()->value(), range.end()->value());
    // A range with fewer than two tokens in it has nothing to split between. The
    // midpoint of two adjacent tokens is the lower of them, so the left side would come
    // out empty and the right side would be the whole range. That cannot happen for a
    // tablet range today, but it would for a tablet holding a single token, which is
    // how a hot partition would be isolated.
    if (split_point.raw() <= range.start()->value().raw()) {
        return std::nullopt;
    }
    return std::pair(dht::token_range::make(*range.start_copy(), {split_point, true}),
                     dht::token_range::make({split_point, false}, *range.end_copy()));
}

SEASTAR_THREAD_TEST_CASE(test_split_token_range_agrees_with_tablet_map) {
    for (auto tablet_count : {1ul, 2ul, 8ul, 128ul}) {
        locator::tablet_map tmap(tablet_count);
        locator::tablet_map tmap_after_splitting(tablet_count * 2);

        for (size_t id = 0; id < tablet_count; id++) {
            auto tid = tablet_id(id);
            auto range = tmap.get_token_range(tid);
            auto sub_ranges = replica::split_token_range(range);
            BOOST_REQUIRE(sub_ranges.has_value());
            const auto& [left, right] = *sub_ranges;
            testlog.debug("tablet_count {}, id {}, range {}, left {}, right {}", tablet_count, id, range, left, right);

            // Split at the same token the map splits at.
            BOOST_REQUIRE(left.end()->value() == tmap.get_split_token(tid));
            // The two halves are the ranges of the tablets the split will produce,
            // which handle_tablet_split_completion() installs once it completes.
            BOOST_REQUIRE(left == tmap_after_splitting.get_token_range(tablet_id(id * 2)));
            BOOST_REQUIRE(right == tmap_after_splitting.get_token_range(tablet_id(id * 2 + 1)));
            // Between them they cover the range being split, and no more.
            BOOST_REQUIRE(*left.start_copy() == *range.start_copy());
            BOOST_REQUIRE(*right.end_copy() == *range.end_copy());

            // A token the map routes to one side lies in that side's range, so a
            // split-ready group's range covers everything written to it.
            auto check = [&] (dht::token t, tablet_range_side expected_side, const dht::token_range& expected_range) {
                BOOST_REQUIRE_EQUAL(tmap.get_tablet_range_side(t), expected_side);
                BOOST_REQUIRE(expected_range.contains(t, dht::token_comparator()));
            };
            auto lower_token = range.start()->value() == dht::minimum_token() ? dht::first_token() : range.start()->value();
            check(next_token(lower_token), tablet_range_side::left, left);
            check(left.end()->value(), tablet_range_side::left, left);
            check(next_token(left.end()->value()), tablet_range_side::right, right);
            check(range.end()->value(), tablet_range_side::right, right);

            thread::maybe_yield();
        }
    }

    // A range which cannot be split reports so rather than returning a pair with an
    // empty side. Splitting a range holding a single token does not arise for a tablet
    // today, but it will for a tablet isolating a hot partition.
    auto t = dht::token::bias(uint64_t(1) << 63);   // an ordinary key token, mid-ring
    BOOST_REQUIRE(!replica::split_token_range(dht::token_range::make({t, false}, {next_token(t), true})));
    BOOST_REQUIRE(!replica::split_token_range(dht::token_range::make_singular(t)));
    BOOST_REQUIRE(!replica::split_token_range(dht::token_range::make_open_ended_both_sides()));
    BOOST_REQUIRE(!replica::split_token_range(dht::token_range::make_starting_with({t, false})));
    BOOST_REQUIRE(!replica::split_token_range(dht::token_range::make_ending_with({t, true})));
}

SEASTAR_THREAD_TEST_CASE(test_split_ready_groups_own_their_post_split_range) {
    auto cfg = tablet_cql_test_config();
    cfg.initial_tablets = std::bit_floor(this_smp_shard_count());
    do_with_cql_env_thread([] (cql_test_env& e) {
        e.execute_cql(
                "CREATE TABLE cf (pk int, ck int, v int, PRIMARY KEY (pk, ck))").get();

        for (unsigned i = 0; i < this_smp_shard_count() * 20; i++) {
            e.execute_cql(format("INSERT INTO cf (pk, ck, v) VALUES ({}, 0, 0)", i)).get();
        }

        e.db().invoke_on_all([] (replica::database& db) {
            auto& table = db.find_column_family("ks", "cf");
            return table.flush();
        }).get();

        e.db().invoke_on_all([] (replica::database& db) {
            auto& table = db.find_column_family("ks", "cf");
            return table.split_all_storage_groups(tasks::task_info{});
        }).get();

        e.db().invoke_on_all([] (replica::database& db) {
            auto& t = db.find_column_family("ks", "cf");
            auto& sgm = column_family_test::get_storage_group_manager(t);
            sgm->for_each_storage_group([&] (size_t id, replica::storage_group& sg) {
                const auto& groups = sg.split_ready_compaction_groups();
                THREADSAFE_BOOST_REQUIRE_EQUAL(groups.size(), 2);

                // A token on each side of the split point, taken from the bounds of
                // the range being split: its start is exclusive and belongs to the
                // preceding tablet, its end is inclusive and is the last token of
                // this one.
                auto range = sg.token_range();
                auto lower_token = range.start()->value() == dht::minimum_token()
                        ? dht::first_token() : next_token(range.start()->value());
                auto upper_token = range.end()->value();

                for (auto [side, token] : {std::pair(tablet_range_side::left, lower_token),
                                           std::pair(tablet_range_side::right, upper_token)}) {
                    const auto& cg = groups[size_t(side)];
                    auto expected = t.get_token_range_after_split(token);
                    testlog.debug("group {} side {} range {} expected {}", id, int(side), cg->token_range(), expected);
                    THREADSAFE_BOOST_REQUIRE(cg->token_range() == expected);
                    // The point of the narrower range: it is the range the group's
                    // own sstables can span, not twice it.
                    THREADSAFE_BOOST_REQUIRE(cg->token_range() != range);
                    THREADSAFE_BOOST_REQUIRE(cg->token_range().contains(token, dht::token_comparator()));
                }
            });
        }).get();
    }, std::move(cfg)).get();
}

void compaction_backlog_tracker::retire() {
    if (_manager) {
        _manager->remove_backlog_tracker(this);
        _manager = nullptr;
    }
    disable();
}

SEASTAR_THREAD_TEST_CASE(test_compaction_backlog_of_compaction_groups_created_by_tablet_split) {
    auto cfg = tablet_cql_test_config();
    cfg.initial_tablets = std::bit_floor(this_smp_shard_count());
    cfg.db_config->tablets_per_shard_goal.set(10000); // Inhibit scaling-down of the count.
    do_with_cql_env_thread([] (cql_test_env& e) {
        e.execute_cql("CREATE TABLE cf (pk int, ck int, v text, PRIMARY KEY (pk, ck))").get();
        auto table = e.local_db().find_column_family("ks", "cf").schema()->id();

        // Auto compaction would consume the very backlog this test observes.
        e.db().invoke_on_all([] (replica::database& db) {
            return db.find_column_family("ks", "cf").disable_auto_compaction();
        }).get();

        auto total_backlog = [&e] {
            return e.db().map_reduce0([] (replica::database& db) {
                return make_ready_future<double>(db.get_compaction_manager().backlog());
            }, double(0), std::plus<double>()).get();
        };
        auto total_sstables = [&e] {
            return e.db().map_reduce0([] (replica::database& db) {
                return make_ready_future<int64_t>(db.find_column_family("ks", "cf").sstables_count());
            }, int64_t(0), std::plus<int64_t>()).get();
        };

        // Each round produces one sstable per compaction group holding data. More than
        // min_compaction_threshold sstables of similar size, so the size-tiered backlog
        // tracker finds an interesting bucket.
        auto write_sstables = [&e] (int rounds, int key_base) {
            for (int round = 0; round < rounds; round++) {
                for (int i = 0; i < 256; i++) {
                    e.execute_cql(format("INSERT INTO cf (pk, ck, v) VALUES ({}, {}, 'payload to give the sstable some size')",
                                         key_base + round * 256 + i, round)).get();
                }
                e.db().invoke_on_all([] (replica::database& db) {
                    return db.find_column_family("ks", "cf").flush();
                }).get();
            }
        };

        write_sstables(8, 0);

        testlog.info("before split: sstables={} backlog={}", total_sstables(), total_backlog());
        // Sanity check: the compaction group that existed when the table was started is
        // registered, so the backlog does account for accumulated work.
        BOOST_REQUIRE_GT(total_backlog(), 0.0);

        testlog.info("Requesting a tablet split...");
        auto new_tablet_count = 2 * std::bit_floor(this_smp_shard_count());
        e.execute_cql(format("ALTER TABLE ks.cf WITH tablets = {{'min_tablet_count': '{}'}}", new_tablet_count)).get();

        auto& stm = e.shared_token_metadata().local();
        shared_load_stats load_stats;
        stm.get()->get_topology().for_each_node([&] (const locator::node& node) {
            load_stats.set_capacity(node.host_id(), service::default_target_tablet_size * node.get_shard_count());
        });
        load_stats.set_tablet_sizes(stm.get(), table, service::default_target_tablet_size);

        // Emit the split resize decision. The replica's own split monitor notices it
        // and splits the storage groups in the background.
        apply_resize_decisions(e, load_stats);

        // Wait for the replica to finish splitting, like the topology coordinator does.
        auto deadline = lowres_clock::now() + std::chrono::minutes(1);
        while (!e.db().map_reduce0([] (replica::database& db) {
                    return make_ready_future<bool>(db.find_column_family("ks", "cf").all_storage_groups_split());
                }, true, std::logical_and<bool>()).get()) {
            BOOST_REQUIRE(lowres_clock::now() < deadline);
            seastar::sleep(std::chrono::milliseconds(100)).get();
        }

        // Finalize the resize: the tablet count doubles and the groups created for the
        // split become the storage groups of the new tablets.
        load_stats.set_split_ready_seq_number(table, stm.get()->tablets().get_tablet_map(table).resize_decision().sequence_number);
        rebalance_tablets(e, &load_stats);
        BOOST_REQUIRE_EQUAL(stm.get()->tablets().get_tablet_map(table).tablet_count(), new_tablet_count);

        // Fill the compaction groups that the split created.
        write_sstables(8, 1000000);

        auto sstables_after = total_sstables();
        auto backlog_after = total_backlog();
        testlog.info("after split: sstables={} backlog={}", sstables_after, backlog_after);
        BOOST_REQUIRE_GT(sstables_after, 0);
        BOOST_REQUIRE_GT(backlog_after, 0.0);
    }, std::move(cfg)).get();
}

static zvec_error_code_t handle_error(zvec_error_code_t error,
                                      const char *context) {
  if (error != ZVEC_OK) {
    char *error_msg = NULL;
    zvec_get_last_error(&error_msg);
    fprintf(stderr, "Error in %s: %d - %s\n", context, error,
            error_msg ? error_msg : "Unknown error");
    zvec_free(error_msg);
  }
  return error;
}

void test_diskann_index_params_functions(void) {
  TEST_START();

  // Create DiskANN index params with defaults
  zvec_index_params_t *params =
      zvec_index_params_create(ZVEC_INDEX_TYPE_DISKANN);
  TEST_ASSERT(params != NULL);
  TEST_ASSERT(zvec_index_params_get_type(params) == ZVEC_INDEX_TYPE_DISKANN);

  // Check defaults: max_degree=100, list_size=50, pq_chunk_num=0
  // (aligned with DiskAnnIndexParams constructor defaults)
  TEST_ASSERT(zvec_index_params_get_diskann_max_degree(params) == 100);
  TEST_ASSERT(zvec_index_params_get_diskann_list_size(params) == 50);
  TEST_ASSERT(zvec_index_params_get_diskann_pq_chunk_num(params) == 0);

  // Default metric type is L2
  TEST_ASSERT(zvec_index_params_get_metric_type(params) == ZVEC_METRIC_TYPE_L2);

  // Set and verify custom values
  zvec_index_params_set_metric_type(params, ZVEC_METRIC_TYPE_COSINE);
  TEST_ASSERT(zvec_index_params_get_metric_type(params) ==
              ZVEC_METRIC_TYPE_COSINE);

  zvec_error_code_t err =
      zvec_index_params_set_diskann_params(params, 200, 100, 8);
  TEST_ASSERT(err == ZVEC_OK);
  TEST_ASSERT(zvec_index_params_get_diskann_max_degree(params) == 200);
  TEST_ASSERT(zvec_index_params_get_diskann_list_size(params) == 100);
  TEST_ASSERT(zvec_index_params_get_diskann_pq_chunk_num(params) == 8);

  // Type-mismatch error path: HNSW params must not accept DiskANN setter
  zvec_index_params_t *hnsw = zvec_index_params_create(ZVEC_INDEX_TYPE_HNSW);
  TEST_ASSERT(hnsw != NULL);
  err = zvec_index_params_set_diskann_params(hnsw, 100, 50, 0);
  TEST_ASSERT(err == ZVEC_ERROR_INVALID_ARGUMENT);
  zvec_index_params_destroy(hnsw);

  // NULL pointer handling
  err = zvec_index_params_set_diskann_params(NULL, 100, 50, 0);
  TEST_ASSERT(err == ZVEC_ERROR_INVALID_ARGUMENT);
  TEST_ASSERT(zvec_index_params_get_diskann_max_degree(NULL) == 0);
  TEST_ASSERT(zvec_index_params_get_diskann_list_size(NULL) == 0);
  TEST_ASSERT(zvec_index_params_get_diskann_pq_chunk_num(NULL) == 0);

  // to_string should report DiskANN
  const char *type_str = zvec_index_type_to_string(ZVEC_INDEX_TYPE_DISKANN);
  TEST_ASSERT(type_str != NULL && strcmp(type_str, "DiskANN") == 0);

  zvec_index_params_destroy(params);
  TEST_END();
}

void test_diskann_query_params_functions(void) {
  TEST_START();

  // Create with default list_size
  zvec_diskann_query_params_t *p_default =
      zvec_query_params_diskann_create(300);
  TEST_ASSERT(p_default != NULL);
  TEST_ASSERT(zvec_query_params_diskann_get_list_size(p_default) == 300);
  zvec_query_params_diskann_destroy(p_default);

  // Create with custom list_size
  zvec_diskann_query_params_t *p = zvec_query_params_diskann_create(500);
  TEST_ASSERT(p != NULL);
  TEST_ASSERT(zvec_query_params_diskann_get_list_size(p) == 500);

  // Set/get list_size
  zvec_error_code_t err = zvec_query_params_diskann_set_list_size(p, 1000);
  TEST_ASSERT(err == ZVEC_OK);
  TEST_ASSERT(zvec_query_params_diskann_get_list_size(p) == 1000);

  // Common params: radius
  err = zvec_query_params_diskann_set_radius(p, 1.5f);
  TEST_ASSERT(err == ZVEC_OK);
  TEST_ASSERT(zvec_query_params_diskann_get_radius(p) == 1.5f);

  // Common params: is_linear
  err = zvec_query_params_diskann_set_is_linear(p, true);
  TEST_ASSERT(err == ZVEC_OK);
  TEST_ASSERT(zvec_query_params_diskann_get_is_linear(p) == true);

  // Common params: is_using_refiner
  err = zvec_query_params_diskann_set_is_using_refiner(p, true);
  TEST_ASSERT(err == ZVEC_OK);
  TEST_ASSERT(zvec_query_params_diskann_get_is_using_refiner(p) == true);

  zvec_query_params_diskann_destroy(p);

  // NULL pointer handling: destroy
  zvec_query_params_diskann_destroy(NULL);

  // NULL pointer handling: setters return error
  err = zvec_query_params_diskann_set_list_size(NULL, 100);
  TEST_ASSERT(err == ZVEC_ERROR_INVALID_ARGUMENT);
  err = zvec_query_params_diskann_set_radius(NULL, 0.5f);
  TEST_ASSERT(err == ZVEC_ERROR_INVALID_ARGUMENT);
  err = zvec_query_params_diskann_set_is_linear(NULL, false);
  TEST_ASSERT(err == ZVEC_ERROR_INVALID_ARGUMENT);
  err = zvec_query_params_diskann_set_is_using_refiner(NULL, false);
  TEST_ASSERT(err == ZVEC_ERROR_INVALID_ARGUMENT);

  // NULL pointer handling: getters return safe defaults
  TEST_ASSERT(zvec_query_params_diskann_get_list_size(NULL) == 300);
  TEST_ASSERT(zvec_query_params_diskann_get_radius(NULL) == 0.0f);
  TEST_ASSERT(zvec_query_params_diskann_get_is_linear(NULL) == false);
  TEST_ASSERT(zvec_query_params_diskann_get_is_using_refiner(NULL) == false);

  TEST_END();
}

void test_diskann_wiring_on_vector_query(void) {
  TEST_START();

  zvec_error_code_t err;

  // Test wiring on zvec_vector_query_t
  zvec_vector_query_t *vq = zvec_vector_query_create();
