  TEST_ASSERT(err == ZVEC_ERROR_INVALID_ARGUMENT);
  zvec_query_params_diskann_destroy(dp_null);

  err = zvec_vector_query_set_diskann_params(vq, NULL);
  TEST_ASSERT(err == ZVEC_ERROR_INVALID_ARGUMENT);

  zvec_vector_query_destroy(vq);

  // Test wiring on zvec_group_by_vector_query_t
  zvec_group_by_vector_query_t *gbq = zvec_group_by_vector_query_create();
  TEST_ASSERT(gbq != NULL);

  zvec_diskann_query_params_t *dp2 = zvec_query_params_diskann_create(200);
  TEST_ASSERT(dp2 != NULL);
  err = zvec_group_by_vector_query_set_diskann_params(gbq, dp2);
  TEST_ASSERT(err == ZVEC_OK);

  err = zvec_group_by_vector_query_set_diskann_params(NULL, dp2);
  TEST_ASSERT(err == ZVEC_ERROR_INVALID_ARGUMENT);

  zvec_group_by_vector_query_destroy(gbq);

  // Test wiring on zvec_sub_query_t
  zvec_sub_query_t *sq = zvec_sub_query_create();
  TEST_ASSERT(sq != NULL);

  zvec_diskann_query_params_t *dp3 = zvec_query_params_diskann_create(150);
  TEST_ASSERT(dp3 != NULL);
  err = zvec_sub_query_set_diskann_params(sq, dp3);
  TEST_ASSERT(err == ZVEC_OK);

  err = zvec_sub_query_set_diskann_params(NULL, dp3);
  TEST_ASSERT(err == ZVEC_ERROR_INVALID_ARGUMENT);

  zvec_sub_query_destroy(sq);

  TEST_END();
}

void fht_flip_sign_avx2(const uint8_t *flip, float *data, size_t dim) {
  size_t simd_end = dim & ~31u;
  constexpr size_t kChunk = 32;
  const __m256i bit_select =
      _mm256_setr_epi32(0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80);
  const __m256 sign_flip = _mm256_castsi256_ps(_mm256_set1_epi32(0x80000000));
  for (size_t i = 0; i < simd_end; i += kChunk) {
    uint32_t mask_bits;
    std::memcpy(&mask_bits, &flip[i / 8], sizeof(mask_bits));
    for (int b = 0; b < 4; ++b) {
      __m256i mb = _mm256_set1_epi32((mask_bits >> (b * 8)) & 0xFF);
      __m256i test = _mm256_and_si256(mb, bit_select);
      __m256i cmp = _mm256_cmpeq_epi32(test, bit_select);
      __m256 xor_mask = _mm256_and_ps(_mm256_castsi256_ps(cmp), sign_flip);
      __m256 v = _mm256_loadu_ps(&data[i + b * 8]);
      v = _mm256_xor_ps(v, xor_mask);
      _mm256_storeu_ps(&data[i + b * 8], v);
    }
  }
  // Scalar tail
  for (size_t i = simd_end; i < dim; ++i) {
    if (flip[i / 8] & (1u << (i % 8))) {
      data[i] = -data[i];
    }
  }
}

void fht_kacs_walk_avx2(float *data, size_t len) {
  size_t half = len / 2;
  size_t base = len % 2;
  size_t offset = base + half;
  size_t half_end = half & ~7u;
  for (size_t i = 0; i < half_end; i += 8) {
    __m256 x = _mm256_loadu_ps(&data[i]);
    __m256 y = _mm256_loadu_ps(&data[i + offset]);
    _mm256_storeu_ps(&data[i], _mm256_add_ps(x, y));
    _mm256_storeu_ps(&data[i + offset], _mm256_sub_ps(x, y));
  }
  // Scalar tail
  for (size_t i = half_end; i < half; ++i) {
    float x = data[i];
    float y = data[i + offset];
    data[i] = x + y;
    data[i + offset] = x - y;
  }
  if (base != 0) {
    data[half] *= std::sqrt(2.0f);
  }
}

void fht_inv_kacs_walk_avx2(float *data, size_t len) {
  size_t half = len / 2;
  size_t base = len % 2;
  size_t offset = base + half;
  if (base != 0) {
    data[half] *= std::sqrt(0.5f);
  }
  size_t half_end = half & ~7u;
  const __m256 half_fac = _mm256_set1_ps(0.5f);
  for (size_t i = 0; i < half_end; i += 8) {
    __m256 a = _mm256_loadu_ps(&data[i]);
    __m256 b = _mm256_loadu_ps(&data[i + offset]);
    _mm256_storeu_ps(&data[i], _mm256_mul_ps(_mm256_add_ps(a, b), half_fac));
    _mm256_storeu_ps(&data[i + offset],
                     _mm256_mul_ps(_mm256_sub_ps(a, b), half_fac));
  }
  // Scalar tail
  for (size_t i = half_end; i < half; ++i) {
    float a = data[i];
    float b = data[i + offset];
    data[i] = (a + b) * 0.5f;
    data[i + offset] = (a - b) * 0.5f;
  }
}

void fht_inplace_avx2(float *data, size_t n) {
  for (size_t len = 1; len < n; len <<= 1) {
    size_t step = len << 1;
    size_t simd_end = len & ~7u;
    for (size_t i = 0; i < n; i += step) {
      for (size_t j = 0; j < simd_end; j += 8) {
        __m256 u = _mm256_loadu_ps(&data[i + j]);
        __m256 v = _mm256_loadu_ps(&data[i + j + len]);
        _mm256_storeu_ps(&data[i + j], _mm256_add_ps(u, v));
        _mm256_storeu_ps(&data[i + j + len], _mm256_sub_ps(u, v));
      }
      for (size_t j = simd_end; j < len; ++j) {
        float u = data[i + j];
        float v = data[i + j + len];
        data[i + j] = u + v;
        data[i + j + len] = u - v;
      }
    }
  }
}

void fht_flip_sign_avx512(const uint8_t *flip, float *data, size_t dim) {
  size_t simd_end = dim & ~63u;
  constexpr size_t kChunk = 64;
  const __m512 sign_flip = _mm512_castsi512_ps(_mm512_set1_epi32(0x80000000));
  for (size_t i = 0; i < simd_end; i += kChunk) {
    uint64_t mask_bits;
    std::memcpy(&mask_bits, &flip[i / 8], sizeof(mask_bits));
    const __mmask16 m0 = _cvtu32_mask16(mask_bits & 0xFFFF);
    const __mmask16 m1 = _cvtu32_mask16((mask_bits >> 16) & 0xFFFF);
    const __mmask16 m2 = _cvtu32_mask16((mask_bits >> 32) & 0xFFFF);
    const __mmask16 m3 = _cvtu32_mask16((mask_bits >> 48) & 0xFFFF);
    __m512 v0 = _mm512_loadu_ps(&data[i]);
    v0 = _mm512_mask_xor_ps(v0, m0, v0, sign_flip);
    _mm512_storeu_ps(&data[i], v0);
    __m512 v1 = _mm512_loadu_ps(&data[i + 16]);
    v1 = _mm512_mask_xor_ps(v1, m1, v1, sign_flip);
    _mm512_storeu_ps(&data[i + 16], v1);
    __m512 v2 = _mm512_loadu_ps(&data[i + 32]);
    v2 = _mm512_mask_xor_ps(v2, m2, v2, sign_flip);
    _mm512_storeu_ps(&data[i + 32], v2);
    __m512 v3 = _mm512_loadu_ps(&data[i + 48]);
    v3 = _mm512_mask_xor_ps(v3, m3, v3, sign_flip);
    _mm512_storeu_ps(&data[i + 48], v3);
  }
  // Scalar tail
  for (size_t i = simd_end; i < dim; ++i) {
    if (flip[i / 8] & (1u << (i % 8))) {
      data[i] = -data[i];
    }
  }
}

void fht_kacs_walk_avx512(float *data, size_t len) {
  size_t half = len / 2;
  size_t base = len % 2;
  size_t offset = base + half;
  size_t half_end = half & ~15u;
  for (size_t i = 0; i < half_end; i += 16) {
    __m512 x = _mm512_loadu_ps(&data[i]);
    __m512 y = _mm512_loadu_ps(&data[i + offset]);
    _mm512_storeu_ps(&data[i], _mm512_add_ps(x, y));
    _mm512_storeu_ps(&data[i + offset], _mm512_sub_ps(x, y));
  }
  // Scalar tail
  for (size_t i = half_end; i < half; ++i) {
    float x = data[i];
    float y = data[i + offset];
    data[i] = x + y;
    data[i + offset] = x - y;
  }
  if (base != 0) {
    data[half] *= std::sqrt(2.0f);
  }
}

void fht_inv_kacs_walk_avx512(float *data, size_t len) {
  size_t half = len / 2;
  size_t base = len % 2;
  size_t offset = base + half;
  if (base != 0) {
    data[half] *= std::sqrt(0.5f);
  }
  size_t half_end = half & ~15u;
  const __m512 half_fac = _mm512_set1_ps(0.5f);
  for (size_t i = 0; i < half_end; i += 16) {
    __m512 a = _mm512_loadu_ps(&data[i]);
    __m512 b = _mm512_loadu_ps(&data[i + offset]);
    _mm512_storeu_ps(&data[i], _mm512_mul_ps(_mm512_add_ps(a, b), half_fac));
    _mm512_storeu_ps(&data[i + offset],
                     _mm512_mul_ps(_mm512_sub_ps(a, b), half_fac));
  }
  // Scalar tail
  for (size_t i = half_end; i < half; ++i) {
    float a = data[i];
    float b = data[i + offset];
    data[i] = (a + b) * 0.5f;
    data[i + offset] = (a - b) * 0.5f;
  }
}

void fht_inplace_avx512(float *data, size_t n) {
  for (size_t len = 1; len < n; len <<= 1) {
    size_t step = len << 1;
    size_t simd_end = len & ~15u;
    for (size_t i = 0; i < n; i += step) {
      for (size_t j = 0; j < simd_end; j += 16) {
        __m512 u = _mm512_loadu_ps(&data[i + j]);
        __m512 v = _mm512_loadu_ps(&data[i + j + len]);
        _mm512_storeu_ps(&data[i + j], _mm512_add_ps(u, v));
        _mm512_storeu_ps(&data[i + j + len], _mm512_sub_ps(u, v));
      }
      for (size_t j = simd_end; j < len; ++j) {
        float u = data[i + j];
        float v = data[i + j + len];
        data[i + j] = u + v;
        data[i + j + len] = u - v;
      }
    }
  }
}

void fht_flip_sign(const uint8_t *flip, float *data, size_t dim) {
#if defined(__ARM_NEON) && defined(__aarch64__)
  fht_flip_sign_neon(flip, data, dim);
#else
#if defined(__AVX512F__)
  if (internal::CpuFeatures::static_flags_.AVX512F &&
      internal::CpuFeatures::static_flags_.AVX512DQ) {
    fht_flip_sign_avx512(flip, data, dim);
    return;
  }
#endif
#if defined(__AVX2__)
  if (internal::CpuFeatures::static_flags_.AVX2) {
    fht_flip_sign_avx2(flip, data, dim);
    return;
  }
#endif
#if defined(__SSE2__)
  if (internal::CpuFeatures::static_flags_.SSE2) {
    fht_flip_sign_sse(flip, data, dim);
    return;
  }
#endif
  fht_flip_sign_scalar(flip, data, dim);
#endif  // __ARM_NEON
}

void fht_kacs_walk(float *data, size_t len) {
#if defined(__ARM_NEON) && defined(__aarch64__)
  fht_kacs_walk_neon(data, len);
#else
#if defined(__AVX512F__)
  if (internal::CpuFeatures::static_flags_.AVX512F) {
    fht_kacs_walk_avx512(data, len);
    return;
  }
#endif
#if defined(__AVX2__)
  if (internal::CpuFeatures::static_flags_.AVX2) {
    fht_kacs_walk_avx2(data, len);
    return;
  }
#endif
#if defined(__SSE2__)
  if (internal::CpuFeatures::static_flags_.SSE2) {
    fht_kacs_walk_sse(data, len);
    return;
  }
#endif
  fht_kacs_walk_scalar(data, len);
#endif  // __ARM_NEON
}

void fht_inv_kacs_walk(float *data, size_t len) {
#if defined(__ARM_NEON) && defined(__aarch64__)
  fht_inv_kacs_walk_neon(data, len);
#else
#if defined(__AVX512F__)
  if (internal::CpuFeatures::static_flags_.AVX512F) {
    fht_inv_kacs_walk_avx512(data, len);
    return;
  }
#endif
#if defined(__AVX2__)
  if (internal::CpuFeatures::static_flags_.AVX2) {
    fht_inv_kacs_walk_avx2(data, len);
    return;
  }
#endif
#if defined(__SSE2__)
  if (internal::CpuFeatures::static_flags_.SSE2) {
    fht_inv_kacs_walk_sse(data, len);
    return;
  }
#endif
  fht_inv_kacs_walk_scalar(data, len);
#endif  // __ARM_NEON
}

void fht_inplace(float *data, size_t n) {
#if defined(__AVX512F__)
  if (internal::CpuFeatures::static_flags_.AVX512F) {
    fht_inplace_avx512(data, n);
    return;
  }
#endif
#if defined(__AVX2__)
  if (internal::CpuFeatures::static_flags_.AVX2) {
    fht_inplace_avx2(data, n);
    return;
  }
#endif
  fht_inplace_scalar(data, n);
}

void fht_flip_sign_neon(const uint8_t *flip, float *data, size_t dim) {
  const uint32x4_t sign_bit = vdupq_n_u32(0x80000000u);
  size_t simd_end = dim & ~3u;
  size_t flip_bytes = (dim + 7) / 8;
  for (size_t i = 0; i < simd_end; i += 4) {
    uint16_t bits16;
    size_t byte_pos = i / 8;
    if (byte_pos + 1 < flip_bytes) {
      std::memcpy(&bits16, &flip[byte_pos], sizeof(bits16));
    } else {
      bits16 = flip[byte_pos];
    }
    bits16 >>= (i % 8);
    uint32_t b0 = bits16 & 1u;
    uint32_t b1 = (bits16 >> 1) & 1u;
    uint32_t b2 = (bits16 >> 2) & 1u;
    uint32_t b3 = (bits16 >> 3) & 1u;
    uint32x4_t bit_mask = {b0, b1, b2, b3};
    uint32x4_t sign_mask = vmulq_u32(bit_mask, sign_bit);
    float32x4_t v = vld1q_f32(&data[i]);
    v = vreinterpretq_f32_u32(veorq_u32(vreinterpretq_u32_f32(v), sign_mask));
    vst1q_f32(&data[i], v);
  }
  // Scalar tail
  for (size_t i = simd_end; i < dim; ++i) {
    if (flip[i / 8] & (1u << (i % 8))) {
      data[i] = -data[i];
    }
  }
}

void fht_kacs_walk_neon(float *data, size_t len) {
  size_t half = len / 2;
  size_t base = len % 2;
  size_t offset = base + half;
  size_t half_end = half & ~3u;
  for (size_t i = 0; i < half_end; i += 4) {
    float32x4_t x = vld1q_f32(&data[i]);
    float32x4_t y = vld1q_f32(&data[i + offset]);
    vst1q_f32(&data[i], vaddq_f32(x, y));
    vst1q_f32(&data[i + offset], vsubq_f32(x, y));
  }
  // Scalar tail
  for (size_t i = half_end; i < half; ++i) {
    float x = data[i];
    float y = data[i + offset];
    data[i] = x + y;
    data[i + offset] = x - y;
  }
  if (base != 0) {
    data[half] *= std::sqrt(2.0f);
  }
}

void fht_inv_kacs_walk_neon(float *data, size_t len) {
  size_t half = len / 2;
  size_t base = len % 2;
  size_t offset = base + half;
  if (base != 0) {
    data[half] *= std::sqrt(0.5f);
  }
  size_t half_end = half & ~3u;
  const float32x4_t half_fac = vdupq_n_f32(0.5f);
  for (size_t i = 0; i < half_end; i += 4) {
    float32x4_t a = vld1q_f32(&data[i]);
    float32x4_t b = vld1q_f32(&data[i + offset]);
    vst1q_f32(&data[i], vmulq_f32(vaddq_f32(a, b), half_fac));
    vst1q_f32(&data[i + offset], vmulq_f32(vsubq_f32(a, b), half_fac));
  }
  // Scalar tail
  for (size_t i = half_end; i < half; ++i) {
    float a = data[i];
    float b = data[i + offset];
    data[i] = (a + b) * 0.5f;
    data[i + offset] = (a - b) * 0.5f;
  }
}

void fht_flip_sign_scalar(const uint8_t *flip, float *data, size_t dim) {
  for (size_t i = 0; i < dim; ++i) {
    if (flip[i / 8] & (1u << (i % 8))) {
      data[i] = -data[i];
    }
  }
}

void fht_kacs_walk_scalar(float *data, size_t len) {
  size_t half = len / 2;
  size_t base = len % 2;
  size_t offset = base + half;
  for (size_t i = 0; i < half; ++i) {
    float x = data[i];
    float y = data[i + offset];
    data[i] = x + y;
    data[i + offset] = x - y;
  }
  if (base != 0) {
    data[half] *= std::sqrt(2.0f);
  }
}

void fht_inv_kacs_walk_scalar(float *data, size_t len) {
  size_t half = len / 2;
  size_t base = len % 2;
  size_t offset = base + half;
  if (base != 0) {
    data[half] *= std::sqrt(0.5f);
  }
  for (size_t i = 0; i < half; ++i) {
    float a = data[i];
    float b = data[i + offset];
    data[i] = (a + b) * 0.5f;
    data[i + offset] = (a - b) * 0.5f;
  }
}

void fht_inplace_scalar(float *data, size_t n) {
  for (size_t len = 1; len < n; len <<= 1) {
    for (size_t i = 0; i < n; i += len << 1) {
      for (size_t j = i; j < i + len; ++j) {
        float u = data[j];
        float v = data[j + len];
        data[j] = u + v;
        data[j + len] = u - v;
      }
    }
  }
}

void fht_vec_rescale(float *data, size_t n, float factor) {
  for (size_t i = 0; i < n; ++i) {
    data[i] *= factor;
  }
}

void fht_flip_sign_sse(const uint8_t *flip, float *data, size_t dim) {
  size_t simd_end = dim & ~3u;
  size_t flip_bytes = (dim + 7) / 8;
  for (size_t i = 0; i < simd_end; i += 4) {
    uint16_t bits16;
    size_t byte_pos = i / 8;
    if (byte_pos + 1 < flip_bytes) {
      std::memcpy(&bits16, &flip[byte_pos], sizeof(bits16));
    } else {
      bits16 = flip[byte_pos];
    }
    bits16 >>= (i % 8);
    uint32_t b0 = bits16 & 1u;
    uint32_t b1 = (bits16 >> 1) & 1u;
    uint32_t b2 = (bits16 >> 2) & 1u;
    uint32_t b3 = (bits16 >> 3) & 1u;
    __m128i bit_mask = _mm_set_epi32(b3, b2, b1, b0);
    __m128i sign_mask = _mm_slli_epi32(bit_mask, 31);
    __m128 v = _mm_loadu_ps(&data[i]);
    v = _mm_xor_ps(v, _mm_castsi128_ps(sign_mask));
    _mm_storeu_ps(&data[i], v);
  }
  // Scalar tail
  for (size_t i = simd_end; i < dim; ++i) {
    if (flip[i / 8] & (1u << (i % 8))) {
      data[i] = -data[i];
    }
  }
}

void fht_kacs_walk_sse(float *data, size_t len) {
  size_t half = len / 2;
  size_t base = len % 2;
  size_t offset = base + half;
  size_t half_end = half & ~3u;
  for (size_t i = 0; i < half_end; i += 4) {
    __m128 x = _mm_loadu_ps(&data[i]);
    __m128 y = _mm_loadu_ps(&data[i + offset]);
    _mm_storeu_ps(&data[i], _mm_add_ps(x, y));
    _mm_storeu_ps(&data[i + offset], _mm_sub_ps(x, y));
  }
  // Scalar tail
  for (size_t i = half_end; i < half; ++i) {
    float x = data[i];
    float y = data[i + offset];
    data[i] = x + y;
    data[i + offset] = x - y;
  }
  if (base != 0) {
    data[half] *= std::sqrt(2.0f);
  }
}

void fht_inv_kacs_walk_sse(float *data, size_t len) {
  size_t half = len / 2;
  size_t base = len % 2;
  size_t offset = base + half;
  if (base != 0) {
    data[half] *= std::sqrt(0.5f);
  }
  size_t half_end = half & ~3u;
  const __m128 half_fac = _mm_set1_ps(0.5f);
  for (size_t i = 0; i < half_end; i += 4) {
    __m128 a = _mm_loadu_ps(&data[i]);
    __m128 b = _mm_loadu_ps(&data[i + offset]);
    _mm_storeu_ps(&data[i], _mm_mul_ps(_mm_add_ps(a, b), half_fac));
    _mm_storeu_ps(&data[i + offset], _mm_mul_ps(_mm_sub_ps(a, b), half_fac));
  }
  // Scalar tail
  for (size_t i = half_end; i < half; ++i) {
    float a = data[i];
    float b = data[i + offset];
    data[i] = (a + b) * 0.5f;
    data[i + offset] = (a - b) * 0.5f;
  }
}

zvec_error_code_t zvec_index_params_set_quantizer_enable_rotate(
    zvec_index_params_t *params, bool enable_rotate) {
  if (!params) {
    SET_LAST_ERROR(ZVEC_ERROR_INVALID_ARGUMENT,
                   "Index params pointer cannot be null");
    return ZVEC_ERROR_INVALID_ARGUMENT;
  }
  auto *cpp_params = reinterpret_cast<zvec::IndexParams *>(params);

  if (!cpp_params->is_vector_index_type()) {
    SET_LAST_ERROR(ZVEC_ERROR_INVALID_ARGUMENT,
                   "Index params is not a vector index type");
    return ZVEC_ERROR_INVALID_ARGUMENT;
  }
  auto *vec_params = dynamic_cast<zvec::VectorIndexParams *>(cpp_params);
  if (!vec_params) {
    SET_LAST_ERROR(ZVEC_ERROR_INVALID_ARGUMENT,
                   "Failed to cast to VectorIndexParams");
    return ZVEC_ERROR_INVALID_ARGUMENT;
  }
  zvec::QuantizerParam qp = vec_params->quantizer_param();
  qp.set_enable_rotate(enable_rotate);
  vec_params->set_quantizer_param(qp);
  return ZVEC_OK;
}

bool zvec_index_params_get_quantizer_enable_rotate(
    const zvec_index_params_t *params) {
  if (!params) {
    return false;
  }
  auto *cpp_params = reinterpret_cast<const zvec::IndexParams *>(params);

  if (cpp_params->is_vector_index_type()) {
    auto *vec_params =
        dynamic_cast<const zvec::VectorIndexParams *>(cpp_params);
    if (vec_params) {
      return vec_params->quantizer_param().enable_rotate();
    }
  }
  return false;
}

