      }
    }
    std::unique_ptr<float[]> rotate_buffer;
    if (enable_rotate_ && rotator_) {
      rotate_buffer.reset(new float[rotator_->dimension()]);
      rotator_->rotate(vec, rotate_buffer.get());
      vec = rotate_buffer.get();
    }
      vec = normalize(vec, qmeta, normalized.get());
    std::unique_ptr<float[]> rotate_buffer;
    if (enable_rotate_ && rotator_) {
      rotate_buffer.reset(new float[rotator_->dimension()]);
    }
      if (enable_rotate_ && rotator_) {
        rotator_->rotate(vec, rotate_buffer.get());
        vec = rotate_buffer.get();
      }
    std::unique_ptr<float[]> rotate_buffer;
    if (enable_rotate_ && rotator_) {
      rotate_buffer.reset(new float[rotator_->dimension()]);
      rotator_->rotate(vec, rotate_buffer.get());
      vec = rotate_buffer.get();
    }
      vec = normalize(vec, rmeta, normalized.get());
    std::unique_ptr<float[]> rotate_buffer;
    if (enable_rotate_ && rotator_) {
      rotate_buffer.reset(new float[rotator_->dimension()]);
    }
      if (enable_rotate_ && rotator_) {
        rotator_->rotate(vec, rotate_buffer.get());
        vec = rotate_buffer.get();
      }
    const size_t stored_dim = qmeta.dimension() - extra_dimension_;

    // Step 1: Unquantize into out buffer (stored_dim floats)
    out->resize(stored_dim * sizeof(float));
    RecordQuantizer::unquantize_record(in, stored_dim, data_type_, out_buf);
    // Step 2: Inverse rotate in-place if rotation was applied
    if (enable_rotate_ && rotator_) {
      rotator_->unrotate(out_buf, out_buf);
    }
  bool enable_rotate_{false};
  std::shared_ptr<Rotator> rotator_{};

size_t floor_pow2(size_t n) {
  if (n == 0) return 0;
  size_t p = 1;
  while (p * 2 <= n) p *= 2;
  return p;
}

int FhtRotator::init_impl(size_t dim) {
  if (dim == 0) {
    return IndexError_InvalidArgument;
  }
  trunc_dim = floor_pow2(dim);
  fac = 1.0f / std::sqrt(static_cast<float>(trunc_dim));
  flip_offset_ = (dim + kByteLen - 1) / kByteLen;
  flip.resize(4 * flip_offset_);
  std::random_device rd;
  std::mt19937 gen(rd());
  std::uniform_int_distribution<int> dist(0, 255);
  for (auto &b : flip) b = static_cast<uint8_t>(dist(gen));
  return 0;
}

void FhtRotator::rotate(const float *in, float *out) const {
  const size_t dim = dimension_;
  std::memcpy(out, in, sizeof(float) * dim);

  if (trunc_dim == dim) {
    // Exact power-of-2: 4 rounds of (flip -> FHT -> rescale)
    ailego::fht_flip_sign(flip.data(), out, dim);
    ailego::fht_inplace(out, trunc_dim);
    ailego::fht_vec_rescale(out, trunc_dim, fac);

    ailego::fht_flip_sign(flip.data() + flip_offset_, out, dim);
    ailego::fht_inplace(out, trunc_dim);
    ailego::fht_vec_rescale(out, trunc_dim, fac);

    ailego::fht_flip_sign(flip.data() + 2 * flip_offset_, out, dim);
    ailego::fht_inplace(out, trunc_dim);
    ailego::fht_vec_rescale(out, trunc_dim, fac);

    ailego::fht_flip_sign(flip.data() + 3 * flip_offset_, out, dim);
    ailego::fht_inplace(out, trunc_dim);
    ailego::fht_vec_rescale(out, trunc_dim, fac);

    return;
  }

  // Non-power-of-2 (e.g. 97, 100, 192, 320): 4 rounds with kacs_walk
  size_t start = dim - trunc_dim;
  float *trunc_ptr = out + start;

  // Round 1: FHT on [0, trunc_dim)
  ailego::fht_flip_sign(flip.data(), out, dim);
  ailego::fht_inplace(out, trunc_dim);
  ailego::fht_vec_rescale(out, trunc_dim, fac);
  ailego::fht_kacs_walk(out, dim);

  // Round 2: FHT on [start, start + trunc_dim)
  ailego::fht_flip_sign(flip.data() + flip_offset_, out, dim);
  ailego::fht_inplace(trunc_ptr, trunc_dim);
  ailego::fht_vec_rescale(trunc_ptr, trunc_dim, fac);
  ailego::fht_kacs_walk(out, dim);

  // Round 3: FHT on [0, trunc_dim)
  ailego::fht_flip_sign(flip.data() + 2 * flip_offset_, out, dim);
  ailego::fht_inplace(out, trunc_dim);
  ailego::fht_vec_rescale(out, trunc_dim, fac);
  ailego::fht_kacs_walk(out, dim);

  // Round 4: FHT on [start, start + trunc_dim)
  ailego::fht_flip_sign(flip.data() + 3 * flip_offset_, out, dim);
  ailego::fht_inplace(trunc_ptr, trunc_dim);
  ailego::fht_vec_rescale(trunc_ptr, trunc_dim, fac);
  ailego::fht_kacs_walk(out, dim);

  // Final rescale: combine the 4 kacs_walk reductions
  ailego::fht_vec_rescale(out, dim, 0.25f);
}

void FhtRotator::unrotate(const float *in, float *out) const {
  const size_t dim = dimension_;
  // Copy input into working buffer
  std::vector<float> data(in, in + dim);

  if (trunc_dim == dim) {
    // Exact power-of-2: reverse 4 rounds in reverse order.
    const float inv_fac = 1.0f / std::sqrt(static_cast<float>(trunc_dim));
    for (int round = 3; round >= 0; --round) {
      ailego::fht_inplace(data.data(), trunc_dim);
      ailego::fht_vec_rescale(data.data(), trunc_dim, inv_fac);
      ailego::fht_flip_sign(flip.data() + round * flip_offset_, data.data(),
                            dim);
    }
    std::memcpy(out, data.data(), dim * sizeof(float));
    return;
  }

  // Non-power-of-2: undo final rescale(0.25) first
  ailego::fht_vec_rescale(data.data(), dim, 4.0f);

  const float inv_fac = 1.0f / std::sqrt(static_cast<float>(trunc_dim));
  size_t start = dim - trunc_dim;
  float *trunc_ptr = data.data() + start;

  // Undo Round 4 (FHT on [start, start+trunc_dim))
  ailego::fht_inv_kacs_walk(data.data(), dim);
  ailego::fht_inplace(trunc_ptr, trunc_dim);
  ailego::fht_vec_rescale(trunc_ptr, trunc_dim, inv_fac);
  ailego::fht_flip_sign(flip.data() + 3 * flip_offset_, data.data(), dim);

  // Undo Round 3 (FHT on [0, trunc_dim))
  ailego::fht_inv_kacs_walk(data.data(), dim);
  ailego::fht_inplace(data.data(), trunc_dim);
  ailego::fht_vec_rescale(data.data(), trunc_dim, inv_fac);
  ailego::fht_flip_sign(flip.data() + 2 * flip_offset_, data.data(), dim);

  // Undo Round 2 (FHT on [start, start+trunc_dim))
  ailego::fht_inv_kacs_walk(data.data(), dim);
  ailego::fht_inplace(trunc_ptr, trunc_dim);
  ailego::fht_vec_rescale(trunc_ptr, trunc_dim, inv_fac);
  ailego::fht_flip_sign(flip.data() + flip_offset_, data.data(), dim);

  // Undo Round 1 (FHT on [0, trunc_dim))
  ailego::fht_inv_kacs_walk(data.data(), dim);
  ailego::fht_inplace(data.data(), trunc_dim);
  ailego::fht_vec_rescale(data.data(), trunc_dim, inv_fac);
  ailego::fht_flip_sign(flip.data(), data.data(), dim);

  std::memcpy(out, data.data(), dim * sizeof(float));
}

void FhtRotator::load_blob(const char *data) {
  // Recompute derived fields from dimension_ (init_impl is not called
  // during open, so trunc_dim/fac/flip_offset_ must be restored here)
  trunc_dim = floor_pow2(dimension_);
  fac = 1.0f / std::sqrt(static_cast<float>(trunc_dim));
  flip_offset_ = (dimension_ + kByteLen - 1) / kByteLen;
  // Load flip data
  flip.resize(4 * flip_offset_);
  std::memcpy(flip.data(), data, flip.size());
}

void random_gaussian_matrix(float *mat, size_t dim) {
  static std::random_device rd;
  static std::mt19937 gen(rd());
  std::normal_distribution<float> dist(0.0f, 1.0f);
  for (size_t i = 0; i < dim * dim; ++i) {
    mat[i] = dist(gen);
  }
}

void householder_qr(const float *A_in, float *q, size_t dim) {
  // R starts as a copy of A
  std::vector<float> R(A_in, A_in + dim * dim);

  // Q starts as identity
  std::fill(q, q + dim * dim, 0.0f);
  for (size_t i = 0; i < dim; ++i) {
    q[i * dim + i] = 1.0f;
  }

  std::vector<float> v(dim);

  for (size_t k = 0; k < dim; ++k) {
    // x = R[k:dim, k]  (sub-column below and including diagonal)
    float norm_x_sq = 0.0f;
    for (size_t i = k; i < dim; ++i) {
      norm_x_sq += R[i * dim + k] * R[i * dim + k];
    }
    if (norm_x_sq == 0.0f) continue;

    float norm_x = std::sqrt(norm_x_sq);

    // alpha = -sign(R[k][k]) * ||x||  (choose sign to avoid cancellation)
    float alpha = (R[k * dim + k] >= 0.0f) ? -norm_x : norm_x;

    // v = x - alpha * e1  (only the sub-vector [k, dim) is non-zero)
    for (size_t i = k; i < dim; ++i) {
      v[i - k] = R[i * dim + k];
    }
    v[0] -= alpha;

    // Normalize v
    float v_norm_sq = 0.0f;
    for (size_t i = 0; i < dim - k; ++i) {
      v_norm_sq += v[i] * v[i];
    }
    if (v_norm_sq == 0.0f) continue;
    float inv_v_norm = 1.0f / std::sqrt(v_norm_sq);
    for (size_t i = 0; i < dim - k; ++i) {
      v[i] *= inv_v_norm;
    }

    // Apply Householder reflection to R: R[k:dim, k:dim] -= 2*v*(v^T * R)
    for (size_t j = k; j < dim; ++j) {
      float dot = 0.0f;
      for (size_t i = 0; i < dim - k; ++i) {
        dot += v[i] * R[(k + i) * dim + j];
      }
      dot *= 2.0f;
      for (size_t i = 0; i < dim - k; ++i) {
        R[(k + i) * dim + j] -= v[i] * dot;
      }
    }

    // Accumulate Q: Q[:, k:dim] -= 2*(Q[:, k:dim] * v) * v^T
    for (size_t i = 0; i < dim; ++i) {
      float dot = 0.0f;
      for (size_t j = 0; j < dim - k; ++j) {
        dot += q[i * dim + k + j] * v[j];
      }
      dot *= 2.0f;
      for (size_t j = 0; j < dim - k; ++j) {
        q[i * dim + k + j] -= dot * v[j];
      }
    }
  }
}

int MatrixRotator::init_impl(size_t dim) {
  if (dim == 0) {
    return IndexError_InvalidArgument;
  }
  // Generate dim x dim random Gaussian matrix
  std::vector<float> rand_mat(dim * dim);
  random_gaussian_matrix(rand_mat.data(), dim);

  // Householder QR: A = Q * R, use Q^T as the rotation matrix
  std::vector<float> Q(dim * dim);
  householder_qr(rand_mat.data(), Q.data(), dim);

  // Store Q^T (transpose) as the rotation matrix
  matrix_.resize(dim * dim);
  for (size_t i = 0; i < dim; ++i) {
    for (size_t j = 0; j < dim; ++j) {
      matrix_[j * dim + i] = Q[i * dim + j];
    }
  }
  return 0;
}

void MatrixRotator::rotate(const float *in, float *out) const {
  const size_t dim = dimension_;
  // out = in * matrix_  (1 x dim) * (dim x dim) -> (1 x dim)
  for (size_t j = 0; j < dim; ++j) {
    float sum = 0.0f;
    for (size_t i = 0; i < dim; ++i) {
      sum += in[i] * matrix_[i * dim + j];
    }
    out[j] = sum;
  }
}

void MatrixRotator::unrotate(const float *in, float *out) const {
  const size_t dim = dimension_;
  // out = in * matrix_^T  (1 x dim) * (dim x dim)^T -> (1 x dim)
  for (size_t j = 0; j < dim; ++j) {
    float sum = 0.0f;
    for (size_t i = 0; i < dim; ++i) {
      sum += in[i] * matrix_[j * dim + i];
    }
    out[j] = sum;
  }
}

void MatrixRotator::load_blob(const char *data) {
  // matrix_ must be pre-sized before loading
  if (matrix_.empty()) {
    matrix_.resize(dimension_ * dimension_);
  }
  std::memcpy(matrix_.data(), data, matrix_.size() * sizeof(float));
}

uint32_t read_u32_le(const char *p) {
  return static_cast<uint32_t>(static_cast<uint8_t>(p[0])) |
         (static_cast<uint32_t>(static_cast<uint8_t>(p[1])) << 8) |
         (static_cast<uint32_t>(static_cast<uint8_t>(p[2])) << 16) |
         (static_cast<uint32_t>(static_cast<uint8_t>(p[3])) << 24);
}

void write_u32_le(char *p, uint32_t v) {
  p[0] = static_cast<char>(v & 0xFF);
  p[1] = static_cast<char>((v >> 8) & 0xFF);
  p[2] = static_cast<char>((v >> 16) & 0xFF);
  p[3] = static_cast<char>((v >> 24) & 0xFF);
}

void write_to(char *buf) const {
    write_u32_le(buf + 0, magic);
    write_u16_le(buf + 4, version);
    write_u16_le(buf + 6, rotator_type);
    write_u32_le(buf + 8, in_dim);
    write_u32_le(buf + 12, out_dim);
    write_u32_le(buf + 16, payload_size);
    write_u32_le(buf + 20, reserved);
  }

void read_from(const char *buf) {
    magic = read_u32_le(buf + 0);
    version = read_u16_le(buf + 4);
    rotator_type = read_u16_le(buf + 6);
    in_dim = read_u32_le(buf + 8);
    out_dim = read_u32_le(buf + 12);
    payload_size = read_u32_le(buf + 16);
    reserved = read_u32_le(buf + 20);
  }

int Rotator::create(std::shared_ptr<Rotator> *out, size_t dimension,
                    RotatorType rotator_type) {
  *out = nullptr;
  std::unique_ptr<Rotator> rot;
  if (rotator_type == RotatorType::FhtKac) {
    rot = std::make_unique<FhtRotator>();
  } else {
    rot = std::make_unique<MatrixRotator>();
  }
  rot->dimension_ = dimension;
  int ret = rot->init_impl(dimension);
  if (ret != 0) {
    LOG_ERROR("Rotator::create: init_impl failed, ret=%d, dim=%zu", ret,
              dimension);
    return ret;
  }
  rot->initialized_ = true;
  *out = std::move(rot);
  return 0;
}

int Rotator::open(std::shared_ptr<Rotator> *out, IndexStorage::Pointer storage,
                  const std::string &seg_id) {
  *out = nullptr;
  if (!storage) {
    LOG_ERROR("Rotator::open: null storage");
    return IndexError_InvalidArgument;
  }

  auto segment = storage->get(seg_id);
  if (!segment) {
    LOG_ERROR("Rotator::open: segment '%s' not found", seg_id.c_str());
    return IndexError_InvalidFormat;
  }

  const size_t data_size = segment->data_size();
  if (data_size <= kHeaderSize) {
    LOG_ERROR("Rotator::open: data too small (%zu bytes)", data_size);
    return IndexError_InvalidFormat;
  }

  IndexStorage::MemoryBlock block;
  size_t read_size = segment->read(0, block, data_size);
  if (read_size != data_size) {
    LOG_ERROR("Rotator::open: read failed, read=%zu, expected=%zu", read_size,
              data_size);
    return IndexError_InvalidFormat;
  }

  // Verify CRC if available (covers header + blob)
  uint32_t expected_crc = segment->data_crc();
  if (expected_crc != 0) {
    uint32_t actual_crc = ailego::Crc32c::Hash(block.data(), data_size, 0);
    if (actual_crc != expected_crc) {
      LOG_ERROR("Rotator::open: CRC mismatch, expected=0x%08x, actual=0x%08x",
                expected_crc, actual_crc);
      return IndexError_InvalidFormat;
    }
  }

  const char *raw = reinterpret_cast<const char *>(block.data());
  uint32_t maybe_magic = read_u32_le(raw);
  if (maybe_magic != kMagic) {
    LOG_ERROR("Rotator::open: invalid magic (expected 0x%08x, got 0x%08x)",
              kMagic, maybe_magic);
    return IndexError_InvalidFormat;
  }

  Header header;
  header.read_from(raw);
  RotatorType type = Header::ser_to_type(header.rotator_type);
  size_t dim = static_cast<size_t>(header.in_dim);

  // Reconstruct the rotator from header info and load blob
  std::unique_ptr<Rotator> rot;
  if (type == RotatorType::FhtKac) {
    rot = std::make_unique<FhtRotator>();
  } else {
    rot = std::make_unique<MatrixRotator>();
  }
  rot->dimension_ = dim;
  rot->load_blob(raw + kHeaderSize);
  rot->initialized_ = true;

  LOG_DEBUG("Rotator::open done: seg=%s, dim=%zu, data_size=%zu",
            seg_id.c_str(), dim, data_size);

  *out = std::move(rot);
  return 0;
}

std::unique_ptr<Rotator> Rotator::load_matrix(const float *matrix,
                                              size_t dimension) {
  if (!matrix || dimension == 0) {
    LOG_ERROR("Rotator::load_matrix: invalid arguments");
    return nullptr;
  }

  std::unique_ptr<Rotator> rot = std::make_unique<MatrixRotator>();
  rot->dimension_ = dimension;
  rot->load_blob(reinterpret_cast<const char *>(matrix));
  rot->initialized_ = true;

  LOG_DEBUG("Rotator::load_matrix done: dim=%zu", dimension);
  return rot;
}

std::vector<float> Rotator::rotate(const float *in) const {
  std::vector<float> out(dimension_);
  rotate(in, out.data());
  return out;
}

std::vector<float> Rotator::unrotate(const float *in) const {
  std::vector<float> out(dimension_);
  unrotate(in, out.data());
  return out;
}

int Rotator::dump(const IndexStorage::Pointer &storage,
                  const std::string &seg_id) const {
  if (!storage) {
    LOG_ERROR("Rotator::dump(storage): null storage");
    return IndexError_InvalidArgument;
  }
  if (!initialized_) {
    LOG_ERROR("Rotator::dump(storage): rotator not initialized");
    return IndexError_NoReady;
  }

  auto align_size = [](size_t size) -> size_t {
    return (size + 0x1F) & (~0x1F);
  };

  const size_t blob_size = blob_bytes();
  const size_t data_size = kHeaderSize + blob_size;
  const size_t total_size = align_size(data_size);
  std::vector<char> buffer(data_size);

  Header header;
  header.magic = kMagic;
  header.version = kVersion;
  header.rotator_type = Header::type_to_ser(rotator_type());
  header.in_dim = static_cast<uint32_t>(dimension_);
  header.out_dim = static_cast<uint32_t>(dimension_);
  header.payload_size = static_cast<uint32_t>(blob_size);
  header.reserved = 0;
  header.write_to(buffer.data());
  save_blob(buffer.data() + kHeaderSize);

  int ret = storage->append(seg_id, total_size);
  if (ret != 0) {
    LOG_ERROR("Rotator::dump(storage): append segment '%s' failed, ret=%d",
              seg_id.c_str(), ret);
    return ret;
  }

  auto segment = storage->get(seg_id);
  if (!segment) {
    LOG_ERROR("Rotator::dump(storage): get segment '%s' failed",
              seg_id.c_str());
    return IndexError_WriteData;
  }

  size_t written = segment->write(0, buffer.data(), data_size);
  if (written != data_size) {
    LOG_ERROR("Rotator::dump(storage): write failed, written=%zu, expected=%zu",
              written, data_size);
    return IndexError_WriteData;
  }
  segment->resize(data_size);
  segment->update_data_crc(ailego::Crc32c::Hash(buffer.data(), data_size, 0));

  LOG_DEBUG("Rotator::dump(storage) done: seg=%s, data_size=%zu, total=%zu",
            seg_id.c_str(), data_size, total_size);
  return 0;
}

int Rotator::dump(const IndexDumper::Pointer &dumper,
                  const std::string &seg_id) const {
  if (!dumper) {
    LOG_ERROR("Rotator::dump(dumper): null dumper");
    return IndexError_InvalidArgument;
  }
  if (!initialized_) {
    LOG_ERROR("Rotator::dump(dumper): rotator not initialized");
    return IndexError_NoReady;
  }

  const size_t blob_size = blob_bytes();
  const size_t data_size = kHeaderSize + blob_size;
  const size_t total_size = (data_size + 0x1F) & (~0x1F);

  std::vector<char> buffer(total_size, 0);
  Header header;
  header.magic = kMagic;
  header.version = kVersion;
  header.rotator_type = Header::type_to_ser(rotator_type());
  header.in_dim = static_cast<uint32_t>(dimension_);
  header.out_dim = static_cast<uint32_t>(dimension_);
  header.payload_size = static_cast<uint32_t>(blob_size);
  header.reserved = 0;
  header.write_to(buffer.data());
  save_blob(buffer.data() + kHeaderSize);

  const uint32_t crc = ailego::Crc32c::Hash(buffer.data(), data_size, 0);
  const size_t padding_size = total_size - data_size;

  if (dumper->write(buffer.data(), total_size) != total_size) {
    LOG_ERROR("Rotator::dump(dumper): write failed, seg=%s", seg_id.c_str());
    return IndexError_WriteData;
  }

  int ret = dumper->append(seg_id, data_size, padding_size, crc);
  if (ret != 0) {
    LOG_ERROR("Rotator::dump(dumper): append failed, seg=%s, ret=%d",
              seg_id.c_str(), ret);
    return ret;
  }

  LOG_DEBUG("Rotator::dump(dumper) done: seg=%s, data_size=%zu, padding=%zu",
            seg_id.c_str(), data_size, padding_size);
  return 0;
}

void test_quantizer_enable_rotate(void) {
  TEST_START();

  // Test 1: set enable_rotate=true on HNSW params and verify
  zvec_index_params_t *hnsw_params =
      zvec_index_params_create(ZVEC_INDEX_TYPE_HNSW);
  TEST_ASSERT(hnsw_params != NULL);

  // Default should be false
  TEST_ASSERT(zvec_index_params_get_quantizer_enable_rotate(hnsw_params) ==
              false);

  // Set to true and verify
  zvec_error_code_t err =
      zvec_index_params_set_quantizer_enable_rotate(hnsw_params, true);
  TEST_ASSERT(err == ZVEC_OK);
  TEST_ASSERT(zvec_index_params_get_quantizer_enable_rotate(hnsw_params) ==
              true);

  // Set back to false and verify
  err = zvec_index_params_set_quantizer_enable_rotate(hnsw_params, false);
  TEST_ASSERT(err == ZVEC_OK);
  TEST_ASSERT(zvec_index_params_get_quantizer_enable_rotate(hnsw_params) ==
              false);

  zvec_index_params_destroy(hnsw_params);

  // Test 2: set enable_rotate on FLAT index params (also a vector index)
  zvec_index_params_t *flat_params =
      zvec_index_params_create(ZVEC_INDEX_TYPE_FLAT);
  TEST_ASSERT(flat_params != NULL);
  err = zvec_index_params_set_quantizer_enable_rotate(flat_params, true);
  TEST_ASSERT(err == ZVEC_OK);
  TEST_ASSERT(zvec_index_params_get_quantizer_enable_rotate(flat_params) ==
              true);
  zvec_index_params_destroy(flat_params);

  // Test 3: set enable_rotate on non-vector index (INVERT) should fail
  zvec_index_params_t *invert_params =
      zvec_index_params_create(ZVEC_INDEX_TYPE_INVERT);
  TEST_ASSERT(invert_params != NULL);
  err = zvec_index_params_set_quantizer_enable_rotate(invert_params, true);
  TEST_ASSERT(err != ZVEC_OK);
  zvec_index_params_destroy(invert_params);

  // Test 4: NULL params should return false for getter
  TEST_ASSERT(zvec_index_params_get_quantizer_enable_rotate(NULL) == false);

  // Test 5: NULL params should return error for setter
  err = zvec_index_params_set_quantizer_enable_rotate(NULL, true);
  TEST_ASSERT(err != ZVEC_OK);

  TEST_END();
}

void test_int8_rotate_e2e(void) {
  TEST_START();

  char temp_dir[] = "./zvec_test_int8_rotate_e2e";
  const size_t dim = 128;
  const size_t cnt = 2000;
  const size_t topk = 10;

  // Create schema with HNSW + INT8 + enable_rotate
  zvec_collection_schema_t *schema =
      zvec_collection_schema_create("int8_rotate_test");
  TEST_ASSERT(schema != NULL);

  // Add ID field
  zvec_field_schema_t *id_field =
      zvec_field_schema_create("id", ZVEC_DATA_TYPE_INT64, false, 0);
  zvec_collection_schema_add_field(schema, id_field);

  // Add vector field with HNSW + INT8 + rotate
  zvec_index_params_t *hnsw_params =
      zvec_index_params_create(ZVEC_INDEX_TYPE_HNSW);
  TEST_ASSERT(hnsw_params != NULL);
  zvec_index_params_set_metric_type(hnsw_params, ZVEC_METRIC_TYPE_L2);
  zvec_index_params_set_hnsw_params(hnsw_params, 16, 100);
  zvec_index_params_set_quantize_type(hnsw_params, ZVEC_QUANTIZE_TYPE_INT8);
  zvec_index_params_set_quantizer_enable_rotate(hnsw_params, true);

  zvec_field_schema_t *vec_field = zvec_field_schema_create(
      "embedding", ZVEC_DATA_TYPE_VECTOR_FP32, false, dim);
  zvec_field_schema_set_index_params(vec_field, hnsw_params);
  zvec_collection_schema_add_field(schema, vec_field);
  zvec_index_params_destroy(hnsw_params);

  // Create and open collection
  zvec_collection_t *collection = NULL;
  zvec_error_code_t err =
      zvec_collection_create_and_open(temp_dir, schema, NULL, &collection);
  TEST_ASSERT(err == ZVEC_OK);
  TEST_ASSERT(collection != NULL);

  // Insert 2000 random vectors
  srand(42);
  for (size_t i = 0; i < cnt; i++) {
    float *vec = (float *)malloc(dim * sizeof(float));
    TEST_ASSERT(vec != NULL);
    for (size_t j = 0; j < dim; j++) {
      vec[j] = (float)rand() / (float)RAND_MAX * 2.0f - 1.0f;
    }

    zvec_doc_t *doc = zvec_doc_create();
    zvec_doc_set_pk(doc, zvec_test_make_pk(i + 1));
    zvec_doc_add_field_by_value(doc, "id", ZVEC_DATA_TYPE_INT64,
                                &(int64_t){(int64_t)(i + 1)}, sizeof(int64_t));
    zvec_doc_add_field_by_value(doc, "embedding", ZVEC_DATA_TYPE_VECTOR_FP32,
                                vec, dim * sizeof(float));

    size_t success_count, error_count;
    const zvec_doc_t *docs[] = {doc};
    err = zvec_collection_insert(collection, docs, 1, &success_count,
                                 &error_count);
    TEST_ASSERT(err == ZVEC_OK);
    zvec_doc_destroy(doc);
    free(vec);
  }

  // Flush to build index
  zvec_collection_flush(collection);

  // Search
  float *query = (float *)malloc(dim * sizeof(float));
  TEST_ASSERT(query != NULL);
  for (size_t j = 0; j < dim; j++) {
    query[j] = (float)rand() / (float)RAND_MAX * 2.0f - 1.0f;
  }

  zvec_vector_query_t *vq = zvec_vector_query_create();
  TEST_ASSERT(vq != NULL);
  zvec_vector_query_set_field_name(vq, "embedding");
  zvec_vector_query_set_query_vector(vq, query, dim * sizeof(float));
  zvec_vector_query_set_topk(vq, topk);

  zvec_doc_t **results = NULL;
  size_t result_count = 0;
  err = zvec_collection_query(collection, vq, &results, &result_count);
  TEST_ASSERT(err == ZVEC_OK);
  TEST_ASSERT(result_count > 0);
  printf("  [int8_rotate_e2e] first search returned %zu results\n",
         result_count);
  zvec_docs_free(results, result_count);

  // Close and reopen
  zvec_collection_close(collection);
  collection = NULL;

  err = zvec_collection_open(temp_dir, NULL, &collection);
  TEST_ASSERT(err == ZVEC_OK);
  TEST_ASSERT(collection != NULL);

  // Search again after reopen (rotator should auto-load from storage)
  results = NULL;
  result_count = 0;
  err = zvec_collection_query(collection, vq, &results, &result_count);
  TEST_ASSERT(err == ZVEC_OK);
  TEST_ASSERT(result_count > 0);
  printf("  [int8_rotate_e2e] reopen search returned %zu results\n",
         result_count);
  zvec_docs_free(results, result_count);

  // Cleanup
  zvec_vector_query_destroy(vq);
  zvec_collection_destroy(collection);
  zvec_collection_schema_destroy(schema);
  free(query);
  cleanup_temp_directory(temp_dir);

  TEST_END();
}

TEST_F(FlatStreamerTest, TestInt8WithRotate) {
  constexpr size_t kTestDim = 128;
  constexpr size_t kCnt = 2000U;
  constexpr size_t kTopk = 10;

  IndexStreamer::Pointer streamer =
      IndexFactory::CreateStreamer("FlatStreamer");
  ASSERT_NE(nullptr, streamer);

  Params params;

  IndexMeta index_meta_raw(IndexMeta::DataType::DT_FP32, kTestDim);
  index_meta_raw.set_metric("SquaredEuclidean", 0, Params());

  // Create INT8 converter with rotation enabled
  Params converter_params;
  converter_params.set("integer_streaming.converter.enable_rotate", true);
  auto converter = IndexFactory::CreateConverter("Int8StreamingConverter");
  ASSERT_NE(nullptr, converter);
  ASSERT_EQ(0, converter->init(index_meta_raw, converter_params));

  IndexMeta index_meta = converter->meta();

  auto reformer = IndexFactory::CreateReformer(index_meta.reformer_name());
  ASSERT_NE(nullptr, reformer);
  ASSERT_EQ(0, reformer->init(index_meta.reformer_params()));

  Params stg_params;
  auto storage = IndexFactory::CreateStorage("MMapFileStorage");
  ASSERT_NE(nullptr, storage);
  ASSERT_EQ(0, storage->init(stg_params));
  ASSERT_EQ(0, storage->open(dir_ + "TestInt8WithRotate.index", true));
  ASSERT_EQ(0, streamer->init(index_meta, params));
  ASSERT_EQ(0, streamer->open(storage));

  // Add 2000 vectors
  auto ctx = streamer->create_context();
  ASSERT_TRUE(!!ctx);
  IndexQueryMeta qmeta(IndexMeta::DataType::DT_FP32, kTestDim);

  std::mt19937 gen(42);
  std::uniform_real_distribution<float> dist(-1.0f, 1.0f);
  for (size_t i = 0; i < kCnt; i++) {
    NumericalVector<float> vec(kTestDim);
    for (size_t j = 0; j < kTestDim; ++j) vec[j] = dist(gen);

    std::string new_vec;
    IndexQueryMeta new_meta;
    ASSERT_EQ(0, reformer->convert(vec.data(), qmeta, &new_vec, &new_meta));
    ASSERT_EQ(0, streamer->add_impl(i, new_vec.data(), new_meta, ctx));
  }

  streamer->flush(0UL);
  streamer.reset();
  storage.reset();

  // Reopen: reformer should auto-detect rotator from storage
  auto storage2 = IndexFactory::CreateStorage("MMapFileStorage");
  ASSERT_NE(nullptr, storage2);
  ASSERT_EQ(0, storage2->init(stg_params));
  ASSERT_EQ(0, storage2->open(dir_ + "TestInt8WithRotate.index", false));

  auto streamer2 = IndexFactory::CreateStreamer("FlatStreamer");
  ASSERT_NE(nullptr, streamer2);
  ASSERT_EQ(0, streamer2->init(index_meta, params));
  ASSERT_EQ(0, streamer2->open(storage2));

  auto reformer2 = IndexFactory::CreateReformer(index_meta.reformer_name());
  ASSERT_NE(nullptr, reformer2);
  ASSERT_EQ(0, reformer2->init(index_meta.reformer_params()));
  ASSERT_EQ(0, reformer2->load(storage2));

  // Search: verify results are non-empty
  auto knnCtx = streamer2->create_context();
  knnCtx->set_topk(kTopk);
  auto linearCtx = streamer2->create_context();
  linearCtx->set_topk(kTopk);

  NumericalVector<float> query(kTestDim);
  for (size_t j = 0; j < kTestDim; ++j) query[j] = dist(gen);

  std::string new_query;
  IndexQueryMeta new_qmeta;
  ASSERT_EQ(0,
            reformer2->transform(query.data(), qmeta, &new_query, &new_qmeta));
  ASSERT_EQ(0, streamer2->search_impl(new_query.data(), new_qmeta, knnCtx));
  ASSERT_EQ(0,
            streamer2->search_bf_impl(new_query.data(), new_qmeta, linearCtx));

  EXPECT_EQ(kTopk, knnCtx->result().size());
  EXPECT_EQ(kTopk, linearCtx->result().size());
}

