TEST(IndexParamsTest, QuantizerParamBasic) {
  // Default constructor: enable_rotate should be false
  QuantizerParam qp_default;
  EXPECT_FALSE(qp_default.enable_rotate());

  // Constructor with true
  QuantizerParam qp_true(true);
  EXPECT_TRUE(qp_true.enable_rotate());

  // Constructor with false
  QuantizerParam qp_false(false);
  EXPECT_FALSE(qp_false.enable_rotate());

  // Setter
  qp_default.set_enable_rotate(true);
  EXPECT_TRUE(qp_default.enable_rotate());
  qp_default.set_enable_rotate(false);
  EXPECT_FALSE(qp_default.enable_rotate());

  // Equality
  EXPECT_TRUE(qp_true == QuantizerParam(true));
  EXPECT_TRUE(qp_false == QuantizerParam(false));
  EXPECT_FALSE(qp_true == qp_false);

  // Inequality
  EXPECT_TRUE(qp_true != qp_false);
  EXPECT_FALSE(qp_true != QuantizerParam(true));
}

TEST(IndexParamsTest, QuantizerParamWithVectorIndex) {
  // HnswIndexParams
  {
    HnswIndexParams params(MetricType::COSINE, 16, 100, QuantizeType::INT8);
    EXPECT_FALSE(params.quantizer_param().enable_rotate());
    EXPECT_FALSE(params.enable_rotate());  // convenience getter

    params.set_quantizer_param(QuantizerParam(true));
    EXPECT_TRUE(params.quantizer_param().enable_rotate());
    EXPECT_TRUE(params.enable_rotate());

    // Clone preserves quantizer_param
    auto cloned = params.clone();
    auto *cloned_hnsw = dynamic_cast<HnswIndexParams *>(cloned.get());
    ASSERT_NE(cloned_hnsw, nullptr);
    EXPECT_TRUE(cloned_hnsw->quantizer_param().enable_rotate());
    EXPECT_TRUE(*cloned == params);

    // Equality: different enable_rotate -> not equal
    HnswIndexParams params2(MetricType::COSINE, 16, 100, QuantizeType::INT8);
    params2.set_quantizer_param(QuantizerParam(false));
    EXPECT_FALSE(params == params2);
  }

  // FlatIndexParams
  {
    FlatIndexParams params(MetricType::L2, QuantizeType::INT8);
    EXPECT_FALSE(params.quantizer_param().enable_rotate());

    params.set_quantizer_param(QuantizerParam(true));
    EXPECT_TRUE(params.quantizer_param().enable_rotate());
    EXPECT_TRUE(params.enable_rotate());

    auto cloned = params.clone();
    auto *cloned_flat = dynamic_cast<FlatIndexParams *>(cloned.get());
    ASSERT_NE(cloned_flat, nullptr);
    EXPECT_TRUE(cloned_flat->quantizer_param().enable_rotate());

    FlatIndexParams params2(MetricType::L2, QuantizeType::INT8);
    EXPECT_FALSE(params == params2);
  }

  // IVFIndexParams
  {
    IVFIndexParams params(MetricType::IP, 128, 10, false, QuantizeType::INT8);
    EXPECT_FALSE(params.quantizer_param().enable_rotate());

    params.set_quantizer_param(QuantizerParam(true));
    EXPECT_TRUE(params.quantizer_param().enable_rotate());
    EXPECT_TRUE(params.enable_rotate());

    auto cloned = params.clone();
    auto *cloned_ivf = dynamic_cast<IVFIndexParams *>(cloned.get());
    ASSERT_NE(cloned_ivf, nullptr);
    EXPECT_TRUE(cloned_ivf->quantizer_param().enable_rotate());

    IVFIndexParams params2(MetricType::IP, 128, 10, false, QuantizeType::INT8);
    EXPECT_FALSE(params == params2);
  }

TEST_F(CollectionTest, Feature_Query_NullableFilter_WithoutIndex) {
  auto run_test = [&](bool with_scalar_index) {
    FileHelper::RemoveDirectory(col_path);
    IndexParams::Ptr scalar_idx =
        with_scalar_index ? std::make_shared<InvertIndexParams>(false) : nullptr;
    auto schema =
        TestHelper::CreateNormalSchema(/*nullable=*/true, "demo", scalar_idx);
    CollectionOptions options{false, true, 100 * 1024 * 1024};
    auto result = Collection::CreateAndOpen(col_path, *schema, options);
    ASSERT_TRUE(result.has_value());
    auto collection = result.value();

    int non_null_count = 50;
    int null_count = 50;
    int total = non_null_count + null_count;

    auto s = TestHelper::CollectionInsertDoc(collection, 0, non_null_count,
                                             /*nullable=*/false);
    ASSERT_TRUE(s.ok());
    s = TestHelper::CollectionInsertDoc(collection, non_null_count, total,
                                        /*nullable=*/true);
    ASSERT_TRUE(s.ok());
    collection->Flush();

    auto stats = collection->Stats().value();
    ASSERT_EQ(stats.doc_count, total);

    auto query_doc = TestHelper::CreateDoc(1, *schema);
    VectorQuery query;
    query.topk_ = total;
    query.field_name_ = "dense_fp32";
    auto vec = query_doc.get<std::vector<float>>("dense_fp32");
    ASSERT_TRUE(vec.has_value());
    query.query_vector_.assign((char *)vec.value().data(),
                               vec.value().size() * sizeof(float));
    query.filter_ = "int32 > 0";
    query.output_fields_ = std::vector<std::string>{"int32"};

    auto query_result = collection->Query(query);
    ASSERT_TRUE(query_result.has_value());
    for (auto &doc : query_result.value()) {
      auto int32_val = doc->get<int32_t>("int32");
      ASSERT_TRUE(int32_val.has_value())
          << "Null doc leaked through filter: " << doc->pk()
          << " (with_scalar_index=" << with_scalar_index << ")";
      ASSERT_GT(int32_val.value(), 0);
    }
    ASSERT_EQ(query_result.value().size(), non_null_count - 1)
        << "with_scalar_index=" << with_scalar_index;
  };

  run_test(false);
  run_test(true);

AVVideoDecoder::~AVVideoDecoder()
{
    if (sws_ctx_)
        sws_freeContext(sws_ctx_);
    if (frame_)
        av_frame_free(&frame_);
    if (codec_ctx_)
        avcodec_free_context(&codec_ctx_);
}

int AVVideoDecoder::open(Bambu_StreamInfo const &info)
{
    auto codec_id = info.sub_type == AVC1 ? AV_CODEC_ID_H264 : AV_CODEC_ID_MJPEG;
    auto codec    = avcodec_find_decoder(codec_id);
    if (codec == nullptr) {
        fprintf(stderr, "AVVideoDecoder: unsupported codec!\n");
        return -1; // Codec not found
    }
    /* open the coderc */
    if (avcodec_open2(codec_ctx_, codec, nullptr) < 0) {
        fprintf(stderr, "AVVideoDecoder: could not open codec\n");
        return -1;
    }

    // Allocate an AVFrame structure
    frame_ = av_frame_alloc();
    if (frame_ == nullptr)
        return -1;

    return 0;
}

int AVVideoDecoder::decode(const Bambu_Sample &sample)
{
    int ret = -1;
    AVPacket *pkt = av_packet_alloc();
    if (!pkt) {
        return ret;
    }

    ret = av_new_packet(pkt, sample.size);
    if (ret != 0) {
        av_packet_free(&pkt);
        return ret;
    }

    memcpy(pkt->data, sample.buffer, size_t(sample.size));

    ret = avcodec_send_packet(codec_ctx_, pkt);
    if (ret == 0) {
        got_frame_ = avcodec_receive_frame(codec_ctx_, frame_) == 0;
    }

    av_packet_unref(pkt);
    av_packet_free(&pkt);
    return ret;
}

int AVVideoDecoder::flush()
{
    int ret = avcodec_send_packet(codec_ctx_, nullptr);
    got_frame_ = avcodec_receive_frame(codec_ctx_, frame_) == 0;
    return ret;
}

bool AVVideoDecoder::toWxImage(wxImage &image, wxSize const &size2)
{
    if (!got_frame_)
        return false;

    auto size1 = size2;
    if (!size1.IsFullySpecified())
        size1 = {frame_->width, frame_->height };
    auto size = size1;
    if (size.GetWidth() & 0x0f) {
        size.SetWidth((size.GetWidth() & ~0x0f) + 0x10);
        if (size.GetWidth() != width_) {
            std::fill(bits_.begin(), bits_.end(), 0);
            width_ = size.GetWidth();
        }
    }
    AVPixelFormat wxFmt = AV_PIX_FMT_RGB24;
    sws_ctx_   = sws_getCachedContext(sws_ctx_,
                                    frame_->width, frame_->height, AVPixelFormat(frame_->format),
                                    size1.GetWidth(), size1.GetHeight(), wxFmt,
                                    SWS_GAUSS,
                                    nullptr, nullptr, nullptr);
    if (sws_ctx_ == nullptr)
        return false;
    int length = size.GetWidth() * size.GetHeight() * 3;
    if (bits_.size() < length)
        bits_.resize(length);
    uint8_t * datas[]   = { bits_.data() };
    int      strides[] = { size.GetWidth() * 3 };
    int      result_h = sws_scale(sws_ctx_, frame_->data, frame_->linesize, 0, frame_->height, datas, strides);
    if (result_h != size.GetHeight()) {
        return false;
    }
    // Copy: the frame outlives this decoder and is painted by the GUI thread while the
    // next sws_scale is already overwriting bits_, so it must own its pixels. The Windows
    // path below needs no equivalent, wxBitmap copies the bits into GDI.
    image = wxImage(size.GetWidth(), size.GetHeight(), bits_.data(), true).Copy();
    if (!image.IsOk()) {
        fprintf(stderr, "AVVideoDecoder: image not ok %dx%d\n", size.GetWidth(), size.GetHeight());
        return false;
    }
    return true;
}

bool AVVideoDecoder::toWxBitmap(wxBitmap &bitmap, wxSize const &size2)
{
    if (!got_frame_)
        return false;

    auto size1 = size2;
    if (!size1.IsFullySpecified())
        size1 = {frame_->width, frame_->height };
    auto size = size1;
    if (size.GetWidth() & 0x0f) {
        size.SetWidth((size.GetWidth() & ~0x0f) + 0x10);
        if (size.GetWidth() != width_) {
            std::fill(bits_.begin(), bits_.end(), 0);
            width_ = size.GetWidth();
        }
    }
    AVPixelFormat wxFmt = AV_PIX_FMT_RGB32;
    sws_ctx_ = sws_getCachedContext(sws_ctx_,
                                    frame_->width, frame_->height, AVPixelFormat(frame_->format),
                                    size1.GetWidth(), size1.GetHeight(), wxFmt,
                                    SWS_GAUSS,
                                    nullptr, nullptr, nullptr);
    if (sws_ctx_ == nullptr)
        return false;
    int length = size.GetWidth() * size.GetHeight() * 4;
    if (bits_.size() < length)
        bits_.resize(length);
    uint8_t *datas[]   = { bits_.data() };
    int      strides[] = { size.GetWidth() * 4 };
    int      result_h  = sws_scale(sws_ctx_, frame_->data, frame_->linesize, 0, frame_->height, datas, strides);
    if (result_h != size.GetHeight()) {
        fprintf(stderr, "AVVideoDecoder: result_h %d %d\n", result_h, size.GetHeight());
        return false;
    }
    bitmap = wxBitmap((char const *) bits_.data(), size.GetWidth(), size.GetHeight(), 32);
    assert(bitmap.IsOk());
    if (!bitmap.IsOk()) {
        fprintf(stderr, "AVVideoDecoder: bitmap not ok %dx%d\n", size.GetWidth(), size.GetHeight());
        return false;
    }
    return true;
}

wxMediaCtrl3::wxMediaCtrl3(wxWindow *parent)
    : wxWindow(parent, wxID_ANY)
    , BambuLib(StaticBambuLib::get(this))
    , m_thread([this] { PlayThread(); })
{
    SetBackgroundColour("#000001ff");
}

wxMediaCtrl3::~wxMediaCtrl3()
{
    {
        std::unique_lock<std::mutex> lk(m_mutex);
        m_url.reset(new wxURI);
        m_frame = wxImage(m_idle_image);
        m_cond.notify_all();
    }
    m_thread.join();
}

void wxMediaCtrl3::Load(wxURI url)
{
    std::unique_lock<std::mutex> lk(m_mutex);
    m_video_size = wxDefaultSize;
    m_error = 0;
    m_url.reset(new wxURI(url));
    m_cond.notify_all();
}

void wxMediaCtrl3::Play()
{
    std::unique_lock<std::mutex> lk(m_mutex);
    if (m_state != wxMEDIASTATE_PLAYING) {
        m_state = wxMEDIASTATE_PLAYING;
        wxMediaEvent event(wxEVT_MEDIA_STATECHANGED);
        event.SetId(GetId());
        event.SetEventObject(this);
        wxPostEvent(this, event);
    }
}

void wxMediaCtrl3::Stop()
{
    std::unique_lock<std::mutex> lk(m_mutex);
    m_url.reset();
    m_frame = wxImage(m_idle_image);
    NotifyStopped();
    m_cond.notify_all();
    Refresh();
}

void wxMediaCtrl3::SetIdleImage(wxString const &image)
{
    if (m_idle_image == image)
        return;
    m_idle_image = image;
    if (m_url == nullptr) {
        std::unique_lock<std::mutex> lk(m_mutex);
        m_frame = wxImage(m_idle_image);
        assert(m_frame.IsOk());
        Refresh();
    }
}

wxMediaState wxMediaCtrl3::GetState()
{
    std::unique_lock<std::mutex> lk(m_mutex);
    return m_state;
}

int wxMediaCtrl3::GetLastError()
{
    std::unique_lock<std::mutex> lk(m_mutex);
    return m_error;
}

wxSize wxMediaCtrl3::GetVideoSize()
{
    std::unique_lock<std::mutex> lk(m_mutex);
    return m_video_size;
}

static void adjust_frame_size(wxSize & frame, wxSize const & video, wxSize const & window)
{
    if (video.x * window.y < video.y * window.x)
        frame = { video.x * window.y / video.y, window.y };
    else
        frame = { window.x, video.y * window.x / video.x };
}

void wxMediaCtrl3::paintEvent(wxPaintEvent &evt)
{
    wxPaintDC dc(this);
    auto      size = GetSize();
    if (size.x <= 0 || size.y <= 0)
        return;
    std::unique_lock<std::mutex> lk(m_mutex);
    if (!m_frame.IsOk())
        return;
    auto size2 = m_frame.GetSize();
    if (size2.x != m_frame_size.x && size2.y == m_frame_size.y)
        size2.x = m_frame_size.x;
    auto size3 = (size - size2) / 2;
    if (size2.x != size.x && size2.y != size.y) {
        double scale = 1.;
        if (size.x * size2.y > size.y * size2.x) {
            size3 = {size.x * size2.y / size.y, size2.y};
            scale = double(size.y) / size2.y;
        } else {
            size3 = {size2.x, size.y * size2.x / size.x};
            scale = double(size.x) / size2.x;
        }
        dc.SetUserScale(scale, scale);
        size3 = (size3 - size2) / 2;
    }
    dc.DrawBitmap(m_frame, size3.x, size3.y);
}

void wxMediaCtrl3::DoSetSize(int x, int y, int width, int height, int sizeFlags)
{
    wxWindow::DoSetSize(x, y, width, height, sizeFlags);
    if (sizeFlags == wxSIZE_USE_EXISTING) return;
    wxMediaCtrl_OnSize(this, m_video_size, width, height);
    std::unique_lock<std::mutex> lk(m_mutex);
    adjust_frame_size(m_frame_size, m_video_size, GetSize());
    Refresh();
}

void wxMediaCtrl3::bambu_log(void *ctx, int level, tchar const *msg2)
{
#ifdef _WIN32
    wxString msg(msg2);
#else
    wxString msg = wxString::FromUTF8(msg2);
#endif
    if (level == 1) {
        if (msg.EndsWith("]")) {
            int n = msg.find_last_of('[');
            if (n != wxString::npos) {
                long val = 0;
                wxMediaCtrl3 *ctrl = (wxMediaCtrl3 *) ctx;
                if (msg.SubString(n + 1, msg.Length() - 2).ToLong(&val)) {
                    std::unique_lock<std::mutex> lk(ctrl->m_mutex);
                    ctrl->m_error = (int) val;
                }
            }
        } else if (msg.Contains("stat_log")) {
            wxCommandEvent evt(EVT_MEDIA_CTRL_STAT);
            wxMediaCtrl3 *ctrl = (wxMediaCtrl3 *) ctx;
            evt.SetEventObject(ctrl);
            evt.SetString(msg.Mid(msg.Find(' ') + 1));
            wxPostEvent(ctrl, evt);
        }
    }
    BOOST_LOG_TRIVIAL(info) << msg.ToUTF8().data();
}

void wxMediaCtrl3::PlayThread()
{
    using namespace std::chrono_literals;
    std::shared_ptr<wxURI> url;
    std::unique_lock<std::mutex> lk(m_mutex);
    while (true) {
        m_cond.wait(lk, [this, &url] { return m_url != url; });
        url = m_url;
        if (url == nullptr)
            continue;
        if (!url->HasScheme())
            break;
        lk.unlock();
        Bambu_Tunnel tunnel = nullptr;
        int error = Bambu_Create(&tunnel, m_url->BuildURI().ToUTF8());
        if (error == 0) {
            Bambu_SetLogger(tunnel, &wxMediaCtrl3::bambu_log, this);
            error = Bambu_Open(tunnel);
            if (error == 0)
                error = Bambu_would_block;
        }
        lk.lock();
        while (error == int(Bambu_would_block)) {
            m_cond.wait_for(lk, 100ms);
            if (m_url != url) {
                error = 1;
                break;
            }
            lk.unlock();
            error = Bambu_StartStream(tunnel, true);
            lk.lock();
        }
        Bambu_StreamInfo info;
        if (error == 0)
            error = Bambu_GetStreamInfo(tunnel, 0, &info);
        AVVideoDecoder decoder;
        int minFrameDuration = 0;
        if (error == 0) {
            decoder.open(info);
            m_video_size = { info.format.video.width, info.format.video.height };
            adjust_frame_size(m_frame_size, m_video_size, GetSize());
            minFrameDuration = 800 / info.format.video.frame_rate; // 80%
            NotifyStopped();
        }
        Bambu_Sample sample;
        while (error == 0) {
            lk.unlock();
            error = Bambu_ReadSample(tunnel, &sample);
            lk.lock();
            while (error == int(Bambu_would_block)) {
                m_cond.wait_for(lk, 100ms);
                if (m_url != url) {
                    error = 1;
                    break;
                }
                lk.unlock();
                error = Bambu_ReadSample(tunnel, &sample);
                lk.lock();
            }
            if (error == 0) {
                auto frame_size = m_frame_size;
                lk.unlock();
                decoder.decode(sample);
#ifdef _WIN32
                wxBitmap bm;
                decoder.toWxBitmap(bm, frame_size);
#else
                wxImage bm;
                decoder.toWxImage(bm, frame_size);
#endif
                lk.lock();
                if (m_url != url) {
                    error = 1;
                    break;
                }
                if (bm.IsOk()) {
                    auto now = std::chrono::system_clock::now();
                    if (m_last_PTS && (sample.decode_time - m_last_PTS) < 30000000ULL) { // 3s
                        auto next_PTS_expected = m_last_PTS_expected + std::chrono::milliseconds((sample.decode_time - m_last_PTS) / 10000ULL);
                        // The frame is late, catch up a little
                        auto next_PTS_practical = m_last_PTS_practical + std::chrono::milliseconds(minFrameDuration);
                        auto next_PTS = std::max(next_PTS_expected, next_PTS_practical);
                        if(now < next_PTS)
                            std::this_thread::sleep_until(next_PTS);
                        else
                            next_PTS = now;
                        //auto text = wxString::Format(L"wxMediaCtrl3 pts diff %ld\n", std::chrono::duration_cast<std::chrono::milliseconds>(next_PTS - next_PTS_expected).count());
                        //OutputDebugString(text);
                        m_last_PTS = sample.decode_time;
                        m_last_PTS_expected = next_PTS_expected;
                        m_last_PTS_practical = next_PTS;
                    } else {
                        // Resync
                        m_last_PTS           = sample.decode_time;
                        m_last_PTS_expected  = now;
                        m_last_PTS_practical = now;
                    }
                    m_frame = bm;
                }
                CallAfter([this] { Refresh(); });
            }
        }
        if (tunnel) {
            lk.unlock();
            Bambu_Close(tunnel);
            Bambu_Destroy(tunnel);
            tunnel = nullptr;
            lk.lock();
        }
        if (m_url == url)
            m_error = error;
        m_frame_size = wxDefaultSize;
        m_video_size = wxDefaultSize;
        NotifyStopped();
    }

}

void wxMediaCtrl3::NotifyStopped()
{
    m_state = wxMEDIASTATE_STOPPED;
    wxMediaEvent event(wxEVT_MEDIA_STATECHANGED);
    event.SetId(GetId());
    event.SetEventObject(this);
    wxPostEvent(this, event);
}

std::vector<double> outer_wall_feed_rates(const std::string& gcode, KeepLine keep_line)
{
    std::vector<double> feed_rates;
    bool outer_wall = false;
    GCodeReader parser;
    parser.parse_buffer(gcode, [&feed_rates, &outer_wall, &keep_line](GCodeReader& self, const GCodeReader::GCodeLine& line) {
        const std::string_view comment = line.comment();
        if (comment.find("FEATURE:") != std::string_view::npos || comment.find("TYPE:") != std::string_view::npos)
            outer_wall = comment.find("Outer wall") != std::string_view::npos ||
                         comment.find("External perimeter") != std::string_view::npos;

        if (outer_wall && line.extruding(self) && line.dist_XY(self) > 1.0 && keep_line(self, line))
            feed_rates.push_back(line.new_F(self));
    });

    return feed_rates;
}

std::vector<double> caged_slope_feed_rates(const std::string& gcode)
{
    return outer_wall_feed_rates(gcode, [](const GCodeReader& self, const GCodeReader::GCodeLine& line) {
        const double z = line.new_Z(self);
        return z > caged_span_z_min && z < caged_slope_z_max &&
               line.dist_XY(self) > 0.5 * caged_slope_span &&
               std::abs(self.y() + z - caged_slope_wall_sum) < caged_wall_tolerance &&
               std::abs(line.new_Y(self) + z - caged_slope_wall_sum) < caged_wall_tolerance;
    });
}

std::vector<double> back_wall_feed_rates(const std::string& gcode)
{
    return outer_wall_feed_rates(gcode, [](const GCodeReader& self, const GCodeReader::GCodeLine& line) {
        return line.new_Z(self) > 1.5 * caged_layer_height &&
               std::abs(self.y() - caged_back_wall_y) < caged_wall_tolerance &&
               std::abs(line.new_Y(self) - caged_back_wall_y) < caged_wall_tolerance;
    });
}

std::vector<double> cage_shoulder_feed_rates(const std::string& gcode)
{
    return outer_wall_feed_rates(gcode, [](const GCodeReader& self, const GCodeReader::GCodeLine& line) {
        return std::abs(line.new_Z(self) - caged_layer_above_slope_z) < 0.5 * caged_layer_height &&
               std::abs(self.y() - caged_front_wall_y) < caged_wall_tolerance &&
               std::abs(line.new_Y(self) - caged_front_wall_y) < caged_wall_tolerance &&
               (std::max(self.x(), line.new_X(self)) <= caged_slope_x_min ||
                std::min(self.x(), line.new_X(self)) >= caged_slope_x_max);
    });
}

std::vector<ExtendedPoint<2>> sampled_wall_over_dished_layer(const std::function<float(float)>& distance_to_speed)
{
    const AABBTreeLines::LinesDistancer<Linef> prev_layer(std::vector<Linef>{
        {{0., 0.}, {20., -dished_layer_depth}},
        {{20., -dished_layer_depth}, {40., 0.}},
        {{40., 0.}, {40., -10.}},
        {{40., -10.}, {0., -10.}},
        {{0., -10.}, {0., 0.}},
    });
    const Points wall{Point::new_scale(0., dished_wall_gap), Point::new_scale(40., dished_wall_gap)};

    return estimate_points_properties<true, true, true, true>(wall, prev_layer, caged_wall_width, -1.f,
                                                              dished_min_distance, distance_to_speed);
}

std::vector<ExtendedPoint<2>> sampled_wall_over_narrow_pocket(
    double pocket_center, const std::function<float(float)>& distance_to_speed)
{
    const double pocket_left  = pocket_center - 0.5 * narrow_pocket_width;
    const double pocket_right = pocket_center + 0.5 * narrow_pocket_width;
    const AABBTreeLines::LinesDistancer<Linef> prev_layer(std::vector<Linef>{
        {{0., 0.}, {pocket_left, 0.}},
        {{pocket_left, 0.}, {pocket_left, -narrow_pocket_depth}},
        {{pocket_left, -narrow_pocket_depth}, {pocket_right, -narrow_pocket_depth}},
        {{pocket_right, -narrow_pocket_depth}, {pocket_right, 0.}},
        {{pocket_right, 0.}, {narrow_pocket_wall_length, 0.}},
        {{narrow_pocket_wall_length, 0.}, {narrow_pocket_wall_length, -10.}},
        {{narrow_pocket_wall_length, -10.}, {0., -10.}},
        {{0., -10.}, {0., 0.}},
    });
    const double wall_y = -0.5 * caged_wall_width;
    const Points wall{Point::new_scale(0., wall_y), Point::new_scale(narrow_pocket_wall_length, wall_y)};

    return estimate_points_properties<true, true, true, true>(wall, prev_layer, caged_wall_width, -1.f,
                                                               dished_min_distance, distance_to_speed);
}

std::vector<ExtendedPoint<2>> sampled_wall_between_growing_corners(const std::function<float(float)>& distance_to_speed)
{
    const AABBTreeLines::LinesDistancer<Linef> prev_layer(std::vector<Linef>{
        {{0., 0.}, {32., 0.}},
        {{32., 0.}, {32., -stepped_wall_span}},
        {{32., -stepped_wall_span}, {0., -stepped_wall_span}},
        {{0., -stepped_wall_span}, {0., 0.}},
    });
    const Points wall{Point::new_scale(stepped_wall_inset, -stepped_end_gap),
                      Point::new_scale(stepped_wall_inset, stepped_end_gap - stepped_wall_span)};

    return estimate_points_properties<true, true, true, true>(wall, prev_layer, caged_wall_width, -1.f,
                                                              dished_min_distance, distance_to_speed);
}

double slowed_length(const std::vector<ExtendedPoint<2>>& points, const std::function<float(float)>& distance_to_speed)
{
    double length = 0.;
    for (size_t i = 0; i + 1 < points.size(); ++i)
        if (std::min(distance_to_speed(points[i].distance), distance_to_speed(points[i + 1].distance)) < distance_to_speed(0.f))
            length += (points[i + 1].position - points[i].position).norm();
    return length;
}

float furthest_reading(const std::vector<ExtendedPoint<2>>& points)
{
    return std::max_element(points.begin(), points.end(), [](const ExtendedPoint<2>& l, const ExtendedPoint<2>& r) {
               return l.distance < r.distance;
           })->distance;
}

std::string caged_overhang_gcode(const char* wall_generator)
{
    Print print;
    Model model;
    init_print(std::vector<TriangleMesh>{caged_overhang_mesh()}, print, model, caged_overhang_config(wall_generator), nullptr,
               false);
    return gcode(print);
}

void info_feed_rates(const char* span, const std::vector<double>& feed_rates)
{
    UNSCOPED_INFO("matched " << feed_rates.size() << " " << span << " moves");
    if (!feed_rates.empty()) {
        const auto extremes = std::minmax_element(feed_rates.begin(), feed_rates.end());
        UNSCOPED_INFO("slowest " << *extremes.first / MM_PER_MIN << " mm/s, fastest " << *extremes.second / MM_PER_MIN << " mm/s");
    }
}

static bool has_zero_flush_volume_for_used_filaments(const std::vector<T> &fv_matrix,
                                                      const std::vector<T> &flush_multipliers,
                                                      const std::vector<int> &used_filaments)
{
    if (used_filaments.size() < 2 || flush_multipliers.empty())
        return false;

    if (fv_matrix.size() % flush_multipliers.size() != 0)
        return false;

    const size_t matrix_len = fv_matrix.size() / flush_multipliers.size();
    const size_t row_len    = size_t(std::sqrt(double(matrix_len)));
    if (row_len < 2 || row_len * row_len != matrix_len)
        return false;

    std::vector<int> filtered_filaments;
    filtered_filaments.reserve(used_filaments.size());
    for (int filament_id : used_filaments) {
        if (filament_id <= 0 || filament_id > int(row_len))
            continue;
        if (std::find(filtered_filaments.begin(), filtered_filaments.end(), filament_id) == filtered_filaments.end())
            filtered_filaments.push_back(filament_id);
    }
    if (filtered_filaments.size() < 2)
        return false;

    for (T multiplier : flush_multipliers) {
        if (multiplier == 0)
            return true;
    }

    for (size_t nozzle_idx = 0; nozzle_idx < flush_multipliers.size(); nozzle_idx++) {
        const size_t block_offset = nozzle_idx * matrix_len;
        for (int from_id : filtered_filaments) {
            for (int to_id : filtered_filaments) {
                if (from_id == to_id)
                    continue;

                const size_t matrix_idx = block_offset + size_t(from_id - 1) * row_len + size_t(to_id - 1);
                if (matrix_idx < fv_matrix.size() && fv_matrix[matrix_idx] == 0)
                    return true;
            }
        }
    }

    return false;
}

void ConfigManipulation::layer_height_limits(double& min_layer_height, double& max_layer_height) const
{
    const DynamicPrintConfig& printer_config = GUI::wxGetApp().preset_bundle->printers.get_edited_preset().config;
    const std::vector<double>& min_limits = printer_config.option<ConfigOptionFloats>("min_layer_height")->values;
    const std::vector<double>& max_limits = printer_config.option<ConfigOptionFloats>("max_layer_height")->values;
    min_layer_height = *std::min_element(min_limits.begin(), min_limits.end());
    max_layer_height = *std::max_element(max_limits.begin(), max_limits.end());
}

bool ConfigManipulation::check_layer_height(DynamicPrintConfig* config)
{
    double min_layer_height = 0., max_layer_height = 0.;
    layer_height_limits(min_layer_height, max_layer_height);
    const double layer_height = config->opt_float("layer_height");

    if (min_layer_height > EPSILON && layer_height < EPSILON) {
        const wxString msg_text = wxString::Format(_L("Layer height is too small. It will be set to the minimum (%g mm)."), min_layer_height);
        MessageDialog dialog(wxGetApp().plater(), msg_text, "", wxICON_WARNING | wxOK);
        dialog.SetButtonLabel(wxID_OK, _L("OK"));
        is_msg_dlg_already_exist = true;
        dialog.ShowModal();
        is_msg_dlg_already_exist = false;
        DynamicPrintConfig new_conf = *config;
        new_conf.set_key_value("layer_height", new ConfigOptionFloat(min_layer_height));
        apply(config, &new_conf);
        return true;
    }
    if (max_layer_height > EPSILON && layer_height > max_layer_height + EPSILON)
        return layer_height_out_of_range_dialog(config, max_layer_height);
    if (min_layer_height > EPSILON && layer_height < min_layer_height - EPSILON)
        return layer_height_out_of_range_dialog(config, min_layer_height);
    return false;
}

bool ConfigManipulation::layer_height_out_of_range_dialog(DynamicPrintConfig* config, double clamp_to)
{
    wxString msg_text = _(L("Layer height is outside the limits set in Printer Settings -> Extruder -> Layer height limits, "
                            "this may cause printing quality issues."));
    msg_text += "\n\n" + wxString::Format(_L("Adjust it to the limit (%g mm) automatically?"), clamp_to);
    MessageDialog dialog(wxGetApp().plater(), msg_text, "", wxICON_WARNING | wxYES | wxNO);
    dialog.SetButtonLabel(wxID_YES, _L("Adjust"));
    dialog.SetButtonLabel(wxID_NO, _L("Ignore"));
    is_msg_dlg_already_exist = true;
    const bool adjust = dialog.ShowModal() == wxID_YES;
    if (adjust) {
        DynamicPrintConfig new_conf = *config;
        new_conf.set_key_value("layer_height", new ConfigOptionFloat(clamp_to));
        apply(config, &new_conf);
    }
    is_msg_dlg_already_exist = false;
    return adjust;
}

kml::MarkId FindTrackSelectionMark(BookmarkManager const & bm, kml::TrackId trackId)
{
  for (auto markId : bm.GetUserMarkIds(UserMark::Type::TRACK_SELECTION))
    if (bm.GetMark<TrackSelectionMark>(markId)->GetTrackId() == trackId)
      return markId;
  return kml::kInvalidMarkId;
}

void TapUserMark(Framework & fm, kml::MarkId markId)
{
  place_page::BuildInfo buildInfo;
  buildInfo.m_source = place_page::BuildInfo::Source::User;
  buildInfo.m_mercator = kTrackPoint;
  buildInfo.m_userMarkId = markId;
  fm.BuildAndSetPlacePageInfo(buildInfo);
}

UNIT_CLASS_TEST(Runner, Bookmarks_ClearTempRelationTrackDeletesSelectionMark)
{
  BookmarkManager bmManager(BM_CALLBACKS);
  bmManager.EnableTestMode(true);

  TEST_EQUAL(bmManager.SetTempRelationTrack(MakeLineTrackData()), kml::kTempRelationTrackId, ());
  bmManager.SetTrackSelectionInfo({kml::kTempRelationTrackId, kTrackPoint, kTrackDistance},
                                  false /* notifyListeners */);
  TEST_EQUAL(selectionInfo.m_distFromBegM, kTrackDistance, ());
// A selection mark stores the track id only, so a tap on the mark of the current temp relation track
// comes back without a relation id and can't be rebuilt from it. Such a tap must reuse the already
// built track instead of clearing it - it used to leave BuildTrackPlacePage with a null Track.
UNIT_TEST(Bookmarks_TapSelectionMarkOfTempRelationTrack)
{
  ScopedBookmarksDir scopedDir;
  Framework fm(kFrameworkParams);
  df::VisualParams::Init(1.0, 1024);

  auto & bmManager = fm.GetBookmarkManager();
  bmManager.EnableTestMode(true);

  TEST_EQUAL(bmManager.SetTempRelationTrack(MakeLineTrackData()), kml::kTempRelationTrackId, ());
  bmManager.SetTrackSelectionInfo({kml::kTempRelationTrackId, kTrackPoint, kTrackDistance},
                                  false /* notifyListeners */);

  auto const markId = FindTrackSelectionMark(bmManager, kml::kTempRelationTrackId);
  TEST_NOT_EQUAL(markId, kml::kInvalidMarkId, ());

  TapUserMark(fm, markId);

  TEST_NOT_EQUAL(bmManager.GetTrack(kml::kTempRelationTrackId), nullptr, ("The tapped track was cleared"));
  TEST(fm.HasPlacePageInfo(), ());
  auto const & info = fm.GetCurrentPlacePageInfo();
  TEST(info.IsRelationTrack(), ());
  TEST_EQUAL(info.GetSelectedObject(), df::SelectionShape::OBJECT_TRACK, ());
}

// The counterpart: selecting any other track still drops the temp relation track.
UNIT_TEST(Bookmarks_TapSelectionMarkClearsTempRelationTrack)
{
  ScopedBookmarksDir scopedDir;
  Framework fm(kFrameworkParams);
  df::VisualParams::Init(1.0, 1024);

  auto & bmManager = fm.GetBookmarkManager();
  bmManager.EnableTestMode(true);

  auto const catId = bmManager.CreateBookmarkCategory("cat", false /* autoSave */);
  kml::TrackId trackId;
  {
    auto es = bmManager.GetEditSession();
    trackId = es.CreateTrack(MakeLineTrackData())->GetId();
    es.AttachTrack(trackId, catId);
  }
  bmManager.SetTrackSelectionInfo({trackId, kTrackPoint, kTrackDistance}, false /* notifyListeners */);
  TEST_EQUAL(bmManager.SetTempRelationTrack(MakeLineTrackData()), kml::kTempRelationTrackId, ());

  auto const markId = FindTrackSelectionMark(bmManager, trackId);
  TEST_NOT_EQUAL(markId, kml::kInvalidMarkId, ());

  TapUserMark(fm, markId);

  TEST_EQUAL(bmManager.GetTrack(kml::kTempRelationTrackId), nullptr, ());
  TEST(fm.HasPlacePageInfo(), ());
  TEST_EQUAL(fm.GetCurrentPlacePageInfo().GetTrackId(), trackId, ());
}

