        m_hdrTransfer = transfer;
        emit hdrTransferModeChanged();
        if (m_hdrTransfer == HdrTransfer::SDR && !qFuzzyCompare(m_hdrGain, 1.0f)) {
            m_hdrGain = 1.0f;
            emit hdrGainChanged();
        }
    }
