static const EngravingItem* topLayoutAncestor(const EngravingItem* item)
    {
        constexpr int MAX_DEPTH = 32;

        const EngravingItem* top = item;
        for (int depth = 0; depth < MAX_DEPTH; ++depth) {
            const EngravingItem* parent = top->layoutParent();
            if (!parent) {
                return top;
            }
            top = parent;
        }

        return nullptr;
    }

TEST_F(Engraving_ParentTests, newItemIsNotAttached)
{
    Segment* segment = someSegment();
    ASSERT_TRUE(segment);

    Dynamic* dynamic = Factory::createDynamic(segment, false /*isAccessibleEnabled*/);

    EXPECT_EQ(dynamic->score(), m_score);

    EXPECT_EQ(dynamic->parent(), segment);
    EXPECT_TRUE(isChildOf(dynamic, segment));

    EXPECT_EQ(dynamic->ownershipParent(), nullptr);
    EXPECT_EQ(dynamic->ownershipParentItem(), nullptr);
    EXPECT_EQ(dynamic->layoutParent(), nullptr);

    delete dynamic;
}

TEST_F(Engraving_ParentTests, attachingAndDetaching)
{
    Segment* segment = someSegment();
    ASSERT_TRUE(segment);

    Dynamic* dynamic = Factory::createDynamic(segment, false /*isAccessibleEnabled*/);

    dynamic->setOwnershipParent(segment);

    EXPECT_EQ(dynamic->parent(), segment);
    EXPECT_EQ(dynamic->ownershipParent(), segment);
    EXPECT_EQ(dynamic->ownershipParentItem(), segment);
    EXPECT_EQ(dynamic->layoutParent(), segment);
    EXPECT_TRUE(isChildOf(dynamic, segment));
    EXPECT_FALSE(isChildOf(dynamic, m_score->dummy()));

    dynamic->moveToDummy();

    EXPECT_EQ(dynamic->parent(), m_score->dummy());
    EXPECT_EQ(dynamic->ownershipParent(), nullptr);
    EXPECT_EQ(dynamic->ownershipParentItem(), nullptr);
    EXPECT_EQ(dynamic->layoutParent(), nullptr);
    EXPECT_TRUE(isChildOf(dynamic, m_score->dummy()));
    EXPECT_FALSE(isChildOf(dynamic, segment));

    delete dynamic;
}

TEST_F(Engraving_ParentTests, deletingOwnerParksChildrenOnDummy)
{
    Segment* segment = someSegment();
    ASSERT_TRUE(segment);

    Chord* chord = Factory::createChord(segment, false /*isAccessibleEnabled*/);
    Note* note = Factory::createNote(chord, false /*isAccessibleEnabled*/);
    note->setOwnershipParent(chord);
    ASSERT_EQ(note->ownershipParent(), chord);

    delete chord;

    EXPECT_EQ(note->parent(), m_score->dummy());
    EXPECT_EQ(note->ownershipParent(), nullptr);

    delete note;
}

TEST_F(Engraving_ParentTests, accessibleParentFallsBackToTheDummy)
{
    Segment* segment = someSegment();
    ASSERT_TRUE(segment);

    Dynamic* dynamic = Factory::createDynamic(segment, false /*isAccessibleEnabled*/);

    dynamic->setOwnershipParent(segment);
    EXPECT_EQ(dynamic->accessibleParentItem(), segment);

    dynamic->moveToDummy();

    EXPECT_EQ(dynamic->layoutParent(), nullptr);
    EXPECT_EQ(dynamic->accessibleParentItem(), m_score->dummy());

    delete dynamic;
}

TEST_F(Engraving_ParentTests, pagesSystemsAndMeasuresAreOwnedByTheScore)
{
    ASSERT_FALSE(m_score->pages().empty());

    Page* page = m_score->pages().front();
    ASSERT_FALSE(page->systems().empty());
    System* system = page->systems().front();
    ASSERT_FALSE(system->measures().empty());
    MeasureBase* measure = system->measures().front();

    // the score is not an EngravingItem, so it is an owner but never a layout parent
    EXPECT_EQ(page->ownershipParent(), m_score);
    EXPECT_EQ(page->ownershipParentItem(), nullptr);
    EXPECT_EQ(page->layoutParent(), nullptr);

    EXPECT_EQ(system->ownershipParent(), m_score);
    EXPECT_EQ(system->ownershipParentItem(), nullptr);
    EXPECT_EQ(system->page(), page);
    EXPECT_EQ(system->layoutParent(), page);

    EXPECT_EQ(measure->ownershipParent(), m_score);
    EXPECT_EQ(measure->ownershipParentItem(), nullptr);
    EXPECT_EQ(measure->system(), system);
    EXPECT_EQ(measure->layoutParent(), system);

    // positions accumulate along the placement chain, not the ownership one
    EXPECT_EQ(page->pagePos(), page->pos());
    EXPECT_EQ(system->pagePos(), system->pos());
    EXPECT_EQ(measure->pagePos(), measure->pos() + system->pos());
    EXPECT_EQ(measure->canvasPos(), measure->pagePos() + page->pos());
}

TEST_F(Engraving_ParentTests, layoutParentDefaultsToTheOwner)
{
    Measure* measure = m_score->firstMeasure();
    ASSERT_TRUE(measure);
    Segment* segment = measure->first(SegmentType::ChordRest);
    ASSERT_TRUE(segment);
    ASSERT_TRUE(segment->element(0) && segment->element(0)->isChord());
    Chord* chord = toChord(segment->element(0));
    Note* note = chord->notes().front();

    EXPECT_EQ(note->ownershipParentItem(), chord);
    EXPECT_EQ(note->layoutParent(), chord);

    EXPECT_EQ(chord->ownershipParentItem(), segment);
    EXPECT_EQ(chord->layoutParent(), segment);

    EXPECT_EQ(segment->ownershipParentItem(), measure);
    EXPECT_EQ(segment->layoutParent(), measure);
}

TEST_F(Engraving_ParentTests, spannerSegmentIsOwnedBySpannerAndPlacedOnSystem)
{
    Hairpin* hairpin = nullptr;
    for (const auto& pair : m_score->spanner()) {
        if (pair.second->isHairpin()) {
            hairpin = toHairpin(pair.second);
            break;
        }
    }
    ASSERT_TRUE(hairpin);
    ASSERT_FALSE(hairpin->spannerSegments().empty());

    SpannerSegment* spannerSegment = hairpin->frontSegment();
    ASSERT_TRUE(spannerSegment->system());

    EXPECT_EQ(spannerSegment->ownershipParent(), hairpin);
    EXPECT_EQ(spannerSegment->ownershipParentItem(), hairpin);
    EXPECT_EQ(spannerSegment->layoutParent(), spannerSegment->system());
    EXPECT_NE(spannerSegment->layoutParent(), spannerSegment->ownershipParentItem());
}

TEST_F(Engraving_ParentTests, deletingASegmentUnplacesItFromItsSystem)
{
    ASSERT_FALSE(m_score->systems().empty());
    System* system = m_score->systems().front();

    Hairpin* hairpin = Factory::createHairpin(m_score->dummy()->segment());
    hairpin->setTrack(0);
    hairpin->setTrack2(0);

    // placed on the system, but not handed to the spanner, so that deleting it does
    // not go through Spanner::eraseSpannerSegments() unplacing it first
    SpannerSegment* segment = hairpin->createLineSegment();
    segment->moveToSystem(system);
    ASSERT_TRUE(muse::contains(system->spannerSegments(), segment));

    delete segment;

    EXPECT_FALSE(muse::contains(system->spannerSegments(), segment));

    delete hairpin;
}

TEST_F(Engraving_ParentTests, deletingASpannerDeletesItsSegments)
{
    const size_t dummyChildrenBefore = m_score->dummy()->children().size();

    Hairpin* hairpin = Factory::createHairpin(m_score->dummy()->segment());
    hairpin->setTrack(0);
    hairpin->setTrack2(0);

    SpannerSegment* segment = hairpin->createLineSegment();
    hairpin->add(segment);
    ASSERT_EQ(segment->ownershipParent(), hairpin);

    delete hairpin;

    // the segment is gone with its spanner, rather than parked on the dummy
    EXPECT_EQ(m_score->dummy()->children().size(), dummyChildrenBefore);
}

TEST_F(Engraving_ParentTests, beamIsPlacedOnTheSystemOfItsElements)
{
    Beam* beam = nullptr;
    for (Measure* measure = m_score->firstMeasure(); measure && !beam; measure = measure->nextMeasure()) {
        for (Segment& segment : measure->segments()) {
            if (!segment.isChordRestType()) {
                continue;
            }
            for (EngravingItem* item : segment.elist()) {
                if (item && item->isChordRest() && toChordRest(item)->beam()) {
                    beam = toChordRest(item)->beam();
                    break;
                }
            }
            if (beam) {
                break;
            }
        }
    }
    ASSERT_TRUE(beam);
    ASSERT_FALSE(beam->elements().empty());

    System* system = beam->elements().front()->measure()->system();
    ASSERT_TRUE(system);

    EXPECT_EQ(beam->layoutParent(), system);
    EXPECT_NE(beam->layoutParent(), beam->ownershipParentItem());
}

TEST_F(Engraving_ParentTests, nestedFrameIsPlacedWithinItsOwner)
{
    VBox* vbox = Factory::createVBox(m_score, false /*isAccessibleEnabled*/);
    HBox* hbox = Factory::createHBox(m_score, false /*isAccessibleEnabled*/);
    hbox->setOwnershipParent(vbox);

    ASSERT_EQ(hbox->system(), nullptr);
    EXPECT_EQ(hbox->ownershipParentItem(), vbox);
    EXPECT_EQ(hbox->layoutParent(), vbox);

    delete hbox;
    delete vbox;
}

TEST_F(Engraving_ParentTests, everyLaidOutItemReachesItsPage)
{
    std::vector<const EngravingItem*> unreachable;
    size_t checkedItems = 0;

    m_score->scanElements([&](EngravingItem* item) {
        if (!item->layoutParent() && !item->isPage()) {
            // not placed anywhere; nothing to verify
            return;
        }

        ++checkedItems;

        const EngravingItem* top = topLayoutAncestor(item);
        if (!top || !top->isPage() || !muse::contains(m_score->pages(), const_cast<Page*>(toPage(top)))) {
            unreachable.push_back(item);
            return;
        }

        // findAncestor() walks the same chain and must agree
        EXPECT_EQ(item->findAncestor(ElementType::PAGE), top) << item->typeName();

        // pageX() stops one step below the page, canvasX() does not
        EXPECT_DOUBLE_EQ(item->canvasX() - item->pageX(), top->x()) << item->typeName();
    });

    for (const EngravingItem* item : unreachable) {
        ADD_FAILURE() << item->typeName() << " does not reach a page through layoutParent()";
    }

    EXPECT_GT(checkedItems, 0u);
}

TEST_F(Engraving_ParentTests, ancestorWalksAgreeWithAttachment)
{
    size_t checkedChordRests = 0;

    for (Measure* measure = m_score->firstMeasure(); measure; measure = measure->nextMeasure()) {
        EXPECT_EQ(measure->findMeasure(), measure);

        for (Segment& segment : measure->segments()) {
            if (!segment.isChordRestType()) {
                continue;
            }

            for (EngravingItem* item : segment.elist()) {
                if (!item || !item->isChordRest()) {
                    continue;
                }

                ChordRest* chordRest = toChordRest(item);
                EXPECT_EQ(chordRest->tick(), segment.tick());
                EXPECT_EQ(chordRest->rtick(), segment.rtick());
                EXPECT_EQ(chordRest->findMeasure(), measure);
                EXPECT_EQ(chordRest->findAncestor(ElementType::SEGMENT), &segment);
                ++checkedChordRests;

                if (!chordRest->isChord()) {
                    continue;
                }

                for (Note* note : toChord(chordRest)->notes()) {
                    // a note has no tick of its own; it must find its segment's
                    EXPECT_EQ(note->tick(), segment.tick());
                    EXPECT_EQ(note->findMeasure(), measure);
                }
            }
        }
    }

    EXPECT_GT(checkedChordRests, 0u);
}

TEST_F(Engraving_ParentTests, accessibilityTreeAgreesInBothDirections)
{
    auto lists = [](const EngravingItem* parent, const EngravingItem* item) {
        return muse::contains(parent->accessibleChildren(), const_cast<EngravingItem*>(item));
    };

    // Upwards: whoever an item names must list it back
    size_t checkedItems = 0;

    auto checkNamedParent = [&](const EngravingItem* item) {
        const EngravingItem* parent = item->accessibleParentItem();
        if (!parent) {
            // nothing to disagree with
            return;
        }

        ++checkedItems;
        EXPECT_TRUE(lists(parent, item))
            << item->typeName() << " is not listed by the " << parent->typeName()
            << " it names as its accessibility parent";
    };

    m_score->scanElements([&](EngravingItem* item) { checkNamedParent(item); });

    // scanElements() visits what is laid out on the score, not the structure it is laid
    // out on, so walk that separately - it is where ownership and placement diverge
    for (const Page* page : m_score->pages()) {
        checkNamedParent(page);

        for (const System* system : page->systems()) {
            checkNamedParent(system);

            for (const MeasureBase* measure : system->measures()) {
                checkNamedParent(measure);
            }
        }
    }

    EXPECT_GT(checkedItems, 0u);

    // Downwards: whatever a parent lists must name it back. This is the direction a
    // screen reader descends, starting from the root item.
    constexpr int MAX_DEPTH = 64;
    size_t checkedChildren = 0;

    std::function<void(const EngravingItem*, int)> checkChildren = [&](const EngravingItem* parent, int depth) {
        ASSERT_LT(depth, MAX_DEPTH) << "the accessibility tree is too deep, or contains a cycle";

        for (const EngravingItem* child : parent->accessibleChildren()) {
            ++checkedChildren;
            EXPECT_EQ(child->accessibleParentItem(), parent)
                << parent->typeName() << " lists a " << child->typeName() << " that names another parent";

            checkChildren(child, depth + 1);
        }
    };

    checkChildren(m_score->rootItem(), 0);

    EXPECT_GT(checkedChildren, 0u);
}

EngravingItem* EngravingItem::parentItem() const
{
    EngravingObject* p = explicitParent();
    if (p && p->isEngravingItem()) {
        return toEngravingItem(p);
    }

    return nullptr;
}

EngravingItem* Beam::accessibleParentItem() const
{
    // The system a beam is drawn on does not own it and cannot list it, so in the
    // accessibility tree the beam stays where it is parked: on the dummy.
    EngravingObject* parent = this->parent();

    return parent && parent->isEngravingItem() ? toEngravingItem(parent) : nullptr;
}

Spanner::~Spanner()
{
    // A spanner owns its segments (they are its DOM children), so it has to free
    // them. Without this they would only be unparented onto the dummy, where they
    // would sit until the score is destroyed - with a dangling spanner() pointer.
    eraseSpannerSegments();
}

::~SpannerSegment()
{
    // A system only places a segment, so it holds a plain back-reference to it: take
    // that reference with us, rather than relying on every deletion site to do it.
    moveToSystem(nullptr);
}

Spanner* SpannerSegment::setSpanner(Spanner* val)
{
    m_spanner = val;
    setParent(val);
    return m_spanner;
}

EngravingItemList Spanner::accessibleChildren() const
{
    // A segment that is placed on a system belongs to that system in the accessibility
    // tree, even though this spanner is what owns it.
    EngravingItemList children = EngravingItem::accessibleChildren();
    muse::remove_if(children, [](EngravingItem* item) {
        return item->isSpannerSegment() && toSpannerSegment(item)->system();
    });

    return children;
}

EngravingItem* Page::layoutParent() const
{
    // A page is the top of the visual hierarchy: it is not laid out inside anything.
    return nullptr;
}

EngravingItem* Page::accessibleParentItem() const
{
    // Above the visual hierarchy sits the root item, which exists only to head the
    // accessibility tree. (The dummy's page hangs off the dummy's own root item, which
    // the base implementation finds as its raw parent.)
    EngravingItem* parent = EngravingItem::accessibleParentItem();

    return parent ? parent : score()->rootItem();
}

EngravingItemList RootItem::accessibleChildren() const
{
    EngravingItemList children = EngravingItem::accessibleChildren();

    if (this == score()->rootItem()) {
        // The pages are owned by the score, but this is the top of the accessibility
        // tree, so this is where they are listed. (The dummy has a root item of its
        // own, which heads the tree of the items parked on it and has no pages.)
        children.insert(children.end(), score()->pages().begin(), score()->pages().end());
    }

    return children;
}

Page::~Page()
{
    for (System* s : m_systems) {
        if (s->page() == this) {
            s->setPage(nullptr);
        }
    }
}

EngravingItemList Page::accessibleChildren() const
{
    // The systems are owned by the score, but it is the page that places them, so the
    // page is where the accessibility tree finds them.
    EngravingItemList children = EngravingItem::accessibleChildren();
    children.insert(children.end(), m_systems.begin(), m_systems.end());

    return children;
}

EngravingItem* System::layoutParent() const
{
    return m_page;
    if (m_page) {
        muse::remove(m_page->systems(), this);
    }

MeasureBase::MeasureBase(const ElementType& type, Score* parent)
    : EngravingItem(type, parent)
    // Owned by its score right away; a system only places it later
    setParent(parent);
}

void MeasureBase::setParent(Score* score)
{
    EngravingItem::setParent(score);
}

EngravingItem* MeasureBase::layoutParent() const
{
    if (m_system) {
        return m_system;
    }
    // e.g. a horizontal frame nested inside a vertical frame is placed within its parent frame
    return EngravingItem::layoutParent();
        nb->setSystem(ob->system());

System* Segment::system() const
{
    Measure* m = measure();
    return m ? m->system() : nullptr;
}

EngravingItemList System::accessibleChildren() const
{
    // The measures are owned by the score, but it is the system that places them, so
    // the system is where the accessibility tree finds them.
    EngravingItemList children = EngravingItem::accessibleChildren();
    children.insert(children.end(), m_ml.begin(), m_ml.end());

    return children;
}

EngravingItem* EngravingItem::accessibleParentItem() const
{
    EngravingItem* p = layoutParent();
    if (p) {
        return p;
    }

    return parentItem(false /*not explicit*/);
}

void compute_act_halt_probabilities(
            resizable_tensor& halt_probs,
            resizable_tensor& logits,
            const tensor& input_data,
            const tensor& halt_params,
            long batch_size,
            long seq_len,
            long feature_dim
        )
        {
            const float* in_ptr = input_data.host();
            const float* W_halt = halt_params.host();
            const float b_halt = halt_params.host()[feature_dim];
            float* logits_ptr = logits.host();
            float* halt_probs_ptr = halt_probs.host();

            const long d_model = feature_dim / input_data.k();
            const long num_channels = input_data.k();

            for (long pos = 0; pos < batch_size * seq_len; ++pos) {
                const long n = pos / seq_len;
                const long s = pos % seq_len;

                float logit = b_halt;

                for (long c = 0; c < num_channels; ++c) {
                    for (long d = 0; d < d_model; ++d) {
                        const long in_idx = ((n * num_channels + c) * seq_len + s) * d_model + d;
                        const long weight_idx = c * d_model + d;
                        logit += in_ptr[in_idx] * W_halt[weight_idx];
                    }
                }

                logits_ptr[pos] = logit;

                halt_probs_ptr[pos] = 1.0f / (1.0f + std::exp(-logit));
            }
        }

void update_act_state(
            resizable_tensor& output,
            const tensor& input_data,
            const tensor& halt_probs,
            resizable_tensor& cumulative_halting,
            resizable_tensor& remainders,
            resizable_tensor& n_steps,
            long batch_size,
            long seq_len,
            long d_model,
            long num_channels,
            float halt_threshold,
            long current_step
        )
        {
            const float* in_ptr = input_data.host();
            const float* p_halt = halt_probs.host();
            float* out_ptr = output.host();
            float* cum_halt = cumulative_halting.host();
            float* remain = remainders.host();
            float* steps = n_steps.host();

            for (long pos = 0; pos < batch_size * seq_len; ++pos) {
                if (cum_halt[pos] < halt_threshold) {
                    const long n = pos / seq_len;
                    const long s = pos % seq_len;

                    float p = p_halt[pos];
                    float r = remain[pos];
                    float effective = std::min(p * r, halt_threshold - cum_halt[pos]);

                    cum_halt[pos] += effective;
                    remain[pos] -= effective;
                    steps[pos] = static_cast<float>(current_step + 1);

                    for (long c = 0; c < num_channels; ++c) {
                        for (long d = 0; d < d_model; ++d) {
                            const long idx = ((n * num_channels + c) * seq_len + s) * d_model + d;
                            out_ptr[idx] += effective * in_ptr[idx];
                        }
                    }
                }
            }
        }

void finalize_act_output(
            resizable_tensor& output,
            const tensor& input_data,
            const tensor& remainders,
            long batch_size,
            long seq_len,
            long d_model,
            long num_channels
        )
        {
            const float* in_ptr = input_data.host();
            const float* remain = remainders.host();
            float* out_ptr = output.host();

            for (long pos = 0; pos < batch_size * seq_len; ++pos) {
                float r = remain[pos];
                if (r > 1e-6f) {
                    const long n = pos / seq_len;
                    const long s = pos % seq_len;

                    for (long c = 0; c < num_channels; ++c) {
                        for (long d = 0; d < d_model; ++d) {
                            const long idx = ((n * num_channels + c) * seq_len + s) * d_model + d;
                            out_ptr[idx] += r * in_ptr[idx];
                        }
                    }
                }
            }
        }

void apply_act_depth_scaling(
            tensor& gradients,
            const tensor& n_steps,
            long batch_size,
            long seq_len,
            long d_model,
            long num_channels,
            float max_steps,
            float scale_factor
        )
        {
            const float* steps = n_steps.host();
            float* grad_ptr = gradients.host();

            for (long pos = 0; pos < batch_size * seq_len; ++pos)
            {
                const float scale = 1.0f + scale_factor * (steps[pos] / max_steps);
                const long n = pos / seq_len;
                const long s = pos % seq_len;

                for (long c = 0; c < num_channels; ++c)
                {
                    for (long d = 0; d < d_model; ++d)
                    {
                        const long idx = ((n * num_channels + c) * seq_len + s) * d_model + d;
                        grad_ptr[idx] *= scale;
                    }
                }
            }
        }

void compute_act_halt_probabilities(
        resizable_tensor& halt_probs,
        resizable_tensor& logits,
        const tensor& input_data,
        const tensor& halt_params,
        long batch_size,
        long seq_len,
        long feature_dim
    )
    {
#ifdef DLIB_USE_CUDA
        cuda::compute_act_halt_probabilities(halt_probs, logits, input_data, halt_params,
            batch_size, seq_len, feature_dim);
#else
        cpu::compute_act_halt_probabilities(halt_probs, logits, input_data, halt_params,
            batch_size, seq_len, feature_dim);
#endif
    }

void update_act_state(
        resizable_tensor& output,
        const tensor& input_data,
        const tensor& halt_probs,
        resizable_tensor& cumulative_halting,
        resizable_tensor& remainders,
        resizable_tensor& n_steps,
        long batch_size,
        long seq_len,
        long d_model,
        long num_channels,
        float halt_threshold,
        long current_step
    )
    {
#ifdef DLIB_USE_CUDA
        cuda::update_act_state(output, input_data, halt_probs, cumulative_halting, remainders,
            n_steps, batch_size, seq_len, d_model, num_channels, halt_threshold, current_step);
#else
        cpu::update_act_state(output, input_data, halt_probs, cumulative_halting, remainders,
            n_steps, batch_size, seq_len, d_model, num_channels, halt_threshold, current_step);
#endif
    }

void finalize_act_output(
        resizable_tensor& output,
        const tensor& input_data,
        const tensor& remainders,
        long batch_size,
        long seq_len,
        long d_model,
        long num_channels
    )
    {
#ifdef DLIB_USE_CUDA
        cuda::finalize_act_output(output, input_data, remainders,
            batch_size, seq_len, d_model, num_channels);
#else
        cpu::finalize_act_output(output, input_data, remainders,
            batch_size, seq_len, d_model, num_channels);
#endif
    }

void apply_act_depth_scaling(
        tensor& gradients,
        const tensor& n_steps,
        long batch_size,
        long seq_len,
        long d_model,
        long num_channels,
        float max_steps,
        float scale_factor
    )
    {
#ifdef DLIB_USE_CUDA
        cuda::apply_act_depth_scaling(gradients, n_steps, batch_size, seq_len,
            d_model, num_channels, max_steps, scale_factor);
#else
        cpu::apply_act_depth_scaling(gradients, n_steps, batch_size, seq_len,
            d_model, num_channels, max_steps, scale_factor);
#endif
    }

void test_positional_encodings()
    {
        print_spinner();
        using net_type = tag1<positional_encodings<input<matrix<float>>>>;
        net_type net;
        const unsigned long sequence_dim = 4;
        const unsigned long embedding_dim = 6;
        const unsigned long n_samples = 1, n_channels = 1;
        matrix<float> input_data(sequence_dim, embedding_dim);
        input_data = 0.0f;
        resizable_tensor input_tensor(n_samples, n_channels, sequence_dim, embedding_dim);
        std::vector<matrix<float>> x(n_samples);
        x[0] = input_data;
        net.to_tensor(&x[0], &x[0] + n_samples, input_tensor);
        net.forward(input_tensor);
        matrix<float> expected_output(sequence_dim, embedding_dim);
        const float n = 10000.0f;
        for (long r = 0; r < sequence_dim; ++r) {
            for (long c = 0; c < embedding_dim; ++c) {
                float theta = static_cast<float>(r) / std::pow(n, static_cast<float>(c) / embedding_dim);
                expected_output(r, c) = (c % 2 == 0) ? std::sin(theta) : std::cos(theta);
            }
        }    
        auto& net_output = layer<tag1>(net).get_output();
        DLIB_TEST(max(abs(mat(net_output) - expected_output)) < 1e-5);
    }

void test_embeddings()
    {
        print_spinner();
        const size_t num_sequences = 100, sequence_length = 7, num_classes = 3, num_tokens = 50, embedding_length = 5;
        using net_type = loss_multiclass_log<fc<num_classes,
            relu<fc<32,relu<fc<64,
            embeddings<num_tokens, embedding_length,
            input<matrix<unsigned long, 0, 1>>>>>>>>>;
        net_type net;
        dnn_trainer<net_type> trainer(net, sgd(0, 0.9));
        trainer.set_learning_rate(1e-1);
        trainer.set_min_learning_rate(1e-4);
        trainer.set_mini_batch_size(16);
        trainer.set_max_num_epochs(500);

        dlib::rand rnd(std::rand());
        auto generate_sequences = [&](size_t num_sequences, size_t sequence_length, size_t num_tokens) {
            std::vector<matrix<unsigned long, 0, 1>> sequences;
            for (size_t i = 0; i < num_sequences; ++i)
            {
                matrix<unsigned long, 0, 1> seq(sequence_length, 1);
                for (size_t j = 0; j < sequence_length; ++j)
                    seq(j, 0) = rnd.get_random_32bit_number() % num_tokens;
                sequences.push_back(seq);
            }
            return sequences;
        };

        auto generate_labels = [&](size_t num_sequences, size_t num_classes) {
            std::vector<unsigned long> labels;
            for (size_t i = 0; i < num_sequences; ++i)
                labels.push_back(rnd.get_random_32bit_number() % num_classes);
            return labels;
        };

        auto sequences = generate_sequences(num_sequences, sequence_length, num_tokens);
        auto labels = generate_labels(num_sequences, num_classes);

        trainer.train(sequences, labels);
        std::vector<unsigned long> predicted_labels = net(sequences);
        size_t num_correct = 0;
        for (size_t i = 0; i < labels.size(); ++i)
            if (predicted_labels[i] == labels[i]) ++num_correct;

        double acc = static_cast<double>(num_correct) / labels.size();
        DLIB_TEST(acc > 0.9);
    }

void test_adaptive_computation_time_network()
    {
        print_spinner();

        // Test with a simple network containing ACT layer
        using net_type = tag1<act<input<matrix<float>>>>;
        net_type net;

        // Create test data
        std::vector<matrix<float>> training_images;
        const int seq_len = 4, d_model = 3;

        matrix<float> sample(seq_len, d_model);
        dlib::rand rnd(54321);

        for (int i = 0; i < 10; ++i)
        {
            for (int r = 0; r < seq_len; ++r)
                for (int c = 0; c < d_model; ++c)
                    sample(r, c) = rnd.get_random_gaussian();
            training_images.push_back(sample);
        }

        // Convert to tensor and run forward pass
        resizable_tensor input_tensor;
        net.to_tensor(&training_images[0], &training_images[0] + training_images.size(), input_tensor);

        // Forward pass
        net.forward(input_tensor);

        // Get output and verify dimensions
        const tensor& output = net.get_output();
        DLIB_TEST(output.num_samples() == training_images.size());
        DLIB_TEST(output.nr() == seq_len);
        DLIB_TEST(output.nc() == d_model);

        // Access the ACT layer for statistics
        auto& act_layer = layer<tag1>(net).subnet().layer_details();
        dlog << LINFO << "Network ACT ponder cost: " << act_layer.get_ponder_cost();
        dlog << LINFO << "Network ACT average steps: " << act_layer.get_average_steps();

        // Verify reasonable statistics
        DLIB_TEST(act_layer.get_ponder_cost() >= 0.0f && act_layer.get_ponder_cost() <= 1.0f);
        DLIB_TEST(act_layer.get_average_steps() >= 1.0f);

        dlog << LINFO << "ACT network tests completed successfully";
    }

id setup(const SUBNET& sub) {
            // Precompute the rotation angles and their trigonometric values
            seq_len = sub.get_output().nr();
            d_head = sub.get_output().nc();
            compute_rotation_angles();
            precompute_trigonometric_values();
        }

id forward(const SUBNET& sub, resizable_tensor& output) {
            const tensor& input = sub.get_output();
            output.copy_size(input);
            tt::copy_tensor(false, output, 0, input, 0, input.k());

            // Apply rotary embedding to the output
            apply_rotary_embedding(output);
        }

id backward(
            const tensor& gradient_input,
            SUBNET& sub,
            tensor& params_grad
        ) {
            tensor& prev = sub.get_gradient_input();
            resizable_tensor grad_output;
            grad_output.copy_size(gradient_input);
            tt::copy_tensor(false, grad_output, 0, gradient_input, 0, gradient_input.k());

            // Apply the inverse rotation to the gradient (transpose of the rotation matrix)
            apply_rotary_embedding(grad_output, true);
            tt::copy_tensor(true, prev, 0, grad_output, 0, grad_output.k());
        }

id serialize(const rotary_positional_embedding_& item, std::ostream& out) {
            std::string version = "rotary_positional_embedding_";
            dlib::serialize(version, out);
            dlib::serialize(item.seq_len, out);
            dlib::serialize(item.d_head, out);
            dlib::serialize(item.angles, out);
            dlib::serialize(item.cos_values, out);
            dlib::serialize(item.sin_values, out);
        }

id deserialize(rotary_positional_embedding_& item, std::istream& in) {
            std::string version;
            dlib::deserialize(version, in);
            if (version != "rotary_positional_embedding_")
                throw serialization_error("Unexpected version found while deserializing rotary_positional_embedding_.");
            dlib::deserialize(item.seq_len, in);
            dlib::deserialize(item.d_head, in);
            dlib::deserialize(item.angles, in);
            dlib::deserialize(item.cos_values, in);
            dlib::deserialize(item.sin_values, in);
        }

d::ostream& operator<<(std::ostream& out, const rotary_positional_embedding_& item) {
            out << "rotary_positional_embedding";
            out << " (d_head=" << item.d_head << ", seq_len=" << item.seq_len << ")";
            return out;
        }

id to_xml(const rotary_positional_embedding_& item, std::ostream& out)
        {
            out << "<rotary_positional_embedding"
                << " d_head='" << item.d_head << "'"
                << " seq_len='" << item.seq_len << "'"
                << "/>\n";
        }

id compute_rotation_angles() {
            // Following the original RoPE paper formulation
            const float base = 10000.0f;
            const long half_dim = d_head / 2;
            angles.set_size(seq_len, half_dim);

            for (long pos = 0; pos < seq_len; ++pos) {
                for (long i = 0; i < half_dim; ++i) {
                    float inv_freq = std::pow(base, -2.0f * (i + 0.5f) / d_head);
                    angles(pos, i) = pos * inv_freq;
                }
            }
        }

id precompute_trigonometric_values() {
            // Precompute cos and sin for all angles
            cos_values.set_size(angles.nr(), angles.nc());
            sin_values.set_size(angles.nr(), angles.nc());

            for (long i = 0; i < angles.size(); ++i) {
                cos_values(i) = std::cos(angles(i));
                sin_values(i) = std::sin(angles(i));
            }
        }

id apply_rotary_embedding(
            tensor_type& x,
            bool is_backward = false
        ) const {
            DLIB_CASSERT(x.nc() == d_head, "Input dimension must match d_head param");
            DLIB_CASSERT(x.nr() == seq_len, "Sequence length must match seq_len param");

            const long batch_size = x.num_samples();
            const long num_heads = x.k();
            const bool is_odd = (d_head % 2 != 0);
            const long rot_dim = is_odd ? d_head - 1 : d_head;

            auto* ptr = x.host();
            const long stride = seq_len * d_head;

            for (long n = 0; n < batch_size; ++n) {
                for (long h = 0; h < num_heads; ++h) {
                    auto* x_ptr = ptr + (n * num_heads + h) * stride;

                    for (long pos = 0; pos < seq_len; ++pos) {
                        const float* cos = &cos_values(pos, 0);
                        const float* sin = &sin_values(pos, 0);

                        for (long i = 0; i < rot_dim; i += 2) {
                            const float x0 = x_ptr[pos * d_head + i];
                            const float x1 = x_ptr[pos * d_head + i + 1];

                            if (!is_backward) {
                                x_ptr[pos * d_head + i] = x0 * cos[i / 2] - x1 * sin[i / 2];
                                x_ptr[pos * d_head + i + 1] = x0 * sin[i / 2] + x1 * cos[i / 2];
                            }
                            else {
                                x_ptr[pos * d_head + i] = x0 * cos[i / 2] + x1 * sin[i / 2];
                                x_ptr[pos * d_head + i + 1] = -x0 * sin[i / 2] + x1 * cos[i / 2];
                            }
                        }
                    }
                }
            }
        }

