static void DiscardQueuedRequests() {
	std::lock_guard<std::mutex> lock(g_upnpLock);
	if (!g_upnpReqs.empty()) {
		DEBUG_LOG(Log::Net, "UPnPService: discarding %d queued request(s)", (int)g_upnpReqs.size());
		g_upnpReqs.clear();
	}
}

static bool ProcessQueuedRequests() {
			if (g_upnpExit || g_upnpReqs.empty())
				return true;
			// Take it out of the queue for the duration. Talking to the router happens without the
			// lock held, and QueueRequest() supersedes pending requests for the same port - if the
			// in-flight one were still in the deque it could be erased out from under us, and we'd
			// then drop whatever replaced it without ever running it.
			arg = std::move(g_upnpReqs.front());
		}

static void StartUPnPService() {
	std::lock_guard<std::mutex> threadLock(g_upnpThreadLock);
	{
		std::lock_guard<std::mutex> lock(g_upnpLock);
		if (!g_upnpInitialized || g_upnpExit || !g_Config.bEnableUPnP)
			return;
		if (g_upnpThreadRunning) {
			// Already up - it'll notice whatever changed on its own.
			return;
		}
		g_upnpThreadRunning = true;
		g_upnpResetBackoff = true;
	}
	// A previous thread may have exited when the setting was turned off. By the time it clears
	// g_upnpThreadRunning it has already cleaned up after itself, so this doesn't block on a router.
	if (g_upnpServiceThread.joinable())
		g_upnpServiceThread.join();
	g_upnpServiceThread = std::thread(upnpService, g_upnpTimeout);
}

static std::string MappingDescription() {
	if (PSP_IsInited()) {
		return "PPSSPP:" + g_paramSFO.GetDiscID() + ":" + g_Config.sNickName;
	}
	return "PPSSPP:at_menu:" + g_Config.sNickName;
}

static const char *SNBasicType(char c) {
	switch (c) {
	case 'v': return "void";
	case 'c': return "char";
	case 's': return "short";
	case 'i': return "int";
	case 'l': return "long";
	case 'x': return "long long";
	case 'f': return "float";
	case 'd': return "double";
	case 'r': return "long double";
	case 'b': return "bool";
	case 'w': return "wchar_t";
	case 'e': return "...";
	default: return nullptr;
	}
}

static int SNLetterValue(char c) {
	if (c >= 'A' && c <= 'Z')
		return c - 'A';
	if (c >= 'a' && c <= 'z')
		return c - 'a' + 26;
	return -1;
}

std::string ParseWholeName() {
		std::vector<std::string> parts;
		while (pos_ < s_.size()) {
			parts.push_back(ParseName(nullptr));
			if (failed_)
				return "";
		}
		std::string out;
		JoinInto(out, parts, "::");
		return out;
	}

bool ConsumeIf(const char *str) {
		const size_t len = strlen(str);
		if (s_.compare(pos_, len, str) != 0)
		pos_ += len;
		return true;
	void Fail() { failed_ = true; }
	std::string ParseIdentifier();
	std::string ParseNumber();
	std::string ParseName(std::vector<std::string> *templateArgs);
	std::string ParseTemplateArgs(std::vector<std::string> *args);
	CWDecl ParseDecl();
	std::string ParseType() { return ParseDecl().str(); }
	std::string ParseParams();

	std::string_view s_;
	size_t pos_ = 0;
	bool failed_ = false;
	int depth_ = 0;
	// The template arguments of the name this symbol belongs to, for resolving "9" back-
	// references in the parameters and return type.
	std::vector<std::string> templateArgs_;
	// Parameter types so far, for resolving the "T" and "N" back-references.
	std::vector<std::string> params_;
}

std::string SNSystemsParser::ParseIdentifier() {
	const int len = SNLetterValue(Peek());
	if (len < 0 || pos_ + 1 + (size_t)len > s_.size()) {
		Fail();
		return "";
	}
	pos_++;
	std::string name(s_.substr(pos_, len));
	pos_ += len;
	return name;
}

std::string SNSystemsParser::ParseNumber() {
	if (Peek() == '8') {
		pos_++;
		const int len = SNLetterValue(Peek());
		if (len <= 0 || pos_ + 1 + (size_t)len > s_.size()) {
			Fail();
			return "";
		}
		pos_++;
		std::string digits(s_.substr(pos_, len));
		pos_ += len;
		if (digits.find_first_not_of("0123456789") != std::string::npos) {
			Fail();
			return "";
		}
		return digits;
	}
	int value = 0;
	while (Peek() == '0') {
		pos_++;
		value += 52;
		if (value > 1000000) {
			Fail();
			return "";
		}
	}
	const int digit = SNLetterValue(Peek());
	if (digit < 0) {
		Fail();
		return "";
	}
	pos_++;
	return std::to_string(value + digit);
}

std::string SNSystemsParser::ParseTemplateArgs(std::vector<std::string> *args) {
	pos_++;
	while (Peek() != '_') {
		if (!Peek() || failed_) {
			Fail();
			return "";
		}
		if (Peek() == '4') {
			pos_++;
			args->push_back(ParseNumber());
		} else {
			args->push_back(ParseType());
		}
		if (failed_)
			return "";
	}
	pos_++;
	std::string out;
	JoinInto(out, *args, ", ");
	return "<" + out + ">";
}

std::string SNSystemsParser::ParseName(std::vector<std::string> *templateArgs) {
	std::vector<std::string> parts;
	while (Peek() == '5') {
		pos_++;
		parts.push_back(ParseIdentifier());
		if (failed_)
			return "";
	}
	parts.push_back(ParseIdentifier());
	if (failed_)
		return "";
	if (Peek() == '7') {
		std::vector<std::string> args;
		const std::string printed = ParseTemplateArgs(&args);
		if (failed_)
			return "";
		parts.back() += printed;
		if (templateArgs && !args.empty())
			*templateArgs = args;
	}
	std::string out;
	JoinInto(out, parts, "::");
	return out;
}

bool DemangleSNSystems(std::string_view mangled, DemangledSymbol *out) {
	if (mangled.size() > 3 && mangled.compare(0, 3, "__0") == 0) {
		SNSystemsParser parser(mangled);
		return parser.Parse(out);
	}

	// Symbols the compiler generates for a type, using the same name encoding.
	static const struct { const char *prefix; const char *text; } kinds[] = {
		{"__TID_", "type id for "},
		{"__T_", "typeinfo for "},
		{"__sti__", "static initializers for "},
	};
	for (const auto &kind : kinds) {
		const size_t len = strlen(kind.prefix);
		if (mangled.size() <= len || mangled.compare(0, len, kind.prefix) != 0)
			continue;
		out->name = kind.text;
		out->isFunction = false;
		if (kind.prefix[2] == 's') {
			// The static initializer is named after a source file, not a type.
			out->name += std::string(mangled.substr(len));
			return true;
		}
		SNSystemsParser parser(mangled.substr(len));
		std::string name = parser.ParseWholeName();
		if (name.empty()) {
			// It can also be a plain type rather than a class - "__TID_v" is void's.
			SNSystemsParser typeParser(mangled.substr(len));
			name = typeParser.ParseWholeType();
		}
		if (name.empty())
			return false;
		out->name += name;
		return true;
	}
	return false;
}

std::string CodeWarriorParser::ParseTemplateArgs(std::string_view args) {
	std::vector<std::string> parts;
	size_t start = 0;
	int depth = 0;
	for (size_t i = 0; i <= args.size(); i++) {
		if (i < args.size()) {
			if (args[i] == '<')
				depth++;
			else if (args[i] == '>')
				depth--;
			// Only a top-level comma separates arguments; a nested "<...>" has its own.
			if (args[i] != ',' || depth != 0)
				continue;
		}
		const std::string_view arg = args.substr(start, i - start);
		start = i + 1;
		if (arg.empty())
			return "<" + std::string(args) + ">";
		// All digits is a non-type argument ("CSimpleChar<24>"); anything else is a type.
		size_t digits = arg[0] == '-' ? 1 : 0;
		while (digits < arg.size() && IsDigit(arg[digits]))
			digits++;
		if (digits == arg.size()) {
			parts.push_back(std::string(arg));
			continue;
		}
		CodeWarriorParser sub(arg, true);
		const std::string type = sub.ParseWholeType();
		if (type.empty())
			return "<" + std::string(args) + ">";
		parts.push_back(type);
	}
	std::string out;
	JoinInto(out, parts, ", ");
	return "<" + out + ">";
}

CWDecl CodeWarriorParser::ParseDecl() {
		return CWDecl();
	CWDecl result;
	{
		result = ParseDecl();
		const char sigil = c == 'P' ? '*' : '&';
		if (result.post.empty()) {
			result.pre += ' ';
		}
		// Pointing at a function or an array, the sigil goes inside the parens the inner
		// type left open: "int (*)(char)", not "int ()(char) *".
		result.pre += sigil;
	}
		result = ParseDecl();
		if (!result.pre.empty() && (result.pre.back() == '*' || result.pre.back() == '&'))
			result.pre += std::string(" ") + qual;
			result.pre = std::string(qual) + " " + result.pre;
		result = ParseDecl();
		result.pre = std::string(c == 'U' ? "unsigned " : "signed ") + result.pre;
		result = ParseDecl();
		result.post = " [" + std::to_string(count) + "]" + result.post;
		// A function type: parameters, then "_" and the return type. The parens around the
		// declarator are left open for a P or R to put its sigil in - see above.
		result.pre = ret + " (";
		result.post = ")(" + args + ")";
			result.pre = params_[index - 1];
		result.pre = "...";
			result.pre = ParseQualifiedName();
			result.pre = basic;
	return failed_ ? CWDecl() : result;
	// A function template spells its arguments out in the name: "sort<Pf>__3stdFPfPf_v".
	const size_t lt = base.find('<');
	if (lt != std::string::npos && base.back() == '>') {
		CodeWarriorParser argParser("", true);
		const std::string_view args = std::string_view(base).substr(lt + 1, base.size() - lt - 2);
		base = base.substr(0, lt) + argParser.ParseTemplateArgs(args);
	}
	// A plain C name with a "__" in it ("I3dClut__FlushCache") can look like an unqualified
	// function whose parameters happen not to decode, so in the lenient pass - where the
	// parameters are allowed not to decode - insist on a class qualifier as evidence that
	// this really is a mangled name.
	if (!strict && parser.qualifier().empty())
		return false;
// A compiler-generated symbol that carries a mangled name inside it, rather than being one:
//
//   __vt__3Son                              vtable for Son
//   __RTTI__Q23std9exception                typeinfo for std::exception
//   __sinit_hl_app.cpp                      static initializers for hl_app.cpp
//   @12@__dt__3SonFv                        non-virtual thunk (12) to Son::~Son()
//   @STRING@Init__Q25shTbb3TbbFPvPci@0      string literal 0 in shTbb::Tbb::Init(...)
//   @LOCAL@sort<Pf>__3stdFPfPf_v@shuffle@0  std::sort<float *>(...)::shuffle
//
// The @-forms are how CodeWarrior names things that have no C++ name of their own; the
// trailing @<n> distinguishes several of them within the same function. Returns false if
// this isn't one of them, leaving the caller to demangle the name as an ordinary symbol.
static bool DemangleCodeWarriorSpecial(std::string_view mangled, DemangledSymbol *out) {
	// Splits off a trailing "@<digits>" discriminator, which is only there when a function
	// has more than one of whatever this is. Then demangles what's left of the front half.
	auto splitIndex = [](std::string_view s, DemangledSymbol *inner, std::string *index) {
		const size_t at = s.rfind('@');
		if (at != std::string_view::npos && at + 1 < s.size() &&
				s.find_first_not_of("0123456789", at + 1) == std::string_view::npos) {
			*index = std::string(s.substr(at + 1)) + " ";
			s = s.substr(0, at);
		}
		return DemangleCodeWarrior(s, inner);
	};

	static const struct { const char *prefix; const char *text; } kinds[] = {
		{"__vt__", "vtable for "},
		{"__RTTI__", "typeinfo for "},
		{"__sinit_", "static initializers for "},
		{"__sterm_", "static destructors for "},
	};
	for (const auto &kind : kinds) {
		const size_t len = strlen(kind.prefix);
		if (mangled.size() <= len || mangled.compare(0, len, kind.prefix) != 0)
			continue;
		const std::string_view rest = mangled.substr(len);
		out->name = kind.text;
		if (kind.prefix[2] == 's') {
			// The static init/term functions are named after a source file, not a class.
			out->name += std::string(rest);
		} else {
			CodeWarriorParser parser(rest, true);
			DemangledSymbol type;
			if (!parser.ParseAfterSeparator(&type) || type.isFunction || parser.qualifier().empty())
				return false;
			out->name += parser.qualifier();
		}
		out->isFunction = false;
		return true;
	}

	if (mangled.compare(0, 8, "@STRING@") == 0) {
		// A string literal inside a function - typically the __FILE__ an assert expanded to.
		DemangledSymbol inner;
		std::string index;
		if (!splitIndex(mangled.substr(8), &inner, &index))
			return false;
		out->name = "string literal " + index + "in " + inner.ToString();
		out->isFunction = false;
		return true;
	}
	if (mangled.compare(0, 7, "@GUARD@") == 0) {
		// The "has this local static been constructed yet" flag. The name is the variable's,
		// undecorated apart from the "$<n>" that CodeWarrior gives every function-local one.
		out->name = "guard variable for " + std::string(mangled.substr(7));
		out->isFunction = false;
		return true;
	}
	if (mangled.compare(0, 7, "@LOCAL@") == 0) {
		// A function-local static: "@LOCAL@<function>@<variable>", plus the usual index.
		std::string_view body = mangled.substr(7);
		size_t at = body.rfind('@');
		if (at != std::string_view::npos && at + 1 < body.size() &&
				body.find_first_not_of("0123456789", at + 1) == std::string_view::npos)
			body = body.substr(0, at);
		at = body.rfind('@');
		if (at == std::string_view::npos)
			return false;
		DemangledSymbol inner;
		if (!DemangleCodeWarrior(body.substr(0, at), &inner))
			return false;
		out->name = inner.ToString() + "::" + std::string(body.substr(at + 1));
		out->isFunction = false;
		return true;
	}
	if (mangled[0] == '@' && IsDigit(mangled[1])) {
		// "@<this-adjustment>@<function>": a thunk for a base other than the first.
		const size_t at = mangled.find('@', 1);
		if (at == std::string_view::npos)
			return false;
		const std::string_view offset = mangled.substr(1, at - 1);
		if (offset.find_first_not_of("0123456789") != std::string_view::npos)
			return false;
		DemangledSymbol inner;
		if (!DemangleCodeWarrior(mangled.substr(at + 1), &inner))
			return false;
		out->name = "non-virtual thunk (" + std::string(offset) + ") to " + inner.ToString();
		out->isFunction = false;
		return true;
	}
	return false;
}

	if (mangled.size() > 2 && (mangled[0] == '@' || mangled[0] == '_') &&
			DemangleCodeWarriorSpecial(mangled, out))
		return true;

static bool DemangleCodeWarriorSpecial(std::string_view mangled, DemangledSymbol *out) {
	// Splits off a trailing "@<digits>" discriminator, which is only there when a function
	// has more than one of whatever this is. Then demangles what's left of the front half.
	auto splitIndex = [](std::string_view s, DemangledSymbol *inner, std::string *index) {
		const size_t at = s.rfind('@');
		if (at != std::string_view::npos && at + 1 < s.size() &&
				s.find_first_not_of("0123456789", at + 1) == std::string_view::npos) {
			*index = std::string(s.substr(at + 1)) + " ";
			s = s.substr(0, at);
		}
		return DemangleCodeWarrior(s, inner);
	};

	static const struct { const char *prefix; const char *text; } kinds[] = {
		{"__vt__", "vtable for "},
		{"__RTTI__", "typeinfo for "},
		{"__sinit_", "static initializers for "},
		{"__sterm_", "static destructors for "},
	};
	for (const auto &kind : kinds) {
		const size_t len = strlen(kind.prefix);
		if (mangled.size() <= len || mangled.compare(0, len, kind.prefix) != 0)
			continue;
		const std::string_view rest = mangled.substr(len);
		out->name = kind.text;
		if (kind.prefix[2] == 's') {
			// The static init/term functions are named after a source file, not a class.
			out->name += std::string(rest);
		} else {
			CodeWarriorParser parser(rest, true);
			DemangledSymbol type;
			if (!parser.ParseAfterSeparator(&type) || type.isFunction || parser.qualifier().empty())
				return false;
			out->name += parser.qualifier();
		}
		out->isFunction = false;
		return true;
	}

	if (mangled.compare(0, 8, "@STRING@") == 0) {
		// A string literal inside a function - typically the __FILE__ an assert expanded to.
		DemangledSymbol inner;
		std::string index;
		if (!splitIndex(mangled.substr(8), &inner, &index))
			return false;
		out->name = "string literal " + index + "in " + inner.ToString();
		out->isFunction = false;
		return true;
	}
	if (mangled.compare(0, 7, "@GUARD@") == 0) {
		// The "has this local static been constructed yet" flag. The name is the variable's,
		// undecorated apart from the "$<n>" that CodeWarrior gives every function-local one.
		out->name = "guard variable for " + std::string(mangled.substr(7));
		out->isFunction = false;
		return true;
	}
	if (mangled.compare(0, 7, "@LOCAL@") == 0) {
		// A function-local static: "@LOCAL@<function>@<variable>", plus the usual index.
		std::string_view body = mangled.substr(7);
		size_t at = body.rfind('@');
		if (at != std::string_view::npos && at + 1 < body.size() &&
				body.find_first_not_of("0123456789", at + 1) == std::string_view::npos)
			body = body.substr(0, at);
		at = body.rfind('@');
		if (at == std::string_view::npos)
			return false;
		DemangledSymbol inner;
		if (!DemangleCodeWarrior(body.substr(0, at), &inner))
			return false;
		out->name = inner.ToString() + "::" + std::string(body.substr(at + 1));
		out->isFunction = false;
		return true;
	}
	if (mangled[0] == '@' && IsDigit(mangled[1])) {
		// "@<this-adjustment>@<function>": a thunk for a base other than the first.
		const size_t at = mangled.find('@', 1);
		if (at == std::string_view::npos)
			return false;
		const std::string_view offset = mangled.substr(1, at - 1);
		if (offset.find_first_not_of("0123456789") != std::string_view::npos)
			return false;
		DemangledSymbol inner;
		if (!DemangleCodeWarrior(mangled.substr(at + 1), &inner))
			return false;
		out->name = "non-virtual thunk (" + std::string(offset) + ") to " + inner.ToString();
		out->isFunction = false;
		return true;
	}
	return false;
}

static const char *CWBasicType(char c) {
	switch (c) {
	case 'v': return "void";
	case 'c': return "char";
	case 's': return "short";
	case 'i': return "int";
	case 'l': return "long";
	case 'x': return "long long";
	case 'f': return "float";
	case 'd': return "double";
	case 'r': return "long double";
	case 'b': return "bool";
	case 'w': return "wchar_t";  // A Metrowerks addition to the cfront set.
	default: return nullptr;
	}
}

int CodeWarriorParser::ParseNumber() {
	if (!IsDigit(Peek()))
		return -1;
	int value = 0;
	while (IsDigit(Peek())) {
		value = value * 10 + (s_[pos_] - '0');
		if (value > 1000000)
			return -1;
		pos_++;
	}
	return value;
}

std::string CodeWarriorParser::ParseIdentifier() {
	const int len = ParseNumber();
	// A too-long length means the symbol was truncated by whatever wrote the symbol table -
	// 127 characters is a common limit, and template names blow past it easily. Nothing
	// useful survives, so don't guess.
	if (len <= 0 || pos_ + (size_t)len > s_.size()) {
		Fail();
		return "";
	}
	std::string name(s_.substr(pos_, len));
	pos_ += len;
	return name;
}

std::string CodeWarriorParser::ParseQualifiedName() {
	if (Peek() != 'Q')
		return ParseIdentifier();
	pos_++;
	int count;
	if (Peek() == '_') {
		pos_++;
		count = ParseNumber();
		if (Peek() != '_')
			count = -1;
		else
			pos_++;
	} else {
		count = IsDigit(Peek()) ? (s_[pos_++] - '0') : -1;
	}
	if (count <= 0) {
		Fail();
		return "";
	}
	std::vector<std::string> parts;
	for (int i = 0; i < count; i++) {
		parts.push_back(ParseIdentifier());
		if (failed_)
			return "";
	}
	std::string out;
	JoinInto(out, parts, "::");
	return out;
}

std::string CodeWarriorParser::ParseType() {
	if (failed_ || depth_ > 64) {
		Fail();
		return "";
	}
	depth_++;
	std::string result;
	const char c = Peek();
	switch (c) {
	case 'P':
	case 'R':
		pos_++;
		result = ParseType() + (c == 'P' ? " *" : " &");
		break;
	case 'C':
	case 'V':
	{
		pos_++;
		const char *qual = c == 'C' ? "const" : "volatile";
		const std::string inner = ParseType();
		// "char * const", but "const char *" - the qualifier binds to whatever came before.
		if (!inner.empty() && (inner.back() == '*' || inner.back() == '&'))
			result = inner + " " + qual;
		else
			result = std::string(qual) + " " + inner;
		break;
	}
	case 'U':
	case 'S':
		pos_++;
		result = std::string(c == 'U' ? "unsigned " : "signed ") + ParseType();
		break;
	case 'A':
	{
		pos_++;
		const int count = ParseNumber();
		if (count < 0 || Peek() != '_') {
			Fail();
			break;
		}
		pos_++;
		result = ParseType() + " [" + std::to_string(count) + "]";
		break;
	}
	case 'F':
	{
		// A function type: parameters, then "_" and the return type. Printed without the
		// declarator gymnastics a real demangler does, so a pointer to one comes out as
		// "int () *" rather than "int (*)()".
		pos_++;
		std::string args;
		if (!ParseParams(&args))
			break;
		std::string ret = "void";
		if (Peek() == '_') {
			pos_++;
			ret = ParseType();
		}
		result = ret + " (" + args + ")";
		break;
	}
	case 'T':
	{
		// "T<n>": the same type as parameter n, 1-based.
		pos_++;
		const int index = IsDigit(Peek()) ? (s_[pos_++] - '0') : -1;
		if (index < 1 || (size_t)index > params_.size())
			Fail();
		else
			result = params_[index - 1];
		break;
	}
	case 'e':
		pos_++;
		result = "...";
		break;
	default:
		if (c == 'Q' || IsDigit(c)) {
			result = ParseQualifiedName();
		} else if (const char *basic = CWBasicType(c)) {
			pos_++;
			result = basic;
		} else {
			Fail();
		}
		break;
	}
	depth_--;
	return failed_ ? "" : result;
}

bool CodeWarriorParser::ParseParams(std::string *out) {
	std::vector<std::string> parts;
	bool unknown = false;
	while (pos_ < s_.size() && Peek() != '_') {
		if (Peek() == 'N') {
			// "N<count><index>": <count> parameters, each the same type as parameter <index>.
			const size_t save = pos_;
			pos_++;
			const int count = IsDigit(Peek()) ? (s_[pos_++] - '0') : -1;
			const int index = IsDigit(Peek()) ? (s_[pos_++] - '0') : -1;
			if (count >= 1 && index >= 1 && (size_t)index <= params_.size()) {
				for (int i = 0; i < count; i++) {
					parts.push_back(params_[index - 1]);
					params_.push_back(params_[index - 1]);
				}
				continue;
			}
			pos_ = save;
		}
		const std::string type = ParseType();
		if (failed_) {
			// Something we don't know. In lenient mode, say so instead of throwing the
			// whole (perfectly readable) name away.
			if (strict_)
				return false;
			failed_ = false;
			unknown = true;
			pos_ = s_.size();
			break;
		}
		// A lone "void" is how a parameterless function is spelled.
		if (type == "void" && parts.empty() && (pos_ >= s_.size() || Peek() == '_'))
			break;
		parts.push_back(type);
		params_.push_back(type);
	}
	if (unknown)
		parts.push_back("...");
	JoinInto(*out, parts, ", ");
	return true;
}

bool CodeWarriorParser::ParseAfterSeparator(DemangledSymbol *out) {
	if (Peek() == 'Q' || IsDigit(Peek())) {
		qualifier_ = ParseQualifiedName();
		if (failed_)
			return false;
	}
	std::vector<std::string> quals;
	while (Peek() == 'C' || Peek() == 'V')
		quals.push_back(s_[pos_++] == 'C' ? "const" : "volatile");
	JoinInto(out->qualifiers, quals, " ");

	if (pos_ >= s_.size()) {
		// No function type: a static data member, which only makes sense qualified.
		if (qualifier_.empty() || !out->qualifiers.empty())
			return false;
		out->isFunction = false;
		return true;
	}
	if (Peek() != 'F')
		return false;
	pos_++;
	out->isFunction = true;
	if (!ParseParams(&out->parameters))
		return false;
	if (Peek() == '_') {
		// Templates encode their return type, same as in the Itanium mangling.
		pos_++;
		out->returnType = ParseType();
		if (failed_)
			return false;
	}
	return pos_ == s_.size();
}

static std::string CodeWarriorName(std::string_view name, const std::string &qualifier) {
	std::string base;
	if (name == "__ct") {
		base = BaseName(qualifier);
	} else if (name == "__dt") {
		base = "~" + BaseName(qualifier);
	} else if (name.size() > 4 && name.compare(0, 4, "__op") == 0) {
		// A conversion operator carries its target type in the name itself.
		CodeWarriorParser typeParser(name.substr(4), true);
		const std::string type = typeParser.ParseWholeType();
		if (!type.empty())
			base = "operator " + type;
	} else if (name.size() > 2 && name.compare(0, 2, "__") == 0) {
		const std::string_view code = name.substr(2);
		for (const CWOperator &op : cwOperators) {
			if (code == op.code) {
				// "operator new", but "operator+".
				base = std::string("operator") + (op.name[0] >= 'a' ? " " : "") + op.name;
				break;
			}
		}
	}
	if (base.empty())
		base = std::string(name);
	return qualifier.empty() ? base : qualifier + "::" + base;
}

static bool TryCodeWarriorSplit(std::string_view mangled, size_t sep, bool strict, DemangledSymbol *out) {
	CodeWarriorParser parser(mangled.substr(sep + 2), strict);
	DemangledSymbol sym;
	if (!parser.ParseAfterSeparator(&sym))
		return false;
	sym.name = CodeWarriorName(mangled.substr(0, sep), parser.qualifier());
	*out = sym;
	return true;
}

bool DemangleCodeWarrior(std::string_view mangled, DemangledSymbol *out) {
	// Names can themselves start with underscores ("__SetupFrameInfo__F..."), and can
	// contain "__" further in, so every candidate separator gets tried. Strict first, so a
	// split that decodes completely wins over one that only decodes its name.
	size_t start = 0;
	while (start < mangled.size() && mangled[start] == '_')
		start++;
	if (start == mangled.size())
		return false;
	for (int pass = 0; pass < 2; pass++) {
		for (size_t i = start; i + 2 < mangled.size(); i++) {
			if (mangled[i] == '_' && mangled[i + 1] == '_' &&
					TryCodeWarriorSplit(mangled, i, pass == 0, out))
				return true;
		}
	}
	return false;
}

bool DemangleSNSystems(std::string_view mangled, DemangledSymbol *out) {
	if (mangled.size() < 6 || mangled.compare(0, 3, "__0") != 0)
		return false;
	size_t pos = 3;
	const char kind = mangled[pos++];
	if (kind != 'f' && kind != 'F')
		return false;
	if (!IsDigit(mangled[pos]))
		return false;
	pos++;

	std::vector<std::string> parts;
	while (pos < mangled.size() && mangled[pos] >= 'A' && mangled[pos] <= 'Z') {
		const size_t len = (size_t)(mangled[pos] - 'A');
		pos++;
		if (pos + len > mangled.size())
			return false;
		parts.push_back(std::string(mangled.substr(pos, len)));
		pos += len;
	}
	if (parts.empty())
		return false;

	DemangledSymbol sym;
	sym.isFunction = true;
	std::vector<std::string> params;
	while (pos < mangled.size()) {
		const char c = mangled[pos];
		if (c == 'v') {
			// void, i.e. no parameters at all.
			pos++;
			continue;
		}
		if (c == 'K' && pos + 1 == mangled.size()) {
			sym.qualifiers = "const";
			pos++;
			continue;
		}
		if (IsDigit(c) && pos + 1 < mangled.size() &&
				mangled[pos + 1] >= 'A' && mangled[pos + 1] <= 'Z') {
			// A tagged, length-prefixed type name.
			const size_t len = (size_t)(mangled[pos + 1] - 'A');
			if (pos + 2 + len > mangled.size())
				return false;
			params.push_back(std::string(mangled.substr(pos + 2, len)));
			pos += 2 + len;
			continue;
		}
		// Anything else is a type code we haven't seen yet. Keep the name, admit to not
		// knowing the rest.
		params.push_back("...");
		break;
	}
	JoinInto(sym.name, parts, "::");
	JoinInto(sym.parameters, params, ", ");
	*out = sym;
	return true;
}

std::string DemangledSymbol::ToString() const {
	std::string out;
	if (!returnType.empty())
		out = returnType + " ";
	out += name;
	if (isFunction)
		out += "(" + parameters + ")";
	if (!qualifiers.empty())
		out += " " + qualifiers;
	return out;
}

void Core_WakeIdleCPUThread() {
	{
		std::lock_guard<std::mutex> guard(g_idleMutex);
		g_idleWakeCounter++;
	}
	g_idleCond.notify_all();
}

static void Core_IdleWaitWhileStepping() {
	constexpr auto kMaxIdleWait = std::chrono::milliseconds(2);
	{
		// Don't sleep if something is already waiting on us.
		std::lock_guard<std::mutex> guard(g_cpuQueueMutex);
		if (!g_cpuQueue.empty())
			return;
	}
	std::unique_lock<std::mutex> guard(g_idleMutex);
	const u64 seen = g_idleWakeCounter;
	g_idleCond.wait_for(guard, kMaxIdleWait, [&] { return g_idleWakeCounter != seen; });
}

View *FindTabOrderNeighbor(ViewGroup *root, View *focusedView, FocusMove direction) {
	std::vector<View *> order;
	root->CollectTabOrder(&order);
	if (order.empty()) {
		return nullptr;
	}

	const int step = direction == FocusMove::NEXT ? 1 : (int)order.size() - 1;

	// The focused view not being in the list is normal - it can have been hidden or disabled
	// since it got focus. Start from one end rather than giving up.
	auto iter = std::find(order.begin(), order.end(), focusedView);
	if (iter == order.end()) {
		return direction == FocusMove::NEXT ? order.front() : order.back();
	}

	const size_t index = iter - order.begin();
	return order[(index + step) % order.size()];
}

void ViewGroup::CollectTabOrder(std::vector<View *> *outViews) const {
	for (View *view : views_) {
		// Gate on visibility only, like Key/Touch/Axis do - a container being disabled doesn't
		// stop its children from being interactive elsewhere, so it shouldn't here either.
		if (view->GetVisibility() != V_VISIBLE) {
			continue;
		}
		if (view->IsViewGroup()) {
			// A group can be focusable itself (rare), in which case it's a stop and we still
			// descend into it - same as arrow navigation, which considers both.
			ViewGroup *vg = static_cast<ViewGroup *>(view);
			if (vg->CanBeFocused() && vg->IsEnabled()) {
				outViews->push_back(vg);
			}
			vg->CollectTabOrder(outViews);
		} else if (view->CanBeFocused() && view->IsEnabled()) {
			outViews->push_back(view);
		}
	}
}

bool TestUITabOrder() {
	using namespace UI;

	LinearLayout root(ORIENT_VERTICAL);

	// A label is not a tab stop, but the item after it is.
	root.Add(new TextView("label"));
	Choice *a = root.Add(new Choice("a"));

	// Nested groups are flattened in place, in order.
	LinearLayout *inner = root.Add(new LinearLayout(ORIENT_HORIZONTAL));
	Choice *b = inner->Add(new Choice("b"));
	Choice *disabled = inner->Add(new Choice("disabled"));
	disabled->SetEnabled(false);

	// A hidden subtree is skipped whole - this is how the inactive tabs of a TabHolder,
	// which are V_GONE rather than removed, stay out of the way.
	LinearLayout *hidden = root.Add(new LinearLayout(ORIENT_VERTICAL));
	hidden->SetVisibility(V_GONE);
	hidden->Add(new Choice("hidden"));

	root.Add(new Spacer());
	Choice *c = root.Add(new Choice("c"));
	Choice *invisible = root.Add(new Choice("invisible"));
	invisible->SetVisibility(V_INVISIBLE);

	std::vector<View *> order;
	root.CollectTabOrder(&order);
	EXPECT_EQ_INT((int)order.size(), 3);
	EXPECT_TRUE(order[0] == a);
	EXPECT_TRUE(order[1] == b);
	EXPECT_TRUE(order[2] == c);

	// Tab walks forwards and wraps at the end, Shift+Tab does the reverse.
	EXPECT_TRUE(FindTabOrderNeighbor(&root, a, FocusMove::NEXT) == b);
	EXPECT_TRUE(FindTabOrderNeighbor(&root, b, FocusMove::NEXT) == c);
	EXPECT_TRUE(FindTabOrderNeighbor(&root, c, FocusMove::NEXT) == a);
	EXPECT_TRUE(FindTabOrderNeighbor(&root, c, FocusMove::PREV) == b);
	EXPECT_TRUE(FindTabOrderNeighbor(&root, b, FocusMove::PREV) == a);
	EXPECT_TRUE(FindTabOrderNeighbor(&root, a, FocusMove::PREV) == c);

	// A view that has gone away (or was never a stop) doesn't stall navigation - it starts
	// from whichever end we're heading towards.
	EXPECT_TRUE(FindTabOrderNeighbor(&root, disabled, FocusMove::NEXT) == a);
	EXPECT_TRUE(FindTabOrderNeighbor(&root, disabled, FocusMove::PREV) == c);
	EXPECT_TRUE(FindTabOrderNeighbor(&root, nullptr, FocusMove::NEXT) == a);

	// With a single stop, both directions land back on it, and with none there's nothing to do.
	LinearLayout one(ORIENT_VERTICAL);
	Choice *only = one.Add(new Choice("only"));
	EXPECT_TRUE(FindTabOrderNeighbor(&one, only, FocusMove::NEXT) == only);
	EXPECT_TRUE(FindTabOrderNeighbor(&one, only, FocusMove::PREV) == only);

	LinearLayout empty(ORIENT_VERTICAL);
	empty.Add(new TextView("just a label"));
	EXPECT_TRUE(FindTabOrderNeighbor(&empty, nullptr, FocusMove::NEXT) == nullptr);

	return true;
}

static inline u64 ARM64ReadFPCR() {
#if PPSSPP_PLATFORM(WINDOWS)
	return _ReadStatusReg(ARM64_FPCR);
#else
	// TODO: Try __builtin_arm_get_fpcr()
	u64 fpcr;  // not really 64-bit, just to match the register size.
	asm volatile ("mrs %0, fpcr" : "=r" (fpcr));
	return fpcr;
#endif
}

static inline void ARM64WriteFPCR(u64 fpcr) {
#if PPSSPP_PLATFORM(WINDOWS)
	_WriteStatusReg(ARM64_FPCR, fpcr);
#else
	// TODO: Try __builtin_arm_set_fpcr()
	// Write back the modified FPCR
	asm volatile ("msr fpcr, %0" : : "r" (fpcr));
#endif
}

void ApplyHostRoundingMode(const MIPSState *mips) {
	u32 fcr1Bits = mips->fcr31 & 0x01000003;
	// If these are 0, we just leave things as they are.
	if (fcr1Bits) {
		int rmode = fcr1Bits & 3;
		bool ftz = (fcr1Bits & 0x01000000) != 0;
#if PPSSPP_ARCH(SSE2)
		u32 csr = _mm_getcsr() & ~0x6000;
		// Translate the rounding mode bits to X86, the same way as in Asm.cpp.
		if (rmode & 1) {
			rmode ^= 2;
		}
		csr |= rmode << 13;

		if (ftz) {
			// Flush to zero
			csr |= 0x8000;
		}
		_mm_setcsr(csr);
#elif PPSSPP_ARCH(ARM64)
		u64 fpcr = ARM64ReadFPCR();
		// Translate MIPS to ARM rounding mode
		static const u8 lookup[4] = {0, 3, 1, 2};

		fpcr &= ~(3 << 22);    // Clear bits [23:22]
		fpcr |= ((u64)lookup[rmode] << 22);

		if (ftz) {
			fpcr |= 1 << 24;
		}

		ARM64WriteFPCR(fpcr);
#endif
	}
}

void RestoreHostRoundingMode() {
	// TODO: We should avoid this if we didn't apply rounding in the first place.
	// In the meantime, clear out FTZ and rounding mode bits.
#if PPSSPP_ARCH(SSE2)
	u32 csr = _mm_getcsr();
	csr &= ~(7 << 13);
	_mm_setcsr(csr);
#elif PPSSPP_ARCH(ARM64)
	u64 fpcr = ARM64ReadFPCR();  // not really 64-bit, just to match the register size.
	fpcr &= ~(7 << 22);    // Clear bits [23:22] for rounding, 24 for FTZ
	// Write back the modified FPCR
	ARM64WriteFPCR(fpcr);
#endif
}

static void JoinInto(std::string &str, const std::vector<std::string> &parts, const char *sep) {
	for (size_t i = 0; i < parts.size(); i++) {
		if (i)
			str += sep;
		str += parts[i];
	}
}

std::string str() const {
		if (!isPack)
			return Decl::str();
		std::vector<std::string> parts;
		AppendTo(&parts);
		std::string out;
		JoinInto(out, parts, ", ");
		return out;
	}

void AppendTo(std::vector<std::string> *list) const {
		if (!isPack) {
			list->push_back(Decl::str());
			return;
		}
		for (const Decl &item : items)
			list->push_back(item.str());
	}

void AppendTo(std::vector<Decl> *list) const {
		if (isPack)
			list->insert(list->end(), items.begin(), items.end());
		else
			list->push_back(*this);
	}

static TypeStr MapType(const TypeStr &type, Func func) {
	if (!type.isPack) {
		TypeStr out;
		static_cast<Decl &>(out) = func(static_cast<const Decl &>(type));
		return out;
	}
	TypeStr out;
	out.isPack = true;
	for (const Decl &item : type.items)
		out.items.push_back(func(item));
	return out;
}

static void AppendTemplateArgs(std::string &str, const std::vector<TypeStr> &args) {
	std::vector<std::string> printable;
	for (const TypeStr &arg : args)
		arg.AppendTo(&printable);
	// "operator< <int>", not "operator<<int>".
	if (!str.empty() && str.back() == '<')
		str += ' ';
	str += '<';
	JoinInto(str, printable, ", ");
	if (!str.empty() && str.back() == '>')
		str += ' ';
	str += '>';
}

static std::string BaseName(const std::string &name) {
	std::string base = name.substr(0, name.find('<'));
	base = base.substr(0, base.find('['));  // An abi tag isn't repeated on the ctor either.
	const size_t sep = base.rfind("::");
	return sep == std::string::npos ? base : base.substr(sep + 2);
}

bool ConsumeIf(char c) {
		if (Peek() == c) {
			pos_++;
			return true;
		}
		return false;
	}

bool ConsumeIf(const char *str) {
		const size_t len = strlen(str);
		if (s_.compare(pos_, len, str) == 0) {
			pos_ += len;
			return true;
		}
		return false;
	}

int Demangler::ParseNumber() {
	const bool negative = ConsumeIf('n');
	if (Peek() < '0' || Peek() > '9') {
		Fail();
		return 0;
	}
	int value = 0;
	while (Peek() >= '0' && Peek() <= '9') {
		if (value > 100000000) {  // Absurd length, and keeps the multiply from overflowing.
			Fail();
			return 0;
		}
		value = value * 10 + (s_[pos_++] - '0');
	}
	return negative ? -value : value;
}

int Demangler::ParseSeqId() {
	int value = 0;
	while (true) {
		const char c = Peek();
		int digit;
		if (c >= '0' && c <= '9')
			digit = c - '0';
		else if (c >= 'A' && c <= 'Z')
			digit = c - 'A' + 10;
		else
			break;
		if (value > 10000) {
			Fail();
			return 0;
		}
		value = value * 36 + digit;
		pos_++;
	}
	return value;
}

std::string Demangler::ParseSourceName() {
	const int length = ParseNumber();
	if (failed_ || length <= 0 || pos_ + length > s_.size()) {
		Fail();
		return "";
	}
	std::string name(s_.substr(pos_, length));
	pos_ += length;
	// GCC's spelling for an anonymous namespace, which c++filt prints in the readable form.
	if (name.compare(0, 11, "_GLOBAL__N_") == 0)
		return "(anon)";
	return name;
}

std::string Demangler::ParseAbiTags() {
	std::string tags;
	while (ConsumeIf('B')) {
		const std::string tag = ParseSourceName();
		if (failed_)
			return "";
		tags += "[abi:" + tag + "]";
	}
	return tags;
}

std::string Demangler::ParseOperatorName() {
	if (ConsumeIf("cv")) {
		// Conversion operator - "operator Foo".
		nameHasNoReturnType_ = true;
		const TypeStr type = ParseType();
		if (failed_)
			return "";
		return "operator " + type.str();
	}
	if (ConsumeIf("li")) {
		// Literal operator - operator"" _x.
		const std::string name = ParseSourceName();
		if (failed_)
			return "";
		return "operator\"\" " + name;
	}
	for (const Operator &op : operators) {
		if (Peek() == op.code[0] && Peek(1) == op.code[1]) {
			pos_ += 2;
			return std::string("operator") + op.name;
		}
	}
	Fail();
	return "";
}

std::string Demangler::ParseUnqualifiedName(const std::string &scope) {
	std::string name;
	const char c = Peek();
	if (c >= '0' && c <= '9') {
		name = ParseSourceName();
	} else if (c == 'C') {
		// <ctor-dtor-name> ::= C1 | C2 | C3 | CI1 <type> | CI2 <type>
		pos_++;
		if (Peek() == 'I')
			pos_++;
		if (Peek() < '1' || Peek() > '5') {
			Fail();
			return "";
		}
		pos_++;
		nameHasNoReturnType_ = true;
		name = scope;
	} else if (c == 'D' && Peek(1) >= '0' && Peek(1) <= '5') {
		pos_ += 2;
		nameHasNoReturnType_ = true;
		name = "~" + scope;
	} else if (c == 'U' && Peek(1) == 't') {
		// <unnamed-type-name> ::= Ut [<number>] _
		pos_ += 2;
		const int index = (Peek() >= '0' && Peek() <= '9') ? ParseNumber() : -1;
		if (failed_ || !ConsumeIf('_')) {
			Fail();
			return "";
		}
		char temp[32];
		snprintf(temp, sizeof(temp), "{unnamed type#%d}", index + 2);
		name = temp;
	} else if (c == 'U' && Peek(1) == 'l') {
		// <closure-type-name> ::= Ul <lambda-sig> E [<number>] _
		pos_ += 2;
		std::vector<std::string> params;
		while (!ConsumeIf('E')) {
			if (pos_ >= s_.size()) {
				Fail();
				return "";
			}
			const TypeStr param = ParseType();
			if (failed_)
				return "";
			param.AppendTo(&params);
		}
		if (params.size() == 1 && params[0] == "void")
			params.clear();
		const int index = (Peek() >= '0' && Peek() <= '9') ? ParseNumber() : -1;
		if (failed_ || !ConsumeIf('_')) {
			Fail();
			return "";
		}
		name = "{lambda(";
		JoinInto(name, params, ", ");
		name += ")#" + std::to_string(index + 2) + "}";
	} else if (c == 'L') {
		// Internal-linkage name, GCC extension: L <source-name>
		pos_++;
		name = ParseSourceName();
	} else {
		name = ParseOperatorName();
	}
	if (failed_)
		return "";
	return name + ParseAbiTags();
}

std::string Demangler::ParseNestedName(bool *endsWithTemplateArgs) {
	const DepthGuard guard(this);
	if (failed_)
		return "";
	if (!ConsumeIf('N')) {
		Fail();
		return "";
	}
	bool restrict = ConsumeIf('r');
	bool volatil = ConsumeIf('V');
	bool cnst = ConsumeIf('K');
	if (cnst)
		nameQualifiers_ += " const";
	if (volatil)
		nameQualifiers_ += " volatile";
	if (restrict)
		nameQualifiers_ += " restrict";
	if (ConsumeIf('R'))
		nameQualifiers_ += " &";
	else if (ConsumeIf('O'))
		nameQualifiers_ += " &&";

	std::string soFar;
	// The name of the innermost component so far, which is the class name a C1/D1 refers to.
	std::string lastComponent;
	bool noReturnType = false;
	*endsWithTemplateArgs = false;
	while (!ConsumeIf('E')) {
		if (pos_ >= s_.size()) {
			Fail();
			return "";
		}
		const char c = Peek();
		if (c == 'I') {
			// <template-prefix> <template-args> - applies to what we have so far.
			const std::vector<TypeStr> args = ParseTemplateArgs();
			if (failed_)
				return "";
			if (soFar.empty()) {
				Fail();
				return "";
			}
			AppendTemplateArgs(soFar, args);
			templateArgs_ = args;
			*endsWithTemplateArgs = true;
		} else {
			if (c == 'S') {
				// A substitution can only stand in for the prefix, i.e. come first. Parse
				// it here rather than through ParseType, which would also swallow any
				// following <template-args> and record the combination a second time.
				TypeStr sub;
				bool isBackReference = false;
				if (!ParseSubstitution(&sub, &isBackReference) || !soFar.empty()) {
					Fail();
					return "";
				}
				soFar = sub.str();
				lastComponent = soFar;
				*endsWithTemplateArgs = false;
				if (isBackReference)
					continue;  // Already in the table - re-adding would shift every later S<n>_.
			} else {
				std::string component;
				if (c == 'T') {
					component = ParseTemplateParam().str();
				} else {
					nameHasNoReturnType_ = false;
					component = ParseUnqualifiedName(BaseName(lastComponent));
					noReturnType = nameHasNoReturnType_;
				}
				if (failed_)
					return "";
				lastComponent = component;
				if (!soFar.empty())
					soFar += "::";
				soFar += component;
				*endsWithTemplateArgs = false;
			}
		}
		// Every <prefix> is a substitution candidate, but the complete <nested-name> is
		// only one when it's used as a type - and then our caller in ParseType adds it.
		if (Peek() != 'E')
			subs_.push_back(TypeStr{ soFar, "" });
	}
	// Set last, so that anything nested (template arguments, in particular) can't clobber it.
	nameHasNoReturnType_ = noReturnType;
	return soFar;
}

std::string Demangler::ParseLocalName() {
	if (!ConsumeIf('Z')) {
		Fail();
		return "";
	}
	// The enclosing function has its own qualifier state; don't let it leak out.
	const std::string savedQualifiers = nameQualifiers_;
	nameQualifiers_.clear();
	// c++filt leaves the enclosing function's return type off in this position.
	std::string outer = ParseEncoding(true);
	nameQualifiers_ = savedQualifiers;
	if (failed_ || !ConsumeIf('E'))
		return "";
	std::string inner;
	if (ConsumeIf('s')) {
		inner = "string literal";
	} else {
		bool unusedTemplateArgs = false;
		inner = ParseName(&unusedTemplateArgs);
		if (failed_)
			return "";
	}
	// <discriminator> ::= _ <non-negative number> | __ <number> _ . Purely disambiguating,
	// and c++filt doesn't print it either.
	if (ConsumeIf("__")) {
		ParseNumber();
		ConsumeIf('_');
	} else if (Peek() == '_' && Peek(1) >= '0' && Peek(1) <= '9') {
		pos_++;
		ParseNumber();
	}
	if (failed_)
		return "";
	return outer + "::" + inner;
}

TypeStr Demangler::ParseTemplateParam() {
	if (!ConsumeIf('T')) {
		Fail();
		return TypeStr();
	}
	int index = 0;
	if (Peek() != '_') {
		index = ParseNumber() + 1;
		if (failed_)
			return TypeStr();
	}
	if (!ConsumeIf('_')) {
		Fail();
		return TypeStr();
	}
	if (index < 0 || index >= (int)templateArgs_.size()) {
		Fail();
		return TypeStr();
	}
	return templateArgs_[index];
}

TypeStr Demangler::ParseExprPrimary() {
	if (!ConsumeIf('L')) {
		Fail();
		return TypeStr();
	}
	if (Peek() == '_' && Peek(1) == 'Z') {
		// An external name used as a template argument (function or object pointer).
		const size_t start = pos_;
		while (pos_ < s_.size() && s_[pos_] != 'E')
			pos_++;
		Demangler sub(s_.substr(start, pos_ - start));
		std::string demangled;
		if (!sub.Run(&demangled))
			demangled = std::string(s_.substr(start, pos_ - start));
		if (!ConsumeIf('E')) {
			Fail();
			return TypeStr();
		}
		return TypeStr{ demangled };
	}
	const TypeStr type = ParseType();
	if (failed_)
		return TypeStr();
	const size_t start = pos_;
	while (pos_ < s_.size() && s_[pos_] != 'E')
		pos_++;
	std::string value(s_.substr(start, pos_ - start));
	if (!ConsumeIf('E')) {
		Fail();
		return TypeStr();
	}
	if (value.empty()) {
		Fail();
		return TypeStr();
	}
	if (value[0] == 'n')
		value = "-" + value.substr(1);
	const std::string typeName = type.str();
	if (typeName == "bool")
		return TypeStr{ value == "0" ? "false" : "true" };
	if (typeName == "int")
		return TypeStr{ value };
	if (typeName == "long")
		return TypeStr{ value + "l" };
	if (typeName == "unsigned int")
		return TypeStr{ value + "u" };
	if (typeName == "unsigned long")
		return TypeStr{ value + "ul" };
	return TypeStr{ "(" + typeName + ")" + value };
}

std::vector<TypeStr> Demangler::ParseTemplateArgs() {
	std::vector<TypeStr> args;
	if (!ConsumeIf('I')) {
		Fail();
		return args;
	}
	while (!ConsumeIf('E')) {
		if (pos_ >= s_.size()) {
			Fail();
			return args;
		}
		if (Peek() == 'X') {
			// An arbitrary constant expression. We don't have an expression parser, and
			// guessing would produce nonsense - fail cleanly instead.
			Fail();
			return args;
		} else if (Peek() == 'J') {
			// <template-arg> ::= J <template-arg>* E  (parameter pack)
			pos_++;
			TypeStr pack;
			pack.isPack = true;
			while (!ConsumeIf('E')) {
				if (pos_ >= s_.size()) {
					Fail();
					return args;
				}
				const TypeStr type = ParseType();
				if (failed_)
					return args;
				type.AppendTo(&pack.items);
			}
			args.push_back(pack);
		} else if (Peek() == 'L') {
			args.push_back(ParseExprPrimary());
		} else {
			args.push_back(ParseType());
		}
		if (failed_)
			return args;
	}
	return args;
}

bool Demangler::ParseBuiltinType(std::string *out) {
	const char *name = nullptr;
	switch (Peek()) {
	case 'v': name = "void"; break;
	case 'w': name = "wchar_t"; break;
	case 'b': name = "bool"; break;
	case 'c': name = "char"; break;
	case 'a': name = "signed char"; break;
	case 'h': name = "unsigned char"; break;
	case 's': name = "short"; break;
	case 't': name = "unsigned short"; break;
	case 'i': name = "int"; break;
	case 'j': name = "unsigned int"; break;
	case 'l': name = "long"; break;
	case 'm': name = "unsigned long"; break;
	case 'x': name = "long long"; break;
	case 'y': name = "unsigned long long"; break;
	case 'n': name = "__int128"; break;
	case 'o': name = "unsigned __int128"; break;
	case 'f': name = "float"; break;
	case 'd': name = "double"; break;
	case 'e': name = "long double"; break;
	case 'g': name = "__float128"; break;
	case 'z': name = "..."; break;
	case 'D':
		switch (Peek(1)) {
		case 'a': name = "auto"; break;
		case 'c': name = "decltype(auto)"; break;
		case 'd': name = "decimal64"; break;
		case 'e': name = "decimal128"; break;
		case 'f': name = "decimal32"; break;
		case 'h': name = "half"; break;
		case 'i': name = "char32_t"; break;
		case 's': name = "char16_t"; break;
		case 'n': name = "decltype(nullptr)"; break;
		case 'u': name = "char8_t"; break;
		case 'F': {
			// DF <number> _ is _FloatN, DF <number> x is _FloatNx.
			size_t end = pos_ + 2;
			while (end < s_.size() && s_[end] >= '0' && s_[end] <= '9')
				end++;
			if (end == pos_ + 2 || end >= s_.size() || (s_[end] != '_' && s_[end] != 'x'))
				return false;
			*out = "_Float" + std::string(s_.substr(pos_ + 2, end - pos_ - 2));
			if (s_[end] == 'x')
				*out += 'x';
			pos_ = end + 1;
			return true;
		}
		default: return false;
		}
		pos_ += 2;
		*out = name;
		return true;
	default:
		return false;
	}
	pos_++;
	*out = name;
	return true;
}

bool Demangler::ParseSubstitution(TypeStr *out, bool *isBackReference) {
	pos_++;  // 'S'
	const char abbrev = Peek();
	const char *stdName = nullptr;
	switch (abbrev) {
	case 't': stdName = "std"; break;
	case 'a': stdName = "std::allocator"; break;
	case 'b': stdName = "std::basic_string"; break;
	case 's': stdName = "std::basic_string<char, std::char_traits<char>, std::allocator<char> >"; break;
	case 'i': stdName = "std::basic_istream<char, std::char_traits<char> >"; break;
	case 'o': stdName = "std::basic_ostream<char, std::char_traits<char> >"; break;
	case 'd': stdName = "std::basic_iostream<char, std::char_traits<char> >"; break;
	default: break;
	}
	if (stdName) {
		pos_++;
		out->pre = stdName;
		// St is a namespace prefix: St <unqualified-name>. The combination is a new name,
		// so unlike the other abbreviations it is a substitution candidate.
		*isBackReference = abbrev != 't';
		if (abbrev == 't') {
			const std::string name = ParseUnqualifiedName("");
			if (failed_)
				return false;
			out->pre += "::" + name;
		}
		return true;
	}
	const int index = Peek() == '_' ? 0 : ParseSeqId() + 1;
	if (failed_ || !ConsumeIf('_')) {
		Fail();
		return false;
	}
	if (index < 0 || index >= (int)subs_.size()) {
		Fail();
		return false;
	}
	*out = subs_[index];
	*isBackReference = true;
	return true;
}

std::string Demangler::ParseName(bool *endsWithTemplateArgs) {
	*endsWithTemplateArgs = false;
	const char c = Peek();
	if (c == 'N')
		return ParseNestedName(endsWithTemplateArgs);
	if (c == 'Z')
		return ParseLocalName();

	nameHasNoReturnType_ = false;
	std::string name;
	if (c == 'S') {
		// <unscoped-name> ::= St <unqualified-name>, or a plain <substitution> standing in
		// for the template name. Either way ParseType knows how to read it - but it would
		// also add "St <name>" to the substitution table, which for an <unscoped-name> is
		// wrong, so handle the St case here.
		if (Peek(1) == 't') {
			pos_ += 2;
			name = "std::" + ParseUnqualifiedName("");
			if (failed_)
				return "";
		} else {
			const TypeStr type = ParseType();
			if (failed_)
				return "";
			return type.str();  // Already had its template args applied, if any.
		}
	} else {
		name = ParseUnqualifiedName("");
		if (failed_)
			return "";
	}

	if (Peek() == 'I') {
		// <unscoped-template-name> <template-args> - the template name is a candidate.
		subs_.push_back(TypeStr{ name, "" });
		const std::vector<TypeStr> args = ParseTemplateArgs();
		if (failed_)
			return "";
		AppendTemplateArgs(name, args);
		templateArgs_ = args;
		*endsWithTemplateArgs = true;
	}
	return name;
}

std::string Demangler::ParseBareFunctionParams() {
	std::vector<std::string> params;
	int count = 0;
	while (pos_ < s_.size() && Peek() != 'E' && Peek() != '.') {
		const TypeStr type = ParseType();
		if (failed_)
			return "";
		count++;
		type.AppendTo(&params);
	}
	if (!count) {
		// A function always encodes at least "v" for (void), so this isn't one.
		Fail();
		return "";
	}
	if (params.size() == 1 && params[0] == "void")
		params.clear();
	std::string out = "(";
	JoinInto(out, params, ", ");
	out += ")";
	return out;
}

std::string Demangler::ParseSpecialName() {
	if (ConsumeIf("TV") || ConsumeIf("TT") || ConsumeIf("TI") || ConsumeIf("TS")) {
		const char kind = s_[pos_ - 1];
		const TypeStr type = ParseType();
		if (failed_)
			return "";
		const char *prefix = kind == 'V' ? "vtable for " : (kind == 'T' ? "VTT for " :
			(kind == 'I' ? "typeinfo for " : "typeinfo name for "));
		return prefix + type.str();
	}
	if (ConsumeIf("GTt") || ConsumeIf("GTn")) {
		const bool nonVirtual = s_[pos_ - 1] == 'n';
		const std::string target = ParseEncoding();
		if (failed_)
			return "";
		return (nonVirtual ? "non-transaction clone for " : "transaction clone for ") + target;
	}
	if (ConsumeIf("GV")) {
		bool unused = false;
		const std::string name = ParseName(&unused);
		if (failed_)
			return "";
		return "guard variable for " + name;
	}
	if (ConsumeIf("GR")) {
		bool unused = false;
		const std::string name = ParseName(&unused);
		if (failed_)
			return "";
		// Followed by a seq-id we don't need to print.
		ParseSeqId();
		ConsumeIf('_');
		return "reference temporary for " + name;
	}
	// <call-offset> thunks: Th <offset> _ <encoding>, Tv <offset> _ <offset> _ <encoding>
	if (ConsumeIf("Th") || ConsumeIf("Tv")) {
		const bool virt = s_[pos_ - 1] == 'v';
		ParseNumber();
		if (failed_ || !ConsumeIf('_'))
			return "";
		if (virt) {
			ParseNumber();
			if (failed_ || !ConsumeIf('_'))
				return "";
		}
		const std::string target = ParseEncoding();
		if (failed_)
			return "";
		return (virt ? "virtual thunk to " : "non-virtual thunk to ") + target;
	}
	Fail();
	return "";
}

std::string Demangler::ParseEncoding(bool suppressReturnType) {
	const DepthGuard guard(this);
	if (failed_)
		return "";
	if (Peek() == 'T' || Peek() == 'G')
		return ParseSpecialName();

	// Each encoding has its own qualifier and template-arg scope (local names nest them).
	const std::string savedQualifiers = nameQualifiers_;
	const std::vector<TypeStr> savedTemplateArgs = templateArgs_;
	nameQualifiers_.clear();

	bool endsWithTemplateArgs = false;
	nameHasNoReturnType_ = false;
	const std::string name = ParseName(&endsWithTemplateArgs);
	if (failed_) {
		nameQualifiers_ = savedQualifiers;
		templateArgs_ = savedTemplateArgs;
		return "";
	}

	std::string result;
	if (pos_ >= s_.size() || Peek() == 'E' || Peek() == '.') {
		// <data name>, no function type follows.
		result = name;
	} else {
		std::string returnType;
		if (endsWithTemplateArgs && !nameHasNoReturnType_) {
			// Only templates encode their return type, since it can depend on the args.
			const TypeStr type = ParseType();
			// Still has to be parsed when suppressed, or it'd be read as a parameter.
			if (!failed_ && !suppressReturnType)
				returnType = type.str() + " ";
		}
		const std::string params = failed_ ? "" : ParseBareFunctionParams();
		result = returnType + name + params + nameQualifiers_;
	}

	nameQualifiers_ = savedQualifiers;
	templateArgs_ = savedTemplateArgs;
	return failed_ ? "" : result;
}

bool Demangler::Run(std::string *out) {
	if (s_.size() < 3 || s_[0] != '_' || s_[1] != 'Z')
		return false;
	pos_ = 2;
	std::string result = ParseEncoding();
	if (failed_ || result.empty())
		return false;
	if (pos_ < s_.size()) {
		// GCC appends things like ".constprop.0" or ".isra.0" to clones of a function.
		if (s_[pos_] != '.')
			return false;
		result += " [clone " + std::string(s_.substr(pos_)) + "]";
	}
	*out = result;
	return true;
}

std::string DemangleSymbolName(std::string_view name) {
	std::string out;
	if (DemangleItanium(name, &out))
		return out;
	return std::string(name);
}

bool TestDemangle() {
	for (const DemangleCase &testCase : demangleCases) {
		std::string out;
		if (!DemangleItanium(testCase.mangled, &out)) {
			printf("Failed to demangle %s\n", testCase.mangled);
			return false;
		}
		const std::string expected = testCase.expected;
		EXPECT_EQ_STR(out, expected);
	}

	for (const char *name : notMangled) {
		std::string out = "unchanged";
		EXPECT_FALSE(DemangleItanium(name, &out));
		EXPECT_TRUE(out == "unchanged");
		// The convenience wrapper hands back the original in that case.
		const std::string passedThrough = DemangleSymbolName(name);
		const std::string original = name;
		EXPECT_EQ_STR(passedThrough, original);
	}

	// Deeply nested types must fail on the depth cap rather than blowing the stack.
	std::string out;
	DemangleItanium("_Z3foo" + std::string(10000, 'P') + "i", &out);
	return true;
}

InstallUpdateScreen::InstallUpdateScreen(const Path &path, std::string_view title)
	: UISimpleBaseDialogScreen(Path(), SimpleDialogFlags::ContentsCanScroll), path_(path), title_(title) {
	destination_ = GetSysDirectory(DIRECTORY_NAND);

	File::FileInfo fileInfo;
	if (File::GetFileInfo(path_, &fileInfo)) {
		fileSize_ = fileInfo.size;
	}
	// There's no practical way to merge two firmwares, so an install replaces whatever is there.
	overwrites_ = File::Exists(destination_ / "flash0");
}

void InstallUpdateScreen::CreateDialogViews(UI::ViewGroup *parent) {
	using namespace UI;

	auto di = GetI18NCategory(I18NCat::DIALOG);
	auto iz = GetI18NCategory(I18NCat::INSTALLZIP);
	auto st = GetI18NCategory(I18NCat::STORE);  // Borrow "Size" from here, like GameScreen does.

	LinearLayout *container = parent->Add(new LinearLayout(ORIENT_VERTICAL, new LinearLayoutParams(600, WRAP_CONTENT, 0.0f, UI::Gravity::G_HCENTER, Margins(10))));

	container->Add(new TextView(iz->T("Install PSP firmware update?"), ALIGN_LEFT, false))->SetBig(true);
	container->Add(new Spacer(8.0f));

	if (!title_.empty()) {
		// The updater's own title, which spells out the firmware version.
		container->Add(new TextWithImage(ImageID("I_INFO"), title_));
	}
	container->Add(new TextWithImage(ImageID("I_FILE"), GetFriendlyPath(path_)));
	if (fileSize_ > 0) {
		container->Add(new TextView(StringFromFormat("%s: %s", st->T_cstr("Size"), NiceSizeFormat(fileSize_).c_str())));
	}

	container->Add(new Spacer(12.0f));
	container->Add(new TextView(iz->T("Install into folder")));
	container->Add(new TextView(GetFriendlyPath(destination_)))->SetAlign(FLAG_WRAP_TEXT);

	if (overwrites_) {
		container->Add(new NoticeView(NoticeLevel::WARN, di->T("Confirm Overwrite"), ""));
	}

	container->Add(new Spacer(12.0f));

	installChoice_ = container->Add(new Choice(iz->T("Install"), ImageID("I_FOLDER_UPLOAD")));
	installChoice_->OnClick.Add([this](UI::EventParams &e) {
		StartInstall();
	});

	progressBar_ = container->Add(new ProgressBar());
	progressBar_->SetVisibility(V_GONE);

	resultView_ = container->Add(new NoticeView(NoticeLevel::SUCCESS, "", ""));
	resultView_->SetVisibility(V_GONE);

	// The screen can get recreated mid-install (a rotation, say), so pick the status back up.
	RefreshStatus();
}

void InstallUpdateScreen::StartInstall() {
	if (state_ && !state_->done) {
		// Already running. A previous attempt that failed can be retried, though.
		return;
	}

	state_ = std::make_shared<InstallState>();
	reportedDone_ = false;

	PSARUnpackOptions options;
	options.model = EmulatedModelGeneration();

	INFO_LOG(Log::Loader, "Unpacking the updater %s into %s (model %s)", path_.c_str(),
		destination_.c_str(), PSPModelGenerationToString(options.model));

	g_threadManager.EnqueueTask(new IndependentTask(TaskType::IO_BLOCKING, TaskPriority::NORMAL,
		[state = state_, path = path_, destination = destination_, options]() mutable {
		options.progress = [state](float progress) {
			state->progress = progress;
		};
		state->success = UnpackUpdater(path, destination, options, &state->stats, &state->error);
		if (state->success && state->stats.written == 0) {
			// Nothing came out, so the archive had no file list for the model we asked for -
			// old firmwares predate the later models. Not something to call a success.
			state->success = false;
			if (state->error.empty()) {
				state->error = "The updater has no firmware for this PSP model";
			}
		}
		// Everything above is published by this store - see the atomic in InstallState.
		state->done = true;
	}));

	RefreshStatus();
}

void InstallUpdateScreen::RefreshStatus() {
	using namespace UI;

	auto iz = GetI18NCategory(I18NCat::INSTALLZIP);

	const bool installing = state_ && !state_->done;
	const bool succeeded = state_ && state_->done && state_->success;

	if (installChoice_) {
		// There's no point installing the same firmware twice, but a failure can be retried.
		installChoice_->SetEnabled(!installing && !succeeded);
	}
	if (progressBar_) {
		progressBar_->SetVisibility(installing ? V_VISIBLE : V_GONE);
		if (installing) {
			progressBar_->SetProgress(state_->progress);
		}
	}
	if (resultView_) {
		if (!state_ || !state_->done) {
			resultView_->SetVisibility(V_GONE);
		} else if (state_->success) {
			resultView_->SetLevelAndText(NoticeLevel::SUCCESS, iz->T("Installed!"));
			resultView_->SetDetailsText(StringFromFormat("%s - %d files", state_->stats.firmwareVersion.c_str(), state_->stats.written));
			resultView_->SetVisibility(V_VISIBLE);
		} else {
			resultView_->SetLevelAndText(NoticeLevel::ERROR, iz->T("Installation failed"));
			resultView_->SetDetailsText(state_->error);
			resultView_->SetVisibility(V_VISIBLE);
		}
	}
}

bool InstallUpdateScreen::key(const KeyInput &key) {
	// Ignore key presses while installing, so the user can't escape out mid-write.
	if (state_ && !state_->done) {
		return false;
	}
	return UISimpleBaseDialogScreen::key(key);
}

void InstallUpdateScreen::update() {
	UISimpleBaseDialogScreen::update();

	if (!state_) {
		return;
	}
	if (state_->done && !reportedDone_) {
		reportedDone_ = true;
		if (state_->success) {
			INFO_LOG(Log::Loader, "Installed firmware %s: %d files, %d failed", state_->stats.firmwareVersion.c_str(),
				state_->stats.written, state_->stats.failed);
		} else {
			ERROR_LOG(Log::Loader, "Failed to install the updater: %s", state_->error.c_str());
		}
	}
	RefreshStatus();
}

explicit PRXType9(const u8 *prx)
	{
		memcpy(tag, prx+0xD0, sizeof(tag));
		memset(empty, 0, sizeof(empty));
		// Not copied from prx+0x10C, unlike type 6: it holds the tail of the signature.
		memset(ecdsaSignatureTail, 0, sizeof(ecdsaSignatureTail));
		memcpy(id, prx+0x140, sizeof(id));
		memcpy(sha1, prx+0x12C, sizeof(sha1));
		// kirk header is split between 0x80->0xB0 and 0xC0->0xD0
		memcpy(kirkHeader, prx+0x80, sizeof(kirkHeader)-0x10);
		memcpy(kirkHeader+0x30, prx+0xC0, 0x10);
		memcpy(kirkMetadata, prx+0xB0, sizeof(kirkMetadata));
		memcpy(prxHeader, prx, sizeof(prxHeader));
	}

static int pspDecryptType9(KirkState *kirk, const u8 *inbuf, u8 *outbuf, u32 size)
{
	INFO_LOG(Log::Loader, "Decrypting tag %02X", (u32)*(u32_le *)&inbuf[0xD0]);
	const auto decryptSize = *(s32_le*)&inbuf[0xB0];
	const auto pti = GetTagInfo2((u32)*(u32_le *)&inbuf[0xD0]);

	if (!pti)
	{
		return -1;
	}

	// Only up to 0x104 - past that is the signature, which is present rather than empty here.
	if (std::any_of(inbuf+0xD4, inbuf+0x104, [](u8 x) { return x != 0; }))
	{
		return -2;
	}

	// expand the seed into a xor buffer
	auto xorbuf = expandSeed(pti->key, pti->code);

	PRXType9 type9(inbuf);
	type9.decrypt(pti->code);

	SHA_CTX ctx;
	SHAInit(&ctx);
	SHAUpdate(&ctx, type9.tag, sizeof(type9.tag));
	SHAUpdate(&ctx, xorbuf.data(), 0x10);
	SHAUpdate(&ctx, type9.empty, sizeof(type9.empty));
	SHAUpdate(&ctx, type9.ecdsaSignatureTail, sizeof(type9.ecdsaSignatureTail));
	SHAUpdate(&ctx, type9.id, sizeof(type9.id));
	SHAUpdate(&ctx, type9.kirkHeader, sizeof(type9.kirkHeader));
	SHAUpdate(&ctx, type9.kirkMetadata, sizeof(type9.kirkMetadata));
	SHAUpdate(&ctx, type9.prxHeader, sizeof(type9.prxHeader));

	u8 sha1[0x14];
	SHAFinal(sha1, &ctx);

	if (memcmp(sha1, type9.sha1, sizeof(sha1)) != 0)
	{
		return -3;
	}

	constexpr auto offset = sizeof(PSP_Header)-sizeof(KIRK_CMD1_ECDSA_HEADER)-sizeof(type9.prxHeader);
	KIRK_CMD1_ECDSA_HEADER *header = reinterpret_cast<KIRK_CMD1_ECDSA_HEADER *>(outbuf+offset);

	if (outbuf != inbuf)
	{
		memcpy(outbuf, inbuf, size);
	}

	memset(header, 0, sizeof(KIRK_CMD1_ECDSA_HEADER));
	memcpy(reinterpret_cast<u8*>(&header->data_size), type9.kirkMetadata, sizeof(type9.kirkMetadata));
	memcpy(reinterpret_cast<u8*>(header)+sizeof(KIRK_CMD1_ECDSA_HEADER), type9.prxHeader, sizeof(type9.prxHeader));
	decryptKirkHeader(reinterpret_cast<u8*>(header), type9.kirkHeader, xorbuf.cbegin()+0x10, pti->code);
	header->mode = 1;
	// Left at 0, unlike type 6/7 which set it: type 9 carries a real ECDSA signature that was
	// verified separately, so KIRK is not asked to hash-check this block. JPCSP's equivalent
	// branch only writes the mode word and zeroes the rest of that region.
	header->ecdsa_hash = 0;

	if (kirk_sceUtilsBufferCopyWithRange(kirk, outbuf, size, reinterpret_cast<u8*>(header), size - offset, KIRK_CMD_DECRYPT_PRIVATE) != 0)
	{
		return -4;
	}

	return decryptSize;
}

static int sceResmgr_9DC14891(u32 bufferAddr, int bufferSize, u32 resultLengthAddr) {
	if (bufferSize < 0 || !Memory::IsValidRange(bufferAddr, bufferSize))
		return hleLogError(Log::sceMisc, -1, "bad buffer");

	u8 *buffer = Memory::GetPointerWriteUnchecked(bufferAddr);

	// Already plaintext - the check JPCSP uses, and cheap insurance against decrypting twice.
	if (bufferSize >= 8 && !memcmp(buffer, "release:", 8)) {
		if (Memory::IsValidAddress(resultLengthAddr))
			Memory::WriteUnchecked_U32(bufferSize, resultLengthAddr);
		return hleLogDebug(Log::sceMisc, 0, "already decrypted");
	}

	// Decrypting in place is fine for the caller, but pspDecryptPRX walks the input while writing
	// the output, so give it somewhere separate to write and copy back on success. On failure the
	// guest buffer is left exactly as it was.
	std::vector<u8> decrypted(bufferSize);
	const int decryptedSize = pspDecryptPRX(buffer, decrypted.data(), bufferSize);
	if (decryptedSize <= 0) {
		return hleLogError(Log::sceMisc, -1, "failed to decrypt %d bytes", bufferSize);
	}

	memcpy(buffer, decrypted.data(), decryptedSize);
	NotifyMemInfo(MemBlockFlags::WRITE, bufferAddr, decryptedSize, "sceResmgrDecrypt");
	if (Memory::IsValidAddress(resultLengthAddr))
		Memory::WriteUnchecked_U32(decryptedSize, resultLengthAddr);
	return hleLogInfo(Log::sceMisc, 0, "decrypted %d bytes to %d", bufferSize, decryptedSize);
}

static int sceImposeGetParam(int param) {
	switch (param) {
	case PSP_IMPOSE_MAIN_VOLUME:
		return hleLogDebug(Log::sceUtility, 30);  // Full, on a 0-30 scale.
	case PSP_IMPOSE_BACKLIGHT_BRIGHTNESS:
		return hleLogDebug(Log::sceUtility, 3);
	case PSP_IMPOSE_AVLS:
		return hleLogDebug(Log::sceUtility, imposeAvls);
	case PSP_IMPOSE_MUTE:
	case PSP_IMPOSE_SOUND_REDUCTION:
	case PSP_IMPOSE_BACKLIGHT_OFF_INTERVAL:
		return hleLogDebug(Log::sceUtility, 0);
	default:
		return hleLogDebug(Log::sceUtility, 0, "unmodelled param %08x", param);
	}
}

static int sceImposeSetParam(int param, int value) {
	switch (param) {
	case PSP_IMPOSE_AVLS:
		if (value < 0 || value > 1)
			return hleLogWarning(Log::sceUtility, SCE_KERNEL_ERROR_INVALID_VALUE);
		imposeAvls = value;
		imposeChanges |= PSP_IMPOSE_AVLS | PSP_IMPOSE_MAIN_VOLUME;
		break;
	case PSP_IMPOSE_MAIN_VOLUME:
		if (value < 0 || value >= 31)
			return hleLogWarning(Log::sceUtility, SCE_KERNEL_ERROR_INVALID_VALUE);
		imposeChanges |= PSP_IMPOSE_MAIN_VOLUME;
		break;
	default:
		// Recording the change is the part callers actually observe, through sceImposeChanges.
		imposeChanges |= param;
		break;
	}
	return hleLogDebug(Log::sceUtility, 0);
}

static int sceImposeChanges() {
	const u32 changes = imposeChanges;
	imposeChanges = 0;
	return hleLogDebug(Log::sceUtility, changes);
}

static u32 sceKernelSearchModuleByName(const char *name) {
	if (!name)
		return hleLogError(Log::Loader, SCE_KERNEL_ERROR_ILLEGAL_ADDR, "null name");
	for (SceUID moduleId : loadedModules) {
		u32 error;
		PSPModule *module = kernelObjects.Get<PSPModule>(moduleId, error);
		if (module && !strncmp(module->nm.name, name, ARRAY_SIZE(module->nm.name)))
			return hleLogInfo(Log::Loader, module->GetUID());
	}
	return hleLogWarning(Log::Loader, SCE_KERNEL_ERROR_UNKNOWN_MODULE, "module '%s' not found", name);
}

void ProcessCommand() {
	u8 cmd = g_data[0];

	// Sub-status byte: must not be 0x80 or 0x81 (uofw's Syscon_cmd() treats those as
	// SYSCON_RES_80/81 and retries the whole command) - 0x82 is what JPCSP's own fallback
	// path uses for exactly this reason.
	u8 payload[DATA_SIZE] = { 0x82 };
	int payloadLen = 1;

	switch (cmd) {
	case CMD_READ_CLOCK:
		// No real hardware clock modeled - always reports zero, matching JPCSP's fallback.
		memset(&payload[payloadLen], 0, 4);
		payloadLen += 4;
		break;
	case CMD_READ_ALARM:
		memcpy(&payload[payloadLen], &g_alarm, 4);
		payloadLen += 4;
		break;
	case CMD_WRITE_CLOCK:
		// Not modeled - accept and ignore, same as JPCSP's writeClock().
		break;
	case CMD_WRITE_ALARM:
		memcpy(&g_alarm, &g_data[2], 4);
		break;
	case CMD_NOP:
	default:
		break;
	}

	g_data[0] = kBaryonStatus;
	g_data[1] = (u8)(payloadLen + 2);
	memcpy(&g_data[2], payload, payloadLen);
	u8 sum = 0;
	for (int i = 0; i < g_data[1]; i++)
		sum += g_data[i];
	g_data[g_data[1]] = (u8)~sum;

	g_dataIndex = 0;
	g_responseLen = g_data[1];
	g_dataExhausted = false;

	// Signals "response ready" the way real hardware raising GPIO4 would - see
	// uofw's Syscon_cmd(), which polls exactly this bit after triggering a command.
	GpioMMIO::SetInterruptStatusBits(0x10);
}

static int sceKernelExitVSH(u32 paramPtr) {
	if (Memory::IsValidRange(paramPtr, sizeof(SceKernelLoadExecVSHParam))) {
		auto param = PSPPointer<SceKernelLoadExecVSHParam>::Create(paramPtr);
		INFO_LOG(Log::sceKernel, "sceKernelExitVSH: size=%d, args=%08x, argp=%08x, flags=%08x", param->size, param->args, param->argp, param->flags);
	}

	INFO_LOG(Log::sceKernel, "sceKernelExitVSH");
	__KernelSwitchOffThread("VSH exited");
	Core_Stop();

	g_OSD.Show(OSDType::MESSAGE_INFO, "sceKernelExitVSH()", 0.0f, "kernelexit");
	return hleNoLog(0);
}

static int sceKernelLoadExecBufferVSHUsbWlan(int bufferSize, u32 bufferAddr, u32 paramPtr) {
	if (!Memory::IsValidRange(bufferAddr, bufferSize)) {
		return hleLogError(Log::sceKernel, SCE_KERNEL_ERROR_ILLEGAL_ADDR, "invalid buffer");
	}

	const u8 *data = Memory::GetPointerUnchecked(bufferAddr);
	std::string error_string;
	if (!__KernelLoadExecFromBuffer(currentMIPS, data, (size_t)bufferSize, paramPtr, &error_string)) {
		Core_UpdateState(CORE_RUNTIME_ERROR);
		return hleLogError(Log::sceKernel, -1, "failed: %s", error_string.c_str());
	}
	if (gpu) {
		gpu->Reinitialize();
	}
	return hleLogInfo(Log::sceKernel, 0);
}

bool __KernelLoadExec(MIPSState *mips, const char *filename, u32 paramPtr, std::string *error_string) {
	std::vector<uint8_t> fileData;
	if (pspFileSystem.ReadEntireFile(filename, fileData) < 0) {
		ERROR_LOG(Log::Loader, "Failed to load executable %s - file doesn't exist", filename);
		*error_string = StringFromFormat("Could not find executable %s", filename);
		__KernelShutdown();
		return false;
	}

	return __KernelLoadExecFromPtr(mips, fileData.data(), fileData.size(), filename, paramPtr, error_string);
}

static bool IsVshOnlyModuleName(std::string_view modname) {
	static const char *const vshOnlyModules[] = {
		"sceVshBridge_Driver",
		"scePaf_Module",
		"sceVshCommonGui_Module",
		"sceVshCommonUtil_Module",
	};
	for (const char *name : vshOnlyModules) {
		if (equalsNoCase(modname, name))
			return true;
	}
	return false;
}

static bool ShouldHLEModuleForLoad(std::string_view modname, bool *wasDisabledManually = nullptr) {
	if (g_runningVSH && IsVshOnlyModuleName(modname)) {
		if (wasDisabledManually)
			*wasDisabledManually = false;
		return false;
	}
	return ShouldHLEModule(modname, wasDisabledManually);
}

static void LoadAndStartVshKernelModules() {
	static const char *const vshKernelModulePaths[] = {
		"flash0:/kd/vshbridge.prx",
		"flash0:/vsh/module/paf.prx",
		"flash0:/vsh/module/common_gui.prx",
		"flash0:/vsh/module/common_util.prx",
	};
	for (const char *path : vshKernelModulePaths) {
		std::string error_string;
		SceUID moduleId = KernelLoadModule(path, &error_string);
		if (moduleId < 0) {
			WARN_LOG(Log::sceModule, "LoadAndStartVshKernelModules: failed to load %s: %s", path, error_string.c_str());
			continue;
		}
		int result = __KernelStartModule(moduleId, 0, 0, 0, nullptr, nullptr);
		if (result < 0) {
			WARN_LOG(Log::sceModule, "LoadAndStartVshKernelModules: failed to start %s (uid=%d)", path, moduleId);
		}
	}
}

static s64 DaysFromCivil(s64 y, u32 m, u32 d) {
	y -= m <= 2;
	const s64 era = (y >= 0 ? y : y - 399) / 400;
	const u32 yoe = (u32)(y - era * 400);                    // [0, 399]
	const u32 doy = (153 * (m > 2 ? m - 3 : m + 9) + 2) / 5 + d - 1;  // [0, 365]
	const u32 doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;   // [0, 146096]
	return era * 146097 + (s64)doe - 719468;
}

static s64 UnixTimeFromDirectoryEntry(const DirectoryEntry &dir) {
	if (dir.month < 1 || dir.month > 12 || dir.day < 1 || dir.day > 31) {
		return 0;
	}
	// years is an offset from 1900, and offsetFromGMT is a signed count of 15-minute steps.
	const s64 days = DaysFromCivil(1900 + (s64)dir.years, dir.month, dir.day);
	return days * 86400 + dir.hour * 3600 + dir.minute * 60 + dir.second - (s64)(s8)dir.offsetFromGMT * 15 * 60;
}

static void FillFileTimes(PSPFileInfo *info, s64 unixTime) {
	if (unixTime == 0) {
		return;
	}
	const time_t t = (time_t)unixTime;
	localtime_r(&t, &info->mtime);
	info->atime = info->ctime = info->mtime;
}

static std::string VersionFromSFO(const std::vector<u8> &sfo) {
	const std::string title = TitleFromSFO(sfo);
	if (title.empty()) {
		return std::string();
	}
	return VersionFromUpdaterTitle(title);
// Just the first few bytes, for a magic check. ReadWholeFile isn't an option when the file we're
// sniffing can be a hundred megabytes.
static bool ReadFileMagic(IFileSystem *fs, const std::string &path, u8 *out, size_t size) {
	const int handle = fs->OpenFile(path, FILEACCESS_READ);
	if (handle < 0) {
		return false;
	}
	const size_t read = fs->ReadFile(handle, out, size);
	fs->CloseFile(handle);
	return read == size;
}

std::string BundledUpdateInfo::Describe() const {
	if (!present) {
		return std::string();
	}
	std::string desc = version.empty() ? "?" : version;
	if (mtime != 0) {
		const time_t t = (time_t)mtime;
		tm local{};
		localtime_r(&t, &local);
		desc += StringFromFormat(" (%04d-%02d-%02d)", local.tm_year + 1900, local.tm_mon + 1, local.tm_mday);
	}
	return desc;
}

bool ReadBundledUpdateInfo(IFileSystem *fs, std::string_view pathPrefix, BundledUpdateInfo *info) {
	*info = BundledUpdateInfo{};

	const std::string psarPath = std::string(pathPrefix) + UPDATE_PSAR_SUFFIX;
	const PSPFileInfo psarFileInfo = fs->GetFileInfo(psarPath);
	if (!psarFileInfo.exists || psarFileInfo.size == 0) {
		return false;
	}

	// Check that the file is actually an updater.
	u8 magic[4]{};
	if (!ReadFileMagic(fs, psarPath, magic, sizeof(magic)) || ReadU32(magic) != PSAR_MAGIC) {
		DEBUG_LOG(Log::Loader, "Disc has a %lld byte %s, but it isn't a PSAR - ignoring it",
			(long long)psarFileInfo.size, UPDATE_PSAR_SUFFIX);
		return false;
	}

	info->present = true;
	info->archiveSize = psarFileInfo.size;
	// PSPFileInfo reports local time, since that's what the PSP wants. Back to UTC seconds -
	// mktime is the exact inverse of the localtime_r the file system used. Not every kind of
	// "disc" we can mount records a date at all, hence the check.
	if (psarFileInfo.mtime.tm_mday != 0) {
		tm local = psarFileInfo.mtime;
		const time_t t = mktime(&local);
		info->mtime = t == (time_t)-1 ? 0 : (s64)t;
	}

	std::vector<u8> sfo;
	if (ReadWholeFile(fs, (std::string(pathPrefix) + UPDATE_SFO_SUFFIX).c_str(), &sfo)) {
		info->title = TitleFromSFO(sfo);
		if (!info->title.empty()) {
			info->version = VersionFromUpdaterTitle(info->title);
		}
	}
	return true;
}

static bool ReadFileMagic(IFileSystem *fs, const std::string &path, u8 *out, size_t size) {
	const int handle = fs->OpenFile(path, FILEACCESS_READ);
	if (handle < 0) {
		return false;
	}
	const size_t read = fs->ReadFile(handle, out, size);
	fs->CloseFile(handle);
	return read == size;
}

