void Seek(size_t pos) {
		if (pos > size_)
			Fail();
		else
			pos_ = pos;
	}

uint8_t U8() {
		if (pos_ + 1 > size_)
			return Fail();
		return data_[pos_++];
	}

uint16_t U16() {
		if (pos_ + 2 > size_)
			return Fail();
		uint16_t v;
		memcpy(&v, data_ + pos_, 2);
		pos_ += 2;
		return v;
	}

uint32_t U32() {
		if (pos_ + 4 > size_)
			return Fail();
		uint32_t v;
		memcpy(&v, data_ + pos_, 4);
		pos_ += 4;
		return v;
	}

uint64_t ULEB() {
		uint64_t result = 0;
		int shift = 0;
		for (int i = 0; i < 10; i++) {
			const uint8_t b = U8();
			if (!ok_)
				return 0;
			if (shift < 64)
				result |= (uint64_t)(b & 0x7f) << shift;
			shift += 7;
			if (!(b & 0x80))
				return result;
		}
		return Fail();
	}

int64_t SLEB() {
		int64_t result = 0;
		int shift = 0;
		for (int i = 0; i < 10; i++) {
			const uint8_t b = U8();
			if (!ok_)
				return 0;
			if (shift < 64)
				result |= (int64_t)(b & 0x7f) << shift;
			shift += 7;
			if (!(b & 0x80)) {
				if (shift < 64 && (b & 0x40))
					result -= (int64_t)1 << shift;
				return result;
			}
		}
		return Fail();
	}

std::string Str() {
		const size_t start = pos_;
		while (pos_ < size_ && data_[pos_])
			pos_++;
		if (pos_ >= size_) {
			Fail();
			return std::string();
		}
		std::string s((const char *)data_ + start, pos_ - start);
		pos_++;
		return s;
	}

uint32_t Fail() {
		ok_ = false;
		pos_ = size_;
		return 0;
	}

static bool ParseUnit(Reader &r, size_t unitEnd, std::vector<LineEntry> *entries,
	std::vector<std::string> *files, std::map<std::string, u32> *fileIndex, u32 moduleStart, u32 moduleSize) {
	const uint16_t version = r.U16();
	if (version < 2 || version > 4) {
		// v5 rewrote the file table to use form-coded entries, which is a different parser. Nothing
		// that targets the PSP emits it today (psp-gcc is on 2, Zig on 4), so skip rather than
		// risk decoding it wrong.
		return false;
	}

	const uint32_t headerLength = r.U32();
	const size_t programStart = r.pos() + headerLength;

	const uint8_t minInstLength = r.U8();
	if (version >= 4)
		r.U8();  // maximum_operations_per_instruction
	const uint8_t defaultIsStmt = r.U8();
	(void)defaultIsStmt;
	const int8_t lineBase = (int8_t)r.U8();
	const uint8_t lineRange = r.U8();
	const uint8_t opcodeBase = r.U8();
	if (!r.ok() || lineRange == 0 || minInstLength == 0 || opcodeBase == 0)
		return false;

	std::vector<uint8_t> stdOpcodeLengths(opcodeBase > 0 ? opcodeBase - 1 : 0);
	for (size_t i = 0; i < stdOpcodeLengths.size(); i++)
		stdOpcodeLengths[i] = r.U8();

	// include_directories, then file_names - each a list terminated by an empty string. We only
	// keep the names; the directory index is ignored, since a bare file name is what's actually
	// readable in a status bar or a backtrace.
	while (r.ok() && !r.Str().empty()) {
	}
	// Index 0 is unused in DWARF < 5; entries start at 1.
	std::vector<u32> unitFiles{ 0 };
	while (r.ok()) {
		const std::string name = r.Str();
		if (name.empty())
			break;
		r.ULEB();  // directory index
		r.ULEB();  // modification time
		r.ULEB();  // length
		// Deduped across units so a header included by 500 files is stored once.
		auto it = fileIndex->find(name);
		if (it == fileIndex->end()) {
			it = fileIndex->insert({ name, (u32)files->size() }).first;
			files->push_back(name);
		}
		unitFiles.push_back(it->second);
	}
	if (!r.ok())
		return false;

	r.Seek(programStart);

	u32 address = 0;
	u32 file = 1;
	int line = 1;
	bool sawAddress = false;

	auto emit = [&](u32 lineNo) {
		// Rows before a DW_LNE_set_address belong to no real code; and anything outside the module
		// we're relocating into would only produce bogus lookups.
		if (!sawAddress || address > moduleSize)
			return;
		LineEntry e;
		e.address = moduleStart + address;
		e.line = lineNo;
		e.fileIndex = file < unitFiles.size() ? unitFiles[file] : 0;
		entries->push_back(e);
	};

	while (r.ok() && !r.AtEnd(unitEnd)) {
		const uint8_t op = r.U8();
		if (op >= opcodeBase) {
			// Special opcode: one byte encoding both an address advance and a line delta.
			const uint8_t adjusted = op - opcodeBase;
			address += (adjusted / lineRange) * minInstLength;
			line += lineBase + (adjusted % lineRange);
			emit(line > 0 ? (u32)line : 1);
		} else if (op == 0) {
			// Extended opcode, length-prefixed so unknown ones can be skipped.
			const uint64_t length = r.ULEB();
			const size_t next = r.pos() + (size_t)length;
			const uint8_t sub = r.U8();
			if (sub == DW_LNE_end_sequence) {
				// line 0 terminates the sequence - see the comment on LineEntry::line.
				emit(0);
				address = 0;
				file = 1;
				line = 1;
				sawAddress = false;
			} else if (sub == DW_LNE_set_address) {
				address = r.U32();
				sawAddress = true;
			}
			r.Seek(next);
		} else {
			switch (op) {
			case DW_LNS_copy:
				emit(line > 0 ? (u32)line : 1);
				break;
			case DW_LNS_advance_pc:
				address += (u32)r.ULEB() * minInstLength;
				break;
			case DW_LNS_advance_line:
				line += (int)r.SLEB();
				break;
			case DW_LNS_set_file:
				file = (u32)r.ULEB();
				break;
			case DW_LNS_set_column:
				r.ULEB();
				break;
			case DW_LNS_negate_stmt:
			case DW_LNS_set_basic_block:
				break;
			case DW_LNS_const_add_pc:
				address += ((255 - opcodeBase) / lineRange) * minInstLength;
				break;
			case DW_LNS_fixed_advance_pc:
				address += r.U16();
				break;
			default:
				// Known length, unknown meaning - skip its operands and carry on.
				for (uint8_t i = 0; op - 1 < (int)stdOpcodeLengths.size() && i < stdOpcodeLengths[op - 1]; i++)
					r.ULEB();
				break;
			}
		}
	}

	return r.ok();
}

int LineInfoMap::AddModule(std::string_view elfData, u32 moduleStart, u32 moduleSize) {
	RemoveModule(moduleStart, moduleSize);

	const uint8_t *data = (const uint8_t *)elfData.data();
	const size_t size = elfData.size();
	if (size < sizeof(Elf32_Ehdr))
		return 0;
	if (data[0] != ELFMAG0 || data[1] != ELFMAG1 || data[2] != ELFMAG2 || data[3] != ELFMAG3)
		return 0;

	const Elf32_Ehdr *header = (const Elf32_Ehdr *)data;
	if (header->e_shoff == 0 || header->e_shnum == 0 || header->e_shentsize < sizeof(Elf32_Shdr))
		return 0;
	if ((size_t)header->e_shoff + (size_t)header->e_shnum * header->e_shentsize > size)
		return 0;
	if (header->e_shstrndx >= header->e_shnum)
		return 0;

	auto section = [&](int i) {
		return (const Elf32_Shdr *)(data + header->e_shoff + (size_t)i * header->e_shentsize);
	};

	const Elf32_Shdr *shstr = section(header->e_shstrndx);
	if ((size_t)shstr->sh_offset + shstr->sh_size > size)
		return 0;

	const Elf32_Shdr *debugLine = nullptr;
	for (int i = 0; i < header->e_shnum; i++) {
		const Elf32_Shdr *s = section(i);
		if (s->sh_name >= shstr->sh_size)
			continue;
		const char *name = (const char *)data + shstr->sh_offset + s->sh_name;
		if (!strcmp(name, ".debug_line")) {
			debugLine = s;
			break;
		}
	}
	if (!debugLine || debugLine->sh_size == 0)
		return 0;
	if ((size_t)debugLine->sh_offset + debugLine->sh_size > size)
		return 0;

	ModuleLines mod;
	mod.start = moduleStart;
	mod.size = moduleSize;
	mod.files.push_back("<unknown>");
	std::map<std::string, u32> fileIndex;

	Reader r(data + debugLine->sh_offset, debugLine->sh_size);
	int skippedUnits = 0;
	while (r.ok() && !r.AtEnd(debugLine->sh_size)) {
		const size_t unitStart = r.pos();
		const uint32_t unitLength = r.U32();
		if (!r.ok() || unitLength == 0)
			break;
		// 0xfffffff0 and up are reserved; 0xffffffff introduces 64-bit DWARF, which nothing here
		// produces, and misreading it would walk off into nonsense.
		if (unitLength >= 0xfffffff0)
			break;
		const size_t unitEnd = unitStart + 4 + unitLength;
		if (unitEnd > debugLine->sh_size)
			break;

		if (!ParseUnit(r, unitEnd, &mod.entries, &mod.files, &fileIndex, moduleStart, moduleSize))
			skippedUnits++;
		r.Seek(unitEnd);
	}

	if (skippedUnits > 0) {
		WARN_LOG(Log::Loader, "Line info: skipped %d compilation unit(s) - unsupported DWARF version?", skippedUnits);
	}
	if (mod.entries.empty())
		return 0;

	// Sorted for binary search. Rows at the same address are collapsed to the last one, which is
	// what a debugger wants: the innermost/most recent statement wins, and an end-of-sequence
	// marker sharing an address with the next sequence's first row loses to it.
	std::stable_sort(mod.entries.begin(), mod.entries.end(), [](const LineEntry &a, const LineEntry &b) {
		return a.address < b.address;
	});
	mod.entries.erase(std::unique(mod.entries.begin(), mod.entries.end(), [](const LineEntry &a, const LineEntry &b) {
		return a.address == b.address;
	}), mod.entries.end());

	const int count = (int)mod.entries.size();
	INFO_LOG(Log::Loader, "Line info: %d rows across %d files for module at %08x",
		count, (int)mod.files.size() - 1, moduleStart);
	modules_.push_back(std::move(mod));
	return count;
}

void LineInfoMap::RemoveModule(u32 moduleStart, u32 moduleSize) {
	modules_.erase(std::remove_if(modules_.begin(), modules_.end(), [&](const ModuleLines &m) {
		return m.start == moduleStart && m.size == moduleSize;
	}), modules_.end());
}

const LineInfoMap::ModuleLines *LineInfoMap::FindModule(u32 address) const {
	for (const ModuleLines &m : modules_) {
		if (address >= m.start && address < m.start + m.size)
			return &m;
	}
	return nullptr;
}

bool LineInfoMap::Lookup(u32 address, std::string *file, int *line) const {
	const ModuleLines *mod = FindModule(address);
	if (!mod)
		return false;

	// The row describing an address is the last one at or before it.
	auto it = std::upper_bound(mod->entries.begin(), mod->entries.end(), address,
		[](u32 addr, const LineEntry &e) { return addr < e.address; });
	if (it == mod->entries.begin())
		return false;
	--it;
	if (it->line == 0)
		return false;  // Past the end of that sequence - see LineEntry::line.

	if (file)
		*file = it->fileIndex < mod->files.size() ? mod->files[it->fileIndex] : mod->files[0];
	if (line)
		*line = (int)it->line;
	return true;
}

std::string LineInfoMap::LookupString(u32 address) const {
	std::string file;
	int line = 0;
	if (!Lookup(address, &file, &line))
		return std::string();
	return StringFromFormat("%s:%d", file.c_str(), line);
}

void ImDisasmView::assembleCurrentOpcode(u32 address) {
	char text[256];
	getOpcodeText(address, text, sizeof(text), false);
	assembleOpcode(address, text, true);
}

static bool CheckSpeedControlAllowed(DebuggerRequest &req) {
	if (Achievements::HardcoreModeActive()) {
		req.Fail("Speed control is not allowed in RetroAchievements hardcore mode");
		return false;
	}
	if (!NetworkAllowSpeedControl()) {
		req.Fail("Speed control is not allowed while connected to a network game");
		return false;
	}
	return true;
}

static void WriteSpeedState(JsonWriter &json) {
	json.writeBool("fastForward", PSP_CoreParameter().fastForward);
	if (PSP_CoreParameter().fpsLimit == FPSLimit::DEBUGGER)
		json.writeInt("percent", FpsToPercent(PSP_CoreParameter().debuggerFpsLimit));
	else
		json.writeNull("percent");
	json.writeInt("limitFps", __DisplayGetFrameTimingLimit());
}

void WebSocketGameSpeedGet(DebuggerRequest &req) {
	// Route the reads to the CPU thread - these are what the frame timing consumes there.
	Core_RunOnCPUThread([&] {
		JsonWriter &json = req.Respond();
		WriteSpeedState(json);
	});
}

void WebSocketGameSpeedSet(DebuggerRequest &req) {
	const bool hasFastForward = req.HasParam("fastForward");
	const bool hasPercent = req.HasParam("percent");
	if (!hasFastForward && !hasPercent)
		return req.Fail("Need at least one of 'fastForward' or 'percent'");

	bool fastForward = false;
	if (hasFastForward && !req.ParamBool("fastForward", &fastForward))
		return;

	// An explicit null clears the override; the parameter being absent leaves it alone.
	const bool clearPercent = hasPercent && !req.HasParam("percent", true);
	uint32_t percent = 0;
	if (hasPercent && !clearPercent) {
		if (!req.ParamU32("percent", &percent))
			return;
		if (percent < 1 || percent > 10000)
			return req.Fail("Parameter 'percent' must be between 1 and 10000");
		if (PercentToFps((int)percent) < 1)
			return req.Fail("Parameter 'percent' is too small to produce a frame rate");
	}

	if (!CheckSpeedControlAllowed(req))
		return;

	// Route the writes to the CPU thread instead of poking at them directly from this WebSocket
	// handler thread - see Core_RunOnCPUThread() in Core.h.
	Core_RunOnCPUThread([&] {
		if (hasFastForward)
			PSP_CoreParameter().fastForward = fastForward;

		if (clearPercent) {
			// Only stand down from a limit we set ourselves - the user may have an alternative
			// speed of their own active, and that isn't ours to cancel.
			if (PSP_CoreParameter().fpsLimit == FPSLimit::DEBUGGER)
				PSP_CoreParameter().fpsLimit = FPSLimit::NORMAL;
			PSP_CoreParameter().debuggerFpsLimit = 0;
		} else if (hasPercent) {
			PSP_CoreParameter().debuggerFpsLimit = PercentToFps((int)percent);
			PSP_CoreParameter().fpsLimit = FPSLimit::DEBUGGER;
		}

		JsonWriter &json = req.Respond();
		WriteSpeedState(json);
	});
}

static std::string DescribeMemBlockInfo(const MemBlockInfo &info) {
	std::string flags;
	auto addFlag = [&flags, &info](MemBlockFlags flag, const char *name) {
		if ((uint32_t)(info.flags & flag) == 0)
			return;
		if (!flags.empty())
			flags += "|";
		flags += name;
	};
	addFlag(MemBlockFlags::ALLOC, "ALLOC");
	addFlag(MemBlockFlags::FREE, "FREE");
	addFlag(MemBlockFlags::SUB_ALLOC, "SUB_ALLOC");
	addFlag(MemBlockFlags::SUB_FREE, "SUB_FREE");
	addFlag(MemBlockFlags::WRITE, "WRITE");
	addFlag(MemBlockFlags::READ, "READ");
	addFlag(MemBlockFlags::TEXTURE, "TEXTURE");
	if (flags.empty())
		flags = "none";

	return StringFromFormat(
		"%s\n%08x-%08x (%d bytes)\nPC: %08x\nTicks: %lld\nFlags: %s\nAllocated: %s\n",
		info.tag.c_str(), info.start, info.start + info.size, (int)info.size, info.pc,
		(long long)info.ticks, flags.c_str(), info.allocated ? "yes" : "no");
}

void Core_Break(BreakReason reason, u32 relatedAddress, const BreakpointHit *hit) {
		// Cleared rather than left alone when there's no hit, so the detail from an earlier
		// breakpoint can't be reported against, say, the user pressing pause afterwards.
		if (hit)
			g_breakHit = *hit;
		else
			g_breakHit = BreakpointHit{};
	r.hit = g_breakHit;

static const char *BreakpointKindToString(BreakpointKind kind) {
	switch (kind) {
	case BreakpointKind::Exec: return "exec";
	case BreakpointKind::Memory: return "memory";
	case BreakpointKind::Register: return "register";
	default: return "none";
	}
}

void WriteBreakpointHit(JsonWriter &json, const BreakpointHit &hit) {
	json.pushDict("hit");
	json.writeString("kind", BreakpointKindToString(hit.kind));
	json.writeUint("pc", hit.pc);
	json.writeUint("address", hit.address);
	json.writeUint("hits", hit.numHits);
	json.writeBool("logged", hit.logged);
	json.writeBool("paused", hit.paused);
	if (hit.condition.empty())
		json.writeNull("condition");
	else
		json.writeString("condition", hit.condition);

	// Resolved here rather than left to the client: it's one symbol map lookup at break time, and
	// it saves a round trip at exactly the moment the client is trying to show something.
	const std::string symbol = g_symbolMap->GetDescription(hit.address);
	if (symbol.empty())
		json.writeNull("symbol");
	else
		json.writeString("symbol", symbol);

	if (hit.kind == BreakpointKind::Memory) {
		json.writeInt("size", hit.size);
		json.writeString("access", hit.write ? "write" : "read");
		json.writeString("source", hit.source);
	}
	if (hit.kind == BreakpointKind::Register) {
		json.writeInt("register", hit.reg);
		json.writeString("registerName", MIPSDebugInterface::GetRegName(0, hit.reg));
	}

	// Which breakpoint it was, as opposed to what was touched. Those differ for every memcheck
	// with a range, and this is what matches the entries in cpu.breakpoint.list / etc. A register
	// breakpoint isn't identified by an address at all, so it gets no range rather than a
	// meaningless zero one - "register" above is its identity.
	if (hit.kind == BreakpointKind::Exec || hit.kind == BreakpointKind::Memory) {
		json.pushDict("breakpoint");
		json.writeUint("start", hit.rangeStart);
		json.writeUint("end", hit.rangeEnd);
		json.end();
	}

	json.end();
}

void ImDisasmView::RunToAddress(u32 address, bool nextFrame) {
	g_breakpoints.SetTempBreakPoint(address);

	if (nextFrame) {
		// The flip counter, so "greater than what it is now" means "not until something new has
		// reached the screen". Handy when the address you're interested in is hit many times per
		// frame and you want the next frame's first hit, not this frame's next one.
		//
		// Counting presented frames rather than vblanks matters for a game that doesn't render at
		// the full refresh rate - at 30fps there are two vblanks per frame, so a vblank-based
		// condition would let you through halfway into the frame you're trying to skip.
		//
		// The flip side is that it only advances when the framebuffer actually changed, so if the
		// game has stopped drawing - or is wedged in the loop you're trying to debug - this never
		// trips at all and the core just keeps running.
		BreakPointCond cond;
		cond.debug = currentDebugMIPS;
		cond.expressionString = StringFromFormat("flipcount > %d", __DisplayGetFlipCount());
		if (initExpression(currentDebugMIPS, cond.expressionString.c_str(), cond.expression)) {
			g_breakpoints.SetTempBreakPointCond(cond);
		} else {
			statusBarText_ = "Couldn't compile the frame condition - running without it.";
		}
	}

	g_breakpoints.SetSkipFirst(address);
	if (Core_IsStepping()) {
		Core_Resume();
	}
}

void ImDisasmView::assembleOpcode(u32 address, std::string_view defaultText) {
		statusBarText_ = "Can't assemble while the core is running - pause it first.";

	// Just record what to assemble and where. The popup itself has to be opened from inside the
	// frame that draws it, which is PopupMenu() - see the "assemble" popup there.
	assembleAddress_ = address;
	truncate_cpy(assembleTemp_, defaultText);
	assembleError_.clear();
	assemblePopup_ = true;
}

void WebSocketClientConfigSet(DebuggerRequest &req) {
	JsonWriter &json = req.Respond();

	bool acknowledgeDeferred = req.client->acknowledgeDeferred;
	if (!req.ParamBool("acknowledgeDeferred", &acknowledgeDeferred, DebuggerParamType::OPTIONAL))
		return;
	req.client->acknowledgeDeferred = acknowledgeDeferred;

	json.writeBool("acknowledgeDeferred", req.client->acknowledgeDeferred);
}

static int LoadSymbolsFromCompanion(const std::string &data, u32 moduleBase, u32 moduleSize, const char **why) {
	*why = "too small";
	if (data.size() < sizeof(Elf32_Ehdr))
		return 0;
	const Elf32_Ehdr *header = (const Elf32_Ehdr *)data.data();
	*why = "not an ELF";
	if (header->e_ident[EI_MAG0] != ELFMAG0 || header->e_ident[EI_MAG1] != ELFMAG1
		|| header->e_ident[EI_MAG2] != ELFMAG2 || header->e_ident[EI_MAG3] != ELFMAG3)
		return 0;
	if (header->e_ident[EI_CLASS] != ELFCLASS32)
		return 0;

	*why = "no section headers";
	if (!header->e_shoff || header->e_shentsize < sizeof(Elf32_Shdr))
		return 0;
	if ((size_t)header->e_shoff + (size_t)header->e_shnum * header->e_shentsize > data.size())
		return 0;

	auto section = [&](int i) {
		return (const Elf32_Shdr *)(data.data() + header->e_shoff + (size_t)i * header->e_shentsize);
	};

	// Identity check. The companion links at base 0 and covers the same image the module was
	// built into, so the top of its highest section should land within a page of the module's
	// size. Without this an unrelated ELF sitting in the same folder would happily contribute
	// nonsense names at real addresses, which is worse than having none.
	u32 top = 0;
	int symtabIndex = -1;
	for (int i = 0; i < header->e_shnum; i++) {
		const Elf32_Shdr *s = section(i);
		if (s->sh_addr)
			top = std::max(top, s->sh_addr + s->sh_size);
		if (s->sh_type == SHT_SYMTAB)
			symtabIndex = i;
	}
	*why = "no symbol table";
	if (symtabIndex < 0)
		return 0;
	*why = "image size doesn't match the loaded module";
	if (top > moduleSize || top + 0x1000 < moduleSize)
		return 0;

	const Elf32_Shdr *symtab = section(symtabIndex);
	if (symtab->sh_link >= header->e_shnum || symtab->sh_entsize < sizeof(Elf32_Sym))
		return 0;
	const Elf32_Shdr *strtab = section(symtab->sh_link);
	if ((size_t)symtab->sh_offset + symtab->sh_size > data.size())
		return 0;
	if ((size_t)strtab->sh_offset + strtab->sh_size > data.size())
		return 0;

	const char *strings = data.data() + strtab->sh_offset;
	const int numSymbols = symtab->sh_size / symtab->sh_entsize;
	int added = 0;
	for (int i = 0; i < numSymbols; i++) {
		const Elf32_Sym *sym = (const Elf32_Sym *)(data.data() + symtab->sh_offset + (size_t)i * symtab->sh_entsize);
		if (!sym->st_size || sym->st_name >= strtab->sh_size)
			continue;
		if (sym->st_value > moduleSize)
			continue;
		const char *name = strings + sym->st_name;
		if (!name[0])
			continue;

		const u32 addr = moduleBase + sym->st_value;
		switch (sym->st_info & 0xF) {
		case STT_FUNC:
			// updateName: these are the names a human wrote, so they beat the analyzer's
			// z_un_<address> placeholders rather than losing to whichever got there first.
			g_symbolMap->AddFunction(name, addr, sym->st_size, -1, true);
			added++;
			break;
		case STT_OBJECT:
			g_symbolMap->AddData(addr, sym->st_size, DATATYPE_BYTE);
			g_symbolMap->AddLabel(name, addr, -1, true);
			added++;
			break;
		default:
			break;
		}
	}
	*why = added ? "ok" : "symbol table had nothing usable";
	return added;
}

int LoadCompanionElfSymbols(const Path &gameFile, u32 moduleBase, u32 moduleSize) {
	if (gameFile.empty() || gameFile.Type() != PathType::NATIVE)
		return 0;

	const Path dir = gameFile.NavigateUp();
	std::vector<File::FileInfo> files;
	if (!File::GetFilesInDir(dir, &files, "elf:"))
		return 0;

	for (const File::FileInfo &file : files) {
		if (file.isDirectory || file.size < sizeof(Elf32_Ehdr) || file.size > 256 * 1024 * 1024)
			continue;
		std::string data;
		if (!File::ReadBinaryFileToString(file.fullName, &data))
			continue;
		const char *why = "";
		const int added = LoadSymbolsFromCompanion(data, moduleBase, moduleSize, &why);
		if (added > 0) {
			INFO_LOG(Log::Loader, "Loaded %d symbols from companion ELF '%s'", added, file.name.c_str());
			g_symbolMap->SortSymbols();
			return added;
		}
		DEBUG_LOG(Log::Loader, "Companion ELF '%s' skipped: %s", file.name.c_str(), why);
	}
	return 0;
}

static void RecomputeBreakDeadline() {
	if (!breakDeadlineUs) {
		breakDeadlineTicks = 0;
		return;
	}
	const s64 remainingUs = breakDeadlineUs - (s64)GetGlobalTimeUs();
	breakDeadlineTicks = (s64)GetTicks(currentMIPS) + (remainingUs > 0 ? usToCycles(remainingUs) : 0);
}

void WebSocketSteppingState::RunUntilTime(DebuggerRequest &req) {
	if (!currentDebugMIPS->isAlive()) {
		return req.Fail("CPU not started");
	}

	const bool absolute = req.HasParam("us");
	if (absolute == req.HasParam("relativeUs")) {
		return req.Fail("Pass exactly one of 'us' or 'relativeUs'");
	}

	double requested = 0.0;
	if (!req.ParamF64(absolute ? "us" : "relativeUs", &requested)) {
		// Error already sent.
		return;
	}
	if (requested < 0.0) {
		return req.Fail("Time must not be negative");
	}

	// Route the actual stepping manipulation to the CPU thread instead of poking at it directly
	// from this WebSocket handler thread - see Core_RunOnCPUThread() in Core.h.
	Core_RunOnCPUThread([&] {
		const u64 nowUs = CoreTiming::GetGlobalTimeUs();
		const u64 targetUs = absolute ? (u64)requested : nowUs + (u64)requested;
		if (targetUs <= nowUs) {
			req.Fail("Target time has already passed");
			return;
		}

		CoreTiming::SetBreakDeadlineUs(targetUs);

		PrepareResume();
		Core_Resume();

		JsonWriter &json = req.Respond();
		json.writeFloat("targetUs", (double)targetUs);
		json.writeFloat("us", (double)nowUs);
	});
}

bool DebuggerRequest::ParamF64(const char *name, double *out, DebuggerParamType type) {
	const bool required = type == DebuggerParamType::REQUIRED || type == DebuggerParamType::REQUIRED_LOOSE;

	const JsonNode *node = data.get(name);
	if (!node) {
		if (required)
			Fail(StringFromFormat("Missing '%s' parameter", name));
		return !required;
	}

	const auto tag = node->value.getTag();
	if (tag == JSON_NUMBER) {
		*out = node->value.toNumber();
		return true;
	}
	if (tag == JSON_STRING) {
		// Same escape hatch as the integer params: a string for values a JSON number would mangle.
		const char *s = node->value.toString();
		char *end = nullptr;
		const double val = strtod(s, &end);
		if (end != s && *end == '\0') {
			*out = val;
			return true;
		}
		Fail(StringFromFormat("Could not parse '%s' parameter: number required", name));
		return false;
	}
	if (tag == JSON_NULL && !required) {
		return false;
	}

	Fail(StringFromFormat("Invalid '%s' parameter type", name));
	return false;
}

u64 PeekGlobalTimeUs() {
	// Same sum as above without the rebasing, so this stays callable from a thread that isn't the
	// CPU thread. The rebasing exists purely to keep the multiply below from overflowing, and it
	// happens often enough on the CPU thread that ticksSinceLast stays small here.
	const s64 ticksSinceLast = GetTicks(currentMIPS) - lastGlobalTimeTicks;
	return lastGlobalTimeUs + ticksSinceLast * 1000000 / GetClockFrequencyHz();
}

Path SymbolMap::GetGameSymbolsPath(const std::string &gameID) {
	// The opposite trade-off from GetModuleSymbolsPath: symbols that aren't inside any module are
	// addresses in this game's own RAM layout, so they're worth nothing to any other game.
	// The "_syms" suffix can't be mistaken for a module file, which always ends in _<8 hex digits>.
	return GetSysDirectory(DIRECTORY_SYSTEM) / "SYMBOLS" / StringFromFormat("%s_syms.ppsym", SymbolFileStem(gameID, "unknown").c_str());
}

int SymbolMap::ResolveModuleIndex(u32 address, int moduleIndex) {
	if (moduleIndex == -1) {
		// -1 from a caller means "work it out from the address".
		moduleIndex = GetModuleIndex(address);
		if (moduleIndex < 0) {
			// Not inside any loaded module - the heap, the stack, scratchpad, a hardware
			// register. That's module 0, "absolute address", not an error. Leaving it at -1
			// would file the symbol under a module index that is never active, so it would
			// never reach the active maps: invisible to every lookup and lost on save.
			moduleIndex = 0;
		}
	}
	if (moduleIndex == 0)
		sawUnknownModule = true;
	return moduleIndex;
}

void WebSocketHLEGameSaveSymbols(DebuggerRequest &req) {
	if (!g_symbolMap)
		return req.Fail("CPU not active");

	// Route the actual symbol reads to the CPU thread instead of poking at them directly
	// from this WebSocket handler thread - see Core_RunOnCPUThread() in Core.h.
	Core_RunOnCPUThread([&] {
		const Path path = SymbolMap::GetGameSymbolsPath(g_paramSFO.GetDiscID());
		if (!g_symbolMap->SaveModuleSymbols(0, path, g_paramSFO.GetDiscID(), g_paramSFO.GetValueString("TITLE"))) {
			req.Fail("Failed to save symbols file");
			return;
		}

		JsonWriter &json = req.Respond();
		json.writeString("path", path.ToString());
		// False when there was nothing to save - any previous file has been removed.
		json.writeBool("saved", File::Exists(path));
	});
}

void WebSocketHLEGameLoadSymbols(DebuggerRequest &req) {
	if (!g_symbolMap)
		return req.Fail("CPU not active");

	// Route the actual symbol manipulation to the CPU thread instead of poking at it directly
	// from this WebSocket handler thread - see Core_RunOnCPUThread() in Core.h.
	Core_RunOnCPUThread([&] {
		const Path path = SymbolMap::GetGameSymbolsPath(g_paramSFO.GetDiscID());
		if (!g_symbolMap->LoadModuleSymbols(0, path)) {
			req.Fail("Failed to load symbols file (does it exist?)");
			return;
		}

		// Clear cache so the disassembly view picks up the newly loaded names.
		g_disassemblyManager.clear();

		JsonWriter &json = req.Respond();
		json.writeString("path", path.ToString());
	});
}

static void LoadGameSymbolsIfEnabled() {
	if (!g_symbolMap || !g_Config.bAutoSaveLoadSymbols)
		return;
	g_symbolMap->LoadModuleSymbols(0, SymbolMap::GetGameSymbolsPath(g_paramSFO.GetDiscID()));
}

static void SaveGameSymbolsIfEnabled() {
	if (!g_symbolMap || !g_Config.bAutoSaveLoadSymbols)
		return;
	// Writes nothing (and cleans up any previous file) if there are no such symbols.
	g_symbolMap->SaveModuleSymbols(0, SymbolMap::GetGameSymbolsPath(g_paramSFO.GetDiscID()),
		g_paramSFO.GetDiscID(), g_paramSFO.GetValueString("TITLE"));
}

