void EventFlag::DoState(PointerWrap &p) {
	auto s = p.Section("EventFlag", 1);
	if (!s)
		return;
	Do(p, nef);
	EventFlagTh eft = { 0 };
	Do(p, waitingThreads, eft);
	Do(p, pausedWaits);
}

void MsgPipeWaitingThread::WriteCurrentTimeout(SceUID waitID) const
{
	u32 error;
	if (IsStillWaiting(waitID))
		u32 timeoutPtr = __KernelGetWaitTimeoutPtr(threadID, error);
		if (timeoutPtr != 0 && waitTimer != -1)
			// Remove any event for this thread.
			s64 cyclesLeft = CoreTiming::UnscheduleEvent(waitTimer, threadID);
			Memory::WriteOrException_U32((u32) cyclesToUs(cyclesLeft), timeoutPtr);
}

void MsgPipeWaitingThread::Complete(SceUID waitID, int result) const
{
	if (IsStillWaiting(waitID))
		WriteCurrentTimeout(waitID);
		__KernelResumeThreadFromWait(threadID, result);
}

void MsgPipeWaitingThread::ReadBuffer(u32 destPtr, u32 len)
{
	Memory::Memcpy(destPtr, bufAddr + bufSize - freeSize, len, "MsgPipeReadBuffer");
	freeSize -= len;
	if (transferredBytes.IsValid())
		*transferredBytes += len;
}

void MsgPipeWaitingThread::WriteBuffer(u32 srcPtr, u32 len)
{
	Memory::Memcpy(bufAddr + (bufSize - freeSize), srcPtr, len, "MsgPipeWriteBuffer");
	freeSize -= len;
	if (transferredBytes.IsValid())
		*transferredBytes += len;
}

MsgPipe::~MsgPipe() {
	if (buffer != 0) {
		BlockAllocator *alloc = BlockAllocatorFromAddr(buffer);
		_assert_msg_(alloc != nullptr, "Should always have a valid allocator/address");
		if (alloc)
			alloc->Free(buffer);
}
u32 MsgPipe::GetUsedSize()
	return (u32)(nmp.bufSize - nmp.freeSize);
void MsgPipe::AddWaitingThread(std::vector<MsgPipeWaitingThread> &list, SceUID id, u32 addr, u32 size, int waitMode, u32 transferredBytesAddr)
	MsgPipeWaitingThread thread = { id, addr, size, size, waitMode, { transferredBytesAddr } };
	// Start out with 0 transferred bytes while waiting.
	// TODO: for receive, it might be a different (partial) number.
	if (thread.transferredBytes.IsValid())
		*thread.transferredBytes = 0;
	list.push_back(thread);
}

bool MsgPipe::CheckSendThreads()
{
	SortSendThreads();
	bool wokeThreads = false;
	bool filledSpace = false;
	while (!sendWaitingThreads.empty() && nmp.freeSize > 0)
		MsgPipeWaitingThread *thread = &sendWaitingThreads.front();
		u32 bytesToSend = std::min(thread->freeSize, (u32) nmp.freeSize);
		thread->ReadBuffer(buffer + GetUsedSize(), bytesToSend);
		nmp.freeSize -= bytesToSend;
		filledSpace = true;
		if (thread->waitMode == SCE_KERNEL_MPW_ASAP || thread->freeSize == 0)
			thread->Complete(GetUID(), 0);
			sendWaitingThreads.erase(sendWaitingThreads.begin());
			wokeThreads = true;
			thread = NULL;
		// Unlike receives, we don't do partial sends.  Stop at first blocked thread.
		else
			break;
	}

bool MsgPipe::CheckReceiveThreads()
{
	SortReceiveThreads();

	bool wokeThreads = false;
	bool freedSpace = false;
	while (!receiveWaitingThreads.empty() && GetUsedSize() > 0)
		MsgPipeWaitingThread *thread = &receiveWaitingThreads.front();
		// Receive as much as possible, even if it's not enough to wake up.
		u32 bytesToSend = std::min(thread->freeSize, GetUsedSize());

		u8* ptr = Memory::GetPointerWriteOrException(buffer);
		thread->WriteBuffer(buffer, bytesToSend);
		// Put the unused data at the start of the buffer.
		nmp.freeSize += bytesToSend;
		memmove(ptr, ptr + bytesToSend, GetUsedSize());
		freedSpace = true;
		if (thread->waitMode == SCE_KERNEL_MPW_ASAP || thread->freeSize == 0)
			thread->Complete(GetUID(), 0);
			receiveWaitingThreads.erase(receiveWaitingThreads.begin());
			wokeThreads = true;
			thread = NULL;
		// Stop at the first that can't wake up.
		else
			break;
	if (freedSpace)
		wokeThreads |= CheckSendThreads();
	return wokeThreads;
}

void MsgPipe::SortThreads(std::vector<MsgPipeWaitingThread> &waitingThreads, bool usePrio)
{
	// Clean up any not waiting at the same time.
	HLEKernel::CleanupWaitingThreads(WAITTYPE_MSGPIPE, GetUID(), waitingThreads);
	if (usePrio)
		std::stable_sort(waitingThreads.begin(), waitingThreads.end(), __KernelMsgPipeThreadSortPriority);
}

void MsgPipe::SortReceiveThreads()
{
	bool usePrio = (nmp.attr & SCE_KERNEL_MPA_THPRI_R) != 0;
	SortThreads(receiveWaitingThreads, usePrio);
}

void MsgPipe::SortSendThreads()
{
	bool usePrio = (nmp.attr & SCE_KERNEL_MPA_THPRI_S) != 0;
	SortThreads(sendWaitingThreads, usePrio);
}

void MsgPipe::DoState(PointerWrap &p)
{
	auto s = p.Section("MsgPipe", 1);
	if (!s)
		return;
	Do(p, nmp);
	MsgPipeWaitingThread mpwt1 = {0}, mpwt2 = {0};
	Do(p, sendWaitingThreads, mpwt1);
	Do(p, receiveWaitingThreads, mpwt2);
	Do(p, pausedSendWaits);
	Do(p, pausedReceiveWaits);
	Do(p, buffer);
}

void PSPMutex::DoState(PointerWrap &p) {
	auto s = p.Section("Mutex", 1);
	if (!s)
		return;
	Do(p, nm);
	SceUID dv = 0;
	Do(p, waitingThreads, dv);
	Do(p, pausedWaits);
}

void PSPSemaphore::DoState(PointerWrap &p) {
	auto s = p.Section("Semaphore", 1);
	if (!s)
		return;
	Do(p, ns);
	SceUID dv = 0;
	Do(p, waitingThreads, dv);
	Do(p, pausedWaits);
}

static const char *LogLevelToString(LogLevel level) {
	switch (level) {
	case LogLevel::LNOTICE: return "notice";
	case LogLevel::LERROR: return "error";
	case LogLevel::LWARNING: return "warning";
	case LogLevel::LINFO: return "info";
	case LogLevel::LDEBUG: return "debug";
	case LogLevel::LVERBOSE: return "verbose";
	default: return "unknown";
	}
}

static bool LogLevelFromString(const std::string &s, LogLevel *out) {
	if (s == "notice") *out = LogLevel::LNOTICE;
	else if (s == "error") *out = LogLevel::LERROR;
	else if (s == "warning") *out = LogLevel::LWARNING;
	else if (s == "info") *out = LogLevel::LINFO;
	else if (s == "debug") *out = LogLevel::LDEBUG;
	else if (s == "verbose") *out = LogLevel::LVERBOSE;
	else return false;
	return true;
}

DebuggerSubscriber *WebSocketLogConfigInit(DebuggerEventHandlerMap &map) {
	map["log.channels.list"] = &WebSocketLogChannelsList;
	map["log.channel.set"] = &WebSocketLogChannelSet;
	return nullptr;
}

void WebSocketLogChannelsList(DebuggerRequest &req) {
	JsonWriter &json = req.Respond();
	json.pushArray("channels");
	for (int i = 0; i < LogManager::GetNumChannels(); ++i) {
		Log type = (Log)i;
		const LogChannel *chan = g_logManager.GetLogChannel(type);
		json.pushDict();
		json.writeString("name", LogManager::GetLogTypeName(type));
		json.writeString("level", LogLevelToString(chan->level));
		json.writeBool("enabled", chan->enabled);
		json.pop();
	}
	json.pop();
}

void WebSocketLogChannelSet(DebuggerRequest &req) {
	std::string channelName;
	if (!req.ParamString("channel", &channelName))
		return;

	bool hasLevel = req.HasParam("level");
	LogLevel level = LogLevel::LNOTICE;
	if (hasLevel) {
		std::string levelStr;
		if (!req.ParamString("level", &levelStr, DebuggerParamType::OPTIONAL))
			return;
		if (!LogLevelFromString(levelStr, &level))
			return req.Fail("Invalid 'level', must be notice, error, warning, info, debug, or verbose");
	}
	bool hasEnabled = req.HasParam("enabled");
	bool enabled = false;
	if (hasEnabled && !req.ParamBool("enabled", &enabled, DebuggerParamType::OPTIONAL))
		return;

	if (!hasLevel && !hasEnabled)
		return req.Fail("Must specify 'level' and/or 'enabled'");

	for (int i = 0; i < LogManager::GetNumChannels(); ++i) {
		Log type = (Log)i;
		if (channelName != LogManager::GetLogTypeName(type))
			continue;

		if (hasLevel)
			g_logManager.SetLogLevel(type, level);
		if (hasEnabled)
			g_logManager.SetEnabled(type, enabled);

		const LogChannel *chan = g_logManager.GetLogChannel(type);
		JsonWriter &json = req.Respond();
		json.writeString("name", channelName);
		json.writeString("level", LogLevelToString(chan->level));
		json.writeBool("enabled", chan->enabled);
		return;
	}

	req.Fail("No log channel found with that name");
}

static const char *DataTypeName(DataType type) {
	switch (type) {
	case DATATYPE_BYTE: return "byte";
	case DATATYPE_HALFWORD: return "halfword";
	case DATATYPE_WORD: return "word";
	case DATATYPE_ASCII: return "ascii";
	default: return "byte";
	}
}

static bool DataTypeFromName(const char *s, DataType *out) {
	if (!strcmp(s, "byte")) *out = DATATYPE_BYTE;
	else if (!strcmp(s, "halfword")) *out = DATATYPE_HALFWORD;
	else if (!strcmp(s, "word")) *out = DATATYPE_WORD;
	else if (!strcmp(s, "ascii")) *out = DATATYPE_ASCII;
	else return false;
	return true;
}

static const char *SkipTokens(const char *line, int count) {
	const char *p = line;
	for (int i = 0; i < count; i++) {
		while (*p == ' ' || *p == '\t') p++;
		while (*p && *p != ' ' && *p != '\t') p++;
	}
	while (*p == ' ' || *p == '\t') p++;
	return p;
}

Path SymbolMap::GetModuleSymbolsPath(const std::string &moduleName, u32 crc) {
	// Module names come from untrusted game/homebrew data (the ELF's module-info string) and
	// may contain characters that aren't safe as a filename - replace anything but the basics.
	std::string safeName;
	safeName.reserve(moduleName.size());
	for (char c : moduleName) {
		bool ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '.';
		safeName += ok ? c : '_';
	}
	if (safeName.empty())
		safeName = "module";
	// Deliberately keyed by module name + crc, NOT by game - the exact same module (e.g. a
	// kernel/driver module, or a homebrew's own statically-linked library) commonly gets loaded
	// by many different games/homebrew, and symbols for it are equally valid for all of them.
	return GetSysDirectory(DIRECTORY_SYSTEM) / "SYMBOLS" / StringFromFormat("%s_%08x.ppsym", safeName.c_str(), crc);
}

u32 SymbolMap::GetModuleCrc(int moduleIndex) const {
	for (const auto &module : modules) {
		if (module.index == moduleIndex)
			return module.crc;
	}
	return 0;
}

bool SymbolMap::SaveModuleSymbols(int moduleIndex, const Path &filename, const std::string &gameID, const std::string &gameTitle) const {
	u32 crc = 0;
	bool found = false;
	for (const auto &module : modules) {
		if (module.index == moduleIndex) {
			crc = module.crc;
			found = true;
			break;
		}
	}
	if (!found)
		return false;

	File::CreateFullPath(filename.NavigateUp());
	FILE *f = File::OpenCFile(filename, "w");
	if (!f)
		return false;

	fprintf(f, ".ppsym 1\n");
	fprintf(f, "crc %08x\n", crc);
	// This file may be shared between multiple games that all load this module - this comment
	// just records who saved it most recently, purely for a human's benefit (e.g. to recognize
	// where a set of names came from); it's never read back by LoadModuleSymbols.
	std::string safeTitle = gameTitle;
	std::replace(safeTitle.begin(), safeTitle.end(), '\n', ' ');
	std::replace(safeTitle.begin(), safeTitle.end(), '\r', ' ');
	fprintf(f, "# game %s %s\n", gameID.empty() ? "?" : gameID.c_str(), safeTitle.c_str());

	for (const auto &[key, e] : functions) {
		if (key.first != moduleIndex)
			continue;
		const char *name = GetLabelNameRel(e.start, moduleIndex);
		fprintf(f, "F %08x %08x %s\n", e.start, e.size, name ? name : "");
	}
	for (const auto &[key, e] : data) {
		if (key.first != moduleIndex)
			continue;
		const char *name = GetLabelNameRel(e.start, moduleIndex);
		fprintf(f, "D %08x %08x %s %s\n", e.start, e.size, DataTypeName(e.type), name ? name : "");
	}
	for (const auto &[key, e] : labels) {
		if (key.first != moduleIndex)
			continue;
		// Functions/data already saved their own (function/data-start) label above - only save
		// the remainder here, labels that aren't at a function or data start.
		if (functions.find(key) != functions.end() || data.find(key) != data.end())
			continue;
		fprintf(f, "L %08x %s\n", e.addr, e.name);
	}

	fclose(f);
	return true;
}

bool SymbolMap::LoadModuleSymbols(int moduleIndex, const Path &filename) {
	if (!IsModuleActive(moduleIndex))
		return false;

	FILE *f = File::OpenCFile(filename, "r");
	if (!f)
		return false;

	u32 currentCrc = 0;
	for (const auto &module : modules) {
		if (module.index == moduleIndex) {
			currentCrc = module.crc;
			break;
		}
	}

	char line[512];
	while (fgets(line, sizeof(line), f)) {
		size_t len = strlen(line);
		while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
			line[--len] = '\0';
		if (line[0] == '\0' || line[0] == '#' || !strncmp(line, ".ppsym", 6))
			continue;

		u32 addr, size;
		char field[192];
		if (!strncmp(line, "crc ", 4)) {
			u32 fileCrc = 0;
			if (sscanf(line + 4, "%x", &fileCrc) == 1 && currentCrc != 0 && fileCrc != 0 && fileCrc != currentCrc) {
				WARN_LOG(Log::Loader, "LoadModuleSymbols: crc mismatch for '%s' (file %08x, loaded %08x) - symbols may not match this build of the module", filename.c_str(), fileCrc, currentCrc);
			}
		} else if (line[0] == 'F' && sscanf(line, "F %x %x", &addr, &size) == 2) {
			const char *name = SkipTokens(line, 3);
			std::string autoName;
			if (!name[0]) {
				autoName = StringFromFormat("z_un_%08x", addr);
				name = autoName.c_str();
			}
			AddFunction(name, GetModuleAbsoluteAddr(addr, moduleIndex), size, moduleIndex, true);
		} else if (line[0] == 'D' && sscanf(line, "D %x %x %191s", &addr, &size, field) == 3) {
			DataType type;
			if (!DataTypeFromName(field, &type))
				type = DATATYPE_BYTE;
			u32 absAddr = GetModuleAbsoluteAddr(addr, moduleIndex);
			AddData(absAddr, size, type, moduleIndex);
			const char *name = SkipTokens(line, 4);
			if (name[0])
				AddLabel(name, absAddr, moduleIndex, true);
		} else if (line[0] == 'L' && sscanf(line, "L %x", &addr) == 1) {
			const char *name = SkipTokens(line, 2);
			if (name[0])
				AddLabel(name, GetModuleAbsoluteAddr(addr, moduleIndex), moduleIndex, true);
		}
	}

	fclose(f);
	SortSymbols();
	return true;
}

int SymbolMap::GetModuleIndexByName(const std::string &name) const {
	// Prefer a currently active module if the name is ambiguous (e.g. two distinct modules
	// that happen to share a name - see AddModule's crc handling).
	for (const auto &[key, module] : activeModuleEnds) {
		if (name == module.name)
			return module.index;
	}
	// Not active (or never was) - fall back to the most recently added entry with that name.
	int found = -1;
	for (const auto &module : modules) {
		if (name == module.name)
			found = module.index;
	}
	return found;
}

void SymbolMap::AddLabel(const char* name, u32 address, int moduleIndex, bool updateName) {
		// By default we leave an existing label's name alone, rather than overwriting it (see
		// updateName's doc comment in the header).
		bool nameChanged = false;
		if (updateName && !equals(existing->second.name, name)) {
			truncate_cpy(existing->second.name, name);
			nameChanged = true;
		}

		// We'll still upgrade it to the correct module / relative address.
		}

void WebSocketHLEModuleSaveSymbols(DebuggerRequest &req) {
	if (!g_symbolMap)
		return req.Fail("CPU not active");

	std::string name;
	if (!req.ParamString("name", &name))
		return;

	// Route the actual symbol reads to the CPU thread instead of poking at them directly
	// from this WebSocket handler thread - see Core_RunOnCPUThread() in Core.h.
	Core_RunOnCPUThread([&] {
		int moduleIndex = g_symbolMap->GetModuleIndexByName(name);
		if (moduleIndex <= 0) {
			req.Fail("No module found with that name");
			return;
		}

		Path path = SymbolMap::GetModuleSymbolsPath(name, g_symbolMap->GetModuleCrc(moduleIndex));
		if (!g_symbolMap->SaveModuleSymbols(moduleIndex, path, g_paramSFO.GetDiscID(), g_paramSFO.GetValueString("TITLE"))) {
			req.Fail("Failed to save symbols file");
			return;
		}

		JsonWriter &json = req.Respond();
		json.writeString("path", path.ToString());
	});
}

void WebSocketHLEModuleLoadSymbols(DebuggerRequest &req) {
	if (!g_symbolMap)
		return req.Fail("CPU not active");

	std::string name;
	if (!req.ParamString("name", &name))
		return;

	// Route the actual symbol manipulation to the CPU thread instead of poking at it directly
	// from this WebSocket handler thread - see Core_RunOnCPUThread() in Core.h.
	Core_RunOnCPUThread([&] {
		int moduleIndex = g_symbolMap->GetModuleIndexByName(name);
		if (moduleIndex <= 0 || !g_symbolMap->IsModuleActive(moduleIndex)) {
			req.Fail("No active module found with that name");
			return;
		}

		Path path = SymbolMap::GetModuleSymbolsPath(name, g_symbolMap->GetModuleCrc(moduleIndex));
		if (!g_symbolMap->LoadModuleSymbols(moduleIndex, path)) {
			req.Fail("Failed to load symbols file (does it exist?)");
			return;
		}

		// Clear cache so the disassembly view picks up the newly loaded names.
		g_disassemblyManager.clear();

		JsonWriter &json = req.Respond();
		json.writeString("path", path.ToString());
	});
}

void DoState(PointerWrap &p) {
		PointerWrapSection s = p.Section("TestState", 1, version);
		if (!s)
			return;
		Do(p, a);
		Do(p, name);
		Do(p, values);
		if (s >= 2)
			Do(p, addedInV2);
	}

static bool SerializerWrite(std::vector<u8> *out, Func f) {
	u8 *ptr = nullptr;
	PointerWrap p(&ptr, PointerWrap::MODE_MEASURE);
	f(p);
	if (p.Failed())
		return false;
	// Fill with junk so a field the write pass forgets shows up as garbage rather than zero.
	out->assign(p.Offset(), 0xCD);
	p.RewindForWrite(out->empty() ? nullptr : &(*out)[0]);
	f(p);
	return p.CheckAfterWrite() && !p.Failed();
}

static PointerWrap::Error SerializerRead(const std::vector<u8> &buf, Func f) {
	std::vector<u8> copy = buf;
	u8 *ptr = copy.empty() ? nullptr : &copy[0];
	PointerWrap p(&ptr, PointerWrap::MODE_READ);
	if (!copy.empty())
		p.SetReadEnd(&copy[0] + copy.size());
	f(p);
	return p.error;
}

static std::vector<u8> SerializerBufferWithCount(int count, size_t totalSize) {
	std::vector<u8> buf(totalSize < sizeof(int) ? sizeof(int) : totalSize, 0);
	memcpy(&buf[0], &count, sizeof(int));
	return buf;
}

static bool ValidateAllocator(BlockAllocator &a, u32 rangeStart, u32 rangeSize) {
	u32 addr = rangeStart;
	u32 totalFree = 0;
	u32 largestFree = 0;
	int guard = 0;
	while (addr < rangeStart + rangeSize) {
		const u32 blockStart = a.GetBlockStartFromAddress(addr);
		const u32 blockSize = a.GetBlockSizeFromAddress(addr);
		if (blockStart != addr)
			return false;  // a gap, or the block misreports where it starts
		if (blockSize == 0 || blockSize == (u32)-1)
			return false;
		if ((u64)blockStart + blockSize > (u64)rangeStart + rangeSize)
			return false;  // runs off the end of the range
		if (a.IsBlockFree(addr)) {
			totalFree += blockSize;
			if (blockSize > largestFree)
				largestFree = blockSize;
		}
		addr += blockSize;
		if (++guard > 200000)
			return false;  // cycle in the list
	}
	if (addr != rangeStart + rangeSize)
		return false;  // last block overshot the end
	if (a.GetTotalFreeBytes() != totalFree)
		return false;
	if (a.GetLargestFreeBlockSize() != largestFree)
		return false;
	return true;
}

void SetupCRT(bool suppressDialogs) {
#if defined(_MSC_VER)
	_CrtSetDbgFlag(_CRTDBG_ALLOC_MEM_DF | _CRTDBG_LEAK_CHECK_DF);

	if (suppressDialogs) {
		// 1. Redirect CRT assertions/errors/warnings to stderr.
		const _HFILE reportTarget = _CRTDBG_FILE_STDERR;

		_CrtSetReportMode(_CRT_ASSERT, _CRTDBG_MODE_FILE);
		_CrtSetReportFile(_CRT_ASSERT, reportTarget);

		_CrtSetReportMode(_CRT_ERROR, _CRTDBG_MODE_FILE);
		_CrtSetReportFile(_CRT_ERROR, reportTarget);

		_CrtSetReportMode(_CRT_WARN, _CRTDBG_MODE_FILE);
		_CrtSetReportFile(_CRT_WARN, reportTarget);

		// 2. Suppress the abort() message box & crash reporting dialogs.
		_set_abort_behavior(0, _WRITE_ABORT_MSG | _CALL_REPORTFAULT);

#if !PPSSPP_PLATFORM(UWP)
		// 3. Suppress Windows OS-level "Program has stopped working" modal dialogs.
		SetErrorMode(SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX);
#endif
	}
#endif
}

TEST(geom, right_handed_vector3d_boundary_negation) {
  // Going Vector3D -> RightHandedVector3D negates Y exactly once.
  const Vector3D lh{1.0f, 2.0f, 3.0f};
  const RightHandedVector3D rh{lh};
  ASSERT_FLOAT_EQ(rh.x, 1.0f);
  ASSERT_FLOAT_EQ(rh.y, -2.0f);
  ASSERT_FLOAT_EQ(rh.z, 3.0f);

  // Round-trip back to Vector3D restores the original.
  const Vector3D round_trip = static_cast<Vector3D>(rh);
  ASSERT_FLOAT_EQ(round_trip.x, 1.0f);
  ASSERT_FLOAT_EQ(round_trip.y, 2.0f);
  ASSERT_FLOAT_EQ(round_trip.z, 3.0f);
}

TEST(geom, quaternion_default_is_identity) {
  const Quaternion q;
  ASSERT_FLOAT_EQ(q.x, 0.0f);
  ASSERT_FLOAT_EQ(q.y, 0.0f);
  ASSERT_FLOAT_EQ(q.z, 0.0f);
  ASSERT_FLOAT_EQ(q.w, 1.0f);

  // Identity quaternion rotates a vector to itself.
  const Vector3D v{1.0f, 2.0f, 3.0f};
  const Vector3D out = static_cast<Vector3D>(q.RotatedVector(RightHandedVector3D{v}));
  ASSERT_NEAR(out.x, v.x, 1e-5f);
  ASSERT_NEAR(out.y, v.y, 1e-5f);
  ASSERT_NEAR(out.z, v.z, 1e-5f);
}

TEST(geom, quaternion_get_forward_matches_rotation_get_forward) {
  // The quaternion built from a Rotation must agree with that Rotation's
  // forward-vector for every axis-aligned angle. This is the canonical
  // regression guard against drift between the two math paths.
  constexpr float eps = 1e-4f;
  const float angles[] = {-180.0f, -90.0f, -45.0f, 0.0f, 30.0f, 90.0f, 123.0f, 180.0f};
  for (const float a : angles) {
    for (const auto axis : {0, 1, 2}) {
      Rotation r{};
      if (axis == 0) r.pitch = a;
      else if (axis == 1) r.yaw = a;
      else r.roll = a;

      const Vector3D r_forward = r.GetForwardVector();
      const Vector3D q_forward = Quaternion(r).GetForwardVector();
      EXPECT_NEAR(q_forward.x, r_forward.x, eps) << "axis=" << axis << " angle=" << a;
      EXPECT_NEAR(q_forward.y, r_forward.y, eps) << "axis=" << axis << " angle=" << a;
      EXPECT_NEAR(q_forward.z, r_forward.z, eps) << "axis=" << axis << " angle=" << a;
    }
  }
}

TEST(geom, quaternion_get_yaw_round_trip) {
  // Yaw component of Rotation -> Quaternion -> Rotation must round-trip.
  // Pitch and roll left at zero so the Rotator extraction is unambiguous.
  constexpr float eps = 1e-3f;
  for (float yaw_deg = -150.0f; yaw_deg <= 150.0f; yaw_deg += 30.0f) {
    const Quaternion q{Rotation{0.0f, yaw_deg, 0.0f}};
    const Rotation r = q.Rotator();
    EXPECT_NEAR(r.yaw, yaw_deg, eps) << "yaw=" << yaw_deg;
    EXPECT_NEAR(r.pitch, 0.0f, eps);
    EXPECT_NEAR(r.roll, 0.0f, eps);
  }
}

TEST(geom, quaternion_inverse_is_left_inverse) {
  // q * q^-1 must be the identity for sampled axis-aligned and combined
  // rotations. Tolerances are generous to accommodate float accumulation.
  constexpr float eps = 1e-4f;
  const Rotation samples[] = {
    {0.0f, 0.0f, 0.0f},
    {30.0f, 0.0f, 0.0f},
    {0.0f, 45.0f, 0.0f},
    {0.0f, 0.0f, 60.0f},
    {15.0f, 25.0f, 10.0f},
    {-45.0f, 90.0f, -30.0f},
  };
  for (const auto &r : samples) {
    const Quaternion q{r};
    const Quaternion identity = q * q.Inverse();
    EXPECT_NEAR(identity.x, 0.0f, eps) << r.pitch << "/" << r.yaw << "/" << r.roll;
    EXPECT_NEAR(identity.y, 0.0f, eps);
    EXPECT_NEAR(identity.z, 0.0f, eps);
    EXPECT_NEAR(std::abs(identity.w), 1.0f, eps);
  }
}

TEST(geom, quaternion_pitch_90_forward_is_negative_z) {
  // Regression guard for the pitch/roll fix from the ROS 2 port.
  // Pre-fix the forward vector of pitch=90 was {0, 0, +1}; the corrected
  // sign convention now yields {0, 0, -1}.
  const Quaternion q{Rotation{90.0f, 0.0f, 0.0f}};
  const Vector3D forward = q.GetForwardVector();
  EXPECT_NEAR(forward.x, 0.0f, 1e-5f);
  EXPECT_NEAR(forward.y, 0.0f, 1e-5f);
  EXPECT_NEAR(forward.z, -1.0f, 1e-5f);
}

TEST(geom, velocity_inherits_vector3d_storage) {
  // Velocity is a Vector3D-inheriting POD that carries m/s unit semantics
  // without adding any data members. Wire-compatibility with Vector3D is
  // preserved (msgpack adapter inherited).
  const Velocity v{1.5f, -2.0f, 0.25f};
  EXPECT_FLOAT_EQ(v.x, 1.5f);
  EXPECT_FLOAT_EQ(v.y, -2.0f);
  EXPECT_FLOAT_EQ(v.z, 0.25f);

  // Arithmetic operations inherit from Vector3D.
  const Velocity v2 = Velocity{v + Vector3D{0.5f, 1.0f, 0.0f}};
  EXPECT_FLOAT_EQ(v2.x, 2.0f);
  EXPECT_FLOAT_EQ(v2.y, -1.0f);
  EXPECT_FLOAT_EQ(v2.z, 0.25f);
}

TEST(geom, angular_velocity_and_acceleration_inherit_vector3d_storage) {
  const AngularVelocity w{45.0f, 0.0f, 0.0f};
  EXPECT_FLOAT_EQ(w.x, 45.0f);
  EXPECT_FLOAT_EQ(w.y, 0.0f);

  const Acceleration a{0.0f, 9.81f, 0.0f};
  EXPECT_FLOAT_EQ(a.y, 9.81f);

  // The new types are layout-compatible with Vector3D so the
  // serialization wire format stays unchanged.
  static_assert(sizeof(Velocity) == sizeof(Vector3D),
                "Velocity must stay layout-compatible with Vector3D");
  static_assert(sizeof(AngularVelocity) == sizeof(Vector3D),
                "AngularVelocity must stay layout-compatible with Vector3D");
  static_assert(sizeof(Acceleration) == sizeof(Vector3D),
                "Acceleration must stay layout-compatible with Vector3D");
}

TEST(geom, quaternion_basis_vectors_for_identity) {
  // Identity quaternion's three basis vectors must be the canonical
  // CARLA left-handed axes.
  constexpr float eps = 1e-5f;
  const Quaternion q;

  const Vector3D forward = q.GetForwardVector();
  EXPECT_NEAR(forward.x, 1.0f, eps);
  EXPECT_NEAR(forward.y, 0.0f, eps);
  EXPECT_NEAR(forward.z, 0.0f, eps);

  const Vector3D right = q.GetRightVector();
  EXPECT_NEAR(right.x, 0.0f, eps);
  EXPECT_NEAR(right.y, 1.0f, eps);
  EXPECT_NEAR(right.z, 0.0f, eps);

  const Vector3D up = q.GetUpVector();
  EXPECT_NEAR(up.x, 0.0f, eps);
  EXPECT_NEAR(up.y, 0.0f, eps);
  EXPECT_NEAR(up.z, 1.0f, eps);
}

TEST(geom, quaternion_basis_vectors_for_yaw_90) {
  // Yaw=90 deg in CARLA's left-handed convention sends:
  //   forward (+X) -> (+Y), right (+Y) -> (-X), up (+Z) -> (+Z).
  constexpr float eps = 1e-4f;
  const Quaternion q{Rotation{0.0f, 90.0f, 0.0f}};

  const Vector3D forward = q.GetForwardVector();
  EXPECT_NEAR(forward.x, 0.0f, eps);
  EXPECT_NEAR(forward.y, 1.0f, eps);
  EXPECT_NEAR(forward.z, 0.0f, eps);

  const Vector3D right = q.GetRightVector();
  EXPECT_NEAR(right.x, -1.0f, eps);
  EXPECT_NEAR(right.y, 0.0f, eps);
  EXPECT_NEAR(right.z, 0.0f, eps);

  const Vector3D up = q.GetUpVector();
  EXPECT_NEAR(up.x, 0.0f, eps);
  EXPECT_NEAR(up.y, 0.0f, eps);
  EXPECT_NEAR(up.z, 1.0f, eps);
}

TEST(geom, quaternion_hamilton_product_yaw_compose) {
  // Two consecutive yaw=45 rotations compose to a yaw=90 rotation:
  // applying the product to the forward axis sends (1,0,0) -> (0,1,0).
  constexpr float eps = 1e-4f;
  const Quaternion q45{Rotation{0.0f, 45.0f, 0.0f}};
  const Quaternion q90 = q45 * q45;

  const Vector3D forward = q90.GetForwardVector();
  EXPECT_NEAR(forward.x, 0.0f, eps);
  EXPECT_NEAR(forward.y, 1.0f, eps);
  EXPECT_NEAR(forward.z, 0.0f, eps);
}

TEST(geom, quaternion_conjugate_equals_inverse_for_unit_quaternion) {
  // For a unit quaternion built from any Rotation, conjugate and inverse
  // are mathematically identical. Sample a few axis-aligned and combined
  // rotations.
  constexpr float eps = 1e-5f;
  const Rotation samples[] = {
    {0.0f, 0.0f, 0.0f},
    {30.0f, 0.0f, 0.0f},
    {0.0f, 45.0f, 0.0f},
    {0.0f, 0.0f, 60.0f},
    {15.0f, 25.0f, 10.0f},
  };
  for (const auto &r : samples) {
    const Quaternion q{r};
    const Quaternion qc = q.Conjugate();
    const Quaternion qi = q.Inverse();
    EXPECT_NEAR(qc.x, qi.x, eps) << r.pitch << "/" << r.yaw << "/" << r.roll;
    EXPECT_NEAR(qc.y, qi.y, eps);
    EXPECT_NEAR(qc.z, qi.z, eps);
    EXPECT_NEAR(qc.w, qi.w, eps);
  }
}

void ROS2::UnregisterVehicle(void *actor) {
  _subscribers.erase(actor);
