  auto it = _last_transforms.find(child_frame_id);
  if (it != _last_transforms.end()
      && IsSameTransform(it->second, tx, ty, tz, pitch_deg, yaw_deg, roll_deg)) {
    translation = it->second.translation;
    rotation = it->second.rotation;
  } else {
