AShaderBasedSensor_WideAngleLens::AShaderBasedSensor_WideAngleLens(const FObjectInitializer& ObjectInitializer) :
    Super(ObjectInitializer)
{
    EnablePostProcessingEffects(false);
}

bool AShaderBasedSensor_WideAngleLens::AddPostProcessingMaterial(const FString& Path)
{
    // ConstructorHelpers::FObjectFinder is documented as constructor-only and
    // has undefined behavior when used from runtime functions. FSoftObjectPath
    // is the runtime-safe path resolver; it accepts both plain object paths
    // and the class-prefixed export-text form ("Material'/Game/.../Foo'") that
    // FObjectFinder previously normalised internally.
    UMaterial* Material = Cast<UMaterial>(FSoftObjectPath(Path).TryLoad());
    if (Material != nullptr)
    {
        MaterialsFound.Add(Material);
        return true;
    }
    UE_LOG(LogCarla, Error,
        TEXT("AShaderBasedSensor_WideAngleLens::AddPostProcessingMaterial: failed to load material '%s'"),
        *Path);
    return false;
}

void AShaderBasedSensor_WideAngleLens::SetUpSceneCaptureComponents(TArrayView<USceneCaptureComponent2D_CARLA*> SceneCaptures)
{
    // Create one dynamic instance per post-processing material. The six face
    // captures of a wide-angle sensor must share an identical post-process
    // chain, so the instances are created once and reused across all faces.
    // Creating them inside the per-face loop would append 6x the materials to
    // the shared Shaders array and give each face a different blendable set.
    for (const auto& MaterialFound : MaterialsFound)
    {
        // Create a dynamic instance of the Material (Shader)
        AddShader({ UMaterialInstanceDynamic::Create(MaterialFound, this), 1.0 });
    }

    for (auto SceneCapture : SceneCaptures)
    {
        for (const auto& Shader : Shaders)
        {
            // Attach the instance into the blendables
            SceneCapture->PostProcessSettings.AddBlendable(Shader.PostProcessMaterial, Shader.Weight);
        }
    }

    // Set the value for each Float parameter in the shader. The dynamic
    // material instances are shared across faces, so each parameter only
    // needs to be applied once.
    if (Shaders.Num() != 0)
    {
        for (const auto& ParameterValue : FloatShaderParams)
        {
            Shaders[ParameterValue.ShaderIndex].PostProcessMaterial->SetScalarParameterValue(
                ParameterValue.ParameterName,
                ParameterValue.Value);
        }
    }
}

void AShaderBasedSensor_WideAngleLens::Set(const FActorDescription& Description)
{
    Super::Set(Description);
    UActorBlueprintFunctionLibrary::SetCamera(Description, this);
}

void AShaderBasedSensor_WideAngleLens::SetFloatShaderParameter(
    uint8_t ShaderIndex,
    const FName& ParameterName,
    float Value)
{
    FloatShaderParams.Add({ ShaderIndex, ParameterName, Value });
}

GraphBuilder.AddPass(
        RDG_EVENT_NAME("ToPerspective-Dispatch"),
        Parameters,
        ERDGPassFlags::Compute,
        [Parameters, Size](FRHICommandListImmediate& RHICmdList)
        {
            TShaderMapRef<FShaderType> ComputeShader(GetGlobalShaderMap(GMaxRHIFeatureLevel));
            check(ComputeShader.IsValid());

            FComputeShaderUtils::Dispatch(RHICmdList, ComputeShader, *Parameters,
                FComputeShaderUtils::GetGroupCount(
                    FIntVector(Size.X, Size.Y, 1),
                    FIntVector(SubgroupSize * WorkPerInvocation, 1, 1)));
        }

float ComputeCameraPolynomial(
            float Theta,
            TArrayView<const float> Coefficients)
        {
            auto Result = 1.0F;
            auto Theta2 = Theta * Theta;
            auto ThetaN = 1.0F;

            for (auto K : Coefficients)
            {
                ThetaN *= Theta2;
                Result += K * ThetaN;
            }

            return Result * Theta;
        }

float ComputeCameraPolynomialDerivative(
            float Theta,
            TArrayView<const float> Coefficients)
        {
            auto Result = 1.0F;
            auto Theta2 = Theta * Theta;
            auto ThetaN = Theta2;
            auto A = 3.0F;

            for (auto K : Coefficients)
            {
                Result += A * K * ThetaN;
                A += 2.0F;
                ThetaN *= Theta2;
            }

            return Result;
        }

float ComputeAngle(
        ECameraModel CameraModel,
        float Distance,
        TArrayView<const float> Coefficients)
    {
        switch (CameraModel)
        {
        case ECameraModel::Perspective:
            return std::atan(Distance);
        case ECameraModel::Stereographic:
            return std::atan(Distance * 0.5F) * 2;
        case ECameraModel::Equidistant:
            return Distance;
        case ECameraModel::Equisolid:
            return std::asin(FMath::Clamp(Distance * 0.5F, -1.0F, 1.0F)) * 2;
        case ECameraModel::Orthographic:
            return std::asin(FMath::Clamp(Distance, -1.0F, 1.0F));
        case ECameraModel::KannalaBrandt:
        {
            float Theta = Distance;
            for (uint8 i = 0; i != KannalaBrandtSolverIterations; ++i)
            {
                float N = Distance - KannalaBrandt::ComputeCameraPolynomial(Theta, Coefficients);
                float D = -KannalaBrandt::ComputeCameraPolynomialDerivative(Theta, Coefficients);
                Theta -= N / D;
            }
            return Theta;
        }
        default:
            check(false);
            return 0.0F;
        }
    }

float ComputeDistance(
        ECameraModel CameraModel,
        float Angle,
        int32 ImageHeight,
        TArrayView<const float> Coefficients)
    {
        const auto H = static_cast<float>(ImageHeight);
        const auto R = H * 0.5F;
        float F = 0.0F;

        Angle *= 0.5F;
        switch (CameraModel)
        {
        case ECameraModel::Perspective:
            F = R / std::tan(Angle);
            break;
        case ECameraModel::Stereographic:
            F = R / (std::tan(Angle * 0.5F) * 2);
            break;
        case ECameraModel::Equidistant:
            F = R / Angle;
            break;
        case ECameraModel::Equisolid:
            F = R / (std::sin(Angle * 0.5F) * 2);
            break;
        case ECameraModel::Orthographic:
            F = R / std::sin(Angle);
            break;
        case ECameraModel::KannalaBrandt:
            F = R / KannalaBrandt::ComputeCameraPolynomial(Angle, Coefficients);
            break;
        default:
            check(false);
            break;
        }
        return F;
    }

void DistortCubemapToImage(
        FRDGBuilder& GraphBuilder,
        UTextureRenderTarget2D* Destination,
        UTextureRenderTarget2D** CubeRenderTargets,
        FRHISamplerState* Sampler,
        const FDistortCubemapToImageOptions& Options)
    {
        FTexture2DRHIRef TextureRHIs[6] = {};

        for (uint8 i = 0; i != 6; ++i)
        {
            TextureRHIs[i] = CubeRenderTargets[i]
                ->GetRenderTargetResource()
                ->GetTextureRenderTarget2DResource()
                ->GetTextureRHI();
        }

        auto DestinationRHI = Destination
            ->GetRenderTargetResource()
            ->GetTextureRenderTarget2DResource()
            ->GetTextureRHI();

        TRefCountPtr<IPooledRenderTarget> PRTs[] =
        {
            CreateRenderTarget(TextureRHIs[0], TEXT("CubeTextures[0]")),
            CreateRenderTarget(TextureRHIs[1], TEXT("CubeTextures[1]")),
            CreateRenderTarget(TextureRHIs[2], TEXT("CubeTextures[2]")),
            CreateRenderTarget(TextureRHIs[3], TEXT("CubeTextures[3]")),
            CreateRenderTarget(TextureRHIs[4], TEXT("CubeTextures[4]")),
            CreateRenderTarget(TextureRHIs[5], TEXT("CubeTextures[5]"))
        };

        auto CaptureRenderTargetTexture = GraphBuilder.RegisterExternalTexture(
            CreateRenderTarget(DestinationRHI, TEXT("CaptureRenderTargetTexture")));

        FRDGTextureRef CubeTextures[6] = { };

        for (uint8 i = 0; i != 6; ++i)
        {
            CubeTextures[i] = GraphBuilder.RegisterExternalTexture(PRTs[i]);
        }

        DistortCubemapToImage(
            GraphBuilder,
            CaptureRenderTargetTexture,
            CubeTextures,
            Sampler,
            Options);
    }

FRHISamplerState* GetSampler(ESamplerFilter Filter)
    {
        switch (Filter)
        {

            case SF_Point:
                return TStaticSamplerState<	SF_Point>::GetRHI();
            case SF_Bilinear:
                return TStaticSamplerState<	SF_Bilinear>::GetRHI();
            case SF_Trilinear:
                return TStaticSamplerState<	SF_Trilinear>::GetRHI();
            case SF_AnisotropicPoint:
                return TStaticSamplerState<	SF_AnisotropicPoint>::GetRHI();
            case SF_AnisotropicLinear:
                return TStaticSamplerState<	SF_AnisotropicLinear>::GetRHI();
            default:
                check(false);
                return nullptr;
        }
    }

to &RandomChoice(const RangeT &range, RNG &rng) {
    if (range.empty()) {
      throw std::runtime_error("RandomChoice: empty range");
    }
    std::uniform_int_distribution<size_t> dist{0u, range.size() - 1u};
    return range[dist(rng)];
  }

n::BehaviorAgent::Behavior ParseBehavior(const std::string &name) {
    if (name == "cautious")   return can::BehaviorAgent::Behavior::Cautious;
    if (name == "aggressive") return can::BehaviorAgent::Behavior::Aggressive;
    return can::BehaviorAgent::Behavior::Normal;
  }

gs ParseArgs(int argc, char **argv) {
    Args a;
    if (argc >= 2) a.host = argv[1];
    if (argc >= 3) a.port = static_cast<uint16_t>(std::stoi(argv[2]));
    if (argc >= 4) a.map  = argv[3];
    if (argc >= 5) a.behavior = argv[4];
    return a;
  }

t main(int argc, char **argv) try {
  std::signal(SIGINT,  HandleSigint);
  std::signal(SIGTERM, HandleSigint);

  const auto args = ParseArgs(argc, argv);

  std::mt19937_64 rng{std::random_device{}()};

  cc::Client client(args.host, args.port);
  client.SetTimeout(40s);
  std::cout << "Client " << client.GetClientVersion()
            << "  ↔  Server " << client.GetServerVersion() << "\n";

  // Use the currently loaded world unless the user asked for a specific map.
  auto world = args.map.empty() ? client.GetWorld()
                                : client.LoadWorld(args.map);
  std::cout << "Map: " << world.GetMap()->GetName() << "\n";

  // Spawn a vehicle at a random valid spawn point.
  auto map         = world.GetMap();
  auto spawn_pts   = map->GetRecommendedSpawnPoints();
  if (spawn_pts.empty()) {
    throw std::runtime_error("No spawn points available on this map");
  }
  auto spawn_tx    = RandomChoice(spawn_pts, rng);

  // Prefer agile cars over trucks/vans for the demo — large vehicles get
  // stuck on tight corners while the agent is still warming up.
  auto bp_library  = world.GetBlueprintLibrary();
  auto vehicles_bp = bp_library->Filter("vehicle.tesla.model3");
  if (vehicles_bp->size() == 0) {
    vehicles_bp = bp_library->Filter("vehicle.audi.*");
  }
  if (vehicles_bp->size() == 0) {
    vehicles_bp = bp_library->Filter("vehicle.*");
  }
  if (vehicles_bp->size() == 0) {
    throw std::runtime_error("No vehicle blueprints in this build");
  }
  auto bp          = RandomChoice(*vehicles_bp, rng);

  auto actor       = world.SpawnActor(bp, spawn_tx);
  auto vehicle     = std::dynamic_pointer_cast<cc::Vehicle>(actor);
  if (!vehicle) {
    actor->Destroy();
    throw std::runtime_error("Spawned actor is not a Vehicle");
  }
  std::cout << "Spawned " << vehicle->GetDisplayId()
            << " at (" << spawn_tx.location.x << ", " << spawn_tx.location.y
            << ", " << spawn_tx.location.z << ")\n";

  // Let physics settle so the vehicle is grounded before the agent engages.
  for (int i = 0; i < 5; ++i) world.WaitForTick(2s);

  // Pick a destination meaningfully ahead of the spawn (positive dot with
  // forward vector). This avoids the agent trying a low-speed U-turn from
  // its first step, which is what saturates the lateral PID and pins the
  // vehicle against geometry.
  const auto fwd = spawn_tx.GetForwardVector();
  cg::Transform dest_tx = spawn_tx;
  float best_score = -1.0f;
  for (int tries = 0; tries < 64; ++tries) {
    const auto &cand = RandomChoice(spawn_pts, rng);
    const float dx = cand.location.x - spawn_tx.location.x;
    const float dy = cand.location.y - spawn_tx.location.y;
    const float dist = std::sqrt(dx * dx + dy * dy);
    if (dist < 80.0f || dist > 400.0f) continue;
    const float forward_dot = (dx * fwd.x + dy * fwd.y) / dist;
    if (forward_dot < 0.2f) continue;     // require destination broadly ahead
    // Score combines forward bias and reasonable distance.
    const float score = forward_dot * std::min(dist, 300.0f);
    if (score > best_score) {
      best_score = score;
      dest_tx    = cand;
    }
  }
  if (best_score < 0.0f) {
    // Fall back: any spawn point >50m away that is at least vaguely ahead.
    for (const auto &cand : spawn_pts) {
      if (cand.location.Distance(spawn_tx.location) > 50.0f) {
        dest_tx = cand;
        break;
      }
    }
  }
  std::cout << "Destination: ("
            << dest_tx.location.x << ", " << dest_tx.location.y
            << ", " << dest_tx.location.z << ")\n";

  // Wrap with BehaviorAgent.
  auto behavior = ParseBehavior(args.behavior);
  std::cout << "Behavior:    " << args.behavior << "\n";
  can::BehaviorAgent agent(vehicle, behavior);
  agent.SetDestination(dest_tx.location);
  std::cout << "Agent route set; entering control loop. Ctrl-C to stop.\n";

  auto spectator = world.GetSpectator();

  size_t step = 0;
  while (!g_stop && !agent.Done()) {
    // Wait for the next server tick (works in both sync and async modes).
    world.WaitForTick(2s);

    // Run one step of the agent and apply.
    auto control = agent.RunStep();
    vehicle->ApplyControl(control);

    // Chase camera: 6m behind, 2.5m up, slight pitch down, looking forward.
    auto vt = vehicle->GetTransform();
    cg::Transform cam = vt;
    cam.location -= 6.0f * vt.GetForwardVector();
    cam.location.z += 2.5f;
    cam.rotation.pitch = -10.0f;
    spectator->SetTransform(cam);

    if (++step % 50 == 0) {
      const auto &v = vehicle->GetVelocity();
      const float speed_kmh =
          3.6f * std::sqrt(v.x*v.x + v.y*v.y + v.z*v.z);
      std::cout << "  step " << step << "  throttle=" << control.throttle
                << " brake=" << control.brake << " steer=" << control.steer
                << "  speed=" << speed_kmh << " km/h\n";
    }
  }

  if (agent.Done()) {
    std::cout << "Agent reached destination after " << step << " steps.\n";
  } else {
    std::cout << "Stopped by user after " << step << " steps.\n";
  }

  vehicle->Destroy();
  std::cout << "Vehicle destroyed.\n";
  return 0;
} catch (const cc::TimeoutException &e) {
  std::cerr << "carla-agent-demo: timeout: " << e.what() << "\n";
  return 1;
} catch (const std::exception &e) {
  std::cerr << "carla-agent-demo: " << e.what() << "\n";
  return 2;
}

std::tuple<std::string, uint16_t> ParseEndpoint(int argc, const char *argv[]) {
    if (!((argc == 1) || (argc == 3))) {
      throw std::runtime_error("Usage: carla-example-client [host port]");
    }

    if (argc == 1) {
      return std::make_tuple(std::string{"localhost"}, static_cast<uint16_t>(2000u));
    }

    return std::make_tuple(std::string{argv[1]}, static_cast<uint16_t>(std::stoi(argv[2])));
  }

int main() try {
  carla::client::Client client("localhost", 2000);
  client.SetTimeout(std::chrono::seconds(10));

  std::cout << "Connected to CARLA " << client.GetServerVersion() << "\n";
  std::cout << "Available maps:";
  for (const auto &m : client.GetAvailableMaps()) {
    std::cout << "\n  " << m;
  }
  std::cout << '\n';
  return 0;
} catch (const std::exception &e) {
  std::cerr << "carla-cpp-standalone: " << e.what() << '\n';
  return 1;
}

idget *buildToolUi(QDockWidget *owner) {
  QWidget *root = new QWidget(owner);
  QVBoxLayout *rootLayout = new QVBoxLayout(root);

  QLabel *title = new QLabel(QStringLiteral("Example community tool"), root);
  title->setStyleSheet(QStringLiteral("font-weight: 700; font-size: 14px;"));
  rootLayout->addWidget(title);

  QLabel *intro = new QLabel(
    QStringLiteral(
      "Replace this dock's contents with anything your tool exposes. "
      "This same widget is usable standalone or docked inside CARLA Studio."),
    root);
  intro->setWordWrap(true);
  rootLayout->addWidget(intro);

  QGroupBox *inputsGroup = new QGroupBox(QStringLiteral("Inputs"), root);
  QVBoxLayout *inputsLayout = new QVBoxLayout(inputsGroup);
  QLineEdit *label = new QLineEdit(inputsGroup);
  label->setPlaceholderText(QStringLiteral("Tag to stamp into the log"));
  inputsLayout->addWidget(label);
  QCheckBox *verbose = new QCheckBox(QStringLiteral("Verbose timestamps"), inputsGroup);
  inputsLayout->addWidget(verbose);
  rootLayout->addWidget(inputsGroup);

  QHBoxLayout *buttons = new QHBoxLayout();
  QPushButton *stamp = new QPushButton(QStringLiteral("Stamp log"), root);
  QPushButton *clear = new QPushButton(QStringLiteral("Clear"), root);
  buttons->addWidget(stamp);
  buttons->addWidget(clear);
  buttons->addStretch();
  rootLayout->addLayout(buttons);

  QPlainTextEdit *log = new QPlainTextEdit(root);
  log->setReadOnly(true);
  log->setPlaceholderText(QStringLiteral("Log output appears here."));
  rootLayout->addWidget(log, 1);

  QObject::connect(stamp, &QPushButton::clicked, log, [log, label, verbose]() {
    const QString tag = label->text().trimmed().isEmpty()
      ? QStringLiteral("event")
      : label->text().trimmed();
    const QString ts = verbose->isChecked()
      ? QDateTime::currentDateTime().toString(Qt::ISODateWithMs)
      : QDateTime::currentDateTime().toString(Qt::ISODate);
    log->appendPlainText(QStringLiteral("[%1] %2").arg(ts, tag));
  });
  QObject::connect(clear, &QPushButton::clicked, log, &QPlainTextEdit::clear);

  return root;
}

ockWidget *createExampleToolDock(QWidget *parent) {
  QDockWidget *dock = new QDockWidget(QStringLiteral("Example Tool"), parent);
  dock->setObjectName(QStringLiteral("CarlaStudio.ExampleCommunityTool"));
  dock->setFeatures(QDockWidget::DockWidgetMovable |
                    QDockWidget::DockWidgetFloatable |
                    QDockWidget::DockWidgetClosable);
  dock->setAllowedAreas(Qt::AllDockWidgetAreas);
  dock->setWidget(buildToolUi(dock));
  return dock;
}

t main(int argc, char *argv[]) {
  QApplication app(argc, argv);
  app.setApplicationName(QStringLiteral("CARLA Studio Example Tool"));

  QMainWindow window;
  window.setWindowTitle(QStringLiteral("CARLA Studio Example Tool (standalone)"));
  window.resize(640, 480);
  window.setDockOptions(QMainWindow::AllowTabbedDocks |
                        QMainWindow::AllowNestedDocks |
                        QMainWindow::AnimatedDocks);

  QDockWidget *dock = createExampleToolDock(&window);
  window.addDockWidget(Qt::LeftDockWidgetArea, dock);

  window.show();
  return app.exec();
}
#

inline bool LaneChangeAllows(LaneChange lc, bool want_left) {
  // bitwise: Right=0x01, Left=0x02, Both=0x03.
  if (want_left) {
    return lc == LaneChange::Left || lc == LaneChange::Both;
  }
  return lc == LaneChange::Right || lc == LaneChange::Both;
}

BasicAgent::BasicAgent(SharedPtr<client::Vehicle> vehicle,
                       float target_speed_kmh,
                       const Options &options,
                       SharedPtr<client::Map> map,
                       SharedPtr<GlobalRoutePlanner> grp)
    : _vehicle(std::move(vehicle)),
      _last_traffic_light(nullptr),
      _ignore_traffic_lights(options.ignore_traffic_lights),
      _ignore_stop_signs(options.ignore_stop_signs),
      _ignore_vehicles(options.ignore_vehicles),
      _use_bbs_detection(options.use_bbs_detection),
      _target_speed(target_speed_kmh),
      _sampling_resolution(options.sampling_resolution),
      _base_tlight_threshold(options.base_tlight_threshold),
      _base_vehicle_threshold(options.base_vehicle_threshold),
      _speed_ratio(options.detection_speed_ratio),
      _max_brake(options.max_brake),
      _offset(options.offset) {

  // World is a value type in LibCarla — wrap it in a SharedPtr to match the
  // Python-side `self._world` reference semantics that BehaviorAgent expects.
  _world = SharedPtr<client::World>(new client::World(_vehicle->GetWorld()));

  _map = map ? map : _world->GetMap();

  // Forward the (possibly customised) options into the local planner. The
  // caller passes target_speed via the dedicated arg, so propagate it through
  // a copy of the LocalPlanner::Options slice.
  LocalPlanner::Options lp_opts = static_cast<const LocalPlanner::Options &>(options);
  lp_opts.target_speed = target_speed_kmh;
  _local_planner = std::make_unique<LocalPlanner>(_vehicle, lp_opts, _map);

  if (grp) {
    _global_planner = grp;
  } else {
    _global_planner = SharedPtr<GlobalRoutePlanner>(
        new GlobalRoutePlanner(_map, static_cast<double>(_sampling_resolution)));
  }

  // Cache the static traffic-light list (mirrors Python __init__).
  _lights_list = _world->GetActors()->Filter("*traffic_light*");
}

c::VehicleControl BasicAgent::AddEmergencyStop(rpc::VehicleControl c) const {
  c.throttle   = 0.0f;
  c.brake      = _max_brake;
  c.hand_brake = false;
  return c;
}

id BasicAgent::SetDestination(const geom::Location &end,
                                std::optional<geom::Location> start) {
  geom::Location start_location;
  bool clean_queue;
  if (!start.has_value()) {
    auto target_wpt = _local_planner->TargetWaypoint();
    // LocalPlanner::_target_waypoint is seeded via Map::GetWaypoint(), which
    // can return nullptr (e.g. vehicle starts off-road, or the planner has
    // not been re-targeted since construction). Fall back to the vehicle's
    // current location so a route can still be planned.
    if (target_wpt) {
      start_location = target_wpt->GetTransform().location;
    } else {
      start_location = _vehicle->GetLocation();
    }
    clean_queue = true;
  } else {
    start_location = *start;  // Use the provided start location
    clean_queue = false;
  }

  auto start_wp = _map->GetWaypoint(start_location);
  auto end_wp   = _map->GetWaypoint(end);

  auto plan = TraceRoute(start_wp, end_wp);
  _local_planner->SetGlobalPlan(plan, /*stop_waypoint_creation=*/true, clean_queue);
}

id BasicAgent::SetGlobalPlan(const std::vector<LocalPlanner::PlanItem> &plan,
                               bool stop_waypoint_creation,
                               bool clean_queue) {
  _local_planner->SetGlobalPlan(plan, stop_waypoint_creation, clean_queue);
}

d::vector<LocalPlanner::PlanItem>
BasicAgent::TraceRoute(SharedPtr<client::Waypoint> start,
                       SharedPtr<client::Waypoint> end) {
  if (!start || !end) return {};  // Null check before dereference
  const auto &start_loc = start->GetTransform().location;
  const auto &end_loc   = end->GetTransform().location;
  return _global_planner->TraceRoute(start_loc, end_loc);
}

c::VehicleControl BasicAgent::RunStep() {
  bool hazard_detected = false;

  // Pull all relevant actors from the world.
  auto vehicle_list = _world->GetActors()->Filter("*vehicle*");

  const float vehicle_speed_ms = GetSpeed(_vehicle) / 3.6f;

  // Vehicles in front?
  const float max_vehicle_distance =
      _base_vehicle_threshold + _speed_ratio * vehicle_speed_ms;
  auto v_obs = VehicleObstacleDetected(vehicle_list, max_vehicle_distance);
  if (v_obs.affected) {
    hazard_detected = true;
  }

  // Red light?
  const float max_tlight_distance =
      _base_tlight_threshold + _speed_ratio * vehicle_speed_ms;
  auto tl_pair = AffectedByTrafficLight(_lights_list, max_tlight_distance);
  if (tl_pair.first) {
    hazard_detected = true;
  }

  rpc::VehicleControl control = _local_planner->RunStep();
  if (hazard_detected) {
    control = AddEmergencyStop(control);
  }
  return control;
}

id BasicAgent::LaneChange(const std::string &direction,
                            float same_lane_time,
                            float other_lane_time,
                            float lane_change_time) {
  const float speed = _vehicle->GetVelocity().Length();
  auto path = GenerateLaneChangePath(
      _map->GetWaypoint(_vehicle->GetLocation()),
      direction,
      same_lane_time * speed,
      other_lane_time * speed,
      lane_change_time * speed,
      /*check=*/false,
      /*lane_changes=*/1,
      _sampling_resolution);
  if (path.empty()) {
    // Match the Python warning behaviour: log and still call set_global_plan
    // (Python falls through). Keeping silent here — no logger dep needed.
  }
  SetGlobalPlan(path);
}

//

:pair<bool, SharedPtr<client::TrafficLight>>
BasicAgent::AffectedByTrafficLight(SharedPtr<client::ActorList> lights_list,
                                   std::optional<float> max_distance_opt) {
  if (_ignore_traffic_lights) {
    return {false, nullptr};
  }

  if (!lights_list) {
    lights_list = _world->GetActors()->Filter("*traffic_light*");
  }

  const float max_distance =
      max_distance_opt.value_or(_base_tlight_threshold);

  if (_last_traffic_light) {
    if (_last_traffic_light->GetState() != rpc::TrafficLightState::Red) {
      _last_traffic_light = nullptr;
    } else {
      return {true, _last_traffic_light};
    }
  }

  const auto ego_location = _vehicle->GetLocation();
  auto ego_wpt = _map->GetWaypoint(ego_location);
  if (!ego_wpt) {
    // Vehicle is not on a road waypoint (off-road, mid-air, etc.); no
    // road-based traffic-light association can be computed.
    return {false, nullptr};
  }

  for (auto actor : *lights_list) {
    auto traffic_light =
        std::dynamic_pointer_cast<client::TrafficLight>(actor);
    if (!traffic_light) {
      continue;
    }

    const uint32_t tl_id = static_cast<uint32_t>(traffic_light->GetId());

    SharedPtr<client::Waypoint> trigger_wp;
    auto it = _lights_map.find(tl_id);
    if (it != _lights_map.end()) {
      trigger_wp = it->second;
    } else {
      const auto trigger_location =
          GetTrafficLightTriggerLocation(traffic_light);
      trigger_wp = _map->GetWaypoint(trigger_location);
      _lights_map.emplace(tl_id, trigger_wp);
    }

    if (!trigger_wp) {
      // Trigger box for this light isn't on the road network — it can't
      // affect an on-road vehicle. Skip (and the null cache entry above
      // makes subsequent lookups short-circuit at the same point).
      continue;
    }

    if (trigger_wp->GetTransform().location.Distance(ego_location) > max_distance) {
      continue;
    }

    if (trigger_wp->GetRoadId() != ego_wpt->GetRoadId()) {
      continue;
    }

    const auto ve_dir = ego_wpt->GetTransform().GetForwardVector();
    const auto wp_dir = trigger_wp->GetTransform().GetForwardVector();
    const float dot_ve_wp = ve_dir.x * wp_dir.x + ve_dir.y * wp_dir.y + ve_dir.z * wp_dir.z;
    if (dot_ve_wp < 0.0f) {
      continue;
    }

    if (traffic_light->GetState() != rpc::TrafficLightState::Red) {
      continue;
    }

    if (IsWithinDistance(trigger_wp->GetTransform(),
                         _vehicle->GetTransform(),
                         max_distance,
                         std::make_pair(0.0f, 90.0f))) {
      _last_traffic_light = traffic_light;
      return {true, traffic_light};
    }
  }

  return {false, nullptr};
}

// -

ector<LocalPlanner::PlanItem> BasicAgent::GenerateLaneChangePath(
    SharedPtr<client::Waypoint> waypoint,
    const std::string &direction,
    float distance_same_lane,
    float distance_other_lane,
    float lane_change_distance,
    bool  check,
    int   lane_changes,
    float step_distance) {

  distance_same_lane    = std::max(distance_same_lane, 0.1f);
  distance_other_lane   = std::max(distance_other_lane, 0.1f);
  lane_change_distance  = std::max(lane_change_distance, 0.1f);

  std::vector<LocalPlanner::PlanItem> plan;
  plan.emplace_back(waypoint, RoadOption::LaneFollow);

  RoadOption option = RoadOption::LaneFollow;

  // Same lane stretch.
  {
    float distance = 0.0f;
    while (distance < distance_same_lane) {
      auto next_wps = plan.back().first->GetNext(step_distance);
      if (next_wps.empty()) return {};
      auto next_wp = next_wps.front();
      distance += static_cast<float>(
          next_wp->GetTransform().location.Distance(
              plan.back().first->GetTransform().location));
      plan.emplace_back(next_wp, RoadOption::LaneFollow);
    }
  }

  bool want_left;
  if (direction == "left") {
    option = RoadOption::ChangeLaneLeft;
    want_left = true;
  } else if (direction == "right") {
    option = RoadOption::ChangeLaneRight;
    want_left = false;
  } else {
    return {};
  }

  int lane_changes_done = 0;
  const float per_change_distance =
      lane_change_distance / static_cast<float>(std::max(lane_changes, 1));

  // Lane change steps.
  while (lane_changes_done < lane_changes) {
    auto next_wps = plan.back().first->GetNext(per_change_distance);
    if (next_wps.empty()) return {};
    auto next_wp = next_wps.front();

    SharedPtr<client::Waypoint> side_wp;
    if (want_left) {
      if (check && !LaneChangeAllows(next_wp->GetLaneChange(), /*want_left=*/true)) {
        return {};
      }
      side_wp = next_wp->GetLeft();
    } else {
      if (check && !LaneChangeAllows(next_wp->GetLaneChange(), /*want_left=*/false)) {
        return {};
      }
      side_wp = next_wp->GetRight();
    }

    if (!side_wp || side_wp->GetType() != LaneType::Driving) {
      return {};
    }

    plan.emplace_back(side_wp, option);
    ++lane_changes_done;
  }

  // Other lane stretch.
  {
    float distance = 0.0f;
    while (distance < distance_other_lane) {
      auto next_wps = plan.back().first->GetNext(step_distance);
      if (next_wps.empty()) return {};
      auto next_wp = next_wps.front();
      distance += static_cast<float>(
          next_wp->GetTransform().location.Distance(
              plan.back().first->GetTransform().location));
      plan.emplace_back(next_wp, RoadOption::LaneFollow);
    }
  }

  return plan;
}

} //

BehaviorParameters BehaviorParamsFor(BehaviorAgent::Behavior b) {
    switch (b) {
      case BehaviorAgent::Behavior::Cautious:   return BehaviorParameters::Cautious();
      case BehaviorAgent::Behavior::Aggressive: return BehaviorParameters::Aggressive();
      case BehaviorAgent::Behavior::Normal:
      default:                                  return BehaviorParameters::Normal();
    }
  }

BehaviorAgent::BehaviorAgent(SharedPtr<client::Vehicle> vehicle,
                             Behavior behavior,
                             const Options &opts,
                             SharedPtr<client::Map> map,
                             SharedPtr<GlobalRoutePlanner> grp)
  : BasicAgent(vehicle, /*target_speed_kmh=*/20.0f, opts, map, grp),
    _behavior(BehaviorParamsFor(behavior)) {
  // Match the Python BehaviorAgent override of the sampling resolution.
  _sampling_resolution = 4.5f;
}

void BehaviorAgent::UpdateInformation() {
  _speed = GetSpeed(_vehicle);
  _speed_limit = _vehicle->GetSpeedLimit();
  // Even when follow_speed_limits is on this seed mirrors the Python reference.
  _local_planner->SetSpeed(_speed_limit);

  _direction = _local_planner->TargetRoadOption();
  if (_direction == RoadOption::Void) {
    _direction = RoadOption::LaneFollow;
  }

  _look_ahead_steps = static_cast<int>(_speed_limit / 10.0f);

  auto incoming = _local_planner->GetIncomingWaypointAndDirection(_look_ahead_steps);
  _incoming_waypoint = incoming.first;
  _incoming_direction = incoming.second;
  if (_incoming_direction == RoadOption::Void) {
    _incoming_direction = RoadOption::LaneFollow;
  }
}

bool BehaviorAgent::TrafficLightManager() {
  auto actor_list = _world->GetActors();
  auto lights_list = actor_list ? actor_list->Filter("*traffic_light*") : nullptr;
  auto result = AffectedByTrafficLight(lights_list);
  return result.first;
}

void BehaviorAgent::Tailgating(SharedPtr<client::Waypoint> waypoint) {
  // Python passes the prefiltered vehicle list around; the base helper
  // `VehicleObstacleDetected` accepts a `SharedPtr<ActorList>` and applies
  // its own proximity gating via `max_distance`, so we hand it the
  // world-wide vehicle filter result here.
  auto left_marking = waypoint->GetLeftLaneMarking();
  auto right_marking = waypoint->GetRightLaneMarking();
  auto left_wpt = waypoint->GetLeft();
  auto right_wpt = waypoint->GetRight();

  // Build the world-vehicle ActorList passthrough (matches Python's reuse of
  // the filtered list).
  auto vehicles_alist = _world->GetActors()
      ? _world->GetActors()->Filter("*vehicle*")
      : nullptr;

  const float behind_max =
      std::max(_behavior.min_proximity_threshold, _speed_limit / 2.0f);

  auto behind = VehicleObstacleDetected(vehicles_alist,
                                        behind_max,
                                        /*up_angle_th=*/180.0f,
                                        /*low_angle_th=*/160.0f,
                                        /*lane_offset=*/0);

  if (!(behind.affected && behind.actor)) return;
  if (_speed >= GetSpeed(behind.actor)) return;

  const int wp_lane_id = waypoint->GetLaneId();

  // Right-lane tailgate avoidance.
  if (right_marking.has_value() && right_wpt &&
      (HasLaneChange(right_marking->lane_change, LaneChange::Right) ||
       HasLaneChange(right_marking->lane_change, LaneChange::Both)) &&
      (wp_lane_id * right_wpt->GetLaneId() > 0) &&
      right_wpt->GetType() == road::Lane::LaneType::Driving) {
    auto check = VehicleObstacleDetected(vehicles_alist,
                                         behind_max,
                                         /*up_angle_th=*/180.0f,
                                         /*low_angle_th=*/0.0f,
                                         /*lane_offset=*/1);
    if (!check.affected) {
      std::cout << "Tailgating, moving to the right!" << std::endl;
      auto end_waypoint = _local_planner->TargetWaypoint();
      _behavior.tailgate_counter = 200;
      if (end_waypoint) {
        SetDestination(end_waypoint->GetTransform().location,
                       right_wpt->GetTransform().location);
      }
    }
    return;
  }

  // Left-lane tailgate avoidance.
  if (left_marking.has_value() && left_wpt &&
      HasLaneChange(left_marking->lane_change, LaneChange::Left) &&
      (wp_lane_id * left_wpt->GetLaneId() > 0) &&
      left_wpt->GetType() == road::Lane::LaneType::Driving) {
    auto check = VehicleObstacleDetected(vehicles_alist,
                                         behind_max,
                                         /*up_angle_th=*/180.0f,
                                         /*low_angle_th=*/0.0f,
                                         /*lane_offset=*/-1);
    if (!check.affected) {
      std::cout << "Tailgating, moving to the left!" << std::endl;
      auto end_waypoint = _local_planner->TargetWaypoint();
      _behavior.tailgate_counter = 200;
      if (end_waypoint) {
        SetDestination(end_waypoint->GetTransform().location,
                       left_wpt->GetTransform().location);
      }
    }
  }
}

BasicAgent::VehicleObstacle BehaviorAgent::CollisionAndCarAvoidManager(
    SharedPtr<client::Waypoint> waypoint) {
  auto vehicles_alist = _world->GetActors()
      ? _world->GetActors()->Filter("*vehicle*")
      : nullptr;

  // Python applies a 45 m prefilter around the waypoint here (excluding the
  // ego). The base helper `VehicleObstacleDetected` honors `max_distance`
  // internally, so we just route the world-wide vehicle list to it.
  VehicleObstacle obs;
  if (_direction == RoadOption::ChangeLaneLeft) {
    obs = VehicleObstacleDetected(
        vehicles_alist,
        std::max(_behavior.min_proximity_threshold, _speed_limit / 2.0f),
        /*up_angle_th=*/180.0f,
        /*low_angle_th=*/0.0f,
        /*lane_offset=*/-1);
  } else if (_direction == RoadOption::ChangeLaneRight) {
    obs = VehicleObstacleDetected(
        vehicles_alist,
        std::max(_behavior.min_proximity_threshold, _speed_limit / 2.0f),
        /*up_angle_th=*/180.0f,
        /*low_angle_th=*/0.0f,
        /*lane_offset=*/1);
  } else {
    obs = VehicleObstacleDetected(
        vehicles_alist,
        std::max(_behavior.min_proximity_threshold, _speed_limit / 3.0f),
        /*up_angle_th=*/30.0f,
        /*low_angle_th=*/0.0f,
        /*lane_offset=*/0);

    // Tailgating check.
    if (!obs.affected &&
        _direction == RoadOption::LaneFollow &&
        !waypoint->IsJunction() &&
        _speed > 10.0f &&
        _behavior.tailgate_counter == 0) {
      Tailgating(waypoint);
    }
  }

  return obs;
}

BasicAgent::VehicleObstacle BehaviorAgent::PedestrianAvoidManager(
    SharedPtr<client::Waypoint> waypoint) {
  auto walkers_alist = _world->GetActors()
      ? _world->GetActors()->Filter("*walker.pedestrian*")
      : nullptr;

  // Python applies a 10 m prefilter around the waypoint here. The base
  // `VehicleObstacleDetected` honors `max_distance` internally, so we let
  // it do the proximity gating from the world-wide walker list.
  (void)waypoint;  // location consumed indirectly via VehicleObstacleDetected
  VehicleObstacle obs;
  if (_direction == RoadOption::ChangeLaneLeft) {
    obs = VehicleObstacleDetected(
        walkers_alist,
        std::max(_behavior.min_proximity_threshold, _speed_limit / 2.0f),
        /*up_angle_th=*/90.0f,
        /*low_angle_th=*/0.0f,
        /*lane_offset=*/-1);
  } else if (_direction == RoadOption::ChangeLaneRight) {
    obs = VehicleObstacleDetected(
        walkers_alist,
        std::max(_behavior.min_proximity_threshold, _speed_limit / 2.0f),
        /*up_angle_th=*/90.0f,
        /*low_angle_th=*/0.0f,
        /*lane_offset=*/1);
  } else {
    obs = VehicleObstacleDetected(
        walkers_alist,
        std::max(_behavior.min_proximity_threshold, _speed_limit / 3.0f),
        /*up_angle_th=*/60.0f,
        /*low_angle_th=*/0.0f,
        /*lane_offset=*/0);
  }
  return obs;
}

rpc::VehicleControl BehaviorAgent::CarFollowingManager(
    SharedPtr<client::Actor> vehicle, float distance, bool debug) {
  const float vehicle_speed = GetSpeed(vehicle);
  const float delta_v = std::max(1.0f, (_speed - vehicle_speed) / 3.6f);
  const float ttc = (delta_v != 0.0f)
      ? distance / delta_v
      : distance / std::nextafter(0.0f, 1.0f);

  float target_speed = 0.0f;
  if (_behavior.safety_time > ttc && ttc > 0.0f) {
    target_speed = std::min({
        Positive(vehicle_speed - _behavior.speed_decrease),
        _behavior.max_speed,
        _speed_limit - _behavior.speed_lim_dist});
  } else if (2.0f * _behavior.safety_time > ttc && ttc >= _behavior.safety_time) {
    target_speed = std::min({
        std::max(_min_speed, vehicle_speed),
        _behavior.max_speed,
        _speed_limit - _behavior.speed_lim_dist});
  } else {
    target_speed = std::min({
        _behavior.max_speed,
        _speed_limit - _behavior.speed_lim_dist});
  }
  _local_planner->SetSpeed(target_speed);
  return _local_planner->RunStep(debug);
}

rpc::VehicleControl BehaviorAgent::RunStep(bool debug) {
  UpdateInformation();

  if (_behavior.tailgate_counter > 0) {
    _behavior.tailgate_counter -= 1;
  }

  const auto ego_vehicle_loc = _vehicle->GetLocation();
  auto ego_vehicle_wp = _map->GetWaypoint(ego_vehicle_loc);

  // 1. Red lights / stops.
  if (TrafficLightManager()) {
    return EmergencyStop();
  }

  // 2.1: Pedestrian avoidance.
  auto walker_obs = PedestrianAvoidManager(ego_vehicle_wp);
  if (walker_obs.affected && walker_obs.actor) {
    const auto &walker_extent = walker_obs.actor->GetBoundingBox().extent;
    const auto &ego_extent    = _vehicle->GetBoundingBox().extent;
    const float distance = walker_obs.distance
        - std::max(walker_extent.y, walker_extent.x)
        - std::max(ego_extent.y,    ego_extent.x);
    if (distance < _behavior.braking_distance) {
      return EmergencyStop();
    }
  }

  // 2.2: Vehicle avoidance / car following.
  auto vehicle_obs = CollisionAndCarAvoidManager(ego_vehicle_wp);
  rpc::VehicleControl control{};
  if (vehicle_obs.affected && vehicle_obs.actor) {
    const auto &v_extent  = vehicle_obs.actor->GetBoundingBox().extent;
    const auto &ego_extent = _vehicle->GetBoundingBox().extent;
    const float distance = vehicle_obs.distance
        - std::max(v_extent.y,   v_extent.x)
        - std::max(ego_extent.y, ego_extent.x);
    if (distance < _behavior.braking_distance) {
      return EmergencyStop();
    }
    control = CarFollowingManager(vehicle_obs.actor, distance, debug);
  }
  // 3: Intersection behaviour (left/right turn).
  else if (_incoming_waypoint && _incoming_waypoint->IsJunction() &&
           (_incoming_direction == RoadOption::Left ||
            _incoming_direction == RoadOption::Right)) {
    const float target_speed = std::min(_behavior.max_speed,
                                        _speed_limit - 5.0f);
    _local_planner->SetSpeed(target_speed);
    control = _local_planner->RunStep(debug);
  }
  // 4: Normal behaviour.
  else {
    const float target_speed = std::min(_behavior.max_speed,
                                        _speed_limit - _behavior.speed_lim_dist);
    _local_planner->SetSpeed(target_speed);
    control = _local_planner->RunStep(debug);
  }
  return control;
}

rpc::VehicleControl BehaviorAgent::EmergencyStop() const {
  rpc::VehicleControl control{};
  control.throttle = 0.0f;
  control.brake = _max_brake;
  control.hand_brake = false;
  return control;
}

void ConstantVelocityAgent::StopConstantVelocity() {
  _is_constant_velocity_active = false;
  _vehicle->DisableConstantVelocity();
  _constant_velocity_stop_time =
      _world->GetSnapshot().GetTimestamp().elapsed_seconds;
  _has_stop_timestamp = true;
}

rpc::VehicleControl ConstantVelocityAgent::RunStep() {
  if (!_is_constant_velocity_active) {
    const double elapsed =
        _world->GetSnapshot().GetTimestamp().elapsed_seconds;
    if (_has_stop_timestamp &&
        (elapsed - _constant_velocity_stop_time) >
            static_cast<double>(_restart_time)) {
      RestartConstantVelocity();
      _is_constant_velocity_active = true;
    } else if (_use_basic_behavior) {
      return BasicAgent::RunStep();
    } else {
      return rpc::VehicleControl{};
    }
  }

  bool hazard_detected = false;
  float hazard_speed = 0.0f;

  auto actor_list   = _world->GetActors();
  auto vehicle_list = actor_list->Filter("*vehicle*");
  auto lights_list  = actor_list->Filter("*traffic_light*");

  const float vehicle_speed = _vehicle->GetVelocity().Length();

  // Vehicle obstacle check.
  const float max_vehicle_distance = _base_vehicle_threshold + vehicle_speed;
  auto v_obs = VehicleObstacleDetected(vehicle_list, max_vehicle_distance);
  if (v_obs.affected && v_obs.actor) {
    const auto vehicle_velocity = _vehicle->GetVelocity();
    const float v_len = vehicle_velocity.Length();
    if (v_len == 0.0f) {
      hazard_speed = 0.0f;
    } else {
      const auto adv_velocity = v_obs.actor->GetVelocity();
      const float dot = vehicle_velocity.x * adv_velocity.x +
                        vehicle_velocity.y * adv_velocity.y +
                        vehicle_velocity.z * adv_velocity.z;
      hazard_speed = dot / v_len;
    }
    hazard_detected = true;
  }

  // Red-light check (uses 0.3 * speed factor instead of _speed_ratio — match
  // the Python source verbatim).
  const float max_tlight_distance = _base_tlight_threshold + 0.3f * vehicle_speed;
  auto tl_pair = AffectedByTrafficLight(lights_list, max_tlight_distance);
  if (tl_pair.first) {
    hazard_speed = 0.0f;
    hazard_detected = true;
  }

  // Run the local planner so the wheels keep spinning even though the actual
  // forward motion comes from EnableConstantVelocity.
  rpc::VehicleControl control = _local_planner->RunStep();
  if (hazard_detected) {
    SetConstantVelocity(hazard_speed);
  } else {
    SetConstantVelocity(_target_speed_ms);
  }
  return control;
}

id ConstantVelocityAgent::SetCollisionSensor() {
  auto blueprint_lib = _world->GetBlueprintLibrary();
  const auto *blueprint = blueprint_lib->Find("sensor.other.collision");
  if (!blueprint) {
    return;
  }

  auto actor = _world->SpawnActor(*blueprint, geom::Transform{}, _vehicle.get());
  _collision_sensor = std::dynamic_pointer_cast<client::Sensor>(actor);
  if (!_collision_sensor) {
    return;
  }

  // Capture `this` raw — the agent owns the sensor and tears it down in the
  // destructor, so the callback can never fire on a destroyed agent.
  _collision_sensor->Listen(
      [this](SharedPtr<sensor::SensorData>) {
        this->StopConstantVelocity();
      });
}

vo

ConstantVelocityAgent::DestroySensor() {
  if (_collision_sensor) {
    if (_collision_sensor->IsListening()) {
      _collision_sensor->Stop();
    }
    _collision_sensor->Destroy();
    _collision_sensor.reset();
  }
}

}

geom::Vector3D UnitVector(const geom::Location &a, const geom::Location &b) {
    geom::Vector3D v(b.x - a.x, b.y - a.y, b.z - a.z);
    const double norm = std::sqrt(static_cast<double>(v.x) * v.x
                                + static_cast<double>(v.y) * v.y
                                + static_cast<double>(v.z) * v.z)
                      + std::numeric_limits<double>::epsilon();
    return geom::Vector3D(
        static_cast<float>(v.x / norm),
        static_cast<float>(v.y / norm),
        static_cast<float>(v.z / norm));
  }

ol LaneChangeAllows(road::element::LaneMarking::LaneChange lc,
                        road::element::LaneMarking::LaneChange flag) {
    using U = std::underlying_type_t<road::element::LaneMarking::LaneChange>;
    return (static_cast<U>(lc) & static_cast<U>(flag)) != 0;
  }

obalRoutePlanner::GlobalRoutePlanner(SharedPtr<client::Map> map,
                                       double sampling_resolution)
  : _map(std::move(map)),
    _sampling_resolution(sampling_resolution) {
  BuildTopology();
  BuildGraph();
  FindLooseEnds();
  LaneChangeLink();
}

obalRoutePlanner::NodeId GlobalRoutePlanner::GetOrCreateNode(const XYZKey &key) {
  auto it = _id_map.find(key);
  if (it != _id_map.end()) {
    return it->second;
  }
  const NodeId new_id = static_cast<NodeId>(_id_map.size());
  _id_map.emplace(key, new_id);
  Node node;
  node.vertex = {std::get<0>(key), std::get<1>(key), std::get<2>(key)};
  _nodes.emplace(new_id, std::move(node));
  return new_id;
}

obalRoutePlanner::Edge &GlobalRoutePlanner::AddEdge(NodeId n1, NodeId n2) {
  auto &edge = _edges[{n1, n2}];
  edge.src = n1;
  edge.dst = n2;
  // Track the successor only on the first insert (matches DiGraph semantics).
  auto &node = _nodes[n1];
  if (std::find(node.successors.begin(), node.successors.end(), n2)
      == node.successors.end()) {
    node.successors.push_back(n2);
  }
  return edge;
}

nst GlobalRoutePlanner::Edge *
GlobalRoutePlanner::FindEdge(NodeId n1, NodeId n2) const {
  auto it = _edges.find({n1, n2});
  return it == _edges.end() ? nullptr : &it->second;
}

obalRoutePlanner::Edge *
GlobalRoutePlanner::FindEdge(NodeId n1, NodeId n2) {
  auto it = _edges.find({n1, n2});
  return it == _edges.end() ? nullptr : &it->second;
}

id GlobalRoutePlanner::BuildTopology() {
  _topology.clear();

  for (const auto &segment : _map->GetTopology()) {
    SharedPtr<client::Waypoint> wp1 = segment.first;
    SharedPtr<client::Waypoint> wp2 = segment.second;

    const auto &l1 = wp1->GetTransform().location;
    const auto &l2 = wp2->GetTransform().location;

    // Round to integer coords to deduplicate near-identical endpoints — must
    // match `np.round([...], 0)` exactly.
    const double x1 = std::round(static_cast<double>(l1.x));
    const double y1 = std::round(static_cast<double>(l1.y));
    const double z1 = std::round(static_cast<double>(l1.z));
    const double x2 = std::round(static_cast<double>(l2.x));
    const double y2 = std::round(static_cast<double>(l2.y));
    const double z2 = std::round(static_cast<double>(l2.z));

    TopologySegment seg;
    seg.entry = wp1;
    seg.exit  = wp2;
    seg.entry_xyz = std::make_tuple(x1, y1, z1);
    seg.exit_xyz  = std::make_tuple(x2, y2, z2);

    const auto end_loc = wp2->GetTransform().location;
    if (wp1->GetTransform().location.Distance(end_loc) > _sampling_resolution) {
      auto next_wps = wp1->GetNext(_sampling_resolution);
      if (next_wps.empty()) {
        // Mirror Python: still record the (empty-path) segment.
        _topology.push_back(std::move(seg));
        continue;
      }
      auto w = next_wps[0];
      while (w && w->GetTransform().location.Distance(end_loc) > _sampling_resolution) {
        seg.path.push_back(w);
        auto step = w->GetNext(_sampling_resolution);
        if (step.empty()) {
          break;
        }
        w = step[0];
      }
    } else {
      auto next_wps = wp1->GetNext(_sampling_resolution);
      if (next_wps.empty()) {
        continue;  // skip degenerate segment
      }
      seg.path.push_back(next_wps[0]);
    }

    _topology.push_back(std::move(seg));
  }
}

//

GlobalRoutePlanner::BuildGraph() {
  _nodes.clear();
  _edges.clear();
  _id_map.clear();
  _road_id_to_edge.clear();

  for (const auto &segment : _topology) {
    const auto &entry_wp = segment.entry;
    const auto &exit_wp  = segment.exit;
    const bool intersection = entry_wp->IsJunction();
    const auto road_id    = entry_wp->GetRoadId();
    const auto section_id = entry_wp->GetSectionId();
    const auto lane_id    = entry_wp->GetLaneId();

    const NodeId n1 = GetOrCreateNode(segment.entry_xyz);
    const NodeId n2 = GetOrCreateNode(segment.exit_xyz);

    _road_id_to_edge[road_id][section_id][lane_id] = {n1, n2};

    const auto entry_v = entry_wp->GetTransform().rotation.GetForwardVector();
    const auto exit_v  = exit_wp->GetTransform().rotation.GetForwardVector();

    Edge &edge = AddEdge(n1, n2);
    // Python: length = len(path) + 1.
    edge.length        = static_cast<double>(segment.path.size()) + 1.0;
    edge.path          = segment.path;
    edge.entry_waypoint = entry_wp;
    edge.exit_waypoint  = exit_wp;
    edge.entry_vector   = entry_v;
    edge.exit_vector    = exit_v;
    edge.net_vector     = UnitVector(entry_wp->GetTransform().location,
                                     exit_wp->GetTransform().location);
    edge.intersection   = intersection;
    edge.type           = RoadOption::LaneFollow;
  }
}

//

lobalRoutePlanner::FindLooseEnds() {
  int count_loose_ends = 0;
  const double hop = _sampling_resolution;

  for (const auto &segment : _topology) {
    const auto &end_wp = segment.exit;
    const auto road_id    = end_wp->GetRoadId();
    const auto section_id = end_wp->GetSectionId();
    const auto lane_id    = end_wp->GetLaneId();

    bool already_indexed = false;
    auto road_it = _road_id_to_edge.find(road_id);
    if (road_it != _road_id_to_edge.end()) {
      auto sec_it = road_it->second.find(section_id);
      if (sec_it != road_it->second.end()) {
        already_indexed = sec_it->second.count(lane_id) > 0;
      }
    }
    if (already_indexed) {
      continue;
    }

    ++count_loose_ends;
    const NodeId n1 = _id_map.at(segment.exit_xyz);
    const NodeId n2 = -1 * count_loose_ends;            // NEGATIVE id sentinel
    _road_id_to_edge[road_id][section_id][lane_id] = {n1, n2};

    std::vector<SharedPtr<client::Waypoint>> path;
    auto next_wps = end_wp->GetNext(hop);
    while (!next_wps.empty()
           && next_wps[0]
           && next_wps[0]->GetRoadId()    == road_id
           && next_wps[0]->GetSectionId() == section_id
           && next_wps[0]->GetLaneId()    == lane_id) {
      path.push_back(next_wps[0]);
      next_wps = next_wps[0]->GetNext(hop);
    }

    if (!path.empty()) {
      const auto &tail_loc = path.back()->GetTransform().location;
      Node terminal;
      terminal.vertex = {static_cast<double>(tail_loc.x),
                         static_cast<double>(tail_loc.y),
                         static_cast<double>(tail_loc.z)};
      _nodes.emplace(n2, std::move(terminal));

      Edge &edge = AddEdge(n1, n2);
      edge.length         = static_cast<double>(path.size()) + 1.0;
      edge.path           = path;
      edge.entry_waypoint = end_wp;
      edge.exit_waypoint  = path.back();
      edge.entry_vector   = std::nullopt;
      edge.exit_vector    = std::nullopt;
      edge.net_vector     = std::nullopt;
      edge.intersection   = end_wp->IsJunction();
      edge.type           = RoadOption::LaneFollow;
    }
  }
}

// -

balRoutePlanner::LaneChangeLink() {
  using LaneChange = road::element::LaneMarking::LaneChange;

  for (const auto &segment : _topology) {
    bool left_found = false;
    bool right_found = false;
    if (segment.entry->IsJunction()) {
      // Python only checks `not segment['entry'].is_junction` inside the loop;
      // skipping the loop when true is equivalent and saves work.
      continue;
    }

    for (const auto &waypoint : segment.path) {
      if (left_found && right_found) {
        break;
      }

      // Right lane change.
      if (!right_found) {
        auto right_marking = waypoint->GetRightLaneMarking();
        if (right_marking
            && LaneChangeAllows(right_marking->lane_change, LaneChange::Right)) {
          auto next_wp = waypoint->GetRight();
          if (next_wp
              && next_wp->GetType() == road::Lane::LaneType::Driving
              && waypoint->GetRoadId() == next_wp->GetRoadId()) {
            auto next_segment = Localize(next_wp->GetTransform().location);
            if (next_segment.has_value()) {
              const NodeId src = _id_map.at(segment.entry_xyz);
              const NodeId dst = next_segment->first;
              Edge &edge = AddEdge(src, dst);
              edge.entry_waypoint = waypoint;
              edge.exit_waypoint  = next_wp;
              edge.intersection   = false;
              edge.exit_vector    = std::nullopt;
              edge.path.clear();
              edge.length         = 0.0;
              edge.type           = RoadOption::ChangeLaneRight;
              edge.change_waypoint = next_wp;
              right_found = true;
            }
          }
        }
      }

      // Left lane change.
      if (!left_found) {
        auto left_marking = waypoint->GetLeftLaneMarking();
        if (left_marking
            && LaneChangeAllows(left_marking->lane_change, LaneChange::Left)) {
          auto next_wp = waypoint->GetLeft();
          if (next_wp
              && next_wp->GetType() == road::Lane::LaneType::Driving
              && waypoint->GetRoadId() == next_wp->GetRoadId()) {
            auto next_segment = Localize(next_wp->GetTransform().location);
            if (next_segment.has_value()) {
              const NodeId src = _id_map.at(segment.entry_xyz);
              const NodeId dst = next_segment->first;
              Edge &edge = AddEdge(src, dst);
              edge.entry_waypoint = waypoint;
              edge.exit_waypoint  = next_wp;
              edge.intersection   = false;
              edge.exit_vector    = std::nullopt;
              edge.path.clear();
              edge.length         = 0.0;
              edge.type           = RoadOption::ChangeLaneLeft;
              edge.change_waypoint = next_wp;
              left_found = true;
            }
          }
        }
      }
    }
  }
}

// ---

ional<std::pair<GlobalRoutePlanner::NodeId, GlobalRoutePlanner::NodeId>>
GlobalRoutePlanner::Localize(const geom::Location &location) const {
  auto wp = _map->GetWaypoint(location);
  if (!wp) {
    return std::nullopt;
  }
  auto road_it = _road_id_to_edge.find(wp->GetRoadId());
  if (road_it == _road_id_to_edge.end()) return std::nullopt;
  auto sec_it = road_it->second.find(wp->GetSectionId());
  if (sec_it == road_it->second.end()) return std::nullopt;
  auto lane_it = sec_it->second.find(wp->GetLaneId());
  if (lane_it == sec_it->second.end()) return std::nullopt;
  return lane_it->second;
}

// ---

lobalRoutePlanner::DistanceHeuristic(NodeId a, NodeId b) const {
  const auto &va = _nodes.at(a).vertex;
  const auto &vb = _nodes.at(b).vertex;
  const double dx = va[0] - vb[0];
  const double dy = va[1] - vb[1];
  const double dz = va[2] - vb[2];
  return std::sqrt(dx * dx + dy * dy + dz * dz);
}

// ---

r<GlobalRoutePlanner::NodeId>
GlobalRoutePlanner::PathSearch(const geom::Location &origin,
                               const geom::Location &destination) {
  auto start = Localize(origin);
  auto end   = Localize(destination);
  if (!start.has_value() || !end.has_value()) {
    return {};
  }
  const NodeId source = start->first;
  const NodeId target = end->first;

  // Standard A*: priority queue keyed on f-score = g + h.
  using Item = std::pair<double, NodeId>;
  std::priority_queue<Item, std::vector<Item>, std::greater<Item>> open;
  std::unordered_map<NodeId, double> g_score;
  std::unordered_map<NodeId, NodeId> came_from;
  std::unordered_set<NodeId> closed;

  g_score[source] = 0.0;
  open.emplace(DistanceHeuristic(source, target), source);

  while (!open.empty()) {
    auto [f, current] = open.top();
    open.pop();
    if (current == target) {
      // Reconstruct path source -> target.
      std::vector<NodeId> path;
      NodeId n = current;
      path.push_back(n);
      while (n != source) {
        auto it = came_from.find(n);
        if (it == came_from.end()) break;
        n = it->second;
        path.push_back(n);
      }
      std::reverse(path.begin(), path.end());
      // Python appends end[1] (the second node id of the destination edge).
      path.push_back(end->second);
      return path;
    }
    if (!closed.insert(current).second) {
      continue;  // stale entry
    }

    auto node_it = _nodes.find(current);
    if (node_it == _nodes.end()) continue;
    const double g_current = g_score[current];

    for (NodeId neighbor : node_it->second.successors) {
      const Edge *edge = FindEdge(current, neighbor);
      if (!edge) continue;
      const double tentative = g_current + edge->length;
      auto it = g_score.find(neighbor);
      if (it == g_score.end() || tentative < it->second) {
        g_score[neighbor] = tentative;
        came_from[neighbor] = current;
        const double f_score = tentative + DistanceHeuristic(neighbor, target);
        open.emplace(f_score, neighbor);
      }
    }
  }

  return {};  // unreachable
}

// -----

std::optional<GlobalRoutePlanner::NodeId>, const GlobalRoutePlanner::Edge *>
GlobalRoutePlanner::SuccessiveLastIntersectionEdge(
    std::size_t index, const std::vector<NodeId> &route) const {
  const Edge *last_intersection_edge = nullptr;
  std::optional<NodeId> last_node;

  for (std::size_t i = index; i + 1 < route.size(); ++i) {
    const NodeId n1 = route[i];
    const NodeId n2 = route[i + 1];
    const Edge *candidate = FindEdge(n1, n2);
    if (!candidate) break;
    if (n1 == route[index]) {
      last_intersection_edge = candidate;
    }
    if (candidate->type == RoadOption::LaneFollow && candidate->intersection) {
      last_intersection_edge = candidate;
      last_node = n2;
    } else {
      break;
    }
  }
  return {last_node, last_intersection_edge};
}

// -----

lobalRoutePlanner::TurnDecision(std::size_t index,
                                            const std::vector<NodeId> &route) {
  // math.radians(35) — hard-coded to avoid depending on the non-standard M_PI.
  static constexpr double threshold = 35.0 * 3.14159265358979323846 / 180.0;
  RoadOption decision = RoadOption::Void;

  const NodeId current_node = route[index];
  const NodeId next_node    = route[index + 1];
  const Edge *next_edge     = FindEdge(current_node, next_node);
  if (!next_edge) {
    _previous_decision = RoadOption::Void;
    return RoadOption::Void;
  }

  if (index > 0) {
    const NodeId previous_node = route[index - 1];
    if (_previous_decision != RoadOption::Void
        && _intersection_end_node > 0
        && _intersection_end_node != previous_node
        && next_edge->type == RoadOption::LaneFollow
        && next_edge->intersection) {
      decision = _previous_decision;
    } else {
      _intersection_end_node = -1;
      const Edge *current_edge = FindEdge(previous_node, current_node);
      if (!current_edge) {
        _previous_decision = next_edge->type;
        return next_edge->type;
      }
      const bool calculate_turn = current_edge->type == RoadOption::LaneFollow
                                  && !current_edge->intersection
                                  && next_edge->type == RoadOption::LaneFollow
                                  && next_edge->intersection;
      if (calculate_turn) {
        auto [last_node, tail_edge] = SuccessiveLastIntersectionEdge(index, route);
        _intersection_end_node = last_node.value_or(-1);
        if (tail_edge != nullptr) {
          next_edge = tail_edge;
        }
        const auto &cv_opt = current_edge->exit_vector;
        const auto &nv_opt = next_edge->exit_vector;
        if (!cv_opt.has_value() || !nv_opt.has_value()) {
          _previous_decision = next_edge->type;
          return next_edge->type;
        }
        const auto cv = *cv_opt;
        const auto nv = *nv_opt;

        // 2-D cross product Z-component for siblings (only LANEFOLLOW
        // successors that aren't the chosen next-node).
        std::vector<double> cross_list;
        auto succ_it = _nodes.find(current_node);
        if (succ_it != _nodes.end()) {
          for (NodeId neighbor : succ_it->second.successors) {
            const Edge *select_edge = FindEdge(current_node, neighbor);
            if (!select_edge) continue;
            if (select_edge->type == RoadOption::LaneFollow
                && neighbor != route[index + 1]
                && select_edge->net_vector.has_value()) {
              const auto &sv = *select_edge->net_vector;
              cross_list.push_back(
                  static_cast<double>(cv.x) * sv.y
                  - static_cast<double>(cv.y) * sv.x);
            }
          }
        }
        const double next_cross = static_cast<double>(cv.x) * nv.y
                                  - static_cast<double>(cv.y) * nv.x;

        const double cv_len = std::sqrt(static_cast<double>(cv.x) * cv.x
                                       + static_cast<double>(cv.y) * cv.y
                                       + static_cast<double>(cv.z) * cv.z);
        const double nv_len = std::sqrt(static_cast<double>(nv.x) * nv.x
                                       + static_cast<double>(nv.y) * nv.y
                                       + static_cast<double>(nv.z) * nv.z);
        double cos_val = 0.0;
        if (cv_len > 0.0 && nv_len > 0.0) {
          cos_val = (static_cast<double>(cv.x) * nv.x
                     + static_cast<double>(cv.y) * nv.y
                     + static_cast<double>(cv.z) * nv.z) / (cv_len * nv_len);
        }
        cos_val = std::clamp(cos_val, -1.0, 1.0);
        const double deviation = std::acos(cos_val);

        if (cross_list.empty()) {
          cross_list.push_back(0.0);
        }

        if (deviation < threshold) {
          decision = RoadOption::Straight;
        } else if (next_cross < *std::min_element(cross_list.begin(), cross_list.end())) {
          decision = RoadOption::Left;
        } else if (next_cross > *std::max_element(cross_list.begin(), cross_list.end())) {
          decision = RoadOption::Right;
        } else if (next_cross < 0.0) {
          decision = RoadOption::Left;
        } else if (next_cross > 0.0) {
          decision = RoadOption::Right;
        }
      } else {
        decision = next_edge->type;
      }
    }
  } else {
    decision = next_edge->type;
  }

  _previous_decision = decision;
  return decision;
}

// ---------

obalRoutePlanner::FindClosestInList(
    const SharedPtr<client::Waypoint> &current,
    const std::vector<SharedPtr<client::Waypoint>> &list) {
  double min_distance = std::numeric_limits<double>::infinity();
  std::size_t closest = 0;
  const auto &cur_loc = current->GetTransform().location;
  for (std::size_t i = 0; i < list.size(); ++i) {
    const double d = list[i]->GetTransform().location.Distance(cur_loc);
    if (d < min_distance) {
      min_distance = d;
      closest = i;
    }
  }
  return closest;
}

// ---------

obalRoutePlanner::RouteItem>
GlobalRoutePlanner::TraceRoute(const geom::Location &origin,
                               const geom::Location &destination) {
  std::vector<RouteItem> route_trace;
  std::vector<NodeId> route = PathSearch(origin, destination);
  if (route.size() < 2) {
    return route_trace;
  }

  SharedPtr<client::Waypoint> current_waypoint = _map->GetWaypoint(origin);
  SharedPtr<client::Waypoint> destination_waypoint = _map->GetWaypoint(destination);
  if (!current_waypoint || !destination_waypoint) {
    return route_trace;
  }

  for (std::size_t i = 0; i + 1 < route.size(); ++i) {
    const RoadOption road_option = TurnDecision(i, route);
    const Edge *edge = FindEdge(route[i], route[i + 1]);
    if (!edge) continue;

    if (edge->type != RoadOption::LaneFollow && edge->type != RoadOption::Void) {
      route_trace.emplace_back(current_waypoint, road_option);
      const auto &exit_wp = edge->exit_waypoint;
      auto road_it = _road_id_to_edge.find(exit_wp->GetRoadId());
      if (road_it == _road_id_to_edge.end()) continue;
      auto sec_it = road_it->second.find(exit_wp->GetSectionId());
      if (sec_it == road_it->second.end()) continue;
      auto lane_it = sec_it->second.find(exit_wp->GetLaneId());
      if (lane_it == sec_it->second.end()) continue;
      const auto &n_pair = lane_it->second;
      const Edge *next_edge = FindEdge(n_pair.first, n_pair.second);
      if (next_edge && !next_edge->path.empty()) {
        std::size_t closest_index = FindClosestInList(current_waypoint, next_edge->path);
        closest_index = std::min(next_edge->path.size() - 1, closest_index + 5);
        current_waypoint = next_edge->path[closest_index];
      } else if (next_edge) {
        current_waypoint = next_edge->exit_waypoint;
      }
      route_trace.emplace_back(current_waypoint, road_option);
    } else {
      // path = [entry] + path + [exit]
      std::vector<SharedPtr<client::Waypoint>> path;
      path.reserve(edge->path.size() + 2);
      path.push_back(edge->entry_waypoint);
      path.insert(path.end(), edge->path.begin(), edge->path.end());
      path.push_back(edge->exit_waypoint);

      const std::size_t closest_index = FindClosestInList(current_waypoint, path);
      bool emitted_break = false;
      for (std::size_t k = closest_index; k < path.size() && !emitted_break; ++k) {
        current_waypoint = path[k];
        route_trace.emplace_back(current_waypoint, road_option);
        const std::size_t remaining = route.size() - i;
        if (remaining <= 2
            && current_waypoint->GetTransform().location.Distance(destination)
               < 2.0 * _sampling_resolution) {
          emitted_break = true;
        } else if (remaining <= 2
                   && current_waypoint->GetRoadId()    == destination_waypoint->GetRoadId()
                   && current_waypoint->GetSectionId() == destination_waypoint->GetSectionId()
                   && current_waypoint->GetLaneId()    == destination_waypoint->GetLaneId()) {
          const std::size_t destination_index = FindClosestInList(destination_waypoint, path);
          if (closest_index > destination_index) {
            emitted_break = true;
          }
        }
      }
    }
  }

  return route_trace;
}

} // namespa

RoadOption ComputeConnection(
    SharedPtr<client::Waypoint> current,
    SharedPtr<client::Waypoint> next_wp,
    float threshold = 35.0f) {
  // Python uses `% 360` and `% 180` on yaws to wrap them. Replicate with
  // `std::fmod` and a positive-fixup, since C++ `%` doesn't accept floats.
  auto wrap = [](float v, float mod) {
    float r = std::fmod(v, mod);
    if (r < 0.0f) r += mod;
    return r;
  };

  const float n = wrap(next_wp->GetTransform().rotation.yaw, 360.0f);
  const float c = wrap(current->GetTransform().rotation.yaw, 360.0f);
  const float diff = wrap(n - c, 180.0f);

  if (diff < threshold || diff > (180.0f - threshold)) {
    return RoadOption::Straight;
  }
  if (diff > 90.0f) {
    return RoadOption::Left;
  }
  return RoadOption::Right;
}

std::vector<RoadOption> RetrieveOptions(
    const std::vector<SharedPtr<client::Waypoint>> &candidates,
    SharedPtr<client::Waypoint> current) {
  std::vector<RoadOption> options;
  options.reserve(candidates.size());
  for (const auto &next_wp : candidates) {
    // The Python code probes 3 m further to disambiguate intersections that
    // share an entry waypoint.
    auto next_next = next_wp->GetNext(3.0);
    if (next_next.empty()) {
      options.push_back(ComputeConnection(current, next_wp));
    } else {
      options.push_back(ComputeConnection(current, next_next.front()));
    }
  }
  return options;
}

LocalPlanner::LocalPlanner(
    SharedPtr<client::Vehicle> vehicle,
    const Options &opt,
    SharedPtr<client::Map> map)
  : _vehicle(std::move(vehicle)),
    _map(std::move(map)),
    _dt(opt.dt),
    _target_speed(opt.target_speed),
    _sampling_radius(opt.sampling_radius),
    _lateral_args(opt.lateral),
    _longitudinal_args(opt.longitudinal),
    _max_throttle(opt.max_throttle),
    _max_brake(opt.max_brake),
    _max_steering(opt.max_steering),
    _offset(opt.offset),
    _base_min_distance(opt.base_min_distance),
    _distance_ratio(opt.distance_ratio),
    _follow_speed_limits(opt.follow_speed_limits),
    _rng(std::random_device{}()) {
  // If no map was supplied, pull it from the vehicle's world (mirrors the
  // `map_inst` fallback in local_planner.py).
  if (!_map && _vehicle) {
    _map = _vehicle->GetWorld().GetMap();
  }
  InitController();
}

void LocalPlanner::InitController() {
  _vehicle_controller = std::make_unique<VehiclePIDController>(
      _vehicle,
      _lateral_args,
      _longitudinal_args,
      _offset,
      _max_throttle,
      _max_brake,
      _max_steering);

  if (_vehicle && _map) {
    auto current_waypoint = _map->GetWaypoint(_vehicle->GetLocation());
    _target_waypoint = current_waypoint;
    _target_road_option = RoadOption::LaneFollow;
    _waypoints_queue.emplace_back(_target_waypoint, _target_road_option);
  }
}

void LocalPlanner::SetSpeed(float speed_kmh) {
  if (_follow_speed_limits) {
    std::cout << "WARNING: The max speed is currently set to follow the speed"
                 " limits. Use 'follow_speed_limits' to deactivate this\n";
  }
  _target_speed = speed_kmh;
}

void LocalPlanner::ComputeNextWaypoints(std::size_t k) {
  // Bound k by remaining queue capacity, like Python's
  // `available_entries = self._waypoints_queue.maxlen - len(...)`.
  const std::size_t available = (_waypoints_queue.size() < _max_queue_size)
      ? (_max_queue_size - _waypoints_queue.size())
      : 0;
  k = std::min(k, available);

  for (std::size_t i = 0; i < k; ++i) {
    if (_waypoints_queue.empty()) break;
    auto last_waypoint = _waypoints_queue.back().first;
    if (!last_waypoint) break;
    auto next_waypoints = last_waypoint->GetNext(_sampling_radius);

    if (next_waypoints.empty()) {
      break;
    }

    SharedPtr<client::Waypoint> next_waypoint;
    RoadOption road_option;
    if (next_waypoints.size() == 1) {
      next_waypoint = next_waypoints.front();
      road_option = RoadOption::LaneFollow;
    } else {
      // Random choice among the available branches.
      auto road_options_list = RetrieveOptions(next_waypoints, last_waypoint);
      std::uniform_int_distribution<std::size_t> dist(
          0, road_options_list.size() - 1);
      const std::size_t idx = dist(_rng);
      road_option = road_options_list[idx];
      // Python pulls `next_waypoints[road_options_list.index(road_option)]`,
      // i.e. the *first* candidate that shares the chosen RoadOption. With a
      // pre-randomised idx that's just the same as picking idx directly,
      // because there's a 1:1 alignment between the lists (the first option
      // matching the random pick is the random pick itself).
      next_waypoint = next_waypoints[idx];
    }

    _waypoints_queue.emplace_back(next_waypoint, road_option);
  }
}

void LocalPlanner::SetGlobalPlan(
    const std::vector<PlanItem> &plan,
    bool stop_waypoint_creation,
    bool clean_queue) {
  if (clean_queue) {
    _waypoints_queue.clear();
  }

  // The Python implementation grows the deque's `maxlen` whenever the new
  // plan exceeds it; we keep a soft cap and just raise it as needed.
  const std::size_t new_plan_length =
      plan.size() + _waypoints_queue.size();
  if (new_plan_length > _max_queue_size) {
    _max_queue_size = new_plan_length;
  }

  for (const auto &elem : plan) {
    _waypoints_queue.push_back(elem);
  }
  _stop_waypoint_creation = stop_waypoint_creation;
}

void LocalPlanner::SetOffset(float offset) {
  _offset = offset;
  if (_vehicle_controller) {
    _vehicle_controller->SetOffset(offset);
  }
}

rpc::VehicleControl LocalPlanner::RunStep(bool debug) {
  if (_follow_speed_limits && _vehicle) {
    _target_speed = _vehicle->GetSpeedLimit();
  }

  if (!_stop_waypoint_creation
      && _waypoints_queue.size() < _min_queue_length) {
    ComputeNextWaypoints(_min_queue_length);
  }

  // Purge waypoints we've already passed.
  if (_vehicle) {
    const auto veh_location = _vehicle->GetLocation();
    const float vehicle_speed_ms = GetSpeed(_vehicle) * kKmhToMs;
    const float min_distance =
        _base_min_distance + _distance_ratio * vehicle_speed_ms;

    std::size_t num_removed = 0;
    for (const auto &item : _waypoints_queue) {
      // Don't remove the very last waypoint until we're almost on top of it
      // (mirrors Python's `min_distance = 1` in the same situation).
      const float threshold =
          (_waypoints_queue.size() - num_removed == 1) ? 1.0f : min_distance;

      const auto &wp_loc = item.first->GetTransform().location;
      if (veh_location.Distance(wp_loc) < threshold) {
        ++num_removed;
      } else {
        break;
      }
    }
    for (std::size_t i = 0; i < num_removed; ++i) {
      _waypoints_queue.pop_front();
    }
  }

  rpc::VehicleControl control;
  if (_waypoints_queue.empty()) {
    control.steer = 0.0f;
    control.throttle = 0.0f;
    control.brake = 1.0f;
    control.hand_brake = false;
    control.manual_gear_shift = false;
  } else {
    _target_waypoint = _waypoints_queue.front().first;
    _target_road_option = _waypoints_queue.front().second;
    control = _vehicle_controller->RunStep(_target_speed, _target_waypoint);
  }

  if (debug && _vehicle && _target_waypoint) {
    auto world = std::make_shared<client::World>(_vehicle->GetWorld());
    DrawWaypoints(world, {_target_waypoint}, 1.0f);
  }

  return control;
}

std::pair<SharedPtr<client::Waypoint>, RoadOption>
LocalPlanner::GetIncomingWaypointAndDirection(int steps) const {
  if (steps >= 0
      && static_cast<std::size_t>(steps) < _waypoints_queue.size()) {
    return _waypoints_queue[static_cast<std::size_t>(steps)];
  }
  if (!_waypoints_queue.empty()) {
    return _waypoints_queue.back();
  }
  return {nullptr, RoadOption::Void};
}

float GetSpeed(SharedPtr<client::Actor> actor) {
  if (!actor) {
    return 0.0f;
  }
  const auto vel = actor->GetVelocity();
  return kKmhPerMs * std::sqrt(vel.x * vel.x + vel.y * vel.y + vel.z * vel.z);
}

geom::Location GetTrafficLightTriggerLocation(
    SharedPtr<client::TrafficLight> traffic_light) {
  // Local helper that mirrors the lambda in misc.py. The Python code rotates
  // the (0, 0, extent.z) point by the traffic light's yaw angle and adds it
  // back onto the trigger volume's transformed location.
  auto rotate_point = [](const geom::Vector3D &point, float radians) {
    const float rotated_x =
        std::cos(radians) * point.x - std::sin(radians) * point.y;
    const float rotated_y =
        std::sin(radians) * point.x - std::cos(radians) * point.y;
    return geom::Vector3D(rotated_x, rotated_y, point.z);
  };

  const geom::Transform base_transform = traffic_light->GetTransform();
  const float base_rot = base_transform.rotation.yaw;
  const geom::BoundingBox &trigger = traffic_light->GetTriggerVolume();

  // Transform the trigger volume's local centre into world space.
  geom::Vector3D area_loc(trigger.location.x, trigger.location.y,
                          trigger.location.z);
  base_transform.TransformPoint(area_loc);

  const geom::Vector3D &area_ext = trigger.extent;

  const geom::Vector3D point = rotate_point(
      geom::Vector3D(0.0f, 0.0f, area_ext.z),
      geom::Math::ToRadians(base_rot));

  return geom::Location(area_loc.x + point.x,
                        area_loc.y + point.y,
                        area_loc.z);
}

bool IsWithinDistance(
    const geom::Transform &target,
    const geom::Transform &reference,
    float max_distance,
    std::optional<std::pair<float, float>> angle_interval) {
  const float dx = target.location.x - reference.location.x;
  const float dy = target.location.y - reference.location.y;
  const float norm_target = std::sqrt(dx * dx + dy * dy);

  // Match the early-out behaviour from misc.py.
  if (norm_target < 0.001f) {
    return true;
  }
  if (norm_target > max_distance) {
    return false;
  }
  if (!angle_interval.has_value()) {
    return true;
  }

  const float min_angle = angle_interval->first;
  const float max_angle = angle_interval->second;

  const auto fwd = reference.GetForwardVector();
  const float dot = (fwd.x * dx + fwd.y * dy) / norm_target;
  const float clamped = std::clamp(dot, -1.0f, 1.0f);
  const float angle_deg = geom::Math::ToDegrees(std::acos(clamped));

  return min_angle < angle_deg && angle_deg < max_angle;
}

std::pair<float, float> ComputeMagnitudeAngle(
    const geom::Location &target,
    const geom::Location &current,
    float orientation_deg) {
  const float dx = target.x - current.x;
  const float dy = target.y - current.y;
  const float norm_target = std::sqrt(dx * dx + dy * dy);

  const float orientation_rad = geom::Math::ToRadians(orientation_deg);
  const float fwd_x = std::cos(orientation_rad);
  const float fwd_y = std::sin(orientation_rad);

  // Avoid a divide-by-zero when target and current coincide.
  const float denom = norm_target > 0.0f ? norm_target : kNormEps;
  const float dot = (fwd_x * dx + fwd_y * dy) / denom;
  const float clamped = std::clamp(dot, -1.0f, 1.0f);
  const float angle_deg = geom::Math::ToDegrees(std::acos(clamped));

  return {norm_target, angle_deg};
}

float DistanceVehicle(
    SharedPtr<client::Waypoint> waypoint,
    const geom::Transform &vehicle_transform) {
  const auto &wp_loc = waypoint->GetTransform().location;
  const float dx = wp_loc.x - vehicle_transform.location.x;
  const float dy = wp_loc.y - vehicle_transform.location.y;
  return std::sqrt(dx * dx + dy * dy);
}

std::array<float, 3> UnitVector(
    const geom::Location &a,
    const geom::Location &b) {
  const float x = b.x - a.x;
  const float y = b.y - a.y;
  const float z = b.z - a.z;
  // Match Python's `np.linalg.norm(...) + np.finfo(float).eps`.
  const float norm = std::sqrt(x * x + y * y + z * z) + kNormEps;
  return {x / norm, y / norm, z / norm};
}

float ComputeDistance(
    const geom::Location &a,
    const geom::Location &b) {
  const float x = b.x - a.x;
  const float y = b.y - a.y;
  const float z = b.z - a.z;
  return std::sqrt(x * x + y * y + z * z) + kNormEps;
}

void DrawWaypoints(
    SharedPtr<client::World> world,
    const std::vector<SharedPtr<client::Waypoint>> &waypoints,
    float z) {
  if (!world) {
    return;
  }
  auto debug = world->MakeDebugHelper();
  for (const auto &wpt : waypoints) {
    if (!wpt) continue;
    const auto wpt_t = wpt->GetTransform();
    const geom::Location begin(
        wpt_t.location.x,
        wpt_t.location.y,
        wpt_t.location.z + z);
    const float angle = geom::Math::ToRadians(wpt_t.rotation.yaw);
    const geom::Location end(
        begin.x + std::cos(angle),
        begin.y + std::sin(angle),
        begin.z);
    debug.DrawArrow(
        begin,
        end,
        /*thickness=*/0.1f,
        /*arrow_size=*/0.3f,
        client::DebugHelper::Color{255u, 0u, 0u},
        /*life_time=*/1.0f);
  }
}

void TrimDeque(std::deque<T> &q, std::size_t max_len) {
  while (q.size() > max_len) {
    q.pop_front();
  }
}

float PIDLongitudinalController::RunStep(float target_speed_kmh, bool debug) {
  const float current_speed_kmh = GetSpeed(_vehicle);
  if (debug) {
    std::cout << "Current speed = " << current_speed_kmh << '\n';
  }
  return PidControl(target_speed_kmh, current_speed_kmh);
}

float PIDLongitudinalController::PidControl(
    float target_speed_kmh, float current_speed_kmh) {
  const float error = target_speed_kmh - current_speed_kmh;
  _error_buffer.push_back(error);
  TrimDeque(_error_buffer, kErrorBufferMaxLen);

  float de = 0.0f;
  float ie = 0.0f;
  if (_error_buffer.size() >= 2) {
    de = (_error_buffer.back() - _error_buffer[_error_buffer.size() - 2]) / _dt;
    float sum = 0.0f;
    for (float e : _error_buffer) sum += e;
    ie = sum * _dt;
  }

  const float u = (_k_p * error) + (_k_d * de) + (_k_i * ie);
  return std::clamp(u, -1.0f, 1.0f);
}

void PIDLongitudinalController::ChangeParameters(
    float K_P, float K_I, float K_D, float dt) {
  _k_p = K_P;
  _k_i = K_I;
  _k_d = K_D;
  _dt  = dt;
}

float PIDLateralController::RunStep(SharedPtr<client::Waypoint> waypoint) {
  const auto vehicle_transform = _vehicle->GetTransform();

  // Vehicle forward vector projected onto the XY plane.
  const auto fwd = vehicle_transform.GetForwardVector();
  const float vx = fwd.x;
  const float vy = fwd.y;

  // Optionally laterally offset the waypoint along its right vector.
  geom::Location w_loc;
  if (_offset != 0.0f) {
    const auto w_tran = waypoint->GetTransform();
    const auto r_vec  = w_tran.GetRightVector();
    w_loc = geom::Location(
        w_tran.location.x + _offset * r_vec.x,
        w_tran.location.y + _offset * r_vec.y,
        w_tran.location.z);
  } else {
    w_loc = waypoint->GetTransform().location;
  }

  const float wx = w_loc.x - vehicle_transform.location.x;
  const float wy = w_loc.y - vehicle_transform.location.y;

  // Python computes `np.linalg.norm(w) * np.linalg.norm(v)`. v_z is 0 by
  // construction so the 2-D length is enough for both.
  const float w_len = std::sqrt(wx * wx + wy * wy);
  const float v_len = std::sqrt(vx * vx + vy * vy);
  const float wv_linalg = w_len * v_len;

  float dot;
  if (wv_linalg == 0.0f) {
    // Matches the Python `_dot = 1` early-out (degenerate inputs).
    dot = 1.0f;
  } else {
    const float cos_theta = std::clamp((wx * vx + wy * vy) / wv_linalg,
                                       -1.0f, 1.0f);
    dot = std::acos(cos_theta);
  }

  // np.cross(v, w)[2] for 2-D vectors lifted into 3-D is just vx*wy - vy*wx.
  const float cross_z = vx * wy - vy * wx;
  if (cross_z < 0.0f) {
    dot *= -1.0f;
  }

  _e_buffer.push_back(dot);
  TrimDeque(_e_buffer, kErrorBufferMaxLen);

  float de = 0.0f;
  float ie = 0.0f;
  if (_e_buffer.size() >= 2) {
    de = (_e_buffer.back() - _e_buffer[_e_buffer.size() - 2]) / _dt;
    float sum = 0.0f;
    for (float e : _e_buffer) sum += e;
    ie = sum * _dt;
  }

  const float u = (_k_p * dot) + (_k_d * de) + (_k_i * ie);
  return std::clamp(u, -1.0f, 1.0f);
}

void PIDLateralController::ChangeParameters(
    float K_P, float K_I, float K_D, float dt) {
  _k_p = K_P;
  _k_i = K_I;
  _k_d = K_D;
  _dt  = dt;
}

rpc::VehicleControl VehiclePIDController::RunStep(
    float target_speed_kmh,
    SharedPtr<client::Waypoint> wp) {
  const float acceleration = _lon_controller.RunStep(target_speed_kmh);
  float current_steering   = _lat_controller.RunStep(wp);

  rpc::VehicleControl control;
  if (acceleration >= 0.0f) {
    control.throttle = std::min(acceleration, _max_throttle);
    control.brake = 0.0f;
  } else {
    control.throttle = 0.0f;
    control.brake = std::min(std::abs(acceleration), _max_brake);
  }

  // Rate-limit steering changes (mirrors controller.py).
  if (current_steering > _past_steering + 0.1f) {
    current_steering = _past_steering + 0.1f;
  } else if (current_steering < _past_steering - 0.1f) {
    current_steering = _past_steering - 0.1f;
  }

  float steering;
  if (current_steering >= 0.0f) {
    steering = std::min(_max_steering, current_steering);
  } else {
    steering = std::max(-_max_steering, current_steering);
  }

  control.steer = steering;
  control.hand_brake = false;
  control.manual_gear_shift = false;
  _past_steering = steering;

  return control;
}

