}

ST(agents_types, behavior_aggressive_matches_python) {
  const auto p = BehaviorParameters::Aggressive();
  EXPECT_FLOAT_EQ(p.max_speed,               70.0f);
  EXPECT_FLOAT_EQ(p.speed_lim_dist,           1.0f);
  EXPECT_FLOAT_EQ(p.speed_decrease,           8.0f);
