id UVehicleImporter::StartServer()
{
  if (ServerRunnable)
    return;

  ServerRunnable = new FVehicleImporterServer();
  ServerThread   = FRunnableThread::Create(ServerRunnable,
                     TEXT("CarlaVehicleImporter"),
                     0, TPri_BelowNormal);
  UE_LOG(LogCarlaTools, Log, TEXT("VehicleImporter: listening on port %d"), GImporterPort);
}

id UVehicleImporter::StopServer()
{
  if (ServerRunnable)
    ServerRunnable->Stop();

  if (ServerThread)
  {
    while (ServerRunnable && !ServerRunnable->bDone.Load())
    {
      FTSTicker::GetCoreTicker().Tick(0.0f);
      FPlatformProcess::Sleep(0.001f);
    }
    ServerThread->WaitForCompletion();
    delete ServerThread;
    ServerThread = nullptr;
  }
  delete ServerRunnable;
  ServerRunnable = nullptr;
}

ol FVehicleImporterServer::Init()
{
  ISocketSubsystem* SS = ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM);
  if (!SS)
    return false;

  ListenSocket = FTcpSocketBuilder(TEXT("CarlaVehicleImporterListen"))
    .AsReusable()
    .BoundToEndpoint(FIPv4Endpoint(FIPv4Address::InternalLoopback, GImporterPort))
    .Listening(1)
    .Build();

  if (!ListenSocket)
  {
    UE_LOG(LogCarlaTools, Error,
           TEXT("VehicleImporter: failed to bind port %d"), GImporterPort);
    return false;
  }

  bRunning = true;
  return true;
}

nt32 FVehicleImporterServer::Run()
{
  FSocket* LocalSocket = ListenSocket;
  if (!LocalSocket) { bDone = true; return 0; }
  while (bRunning && LocalSocket)
  {
    bool bPending = false;
    if (LocalSocket->WaitForPendingConnection(bPending, FTimespan::FromSeconds(1.0)))
    {
      if (bPending)
      {
        FSocket* Client = LocalSocket->Accept(TEXT("CarlaStudio"));
        if (Client)
        {
          ServeClient(Client);
          Client->Close();
          ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->DestroySocket(Client);
        }
      }
    }
  }
  bDone = true;
  return 0;
}

id FVehicleImporterServer::Stop()
{
  bRunning = false;
  if (ListenSocket)
  {
    ListenSocket->Close();
    ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->DestroySocket(ListenSocket);
    ListenSocket = nullptr;
  }
}

atic bool RecvAll(FSocket* S, uint8* Buf, int32 Len)
{
  int32 Received = 0;
  while (Received < Len)
  {
    int32 Got = 0;
    if (!S->Recv(Buf + Received, Len - Received, Got) || Got <= 0)
      return false;
    Received += Got;
  }
  return true;
}

atic bool SendAll(FSocket* S, const uint8* Buf, int32 Len)
{
  int32 Sent = 0;
  while (Sent < Len)
  {
    int32 Written = 0;
    if (!S->Send(Buf + Sent, Len - Sent, Written) || Written <= 0)
      return false;
    Sent += Written;
  }
  return true;
}

id FVehicleImporterServer::ServeClient(FSocket* Client)
{
  // Read 4-byte length header.
  uint8 LenBuf[4];
  if (!RecvAll(Client, LenBuf, 4))
    return;

  const int32 MsgLen = (int32)(LenBuf[0]
    | ((uint32)LenBuf[1] << 8)
    | ((uint32)LenBuf[2] << 16)
    | ((uint32)LenBuf[3] << 24));

  if (MsgLen <= 0 || MsgLen > GMaxMessageBytes)
  {
    UE_LOG(LogCarlaTools, Warning,
           TEXT("VehicleImporter: bad message length %d"), MsgLen);
    return;
  }

  TArray<uint8> Body;
  Body.SetNumUninitialized(MsgLen + 1);  // +1 for null terminator
  if (!RecvAll(Client, Body.GetData(), MsgLen))
    return;

  Body[MsgLen] = '\0';

  const FString JsonStr = FString(UTF8_TO_TCHAR(
    reinterpret_cast<const ANSICHAR*>(Body.GetData())));

  // Multiplex on the JSON `action` field: "spawn" → drop the named asset
  // into the editor world; anything else (or absent) → the original
  // import flow. Any new game-thread work goes through the same FTSTicker
  // dispatch as ProcessSpec — see the comment block in ProcessSpec for
  // why this dance is needed (TaskGraph RecursionGuard otherwise).
  FString Response;
  TSharedPtr<FJsonObject> Root;
  TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(JsonStr);
  if (!FJsonSerializer::Deserialize(Reader, Root) || !Root.IsValid())
  {
    Response = MakeResponse(false, TEXT(""), TEXT("JSON parse error"));
  }
  else
  {
    FString Action;
    Root->TryGetStringField(TEXT("action"), Action);
    if (Action.Equals(TEXT("spawn"), ESearchCase::IgnoreCase))
    {
      FSpawnRequest Req;
      Root->TryGetStringField(TEXT("asset_path"), Req.AssetPath);
      double V = 0.0;
      if (Root->TryGetNumberField(TEXT("x"),   V)) Req.Loc.X   = (float)V;
      if (Root->TryGetNumberField(TEXT("y"),   V)) Req.Loc.Y   = (float)V;
      if (Root->TryGetNumberField(TEXT("z"),   V)) Req.Loc.Z   = (float)V;
      if (Root->TryGetNumberField(TEXT("yaw"), V)) Req.Yaw     = (float)V;

      auto P = MakeShared<TPromise<FString>>();
      TFuture<FString> Future = P->GetFuture();
      FTSTicker::GetCoreTicker().AddTicker(FTickerDelegate::CreateLambda(
        [this, Req, P](float) -> bool {
          P->SetValue(ProcessSpawn(Req));
          return false;
        }));
      Response = Future.Get();
    }
    else
    {
      FVehicleImportSpec Spec;
      if (!ParseSpec(JsonStr, Spec))
      {
        Response = MakeResponse(false, TEXT(""), TEXT("JSON parse error"));
      }
      else
      {
        auto P = MakeShared<TPromise<FString>>();
        TFuture<FString> Future = P->GetFuture();
        FTSTicker::GetCoreTicker().AddTicker(FTickerDelegate::CreateLambda(
          [this, Spec, P](float) -> bool {
            P->SetValue(ProcessSpec(Spec));
            return false;
          }));
        Response = Future.Get();
      }
    }
  }

  // Send length-prefixed response.
  FTCHARToUTF8 ResponseUTF8(*Response);
  const int32 RespLen = ResponseUTF8.Length();
  uint8 RespLenBuf[4] = {
    (uint8)(RespLen & 0xFF),
    (uint8)((RespLen >> 8)  & 0xFF),
    (uint8)((RespLen >> 16) & 0xFF),
    (uint8)((RespLen >> 24) & 0xFF)
  };
  SendAll(Client, RespLenBuf, 4);
  SendAll(Client, reinterpret_cast<const uint8*>(ResponseUTF8.Get()), RespLen);
}

// ---

loat JF(const TSharedPtr<FJsonObject>& O, const FString& K, float Def = 0.f)
{
  double V = Def;
  O->TryGetNumberField(K, V);
  return (float)V;
}

static

SharedPtr<FJsonObject> JO(const TSharedPtr<FJsonObject>& O, const FString& K)
{
  const TSharedPtr<FJsonObject>* Sub = nullptr;
  if (O->TryGetObjectField(K, Sub))
    return *Sub;
  return nullptr;
}

static

oid ParseWheel(const TSharedPtr<FJsonObject>& Root,
                       const FString& Key,
                       FWheelImportSpec& Out)
{
  TSharedPtr<FJsonObject> W = JO(Root, Key);
  if (!W) return;
  Out.X              = JF(W, "x");
  Out.Y              = JF(W, "y");
  Out.Z              = JF(W, "z");
  Out.Radius         = JF(W, "radius",           33.f);
  Out.MaxSteerAngle  = JF(W, "max_steer_angle",  70.f);
  Out.MaxBrakeTorque = JF(W, "max_brake_torque", 1500.f);
  Out.SuspMaxRaise   = JF(W, "susp_max_raise",   10.f);
  Out.SuspMaxDrop    = JF(W, "susp_max_drop",    10.f);
}

bool F

hicleImporterServer::ParseSpec(const FString& Json, FVehicleImportSpec& Out)
{
  TSharedPtr<FJsonObject> Root;
  TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(Json);
  if (!FJsonSerializer::Deserialize(Reader, Root) || !Root.IsValid())
    return false;

  Root->TryGetStringField(TEXT("vehicle_name"),   Out.VehicleName);
  Root->TryGetStringField(TEXT("mesh_path"),       Out.MeshFilePath);
  Root->TryGetStringField(TEXT("content_path"),    Out.ContentPath);
  Root->TryGetStringField(TEXT("base_vehicle_bp"), Out.BaseVehicleBP);

  double V = 1500.0;
  Root->TryGetNumberField(TEXT("mass"),            V); Out.Mass = (float)V;
  Root->TryGetNumberField(TEXT("susp_damping"),    V); Out.SuspDamping = (float)V;

  V = 1.0;
  Root->TryGetNumberField(TEXT("source_scale_to_cm"), V); Out.SourceScaleToCm = (float)V;
  int32 IV = 2;
  Root->TryGetNumberField(TEXT("source_up_axis"),      IV); Out.SourceUpAxis      = IV;
  IV = 0;
  Root->TryGetNumberField(TEXT("source_forward_axis"), IV); Out.SourceForwardAxis = IV;

  ParseWheel(Root, TEXT("wheel_fl"), Out.WheelFL);
  ParseWheel(Root, TEXT("wheel_fr"), Out.WheelFR);
  ParseWheel(Root, TEXT("wheel_rl"), Out.WheelRL);
  ParseWheel(Root, TEXT("wheel_rr"), Out.WheelRR);

  return !Out.VehicleName.IsEmpty() && !Out.MeshFilePath.IsEmpty();
}

FStrin

FVehicleImporterServer::MakeResponse(bool bOk, const FString& Path, const FString& Err)
{
  TSharedPtr<FJsonObject> Obj = MakeShared<FJsonObject>();
  Obj->SetBoolField(TEXT("success"),      bOk);
  Obj->SetStringField(TEXT("asset_path"), Path);
  Obj->SetStringField(TEXT("error"),      Err);

  FString Out;
  TSharedRef<TJsonWriter<>> W = TJsonWriterFactory<>::Create(&Out);
  FJsonSerializer::Serialize(Obj.ToSharedRef(), W);
  return Out;
}

// ---

String SanitizeAssetName(const FString& In)
{
  FString Out;
  Out.Reserve(In.Len());
  for (TCHAR C : In)
  {
    const bool bOk = (C >= 'A' && C <= 'Z') || (C >= 'a' && C <= 'z')
                  || (C >= '0' && C <= '9') || C == '_';
    Out.AppendChar(bOk ? C : TEXT('_'));
  }
  if (Out.IsEmpty()) Out = TEXT("Vehicle");
  if (Out[0] >= '0' && Out[0] <= '9') Out = TEXT("V_") + Out;
  return Out;
}

static

StaticMesh* ImportStaticMesh(const FString& FilePath,
                                     const FString& ContentPath,
                                     const FString& AssetName,
                                     const FVehicleImportSpec& Spec)
{
  UAssetImportTask* Task = NewObject<UAssetImportTask>();
  Task->Filename        = FilePath;
  Task->DestinationPath = ContentPath;
  Task->DestinationName = SanitizeAssetName(AssetName);
  // Don't save during import. Saving while we're holding the game-thread
  // tick (we run ProcessSpec from FTSTicker) triggers source-control
  // modals + a save dialog cascade that hangs the editor. The asset is
  // saved separately at the very end of the import, after all the
  // wheel/vehicle BPs have been built.
  Task->bSave           = false;
  Task->bAutomated      = true;
  Task->bReplaceExisting = true;

  IAssetTools& AssetTools =
    FModuleManager::GetModuleChecked<FAssetToolsModule>("AssetTools").Get();
  AssetTools.ImportAssetTasks({ Task });

  TArray<UObject*> Imported = Task->GetObjects();
  if (Imported.Num() == 0)
    return nullptr;
  UStaticMesh* Mesh = Cast<UStaticMesh>(Imported[0]);
  if (!Mesh) return nullptr;

  // Unit scaling is done by CarlaStudio at the source (it pre-scales the
  // OBJ vertices before sending the file path) so MeshDescription and
  // RenderData bounds stay in sync. Force BuildScale3D back to (1,1,1)
  // explicitly — UE preserves the previous BuildSettings on re-import, so
  // an asset that was previously imported with a 100× scale will keep
  // multiplying. Resetting here makes re-imports idempotent.
  if (Mesh->GetNumSourceModels() > 0)
  {
    FStaticMeshSourceModel& SM = Mesh->GetSourceModel(0);
    if (!SM.BuildSettings.BuildScale3D.Equals(FVector(1.0)))
    {
      SM.BuildSettings.BuildScale3D = FVector(1.0);
      Mesh->Build(false);
      Mesh->MarkPackageDirty();
    }
  }
  return Mesh;
}

static TS

classOf<UChaosVehicleWheel> CreateWheelBlueprint(
    const FString& ContentPath,
    const FString& Name,
    const FWheelImportSpec& W)
{
  IAssetTools& AssetTools =
    FModuleManager::GetModuleChecked<FAssetToolsModule>("AssetTools").Get();

  UBlueprintFactory* Factory = NewObject<UBlueprintFactory>();
  Factory->ParentClass = UChaosVehicleWheel::StaticClass();

  UObject* Asset = AssetTools.CreateAsset(Name, ContentPath,
                                          UBlueprint::StaticClass(), Factory);
  UBlueprint* BP = Cast<UBlueprint>(Asset);
  if (!BP || !BP->GeneratedClass) return nullptr;

  // BP factory does an initial compile inside CreateAsset, so GeneratedClass
  // is already valid. Just patch the CDO with our wheel parameters and skip
  // the explicit CompileBlueprint recompile — that call needs other game-
  // thread tasks to pump (shader/asset registry/save callbacks) to make
  // progress, which we can't provide while we're holding the FTSTicker
  // callback open.
  UChaosVehicleWheel* Defaults =
    Cast<UChaosVehicleWheel>(BP->GeneratedClass->ClassDefaultObject);
  if (Defaults)
  {
    Defaults->WheelRadius        = W.Radius;
    Defaults->MaxSteerAngle      = W.MaxSteerAngle;
    Defaults->MaxBrakeTorque     = W.MaxBrakeTorque;
    Defaults->SuspensionMaxRaise = W.SuspMaxRaise;
    Defaults->SuspensionMaxDrop  = W.SuspMaxDrop;
  }
  return TSubclassOf<UChaosVehicleWheel>(BP->GeneratedClass);
}

FString FVe

cessSpawn(const FSpawnRequest& Req)
{
  UE_LOG(LogCarlaTools, Display, TEXT("VI.ProcessSpawn: enter (asset=%s loc=%s yaw=%.1f)"),
         *Req.AssetPath, *Req.Loc.ToString(), Req.Yaw);

  if (Req.AssetPath.IsEmpty())
    return MakeResponse(false, TEXT(""), TEXT("spawn: asset_path missing"));

  // Resolve the actor class from the asset path. We try in order:
  //   (1) LoadAsset → cast to UBlueprint, take GeneratedClass
  //   (2) LoadClass with explicit `_C` suffix on the package object
  //   (3) StaticLoadObject<UClass> with the full fixed-up path
  // Each of these covers a slightly different shape of input the user
  // (or our own importer) might have given us.
  auto fixupClassPath = [](const FString& In) -> FString {
    // "/Game/.../BP_X"          -> "/Game/.../BP_X.BP_X_C"
    // "/Game/.../BP_X.BP_X"     -> "/Game/.../BP_X.BP_X_C"
    // "/Game/.../BP_X.BP_X_C"   -> unchanged
    if (In.EndsWith(TEXT("_C"))) return In;
    int32 Dot = INDEX_NONE; In.FindLastChar(TEXT('.'), Dot);
    int32 Slash = INDEX_NONE; In.FindLastChar(TEXT('/'), Slash);
    if (Dot == INDEX_NONE || Dot < Slash)
    {
      const FString Leaf = (Slash == INDEX_NONE) ? In : In.RightChop(Slash + 1);
      return In + TEXT(".") + Leaf + TEXT("_C");
    }
    return In + TEXT("_C");
  };

  UClass* Cls = nullptr;
  FString AttemptedPaths;
  // (1) Direct LoadAsset → blueprint
  {
    AttemptedPaths += Req.AssetPath;
    UObject* Loaded = UEditorAssetLibrary::LoadAsset(Req.AssetPath);
    if (UBlueprint* BP = Cast<UBlueprint>(Loaded))
      Cls = BP->GeneratedClass;
    else if (UClass* DirectClass = Cast<UClass>(Loaded))
      Cls = DirectClass;
  }
  // (2) LoadClass with `_C`-fixed-up path
  if (!Cls)
  {
    const FString Fixed = fixupClassPath(Req.AssetPath);
    AttemptedPaths += TEXT(" | ") + Fixed;
    Cls = LoadClass<AActor>(nullptr, *Fixed);
  }
  // (3) StaticLoadObject as final fallback (handles edge cases the
  // first two miss, e.g. the asset registry not yet caching the BP).
  if (!Cls)
  {
    const FString Fixed = fixupClassPath(Req.AssetPath);
    Cls = Cast<UClass>(StaticLoadObject(UClass::StaticClass(), nullptr, *Fixed));
  }

  if (!Cls || !Cls->IsChildOf(AActor::StaticClass()))
    return MakeResponse(false, TEXT(""),
      FString::Printf(TEXT("spawn: could not resolve actor class. Tried: %s"),
                      *AttemptedPaths));

  UWorld* World = GEditor ? GEditor->GetEditorWorldContext().World() : nullptr;
  if (!World)
    return MakeResponse(false, TEXT(""), TEXT("spawn: no editor world available"));

  FActorSpawnParameters Params;
  Params.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
  AActor* Spawned = World->SpawnActor<AActor>(
      Cls, FTransform(FRotator(0.f, Req.Yaw, 0.f), Req.Loc), Params);
  if (!Spawned)
    return MakeResponse(false, TEXT(""),
      FString::Printf(TEXT("spawn: SpawnActor returned null for %s"), *Cls->GetName()));

  UE_LOG(LogCarlaTools, Display, TEXT("VI.ProcessSpawn: spawned %s (label=%s)"),
         *Cls->GetName(), *Spawned->GetActorLabel());
  return MakeResponse(true, Spawned->GetActorLabel(), TEXT(""));
}

TEST(BoostAsioTimer, TimerFiresWithinReasonableTime) {
  boost::asio::io_context io;
  boost::asio::steady_timer timer{io, std::chrono::milliseconds(10)};

  std::atomic<bool> fired{false};
  timer.async_wait([&](const boost::system::error_code &ec) {
    EXPECT_FALSE(ec) << "steady_timer error: " << ec.message();
    fired = true;
  });

  std::thread t{[&] { io.run(); }};
  t.join();

  EXPECT_TRUE(fired) << "steady_timer handler never fired";
}

TEST(BoostAsioTimer, ExpiresAtNowComparison) {
  boost::asio::io_context io;
  boost::asio::steady_timer timer{io, std::chrono::milliseconds(5)};

  // Before expiry: expiry() should be in the future.
  auto expires_at = timer.expiry();
  auto now_before = std::chrono::steady_clock::now();
  EXPECT_GT(expires_at, now_before);

  // Run until the timer fires to advance real time past the expiry point.
  std::atomic<bool> done{false};
  timer.async_wait([&](const boost::system::error_code &) { done = true; });
  std::thread t{[&] { io.run(); }};
  t.join();

  // After expiry: now() should be >= expiry().
  auto now_after = std::chrono::steady_clock::now();
  EXPECT_GE(now_after, expires_at);
  EXPECT_TRUE(done);
}

TEST(BoostAsioTimer, ChronoDurationComposition) {
  const std::chrono::milliseconds d{250};
  EXPECT_EQ(d.count(), 250);
  EXPECT_EQ(std::chrono::duration_cast<std::chrono::seconds>(d).count(), 0);
}

TEST(BoostAsioTimer, InitializedWithMaxIsInDistantFuture) {
  boost::asio::io_context io;
  boost::asio::steady_timer timer{io, std::chrono::steady_clock::time_point::max()};
  EXPECT_GT(timer.expiry(), std::chrono::steady_clock::now());
}

TEST(BoostAsioTimer, DefaultConstructedExpiryIsInPast) {
  boost::asio::io_context io;
  boost::asio::steady_timer timer{io};
  EXPECT_LE(timer.expiry(), std::chrono::steady_clock::now());
}

TEST(BoostAsioTimer, CancelTriggersAbortedError) {
  boost::asio::io_context io;
  boost::asio::steady_timer timer{io, std::chrono::seconds(60)};
  boost::system::error_code captured;
  std::atomic<bool> fired{false};
  timer.async_wait([&](const boost::system::error_code &ec) {
    captured = ec;
    fired = true;
  });
  timer.cancel();
  io.run();
  EXPECT_TRUE(fired);
  EXPECT_EQ(captured, boost::asio::error::operation_aborted);
}

TEST(BoostRtree, InsertAndNearestNeighbour2D) {
  bgi::rtree<Value2D, bgi::quadratic<16>> tree;
  tree.insert({Point2D{0.0, 0.0}, 0u});
  tree.insert({Point2D{1.0, 1.0}, 1u});
  tree.insert({Point2D{10.0, 10.0}, 2u});
  tree.insert({Point2D{-5.0, -5.0}, 3u});

  std::vector<Value2D> result;
  tree.query(bgi::nearest(Point2D{0.9, 1.1}, 1), std::back_inserter(result));
  ASSERT_EQ(result.size(), 1u);
  EXPECT_EQ(result.front().second, 1u);
}

TEST(BoostRtree, InsertAndNearestNeighbour3D) {
  bgi::rtree<Value3D, bgi::quadratic<16>> tree;
  tree.insert({Point3D{0.0, 0.0, 0.0}, 0u});
  tree.insert({Point3D{1.0, 1.0, 1.0}, 1u});
  tree.insert({Point3D{2.0, 2.0, 2.0}, 2u});
  tree.insert({Point3D{10.0, 10.0, 10.0}, 3u});
  tree.insert({Point3D{-5.0, -5.0, -5.0}, 4u});

  std::vector<Value3D> result;
  tree.query(bgi::nearest(Point3D{2.1, 2.2, 1.9}, 1), std::back_inserter(result));
  ASSERT_EQ(result.size(), 1u);
  EXPECT_EQ(result.front().second, 2u);
}

TEST(BoostRtree, WithinBoxQuery2D) {
  bgi::rtree<Value2D, bgi::quadratic<16>> tree;
  tree.insert({Point2D{0.5, 0.5}, 0u});
  tree.insert({Point2D{2.0, 2.0}, 1u});
  tree.insert({Point2D{5.0, 5.0}, 2u});
  tree.insert({Point2D{-1.0, -1.0}, 3u});

  const Box2D box{Point2D{0.0, 0.0}, Point2D{3.0, 3.0}};
  std::vector<Value2D> result;
  tree.query(bgi::within(box), std::back_inserter(result));
  ASSERT_EQ(result.size(), 2u);

  std::vector<std::size_t> ids;
  for (const auto &entry : result) {
    ids.push_back(entry.second);
  }
  std::sort(ids.begin(), ids.end());
  EXPECT_EQ(ids[0], 0u);
  EXPECT_EQ(ids[1], 1u);
}

TEST(BoostRtree, KNearestReturnsExpectedSet) {
  bgi::rtree<Value2D, bgi::quadratic<16>> tree;
  tree.insert({Point2D{0.0, 0.0}, 0u});
  tree.insert({Point2D{1.0, 0.0}, 1u});
  tree.insert({Point2D{2.0, 0.0}, 2u});
  tree.insert({Point2D{3.0, 0.0}, 3u});

  std::vector<Value2D> result;
  tree.query(bgi::nearest(Point2D{0.0, 0.0}, 3), std::back_inserter(result));
  ASSERT_EQ(result.size(), 3u);

  // The rtree's nearest() query does not guarantee ordering of its k results,
  // only that they are the k nearest. Verify the expected set membership.
  std::vector<std::size_t> ids;
  for (const auto &entry : result) {
    ids.push_back(entry.second);
  }
  std::sort(ids.begin(), ids.end());
  EXPECT_EQ(ids[0], 0u);
  EXPECT_EQ(ids[1], 1u);
  EXPECT_EQ(ids[2], 2u);
}

Location GeoProjection::GeoLocationToTransform(const GeoLocation& geolocation) const {
        switch (static_cast<ProjectionType>(params.index())) {

            case ProjectionType::TransverseMercator: {
                auto& p = boost::variant2::get<TransverseMercatorParams>(params);
                return GeoLocationToTransformTransverseMercator(geolocation, p);
            }

            case ProjectionType::UniversalTransverseMercator: {
                auto& p = boost::variant2::get<UniversalTransverseMercatorParams>(params);
                return GeoLocationToTransformUniversalTransverseMercator(geolocation, p);
            }

            case ProjectionType::WebMercator: {
                auto& p = boost::variant2::get<WebMercatorParams>(params);
                return GeoLocationToTransformWebMercator(geolocation, p);
            }

            case ProjectionType::LambertConformalConic: {
                auto& p = boost::variant2::get<LambertConformalConicParams>(params);
                return GeoLocationToTransformLambertConformalConic(geolocation, p);
            }

            default: {
                auto& p = boost::variant2::get<TransverseMercatorParams>(params);
                return GeoLocationToTransformTransverseMercator(geolocation, p);
            }
        }
    }

GeoLocation GeoProjection::TransformToGeoLocation(const Location& location) const {
        switch (static_cast<ProjectionType>(params.index())) {
            case ProjectionType::TransverseMercator: {
                auto& p = boost::variant2::get<TransverseMercatorParams>(params);
                return TransformToGeoLocationTransverseMercator(location, p);
            }

            case ProjectionType::UniversalTransverseMercator: {
                auto& p = boost::variant2::get<UniversalTransverseMercatorParams>(params);
                return TransformToGeoLocationUniversalTransverseMercator(location, p);
            }

            case ProjectionType::WebMercator: {
                auto& p = boost::variant2::get<WebMercatorParams>(params);
                return TransformToGeoLocationWebMercator(location, p);
            }

            case ProjectionType::LambertConformalConic:{
                auto& p = boost::variant2::get<LambertConformalConicParams>(params);
                return TransformToGeoLocationLambertConformalConic(location, p);
            }

            default: {
                auto& p = boost::variant2::get<TransverseMercatorParams>(params);
                return TransformToGeoLocationTransverseMercator(location, p);
            }
        }
    }

Location GeoProjection::GeoLocationToTransformTransverseMercator(
        const GeoLocation& geolocation, const TransverseMercatorParams p) const {

        // Using Snyder TM forward (ellipsoidal) to 6th order
        double lat  = DegreesToRadians(geolocation.latitude);
        double lon  = DegreesToRadians(geolocation.longitude);
        double lat_0 = DegreesToRadians(p.lat_0);
        double lon_0 = DegreesToRadians(p.lon_0);

        double dlon = std::atan2(std::sin(lon - lon_0), std::cos(lon - lon_0));

        double a = p.ellps.a;
        double e2 = p.ellps.e2();
        double ep2 = p.ellps.ep2();
        double e4 = e2 * e2;
        double e6 = e4 * e2;

        double N = a / std::sqrt(1.0 - e2 * std::sin(lat) * std::sin(lat));
        double T = std::tan(lat) * std::tan(lat);
        double C = ep2 * std::cos(lat) * std::cos(lat);
        double A = std::cos(lat) * dlon;

        auto meridional_arc = [&](double phi) {
            return p.ellps.a * ((1.0 - e2 / 4.0 - 3.0 * e4 / 64.0 - 5.0 * e6 / 256.0) * phi
                - (3.0 * e2 / 8.0 + 3.0 * e4 / 32.0 + 45.0 * e6 / 1024.0) * std::sin(2.0 * phi)
                + (15.0 * e4 / 256.0 + 45.0 * e6 / 1024.0) * std::sin(4.0 * phi)
                - (35.0 * e6 / 3072.0) * std::sin(6.0 * phi));
        };

        double M  = meridional_arc(lat);
        double M_0 = meridional_arc(lat_0);

        double x = p.x_0 + p.k * N * (A + (1.0 - T + C) * std::pow(A, 3) / 6.0
            + (5.0 - 18.0 * T + T * T + 72.0 * C - 58.0 * ep2) * std::pow(A, 5) / 120.0);

        double  y = p.y_0 + p.k * ((M - M_0) + N * std::tan(lat) * ((A*A) / 2.0
            + (5.0 - T + 9.0 * C + 4.0 * C * C) * std::pow(A, 4) / 24.0
            + (61.0 - 58.0 * T + T * T + 600.0 * C - 330.0 * ep2) * std::pow(A, 6) / 720.0));

        return Location(static_cast<float>(x), static_cast<float>(y), static_cast<float>(geolocation.altitude));
    }

Location GeoProjection::GeoLocationToTransformUniversalTransverseMercator(
        const GeoLocation& geolocation, const UniversalTransverseMercatorParams p) const {

        // Using Snyder TM forward (ellipsoidal) to 6th order. Same formula as Transverse Mercator.
        double lat = DegreesToRadians(geolocation.latitude);
        double lon = DegreesToRadians(geolocation.longitude);
        double lon_0 = DegreesToRadians(6 * p.zone - 183);
        double k = 0.9996;
        double x_0 = 500000.0;
        double y_0 = (p.north) ? 0.0 : 10000000.0;

        double a = p.ellps.a;
        double e2 = p.ellps.e2();
        double ep2 = p.ellps.ep2();
        double e4 = e2 * e2;
        double e6 = e4 * e2;

        double N = a / std::sqrt(1.0 - e2 * std::sin(lat) * std::sin(lat));
        double T = std::tan(lat) * std::tan(lat);
        double C = ep2 * std::cos(lat) * std::cos(lat);
        double A = std::cos(lat) * std::atan2(std::sin(lon - lon_0), std::cos(lon - lon_0));

        double M = p.ellps.a * ((1.0 - e2 / 4.0 - 3.0 * e4 / 64.0 - 5.0 * e6 / 256.0) * lat
            - (3.0 * e2 / 8.0 + 3.0 * e4 / 32.0 + 45.0 * e6 / 1024.0) * std::sin(2.0 * lat)
            + (15.0 * e4 / 256.0 + 45.0 * e6 / 1024.0) * std::sin(4.0 * lat)
            - (35.0 * e6 / 3072.0) * std::sin(6.0 * lat));

        double x = x_0 + k * N * (A + (1.0 - T + C) * std::pow(A, 3) / 6.0
            + (5.0 - 18.0 * T + T * T + 72.0 * C - 58.0 * ep2) * std::pow(A, 5) / 120.0);

        double y = y_0 + k * (M + N * std::tan(lat) * ((A * A) / 2.0
            + (5.0 - T + 9.0 * C + 4.0 * C * C) * std::pow(A, 4) / 24.0
            + (61.0 - 58.0 * T + T * T + 600.0 * C - 330.0 * ep2) * std::pow(A, 6) / 720.0));

        Location result(static_cast<float>(x), static_cast<float>(y), static_cast<float>(geolocation.altitude));

        // The inverse transform applies p.offset to the input location before
        // un-projecting; mirror it here with the inverse offset so a
        // geo -> location -> geo round-trip stays the identity.
        if (p.offset.has_value()) {
            result = p.offset->ApplyInverseTransformation(result);
        }

        return result;
    }

Location GeoProjection::GeoLocationToTransformWebMercator(
        const GeoLocation& geolocation, const WebMercatorParams p) const {

        double lat = DegreesToRadians(geolocation.latitude);
        double lon = DegreesToRadians(geolocation.longitude);

        double x = p.ellps.a * lon;
        double y = p.ellps.a * std::log(std::tan(Math::Pi<double>() / 4.0 + lat / 2.0));

        return Location(static_cast<float>(x), static_cast<float>(y), static_cast<float>(geolocation.altitude));
    }

Location GeoProjection::GeoLocationToTransformLambertConformalConic(
        const GeoLocation& geolocation, const LambertConformalConicParams p) const {

        double lat = DegreesToRadians(geolocation.latitude);
        double lon = DegreesToRadians(geolocation.longitude);
        double lon_0 = DegreesToRadians(p.lon_0);
        double lat_0 = DegreesToRadians(p.lat_0);
        double lat_1 = DegreesToRadians(p.lat_1);
        double lat_2 = DegreesToRadians(p.lat_2);

        double a = p.ellps.a;
        double e2 = p.ellps.e2();
        double e = std::sqrt(e2);

        double m1 = std::cos(lat_1) / std::sqrt(1.0 - e2 * std::sin(lat_1) * std::sin(lat_1));
        double m2 = std::cos(lat_2) / std::sqrt(1.0 - e2 * std::sin(lat_2) * std::sin(lat_2));

        double t0 = std::tan(Math::Pi<double>() / 4 - lat_0 / 2)
            / std::pow((1.0 - e * std::sin(lat_0)) / (1.0 + e * std::sin(lat_0)), e / 2);
        double t1 = std::tan(Math::Pi<double>() / 4- lat_1 / 2)
            / std::pow((1.0 - e * std::sin(lat_1)) / (1.0 + e * std::sin(lat_1)), e / 2);
        double t2 = std::tan(Math::Pi<double>() / 4 - lat_2 / 2)
            / std::pow((1.0 - e * std::sin(lat_2)) / (1.0 + e * std::sin(lat_2)), e / 2);
        double t = std::tan(Math::Pi<double>() / 4 - lat / 2)
            / std::pow((1.0 - e * std::sin(lat)) / (1.0 + e * std::sin(lat)), e / 2);

        double n = (std::log(m1) - std::log(m2)) / (std::log(t1) - std::log(t2));
        double F = m1 / (n * std::pow(t1, n));
        double rho = a * F * std::pow(t, n);
        double rho0 = a * F * std::pow(t0, n);
        double theta = n * std::atan2(std::sin(lon - lon_0), std::cos(lon - lon_0));

        double x = p.x_0 + rho * std::sin(theta);
        double y = p.y_0 + rho0 - rho * std::cos(theta);

        return Location(static_cast<float>(x), static_cast<float>(y), static_cast<float>(geolocation.altitude));
    }

GeoLocation GeoProjection::TransformToGeoLocationTransverseMercator(
        const Location& location, const TransverseMercatorParams p) const {

        // Using Snyder TM inverse (ellipsoidal) to 6th order
        double lat_0 = DegreesToRadians(p.lat_0);
        double lon_0 = DegreesToRadians(p.lon_0);

        double a = p.ellps.a;
        double e2 = p.ellps.e2();
        double ep2 = p.ellps.ep2();
        double e4 = e2 * e2;
        double e6 = e4 * e2;

        double x = (location.x - p.x_0) / p.k;
        double y = (location.y - p.y_0) / p.k;

        double M = a * ((1.0 - e2 / 4.0 - 3.0 * e4 / 64.0 - 5.0 * e6 / 256.0) * lat_0
            - (3.0 * e2 / 8.0 + 3.0 * e4 / 32.0 + 45.0 * e6 / 1024.0) * std::sin(2.0 * lat_0)
            + (15.0 * e4 / 256.0 + 45.0 * e6 / 1024.0) * std::sin(4.0 * lat_0)
            - (35.0 * e6 / 3072.0) * std::sin(6.0 * lat_0)) + y;

        double mu = M / (a * (1.0 - e2 / 4.0 - 3.0 * e4 / 64.0 - 5.0 * e6 / 256.0));
        double e1 = (1.0 - std::sqrt(1.0 - e2)) / (1.0 + std::sqrt(1.0 - e2));
        double e1_2 = e1 * e1;
        double e1_3 = e1_2 * e1;
        double e1_4 = e1_3 * e1;

        double phi1 = mu + (3.0 * e1 / 2.0 - 27.0 * e1_3 / 32.0) * std::sin(2.0 * mu)
            + (21.0 * e1_2 / 16.0 - 55.0 * e1_4 / 32.0) * std::sin(4.0 * mu)
            + (151.0 * e1_3 / 96.0) * std::sin(6.0 * mu) + (1097.0 * e1_4 / 512.0) * std::sin(8.0 * mu);

        double sin1 = std::sin(phi1), cos1 = std::cos(phi1), tan1 = std::tan(phi1);

        double N = a / std::sqrt(1.0 - e2 * sin1 * sin1);
        double R = a * (1.0 - e2) / std::pow(1.0 - e2 * sin1 * sin1, 1.5);
        double T = tan1 * tan1;
        double C = ep2 * cos1 * cos1;
        double D  = x / N;

        // Snyder TM inverse (to 6th order)
        double lat = phi1 - (N * tan1 / R) * ((D * D) / 2.0
            - (5.0 + 3.0 * T + 10.0 * C - 4.0 * C * C - 9.0 * ep2) * std::pow(D, 4) / 24.0
            + (61.0 + 90.0 * T + 298.0 * C + 45.0 * T * T - 252.0 * ep2 - 3.0 * C * C) * std::pow(D, 6) / 720.0);

        double lon = lon_0 + (D - (1.0 + 2.0 * T + C) * std::pow(D, 3) / 6.0
            + (5.0 - 2.0 * C + 28.0 * T + 3.0 * C * C + 8.0 * ep2 + 24.0 * T * T) * std::pow(D, 5) / 120.0) / cos1;

        lon = std::atan2(std::sin(lon), std::cos(lon));

        return GeoLocation(RadiansToDegrees(lat), RadiansToDegrees(lon), location.z);
    }

GeoLocation GeoProjection::TransformToGeoLocationUniversalTransverseMercator(
        const Location& location_in, const UniversalTransverseMercatorParams p) const {

        // Using Snyder TM inverse (ellipsoidal) to 6th order. Same formula as Transverse Mercator.
        double lon_0 = DegreesToRadians(6 * p.zone - 183); // central meridian
        double k = 0.9996;
        double x_0 = 500000.0;
        double y_0 = (p.north) ? 0.0 : 10000000.0;

        double a = p.ellps.a;
        double e2 = p.ellps.e2();
        double ep2 = p.ellps.ep2();
        double e4 = e2 * e2;
        double e6 = e4 * e2;

        Location location;
        if (p.offset.has_value()) {
            location = p.offset->ApplyTransformation(location_in);
        }
        else{
            location = location_in;
        }

        //Negate the value of y because of the unreal left hand rule
        double x = (location.x - x_0) / k;
        double y = (location.y - y_0) / k;

        double mu = y / (a * (1.0 - e2 / 4.0 - 3.0 * e4 / 64.0 - 5.0 * e6 / 256.0));
        double e1 = (1.0 - std::sqrt(1.0 - e2)) / (1.0 + std::sqrt(1.0 - e2));
        double e1_2 = e1 * e1;
        double e1_3 = e1_2 * e1;
        double e1_4 = e1_3 * e1;

        double phi1 = mu + (3.0 * e1 / 2.0 - 27.0 * e1_3 / 32.0) * std::sin(2.0 * mu)
            + (21.0 * e1_2 / 16.0 - 55.0 * e1_4 / 32.0) * std::sin(4.0 * mu)
            + (151.0 * e1_3 / 96.0) * std::sin(6.0 * mu) + (1097.0 * e1_4 / 512.0) * std::sin(8.0 * mu);

        double sin1 = std::sin(phi1);
        double cos1 = std::cos(phi1);
        double tan1 = std::tan(phi1);

        double N = a / std::sqrt(1.0 - e2 * sin1 * sin1);
        double R = a * (1.0 - e2) / std::pow(1.0 - e2 * sin1 * sin1, 1.5);
        double T = tan1 * tan1;
        double C = ep2 * cos1 * cos1;
        double D  = x / N;

        double lat = phi1 - (N * tan1 / R) * ((D * D) / 2.0
            - (5.0 + 3.0 * T + 10.0 * C - 4.0 * C * C - 9.0 * ep2) * std::pow(D, 4) / 24.0
            + (61.0 + 90.0 * T + 298.0 * C + 45.0 * T * T - 252.0 * ep2 - 3.0 * C * C) * std::pow(D, 6) / 720.0);

        double lon = lon_0 + (D - (1.0 + 2.0 * T + C) * std::pow(D, 3) / 6.0
            + (5.0 - 2.0 * C + 28.0 * T + 3.0 * C * C + 8.0 * ep2 + 24.0 * T * T) * std::pow(D, 5) / 120.0) / cos1;

        lon = std::atan2(std::sin(lon), std::cos(lon));

        return GeoLocation(RadiansToDegrees(lat), RadiansToDegrees(lon), location.z);
    }

GeoLocation GeoProjection::TransformToGeoLocationWebMercator(
        const Location& location, const WebMercatorParams p) const {

        double lon = location.x / p.ellps.a;
        double lat = 2*std::atan(std::exp(location.y / p.ellps.a)) - Math::Pi<double>()/2;

        return GeoLocation(RadiansToDegrees(lat), RadiansToDegrees(lon), location.z);
    }

GeoLocation GeoProjection::TransformToGeoLocationLambertConformalConic(
        const Location& location, const LambertConformalConicParams p) const {

        double lon_0 = DegreesToRadians(p.lon_0);
        double lat_1 = DegreesToRadians(p.lat_1);
        double lat_2 = DegreesToRadians(p.lat_2);
        double lat_0 = DegreesToRadians(p.lat_0);

        double a = p.ellps.a;
        double e2 = p.ellps.e2();
        double e = std::sqrt(e2);

        double m1 = std::cos(lat_1) / std::sqrt(1.0 - e2 * std::sin(lat_1) * std::sin(lat_1));
        double m2 = std::cos(lat_2) / std::sqrt(1.0 - e2 * std::sin(lat_2) * std::sin(lat_2));

        double t0 = std::tan(Math::Pi<double>() / 4 - lat_0 / 2)
            / std::pow((1.0 - e * std::sin(lat_0)) / (1.0 + e * std::sin(lat_0)), e / 2);
        double t1 = std::tan(Math::Pi<double>() / 4- lat_1 / 2)
            / std::pow((1.0 - e * std::sin(lat_1)) / (1.0 + e * std::sin(lat_1)), e / 2);
        double t2 = std::tan(Math::Pi<double>() / 4 - lat_2 / 2)
            / std::pow((1.0 - e * std::sin(lat_2)) / (1.0 + e * std::sin(lat_2)), e / 2);

        double n = (std::log(m1) - std::log(m2)) / (std::log(t1) - std::log(t2)); // cone constant
        double F = m1 / (n * std::pow(t1, n));
        double rho0 = a * F * std::pow(t0, n);

        double x = static_cast<double>(location.x) - p.x_0;
        double y = static_cast<double>(location.y) - p.y_0;

        double sgn = (n >= 0.0) ? 1.0 : -1.0;
        double Y = rho0 - y;
        double rho = sgn * std::hypot(x, Y);
        double theta = std::atan2(sgn * x, sgn * Y);

        double t = std::pow(rho / (a * F), 1.0 / n);

        // initial spherical guess
        double lat = Math::Pi<double>() * 0.5 - 2.0 * std::atan(t);
        for (int i = 0; i < 10; ++i) {
            const double lat_next = Math::Pi<double>() * 0.5
                - 2.0 * std::atan(t * std::pow((1.0 - e * std::sin(lat)) / (1.0 + e * std::sin(lat)), 0.5 * e));
            if (std::abs(lat_next - lat) < 1e-12){
                lat = lat_next; break;
            }
            lat = lat_next;
        }
        double lon = lon_0 + theta / n;
        lon = std::atan2(std::sin(lon), std::cos(lon));

        return GeoLocation(RadiansToDegrees(lat), RadiansToDegrees(lon), location.z);
    }

static std::unordered_map<std::string, std::string> ParseProjectionParameters(const std::string &s){
    // +key[=value]; value can be "quoted" or 'quoted' or an unquoted token (no spaces)
    // This also captures bare flags like +south
    std::unordered_map<std::string, std::string> geo_parameters_map;

    static const std::regex re(R"(\+([A-Za-z0-9_]+)(?:=("[^"]*"|'[^']*'|[^ \t\r\n+]+))?)");
    for (std::sregex_iterator it(s.begin(), s.end(), re), end; it != end; ++it) {
        std::string key = (*it)[1].str();
        std::string val = (*it)[2].str();
        geo_parameters_map[key] = val;
    }

    return geo_parameters_map;
  }

static std::unordered_map<std::string, double> ParseOffsetParameters(const pugi::xml_node &geo_offset){

    std::unordered_map<std::string, double> geo_offset_result;

    for (auto attr = geo_offset.first_attribute(); attr; attr = attr.next_attribute()){
      std::string key = attr.name();
      double value = attr.as_double();
      geo_offset_result[key] = value;
    }
    return geo_offset_result;
  }

static bool TryGetParameter(std::string& out, M& parameters, S&& name)
  {
    auto i = parameters.find(std::forward<S>(name));
    if (i == parameters.cend())
      return false;
    out = i->second;
    return true;
  }

static
  std::enable_if_t<std::is_floating_point<O>::value, bool>
  TryGetParameter(O& out, M& parameters, S&& name)
  {
    auto i = parameters.find(std::forward<S>(name));
    if (i == parameters.cend())
      return false;
    out = static_cast<O>(std::stod(i->second));
    return true;
  }

static
  std::enable_if_t<std::is_integral<O>::value && std::is_unsigned<O>::value, bool>
  TryGetParameter(O& out, M& parameters, S&& name)
  {
    auto i = parameters.find(std::forward<S>(name));
    if (i == parameters.cend())
      return false;
    out = static_cast<O>(std::stoull(i->second));
    return true;
  }

static
  std::enable_if_t<std::is_integral<O>::value && std::is_signed<O>::value, bool>
  TryGetParameter(O& out, M& parameters, S&& name)
  {
    auto i = parameters.find(std::forward<S>(name));
    if (i == parameters.cend())
      return false;
    out = static_cast<O>(std::stoll(i->second));
    return true;
  }

static bool TryGetParameter(O& out,std::unordered_map<std::string, double>& parameters,S&& name)
  {
    auto i = parameters.find(std::forward<S>(name));
    if (i == parameters.cend()){
      return false;
    }
    out = static_cast<O>(i->second);
    return true;
  }

static boost::optional<geom::OffsetTransform> CreateOffsetTransform(std::unordered_map<std::string, double>& offset_parameters){

    if(offset_parameters.empty()){
      return boost::none;
    }

    double x = 0.0;
    double y = 0.0;
    double z = 0.0;
    double hdg = 0.0;

    TryGetParameter(x, offset_parameters, "x");
    TryGetParameter(y, offset_parameters, "y");
    TryGetParameter(z, offset_parameters, "z");
    TryGetParameter(hdg, offset_parameters, "hdg");

    return geom::OffsetTransform{x, y, z, hdg};
  }

static geom::GeoProjection CreateTransverseMercatorProjection(
    std::unordered_map<std::string, std::string> parameters,
    std::string proj_string,
    geom::Ellipsoid ellipsoid){

    geom::TransverseMercatorParams p;
    TryGetParameter(p.lat_0, parameters, "lat_0");
    TryGetParameter(p.lon_0, parameters, "lon_0");
    TryGetParameter(p.k, parameters, "k");
    TryGetParameter(p.x_0, parameters, "x_0");
    TryGetParameter(p.y_0, parameters, "y_0");
    p.ellps = ellipsoid;
    auto projection = geom::GeoProjection::Make(p);
    projection.SetPROJString(proj_string);
    return projection;
  }

static geom::GeoProjection CreateWebMercatorProjection(
    std::string proj_string,
    geom::Ellipsoid ellipsoid){
    // Parameters are fixed.
    geom::WebMercatorParams p;
    p.ellps = ellipsoid;
    auto projection = geom::GeoProjection::Make(p);
    projection.SetPROJString(proj_string);
    return projection;
  }

static geom::GeoProjection CreateLambertConformalConicProjection(
    std::unordered_map<std::string, std::string> parameters,
    std::string proj_string,
    geom::Ellipsoid ellipsoid){

    geom::LambertConformalConicParams p;
    TryGetParameter(p.lon_0, parameters, "lon_0");
    TryGetParameter(p.lat_0, parameters, "lat_0");
    if (!TryGetParameter(p.lat_1, parameters, "lat_1"))
      log_warning("Missing 'lat_1' parameter for LCC projection. Using default value " + std::to_string(p.lat_1));
    if (!TryGetParameter(p.lat_2, parameters, "lat_2"))
      log_warning("Missing 'lat_2' parameter for LCC projection. Using default value " + std::to_string(p.lat_2));
    TryGetParameter(p.x_0, parameters, "x_0");
    TryGetParameter(p.y_0, parameters, "y_0");
    p.ellps = ellipsoid;
    auto projection = geom::GeoProjection::Make(p);
    projection.SetPROJString(proj_string);
    return projection;
  }

static geom::GeoProjection CreateDefaultProjection(geom::Ellipsoid ellipsoid){
    geom::TransverseMercatorParams p;

    p.ellps = ellipsoid;
    auto projection = geom::GeoProjection::Make(p);
    return projection;
  }

static geom::GeoLocation CreateUniversalTransverseMercatorGeoReference(std::unordered_map<std::string, std::string> parameters){
    geom::GeoLocation result{0.0, 0.0, 0.0};
    double zone = 0.0;
    if (TryGetParameter(zone, parameters, "zone"))
      result.longitude = 6.0 * zone - 183.0;
    return result;
  }

static geom::GeoLocation CreateLambertConic2SPGeoReference(std::unordered_map<std::string, std::string> parameters){
    geom::GeoLocation result{0.0, 0.0, 0.0};
    TryGetParameter(result.latitude, parameters, "lat_0");
    TryGetParameter(result.longitude, parameters, "lon_0");
    return result;
  }

static auto ParseGeoProjectionAndReference(const std::string& proj_string, const pugi::xml_node &geo_offset){
    auto parameters = ParseProjectionParameters(proj_string);
    auto offset_parameters = ParseOffsetParameters(geo_offset);
    auto ellipsoid = CreateEllipsoid(parameters);
    auto offset_transform = CreateOffsetTransform(offset_parameters);

    // Get the projection type
    std::string proj;
    if (!TryGetParameter(proj, parameters, "proj")) {
      log_warning("cannot find the type of projection, using default transverse mercator");
      return std::make_pair(
        CreateDefaultProjection(ellipsoid),
        CreateDefaultGeoReference());
    }

    // Parse the parameters
    if (proj == "tmerc") {
      return std::make_pair(
        CreateTransverseMercatorProjection(parameters, proj_string, ellipsoid),
        CreateTransverseMercatorGeoReference(parameters));
    } else if (proj == "utm") {
      return std::make_pair(
        CreateUniversalTransverseMercatorProjection(parameters, proj_string, ellipsoid, offset_transform),
        CreateUniversalTransverseMercatorGeoReference(parameters));
    } else if (proj == "merc") {
      return std::make_pair(
        CreateWebMercatorProjection(proj_string, ellipsoid),
        CreateWebMercatorGeoReference());
    } else if (proj == "lcc") {
      return std::make_pair(
        CreateLambertConformalConicProjection(parameters, proj_string, ellipsoid),
        CreateLambertConic2SPGeoReference(parameters));
    } else {
      log_debug("projection '" + proj + "' is not supported, using default transverse mercator.");
      return std::make_pair(
        CreateDefaultProjection(ellipsoid),
        CreateDefaultGeoReference());
    }
  }

TEST(GeoProjection, tm_round_trip_zero) {
  // location -> geo -> location of the origin returns the origin within
  // the double-to-float rounding tolerance of the projection.
  const GeoProjection projection = TransverseMercator();
  const Location origin{0.0f, 0.0f, 0.0f};

  const GeoLocation geo = projection.TransformToGeoLocation(origin);
  const Location back = projection.GeoLocationToTransform(geo);

  ASSERT_NEAR(back.x, 0.0f, 1e-3f);
  ASSERT_NEAR(back.y, 0.0f, 1e-3f);
  ASSERT_NEAR(back.z, 0.0f, 1e-3f);
}

TEST(GeoProjection, tm_round_trip_random) {
  // For ten deterministic random Locations within ±50 km of the origin,
  // location -> geo -> location must recover the input.
  std::mt19937 rng(42u);
  std::uniform_real_distribution<float> xy_dist(-50000.0f, 50000.0f);
  std::uniform_real_distribution<float> z_dist(-20.0f, 3000.0f);

  const GeoProjection projection = TransverseMercator();
  constexpr float tolerance_m = 0.1f;

  for (int i = 0; i < 10; ++i) {
    const Location input{xy_dist(rng), xy_dist(rng), z_dist(rng)};
    const GeoLocation geo = projection.TransformToGeoLocation(input);
    const Location back = projection.GeoLocationToTransform(geo);

    ASSERT_NEAR(back.x, input.x, tolerance_m) << "iteration " << i;
    ASSERT_NEAR(back.y, input.y, tolerance_m) << "iteration " << i;
    ASSERT_NEAR(back.z, input.z, tolerance_m) << "iteration " << i;
  }
}

EST(GeoProjection, tm_preserves_relative_offsets) {
  // Two Locations separated by a known XY delta must round-trip through
  // the projection with the same delta. This pins the sign convention so
  // a future projection change cannot silently flip an axis.
  const GeoProjection projection = TransverseMercator();
  const Location a{100.0f, 50.0f, 0.0f};
  const Location b{120.0f, 70.0f, 0.0f};

  const Location back_a =
      projection.GeoLocationToTransform(projection.TransformToGeoLocation(a));
  const Location back_b =
      projection.GeoLocationToTransform(projection.TransformToGeoLocation(b));

  constexpr float tolerance_m = 1e-2f;
  ASSERT_NEAR(back_b.x - back_a.x, b.x - a.x, tolerance_m);
  ASSERT_NEAR(back_b.y - back_a.y, b.y - a.y, tolerance_m);
}

EST(GeoProjection, tm_altitude_passes_through) {
  // Altitude is carried through the projection unchanged regardless of
  // horizontal position.
  const GeoProjection projection = TransverseMercator();
  for (float z : {0.0f, 50.0f, 500.0f, 1000.0f, 3000.0f}) {
    const Location input{10.0f, 10.0f, z};
    const GeoLocation geo = projection.TransformToGeoLocation(input);
    const Location back = projection.GeoLocationToTransform(geo);
    ASSERT_NEAR(back.z, z, 1e-3f);
  }
}

EST(GeoProjection, utm_offset_round_trip) {
  // Regression test: the UTM inverse transform applies the parsed
  // OpenDRIVE offset to the input location, so the forward transform must
  // apply the inverse offset. Without that symmetry a location -> geo ->
  // location round-trip drifts by the full offset.
  const OffsetTransform offset(500000.0, 4000000.0, 100.0, 0.0);
  const GeoProjection projection = GeoProjection::Make(
      UniversalTransverseMercatorParams(32, true, Wgs84(), offset));

  constexpr float tolerance_m = 0.5f;
  for (const Location &input :
       {Location{0.0f, 0.0f, 0.0f}, Location{120.0f, -80.0f, 35.0f},
        Location{-200.0f, 250.0f, -15.0f}}) {
    const GeoLocation geo = projection.TransformToGeoLocation(input);
    const Location back = projection.GeoLocationToTransform(geo);
    ASSERT_NEAR(back.x, input.x, tolerance_m);
    ASSERT_NEAR(back.y, input.y, tolerance_m);
    ASSERT_NEAR(back.z, input.z, tolerance_m);
  }
}

EST(OffsetTransform, inverse_is_exact) {
  // ApplyInverseTransformation must invert ApplyTransformation exactly,
  // including the heading rotation and the z translation.
  const OffsetTransform offset(12.5, -7.25, 3.0, 0.4);
  constexpr float tolerance_m = 1e-3f;
  for (const Location &input :
       {Location{0.0f, 0.0f, 0.0f}, Location{100.0f, 200.0f, 30.0f},
        Location{-150.0f, 75.0f, -10.0f}}) {
    const Location forward = offset.ApplyTransformation(input);
    const Location back = offset.ApplyInverseTransformation(forward);
    ASSERT_NEAR(back.x, input.x, tolerance_m);
    ASSERT_NEAR(back.y, input.y, tolerance_m);
    ASSERT_NEAR(back.z, input.z, tolerance_m);
  }
}

static boost::python::object OptionalToPythonObject(const boost::optional<T>& opt) {
  if (opt.has_value()) {
    return boost::python::object(*opt);
  }
  return boost::python::object(); // None
}

static auto GetGeoProjection(const carla::client::Map &self) {
  const auto &variant = self.GetGeoProjection().params;

  return boost::variant2::visit([](const auto &params) -> boost::python::object {
    return boost::python::object(params);}, variant);
}

