void ACarlaRecorder::AddWeather(const CarlaRecorderWeather &Weather)
{
  if (Enabled)
  {
    Weathers.Add(Weather);
  }
}

void ACarlaRecorder::AddExistingWeather(void)
{
  AWeather *WeatherActor = Episode->GetWeather();
  if (WeatherActor != nullptr)
  {
    CarlaRecorderWeather RecorderWeather;
    const auto &Params = WeatherActor->GetCurrentWeather();
    RecorderWeather.Cloudiness              = Params.Cloudiness;
    RecorderWeather.Precipitation           = Params.Precipitation;
    RecorderWeather.PrecipitationDeposits   = Params.PrecipitationDeposits;
    RecorderWeather.WindIntensity           = Params.WindIntensity;
    RecorderWeather.SunAzimuthAngle         = Params.SunAzimuthAngle;
    RecorderWeather.SunAltitudeAngle        = Params.SunAltitudeAngle;
    RecorderWeather.FogDensity              = Params.FogDensity;
    RecorderWeather.FogDistance             = Params.FogDistance;
    RecorderWeather.FogFalloff              = Params.FogFalloff;
    RecorderWeather.Wetness                 = Params.Wetness;
    RecorderWeather.ScatteringIntensity     = Params.ScatteringIntensity;
    RecorderWeather.MieScatteringScale      = Params.MieScatteringScale;
    RecorderWeather.RayleighScatteringScale = Params.RayleighScatteringScale;
    RecorderWeather.DustStorm               = Params.DustStorm;
    AddWeather(RecorderWeather);
  }
}

void CarlaRecorderWeather::Write(std::ostream &OutFile)
{
  WriteValue(OutFile, this->Cloudiness);
  WriteValue(OutFile, this->Precipitation);
  WriteValue(OutFile, this->PrecipitationDeposits);
  WriteValue(OutFile, this->WindIntensity);
  WriteValue(OutFile, this->SunAzimuthAngle);
  WriteValue(OutFile, this->SunAltitudeAngle);
  WriteValue(OutFile, this->FogDensity);
  WriteValue(OutFile, this->FogDistance);
  WriteValue(OutFile, this->FogFalloff);
  WriteValue(OutFile, this->Wetness);
  WriteValue(OutFile, this->ScatteringIntensity);
  WriteValue(OutFile, this->MieScatteringScale);
  WriteValue(OutFile, this->RayleighScatteringScale);
  WriteValue(OutFile, this->DustStorm);
}

void CarlaRecorderWeather::Read(std::istream &InFile)
{
  ReadValue(InFile, this->Cloudiness);
  ReadValue(InFile, this->Precipitation);
  ReadValue(InFile, this->PrecipitationDeposits);
  ReadValue(InFile, this->WindIntensity);
  ReadValue(InFile, this->SunAzimuthAngle);
  ReadValue(InFile, this->SunAltitudeAngle);
  ReadValue(InFile, this->FogDensity);
  ReadValue(InFile, this->FogDistance);
  ReadValue(InFile, this->FogFalloff);
  ReadValue(InFile, this->Wetness);
  ReadValue(InFile, this->ScatteringIntensity);
  ReadValue(InFile, this->MieScatteringScale);
  ReadValue(InFile, this->RayleighScatteringScale);
  ReadValue(InFile, this->DustStorm);
}

void CarlaRecorderWeathers::Write(std::ostream &OutFile)
{
  if (Weathers.size() == 0)
  {
    return;
  }

  // write the packet id
  WriteValue<char>(OutFile, static_cast<char>(CarlaRecorderPacketId::Weather));

  // write the packet size
  uint32_t Total = 2 + Weathers.size() * sizeof(CarlaRecorderWeather);
  WriteValue<uint32_t>(OutFile, Total);

  // write total records
  Total = Weathers.size();
  WriteValue<uint16_t>(OutFile, Total);

  // write records
  for (auto& Weather : Weathers)
  {
    Weather.Write(OutFile);
  }
}

void UCustomTerrainPhysicsComponent::OnHeightMapLoaded()
{
  if (!PendingHeightMapHandle.IsValid())
  {
    return;
  }
  UObject* LoadedObject = PendingHeightMapHandle->GetLoadedAsset();
  const FIntVector TargetTileId = PendingHeightMapTileId;
  PendingHeightMapHandle.Reset();

  UHeightMapDataAsset* HeightMapDataAsset = Cast<UHeightMapDataAsset>(LoadedObject);
  if (HeightMapDataAsset == nullptr || LargeMapManager == nullptr)
  {
    UE_LOG(LogCarla, Warning,
        TEXT("UCustomTerrainPhysicsComponent::OnHeightMapLoaded: async load for tile %s resolved but asset is unusable"),
        *TargetTileId.ToString());
    return;
  }

  ActiveHeightMap = HeightMapDataAsset;
  FVector TilePosition =
      HeightMapOffset
      + LargeMapManager->GetTileLocation(TargetTileId)
      - 0.5f * FVector(LargeMapManager->GetTileSize(), -LargeMapManager->GetTileSize(), 0);
  UE_LOG(LogCarla, Log,
      TEXT("Async height map loaded for tile %s at location %s"),
      *TargetTileId.ToString(), *TilePosition.ToString());
  TilePosition.Z += UEFrameToSI(FloorHeight);
  SparseMap.UpdateHeightMap(
      HeightMapDataAsset,
      UEFrameToSI(TilePosition),
      UEFrameToSI(FVector(
          LargeMapManager->GetTileSize(),
          -LargeMapManager->GetTileSize(),
          0)),
      1.f,
      HeightMapScaleFactor.Z);
}

static std::string MakeHeader() {
  return R"(<?xml version="1.0" encoding="UTF-8"?>
<OpenDRIVE>
  <header revMajor="1" revMinor="4" name="" version="1"
          north="100" south="-100" east="100" west="-100"/>
)";
}

static std::string NegativeOnlyLanes() {
  return R"(
    <lanes>
      <laneSection s="0">
        <center><lane id="0" type="none" level="false"/></center>
        <right>
          <lane id="-1" type="driving" level="false">
            <width sOffset="0" a="3.5" b="0" c="0" d="0"/>
          </lane>
        </right>
      </laneSection>
    </lanes>)";
}

TEST(road, filter_roads_includes_positive_only_lanes_9565) {
  // Three roads side-by-side along X axis, all centred around Y=0.
  //   Road 0 (x=0..50):  bidirectional   -- has lane -1, was always included
  //   Road 1 (x=60..110): positive-only  -- no lane -1, was EXCLUDED before fix
  //   Road 2 (x=120..170): negative-only -- has lane -1, was always included
  std::string xodr = MakeHeader()
      + MakeRoad(0, 0.f,   50.f, BidirectionalLanes())
      + MakeRoad(1, 60.f,  50.f, PositiveOnlyLanes())
      + MakeRoad(2, 120.f, 50.f, NegativeOnlyLanes())
      + "</OpenDRIVE>\n";

  auto map = OpenDriveParser::Load(xodr);
  ASSERT_TRUE(map.has_value());

  // Bounding box covering all three roads.
  // FilterRoadsByPosition checks minpos.y > y > maxpos.y (Y axis is inverted),
  // so minpos.y must be the larger (positive) value.
  const Vector3D minpos(-10.f,  20.f, -10.f);
  const Vector3D maxpos(200.f, -20.f,  10.f);

  auto included = map->GetMap().FilterRoadsByPosition(minpos, maxpos);

  // All three roads must be included after the fix.
  EXPECT_EQ(included.size(), 3u)
      << "FilterRoadsByPosition excluded a road with positive-only lanes";
}

TEST(road, get_trees_transform_no_crash_without_speed_9565) {
  // Road without any <speed> element --roadinfo will be nullptr.
  std::string xodr = MakeHeader()
      + MakeRoad(0, 0.f, 100.f, BidirectionalLanes(), /*with_speed=*/false)
      + "</OpenDRIVE>\n";

  auto map = OpenDriveParser::Load(xodr);
  ASSERT_TRUE(map.has_value());

  // FilterRoadsByPosition checks minpos.y > y > maxpos.y (Y axis inverted).
  const Vector3D minpos(-10.f,  20.f, -10.f);
  const Vector3D maxpos(110.f, -20.f,  10.f);

  // Must not crash (a regression to the null dereference will fail by crashing).
  std::vector<std::pair<carla::geom::Transform, std::string>> result =
      map->GetMap().GetTreesTransform(minpos, maxpos, 10.f, 2.f);

  // Must produce at least one tree so the fallback-type loop below is not vacuous.
  ASSERT_GT(result.size(), 0u)
      << "No trees generated for road without maxspeed tag";

  // Fallback type "Town" must be used for all entries.
  for (const auto& entry : result) {
    EXPECT_EQ(entry.second, "Town")
        << "Expected \"Town\" fallback for road without maxspeed tag";
  }
}

TEST(road, get_trees_transform_positive_lane_road_gets_trees_9565) {
  // One-way road with positive-only lanes: before the fix, min_lane stayed 0
  // and the lane section was skipped --no trees were generated at all.
  std::string xodr = MakeHeader()
      + MakeRoad(0, 0.f, 100.f, PositiveOnlyLanes())
      + "</OpenDRIVE>\n";

  auto map = OpenDriveParser::Load(xodr);
  ASSERT_TRUE(map.has_value());

  // FilterRoadsByPosition checks minpos.y > y > maxpos.y (Y axis inverted).
  const Vector3D minpos(-10.f,  20.f, -10.f);
  const Vector3D maxpos(110.f, -20.f,  10.f);

  auto result = map->GetMap().GetTreesTransform(minpos, maxpos, 10.f, 2.f);

  ASSERT_GT(result.size(), 0u)
      << "No trees generated for one-way road with positive-only lanes";

  // PositiveOnlyLanes: lane id=1 (3.5m wide) and lane id=2 (3.5m wide).
  // Outer edge of lane id=2 is at |Y| = 3.5 + 3.5 = 7.0m from road centre.
  // distancefromdrivinglineborder=2.0 => trees placed 2.0m beyond that edge.
  // Trees must satisfy |Y| >= 7.0 + 2.0 = 9.0.
  const float lane1_width      = 3.5f;
  const float lane2_width      = 3.5f;
  const float dist_from_edge   = 2.0f;
  const float outer_road_edge  = lane1_width + lane2_width;
  const float min_expected_dist = outer_road_edge + dist_from_edge;  // 9.0
  for (const auto& entry : result) {
    const float tree_y = std::abs(entry.first.location.y);
    EXPECT_NEAR(tree_y, min_expected_dist, TREE_Y_TOLERANCE)
        << "Tree Y=" << entry.first.location.y
        << " is not within ±" << TREE_Y_TOLERANCE << " of the expected minimum distance (|Y| = " << min_expected_dist << ")";
  }
}

EST(road, get_trees_transform_trees_outside_road_9565) {
  // Verify trees are not placed inside the driving lane.
  // Road: single right lane (id=-1, width=3.5m) centred at Y=0.
  // Driving surface occupies Y in [-3.5, 0] (right side, post-Y-flip).
  // DistanceFromRoadEdge=2.0 => trees should be at Y < -3.5 (beyond outer edge).
  std::string xodr = MakeHeader()
      + MakeRoad(0, 0.f, 100.f, NegativeOnlyLanes())
      + "</OpenDRIVE>\n";

  auto map = OpenDriveParser::Load(xodr);
  ASSERT_TRUE(map.has_value());

  // FilterRoadsByPosition checks minpos.y > y > maxpos.y (Y axis inverted).
  const Vector3D minpos(-10.f,  20.f, -10.f);
  const Vector3D maxpos(110.f, -20.f,  10.f);

  auto result = map->GetMap().GetTreesTransform(minpos, maxpos, 10.f, 2.f);
  ASSERT_GT(result.size(), 0u) << "No trees generated for negative-only lane road";

  // Outer edge of lane -1 is at t=3.5m from road centre.
  // distancefromdrivinglineborder=2.0 => trees placed 2.0m beyond that edge.
  // After Y-flip, trees must be at |Y| >= 3.5 + 2.0 = 5.5.
  const float lane_outer_edge   = 3.5f;
  const float dist_from_edge    = 2.0f;
  const float min_expected_dist = lane_outer_edge + dist_from_edge;

  for (const auto& entry : result) {
    const float tree_y = std::abs(entry.first.location.y);
    EXPECT_NEAR(tree_y, min_expected_dist, TREE_Y_TOLERANCE)
        << "Tree Y=" << entry.first.location.y
        << " is not within ±" << TREE_Y_TOLERANCE << " of the expected minimum distance (|Y| = " << min_expected_dist << ")";
  }
}

void TestQgsProcessingAlgsPt1::modelerRasterCalculatorCreationOptions()
{
  std::unique_ptr<QgsProcessingAlgorithm> alg( QgsApplication::processingRegistry()->createAlgorithmById( u"native:modelerrastercalc"_s ) );
  QVERIFY( alg );

  const QString inputFilename = QStringLiteral( TEST_DATA_DIR ) + u"/raster/band1_int16_noct_epsg4326.tif"_s;
  const QTemporaryDir tempDir;
  const QString outputFilename = tempDir.filePath( u"modeler_raster_calculator.tif"_s );

  QVariantMap parameters;
  parameters.insert( u"LAYERS"_s, QStringList( { inputFilename } ) );
  parameters.insert( u"EXPRESSION"_s, u"\"A@1\""_s );
  parameters.insert( u"CREATION_OPTIONS"_s, u"TILED=YES|BLOCKXSIZE=16|BLOCKYSIZE=16"_s );
  parameters.insert( u"OUTPUT"_s, outputFilename );

  QgsProcessingContext context;
  QgsProcessingFeedback feedback;
  bool ok = false;
  alg->run( parameters, context, &feedback, &ok );
  QVERIFY( ok );

  gdal::dataset_unique_ptr dataset( GDALOpen( outputFilename.toUtf8().constData(), GA_ReadOnly ) );
  QVERIFY( dataset );

  int blockWidth = 0;
  int blockHeight = 0;
  GDALGetBlockSize( GDALGetRasterBand( dataset.get(), 1 ), &blockWidth, &blockHeight );
  QCOMPARE( blockWidth, 16 );
  QCOMPARE( blockHeight, 16 );
}

size_t QueryComputeUnits(const sycl::device& sycl_device) {
    try {
        const size_t slices =
                sycl_device
                        .get_info<sycl::ext::intel::info::device::gpu_slices>();
        const size_t subslices_per_slice = sycl_device.get_info<
                sycl::ext::intel::info::device::gpu_subslices_per_slice>();
        if (slices > 0 && subslices_per_slice > 0) {
            return slices * subslices_per_slice;
        }
    } catch (const sycl::exception&) {
        // Extension unsupported on this device; fall through.
    }
    return static_cast<size_t>(
            sycl_device.get_info<sycl::info::device::max_compute_units>());
}

sycl::queue GetQueue(const Device& device) {
    auto it = g_queue_overrides.find(device);
    if (it != g_queue_overrides.end()) {
        return it->second;
    }
    return SYCLContext::GetInstance().GetDefaultQueue(device);
}

SYCLScopedQueue::SYCLScopedQueue(const Device& device, sycl::queue queue)
    : device_(device) {
    auto it = g_queue_overrides.find(device_);
    if (it != g_queue_overrides.end()) {
        prev_queue_ = it->second;
    }
    g_queue_overrides[device_] = std::move(queue);
}

SYCLScopedQueue::~SYCLScopedQueue() {
    if (prev_queue_) {
        g_queue_overrides[device_] = *prev_queue_;
    } else {
        g_queue_overrides.erase(device_);
    }
}

size_t SYCLContext::GetComputeUnits(const sycl::device& sycl_device) {
    std::lock_guard<std::mutex> lock(g_compute_units_mutex);
    auto it = g_compute_units_cache.find(sycl_device);
    if (it != g_compute_units_cache.end()) {
        return it->second;
    }
    const size_t compute_units = QueryComputeUnits(sycl_device);
    g_compute_units_cache.emplace(sycl_device, compute_units);
    return compute_units;
}

id IoUBevSYCLKernel(sycl::queue &queue,
                      const float *boxes_a,
                      const float *boxes_b,
                      float *iou,
                      int num_a,
                      int num_b) {
    const int n = num_a * num_b;
    if (n == 0) {
        return;
    }
    core::ParallelFor(queue, n, [=](int64_t idx64) {
        const int idx = static_cast<int>(idx64);
        const int idx_a = idx / num_b;
        const int idx_b = idx % num_b;
        const float *box_a = boxes_a + idx_a * 5;
        const float *box_b = boxes_b + idx_b * 5;
        iou[idx_a * num_b + idx_b] = IoUBev2DWithCenterAndSize(box_a, box_b);
    });
}

id IoU3dSYCLKernel(sycl::queue &queue,
                     const float *boxes_a,
                     const float *boxes_b,
                     float *iou,
                     int num_a,
                     int num_b) {
    const int n = num_a * num_b;
    if (n == 0) {
        return;
    }
    core::ParallelFor(queue, n, [=](int64_t idx64) {
        const int idx = static_cast<int>(idx64);
        const int idx_a = idx / num_b;
        const int idx_b = idx % num_b;
        const float *box_a = boxes_a + idx_a * 7;
        const float *box_b = boxes_b + idx_b * 7;
        iou[idx_a * num_b + idx_b] = IoU3DWithCenterAndSize(box_a, box_b);
    });
}

id IoUBevSYCLKernel(const core::Device &device,
                      const float *boxes_a,
                      const float *boxes_b,
                      float *iou,
                      int num_a,
                      int num_b) {
    sycl::queue queue = core::sy::GetQueue(device);
    IoUBevSYCLKernel(queue, boxes_a, boxes_b, iou, num_a, num_b);
}

id IoU3dSYCLKernel(const core::Device &device,
                     const float *boxes_a,
                     const float *boxes_b,
                     float *iou,
                     int num_a,
                     int num_b) {
    sycl::queue queue = core::sy::GetQueue(device);
