}

t NmsSYCLKernel(sycl::queue &queue,
                  const float *boxes,
                  const float *scores,
                  int n,
                  double nms_overlap_thresh,
                  int64_t *keep_indices_out) {
    if (n == 0) {
        return 0;
    }

    const int num_block_cols = utility::DivUp(n, NMS_BLOCK_SIZE);
    const int num_block_rows = num_block_cols;  // Grid is n x n in blocks.

    // Rank `scores` in descending order entirely on device: fill
    // sort_indices with 0..n-1, then stable_sort it by score via oneDPL
    // (mirrors Nms.cu's thrust::sequence + thrust::stable_sort_by_key).
    // stable_sort has no non-blocking oneDPL async equivalent, and the
    // device policy does not inherit a queue's pending work when the queue
    // is out-of-order (as PyTorch's XPU queue can be), so an explicit
    // barrier -- not a wait() -- makes the iota visible to it without
    // stalling the host.
    int64_t *sort_indices = sycl::malloc_device<int64_t>(n, queue);
    sycl::event iota_event = queue.parallel_for(
            sycl::range<1>(n),
            [=](sycl::id<1> id) [[intel::kernel_args_restrict]] {
                sort_indices[id[0]] = static_cast<int64_t>(id[0]);
            });
    queue.ext_oneapi_submit_barrier({iota_event});

    auto policy = oneapi::dpl::execution::make_device_policy(queue);
    std::stable_sort(
            policy, sort_indices, sort_indices + n,
            [scores](int64_t i, int64_t j) { return scores[i] > scores[j]; });

    // mask/remv/count are kernel-private scratch (never touched by PyTorch
    // or oneDPL), so they are backed by sycl::buffer rather than
    // malloc_device/free (see file header).
    sycl::buffer<uint64_t, 1> mask_buf{
            sycl::range<1>(static_cast<size_t>(n) * num_block_cols)};

    const size_t num_groups =
            static_cast<size_t>(num_block_rows) * num_block_cols;
    const sycl::range<1> global(num_groups * NMS_BLOCK_SIZE);
    const sycl::range<1> local(NMS_BLOCK_SIZE);

    queue.submit([&](sycl::handler &cgh) {
        sycl::local_accessor<float, 1> block_boxes(NMS_BLOCK_SIZE * 5, cgh);
        sycl::accessor mask_acc(mask_buf, cgh, sycl::write_only, sycl::no_init);

        cgh.parallel_for(
                sycl::nd_range<1>(global, local),
                // Distinct buffers — safe for [[intel::kernel_args_restrict]].
                [=](sycl::nd_item<1> item) [[intel::kernel_args_restrict]] {
                    const int group_id = static_cast<int>(item.get_group(0));
                    const int block_row_idx = group_id / num_block_cols;
                    const int block_col_idx = group_id % num_block_cols;
                    const int lid = static_cast<int>(item.get_local_id(0));

                    const int row_size = sycl::min(
                            n - block_row_idx * NMS_BLOCK_SIZE, NMS_BLOCK_SIZE);
                    const int col_size = sycl::min(
                            n - block_col_idx * NMS_BLOCK_SIZE, NMS_BLOCK_SIZE);

                    // Stage the block_col_idx-th column block of boxes into
                    // local memory (matches CUDA's __shared__ block_boxes).
                    if (lid < col_size) {
                        float *dst = &block_boxes[lid * 5];
                        const int src_idx =
                                NMS_BLOCK_SIZE * block_col_idx + lid;
                        const float *src = boxes + sort_indices[src_idx] * 5;
                        dst[0] = src[0];
                        dst[1] = src[1];
                        dst[2] = src[2];
                        dst[3] = src[3];
                        dst[4] = src[4];
                    }
                    sycl::group_barrier(item.get_group());

                    if (lid < row_size) {
                        const int src_idx =
                                NMS_BLOCK_SIZE * block_row_idx + lid;
                        // On the diagonal block, skip self- and
                        // already-compared pairs (dst_idx <= src local idx).
                        int dst_idx =
                                (block_row_idx == block_col_idx) ? lid + 1 : 0;

                        uint64_t t = 0;
                        while (dst_idx < col_size) {
                            if (IoUBev2DWithMinAndMax(
                                        boxes + sort_indices[src_idx] * 5,
                                        &block_boxes[dst_idx * 5]) >
                                nms_overlap_thresh) {
                                t |= 1ULL << dst_idx;
                            }
                            dst_idx++;
                        }
                        mask_acc[src_idx * num_block_cols + block_col_idx] = t;
                    }
                });
    });

    // Greedy keep-loop: run on-device as a single-work-item kernel (see file
    // header comment), writing straight into the caller-owned
    // `keep_indices_out` (no separate device allocation/free for the result,
    // and no device->host copy of the result data -- only the final count,
    // a single int, needs to reach the host).
    sycl::buffer<uint64_t, 1> remv_buf{sycl::range<1>(num_block_cols)};
    sycl::buffer<int, 1> count_buf{sycl::range<1>(1)};

    queue.submit([&](sycl::handler &cgh) {
        sycl::accessor mask_acc(mask_buf, cgh, sycl::read_only);
        sycl::accessor remv_acc(remv_buf, cgh, sycl::write_only, sycl::no_init);
        sycl::accessor count_acc(count_buf, cgh, sycl::write_only,
                                 sycl::no_init);
        cgh.single_task([=]() {
            count_acc[0] = NmsGreedyKeepCore(&mask_acc[0], sort_indices, n,
                                             &remv_acc[0], keep_indices_out);
        });
    });

    // Reading `count` back to the host via a host_accessor is a genuine
    // synchronization point (PyTorch needs the tensor shape on the host);
    // it blocks until the single_task above (count_buf's only writer) has
    // completed, replacing the previous explicit memcpy + wait().
    sycl::host_accessor count_acc(count_buf, sycl::read_only);
    const int count = count_acc[0];

    // sort_indices is raw USM (see file header); the host_accessor read
    // above blocks on the single_task, whose sort_indices read happens
    // after the stable_sort above, so freeing it here is safe.
    sycl::free(sort_indices, queue);

    return count;
}

}

id roipool3dLauncherCPU(int batch_size,
                          int pts_num,
                          int boxes_num,
                          int feature_in_len,
                          int sampled_pts_num,
                          const float *xyz,
                          const float *boxes3d,
                          const float *pts_feature,
                          float *pooled_features,
                          int *pooled_empty_flag) {
    tbb::parallel_for(
            tbb::blocked_range<int>(0, batch_size * boxes_num),
            [&](const tbb::blocked_range<int> &r) {
                for (int idx = r.begin(); idx != r.end(); ++idx) {
                    const int i = idx / boxes_num;          // batch index
                    const int boxes_idx = idx % boxes_num;  // box index

                    int cnt = 0;
                    for (int k = 0; k < pts_num; k++) {
                        const int pt_offset = i * pts_num * 3 + k * 3;
                        const int box_offset =
                                i * boxes_num * 7 + boxes_idx * 7;

                        const int cur_in_flag = pt_in_box3d(
                                xyz[pt_offset], xyz[pt_offset + 1],
                                xyz[pt_offset + 2], boxes3d[box_offset],
                                boxes3d[box_offset + 1],
                                boxes3d[box_offset + 2],
                                boxes3d[box_offset + 3],
                                boxes3d[box_offset + 4],
                                boxes3d[box_offset + 5],
                                boxes3d[box_offset + 6], 10.0);
                        if (cur_in_flag) {
                            if (cnt < sampled_pts_num) {
                                const int feature_out_offset =
                                        i * boxes_num * sampled_pts_num *
                                                (3 + feature_in_len) +
                                        boxes_idx * sampled_pts_num *
                                                (3 + feature_in_len) +
                                        cnt * (3 + feature_in_len);
                                const int feature_in_offset =
                                        i * pts_num * feature_in_len +
                                        k * feature_in_len;

                                for (int j = 0; j < 3; j++)
                                    pooled_features[feature_out_offset + j] =
                                            xyz[pt_offset + j];
                                for (int j = 0; j < feature_in_len; j++)
                                    pooled_features[feature_out_offset + 3 +
                                                    j] =
                                            pts_feature[feature_in_offset + j];

                                cnt++;
                            } else {
                                break;
                            }
                        }
                    }

                    if (cnt == 0) {
                        pooled_empty_flag[i * boxes_num + boxes_idx] = 1;
                    } else if (cnt < sampled_pts_num) {
                        // Duplicate same points for sampling.
                        for (int k = cnt; k < sampled_pts_num; k++) {
                            const int duplicate_idx = k % cnt;
                            const int src_offset =
                                    i * boxes_num * sampled_pts_num *
                                            (3 + feature_in_len) +
                                    boxes_idx * sampled_pts_num *
                                            (3 + feature_in_len) +
                                    duplicate_idx * (3 + feature_in_len);
                            const int dst_offset =
                                    i * boxes_num * sampled_pts_num *
                                            (3 + feature_in_len) +
                                    boxes_idx * sampled_pts_num *
                                            (3 + feature_in_len) +
                                    k * (3 + feature_in_len);
                            for (int j = 0; j < 3 + feature_in_len; j++)
                                pooled_features[dst_offset + j] =
                                        pooled_features[src_offset + j];
                        }
                    }
                }
            });
}

keStrideA(int64_t ld) {
    if constexpr (cute::is_same_v<Layout, cutlass::layout::RowMajor>) {
        return cute::make_stride(ld, cute::Int<1>{}, int64_t(0));
    } else {
        return cute::make_stride(cute::Int<1>{}, ld, int64_t(0));
    }
}

/// B

rideB(int64_t ld) {
    if constexpr (cute::is_same_v<Layout, cutlass::layout::RowMajor>) {
        return cute::make_stride(cute::Int<1>{}, ld, int64_t(0));
    } else {
        return cute::make_stride(ld, cute::Int<1>{}, int64_t(0));
    }
}

/// Runs

utlass::Status, sycl::event> RunGemmXmxTf32RowMajorOutput(
        sycl::queue& queue,
        int m,
        int n,
        int k,
        float alpha,
        const float* A,
        int64_t lda,
        const float* B,
        int64_t ldb,
        float beta,
        const float* C,
        int64_t ldc,
        float* D,
        int64_t ldd,
        const std::vector<sycl::event>& deps = {}) {
    using ElementA = cutlass::tfloat32_t;
    using ElementB = cutlass::tfloat32_t;
    using ElementAccumulator = float;
    using ElementC = float;
    using ElementOutput = float;
    using ElementComputeEpilogue = float;

    using LayoutC = cutlass::layout::RowMajor;
    using LayoutD = cutlass::layout::RowMajor;

    // Alignment is expressed in elements, not bytes: sycl-tla requires the
    // operand's contiguous extent to be aligned to 128 bits (see
    // `xe_mma.hpp`'s `copy_alignment_bits`); with 4-byte tfloat32_t/float
    // elements, 128 bits / 32 bits = 4 elements.
    constexpr int AlignmentA = 4;
    constexpr int AlignmentB = 4;
    constexpr int AlignmentC = 4;
    constexpr int AlignmentD = 4;

    using CollectiveMainloop = cutlass::gemm::collective::CollectiveBuilder<
            cutlass::arch::IntelXe, cutlass::arch::OpClassTensorOp, ElementA,
            LayoutA, AlignmentA, ElementB, LayoutB, AlignmentB,
            ElementAccumulator, TileShape,
            cute::Shape<cute::_1, cute::_1, cute::_1>,
            cutlass::gemm::collective::StageCountAuto,
            cutlass::gemm::collective::KernelScheduleAuto>::CollectiveOp;

    using CollectiveEpilogue = cutlass::epilogue::collective::CollectiveBuilder<
            cutlass::arch::IntelXe, cutlass::arch::OpClassTensorOp, TileShape,
            cute::Shape<cute::_1, cute::_1, cute::_1>,
            cutlass::epilogue::collective::EpilogueTileAuto,
            ElementComputeEpilogue, ElementAccumulator, ElementC, LayoutC,
            AlignmentC, ElementOutput, LayoutD, AlignmentD,
            cutlass::epilogue::collective::EpilogueScheduleAuto>::CollectiveOp;

    using GemmKernel = cutlass::gemm::kernel::GemmUniversal<
            cute::Shape<int, int, int, int>, CollectiveMainloop,
            CollectiveEpilogue>;

    using Gemm = cutlass::gemm::device::GemmUniversalAdapter<GemmKernel>;

    using StrideA = typename Gemm::GemmKernel::StrideA;
    using StrideB = typename Gemm::GemmKernel::StrideB;
    using StrideC = typename Gemm::GemmKernel::StrideC;
    using StrideD = typename Gemm::GemmKernel::StrideD;

    // Build CuTe strides directly from the caller-provided leading
    // dimensions (general strided case, not just the packed/contiguous
    // case): ColumnMajor (rows x cols) -> stride (1, ld); RowMajor
    // (rows x cols) -> stride (ld, 1); batch (L=1) stride is unused (0).
    // The unit-stride dimension's type is a compile-time cute::C<1> (fixed
    // by TagToStrideA_t/TagToStrideB_t), so it must be constructed in place
    // per-layout rather than through a single runtme-typed helper.
    StrideA stride_A = MakeStrideA<LayoutA>(lda);
    StrideB stride_B = MakeStrideB<LayoutB>(ldb);
    // C/D are always RowMajor here (rows=m, cols=n) -> stride (ld, 1).
    StrideC stride_C = cute::make_stride(ldc, cute::Int<1>{}, int64_t(0));
    StrideD stride_D = cute::make_stride(ldd, cute::Int<1>{}, int64_t(0));

    cutlass::KernelHardwareInfo hw_info;
    hw_info.sm_count = static_cast<int>(
            open3d::core::sy::SYCLContext::GetInstance().GetComputeUnits(
                    queue.get_device()));

    typename Gemm::GemmKernel::Arguments arguments{
            cutlass::gemm::GemmUniversalMode::kGemm,
            {m, n, k, 1},
            {reinterpret_cast<const ElementA*>(A), stride_A,
             reinterpret_cast<const ElementB*>(B), stride_B},
            {{alpha, beta}, C, stride_C, D, stride_D},
            hw_info};

    Gemm gemm_op;
    size_t workspace_size = Gemm::get_workspace_size(arguments);
    void* workspace = nullptr;
    if (workspace_size > 0) {
        workspace = sycl::malloc_device(workspace_size, queue);
    }

    auto status = gemm_op.can_implement(arguments);
    if (status != cutlass::Status::kSuccess) {
        if (workspace) sycl::free(workspace, queue);
        return {status, sycl::event()};
    }
    status = gemm_op.initialize(arguments, workspace, &queue);
    if (status != cutlass::Status::kSuccess) {
        if (workspace) sycl::free(workspace, queue);
        return {status, sycl::event()};
    }
    // sycl-tla's GemmUniversalAdapter::run() takes only a sycl::queue*, with
    // no event-dependency parameter, so an explicit barrier is needed to
    // make the GEMM's kernels wait for `deps` on a possibly out-of-order
    // queue (submission order alone would not guarantee this).
    if (!deps.empty()) {
        queue.ext_oneapi_submit_barrier(deps);
    }
    status = gemm_op.run(&queue);
    // sycl-tla's GemmUniversalAdapter::run() returns only a cutlass::Status,
    // not a sycl::event, so there is no per-kernel completion event to
    // return directly. A no-arg submit_barrier() is a correct (if coarser)
    // substitute: on this in-order queue it completes only after every
    // command submitted so far -- including the GEMM just launched -- has
    // finished, so a caller chaining depends_on({done}) is still correctly
    // serialized after this GEMM. This lets the function return without
    // blocking the host thread here.
    sycl::event done = queue.ext_oneapi_submit_barrier();
    if (workspace) {
        // Free the scratch workspace only once the GEMM (and hence all its
        // reads of it) has completed; never free while a kernel may still
        // be running (see Phase 2 buffer-lifetime rule).
        queue.submit([&](sycl::handler& cgh) {
            cgh.depends_on(done);
            cgh.host_task(
                    [workspace, &queue]() { sycl::free(workspace, queue); });
        });
    }
    return {status, done};
}

/// Runs

utlass::Status, sycl::event> RunGemmIeeeFp32RowMajorOutput(
        sycl::queue& queue,
        int m,
        int n,
        int k,
        float alpha,
        const float* A,
        int64_t lda,
        const float* B,
        int64_t ldb,
        float beta,
        const float* C,
        int64_t ldc,
        float* D,
        int64_t ldd,
        const std::vector<sycl::event>& deps = {}) {
    using ElementA = float;
    using ElementB = float;
    using ElementAccumulator = float;
    using ElementC = float;
    using ElementOutput = float;
    using ElementComputeEpilogue = float;
    using LayoutC = cutlass::layout::RowMajor;
    using LayoutD = cutlass::layout::RowMajor;

    constexpr int AlignmentA = sizeof(ElementA);
    constexpr int AlignmentB = sizeof(ElementB);
    constexpr int AlignmentC = sizeof(ElementC);
    constexpr int AlignmentD = sizeof(ElementOutput);

    using CollectiveMainloop =
            typename cutlass::gemm::collective::CollectiveBuilder<
                    cutlass::arch::Agnostic, cutlass::arch::OpMultiplyAdd,
                    ElementA, LayoutA, AlignmentA, ElementB, LayoutB,
                    AlignmentB, ElementAccumulator, TileShape,
                    cute::Shape<cute::_1, cute::_1, cute::_1>,
                    cutlass::gemm::collective::StageCountAuto,
                    cutlass::gemm::collective::KernelScheduleAuto>::
                    CollectiveOp;

    using EpilogueOp = cutlass::epilogue::fusion::LinearCombination<
            ElementOutput, ElementComputeEpilogue, ElementAccumulator,
            ElementAccumulator>;
    using CollectiveEpilogue =
            typename cutlass::epilogue::collective::CollectiveBuilder<
                    cutlass::arch::Agnostic, cutlass::arch::OpMultiplyAdd,
                    TileShape, cute::Shape<cute::_1, cute::_1, cute::_1>,
                    cutlass::epilogue::collective::EpilogueTileAuto,
                    ElementComputeEpilogue, ElementAccumulator, ElementC,
                    LayoutC, AlignmentC, ElementOutput, LayoutD, AlignmentD,
                    cutlass::epilogue::collective::EpilogueScheduleAuto,
                    EpilogueOp>::CollectiveOp;

    using GemmKernel = cutlass::gemm::kernel::GemmUniversal<
            cute::Shape<int, int, int, int>, CollectiveMainloop,
            CollectiveEpilogue>;
    using Gemm = cutlass::gemm::device::GemmUniversalAdapter<GemmKernel>;

    using StrideA = typename Gemm::GemmKernel::StrideA;
    using StrideB = typename Gemm::GemmKernel::StrideB;
    using StrideC = typename Gemm::GemmKernel::StrideC;
    using StrideD = typename Gemm::GemmKernel::StrideD;

    StrideA stride_A = MakeStrideA<LayoutA>(lda);
    StrideB stride_B = MakeStrideB<LayoutB>(ldb);
    StrideC stride_C = cute::make_stride(ldc, cute::Int<1>{}, int64_t(0));
    StrideD stride_D = cute::make_stride(ldd, cute::Int<1>{}, int64_t(0));

    cutlass::KernelHardwareInfo hw_info;
    hw_info.sm_count = static_cast<int>(
            open3d::core::sy::SYCLContext::GetInstance().GetComputeUnits(
                    queue.get_device()));

    typename Gemm::GemmKernel::Arguments arguments{
            cutlass::gemm::GemmUniversalMode::kGemm,
            {m, n, k, 1},
            {A, stride_A, B, stride_B},
            {{alpha, beta}, C, stride_C, D, stride_D},
            hw_info};

    Gemm gemm_op;
    size_t workspace_size = Gemm::get_workspace_size(arguments);
    void* workspace = nullptr;
    if (workspace_size > 0) {
        workspace = sycl::malloc_device(workspace_size, queue);
    }

    auto status = gemm_op.can_implement(arguments);
    if (status != cutlass::Status::kSuccess) {
        if (workspace) sycl::free(workspace, queue);
        return {status, sycl::event()};
    }
    status = gemm_op.initialize(arguments, workspace, &queue);
    if (status != cutlass::Status::kSuccess) {
        if (workspace) sycl::free(workspace, queue);
        return {status, sycl::event()};
    }
    // See the analogous comment in RunGemmXmxTf32RowMajorOutput above: an
    // explicit barrier is needed since run() has no event-dependency param.
    if (!deps.empty()) {
        queue.ext_oneapi_submit_barrier(deps);
    }
    status = gemm_op.run(&queue);
    // See the analogous comment in RunGemmXmxTf32RowMajorOutput above: a
    // no-arg submit_barrier() stands in for sycl-tla's missing per-kernel
    // completion event, letting this function return without blocking here.
    sycl::event done = queue.ext_oneapi_submit_barrier();
    if (workspace) {
        queue.submit([&](sycl::handler& cgh) {
            cgh.depends_on(done);
            cgh.host_task(
                    [workspace, &queue]() { sycl::free(workspace, queue); });
        });
    }
    return {status, done};
}

/// Colle

utlass::Status, sycl::event> RunTf32(const GemmArgs& a) {
    return RunGemmXmxTf32RowMajorOutput<Tile, LayoutA, LayoutB>(
            a.queue, a.m, a.n, a.k, a.alpha, a.A, a.lda, a.B, a.ldb, a.beta,
            a.C, a.ldc, a.D, a.ldd, a.deps);
}

/// Runs

utlass::Status, sycl::event> RunIeee(const GemmArgs& a) {
    return RunGemmIeeeFp32RowMajorOutput<Tile, LayoutA, LayoutB>(
            a.queue, a.m, a.n, a.k, a.alpha, a.A, a.lda, a.B, a.ldb, a.beta,
            a.C, a.ldc, a.D, a.ldd, a.deps);
}

/// True

GemmColumnMajorSYCL(sycl::queue& queue,
                                int m,
                                int n,
                                int k,
                                float alpha,
                                const float* A,
                                int64_t lda,
                                const float* B,
                                int64_t ldb,
                                float beta,
                                float* C,
                                int64_t ldc,
                                bool allow_tf32,
                                const std::vector<sycl::event>& deps) {
    using namespace sycl_gemm_detail;
    // D_colmajor(M,N) = A*B  <=>  D_rowmajor(N,M) = B^T * A^T (same memory,
    // ld=ldc; see the file header). Swap the operands, swap M/N and transpose
    // the layout tags; C aliases D so we accumulate in place as CUDA does.
    using SwappedLayoutA = typename TransposeLayout<LayoutB>::type;
    using SwappedLayoutB = typename TransposeLayout<LayoutA>::type;

    const GemmArgs args{queue, n,    m, k,   alpha, B,   ldb, A,
                        lda,   beta, C, ldc, C,     ldc, deps};

    // TF32/XMX requires every contiguous operand extent (lda, ldb, ldc, and
    // m/n/k themselves -- the un-swapped, caller-facing values) to be a
    // multiple of 4 elements (see AlignmentA/B/C/D above); anything else
    // silently fails `can_implement`, so check up front and fall back to the
    // IEEE fp32 path with a warning rather than relying on that failure.
    if (allow_tf32 &&
        !(IsTf32Aligned(lda) && IsTf32Aligned(ldb) && IsTf32Aligned(ldc) &&
          IsTf32Aligned(m) && IsTf32Aligned(n) && IsTf32Aligned(k))) {
        static std::once_flag warned_once;
        std::call_once(warned_once, [&]() {
            utility::LogWarning(
                    "GemmSYCL: allow_tf32 was requested, but the operand "
                    "shape/strides (m={}, n={}, k={}, lda={}, ldb={}, "
                    "ldc={}) are not all multiples of 4 elements, which the "
                    "TF32/XMX path requires. Falling back to the IEEE fp32 "
                    "path for this and all other unaligned problem shapes.",
                    m, n, k, lda, ldb, ldc);
        });
        allow_tf32 = false;
    }

    std::pair<cutlass::Status, sycl::event> result{
            cutlass::Status::kErrorNotSupported, sycl::event()};
    if (allow_tf32) {
        result = RunTf32<SwappedLayoutA, SwappedLayoutB>(args);
    }
    if (result.first != cutlass::Status::kSuccess) {
        result = RunIeee<SwappedLayoutA, SwappedLayoutB>(args);
    }
    if (result.first != cutlass::Status::kSuccess) {
        std::ostringstream msg;
        msg << "GemmSYCL: sycl-tla GEMM cannot implement problem m=" << m
            << ", n=" << n << ", k=" << k << ", lda=" << lda << ", ldb=" << ldb
            << ", ldc=" << ldc << (allow_tf32 ? " (TF32 XMX)" : " (IEEE fp32)");
        throw std::runtime_error(msg.str());
    }
    return result.second;
}

// The on

sycl::event MultiplyColumnsSYCL(sycl::queue& queue,
                                size_t rows,
                                size_t cols,
                                T* col_major_matrix,
                                const T* const vector,
                                const std::vector<sycl::event>& deps) {
    const size_t n = rows * cols;
    if (n == 0) return sycl::event();
    const size_t num_groups = (n + kBlockSize - 1) / kBlockSize;
    return queue.submit([&](sycl::handler& cgh) {
        cgh.depends_on(deps);
        cgh.parallel_for(
                sycl::nd_range<1>(sycl::range<1>(num_groups * kBlockSize),
                                  sycl::range<1>(kBlockSize)),
                // Distinct buffers — safe for [[intel::kernel_args_restrict]].
                [=](sycl::nd_item<1> item) [[intel::kernel_args_restrict]] {
                    const size_t idx = item.get_global_id(0);
                    if (idx >= n) return;
                    const size_t col = idx / rows;
                    col_major_matrix[idx] *= vector[col];
                });
    });
}

cl::event MultiplyAndCopyColumnsSYCL(sycl::queue& queue,
                                       size_t rows,
                                       size_t cols,
                                       T* out_ptr,
                                       const T* const col_major_matrix,
                                       const T* const vector,
                                       const std::vector<sycl::event>& deps) {
    const size_t n = rows * cols;
    if (n == 0) return sycl::event();
    const size_t num_groups = (n + kBlockSize - 1) / kBlockSize;
    return queue.submit([&](sycl::handler& cgh) {
        cgh.depends_on(deps);
        cgh.parallel_for(
                sycl::nd_range<1>(sycl::range<1>(num_groups * kBlockSize),
                                  sycl::range<1>(kBlockSize)),
                // Distinct buffers — safe for [[intel::kernel_args_restrict]].
                [=](sycl::nd_item<1> item) [[intel::kernel_args_restrict]] {
                    const size_t idx = item.get_global_id(0);
                    if (idx >= n) return;
                    const size_t col = idx / rows;
                    out_ptr[idx] = col_major_matrix[idx] * vector[col];
                });
    });
}

te

sycl::event FillColumnSYCL(sycl::queue& queue,
                           TReal* columns,
                           int in_channels,
                           TIndex begin_idx,
                           TIndex end_idx,
                           TIndex num_out,
                           TIndex num_inp,
                           const TReal* const inp_features,
                           const TReal* const inp_importance,
                           size_t neighbors_index_size,
                           const TIndex* const neighbors_index,
                           const TKernelIndex* const neighbors_kernel_index,
                           const TReal* const neighbors_importance,
                           const int64_t* const neighbors_row_splits,
                           const int num_kernel_elements,
                           bool normalize,
                           const std::vector<sycl::event>& deps) {
    const TIndex num_columns = end_idx - begin_idx;
    if (num_columns <= 0) return sycl::event();

    sycl::event fill_event = queue.fill(
            columns, TReal(0),
            size_t(num_kernel_elements) * in_channels * num_columns, deps);

    const bool point_importance = inp_importance != nullptr;
    const bool neighbor_importance = neighbors_importance != nullptr;

    return queue.submit([&](sycl::handler& cgh) {
        cgh.depends_on(fill_event);
        cgh.parallel_for(
                sycl::nd_range<1>(sycl::range<1>(num_columns * kWGSize),
                                  sycl::range<1>(kWGSize)),
                // Distinct buffers — safe for [[intel::kernel_args_restrict]].
                [=](sycl::nd_item<1> item) [[intel::kernel_args_restrict]] {
                    const TIndex out_idx =
                            begin_idx + static_cast<TIndex>(item.get_group(0));
                    if (out_idx >= end_idx) return;

                    const TIndex col_idx = out_idx - begin_idx;
                    TReal* out_column = columns + size_t(num_kernel_elements) *
                                                          in_channels * col_idx;
                    const int64_t neighbor_start =
                            neighbors_row_splits[out_idx];
                    const int64_t neighbor_end =
                            neighbors_row_splits[out_idx + 1];

                    auto group = item.get_group();
                    const size_t lid = item.get_local_id(0);
                    const size_t lsize = item.get_local_range(0);

                    TReal normalizer = TReal(0);
                    if (normalize) {
                        if (neighbor_importance) {
                            TReal local_sum = TReal(0);
                            for (int64_t n_idx = neighbor_start +
                                                 static_cast<int64_t>(lid);
                                 n_idx < neighbor_end;
                                 n_idx += static_cast<int64_t>(lsize)) {
                                local_sum += neighbors_importance[n_idx];
                            }
                            normalizer = sycl::reduce_over_group(
                                    group, local_sum, sycl::plus<TReal>());
                        } else {
                            normalizer = TReal(neighbor_end - neighbor_start);
                        }
                    }

                    for (int64_t n_idx = neighbor_start; n_idx < neighbor_end;
                         ++n_idx) {
                        const TIndex inp_idx = neighbors_index[n_idx];
                        const TReal n_importance =
                                neighbor_importance
                                        ? neighbors_importance[n_idx]
                                        : TReal(1);
                        const int kernel_idx = neighbors_kernel_index[n_idx];

                        TReal importance = TReal(1);
                        if (point_importance)
                            importance = inp_importance[inp_idx];
                        if (neighbor_importance) importance *= n_importance;
                        if (normalize && normalizer != 0)
                            importance /= normalizer;

                        for (int ic = static_cast<int>(lid); ic < in_channels;
                             ic += static_cast<int>(lsize)) {
                            out_column[kernel_idx * in_channels + ic] =
                                    importance *
                                    inp_features[size_t(inp_idx) * in_channels +
                                                 ic];
                        }
                    }
                });
    });
}

cl::event FillColumnTransposeSYCL(
        sycl::queue& queue,
        TReal* columns,
        int in_channels,
        TIndex begin_idx,
        TIndex end_idx,
        TIndex num_out,
        TIndex num_inp,
        const TReal* const inp_features,
        const TReal* const inp_neighbors_importance_sum,
        const int64_t* const inp_neighbors_prefix_sum,
        size_t neighbors_index_size,
        const TIndex* const neighbors_index,
        const TKernelIndex* const neighbors_kernel_index,
        const TReal* const neighbors_importance,
        const int64_t* const neighbors_row_splits,
        const int num_kernel_elements,
        bool normalize,
        const std::vector<sycl::event>& deps) {
    const TIndex num_columns = end_idx - begin_idx;
    if (num_columns <= 0) return sycl::event();

    sycl::event fill_event = queue.fill(
            columns, TReal(0),
            size_t(num_kernel_elements) * in_channels * num_columns, deps);

    const bool neighbor_importance = neighbors_importance != nullptr;

    return queue.submit([&](sycl::handler& cgh) {
        cgh.depends_on(fill_event);
        cgh.parallel_for(
                sycl::nd_range<1>(sycl::range<1>(num_columns * kWGSize),
                                  sycl::range<1>(kWGSize)),
                // Distinct buffers — safe for [[intel::kernel_args_restrict]].
                [=](sycl::nd_item<1> item) [[intel::kernel_args_restrict]] {
                    const TIndex out_idx =
                            begin_idx + static_cast<TIndex>(item.get_group(0));
                    if (out_idx >= end_idx) return;

                    const TIndex col_idx = out_idx - begin_idx;
                    TReal* out_column = columns + size_t(num_kernel_elements) *
                                                          in_channels * col_idx;
                    const int64_t neighbor_start =
                            neighbors_row_splits[out_idx];
                    const int64_t neighbor_end =
                            neighbors_row_splits[out_idx + 1];

                    const size_t lid = item.get_local_id(0);
                    const size_t lsize = item.get_local_range(0);

                    for (int64_t n_idx = neighbor_start; n_idx < neighbor_end;
                         ++n_idx) {
                        const TIndex inp_idx = neighbors_index[n_idx];
                        const int kernel_idx = neighbors_kernel_index[n_idx];

                        TReal normalizer = TReal(1);
                        if (normalize) {
                            if (inp_neighbors_importance_sum) {
                                if (inp_neighbors_importance_sum[inp_idx] != 0)
                                    normalizer /= inp_neighbors_importance_sum
                                            [inp_idx];
                            } else {
                                const int64_t inp_neighbor_start =
                                        inp_neighbors_prefix_sum[inp_idx];
                                const int64_t inp_neighbor_end =
                                        inp_idx + 1 < num_inp
                                                ? inp_neighbors_prefix_sum
                                                          [inp_idx + 1]
                                                : static_cast<int64_t>(
                                                          neighbors_index_size);
                                const int64_t num_inp_neighbors =
                                        inp_neighbor_end - inp_neighbor_start;
                                if (num_inp_neighbors > 0)
                                    normalizer /= TReal(num_inp_neighbors);
                            }
                        }

                        for (int ic = static_cast<int>(lid); ic < in_channels;
                             ic += static_cast<int>(lsize)) {
                            TReal infeat =
                                    inp_features[size_t(inp_idx) * in_channels +
                                                 ic];
                            if (neighbor_importance)
                                infeat *= neighbors_importance[n_idx];
                            if (normalize) infeat *= normalizer;

                            sycl::atomic_ref<
                                    TReal, sycl::memory_order::relaxed,
                                    sycl::memory_scope::device,
                                    sycl::access::address_space::global_space>
                                    out_ref(out_column[kernel_idx *
                                                               in_channels +
                                                       ic]);
                            out_ref.fetch_add(infeat);
                        }
                    }
                });
    });
}

