void ContinuousConvBackpropFilterSYCL(
        const torch::Tensor& filters,
        const torch::Tensor& out_positions,
        const torch::Tensor& extents,
        const torch::Tensor& offset,
        const torch::Tensor& inp_positions,
        const torch::Tensor& inp_features,
        const torch::Tensor& inp_importance,
        const torch::Tensor& neighbors_index,
        const torch::Tensor& neighbors_importance,
        const torch::Tensor& neighbors_row_splits,
        const torch::Tensor& out_features_gradient,
        const bool align_corners,
        const open3d::ml::impl::CoordinateMapping coordinate_mapping,
        const bool normalize,
        const open3d::ml::impl::InterpolationMode interpolation,
        const int64_t max_temp_mem_MB,
        const bool allow_tf32,
        torch::Tensor& filter_backprop) {
    const bool individual_extents = extents.size(0) > 1;
    const bool isotropic_extents = extents.size(1) == 1;
    std::vector<int> filter_dims;
    for (auto d : filters.sizes()) {
        filter_dims.push_back(d);
    }

    sycl::queue& queue = c10::xpu::getCurrentXPUStream().queue();
    const int texture_alignment = 64;

    auto device = filters.device();

    RunSYCLWithTempMemory(
            device, max_temp_mem_MB,
            [&](void* temp_ptr, size_t& temp_size, size_t& max_temp_size) {
                CConvBackpropFilterSYCL<TFeat, TOut, TReal, TIndex>(
                        queue, temp_ptr, temp_size, max_temp_size,
                        texture_alignment, filter_backprop.data_ptr<TOut>(),
                        filter_dims, out_positions.size(0),
                        out_positions.data_ptr<TReal>(), inp_positions.size(0),
                        inp_positions.data_ptr<TReal>(),
                        inp_features.data_ptr<TFeat>(),
                        inp_importance.size(0)
                                ? inp_importance.data_ptr<TFeat>()
                                : nullptr,
                        neighbors_index.size(0),
                        neighbors_index.data_ptr<TIndex>(),
                        neighbors_importance.size(0)
                                ? neighbors_importance.data_ptr<TFeat>()
                                : nullptr,
                        neighbors_row_splits.data_ptr<int64_t>(),
                        extents.data_ptr<TReal>(), offset.data_ptr<TReal>(),
                        out_features_gradient.data_ptr<TFeat>(), interpolation,
                        coordinate_mapping, align_corners, individual_extents,
                        isotropic_extents, normalize, allow_tf32);
            });
}

void ContinuousConvSYCL(const torch::Tensor& filters,
                        const torch::Tensor& out_positions,
                        const torch::Tensor& extents,
                        const torch::Tensor& offset,
                        const torch::Tensor& inp_positions,
                        const torch::Tensor& inp_features,
                        const torch::Tensor& inp_importance,
                        const torch::Tensor& neighbors_index,
                        const torch::Tensor& neighbors_importance,
                        const torch::Tensor& neighbors_row_splits,
                        const bool align_corners,
                        const CoordinateMapping coordinate_mapping,
                        const bool normalize,
                        const InterpolationMode interpolation,
                        const int64_t max_temp_mem_MB,
                        const bool allow_tf32,
                        torch::Tensor& out_features) {
    const bool individual_extents = extents.size(0) > 1;
    const bool isotropic_extents = extents.size(1) == 1;
    std::vector<int> filter_dims;
    for (auto d : filters.sizes()) {
        filter_dims.push_back(d);
    }

    sycl::queue& queue = c10::xpu::getCurrentXPUStream().queue();
    // texture_alignment is a CUDA-specific concept; a small, safe default
    // alignment is used for the SYCL MemoryAllocation bookkeeping instead.
    const int texture_alignment = 64;

    auto device = filters.device();

    RunSYCLWithTempMemory(
            device, max_temp_mem_MB,
            [&](void* temp_ptr, size_t& temp_size, size_t& max_temp_size) {
                CConvComputeFeaturesSYCL<TFeat, TOut, TReal, TIndex>(
                        queue, temp_ptr, temp_size, max_temp_size,
                        texture_alignment, out_features.data_ptr<TOut>(),
                        filter_dims, filters.data_ptr<TFeat>(),
                        out_positions.size(0), out_positions.data_ptr<TReal>(),
                        inp_positions.size(0), inp_positions.data_ptr<TReal>(),
                        inp_features.data_ptr<TFeat>(),
                        inp_importance.size(0)
                                ? inp_importance.data_ptr<TFeat>()
                                : nullptr,
                        neighbors_index.size(0),
                        neighbors_index.data_ptr<TIndex>(),
                        neighbors_importance.size(0)
                                ? neighbors_importance.data_ptr<TFeat>()
                                : nullptr,
                        neighbors_row_splits.data_ptr<int64_t>(),
                        extents.data_ptr<TReal>(), offset.data_ptr<TReal>(),
                        interpolation, coordinate_mapping, align_corners,
                        individual_extents, isotropic_extents, normalize,
                        allow_tf32);
            });
}

