BuildSpatialHashTableSYCL(const torch::Tensor& points,
                               double radius,
                               const torch::Tensor& points_row_splits,
                               const std::vector<uint32_t>& hash_table_splits,
                               torch::Tensor& hash_table_index,
                               torch::Tensor& hash_table_cell_splits) {
    sycl::queue& queue = c10::xpu::getCurrentXPUStream().queue();

    // points_row_splits is on CPU (moved by BuildSpatialHashTableOps.cpp).
    const int64_t* row_splits_ptr = points_row_splits.data_ptr<int64_t>();
    const int batch_size = static_cast<int>(points_row_splits.size(0)) - 1;

    // Non-blocking: hash_table_index/hash_table_cell_splits are output
    // tensors owned by PyTorch's XPU caching allocator, which is
    // queue-ordered (see the Phase 3.2 GemmSYCL discussion) -- any further
    // consumption on this or another stream is correctly ordered without an
    // explicit host wait here.
    open3d::core::nns::BuildSpatialHashTableSYCLRaw<T>(
            queue, points.data_ptr<T>(), T(1) / T(2 * radius), batch_size,
            row_splits_ptr, hash_table_splits.data(),
            reinterpret_cast<uint32_t*>(
                    hash_table_cell_splits.data_ptr<int32_t>()),
            static_cast<size_t>(hash_table_cell_splits.numel()),
            reinterpret_cast<uint32_t*>(hash_table_index.data_ptr<int32_t>()));
}

#d

void FixedRadiusSearchSYCL(const torch::Tensor& points,
                           const torch::Tensor& queries,
                           double radius,
                           const torch::Tensor& points_row_splits,
                           const torch::Tensor& queries_row_splits,
                           const torch::Tensor& hash_table_splits,
                           const torch::Tensor& hash_table_index,
                           const torch::Tensor& hash_table_cell_splits,
                           const Metric metric,
                           const bool ignore_query_point,
                           const bool return_distances,
                           torch::Tensor& neighbors_index,
                           torch::Tensor& neighbors_row_splits,
                           torch::Tensor& neighbors_distance) {
    sycl::queue& queue = c10::xpu::getCurrentXPUStream().queue();
    auto dpl_policy = oneapi::dpl::execution::make_device_policy(queue);

    const T radius_t = static_cast<T>(radius);
    const T inv_voxel_size = T(1) / (T(2) * radius_t);
    T threshold = radius_t;
    if (metric == Metric::L2) {
        threshold = radius_t * radius_t;
    }

    const T* points_ptr = points.data_ptr<T>();
    const T* queries_ptr = queries.data_ptr<T>();
    const uint32_t* hash_index_ptr = reinterpret_cast<const uint32_t*>(
            hash_table_index.data_ptr<int32_t>());

    const int64_t num_queries = queries.size(0);
    const int num_batches = static_cast<int>(queries_row_splits.size(0)) - 1;

    // Allocate count buffer (uint32_t per query, cast from int32)
    torch::Tensor counts_tensor =
            torch::empty({num_queries},
                         torch::dtype(torch::kInt32).device(queries.device()));
    uint32_t* counts_ptr =
            reinterpret_cast<uint32_t*>(counts_tensor.data_ptr<int32_t>());

    const int64_t* q_row_splits_ptr = queries_row_splits.data_ptr<int64_t>();
    const uint32_t* ht_splits_ptr = reinterpret_cast<const uint32_t*>(
            hash_table_splits.data_ptr<int32_t>());
    const uint32_t* cell_splits_ptr = reinterpret_cast<const uint32_t*>(
            hash_table_cell_splits.data_ptr<int32_t>());

    // Pass 1: count neighbors per query
    for (int b = 0; b < num_batches; ++b) {
        const int64_t query_begin = q_row_splits_ptr[b];
        const int64_t query_end = q_row_splits_ptr[b + 1];
        const uint32_t first_cell_idx = ht_splits_ptr[b];
        const uint32_t hash_table_size = ht_splits_ptr[b + 1] - first_cell_idx;

        CountNeighborsSYCL<T>(queue, counts_ptr + query_begin, hash_index_ptr,
                              cell_splits_ptr + first_cell_idx, hash_table_size,
                              queries_ptr + 3 * query_begin,
                              query_end - query_begin, points_ptr,
                              inv_voxel_size, radius_t, metric,
                              ignore_query_point, threshold);
    }
    queue.wait_and_throw();

    // Build row_splits from counts via inclusive scan
    neighbors_row_splits =
            torch::zeros({num_queries + 1},
                         torch::dtype(torch::kInt64).device(queries.device()));
    int64_t* row_splits_ptr = neighbors_row_splits.data_ptr<int64_t>();
    std::inclusive_scan(dpl_policy, counts_ptr, counts_ptr + num_queries,
                        row_splits_ptr + 1, std::plus<int64_t>(), int64_t(0));
    queue.wait_and_throw();

    // Read total neighbor count from device
    int64_t total_neighbors = 0;
    if (num_queries > 0) {
        queue.memcpy(&total_neighbors, row_splits_ptr + num_queries,
                     sizeof(int64_t))
                .wait_and_throw();
    }

    auto device_type = queries.device().type();
    auto device_idx = queries.device().index();
    NeighborSearchAllocator<T, TIndex> output_allocator(device_type,
                                                        device_idx);

    TIndex* out_indices_ptr;
    T* out_dist_ptr;
    output_allocator.AllocIndices(&out_indices_ptr, total_neighbors);
    output_allocator.AllocDistances(&out_dist_ptr,
                                    return_distances ? total_neighbors : 0);

    // Pass 2: write neighbor indices (and optionally distances)
    for (int b = 0; b < num_batches; ++b) {
        const int64_t query_begin = q_row_splits_ptr[b];
        const int64_t query_end = q_row_splits_ptr[b + 1];
        const uint32_t first_cell_idx = ht_splits_ptr[b];
        const uint32_t hash_table_size = ht_splits_ptr[b + 1] - first_cell_idx;

        WriteNeighborsSYCL<T, TIndex>(
                queue, out_indices_ptr, out_dist_ptr,
                row_splits_ptr + query_begin, hash_index_ptr,
                cell_splits_ptr + first_cell_idx, hash_table_size,
                queries_ptr + 3 * query_begin, query_end - query_begin,
                points_ptr, inv_voxel_size, radius_t, metric,
                ignore_query_point, threshold, return_distances);
    }
    queue.wait_and_throw();

    neighbors_index = output_allocator.NeighborsIndex();
    neighbors_distance = output_allocator.NeighborsDistance();
}

std::tuple<torch::Tensor, torch::Tensor, torch::Tensor> InvertNeighborsListSYCL(
        int64_t num_points,
        const torch::Tensor& inp_neighbors_index,
        const torch::Tensor& inp_neighbors_row_splits,
        const torch::Tensor& inp_neighbors_attributes) {
    auto device = inp_neighbors_index.device();

    torch::Tensor neighbors_index =
            torch::empty(inp_neighbors_index.sizes(),
                         torch::dtype(ToTorchDtype<TIndex>()).device(device));
    torch::Tensor neighbors_row_splits = torch::zeros(
            {num_points + 1}, torch::dtype(torch::kInt64).device(device));
    torch::Tensor neighbors_attributes =
            torch::empty_like(inp_neighbors_attributes);

    // Scratch buffer: uint32_t count array of length num_points.
    // Torch has no native uint32 dtype (only [u]int8/16, int32/64), so
    // allocate as int32 (same bit width) and reinterpret the pointer.
    torch::Tensor count_buf = torch::empty(
            {num_points}, torch::dtype(ToTorchDtype<int32_t>()).device(device));

    int num_attributes;
    if (inp_neighbors_attributes.size(0) == 0) {
        num_attributes = 0;
    } else {
        num_attributes = 1;
        for (int i = 1; i < inp_neighbors_attributes.dim(); ++i)
            num_attributes *= inp_neighbors_attributes.size(i);
    }

    sycl::queue& queue = c10::xpu::getCurrentXPUStream().queue();

    open3d::ml::impl::InvertNeighborsListSYCL(
            queue, reinterpret_cast<uint32_t*>(count_buf.data_ptr<int32_t>()),
            inp_neighbors_index.data_ptr<TIndex>(),
            num_attributes ? inp_neighbors_attributes.data_ptr<TAttr>()
                           : nullptr,
            num_attributes, inp_neighbors_row_splits.data_ptr<int64_t>(),
            inp_neighbors_row_splits.size(0) - 1,
            neighbors_index.data_ptr<TIndex>(),
            num_attributes ? neighbors_attributes.data_ptr<TAttr>() : nullptr,
            neighbors_index.size(0), neighbors_row_splits.data_ptr<int64_t>(),
            static_cast<size_t>(num_points));

    return std::make_tuple(neighbors_index, neighbors_row_splits,
                           neighbors_attributes);
}

void KnnSearchSYCL(const torch::Tensor& points,
                   const torch::Tensor& queries,
                   const int64_t k,
                   const torch::Tensor& points_row_splits,
                   const torch::Tensor& queries_row_splits,
                   torch::Tensor& neighbors_index,
                   torch::Tensor& neighbors_row_splits,
                   torch::Tensor& neighbors_distance) {
    open3d::core::Tensor points_ = TorchToOpen3DTensor(points);
    open3d::core::Tensor queries_ = TorchToOpen3DTensor(queries);
    open3d::core::Tensor points_row_splits_ =
            TorchToOpen3DTensor(points_row_splits);
    open3d::core::Tensor queries_row_splits_ =
            TorchToOpen3DTensor(queries_row_splits);
    open3d::core::Tensor neighbors_index_, neighbors_distance_;

    // Installs PyTorch's current XPU queue as the ambient queue for
    // points_'s device; o3dnns::KnnSearchSYCL (and everything it calls, via
    // core::sy::GetQueue) will run on this queue for the duration of this
    // scope.
    sycl::queue& torch_queue = c10::xpu::getCurrentXPUStream().queue();
    open3d::core::sy::SYCLScopedQueue scoped_queue(points_.GetDevice(),
                                                   torch_queue);

    // o3dnns::KnnSearchSYCL (like o3dnns::KnnSearchCUDA) requires
    // neighbors_row_splits to be pre-allocated by the caller (it only fills
    // it in), matching the pattern used by KnnIndex::SearchKnn. Must be
    // allocated after scoped_queue above installs PyTorch's queue as
    // ambient: SYCL USM allocations are bound to the context of the queue
    // that made them, so allocating this before scoped_queue would bind it
    // to Open3D's own default context instead of PyTorch's, and the
    // KnnSearchSYCL call below -- which runs on PyTorch's queue/context --
    // would then read/write it across a context boundary (crashes on real
    // hardware).
    open3d::core::Tensor neighbors_row_splits_ = open3d::core::Tensor::Empty(
            {queries.size(0) + 1}, open3d::core::Int64, points_.GetDevice());

    o3dnns::KnnSearchSYCL<T, TIndex>(
            points_, points_row_splits_, queries_, queries_row_splits_, int(k),
            neighbors_index_, neighbors_row_splits_, neighbors_distance_,
            o3dnns::kSYCLKnnDefaultTileBytes);

    neighbors_index = Open3DToTorchTensor(neighbors_index_);
    neighbors_row_splits = Open3DToTorchTensor(neighbors_row_splits_);
    neighbors_distance = Open3DToTorchTensor(neighbors_distance_);
}

void ConvertToGlobalIndices(torch::Tensor& neighbors_index,
                            const torch::Tensor& points_row_splits,
                            const torch::Tensor& queries_row_splits,
                            int64_t k) {
    int64_t neighbors_offset = 0;
    const int64_t batch_size = points_row_splits.size(0) - 1;
    for (int64_t i = 0; i < batch_size; ++i) {
        const int64_t points_begin = points_row_splits[i].item<int64_t>();
        const int64_t num_points =
                points_row_splits[i + 1].item<int64_t>() - points_begin;
        const int64_t num_queries = queries_row_splits[i + 1].item<int64_t>() -
                                    queries_row_splits[i].item<int64_t>();
        const int64_t num_neighbors = std::min(k, num_points) * num_queries;
        if (num_neighbors > 0) {
            neighbors_index
                    .slice(0, neighbors_offset,
                           neighbors_offset + num_neighbors)
                    .add_(points_begin);
        }
        neighbors_offset += num_neighbors;
    }
}

torch::Tensor RaggedToDenseSYCL(const torch::Tensor& values,
                                const torch::Tensor& row_splits,
                                const int64_t out_col_size,
                                const torch::Tensor& default_value) {
    auto out_shape = values.sizes().vec();
    out_shape.erase(out_shape.begin());
    out_shape.insert(out_shape.begin(), {row_splits.size(0) - 1, out_col_size});
    auto device = values.device();
    torch::Tensor out = torch::empty(
            out_shape, torch::dtype(ToTorchDtype<T>()).device(device));

    sycl::queue& queue = c10::xpu::getCurrentXPUStream().queue();

    open3d::ml::impl::RaggedToDenseSYCL(
            queue, values.data_ptr<T>(), row_splits.data_ptr<int64_t>(),
            row_splits.size(0), out_col_size, default_value.data_ptr<T>(),
            default_value.numel(), out.data_ptr<T>());

    return out;
}

torch::Tensor ReduceSubarraysSumSYCL(const torch::Tensor& values,
                                     const torch::Tensor& row_splits) {
    auto device = values.device();
    torch::Tensor sums =
            torch::empty({row_splits.size(0) - 1},
                         torch::dtype(ToTorchDtype<T>()).device(device));

    sycl::queue& queue = c10::xpu::getCurrentXPUStream().queue();

    open3d::ml::impl::ReduceSubarraysSumSYCL(
            queue, values.data_ptr<T>(), values.size(0),
            row_splits.data_ptr<int64_t>(), row_splits.size(0) - 1,
            sums.data_ptr<T>());

    return sums;
}

void VoxelizeSYCLDispatch(const torch::Tensor& points,
                          const torch::Tensor& row_splits,
                          const torch::Tensor& voxel_size,
                          const torch::Tensor& points_range_min,
                          const torch::Tensor& points_range_max,
                          const int64_t max_points_per_voxel,
                          const int64_t max_voxels,
                          torch::Tensor& voxel_coords,
                          torch::Tensor& voxel_point_indices,
                          torch::Tensor& voxel_point_row_splits,
                          torch::Tensor& voxel_batch_splits) {
    sycl::queue& queue = c10::xpu::getCurrentXPUStream().queue();

    VoxelizeOutputAllocator output_allocator(points.device().type(),
                                             points.device().index());

    switch (points.size(1)) {
#define CASE(NDIM)                                                        \
    case NDIM: {                                                          \
        VoxelizeSYCL<T, NDIM>(                                            \
                queue, points.size(0), points.data_ptr<T>(),              \
                row_splits.size(0) - 1, row_splits.data_ptr<int64_t>(),   \
                voxel_size.data_ptr<T>(), points_range_min.data_ptr<T>(), \
                points_range_max.data_ptr<T>(), max_points_per_voxel,     \
                max_voxels, output_allocator);                            \
    } break;
        CASE(1)
        CASE(2)
        CASE(3)
        CASE(4)
        CASE(5)
        CASE(6)
        CASE(7)
        CASE(8)
        default:
            break;  // will be handled by the generic torch function
#undef CASE
    }

    voxel_coords = output_allocator.VoxelCoords();
    voxel_point_indices = output_allocator.VoxelPointIndices();
    voxel_point_row_splits = output_allocator.VoxelPointRowSplits();
    voxel_batch_splits = output_allocator.VoxelBatchSplits();
}

void ball_query_launcher_cpu(int b,
                             int n,
                             int m,
                             float radius,
                             int nsample,
                             const float *new_xyz,
                             const float *xyz,
                             int *idx) {
    // new_xyz: (B, M, 3)
    // xyz: (B, N, 3)
    // output:
    //      idx: (B, M, nsample)
    //
    // Each (batch, query_pt) pair is independent — no data races.
    // Parallelize over flattened b * m (total query points).
    const float radius2 = radius * radius;
    const int total_queries = b * m;
    tbb::parallel_for(
            tbb::blocked_range<int>(0, total_queries),
            [&](const tbb::blocked_range<int> &r) {
                for (int flat = r.begin(); flat != r.end(); ++flat) {
                    const int batch = flat / m;
                    const int i = flat % m;

                    const float *new_xyz_bi = new_xyz + batch * m * 3 + i * 3;
                    const float *xyz_b = xyz + batch * n * 3;
                    int *idx_bi = idx + batch * m * nsample + i * nsample;

                    float new_x = new_xyz_bi[0];
                    float new_y = new_xyz_bi[1];
                    float new_z = new_xyz_bi[2];

                    int cnt = 0;
                    for (int k = 0; k < n; ++k) {
                        float x = xyz_b[k * 3 + 0];
                        float y = xyz_b[k * 3 + 1];
                        float z = xyz_b[k * 3 + 2];
                        float d2 = (new_x - x) * (new_x - x) +
                                   (new_y - y) * (new_y - y) +
                                   (new_z - z) * (new_z - z);
                        if (d2 < radius2) {
                            if (cnt == 0) {
                                std::fill(idx_bi, idx_bi + nsample, k);
                            }
                            idx_bi[cnt] = k;
                            ++cnt;
                            if (cnt >= nsample) break;
                        }
                    }
                }
            });
}

void ball_query_launcher_sycl(int b,
                              int n,
                              int m,
                              float radius,
                              int nsample,
                              const float *new_xyz,
                              const float *xyz,
                              int *idx) {
    sycl::queue &queue = c10::xpu::getCurrentXPUStream().queue();
    open3d::ml::contrib::BallQuerySYCL(queue, b, n, m, radius, nsample, new_xyz,
                                       xyz, idx);
}

void three_nn_launcher_cpu(int b,
                           int n,
                           int m,
                           const float *unknown,
                           const float *known,
                           float *dist2,
                           int *idx) {
    // unknown: (B, N, 3)
    // known: (B, M, 3)
    // output:
    //      dist2: (B, N, 3)
    //      idx: (B, N, 3)
    //
    // Each (batch, query_pt) pair is independent — no data races.
    // Parallelize over the flattened b * n space.
    const int total_queries = b * n;
    tbb::parallel_for(
            tbb::blocked_range<int>(0, total_queries),
            [&](const tbb::blocked_range<int> &r) {
                for (int flat = r.begin(); flat != r.end(); ++flat) {
                    const int batch = flat / n;
                    const int i = flat % n;

                    const float *unknown_b = unknown + batch * n * 3 + i * 3;
                    const float *known_b = known + batch * m * 3;
                    float *dist2_b = dist2 + batch * n * 3 + i * 3;
                    int *idx_b = idx + batch * n * 3 + i * 3;

                    float ux = unknown_b[0];
                    float uy = unknown_b[1];
                    float uz = unknown_b[2];

                    float best1 = std::numeric_limits<float>::max();
                    float best2 = std::numeric_limits<float>::max();
                    float best3 = std::numeric_limits<float>::max();
                    int besti1 = 0, besti2 = 0, besti3 = 0;

                    for (int k = 0; k < m; ++k) {
                        float x = known_b[k * 3 + 0];
                        float y = known_b[k * 3 + 1];
                        float z = known_b[k * 3 + 2];
                        float d = (ux - x) * (ux - x) + (uy - y) * (uy - y) +
                                  (uz - z) * (uz - z);
                        if (d < best1) {
                            best3 = best2;
                            besti3 = besti2;
                            best2 = best1;
                            besti2 = besti1;
                            best1 = d;
                            besti1 = k;
                        } else if (d < best2) {
                            best3 = best2;
                            besti3 = besti2;
                            best2 = d;
                            besti2 = k;
                        } else if (d < best3) {
                            best3 = d;
                            besti3 = k;
                        }
                    }
                    dist2_b[0] = best1;
                    dist2_b[1] = best2;
                    dist2_b[2] = best3;
                    idx_b[0] = besti1;
                    idx_b[1] = besti2;
                    idx_b[2] = besti3;
                }
            });
}

id three_interpolate_launcher_cpu(int b,
                                    int c,
                                    int m,
                                    int n,
                                    const float *points,
                                    const int *idx,
                                    const float *weight,
                                    float *out) {
    // points: (B, C, M)
    // idx: (B, N, 3)
    // weight: (B, N, 3)
    // output:
    //      out: (B, C, N)
    //
    // Each output element out[b, c, n] is independent (read-only access to
    // points/idx/weight). Parallelize over the flattened b * c * n space.
    const int total = b * c * n;
    tbb::parallel_for(
            tbb::blocked_range<int>(0, total),
            [&](const tbb::blocked_range<int> &r) {
                for (int flat = r.begin(); flat != r.end(); ++flat) {
                    const int batch = flat / (c * n);
                    const int c_idx = (flat / n) % c;
                    const int i = flat % n;

                    const float *points_bc = points + batch * c * m + c_idx * m;
                    const int *idx_i = idx + batch * n * 3 + i * 3;
                    const float *weight_i = weight + batch * n * 3 + i * 3;
                    float *out_bci = out + batch * c * n + c_idx * n + i;

                    *out_bci = weight_i[0] * points_bc[idx_i[0]] +
                               weight_i[1] * points_bc[idx_i[1]] +
                               weight_i[2] * points_bc[idx_i[2]];
                }
            });
}

id three_interpolate_grad_launcher_cpu(int b,
                                         int c,
                                         int n,
                                         int m,
                                         const float *grad_out,
                                         const int *idx,
                                         const float *weight,
                                         float *grad_points) {
    // grad_out: (B, C, N)
    // weight: (B, N, 3)
    // output:
    //      grad_points: (B, C, M)
    //
    // IMPORTANT: This is a scatter-add — multiple n-queries within the same
    // (batch, c) may write to the same grad_points[batch, c, idx_i[j]] slot.
    // To avoid data races without atomic operations, we partition by (batch,
    // c) so each TBB task owns an exclusive slice of grad_points. The inner
    // loop over n is serial within each task.
    std::fill(grad_points, grad_points + b * c * m, 0.0f);

    const int total_slices = b * c;
    tbb::parallel_for(tbb::blocked_range<int>(0, total_slices),
                      [&](const tbb::blocked_range<int> &r) {
                          for (int flat = r.begin(); flat != r.end(); ++flat) {
                              const int batch = flat / c;
                              const int c_idx = flat % c;

                              const float *grad_out_bc =
                                      grad_out + batch * c * n + c_idx * n;
                              const int *idx_b = idx + batch * n * 3;
                              const float *weight_b = weight + batch * n * 3;
                              float *grad_points_bc =
                                      grad_points + batch * c * m + c_idx * m;

                              for (int i = 0; i < n; ++i) {
                                  const int *idx_i = idx_b + i * 3;
                                  const float *weight_i = weight_b + i * 3;
                                  float g = grad_out_bc[i];
                                  grad_points_bc[idx_i[0]] += weight_i[0] * g;
                                  grad_points_bc[idx_i[1]] += weight_i[1] * g;
                                  grad_points_bc[idx_i[2]] += weight_i[2] * g;
                              }
                          }
                      });
}

