void furthest_point_sampling_launcher_cpu(
        int b, int n, int m, const float *dataset, float *temp, int *idxs) {
    // dataset: (B, N, 3)
    // temp: (B, N)
    // output:
    //      idxs: (B, M)
    //
    // Each batch is independent — parallelize over batches. Within each
    // batch the sampling is sequential (each iteration depends on the
    // previous), but the inner candidate-distance loop is parallelized.

    if (m <= 0) return;

    tbb::parallel_for(
            tbb::blocked_range<int>(0, b),
            [&](const tbb::blocked_range<int> &r) {
                for (int batch = r.begin(); batch != r.end(); ++batch) {
                    const float *dataset_b = dataset + batch * n * 3;
                    float *temp_b = temp + batch * n;
                    int *idxs_b = idxs + batch * m;

                    // Initialize distances to infinity.
                    std::fill(temp_b, temp_b + n,
                              std::numeric_limits<float>::max());

                    int old = 0;
                    idxs_b[0] = old;

                    for (int j = 1; j < m; ++j) {
                        float x1 = dataset_b[old * 3 + 0];
                        float y1 = dataset_b[old * 3 + 1];
                        float z1 = dataset_b[old * 3 + 2];

                        // Thread-local best for the reduction.
                        // Use enumerable_thread_specific to avoid false
                        // sharing and get per-thread storage with automatic
                        // combining.
                        typedef std::pair<float, int> BestPair;
                        tbb::enumerable_thread_specific<BestPair> tls_best(
                                BestPair(-1.0f, 0));

                        tbb::parallel_for(
                                tbb::blocked_range<int>(0, n),
                                [&](const tbb::blocked_range<int> &kr) {
                                    BestPair &local_best = tls_best.local();
                                    for (int k = kr.begin(); k != kr.end();
                                         ++k) {
                                        float x2 = dataset_b[k * 3 + 0];
                                        float y2 = dataset_b[k * 3 + 1];
                                        float z2 = dataset_b[k * 3 + 2];

                                        float d = (x2 - x1) * (x2 - x1) +
                                                  (y2 - y1) * (y2 - y1) +
                                                  (z2 - z1) * (z2 - z1);
                                        float d2 = std::min(d, temp_b[k]);
                                        temp_b[k] = d2;
                                        if (d2 > local_best.first) {
                                            local_best.first = d2;
                                            local_best.second = k;
                                        }
                                    }
                                });

                        // Serial reduction over thread-local bests.
                        BestPair global_best(-1.0f, 0);
                        for (auto &lb : tls_best) {
                            if (lb.first > global_best.first) {
                                global_best = lb;
                            }
                        }
                        old = global_best.second;
                        idxs_b[j] = old;
                    }
                }
            });
}

cl::event FurthestPointSamplingSYCL(sycl::queue& queue,
                                      int b,
                                      int n,
                                      int m,
                                      const float* const dataset,
                                      float* const temp,
                                      int* const idxs,
                                      size_t work_group_size = 256) {
    if (b <= 0 || m <= 0) return sycl::event();

    const size_t max_wg =
            queue.get_device()
                    .get_info<sycl::info::device::max_work_group_size>();
    size_t wg = std::min(work_group_size, max_wg);
    // Round down to a power of two so the tree reduction is exact.
    size_t pow2 = 1;
    while (pow2 * 2 <= wg) pow2 *= 2;
    wg = std::max<size_t>(pow2, 1);

    const sycl::range<1> global(static_cast<size_t>(b) * wg);
    const sycl::range<1> local(wg);

    return queue.submit([&](sycl::handler& cgh) {
        sycl::local_accessor<float, 1> dists(wg, cgh);
        sycl::local_accessor<int, 1> dists_i(wg, cgh);

        cgh.parallel_for(
                sycl::nd_range<1>(global, local), [=](sycl::nd_item<1> item) {
                    const int batch_index = static_cast<int>(item.get_group(0));
                    const int tid = static_cast<int>(item.get_local_id(0));
                    const int stride =
                            static_cast<int>(item.get_local_range(0));

                    const float* const data = dataset + batch_index * n * 3;
                    float* const tmp = temp + batch_index * n;
                    int* const out_idx = idxs + batch_index * m;

                    int old = 0;
                    if (tid == 0) out_idx[0] = old;
                    item.barrier(sycl::access::fence_space::local_space);

                    for (int j = 1; j < m; ++j) {
                        int besti = 0;
                        float best = -1;
                        const float x1 = data[old * 3 + 0];
                        const float y1 = data[old * 3 + 1];
                        const float z1 = data[old * 3 + 2];
                        for (int k = tid; k < n; k += stride) {
                            const float x2 = data[k * 3 + 0];
                            const float y2 = data[k * 3 + 1];
                            const float z2 = data[k * 3 + 2];
                            const float d = (x2 - x1) * (x2 - x1) +
                                            (y2 - y1) * (y2 - y1) +
                                            (z2 - z1) * (z2 - z1);
                            const float d2 = sycl::min(d, tmp[k]);
                            tmp[k] = d2;
                            besti = d2 > best ? k : besti;
                            best = d2 > best ? d2 : best;
                        }
                        dists[tid] = best;
                        dists_i[tid] = besti;
                        item.barrier(sycl::access::fence_space::local_space);

                        // Argmax tree reduction over [dists, dists_i] pairs.
                        for (size_t s = wg / 2; s > 0; s >>= 1) {
                            if (static_cast<size_t>(tid) < s) {
                                const float v1 = dists[tid];
                                const float v2 = dists[tid + s];
                                const int i1 = dists_i[tid];
                                const int i2 = dists_i[tid + s];
                                dists[tid] = sycl::max(v1, v2);
                                dists_i[tid] = v2 > v1 ? i2 : i1;
                            }
                            item.barrier(
                                    sycl::access::fence_space::local_space);
                        }

                        old = dists_i[0];
                        if (tid == 0) out_idx[j] = old;
                        // Extra barrier vs. the CUDA original: SYCL
                        // work-item scheduling does not guarantee
                        // CUDA-warp-like lock-step progress, so make sure
                        // every work-item has consumed dists_i[0] before the
                        // next iteration overwrites it.
                        item.barrier(sycl::access::fence_space::local_space);
                    }
                });
    });
}

