            {0.155918367347, 0.155918367347, 0.844081632653},
            {0.844081632653, 0.155918367347, 0.844081632653},
            {0.155918367347, 0.844081632653, 0.844081632653},
            {0.844081632653, 0.844081632653, 0.844081632653},
