void SYCLContext::Clear() {
    if (!g_sycl_context || !g_sycl_context->impl_) return;
    for (auto& pair : g_sycl_context->impl_->devices) {
        try {
            pair.second.queue.wait_and_throw();
        } catch (...) {
        }
    }
    // Destroy queues while the process is still in a normal runtime state
    // (e.g. from Python atexit). If done from static destructors / C++ atexit,
    // OpenCL CPU aborts with glibc heap corruption.
    g_sycl_context->impl_->devices.clear();
}

std::vector<Device> SYCLContext::GetAvailableSYCLDevices() {
    std::vector<Device> device_vec;
    for (const auto& pair : impl_->devices) {
        device_vec.push_back(pair.first);
    }
    return device_vec;
}

SYCLContext::SYCLContext() : impl_(std::make_unique<Impl>()) {
    g_sycl_context = this;
        const sycl::device& sycl_device = sycl::device(sycl::gpu_selector_v);
        impl_->devices.emplace(open3d_device, MakeDeviceEntry(sycl_device));
    }

std::shared_ptr<DeviceHashBackend> CreateSYCLHashBackend(
        int64_t init_capacity,
        const Dtype& key_dtype,
        const SizeVector& key_element_shape,
        const std::vector<Dtype>& value_dtypes,
        const std::vector<SizeVector>& value_element_shapes,
        const Device& device,
        const HashBackendType& backend) {
    if (backend != HashBackendType::Default) {
        utility::LogError("Unsupported backend for SYCL hashmap.");
    }

    int64_t dim = key_element_shape.NumElements();
    int64_t key_dsize = dim * key_dtype.ByteSize();

    std::vector<int64_t> value_dsizes;
    for (size_t i = 0; i < value_dtypes.size(); ++i) {
        int64_t dsize_value = value_element_shapes[i].NumElements() *
                              value_dtypes[i].ByteSize();
        value_dsizes.push_back(dsize_value);
    }

    std::shared_ptr<DeviceHashBackend> device_hashmap_ptr;
    DISPATCH_DTYPE_AND_DIM_TO_TEMPLATE(key_dtype, dim, [&] {
        device_hashmap_ptr =
                std::make_shared<SYCLHashBackend<key_t, hash_t, eq_t>>(
                        init_capacity, key_dsize, value_dsizes, device);
    });
    return device_hashmap_ptr;
}

SYCLResetHeap(Tensor &heap) {
    uint32_t *heap_ptr = heap.GetDataPtr<uint32_t>();
    const int64_t capacity = heap.GetLength();
    sycl::queue queue =
            sy::SYCLContext::GetInstance().GetDefaultQueue(heap.GetDevice());
    queue.parallel_for(capacity, [=](int64_t i) {
             heap_ptr[i] = static_cast<uint32_t>(i);
         }).wait_and_throw();
}

}

inline void BinaryEWBoolApplyIndexer(const Indexer& indexer,
                                     int64_t i,
                                     BinaryEWOpCode op_code) {
    const src_t* lhs = indexer.GetInputPtr<src_t>(0, i);
    const src_t* rhs = indexer.GetInputPtr<src_t>(1, i);
    dst_t* dst = indexer.GetOutputPtr<dst_t>(i);
    *dst = static_cast<dst_t>(BinaryEWBooleanResult(*lhs, *rhs, op_code));
}

inline void BinaryEWArithmeticApplyIndexer(const Indexer& indexer,
                                           int64_t i,
                                           BinaryEWOpCode op_code) {
    const scalar_t* lhs = indexer.GetInputPtr<scalar_t>(0, i);
    const scalar_t* rhs = indexer.GetInputPtr<scalar_t>(1, i);
    scalar_t* dst = indexer.GetOutputPtr<scalar_t>(i);
    *dst = BinaryEWArithmetic(*lhs, *rhs, op_code);
}

inline void BinaryEWMaxMinApplyIndexer(const Indexer& indexer,
                                       int64_t i,
                                       BinaryEWOpCode op_code) {
    const scalar_t* lhs = indexer.GetInputPtr<scalar_t>(0, i);
    const scalar_t* rhs = indexer.GetInputPtr<scalar_t>(1, i);
    scalar_t* dst = indexer.GetOutputPtr<scalar_t>(i);
    *dst = BinaryEWMaxMin(*lhs, *rhs, op_code);
}

inline const scalar_t* GetInputPtrDevice(const Indexer& indexer,
                                         int64_t output_idx,
                                         int64_t reduction_element_idx) {
    int64_t ndims = indexer.NumDims();
    const int64_t* primary_shape = indexer.GetPrimaryShape();

    // 1. Compute coordinates for non-reduction dimensions from output_idx
    int64_t output_shape[MAX_DIMS] = {0};
    int64_t output_default_strides[MAX_DIMS] = {0};
    int64_t input_coords[MAX_DIMS] = {0};

    for (int64_t i = 0; i < MAX_DIMS; ++i) {
        if (i < ndims) {
            if (indexer.IsReductionDim(i)) {
                output_shape[i] = 1;
            } else {
                output_shape[i] = primary_shape[i];
            }
        }
    }
    int64_t stride = 1;
    for (int64_t i = MAX_DIMS - 1; i >= 0; --i) {
        if (i < ndims) {
            output_default_strides[i] = stride;
            stride = output_shape[i] > 1 ? stride * output_shape[i] : stride;
        }
    }
    int64_t temp_output_idx = output_idx;
    for (int64_t i = 0; i < MAX_DIMS; ++i) {
        if (i < ndims) {
            if (!indexer.IsReductionDim(i)) {
                input_coords[i] = temp_output_idx / output_default_strides[i];
                temp_output_idx = temp_output_idx % output_default_strides[i];
            }
        }
    }

    // 2. Compute coordinates for reduction dimensions from
    // reduction_element_idx
    int64_t reduction_shape[MAX_DIMS] = {0};
    int64_t reduction_default_strides[MAX_DIMS] = {0};
    for (int64_t i = 0; i < MAX_DIMS; ++i) {
        if (i < ndims) {
            if (indexer.IsReductionDim(i)) {
                reduction_shape[i] = primary_shape[i];
            } else {
                reduction_shape[i] = 1;
            }
        }
    }
    stride = 1;
    for (int64_t i = MAX_DIMS - 1; i >= 0; --i) {
        if (i < ndims) {
            reduction_default_strides[i] = stride;
            stride = reduction_shape[i] > 1 ? stride * reduction_shape[i]
                                            : stride;
        }
    }
    int64_t temp_reduction_idx = reduction_element_idx;
    for (int64_t i = 0; i < MAX_DIMS; ++i) {
        if (i < ndims) {
            if (indexer.IsReductionDim(i)) {
                input_coords[i] =
                        temp_reduction_idx / reduction_default_strides[i];
                temp_reduction_idx =
                        temp_reduction_idx % reduction_default_strides[i];
            }
        }
    }

    // 3. Reconstruct workload_idx (linear index in input shape)
    int64_t workload_idx = 0;
    const int64_t* primary_strides = indexer.GetPrimaryStrides();
    for (int64_t i = 0; i < MAX_DIMS; ++i) {
        if (i < ndims) {
            workload_idx += input_coords[i] * primary_strides[i];
        }
    }

    return indexer.GetInputPtr<scalar_t>(0, workload_idx);
}

inline void UnaryEWApplyIndexer(const Indexer& indexer,
                                int64_t i,
                                UnaryEWOpCode op_code) {
    const scalar_t* src = indexer.GetInputPtr<scalar_t>(0, i);
    scalar_t* dst = indexer.GetOutputPtr<scalar_t>(i);
    *dst = UnaryEWTransform(op_code, *src);
}

inline void UnaryEWFloatCheckApplyIndexer(const Indexer& indexer,
                                          int64_t i,
                                          UnaryEWOpCode op_code) {
    const scalar_t* src = indexer.GetInputPtr<scalar_t>(0, i);
    bool* dst = indexer.GetOutputPtr<bool>(i);
    *dst = UnaryEWFloatCheck(op_code, *src);
}

inline void UnaryEWLogicalNotApplyIndexer(const Indexer& indexer, int64_t i) {
    const src_t* src = indexer.GetInputPtr<src_t>(0, i);
    dst_t* dst = indexer.GetOutputPtr<dst_t>(i);
    *dst = UnaryEWLogicalNot<src_t, dst_t>(*src);
}

FixedRadiusIndex::FixedRadiusIndex(const Tensor &dataset_points,
                                   double radius,
                                   const Dtype &index_dtype,
                                   int64_t tile_bytes)
    : tile_bytes_(tile_bytes) {
    AssertTensorDtypes(dataset_points, {Float32, Float64});
    assert(index_dtype == Int32 || index_dtype == Int64);
    SetTensorData(dataset_points, radius, index_dtype);
}

KnnIndex::KnnIndex(const Tensor& dataset_points,
                   const Dtype& index_dtype,
                   int64_t tile_bytes)
    : tile_bytes_(tile_bytes) {
    SetTensorData(dataset_points, index_dtype);
}

// it always lies in the data range and can never be NaN/uninitialized) and
    // needs no reduction. A centroid (Mean) would shrink norms slightly more,
    // but is not worth a reduction kernel here.
    const Tensor center = points.Slice(0, 0, 1);  // (1, D)
    points = points.Sub(center);
    queries = queries.Sub(center);
}

template <class T>
T FixedRadiusThreshold(Metric metric, T radius) {
    if (metric == L2) {
        return radius * radius;
    }
    return radius;
}

}  // namespace

// Batched KN

ble_splits,
                           const Tensor& hash_table_index,
                           const Tensor& hash_table_cell_splits,
                           const Metric metric,
                           const bool ignore_query_point,
                           const bool return_distances,
                           const bool sort,
                           Tensor& neighbors_index,
                           Tensor& neighbors_row_splits,
                           Tensor& neighbors_distance,
                           int64_t /*tile_bytes*/) {
    const Device device = points.GetDevice();
    const int64_t num_queries = queries.GetShape(0);
    const T radius_t = static_cast<T>(radius);
    const T threshold = FixedRadiusThreshold<T>(metric, radius_t);
    const T voxel_size = T(2) * radius_t;
    const T inv_voxel_size = T(1) / voxel_size;
    sycl::queue queue = sy::SYCLContext::GetInstance().GetDefaultQueue(device);

    const T* points_ptr = points.GetDataPtr<T>();
    const T* queries_ptr = queries.GetDataPtr<T>();
    const uint32_t* hash_index_ptr = hash_table_index.GetDataPtr<uint32_t>();

    Tensor counts = Tensor::Empty({num_queries}, UInt32, device);
    uint32_t* counts_ptr = counts.GetDataPtr<uint32_t>();

    const int num_batches = static_cast<int>(points_row_splits.GetShape(0)) - 1;

    // ── Pass 1: count ────────────────────────────────────────────────────────
    for (int batch_idx = 0; batch_idx < num_batches; ++batch_idx) {
        const int64_t query_begin =
                queries_row_splits[batch_idx].Item<int64_t>();
        const int64_t query_end =
                queries_row_splits[batch_idx + 1].Item<int64_t>();
        const uint32_t first_cell_idx =
                hash_table_splits[batch_idx].Item<uint32_t>();
        const uint32_t hash_table_size =
                hash_table_splits[batch_idx + 1].Item<uint32_t>() -
                first_cell_idx;
        const uint32_t* cell_splits_i =
                hash_table_cell_splits.GetDataPtr<uint32_t>() + first_cell_idx;

        CountNeighborsSYCL<T>(
                queue, counts_ptr + query_begin, hash_index_ptr, cell_splits_i,
                hash_table_size, queries_ptr + 3 * query_begin,
                query_end - query_begin, points_ptr, inv_voxel_size, radius_t,
                metric, ignore_query_point, threshold);
    }
    queue.wait_and_throw();

    // Build row_splits from counts (device inclusive scan; no host fallback).
    neighbors_row_splits = Tensor::Zeros({num_queries + 1}, Int64, device);
    int64_t* row_splits_ptr = neighbors_row_splits.GetDataPtr<int64_t>();
    {
        auto policy = oneapi::dpl::execution::make_device_policy(queue);
        // counts_ptr is uint32_t; scan directly into the int64_t row-splits
        // tail (offset by 1) so element 0 stays the required leading zero.
        // The explicit int64_t init forces 64-bit accumulation (avoids
        // overflow for very large neighbor counts).
        std::inclusive_scan(policy, counts_ptr, counts_ptr + num_queries,
                            row_splits_ptr + 1, std::plus<int64_t>(),
                            int64_t(0));
        queue.wait_and_throw();
    }
    int64_t total_neighbors = 0;
    if (num_queries > 0) {
        queue.memcpy(&total_neighbors, row_splits_ptr + num_queries,
                     sizeof(int64_t))
                .wait_and_throw();
    }

    NeighborSearchAllocator<T, TIndex> output_allocator(device);
    TIndex* neighbors_index_ptr;
    T* neighbors_distance_ptr;
    output_allocator.AllocIndices(&neighbors_index_ptr, total_neighbors);
    if (return_distances || sort) {
        output_allocator.AllocDistances(&neighbors_distance_ptr,
                                        total_neighbors);
    } else {
        output_allocator.AllocDistances(&neighbors_distance_ptr, 0);
    }

    // ── Pass 2: gather ───────────────────────────────────────────────────────
    for (int batch_idx = 0; batch_idx < num_batches; ++batch_idx) {
        const int64_t query_begin =
                queries_row_splits[batch_idx].Item<int64_t>();
        const int64_t query_end =
                queries_row_splits[batch_idx + 1].Item<int64_t>();
        const uint32_t first_cell_idx =
                hash_table_splits[batch_idx].Item<uint32_t>();
        const uint32_t hash_table_size =
                hash_table_splits[batch_idx + 1].Item<uint32_t>() -
                first_cell_idx;
        const uint32_t* cell_splits_i =
                hash_table_cell_splits.GetDataPtr<uint32_t>() + first_cell_idx;

        WriteNeighborsSYCL<T, TIndex>(
                queue, neighbors_index_ptr, neighbors_distance_ptr,
                row_splits_ptr + query_begin, hash_index_ptr, cell_splits_i,
                hash_table_size, queries_ptr + 3 * query_begin,
                query_end - query_begin, points_ptr, inv_voxel_size, radius_t,
                metric, ignore_query_point, threshold,
                return_distances || sort);
    }
    queue.wait_and_throw();

    if (sort && total_neighbors > 0) {
        SortNeighborsByDistanceSYCL<T, TIndex>(
                device, neighbors_index_ptr, neighbors_distance_ptr,
                row_splits_ptr, num_queries, total_neighbors);
    }

    neighbors_index = output_allocator.NeighborsIndex();
    neighbors_distance = output_allocator.NeighborsDistance();
    if (!return_distances)
        neighbors_distance = Tensor({0}, Dtype::FromType<T>(), device);
}

// Hybrid search: uniform-grid (cell-list) algorithm, ported from
// FixedRadiusSearchImpl.cuh (CUDA). A single pass over the grid's 8
// corner-adjacent hash bins per query counts all in-radius neighbors while
// keeping a running top-max_knn (see WriteNeighborsHybridSYCL in
// FixedRadiusSearchSYCLImpl.h, including its final per-query bubble sort).
template <class T, class TIndex>
void HybridSearchSYCL(const Tensor& points,
                      const Tensor& queries,
                      double radius,
                      int

Tensor& neighbors_count,
                      Tensor& neighbors_distance,
                      int64_t /*tile_bytes*/) {
    if (metric != Metric::L2) {
        utility::LogError("SYCL hybrid search only supports L2 metric.");
    }
    const Device device = points.GetDevice();
    const int64_t num_queries = queries.GetShape(0);
    const T radius_t = static_cast<T>(radius);
    const T threshold = radius_t * radius_t;  // L2: compare squared distances.
    const T voxel_size = T(2) * radius_t;
    const T inv_voxel_size = T(1) / voxel_size;
    sycl::queue queue = sy::SYCLContext::GetInstance().GetDefaultQueue(device);

    const T* points_ptr = points.GetDataPtr<T>();
    const T* queries_ptr = queries.GetDataPtr<T>();
    const uint32_t* hash_index_ptr = hash_table_index.GetDataPtr<uint32_t>();

    NeighborSearchAllocator<T, TIndex> output_allocator(device);
    TIndex* neighbors_index_ptr;
    T* neighbors_distance_ptr;
    TIndex* neighbors_count_ptr;
    output_allocator.AllocIndices(&neighbors_index_ptr, num_queries * max_knn,
                                  TIndex(-1));
    output_allocator.AllocDistances(&neighbors_distance_ptr,
                                    num_queries * max_knn, T(0));
    output_allocator.AllocCounts(&neighbors_count_ptr, num_queries, TIndex(0));

    const int num_batches = static_cast<int>(points_row_splits.GetShape(0)) - 1;
    for (int batch_idx = 0; batch_idx < num_batches; ++batch_idx) {
        const int64_t query_begin =
                queries_row_splits[batch_idx].Item<int64_t>();
        const int64_t query_end =
                queries_row_splits[batch_idx + 1].Item<int64_t>();
        const uint32_t first_cell_idx =
                hash_table_splits[batch_idx].Item<uint32_t>();
        const uint32_t hash_table_size =
                hash_table_splits[batch_idx + 1].Item<uint32_t>() -
                first_cell_idx;
        const uint32_t* cell_splits_i =
                hash_table_cell_splits.GetDataPtr<uint32_t>() + first_cell_idx;

        WriteNeighborsHybridSYCL<T, TIndex>(
                queue, neighbors_index_ptr + max_knn * query_begin,
                neighbors_distance_ptr + max_knn * query_begin,
                neighbors_count_ptr + query_begin, hash_index_ptr,
                cell_splits_i, hash_table_size, queries_ptr + 3 * query_begin,
                query_end - query_begin, points_ptr, inv_voxel_size, radius_t,
                threshold, max_knn);
    }
    queue.wait_and_throw();

    neighbors_index = output_allocator.NeighborsIndex();
    neighbors_distance = output_allocator.NeighborsDistance();
    neighbors_count = output_allocator.NeighborsCount();
}

#define INSTANTIATE(T, TIndex)                                                 \
    template void KnnSearchSYCL<T, TIndex>(                                    \
            const Tensor& points, const Tensor& points_row_splits,             \
            const Tensor& queries, const Tensor& queries_row_splits, int knn,  \
            Tensor& neighbors_index, Tensor& neighbors_row_splits,             \
            Tensor& neighbors_distance, int64_t tile_bytes,                    \
            int64_t max_tile_queries, int64_t tile_p

void ProjectSYCL(
        core::Tensor& depth,
        std::optional<std::reference_wrapper<core::Tensor>> image_colors,
        const core::Tensor& points,
        std::optional<std::reference_wrapper<const core::Tensor>> colors,
        const core::Tensor& intrinsics,
        const core::Tensor& extrinsics,
        float depth_scale,
        float depth_max) {
    const bool has_colors = image_colors.has_value();

    int64_t n = points.GetLength();

    const float* points_ptr = points.GetDataPtr<float>();
    const float* point_colors_ptr =
            has_colors ? colors.value().get().GetDataPtr<float>() : nullptr;

    core::Tensor depth_atomic = depth.Contiguous();
    TransformIndexer transform_indexer(intrinsics, extrinsics, 1.0f);
    NDArrayIndexer depth_indexer(depth_atomic, 2);

    core::ParallelFor(depth.GetDevice(), n, [=] OPEN3D_DEVICE(int64_t idx) {
        float x = points_ptr[3 * idx + 0];
        float y = points_ptr[3 * idx + 1];
        float z = points_ptr[3 * idx + 2];

        float xc, yc, zc, u, v;
        transform_indexer.RigidTransform(x, y, z, &xc, &yc, &zc);
        transform_indexer.Project(xc, yc, zc, &u, &v);
        u = round(u);
        v = round(v);
        if (!depth_indexer.InBoundary(u, v) || zc <= 0 || zc > depth_max) {
            return;
        }

        float* depth_ptr = depth_indexer.GetDataPtr<float>(
                static_cast<int64_t>(u), static_cast<int64_t>(v));
        float d = zc * depth_scale;
        auto depth_atomic_ref =
                sycl::atomic_ref<float, sycl::memory_order::relaxed,
                                 sycl::memory_scope::device,
                                 sycl::access::address_space::global_space>(
                        *depth_ptr);
        float old = depth_atomic_ref.load(sycl::memory_order::relaxed);
        while (old == 0.0f || old > d) {
            if (depth_atomic_ref.compare_exchange_strong(
                        old, d, sycl::memory_order::relaxed,
                        sycl::memory_order::relaxed)) {
                break;
            }
        }
    });

    if (!has_colors) {
        depth = depth_atomic;
        return;
    }

    NDArrayIndexer color_indexer(image_colors.value().get(), 2);
    float precision_bound = depth_scale * 1e-4;
    core::Tensor depth_snapshot = depth_atomic;
    NDArrayIndexer depth_snapshot_indexer(depth_snapshot, 2);

    core::ParallelFor(depth.GetDevice(), n, [=] OPEN3D_DEVICE(int64_t idx) {
        float x = points_ptr[3 * idx + 0];
        float y = points_ptr[3 * idx + 1];
        float z = points_ptr[3 * idx + 2];

        float xc, yc, zc, u, v;
        transform_indexer.RigidTransform(x, y, z, &xc, &yc, &zc);
        transform_indexer.Project(xc, yc, zc, &u, &v);
        if (!depth_indexer.InBoundary(u, v) || zc <= 0 || zc > depth_max) {
            return;
        }

        float dmap = *depth_snapshot_indexer.GetDataPtr<float>(
                static_cast<int64_t>(u), static_cast<int64_t>(v));
        float d = zc * depth_scale;
        if (d < dmap + precision_bound) {
            float* color_ptr = color_indexer.GetDataPtr<float>(
                    static_cast<int64_t>(u), static_cast<int64_t>(v));
            color_ptr[0] = point_colors_ptr[3 * idx + 0];
            color_ptr[1] = point_colors_ptr[3 * idx + 1];
            color_ptr[2] = point_colors_ptr[3 * idx + 2];
        }
    });

    depth = depth_atomic;
}

void ComputeVertexNormalsSYCL(const core::Tensor& triangles,
                              const core::Tensor& triangle_normals,
                              core::Tensor& vertex_normals) {
    const core::Dtype dtype = vertex_normals.GetDtype();
    const int64_t n = triangles.GetLength();
    const core::Tensor triangles_d = triangles.To(core::Int64);

    DISPATCH_FLOAT_DTYPE_TO_TEMPLATE(dtype, [&]() {
        const int64_t* triangle_ptr = triangles_d.GetDataPtr<int64_t>();
        const scalar_t* triangle_normals_ptr =
                triangle_normals.GetDataPtr<scalar_t>();
        scalar_t* vertex_normals_ptr = vertex_normals.GetDataPtr<scalar_t>();
        core::ParallelFor(vertex_normals.GetDevice(), n,
                          [=] OPEN3D_DEVICE(int64_t workload_idx) {
                              int64_t idx = 3 * workload_idx;
                              const int64_t vertex_ids[3] = {
                                      triangle_ptr[idx], triangle_ptr[idx + 1],
                                      triangle_ptr[idx + 2]};
                              const scalar_t n1 = triangle_normals_ptr[idx];
                              const scalar_t n2 = triangle_normals_ptr[idx + 1];
                              const scalar_t n3 = triangle_normals_ptr[idx + 2];

                              for (int vi = 0; vi < 3; ++vi) {
                                  const int64_t base = 3 * vertex_ids[vi];
                                  OPEN3D_ATOMIC_ADD_RELAXED(
                                          &vertex_normals_ptr[base], n1);
                                  OPEN3D_ATOMIC_ADD_RELAXED(
                                          &vertex_normals_ptr[base + 1], n2);
                                  OPEN3D_ATOMIC_ADD_RELAXED(
                                          &vertex_normals_ptr[base + 2], n3);
                              }
                          });
    });
}

void PointCloudTouchSYCL(std::shared_ptr<core::HashMap> &hashmap,
                         const core::Tensor &points,
                         core::Tensor &voxel_block_coords,
                         index_t voxel_grid_resolution,
                         float voxel_size,
                         float sdf_trunc) {
    index_t resolution = voxel_grid_resolution;
    float block_size = voxel_size * resolution;

    index_t n = points.GetLength();
    const float *pcd_ptr = static_cast<const float *>(points.GetDataPtr());

    core::Device device = points.GetDevice();
    core::Tensor block_coordi({8 * n, 3}, core::Int32, device);
    index_t *block_coordi_ptr =
            static_cast<index_t *>(block_coordi.GetDataPtr());
    core::Tensor count(std::vector<index_t>{0}, {}, core::Int32, device);
    index_t *count_ptr = static_cast<index_t *>(count.GetDataPtr());

    core::ParallelFor(
            hashmap->GetDevice(), n, [=] OPEN3D_DEVICE(index_t workload_idx) {
                float x = pcd_ptr[3 * workload_idx + 0];
                float y = pcd_ptr[3 * workload_idx + 1];
                float z = pcd_ptr[3 * workload_idx + 2];

                index_t xb_lo = static_cast<index_t>(
                        floorf((x - sdf_trunc) / block_size));
                index_t xb_hi = static_cast<index_t>(
                        floorf((x + sdf_trunc) / block_size));
                index_t yb_lo = static_cast<index_t>(
                        floorf((y - sdf_trunc) / block_size));
                index_t yb_hi = static_cast<index_t>(
                        floorf((y + sdf_trunc) / block_size));
                index_t zb_lo = static_cast<index_t>(
                        floorf((z - sdf_trunc) / block_size));
                index_t zb_hi = static_cast<index_t>(
                        floorf((z + sdf_trunc) / block_size));

                index_t xb_diff = xb_hi - xb_lo + 1;
                index_t yb_diff = yb_hi - yb_lo + 1;
                index_t zb_diff = zb_hi - zb_lo + 1;
                if (xb_diff <= 0 || yb_diff <= 0 || zb_diff <= 0) return;
                index_t local_count = xb_diff * yb_diff * zb_diff;

                auto count_atomic_ref = sycl::atomic_ref<
                        index_t, sycl::memory_order::acq_rel,
                        sycl::memory_scope::device,
                        sycl::access::address_space::global_space>(*count_ptr);
                index_t start_idx = count_atomic_ref.fetch_add(local_count);

                index_t idx = start_idx;
                for (index_t xb = xb_lo; xb <= xb_hi; ++xb) {
                    for (index_t yb = yb_lo; yb <= yb_hi; ++yb) {
                        for (index_t zb = zb_lo; zb <= zb_hi; ++zb) {
                            block_coordi_ptr[3 * idx + 0] = xb;
                            block_coordi_ptr[3 * idx + 1] = yb;
                            block_coordi_ptr[3 * idx + 2] = zb;
                            idx++;
                        }
                    }
                }
            });

    index_t total_block_count = count.Item<index_t>();
    if (total_block_count == 0) {
        utility::LogError(
                "No block is touched in TSDF volume, abort integration. Please "
                "check specified parameters, especially depth_scale and "
                "voxel_size");
    }
    block_coordi = block_coordi.Slice(0, 0, total_block_count);
    core::Tensor block_buf_indices, block_masks;
    hashmap->Activate(block_coordi, block_buf_indices, block_masks);
    voxel_block_coords = block_coordi.IndexGet({block_masks});
}

void FillInRigidAlignmentTermSYCL(core::Tensor &AtA,
                                  core::Tensor &Atb,
                                  core::Tensor &residual,
                                  const core::Tensor &Ti_ps,
                                  const core::Tensor &Tj_qs,
                                  const core::Tensor &Ri_normal_ps,
                                  int i,
                                  int j,
                                  float threshold) {
    core::Device device = AtA.GetDevice();
    int64_t n = Ti_ps.GetLength();
    if (Tj_qs.GetLength() != n || Ri_normal_ps.GetLength() != n) {
        utility::LogError(
                "Unable to setup linear system: input length mismatch.");
    }

    // First fill in a small 12 x 12 linear system using group reduction.
    // kLocalDim = 12*12 + 12 + 1 = 157 elements.
    static constexpr int kLocalDim12 = 144;  // 12*12
    static constexpr int kLocalDimAtb = 12;
    static constexpr int kLocalDimTotal = kLocalDim12 + kLocalDimAtb + 1;

    // Single contiguous buffer for the reduction:
    // [AtA_local(144) | Atb_local(12) | residual(1)].
    core::Tensor local_sum_all =
            core::Tensor::Zeros({kLocalDimTotal}, core::Float32, device);
    float *local_sum_all_ptr = local_sum_all.GetDataPtr<float>();

    const float *Ti_ps_ptr = static_cast<const float *>(Ti_ps.GetDataPtr());
    const float *Tj_qs_ptr = static_cast<const float *>(Tj_qs.GetDataPtr());
    const float *Ri_normal_ps_ptr =
            static_cast<const float *>(Ri_normal_ps.GetDataPtr());

    sycl::queue queue =
            core::sy::SYCLContext::GetInstance().GetDefaultQueue(device);
    const size_t wgs = core::sy::PreferredWorkGroupSize(device);

    core::sy::PersistentReduce<kLocalDimTotal, float>(
            queue, n, wgs, local_sum_all_ptr,
            [=](int64_t gid, float(&local_sum)[kLocalDimTotal]) {
                const float *p_prime = Ti_ps_ptr + 3 * gid;
                const float *q_prime = Tj_qs_ptr + 3 * gid;
                const float *normal_p_prime = Ri_normal_ps_ptr + 3 * gid;

                float r = (p_prime[0] - q_prime[0]) * normal_p_prime[0] +
                          (p_prime[1] - q_prime[1]) * normal_p_prime[1] +
                          (p_prime[2] - q_prime[2]) * normal_p_prime[2];

                if (sycl::fabs(r) <= threshold) {
                    float J_ij[12];
                    ComputeRigidAlignmentJacobian(q_prime, normal_p_prime,
                                                  J_ij);

                    for (int i_local = 0; i_local < 12; ++i_local) {
                        for (int j_local = 0; j_local < 12; ++j_local) {
                            local_sum[i_local * 12 + j_local] +=
                                    J_ij[i_local] * J_ij[j_local];
                        }
                        local_sum[kLocalDim12 + i_local] += J_ij[i_local] * r;
                    }
                    local_sum[kLocalDim12 + kLocalDimAtb] += r * r;
                }
            });

    core::Tensor AtA_local =
            local_sum_all.Slice(0, 0, kLocalDim12).View({12, 12});
    core::Tensor Atb_local =
            local_sum_all.Slice(0, kLocalDim12, kLocalDim12 + kLocalDimAtb);
    residual = local_sum_all.Slice(0, kLocalDimTotal - 1, kLocalDimTotal);

    // Then fill-in the large linear system.
    std::vector<int64_t> indices_vec(12);
    for (int k = 0; k < 6; ++k) {
        indices_vec[k] = i * 6 + k;
        indices_vec[k + 6] = j * 6 + k;
    }

    std::vector<int64_t> indices_i_vec;
    std::vector<int64_t> indices_j_vec;
    for (int local_i = 0; local_i < 12; ++local_i) {
        for (int local_j = 0; local_j < 12; ++local_j) {
            indices_i_vec.push_back(indices_vec[local_i]);
            indices_j_vec.push_back(indices_vec[local_j]);
        }
    }

    core::Tensor indices(indices_vec, {12}, core::Int64, device);
    core::Tensor indices_i(indices_i_vec, {12 * 12}, core::Int64, device);
    core::Tensor indices_j(indices_j_vec, {12 * 12}, core::Int64, device);

    core::Tensor AtA_sub = AtA.IndexGet({indices_i, indices_j});
    AtA.IndexSet({indices_i, indices_j}, AtA_sub + AtA_local.View({12 * 12}));

    core::Tensor Atb_sub = Atb.IndexGet({indices});
    Atb.IndexSet({indices}, Atb_sub + Atb_local.View({12, 1}));
}

void ComputeOdometryResultPointToPlaneSYCL(
        const core::Tensor &source_vertex_map,
        const core::Tensor &target_vertex_map,
        const core::Tensor &target_normal_map,
        const core::Tensor &intrinsics,
        const core::Tensor &init_source_to_target,
        core::Tensor &delta,
        float &inlier_residual,
        int &inlier_count,
        const float depth_outlier_trunc,
        const float depth_huber_delta) {
    NDArrayIndexer source_vertex_indexer(source_vertex_map, 2);
    NDArrayIndexer target_vertex_indexer(target_vertex_map, 2);
    NDArrayIndexer target_normal_indexer(target_normal_map, 2);

    core::Device device = source_vertex_map.GetDevice();
    core::Tensor trans = init_source_to_target;
    TransformIndexer ti(intrinsics, trans);

    const int64_t rows = source_vertex_indexer.GetShape(0);
    const int64_t cols = source_vertex_indexer.GetShape(1);
    const int64_t n = rows * cols;

    core::Tensor global_sum =
            core::Tensor::Zeros({kReduceDimOdometry}, core::Float32, device);
    float *global_sum_ptr = global_sum.GetDataPtr<float>();

    sycl::queue queue =
            core::sy::SYCLContext::GetInstance().GetDefaultQueue(device);
    const size_t wgs = core::sy::PreferredWorkGroupSize(device);

    core::sy::PersistentReduce<kReduceDimOdometry, float>(
            queue, n, wgs, global_sum_ptr,
            [=](int64_t gid, float(&local_sum)[kReduceDimOdometry]) {
                const int y = static_cast<int>(gid / cols);
                const int x = static_cast<int>(gid % cols);

                float J[6] = {0};
                float r = 0;
                const bool valid = GetJacobianPointToPlane(
                        x, y, depth_outlier_trunc, source_vertex_indexer,
                        target_vertex_indexer, target_normal_indexer, ti, J, r);

                if (valid) {
                    const float d_huber = HuberDeriv(r, depth_huber_delta);
                    const float r_huber = HuberLoss(r, depth_huber_delta);
                    int offset = 0;
                    for (int i = 0; i < 6; ++i) {
                        for (int j = 0; j <= i; ++j) {
                            local_sum[offset++] += J[i] * J[j];
                        }
                        local_sum[21 + i] += J[i] * d_huber;
                    }
                    local_sum[27] += r_huber;
                    local_sum[28] += 1.0f;
                }
            });

    DecodeAndSolve6x6(global_sum, delta, inlier_residual, inlier_count);
}

void ComputeOdometryResultIntensitySYCL(
        const core::Tensor &source_depth,
        const core::Tensor &target_depth,
        const core::Tensor &source_intensity,
        const core::Tensor &target_intensity,
        const core::Tensor &target_intensity_dx,
        const core::Tensor &target_intensity_dy,
        const core::Tensor &source_vertex_map,
        const core::Tensor &intrinsics,
        const core::Tensor &init_source_to_target,
        core::Tensor &delta,
        float &inlier_residual,
        int &inlier_count,
        const float depth_outlier_trunc,
        const float intensity_huber_delta) {
    NDArrayIndexer source_depth_indexer(source_depth, 2);
    NDArrayIndexer target_depth_indexer(target_depth, 2);
    NDArrayIndexer source_intensity_indexer(source_intensity, 2);
    NDArrayIndexer target_intensity_indexer(target_intensity, 2);
    NDArrayIndexer target_intensity_dx_indexer(target_intensity_dx, 2);
    NDArrayIndexer target_intensity_dy_indexer(target_intensity_dy, 2);
    NDArrayIndexer source_vertex_indexer(source_vertex_map, 2);

    core::Device device = source_vertex_map.GetDevice();
    core::Tensor trans = init_source_to_target;
    TransformIndexer ti(intrinsics, trans);

    const int64_t rows = source_vertex_indexer.GetShape(0);
    const int64_t cols = source_vertex_indexer.GetShape(1);
    const int64_t n = rows * cols;

    core::Tensor global_sum =
            core::Tensor::Zeros({kReduceDimOdometry}, core::Float32, device);
    float *global_sum_ptr = global_sum.GetDataPtr<float>();

    sycl::queue queue =
            core::sy::SYCLContext::GetInstance().GetDefaultQueue(device);
    const size_t wgs = core::sy::PreferredWorkGroupSize(device);

    core::sy::PersistentReduce<kReduceDimOdometry, float>(
            queue, n, wgs, global_sum_ptr,
            [=](int64_t gid, float(&local_sum)[kReduceDimOdometry]) {
                const int y = static_cast<int>(gid / cols);
                const int x = static_cast<int>(gid % cols);

                float J_I[6] = {0};
                float r_I = 0;
                const bool valid = GetJacobianIntensity(
                        x, y, depth_outlier_trunc, source_depth_indexer,
                        target_depth_indexer, source_intensity_indexer,
                        target_intensity_indexer, target_intensity_dx_indexer,
                        target_intensity_dy_indexer, source_vertex_indexer, ti,
                        J_I, r_I);

                if (valid) {
                    const float d_huber =
                            HuberDeriv(r_I, intensity_huber_delta);
                    const float r_huber = HuberLoss(r_I, intensity_huber_delta);
                    int offset = 0;
                    for (int i = 0; i < 6; ++i) {
                        for (int j = 0; j <= i; ++j) {
                            local_sum[offset++] += J_I[i] * J_I[j];
                        }
                        local_sum[21 + i] += J_I[i] * d_huber;
                    }
                    local_sum[27] += r_huber;
                    local_sum[28] += 1.0f;
                }
            });

    DecodeAndSolve6x6(global_sum, delta, inlier_residual, inlier_count);
}

void ComputeOdometryResultHybridSYCL(const core::Tensor &source_depth,
                                     const core::Tensor &target_depth,
                                     const core::Tensor &source_intensity,
                                     const core::Tensor &target_intensity,
                                     const core::Tensor &target_depth_dx,
                                     const core::Tensor &target_depth_dy,
                                     const core::Tensor &target_intensity_dx,
                                     const core::Tensor &target_intensity_dy,
                                     const core::Tensor &source_vertex_map,
                                     const core::Tensor &intrinsics,
                                     const core::Tensor &init_source_to_target,
                                     core::Tensor &delta,
                                     float &inlier_residual,
                                     int &inlier_count,
                                     const float depth_outlier_trunc,
                                     const float depth_huber_delta,
                                     const float intensity_huber_delta) {
    NDArrayIndexer source_depth_indexer(source_depth, 2);
    NDArrayIndexer target_depth_indexer(target_depth, 2);
    NDArrayIndexer source_intensity_indexer(source_intensity, 2);
    NDArrayIndexer target_intensity_indexer(target_intensity, 2);
    NDArrayIndexer target_depth_dx_indexer(target_depth_dx, 2);
    NDArrayIndexer target_depth_dy_indexer(target_depth_dy, 2);
    NDArrayIndexer target_intensity_dx_indexer(target_intensity_dx, 2);
    NDArrayIndexer target_intensity_dy_indexer(target_intensity_dy, 2);
    NDArrayIndexer source_vertex_indexer(source_vertex_map, 2);

    core::Device device = source_vertex_map.GetDevice();
    core::Tensor trans = init_source_to_target;
    TransformIndexer ti(intrinsics, trans);

    const int64_t rows = source_vertex_indexer.GetShape(0);
    const int64_t cols = source_vertex_indexer.GetShape(1);
    const int64_t n = rows * cols;

    core::Tensor global_sum =
            core::Tensor::Zeros({kReduceDimOdometry}, core::Float32, device);
    float *global_sum_ptr = global_sum.GetDataPtr<float>();

    sycl::queue queue =
            core::sy::SYCLContext::GetInstance().GetDefaultQueue(device);
    const size_t wgs = core::sy::PreferredWorkGroupSize(device);

    core::sy::PersistentReduce<kReduceDimOdometry, float>(
            queue, n, wgs, global_sum_ptr,
            [=](int64_t gid, float(&local_sum)[kReduceDimOdometry]) {
                const int y = static_cast<int>(gid / cols);
                const int x = static_cast<int>(gid % cols);

                float J_I[6] = {0}, J_D[6] = {0};
                float r_I = 0, r_D = 0;
                const bool valid = GetJacobianHybrid(
                        x, y, depth_outlier_trunc, source_depth_indexer,
                        target_depth_indexer, source_intensity_indexer,
                        target_intensity_indexer, target_depth_dx_indexer,
                        target_depth_dy_indexer, target_intensity_dx_indexer,
                        target_intensity_dy_indexer, source_vertex_indexer, ti,
                        J_I, J_D, r_I, r_D);

                if (valid) {
                    int offset = 0;
                    for (int i = 0; i < 6; ++i) {
                        for (int j = 0; j <= i; ++j) {
                            local_sum[offset++] +=
                                    J_I[i] * J_I[j] + J_D[i] * J_D[j];
                        }
                        local_sum[21 + i] +=
                                J_I[i] *
                                        HuberDeriv(r_I, intensity_huber_delta) +
                                J_D[i] * HuberDeriv(r_D, depth_huber_delta);
                    }
                    local_sum[27] += HuberLoss(r_I, intensity_huber_delta) +
                                     HuberLoss(r_D, depth_huber_delta);
                    local_sum[28] += 1.0f;
                }
            });

    DecodeAndSolve6x6(global_sum, delta, inlier_residual, inlier_count);
}

void ComputeOdometryInformationMatrixSYCL(const core::Tensor &source_vertex_map,
                                          const core::Tensor &target_vertex_map,
                                          const core::Tensor &intrinsic,
                                          const core::Tensor &source_to_target,
                                          const float square_dist_thr,
                                          core::Tensor &information) {
    NDArrayIndexer source_vertex_indexer(source_vertex_map, 2);
    NDArrayIndexer target_vertex_indexer(target_vertex_map, 2);

    core::Device device = source_vertex_map.GetDevice();
    core::Tensor trans = source_to_target;
    TransformIndexer ti(intrinsic, trans);

    const int64_t rows = source_vertex_indexer.GetShape(0);
    const int64_t cols = source_vertex_indexer.GetShape(1);
    const int64_t n = rows * cols;

    core::Tensor global_sum =
            core::Tensor::Zeros({kJtJDimOdometry}, core::Float32, device);
    float *global_sum_ptr = global_sum.GetDataPtr<float>();

    sycl::queue queue =
            core::sy::SYCLContext::GetInstance().GetDefaultQueue(device);
    const size_t wgs = core::sy::PreferredWorkGroupSize(device);

    core::sy::PersistentReduce<kJtJDimOdometry, float>(
            queue, n, wgs, global_sum_ptr,
            [=](int64_t gid, float(&local_sum)[kJtJDimOdometry]) {
                const int y = static_cast<int>(gid / cols);
                const int x = static_cast<int>(gid % cols);

                float J_x[6] = {0}, J_y[6] = {0}, J_z[6] = {0};
                float rx = 0, ry = 0, rz = 0;
                const bool valid = GetJacobianPointToPoint(
                        x, y, square_dist_thr, source_vertex_indexer,
                        target_vertex_indexer, ti, J_x, J_y, J_z, rx, ry, rz);

                if (valid) {
                    int offset = 0;
                    for (int i = 0; i < 6; ++i) {
                        for (int j = 0; j <= i; ++j) {
                            local_sum[offset++] += J_x[i] * J_x[j] +
                                                   J_y[i] * J_y[j] +
                                                   J_z[i] * J_z[j];
                        }
                    }
                }
            });

    const core::Device host(core::Device("CPU:0"));
    information = core::Tensor::Empty({6, 6}, core::Float64, host);
    global_sum = global_sum.To(host, core::Float64);

    double *info_ptr = information.GetDataPtr<double>();
    double *reduction_ptr = global_sum.GetDataPtr<double>();
    for (int j = 0; j < 6; j++) {
        const int64_t reduction_idx = ((j * (j + 1)) / 2);
        for (int k = 0; k <= j; k++) {
            info_ptr[j * 6 + k] = reduction_ptr[reduction_idx + k];
            info_ptr[k * 6 + j] = reduction_ptr[reduction_idx + k];
        }
    }
}

std::tuple<core::Tensor, core::Tensor> ComputeRtPointToPointTensor(
        const core::Tensor &source_points,
        const core::Tensor &target_points,
        const core::Tensor &correspondence_indices,
        const core::Device &device,
        int &inlier_count) {
    core::Tensor valid = correspondence_indices.Ne(-1).Reshape({-1});
    // correpondence_set : (i, corres[i]).
    if (valid.GetLength() == 0) {
        utility::LogError("No valid correspondence present.");
    }

    // source[i] and target[corres[i]] is a correspondence.
    core::Tensor source_indices =
            core::Tensor::Arange(0, source_points.GetShape()[0], 1, core::Int64,
                                 device)
                    .IndexGet({valid});
    // Only take valid indices.
    core::Tensor target_indices =
            correspondence_indices.IndexGet({valid}).Reshape({-1});

    // Number of good correspondences (C).
    inlier_count = source_indices.GetLength();

    core::Tensor source_select = source_points.IndexGet({source_indices});
    core::Tensor target_select = target_points.IndexGet({target_indices});

    // https://ieeexplore.ieee.org/document/88573
    core::Tensor mean_s = source_select.Mean({0}, true);
    core::Tensor mean_t = target_select.Mean({0}, true);

    // Compute linear system on CPU as Float64.
    core::Device host("CPU:0");
    core::Tensor Sxy = (target_select - mean_t)
                               .T()
                               .Matmul(source_select - mean_s)
                               .Div_(static_cast<float>(inlier_count))
                               .To(host, core::Float64);

    mean_s = mean_s.To(host, core::Float64);
    mean_t = mean_t.To(host, core::Float64);

    core::Tensor U, D, VT;
    std::tie(U, D, VT) = Sxy.SVD();
    core::Tensor S = core::Tensor::Eye(3, core::Float64, host);
    core::Tensor R, t;
    if (U.Det() * (VT.T()).Det() < 0) {
        S[-1][-1] = -1;
    }
    R = U.Matmul(S.Matmul(VT));
    t = mean_t.Reshape({-1}) - R.Matmul(mean_s.T()).Reshape({-1});
    return std::make_tuple(R, t);
}

void ComputePosePointToPlaneSYCL(const core::Tensor &source_points,
                                 const core::Tensor &target_points,
                                 const core::Tensor &target_normals,
                                 const core::Tensor &correspondence_indices,
                                 core::Tensor &pose,
                                 float &residual,
                                 int &inlier_count,
                                 const core::Dtype &dtype,
                                 const core::Device &device,
                                 const registration::RobustKernel &kernel) {
    const int64_t n = source_points.GetLength();

    core::Tensor global_sum = core::Tensor::Zeros({kReduceDim}, dtype, device);

    sycl::queue queue =
            core::sy::SYCLContext::GetInstance().GetDefaultQueue(device);
    const size_t wgs = core::sy::PreferredWorkGroupSize(device);

    DISPATCH_FLOAT_DTYPE_TO_TEMPLATE(dtype, [&]() {
        scalar_t *global_sum_ptr = global_sum.GetDataPtr<scalar_t>();

        DISPATCH_ROBUST_KERNEL_FUNCTION(
                kernel.type_, scalar_t, kernel.scaling_parameter_,
                kernel.shape_parameter_, [&]() {
                    const scalar_t *source_points_ptr =
                            source_points.GetDataPtr<scalar_t>();
                    const scalar_t *target_points_ptr =
                            target_points.GetDataPtr<scalar_t>();
                    const scalar_t *target_normals_ptr =
                            target_normals.GetDataPtr<scalar_t>();
                    const int64_t *correspondence_indices_ptr =
                            correspondence_indices.GetDataPtr<int64_t>();

                    core::sy::PersistentReduce<kReduceDim, scalar_t>(
                            queue, n, wgs, global_sum_ptr,
                            [=](int64_t gid, scalar_t(&local_sum)[kReduceDim]) {
                                scalar_t J_ij[6] = {0};
                                scalar_t r = 0;
                                const bool valid =
                                        GetJacobianPointToPlane<scalar_t>(
                                                gid, source_points_ptr,
                                                target_points_ptr,
                                                target_normals_ptr,
                                                correspondence_indices_ptr,
                                                J_ij, r);

                                if (valid) {
                                    const scalar_t w =
                                            GetWeightFromRobustKernel(r);
                                    int i = 0;
                                    for (int j = 0; j < 6; ++j) {
                                        for (int k = 0; k <= j; ++k) {
                                            local_sum[i++] +=
                                                    J_ij[j] * w * J_ij[k];
                                        }
                                        local_sum[21 + j] += J_ij[j] * w * r;
                                    }
                                    local_sum[27] += r;
                                    local_sum[28] += scalar_t(1);
                                }
                            });
                });
    });

    DecodeAndSolve6x6(global_sum, pose, residual, inlier_count);
}

void ComputePoseColoredICPSYCL(const core::Tensor &source_points,
                               const core::Tensor &source_colors,
                               const core::Tensor &target_points,
                               const core::Tensor &target_normals,
                               const core::Tensor &target_colors,
                               const core::Tensor &target_color_gradients,
                               const core::Tensor &correspondence_indices,
                               core::Tensor &pose,
                               float &residual,
                               int &inlier_count,
                               const core::Dtype &dtype,
                               const core::Device &device,
                               const registration::RobustKernel &kernel,
                               const double &lambda_geometric) {
    const int64_t n = source_points.GetLength();

    core::Tensor global_sum = core::Tensor::Zeros({kReduceDim}, dtype, device);

    sycl::queue queue =
            core::sy::SYCLContext::GetInstance().GetDefaultQueue(device);
    const size_t wgs = core::sy::PreferredWorkGroupSize(device);

    DISPATCH_FLOAT_DTYPE_TO_TEMPLATE(dtype, [&]() {
        const scalar_t sqrt_lambda_geometric =
                static_cast<scalar_t>(sqrt(lambda_geometric));
        const scalar_t sqrt_lambda_photometric =
                static_cast<scalar_t>(sqrt(1.0 - lambda_geometric));
        scalar_t *global_sum_ptr = global_sum.GetDataPtr<scalar_t>();

        DISPATCH_ROBUST_KERNEL_FUNCTION(
                kernel.type_, scalar_t, kernel.scaling_parameter_,
                kernel.shape_parameter_, [&]() {
                    const scalar_t *source_points_ptr =
                            source_points.GetDataPtr<scalar_t>();
                    const scalar_t *source_colors_ptr =
                            source_colors.GetDataPtr<scalar_t>();
                    const scalar_t *target_points_ptr =
                            target_points.GetDataPtr<scalar_t>();
                    const scalar_t *target_normals_ptr =
                            target_normals.GetDataPtr<scalar_t>();
                    const scalar_t *target_colors_ptr =
                            target_colors.GetDataPtr<scalar_t>();
                    const scalar_t *target_color_gradients_ptr =
                            target_color_gradients.GetDataPtr<scalar_t>();
                    const int64_t *correspondence_indices_ptr =
                            correspondence_indices.GetDataPtr<int64_t>();

                    core::sy::PersistentReduce<kReduceDim, scalar_t>(
                            queue, n, wgs, global_sum_ptr,
                            [=](int64_t gid, scalar_t(&local_sum)[kReduceDim]) {
                                scalar_t J_G[6] = {0}, J_I[6] = {0};
                                scalar_t r_G = 0, r_I = 0;

                                const bool valid =
                                        GetJacobianColoredICP<scalar_t>(
                                                gid, source_points_ptr,
                                                source_colors_ptr,
                                                target_points_ptr,
                                                target_normals_ptr,
                                                target_colors_ptr,
                                                target_color_gradients_ptr,
                                                correspondence_indices_ptr,
                                                sqrt_lambda_geometric,
                                                sqrt_lambda_photometric, J_G,
                                                J_I, r_G, r_I);

                                if (valid) {
                                    const scalar_t w_G =
                                            GetWeightFromRobustKernel(r_G);
                                    const scalar_t w_I =
                                            GetWeightFromRobustKernel(r_I);

                                    int i = 0;
                                    for (int j = 0; j < 6; ++j) {
                                        for (int k = 0; k <= j; ++k) {
                                            local_sum[i++] +=
                                                    J_G[j] * w_G * J_G[k] +
                                                    J_I[j] * w_I * J_I[k];
                                        }
                                        local_sum[21 + j] +=
                                                J_G[j] * w_G * r_G +
                                                J_I[j] * w_I * r_I;
                                    }
                                    local_sum[27] += r_G * r_G + r_I * r_I;
                                    local_sum[28] += scalar_t(1);
                                }
                            });
                });
    });

    DecodeAndSolve6x6(global_sum, pose, residual, inlier_count);
}

void ComputePoseDopplerICPSYCL(
        const core::Tensor &source_points,
        const core::Tensor &source_dopplers,
        const core::Tensor &source_directions,
        const core::Tensor &target_points,
        const core::Tensor &target_normals,
        const core::Tensor &correspondence_indices,
        core::Tensor &output_pose,
        float &residual,
        int &inlier_count,
        const core::Dtype &dtype,
        const core::Device &device,
        const core::Tensor &R_S_to_V,
        const core::Tensor &r_v_to_s_in_V,
        const core::Tensor &w_v_in_V,
        const core::Tensor &v_v_in_V,
        const double period,
        const bool reject_dynamic_outliers,
        const double doppler_outlier_threshold,
        const registration::RobustKernel &kernel_geometric,
        const registration::RobustKernel &kernel_doppler,
        const double lambda_doppler) {
    const int64_t n = source_points.GetLength();

    core::Tensor global_sum = core::Tensor::Zeros({kReduceDim}, dtype, device);
    core::Tensor v_s_in_S = core::Tensor::Zeros({3}, dtype, device);

    sycl::queue queue =
            core::sy::SYCLContext::GetInstance().GetDefaultQueue(device);
    const size_t wgs = core::sy::PreferredWorkGroupSize(device);

    DISPATCH_FLOAT_DTYPE_TO_TEMPLATE(dtype, [&]() {
        const scalar_t sqrt_lambda_geometric =
                sqrt(1.0 - static_cast<scalar_t>(lambda_doppler));
        const scalar_t sqrt_lambda_doppler = sqrt(lambda_doppler);
        const scalar_t sqrt_lambda_doppler_by_dt =
                sqrt_lambda_doppler / static_cast<scalar_t>(period);

        // Pre-compute v_s_in_S using a
        // single-task kernel.
        {
            const scalar_t *R_S_to_V_ptr = R_S_to_V.GetDataPtr<scalar_t>();
            const scalar_t *r_v_to_s_in_V_ptr =
                    r_v_to_s_in_V.GetDataPtr<scalar_t>();
            const scalar_t *w_v_in_V_ptr = w_v_in_V.GetDataPtr<scalar_t>();
            const scalar_t *v_v_in_V_ptr = v_v_in_V.GetDataPtr<scalar_t>();
            scalar_t *v_s_in_S_ptr = v_s_in_S.GetDataPtr<scalar_t>();
            queue.single_task([=]() {
                     PreComputeForDopplerICP(R_S_to_V_ptr, r_v_to_s_in_V_ptr,
                                             w_v_in_V_ptr, v_v_in_V_ptr,
                                             v_s_in_S_ptr);
                 }).wait_and_throw();
        }

        scalar_t *global_sum_ptr = global_sum.GetDataPtr<scalar_t>();

        DISPATCH_DUAL_ROBUST_KERNEL_FUNCTION(
                scalar_t, kernel_geometric.type_,
                kernel_geometric.scaling_parameter_, kernel_doppler.type_,
                kernel_doppler.scaling_parameter_, [&]() {
                    const scalar_t *source_points_ptr =
                            source_points.GetDataPtr<scalar_t>();
                    const scalar_t *source_dopplers_ptr =
                            source_dopplers.GetDataPtr<scalar_t>();
                    const scalar_t *source_directions_ptr =
                            source_directions.GetDataPtr<scalar_t>();
                    const scalar_t *target_points_ptr =
                            target_points.GetDataPtr<scalar_t>();
                    const scalar_t *target_normals_ptr =
                            target_normals.GetDataPtr<scalar_t>();
                    const int64_t *correspondence_indices_ptr =
                            correspondence_indices.GetDataPtr<int64_t>();
                    const scalar_t *R_S_to_V_ptr =
                            R_S_to_V.GetDataPtr<scalar_t>();
                    const scalar_t *r_v_to_s_in_V_ptr =
                            r_v_to_s_in_V.GetDataPtr<scalar_t>();
                    const scalar_t *v_s_in_S_ptr =
                            v_s_in_S.GetDataPtr<scalar_t>();

                    core::sy::PersistentReduce<kReduceDim, scalar_t>(
                            queue, n, wgs, global_sum_ptr,
                            [=](int64_t gid, scalar_t(&local_sum)[kReduceDim]) {
                                scalar_t J_G[6] = {0}, J_D[6] = {0};
                                scalar_t r_G = 0, r_D = 0;

                                const bool valid = GetJacobianDopplerICP<
                                        scalar_t>(
                                        gid, source_points_ptr,
                                        source_dopplers_ptr,
                                        source_directions_ptr,
                                        target_points_ptr, target_normals_ptr,
                                        correspondence_indices_ptr,
                                        R_S_to_V_ptr, r_v_to_s_in_V_ptr,
                                        v_s_in_S_ptr, reject_dynamic_outliers,
                                        static_cast<scalar_t>(
                                                doppler_outlier_threshold),
                                        sqrt_lambda_geometric,
                                        sqrt_lambda_doppler,
                                        sqrt_lambda_doppler_by_dt, J_G, J_D,
                                        r_G, r_D);

                                if (valid) {
                                    const scalar_t w_G =
                                            GetWeightFromRobustKernelFirst(r_G);
                                    const scalar_t w_D =
                                            GetWeightFromRobustKernelSecond(
                                                    r_D);

                                    int i = 0;
                                    for (int j = 0; j < 6; ++j) {
                                        for (int k = 0; k <= j; ++k) {
                                            local_sum[i++] +=
                                                    J_G[j] * w_G * J_G[k] +
                                                    J_D[j] * w_D * J_D[k];
                                        }
                                        local_sum[21 + j] +=
                                                J_G[j] * w_G * r_G +
                                                J_D[j] * w_D * r_D;
                                    }
                                    local_sum[27] += r_G * r_G + r_D * r_D;
                                    local_sum[28] += scalar_t(1);
                                }
                            });
                });
    });

    DecodeAndSolve6x6(global_sum, output_pose, residual, inlier_count);
}

void ComputeInformationMatrixSYCL(const core::Tensor &target_points,
                                  const core::Tensor &correspondence_indices,
                                  core::Tensor &information_matrix,
                                  const core::Dtype &dtype,
                                  const core::Device &device) {
    const int64_t n = correspondence_indices.GetLength();

    core::Tensor global_sum = core::Tensor::Zeros({21}, dtype, device);

    sycl::queue queue =
            core::sy::SYCLContext::GetInstance().GetDefaultQueue(device);
    const size_t wgs = core::sy::PreferredWorkGroupSize(device);

    DISPATCH_FLOAT_DTYPE_TO_TEMPLATE(dtype, [&]() {
        scalar_t *global_sum_ptr = global_sum.GetDataPtr<scalar_t>();
        const scalar_t *target_points_ptr =
                target_points.GetDataPtr<scalar_t>();
        const int64_t *correspondence_indices_ptr =
                correspondence_indices.GetDataPtr<int64_t>();

        core::sy::PersistentReduce<21, scalar_t>(
                queue, n, wgs, global_sum_ptr,
                [=](int64_t gid, scalar_t(&local_sum)[21]) {
                    scalar_t J_x[6] = {0}, J_y[6] = {0}, J_z[6] = {0};
                    const bool valid = GetInformationJacobians<scalar_t>(
                            gid, target_points_ptr, correspondence_indices_ptr,
                            J_x, J_y, J_z);

                    if (valid) {
                        int i = 0;
                        for (int j = 0; j < 6; ++j) {
                            for (int k = 0; k <= j; ++k) {
                                local_sum[i++] += J_x[j] * J_x[k] +
                                                  J_y[j] * J_y[k] +
                                                  J_z[j] * J_z[k];
                            }
                        }
                    }
                });

        // Match RegistrationCUDA.cu: reduce on device, symmetrize on CPU
        // Float64.
        const core::Device host(core::Device("CPU:0"));
        core::Tensor global_sum_cpu = global_sum.To(host, core::Float64);
        double *sum_ptr = global_sum_cpu.GetDataPtr<double>();

        // Information matrix is on CPU of type Float64.
        double *GTG_ptr = information_matrix.GetDataPtr<double>();

        int i = 0;
        for (int j = 0; j < 6; j++) {
            for (int k = 0; k <= j; k++) {
                GTG_ptr[j * 6 + k] = GTG_ptr[k * 6 + j] = sum_ptr[i];
                ++i;
            }
        }
    });
}

void PoseToTransformationSYCL(scalar_t *transformation_ptr,
                              const scalar_t *pose_ptr,
                              const core::Device &device) {
    sycl::queue queue =
            core::sy::SYCLContext::GetInstance().GetDefaultQueue(device);
    queue.single_task([=]() {
             PoseToTransformationImpl(transformation_ptr, pose_ptr);
         }).wait_and_throw();
}

void TransformationToPoseSYCL(scalar_t *pose_ptr,
                              const scalar_t *transformation_ptr,
                              const core::Device &device) {
    sycl::queue queue =
            core::sy::SYCLContext::GetInstance().GetDefaultQueue(device);
    queue.single_task([=]() {
             TransformationToPoseImpl(pose_ptr, transformation_ptr);
         }).wait_and_throw();
}

std::vector<core::Device> GetSYCLDevicesForTesting() {
    std::vector<core::Device> sycl_devices =
            core::Device::GetAvailableSYCLDevices();

    // A real SYCL GPU is available: keep existing behavior of testing only
    // the first (GPU) device, skipping the CPU fallback.
    if (sycl_devices.size() > 1) {
        sycl_devices.resize(1);
        return sycl_devices;
    }

    // Only the CPU fallback is available. Use it in CI, skip it otherwise.
    if (IsCIEnvironment() && sycl_devices.size() == 1) {
        return sycl_devices;
    }

    return {};
}

TEST_P(HashMapPermuteDevices, InsertNoCapacitySlack) {
    core::Device device = GetParam();
    std::vector<core::HashBackendType> backends;
    if (device.IsCUDA()) {
        backends.push_back(core::HashBackendType::Slab);
        backends.push_back(core::HashBackendType::StdGPU);
    } else if (device.IsSYCL()) {
        backends.push_back(core::HashBackendType::Default);
    } else {
        backends.push_back(core::HashBackendType::TBB);
    }

    const int n = 20000;
    const int slots = 2;
    // No headroom: the buffer heap has exactly as many slots as there are
    // unique keys, so any leaked slot is directly observable.
    const int init_capacity = slots;

    HashData<int, int> data(n, slots);
    core::Tensor keys(data.keys_, {n}, core::Int32, device);
    core::Tensor values(data.vals_, {n}, core::Int32, device);

    for (auto backend : backends) {
        core::HashMap hashmap(init_capacity, core::Int32, {1}, core::Int32, {1},
                              device, backend);

        core::Tensor buf_indices, masks;
        hashmap.Insert(keys, values, buf_indices, masks);
        EXPECT_EQ(masks.To(core::Int64).Sum({0}).Item<int64_t>(), slots);
        EXPECT_EQ(hashmap.Size(), slots);
    }
}

void SetUp() override {
        if (GetParam().IsCPU()) {
            GTEST_SKIP() << "CPU is the oracle for this parity check.";
        }
        sycl = GetParam();
    }

