d::shared_ptr<Dialog> CreateAboutDialog(Window *window) {
    auto &theme = window->GetTheme();
    auto em = theme.font_size;
    auto dlg = std::make_shared<Dialog>("About");

    auto title = std::make_shared<Label>(
            (std::string("Open3D ") + OPEN3D_VERSION).c_str());
    auto text = std::make_shared<Label>(
            "The MIT License (MIT)\n"
            "Copyright (c) 2018-2024 www.open3d.org\n\n"

            "Permission is hereby granted, free of charge, to any person "
            "obtaining a copy of this software and associated documentation "
            "files (the \"Software\"), to deal in the Software without "
            "restriction, including without limitation the rights to use, "
            "copy, modify, merge, publish, distribute, sublicense, and/or "
            "sell copies of the Software, and to permit persons to whom "
            "the Software is furnished to do so, subject to the following "
            "conditions:\n\n"

            "The above copyright notice and this permission notice shall be "
            "included in all copies or substantial portions of the "
            "Software.\n\n"

            "THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, "
            "EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES "
            "OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND "
            "NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT "
            "HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, "
            "WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING "
            "FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR "
            "OTHER DEALINGS IN THE SOFTWARE.");
    auto ok = std::make_shared<Button>("OK");
    ok->SetOnClicked([window]() { window->CloseDialog(); });

    Margins margins(em);
    auto layout = std::make_shared<Vert>(0, margins);
    layout->AddChild(Horiz::MakeCentered(title));
    layout->AddFixed(em);
    auto scroll = std::make_shared<ScrollableVert>(0);
    scroll->AddChild(text);
    layout->AddChild(scroll);
    layout->AddFixed(em);
    layout->AddChild(Horiz::MakeCentered(ok));
    dlg->AddChild(layout);

    return dlg;
}

d::shared_ptr<Dialog> CreateControlsHelpDialog(Window *window) {
    auto &theme = window->GetTheme();
    auto em = theme.font_size;
    auto dlg = std::make_shared<Dialog>("Controls");

    // Helper to build a two-column grid of shortcut rows.
    // Each row is (key label, description label).  Section headers span the
    // left column only; the right column gets an empty string.
    auto grid = std::make_shared<VGrid>(2, int(0.25f * em));

    auto AddRow = [&grid](const char *key, const char *desc) {
        grid->AddChild(std::make_shared<Label>(key));
        grid->AddChild(std::make_shared<Label>(desc));
    };
    // A section header uses the full left column; right cell is blank.
    auto AddSection = [&AddRow](const char *title) { AddRow(title, ""); };
    // A blank spacer row between sections.
    auto AddSpacer = [&AddRow]() { AddRow("", ""); };

    // ---- Arcball (Orbit) mode --------------------------------------------
    AddSection("Arcball mode");
    AddRow("Left-drag", "Rotate camera");
    AddRow("Shift + left-drag", "Forward / backward");
#if defined(__APPLE__)
    AddRow("Cmd + left-drag", "Pan camera");
    AddRow("Opt + left-drag (up/down)", "Rotate around forward axis");
#else
    AddRow("Ctrl + left-drag", "Pan camera");
    AddRow("Win + left-drag (up/down)", "Rotate around forward axis");
#endif
    // GNOME3 uses Win/Meta to move windows, so provide an alternative.
    AddRow("Ctrl + Shift + left-drag", "Rotate around forward axis");
#if defined(__APPLE__)
    AddRow("Ctrl + left-drag", "Rotate directional light");
#else
    AddRow("Alt + left-drag", "Rotate directional light");
#endif
    AddRow("Right-drag", "Pan camera");
    AddRow("Middle-drag", "Rotate directional light");
    AddRow("Scroll wheel", "Forward / backward");
    AddRow("Shift + scroll wheel", "Change field of view");

    AddSpacer();

    // ---- Fly mode --------------------------------------------------------
    AddSection("Fly mode");
    AddRow("Left-drag", "Look (rotate camera)");
#if defined(__APPLE__)
    AddRow("Opt + left-drag", "Rotate around forward axis");
#else
    AddRow("Win + left-drag", "Rotate around forward axis");
#endif
    AddRow("W / S", "Forward / backward");
    AddRow("A / D", "Step left / right");
    AddRow("Q / Z", "Step up / down");
    AddRow("E / R", "Roll left / right");
    AddRow("Up / Down arrow", "Look up / down");
    AddRow("Left / Right arrow", "Look left / right");

    // Wrap the grid in a scrollable area so the dialog stays compact on
    // small displays.
    Margins grid_margins(em, int(0.5f * em));
    auto scroll = std::make_shared<ScrollableVert>(0, grid_margins);
    scroll->AddChild(grid);

    auto ok = std::make_shared<Button>("OK");
    ok->SetOnClicked([window]() { window->CloseDialog(); });

    Margins outer(em);
    auto layout = std::make_shared<Vert>(int(0.5f * em), outer);
    layout->AddChild(scroll);
    layout->AddChild(Horiz::MakeCentered(ok));
    dlg->AddChild(layout);

    return dlg;
}

void Label::DrawOverlay(const DrawContext& context) const {
    const auto& frame = GetFrame();
    ImDrawList* draw_list = ImGui::GetForegroundDrawList();
    ImFont* font = static_cast<ImFont*>(context.fonts.GetFont(impl_->font_id_));
    const float font_size = font->FontSize;
    const bool is_default_color = (impl_->color_ == DEFAULT_COLOR);
    const ImU32 text_col = is_default_color ? ImGui::GetColorU32(ImGuiCol_Text)
                                            : colorToImguiRGBA(impl_->color_);

    const ImVec2 padding = ImGui::GetStyle().FramePadding;
    const ImVec2 pos(float(frame.x + padding.x), float(frame.y + padding.y));
    const float wrap_width =
            std::max(1.0f, float(frame.width) - 2.0f * padding.x);

    const char* text_begin = impl_->text_.c_str();
    const char* text_end = text_begin + impl_->text_.size();

    draw_list->AddText(font, font_size, pos, text_col, text_begin, text_end,
                       wrap_width);
}

DebugHudEnvMode ParseOpen3dDebugHudMode() {
    const char* env = std::getenv("OPEN3D_DEBUG");
    if (!env || env[0] == '\0') {
        return DebugHudEnvMode::kNone;
    }
    std::string debugconfig(env);
    std::transform(debugconfig.begin(), debugconfig.end(), debugconfig.begin(),
                   ::tolower);
    if (debugconfig.find("frametime") != std::string::npos) {
        return DebugHudEnvMode::kFrameTime;
    }
    if (debugconfig.find("fps") != std::string::npos) {
        return DebugHudEnvMode::kFps;
    }
    return DebugHudEnvMode::kNone;
}

void BlendPremultipliedSplatOverRgb8(
        uint8_t* base_rgb, int n_channels, const float* gs_rgba, int w, int h) {
    const int n = w * h;
    for (int i = 0; i < n; ++i) {
        const float fr = gs_rgba[i * 4 + 0];
        const float fg = gs_rgba[i * 4 + 1];
        const float fb = gs_rgba[i * 4 + 2];
        const float fa = gs_rgba[i * 4 + 3];
        const float br = static_cast<float>(base_rgb[i * n_channels + 0]) *
                         (1.f / 255.f);
        const float bg = static_cast<float>(base_rgb[i * n_channels + 1]) *
                         (1.f / 255.f);
        const float bb = static_cast<float>(base_rgb[i * n_channels + 2]) *
                         (1.f / 255.f);
        const float r = fr + br * (1.f - fa);
        const float g = fg + bg * (1.f - fa);
        const float b = fb + bb * (1.f - fa);
        base_rgb[i * n_channels + 0] = static_cast<uint8_t>(
                std::min(std::max(r, 0.f), 1.f) * 255.f + 0.5f);
        base_rgb[i * n_channels + 1] = static_cast<uint8_t>(
                std::min(std::max(g, 0.f), 1.f) * 255.f + 0.5f);
        base_rgb[i * n_channels + 2] = static_cast<uint8_t>(
                std::min(std::max(b, 0.f), 1.f) * 255.f + 0.5f);
        if (n_channels == 4) {
            base_rgb[i * n_channels + 3] = 255;
        }
    }
}

