bool EnsureProgramsLoaded() override {
        if (programs_loaded_) return programs_valid_;
        programs_loaded_ = true;
        programs_valid_ = false;

        auto& interop = GaussianSplatVulkanInteropContext::GetInstance();
        if (!interop.IsValid()) {
            utility::LogWarning(
                    "GaussianSplatVulkan: interop context not initialized");
            return false;
        }

        device_ = interop.GetDevice();
        physical_device_ = interop.GetPhysicalDevice();
        compute_queue_ = interop.GetComputeQueue();
        queue_family_ = interop.GetComputeQueueFamily();
        debug_utils_enabled_ = interop.GetDebugUtilsEnabled();

        if (!InitVma()) return false;
        if (!InitCommandPool()) return false;
        if (!InitFence()) return false;
        if (!InitSampler()) return false;

        // Shaders are compiled with -V --target-env vulkan1.3 by
        // open3d_add_compute_shaders.
        const std::string shader_root =
                EngineInstance::GetResourcePath() + "/gaussian_splat/";

        for (int i = 0; i < static_cast<int>(ComputeProgramId::kCount); ++i) {
            if (!LoadShader(static_cast<ComputeProgramId>(i), shader_root)) {
                utility::LogWarning(
                        "GaussianSplatVulkan: failed to load shader {}",
                        kGsShaderNames[i]);
                return false;
            }
        }
        programs_valid_ = true;
        // Cache the device's maximum compute workgroup count along X so
        // PassRunner can split large dispatches without hardcoding 65535.
        // Use vkGetPhysicalDeviceProperties2 (Vulkan 1.1+) to avoid the
        // legacy-command validation warning triggered by the v1.0 variant.
        VkPhysicalDeviceProperties2 props2{};
        props2.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2;
        VULKAN_HPP_DEFAULT_DISPATCHER.vkGetPhysicalDeviceProperties2(
                physical_device_, &props2);
        max_wg_count_x_ = props2.properties.limits.maxComputeWorkGroupCount[0];
        utility::LogDebug("GaussianSplatVulkan: programs loaded");
        return true;
    }

std::uint32_t GetMaxComputeWorkGroupCount() const override {
        // Returns the cached value queried at program-load time.
        // Falls back to the Vulkan-mandated minimum (65535) if not yet loaded.
        return max_wg_count_x_ > 0 ? max_wg_count_x_ : 65535u;
    }

void DestroyBuffer(std::uintptr_t buf) override {
        auto it = buffers_.find(buf);
        if (it == buffers_.end()) return;
        auto& e = it->second;
        // Persistent-mapped allocations (CPU_TO_GPU +
        // VMA_ALLOCATION_CREATE_MAPPED_BIT) are managed by VMA internally; do
        // NOT call vmaUnmapMemory on them. vmaDestroyBuffer handles cleanup
        // including the persistent mapping.
        vmaDestroyBuffer(vma_, e.buffer, e.alloc);
        buffers_.erase(it);
    }

std::uintptr_t ResizeBuffer(std::uintptr_t buf,
                                std::size_t new_size,
                                const char* label = nullptr) override {
        if (buf == 0) return CreateBuffer(new_size, label);
        auto it = buffers_.find(buf);
        if (it == buffers_.end()) return CreateBuffer(new_size, label);
        if (it->second.size == new_size) return buf;
        DestroyBuffer(buf);
        return CreateBuffer(new_size, label);
    }

std::uintptr_t ResizePrivateBuffer(std::uintptr_t buf,
                                       std::size_t new_size,
                                       const char* label = nullptr) override {
        if (new_size == 0) {
            DestroyBuffer(buf);
            return 0;
        }
        if (buf == 0) return CreatePrivateBuffer(new_size, label);
        auto it = buffers_.find(buf);
        if (it == buffers_.end()) return CreatePrivateBuffer(new_size, label);
        if (it->second.size == new_size) return buf;
        DestroyBuffer(buf);
        return CreatePrivateBuffer(new_size, label);
    }

void UploadBuffer(std::uintptr_t buf,
                      const void* data,
                      std::size_t size,
                      std::size_t offset) override {
        auto it = buffers_.find(buf);
        if (it == buffers_.end()) return;
        auto& e = it->second;
        void* mapped = e.mapped;
        if (!mapped) {
            if (vmaMapMemory(vma_, e.alloc, &mapped) != VK_SUCCESS) return;
        }
        std::memcpy(static_cast<char*>(mapped) + offset, data, size);
        if (!e.mapped) {
            vmaFlushAllocation(vma_, e.alloc, offset, size);
            vmaUnmapMemory(vma_, e.alloc);
        }
    }

bool DownloadBuffer(std::uintptr_t buf,
                        void* dst,
                        std::size_t size,
                        std::size_t offset) override {
        auto it = buffers_.find(buf);
        if (it == buffers_.end()) return false;
        auto& e = it->second;
        if (e.is_private) return false;
        void* mapped = e.mapped;
        if (!mapped) {
            if (vmaMapMemory(vma_, e.alloc, &mapped) != VK_SUCCESS)
                return false;
        }
        vmaInvalidateAllocation(vma_, e.alloc, offset, size);
        std::memcpy(dst, static_cast<const char*>(mapped) + offset, size);
        if (!e.mapped) vmaUnmapMemory(vma_, e.alloc);
        return true;
    }

void ClearBufferUInt32Zero(std::uintptr_t buf) override {
        auto it = buffers_.find(buf);
        if (it == buffers_.end()) return;
        cmd_.fillBuffer(vk::Buffer(it->second.buffer), 0, VK_WHOLE_SIZE, 0u);
    }

void BindSSBO(std::uint32_t binding, std::uintptr_t buf) override {
        auto it = buffers_.find(buf);
        if (it == buffers_.end()) return;
        PendingWrite pw{};
        pw.binding = binding;
        pw.type = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER;
        pw.buf = {it->second.buffer, 0, VK_WHOLE_SIZE};
        pending_.push_back(pw);
    }

void BindUBO(std::uint32_t binding, std::uintptr_t buf) override {
        auto it = buffers_.find(buf);
        if (it == buffers_.end()) return;
        PendingWrite pw{};
        pw.binding = binding;
        pw.type = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
        pw.buf = {it->second.buffer, 0, it->second.size};
        pending_.push_back(pw);
    }

void BindUBORange(std::uint32_t binding,
                      std::uintptr_t buf,
                      std::size_t offset,
                      std::size_t range_size) override {
        auto it = buffers_.find(buf);
        if (it == buffers_.end()) return;
        PendingWrite pw{};
        pw.binding = binding;
        pw.type = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
        pw.buf = {it->second.buffer, offset, range_size};
        pending_.push_back(pw);
    }

void BindImage(std::uint32_t binding,
                   std::uintptr_t tex,
                   std::uint32_t /*width*/,
                   std::uint32_t /*height*/,
                   ImageFormat /*fmt*/) override {
        // Depth images (D32_SFLOAT) lack VK_IMAGE_USAGE_STORAGE_BIT and
        // cannot be bound as STORAGE_IMAGE.  This indicates a caller bug
        // (wrong handle); skip silently so we don't trigger VUID-00339.
        auto it = textures_.find(tex);
        if (it == textures_.end()) {
            auto git = gl_to_handle_.find(static_cast<std::uint32_t>(tex));
            if (git != gl_to_handle_.end()) {
                it = textures_.find(git->second);
            }
        }
        if (it != textures_.end() &&
            it->second.format == VK_FORMAT_D32_SFLOAT) {
            utility::LogWarning(
                    "GaussianSplatVulkan: BindImage(binding={}) skipped — "
                    "handle resolves to a depth image which cannot be a "
                    "STORAGE_IMAGE. Check handle/GL-name mapping.",
                    binding);
            return;
        }
        auto view = ResolveImageView(tex, VK_IMAGE_LAYOUT_GENERAL);
        if (view == VK_NULL_HANDLE) return;
        PendingWrite pw{};
        pw.binding = binding;
        pw.type = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
        pw.img = {VK_NULL_HANDLE, view, VK_IMAGE_LAYOUT_GENERAL};
        pending_.push_back(pw);
    }

id BindSamplerTexture(std::uint32_t unit,
                            std::uintptr_t tex,
                            std::uint32_t /*width*/,
                            std::uint32_t /*height*/) override {
        auto view =
                ResolveImageView(tex, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL);
        if (view == VK_NULL_HANDLE) return;
        PendingWrite pw{};
        pw.binding = unit;
        pw.type = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
        pw.img = {static_cast<VkSampler>(*nearest_sampler_), view,
                  VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL};
        pending_.push_back(pw);
    }

id UseProgram(ComputeProgramId id) override {
        int i = static_cast<int>(id);
        if (i < 0 || i >= static_cast<int>(ComputeProgramId::kCount)) return;
        auto& p = pipelines_[i];
        if (!p.valid) return;
        active_id_ = i;
        cmd_.bindPipeline(vk::PipelineBindPoint::eCompute, *p.pipeline);
        pending_.clear();
    }

id Dispatch(std::uint32_t gx,
                  std::uint32_t gy,
                  std::uint32_t gz) override {
        FlushPendingBindings();
        cmd_.dispatch(gx, gy, gz);
    }

id DispatchIndirect(std::uintptr_t indirect_buf,
                          std::size_t byte_offset) override {
        auto it = buffers_.find(indirect_buf);
        if (it == buffers_.end()) return;
        FlushPendingBindings();
        cmd_.dispatchIndirect(vk::Buffer(it->second.buffer),
                              static_cast<vk::DeviceSize>(byte_offset));
    }

id FullBarrier() override {
        // Full compute+transfer memory barrier using Vulkan 1.3
        // synchronization2.
        vk::MemoryBarrier2 mb{
                vk::PipelineStageFlagBits2::eComputeShader |
                        vk::PipelineStageFlagBits2::eTransfer,
                vk::AccessFlagBits2::eMemoryWrite,
                vk::PipelineStageFlagBits2::eComputeShader |
                        vk::PipelineStageFlagBits2::eTransfer |
                        vk::PipelineStageFlagBits2::eDrawIndirect,
                vk::AccessFlagBits2::eMemoryRead |
                        vk::AccessFlagBits2::eMemoryWrite |
                        vk::AccessFlagBits2::eIndirectCommandRead,
        };
        cmd_.pipelineBarrier2(vk::DependencyInfo{{}, mb, {}, {}});
    }

d::uintptr_t CreateTexture2DR32F(std::uint32_t w,
                                       std::uint32_t h,
                                       const char* /*label*/) override {
        return AllocTex(w, h, VK_FORMAT_R32_SFLOAT,
                        VK_IMAGE_USAGE_STORAGE_BIT |
                                VK_IMAGE_USAGE_SAMPLED_BIT |
                                VK_IMAGE_USAGE_TRANSFER_SRC_BIT,
                        VK_IMAGE_ASPECT_COLOR_BIT);
    }

id DestroyTexture(std::uintptr_t tex) override {
        auto it = textures_.find(tex);
        if (it == textures_.end()) return;
        auto& e = it->second;
        // Explicitly destroy the view before the VMA image for correct order.
        e.view = vk::raii::ImageView{nullptr};
        if (!e.is_shared) vmaDestroyImage(vma_, e.image, e.alloc);
        textures_.erase(it);
    }

d::uintptr_t ResizeTexture2DR32F(std::uintptr_t tex,
                                       std::uint32_t w,
                                       std::uint32_t h,
                                       const char* label) override {
        if (tex == 0) return CreateTexture2DR32F(w, h, label);
        auto it = textures_.find(tex);
        if (it != textures_.end() && it->second.width == w &&
            it->second.height == h)
            return tex;
        DestroyTexture(tex);
        return CreateTexture2DR32F(w, h, label);
    }

d::uintptr_t ResizeTexture2DR16UI(std::uintptr_t tex,
                                        std::uint32_t w,
                                        std::uint32_t h,
                                        const char* /*label*/) override {
        if (tex != 0) {
            auto it = textures_.find(tex);
            if (it != textures_.end() && it->second.width == w &&
                it->second.height == h)
                return tex;
            DestroyTexture(tex);
        }
        return AllocTex(
                w, h, VK_FORMAT_R16_UINT,
                VK_IMAGE_USAGE_STORAGE_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT,
                VK_IMAGE_ASPECT_COLOR_BIT);
    }

ol DownloadTextureR32F(std::uintptr_t tex,
                             std::uint32_t w,
                             std::uint32_t h,
                             std::vector<float>& out) override {
        return DownloadTexBytes(tex, w, h, sizeof(float), out);
    }

ol DownloadTextureR16UI(std::uintptr_t tex,
                              std::uint32_t w,
                              std::uint32_t h,
                              std::vector<std::uint16_t>& out) override {
        return DownloadTexBytes(tex, w, h, sizeof(std::uint16_t), out);
    }

id BeginCompositePass() override {
        BeginCmdBuf();
        // Acquire shared GL-interop images from the external (OpenGL) API into
        // this Vulkan compute queue.  flushAndWait() in FilamentRenderer
        // ensures GL has finished writing before we reach here on the CPU;
        // these barriers perform the GPU-side queue-family ownership transfer
        // and set the layout Vulkan will use.  Without them the spec considers
        // the image contents and layout undefined, which manifests as
        // VK_ERROR_DEVICE_LOST on strict drivers (typically Windows AMD/Intel).
        EmitSharedInteropAcquireBarriers();
    }

id EndCompositePass() override {
        // Release shared images back to the external (OpenGL) API before
        // Filament samples the GS color overlay.  The release barrier transfers
        // queue-family ownership and leaves both images in GENERAL so GL can
        // use them without an explicit Vulkan layout.
        EmitSharedInteropReleaseBarriers();
        SubmitAndWait();
    }

id PushDebugGroup(const char* label) override {
        if (!cmd_active_) return;
        if (!debug_utils_enabled_) return;
        auto fn = VULKAN_HPP_DEFAULT_DISPATCHER.vkCmdBeginDebugUtilsLabelEXT;
        if (!fn) return;
        VkDebugUtilsLabelEXT info{};
        info.sType = VK_STRUCTURE_TYPE_DEBUG_UTILS_LABEL_EXT;
        info.pLabelName = label;
        fn(static_cast<VkCommandBuffer>(*cmd_), &info);
    }

id PopDebugGroup() override {
        if (!cmd_active_) return;
        if (!debug_utils_enabled_) return;
        auto fn = VULKAN_HPP_DEFAULT_DISPATCHER.vkCmdEndDebugUtilsLabelEXT;
        if (fn) fn(static_cast<VkCommandBuffer>(*cmd_));
    }

id RegisterSharedImage(std::uint32_t gl_name,
                             VkImage image,
                             VkFormat format,
                             std::uint32_t w,
                             std::uint32_t h) {
        // If already registered, clean up old data first.
        UnregisterSharedImage(gl_name);
        VkImageAspectFlags aspect = (format == VK_FORMAT_D32_SFLOAT)
                                            ? VK_IMAGE_ASPECT_DEPTH_BIT
                                            : VK_IMAGE_ASPECT_COLOR_BIT;
        vk::raii::ImageView view = CreateImageView(image, format, aspect);
        if (static_cast<VkImageView>(*view) == VK_NULL_HANDLE) {
            utility::LogWarning(
                    "GaussianSplatVulkan: failed to create view for shared "
                    "gl_name={}",
                    gl_name);
            return;
        }
        TexEntry e{};
        e.image = image;
        e.view = std::move(view);
        e.alloc = VK_NULL_HANDLE;  // owned by VulkanInteropContext
        e.format = format;
        e.width = w;
        e.height = h;
        // Initialise current_layout to GENERAL as a consistent sentinel for
        // shared images.  The acquire barrier in
        // EmitSharedInteropAcquireBarriers always uses oldLayout = UNDEFINED
        // (external-acquire pattern, spec §12.7.4) and ignores this field; the
        // release barrier writes GENERAL back here each frame.  The sentinel is
        // used only by ResolveImageView for any intra-CB transitions that
        // follow the acquire.
        e.current_layout = VK_IMAGE_LAYOUT_GENERAL;
        e.is_shared = true;
        uintptr_t handle = next_handle_++;
        textures_[handle] = std::move(e);
        gl_to_handle_[gl_name] = handle;
    }

d UnregisterSharedImage(std::uint32_t gl_name) {
        auto it = gl_to_handle_.find(gl_name);
        if (it == gl_to_handle_.end()) return;
        uintptr_t h = it->second;
        auto te = textures_.find(h);
        if (te != textures_.end()) {
            // vk::raii::ImageView in TexEntry auto-destroyed on erase
            textures_.erase(te);
        }
        gl_to_handle_.erase(it);
    }

p

EmitSharedInteropAcquireBarriers() {
        std::vector<vk::ImageMemoryBarrier2> barriers;
        barriers.reserve(textures_.size());
        for (auto& [handle, e] : textures_) {
            if (!e.is_shared) continue;
            const bool is_depth = (e.format == VK_FORMAT_D32_SFLOAT);
            const vk::ImageLayout new_layout =
                    is_depth ? vk::ImageLayout::eShaderReadOnlyOptimal
                             : vk::ImageLayout::eGeneral;
            const vk::AccessFlags2 dst_access =
                    is_depth ? vk::AccessFlagBits2::eShaderRead
                             : (vk::AccessFlagBits2::eShaderRead |
                                vk::AccessFlagBits2::eShaderWrite);
            const vk::ImageAspectFlags aspect =
                    is_depth ? vk::ImageAspectFlagBits::eDepth
                             : vk::ImageAspectFlagBits::eColor;
            barriers.emplace_back(
                    vk::PipelineStageFlagBits2::eNone,  // srcStageMask
                    vk::AccessFlags2{},                 // srcAccessMask
                    vk::PipelineStageFlagBits2::eComputeShader,  // dstStageMask
                    dst_access,
                    vk::ImageLayout::eGeneral,  // oldLayout (preserve data)
                    new_layout,
                    VK_QUEUE_FAMILY_EXTERNAL,  // srcQueueFamilyIndex
                    queue_family_,             // dstQueueFamilyIndex
                    vk::Image(e.image),
                    vk::ImageSubresourceRange{aspect, 0, 1, 0, 1});
            e.current_layout = static_cast<VkImageLayout>(new_layout);
        }
        if (!barriers.empty()) {
            cmd_.pipelineBarrier2(vk::DependencyInfo{{}, {}, {}, barriers});
        }
    }

EmitSharedInteropReleaseBarriers() {
        if (!cmd_active_) return;
        std::vector<vk::ImageMemoryBarrier2> barriers;
        barriers.reserve(textures_.size());
        for (auto& [handle, e] : textures_) {
            if (!e.is_shared) continue;
            const bool is_depth = (e.format == VK_FORMAT_D32_SFLOAT);
            const vk::AccessFlags2 src_access =
                    is_depth ? vk::AccessFlagBits2::eShaderRead
                             : (vk::AccessFlagBits2::eShaderRead |
                                vk::AccessFlagBits2::eShaderWrite);
            const vk::ImageAspectFlags aspect =
                    is_depth ? vk::ImageAspectFlagBits::eDepth
                             : vk::ImageAspectFlagBits::eColor;
            barriers.emplace_back(
                    vk::PipelineStageFlagBits2::eComputeShader,  // srcStageMask
                    src_access,
                    vk::PipelineStageFlagBits2::eNone,  // dstStageMask
                    vk::AccessFlags2{},                 // dstAccessMask
                    vk::ImageLayout(
                            e.current_layout),  // oldLayout (post-composite)
                    vk::ImageLayout::eGeneral,  // newLayout for GL
                    queue_family_,              // srcQueueFamilyIndex
                    VK_QUEUE_FAMILY_EXTERNAL,   // dstQueueFamilyIndex
                    vk::Image(e.image),
                    vk::ImageSubresourceRange{aspect, 0, 1, 0, 1});
            e.current_layout = VK_IMAGE_LAYOUT_GENERAL;
        }
        if (!barriers.empty()) {
            cmd_.pipelineBarrier2(vk::DependencyInfo{{}, {}, {}, barriers});
        }
    }

itVma() {
        // VMA is compiled with VMA_STATIC_VULKAN_FUNCTIONS=0 and
        // VMA_DYNAMIC_VULKAN_FUNCTIONS=0 (set in
        // GaussianSplatVulkanInteropContext.cpp before VMA_IMPLEMENTATION), so
        // all function pointers must be provided manually.
        // vma::functionsFromDispatcher() fills VmaVulkanFunctions from the
        // vulkan-hpp dynamic dispatcher, which is fully initialised after
        // GaussianSplatVulkanInteropContext::Initialize() calls
        // VULKAN_HPP_DEFAULT_DISPATCHER.init(instance) and .init(device).
        VmaVulkanFunctions vk_fn =
                vma::functionsFromDispatcher(VULKAN_HPP_DEFAULT_DISPATCHER);

        VmaAllocatorCreateInfo ci{};
        ci.vulkanApiVersion = VK_API_VERSION_1_3;
        ci.physicalDevice = physical_device_;
        ci.device = device_;
        ci.instance = GaussianSplatVulkanInteropContext::GetInstance()
                              .GetVkInstance();
        ci.pVulkanFunctions = &vk_fn;
        if (vmaCreateAllocator(&ci, &vma_) != VK_SUCCESS) {
            utility::LogWarning(
                    "GaussianSplatVulkan: vmaCreateAllocator failed");
            return false;
        }
        return true;
    }

    b

itCommandPool() {
        auto& raii_dev = GaussianSplatVulkanInteropContext::GetInstance()
                                 .GetRaiiDevice();
        vk::CommandPoolCreateInfo ci{{}, queue_family_};
        try {
            cmd_pool_ = raii_dev.createCommandPool(ci);
        } catch (const vk::SystemError& e) {
            utility::LogWarning(
                    "GaussianSplatVulkan: vkCreateCommandPool failed: {}",
                    e.what());
            return false;
        }
        vk::CommandBufferAllocateInfo ai{
                *cmd_pool_,
                vk::CommandBufferLevel::ePrimary,
                1,
        };
        try {
            auto cmds = raii_dev.allocateCommandBuffers(ai);
            cmd_ = std::move(cmds.front());
        } catch (const vk::SystemError& e) {
            utility::LogWarning(
                    "GaussianSplatVulkan: vkAllocateCommandBuffers failed: {}",
                    e.what());
            return false;
        }
        return true;
    }

    b

itFence() {
        try {
            fence_ = GaussianSplatVulkanInteropContext::GetInstance()
                             .GetRaiiDevice()
                             .createFence({});
        } catch (const vk::SystemError& e) {
            utility::LogWarning("GaussianSplatVulkan: vkCreateFence failed: {}",
                                e.what());
            return false;
        }
        return true;
    }

    b

itSampler() {
        vk::SamplerCreateInfo si{
                {},
                vk::Filter::eNearest,
                vk::Filter::eNearest,
                vk::SamplerMipmapMode::eNearest,
                vk::SamplerAddressMode::eClampToEdge,
                vk::SamplerAddressMode::eClampToEdge,
                vk::SamplerAddressMode::eClampToEdge,
        };
        try {
            nearest_sampler_ = GaussianSplatVulkanInteropContext::GetInstance()
                                       .GetRaiiDevice()
                                       .createSampler(si);
        } catch (const vk::SystemError& e) {
            utility::LogWarning(
                    "GaussianSplatVulkan: vkCreateSampler failed: {}",
                    e.what());
            return false;
        }
        return true;
    }

    /

adShader(ComputeProgramId id, const std::string& shader_root) {
        const int i = static_cast<int>(id);
        const std::string name = kGsShaderNames[i];
        const std::string spv_path = shader_root + name + ".spv";
        std::vector<char> bytes;
        std::string err;
        if (!utility::filesystem::FReadToBuffer(spv_path, bytes, &err)) {
            utility::LogDebug("GaussianSplatVulkan: SPIR-V not found: {}",
                              spv_path);
            return false;
        }

        // RAII device: all vk::raii::Xxx handles auto-destroy on exception.
        auto& raii_dev = GaussianSplatVulkanInteropContext::GetInstance()
                                 .GetRaiiDevice();
        vk::ShaderModuleCreateInfo smi{
                {},
                bytes.size(),
                reinterpret_cast<const std::uint32_t*>(bytes.data()),
        };
        vk::raii::ShaderModule shader_module{nullptr};
        try {
            shader_module = raii_dev.createShaderModule(smi);
        } catch (const vk::SystemError& e) {
            utility::LogWarning(
                    "GaussianSplatVulkan: vkCreateShaderModule failed for {}: "
                    "{}",
                    name, e.what());
            return false;
        }

        // Build descriptor set layout for this pipeline
        const auto& bt = kShaderBindings[i];
        std::vector<vk::DescriptorSetLayoutBinding> layout_bindings(bt.count);
        std::uint64_t binding_mask = 0;
        for (std::uint32_t j = 0; j < bt.count; ++j) {
            auto& lb = layout_bindings[j];
            lb.binding = bt.descs[j].binding;
            lb.descriptorType =
                    static_cast<vk::DescriptorType>(bt.descs[j].type);
            lb.descriptorCount = 1;
            lb.stageFlags = vk::ShaderStageFlagBits::eCompute;
            if (lb.binding < 64) binding_mask |= (uint64_t(1) << lb.binding);
        }

        vk::DescriptorSetLayoutCreateInfo dslci{};
        // Enable push descriptors for this layout.
        dslci.flags = static_cast<vk::DescriptorSetLayoutCreateFlags>(
                VK_DESCRIPTOR_SET_LAYOUT_CREATE_PUSH_DESCRIPTOR_BIT_KHR);
        dslci.bindingCount = bt.count;
        dslci.pBindings = layout_bindings.data();
        vk::raii::DescriptorSetLayout dset_layout{nullptr};
        try {
            dset_layout = raii_dev.createDescriptorSetLayout(dslci);
        } catch (const vk::SystemError& e) {
            // shader_module auto-destroyed by RAII
            utility::LogWarning(
                    "GaussianSplatVulkan: vkCreateDescriptorSetLayout failed "
                    "for {}: {}",
                    name, e.what());
            return false;
        }

        const vk::DescriptorSetLayout dsl_handle = *dset_layout;
        vk::PipelineLayoutCreateInfo plci{{}, 1, &dsl_handle};
        vk::raii::PipelineLayout pipeline_layout{nullptr};
        try {
            pipeline_layout = raii_dev.createPipelineLayout(plci);
        } catch (const vk::SystemError& e) {
            // dset_layout, shader_module auto-destroyed by RAII
            utility::LogWarning(
                    "GaussianSplatVulkan: vkCreatePipelineLayout failed "
                    "for {}: {}",
                    name, e.what());
            return false;
        }

        vk::ComputePipelineCreateInfo pci{
                {},
                vk::PipelineShaderStageCreateInfo{
                        {},
                        vk::ShaderStageFlagBits::eCompute,
                        *shader_module,
                        "main",
                },
                *pipeline_layout,
        };
        vk::raii::Pipeline pipeline{nullptr};
        try {
            pipeline = raii_dev.createComputePipeline(nullptr, pci);
        } catch (const vk::SystemError& e) {
            // pipeline_layout, dset_layout, shader_module auto-destroyed by
            // RAII
            utility::LogWarning(
                    "GaussianSplatVulkan: vkCreateComputePipelines failed "
                    "for {}: {}",
                    name, e.what());
            return false;
        }
        // shader_module auto-destroyed here (pipeline compiled; module no
        // longer needed)

        auto& p = pipelines_[i];
        p.dset_layout = std::move(dset_layout);
        p.layout = std::move(pipeline_layout);
        p.pipeline = std::move(pipeline);
        p.binding_mask = binding_mask;
        p.valid = true;
        utility::LogDebug("GaussianSplatVulkan: loaded {}", name);
        return true;
    }

    /

ginCmdBuf() {
        if (cmd_active_) return;
        // If the geometry pass submitted a fence-only (fire-and-forget), drain
        // it now before resetting the command pool.  Also guards the case where
        // BeginCmdBuf is called again before a previous SubmitAndWait has had
        // a chance to drain (e.g. geometry pass on frame N+1 before composite
        // on frame N was submitted due to an early return).
        WaitForPendingSubmit();
        vk::Device(device_).resetCommandPool(*cmd_pool_, {});
        cmd_.begin({vk::CommandBufferUsageFlagBits::eOneTimeSubmit});
        cmd_active_ = true;
        active_id_ = -1;
        pending_.clear();
    }

    /

bmitOnly() {
        if (!cmd_active_) return;
        cmd_.end();
        cmd_active_ = false;
        vk::Device(device_).resetFences({*fence_});
        vk::CommandBufferSubmitInfo cmd_info{*cmd_, 0};
        vk::SubmitInfo2 si{{}, {}, cmd_info, {}};
        vk::Queue(compute_queue_).submit2(si, *fence_);
        fence_submitted_ = true;
        active_id_ = -1;
        pending_.clear();
    }

    /

itForPendingSubmit() {
        if (!fence_submitted_) return;
        (void)vk::Device(device_).waitForFences({*fence_}, true, UINT64_MAX);
        vk::Device(device_).resetFences({*fence_});
        fence_submitted_ = false;
    }

    /

bmitAndWait() {
        SubmitOnly();
        WaitForPendingSubmit();
    }

    /

ushPendingBindings() {
        if (active_id_ < 0 || pending_.empty()) return;
        auto& p = pipelines_[active_id_];
        // Build push descriptor writes, filtering to bindings in the layout.
        std::vector<VkWriteDescriptorSet> writes;
        writes.reserve(pending_.size());
        for (auto& pw : pending_) {
            if (pw.binding < 64 &&
                !(p.binding_mask & (uint64_t(1) << pw.binding)))
                continue;  // not in this pipeline's layout
            VkWriteDescriptorSet w{};
            w.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
            w.dstBinding = pw.binding;
            w.descriptorCount = 1;
            w.descriptorType = pw.type;
            switch (pw.type) {
                case VK_DESCRIPTOR_TYPE_STORAGE_BUFFER:
                case VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER:
                    w.pBufferInfo = &pw.buf;
                    break;
                case VK_DESCRIPTOR_TYPE_STORAGE_IMAGE:
                case VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER:
                    w.pImageInfo = &pw.img;
                    break;
                default:
                    break;
            }
            writes.push_back(w);
        }
        if (!writes.empty()) {
            // vkCmdPushDescriptorSetKHR is a KHR extension function; call it
            // through the default dispatcher which was loaded with the device.
            VULKAN_HPP_DEFAULT_DISPATCHER.vkCmdPushDescriptorSetKHR(
                    static_cast<VkCommandBuffer>(*cmd_),
                    VK_PIPELINE_BIND_POINT_COMPUTE,
                    static_cast<VkPipelineLayout>(*p.layout), 0,
                    static_cast<std::uint32_t>(writes.size()), writes.data());
        }
        pending_.clear();
    }

    /

View ResolveImageView(std::uintptr_t handle,
                                 VkImageLayout needed_layout) {
        // First check if this handle directly maps to a known texture.
        auto it = textures_.find(handle);
        if (it == textures_.end()) {
            // Try interpreting the handle as a GL texture name.
            auto git = gl_to_handle_.find(static_cast<std::uint32_t>(handle));
            if (git == gl_to_handle_.end()) return VK_NULL_HANDLE;
            it = textures_.find(git->second);
            if (it == textures_.end()) return VK_NULL_HANDLE;
        }
        auto& e = it->second;
        if (e.current_layout != needed_layout) {
            TransitionImageLayout(e.image, e.format, e.current_layout,
                                  needed_layout);
            e.current_layout = needed_layout;
        }
        return static_cast<VkImageView>(*e.view);
    }

    /

ansitionImageLayout(VkImage image,
                               VkFormat format,
                               VkImageLayout old_layout,
                               VkImageLayout new_layout) {
        const bool is_depth = (format == VK_FORMAT_D32_SFLOAT);
        const auto src_stage =
                (old_layout == VK_IMAGE_LAYOUT_UNDEFINED)
                        ? vk::PipelineStageFlagBits2::eNone
                : (old_layout == VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL)
                        ? vk::PipelineStageFlagBits2::eTransfer
                        : vk::PipelineStageFlagBits2::eComputeShader;
        const auto src_access =
                (old_layout == VK_IMAGE_LAYOUT_UNDEFINED) ? vk::AccessFlags2{}
                : (old_layout == VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL)
                        ? vk::AccessFlagBits2::eTransferRead
                // SHADER_READ_ONLY_OPTIMAL is a read-only layout;
                // using eShaderWrite here would be incorrect and
                // triggers BestPractices-ImageBarrierAccessLayout.
                : (old_layout == VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL)
                        ? vk::AccessFlagBits2::eShaderRead
                        : (vk::AccessFlagBits2::eShaderWrite |
                           vk::AccessFlagBits2::eShaderRead);
        const auto dst_stage =
                (new_layout == VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL)
                        ? vk::PipelineStageFlagBits2::eTransfer
                        : vk::PipelineStageFlagBits2::eComputeShader;
        const vk::AccessFlags2 dst_access =
                (new_layout == VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL)
                        ? vk::AccessFlagBits2::eTransferRead
                : (new_layout == VK_IMAGE_LAYOUT_GENERAL)
                        ? (vk::AccessFlagBits2::eShaderWrite |
                           vk::AccessFlagBits2::eShaderRead)
                        : vk::AccessFlagBits2::eShaderRead;
        vk::ImageMemoryBarrier2 b{
                src_stage,
                src_access,
                dst_stage,
                dst_access,
                static_cast<vk::ImageLayout>(old_layout),
                static_cast<vk::ImageLayout>(new_layout),
                VK_QUEUE_FAMILY_IGNORED,
                VK_QUEUE_FAMILY_IGNORED,
                vk::Image(image),
                vk::ImageSubresourceRange{
                        is_depth ? vk::ImageAspectFlagBits::eDepth
                                 : vk::ImageAspectFlagBits::eColor,
                        0, 1, 0, 1},
        };
        cmd_.pipelineBarrier2(vk::DependencyInfo{{}, {}, {}, b});
    }

    v

i::ImageView CreateImageView(VkImage image,
                                        VkFormat format,
                                        VkImageAspectFlags aspect) {
        vk::ImageViewCreateInfo vci{
                {},
                vk::Image(image),
                vk::ImageViewType::e2D,
                static_cast<vk::Format>(format),
                {},
                vk::ImageSubresourceRange{
                        static_cast<vk::ImageAspectFlags>(aspect), 0, 1, 0, 1},
        };
        try {
            return GaussianSplatVulkanInteropContext::GetInstance()
                    .GetRaiiDevice()
                    .createImageView(vci);
        } catch (const vk::SystemError&) {
            return vk::raii::ImageView{nullptr};
        }
    }

    /

ntptr_t AllocBuf(std::size_t size, bool priv, const char* /*lbl*/) {
        if (size == 0) return 0;
        VkBufferCreateInfo bci{};
        bci.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
        bci.size = size;
        bci.usage = VK_BUFFER_USAGE_STORAGE_BUFFER_BIT |
                    VK_BUFFER_USAGE_UNIFORM_BUFFER_BIT |
                    VK_BUFFER_USAGE_INDIRECT_BUFFER_BIT |
                    VK_BUFFER_USAGE_TRANSFER_DST_BIT |
                    VK_BUFFER_USAGE_TRANSFER_SRC_BIT;
        bci.sharingMode = VK_SHARING_MODE_EXCLUSIVE;

        VmaAllocationCreateInfo aci{};
        if (priv) {
            aci.usage = VMA_MEMORY_USAGE_GPU_ONLY;
        } else {
            aci.usage = VMA_MEMORY_USAGE_CPU_TO_GPU;
            aci.flags = VMA_ALLOCATION_CREATE_MAPPED_BIT;
        }

        VmaAllocation alloc = VK_NULL_HANDLE;
        VkBuffer buf = VK_NULL_HANDLE;
        VmaAllocationInfo info{};
        if (vmaCreateBuffer(vma_, &bci, &aci, &buf, &alloc, &info) !=
            VK_SUCCESS)
            return 0;

        uintptr_t handle = next_handle_++;
        BufEntry& e = buffers_[handle];
        e.alloc = alloc;
        e.buffer = buf;
        e.size = size;
        e.mapped = priv ? nullptr : info.pMappedData;
        e.is_private = priv;
        return handle;
    }

    /

ntptr_t AllocTex(std::uint32_t w,
                            std::uint32_t h,
                            VkFormat format,
                            VkImageUsageFlags usage,
                            VkImageAspectFlags aspect) {
        VkImageCreateInfo ici{};
        ici.sType = VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO;
        ici.imageType = VK_IMAGE_TYPE_2D;
        ici.format = format;
        ici.extent = {w, h, 1};
        ici.mipLevels = 1;
        ici.arrayLayers = 1;
        ici.samples = VK_SAMPLE_COUNT_1_BIT;
        ici.tiling = VK_IMAGE_TILING_OPTIMAL;
        ici.usage = usage;
        ici.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
        ici.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
        VmaAllocationCreateInfo aci{};
        aci.usage = VMA_MEMORY_USAGE_GPU_ONLY;
        VmaAllocation alloc = VK_NULL_HANDLE;
        VkImage image = VK_NULL_HANDLE;
        if (vmaCreateImage(vma_, &ici, &aci, &image, &alloc, nullptr) !=
            VK_SUCCESS)
            return 0;
        vk::raii::ImageView view = CreateImageView(image, format, aspect);
        if (static_cast<VkImageView>(*view) == VK_NULL_HANDLE) {
            vmaDestroyImage(vma_, image, alloc);
            return 0;
        }
        uintptr_t handle = next_handle_++;
        TexEntry& e = textures_[handle];
        e.alloc = alloc;
        e.image = image;
        e.view = std::move(view);
        e.format = format;
        e.width = w;
        e.height = h;
        e.current_layout = VK_IMAGE_LAYOUT_UNDEFINED;
        e.is_shared = false;
        return handle;
    }

    /

wnloadTexBytes(std::uintptr_t tex,
                          std::uint32_t w,
                          std::uint32_t h,
                          std::size_t bytes_per_elem,
                          std::vector<T>& out) {
        auto it = textures_.find(tex);
        if (it == textures_.end() || w == 0 || h == 0) return false;
        const std::size_t row_size =
                static_cast<std::size_t>(w) * bytes_per_elem;
        const std::size_t total = row_size * h;
        out.resize(static_cast<std::size_t>(w) * h);

        // Create a staging readback buffer.
        VkBufferCreateInfo bci{};
        bci.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
        bci.size = total;
        bci.usage = VK_BUFFER_USAGE_TRANSFER_DST_BIT;
        VmaAllocationCreateInfo aci{};
        aci.usage = VMA_MEMORY_USAGE_GPU_TO_CPU;
        aci.flags = VMA_ALLOCATION_CREATE_MAPPED_BIT;
        VmaAllocation alloc = VK_NULL_HANDLE;
        VkBuffer staging = VK_NULL_HANDLE;
        VmaAllocationInfo info{};
        if (vmaCreateBuffer(vma_, &bci, &aci, &staging, &alloc, &info) !=
            VK_SUCCESS)
            return false;

        // Record copy: transition image to TRANSFER_SRC, copy, transition
        // back.
        BeginCmdBuf();
        auto& e = it->second;
        TransitionImageLayout(e.image, e.format, e.current_layout,
                              VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL);
        vk::BufferImageCopy region{
                0,         0,
                0,         {vk::ImageAspectFlagBits::eColor, 0, 0, 1},
                {0, 0, 0}, {w, h, 1},
        };
        cmd_.copyImageToBuffer(vk::Image(e.image),
                               vk::ImageLayout::eTransferSrcOptimal,
                               vk::Buffer(staging), region);
        // Transition back to previous layout (or GENERAL).
        TransitionImageLayout(e.image, e.format,
                              VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                              e.current_layout == VK_IMAGE_LAYOUT_UNDEFINED
                                      ? VK_IMAGE_LAYOUT_GENERAL
                                      : e.current_layout);
        SubmitAndWait();

        std::memcpy(out.data(), info.pMappedData, total);
        vmaDestroyBuffer(vma_, staging, alloc);

        // Flip bottom-up → top-down (matches GL / Filament readPixels).
        for (std::uint32_t row = 0; row < h / 2; ++row) {
            std::swap_ranges(out.begin() + row * w, out.begin() + row * w + w,
                             out.begin() + (h - 1 - row) * w);
        }
        return true;
    }

    //

down() {
        if (device_ == VK_NULL_HANDLE) return;
        vk::Device(device_).waitIdle();

        // Destroy image views (RAII) before their VMA images.
        for (auto& [h, e] : textures_) {
            e.view = vk::raii::ImageView{nullptr};  // vkDestroyImageView
            if (!e.is_shared && e.alloc != VK_NULL_HANDLE)
                vmaDestroyImage(vma_, e.image, e.alloc);
        }
        textures_.clear();

        // Destroy VMA buffers.
        for (auto& [h, e] : buffers_) {
            vmaDestroyBuffer(vma_, e.buffer, e.alloc);
        }
        buffers_.clear();

        // Reset pipeline RAII handles: destroys pipelines, layouts, dset
        // layouts.
        for (auto& p : pipelines_) {
            p.pipeline = vk::raii::Pipeline{nullptr};
            p.layout = vk::raii::PipelineLayout{nullptr};
            p.dset_layout = vk::raii::DescriptorSetLayout{nullptr};
            p.valid = false;
        }

        // Reset remaining RAII handles in reverse init order.
        nearest_sampler_ = vk::raii::Sampler{nullptr};
        fence_ = vk::raii::Fence{nullptr};
        cmd_ = vk::raii::CommandBuffer{nullptr};
        cmd_pool_ = vk::raii::CommandPool{nullptr};
        if (vma_ != VK_NULL_HANDLE) {
            vmaDestroyAllocator(vma_);
            vma_ = VK_NULL_HANDLE;
        }
        device_ = VK_NULL_HANDLE;
    }
};

// -

sterSharedImageInVulkanContext(GaussianSplatGpuContext& ctx,
                                        std::uint32_t gl_name,
                                        std::uintptr_t vk_image_opaque,
                                        std::uint32_t vk_format_opaque,
                                        std::uint32_t width,
                                        std::uint32_t height) {
    auto* vk_ctx = dynamic_cast<GaussianSplatGpuContextVulkan*>(&ctx);
    if (!vk_ctx) return;
    vk_ctx->RegisterSharedImage(
            gl_name, reinterpret_cast<VkImage>(vk_image_opaque),
            static_cast<VkFormat>(vk_format_opaque), width, height);
}

void Un

gisterSharedImageFromVulkanContext(GaussianSplatGpuContext& ctx,
                                            std::uint32_t gl_name) {
    auto* vk_ctx = dynamic_cast<GaussianSplatGpuContextVulkan*>(&ctx);
    if (!vk_ctx) return;
    vk_ctx->UnregisterSharedImage(gl_name);
}

std::un

ue_ptr<GaussianSplatGpuContext> CreateComputeGpuContextVulkan() {
    auto& interop = GaussianSplatVulkanInteropContext::GetInstance();
    if (!interop.IsValid()) {
        utility::LogWarning(
                "GaussianSplatVulkan: interop context not initialized; "
                "Vulkan compute context not created");
        return nullptr;
    }
    return std::make_unique<GaussianSplatGpuContextVulkan>();
}

}  // n

void ReservePackedAttrArrays(GaussianSplatPackedAttrs* out,
                             std::size_t splat_capacity,
                             std::size_t sh_u32_per_splat) {
    out->positions.reserve(splat_capacity);
    out->scales.reserve(2 * splat_capacity);
    out->rotations.reserve(splat_capacity);
    out->dc_opacity.reserve(2 * splat_capacity);
    if (sh_u32_per_splat > 0u) {
        out->sh_coefficients.reserve(splat_capacity * sh_u32_per_splat);
    }
}

std::size_t AppendZeroedShSlot(std::vector<std::uint32_t>* dst_sh,
                               std::size_t sh_u32_per_splat) {
    const std::size_t dst_base = dst_sh->size();
    dst_sh->resize(dst_base + sh_u32_per_splat, 0u);
    return dst_base;
}

void CopyShPrefixToSlot(std::vector<std::uint32_t>* dst_sh,
                        std::size_t dst_base,
                        std::size_t dst_sh_u32_per_splat,
                        const std::uint32_t* src_u32,
                        std::size_t src_u32_count) {
    const std::size_t copy_count =
            std::min(dst_sh_u32_per_splat, src_u32_count);
    if (copy_count == 0u) {
        return;
    }
    std::copy_n(src_u32, copy_count, dst_sh->begin() + dst_base);
}

void SetVisibilityMaskRange(std::vector<std::uint32_t>* visibility_mask,
                            std::uint32_t splat_start,
                            std::uint32_t splat_count,
                            bool visible) {
    const std::uint32_t splat_end = splat_start + splat_count;
    const std::uint32_t n_words = (splat_end + 31u) / 32u;
    visibility_mask->resize(n_words, 0u);
    if (!visible) {
        return;
    }

    for (std::uint32_t k = splat_start; k < splat_end; ++k) {
        (*visibility_mask)[k >> 5u] |= 1u << (k & 31u);
    }
}

std::uint16_t FloatToHalfBits(float value) {
    return Eigen::half_impl::raw_half_as_uint16(
            Eigen::half_impl::float_to_half_rtne(value));
}

inli

std::uint32_t HalfPair(float lo, float hi) {
    return static_cast<std::uint32_t>(FloatToHalfBits(lo)) |
           (static_cast<std::uint32_t>(FloatToHalfBits(hi)) << 16u);
}

// F

td::array<std::uint32_t, 2> PackHalf4(float x,
                                              float y,
                                              float z,
                                              float w) {
    return {{HalfPair(x, y), HalfPair(z, w)}};
}

// Enc

t8_t EncodeSnorm8(float f) {
    const float clamped = std::max(-1.0f, std::min(1.0f, f));
    const auto q = static_cast<std::int8_t>(
            static_cast<int>(std::round(clamped * 127.0f)));
    return static_cast<std::uint8_t>(static_cast<int>(q) + 128);
}

// Pac

t32_t PackSnorm8x4(float w, float x, float y, float z) {
    return static_cast<std::uint32_t>(EncodeSnorm8(w)) |
           (static_cast<std::uint32_t>(EncodeSnorm8(x)) << 8) |
           (static_cast<std::uint32_t>(EncodeSnorm8(y)) << 16) |
           (static_cast<std::uint32_t>(EncodeSnorm8(z)) << 24);
}

// Rad

teGaussianGpuBufferSizes(const PackedGaussianScene& packed,
                                   GaussianGpuBufferSizes* out) {
    // Derive SSBO/UBO byte sizes from the packed-scene tile/splat counts.
    // All size formulas must stay in sync with the dispatch shaders.
    if (!out || !packed.valid) {
        return;
    }
    // ProjectedComposite (32 B): written by project, read only by composite.
    out->projected_composite_size =
            packed.splat_count * sizeof(ProjectedComposite);
    // steal_counter: one uint32 — atomic tile index for composite
    // work-stealing. Composite no longer needs per-tile counts/offsets arrays
    // (binary search).
    out->tile_scalar_size = sizeof(std::uint32_t);

    out->entries_capacity =
            std::max<std::uint32_t>(1u, packed.view_params.limits[0]);
    // Sort key/value ping-pong buffers: one uint32 per entry capacity.
    out->key_cap_size = std::max<std::size_t>(
            4u, static_cast<std::size_t>(out->entries_capacity) *
                        sizeof(std::uint32_t));

    out->radix_num_wg_cap = std::max(
            1u, (out->entries_capacity +
                 kRadixWorkgroupSize * kRadixTargetBlocksPerWG - 1u) /
                        (kRadixWorkgroupSize * kRadixTargetBlocksPerWG));
    out->histogram_buf_size = std::max<std::size_t>(
            4u, static_cast<std::size_t>(out->radix_num_wg_cap) *
                        kRadixSortBins * sizeof(std::uint32_t));

    // 8 slots: 4×histogram + 4×radix_scatter.
    out->dispatch_args_size = 8u * 3u * sizeof(std::uint32_t);
    out->radix_params_size = 4u * kGaussianRadixParamsStride;
}

// ----- Pac

Scene PackGaussianViewParams(
        const GaussianSplatPackedAttrs& attrs,
        const GaussianSplatRenderer::ViewRenderData& render_data,
        const GaussianSplatRenderer::RenderConfig& config) {
    // Build the 288-byte per-frame UBO from camera/viewport/scene state.
    // Called every frame; cost is a single memcpy-sized CPU write to the GPU.
    PackedGaussianScene packed;

    if (attrs.splat_count == 0 || render_data.viewport_size.x() <= 0 ||
        render_data.viewport_size.y() <= 0) {
        return packed;
    }

    const std::uint32_t n = attrs.splat_count;
    const int w = render_data.viewport_size.x();
    const int h = render_data.viewport_size.y();
    const int tx = config.tile_size.x();
    const int ty = config.tile_size.y();
    const int tcx = CeilDiv(w, tx);
    const int tcy = CeilDiv(h, ty);

    auto& vp = packed.view_params;
    std::memset(&vp, 0, sizeof(vp));

    const auto entry_budget =
            static_cast<std::uint64_t>(n) * config.max_tiles_per_splat;
    const auto entry_capacity = static_cast<std::uint32_t>(std::min(
            entry_budget,
            static_cast<std::uint64_t>(config.max_tile_entries_total)));

    // world_from_model: splat positions are in world space → identity.
    // render_data.model_matrix is the camera rig; do not use it here.
    PackMat4(vp.world_from_model, Eigen::Matrix4f::Identity());
    PackMat4(vp.view_from_world,
             render_data.view_matrix.matrix().cast<float>());
    PackMat4(vp.clip_from_view, render_data.projection_matrix.matrix());

    const std::array<float, 4> cam_pn{
            render_data.camera_position.x(), render_data.camera_position.y(),
            render_data.camera_position.z(),
            static_cast<float>(render_data.near_plane)};
    std::memcpy(vp.camera_position_and_near, cam_pn.data(), sizeof(cam_pn));

    const std::array<float, 4> vp_origin_size{
            static_cast<float>(render_data.viewport_origin.x()),
            static_cast<float>(render_data.viewport_origin.y()),
            static_cast<float>(w), static_cast<float>(h)};
    std::memcpy(vp.viewport_origin_and_size, vp_origin_size.data(),
                sizeof(vp_origin_size));

    const int effective_sh_degree =
            std::min(attrs.sh_degree, config.max_sh_degree);
    const std::array<std::uint32_t, 4> scene_u{
            n, static_cast<std::uint32_t>(effective_sh_degree),
            (attrs.antialias || config.antialias) ? 1u : 0u,
            render_data.screen_y_down ? 1u : 0u};
    std::memcpy(vp.scene, scene_u.data(), sizeof(scene_u));

    const std::array<std::uint32_t, 4> tiles_u{
            static_cast<std::uint32_t>(tx), static_cast<std::uint32_t>(ty),
            static_cast<std::uint32_t>(tcx), static_cast<std::uint32_t>(tcy)};
    std::memcpy(vp.tiles, tiles_u.data(), sizeof(tiles_u));

    vp.limits[0] = entry_capacity;
    vp.limits[1] = config.max_tiles_per_splat;
    vp.limits[2] = config.max_tile_entries_total;
    // T = bits needed to hold the largest tile index =
    // floor(log2(max_index))+1. For a single tile (tcx*tcy == 1) max_tile_index
    // == 0, so T defaults to 1 (no zero-shift UB). Clamped to [1,31] so the
    // depth field gets >= 1 bit.
    const std::uint32_t max_tile_index =
            static_cast<std::uint32_t>(tcx * tcy) - 1u;
    std::uint32_t tile_key_bits = 0u;
    for (std::uint32_t v = max_tile_index; v > 0u; v >>= 1u) {
        ++tile_key_bits;
    }
    vp.limits[3] = std::clamp(tile_key_bits, 1u, 31u);

    const std::array<float, 4> depth_rng{
            static_cast<float>(render_data.near_plane),
            static_cast<float>(render_data.far_plane), 0.f, 0.f};
    std::memcpy(vp.depth_range_and_flags, depth_rng.data(), sizeof(depth_rng));

    packed.splat_count = n;
    packed.tile_count = static_cast<std::uint32_t>(tcx * tcy);
    packed.pixel_count = static_cast<std::uint32_t>(w * h);
    packed.valid = true;
    return packed;
}

// ----- PackG

nSplatAttrsDirect(const float* pts_ptr,
                                  std::size_t n,
                                  const float* scale_ptr,
                                  const float* rot_ptr,
                                  const float* f_dc_ptr,
                                  const float* opacity_ptr,
                                  const float* f_rest_ptr,
                                  int source_sh_degree,
                                  int desired_sh_degree,
                                  float min_opacity_logit,
                                  bool antialias,
                                  GaussianSplatPackedAttrs& out) {
    // Pack all per-splat attributes into GPU-ready fp16/snorm8 arrays in a
    // single pass, filtering below-threshold splats to keep upload small.
    // scale_ptr, rot_ptr, f_dc_ptr, opacity_ptr must be non-null when n>0
    // (FilamentScene rejects clouds missing any of these). f_rest_ptr is
    // optional. For n==0, pointers are unused (empty std::vector::data() may be
    // nullptr).
    out = GaussianSplatPackedAttrs{};
    out.sh_degree = desired_sh_degree;
    out.antialias = antialias;
    if (n == 0) {
        out.visibility_mask.assign(0, 0u);
        return;
    }
    if (!pts_ptr || !scale_ptr || !rot_ptr || !f_dc_ptr || !opacity_ptr) {
        return;
    }

    int source_coeffs = 0;
    int desired_coeffs = 0;
    std::size_t sh_u32_per_splat = 0;
    if (desired_sh_degree > 0 && f_rest_ptr) {
        source_coeffs = GetGaussianSplatRestCoeffCount(source_sh_degree);
        desired_coeffs = GetGaussianSplatRestCoeffCount(desired_sh_degree);
        sh_u32_per_splat = GetShU32PerSplat(desired_sh_degree);
    }

    ReservePackedAttrArrays(&out, n, sh_u32_per_splat);

    for (std::size_t i = 0; i < n; ++i) {
        const float opacity = opacity_ptr[i];
        if (opacity < min_opacity_logit) {
            continue;
        }

        out.positions.push_back({pts_ptr[i * 3 + 0], pts_ptr[i * 3 + 1],
                                 pts_ptr[i * 3 + 2], 0.f});

        const auto sc = PackHalf4(scale_ptr[i * 3 + 0], scale_ptr[i * 3 + 1],
                                  scale_ptr[i * 3 + 2], 0.f);
        out.scales.insert(out.scales.end(), sc.begin(), sc.end());

        out.rotations.push_back(
                PackSnorm8x4(rot_ptr[i * 4 + 0], rot_ptr[i * 4 + 1],
                             rot_ptr[i * 4 + 2], rot_ptr[i * 4 + 3]));

        // Apply sigmoid to the raw opacity logit once at pack time; the shader
        // reads the result directly as alpha without a per-frame exp() call.
        const float sigmoid_opacity = 1.0f / (1.0f + std::exp(-opacity));
        const auto dc = PackHalf4(f_dc_ptr[i * 3 + 0], f_dc_ptr[i * 3 + 1],
                                  f_dc_ptr[i * 3 + 2], sigmoid_opacity);
        out.dc_opacity.insert(out.dc_opacity.end(), dc.begin(), dc.end());

        if (sh_u32_per_splat > 0 && f_rest_ptr) {
            const std::size_t dst_base =
                    AppendZeroedShSlot(&out.sh_coefficients, sh_u32_per_splat);
            const float* src = f_rest_ptr + i * source_coeffs;
            const int pairs = desired_coeffs / 2;
            for (int p = 0; p < pairs; ++p) {
                out.sh_coefficients[dst_base + std::size_t(p)] =
                        HalfPair(src[p * 2 + 0], src[p * 2 + 1]);
            }
            if (desired_coeffs & 1) {
                out.sh_coefficients[dst_base + std::size_t(pairs)] =
                        HalfPair(src[desired_coeffs - 1], 0.f);
            }
        }
    }

    out.splat_count = static_cast<std::uint32_t>(out.positions.size());
    // Populate a default all-visible mask so the buffer is always present.
    // RebuildMergedGaussianData() overwrites this with per-object visibility.
    // Bit-packed: all-ones = all splats visible. ceil(n/32) words.
    out.visibility_mask.clear();
    SetVisibilityMaskRange(&out.visibility_mask, 0u, out.splat_count, true);
}

void MergeGaus

anSplatPackedAttrs(
        const std::vector<GaussianSplatMergeItem>& items,
        GaussianSplatPackedAttrs* out,
        std::vector<std::uint32_t>* splat_starts) {
    if (!out) {
        return;
    }

    *out = GaussianSplatPackedAttrs{};
    if (splat_starts) {
        splat_starts->clear();
        splat_starts->reserve(items.size());
    }

    std::uint32_t merged_sh_degree = 0u;
    std::size_t merged_splat_capacity = 0u;
    for (const auto& item : items) {
        if (!item.attrs) {
            continue;
        }
        merged_sh_degree = std::max(merged_sh_degree,
                                    std::uint32_t(item.attrs->sh_degree));
        merged_splat_capacity += item.attrs->splat_count;
    }

    out->sh_degree = static_cast<int>(merged_sh_degree);
    const std::size_t merged_sh_u32_per_splat =
            GetShU32PerSplat(static_cast<int>(merged_sh_degree));
    ReservePackedAttrArrays(out, merged_splat_capacity,
                            merged_sh_u32_per_splat);

    for (const auto& item : items) {
        if (splat_starts) splat_starts->push_back(out->splat_count);
        if (!item.attrs) {
            continue;
        }
        const auto& src = *item.attrs;
        const std::uint32_t splat_count = src.splat_count;

        out->positions.insert(out->positions.end(), src.positions.begin(),
                              src.positions.end());
        out->scales.insert(out->scales.end(), src.scales.begin(),
                           src.scales.end());
        out->rotations.insert(out->rotations.end(), src.rotations.begin(),
                              src.rotations.end());
        out->dc_opacity.insert(out->dc_opacity.end(), src.dc_opacity.begin(),
                               src.dc_opacity.end());

        if (merged_sh_u32_per_splat > 0u) {
            const std::size_t src_sh_u32_per_splat =
                    GetShU32PerSplat(src.sh_degree);
            const std::size_t src_sh_size = src.sh_coefficients.size();
            for (std::uint32_t i = 0; i < splat_count; ++i) {
                const std::size_t dst_base = AppendZeroedShSlot(
                        &out->sh_coefficients, merged_sh_u32_per_splat);
                if (src_sh_u32_per_splat == 0u) {
                    continue;
                }
                const std::size_t src_base =
                        std::size_t(i) * src_sh_u32_per_splat;
                if (src_base >= src_sh_size) {
                    continue;
                }
                CopyShPrefixToSlot(
                        &out->sh_coefficients, dst_base,
                        merged_sh_u32_per_splat,
                        src.sh_coefficients.data() + src_base,
                        std::min(src_sh_u32_per_splat, src_sh_size - src_base));
            }
        }

        SetVisibilityMaskRange(&out->visibility_mask, out->splat_count,
                               splat_count, item.visible);
        out->splat_count += splat_count;
        out->antialias = out->antialias || src.antialias;
    }
}

}  // namespac

const char* GetSessionType() {
#if defined(_WIN32)
    return "windows";
#else
    const char* session = std::getenv("XDG_SESSION_TYPE");
    return session ? session : "unknown";
#endif
}

const char* GetNativeBackendName() {
#if defined(_WIN32)
    return "WGL";
#else
    return "GLX";
#endif
}

bool GaussianSplatOpenGLContext::InitializeStandalone() {
    if (initialized_) {
        return true;
    }

#if !defined(_WIN32)
    if (std::strcmp(GetSessionType(), "wayland") == 0) {
        utility::LogInfo(
                "GaussianSplatOpenGLContext: Wayland session detected; "
                "using X11/GLX via XWayland for Filament compatibility.");
    }
#endif

    glfwWindowHint(GLFW_VISIBLE, GLFW_FALSE);
    glfwWindowHint(GLFW_CLIENT_API, GLFW_OPENGL_API);
    glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, 4);
    glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, 6);
    glfwWindowHint(GLFW_OPENGL_PROFILE, GLFW_OPENGL_CORE_PROFILE);
    glfwWindowHint(GLFW_DOUBLEBUFFER, GLFW_FALSE);

    GLFWwindow* window =
            glfwCreateWindow(1, 1, "O3D_GS_Helper", nullptr, nullptr);
    glfwDefaultWindowHints();
    if (!window) {
        utility::LogWarning(
                "GaussianSplatOpenGLContext: glfwCreateWindow failed. "
                "Linux offscreen rendering now requires an X11/XWayland "
                "server.");
        return false;
    }

    glfwMakeContextCurrent(window);
    glewExperimental = GL_TRUE;
    const GLenum glew_err = glewInit();
    while (glGetError() != GL_NO_ERROR) {
    }
    if (glew_err != GLEW_OK) {
        utility::LogWarning(
                "GaussianSplatOpenGLContext: glewInit warning: {}",
                reinterpret_cast<const char*>(glewGetErrorString(glew_err)));
    }

    glfw_window_ = window;
    initialized_ = true;

    // After glewInit(), probe GL interop extensions for the Vulkan interop
    // context (EXT_memory_object_fd, etc.).
    // This must happen while the GL context is current.
    auto& vk_ctx = GaussianSplatVulkanInteropContext::GetInstance();
    if (vk_ctx.IsValid() && !vk_ctx.AreGLExtensionsReady()) {
        vk_ctx.ProbeGLExtensions();
    }

    const char* vendor = reinterpret_cast<const char*>(glGetString(GL_VENDOR));
    const char* renderer =
            reinterpret_cast<const char*>(glGetString(GL_RENDERER));
    const char* version =
            reinterpret_cast<const char*>(glGetString(GL_VERSION));
    utility::LogDebug(
            "GaussianSplatOpenGLContext: Created standalone {} context "
            "for session={} native={:p}",
            GetNativeBackendName(), GetSessionType(), GetNativeContext());
    utility::LogDebug(
            "GaussianSplatOpenGLContext: GL vendor={} renderer={} "
            "version={}",
            vendor ? vendor : "?", renderer ? renderer : "?",
            version ? version : "?");

    glfwMakeContextCurrent(nullptr);
    return true;
}

bool GaussianSplatOpenGLContext::Initialize() {
    if (initialized_) {
        return true;
    }

    utility::LogWarning(
            "GaussianSplatOpenGLContext: late initialization is not "
            "supported. InitializeStandalone() must run before Filament "
            "Engine::create() so zero-copy sharedGLContext setup succeeds.");
    return false;
}

void* GaussianSplatOpenGLContext::GetNativeContext() const {
    if (!glfw_window_) {
        return nullptr;
    }

    GLFWwindow* window = static_cast<GLFWwindow*>(glfw_window_);
#if defined(_WIN32)
    return reinterpret_cast<void*>(glfwGetWGLContext(window));
#else
    return reinterpret_cast<void*>(glfwGetGLXContext(window));
#endif
}

void GaussianSplatOpenGLContext::Shutdown() {
    if (!initialized_) {
        return;
    }

    glfwMakeContextCurrent(nullptr);
    glfwDestroyWindow(static_cast<GLFWwindow*>(glfw_window_));
    glfw_window_ = nullptr;
    initialized_ = false;
    gl_logged_ = false;
    utility::LogDebug("GaussianSplatOpenGLContext: Shut down.");
}

bool GaussianSplatOpenGLContext::MakeCurrent() {
    if (!initialized_) {
        return false;
    }

    GLFWwindow* window = static_cast<GLFWwindow*>(glfw_window_);
    glfwMakeContextCurrent(window);
    const bool ok = (glfwGetCurrentContext() == window);
    if (!ok) {
        utility::LogWarning(
                "GaussianSplatOpenGLContext: glfwMakeContextCurrent "
                "failed.");
        return false;
    }

    if (!gl_logged_) {
        gl_logged_ = true;
        const char* version =
                reinterpret_cast<const char*>(glGetString(GL_VERSION));
        const char* renderer =
                reinterpret_cast<const char*>(glGetString(GL_RENDERER));
        utility::LogDebug("GaussianSplatOpenGLContext: {} active - GL {} on {}",
                          GetNativeBackendName(), version ? version : "?",
                          renderer ? renderer : "?");
    }

    return true;
}

e std::size_t IndirectByteOffset(std::uint32_t slot) {
    return slot * kIndirectStride;
}

///

LogGaussianGpuErrorsOnce(GaussianSplatGpuContext& ctx,
                              GaussianSplatViewGpuResources& vs) {
    if ((vs.warned_gpu_error_flags & kGaussianGpuErrorKnownMask) ==
        kGaussianGpuErrorKnownMask) {
        return;
    }

    std::array<std::uint32_t, kGaussianCounterCount> counters = {0, 0, 0, 0};
    if (!ctx.DownloadBuffer(vs.counters_buf, counters.data(), sizeof(counters),
                            0)) {
        return;
    }

    const std::uint32_t new_error_flags =
            counters[kGaussianCounterErrorFlagsIndex] &
            ~vs.warned_gpu_error_flags;
    if ((new_error_flags & kGaussianGpuErrorTileEntryOverflow) != 0u) {
        utility::LogWarning(
                "GaussianSplat: tile entry capacity exceeded; excess tile "
                "entries were dropped. Increase "
                "RenderConfig.max_tile_entries_total or max_tiles_per_splat.");
    }
    if ((new_error_flags & kGaussianGpuErrorSortCountClamped) != 0u) {
        utility::LogWarning(
                "GaussianSplat: radix sort input count exceeded the configured "
                "tile entry capacity and was clamped. Output may be "
                "incomplete.");
    }
    vs.warned_gpu_error_flags |= new_error_flags;
}

//

unClassicalRadixSort(GaussianSplatGpuContext& ctx,
                          GaussianSplatViewGpuResources& vs,
                          int src) {
    for (std::uint32_t pass = 0; pass < 4; ++pass) {
        const int dst = 1 - src;
        const std::size_t params_offset = pass * kGaussianRadixParamsStride;

        ctx.ClearBufferUInt32Zero(vs.histogram_buf);
        ctx.FullBarrier();

        GpuComputePass(ctx, ComputeProgramId::kGsRadixHistograms,
                       "gs_radix_histogram")
                .UBORange(14, vs.radix_params_buf, params_offset,
                          sizeof(RadixSortParams))
                .SSBO(0, vs.sort_keys_buf[src])
                .SSBO(1, vs.histogram_buf)
                .DispatchIndirect(vs.dispatch_args_buf,
                                  IndirectByteOffset(kSlotRadixHist0 + pass));
        ctx.FullBarrier();

        GpuComputePass(ctx, ComputeProgramId::kGsRadixScatter,
                       "gs_radix_scatter")
                .UBORange(14, vs.radix_params_buf, params_offset,
                          sizeof(RadixSortParams))
                .SSBO(0, vs.sort_keys_buf[src])
                .SSBO(1, vs.sort_keys_buf[dst])
                .SSBO(2, vs.histogram_buf)
                .SSBO(3, vs.sort_values_buf[src])
                .SSBO(4, vs.sort_values_buf[dst])
                .DispatchIndirect(
                        vs.dispatch_args_buf,
                        IndirectByteOffset(kSlotRadixScatter0 + pass));
        ctx.FullBarrier();

        src = dst;
    }
    return src;
}

}

anCompositePass(GaussianSplatGpuContext& ctx,
                              const GaussianSplatRenderer::RenderConfig& config,
                              GaussianSplatViewGpuResources& vs,
                              GaussianSplatRenderer::OutputTargets& targets) {
    // Ensure the geometry pass has finished writing splat buffers before we
    // read them in the composite pass.  On Vulkan, geometry runs
    // fire-and-forget (overlapping with Filament rendering), so this may be a
    // no-op if the GPU already completed the work; otherwise it blocks until
    // the fence signals.
    ctx.WaitForGeometryPass();

    // Composite splats from the sorted tile-entry buffer onto the GS color
    // texture, then optionally merge GS linear depth with Filament scene depth.
    //
    // Composite dispatch grid sized by viewport / workgroup size.
    // Composite uses a work-stealing dispatch: each workgroup atomically
    // claims tile indices until all tiles are processed.  Tile indices are
    // Morton Z-curve codes: the counter scans [0, morton_range) where
    // morton_range = next_pow2(max(tile_x, tile_y))^2.  Out-of-bounds codes
    // are skipped cheaply by the shader.  Launch ceil(morton_range / 4)
    // workgroups so each handles ~4 tiles on average.
    const std::uint32_t comp_x =
            DivUp(targets.width,
                  static_cast<std::uint32_t>(config.composite_group_size.x()));
    const std::uint32_t comp_y =
            DivUp(targets.height,
                  static_cast<std::uint32_t>(config.composite_group_size.y()));
    // Next power-of-2 side covering both dimensions.
    std::uint32_t morton_side = 1u;
    while (morton_side < comp_x || morton_side < comp_y) morton_side <<= 1u;
    const std::uint32_t morton_range = morton_side * morton_side;
    const std::uint32_t steal_wg_count = std::max(1u, (morton_range + 3u) / 4u);

    // Always upload depth flag when scene depth is present (which is always
    // for interactive GS views). The shader will use this to test occlusion
    // against mesh geometry.
    const bool has_scene_depth = (targets.scene_depth_gl_handle != 0) ||
                                 (targets.scene_depth_mtl_texture != 0);
    if (has_scene_depth) {
        float flag = 1.0f;
        static constexpr std::size_t kDepthFlagOffset =
                offsetof(GaussianViewParams, depth_range_and_flags) +
                3 * sizeof(float);
        ctx.UploadBuffer(vs.view_params_buf, &flag, sizeof(flag),
                         kDepthFlagOffset);
    }

    GpuComputeFrame frame(ctx, GpuComputeFrame::Kind::kComposite);

    // Reset the work-stealing counter so each composite invocation starts
    // tile stealing from 0.
    ctx.ClearBufferUInt32Zero(vs.tile_counts_buf);
    ctx.FullBarrier();

    const std::uint32_t w = targets.width;
    const std::uint32_t h = targets.height;
    vs.composite_depth_tex = ctx.ResizeTexture2DR32F(vs.composite_depth_tex, w,
                                                     h, "gs.composite_depth");
    // Allocate the merged-depth R16UI texture only when both scene depth is
    // present (mesh occluders exist) AND an offscreen depth readback has been
    // requested for this view.  When only GS depth is needed (no meshes),
    // composite_depth_tex (R32F) is read directly via
    // ReadCompositeDepthToFloatCpu.
    if (has_scene_depth && targets.wants_depth_readback) {
        vs.merged_depth_u16_tex = ctx.ResizeTexture2DR16UI(
                vs.merged_depth_u16_tex, w, h, "gs.merged_depth");
    }

    const std::uintptr_t color_tex =
            targets.gs_color_mtl_texture
                    ? targets.gs_color_mtl_texture
                    : static_cast<std::uintptr_t>(targets.color_gl_handle);

    if (color_tex == 0 || vs.composite_depth_tex == 0) {
        utility::LogWarning(
                "GaussianSplat composite: missing output textures.");
        return false;
    }

    auto pass =
            GpuComputePass(ctx, ComputeProgramId::kGsComposite, "gs_composite");
    if (!pass.ok()) {
        return false;
    }

    // Opt9: Work-stealing composite — bindings:
    //   7: sort_keys (binary search to find per-tile entry range)
    //   8: steal_counter (atomic tile claim, reset to 0 above)
    //  10: gs_counters (total_entries for binary search bound)
    //  11: sorted_splat_indices (final sort payload)
    pass.UBO(0, vs.view_params_buf)
            .SSBO(6, vs.projected_composite_buf)
            .SSBO(7, vs.sort_keys_buf[vs.final_sort_src])
            .SSBO(8, vs.tile_counts_buf)  // repurposed as steal_counter
            .SSBO(10, vs.counters_buf)
            .SSBO(11, vs.sort_values_buf[vs.final_sort_src])
            // Image unit 16 for color (shared UBO/image binding 0 conflict in
            // Vulkan); image unit 1 for composite depth.
            .Image(16, color_tex, w, h, ImageFormat::kRGBA16F)
            .Image(1, vs.composite_depth_tex, w, h, ImageFormat::kR32F);

    if (has_scene_depth) {
        std::uintptr_t sd = targets.scene_depth_mtl_texture
                                    ? targets.scene_depth_mtl_texture
                                    : static_cast<std::uintptr_t>(
                                              targets.scene_depth_gl_handle);
        pass.Sampler(14, sd, w, h);
    }

    pass.Dispatch(steal_wg_count, 1u, 1u);
    ctx.FullBarrier();

    // GPU depth-merge pass (optional): merge GS linear depth with Filament
    // scene depth into a normalised R16UI texture for CPU readback.
    // Only dispatched when a readback was requested AND the merged texture
    // was successfully allocated.
    if (targets.wants_depth_readback && vs.merged_depth_u16_tex != 0) {
        const std::uintptr_t sd =
                targets.scene_depth_mtl_texture
                        ? targets.scene_depth_mtl_texture
                        : static_cast<std::uintptr_t>(
                                  targets.scene_depth_gl_handle);
        GpuComputePass(ctx, ComputeProgramId::kGsDepthMerge, "gs_depth_merge")
                .UBO(0, vs.view_params_buf)
                .Sampler(15, vs.composite_depth_tex, w,
                         h)  // binding 15: Metal max texture/sampler index
                .Image(1, vs.merged_depth_u16_tex, w, h, ImageFormat::kR16UI)
                .Sampler(14, sd, w, h)
                .Dispatch(DivUp(w, 16u), DivUp(h, 16u), 1u);
        ctx.FullBarrier();
    }

    ctx.FinishGpuWork();
    // frame destructor calls End() automatically; explicit call omitted.
    LogGaussianGpuErrorsOnce(ctx, vs);

    return ctx.WasLastSubmitSuccessful();
}

}  // namespac

bool PrepareOutputTextures(FilamentView&,
                               FilamentResourceManager&,
                               std::uint32_t,
                               std::uint32_t,
                               GaussianSplatRenderer::OutputTargets&) override {
        return false;
    }

bool RenderGeometryStage(const FilamentView& view,
                             const FilamentScene&,
                             const GaussianSplatRenderer::ViewRenderData&,
                             GaussianSplatRenderer::OutputTargets&) override {
        if (logged_views_.insert(&view).second) {
            utility::LogWarning(
                    "GaussianSplat backend '{}' is selected but GPU "
                    "dispatch is not implemented yet.",
                    name_);
        }
        return false;
    }

bool RenderCompositeStage(const FilamentView&,
                              const GaussianSplatRenderer::ViewRenderData&,
                              GaussianSplatRenderer::OutputTargets&) override {
        return false;
    }

std::unique_ptr<GaussianSplatRenderer::Backend> CreateBackend(
        RenderingType backend,
        FilamentResourceManager& resource_mgr,
        const GaussianSplatRenderer::RenderConfig& config) {
    switch (backend) {
        case RenderingType::kMetal:
#if defined(__APPLE__)
            return CreateGaussianSplatMetalBackend(resource_mgr, config);
#else
            return std::unique_ptr<GaussianSplatRenderer::Backend>(
                    new GaussianSplatPlaceholderBackend("Metal"));
#endif
        case RenderingType::kOpenGL:
        case RenderingType::kDefault:
        case RenderingType::kVulkan:
#if !defined(__APPLE__)
            if (auto vk_backend =
                        CreateGaussianSplatVulkanBackend(resource_mgr, config);
                vk_backend) {
                return vk_backend;
            }
            return std::unique_ptr<GaussianSplatRenderer::Backend>(
                    new GaussianSplatPlaceholderBackend(
                            "Vulkan not available"));
#else
            return std::unique_ptr<GaussianSplatRenderer::Backend>(
                    new GaussianSplatPlaceholderBackend("Unsupported"));
#endif
    }
    return nullptr;
}

bool HasGsColorOutput(const GaussianSplatRenderer::OutputTargets& targets) {
#if defined(__APPLE__)
    return targets.gs_color_mtl_texture != 0;
#else
    return targets.color_gl_handle != 0;
#endif
}

bool GaussianSplatBackendSupported(RenderingType backend) {
    if (!EngineInstance::GetPlatform()) {
        return false;
    }

    switch (backend) {
        case RenderingType::kMetal:
#if defined(__APPLE__)
            return true;
#else
            return false;
#endif
        case RenderingType::kOpenGL:
            // On Linux/Windows, Filament uses OpenGL but 3DGS compute runs on
            // Vulkan (GL compute has limited subgroup support on Intel
            // hardware). Fall through to check Vulkan availability.
        case RenderingType::kDefault:
        case RenderingType::kVulkan:
#if !defined(__APPLE__)
            return GaussianSplatVulkanInteropContext::GetInstance().IsValid();
#else
            return false;
#endif
    }
    return false;
}

bool ProjectionInfoEquals(const Camera::ProjectionInfo& left,
                          const Camera::ProjectionInfo& right) {
    // Compare all active projection fields; used for per-frame dirty detection.
    if (left.is_ortho != right.is_ortho ||
        left.is_intrinsic != right.is_intrinsic) {
        return false;
    }

    if (left.is_intrinsic) {
        return left.proj.intrinsics.fx == right.proj.intrinsics.fx &&
               left.proj.intrinsics.fy == right.proj.intrinsics.fy &&
               left.proj.intrinsics.cx == right.proj.intrinsics.cx &&
               left.proj.intrinsics.cy == right.proj.intrinsics.cy &&
               left.proj.intrinsics.near_plane ==
                       right.proj.intrinsics.near_plane &&
               left.proj.intrinsics.far_plane ==
                       right.proj.intrinsics.far_plane &&
               left.proj.intrinsics.width == right.proj.intrinsics.width &&
               left.proj.intrinsics.height == right.proj.intrinsics.height;
    }

    if (left.is_ortho) {
        return left.proj.ortho.projection == right.proj.ortho.projection &&
               left.proj.ortho.left == right.proj.ortho.left &&
               left.proj.ortho.right == right.proj.ortho.right &&
               left.proj.ortho.bottom == right.proj.ortho.bottom &&
               left.proj.ortho.top == right.proj.ortho.top &&
               left.proj.ortho.near_plane == right.proj.ortho.near_plane &&
               left.proj.ortho.far_plane == right.proj.ortho.far_plane;
    }

    return left.proj.perspective.fov_type == right.proj.perspective.fov_type &&
           left.proj.perspective.fov == right.proj.perspective.fov &&
           left.proj.perspective.aspect == right.proj.perspective.aspect &&
           left.proj.perspective.near_plane ==
                   right.proj.perspective.near_plane &&
           left.proj.perspective.far_plane == right.proj.perspective.far_plane;
}

GaussianSplatRenderer::GaussianSplatRenderer(
        filament::Engine& engine, FilamentResourceManager& resource_mgr)
    : engine_(engine), resource_mgr_(resource_mgr) {
    enabled_ = GaussianSplatBackendSupported(EngineInstance::GetBackendType());
    backend_ = CreateBackend(EngineInstance::GetBackendType(), resource_mgr_,
                             render_config_);
}

GaussianSplatRenderer::~GaussianSplatRenderer() {
    // Destroy output targets before releasing backend resources.
    for (auto& pair : outputs_) {
        ResetOutputTargets(pair.second);
    }
}

void GaussianSplatRenderer::BeginFrame() {
    // Advance the frame counter and notify the backend so it can reset
    // per-frame GPU state (e.g. Metal command buffer recycling).
    ++frame_index_;
    if (backend_) {
        backend_->BeginFrame(frame_index_);
    }
}

void GaussianSplatRenderer::RenderGeometryStage(FilamentView& view,
                                                const FilamentScene& scene) {
    // Skip when disabled or when the scene has no splat geometry.
    if (!enabled_ || !scene.HasGaussianSplatGeometry()) {
        return;
    }

    // Always allocate scene depth for GS views to ensure stable render-target
    // topology. This prevents Filament handle lifecycle hazards that occur
    // when transitioning between private-depth and shared sampleable depth
    // attachments during runtime geometry visibility changes.
    auto& targets = PrepareOutputTargets(view);
    const std::uint64_t scene_change_id = scene.GetGeometryChangeId();
    const bool view_changed = UpdateViewRenderData(targets, view);
    const bool scene_changed = targets.last_scene_change_id != scene_change_id;

    if (view_changed || scene_changed) {
        targets.needs_render = true;
    }

    if (!targets.needs_render) {
        return;
    }

    bool rendered = false;
    if (backend_ && targets.has_render_data) {
        rendered = backend_->RenderGeometryStage(view, scene,
                                                 targets.render_data, targets);
    }
    if (rendered) {
        targets.last_scene_change_id = scene_change_id;
    } else {
        // Geometry stage failed: prevent composite from consuming stale
        // intermediate buffers from the prior frame.
        targets.has_valid_output = false;
        targets.needs_render = false;
    }
}

bool GaussianSplatRenderer::RenderCompositeStage(FilamentView& view) {
    // Run the composite compute pass for a single view; returns true on
    // success.
    auto it = outputs_.find(&view);
    if (it == outputs_.end() || !it->second.needs_render) {
        return false;
    }

    auto& targets = it->second;
    if (targets.width == 0 || targets.height == 0 ||
        !HasGsColorOutput(targets)) {
        return false;
    }

    bool rendered = false;
    if (backend_ && targets.has_render_data) {
        rendered = backend_->RenderCompositeStage(view, targets.render_data,
                                                  targets);
    }

    targets.has_valid_output = rendered;
    targets.needs_render = false;
    targets.last_updated_frame = frame_index_;
    return rendered;
}

void GaussianSplatRenderer::RequestRedrawForView(const FilamentView& view) {
    // Force the next frame to run both GS stages even if nothing has changed.
    auto it = outputs_.find(&view);
    if (it != outputs_.end()) {
        it->second.needs_render = true;
    }
}

void GaussianSplatRenderer::InvalidateOutputForView(FilamentView& view) {
    // Destroy GS outputs for the view, clearing the view's RT first to avoid
    // a use-after-free when Filament processes the pending destroy commands.
    auto it = outputs_.find(&view);
    if (it == outputs_.end()) {
        return;
    }
    // Clear the view's render target BEFORE destroying our GS render target.
    // If the view still points to the GS RT when Filament processes the
    // destroy command, it could try to render through a freed object.
    view.SetRenderTarget({});
    ResetOutputTargets(it->second);
}

void GaussianSplatRenderer::PruneOutputs(
        const std::unordered_set<const FilamentView*>& live_views) {
    // Remove outputs for views that are no longer active, releasing GPU memory.
    for (auto it = outputs_.begin(); it != outputs_.end();) {
        if (live_views.find(it->first) != live_views.end()) {
            ++it;
            continue;
        }

        if (backend_) {
            backend_->ForgetView(*it->first);
        }
        ResetOutputTargets(it->second);
        it = outputs_.erase(it);
    }
}

bool GaussianSplatRenderer::HasOutput(const FilamentView& view) const {
    auto found = outputs_.find(&view);
    return found != outputs_.end() && found->second.color &&
           found->second.depth && found->second.render_target &&
           found->second.has_valid_output;
}

const GaussianSplatRenderer::ViewRenderData*
GaussianSplatRenderer::GetViewRenderData(const FilamentView& view) const {
    auto found = outputs_.find(&view);
    if (found == outputs_.end() || !found->second.has_render_data) {
        return nullptr;
    }
    return &found->second.render_data;
}

void GaussianSplatRenderer::SetRenderConfig(const RenderConfig& config) {
    // Validate and apply a new render config; invalidate all outputs so the
    // next frame rebuilds with the new settings.
    if (!ValidateRenderConfig(config)) {
        utility::LogWarning(
                "Ignoring invalid GaussianSplat render configuration.");
        return;
    }

    render_config_ = config;
    for (auto& pair : outputs_) {
        pair.second.has_valid_output = false;
        pair.second.needs_render = true;
    }
}

TextureHandle GaussianSplatRenderer::GetColorTexture(
        const FilamentView& view) const {
    auto found = outputs_.find(&view);
    return found != outputs_.end() ? found->second.color : TextureHandle();
}

TextureHandle GaussianSplatRenderer::GetDepthTexture(
        const FilamentView& view) const {
    auto found = outputs_.find(&view);
    return found != outputs_.end() ? found->second.depth : TextureHandle();
}

RenderTargetHandle GaussianSplatRenderer::GetColorReadbackRT(
        const FilamentView& view) const {
    auto found = outputs_.find(&view);
    return found != outputs_.end() ? found->second.gs_readback_rt
                                   : RenderTargetHandle();
}

bool GaussianSplatRenderer::ReadMergedDepthToUint16Cpu(
        const FilamentView& view,
        std::vector<std::uint16_t>& out,
        std::uint32_t width,
        std::uint32_t height) {
    if (!backend_) {
        return false;
    }
    return backend_->ReadMergedDepthToUint16Cpu(view, out, width, height);
}

bool GaussianSplatRenderer::ReadCompositeDepthToFloatCpu(
        const FilamentView& view,
        std::vector<float>& out,
        std::uint32_t width,
        std::uint32_t height) {
    if (!backend_) {
        return false;
    }
    return backend_->ReadCompositeDepthToFloatCpu(view, out, width, height);
}

void GaussianSplatRenderer::RequestDepthReadbackForView(
        const FilamentView& view, bool wanted) {
    auto it = outputs_.find(&view);
    if (it != outputs_.end()) {
        it->second.wants_depth_readback = wanted;
    }
}

std::uint32_t GaussianSplatRenderer::GetSceneDepthGLHandle(
        const FilamentView& view) const {
    auto found = outputs_.find(&view);
    return found != outputs_.end() ? found->second.scene_depth_gl_handle : 0;
}

GaussianSplatRenderer::OutputTargets&
GaussianSplatRenderer::PrepareOutputTargets(FilamentView& view) {
    // Allocate (or return cached) output textures and render target for this
    // view.  Zero-copy setup via the backend is tried first; on failure the
    // fallback creates Filament-owned textures.
    auto viewport = view.GetViewport();
    auto& targets = outputs_[&view];
    if (viewport[2] <= 0 || viewport[3] <= 0) {
        view.SetRenderTarget({});
        ResetOutputTargets(targets);
        return targets;
    }

    auto width = static_cast<std::uint32_t>(viewport[2]);
    auto height = static_cast<std::uint32_t>(viewport[3]);
    if (targets.width == width && targets.height == height && targets.color &&
        targets.depth && targets.render_target && HasGsColorOutput(targets)) {
        return targets;
    }

    view.SetRenderTarget({});
    ResetOutputTargets(targets);

    // Attempt zero-copy setup via the backend (GL texture sharing on
    // OpenGL, Metal texture import on Apple). Falls back to Filament-owned
    // textures if the backend returns false.
    const bool zero_copy =
            backend_ && backend_->PrepareOutputTextures(view, resource_mgr_,
                                                        width, height, targets);

    if (!zero_copy) {
        // Fallback: Filament-owned textures (no zero-copy).
        targets.color = resource_mgr_.CreateColorAttachmentTexture(int(width),
                                                                   int(height));
        targets.depth = resource_mgr_.CreateDepthAttachmentTexture(int(width),
                                                                   int(height));
        targets.render_target =
                resource_mgr_.CreateRenderTarget(targets.color, targets.depth);
        view.SetRenderTarget(targets.render_target);
    }

    // Create a color-only render target for offscreen readback via readPixels.
    if (targets.color) {
        targets.gs_readback_rt =
                resource_mgr_.CreateColorOnlyRenderTarget(targets.color);
    }

    targets.width = width;
    targets.height = height;
    targets.has_valid_output = false;
    targets.needs_render = true;
    return targets;
}

void GaussianSplatRenderer::ResetOutputTargets(OutputTargets& targets) {
    // Destroy all GS output handles in the correct order: Filament wrappers
    // first, then the underlying native textures via the backend.
    if (targets.gs_readback_rt) {
        resource_mgr_.Destroy(targets.gs_readback_rt);
        targets.gs_readback_rt = RenderTargetHandle();
    }
    if (targets.render_target) {
        resource_mgr_.Destroy(targets.render_target);
        targets.render_target = RenderTargetHandle();
    }
    if (targets.color) {
        resource_mgr_.Destroy(targets.color);
        targets.color = TextureHandle();
    }
    if (targets.depth) {
        resource_mgr_.Destroy(targets.depth);
        targets.depth = TextureHandle();
    }

    // Release platform-specific textures via the backend.
    if (backend_) {
        backend_->ReleaseOutputTextures(resource_mgr_, targets);
    }
    targets.scene_depth_gl_handle = 0;
    targets.color_gl_handle = 0;
    targets.scene_depth_mtl_texture = 0;
    targets.gs_color_mtl_texture = 0;

    targets.width = 0;
    targets.height = 0;
    targets.has_render_data = false;
    targets.has_valid_output = false;
    targets.needs_render = true;
    targets.wants_depth_readback = false;
    targets.last_scene_change_id = 0;
    targets.last_updated_frame = 0;
}

GaussianSplatRenderer::ViewRenderData
GaussianSplatRenderer::ExtractViewRenderData(const FilamentView& view) const {
    // Extract camera and viewport state for upload to the compute UBO.
    ViewRenderData data;

    auto viewport = view.GetViewport();
    data.viewport_origin = Eigen::Vector2i(viewport[0], viewport[1]);
    data.viewport_size = Eigen::Vector2i(viewport[2], viewport[3]);
    data.screen_y_down =
            (EngineInstance::GetBackendType() != RenderingType::kOpenGL);

    const auto* camera = view.GetCamera();
    if (camera) {
        data.camera_position = camera->GetPosition();
        data.model_matrix = camera->GetModelMatrix();
        data.view_matrix = camera->GetViewMatrix();
        data.projection_matrix = camera->GetProjectionMatrix();
        data.culling_projection_matrix = camera->GetCullingProjectionMatrix();
        data.projection = camera->GetProjection();
        data.near_plane = camera->GetNear();
        data.far_plane = camera->GetFar();
    }

    return data;
}

bool GaussianSplatRenderer::UpdateViewRenderData(OutputTargets& targets,
                                                 const FilamentView& view) {
    // Detect camera/viewport changes; set needs_render when anything changed.
    const ViewRenderData new_data = ExtractViewRenderData(view);
    if (!targets.has_render_data ||
        !ViewRenderDataEquals(targets.render_data, new_data)) {
        targets.render_data = new_data;
        targets.has_render_data = true;
        targets.needs_render = true;
        return true;
    }

    return false;
}

bool GaussianSplatRenderer::ValidateRenderConfig(
        const RenderConfig& config) const {
    // Reject configs with zero or out-of-range values before applying.
    static constexpr int kMaxSupportedShDegree = 2;
    return config.tile_size.x() > 0 && config.tile_size.y() > 0 &&
           config.projection_group_size > 0 &&
           config.composite_group_size.x() > 0 &&
           config.composite_group_size.y() > 0 && config.max_sh_degree >= 0 &&
           config.max_sh_degree <= kMaxSupportedShDegree &&
           config.max_tiles_per_splat > 0 && config.max_tile_entries_total > 0;
}

~GaussianSplatVulkanBackend() override {
        // Free per-view GPU resources via the compute context.
        if (gpu_) {
            for (auto& [view, vs] : view_states_) {
                DestroyViewState(vs);
            }
        }
        view_states_.clear();
        gpu_.reset();
    }

void ForgetView(const FilamentView& view) override {
        auto it = view_states_.find(&view);
        if (it != view_states_.end()) {
            if (gpu_) DestroyViewState(it->second);
            view_states_.erase(it);
        }
    }

bool PrepareOutputTextures(
            FilamentView& view,
            FilamentResourceManager& resource_mgr,
            std::uint32_t width,
            std::uint32_t height,
            GaussianSplatRenderer::OutputTargets& targets) override {
        // Shared GL interop textures: same path as the GL backend.
        // The GL context must be current for EXT_memory_object import.
        auto& gl_ctx = GaussianSplatOpenGLContext::GetInstance();
        if (!gl_ctx.IsValid() || !gl_ctx.MakeCurrent()) {
            return false;
        }

        auto& vk_ctx = GaussianSplatVulkanInteropContext::GetInstance();

        if (vk_ctx.IsValid() && vk_ctx.AreGLExtensionsReady()) {
            SharedImageDesc color_img =
                    vk_ctx.CreateSharedColorImage(width, height, "gs.color");
            if (!color_img.IsValid()) {
                utility::LogWarning(
                        "GaussianSplatVulkan: shared color image failed; "
                        "falling back to GL textures");
            } else {
                SharedImageDesc depth_img = vk_ctx.CreateSharedDepthImage(
                        width, height, "gs.scene_depth");
                if (!depth_img.IsValid()) {
                    vk_ctx.DestroySharedImage(color_img);
                    utility::LogWarning(
                            "GaussianSplatVulkan: shared depth image failed; "
                            "falling back to GL textures");
                } else {
                    targets.color_gl_handle = color_img.gl_texture;
                    targets.color_vk_image = reinterpret_cast<std::uintptr_t>(
                            color_img.vk_image);
                    targets.color_vk_memory = reinterpret_cast<std::uintptr_t>(
                            color_img.vk_memory);
                    targets.color_gl_mem_obj = color_img.gl_memory_object;
                    targets.scene_depth_gl_handle = depth_img.gl_texture;
                    targets.depth_vk_image = reinterpret_cast<std::uintptr_t>(
                            depth_img.vk_image);
                    targets.depth_vk_memory = reinterpret_cast<std::uintptr_t>(
                            depth_img.vk_memory);
                    targets.depth_gl_mem_obj = depth_img.gl_memory_object;
                    targets.uses_vulkan_interop = true;

                    // Register shared images in the Vulkan compute context
                    // so BindImage/BindSamplerTexture can resolve GL names
                    // to VkImages during compute dispatch.
                    EnsureGpuContext();
                    if (gpu_) {
                        RegisterSharedImageInVulkanContext(
                                *gpu_, color_img.gl_texture,
                                reinterpret_cast<std::uintptr_t>(
                                        color_img.vk_image),
                                static_cast<std::uint32_t>(
                                        VK_FORMAT_R16G16B16A16_SFLOAT),
                                width, height);
                        RegisterSharedImageInVulkanContext(
                                *gpu_, depth_img.gl_texture,
                                reinterpret_cast<std::uintptr_t>(
                                        depth_img.vk_image),
                                static_cast<std::uint32_t>(
                                        VK_FORMAT_D32_SFLOAT),
                                width, height);
                    }
                }
            }
        }

        gl_ctx.ReleaseCurrent();

        if (targets.color_gl_handle == 0) return false;

        using Tex = filament::Texture;
        if (targets.scene_depth_gl_handle != 0) {
            targets.depth = resource_mgr.CreateImportedTexture(
                    targets.scene_depth_gl_handle, int(width), int(height),
                    static_cast<int>(Tex::InternalFormat::DEPTH32F),
                    static_cast<int>(Tex::Usage::DEPTH_ATTACHMENT |
                                     Tex::Usage::SAMPLEABLE));
        }
        targets.color = resource_mgr.CreateImportedTexture(
                targets.color_gl_handle, int(width), int(height),
                static_cast<int>(Tex::InternalFormat::RGBA16F),
                static_cast<int>(Tex::Usage::SAMPLEABLE |
                                 Tex::Usage::COLOR_ATTACHMENT |
                                 Tex::Usage::BLIT_SRC));

        auto view_color = view.GetColorBuffer();
        if (!view_color || !targets.color) return false;

        if (targets.depth) {
            targets.render_target =
                    resource_mgr.CreateRenderTarget(view_color, targets.depth);
        } else {
            auto owned_depth = resource_mgr.CreateDepthAttachmentTexture(
                    int(width), int(height));
            targets.depth = owned_depth;
            targets.render_target =
                    resource_mgr.CreateRenderTarget(view_color, targets.depth);
        }
        view.SetRenderTarget(targets.render_target);

        auto* native = view.GetNativeView();
        auto msaa = native->getMultiSampleAntiAliasingOptions();
        msaa.enabled = false;
        native->setMultiSampleAntiAliasingOptions(msaa);
        view.SetPostProcessing(false);

        return static_cast<bool>(targets.render_target);
    }

void ReleaseOutputTextures(
            FilamentResourceManager&,
            GaussianSplatRenderer::OutputTargets& targets) override {
        if (targets.scene_depth_gl_handle == 0 &&
            targets.color_gl_handle == 0) {
            return;
        }

        // Unregister shared images from the Vulkan compute context BEFORE
        // destroying them (prevents stale VkImageView usage in next dispatch).
        if (gpu_ && targets.uses_vulkan_interop) {
            if (targets.color_gl_handle != 0)
                UnregisterSharedImageFromVulkanContext(*gpu_,
                                                       targets.color_gl_handle);
            if (targets.scene_depth_gl_handle != 0)
                UnregisterSharedImageFromVulkanContext(
                        *gpu_, targets.scene_depth_gl_handle);
        }

        auto& gl_ctx = GaussianSplatOpenGLContext::GetInstance();
        if (!gl_ctx.IsValid() || !gl_ctx.MakeCurrent()) {
            utility::LogWarning(
                    "GaussianSplatVulkan: MakeCurrent failed in "
                    "ReleaseOutputTextures — handles may leak");
            return;
        }

        if (targets.uses_vulkan_interop) {
            auto& vk_ctx = GaussianSplatVulkanInteropContext::GetInstance();
            if (targets.color_gl_handle != 0) {
                SharedImageDesc d;
                d.vk_image = reinterpret_cast<VkImage>(targets.color_vk_image);
                d.vk_memory = reinterpret_cast<VkDeviceMemory>(
                        targets.color_vk_memory);
                d.gl_memory_object = targets.color_gl_mem_obj;
                d.gl_texture = targets.color_gl_handle;
                vk_ctx.DestroySharedImage(d);
                targets.color_vk_image = 0;
                targets.color_vk_memory = 0;
                targets.color_gl_mem_obj = 0;
                targets.color_gl_handle = 0;
            }
            if (targets.scene_depth_gl_handle != 0) {
                SharedImageDesc d;
                d.vk_image = reinterpret_cast<VkImage>(targets.depth_vk_image);
                d.vk_memory = reinterpret_cast<VkDeviceMemory>(
                        targets.depth_vk_memory);
                d.gl_memory_object = targets.depth_gl_mem_obj;
                d.gl_texture = targets.scene_depth_gl_handle;
                vk_ctx.DestroySharedImage(d);
                targets.depth_vk_image = 0;
                targets.depth_vk_memory = 0;
                targets.depth_gl_mem_obj = 0;
                targets.scene_depth_gl_handle = 0;
            }
            targets.uses_vulkan_interop = false;
        }
        gl_ctx.ReleaseCurrent();
    }

ol RenderGeometryStage(
            const FilamentView& view,
            const FilamentScene& scene,
            const GaussianSplatRenderer::ViewRenderData& render_data,
            GaussianSplatRenderer::OutputTargets& targets) override {
        // Vulkan compute: no GL context needed for dispatch.
        if (!EnsureGpuContext()) return false;

        const GaussianSplatPackedAttrs* attrs =
                scene.GetGaussianSplatPackedAttrs();
        if (!attrs || attrs->splat_count == 0) return false;

        PackedGaussianScene frame =
                PackGaussianViewParams(*attrs, render_data, config_);
        if (!frame.valid) return false;

        auto& vs = view_states_[&view];
        const std::uint64_t scene_id = scene.GetGeometryChangeId();
        const bool scene_changed =
                (scene_id != vs.cached_scene_id ||
                 attrs->splat_count != vs.cached_splat_count);

        return RunGaussianGeometryPasses(*gpu_, config_, frame, *attrs, vs,
                                         scene_id, scene_changed);
    }

ol RenderCompositeStage(
            const FilamentView& view,
            const GaussianSplatRenderer::ViewRenderData&,
            GaussianSplatRenderer::OutputTargets& targets) override {
        if (!gpu_) return false;
        auto it = view_states_.find(&view);
        if (it == view_states_.end() || it->second.view_params_buf == 0) {
            return false;
        }
        return RunGaussianCompositePass(*gpu_, config_, it->second, targets);
    }

ol ReadMergedDepthToUint16Cpu(const FilamentView& view,
                                    std::vector<std::uint16_t>& out,
                                    std::uint32_t width,
                                    std::uint32_t height) override {
        auto it = view_states_.find(&view);
        if (it == view_states_.end() || it->second.merged_depth_u16_tex == 0)
            return false;
        if (!gpu_) return false;
        return gpu_->DownloadTextureR16UI(it->second.merged_depth_u16_tex,
                                          width, height, out);
    }

ol ReadCompositeDepthToFloatCpu(const FilamentView& view,
                                      std::vector<float>& out,
                                      std::uint32_t width,
                                      std::uint32_t height) override {
        auto it = view_states_.find(&view);
        if (it == view_states_.end() || it->second.composite_depth_tex == 0)
            return false;
        if (!gpu_) return false;
        return gpu_->DownloadTextureR32F(it->second.composite_depth_tex, width,
                                         height, out);
    }

ol EnsureGpuContext() {
        if (gpu_) return gpu_->EnsureProgramsLoaded();
        gpu_ = CreateComputeGpuContextVulkan();
        if (!gpu_) return false;
        return gpu_->EnsureProgramsLoaded();
    }

id DestroyViewState(GaussianSplatViewGpuResources& vs) {
        if (!gpu_) return;
        auto destroy_buf = [&](std::uintptr_t& b) {
            if (b != 0) {
                gpu_->DestroyBuffer(b);
                b = 0;
            }
        };
        destroy_buf(vs.view_params_buf);
        destroy_buf(vs.positions_buf);
        destroy_buf(vs.scales_buf);
        destroy_buf(vs.rotations_buf);
        destroy_buf(vs.dc_opacity_buf);
        destroy_buf(vs.sh_buf);
        destroy_buf(vs.projected_composite_buf);
        destroy_buf(vs.tile_counts_buf);  // steal_counter
        destroy_buf(vs.counters_buf);
        destroy_buf(vs.dispatch_args_buf);
        destroy_buf(vs.sort_keys_buf[0]);
        destroy_buf(vs.sort_keys_buf[1]);
        destroy_buf(vs.sort_values_buf[0]);
        destroy_buf(vs.sort_values_buf[1]);
        destroy_buf(vs.histogram_buf);
        destroy_buf(vs.radix_params_buf);
        destroy_buf(vs.mask_buf);
        if (vs.composite_depth_tex != 0) {
            gpu_->DestroyTexture(vs.composite_depth_tex);
            vs.composite_depth_tex = 0;
        }
        if (vs.merged_depth_u16_tex != 0) {
            gpu_->DestroyTexture(vs.merged_depth_u16_tex);
            vs.merged_depth_u16_tex = 0;
        }
    }
}

d::unique_ptr<GaussianSplatRenderer::Backend>
CreateGaussianSplatVulkanBackend(
        FilamentResourceManager& /*resource_mgr*/,
        const GaussianSplatRenderer::RenderConfig& config) {
    auto& interop = GaussianSplatVulkanInteropContext::GetInstance();
    if (!interop.IsValid()) {
        utility::LogDebug(
                "GaussianSplatVulkan: interop context not valid; Vulkan "
                "backend not available");
        return nullptr;
    }
    return std::make_unique<GaussianSplatVulkanBackend>(config);
}

ShouldEnableDebugUtils() {
    const char* value = std::getenv("OPEN3D_VULKAN_DEBUG_UTILS");
    return value != nullptr && value[0] != '\0' && std::strcmp(value, "0") != 0;
}

//

CheckExtensions(const std::vector<vk::ExtensionProperties>& available,
                     const char* const* required,
                     std::size_t required_count,
                     std::string& out_missing) {
    for (std::size_t i = 0; i < required_count; ++i) {
        bool found = false;
        for (const auto& ext : available) {
            if (std::strcmp(ext.extensionName, required[i]) == 0) {
                found = true;
                break;
            }
        }
        if (!found) {
            out_missing = required[i];
            return false;
        }
    }
    return true;
}

//

eDevice(const vk::raii::PhysicalDevice& dev) {
    // Check for a compute queue.
    const auto qfams = dev.getQueueFamilyProperties();
    bool has_compute = false;
    for (const auto& qf : qfams) {
        if (qf.queueFlags & vk::QueueFlagBits::eCompute) {
            has_compute = true;
            break;
        }
    }
    if (!has_compute) return -1;

    // Check device extensions.
    const auto exts = dev.enumerateDeviceExtensionProperties();

    std::string missing;
    const bool ok =
            CheckExtensions(exts, kRequiredDeviceExtensions,
                            std::size(kRequiredDeviceExtensions), missing);
    if (!ok) return -1;

    // Shaders are compiled for Vulkan 1.3 (SPIR-V 1.6); reject older devices.
    const auto props = dev.getProperties();
    if (props.apiVersion < VK_API_VERSION_1_3) return -1;

    // Score device type.
    if (props.deviceType == vk::PhysicalDeviceType::eDiscreteGpu) return 2;
    if (props.deviceType == vk::PhysicalDeviceType::eIntegratedGpu) return 1;
    return 0;
}

}  //

SplatVulkanInteropContext&
GaussianSplatVulkanInteropContext::GetInstance() {
    static GaussianSplatVulkanInteropContext instance;
    return instance;
}

Gaussi

SplatVulkanInteropContext::~GaussianSplatVulkanInteropContext() {
    Shutdown();
}

// ---

ssianSplatVulkanInteropContext::Initialize() {
    if (initialized_) return true;

    // Initialize the global dynamic dispatcher with vkGetInstanceProcAddr
    // obtained from the Vulkan loader via vulkan-hpp's DynamicLoader utility.
    // This loads instance-independent entry points (e.g. vkCreateInstance).
    try {
        VULKAN_HPP_DEFAULT_DISPATCHER.init(
                vk::detail::DynamicLoader()
                        .getProcAddress<PFN_vkGetInstanceProcAddr>(
                                "vkGetInstanceProcAddr"));
    } catch (const std::exception& e) {
        last_error_ = std::string("Vulkan loader not found: ") + e.what();
        utility::LogWarning("GaussianSplat Vulkan: {}", last_error_);
        return false;
    }

    if (!CreateInstance()) return false;

    // After instance creation, update the dispatcher with instance-level
    // function pointers (required for physical device enumeration etc.).
    VULKAN_HPP_DEFAULT_DISPATCHER.init(static_cast<vk::Instance>(*instance_));

    if (!SelectPhysicalDevice()) return false;
    if (!CreateLogicalDevice()) return false;

    // After device creation, update the dispatcher with device-level
    // function pointers for push descriptors and other extensions.
    VULKAN_HPP_DEFAULT_DISPATCHER.init(static_cast<vk::Device>(*device_));

    initialized_ = true;
    utility::LogDebug("GaussianSplat VulkanInteropContext: initialized ({})",
                      physical_device_.getProperties().deviceName.data());
    return true;
}

void G

ssianSplatVulkanInteropContext::Shutdown() {
    if (!initialized_) return;

    // Wait for idle before releasing sub-objects.  The raw VkDevice is
    // extracted before the raii handle is reset so the call is valid.
    if (*device_) {
        try {
            device_.waitIdle();
        } catch (const vk::SystemError& e) {
            utility::LogWarning(
                    "GaussianSplat VulkanInteropContext: waitIdle during "
                    "shutdown failed: {}",
                    e.what());
        }
    }

    // Resetting in reverse construction order: queue → device → physical →
    // instance → context. vk::raii handles call vkDestroy* in their dtors.
    compute_queue_ = vk::raii::Queue{nullptr};
    device_ = vk::raii::Device{nullptr};
    physical_device_ = vk::raii::PhysicalDevice{nullptr};
    instance_ = vk::raii::Instance{nullptr};
    // context_ is a value member; its dtor unloads the Vulkan loader.

    compute_queue_family_ = UINT32_MAX;
    initialized_ = false;
    gl_extensions_ok_ = false;
    utility::LogDebug("GaussianSplat VulkanInteropContext: shutdown");
}

// -----------

atVulkanInteropContext::ProbeGLExtensions() {
    // All required GL interop extension entry points are loaded by GLEW
    // after glewInit(). GLEW_GET_FUN returns nullptr for absent extensions.
    struct GLExtEntry {
        const char* name;
        bool present;
    } entries[] = {
            {"GL_EXT_memory_object", GLEW_EXT_memory_object != 0},
#if defined(_WIN32)
            {"GL_EXT_memory_object_win32", GLEW_EXT_memory_object_win32 != 0},
#else
            {"GL_EXT_memory_object_fd", GLEW_EXT_memory_object_fd != 0},
#endif
    };

    for (const auto& e : entries) {
        if (!e.present) {
            last_error_ = std::string("Missing GL extension: ") + e.name;
            utility::LogWarning("GaussianSplat Vulkan interop: {}",
                                last_error_);
            return false;
        }
    }
    gl_extensions_ok_ = true;
    utility::LogDebug(
            "GaussianSplat Vulkan interop: all GL extensions present");
    return true;
}

// -----------

atVulkanInteropContext::CreateInstance() {
    // Query instance extensions so we can enable VK_EXT_debug_utils only when
    // explicitly requested for validation/profiling runs.
    const auto available_exts = context_.enumerateInstanceExtensionProperties();

    std::vector<const char*> extensions;
    if (ShouldEnableDebugUtils()) {
        for (const auto& ext : available_exts) {
            if (std::strcmp(ext.extensionName,
                            VK_EXT_DEBUG_UTILS_EXTENSION_NAME) == 0) {
                extensions.push_back(VK_EXT_DEBUG_UTILS_EXTENSION_NAME);
                debug_utils_enabled_ = true;
                break;
            }
        }
    }

    // Shaders are compiled for --target-env vulkan1.3 (SPIR-V 1.6).
    // The instance must advertise 1.3 or vkCreateShaderModule rejects them.
    vk::ApplicationInfo app_info{
            "Open3D GaussianSplat",  // pApplicationName
            1,                       // applicationVersion
            nullptr,                 // pEngineName
            0,                       // engineVersion
            VK_API_VERSION_1_3,      // apiVersion
    };
    vk::InstanceCreateInfo ci({}, &app_info, {}, extensions);

    try {
        instance_ = context_.createInstance(ci);
    } catch (const vk::SystemError& e) {
        last_error_ = std::string("vkCreateInstance failed: ") + e.what();
        utility::LogWarning("GaussianSplat Vulkan: {}", last_error_);
        return false;
    }
    return true;
}

// -----------

atVulkanInteropContext::SelectPhysicalDevice() {
    auto devices = instance_.enumeratePhysicalDevices();
    if (devices.empty()) {
        last_error_ = "No Vulkan-capable devices found";
        utility::LogWarning("GaussianSplat Vulkan: {}", last_error_);
        return false;
    }

    int best_score = -1;
    std::size_t best_idx = devices.size();
    for (std::size_t i = 0; i < devices.size(); ++i) {
        const int score = ScoreDevice(devices[i]);
        if (score > best_score) {
            best_score = score;
            best_idx = i;
        }
    }

    if (best_idx == devices.size()) {
        last_error_ =
                "No suitable Vulkan device found with required interop "
                "extensions. Required "
                "extensions: " VK_KHR_EXTERNAL_MEMORY_FD_EXTENSION_NAME;
        utility::LogWarning("GaussianSplat Vulkan: {}", last_error_);
        return false;
    }
    physical_device_ = std::move(devices[best_idx]);

    const auto props = physical_device_.getProperties();
    memory_props_ = static_cast<VkPhysicalDeviceMemoryProperties>(
            physical_device_.getMemoryProperties());
    utility::LogDebug("GaussianSplat Vulkan: selected device '{}'",
                      props.deviceName.data());
    return true;
}

// -----------

atVulkanInteropContext::CreateLogicalDevice() {
    const auto qfams = physical_device_.getQueueFamilyProperties();

    // Prefer a queue family that supports both GRAPHICS and COMPUTE — the
    // same hardware engine (RCS on Intel, GFX on AMD) as the OpenGL context.
    // Dedicated compute-only queues (CCS on Intel) can behave differently for
    // the same SPIR-V shaders and may hang on some driver/hardware combos.
    // Fall back to a compute-only queue only when no graphics+compute family
    // exists.
    std::uint32_t graphics_compute_family = UINT32_MAX;
    std::uint32_t compute_only_family = UINT32_MAX;
    for (std::uint32_t i = 0; i < static_cast<std::uint32_t>(qfams.size());
         ++i) {
        const auto flags = qfams[i].queueFlags;
        if ((flags & vk::QueueFlagBits::eCompute) &&
            (flags & vk::QueueFlagBits::eGraphics)) {
            if (graphics_compute_family == UINT32_MAX)
                graphics_compute_family = i;
        } else if ((flags & vk::QueueFlagBits::eCompute) &&
                   compute_only_family == UINT32_MAX) {
            compute_only_family = i;
        }
    }
    compute_queue_family_ = (graphics_compute_family != UINT32_MAX)
                                    ? graphics_compute_family
                                    : compute_only_family;
    if (compute_queue_family_ == UINT32_MAX) {
        last_error_ = "No compute queue family found";
        utility::LogWarning("GaussianSplat Vulkan: {}", last_error_);
        return false;
    }

    const float queue_priority = 1.0f;
    vk::DeviceQueueCreateInfo qci({}, compute_queue_family_, 1,
                                  &queue_priority);

    // Request only the Vulkan 1.3 features this backend actually uses.
    // The command path relies on vkQueueSubmit2 / vkCmdPipelineBarrier2, so
    // synchronization2 must be enabled. Subgroup variants are selected from
    // properties and supported-operation bits only.
    auto supported_features =
            physical_device_.getFeatures2<vk::PhysicalDeviceFeatures2,
                                          vk::PhysicalDeviceVulkan13Features>();
    const auto& supported_vulkan13 =
            supported_features.get<vk::PhysicalDeviceVulkan13Features>();
    if (supported_vulkan13.synchronization2 != VK_TRUE) {
        last_error_ =
                "Selected Vulkan device does not support synchronization2";
        utility::LogWarning("GaussianSplat Vulkan: {}", last_error_);
        return false;
    }

    vk::StructureChain<vk::PhysicalDeviceFeatures2,
                       vk::PhysicalDeviceVulkan13Features>
            enabled_features;
    enabled_features.get<vk::PhysicalDeviceVulkan13Features>()
            .synchronization2 = VK_TRUE;

    vk::DeviceCreateInfo dci({}, qci, {}, kRequiredDeviceExtensions);
    dci.pNext = &enabled_features.get<vk::PhysicalDeviceFeatures2>();

    try {
        device_ = physical_device_.createDevice(dci);
    } catch (const vk::SystemError& e) {
        last_error_ = std::string("vkCreateDevice failed: ") + e.what();
        utility::LogWarning("GaussianSplat Vulkan: {}", last_error_);
        return false;
    }
    compute_queue_ = device_.getQueue(compute_queue_family_, 0);

    // Query the hardware subgroup size so callers can skip _subgroup shader
    // variants when the device subgroup size is too small (e.g. Intel Xe2=8).
    auto props11 =
            physical_device_
                    .getProperties2<vk::PhysicalDeviceProperties2,
                                    vk::PhysicalDeviceVulkan11Properties>();
    const auto& subgroup_props =
            props11.get<vk::PhysicalDeviceVulkan11Properties>();
    subgroup_size_ = subgroup_props.subgroupSize;
    subgroup_supported_stages_ =
            static_cast<std::uint32_t>(subgroup_props.subgroupSupportedStages);
    subgroup_supported_operations_ = static_cast<std::uint32_t>(
            subgroup_props.subgroupSupportedOperations);

    utility::LogDebug(
            "GaussianSplat Vulkan: compute queue family {}, "
            "subgroupSize={}, subgroupStages=0x{:x}, "
            "subgroupOps=0x{:x}, synchronization2={}",
            compute_queue_family_, subgroup_size_, subgroup_supported_stages_,
            subgroup_supported_operations_,
            supported_vulkan13.synchronization2 == VK_TRUE);
    return true;
}

// -------------

sianSplatVulkanInteropContext::FindMemoryType(
        std::uint32_t type_filter, VkMemoryPropertyFlags props) const {
    for (std::uint32_t i = 0; i < memory_props_.memoryTypeCount; ++i) {
        if ((type_filter & (1u << i)) &&
            (memory_props_.memoryTypes[i].propertyFlags & props) == props) {
            return i;
        }
    }
    return UINT32_MAX;
}

// -------------

VulkanInteropContext::AllocateExportableImage(
        std::uint32_t width,
        std::uint32_t height,
        VkFormat vk_format,
        VkImageUsageFlags usage,
        VkImage& out_image,
        VkDeviceMemory& out_memory,
        int& out_fd) const {
    const vk::Format format = static_cast<vk::Format>(vk_format);
    const vk::ImageUsageFlags vk_usage =
            static_cast<vk::ImageUsageFlags>(usage);

#if defined(_WIN32)
    constexpr vk::ExternalMemoryHandleTypeFlagBits kHandleType =
            vk::ExternalMemoryHandleTypeFlagBits::eOpaqueWin32;
#else
    constexpr vk::ExternalMemoryHandleTypeFlagBits kHandleType =
            vk::ExternalMemoryHandleTypeFlagBits::eOpaqueFd;
#endif

    // Chain external-memory info into the image create info.
    vk::StructureChain<vk::ImageCreateInfo, vk::ExternalMemoryImageCreateInfo>
            img_chain{
                    vk::ImageCreateInfo{
                            {},
                            vk::ImageType::e2D,
                            format,
                            {width, height, 1},
                            1,
                            1,
                            vk::SampleCountFlagBits::e1,
                            vk::ImageTiling::eOptimal,
                            vk_usage,
                            vk::SharingMode::eExclusive,
                            {},
                            vk::ImageLayout::eUndefined,
                    },
                    vk::ExternalMemoryImageCreateInfo{kHandleType},
            };

    // Use the non-RAII vk::Device wrapper: AllocateExportableImage manages raw
    // VkImage/VkDeviceMemory lifetimes explicitly (exported to GL via FD).
    const vk::Device dev(*device_);

    vk::Image image;
    try {
        image = dev.createImage(img_chain.get<vk::ImageCreateInfo>());
    } catch (const vk::SystemError& e) {
        utility::LogWarning("GaussianSplat Vulkan: vkCreateImage failed: {}",
                            e.what());
        return false;
    }

    const vk::MemoryRequirements mem_req =
            dev.getImageMemoryRequirements(image);
    const std::uint32_t mem_type =
            FindMemoryType(mem_req.memoryTypeBits,
                           static_cast<VkMemoryPropertyFlags>(
                                   vk::MemoryPropertyFlagBits::eDeviceLocal));
    if (mem_type == UINT32_MAX) {
        utility::LogWarning(
                "GaussianSplat Vulkan: no suitable device-local memory type");
        dev.destroyImage(image);
        return false;
    }

    // Chain dedicated-alloc and export-alloc info into vk::MemoryAllocateInfo.
    vk::StructureChain<vk::MemoryAllocateInfo, vk::ExportMemoryAllocateInfo,
                       vk::MemoryDedicatedAllocateInfo>
            mem_chain{
                    vk::MemoryAllocateInfo{mem_req.size, mem_type},
                    vk::ExportMemoryAllocateInfo{kHandleType},
                    vk::MemoryDedicatedAllocateInfo{image},
            };

    vk::DeviceMemory memory;
    try {
        memory = dev.allocateMemory(mem_chain.get<vk::MemoryAllocateInfo>());
    } catch (const vk::SystemError& e) {
        utility::LogWarning("GaussianSplat Vulkan: vkAllocateMemory failed: {}",
                            e.what());
        dev.destroyImage(image);
        return false;
    }

    try {
        (void)dev.bindImageMemory(image, memory, 0);
    } catch (const vk::SystemError& e) {
        utility::LogWarning(
                "GaussianSplat Vulkan: vkBindImageMemory failed: {}", e.what());
        dev.freeMemory(memory);
        dev.destroyImage(image);
        return false;
    }

    // Export the memory as a platform handle.
#if defined(_WIN32)
    HANDLE win32_handle = nullptr;
    try {
        win32_handle = dev.getMemoryWin32HandleKHR(
                {memory, vk::ExternalMemoryHandleTypeFlagBits::eOpaqueWin32});
    } catch (const vk::SystemError& e) {
        utility::LogWarning(
                "GaussianSplat Vulkan: vkGetMemoryWin32HandleKHR failed: {}",
                e.what());
        dev.freeMemory(memory);
        dev.destroyImage(image);
        return false;
    }
    out_fd = static_cast<int>(reinterpret_cast<intptr_t>(win32_handle));
    // NOTE: on Windows, HANDLE values are not real file descriptors and should
    // be closed with CloseHandle() after being imported into GL. However, the
    // current design passes them as int (out_fd) to ImportFDIntoGL, which will
    // pass them to glImportMemoryWin32HandleEXT. GL takes ownership of the
    // HANDLE import, so we cannot close it here. The HANDLE lifetime is managed
    // by GL and Vulkan.
#else
    try {
        out_fd = dev.getMemoryFdKHR(
                {memory, vk::ExternalMemoryHandleTypeFlagBits::eOpaqueFd});
    } catch (const vk::SystemError& e) {
        utility::LogWarning("GaussianSplat Vulkan: vkGetMemoryFdKHR failed: {}",
                            e.what());
        dev.freeMemory(memory);
        dev.destroyImage(image);
        return false;
    }
#endif

    out_image = static_cast<VkImage>(image);
    out_memory = static_cast<VkDeviceMemory>(memory);
    return true;
}

bool GaussianSpl

VulkanInteropContext::ImportFDIntoGL(
        int fd,
        std::uint32_t width,
        std::uint32_t height,
        VkDeviceSize memory_size,
        VkInteropImageFormat format,
        std::uint32_t& out_gl_memory_object,
        std::uint32_t& out_gl_texture) const {
    // Create a GL memory object and import the Vulkan FD into it.
    glCreateMemoryObjectsEXT(1, &out_gl_memory_object);
    if (out_gl_memory_object == 0) {
        utility::LogWarning(
                "GaussianSplat GL: glCreateMemoryObjectsEXT returned 0");
        return false;
    }

#if defined(_WIN32)
    const HANDLE win32_handle =
            reinterpret_cast<HANDLE>(static_cast<intptr_t>(fd));
    glImportMemoryWin32HandleEXT(out_gl_memory_object,
                                 static_cast<GLuint64>(memory_size),
                                 GL_HANDLE_TYPE_OPAQUE_WIN32_EXT, win32_handle);
    // IMPORTANT: On Windows, vkGetMemoryWin32HandleKHR() returns a new HANDLE
    // that we own. glImportMemoryWin32HandleEXT() makes a copy internally. We
    // must close the returned HANDLE to avoid kernel handle resource leaks.
    CloseHandle(win32_handle);
#else
    glImportMemoryFdEXT(out_gl_memory_object,
                        static_cast<GLuint64>(memory_size),
                        GL_HANDLE_TYPE_OPAQUE_FD_EXT, fd);
    // FD ownership is transferred to GL; do not close it.
#endif

    // Create a GL texture backed by the imported memory object.
    glCreateTextures(GL_TEXTURE_2D, 1, &out_gl_texture);
    if (out_gl_texture == 0) {
        glDeleteMemoryObjectsEXT(1, &out_gl_memory_object);
        out_gl_memory_object = 0;
        utility::LogWarning("GaussianSplat GL: glCreateTextures returned 0");
        return false;
    }

    // Allocate GL texture storage bound to the imported memory.
    GLenum gl_internal_format = 0;
    switch (format) {
        case VkInteropImageFormat::kRGBA16F:
            gl_internal_format = GL_RGBA16F;
            break;
        case VkInteropImageFormat::kDepth32F:
            gl_internal_format = GL_DEPTH_COMPONENT32F;
            break;
    }
    glTextureStorageMem2DEXT(
            out_gl_texture, 1, gl_internal_format, static_cast<GLsizei>(width),
            static_cast<GLsizei>(height), out_gl_memory_object, /*offset=*/0);

    const GLenum err = glGetError();
    if (err != GL_NO_ERROR) {
        utility::LogWarning(
                "GaussianSplat GL: glTextureStorageMem2DEXT error 0x{:x}",
                static_cast<unsigned>(err));
        glDeleteTextures(1, &out_gl_texture);
        glDeleteMemoryObjectsEXT(1, &out_gl_memory_object);
        out_gl_texture = 0;
        out_gl_memory_object = 0;
        return false;
    }
    return true;
}

SharedImageDesc

ussianSplatVulkanInteropContext::CreateSharedImage(
        std::uint32_t width,
        std::uint32_t height,
        VkInteropImageFormat interop_format,
        const char* label) {
    SharedImageDesc desc{};
    if (!initialized_ || !gl_extensions_ok_) {
        utility::LogWarning(
                "GaussianSplat Vulkan: CreateSharedImage called before "
                "Initialize()+ProbeGLExtensions()");
        return desc;
    }

    VkFormat vk_fmt = VK_FORMAT_UNDEFINED;
    VkImageUsageFlags usage = 0;
    switch (interop_format) {
        case VkInteropImageFormat::kRGBA16F:
            vk_fmt = VK_FORMAT_R16G16B16A16_SFLOAT;
            // STORAGE for compute write; SAMPLED for Filament/UI read;
            // COLOR_ATTACHMENT: required for Filament COLOR_ATTACHMENT usage.
            usage = VK_IMAGE_USAGE_STORAGE_BIT | VK_IMAGE_USAGE_SAMPLED_BIT |
                    VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT |
                    VK_IMAGE_USAGE_TRANSFER_SRC_BIT;
            break;
        case VkInteropImageFormat::kDepth32F:
            vk_fmt = VK_FORMAT_D32_SFLOAT;
            // DEPTH_STENCIL_ATTACHMENT: Filament writes depth into it.
            // SAMPLED: Vulkan composite pass samples it for occlusion.
            usage = VK_IMAGE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT |
                    VK_IMAGE_USAGE_SAMPLED_BIT;
            break;
    }

    int export_fd = -1;
    {
        // Probe memory requirements using a temporary image (no exportable
        // memory yet) to determine the actual allocation size for GL import.
        vk::ImageCreateInfo probe_ci{{},
                                     vk::ImageType::e2D,
                                     static_cast<vk::Format>(vk_fmt),
                                     {width, height, 1},
                                     1,
                                     1,
                                     vk::SampleCountFlagBits::e1,
                                     vk::ImageTiling::eOptimal,
                                     static_cast<vk::ImageUsageFlags>(usage)};
        try {
            vk::Image probe_img = vk::Device(*device_).createImage(probe_ci);
            vk::Device(*device_).destroyImage(probe_img);
        } catch (...) {
            // Ignore probe failures; AllocateExportableImage will report.
        }
    }

    bool ok = AllocateExportableImage(width, height, vk_fmt, usage,
                                      desc.vk_image, desc.vk_memory, export_fd);
    if (!ok) return desc;

    // Query actual memory size for the GL import call.
    const vk::MemoryRequirements actual_req =
            vk::Device(*device_).getImageMemoryRequirements(
                    static_cast<vk::Image>(desc.vk_image));

    ok = ImportFDIntoGL(export_fd, width, height,
                        static_cast<VkDeviceSize>(actual_req.size),
                        interop_format, desc.gl_memory_object, desc.gl_texture);
    if (!ok) {
        vk::Device(*device_).freeMemory(
                static_cast<vk::DeviceMemory>(desc.vk_memory));
        vk::Device(*device_).destroyImage(
                static_cast<vk::Image>(desc.vk_image));
        desc = SharedImageDesc{};
        return desc;
    }

    desc.width = width;
    desc.height = height;
    desc.format = interop_format;
    desc.current_layout = VK_IMAGE_LAYOUT_UNDEFINED;

    if (label) {
        utility::LogDebug(
                "GaussianSplat Vulkan: created shared image '{}' "
                "{}x{} GL={}",
                label, width, height, desc.gl_texture);
    }
    return desc;
}

SharedImageDesc

ussianSplatVulkanInteropContext::CreateSharedColorImage(
        std::uint32_t width, std::uint32_t height, const char* label) {
    return CreateSharedImage(width, height, VkInteropImageFormat::kRGBA16F,
                             label);
}

SharedImageDesc

ussianSplatVulkanInteropContext::CreateSharedDepthImage(
        std::uint32_t width, std::uint32_t height, const char* label) {
    return CreateSharedImage(width, height, VkInteropImageFormat::kDepth32F,
                             label);
}

void GaussianSpl

VulkanInteropContext::DestroySharedImage(
        SharedImageDesc& desc) {
    if (!desc.IsValid()) return;

    // GL objects must be destroyed before the underlying Vulkan memory.
    if (desc.gl_texture != 0) {
        glDeleteTextures(1, &desc.gl_texture);
        desc.gl_texture = 0;
    }
    if (desc.gl_memory_object != 0) {
        glDeleteMemoryObjectsEXT(1, &desc.gl_memory_object);
        desc.gl_memory_object = 0;
    }
    // Now safe to free Vulkan resources.
    if (desc.vk_image != VK_NULL_HANDLE) {
        vk::Device(*device_).destroyImage(
                static_cast<vk::Image>(desc.vk_image));
        desc.vk_image = VK_NULL_HANDLE;
    }
    if (desc.vk_memory != VK_NULL_HANDLE) {
        vk::Device(*device_).freeMemory(
                static_cast<vk::DeviceMemory>(desc.vk_memory));
        desc.vk_memory = VK_NULL_HANDLE;
    }
    desc = SharedImageDesc{};
}

}  // namespace

void GuiVisualizer::SetGeometry(
        std::shared_ptr<const t::geometry::Geometry> geometry,
        bool loaded_model) {
    auto scene3d = impl_->scene_wgt_->GetScene();
    scene3d->ClearGeometry();

    impl_->SetMaterialsToDefault();

    rendering::MaterialRecord loaded_material;
    if (loaded_model) {
        scene3d->AddModel(MODEL_NAME, impl_->loaded_model_);
        impl_->settings_.model_.SetDisplayingPointClouds(false);
        loaded_material.shader = "defaultLit";
    } else {
        auto pcd = std::dynamic_pointer_cast<const t::geometry::PointCloud>(
                geometry);
        if (pcd) {
            if (pcd->IsGaussianSplat()) {
                loaded_material.shader = "gaussianSplat";
                loaded_material.gaussian_splat_sh_degree =
                        pcd->GaussianSplatGetSHOrder();
            } else if (pcd->HasPointNormals()) {
                loaded_material.shader = "defaultLit";
            } else if (pcd->HasPointColors()) {
                loaded_material.shader = "defaultUnlit";
            } else {
                loaded_material.shader = "defaultLit";
            }

            scene3d->AddGeometry(MODEL_NAME, pcd.get(), loaded_material);

            impl_->settings_.model_.SetDisplayingPointClouds(true);
            if (!impl_->settings_.model_.GetUserHasChangedLightingProfile()) {
                auto &profile =
                        GuiSettingsModel::GetDefaultPointCloudLightingProfile();
                impl_->settings_.model_.SetLightingProfile(profile);
            }
        }
    }

    auto type = impl_->settings_.model_.GetMaterialType();
    if (type == GuiSettingsModel::MaterialType::LIT ||
        type == GuiSettingsModel::MaterialType::UNLIT) {
        if (loaded_material.shader == "defaultUnlit") {
            impl_->settings_.model_.SetMaterialType(
                    GuiSettingsModel::MaterialType::UNLIT);
        } else {
            impl_->settings_.model_.SetMaterialType(
                    GuiSettingsModel::MaterialType::LIT);
        }
    }

    impl_->settings_.model_.UnsetCustomDefaultColor();
    if (loaded_model) {
        impl_->settings_.view_->ShowFileMaterialEntry(true);
        impl_->settings_.model_.SetCurrentMaterials(
                GuiSettingsModel::MATERIAL_FROM_FILE_NAME);
    } else {
        impl_->settings_.view_->ShowFileMaterialEntry(false);
    }
    impl_->settings_.view_->Update();

    const auto bounds = scene3d->GetBoundingBox();
    impl_->scene_wgt_->SetupCamera(60.0, bounds,
                                   bounds.GetCenter().cast<float>());

    if (impl_->basic_mode_enabled_) {
        impl_->SetBasicModeGeometry(true);
        scene3d->GetScene()->SetSunLightDirection(
                scene3d->GetCamera()->GetForwardVector());
    }

    impl_->scene_wgt_->ForceRedraw();
}

void CopyViewToClipboard() {
        auto *camera = scene_->GetScene()->GetCamera();
        Eigen::Vector3d lookat = scene_->GetCenterOfRotation().cast<double>();
        Eigen::Vector3d eye = camera->GetPosition().cast<double>();
        Eigen::Vector3d up = camera->GetUpVector().cast<double>();

        Json::Value result;
        utility::IJsonConvertible::EigenVector3dToJsonArray(lookat,
                                                            result["lookat"]);
        utility::IJsonConvertible::EigenVector3dToJsonArray(eye, result["eye"]);
        utility::IJsonConvertible::EigenVector3dToJsonArray(up, result["up"]);
        result["field_of_view"] = camera->GetFieldOfView();
        result["near_plane"] = camera->GetNear();
        result["far_plane"] = camera->GetFar();
        auto frame = scene_->GetFrame();
        result["width"] = frame.width;
        result["height"] = frame.height;

        window_->SetClipboardText(utility::JsonToString(result));
        utility::LogInfo("View parameters copied to clipboard.");
    }

void ExportCurrentDepthImage(const std::string &path) {
        scene_->EnableSceneCaching(false);
        scene_->GetScene()->GetScene()->RenderToDepthImage(
                [this, path](std::shared_ptr<geometry::Image> image) mutable {
                    bool ok = false;
                    if (image && image->num_of_channels_ == 1 &&
                        image->bytes_per_channel_ == 4) {
                        // Depth export stores normalized depth in 16-bit PNG.
                        auto depth_float =
                                std::make_shared<geometry::Image>(*image);
                        float *depth_data = depth_float->PointerAs<float>();
                        size_t num_pixels = static_cast<size_t>(
                                depth_float->GetMaxBound().prod());
                        float max_val =
                                std::reduce(depth_data, depth_data + num_pixels,
                                            0.0f, [](float a, float b) {
                                                if (!std::isfinite(a)) return b;
                                                if (!std::isfinite(b)) return a;
                                                return std::max(a, b);
                                            });
                        if (max_val > 0)
                            depth_float->LinearTransform(65535.0 / max_val,
                                                         0.0);
                        auto depth_u16 =
                                depth_float
                                        ->CreateImageFromFloatImage<uint16_t>();
                        ok = io::WriteImage(path, *depth_u16);
                    }
                    if (!ok) {
                        this->window_->ShowMessageBox(
                                "Error",
                                (std::string(
                                         "Could not write depth image to ") +
                                 path + ".")
                                        .c_str());
                    }
                    scene_->EnableSceneCaching(true);
                });
    }

void OnExportDepth() {
        auto dlg = std::make_shared<gui::FileDialog>(
                gui::FileDialog::Mode::SAVE, "Save Depth File",
                window_->GetTheme());
        dlg->AddFilter(".png", "PNG images (.png)");
        dlg->AddFilter("", "All files");
        dlg->SetOnCancel([this]() { this->window_->CloseDialog(); });
        dlg->SetOnDone([this](const char *path) {
            this->window_->CloseDialog();
            this->ExportCurrentDepthImage(path);
        });
        window_->ShowDialog(dlg);
    }

