TEST_F(utSIBImporter, UvPointCountExceedingFace) {
    // The face is built with a single point, but the UV ('FTVS') chunk claims the
    // face has two. ReadUVs() would then walk its index cursor past the end of the
    // per-face index data and off the end of mesh->idx, an out-of-bounds read. Such
    // a UV chunk must be rejected.
    static const unsigned char kSibData[] = {
        // 'SHAP' chunk, 0x44 bytes of payload
        0x53, 0x48, 0x41, 0x50, 0x44, 0x00, 0x00, 0x00,
        // 'VRTS' chunk: a single vertex at the origin
        0x56, 0x52, 0x54, 0x53, 0x0c, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        // 'FACS' chunk: one face with a single point, index 0
        0x46, 0x41, 0x43, 0x53, 0x08, 0x00, 0x00, 0x00,
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        // 'FTVS' chunk: UVs for face 0 claiming two points
        0x46, 0x54, 0x56, 0x53, 0x18, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x02, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x80, 0x3f, 0x00, 0x00, 0x80, 0x3f,
        0x00, 0x00, 0x80, 0x3f, 0x00, 0x00, 0x80, 0x3f
    };

    Importer importer;
    const aiScene *scene = importer.ReadFileFromMemory(kSibData, sizeof(kSibData), 0, "sib");
    EXPECT_EQ(nullptr, scene);
}

TEST_F(utGenBoundingBoxesProcess, ExecuteFarFromOriginTest) {
    // Coordinates beyond the former +/-999999 sentinel values, e.g. from projected
    // geographic coordinate systems, must still yield a tight bounding box.
    const ai_real kOffset = (ai_real)2600000;
    for (unsigned int i = 0; i < mMesh->mNumVertices; ++i) {
        mMesh->mVertices[i] = aiVector3D(kOffset + (ai_real)i, -(kOffset + (ai_real)i), kOffset + (ai_real)i);
    }

    mProcess->Execute(mScene);

    aiMesh *mesh = mScene->mMeshes[0];
    EXPECT_NE(nullptr, mesh);
    EXPECT_EQ(kOffset, mesh->mAABB.mMin.x);
    EXPECT_EQ(-(kOffset + 99), mesh->mAABB.mMin.y);
    EXPECT_EQ(kOffset, mesh->mAABB.mMin.z);

    EXPECT_EQ(kOffset + 99, mesh->mAABB.mMax.x);
    EXPECT_EQ(-kOffset, mesh->mAABB.mMax.y);
    EXPECT_EQ(kOffset + 99, mesh->mAABB.mMax.z);
}

TEST_F(utGenBoundingBoxesProcess, ExecuteEmptyMeshTest) {
    delete[] mMesh->mVertices;
    mMesh->mVertices = nullptr;
    mMesh->mNumVertices = 0;

    mProcess->Execute(mScene);

    aiMesh *mesh = mScene->mMeshes[0];
    EXPECT_NE(nullptr, mesh);
    EXPECT_EQ(0, mesh->mAABB.mMin.x);
    EXPECT_EQ(0, mesh->mAABB.mMin.y);
    EXPECT_EQ(0, mesh->mAABB.mMin.z);

    EXPECT_EQ(0, mesh->mAABB.mMax.x);
    EXPECT_EQ(0, mesh->mAABB.mMax.y);
    EXPECT_EQ(0, mesh->mAABB.mMax.z);
}

static void ResizeForIndex(std::vector<T> &container, unsigned int idx, unsigned int line) {
    // The index is parsed without an overflow check, and idx + 1 wraps around to zero
    // for the largest one, which would shrink the container instead of growing it.
    if (idx == std::numeric_limits<unsigned int>::max()) {
        MD5Parser::ReportError("Index out of range", line);
    }
    if (idx >= container.size()) {
        container.resize(static_cast<size_t>(idx) + 1);
    }
}

