TEST(Common, MaybeUnwrapOrReturn) {
  {
    auto func = [](Maybe<int> i) -> int {
      int& j = KJ_UNWRAP_OR_RETURN(i, -1);
      KJ_EXPECT(&j == &KJ_ASSERT_NONNULL(i));
      return j + 2;
    };

    KJ_EXPECT(func(123) == 125);
    KJ_EXPECT(func(kj::none) == -1);
  }

  {
    auto func = [&](Maybe<String> maybe) -> int {
      String str = KJ_UNWRAP_OR_RETURN(kj::mv(maybe), -1);
      return str.parseAs<int>();
    };

    KJ_EXPECT(func(kj::str("123")) == 123);
    KJ_EXPECT(func(kj::none) == -1);
  }

  // Test void return.
  {
    int val = 0;
    auto func = [&](Maybe<int> i) {
      val = KJ_UNWRAP_OR_RETURN(i);
    };

    func(123);
    KJ_EXPECT(val == 123);
    val = 321;
    func(kj::none);
    KJ_EXPECT(val == 321);
  }

  // Test KJ_UNWRAP_OR
  {
    bool wasNull = false;
    auto func = [&](Maybe<int> i) -> int {
      int& j = KJ_UNWRAP_OR(i, {
        wasNull = true;
        return -1;
      });
      KJ_EXPECT(&j == &KJ_ASSERT_NONNULL(i));
      return j + 2;
    };

    KJ_EXPECT(func(123) == 125);
    KJ_EXPECT(!wasNull);
    KJ_EXPECT(func(kj::none) == -1);
    KJ_EXPECT(wasNull);
  }

  {
    bool wasNull = false;
    auto func = [&](Maybe<String> maybe) -> int {
      String str = KJ_UNWRAP_OR(kj::mv(maybe), {
        wasNull = true;
        return -1;
      });
      return str.parseAs<int>();
    };

    KJ_EXPECT(func(kj::str("123")) == 123);
    KJ_EXPECT(!wasNull);
    KJ_EXPECT(func(kj::none) == -1);
    KJ_EXPECT(wasNull);
  }

  // Test void return.
  {
    int val = 0;
    auto func = [&](Maybe<int> i) {
      val = KJ_UNWRAP_OR(i, {
        return;
      });
    };

    func(123);
    KJ_EXPECT(val == 123);
    val = 321;
    func(kj::none);
    KJ_EXPECT(val == 321);
  }

}

kj::Promise<void> request(
        HttpMethod method, kj::StringPtr url, const HttpHeaders& headers,
        kj::AsyncInputStream& requestBody, Response& response) override {
      KJ_ASSERT(nextGate < gates.size(), "no gate available for incoming request");
      co_await gates[nextGate++];
      if (headers.isWebSocket()) {
        auto ws = response.acceptWebSocket(HttpHeaders(headerTable));
        // Send a message, then wait for the client to close.
        co_await ws->send("hello from server"_kj);
        co_await ws->receive();
      } else {
        auto body = kj::str("body:", url);
        auto stream = response.send(200, "OK", HttpHeaders(headerTable), body.size());
        co_await stream->write(body.asBytes());
        co_await requestBody.readAllBytes();
      }
    }

kj::Promise<void> connect(kj::StringPtr host,
                              const HttpHeaders& headers,
                              kj::AsyncIoStream& connection,
                              ConnectResponse& response,
                              kj::HttpConnectSettings settings) override {
      KJ_ASSERT(nextGate < gates.size(), "no gate available for incoming CONNECT");
      co_await gates[nextGate++];
      response.accept(200, "OK", HttpHeaders(headerTable));
      co_await connection.pumpTo(connection);
    }

kj::Promise<void> request(
        HttpMethod method, kj::StringPtr url, const HttpHeaders& headers,
        kj::AsyncInputStream& requestBody, Response& response) override {
      if (headers.isWebSocket()) {
        auto ws = response.acceptWebSocket(HttpHeaders(headerTable));
        co_await ws->receive();
      } else {
        auto body = "ok"_kjb;
        auto stream = response.send(200, "OK", HttpHeaders(headerTable), body.size());
        co_await stream->write(body);
        co_await requestBody.readAllBytes();
      }
    }

kj::Promise<void> connect(kj::StringPtr host,
                              const HttpHeaders& headers,
                              kj::AsyncIoStream& connection,
                              ConnectResponse& response,
                              kj::HttpConnectSettings settings) override {
      response.accept(200, "OK", HttpHeaders(headerTable));
      co_await connection.pumpTo(connection);
    }

static kj::Promise<Response> releaseCounterOnHeaders(
      kj::Promise<Response>&& promise,
      ConnectionCounter&& counter) {
    return promise.then([counter = kj::mv(counter)](Response&& response) mutable {
      // Counter destroyed here when lambda exits, releasing the slot
      return kj::mv(response);
    });
  }

static kj::Promise<WebSocketResponse> releaseCounterOnHeaders(
      kj::Promise<WebSocketResponse>&& promise,
      ConnectionCounter&& counter) {
    return promise.then([counter = kj::mv(counter)](WebSocketResponse&& response) mutable {
      // Counter destroyed here when lambda exits, releasing the slot
      return kj::mv(response);
    });
  }

static ConnectRequest releaseCounterOnHeaders(
      ConnectRequest&& request,
      ConnectionCounter&& counter) {
    // Release the slot when the status promise resolves (headers received)
    request.status = request.status.then(
        [counter = kj::mv(counter)](ConnectRequest::Status&& status) mutable {
      // Counter destroyed here when lambda exits, releasing the slot
      return kj::mv(status);
    });
    return kj::mv(request);
  }

CopyableNode(const CopyableNode& other): value(other.value) {
      KJ_IF_SOME(n, other.next) {
        next = heap<CopyableNode>(*n);
      }
    }

KJ_IF_SOME(node, head) {
    KJ_IF_SOME(nextNode, node.next) {
      head = *nextNode;  // Copy from *next into head
    }
  }

KJ_IF_SOME(node, head) {
    KJ_IF_SOME(next, node.next) {
      head = kj::mv(*next);  // operator=(T&&) where T is inside head's value
    }
  }

Node(const Node& other): value(other.value) {
      // Deep copy
      KJ_IF_SOME(n, other.next) {
        next = heap<Node>(*n);
      }
    }

KJ_IF_SOME(node, head) {
    KJ_IF_SOME(next, node.next) {
      head = *next;  // operator=(const T&) where T is inside head's value
    }
  }

NoneDestructorCounter& operator=(NoneDestructorCounter&& other) {
    value = other.value;
    other.value = -1;  // moved-from state, NOT none
    return *this;
  }

~NoneDestructorCounter() {
    if (value == 0) {
      ++noneDestroyCount;  // This should never happen!
    } else {
      ++nonNoneDestroyCount;
    }
  }

MoveOnlyNiche& operator=(MoveOnlyNiche&& other) {
    value = other.value;
    other.value = 0;
    return *this;
  }

NoneThrowingNiche(NoneThrowingNiche&& other): value(other.value) {
    if (other.value == 0) {
      throw std::logic_error("moved from none!");
    }
    other.value = -1;  // moved-from state, NOT none
  }

NoneThrowingNiche(const NoneThrowingNiche& other): value(other.value) {
    if (other.value == 0) {
      throw std::logic_error("copied from none!");
    }
  }

NoneThrowingNiche& operator=(NoneThrowingNiche&& other) {
    if (other.value == 0) {
      throw std::logic_error("move-assigned from none!");
    }
    value = other.value;
    other.value = -1;  // moved-from state, NOT none
    return *this;
  }

NoneThrowingNiche& operator=(const NoneThrowingNiche& other) {
    if (other.value == 0) {
      throw std::logic_error("copy-assigned from none!");
    }
    value = other.value;
    return *this;
  }

TestPtr& operator=(TestPtr&& other) {
    if (this != &other) {
      delete ptr;
      ptr = other.ptr;
      other.ptr = nullptr;
    }
    return *this;
  }

explicit ThrowingNiche(int v): value(v) {
    ++constructCount;
    if (throwOnConstruct && v != 0) {  // Don't throw for none value (v == 0)
      throw std::runtime_error("constructor throw");
    }
  }

ThrowingNiche(ThrowingNiche&& other): value(other.value), throwOnDestroy(other.throwOnDestroy) {
    // Set to moved-from state (-1), NOT to none state (0).
    // This means the moved-from object still needs destruction.
    other.value = -1;
    other.throwOnDestroy = false;
    ++constructCount;
    if (throwOnConstruct && value != 0) {
      throw std::runtime_error("move constructor throw");
    }
  }

~ThrowingNiche() noexcept(false) {
    ++destroyCount;
    if (throwOnDestroy) {
      throwOnDestroy = false;
      throw std::runtime_error("destructor throw");
    }
    if (throwOnMovedFromDestroy && value == -1) {
      throwOnMovedFromDestroy = false;  // Only throw once
      throw std::runtime_error("moved-from destructor throw");
    }
  }

KJ_IF_SOME(own, kj::mv(m)) {
      KJ_EXPECT(*own == 42);
      Own<int> taken = kj::mv(own);  // take ownership
      KJ_EXPECT(*taken == 42);
    }

TEST(Common, Maybe) {
  {
    Maybe<int> m = 123;
    EXPECT_FALSE(m == kj::none);
    EXPECT_TRUE(m != kj::none);
    KJ_IF_SOME(v, m) {
      EXPECT_EQ(123, v);
    } else {
      ADD_FAILURE();
    }
    KJ_IF_SOME(v, mv(m)) {
      EXPECT_EQ(123, v);
    } else {
      ADD_FAILURE();
    }

KJ_IF_SOME(v, m) {
      int notUsedForRef = 5;
      const int& ref = m.orDefault([&]() -> int& { return notUsedForRef; });

      EXPECT_EQ(ref, v);
      EXPECT_EQ(&ref, &v);

      const int& ref2 = m.orDefault([notUsed = 5]() -> int { return notUsed; });
      EXPECT_NE(&ref, &ref2);
      EXPECT_EQ(ref2, 123);
    }

TEST(Common, MaybeConstness) {
  int i;

  Maybe<int&> mi = i;
  const Maybe<int&> cmi = mi;
//  const Maybe<int&> cmi2 = cmi;    // shouldn't compile!  Transitive const violation.

  KJ_IF_SOME(i2, cmi) {
    EXPECT_EQ(&i, &i2);
  } else {
    ADD_FAILURE();
  }

TEST(Common, MaybeUnwrapOrReturn) {
  {
    auto func = [](Maybe<int> i) -> int {
      int& j = KJ_UNWRAP_OR_RETURN(i, -1);
      KJ_EXPECT(&j == &KJ_ASSERT_NONNULL(i));
      return j + 2;
    };

    KJ_EXPECT(func(123) == 125);
    KJ_EXPECT(func(kj::none) == -1);
  }

  {
    auto func = [&](Maybe<String> maybe) -> int {
      String str = KJ_UNWRAP_OR_RETURN(kj::mv(maybe), -1);
      return str.parseAs<int>();
    };

    KJ_EXPECT(func(kj::str("123")) == 123);
    KJ_EXPECT(func(kj::none) == -1);
  }

  // Test void return.
  {
    int val = 0;
    auto func = [&](Maybe<int> i) {
      val = KJ_UNWRAP_OR_RETURN(i);
    };

    func(123);
    KJ_EXPECT(val == 123);
    val = 321;
    func(kj::none);
    KJ_EXPECT(val == 321);
  }

  // Test KJ_UNWRAP_OR
  {
    bool wasNull = false;
    auto func = [&](Maybe<int> i) -> int {
      int& j = KJ_UNWRAP_OR(i, {
        wasNull = true;
        return -1;
      });
      KJ_EXPECT(&j == &KJ_ASSERT_NONNULL(i));
      return j + 2;
    };

    KJ_EXPECT(func(123) == 125);
    KJ_EXPECT(!wasNull);
    KJ_EXPECT(func(kj::none) == -1);
    KJ_EXPECT(wasNull);
  }

  {
    bool wasNull = false;
    auto func = [&](Maybe<String> maybe) -> int {
      String str = KJ_UNWRAP_OR(kj::mv(maybe), {
        wasNull = true;
        return -1;
      });
      return str.parseAs<int>();
    };

    KJ_EXPECT(func(kj::str("123")) == 123);
    KJ_EXPECT(!wasNull);
    KJ_EXPECT(func(kj::none) == -1);
    KJ_EXPECT(wasNull);
  }

  // Test void return.
  {
    int val = 0;
    auto func = [&](Maybe<int> i) {
      val = KJ_UNWRAP_OR(i, {
        return;
      });
    };

    func(123);
    KJ_EXPECT(val == 123);
    val = 321;
    func(kj::none);
    KJ_EXPECT(val == 321);
  }

}

